INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3392386, 'OT', 'Moze I', 1, 1, 'Ba mböröta ifazökhi Lowalangi mbanua si yaŵa, awö danö.[1]', '["Yob 38; Sin 33:6–9; 104; Yoh 1:3; Amaed 8:22–31"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 2, 'Ba no si fakuyu manö guli danö ba si lö ösi;[2] ba manaha-nahae Geheha Lowalangi yaŵa nidanö.', '["Fakuyu eluahania lö khala-khala ma zui lö boto, hulö gangowuloa zoya ngawalö si no oi faruka manö. Asese te''oguna''ö fakuyu na oi fatali mbana sanau, irege tebai la''adölö''ö ia sa''ae. Heŵa''ae simanö fehede ni''oguna''ö ba li Ibrani fabö''ö ma''ifu. Tenga si fakuyu ba si lö ösi gulidanö ba mböröta, ba hiza lö moboto ba lö ösi."]', NULL),
  (3392386, 'OT', 'Moze I', 1, 3, 'Ba imane Lowalangi: Yamohaga! Ba mohaga.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 4, 'Ba i''ila Lowalangi, wa no si sökhi haga andrö, ba iföfö''ö ira haga andrö sogömi-gömi Lowalangi.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 5, 'Ba ibe''e töi haga andrö zi ma''ökhö Lowalangi ba töi zogömi-gömi andrö ba si bongi ibe''e.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 6, 'Ba imane Lowalangi: Yamubologö ia banua ba gotalua nidanö, ena''ö famabali ia ba gotalua nidanö si dua balö andrö. Ba itörö.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 7, 'Ba ifazökhi wa''ebolo mbanua andrö Lowalangi, famabali nidanö tou mbanua ba nidanö yaŵa mbanua.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 8, 'Ba ibe''e töi wa''ebolo andrö mbanua Lowalangi.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 9, 'Ba imane Lowalangi: Yamu''oniagö ia idanö barö mbanua ba zi ha sambua nahia, ena''ö oroma zabe''e tanö. Ba itörö.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 10, 'Ba ibe''e töi zabe''e andrö danö Lowalangi, ba si tonia idanö, ba asi ifotöi. Ba i''ila Lowalangi, wa no si sökhi.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 11, 'Ba imane Lowalangi: Yatumbu ba danö ndru''u, awö gule-gule sowua, tanömö dania, ba eu sowua ngawalö mbua ba danö, sohunö, tanömönia. Ba itörö.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 12, 'Ba tumbu ba danö ndru''u ba gule-gule sowua dania, tanömö, ngawa-ngawalö, ba eu sowua si so hunö, tanömö dania, ngawa-ngawalö. Ba i''ila Lowalangi, wa no si sökhi.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 13, 'Ba bongi, ba moluo, ba luo si tölu.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 14, 'Ba imane Lowalangi: Yaso zihaga ba wa''ebolo mbanua andrö, ba wamöfö''ö si ma''ökhö ba si bongi, ba yatobali tandra nga''ötö ba tandra ngaluo ba tandra ndröfi wakhe;[3]', '["Yer 31:35"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 15, 'tobali sihaga ba wa''ebolo mbanua andrö, ba wohagaini uli danö. Ba itörö.', '["Yer 31:35"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 16, 'Ba ifazökhi zihaga andrö Lowalangi, si dombua: sihaga sebua andrö, famatörö zi ma''ökhö ba sihaga side-ide andrö, famatörö zi bongi, ba awönia ndröfi andrö.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 17, 'Ba ifataro ira ba wa''ebolo mbanua andrö Lowalangi, ena''ö lahagaini guli danö,', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 18, 'ba wamatörö si ma''ökhö ba si bongi ba ba wamöfö''ö si moluo ba si bongi. Ba i''ila Lowalangi wa no si sökhi.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 19, 'Ba bongi ba moluo, ba luo si öfa.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 20, 'Ba imane Lowalangi : Yamaliŵa-liŵa ba nidanö zaliŵa-liŵa sonoso ba yamuhombo wofo yaŵa guli danö, ba wa''ebolo mbanua andrö.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 21, 'Ba ifazökhi Lowalangi zaliŵa-liŵa ba nasi andrö, segebua, ba sonoso andrö fefu, saliŵa-liŵa, soliha-liha ba nidanö, ngawa-ngawalö, awö ngawalö zihombo.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 22, 'Ba ifahowu''ö ira Lowalangi, imane: Mi''o''ono ba mi''oya''ö ami ba mifo''ösi nasi; ba fofo andrö, ba ya''oya sibai ba guli danö.[4]', '["Faigi 8:17"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 23, 'Ba bongi ba moluo, ba luo si lima.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 24, 'Ba imane Lowalangi: Yamulua ba danö zonoso, ngawa-ngawalö, urifö niha ba kuö-kuö ba utu ndru''u, ngawa-ngawalö. Ba itörö.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 25, 'Ba ifazökhi gutu ndru''u andrö Lowalangi, hadia ia ngawalö, awö ngawalö gurifö niha ba saliŵa-liŵa ba danö fefu, sanana ba danö, ngawa-ngawalö. Ba i''ila Lowalangi, wa no si sökhi.', '[]', NULL),
  (3392386, 'OT', 'Moze I', 1, 26, 'Ba imane Lowalangi: Datafazökhi niha, famaedoda, si fakhili-khili khöda, samatörö i''a ba nasi dania ba fofo ba dalu mbanua ba urifö niha andrö ba utu ndru''u fefu, awö kuö-kuö andrö, sanana-nana ba guli danö.[5]', '["Faigi 5:1; Efes 4:24; Kol 3:10","KorI 11:7; Mat 19:4"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 27, 'Ba ifazökhi niha Lowalangi, famaedonia — famaedo Lowalangi ibali''ö; ira matua ba ira alawe womböinia ya''ira.[6]', '["Faigi 5:1; Efes 4:24; Kol 3:10","KorI 11:7; Mat 19:4"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 28, 'Ba ifahowu''ö ira Lowalangi, imane khöra: Mi''o''ono ba mi''oya''ö ami, mifo''ösi guli danö ba mibe''e barö mbawami, samatörö i''a ba nasi ami, awö wofo ba dalu mbanua, awö zaliŵa-liŵa ba danö fefu, sanana-nana ba guli danö.[7]', '["Faigi 9:1; Sin 8:7"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 29, 'Ba imane Lowalangi: Hiza, ube''e fönami fefu zinanö sowua ba guli danö heza, awö geu sowua sohunö, tanömö dania — da''ö gömi.', '["Faigi 9:1; Sin 8:7"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 30, 'Ba ba zaliŵa-liŵa ba danö andrö fefu ba ba wofo ba dalu mbanua fefu, möi ba zanana ba danö, sonoso ba bulu ndru''u hadia ia göra. Ba itörö.', '["Faigi 9:1; Sin 8:7"]', NULL),
  (3392386, 'OT', 'Moze I', 1, 31, 'Ba i''ila Lowalangi, sökhi sibai fefu nifazökhinia.', '["Faigi 9:1; Sin 8:7"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 1, 'Si manö wangasiwai banua si yaŵa ba tanö, awö nösi fefu.', '["MozII 20:21; MozV 5:14; Heb 4:4"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 2, 'Ba me luo si fitu i''o''ozui womböinia andrö Lowalangi, nifazökhinia andrö; ba molombase ia me luo si fitu, me no awai womböinia andrö fefu, nifazökhinia.[1]', '["MozII 20:21; MozV 5:14; Heb 4:4"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 3, 'Ba ifahowu''ö Lowalangi luo si fitu, ni''amoni''ö iŵa''ö, me no molombase ia ba da''ö, me no awai halöŵönia andrö fefu, niwöwöinia ba nifazökhinia.', '["MozII 20:21; MozV 5:14; Heb 4:4"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 4, 'Da''ö mböröta mbanua si yaŵa, fabaya tanö, me tefazökhi: Me luo ifazökhi Yehowa Lowalangi danö, awö mbanua si yaŵa,', '["KorI 15:45; Yob 33:4; Fangomb 12:7"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 5, 'ba lö eu-eu na ba mbenua ba lö sinanö na ba mbolo mbenua; lö''ö na nifoteu Yehowa Lowalangi tanö, ba lö niha na, sonowi mena''ö.', '["KorI 15:45; Yob 33:4; Fangomb 12:7"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 6, 'Ba sau zi möi miyaŵa moroi ba danö, inamoi guli danö ma''asagörö.', '["KorI 15:45; Yob 33:4; Fangomb 12:7"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 7, 'Ba iwöwöi niha Yehowa Lowalangi, tanö mböröta, nihalö ba mbenua ba iwuwusi ba dögi nikhunia hanu-hanu fangorifi ba tobali sonoso niha andrö.[2]', '["KorI 15:45; Yob 33:4; Fangomb 12:7"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 8, 'Ba ifazökhi kabu Yehowa Lowalangi, ba Gedena, tanö ba gatumbukha luo, ba ifa''aso ba da''ö niha andrö, nifazökhinia.', '["Faigi 3:22; Fam 2:7; 22:2"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 9, 'Ba ifatumbu''ö moroi ba danö ngawalö geu sowua Lowalangi, eu somasi ita famaigi ba sami bua, ba eu fangorifi ba dalu kabu ba eu famotokhi ba dödö si sökhi ba si lö sökhi.[3]', '["Faigi 3:22; Fam 2:7; 22:2"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 10, 'Ba sara nidanö si otarai Gedena, ba wamo''idanö kabu andrö; ba si fabali dania ia, tobali öfa rozi; si sara, ba Fizona döi;', '["Faigi 3:22; Fam 2:7; 22:2"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 11, 'da''ö zamasui tanö Hewila andrö ma''afefu, ba nisöndra balaki.', '["Faigi 3:22; Fam 2:7; 22:2"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 12, 'Ba balaki ba danö andrö, ba no si sökhi. Ba tesöndra göi ba da''ö mbaluri ba feremata una.', '["Faigi 3:22; Fam 2:7; 22:2"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 13, 'Ba töi nidanö si sara, ba Gihona, samasui tanö Gusi da''ö.', '["Faigi 3:22; Fam 2:7; 22:2"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 14, 'Ba si sara zui, ba Hideke döi, ya''ia föna-föna danö Asiria; ba si sara, ba Oiferati.', '["Faigi 3:22; Fam 2:7; 22:2"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 15, 'Ba ihalö niha no mege Yehowa Lowalangi, ifa''aso ba kabu Edena andrö, ba wangehao ba ba wanaro.', '["Faigi 3:22; Fam 2:7; 22:2"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 16, 'Ba ibe''e li ba niha Yehowa Lowalangi, imane: Ö''a sa''ae mbua geu ba kabu fefu,', '["Rom 5:12"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 17, 'ba bua geu famotokhi ba dödö si sökhi ba si lö sökhi, ba lö tola ö''a; ö''a si''aikö da''ö, ba mate ndra''ugö![4]', '["Rom 5:12"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 18, 'Ba imane Yehowa Lowalangi: Lö sökhi ba niha, na ha ya''i-ya''ia; da''ufazökhi khönia nawö, si fabohö khönia.', '["KorI 11:8","Mat 19:5; KorI 6:16; Efes 5:31"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 19, 'Me noa sa''ae ifazökhi Yehowa Lowalangi moroi ba danö fefu zaliŵa-liŵa ba danö, awö wofo ba dalu mbanua, ba i''ohe ba niha, ena''ö ifaigi, hadia döi ibe''e, ba hadia si''ai nibe''e niha töi zonoso andrö, da''ö döira dania.', '["KorI 11:8","Mat 19:5; KorI 6:16; Efes 5:31"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 20, 'Ba ifotöi niha fefu gurifö niha, awö wofo ba dalu mbanua, awö gutu ndru''u fefu; ba ba niha, ba lö falukha nawö, si faböbö khönia.', '["KorI 11:8","Mat 19:5; KorI 6:16; Efes 5:31"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 21, 'Ba ifaförö niha Yehowa Lowalangi, femörö sabölö, ba me no mörö ia, ba ihalö zara döla nosunia ba ifo''ösi nagole nahania.', '["KorI 11:8","Mat 19:5; KorI 6:16; Efes 5:31"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 22, 'Ba ibali''ö ira alawe Yehowa Lowalangi döla nosu andrö, nihalönia ba niha, ba ifasao ba niha.', '["KorI 11:8","Mat 19:5; KorI 6:16; Efes 5:31"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 23, 'Ba imane niha: Töla föfö dölagu da''ö ba nagole föfö nagolegu; labe''e töinia ndra alawe, me no ba ndra matua tehalö ia.[5]', '["KorI 11:8","Mat 19:5; KorI 6:16; Efes 5:31"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 24, 'Andrö i''erogö ndra amania inania niha, ba molemba ia ba ngambatönia, ba tobali ha sambua boto ira.[6]', '["KorI 11:8","Mat 19:5; KorI 6:16; Efes 5:31"]', NULL),
  (3392404, 'OT', 'Moze I', 2, 25, 'Ba si lö nukha ira, darua ira niha ngambatönia, ba lö''ö sa aila ira.', '["KorI 11:8","Mat 19:5; KorI 6:16; Efes 5:31"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 1, 'Ba no sonekhe gulö, moroi ba zaliŵa-liŵa ba danö fefu nifazökhi Yehowa Lowalangi; ba imane ba ndra alawe: Hadia, duhu no iŵa''ö Lowalangi: Lö''ö manö mi''a mbua geu ba kabu?[1]', '["Fam 12:9"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 2, 'Ba imane ira alawe khö gulö: Tola sa ma''a mbua geu ba kabu,', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 3, 'ba ba mbua geu andrö si so ba dalu kabu, ba no iŵa''ö Lowalangi: Lö tola mi''a ia, ba böi mibabaya, fa böi mate ami!', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 4, 'Ba imane ulö ba ndra alawe: Ma''ifu sa lö mate ami;[2]', '["KorII 11:3"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 5, 'ba i''ila sibai sa Lowalangi: mi''a si''aikö ia, ba teboka hörömi, ba tobali si mane Lowalangi ami, saboto ba dödö si sökhi ba si lö sökhi.', '["KorII 11:3"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 6, 'Ba me i''ila sa''ae ira alawe, wa sökhi ni''a mbua geu andrö, awö wa si sökhi famaigi, awö wa no omasiö geu da''ö, ba wanöndra fa''atua-tua khönia, ba ihalö mbua, i''a, ba ibe''e göi ö ngambatönia si so ba ngainia, ba i''a göi.[3]', '["TimI 2:14"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 7, 'Ba teboka höröra, darua ira, ba oroma khöra, wa lö balu-balura; ba lafatagu lae-lae, u''ira.', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 8, 'Ba me larongo ruru Yehowa Lowalangi sanörö kabu, tanö owi, me okafu zino, ba i''alui wamini''ö ya''ia khö Yehowa Lowalangi niha, awö ngambatönia barö ndraha geu ba kabu.', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 9, 'Ba humede Yehowa Lowalangi ba niha, imane khönia : Heza so ndra''ugö?', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 10, 'Ba imane: Urongo wehozi-hozi gaheu ba kabu, ba ata''udo, me lö balu-balugu, ba ubini''ö ndra''o.', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 11, 'Ba imane: Ha niha zanguma''ö khöu, wa lö balu-balumö? Hadia, no ö''a mbua geu andrö niŵa''ögu khöu: Böi a da''ö?', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 12, 'Ba imane niha: Alawe andrö, nibe''eu awögu, da''ö zame''e ögu, mbua geu andrö, ba no u''a.', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 13, 'Ba imane Yehowa Lowalangi ba ndra alawe: Hadia nilaumö andrö? Imane ira alawe: Ulö zamowöhö ya''o, fa u''a.', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 14, 'Ba imane Yehowa Lowalangi khö gulö: Me no ölau da''ö, ba ni''elifi ndra''ugö föna gurifö niha fefu ba föna gutundru''u fefu; ö''anana''ö talu wofanö-fanö ba ö''a danö, götö wa''anau nosou!', '["Heb 2:14; YohI 3:8"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 15, 'Ba ufa''udu ami ndra alawe ba ufa''udu ira ma''uwumö ma''uwunia, da''ö zomama högöu dania, ihundragö, ba sondrou börö sisinia ndra''ugö.[4]', '["Heb 2:14; YohI 3:8"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 16, 'Ba ba ndra alawe, ba imane: Erege sibai dödöu ba dabi-dabina ube''e, afökhö dania wadono khöu, ba ö''isö [sa atö] ngambatöu ba samatörö ya''ugö ia![5]', '["KorI 11:3; Efes 5:22; Kol 3:18; FetI 3:1"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 17, 'Ba ba niha, ba imane: Me no ö''o''ö niŵa''ö ngambatöu ba me no ö''a mbua geu andrö, niŵa''ögu khöu wanguma''ö: Böi a ia, ba ni''elifi mbenua, börö ndra''ugö; ya''erege dödöu wemanga göu khönia, götö wa''anau nosou.', '["TesII 3:10"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 18, 'Doi ba du''u zilua khönia khöu, ba si manga gule-gule ba nowi ndra''ugö.', '["TesII 3:10"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 19, 'Aböböi dania mbawau ba wemanga göu, irege mangawuli ndra''ugö ba danö tou, ba nihalö ya''ugö. Tanö sa atö ndra''ugö ba si tobali tanö zui dania![6]', '["TesII 3:10"]', NULL),
  (3221777, 'OT', 'Moze I', 3, 20, 'Ba ibe''e töi ngambatönia Khawa niha, me ma''uwunia fefu zauri dania.', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 21, 'Ba ifobaru niha Lowalangi baru uli gutu ndru''u, awö ngambatönia.', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 22, 'Ba imane Yehowa Lowalangi: Hiza, no tobali si mane ya''ita niha, me no aboto ba dödönia hadia zi sökhi ba hadia zi lö sökhi. Ba me si manö, ba fa böi i''oro''ö dangania, ba wangai bua geu fangorifi andrö, ba wanöndra fa''auri si lö aetu!', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 23, 'Ba iheta ba kabu Edena niha Yehowa Lowalangi, ena''ö mangahalö ia ba danö, ba nihalö ya''ia.', '[]', NULL),
  (3221777, 'OT', 'Moze I', 3, 24, 'Ifofanö niha ba ifataro Kerubi föna kabu Edena, tanö ba gatumbukha luo khönia, Kerubi si so föda si takile, nifaligoi, ba wanaro lala ba geu fangorifi andrö.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 1, 'Ba orudu niha khö wo''omonia, ba manabina ba madono, Ka''ino döi nononia, ba imane: No usöndra niha, itolo Lowalangi.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 2, 'Ba ifuli mo''ono, Habeli döi, akhi Ga''ino.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 3, 'Ba ara ma''ifu, ba ibe''e zumange Yehowa Ka''ino bua nowi khönia.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 4, 'Ba ibe''e göi Habeli, ono gurifönia si a''a, tawö ibe''e. Ba omasi Yehowa Habeli ba sumange khönia;[1]', '["Heb 11:4"]', NULL),
  (3224157, 'OT', 'Moze I', 4, 5, 'ba Ka''ino ba sumange andrö khönia, ba lö omasi ia.', '["Heb 11:4"]', NULL),
  (3224157, 'OT', 'Moze I', 4, 6, 'Ba imane Yehowa khö Ga''ino: Hana wa mofönu ndra''ugö, ba hana wa abao mbawau?', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 7, 'Tenga si manö: na satulö ölau, ba tola öfaöga mbawau; ba na tenga satulö nilaumö, ba no so moroi tou horö, itarogö ndra''ugö ba i''isö''ö; ba ya''ugö ba höndrögö ia.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 8, 'Ba imane Ka''ino khö nakhinia: Tabu ba mbenua! ba me no larugi mbenua, ba maoso Ga''ino khö nakhinia Habeli, ibunu.[2]', '["Mat 23:35; YohI 3:12; Yud 11"]', NULL),
  (3224157, 'OT', 'Moze I', 4, 9, 'Ba imane Yehowa khö Ga''ino: Heza so nakhiu Habeli?', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 10, 'Ba imane: Hadia nilaumö? Hiza, mu''ao khögu ndro nakhiu andrö moroi ba danö tou.[3]', '["Heb 12:24"]', NULL),
  (3224157, 'OT', 'Moze I', 4, 11, 'Ba iada''e, ba ni''elifi ndra''ugö, nifofanö ba danö andrö, si no mamokai bawania, ba wamadu do nakhiu andrö, moroi ba dangau.', '["Heb 12:24"]', NULL),
  (3224157, 'OT', 'Moze I', 4, 12, 'Na monowi ndra''ugö ba danö, ba lö''ö sa''ae ibe''e khöu mbuania; si lö hinaoma ndra''ugö ba guli danö!', '["Heb 12:24"]', NULL),
  (3224157, 'OT', 'Moze I', 4, 13, 'Ba imane Ka''ino khö Yehowa: Si tebai utaha lua-lua horögu andrö.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 14, 'Öfofanö ndra''o ma''ökhö, moroi ba danö, ba samini''ö ya''ia fönau ndra''odo ba si lö hinaoma ba guli danö, ba ha niha zi falukha khögu, ba ibunudo.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 15, 'Ba imane khönia Yehowa: Hiza, mewitu lalau mbalö ba zamunu Ka''ino.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 16, 'Ba mofanö Ga''ino, i''erogö Yehowa; ba danö Nodi soso ia dania, tanö ba gatumbukha luo, i''otarai Gedena.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 17, 'Ba orudu Ga''ino khö wo''omonia, ba manabina ba madono, Khanoki döi nononia. Ba itaru''ö mbanua ba ibe''e töi mbanua andrö döi nononia andrö, Khanoki.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 18, 'Ba ono Khanoki, ba Iradi. Ba ono Giradi ba Mehuya''eli, ba ono Mehuya''eli, ba Metuza''eli, ba ono Metuza''eli ba Lameki.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 19, 'Ba samodombua dongania Lameki andrö, Ada döi zi sambua ba Sila döi zi sambua.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 20, 'Ba mo''ono Gada, Yabalo döi nononia, tua zi so baosi, sanguri hadia ia da''ö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3224157, 'OT', 'Moze I', 4, 21, 'Ba akhinia Yubalo, tua zolau biola ba sigu.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 22, 'Ba mo''ono göi Zila, Tubaka''ino nononia, tua ziambu da''ö, ba talifusönia alawe, ba Na''ama.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 23, 'Ba imane Lameki khö wo''omonia andrö si darua: Ya''ugö Ada ba ya''ugö Sila, mifondrongondrongo wehedegu andre! Ya''ami fo''omo Lameki, ya''aboto ba dödömi niŵa''ögu! Ubunu niha, balö zokho andre khögu ba ono niha balö zelezitö andre.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 24, 'Na fitu winaeta wolau balö Ga''ino, ba fitu ngafulu a fitu winaeta mbalö Lameki andre.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 25, 'Ba ifuli orudu Gadamo khö wo''omonia, ba mo''ono ia ono matua, ba ibe''e töinia Zeti (Te''ali). [Imane]: Noa sa ibe''e khögu nga''ötö bö''ö Lowalangi, fangali Habeli andrö, nibunu Ga''ino.', '[]', NULL),
  (3224157, 'OT', 'Moze I', 4, 26, 'Ba mo''ono göi Zeti andrö, ba ibe''e töi nononia Genosi.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 1, 'Sura nga''ötö duada Adamo da''e. Me ifazökhi Gadamo andrö Lowalangi, ba famaedo Lowalangi womböinia ya''ia;', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 2, 'ira matua ba ira alawe wamazökhinia ya''ira, ba ifahowu''ö ira ba ibe''e töira niha, me luo tefazökhi ira.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 3, 'Ba me no 130 fakhe Gadamo, ba tumbu khönia nono, si fakhili-khili khönia, famaedonia, ba ibe''e töinia Zeti.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 4, 'Ba me no tumbu khönia Zeti andrö, ba 800 fakhe tö wa''anau noso Gadamo, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 5, 'Ba fa''anau noso Gadamo fefu, fa''arania ba guli danö, ba 930 fakhe; ba mate ia.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 6, 'Ba no 105 fakhe Zeti, ba tumbu khönia Genosi andrö.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 7, 'Ba me no tumbu khönia Genosi, ba 807 fakhe tö Zeti, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 8, 'Ba fa''anau noso Zeti fefu, ba 912 fakhe, ba mate ia.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 9, 'Ba 90 fakhe Genosi, ba tumbu khönia Genana andrö.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 10, 'Ba me no tumbu khönia Genana andrö, ba 815 fakhe tö Genosi andrö, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 11, 'Ba fa''anau noso Genosi fefu, ba 905 fakhe, ba mate ia.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 12, 'Ba me no 70 fakhe Genana andrö, ba tumbu khönia Mahalaleli.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 13, 'Ba me no tumbu khönia Mahalaleli, ba 840 fakhe tö Genana ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 14, 'Ba fa''anau noso Genana fefu, ba 910 fakhe, ba mate ia.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 15, 'Ba me no 65 fakhe Mahalaleli andrö, ba tumbu khönia Yaredi.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 16, 'Ba me no tumbu khönia Yaredi andrö, ba 830 fakhe tö Mahalaleli, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe:', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 17, 'Ba fa''anau noso Mahalaleli fefu, ba 895 fakhe, ba mate ia.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 18, 'Ba me no 162 fakhe Yaredi, ba tumbu khönia Khenoki.[1]', '["Yuda 14"]', NULL),
  (3225143, 'OT', 'Moze I', 5, 19, 'Ba me no tumbu khönia Khenoki andrö, ba 800 fakhe tö Yaredi, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Yuda 14"]', NULL),
  (3225143, 'OT', 'Moze I', 5, 20, 'Ba fa''anau noso Yaredi fefu, ba 962 fakhe, ba mate ia.', '["Yuda 14"]', NULL),
  (3225143, 'OT', 'Moze I', 5, 21, 'Ba me no 65 fakhe Khenoki, ba tumbu khönia Metusala.', '["Heb 11:5"]', NULL),
  (3225143, 'OT', 'Moze I', 5, 22, 'Ba me no tumbu khönia Metusala andrö, ba 300 fakhe tö Khenoki, lö aefa-aefa khönia Lowalangi ba döröŵania ba guli danö, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.[2]', '["Heb 11:5"]', NULL),
  (3225143, 'OT', 'Moze I', 5, 23, 'Ba fa''anau noso Khenoki fefu, ba 365 fakhe.', '["Heb 11:5"]', NULL),
  (3225143, 'OT', 'Moze I', 5, 24, 'Ba me no lö saefa-aefa khönia Lowalangi ba lalania, ba samuza ma''ökhö, ba taya manö ia, noa sa iheta Lowalangi.', '["Heb 11:5"]', NULL),
  (3225143, 'OT', 'Moze I', 5, 25, 'Ba me no 187 fakhe Metusala, ba tumbu khönia Lameki.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 26, 'Ba me no tumbu khönia Lameki andrö, ba 782 fakhe tö Metusala, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 27, 'Ba fa''anau noso Metusala fefu, ba 969 fakhe, ba mate ia.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 28, 'Ba me no 182 fakhe Lameki andrö, ba tumbu khönia nono matua.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 29, 'Ba ibe''e töinia Noakhi, imane: Da''e dania zondrara tödöda ba wa''erege dödöda ba ba wa''akao dangada andre, ba danö, ni''elifi Yehowa.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 30, 'Ba me no aefa tumbu khönia Noakhi andrö, ba 595 fakhe tö Lameki, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 31, 'Ba fa''anau noso Lameki fefu, ba 777 fakhe, ba mate ia.', '[]', NULL),
  (3225143, 'OT', 'Moze I', 5, 32, 'Ba me no 500 fakhe Noakhi, ba tumbu khönia Zemi ba Khamo ba Yafeti.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 1, 'Ba me no ibörötaigö ato niha ba guli danö, me tumbu-tumbu khöra nono alawe,', '["Mat 24:38"]', NULL),
  (3227278, 'OT', 'Moze I', 6, 2, 'ba la''ila ono matua khö Lowalangi, wa no si sökhi sibai nono alawe ba niha, ba lahalö zomasi ira.[1]', '["Mat 24:38"]', NULL),
  (3227278, 'OT', 'Moze I', 6, 3, 'Ba imane Yehowa: Lö tola sa''ae Ehehagu zamatörö tödö niha, ösi niha ira, ba wa''elungura andrö; famonosogu ya''ira na, ba ya hatö 120 fakhe.[2]', '["Yoh 3:6; FetI 3:20"]', NULL),
  (3227278, 'OT', 'Moze I', 6, 4, 'Ba me luo da''ö ba so ba guli danö niha sebua sibai boto; ba meno orudu nono matua khö Lowalangi ba nono alawe ba niha, ba me mo''ono ira khöra — ba da''ö niha sabölö andrö, sebua sibai turia ba götö föna andrö.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 5, 'Ba me i''ila Yehowa, wa no ebua sibai zi lö sökhi ba niha ba guli danö, wa no si lö sökhi manö gera-erara, awö nikhoi dödöra, si lö mamalö-malö,[3]', '["Faigi 8:21; Mat 15:19; Sin 14:3"]', NULL),
  (3227278, 'OT', 'Moze I', 6, 6, 'ba mangesa dödö Yehowa, wa no ifazökhi niha ba guli danö, ibusi sibai tödönia.', '["Faigi 8:21; Mat 15:19; Sin 14:3"]', NULL),
  (3227278, 'OT', 'Moze I', 6, 7, 'Ba imane Yehowa: Da''uhori ba guli danö niha andrö nifazökhigu, he niha ba he uriföra ba he kuö-kuö andrö ba he fofo ba dalu mbanua; mangesa sa''ae dödögu, wa no ufazökhi ira.', '["Faigi 8:21; Mat 15:19; Sin 14:3"]', NULL),
  (3227278, 'OT', 'Moze I', 6, 8, 'Ba Noakhi andrö, ba falukha wa''ebolo dödö Lowalangi.', '["Faigi 8:21; Mat 15:19; Sin 14:3"]', NULL),
  (3227278, 'OT', 'Moze I', 6, 9, 'Da''e nga''ötö No''akhi: No''akhi andrö, ba no niha satulö tödö, si lö sinegu, ba götönia andrö; lö aefa-aefa khönia Lowalangi ba lalania.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 10, 'Ba tölu nono No''akhi: Semi ba Khamo ba Yafeti.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 11, 'Ba no tekiko guli danö föna Lowalangi, anönö danö horö.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 12, 'Ba i''ila Lowalangi, wa no tekiko sibai guli danö, noa sa tefuyu lala nösi guli danö fefu.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 13, 'Ba imane Lowalangi khö Noakhi: No so ba duduma hörögu wozu nösi guli danö fefu: noa sa anönö danö horö, nifazökhira; ba da''uhori ira ba guli danö.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 14, 'Fazökhi khöu nowo, naru''u geunia, ba öfobate''e ba ögalö-galöni sulumou, tanö bakha ba tanö baero.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 15, 'Ba ömane wamazökhi ya''ia: 300 hela wa''anau nowo andrö ba 50 hela wa''ebolo ba 30 hela wa''alaŵa.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 16, 'Ba öfosandrela nowo, yaŵa, ba dete, sahela wa''alaŵa öbe''e. Ba bawandruhö nowo, ba ba ngai öbe''e; öfotölu nga''ötö ba oi bate''e öbe''e.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 17, 'Lö ara tö sa dania ba anönö danö idanö ube''e, ba wangohori fefu nösi guli danö, si so noso, barö mbanua, si yaŵa; fefu zi so ba guli danö ba si tekiko ube''e.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 18, 'Ba ba khöu, ba fawu''u li ndra''o, ba si möi ba nowo ndra''ugö ya''ugö ba onou matua andrö ba fo''omou ba umönöu andrö, awöu.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 19, 'Ba ba zi so noso fefu, ba nösi guli danö ma''afefu, ba dua-dua geu, dombu-dombua ö''ohe yaŵa ba nowo, ba wangorifi ya''ira, awöu; sara zi matua ba sara zi alawe.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 20, 'Fofo andrö, ngawa-ngawalö, ba urifö niha ngawa-ngawalö ba sanana-nana ba guli danö fefu, ngawa-ngawalö ba dua-dua möi khöu ba nowo yaŵa, ena''ö te''orifi.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 21, 'Ba ya''ugö, ba faigi khöu ngawalö gö fefu, ni''aga-aga, ba höna khöu, öu dania ba öra.', '[]', NULL),
  (3227278, 'OT', 'Moze I', 6, 22, 'Ba i''o''ö sibai Noakhi, dali niwa''ö Lowalangi khönia.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 1, 'Ba imane Yehowa khö Noakhi: Ae baowo, ya''ugö ba soroiyomou fefu, me no satulö ndra''ugö fönagu, u''ila, ba niha andrö.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 2, 'Ba zaliŵa-liŵa ba danö, si lö si lö sökhi, ba fitu-fitu halö, si matua ba si alawenia; ha ba zi so si lö sökhi ba dua-dua, si matua ba si alawenia.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 3, 'Ba si manö ba wofo ba dalu mbanua, fitu-fitu, si matua ba si alawenia, ba wangorifi tanömö ba guli danö ma''asagörö.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 4, 'Hatö fitu bongi sa, ba moteu ba guli danö ube''e, öfa wulu ngaluo ba öfa wulu mbongi, ba uhori ba guli danö fefu zi so andrö, nifazökhigu.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 5, 'Ba i''o''ö sibai Noakhi niŵa''ö Yehowa khönia.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 6, 'Ba no 600 fakhe Noakhi, me anönö danö idanö.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 7, 'Ba möi ba nowo Noakhi, awö nononia ba fo''omonia ba umönönia, föna wa''anönö danö andrö.[1]', '["Luk 17:27; FetII 2:5"]', NULL),
  (3229070, 'OT', 'Moze I', 7, 8, 'Ba saliŵa-liŵa ba danö, si lö hadia ia si lö sökhi, ba si so si lö sökhi ba fofo ba sanana-nana ba guli danö,', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 9, 'ba faedo we''amöi baowo khö Noakhi, sara-sara zi matua ba sara-sara zi alawe, si mane niŵa''ö Lowalangi khö Noakhi.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 10, 'Ba me no aefa zi fitu bongi andrö, ba ibörötaigö wa''anönö danö andrö.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 11, 'Me 600 fakhe Noakhi, me baŵa si dua, ba zi mewelewitu, da''ö mbaŵa, ba zangumbu-ngumbu manö nidanö moroi ba namö sabakha, ba teboka zandrela mbanua si yaŵa.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 12, 'Ba abölö-bölö sibai deu ba guli danö, öfa wulu ngaluo ba öfa wulu mbongi.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 13, 'Ba me luo da''ö möi baowo Noakhi ba Semi ba Khamo ba Yafeti, ono Noakhi ba fo''omo Noakhi ba umönönia andrö si datölu,', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 14, 'ba fao, ya''ira ba utu ndru''u andrö fefu ba urifö niha fefu, ngawa-ngawalö ba kuö-kuö fefu, sanana-nana ba danö, ngawa-ngawalö, awö ngawalö wofo, fefu zo''afi.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 15, 'Da''ö zi möi khö Noakhi, baowo, dua-dua, fefu nösi guli danö, si so noso.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 16, 'Ba si möi yaŵa, ba sara-sara zi matua ba sara-sara zi alawe, fefu nösi guli danö, si mane niŵa''ö Lowalangi khönia. Ba ikusi mbawandruhö Yehowa, furinia.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 17, 'Ba ibörötaigö wa''anönö danö andrö, öfa wulu ngaluo. Ba tedou-dou molö, ifazaŵa nowo, alaŵa yaŵa danö.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 18, 'Ba itugu ebua sibai molö, tedou-dou sibai ba guli danö, ba hulö zoloyo nowo ba molö andrö.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 19, 'Itugu ebua sibai nidanö ba guli danö, tobali anönö hili salaŵa fefu, ba guli danö.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 20, 'Felelima si''u inönöi hili idanö, tobalu manö.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 21, 'Ba tekiko nösi guli danö fefu, saliŵa-liŵa ba guli danö, he fofo ba he urifö niha ba he utu ndru''u, fefu hadia ia zanana-nana ba guli danö, ba dozi niha.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 22, 'Fefu zi so noso ba nikhu, si so ba danö yaŵa, ba mate.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 23, 'Si manö wangohorinia fefu zi so ba guli danö, he niha, ba he urifö niha ba kuö-kuö ba fofo ba dalu mbanua; tehori ba danö, tobali hatö Noakhi zi tosai, awö hadia ia zi fao khönia baowo.', '[]', NULL),
  (3229070, 'OT', 'Moze I', 7, 24, 'Ba lö alö-alö nidanö ba guli danö, 150 wongi.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 1, 'Ba itörö tödö Lowalangi Noakhi ba utu ndru''u andrö fefu ba urifö niha fefu, si no fao khönia baowo.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 2, 'Ba teduhö gumbu andrö ba namö, ba sandrela andrö ba mbanua si yaŵa, ba tetaha deu si oroi mbanua si yaŵa.[1]', '["Yob 38:37"]', NULL),
  (3229780, 'OT', 'Moze I', 8, 3, 'Ba itugu alö nidanö ba guli danö, ogo''ö, me no irugi 150 wongi.', '["Yob 38:37"]', NULL),
  (3229780, 'OT', 'Moze I', 8, 4, 'Ba ba zi mewelewitu ba mbaŵa si fitu, ba tosake nowo ba hili Gararata.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 5, 'Ba itugu alö-alö nidanö, irugi mbaŵa si fulu. Ba me tesa''a ba mbaŵa si fulu, ba oroma zuzu hili misa.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 6, 'Ba 40 wongi aefa da''ö, ba ibokai zandrela nowo Noakhi, sandrela andrö nifazökhinia,', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 7, 'ba ifoloi gaga, ba manörö-nörö manö da''ö, irege ogo''ö nidanö ba guli danö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 8, 'Aefa da''ö, ba ifoloi marafadi, ba wamaigi, na no ogo''ö nidanö ba guli danö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 9, 'Ba lö isöndra dugela, solombase ia, marafadi andrö, ba mangawuli ia baowo khö Noakhi, me lö saefa na wa''anönö guli danö ma''afefu; ba i''oro''ö dangania Noakhi, ifuli ihalö baowo khönia marafadi andrö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 10, 'Ba fitu bongi tö ifuli ibase''ö, ba ifuli ifoloi marafadi, moroi ba nowo.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 11, 'Ba mangawuli khönia da''ö me tanö owi, ba hiza ba mbawania mbadö-badö falo, sawena ifatö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 12, 'Ba ibase''ö zui, fitu bongi tö, ba ifuli ifoloi marafadi, ba lö mangawuli khönia da''ö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 13, 'Ba me no sara töra 600 fakhe Noakhi, me tesa''a ba mbaŵa si föföna, ba no ogo''ö nidanö ba guli danö. Ba ibeta zagö nowo Noakhi ba ifakhölö ia, ba no otufo guli danö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 14, 'Ba ba zi dua wulu a fitu ba mbaŵa si dua, ba alua otufo guli danö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 15, '13 Ba me no sara töra 600 fakhe Noakhi, me tesa''a ba mbaŵa si föföna, ba no ogo''ö nidanö ba guli danö. Ba ibeta zagö nowo Noakhi ba ifakhölö ia, ba no otufo guli danö. 14 Ba ba zi dua wulu a fitu ba mbaŵa si dua, ba alua otufo guli danö. 15', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 16, 'Heta''ö baowo, ya''ugö ba fo''omou ba onou ba umönöu, awöu.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3229780, 'OT', 'Moze I', 8, 17, 'Ba fefu zaliŵa-liŵa ba danö, si no fao khöu, fefu nösi guli danö, he fofo ba he urifö niha ba he kuö-kuö fefu, sanana-nana ba danö, ba fao khöu we''amöi tou, ena''ö maliŵa-liŵa ba guli danö ba ena''ö mo''ono-ono ba wangoya''ö ya''ira ba guli danö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 18, 'Ba möi tou Noakhi ba ononia ba fo''omonia ba umönönia.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 19, 'Fefu zi öfa ahe, fefu kuö-kuö ba fefu wofo, fefu zaliŵa-liŵa ba guli danö, ngawa-ngawalö, ba aheta baowo.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 20, 'Ba ifa''anö naha wame''e sumange khö Yehowa Noakhi, ihalö ngawalö zaliŵa-liŵa ba guli danö fefu, si lö hadia ia zi lö sökhi, awö ngawalö wofo fefu, si lö si lö sökhi, ba ibe''e sumange nitunu, ba naha andrö.', '[]', NULL),
  (3229780, 'OT', 'Moze I', 8, 21, 'Ba me i''ago hua omasiö andrö Yehowa, ba imane dödönia: Lö utohugö wangelifi tanö ha niha andrö, me no si lö sökhi gera-era dödönia, i''otarai iraono ia; ba lö utohugö wamubunu fefu zi so noso, si mane folaugu mege.[2]', '["Faigi 6:5; Yes 54:9","Yer 33:20"]', NULL),
  (3229780, 'OT', 'Moze I', 8, 22, 'Sagötö tanö dania, ba böi ya''aetu-aetu wananö ba famasi ba fa''okafu ba fa''aukhu zino ba baŵa lökhö ba baŵa deu ba si ma''ökhö ba si bongi.[3]', '["Faigi 6:5; Yes 54:9","Yer 33:20"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 1, 'Ba ifahuwu''ö Noakhi ba ononia Lowalangi, imane khöra: Mi''o''ono ba mi''oya''ö ami, mifo''ösi guli danö![1]', '["Faigi 1:28"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 2, 'Ndramu''ata''ufi ami, yamuhokha mbu zaliŵa-liŵa ba danö fefu, awö wofo ba dalu mbanua fefu, awö zanana-nana ba danö fefu, ba awö gi''a ba nasi, fefu: barö mbawami tebe''e.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 3, 'Fefu zaliŵa-liŵa, si so noso, ba ömi: simane fame''egu bulu ndru''u andrö ube''e khömi, fefu.', '["MozIII 7:26; 17:14; HalZin 15:20"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 4, 'Ha nagole si so noso na bakha, si so donia na, ba lö tola mi''a.[2]', '["MozIII 7:26; 17:14; HalZin 15:20"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 5, 'Ba ulau mbalö ndromi; ba zaliŵa-liŵa ba danö fefu ulau, ba ba niha fefu, ulau mbalö noso niha, me no si fatalifusö; me no ibe''e famaedonia niha Lowalangi, wamazökhi ya''ia.[3]', '["MozII 21:12,28","Mat 26:52; Faigi 1:26"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 6, 'Na so zame''e aduwa ndro niha, ba niha zui zame''e aduwa ndronia, me no ibe''e famaedonia niha Lowalangi, wamazökhi yaia.[4]', '["MozII 21:12,28","Mat 26:52; Faigi 1:26"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 7, 'Ba ya''ami, ba mi''o''ono, mi''oya''ö ami; mi''aliŵa-liŵa ba guli danö ba mi''oya''ö ami ba detenia.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 8, 'Ba imane na Lowalangi khö Noakhi ba ba nononia, si so ba ngainia:', '["Yes 54:9"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 9, 'Hiza, fawu''u li ndra''odo khömi, ba ba ma''uwumi,[5]', '["Yes 54:9"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 10, 'ba ba zi so noso fefu, awömi, he fofo ba he urifömi andrö ba utu ndru''u fefu, si fao-fao khömi, fefu gofu hadia zaliŵa-liŵa ba danö, si oroi nowo andrö.', '["Yes 54:9"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 11, 'Fawu''usa li andrö khögu khömi: tenga sa''ae nihori hadia ia nifazökhi, ba nidanö andrö, si nönöi tanö, ba lö''ö sa''ae itörö fa''anönö danö, ba wamakiko uli danö.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 12, 'Ba imane Lowalangi: Da''ö dandra wawu''usa li andrö, fawu''usa li khögu khömi ba ba zi so noso fefu, awömi, ba nga''ötö fefu mitou.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 13, 'Dumi andrö khögu, ba ube''e ba lawuo, ena''ö tandra wawu''usa li ia ba gotaluama danö.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 14, 'Ba na so uhöna lawuo, yaŵa danö, ba na te''ila ndrumi andrö,', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 15, 'ba itörö tödögu wawu''usa li andrö, fawu''usa li khögu khömi ba ba zonoso fefu ba nösi guli danö ma''afefu; fa böi sa''ae anönö danö idanö andrö, ba wamakiko ösi guli danö fefu.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 16, 'Ba na no so ba lawuo ndrumi andrö, ba ufaigi ia, ena''ö itörö tödögu wawu''usa li andrö, si lö tebulö, nilau Lowalangi ba zonoso fefu ba nösi guli danö ma''afefu.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 17, 'Ba imane Lowalangi khö Noakhi: Ya da''ö dandra wawu''usa li andrö, fawu''usa li andrö khögu ba nösi guli danö fefu.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 18, 'Ba ono Noakhi si oroi nowo andrö, ba Semi ba Khamo ba Yafeti; ba Khamo andrö, ba ama Gana''ana andrö.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 19, 'Da''ö nono Noakhi si datölu andrö, ba ya''ira wurugö niha ba guli danö fefu.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 20, 'Ba ibörötaigö Noakhi ifazökhi kabu nagu, sangahalö ia.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 21, 'Ba me ibadu nagu, ba mabu ia, ba mörö-mörö tou ia ba nosenia, lö balu-balu zaila ia.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 22, 'Ba me i''ila Khamo andrö, ama Gana''ana, lö balu-balu namania, ba möi ia muŵa''ö khö ga''ania si darua andrö, baero.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 23, 'Ba lahalö mbaru sebua ira Semi Yafeti, la''angalisigö, la''erogö we''amöi khö namara ba labalugö zaila ia; noa sa la''erogö, fa böi la''ila zaila namara.', '[]', NULL),
  (3232367, 'OT', 'Moze I', 9, 24, 'Ba me tokea Noakhi, me döhö wemabunia ba me irongo nilau nononia si akhi andrö khönia, ba imane:', '["Faigi 12:8; MozII 3:14; Sanguhuk 1:28"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 25, 'Ni''elifi Gana''ana, ya sawuyu zawuyu ia ba khö ga''ania andrö!', '["Faigi 12:8; MozII 3:14; Sanguhuk 1:28"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 26, 'Ba imane na: Nisuno Yehowa Lowalangi Zemi, ba ya sawuyura Gana''ana![6]', '["Faigi 12:8; MozII 3:14; Sanguhuk 1:28"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 27, 'Yamufonaha sebolo Yafeti Lowalangi ba yamonahia [Yafeti] ba nose Zemi; ba sawuyura dania Gana''ana!', '["Faigi 12:8; MozII 3:14; Sanguhuk 1:28"]', NULL),
  (3232367, 'OT', 'Moze I', 9, 28, 'Ba 350 fakhe tö na Noakhi, me no aefa wa''anönö danö andrö, ba 950 fakhe wa''anau noso Noakhi fefu, ba mate ia.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 1, 'Da''e nga''ötö nono Noakhi andrö, Semi ba Khamo ba Yafeti; tumbu-tumbu khöra ndraono, me no aefa wa''atua danö andrö föna.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 2, 'Da''e nono Yafeti andrö: Gomeri ba Magogi ba Madai ba Yawano ba Tubalo ba Mesekhi ba Tirasi.[1]', '["Nga''ötI 1:5"]', NULL),
  (3234218, 'OT', 'Moze I', 10, 3, 'Ba ono Gomeri, ba Asekena ba Rifati ba Togarima.', '["Nga''ötI 1:5"]', NULL),
  (3234218, 'OT', 'Moze I', 10, 4, 'Ba ono Yawano, ba Elisa ba Tarisi ba mado Khiti andrö ba mado Rodani.', '["Nga''ötI 1:5"]', NULL),
  (3234218, 'OT', 'Moze I', 10, 5, 'Ba da''ö fabali zi so ba hulo andrö, niha baero.', '["Nga''ötI 1:5"]', NULL),
  (3234218, 'OT', 'Moze I', 10, 6, 'Ba ono Khamo, ba Kusi, ba Miserayi ba Futo ba Kana''ana.[2]', '["Nga''ötI 1:8"]', NULL),
  (3234218, 'OT', 'Moze I', 10, 7, 'Ba ono Gusi, ba Seba ba Hewila ba Sabata ba Ra''ema ba Sabitekha; ba ono Ra''ema, ba Sekheba ba Dedano.', '["Nga''ötI 1:8"]', NULL),
  (3234218, 'OT', 'Moze I', 10, 8, 'Ba ono Gusi ba Nimerodi; ba ibörötaigö sabölö da''ö ba guli danö.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 9, 'Sabölö ba wealu ia, tanö föna Yehowa; andrö wa lawa''öwa''ö: "Sabölö ba wealu, tanö föna Yehowa, si mane Nimerodi."', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 10, 'Böröta gamatöröŵania Mbabeli andrö ba Erekhi ba Akadi ba Kalene, ba danö Zineara.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 11, 'Ba da''ö i''otarai wanaŵa tanö Asuri, ba itaru''ö Niniwe andrö ba Rehoboti-Iri ba Kala,', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 12, 'ba Reseni andrö ba gotaluara Niniwe Gala — da''ö mbanua sebua andrö.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 13, 'Ba nga''ötö Miserayi andrö, ba mado Ludi ba mado Ganami ba mado Lehabi ba mado Nafetuhi,', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 14, 'ba mado Wateruzi ba mado Gaseluhi (böröta Ndrawa Wilisiti andrö) ba mado Gafetori.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 15, 'Ba ono Gana''ana, ba Sidona, ononia si a''a, ba Kheti;', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 16, 'ba nga''ötönia na Ndraono Yebusi andrö ba Iraono Gamori ba Iraono Girigasi,', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 17, 'ba Iraono Hewi ba Iraono Gariki ba Iraono Zini,', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 18, 'ba Iraono Gariwadi ba Iraono Zemari ba Iraono Hamata; ba si manö wa''afabali soi Ndrawa Gana''ana andrö.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 19, 'Ba tanö Ndrawa Gana''ana andrö, ba i''otarai Zidona ba numalö ba Gerara, irege Gasa, ba numalö ba Zodoma ba ba Gomora ba ba Gadama ba ba Zebo''i, irugi Laza.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 20, 'Da''ö ndraono Khamo, soira ba hadia ngawalö lira, tanöra andrö ba madora.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 21, 'Ba Semi andrö, furugö ndraono Heberi andrö fefu, ga''a Yafeti, ba mo''ono-ono göi.[3]', '["Nga''ötI 1:17"]', NULL),
  (3234218, 'OT', 'Moze I', 10, 22, 'Ono Zemi ba Elama ba Asuri ba Arafasa ba Ludi ba Aramo.', '["Nga''ötI 1:17"]', NULL),
  (3234218, 'OT', 'Moze I', 10, 23, 'Ba ono Garamo, ba Usi ba Huli ba Geteri ba Masi.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 24, 'Ba ono Garafasa, ba Sela, ba ono Zela, ba Heberi.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 25, 'Ba khö Heberi andrö, ba dombua nono matua; töi zi sambua, ba Felegi, me ba götönia fabali niha ba guli danö. Ba töi dalifusönia andrö, ba Yoketana.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 26, 'Ba ono Yoketana andrö, ba Alimodadi ba Salefi ba Hasamaweti ba Yara,', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 27, 'ba Hadoramo ba Usala ba Dikela,', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 28, 'ba Obala ba Abimaeli ba Seba ba Ofiri ba Hawila', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 29, 'ba Yobabi, oi ono Yoketana da''ö.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 30, 'Ba banuara, ba i''otarai Mesa, numalö ba Zefara, irege hili andrö, tanö ba gatumbukha luo.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 31, 'Da''ö nga''ötö Zemi andrö, soira andrö ba hadia ngawalö lira ba tanöra ba madora andrö.', '[]', NULL),
  (3234218, 'OT', 'Moze I', 10, 32, 'Da''ö nga''öto ndraono Noakhi, iwara andrö ba soira; ba ba khöra fabali soi andrö ba guli danö, me no aefa wa''atua danö andrö föna.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 1, 'Ba ha sambalö li niha ba guli danö fefu, ha sambua wehede.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 2, 'Ba me latöröi danö tanö ba gatumbukha luo, ba lasöndra ndraso ba danö Zineara, ba mowanua ira ba da''ö.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 3, 'Ba faoma lamane khö nawöra: Talabu, tafazökhi gara tembo ba tatunu! Ba kara khöra gara tembo andrö ba sulumou wamaböbö.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 4, 'Ba lamane: Talabu, tataru''ö khöda mbanua, awö malige, sirugi banua si yaŵa zuzu, ta''ebua''ö döida, fa böi muzaewe ita ba guli danö ma''asagörö.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 5, 'Ba möi tou Yehowa, ba wamaigi banua andrö, awö malige, nilau nono niha andrö.[1]', '["MozI 18:21"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 6, 'Ba imane Yehowa: Ha sambua soi ira ba ha sambalö lira, ba böröta wolaura da''ö, ba lö''ö [sa''ae] si tebai lalau, nikhoi dödöra.', '["MozI 18:21"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 7, 'Ba damöi ita tou ba tafakhöyö lira, fa böi sa''ae i''ila li nawönia zamösana!', '["MozI 18:21"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 8, 'Ba tobali ifazawili ira Yehowa ba zi manö, moroi ba da''ö, ifazaewe ira ba guli danö ma''asagörö, ba tobali tebai sa''ae lataru''ö mbanua andrö.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 9, 'Andrö wa labe''e töinia Mbabeli, me no ba da''ö ifakhöyö Yehowa li niha fefu, ba me ba da''ö i''oroi Yehowa, wamazawili ya''ira ba guli danö ma''asagörö.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 10, 'Da''e nga''ötö Zemi: Me no otu fakhe Zemi andrö, ba tumbu khönia Garafasa.[2]', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 11, 'Ba me no tumbu Garafasa, ha 500 fakhe tö na noso Zemi, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 12, 'Ba me no 35 fakhe Garafasa, ba tumbu khönia Zela.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 13, 'Ba me no tumbu Zela, ba 403 fakhe tö na noso Garafasa, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 14, 'Ba me no 30 fakhe Zela, ba tumbu khönia Heberi.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 15, 'Ba me no tumbu Heberi andrö, ba 403 fakhe tö na noso Zela, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 16, 'Ba me no 34 fakhe Heberi, ba tumbu khönia Welegi.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 17, 'Ba me no tumbu Welegi, ba 430 fakhe tö na noso Heberi, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 18, 'Ba me no 30 fakhe Welegi, ba tumbu khönia Reu.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 19, 'Ba me no tumbu Reu andrö, ba 209 fakhe tö na noso Welegi, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 20, 'Ba me no 32 fakhe Reu, ba tumbu khönia Zerugi.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 21, 'Ba me no tumbu Zerugi, ba 207 fakhe tö na noso Reu, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 22, 'Ba me no 30 fakhe Zerugi, ba tumbu khönia Nakhori.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 23, 'Ba me no tumbu Nakhori andrö, ba 200 fakhe tö na noso Zerugi, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 24, 'Ba meno 29 fakhe Nakhori, ba tumbu khönia Dara.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 25, 'Ba me no tumbu Dara andrö, ba 119 fakhe tö na noso Nakhori, ba tumbu-tumbu khönia ndraono, ono matua ba ono alawe.', '["Nga''ötI 1:17-27"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 26, 'Ba me no 70 fakhe Dara, ba tumbu khönia Gaberamo ba Nakhori ba Harana.[3]', '["Yos 24:2"]', NULL),
  (3404429, 'OT', 'Moze I', 11, 27, 'Ba da''e nga''ötö Dara andrö: Ono Dara, ba Aberamo ba Nakhori ba Harana.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 28, 'Ba ono Harana Loti andrö. Ba si mate föna namania Tara Harana andrö, ba mbanuara andrö, ba Guri ba Galedaia.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 29, 'Ba mangowalu ndra Aberamo Nakhori; töi wo''omo Gaberamo, ba Sara''i, ba töi wo''omo Nakhori, ba Milika, ono Harana andrö, ama ndra Milika Yisika.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 30, 'Ba si lö mo''ono Zara''i andrö.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 31, 'Ba i''ohe nononia Aberamo Tara, awö Loti, ono nononia Harana andrö, awö numönönia Sara''i andrö, fo''omo nononia Aberamo, aheta ira ba Guri ba Galedaia, ba wanaŵa tanö Gana''ana. Ba larugi Harana, ba ahono ira ba da''ö.', '[]', NULL),
  (3404429, 'OT', 'Moze I', 11, 32, 'Ba fa''anau noso Dara, ba 205 fakhe; ba mate Dara ba Harana.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 1, 'Ba imane Yehowa khö Gaberamo: Heta''ö ba danömi ba ba dalifusöu ba ba nomo namau, ba ae ba danö ni''oroma''ögu khöu dania.[1]', '["MozI 15:7; Yos 24:3; Mat 19:29; HalZin 7:3; Heb 11:8","Faigi 22:18; 26:4; HalZin 3:25; Gal 3:8"]', NULL),
  (3437897, 'OT', 'Moze I', 12, 2, 'Ba ubali''ö soi sebua ndra''ugö, ba ufahowu''ö ndra''ugö ba u''ebua''ö döimö ba to bali howu-howu ndra''ugö.', '["MozI 15:7; Yos 24:3; Mat 19:29; HalZin 7:3; Heb 11:8","Faigi 22:18; 26:4; HalZin 3:25; Gal 3:8"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3437897, 'OT', 'Moze I', 12, 3, 'ufahowu''ö zamahowu''ö ya''ugö, ba sangelifi ya''ugö, ba u''elifi göi, ba moroi khöu tefahowu''ö dania fefu soi ba guli danö.[2]', '["MozI 15:7; Yos 24:3; Mat 19:29; HalZin 7:3; Heb 11:8","Faigi 22:18; 26:4; HalZin 3:25; Gal 3:8"]', NULL),
  (3437897, 'OT', 'Moze I', 12, 4, 'Ba awu''a Gaberamo, i''o''ö niŵa''ö Yehowa khönia, ba fao khönia Loti. Ba no 75 fakhe Geberamo, me aheta ia ba Harana.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 5, 'Ba i''ohe wo''omonia Sara''i Aberamo, awö Loti, ono dalifusönia, awö nibaya-bayara fefu, si so khöra, awö niha andrö (sangai halöŵö) nisöndrara ba Harana, ba laheta ira, ba we''amöi ba danö Gana''ana, ba larugi danö Gana''ana.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 6, 'Ba itöröi danö andrö Aberamo, irugi mbanua Zikhema, irugi gatua More; ba me luo da''ö, ba Dawa Gana''ana zi so ba danö.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 7, 'Ba i''oroma''ö ia khö Gaberamo Yehowa, imane khönia: Ba ma''uwumö ube''e danö andre! Ba ifa''anö naha wame''e sumange ba da''ö khö Yehowa, si no mangoroma''ö ya''ia khönia.[3]', '["Faigi 13:15; 15:18; MozV 34:4"]', NULL),
  (3437897, 'OT', 'Moze I', 12, 8, 'Ba ifa''ese ia föna, isaŵa hili tanö ba gatumbukha luo, i''otarai Mbetieli, ba da''ö itaru''ö nosenia, tobali tanö ba gaekhula Mbetieli ba tanö ba gatumbukha Ga''i, i''otarai zi so ia. Ba ifa''anö ba da''ö naha wame''e sumange khö Yehowa ba i''angaröfi li Yehowa.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 9, 'Aefa da''ö, ba idou''ö-dou''ö ia Aberamo miraya.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 10, 'Ba itörö lofo danö andrö. Ba möi misi tou ba danö Miserayi Gaberamo, ba we''aso ba da''ö ma''ifu; noa sa abölö-bölö lofo ba danö.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 11, 'Ba me no ahatö ira ba danö Miserayi, ba imane Aberamo khö wo''omonia Sara''i: Hiza, u''ila, wa no ira alawe si sökhi bawa ndra''ugö.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 12, 'Ba na la''ila''ö dania Dawa Miserayi, ba lamane dania: Fo''omonia! ba labunu ndra''o, ba la''orifi ndra''ugö.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 13, 'U''andrö khöu, öŵa''ö dania, akhigu ndra''ugö, ena''ö ohahau dödögu, börö ndra''ugö, fa aurido, börö ndra''ugö.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 14, 'Ba me no irugi danö Miserayi Aberamo, ba la''ila Dawa Miserayi, wa no si sökhi sibai ndra alawe andrö.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 15, 'Ba me no la''ila ia kumandru sebua andrö khö Wara''o ba lasuno ia khö Wara''o, ba te''ohe ba gödo Wara''o ndra alawe andrö.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 16, 'Ba oböwö Wara''o khö Gaberamo, börö ndra alawe, ba isöndra Aberamo mbiri-biri ba saŵi ba kalide ba sawuyu ono matua ba sawuyu ono alawe ba kalide si alawe ba ondra.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 17, 'Ba ifatörö wamakao sebua Yehowa khö Wara''o ba ba zoroiyomonia, börö Zara''i, fo''omo Gaberamo.', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 18, 'Ba ifakaoni''ö Gaberamo Fara''o, imane: Hana wa ölau khögu da''ö? Hana wa lö öŵa''ö khögu, wa fo''omou?', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 19, 'Hana wa öŵa''ö: akhigu, fa tobali uhalö ia fo''omogu? Ba iada''e, ba hiza wo''omou, ohe ia ba fuli''ö!', '[]', NULL),
  (3437897, 'OT', 'Moze I', 12, 20, 'Ba iŵa''ö niha Fara''o, khönia, ena''ö möi ira awöra ba lala, ba fao wo''omonia, awö fefu hadia ia khönia.', '[]', NULL),
  (3438338, 'OT', 'Moze I', 13, 1, 'Ba möi miyaŵa Gaberamo, moroi ba danö Miserayi, awö wo''omonia, awö fefu hadia ia khönia, ba fao khönia göi Loti, lasaŵa danö si raya no.', '["Faigi 12:8"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 2, 'Ba no ebua sibai gokhöta Gaberamo, he urifö ba he firö ba he ana''a.', '["Faigi 12:8"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 3, 'Ba itohu-tohugö wofanönia, iheta ia si raya, isaŵa Mbetieli, irege zi so osenia no, ba gotaluara Mbetieli Ga''i,[1]', '["Faigi 12:8"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 4, 'irege zi so naha wame''e sumange no, nifa''anönia ba da''ö föna. Ba i''angaröfi li döi Yehowa Aberamo ba da''ö.', '["Faigi 12:8"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 5, 'Ba khö Loti göi, si fao khö Gaberamo, ba so mbiri-biri ba saŵi ba ose.', '["Faigi 36:7"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 6, 'Ba tebai itaha ira tanö, fa orudu-rudu manö ira mena''ö, me no oya sibai guriföra, tebai orudu manö ira.[2]', '["Faigi 36:7"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 7, 'Ba tobali fasoso-soso ira gubalo gurifö Gaberamo gubalo gurifö Loti. Ba so na göi Ndrawa Gana''ana ba danö ba Dawa Weresi, me luo da''ö.', '[]', NULL),
  (3438338, 'OT', 'Moze I', 13, 8, 'Ba imane Aberamo khö Loti: Böi fasoso ita, ba böi fasoso ira gubalo khögu gubalo khöu, noa sa si fatalifusö ita.', '[]', NULL),
  (3438338, 'OT', 'Moze I', 13, 9, 'Tenga no so fönau danö ma''afefu. Sökhi na öheta''ö khögu; na ba gabera zomasi''ö, ba ba gambölö möi ndra''o, ba na ba gambölö öŵa''ö, ba ba gabera ndra''o.', '[]', NULL),
  (3438338, 'OT', 'Moze I', 13, 10, 'Ba ifaöga hörönia Loti, ba i''ila, tanö si lö ambö-ambö idanö ndraso Yoridano andrö ma''asagörö, me lö''ö na nidudugö Lowalangi Sodoma ba Gomora andrö, ba hulö kabu Yehowa, si mane tanö Miserayi, irugi Zoara andrö.', '[]', NULL),
  (3438338, 'OT', 'Moze I', 13, 11, 'Ba ituyu khönia ndraso Yoridano andrö ma''asagörö Loti, ba maoso ia, isaŵa gatumbukha luo, ba tobali fabali ira.', '[]', NULL),
  (3438338, 'OT', 'Moze I', 13, 12, 'Ba danö Gana''ana so Gaberamo, ba Loti, ba ba mbanua ba ndraso i''iagö, ba ifa''eze-eze nosenia, irugi Zodoma.', '[]', NULL),
  (3438338, 'OT', 'Moze I', 13, 13, 'Ba si lö sökhi mbanua Zodoma andrö, fahöna horöra khö Yehowa.', '[]', NULL),
  (3438338, 'OT', 'Moze I', 13, 14, 'Ba imane Yehowa khö Gaberahamo, me no fabali Loti khönia: Faöga höröu ba faigi danö andrö fefu, i''otarai zi so''ö, miyöu ba miraya ba tanö ba gatumbukha ba tanö ba gaekhula.', '["Faigi 12:7","Faigi 15:5; 22:17; Heb 11:12"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 15, 'Fefu danö andrö sa, ni''ilau, ba khöu ba ba ma''uwumö ube''e, si lö tebulö.[3]', '["Faigi 12:7","Faigi 15:5; 22:17; Heb 11:12"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 16, 'Ba u''oya''ö ma''uwumö, irege fa''oya ngawua nene ba danö, fa tebai la''erai ma''uwumö, si mane fa''atebai wangerai ngawua nene ba danö.[4]', '["Faigi 12:7","Faigi 15:5; 22:17; Heb 11:12"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 17, 'Faoso ba töröi danö, fa''anau ba fa''ebolo, khöu sa ube''e ia, tana khöu.', '["Faigi 12:7","Faigi 15:5; 22:17; Heb 11:12"]', NULL),
  (3438338, 'OT', 'Moze I', 13, 18, 'Ba ifa''ese nosenia Aberamo, irugi gatua Mamere ba tebato ia ba da''ö, ba Heberona andrö, ba ifa''anö naha wame''e sumange khö Yehowa.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 1, 'Ba me luo Garambeli, razo Zineara, ba maoso Gariokhi, razo Gelasara ba Kedoro La''omoro, razo Gelama ba Tidala, razo niha baero, lasuwö Mbera,', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 2, 'razo Zodoma ba Birisa, razo Gomora ba Sinaba, razo Gadama, ba Semeberi, razo Zebo''i ba razo Mbela, ya''ia Zo''ara andrö.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 3, 'Da''ö fefu zorudu we''amöi ba ndraso Sidi andrö, ya''ia zilua asi sasi-asi ma''ökhö.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 4, 'No mewelendrua fakhe ira barö mbawa Kedoro La''omoro andrö ba me aefa da''ö, ba laheta ira banuania.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 5, 'Ba me no alua meweledölu fakhe, ba so Kedoro La''omoro, ba razo andrö, si möi awönia, ba la''alani mado Refa''i andrö ba Gasaroto Karanai, awö mado Zusi ba Hama, awö mado Gemi, ba ndraso ba Giriata''i,[1],', '["MozV 2:10 b.t."]', NULL),
  (3438581, 'OT', 'Moze I', 14, 6, 'ba mado Hori ba hili Ze''ira andrö khöra, irugi Geli Farana, tanö ba gatumbukha luo, i''otarai danö si mate andrö.', '["MozV 2:10 b.t."]', NULL),
  (3438581, 'OT', 'Moze I', 14, 7, 'Ba lafuli ira furi ba larugi Geni Misefa, ya''ia Kadesi, ba lasuwö danö Ndraono Gamaleki ma''asagörö, awö Ndraono Gamori ba Hazaso Tamara.', '["MozV 2:10 b.t."]', NULL),
  (3438581, 'OT', 'Moze I', 14, 8, 'Ba maoso razo Zodoma ba razo Gomora ba razo Gadama ba razo Zebo''i ba razo Mbela, ya''ia Zoara andrö, lafa''anö ira ba wolau khöra ba zalo''o ba Zidi,', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 9, 'ba wolau khö Kedoro La''omoro andrö, razo Gelama, ba khö Didala, razo niha baero, ba khö Garambeli, razo Zineara, ba khö Gariokhi, razo Gelasara — daöfa razo udu zi dalima.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 10, 'Ba ba ndraso Sidi andrö, ba no fahöna manö dögi zulumou. Ba me no tetimba furi razo Zodoma ba razo Gomora, ba ahöndrö ira ba da''ö, ba si tosai, ba moloi, lasaŵa hili.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 11, 'Ba ahori lahalö nibaya-baya ba Zodoma ba ba Gomora ba balazora fefu, ba mofanö.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 12, 'Ba la''oloi''ö göi Loti andrö, ono dalifusö Gaberamo, si no fatewu ba Zodoma, awö nibaya-bayania, ba mofanö.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 13, 'Ba so zoloi, ba i''ombakha''ö khö Gaberamo andrö, mado Heberaio; ba gatua Ndraono Gamori Mamere, talifusö ndra Esikoli Aneri, so da''ö, ba si fa''awö khö Gaberamo da''ö no mege.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 14, 'Ba me irongo Gaberamo, no lara''u dana nononia andrö ba no la''oloi''ö, ba ifa''anö niha andrö khönia, si no faduhu dödönia, si tumbu baomonia [sawuyu], 318, ba igohi zanuwö andrö, irege Dano.[2]', '["SamII 24:6"]', NULL),
  (3438581, 'OT', 'Moze I', 14, 15, 'Ba ibarigö niha andrö khönia ba lahawui zanuwö, ba zi bongi, ba te''ala labe''e ba lagohi, irege Hoba, yöu Ndramaseko.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 16, 'Ba i''ohe mangawuli [Aberamo] fefu nibaya-baya, ba he Loti göi, tana nononia, awö nibaya-bayania, i''ohe mangawuli, awö ndra alawe, awö niha sato ni''oloi''ö.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 17, 'Ba no te''ala Kedoro La''omoro andrö, awö razo andrö si fao khönia, ibe''e Aberamo, ba ifuli ia, ba ifaondragö ia razo Zodoma ba ndraso Zawe, ya''ia ndraso razo andrö.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 18, 'Ba i''ohe baero roti ba agu Melekhisede, razo Zalema, ere Lowalangi Fondrege Zalaŵa da''ö.[3]', '["Sin 110:4; Heb 5:6; 6:20; 7:1 b.t.","MozIV 18:21"]', NULL),
  (3438581, 'OT', 'Moze I', 14, 19, 'Ba ifahowu''ö Gaberamo, imane: Ya''ifahowu''ö Gaberamo Lowalangi Fondrege Zalaŵa, samazökhi banua si yaŵa, awö danö!', '["Sin 110:4; Heb 5:6; 6:20; 7:1 b.t.","MozIV 18:21"]', NULL),
  (3438581, 'OT', 'Moze I', 14, 20, 'Ba nisuno Lowalangi Fondrege Zalaŵa, si no mame''e ba dangau emaliu. Ba ibe''e khönia Aberamo zambua ni''ofulu fefu hadia ia.[4]', '["Sin 110:4; Heb 5:6; 6:20; 7:1 b.t.","MozIV 18:21"]', NULL),
  (3438581, 'OT', 'Moze I', 14, 21, 'Ba imane razo Zodoma khö Gaberamo: Niha andrö be''e khögu, ba nibaya-baya andrö, ba halö khöu.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 22, 'Ba imane Aberamo khö razo Zodoma: ufazaŵa dangagu khö Yehowa, Lowalangi Fondrege Zalaŵa, samazökhi banua si yaŵa, awö danö:', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 23, 'Sara bana fanagu ba sara böbö mbadagahe ba hadia ia fefu zi so khöu, ba lö uhalö, fa böi öŵa''ö, no öfo''ana''a Gaberamo.', '[]', NULL),
  (3438581, 'OT', 'Moze I', 14, 24, 'Alakha lö khögu! Ha ni''a nono matua andrö ba tana ba niha andrö, si no möi awögu, Aneri ba Esikoli ba Mamere — akha mo''urakha ira!', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 1, 'Ba me no aefa da''ö no mege, ba humede Yehowa khö Gaberamo, ba gangilata, imane: Böi ata''u ndra''ugö, Aberamo; baluseu ndra''o, luou, ba börö zebua.[1]', '["Sin 19:12; Yes 41:10; 43:1"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 2, 'Ba imane Aberamo: He So''aya Yehowa, hadia nibe''eu khögu? mowaö-waö manö ndra''o ba lö onogu, ba sanema ondröitagu dania, ba Eliezeri andrö, banua Ndramaseko.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 3, 'Ba imane na Aberamo: Lö''ö sa nibe''eu khögu nga''ötö, ba tobali sanema ondröitagu, ba sawuyu baomogu.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 4, 'Ba humede khönia Yehowa, imane: Tenga sanema ondröitamö da''ö, si otarai nösiu dania, da''ö zanema ondröitamö.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 5, 'Ba i''ohe ia baero baewali ba imane: Faigi mbanua si yaŵa ba erai ndröfi; hadia, ö''ila maö ö''erai? Ba imane na khönia: Si manö [wa''oya] ma''uwumö dania.[2]', '["MozI 13:16"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 6, 'Ba faduhu dödönia khö Yehowa, ba ibe''e fa''atulö dödönia da''ö Yehowa.[3]', '["Rom 4:3; Gal 3:6; Yak 2:23"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 7, 'Ba imane khönia: Yehowa ndra''odo si no mangeheta ya''ugö ba Guri, ba Galedaia, ba wame''e tana khöu tanö da''e.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 8, 'Ba imane: He So''aya, Yehowa! heza oroma khögu, wa okhötagu dania?', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 9, 'Ba imane khönia Yehowa: Halö khögu zaŵi si no medölu fakhe ba nambi si medölu fakhe ba si matua mbiri-biri si medölu fakhe ba sambua wune ba sambua nono marafadi.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 10, 'Ba ihalö khönia da''ö fefu ba idozigö ibago dalu ba ifatahö zi tamba-tambai; ba fofo andrö, ba lö isila.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 11, 'Ba aekhu moyo ba nagole andrö; ba itaboi ira Aberamo.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 12, 'Ba me aekhu-aekhu luo, ba ihawui Gaberamo femörö sabölö ba fa''ata''u; ihawui ia fa''ogömi-gömi sabe''e.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 13, 'Ba imane [Yehowa] khö Gaberamo: Böi zi lö örongo, wa si fatewu ba danö si tenga tanöra ma''uwumö dania ba sawuyu ira ba da''ö ba lafakao sibai ira niha andrö, öfa ngaotu fakhe wa''ara.[4]', '["MozII 1:13; 12:40; HalZin 7:6","MozII 11:2; 12:35,36","Faigi 25:8","MozV 9:4"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 14, 'Ba soi andrö göi, si möi ira sawuyu, ba uhuku, ba awena dania aefa ira, ebua la''ohe ana''a.[5]', '["MozII 1:13; 12:40; HalZin 7:6","MozII 11:2; 12:35,36","Faigi 25:8","MozV 9:4"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 15, 'Ba ya''ugö, ba sohahau tödö, irege orudu''ö khö ndra tuau; ba wa''atua omasiö teko''o ndra''ugö.[6]', '["MozII 1:13; 12:40; HalZin 7:6","MozII 11:2; 12:35,36","Faigi 25:8","MozV 9:4"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 16, 'Ba öfa nga''ötöra, ba mangawuli ira ba da''e; lö''ö na sa afönu zu''a-su''a horö Ndraono Gamori.[7]', '["MozII 1:13; 12:40; HalZin 7:6","MozII 11:2; 12:35,36","Faigi 25:8","MozV 9:4"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 17, 'Ba me no aekhu luo, me no ogömi-gömi sibai, ba so zimbo, hulö zimbo zino wa''u ba sulu, sanörö nisila no mege.', '[]', NULL),
  (3438654, 'OT', 'Moze I', 15, 18, 'Me luo da''ö fawu''u li Yehowa khö Gaberamo, imane: Ba ma''uwumö ube''e danö andre, i''otarai nidanö Miserayi andrö, irugi nidanö sebua andrö, Oiferati,[8]', '["Faigi 12:7; RazI 4:21; Nga''ötII 9:26),","MozV 7:1"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 19, 'tanö Ndraono Geni ba tanö Ndraono Genisi ba tanö Ndraono Gadamoni,[9]', '["Faigi 12:7; RazI 4:21; Nga''ötII 9:26),","MozV 7:1"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 20, 'ba tanö Ndraono Kheti ba tanö Ndraono Weresi ba tanö Ndraono Refati ba', '["Faigi 12:7; RazI 4:21; Nga''ötII 9:26),","MozV 7:1"]', NULL),
  (3438654, 'OT', 'Moze I', 15, 21, 'tanö Ndraono Gamori ba tanö Ndrawa Gana''ana ba tanö Ndraono Girigasi ba tanö Ndraono Yebusi.', '["Faigi 12:7; RazI 4:21; Nga''ötII 9:26),","MozV 7:1"]', NULL),
  (3438921, 'OT', 'Moze I', 16, 1, 'Ba lö so''ono Gaberamo, khö wo''omonia Sara''i andrö; ba so khönia zawuyu, ono alawe, Dawa Miserayi, Hagara döi.', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 2, 'Ba imane Sara''i khö Gaberamo: Me lö''ö sa nibe''e Yehowa khögu ono, ba hana na orudu ndra''ugö khö zawuyugu yomo andrö, ma falukhado nono khönia!', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 3, 'Ba ihalö zawuyunia yomo andrö, Hagara, Dawa Miserayi, Sara''i, fo''omo Gaberamo, ba ibe''e donga wo''omonia Aberamo, me no mewulu fakhe Gaberamo ba danö Gana''ana.', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 4, 'Ba orudu ia khö Hagara andrö, ba manabina. Ba me i''ila, no manabina ia, ba lö ba dödönia sa''ae sokhö ya''ia.', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 5, 'Ba imane Sara''i khö Gaberamo: Horöu wa falukhado wango''aya. Ya''odo zolulu khöu sawuyugu yomo andrö, ba iya''e, me i''ila no manabina ia, ba lö''ö sa''ae ba dödönia ya''odo. Yamufaigi lala khöda Yehowa.', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 6, 'Ba imane Aberamo khö Zara''i: Ba dangau atö so zawuyumö; si so ba dödöu lau khönia!', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 7, 'Ba falukha khönia mala''ika Yehowa, ba zinga gumbu ba danö si mate, umbu ba ngai lala ba Zuri.', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 8, 'Ba imane: He Hagara, sawuyu Zara''i! he ö''otarai ba heza moi''ö?', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 9, 'Ba imane khönia mala''ika Yehowa andrö: Fuli''ö khö zokhö ya''ugö andrö, ba o''ö niŵa''önia.', '["Faigi 21:20; Yob 39:5–8"]', NULL),
  (3438921, 'OT', 'Moze I', 16, 10, 'Ba imane na khönia mala''ika Yehowa andrö: Oya sibai ma''uwumö dania ube''e, irege tebai te''erai wa''oya.', '["Faigi 21:20; Yob 39:5–8"]', NULL),
  (3438921, 'OT', 'Moze I', 16, 11, 'Ba imane na khönia mala''ika Yehowa andrö: Si no manabina ndra''ugö ba tumbu dania khöu nono matua, ba öbe''e töinia Zima''eli, me no ifondrondrongo [wangarö-ngaröu ba] wamakaomö andrö Yehowa.', '["Faigi 21:20; Yob 39:5–8"]', NULL),
  (3438921, 'OT', 'Moze I', 16, 12, 'Ba ya''ia andrö, ba niha si hulö galide gatua — dozi niha bö''ö fa''udu ia, ba si fa''udu khönia zui niha bö''ö fefu — ba ihöndrögö dania fefu zahatö khönia.[1]', '["Faigi 21:20; Yob 39:5–8"]', NULL),
  (3438921, 'OT', 'Moze I', 16, 13, 'Ba ibe''e töi Yehowa andrö, sihede khönia: "Lowalangi soroma ndra''ugö!" Imane sa: Hadia, noa göi anehedo zamaigi-maigi ya''odo andrö?[2]', '["Sanguhuk 13:22"]', NULL),
  (3438921, 'OT', 'Moze I', 16, 14, 'Andrö wa labe''e töi gumbu andrö: "umbu zauri andrö, samaigi ya''odo"; ba gotaluara Gadesi Mbaredi so.', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 15, 'Ba mo''ono Hagara khö Gaberamo, ono matua. Ba Sima''eli ibe''e töi nono andrö Aberamo, töi nono andrö si no tumbu khönia khö Hagara.', '[]', NULL),
  (3438921, 'OT', 'Moze I', 16, 16, 'Ba ŵalu ngafulu a önö fakhe Gaberamo, me tumbu khönia Zima''eli andrö, khö Hagara.', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 1, 'Ba me no 99 fakhe Gaberamo, ba i''oroma''ö ia Yehowa khö Gaberamo, imane khönia: Lowalangi si lö ambö fa''abölö ndra''o, fönagu törö lalau ba ya''atulö ndra''ugö,[1]', '["Faigi 24:40"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 2, 'ba fawu''u li ita, ba oya sibai dania ma''uwumö ube''e.', '["Faigi 24:40"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 3, 'Ba ifalögu tou ia Aberamo, ba humede khönia Lowalangi, imane:', '["Rom 4:17","Faigi 35:11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3438925, 'OT', 'Moze I', 17, 4, 'Ya''odo zi no fawu''u li khöu, wa furugö ŵalo soi ndra''ugö dania.', '["Rom 4:17","Faigi 35:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 5, 'Ba böi sa''ae Aberamo döimö, Aberahamo döiu sa''ae. Furugö ŵalo soi sa ube''e ndra''ugö. [2]', '["Rom 4:17","Faigi 35:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 6, 'Ba ato sibai dania ma''uwumö ube''e, tobali mosoi dania ira, razo na''i dania ösa ma''uwumö.[3]', '["Rom 4:17","Faigi 35:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 7, 'Ba fawu''u li ndra''o khöu ba ba ma''uwumö furiu, ba nga''ötöra andrö, fawu''usa li si lö tebulö, irugi zi lö aetu, fa Lowalangiu ndra''odo ba Lowalangi ma''uwumö furiu.', '["Rom 4:17","Faigi 35:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 8, 'Ba khöu ba ba ma''uwumö furiu ube''e danö andre, ba zi so''ö si fatewu iada''e, tanö Gana''ana ma''asagörö, ube''e okhötami si lö tebulö, ba Lowalangira ndra''odo.', '["Rom 4:17","Faigi 35:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 9, 'Ba imane Lowalangi khö Gaberahamo: Ba ya''ugö, böi böhöli wawu''usa li andrö khögu, ya''ugö andre ba ma''uwumö furiu, ba nga''ötöra andrö.', '["Rom 4:17","Faigi 35:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 10, 'Da''ö wawu''usa li si lö tola miböhöli, fawu''usa li khögu khömi ba ba ma''uwumö furiu: fefu motöi matua ba khömi, ba niboto.', '["Rom 4:11; HalZin 7:8","MozIII 12:3"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 11, 'uli khömi niboto ba ya da''ö dandra wawu''usa li khöda.[4]', '["Rom 4:11; HalZin 7:8","MozIII 12:3"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 12, 'Na no fitu bongi wa''ebua, ba niboto fefu motöi matua ba khömi, ha uga nga''ötömi, he si tumbu yomo ba he nihöli ba niha bö''ö, si tenga ya''ami.[5]', '["Rom 4:11; HalZin 7:8","MozIII 12:3"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 13, 'Niboto zi tumbu baomou ba he nihöliu ana''a, ena''ö tobali oroma ba nösimi wawu''usa li andrö khögu, fawu''usa li sirugi si lö aetu.', '["Rom 4:11; HalZin 7:8","MozIII 12:3"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 14, 'Ba niha si lö muboto, si lö muboto uli — ba nihori ba niwania zi manö, no adudu wawu''usa li andrö khögu, ibe''e.', '["Rom 4:11; HalZin 7:8","MozIII 12:3"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 15, 'Ba imane na Lowalangi khö Gaberahamo: Böi sa''ae be''e töi wo''omou Sara''i andrö Zara''i; Sara sa''ae döinia.', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 16, 'Ba ufahowu''ö ia ba ube''e bualagu khöu nono matua, khönia, ufahowu''ö ia ba ya awe soi ia dania; samatörö soi niha dania ma''uwunia ösa.', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 17, 'Ba ifalögu tou ia Aberahamo ba ma''iki, imane sa dödönia: Hadia, mo''ono maö zi zi no 100 fakhe fa''atua, ba mo''ono Zara, si no 90 fakhe?', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 18, 'Ba imane Aberahamo khö Lowalangi: Ena''ö na auri manö Zima''eli andrö fönau!', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 19, 'Ba imane Lowalangi: Böi! Fo''omou Sara andrö zo''ono khöu ono matua, ba öbe''e töi nono andrö Giza''aki, ba fawu''u li ndra''odo khönia, fawu''usa li sirugi si lö aetu, khö ma''uwuna furinia.[6]', '["Faigi 18:10; 21:2; Gal 4:23; Heb 11:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 20, 'Ba he ba khö Zima''eli andrö, ba ufondrondrongo göi wangandröu; ufahowu''ö ia ba ufonga''ötö ia, oya sibai ma''uwunia, ube''e. Felendrua zalaŵa nga''ötönia dania, ba soi sebua ma''uwunia ube''e.', '["Faigi 18:10; 21:2; Gal 4:23; Heb 11:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 21, 'Ba fawu''usa li andrö khögu, ba khö Giza''aki andrö utandrösaigö, si tumbu dania khöu, khö Zara, mane furi.', '["Faigi 18:10; 21:2; Gal 4:23; Heb 11:11"]', NULL),
  (3438925, 'OT', 'Moze I', 17, 22, 'Ba me no awai huhuo Lowalangi khönia, ba numalö miyaŵa ia, iröi Gaberahamo.', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 23, 'Ba ihalö nononia Sima''eli Aberahamo, awö dozi si no tumbu baomonia ba dozi nihölinia ana''a, fefu motöi matua ba zi so yomo khö Gaberahamo, ba iboto gulira, me luo da''ö, i''o''ö niŵa''ö Lowalangi khönia.', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 24, 'Ba no 99 fakhe Gaberahamo, me teboto gulinia.', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 25, 'Ba 13 fakhe Zima''eli, me teboto gulinia.', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 26, 'Ba me luo da''ö, ba teboto Gaberahamo ba ononia Sima''eli; ba si so yomo khönia fefu,', '[]', NULL),
  (3438925, 'OT', 'Moze I', 17, 27, 'he si tumbu baomonia, ba he nihölinia ana''a ba niha bö''ö, ba teboto awönia.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 1, 'Ba i''oroma''ö ia khönia Yehowa, ba gatua Mamere andrö, me dumadao ia ba mbawandruhö nose, me hino wa''aukhu zino.', '["Heb 13:2"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 2, 'Me ifaöga hörönia, ba hiza niha, datölu, si so fönania; ba me i''ila ira, ba fagohi ia, i''oroi mbawandruhö nose, ifaondragö ira, ba ifaöndrö ia, irege danö tou.[1]', '["Heb 13:2"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 3, 'Ba imane: He Tuha, na no atö falukhado ma''ifu wa''ebua dödöu, wamaigiu, ba böi atö talu''i zawuyumö andre!', '["Heb 13:2"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 4, 'Dalabe''e nidanö ma''ifu, ena''ö misasai gahemi; ba midadao ba lumö geu andre,', '["Heb 13:2"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 5, 'ba da''uhalö khömi zambawa kue, ena''ö mi''abe''e''ö ami, ba dania, ba hana na mitohugö wofanö. Andrö sa mitörö zawuyumi andre.', '["Heb 13:2"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 6, 'Ba fagohi Gaberahamo, isaŵa nose, khö Zara, imane: Ta''i-ta''i, halö hamo, tölu hinaoya, faruka ba fazökhi kue!', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 7, 'Ba idölö ia ba zaŵi Aberahamo, ihalö nono zaŵi sawuyu-wuyu ba ibe''e ba danga zangai halöŵö ba i''aliogö da''ö wangasosoi.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 8, 'Ba ihalö matega ba susu Aberahamo ba saŵi andrö, ni''asiwainia, ba ifa''oli göra; ba ya''ia zangai-ngai hadia zoguna khöra, ba da''ö, ba lumö geu, me manga ira.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 9, 'Ba lamane khönia: Heza so wo''omou Sara?', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 10, 'Ba imane: ufulido khöu, ba ndröfia, mane furi, ba no so nono khö wo''omou Sara.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 11, 'Ba Aberahamo ba Sara, ba no satua sa''ae, no numalö ndröfi, ba khö Zara, ba tenga sa''ae si mane ba ndra alawe bö''ö.', '["RazII 4:16; Rom 9:9; Heb 11:11","FetI 3:6"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 12, 'Ba ma''iki Zara tödönia, imane dödönia: Hadia, me no saleu ndra''odo, ba hadia, somasi ira matua na ndra''o? ba no satua atö göi wo''omogu,[3]', '["RazII 4:16; Rom 9:9; Heb 11:11","FetI 3:6"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 13, 'Ba imane Yehowa khö Gaberahamo: Hadia atö, wa ma''iki Zara, ba hana wa imane dödönia: Hadia si ndruhu tola so''ono ndra''o, me no satua ndra''odo?', '["Luk 1:37"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 14, 'Hadia, so hadia zi tebai khö Yehowa? Na mane furi, ba ndröfia, ba ufulido khöu, ba no so nono khö Zara![4]', '["Luk 1:37"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 15, 'Ba i''osilö''ögö Sara, imane: Lö sa''ikido; Ata''u sa''ae ia.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 16, 'Ba maoso niha andrö, mangefa ira ba da''ö, ba lafaigi mitou Zodoma — ba fao khöra Gaberahamo, awöra ba lala.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 17, 'Ba imane Yehowa: Hadia, ubini''ö khö Gaberahamo zadölö ulau?[5]', '["Amos 3:7","Faigi 12:2"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 18, 'Ba soi sebua, sato sibai, sa atö dania nga''ötö Gaberahamo, ba moroi khönia, wa tefahowu''ö fefu soi ba guli danö[6]', '["Amos 3:7","Faigi 12:2"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 19, 'Noa sa utuyu ia, ena''ö iŵa''ö khö nononia ba ba zoroiyomonia fefu, furinia, wanörö lala andrö khö Yehowa, wolau sadölö ba satulö, ena''ö ifatörö khö Gaberahamo, nifabu''unia khönia.', '["Amos 3:7","Faigi 12:2"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 20, 'Ba imane Yehowa: Turia Zodoma ba turia Gomora andrö, ba no ebua; ba horöra, ba si ndruhu, ba sebua sibai![7]', '["Hes 16:49,50"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 21, 'Andrö möido mitou, ba wamaigi, na duhu dozi zolau da''ö, si mane duriara andrö, si no terongo khögu, ba na faya; omasido u''ila!', '["Hes 16:49,50"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 22, 'Ba mofanö niha andrö, lasaŵa Zodoma, ba tebato na ba da''ö Gaberahamo, khö Yehowa.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 23, 'Ba ihatö''ö ia Aberahamo, ba imane: Hadia, öfarahugö wamakiko si lö horö, awö zi so horö?', '["Rom 3:6"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 24, 'Ma dania lima wulu zi lö horö, ba mbanua andrö? Hadia, öfakiko da''ö göi, ba lö''ö sa öhakhösi tödö mbanua andrö, börö zi lima wulu andrö, si lö horö, si so ba mbanua bakha?', '["Rom 3:6"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 25, 'Ya''aröu khöu wolau si manö, wa öfarahugö ba zi so horö zi lö horö, wamunu ya''ira, fa faoma nifatörö, he ba zi lö horö, ba he ba zi so horö. Ya''aröu khöu da''ö! Hadia, tenga satulö, ilau sanguhuku uli danö ma''asagörö andrö?[8]', '["Rom 3:6"]', NULL),
  (3439337, 'OT', 'Moze I', 18, 26, 'Ba imane Yehowa: Na usöndra ena''ö zi lima wulu si lö horö, ba Zodoma, ba mbanua, ba uhakhösi tödö mbanua ma''asambua, börö ira andrö.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 27, 'Ba itohugö Aberahamo, imane: Hiza sa, lö ata''udo muhede khöu, he ŵa''ae no tanö ba awu ndra''odo.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 28, 'Ma dania lima ambö lima wulu zi lö horö andrö, ba hadia, öfakiko mbanua andrö ma''asambua börö zi lima andrö?', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 29, 'Ba itohugö na wehede khönia, imane: Ma dania falukha zi öfa wulu bakha.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 30, 'Ba imane Aberahamo: He Tuha, böi ofönu, na uŵa''ö na. Ma dania tölu ngafulu zi so bakha.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 31, 'Ba imane: He Tuha, lö sata''u ndra''o muhede khöu; ma dania falukha zi dua wulu bakha.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 32, 'Ba imane: Böi öfönu, Tuha, na uŵa''ö na, hatö zi samuza andre: Ma falukha zi dafulu bakha.', '[]', NULL),
  (3439337, 'OT', 'Moze I', 18, 33, 'Ba mofanö Yehowa, me no i''o''ozui huhuo andrö khö Gaberahamo; ba ifuli ia khöra Aberahamo.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 1, 'Ba larugi Zodoma mala''ika andrö si darua, me tanö owi.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 2, 'Ba imane: He Tua, mi''ae yomo ba nomo zawuyumi, ba wemörö, ba misasai gahemi; ba mahemolu mbanua, ba hana na mofanö ami.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 3, 'Ba iforege khöra, irege fao ira khönia, irege möi baomonia. Ba ihalö göra, ba ifazökhi kue, si lö mu''aisöni, ba manga ira.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 4, 'Ba lö si mörö ira na, ba lafasui nomo ira matua mbanuara andrö, banua Zodoma andrö, he ono matua, ba he satua, samba banua manö, lahurufai.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 5, 'Mu''ao ira khö Loti, lamane khönia: Heza so niha andrö, si no möi yomo khöu bongi? Ohe baero ira khöma, ena''ö oruduga khöra.[1]', '["MozIII 18:22; Sanguhuk 19:22"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 6, 'Ba möi tou khöra Loti — ba bawandruhö, ba ikusi furinia —', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 7, 'Ba imane: He ga''a! Böi manao horö ami! Hiza!', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 8, 'Dombua khögu nono alawe, si lö irai mangila ira matua; da''ö ube''e baero khömi, ba hana na milau khöra zomasi ami. Ba lö tola milau hadia ia ba niha andrö, me no atö möi ira ba lumö zagö khögu.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 9, 'Ba lamane: Fa''ese''ö! lamane: Ha samö-samösa ia, si möi fatewu ba da''e, ba lö aetu idegu-degu ita. Ba damalau khöu zabölö-bölö, moroi ba nilauma khöra ena''ö!', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 10, 'Ba la''oro''ö dangara moroi yomo niha no mege, lasöbi yomo khöra Loti ba lakusi mbawandruhö.', '["RazII 6:18"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 11, 'Ba lahawui bösi niha andrö, si so tou, he iraono ba he satua, tobali la''alu-alui manö mbawandruhö, ba lö lasöndra.[3].', '["RazII 6:18"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 12, 'Ba lamane niha no mege khö Loti: Hadia, so khöu na ba da''e, ha niha? umönöu ba ma onou matua ba ma onou alawe ba ha niha na tana khöu, ba mbanua andre, ba ohe misa!', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 13, 'Mafakiko sa mbanua da''e, me no te''adugö sibai ira khö Yehowa; andrö ifatenge ndra''aga Yehowa, ba wamakiko ya''ira.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 14, 'Ba möi tou Loti, humede ia ba numönönia, sangai ononia ena''ö, imane: Milabu, miheta ami ba da''e! Ifakiko sa''ae mbanua da''e Yehowa!', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 15, 'Ba me ibörötaigö moluo, ba lafangaösö Loti mala''ika andrö, lamane: Labu, ohe wo''omou ba onou andrö si dombua, si so ba da''e, fa böi tetiko ndra''ugö göi ba horö mbanua andre!', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 16, 'Ba me arörö-rörö ia na, ba latuyu da''ionia niha andrö, fabaya fo''omonia ba ononia andrö si dombua, me no edöna i''orifi ia Yehowa, la''ohe baero ba laröi ia ba da''ö baero mbanua.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 17, 'Ba ba wolohe ya''ira baero, ba lamane: Orifi''ö, nosou mbalazi! Böi bali''ögö furi ba böi badugö''ö heza, ba ndraso. Ba hili orifi''ö, fa böi fao ndra''ugö ba wa''atekiko!', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 18, 'Ba imane khöra Loti: Böi, Tua!', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 19, 'Noa sa atö isöndra wa''ebua dödö sawuyumö, wamaigiu, tobali no ebua wa''ahakhö dödöu khögu, ba no ö''orifido; ba tebai moloi ndra''o ba hili; ma dania so zi göna ndra''o, famunugu.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 20, 'Hiza mbanua, si no ahatö, si tola usaŵa; ba no side-ide, da''ö zomasido usaŵa — noa sa atö side-ide ia — ena''ö aurido.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 21, 'Ba imane khönia: Hiza, ba da''ö göi u''o''ö khöu, ba lö ufakiko mbanua andrö niŵa''öu.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 22, 'Ta''i-ta''i, saŵa daö; lö''ö sa u''ila ulau hadia ia, balazi no örugi. Andrö wa labe''e töi mbanua andrö Zoara (side-ide).', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 23, 'Ba no tumbu luo ba guli danö, me irugi Zoara Loti.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 24, 'Ba aekhu dalö balera[4] ba alitö ba Zodoma ba ba Gomora, ibe''e Yehowa, moroi yaŵa ba mbanua,[5]', '["talö-balera: sambua botoŵa soroma hulö dalö sa''usö. Huania aböu ba so ia ba nahia heza böla nidanö aukhu ba mbombo aukhu. Molo''ö niha meföna hua dalö balera andre fagölö ira hua narako.","MozV 29:23; Yes 13:19; Luk 17:29; Yud 7"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 25, 'idudugö mbanua andrö, fabaya tanö tou, tefarahu ndraso andrö ma''asagörö, awö niha, banua da''ö, awö zinanö ba danö andrö.', '["talö-balera: sambua botoŵa soroma hulö dalö sa''usö. Huania aböu ba so ia ba nahia heza böla nidanö aukhu ba mbombo aukhu. Molo''ö niha meföna hua dalö balera andre fagölö ira hua narako.","MozV 29:23; Yes 13:19; Luk 17:29; Yud 7"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 26, 'Ba ibali''ö ia furi, ba wamaigi, fo''omo Loti, furinia, ba tobali kara mo''asio.[6].', '["Luk 17:32"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 27, 'Ba mahemolu ö, ba ihulö wongi Aberahamo, we''amöi ba zi so ia mege, khö Yehowa.', '["sino-wa''u: alitö sebua"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 28, 'Ba me ifaigi mitou Zodoma ba Gomora, awö ndraso andrö ma''asagörö, ba i''ila, numalö yaŵa zimbo, moroi ba danö andrö, hulö zimbo zino wa''u.[7]', '["sino-wa''u: alitö sebua"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 29, 'Ba me idudugö Lowalangi mbanua ba ndraso andrö, ba itörö tödö Lowalangi Gaberahamo andrö, ba ifasao misa Loti, iheta ba wa''adudu andrö, me idudugö mbanua andrö, fabaya tanö tou, banua si so Loti mege.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 30, 'Ba ifuli iheta ia ba Zoara Loti, isaŵa miyaŵa ba i''iagö hili, awö nononia alawe andrö, si dombua; ata''u sa''ae ia, ba Zoara soso ia; ba dögi narö hili nahiania, awö nononia andrö si dombua.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 31, 'Ba imane si a''a khö nakhinia: Satua sa''ae namada, ba lö niha ba guli danö, sorudu khöda ena''ö, si mane huku ba guli danö ma''afefu.', '["MozIII 18:7"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 32, 'Tabu, datafabadugö nagu khö namada, ba orudu mörö ita khönia, ena''ö lö aetu nga''ötöda ibe''e amada.[8]', '["MozIII 18:7"]', NULL),
  (3439510, 'OT', 'Moze I', 19, 33, 'Ba latema lafabadugö nagu khö namara, ba zi bongi andrö; ba möi si bakha zi a''a, orudu mörö ia khö namara. Ba lö i''ila, me ifadölö tou ia, ba lö''ö göi i''ila, me maaso.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 34, 'Ba mahemolu mbanua, ba imane si a''a andrö khö nakhinia: Noa sa orudu mörö ndra''o khö namada; tafuli tafabadugö khönia nagu, bongi dania göi; ba ae si bakha ba förö ba ngainia, ena''ö lö aetu nga''ötöda ibe''e amada.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 35, 'Ba lafuli lafabadugö nagu khö namara, ba zi bongi andrö göi; ba möi mörö ba ngainia zi akhi. Ba lö i''ila, me ifadölö ia ba he me maoso ia.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 36, 'Ba tobali manabina nono Loti andrö, ma''adombua, khö namara.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 37, 'Ba madono zi a''a, ono matua, ba ibe''e töi nononia andrö Moabi; da''ö wurugö Ndraono Moabi andrö ma''ökhö.', '[]', NULL),
  (3439510, 'OT', 'Moze I', 19, 38, 'Ba si akhi göi, ba madono göi, ono matua, ba ibe''e töinia Gamoni; da''ö wurugö Ndraono Gamoni ma''ökhö.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 1, 'Ba iheta ia ba da''ö Aberahamo, isaŵa danö si raya, ba gotaluara Gadesi Zuri i''iagö, ba Gerara.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 2, 'Ba ba khö wo''omonia Sara, ba imane: Akhigu!', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 3, 'Ba möi khö Gabimelekhi Lowalangi, ba wangifi, ba zi bongi, imane khönia: Si mate ndra''ugö, börö ndra alawe andrö, nihalöu, me no donga zodonga.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 4, 'Ba lö sorudu khönia Gabimelekhi; ba imane: He So''aya! zumöi öbunu zi lö horö!', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 5, 'Ba noa sa ya''ia zanguma''ö khögu: Akhigu! Ba si manö göi ndra alawe, no imane: Ga''agu! Sadölö dödögu ba si lö sala dangagu ba wolaugu andrö khönia.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3414393, 'OT', 'Moze I', 20, 6, 'Ba imane khönia Lowalangi, ba wangifi: Ba ya''odo göi, u''ila sa, wa no sadölö tödö ndra''ugö, wolau si manö, ba no ya''o zanimba khöu wamazökhi horö khögu mena''ö; andrö lö utehe öbabaya ia.', '["Sin 105:15; Yob 42:8"]', NULL),
  (3414393, 'OT', 'Moze I', 20, 7, 'Ba fuli sa''ae ba zodonga ndrongania, noa sa sama''ele''ö ia, ba akha mangandrö ia salahiu, ena''ö auri ndra''ugö; ba na lö öfuli, ba ya''aboto ba dödöu, wa si mate ndra''ugö, fabaya fefu dana khöu.[2]', '["Sin 105:15; Yob 42:8"]', NULL),
  (3414393, 'OT', 'Moze I', 20, 8, 'Ba mahemolu ö, ba ihulö wongi Abimelekhi, wehede ba zawuyunia fefu, ba idunö-dunö khöra fefu, he wisa mege; ba ata''u sibai niha andrö.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 9, 'Ba ifakaoni''ö Gaberahamo Abimelekhi, imane khönia: Hadia wolaumö khöma! Hadia horögu khöu, wa öfatörö khögu ba ba mbanuagu fefu horö sebua andrö! Si tebai manö telau mena''ö, ba no ölau khögu.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 10, 'Ba imane na Abimelekhi khö Gaberahamo: Hadia daniu wolau si manö?', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 11, 'Ba imane Aberahamo: Me no umane dödögu: Te sa lö falukha wangata''ufi Lowalangi ba mbanua andrö, ba labunu sa''ae ndra''odo, börö wo''omogu andrö.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 12, 'Ba si ndruhu sa göi akhigu ia, ono namagu — ha fa tenga ono ninagu, ba no uhalö ia.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 13, 'Me iŵa''ö khögu Lowalangi, ahetado ba khöma, möido ba danö bö''ö, ba umane khönia: Da''ö ölau, fa''omasiu ndra''odo: gofu heza tarugi dania, ba öŵa''ö ga''au ndra''odo.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 14, 'Ba ihalö mbiri-biri ba saŵi ba sawuyu ono matua ba sawuyu ono alawe Abimelekhi, ba ibe''e khö Gaberahamo; ba ifuli göi khönia wo''omonia Sara.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 15, 'Ba imane Abimelekhi: Hiza fönau danögu; heza zomasi''ö, ba da''ö iagö.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 16, 'Ba imane khö Zara: Hiza, ube''e ba danga ga''au zi hönö rufia, zosi-zosi khöu da''ö ba zi so ba ngaiu, fefu, tobali lö horöu ba niha fefu.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 17, 'Ba mangandrö Gaberahamo khö Lowalangi, salahi Gabimelekhi, ba ifadöhö wökhönia Lowalangi, ba fökhö wo''omonia ba fökhö zawuyunia ira alawe, fa mo''ono''ono ira.', '[]', NULL),
  (3414393, 'OT', 'Moze I', 20, 18, 'Noa sa ifaulugö Yehowa wokusi talu ndra alawe ba nomo Gabimelekhi fefu, börö Zara andrö, fo''omo Gaberahamo.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 1, 'Ba no ifatörö khö Zara Yehowa nifabu''unia; ilau khönia niŵa''önia Yehowa.[1]', '["Faigi 17:19","Gal 4:23; Heb 11:11"]', NULL),
  (3415471, 'OT', 'Moze I', 21, 2, 'Ba manabina Zara ba mo''ono khö Gaberahamo, ba wa''atuania, ono matua, ba ginötö andrö, niŵa''ö Lowalangi.[2]', '["Faigi 17:19","Gal 4:23; Heb 11:11"]', NULL),
  (3415471, 'OT', 'Moze I', 21, 3, 'Ba ibe''e töi nononia Giza''aki Aberahamo, töi nono sawena tumbu andrö khönia khö Zara.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 4, 'Ba iboto nononia Iza''aki Aberahamo, me no fitu bongi, i''o''ö niŵa''ö Lowalangi khönia.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 5, 'Ba no otu fakhe Gaberahamo, me tumbu khönia nononia Iza''aki andrö.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 6, 'Ba imane Sara: Fama''iki nilau Lowalangi khögu; dozi ha niha zamondrongo, ba la''igi-igi''ö ndra''odo.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 7, 'Ba imane na: Ha niha zirai möi ba dödö, khö Gaberahamo andrö, wa samaenu ono na dania Zara! Ba noa sa mo''onodo khönia, ba wa''atuania.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 8, 'Ba manöi nono andrö ba aefa ba mbagi zusu; ba ibe''e gö niha, Aberahamo, ebua ihalö, me luo aefa ba mbagi zusu Giza''aki.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 9, 'Ba me i''ila Sara nono Hagara andrö, Dawa Miserayi, ononia khö Gaberahamo, wa saiki-iki ia,', '["Gal 4:30"]', NULL),
  (3415471, 'OT', 'Moze I', 21, 10, 'ba imane khö Gaberahamo: Fofanö zawuyu andrö, awö nononia; lö''ö sa tola manema ondröita dania nono zawuyu andrö, awö nonogu Iza''aki.[3]', '["Gal 4:30"]', NULL),
  (3415471, 'OT', 'Moze I', 21, 11, 'Ba fatuwu sibai da''ö khö Gaberahamo, börö nononia andrö.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 12, 'Ba imane Lowalangi khö Gaberahamo: Böi abua khöu ba nono andrö ba ba zawuyumö andrö; ahori ö''o''ö ni''andrö Zara khöu; ha sa ma''uwu Giza''aki dania, niŵa''ö sindruhu nga''ötöu.[4]', '["Rom 9:7; Heb 11:18"]', NULL),
  (3415471, 'OT', 'Moze I', 21, 13, 'Ba he ono zawuyu andrö göi, ba soi sebua dania ube''e, me no onou.', '["Rom 9:7; Heb 11:18"]', NULL),
  (3415471, 'OT', 'Moze I', 21, 14, 'Ba mamahemolu ö, ba ihulö wongi Aberahamo, ihalö roti ba sara asoa nidanö, ibe''e khö Hagara, ba ifalu''igö khönia nono, ba ifofanö.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 15, 'Ba me no ahori nidanö ba nasoa, ba itibo''ö tou ba mbörö da''uli nono,', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 16, 'ba möi ia dumadao ba zi tambai, mato ikhamö ono wana wa''aröu; imane sa: Tebai unehegö wa''amate nono! Andrö i''aröu''ö ia ma''ifu; ba ibörötaigö me''e nono.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 17, 'Ba me irongo Lowalangi we''e nono, ba mu''ao mala''ika Lowalangi khö Hagara, moroi ba mbanua si yaŵa, imane khönia: Hadia khöu, Hagara? Böi busi dödöu! No irongo Lowalangi we''e nono andrö, ba zi so ia.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 18, 'Ae fazaŵa nono ba ohe dangania, tobali soi sebua sa ia ube''e.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 19, 'Ba ibokai hörönia Lowalangi, ba i''ila gumbu nidanö. Ba möi ia, ifo''ösi nasoa idanö, ba ifabadugö khö nono.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 20, 'Ba itolo nono andrö Lowalangi; manöi ia, ba ba danö si mate soso ia ba tobali sonekhe fafanata.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 21, 'Ba danö si mate Farana i''iagö, ba ifangowalu ia inania, moroi ba danö Miserayi.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 22, 'Ba me luo da''ö, ba lamane khö Gaberahamo Abimelekhi no ba kumandra andrö khönia, Fikholo: Itolo-tolo''ö Lowalangi ba nilaumö fefu.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 23, 'Andrö ae ba hölu khögu iya''e ba da''e, ba Lowalangi, wa lö''ö manö falimo ndra''ugö khögu ba he ba dana khögu, si mane ya''odo, me no si fahuwu ndra''o khöu, ba no si fahuwu khögu göi ndra''ugö ba ba zi so ba danö andre fefu, ba zi soso ndra''ugö si fatewu.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 24, 'Ba imane Aberahamo: Möido ba hölu.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 25, 'Ba isekhegö Gabimelekhi Aberahamo, ba mba''a nidanö andrö, ni''okhögö zawuyu Gabimelekhi, ni''anösö''ö.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 26, 'Ba imane Abimelekhi: Lö u''ila, ha niha zolau da''ö; lö hadia ia ni''ombakha''öu khögu, ba lö''ö göi nirongogu ya''ia, irege ma''ökhö.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 27, 'Ba ihalö mbiri-biri ba saŵi Aberahamo, ibe''e khö Gabimelekhi, ba fawu''u li ira.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 28, 'Ba i''oniagö zi fitu rozi, ono mbiri-biri, Aberahamo.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 29, 'Ba imane Abimelekhi khö Gaberahamo: Heza labe''e nono mbiri-biri andrö, si fitu rozi, ni''oniagömö?', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 30, 'Imane Aberahamo: Ono mbiri-biri andrö, si fitu rozi, ba ya sinemau khögu; ya famaduhu''ö da''ö khögu, wa no ya''o zogao ba''a andrö.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 31, 'Andrö wa labe''e töi naha andrö: Mbereseba, me no ba da''ö faoma fahölu ira khö nawöra.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 32, 'Si manö: wawu''usa li khöra ba Mbereseba.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 33, 'Ba itanö mbou Aberahamo, ba Mbereseba andrö ba i''angaröfi li döi Yehowa ba da''ö, töi Lowalangi si lö aetu andrö.', '[]', NULL),
  (3415471, 'OT', 'Moze I', 21, 34, 'Ba ara Gaberahamo ba danö Ndrawa Wilisiti.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 1, 'Ba me no aefa da''ö, ba itandraigö Gaberahamo Lowalangi, imane khönia: He Aberahamo!', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 2, 'Ba imane: Halö nonou andrö si ha sambua, somasi ndra''ugö, Iza''aki andrö, ba ae ba danö Moriya, ba be''e sumange nitunu ia ba da''ö ba hili, niŵa''ögu khöu dania.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 3, 'Ba mahemolu ö, ba ihulö wongi Aberahamo, ifosela galidenia, i''ohe zawuyunia, darua, ba ononia Iza''aki, isisila geu, fanunu zumange, ba maoso ia, isaŵa naha andrö, niŵa''ö Lowalangi khönia.[2]', '["MozV 18:10 b.t."]', NULL),
  (3418223, 'OT', 'Moze I', 22, 4, 'Ba dua wongi, ba ifaöga hörönia Aberahamo, ifakhölö ia, ba faoro khönia naha andrö, aröu na.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 5, 'Ba imane Aberahamo ba zawuyunia: Mi''iagö da''e, awö galide, möiga misa mangandrö, daruaga ono, ba na noa da''ö, ba mafuliga khömi.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 6, 'Ba ihalö geu andrö, fanunu zumange, ibe''e noro nononia Iza''aki ba ituyu galitö ba si''öli fanaba, ba mofanö ira, darua ira.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 7, 'Ba humede Giza''aki khö namania Aberahamo, imane: He Ama!', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 8, 'Imane Aberahamo: Ifaigi sa dania Lowalangi mbiri-biri, sumange nitunu, onogu! Ba mowaö-waö ira, darua ira.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 9, 'Ba me no larugi naha andrö, niŵa''ö Lowalangi khönia, ba ifa''anö naha wame''e sumange Aberahamo ba eu andrö, ba ifa''anö göi; ba i''amöbö''ö nononia Iza''aki ba ibe''e ba naha wame''e sumange andrö, ba dete geu.[3]', '["Yak 2:21"]', NULL),
  (3418223, 'OT', 'Moze I', 22, 10, 'Ba i''oro''ö dangania Aberahamo, ituyu zi''öli, ba wanaba ononia.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 11, 'Ba mu''ao khönia mala''ika Yehowa moroi ba mbanua si yaŵa, imane: He Aberahamo! He Aberahamo!', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 12, 'Ba imane: Böi babaya nono andrö, böi fakao ia! Awena sa u''ila, wa no sangata''ufi Lowalangi ndra''ugö, me lö alimagö khöu nonou andrö, si ha sambua, ölulu khögu.[4]', '["Rom 8:32"]', NULL),
  (3418223, 'OT', 'Moze I', 22, 13, 'Ba ifaöga hörönia Aberahamo ba i''ila zi matua mbiri-biri, si no tokhai ba ndru''u tandrunia. Ba möi Gaberahamo, ihalö mbiri-biri andrö ba ibe''e sumange nitunu, salahi nononia.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 14, 'Ba ibe''e töi naha andrö Aberahamo "Zanehe Yehowa". Andrö wa laŵa''ö na ma''ökhö: "Ba hili andrö, ba ni''oroma''ö Yehowa ya''ia."', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 15, 'Ba ifuli mu''ao mala''ika Yehowa khö Gaberahamo, i''oroi mbanua si yaŵa, imane:', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 16, 'Fahölu ndra''o ba khögu, iŵa''ö Yehowa: Me no ölau da''ö, ba me lö salimagö khöu nonou andrö si ha sambua, ölulu khögu,[5]', '["Heb 6:13","Faigi 12:3"]', NULL),
  (3418223, 'OT', 'Moze I', 22, 17, 'ba uhöna khöu howu-howu, ba ato sibai dania ma''uwumö ube''e, fa''oya ndröfi ba mbanua si yaŵa ba fa''oya ngawua nene ba mbewe nasi, ba sokhö bawa göli ba nemalira ma''uwumö dania.', '["Heb 6:13","Faigi 12:3"]', NULL),
  (3418223, 'OT', 'Moze I', 22, 18, 'Ba moroi ba ma''uwumö tefahowu''ö dania fefu soi ba guli danö, böli gölöu, me no ö''o''ö niŵa''ögu andrö.[6]', '["Heb 6:13","Faigi 12:3"]', NULL),
  (3418223, 'OT', 'Moze I', 22, 19, 'Ba ifuli ia ba zawuyunia Aberahamo, ba maoso ira ba fao ira ba Mbereseba, ba ba Mbereseba ahono Gaberahamo.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 20, 'Ba me aefa da''ö, ba te''ombakha''ö khö Gaberahamo: Noa göi mo''ono Milika andrö khö nakhiu Nakhori, Usi, si a''a,', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 21, 'ba akhi da''ö, Busi ba Kemueli, furugö Ndrawa Garamo andrö,', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 22, 'ba Khesudi ba Haso ba Filida ba Yidilafa ba Betueli;', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 23, 'ba ono Mbetueli Rebeka andrö. Si daŵalu andrö nono Milika khö Nakhori, akhi Gaberahamo.', '[]', NULL),
  (3418223, 'OT', 'Moze I', 22, 24, 'Ba so na zambua tö ndrongania ba döi, Roima döi; ba mo''ono göi da''ö khönia: Teba ba Gahamo ba Tahasi ba Ma''akha.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 1, 'Otu a dua wulu a fitu fakhe wa''ara Zara ba guli danö; da''ö wa''anau nosonia.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 2, 'Ba mate Zara be Giriata Garaba, ya''ia Heberona andrö, ba danö Gana''ana. Ba möi Gaberahamo fa''ala-alai ba khö Zara, mange''esi ya''ia.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 3, 'Aefa da''ö, ba iröi mboto zi mate andrö, möi ia muhede ba Ndraono Kheti, imane:', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 4, 'Niha bö''ö ndra''o khömi, si fatewu; Mitehe khögu lewatö ba khömi, ondröita dania, ena''ö uheta yomo zi mate andrö khögu, ena''ö uko''o.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 5, 'Ba latema li Gaberahamo Iraono Kheti, lamane:', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 6, 'Fondrondrongo khöma ine, Tua! Amaedola zalaŵa ba khö Lowalangi ndra''ugö, we''asosömö ba khöma; ba wondrege zi sökhi lewatö khöma ko''o zi mate andrö khöu! samösa lö ba khöma, sanenaŵa ya''ugö, na ba lewatö khönia öko''o zi mate andrö khöu.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 7, 'Ba maoso Gaberahamo, mangalulu ia ba niha ba danö andrö, Iraono Kheti.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 8, 'Ba humede ia khöra, imane: Na möi dödömi uheta yomo zi mate andrö khögu ba uko''o, be mitolodo, milului manguma''ö khö Geferono andrö, ono Zohara,', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 9, 'ena''ö ibe''e khögu dögi narö hili andrö, Makhefela, khönia, ba wondrege mbenuania andrö; lö u''ambösi mbölinia khönia, na ibe''e khögu lewatö ba khömi, ondröita dania.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 10, 'Ba no dumadao göi ba da''ö Geferono andrö, awö Ndraono Kheti. Ba itema li Gaberahamo Eferono, Iraono Kheti, tobali larongo Iraono Kheti, ha wa''ato ira, sanörö bawa göli mbanuania miyomo, imane:', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 11, 'Böi, Tua! fondrondrongo khögu! Ube''e bualagu khöu mbenua andrö, fabaya tögi narö hili andrö bakha, ube''e buala khöu; ba zanehe niwama andre ube''e bualagu khöu. Ko''o manö sa''ae zi mate andrö khöu!', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 12, 'Ba mangalulu Geberahamo ba niha ba danö andrö.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 13, 'Ba humede ia khö Geferono andrö; larongo banuara, imane: Na si manö dödöu, ba fondrondrongo khögu! Ube''e mböli mbenua andrö, halö ia khögu, ena''ö uko''o ba da''ö zi mate andrö khögu.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 14, 'Ba imane Eferono khö Gaberahamo:', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 15, 'Fondrondrongo khögu ine, Tua! Benua si 400 rufia moböli, ba hadia da''ö khöda, darua ita? Ko''o manö sa''ae zi mate andrö khöu!', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 16, 'Ba i''o''ö khö Geferono Aberahamo, ba itulo khö Geferono mböli andrö Aberahamo, niŵa''önia ba zi so Ndraono Kheti andrö, 400 rufia fanimba, si laku ba waniaga.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 17, 'Ba tobali khö Gaberahamo mbenua Geferono andrö, ba Makhefela, ba gamaudu Mamere, banua andrö, si so tögi narö hili andrö bakha, awö geu fefu, si so ba mbenua andrö, fasui,[1]', '["Faigi 25:10; 50:13"]', NULL),
  (3421579, 'OT', 'Moze I', 23, 18, 'te''aro''ö khö Gaberahamo, ba zi so Ndraono Kheti andrö, ha wa''ato ira, sanörö bawa göli mbanuania, miyomo.', '["Faigi 25:10; 50:13"]', NULL),
  (3421579, 'OT', 'Moze I', 23, 19, 'Aefa da''ö ba iko''o wo''omonia Sara Aberahamo ba dögi narö hili andrö, ba mbenua Makhefela, ba gamaudu Mamere, ya''ia Heberona, ba danö Gana''ana.', '[]', NULL),
  (3421579, 'OT', 'Moze I', 23, 20, 'Ba tobali te''aro''ö khö Gaberahamo mbenua andrö fabaya tögi narö hili andrö bakha, la''aro''ö Iraono Kheti, lewatö khönia, ondröita dania.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 1, 'Ba no atua Gaberahamo, no numalö ndröfi; ba no ifahowu''ö Gaberahamo Yehowa, ba nibaya-bayania fefu.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 2, 'Ba humede Gaberahamo khö zatua zawuyunia baomonia, si so barö mbawa fefu hadia ia zi so khönia, imane: Tufa tangau narö zolagu!', '["Faigi 28:1; MozV 7:3"]', NULL),
  (3422589, 'OT', 'Moze I', 24, 3, 'Möi''ö sa ba hölu khögu, ba khö Yehowa, Lowalangi mbanua si yaŵa ba Lowalangi danö, wa tenga ono Ndrawa Gana''ana ba zi fatewu ndra''odo, öhalö khö nonogu andrö,[1]', '["Faigi 28:1; MozV 7:3"]', NULL),
  (3422589, 'OT', 'Moze I', 24, 4, 'wa ba khöma möi''ö, ba niŵa''öma, ba wangai ira alawe khö nonogu Iza''aki.', '["Faigi 28:1; MozV 7:3"]', NULL),
  (3422589, 'OT', 'Moze I', 24, 5, 'Ba imane sawuyu andrö: Ba na lö edöna fao khögu ndra alawe andrö, ba danö andre, ba hadia u''ohe mangawuli nonou ba danö andrö, ba zaheta ya''ugö?', '["Faigi 12:1,7; MozII 32:13"]', NULL),
  (3422589, 'OT', 'Moze I', 24, 6, 'Imane khönia Aberahamo: Böi! böi ohe mangawuli ba da''ö nonogu!', '["Faigi 12:1,7; MozII 32:13"]', NULL),
  (3422589, 'OT', 'Moze I', 24, 7, 'Yehowa andrö, Lowalangi mbanua si yaŵa, sangeheta ya''o mege ba nomo namagu ba ba mbanuama, si no muhede khögu, si no fahölu khögu, wanguma''ö: "Ba ma''uwumö ube''e danö andre" — da''ö zamowaö-waö dania fönau mala''ikania, ena''ö ba da''ö öhalö ndra alawe khö nonogu.[2]', '["Faigi 12:1,7; MozII 32:13"]', NULL),
  (3422589, 'OT', 'Moze I', 24, 8, 'Ba na lö edöna ndra alawe andrö, i''o''ö ndra''ugö, ba aefa ndra''ugö ba wahölusa andre; ba lö''ö manö tola ö''ohe mangawuli ba da''ö nonogu!', '["Faigi 12:1,7; MozII 32:13"]', NULL),
  (3422589, 'OT', 'Moze I', 24, 9, 'Awena itufa tangania narö zola Gaberahamo, möi ia ba hölu khönia, i''o''ö niŵa''önia.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3422589, 'OT', 'Moze I', 24, 10, 'Aefa da''ö, ba ihalö gondra sawuyu andrö, fulu nga''eu, ondra zokhö ya''ia, awö ngawalö naya khö zokhö ya''ia, i''ohe, ba maoso ia, isaŵa Mezofotamia, mbanua Nakhori andrö.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 11, 'Ba ibe''e molombase gondra no mege baero mbanua, ba zinga mba''a, tanö-tanö owi, si möi-möi baero ndra alawe, ba wana''u idanö.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 12, 'Ba imane: "He Yehowa Lowalangi zokhö ya''o andrö, Lowalangi Gaberahamo! Tolodo, ebua''ö dödöu khö zokhö ya''o andrö Aberahamo.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 13, 'Na sodo ba zinga mba''a iada''e, ba na so moroi yomo nono alawe ba mbanua da''e mana''u idandö —', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 14, 'ba na itema dania ligu ono alawe andrö ba niŵa''ögu: Oro''ö nasoa, da''ubadu, na imane: Badu, ba ufabadugö göi ba gondra khöu, ba ya da''ö nihonogöimö khö genoniu Iza''aki, ba ba da''ö ya''aboto ba dödögu. wa no ebua dödöu khö zokhö ya''o.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 15, 'Ba lö saetu wangandrönia na, ba so moroi yomo Rebeka, ono Mbetueli ono Milika andrö, fo''omo Nakhori, akhi Gaberahamo, so ba galisinia nasoa.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 16, 'Ba si sökhi bawa ia, ono alawe, si lö irai orudu ba ndra matua. Ba möi ia mitou ba mba''a, ifo''ösi nasoa ba ifuli ia miyaŵa.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 17, 'Ba fagohi zawuyu no mege, wamaondragö ya''ia, imane: Da''ubadu ma''ifu nidanö ba nasoa khöu.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 18, 'Ba imane: Badu, Tua! Ba i''aliogö i''oro''ö nasoa, ifabadugö khönia.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 19, 'Ba me no abönö ifabadugö khönia, ba imane: Da''uta''u-ta''u göi ö gondra khöu, irege abuso ira.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 20, 'Ba i''aliogö ifaduwa ba luha nösi nasoa andrö khönia ba fagohi ia, ifuli isaŵa mba''a, ba wana''u idanö na, ita''u ö gondra khönia fefu.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 21, 'Ba ahöli-höli dödö niha andrö, ifaigi-faigi, lö hede-hede, ena''ö i''ila, na no ifahowu''ö Yehowa we''amöinia, ba na lö''ö.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 22, 'Ba me no abuso gondra, ba ihalö naya ba nikhu niha andrö, ana''a, sasuku fanimba, ba dua rozi naya ba mbulökha, fulu rufia fanimba, ana''a, ba imane:', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 23, 'Ha ono ndra''ugö? Ombakha''ö khögu! Hadia, monaha ndra''aga ba nomo namau, na möiga mörö ba da''ö?', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 24, 'Ba imane khönia: Ono Mbetueli andrö ndra''odo, Betueli ono Milika andrö, ononia khö Nakhori.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 25, 'Ba imane na: No fahöna khöma ndru''u ba ö gondra, ba ebolo naha, ba wemörö.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 26, 'Ba ifaöndrö ia niha andrö, mangalulu ia khö Yehowa, imane:', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 27, 'Nisuno Yehowa, Lowalangi zokhö ya''o andrö, Lowalangi Gaberahamo, si lö mangambösi fa''ebua dödönia, awö wa lö faröi khö zokhö ya''o. Lala da''e, ba ni''oroma''ö Yehowa khögu, lala ba nomo dalifusö zokhö ya''o!', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 28, 'Ba fagohi nono alawe andrö, i''ombakha''ö khö ninania zi no falukha ia.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 29, 'Ba so dalifusö Rebeka andrö, Labano döi.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 30, 'Ba me i''ila da''ö naya ba nikhu andrö, awö naya ba mbulökha khö nakhinia, ba me irongo ni''ombakha''ö Rebeka, me imane: Da''ö niŵa''ö niha andrö khögu! ba fagohi Labano andrö, isaŵa niha andrö ba gero mbanua, ba zinga mba''a, ba irugi; no soso manö ia ba da''ö; awö gondra, ba zinga mba''a.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 31, 'Ba imane Labano: Ae yomo, nifahowu''ö Yehowa! hana wa ba da''e baero so''ö? Noa sa''ae uhaogö nomo ba no ufaigi naha gondra.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 32, 'Ba me no irugi yomo niha andrö, ba iheta zela gondra [Labano] ba ibologö tou ndru''u, tufo gondra ba ibe''e gö ba ihalö nidanö, fanasa gahe khönia ba ba nawönia fao.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 33, 'Ba me labe''e gönia mena''ö, ba imane: Lö mangado, irege no uŵa''ö niŵa''ögu!', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 34, 'Ba imane: Sawuyu Gaberahamo ndra''odo.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 35, 'No ihöna howu-howu khö zokhö ya''o Yehowa, ba no sebua ana''a ia. No ibe''e bualania khönia Yehowa mbiri-biri ba saŵi ba firö ba ana''a ba sawuyu ira matua ba sawuyu ira alawe ba ondra ba kalide.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 36, 'Ba Sara andrö, fo''omo zokhö ya''o, ba no mo''ono, ono matua, khö zokhö ya''o, me niha satua sa''ae ia; ba danga da''ö ibe''e fefu zi so khönia.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 37, 'Ba no ibe''e li khögu sokhö ya''o, no ibe''edo ba hölu ba da''ö, imane: Lö tola ba Ndrawa Gana''ana öhalö ndra alawe khö nonogu, ba Ndrawa Gana''ana andre, si sodo ba danö, ba mbanuama möi''ö,', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 38, 'ba niwama, ba wangai ira alawe khö nonogu.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 39, 'Ba no umane khö zokhö ya''o: Ba he wisa, na lö edöna i''o''ö ndra''o alawe andrö?', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 40, 'Ba imane khögu: Yehowa andrö, si no anehe, ba wanörögu lalagu andrö, ifowaö-waö mala''ikania fönau ba ifahowu''ö we''amöimö, ena''ö ba niwama öhalö ndra alawe khö nonogu, ba mbanuama andrö.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 41, 'Ba awena aefa''ö ba wahölusa andre, na no möi''ö ba niwama; na lö latehe khöu, ba aefa''ö ba wahölusa andre khögu.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 42, 'Ba me urugi mba''a andrö, me ma''ökhö, ba umane: He Yehowa Lowalangi, zokhö ya''o, Lowalangi Gaberahamo! na öfahowu''ö ndra''o ba lala andre nitörögu, ba tolodo:', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 43, 'Na sodo ba da''e, ba zinga mba''a, ba na so moroi yomo nono alawe, ba wana''u idanö, ba na umane khönia: Be''e ögu ma''ifu nidandö ba nasoa khöu!', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 44, 'ba na imane: Badu, ba da''ufabadugö göi ba gondra khöu! — ba ya da''ö ndra alawe andrö, si no ihonogöi Yehowa khö nono zokhö ya''o andrö.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 45, 'Ba ha si''aikö aefa uhonogöi da''ö tödögu, ba so moroi yomo Rebeka, no i''angalisigö nasoa, möi ia mitou ba mba''a, mana''u idanö. Ba umane khönia: Be''e ögu, ubadu!', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 46, 'Ba i''anema''ö i''oro''ö nasoa, imane: Badu, ba da''ufabadugö ba gondra khöu göi. Ba ubadu nidanö ba ifabadugö ba gondra göi.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 47, 'Aefa da''ö, ba usofu khönia, umane: Ha ono ndra''ugö? Ba imane: Ono Mbetueli ndra''odo, Betueli ono Nakhori andrö, ononia khö Milika andrö. Ba utema ube''e ba nikhunia naya andrö, ba ba mbulökhania.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 48, 'Ba ufaöndrö ndra''o, mangalulu khö Yehowa, usuno Yehowa, Lowalangi zokhö ya''o, Aberahamo, me no i''oroma''ö khögu lala, si lö elungu ndra''o, lala ba wangai ono dalifusö zokhö ya''o, khö nononia.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 49, 'Ba na edöna atö ami, mihakhösi tödö zokhö ya''o, na lö edöna faröi ami khönia, ba mi''ombakha''ö khögu; ba na lö''ö, ba mi''ombakha''ö zui khögu, ena''ö ufulido, ma ba gambölö, ba ma gabera usaŵa.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 50, 'Ba latema linia ira Labano Betueli, lamane: Moroi khö Yehowa da''ö! Tebai maŵa''ö hadia ia, he si lö sökhi, ba he si sökhi.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 51, 'Ya''e khöu Rebeka; ohe ia ba ae''e, ena''ö fo''omo nono zokhö ya''ugö ia, si mane niŵa''ö Yehowa.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 52, 'Ba me irongo niŵa''öra andrö sawuyu Gaberahamo andrö, ba mangalulu ia khö Yehowa irugi danö tou.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 53, 'Ba isao''ö baero sawuyu andrö naya ana''a ba aya firö ba nukha, ibe''e buala khö Rebeka; ba khö ga''ania ba khö ninania, ba ibe''e göi naya.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 54, 'Ba manga ira ba mamadu hadia ia, ya''ia ba awönia fao, ba mörö ira ba da''ö.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 55, 'Ba lamane ira ga''a Rebeka inania: Akha mowongi na ma''ifu ba da''e nono alawe, ma irege fulu bongi, ba hana na mofanö ia.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 56, 'Ba imane khöra: Böi mitahado! No ifahowu''ö Yehowa we''amöigu andre, ba mi''efa''ö ndra''o, ena''ö ufulido khö zokhö ya''o.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 57, 'Ba lamane: Ba damuhede ita khö nono alawe, khönia tasofu!', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 58, 'Ba humede ira khö Rebeka, lamane khönia: Hadia, edöna''ö möi awö niha andre?', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 59, 'Ba lafofanö sa''ae dalifusöra Rebeka andrö, awö zamaenu ya''ia föna ba sawuyu Gaberahamo andrö ba awönia fao.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 60, 'Ba lafahowu''ö Rebeka, lamane khönia: He si akhi! Ya oya ngahönö ma''uwumö dania, ba yala''aro''ö khöra dania mbawa göli nemalira nga''ötömi!', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 61, 'Ba mangefa Rebeka, awö ngoni-ngoninia, möi ira yaŵa ba hulu gondra ba la''o''ö niha no mege; ba i''ohe Rebeka sawuyu no mege ba mofanö.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 62, 'Ba no möi ba "mba''a zauri, samaigi ya''odo" Giza''aki; ba danö si raya sa soso ia.[3]', '["Faigi 16:14"]', NULL),
  (3422589, 'OT', 'Moze I', 24, 63, 'Ba samuza ma''ökhö, ba no möi ba mbenua Giza''aki mangandrö, me tanö-tanö owi. Ba me ifaöga hörönia, ba i''ila gondra moroi sa.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 64, 'Ba me ifakhölö ia Rebeka, ba i''ila Giza''aki.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 65, 'ba imane khö zawuyu andrö: Ha niha da''ö, samaondragö ya''ita ba mbenua?', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 66, 'Ba idunö-dunö khö Giza''aki sawuyu andrö wolaunia fefu.', '[]', NULL),
  (3422589, 'OT', 'Moze I', 24, 67, 'Ba i''ohe baose Rebeka Iza''aki, baose ninania Sara, ihalö ia ba tobali fo''omonia ba itugu i''omasi''ö; ba terara dödö Giza''aki ba wa''amate ninania.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 1, 'Ba ifuli mangai ira alawe Aberahamo, Ketura döi,', '["Nga''ötI 1:32"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 2, 'ba mo''ono da''ö khönia: Simera ba Yokisa ba Medano ba Midiano ba Yisibaki ba Sua.[1]', '["Nga''ötI 1:32"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 3, 'Ba ono Yokisa, ba Seba ba Dedano; ba ma''uwu Dedano Ndrawa Asuri andrö ba Dawa Letusi ba Dawa Loimeni.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 4, 'Ba ono Midiano, ba Efa ba Eferi ba Hanokhi, ba Abida ba Elida''a; oi iraono Getura andrö da''ö.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 5, 'Ba hadia ia zi so khönia, fefu, ba ibe''e khö Giza''aki Aberahamo.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 6, 'Ba ba ndraono ndrongania ba döi, khönia, ba mamuala Gaberahamo ba ifofanö ira, ifabali khö nononia Iza''aki, me auri ia na, ifofanö ba danö tanö ba gatumbukha luo.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 7, 'Ba da''ö wa''anau noso Gaberahamo, si so ia ba guli danö: 175 fakhe.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 8, 'Ba aetu noso Gaberahamo, mate ia ba wa''atua omasiö, no atua ia ba no aföli fa''auri; ba te''orudugö ia ba niwara.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 9, 'Ba lako''o ia ononia Iza''aki ba Sima''eli ba dögi narö hili Makhefela andrö, ba mbenua Ndraono Kheti andrö, Eferono, ono Zohara, ba gamaudu Mamere.', '["Faigi 23:19"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 10, 'Ba mbenua andrö, ni''öli Gaberahamo ba Ndraono Kheti: ba da''ö teko''o Gaberahamo ba fo''omonia Sara.[2]', '["Faigi 23:19"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 11, 'Ba me no mate Gaberahamo, ba ifahowu''ö nononia Iza''aki Lowalangi. Ba ba ngai "mba''a zauri, samaigi ya''odo" soso Giza''aki.[3]', '["Faigi 24:62"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 12, 'Ba da''ö nga''ötö Zima''eli andrö, ono Gaberahamo, ononia ba Ndrawa Miserayi andrö, Hagara, sawuyu yomo khö Zara.', '["Faigi 17:20"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 13, 'Da''e döi nono Zima''eli, wanötöi ya''ira, ngenolira: Si a''a khö Zima''eli, ba Nebayoti, ba Kedara ba Adibe''eli', '["Faigi 17:20"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 14, 'ba Mibisa ba Misima ba Duma ba Masa,', '["Faigi 17:20"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 15, 'ba Hadadi ba Tema ba Yeturi ba Nafisi ba Kedema.', '["Faigi 17:20"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 16, 'Da''ö nono Zima''eli andrö, ba da''ö döira, ba mbanuara andrö, ba naha nosera: felendrua zalaŵa, ba niwara andrö.[4]', '["Faigi 17:20"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 17, 'Ba fa''anau noso Zima''eli andrö, ba 137 fakhe. Ba aetu nosonia, mate ba te''orudugö ba niwara.', '["Faigi 16:12"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 18, 'Ba nahiara, banuara, ba i''otarai Hawila, numalö ba Zuri, tanö ba gatumbukha, na ta''otarai danö Miserayi, irugi misa danö Ndrawa Asiria; tanö ba gatumbukha mowanua ia föna-föna dalifusönia fefu.[5]', '["Faigi 16:12"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 19, 'Ba da''ö khö Giza''aki, ono Gaberahamo: Ono Gaberahamo Giza''aki.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 20, 'Ba öfa wulu fakhe Giza''aki, me ihalö Rebeka andrö, ono Ndrawa Garamo andrö, Betueli, ba Mezofotamia, akhi Ndrawa Garamo andrö, Labano.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 21, 'Ba mangandrö Giza''aki khö Yehowa ba khö wo''omonia andrö, me no si lö ono. Ba ifondrondrongo wangandrönia Yehowa, ba manabina wo''omonia Rebeka [si faero].', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 22, 'Ba fagobi-gobi nononia ba dalunia; ba imane: Na si manö, ba hana wa aurido? Ba möi ia musofu khö Yehowa.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 23, 'Ba imane khönia Yehowa: Dombua soi ba dalumö; dombua mado zi tumbu khöu dania, ba wasuwöta. Ba abölö dania mado si sambua, ba sawuyu zi akhi dania zi a''a.[6]', '["Rom 9:12"]', NULL),
  (3424834, 'OT', 'Moze I', 25, 24, 'Ba me irugi baŵania ba wo''ono, ba hiza zi faero ba dalunia.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 25, 'Ba böla zi a''a, no oyo-oyo, hulö mbaru luo sobubu, ma''asageu. Andrö wa labe''e töinia Gezau.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 26, 'Ba böla göi nakhinia andrö, ba no igogohe mbörö sisi Gezau tangania; andrö wa labe''e töinia Yakobo.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 27, 'Ba me manöi ndraono andrö, ba tobali sabölö ba wealu Gezau, niha ba ndru''u, ba Yakobo, ba niha sahono-hono, si iagö ose.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 28, 'Ba Iza''aki, ba i''omasi''ö Gezau, ami khönia gahulua andrö; ba Rebeka, ba i''omasi''ö Yakobo.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 29, 'Ba samuza ma''ökhö, ba ituge''ö gönia Yakobo.', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 30, 'Ba imane Ezau khö Yakobo: Ta''i-ta''i be''e ögu zoyo andrö, soyo andrö we! solofo sibai sa''ae ndra''o. Andrö wa labe''e töinia Gedomo (Soyo).', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 31, 'Ba imane Yakobo: Amawa khögu wa''asia''amö ua!', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 32, 'Ba imane Ezau: A! mate sa atö ndra''o dania, ba ha uwai wa''asia''a andrö!', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 33, 'Imane Yakobo: Ba ae ba hölu ua khögu!', '[]', NULL),
  (3424834, 'OT', 'Moze I', 25, 34, 'Ba ibe''e khö Gezau roti ba samösa mö''ö harita side-ide; ba manga ia, ba ifazaŵa ia, ilau mofanö. Ba tobali i''ositengagö wa''asia''ania Ezau.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 1, 'Ba itörö lofo danö andrö, — lö lai lofo föna, ba götö Gaberahamo — ba isaŵa Gabimelekhi, razo Ndrawa Wilisiti, Iza''aki, ba Gerara.[1]', '["Faigi 12:10"]', NULL),
  (3426284, 'OT', 'Moze I', 26, 2, 'Ba i''oroma''ö ia khönia Yehowa imane: Böi ae misi tou ba danö Miserayi! Iagö danö, niŵa''ögu khöu dania.', '["Faigi 12:3; 15:5; 22:18"]', NULL),
  (3426284, 'OT', 'Moze I', 26, 3, 'Ya si fatewu ndra''ugö ba danö andre, ba utolo-tolo''ö ba ufahowu''ö ndra''ugö, khöu sa ba ba ma''uwumö ube''e danö andre fefu, ba lö uwu''ai zi no möido ba hölu khö namau Aberahamo.', '["Faigi 12:3; 15:5; 22:18"]', NULL),
  (3426284, 'OT', 'Moze I', 26, 4, 'Ba ato sibai dania ma''uwumö ube''e, fa''oya ndröfi ba mbanua yaŵa, ba ube''e ba ma''uwumö dania danö da''e fefu, ba moroi ba ma''uwumö tefahowu''ö dania fefu soi ba guli danö,[2] böli gölö,', '["Faigi 12:3; 15:5; 22:18"]', NULL),
  (3426284, 'OT', 'Moze I', 26, 5, 'me no i''o''ö niŵa''ögu Aberahamo, ba me no itöngöni fefu nibe''egu li khönia, oroisagu andrö ba amakhoitagu ba famobawagu lala.', '["Faigi 12:3; 15:5; 22:18"]', NULL),
  (3426284, 'OT', 'Moze I', 26, 6, 'Ba sahono ba Gerara Giza''aki.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 7, 'Ba me lasofu wo''omo Giza''aki banua da''ö bakha, ba imane: Akhigu. Ata''u sa''ae ia i''ombakha''ö wa fo''omonia, imane: Ma dania labunu ndra''o, banua da''e, börö Rebeka andrö, me no si sökhi sibai bawa ia.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 8, 'Ba me no ara ma''ifu ia ba da''ö, ba ifaigi ba zandrela Abimelekhi, razo Ndrawa Wilisiti andrö, ba i''ila, me fawude Giza''aki khö wo''omonia Rebeka.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3426284, 'OT', 'Moze I', 26, 9, 'Ba ifakaoni''ö Giza''aki Abimelekhi, imane: Ba fo''omou ia ya''ö? Ba hana wa tola öŵa''ö: Akhigu?', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 10, 'Ba imane Abimelekhi: Hadia nilaumö khöma! No ahatö orudu khö wo''omou niha bö''ö, ha niha ia, ba no öfatörö khöma horö sebua mena''ö.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 11, 'Ba ibe''e li ba mbanuania Abimelekhi, imane: Ha niha zombambaya niha da''ö ba fo''omonia, ba nibunu.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 12, 'Ba manaru Giza''aki ba danö andrö, ba mamasi, dua wulu zamba yöu mbua, ifahowu''ö sa''ae ia Yehowa.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 13, 'Ba tobali mo''ana''a ia, itugu tedou-dou manö gana''ania, irege ebua sibai.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 14, 'Ba mongawawa khönia mbiri-biri ba mongawawa zaŵi ba ato sibai zawuyunia, tobali afökhö dödö Ndrawa Wilisiti khönia.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 15, 'Ba no lahawui Dawa Wilisiti mba''a andrö fefu, nikharu zawuyu namania, ba götö namania Aberahamo, no lafo''ösi tanö.[3]', '["Faigi 21:25"]', NULL),
  (3426284, 'OT', 'Moze I', 26, 16, 'Ba imane Abimelekhi khö Giza''aki: Heta''ö ba khöma, noa sa töra wa''abölöu khöma!', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 17, 'Ba iheta ia ba da''ö Iza''aki, ba ndraso ba Gerara itaru''ö nosenia, ba da''ö i''iagö.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 18, 'Ba ifuli ifakharu''ö Iza''aki mba''a andrö, nikharura ba götö namania Aberahamo, ba nihawui Ndrawa Wilisiti, me no mate Gaberahamo, ba ifuli ifotöi, töi nifatörö namania mege.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 19, 'Ba lakharu danö sawuyu Giza''aki, ba ndraso, ba lasöndra gumbu ba da''ö, hele.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 20, 'Ba lafasosoni gubalo khö Giza''aki kubalo ba mbanua Gerara, lamane: Khöma nidanö andrö! ba ibe''e töi gumbu andrö "Ezeki", me no fasoso ira khönia.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 21, 'Aefa da''ö, ba lakharu mba''a bö''ö, ba ba da''ö göi fasoso, andrö ibe''e töinia "Zitina".', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 22, 'Ba iheta ia ba da''ö, ifa''ese ia ba ifakharu''ö mba''a bö''ö. Ba ba da''ö, ba lö fasosota, andrö ibe''e töinia "Rehoboti", imane: Noa sa''ae ifaigi khöda naha sebolo Yehowa, fa ta''ila tabologö ita ba danö!', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 23, 'Ba iheta ia ba da''ö, isaŵa miyaŵa Mbereseba.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 24, 'Ba i''oroma''ö ia khönia Yehowa: ba zi bongi andrö, imane: Lowalangi namau Aberahamo ndra''odo! Böi busi dödöu, utolo sa ndra''ugö; ba ufahowu''ö ndra''ugö ba ato dania ma''uwumö ube''e, börö genonigu Aberahamo.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 25, 'Ba ifa''anö naha wame''e sumange ba da''ö, i''angaröfi li döi Yehowa ba itaru''ö nosenia ba da''ö.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 26, 'Ba möi khönia Gabimelekhi, awö Gahusati, anofulania, awö Wikholo kumandra andrö khönia, la''otarai Gerara.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 27, 'Ba imane khöra Iza''aki: Hadia wa möi ami khögu, me noa sa atö si fa''udu ami khögu, ba me no mifofanö ndra''o ba khömi?', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 28, 'Lamane: Noa sa ma''ila, wa no itolo-tolo''ö Yehowa, ba no maŵa''ö, sökhi na fawu''u li ita, na faoma möi ita ba hölu khö nawöda,', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 29, 'fawu''u li ita, wa lö ölau khöma zi lö sökhi, si mane ya''aga, me lö nibabayama ya''ugö ba me ha sambalö si sökhi nilauma khöu, me no ma''efa''ö ndra''ugö, malau khöu hadia ia. Nifahowu''ö Yehowa sa atö ndra''ugö!', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 30, 'Ba ifodiwo ira, ba manga ira ba labadu hadia ia.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 31, 'Ba mahemolu mbanua, ba faoma möi ira ba hölu, khö nawöra, ba ifofanö ira Iza''aki, ba laröi ia, lö hadia ia.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 32, 'Ba me luo da''ö, ba so zawuyu Giza''aki la''ombakha''ö khönia, he wisa mba''a andrö, nikhaora, lamane khönia: No masöndra nidanö!', '["Faigi 21:31"]', NULL),
  (3426284, 'OT', 'Moze I', 26, 33, 'Ba ibe''e töinia Zeba (fahölusa); ba da''ö moroi, wa Bereseba döi mbanua andrö, irugi ma''ökhö.[4]', '["Faigi 21:31"]', NULL),
  (3426284, 'OT', 'Moze I', 26, 34, 'Ba me no öfa wulu fakhe Gezau, ba ihalö Yudita, ono Ndraono Kheti andrö, Be''eri, ba Basimata, ono Ndraono Kheti, Elono.', '[]', NULL),
  (3426284, 'OT', 'Moze I', 26, 35, 'Ba langu dödö ndra Iza''aki Rebeka galawe andrö.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 1, 'Ba me no atua Giza''aki ba me no abösi hörönia, fa lö''ö sa''ae i''ila niha, ba humede ia khö nononia si a''a Ezau, imane khönia: He onogu!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 2, 'Ba imane [Iza''aki]: Atua sa''ae ndra''odo, ba lö u''ila, ha wa''ara matedo.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 3, 'Ba halö wangönau ba wealu, naha nono wana, awö wana, ae ba mbenua ba halö khögu gahulua;', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 4, 'ba haogö ögu, somasido ba ohe khögu si bakha andre, ena''ö u''a, ba ufahowu''ö ndra''ugö, gasa-gasa wa''amategu.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 5, 'Ba no ifondrongo-ndrongo Rebeka, me iŵa''ö da''ö Iza''aki khö nononia Ezau.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 6, 'ba imane Rebeka khö nononia Yakobo: Faefa urongo, me humede namau khö ga''au Ezau, me imane khönia:', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 7, 'Halö khögu gahulua ba haögö ögu, ena''ö u''a, ba ufahowu''ö ndra''ugö, ba zanehe Yehowa, gasa-gasa wa''amategu.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 8, 'Ba iya''e, ya''ugö onogu, ba o''ö niŵa''ögu, wamobawa lala khöu!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 9, 'Ae ba nambi ba halö khögu ba da''ö zi matua nono nambi si sökhi, dua rozi, ena''ö uhaogö, ö namau, somasi ia.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 10, 'Ba ö''ohe dania khö namau si bakha, ena''ö i''a, ba ifahowu''ö dania ndra''ugö, gasa-gasa wa''amatenia.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 11, 'Ba imane Yakobo khö ninania Rebeka: Hiza, ba no mobu sibai ga''agu Ezau, ba ya''o, ba si lö bu.[1]', '["Faigi 25:25"]', NULL),
  (3428671, 'OT', 'Moze I', 27, 12, 'Ma dania ibayaisi ndra''o amagu, ba tobali sango''aya ya''ia ndra''odo, ba tohare khögu wangelifi ube''e, ba tenga howu-howu!', '["Faigi 25:25"]', NULL),
  (3428671, 'OT', 'Moze I', 27, 13, 'Ba imane khönia inania: Khögu yatohare wangelifi andrö, si göna ndra''ugö ena''ö, onogu; o''ö manö niŵa''ögu, ae halö khögu.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 14, 'Ba möi ia muhalö, ba i''ohe khö ninania; ba ihaogö inanania, ö namania, somasi ia.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 15, 'Ba ihalö nukha nononia si a''a Rebeka, nukha si sökhi khönia, si so khönia si bakha, ba ibe''e nukha nononia si akhi, Yakobo.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 16, 'Ba uli nono nambi andrö, ba ibe''e ba dangania ba ba mbaginia, si no alösö-lösö.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 17, 'Ba ibe''e ba danga nononia Yakobo gö no mege, fabaya roti nibogönia.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 18, 'Ba möi ia si bakha khö namania, imane: He ama! Imane: Ya''e ndra''odo!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 19, 'Ba imane Yakobo khö namania: Ezau ndra''odo, onou si a''a; no''u''o''ö niŵaöu khögu. Ba dadao ba a gahulua andre khögu, ena''ö öfahowu''ö ndra''o dania!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 20, 'Ba imane Iza''aki khö nononia: Ha lö alio ösöndra, onogu!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 21, 'Ba imane Iza''aki khö Yakobo: Hatö''ögö we, onogu, ena''ö u''ila ubabaya nösiu, na si ndruhu onogu Ezau ndra''ugö, ba na tenga!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 22, 'Ba ihatö''ö ia khö namania Iza''aki Yakobo, ba me no ibayaisi, ba imane: Li andrö, ba no li Yakobo, ba ta''io, ba no ta''io Gezau.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 23, 'Ba lö i''ila, wa ya''ia, me no mobu da''ionia, si mane ta''io ga''ania Ezau; ba ifahowu''ö ia.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 24, 'Ba imane: Hadia, onogu Ezau ndra''ugö?', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 25, 'Ba imane: Ba ohe khögu, ena''ö u''a gahulua andrö, khö nonogu, ba ufahowu''ö dania ndra''ugö!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 26, 'Aefa da''ö, ba imane khönia amania Iza''aki: Ae ba da''e, ago mbawagu, onogu!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 27, 'Ba me ihatö''ö ia, me fa''ago bawa ya khönia, ba i''ago hua nukhania; ba ifahowu''ö ia, imane: Sindruhu, hua nonogu andrö, ba no hulö hua mbenua, nifahowu''ö Yehowa!', '["Heb 11:20","Faigi 25:23; MozIV 24:9"]', NULL),
  (3428671, 'OT', 'Moze I', 27, 28, 'Yamube''e khöu Lowalangi namo moroi ba mbanua si yaŵa, ba tanö satabö sinanö, ba yamuhöna khöu mbua nowi, awö nagu.[2]', '["Heb 11:20","Faigi 25:23; MozIV 24:9"]', NULL),
  (3428671, 'OT', 'Moze I', 27, 29, 'Ndramöi sawuyumö soi niha ba yamangalulu khöu ngawalö mado. Samatörö talifusöu fefu dania ndra''ugö, ba ya mangalulu khöu ndraono ninau. Ha niha zangelifi ya''ugö, ba ni''elifi da''ö; ba samahowu''ö ya''ugö, ba nifahowu''ö?[3]', '["Heb 11:20","Faigi 25:23; MozIV 24:9"]', NULL),
  (3428671, 'OT', 'Moze I', 27, 30, 'Ba me no i''o''ozui Iza''aki wamahowu''ö Yakobo ba me ha si''aikö iröi namania Iza''aki Yakobo, we''amöi baero, ba so ga''ania Ezau, moroi fafana.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 31, 'Ba i''asiwai göi gö, i''ohe si bakha khö namania, ba imane khö namania: Faoso, ama, ba a gahulua andre khö nonou, ena''ö öfahowu''ö ndra''o dania.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 32, 'Ba imane khönia amania Iza''aki: Ha niha ndra''ugö?', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 33, 'Ba tokea sibai Giza''aki ba imane: Ba ha niha atö zi no ahulu, solohe khögu si bakha, tobali no ahori u''a, me lö ya''ugö na, ba no ufahawu''ö ia. Ba lö''ö sa tebulö nifahowu''ö ia!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 34, 'Ba me irongo Ezau niŵa''ö namania andrö, ba mege-ege sibai ia, mu''ira-ira, ba imane khö namania: Fohowu''ö ndra''odo göi, ama![4]', '["Heb 12:17"]', NULL),
  (3428671, 'OT', 'Moze I', 27, 35, 'Ba imane: Noa sa i''onekhesi akhiu, ba no itagö howu-howu andrö khöu.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 36, 'Ba imane: Tenga sa faya, wa no labe''e töinia Yakobo; noa sa mendrua ilimodo: fa''asia''a andrö khögu, ba no ihalö, ba no itagö göi howu-howu andrö khögu!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 37, 'Ba itema li Iza''aki, imane khö Gezau: Noa sa atö ufataro samatörö ya''ugö ia, ba no ube''e barö mbawania, sawuyunia, dalifusönia fefu, ba no uhöna khönia mbua nowi, awö nagu; ba hadia atö nibe''egu khöu, onogu?', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 38, 'Ba imane Ezau khö namania: Ba hadia sa, ha da''ö howu-howu khöu, ya''ugö amagu? Fahowu''ö ndra''o göi, ama! ba mege-ege Gezau.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 39, 'Ba itema linia amania Iza''aki, imane khönia: Hiza, si lö atabö sinanö danö, ba zi so''ö ba lö tana khönia namo mbanua moroi yaŵa.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 40, 'Si''öli wangalui mbalazo khöu, ba sawuyu nakhiu ndra''ugö. Ba tobali, na ö''anösö''ö, ba ö''eŵegö galo mbagi andrö khönia, aheta ba mbagiu.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 41, 'Ba fatiu dödö Gezau khö Yakobo, ba howu-howu andrö nifa''ema namania khönia; imane dödönia Ezau: Na irugi baŵa wange''esi amagu dania, ba ubunu nakhigu Yakobo![6]', '["Obad 1:10"]', NULL),
  (3428671, 'OT', 'Moze I', 27, 42, 'Ba me te''ombakha''ö khö Rebeka wehede nononia si a''a Ezau, ba ifakaoni''ö nononia si akhi, Yakobo, imane khönia: Hiza, edöna ilau mbalönia khöu ga''au Ezau, wamunu ya''ugö.', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 43, 'Ba o''ö niŵa''ögu khöu, onogu! Faoso, oloi, saŵa ga''agu Labano, ba Harana,', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 44, 'khönia iagö maiifu, irege alö wa''abao dödö ga''au —', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 45, 'irege döhö wönu ga''au andrö khöu ba irege olifu ia nilaumö khönia; awena dania ufatenge, ufahalö''ö ndra''ugö ba da''ö. Hana wa faoma taya ami khögu, ha ma''ö-ma''ökhö!', '[]', NULL),
  (3428671, 'OT', 'Moze I', 27, 46, 'Ba imane Rebeka khö Giza''aki: Saföli fa''auri sa''ae ndra''o, börö Ndraono Kheti andrö. Na Yakobo göi dania zangai Iraono Kheti si manö, ono niha ba danö, ba hadia guna aurido na?', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 1, 'Ba humede Giza''aki khö Yakobo ba ifahowu''ö ia; ba ibe''e na li khönia, imane: Böi halö nono alawe Ndrawa Gana''ana.[1]', '["Faigi 24:3","Hos 12:13","MozV 34:4"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 2, 'Faoso, ae ba Mezofotamia, ba nomo Mbetueli, ama ninau, ba da''ö halö khöu ndra alawe, ono zibayau Labano, sambua.[2]', '["Faigi 24:3","Hos 12:13","MozV 34:4"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 3, 'Ba yamufahowu''ö ndra''ugö Lowalangi si lö ambö fa''abölö, ba yamufo''ono ndra''ugö yamu''oya''ögö, ena''ö ŵalo soi ndra''ugö!', '["Faigi 24:3","Hos 12:13","MozV 34:4"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 4, 'Ba yamube''e khöu howu-howu andrö khö Gaberahamo, khöu ba ba ma''uwumö, awöu, ena''ö okhötau dania danö andre, ba zi so ndra''ugö si fatewu, nitehe Lowalangi khö Gaberahamo.[3]', '["Faigi 24:3","Hos 12:13","MozV 34:4"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 5, 'Ba ifofanö Yakobo Iza''aki, ba isaŵa Mezofotamia, khö Labano, ono Mbetueli, Dawa Garamo, ga''a Rebeka, ina ndra Yakobo Ezau.', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 6, 'Ba me irongo Ezau, no ifahowu''ö Yakobo Iza''aki ba no ifatenge ba Mezofotamia, ena''ö ba da''ö ihalö khönia ndra alawe, wa no ifahowu''ö ia, awö wa no ibe''e li khönia, wanguma''ö: Böi halö nono alawe Ndrawa Gana''ana!', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 7, 'awö wa no ifondrondrongo Yakobo li ndra amania inania, we''amöi ba Mezofotamia,', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 8, 'ba aboto ba dödö Gezau, wa anuzu dödö namania ndra alawe Dawa Gana''ana.', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 9, 'Ba möi khö Zima''eli Gezau ba ihalö Mahalata, ono Zima''eli ono Gaberahamo andrö, talifusö Nebayoti, nönö-nönö ndrongania si tohöna.[4]', '["Faigi 36:3"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 10, 'Ba mofanö Yakobo, iheta ia ba Mbereseba, isaŵa Harana:', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 11, 'Ba irugi zi mörö ia, noa sa''ae aekhu luo. Ba sambua ihalö kara, si so ba da''ö, ibe''e tandrayania, ba ifadölö ia tou mörö ba naha andrö.', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 12, 'Ba mangifi ia, ora nifasindro ba danö sirugi banua si yaŵa zuzu, ba mangörö-ngörö ba da''ö mala''ika Lowalangi.[5]', '["Yoh 1:52"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 13, 'Ba so si yaŵa ba mbagi Yehowa, imane: Yehowa ndra''odo, Lowalangi duau Aberahamo, ba Lowalangi Giza''aki: tanö andre, si mörö ndra''ugö tou, ba khöu ube''e dania ba ba ma''uwumö.[6]', '["Faigi 35:1; 48:3"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 14, 'Ba ma''uwumö dania, ba si mane ngawua nene ba danö [wa''oya], ba mibologö dania ami tanö ba gaekhula ba tanö ba gatumbukha ba miyöu ba miraya, ba moroi khöu tefahowu''ö dania fefu soi ba guli danö, ba moroi ba ma''uwumö.', '["Faigi 35:1; 48:3"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 15, 'Ba fao-fao ndra''o khöu ba utimba khöu zi lö sökhi, fefu gofu heza möi''ö, ba u''ohe mangawuli ndra''ugö ba danö andre; lö''ö sa faröi ndra''o khöu, irege no ufalua nifabu''ugu khöu.[7]', '["Yes 43:1"]', NULL),
  (3439819, 'OT', 'Moze I', 28, 16, 'Ba tokea Yakobo, ba imane: Si ndruhu, so Yehowa ba naha andre, ba no lö u''ila!', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 17, 'Ba ata''u ia ba imane: Sihokha mbuda naha da''e; si ndruhu nahia Lowalangi da''e, bawandruhö zorugo!', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 18, 'Ba me moluo, ba ihalö gowe andrö Yakobo, tandrayania mege, ifasindro harefa, ba ifaduwa wanikha ba detenia.', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 19, 'Ba ibe''e töi naha andrö Mbetieli; Lusi döinia föna.', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 20, 'Ba ifabu''u linia Yakobo, imane: Na itolodo Lowalangi, na itimba khögu zi lö sökhi ba lala andre, nitörögu iada''e, na ibe''e gögu, ni''a, ba nukhagu, ni''onukha,', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 21, 'ba na [ibe''e] mangawuli ndra''o ba nomo namagu, lö hadia ia, ba ya Lowalangigu Yehowa.', '[]', NULL),
  (3439819, 'OT', 'Moze I', 28, 22, 'Ba gowe andre, nitaru''ögu harefa, ba ya osali Lowalangi, ba hadia ia fefu, nibe''eu khögu, ba lö zi lö ufuli khöu zambua ni''ofulu.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 1, 'Ba mofanö Yakobo, isaŵa danö tanö ba gatumbukha luo.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 2, 'Ba i''ila mba''a ba mbenua, ba mörö ba zingania mbiri-biri, tölu ngawawa, ba mba''a da''ö sa lafabadu-badugö nidanö ba mbiri-biri. Ba no musösöwui mba''a andrö gowe sebolo.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 3, 'Ba na no mu''orudugö ba da''ö ngawawa mbiri-biri fefu, ba laheta gowe andrö ba mbawa mba''a, ba lafabadugö nidanö ba mbiri-biri; ba aefa da''ö, ba lafuli ba nahania gowe, söwu-söwu mba''a.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 4, 'Ba imane khöra Yakobo: He ga''a! Ha banua ami?', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 5, 'Ba imane khöra: Hadia, mi''ila Labano andrö, ma''uwu Nakhori?', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3440083, 'OT', 'Moze I', 29, 6, 'Ba imane khöra: Hadia, lö hadia ia khönia?', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 7, 'Ba imane: Alaŵa luo na, ba tenga na inötö wolohoe urifö. Mifabadugö nidanö ba mbiri-biri ba mifuli mi''ohe ba ndru''u.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 8, 'Lamane: Tebai, balazi no ahori mu''orudugö ngawawa, awena dania laheta gowe andrö ba mbawa mba''a, ba mafabadugö ba mbiri-biri.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 9, 'Ba fatua fahuhuo ia khöra, ba no irugi Rakhela, wolohe biri-biri namania, kubalo sa ia.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 10, 'Ba me i''ila Yakobo Rakhela andrö, ono Labano andrö, ga''a ninania, awö mbiri-biri zibayania Labano, ba möi ia muheta gowe andrö ba mbawa mba''a ba ifabadugö nidanö ba mbiri-biri zibayania Labano.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 11, 'Aefa da''ö ba fa''ago bawa ia khö Rakhela, ba mege-ege sibai ia.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 12, 'Ba i''ombakha''ö khö Rakhela Yakobo, wa ono mbene''ö namania ia, ono Rebeka; ba fagohi da''ö, i''ombakha''ö khö namania.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 13, 'Ba me irongo Labano duria Yakobo andrö, turia nono nakhinia, ba fagohi ia, ba wamaondragö, italagui mbagi, fa''ago bawa ia khönia, ba i''ohe yomo, ba nomonia; ba idunö-dunö khö Labano fefu hadia ia.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 14, 'Ba imane khönia Labano: Hiza, föfö nösigu ndra''ugö!', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 15, 'Ba me no sara waŵa ia khönia, ba imane Labano khö Yakobo: Ono mbene''öma sa ndra''ugö; ba hadia, andrö mohalö-halöŵö''ö manö khögu, lö böli gölöu? ŵa''ö khögu, hadia luou.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 16, 'Ba dombua nono alawe khö Labano, Lea döi zi a''a, ba Rakhela döi zi akhi.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 17, 'Ba no abösi-bösi Lea andrö, ba Rakhela, ba si sökhi boto ba si sökhi bawa.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 18, 'Ba omasi Yakobo Rakhela andrö imane: Damohalöŵödo khöu mewitu fakhe, böli Rakhela andrö, onou si akhi.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 19, 'Imane Labano: Sökhi ube''e khöu, moroi ube''e ba niha bö''ö; iagö khögu!', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 20, 'Ba tobali mohalö-halöŵö Yakobo, böli Rakhela, mewitu fakhe; ba ba dödönia, ba hulö zi lö oya-oya ngaluo, balazi wa''omasinia ia.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 21, 'Ba aefa da''ö, ba imane Yakobo khö Labano: Be''e khögu ngambatögu, noa sa irugi döfigu — ena''ö orudu ndra''o khönia.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 22, 'Ba ikaoni mbanuara fefu Labano, ilau walöŵa.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 23, 'Ba me bongi, ba ihalö nononia Lea, i''ohe khö Yakobo si bakha, ba orudu ia khönia.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 24, 'Ba ibe''e khö nononia Lea zawuyunia ono alawe, Silifa, Labano, ngoni-ngoninia yomo.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 25, 'Ba me moluo, ba oroma [khö Yakobo] wa no Lea [nibe''e khönia]. Ba imane khö Labano: Hadia nilaumö khögu? Hadia, tenga böli Rakhela, wohalö-halöŵögu khöu?', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 26, 'Hana sa wa ölimodo?', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 27, 'Böi bulö''ögö ba da''e zi samigu andre, ba tebe''e khöu zi sambua göi, na mewitu fakhe tö mohalö-halöŵö''ö khögu.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 28, 'Ba i''o''ö da''ö Yakobo, ifalua zi samigu khönia, awena ibe''e khönia nononia Rakhela [Labano].', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 29, 'Ba ibe''e khö nononia Rakhela zawuyunia, Biliha, Labano, ngoni-ngoninia yomo.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 30, 'Ba orudu Yakobo khö Rakhela göi, ba omasi ia Rakhela, moroi khö Lea. Ba mewitu fakhe tö mohalö-halöŵö ia khö Labano.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 31, 'Ba me i''ila Yehowa, te''ositengagö Lea andrö, ba ifo''ono, ba lö''ö sa ono Rakhela.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 32, 'Manabina Lea, ba tumbu khönia nono matua, ba ibe''e töinia Rubeno, imane: Noa sa inehegö wa''anumanagu Yehowa; lö zi lö i''omasi''ö sa''ae ndra''odo fo''omogu!', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 33, 'Ba ifuli manabina, ba madono, ono matua. Ba imane: No irongo Yehowa, wa ni''ositengagö ndra''odo, andrö ibe''e khögu da''e göi. Ba ibe''e töinia Zimeoni.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 34, 'Ba ifuli manabina, ba madono, ono matua. Ba imane: Awena molemba dania khögu wo''omogu, me no tölu nonogu matua khönia; andrö ibe''e töinia Lewi.', '[]', NULL),
  (3440083, 'OT', 'Moze I', 29, 35, 'Ba samuza tö manabina ia, ba madono, ono matua zui: Ba imane: Sanuno Yehowa sa''ae ndra''odo! Andrö ibe''e töinia Yuda. Aefa da''ö, ba lö''ö sa''ae ono khönia.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 1, 'Ba me i''ila Rakhela, lö ononia khö Yakobo, ba afökhö dödönia khö ga''ania Lea, ba imane khö Yakobo: Fo''ono ndra''o — ba na lö''ö, ba matedo!', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 2, 'Ba mofönu Yakobo khö Rakhela, imane: Hadia, salahi Lowalangi ndra''o? Ya''ia zi lö mamo''ono ya''ugö!', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 3, 'Ba imane: Ya''e zawuyugu yomo, Biliha andre, odonga ia, ena''ö mo''ono ia ba gahetagu, ba ena''ö moroi khönia usöndra göi nono!', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 4, 'Ba ibe''e khönia zawuyunia yomo, Biliha andrö, donga ba döi, ba orudu khönia Yakobo.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 5, 'Ba manabina Mbiliha andrö, ba madono khö Yakobo, ono matua.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 6, 'Ba imane Rakhela: No ifaigi khögu lala Lowalangi, no ifondrondrongo khögu ba no ibe''e bualania khögu nono! Andrö wa ibe''e töinia Dano.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 7, 'Ba samuza tö manabina Mbiliha andrö, sawuyu yomo khö Rakhela, ba madono ia khö Yakobo, ono matua, sambua tö.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 8, 'Ba imane Rakhela: No fasöndra ndra''o khö ga''agu, ba wangai tödö Lowalangi, ba no abölö ndra''o! Andrö wa ibe''e töinia Nafetali.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 9, 'Ba me i''ila Lea, wa lö''ö sa''ae ono khönia, ba ihalö zawuyunia yomo, Silifa andrö, ba ibe''e khö Yakobo, donga ba döi.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 10, 'Ba mo''ono Zilifa andrö, sawuyu yomo khö Lea, khö Yakobo, ono matua.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 11, 'Ba imane Lea: Salöfö! ba ibe''e töinia Gado.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 12, 'Ba samuza tö mo''ono Zilifa, sawuyu yomo khö Lea, khö Yakobo, ono matua zui.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 13, 'Ba imane Lea: Ya''ahowu ndra''odo! Hiza, nifahowu''ö ndra alawe bö''ö sa''ae ndra''o! Andrö wa ibe''e töinia Gaseri.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 14, 'Ba ha samuza ma''ökhö, ba möi ba mbenua Rubeno, me baŵa wamasi gandru, ba isöndra dudayi, ba i''ohe khö ninania Lea.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 15, 'Ba imane: Hadia, ambö na, wa no ötagö khögu wo''omogu, hadia, öhalö na göi iada''e dudayi andrö khö nonogu?', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 16, 'Ba me so Yakobo, me bongi, me i''otarai mbenua, ba ifaondragö ia Lea, imane: Khögu si bakha möi''ö, noa sa ube''e mböliu, dudayi andrö khö nonou. Ba ba ngainia mörö ia ba zi bongi andrö.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 17, 'Ba i''o''ö khö Lea Lowalangi, tobali manabina ia ba madono khö Yakobo, ono matua, lima möi da''ö.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 18, 'Ba imane Lea: No ibe''e luogu Lowalangi, me no ululu khö wo''omogu zawuyugu yomo. Andrö wa ibe''e töimia Isasari.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 19, 'Ba ifuli manabina Lea ba madono khö Yakobo, ono matua, önö sa''ae.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 20, 'Ba imane Lea: No buala si sökhi nibe''e Lowalangi khögu, awena ebua ndra''o ba dödö wo''omogu dania, me no önö nonogu matua khönia! Andrö ibe''e töi da''ö Zebuloni.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 21, 'Ba aefa da''ö, ba mo''ono ia ono alawe, ba ibe''e töinia Dina.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 22, 'Ba itörö tödö Lowalangi Rakhela, ifondrondrongo wangandrönia Lowalangi ba ifo''ono.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 23, 'Manabina ia ba madono, ono matua. Ba imane: No iheta wa''ailagu Lowalangi.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 24, 'Andrö wa ibe''e töi nono Yosefo, imane: Yamube''e khögu zambua tö nono matua Yehowa!', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 25, 'Ba me no tumbu Yosefo andrö khö Rakhela, ba imane Yakobo khö Labano: Efa''ö ndra''o, ba wangawuli ba khöma!', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 26, 'Be''e khögu wo''omogu ba onogu, sohalö-halöŵö khöu, ena''ö mofanödo; ya''ugö sa''ae zangila, he wisa wohalö-halöŵögu khöu!', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 27, 'Ba imane khönia Labano: Na ma''ifu so so dödöu khögu — oroma khögu, wa no ifahowu''ö ndra''o Yehowa, börö ndra''ugö.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 28, 'Ba imane na: Fatö luo, ni''andröu khögu, ba ube''e khöu.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 29, 'Ba itema linia, imane: Ö''ila, he wisa wohalö-halöŵögu khöu, ba he wisa wa''atedou guriföu khögu.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 30, 'Lö''ö sa oya-oya, si so khöu, me lö ya''odo na, ba no ihötöi tedou, ba sambeka ubekai, ba fago''ö-go''ö howu-howu khöu, ibe''e Yehowa — ba iya''e, ba ha wa''ara ufaigi gaurifa zoroiyomogu andrö fefu?', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 31, 'Ba imane: Ba hadia zomasi''ö ube''e khöu?', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 32, 'Da''utöröi mbiri-biriu fefu, ma''ökhö andre ba uföfö''ö fefu, ha uga geu zogara-gara ba sombaŵa-mbaŵa — fefu zaitö ba nono-ono ba sombaŵa-mbaŵa ba sogara-gara ba nambi.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 33, 'Ba ya da''ö luogu, ba ba da''ö oroma dania wa''adölö dödögu: na öfaigi-faigi dania luogu andrö, ba sinagö fefu si faruka ba nambigu, si tenga sogara-gara ba si tenga sombaŵa-mbaŵa, ba si tenga saitö ba nono mbiri-biri khöu.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 34, 'Ba imane Labano: Lau, ya''ia da''ö niŵa''öu.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 35, 'Ba iföfö''ö [Labano], me luo da''ö zi matua sokhoi-khoi ba sombaŵa-mbaŵa, awö nambi sogara-gara ba sombaŵa-mbaŵa fefu, fefu zi so hadia ia zafusi — ba saitö ba nono-ono fefu, ba ibe''e ba danga nononia.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 36, 'Ba ifo''otalua, tölu ngaluo fofanö ba gotaluara Yakobo; ba Yakobo zokubaloi biri-biri khö Labano si tosai.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 37, 'Ba ihalö Yakobo ndraha geu sauri, bou ba bua kare ba dara ba ifokhoi-khoi, wameta uli, wangoroma''ö safusi ba ndraha andrö.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 38, 'Ba ibe''e ba luha ndraha andrö, nibo''ania uli, ba naha nidanö, ba zi möi mbiri-biri mamadu, ifaudugö ba mbiri-biri. Ba alau ba zi matua na möi mamadu idanö.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 39, 'Tobali fahömba, na so ba duduma höröra ndraha geu andrö; ba tobali sokhoi-khoi nono mbiri-biri ba sogara-gara ba sombaŵa-mbaŵa.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 40, 'Ba iföfö''ö nono andrö Yakobo, ifatahö ba mbiri-biri fefu zokhoi-khoi, awö zaitö ba mbiri-biri Labano, ba iföfö''ö khönia ngawawa, si lö i''orudugö ba mbiri-biri Labano.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 41, 'Ba ero na baŵa welowu zebua, ba ibe''e ba naha nidanö ndraha geu no mege Yakobo, ifaudugö ba mbiri-biri, ena''ö ba gamaudu ndraha geu andrö fahömba.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 42, 'Ba na sambö fa''ebua, ba lö ibe''e ndraha geu; ba tobali khö Labano zambö fa''abölö, ba khö Yakobo zabölö.', '[]', NULL),
  (3285077, 'OT', 'Moze I', 30, 43, 'Ba tobali fahöna khönia, oya sibai zi falukha ia, biri-biri ba sawuyu ono alawe ba sawuyu ono matua ba ondra ba kalide.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 1, 'Ba terongo khö Yakobo huhuo nono Labano; no lamane: No ihalö manö khönia Yakobo dana khö namada, fefu, ba ba dana khö namada mege isöndra wo''ana''a andrö, fefu.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 2, 'Ba ifaigi-faigi mbawa Labano Yakobo, ba tenga sa''ae si mane föna gamuata da''ö khönia.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 3, 'Ba imane Yehowa khö Yakobo: Fuli''ö ba danö duau ba ba niwami, ba utolo-tolo''ö.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 4, 'Ba ifatenge zinenge Yakobo, ifakaoni''ö ndra Rakhela Lea, ba we''amöi khönia ba danö ba zi so biri-biri.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 5, 'Ba imane khöra: U''ila sa''ae, wa tenga sa''ae si mane föna mbawa namami khögu, ba no itolo-tolodo Lowalangi namagu andrö.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 6, 'Ya''ami zangila, wa no a''oi dölagu wangai halöŵö namami.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 7, 'Ba no ilimodo amami; no mewulu ifalala-lala luogu; ba lö sa nitehe Lowalangi khönia fangalani ya''odo.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 8, 'Na imane: Sogara-gara luou, ba no sambawa manö zo''ono-ono sogara-gara. Ba na imane zui: Sokhoi-khoi luou, ba sambawa zo''ono-ono sokhoi-khoi.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 9, 'Ba tobali iböda khö namami gurifö andrö Lowalangi, ba ibe''e khögu.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 10, 'Ba me baŵa welowu mbiri-biri, ba u''ila ba wangifi, oroma sibai, si matua mbiri-biri andrö, si fahömba ba zi alawe, ba ahori no sokhoi-khoi ba sogara-gara ba sombaŵa-mbaŵa.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 11, 'Ba imane khögu mala''ika Lowalangi, ba wangifi: He Yakobo! Ba umane: Ya''e ndra''odo!', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 12, 'Ba imane: Faigi we, si matua mbiri-biri andrö, si fahömba ba zi alawe, ba ha sambalö sokhoi-khoi ba sogara-gara, ba sombaŵa-mbaŵa! Noa sa ahori u''ila nilau Labano khöu.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 13, 'Lowalangi ba Mbetieli no ndra''odo, ba nilaumö fanikha ba harefa andrö, ba nifabu''umö limö khögu. Ba faoso, heta''ö ba danö andre, ba fuli''ö ba khömi.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 14, 'Ba latema linia ira Rakhela Lea, lamane khönia: Hadia, so na sa dana khöma, so na zinemama ondröita ba nomo namada?', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 15, 'Hadia, tenga no niha bö''ö ndra''aga khönia, me no i''amawa ndra''aga, ba me no ara me i''a mbölima?', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 16, 'Fefu sa, zi no fahöna andrö, nifasöbi Lowalangi khö namada, ba khöda ba khö nonoda. Ba ya''ugö, ba o''ö manö fefu niŵa''ö Lowalangi khöu!', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 17, 'Ba ifakudo nononia ba fo''omonia ba hulu gondra;', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 18, 'ba i''ohe misa gurifönia andrö, awö fefu zi so khönia, nisöndrania, urifö andrö, si so khönia, nisöndrania ba Mezofotamia, ba we''amöi khö namania Iza''aki ba danö Gana''ana.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 19, 'Ba me no möi Labano, ba woguti bu mbiri-birinia, ba itema itagö ziraha namania Rakhela.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 20, 'Ba tobali ilimo Labano andrö, Dawa Garamo, Yakobo, wamini''ö khönia, wa edöna moloi ia.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 21, 'Ba moloi ia, i''ohe fefu hadia zi so khö nia; mangefa ia, i''ötö nidanö ba isaŵa hili Gileadi andrö.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 22, 'Ba dua wongi, ba te''ombakha''ö khö Labano, wa no moloi Yakobo.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 23, 'Ba i''ohe dalifusönia, igohi Yakobo, fitu ngaluo fofanö, ba ikhamö ia, ba hili Gileadi andrö.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 24, 'Ba möi khö Labano, Dawa Garamo andrö, Lowalangi, ba zi bongi, ba wangifi, imane khönia: Angelama; sambua li böi ŵa''ö khö Yakobo, si lö sökhi!', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 25, 'Ba ikhamö Yakobo Labano. Ba no itaru''ö nosenia Yakobo ba hili. Ba Labano ba talifusönia, ba no lataru''ö ba hili Gileadi andrö göi.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 26, 'Ba imane Labano khö Yakobo: Hadia da''ö, wa ölimodo öŵa''ö, wa no ö''oloi''ö nonogu andrö, amaedola nira''u ba wanuwö?', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 27, 'Hadia wa moloi''ö, nibini''ö, ba hana wa ölimodo, ba lö öfarongogö khögu, fa ufasao''ö mena''ö, fao wa''iki ba fanunö ba faritia ba biola?', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3286875, 'OT', 'Moze I', 31, 28, 'ba lö öbase''ö, fa''ago bawa ndra''o ba ma''uwugu ba ba nonogu; si ndruhu, nifolau zi lö tödö wolaumö andrö!', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 29, 'So sa ena''ö wa''abölö khögu, ba wamakao ya''ami, ba no imane khögu me owi Lowalangi namau andrö: Angelama; sambua li böi ŵa''ö khö Yakobo, si lö sökhi!', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 30, 'Ba lau ua; noa sa moloi''ö me no abölö sibai adöni dödöu ba khömi, ba hana wa no ötagö Lowalangigu?', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 31, 'Ba itema li Labano Yakobo, imane khönia: Sata''u ndra''o, umane sa''ae dödögu: ma öfasöbi khögu nonou.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 32, 'Ba nisöndra Lowalangiu andrö, ba böi ya auri! Ba zanehe talifusöda andrö bo''a-bo''ai zi so khögu, ba halö. Ba lö''ö sa i''ila Yakobo, wa no Rakhela zanagö.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 33, 'Ba möi ba nose Yakobo Labano ba ba nose Lea ba ba nose zawuyu yomo andrö, si darua, ba lö hadia ia isöndra; ba iröi nose Lea ba möi ba nose Rakhela.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 34, 'Ba no ihalö ziraha andrö Rakhela, ba no isigö''ö barö zela gondra, ba no idadaoni. Ba ibo''ai nose ma''afefu Labano, ba lö hadia ia isöndra.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 35, 'Ba imane Rakhela khö namania: He ama, böi ofönu, na tebai maosodo khöu; itörö ndra''o si mane amuata ndra alawe! Ba i''alu-alui, ba lö isöndra ziraha.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 36, 'Ba mofönu Yakobo, ihede-hede''ö Labano. Humede ia, imane khö Labano: Hadia horögu, hadia zalagu, wa no öforege wolohi ya''odo?', '["MozII 22:13"]', NULL),
  (3286875, 'OT', 'Moze I', 31, 37, 'Noa sa öbo''ai fefu nibaya-bayagu, ba hadia, no ösöndra hadia ia nibaya-bayamö? Tou''ö tou ba da''e föna dalifusögu ba föna dalifusöu, ena''ö la''etu''ö huku, ha khö zatulö ba khöda andre.', '["MozII 22:13"]', NULL),
  (3286875, 'OT', 'Moze I', 31, 38, 'Dua wulu fakhe iada''e, wa sodo khöu; lö irai alau dalu mbiri-biriu ba he nambiu, ba lö ni''agu zi matua mbiri-birimö.', '["MozII 22:13"]', NULL),
  (3286875, 'OT', 'Moze I', 31, 39, 'Hadia nisasawi gutu ndru''u, ba lö ni''ohegu khöu, no ya''odo zangali; khögu ösugi, he ba zi ma''ökhö tera''u ba he ba zi bongi.[1]', '["MozII 22:13"]', NULL),
  (3286875, 'OT', 'Moze I', 31, 40, 'Na ma''ökhö, ba ariri ndra''o ba wa''aukhu zino, ba na bongi, ba ba wa''o''afu, ba lö salau hörögu.', '["MozII 22:13"]', NULL),
  (3286875, 'OT', 'Moze I', 31, 41, 'Alo''o 20 fakhe mohalö-halöŵö ndra''o khöu: si fele''öfa fakhe ba böli nonou alawe si dombua, ba si me''önö fakhe dania, ba böli mbiri-biri andrö khöu: ba no mewulu öfalala-lala luogu.', '["MozII 22:13"]', NULL),
  (3286875, 'OT', 'Moze I', 31, 42, 'Ena''ö lö si fa''awö khögu Lowalangi duagu andrö, Lowalangi Gaberahamo, ni''ata''ufi Giza''aki göi, ba no öfofanö ndra''odo, lö noro danga! Famakaogu andrö ba fa''erege dödögu andrö, ba no i''ila Lowalangi, ba no iŵa''ö lala me owi.', '["MozII 22:13"]', NULL),
  (3286875, 'OT', 'Moze I', 31, 43, 'Ba itema li Yakobo Labano, imane khönia: Khögu ndra alawe ba khögu ndraono, ba khögu gurifö andrö ba fefu ni''ila höröu, ba khögu. Ba he uwisa ba khö nonogu alawe andrö ba ba ndraono andrö, onora?', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 44, 'Ba lau, ba talau fawu''u li, da''ö dania wamaduhu''ö khöda, darua ita.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 45, 'Ba ihalö gowe Yakobo, itaru''ö harefa.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 46, 'Ba imane Yakobo ba zi tenga bö''önia: Mi''ozaragö gowe! Ba la''ozaragö: ba labahogö, ba labe''e zumange ba dete mbaho gowe andrö.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 47, 'Ba ibe''e töinia Yegara Sahaduta Labano, ba Yakobo, ba ibe''e töinia Galeadi.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 48, 'Ba imane Labano: Baho gowe andre zi so ba mbörö khöda, darua ita — andrö wa labe''e töinia Galeadi —', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 49, 'ba Misefa (nahia zanaro), imane sa: Yamöi sanaro Yehowa ba gotaluada, na no aröu gotaluada dania!', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 50, 'Ma öfakao nonogu andrö, ba ma önönö na ira ira alawe bö''ö — na lö niha khöda, ba böi olifu ndra''ugö: Lowalangi zi so ba mbörö khöda, darua ita!', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 51, 'Ba imane na Labano khö Yakobo: Hiza, baho gowe andre ba harefa andre, nitaru''ögu ba gotaluada —', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 52, 'ba ya si so ba mbörö mbaho gowe andre ba si so ba mbörö harefa; he ya''o, ba lö tola utalu''i mbaho gowe andre, wanaŵa khöu, ba he ya''ugö, ba tebai ötalu''i mbaho gowe andre ba he harefa andre, we''amöi khögu, na si lö sökhi dödöu khögu.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 53, 'Yamöi same''e lala khöda Lowalangi Gaberahamo, Lowalangi Nakhori andrö, Lowalangi namara.', '[]', NULL),
  (3286875, 'OT', 'Moze I', 31, 54, 'Ba möi ba hölu Yakobo, ba Lowalangi, ni''ata''ufi namania Iza''aki.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 1, 'Ba mahemolu ö, ba ihulö wongi Labano fa''ago bawa ba ma''uwunia ba ba ndraononia ba i''angonasi ira. Ba maoso Labano, ifuli ia ba mbanuara.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 2, 'Ba sofanö göi Yakobo, ba falukha khönia mala''ika Lowalangi.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 3, 'Ba imane Yakobo, me i''ila ira: Sabölö khö Lowalangi da''ö. Andrö wa ibe''e töi naha andrö Mahana''i.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 4, 'Ba ifowaö-waö zinenge Yakobo, khö ga''ania Ezau, ba Ze''ira, ba danö Ndraono Gedomo!', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 5, 'ibe''e li khöra, imane: Mimane khö zalaŵada Ezau: Da''ö niŵa''ö zawuyumö Yakobo khöu: Khö Labano so so ndra''o, ba no arörödo ba da''ö, irege iada''e.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 6, 'Ba no falukhado zaŵi ba kalide ba biri-biri ba sawuyu ono matua, ba sawuyu ono alawe, ba ufatenge iada''e, ba wamarongogö turia khöu, ya''ugö sokhö ya''odo, ena''ö öbologö dödöu khögu.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 7, 'Ba mangawuli zinenge andrö khö Yakobo, lamane: Falukhaga khö ga''au Ezau, ba lala sa''ae so ia, ba wamaondragö ya''ugö, ba öfa ngaotu nawönia fao.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 8, 'Ba ata''u sibai Yakobo, mogikhi dödönia. Ba ifosasi niha, si fao khönia, ba biri-biri ba saŵi ba ondra, ifodua mbawa.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 9, 'Imane sa dödönia: Na ihawui zi sambawa Ezau, na i''ö''ötö, ba i''ila sa''ae moloi si sambawa.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 10, 'Ba imane Yakobo: He ya''ugö, Lowalangi duagu andrö, Lowalangi namagu Iza''aki, Yehowa, sanguma''ö khögu: Fuli''ö ba khömi, ba niwami, ba ufaigi lala, fa''ohahau dödöu.[1]', '["SamII 7:18","Faigi 28:14"]', NULL),
  (3286877, 'OT', 'Moze I', 32, 11, 'Sambö ndra''odo, ba wa''ebua dödöu andrö, fefu, ba ba wa lö faröi ndra''ugö, fefu, si no falukha genoniu andre khöu. Ha sara si''o khögu, me u''ötö Yoridano andre, ba iada''e, ba dua mbawa gamatöröŵagu.', '["SamII 7:18","Faigi 28:14"]', NULL),
  (3286877, 'OT', 'Moze I', 32, 12, 'Efa''ö ndra''o ba danga ga''agu andrö, ba danga Gezau; ata''udo sa ia; fa böi möi ia, mangö''ötö ya''aga, he ina, ba he iraono![2]', '["SamII 7:18","Faigi 28:14"]', NULL),
  (3286877, 'OT', 'Moze I', 32, 13, 'Ba ya''ugö, ba no öfabu''u, wanguma''ö: Ufaigi lala, fa lö hadia ia khöu, ba ato sibai ma''uwumö dania ube''e, fa''oya ngawua nene ba mbewe nasi, si tebai te''erai fa''oya!', '["SamII 7:18","Faigi 28:14"]', NULL),
  (3286877, 'OT', 'Moze I', 32, 14, 'Ba mörö ia ba da''ö. Ba i''oniagö ösa zi so khönia andrö, buala khö ga''ania Ezau:', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 15, '200 nga''eu nambi si alawe, ba 20 zi matua, ba 200 nga''eu biri-biri si alawe ba 20 zi matua,', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 16, 'ba 30 nga''eu ondra, si bohou mo''ono, awö nono, ba 40 ono-ono zaŵi, ba 10 rozi ono zaŵi si matua, si bohou ebua ba 20 nga''eu kalide si alawe ba 10 rozi ono galide.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 17, 'Ba ibe''e ba danga zawuyunia da''ö, samba-sambawa, i''oniagö, ba ibe''e li ba zawuyunia, imane: Mi''owaö-waö ba mifo''ota-otalua ngawawa andrö!', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 18, 'Ba ifobawa lala ba zi so föna, imane: Na falukha khöu ga''agu Ezau ba na isofu khöu: Ha khö ndra''ugö ba heza möi''ö ba ha khö da''ö fönau? ba ömane:', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 19, 'Buala zawuyumö Yakobo khö zokhö ya''o, Ezau; ba ya''ia, ba moroi furima sibai.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 20, 'Ba si manö göi wanguma''önia khö wanete da''ö, ba khö wanete zi darua ba ba danö bö''ö fefu, solohe ngawawa andrö, imane: Mimanö göi khö Gezau, na falukha ami khönia, ba mimane:', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 21, 'Sawuyumö Yakobo andrö, ba moroi furima sibai. Imane sa dödönia: Da''u''alösi dödönia buala andrö, sowaö-waö fönagu, ba awena dania falukha ndra''o khönia, ma atö ibologö dödönia khögu.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 22, 'Ba tobali mowaö-waö mbuala andrö, fatua so ia na ba golombaseŵa, ba zi bongi andrö.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 23, 'Ba ba zi bongi andrö, ba maoso ia, i''ötö götöna ba Yaboko andrö, i''ohe wo''omonia si dombua ba sawuyu yomo andrö, si darua ba ononia andrö, si felezara.', '["Hos 12:4"]', NULL),
  (3286877, 'OT', 'Moze I', 32, 24, 'I''ohe miyefo ira ba ifa''ötö fefu hadia ia zi so khönia.[3]', '["Hos 12:4"]', NULL),
  (3286877, 'OT', 'Moze I', 32, 25, 'Ba ha Yakobo zi toröi furi. Ba so zi fasöndra khönia, irege tobaha fa''amoluo.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 26, 'Ba me i''ila da''ö, tebai ilaŵa, ba itema ifalisi zolania, tobali fabesu zola Yakobo, me fasöndra ia khönia.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 27, 'Ba imane da''ö no mege: Böhölido, tobaha fa''amoluo!', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 28, 'Ba imane khönia: Ha niha döimö!', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 29, 'Ba imane: Lö''ö sa''ae labe''e töimö Yakobo, Izeraeli sa''ae döiu, me no fasöndra''ö khö Lowalangi ba ba niha, ba me no ya''ugö zabölö.[4]', '["MozII 3:13; Sanguhuk 13:18"]', NULL),
  (3286877, 'OT', 'Moze I', 32, 30, 'Ba mangandrö Yakobo, imane: Ombakha''ö khögu döimö!', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 31, 'Ba ibe''e töi naha andrö Wenieli Yakobo, imane: Me no fa''ila bawa ndra''o khö Lowalangi ba me lö si matedo.[5]', '["Faigi 16:13; Sin 80:4"]', NULL),
  (3286877, 'OT', 'Moze I', 32, 32, 'Ba me no italu''i Wenieli andrö, ba tumbu luo; ba sakela-kela ia, ba zolania andrö.', '[]', NULL),
  (3286877, 'OT', 'Moze I', 32, 33, 'Andrö wa lö la''a Iraono Gizeraeli nuo andrö ba dete zola, irugi ma''ökhö, me no ifalisi zola Yakobo, uo andrö.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 1, 'Ba i''ila Yakobo so moroi sa Gezau, ba öfa ngaotu nawönia fao, ba ifosasi ndraono khö Lea ba khö Rakhela, ba ba zawuyu yomo andrö, si darua.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 2, 'Ba ibe''e tanö föna zawuyu andrö, awö nonora ba furira Lea, awö nononia ba furi da''ö Rakhela, awö Yosefo.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 3, 'Ba ya''ia, ba mowaö-waö, ba mewitu ifaöndrö ia, irege danö tou, awena irugi ga''ania.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 4, 'Ba fagohi Gezau, wamaondragö ya''ia, italagui mbagi ba fa''ago bawa khönia, ba mege-ege ira.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 5, 'Ba me ifakhölö ia Ezau, me i''ila ndra alawe, awö ndraono, ba imane: Ba ha niha da''ö, awöu?', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 6, 'Ba la''ondrasi sawuyu yomo andrö, awö nonora, mangalulu khönia.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 7, 'Awena i''ondrasi göi Lea, awö nononia, mangalulu, ba awena Yosefo ba Rakhela ba mangalulu.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 8, 'Ba imane: Ba hadia guna ngawawa andrö, si falukhado?', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 9, 'Ba imane Ezau: No abönö khögu; hana na khöu zi so khöu, akhi!', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 10, 'Imane Yakobo: Böi, na so ba dödöu ndra''o ma''ifu, ba lö tola lö ötema khögu game''elagu! Noa sa atö u''ila mbawau, hulö mbawa mbanua zorugo, me no öbologö dödöu khögu.[1]', '["Amaed 16:7"]', NULL),
  (3291877, 'OT', 'Moze I', 33, 11, 'Halö atö khögu mbuala fangowai andrö; si no mu''ohe khöu; noa sa ifahowu''ö sibai ndra''odo Lowalangi, no fahöna manö khögu. Ba iforege khönia, balazi ihalö.', '["Amaed 16:7"]', NULL),
  (3291877, 'OT', 'Moze I', 33, 12, 'Aefa da''ö, ba imane: Tafazaŵa ita, mofanö ita; ba sowaö-waö ndra''o khöu.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 13, 'Ba imane Yakobo: I''ila sokhö ya''o, wa no sambö fa''abölö na ndraono, ha ba mbiri-biri ba ba zaŵi, ba so zi bohou mo''ono, ba he ha ma''ö-ma''ökhö uforege khöra, ba ahori mate, sambawa manö.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 14, 'Akha mowaö-waö föna zawuyunia zokhö ya''o; ba ya''odo, ba lö uda''i-da''i wofanö, dali wa''abölö gurifö andrö, ni''ohegu, ba fa''abölö ndraono, irege urugi zokhö ya''o, ba Ze''ira.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 15, 'Ba imane Ezau: Ba da''uröi atö awöu nawögu ösa.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 16, 'Ba mangawuli Gezau, me luo da''ö, isawa Ze''ira.', '[]', NULL),
  (3291877, 'OT', 'Moze I', 33, 17, 'Ba Yakobo, ba isaŵa Zukota, ba itaru''ö nomonia. Ba nahia gurifö, ba ose daha geu itaru''ö. Andrö wa labe''e töi mbanua andrö Zukota.', '["Faigi 28:21"]', NULL),
  (3291877, 'OT', 'Moze I', 33, 18, 'Ba dania, ba irugi Zikhema andrö Yakobo, lö hadia ia, Sikhema ba danö Gana''ana; me i''otarai Mezofotamia. Ba föna-föna mbanua itaru''ö nosenia.[2]', '["Faigi 28:21"]', NULL),
  (3291877, 'OT', 'Moze I', 33, 19, 'Ba benua andrö, nitaru''önia osenia, ba i''öli khö nono Hemori andrö, Ama Zikhema 100 kesita mböli.', '["Faigi 28:21"]', NULL),
  (3291877, 'OT', 'Moze I', 33, 20, 'Ba ifa''anö ba da''ö naha wame''e sumange ba ibe''e töinia "Eli, Lowalangi Gizeraeli".', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 1, 'Ba samuza ma''ökhö, me möi mangero Dina andrö, ono Lea, ononia khö Yakobo, me möi mamaigi ono niha ba danö alawe,', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 2, 'ba i''ila ia Sikhema, ono Ndrawa Hewi andrö, Hemori, salaŵa ba danö andrö, ba ira''u, orudu ia khönia, ihoröni.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 3, 'Ba molemba sibai dödönia khö Dina andrö, ono Yakobo, omasi ia nono alawe andrö, itandraigö irara dödönia.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 4, 'Ba i''andrö khö namania Hemori Sikhema, imane: Sofu khögu nono alawe andrö, ena''ö uhalö!', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 5, 'Ba no irongo Yakobo, wa no ihoröni nononia Dina; ba ononia matua, ba no lafasao ba ndru''u gurifö, ba ihonogö manö ia Yakobo, irege mangawuli ira.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 6, 'Ba möi khö Yakobo Hemori, Ama Zikhema, ba wahuhuosa khönia.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 7, 'Ba me so nono Yakobo, si otarai mbenua ba me larongo, ba abao sibai dödöra, tesao wönura sabölö-bölö. Ba dödö Ndraono Gizeraeli, ba no horö sebua nifazökhinia, me no orudu ia khö nono Yakobo; lö''ö manö sa tola zi manö mena''ö![1]', '["MozV 22:21"]', NULL),
  (3293409, 'OT', 'Moze I', 34, 8, 'Ba humede Hemori, imane khöra: Tödö nonogu Sikhema andrö, ba no molemba khö nono alawe andrö, akhimi; u''andrö khömi, mibe''e ia khönia,', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 9, 'hana na olembatama ami. Mibe''e khöma nonomi alawe, ba mihalö nono alawe khöma, ba mi''iagö khöma:', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 10, 'ya''e fönami danö, mi''iagö ba midörö-döröi, hana na tetaro ami ba danö!', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 11, 'Ba imane Sikhema khö nama Dina andrö ba khö ndra ga''ania: Ena''ö na falukhado wa''ebua dödö wamaigimi! Gofu ha wa''ebua niŵa''ömi, ba ube''e.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 12, 'He ebua sibai niŵa''ömi khögu, böwö ba buala, ba ube''e, u''o''ö niŵa''ömi; ba mibe''e fo''omogu nono alawe andrö!', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 13, 'Ba latema li Zikhema ba li namania Hemori ono Yakobo, la''onekhesi, me no ihoröni nakhira Dina, lamane khöra:', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 14, 'Tebai matehe, ihalö nakhima niha si lö muboto; saila ndra''aga sa da''ö.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 15, 'Awena tola ma''o''ö khömi, na mibali''ö si mane ya''aga ami, wamoto fefu motöi matua ba khömi.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 16, 'Ba mabe''e sa''ae khömi nono alawe khöma ba mahalö nono alawe khömi ba ma''iagö khömi, ena''ö ha sambua soi ita.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 17, 'Ba na lö mi''o''ö da''ö, wamoto ya''ami, ba ma''ohe nono alawe khöma, ba malau mofanö!', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 18, 'Ba atulö dödö ndra Hemori Sikhema, ononia, niŵa''öra andrö.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 19, 'Ba i''aliogö wolau si manö ono matua andrö, me no omasi ia nono Yakobo, ba no sebua töi ia ba zi sawu ya''ira.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 20, 'Ba möi ba mbawa göli Hemori ba ononia andrö, ba lamane ba mbanuara:', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3293409, 'OT', 'Moze I', 34, 21, 'Si sökhi tödö khöda niha andrö: akha mowanua ira ba danöda ba hana na ladörö-döröi; tenga sa atö sambö nahara danö, gofu he tanö la''iagö! Tahalö nonora alawe ba tabe''e khöra nono alawe khöda.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 22, 'Ba awena la''o''ö niha andrö, wangiagö khöda, ena''ö ha sambua soi ita, na lafaboto''ö ira dozi motöi matua ba khöda, si mane ya''ira, me no muboto ira.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 23, 'Khöda dania zi so khöra, nibaya-bayara ba uriföra, fefu. Ba data''o''ö khöra, ena''ö böi labulö''ö ira khöda!', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 24, 'Ba la''o''ö niŵa''ö Hemori ba ononia Sikhema dozi sanörö-nörö bawa göli mbanuania andrö, ba we''amöi baero ba ba we''amöi miyomo, ira matua andrö fefu, ha wa''ato zanörö-nörö bawa göli mbanuania, ba lafaboto''ö ira.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 25, 'Ba me no aefa dua wongi, me la''akhömöi, ba latuyu zi''öli ono Yakobo andrö, si darua, Simeoni ba Lewi, ga''a Dina andrö, lahawui mbanua andrö, si lö famaudu dödö, ba labunu ndra matua fefu.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 26, 'Numalö Hemori ba ononia Sikhema, labunu si''öli, ba lahalö Dina ba nomo Zikhema ba lalau mofanö.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 27, 'Ba latörö nibunu andrö ono Yakobo, larabu hadia ia khöra, me no muhoröni nakhira.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 28, 'Biri-birira ba saŵira ba kalidera, ba hadia ia ba mbanua bakha ba hadia ia baero,', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 29, 'ba larabu, awö nibaya-bayara fefu, awö ndraonora side-ide, awö ndra alawera, la''oloi''ö sawuyu, ba si so ba nomo fefu, ba larabu.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 30, 'Ba imane Yakobo khö ndra Simeoni Lewi: Famakao nifobörömi khögu, noa sa mibe''e fa''udu khögu niha ba danö, Dawa Gana''ana ba Dawa Weresi, ya''odo, si lö atoto niha barö mbawa; na la''osara''ö li dania, ba lalaŵa ndra''o, ba tehori ba danö ndra''odo, awö zoroiyomogu fefu.', '[]', NULL),
  (3293409, 'OT', 'Moze I', 34, 31, 'Ba lamane: Hadia, akha ihoröni manö nakhima?', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 1, 'Ba imane Lowalangi khö Yakobo: Labu, ae misi yaŵa ba Mbetieli, ba da''ö tebato''ö ba ba da''ö öfa''anö naha wame''e sumange khö Lowalangi sangoroma''ö ya''ia khöu, me moloi''ö no, börö ga''au Ezau.[1]', '["Faigi 28:13"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 2, 'Ba ibe''e li Yakobo ba soroiyomonia fefu ba ba zi fao-fao khönia fefu, imane: Miheta Lowalangi niha bö''ö andrö, ni''ohe-ohemi, mihaogö ami ba mifalalini nukhami,[2]', '["Faigi 31:19","Faigi 28:15"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 3, 'ena''ö möi ita misi yaŵa, ba Mbetieli, ba da''ö sa ufa''anö naha wame''e sumange ba Lowalangi andrö, si no mamondrongo ligu, me baŵa wa''atosasagu, ba si no fao-fao khögu ba lala andrö, nitörögu.[3]', '["Faigi 31:19","Faigi 28:15"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 4, 'Ba labe''e ba danga Yakobo fefu Lowalangi niha bö''ö andrö, si so khöra, fabaya saeru dalinga andrö ba dalingara, ba iko''o Yakobo ba mbörö manawa andrö ba zinga Zikhema.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 5, 'Ba aefa da''ö, ba lafazaŵa ira. Ba no ihawui fa''ata''u mbanua si tefasui ya''ira, fa''ata''u ni''asogö Lowalangi, tobali lö lagohi nono Yakobo andrö.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 6, 'Ba irugi Lusi Yakobo ba danö Gana''ana — ya''ia Mbetieli andrö — awö niha andrö fefu, si fao-fao khönia.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 7, 'Ba ifa''anö ba da''ö naha wame''e sumange ba ibe''e töi naha andrö "Lowalangi ba Mbetieli", me no ba da''ö i''oroma''ö ia khönia Lowalangi, me moloi ia no, börö ga''ania.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 8, 'Ba mate Debora, babu andrö khö Rebeka, ba lako''o ia tou Mbetieli, ba mbörö manawa; andrö wa "manawa wange''esi" döinia.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 9, 'Ba ifuli i''oroma''ö ia khö Yakobo Lowalangi, me no mangawuli ia moroi ba Mezofotamia ba ifahowu''ö ia.', '["Faigi 32:38"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 10, 'Ba imane khönia Lowalangi: Yakobo döimö; böi sa''ae labe''e töimö Yakobo, Izeraeli sa''ae döiu. Andrö wa labe''e töinia Gizeraeli.[4]', '["Faigi 32:38"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 11, 'Ba imane khönia Lowalangi: Lowalangi si lö ambö fa''abölö ndra''o; yamonga''ötö ndra''ugö ba ya oya ma''uwumö dania! Sambua soi, ŵalo soi na''i madoumö dania, ba razo zi otarai löwi-löwiu dania.[5]', '["Faigi 17:1"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 12, 'Ba tanö andrö nitehegu khö Gaberahamo ba khö Giza''aki, ba khöu ube''e ba ba ma''uwumö ube''e danö andrö.', '["Faigi 17:1"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 13, 'Ba möi miyaŵa Lowalangi, iröi ia, ba naha andrö, ba zi no muhede ia khönia.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 14, 'Ba itaru''ö harefa Yakobo, ba naha andrö, ba zi no fahuhuo ia khönia gowe [itaru''ö] ba ifaduwa ba detenia zumange nibadu ba ilau yaŵa wanikha.[6]', '["Faigi 28:18"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 15, 'Ba ibe''e töi naha andrö, ba zi no fahuhuo Lowalangi khönia, Mbetieli Yakobo.', '["Faigi 28:18"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 16, 'Ba aefa da''ö, ba lafa''ese ira, laröi Mbetieli, ba me lö aröu tö irege Geferata, ba afökhö hulu Rakhela, ba afökhö sibai khönia wadono.', '["Sangamöi talu eluahania ira''alawe sanolo ba wo''ono. Itaria göi laŵa''ö ia solomö talu ma zui solomö manö, ba so göi zanguma''ö sondrusi."]', NULL),
  (3294247, 'OT', 'Moze I', 35, 17, 'Ba me no afökhö sibai khönia, ba imane khönia sangamöi talu:[7] Böi busi dödöu, ono matua sa göi khöu iada''e!', '["Sangamöi talu eluahania ira''alawe sanolo ba wo''ono. Itaria göi laŵa''ö ia solomö talu ma zui solomö manö, ba so göi zanguma''ö sondrusi."]', NULL),
  (3294247, 'OT', 'Moze I', 35, 18, 'Ba me aetu nosonia — mate sa ia — ba ibe''e töinia "Mbenoni" ("Ono ba wa''afökhö") ba amania ba ibe''e töinia Mbeniyami.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 19, 'Ba mate Rakhela ba lako''o ia ba ngai lala ba Geferata, ya''ia Mbetilekhema andrö.', '["Gowe no tandra sasese lafasindro ba dete lewatö zatua me föna. Ba li Indonesia tola lafo''eluaha ia tugu. Ma''ökhö sasese lafasindro niha tenga gowe ba hiza gowe side-ide nifazökhi moroi ba gara ma semen (li Indonesia, nisan) si hulö röfa ma zui hulö wafa wanura yaŵania lasura döi ba baŵa wa''atumbu ba ba wa''amate zimate."]', NULL),
  (3294247, 'OT', 'Moze I', 35, 20, 'Ba itaru''ö gowe[8], tandra ba dete lewatönia, Yakobo; da''ö dandra lewatö andrö ba dete lewatö Rakhela, si lö tebulö, irugi ma''ökhö andre.', '["Gowe no tandra sasese lafasindro ba dete lewatö zatua me föna. Ba li Indonesia tola lafo''eluaha ia tugu. Ma''ökhö sasese lafasindro niha tenga gowe ba hiza gowe side-ide nifazökhi moroi ba gara ma semen (li Indonesia, nisan) si hulö röfa ma zui hulö wafa wanura yaŵania lasura döi ba baŵa wa''atumbu ba ba wa''amate zimate."]', NULL),
  (3294247, 'OT', 'Moze I', 35, 21, 'Ba ifa''ese zui ia Izeraeli, ba zi tambai Migedala Ederi itaru''ö nosenia.[9]', '["Mikh 4:8"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 22, 'Ba me soso ba danö andrö Gizeraeli, ba maoso Rubeno möi muhoröni Mbiliha andrö, donga ba döi khö namania.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 23, 'Ono Lea: Si a''a nono khö Yakobo, ba Rubeno, ba Simeoni ba Lewi ba Yuda ba Isasari ba Sebuloni.', '["Faigi 49:4; Nga''ötI 5:1"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 24, 'Ba ono Rakhela, ba Yosefo ba Beniyami.', '["Faigi 49:4; Nga''ötI 5:1"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 25, 'Ba ono Mbiliha andrö, sawuyu yomo khö Rakhela, ba Dano ba Nafetali.', '["Faigi 49:4; Nga''ötI 5:1"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 26, 'Ba ono Zilifa andrö, sawuyu yomo khö Lea, ba Gado ba Aseri. Da''ö nono Yakobo andrö, si tumbu khönia ba Mesofotamia.', '["Faigi 49:4; Nga''ötI 5:1"]', NULL),
  (3294247, 'OT', 'Moze I', 35, 27, 'Ba irugi namania Iza''aki, ba Mamere Yakobo, ba Mamere Kiriati Garaba — ya''ia Heberona andrö — ba zi soso ndra Aberahamo Iza''aki, si fatewu.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 28, 'Ba fa''ara Giza''aki ba guli danö, ba 180 fakhe.', '[]', NULL),
  (3294247, 'OT', 'Moze I', 35, 29, 'Ba mate Giza''aki, orudu ia ba niwara, atua ba no aföli fa''auri; ba lako''o ia ononia Ezau ba Yakobo.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 1, 'Da''e nga''ötö Gezau andrö, ya''ia Gedomo andrö.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 2, 'Ira alawe Ndrawa Gana''ana nihalö Gezau: Ada, ono Ndraono Kheti andrö, Elono, ba Oholibama, ono Ana andrö, ono Zibeona, Iraono Hori andrö alawe;', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 3, 'ba Basamata, ona Zima''eli, akhi Nebayoti andrö.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 4, 'Ba ono Gada andrö khö Gezau, ba Elifasi, ba ono Mbasamata, ba Regueli,', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 5, 'ba ono Goholibama, ba Yehusi ba Ya''ela ba Kora. Da''ö nono Gezau andrö si tumbu khönia ba danö Gana''ana.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 6, 'Ba ihalö wo''omonia Ezau, awö nononia matua ba ononia alawe, awö zawuyu fefu, si so baomonia, ba urifönia fefu, awö fefu zi so khönia nisöndrania ba danö Gana''ana, ba iheta ia khö nakhinia Yakobo, isaŵa danö Ze''ira.', '["Faigi 13:6"]', NULL),
  (3294250, 'OT', 'Moze I', 36, 7, 'Noa sa abölö ebua gokhötara, fa tola orudu ira mena''ö, ba ambö tanö, ba zi so ira, si fatewu, börö wa''oya guriföra andrö.[1]', '["Faigi 13:6"]', NULL),
  (3294250, 'OT', 'Moze I', 36, 8, 'Ba i''iagö hili Ze''ira andrö Ezau, Edomo andrö.', '["Nga''ötI 1:35 b.t."]', NULL),
  (3294250, 'OT', 'Moze I', 36, 9, 'Da''e nga''ötö Gezau, furugö Ndraono Gedomo andrö, ba hili Ze''ira.[2]', '["Nga''ötI 1:35 b.t."]', NULL),
  (3294250, 'OT', 'Moze I', 36, 10, 'Da''e döi nono Gezau andrö: Elifasi, ono Gada andrö, fo''omo Gezau; ba Regueli, ono Mbasamata andrö, fo''omo Gezau.', '["Nga''ötI 1:35 b.t."]', NULL),
  (3294250, 'OT', 'Moze I', 36, 11, 'Ba ono Gelifasi andrö, ba Tema ba Omara ba Sefo ba Ga''etama ba Kena.', '["Nga''ötI 1:35 b.t."]', NULL),
  (3294250, 'OT', 'Moze I', 36, 12, 'Ba Tima ndronga ba döi khö Gelifasi andrö, ono Gezau; ba mo''ono da''ö khö Gelifasi, Amaleki döi nononia. Da''ö ndraono Gada andrö, fo''omo Gezau.', '["Nga''ötI 1:35 b.t."]', NULL),
  (3294250, 'OT', 'Moze I', 36, 13, 'Ba da''e nono Regueli andrö: Nahata ba Sera ba Sama ba Misa. Da''ö ndraono Mbasamata andrö, fo''omo Gezau.', '["Nga''ötI 1:35 b.t."]', NULL),
  (3294250, 'OT', 'Moze I', 36, 14, 'Ba da''e nono Goholibama andrö, ono Ana, ono Zibeona andrö alawe, fo''omo Gezau: ononia khö Gezau, ba Yehusi ba Ya''ela ba Kora.', '["Nga''ötI 1:35 b.t."]', NULL),
  (3294250, 'OT', 'Moze I', 36, 15, 'Ba da''e zalaŵa ba ndraono Gezau: Ono Gelifasi andrö, si a''a nono khö Gezau, ba salaŵa Tema ba salaŵa Omara ba salaŵa Sefo ba salaŵa Kena,', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 16, 'ba salaŵa Kora ba salaŵa Ga''etama ba salaŵa Amaleki. Da''ö zalaŵa andrö, nga''ötö Gelifasi andrö, ba danö Gedomo. Da''ö nono Gada andrö.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 17, 'Ba da''e nono Regueli andrö, ono Gezau: Salaŵa Nahata ba salaŵa Sera ba salaŵa Sama ba salaŵa Misa. Da''ö zalaŵa andrö, nga''ötö Regueli andrö ba danö Gedomo. Da''ö ndraono Mbasamata andrö, fo''omo Gezau.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 18, 'Ba da''e nono Goholibama andrö, fo''omo Gezau: salaŵa Yehusi ba salaŵa Ya''ela ba salaŵa Kora. Da''ö zalaŵa andrö, madou Goholibama andrö, ono Ana, fo''omo Gezau.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 19, 'Da''ö ndraono Gezau ba da''ö zalaŵara; ya''ia Gedomo andrö.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 20, 'Ba da''e nono Ze''ira, Iraono Hori, niha si tohöna ba danö: Lotana ba Sobala ba Sibeona ba Ana, ba Disona ba Eseri ba Disano.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 21, 'Da''ö zalaŵa Ndraono Hori andrö, ono Ze''ira, ba danö Gedomo.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 22, 'Ba ono Lotana andrö, ba Hori ba Hemama; ba talifusö Lotana alawe, ba Tima.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 23, 'Ba da''e nono Zobala andrö: Alawana ba Manahata ba Ebala ba Sefa ba Onama.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 24, 'Ba ono Zibeona andrö, ba Aya ba Ana. Da''ö Ana andrö, sanöndra gumbu nidanö aukhu andrö ba danö si mate, me ikubaloi galide namania Zibeona andrö.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 25, 'Ba da''e nono Ana andrö: Disono; ba ono Ana alawe Goholibama andrö.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 26, 'Ba da''e nono Disono andrö: Hemeda ba Esibano ba Yitera ba Kerano.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 27, 'Ba da''e nono Geseri andrö: Bilihano ba Sawano ba Akano.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 28, 'Ba da''e nono Disano andrö: Usi ba Arano.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 29, 'Ba da''e zalaŵa Ndraono Hori: salaŵa Lotana ba salaŵa Sobala ba salaŵa Sibeona ba salaŵa Ana.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 30, 'Ba salaŵa Disona ba salaŵa Eseri ba salaŵa Disano. Da''ö zalaŵa Ndraono Hori ba wa''asalaŵara, ba danö Ze''ira andrö.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 31, 'Ba da''e zalaŵa andrö, samatörö banua Gedomo, me lö''ö na razo Ndraono Gizeraeli:', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 32, 'salaŵa ba danö Gedomo, ba Bela, ono Mbeori; ba nahiania banua, ba Dinihaba.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 33, 'Ba me no mate Mbela andrö, ba salaŵa, fangalinia Yobaba, ono Zera, banua Mbosera.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 34, 'Ba me no mate Yobaba andrö, ba salaŵa, fangalinia, Husama, Iraono Dema.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 35, 'Ba me no mate Husama andrö, ba salaŵa, fangalinia, Hadadi, ono Mbedadi; ya''ia zi fasuwö ba Ndraono Midiano, ba zalo''o andrö, ba danö Ndraono Moabi: ba nahiania banua, ba Awiti.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 36, 'Ba me no mate Hadadi andrö, ba salaŵa, fangalinia, Zamela, banua Masereka.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 37, 'Ba me no mate Zamela andrö, ba salaŵa, fangalinia, Zaulo, banua Rehoboti, ba mbewe Oiferati.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 38, 'Ba me no mate Zaulo andrö, ba salaŵa, fangalinia, Mba''alihana, ono Nakhibori.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 39, 'Ba me no mate Mba''alihana andrö, ono Nakhibori, ba salaŵa, fangalinia, Hadaro; ba töi nahiania banua, ba Fagu, ba töi wo''omonia, ba Mehetabe''eli, ono Materedi ono Mesahaba alawe.', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 40, 'Ba da''e döi zalaŵa ba ma''uwu Gezau, ba nga''ötöra ba ba mbanuara ba ba döira andrö: salaŵa Timena ba salaŵa Alawa ba salaŵa Yeteti,', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 41, 'ba salaŵa Oholibama ba salaŵa Ela ba salaŵa Fino,', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 42, 'ba salaŵa Kena ba salaŵa Tema ba salaŵa Mibesaro,', '[]', NULL),
  (3294250, 'OT', 'Moze I', 36, 43, 'ba salaŵa Magedieli ba salaŵa Iramo. Da''ö zalaŵa Ndraono Gedomo, ba nahiara ba danö, ni''okhögöra. Da''ö nga''ötö Gezau andrö, furugö Ndraono Gedomo.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 1, 'Ba ahono Yakobo ba danö, ba zi fatewu mege namania, ba danö Gana''ana andrö.[1]', '["Heb 11:9"]', NULL),
  (3294252, 'OT', 'Moze I', 37, 2, 'Ba da''ö khö Yakobo andrö: Me no mewelewitu fakhe Yosefo, ba möi-möi ia kubalo mbiri-biri, awö ndra ga''ania — ba iraono na ia — awö nono ndra Biliha Silifa, donga ba döi khö namania, ia; ba na so duria si lö sökhi khöra, ba i''ombakha''ö khö namara Yosefo.', '["Heb 11:9"]', NULL),
  (3294252, 'OT', 'Moze I', 37, 3, 'Ba omasi Gizeraeli Yosefo, moroi ba wa''omasinia nononia bö''ö fefu, me no si tumbu khönia ba wa''atuania, ba ifafazökhi''ö khönia mbaru sota''io.[2]', '["Baru sota''io eluahania ba da''a baru sebua nifola''a-la''a. Fakhili ira toga ni''owaru ndra hakim ma zui baru ndra suster ba Gereja Katolik. Amaehutania, nukha niha föna andre lö mutaba ma mutagu. Hulö nifali''ö manö ba mboto. Ba li khöda tola tetötöi mbaru Yosefo andre lembe sola''a-la''a ma zui baru sanau nifali''ö sola''a-la''a."]', NULL),
  (3294252, 'OT', 'Moze I', 37, 4, 'Ba me la''ila ira ga''ania i''omasi''ö ia amara, moroi ba wa''omasinia nononia bö''ö fefu, ba fatiu dödöra khönia ba tebai lahaogö wehedera khönia.', '["Baru sota''io eluahania ba da''a baru sebua nifola''a-la''a. Fakhili ira toga ni''owaru ndra hakim ma zui baru ndra suster ba Gereja Katolik. Amaehutania, nukha niha föna andre lö mutaba ma mutagu. Hulö nifali''ö manö ba mboto. Ba li khöda tola tetötöi mbaru Yosefo andre lembe sola''a-la''a ma zui baru sanau nifali''ö sola''a-la''a."]', NULL),
  (3294252, 'OT', 'Moze I', 37, 5, 'Ba samuza ma''ökhö, ba so wangifi Yosefo, ba itunö khö ndra ga''ania; ba tedou na watiusara khönia.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 6, 'Imane khöra: Mifondrondrongo we, hadia wangifigu andrö!', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 7, 'Halöŵöda, ba mamöbö töla wakhe ita baero ba nowi. Ba ifasindro ia ngamböbö khögu ba sumindro, ba lafasui ia ngamböbö khömi ba lafalögu tou ira, föna ngamböbö khögu.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 8, 'Ba lamane khönia ira ga''ania: Hadia, salaŵama dania ndra''ugö, samatörö ya''aga?', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 9, 'Ba samuza tö zui, ba ifuli mangifi, ba itunö khö ndra ga''ania, imane: Mifondrondrongo, no ifuli mangifido! So luo ba baŵa ba felendrua ndröfi, ba lafalögu tou ira fönagu.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 10, 'Ba me itunö da''ö khö namania, ba khö ndra ga''ania, ba itegu ia amania, imane khönia: Hadia wangifi da''ö, ni''ifiu andrö! Hadia, möiga inau ba ira ga''au, ba wamalögu tou ya''aga ba danö, fönau?', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 11, 'Ba afökhö dödö ndra ga''ania khönia, ba amania, ba itanö ba dödönia.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 12, 'Ba samuza, me no möi ndra ga''ania mokubaloi biri-biri namara ba Zikhema,', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 13, 'ba imane Izeraeli khö Yosefo: Ba Zikhema la''ohe mbiri-biri ira ga''au; labu, da''ufatenge ndra''ugö khöra! Imane: Ya''e ndra''odo!', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 14, 'Ba imane khönia: Ae''e, ba faigi, na lö hadia ia khö ndra ga''au ba ba mbiri-biri, ba fuli''ö, ba wangombakha khögu!', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 15, 'Ba falukha khönia niha, me selungu-lungu ia ba danö, imane khönia: Ha niha ni''aluimö?', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 16, 'Imane: Ira ga''agu ni''aluigu; ombakha''ö khögu, heza lakubaloi mbiri-biri iya''e!', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 17, 'Imane niha andrö: No laheta ira ba da''e, noa sa urongo, me lamane: Tasaŵa Ndrotana!', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3294252, 'OT', 'Moze I', 37, 18, 'Ba me la''ila ia moroi ba zaröu na, me lö niruginia ya''ira na, ba mamagölö ira, ba wamunu ya''ia,', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 19, 'ba faoma lamane khö nawöra: Hiza moroi sa zangifi-ngifi andrö!', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 20, 'Talabu, tabunu ia ba tatibo''ö ia ba goho-koho danö ba tamane dania: No i''a ia utu ndru''u; awena dania oroma geluaha wangifinia andrö.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 21, 'Ba me irongo da''ö Rubeno, ba edöna i''efa''ö ia ba dangara ba imane: Böi! böi tabunu ia.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 22, 'Ba imane na khöra Rubeno: Böi mibe''e aduwa ndro! Mitema mitibo''ö ia ba goho-koho danö andrö ba mbenua, ba böi sa mibabaya ia, wamunu ya''ia! Ba wangefa''ö ya''ia ba dangara, ba wamuli ya''ia khö namania.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 23, 'Ba me no irugi ndra ga''ania Yosefo, ba laheta khönia mbarunia — baru sota''io andrö, ni''obarunia —,', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 24, 'latuyu ia ba latibo''ö ba goho-koho danö andrö; ba si lö ösi goho-koho andrö, lö idanö bakha.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 25, 'Ba me no mudadao ira, ba wemanga, ba la''ila moroi sa zambawa Ndraono Zima''eli si otarai Gileadi; noro gondra khöra, ba gitö ba dalu-dalu, ni''ohe ba danö Miserayi.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 26, 'Ba imane Yuda khö ndra talifusönia: Hadia hareda, na tabunu nakhida ba na tabini''ö wamunuda ya''ia?', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 27, 'Talabu, ta''amawa ia ba Ndraono Zima''eli andrö, ba böi tahalö tangada wamunu ya''ia; noa sa akhida ia, föfö nösida. Ba latehe ira talifusönia.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 28, 'Ba me latörö Iraono Midiano andrö, saniaga andrö, ba ladöni yaŵa Yosefo moroi ba goho-koho andrö ba la''amawa ba Ndraono Zima''eli andrö, 20 rufia; ba la''ohe ba danö Miserayi Yosefo.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 29, 'Ba me möi zui ba goho-koho andrö Rubeno, ba lö''ö sa''ae bakha Yosefo.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 30, 'Ba itika nukhania, ba ifuli ia khö ndra akhinia, imane: No taya nakhida! Heza usaŵa!', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 31, 'Ba lahalö mbaru Yosefo andrö, ba lataba zi matua nambi ba la''ungugö ba ndro mbaru andrö.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 32, 'Ba lafa''ohe''ö khö namara mbaru sota''io andrö, lamane: Da''ö nisöndrama; faigi na baru nonou, ba na tenga.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 33, 'Ba me no ifaigi sibai, ba mu''ao ia: Baru nonogu! No i''a ia utu ndru''u, si manga niha! Si ndruhu, no tesasawi Yosefo!', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 34, 'Ba itika nukhania Yakobo ba i''olembe goni, ba i''aragö wange''esi ononia.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 35, 'Ba ahori möi nononia matua, awö nononia alawe, ba wondrara tödönia, ba lö edöna ia nirara tödö, imane sa: Möido mitou khö nonogu ba mbanua tou, abu dödö! Si manö wange''esi namania ya''ia.', '[]', NULL),
  (3294252, 'OT', 'Moze I', 37, 36, 'Ba Iraono Midiano andrö, ba la''amawa ia ba danö Miserayi, khö Wotifa, mandru yomo khö Wara''o, högö wazuri.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 1, 'Me luo da''ö, ba tobali ifabali ia ba dalifusönia Yuda, ba i''olembai mbanua Gadula samösa, Hira döi.', '["Nga''ötöI 2:3"]', NULL),
  (3294256, 'OT', 'Moze I', 38, 2, 'Ba da''ö dania i''ila Yuda nono Ndrawa Gana''ana alawe, Sua döi nama; da''ö ihalö ba orudu ia khönia.[1]', '["Nga''ötöI 2:3"]', NULL),
  (3294256, 'OT', 'Moze I', 38, 3, 'Ba manabina ba mo''ono, ono matua, ba ibe''e töinia Geri.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 4, 'Ba ifuli manabina, ba mo''ono, ono matua, ba Onani ibe''e töi da''ö.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 5, 'Ba furi ö, ba samuza tö mo''ono ia, ono matua, ba Sela döi da''ö khönia. Ba ba Gezibi so Yuda, me tumbu khönia da''ö.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 6, 'Ba ifatunö Geri, ononia si a''a, Yuda, Tamara döi nihalönia.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 7, 'Ba si lö omasi Yehowa nilau-lau Geri andrö, si a''a nono khö Yuda, andrö ibe''e mate ia Yehowa.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 8, 'Ba iŵa''ö khö Gonani Yuda: Ae khö ndronga ga''au ba törö khönia gömöu, ömö zi fatalifusö, ena''ö öfonga''ötö ga''au.[2]', '["MozV 25:5"]', NULL),
  (3294256, 'OT', 'Moze I', 38, 9, 'Ba me no i''ila Onani, tenga khönia dania ndraono andrö, ba itema ifiligö, ero na orudu ia khö ndronga ga''ania andrö, fa böi ifonga''ötö ga''ania.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 10, 'Ba lö omasi Yehowa wolau si manö, andrö ibe''e mate ia göi.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 11, 'Ba ibe''e li Yuda khö numönönia Tamara andrö, imane: Iagö lakha baomo khö namau, irege ebua nonogu Sela! Ata''u ia, ma mate da''ö göi, si mane ira ga''ania. Ba itema i''iagö baomo khö namania Tamara andrö.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 12, 'Ba me no ara ma''ifu, ba itema mate nono Zua andrö, fo''omo Yuda. Ba me no ahöwö mbongi wange''esi khö Yuda, ba möi ia khö zi fahuwu khönia andrö, banua Gadula andrö, Hira, misi yaŵa ba Dimena, ba wamaigi soguti bu mbiri-birinia.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 13, 'Ba me te''ombakha''ö khö Damara: Hiza, möi misi yaŵa ba Dimena namau, ba woguti bu mbiri-biri!', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 14, 'Ba iheta mbarunia, baru lakha mbanua, ba ibalugö mbawania, i''olohuni ia, ba mudadao ba zinga lala ba Gena''i, lala ba Dimena. Noa sa i''ila, wa no ebua Zela andrö, ba lö''ö zui mube''e dongania ia.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 15, 'Ba me i''ila ia Yuda, ba iwai ira alawe sabao; me no ibalugö mbawania.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 16, 'Ba ihole''ö ia khönia ba zinga lala, ba imane: Da''orududo khöu! Lö''ö sa i''ila, wa umönönia.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 17, 'Imane: ufa''ohe''ö dania khöu nono nambi si matua, na urugi ngawawa!', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 18, 'Ba imane: Hadia gade, nibe''egu khöu?', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 19, 'Ba mofanö ia, möi muheta mbalu-balu mbawania ba ifuli i''obaru mbarunia, baru lakha mbanua.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 20, 'Ba ifa''ohe''ö, nono nambi andrö Yuda khö zi fahuwu khönia andrö, banua Gadula andrö, ba wanabusi gade no mege ba ndra alawe andrö; ba lö isöndra ia.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 21, 'Ba isofu ba mbanua da''ö, imane: Heza so galawe sabao andrö, sidao-dao no ba zinga lala ba Gena''i andre? Ba lamane: Lö si möi ba da''e ira alawe sabao.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 22, 'Ba ifuli ia khö Yuda, i''ombakha''ö khönia: Lö si falukhado ia, ba lamane banua da''ö: Lö si möi ba da''e ira alawe sabao.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 23, 'Imane Yuda: Ba alakha so khönia, asala lö la''igi-igi''ö ita. No atulö ufa''ohe''ö nono nambi andrö, ba lö nisöndrau ya''ia!', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 24, 'Ba mato tölu waŵa, ba te''ombakha''ö khö Yuda: No mohorö numönöu Tamara, ba hiza, no abeto ia ba da''ö.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 25, 'Ba me no la''ohe baero ia, ba ifatenge khö namania, imane khönia: Niha sokhö da''ö zi abetosi ya''odo; ba imane na khönia: Faigi we, ha ökhö laeduru andrö ba sinali andrö ba si''o!', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 26, 'Ba me no ifaigi sibai Yuda, ba imane: Tenga sala niŵa''önia khögu; Hana sa göi, wa lö ube''e ia donga nonogu Sela! Ba lö''ö sa''ae orudu ia khönia.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 27, 'Ba me no irugi baŵa wadono khönia, ba hiza zi faero ba dalunia.', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 28, 'Ba ba wadononia andrö, ba i''oro''ö baero dangania si sara ono si sambua andrö. Ba ihalö mbana soyo sangamöi talu, ifali''ö ba danga andrö, imane: Da''e zi oföna möi baero!', '[]', NULL),
  (3294256, 'OT', 'Moze I', 38, 29, 'Ba ifuli iböda dangania, ba awena böla dalifusönia. Ba imane [sangamöi talu]: Ha lö abölö öfolala ndra''ugö! Andrö wa labe''e töinia Weresi.[4]', '["Nga''ötöI 2:4; Mat 1:3"]', NULL),
  (3294256, 'OT', 'Moze I', 38, 30, 'Ba awena böla nakhinia, si so bana soyo andrö ba danga; ba labe''e töinia Zera.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 1, 'Ba me no la''ohe ba danö Miserayi Yosefo, ba i''öli ia Fotifa, Dawa Miserayi, mandru yomo khö Wara''o, högö wazuri, ihöli ba Ndraono Zima''eli andrö, solohe ya''ia misi tou ba da''ö.[1]', '["MozI 37:36"]', NULL),
  (3294258, 'OT', 'Moze I', 39, 2, 'Ba itolo Yosefo Yehowa, tobali mofozu fefu hadia ia khönia, ba ba nomo Ndrawa Miserayi andrö, sokhö ya''ia soso ia.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 3, 'Ba me i''ila sokhö ya''ia, itolo ia Yehowa, awö wa mofozu fefu hadia ia halöŵönia, ibe''e Yehowa,', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 4, 'ba ebua sibai dödönia khö Yosefo, ba ihalö ia ngoni-ngoninia ba ifataro ia mandru yomo khönia, ba ibe''e ba dangania fefu hadia ia nibaya-bayania.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 5, 'Ba i''otarai da''ö, me no ifataro ia mandru yomo khönia ba samaigi-maigi nibaya-bayania fefu, ba ifahowu''ö Yehowa nomo Ndrawa Miserayi andrö, börö Yosefo, ba howu-howu Yehowa manö ba zi so khönia, fefu, he yomo, ba he baero.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 6, 'Ba ibe''e manö ba danga Yosefo gombayasö dangania fefu; lö ba dödönia hadia ia, ba ngai Yosefo, baero gönia, ni''a.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 7, 'Ba no si sökhi sibai mboto Yosefo ba si sökhi göi mbawania. Ba lö ara sibai, ba ileke''ö Yosefo fo''omo zokhö ya''ia ba imane khönia: Förö ba ngaigu!', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 8, 'Ba itimba, imane khö wo''omo zokhö ya''ia: Törö tödö, wa lö ba dödö zokhö ya''odo hadia ia, ba ngaigu, awö wa no ibe''e ba dangagu nibaya-bayania fefu.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 9, 'Tenga sebua moroi khögu ia yomo ba da''e, ba lö hadia ia zi lö ibe''e ba dangagu, hatö ya''ugö, me no fo''omonia ndra''ugö. Ba hadia, ulau zi lö atulö andrö, sabölö-bölö sibai, wamazökhi horö ba Lowalangi?', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 10, 'Ba he ŵa''ae ero ma''ökhö iforege khö Yosefo, ba lö i''o''ö khönia, fa orudu mena''ö ia khönia, fa mörö-mörö ba ngainia.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 11, 'Ba samuza ma''ökhö, me möi yomo Yosefo mangai halöŵö, me ha si''aikö lö niha bö''ö yomo,', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 12, 'ba ira''u mbarunia, imane: Förö ba ngaigu!', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 13, 'Ba me i''ila [alawe andrö], no iröi ba dangania mbarunia ba no moloi,', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 14, 'ba humede ia ba zi so yomo ba imane khöra: Hiza, mifaigi, no i''ohe khöda niha Heberaio andrö, ena''ö i''o''aya ita! No möi ia khögu si bakha, ba wemörö ba ngaigu; ba mu''ira-ira ndra''o.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 15, 'Ba me irongo, mu''ira-irado, ba iröi mbarunia khögu ba da''e, ba ilau moloi, isaŵa baero.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 16, 'Ba ibe''e ba ngainia mbaru Yosefo, irege so zokhö ya''ia.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 17, 'Ba imanö göi wangombakha khönia, imane: So zawuyu andrö, niha Heberaio andrö, ni''oheu khöda, möi ia si bakha khögu, ba wango''aya ya''odo.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 18, 'Ba me mu''ira-ira ndra''o, ba iröi furi khögu mbarunia, moloi ia, isaŵa baero.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 19, 'Ba me irongo sokhö ya''ia ni''ombakha''ö wo''omonia khönia, me imane: Da''ö nilau zawuyumö andrö khögu! ba mofönu sibai ia.', '["Sin 105:18"]', NULL),
  (3294258, 'OT', 'Moze I', 39, 20, 'Ba ifara''u''ö Yosefo sokhö ya''ia, ifabe''e''ö ba gurunga, ba zi so nifakuru''ö razo, ba soso ia ba da''ö ba gurunga.[2]', '["Sin 105:18"]', NULL),
  (3294258, 'OT', 'Moze I', 39, 21, 'Ba itolo Yosefo Yehowa, ibe''e la''omasi''ö ia niha bö''ö ba ebua dödö högö mandru ba gurunga khönia.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 22, 'Ba ibe''e barö mbawa Yosefo nikuru andrö högö mandru, fefu zi so ba gurunga, ba fefu hadia ia nilau ba da''ö, ba balazi ya''ia manguma''ö.', '[]', NULL),
  (3294258, 'OT', 'Moze I', 39, 23, 'Lö ifaigi-faigi högö mandru ba gurunga hadia ia nilau Yosefo, me itolo ia Yehowa. Fefu hadia ia nilaunia, ba mofozu ibe''e Yehowa.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 1, 'Ba lö ara furi ö, ba mosala zama''oli gö khö razo Miserayi ba samazökhi kue khönia, so zalara khö zokhö ya''ira, razo Miserayi.', '["Faigi 39:20"]', NULL),
  (3294259, 'OT', 'Moze I', 40, 2, 'Ba mofönu Wara''o ba ngoni-ngoninia andrö, si darua, högö zama''oli gö ba högö zamazökhi kue,', '["Faigi 39:20"]', NULL),
  (3294259, 'OT', 'Moze I', 40, 3, 'ba ifabe''e''ö ba gurunga ira ba nono högö wazuri, ba gurunga andrö, ba nikuru Yosefo,[1]', '["Faigi 39:20"]', NULL),
  (3294259, 'OT', 'Moze I', 40, 4, 'Ba ibe''e ngoni-ngonira Yosefo högö wazuri andrö; ba ara ma''ifu tetaha ira.', '["Faigi 39:20"]', NULL),
  (3294259, 'OT', 'Moze I', 40, 5, 'Ba mangifi zi darua andrö, ha sara wongi, ba fasambua geluaha wangifira, fangifi zama''oli gö ba fangifi zamazökhi kue khö razo Miserayi, si so ba gurunga.', '["Faigi 39:20"]', NULL),
  (3294259, 'OT', 'Moze I', 40, 6, 'Ba me möi si bakha khöra Yosefo, sihulöwongi, ba oroma khönia, wa lö sökhi-sökhi dödöra.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 7, 'Ba isofu khö ngoni-ngoni Wara''o andrö, nitaha awönia ba nomo zokhö ya''ia, imane: Hadia, wa mangerau mbawami ma''ökhö?', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 8, 'Ba lamane khönia: No mangifi ndra''aga ba lö sangombakha eluaha.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 9, 'Ba itunö khö Yosefo wangifinia högö zama''oli gö, imane khönia: Ba wangifigu andrö, ba so fönagu ŵeŵe nagu, uŵa''ö.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 10, 'Ba si tölu daha ŵeŵe nagu andrö. Ba me molehe ia, ba alua mbowo ba adölö mowua sasoso.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 11, 'Ba so ba dangagu mako Wara''o. Ba uhalö mbua nagu andrö, ba uferaisi ba mako khö Wara''o ba ube''e ba danga Wara''o mako.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 12, 'Ba imane khönia Yosefo: Da''ö geluaha: Daha andrö si tölu, ba no ngaluo.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 13, 'Tölu bongi tö, i''otarai ma''ökhö, ba i''efa''ö ndra''ugö Fara''o ba ifuli ifataro ndra''ugö ba nahau. Ba öfuli öbe''e ba danga Warao makonia, si mane föna, me sama''oli gö ndra''ugö khönia.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 14, 'Ba törö-törö tödöu ndra''odo, na ohahau dödöu, tolodo, wangombakha ya''o khö Wara''o, ena''ö ö''efa''ö ndra''o ba nomo andre.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 15, 'Noa sa nitagö manö ndra''o ba danö Heberaio ba ba da''e göi, ba lö horögu, wa no labe''e ba gurunga ndra''odo.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 16, 'Ba me irongo högö zamazökhi kue andrö, si sökhi geluaha andrö, ba imane khö Yosefo: Ba wangifigu, ba tölu kambu-kambu kue ba högögu, uŵa''ö.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 17, 'Ba ba gambu-kambu tanö yaŵa, ba so ngawalö gö khö Wara''o, nifazökhi duka kue; ba la''a fofo ba gambu-kambu andrö ba högögu.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 18, 'Ba itema linia Yosefo, imane: Da''ö geluaha da''ö: Kambu-kambu andrö, si tölu, ba tölu ngaluo.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 19, 'Tölu bongi tö, i''otarai ma''ökhö, ba ifa''eŵa''ö mbagiu Fara''o ba ifataŵi''ö ba döla geu, ba tobali la''a nösiu fofo.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 20, 'Ba tölu bongi aefa da''ö, me baŵa wa''atumbu Wara''o, ba ibe''e gö ngoni-ngoninia fefu. Ba ifahalö''ö miyaŵa högö zama''oli gö andrö, awö högö zamazökhi kue, ba zi so ngoni-ngoninia;', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 21, 'högö zama''oli gö andrö, ba ifuli ifataro ba halöŵönia, fa tola ifuli ibe''e ba danga Wara''o mako;', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 22, 'ba högö zamazökhi kue, ba ifataŵi''ö, itörö niŵa''ö Yosefo khöra.', '[]', NULL),
  (3294259, 'OT', 'Moze I', 40, 23, 'Ba lö''ö sa''ae itörö tödö högö zama''oli gö Yosefo, olifu ia.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 1, 'Ba mendrua fakhe aefa da''ö, ba mangifi Wara''o; ba mbewe Nilo so ia, iŵa''ö,[1]', '["Dan 2:1"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 2, 'ba möi miyaŵa moroi ba Nilo zaŵi, fitu nga''eu, si sökhi famaigi ba satabö, ba möi ira ba ndru''u mangalui göra.', '["Dan 2:1"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 3, 'Ba aefa da''ö, ba möi miyaŵa zaŵi bö''ö, fitu nga''eu göi, moroi ba Nilo, ba si lö sökhi famaigi ba sangao; ba möi ba ngai zaŵi no mege, ba mbewe Nilo.', '["Dan 2:1"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 4, 'Ba latema la''a zaŵi si sökhi andrö, satabö, saŵi si lö sökhi andrö, sangao, si fitu nga''eu — ba tokea sa''ae Wara''o.', '["Dan 2:1"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 5, 'Ba ifuli mörö, ba ifuli mangifi göi, ha sara döla wakhe, iŵa''ö, ba fitu ngalai, salua khönia, so''ösi ba si sökhi.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3294277, 'OT', 'Moze I', 41, 6, 'Aefa da''ö, ba fitu tö zalua ngalai, si lö ösi, si no ariri ba nangi moroi ba gatumbukha.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 7, 'Ba ngalai si lö ösi andrö, ba latölö ngalai si so ösi andrö, si no owulo-wulo, si fitu.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 8, 'Ba me moluo ba abu dödönia.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 9, 'Awena humede högö zama''oli gö andrö, imane khö Wara''o: Awena ma''ökhö itörö tödögu horögu.', '["Faigi 40:15"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 10, 'Mofönu no Wara''o khö ngoni-ngoninia, ba ifabe''e''ö ba gurunga ira, ba nomo högö wazuri, ya''odo andre ba högö zamazökhi kue andrö.', '["Faigi 40:15"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 11, 'Ba mangifi ndra''aga, daruaga, ha sara wongi, ba no fasambua geluaha wangifima andrö.', '["Faigi 40:15"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 12, 'Ba so ba da''ö, awöma, nono matua Heberaio, sawuyu högö wazuri; khönia matunö wangifima, ba i''ombakha''ö khöma geluaha, ifa''ele''ö sibai, hadia lawu-lawu wangifi zamösana.[2]', '["Faigi 40:15"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 13, 'Ba niŵa''önia khöma, ba no itörö: ya''odo, ba no mufuli mufataro ba halöŵögu ba ya''ia ba no mutaŵi.', '["Faigi 40:15"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 14, 'Ba ifatenge Fara''o, ifakaoni''ö Yosefo. Ba lata''i-ta''i la''efa''ö ia ba gurunga, ba ifatöwö''ö ia, ifalalini nukhania, ba möi yomo khö Wara''o.[3]', '["Sin 105:20"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 15, 'Ba imane Fara''o khö Yosefo: No mangifi ndra''o, ba lö sangila mangombakha eluaha. Ba no urongo ndra''ugö: ha örongo wangifi, ba ö''anema''ö ö''ombakha''ö geluaha.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 16, 'Ba imane Yosefo khö Wara''o: Ai, tenga, tenga ya''odo; ba ya fangorifi nifa''ele''ö Lowalangi khö Wara''o![4]', '["Faigi 40:8; Dan 2:28"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 17, 'Ba imane Fara''o khö Yosefo: Mangifi ndra''o, ba mbewe Nilo sodo, uŵa''ö.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 18, 'Ba möi miyaŵa, moroi ba Nilo, zaŵi, fitu nga''eu, satabö ba si sökhi famaigi. Ba möi ira ba ndru''u, mangalui göra.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 19, 'Ba aefa da''ö, ba möi miyaŵa zaŵi bö''ö, fitu nga''eu göi, si no oköli-köli, si lö sökhi famaigi, ba si no angao — lö urai u''ila ba danö Miserayi ma''asagörö zi manö fa lö sökhi!', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 20, 'Ba latema la''a zaŵi satabö andrö, si föföna andrö, si fitu, saŵi sangao andrö, si lö sökhi-sökhi.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 21, 'Ba he me no la''a, ba lö oroma, wa no la''a, lö''ö sa tebulö wa lö sökhi-sökhi mege.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 22, 'Ba tokea ndra''o. Ba u''ila na göi ba wangifi: ha sara döla wakhe, ba fitu zalua ngalai, so''ösi ba si sökhi.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 23, 'Ba aefa da''ö ba alua göi ngalai si lö ösi, si no oköli-köli, fitu göi, si no ariri ba nangi moroi ba gatumbukha,', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 24, 'ba latema latölö ngalai si sökhi andrö, si fitu, ngalai si no oköli-köli andrö. Da''ö nitunögu ba zi faeta andrö, ba lö sangila mangombakha eluaha khögu.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 25, 'Ba imane Yosefo khö Wara''o: Eluaha wangifi Wara''o andrö, ba no faoma. No ihönagö ifa''ele''ö khö Wara''o Lowalangi hadia nilaunia dania.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 26, 'Saŵi si sökhi andrö, si fitu nga''eu, ba mewitu fakhe, ba ngalai wakhe andrö, si sökhi, si fitu, ba mewitu fakhe göi — no faoma geluaha wangifi andrö.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 27, 'Ba saŵi safuo andrö, si fitu nga''eu, si lö sökhi-sökhi, safuria möi yaŵa, ba mewitu fakhe, ba ngalai wakhe andrö si lö ösi, si fitu, si no ariri ba nangi moroi ba gatumbukha, ba mewitu fakhe lofo, oroma dania.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 28, 'Andrö umane mege khö Wara''o: Hadia zi so ba dödö Lowalangi, nilau dania, ba no ifa''ele''ö khö Wara''o.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 29, 'Mewitu fakhe iada''e dania, ba fahöna manö hadia ia ba danö Miserayi, ma''asagörö.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 30, 'Ba na aefa da''ö, ba mewitu fakhe lofo, ba tobali olifu manö niha wa''afahöna mege, ba danö Miserayi, ba i''a danö lofo andrö.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 31, 'Ba lö''ö manö sa''ae itörö tödö niha wa''afahöna mege ba danö, balazi lofo andrö moroi furi dania, abölö-bölö sibai sa dania.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 32, 'Ba ba zi mendrua andrö, wa no fatete mendrua mangifi Wara''o, ba hiza, no ihonogöi sibai da''ö Lowalangi ba i''aliogö Lowalangi ifalua.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 33, 'Ba yamufaigi khönia Fara''o niha si so tödö, satua-tua, ena''ö ibe''e barö mbawania danö Miserayi.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 34, 'Ba yamunönö na Fara''o wamataro mandru ba danö, ena''ö la''ozaragö zambua ni''olima ba danö Miserayi, barö ndröfi andrö si fitu, ba zi fahöna bua nowi.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 35, 'Ni''owuloi mbua nowi andrö fefu, barö ndröfi andre, si fitu dania, nihöna mbua nowi ba danga Wara''o, bua nowi ba mbanua misa, ba ni''irö''ö.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 36, 'Ba ya we''e-we''e dödö ba danö nihöna andrö, ba zi mewitu fakhe andrö dania, ba lofo andrö, sanörö tanö Miserayi dania; ba tobali lö tekiko niha ba danö ba lofo andrö.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 37, 'Ba faduhu dödö Wara''o ba wehedenia andrö ba tödö ngoni-ngoninia fefu.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 38, 'Ba imane Fara''o ba ngoni-ngoninia andrö: Hadia, tasöndra na niha, si so Eheha Lowalangi ba dödö, si mane khönia?[5]', '["Dan 5:11"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 39, 'Ba imane Fara''o khö Yosefo: Me no ifa''ele''ö khöu Lowalangi da''ö fefu, ba lö''ö sa''ae niha, si manö fotödö ba si manö fa''atua-tua, si mane ya''ugö.', '["Dan 2:48; HalZin 7:10"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 40, 'Tebe''e barö mbawau nomogu ba ndramu''o''ö niŵa''öu banuagu fefu, ha irege dadaoma razo tohude ndra''o moroi khöu.[6]', '["Dan 2:48; HalZin 7:10"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 41, 'Ba imane na Fara''o khö Yosefo: Hiza, ube''e barö mbawau danö Miserayi ma''asagörö!', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 42, 'Ba iheta ba durunia laeduru andrö khönia Fara''o, ibe''e ba duru Yosefo; ba ifobaru ia baru muko karate ba ibe''e naya ana''a ba mbaginia.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 43, 'Ba ifakureta ia ba kureta razo, fanete khönia, ba mu''ao fönania niha, lamane: Mi''angalulu! Si manö wame''e Wara''o barö mbawania tanö Miserayi ma''asagörö.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 44, 'Ba imane Fara''o khö Yosefo: Fara''o ndra''odo — ba lö tola ifaliŵa dangania, ba ma ahenia, niha ba danö Miserayi ma''asagörö, na tenga ya''ugö zanguma''ö.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 45, 'Ba Fara''o andrö, ba ibe''e töi Yosefo Zafenati Faneakhi ba ibe''e khönia Gasenata, ono Wotifera, högö gere ba Gono.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 46, 'Ba tölu ngafulu fakhe Yosefo, me so ia ba da''ö föna Wara''o, razo Miserayi. Ba iröi Wara''o Yosefo ba itöröi danö Miserayi.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 47, 'Ba falawulaete mbua danö ba zi mewitu fakhe andrö, ba zi fahöna.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 48, 'Ba i''owuloi mbua nowi andrö fefu Yosefo ba zi mewitu fakhe andrö, götö wa''afahöna ba danö Miserayi, ibe''e ba mbanua misa nitenagö andrö; sambu-sambua banua ba ihöna mbua nowi andrö, si tefasui ya''ia.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 49, 'Tobali ihöna mbua nowi Yosefo, si mane ene ba mbewe nasi, tenga ono wa''oya, irege iböhöli wanu''a, tebai sa''ae lasu''a.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 50, 'Ba dombua tumbu ono matua khö Yosefo, föna ndröfi böröta lofo andrö, ononia khö Gasenata andrö, ono Wotifera, högö gere ba Gono.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 51, 'Töi zi a''a, ba Manase ibe''e Yosefo, imane: Noa sa''ae olifudo wamakaogu andrö fefu ba ira amagu ba ira talifusögu fefu, ibe''e Lowalangi.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 52, 'Ba töi zi akhi, ba Eferayi ibe''e, imane: Noa sa ifowua ndra''odo Lowalangi ba danö wamakaogu andre.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 53, 'Ba me no numalö ndröfi andrö si fitu ba zi fahöna balazo ba danö Miserayi,', '["Sin 105:16"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 54, 'ba ibörötaigö döfi lofo andrö, si fitu, itörö nihönagö Yosefo fangombakha. Ba dozi tanö itörö lofo andrö; ba ba danö Miserayi ma''asagörö, ba so mbalazo.[7]', '["Sin 105:16"]', NULL),
  (3294277, 'OT', 'Moze I', 41, 55, 'Ba me no afökhö lofo andrö ba danö Miserayi ma''asagörö, ba laforege niha sato wangandrö gö khö Wara''o.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 56, 'Ba sagörö guli danö, ba afökhö lofo andrö. Ba ibokai halasa andrö fefu Yosefo ba i''amawa ba Ndrawa Miserayi wakhe. Ba itugu tedou wa''afökhö lofo andrö ba danö Miserayi.', '[]', NULL),
  (3294277, 'OT', 'Moze I', 41, 57, 'Ba dozi niha ba guli danö, ba möi khö Yosefo ba danö Miserayi, ba wowöli fakhe; fefu gofu heza sa, ba lofo safökhö sibai.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 1, 'Ba me irongo Yakobo, ba danö Miserayi so wakhe, ba imane Yakobo khö nononia: Hadia, wa mifaigi-faigi nawömi?', '["HalZin 7:12"]', NULL),
  (3294325, 'OT', 'Moze I', 42, 2, 'Ba imane na: Hiza, no urongo, ba danö Miserayi so wakhe. Mi''ae''e mihalö khöda wakhe ba da''ö, ena''ö auri ita ba ena''ö lö mate.[1]', '["HalZin 7:12"]', NULL),
  (3294325, 'OT', 'Moze I', 42, 3, 'Ba dafulu zi möi ga''a Yosefo, ba wangai fakhe ba danö Miserayi.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 4, 'Ba Beniyami andrö, akhi Yosefo, ba lö ifa''amöi Yakobo, awö ndra ga''ania; soso dödönia, ma göna ia hadia ia.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 5, 'Ba larugi göi iraono Gizeraeli andrö, awö zi möi-möi andrö, ba wowöli fakhe; lofo sa ba danö Gana''ana.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 6, 'Ba Yosefo, si no salaŵa, ba danö, zamawa fakhe ba niha fefu. Ba me no larugi yomo ira ga''a Yosefo ba me mangalulu ira khönia, ba i''ila Yosefo,', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 7, 'wa ira ga''ania, me ha si''aikö anehe ia. Ba lö i''ombakha''ö ia khöra, i''abe''e''ö wehedenia khöra, imane khöra: Heza mi''otarai?', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 8, 'Ba i''ila Yosefo, wa ira ga''ania, ba ya''ira, ba lö la''ila, wa ya''ia.', '["Faigi 37:5 b.t."]', NULL),
  (3294325, 'OT', 'Moze I', 42, 9, 'Ba itörö tödö Yosefo wangifinia andrö, ni''ifinia nitandrösaigö khöra. Ba [i''abe''e''ö wehedenia khöra], imane khöra: Samauze ami! Möi ami mamaigi, hezo lala ba danö.[2]', '["Faigi 37:5 b.t."]', NULL),
  (3294325, 'OT', 'Moze I', 42, 10, 'Lamane khönia: Tenga, Tua! ba wowöli balazo möi zawuyumö.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 11, 'Ha sambua namama; niha sadölö tödö ndra''aga; tenga samauze zawuyumö!', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 12, 'Imane khöra: Faya! ba da''ö möi ami, ba wamaigi hezo lala ba danö!', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 13, 'Ba lamane khönia: Felendrua ndra''aga, sawuyumö andre, oi si fatalifusö, ha sambua namama, ba danö Gana''ana; si akhi, ba so khö namama ma''ökhö, ba samösa zi no taya.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 14, 'Ba imane khöra Yosefo: Si ndruhu niŵa''ögu khömi: Samauze ami!', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 15, 'Ba da''ö mifaduhu''ö ami: Faya wa no sauri Wara''o, na aefa ami ba da''e, na lö möi ba da''e nakhimi andrö, si akhi.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 16, 'Mifatenge zamösa, ba wangai akhimi; ba ya''ami, ba nitaha ba da''e. Si manö wanandraigö niŵa''ömi, na si duhu nilaumi, ba na tenga. Ba wa''aduhu wa''auri Wara''o — samauze zui ami!', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 17, 'Aefa da''ö, ba tölu ngaluo itaha ira.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 18, 'Ba me aefa dua wongi, ba imane khöra Yosefo: Mi''o''ö dae, ena''ö auri ami — niha sangata''ufi Lowalangi sa ndra''odo.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 19, 'Na niha sadölö tödö ami, ba yatoröi dalifusömi samösa, nitaha, ba nitaha ya''ami mege, ba ya''ami, ba mi''ae''e, mi''ohe wakhe andrö, soguna ö zoroiyomomi.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 20, 'Ba akhimi andrö, si akhi, ba ni''ohe ba da''e khögu, ba oroma dania, wa si duhu niŵa''ömi, ba lö mate ami.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 21, 'Ba faoma lamane khö nawöra: Si ndruhu, lua-lua horöda khö nakhida no da''e; noa sa ta''ila wa''ata''unia, me fakao ia khöda, ba lö tafondrondrongo. Andrö itörö ita fa''ata''u dödö andre.', '["Faigi 37:21"]', NULL),
  (3294325, 'OT', 'Moze I', 42, 22, 'Ba imane khöra Rubeno: Tenga no uŵa''ö khömi: böi mihalö horömi wolaumi ba ndraono andrö! Ba lö sedöna mamondrongo ami — ba iada''e telau mbalö ndronia![3]', '["Faigi 37:21"]', NULL),
  (3294325, 'OT', 'Moze I', 42, 23, 'Ba lö''ö sa la''ila, wa aboto ba dödö Yosefo niŵa''öra, me no so zangali lira, na fahuhuo ira.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 24, 'Ba ibali''ö ia, ba we''e, ba ifuli ia khöra, fahuhuo khöra. Ba ifara''u''ö Zimeoni, ba ngaira, ba ifaböbö''ö, ba zanehe ira.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 25, 'Aefa da''ö, ba iŵa''ö Yosefo lafo''ösi fakhe zi''era ba ladozigö labe''e ba zi''e bakha mböli wakhe khö zamösana ba lafa''ohe''ö na göi nifatö''öra, ba lala. Ba la''o''ö da''ö wame''e khöra.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 26, 'Ba lahare''ö ba hulu galidera wakhe andrö khöra ba mofanö ira.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 27, 'Ba me itoto''ö mböbö zi''e khönia si samösa, ba zi mörö ira, ba wame''e gö galidenia, ba i''ila gana''ania andrö, ba dete nösi zi''e khönia.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 28, 'Ba i''ombakha''ö khö ndra talifusönia, imane: No mangawuli khögu gana''agu, hiza ia ba zi''e khögu! Ba atoru dödöra, faoma lafaigi-faigi nawöra, manizi-nizi, ba lamane: Hadia nilau Lowalangi khöda ba da''ö!', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 29, 'Ba me larugi namara ba danö Gana''ana, ba ladunö-dunö khönia fefu hadia ia zi göna ira, lamane:', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 30, 'Niha andrö, si no salaŵa ba danö, ba i''abe''e''ö wehedenia khöma, ifo''esuanö ndra''aga, ba wamauze tanö möi ndra''aga, iŵa''ö.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 31, 'Ba mamane khönia: Niha sadölö tödö ndra''aga, tenga samauze ndra''aga!', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 32, 'Felendrua ndra''aga, ha sambua namama; samösa si no taya, ba fondrege zi akhi, ba so khö namama na iya''e, ba danö Gana''ana.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 33, 'Ba imane khöma niha andrö, salaŵa ba danö: Ba da''ö ya oroma khögu dania wa niha sadölö tödö ami: miröi ba da''e khögu zamösa, talifusömi! Hadia zoguna khömi, ö zoroiyomomi, fakhe, ba hana na mi''ohe, ba hana na mofanö ami.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 34, 'Ba mi''ohe ba da''e nakhimi andrö, ena''ö oroma khögu, wa tenga samauze ami, wa no niha sadölö tödö ami. Ba ufuli dania khömi dalifusömi andre, ba tola mitörö danö, lö mutenaŵa.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 35, 'Ba me lafaduwa nösi zi''e khöra ba hiza mbola gana''a ba zi''e zamösana. Ba me la''ila mbola gana''a andrö, ba me i''ila göi amara, ba tobali dödöra.', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 36, 'Ba imane khöra Amara Yakobo: Taya-taya ndraonogu mibe''e: Yosefo, ba si no taya, ba Simeoni, ba si no taya, ba edöna mihalö na göi Mbeniyami — tehawu manö ndra''o da''ö fefu!', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 37, 'Ba itema li namania Rubeno, imane: Tema bunu nonogu matua si dombua, na lö ufuli ia khöu. Be''e ba dangagu ia, ba ufuli ia khöu!', '[]', NULL),
  (3294325, 'OT', 'Moze I', 42, 38, 'Ba imane: Lö fao khömi nonogu; noa sa mate ga''ania, ba hatö ya''ia zi tosai; na so ena''ö zi göna ia ba lala andrö, nitörömi, ba horömi ena''ö, na u''ohe huwagu andre, wanaŵa banua tou, oi so wa''abu dödö.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 1, 'Ba abölö-bölö na lofo ba danö.', '["Faigi 42:20"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 2, 'Ba me no ahori fefu wakhe andrö, nihalöra ba danö Miserayi, ba imane khöra amara: Mifuli mi''ae''e, ba wowöli fakhe khöda ma''ifu.[1]', '["Faigi 42:20"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 3, 'Ba imane khönia Yuda: No iŵa''ö sibai khöma niha andrö, imane: Lö tola fa''ila bawa ita, na lö mi''ohe nakhimi andrö.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 4, 'Ba na öfa''amöi awöma nakhima, ba möiga mowöli fakhe khöu.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 5, 'Ba na lö öfa''amöi ia, ba lö möiga. Noa sa iŵa''ö khöma niha andrö imane: Lö tola fa''ila bawa ita, na lö mi''ohe nakhimi andrö.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 6, 'Imane Izeraeli: Ba hana wa mifakao ndra''o wangombakha ba niha andrö, wa so na nakhimi?', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 7, 'No izofu-zofu sibai ndra''aga ba soroiyomonia niha andrö, imane: Hadia, lö si mate namami? Hadia, so nakhimi na? Ba ma''ombakha''ö khönia, lö mabini''ö zi duhu. Hadia no ma''ila, iŵa''ö dania: Mi''ohe ba da''e nakhimi andrö?', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 8, 'Ba imane Yuda khö namania Izeraeli: khögu fa''ohe''ö nono andrö, ba mafazaŵa ndra''aga, möiga, ena''ö auri ita ba böi mate, ya''aga ba ya''ugö ba iraonoma.[2]', '["Faigi 44:32"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 9, 'ya''o zi so ba wali khöu ba khönia andrö; ba hulugu öbe''e. Na lö ufuli ia khöu, na lö ufa''ila''ö khöu, ba ya''odo zolu''i sala khöu, sagötö ya''odo.', '["Faigi 44:32"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 10, 'Na lö aröröga mena''ö, si tenga inötö, ba no tola mendrua mangawuliga.', '["Faigi 44:32"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3294340, 'OT', 'Moze I', 43, 11, 'Ba imane khöra amara Izeraeli: Na lö tola lö''ö sa''ae, ba mimane: Mi''ohe ösi zi''e khömi, nisöndra ba danöda, ma''ifu, mi''ohe buala ba niha andrö: dalu-dalu ma''ifu ba ŵe ŵani ma''ifu ba gitö godu ba samohua ba bua kare ba bua falo.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 12, 'Ba mifuli mi''ohe gana''a, fa''oya mege ba ana''a andrö, nisöndra ba zuzu nösi zi''e khömi mege, ba mifuli mi''ohe — tabe''e selungu ia.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 13, 'Ba mi''ohe göi nakhimi, mifazaŵa ami ba mifuli mi''ae ba niha andrö.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 14, 'Ba Lowalangi si lö ambö fa''abölö, ba yamube''e ahakhö dödö niha andrö khömi, ena''ö ifuli ifa''amöi awömi dalifusömi si samösa andrö, awö Mbeniyami göi; ba ya''odo, ba na lö tola lö''ö, ba si lö ono sa''ae ndra''o.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 15, 'Ba la''ohe mbuala no mege ba ana''a bö''ö göi la''ohe, awö Mbeniyami, ba mangefa ira, lasaŵa danö Miserayi ba la''ondrasi Yosefo.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 16, 'Ba me i''ila Yosefo, no so Mbeniyami, awöra, ba imane ba zatua zangai halöŵö yomo: Ohe yomo niha andrö, taba ndriwora, ba halö göra, manga dania niha andrö, awögu, na laluo.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 17, 'Ba i''o''ö da''ö niŵa''ö Yosefo, i''ohe yomo ira, ba nomo Yosefo.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 18, 'Ba ata''u ira, me te''ohe yomo ira, ba nomo Yosefo, lamane: Börö gana''a andrö selungu no ba zi''e khöda, me möi ita no, si föföna, wa la''ohe yomo ita: lahawui dania ita, lara''u ita ba labali''ö sawuyu ita, fabaya kalide khöda.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 19, 'Ba la''ondrasi zatua zangai halöŵö, ba zinga mbawandruhö ba nomo, lamane khönia:', '["Faigi 31:29; 42:24"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 20, 'So ni''andröma khöu, Tua: No möiga ba da''e, si föföna no, ba wowöli fakhe.', '["Faigi 31:29; 42:24"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 21, 'Ba me no marugi zi möröga, me matoto''ö mböbö zi''e khöma, ba hiza gana''a zamösana ba zuzu nösi zi''e khönia — ana''a andrö khöma, lö ambö ba wanulo; no mafuli ma''ohe iada''e.', '["Faigi 31:29; 42:24"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 22, 'Ba ana''a bö''ö göi, no ma''ohe, ba wowöli fakhe. Lö aboto ba dödöma, ha niha zame''e ba zi''e wakhe khöma ana''a andrö,[3]', '["Faigi 31:29; 42:24"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 23, 'Ba imane khöra: Mihonogö manö ami; böi mibusi dödömi! Lowalangimi, Lowalangi namami andrö, ba no ifo''ana''a ami, nibini''ö, ba zi''e wakhe khömi. Ana''ami andrö, ba no möi khögu. Ba i''ohe baero khöra Zimeoni.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 24, 'Aefa da''ö, ba i''ohe ira ba nomo Yosefo. Ibe''e khöra nidanö, ba lasasai gahera, ba ibe''e gö galidera.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 25, 'Ba lafa''oli tou mbuala andrö, gasa-gasa wa''aso Yosefo, na laluo; noa sa terongo khöra, wa ba da''ö manga ira dania.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 26, 'Ba me no möi yomo Yosefo, ba labe''e khönia mbuala andrö, ni''ohera, ba lafaöndrö ira fönania, irege zalo tou.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 27, 'Ba isofu khöra, na lö hadia ia khöra, ba imane: He wisa, lö hadia ia khö namami, nitörö limi no. Hadia, lö si mate ia?[4]', '["Faigi 37:7"]', NULL),
  (3294340, 'OT', 'Moze I', 43, 28, 'Ba lamane: Lö''ö sa hadia khö zawuyumö andrö, amama; soso ia na. Ba lafaöndrö ira, mangalulu ira khönia.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 29, 'Ba i''ila Mbeniyami, si ndruhu nakhinia, ba imane: Hadia, da''ö nakhimi, si akhi andrö, niŵa''ömi no? ba imane [khö Mbeniyami]: yamu''ebua''ö dödönia khöu Lowalangi, onogu!', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 30, 'Ba i''ozumagö lö hede-hedenia sa''ae, ahakhö sibai dödönia, me no so tanö fönania nakhinia andrö, ba i''alui, heza zi tola me''e ia. Andrö möi ia si bakha ba mbate''e, tanö si bakha, ba mege-ege ia ba da''ö.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 31, 'Awena dania ifuli isasai mbawania ba ifuli möi baulu, i''abe''e''ö dödönia ba imane: Mifa''oli gö.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 32, 'Ba la''oniagö, khönia ba khöra, ba si manö göi ba Ndrawa Miserayi, sorudu manga khönia. Lö''ö sa tola orudu manga Ndrawa Miserayi ba niha Heberaio; salakha da''ö ba Ndrawa Miserayi.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 33, 'Ba ba gamaudunia tefedadao ira, i''otarai zi a''a, numalö ba zi akhi, balazi sibai wa''asia''a; ba faoma lafaigi-faigi nawöra, ahöli-höli dödöra.', '[]', NULL),
  (3294340, 'OT', 'Moze I', 43, 34, 'Aefa da''ö, ba ifabe''e''ö öra gö andrö si so fönania ösa; ba urakha Mbeniyami, ba no melima fa''ebua gurakha danö bö''ö fefu. Ba labadu nagu, awönia, ba sökhi dödöra.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 1, 'Ba imane Yosefo ba zatua zangai halöŵö khönia: Fo''ösi fakhe zi''e niha andrö, ndrohu-ndrohu zi tola la''ohe; ba ana''a zamösana, ba öbe''e ba zuzu nösi zi''e khönia; ba mako firö andrö khögu,', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 2, 'ba öbe''e ba zuzu nösi zi''e zi akhi, awö mböli wakhe andrö khönia.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 3, 'Ba ha moluo sibai, ba lafofanö ira, awö galidera.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 4, 'Ba ha si''aikö larugi ngai mbanua, ba imane Yosefo khö zatua zangai halöŵö khönia: Labu, gohi niha andrö, ba na ökhamö ira, ba ömane khöra: Hana wa misulöni si lö sökhi zi sökhi? Hana wa no mitagö mako firö andrö khögu?', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 5, 'Tenga ya''ia ni''amadugö zokhö ya''o, ba tenga ya''ia ba zi faeta ia? andrö wa si lö sökhi nilaumi!', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 6, 'Ba me no ikhamö ira, ba imanö khöra.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 7, 'Ba lamane khönia: He Tua, hana wa ömanö wehede? Lö''ö manö möi ba dödö zawuyumö wolau si manö.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 8, 'Hadia, tenga no mafuli ma''ohe khöu gana''a andrö, me ma''otarai danö Gana''ana, ana''a andrö nisöndra ba zuzu nösi zi''e khöma: ba he moroi, wa matagö mena''ö wirö, ba ma ana''a, yomo khö zokhö ya''ugö?', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 9, 'Nisöndra ya''ia, ba zawuyumö andre, ba ya mate, ba ya''aga tanö bö''ö, ba si möi sawuyumö.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 10, 'Ba imane: Lau, ya''ia da''ö niwa''ömi. Nisöndra ya''ia, ba sawuyugu dania, ba saefa ami.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 11, 'Ba dozi la''aliogö latou''ö tou nganu''i khöra, ba dozi latoto''ö mböbö.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 12, 'Ba ibörötaigö i''alui, i''otarai ba zi a''a ba ba zi akhi ibato, ba ba zi''e khö Mbeniyami tesöndra mako.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 13, 'Ba lasika nukhara, dozi lafuli lafonoro galidera ba lafuli ira miyomo.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 14, 'Ba me irugi yomo ba nomo Yosefo Yuda, awö dalifusönia — no so na ba da''ö Yosefo — ba lafalögu tou ira ba zalo, fönania.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 15, 'Ba imane khöra Yosefo: Hadia nilaumi andrö? Hadia, lö''ö sa itörö tödömi, i''ohe ba waetasa niha si mane ya''odo andre?', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 16, 'Ba imane Yuda: Hadia niŵa''öma khö zokhö ya''aga? Hadia huhuoma ba he mawisa wamu''a ba huluma, me no isöndra horö zawuyumö Lowalangi! Sawuyumö sa''ae ndra''aga, ya''aga andre, fabaya nisöndra mako andrö.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 17, 'Ba imane Yosefo: ya aröu khögu wolau si manö: nisöndra mako andrö, da''ö zawuyugu; ba ya''ami andrö, ba hana na mifuli ami khö namami, lö mutenaŵa.', '[]', NULL),
  (3294345, 'OT', 'Moze I', 44, 18, 'Ba ihatö''ö ia khönia Yuda, imane: He Tua! Hadia na lö ata''u zawuyumö muhede khöu, hadia, lö mofönu''ö khö zawuyumö ba da''ö? me no fagölö-gölö ami Wara''o!', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 19, 'No isofu khö zawuyunia sokhö ya''o, imane: Hadia, so na namami, so dalifusömi na?', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 20, 'Ba no mamane khöu: Lö si mate namama satua andrö ba so na nononia si akhi si tumbu moroi furi; si ndruhu ga''ania, ba no mate, ba tobali ha ya''ia zi tosai ono ninania, ba no omasiö namania.[1]', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 21, 'Ba no öŵa''ö ba zawuyumö andre: Mi''ohe ia ba da''e khögu, ena''ö i''ila ia hörögu.', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 22, 'Ba no mamane khöu: Tebai iröi namania ono matua andrö; na iröi ena''ö namania, ba lö auri da''ö.', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 23, 'Ba ömane ba zawuyumö: Na lö mi''ohe nakhimi andrö, ba tebai ifuli fa''ila bawa ita.', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 24, 'Ba me no mangawuli ndra''aga khö zawuyumö amagu, ba ma''ombakha''ö khönia niŵa''öu.', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 25, 'Ba me iŵa''ö dania khöma amama: Mifuli mi''ae''e, ba wowöli fakhe khöda ma''ifu,', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 26, 'ba mamane khönia: Tebai möiga! Na fao khöma nakhima, awena möiga; tebai sa fa''ila bawa ndra''aga ba niha andrö, na lö fao khöma nakhima.[2]', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 27, 'Ba imane khöma sawuyumö amagu: Mi''ila ya''ö, wa ha dombua nono wo''omogu khögu.', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 28, 'Si sambua, ba no iröi ndra''o, ba no umane dödögu: Si ndruhu, no tesasawi ia [ba gutu ndru''u]! ba irege ma''ökhö, ba lö ni''ila hörögu ya''ia mangawuli.', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 29, 'Ba na mihalö na da''e göi khögu, ba na göna ia hadia ia ena''ö, ba horömi, na u''ohe huwagu andre, we''amöi mitou, ba mbanua niha tou abu sibai dödö.[3]', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 30, 'Ba si ndruhu, na mangawulido ena''ö dania khö zawuyumö amagu, ba lö fao khöma nono andrö, ba zi no molemba dödönia ma''asambua,', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 31, 'ba ha si''aikö ena''ö irongo, lö''ö sa''ae fao khöma nono andrö, ba lö auri ia, ba horö zawuyumö andre ena''ö, na i''ohe huwania andrö sawuyumö amama, wanaŵa banua niha tou abu dödö.', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 32, 'Noa sa möi ba wali zawuyumö andre, khö namagu, ba khö nono andre, no ifabu''u: Na lö ufuli ia khöu, ba ya''odo zolu''i horö andrö khö namagu, sagötö ya''o.[4]', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 33, 'Ba ena''ö na tola toröi furi zawuyumö andre sawuyu zokhö ya''o salahi nono matua andrö, ba ena''ö na tola fao khö ndra ga''ania nono, wangawuli!', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3294345, 'OT', 'Moze I', 44, 34, 'He uwisa sa''ae wangawuli khö namagu, na lö fao khögu nono andrö! Tebai ufaigi-faigi ena''ö wa''abu dödö andrö, si falukha namagu!', '["Faigi 42:13 b.t.","Faigi 43:2","Faigi 42:38","Faigi 43:8"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 1, 'Ba tebai sa''ae itaha dödönia Yosefo, wamaigi si so ba ngainia, ba imane: Ndramöi baero fefu! Ba tobali lö niha bö''ö, me i''ombakha''ö ia ba dalifusönia Yosefo.[1]', '["HalZin 7:13"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 2, 'Ba mege-ege sibai ia, irege larongo Dawa Miserayi andrö, awö ngoni-ngoni Wara''o andrö.', '["HalZin 7:13"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 3, 'Ba imane Yosefo ba dalifusönia: Yosefo ndra''o! Hadia, lö si mate namada? Ba tebai latema linia ira talifusönia, ba wa''atobali dödöra khönia.', '["Faigi 37:28","Faigi 50:20","Faigi 41:40"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 4, 'Ba imane Yosefo khö ndra talifusönia: Ba mihatö''ö ami khögu! Ba me lahatö''ö ira, ba imane: Talifusömi Yosefo ndra''odo, ni''amawami ba danö Miserayi![2]', '["Faigi 37:28","Faigi 50:20","Faigi 41:40"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 5, 'Ba böi abu dödömi ba da''ö, ba böi maoso dödömi, me no mi''amawa ndra''o ba da''e; ba wangorifi sa ifowaö-waö ndra''o fönami Lowalangi.[3]', '["Faigi 37:28","Faigi 50:20","Faigi 41:40"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 6, 'No mendrua fakhe sa''ae wamakao andrö ba danö, lofo andrö, ba melima fakhe tö na fönada, si lö fananö ba si lö famasi.', '["Faigi 37:28","Faigi 50:20","Faigi 41:40"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 7, 'Ba no ifowaö-waö ndra''o fönami Lowalangi ba wamaigi lala, fa böi aetu nga''ötömi, ena''ö auri ösa ami, ba wangorifi sebua.', '["Faigi 37:28","Faigi 50:20","Faigi 41:40"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 8, 'Tobali tenga ya''ami zamatenge ya''odo ba da''e, no Lowalangi zamatenge. No ya''ia zamali''ö anofula Wara''o ndra''odo ba mandru ba nomonia ma''asambua ba samatörö tanö Miserayi ma''asagörö.[4]', '["Faigi 37:28","Faigi 50:20","Faigi 41:40"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 9, 'Ba mi''aliogö mi''ae khö namada ba mimane khönia: Da''ö niŵa''ö nonou Yosefo khöu: No ibali''ö samatörö tanö Miserayi ma''asagörö ndra''odo Lowalangi; ae khögu, böi radö''ö![5]', '["HalZin 7:14"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 10, 'Ba danö Gozena nahau dania, ba sahatö khögu ndra''ugö, awö nonou ba ma''uwumö ba biri-biri khöu ba saŵiu ba hadia ia na fefu zi so khöu.', '["HalZin 7:14"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 11, 'Ba ya''o zi''onoro tödö balazou ba da''ö; melima fakhe tö na lofo andre: ma dania numana ndra''ugö, awö zoroiyomou fefu ba awö zi so khöu fefu.', '["HalZin 7:14"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 12, 'Hörömi sa''ae zangila ba hörö nakhigu Beniyami zangila, wa ya''odo zihede khömi.', '["HalZin 7:14"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 13, 'Ba ahori mi''ombakha''ö khö namada wa''asalaŵagu andre ba danö Miserayi, awö ni''ilami andrö fefu, ba mita''i-ta''i mi''ohe ba da''e namada.', '["HalZin 7:14"]', NULL),
  (3295334, 'OT', 'Moze I', 45, 14, 'Ba italagui mbagi nakhinia Beniyami ba mege-ege; ba Beniyami göi, ba mege-ege ba mbaginia.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 15, 'Ba fa''ago bawa ia ba dalifusönia fefu ba mege-ege wanalagui ya''ira; ba fahuhuo khönia dalifusönia.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 16, 'Ba terongo khö Wara''o ba nomonia duria da''ö: no so dalifusö Yosefo! Ba omuso dödö Wara''o, awö zi soso khönia.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 17, 'Ba imane Fara''o khö Yosefo: ömane ba dalifusöu andrö: Mifonoro sa''ae galidemi, ba mi''ae ba danö Gana''ana,', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 18, 'mihalö namami ba soroiyomomi fefu, ba mi''ae ba da''e khögu, ba ube''e khömi hadia zi sökhi nisöndra ba danö Miserayi, ba mi''a zatabö, si falukha ba danö.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 19, 'Ba ya''ugö, ba öŵa''ö khöra: mimanö! Mi''ohe gureta, moroi ba danö Miserayi andre, lala ndraono sawuyu khömi ba lala wo''omomi ba mifa''amöi yaŵa namami ba mi''ae ba da''e.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 20, 'Ba böi afökhö khömi gama-gamami yomo, hadia sa zi sökhi ba danö Miserayi, ba khömi dania.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 21, 'Ba la''o''ö da''ö iraono Gizeraeli, ba ibe''e khöra gureta Yosefo, dali niŵa''ö Wara''o, ba ibe''e göi khöra nifatö''ö ba lala.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 22, 'Ba idozigö ira baru luo, buala, ba khö Mbeniyami, ba 300 rufia ba lima nga''örö baru luo ibe''e buala.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 23, 'Ba khö amania, ba fulu nga''eu kalide göi ifa''ohe''ö, sonoro fondrege zi sökhi mbua danö, ba fulu nga''eu kalide si alawe, sonoro fakhe ba roti ba nifatö''ö khö namania dania ba lala.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 24, 'Awena dania ifofanö dalifusönia ba mangefa ira, me no ibe''e na li khöra, imane: Böi fasoso ami ba lala!', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 25, 'Ba mofanö ira, laröi danö Miserayi ba larugi danö Gana''ana, namara Yakobo.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 26, 'Ba la''ombakha''ö khönia, lamane: Lö si mate Yosefo; samatörö tanö Miserayi ma''asagörö ia a''ine.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 27, 'Ba me ahori la''ombakha''ö khönia niŵa''ö Yosefo khöra, ba me i''ila gureta andrö, nifa''ohe''ö Yosefo, ba wolohe ya''ia, ba ifuli auri dödö namara Yakobo.', '[]', NULL),
  (3295334, 'OT', 'Moze I', 45, 28, 'Ba imane Izeraeli: Noa sa''ae — tenga si no mate nonogu Yosefo! Möido falukha khönia, gasa-gasa wa''amategu!', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 1, 'Ba mangefa Gizeraeli, awö zoroiyomonia fefu, ba irugi Mbereseba, ba ibe''e zumange Lowalangi namania Iza''aki, ba da''ö.[1]', '["Yos 24:4; Sin 105:23; HalZin 7:15"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 2, 'Ba mu''ao khö Gizeraeli Lowalangi, ba gangilata ba zi bongi, imane: He Yakobo! He Yakobo!', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 3, 'Ba imane: Lowalangi ndra''odo, Lowalangi namau. Böi mangiwa dödöu we''amöi ba danö Miserayi, ba da''ö sa ubali''ö soi sebua ndra''ugö.[2]', '["Faigi 26:24; 28:13"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 4, 'Ya''odo zi fao khöu ba danö Miserayi ba ya''odo göi zolohe mangawuli ya''ugö, ba Yosefo zamakifu höröu dania.', '["Faigi 26:24; 28:13"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 5, 'Ba iheta ia ba Mbereseba Yakobo, ba lafazaŵa ba gureta namara Yakobo iraono Gizeraeli, awö ndraonora sawuyu, awö wo''omora, ba gureta andrö, nifaohe''ö Wara''o, lalara.', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 6, 'Ba la''ohe guriföra ba hadia ia zi so khöra, nisöndrara ba danö Gana''ana, ba larugi, danö Miserayi, Yakobo, awö nga''ötönia fefu;', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 7, 'ononia matua ba ma''uwunia matua ba ononia alawe ba ma''uwunia alawe, nga''ötönia ma''afefu i''ohe awönia ba danö Miserayi.', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 8, 'Ba da''e döi nga''ötö Gizeraeli andrö, si fao ba danö Miserayi, Yakobo, awö nga''ötönia: Si a''a nono Yakobo Rubeno.[3]', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 9, 'Ba ono Rubeno, ba Hanokhi ba Falu ba Heseroni ba Karemi.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 10, 'Ba ono Zimeoni, ba Yemueli ba Yamino ba Ohada ba Yakhino ba Sohara; ba Saulo, ono mbene''ö Ndrawa Gana''ana andrö.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 11, 'Ba ono Lewi, ba Gereso ba Kahati ba Merari.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 12, 'Ba ono Yuda, ba Geri ba Onani ba Sela ba Feresi ba Sera; ba si mate ba danö Gana''ana Geri ba Onani. Ba ono Weresi andrö, ba Heseroni ba Hamula.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 13, 'Ba ono Isasari, ba Tola ba Fuwa ba Yobi ba Simeroni.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 14, 'Ba ono Zebuloni, ba Serede ba Elono ba Yale''eli.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3295336, 'OT', 'Moze I', 46, 15, 'Da''ö nono Lea andrö, ononia khö Yakobo ba danö Mezofotamia, awö nono alawe andrö, Dina; 33 fefu, ono matua ba ono alawe.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 16, 'Ba ono Gado, ba Safono ba Hagi ba Suni ba Esebono ba Eri ba Arodi ba Areli.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 17, 'Ba ono Gaseri, ba Yimena ba Yisiwa ba Yisiwi ba Beria ba talifusöra alawe Sera; ba ono Mberia andrö, ba Heberi ba Malekieli.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 18, 'Da''ö nono Zilifa andrö, nifa''ohe''ö Labano khö nononia Lea, ononia khö Yakobo, 16 niha fefu.[4]', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 19, 'Ba ono Rakhela andrö, fo''omo Yakobo, ba Yosefo ba Beniyami.', '["MozII 1:1; Nga''ötI 5:3","Faigi 29:24"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 20, 'Ba ono si tumbu khö Yosefo ba danö Miserayi, ononia khö Gasanata andrö, ono Wotifera, högö gere ba Gono, ba Manase ba Eferayi.[5]', '["Faigi 41:50"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 21, 'Ba ono Mbeniyami, ba Bela ba Bekheri ba Asibeli; ba Gera ba Na''ama ba Ehi ba Rosi ba Mufi ba Hufi ba Aredi.', '["Faigi 41:50"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 22, 'Da''ö nono Rakhela, ononia khö Yakobo, 14 niha fefu.', '["Faigi 29:29"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 23, 'Ba ono Dano, ba Husimi, ba ono Nafetali,', '["Faigi 29:29"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 24, 'ba Yase''eli ba Guni ba Yeseri ba Silemi.', '["Faigi 29:29"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 25, 'Da''ö nono Mbiliha andrö, nifa''ohe''ö Labano khö nononia Rakhela, ononia khö Yakobo, fitu niha fefu.[6]', '["Faigi 29:29"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 26, 'Fa''ato nga''ötö Yakobo andrö, sanaŵa tanö Miserayi, lö lai numönönia andrö, ba 66 niha.', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 27, 'Ba ono Yosefo andrö, si tumbu khönia ba danö Miserayi, ba dombua. Tobali 70 fefu zoroiyomo Yakobo andrö, sanaŵa tanö Miserayi. (MozV 10, 22. Nga''ötI 7, 14).', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 28, 'Ba ifowaö-waö Yuda, khö Yosefo, ba wanofu lala ba Gozena, fönania. Ba me no larugi danö Gozena,', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 29, 'ba ifa''anö guretania Yosefo, fakureta ia, isaŵa Gozena, ba wamaondragö amania Izeraeli. Ba me falukha ia khönia, ba italagui mbagi, ba ara mege-ege ia ba mbaginia.', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 30, 'Ba imane Izeraeli khö Yosefo: Lö''ö sa''ae afökhö khögu wa''amate, me no ifuli falukha ita, wa lö si mate ndra''ugö![7]', '["Faigi 45:28"]', NULL),
  (3295336, 'OT', 'Moze I', 46, 31, 'Ba imane Yosefo khö ndra ga''ania ba ba zoroiyomo namania: Damöido mangombakha khö Wara''o, umane dania khönia: No möi khögu ndra talifusögu ba tana khö namagu andrö, si so ba danö Gana''ana mege.', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 32, 'Ba no kubalo mbiri-biri niha andrö — sanguri urifö niha sa ira — ba no la''ohe mbiri-birira ba saŵira, awö fefu hadia ia zi so khöra.', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 33, 'Ba na ifakaoni''ö dania ami Fara''o, na isofu: Hadia halö-halöŵömi?', '[]', NULL),
  (3295336, 'OT', 'Moze I', 46, 34, 'ba mimane: Sanguri urifö niha zawuyumö, i''otarai iraono ndra''aga, irege ma''ökhö, he ya''aga andre, ba he ira tuama — ena''ö tola ba danö Gozena mi''iagö. Kubalo mbiri-biri sa, ba no sogoro Ndrawa Miserayi.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 1, 'Ba möi Yosefo, i''ombakha''ö khö Wara''o, imane: No so namagu ba ira ga''agu, moroi ba danö Gana''ana, no la''ohe mbiri-birira ba saŵira, awö fefu hadia ia zi so khöra; ba danö Gozena so ira iada''e.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 2, 'Ba lima i''ohe, ga''ania, ba ifalukha''ö da''ö khö Wara''o.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 3, 'Ba isofu khö ndra ga''a Yosefo Fara''o, imane: Hadia halö-halöŵömi?', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 4, 'Ba lamane na khö Wara''o: Möiga ba da''e, ena''ö ma''iagö da''e ma''ifu, me no ambö du''u, ö mbiri-biri khöma; noa sa afökhö lofo andrö ba danö Gana''ana. Ba ena''ö na ba danö Gozena so zawuyumö!', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 5, 'Ba imane Fara''o khö Yosefo: Hana na ba danö Gozena la''iagö, ba na ö''ila, so ba khöra niha si tola, ba fataro högö gubalo gurifögu ira.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 6, 'Ba larugi danö Miserayi khö Yosefo Yakobo ba ononia.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 7, 'Ba i''ohe yomo namania Yakobo Yosefo, ifalukha''ö khö Wara''o. Ba fatabe Yakobo khö Wara''o, wamahowu''ö ya''ia.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 8, 'Ba isofu khö Yakobo Fara''o, imane: Ha me uga fakhe ndra''ugö?', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 9, 'Imane Yakobo khö Wara''o: Fa''ara wekoligu andrö, ba no 130 fakhe. Lö anaunau ba si no fahöna famakao götögu andrö, ba lö ikhamö götö ndra amagu tuagu, töröŵara andrö.[1]', '["Sin 39:13; 119:19; Heb 11:13"]', NULL),
  (3295338, 'OT', 'Moze I', 47, 10, 'Ba i''angonasi Wara''o Yakobo, wamahowu''ö ya''ia zui, ba iröi Wara''o.', '["Sin 39:13; 119:19; Heb 11:13"]', NULL),
  (3295338, 'OT', 'Moze I', 47, 11, 'Ba ihonogöi nahia khö namania ba khö ndra talifusönia Yosefo, ifakhoi khöra dana khöra tanö ba danö Miserayi, ba zabölö atabö zinanö ba danö, ba danö Ramese, i''o''ö niŵa''ö Wara''o.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 12, 'Ba ibalazoi namania ba talifusönia ba soroiyomo namania fefu Yosefo, fakhe, dali wa''oya ndraono.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 13, 'Ba dozi tanö, ba lö ö fakhe, abölö-bölö sibai lofo, he tanö Miserayi ba he tanö Gana''ana, ba erege dödö ba lofo andrö.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 14, 'Ba owulo manö khö Yosefo gana''a fefu, he ana''a ba danö Miserayi, ba he ana''a ba danö Gana''ana, böli wakhe andrö, ni''ölira, ba ifa''ema ba nomo Wara''o gana''a andrö Yosefo.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 15, 'Ba me no ahori gana''a ba danö Miserayi ba ba danö Gana''ana, ba dozi möi Ndrawa Miserayi khö Yosefo, lamane: Faigi khöma mbalazo! Ma tola matega ba zanehe ndra''ugö? ana''a sa, ba no ahori!', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 16, 'Imane Yosefo: Mibe''e gurifömi, ba ube''e khömi, böli gurifömi andrö, na no ahori gana''a.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 17, 'Ba la''ohe khö Yosefo guriföra, ba ibe''e khöra wakhe Yosefo, böli kudo ba böli mbiri-biri ba böli zaŵi ba böli galide. Itaha mbalazora fakhe, barö ndröfi andrö, böli guriföra fefu.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 18, 'Ba alua ndröfi andrö; ba ba ndröfi dania, ba möi ira zui khönia, ba lamane: Tebai mabini''ö khöu, Tua: no ahori gana''a ba okhötama urifö, ba no möi khöu. Lö si tosai nihalöu ena''ö, hatö botoma ba benuama.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 19, 'Hadia, tola tekiko ndra''aga fönau, ya''aga andre ba benuama. Tema öli ndra''aga, fabaya benuama andrö, fakhe be''e böli, ba enoni Wara''o ndra''aga, fabaya benuama. Ba be''e khöma danömö, ena''ö auri ndra''aga ba böi mate, ba fa böi tobali sasai''ö mbenuama.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 20, 'Ba ahori i''öli mbenua Ndrawa Miserayi andrö Yosefo, khö Wara''o. Dozi sa la''amawa mbenuara Dawa Miserayi, me no famakaora lofo andrö; ba tobali okhöta Wara''o danö.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 21, 'Ba niha sato andrö, ba i''owuloi ba mbanua misa, i''otarai wondrege danö Miserayi, numalö ba wondregenia tanö sa.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 22, 'Hatö banua gere zi lö i''öli. Ere andrö sa, ba nibalazoi Wara''o, aurifara mbalazo andrö, nibe''e Wara''o khöra; da''ö mbörö, wa lö la''amawa mbenuara.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 23, 'Ba imane Yosefo ba niha sato: Ba tobali, no u''öli ami, khö Wara''o sa''ae ami, fabaya benuami. ya''e khömi danömö, ena''ö tola manaru ami.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 24, 'Ba buania dania, ba sambua ni''olima mibe''e khö Wara''o; ba si öfa ni''olima, ba khömi, tanömömi ba balazomi ba balazo zoroiyomomi ba ö ndraono sawuyu khömi.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 25, 'Ba lamane: No ö''orifi ndra''aga! Asala falukhaga wa''ebua dödö khöu, Tua, ba sawuyu Wara''o sa''ae ndra''aga!', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 26, 'Ba tobali ifatö gömö Ndrawa Miserayi Yosefo, si lö tebulö, irege ma''ökhö: sambua ni''olima labe''e khö Wara''o mbua nowira; hatö nowi gere zi tenga khö Wara''o.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 27, 'Ba Iraono Gizeraeli, ba sahono ba danö Miserayi, ba danö Gozena. Moŵa''a ira ba da''ö, ba itugu ato ira, tobali ato sibai dania.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 28, 'Ba fa''anau noso Yakobo na, ba danö Miserayi, ba 17 fakhe, ba fa''anau noso Yakobo fefu, götönia, ba 147 fakhe.', '[]', NULL),
  (3295338, 'OT', 'Moze I', 47, 29, 'Ba me no ahatö wa''amate Gizeraeli, ba ifakaoni''ö nononia Yosefo, imane khönia: Na soso dödöu ndra''odo ma''ifu, ba tufa tanga narö zolagu [ba we''amöi ba hölu], ebua''ö dödöu khögu, böi limodo: böi ko''o ndra''o ba danö Miserayi![2]', '["Faigi 24:2"]', NULL),
  (3295338, 'OT', 'Moze I', 47, 30, 'Omasido ba ngai ndra tuagu sodo; andrö ö''ohe ndra''o, öhetado ba danö Miserayi ba ba lewatöra ötanö ndra''o.', '["Faigi 24:2"]', NULL),
  (3295338, 'OT', 'Moze I', 47, 31, 'Ba imane Yakobo: Ae ba hölu khögu!', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 1, 'Aefa da''ö, ba te''ombakha''ö khö Yosefo: Mofökhö namau!', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 2, 'Ba me tefarongogö khö Yakobo: No so nonou Yosefo, ba i''abe''e''ö ia Izeraeli, mudadao ia ba gasonia.', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 3, 'Ba imane Yakobo khö Yosefo: No i''oroma''ö ia khögu Lowalangi si lö ambö fa''abölö, ba Lusi, ba danö Gana''ana, no ifahowu''ö ndra''o,', '["Faigi 41:50; 46:20","Faigi 35, 19"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 4, 'ba no imane khögu: "Ufo''ono ndra''ugö ba ato ma''uwumö ube''e, ŵalo soi zi otarai ba khöu ube''e, ba tanö da''e, ba ube''e okhöta ma''uwumö, si lö tebulö".', '["Faigi 41:50; 46:20","Faigi 35, 19"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 5, 'Ba onou andrö, si dombua, si no tumbu khöu ba danö Miserayi andre, me lö si möido khöu na, ba danö Miserayi, ba khögu da''ö: Eferayi andrö ba Manase — si mane Rubeno ba Simeoni ira khögu dania.[1]', '["Faigi 41:50; 46:20","Faigi 35, 19"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 6, 'Ba iraono andrö, nisöndrau akhira, ba khöu, ba töi ga''ara dania döira ba dana khöra andrö.', '["Faigi 41:50; 46:20","Faigi 35, 19"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 7, 'Me mangawulido moroi ba Mezofotamia, ba mate khögu [ninau] Rakhela, ba lala, ba danö Gana''ana, me lö aröu tö irege Geferata, ba no uko''o ia ba ngai lala ba Geferata, ya''ia Mbetilekhema andrö.[2]', '["Faigi 41:50; 46:20","Faigi 35, 19"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 8, 'Ba me i''ila ndraono Yosefo andrö Izeraeli, ba imane: Ha niha da''ö?', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 9, 'Imane Yosefo khö namania: Onogu da''ö, nibe''e Lowalangi khögu ba da''e.', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 10, 'Ba no abösi hörö Gizeraeli, ba wa''atua, fa lö i''ila niha. Ba me no ihatö''ö ira khönia, ba fa''ago bawa ia khöra ba i''omösi ira.[4]', '["Heb 11:21","Faigi 27, 1"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 11, 'Ba imane Izeraeli khö Yosefo: Lö''ö manö faduhu dödögu mege, ifuli fa''ila ita, ba iya''e, ba noa na ifa''ila''ö khögu nga''ötömö Lowalangi!', '["Heb 11:21","Faigi 27, 1"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 12, 'Ba ifuli iwuwu ira Yosefo, ba ifaöndrö tou ia föna namania.', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 13, 'Ba ituyu zi darua andrö Yosefo, ba dangania kambölö, ba Eferayi, tobali ba gabera Gizeraeli so da''ö, ba ba dangania kabera, ba Manase, tobali ba gambölö Gizeraeli so da''ö, ba ihatö''ö ira khönia.', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 14, 'Ba i''oro''ö gambölönia Izeraeli, itufa högö Geferayi, lö lai wa no si akhi ia, ba ba högö Manase, ba tangania kabera, tobali ifariŵa dangania; si a''a sa Manase.', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 15, 'Ba ifahowu''ö Yosefo, imane: Lowalangi andrö, ni''ata''ufi ndra amagu, Aberahamo ba Iza''aki, Lowalangi andrö, si no kubalogu, i''otarai iraono sawena si''ai tumbu ndra''o, irege ma''ökhö andre, mala''ika andrö,', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 16, 'si no mangefa''ö ya''odo ba wamakao fefu, ba yamufahowu''ö ndraono andre, ba khöra yamonga''ötö döigu ba töi ndra amagu, Aberahamo ba Iza''aki ba ya ato sibai ma''uwura ba guli danö!', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 17, 'Ba me i''ila Yosefo, wa tanga namania kambölö wanufa högö Geferayi, ba tetutu ba dödönia; andrö ituyu danga namania ba wameta ya''ia ba högö Geferayi ba ba wame''e ba högö Manase.', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 18, 'Imane Yosefo khö namania, ba da''ö: Böi, ama, da''e sa zi a''a, kambölöu be''e ba högönia.', '[]', NULL),
  (3295339, 'OT', 'Moze I', 48, 19, 'Ba itimba amania, imane: u''ila sa, onogu, u''ila sa! ya''ia göi zi tobali soi sebua dania ba ya''ia göi zabölö dania. Ba lö lai da''ö, ba abölö zui nakhinia, moroi khönia, ba ma''uwunia, ba si ndruhu ŵalo soi dania.', '["Yer 31:9,20"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 20, 'Ba ifahowu''ö ira, me luo da''ö, imane: Töimö andrö nitötöi Ndraono Gizeraeli dania, na mamahowu, wanguma''ö: yamufagölö-gölö ndra''ugö khö Geferayi ba khö Manase Lowalangi; tobali föna Manase ibe''e Geferayi.[5]', '["Yer 31:9,20"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 21, 'Aefa da''ö, ba imane Izeraeli khö Yosefo: Lö ara tö, ba mate ndra''o, ba itolo ami Lowalangi ba i''ohe mangawuli ami ba danö duami.', '["Faigi 34:25; Yos 17:7; Yoh 4:5"]', NULL),
  (3295339, 'OT', 'Moze I', 48, 22, 'Ba utehe khöu mboto hili, mifasöbigu ba Ndraono Gamori si''öli ba fana, hudeu föna ndra talifusöu.[6]', '["Faigi 34:25; Yos 17:7; Yoh 4:5"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 1, 'Ba humede Yakobo khö nononia,[1] imane: Mifa''aso ami, ena''ö u''ombakha''ö khömi, hadia zi falukha ami dania!', '["Faigi göi MozV 33:1—29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 2, 'Mi''owuloi ami ba mifondrondrongo, ya''ami, iraono Yakobo, mifondrondrongo khö namami Izeraeli!', '["Faigi göi MozV 33:1—29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 3, 'Ya''ugö Rubeno, si a''a ndra''ugö khögu, fangabe''egu ba si a''a wa''abölögu — si so föna ba wa''asalaŵa ba si so föna ba wa''abölö.', '["Faigi 35:22; Nga''ötI 5:1"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 4, 'Ba me no si maoso-maoso tödö ndra''ugö, ba böi labe''e''ö föna; noa sa möi''ö ba gaso namau, no öta''unöi no — no möi ia ba gasogu.[2]', '["Faigi 35:22; Nga''ötI 5:1"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 5, 'Ya''ami, Sime''oni ba Lewi, si fatalifusö, — fangöna ba wanao horö zi''ölira.', '["Faigi 34:25","Yos 19:1; 21:3"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 6, 'Lö''ö manö uhalö khögu nikhoi dödöra andrö, ba lö ya''odo ba nifagölösira; noa sa labunu niha ba wönura andrö, ba ba hokhara andrö, ba no lataba gölu-ölu zi matua zaŵi.[3]', '["Faigi 34:25","Yos 19:1; 21:3"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 7, 'Ni''elifi wönura andrö, si no abölö-bölö sibai, ba bakhu-bakhu dödöra andrö, si so fa''afaito! Ufosasi ira ba ndraono Yakobo, ufazawili ira ba ndraono Gizeraeli.[4]', '["Faigi 34:25","Yos 19:1; 21:3"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 8, 'Ya''ugö Yuda, ya''ugö nisuno dalifusöu dania. Ituyu mbörö du''i nemalimö tangau; khöu mangalulu ndraono namau.[5]', '["Faigi 29:35","Nga''ötI 5:2; Yes 9:6,7; Mat 2:6; Fam 5:5"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 9, 'Ono zingo Yuda — no salaŵa ndra''ugö, onogu, ba wamara''u. No ifadölö ia tou, no iköwö ia, si mane singo ba si mane singo si alawe; ha niha zi tola manuko ya''ia?', '["Faigi 29:35","Nga''ötI 5:2; Yes 9:6,7; Mat 2:6; Fam 5:5"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 10, 'Lö aheta dania zi''o zalaŵa khö Yuda, ba khönia manö wamatörö, irege so zangehao andrö, ba ni''o''ö soi niha dania.[6]', '["Faigi 29:35","Nga''ötI 5:2; Yes 9:6,7; Mat 2:6; Fam 5:5"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 11, 'Ba döla nagu ifesugö nono galide khönia ba ba ndraha nagu si sökhi ifesugö nono zi alawe galide khönia. Ba nösi nagu ibabago mbarunia ba ba ŵe mbua nagu nukhania.', '["Faigi 29:35","Nga''ötI 5:2; Yes 9:6,7; Mat 2:6; Fam 5:5"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 12, 'Si balunö hörönia ba nagu ba safusi nifönia ba zusu.', '["Faigi 29:35","Nga''ötI 5:2; Yes 9:6,7; Mat 2:6; Fam 5:5"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 13, 'Sebuloni, ba ba mbewe nasi so nahania, ba mbewe labua nowo ba ba Zidona itendro''ö ngainia.[7]', '["Yos 19:10"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 14, 'Isasari, ba no kalide sabe''e töla, si mörö-mörö ba gandra.[8]', '["MozV 33:18"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 15, 'Ba me isöndra si sökhi wa''ahono-hono ba omasiö danönia, ba ifaöndrö mbaginia ba wonoro-noro, ba tobali enoni, so''ömö halöŵö.', '["MozV 33:18"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 16, 'Dano, ba same''e ba lala huhuo mbanuania, föna mado Gizeraeli bö''ö.[9]', '["Sanguhuk 13:5","Luk 2:29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 17, 'Ulö ba ngai lala Dano, taritö ba ngai lala niha, sondrou ahe kudo, tobali ahele tou mifuri zi fakudo.', '["Sanguhuk 13:5","Luk 2:29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 18, 'Udöna-döna wangorifi andrö khöu, Yehowa![10]', '["Sanguhuk 13:5","Luk 2:29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 19, 'Gado, ba lalangögö ia sato, ba igohi ira moroi furi.', '[]', NULL),
  (3295340, 'OT', 'Moze I', 49, 20, 'Aseri, ba si no fahöna balazo; ö razo sami i''otarai ia.', '[]', NULL),
  (3295340, 'OT', 'Moze I', 49, 21, 'Nafetali ba böhö si alawe, si no muböhöli; moroi khönia huhuo omasiö.[11]', '["Sanguhuk 5"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 22, 'Eu sawena mowua Yosefo; eu sowua ba zinga gumbu. Dahania, ba mangoro ba göli kara.', '[]', NULL),
  (3295340, 'OT', 'Moze I', 49, 23, 'Lalau khönia si fafana, la''efasi wana, lasuwö ia.', '[]', NULL),
  (3295340, 'OT', 'Moze I', 49, 24, 'Ba tebai aböda wanania, alio dangania, balazi wanolo zabölö andrö, khö Yakobo, fanolo gubalo Ndraono Giseraeli andrö, gowera.', '[]', NULL),
  (3295340, 'OT', 'Moze I', 49, 25, 'Khö Lowalangi namau andrö — yamutolo''ö — khö Lowalangi, si lö ambö fa''abölö, — yamufahowu''ö ndra''ugö fa''afahöna howu-howu andrö, moroi ba mbanua si yaŵa ba fa''afahöna howu-howu moroi ba namö nidanö, si no ahono si tou, ba fa''afahöna howu-howu andrö moroi ba mbagi zuzu ba moroi ba dalu nina niha.', '[]', NULL),
  (3295340, 'OT', 'Moze I', 49, 26, 'Howu-howu andrö, si no itema amau, ba no italu''i howu-howu andrö ba hili andrö, si lö tebulö ba fa''asökhi hili-hili andrö, si lö tebulö. Ba ena''ö na khö Yosefo, ba galizuzu si no salaŵa andrö ba dalifusönia!', '[]', NULL),
  (3295340, 'OT', 'Moze I', 49, 27, 'Beniyami, ba no asu gatua sondra''u-ndra''u: na mahemolu mbanua, ba i''a nira''unia, ba na owi, ba ifaosa gahulua.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3295340, 'OT', 'Moze I', 49, 28, 'Da''ö fefu mado Gizeraeli andrö, felendrua ira, ba da''ö wehede namara khöra. Ba ifahowu''ö ira; idozigö ifahowu''ö, oi fazambu-zambua howu-howu.', '["Faigi 23:19","Faigi 25:9; 35:29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 29, 'Ba ibe''e li khöra, imane: Na no urugi dania ndra tuagu, ba mi''ohe ndra''o ba lewatö ndra tuagu, ba dögi narö hili andrö, ba mbenua Geferoni andrö, Iraono Kheti,[12]', '["Faigi 23:19","Faigi 25:9; 35:29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 30, 'ba dögi narö hili ba mbenua Makhefela, ba gamaudu Mamere, ba danö Gana''ana, benua ni''öli Gaberahamo khö Geferoni andrö, Iraono Kheti, lewatö ondröita.', '["Faigi 23:19","Faigi 25:9; 35:29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 31, 'Ba da''ö mege lako''o Gaberahamo ba fo''omonia Sara, ba da''ö göi lako''o Giza''aki ba fo''omonia Rebeka, ba ba da''ö göi uko''o Lea no,[13]', '["Faigi 23:19","Faigi 25:9; 35:29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 32, 'ba mbenua andrö, ni''öli ba Ndraono Kheti, fabaya tögi narö hili andrö bakha.', '["Faigi 23:19","Faigi 25:9; 35:29"]', NULL),
  (3295340, 'OT', 'Moze I', 49, 33, 'Ba me no i''o''ozui Yakobo wanguma''ö li ba ndraononia, ba ileagö tou ia ba gasonia, ba aetu noso; isaŵa ndra tuania.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 1, 'Ba ifalögu ia ba doto namania Yosefo, i''e''esi ia ba fa''ago bawa ia khönia.[1]', '["Faigi 46:4"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 2, 'Aefa da''ö, ba ibe''e li Yosefo ba zolau dalu-dalu, ngoni-ngoninia, ena''ö lalau dalu-dalu ba mboto namania. Ba lalau ba mboto Gizeraeli same''e-me''e dalu-dalu andrö.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 3, 'Öfa wulu wongi wa''ara da''ö, da''ö sa wa''ara wolau-lau dalu-dalu andrö. Ba 70 wongi la''e''esi ia Dawa Miserayi.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 4, 'Ba me no ahöwö mbongi wange''esi andrö, ba i''andrö ba ngoni-ngoni Wara''o Yosefo, imane: Na soso atö dödömi ndra''o ma''ifu, ba mitolo wanguma''ö khö Wara''o, wamarongogö khönia.', '["Faigi 47:29"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 5, 'No ibe''e ba hölu ndra''o amagu ba no imane: "Lö ara tö mate ndra''odo, ba lewatö andrö, nikhaogu ba danö Gana''ana öko''o ndra''o." Ba möido ena''ö mogo''o amagu, ba aefa da''ö, ba ufulido.[2]', '["Faigi 47:29"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 6, 'Ba ifafuli''ö li khönia Fara''o, imane: Ae''e, ba ko''o namau, dali wahölusa andrö, me ibe''e''ö ba hölu.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 7, 'Ba möi sa''ae Yosefo, ba wogo''o amania, ba ahori möi ngoni-ngoni Wara''o, awö gumandru sebua khönia, awö zatua ba danö Miserayi, fefu.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 8, 'Ba soroiyomo Yosefo, fefu, ba talifusönia ba soroiyomo namania, fefu; ha iraono sawuyu khöra, ba biri-birira ba saŵira laröi furi, ba danö Gozena.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 9, 'Ba fao göi khönia gureta ba si fakudo; tobali ato sibai ira.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 10, 'Ba me no larugi Goreni-Atada andrö, yefo Yoridano, ba lalau mange''esi ba da''ö, fange''esi sabölö-bölö sibai; fitu bongi wa''ara ifange''esi''ö namania Yosefo.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 11, 'Ba me la''ila wange''esi andrö ba Goreni-Atada niha ba danö, Dawa Gana''ana, ba lamane: Fange''esi Ndrawa Miserayi da''ö, sabölö-bölö. Andrö wa labe''e töi naha andrö "wange''esi Ndrawa Miserayi", yefo Yoridano.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 12, 'Ba lalau iraono Yakobo ni''oroi''önia khöra.', '["Faigi 28:17"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 13, 'Fa la''ohe ba danö Gana''ana ia iraononia ba lako''o ia ba dögi narö hili andrö ba mbenua Makhefela andrö, benua ni''öli Gaberahamo ba Ndraono Kheti andrö, Eferoni, lewatö ondröita, ba gamaudu Mamere.[3]', '["Faigi 28:17"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 14, 'Ba mangawuli ba danö Miserayi Yosefo, me no iko''o namania, ya''ia ba talifusönia ba awöra fao, fefu, me möi mogo''o amania.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 15, 'Ba lamane ira ga''a Yosefo — börö me no mate namara —: Ma dania i''afökhöi tödö ita Yosefo, ma isulöni khöda zi lö sökhi andrö fefu, nilauda khönia.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 16, 'Ba lafatenge zinenge khö Yosefo, lamane khönia: No iŵa''ö li amada, me lö si mate ia na, no imane:', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 17, 'Mimane khö Yosefo: Be''e aefa khö ndra ga''au horöra, olalöŵara andrö, me no lalau khöu zi lö sökhi! Ba be''e aefa sa''ae khöma horöma andrö, khöma andre, samosumange [göi] Lowalangi namau!', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 18, 'Ba möi khönia ndra ga''ania, latuhi danö fönania ba lamane: Ya''e ndra''aga, halöga sawuyumö!', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 19, 'Ba imane khöra Yosefo: Böi mibusi dödömi! hadia sa, no salahi Lowalangi ndra''odo?[4]', '["Faigi 45:5"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 20, 'Si lö sökhi sa nifakhaimi khögu, ba no i''ohe ba zi sökhi Lowalangi, ba wamalua ni''ilada ma''ökhö — fangorifi niha si no ato!', '["Faigi 45:5"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 21, 'Andrö böi mibusi dödömi; urorogö ami ba iraonomi.', '["Faigi 45:5"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 22, 'Ba si lö tebulö ba danö Miserayi Yosefo, awö zi sawu ya''ira, ba 110 fakhe wa''anau noso Yosefo.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 23, 'Ba fakhamö i''ila ma''uwu Geferayi Yosefo; ba mo''ono göi na ba götö Yosefo Makhiri andrö, ono Manase.', '[]', NULL),
  (3295341, 'OT', 'Moze I', 50, 24, 'Ba imane Yosefo khö ndra talifusönia: Na no ara lö ya''odo sa''ae, ba itolo ami Lowalangi ba iheta ami ba danö andre, i''ohe ami ba danö andrö, nifabu''unia khö Gaberahamo ba khö Giza''aki ba khö Yakobo, fahölusa.[5]', '["Heb 11:22"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 25, 'Ba ibe''e ba hölu Ndraono Gizeraeli Yosefo, imane: Na itolo dania ami Lowalangi, ba mi''ohe mbotogu, miheta ba da''e![6]', '["MozII 13:19; Yos 24:32"]', NULL),
  (3295341, 'OT', 'Moze I', 50, 26, 'Ba mate Yosefo, 110 fakhe wa''arania ba guli danö. Ba lalau dalu-dalu ba mbotonia ba labe''e ba hasi, [ba da''ö] ba danö Miserayi.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 1, 'Da''e ndraono Gizeraeli, si no möi ba danö Miserayi; fao ira Yakobo no, ba no i''ohe zoroiyomonia fefu zamösana:[1]', '["MozI 46:8","MozV 26:5; Sin 105:24; HalZin 7:17"]', NULL),
  (3440511, 'OT', 'Moze II', 1, 2, 'Rubeno ba Simeoni ba Lewi ba Yuda,', '["MozI 46:8","MozV 26:5; Sin 105:24; HalZin 7:17"]', NULL),
  (3440511, 'OT', 'Moze II', 1, 3, 'ba Isasari ba Sebuloni ba Beniyami,', '["MozI 46:8","MozV 26:5; Sin 105:24; HalZin 7:17"]', NULL),
  (3440511, 'OT', 'Moze II', 1, 4, 'ba Dano ba Nafetali ba Gado ba Aseri.', '["MozI 46:8","MozV 26:5; Sin 105:24; HalZin 7:17"]', NULL),
  (3440511, 'OT', 'Moze II', 1, 5, 'Ba nga''ötö Yakobo fefu, ba fitu ngafulu niha; ba Yosefo, ba si no tohöna ba danö Miserayi.', '["MozI 46:8","MozV 26:5; Sin 105:24; HalZin 7:17"]', NULL),
  (3440511, 'OT', 'Moze II', 1, 6, 'Ba mate Yosefo ba talifusönia, awö zi sagötö niha andrö ma''afefu.', '["MozI 46:8","MozV 26:5; Sin 105:24; HalZin 7:17"]', NULL),
  (3440511, 'OT', 'Moze II', 1, 7, 'Ba mo''ono''ono Ndraono Gizeraeli, itugu fahöna ba tobali ato sibai, tobali anönö danö ya''ira.[2]', '["MozI 46:8","MozV 26:5; Sin 105:24; HalZin 7:17"]', NULL),
  (3440511, 'OT', 'Moze II', 1, 8, 'Ba so razo si bohou ba danö Miserayi, si lö falukha sa''ae khö Yosefo.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 9, 'Ba imane da''ö ba mbanuania: Itugu ato moroi khöda Ndraono Gizeraeli andrö ba abölö ira moroi khöda.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 10, 'Talabu, ta''alui wa''onekhe, ba khöra andrö, fa böi abölö ato ira ba fa böi fa''awö ira ba nemalida, na tesao wanuwö, wangeheta ya''ira ba danö!', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 11, 'Ba lafataro khöra mandru, ba wamakao ya''ira ba halöŵö zawuyu, ba sanaru''ö banua khö Wara''o ira, banua naha nihöna, Fitomo ba Ramese.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 12, 'Ba lahötöi lafakao, ba ihötöi mo''ono''ono ira ba ato, tobali ata''u ira Ndraono Gizeraeli.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 13, 'Ba laforege ba Ndraono Gizeraeli Dawa Miserayi ba halöŵö sabe''e, halöŵö zawuyu,', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 14, 'ba alangu dödöra labe''e, ba halöŵö sabe''e andrö ba la''uri ba gara tembo ba ba ngawalö halöŵö ba danö; oi halöŵö niforege khöra, ena''ö lahalö.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 15, 'Ba ibe''e goroisa razo Miserayi ba zangamöi talu ba niha Heberaio — Sifera döi zi samösa ba Fua döi zi samösa — imane:', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 16, 'Na möi ami, na madono ndra alawe Heberaio, ba mifaigi ba daoge-daoge; na ono matua, ba mibunu; ba ono alawe atö, ba hana na auri.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 17, 'Ba sangata''ufi Lowalangi zangamöi talu andrö, ba lö la''o''ö ni''oroi''ö razo Miserayi khöra, la''orifi sa nono matua.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 18, 'Ba ifakaoni''ö zangamöi talu andrö razo Miserayi, imane, khöra: Hana wa mimanö, wa mi''orifi nono matua andrö?', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 19, 'Ba lamane khö Wara''o sangamöi talu andrö: Ira alawe Heberaio andrö, ba tenga si mane ira alawe Ndrawa Miserayi, no sabe''e ira; lö fakhamö so zangamöi talu, ba no tumbu nono.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 20, 'Ba ifahowu''ö zangamöi talu andrö Lowalangi, ba ato sibai niha ba abölö sibai ira.', '[]', NULL),
  (3440511, 'OT', 'Moze II', 1, 21, 'Ba me la''ata''ufi Lowalangi sangamöi talu andrö, ba i''oya''ö khöra ndraono.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 1, 'Ba so niha, mado Lewi, sangowalu, ono alawe mado Lewi göi ihalö.[1]', '["Faigi 6:20; MozIV 26:59; Nga''ötI 23:13","HalZin 7:20; Heb 11:23"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 2, 'Ba manabina galawe andrö ba madono, ono matua. Ba me i''ila, wa ono si sökhi, ba ibini''ö, tölu waŵa.[2]', '["Faigi 6:20; MozIV 26:59; Nga''ötI 23:13","HalZin 7:20; Heb 11:23"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 3, 'Ba me tebai sa''ae ibini''ö, ba ihalö nahania wetifeti sukhu, igalögalöni sulumou ba kita, ibe''e bakha nono andrö, ba ibe''e barö zukhu ba mbewe Nilo.', '["Faigi 6:20; MozIV 26:59; Nga''ötI 23:13","HalZin 7:20; Heb 11:23"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 4, 'Ba so ga''a nono andrö alawe, idaro-darogö ba zahatö, ena''ö i''ila, he wisa lua-lua.', '["Faigi 6:20; MozIV 26:59; Nga''ötI 23:13","HalZin 7:20; Heb 11:23"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 5, 'Ba so nono Wara''o alawe, möi ia ba Nilo, mondri. Ba me latörö mbewe Nilo awönia, ba i''ila wetifeti andrö barö zukhu; ba ifatenge zawuyunia samösa, ifahalö''ö.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 6, 'Ba me ibokai, ba i''ila nono, ono matua, se''e. Ba ahakhö dödönia ia, imane sa dödönia: Dörö ono niha Heberaio andrö.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 7, 'Ba imane ga''a nono khö nono Wara''o: Hadia, möido mogaoni khöu ira alawe Heberaio, si bohou madono, ena''ö ifaenu khöu nono matua andrö?', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 8, 'Imane ono Wara''o: Ae''e! Ba möi nono alawe andrö mogaoni ina nono no mege.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 9, 'Ba imane ba da''ö ono Wara''o: Na ö''ohe nono andre ba na öfaenu ia khögu, ba ube''e mböli gölöu! Ba i''ohe nono ira alawe andrö ba ifaenu-faenu.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 10, 'Ba me no ebua nono matua andrö, ba i''ohe khö nono Wara''o alawe no mege, ba ihalö ononia, ibe''e töinia Mose, imane sa: Nihalögu ba nidanö!', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 11, 'Ba me luo no ira matua Mose, ba samuza ma''ökhö, ba möi ia baero ba niwara ba i''ila, wa no halöŵö zawuyu halöŵöra; ba anehe ia, me ibago niwara, niha Heberaio, Dawa Miserayi.[3]', '["Heb 11:24–26","HalZin 7:24–28","HalZin 7:29; Heb 11:27"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 12, 'Ba ifakhölö ia, ba me i''ila lö niha bö''ö, ba itema ibunu Ndrawa Miserayi andrö ba iko''o ba gawu.[4]', '["Heb 11:24–26","HalZin 7:24–28","HalZin 7:29; Heb 11:27"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 13, 'Ba mahemolu ö, ba ifuli möi baero, ba darua si fasoso, i''ila, niha Heberaio. Ba imane ba zi so sala: Hana wa öbago nawöu?', '["Heb 11:24–26","HalZin 7:24–28","HalZin 7:29; Heb 11:27"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 14, 'Ba imane da''ö: Ha niha zamataro sokhö ya''aga ba sanguhuku ya''aga ya''ugö? hadia edöna öbunu ndra''odo göi, si mane famunumö Dawa Miserayi andrö? Ba ata''u Mose, imane sa dödönia: Si ndruhu, no terongo da''ö!', '["Heb 11:24–26","HalZin 7:24–28","HalZin 7:29; Heb 11:27"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 15, 'Ba irongo göi Fara''o; ba i''alui wamunu Mose. Ba itema moloi Mose khö Wara''o, isaŵa danö Ndraono Midiano. Ba mudadao ia ba zinga mba''a ba da''ö.[5]', '["Heb 11:24–26","HalZin 7:24–28","HalZin 7:29; Heb 11:27"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 16, 'Ba khö högö gere ba Ndraono Midiano, ba fitu nono alawe; ba möi da''ö, ba wana''u idanö. Ba wamo''ösi luha, ba wamabadugö ba mbiri-biri namara.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 17, 'Ba so gubalo, latimba ira. Ba maoso Mose, itolo ira ifa''amöi mbiri-biri khöra ba wamadu.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 18, 'Ba me mangawuli ira khö namara Regueli, ba imane khöra: Hana wa lö arara ami ma''ökhö?', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 19, 'Lamane: Dawa Miserayi zanolo ya''aga ba gubalo andrö, ba noa na''i ita''u khöma nidanö ba ifabadugö ba mbiri-biri.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 20, 'Ba imane ba ba ndraononia: Heza so ia ya''o? Hana wa miröi ba da''ö niha andrö? Mikaoni ia ba wemanga!', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 21, 'Ba omasi Mose i''iagö ba niha andrö ba ibe''e khö Mose nononia Sifora.', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 22, 'Ba mo''ono da''ö, ono matua, ba ibe''e töi nono andrö Gereso, imane sa: "No tobali si fatewu ndra''odo ba danö niha bö''ö."', '[]', NULL),
  (3400671, 'OT', 'Moze II', 2, 23, 'Ba ara ma''ifu furi ö, ba mate razo Miserayi. Ba mangarö-ngarö Ndraono Gizeraeli ba halöŵö sabe''e andrö, mu''ira-ira, tobali terongo ba Lowalangi we''aora ba wangefa''ö ya''ira ba halöŵö sabe''e andrö.', '["MozI 17:2"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 24, 'Ba ifondrondrongo wangarö-ngaröra andrö Lowalangi, ba itörö tödö Lowalangi wawu''usa li andrö khönia, khö ndra Aberahamo, Iza''aki, Yakobo.[6]', '["MozI 17:2"]', NULL),
  (3400671, 'OT', 'Moze II', 2, 25, 'Ba inehegö Ndraono Gizeraeli Lowalangi, ba ihakhösi tödö ira.', '["MozI 17:2"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 1, 'Ba kubalo mbiri-biri Mose khö matuania Yetero, högö gere ba danö Ndraono Midiano. Ba irugi ba wondrege danö si mate i''ohe mbiri-biri, ba irugi hili Lowalangi andrö, hili Horebi.', '["HalZin 7:30","Mat 22:32"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 2, 'Ba i''oroma''ö ia khönia mala''ika Yehowa andrö ba hola-hola galitö, soroi ngafu za''a-sa''a mao. Ba me ifaigi sibai, ba hiza, humola-hola ngafu za''a-sa''a mao andrö, ba lö''ö sa akhozi.[1]', '["HalZin 7:30","Mat 22:32"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 3, 'Ba imane dödönia Mose: Möido sa mufaigi gangilata sebua andrö, hana wa lö akhozi ngafu za''a-sa''a mao andrö.', '["HalZin 7:30","Mat 22:32"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 4, 'Ba me i''ila Yehowa, möi ia mufaigi, ba mu''ao khönia Lowalangi moroi ba ngafu za''a-sa''a mao andrö, imane: He Mose! He Mose! Ba imane: Ya''e ndra''odo!', '["HalZin 7:30","Mat 22:32"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 5, 'Ba imane khönia: Böi hatö''ögö! Heta mbadagaheu ba gahemö, me no tanö ni''amoni''ö naha andrö, ba zi so''ö!', '["HalZin 7:30","Mat 22:32"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 6, 'Ba imane na: Lowalangi namau ndra''odo, Lowalangi Gaberahamo, Lowalangi Giza''aki, Lowalangi Yakobo. Ba ibalugö mbawania Mose, me ata''u ia, ifaigi Lowalangi.[2]', '["HalZin 7:30","Mat 22:32"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 7, 'Ba imane Yehowa: No irege ginötö ufaigi wamakao mbanuagu andrö, si so ba danö Miserayi, ba no urongo wangarö-ngaröra andrö, ena''ö aefa ira ba mandrura andrö, noa sa u''ila wa''abölö-bölö wamakaora andrö.', '["HalZin 7:34"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 8, 'Andrö möido tou sa''ae, ba wangefa''ö ya''ira ba danga Ndrawa Miserayi, ba wamawu''a ya''ira ba danö andrö, ba wolohe ba danö si sökhi, si no ebolo, ba danö ba zi falawu zusu ba ŵe ŵani, ba naha mbanua Ndrawa Gana''ana andrö, Iraono kheti ba Iraono Gamori ba Iraono Weresi ba Iraono Hewi ba Iraono Yebusi.', '["HalZin 7:34"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 9, 'Ba iya''e, ba no urongo wangarö-ngarö Ndraono Gizeraeli ba no u''ila wamakao Ndrawa Miserayi ya''ira.[3]', '["HalZin 7:34"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 10, 'Ba ae sinengegu khö Wara''o ba heta ba danö Miserayi mbanuagu andrö, Iraono Gizeraeli.', '["HalZin 7:34"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 11, 'Ba imane Mose khö Lowalangi: Ha niha ndra''o, wa ya''odo zi möi khö Wara''o, awö wa ya''odo zangeheta ba danö Miserayi Iraono Gizeraeli?', '[]', NULL),
  (3440771, 'OT', 'Moze II', 3, 12, 'Ba imane: utolo sa''ae ndra''ugö! ba da''ö dandra khöu dania, wa ya''odo zamatenge ya''ugö: na no öheta ira ba danö Miserayi, ba ba hili da''e mifosumange Lowalangi.', '[]', NULL),
  (3440771, 'OT', 'Moze II', 3, 13, 'Ba imane Mose khö Lowalangi: Ba na urugi Ndraono Gizeraeli ba na umane khöra: Lowalangi ndra tuami andrö zamatenge ya''o khömi, ba na lamane khögu: Ha niha döinia? ba ha uŵa''ö khöra?', '[]', NULL),
  (3440771, 'OT', 'Moze II', 3, 14, 'Ba imane Lowalangi khö Moze: "Ya''o-ya''odo manö ndra''odo andre"! ba imane na: Da''ö niŵa''öu ba Ndraono Gizeraeli: Si "Ya''odo" andrö zamatenge ya''o khömi![4]', '["MozI 9:26; 12:8; MozIV 6:27; Fam 1:8","Yes 42:8"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 15, 'Ba imane na Lowalangi khö Moze: Da''ö niŵa''öu ba Ndraono Gizeraeli: Yehowa andrö, Lowalangi ndra tuami, Lowalangi Gaberahamo, Lowalangi Giza''aki ba Lowalangi Yakobo zamatenge ya''o khömi; da''ö döigu, irugi zi lö aetu, da''ö wamotöi ya''odo götö-götö wa''ara.[5]', '["MozI 9:26; 12:8; MozIV 6:27; Fam 1:8","Yes 42:8"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 16, 'Ae''e, falukha''ö zatua Ndraono Gizeraeli ba ömane khöra: Yehowa andrö, Lowalangi ndra tuami, ba no i''oroma''ö ia khögu, Lowalangi ndra Aberahamo, Iza''aki, Yakobo andrö; ba no ifabu''u: ufaigi ami ba ube''e balazi zi no göna ami ba danö Miserayi; ba no uhonogöi:', '[]', NULL),
  (3440771, 'OT', 'Moze II', 3, 17, 'uheta ami ba wamakao andrö ba danö Miserayi, ba u''ohe ami ba danö Ndrawa Gana''ana andrö, Iraono kheti, ba Iraono Gamori ba Iraono Weresi ba Iraono Hewi ba Iraono Yebusi, ba danö, ba zi falawu zusu ba ŵe ŵani.', '[]', NULL),
  (3440771, 'OT', 'Moze II', 3, 18, 'Ba lafondrondrongo khöu; ba ö''ohe khö razo Miserayi zatua Ndraono Gizeraeli, ba mimane khönia: Yehowa andrö, Lowalangi niha Heberaio, ba no falukha khöma; ba fa''amöiga ba danö si mate, tölu ngaluo fofanö wa''aröu, ba wamosumange Yehowa andrö, Lowalangima.', '[]', NULL),
  (3440771, 'OT', 'Moze II', 3, 19, 'Ba u''ila sa''ae, wa lö itehe khömi wofanö razo Miserayi, na tenga ni''anösö''ö.', '[]', NULL),
  (3440771, 'OT', 'Moze II', 3, 20, 'Ba u''oro''ö dania dangagu ba uhare''ö ba Ndrawa Miserayi fefu zahöli-höli dödö andrö khögu, nilaugu khöra; awena dania lafofanö ami.', '[]', NULL),
  (3440771, 'OT', 'Moze II', 3, 21, 'Ba ebua dania dödö Ndrawa Miserayi khömi ube''e, fa böi si lö noro danga ami, na mofanö ami.', '["Faigi 11:2; 12:35"]', NULL),
  (3440771, 'OT', 'Moze II', 3, 22, 'Dozi ira alawe, ba hana na laŵa''ö dania ba ndra alawe Miserayi si fahatö omo khöra, ba ma ba zorudu yomo khöra, ena''ö na labe''e niwawalöra gama-gama firö ba gama-gama ana''a ba nukha, ba mibe''e fangehao nonomi matua ba fangehao nonomi alawe, mi''osindra''ui gokhöta Ndrawa Miserayi ba zi manö.[6]', '["Faigi 11:2; 12:35"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3441353, 'OT', 'Moze II', 4, 1, 'Ba imane Moze: Ba na lö faduhu dödöra khögu, ba na lö lafondrondrongo khögu, ma lamane: Lö''ö sa ni''oroma''ö Yehowa ya''ia khöu?', '["Faigi 7:10"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 2, 'Ba imane khönia Yehowa: Hadia da''ö ba dangau? Imane: Si''o. Ba imane: Tibo''ö tou.', '["Faigi 7:10"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 3, 'Ba me itibo''ö tou, ba tobali ulö, ba moloi Moze khönia.[1]', '["Faigi 7:10"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 4, 'Ba imane Yehowa khö Moze: Oro''ö dangau, ra''u gi''onia. Ba i''oro''ö dangania, i''aro''ö wondra''u; ba tobali si''o ba dangania.', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 5, 'Ba faduhu sa''ae dödöra, wa no i''oroma''ö ia khöu Yehowa, Lowalangi ndra tuara andrö, Lowalangi Gaberahamo, Lowalangi Giza''aki ba Lowalangi yakobo.', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 6, 'Ba imane na khönia Yehowa: Sigö''ö ba nono mbarumö ba dotou dangau! ba isigö''ö ba nono mbarunia dangania. Ba me ifuli isöbi, ba no bou auri, si lö mudöna-döna, afusi, si mane betua.', '["Faigi 7:20"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 7, 'Ba imane: Fuli sigö''ö ba nono mbaru dangau! Ba isigö''ö ba nono mbarunia dangania, ba me ifuli isöbi, ba no ifuli tobali si mane ösinia bö''ö, lö mudöna-döna.', '["Faigi 7:20"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 8, 'Ba na lö faduhu dödöra, na lö lafondrondrongo ba dandra si föföna andrö, ba faduhu sa dödöra ba dandra si sambua andrö.', '["Faigi 7:20"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 9, 'Ba na lö''ö göi faduhu dödöra ba zi dua balö andrö, tandra, na lö la''o''ö khöu, ba ösou nidanö ba Nilo, ba öfaduwa ba danö, ba idanö andrö misoumö ba Nilo, ba tobali do, ba danö.[2]', '["Faigi 7:20"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 10, 'Ba imane Moze khö Yehowa: He So''aya! Tenga niha sangila fahuhuo ndra''o, he föna, ba he götö iada''e, me fahuhuo ndra''ugö khö genonimö, no sabe''e li ndra''o, ba hulö zabua lelagu.[3]', '["Faigi 6:12; Yer 1:6","Sin 94:9","Mat 10:19"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 11, 'Ba imane khönia Yehowa: Ba ha niha zomböi bawa niha? ba ha niha zame''e si lö hede niha ba safiso ba sangila niha ba sau''a? Hadia, tenga ya''odo, Yehowa?[4]', '["Faigi 6:12; Yer 1:6","Sin 94:9","Mat 10:19"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 12, 'Ba ae''e manö! Ya''o zanolo ya''ugö ba wahuhuosa ba uwawakha''ö khöu, hadia niŵa''öu.[5]', '["Faigi 6:12; Yer 1:6","Sin 94:9","Mat 10:19"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 13, 'Ba imane: He Soaya! sökhi na niha bö''ö öfatenge!', '["Faigi 7:2"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 14, 'Ba mofönu Yehowa khö Moze, imane: Ba hadia, ba lö A''aroni, ga''au, ono Lewi andrö? Noa sa u''ila khönia, wa i''ila sibai fahuhuo. Ba ifaondragö na ndra''ugö dania ba omuso sibai dödönia, na i''ila''ö.', '["Faigi 7:2"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 15, 'Ba hana na fahuhuo ndra''ugö khönia, ba öfa''ema khönia niŵa''ö andre. Ba utolo ndra''ugö ba he ya''ia göi, ba wahuhuosa, ba uwawakha''ö khömi, he miwisa.[6]', '["Faigi 7:2"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 16, 'Ba ya''ia zi fahuhuo ba niha sato, salahiu, ba ya''ia mbawau; ba ya''ugö, ba [hulö] Lowalanginia.', '["Faigi 7:2"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 17, 'Ba si''o andrö, ba ohe tangau; ya''ia wamazökhi dandra andrö.', '["Faigi 7:2"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 18, 'Ba mofanö Moze, ifuli ia khö matuania Yetero, ba imane khönia: Mofanö ndra''o, ufulido ba niwama ba danö Miserayi, ba wamaigi, na lö si mate ira. Imane Yetero khö Moze: Ae''e, ya''ohahau dödöu!', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 19, 'Ba imane Yehowa khö Moze, ba danö Ndraono Midiano: Faoso, fuli''ö ba danö Miserayi; noa sa ahori mate zangalui no famunu ya''ugö.[7]', '["Mat 2:20","Faigi 12:29"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 20, 'Ba ifakudo ba galide wo''omonia ba ononia Moze ba mangefa ia, ba wanaŵa tanö Miserayi; ba si''o andrö khö Lowalangi, ba i''ohe tangania Moze.', '["Mat 2:20","Faigi 12:29"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 21, 'Ba imane na Yehowa khö Moze. Na örugi danö Miserayi, ba faigi: fefu dandra andrö, nibe''egu ba dangau, ba ölau föna Wara''o, ba ya''o, ba u''oköli''ö dödönia, fa lö ifofanö ira.', '["Mat 2:20","Faigi 12:29"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 22, 'Ba ya''ugö, ba ömane khö Wara''o: Da''ö niŵa''ö Yehowa: Iraono Gizeraeli andrö, ba no onogu si a''a.', '["Mat 2:20","Faigi 12:29"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 23, 'Ba da''ö sa''ae niŵa''ögu khöu: Fofanö nonogu andrö, ena''ö ifosumange ndra''o; ba na lö edöna öfofanö ia, ba ubunu nonou si a''a![8]', '["Mat 2:20","Faigi 12:29"]', NULL),
  (3441353, 'OT', 'Moze II', 4, 24, 'Ba ba lala, ba zi mörö ira, ba falukha Yehowa khö Moze, ibunu ia mena''ö.', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 25, 'Ba ihalö gara satarö singa Sifora, itaba guli nononia ba ifagule ba zaila ia, imane: Soniha si no togule do ndra''ugö khögu!', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 26, 'Awena iböhöli ia [Yehowa]. Ba börö wamoto andrö, wa iŵa''ö Soniha si no togule do.', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 27, 'Ba iŵa''ö Yehowa khö Ga''aroni: Ae faondragö Moze ba danö si mate! Ba möi da''ö, falukha ia khönia ba gahe hili Lowalangi andrö, hili Horebi; ba fa''ago bawa ia khönia.', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 28, 'Ba i''ombakha''ö khö Ga''aroni Moze fefu huhuo Yehowa, oroisania khönia, ba tandra andrö fefu, niŵa''önia khönia.', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 29, 'Ba möi ira, darua ira Moze Ga''aroni ba lafalukha''ö zatua Ndraono Gizeraeli fefu.', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 30, 'Ba ifa''ema A''aroni fefu goroisa, nibe''e Yehowa khö Moze, ba da''ö zolau tandra andrö, ba zanehe niha sato.', '[]', NULL),
  (3441353, 'OT', 'Moze II', 4, 31, 'Ba faduhu dödöra ba da''ö, me larongo, no ihakhösi tödö Ndraono Gizeraeli Yehowa ba no inehegö wamakao ya''ira andrö ba mangalulu, ira, lafalögu tou ira ba danö.', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 1, 'Aefa da''ö, ba möi ndra Moze A''aroni, ba lamane khö Wara''o: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Fofanö mbanuagu andrö, ena''ö möi ira ba danö si mate molau owasa.', '["Faigi 3:18"]', NULL),
  (3441645, 'OT', 'Moze II', 5, 2, 'Ba imane Fara''o: Ha niha Yehowa andrö, fa ufondrondrongo linia, fa ufofanö Ndraono Gizeraeli? Lö u''ila Yehowa, ba lö''ö göi ufofanö Ndraono Gizeraeli!', '["Faigi 3:18"]', NULL),
  (3441645, 'OT', 'Moze II', 5, 3, 'Ba lamane: No falukha khöma Lowalangi niha Heberaio andrö; ba fofanö ndra''aga, tölu ngaluo fofanö ba danö si mate, ena''ö mabe''e zumange khö Lowalangima Yehowa, fa böi ifatörö khöma wökhö waba, ba ma si''öli.[1]', '["Faigi 3:18"]', NULL),
  (3441645, 'OT', 'Moze II', 5, 4, 'Ba itema lira razo Miserayi, imane: Hana wa midönisi niha, fa laböhöli halöŵöra, ya''ami Moze ba A''aroni? mi''ae ba halöŵömi!', '["Faigi 3:18"]', NULL),
  (3441645, 'OT', 'Moze II', 5, 5, 'Ba imane na Fara''o: Hiza, no töra wa''ato niha ba danö, ba omasi na ami, na labato halöŵöra?', '["Faigi 3:18"]', NULL),
  (3441645, 'OT', 'Moze II', 5, 6, 'Ba me luo da''ö, ba ibe''e goroisa Fara''o ba mandru andrö, nifataro khöra ba ba zamaigi-maigi halöŵöra, imane:', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 7, 'Böi sa''ae mibe''e döla wakhe ba niha andrö, si mane föna, ba wamazökhi kara tembo andrö, ya''ira zi möi mangalui töla wakhe khöra.', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 8, 'Ba fa''oya gara tembo, si no muhuku, nifazökhira, irege ma''ökhö, ba böi milulu khöra, ma''ifu böi miböhöli. Ambö halöŵöra, andrö laforege wangandrö: Damöiga mame''e sumange khö Lowalangima!', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 9, 'Ni''abe''e''ö halöŵö ba niha andrö, fa a''oi dödöra ba da''ö ba fa böi lafondrondrongo waya!', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 10, 'Ba möi mandru andrö ba samaigi-maigi ya''ira, ba lamane ba niha sato: Da''ö nihonogöi Wara''o: lö''ö sa''ae ufabe''e''ö khömi döla wakhe;', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 11, 'ya''ami zi möi mamaigi töla wakhe khömi, heza misöndra; ba ma''ifu sa lö lawuwu halöŵömi.', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 12, 'Ba latöröi danö Miserayi ma''asagörö, ba wangalui töla wakhe, nira''a.', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 13, 'Ba laforege khöra mandru andrö, lamane: Böi ambö halöŵömi, halöŵö ma''ökhö, si mane mege, me so döla wakhe.', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 14, 'Ba samaigi-maigi Iraono Gizeraeli, nifataro mandru andrö khö Wara''o khöra ba lafabözi''ö ba lamane khöra: Hana wa lö ahori mirugi menewi ba me dua wongi ndrohu-ndrohu gara tembo andrö, nihuku khömi mege?', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 15, 'Ba möi zamaigi-maigi Iraono Gizeraeli andrö, mangarö-ngarö ira khö Wara''o, lamane: He Tua! hana wa öfatörö khöma da''ö?', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 16, 'Lö''ö sa''ae labe''e khöma döla wakhe, ba lamane zui: Da gara tembo! ba hiza, tebözi-bözi na''i ndra''aga; mosala mbanuamö.', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 17, 'Ba imane: Sareu ami, sareu! Andrö mimane: Möiga mamosumange Yehowa.', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 18, 'Midölö ami ba halöŵömi andrö. Töla wakhe, ba lö labe''e khömi, ba ndrohu-ndrohu gara tembo andrö, ba ahori mi''asogö!', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 19, 'Ba tosasa zamaigi-maigi Iraono Gizeraeli andrö, me no lamane khöra: Ndrohu-ndrohu gara tembo ma''ökhö, ba ma''ifu lö lawuwu khömi!', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 20, 'Ba me la''otarai khö Wara''o, ba falukha ira ndra Moze A''aroni, si so ba da''ö, ba wamaondragö ya''ira,', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 21, 'ba lamane khöra: Yamuhuku ami Lowalangi ba yamufaigi khöma lala, me no mofönu khöma Wara''o, awö ngoni-ngoninia, mibe''e, ba me no mibe''e ba dangara zi''öli, ba wamunu ya''aga.', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 22, 'Ba humede zui Moze khö Yehowa, imane: He So''aya! Hana wa öfatörö ba khöra wamunu andrö? Ba hadia guna wamatengeu ya''odo?', '[]', NULL),
  (3441645, 'OT', 'Moze II', 5, 23, 'Götö wa no möi ndra''o khö Wara''o, ba wehede khönia salahiu, ba i''abölögö na wamakao ya''ira, ba lö''ö manö ni''efa''öu banuamö andre.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 1, 'Ba imane Yehowa khö Mose: Iada''e dania ö''ila hadia nilaugu khö Wara''o andrö: ni''anösö''ö tanga sabe''e ifofanö ira, ba ni''anösö''ö tanga sabe''e itimba ira, iheta ira ba danönia.[1]', '["Faigi 12:33"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 2, 'Ba humede Lowalangi khö Moze, imane khönia: Yehowa ndra''odo!', '["MozI 17:1; Faigi 3:14","MozI 17:8"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 3, 'No u''oroma''ö ndra''odo no, Lowalangi si lö ambö fa''abölö, khö ndra Aberahamo, Iza''aki, Yakobo; ba tenga Yehowa döigu ba wangoroma''ögu ya''odo khöra.[2]', '["MozI 17:1; Faigi 3:14","MozI 17:8"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 4, 'Ba noa na''i ulau fawu''u li khöra, wa ube''e khöra danö Gana''ana andrö, tanö andrö ba zi fatewu ira mege[3]', '["MozI 17:1; Faigi 3:14","MozI 17:8"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 5, 'Ba iya''e, ba no ufondrodrongo wangarö-ngarö Ndraono Gizeraeli andrö ba wangosawuyu Ndrawa Miserayi andrö ya''ira, ba no itörö tödögu gamabu''ula ligu andrö.', '["MozI 17:1; Faigi 3:14","MozI 17:8"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 6, 'Andrö ömane ba Ndraono Gizeraeli: Yehowa ndra''odo, u''efa''ö ami ba halöŵö zawuyu andrö, halöŵömi ba Ndrawa Miserayi, usöbi ami, wameta ya''ami ba halöŵömi andrö, halöŵö zawuyu, u''efa''ö ami tangagu ni''oro''ö andrö ba fao wangoroma''ö fa''abölö si lö ambö.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 7, 'Ba utuyu ami banuagu, ba Lowalangimi ndra''odo ba ya''aboto dania ba dödömi, wa no Yehowa ndra''odo, Lowalangimi, sangefa''ö ya''ami ba halöŵö zawuyu andrö, ba danö Miserayi.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 8, 'Ba u''ohe ami ba danö andrö nifabu''ugu fahölusa khö ndra Aberahamo, Iza''aki, Yakobo, fame''e khöra; ba ube''e okhötami, ya''odo, Yehowa andre!', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 9, 'Ba ifa''ema da''ö ba Ndraono Gizeraeli Moze. Ba lö lafondrondrongo khö Moze, ba wa''alangu dödöra andrö ba me no si manö wa''abe''e halöŵöra.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 10, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 11, 'Ae ŵa''ö khö Wara''o andrö, razo Miserayi, yamufofanö Ndraono Gizeraeli, ya''aheta ba danönia.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 12, 'Ba humede Moze khö Yehowa, imane: Me lö nifondrondrongo Ndraono Gizeraeli khögu, ba he moroi ifondrondrongo Fara''o? ba mendrua manö, me tenga si to''ölö ba wahuhuosa ndra''odo.[4]', '["Faigi 4:1"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 13, 'Ba humede Yehowa khö ndra Moze A''aroni, ifatenge ira ba Ndraono Gizeraeli ba khö Wara''o, razo Miserayi, ba wangeheta Iraono Gizeraeli ba danö Miserayi.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 14, 'Da''e zatua baomo, ira tuara:', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 15, 'Ba ono Zimeoni, ba Yemueli ba Yamini ba Ohadi ba Yakhino ba Sohara, ba Saulo, ono ndrongania Dawa Gana''ana andrö; da''ö nga''ötö Zimeoni.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 16, 'Ba töi nono Lewi ba nga''ötöra, ba Gereso ba Kahati ba Merari. Ba 137 fakhe wa''anau noso Lewi.[6]', '["MozI 46:11"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 17, 'Ono Gereso andrö, ba Libini ba Simei, ba nga''ötöra.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 18, 'Ba ono Gahati, ba Ameramo ba Yeseari ba Heberona ba uzieli. Ba 133 fakhe wa''anau noso Gahati.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 19, 'Ba ono Merari, ba Maheli ba Musi. Da''ö ma''uwu Lewi, ba nga''ötöra andrö.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 20, 'Ba Ameramo andrö, ba ihalö Yokhebe, inania si akhi; ba mo''ono da''ö khönia, A''aroni ba Moze nononia. Ba 137 fakhe wa''anau noso Gameramo.[7]', '["MozIV 26:59"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 21, 'Ba ono Yeseari andrö, ba Kora ba Nefegi ba Sikhiri.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 22, 'Ba ono Guzieli, ba Mizaeli ba Elisafa ba Sitiri.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 23, 'Ba A''aroni andrö, ba ihalö Gelizabe, ono Gaminadabi, talifusö Nahaso. Ba mo''ono da''ö khönia; ya''ia Nadabi ba Abihu ba Eleazari ba Itamaro.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 24, 'Ba ono Gora andrö, ba Asiri ba Elikana ba Abiazafi; da''ö nga''ötö Gora andrö.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 25, 'Ba Eleazari andrö ono Ga''aroni, ba ihalö nono Wutieli sambua; ba mo''ono da''ö khönia; ya''ia Wineha andrö. Da''ö wurugö nono Lewi, ba nga''ötöra andrö.[8]', '["MozIV 25:7"]', NULL),
  (3441980, 'OT', 'Moze II', 6, 26, 'Da''ö Ga''aroni andrö ba Moze andrö, ba niŵa''ö Yehowa: Miheta ba danö Miserayi ngahönö Ndraono Gizeraeli andrö.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 27, 'Da''ö ira, sama''ema khö Wara''o, razo Miserayi, wa edöna laheta ba danö Miserayi Ndraono Gizeraeli — Mose ba A''aroni.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 28, 'Ba me humede Yehowa khö Moze ba danö Miserayi, ba imane Yehowa khö Moze:', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 29, 'Fa''ema khö Wara''o, razo Miserayi, fefu hadia ia, niŵa''ögu khöu.', '[]', NULL),
  (3441980, 'OT', 'Moze II', 6, 30, 'Ba imane Moze khö Yehowa: Ba si lö to''ölö ba wahuhuosa ndra''odo; he moroi ifondrondrongo khögu Fara''o?', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 1, 'Ba imane Yehowa khö Moze: ubali''ö Lowalangi ndra''ugö khö Wara''o; ba ga''au A''aroni, ba si fahuhuo, salahiu.[1]', '["Faigi 4:16","Faigi 4:21","Faigi 14:18"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 2, 'Fefu hadia ia niŵa''ögu khöu, ba öfa''ema, ba ga''au A''aroni zangombakha khö Wara''o, ena''ö i''efa''ö Ndraono Gizeraeli ba danönia.', '["Faigi 4:16","Faigi 4:21","Faigi 14:18"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 3, 'Ba ya''o, ba u''oköli''ö dödö Wara''o andrö ba u''oya''ö wolau tandra ba sahöli-höli dödö, ba danö Miserayi.[2]', '["Faigi 4:16","Faigi 4:21","Faigi 14:18"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 4, 'Ba lö''ö sa ifondrondrongo khömi Fara''o; awena dania ubaya Ndrawa Miserayi, ba uheta ba danö Miserayi ngahönö andrö khögu, banuagu andrö, Iraono Gizeraeli, fao wangoroma''ö fa''abölö, si lö ambö.', '["Faigi 4:16","Faigi 4:21","Faigi 14:18"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 5, 'Ba ya''aboto dania ba dödö Ndrawa Miserayi, wa no Yehowa ndra''odo, na tosinga khöra wa''abölögu ube''e, ba na uheta ba ngaira Ndraono Gizeraeli.[3]', '["Faigi 4:16","Faigi 4:21","Faigi 14:18"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 6, 'Ba la''o''ö niŵa''ö Yehowa khöra ira Moze A''aroni; da''ö lalau.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 7, 'Ba no 80 fakhe Moze ba 83 Ga''aroni, me fahuhuo ira khö Wara''o.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 8, 'Ba imane Yehowa khö ndra Moze A''aroni:', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 9, 'Na iŵa''ö khömi Fara''o: Mifazökhi dandra! ba ömane khö Ga''aroni: Labu, tibo''ö tou zi''ou föna Wara''o, ba tobali ulö sebua dania.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 10, 'Ba möi khö Wara''o ndra Moze A''aroni, ba lalau niŵa''ö Yehowa: Itibo''ö tou zi''onia A''aroni, föna Wara''o ba föna ngoni-ngoninia, ba tobali ulö sebua.[4]', '["Faigi 4:3"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 11, 'Ba ifakaoni''ö zatua-tua ba si no to''ölö ba gelemu Fara''o; ba lalau göi zi manö si fakelemu andrö, elemura andrö:[5]', '["TimII 3:8"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 12, 'Itibo''ö tou zi''onia zamösana, ba tobali ulö sebua; ba itölö sa zi''ora si''o Ga''aroni.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 13, 'Ba lö tebulö wa''abe''e dödö Wara''o, ba lö i''o''ö khöra, itörö niŵa''ö Yehowa.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 14, 'Ba imane Yehowa khö Moze: No abe''e dödö Wara''o ba te khönia ifofanö ira.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 15, 'Mahemolu mbanua ae khö Wara''o ba ondrasi ia, na möi ia mondri ba mbewe Nilo, ohe tangau zi''o andrö, si no tobali ulö, ba ömane khönia:', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 16, 'Yehowa andrö, Lowalangi niha Heberaio zamatenge ya''o khöu, ba wanguma''ö khöu: Fofanö mbanuagu andrö, ena''ö lafosumange ndra''o ba danö si mate. Ba lö nifondrondrongou irugi da''e.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3442226, 'OT', 'Moze II', 7, 17, 'Ba imane sa''ae Yehowa: Ba da''ö aboto ba dödöu dania, wa Yehowa ndra''odo: ubözi dania nidanö ba Nilo si''o andre, si so ba dangagu, ba tobali do.[6]', '["Faigi 4:9"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 18, 'Ba yamate gi''a ba Nilo ba ya''aböu Nilo, fa ogoro Ndrawa Miserayi wamadu idanö Nilo andrö.', '["Faigi 4:9"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 19, 'Ba imane Yehowa khö Moze: ŵa''ö khö Ga''aroni: halö zi''ou andrö ba oro''ö dangau yaŵa nidanö Miserayi, yaŵa mbombo ba yaŵa lala nidanö niko''o ba yaŵa mbaŵa nidanö ba yaŵa nahia nidanö fefu: yatobali do; ya do manö ba danö Miserayi ma''asagörö, he ba nahia eu ba he ba nahia kara.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 20, 'Ba la''o''ö ira Moze A''aroni niŵa''ö Yehowa khöra. Ifazaŵa zi''onia, ibözi nidanö ba Nilo, ba zanehe Wara''o, awö ngoni-ngoninia: ba tobali do nidanö fefu, ba Nilo.[7]', '["Sin 78:44; 105:29"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 21, 'Ba i''a ba Nilo, ba mate ba aböu Nilo, tobali tebai sa''ae labadu nidanö ba Nilo Dawa Miserayi. Ba do manö fefu gofu heza ba danö Miserayi.', '["Sin 78:44; 105:29"]', NULL),
  (3442226, 'OT', 'Moze II', 7, 22, 'Ba lalau göi zi manö si fakelemu andrö, Dawa Miserayi, elemura andrö. Ba lö tebulö wa''abe''e dödö Wara''o, ba lö i''o''ö khöra, itörö niŵa''ö Yehowa.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 23, 'Ba i''erogö ira Fara''o, möi ia miyomo; lö ibe e ba dödönia.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 24, 'Ba lakhao danö Dawa Miserayi fefu, ba mbewe Nilo, wangalui idanö nibadu, me tebai labadu nidanö Nilo andrö.', '[]', NULL),
  (3442226, 'OT', 'Moze II', 7, 25, 'Ba famakao andrö, nifatörö Yehowa, ba Nilo andrö, ba alo''o fitu bongi wa''ara.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 1, 'Ba iŵa''ö Yehowa khö Moze: Ae khö Wara''o, ba ömane khönia: Da''ö niŵa''ö Yehowa: Fofanö mbanuagu andrö, ena''ö lafosumange ndra''o!', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 2, 'Ba na tekhöu, öfofanö ira, ba ufatörö khöu ba ba danöu wamakao talaho.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 3, 'Yamoliha-liha dania dalaho, ba Nilo, ba akha möi ira yaŵa, irugi gödomö ba irugi si bakha khöu, ba ba gasomö, ba he ba nomo ngoni-ngoniu, ba he ba nomo mbanuau, ba he ba naha wamogö roti khöu ba he ba naha wamaruka, numalö ösiu', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 4, 'ba ösi mbanuau ba ösi ngoni-ngoniu, ba latugelai dania talaho andrö.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 5, 'Ba imane Yehowa khö Moze: ŵa''ö khö Ga''aroni: Oro''ö dangau, fabaya si''o andrö yaŵa mbombo ba yaŵa lala nidanö niko''o ba yaŵa mbaŵa nidanö, asogö dalaho ba danö Miserayi.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 6, 'Ba i''oro''ö dangania A''aroni, yaŵa nidanö Miserayi, i''asogö dalaho, tobali lahawui danö Miserayi.[1]', '["Sin 78:45; 105:30"]', NULL),
  (3442580, 'OT', 'Moze II', 8, 7, 'Ba lalau göi da''ö si fakelemu andrö, elemura andrö, la''asogö dalaho ba danö Miserayi ma''asagörö.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 8, 'Ba ifakaoni''ö ndra Moze A''aroni Fara''o, ba imane: Mi''andrö khö Yehowa, ena''ö iheta dalaho andrö, khögu ba ba mbanuagu, ba ufofanö mbanuami andrö, ena''ö labe''e zumange khö Yehowa.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 9, 'Ba imane Moze khö Wara''o: Ebua''ö dödöu khögu, wanguma''ö khögu, ha wa''ara u''andrö khömi, khöu ba ba ngoni-ngoniu ba ba mbanuau, ena''ö aheta khöu ba ba gödomö dalaho andrö, ena''ö hatö ba Nilo tosai.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 10, 'Ba imane: Mahemolu.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 11, 'Aheta dania khömi dalaho andrö, he khöu, ba he ba gödomö, ba he ba ngoni-ngoniu, ba he ba mbanuau; hatö ba Nilo tosai dania.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 12, 'Ba me no laröi Wara''o ira Moze A''aroni, iforege wangandrö khö Yehowa Moze, ba dalaho andrö, nifatörönia khö Wara''o.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 13, 'Ba i''o''ö Yehowa ni''andrö Moze: mate dalaho andrö ba nomo misa ba ba golayama ba ba mbenua.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 14, 'Ba la''owuloi, la''oya''ö nahia, ba aböu danö.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 15, 'Ba me i''ila Fara''o, no molala dödönia, ba ifuli abe''e dödönia, ba lö i''o''ö khöra; itörö niŵa''ö Yehowa.[2]', '["Faigi 7:13"]', NULL),
  (3442580, 'OT', 'Moze II', 8, 16, 'Ba imane Yehowa khö Moze: ŵa''ö khö Ga''aroni: Oro''ö zi''omö andrö ba bözi gawu-gawu tou ba danö, ba tobali di manu, fefu gofu heza ba danö Miserayi.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 17, 'Ba la''o''ö da''ö: I''oro''ö dangania A''aroni, fabaya si''o, ibözi gawu-gawu tou ba danö: Ba so ndri manu ba niha ba ba guriföra; fefu gawu-gawu ba danö, ba tobali di manu ba danö Miserayi, ma''asagörö.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 18, 'Ba latandraigö göi si fakelemu andrö wangasogö di manu elemura andrö, ba tebai. Ba di manu andrö, ba lahawui niha, fabaya uriföra.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 19, 'Ba lamane khö Wara''o si fakelemu andrö: Tanga Lowalangi da''ö! Ba lö tebulö wa''abe''e dödö Wara''o, ba lö i''o''ö khöra; itörö niŵa''ö Yehowa.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 20, 'Ba imane Yehowa khö Moze: Mahemolu mbanua, ba ondrasi Wara''o, na möi ia mondri ba ömane khönia: Da''ö niŵa''ö Yehowa: Fofanö mbanuagu andrö, ena''ö lafosumange ndra''o.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 21, 'Na lö''ö sa öfofanö mbanuagu andrö, ba ufatörö khömi ndri mböhö, khöu ba ba ngoni-ngoniu ba ba mbanuau ba ba gödomö; ya''afönu dania nomo Ndrawa Miserayi di mböhö ba he tanö nihundragö gahera.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 22, 'Ba tanö Gozena andrö, si so banuagu andrö, ba u''oniagö, fa böi oroma ndri mböhö ba da''ö, ena''ö aboto ba dödöu, wa ya''odo Zo''aya ba danö.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 23, 'Ba u''asogö wangefa famabali mbanuagu ba mbanuamö; mahemolu alua dandra andrö.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 24, 'Ba ifatörö da''ö Yehowa. Ba oya sibai ndri mhöhö, si möi yomo ba gödo Wara''o ba ba nomo ngoni-ngoninia ba danö Miserayi ma''asagörö, ba afökhö sibai ba danö ndri mböhö andrö.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 25, 'Ba ifakaoni''ö ndra Moze A''aroni Fara''o, imane khöra: Lau! ba danö andre mifosumange Lowalangimi!', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 26, 'Ba imane Moze: Tebai ma''o''ö da''ö; sumange andrö sa, nibe''ema khö Lowalangima, ba no sogoro Ndrawa Miserayi; hadia, lö latebu kara ndra''aga dania?[3]', '["MozI 46:34","Faigi 3:18"]', NULL),
  (3442580, 'OT', 'Moze II', 8, 27, 'Tölu ngaluo fofanö wa''aröu möiga ba danö si mate, ba wame''e sumange khö Lowalangima ba da''ö; ma''o''ö niŵa''önia khöma.[4]', '["MozI 46:34","Faigi 3:18"]', NULL),
  (3442580, 'OT', 'Moze II', 8, 28, 'Ba imane Fara''o: ufofanö ami, fa mi''ila mifosumange Yehowa, Lowalangimi andrö, ba danö si mate; ba böi mi''aröu''ö sibai ami! Mi''angandrö, salahigu!', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 29, 'Ba imane Moze: He razo! ha si''aikö möido baero, ba u''andrö khöu khö Yehowa, ena''ö mahemolu aheta ndri mböhö andrö khöu ba ba ngoni-ngoniu ba he ba mbanuau, hatö fa böi öfuli ö''o''aya mbanuama, fa lö öfofanö ira ba wamosumange Yehowa.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 30, 'Ba iröi Wara''o Moze, ba mangandrö ia khö Yehowa.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 31, 'Ba i''o''ö Yehowa ni''andrö Moze, iheta ndri mböhö andrö khö Wara''o ba ba ngoni-ngoninia ba ba mbanuania, tobali sambua lö tosai.', '[]', NULL),
  (3442580, 'OT', 'Moze II', 8, 32, 'Ba ifuli abe''e dödö Wara''o, ba da''ö göi, ba lö ifofanö ira.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 1, 'Ba imane Yehowa khö Moze: Ae khö Wara''o, ba ŵa''ö khönia:', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 2, 'Na tekhöu sa wamofanö ya''ira ba na ötohugö na, ötaha ira,', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 3, 'ba ibaya tanga Yehowa gurifömö ba mbenua, he kudo ba he kalide ba he ondra ba he saŵi ba he biri-biri, ifatörö wökhö sabe''e.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 4, 'Ba ifaehusi ira, gurifö Ndraono Gizeraeli gurifö Ndrawa Miserayi Yehowa: Fefu gurifö Ndraono Gizeraeli, ba sageu lö mate.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 5, 'Ba ihonogöi Yehowa ha wa''ara, imane: Mahemolu ifatörö da''ö ba danö Yehowa.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 6, 'Ba mahemolu ö, ba ifalua Yehowa; ba ahori mate gurifö Ndrawa Miserayi; ba ba gurifö Ndraono Gizeraeli, ba sageu lö''ö, si mate.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 7, 'Ba ifatenge zinenge Fara''o, ba hiza sageu lö si mate urifö Ndraono Gizeraeli.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 8, 'Ba imane Yehowa khö ndra Moze A''aroni: Mi''ondrua tanga, wangai da''i wulaŵa, ba yamufa zawili ba dalu mbanua Moze, ba zanehe Wara''o;', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 9, 'ba atoru hawu-hawu ba danö Miserayi ma''asagörö, ba tobali gigimö dania, he ba niha ba he ba zaliŵa-liŵa ba danö, si tobali bahi ba danö Miserayi, ma''asagörö.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 10, 'Ba latuyu ndra''i wulaŵa andrö ba la''ondrasi Wara''o; ba da''ö ifazawili miyaŵa Moze, ba tobali gigimö, hulö mbahi, he ba niha ba he ba zaliŵa-liŵa ba danö.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 11, 'Ba tebai lalaŵa Moze si fakelemu andrö, ba gigimö andrö; ba zi fakelemu andrö sa''ae göi tumbu gigimö, si mane ba Ndrawa Miserayi fefu.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 12, 'Ba i''oköli''ö dödö Wara''o Yehowa, ba lö i''o''ö khöra; itörö niŵa''ö Yehowa.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 13, 'Ba imane Yehowa khö Moze: Mahemolu mbanua, ba ae khö Wara''o, ba ömane khönia:', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 14, 'Ba zi samuza andre sa, ba khöu ufatörö wamakao andrö khögu, fefu, ba ba ngoni-ngoniu ba ba mbanuau, ena''ö aboto ba dödöu, lö si mane ya''odo, ba guli danö, ma''asagörö!', '["Rom 9:17"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 15, 'Tola sa mena''ö u''oro''ö dangagu mege ba tola ufakiko ndra''ugö, fabaya banuau, fökhö waba andrö, ena''ö tebözini ndra''ugö ba guli danö.', '["Rom 9:17"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 16, 'Ba andrö lö ubabaya ndra''ugö, ena''ö ö''ila wa''abölögu, ube''e, ba ena''ö tesuno döigu ba guli danö ma''asagörö.[1]', '["Rom 9:17"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 17, 'Dörö-dörö na tekhöu wamofanö banuagu andrö.', '["Rom 9:17"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 18, 'Ba na mane wa''alaŵa luo mahemolu, ba aekhu deu kara sabölö-bölö, ube''e, si lö famaedo ba danö Miserayi, i''otarai tewöwöi ia, irege ma''ökhö andre.', '["Rom 9:17"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 19, 'Ba fatenge ba fa''orifi''ö guriföu, awö fefu hadia ia, zi so baero khöu, fefu sa zi so baero, ba niha ba he urifö, si lö möi yomo, ba mate ibe''e teu kara andrö.', '["Rom 9:17"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 20, 'Ba ha niha zangata''ufi, ngoni-ngoni Wara''o andrö, me idaö''ö-daö''ö Yehowa, ba i''oloi''ö yomo zawuyunia ba urifönia.', '["Rom 9:17"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 21, 'Ba si lö ba dödö wameta''u Yehowa ya''ira, ba lö ibulö''ö baero zawuyunia ba urifönia.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 22, 'Ba imane Yehowa khö Moze: Oro''ö dangau ba mbanua si yaŵa, ba aekhu deu kara ba danö Miserayi ma''asagörö, he ba niha ba he ba zaliŵa-liŵa ba danö ba ba zinanö ba nowi, ba danö Miserayi.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 23, 'Ba i''oro''ö zi''onia miyaŵa ba mbanua Moze, ba ilabu banua ba teu kara, ibe''e Yehowa ba aekhu zaerezaere; i''ekhugö ba danö Miserayi deu kara andrö Yehowa.[2]', '["Sin 78:47,48; Sin 105:32"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 24, 'Aekhu deu kara sabölö-bölö sibai, ba lö mamalö-malö galitö, si fabaya ba deu kara andrö; si lö famaedo, saekhu ba danö Miserayi, götö wa no mowanua niha ba da''ö.', '["Sin 78:47,48; Sin 105:32"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 25, 'Ba ibözi teu kara andrö fefu hadia ia ba danö Miserayi, si so baero, he niha ba he saliŵa-liŵa ba danö, ba sinanö ba nowi, ba ibözi teu kara andrö, ba hogu geu fefu, ba mbenua, ba afatö ibe''e.', '["Sin 78:47,48; Sin 105:32"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 26, 'Ha ba danö Gozena, ba zi so Ndraono Gizeraeli, ba lö teu kara.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 27, 'Ba ifatenge Fara''o, ifakaoni''ö ndra Moze A''aroni, ba imane khöra:', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 28, 'Mi''angandrö khö Yehowa [salahigu] no töra ndrohu-ndrohu we''ugu-ugu mbanua andrö ba teu kara andrö —, ba ufofanö ami, alakha lö mi''iagö sa''ae da''e.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 29, 'Itema linia Moze, imane: Na urugi baero mbanua, ba u''oro''ö dangagu khö Yehowa, ba tebato dania mbanua ba lö''ö sa''ae aekhu deu kara andrö, ena''ö aboto ba dödöu, wa no khö Yehowa danö.[3]', '["Sin 24:1"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 30, 'Ba ya''ugö ba ngoni-ngoniu andrö — u''ila — ba lö mi''ata''ufi Lowalangi andrö, Yehowa.', '["Sin 24:1"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 31, 'Ba taliö ba rigi ba afufu, noa sa molai rigi ba taliö, ba no mobene.', '["Sin 24:1"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 32, 'Ba gandru ba rigi ö manu, ba lö safufu, me tenga baŵa da''ö.', '["Sin 24:1"]', NULL),
  (3442356, 'OT', 'Moze II', 9, 33, 'Ba iröi Wara''o Moze, möi ia baero mbanua. Ba i''oro''ö dangania khö Yehowa, ba i''anema''ö tebato we''ugu-ugu mbanua andrö, fabaya teu kara, ba lö''ö sa''ae aekhu ba danö deu.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 34, 'Ba me i''ila Fara''o, no tebato deu ba teu kara andrö ba banua, ba itohugö molalö ba ifuli abe''e dödö, he tödönia ba he tödö ngoni-ngoninia.', '[]', NULL),
  (3442356, 'OT', 'Moze II', 9, 35, 'Ba lö tebulö wa''abe''e dödö Wara''o ba lö ifofanö Ndraono Gizeraeli, itörö niŵa''ö Yehowa.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 1, 'Ba imane Yehowa khö Moze:', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 2, 'Ba ena''ö ödunö-dunö dania ba ndraonou ba ba ma''uwumö, hadia nifatörögu ba Ndrawa Miserayi, awö dandra andrö khögu, nilaugu khöra, ena''ö aboto ba dödömi, wa no ya''o Yehowa.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 3, 'Ba möi khö Wara''o ndra Moze A''aroni, ba lamane khönia: Da''ö niŵa''ö Yehowa andrö, Lowalangi niha Heberaio: Ha wa''ara na tekhöu ö''ide-ide''ö ndra''ugö fönagu? Fofanö mbanuagu andrö, ena''ö lafosumange ndra''o!', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 4, 'Na tekhöu sa öfofanö mbanuagu, ba mahemolu, ba uasogö damo ba danöu,', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 5, 'ba alakha lahawui danö ma''asagörö, irege lö''ö sa''ae oroma danö tou. La''a dania zi tosai andrö, sauri na, ba si lö ahori na ba deu kara andrö, ba bulu geu fefu, sauri ba mbenua, ba lahori.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 6, 'Ba moliha-liha dania ira ba mbate''e khömö ba ba mbate''e ngoni-ngoniu fefu ba ba mbate''e Ndrawa Miserayi fefu, irege zi lö larai mila ira tua moroi yaŵa, irugi ma''ökhö, götö wa no so ira ba guli danö.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 7, 'Ba lamane khö Wara''o ngoni-ngoninia: Ha wa''ara tö na tatehe tandraŵada niha andrö? Fofanö sa''ae niha andrö, ena''ö lafosumange Lowalangira Yehowa. Hadia lö saboto ba dödöu na wa si tekiko danö Miserayi?', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 8, 'Ba lakaoni mangawuli khö Wara''o ndra Moze A''aroni, ba imane khöra: Ba mi''ae''e ba mifosumange Lowalangimi Yehowa; ba ha niha atö zi möi miŵa''ö?', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 9, 'Imane Moze: Ono sawuyu khöma ba satua khöma, ba ma''ohe; ba ono matua khöma ba ono alawe ba biri-birima ba saŵima, ba ma''ohe; so sa khöma gowasa, nilau khö Yehowa.[1]', '["Faigi 5:1"]', NULL),
  (3443011, 'OT', 'Moze II', 10, 10, 'Ba imane khöra: Lau! Yamutolo ami Yehowa, na ufa''ohe''ö khömi ndraono sawuyu khömi; si ndruhu, no so ba dödömi zi lö sökhi!', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 11, 'Tebai da''ö; akha möi ndra matua mamosumange Yehowa; ha sa da''ö niŵa''ömi! Ba lafofanö ira ba da''ö khö Wara''o.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 12, 'Ba imane Yehowa khö Moze: Oro''ö dangau yaŵa danö Miserayi ba asogö damo, alakha lahawui danö Miserayi, ba wangohori fefu zinanö ba danö, fefu hadia ia zi tosai ba deu kara no.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 13, 'Ba i''oro''ö zi''onia Moze yaŵa danö Miserayi, ba ifatörö ba danö nangi timu Yehowa, sara luo sara mbongi; ba me moluo, ba no i''ohe damo angi timu andrö.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 14, 'Ba lahawui danö Miserayi tamo andrö, dozi banua ba danö Miserayi aekhu ira, oya sibai; lö irai si manö wa''oya föna, damo, ba lö''ö manö göi ifuli si manö dania.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 15, 'Ba lahawui danö ma''asagörö, tobali lö''ö sa''ae oroma danö tou; ba lahori fefu zinanö ba danö ba bua geu fefu, si tosai ba deu kara no; tobali ma''ifu lö tosai bulu sauri, he ba geu ba he ba zinanö ba danö, ba danö Miserayi, ma''asagörö.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 16, 'Ba i''aliogö ifakaoni''ö ndra Moze A''aroni Fara''o, ba imane: No sala ndra''odo khö Yehowa, Lowalangimi, ba khömi göi.[2]', '["Faigi 9:27"]', NULL),
  (3443011, 'OT', 'Moze II', 10, 17, 'Ba mibologö dödömi khögu ba lalögu andrö, hatö zi samuza andre, ba mi''angandrö khö Lowalangimi, Yehowa, salahigu, ena''ö itimba atö khögu wamunu andre!', '["Faigi 9:27"]', NULL),
  (3443011, 'OT', 'Moze II', 10, 18, 'Ba iröi Wara''o [Moze] ba mangandrö ia khö Yehowa.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 19, 'Ba ifatörö nangi sabe''e moroi ba gaekhula Yehowa, zuzumö, sangoloi''ö tamo andrö ba sanibo ba nasi zukhu; sambua lö tosai tamo, ba danö Miserayi ma''asagörö.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 20, 'Ba i''abe''e''ö dödö Wara''o Yehowa, ba lö ifofanö Ndraono Gizeraeli.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 21, 'Ba imane Yehowa khö Moze: Oro''ö dangau miyaŵa ba mbanua, ba ihawui danö Miserayi fa''ogömi-gömi, tobali la''ila mura''u tanga wa''ogömi-gömi andrö.[3]', '["Mat 27:45"]', NULL),
  (3443011, 'OT', 'Moze II', 10, 22, 'Ba i''oro''ö dangania miyaŵa, ba mbanua, Moze, ba ihawui fa''ogömi-gömi danö Miserayi ma''asagörö, tölu bongi wa''ara.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 23, 'Tobali lö i''ila nawönia zamösana, ba tebai maoso, tebai iröi nahania zi tölu bongi andrö.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 24, 'Ba ifakaoni ö Moze Fara''o, imane: Mi''ae''e ba wamosumange Yehowa; ba biri-birimi ba saŵimi, ba toröi; iraono sawuyu khömi, ba hana na fao.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3443011, 'OT', 'Moze II', 10, 25, 'Ba imane Moze: Ya''ugö zama''ohe''ö khöma sumange nitaba ba sumange nitunu, ena''ö ma''asiwai khö Lowalangima Yehowa,', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 26, 'ba si fao göi guriföma — sambua sa''a lö tola toröi furi, me soguna khöma ba wamosumange Lowalangima Yehowa; lö''ö sa ma''ila na, he mawisa wamosumange Yehowa, irege no marugi da''ö.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 27, 'Ba i''abe''e''ö dödö Wara''o Yehowa, ba tekhönia ifofanö ira.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 28, 'Ba imane khönia Fara''o: Labu''ögö! Angelama, fa böi sa''ae fa''ila bawa ita; na fa''ila bawa ita sa, ba si mate ndra''ugö.', '[]', NULL),
  (3443011, 'OT', 'Moze II', 10, 29, 'Ba imane Moze: Ba no öŵa''ö; lö''ö sa''ae fa''ila bawa ita.', '[]', NULL),
  (3443129, 'OT', 'Moze II', 11, 1, 'Ba imane Yehowa khö Moze: Hatö sambalö tö famakao ufatörö khö Wara''o ba ba Ndrawa Miserayi; awena dania ifofanö ami ba da''e, ifaulugö, itimba na''i ami, iforege.', '["Faigi 3:22"]', NULL),
  (3443129, 'OT', 'Moze II', 11, 2, 'Ba öŵa''ö ba zato, dozi ira, ba ndramu''andrö ba zi so ba ngaira gama-gama firö ba gama-gama ana''a; he ira matua ba he ira alawe.[1]', '["Faigi 3:22"]', NULL),
  (3443129, 'OT', 'Moze II', 11, 3, 'Ba ebua dödö Ndrawa Miserayi khöra ibe''e Yehowa; ba sebua töi göi Moze ba danö Miserayi, ba ngoni-ngoni Wara''o andrö ba ba mbanuania.', '["Faigi 3:22"]', NULL),
  (3443129, 'OT', 'Moze II', 11, 4, 'Ba imane Moze: Da''ö niŵa''ö Yehowa: Na talu mbongi, ba utöröi danö Miserayi ma''asagörö,[2]', '["Faigi 12:29"]', NULL),
  (3443129, 'OT', 'Moze II', 11, 5, 'ba ahori mate zi a''a nono matua ba danö Miserayi, i''otarai nono si a''a khö Wara''o, sidadao ba dadaoma razo, numalö ba nono si a''a khö zawuyu ira alawe, sanutu fakhe, fabaya nono si a''a ba gurifö fefu.', '["Faigi 12:29"]', NULL),
  (3443129, 'OT', 'Moze II', 11, 6, 'Ba tobali fe''ira-ira sabölö-bölö ba danö Miserayi ma''asagörö, si lö irai, ba lö''ö manö göi ifuli si manö dania.', '["Faigi 12:29"]', NULL),
  (3443129, 'OT', 'Moze II', 11, 7, 'Ba ba Ndraono Gizeraeli, fefu, ba lö nikhau nasu, he niha ba he urifö, ena''ö aboto ba dödömi, wa ifaehusi ira Ndrawa Miserayi Ndraono Gizeraeli Yehowa.', '["Faigi 12:29"]', NULL),
  (3443129, 'OT', 'Moze II', 11, 8, 'Ba ndramu''ondrasido dania ngoni-ngoniu andrö fefu, ba wangalulu khögu ba ba wangandrö khögu: Heta''ö, ya''ugö ba banuami fefu, solo''ö khöu! ba awena dania uhetado. Aefa da''ö, ba iröi Wara''o, mofönu sibai ia.', '["Faigi 12:29"]', NULL),
  (3443129, 'OT', 'Moze II', 11, 9, 'Ba imane Yehowa khö Moze: Lö i''o''ö khömi Fara''o, ena''ö oya dandra andrö khögu, ba danö Miserayi.', '[]', NULL),
  (3443129, 'OT', 'Moze II', 11, 10, 'Ba lalau dandra andrö fefu föna Wara''o ira Moze A''aroni; ba i''abe''e''ö dödö Wara''ö Yehowa, ba tobali lö i''efa''ö Ndraono Gizeraeli ba danönia.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 1, 'Ba imane Yehowa khö ndra Moze A''aroni, ba danö Miserayi:', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 2, 'Si a''a mbaŵa khömi dania mbaŵa da''e; böröta mbaŵa ia khömi ba ndröfi.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 3, 'Mimane ba mbanua Ndraono Gizeraeli fefu: Ba zi mewulu ba mbawa da''e, ba ya mufaigi khönia nono mbiri-biri zamösana, sambua-sambua omo, ba sara-sara nono mbiri-biri.[1]', '["Yoh 1:29"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 4, 'Ba na ambö fa''ato zi samba omo, ba zi sara ono mbiri-biri, ba yamuhalö awönia zi fahatö omo khönia, ba wangai si sara, dali wa''ato niha; ha wa''ato zi tola mangohori ya''ia, ba sara nono mbiri-biri mihonogöi.', '["Yoh 1:29"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 5, 'Ono mbiri-biri si lö hadia ia zi sala nifaigi, si matua ba si döfi fa''ebua; na tenga ono mbiri-biri, ba ono nambi nitutuyu.[2]', '["MozIII 1:3; 22:21","MozIV 9:5"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 6, 'Ba mihoe, irugi zi meweleöfa ba mbaŵa da''e, ba tanö owi lataba, dozi Iraono Giseraeli.[3]', '["MozIII 1:3; 22:21","MozIV 9:5"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 7, 'Ba ndramuhalö ösa ndro, ba lagule''ö ba gehomo, fatambai mbaŵandruhö ba ba högö mbawandruhö, ba nomo andrö, ba ni''a ya''ia.', '["MozIII 1:3; 22:21","MozIV 9:5"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 8, 'Ba ösinia, ba ba zi bongi andrö la''a, nitunu; roti si lö mu''aisöni ba bulu ndru''u safeto nawö.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 9, 'Böi mi''enata, ba tenga nirino ba nidanö, mitunu ba galitö, ma''asara, tenga nifaefa hadia ia: fabaya alakhaö.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 10, 'Ba ma''ifu böi misaigö irege mahemolu; hadia zi tosai irege mahemolu mbanua, ba nitunu.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 11, 'Ba mimane ba wemanga: Si no mamöbö talu ami ba so mbadagahe ba gahemi ba si''o ba dangami; ba mita''i-ta''i wemanga ya''ia! Fasa ia khö Yehowa.[4]', '["Mat 26:17; Heb 11:28"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 12, 'Ba zi bongi andrö sa utöröi danö Miserayi, ba ububunu nono si a''a fefu, ba danö Miserayi, he ba niha ba he ba guriföra; ba la''ila dania wa''abölögu fefu Lowalangi Miserayi ube''e, ya''o, Yehowa![5]', '["MozIV 33:4; Sin 136:10"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 13, 'Ba do andrö ba nomo, ba zi so ami, ba tandra khögu, fangorifimi; na u''ila ndro andrö, ba utalu''i ami, fa lö göna ami famakao, famakiko andrö, na ulau ba Ndrawa Miserayi.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 14, 'Ba baŵa da''ö, ba baŵa wamasugi ba dödö khömi dania; baŵa gowasa khö Yehowa dania ia khömi, götö-götö wa''ara; si lö tebulö khömi wolau ya''ia, irugi zi lö aetu.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 15, 'Fitu bongi wa''ara mi''a roti si lö mu''aisöni. Ba mböröta mbaŵa da''ö sa''ae, ba böi falukha ba nomomi danömö roti; ha niha sa zi manga roti ni''aisöni, götö zi fitu bongi andrö, ba nise''e ba Ndraono Gizeraeli.[6]', '["Faigi 23:15; KorI 5:7"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 16, 'Ba na luo si föföna andrö, ba owulo ami ba ni''amoni''ö andrö ba si manö göi na luo si fitu; ba ba luo da''ö, ba ma''ifu manö lö lahalö halöŵö; ha soguna ö zamösana, ba tola mihalö.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 17, 'Ba böi olifu ami roti si lö mu''aisöni no mege; me ba mbaŵa da''ö uheta ngahönömi ba danö Miserayi, andrö, mitöngöni mbaŵa da''ö, götö-götö wa''ara, nihonogöi, sirugi si lö aetu.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 18, 'Ba mbaŵa si föföna andrö, ba zi meweleöfa, ba zi bongi, ba da''ö mi''a roti si lö mu''aisöni ba irugi ba zi bongi ba zi meönö gakhömita.[7]', '["MozIII 23:6; MozIV 28:17; MozV 16:3"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 19, 'Fitu bongi wa''ara, ba lö tola falukha danömo roti ba nomomi; ha niha sa zi manga roti ni''aisöni, ba nise''e ba mbanua Ndraono Gizeraeli, he na niha bö''ö ba he na iwara.', '["MozIII 23:6; MozIV 28:17; MozV 16:3"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 20, 'Sambawa böi mi''a roti ni''aisöni. Fefu gofu heza, ba zi so ami, ba roti si lö mu''aisöni mi''a.', '["MozIII 23:6; MozIV 28:17; MozV 16:3"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 21, 'Ba ifakaoni''ö zatua Ndraono Gizeraeli fefu Moze, ba imane khöra: Milabu, mifaigi khömi nono mbiri-biri, ö zoroiyomomi, samba-samba omo, ba mitaba wasa andrö.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 22, 'Ba mihalö zambua muru-muru duturu zufa ba mi''ungugö ba ndro andrö, ba wiga yaŵa, ba migule''ö ösa ndro andrö ba wiga ba högö mbawandruhö ba ba gehomo fatambai; ba samösa böi yamöi tou, böi miröi nomomi, iregi moluo.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 23, 'Itörö sa danö Yehowa, ba wolau ba Ndrawa Miserayi, ba na i''ila ndro andrö ba högö mbawandruhö ba ba gehomo fatambai, ba italu''i mbawandruhö si manö Yehowa, ba lö itehe ba zamakiko andrö we''amöi yomo khömi, ba wolau khömi.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 24, 'Ba milau da''ö, amakhoita khöu ba ba nga''ötöu, irugi zi lö aetu.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 25, 'Ba na mirugi dania danö andrö nibe''e Yehowa okhötami, si mane nifabu''unia, ba mitörö da''ö wamosumange Lowalangi.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 26, 'Ba na lasofu dania khömi iraonomi, na lamane: Hadia khömi wamosumange andrö?', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 27, 'ba mimane khöra: Sumange fasa khö Yehowa, sanalu''i omo Ndraono Gizeraeli, me ilau ba Ndrawa Miserayi, fa lö ibabaya zi so yomo khöda. Ba lafaöndrö ira sato, mangalulu.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 28, 'Ba möi Ndraono Gizeraeli, la''o''ö niŵa''ö Yehowa khö ndra Moze A''aroni; da''ö lalau.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 29, 'Ba me talu mbongi, ba ahori ibubunu Yehowa nono si a''a ba danö Miserayi, i''otarai nono si a''a khö Wara''o, sidadao ba dadaoma razo khönia, numalö ba nono si a''a ba nikuru, si so ba gurunga, awö fefu nono si a''a ba gurifö.[8]', '["Sin 78:51; 135:8"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 30, 'Ba maoso Wara''o, awö ngoni-ngoninia, awö Ndrawa Miserayi fefu, ba zi bongi andrö ba tesao wege-ege sabölö-bölö, ba danö Miserayi; sambua sa lö omo, si lö si mate.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 31, 'Ba ifakaoni''ö ndra Mose A''aroni Fara''o, ba zi bongi, ba imane: Milabu! miheta ami, mifabali ami ba mbanuagu, he ya''ami ba he Iraono Gizeraeli andrö; mi''ae mifosumange Yehowa, mitörö ni''andrömi andrö.[9]', '["SamI 6:6; Sin 105:38","Faigi 10:26"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 32, 'Ba biri-birimi göi, ba saŵimi, ba mi''ohe, si mane ni''andrömi; miheta ami ba mi''andrö khögu göi howu-howu.[10]', '["SamI 6:6; Sin 105:38","Faigi 10:26"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 33, 'Ba lalulugö ira Dawa Miserayi, ena''ö la''aliogö wangeheta ya''ira ba danö; lamane sa dödöra: ahori mate ita!', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 34, 'Ba la''ohe gomböila roti andrö sato, si lö fakhamö aisö na, la''angalisigö nahia, ni''olöwösi ba lembera.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 35, 'Ba no la''o''ö niŵa''ö Moze khöra Iraono Gizeraeli, no la''andrö ba Ndrawa Miserayi gama-gama firö ba gama-gama ana''a, awö nukha.[11]', '["Faigi 3:21; 11:12"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 36, 'Ba no ibe''e Yehowa ebua dödö Ndrawa Miserayi khöra, wolo''ö khöra; ba tobali larabu gama-gama Ndrawa Miserayi.', '["Faigi 3:21; 11:12"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 37, 'Ba aheta ba Ramese Ndraono Gizeraeli, lasaŵa Zukota, mato 600,000 niha, sanörö tanö, ira matua, lö lai ndraono.[12]', '["MozIV 33:3"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 38, 'Ba ato göi zi fao khöra niha [bö''ö] ba biri-biri ba saŵi, oya sibai gurifö.', '["MozIV 33:3"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 39, 'Ba labogö gomböila roti no mege, ni''ohera moroi ba danö Miserayi, labali''ö kue si lö mu''aisöni; lö''ö sa si fakhamö aisö, me nilulugö ira, ba wondröi tanö Miserayi, ba me tebai sa''ae tebato ira, ba wamaigi khöra nifatö''ö ena''ö.', '["MozIV 33:3"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 40, 'Ba fa''ara Ndraono Gizeraeli ba danö Miserayi, ba öfa ngaotu a tölu ngafulu fakhe.[13]', '["MozI 15:13; HalZin 7:6"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 41, 'Ba me no alua zi öfa ngaotu a tölu ngafulu fakhe, me luo da''ö sibai, ba aheta ba danö Miserayi ngahönö andrö khö Yehowa.', '["MozI 15:13; HalZin 7:6"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 42, 'Bongi wangorifi khö Yehowa, me iheta ira ba danö Miserayi. Ni''amoni''ö mbongi andrö khö Yehowa, me no fangorifi ba Ndraono Gizeraeli fefu; götö-götö wa''ara.', '["MozI 15:13; HalZin 7:6"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 43, 'Ba imane Yehowa khö ndra Moze A''aroni: Da''ö gamakhoita ba wasa andrö: lö tola i''a wöfö niha bö''ö.', '["MozIV 9:12; Yoh 19:36"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 44, 'Ba awena tola la''a dozi sawuyu nihöli, na no muboto ira.', '["MozIV 9:12; Yoh 19:36"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 45, 'Si fatewu ba enoni, ba lö tola la''a.', '["MozIV 9:12; Yoh 19:36"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 46, 'Nifasambua nomo ba ni''a ya''ia; lö tola la''ohe hadia ia, nösi. Sara töla böi mifatö khönia.[14]', '["MozIV 9:12; Yoh 19:36"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 47, 'Dozi Iraono Gizeraeli zolau ya''ia.', '["MozIV 9:12; Yoh 19:36"]', NULL),
  (3443370, 'OT', 'Moze II', 12, 48, 'Ba na so niha bö''ö, somasi sosó khömi ba molau fasa khö Yehowa, ba niboto fefu motöi matua ba khöra; awena dania tola la''ondrasi, ba wolau, ba iwami sa''ae ira, miŵa''ö. Ba si lö muboto, ba lö''ö manö tola i''a.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 49, 'Ha sambua goroisa, he ba niwami ba he ba niha bö''ö, si soso ba khömi.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 50, 'Ba la''o''ö niŵa''ö Yehowa khö ndra Moze A''aroni dozi Iraono Gizeraeli; lamanö wolau.', '[]', NULL),
  (3443370, 'OT', 'Moze II', 12, 51, 'Ba me luo da''ö iheta ba danö Miserayi Ndraono Gizeraeli Yehowa, ba ngahönöra.', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 1, 'Ba imane Yehowa khö Moze:', '["Faigi 22:29; SamI 1:28; Luk 2:23"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 2, 'Oniagö khögu fefu zi a''a nono, ni''amoni''ö; fefu hadia ia zi a''a ba wa''atumbu khö ninania, ba Ndraono Gizeraeli, he niha ba he urifö, ba khögu da''ö.[1]', '["Faigi 22:29; SamI 1:28; Luk 2:23"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 3, 'Ba imane Moze ba zato: Mitörö-törö tödömi mbaŵa da''e, saheta ami ba danö Miserayi ba danö si no sawuyu ami; noa sa iheta ami ba da''ö Yehowa tanga sabölö; andrö wa lö tola te''a roti si no mu''aisöni.', '["Faigi 23:15"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 4, 'Ma''ökhö andre aheta ami, ba mbaŵa Abibi.[2]', '["Faigi 23:15"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 5, 'Ba na i''ohe ndra''ugö Yehowa ba danö Ndrawa Gana''ana andrö, ba danö Ndraono kheti ba ba danö Ndraono Gamori ba ba danö Ndraono Hewi ba ba danö Ndraono Yebusi, nifabu''unia khö ndra tuau fahölusa fame''e khöu, tanö ba zi falawu susu ba ŵe ŵani, ba böi olifu''ö wamosumange andrö, ba mbaŵa da''e.[3]', '["MozI 15:18"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 6, 'Fitu bongi wa''ara, ba roti si lö mu''aisöni mi''a; ba ba luo si fitu, ba telau gowasa khö Yehowa.', '["MozI 15:18"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 7, 'Roti si lö mu''aisöni ni''a, götö zi fitu bongi andrö ba lö tola falukha ba khöu roti si no mu''aisöni ba he tanömö roti, ba mbanuami fefu.', '["MozI 15:18"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 8, 'Ba na luo da''ö, ba ödunö-dunö ba ndraonou matua, ömane: Börö wanolo Yehowa ya''aga; da''ö nilau Yehowa khöma, me ahetaga ba danö Miserayi.', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 9, 'Ba hulö dandra ia ba dangau, ila-ila ba gangangou, ena''ö so ba mbeweu goroisa Yehowa; fa''abölö danga Yehowa sa wangeheta ya''ugö ba danö Miserayi.', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 10, 'Andrö böi olifu''ö gamakhoita andrö, ero röfi, na inötönia.', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 11, 'Ba na i''ohe dania ndra''ugö Yehowa ba danö Ndrawa Gana''ana andrö, na itörö zi fahölu ia mege khöu ba khö ndra tuau, na ibe''e khöu,', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 12, 'ba ö''amoni''ö khö Yehowa fefu zi a''a ba wa''atumbu khö ninania; fefu zi a''a nono gurifö, si falukha''ö, na si matua, ba tana khö Yehowa.', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 13, 'Ba fefu zi a''a nono galide ba ösalahini ono mbiri-biri; ba na lö omasi''ö ösalahini, ba öfatö mbaginia. Ba ono si a''a ba niha, fefu, ba ösalahini [öhöli].', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 14, 'Ba na isofu dania khöu onou: Hadia geluaha da''ö? ba ömane khönia: No ihetaga Yehowa ba danö Miserayi tanga sabölö, ba danö ba zi no sawuyu ndra''aga.', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 15, 'Me no abe''e dödö Wara''o, me lö ifofanöga mena''ö, ba no ibubunu nono si a''a fefu ba danö Miserayi Yehowa, he ono si a''a ba niha ba he ono si a''a ba wa''atumbu ba gurifö; andrö ube''e sumange Yehowa zi a''a ba wa''atumbu fefu, na si matua, ba ono si a''a khögu, ba usalahini, [uhöli].', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 16, 'Ba ya hulö dandra ia khöu, ba dangau ba amaedola harefa ba gangangou, wa no ihetaga ba danö Miserayi Yehowa, tanga sabölö.', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 17, 'Ba me no ifofanö ira Fara''o, ba lö ifatörö ira ba lala ba danö Ndrawa Wilisiti Lowalangi, he ŵa''ae sahatö da''ö mena''ö; imane sa dödönia Lowalangi: ma mangesa dödöra, na so zi fasuwö khöra ba ma lafuli ira ba danö Miserayi;', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 18, 'lafasui ibe''e Lowalangi, latörö lala ba danö si mate, saekhu ba nasi zukhu, ba no lafa''anö ira ba wanuwö, Iraono Gizeraeli, me aheta ira ba danö Miserayi.', '[]', NULL),
  (3443794, 'OT', 'Moze II', 13, 19, 'Ba i''ohe mboto Yosefo andrö Moze; noa sa ibe''e li ba Ndraono Gizeraeli da''ö, no ibe''e ira ba hölu sabe''e, no imane: na itolo dania ami Lowalangi, ba mi''ohe mbotogu, miheta ba da''e.[4]', '["MozI 50:25"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 20, 'Ba la''otarai Zukota wofanö ba ba Getama molombase, ba zinga danö si mate andrö.[5]', '["MozIV 33:6","Faigi 40:38; Neh 9:19; Sin 78:14; Sin 105:39; KorI 10:1"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 21, 'Ba mowaö-waö fönara Yehowa, na ma''ökhö, ba boto lawuo, ba wangoroma''ö lala khöra, ba na bongi, ba boto galitö, ba wame''e haga khöra; ba tobali bongi ma''ökhö la''ila mofanö.[6]', '["MozIV 33:6","Faigi 40:38; Neh 9:19; Sin 78:14; Sin 105:39; KorI 10:1"]', NULL),
  (3443794, 'OT', 'Moze II', 13, 22, 'Na ma''ökhö, ba lö tebulö fönara mboto lawuo andrö, ba ba zi bongi, ba si manö mboto galitö andrö.', '["MozIV 33:6","Faigi 40:38; Neh 9:19; Sin 78:14; Sin 105:39; KorI 10:1"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 2, 'Ŵa''ö ba Ndraono Gizeraeli, mdramuhole''ö ira, ba ba Wihakhiroti, ba gotaluara Migidolo nasi molombase ira, ba zinga Mba''ali Zefono; faudu da''ö, ba mbewe nasi molombase ami.', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 3, 'Ba imane dödönia Fara''o, ba Ndraono Gizeraeli andrö: "No elungu ira ba danö; no te''u''u ira ba danö si mate."', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 4, 'Ba u''abe''e''ö dania dödö Wara''o, ba igohi ira; ba u''oroma''ö dania wa''abölögu ba khö Wara''o andrö ba ba zabölö andrö khönia fefu, ba ya''aboto dania ba dödö Ndrawa Miserayi, wa no ya''o Yehowa.', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 5, 'Ba te''ombakha''ö khö razo Miserayi, wa no moloi ira; ba afökhö dödö Wara''o ba tödö ngoni-ngoninia, khöra andrö, lamane sa: Hana wa no tamanö, wa no tafofanö Ndraono Gizeraeli andrö, fa böi lahalö halöŵö khöda!', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 6, 'Ba ifa''anö guretania ba i''ohe zabölö andrö khönia.', '["MozIV 33:3","Yos 24:6"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 7, 'önö ngaotu i''ohe kureta ba wanuwö, awö niha nitutuyu, awö gureta ba wanuwö fefu ba Ndrawa Miserayi; ba dozi kureta, ba so yaŵa zi fasöndra soroi ba gureta.', '["MozIV 33:3","Yos 24:6"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 8, 'Ba Yehowa, ba i''abe''e''ö dödö Wara''o, razo Miserayi; ba igohi Ndraono Gizeraeli, ba no mama''anö ba wanuwö Ndraono Gizeraeli, wanörö lalara.[2]', '["MozIV 33:3","Yos 24:6"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 9, 'Ba lagohi ira Dawa Miserayi, ba lakhamö, me molombase ira ba mbewe nasi; ahori so kudo andrö khö Wara''o ba kuretania ba wanuwö ba si fakudo ba sabölö andrö khönia, ba zinga Wihakhiroti, ba ngai Mba''ali Zefono.[3]', '["MozIV 33:3","Yos 24:6"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 10, 'Ba me no ahatö Wara''o, ba lafakhölö ira Iraono Gizeraeli: ba i''ogomuzaö so moroi furira Ndrawa Miserayi. Ba ata''u sibai ira. Ba la''angaröfi li Yehowa Iraono Gizeraeli.', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 11, 'Ba lamane khö Moze: Hadia, ambö mege lewatö ba danö Miserayi, wa ödönisiga baero, ena''ö ba danö si mate tekiko ndra''aga? Hana wa ömanö khöma, wa öhetaga ba danö Miserayi?[4]', '["Sin 106:7"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 12, 'Hadia, tenga da''ö niŵa''öma khöu mege, ba danö Miserayi: Böhöliga, ba damahalö halöŵö Ndrawa Miserayi, halöŵö zawuyu? Ohahau sa mena''ö dödöma, na mahalö halöŵö Ndrawa Miserayi, moroi tekiko ndra''aga ba danö si mate!', '["Sin 106:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3444052, 'OT', 'Moze II', 14, 13, 'Ba imane Moze ba zato: Böi mi''ata''ufi! Mi''abe''e''ö dödömi, ba mi''ila dania wangorifi andrö si falukha ami khö Yehowa ma''ökhö; hadia sa ni''ilami ma''ökhö nifatörö ba Ndrawa Miserayi, ba lö''ö manö sa''ae mi''ila dania ba khöra, götö-götö wa''ara.[5]', '["Nga''ötII 20:15"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 14, 'Yehowa zi fasöndra salahimi, ba sahono ami.', '["Nga''ötII 20:15"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 15, 'Ba imane Yehowa khö Moze: Hadia wa ö''angaröfi li ndra''o? ŵa''ö ba Ndraono Gizeraeli, ndramufazaŵa ira.', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 16, 'Ba ya''ugö, ba fazaŵa zi''ou ba oro''ö dangau yaŵa nasi; ba faefa ia, ba latörö dania dalu nasi Iraono Gizeraeli, hulö na ba zabe''e tanö so ira.', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 17, 'Ba ufobalunö Ndrawa Miserayi, ena''ö la''o''ö ira, ba u''oroma''ö wa''abölögu, ba khö Wara''o ba ba zabölö andrö khönia fefu, ba ba guretania andrö ba ba zi fakudo andrö khönia,', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 18, 'ena''ö aboto ba dödö Ndrawa Miserayi, wa no ya''o Yehowa, na u''oroma''ö wa''abölögu ba khö Wara''o ba ba zabölö andrö khönia ba ba guretania ba ba zi fakudo.', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 19, 'Ba ifazaŵa ia mala''ika Lowalangi andrö, sowaö-waö föna ngahönö Ndraono Gizeraeli, möi ia furira. Ba iheta göi ia fönara boto lawuo andrö, möi furira göi.[6]', '["Faigi 13:21"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 20, 'Ba möi ba gotaluara golombaseŵa Ndrawa Miserayi golombaseŵa Ndraono Gizeraeli, ba no lawuo ba zogömi-gömi, ba ihagaini zi bongi. Ba tebai fahatö ira zi sara wongi andrö.', '["Faigi 13:21"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 21, 'Ba i''oro''ö dangania Moze yaŵa nasi, ba ahele nasi ibe''e Yehowa, sara wongi manö ba nangi sabe''e, si oroi ba gatumbukha luo, ba otufo nasi ibe''e; fabali nidanö.[7]', '["Yos 4:23; Sin 78:13; 114:3; Yes 63:12","KorI 10:1; Heb 11:29"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 22, 'Ba latörö dalu nasi Iraono Gizeraeli, hulö na ba danö sabe''e, ba amaedola mbagolö nasi, he ba gambölöra, ba he ba gaberara.[8]', '["Yos 4:23; Sin 78:13; 114:3; Yes 63:12","KorI 10:1; Heb 11:29"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 23, 'Ba lagohi ira Dawa Miserayi, la''o''ö ira moroi furi, kudo andrö khö Wara''o, fefu, awö gureta, awö zi fakudo, ba dalu nasi bakha.', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 24, 'Ba me miwo manu, ba ifaigi Yehowa zabölö Ndrawa Miserayi andrö, moroi ba mboto galitö andrö, moroi ba mboto lawuo ba ifakuyu ira.', '["Yos 10:14"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 25, 'Adeha gaolo ba gureta andrö khöra ibe''e, tobali tosasa ira. Ba lamane Dawa Miserayi: Talau moloi, ba Ndraono Gizeraeli andrö! Yehowa sa zi fasöndra ba Ndrawa Miserayi, salahira.[9]', '["Yos 10:14"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 26, 'Ba imane Yehowa khö Moze: Oro''ö dangau yaŵa nasi, ba ihawui Ndrawa Miserayi asi, fabaya kureta khöra ba si fakudo!', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 27, 'Ba i''oro''ö dangania Moze yaŵa nasi, ba mangawuli ba nahania nasi, me arakha moluo, ba lafaondragö ia Dawa Miserayi woloi, ba itaboi ba dalu nasi Ndrawa Miserayi Yehowa.', '["Yos 3:16"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 28, 'Ba ifuli fahalö nasi ba ihawui gureta, awö zi fakudo — sabölö andrö khö Wara''o fefu — si no molo''ö ya''ira, bakha ba nasi; samösa lö sauri, ya''ira andrö.', '["Yos 3:16"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 29, 'Ba no latörö nasi Iraono Gizeraeli, hulö na ba danö sabe''e, ba amaedola mbagolö nasi, he ba gambölöra, ba he ba gaberara.[10]', '["Yos 3:16"]', NULL),
  (3444052, 'OT', 'Moze II', 14, 30, 'Si manö wangorifi Yehowa Iraono Gizeraeli ba Ndrawa Miserayi, me luo da''ö, ba la''ila tou ba mbewe nasi Ndrawa Miserayi, si no mate, Iraono Gizeraeli.', '[]', NULL),
  (3444052, 'OT', 'Moze II', 14, 31, 'Ba aboto ba dödö Ndraono Gizeraeli zabölö sibai andrö, nilau Yehowa ba Ndrawa Miserayi. Ba la''ata''ufi Yehowa sato, ba faduhu dödöra khö Yehowa ba khö genoninia andrö, Moze.', '[]', NULL),
  (3444228, 'OT', 'Moze II', 15, 1, 'Me luo da''ö lalau zinunö andre Moze ba Iraono Gizeraeli, wanuno Yehowa, lamane wanunö:', '[]', NULL),
  (3444228, 'OT', 'Moze II', 15, 2, 'Fa''abölögu Yehowa ba fanunögu, me no sangorifi ya''odo ia; Lowalangigu ia, andrö usuno ia — Lowalangi namagu andrö, u''ebua''ö duriania.[1]', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 3, 'Sabölö ba wanuwö Yehowa andrö; Yehowa döinia.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 4, 'Kureta andrö khö Wara''o ba sabölö andrö khönia, ba no ituli''ö ba nasi, ba nitutuyu andrö, si fasöndra moroi ba gureta yaŵa, ba no alömö ba nasi zukhu.[2]', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 5, 'No ibalugö ira namö nasi; ba dawuyu ahöndrö ira, hulö gara.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 6, 'Si so lakhömi dangau kambölö, ya''ugö, Yehowa, ba wa''abölönia andrö. Tangau kambölö andrö, ya''ugö, Yehowa, ba irasa nemali.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 7, 'Ba ba wa''asalaŵamö andrö, si no ebua sibai, ba öhori zi fa''udu khöu. Na öbe''e tesao mbakhu-bakhu dödöu, ba i''a ira, si mane femanga galitö döla wakhe.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 8, 'Ba wehöfu-höfumö, ba wönumö, toba''a nidanö; abe''e hohou, hulö mba''a-ba''a; hulö zi baku hou nasi.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 9, 'Imane emali: Da''ugohi ira, ukhamö dania: ufaosa dania nirabu, u''abusoi''ö ndra''o ba khöra. Udöni zi''öli; ihori ira tangagu andre.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 10, 'Öfatörö hanu-hanumö andrö, ba ihawui ira asi; ahöndrö ira, hulö zimo, ba nasi sebua sibai.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 11, 'Ha niha Lowalangi si fagölö-gölö khöu, ya''ugö. Yehowa! Ha niha zi fagölö-gölö khöu, ya''ugö, salaŵa sebua lakhömi, ya''ugö, sata''u ita, ba wolaumö andrö, sebua turia, solau sahöli-höli dödöda![3]', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 12, 'Ö''oro''ö dangau, ba itölö ira tanö.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 13, 'No öfasao fa''ebua dödöu soi andrö si no ö''efa''ö; no ö''ohe ba nahiau ni''amoni''ö andrö, fa''abölöu.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 14, 'Me larongo niha baero, ba manizi-nizi ira; ihawui Ndrawa Wilisiti fa''ata''u.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 15, 'Tobali dödö zalaŵa Ndraono Gedomo, ba ihawui zolohe Iraono Moabi fogikhi dödö; aragu-ragu dödö mbanua ba danö Gana''ana fefu.[4]', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 16, 'Ihawui ira fa''atobali dödö ba fa''ata''u; ba nilau dangau andrö, si no ebua, tobali hulö gara ira, ba latörö banuau, ya''ugö, Yehowa; latörö banua andrö, nituyumö khöu.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 17, 'No ö''ohe ira ba no ötanö ira ba hili andrö, ba hili tana khöu andrö, ba nahia andrö, nihaogöu khöu, ya''ugö, Yehowa, ena''ö ba da''ö soso''ö, ba ni''amoni''ö andrö, ya''ugö, So''aya, ba nihaogö dangau.', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 18, 'Razo Yehowa, götö-götö wa''ara![5]', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 19, 'Me larugi nasi kudo Wara''o, awö gureta, awö zi fakudo, ba ifuli fahalö yaŵara hou nasi ibe''e Yehowa; ba Iraono Gizeraeli, ba no latörö nasi, ba zi no otufo."', '["SamII 22:2;. Sin 18:3; Yes 12:2; Fam 15:3","Neh 9:11","Sin 72:18","Yos 2:9","Sin 93:1"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 20, 'Ba ituyu waritia Miriya sama''ele''ö andrö, ira alawe, talifusö Ga''aroni, ba la''o''ö ia ira alawe fefu, la''ohe waritia ba manari ira.[6]', '["Sin 68:26"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 21, 'Ba manunö Miriya, imane:', '["Sin 68:26"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 22, 'Ba ifofanö Ndraono Gizeraeli Moze, la''oroi nasi zukhu, ba lasaŵa danö si mate Suri; tölu ngaluo ba tölu mbongi latörö danö si mate, ba lö lasöndra nidanö.', '["MozIV 33:8; RazII 2:19"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 23, 'Awena larugi Mara; ba tebai labadu nidanö andrö, börö wa''afetonia. Safeto sa ia, andrö wa labe''e töi naha andrö Mara (Safeto).[7]', '["MozIV 33:8; RazII 2:19"]', NULL),
  (3444228, 'OT', 'Moze II', 15, 24, 'Ba kumökö-kökö zato khö Moze, lamane: Ha mabadu idanö?', '[]', NULL),
  (3444228, 'OT', 'Moze II', 15, 25, 'Ba i''angaröfi li Yehowa, ba i''oroma''ö khönia geu Yehowa, da''ö itibo''ö ba nidanö andrö, ba ami sa''ae nidanö. Ba da''ö ibe''e khöra gamakhoita ba huku ba ba da''ö itandraigö ira,', '[]', NULL),
  (3444228, 'OT', 'Moze II', 15, 26, 'imane:', '[]', NULL),
  (3444228, 'OT', 'Moze II', 15, 27, 'Ba larugi Gelima, ba felendrua lasöndra ba da''ö umbu nidanö ba fitu ngafulu nga''eu döla nohi; ba molombase ira ba da''ö ba zinga nidanö.[9]', '["MozIV 33:9"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 1, 'Ba laheta ira ba Gelima ba larugi danö si mate Sini, Iraono Gizeraeli fefu, tanö si mate ba gotaluara Gelima andrö Zina''i, ba duli ba mbaŵa si dua, i''otarai aheta ira ba danö Miserayi.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 2, 'Ba kumökö-kökö Ndraono Gizeraeli fefu khö ndra Moze A''aroni ba danö si mate andrö.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 3, 'Lamane khöra Iraono Gizeraeli: Ena''ö na mate mege ndra''aga ba danga Yehowa, ba danö Miserayi, me dumadaoga ba ngai mbowoa ndriwo khöma ba me abusoga kue; ba no mi''ohega ba danö si mate andre, ba wame''e mate olofo Ndraono Gizeraeli fefu.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 4, 'Ba imane Yehowa khö Moze: Lau! Da''ube''e atoru moroi ba mbanua si yaŵa kue, amaedola daŵa deu, ba akha möi ira, akha la''erogö ma''ökhö wangozaragö soguna khöra ma''ökhö. Ba da''ö dania utandraigö ira, na edöna la''o''ö nifakhoigu, ba na lö''ö.[1]', '["Neh 9:15; Sin 78:24; Yoh 6:31; KorI 10:3"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 5, 'Ba na la''asiwai nihalöra ba luo wangöhöna, ba no mendrua fa''oya ni''ozaragöra na luo bö''ö.', '["Neh 9:15; Sin 78:24; Yoh 6:31; KorI 10:3"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 6, 'Ba lamane ba Ndraono Gizeraeli fefu ira Moze A''aroni: Owi dania, ba aboto ba dödömi, wa no Yehowa zangeheta ya''ami ba danö Miserayi;', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 7, 'ba mahemolu mbanua, ba oroma khömi lakhömi Yehowa; noa sa irongo wekökö-kökömi khö Yehowa; ba hadia ndra''aga, wa khöma kumökö-kökö ami?', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 8, 'Ba imane na Moze: Me ibe''e dania khömi Yehowa, owi dania, ba ömi diwo, ba mahemolu mbanua, ba sabönö kue, ba me no irongo wekökö-kökömi khöma Yehowa — hadia sa ndra''aga andre? Tenga khöma mukökö-kökö ami, tobali sa khö Yehowa!', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 9, 'Ba imane Moze khö Ga''aroni: Ömane ba Ndraono Gizeraeli fefu: Mi''ondrasi Yehowa: noa sa irongo wekökö-kökömi andrö.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 10, 'Ba me no iŵa''ö da''ö ba Ndraono Gizeraeli fefu A''aroni, ba la''otahögö danö si mate wamaigi; ba i''ozumagö oroma lakhömi Yehowa ba lawuo andrö.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 11, 'Ba imane Yehowa khö Mose:', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 12, 'No urongo wekökö-kökö Ndraono Gizeraeli; ömane khöra: Owi dania, ba so gömi diwo, ba mahemolu mbanua, ba abuso ami kue, ba ya''aboto ba dödömi, wa no ya''o Yehowa, Lowalangimi.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 13, 'Ba me arakha bongi, ba so moroi si tou zi ate, lahawui golombaseŵa.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 14, 'Ba mahemolu mbanua, ba aekhu namo ba zi tefasui olombaseŵa. Ba me taya namo andrö, ba hiza tou ba danö si mate zi no ide-ide, mongawua, fa''ebua damböni, ba danö tou.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 15, 'Ba me la''ila Iraono Gizeraeli, ba faoma lamane khö nawöra: Hadia da''ö? lö''ö sa la''ila hadia. Ba imane khöra Moze: Da''ö kue andrö, buala Yehowa khömi, ömi.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 16, 'Da''ö ni''oroi''ö Yehowa: Mi''ozaragö ha wa''oya moguna, ö zamösana, sadumba zamösa; balazi ha dauga zi samba ose, ba wangaimi.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 17, 'Ba la''o''ö da''ö Iraono Gizeraeli, la''ozaragö; samösa, ba oya i''ozaragö ba samösa, ba ambö fa''oya.[2]', '["KorII 8:15"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 18, 'Ba me lasu''a ba dumba, ba lö si töra ba zi no oya mangai, ba lö''ö göi ambö ba zambö fa''oya ni''ozaragö, ha ndrohu-ndrohu zoguna, ö zamösana, ni''ozaragöra.', '["KorII 8:15"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 19, 'Ba imane khöra Moze: Samösa lö same''e yaŵa, irege mahemolu.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 20, 'Ba lö lafondrondrongo li Moze, so zame''e yaŵa ösa, irege mahemolu ö. Ba mokukuö ba obou. Ba mofönu khöra Moze.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 21, 'Ba ero mahemolu mbanua la''ozaragö, ndrohu-ndrohu zoguna ö zamösana. Ba na aukhu zino, ba maniö.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 22, 'Ba me luo wangöhöna, ba no mendrua wa''oya ni''ozaragöra, öra, no dua dumba zamösa.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 23, 'Ba imane khöra: Ya''ia niŵa''ö Yehowa: Mahemolu luo wolombase, sabato, ni''amoni''ö khö Yehowa. Hadia zomasi ami misala, ba misala, ba hadia nirino, ba mirino; hadia zi tosai, ba mibe''e yaŵa, ba wanenagö ya''ia, ö mahemolu.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 24, 'Ba labe''e yaŵa irege mahemolu, dali niŵa''ö Moze, ba lö obou ba lö''ö göi kukuö bakha.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 25, 'Ba imane Moze: Ömi ma''ökhö; Sabato khö Yehowa sa ma''ökhö; lö misöndra hadia ia ba danö ma''ökhö.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 26, 'Önö ngaluo mi''ozaragö ia, ba ba luo si fitu, ba zabato, ba lö ya''ia.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 27, 'Ba so zi möi baero, me luo sabato, ba wangozaragö, ba lö hadia ia lasöndra.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 28, 'Ba imane Yehowa khö Moze: Ha wa''ara tö na tekhömi mi''o''ö goroisagu ba amakhoitagu?', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 29, 'Hiza, Yehowa zame''e khömi Sabato andrö, dua ngaluo balazo ibe''e khömi, na luo wangöhöna; mihonogö ami yomo; samösa böi yamöi tou, na luo Sabato.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 30, 'Ba la''amoni''ö luo Sabato.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 31, 'Ba "mana" labe''e töinia Iraono Gizeraeli: No afusi, hulö lada safusi, ba fa''aminia, ba hulö kue nilau ŵe ŵani.[3]', '["MozIV 11:7"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 32, 'Ba imane Moze: Da''ö niŵa''ö Yehowa: Sadumba la''irö''ö ba nga''önga''ötö mitou, ena''ö la''ila gö andrö, nibe''egu balazomi ba danö si mate, me uheta ami ba danö Miserayi.[4]', '["Heb 9:4"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 33, 'Ba imane Moze khö Ga''aroni: Halö migö, sadumba be''e bakha "mana", ba be''e yaŵa föna Yehowa, ena''ö te''irö''ö, götö-götö wa''ara.', '["Heb 9:4"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 34, 'Ba i''o''ö da''ö A''aroni, dali niŵa''ö Yehowa khö Moze; ibe''e föna zura goroisa A''aroni, ba wangirö''ö ya''ia.', '[]', NULL),
  (3444445, 'OT', 'Moze II', 16, 35, 'Ba öfa wulu fakhe wa''ara la''aga-aga "mana" Iraono Gizeraeli, irege larugi danö si so niha; "mana" göra, irege lakhamö nola danö Gana''ana.[5]', '["Yos 5:12"]', NULL),
  (3444445, 'OT', 'Moze II', 16, 36, 'Ba si sadumba, ba sambua ni''ofulu zi samba Efa [khöra].', '["Yos 5:12"]', NULL),
  (3444528, 'OT', 'Moze II', 17, 1, 'Ba laheta ira ba danö si mate Sini Iraono Gizeraeli fefu; latari tebato, la''o''ö niŵa''ö Yehowa, ba molombase ba Rafidi. Ba lö idanö ö zato.[1]', '["MozIV 33:14"]', NULL),
  (3444528, 'OT', 'Moze II', 17, 2, 'Ba lafasosoni Moze, lamane: Mibe''e göma idanö!', '["MozIV 33:14"]', NULL),
  (3444528, 'OT', 'Moze II', 17, 3, 'Ba sowökhi tödö ira ba da''ö, andrö mukökö-kökö ira khö Moze, wanguma''ö: Hana wa no öheta ndra''aga ba danö Miserayi? hadia, ba wame''e mate owökhi dödö ndra''aga, awö ndraonoma, awö guriföma?[2]', '["MozIV 20:4"]', NULL),
  (3444528, 'OT', 'Moze II', 17, 4, 'Ba i''angaröfi li Yehowa Moze, imane: He uwisa ba niha andrö! hatö ma''ifu tö, ba latebu kara ndra''odo!', '[]', NULL),
  (3444528, 'OT', 'Moze II', 17, 5, 'Ba imane Yehowa khö Moze: Owaö-waö föna zato, ba ohe awöu zatua Ndraono Gizeraeli ösa; ba si''o andrö, famözi Nilo no khöu, ba ohe tangau ba owaö-waö![3]', '["Faigi 7:20"]', NULL),
  (3444528, 'OT', 'Moze II', 17, 6, 'Hiza, sodo dania ba da''ö fönau, ba dete gara, ba gahe hili Horebi. Ba öbözi dania gara andrö, ba mangumbu nidanö salua khönia, öra.', '["Faigi 7:20"]', NULL),
  (3444528, 'OT', 'Moze II', 17, 7, 'Ba ibe''e töi naha andrö Masa ba Meriba, me no fasoso Ndraono Gizeraeli ba me no latandraigö Yehowa, wanofu: Hadia, so ba khöda Yehowa, ma lö''ö?', '[]', NULL),
  (3444528, 'OT', 'Moze II', 17, 8, 'Ba so moroi sa Ndraono Gamaleki, möi fasuwö ba Ndraono Gizeraeli, ba Rafidi.[5]', '["MozV 25:17"]', NULL),
  (3444528, 'OT', 'Moze II', 17, 9, 'Ba imane Moze khö Yosua: Tutuyu khöda zabölö, ba mahemolu, ba ae fasuwö ba Ndraono Gamaleki andrö. Ba ya''odo, ba ba zuzu hili sodo, ba so ba dangagu si''o andrö khö Lowalangi.', '[]', NULL),
  (3444528, 'OT', 'Moze II', 17, 10, 'Ba i''o''ö Yosua niŵa''ö Moze khönia, ba wasuwöta ba Ndraono Gamaleki; ba möi ba zuzu hili ndra Moze, A''aroni, Huri.', '[]', NULL),
  (3444528, 'OT', 'Moze II', 17, 11, 'Ba fatua ifazaŵa dangania Moze, ba abölö Ndraono Gizeraeli, ba na idada dangania, ba Iraono Gamaleki zabölö.', '[]', NULL),
  (3444528, 'OT', 'Moze II', 17, 12, 'Ba me atage danga Moze, ba lahalö gara ba labe''e dadaomania. Ba latuwu da''ionia A''aroni ba Huri, samösa dambai, ba abe''e da''ionia, irege aekhu luo.', '[]', NULL),
  (3444528, 'OT', 'Moze II', 17, 13, 'Ba tobali ilaŵa Ndraono Gamaleki ba sabölö andrö khöra Yosua bawa zi''öli.', '[]', NULL),
  (3444528, 'OT', 'Moze II', 17, 14, 'Ba imane Yehowa khö Moze: Tanö ba zura da''ö, fa böi olifu, ba abe''e''ö wanguma''ö khö Yosua, ömane: uhori ba danö Ndraono Gamaleki, irege taya döira ube''e.[6]', '["MozIV 24:20; MozV 25:19; SamI 15:2,3"]', NULL),
  (3444528, 'OT', 'Moze II', 17, 15, 'Ba ifa''anö naha wame''e sumange Moze, ba ibe''e töinia "Yehowa mandreragu",', '[]', NULL),
  (3444528, 'OT', 'Moze II', 17, 16, 'imane sa: "Nituyu mandrera andrö khö Yehowa; fasuwöta ba Ndraono Gamaleki khö Yehowa, irugi zi lö aetu!"', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 1, 'Ba me irongo Yetero, högö gere ba Ndraono Midiano, matua Moze, duria da''ö fefu, he wisa Lowalangi khö Moze ba ba mbanuania Iraono Gizeraeli, wa no iheta ba danö Miserayi Ndraono Gizeraeli Yehowa,', '["Faigi 2:21; 4:20","Faigi 2:22"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 2, 'ba ihalö Zifora andrö, fo''omo Moze Yetero, matua Moze — noa sa ifa''ohe''ö mangawuli Moze[1] —', '["Faigi 2:21; 4:20","Faigi 2:22"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3445211, 'OT', 'Moze II', 18, 3, 'awö nononia andrö, si dombua — töi zi sambua, ba Gereso, me no imane: No tobali si fatewu ndra''o ba danö zotanö;[2]', '["Faigi 2:21; 4:20","Faigi 2:22"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 4, 'ba töi zi samösa, ba Eliezeri, me imane: No itolodo Lowalangi namagu andrö, no i''efa''ö ndra''o ba mbawa zi''öli Wara''o. —', '["Faigi 2:21; 4:20","Faigi 2:22"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 5, 'Ba so Yetero, matua Moze, awö ndraono Moze, awö wo''omonia, möi ia khö Moze ba danö si mate, ba zolombase ira, ba gahe hili Lowalangi andrö.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 6, 'Ba ifaŵa''ögö khö Moze imane: Möido khöu, ya''odo andre, matuau Yetero, awö wo''omou ba ononia si dombua andrö, si fao khönia.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 7, 'Ba maoso Moze, möi mufaondragö matuania andrö, ifaöndrö ia ba fa''ago bawa khönia; ba faoma lasofu khö nawöra, na lö hadia ia khöra, ba möi baose.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 8, 'Ba idunö-dunö khö matuania Moze fefu milau Yehowa khö Wara''o ba ba Ndrawa Miserayi, ba wangorifi Iraono Gizeraeli, awö wamakao andrö fefu, si no göna ira ba lala ba fangorifi Yehowa ya''ira.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 9, 'Ba omuso dödö Yetero ba zi sökhi andrö fefu, nilau Yehowa ba Ndraono Gizeraeli, wa no i''efa''ö ira ba danga Ndrawa Miserayi.', '["Faigi 1:22; 14:27; Sin 76:11"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 10, 'Ba imane Yetero: Nisuno Yehowa, me no i''efa''ö ami ba danga Wara''o ba ba danga Ndrawa Miserayi, me no iheta barö mbawa Ndrawa Miserayi mbanuami.', '["Faigi 1:22; 14:27; Sin 76:11"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 11, 'Awena aboto ba dödögu, wa no sabölö moroi ba Lowalangi bö''ö fefu Yehowa; ba zi fayaŵa ira khöra sa''ae ilaŵa ira.[3]', '["Faigi 1:22; 14:27; Sin 76:11"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 12, 'Aefa da''ö, ba ifahalö''ö gurifö Yetero andrö, matua Moze, nibe''e sumange nitunu ba sumange nitaba, sumange Lowalangi, ba so Ga''aroni, awö zatua Ndraono Gizeraeli fefu, ba wangorudugö ya''ira khö matua Moze andrö, ba wemanga zumange andrö föna Lowalangi.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 13, 'Ba mahemolu ö, ba mudadao Moze, ba wamatunö huhuo zato, ba la''ondrasi Moze niha, i''otarai sihulö wongi, numalö ba wa''abongi.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 14, 'Ba me i''ila matua Moze halöŵönia ba niha, ba imane khönia: He wisa ndra''ugö ba niha andrö? Hana wa ha ya''ugö zidao-dao, ba lahurufai manö ndra''ugö niha, i''otarai zi hulö wongi numalö ba wa''abongi?', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 15, 'Imane Moze khö matuania: Ya''ia, möi-möi khögu niha, ba wanofu faetasa.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 16, 'Na so huhuora, ba la''ondrasi ndra''o, ena''ö u''etu''ö, ha khö zatulö, ba ena''ö u''ombakha''ö nifakhoi Lowalangi ba oroisania.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 17, 'Ba imane matua Moze khönia: Tenga si göna wolaumö andrö.', '["MozIV 11:16; MozV 1:13"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 18, 'Erege dödöu ba erege göi dödö niha andrö, si so khöu; abölö afökhö halöŵöu andrö khöu, tebai ha ya''ugö zangasiwai.', '["MozIV 11:16; MozV 1:13"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 19, 'Ba da''ufobawa lala khöu, o''ö khögu, ba itolo''ö Lowalangi: böi bulö''ögö sama''ema khö Lowalangi hadia ia niŵa''ö-ŵa''ö niha, fa''ema khö Lowalangi huhuora.', '["MozIV 11:16; MozV 1:13"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 20, 'Ba botokhi ba dödöra gamakhoita ba oroisa, ba oroma''ö khöra lala nitöröra ba he lawisa wolau.', '["MozIV 11:16; MozV 1:13"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 21, 'Ba tutuyu ba niha sato zangata''ufi Lowalangi ba si faduhu dödöda ba si lö mangalui khöra hadia ia, ba fataro ira sanguhuku si hönö-hönö ba si otu-otu ba si lima-lima wulu ba si fulu-fulu,[4]', '["MozIV 11:16; MozV 1:13"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 22, 'fa lö mamalö-malö lafatunö huhuo zato. Ba huhuo sebua, fefu ba ndramu''ohe khöu; ba huhuo side-ide fefu, ba ya''ira zangetu''ö, ba aoha khöu öbe''e, ba latolo''ö.', '["MozIV 11:16; MozV 1:13"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 23, 'Na ömanö wangohonogöi da''ö, ba na iŵa''ö khöu Lowalangi, ba tola ötaha, ba si sökhi tödö niha andrö fefu, wangawuli ba khöra.', '["MozIV 11:16; MozV 1:13"]', NULL),
  (3445211, 'OT', 'Moze II', 18, 24, 'Ba i''o''ö niŵa''ö matuania Moze, fefu nifobawania lala khönia, ba ifalua.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 25, 'Itutuyu Moze ba Ndraono Gizeraeli fefu niha si so tödö ba ifataro högö zato, sanguhuku si hönö-hönö ba si otu''utu ba si lima-lima wulu ba si fulu-fulu,', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 26, 'ena''ö lö mamalö-malö la''asiwai huhuo zato. Ba huhuo sebua, ba ni''ohe khö Moze, ba fefu huhuo side-ide, ba ya''ira zangetu''ö.', '[]', NULL),
  (3445211, 'OT', 'Moze II', 18, 27, 'Ba ifasao ba lala matuania Moze, mangawuli ba khöra da''ö.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 1, 'Tölu waŵa aefa ira ba danö Miserayi; me luo da''ö sibai, ba larugi danö si mate Sina''i.[1]', '["MozIV 33:15"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 2, 'No laheta ira ba Rafidi, ba larugi danö si mate Sina''i; ba molombase ira ba danö si mate. Ba gamaudu hili andrö labe''e golombaseŵa Iraono Gizeraeli.', '["MozIV 33:15"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 3, 'Ba me no möi miyaŵa Moze khö Lowalangi, ba humede khönia Yehowa moroi ba hili yaŵa, imane: Da''ö niŵa''öu ba ma''uwu Yakobo, da''ö ni''ombakha''öu ba Ndraono Gizeraeli:[2]', '["HalZin 7:38"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 4, 'No mi''ila nilaugu ba Ndrawa Miserayi; wa no u''ohe ami, amaedola ba dete gafi moyo, wa ba da''e urugi wolohe ya''ami, khögu.[3]', '["MozV 29:2; 32:11","MozV 5:2; Sin 24:1; 50:12; KorI 10:26","MozV 7:6; FetI 2:9"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 5, 'Ba na edöna sa''ae ami mifondrondrongo ligu, ba na lö olifu ami gamakhoitagu andrö ba tana khögu ami, moroi ba niha bö''ö fefu; me no khögu guli danö ma''asagörö.[4]', '["MozV 29:2; 32:11","MozV 5:2; Sin 24:1; 50:12; KorI 10:26","MozV 7:6; FetI 2:9"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 6, 'Ba öri ere ami khögu, soi ni''amoni''ö! Da''ö niŵa''öu ba Ndraono Gizeraeli.[5]', '["MozV 29:2; 32:11","MozV 5:2; Sin 24:1; 50:12; KorI 10:26","MozV 7:6; FetI 2:9"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 7, 'Ba möi Moze, ifalukha''ö zatuara ba ifa''ema khöra daroma li andrö, niŵa''ö Yehowa khönia, fefu.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 8, 'Ba dozi manö ira, ba ha sara li, lamane: Fefu hadia ia niŵa''ö Yehowa, ba ma''o''ö!', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 9, 'Ba imane Yehowa khö Moze: Hiza, möido khöu bakha ba lawuo sawe''e-we''e, ena''ö larongo sato, na fahuhuodo khöu, ba ena''ö si lö aetu wamatira khöu.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 10, 'Ba imane Yehowa khö Moze: Ae khöra ba ŵa''ö khöra, ena''ö mamoni ira ma''ökhö ba mahemolu, ba ndramubabago nukhara.', '["Faigi 24:9; Heb 12:20"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 11, 'Ba ba zi dua wongi, ba no mama''anö ira; ba zi dua wongi sa möi tou ba hili Zina''i Yehowa, ba zanehe zato fefu.', '["Faigi 24:9; Heb 12:20"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 12, 'Ba ba zato, ba ötaru''ö göli, fasui, wanguma''ö khöra: Mi''angelama, fa böi möi miyaŵa ami ba hili, böi na''i mihatö''ö ami ba gahenia; gofu ha niha zi hatö''ö ya''ia ba hili, ba si mate!', '["Faigi 24:9; Heb 12:20"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 13, 'Lö tola ibabaya hili tanga niha; nitebu kara na so zi manö ba ma nifana, he niha, ba he urifö, lö tola lö mate. Ba na terongo li dorofe, ba möi miyaŵa ira ba hili.[6]', '["Faigi 24:9; Heb 12:20"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 14, 'Ba möi mitou Moze moroi ba hili, möi ia ba zato ba iwa''ö khöra, mamoni ira ba lababago nukhara.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 15, 'Ba imane na khöra: Mifa''anö ami, irege ba zi dua wongi; samösa lö tola orudu ba ndra alawe.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 16, 'Ba dua wongi aefa da''ö, me moluo, ba ilabu banua, awö gari mbanua, no ibalugö hili lawuo saitö ba terongo li dorofe sabölö-bölö; ba ihawui fa''ata''u zato, si so ba golombaseŵa.', '["MozV 4:11"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 17, 'Ba i''ohe baero golombaseŵa zato Moze, ba wamaondragö Lowalangi, ba la''iagö gahe hili.[7]', '["MozV 4:11"]', NULL),
  (3446395, 'OT', 'Moze II', 19, 18, 'Ba no anönö simbo hili Zina''i, me no möi tou ba zuzunia Yehowa ba galitö; ba numalö miyaŵa zimbo, moroi khönia, hulö zimbo galitö mbaho, ba moduru sibai hili andrö ma''asambua.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 19, 'Ba itugu ara, ba itugu abölö li dorofe andrö: humede Moze ba itema linia Lowalangi, ebua linia.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 20, 'Möi mitou ba hili Zina''i Yehowa, ba zuzu hili. Ba ikaoni ba zuzu hili Moze Yehowa; ba möi miyaŵa Moze.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 21, 'Ba imane Yehowa khö Moze: Ae mitou ba abe''e''ö wanguma''ö ba zato, böi ndramuhatö''ö ira khö Yehowa, ba wamaigi ya''ia; fa böi ato zi mate khöra.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 22, 'He ere andrö göi, sangahangahatö ya''ira khö Yehowa, ba la''amoni''ö göi ira; fa böi ilau khöra Yehowa.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 23, 'Ba imane Moze khö Yehowa: Tebai möi miyaŵa ba hili Zina''i zato; noa sa ya''ugö zangabe''e''ö fanguma''ö khöma, ba wangöli hili ba no öŵa''ö: tebai mirugi.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 24, 'Ba imane khönia Yehowa: Ae manö mitou ba ohe awöu Ga''aroni, wangawuli miyaŵa. Ba böi ndra muhatö''ö ira ere andrö, awö zato, ba we''amöi miyaŵa khö Yehowa, ena''ö böi ilau khöra.', '[]', NULL),
  (3446395, 'OT', 'Moze II', 19, 25, 'Ba möi mitou ba zato Moze ba iŵa''ö khöra.', '[]', NULL),
  (3446583, 'OT', 'Moze II', 20, 1, 'Ba iŵa''ö daroma li andrö fefu Yehowa, imane:', '[]', NULL),
  (3446583, 'OT', 'Moze II', 20, 2, 'Ya''odo Yehowa Lowalangiu, si no mangeheta ya''ugö ba danö Miserayi andrö, ba zi no möi sawuyu ami.[1]', '["MozV 5:6–21; Sin 81:11; Hos 13:4"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 3, 'Böi so khömö Lowalangi tanö bö''ö, baero ndra''o.[2]', '["Yos 24:14"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 4, 'Böi fazökhi khöu nadu, ba he famaedo hadia ia, he si so si yaŵa ba mbanua, ba he si so si tou ba guli danö, ba he si so ba nidanö, barö danö.[3]', '["Sin 97:7; Yes 40:18"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 5, 'Böi angalulu khönia ba böi fosumange ia, me no Lowalangi solohu ndra''o, ya''odo andre, Yehowa, Lowalangiu, sanguhuku horö ndra ama ba ndraono ba ba ma''uwu mitou, khöra si fatiu tödö khögu,', '[]', NULL),
  (3446583, 'OT', 'Moze II', 20, 6, 'ba si hakhösi tödö sangomasi''ö ya''o ba solo''ö oroisagu; irugi hönö nga''ötö.', '[]', NULL),
  (3446583, 'OT', 'Moze II', 20, 7, 'Böi tötöi döi Lowalangiu Yehowa ba waya; lö''ö sa zi lö ihuku Yehowa zanötöi töinia ba waya.[4]', '["MozIII 19:12"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 8, 'Ame''egö tödö luo wolombase andrö, ba we''amoni''ö ya''ia.[5]', '["Faigi 31:13; 35:2","MozI 2:2"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 9, 'Önö ngaluo mohalöŵö ndra''ugö ba öhalö halöŵöu fefu.', '["Faigi 31:13; 35:2","MozI 2:2"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 10, 'Ba ero fitu bongi, ba luo wolombase khö Lowalangiu Yehowa; böi babaya hadia ia halöŵö ba da''ö, he ya''ugö, ba he onou matua, ba he onou alawe, ba he sangai halöŵö khöu ira matua ba he sangai halöŵö khöu ira alawe, ba he uriföu, ba he si fatewu khöu ba mbanuami bakha.', '["Faigi 31:13; 35:2","MozI 2:2"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 11, 'Önö ngaluo sa mege khö Yehowa, ba wamazökhi banua si yaŵa, awö danö, awö nasi, awö nösira fefu; ba ba luo si fitu, ba no molombase ia. Andrö wa no ifahawu''ö luo si fitu andrö Yehowa, ba no i''amoni''ö.[6]', '["Faigi 31:13; 35:2","MozI 2:2"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 12, 'Fosumange namau, awö ninau, ena''ö anau nosou ba danö, nibe''e Lowalangiu Yehowa khöu.[7]', '["MozIII 19:3; Mat 15:4; Efes 6:2"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 13, 'Böi ange''e.[8]', '["MozI 9:6; Mat 5:21"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 14, 'Böi ohorö.[9]', '["MozIII 20:10; Mat 5:27; Heb 13:4"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 15, 'Böi anagö.[10]', '["Efes 4:28"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 16, 'Böi böbögö khö nawöu zi lö duhu.[11]', '["MozV 19:18"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 17, 'Böi isö nomo nawöu. Böi isö wo''omo nawöu ba he sangai halöŵö khönia ira matua, ba he sangai halöŵö khönia ira alawe, ba he öröbaonia, ba he kudonia, ba he hadia ia, fefu, nibaya-baya nawöu.[12]', '["Rom 7:7"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 18, 'Ba me larongo sato fefu we''ugu-ugu mbanua andrö ba me la''ila gari mbanua andrö, ba me larongo li dorofe ba me la''ila wanimbo hili, ba ata''u ira ba manizi-nizi ba ba zaröu la''iagö.', '["MozIV 18:16; Heb 12:19"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 19, 'Ba lamane khö Moze: Sökhi na ya''ugö zihede khöma, ba samondrongo ndra''aga. Sökhi na tenga Lowalangi zihede khöma, fa böi mate ndra''aga.[13]', '["MozIV 18:16; Heb 12:19"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 20, 'Ba imane Moze ba zato: Böi mi''ata''ufi; ba wanandraigö ya''ami sa so Lowalangi, ba ena''ö mi''ata''ufi ia, fa böi mifazökhi horö.[14]', '["MozV 5:28"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 21, 'Ba ba zaröu la''iagö sato, ba möi ba lawuo saitö andrö bakha Moze, ba zi so Lowalangi bakha.', '[]', NULL),
  (3446583, 'OT', 'Moze II', 20, 22, 'Ba imane Yehowa khö Moze: Da''ö niŵa''öu ba Ndraono Gizeraeli:', '[]', NULL),
  (3446583, 'OT', 'Moze II', 20, 23, 'Böi mifazökhi khömi nadu firö baerogu, ba he adu ana''a, ba böi mifazökhi khömi.', '[]', NULL),
  (3446583, 'OT', 'Moze II', 20, 24, 'Naha wame''e sumange öfa''anö khögu, tanö, ba ba dete da''ö öbe''e zumange nitunu andrö khöu ba sumange fangorifi, biri-biri ba saŵi andrö khöu; ba nahia andrö fefu, nihonogöigu ba da''ö, ba wamosumange ya''odo ba da''ö, möido khöu, ba ufahowu''ö ndra''ugö.', '[]', NULL),
  (3446583, 'OT', 'Moze II', 20, 25, 'Ba na öfa''anö khögu naha wame''e sumange, kara, ba lö tola öfake gara nitoto, wama''anö ya''ia; na ölau khönia wakake si''öli, ba salakha öfatörö khönia.[15]', '["MozV 27:5"]', NULL),
  (3446583, 'OT', 'Moze II', 20, 26, 'Ba lö tola göi ora ötörö, we''amöi yaŵa ba naha wame''e sumange andrö khögu, fa böi tehoi fönania mbalu-balu zaila ndra''ugö.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 1, 'Da''ö gamakhoita andrö, nifa''emau khöra:', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 2, 'Na öhöli zawuyu, niha Heberaio, ba meönö fakhe mohalöŵö ia [khöu], sawuyu, ba ba ndröfi si fitu, ba ni''efa''ö ia, saoha gölö.[1]', '["MozIII 25:39; MozV 15:12; Yer 34:14"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 3, 'Na ha samösa ia, me awena so ia, ba ha samösa göi ia ba wangefa''ö ya''ia; ba na no so ndrongania, ba ni''efa''ö göi da''ö, awönia.', '["MozIII 25:39; MozV 15:12; Yer 34:14"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 4, 'Ba na sokhö ya''ia zamodonga ya''ia mege, ba na no mo''ono khönia, ono matua, ba ma ono alawe, ba khö zokhö ya''ia ndrongania, fabaya iraono andrö, ba ha ya''ia ni''efa''ö.', '["MozV 19:17; Sin 82:6; Yoh 10:34"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 5, 'Ba na iŵa''ö ena''ö sawuyu andrö: Omasido zokhö ya''o ba fo''omogu ba iraonogu, ba alakha lö aefado,', '["MozV 19:17; Sin 82:6; Yoh 10:34"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 6, 'ba yamu''ohe ia föna Lowalangi sokhö ya''ia, ba yamufaedogö ia ba lagö mbawandruhö, ba ma ba gehomo mbawandruhö, ba yamutögi dalingania förögi sokhö ya''ia, ba ya lö tebulö sawuyunia.[2]', '["MozV 19:17; Sin 82:6; Yoh 10:34"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 7, 'Na so zamawa sawuyu ononia alawe, ba tebai ni''efa''ö da''ö, si mane sawuyu bö''ö.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 8, 'Na lö omasi zokhö ya''ia, samohu ya''ia ia, ba yamufahöli''ö, ba lö tola i''amawa ba niha bö''ö, si tenga ya''ira, na lö aro linia ehönia.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 9, 'Ba na khö nononia ihonogöi, ba ya hulö nononia alawe.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 10, 'Ba na ihalö zambua tö, ba böi yamu''ambösi ia; he ba gönia, ba he ba nukhania, ba he ba wa''orudu khönia.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 11, 'Na lö itörö zi tölu balö andrö, ba ya aefa ndra alawe andrö, saoha gölö.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 12, 'Na so zamöbözi awönia, irege mate, ba huku famunu hukunia.[3]', '["Faigi 20:13","MozIV 35:11; MozV 19:2; Yos 20:2"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 13, 'Ba na tenga ni''odödögö, na Lowalangi zamatörö tangania, ba uhonogöi khöu naha, nisaŵania woloi.[4]', '["Faigi 20:13","MozIV 35:11; MozV 19:2; Yos 20:2"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 14, 'Ba na so zolau horö khö nawönia, na ibunu, nilimo, ba ba zinga naha wame''e sumange khögu öhalö ia, ba wamunu ya''ia.[5]', '["RazI 2:29"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 15, 'Samöbözi amania, ba ma inania, ba nibunu.[6]', '["MozIII 20:9"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 16, 'Sorabu Iraono Gizeraeli — he i''amawa sawuyu, ba he ba nomonia, lasöndra, ba nibunu.[7]', '["MozV 24:7"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 17, 'Sangelifi amania, ba ma inania, ba nibunu.[8]', '["MozV 27:16; Amaed 20:20; 30:17; Mat 15:4"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 18, 'Na so zi fagua-gua ba na ibözi nawönia si samösa, kara, ba ma tanga, irege ibe''e ba zalo, he lö mate ia,', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 19, 'ba ya aefa zolau da''ö, na ifuli abe''e nibözi andrö, na i''ila möi tou, mani''o; ha götö zi tebato ia yomo isalahini khönia, ba ifaigi dalu-dalu khönia.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 20, 'Na so zamözi sawuyunia ira matua, ba ma sawuyunia ira alawe, si''o, irege adölö mate, ba nihuku da''ö.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 21, 'Ba na auri na ua, mato ma''ökhö, ba ma mato dua wongi, ba tenga nihuku ia, me no khönia, böli gana''ania.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 22, 'Ba na so niha si fasöndra, ba na latimba ndra alawe sanabina, irege aekhu dabinania, ba na lö''ö na atö bö''önia, safökhö, ba nikhau zolau da''ö, ogauta niŵa''ö zodonga ira alawe andrö, ba ibe''e dali niŵa''ö zanguhuku.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 23, 'Ba na irugi zabölö-bölö, ba noso lahalö fangali noso,[9]', '["MozIII 24:19; Mat 5:38"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 24, 'ba hörö fangali hörö, ba boha fangali mboha, ba tanga fangali danga, ba ahe fangali gahe,', '["MozIII 24:19; Mat 5:38"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3447568, 'OT', 'Moze II', 21, 25, 'ba sakhozi fangali zakhozi, ba sokho ba doho fangali zokho ba doho, ba sokho ba mbalatu fangali zokho ba mbalatu.', '["MozIII 24:19; Mat 5:38"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 26, 'Na so zamözi hörö zawuyunia ira matua, ba ma hörö zawuyunia ira alawe, irege aboto, ba yamu''efa''ö ia, salahi hörö andrö.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 27, 'Ba na ateu nifö ibe''e, na ibözi zawuyunia ira matua, ba ma sawuyunia ira alawe, ba yamu''efa''ö zawuyu andrö, salahi nifö andrö.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 28, 'Na itandru ndra matua, ba ma ira alawe saŵi, balazi mate, ba nitebu kara zaŵi andrö, wamunu ya''ia; ba ya si lö horö zokhö saŵi.[10]', '["MozI 9:5"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 29, 'Ba na no ara si fatandru-tandru zaŵi andrö ba na no mufangelama zokhö, ba na lö''ö zui idaro-darogö, ba mitebu kara göi zaŵi andrö, na no ibunu ndra matua, ba ma ira alawe, ba huku famunu göi huku zokhö ya''ia.', '["MozI 9:5"]', NULL),
  (3447568, 'OT', 'Moze II', 21, 30, 'Ba na lafo''ömö ia höli, ba ibe''e höli noso, ha wa''ebua nibe''e ömönia.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 31, 'Ba na ono matua ba ma ono alawe nitandru, ba si manö zui huku nifatörö khönia.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 32, 'Ba na sawuyu ira matua, ba ma sawuyu ira alawe nitandru zaŵi, ba 30 rufia gömö zokhö saŵi andrö ba nitebu kara zaŵi.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 33, 'Na so zi lö manösöwui ba''a, ba ma sogao ba''a ba lö isösöwui, ba na aekhu si tou zaŵi,', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 34, 'ba ma kalide, ba yamusalahini ba zokhö, ana''a, sokhö ba''a andrö, ba amatela andrö, ba khö zokhö.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 35, 'Ba na itandru zaŵi niha bö''ö saŵi, irege mate, ba ni''amawa zaŵi sauri andrö ba nifaosa mböli; ba si mate, ba nifaosa göi.', '[]', NULL),
  (3447568, 'OT', 'Moze II', 21, 36, 'Ba na no la''ila manö niha, wa no tohöna si fatandru-tandru zaŵi andrö, ba na lö nidaro-darogö zokhö ya''ia, ba isalahini saŵi zaŵi andrö, ba ya khönia zi mate andrö.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 1, 'Na so zanagö saŵi, ba ma biri-biri, ba na itaba ba ma i''amawa, ba lima nga''eu saŵi ibe''e fangali zi sageu ba öfa nga''eu biri-biri fangali zi sageu, ogauta[1]', '["SamII 12:6. Amaed 6:31; Luk 19:8"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 2, 'Na tera''u zanagö ba wanöi yomo, ba na labunu, ba tenga nilau balö da''ö.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 3, 'Ba na ba zi no moluo zi manö ba nilau balö. Sanagö, ba isalahini zinagönia, ba na lö khönia, ba ni''amawa ia salahi nitagönia andrö.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 4, 'Na tesöndra auri ba khönia nitagönia, he saŵi, ba he kalide, ba he biri-biri, ba sage-sageu tö ifuli, ogauta.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 5, 'Na so zi dudu urifönia ba mbenuania, ba ma ba kabu nagu khönia, ba na lö i''öli, na la''a zinanö ba nowi bö''ö, ba isalahini bua zinanönia, balazi wa''abölö mbua; ba na ahori la''a zinanö ba nowi, ba fondrege zi sökhi mbua nowinia ba bua ba kabu nagu khönia ibe''e salahi.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 6, 'Na so galitö, na akhozi go''o ba na ira''i mbasitö ba na akhozi nowi, ba isalahini zakhozi andrö samobörö alitö mege.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 7, 'Na so zame''e ba nawönia ni''irö''ö, ana''a, ba ma aya, ba na tetagö ba nomo da''ö, ba ifabali mbölinia sanagö andrö, na tesöndra ia.', '["Faigi 21:6"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 8, 'Ba na lö musöndra zanagö, ba yamöi föna Lowalangi zokhö omo, yamöi ba hölu, wa lö nibabayania okhöta nawönia andrö.[2]', '["Faigi 21:6"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 9, 'Na so hadia ia zi taya, he saŵi, ba he kalide, ba he biri-biri, ba he baru, ba he gofu hadia ia zi taya, ba na so zanguma''ö: da''ö ia! ba ni''ohe föna Lowalangi huhuora, ba niŵa''ö Lowalangi si so sala, ba ifabali wanalahini khö nawönia.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 10, 'Na so zame''e nikubaloi nawönia kalide, ba ma saŵi ba ma biri-biri, ba ma hadia ia gurifö, ba na mate da''ö, ba ma na göna hadia ia, ba ma na te''oloi''ö, si lö i''ila niha bö''ö,', '["MozI 31:39"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 11, 'ba fe''amöi ba hölu khö Yehowa wangetu''ö huhuo, ma no numalö dangania ba gokhöta nawönia andrö; ba na itehe da''ö sokhö, ba alakha lö i''alī.', '["MozI 31:39"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 12, 'Ba na no latagö khönia, ba i''alī khö zokhö.', '["MozI 31:39"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 13, 'Ba na no tesasawi [ba gutu ndru''u], ba na i''ila i''oroma''ö ngamohi, ba alakha lö i''ali nisasawi andrö.[3]', '["MozI 31:39"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 14, 'Na so zombalö urifö nawönia ba na göna hadia ia ba ma na mate, ba zi lö sokhö ya''ia, ba i''ali.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 15, 'Ba na ba zi so zokhö, ba alakha lö ibe''e wangali si samösa; na niwawalö ba no itema wombalö.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 16, 'Na so zamowöhö ono alawe, si lö mufohu na, na orudu ia khönia, ba ibe''e mböwö.[4]', '["MozV 22:28"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 17, 'Ba na ha sambalö lö itehe amania, ibe''e khönia, ba yamutulö wirö, ndrohu-ndrohu mböwö nono alawe.', '["MozV 22:28"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 18, 'Ira alawe si fakelemu, ba böi orifi.[5]', '["MozV 18:10"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 19, 'Dozi sorudu ba gurifö, ba nibunu.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 20, 'Na so zamozumange adu, ba tenga ha Yehowa, ba nihori[6]', '["MozV 17:3—5"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 21, 'Niha bö''ö, ba böi fakao ba böi falangögö; noa sa niha bö''ö göi ami ba danö Miserayi mege.[7]', '["MozIII 19, 34"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 22, 'Lakha mbanua ba si lö ama si lö ina ba böi manö mifakao.[8]', '["Yes 1:17"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 23, 'Na öfakao ia sa, ba na i''angaröfi li ndra''o, ba lö zi lö ufondrondrongo wangarö-ngarönia,', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 24, 'ba tesao dania wönugu ba ufabunu''ö ami si''öli, ba tobali lakha mbanua ngambatömi ba si lö ama ndraonomi.', '[]', NULL),
  (3447997, 'OT', 'Moze II', 22, 25, 'Na öbe''e nifalali gana''a ba mbanuagu si numana, si so ba ngaimö, ba böi sangebua hare ndra''ugö khönia; böi mifohare khönia.[9]', '["MozV 23:19; Sin 15:5; Hez 22:12"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 26, 'Na öhalö gade mbaru nawöu, ba irege aekhu luo, ba öfuli khönia.[10]', '["MozV 24:13"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 27, 'Awai sa gambala mbotonia, ha barunia andrö; hadia sa''ae ibe''e ambalania, na mö rö ia? Na i''angaröfi li ndra''o, ba ufondrondrongo khönia, me no sahakhö tödö ndra''odo.', '["MozV 24:13"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 28, 'Böi tandraŵaisi Lowalangi ba böi elifi zatua mbanuami.[11]', '["HalZin 23:5"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 29, 'Si no fahöna khöu ba si sökhi nösi mbua nagu khöu, ba böi zi lö ölulu. Si a''a nonou matua, ba öbe''e khögu.', '["MozIII 23:27"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 30, 'Ba si manö göi ba zaŵiu ba ba mbiri-biriu: fitu bongi yaso khö ninania, ba na aefa da''ö, ba ö''ohe khögu.[12]', '["MozIII 23:27"]', NULL),
  (3447997, 'OT', 'Moze II', 22, 31, 'Ya niha ni''amoni''ö ami khögu. Ba ösi nisasawi gutu ndru''u ba mbenua, ba lö tola mi''a, mibe''e ö nasu.[13]', '["MozIII 19:2; FetI 1:16"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 1, 'Böi böbögö zi lö duhu. Böi tolo zolau si lö atulö, we''amöi sasinia, ba wamuyu''ö huku.[1]', '["Faigi 20:16"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 2, 'Böi o''ö zato, ba wamazökhi si lö sökhi. Na so huhuo, ba böi o''awögö zato we''amöi sasi, ba wamuyu''ö huku.', '[]', NULL),
  (3448160, 'OT', 'Moze II', 23, 3, 'Böi o''awögö zalaŵa, na so huhuonia.[2]', '["MozIII 19:15"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 4, 'Na ösöndra zaŵi zi fa''udu khöu, ba ma kalidenia, sisuna, ba ö''ohe mangawuli khönia.[3]', '["MozV 22:1"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 5, 'Na ö''ila ilangö galide zi fa''udu khöu noronia, ba böi erogö ia, ötolo ia, ba wamu''a andrö.', '[]', NULL),
  (3448160, 'OT', 'Moze II', 23, 6, 'Böi fuyu''ö huku zi numana, banuami, na so huhuonia.', '[]', NULL),
  (3448160, 'OT', 'Moze II', 23, 7, 'Böi fabaya ndra''ugö ba huhuo, ba zi faruka faya ba böi fa''awö ndra''ugö ba wangetu''ö huku zi lö horö, ba si so huhuo satulö; lö''ö sa uŵa''ö si lö horö zi so horö.', '[]', NULL),
  (3448160, 'OT', 'Moze II', 23, 8, 'Ba böi a gana''a'' i''abösi''ö sa''ae zangila niha ana''a andrö ba ifuyu''ö huhuo satulö.[4]', '["MozV 16:19; 27:25"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 9, 'Niha bö''ö, ba böi fakao, noa sa mi''ila, he wisa dödö niha bö''ö, me no niha bö''ö mege ami, ba danö Miseraiyi.[5]', '["Faigi 22:21"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 11, 'ba ba ndröfi si fitu, ba böi oguna''ö ia, böi halö, ena''ö lahalö göra khönia si numana, banuami; ba hadia nisaigöra, ba hana na utu ndru''u zi manga; ba si manö göi wolaumö ba kabu nagu khöu ba ba kabu falo.', '["MozIII 25:3"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 12, 'Önö ngaluo wa''ara, ba hana na öhalö-halö halöŵöu, ba ba luo si fitu, ba molombase ndra''ugö, ena''ö molombase göi zaŵi ba kalide khöu, ba ena''ö lahasugö ira ono zawuyumö ira alawe, ba he niha bö''ö andrö [khöu].[7]', '["Faigi 20:9"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 13, 'Fefu hadia ia, niŵa''ögu khömi, ba böi olifu ami! Böi itörö limi döi Lowalangi bö''ö; böi itörö mbewemi![8]', '["Yos 23:7"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 14, 'Medölu zi döfi ölau khögu gowasa.[9]', '["Ayati 14–19: Faigi 34:18-26; MozV 16:1–17","Faigi 34:18; MozV 16:16"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 15, 'Owasa roti si lö mu''aisöni ölau: fitu, ngaluo wa''ara ö''a roti si lö mu''aisöni, si mane niŵa''ögu khöu, na baŵa Abibi, me no ba da''ö aheta''ö ba danö Miserayi. Böi möi khögu lö ba danga.[10] 16', '["Ayati 14–19: Faigi 34:18-26; MozV 16:1–17","Faigi 34:18; MozV 16:16"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 17, 'Medölu zi döfi la''ondrasi Zo''aya, Yehowa, dozi motöi matua.[11]', '["Faigi 34:23"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 18, 'Böi fabaya ba roti ni''aisöni ndro zumange andrö ni''oheu khögu, ba tawö zumangegu ba gowasa, ba böi tebe''e yaŵa irugi mahemolu.', '["Faigi 34:23"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 19, 'Fondrege zi sökhi, si a''a mbua nowi khöu, ba ö''ohe ba nahia Lowalangiu Yehowa. Ono mbiri-biri, ba böi rino ba nösi zusu ninania.', '["Faigi 34:23"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 20, 'Ba ufowaö-waö fönau mala''ika ba wondrorogö ya''ugö ba lala ba ba wolohe ya''ugö ba naha andrö, nihonogöigu;[12]', '["Faigi 33:2; Yes 6:14; Mal 3:9"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 21, 'Angelama ba khönia andrö ba o''ö niŵa''önia; böi sabe''e tandro ndra''ugö khönia; lö''ö sa ibe''e aefa khömi lalömi; fangoroma''ö ya''o sa''ae ia.', '["Faigi 33:2; Yes 6:14; Mal 3:9"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 22, 'Ba na öfondrondrongo linia ba na ö''o''ö fefu niŵa''ögu khöu, ba emali nemaliu ndra''odo ba si fa''udu ba zi fa''udu khöu.', '["Faigi 33:2; Yes 6:14; Mal 3:9"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 23, 'Mowaö-waö sa''ae dania fönau mala''ika andrö khögu, wolohe ya''ugö ba Ndraono Gamori ba ba Ndraono Kheti ba ba Ndraono Weresi ba ba Ndrawa Gana''ana ba ba Ndraono Hewi ba ba Ndraono Yebusi, ena''ö uhori ira.', '["MozIII 18:3"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 24, 'Böi angalulu ba Lowalangira ba böi fosumange, ba böi ohia''ö wolaura faulugö dudugö, ba rasa harefa andrö khöra.[13]', '["MozIII 18:3"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 25, 'Lowalangimi Yehowa mifosumange, ba ihöna dania khöu gaurifa, ba fökhö, ba itimba khöu.[14]', '["MozV 7:13"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 26, 'Ba lö dania salau talu ba lö si lö ono ba danö khöu, ba biha wa''anau nosou ube''e.', '["MozV 7:13"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 27, 'Ufowaö-waö fönau wameta''u andrö khögu ba ufawuka fefu niha, nirugiu dania, ba moloi dania fönau nemaliu fefu ube''e.[15]', '["MozV 11:25","MozV 7:20; Yos 24:12"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 28, 'Geto ufowaö-waö fönau, ena''ö moloi fönau Ndraono Hewi ba Dawa Gana''ana ba Iraono Kheti labe''e.[16]', '["MozV 11:25","MozV 7:20; Yos 24:12"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 29, 'Ba tenga ha döfi wa''ara utimba ira fönau, fa böi modu''u danö ba fa böi fahöna gutu ndru''u khöu.', '[]', NULL),
  (3448160, 'OT', 'Moze II', 23, 30, 'Uzara-zara wanimba ya''ira fönau, irege ato ami, ba wangokhögö tanö.', '[]', NULL),
  (3448160, 'OT', 'Moze II', 23, 31, 'Ba i''otarai nasi zukhu Kebe''e nolamö, irugi nasi ba Ndrawa Wilisiti, ba i''otarai danö si mate andrö ba irugi mboto nidanö (Oiferati) andrö. Ube''e sa''ae ba dangau niha ba danö, ba ötimba ira fönau.', '[]', NULL),
  (3448160, 'OT', 'Moze II', 23, 32, 'Böi fawu''u li ndra''ugö khöra, ba he ba Lowalangira andrö.[17]', '["Faigi 34:12","Sanguhuk 2:3"]', NULL),
  (3448160, 'OT', 'Moze II', 23, 33, 'Böi si lö tebulö ba danö ira, fa böi labe''e mamazökhi horö ndra''ugö khögu. Na öfosumange Lowalangira, ba tobali tandraŵa khöu.[18]', '["Faigi 34:12","Sanguhuk 2:3"]', NULL),
  (3448686, 'OT', 'Moze II', 24, 1, 'Ba imane khö Moze: Ae miyaŵa khö Yehowa, ya''ugö ba ira A''aroni, Nadabi, Elihu ba satua Ndraono Gizeraeli, fitu ngafulu, ba mi''angalulu khönia; ba zaröu so ami.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 2, 'Ba ha Moze zi hatö''ö ya''ia khö Yehowa; ya''ira andrö, ba lö tola lahatö''ö ira, ba sato, ba böi fao khönia, we''amöi miyaŵa.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 3, 'Ba möi Moze, i''ombakha''ö ba zato goroisa Yehowa andrö fefu ba amakhoitania fefu.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 4, 'Ba itanö ba zura goroisa Yehowa fefu Moze.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 5, 'Ba iŵa''ö ba nono matua Ndraono Gizeraeli labe''e zumange nitunu khö Yehowa ba lataba nono zaŵi, si matua, sumange fangorifi.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 6, 'Ba ihalö zi matonga ndro Moze, ilau ba wiga, ba si matonga, ba ibe''e fanefe naha wame''e sumange.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 7, 'Ba ihalö zura wawu''usa li andrö, ba ifarongogö ba zato wombaso.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 8, 'Ba ihalö ndro no mege Moze, itefe zato, imane: Do wawu''usa li andrö da''e, fawu''usa li nilau Yehowa khömi, dali goroisa andrö fefu.[1]', '["Mat 26:28; Heb 9:20"]', NULL),
  (3448686, 'OT', 'Moze II', 24, 9, 'Ba möi miyaŵa Moze ba ira A''aroni, Nadabi, Abihu ba satua Ndraono Gizeraeli, fitu ngafulu.[2]', '["Faigi 19:13"]', NULL),
  (3448686, 'OT', 'Moze II', 24, 10, 'Ba oroma khöra Lowalangi Ndraono Gizeraeli; barö gahenia, ba hulö mbatu nila nifa''anö, si mane banua si yaŵa wa''ohahau.[3]', '["Faigi 33:20; Yes 6:1; Hez 1:26"]', NULL),
  (3448686, 'OT', 'Moze II', 24, 11, 'Ba nitutuyu andrö ba Ndraono Gizeraeli, ba lö ibabaya. Ba me no lanehegö Lowalangi, ba manga ira.', '["Faigi 33:20; Yes 6:1; Hez 1:26"]', NULL),
  (3448686, 'OT', 'Moze II', 24, 12, 'Ba imane Yehowa khö Moze: Ae miyaŵa khögu ba hili ba ba da''ö iagö, ba ube''e khöu gara wanura andrö, ba nisura goroisa ba amakhoita andrö, nisuragu, ba wamahaö ya''ira.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 13, 'Ba maoso Moze, i''ohe genoninia Yosua andrö; ba möi miyawa ba hili Lowalangi Moze.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 14, 'Ba ba zatua no mege, ba imane: Mibaloiga ba da''e, irege mangawuliga khömi; so sa atö awömi Ga''aroni ba Huri. Na so zi so huhuo, ba yamu''ohe khöra.', '[]', NULL),
  (3448686, 'OT', 'Moze II', 24, 15, 'Ba me no irugi yaŵa hili, ba ibalugö hili lawuo.', '["MozV 4:24; Heb 12:29"]', NULL),
  (3448686, 'OT', 'Moze II', 24, 16, 'Ba i''iagö hili Zina''i lakhömi Yehowa. Önö ngaluo wa''ara ibalugö hili lawuo andrö; ba me luo si fitu, ba humede ia khö Moze, moroi ba lawuo.', '["MozV 4:24; Heb 12:29"]', NULL),
  (3448686, 'OT', 'Moze II', 24, 17, 'Ba ba wamaigi Ndraono Gizeraeli, ba hulö galitö si manga-manga hadia ia lakhömi Yehowa andrö ba zuzu hili.[4]', '["MozV 4:24; Heb 12:29"]', NULL),
  (3448686, 'OT', 'Moze II', 24, 18, 'Ba möi bakha ba lawuo Moze, möi ia miyaŵa ba hili. Ba öfa wulu ngaluo ba öfa wulu mbongi Moze ba hili.[5]', '["Faigi 34:28; MozV 9:9"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 2, 'Ŵa''ö ba Ndraono Gizeraeli, ena''ö labe''e mbobotolö khögu; midozigö zi no aoha gölö, wangai, khöra.[1]', '["Faigi 35:5"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 3, 'Ba da''ö game''ela nihalömi khöra: ana''a ba firö ba töla; ba ungu sowu', '["Sanguhuk 8:27"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 4, 'waru-waru ba ungu soyo ba kirimisi, ba tarafali ba bu nambi;', '["Sanguhuk 8:27"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 5, 'ba uli mbiri-biri nilau soyo ba uli mina guaza ba bana (eu);', '["Sanguhuk 8:27"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 6, 'ba fanikha ba wandru, ba remba-remba ba wanikha famayoini ba ba nitunu samohua;', '["Sanguhuk 8:27"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 7, 'ba feremata una, ba feremata bö''ö, talakhoi nono mbaru andrö, awö ba mbola waetasa andrö.[2]', '["Sanguhuk 8:27"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 8, 'Ba lafa''anö khögu nahia ni''amoni''ö, ena''ö sosodo ba khöra.[3]', '["Faigi 29:45; Heb 9:1"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3449318, 'OT', 'Moze II', 25, 9, 'Mitöngöni sibai wamaedo nahia ba famaedo wakakenia andrö fefu ni''oroma''ögu khöu dania, wamazökhi ya''ia.', '["Faigi 29:45; Heb 9:1"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 10, 'Ba lafazökhi dawöla, bana geunia, 2½ bela wa''anau ba 1½ hela wa''ebolo ba 1½ hela wa''alaŵa.[4]', '["Ayati 10—22: MozII 37:1—9"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 11, 'Ba öfo''uli si ndruhu mbalaki tanö bakha ba tanö baero öfo''uli ba öfasui wamosinga ya''ia ana''a.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 12, 'Ba öfa öfahele tumbo ni''ogaolo, ana''a, ba öfakhai ba gahenia si öfa, dombu-dombua fatambai.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 13, 'Ba öfazökhi hea-hea bana, ba öfo''uli ana''a.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 14, 'Ba hea-hea andrö, ba öfatörö ba dumbo ni''ogaolo no mege, ba ngai dawöla, ena''ö tobali famahea dawola.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 15, 'Böi tebulö ba dumbo ni''ogaolo andrö ba ngai dawöla hea-hea andrö; lö tola aheta ba da''ö.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 16, 'Ba barö dawöla andrö öbe''e zura goroisa, nibe''egu ba dangau dania.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 17, 'Ba öfazökhi lagö-lagö, si ndruhu mbalaki 2½ hela wa''anau ba 1½ hela wa''ebolo.', '["RazI 8:9; Heb 9:4"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 18, 'Ba dombua öfazökhi kerubi ana''a, — niböbözi wamazökhi ya''ia — faföfö lagö-lagö andrö; faoma faföfö öbe''e kerubi andrö.', '["RazI 8:9; Heb 9:4"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 19, 'Ba dete lagö-lagö andrö öbe''e kerubi andrö faföfö.', '["RazI 8:9; Heb 9:4"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 20, 'Ba kerubi andrö, ba samologö afira, miyaŵa, wamalugö lagö-lagö andrö afira, si fatahö ira, la''otahögö lagö dawöla kerubi andrö.', '["RazI 8:9; Heb 9:4"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 21, 'Ba öbe''e ba dete dawöla lagö-lagö andrö; ba bakha barö dawöla öbe''e zura goroisa andrö, nibe''egu ba dangau dania.[5]', '["RazI 8:9; Heb 9:4"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 22, 'Ba ba da''ö u''oroma-roma''ö ndra''o khöu dania, moroi ba lagö-lagö andrö fahuhuo ndra''o khöu, moroi ba gotalua kerubi andrö si dombua, si so ba dete dawöla wamaduhu''ö andrö, ero na so niŵa''ögu, nifa''emau ba Ndraono Gizeraeli.[6]', '["MozIV 7:89"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 23, 'Ba öfazökhi meza, bana geunia, 2 hela wa''anau ba sahela wa''ebolo ba 1½ wa''alaŵa.[7]', '["Ayati 23—29: Faza 37:10—16"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 24, 'Ba öfo''uli ia si ndruhu mbalaki ba öfosinga ana''a, fasui.', '["Ayati 23—29: Faza 37:10—16"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 25, 'Ba öfolambe-lambe, lalu''a wa''ebolo, fasui, ba öfosinga göi ana''a lambe-lambe andrö, si fasui göi.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 26, 'Ba öfa öfazökhi khönia tumbo ni''ogaolo, ba ba watalinga gahenia öfakhai dumbo andrö.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 27, 'Si fatöfa ba lambe-lambe dumbo andrö, naha hea-hea, ba wolohe meza andrö.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 28, 'Ba hea-hea andrö, ba bana, nifo''uli ana''a; da''ö wamahea meza andrö.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 29, 'Ba öfazökhi zoguna ba da''ö, mako ba figa ba kundri ba mako ba wamadu, fame''e zumange nibadu; si ndruhu mbalaki ö''oguna''ö wamazökhi ya''ia.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 30, 'Ba ba meza andrö, ba lö öbulö''ö roti nifaigi-faigi, fönagu.[8]', '["MozIII 24:5"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 31, 'Ba öfazökhi na naha wandru si ndruhu mbalaki,[9] niböbözi naha wandru andrö, ahenia ba tölania; ba nifobunga ia, bowo sawena aboto.[10]', '["Ayati 31—39: Faza 37:17—24","Faigi 37:17"]', NULL),
  (3449318, 'OT', 'Moze II', 25, 32, 'Ba nifodaha fatambai, tölu-tölu dambai ndraha.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 33, 'Ba sara-sara daha, ba tölu-tölu tebe''e ni''obowo kanari, sambu-sambua bowo, sawena aboto; si manö ba ndraha andrö fefu, si önö, daha naha wandru andrö.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 34, 'Ba ba döla, ba öfa tebe''e bunga ni''obowo kanari, sawena aboto.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 35, 'Sambu-sambua bowo tou zi dua-dua daha khönia, ba ndraha andrö, si önö, daha naha wandru andrö.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 36, 'Ba bene mbowo andrö ba daha andrö, ba ha sara, awö döla; niböbözi fefu, ba ha sara, si ndruhu mbalaki.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 37, 'Ba fitu öfazökhi fandru khönia, nibe''e yaŵa dania, ba wohagami naha andrö fönania.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 38, 'Ba guti wandru khönia ba sife andrö, ba si ndruhu mbalaki göi.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 39, 'Otu a dua wulu balaki ö''oguna''ö si ndruhu mbalaki, wamazökhi ya''ia, fabaya gama-gamania no mege.', '[]', NULL),
  (3449318, 'OT', 'Moze II', 25, 40, 'Ba faigi, fa ötöngöni sibai dulada andrö, ni''oroma''ö khöu ba hili, wamazökhi ya''ia.[11]', '["HalZin 7:44; Heb 8:5"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 1, 'Ba ba nose andrö,[1] ba fulu nga''örö kulambu öbe''e, wamazökhi ya''ia, kulambu nisoso, tarafali bana, ba ungu sowu waru-waru ba soyo, ba kirimisi; öfokerubi nifolau duka wanoso, wamazökhi ya''ia.[2]', '["Ayati 1—14: Faza 36:18—19","Faigi 36:8"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 2, 'Sagörö kulambu, ba 28 hela wa''anau ba 4 hela wa''ebolo; nifaomagö wa''ebua gulambu andrö fefu.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 3, 'Lima-lima nga''örö kulambu nifatagu.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 4, 'Ba öfotumbo dagu-tagu gulambu ba wondrege zi sagörö, tumbo ungu sowu waru-waru, ba si manö ba dagu-tagu gulambu ba wondrege zi sagörö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 5, 'Lima wulu dumbo öbe''e ba gulambu si sagörö ba lima wulu dumbo göi ba gulambu andrö si fasinga ba zi sagörö andrö, ena''ö faudu-faudu dumbo andrö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 6, 'Ba lima wulu öfazökhi khai-khai ba öbe''e famakhai gulambu andrö, ena''ö ha sambua nose andrö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 7, 'Ba öfazökhi göi dufo bu nambi, sagö nose andrö; felezara nga''örö öfazökhi tufo ba da''ö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 8, 'Sagörö tufo, ba 30 hela wa''anau ba 4 hela wa''ebolo; faoma wa''ebua zi felezara nga''örö andrö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 9, 'Lima nga''örö tufo andrö, ba öfatagu, öbali''ö si ha sagörö, ba si manö göi zi önö nga''örö, si tosai, ni''osagörö''ö; ba si sagörö ba naha zi önö, ba öfatö''ö dalu, öfodua winaeta, ba mbawa duasa nose.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 10, 'Ba ba dagu-tagu dufo ba wondrege zi sagörö andrö, ba lima wulu öfazökhi tumbo, ba si manö göi ba dagu-tagu dufo ba wondrege zi sagörö, lima wulu dumbo.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 11, 'Ba lima wulu öfazökhi khai-khai, töla, ba öfatörö ba dumbo andrö khai-khai andrö, wama''anö sagö andrö, fa ha sagörö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 12, 'Ba ba zi töra fa''anau dufo andrö, ba si matonga, ba ba gero nose latöraigö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 13, 'Ba hadia zi töra na ba dufo andrö, ba sahe-sahela dambai lafatalu''i''ö, ba ngai nose, ena''ö ibalugö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 14, 'Ba öfazökhi balu-balu dufo andrö dufo uli mbiri-biri, nilau soyo, ba balu-balu da''ö zui, ba tufo uli mina guaza.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 15, 'Ba öfalau''ö wafa, döla-döla nose, nifasindro, bana geunia.[3]', '["Ayati 15—25: Faza 36:20—30"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 16, 'Sagörö fafa, ba 10 hela wa''anau ba 1½ wa''ebolo.', '["Ayati 15—25: Faza 36:20—30"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 17, 'Ba sagörö, ba dua mba''i-ba''i, nifaböbö; si manö wamazökhiu fafa nose andrö fefu.', '["Ayati 15—25: Faza 36:20—30"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 18, 'Ba fafa nose, nifalau''ömö, ba 20 nga''örö tanö raya.', '["Ayati 15—25: Faza 36:20—30"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 19, 'Ba öfo''ahe firö, 40, ba wafa andrö si 20 nga''örö; dua-dua gahe zagörö fafa, ba mba''i-ba''inia andrö si dua-dua.', '["Ayati 15—25: Faza 36:20—30"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 20, 'Ba si manö göi, ba zi tambai nose, tanö yöu, 20 nga''örö fafa,', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 21, 'awö gahe firö andrö si 40, dua-dua gahe zagörö fafa.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 22, 'Ba ba hambo nose, tanö ba gaekhula luo, ba 6 nga''örö öfalau''ö fafa.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 23, 'Ba dua görö wafa öfalau''ö ba watalinga nose tanö furi, si dombua.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 24, 'Si dua-dua görö da''ö moroi tou, ba ha sara ba hogu, ba dumbo ni''ogaolo andrö si sambua; si manö zi dua görö andrö nifotalinga zi''u.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 25, 'Tobali ŵalu nga''örö fafa, si so ahe firö andrö — 16 gahe, dua-dua gahe zagörö fafa.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 26, 'Ba lima öfazökhi lazi,[4] bana, ba wafa andrö ba zi tambai nose,', '["Ayati 26—30: Faza 36:31—34"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 27, 'ba lima lazi ba wafa ba zi tambainia, ba lima lazi ba wafa ba gero nose, tanö ba gaekhula luo.', '["Ayati 26—30: Faza 36:31—34"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 28, 'Ba lazi ba dalu andrö, ba ba dalu wafa itörö, sandroro manö.', '["Ayati 26—30: Faza 36:31—34"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 29, 'Ba fafa andrö, ba öfo''uli ana''a, ba he tumbo andrö khönia, ba nifatörö lazi andrö, ba ana''a öfake wamazökhi ya''ia, ba lazi andrö ba öfo''uli ana''a.', '["Ayati 26—30: Faza 36:31—34"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 30, 'Si manö wamazökhiu ose andrö, dali ni''oroma''ö khöu ba hili.[5]', '["Faigi 25:40"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 31, 'Ba öfazökhi göi mba''a-ba''a ungu sowu waru-waru ba soyo ba kirimisi [6] ba tarafali bana nifolau duka wanoso wamazökhi ya''ia, nilalau kerubi.[7]', '["Ayati 31—37: Faza 36:35—38","Faigi 36:35"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 32, 'Öfa be''e taru nahe bana, nifo''uli ana''a ba nifo''ahe firö, ba wanandro ya''ia osö-osö ana''a.', '["Ayati 31—37: Faza 36:35—38","Faigi 36:35"]', NULL),
  (3449331, 'OT', 'Moze II', 26, 33, 'Ba barö khai-khai andrö naha mba''a-ba''a andrö; ba bakha barö mba''a-ba''a andrö öbe''e dawöla si so sura goroisa. Ba oto-oto khömi mba''a-ba''a andrö, ba gotaluara ni''amoni''ö wondrege ni''amoni''ö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 34, 'Ba öbe''e ba dete dawöla zura goroisa lagö-lagö andrö, ba wondrege ni''amoni''ö andrö.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 35, 'Ba meza andrö, ba baero mba''a-ba''a andrö öbe''e, ba naha wandru andrö, ba ba gamaudu meza, tanö raya ba nose; tanö yöu öbe''e meza.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 36, 'Ba öfazökhi göi mba''a-ba''a mbawandruhö nose, ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana, nifolau zanoso si gara-gara.', '[]', NULL),
  (3449331, 'OT', 'Moze II', 26, 37, 'Ba lima öfazökhi taru nahe, taru-taru mba''a-ba''a andrö, bana, ba öfo''uli ana''a; ba osö-osönia, ba ana''a göi, ba lima öfahele ahenia, töla.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 1, 'Ba naha wame''e sumange andrö,[1] ba bana geunia, lima hela wa''anau ba lima hela wa''ebolo — si öfa sagi — ba tölu hela wa''alaŵa.[2]', '["Ayati 1–8: Faza 38:1–7","Faigi 38:1"]', NULL),
  (3449333, 'OT', 'Moze II', 27, 2, 'Ba tandrunia, ba ba watalingania si öfa öbe''e ena''ö faböbö khönia dandru andrö, ba öfo''uli ia töla.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 3, 'Ba bowoa andrö khönia, ba wameta awu andrö, ba sou-sou khönia ba figa ba garafu ba gali, fefu wakake khönia, ba töla öbe''e.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 4, 'Ba öfazökhi khönia darali, si hulö gu''ö, töla; ba ba darali andrö, ba öfa öbe''e tumbo ni''ogaolo, töla, ba watalinga naha wame''e sumange andrö, si öfa,', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 5, 'ba tou lambe-lambe andrö, si fasui ba naha wame''e sumange andrö, ökhaigö, ena''ö ba dalu naha wame''e sumange irugi u''ö andrö.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 6, 'Ba öfazökhi hea-hea naha wame''e sumange, hea-hea bana, ba öfo''uli töla.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 7, 'Hea-hea andrö, ba ba dumbo andrö tefatörö, ena''ö tefatambai naha wame''e sumange hea-hea andrö, na lafabea.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 8, 'Fafa döla-dölania, ena''ö mo''arö tanö bakha; la''o''ö ni''oroma''ö khöu ba hili, wamazökhi ya''ia.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 9, 'Ba olayama nose andrö,[3] ba ömane wamazökhi ya''ia: ba wondregenia tanö raya, ba öfazökhi mba''a-ba''a golayama, tarafali bana öbe''e, otu hela wa''anau, ba ngai andrö si sara;[4]', '["Ayati 9–19: Faza 38:9–20","Faigi 38:9"]', NULL),
  (3449333, 'OT', 'Moze II', 27, 10, 'ba dua wulu daru nahe, awö gahe töla, si dua wulu — osö-osö ba daru nahe andrö ba tumbo ni''ogaolo andrö, ba firö öbe''e.', '["Ayati 9–19: Faza 38:9–20","Faigi 38:9"]', NULL),
  (3449333, 'OT', 'Moze II', 27, 11, 'Ba ba''a-ba''a ba ngai tanö yöu, otu hela, ba dua wulu daru nahe, awö gahe töla, si dua wulu; osö-osö ba daru nahe andrö ba tumbo ni''ogaolo andrö, ba firö.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 12, 'Ba ba lulu golayama tanö ba gaekhula, ba ba''a-ba''a si lima wulu hela ba fulu daru nahe, awö gahe, fulu.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 13, 'Ba lima wulu hela göi lulu golayama tanö ba gatumbukha,', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 14, 'ba felelima hela mba''a-ba''a ba zi tambai, ba tölu daru nahe, awö gahe, si tölu.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 15, 'Ba felelima hela mba''a-ba''a ba zi tambai ba tölu daru nahe, awö gahe, si tölu.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 16, 'Ba ba mbawa göli golayama, ba ba''a-ba''a si dua wulu hela fa''ebolo, ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana, nifolau zanoso si gara-gara, ba öfa daru nahe, awö gahe, si öfa.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 17, 'Ba fefu daru nahe ba golayama andrö, fasui, ba nifotumbo ni''ogaolo, firö; osö-osö khönia, ba firö, ba ahe, ba töla;', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 18, 'Fa''anau golayama andrö, ba otu hela, ba fa''ebolo, ba lima wulu hela, ba fa''alaŵa, ba lima hela [ba''a-ba''a andrö], tarafali bana, nifo''ahe töla.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 19, 'Ba fakake ba nose andrö, fefu [soguna] ba halöŵö ni''amoni''ö andrö, ba khönia, ba taru-tarunia fefu, awö daru-taru ba golayama fefu, ba töla.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 20, 'Ba ya''ugö, ba ŵa''ö ba Ndraono Gizeraeli, la''ohe khöu zi ndruhu wanikha zai, fanikha mbua zai nitutu, fanikha wandru andrö, ena''ö lö mamalö-malö la''ila latunu wandru.', '[]', NULL),
  (3449333, 'OT', 'Moze II', 27, 21, 'Ba nose wama''ele''ö andrö, baero mba''a-ba''a andrö, fomba''a zura goroisa, lafazökhi ia A''aroni ba ononia, i''otarai na bongi, irugi moluo, föna Yehowa. Huku si lö mamalö-malö da''ö ba Ndraono Gizeraeli, götö-götö wa''ara.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 1, 'Ba halö khöu ga''au A''aroni, awö nononia, nitutuyu ba Ndraono Gizeraeli fefu, ena''ö ere ira khögu, A''aroni ba Nadabi ba Abihu ba Eleazari ba Itamari, ono Ga''aroni andrö.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 2, 'Ba öfatagu''ö mbaru ni''amoni''ö khö Ga''aroni, sumange ba famoadu.', '["Faigi 39:1 b.t."]', NULL),
  (3449398, 'OT', 'Moze II', 28, 3, 'Ba hede ba duka andrö fefu, nibe''egu tödö ba wa''atuka, ena''ö latagu nukha andrö khö Ga''aroni, fa ta''ila ta''amoni''ö ia, ena''ö ere ia khögu.', '["Faigi 39:1 b.t."]', NULL),
  (3449398, 'OT', 'Moze II', 28, 4, 'Ba da''ö nukha andrö, nitagura: Bola ba ono mbaru ba doto ba baru sebua ba kameza, muko si gara-gara, ba bala högö ba böbö talu.[1]', '["Faigi 39:1 b.t."]', NULL),
  (3449398, 'OT', 'Moze II', 28, 5, 'Ba latagu nukha ni''amoni''ö khö Ga''aroni ba ba nononia, ena''ö ere ia khögu. Böna ame labe''e ba ungu sowu waru-waru ba soyo ba kirimisi ba tarafali.', '["Faigi 39:1 b.t."]', NULL),
  (3449398, 'OT', 'Moze II', 28, 6, 'Ba ba nono mbaru ba doto, ba böna ame labe''e ba ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 7, 'Dua görö labe''e balu-balu galisi, nifaböbö khönia, ba mbalönia si dua tefaböbö.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 8, 'Ba taŵi-taŵi andrö, si so khönia ba wobaru ya''ia, ba si manö göi wamazökhi, ba si fadoro khönia, böna ame ba ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 9, 'Ba dombua öhalö feremata una ba ösua yaŵa döi Ndraono Gizeraeli,', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 10, 'önö döi ba weremata si sambua, ba si önö, si tosai, ba ba zi sambua; öfa''oli, dali wa''asia''a.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3449398, 'OT', 'Moze II', 28, 11, 'Halöŵö zanua kara, fa''atuka zogao tandro wanua feremata andrö si dombua, dali döi Ndraono Gizeraeli; ba öfosinga ana''a.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 12, 'Ba feremata andrö, si dombua, ba öfakhai ba mbalu-balu galisi andrö, ba nono mbaru ba doto andrö, famasugi ba dödö [Yehowa] Ndraono Gizeraeli; tobali i''angalisigö döira A''aroni föna Yehowa, fa böi olifu ia.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 13, 'Ba öfosinga ana''a.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 14, 'Ba dua öfazökhi raeŵe-raeŵe si ndruhu mbalaki; si mane sinali nitali öbe''e, ba raeŵe-raeŵe sinali andrö, ba ba zinga no mege öfakhai.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 15, 'Ba öfazökhi mbola waetasa, nifolau duka wanoso, dali wamazökhi ono mbaru ba doto andrö ba wolaumö ya''ia, böna ame ba ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana öbe''e.', '["Fam 21:19–20"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 16, 'Ni''o''öfa sagi, dua winaeta, lito wa''anau ba lito wa''ebolo.', '["Fam 21:19–20"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 17, 'Ba öfa''oli ba detenia weremata, öfa ngenoli: feremata aki ba feremata zabarazadi ba feremata zumurudi ngenoli moroi yaŵa.[2]', '["Fam 21:19–20"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 18, 'Ba ba wanetenia, ba feremata manika ba feremata nila ba feremata ita.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 19, 'Ba ba wanetenia, ba feremata fusifaraga ba batu siabu ba feremata mariti.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 20, 'Ba ba wanetenia ba feremata firuza ba feremata una ba feremata yasia; da''ö nifa''oli khönia, nifasui singa ana''a andrö.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 21, 'Ba felendrua weremata andrö, dali döi Ndraono Gizeraeli andrö, si felendrua; sambu-sambua feremata, ba sambua-sambua nisua töi mado Ndraono Gizeraeli andrö, si felendrua, nifolau duka, sogao tandro.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 22, 'Ba öfakhai ba mbola andrö raeŵe-raeŵe nitali andrö, balaki.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 23, 'Ba bola andrö, ba öfotumbo ni''ogaolo, dombua; ba watalinga mbola andrö, si dombua öfakhai dumbo andrö, si dombua.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 24, 'Ba raeŵe-raeŵe balaki andrö, si dua rozi, ba ba dumbo mbola andrö, si dombua, öfakhai.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 25, 'Ba si föfö raeŵe-raeŵe andrö, si dua, ba öfakhai ba zinga no mege ba öfaböbö ba mbalu-balu galisi andrö ba nono mbaru ba doto, tanö föna.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 26, 'Ba dombua öfazökhi tumbo ni''ogaolo, ana''a, ba öbe''e ba watalinga mbola andrö, ba watalinga tanö barö, si otahögö ono mbaru ba doto.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 27, 'Ba dombua tö öfazökhi tumbo ni''ogaolo, ana''a, ba öfakhai ba mbalu-balu galisi andrö ba nono mbaru ba doto, tanö tou sibai, miföna, ba nifaböbö ya''ia, yaŵa mböbö nono mbaru ba doto.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 28, 'Ba bola andrö nifotumbo ba öfakhai ba dumbo nono mbaru, sinali ungu sowu waru-waru, nifatörö ba dete mböbö nono mbaru andrö, ba tobali lö maliŵa-liŵa mbola ba dete nono mbaru.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 29, 'Ba i''ohe-ohe döi Ndraono Gizeraeli A''aroni ba dete mbola waetasa andrö, ba dotonia, na möi ia ba ni''amoni''ö, föna Yehowa ena''ö lö mamalö-malö itörö tödönia ira.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 30, 'Ba ba mbola waetasa andrö öbe''e Urimi ba Tumimi (haga ba fa''atulö) andrö, ena''ö ba doto Ga''aroni so, na möi ia si bakha, föna Yehowa, fa böi mamalö-malö ba doto Ga''aroni waetasa andrö ba Ndraono Gizeraeli, föna Yehowa.[3]', '["MozIII 8:8; MozIV 27:21; MozV 33:8"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 31, 'Ba baru sebua andrö,[4] daya-daya nono mbaru andrö, ba ha sambalö ungu sowu waru-waru öbe''e,', '["Ayati 31-35: Faza 39:22–26"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 32, 'ba nitöla''ö, lala högö, ba dalu, ba nifasui rendra zatöla andrö, rendra nisoso, si mane ba lala högö ba göröba, fa böi atika.', '["Ayati 31-35: Faza 39:22–26"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 33, 'Ba ba dagu-tagunia, ba öbe''e ni''obua dalimo, ungu sowu waru-waru ba soyo ba kirimisi — ba dagu-tagunia, fasui — ba öfasolisi riti-riti, ana''a, sambu-sambua riti-riti', '["Ayati 31-35: Faza 39:22–26"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 34, 'ba sambu-sambua ni''obua dalimo, fasui, ba dagu-tagu mbaru sebua andrö, nifasolisi.', '["Ayati 31-35: Faza 39:22–26"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 35, 'Ba i''obaru A''aroni, ba halöŵönia, ena''ö terongo linia [li riti-riti andrö], na möi ia si bakha, ba ni''amoni''ö andrö, föna Yehowa, ba na möi baulu, fa böi mate ia.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 36, 'Ba öfazökhi na mbala högö si ndruhu mbalaki ba öfasua''ö ba detenia:[5] "Ni''amoni''ö khö Yehowa", nifolau zogao tandro.[6]', '["Ayati 36-38: Faza 39:30–31","Faigi 39:30"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 37, 'Ba öfaböbö ba zinali ungu sowu waru-waru, ena''ö adölö bala högö; ba gangango mbala högö tebe''e ia.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 38, 'Ba ba gangango Ga''aroni fatöfa ia, ena''ö A''aroni zolu''i si sala andrö ba ngawalö ni''amoni''ö andrö, ba zumange ni''amoni''ö andrö fefu, nibe''e Ndraono Gizeraeli dania. Böi yatebulö ba gangangonia, ena''ö omasi Yehowa ira ibe''e.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 39, 'Ba kameza andrö, ba tarafali öbe''e, nisoso, sogara-gara;[7] ba öfazökhi mbala högö tarafali ba böbö talu, nifolau zanoso sola''a-la''a.', '["Ayati 39-42: Faza 39:27–29"]', NULL),
  (3449398, 'OT', 'Moze II', 28, 40, 'Ba ba ndraono Ga''aroni, ba öfazökhi gameza ba böbö talu, ba kofia salaŵa öfazökhi khöra, sumange ba famoadu.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 41, 'Ba öbe''e nukha Ga''aroni ba nukha ndraononia ba öbayoini ira ba öfo''ösi dangara ba ö''amoni''ö ira, ena''ö ere ira khögu.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 42, 'Ba öfazökhi khöra zaraeŵa tarafali, balu-balu zaila ira; i''otarai löwi-löwi, irugi waha.', '[]', NULL),
  (3449398, 'OT', 'Moze II', 28, 43, 'Ba la''anaraeŵa A''aroni ba iraononia, na möi ira ba nose wama''ele''ö andrö ba na la''ondrasi naha wame''e sumange, ba wangai halöŵöra ba ni''amoni''ö andrö, fa böi mosala ira ba fa böi mate ira. Ya huku da''ö khönia ba ba madounia, si lö mamalö-malö.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 1, 'Ba ömane khöra we''amoni''ö ya''ira, ena''ö ere ira khögu:[1] Halö zi matua nono zaŵi ba dua geu zi matua mbiri-biri, si lö sinegu,[2]', '["Ayati 1—35: MozIII 8:1—32","MozIII 8:2"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 2, 'ba roti si lö mu''aisöni, nifaruka fanikha ba kue bö''ö si lö mu''aisöni, nigule''ö fanikha; hamo gandru wamazökhi ya''ia fefu.', '["Ayati 1—35: MozIII 8:1—32","MozIII 8:2"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 3, 'Ba öbe''e ba gambu-kambu, ba ohe, fabaya kambu-kambu, awö zaŵi andrö ba awö mbiri-biri andrö, si dua geu.', '["Ayati 1—35: MozIII 8:1—32","MozIII 8:2"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 4, 'Ba A''aroni ba iraononia, ba ohe ba mbawandruhö nose ba femondri ira.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 5, 'Ba halö nukha andrö ba fonukha Ga''aroni kameza ba baru sebua, daya-daya nono mbaru andrö, ba ono mbaru ba doto ba bola andrö, ba öböbö khönia mböbö nono mbaru andrö.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 6, 'Bala högö andrö be''e ba högönia ba öfaböbö ba mbala högö detenia andrö ni''amoni''ö.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 7, 'Ba öhalö wanikha famayoini andrö, ölau ba högönia, öbayoini ia.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 8, 'Ba ö''ohe ba da''ö göi ndraononia ba öfonukha ira kameza.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 9, 'Foböbö talu ira, he A''aroni ba he iraononia ba fokofia, ena''ö tetehe khöra wa''a''ere, gotö-götö wa''ara, huku si lö tebulö. Ba öfo''ösi danga ndra A''aroni iraononia.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 10, 'Ba ö''ohe föna nose wama''ele''ö zaŵi andrö, ena''ö latufa högönia A''aroni ba ira ononia tangara.[3]', '["MozIII 1:4"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 11, 'Awena dania ötaba zaŵi föna Yehowa, ba zinga mbawandruhö nose wama''ele''ö,', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 12, 'ba halö ösa ndro zaŵi andrö, ba gule''ö ba dandru naha wame''e sumange turumö; ba do soya, ba duwagö ba danö, ba gahe nahe wame''e sumange.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 13, 'Ba halö dawö fefu, balu-balu galakhaö ba si falemba ga gate, ba bua, si dombua, awö dawönia, ba tunu ba dete naha wame''e sumange.', '["MozIII 4:12; Heb 13:11"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 14, 'Ba ösi zaŵi andrö ba ulinia ba tainia, ba baero golombaseŵa ötunu — sumange fameta horö ia.[4]', '["MozIII 4:12; Heb 13:11"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 15, 'Ba sageu öhalö biri-biri andrö, ena''ö latufa högönia A''aroni ba iraononia, tangara.[5]', '["MozIII 8:18"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 16, 'Awena dania ötaba mbiri-biri andrö ba öhalö ndro ba öbe''e fanefe naha wame''e sumange, fasui.', '["MozIII 8:18"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 17, 'Ba biri-biri andrö, ba ötatawi, sasai mbetu''ania ba ahenia, ba orudugö ba nösinia bö''ö ba ba högönia.', '["MozIII 8:18"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 18, 'Ba tunu mbiri-biri andrö ma''asageu ba dete naha wame''e sumange — sumange nitunu ia, sumange Yehowa, samohua, sumange ba galitö, nibe''e khö Yehowa.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 19, 'Ba öhalö mbiri-biri si sageu, ena''ö latufa högönia A''aroni ba iraononia, tangara;', '["Faigi 28:41"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 20, 'ba taba mbiri-biri andrö ba halö ösa ndronia ba gule''ö ba mbörö dalinga Ga''aroni, ba gambölö, ba ba mbörö dalinga ndraononia ba gambölö ba ba duturura sebua ba dangara kambölö ba ba duturu kahe sebua ba gambölöra, ba do soya, ba be''e fanefe naha wame''e sumange, fasui.', '["Faigi 28:41"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 21, 'Ba öhalö ndro andrö ma''ifu, ba naha wame''e sumange, awö wanikha famayoini andrö, ma''ifu, ba ötefe Ga''aroni ba nukhania, ba iraononia ba nukhara, ena''ö ni''amoni''ö ia, awö nukhania, ba he iraononia, awö nukhara.[6]', '["Faigi 28:41"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 22, 'Ba halö dawö mbiri-biri andrö ba i''onia sotawö andrö, fabaya tawö balu-balu galakhaö, ba si falemba ba gate ba bua, si dombua, awö dawönia ba faha ba gambölö — biri-biri famataro ia[7] —', '["MozIII 7:3"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 23, 'ba sambua roti ba sagörö kue nifaruka fanikha ba sagörö kue bö''ö ba gambu-kambu andrö, nibe''e si lö mu''aisöni andrö, si so föna Yehowa.', '["MozIII 7:3"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 24, 'Ba öbe''e ba danga Ga''aroni ba ba danga ndraononia da''ö fefu, ba öhahae nihahae khö Yehowa.', '["MozIII 7:3"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 25, 'Ba öfuli öhalö ba dangara ba ötunu ba dete naha wame''e sumange, awö zumange nitunu andrö, samohua khö Yehowa: sumange ba galitö ia, nibe''e khö Yehowa.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 26, 'Ba öhalö nosu mbiri-biri famataro Ga''aroni andrö ba öhahae nihahae khö Yehowa, ba urakhau dania ia.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 27, 'Ba ni''amoni''ö öŵa''ö nosu andrö, nihahae, ba faha andrö fegero, nihalö mege fegero, faha mbiri-biri famataro Ga''aroni ba iraononia.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 28, 'Urakha ndra A''aroni iraononia da''ö, nifakhoi ba Ndraono Gizeraeli, si lö mamalö-malö; sumange nihalö fegero ia, ba sumange nihalö fegero labe''e ia Iraono Gizeraeli, föfö zumange fangorifi andrö khöra, sumange nihalö fegero khöra, nibe''e khö Yehowa.[8]', '["MozIII 7:34; MozIV 18:11"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 29, 'Ba nukha ni''amoni''ö andrö khö Ga''aroni, ba möi ba nononia na furi ena''ö la''onukha na tebayoini ira ba na tefo''ösi dangara.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 30, 'Fitu ngaluo wa''ara i''onukha ononia andrö si tobali ere fangalinia, si möi-möi ba nose wama''ele''ö andrö, ba wangai halöŵö andrö ba ni''amoni''ö.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 31, 'Ba biri-biri famataro andrö, ba öhalö, ba ba naha ni''amoni''ö örino nösinia.', '["MozIII 8:31; 24:9"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 32, 'Ba A''aroni ba iraononia zi manga nösi mbiri-biri andrö, awö roti andrö, ba gambu-kambu, ba zinga mbawandruhö nose wama''ele''ö la''a.[9]', '["MozIII 8:31; 24:9"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 33, 'Fameta horö andrö, me lafo''ösi dangara, me la''amoni''ö ira, da''ö la''a; lö töla i''a niha bö''ö, me no ni''amoni''ö.', '["MozIII 8:31; 24:9"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 34, 'Ba na so zi tosai, irege mahemolu mbanua, ösi mbiri-biri famataro andrö, ba ma roti andrö, ba ötunu zi tosai andrö: lö tola la''a niha, me no ni''amoni''ö.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 35, 'Si manö wolaumö khö Ga''aroni ba ba ndraononia, ö''o''ö sibai niŵa''ögu khöu: fitu bongi wa''ara öfo''ösi dangara.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 36, 'Ba ö''erogö ma''ökhö wangasogö si matua nono zaŵi, sumange fameta horö, ba wangefa''ö horö andrö, ba öheta zala ba naha wame''e sumange, na ölau wangefa horö andrö ba khönia, ba öbayoini ia, ba we''amoni''ö ya''ia.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 37, 'Fitu bongi wa''ara ölau wangefa horö andrö ba naha wame''e sumange, ba we''amoni''ö ya''ia; ba tobali ni''amoni''ö sibai naha wame''e sumange andrö, ba dozi sombambaya naha wame''e sumange andrö, ba no ni''amoni''ö göi.[10]', '["Mat 23:19"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 38, 'Ba da''ö nibe''eu ba naha wame''e sumange:[11] Ero ma''ökhö ba dua rozi nono mbiri-biri, si döfi fa''ebua; si lö mamalö-malö da''ö.[12]', '["Ayati 38—42: MozIV 28:2—8","MozIV 28:3"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 39, 'Ono mbiri-biri si sara, ba na mahemolu mbanua öbe''e, ba si sara, ba na tanö owī.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 40, 'Ba samba hinaoya hamo safusi, nifaruka fanikha mbua zai nitutu, samba kata; ba sumange nibadu, samba kata agu, nifao ba nono mbiri-biri si sara.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 41, 'Ba ono mbiri-biri si sara, ba tanö owi öbe''e — ba ba zumange ni''a ba ba zumange nibadu, ba si mane na mahemolu mbanua ölau, samohua omasiö, ö nifatörö ba galitö, nibe''e khö Yehowa,', '["MozIII 1:1; MozIV 12:5"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 42, 'sumange nitunu khömi, si lö mamalö-malö, götö-götö wa''ara, ba zinga mbawandruhö nose wama''ele''ö, föna Yehowa, ba ni''oroma''ögu ya''o khöu dania ba zi fahuhuodo khöu.[13]', '["MozIII 1:1; MozIV 12:5"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 43, 'Ba ba da''ö u''oroma''ö ndra''odo ba Ndraono Gizeraeli, ba ni''amoni''ö dania ia, ba lakhömigu andrö.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 44, 'Ba u''amoni''ö nose wama''ele''ö andrö, awö naha wame''e sumange; ba A''aroni göi ba iraononia, ba u''amoni''ö, ena''ö ere ira khögu.', '[]', NULL),
  (3451145, 'OT', 'Moze II', 29, 45, 'Ba u''iagö ba hunö Ndraono Gizeraeli, ba Lowalangira ndra''odo;[14]', '["Faigi 25:8; MozIII 26:12; KorII 6:16; Fam 21:3"]', NULL),
  (3451145, 'OT', 'Moze II', 29, 46, 'ba ya''aboto ba dödöra, wa no ya''odo, Yehowa, Lowalangira, si no mangeheta ya''ira ba danö Miserayi, ba wangiagö khöra — ya''odo andre, Yehowa, Lowalangira.', '["Faigi 25:8; MozIII 26:12; KorII 6:16; Fam 21:3"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 1, 'Ba öfazökhi na naha wanunu samohua;[1] bana öbe''e eunia.[2]', '["Ayati 1—5: Faza 37:25—28","Faigi 37:25"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 2, 'Sahela wa''anau ba sahela wa''ebolo; ni''o''öfa sagi, ba dua hela wa''alaŵa. Si fadoro khönia dandrunia.', '["Ayati 1—5: Faza 37:25—28","Faigi 37:25"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 3, 'Ba öfo''uli ia si ndruhu mbalaki, mezania, awö saginia, fasui, awö dandrunia, ba öfasui ia singa si ndruhu mbalaki.', '["Ayati 1—5: Faza 37:25—28","Faigi 37:25"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 4, 'Ba tou zinga andrö, ba öfotumbo ni''ogaolo, dombua, ba watalingania si dombu-dombua; faoma fatambai öbe''e, naha hea-hea, ba wamahea ya''ia.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 5, 'Ba hea-hea andrö, ba bana öbe''e eu, ba öfo''uli ana''a.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 6, 'Ba baero mba''a-ba''a andró, fomba''a dawöla, si so sura goroisa, öbe''e ia — baero mba''a-ba''a lagö dawöla andrö, si so yaŵa zura goroisa andrö, ba ni''oroma''ögu ya''o khöu dania.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 7, 'Ba itunu ba detenia yaŵa zamohua A''aroni; ero mahemolu mbanua, na ihaogö wandru andrö, itunu.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 8, 'Ba na owi göi, na itunu wandru, ba itunu göi A''aroni; sumange simbo, si lö mamalö-malö khömi, föna Yehowa, götö-götö wa''ara.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 9, 'Samohua bö''ö ba sumange nitunu ba sumange ni''a, ba böi mibe''e yaŵa; ba he sumange nibadu, ba lö tola mifaduwa yaŵa.[3]', '["MozIII 10:1"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 10, 'Ba samuza zi döfi iheta zala, ba dandrunia andrö A''aroni, do zumange fameta horö andrö, ba wameta sala, ibe e fameta zala khönia, zamuza zi döfi, götö-götö wa''ara — ni''amoni''ö sibai khö Yehowa.[4]', '["MozIII 16:2; Heb 9:7"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 11, 'Ba humede Yehowa khö Mose, imane:', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 12, 'Na ö''erai zatua Ndraono Gizeraeli ba yamube''e khö Yehowa mbele-bele nosonia zamösana, na te''erai ira, ena''ö lö göna ira famakao, na te''erai ira.[5]', '["MozIV 1:2"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 13, 'Dozi ni''erai ba ½ zekeli (sasuku) zamösa labe''e, saga ni''amoni''ö, 20 gera zamba sekeli, ½ zekeli, ömöra sumange Yehowa.[6]', '["MozIII 27:25; Hez 45:12"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 14, 'Dozi ni''erai, i''otarai zi no dua wulu fakhe, numalö ba zi a''a moroi andrö, ba labe''e khö Yehowa zumange andrö, ömöra.', '["MozIII 27:25; Hez 45:12"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 15, 'So''ana''a ba lö itöraigö, ba si numana, ba lö i''ambösi, ha ½ zekeli, wame''e sumange andrö khö Yehowa, ömöra, bele-bele noso.', '["MozIII 27:25; Hez 45:12"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 16, 'Ba ötema gasalaö andrö ba Ndraono Gizeraeli ba öbe''e balazo ba wohalöŵö ba nose wama''ele''ö, ena''ö itörö tödö Yehowa Ndraono Gizeraeli ibe''e, ba ena''ö bele-bele nosora.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 17, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 18, 'Fazökhi gala töla, nifo''ahe töla, naha wanasa. Ba ba gotalura nose wama''ele''ö naha wame''e sumange öbe''e ba fo''ösi idanö,[7]', '["Faigi 38:8"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 19, 'fanasa gahe ba fanasa danga khö Ga''aroni ba ba ndraononia.', '["Faigi 38:8"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 20, 'Na möi ira ba nose wama''ele''ö, ba lasasai nösira, fa böi mate ira, ba si manö göi na möi baero, ba naha wame''e sumange, ba wangai halöŵöra wanunu sumange ba galitö, khö Yehowa.', '["Faigi 38:8"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 21, 'Lasasai dangara ba ahera, fa böi mate ira, ba amakhoita khöra da''ö si lö tebulö, götö-götö wa''ara — khönia ba ba madounia, götö-götö wa''ara.', '["Faigi 38:8"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3452299, 'OT', 'Moze II', 30, 22, 'Ba humede na Yehowa khö Moze, imane:', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 23, 'Faigi khöu remba-remba, fondrege zi sökhi, 500 [zekeli] emuri fondrege zi sökhi ba matonga da''ö guli mani, tobali 250 [zekeli], ba 250 [zekeli] deringu samohua,', '["Faigi 37:29"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 24, 'ba kuli deza 500 [zekeli], ba zaga ni''amoni''ö ba sadumba wanikha zai;', '["Faigi 37:29"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 25, 'ba bali''ö fanikha famayoini, ni''amoni''ö, si hulö dalu-dalu nigule''ö samohua, nifolau zamaruka dalu-dalu nigule''ö — ya fanikha famayoini ni''amoni''ö ia![8]', '["Faigi 37:29"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 26, 'Ba öbe''e famayoini nose wama''ele''ö andrö, fabaya tawöla, si so sura goroisa andrö barö,[9]', '["MozIII 8:10"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 27, 'ba he meza andrö, awö wakake ba da''ö, ba he naha wandru ba fakakenia, awö naha wanunu samohua andrö,', '["MozIII 8:10"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 28, 'ba he naha wame''e sumange nitunu, ba fakakenia fefu ba he gala andrö ba ahenia.', '["MozIII 8:10"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 29, 'Ba ö''amoni''ö, ena''ö ni''amoni''ö sibai; dozi sombambaya, ba no ni''amoni''ö göi.', '["MozIII 8:10"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 30, 'Ba A''aroni ba iraononia, ba öbayoini göi ba ö''amoni''ö, ena''ö ere ira khögu.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 31, 'Ba ba Ndraono Gizeraeli; ba ömane: Fanikha famayoini, ni''amoni''ö, khögu ia, miŵa''ö, götö-götö wa''ara.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 32, 'Lö tola lalau ba nösi niha, ba lö tola mifazökhi khömi zi manö famaruka: ni''amoni''ö ia, ni''amoni''ö miŵa''ö.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 33, 'Na so zamaruka si manö ba na ibe''e ba niha bö''ö, ba nise''e ia ba niwara.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 34, 'Ba imane Yehowa khö Moze: Faigi khöu remba-remba samohua: gitö emuri ba lawa ba rasamala — remba-remba, ba si ndruhu kumöyö, fagölö-gölö wa''oya,', '["MozIII 2:13"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 35, 'ba bali''ö samohua nitunu, nifaruka, samohua, nifolau zamaruka dalu-dalu nigule''ö, nilau asio ma''ifu ba böi fabaya hadia ia, nifake ba ni''amoni''ö.[10]', '["MozIII 2:13"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 36, 'Ba öhalö ma''ifu ba öfaulugö örekha ba öbe''e föna zura goroisa ösa ba nose wama''ele''ö, ba ni''oroma''ögu ya''odo khöu dania; ni''amoni''ö sibai niŵa''ö.', '["MozIII 2:13"]', NULL),
  (3452299, 'OT', 'Moze II', 30, 37, 'Ba khömi, ba lö tola mifazökhi zamohua nitunu si manö famaruka, nilau ba nifazökhimö andrö; ni''amoni''ö khö Yehowa öŵa''ö.', '[]', NULL),
  (3452299, 'OT', 'Moze II', 30, 38, 'Na so zamazökhi si manö, ena''ö i''ago hua, ba nise''e ba niwara da''ö.', '[]', NULL),
  (3452853, 'OT', 'Moze II', 31, 1, 'Ba humede Yehowa khö Moze, imane:[1]', '["Ayati 1–6: Faza 35:30–35"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 2, 'Hiza, no ukaoni Mbesale''eli andrö, ono Guri ono Huri, mado yuda, no utötöi döi,', '["Faigi 35:30","RazI 7:14"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 3, 'ba no uhöna khönia Geheha Lowalangi,[2] ba fa''atuka ba fa''aboto ba dödö ba fangila, awö ngawalö wa''ato''ölö,[3]', '["Faigi 35:30","RazI 7:14"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 4, 'ba wangalui nekhe-nekhe ba wohalöŵö ba gana''a ba ba wirö ba ba döla,', '["Faigi 35:30","RazI 7:14"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 5, 'ba ba wangazökhi feremata, famoadu, ba fama''anö eu, hadia ia ngawalö.', '["Faigi 35:30","RazI 7:14"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 6, 'Ba noa göi ube''e awönia Goholiabi, ono Gahizamakhi, mado Dano, ba no ube''e dödö wa''atuka ba duka andrö fefu, ena''ö ahori lafazökhi niŵa''ögu khöu:', '["Ayati 7–11: Faza 35:11–19","MozV 9:12"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 7, 'Ose wama''ele''ö andrö,[4] ba tawöla andrö, naha zura goroisa ba lagö-lagö andrö yaŵa, fabaya fakake ba nose fefu;[5]', '["Ayati 7–11: Faza 35:11–19","MozV 9:12"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 8, 'ba meza andrö, awö wakake khönia, awö naha wanunu samohua,', '["Ayati 7–11: Faza 35:11–19","MozV 9:12"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 9, 'awö naha wame''e sumange nitunu, fabaya fakakenia fefu, ba gala andrö, awö gahenia.', '["Ayati 7–11: Faza 35:11–19","MozV 9:12"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 10, 'Awö nukha nihaogö famazökhi andrö ba nukha ni''amoni''ö khö Ga''aroni, ere andrö, fabaya nukha ndraononia ba wo''ere,', '["Ayati 7–11: Faza 35:11–19","MozV 9:12"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 11, 'ba fanikha famayoini ba samohua andrö nitunu ba ni''amoni''ö andrö. La''o''ö sibai niŵa''ögu khöu, wamazökhi ya''ia.', '["Ayati 7–11: Faza 35:11–19","MozV 9:12"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 12, 'Ba imane Yehowa khö Moze:[6]', '["Ayati 12–17: Faza 35:1–3"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 13, 'Be''e li ba Ndraono Gizeraeli, ömane: Böi zi lö itörö tödömi luo wolombase andrö khögu! me no tandra ia khöda, götö-götö wa''ara, ena''ö aboto ba dödö, wa no ya''o, Yehowa, zi amoni''ö ya''ami.[7]', '["MozI 20:8"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 14, 'Andrö böi olifu ami luo wolombase andrö; ni''amoni''ö ia khömi; ha niha zanawö oroisa ba khönia ba huku famunu hukunia. Na so zangai hadia ia halöŵö, na luo da''ö, ba nise''e da''ö ba niwara.[8]', '["MozIV 15:35","MozI 2:2"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 15, 'Önö ngaluo zi tola tehalö halöŵö, ba luo si fitu andrö, ba no luo ni''amoni''ö khö Yehowa, lö''ö manö mohalöŵö ba da''ö, dozi sangai halöŵö ba luo sabato, ba huku famunu huku.', '["MozIV 15:35","MozI 2:2"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 16, 'Andrö böi olifu Ndraono Gizeraeli luo sabato andrö, ba we''amoni''ö ya''ia, götö-götö wa''ara, amakhoita si lö tebulö.', '["MozIV 15:35","MozI 2:2"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 17, 'Ya tandra ia khöma Iraono Gizeraeli, götö-götö wa''ara. önö ngaluo Yehowa wamazökhi banua si yaŵa, awö danö; ba me luo si fitu andrö, ba molombase ia, ihasugö ia.[9]', '["MozIV 15:35","MozI 2:2"]', NULL),
  (3452853, 'OT', 'Moze II', 31, 18, 'Ba me no i''o''ozui huhuonia khö Moze, ba ibe''e ba dangania zura goroisa andrö, si dua görö, kara wanura, nisua turu Lowalangi.[10]', '["MozV 9:10"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 1, 'Ba me la''ila sato,[1] arörö Moze wangawuli moroi ba hili, ba lahurufai Ga''aroni, ba lamane khönia: Labu, asogö khöda Lowalangi sowaö-waö fönada; lö''ö sa ma''ila, hadia zi göna niha andrö, Moze andrö, sangeheta ya''ita ba danö Miserayi.[2]', '["Faigi göi MozV 9:8–21","HalZin 7:40"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 2, 'Ba imane khöra A''aroni: Miheta zaeru dalinga ana''a andrö, ba dalinga wo''omomi ba ba dalinga nonomi matua ba ba dalinga nonomi alawe, ba mi''ohe khögu.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 3, 'Ba laheta zaeru dalinga ana''a ba dalingara, dozi, ba la''ohe khö Ga''aroni.', '["Sin 106:19"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 4, 'Ba ihalö ba dangara, ilau wahö, ibali''ö ono zaŵi nifahele. Ba lamane: Da''ö Lowalangimi, ya''ami, Iraono Gizeraeli, sangeheta ya''ami ba danö Miserayi![3]', '["Sin 106:19"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 5, 'Ba me i''ila da''ö A''aroni, ba ifazökhi naha wame''e sumange fönania; ba ifatenge zi''ao, lamane: Mahemolu telau gowasa khö Yehowa!', '["KorI 10:7"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 6, 'Ba mahemolu ö, ba lahulö wongi wame''e sumange nitunu ba sumange fangorifi, ba mudadao zato manga ba mamadu hadia ia; ba maoso ira, ba wolaya.[4]', '["KorI 10:7"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 7, 'Ba imane Yehowa khö Moze: Labu, ae mitou, noa sa elungu mbanuau andrö, nihetau ba danö Miserayi.[5]', '["MozV 9:12","RazI 12:28"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 8, 'No alio sibai laröi lala andrö, nifakhoigu khöra, no lafazökhi nono zaŵi nifahele ba no mangalulu ira khönia, no lafosumange ba no lamane: Da''ö Lowalangimi, ya''ami Iraono Gizeraeli, sangeheta ya''ami ba danö Miserayi.[6]', '["MozV 9:12","RazI 12:28"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 9, 'Ba imane na Yehowa khö Moze: u''ila sa''ae, wa no niha sabe''e börö du''i niha andrö.[7]', '["Yes 48:4"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 10, 'Ba böhöido sa''ae, ena''ö tesao wönugu khöra ba ena''ö uhori ira, ba ubali''ö furugö soi sebua ndra''ugö!', '["Yes 48:4"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 11, 'Ba itandraigö i''alösi dödö Lowalanginia Yehowa Moze, imane: He Yehowa! hana wa mofönu sibai ndra''ugö ba mbanuau andrö nihetau ba danö Miserayi fa''abölöu ba tangau sabe''e andrö?[8]', '["Sin 106:23","MozIV 14:13","MozI 12:7"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 12, 'Hana wa öbe''e laŵa''ö dania Dawa Miserayi: Ba wamatörö si lö sökhi iheta ira, ena''ö ibunu ira ba hili andrö, ba ena''ö ihori ira ba guli danö? Alösi wönumö, sabölö sibai andrö, ba hana na mangesa dödöu ba wamunu andrö, niŵa''öu nifatörö ba mbanuau andrö![9]', '["Sin 106:23","MozIV 14:13","MozI 12:7"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 13, 'Törö tödöu genoniu Aberahamo ba Iza''aki ba Izeraeli, ba zi no fahölu ndra''ugö ba khöu, ba zi no öfabu''u: u''oya''ö dania ma''uwumi, timba ndröfi ba mbanua si yawa, ba tanö andre, niŵa''ögu, ba ube''e ba ma''uwumi, ena''ö khöra, irugi zi lö aetu![10]', '["Sin 106:23","MozIV 14:13","MozI 12:7"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 14, 'Ba mangesa dödö Yehowa ba wamunu andrö, nidaö''ö-daö''önia folau ba mbanuania andrö.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 15, 'Ba mangawuli Moze möi ia mitou, moroi ba hili, i''ohe tangania zura goroisa andrö, si dua görö — kara wanura, nisura faoma fatambai; tete ba arö, ba faoma no musura.[11]', '["MozV 9:10"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 16, 'Ba nifazökhi Lowalangi gara wanura andrö, ba sura Lowalangi zura nisura ba gara andrö.', '["MozV 9:10"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 17, 'Ba me irongo wagua-guasa zato Yosua, ba imane khö Moze: Fangahahagö ba wanuwö ba golombaseŵa!', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 18, 'Ba imane Moze: Tenga fe''ao nilau zabölö da''ö ba tenga göi fangahahagö nilau zi te''ala; fanunö urongo.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 19, 'Ba me ahatö Moze ba golombaseŵa ba me i''ila nono zaŵi andrö ba solaya andrö, ba mofönu ia, tobali itibo''ö tou gara wanura andrö, irasa ba gahe hili.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 20, 'Ba ihalö nono zaŵi andrö, nifazökhira, itunu ba irekha, ibali''ö gawu-gawu, ilau ba nidanö ba ibe''e ba Ndraono Gizeraeli, nibadu.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 21, 'Ba imane Moze khö Ga''aroni: Hadia nilau niha andrö khöu, wa öfatörö khöra horö sebua andrö?', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 22, 'Ba imane A''aroni: He Tua! böi öfönu; ya''ugö sa''ae zangila, wa no si lö sökhi nilau dödö zato andrö.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 23, 'No la''andrö khögu, lamane: Fazökhi khöda Lowalangi, sowaö-waö fönada; lö''ö sa ta''ila hadia zi göna niha andrö, Moze andrö, solohe ya''ita ba da''e, moroi ba danö Miserayi.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 24, 'Ba umane khöra: Ha niha zo''aya ana''a, ba yamuheta! Ba labe''e khögu ba utibo''ö ba galitö, ba tobali ono zaŵi andrö.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 25, 'Ba me i''ila Moze, no fakuyu ba zato — noa sa ilulu khöra A''aroni, fama''iki zi fa''udu khöra —', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 26, 'ba i''agö mbawa göli golombaseŵa Moze, mu''ao ia, imane: Yamöi khögu ba da''e zi lö aefa khö Yehowa! Ba owulo khönia nono Lewi, fefu.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 27, 'Ba imane khöra: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizaraeli: Dozi ami mibe''e ba löwi-löwimi wödami, ba mitöröi golombaseŵa, i''otarai mbawa göli tanö andre, numalö ba mbawa göli tanö sa, ba mibunu ha niha ira, he talifusö ba he si fahuwu ba he si tenga bö''ö!', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 28, 'Ba la''o''ö niŵa''ö Moze ono Lewi andrö ba mafo tölu ngahönö zi mate me luo da''ö niha sato.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 29, 'Ba imane Moze: Mifo''ösi dangami khö Yehowa ma''ökhö, noa sa udu nononia zamösana ba udu dalifusönia, ena''ö möi sa''ae khömi howu-howu.[12]', '["MozIV 25:13"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 30, 'Ba mahemolu ö, ba imane Moze ba niha sato: No ebua sibai horömi; ba damöido miyaŵa khö Yehowa, ma atö u''ila u''andrö aefa khömi horömi andrö.', '[]', NULL),
  (3453634, 'OT', 'Moze II', 32, 31, 'Ba ifuli ia khö Yehowa Moze, imane: Alai ndra''o, no ebua sibai horö niha andrö, no lafazökhi khöra Lowalangi ana''a.', '["Sin 69:29; Rom 9:3"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 32, 'Ba u''andrö khöu, be''e aefa khöra horöra andrö! ba na lö''ö, ba töigu bunu ba zura andrö, nisuramö.[13]', '["Sin 69:29; Rom 9:3"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 33, 'Ba imane Yehowa khö Moze: Si so sala khögu, da''ö nibunugu töi ba zuragu.', '["Faigi 23:20"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 34, 'Ba ae''e iada''e, ba ohe niha andrö ba niŵa''ögu khöu; mowaö-waö fönau mala''ika andrö khögu. Ba na irugi inötö wanguhuku andrö khögu, ba uhuku sa khöra horöra andrö.[14]', '["Faigi 23:20"]', NULL),
  (3453634, 'OT', 'Moze II', 32, 35, 'Ba ifatörö khöra wamakao Yehowa, me no lafazökhi nono zaŵi andrö, nifahele Ga''aroni.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 1, 'Ba imane Yehowa khö Moze: Faoso, miheta ami ba da''e, ya''ugö ba sato, nihetau ba danö Miserayi, mi''ae ba danö andrö, nifabu''ugu khö ndra tuami Aberahamo, Iza''aki, Yakobo, fahölusa, me umane: Ba ma''uwumi ube''e ia![1]', '["MozI 15:18","Faigi 23:20; Yos 24:11","Faigi 32:9"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 2, 'Ba ufowaö-waö fönami mala''ika, ba wanimba fönami Dawa Gana''ana ba Iraono Gamori ba Iraono kheti ba Iraono Weresi ba Iraono Hewi ba Iraono Yebusi[2] —', '["MozI 15:18","Faigi 23:20; Yos 24:11","Faigi 32:9"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 3, 'ba danö si falawu susu ba ŵe ŵani; ya''odo sa, ba lö fao khömi me no niha sabe''e börö du''i ami, ma dania uhori ami ba lala.[3]', '["MozI 15:18","Faigi 23:20; Yos 24:11","Faigi 32:9"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 4, 'Ba me larongo wehede sabe''e andrö sato, ba abu sibai dödöra ba samösa lö si o''aya ayania.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 5, 'Ba imane Yehowa khö Moze: Ömane ba Ndraono Gizeraeli: Niha sabe''e börö du''i ami! he ha mamö''i hörö wa''ara faodo khömi, ba uhori ami. Ba miheta nayami; awena dania ufaigi he uwisa khömi.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 6, 'Ba laheta nayara Iraono Gizeraeli, i''otarai ba hili Horebi andrö.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 7, 'Ba ihalö-halö nose andrö Moze, ba baero golombaseŵa ifa''anö-anö, aröu ma''ifu aefa ba golombaseŵa, ba ose wama''ele''ö ibe''e töinia. Na so zanofu hadia ia khö Yehowa, ba möi baero, ba nose wama''ele''ö andrö, föna-föna golombaseŵa.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 8, 'Ba ero möi baero Moze, ba nose, ba maoso zato fefu ba i''iagö mbawandruhö nosenia zamösana, lanehegö wofanö Mose, irege no irugi nose.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 9, 'Ba ero na irugi nose Moze, ba adada mboto lawuo andrö, i''iagö zinga mbawandruhö nose, ba fahuhuo Yehowa khö Moze.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 10, 'Ba dozi niha zangila boto lawuo andrö, ba zinga mbawandruhö nose, ba maoso ira fefu, ba ifalögu tou ia ba danö zamösana, ba mbawandruhö nosenia.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 11, 'Ba fahuhuo Yehowa khö Moze, si faudu wawa ira, si mane na fahuhuo zi fahuwu; ba ifuli ia ba golombaseŵa ba toröi dohu-tohu dangania andrö, Yosua, ono Nuni, ngoni-ngoni bakha ba nose, lö tebulö.[4]', '["MozIV 12:8"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 12, 'Ba imane Moze khö Yehowa: öŵa''ö sa: Ohe misa niha andrö! ba lö ni''ombakha''öu khögu, ha niha nifatengeu awögu.', '["Sin 103:7"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 13, 'Ba na no falukhado wa''ebua dödöu, ba bokai khögu dödöu ba be''e aboto ba dödögu ndra''ugö, ena''ö falukhado wa''ebua dödö khöu, ba törö-törö atö tödöu, wa no banuau niha andre.[5]', '["Sin 103:7"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 14, 'Ba imane: Hadia, ya''odo zi fao, ba wolohe ya''ugö ba gahonoa naha?', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 15, 'Ba imane Moze: Na tenga ya''ugö zi fao, ba si sökhinia, na lö öhetaga ba da''e!', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 16, 'Heza so na, baero ö, ba zaboto ba dödö, wa no falukhaga wa''ebua dödö khöu, he ya''odo, ba he banuau andrö, na tenga ba wefaomö khöma, ba na tehude''ö ndra''aga banuau andrö, ba da''ö, föna soi bö''ö fefu ba guli danö?', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 17, 'Ba imane Yehowa khö Moze: Ba he da''ö göi, ni''andröu, ba u''o''ö; noa sa falukha''ö wa''ebua dödö khögu ba no u''ila döimö.', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 18, 'Ba i''andrö khönia: Oroma''ö khögu lakhömimö!', '[]', NULL),
  (3454319, 'OT', 'Moze II', 33, 19, 'Ba imane: Fa''asökhigu fefu ba ufatörö fönau ba utötöi fönau döi Yehowa, ba ebua dödögu ba zomasido ebua ia, ba uhakhösi tödö zomasido akhakhö dödögu.[6]', '["Faigi 34:5; Rom 9:15","MozV 4:12; Yoh 1:18; TimI 6:16"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 20, 'Ba imane na: Bawagu, ba tebai öfaigi; lö''ö sa auri niha, na i''ila ndra''odo![7]', '["Faigi 34:5; Rom 9:15","MozV 4:12; Yoh 1:18; TimI 6:16"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 21, 'Ba imane na Yehowa: So naha, sahatö khögu, hana sa na ba da''ö möi''ö, ba gara yaŵa.', '["Faigi 34:5; Rom 9:15","MozV 4:12; Yoh 1:18; TimI 6:16"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 22, 'Ba na itörö lakhömigu andrö, ba u''ohe''ö ba dögi narö gara, ba ubalugö ndra''ugö tangagu, irege no utörö.', '["Faigi 34:5; Rom 9:15","MozV 4:12; Yoh 1:18; TimI 6:16"]', NULL),
  (3454319, 'OT', 'Moze II', 33, 23, 'Ba na uböda dangagu, ba ö''ila gerogu; ba bawagu, ba tebai ifaigi niha.', '["Faigi 34:5; Rom 9:15","MozV 4:12; Yoh 1:18; TimI 6:16"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 1, 'Ba imane Yehowa khö Moze: Toto khöu gara wanura, dua görö, si mane mege, ba usura ba gara andrö goroisa andrö, si so ba gara mege, nirasamö.[1]', '["Faigi 32:19"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 2, 'Ba fa''anö''ö, ba we''amöi ba hili yaŵa, mahemolu, si hulö wongi, ba döna-döna ndra''o ba da''ö, ba zuzu hili.', '["Faigi 32:19"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 3, 'Ba lö tola möi awöu ha niha, ba we''amöi miyaŵa, ba lö tola oroma niha ba gahe hili, fasui; ba he biri-biri ba saŵi, ba lö tola mangalui gö heza, ba zahatö ba hili andre.', '["Faigi 32:19"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 4, 'Ba itoto gara wanura, dua görö, si mane mege. Ba mahemolu ö, ba ihulö wongi wemaoso Moze, möi ia miyaŵa, ba hili Zina''i andrö, i''o''ö niŵa''ö Yehowa khönia, i''ohe gara andrö, si dua görö.', '[]', NULL),
  (3454521, 'OT', 'Moze II', 34, 5, 'Ba möi mitou Yehowa, ba lawuo, i''agö ngainia ba itötöi döi Yehowa.[2]', '["Faigi 33:19","MozIV 14:18; Neh 9:17; Sin 86:5; Sin 103:8","Faigi 20:5; Yer 32:18"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 6, 'Ba me itörö fönania Yehowa, ba imane: Yehowa, Lowalangi sahakhö tödö Yehowa ba si no ebua tödö, ba sebolo tödö ba si no fahöna fa''aböwö, awö wa lö faröi ia,[3]', '["Faigi 33:19","MozIV 14:18; Neh 9:17; Sin 86:5; Sin 103:8","Faigi 20:5; Yer 32:18"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 7, 'sebua tödö ba ngahönö nga''ötö ba same''e aefa sala ba olalöŵa ba horö, ba lö''ö sa taŵa''ö, lö''ö manö fotu; lalö ndra ama, ba ihuku ba ndraono ba ba ma''uwu, ikhamö tölu, irege öfa nga''ötö.[4]', '["Faigi 33:19","MozIV 14:18; Neh 9:17; Sin 86:5; Sin 103:8","Faigi 20:5; Yer 32:18"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3454521, 'OT', 'Moze II', 34, 8, 'Ba i''alio''ö Moze ifaöndrö ia tou ba danö, ifalögu tou ia,', '["Sin 33:12; Sakh 2:12"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 9, 'ba imane: He So''aya! na no atö usöndra wa''ebua dödö khöu, ba iagö hunöma ba wofanöma! Sabe''e börö du''i sa ira, ba be''e aefa khöma lalöma, awö horöma ba halö tana khöu ndra''aga![5]', '["Sin 33:12; Sakh 2:12"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 10, 'Ba imane Yehowa: Hiza uhonogöi ba zi so banuau andrö fefu: ufazökhi dandra, si lö murai mulau ba guli danö ma''asagörö, ba niha bö''ö fefu, ba la''ila dania wolau Yehowa banuau andrö fefu, si so ya''ugö ba hunö; sahöli-höli dödöda sa nilaugu khöu dania![6]', '["MozV 5:2"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 11, 'O''ö niŵa''ögu khöu ma''ökhö; da''utimba fönau Ndraono Gamori ba Dawa Gana''ana ba Iraono kheti ba Iraono Weresi ba Iraono Yebusi.', '["Faigi 23:32","Faigi 23:24; MozV 7:5"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 12, 'Angelama, fa böi fawu''u li ndra''ugö ba niha ba danö andrö, nirugimö dania; ma dania tobali tandraŵa ira ba ngaimi.[7]', '["Faigi 23:32","Faigi 23:24; MozV 7:5"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 13, 'Midudugö naha wame''e sumange andrö khöra, mirasa harefara ba mi''obö geu ni''amoni''ö andrö khöra.[8]', '["Faigi 23:32","Faigi 23:24; MozV 7:5"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 14, 'Ba böi angalulu ba Lowalangi bö''ö; solohu döi Yehowa, Lowalangi solohu ia.[9]', '["Faigi 20:5"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 15, 'Na fawu''u li ndra''ugö ba niha ba danö andrö, ba na lakaoni ndra''ugö, na mame''e adu ira, na lafosumange Lowalangira, ba ahatö khömi wa''elungu, wemanga gö nadu andrö.[10]', '["MozIV 25:1,2; KorI 8:7; 10:21"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 16, 'Ba ma mihalö göi dania donga nonomi matua nonora alawe, ba na mame''e adu nonora, wamosumange Lowalangira, ba lafaelungu göi ndraonomi, ba wame''e adu andrö.', '["MozIV 25:1,2; KorI 8:7; 10:21"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 17, 'Böi fazökhi khöu wamaedo Lowalangi nifahele.[11]', '["Faigi 20:23"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 18, 'Owasa roti si lö mu''aisöni andrö,[12] ba böi olifu''ö; fitu ngaluo wa''ara ö''a roti si lö mu''aisöni, ö''o''ö niŵa''ögu khöu, na baŵa Abibi; me no ba mbaŵa Abibi aheta''ö ba danö Miserayi.[13]', '["Ayati 18—26: Faza 23:14—19","Faigi 12:18"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 19, 'Fefu zi a''a ba wa''atumbu, ba khögu, he uriföu fefu, motöi matua ono si a''a ba zaŵi ba ba mbiri-biri[14]', '["Faigi 13:2","Faigi 13:13; 23:15"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 20, 'Ba ono si a''a ba galide ba öhöli biri-biri; ba na lö omasi''ö öhöli, ba öfatö mbaginia. Fefu nono si a''a khöu, ba öhöli; ba khögu, ba böi möi lö ba danga.[15]', '["Faigi 13:2","Faigi 13:13; 23:15"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 21, 'Önö ngaluo wa''ara, ba hana na öhalö-halö halöŵö, ba na luo si fitu, ba molombase ndra''ugö; he na baŵa wamaku ba he na baŵa wamasi, ba molombase''ö.[16]', '["Faigi 20:9"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 22, 'Ba owasa fendrakose andrö, ba ölau, owasa wamasi gandru sahulö, ba owasa wamasi ba wasulöna ndröfi.[17]', '["Faigi 23:16","Faigi 23:17"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 23, 'Medölu zi döfi ndramu''oroma''ö ira föna Zo''aya, Yehowa, Lowalangi Ndraono Gizeraeli, dozi motöi matua ba khömi.[18]', '["Faigi 23:16","Faigi 23:17"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 24, 'Utimba sa fönau soi niha andrö, ba ebolo danöu ube''e, ba lö tola i''isö niha bö''ö danö andrö khöu, fatua möi misi yaŵa ndra''ugö, ba wangoroma''ö ya''ugö föna Lowalangiu Yehowa, si medölu zi döfi.', '["Faigi 23:16","Faigi 23:17"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 25, 'Böi orudugö ba roti si no mu''aisöni ndro zumange andrö khögu, ba sumange andrö ba gowasa fasa, ba tenga nibe''e yaŵa irege mahemolu.[19]', '["Faigi 23:18","Faigi 23:19"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 26, 'Bua zahulö ba danö khöu, ba ö''ohe ba nomo Lowalangiu Yehowa. Ono mbiri-biri andrö, ba böi rino ba nösi zusu ninania.[20]', '["Faigi 23:18","Faigi 23:19"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 27, 'Ba imane Yehowa khö Moze: Tanö ba zura khöu goroisa andrö. Tandrösa wawu''usa ligu khöu ba ba Ndraono Gizeraeli sa goroisa andrö.', '[]', NULL),
  (3454521, 'OT', 'Moze II', 34, 28, 'Ba öfa wulu ngaluo ba öfa wufu mbongi wa''arania ba da''ö khö Yehowa; lö manga ia ba lö ibadu hadia ia. Ba itanö ba zura goroisa ba wawu''usa li andrö, oroisa si fulu andrö, isura ba gara andrö.[21]', '["Faigi 24:18; 31:18"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 29, 'Ba me möi mitou Moze moroi ba hili Zina''i, ba so ba dangania zura goroisa andrö, si dua görö; ba lö i''ila, wa no tobali sihaga guli mbawania, ba wahuhuosania khö Yehowa.[22]', '["KorII 3:7"]', NULL),
  (3454521, 'OT', 'Moze II', 34, 30, 'Ba me la''ila A''aroni ba Iraono Gizeraeli fefu mbawa Moze, wa no sihaga, ba ata''u ira lahatö''ö ira khönia.', '[]', NULL),
  (3454521, 'OT', 'Moze II', 34, 31, 'Ba humede khöra Moze, ba lafuli la''otahögö ia, he A''aroni ba he satua mbanua fefu; ba fahuhuo khöra Moze.', '[]', NULL),
  (3454521, 'OT', 'Moze II', 34, 32, 'Awena la''ondrasi ia Iraono Gizeraeli fefu. Ba i''ombakha''ö khöra goroisa andrö fefu, ni''oroi''ö Yehowa khönia ba hili.', '[]', NULL),
  (3454521, 'OT', 'Moze II', 34, 33, 'Ba me no i''o''ozui Moze huhuonia khöra, ba ifobalu-balu mbawania.', '[]', NULL),
  (3454521, 'OT', 'Moze II', 34, 34, 'Ba ero na i''ondrasi Yehowa Moze, ba wahuhuosa khönia, ba iheta mbalu-balu andrö, irege möi ia baero, ba ifa''ema ba Ndraono Gizeraeli hadia niŵa''ö khönia.', '[]', NULL),
  (3454521, 'OT', 'Moze II', 34, 35, 'Ba ero na si manö, ba la''ila Iraono Gizeraeli, wa no sihaga guli mbawa Moze. Ba ifuli dania ifobalu-balu mbawania Moze, irege möi ia bakha zui, ba wahuhuosa khö Yehowa.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 1, 'Ba ifalukha''ö mbanua Ndraono Gizeraeli fefu Moze ba imane khöra: Da''ö ni''oroi''ö Yehowa nilau:', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 2, 'Önö ngaluo, ba tola mohalöŵö, ba luo si fitu andrö, ba mi''amoni''ö, baŵa ni''amoni''ö khö Yehowa, salösu lö mohalöŵö ami. Dozi sangai halöŵö na luo da''ö, ba nibunu.[1]', '["Faigi 20:8"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 3, 'Na luo sabato andrö, ba lö tola mi''ebua''ö galitö ba nahiami andrö, fefu.', '["Faigi 20:8"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 4, 'Ba humede na Moze ba mbanua Ndraono Gizeraeli fefu imane:', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 5, 'Da''ö ni''oroi''ö Yehowa:', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 6, 'ba ungu sowu waru-waru ba soyo ba kirimisi ba tarafali ba bu nambi', '["Faigi 25:2"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 7, 'ba uli mbiri-biri si matua nilau soyo ba uli guaza mina ba eu bana', '["Faigi 25:2"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 8, 'ba fanikha wandru ba remba-remba ba wanikha famayoini andrö ba ba nitunu,', '["Faigi 25:2"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 9, 'samohua, ba feremata una ba feremata nitagu ba nono mbaru ba doto andrö ba ba mbola waetasa andrö.', '["Faigi 25:2"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 10, 'Ba dozi ba khömi si so fa''atuka, ba ndramufa''aso ira ba ndramulau fefu hadia ia niŵa''ö Yehowa.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 11, 'Ose andrö,[3] fabaya ba''a-ba''a andrö khönia, kulambu ba sagönia andrö ba khai-khai andrö khönia ba fafa ba lazi ba taru nahe andrö, fabaya ahe, ba tawöla andrö,', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 12, 'fabaya hea-heania ba lagö-lagö ba kulambu andrö, fomba''a;', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 13, 'ba meza andrö, fabaya hea-heania, awö wakakenia fefu, awö roti andrö, nifaigi-faigi;', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 14, 'awö naha wandru andrö, fabaya fakake khönia ba fandrunia ba fanikha wandru,', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 15, 'awö naha wanunu kumöyö, fabaya hea-heania ba fanikha famayoini andrö, awö nitunu andrö, samohua, ba kulambu andrö, ba''a-ba''a mbawandruhö nose,', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 16, 'awö naha wanunu sumange andrö, fabaya taralinia, töla, ba hea-heania ba fakake andrö khönia, fefu, awö gala andrö,', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 17, 'fabaya ahenia, ba ba''a-ba''a golayama ba taru nahe andrö khönia, fabaya ahe, ba ba''a-ba''a mbawa göli golayama,', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 18, 'ba osö-osö nose andrö ba osö-osö ba golayama, fabaya sinali andrö, awö nukha andrö,', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 19, 'nihaogö sibai fanoso, nukha ba halöŵö andrö, ba ni''amoni''ö, nukha ni''amoni''ö andrö khö Ga''aroni ere andrö, awö nukha nononia ba halöŵöra, halöŵö gere.', '["Ayati 11–19: Faza 31:7–11"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 20, 'Ba mofanö Ndraono Gizeraeli fefu, laröi Moze.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 21, 'Ba dozi si terou tödö, dozi saoha ölö, ba möi mame''e bobotolö andrö khö Yehowa, ba wamazökhi ose wama''ele''ö andrö ba soguna ba halöŵö andrö bakha, ba ba nukha ni''amoni''ö andrö.', '["Faigi 29:24"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 22, 'Ba la''ohe — he ira matua ba he ira alawe — dozi si no terou tödö, ba famakhai mbaru ba saeru dalinga, ba laeduru ba aya, awö ngawalö gana''a si no awai; ba awö dozi si no mangohonogöi fame''e ame''ela ana''a khö Yehowa.[4]', '["Faigi 29:24"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 23, 'Ba dozi si so ungu sowu waru-waru ba soyo ba kirimisi ba tarafali ba bu nambi ba uli mbiri-biri si matua, nilau soyo, ba uli guaza mina, ba la''ohe.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 24, 'Ba dozi sedöna mame''e bobotolö firö ba töla, ba labe''e mbobotolö andrö khö Yehowa, ba dozi si so eu bana, ni''oguna''ö ba wamazökhi hadia ia, fefu, ba la''ohe.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 25, 'Ba ira alawe fefu, si so fa''atuka ba mogadi, tangara, ba la''ohe mbana andrö: ungu sowu waru-waru ba soyo ba kirimisi ba tarafali.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 26, 'Ba dozi ira alawe si terou tödö, ba wa''atukara andrö, ba mogadi bu nambi.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 27, 'Ba satua, ba la''ohe weremata una ba feremata bö''ö andrö, nitagu ba nono mbaru ba doto andro ba ba mbola waetasa andrö.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 28, 'Ba remba-remba andrö ba fanikha ba wandru ba ba wanikha famayoini andrö ba nitunu andrö, samohua.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 29, 'Dozi ira matua ba dozi ira alawe, si terou tödö, ba wolohe, ba nifazökhi andrö, ni''oroi''ö Yehowa famazökhi, khö Moze — la''ohe ame''ela saoha gölö khö Yehowa Iraono Gizeraeli.', '[]', NULL),
  (3454970, 'OT', 'Moze II', 35, 30, 'Ba imane Moze ba Ndraono Gizeraeli:[5] Hiza, no itötöi Yehowa döi Mbesale''eli andrö, ono Guri, ma''uwu Huri, mado Yuda,[6]', '["Ayati 30–35: Faza 31:1–6","Faigi 31:2"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 31, 'ba no ihöna khönia Geheha Lowalangi ba fa''atuka ba fa''aboto ba dödö ba fangila, awö ngawalö wa''onekhe,', '["Ayati 30–35: Faza 31:1–6","Faigi 31:2"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 32, 'ba wangalui nekhe-nekhe, ba wolau ya''ia, he ana''a ba he firö ba he töla,', '["Ayati 30–35: Faza 31:1–6","Faigi 31:2"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 33, 'ba he ba wolau ba weremata nifa''oli, ba he ba wolau ba geu, ba wamazökhi ngawalö nekhe-nekhe danga fefu.', '["Ayati 30–35: Faza 31:1–6","Faigi 31:2"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 34, 'Ba he fa''onekhe ba wamahaö, ba no ibe''e khönia, khönia ba khö Goholiabi andrö, ono Gahizamakhi, mado Dano.[7]', '["Faigi 31:6"]', NULL),
  (3454970, 'OT', 'Moze II', 35, 35, 'No ihöna khöra wa''atuka, ba wolau ngawalö halöŵö andrö, nifolau ziambu ba tuka geu ba tuka wanoso ba sanoso nifola''a-la''a, ungu sowu waru-waru ba soyo ba kirimisi ba tarafali, nifolau zanoso; ba wangasiwai halöŵö andrö, fefu ba ba wangalui nekhe-nekhe.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 1, 'Ba mohalöŵö ndra Besale''eli Oholiabi, awö dozi si so fa''atuka, nibe''e Yehowa fa''onekhe ba fa''aboto ba dödö, tobali la''ila mu''asiwai; lalau fefu hadia ia zoguna ba wamazökhi ni''amoni''ö andrö.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 2, 'Ba ifakaoni''ö Moze ndra Besale''eli Oholiabi, awö dozi si so fa''atuka, nibe''e Yehowa fa''onekhe, dozi si no terou tödö ba wangai halöŵö andrö, ba wangasiwai ya''ia.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 3, 'Ba latema khö Moze mbobotolö andrö fefu, nibe''e Ndraono Gizeraeli ba wangasiwai halöŵö andrö, ba wolau ni''amoni''ö andrö. Ba lö labato-bato wolohe khönia na, saoha gölö, ero mahemolu mbanua.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 4, 'Ba dozi ndra tuka, solau halöŵö andrö fefu, ba ni''amoni''ö andrö, ba oi zara laböhöli halöŵöra ni''ohalöŵögöira,', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 5, 'ba lamane khö Moze: Lö ahori moguna ba wolau niŵa''ö Yehowa andrö ni''ohe zato!', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 6, 'Ba ifaŵa''ögö ba golombaseŵa Moze, imane: Böi sa''ae yamulau hadia ia mbobotolö ba ni''amoni''ö andrö ha niha, he ira matua ba he ira alawe! Ba tobali tetenaŵa niha zato, fa böi sa''ae la''ohe game''ela.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 7, 'Noa sa irugi, no töra na''i khöra omböila, wangasiwai nilau andrö fefu.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 8, 'Ba lalau sa''ae nose andrö,[1] fulu nga''örö kulambu, dozi si so fa''atuka ba zohalö-halöŵö andrö; tarafali bana gulambu andrö ba ungu sowu waru-waru ba soyo ba kirimisi, nilalau kerubi, nifolau duka wanoso, wamazökhinia ya''ia,[2]', '["Ayati 8–19: Faza 26:1–14","Faigi 26:1"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 9, '28 hela wa''anau zi sagörö kulambu ba 4 hela wa''ebolo — fagölö-gölö wa''ebua gulambu andrö fefu.', '["Ayati 8–19: Faza 26:1–14","Faigi 26:1"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 10, 'Lima-lima nga''örö kulambu ifatagu; ba awena ifotumbo zinga', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 11, 'zi sagörö kulambu andrö, ba wondrege zi sandroro andrö, tumbo ungu sowu waru-waru, ba si manö zinga gulambu ba wondrege zi sandroro.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 12, '50 dumbo ibe''e ba gulambu zi sagörö ba 50 göi ba zinga zi sagörö, si faböbö ba zi sandroro andrö; si fatahö sibai dumbo andrö ibe''e.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 13, 'Ba ifazökhi khai-khai ana''a ba ifakhai gulambu andrö khai-khai andrö, tobali ha sambua nose andrö.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 14, 'Ba ilalau dufo bu nambi, sagö nose, felezara nga''örö tufo ilalau ba da''ö.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 15, '30 hela wa''anau zagörö ba 4 hela wa''ebolo; fagölö-gölö wa''ebua zi 11 nga''örö tufo andrö.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 16, '5 nga''örö dufo andrö ifatagu, idoro, ba sandroro göi zi 6 nga''örö andrö.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 17, 'Ba ifotumbo zinga ba wondrege zi sandroro, 50 dumbo, ba 50 göi dumbo ba zinga dufo ba wondrege zi sandroro.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 18, 'Ba 50 ifazökhi khai-khai töla, ba wama''anö sagö andrö, ena''ö ha sandroro.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 19, 'Ba ifazökhi na mbalu-balu zagö andrö, uli mbiri-biri si matua nilau soyo, ba sagörö tö mbalu-balu da''ö, uli guaza mina.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 20, 'Ba ilau wafa andrö, döla-döla nose, nifasindro, bana.[3]', '["Ayati 20–30: Faza 26:15–25"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 21, '10 hela wa''anau zagörö ba sahela a matonga wa''ebolo.', '["Ayati 20–30: Faza 26:15–25"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 22, 'Ba sagörö fafa ba dua mba''iba''i si faböbö; si manö wolau fafa nose andrö fefu.', '["Ayati 20–30: Faza 26:15–25"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 23, 'Ba nilaunia fafa nose, ba 20 nga''örö fafa tanö miraya —', '["Ayati 20–30: Faza 26:15–25"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 24, 'Ba 40 ibe''e ahe zi 20 nga''örö fafa, ahe firö, dua-dua gahe zagörö fafa, ba mba''iba''i no mege, si dua-dua —', '["Ayati 20–30: Faza 26:15–25"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 25, 'si manö göi ba ngai nose tanö yöu, 20 nga''örö fafa, awö gahe firö andrö,', '["Ayati 20–30: Faza 26:15–25"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 26, 'si 40, dua-dua gahe zagörö fafa.', '["Ayati 20–30: Faza 26:15–25"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 27, 'Ba nibe''e tanö ba gaekhula luo, ba 6 nga''örö fafa ilau.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 28, 'Ba 2 görö fafa ilau, nibe''e ba watalinga nose, tanö furi.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 29, 'Dua winaeta da''ö, i''otarai moroi tou, ba nifa''anö si yaŵa, tumbo ni''ogaolö. Si manö wolaunia ba watalinga andrö, si dua; tobali 8 nga''örö fafa,', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 30, 'fabaya ahe firö andrö — 16 gahe, dua-dua gahe zagörö fafa.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 31, 'Ba 5 ifazökhi lazi, bana, ba wafa andrö ba ngai nose,[4]', '["Ayati 31–34: Faza 26:26–30"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 32, 'ba 5 göi lazi ba wafa ba zi tambai, ba 5 ba wafa ba hambo nose, tanö ba gaekhula luo.', '["Ayati 31–34: Faza 26:26–30"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 33, 'Ba lazi ba dalu andrö, ba ba dalu wafa ifatörö, adölö manö ma''asandroro.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 34, 'Ba fafa andrö, ba ifo''uli ana''a: ba tumbo andrö göi, lala lazi, ba ana''a ibe''e, ba lazi, ba ifo''uli ana''a.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 35, 'Ba ifazökhi mba''a-ba''a andrö,[5] ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana, nifolau duka wanoso wamazökhinia ya''ia, nilalau kerubi.[6]', '["Ayati 35–38: Faza 26:31–37","Faigi 26:31"]', NULL),
  (3455713, 'OT', 'Moze II', 36, 36, 'Ba 4 ifazökhi khönia taru nahe, bana, ba ifo''uli ana''a; ana''a göi gosö-osönia; ba 4 ifahele ahe da''ö, firö.', '[]', NULL),
  (3455713, 'OT', 'Moze II', 36, 37, 'Ba ifazökhi mba''a-ba''a mbawandruhö nose, ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana, nifolau zanoso sola''a-la''a,[7]', '["Faigi 26:36"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3455713, 'OT', 'Moze II', 36, 38, 'fabaya taru nahe andrö khönia, si lima, ba osö-osönia: högö ba tumbo ni''ogaolo andrö khönia, ba ifo''uli ana''a; ba ahe andrö si lima, ba töla ibe''e.', '["Faigi 26:36"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 1, 'Ba ifazökhi dawöla andrö Besale''eli, bana geunia;[1] 2 hela a matonga wa''anau ba sahela a matonga wa''ebolo ba sahela a matonga wa''alaŵa.[2]', '["Ayati 1–9: Faza 25:10–22","Faigi 25:10"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 2, 'Ba ifo''uli si ndruhu mbalaki, tanö bakha ba tanö baero, ba ifosinga ana''a, fasui.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 3, 'Ba öfa ifahele khönia tumbo ni''ogaolo, ba gahenia si öfa, dombu-dombua fatambai.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 4, 'Ba ifazökhi hea-hea, bana, ba ifo''uli ana''a;', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 5, 'ba hea-hea andrö, ba ifatörö ba dumbo no mege, fatambai dawöla, ba wamahea tawöla.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 6, 'Ba ifazökhi lagö-lagö, si ndruhu mbalaki, 2 hela a matonga wa''anau ba sahela a matonga wa''ebolo.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 7, 'Ba ifazökhi göi gerubi, dombua, ana''a; niböbözi wamazökhi ya''ia, ba faföfö lagö-lagö andrö ibe''e,', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 8, 'sambua-sambua faföfö, ba dete lagö-lagö ibe''e gerubi andrö, faoma faföfö.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 9, 'Ba kerubi andrö, ba samologö miyaŵa afira, wamalugö lagö-lagö afira, faoma la''otahögö nawöra; lagö-lagö andrö la''otahögö kerubi andrö.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 10, 'Ba ifazökhi meza andrö,[3] bana geunia, 2 hela wa''anau ba sahela wa''ebolo ba sahela a matonga wa''alaŵa.[4]', '["Ayati 10–16: Faza 25:23–29","Faigi 25:23"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 11, 'Ba ifo''uli si ndruhu mbalaki ba ifosinga ana''a, fasui.', '["Ayati 10–16: Faza 25:23–29","Faigi 25:23"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 12, 'Ba ifolambe-lambe na göi, lalu''a wa''ebolo fasui; ba lambe-lambe andrö, ba ifosinga zui ana''a, fasui.', '["Ayati 10–16: Faza 25:23–29","Faigi 25:23"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 13, 'Ba öfa ifahele khönia tumbo ni''ogaolo, ana''a, ba ba watalingania ifakhai dumbo andrö, ba gahenia si öfa.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 14, 'Si fadege ba lambe-lambe no mege dumbo andrö, ba nifatörö hea-hea, ba wamahea meza andrö.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 15, 'Ba hea-hea andrö, ba bana ibe''e, ba ifo''uli ana''a, ba wamahea meza andrö.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 16, 'Ba ifazökhi wakake andrö ba meza, mako andrö khönia ba figa ba mako ba wamadu ba kundri, fame''e zumange nibadu andrö, si ndruhu mbalaki manö, fefu.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 17, 'Ba ifazökhi naha wandru andrö,[5] si ndruhu mbalaki. Niböbözi wamazökhi naha wandru andrö ahenia ba tölania; ba tebe''e ni''obene mbunga andrö — ulu-ulu sawena aboto[6] —', '["Ayati 17–24: Faza 25:31–39","Faigi 25:31"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 18, 'Ba önö zi otarai ngainia daha, tölu-tölu fatambai naha wandru.', '["Ayati 17–24: Faza 25:31–39","Faigi 25:31"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 19, 'Ba sara daha, ba tölu ni''obene mbunga, si hulö mbene mbowo kanari, sambu-sambua mbene, sawena aboto. Si manö ba ndraha andrö fefu, si önö, si otarai naha wandru andrö.', '["Ayati 17–24: Faza 25:31–39","Faigi 25:31"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 20, 'Ba ba döla naha wandru, ba 4 ni''obene mbunga, si hulö mbene mbowo kanari, si so ulu-ulu ba bowo,', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 21, 'sambu-sambua mbene tou zi medölu wa dua khönia, — daha si önö andrö, si otarai ia.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 22, 'Bene andrö khönia ba daha andrö, ba ha sara, niböbözi fefu, ha sandroro, si ndruhu mbalaki.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 23, 'Ba fitu ifazökhi fandru khönia, fabaya guti andrö ba sife andrö khönia, si ndruhu mbalaki.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 24, 'Otu a dua wulu balaki i''oguna''ö si ndruhu mbalaki, wamazökhi ya''ia, fabaya gama-gamania no mege.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 25, 'Ba ifazökhi naha wanunu kumöyö andrö,[7] bana geunia, sahela wa''anau ba sehela wa''ebolo, si öfa sagi, ba 2 hela wa''alaŵa, ba si fadoro khönia dandrunia andrö.', '["Ayati 25–28: Faza 30:1–5"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 26, 'Ba ifo''uli si ndruhu mbalaki mezania awö ngainia, fasui, ba tandrunia, ba ifosinga ana''a, fasui.', '["Ayati 25–28: Faza 30:1–5"]', NULL),
  (3457065, 'OT', 'Moze II', 37, 27, 'Ba tou zinga andrö, ba ifotumbo ni''ogaolo, dombua, ba watalingania si dombua, ba faoma fatambai zi manö, ba nifatörö hea-hea andrö, ba wamahea ya''ia ba da''ö.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 28, 'Ba hea-hea andrö, ba bana ibe''e ba ifo''uli ana''a.', '[]', NULL),
  (3457065, 'OT', 'Moze II', 37, 29, 'Ba ifazökhi wanikha famayoini andrö ni''amoni''ö, awö nitunu andrö samohua, si lö si fabaya, nifolau zamaruka dalu-dalu nigule''ö.[8]', '["Faigi 30:25,35"]', NULL),
  (3458730, 'OT', 'Moze II', 38, 1, 'Ba ifa''anö naha wame''e sumange nitunu andrö,[1] bana geunia; 5 hela wa''anau ba 5 hela wa''ebolo, si öfa sagi, ba tölu hela wa''alaŵa.', '["Ayati 1–7: Faza 27:1–8"]', NULL),
  (3458730, 'OT', 'Moze II', 38, 2, 'Ba tandrunia, ba ba watalingania si öfa ibe''e, tobali si fadoro khönia dandrunia andrö, ba ifo''uli töla.', '["Ayati 1–7: Faza 27:1–8"]', NULL),
  (3458730, 'OT', 'Moze II', 38, 3, 'Ba ifazökhi wakake fefu, soguna ba naha wame''e sumange andrö, bowoa ba sundru-sundru ba figa ba garafu ba gali; fefu wakakenia, ba töla ibe''e.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 4, 'Ba ifotarali naha wame''e sumange andrö, ni''o''u''ö, töla, tou lambe-lambenia, irugi dalu wa''alaŵania.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 5, 'Ba öfa ifahele tumbo ni''ogaolo, nibe''e ba watalinga darali töla andrö, si öfa, ba nifatörö hea-hea.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 6, 'Ba hea-hea andrö, ba bana ibe''e, ba ifo''uli töla.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 7, 'Ba ifatörö ba dumbo no mege hea-hea andrö, fatambai naha wame''e sumange, ba wamahea, ya''ia. Fafa döladölania, tobali mo''arö, wamazökhinia ya''ia.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 8, 'Ba ifazökhi gala andrö, töla, ba ahenia töla, sörömi ndra alawe, sangai-ngai halöŵö, si so halöŵö ba zinga mbawandruhö nose wama''ele''ö.[2]', '["Faigi 30:18"]', NULL),
  (3458730, 'OT', 'Moze II', 38, 9, 'Ba ifazökhi golayama tanö raya,[3] ba da''ö ibe''e gulambu ba''a-ba''a golayama andrö tarafali bana, otu hela wa''anau,[4]', '["Ayati 9–20: Faza 27:9–19","Faigi 27:9"]', NULL),
  (3458730, 'OT', 'Moze II', 38, 10, 'ba 20 daru nahe, fabaya ahe töla, 20 — ba osö-osö ba daru nahe andrö ba tumbo ni''ogaolo andrö khönia, ba firö.', '["Ayati 9–20: Faza 27:9–19","Faigi 27:9"]', NULL),
  (3458730, 'OT', 'Moze II', 38, 11, 'Ba tanö yöu, ba otu hela göi wa''anau [mba''a-ba''a], ba 20 daru nahe, fabaya ahe töla, 26 — ba osö-osö ba daru nahe andrö ba tumbo andrö khönia, ba firö.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 12, 'Ba tanö ba gaekhula luo, ba 50 hela mba''a-ba''a ba fulu daru nahe, awö gahe, fulu; ba osö-osö ba daru nahe andrö ba tumbo andrö khönia, ba firö.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 13, 'Ba tanö ba gatumbukha, ba 50 hela,', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 14, 'ba''a-ba''a si 15 hela ba zi tambai, ba tölu daru nahe, fabaya ahe,', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 15, 'ba si manö ba zi tambai: 15 hela mba''a-ba''a, ba tölu daru nahe, fabaya ahe; faoma fatambai mbawa göli ba golayama.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 16, 'Fefu mba''a-ba''a golayama, fasui, ba tarafali bana,', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 17, 'ba ahe daru nahe andrö, ba töla, ba osö-osö, ba firö, ba uli högö, ba firö; ba fefu daru nahe ba golayama, ba nifotumbo firö.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 18, 'Ba ba''a-ba''a mbawa göli ba golayama, ba no nifolau zanoso sola''a-la''a, ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana, 20 hela wa''anau ba 5 hela wa''alaŵa, fa''ebolonia, dali mba''a-ba''a golayama andrö.[5]', '["Faigi 27:16"]', NULL),
  (3458730, 'OT', 'Moze II', 38, 19, 'Ba taru nahe andrö, si öfa, fabaya ahe si öfa, ba töla, ba osö-osö, ba firö, ba si manö guli högö, ba tumbo andrö khönia, ba firö.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 20, 'Ba fefu daru-taru ba nose ba ba golayama, fasui, ba töla.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 21, 'Ba da''e wangerai balazo nose andrö, ose zura goroisa, niŵa''ö Moze fangerai, folau nono Lewi andrö, högö Gitamari, ono Ga''aroni, ere andrö.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 22, 'Ba Besale''eli andrö, ono Guri, ma''uwu Huri, mado Juda, zamazökhi fefu hadia ia, niŵa''ö Yehowa khö Moze,', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 23, 'ba awönia Goholiabi, ono Gahizamakhi, mado Dano, da''ö ziambu ba tuka geu, ba tuka wanoso ba sanoso sola''a-la''a, ungu sowu waru-waru ba soyo ba kirimisi ba tarafali.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 24, 'Ba ana''a andrö fefu, ba wolau ya''ia, ba nifazökhi andrö fefu, ba wolau ni''amoni''ö andrö, ana''a nifalau, ame''ela ni''amoni''ö, ba no 77.408 balaki ba zaga ni''amoni''ö.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 25, 'Ba firö nibe''e, ba wangofaya banua, ba 301.775 ba rufia, ba zaga ni''amoni''ö;', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 26, 'sasuku zamösa, dozi ni''ofaya andrö, si 20 fakhe ba si a''a moroi andrö, 603.550 ira.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 27, 'Si 300.000 rufia fa''abua firö, ba la''oguna''ö ba wamahele ahe ni''amoni''ö andrö, fabaya ahe mba''a-ba''a andrö 300.000 ba rufia, ba gahe andrö si otu, 3000 zara ahe.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 28, 'Ba si 1.775 fa''abua, ba i''oguna''ö ba wamazökhi osö-osö andrö ba daru nahe andrö, ba ifo''uli högö ba ifotumbo.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 29, 'Ba töla andrö nifalau, ame''ela ni''amoni''ö, ba 212.400 rufia wa''abua.', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 30, 'Da''ö i''oguna''ö ba wamazökhi ahe mba''a-ba''a ba mbawandruhö nose wama''ele''ö, awö naha wame''e sumange andrö töla, fabaya taralinia andrö töla, awö fefu wakake ba naha wame''e sumange,', '[]', NULL),
  (3458730, 'OT', 'Moze II', 38, 31, 'awö gahe mba''a-ba''a golayama, fasui, ba ahe mba''a-ba''a mbawa göli ba golayama, fabaya taru-taru andrö ba nose ba taru-taru ba golayama fefu, fasui.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 1, 'Ba ungu sowu waru-waru ba soyo andrö ba kirimisi andrö,[1] ba labali''ö nukha gere, si no maulu fanoso, nukha ba halöŵö ba ni''amoni''ö andrö; ba lafazökhi nukha ni''amoni''ö andrö khö Ga''aroni, la''o''ö niŵa''ö Yehowa khö Moze.', '["Ayati 1–21: Faza 28:4–30"]', NULL),
  (3462298, 'OT', 'Moze II', 39, 2, 'Ono mbaru ba doto andrö ifazökhi, böna ame ba ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 3, 'Laböbözi gana''a, la''anifi''ö, irege i''ila ikhoi, ibali''ö böna ame, ba wangorudugö da''ö ba ungu sowu waru-waru ba ba ungu soyo ba ba kirimisi ba ba darafali, nifolau duka wanoso.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 4, 'Ba lafobalu-balu galisi, nifaböbö khönia; ba mbalönia si dua tefaböbö:', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 5, 'Ba böbö doto andrö khönia, ba wobaru ya''ia, ba no fadoro khönia, si manö göi wolau, böna ame ba ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 6, 'Ba ifazökhi weremata una andrö, nifosinga kawa ana''a ba nisua, nifolau duka dandro, dali döi Ndraono Gizeraeli.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 7, 'Ba ifakhai ba mbalu-balu galisi andrö ba nono mbaru ba doto, feremata famasugi ba dödö Yehowa Ndraono Gizeraeli, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 8, 'Ba ifazökhi mbola andrö, nifolau duka wanoso, si mane folau ono mbaru ba doto, böna ame ba ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 9, 'Si öfa sagi ia; dua winaeta labe''e mbola andrö, lalulalu''a wa''anau, nifodua winaeta.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 10, 'Ba öfa ngenoli latagu khönia feremata: sambua weremata aki ba sambua weremata sabarazadi ba sambua weremata zumurudi nifa''oli ba ngenoli si sara.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 11, 'Ba ba ngenoli fanete da''ö, ba sambua weremata manika ba sambua weremata nila ba sambua weremata ita.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 12, 'Ba fanete da''ö, ba sambua weremata fusifaraga ba sambua mbatu siabu ba sambua weremata mariti.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 13, 'Ba fanete da''ö, ba sambua weremata firusa ba sambua weremata una ba sambua weremata yasia; da''ö nitagu khönia, nifasui singa kawa ana''a nilalau.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 14, 'Ba dali döi Ndraono Gizeraeli, wa 12 weremata; dali döira, sambu-sambua lasua yaŵa töi zi felendrua tua, nifolau duka dandro.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 15, 'Awena laforaeŵe-raeŵe mbola andrö, ni''osinali, nitali, si ndruhu mbalaki,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 16, 'ba lalalau rendra ana''a, dua, ba tumbo ni''ogaolo, dombua, ba ba watalinga mbola andrö, si dombua lafakhai dumbo andrö.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 17, 'Ba ba dumbo andrö si dombua, ba watalinga mbola, si dombua lafakhai raeŵe-raeŵe andrö, si dua rozi.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 18, 'Ba balö raeŵe-raeŵe andrö, si dua ba ba rendra nilalau andrö, si dua, lafakhai, ba da''ö nifakhai ba mbalu-balu galisi andrö, si dua görö, ba nono mbaru ba doto, tanö fönania.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 19, 'Ba dombua lafazökhi tumbo ni''ogaolo ana''a, nifakhai ba watalinga mbola, si dombua, tanö barö, ba dagu-tagunia, tanö ba nono mbaru.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 20, 'Ba dombua zui lafazökhi tumbo ni''ogaolo nifakhai ba mbalu-balu galisi andrö ba nono mbaru, ba wondrege tou, tanö föna, ba zi fahalö ia, yaŵa mböbö doto ba nono mbaru.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 21, 'Awena lafakhai ba dumbo nono mbaru mbola andrö ba tumbonia sinali ungu sowu waru-waru wamakhai — tobali yaŵa mböbö doto ba nono mbaru si lö liŵa-liŵa, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 22, 'Ba ifazökhi mbaru sebua andrö,[2] awö nono mbaru no mege, nisoso, ungu sowu waru-waru, ma''asagörö.', '["Ayati 22–26: Faza 28:31–35"]', NULL),
  (3462298, 'OT', 'Moze II', 39, 23, 'Ba lala högö ba mbaru sebua andrö, ba si mane lala högö ba göröba, nifasui tagu-tagu, fa böi atika.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 24, 'Ba tagu-tagu ba gahe mbaru sebua andrö, ba lafobua dalimo, ungu sowu waru-waru ba soyo ba kirimisi ba tarafali bana,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 25, 'ba lafazökhi riti-riti, si ndruhu mbalaki, ba lafasolisi ba ni''obua dalimo andrö riti-riti andrö, lafasui gahe mbaru sebua andrö, ba gota''otalua ni''obua dalimo no mege,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 26, 'tobali sambu-sambua riti-riti ba sambu-sambua ni''obua dalimo, si fazoli-zoli ba gahe mbaru sebua andrö, ba wangai halöŵö andrö, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 27, 'Ba lafazökhi gameza andrö,[3] tarafali, khö Ga''aroni ba ba nononia, nisoso,', '["Ayati 27–29: Faza 28:39–42"]', NULL),
  (3462298, 'OT', 'Moze II', 39, 28, 'awö mbala högö andrö, tarafali, ba kofia famoadu andrö, tarafali, ba saraeŵa andrö, tarafali bana,', '["Ayati 27–29: Faza 28:39–42"]', NULL),
  (3462298, 'OT', 'Moze II', 39, 29, 'awö mböbö talu andrö, tarafali bana ba ungu sowu waru-waru ba soyo ba kirimisi, nifolau zanoso sola''a-la''a, si mane niŵa''ö Yehowa khö Moze.', '["Ayati 27–29: Faza 28:39–42"]', NULL),
  (3462298, 'OT', 'Moze II', 39, 30, 'Ba lafazökhi dete mbala högö andrö,[4] diadema ni''amoni''ö, si ndruhu mbalaki, ba lasua yaŵa, nifolau zogao tandro: "Ni''amoni''ö khö Yehowa".[5]', '["Ayati 30–31: Faza 28:36–38","Faigi 28:36"]', NULL),
  (3462298, 'OT', 'Moze II', 39, 32, 'Si manö wangasiwai halöŵö andrö fefu ba nahia ose wama''ele''ö andrö; la''o''ö sibai Iraono Gizeraeli niŵa''ö Yehowa khö Moze — si manö wolaura.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 33, 'Ba la''ohe khö Moze nahia andrö, ose andrö, awö wakake khönia fefu, famakhainia andrö ba fafa ba lazi ba taru nahe, fabaya ahe, ba balu-balu zagö andrö,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 34, 'uli mbiri-biri si matua, nilau soyo ba balu-balu uli guaza mina ba ba''a-ba''a andrö,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 35, 'ba tawöla zura goroisa, fabaya hea-heania ba lagönia, ba meza andrö,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 36, 'awö wakake andrö khönia fefu, awö roti nifaigi-faigi,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 37, 'awö naha wandru andrö, si ndruhu mbalaki, fabaya fandru andrö, nifa''oli khönia, ba fakake khönia, fefu, ba fanikha ba wandru andrö,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 38, 'awö naha wame''e sumange andrö, ana''a, ba fanikha famayoini ba hadia nitunu, samohua, ba''a-ba''a andrö ba mbawandruhö nose,', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 39, 'ba naha wame''e sumange andrö, töla, ba tarali andrö khönia, töla, ba hea-heania ba fakake andrö khönia, fefu, ba gala andrö fabaya ahenia.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 40, 'Ba ba''a-ba''a golayama andrö ba taru nahe khönia, fabaya ahe, ba ba''a-ba''a ba mbawa göli ba golayama ba sinalinia ba taru-taru, ba fakake andrö fefu ba halöŵö andrö ba nahia ose wama''ele''ö andrö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3462298, 'OT', 'Moze II', 39, 41, 'Awö nukha andrö, si no maulu fanoso, ba halöŵö ba ni''amoni''ö andrö, nukha ni''amoni''ö andrö khö Ga''aroni ere andrö, awö nukha ba nononia, ba halöŵöra halöŵö gere.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 42, 'La''o''ö sibai niŵa''ö Yehowa khö Moze Iraono Gizeraeli, wolau da''ö fefu.', '[]', NULL),
  (3462298, 'OT', 'Moze II', 39, 43, 'Ba me i''ila Moze, awai sa''ae khöra halöŵö andrö fefu — si mane niŵa''ö Yehowa wolaura — ba ifahowu''ö ira Moze.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 1, 'Ba humede Yehowa khö Moze, imane:[1]', '["Ayati 1–33: Faza 25–31"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 2, 'Ba desa''a ba mbaŵa si föföna öfa''anö nahia ose wama''ele''ö andrö,[2]', '["Nga''ötII 1:3"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 3, 'ba öbe''e bakha dawöla gamabu''ula li andrö ba öba''a dawöla ba''a-ba''a andrö.', '["Nga''ötII 1:3"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 4, 'Ba öbe''e bakha göi meza andrö ba öbe''e yaŵa nifinaetagö andrö [roti], öfa''anö; ö''ohe bakha naha wandru andrö ba öbe''e yaŵa wandrunia.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 5, 'Ba naha wanunu kumöyö andrö, ana''a, ba föna dawöla zura goroisa öbe''e ba ötaŵi mba''a-ba''a mbawandruhö nose.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 6, 'Ba naha wame''e sumange nitunu, ba ba zinga mbawandruhö ba nahia ose wama''ele''ö öfa''anö,', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 7, 'ba gala andrö, ba ba gotaluara nose wama''ele''ö naha wame''e sumange andrö öbe''e, ba ölau yaŵa nidanö.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 8, 'Ba öfa''anö mba''a-ba''a golayama andrö, fasui, ba ötaŵi mba''a-ba''a mbawa göli ba golayama.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 9, 'Ba öhalö wanikha andrö, famayoini, ba öbayoini nose, awö nösinia fefu, ö''amoni''ö, awö wakake khönia fefu, ena''ö ni''amoni''ö.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 10, 'Ba he naha wame''e sumange nitunu göi, fabaya fakake andrö khönia, fefu, ba öbayoini, ö''amoni''ö naha wame''e sumange andrö, ena''ö ni''amoni''ö sibai.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 11, 'Ba he gala andrö, fabaya ahenia, ba öbayoini ba ö''amoni''ö.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 12, 'Ba öŵa''ö khö Ga''aroni ba ba ndraononia, ndramu''iagö zinga mbawandruhö nose wama''ele''ö, ba öfemondri ira.[3]', '["Faigi 29:4"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 13, 'Ba öfonukha Ga''aroni nukha ni''amoni''ö andrö, öbayoini ia, ö''amoni''ö, ena''ö ihalö halöŵö gere.', '["Faigi 29:4"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 14, 'Ba öŵa''ö ba nononia, ndramu''ondrasi, ba öfobaru ira kameza;', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 15, 'ba öbayoini ira, si mane famayoiniu amara, ena''ö ere ira khögu, ba ba wamayoini andrö tetehe khöra, ere ira, si lö mamalö-malö, götö-götö wa''ara.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 16, 'Ba i''o''ö sibai Moze niŵa''ö Yehowa khönia; si manö wolaunia.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 17, 'Ba desa''a ba mbaŵa si föföna, ba ndröfi si dua tefa''anö nahia andrö.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 18, 'Ifa''anö nahia andrö Moze: ifedadao gahe ba itaru''ö yaŵa wafa andrö, ifa''anö lazi ba ifasindro daru nahe.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 19, 'Ibologö dufo sagö andrö, sagö nose ba ibalugö zagö andrö balu-balu andrö, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 20, 'Awena ihalö zura goroisa ba ibe''e barö dawöla andrö, ifohea-hea dawöla ba ibe''e yaŵa lagö-lagö andrö.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 21, 'Ba i''ohe bakha ba nose dawöla, itaŵi mba''a-ba''a andrö, iba''a dawöla zura goroisa, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 22, 'Ba ibe''e göi ba nose wama''ele''ö meza andrö, tanö yöu, baero mba''a-ba''a andrö.', '["Faigi 25:30"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 23, 'Ba ibe''e yaŵa nifinaetagö andrö [roti], ifa''anö, föna Yehowa, si mane niŵa''ö Yehowa khö Moze.[4]', '["Faigi 25:30"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 24, 'Ba ibe''e göi ba nose wama''ele''ö naha wandru andrö, ba gamaudu meza no mege, tanö raya ba nose,', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 25, 'ba ibe''e yaŵa wandru andrö, föna Yehowa, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 26, 'Ba si manö göi naha wame''e sumange andrö, ana''a, ibe''e ba nose wama''ele''ö, föna mba''a-ba''a andrö,', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 27, 'ba itunu yaŵa zamohua, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 28, 'Ba itaŵi mba''a-ba''a mbawandruhö nose.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 29, 'Naha wame''e sumange nitunu andrö, ba ibe''e ba zinga mbawandruhö nahia ose wama''ele''ö ba ibe''e yaŵa zumange nitunu ba sumange ni''a, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 30, 'Ba gala andrö, ba ibe''e ba gotaluara nose wama''ele''ö naha wame''e sumange andrö, ba ilau yaŵa nidanö, ba wanasa.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 31, 'Ba lasasai ba da''ö dangara ba ahera ira Moze A''aroni ba ononia,', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 32, 'ero na möi ira bakha ba nose wama''ele''ö ba na la''ondrasi naha wame''e sumange lasasai ira, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 33, 'Ba ifasindro mba''a-ba''a golayama, ifasui nose, fabaya naha wame''e sumange andrö, ba itaŵi mba''a-ba''a mbawa göli ba golayama.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 34, 'Ba me no i''asiwai wama''anö Moze, ba ibalugö nose wama''ele''ö lawuo ba anönö nose lakhömi Yehowa.[5]', '["MozIV 9:15; RazI 8:10; Hez 43:5"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 35, 'Ba tebai möi bakha ba nose Moze, me no ibalugö lawuo andrö ba me no anönö nose lakhömi Yehowa.', '["MozIV 9:15; RazI 8:10; Hez 43:5"]', NULL),
  (3462300, 'OT', 'Moze II', 40, 36, 'Ba ero na isaŵa miyaŵa lawuo andrö, moroi ba nose, ba lafazaŵa ira Iraono Gizeraeli; mofanö, götö we''asora ba lala.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 37, 'Ba na lö isaŵa miyaŵa lawuo, ba lö lafazaŵa ira, balazi ifuli isaŵa yaŵa.', '[]', NULL),
  (3462300, 'OT', 'Moze II', 40, 38, 'Na ma''ökhö sa, ba yaŵa nose so lawuo andrö khö Yehowa, ba ba zi bongi, ba mo''alitö ia, anehe Ndraono Gizeraeli fefu, götö we''asora ba lala.[6]', '["Faigi 13:21"]', NULL),
  (3462308, 'OT', 'Moze III', 1, 1, 'Ba humede Yehowa khö Moze, fahuhuo ia khönia, moroi ba nose wama''ele''ö, imane:[1]', '["MozII 29:42"]', NULL),
  (3462308, 'OT', 'Moze III', 1, 2, 'Hede ba Ndraono Gizeraeli ba ŵa''ö khöra: na so ba khömi zame''e sumange Yehowa, ba urifönia ibe''e sumange, saŵi, ba ma urifö side-ide.', '["MozII 29:10"]', NULL),
  (3462308, 'OT', 'Moze III', 1, 3, 'Na saŵi ibe''e sumange nitunu, ba si matua, si lö sala ibe''e. Yamu''ohe ba zinga mbawandruhö nose wama''ele''ö, ena''ö somasi Yehowa ia, ibe''e.[2]', '["MozII 29:10"]', NULL),
  (3462308, 'OT', 'Moze III', 1, 4, 'Ba yamutufa tangania högö zumange andrö, ba ni''omasi''ö ia ba aefa horönia ibe''e.', '["MozII 29:10"]', NULL),
  (3462308, 'OT', 'Moze III', 1, 5, 'Awena dania itaba nono zaŵi andrö, föna Yehowa; ba iraono Ga''aroni, ere andrö, zame''e do andrö. Latefe naha wame''e sumange do andrö fasui, naha wame''e sumange andrö ba zinga mbawandruhö nose.', '["MozII 29:10"]', NULL),
  (3462308, 'OT', 'Moze III', 1, 6, 'Ba ibo''a guli zumange ba itatawi nösi.', '["MozII 29:10"]', NULL),
  (3462308, 'OT', 'Moze III', 1, 7, 'Ba iraono Ga''aroni, ere andrö, zangebua alitö ba dete naha wame''e sumange ba labahogö ba galitö geu nisisila.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 8, 'Ba lahaogö Iraono Ga''aroni, ere andrö, wame''e yaŵa ba mbaho geu andrö ba galitö ba naha wame''e sumange ngawalö andrö, högö ba tawö.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 9, 'Ba alakhaö ba ahe, ba lasasai ba nidanö, ba ifarahugö itunu ba naha wame''e sumange ere sumange nitunu, sumange nibe''e khö Yehowa, nifatörö ba galitö, samohua.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 10, 'Ba na urifö side-ide — ono mbiri-biri, ba ma nambi — zumange andrö, nibe''enia sumange nitunu, ba si matua, si lö sala ibe''e.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 11, 'Yamutaba föna Yehowa yöu naha wame''e sumange; ba iraono Ga''aroni, ere andrö, zanefe naha wame''e sumange do andrö, fasui.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 12, 'Ba itatawi, ba ihaogö ere, wame''e ba mbaho geu andrö ba galitö ba naha wame''e sumange ngawalö andrö, awö högö, awö dawö.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 13, 'Ba alakhaö ba ahe, ba lasasai ba nidanö, ba ifarahugö ere, wame''e ya''ia, itunu ba dete naha wame''e sumange; sumange nitunu ia, sumange nibe''e khö Yehowa, nifatörö ba galitö, samohua.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 14, 'Ba na sumange fofo zumange andrö, nibe''enia khö Yehowa, ba fune ba ma ono marafadi ibe''e sumange.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 15, 'Ba ere zolohe ba naha wame''e sumange, iboto högö ba itunu ba galitö ba naha wame''e sumange, ba do, ba nifera''ö ba ngai naha wame''e sumange.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 16, 'Ba horokina ba bu, ba iheta ba itibo''ö ba niduwagö awu, tanö ba gatumbukha, i''otarai naha wame''e sumange.', '[]', NULL),
  (3462308, 'OT', 'Moze III', 1, 17, 'Ba ilöwa gafi ba lö ifaefa; ba itunu ere ba naha wame''e sumange, ba mbaho geu andrö ba galitö yaŵa; sumange nitunu ia, sumange nibe''e khö Yehowa, nifatörö ba galitö, samohua.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 1, 'Na so zame''e khö Yehowa sumange ni''a, ba ya hamo si sökhi zumange andrö khönia; yamulau wanikha yaŵa ba yamube''e gumöyö.[1]', '["MozIV 15:4"]', NULL),
  (3464871, 'OT', 'Moze III', 2, 2, 'Ba i''ohe ba ndraono Ga''aroni, ere andrö; ba yamuhalö zi tambai tanga ere, hamo andrö ba fanikha andrö, nilau, ba kumöyö, andrö, ahori, ba yamutunu ba naha wame''e sumange zamohua andrö khönia, sumange nibe''e khö Yehowa, nifatörö ba galitö, samohua.', '["Faigi 10:12"]', NULL),
  (3464871, 'OT', 'Moze III', 2, 3, 'Ba si tosai sumange ni''a andrö, fefu, ba tana khö Ga''aroni ba ba ndraononia; ni''amoni''ö sibai da''ö ba zumange Yehowa andrö, nifatörö ba galitö.[2]', '["Faigi 10:12"]', NULL),
  (3464871, 'OT', 'Moze III', 2, 4, 'Ba na edöna öbe''e sumange ni''a nibogö ba galitö, ba kue si lö mu''aisöni öbe''e, kue hamo si sökhi, nifaruka ba kue sanifi, si lö mu''aisöni, nigule''ö fanikha.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 5, 'Ba na sumange ni''a ba gali öbe''e, ba hamo si sökhi nifaruka fanikha ba si lö mu''aisöni öfake;', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 6, 'öboboto ia, samba-sambawa ba ölau wanikha yaŵa — sumange ni''a ia.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 7, 'Ba na sumange ni''a, nirino ba mbowoa, ba hamo si sökhi, awö wanikha öbe''e.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 8, 'Ba ö''ohe khö Yehowa zumange ni''a andrö, nimanö famazökhi; labe''e ba danga gere, ena''ö ya''ia zolohe ba naha wame''e sumange.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 9, 'Ba ihalö ere ndrohu-ndrohu, samohua andrö, ba zumange ni''a andrö, ba itunu ba naha wame''e sumange, sumange nibe''e khö Yehowa, nifatörö ba galitö, samohua.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 10, 'Ba si tosai sumange ni''a andrö fefu, ba tana khö Ga''aroni ba ba ndraononia, ni''amoni''ö sibai da''ö ba zumange Yehowa andrö, nifatörö ba galitö.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 11, 'Fefu zumange ni''a andrö, nibe''emi khö Yehowa, ba lö tola si no mu''aisöni mibe''e; tanömö roti sa, ba ŵe ŵani, ba lö tola mitunu ba galitö, sumange Yehowa, nifatörö ba galitö.', '["Mar 9:49"]', NULL),
  (3464871, 'OT', 'Moze III', 2, 12, 'Hana na mibe''e böröta zumange khö Yehowa, ba lö tola möi ba naha wame''e sumange, samohua ena''ö.', '["Mar 9:49"]', NULL),
  (3464871, 'OT', 'Moze III', 2, 13, 'Ba fefu zumange ni''a, nibe''eu, ba ölau nasio; lö''ö manö tola lö öbe''e nasio wawu''usa li andrö, nihonogöi Lowalangiu, ba zumange ni''a andrö khöu: ba zumange andrö khöu fefu, ba öfao nasio.[3]', '["Mar 9:49"]', NULL),
  (3464871, 'OT', 'Moze III', 2, 14, 'Ba na edöna''ö öbe''e sumange Yehowa mbua zinanö sahulö, ba ngalai nibogö ba galitö ba ma böra nirekha, bua si bohou mubasi, öbe''e sumange ni''a khöu, bua zahulö.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 15, 'Ba ölau wanikha ba öbe''e yaŵa gumöyö — sumange ni''a ia.', '[]', NULL),
  (3464871, 'OT', 'Moze III', 2, 16, 'Ba ihalö ndrohu-ndrohu, samohua, ere, böra nirekha andrö ba fanikha, nibe''e andrö — ba kumöyö andrö khönia, ba ahori, ihalö, ba itunu ba galitö sumange Yehowa, nifatörö ba galitö.', '[]', NULL),
  (3470627, 'OT', 'Moze III', 3, 1, 'Ba na sumange fangorifi nibe''enia, ba na saŵi zedöna ibe''e, ba si lö sala ifaigi, ma zi matua, ba ma si alawe, ni''ohenia khö Yehowa.', '[]', NULL),
  (3470627, 'OT', 'Moze III', 3, 2, 'Ba itufa tangania högö zumange andrö khönia, ba itaba ba zinga mbawandruhö nose wama''ele''ö; ba iraono Ga''aroni, ere andrö, zanefe naha wame''e sumange do andrö, fasui.[1]', '["MozII 29:12"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 3, 'Ba yamuhalö ba zumange fangorifi andrö, nibe''e sumange Yehowa nifatörö ba galitö, dawö wali''a andrö ba muru-muru mbetu''a ba bua si dombua,', '["MozII 29:12"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 4, 'fabaya tawönia, ba ba rami lafoyo, ba si faböbö ba gate; ba mbua i''etu''ö.', '["MozII 29:12"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 5, 'Ba ndra mutunu iraono Ga''aroni ba dete naha wame''e sumange, yaŵa ba zumange nitunu andrö, si so ba dete mbaho geu andrö ba galitö, latunu sumange nibe''e khö Yehowa nifatörö ba galitö, samohua.[2]', '["MozII 29:25"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 6, 'Ba na urifö side-ide nibe''enia sumange Yehowa, sumange fangorifi ba si lö sala ifaigi, ma si matua, ba ma si alawe, nibe''enia.', '[]', NULL),
  (3470627, 'OT', 'Moze III', 3, 7, 'Na ono mbiri-biri sedöna ibe''e sumange, ba yamu''ohe föna Yehowa,', '[]', NULL),
  (3470627, 'OT', 'Moze III', 3, 8, 'ba yamutufa tangania högö zumange andrö khönia, ba yamutaba sa''ae föna nose wama''ele''ö; ba iraono Ga''aroni zanefe naha wame''e sumange do andrö, fasui.', '[]', NULL),
  (3470627, 'OT', 'Moze III', 3, 9, 'Ba yamube''e sumange Yehowa nifatörö ba galitö zumange fangarifi andrö ösa, tawönia andrö: i''o sotawö andrö, ma''asara, ba mbörö gi''o sibai ifaefa — awö dawö wali''a andrö, ba muru-muru mbetu''a, fefu, ba bua si dombua,', '["Faigi 21:6"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 10, 'fabaya tawönia ba ba rami lafoyo ba si faböbö ba gate; ba mbua i''etu''ö.', '["Faigi 21:6"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 11, 'Ba itunu ba naha wame''e sumange ere, ö sumange nifatörö ba galitö, khö Yehowa.[3]', '["Faigi 21:6"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 12, 'Ba na nambi zumange khönia, ha yamu''ohe föna Yehowa,', '[]', NULL),
  (3470627, 'OT', 'Moze III', 3, 13, 'yamutufa tangania högö ba yamutaba föna nose wama''ele''ö; ba iraono Ga''aroni zanefe naha wame''e sumange do andrö, fasui.', '[]', NULL),
  (3470627, 'OT', 'Moze III', 3, 14, 'Ba ihalö ba da''ö zumange andrö khönia, nibe''e, sumange khö Yehowa, nifatörö ba galitö, tawö wali''a andrö ba muru-muru mbetu''a,', '["Faigi 7:23"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 15, 'fefu, ba bua si dombua, fabaya tawönia ba ba rami lafoyo, ba si faböbö ba gate; ba mbua i''etu''ö.', '["Faigi 7:23"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 16, 'Ba ere zanunu ba naha wame''e, sumange, ö nibe''e khö Yehowa, sumange nifatörö ba galitö, samohua. Fefu dawö, ba khö Yehowa.[4]', '["Faigi 7:23"]', NULL),
  (3470627, 'OT', 'Moze III', 3, 17, 'Amakhoita si lö tebulö da''ö, nitörömi, götö-götö wa''ara, fefu gofu heza so ami: Tawö ba do, ba alösu lö tola mi''a![5]', '["MozI 9:4; HalZin 15:20"]', NULL),
  (3471108, 'OT', 'Moze III', 4, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 2, 'Hede ba Ndraono Gizeraeli, ba ŵa''ö khöra: Na so zanawö oroisa Yehowa andrö zambalö, hadia ia, si lö mu''odödögö, na ilau hadia nilakha''ö [ba mimane:]', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 3, 'Na ere nibayoini andrö zosala, si möi sala zato, ba ibe''e khö Yehowa sumange fameta horö nono zaŵi si matua, si lö sala, sulö lalö andrö, horönia andrö.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 4, 'I''ohe ba zinga mbawandruhö nose wama''ele''ö, föna Yehowa, nono zaŵi andrö, ba itufa tangania högö nono zaŵi ba itaba nono zaŵi, föna Yehowa.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 5, 'Ba yamuhalö ösa ndro zaŵi andrö ere nibayoini andrö ba yamu''ohe bakha ba nose wema''ele''ö.[1]', '["Faigi 16:14; MozIV 19:4","Faigi 9:9"]', NULL),
  (3471108, 'OT', 'Moze III', 4, 6, 'Ba yamu''ungugö durunia ba ndro ere, ba mewitu yamutefe tou zalo do andrö ösa, föna mba''a-ba''a andrö, ba ni''amoni''ö, föna Yehowa.', '["Faigi 16:14; MozIV 19:4","Faigi 9:9"]', NULL),
  (3471108, 'OT', 'Moze III', 4, 7, 'Ba yamugule''ö ba dandru naha wame''e sumange, föna Yehowa, ba nose wama''ele''ö ndro andrö ma''ifu ere, ifabaya zamohua andrö, nitunu-tunu; ba do nono zaŵi, soya andrö, ba iduwagö tou ba zinga naha wame''e sumange nitunu andrö, ba zinga mbawandruhö nose wama''ele''ö.[2]', '["Faigi 16:14; MozIV 19:4","Faigi 9:9"]', NULL),
  (3471108, 'OT', 'Moze III', 4, 8, 'Ba ahori yamuhalö dawö nono zaŵi sumange fameta horö andrö, tawö wali''a andrö ba murumuru mbetu''a', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 9, 'ba bua si dombua, fabaya tawönia, ba ba rami lafoyo, awö zi faböbö ba gate; ba mbua i''etu''ö —', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3471108, 'OT', 'Moze III', 4, 10, 'si mane fangai ba zaŵi si matua, sumange fangorifi; ba itunu ere ba naha wame''e sumange nitunu.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 11, 'Ba ba guli nono zaŵi andrö ba ba nösinia, numalö högönia ba ahenia ba betu''ania ba tainia,', '["MozII 29:14; Heb 13:11"]', NULL),
  (3471108, 'OT', 'Moze III', 4, 12, 'ono zaŵi andrö, ma''asageu, ba ni''ohe baero golombaseŵa, ba naha si sökhi — ba naha niduwagö awu andrö — ba nitunu ba mbaho geu; ba naha niduwagö awu andrö latunu ia.[3]', '["MozII 29:14; Heb 13:11"]', NULL),
  (3471108, 'OT', 'Moze III', 4, 13, 'Ba na samba banua Iraono Gizeraeli zosala, si lö mu''odödögö, si lö aboto ba dödö zato, na lasawö goroisa Yehowa andrö zambalö, hadia ia, horöra,', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 14, 'ba sato zame''e ono saŵi, sumange fameta horö, na no murongo lalö andrö, horöra.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 15, 'La''ohe föna nose wama''ele''ö, ba latufa tangara högö nono zaŵi andrö satua mbanua, föna Yehowa ba lataba ia, föna Yehowa.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 16, 'Ba i''ohe bakha ba nose wama''ele''ö ndro nono zaŵi andrö ösa ere nibayoini andrö.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 17, 'Ba i''ungugö ba ndro andrö durunia ere ba mewitu itefe tou zalo do andrö ma''ifu föna Yehowa — föna mba''a-ba''a andrö.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 18, 'Ba ma''ifu göi igule''ö ba dandru naha wame''e sumange, föna Yehowa, ba nose wama''ele''ö do andrö; ba do soya andrö, ba iduwagö tou ba zinga naha wame''e sumange nitunu, ba zinga mbawandruhö nose wama''ele''ö.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 19, 'Ba tawönia fefu, ba ihalö, ba itunu ba naha wame''e sumange.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 20, 'Ba ono zaŵi andrö, ba ifatörö ba nifatörönia saŵi si matua andrö sumange fameta horö — ba da''ö göi ifatörö. Na no imanö ere, wamaigi khöra fameta horö, ba tebe''e aefa khöra.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 21, 'Ba ono zaŵi andrö, ba ni''ohe baero golombaseŵa ba nitunu, si mane fanunu saŵi si matua no mege. Sumange fameta horö mbanua da''ö.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 22, 'Ba na salaŵa zanawö oroisa Lowalanginia Yehowa, zambalö, horönia, si lö mu''odödögö,', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 23, 'ba na no mu''ombakha''ö khönia lalönia, horönia andrö, ba yamube''e sumange nambi si matua, si lö sala,', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 24, 'itufa tangania högö nambi andrö, ba itaba ba nitataba sumange nitunu andrö föna Yehowa; sumange fameta horö ia.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 25, 'Ba ihalö ma''ifu ndro zumange fameta horö andrö ere, turunia, ba igule''ö ba dandru naha wame''e sumange nitunu, ba do soya, ba iduwagö tou, ba zinga naha wame''e sumange nitunu.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 26, 'Ba tawö, ba ahori itunu ba naha wame''e sumange, si mane tawö zumange fangorifi andrö. Na no ifaigi khönia ere wameta lalönia andrö, ba tebe''e aefa khönia.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 27, 'Ba na ono mbanua zolalö wanawö oroisa Yehowa zambalö, horönia, si lö mu''odödögö,', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 28, 'ba na no mu''ombakha''ö khönia, lalönia andrö, horönia, ba yamube''e nambi si alawe, si lö sala, sumange fameta zala andrö horönia andrö,', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 29, 'itufa tangania högö zumange fameta horö andrö, ba itaba, ba nitataba sumange nitunu andrö.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 30, 'Ba ihalö ma''ifu ndro andrö ere, turunia, ba igule''ö ba dandru naha wame''e sumange nitunu. Ba do soya, ba iduwagö tou, ba zinga naha wame''e sumange.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 31, 'Ba tawö, ba ahori ihalö, si mane fangai ya''ia ba zumange fangorifi andrö, ba itunu ere ba naha wame''e sumange, samohua khö Yehowa. Na no imanö ere, wamaigi khönia fameta horö, ba tebe''e aefa khönia.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 32, 'Ba na ono mbiri-biri zumange andrö, nibe''enia sumange fameta horö, ba si alawe, si lö sala, ibe''e.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 33, 'Ba itufa tangania högö zumange fameta horö, ba itaba sumange fameta hörö, ba nitataba sumange nitunu andrö.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 34, 'Ba ihalö ma''ifu ndro zumange fameta horö andrö ere, turunia, ba igule''ö ba dandru naha wame''e sumange. Ba do soya, ba iduwagö tou ba zinga naha wame''e sumange.', '[]', NULL),
  (3471108, 'OT', 'Moze III', 4, 35, 'Ba tawö, ba ahori ihalö, si mane fangai-ngai tawö nono mbiri-biri andrö, sumange fangorifi, ba itunu ere, ba naha wame''e sumange, ba zumange Yehowa nifatörö ba galitö. Na no imanö ere, wamaigi khönia fameta sala andrö, horönia andrö, ba tebe''e aefa khönia.', '[]', NULL),
  (3471272, 'OT', 'Moze III', 5, 1, 'Na so zi sala, na no irongo wangelifi, na tola sasi ia, ma no i''ila [zangelifi] ba ma no irongo, ba na lö ni''ombakha''önia, si tobali horönia —', '["Hag 2:13; KorII 6:17"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 2, 'ma no so zi no mombambaya salakha, ma amatela gutu ndru''u salakha, ba ma amatela gurifö salakha ba ma zui amatela guökuö salakha, si lö i''ila mege, ba na irongo dania, si tobali horönia[1] —', '["Hag 2:13; KorII 6:17"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 3, 'ba ma zui tobaya khönia zalakha, ba niha, ba ma hadia ia zalakha, ba zi hulö zi ra''i-ra''iö niha, si lö i''ila mege, ba nirongonia dania, si tobali horönia —', '["Hag 2:13; KorII 6:17"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 4, 'ba ma zui na fahölu niha, sambö fangera-ngera, na iŵa''ö ilau hadia ia ba na numalö linia fahölusa, si lö aboto ba dödönia ua, ba na aboto ba dödönia dania, na tobali horönia zi mane da''ö,', '["Hag 2:13; KorII 6:17"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 5, 'ba yamu''ombakha''ö hadia horönia, na no tobali horönia zi mane da''ö;', '["Hag 2:13; KorII 6:17"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 6, 'ba ibe''e sumange Yehowa, sumange fameta horö zageu, urifö side-ide, si alawe, ma biri-biri ba ma nambi, ogauta ba golalöŵa andrö, horönia andrö, ba ifaigi khönia wameta lalö andrö ere.', '["Hag 2:13; KorII 6:17"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 7, 'Ba na tebai ibe''e nambi, na si numana ia, ba dombua wune, ba ma dumbua nono marafadi; si sambua, ba sumange fameta horö, ba si sambua, ba sumange nitunu.[2]', '["Faigi 12:8","Faigi 1:15"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 8, 'Yamu''ohe khö gere; ba yamu''ofönai''ö wame''e nihonogöi sumange fameta horö da''ö; iboto högö, tanö ba mbörö du''i, ba böi yamufaefa.[3]', '["Faigi 12:8","Faigi 1:15"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 9, 'Ba do zumange fameta horö andrö, ba igule''ö ba ngai naha wame''e sumange ma''ifu; ba do soya, ba nifera''ö tou, ba zinga naha wame''e sumange; sumange fameta horö ia.', '["Faigi 12:8","Faigi 1:15"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 10, 'Ba si sambua, ba i''asiwai sumange nitunu; i''o''ö nifakhoi andrö. Na no imanö ere wamaigi khönia fameta lalö andrö, horönia andrö, ba tebe''e aefa khönia.', '["Faigi 12:8","Faigi 1:15"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 11, 'Ba na tebai ibe''e wune andrö, si dombua, ba he ono marafadi, si dombua, ba wa''anumanania, ba yumube''e sumange ba lalönia andrö, sumange fameta horö, zi samba hinaoya hamo si sökhi, ba böi yamulau wanikha, ba he kumöyö, me sumange fameta horö.', '["Faigi 2:2"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 12, 'Ba yamu''ohe khö gere; ba ihalö zi tambai tanga ere, ndrohu-ndrohu, samohua, ba itunu ba naha wame''e sumange ba zumange Yehowa andrö, nifatörö ba galitö — sumange fameta horö ia.[4]', '["Faigi 2:2"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 13, 'Na no imanö ere, wamaigi khönia fameta zala andrö, horönia heza andrö, ba tebe''e aefa khönia. Ba khö gere [zumange si manö], si mane sumange ni''a andrö.', '["Faigi 2:2"]', NULL),
  (3471272, 'OT', 'Moze III', 5, 14, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3471272, 'OT', 'Moze III', 5, 15, 'Na so zi falimo, na ihalö hadia ia ni''amoni''ö khö Yehowa, si lö mu''odödögö, ba ibe''e sumange Yehowa, sumange fameta horö, ogauta, mbiri-biri si matua, si lö sala — ba gurifönia side-ide ihalö — si lö ambö dombua rufia fowöli, wamatöu böli.', '[]', NULL),
  (3471272, 'OT', 'Moze III', 5, 16, 'Ba yamufuli nihalönia ni''amoni''ö andrö ba ifo''uwu, sambua ni''olima ya''ia. Ba danga gere ibe''e, ba yamufaigi khönia wameta zala ere, ba zumange fameta horö, biri-biri andrö, ba tebe''e aefa khönia.', '[]', NULL),
  (3471272, 'OT', 'Moze III', 5, 17, 'Ba na so zi sala, sanawö oroisa Yehowa zambalö, horönia, na tohare khönia golalöŵa, si lö mu''odödögö,', '[]', NULL),
  (3471272, 'OT', 'Moze III', 5, 18, 'ba yamu''ohe khö gere mbiri-biri si matua si lö sala — ba gurifönia side-ide ihalö — ba ya''ugö zangukuku fa''ebua, yamube''e sumange ogauta, ba ifaigi khönia wameta lalö andrö ere, lalö andrö si lö mu''odödögö, ba tebe''e aefa khönia.', '[]', NULL),
  (3471272, 'OT', 'Moze III', 5, 19, 'Sumange ogauta da''ö, me no molalö ia khö Yehowa.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 2, 'Na so zi sala, na falimo ia khö Yehowa, horönia, na i''osilö''ögö khö nawönia nibe''e ba dangania, ma nifa''irö''ögö, ba ma nirabu, ba ma na ibe''e te''ala nawönia,', '["MozIV 5:6"]', NULL),
  (3471474, 'OT', 'Moze III', 6, 3, 'ba ma na i''osilö''ögö nisöndrania, saekhu, ba ma na möi ia ba hölu ba zi lö duhu, na so nilau hadia ia, sosala niha —', '["MozIV 5:6"]', NULL),
  (3471474, 'OT', 'Moze III', 6, 4, 'na molalö ia si manö, horönia, ba yamufuli nirabunia andrö, ba ma si falau horö ia, ba ma nibe''e ba dangania, ba ma saekhu no mege, nisöndrania,[1]', '["MozIV 5:6"]', NULL),
  (3471474, 'OT', 'Moze III', 6, 5, 'ba ma si möi ia ba hölu si lö duhu — fefu, gofu hadia ia — bölinia ma''afefu ifuli, ba sambua ni''olima ibe''e uwunia; ba zokhö ibe''e, na luo ibe''e gogauta andrö.', '["MozIV 5:6"]', NULL),
  (3471474, 'OT', 'Moze III', 6, 6, 'Ba khö Yehowa ibe''e ogauta mbiri-biri si matua, si lö sala — ba gurifönia side-ide ihalö — ya''ugö zanguhuku fa''ebua, yamu''ohe khö gere, sumange ogauta.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 7, 'Ba yamufaigi khönia wameta zala khö Yehowa ere, ba tebe''e aefa khönia — hadia ia nilau, horö zamösana.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 8, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 9, 'Be''e lala khö Ga''aroni ba ba ndraononia, ömane: Da''ö gamakhoita ba zumange nitunu andrö: Sumange nitunu andrö, ba sara wongi lö tebulö ba naha wame''e sumange, ba nitunu ya''ia, irege mahemolu mbanua, fangebua galitö ba naha wame''e sumange, fa lö mate.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 10, 'Ba yamu''obaru gamezania ere, ba yamubalugö zaila ia saraeŵa tarafali ba yamuheta nawu andrö, awu zumange nitunu andrö ba galitö ba naha wame''e sumange, ba yamuduwagö ba ngai naha wame''e sumange.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 11, 'Aefa da''ö, ba yamufohani ia, ba yamu''ohe baero golombaseŵa nawu andrö, ba naha si sökhi.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 12, 'Ba nibe''e fangebua galitö ba naha wame''e sumange ia, böi manö mate. Ero mahemolu itunu yaŵa geu ere, ifa''anö yaŵa geu, ba itunu yaŵa ba da''ö dawö zumange fangorifi andrö.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 13, 'Si lö tebulö galitö ba naha wame''e sumange, lö tola mate ia.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 14, 'Ba da''ö gamakhoita ba zumange ni''a andrö: Iraono Ga''aroni zolohe khö Yehowa, ba naha wame''e sumange.[2]', '["Faigi 2:1 b.t."]', NULL),
  (3471474, 'OT', 'Moze III', 6, 15, 'Ba ihalö ösa, tambai tanga — hamo si sökhi andrö ba fanikha, nibe''e sumange ni''a — ba kumöyö andrö, hawu-hawu zumange ni''a andrö, ba ahori ihalö, ba itunu ba naha wame''e sumange, sumange nifatörö ba galitö, samohua, ndrohu-ndrohunia, samohua, khö Yehowa.', '["Faigi 2:1 b.t."]', NULL),
  (3471474, 'OT', 'Moze III', 6, 16, 'Ba si tosainia, ba ö ndra A''aroni iraononia; ni''a lö mu''aisöni, ba naha ni''amoni''ö: ba golayama nose wama''ele''ö la''a ia.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 17, 'Lö tola labogö nifaruka tanömö roti. Utehe khöra urakhara ba zumangegu andrö nifatörö ba galitö; ni''amoni''ö sibai ia si mane sumange fameta horö andrö ba si mane sumange ogauta.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 18, 'Dozi motöi matua ba ndraono Ga''aroni zi tola manga ya''ia; amakhoita si lö tebulö ha wa''ara, nitehe khömi ba zumange Yehowa andrö, nifatörö ba galitö, götö-götö wa''ara; sombambaya ya''ia, ba no ni''amoni''ö göi.[3]', '["MozII 29:37"]', NULL),
  (3471474, 'OT', 'Moze III', 6, 19, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 20, 'Da''ö zumange Yehowa, nibe''e Ga''aroni ba iraononia, na luo tebayoini ia: Samba hinaoya hamo si sökhi, sumange ni''a, sero ma''ökhö — si matongania, ba na mahemolu mbanua, ba si matonga, ba na owi.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 21, 'Ba gali la''asosoi, nifaruka fanikha; öfakhöyö ua, atö öbe''e, sinaba zumange ni''a andrö nigore öbe''e, samohua khö Yehowa.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 22, 'Ere andrö, nibayoini fangalinia, nituyu ba ndraononia andrö, da''ö zangasiwai; amakhoita Yehowa si lö tebulö da''ö, götö-götö wa''ara; ahori tetunu khö Yehowa.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 23, 'Fefu zumange nibe''e gere, ba ahori tebe''e sumange; lö tola la''a niha.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 24, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 25, 'Hede khö Ga''aroni ba ba ndraononia, ŵa''ö khöra: Da''ö gamakhoita ba zumange fameta horö andrö: ba nitaba sumange nitunu, föna Yehowa, ba da''ö göi tetaba zumange fameta horö; ni''amoni''ö sibai ia.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 26, 'Ere andrö, same''e sumange fameta horö andrö, da''ö zi manga ya''ia; ba naha ni''amoni''ö te''a ia, ba golayama nose wama''ele''ö.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 27, 'Dozi sombambaya ösinia andrö, ba no ni''amoni''ö göi; ba na tokana ba mbaru ndronia ösa, ba ba naha ni''amoni''ö ösasai nikanania andrö.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 28, 'Bowoa tanö, fondrinonia, ba niboto; ba na bowoa töla wondrinonia, ba nidukhu ba nihaogö fangogumi.', '[]', NULL),
  (3471474, 'OT', 'Moze III', 6, 29, 'Dozi motöi matua ba gere zi manga ya''ia; ni''amoni''ö sibai ia.', '["Faigi 4:5; Heb 13:11"]', NULL),
  (3471474, 'OT', 'Moze III', 6, 30, 'Ba sumange fameta horö fefu ni''ohe do ösa ba nose wama''ele''ö, ba wolau fameta horö, ba ni''amoni''ö, ba lö tola te''a; nitunu da''ö.[4]', '["Faigi 4:5; Heb 13:11"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 1, 'Ba da''ö gamakhoita ba zumange ogauta andrö; ni''amoni''ö sibai ia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 2, 'Ba nitataba sumange nitunu andrö, ba da''ö göi lataba zumange ogauta, ba donia, ba fanefe naha wame''e sumange, fasui.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 3, 'Ba tawönia fefu, ba nibe''e sumange: i''o sotawö andrö ba tawö wali''a ba bua si dombua,', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 4, 'fabaya tawönia ba ba rami lafoyo ba si faböbö ba gate; ba mbua i''etu''ö.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 5, 'Ba itunu ere ba naha wame''e sumange sumange nibe''e khö Yehowa, nifatörö ba galitö; sumange ogauta ia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 6, 'Dozi motöi matua ba gere zi manga ya''ia; ba naha ni''amoni''ö te''a; ni''amoni''ö sibai ia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 7, 'Si mane ba zumange fameta horö, si manö göi ba zumange ogauta, fagölö-gölö: khö gere andrö, same''e ya''ia, fameta horö ia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 8, 'Ba khö gere andrö, same''e sumange nitunu andrö, ni''ohe niha, guli zumange nitunu andrö, nibe''enia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 9, 'Si manö göi zumange ni''a andrö, nibogö bawu, fefu, ba he nirino ba mbowoa, fefu, ba he nigore ba gali, ba khö gere, same''e ya''ia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 10, 'Ba fefu zumange ni''a, he nifaruka fanikha ba he sotufo ba ba ndraono Ga''aroni, faoma khöra.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 11, 'Ba da''ö gamakhoita ba zumange fangorifi, nibe''e khö Yehowa:', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 12, 'Na so zame''e ya''ia fangandrö saoha gölö, ba ifo''awö zumange fangandrö saoha gölö andrö kue nifaruka fanikha, si lö mu''aisöni ba kue sanifi, si lö mu''aisöni nigule''ö fanikha, ba hamo si sökhi, si no mufaruka — kue nilau fanikha ba wamazökhi —', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 13, 'Ba kue roti si lö mu''aisöni ifao ba zumange andrö khönia, lö lai zumange urifö, nibe''enia sumange fanuno, fangandrö saoha gölö.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 14, 'Ba sagö-sagörö kue zambalö sumange ibe''e amaedola zumange fegero khö Yehowa; ba khö gere andrö, sanefe do zumange fangorifi andrö ia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 15, 'Ba ösi zumange fangorifi andrö fangandrö saoha gölö, ba na luo tebe''e zumange andrö te''a ia; lö tola lasaigö hadia ia irege mahemolu mbanua.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 16, 'Ba na amabu''ula li mbörö zumange andrö, nibe''enia, ba ma na saoha gölö, ba na luo da''ö göi te''a, ba si tosai, ba hana na mahemolu ö la''a;[1]', '["Faigi 19:6"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 17, 'ba hadia zi tosai na ösi zumange, ba zi dua wongi, ba nitunu.', '["Faigi 19:6"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 18, 'Ba na te''a na ba zi dua wongi nösi zumange fangorifi andrö, ba lö ibe''e ni''omasi''ö zame''e ya''ia andrö; lö''ö sa tebe''e hare, tobali sa amaedola no i''a zobou, ba si manga ya''ia, ba ifalu''igö khönia horö.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 19, 'Ba he nagole si no fabaya ba zalakha, hadia ia, ba lö tola te''a, nitunu ia. Ba ba nagole [bö''ö], ba dozi si lö hadia ia salakha, ba tola la''a nagole.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 20, 'Ba si manga nösi zumange fangorifi andrö nibe''e khö Yehowa, fatua so khönia zalakha, ba nihori da''ö ba niwara andrö.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 21, 'Ba na so zi fabaya ba zalakha, hadia ia, he ba zalakha ba niha ba he ba zalakha urifö ba he ba zogoro ita, hadia ia, si ta''unö, ba na i''a [zui] nösi zumange fangorifi andrö, nibe''e khö Yehowa, ba nihori da''ö ba niwara andrö.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 22, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 23, 'Hede ba Ndraono Gizeraeli, ba ŵa''ö khöra: Lö tola mi''a hadia ia dawö zaŵi ba tawö mbiri-biri ba tawö nambi.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 24, 'Tawö gurifö si mate ba he nisasawi, ba hana na la''oguna''ö ba ngawalö hadia ia, ba lö tola mi''a.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 25, 'Dozi sa si manga dawö gurifö andrö, nibe''e sumange Yehowa, nifatörö ba galitö, ba nihori da''ö — si manga ya''ia — ba niwara andrö.', '["MozI 9:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3471703, 'OT', 'Moze III', 7, 26, 'Ba lö''ö göi tola mi''a ndro, ba nahiami fefu, he do wofo, ba he do zi öfa ahe.[2]', '["MozI 9:14"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 27, 'Dozi si manga ndro, ba nihori ba niwara.', '["MozI 9:14"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 28, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 29, 'Hede ba Ndraono Gizeraeli ba ŵa''ö khöra: Same''e khö Yehowa sumange fangorifi, ba ibe''e khö Yehowa ndrohu-ndrohu, ba zumange fangorifi andrö, ömönia khönia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 30, 'Ya''ia zolohe ngawua andrö, tana khö Yehowa, sumange nifatörö ba galitö: tawö ba osu yamu''ohe; osu andrö, ena''ö lahahae, nihahae föna Yehowa.[3]', '["MozII 29:24","MozII 29:27"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 31, 'Ba tawö, ba itunu ere ba naha wa''me''e sumange, ba osu andrö, ba khö Ga''aroni ba ba ndraononia.', '["MozII 29:24","MozII 29:27"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 32, 'Ba faha kambölö ba zumange fangorifi andrö khömi, ba ba gere göi mibe''e, amaedola fegero.[4]', '["MozII 29:24","MozII 29:27"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 33, 'Ono Ga''aroni andrö, same''e do zumange fangorifi andrö ba tawönia, zanema faha kambolö, tana khönia.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 34, 'Osu andrö sa, nihahae andrö ba faha andrö nibe''e fegero, ba zumange fangorifi andrö, nibe''e Ndraono Gizeraeli, ba ya''o zi okhögö, ba ube''e khö Ga''aroni ere andrö, ba ba ndraononia, tana khöra, ömö Ndraono Gizeraeli, si lö mamalö-malö.[5]', '["MozIV 18:11"]', NULL),
  (3471703, 'OT', 'Moze III', 7, 35, 'Da''ö dana khö Ga''aroni ba tana ba ndraononia, ba zumange Yehowa andrö, nifatörö ba galitö, na baŵa nifa''asonia ya''ira, ba wangai halöŵö gere khö Yehowa,', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 36, 'nihonogöi Yehowa khöra, me luo ibayoini ira, ame''ela Ndraono Gizeraeli, tana khö, ömöra si lö mamalö-malö, götö-götö wa''ara.', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 37, 'Da''ö gamakhoita ba zumange nitunu andrö ba ba zumange ni''a ba ba zumange fameta horö ba ba zumange ogauta ba ba zumange famataro ba ba zumange fangorifi,', '[]', NULL),
  (3471703, 'OT', 'Moze III', 7, 38, 'niŵa''ö Yehowa khö Mose ba hili Zina''i, me iŵa''ö lala ba Ndraono Gizeraeli, ba wame''e sumange khö Yehowa, ba danö si mate Sina''i.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 1, 'Ba humede Yehowa khö Moze, imane:[1]', '["Ayati 1–32: MozII 29:1–35"]', NULL),
  (3472878, 'OT', 'Moze III', 8, 2, 'Ohe Ga''aroni, awö ndraononia, awö nukha andrö ba fanikha famayoini, ba ono zaŵi, sumange fameta horö, ba biri-biri si matua andrö, si dua geu, ba kude andrö, si so bakha si lö mu''aisöni andrö,', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 3, 'ba falukha''ö zato fefu, föna mbawandruhö nose wama''ele''ö.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 4, 'Ba i''o''ö niŵa''ö Yehowa khönia Moze, ba owulo zato föna mbawandruhö nose wama''ele''ö.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 5, 'Ba imane Moze ba zato: Da''e ia, niŵa''ö Yehowa, nilau.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 6, 'Ba ifa''aso Ga''aroni ba iraononia Moze ba ifemondri ira.', '["MozII 28"]', NULL),
  (3472878, 'OT', 'Moze III', 8, 7, 'Aefa da''ö, ba ifobaru Ga''aroni kameza andrö ba ifamöbö talu böbö talu andrö ba ifobaru baru sebua ba ono mbaru ba doto andrö; ba iböbö khönia mböbö nono mbaru andrö, wangaro''ö khönia.[2]', '["MozII 28"]', NULL),
  (3472878, 'OT', 'Moze III', 8, 8, 'Ba ibe''e ba dotonia mbola andrö, ba ibe''e bakha ba mbola Urimi ba Tumimi andrö.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 9, 'Ba ibe''e ba högönia mbala högö andrö; ba tanö föna ba mbala högö andrö ibe''e detenia andrö, ana''a, diadema ni''amoni''ö andrö, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 10, 'Ba ihalö wanikha famayoini Moze, ibayoini nose, awö fefu hadia ia zi so bakha, we''amoni''ö ya''ia.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 11, 'Ba itefe göi ba naha wame''e sumange ösa, mewitu, ibayoini naha wame''e sumange andrö, awö wakake khönia, fefu, ba he gala andrö, fabaya ahenia, we''amoni''ö ya''ia.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 12, 'Ba ilau ba högö Ga''aroni ösa wanikha famayoini, ibayoini ia, we''amoni''ö ya''ia.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 13, 'Ba ifa''aso göi ndraono Ga''aroni, ifobaru ira kameza, ba ifamöbö talu böbö talu andrö ba ifokofia, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 14, 'Ba ifa''aso nono zaŵi andrö, sumange fameta horö, ba latufa högö nono zaŵi andrö ira A''aroni iraononia, tangara.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 15, 'Ba itaba Moze, ihalö ndro, igule''ö ba dandru naha wame''e sumange, fasui, turunia, fameta sala ba naha wame''e sumange; ba do soya, ba iduwagö tou ba zinga naha wame''e sumange; i''amoni''ö naha wame''e sumange andrö, wolau khönia fameta sala andrö.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 16, 'Ba ahori ihalö dawö wali''a, ba si faböbö ba gate ba bua si dombua, fabaya tawönia, ba itunu Moze, ba naha wame''e sumange.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 17, 'Ba ono zaŵi andrö, fabaya uli, ba ösinia ba tainia, ba baero golombaseŵa itunu, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 18, 'Ba awena ifa''aso mbiri-biri si matua andrö, sumange nitunu, ba latufa högönia ira A''aroni iraononia, tangara.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 19, 'Ba itaba Moze ba itefe naha wame''e sumange do andrö, fasui.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 20, 'Ba biri-biri andrö, ba itatawi, ba itunu högö, awö ngawua andrö, awö dawö.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 21, 'Ba alakhaö ba ahe, ba isasai ba nidanö; aefa da''ö, ba itunu mbiri-biri andrö, ma''asageu Moze, sumange nitunu, samohua, ö nibe''e khö Yehowa, nifatörö ba galitö, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 22, 'Aefa da''ö ba ifa''aso mbiri-biri si sageu andrö, biri-biri famataro, ba latufa högönia ira A''aroni ononia, tangara.[3]', '["MozII 29:10 b.t."]', NULL),
  (3472878, 'OT', 'Moze III', 8, 23, 'Ba itaba Moze ba ihalö ndro ma''ifu, ba igule''ö ba doyo dalinga Ga''aroni ba gambölö ba ba duru sebua ba dangania kambölö ba ba duturu kahe sebua kambölö.', '["MozII 29:10 b.t."]', NULL),
  (3472878, 'OT', 'Moze III', 8, 24, 'Ba ifa''aso göi Ndraono Ga''aroni Moze ba igule''ö göi ma''ifu ndro ba doyo dalingara kambölö ba ba duru sebua ba dangara kambölö ba ba duturu kahe sebua kambölö, ba do soya, ba ibe''e fanefe naha wame''e sumange, fasui.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 25, 'Ba ihalö dawö: i''o sotawö andrö ba tawö mbetu''a fefu, ba si faböbö ba gate ba bua si dombua, fabaya tawönia, ba faha kambölö.', '["MozII 29:24"]', NULL),
  (3472878, 'OT', 'Moze III', 8, 26, 'Ba ihalö ba gude, si so si lö mu''aisöni andrö, föna Yehowa, zagörö kue si lö mu''aisöni ba sagörö kue roti nifaruka fanikha ba sagörö kue sanifi, ba i''orudugö ba dawö no mege ba ba waha andrö, faha kambölö;', '["MozII 29:24"]', NULL),
  (3472878, 'OT', 'Moze III', 8, 27, 'ba ifarahugö wame''e ba danga ndra A''aroni iraononia, ihahae, nihahae föna Yehowa.[4]', '["MozII 29:24"]', NULL),
  (3472878, 'OT', 'Moze III', 8, 28, 'Awena ifuli ihalö ba dangara Moze ba itunu ba naha wame''e sumange, yaŵa ba zumange nitunu, sumange famataro, samohua, sumange nibe''e khö Yehowa, nifatörö ba galitö.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 29, 'Ba ihalö nosu mbiri-biri famataro andrö Moze ba ihahae, nihahae föna Yehowa; tana khö Moze ia, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 30, 'Ba ihalö ösa Moze fanikha famayoini ba do, si so ba naha wame''e sumange, ba itefe Ga''aroni, awö nukhania, ba iraononia, awö nukhara, i''amoni''ö Ga''aroni, fabaya nukhania ba iraononia, fabaya nukhara.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 31, 'Ba imane Moze khö ndra A''aroni iraononia: Mirino nagole andrö, föna mbawandruhö nose wama''ele''ö, ba mi''a ba da''ö, awö roti andrö, si so ba gude, nifao ba zumange famataro andrö, si mane niŵa''ö khögu ba goroisa andrö; A''aroni ba iraononia zi manga ya''ia.[5]', '["MozII 29:32"]', NULL),
  (3472878, 'OT', 'Moze III', 8, 32, 'Ba si tosai nagole ba roti, ba mitunu.', '["MozII 29:32"]', NULL),
  (3472878, 'OT', 'Moze III', 8, 33, 'Ba fitu bongi lö tola miröi mbawandruhö nose wama''ele''ö, irugi luo no ahöwö mbongi andrö, nihonogöi ba wamataro ya''ami; fitu ngaluo sa wa''ara lafo''ösi''ösi dangami.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 34, 'Si mane nilau ma''ökhö, si manö ni''oroi''ö Lowalangi folau-lau, ba wameta salami.', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 35, 'Fitu bongi wa''ara, ba bongi ma''ökhö mi''iagö zinga mbawandruhö nose wama''ele''ö, mi''o''ö goroisa Yehowa, fa böi mate ami — si manö niŵa''ö khögu!', '[]', NULL),
  (3472878, 'OT', 'Moze III', 8, 36, 'Ba la''o''ö A''aroni ba iraononia fefu ni''oroi''ö Yehowa khö Moze.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 1, 'Ba fitu bongi, ba humede Moze khö ndra A''aroni iraononia ba ba zatua Ndraono Gizeraeli, imane khö Ga''aroni:', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 2, 'Halö khöu nono zaŵi, ono-ono, sumange fameta horö ba biri-biri si matua, sumange nitunu, faoma si lö sala, ba ohe föna Yehowa.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 3, 'Ba ba Ndraono Gizeraeli, ba ömane: Mihalö nambi si matua, sumange fameta horö, ba ono zaŵi ba biri-biri, sage-sageu, faoma si döfi fa''ebua ba si lö sala, sumange nitunu,', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 4, 'ba saŵi si matua ba biri-biri si matua, sumange fangorifi, ba wanaba föna Yehowa, ba nifao zumange ni''a, nifaruka fanikha; ma''ökhṍ sa i''oroma''ö ia khömi Yehowa.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 5, 'Ba la''ohe niŵa''ö Moze, la''ohe ba golayama nose wama''ele''ö, ba so zato fefu, la''ondrasi Yehowa.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 6, 'Ba imane Moze: Da''ö ia, ni''oroi''ö Yehowa khömi folau, ena''ö oroma khömi lakhömi Yehowa.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 7, 'Ba imane Moze khö Ga''aroni: Ae ba naha wame''e sumange, ba be''e zumange fameta horö andrö khöu ba sumange nitunu, ena''ö aheta horöu, awö horö zato, öbe''e; aefa da''ö, ba be''e zumange nibe''e zato, ena''ö aheta horöra, öbe''e, si mane niŵa''ö Yehowa.[1]', '["Faigi 16:6; Heb 5:1; 7:27"]', NULL),
  (3473686, 'OT', 'Moze III', 9, 8, 'Ba möi ba naha wame''e sumange Ga''aroni, itaba nono zaŵi andrö, nihonogöi sumange fameta horö khönia.', '["Faigi 4:11,12"]', NULL),
  (3473686, 'OT', 'Moze III', 9, 9, 'Ba iraono Ga''aroni zangoro''ö khönia do andrö; ba i''ungugö durunia bakha ba igule''ö ba dandru naha wame''e sumange. Ba do soya, ba iduwagö tou ba zinga naha wame''e sumange.', '["Faigi 4:11,12"]', NULL),
  (3473686, 'OT', 'Moze III', 9, 10, 'Ba tawö zumange fameta horö, awö mbua, awö zi faböbö ba gate, ba itunu ba naha wame''e sumange, si mane niŵa''ö Yehowa khö Moze.', '["Faigi 4:11,12"]', NULL),
  (3473686, 'OT', 'Moze III', 9, 11, 'Ba ösi ba uli, ba baero golombaseŵa itunu.[2]', '["Faigi 4:11,12"]', NULL),
  (3473686, 'OT', 'Moze III', 9, 12, 'Aefa da''ö, ba itaba zumange nitunu; ba iraono Ga''aroni zangoro''ö khönia do andrö, ba ibe''e fanefe naha wame''e sumange, fasui.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 13, 'Ba sumange nitunu andrö, ba la''oro''ö khönia nitatawi, awö högö, ba itunu ba naha wame''e sumange.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 14, 'Ba alakhaö ba ahe, ba isasai ba nidanö ba itunu ba naha wame''e sumange, yaŵa ba zumange nitunu.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 15, 'Aefa da''ö, ba ibe''e zumange nibe''e zato: ihalö nambi si matua andrö, nihonogöi zumange fameta horö zato, itaba ba ibe''e sumange fameta horö, si mane mege.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 16, 'Aefa da''ö, ba ibe''e zumange nitunu andrö, ba lala nifakhoi ifatörö.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 17, 'Ba ibe''e göi zumange ni''a andrö; ihalö ösa, si tambai tanga, ba itunu ba naha wame''e sumange, lö lai zumange nitunu andrö na mahemolu mbanua.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 18, 'Aefa da''ö, ba itaba nono zaŵi andrö, awö mbiri-biri si matua andrö, sumange fangorifi, si tefaudu ba zato; ba iraono Ga''aroni zangoro''ö khönia do andrö ba ibe''e fanefe naha wame''e sumange, fasui.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 19, 'Ba ba ngawua dawö zaŵi andrö, ba ba gi''o mbiri-biri, sotawö andrö, awö dawö wali''a ba bua ba si faböbö ba gate,', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 20, 'ba lafalaetegö ba ngawua nosu ngawua dawö andrö, ba itunu ngawua dawö andrö, ba naha wame''e sumange.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 21, 'Ba ngawua nosu, awö waha kambölö, ba ihahae A''aroni, nihahae föna Yehowa, si mane niŵa''ö Moze.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 22, 'Ba i''oro''ö dangania A''aroni, yaŵa zato, ifahowu''ö ira; ba me no i''asiwai zumange fameta horö ba sumange nitunu ba sumange fangorifi, ba möi ia mitou.', '[]', NULL),
  (3473686, 'OT', 'Moze III', 9, 23, 'Ba möi bakha ba nose wama''ele''ö ndra Moze A''aroni, ba me lafuli ira baero, ba lafahowu''ö niha sato. Ba oroma ba niha sato fefu lakhömi Yehowa.', '["Sanguhuk 6:21; RazI 8:11; 18:38; Nga''ötII 7:1"]', NULL),
  (3473686, 'OT', 'Moze III', 9, 24, 'Ba so galitö si oroi Yehowa, ba i''a zumange nitunu andrö, awö ngawua dawö andrö, ba naha wame''e sumange. Ba me la''ila da''ö sato fefu, ba owua-wua dödöra ba lafalögu tou ira.[3]', '["Sanguhuk 6:21; RazI 8:11; 18:38; Nga''ötII 7:1"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 1, 'Ba lahalö gali mbo galitö khöra iraono Ga''aroni andrö Nadabi ba Abihu, labe''e galitö yaŵa ba lalau nitunu, samohua, ba tobali la''ohe föna Yehowa galitö si tenga, si tenga niŵa''önia khöra.[1]', '["MozII 30:9; MozIV 3:4; Nga''ötI 24:2"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 2, 'Ba so galitö, si oroi Yehowa, ba i''a ira, tobali mate ira [ba da''ö] föna Yehowa.', '[]', NULL),
  (3475571, 'OT', 'Moze III', 10, 3, 'Ba imane Moze khö Ga''aroni: Ba da''ö itörö niŵa''ö Yehowa, me imane: "Ba zahatö khögu u''oroma''ö, wa ni''amoni''ö ndra''odo, ba ba zi so sato fefu ufa''ele''ö lakhömigu." Ba lö hede-hede Ga''aroni.[2]', '["MozII 19:22"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 4, 'Ba humede Moze khö ndra Miza''eli Elisafa, ono Uzieli andrö, ama Ga''aroni si akhi, imane khöra: Mi''aini, miheta föna ni''amoni''ö dalifusömi andrö, mi''ohe baero golombaseŵa.', '["MozII 19:22"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 5, 'Ba möi ira, la''ohe baero golombaseŵa, la''o''ö niŵa''ö Moze; lö muheta gamezara andrö.', '[]', NULL),
  (3475571, 'OT', 'Moze III', 10, 6, 'Ba imane Moze khö Ga''aroni ba khö nononia Eleazari ba Itamari: Lö tola miheta kofiami ba lö tola mitika nukhami, fa böi mate ami ba fa böi mofönu Yehowa ba zato fefu! Ba talifusömi andrö ba ma''uwu Gizeraeli fefu, ba hana na la''e''esi nitunu Yehowa andrö.', '["Faigi 21:12"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 7, 'Ba lö''ö göi tola miröi nose wama''ele''ö, we''amöi baero, fa böi mate ami, me no tohare khömi wanikha wamayoini andrö khö Yehowa! Ba la''o''ö niŵa''ö Moze.[3]', '["Faigi 21:12"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 8, 'Ba humede Yehowa khö Ga''aroni, imane:', '[]', NULL),
  (3475571, 'OT', 'Moze III', 10, 9, 'Agu ba hadia ia nibadu, si mabu niha, ba lö tola mibadu — he ya''ugö ba he iraonou — na möi ami bakha ba nose wama''ele''ö, fa böi mate ami. Amakhoita si lö tebulö da''ö, götö-götö wa''ara.[4]', '["Hez 44:21; Tit 1:7"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 10, 'Ba mifaehusi ira ni''amoni''ö zi tenga ni''amoni''ö ba salakha ba si lö alakha,', '["Hez 44:21; Tit 1:7"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 11, 'ba mifahaö Ndraono Gizeraeli ba gamakhoita andrö fefu, nifa''ema Yehowa khöra khö Moze.', '["Hez 44:21; Tit 1:7"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 12, 'Ba ibe''e lala Moze khö Ga''aroni ba khö ndra Eleazari Itamari, si tosai ononia na, imane: Mihalö zumange ni''a andrö, si tosai na sumange nibe''e khö Yehowa, nifatörö ba galitö, ba mi''a lö mu''aisöni, ba ngai naha wame''e sumange, me no ni''amoni''ö sibai ia.[5]', '["Faigi 2:10","Faigi 6:16"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 13, 'Andrö wa ba naha ni''amoni''ö mi''a; noa sa tana khöu, si möi khöu ba ba ndraonou, föfö zumange Yehowa andrö, nifatörö ba galitö — si manö niŵa''ö khögu.[6]', '["Faigi 2:10","Faigi 6:16"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 14, 'Ba osu andrö, nihahae ba faha fegero, ba mi''a onou matua ba onou alawe, ba naha si sökhi, noa sa mutehe khömi, tana khömi, si möi khömi iraonou, föfö zumange fangorifi andrö, nibe''e Ndraono Gizeraeli.', '["Faigi 2:10","Faigi 6:16"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 15, 'Ba faha andrö, fegero, ba osu nihahae, ba nifao ba ngawua dawö andrö, nihonogöi sumange nifatörö ba galitö, ena''ö tehahae, nihahae föna Yehowa; ba khömi iraonou dania, tana khömi si lö tebulöbulö, ha wa''ara, si mane niŵa''ö Yehowa.', '["Faigi 2:10","Faigi 6:16"]', NULL),
  (3475571, 'OT', 'Moze III', 10, 16, 'Ba i''alu-alui nambi si matua andrö, sumange fameta horö, Moze, ba hiza, no mutunu. Ba mofönu sibai ia khö ndra Eleazari Itamari, ono Ga''aroni andrö, si tosai na khönia, ba imane:', '[]', NULL),
  (3475571, 'OT', 'Moze III', 10, 17, 'Hana sa wa lö mi''a zumange fameta horö andrö, ba naha ni''amoni''ö? noa sa ni''amoni''ö sibai ia, ba no ibe''e khömi, ba wameta horö mbanua, ba ba wangatulö''ö ya''ira khö Yehowa.', '[]', NULL),
  (3475571, 'OT', 'Moze III', 10, 18, 'Hiza, no lö mu''ohe si bakha ba ni''amoni''ö ndronia andrö, ba mi''a mena''ö, ba ni''amoni''ö, si mane niŵa''ögu.', '[]', NULL),
  (3475571, 'OT', 'Moze III', 10, 19, 'Ba imane A''aroni khö Moze: Hiza, no labe''e zumange fameta horö, awö zumange nitunu khöra, khö Yehowa ma''ökhö, ba no göna ndra''o si manö, ba na u''a ena''ö zumange fameta horö ma''ökhö, hadia, omasi maö Yehowa?', '[]', NULL),
  (3475571, 'OT', 'Moze III', 10, 20, 'Ba me irongo da''ö Moze, ba ibato wanegu ya''ira.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 1, 'Ba humede Yehowa khö ndra Moze A''aroni,[1] iŵa''ö li khöra, imane:', '["Faigi göi MozV 14:2–21"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 2, 'Mimane ba Ndraono Gizeraeli:', '["Faigi göi MozV 14:2–21"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 3, 'Fefu zi öfa ahe ba si no fabali sa''a, si no alua fabali, ba samomendrua fonganga göra ba tola mi''a.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 4, 'Ba ba zamomendrua fonganga göra ba ba zi no fabali sa''a, ba da''ö zi lö tola mi''a: ondra andrö; ifomendrua sa wonganga gönia, ba tenga si no alua fabali sa''a — salakha ia miŵa''ö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 5, 'Ba kelindri; ifomendrua sa wonganga gönia, ba tenga si no fabali sa''a, ba salakha ia miŵa''ö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 6, 'Ba kawelu, ifomendrua wonganga gönia, ba tenga si no fabali sa''a: ba salakha ia miŵa''ö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 7, 'Ba bawi; noa sa salua fabali sa''ania, ba tenga samomendrua fonganga gönia; salakha ia miŵa''ö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3482835, 'OT', 'Moze III', 11, 8, 'Lö tola mi''a nösira ba lö tola mibabaya gamatela; salakha ira miŵa''ö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 9, 'Ba da''ö zi töla mi''a, saliŵa-liŵa ba nidanö, fefu:', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 10, 'Ba fefu zi so ba nasi ba ba nidanö, si lö fere-fere ba si lö huna-huna, ba zaliŵa-liŵa ba nidanö, fefu, ba ba zi so noso, si so ba nidanö, ba sogoro ami da''ö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 11, 'Sogoro ami ira: ösira, ba lö tola mi''a, ba amatelara, ba mi''ogorofi.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 12, 'Fefu zaliŵa-liŵa ba nidanö, si lö fere-fere, ba si lö huna-huna, ba sogoro ami.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 13, 'Ba ba wofo, ba da''ö ni''ogorofimi — tebai ni''a, ni''ogorofi: moyo ba fofo basi ba moyo nasi.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 14, 'Ba razo wali, awö ngawalö ala-ala,', '["Lafotöi wofo laki-laki ba li Indonesia burung ranggung ba ba li Inggris stork."]', NULL),
  (3482835, 'OT', 'Moze III', 11, 15, 'awö ngawalö gaga fefu.', '["Lafotöi wofo laki-laki ba li Indonesia burung ranggung ba ba li Inggris stork."]', NULL),
  (3482835, 'OT', 'Moze III', 11, 16, 'Ba fofo ondra, ba katawaena ba samari, awö ngawalö wötö.', '["Lafotöi wofo laki-laki ba li Indonesia burung ranggung ba ba li Inggris stork."]', NULL),
  (3482835, 'OT', 'Moze III', 11, 17, 'Ba tugöu ba belibi ba lamuhu,', '["Lafotöi wofo laki-laki ba li Indonesia burung ranggung ba ba li Inggris stork."]', NULL),
  (3482835, 'OT', 'Moze III', 11, 18, 'ba meu ba engangi ba banga.', '["Lafotöi wofo laki-laki ba li Indonesia burung ranggung ba ba li Inggris stork."]', NULL),
  (3482835, 'OT', 'Moze III', 11, 19, 'Ba laki-laki,[3] awö ngawalö mbangau, ba meragai ba bögi.', '["Lafotöi wofo laki-laki ba li Indonesia burung ranggung ba ba li Inggris stork."]', NULL),
  (3482835, 'OT', 'Moze III', 11, 20, 'Fefu zaliŵa-liŵa side-ide, si so afi ba si öfa ahe, ba sogoro ami.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 21, 'Fefu zaliŵa-liŵa side-ide, si so afi ba si öfa ahe, ba ha da''ö zi tola mi''a, si dua faha, yaŵa gahera, ba wanoka ba danö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 22, 'Ba da''ö ba tola mi''a ngawalö damo andrö, ya''ia ngawalö damo solama, awö ngawalö damo hara goli, awö ngawalö damo hagabi.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 23, 'Ba bö''önia, saliŵa-liŵa side-ide, si so afi, ba si öfa ahe, ba sogoro ami.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 24, 'Tobali si ra''i-ra''iö da''ö mibe''e; dozi sombambaya amatela, ba si ra''iö, irege bongi.[4]', '["Faigi 5:2"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 25, 'Ba ha niha zolohe amatela, zambua, ba lö tola lö ibabago nukhania, ba si ra''iö ia, irege bongi —', '["Faigi 5:2"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 26, 'ba zaliŵa-liŵa ba danö, fefu, si no fabali sa''a, si lö alua fabali, ba si tenga samomendrua fonganga gönia. Salakha ira miŵa''ö, dozi sombambaya ya''ira ba ra''iö.', '["Faigi 5:2"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 27, 'Ba fefu göi zosa''a, sa''a mao, ba zaliŵa-liŵa ba danö, si öfa ahe, ba salakha miŵa''ö; dozi sombambaya amatela, ba ra''iö, irege bongi.', '["Faigi 5:2"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 28, 'Ba solohe amatela, ba lö tola lö ibabago nukhania, ba ra''iö ia, irege bongi — salakha ira miŵa''ö.', '["Faigi 5:2"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 29, 'Ba da''ö zalakha, miŵa''ö, ba zaliŵa-liŵa ba danö side-ide: bituru ba te''u ba bayakomo, hadia ngawalö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 30, 'Ba anaka ba koakhi ba leta''a ba khometi ba loa.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 31, 'Da''ö ira zalakha, miŵa''ö, ba zaliŵa-liŵa ba danö side-ide; dozi sombambaya, na no mate, ba ra''iö irege bongi.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 32, 'Ba fefu hadia ia nilangö zi manö, ba wa''amate, ba ra''iö, he nahia eu fefu ba he nukha ba he uli ba he goni — fefu wakake, ni''oguna''ö. Ni''ungugö ba nidanö, ba lö tebulö wa''ata''unö irege bongi; awena ifuli sökhi.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 33, 'Ba na aekhu ba nahia tanö zara, da''ö, ba ta''unö nösi ma''afefu, ba nirasa [nahia andrö].', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 34, 'Fefu ngawalö gö, ni''aga-aga niha, ba ta''unö, na göna nidanö si manö; ba si manö göi nibadu hadia ia, nibadu-badu niha, gofu hadia ia nahia, ba ta''unö [ba zi manö].', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 35, 'Ba fefu hadia ia, nilangö gamatela zi manö, ba ta''unö: bowoa roti ba nirasa ba awu, ba nidudugö. Si ta''unö ia ba si ta''unö miŵa''ö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 36, 'Ha umbu ba ba''a, ö idanö, ba tenga si ta''unö; ba ha niha zombambaya amatela bakha, ba ra''iö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 37, 'Ba na göna ba mbua zinanö hadia ia, tanömö, gamatela zi manö, ba tenga si ta''unö da''ö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 38, 'Ba na no muwuwui idanö danömö zinanö andrö, ba ilangö dania amatela zi manö, ba si ta''unö ia miŵa''ö.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 39, 'Ba na mate zaliŵa-liŵa ba danö andrö, si tola mi''a, ba na so zombambaya amatelania, ba ra''iö ia, irege bongi.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 40, 'Ba na so zi manga gamatela andrö, ba ibabago nukhania, ba ra''iö ia, irege bongi; ba solohe amatela, ba ibabago nukhania, ba ra''iö ia, irege bongi.', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 41, 'Fefu zaliŵa-liŵa ba danö, side-ide, ba sogoro ami, miŵa''ö, ba lö tola te''a.', '["MozII 22:31; FetI 1:16"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 42, 'Fefu zi''anana''ö talu ba fefu zi öfa ahe, fabaya fefu, soya ahe, moroi andrö, ba zaliŵa-liŵa ba danö, side-ide andrö, ba lö tola mi''a, sogoro ami sa ira miŵa''ö.', '["MozII 22:31; FetI 1:16"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 43, 'Böi mibali''ö sogoro niha ami ba guö-kuö andrö, hadia ia, ba böi mita''unöi ami ba da''ö, fa ra''iö ami ba da''ö.', '["MozII 22:31; FetI 1:16"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 44, 'Me no Yehowa ndra''o, Lowalangimi; ba mi''amoni''ö ami; yani''amoni''ö ami, me no ni''amoni''ö ndra''odo. Ba böi mita''unöi ami ba zaliŵa-liŵa ba danö andrö, side-ide, soliha-liha ba guli danö.[5]', '["MozII 22:31; FetI 1:16"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 45, 'Me no Yehowa ndra''odo, si no mangeheta ya''ami ba danö Miserayi, ena''ö Lowalangimi ndra''o; andrö yani''amoni''ö ami, me no ni''amoni''ö ndra''odo.', '["MozII 22:31; FetI 1:16"]', NULL),
  (3482835, 'OT', 'Moze III', 11, 46, 'Da''ö nihonogöi ba zi öfa ahe andrö ba ba wofo ba ba zonoso fefu, saliŵa-liŵa ba nidanö, ba ba zaliŵa-liŵa ba danö fefu,', '[]', NULL),
  (3482835, 'OT', 'Moze III', 11, 47, 'ena''ö lafaehusi ira zalakha zi tenga salakha ba si tola te''a ba si lö tola te''a.', '[]', NULL),
  (3482836, 'OT', 'Moze III', 12, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3482836, 'OT', 'Moze III', 12, 2, 'Hede ba Ndraono Gizeraeli, ŵa''ö khöra:', '[]', NULL),
  (3482836, 'OT', 'Moze III', 12, 3, 'Ba na aefa zi fitu bongi, ba niboto nono.[1]', '["MozI 17:10"]', NULL),
  (3482836, 'OT', 'Moze III', 12, 4, 'Ba 33 bongi dania ia ba ndro wangehao andrö khönia; lö tola ibabaya hadia ia ni''amoni''ö, ba lö tola möi ia ba ni''amoni''ö, irege no ahöwö mbongi wangehaonia andrö.', '["MozI 17:10"]', NULL),
  (3482836, 'OT', 'Moze III', 12, 5, 'Ba na ono alawe nononia, ba dua migu wa''ara ra''iö ia, si mane na afökhö dalunia, ba 66 wongi ia ba ndro wangehao andrö khönia.', '[]', NULL),
  (3482836, 'OT', 'Moze III', 12, 6, 'Ba na no ahöwö mbongi wangehao andrö khönia — he ba nono matua, ba he ba nono alawe — ba i''ohe khö gere ba mbawandruhö nose wama''ele''ö nono mbiri-biri si döfi fa''ebua, sumange nitunu, ba ono marafadi, ba ma fune, sumange fameta horö.', '[]', NULL),
  (3482836, 'OT', 'Moze III', 12, 7, 'Ba ere zame''e khö Yehowa, ifaigi khönia wameta sala, ba nihaogö zui ia ba wendro dalu andrö.', '[]', NULL),
  (3482836, 'OT', 'Moze III', 12, 8, 'Ba na abölö numana ia, ba wamaigi biri-biri, ba yamuhalö zi dombua fune, ba ma dombua nono marafadi; si sambua, ba sumange nitunu, ba si sambua, ba sumange fameta horö, ba yamufaigi khönia wameta sala ere, ba nihaogö ia.[2]', '["Faigi 5:7; Luk 2:24"]', NULL),
  (3482837, 'OT', 'Moze III', 13, 1, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 2, 'Na oroma ba dete guli niha zobu''u, ba ma gigimö, ba ma safusi, na ibörötaigö bou auri, ba ni''ohe khö Ga''aroni ere andrö ia, ba ma khö nononia, ha niha, ere andrö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 3, 'Ba na ifaigi ere zofökhö andrö ba gulinia, wa no ahuwa mbu ba da''ö, awö wa hulö zahöndrö, moroi ba guli bö''ö, ba no si ndruhu mbou auri; ba ha i''ila si''aikö da''ö ere, ba si ra''iö niha da''ö yamuŵa''ö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 4, 'Ba na so zafusi ba gulinia, si tenga sahöndrö, moroi ba guli bö''ö ba si lö ahuwa bu, ba i''oniagö zi göna da''ö ere, fitu bongi.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 5, 'Ba na ifaigi dania ia ere, na no irugi fitu bongi, ba na i''ila, si manö-manö zi göna andrö, wamaiginia, ba lö si tedou wökhö andrö, ba guli; ba ifuli i''oniagö ia ere, fitu bongi tö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 6, 'Ba na ifuli ifaigi ere, na no irugi fitu bongi, ba na i''ila no ahoe nahia andrö, ba lö si tedou wökhö andrö, ba guli, ba tenga si ra''iö ia yamuŵa''ö ere — ha gigimö; ba ibabago sa nukhania, ba tenga si ra''iö ia.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 7, 'Ba na tedou-dou gigimö andrö, ba guli, aefa mbaŵa wangoroma''önia ya''ia khö gere, ba wanguma''ö tenga si ra''iö ia, ba na ifuli i''oroma''ö ia khö gere, ba na isöndra ere,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 8, 'no tedou-dou gigimö andrö, ba guli, ba si ra''iö ia yamuŵa''ö ere: bou auri sa''ae.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 9, 'Na te''ila ba niha zi göna bou auri ia, ba ni''ohe khö gere.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 10, 'Ba na isöndra ere, so ba guli zi hulö waosa, safusi, si no ahuwa bu, ba sotawötawö,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 11, 'ba no bou auri si no ara, ba gulinia, ba iŵa''ö ere, si ra''iö ia, lö''ö sa''ae i''oniagö, si ra''iö sa''ae ia.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 12, 'Ba na bou auri manö, sageu ya''ia, ba gulinia, na no anönö bou auri guli zi göna andrö, ma''asageu i''otarai högö, numalö ba gahe, heza göi ifaigi ere, ba na i''ila ere,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 13, 'no tehawu manö bou auri nösinia ma''afefu, ba tenga si ra''iö zi göna andrö yamuŵa''ö: no fatutu wa''afusi, ba tobali tenga si ra''iö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 14, 'Ba na si tawötawösö khönia, ba si ra''iö ia;', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 15, 'ba na i''ila zi no tawötawösö andrö ere, ba si ra''iö yamuŵa''ö: si tawötawösö andrö sa, ba si ra''iö, no bou auri.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 16, 'Ba na ifuli taya zi tawötawösö andrö ba na afusi, ba yamöi khö gere.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 17, 'Ba ifaigi ia ere ba na i''ila, no afusi nahia andrö si no göna, ba tenga si ra''iö zi göna andrö yamuwa''ö ere; no tenga si ra''iö ia.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 18, 'Na so zi tumbu faosa ba guli ba na ifuli döhö, ba na obu''ubu''u dania,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 19, 'safusi ba ma soyoramö, ba yamu''oroma''ö ia khö gere.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 20, 'Ba na isöndra ere, no ahöndrö, moroi ba guli bö''ö, wamaigida, awö wa no ahuwa mbu khönia, ba si ra''iö ia yamuŵa''ö ere; no si ndruhu bou auri, salua ba waosa andrö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 21, 'Ba na ifaigi nahia andrö ere ba na i''ila, lö sahuwa bu khönia ba tenga sahöndrö moroi ba guli bö''ö ba no ahoe ma''ifu, ba yamu''oniagö niha da''ö ere, fitu bongi.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 22, 'Ba na itugu tedou-dou dania zafusi andrö, ba guli, ba si ra''iö niha da''ö yamuŵa''ö ere; no göna nahia andrö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 23, 'Ba na lö si tedou zafusifusi andrö, na lö sanana-nana, ba no laheto waosa no mege, ba tenga si ra''iö ia yamuŵa''ö ere.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 24, 'Na so ba guli niha zakhozi, ba na oyoramö, ba ma na safusi nagole andrö, sanöi ba zakhozi andrö,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 25, 'ba na ifaigi ere ba na i''ila, no ahuwa mbu ba zafusifusi andrö, ba no ahöndrö, moroi ba guli bö''ö, wamaigida, ba no bou auri, salua ba zakhozi andrö, ba si ra''iö niha da''ö yamuŵa''ö ere; no si ndruhu bou auri.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 26, 'Ba na i''ila ere, na ifaigi, lö sahuwa mbu ba nahia safusifusi andrö ba tenga sahöndrö ia, moroi ba guli bö''ö ba no ahoe ma''ifu, ba yamu''oniagö niha da''ö ere, fitu bongi.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 27, 'Ba na ifaigi ia ere, na no irugi fitu bongi, ba si ra''iö ia iŵa''ö ere, na tedou-dou nahia andrö, ba guli — no si ndruhu bou auri.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 28, 'Ba na lö si tedou nahia safusifusi andrö, na lö sanana-nana ia ba na no ahoe ma''ifu, ba no sobu''ubu''u zakhozi andrö ba tenga si ra''iö ia yamuŵa''ö ere; noa sa laheto zakhozi andrö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 29, 'Na so ndra matua, ba ma ira alawe, si so tandra ba högö, ba ma ba gambi,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 30, 'ba na ifaigi ere dandra andrö, ba na isöndra, no ahöndrö, moroi ba guli bö''ö, wamaiginia ba mobu sise-ise, sa''usö, ba si ra''iö ia yamuŵa''ö ere, no gigimö bou auri ba högö, ba ma ba gambi.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 31, 'Ba na i''ila ere — na ifaigi gigimö andrö — tenga sahöndrö moroi ba guli bö''ö ba lö bu saitö khönia, ba yamu''oniagö zi göna gigimö andrö ere, fitu bongi.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 32, 'Ba na ifaigi nahia si göna andrö ere, na no irugi fitu bongi, ba na i''ila, lö si tedou gigimö andrö, ba lö bu sa''usö, ba tenga sahöndrö moroi ba guli bö''ö gigimö andrö,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 33, 'ba yamutöwö ia — ha gigimö andrö zi lö itöwö —; ba awena dania ifuli i''oniagö ere zi no göna gigimö andrö, fitu bongi zui.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 34, 'Ba na ifaigi gigimö andrö ere, na no irugi fitu bongi, ba na i''ila, lö si tedou gigimö andrö, ba guli, ba na tenga sahöndrö ia, moroi ba guli bö''ö, ba tenga si ra''iö ia yamuŵa''ö ere; ba yamubabagö nukhania, ba tenga si ra''iö ia.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 35, 'Ba na tedou-dou gigimö andrö, ba guli, na no muŵa''ö tenga si ra''iö zi göna andrö,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 36, 'ba na ifaigi ia ere ba na i''ila, no tedou gigimö andrö ba guli, ba alakha lö i''alui mbu sa''usö andrö ere — si ra''iö ia.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 37, 'Ba na si manö-manö gigimö, wamaigida ba na no tumbu khonia mbu saitö, ba no döhö gigimö andrö — tenga si ra''iö ia, ba yamuŵa''ö ere, wa tenga si ra''iö ia.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 38, 'Na oroma ba guli ndra matua, ba ma ba guli ndra alawe dandra, tandra safusifusi,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 39, 'ba na ifaigi ere ba na i''ila ba guli dandra safusifusi, si no ahoe, ba no gigimö si lö ata''u ita, si tumbu ba guli — tenga si ra''iö niha si manö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 40, 'Ba na batule niha, ba no si batule tanö ba mbörö du''i — tenga si ra''iö niha si manö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 41, 'Ba na batule ia yaŵa gangango, ba no si batule tanö föna — tenga si ra''iö niha si manö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 42, 'Ba na tumbu ba zi batule tanö furi, ba ma tanö föna gigimö soyoramö, ba no bou auri, salua ba zi batule andrö tanö furi, ba ma tanö föna.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 43, 'Ba na ifaigi ia ere, ba na i''ila gigimö soyoramö ba zi batule andrö khönia tanö furi, ba ma tanö föna, si mane bou auri ba guli nösi, wamaigida,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 44, 'ba si no göna bou auri zi manö. Si ra''iö ia; yamuŵa''ö manö ere, si ra''iö ia; no ba högönia so wökhö andrö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 45, 'Ba si no göna bou auri andrö, si so fökhö andrö ba nösi, ba yamu''onukha nukha si no atika ba böi yamufake mbalu-balu högö ba yamubalugö gambinia ba yamu''ao: Si ra''iö! si ra''iö!', '["RazII 7:3; 15:5"]', NULL),
  (3482837, 'OT', 'Moze III', 13, 46, 'Götö so khönia wökhö andrö, ba si ra''iö ia. Si ra''iö ia; ni''oniagö nahiania — baero golombaseŵa i''iagö.[1]', '["RazII 7:3; 15:5"]', NULL),
  (3482837, 'OT', 'Moze III', 13, 47, 'Ba na ba mbaru oroma zi hulö mbou auri, sambua nahia — he ba mbaru luo, ba he ba mbaru tarafali,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 48, 'ba ma ba nukha bö''ö, nukha nisoso, he tarafali, ba he baru luo, ba ma ba guli zaŵi, ba ma ba gama-gama uli zaŵi, hadia ia, ba na no mowuge''e,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 49, 'ba ma na no oyoramö nahia andrö, ba mbaru, ba ma ba guli zaŵi, ba ma ba nukha nisoso, ba ma ba gama-gama uli zaŵi, hadia ia, ba no bou auri, ba ni''oroma''ö khö gere.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 50, 'Ba na no ifaigi nahia andrö, si göna, ere, ba yamukusi ba naha zi no göna bou auri andrö, ere, fitu bongi.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 51, 'Ba na i''ila, na no irugi fitu bongi, no tedou zi hulö gigimö andrö, ba mbaru, ba ma ba nukha nisoso, ba ma ba guli zaŵi, ba ma ba gama-gama hadia ia, ni''oguna''ö uli zaŵi, wamazökhi hadia ia, ba no bou auri safaito gigimö andrö; si ra''iö zi manö;', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 52, 'ba nitunu mbaru andrö, ba ma nukha nisoso, baru luo ba ma tarafali, ba ma gama-gama uli zaŵi, ba zoroma gigimö andrö; noa sa bou auri safaito; nitunu ia.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3482837, 'OT', 'Moze III', 13, 53, 'Ba na ifaigi ere, ba na i''ila, lö si tedou gigimö andrö, ba mbaru, ba ma ba nukha nisoso, ba ma ba gama-gama uli zaŵi, hadia ia,', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 54, 'ba yamuŵa''ö ere, nibabago zi göna gigimö andrö, ba yamufuli mukusi ba naha, fitu bongi zui.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 55, 'Ba na ifuli ifaigi ere, na no mubabago mege nahia andrö, si no göna, ba na i''ila, si manö-manö nahia andrö, wamaigida, he ŵa''ae lö si tedou gigimö andrö, ba si ra''iö ia; nitunu — no si no mogao, he tete, ba he arö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 56, 'Ba na i''ila ere — na ifaigi — no ahoe nahia andrö, si göna, na no aefa lababago, ba nisaka [nahia andrö], ba mbaru, ba ma ba guli zaŵi, ba ma ba nukha nisoso.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 57, 'Ba na ifuli tumbu mbou auri ba mbaru, ba ma ba nukha nisoso, ba ma ba gama-gama uli zaŵi, hadia ia, ba no si bohou alua; nitunu zi göna gigimö andrö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 58, 'Ba baru andrö, ba he nukha nisoso, ba he gama-gama uli zaŵi, hadia ia ngawalö, ba zi no taya gigimö andrö, na no mubabago, ba nifuli nibabago, awena dania tenga si ra''iö.', '[]', NULL),
  (3482837, 'OT', 'Moze III', 13, 59, 'Da''ö nihonogöi ba mbou auri andrö ba mbaru luo ba ba mbaru tarafali ba he ba gama-gama uli zaŵi, hadia ia, ba wanguma''ö na tenga si ra''iö ba na si ra''iö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 2, 'Da''ö gamakhoita ba zi göna bou auri, na baŵa wangehao ya''ia: Ni''ohe khö gere.[1]', '["Mat 8:4; Mar 1:44; Luk 5:14; 17:14","Sin 51:9","RazII 5:10"]', NULL),
  (3482838, 'OT', 'Moze III', 14, 3, 'Ba si möi baero golombaseŵa gere, ba na isöndra ere — na ifaigi ia — no döhö wökhö nahia andrö, si göna bou auri ia,', '["Mat 8:4; Mar 1:44; Luk 5:14; 17:14","Sin 51:9","RazII 5:10"]', NULL),
  (3482838, 'OT', 'Moze III', 14, 4, 'ba yamuŵa''ö ere, ndramu''ohe wofo sauri, dombua, si tenga salakha, ba eu, eresi, ba kirimisi ba sufo, ba zi möi nihaogö andrö.[2]', '["Mat 8:4; Mar 1:44; Luk 5:14; 17:14","Sin 51:9","RazII 5:10"]', NULL),
  (3482838, 'OT', 'Moze III', 14, 5, 'Ba yamuŵa''ö ere, lataba wofo si sambua ba nahia tanö, yaŵa nidanö gumbu.', '["Mat 8:4; Mar 1:44; Luk 5:14; 17:14","Sin 51:9","RazII 5:10"]', NULL),
  (3482838, 'OT', 'Moze III', 14, 6, 'Ba fofo sauri andrö ba eu eresi ba kirimisi ba sufo andrö, ba yamu''ungugö ba ndro wofo andrö, nitaba yaŵa nidanö gumbu no mege, fabaya fofo sauri andrö.', '["Mat 8:4; Mar 1:44; Luk 5:14; 17:14","Sin 51:9","RazII 5:10"]', NULL),
  (3482838, 'OT', 'Moze III', 14, 7, 'Ba mewitu itefe niha andrö, si möi nihaogö, ba mbou auri andrö, wangehao ya''ia; ba fofo sauri andrö, ba yamufoloi ba mbenua.', '["Mat 8:4; Mar 1:44; Luk 5:14; 17:14","Sin 51:9","RazII 5:10"]', NULL),
  (3482838, 'OT', 'Moze III', 14, 8, 'Ba si möi nihaogö andrö, ba ibabago nukhania, ba itöwö mbunia, ihori, ba mondri, ba nihaogö ia. Aefa da''ö ba tola möi ia ba golombaseŵa, ba baero nosenia i''iagö, fitu bongi.', '["Mat 8:4; Mar 1:44; Luk 5:14; 17:14","Sin 51:9","RazII 5:10"]', NULL),
  (3482838, 'OT', 'Moze III', 14, 9, 'Ba na no irugi fitu bongi, ba itöwö mbunia fefu, he ba högö, ba he gambi, ba he röngöröngö, bunia ma''afefu itöwö; ba ibabago nukhania ba mondri, ba abeta wa''ara''iönia.[3]', '["Mat 8:4; Mar 1:44; Luk 5:14; 17:14","Sin 51:9","RazII 5:10"]', NULL),
  (3482838, 'OT', 'Moze III', 14, 10, 'Ba na irugi ŵalu bongi, ba yamuhalö nono mbiri-biri, dua rozi, si lö sala, ba sara nono mbiri-biri si alawe, si lö sala, si döfi fa''ebua, ba tölu ni''ofulu [zu''a-su''a] hamo si sökhi, nifaruka fanikha, sumange ni''a, ba matonga kata wanikha.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 11, 'Ba yamu''angaruwusi khö Yehowa niha andrö si möi nihaogö, awö da''ö no mege, ere andrö, solau fangehao andrö, föna mbawandruhö nose wama''ele''ö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 12, 'Ba yamuhalö nono mbiri-biri si sara ere, yamube''e sumange ogauta, awö wanikha andrö, si matonga kata; faoma yamuhahae föna Yehowa.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 13, 'Ba nitataba sumange fameta horö ba sumange nitunu, lataba nono mbiri-biri andrö, ba naha ni''amoni''ö; si mane sumange fameta horö sa, si manö göi zumange ogauta andrö: khö gere; ni''amoni''ö sibai ia.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 14, 'Ba ihalö ma''ifu ndro zumange ogauta andrö ere ba igule''ö ba mbörö dalinga zi möi nihaogö andrö, ba gambölö ba ba duru sebua ba danga kambölö ba ba duturu kahe sebua kambölö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 15, 'Ba ma''ifu ihalö fanikha andrö, si matonga kata, ere, ba ilau ba dangania — ba danga gere — kabera.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 16, 'Ba i''ungugö ba wanikha andrö durunia kambölö ere, ba wanikha ba dangania kabera, ba itefe föna Yehowa wanikha andrö turunia, mewitu.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 17, 'Ba fanikha si tosai ba dangania, ba igule''ö ba mbörö dalinga zi möi nihaogö andrö, kambölö ba ba duru sebua ba dangania kambölö ba ba duturu kahenia sebua kambölö ba dete ndro zumange ogauta andrö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 18, 'Ba hadia zi tosai na do ba danga gere, ba yamulau ba högö zi möi nihaogö andrö, ena''ö iheta zalania khö Yehowa ere, ba zi manö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 19, 'Ba i''asiwai zumange fameta horö andrö ere, ba wameta sala zi möi nihaogö andrö ba wa''ara''iönia andrö; ba awena dania itaba zumange nitunu andrö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 20, 'Ba ibe''e zumange nitunu andrö ere, awö zumange ni''a, ba naha wame''e sumange; ba na no imanö ere, wamaigi fameta zala khönia, ba aheta wa''ara''iönia.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 21, 'Ba na si numana ia, na tebai ibe''e [niŵa''ö andrö], ba ha sara yamuhalö ono mbiri-biri, sumange ogauta, ena''ö tehahae ba ena''ö tefaigi khönia wameta zala, ba sambua ni''ofulu hamo si sökhi, nifaruka fanikha, sumange ni''a, ba matonga kata wanikha, ba dombua wune,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 22, 'ba ma dombua nono marafadi — hadia zi tola ibe''e —, ena''ö sumange fameta horö zi sambua ba sumange nitunu zi sambua.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 23, 'Ba na no alua fitu bongi, i''otarai tehaogö ia, ba yamu''ohe khö gere, ba zinga mbawandruhö nose wama''ele''ö, föna Yehowa.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 24, 'Ba yamuhalö nono mbiri-biri andrö, sumange ogauta, ere, fabaya fanikha andrö, si matonga kata, ba faoma yamuhahae ere, nihahae föna Yehowa.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 25, 'Ba ndramutaba nono mbiri-biri andrö, sumange ogauta, ba yamuhalö ma''ifu ndro zumange ogauta andrö ere, ba yamugule''ö ba mbörö dalinga zi möi nihaogö andrö, ba gambölö ba ba duru sebua ba dangania kambölö, ba ba duturu kahenia sebua kambölö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 26, 'Ba fanikha andrö, ba yamulau ba dangania ma''ifu ere — ba danga gere — kabera,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 27, 'ba yamutefe ere wanikha andrö ösa, si so ba dangania kabera, turunia kambölö, mewitu, föna Yehowa.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 28, 'Ba igule''ö ba mbörö dalinga zi möi nihaogö andrö ma''ifu wanikha andrö ba dangania, ere, ba ba duru sebua, ba dangania kambölö ba ba duturu kahenia sebua, kambölö, yaŵa ba dete ndro zumange ogauta andrö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 29, 'Ba si tosai fanikha ba danga gere, ba yamulau ba högö zi möi nihaogö andrö, ena''ö ifaigi khönia wameta zala khö Yehowa.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 30, 'Ba yamu''asiwai wune si sambua andrö, ba ma ono marafadi, si tola ibe''e,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 31, 'hadia zi tola ibe''e — si sambua, ba sumange fameta horö, ba si sambua, ba sumange nitunu, awö zumange ni''a andrö, ifaigi ba zi möi nihaogö andrö wameta zala khö Yehowa ere, ba zi manö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 32, 'Da''ö nihonogöi, ba zi no göna bou auri, ba si tebai mame''e [niŵa''ö andrö], ba wangehao ya''ia.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 33, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 34, 'Na mirugi dania danö Gana''ana, nibe''egu khömi dania, ba na tumbu zi hulö mbou auri ba nomo heza, ube''e, ba danö andrö, si no tana khömi,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 35, 'ba möi mu''ombakhaö khö gere zokhö omo andrö, imane: No tumbu ba nomogu zi hulö mbou auri!', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 36, 'Ba yamuŵa''ö ere, laheta nösi nomo, atö möi yomo gere, ba wamaigi nahia andrö si göna, fa böi laŵa''ö dania, si ra''iö manö nösi nomo ma''afefu. Awena dania möi yomo gere, ba wamaigi omo andrö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 37, 'Ba na isöndra — na ifaigi nahia si no göna bou auri andrö — ba mbagolö nomo so, mogao ba mowuge''e ba oyoramö, hulö zahöndrö ba mbolo mbagolö,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 38, 'ba möi tou gere ba mbawandruhö, ba ikusi nomo andrö, fitu bongi.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 39, 'Ba na ifuli dania ia ere, na no irugi fitu bongi, ba na i''ila — na ifaigi — no tedou mbou auri andrö ba mbagolö nomo,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 40, 'ba yamuŵa''ö ere, ladeha gara andrö, soroma bou auri andrö, ba latibo''ö baero mbanua, ba naha si ta''unö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 41, 'Ba omo andrö, ba ni''o''oi tanö bakha, fasui, ba o''oila la''uri andrö, ba niduwagö baero mbanua, ba naha si ta''unö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 42, 'Ba lahalö gara bö''ö ba labe''e fangali gara no mege; ba si manö la''uri bö''ö, ba wangalösö omo andrö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 43, 'Ba na ifuli tumbu mbou auri ba nomo andrö, na no muheta gara andrö ba na no mu''o''oi nomo, ba na no mufuli mu''alösöigö,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 44, 'ba yamöi yomo gere, ba na i''ila — na ifaigi — no tedou mbou auri ba nomo andrö, ba no bou auri safaito, ba nomo: si ra''iö ia.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 45, 'Ba nidudugö nomo andrö, ba karania ba eunia ba la''uri fefu, ba nomo, ba ni''ohe baero ba naha si ta''unö, baero mbanua.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 46, 'Ba si möi yomo ba nomo andrö, fatua, no mukusi, ba niŵa''ö si ra''iö, irege bongi.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 47, 'Ba si no mörö yomo, ba ibabago nukhania; ba he si no manga yomo, ba ibabago nukhania.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 48, 'Ba na möi yomo gere, ba na i''ila, ba wamaiginia, lö si tedou mbou auri, ba nomo andrö, me no mufuli mu''alösöigö nomo, ba tenga si ra''iö sa''ae nomo andrö, yamuŵa''ö ere, noa sa döhö wökhö andrö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 49, 'Ba yamuhalö wofo, dombua ba eu eresi ba kirimisi ba sufo, ba wameta sala nomo andrö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 50, 'Fofo si sambua, ba itaba ba nahia tanö, yaŵa nidanö gumbu;', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 51, 'ba eu eresi andrö ba sufo ba kirimisi ba fofo sauri andrö, ba ihalö ba i''ungugö ba ndro wofo nitaba andrö ba ba nidanö gumbu, ba omo, ba mewitu itefe,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 52, 'ba wameta sala nomo do wofo andrö ba idanö gumbu ba fofo sauri andrö ba eu eresi ba sufo ba kirimisi andrö.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 53, 'Ba fofo sauri andrö, ba yamufoloi baero mbanua, ba mbenua; si manö wametania sala nomo andrö: abeta wa''ara''iönia.', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 54, 'Da''ö nihonogöi ba ngawalö mbou auri andrö ba ba gigimö,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 55, 'ba ba mbou auri ba nukha ba ba nomo,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 56, 'ba ba dandra ba guli ba ba zi hulö mböni ba ba dandra safusi andrö,', '[]', NULL),
  (3482838, 'OT', 'Moze III', 14, 57, 'ba wangombakha hadia zi ra''iö ba hadia zi tenga si ra''iö. Da''ö gamakhoita ba ba mbou auri andrö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 1, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 2, 'Mihede ba Ndraono Gizeraeli, ba mimane khöra: Na so zi hulö zonana famatua, ba fonana si ra''i-ra''iö zi manö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 3, 'Ba da''ö wa''ara''iönia ba wonana andrö: he na mowöi wamatunia, ba he na no teduhu, fa lö alua nana — si ra''iö ia.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 4, 'Fefu gaso, niföröni zi so sonana andrö, ba si ra''iö, ba fefu dadaoma nidadaoninia, ba si ra''iö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 5, 'Sombambaya kasonia, ba ibabago nukhania ba mondri, ba si ra''iö ia, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 6, 'Ba si dadaoni dadaoma andrö, nidadaoni zi so sonana andrö, ba isasai nukhania ba mondri, ba si ra''iö ia, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 7, 'Ba sombambaya ösi zi so sonana andrö, ba ibabago nukhania ba mondri, ba si ra''iö ia, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 8, 'Ba na idiloi zi lö si ra''iö si so sonana andrö, ba ibabago nukhania da''ö ba mondri, ba si ra''iö ia, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 9, 'Ba fefu sela, ba zi fakudo zi so sonana andrö, ba si ra''iö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 10, 'Ba sombambaya hadia ia dane-danenia, ba si ra''iö, irege bongi. Ba solohe misa, ba ibabago nukhania ba mondri, ba si ra''iö ia, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 11, 'Ba dozi nibabaya zi so sonana andrö na lö nisasainia tangania, ba lababago nukhara ba mondri, ba si ra''iö, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 12, 'Nahia tanö, nibabaya zi so sonana andrö, ba niboto, ba nahia eu, ba nisasai ba nidanö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 13, 'Ba na döhö zonana andrö khönia, ba i''erai mbongi, fitu bongi, i''otarai döhö khönia; ba awena dania ibabago nukhania ba mondri ba nidanö gumbu — ba aheta wa''ara''iönia.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 14, 'Ba na no alua fitu bongi, ba ihalö wune, dombua, ba ma ono marafadi dombua, ba möi ia föna Yehowa, ba zinga mbawandruhö nose wama''ele''ö, ba ibe''e ba danga gere wofo andrö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 15, 'Ba i''asiwai ere: si sambua, ba sumange fameta horö, ba si sambua, ba sumange nitunu; ba si manö gere wamaigi khönia fameta zala khö Yehowa, ba zonana andrö khönia.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 16, 'Na no ahele gula ba niha, ba ifemondri nösinia ma''asageu, ba si ra''iö ia, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 17, 'Ba fefu nukha ba uli zaŵi, si göna ula andrö, ba nibabago, ba si ra''iö, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 18, 'Ba na so zorudu ba ndra alawe ba na no ahele gula, ba faoma mondri ira, ba si ra''iö ira, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 19, 'Na afökhö dalu ndra alawe, landro, ba fitu bongi wa''ara ra''iö ia, ba dozi sombambaya ya''ia, ba si ra''iö, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 20, 'Ba hadia niföröninia fefu, götö wa''ara''iönia, ba ra''iö, awö nidadaoninia fefu, ba ra''iö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 21, 'Ba dozi sombambaya kasonia, ba lababago nukhara ba mondri, ba si ra''iö, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 22, 'Ba dozi sombambaya hadia ia nidadaoninia, ba lababago nukhara ba mondri, ba si ra''iö, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 23, 'Ba sombambaya hadia ia zi so ba gasonia, ba ma ba dadaomania, ba ra''iö, irege bongi.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 24, 'Ba na so zorudu khönia, ba na göna khönia zi rai''önia, ba fitu bongi wa''ara ra''iö ia ba fefu gaso, ba zi mörö ia, ba ra''iö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 25, 'Ba na ara wa''afökhö dalu ndra alawe, na tenga baŵa landro khönia, ba na mendro, sanalu''i baŵa landro khönia, ba si ra''iö ia, götö wa''ara wendro andrö khönia, si mane na baŵa zatulö landro khönia, si ra''iö ia.[1]', '["Mat 9:20"]', NULL),
  (3480247, 'OT', 'Moze III', 15, 26, 'Fefu gaso niföröninia, götö wendro andrö khönia ba si mane kasonia, na satulö landro khönia, iŵa''ö, ba fefu dadaoma, nidadaoninia, ba ra''iö, si mane fa''ara''iönia na satulö landro khönia.', '["Mat 9:20"]', NULL),
  (3480247, 'OT', 'Moze III', 15, 27, 'Sombambaya da''ö no mege, ba ra''iö; ibabago nukhania ba mondri, ba dörö-dörö ra''iö, irege bongi.', '["Mat 9:20"]', NULL),
  (3480247, 'OT', 'Moze III', 15, 28, 'Ba na no döhö khönia wendro andrö, ba yamu''erai mbongi, fitu bongi: ba awai wa''ara''iönia laŵa''ö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 29, 'Ba na no alua fitu bongi, ba yamuhalö wune, dombua, ba ma ono marafadi, dombua, ba i''ohe khö gere ba zinga mbawandruhö nose wama''ele''ö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 30, 'Ba yamu''asiwai ere: si sambua, ba sumange fameta horö, ba si sambua, ba sumange nitunu; ifaigi khönia wameta zala khö Yehowa ere, ba zi manö, ba wendronia andrö, si ra''iö.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 31, 'Si manö wanenaŵamö Iraono Gizeraeli, ba wa''ara''iö andrö khöra, fa böi mate ira börö wa''ara''i''öra andrö, na lata''unöi nahiagu andrö, ba khöra.', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 32, 'Da''ö nihonogöi ba zi so sonana ba ba zahele ula, fa ra''iö ia ba da''ö,', '[]', NULL),
  (3480247, 'OT', 'Moze III', 15, 33, 'ba ba zolandro satulö, ba ba zi so si hulö zonana, he ira matua, ba he ira alawe, ba ba zorudu ba zi no ra''iö.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 1, 'Ba humede Yehowa khö Moze, me no mate ndraono Ga''aroni andrö; me no la''ondrasi Yehowa, si mate ira.[1]', '["Faigi 10:1"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 2, 'Ba imane Yehowa khö Moze:', '["Faigi 10:1"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 3, 'Awena tola möi bakha ba ni''amoni''ö Ga''aroni, na ibe''e nono zaŵi si matua, sumange fameta horö ba biri-biri si matua, sumange nitunu.', '["MozII 30:10; 40:34; RazI 8:10; Heb 9:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3480248, 'OT', 'Moze III', 16, 4, 'Kameza tarafali ni''amoni''ö i''obaru, ba saraeŵa tarafali mbalu-balu zaila ia, ba böbö talu tarafali i''amöbö talu ba bala högö tarafali ibe''e ba högönia. Nukha ni''amoni''ö da''ö — i''onukha na no aefa mondri ia.', '["MozII 30:10; 40:34; RazI 8:10; Heb 9:7"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 5, 'Ba ba zato Ndraono Gizeraeli, ba dua geu ihalö nambi si matua, sumange fameta horö, ba sageu mbiri-biri si matua, sumange nitunu.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 6, 'Ba A''aroni, ba i''ohe nono zaŵi andrö, sumange fameta horö tana khönia, fameta zalania ba sala moroi yomo khöra.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 7, 'Ba awena dania ibe''e föna Lowalangi nambi si matua andrö si dua geu ba zinga mbawandruhö nose wama''ele''ö.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 8, 'Ba ilau dahö-dahö A''aroni ba nambi andrö: sambua dahö-dahö khö Yehowa ba sambua khö Azazeli (Afökha).', '["Yes 13:21; Mat 12:43; Fam 18:2"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 9, 'Ba i''ohe nambi andrö, si göna khö Yehowa, A''aroni, ba i''asiwai sumange fameta horö.', '["Yes 13:21; Mat 12:43; Fam 18:2"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 10, 'Ba si sageu andrö, si göna khö Azazeli, ba labe''e auri, föna Yehowa, ena''ö lafatörö khönia nilau ba wameta sala, ba ena''ö lafofanö khö Azazeli, ba danö si mate.[3]', '["Yes 13:21; Mat 12:43; Fam 18:2"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 11, 'Ba yamuhalö nono zaŵi, sumange fameta horö tana khönia, ba wameta salania ba sala moroi yomo khöra, ba yamutaba nono zaŵi andrö fameta zala, khönia.', '["Faigi 3:2; Heb 10:3,4"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 12, 'Ba yamuhalö zamba gali mbo galitö ba naha wame''e sumange, föna Yehowa, awö nitunu samohua, ni''ohama, sandra''u, ba yamu''ohe bakha, barö mba''a-ba''a andrö.', '["Faigi 3:2; Heb 10:3,4"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 13, 'Ba ilau ba galitö zamohua andrö, föna Yehowa, ena''ö iba''a lagö-lagö andrö yaŵa zura goroisa simbo zamohua andrö, fa böi mate Ga''aroni.', '["Faigi 3:2; Heb 10:3,4"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 14, 'Ba ihalö ma''ifu ndro nono zaŵi andrö ba ibe''e fanefe dete lagö-lagö andrö, tanö föna, turunia; ba föna lagö-lagö, ba mewitu itefe do andrö ösa, turunia.[4]', '["Faigi 3:2; Heb 10:3,4"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 15, 'Awena dania itaba nambi si matua andrö sumange fameta horö ba zato, ba donia, ba i''ohe bakha barö mba''a-ba''a, ba ilau si mane mege ba ndro nono zaŵi andrö, ibe''e fanefe lagö-lagö andrö ba föna lagö-lagö misa itefe,', '["Faigi 3:2; Heb 10:3,4"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 16, 'wameta sala ba ni''amoni''ö andrö, börö wa''ara''iö Ndraono Gizeraeli ba lalöra andrö, si no molalö ira, ba si manö göi ilau ba nose wama''ele''ö, nifa''anö ba khöra, ba hunö wa''ara''iöra.', '["Faigi 3:2; Heb 10:3,4"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 17, 'Ba lö tola so niha ba nose wama''ele''ö, na möi ia bakha, ba wolau nilau ba wameta sala, ba ni''amoni''ö andrö, irege ifuli möi baero. Si manö wametania salania ba sala moroi yomo khöra ba sala zato Ndraono Gizeraeli fefu.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 18, 'Awena dania möi ia baero, ba zinga naha wame''e sumange, föna Yehowa, ba wameta sala ba da''ö; ihalö ma''ifu ndro nono zaŵi andrö ba do nambi ma''ifu ba igule''ö ba dandru naha wame''e sumange, fasui,', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 19, 'ba mewitu itefe naha wame''e sumange do andrö, turunia, wangehao ya''ia ba fe''amoni''ö ya''ia, börö wa''ara''iö Ndraono Gizeraeli andrö.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 20, 'Ba na no imanö, wangasiwai fameta sala ba ni''amoni''ö andrö ba ba nose wama''ele''ö ba ba naha wame''e sumange, ba i''ohe ba da''ö nambi si matua andrö, sauri;', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 21, 'ba itufa högö nambi andrö sauri A''aroni tangania ma''adua ba i''ombakha''ö yaŵania zala Ndraono Gizeraeli fefu, awö lalö fefu, solalö ira heza, ba ihare''ö ba högö nambi andrö, ba ifa''ohe''ö ba danö si mate nambi, ba niha, si no ihönagö ba da''ö.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 22, 'Ba ba hulunia i''ohe misa ba danö saröu golalöŵara fefu nambi si matua andrö, ba ba danö si mate ladudu ia.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 23, 'Ba möi bakha Ga''aroni ba nose wama''ele''ö, iheta nukha tarafali andrö, nukhania me möi ia ba ni''amoni''ö, ba ibe''e tou ba da''ö.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 24, 'Ba mondri ia ba naha ni''amoni''ö ba ifuli i''onukha nukhania; awena möi ia baero, ba wangasiwai sumange nitunu khönia ba sumange nitunu ba niha sat, ba wameta salania ba sala zato.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 25, 'Ba tawö zumange fameta horö andrö, ba itunu ba naha wame''e sumange.', '[]', NULL),
  (3480248, 'OT', 'Moze III', 16, 26, 'Ba solohe baero nambi si matua andrö khö Azazeli, ba ibabago nukhania ba mondri, awena tola ifuli ia ba golombaseŵa.', '["Faigi 6:30; Hez 43:21; Heb 13:11"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 27, 'Ba ono zaŵi andrö, ba nambi si matua sumange fameta horö, ni''ohe bakha do, ba wolau nilau ba wameta sala, ba ni''amoni''ö, ba ni''ohe baero golombaseŵa, ba uli ba ösi ba tai, ba nitunu.[5]', '["Faigi 6:30; Hez 43:21; Heb 13:11"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 28, 'Ba sanunu ya''ia, ba ibabago nukhania ba mondri, awena tola ifuli ia ba golombaseŵa.', '["Faigi 6:30; Hez 43:21; Heb 13:11"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 29, 'Ba da''ö huku ba khömi, götö-götö wa''ara: ba mbaŵa si fitu, ba zi mewulu, ba mifakao ami, ba lö tola mihalö holöŵö, hadia ia, he niha ba danö, ba he si fatewu, si so ba ngaimi.[6]', '["Faigi 23:27","MozII 28:41"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 30, 'Na baŵa da''ö sa lafaigi khömi wameta zala, ba wangehao ya''ami; horömi fefu niheta föna Yehowa.', '["Faigi 23:27","MozII 28:41"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 31, 'Baŵa salösu lö mohalöŵö ami ia khömi ba mifakao ami; huku si lö mamalö-malö khömi da''ö.', '["Faigi 23:27","MozII 28:41"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 32, 'Ere zolau fameta horö andrö, nibayoini ba nifo''ösi tanga, ena''ö ihalö halöŵö gere, fangali namania; ba i''onukha nukha tarafali andrö, nukha ni''amoni''ö,[7]', '["Faigi 23:27","MozII 28:41"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 33, 'ba iheta zala ba wondrege ni''amoni''ö andrö; ba sala ba nose wama''ele''ö ba ba naha wame''e sumange, ba iheta; ba ba gere ba ba zato fefu ifaigi wameta zala.', '["Faigi 23:27","MozII 28:41"]', NULL),
  (3480248, 'OT', 'Moze III', 16, 34, 'Ba huku ba khömi da''ö, götö-götö wa''ara dania, wa samuza zi döfi lafaigi ba Ndraono Gizeraeli wameta horöra fefu. Ba la''o''ö niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3480249, 'OT', 'Moze III', 17, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480249, 'OT', 'Moze III', 17, 2, 'Hede khö Ga''aroni ba ba ndraononia ba ba Ndraono Gizeraeli fefu, ömane khöra: Da''ö ia, ni''oroi''ö Yehowa:', '[]', NULL),
  (3480249, 'OT', 'Moze III', 17, 3, 'Dozi Iraono Gizeraeli, na so zanaba ono zaŵi, ba ma ono mbiri-biri, ba ma nambi, na ba golombaseŵa itaba, ba ma baero golombaseŵa,', '[]', NULL),
  (3480249, 'OT', 'Moze III', 17, 4, 'ba na lö i''ohe ba zinga mbawandruhö nose wama''ele''ö, ba wame''e sumange ya''ia khö Yehowa, föna nahia Yehowa andrö, ba tebe''e horönia fange''e: no aduwa ndro ibe''e, ba nise''e niha si manö ba niwara,', '[]', NULL),
  (3480249, 'OT', 'Moze III', 17, 5, 'ena''ö la''ohe Iraono Gizeraeli zumange nitaba andrö khöra, nibe''e-be''era sumange baero, ba mbenua; khö Yehowa la''ohe, ba zinga mbawandruhö nose wama''ele''ö, khö gere, ba lataba sumange fangorifi khö Yehowa.', '[]', NULL),
  (3480249, 'OT', 'Moze III', 17, 6, 'Ba itefe naha wame''e sumange khö Yehowa do andrö ere, föna mbawandruhö nose wama''ele''ö, ba tawö, ba itunu samohua khö Yehowa.[1]', '["Faigi 4:31"]', NULL),
  (3480249, 'OT', 'Moze III', 17, 7, 'Ba böi sa''ae labe''e sumange mbekhu, ba zohorö-horö ira, zumange nitaba andrö khöra. Huku si lö mamalö-malö khöra da''ö, götö-götö wa''ara dania.', '["Faigi 4:31"]', NULL),
  (3480249, 'OT', 'Moze III', 17, 8, 'Ba ömane khöra: Dozi ma''uwu Gizeraeli, awö niha bö''ö, si so ba khöra, na so zame''e sumange nitunu, ba ma sumange nitaba,', '[]', NULL),
  (3480249, 'OT', 'Moze III', 17, 9, 'ba na lö i''ohe ba zinga mbawandruhö nose wama''ele''ö, ba wame''e khö Yehowa, ba nise''e niha si manö, ba niwara.', '[]', NULL),
  (3480249, 'OT', 'Moze III', 17, 10, 'Ba dozi, he ma''uwu Gizeraeli, ba he niha bö''ö, si so ba khöra, na so zi manga ndro, ba si fa''udu ndra''o ba niha si manö, ba use''e ba niwara.', '["MozI 9:4,5; Faigi 7:27; SamI 14:33"]', NULL),
  (3480249, 'OT', 'Moze III', 17, 11, 'Noso nösi sa zi so ba ndro, ba no utehe khömi ba naha wame''e sumange, ena''ö labe''e fameta zalami; fameta zala sa ndro andrö, ba noso andrö khönia.[2]', '["MozI 9:4,5; Faigi 7:27; SamI 14:33"]', NULL),
  (3480249, 'OT', 'Moze III', 17, 12, 'Andrö wa no uŵa''ö ba Ndraono Gizeraeli: Samösa lö ba khömi zi tola manga ndro! He niha bö''ö, si so ba khömi, ba lö tola i''a ndro.', '["MozI 9:4,5; Faigi 7:27; SamI 14:33"]', NULL),
  (3480249, 'OT', 'Moze III', 17, 13, 'Ba dozi Iraono Gizeraeli, awö niha bö''ö, si so ba khöra, na so zahulu hadia ia ba ma fofo, si tola la''a, ba ifowöi ndro ba ibalugö tanö,', '["MozII 22:31"]', NULL),
  (3480249, 'OT', 'Moze III', 17, 14, 'me no ba ndro fangorifinia andrö so noso nösi fefu, hadia ia. Andrö wa no uŵa''ö ba Ndraono Gizeraeli: Lö tola mi''a ndro nösi, hadia ia, me ba ndro so noso nösi fefu, hadia ia — dozi si manga ya''ia, ba nihori.', '["MozII 22:31"]', NULL),
  (3480249, 'OT', 'Moze III', 17, 15, 'Ba dozi si manga gamatela, ba ma nisasawi [gutu ndru''u], he niha ba danö, ba he niha bö''ö, ba ibabago nukhania ba mondri, ba ra''iö, irege bongi; awena abeta wa''ara''iönia.[3]', '["MozII 22:31"]', NULL),
  (3480249, 'OT', 'Moze III', 17, 16, 'Ba na lö ibabago nukhania, ba na lö mondri, ba ilu''i horönia.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 2, 'Hede ba Ndraono Gizeraeli ba ömane khöra:', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 3, 'Böi mi''o''ö wolau ba danö Miserayi, ba zi so ami mege, ba böi göi mi''o''ö wolau ba danö Gana''ana, ba ni''ohegu ya''ami dania; böi mitörö huku khöra.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 4, 'Huku khögu mi''o''ö ba nifakhoigu mitöngöni ba mitörö; no ya''odo Yehowa, Lowalangimi.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 5, 'Andrö mitöngöni nifakhoigu, awö huku khögu: ba zolo''ö ya''ia möi fangorifi ia;', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 6, 'Böi yamuhatö''ö ia ha niha ba ndra alawe sabölö ahatö khönia, böi yamuheta mbalu-balu zaila ia; Yehowa ndra''odo.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 7, 'Saila namau ba saila ninau, ba tebai öheta mbalu-balu; no inau, lö tola öheta mbalu-balu zaila ia.[2]', '["MozI 19:33"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 8, 'Saila wo''omo namau, ba lö tola öheta mbalu-balu, no saila namau.[3]', '["Faigi 20:11; MozV 27:20"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 9, 'Saila nakhiu, ono namau, ba ma ono ninau, he ono yomo, ba he baero mege tumbu ia — lö tola öheta mbalu-balu zaila ia.[4]', '["MozV 27:22; SamII 13:14"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 10, 'Saila nono nonou matua ba saila nono nonou alawe — lö tola öheta mbalu-balu zaila ia; noa sa saila ndra''ugö.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 11, 'Saila nono wo''omo namau, ono namau — lö tola öheta mbalu-balu zaila ia; no talifusöu.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 12, 'Saila dalifusö namau alawe, ba lö tola öheta mbalu-balu; no fondrege zahatö khö namau.[5]', '["Faigi 20:19"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 13, 'Saila dalifusö ninau alawe, ba tebai öheta mbalu-balu, noa sa fondrege zahatö khö ninau.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 14, 'Saila dalifusö namau matua, ba tebai öheta mbalu-balu, lö tola öhatö''ögö khö wo''omonia; no inau.[6]', '["Faigi 20:20"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 15, 'Saila numönöu, ba tebai öheta mbalu-balu: no fo''omo nonou, tebai öheta mbalu-balu zaila ia.[7]', '["MozI 38:18; Hez 22:11"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 16, 'Saila wo''omo dalifusöu, ba tebai öheta mbalu-balu, no saila dalifusöu.[8]', '["Mat 14:4"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 17, 'Saila ndra alawe ba saila nononia alawe, ba tebai faoma öheta mbalu-balu; ono nononia matua ba ono nononia alawe, ba lö töla öhalö, wameta balu-balu zaila ia; no fondrege zahatö khöu ira — horö sebua da''ö.[9]', '["Faigi 20:14"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 18, 'Ba lö''ö göi tola öfakaerua zi fatalifusö, wamobörö fa''udusa, na öheta zaila ia, ba ngai zi sambua, fatua auri ia.[10]', '["MozI 29:27"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 19, 'Lö tola öhatö''ögö ba ndra alawe, ba wameta balu-balu zaila ia, götö wa''ara''iönia andrö.[11]', '["Faigi 20:18; Hez 22:10"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 20, 'Lö tola orudu ndra''ugö khö wo''omo nawöu, wangai fa''ara''iö khöu.[12]', '["Faigi 20:10; SamII 11:4"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 21, 'Lö tola öbe''e nonou, ba wame''e sumange Molokho andrö ya''ia, fa böi ö''o''aya döi Lowalangiu; Yehowa ndra''odo.[13]', '["Faigi 20:2; RazII 17:17"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 22, 'Lö tola orudu''ö ba ndra matua, lala wa''orudu ba ndra alawe; sogoro ita zi manö.[14]', '["MozI 19:5; Faigi 20:13; Rom 1:27"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 23, 'Ba zaliŵa-liŵa ba danö, ba lö tola orudu''ö, wangai fa''ara''iö khöu; ba ira alawe, ba lö tola i''edogö ia ba zaliŵa-liŵa ba danö, ena''ö urudu khönia; horö sebua zi manö.[15]', '["MozV 27:21"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 24, 'Ba da''ö fefu, ba böi mihalö wa''ara''iö khömi; noa sa da''ö fefu mbörö wa''ara''iö niha baero, nitimbagu fönami.[16]', '["RazII 17:15"]', NULL),
  (3480250, 'OT', 'Moze III', 18, 25, 'Ba da''ö ra''iö danö, ba ba khönia uhuku golalöŵania, tobali i''uta''ö zowanua ba khönia tanö.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 26, 'Ba mitöngöni sa''ae nifakhoigu andrö, awö huku andrö khögu, ba sambalö böi milau zogoro ita andrö, he niha ba danö, ba he niha bö''ö, si so ba khömi.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 27, 'Noa sa lafazökhi horö andrö fefu niha ba danö, fönami, ba no ra''iö danö;', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 28, 'fa böi i''uta''ö ami tanö, na ra''iö ami, mibe''e, si mane fanguta''önia soi niha andrö fönami.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 29, 'Ha niha sa zolau sambalö andrö, sogoro ita — ba nise''e ba niwara zolau ya''ia.', '[]', NULL),
  (3480250, 'OT', 'Moze III', 18, 30, 'Ba mi''o''ö nifakhoigu andrö, fa böi mi''ohia''ö huku andrö, sihokha mbuda, nilau fönami, wangai fa''ara''iö khömi; Yehowa ndra''odo, Lowalangimi.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 2, 'Hede ba mbanua Ndraono Gizeraeli fefu, ba ömane khöra:', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 3, 'Ya mu''ata''ufi ninania, awö namania zamösana ba mitöngöni luo wolombase andrö khögu; Yehowa ndra''odo, Lowalangimi.[2]', '["MozII 20:12; 31:13"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 4, 'Böi mi''otahögö nadu ba böi mifazökhi khömi Lowalangi nifahele, ya''odo Yehowa, Lowalangimi.[3]', '["MozII 34:17"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 5, 'Ba na mitaba zumange fangorifi khö Yehowa, ba mifaigi wame''e, ena''ö omasi ia ami.', '["Faigi 7:15"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 6, 'Na luo wame''emi ya''ia te''a ia, ba mahemolu ö; ba hadia zi tosai irege ba zi dua wongi, ba nitunu.[4]', '["Faigi 7:15"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 7, 'Ba na te''a zui ba zi dua wongi, ba no amaedola zobou, ba tenga omasiö.', '["Faigi 7:15"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 8, 'Ha niha zi manga, ba ihalö horönia; noa sa ilau zalakha ba ni''amoni''ö khö Yehowa, ba nise''e ba niwara niha si manö.', '["Faigi 7:15"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 9, 'Na mibasi mbua danö khömi, ba böi basi irege hinölu ba böi ozaragö nalöŵa, na no aefa wamasiu.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 10, 'Ba he wo''uwo''u ba kabu nagu khöu ba he bua satoru ba danö ba kabu nagu khöu, ba böi ozaragö: ölulu ba zi numana ba ba zi fatewu; ya''odo Yehowa, Lowalangimi.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 11, 'Böi managö ami ba böi mofaya ba böi falimo,[5]', '["MozII 20:15; Efes 4:25; Kol 3:9; TesI 4:6","MozII 20:7; Mat 5:33","MozV 24:15; Yak 5:4","MozV 27:18"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 12, 'Böi möi ba hölu, ba döigu, na faya, wango''aya töi Lowalangimö; Yehowa ndra''odo.[6]', '["MozII 20:15; Efes 4:25; Kol 3:9; TesI 4:6","MozII 20:7; Mat 5:33","MozV 24:15; Yak 5:4","MozV 27:18"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 13, 'Böi limo nawöu ba böi osindra''ui hadia ia khönia; luo genoni, ba lö tola ötaha irege mahemolu mbanua.[7]', '["MozII 20:15; Efes 4:25; Kol 3:9; TesI 4:6","MozII 20:7; Mat 5:33","MozV 24:15; Yak 5:4","MozV 27:18"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 14, 'Böi elifi zafiso ba böi ba''a lala zau''a; ö''ata''ufi Lowalangiu; Yehowa ndra''odo.[8]', '["MozII 20:15; Efes 4:25; Kol 3:9; TesI 4:6","MozII 20:7; Mat 5:33","MozV 24:15; Yak 5:4","MozV 27:18"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 15, 'Böi mifuyu''ö huku, na tefatunö huhuo; böi ö''awögö zi numana ba böi faigi-faigi mbawa zalaŵa, ö''atulö''ö wangefu''ö huku khö nawöu.[9]', '["MozV 1:17; 16:19","MozII 23:1","YohI. 2:11; 3:15; Mat 18:15","Mat 5:39; Rom 12:19; TesI 5:15; Yak 2:8"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 16, 'Böi samöbögö si lö duhu ndra''ugö ba niwamö ba böi andrö wamunu awöu; Yehowa ndra''odo.[10]', '["MozV 1:17; 16:19","MozII 23:1","YohI. 2:11; 3:15; Mat 18:15","Mat 5:39; Rom 12:19; TesI 5:15; Yak 2:8"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 17, 'Böi so ba dödöu watiusa khö dalifusöu; öfahede nawöu, böi aiwö''ö; böi öfalu''igö khöu horö, börö ia.[11]', '["MozV 1:17; 16:19","MozII 23:1","YohI. 2:11; 3:15; Mat 18:15","Mat 5:39; Rom 12:19; TesI 5:15; Yak 2:8"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 18, 'Böi omasi ndra''ugö wolau balö, ba böi be''e bu''u dödö ba niwau hadia ia. Ö''omasi''ö nawöu, si mane fangomasi''ömö ya''ugö; Yehowa ndra''odo.[12]', '["MozV 1:17; 16:19","MozII 23:1","YohI. 2:11; 3:15; Mat 18:15","Mat 5:39; Rom 12:19; TesI 5:15; Yak 2:8"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 19, 'Nifakhoigu, ba mitöngöni: lö tola ö''orudugö zi dua balö uriföu, ba wamo''ono, ba lö tola öfakhöyö zi dua balö sinanö ba nowiu, ba lö tola ö''obaru mbaru, si dua balö bana mege ba wanoso ya''ia.[13]', '["MozV 22:9"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 20, 'Na so zorudu ba ndra alawe, si no sawuyu niha bö''ö, si lö muhöli, si lö mu''efa''ö, ba nikhau ira; ba tenga sa nibunu, me no tenga ni''efa''ö ia.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 21, 'Ba i''ohe khö Yehowa, ba zinga mbawandruhö nose wama''ele''ö, ogautania mbiri-biri si matua, sumange fameta horö.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 22, 'Ba ifaigi khönia wameta sala khö Yehowa ere ba mbiri-biri andrö, sumange fameta horö, ba horö andrö, nifazökhinia; ba tebe''e aefa khönia horö andrö, nifazökhinia.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 23, 'Na mirugi dania danö, ba na mitanö ngawalö geu sowua, ba böi miteu gamaedola "guli" andrö — si a''a mbua —. Medölu fakhe wa''ara, ba si lö muboto miŵa''ö, ba lö tola te''a mbua.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3480251, 'OT', 'Moze III', 19, 24, 'Ba ba ndröfi fanete zi medölu fakhe, ba ni''amoni''ö mbuania fefu, fangandrö saoha gölö.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 25, 'Ba ba ndröfi fanete zi mendröfa, ba tola mi''a mbua, ena''ö tedou mbuania khömi; Yehowa ndra''odo, Lowalangimi.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 26, 'Böi mi''a hadia ia fabaya do. Böi faeta ami ba böi fakelemu.[14]', '["Faigi 3:17; MozV 18:10"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 27, 'Böi mi''ogaolo wanöwö bumi, ba böi mifalo''o gambimi.[15]', '["Faigi 21:5; Hez 44:20"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 28, 'Böi mikhoi nösimi, na so zi mate, ba böi misua gulimi; Yehowa ndra''odo.', '["Faigi 21:5; Hez 44:20"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 29, 'Böi be''e ba zalakha nonou alawe, wamarou ya''ia ba wohorö, ena''ö böi mohorö danö ba ena''ö böi anönö horö.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 30, 'Luo wolombase andrö khögu, ba mitöngöni, ba mi''ata''ufi ni''amoni''ö andrö khögu; Yehowa ndra''odo.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 31, 'Böi mi''ae ba zogawi bekhu ba ba zi faeta; böi misofu khöra hadia ia, fa böi ra''iö ami ba khöra mibe''e; Yehowa ndra''odo, Lowalangimi.[16]', '["Faigi 20:6; SamI 28:8"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 32, 'Na so zi no tohare huwa, ba maoso ndra''ugö ba öfosumange zatua ba ö''ata''ufi Lowalangimö; Yehowa ndra''odo.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 33, 'Ba na so zi fatewu khöu, ba danömi, ba böi mifakao ia.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 34, 'Ya si mane awömi niha ba danö niha bö''ö andrö, si so ba khömi, miŵa''ö, ö''omasi''ö ia, si mane fangomasi''ömö ya''ugö, noa sa si fatewu göi ami ba danö Miserayi no; Yehowa ndra''odo Lowalangimi.', '[]', NULL),
  (3480251, 'OT', 'Moze III', 19, 35, 'Böi mifuyu''ö huku, na tefatunö huhuo, ba böi falimo ba helo, ba ma ba zaga, ba ma ba lauru.[17]', '["MozV 25:15"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 36, 'Faliera satulö ba saga satulö ba lauru satulö ba tumba satulö mifake; Yehowa ndra''odo, Lowalangimi, si no mangeheta ya''ami ba danö Miserayi.', '["MozV 25:15"]', NULL),
  (3480251, 'OT', 'Moze III', 19, 37, 'Mitöngöni sa''ae nifakhoigu andrö, fefu, awö huku andrö khögu, fefu, ba mi''o''ö; Yehowa ndra''odo.', '[]', NULL),
  (3480252, 'OT', 'Moze III', 20, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480252, 'OT', 'Moze III', 20, 2, 'Öŵa''ö ba Ndraono Gizeraeli:', '[]', NULL),
  (3480252, 'OT', 'Moze III', 20, 3, 'Ba udunia ndra''odo, ba use''e ia ba niwania, börö me no ibe''e ba Molokho andrö nononia, ba wame''e ra''iö ni''amoni''ö andrö khögu, ba ba wango''aya töigu andrö, ni''amoni''ö.', '["Faigi 18:21"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 4, 'Ba na la''osilömilagö ena''ö niha ba danö nilau niha si manö, na ibe''e ba Molokho andrö nononia, fa lö labunu ia,', '["Faigi 18:21"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 5, 'ba udunia sa atö ndra''odo ba udu nga''ötönia, ba use''e ia ba niwara, fabaya dozi lolo''ö khönia, ba wame''e adu andrö, wamosumange Molokho andrö.', '["Faigi 18:21"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 6, 'Ba ha niha zi möi ba zogawi bekhu ba ba zi faeta, si no amaedola zohorö khöra, ba udunia ndra''odo ba use''e ia ba hunö niwara.[2]', '["Faigi 19, 31"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 7, 'Ba mi''amoni''ö ami, ena''ö ni''amoni''ö ami; Yehowa sa ndra''odo, Lowalangimi.', '[]', NULL),
  (3480252, 'OT', 'Moze III', 20, 8, 'Andrö mitöngöni nifakhoigu andrö, ba mi''o''ö; Yehowa ndra''odo, same''e ni''amoni''ö ya''ami.', '[]', NULL),
  (3480252, 'OT', 'Moze III', 20, 9, 'Dozi, ha niha zangelifi amania ba inania, ba huku mate hukunia; noa sa i''elifi namania ba inania — horö fange''e zi no tohare khönia.[3]', '["MozII 21:17"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 10, 'Ba na so zohoröni donga zodonga, ha niha zohoröni donga nawönia, ba huku mate hukura, he sohorö, ba he nihoröni andrö.[4]', '["Faigi 18:20; Yoh 8:5"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 11, 'Ba na so zorudu khö wo''omo namania, ba no iheta mbalu-balu zaila namania ba huku mate hukura, faoma darua ira; amaedola horö fange''e zi no tohare khöra.[5]', '["Faigi 18:8"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 12, 'Ba na so zohoröni umönönia, ba huku mate hukura, faoma darua ira; no horö sebua nifazökhira, amaedola horö fange''e zi no tohare khöra.[6]', '["Faigi 18:10"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 13, 'Ba na so zorudu ba ndra matua, si mane fa''orudu ba ndra alawe, ba no horö sebua nifazökhira, faoma darua ira, ba huku mate hukura, no amaedola horö fange''e zi no tohare khöra.[7]', '["Faigi 18:22"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 14, 'Ba na so zangai ira alawe ba na ihalö göi nina, ba horö sebua da''ö; nitunu auri ia, awö ndra alawe andrö, fa böi mamaha ba khömi horö.[8]', '["Faigi 18:17"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 15, 'Na so zohoröni saliŵa-liŵa ba danö ba huku mate hukunia, ba saliŵa-liŵa ba danö andrö göi, ba mibunu.[9]', '["Faigi 18:23"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 16, 'Ba na ihatö''ö ia ba zaliŵa-liŵa ba danö ira alawe, ena''ö orudu khönia, ba öbunu ndra alawe andrö, awö zaliŵa-liŵa ba danö andrö; huku mate hukura, no amaedola horö fange''e zi no tohare khöra.', '[]', NULL),
  (3480252, 'OT', 'Moze III', 20, 17, 'Ba na so zangai talifusönia, ono namania, ba ma ono ninania, na tobali i''ila zaila ia ba na i''ila göi da''ö zaila ndra matua, ba no salakha, ba nihori ira, ba zanehe niwara; no iheta mbalu-balu zaila dalifusönia ba no tohare khönia horö ibe''e.[10]', '["Faigi 18:9"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 18, 'Ba na so zorudu ba ndra alawe götö wa''afökhö dalunia, na iheta mbalu-balu zaila ia, balu-balu gumbu andrö khönia, ba na ya''ia göi zangeheta balu-balu gumbu ndro andrö khönia, ba nihori ira ba hunö niwara, faoma darua ira.[11]', '["Faigi 18:19"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 19, 'Saila dalifusö ninau ba saila dalifusö namau, ba tebai öheta mbalu-balu; sangeheta balu-balu wondrege zahatö khönia zi manö, ba no tohare khöra horö labe''e.[12]', '["Faigi 18:12"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 20, 'Ba na so zorudu khö wo''omo dalifusö namania, ba no iheta zaila dana namania, ba no tohare khöra horö labe''e — si mate lö ono ira.[13]', '["Faigi 18:14"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 21, 'Ba na so zangai fo''omo dalifusönia, ba salakha da''ö; no sangeheta saila dalifusönia ia — si mate lö ono ira.[14]', '["Faigi 18:16"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 22, 'Ba mitöngöni sa''ae nifakhoigu andrö, fefu, awö huku andrö khögu, fefu, ba mi''o''ö, fa böi i''uta''ö ami tanö, ba ni''ohegu ya''ami dania, ena''ö mowanua ami ba da''ö.', '["Faigi 18:28"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 23, 'Böi mi''o''ö huku niha andrö, nitimbagu fönami, me no lalau da''ö fefu, irege ogorodo ira.[15]', '["Faigi 18:28"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 24, 'Andrö wa umane khömi: Khömi dania danöra, ube''e okhötami — tanö si falawu susu ba ŵe ŵani, ya''odo andre, Yehowa, Lowalangimi, si no mangoniagö ya''ami ba niha baero.', '["Faigi 18:28"]', NULL),
  (3480252, 'OT', 'Moze III', 20, 25, 'Ba mifaehusi sa''ae ira zi öfa ahe salakha zi tenga salakha, ba he fofo salakha ba si tenga salakha, ba böi mibe''e ni''ogorofi ami ba zi öfa ahe, ba ma ba wofo, ba ma ba ngawalö hadia ia, saliŵa-liŵa ba danö, ni''oniagögu, ena''ö salakha ia miŵa''ö.', '[]', NULL),
  (3480252, 'OT', 'Moze III', 20, 26, 'Ba ni''amoni''ö ami khögu, me no ni''amoni''ö ndra''o, ya''odo andre Yehowa, ba no u''oniagö ami ba niha baero, ena''ö tana khögu ami.', '[]', NULL),
  (3480252, 'OT', 'Moze III', 20, 27, 'Ba na so ndra matua, ba ma ira alawe si so bekhu ba wogawi bekhu bö''ö, ba ma si so bekhu waetasa, ba huku mate hukura, nitebu kara; no horö fange''e, si tohare khöra.', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 1, 'Ba imane Yehowa khö Moze: Be''e li ba gere andrö, iraono Ga''aroni, ömane khöra:', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 2, 'Ha sahatö khönia, fondrege zahatö, inania ba amania ba ononia matua ba ononia alawe ba talifusönia matua,', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 3, 'ba talifusönia alawe, sahatö khönia, ono alawe, si lö muhalö na — ha da''ö zi tola ihalö fa''ara''iönia.', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 4, 'Lö tola ibe''e ra''iö ia ba niwara, wanörö salakha khönia.', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 5, 'Lö tola latöwö galizuzura ba lö tola lafalo''o gambira ba he fogoi ösira, ba lö tola.[1]', '["Faigi 19:27,28"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 6, 'Ni''amoni''ö khö Lowalangira ira, ba böi la''o''aya döi Lowalangira, me same''e sumange Yehowa ira, sumange nifatörö ba galitö, ö Lowalangira, andrö wa ni''amoni''ö ira.', '["Faigi 19:27,28"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 7, 'Sohorö-horö ba si no muhoröni, ba tebai la''owalu, ba he ira alawe nitibo''ö ndra matua, ba lö tola lahalö, me no ni''amoni''ö khö Lowalanginia gere.[2]', '["Hez 44:22"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 8, 'Andrö wa ni''amoni''ö ia khöu, me ya''ia zame''e gö Lowalangiu; ni''amoni''ö ia öŵa''ö; me no ni''amoni''ö ndra''o, ya''odo andre, Yehowa, same''e ni''amoni''ö ya''ami.', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 9, 'Ba na ibörötaigö mohorö nono gere alawe, ba salakha namania ibe''e, nitunu auri ia.', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 10, 'Ba si no ere sebua ba dalifusönia, si no mulau ba högö fanikha famayoini andrö, si no mufo''ösi tanga ba si no mufonukha nukha [ni''amoni''ö] andrö, ba lö tola ifehombo mbunia ba lö tola itika nukhania.[3]', '["MozII 28:41","MozII 28:38"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 11, 'Lö tola möi ia yomo si so si mate; amania na''i ba inania, ba lö tola ibe''e fa''ara''iönia.', '["MozII 28:41","MozII 28:38"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 12, 'Lö tola iröi ni''amoni''ö andrö, fa böi ifatörö zalakha ba ni''amoniö andrö khö Lowalanginia; noa sa tohare khönia we''amoni''ö andrö ba wanikha famayoini andrö khö Lowalanginia; Yehowa ndra''odo.[4]', '["MozII 28:41","MozII 28:38"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 13, 'Si ndruhu nono alawe ihalö fo''omonia,', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 14, 'lakha ba nitibo''ö ba si no muhoröni ba sohorö-horö, ba lö tola ihalö; ha ono alawe iwara, zi tola ihalö fo''omonia,', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 15, 'fa böi salakha nga''ötönia ba niwara ibe''e; Yehowa sa ndra''odo, same''e ni''amoni''ö ya''ia.', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 16, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 17, 'Hede khö Ga''aroni, ömane:', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 18, 'Ha niha sa zi so hadia ia zi sala ba nösinia, ba lö tola möi, he sau''a, ba he sombuyu-mbuyu töla ba he si so saböda, ba he sanau ndroto-ndroto, zara,', '["Heb 7:26"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 19, 'ba he safatö ahe,', '["Heb 7:26"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 20, 'ba he safatö ta''io, ba he sa''ebu, ba he si no afuofuo, ba he si bidöyö, ba he soböni, ba he si so gigimö bö''ö, ba he sabao bazili.', '["Heb 7:26"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 21, 'Samösa lö''ö si tola möi, nga''ötö Ga''aroni, si so si sala ba nösinia, ba wame''e sumange Yehowa andrö, nifatörö ba galitö; na so zi sala ba nösinia, ba lö tola möi ia, ba wame''e gö Lowalanginia.[5]', '["Heb 7:26"]', NULL),
  (3480253, 'OT', 'Moze III', 21, 22, 'Ba tola sa i''a wöfö gö Lowalanginia, he ni''amoni''ö sibai andrö, ba he ame''ela andrö ni''amoni''ö.', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 23, 'Ha fa lö tola möi ia bakha barö mba''a-ba''a andrö, ba lö tola ihatö''ö ia ba naha wame''e sumange, me no so zi sala, ba nösinia; fa böi ifatörö zalakha ba ni''amoni''ö andrö khögu; me no Yehowa ndra''odo, same''e ni''amoni''ö ya''ia.', '[]', NULL),
  (3480253, 'OT', 'Moze III', 21, 24, 'Ba iŵa''ö da''ö Moze khö Ga''aroni ba ba ndraononia ba ba Ndraono Gizeraeli fefu.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 2, 'Ŵa''ö khö ndra A''aroni iraononia, ndramu''onangegö ba game''ela Ndraono Gizeraeli andrö, ni''amoni''ö, ni''amoni''öra khögu, fa böi la''o''aya döigu andrö ni''amoni''ö; Yehowa ndra''odo.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 3, 'Ömane khöra:', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 4, 'Ha niha ba nga''ötö Ga''aroni zobou auri ba ha niha zi so si hulö zonana no, ba lö tola i''a wöfö game''ela ni''amoni''ö andrö, irege ifuli aheta khönia wa''ara''iönia andrö. Na so zi no mombambaya si no ra''iö ba zi mate, ba ma si no ahele ula,[1]', '["Faigi 15:16"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 5, 'ba ma si no mombambaya kuö-kuö, fangara''iönia, ba ma niha, fangara''iönia, na so hadia ia wa''ara''iö ba niha andrö,', '["Faigi 15:16"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 6, 'ha niha zombambaya si mane da''ö, ba si ra''iö, irege bongi, ba lö tola i''a wöfö game''ela ni''amoni''ö andrö, na lö mondri ia ua.', '["Faigi 15:16"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 7, 'Ba ha si''ai aekhu luo, ba lö''ö sa''ae fa''ara''iö; awena tola i''a wöfö game''ela andrö ni''amoni''ö, önia sa atö da''ö.', '["Faigi 15:16"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 8, 'Amatela ba nisasawi [gutu ndru''u], ba lö tola i''a, fa ihalö fa''ara''iönia; Yehowa ndra''odo.[2]', '["MozII 22:31"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 9, 'Ba la''o''ö sa''ae nifakhoigu andrö, fa böi lahare''ö khöra horö ba da''ö, ba fa böi möi famunura, na lalau zalakha khönia; Yehowa ndra''odo, same''e ni''amoni''ö ya''ira.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 10, 'Niha bö''ö, ba lö tola i''a ni''amoni''ö, samösa lö''ö; si fatewu khö gere ba enoninia, ba lö tola la''a ni''amoni''ö.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 11, 'Ba na ihöli zawuyu ere, ba tola i''a wöfö da''ö; si manö göi zi tumbu yomo khönia — ya''ira zi tola manga wöfö gönia.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 12, 'Ono gere alawe, nihalö niha bö''ö, ba lö tola i''a wegero andrö, nihalö ba game''ela andrö ni''amoni''ö.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 13, 'Ba ono gere alawe, si no mate ira matua, ba ma na nitibo''ö ia, ba si lö ono, sangawuli khö ndra amania, si mane me iraono ia, ba tola i''a wöfö gö namania; ba niha bö''ö, ba lö''ö manö tola i''a da''ö.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 14, 'Ba na so zi manga ni''amoni''ö si tenga ni''odödögö, ba sambua ni''olima inönö, ba ifuli khö gere, awö ni''amoni''ö andrö.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 15, 'Ba ya''ira andrö [ere], ba böi lalau zalakha ba game''ela Ndraono Gizeraeli andrö ni''amoni''ö — nihalöra si no amaedola wegero khö Yehowa —,', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 16, 'fa böi lahare''ö khöra horö ba lalöra andrö, na la''a game''elara andrö, ni''amoni''ö; Yehowa sa ndra''odo, same''e ni''amoni''ö ya''ira.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 17, 'Ba humede Yehowa khö Mose, imane:', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 18, 'Hede khö ndra A''aroni iraononia ba ba Ndraono Gizeraeli fefu, ba ömane khöra:', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 19, 'ba [mifaigi] ena''ö ni''omasi''ö ami ibe''e: urifö si lö sala, si matua, saŵi, ba ma ono mbiri-biri, ba ma nambi.', '["Mal 1:8"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 20, 'Si so si sala hadia ia, ba lö tola mibe''e; lö''ö sa ibe''e omasiö ami ena''ö.[3]', '["Mal 1:8"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 21, 'Ba na so zame''e khö Yehowa sumange fangorifi, saŵi, ba ma biri-biri, he ba wanörö amabu''ula li, ba he na saoha gölö, ba si lö sala nibe''e, ena''ö omasiö ia ibe''e; lö tola so hadia ia zi sala ba khönia.', '["MozV 15:21"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 22, 'Si lö hörö ba si no afatö ndroto-ndroto zara ba si no mesokho ba sofaosa ba si so gigimö hadia ia, ba lö tola mibe''e khö Yehowa zi manö, ba lö tola mibe''e ba naha wame''e sumange, sumange Yehowa, nifatörö ba galitö.[4]', '["MozV 15:21"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 23, 'Ba saŵi, ba ma biri-biri si töra fa''anau gahe, ba ma si töra fa''adogo-dogo ba tola öbe''e saoha gölö; ba na mibe''e sumange amabu''ula li ena''ö, ba lö ibe''e omasiö ami.', '["MozV 15:21"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 24, 'Ba he si no aboto bazili; ba ma si no murasa, ba ma si no mu''etu''ö, ba ma si no mufölö, ba lö tola mibe''e khö Yehowa. Lö tola mibali''ö si manö hadia ia, ba danömi,', '["MozV 15:21"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 25, 'ba lö''ö göi tola mihalö ba niha bö''ö, nibe''e ö Lowalangimi; noa sa molemba khöra zi sala — sambö zolemba khöra — andrö wa lö labe''e omasiö ami.', '["MozV 15:21"]', NULL),
  (3480254, 'OT', 'Moze III', 22, 26, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 27, 'Na so zi tumbu, ma ono zaŵi, ba ma ono mbiri-biri, ba ma ono nambi, ba fitu bongi labe''e nifaenu ninania, ba na no aefa zi fitu bongi ba na ara moroi andrö, ba omasiö na tebe''e sumange Lowalangi, nifatörö ba galitö.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 28, 'Saŵi ba biri-biri, ba lö tola mi''endrongagö khö nononia wanaba ya''ia, si ha ma''ökhö.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 29, 'Ba na mibe''e khö Yehowa zumange fangandrö saoha gölö, ba mifaigi, ena''ö omasiö ami ibe''e.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 30, 'Na luo da''ö te''a ia; lö tola misaigö hadia ia, irege mahemolu mbanua; Yehowa ndra''odo.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 31, 'Ba mitöngöni sa''ae goroisagu andrö, ba mi''o''ö; Yehowa ndra''odo.', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 32, 'Ba böi mi''o''aya döigu andrö, ni''amoni''ö, ena''ö ni''amoni''ö ndra''o ba hunö Ndraono Gizeraeli; Yehowa ndra''odo, same''e ni''amoni''ö ya''ami,', '[]', NULL),
  (3480254, 'OT', 'Moze III', 22, 33, 'si no mangeheta ya''ami ba danö Miserayi, ba we''amöi Lowalangimi — ya''odo andre, Yehowa.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 2, 'Hede ba Ndraono Gizeraeli, ba ömane khöra:', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3480255, 'OT', 'Moze III', 23, 3, 'Önö ngaluo wa''ara, ba tola tehalö-halö halöŵö; ba luo si fitu andrö, ba baŵa wolombase manö, ba owuloa ba ni''amoni''ö andrö; sambalö lö tola mihalö halöŵö ba da''ö, ba nahiami fefu, — bawa wolombase ia khö Yehowa.[1]', '["MozII 20:10; 23:12"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 4, 'Da''ö mbaŵa gowasa khö Yehowa, baŵa gowuloa ba ni''amoni''ö, nifarongogömi, na no irugi inötö:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 5, 'Ba mbaŵa si föföna, ba zi meweleöfa, na tanö owi, ba fasa khö Yehowa.[2]', '["MozII 12:18,43; MozIV 28:16; MozV 16:1"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 6, 'Ba ba zi mewelelima ba mbaŵa da''ö, ba owasa roti si lö mu''aisöni khö Yehowa; fitu bongi wa''ara mi''a roti si lö mu''aisöni.', '["MozII 12:18,43; MozIV 28:16; MozV 16:1"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 7, 'Ba mböröta mbaŵa da''ö, ba owuloa khömi ba ni''amoni''ö, ba lö tola mihalö hadia ia halöŵö, na luo da''ö.', '["MozII 12:18,43; MozIV 28:16; MozV 16:1"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 8, 'Ba fitu bongi wa''ara mibe''e-be''e zumange Yehowa, nifatörö ba galitö; ba na luo si fitu, ba owuloa zui ba ni''amoni''ö andrö; ba sambalö lö tola mihalö halöŵö na luo da''ö.', '["MozII 12:18,43; MozIV 28:16; MozV 16:1"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 9, 'Ba humede Yehowa khö Mose, imane:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 10, 'Hede ba Ndraono Gizeraeli, ba ömane khöra:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 11, 'föna Yehowa, ena''ö omasiö ami ibe''e; sara wongi aefa sabato ihahae ere.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 12, 'Ba na luo ihahae ngamböbö andrö, ba mibe''e nono mbiri-biri si lö sala, si döfi fa''ebua, sumange nitunu, khö Yehowa,', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 13, 'ba sambua ni''ofulu hamo si sökhi, nifaruka fanikha, sumange ni''a, sumange nifatörö ba galitö, samohua khö Yehowa, awö zumange nibadu, samba selefe agu.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 14, 'Ba roti ba böra nifaköe ba he nifufu, ba lö tola mi''a, irege luo da''ö, irege no mibe''e zumange andrö khö Lowalangimi. Amakhoita si lö tebulö da''ö, götö-götö wa''ara dania, nitörömi, götö-götö wa''ara mitou, ba nahiami fefu.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 15, 'Ba mi''erai dania mbongi, i''otarai luo andrö na aefa zabato andrö, ba nibe''emi ngamböbö nihahae andrö, alo''o fitu migu,[3]', '["MozV 16:9"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 16, 'irege luo aefa luo sabato si fitu mi''erai, 50 wongi, ba mibe''e khö Yehowa zumange ni''a, fakhe si bohou andrö.', '["MozV 16:9"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 17, 'Samba omo ami, ba dombua mibe''e roti nihahae; roti si dombua ni''ofulu hamo si sökhi mege, ba nibe''e tanömö roti ba wamogö ya''ia, si a''a zumange khö Yehowa.', '["MozV 16:9"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 18, 'Ba awö roti andrö, ba mibe''e: fitu rozi nono mbiri-biri si lö sala, si döfi fa''ebua, ba sageu nono zaŵi si matua, ba dua geu mbiri-biri si matua, ni''ohe sumange nitunu khö Yehowa da''ö, awö zumange ni''a andrö ba sumange nibadu, si faböbö ba da''ö, sumange nifatörö ba galitö, samohua khö Yehowa.', '["MozV 16:9"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 19, 'Ba awö da''ö ba sageu mibe''e nambi si matua, sumange fameta horö, ba dua rozi nono mbiri-biri, si döfi fa''ebua, sumange fangorifi.', '["MozV 16:9"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 20, 'Ba ihahae ere, awö zi a''a roti andrö, sumange nihahae föna Yehowa, awö nono mbiri-biri andrö, zi dua rozi; ni''amoni''ö khö Yehowa da''ö, ba tana khö gere.', '["MozV 16:9"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 21, 'Ba na luo da''ö mifarongogö — milau gowuloa ba ni''amoni''ö; ba sambalö lö tola mihalö halöŵö na luo da''ö. Amakhoita si lö tebulö da''ö, götö-götö wa''ara dania, nitöngönimi ba nahiami fefu, götö-götö wa''ara.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 22, 'Ba na mibasi mbua danö, ba böi öbasi nowi irege hinölu ba böi ö''ozaragö nalöŵa, na no aefa wamasiu: faoma ölulu ba zi numana ba ba zi fatewu; Yehowa ndra''odo, Lowalangimi.[4]', '["Faigi 19:9"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 23, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 24, 'Hede ba Ndraono Gizeraeli, ömane:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 25, 'Sambalö lö tola mihalö halöŵö na luo da''ö, ba mibe''e khö Yehowa zumange nifatörö ba galitö.', '["MozIV 29:1"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 26, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 27, 'Ba si mewulu ba mbaŵa si fitu andrö, ba baŵa wangatulö; milau gowuloa ba ni''amoni''ö na luo da''ö, ba mangalulu ami, ba mibe''e khö Yehowa zumange nifatörö ba galitö.[6]', '["Faigi 16:29; MozIV 29:7"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 28, 'Ba na luo da''ö, ba sambalö lö tola mihalö halöŵö, me baŵa wangatulö, ena''ö lafaigi khömi wameta sala khö Yehowa, Lowalangimi.', '["Faigi 16:29; MozIV 29:7"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 29, 'Ha niha sa zi lö mangalulu, na luo da''ö, ba nise''e ba niwara.', '["Faigi 16:29; MozIV 29:7"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 30, 'Ba ha niha zangai hadia ia halöŵö, na luo da''ö, ba uhori ba hunö niwara.', '["Faigi 16:29; MozIV 29:7"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 31, 'Lö tola mihalö hadia ia halöŵö, na luo da''ö; amakhoita si lö tebulö da''ö, götö-götö wa''ara dania, ba nga''önga''ötö mitou, ba nahiami fefu.', '["Faigi 16:29; MozIV 29:7"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 32, 'Baŵa wolombase manö miŵa''ö ba mangalulu ami. Bongibongi ba zi meziŵa ba mbaŵa da''ö — i''otarai na bongibongi, irugi bongibongi mahemolu — ba mitöngöni wolombase andrö niŵa''ö.', '["Faigi 16:29; MozIV 29:7"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 33, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 34, 'Hede ba Ndraono Gizeraeli, ömane:', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 35, 'Ba mböröta ngaluo da''ö, ba owuloa ba ni''amoni''ö; sambalö lö tola mihalö halöŵö, na luo da''ö.', '["MozII 23:16; MozIV 29:12; MozV 16:13","Yoh 7:37"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 36, 'Fitu bongi wa''ara ba mibe''e-be''e zumange Yehowa, nifatörö ba galitö; ba na luo si ŵalu, ba milau gowuloa ba ni''amoni''ö ba mibe''e zumange Yehowa, nifatörö ba galitö — owuloa na luo da''ö, ba lö tola mihalö hadia ia halöŵö.[8]', '["MozII 23:16; MozIV 29:12; MozV 16:13","Yoh 7:37"]', NULL),
  (3480255, 'OT', 'Moze III', 23, 37, 'Da''ö ginötö gowasa andrö, nifarongogömi owuloa ba ni''amoni''ö, ena''ö labe''e zumange Yehowa, nifatörö ba galitö — sumange nitunu ba sumange ni''a ba sumange nitaba ba sumange nibadu, balazi mbaŵa nibe''e ya''ia,', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 38, 'lö lai zabato andrö khö Yehowa ba lö lai game''elami andrö ba he sumange amabu''ula li khömi, fefu, ba he ame''elami saoha gölö, fefu, nibe''emi khö Yehowa.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 39, 'Ba ba zi mewelelima ba mbaŵa si fitu andrö, na mibasi mbua danö, ba fitu ngaluo milau gowasa andrö khö Yehowa; luo si föföna, ba luo wolombase ba si manö göi luo si ŵalu.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 40, 'Ba na luo si föföna andrö, ba mihalö khömi mbua geu si sökhi ba bulu nohi ba daha geu sarege bulu ba daha mbou ba fitu bongi wa''ara omuso dödömi föna Lowalangimi Yehowa,', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 41, 'ba ero röfi milau ia, owasa khö Yehowa, fitufitu bongi wa''ara; amakhoita si lö tebulö da''ö, götö-götö wa''ara dania, nitöngönimi götö-götö wa''ara: ba mbaŵa si fitu milau ia.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 42, 'Ba nose daha geu soso ami ba da''ö, fitu bongi wa''ara; dozi niha ba danö, Iraono Gizeraeli, ba baose soso,', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 43, 'ena''ö aboto ba dödö nga''ötömi dania, wa no baose ufa''aso Ndraono Gizeraeli, me uheta ira ba danö Miserayi, ya''odo andre, Yehowa, Lowalangimi.', '[]', NULL),
  (3480255, 'OT', 'Moze III', 23, 44, 'Ba i''ombakha''ö ba Ndraono Gizeraeli ginötö gowasa andrö khö Yehowa Moze.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 2, 'Ŵa''ö ba Ndraono Gizeraeli, ndramu''ohe khöu zi ndruhu wanikha mbua zai nifufu, fanikha wandru andrö, ena''ö böi mate-mate wandru.[1]', '["MozII 27:20"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 3, 'Baero mba''a-ba''a, fomba''a zura goroisa, ba nose wama''ele''ö, ibe''e A''aroni, böi tebulö föna Yehowa, i''otarai na bongi, irugi moluo. Amakhoita si lö tebulö da''ö, götö-götö wa''ara dania, nitöngönimi, götö-götö wa''ara.', '["MozII 27:20"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 4, 'Ba naha wandru andrö, si ndruhu mbalaki, ibe''e wandru andrö, si lö tebulö föna Yehowa.', '["MozII 27:20"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 5, 'Ba öhalö hamo si sökhi ba öbali''ö kue, felendrua nga''örö — dombua ni''ofulu zagörö kue —', '["MozII 29:32; SamI 21:6; Mat 12:4"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 6, 'ba öbahogö ba meza si ndruhu mbalaki andrö, föna Yehowa, dombua baho, önö''önö nga''örö zambua baho.', '["MozII 29:32; SamI 21:6; Mat 12:4"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 7, 'Ba sambu-sambua baho, ba öfao zi ndruhu gumöyö, samobua da''ö, awö roti andrö, amaedola zumange nifatörö ba galitö, nibe''e khö Yehowa.', '["MozII 29:32; SamI 21:6; Mat 12:4"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 8, 'Ero na luo sabato ibahogö föna Yehowa, böi mamalö-malö, ömö Ndraono Gizeraeli, si lö tebulö, götö-götö wa''ara dania.', '["MozII 29:32; SamI 21:6; Mat 12:4"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 9, 'Ba ö ndra A''aroni iraononia dania ena''ö ba naha ni''amoni''ö la''a; tana khönia sa, ni''amoni''ö sibai, föfö zumange andrö, nifatörö ba galitö; huku si lö tebulö, götö-götö wa''ara dania.[2]', '["MozII 29:32; SamI 21:6; Mat 12:4"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 10, 'Ba möi ba Ndraono Gizeraeli nono Ndraono Gizeraeli ira alawe — Dawa Miserayi namania — ba fasoso da''ö ba Ndraono Gizeraeli bö''ö samösa.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 11, 'Ba i''o''aya döi Yehowa ono Ndraono Gizeraeli ira alawe andrö ba mangelifi; ba la''ohe ia khö Moze (töi ninania, ba Selomita, ono Dibiri, mado Dano).', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 12, 'Ba lakuru ia, irege larongo lala, niŵa''ö Yehowa.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 13, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 14, 'Fa''ohe''ö baero golombaseŵa zangelifi andrö, ba dozi samondrongo mege, ba latufa högönia tangara, ba awena labunu ia, latebu kara sato fefu.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 15, 'Ba ba Ndraono Gizeraeli, ba ömane: Ha niha zangelifi khö Lowalanginia, ba ilu''i horönia.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 16, 'Ba sango''aya töi Yehowa, ba huku mate hukunia; lö''ö sa tola lö latebu kara ia sato fefu. He si fatewu, ba he niha ba danö na i''o''aya döi Yehowa, ba nibunu.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 17, 'Na so zamunu niha, ba huku mate hukunia.[3]', '["MozII 21:12"]', NULL),
  (3480256, 'OT', 'Moze III', 24, 18, 'Na so zamunu urifö zageu, ba i''ali — noso wangali noso.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 19, 'Na so zamesokho awönia, ba nisulöni khönia nilaunia:', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 20, 'Safatö wangali zafatö, hörö wangali hörö, boha wangali mboha; nilaunia khö nawönia, da''ö nilau khönia.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 21, 'Samunu urifö [sageu], ba i''ali; ba samunu niha, ba nibunu göi.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 22, 'Ha sara huku nibe''e ba khömi, he ba zi fatewu, ba he ba niha ba danö; Yehowa sa ndra''odo, Lowalangimi.', '[]', NULL),
  (3480256, 'OT', 'Moze III', 24, 23, 'Ba humede Moze ba Ndraono Gizeraeli; ba la''ohe baero golombaseŵa zangelifi no mege ba latebu kara. La''o''ö Iraono Gizeraeli ni''oroi''ö Yehowa khö Moze.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 1, 'Ba humede Yehowa khö Moze ba hili Zina''i, imane:', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 2, 'Hede ba Ndraono Gizeraeli ba ömane khöra:', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 3, 'Me önö fakhe wa''ara öhalö-halö danö nowi ba ögutiguti nagu khöu, ba ö''ozaragö mbua.', '["MozII 23:11","MozV 15:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 4, 'Ba ba ndröfi si fitu, ba mosabato danö, sabato khö Yehowa. Ba lö tola öhalö nowiu ba da''ö ba lö tola ogutiguti nagu khöu.', '["MozII 23:11","MozV 15:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 5, 'Ba hadia zowua manö, aefa wamasiu mege, ba lö tola öbasi, ba bua nagu andrö, si lö mugutiguti, ba lö tola ö''ozaragö, me döfi sabato ba danö.[2]', '["MozII 23:11","MozV 15:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 6, 'Hadia mbua danö götö wolombase andrö, ba ömi — öu, ba ö zawuyumö, ono matua ba ono alawe, ba ö genoniu, ba ö zi fatewu khöu, yomo khöu.', '["MozII 23:11","MozV 15:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 7, 'Ba ö guriföu göi ba ö gutu ndru''u ba danömi fefu mbua danö andrö.', '["MozII 23:11","MozV 15:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 8, 'Ba ö''erai ndröfi sabato andrö, fitu — mewitu wa fitu fakhe, tobali öfa wulu a siŵa fakhe götö ndröfi sabato si fitu.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 9, 'Ba ba da''ö öfalau''ö dorofe, ba zi mewulu ba mbaŵa si fitu; na baŵa wangatulö andrö, ba sagörö tanö mifalau''ö dorofe,', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 10, 'ba mi''amoni''ö ndröfi si lima wulu andrö, mifarongogö ba da''ö wa''aefa, fa''aefa niha fefu ba danö. Döfi wa''owua-wua dödö miŵa''ö, ba dozi ami, ba mangawuli khömi gokhötami, ba mangawuli ba niwara zamösana.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 11, 'Döfi wa''owua-wua dödö ia, miŵa''ö, ndröfi si lima wulu andrö. Ba lö tola manaru ami ba da''ö, ba lö tola mibasi zowua manö, ba he bua nagu andrö, si lö mugutiguti, ba lö tola mi''ozaragö.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 12, 'Me no döfi wa''owua-wua dödö, ba ni''amoni''ö ia, miŵa''ö. Moroi ba danö mi''a mbuania.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 13, 'Da''ö ndröfi wa''owua-wua dödö andrö, ba zangawuli ba zamösana okhötania.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 14, 'Na so ni''amawau khö nawöu, ba ma na ö''öli hadia ia khö nawöu, ba faoma böi mibe''e te''ala nawömi.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 15, 'Balazi ha me uga fakhe aefa ndröfi wa''owua-wua dödö, na ö''öli hadia ia khö nawöu, ba balazi ha me uga fakhe mamasi na, na i''amawa khöu.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 16, 'Na oya na ndrofi, ba ö''ebua''ö khönia mböli, ba na ambö fa''oya, ba ö''ambösi nibe''e; ha me uga famasi sa i''amawa khöu.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 17, 'Böi yamube''e te''ala nawönia zamösana; ata''ufi Lowalangiu, me no Yehowa ndra''odo Lowalangimi.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 18, 'Andrö mi''o''ö nifakhoigu, mitöngöni huku andrö khögu ba mi''o''ö, ena''ö lö hadia ia khömi ba danö.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 19, 'Ba mowua dania danö, ena''ö abuso ami ba ena''ö lö hadia ia khömi ba danö.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 20, 'Ba na miŵa''ö ena''ö: Hadia göma ba ndröfi si fitu andrö, na lö manaruga ba na lö tola ma''ozaragö mbua danö?', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 21, 'ba na döfi si önö andrö, ba ube''e li ba howu-howu andrö khögu, ena''ö ndrohu-ndrohu ba zi medölu fakhe misöndra khönia, ibe''e.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 22, 'Ba na manaru ami, na döfi si ŵalu, ba mi''aga''aga mbua danö mege; irugi ba ndröfi si siŵa — tobali mi''aga''aga zi tohöna, irege so zi bohou.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 23, 'Tanö, ba lö tola mi''amawa tenga sanutö, me no khögu danö, niha bö''ö sa ami ba si fatewu khögu.', '["Rut 4:4; Yer 32:7"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 24, 'Andrö mitehe wananu benua, fefu gofu heza ba danö andrö, si no möi tanömi.', '["Rut 4:4; Yer 32:7"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 25, 'Na tobali numana dalifusöu, ba na i''amawa osa mbenuania, ba yamöi sananu, salahinia, wondrege zahatö khönia, yamusanu ni''amawa dalifusönia andrö.[3]', '["Rut 4:4; Yer 32:7"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 26, 'Ba na so zi lö sananu, ba na i''ila i''alui ndrohu-ndrohu wananu,', '["Rut 4:4; Yer 32:7"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 27, 'ba yamusöbi ndröfi andrö aefa wamawa, ba hadia zi tosai, ba yamufuli ba ni''amawania ya''ia, ena''ö mangawuli khönia gokhötania.', '["Rut 4:4; Yer 32:7"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 28, 'Ba na lö isöndra zoguna fananu, ba lö tebulö khö zowöli ni''amawania andrö, irege döfi wa''owua-wua dödö andrö; ba da''ö dania aefa, tobali mangawuli khönia gokhötania andrö.', '["Rut 4:4; Yer 32:7"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 29, 'Ba na so zamawa omo, bakha barö göli mbanua, ba tola ifuli isanu na barö ndröfi andrö, ni''amawania ya''ia; irege da''ö lafonoso ia, ba wananu.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 30, 'Ba na lö musanu irege alua ndröfi; ba tetutu danö ba zowöli andrö ba ba nga''ötönia, ba nomo andrö, bakha barö göli mbanua, ba lö''ö sa''ae mangawuli ba ndröfi wa''owua-wua dödö andrö.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 31, 'Ba omo ba mbanua side-ide, si lö mufasui öli, ba si faböbö ba mbenua miŵa''ö; tola nisanu, ba mangawuli na döfi wa''owua-wua dödö andrö.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 32, 'Ba ba nomo nono Lewi andrö — omo ba mbanua misa, khöra — ba tetehe ba nono Lewi wananu, gofu ha wa''ara.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 33, 'Ba na so nono Lewi si lö mananu ya''ia, ba mangawuli khönia nomo andrö, ni''amawania, na döfi wa''owua-wua dödö andrö, ba mbanua si so okhötania; omo andrö sa, ba mbanua nono Lewi, ba si lö tebulö khöra, ba hunö Ndraono Gizeraeli.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 34, 'Ba benua andrö ba zinga mbanua khöra, ba lö tola te''amawa, me no khörakhöra, götö-götö wa''ara, okhöta si lö tebulö.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 35, 'Ba na tobali numana dalifusöu, na awuwu ia ba ngaiu, ba ötolo ia, amaedola niha bö''ö, amaedola zi fatewu, ena''ö isöndra mbalazonia ba ngaimö.', '["MozII 22:25"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3480257, 'OT', 'Moze III', 25, 36, 'Lö tola öfohare gana''au khönia, böi fabali khönia, ö''ata''ufi Lowalangiu, ena''ö isöndra mböli gönia talifusöu, ba ngaimö.[4]', '["MozII 22:25"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 37, 'Ana''au, ba lö tola öfohare khönia, ba önia, nibe''eu, ba böi fabali.', '["MozII 22:25"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 38, 'Yehowa ndra''odo, Lowalangimi, si no mangeheta ya''ami ba danö Miserayi, ba wame''e khömi tanö Gana''ana, ba we''amöi Lowalangimi.', '["MozII 22:25"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 39, 'Ba na tobali numana dalifusöu ba ngaiu ba na i''amawa ia khöu, ba böi fohalöŵö ia halöŵö zawuyu.[5]', '["MozII 21:2","Efes 6:9; Kol 4:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 40, 'Amaedola enoni ia khöu öbe''e, ba amaedola zi fatewu, yamöi ngoni-ngoniu, irege döfi wa''owua-wua dödö andrö.', '["MozII 21:2","Efes 6:9; Kol 4:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 41, 'Ba da''ö dania ö''efa''ö ia, awö ndraononia, ba ifuli ia ba niwara, ba mangawuli khönia gondröita namania.', '["MozII 21:2","Efes 6:9; Kol 4:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 42, 'Enonigu sa ira, nihetagu, ba danö Miserayi; lö tola la''amawa sawuyu ira.', '["MozII 21:2","Efes 6:9; Kol 4:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 43, 'Böi faitoisi wamatörö ya''ia, ö''ata''ufi Lowalangiu.[6]', '["MozII 21:2","Efes 6:9; Kol 4:1"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 44, 'Ba na omasi''ö zawuyu ono matua ba sawuyu ono alawe, ba ba niha baero, si tefasui ya''ami — ba khöra mihöli zawuyu ono matua ba sawuyu ono alawe.', '["RazI 9:22"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 45, 'Ba he iraono zi fatewu andrö, ba khömi, ba hana na mihöli ösa, awö nga''ötöra andrö, ba khömi, si tumbu ba danömi; hana na khömi da''ö.', '["RazI 9:22"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 46, 'Ba hana na mifa''ema ba ndraonomi furimi, ondröita, ena''ö okhötara, ba hana na lö tebulö sawuyumi ira. Ba ba dalifusömi andrö, Iraono Gizeraeli — ba faoma böi mifaitoisi, wamatörö awömi.[7]', '["RazI 9:22"]', NULL),
  (3480257, 'OT', 'Moze III', 25, 47, 'Ba na falukha niha bö''ö, ba ma si fatewu, öna-öna so khönia ba ngaiu, ba na tobali numana dalifusöu ba ngainia, ba na i''amawa ia ba niha bö''ö, ba ma ba zi fatewu, ba ma ba nga''ötö niha bö''ö ba ngaimö,', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 48, 'ba nitehe khönia wananu, na no i''amawa ia; hana na talifusönia zananu ya''ia;', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 49, 'ma tana mamania ba ma ono dana namania zananu ya''ia, ba ma ha niha zabölö ahatö khönia, iwara, zananu ya''ia, ba ma zui, na isöndra gana''a, ba hana na ya''ia zananu ya''ia.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 50, 'Ba i''erai khö zowöli ya''ia, i''otarai ndröfi, me i''amawa ia, irugi ndröfi wa''owua-wua dödö andrö. Ba ba mböli, ba balazi ha me uga fakhe, me i''amawa ia; amaedola genoni ia, götö we''asonia khönia.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 51, 'Ba na oya na ndröfi si tosai, ba i''erai ba wamuli ösa, bölinia, ba wananu ya''ia.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 52, 'Ba na ambö fa''oya ndröfi si tosai, irege döfi wa''owua-wua dödö andrö, ba i''erai khönia; balazi ha me uga fakhe ia khönia, ha wa''ebua ifuli, ba wananu ya''ia.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 53, 'Amaedola zi manga gazi, döfidöfi, ia khönia; lö tola öfaigi manö lö hede-hede, na ifaitoisi wamatörö ya''ia.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 54, 'Ba na lö falukha ia wananu si manö, ba ba ndröfi wa''owua-wua dödö andrö dania aefa ia, awö ndraononia.', '[]', NULL),
  (3480257, 'OT', 'Moze III', 25, 55, 'Khögu sa Ndraono Gizeraeli, enonigu; enonigu, nihetagu ba danö Miserayi, ya''odo andre, Yehowa, Lowalangimi.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 1, 'Lö tola mifazökhi khömi nadu, ba ma famaedo, kara nitoto, ba böi mitaru''ö khömi harefa, ba he gowe ni''oniha, ba böi mifataro ba danömi, ba wangalulu khönia, me no Yehowa ndra''odo Lowalangimi.[1]', '["MozII 20:4; MozV 16:22"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 2, 'Luo wolombase andrö khögu mitöngöni, ba mi''ata''ufi ni''amoni''ö andrö khögu; Yehowa ndra''odo.', '["MozII 20:4; MozV 16:22"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 3, 'Ba na mi''o''ö nifakhoigu ba na mitöngöni goroisagu, wolo''ö ya''ia,[2]', '["Faigi 19:30","MozV 11:14; 28:1 b.t."]', NULL),
  (3480258, 'OT', 'Moze III', 26, 4, 'ba ube''e deu khömi, ero na inötö, ena''ö mowua danö, ba he eu sowua ba mbenua, ba ena''ö na mowua.[3]', '["Faigi 19:30","MozV 11:14; 28:1 b.t."]', NULL),
  (3480258, 'OT', 'Moze III', 26, 5, 'Ba irugi dania wangozara bua nagu famöbörö fakhe, ba khömi ba fangozara bua nagu andrö, ba irugi wanaru, ena''ö fahöna khömi mbalazo, ba ena''ö lö hadia ia khömi, ba danö.', '["Faigi 19:30","MozV 11:14; 28:1 b.t."]', NULL),
  (3480258, 'OT', 'Moze III', 26, 6, 'Lö fanuwö-nuwö ube''e, ena''ö mi''ila mörö lö si keani ya''ami. Uheta ba danömi gutu ndru''u andrö, ba lö irugi danömi si''öli ube''e.[4]', '["Yob 11:19","Yos 23:10"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 7, 'Emalimi, ba mitimba dania ba ikhamö ira si''ölimi, ba woloira khömi.', '["Yob 11:19","Yos 23:10"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 8, 'Dalima ami, ba otu migohi, ba otu ami, ba fulu ngahönö migohi, ba ikhamö nemalimi si''ölimi, ba woloira khömi.[5]', '["Yob 11:19","Yos 23:10"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 9, 'Ba u''otahögö ami, ba tedou ami ube''e, ato ami, ba aro wawu''usa li andrö khöda ube''e.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 10, 'Bua danö me ndröfia gömi: ba tobali miheta zi tohöna, ba wamonaha si bohou [mubasi].', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 11, 'Ba u''iagö ba khömi, lö anuzu dödögu ami.[6]', '["MozII 29:45"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 12, 'Udörö-döröi ami, ba Lowalangimi ndra''odo, ba banuagu ami.', '["MozII 29:45"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 13, 'Yehowa ndra''odo, Lowalangimi, si no mangeheta ya''ami ba danö Miserayi, fa böi sa''ae sawuyura ami; no ufatö döladöla galo mbagimi, ba mi''ila mifaöga mbagimi ube''e.', '["MozII 29:45"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 14, 'Ba na lö mifondrondrongo khögu, na lö''ö manö mi''o''ö goroisagu,[7]', '["MozV 28:15 b.t.; Mal 2:2"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 15, 'na lö ba dödömi nifakhoigu andrö ba na anuzu dödömi huku andrö khögu, na tobali lö''ö manö mi''o''ö goroisagu, wanudugö fawu''usa li andrö khögu,', '["MozV 28:15 b.t.; Mal 2:2"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 16, 'ba u''ohia''ö göi da''ö, wolau khömi; sata''u ita ufatörö khömi:', '["MozV 28:15 b.t.; Mal 2:2"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 17, 'Ba fa''udu ndra''o khömi, tobali te''ala ami ba nemalimi, ba labe''e barö mbawara ami si fa''udu khömi, ba moloi ami, he göi lö solohi ya''ami.[8]', '["Amaed 28:1"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 18, 'Ba na lö''ö zui na mifondrondrongo khögu dania, ba mewitu u''abe''ö wangotu''ö ya''ami, ba horömi andrö,', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 19, 'ba uhöndrögö hokhami andrö, si no abe''e, ba timba zi''öli mbanua yaŵami ube''e, ba timba döla garamba danömi [wa''abe''e].', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 20, 'Ba tobali mifakao ami lö boto: tanö, ba lö mowua, ba he eu sowua ba danö, ba si lö bua.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 21, 'Ba na milau zi lö faudu khögu, na lö mifondrondrongo khögu, ba utohugö ubago ami, mewitu, luomi ba horömi.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 22, 'Ba ududu khömi gutu ndru''u andrö, ena''ö la''oloi''ö ndraonomi ba ena''ö labubunu gurifömi, ena''ö alö wa''atomi labe''e, ena''ö lö niha-niha ba lala khömi misa.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 23, 'Ba na lö''ö zui falukhado ata''u ami ba da''ö, na milau na zi lö faudu khögu,', '["Hos 4:10; Mikh 6:14"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 24, 'ba ulau göi zi lö faudu khömi, ba mewitu ubago ami, ba horömi andrö.', '["Hos 4:10; Mikh 6:14"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 25, 'Ba itörö ami si''öli ube''e, folau mbalö, me no mududugö wawu''usa li andrö. Ba na mi''owuloi dania ami yomo ba mbanua, ba ufatörö khömi wökhö waba, ba tebe''e ba danga nemali ami.', '["Hos 4:10; Mikh 6:14"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 26, 'Ba na ufatö khömi dendrotendro gö, ba dafulu dania ndra alawe zamogö roti khömi, ha sambua mbowoa, ba lafuli khömi roti andrö, nitulo, ba manga ami, ba lö abuso.[9]', '["Hos 4:10; Mikh 6:14"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 27, 'Ba na lö''ö zui mifondrondrongo khögu, na milau na zi lö faudu khögu,', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 28, 'ba ulau göi zi lö faudu khömi, ba wönugu, ba mewitu u''otu''ö ami, ba horömi andrö.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 29, 'Ba mi''a dania nösi nonomi matua ba ösi nonomi alawe mi''a.[10]', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 30, 'Ba ufufu hili-hili andrö khömi, ba gowe luo andrö khömi, ba urasa, ba u''orudugö ba mboto nadumi mbotomi si mate, ba ogorodo ami.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 31, 'Banuami, ba ubali''ö adudula, awö ni''amoni''ö andrö khömi, ududugö, ba lö''ö sa''ae u''ago wa''amohua zumange andrö khömi, si no omasiö ena''ö.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 32, 'Ya''odo andre zamali''ö tanö si mate tanö, ena''ö tobali dödö nemalimi andrö ba da''ö, emalimi si möi mowanua ba danö.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 33, 'Ba ya''ami, ba ufazawili ba niha baero, ba usöbi zi''öli moroi furimi; ba yatobali tanö si mate danömi ba banuami, ba yatobali adudula.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 34, 'Ba te''ali dania ba danö ndröfi wolombase andrö khönia, götö tanö si mate ia, fatua ba danö nemalimi so ami. Ba da''ö dania molombase danö, ba itörö ndröfi wolombase andrö khönia.[11]', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 35, 'Götö tanö si mate ia molombase ia — folombase si lö falukha ia mege, na döfi wolombase andrö, niŵa''ö khömi, me so ami ba danö.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 36, 'Ba ha niha ami si tosai, ba lö lala dödö ube''e, ba danö nemalira, ena''ö moloi ira ba weruru zi sagörö bulu lehu, ena''ö moloi, si mane foloi na so zi''öli, ba ena''ö alau, he ŵa''ae lö solohi.[12]', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 37, 'Ba lalangö nawöra wa''alau, si mane na so zi''öli moroi furi, he ŵa''ae lö solohi; ba ya tebai milaŵa nemalimi.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 38, 'Ba yatekiko ami ba niha baero andrö, hana na i''a ami tanö nemalimi andrö.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 39, 'Ba ha niha ami si tosai dania, ba hana na ariri ira ba danö nemalimi, börö horöra andrö; ba börö göi golalöŵa ndra tuara ösa, wa sariri ira, si mane da''ö mege.', '["RazII 6:28; Yer 19:9; Ngenu 4:10","Nga''ötII 36:21","Yes 30:17"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 40, 'Ba na latehe dania horöra, awö horö ndra tuara andrö — wa no faröi ira khögu — awö wa no lalau zi lö faudu khögu,[13]', '["MozV 4:30; 30:2"]', NULL),
  (3480258, 'OT', 'Moze III', 26, 41, 'börö wa ulau göi khöra si lö faudu khöra, awö wa no u''ohe ira ba danö nemalira — na mangalulu dania dödöra andrö, si lö muboto, ba na tesulöni khöra horöra andrö,', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 42, 'ba itorö tödögu wawu''usa li andrö khögu khö Yakobo ba fawu''usa li khö Giza''aki ba fawu''usa li khö Gaberahamo, ba itörö tödögu, ba tanö andrö, ba itörö tödögu.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 43, 'Ba saheta sa ira ba danö, ena''ö tetörö khönia ndröfi wolombase andrö, fatua tanö si mate ia, na no aheta ira; ba khöra, ba tesulöni horöra andrö, me no la''ositengagö huku andrö khögu, ba me no anuzu dödöra nifakhoigu.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 44, 'Ba he ba da''ö dania, na ba danö nemalira so ira, ba lö ogorodo ira, fa uhori ira ena''ö, fa ududugö wawu''usa li andrö khöma, ena''ö, me no Yehowa ndra''odo, Lowalangimi.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 45, 'Ba itörö tödögu — ba khöra andrö — wawu''usa li andrö khögu khö ndra tua, nihetagu ba danö Miserayi, ba zanehe niha baero, ba we''amöi Lowalangira, ya''odo andre, Yehowa.', '[]', NULL),
  (3480258, 'OT', 'Moze III', 26, 46, 'Da''ö gamakhoita andrö ba huku ba oroisa, nibe''e Yehowa ba hili Zina''i andrö, nifa''ema Moze, lala niŵa''önia ba Ndraono Gizeraeli.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 2, 'Hede ba Ndraono Gizeraeli, ba ömane khöra:', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 3, 'ba fatö ndra matua si dua wulu fakhe, irege önö ngafulu, ba lima wulu rufia ba zaga ni''amoni''ö andrö;', '["MozIV 30:3; MozV 23:21"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 4, 'ba na ira alawe, ba tölu ngafulu rufia watönia.', '["MozIV 30:3; MozV 23:21"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 5, 'Ba na si melima fakhe, irugi dua wulu fakhe, ba fatö nono matua, ba dua wulu rufia ba fatö nono alawe, ba fulu rufia.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 6, 'Ba na si sara waŵa, irugi melima fakhe, ba fatö nono matua, ba lima rufia, ba fatö nono alawe, ba tölu rufia.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 7, 'Ba na si önö ngafulu fakhe ba na si töra, ba fatö ndra matua, ba felelima rufia, ba fatö ndra alawe, ba fulu rufia.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 8, 'Ba na no abölö numana niha si manö, na tebai itörö watö andrö, ba la''ohe khö gere, ba yamufatö mbölinia ere; yamufaigi ere, ha wa''ebua zi tola ibe''e samabu''u andrö.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 9, 'Ba na urifö, si tola labe''e sumange Yehowa, ba ni''amoni''ö laŵa''ö fefu nibe''e khö Yehowa.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 10, 'Lö tola ifalalini ba lö tola isalahini, wame''e si sökhi salahi zi lö sökhi, ba ma si lö sökhi salahi zi sökhi; ba na ifalalini zui gurifö andrö, ba faoma ni''amoni''ö.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 11, 'Ba na urifö salakha, si tebai labe''e sumange Yehowa, ba ndramu''ohe khö gere.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 12, 'Ba yamufatö mbölinia ere, na si sökhi, ba na sambö fa''asökhi; ba ba watö andrö, niŵa''ö gere, ahono.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 13, 'Ba na edona isanu, ba sambua ni''olima watö andrö inönö.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 14, 'Ba na so zi amoni''ö khö Yehowa omonia, ba yamufatö mbölinia ere, na si sökhi, ba na sambö fa''asökhi, ba fatö niŵa''ö gere mbölinia.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 15, 'Ba na edöna ifuli isanu nomonia si amoni''ö ya''ia mege, ba sambua ni''olima watönia andrö inönö, ba khönia sa''ae.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 16, 'Ba na so zi amoni''ö khö Yehowa benua, föfö gondröita namania mege, ba ba watönia, ba balazi ha uga lauru tanömö; si 25 lauru tanömö, ba 50 rufia watönia.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 17, 'Na ba ndröfi wa''owua-wua dödö andrö i''otarai we''amoni''ö benuania andrö, ba fatönia itörö.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 18, 'Ba na no aefa ndröfi wa''owua-wua dödö na i''amoni''ö, ba yamu''erai khönia mböli ere, balazi ha me uga fakhe na, irugi ndröfi wa''owua-wua dödö dania, ba lasöbi dania ndrohu-ndrohu ba watönia andrö.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 19, 'Ba na edöna zui isanu mbenua andrö si amoni''ö ya''ia, ba sambua ni''olima watönia andrö inönö; ba lö tebulö wa khönia.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 20, 'Ba na lö isanu mbenua andrö, ba na i''amawa zui ba niha bö''ö, ba tebai tefuli tesanu;', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 21, 'benua andrö, na aefa dania, na döfi wa''owua-wua dödö andrö, ba ni''amoni''ö khö Yehowa laŵa''ö, si mane benua nilakha''ö; okhöta gere sa''ae ia.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 22, 'Ba na so zi amoni''ö khö Yehowa benua ni''ölinia, si tenga föfö mbenua ondröita namania mege, ba yamu''erai khönia ere,', '["MozII 30:13"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 23, 'he wisa fatönia, irege döfi wa''owua-wua dödö andrö, ba fatö da''ö, ba na luo da''ö ibe''e, ame''ela ni''amoni''ö khö Yehowa.', '["MozII 30:13"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 24, 'Ba na döfi wa''owua-wua dödö, ba mangawuli ba ni''olinia ya''ia mbenua andrö, ba zokhö ya''ia mege ondröita namania.', '["MozII 30:13"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 25, 'Fefu watö, ba saga ni''amoni''ö mbalazi; si samba sekeli [rufia] ba 20 gera.[2]', '["MozII 30:13"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 26, 'Ba si a''a nono gurifö, si möi khö Yehowa, me no si a''a, ba lö tola la''amoni''ö; he saŵi, ba he biri-biri — khö Yehowa ia sa''ae.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 27, 'Ba na urifö salakha, ba nihöli, balazi watö, ba sambua ni''olima mböli inönö; ba na lö lasanu, ba ni''amawa, balazi watö.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 28, 'Ba ba nilakha''ö, ni''amoni''ö niha khö Yehowa, wolakha''ö ya''ia, nituyu ba zi so khönia fefu, he niha, ba he urifö, ba he benua, ondröita mege, ba lö''ö manö tola la''amawa ba lö tola lasanu; fefu nilakha''ö ba no ni''amoni''ö sibai khö Yehowa.', '["SamI 15:3"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 29, 'Na so ha niha, niha nilakha''ö, ba lö tola lasanu, nibunu sa''ae.[3]', '["SamI 15:3"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 30, 'Sambua ni''ofulu, fefu, he benua, ba he bua danö, ba he bua geu, ba khö Yehowa, ni''amoni''ö khö Yehowa.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 31, 'Ba na so zomasi mananu ösa ni''öfulu andrö khönia, ba sambua ni''olima mbölinia inönö.', '[]', NULL),
  (3480259, 'OT', 'Moze III', 27, 32, 'Ba ba zi sambua ni''ofulu zaŵi ba biri-biri, ba ba nifatörö si''o [gubalo] fefu, ba ni''erai, fulufulu nga''eu, ba sagesageu ni''amoni''ö khö Yehowa.[4]', '["Yer 33:13"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 33, 'Böi lafaigi, na si sökhi, ba na si lö sökhi, ba lö tola lafalalini. Ba na so zamalalini zui, ba faoma ni''amoni''ö ira, ba lö tola lasanu.', '["Yer 33:13"]', NULL),
  (3480259, 'OT', 'Moze III', 27, 34, 'Da''ö goroisa andrö, ni''oroi''ö Yehowa khö Moze, ba hili Zina''i, ba Ndraono Gizeraeli.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3473284, 'OT', 'Moze IV', 1, 1, 'Ba humede Yehowa khö Moze ba danö si mate, ba gahe hili Zina''i, ba nose wama''ele''ö andrö, me fasulöna ba mbaŵa si dua, me döfi si dua, aefa aheta ira ba danö Miserayi, imane:[1]', '["MozV 1:3"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 2, 'Mi''ofaya[2] ha wa''ato mbanua Ndraono Gizeraeli andrö, sambu-sambua mado ba sawu-sawu, ba töira, sambu-sambua, dozi motöi matua, samö-samösa.[3]', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 3, 'Dozi solohe baluse, ba Ndraono Gizeraeli, i''otarai zi 20 fakhe fa''ebua, ba si a''a moroi andrö, ba mi''ofaya, samba-sambawa, ya''ugö ba A''aroni.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 4, 'Ba sambu-sambua mado, ba samö-samösa tebe''e awömi, högö niwara andrö.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 5, 'Da''ö döi nibe''e awömi: ba mado Rubeno, ba Elisuri, ono Zedeuri.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 6, 'Ba ba mado Zimeoni, ba Selumieli, ono Zuri-Sada''i.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 7, 'Ba ba mado Yuda, ba Nahaso, ono Gaminadabi.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 8, 'Ba ba mado Isasari, ba Natana''eli, ono Zuara.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 9, 'Ba ba mado Zebuloni, ba Eliabi, ono Helono.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 10, 'Ba ba Ndraono Yosefo: ba mado Geferayi, ba Elizama, ono Gamihudi, ba ba mado Manase, ba Gamelieli, ono Wedasuri.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 11, 'Ba ba mado Mbeniyami, ba Abidano, ono Gideono.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 12, 'Ba ba mado Dano, ba Ahiezeri, ono Ami-Sada''i.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 13, 'Ba ba mado Gaseri, ba Fagieli, ono Okherana.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 14, 'Ba ba mado Gado, ba Eliazafi, ono Degueli.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 15, 'Ba ba mado Nafetali, ba Ahira, ono Genano.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 16, 'Da''ö nituyu ba zato, högö niwara andrö, högö ngahönö Ndraono Gizeraeli.', '["Mangofaya: mangerai fa''oya niha (li Indonesia sensus)","MozII 30:12"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 17, 'Ba lafakaoni''ö niha andrö, si no mutötöi khöra, ira Moze A''aroni,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 18, 'ba lafalukha''ö mbanua ma''afefu, me fasulöna ba mbaŵa si dua. Ba lafatanö''ö ba zura wa''atumbu döira, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, samö-samösa.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 19, 'Dali niŵa''ö Yehowa khö Moze; si manö sa wangofayania ya''ira ba danö si mate, ba gahe hili Zina''i.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 20, 'Ba fa''ato nga''ötö ndraono Rubeno, si a''a ndraono Gizeraeli, iwara ba ngafura ba töira, si ha sambu-sambua, ni''ofaya, samö-samösa — dozi motöi matua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 21, 'ha wa''ato ni''ofaya, mado Rubeno, ba no 46.500.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 22, 'Ba fa''ato nga''ötö ndraono Zimeoni, iwara ba ngafura ba töira, si ha sambu-sambua, ni''ofaya, samö-samösa — dozi motöi matua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 23, 'ha wa''ato ni''ofaya, mado Zimeoni ba no 59.300.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 24, 'Ba fa''ato nga''ötö ndraono Gado, iwara, ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 25, 'ha wa''ato ni''ofaya, mado Gado, ba no 45.650.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 26, 'Ba fa''ato nga''ötö ndraono Yuda, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 27, 'ha wa''ato ni''ofaya, mado Yuda, ba no 74.600.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 28, 'Ba fa''ato nga''ötö ndraono Izasari, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 29, 'ha wa''ato ni''ofaya, mado Izasari, ba no 54.400.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 30, 'Ba fa''ato nga''ötö ndraono Zebuloni, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 wulu fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 31, 'ha wa''ato ni''ofaya, mado Zebuloni, ba no 57.400.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 32, 'Ba ba ndraono Yosefo andrö, ba fa''ato nga''ötö ndraono Geferayi, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 33, 'ha wa''ato ni''ofaya, mado Geferayi, ba no 40.500.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 34, 'Ba fa''ato nga''ötö ndraono Manase, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 35, 'ha wa''ato ni''ofaya, mado Manase, ba no 32.200.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 36, 'Ba fa''ato nga''ötö ndraono Mbeniyami, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe, baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 37, 'ha wa''ato ni''ofaya, mado Mbeniyami, ba no 35.400.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 38, 'Ba fa''ato nga''ötö ndraono Dano, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai si 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 39, 'ha wa''ato ni''ofaya, mado Dano, ba no 62.700.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 40, 'Ba fa''ato nga''ötö ndraono Gaseri, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 41, 'ha wa''ato ni''ofaya mado Gaseri, ba no 41.500.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 42, 'Ba fa''ato nga''ötö ndraono Nafetali, iwara ba ngafura ba töira, si ha sambu-sambua, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse,', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 43, 'ha wa''ato ni''ofaya, mado Nafetali, ba no 53.400.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 44, 'Da''ö ni''ofaya andrö, ni''ofaya ndra Moze A''aroni ba salaŵa Ndraono Gizeraeli; felendrua da''ö, sambu-sambua mado, ba samö-samösa.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 45, 'Ba dozi ni''ofaya, Iraono Gizeraeli, ngafura andrö, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, dozi solohe baluse ba Ndraono Gizeraeli —', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 46, 'dozi ni''ofaya, ba no 603.550.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 47, 'Ba Ono Lewi andrö, iwara andrö, ba lö lafao khöra ba wangofaya.[4]', '["MozII 38:26"]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 48, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 49, 'Ono Lewi andrö, ba lö tola ö''ofaya, lö tola ö''erai wa''atora, ba ngai Ndraono Gizeraeli bö''ö.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 50, 'Ba nahia zura goroisa öfataro Nono Lewi, ba ba wakakenia, fefu, ba ba zi faböbö khönia, fefu. Ya''ira zangosa''ö ose andrö, awö wakake andrö ba khönia fefu, ba ya''ira zangai halöŵö ba da''ö, lafasui nose wame''e nahiara.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 51, 'Ba na mofanö nose, ba Ono Lewi zanudugö, ba na tebato nose, ba Ono Lewi zama''anö, ba na so niha bö''ö, si hatö''ö ya''ia, ba nibunu.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 52, 'Ba Iraono Gizeraeli bö''ö, ba yamufaigi nahania zamösana ba zinga mandrera khöra, dali ngawawara andrö.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 53, 'Ba Ono Lewi, ba lafasui nahia zura goroisa, wame''e nahara, fa böi göna fönu Lowalangi Ndraono Gizeraeli sato. Ba lahalö-halö halöŵö ba nahia zura goroisa Ono Lewi andrö.', '[]', NULL),
  (3473284, 'OT', 'Moze IV', 1, 54, 'Ba la''o''ö sibai Iraono Gizeraeli niŵa''ö Yehowa khö Moze — ba da''ö labe''e.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 1, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 2, 'Ba nahia olombaseŵa andrö ba Ndraono Gizeraeli, ba ba mandrera khönia ifaigi zamösana ba ba dandra niwara; ba gamaudu nose wama''ele''ö labe''e nahara, fasui.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 3, 'Tanö föna, tanö ba gatumbukha, ba mandrera ba golombaseŵa ba mado Yuda, dali ngawawara, ba solohe Iraono Yuda, Nahaso andrö, ono Gaminadabi,', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 4, 'awö zato andrö khönia, ni''ofaya andrö, 74.600.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 5, 'Ba ba ngaira monaha mado Izasari, ba solohe Iraono Izasari, Natanaeli andrö, ono Zuara,', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 6, 'awö zato andrö khönia, ni''ofaya andrö, 54.400.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 7, 'Ba mado Zebuloni, ba solohe Iraono Zebuloni, Eliabi andrö, ono Helono,', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 8, 'awö zato andrö khönia, ni''ofaya andrö, 57.400.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 9, 'Dozi ni''ofaya andrö, si faböbö ba nahia olombaseŵa ba mado Yuda andrö, ngawawara andrö, ba 186.400: ya''ira zi so föna ba wofanö.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 10, 'Ba tanö miraya, ba mandrera ba golombaseŵa ba mado Rubeno, ba ngawawara andrö, ba solohe Iraono Rubeno, Elisuri andrö, ono Zedeuri,', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 11, 'awö zato andrö khönia, ni''ofaya, 46.500.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 12, 'Ba ba ngaira monaha mado Zimeoni, ba solohe iraono Zimeoni, Selumieli andrö, ono Zuri-Sada''i,', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 13, 'awö zato andrö khönia ni''ofaya, 59.300.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 14, 'Ba mado Gado, ba solohe Iraono Gado, Eliazafi andrö, ono Regueli,', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 15, 'awö zato andrö khönia, ni''ofaya, 45.650.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 16, 'Dozi ni''ofaya ba nahia olombaseŵa ba mado Rubeno, ba ngawawara andrö, ba 151.450; da''ö wanete zi so föna, ba wofanö.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 17, 'Ba ose wama''ele''ö, olombaseŵa Nono Lewi, ba ba dödö golombaseŵa bö''ö andrö lafazaŵa ira; balazi heza nahiara mege, ba wamazaŵara ya''ira, ba nahania i''agö zamösana, dali mandrera khöra.', '[]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 18, 'Ba mandrera ba golombaseŵa ba mado Geferayi, ba ngawawara andrö, ba tanö ba gaekhula tebe''e, ba solohe Iraono Geferayi, Elisama andrö, ono Gamihudi,', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 19, 'awö zato andrö khönia, ni''ofaya, 40.500.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 20, 'Ba ba ngaira, ba mado Manase ba solohe Iraono Manase, Gamelieli andrö, ono Wedasuri,', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 21, 'awö zato andrö khönia, ni''ofaya andrö, 32.200.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 22, 'Ba mado Mbeniyami ba solohe Iraono Mbeniyami, Abidano andrö, ono Gideono,', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 23, 'awö zato andrö khönia, ni''ofaya andrö, 35.400.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 24, 'Dozi ni''ofaya, ba nahia olombaseŵa ba mado Geferayi, ba ngawawara andrö, ba no 108.100. Fanete zi dua bawa no mege da''ö, ba wofanö.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 25, 'Ba mandrera ba golombaseŵa ba mado Dano, ba ngawawara andrö, ba tanö miyöu tebe''e, ba solohe Iraono Dano, Ahiezeri andrö, ono Ami-Sada''i,', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 26, 'awö zato andrö khönia, ni''ofaya andrö, 62.700.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 27, 'Ba ba ngaira monaha mado Gaseri ba solohe Iraono Gaseri, Fagieli andrö, ono Okherana,', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 28, 'awö zato andrö khönia, ni''ofaya, 41.500.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 29, 'Ba mado Nafetali, ba solohe iraono Nafetali, Ahira andrö, ono Genani,', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 30, 'awö zato andrö khönia, ni''ofaya andrö, 53.400.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 31, 'Dozi ni''ofaya ba nahia olombaseŵa ba mado Dano, ba no 157.600. Da''ö zafuria, ba wofanö; dali mandrera andrö khöra.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 32, 'Da''ö ni''ofaya andrö, Iraono Gizeraeli, ba niwara andrö; fa''ato ni''ofaya andrö, ba golombaseŵa, ba ngawawara andrö, ba no 603.550.[1]', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 33, 'Ba Ono Lewi, ba lö''ö sa la''ofaya, lö lafao ba Ndraono Gizeraeli bö''ö, dali niŵa''ö Yehowa khö Moze.', '["Faigi 1:46"]', NULL),
  (3473285, 'OT', 'Moze IV', 2, 34, 'Ba la''o''ö sibai Iraono Gizeraeli niŵa''ö Yehowa khö Moze wamaigi nahiara olombasewa, dali mandrera andrö khöra; ba si manö göi na lafazaŵa ira, dali niwara, ha ma''uwu ira.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 1, 'Ba da''e nga''ötö ndra A''aroni Moze, me luo fahuhuo Yehowa khö Moze, ba hili Zina''i.', '["MozII 28:41","MozIII 10:1"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 2, 'Da''e döi ndraono Ga''aroni andrö: Nadabi, si a''a, ba Abihu; ba Eleazari ba Itamari.', '["MozII 28:41","MozIII 10:1"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 3, 'Da''ö döi ndraono Ga''aroni andrö, töi gere andrö, nibayoini, nifo''ösi tanga, ena''ö lahalö-halö halöŵö gere.[1]', '["MozII 28:41","MozIII 10:1"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 4, 'Ba si mate föna Yehowa Nadabi ba Abihu, me la''ohe föna Yehowa galitö si tenga, ba danö si mate, ba gahe hili Zina''i; ba lö khöra ono matua. Ba Eleazari ba Itamari sa''ae zangai-ngai halöŵö gere, barö mbawa namara.[2]', '["MozII 28:41","MozIII 10:1"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 5, 'Ba humede Yehowa khö Moze, imane:', '["Faigi 16:40"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 6, 'Hede ba mado Lewi, ohe khö Ga''aroni ere, ena''ö ngoni-ngoninia ira.', '["Faigi 16:40"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 7, 'Ba ya''ira zangai-ngai hadia ia nihalö-halö khönia, ba ba zato fefu, föna nose wama''ele''ö; ya''ira zangai-ngai halöŵö ba nose.', '["Faigi 16:40"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 8, 'Ba ba dangara tebe''e fefu wakake ba nose wama''ele''ö ba hadia ia ba Ndraono Gizeraeli; sangai-ngai halöŵö ba nose ira.', '["Faigi 16:40"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 9, 'Öbe''e barö mbawa ndra A''aroni iraononia Nono Lewi, tana khönia manö nibe''e Ndraono Gizeraeli bö''ö.', '["Faigi 16:40"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 10, 'Ba A''aroni ba iraononia, ba öfataro, ba wangai halöŵöra, halöŵö gere; niha bö''ö, si hatö''ö ya''ia, ba nibunu.[3]', '["Faigi 16:40"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 11, 'Ba humede Yehowa khö Moze, imane:', '["Faigi 8:16","MozII 13:2"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 12, 'Ya''odo zanutuyu ba Ndraono Gizeraeli bö''ö Ono Lewi andrö, salahi zi a''a bawa''atumbu, fefu, ba Ndraono Gizeraeli — si a''a ndraono khö ninara — ena''ö tana khögu Nono Lewi andrö.[4]', '["Faigi 8:16","MozII 13:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3473286, 'OT', 'Moze IV', 3, 13, 'Me no tana khögu fefu zi a''a ba wa''atumbu; me luo ubunu zi a''a nono fefu, ba danö Miserayi u''amoni''ö khögu fefu zi a''a ba wa''atumbu ba Ndraono Gizeraeli, ya''odo andre, Yehowa; he niha ba he urifö; tana khögu ira.[5]', '["Faigi 8:16","MozII 13:2"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 14, 'Ba humede Yehowa khö Moze, ba danö si mate, ba gahe hili Zina''i, imane:', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 15, 'Ofaya Nono Lewi andrö, ba ngafura ba ba watalifusöta khöra, dozi motöi matua, i''otarai zi sara wawa fa''ebua, ba si a''a moroi andrö, ö''ofaya, ya''ira.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 16, 'Ba i''ofaya ira Moze, i''o''ö goroisa Yehowa andrö, dali niŵa''önia khönia.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 17, 'Ba da''e döi ndraono Lewi andrö: Gereso ba Kahati ba Merari.[6]', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 18, 'Ba töi ndraono Gereso, ba ngafura, ba Libeni ba Sime''i.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 19, 'Ba iraono Gahati, ba ngafura, ba Ameramo ba Yesehari ba Heberona ba Uzieli.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 20, 'Ba iraono Merari, ba ngafura, ba Maheli ba Musi. Da''ö nga''ötö Lewi ba ira amara.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 21, 'Nga''ötö Gereso ndraono Libeni andrö ba iraono Zime''i. Nga''ötö ndraono Gereso da''ö.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 22, 'Fa''ato ni''ofaya, ya''ira — dozi motöi matua, i''otarai zi sara waŵa fa''ebua ba si a''a moroi andrö — ba no 7.500.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 23, 'Nga''ötö Gereso andrö, ba ba gero nose soso golombaseŵara, tanö ba gaekhula luo.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 24, 'Ba högö ndraono Gereso andrö, ba Eliazafi, ono La''eli.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 25, 'Ba halöŵö ndraono Gereso andrö ba nose wama''ele''ö, ba famaigi ösi nose, awö dufo sagö andrö ba balu-balu dufo sagö ba ba''a-ba''a mbawandruhö nose wama''ele''ö,', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 26, 'ba ba''a-ba''a golayama andrö ba ba''a-ba''a mbawa göli ba golayama, samasui ose, awö naha wame''e sumange, ba sinalinia — fabaya fefu hadia ia halöŵö ba da''ö.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 27, 'Ba madou Gahati, ba ya''ia nga''ötö Ameramo andrö, awö nga''ötö Yesehari, awö nga''ötö Heberona, awö nga''ötö Uzieli. Da''ö nga''ötö ndraono Gahati.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 28, 'Ba fa''atora — dozi motöi matua, i''otarai zi sara waŵa fa''ebua ba si a''a moroi andrö, ba no 8.600, si so halöŵö ba ni''amoni''ö andrö.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 29, 'Ba nga''ötö ndraono Gahati andrö, ba ba ngai nose soso golombaseŵara, tanö miraya.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 30, 'Ba högö nga''ötö ndraono Gahati andrö, ba Elisafa, ono Uzieli.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 31, 'Ba halöŵöra, ba famaigi tawöla andrö ba meza ba naha wandru, awö naha wame''e sumange, awö wakake ni''amoni''ö andrö, ni''oguna''ö ba wangai-ngai halöŵö andrö, ba ba''a-ba''a andrö — fabaya fefu hadia ia halöŵö ba da''ö.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 32, 'Ba högö zatua Nono Lewi andrö, ba Eleazari, ono Ga''aroni ere andrö, ya''ia mandru zangai halöŵö ba ni''amoni''ö.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 33, 'Ba nga''ötö Merari, ba ya''ia ndraono Maheli andrö ba iraono Musi; da''ö nga''ötö Merari.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 34, 'Ba fa''ato ni''ofaya, ya''ira — dozi motöi matua, i''otarai zi sara waŵa fa''ebua ba si a''a moroi andrö, ba no 6.200.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 35, 'Ba högö nga''ötö Merari andrö, ba Surieli, ono Gabiha''ili, ba ba zi tambai nose soso golombaseŵa khöra, tanö miyöu.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 36, 'Ba nibe''e ba danga ndraono Merari, ba ya''ia wafa [döla-döla] nose, awö lazi, awö daru nahe andrö, fabaya ahe, awö wakakenia fefu, fabaya fefu hadia ia halöŵö ba da''ö.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 37, 'Ba baero ö, ba taru nahe ba golayama andrö, fasui, fabaya ahe ba taru-taru ba sinali.', '["MozII 6:16"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 38, 'Ba ba mbawa duasa nose, tanö miföna — föna nose wama''ele''ö, tanö ba gatumbukha luo, — ba olombaseŵa Moze, awö ndra A''aroni iraononia, sangai-ngai halöŵö andrö, ba ni''amoni''ö, hadia zoguna ba Ndraono Gizeraeli; ba niha bö''ö si hatö''ö ya''ia, ba nibunu.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 39, 'Ba dozi ni''ofaya, Ono Lewi, ni''ofaya ndra Moze A''aroni, sawu-sawu, wolo''ö niŵa''ö Yehowa — dozi motöi matua, i''otarai zi sara waŵa fa''ebua ba si a''a moroi andrö, ba no 22.000.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 40, 'Ba imane Yehowa khö Moze: Ofaya fefu nono matua si a''a, ba Ndraono Gizeraeli, i''otarai zi sara waŵa fa''ebua ba si a''a moroi andrö ba tanö ba zura döira, ha wa''ato.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 41, 'Ba Ono Lewi andrö öhalö khögu, khö Yehowa, salahi zi a''a ba wa''atumbu fefu, ba Ndraono Gizeraeli; ba urifö nono Lewi, ba öbe''e salahi zi a''a ba wa''atumbu ba gurifö Ndraono Gizeraeli [bö''ö].', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 42, 'Ba i''ofaya fefu zi a''a ba wa''atumbu ba Ndraono Gizeraeli Moze, dali niŵa''ö Yehowa khönia.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 43, 'Ba fa''ato döi nono matua si a''a fefu, i''otarai zi sara waŵa fa''ebua ba si a''a moroi andrö, dozi ni''ofaya, ba no 22.273.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 44, 'Ba humede Yehowa khö Moze, imane:', '["MozII 30:13"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 45, 'Ono Lewi halö salahi zi a''a ba wa''atumbu fefu, ba Ndraono Gizeraeli, ba urifö Nono Lewi, ba öbe''e salahi guriföra; ena''ö tana khögu Nono Lewi andrö; Yehowa ndra''odo.', '["MozII 30:13"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 46, 'Ba ba wananu si 273 andrö, si a''a ba wa''atumbu ba Ndraono Gizeraeli, sanalu''i fa''ato Nono Lewi,', '["MozII 30:13"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 47, 'ba lima rufia zamösa öŵa''ö; saga ni''amoni''ö ni''anulo''ö; samba sekeli [rufia] ba 20 gera.[7]', '["MozII 30:13"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 48, 'Ba ana''a andrö, ba ba danga ndra A''aroni iraononia öbe''e, fananu zi töra andrö, ba khöra.', '["MozII 30:13"]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 49, 'Ba iŵa''ö wananu andrö Moze ba zi töra andrö ba nibe''e fananu Ono Lewi.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 50, 'Ba zi a''a ba wa''atumbu ba Ndraono Gizeraeli iŵa''ö, 1365 ba rufia, saga ni''amoni''ö.', '[]', NULL),
  (3473286, 'OT', 'Moze IV', 3, 51, 'Ba ibe''e ba danga ndra A''aroni iraononia wananu andrö Moze, dali li Yehowa, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 1, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 2, 'Mi''ofaya ba Nono Lewi ha wa''ato ndraono Gahati, sawu-sawu, ba sambu-sambua watalifusöta,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 3, 'i''otarai zi 30 fakhe ba si a''a moroi andrö, irugi zi 50 fakhe, dozi si möi ngoni-ngoni, sangai halöŵö ba nose wama''ele''ö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 4, 'Ba da''ö halöŵö ndraono Gahati andrö ba nose wama''ele''ö: famaigi ni''amoni''ö sibai andrö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 5, 'Ba na mifazaŵa ami ba zolombase ami, ba möi si bakha ndra A''aroni iraononia, lahalö tou mba''a-ba''a andrö ba labe''e balu-balu dawöla zura goroisa.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 6, 'Ba labe''e na dufo uli guaza mina ba ba dete da''ö labologö lembe sadölö ungu sowu waru-waru, ba labe''e hea-hea andrö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 7, 'Ba meza roti nifaigi-faigi andrö, ba labalugö lembe ungu sowu waru-waru ba labe''e yaŵa mako ba figa ba mako wamadu andrö, awö gundri, soguna ba zumange nibadu, ba yaso göi yaŵa roti andrö, ni''ali-ali.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 8, 'Ba da''ö fefu, ba nibalugö lembe kirimisi, ba balu-balu da''ö, ba tufa uli guaza mina; awena dania labe''e hea-heania.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 9, 'Ba lahalö na lembe ungu sowu waru-waru, ba labe''e balu-balu naha wandru andrö, fabaya fandru ba guti wandru ba gali andrö, awö naha wanikha khönia fefu, soguna ba wangehao ya''ia.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 10, 'Ba la''olohuni ia — fabaya fakakenia fefu — lohu-lohu uli guaza mina, ba labe''e ba hea-hea.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 11, 'Ba naha wame''e sumange andrö ana''a, ba labalugö lembe ungu sowu waru-waru, ba latötöwui tufo uli guaza mina, ba labe''e hea-heania.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 12, 'Ba lahalö fefu wakake soguna ba halöŵö andrö, nifakefake ba wangai-ngai halöŵö andrö ba ni''amoni''ö, ba la''olohuni lembe ungu sowu waru-waru; ba latötöwui tufo uli guaza mina, ba labe''e ba hea-hea.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 13, 'Ba lahaogö naha wame''e sumange, laheta nawu, ba labe''e balu-balunia lembe ungu soyo.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 14, 'Ba ba dete da''ö labe''e wakake andrö, fefu, nifakefake ba wangai-ngai halöŵö ba khönia, gali andrö ba garafu ba sundru-sundru ba figa, fefu wakake ba naha wame''e sumange; ba latötöwui ia tufo uli guaza mina, ba labe''e hea-heania.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 15, 'Ba na no mo''ahonoa khö Ga''aroni ba ba ndraononia wangolohuni ngawalö andrö fefu, ni''amoni''ö fefu, na lafazaŵa ira sato, ba ndra mufa''aso ira iraono Gahati andrö, ba wamahea; ba lö tola lababaya ni''amoni''ö andrö, fa böi mate ira.[1]', '["SamI 6:19; SamII 6:6"]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 16, 'Ba ba danga Geleazari, ono Ga''aroni ere, ba tebe''e wanikha wandru ba samohua andrö nitunutunu ba sumange ni''a andrö, sero ma''ökhö ba fanikha famayoini andrö, fabaya famaigi ose ma''afefu, awö nösinia fefu, hadia ia ngawalö ni''amoni''ö ba fakake andrö khönia.', '["SamI 6:19; SamII 6:6"]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 17, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 18, 'Böi mibe''e nihori nga''ötö Gahati andrö, ba Nono Lewi.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 19, 'Mimane wamaigi, ya''ira, ena''ö auri ira ba ni''amoni''ö sibai andrö — Möi bakha ndra A''aroni iraononia ba lafataro ba halöŵönia zamösana, hadia nihalö ba hadia ni''ohe.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 20, 'Ba böi möi ira bakha, ba wamaigi ni''amoni''ö andrö, he ha mamö''i hörö wa''ara, fa böi mate ira.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 21, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 22, 'Ofaya göi wa''ato ndraono Gereso, sambu-sambua watalifusöta ba sawu-sawu,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 23, 'i''otarai zi 30 fakhe ba si a''a moroi andrö, irege zi 50 fakhe ö''ofaya, dozi si möi ba halöŵö andrö, ba wangai-ngai hadia ia ba nose wama''ele''ö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 24, 'Ba da''ö halöŵö nga''ötö Gereso andrö — nihalöra ba ni''ohera:', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 25, 'Ni''ohera, ba kulambu nose andrö ba ose wama''ele''ö, sagönia andrö, awö dufo uli guaza mina, balu-balunia ba ba''a-ba''a mbawandruhö nose wama''ele''ö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 26, 'Ba ba''a-ba''a ba golayama ba ba''a-ba''a mbawa göli ba golayama, samasui ose, awö naha wame''e sumange, fabaya sinali andrö khönia ba fakake fefu, si faböbö ba da''ö nihalöra, ba fefu hadia ia halöŵö ba da''ö, ba halöŵöra da''ö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 27, 'Dali niŵa''ö ndra A''aroni iraononia khöra ba halöŵöra andrö, ba ni''ohera andrö fefu ba ba nihalö-halöra fefu; ba fefu hadia ia norora, ba mituturu khöra, mitötöi döi.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 28, 'Da''ö halöŵö nga''ötö ndraono Gereso andrö, ba nose wama''ele''ö; ba mandrura ba halöŵöra, ba Itamari, ono Ga''aroni ere andrö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 29, 'Ba iraono Merari, ba ö''ofaya göi, sawu-sawu ba sambu-sambua watalifusöta,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 30, 'i''otarai zi 30 fakhe ba si a''a moroi andrö, irege zi 50 fakhe, ö''ofaya, dozi si möi ba halöŵö andrö, sangai-ngai nihalö-halö andrö ba nose wame''ele''ö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 31, 'Ba da''ö ni''ohera, da''ö fefu nibe''e ba dangara, föfö nose wama''ele''ö: Fafa [döla-döla] nose ba lazi ba taru nahe, fabaya ahe;', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 32, 'ba taru nahe ba golayama fasui, fabaya ahe ba taru-taru ba sinali, awö wakakenia fefu, awö nihalö-halö ba da''ö, fefu; ba fakake andrö, norora, ba mituturu khöra, mitötöi döi.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 33, 'Da''ö halöŵö nga''ötö ndraono Merari andrö, nihalö-halöra ba nose wama''ele''ö, barö mbawa Gitamari andrö, ono Ga''aroni ere.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 34, 'Ba la''ofaya ndraono Gahati ira Moze A''aroni ba satua mbanua, sawu-sawu ba sambu-sambua watalifusöta,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 35, 'i''otarai zi 30 fakhe ba si a''a moroi andrö, irege zi 50 fakhe, dozi si möi ba halöŵö andrö, ba nihalö-halö ba nose wama''ele''ö.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 36, 'Ba fa''ato ni''ofaya andrö, sawu-sawu, ba no 2.750.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 37, 'Da''ö ni''ofaya nga''ötö Gahati, dozi si so halöŵö ba nose wama''ele''ö, ni''ofaya ndra Moze A''aroni, dali ni''oroi''ö Yehowa khö Moze.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 38, 'Ba ba ni''ofaya iraono Gereso, sawu-sawu ba sambu-sambua watalifusöta,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 39, 'i''otarai zi 30 fakhe ba si a''a moroi andrö, irege zi 50 fakhe, dozi si möi ba halöŵö andrö, ba nihalö-halö ba nose wama''ele''ö, ba fa''ato ni''ofaya,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 40, 'sawu-sawu ba sambu-sambua watalifusota, ba no 2.630.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 41, 'Da''ö ni''ofaya nga''ötö ndraono Gereso, dozi si so halöŵö ba nose wama''ele''ö, ni''ofaya ndra Moze A''aroni, dali goroisa Yehowa.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 42, 'Ba ba ni''ofaya nga''ötö ndraono Merari, sawu-sawu ba sambu-sambua watalifusöta,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 43, 'i''otarai zi 30 fakhe ba si a''a moroi andrö, irege zi 50 fakhe, dozi si möi ba halöŵö andrö, ba nihalö-halö ba nose wama''ele''ö,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 44, 'ba fa''atö ni''ofaya andrö, sawu-sawu, ba no 3.200.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 45, 'Da''ö ni''ofaya andrö, nga''ötö ndraono Merari, ni''ofaya ndra Moze A''aroni, dali ni''oroi''ö Yehowa khö Moze.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 46, 'Ba ba ni''ofaya andrö fefu, ni''ofaya ndra Moze A''aroni ba satua Ndraono Gizeraeli, Ono Lewi sawu-sawu ba sambu-sambua watalifusöta,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 47, 'i''otarai zi 30 fakhe ba si a''a moroi andrö, irege zi 50 fakhe, si möi ba wangai halöŵö andrö, ba nose wama''ele''ö ba ba halöŵö fonoro andrö,', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 48, 'fa''ato ni''ofaya andrö khöra, ba no 8.580.', '[]', NULL),
  (3473287, 'OT', 'Moze IV', 4, 49, 'Ba lafataro ba halöŵönia zamösana — Moze zamaigi — dali goroisa Yehowa, hadia halöŵöra, hadia norora, ni''ofayania andrö, dali niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 1, 'Ba humede Yehowa khö Moze, imane:', '["MozIII 13:46; 21:1"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 2, 'Ŵa''ö ba Ndraono Gizeraeli, laheta ba golombaseŵa dozi si no göna bou auri ba si so si hulö zonana, ba dozi si no ra''iö, me no lababaya mboto zi mate.[1]', '["MozIII 13:46; 21:1"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 3, 'He ira matua, ba he ira alawe, ba ni''ohe baero, fa böi ra''iö nahiara labe''e, me no ya''odo zi soso ba khöra.', '["MozIII 13:46; 21:1"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 4, 'Ba la''o''ö da''ö Iraono Gizeraeli, la''ohe baero golombaseŵa, dali niŵa''ö Yehowa khö Moze, si manö wolau Ndraono Gizeraeli.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 5, 'Ba humede Yehowa khö Moze, imane:', '["MozIII 6:2","MozIII 5:5"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 6, 'Ŵa''ö ba Ndraono Gizeraeli: Na lafazökhi horö, he ira matua, ba he ira alawe, horö nifazökhizökhi niha, na lalimo Yehowa, ba na tobali mo''ömö niha si manö,[2]', '["MozIII 6:2","MozIII 5:5"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 7, 'ba ndra mu''ombakha''ö horö andrö, nifazökhira, ba la''ali zinagöra andrö, böi ambö, ba sambua ni''olima wa''ebuania lanönö, ba ba nilimora labe''e.[3]', '["MozIII 6:2","MozIII 5:5"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 8, 'Ba na lö sahatö ba da''ö, ba nibe''e ogauta andrö ena''ö, ba khö Yehowa möi gogauta andrö nibe''e, tana ba gere, lö lai mbiri-biri si matua andrö, fangatulö, nibe''e ba wangatulö ya''ia.', '["MozIII 6:2","MozIII 5:5"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 9, 'Ba fefu zi no amaedola wegero andrö, föfö game''ela Ndraono Gizeraeli andrö, ni''amoni''ö, fefu, ni''ohera khö gere, ba tana khönia.', '["MozIII 6:2","MozIII 5:5"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 10, 'Fefu hadia ia ni''amoni''ö niha, ba khönia; hadia ia nibe''e niha khö gere, ba no khönia.', '["MozIII 6:2","MozIII 5:5"]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 11, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 12, 'Hede ba Ndraono Gizeraeli, ömane khöra: Na mosala ndronga niha, na ilimo ia,', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3473288, 'OT', 'Moze IV', 5, 13, 'na so zorudu khönia [niha bö''ö] ba na lö irongo sodonga ya''ia, na lö teboka, he ŵa''ae no rai''ö ia ibe''e, ba na lö''ö göi si so ba mbörö, na lö mura''u baewawö,', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 14, 'ba na tesao khönia wa''olohu, na oloho ia ba khö ndrongania, me no ra''iö ia ibe''e — ma na tesao khönia wa''olohu, fa olohu ia ba khö ndrongania, he ŵa''ae lö si ra''iö ia —', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 15, 'ba yamu''ohe khö gere ndrongania niha da''ö, ba i''olohe''ö sumange andrö, niŵa''ö, nibe''e, ba khönia andrö: sadumba hamo gandru, ba lö tola ilau yaŵa wanikha, ba he kumöyö, ba lö tola ilau. Me no sumange ni''a, ba wa''olohu, sumange ni''a fama''ele''ö, famokai horö.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 16, 'Ba yamufa''aso ia [ndra alawe andrö] ere, yamube''e föna Yehowa.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 17, 'Ba ihalö nidanö ni''amoni''ö ere, ba nahia tanö; ba tanö ma''ifu ihalö ere, tou, baose, ba ilau ba nidanö andrö.', '["mondröni ba duna: molohe samösa niha föna zanguhuku."]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 18, 'Ba ibe''e föna Yehowa ndra alawe andrö ere, idudugö mbunia ba ibe''e ba dangania zumange ni''a andrö, sumange fama''ele''ö — no sumange ni''a, ba wa''olohu; ba idanö safeto andrö, idanö fangelifi, ba i''ohe tangania ere.', '["mondröni ba duna: molohe samösa niha föna zanguhuku."]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 19, 'Ba idöni ba duna[4] ndra alawe ere, imane khönia: Na lö sorudu khöu niha, na lö si sala ndra''ugö ba na tenga si ra''iö ndra''ugö ba na lö horöu khö ndrongau, ba böi yatobali famunumö nidanö safeto andre, idanö fangelifi.', '["mondröni ba duna: molohe samösa niha föna zanguhuku."]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 20, 'Ba na no atö mosala ndra''ugö, na so horöu khö ndrongau, na no ra''iö ndra''ugö öbe''e, na no urudu khöu niha bö''ö, baero ndrongau —', '["mondröni ba duna: molohe samösa niha föna zanguhuku."]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 21, '(ba yamube''e ba hölu ndra alawe andrö ere, ba hölu fangelifi, imane ba ndra alawe andrö ere:) Yamube''e ni''elifi ndra''ugö Yehowa, ba niwami; yamube''e Yehowa ariri zolamö ba abao dalumö;', '["mondröni ba duna: molohe samösa niha föna zanguhuku."]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 22, 'ba yamutörö mbetu''au idanö fangelifi andre, ena''ö abao dalumö ba ena''ö ariri zolamö! Ba imane dania ira alawe: Yaduhu! Yaduhu!', '["mondröni ba duna: molohe samösa niha föna zanguhuku."]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 23, 'Ba itanö ba zura wangelifi andrö ere, ba isasai ba nidanö safeto andrö,', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 24, 'ba ifabadugö ba ndra alawe andrö nidanö safeto andrö, idanö fangelifi, ena''ö itörö dalunia idanö fangelifi andrö ba ena''ö afeto khönia.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 25, 'Ba ihalö sa''ae ba danga ndra alawe zumange ni''a andrö ere, sumange ba wa''olohu andrö; ihahae zumange ni''a andrö föna Yehowa, ba i''ohe ba naha wame''e sumange.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 26, 'Ba ihalö zi sadane ere, föfö zumange ni''a andrö, ihalö samohua, nibe''e, föfönia, ba itunu ba naha wame''e sumange; aefa da''ö, ba ifabadugö ba ndra alawe andrö nidanö andrö.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 27, 'Ba na no ifabadugö khönia nidanö, ba na si ra''iö ia, na no ilimo ndrongania, ba itörö dalunia idanö fangelifi andrö, ba tobali afeto khönia: abao dania dalunia ba ariri zolania, ba ni''elifi ndra alawe andrö na niwara.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 28, 'Ba na tenga si ra''iö ndra alawe andrö, na lö fa''ara''iönia, ba lö göna ia hadia ia, ba tola manabina ia.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 29, 'Da''ö gamakhoita ba wa''olohu. Na mosala ndra alawe, na so horönia khö ndrongania, na si ra''iö ia,', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 30, 'ba ma zui na tesao wa''olohu ba ndra matua, na olohu ia ba khö ndrongania, ba yamu''ohe föna Yehowa ndra alawe andrö, ba yamufatörö khönia nifakhoi andrö, fefu.', '[]', NULL),
  (3473288, 'OT', 'Moze IV', 5, 31, 'Ba ira matua andrö, ba si lö horö; ba ira alawe si manö ba ilu''i horönia.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 2, 'Hede ba Ndraono Gizeraeli, ömane khöra:', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 3, 'ba lö tola ibadu nagu ba hadia ia nibadu si mabu niha; ba he na no mubali''ö nirö aisö (zuka) ba lö tola ibadu; fefu hadia ia, na ösi mbua nagu mböröta, ba lö tola ibadu, ba bua nagu, he sauri, ba he ni''oköli''ö, ba lö tola i''a.[1]', '["Sanguhuk 13:4,5; Luk 1:15"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 4, 'Götö ni''amoni''ö ia, ba lö töla i''a hadia ia nihalö ba nagu, he hunö, ba he uli.', '["Sanguhuk 13:4,5; Luk 1:15"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 5, 'Götö wa''ara, nifabu''unia ya''ia ni''amoni''ö ba lö tola itörö högönia fanöŵö. Irege no numalö götö nifabu''unia ya''ia, ba ni''amoni''ö ia laŵa''ö; bunia, ba ifotuwu.[2]', '["SamI 1:11"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 6, 'Götö wa''ara nifabu''unia ya''ia khö Yehowa, ba lö tola möi ia ba zi mate.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 7, 'Na mate namania, ba ma inania, ba ma talifusönia matua, ba ma talifusönia alawe, ba lö tola ihalö fa''ara''iönia, me no tohare khönia we''amoni''ö andrö khö Lowalanginia.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 8, 'Götö we''amoni''ö andrö khönia, ba ni''amoni''ö khö Yehowa ia.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 9, 'Ba na so zi mate, si lö mudöna-döna, ba zi so ia, na ra''iö ba zi manö högönia andrö, si no mu''amoni''ö, ibe''e, ba itöwö mbunia; na luo si fitu itöwö.', '["MozIII 5:7"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 10, 'Ba na luo si ŵalu, ba dombua i''ohe fune ba ma ono marafadi, dombua, i''ohe khö gere, ba zinga mbawandruhö nose wama''ele''ö.[3]', '["MozIII 5:7"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 11, 'Ba ibe''e sumange fameta horö zi sambua ere, ba sumange nitunu zi sambua, ifaigi khönia wangatulö ba da''ö, me no mosala ia ba zi mate andrö; ba na luo da''ö, ba ifuli ni''amoni''ö högönia iŵa''ö,', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 12, 'ba ifuli i''amoni''ö ia khö Yehowa fa''ara nifabu''unia [föna], ba ono mbiri-biri si döfi fa''ebua i''ohe sumange ogauta; ba tobali si lö mu''erai zi no numalö irege da''ö, me no ra''iö we''amoni''ö andrö khönia.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 13, 'Ba da''ö gamakhoita ba ni''amoni''ö khö Lowalangi: na no ahöwö götö we''amoni''ö andrö, nifabu''unia, ba la''ohe ia ba zinga mbawandruhö nose wama''ele''ö.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 14, 'Ba sumange nibe''enia khö Yehowa, ba ono mbiri-biri si lö si sala, si döfi fa''ebua, sumange nitunu, ba ono mbiri-biri si alawe, si lö si sala, si döfi fa''ebua, sumange fameta horö, ba biri-biri si matua, si lö si sala, sumange fangorifi.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 15, 'Ba baero ö, ba samba kude kue si lö mu''aisöni, hamo si sökhi, nifaruka fanikha ba kue sanifi, nigule''ö fanikha, ba sumange ni''a andrö ba sumange nibadu, si faböbö ba da''ö.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 16, 'Ba i''ohe föna Yehowa ere, ba i''asiwai khönia zumange fameta horö ba sumange nitunu.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 17, 'Ba biri-biri si matua andrö, ba i''asiwai sumange Yehowa, sumange fangorifi, awö gude andrö, si so si lö mu''aisöni; ba he sumange ni''a ba sumange nibadu andrö, ba i''asiwai khönia ere.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 18, 'Ba yamutöwö sa''ae mbunia, ba högönia ni''amoni''ö, niha andrö, ni''amoni''ö khö Lowalangi, ba da''ö, föna mbawandruhö nose wama''ele''ö, ba yamuhalö mbunia andrö, ni''amoni''ö, yamutibo''ö ba galitö zumange andrö, ba galitö zumange fangorifi andrö.[4]', '["HalZin 21:24"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 19, 'Aefa da''ö, ba ihalö ere da''io mbiri-biri si matua andrö, si no murino, ba sagörö kue si lö mu''aisöni ba gude no mege ba sagörö kue sanifi, si lö mu''aisöni, ba ibe''e ba danga ni''amoni''ö andrö, na no itöwö mbunia andrö, ni''amoni''ö.', '["MozII 29:27"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 20, 'Ba ihahae ere föna Yehowa nihahae; tana khö gere ia, ame''ela ni''amoni''ö, lö lai nosu andrö, nihahae ba faha andrö, fegero andrö. Awena tola ibadu nagu niha ni''amoni''ö andrö.[5]', '["MozII 29:27"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 21, 'Da''ö gamakhoita ba ni''amoni''ö andrö, si no mamabu''u ya''ia — hadia gömönia ba Lowalangi, ba we''amoni''ö ya''ia andrö, lö lai zi tola ibe''e na [baero ö]. Ömö ba gamabu''ula li andrö, me ifabu''u ia, ba itörö, dali gamakhoita andrö, ba we''amoni''ö andrö khönia.', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 22, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 23, 'Hede khö ndra A''aroni iraononia, ömane: Na mifahowu''ö Ndraono Gizeraeli, ba mimane khöra:', '[]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 24, 'Yamufahowu''ö ndra''ugö Yehowa, yamurorogö ndra''ugö![6]', '["Sin 64:2; 134:3"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 25, 'Yamufohaga mbawania khöu Yehowa, yamu''ebua''ö dödönia khöu!', '["Sin 64:2; 134:3"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 26, 'Yamufalemba hörönia khöu Yehowa, yamube''e wa''ohahau dödö khöu!', '["Sin 64:2; 134:3"]', NULL),
  (3475692, 'OT', 'Moze IV', 6, 27, 'Ndramube''e tohare ba Ndraono Gizeraeli döigu, ba ya''odo zamahowu''ö ya''ira.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 1, 'Ba me no awai ifa''anö nose andrö Moze ba me no ibayoini ba me no i''amoni''ö, awö wakake khönia fefu, ba me no ibayoini göi naha wame''e sumange ba me no i''amoni''ö, awö wakake khönia fefu,', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 2, 'ba la''ohe zumange satua Ndraono Gizeraeli, högö madora andrö — salaŵa ganara andrö, satua ni''ofaya no.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 3, 'Ni''ohera khö Yehowa, ame''elara, ba önö gureta nifosagö, ba felendrua nono zawi — daru-darua zalaŵa, ba sambu-sambua kureta ba sara nono zawi zamösa; da''ö la''ohe föna nose.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 4, 'Ba imane Yehowa khö Moze:', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 5, 'Tema khöra, ena''ö te''oguna''ö ba nilau andrö, ba nose wama''ele''ö; ba ba danga Nono Lewi öbe''e, öfaigi hadia zoguna ba halöŵö zamösana.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 6, 'Ba itema Moze gureta andrö, awö nono zawi ba ibe''e ba danga Nono Lewi.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 7, 'Dombua gureta ba öfa nono zawi ibe''e ba danga ndraono Gereso, balazi hadia zoguna ba halöŵöra.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 8, 'Ba öfa gureta ba ŵalu nono zawi ibe''e ba danga ndraono Merari, balazi hadia zoguna ba halöŵöra, barö mbawa Gitamari andrö, ono Ga''aroni ere.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 9, 'Ba ba ndraono Gahati, ba lö''ö, me solohe ni''amoni''ö [sibai] andrö ira; ni''osa''ö da''ö.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 10, 'Ba la''ohe salaŵa game''ela ba we''amoni''ö naha wame''e sumange, me luo tebayoini ia; föna naha wame''e sumange labe''e zumange andrö khöra salaŵa.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 11, 'Ba imane Yehowa khö Moze: Samösa ma''ökhö ndramube''e salaŵa zumange andrö khöra, ba we''amoni''ö naha wame''e sumange.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 12, 'Ba si börötaigö mame''e sumange khönia, ba Nahaso, ono Gaminadabi, mado Yuda.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 13, 'Ba sumange andrö khönia, ba mako firö, 130 rufia fanulo, ba figa sebua, firö, 70 rufia fanulo ba zaga ni''amoni''ö, faoma nifo''ösi hamo si sökhi, nifaruka fanikha, sumange ni''a, ba sambua wiga ana''a,', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 14, '10 rufia fanulo, nifo''ösi samohua nitunu, ba sara nono zawi,', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 15, 'si matua, ba sageu mbiri-biri si matua, ba sara nono mbiri-biri, si matua, si döfi fa''ebua, sumange nitunu, ba sageu nambi si matua,', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 16, 'sumange fameta horö;', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 17, 'ba sumange fangorifi, ba dua rozi nono zawi, ba lima nga''eu mbiri-biri si matua ba lima nga''eu nambi si matua, ba lima rozi nono mbiri-biri, si matua, si döfi fa''ebua. Da''ö game''ela Nahaso andrö, ono Gaminadabi.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 18, 'Ba mahemolu ö, ba Natana''eli, ono Zuara, salaŵa mado Izasari.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 19, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 23, 'Ba sumange khönia ba mako firö, 130 rufia fanulo, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Natana''eli andrö, ono Zuara.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 24, 'Ba me luo si tölu, ba salaŵa Ndraono Zebuloni, Eliabi andrö, ono Helono.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 25, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 29, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Geliabi andrö, ono Helono.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 30, 'Ba me luo si öfa, ba salaŵa Ndraono Rubeno, Elisuri andrö, ono Zedeuri.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 31, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 35, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Gelisuri andrö, ono Zedeuri.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 36, 'Ba me luo si lima, ba salaŵa Ndraono Zimeoni, Selumieli andrö, ono Zuri-Sada''i.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 37, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 41, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Zelumieli andrö, ono Zuri-Sada''i.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 42, 'Ba me luo si önö, ba salaŵa Ndraono Gado, Eliazafi andrö, ono Degueli.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 43, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 47, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Geliazafi andrö, ono Degueli.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 48, 'Ba me luo si fitu, ba salaŵa Ndraono Geferayi, Eliazama andrö, ono Gamihudi.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 49, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 53, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Geliazama andrö, ono Gamihudi.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 54, 'Ba me luo si ŵalu, ba salaŵa Ndraono Manase, Gamelieli andrö, ono Wedasuri.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 55, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 59, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Gamelieli andrö, ono Wedasuri.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 60, 'Ba me luo si siŵa, ba salaŵa Ndraono Mbeniyami, Abidano andrö, ono Gideono.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 61, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 65, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Gabidano andrö, ono Gideono.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 66, 'Ba me luo si fulu, ba salaŵa Ndraono Dano, Ahiezeri andrö, ono Ami-Sada''i.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 67, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 71, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Gahiezeri andrö, ono Ami-Sada''i.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 72, 'Ba me luo si felezara, ba salaŵa Ndraono Gaseri, Fagieli andrö, ono Okherana.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 73, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 77, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Wagieli andrö, ono Okherana.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 78, 'Be me luo si felendrua, ba salaŵa Ndraono Nafetali, Ahira andrö, ono Genani.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 79, '–', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 83, 'Ba sumange khönia, ba mako firö, ba si manö sa''ae, si mane khö Nahaso no mege. Da''ö game''ela Gahira andrö, ono Genani.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 84, 'Da''ö we''amoni''ö naha wame''e sumange andrö, me luo tebayoini ia, nibe''e zalaŵa Ndraono Gizeraeli: 12 mako firö ba 12 wiga sebua firö ba 12 wiga ana''a; sambu-sambua mako,', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 85, 'ba 130 rufia fanulo, ba sambu-sambua figa sebua, ba 70 rufia; firö gama-gama andrö fefu, ba 2400 rufia fanulo, ba zaga ni''amoni''ö.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 86, 'Felendrua wiga ana''a, nifo''ösi samohua nitunu; sambu-sambua figa ba 10 rufia fanulo, ba zaga ni''amoni''ö; ana''a wiga andrö fefu, ba 120 rufia fanulo.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 87, 'Ba sawi fefu, sumange nitunu, ba 12 nono zawi; ba 12 mbiri-biri si matua, ba 12 rozi nono mbiri-biri, si matua, si döfi fa''ebua, awö zumange ni''a andrö, nifao ba da''ö, ba 12 nambi si matua, sumange fameta horö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475693, 'OT', 'Moze IV', 7, 88, 'Ba fefu zawi, sumange fangandrö saoha gölö, ba 24 nono zawi; ba 60 mbiri-biri si matua, ba 60 nambi si matua, ba 60 rozi nono mbiri-biri, si matua, si döfi fa''ebua.', '[]', NULL),
  (3475693, 'OT', 'Moze IV', 7, 89, 'Ba na möi bakha Moze ba nose wama''ele''ö, fahuhuo khö Yehowa, ba irongo linia khönia, moroi ba lagö-lagö andrö, ba dete dawöla zura goroisa, moroi ba naha andrö ba gotalua gerubi andrö, si dombua; si manö wehedenia khönia.[1]', '["MozII 25:22"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 1, 'Ba humede Yehowa khö Moze, imane:', '["MozII 25:37"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 2, 'Hede khö Ga''aroni, ba ömane khönia: Na öbe''e ba naha wandru wandru andrö, ba miföna naha wandru haga wandru andrö, si fitu, öbe''e.[1]', '["MozII 25:37"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 3, 'Ba i''o''ö da''ö A''aroni; tanö föna ba naha wandru ibe''e wandru andrö, dali niŵa''ö Yehowa khö Mose.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 4, 'Ba naha wandru andrö, ba no ana''a niböbözi mege, wamazökhi ya''ia; he tölania, ba he bunga andrö khönia, oi ana''a niböbözi, dali wamaedo andrö, ni''oroma''ö Yehowa khö Moze, si manö ifazökhi naha wandru andrö.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 5, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 6, 'Tutuyu Nono Lewi ba Ndraono Gizeraeli bö''ö, ba haogö ira.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 7, 'Ömane khöra, wangehao ya''ira: Ötefe ira idanö fameta horö, ba latöŵö mbura, ma''asageu ya''ira, lababago nukhara ba lahaogö ira.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 8, 'Ba lahalö nono zawi, si matua, awö zumange ni''a, si faböbö ba da''ö — hamo si sökhi nifaruka fanikha — ba ya''ugö, ba sara tö öhalö ono zawi, si matua, sumange fameta horö.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 9, 'Ba öfa''aso nono Lewi föna nose wama''ele''ö ba öfalukha''ö zato Ndraono Gizeraeli fefu.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 10, 'Awena dania muhede''ö ba nono Lewi, föna Yehowa ba latufa tangara Nono Lewi Iraono Gizeraeli.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 11, 'Ba ihahae Nono Lewi A''aroni, föna Yehowa, sumange nihahae, nibe''e Ndraono Gizeraeli, ena''ö lahalö-halö halöŵö andrö khö Yehowa.[2]', '["MozII 29:24"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 12, 'Ba Ono Lewi, ba latufa tangara högö nono zawi andrö, ba ö''asiwai, si sara, ba sumange fameta horö, ba si sara, ba sumange nitunu khö Yehowa, ba wameta sala Nono Lewi.', '["MozII 29:24"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 13, 'Ba ö''ohe khö ndra A''aroni iraononia Nono Lewi, ba öhahae ira sumange nihahae khö Yehowa.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 14, 'Ba ö''oniagö Nono Lewi ba Ndraono Gizeraeli, ena''ö tana khögu Nono Lewi andrö.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 15, 'Ba aefa da''ö, ba hana na möi bakha Nono Lewi, ba wangai halöŵö ba nose wama''ele''ö; ömanö wangehao ya''ira ba öhahae sumange nihahae.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 16, 'Buala Ndraono Gizeraeli khögu manö sa''ae ira, salahi zi a''a ba wa''atumbu, fefu, si a''a ndraono ba Ndraono Gizeraeli fefu, wa no uhalö ira khögu.[3]', '["Faigi 3:12","MozII 13:2"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 17, 'Me no khögu fefu zi a''a ba wa''atumbu, ba Ndraono Gizeraeli, he ba niha, ba he ba gurifö. Me luo ubunu no zi a''a ba wa''atumbu ba danö Miserayi u''amoni''ö ira khögu.[4]', '["Faigi 3:12","MozII 13:2"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 18, 'Ba no uhalö Nono Lewi, salahi zi a''a andrö, fefu, ba Ndraono Gizeraeli.', '["Faigi 3:12","MozII 13:2"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 19, 'Ba no ube''e tana khö ndra A''aroni iraononia Nono Lewi andrö nitutuyu ba Ndraono Gizeraeli, ena''ö lahalö-halö halöŵö andrö ba nose wama''ele''ö, soguna ba Ndraono Gizeraeli, ba ena''ö ba''a-ba''a Ndraono Gizeraeli ira, fa lö göna famakao Ndraono Gizeraeli, na lahatö''ö ena''ö ira ba ni''amoni''ö andrö.', '["Faigi 3:12","MozII 13:2"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 20, 'Ba lamanö ba Nono Lewi andrö ira Moze A''aroni ba sato Ndraono Gizeraeli fefu; la''o''ö sibai niŵa''ö Yehowa khö Moze, ba Nono Lewi andrö; si manö wolau Ndraono Gizeraeli khöra.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 21, 'Ba lafabeta''ö horöra Ono Lewi, ba lababago nukhara; ba ihahae ira A''aroni sumange nihahae, ba ifaigi khöra wangatulö, ba wangehao ya''ira.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 22, 'Ba aefa da''ö, ba möi bakha ba nose Nono Lewi, ba wangai halöŵöra ba nose wama''ele''ö, barö mbawa ndra A''aroni iraononia; dali niŵa''ö Yehowa khö Moze ba Nono Lewi andrö; si manö wolaura khöra.', '[]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 23, 'Ba humede Yehowa khö Moze, imane:', '["Faigi 4:3"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 24, 'Da''ö ia, ba Nono Lewi andrö: Na 25 fakhe ia ba ma si a''a moroi andrö, ba lafataro ia, ba wanolo ba halöŵö andrö, ba nose wama''ele''ö.[5]', '["Faigi 4:3"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 25, 'Ba na 50 fakhe ia, ba aefa ia ba halöŵö; alakha lö''ö sa''ae mohalöŵö.', '["Faigi 4:3"]', NULL),
  (3475694, 'OT', 'Moze IV', 8, 26, 'Ba hana na möi ia tohu-tohu danga dalifusönia ba nose wama''ele''ö, ba wangai halöŵö andrö; ba si ndruhu halöŵö, ba lö''ö sa''ae ihalö. Si manö wolaumö ba Nono Lewi andrö, ba halöŵöra andrö.', '["Faigi 4:3"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 1, 'Ba humede Yehowa khö Moze, ba danö si mate, ba gahe hili Zina''i, me döfi si dua, aefa aheta ira ba danö Miserayi, me baŵa si föföna, imane:', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 2, 'Böi zi lö lalau gowasa fasa Iraono Gizeraeli, na baŵania.[1]', '["MozIII 23:5"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 3, 'Ba zi meweleöfa ba baŵa da''e lalau, na bongibongi, ba ginötönia; mi''o''ö nifakhoi fefu, awö nihonogöi ba khönia, wolau ya''ia.', '["MozIII 23:5"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 4, 'Ba iŵa''ö Moze ba Ndraono Gizeraeli, lalau wasa andrö.', '["MozIII 23:5"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 5, 'Ba lalau wasa ba mbaŵa si föföna andrö, ba zi meweleöfa, me bongi-bongi, ba danö si mate, ba gahe hili Zina''i; la''o''ö sibai niŵa''ö Yehowa khö Moze; si manö wolau Ndraono Gizeraeli.', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 6, 'Ba so niha si no ra''iö ba zi mate, ba tobali tebai lalau wasa, me luo da''ö. Ba möi ira khö ndra Moze A''aroni, me luo da''ö,', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 7, 'lamane khönia: No ra''iö ndra''aga ba zi mate, ba hana wa te''ambösi ndra''aga, me tebai ba ginötönia mabe''e zumange andrö khö Yehowa, awö Ndraono Gizeraeli bö''ö?', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 8, 'Ba imane khöra Moze: Mibase''ö, da''ufondrondrongo ua, hadia niŵa''ö Yehowa ba khömi andrö.', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 9, 'Ba humede Yehowa khö Moze, imane:', '["MozII 12:8","MozII 12:46"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 10, 'Ŵa''ö ba Ndraono Gizeraeli: Na so, ha niha ia, ba khömi, ba ma ba nga''ötömi dania, zi no ra''iö ba zi mate, ba ma si no mofanö mukoli, ba ilau zui wasa khö Yehowa.', '["MozII 12:8","MozII 12:46"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 11, 'Ba mbaŵa si dua, ba zi meweleöfa, na bongi-bongi, lalau, lafo''awö roti si lö mu''aisöni ba gule-gule safeto, wemanga ya''ia.[2]', '["MozII 12:8","MozII 12:46"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 12, 'Lö tola lasaigö hadia ia, irege mahemolu, ba sara töla lö tola lafatö khönia; la''o''ö fefu nifakhoi ba wolau fasa andrö, wolau ya''ia.[3]', '["MozII 12:8","MozII 12:46"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 13, 'Ba si lö fa''ara''iö ba si tenga si möi mukoli, ba na lö ilau wasa, ba nise''e ia a niwara, me no lö nibe''enia sumange andrö khö Yehowa, me inötönia, no tohare khönia horö ibe''e niha si manö.', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 14, 'Ba na so ba khömi niha bö''ö, ba na ilau wasa khö Yehowa, ba dali khönia nifakhoi andrö, awö nihonogöi ba wolau fasa andrö. Ha sara gamakhoita khömi fefu, he ba niha bö''ö, ba he ba niha ba danö.[4]', '["MozII 12:49"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 15, 'Ba me luo tefa''anö nose andrö, ba ibalugö lawuo nose — ose nahia zura goroisa — ba na bongi, ba yaŵa nose so ia, hulö haga galitö.[5]', '["MozII 40:38"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 16, 'Ba si manö-manö dania: ibalugö ia lawuo, ba ba zi bongi, ba hulö haga galitö, irugi moluo.', '["MozII 40:38"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 17, 'Ba ero na ifazaŵa ia lawuo, na iheta ia ba nose, ba lafazaŵa göi ira Iraono Gizeraeli, ba ba zadada lawuo andrö, ba da''ö molombase Ndraono Gizeraeli.', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 18, 'Dali goroisa Yehowa ba wamazaŵa Ndraono Gizeraeli ya''ira ba dali goroisa Yehowa ba wolombasera, fatua ahono yaŵa nose lawuo, ba lö labulö''ö ira ba golombaseŵa.[6]', '["MozII 40:37"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 19, 'Ba na iradö ia yaŵa nose lawuo, ba la''o''ö nilau Yehowa Iraono Gizeraeli, lö lafazaŵa ira.', '["MozII 40:37"]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 20, 'Ba so göi, ba ha mato tölu bongi lawuo yaŵa nose; dali goroisa Yehowa ba wolombasera ba dali goroisa Yehowa ba wamazaŵara ya''ira.', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 21, 'Ba so göi, ba sara wongi lawuo, ba na ifazaŵa ia na moluo, ba lafazaŵa göi ira. Ba so zui, ba sara luo sara mbongi ia, ba na ifazaŵa ia lawuo, ba lafazaŵa göi ira.', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 22, 'Ba so, ba dua wongi ia ba ma sara waŵa, ba ma ara moroi andrö, na iradö ia yaŵa nose lawuo, na ahono ia yaŵania, ba lö labulö''ö ira ba golombaseŵa Iraono Gizeraeli, lö lafazaŵa ira. Ba na isaŵa yaŵa lawuo, ba lafazaŵa göi ira.', '[]', NULL),
  (3475695, 'OT', 'Moze IV', 9, 23, 'Dali goroisa Yehowa, ero na molombase ira, ba dali goroisa Yehowa, ero na lafazaŵa ira, la''o''ö nifakhoi Yehowa, dali goroisa Yehowa khö Moze.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 2, 'Fazökhi khöu dorofe, dombua, niböbözi, wamazökhiu ya''ia, soguna ba wame''e tandra ba zato, na lafazaŵa ira ba golombaseŵa.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 3, 'Na telau, ba sowulo khöu zato fefu föna nose wama''ele''ö.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 4, 'Ba na ha sambua telau, ba salaŵa andrö — högö Ndraono Gizeraeli — zowulo khöu.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 5, 'Ba na milau, fangekhugö niha, ba si so ba golombaseŵa tanö ba gatumbukha luo zamazaŵa ya''ira.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 6, 'Ba na milau zamuza tö, fangekhugö niha, ba si so ba golombaseŵa tanö miraya zamazaŵa ya''ira; nilau fangekhugö niha, na lafazaŵa ira ena''ö.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 7, 'Ba na ba wangowulo sato, ba milau manö, si tenga fangekhugö niha.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 8, 'Ba iraono Ga''aroni, ere andrö zolau torofe andrö; ba folau ya''ia, ba huku khömi dania, si lö tebulö, götö-götö wa''ara.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 9, 'Ba na lasuwö ami ba danömi emalimi, samakao ya''ami, ba na milau dorofe andrö, ba itörö tödö Yehowa, Lowalangimi, ami, ba te''efa''ö ami ba danga nemalimi andrö.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 10, 'Ba he göi na baŵa wa''omuso dödö khömi, ba gowasa andrö khömi ba ba wasulöna, ba milau dorofe andrö, na mibe''e zumange nitunu ba sumange fangorifi; ena''ö itörö tödö Lowalangi ami ibe''e; Yehowa ndra''odo, Lowalangimi.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 11, 'Ba ba ndröfi si dua, me baŵa si dua, ba zi mendröfa gofayaö, ba isaŵa yaŵa lawuo andrö, moroi ba nose zura goroisa.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 12, 'Ba lafazaŵa ira Iraono Gizeraeli, moniza-nizara, laheta ira ba danö si mate, ba gahe hili Zina''i, ba ba danö si mate Farana adada lawuo.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 13, 'Böröta wamazaŵara ya''ira da''ö, dali ni''oroi''ö Lowalangi khö Moze.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 14, 'Si föföna aheta, ba mandrera ba golombaseŵa Ndraono Yuda samba-sambawa; ba högö ngawawa andrö khöra, ba Nahaso andrö, ono Gaminadabi.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 15, 'Ba solohe ngawawa mado ndraono Izasari, ba Natana''eli andrö, ono Zuara,', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 16, 'ba solohe ngawawa mado ndraono Zebuloni, ba Eliabi andrö, ono Helono.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 17, 'Ba na no mududugö nose, ba lafazaŵa ira iraono Gereso ba iraono Merari, sangosa''ö ose.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 18, 'Aefa da''ö, ba aheta mandrera ba golombaseŵa mado Rubeno, samba-sambawa; ba solohe ngawawa andrö, si faböbö ba da''ö, ba Elisuri andrö, ono Zedeuri.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 19, 'Ba solohe ngawawa mado ndraono Zimeoni, ba Selumieli andrö, ono Zuri-Sadai.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 20, 'Ba solohe ngawawa mado ndraono Gado, ba Eliasafi andrö, ono Degueli.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 21, 'Aefa da''ö, ba lafazaŵa ira nga''ötö Gahati, sangosa''ö ni''amoni''ö andrö; ba irege so ira, ba no mufa''anö nose.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 22, 'Ba awena aheta mandrera ba golombaseŵa ndraono Geferayi samba-sambawa: ba solohe ngawawa si faböbö ba da''ö, ba Elisama andrö, ono Gamihudi.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 23, 'Ba solohe ngawawa mado ndraono Manase, ba Gamelieli andrö, ono Wedasuri.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 24, 'Ba solohe ngawawa mado ndraono Mbeniyami, ba Abidano andrö, ono Gideono.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 25, 'Ba aefa da''ö ba aheta mandrera ba golombaseŵa ndraono Dano, angohorita golombaseŵa fefu, samba-sambawa; ba solohe ngawawa, si faböbö ba da''ö, ba Ahiezeri andrö, ono Ami-Sada''i.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 26, 'Ba solohe ngawawa mado ndraono Gaseri, ba Fagieli andrö, ono Okherana.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 27, 'Ba solohe ngawawa mado ndraono Nafetali, ba Ahira andrö, ono Genani.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 28, 'Da''ö wamöfö''ö, na moniza-nizara Ndraono Gizeraeli wamazaŵa ya''ira, samba-sambawa.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 29, 'Ba me mofanö ira, ba imane Moze khö la''onia Hobaba, ono Regueli, Iraono Midiano andrö: Hiza, mofanö sa''ae ndra''aga, masaŵa danö nifabu''u Yehowa, wanguma''ö: ube''e khömi; ae awöma, ba lö ma''ambösi mböli gölöu; noa sa ifabu''u zi sökhi sibai ba Ndraono Gizeraeli Yehowa!', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 30, 'Ba imane: Lö omasido möido awömi; ufulido ba khöma, ba niwama.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 31, 'Ba i''andrö [khönia Moze], imane: Böi erogö ndra''aga; noa sa sangila ndra''ugö, heza mabe''e nahama wolombase, ba danö si mate, ba akha sangombakha lala khöma ndra''ugö.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 32, 'Na möi''ö awöma ba na falukhaga dania zi sökhi sibai andrö fefu, nibe''e Yehowa khöma, ba lö ma''ambösi mböli gölöu.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 33, 'Ba laheta ira ba gahe hili Yehowa, mofanö ira, tölu ngaluo, ba sowaö-waö fönara dawöla andrö, nahia zura goroisa Yehowa, zi tölu ngaluo fofanö andrö, ba wangalui naha wolombase khöra.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 34, 'Ba lawuo andrö khö Yehowa, ba yaŵara so na ma''ökhö, na laheta ira ba golombaseŵa.', '[]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 35, 'Ba na mofanö dawöla, ba imane Moze: Faoso Yehowa! ena''ö muzaewe zi fa''udu khöu, ba ena''ö moloi fönau zi fatiu tödö khöu![1]', '["Sin 68:2"]', NULL),
  (3475696, 'OT', 'Moze IV', 10, 36, 'Ba na irugi golombaseŵa, ba imane: Fuli''ö Yehowa ba zi mewulu ngahönö wa hönö andrö Iraono Gizeraeli!', '["Sin 68:2"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 1, 'Ba latahigö Yehowa niha sato, wa hulö nifakao ira, lafarongogö khö Yehowa.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 2, 'Ba la''angaröfi li Moze sato; ba mangandrö Moze khö Yehowa, ba mate galitö andrö.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 3, 'Andrö wa labe''e töi naha andrö Dabera (anunua) me no itörö ira alitö andrö, khö Yehowa, ba da''ö.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 4, 'Ba tesao wangisö ba niha bö''ö andrö, si no fao khöra; ba ifuli labörötaigö göi Iraono Gizeraeli mangarö-ngarö, lamane: Ha niha zame''e khöma diwo?[2]', '["MozII 12:38; Sin 106:14; KorI 10:6","Faigi 21:5"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 5, 'Itörö tödöma gi''a andrö, ni''ama mege ba danö Miserayi, si lö böli, ba la''izu andrö, ba baŵa limi ba kalamboza ba baŵa ba dasu.[3]', '["MozII 12:38; Sin 106:14; KorI 10:6","Faigi 21:5"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 6, 'Ba iya''e, ba si mate olofo ndra''aga, me lö hadia ia; lö hadia ia ma''ila, ha "mana" andrö.', '["MozII 12:38; Sin 106:14; KorI 10:6","Faigi 21:5"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 7, 'Ba "mana" andrö, ba no hulö mbua gatumba ba si mane mutiara wamaigida.[4]', '["MozI 2:12","MozII 16:21"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 8, 'Ba latöröi danö wangozaragö ya''ia ba lakisa, ba so göi, ba latutu; awena dania larino ba mbowoa, ba labali''ö kue sanifi; ba hulö kue nisala ba wanikha wa''ami.[5]', '["MozI 2:12","MozII 16:21"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 9, 'Ba na aekhu namo ba golombaseŵa ba zi bongi, ba aekhu göi yaŵa "mana" andrö.', '["MozI 2:12","MozII 16:21"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 10, 'Ba me irongo Moze mangarö-ngarö zamösana ba mbawandruhö nosenia, niha sato, samba-samba omo, ba mofönu sibai Yehowa ba anuzu sibai dödö Moze göi.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 11, 'Ba imane Moze khö Yehowa: Hana wa öfakao genoniu, ba hana wa lö''ö sa''ae ba dödöu ya''odo, wa öbe''e manö ba hulugu zi sambua soi andre?', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 12, 'Hadia, ya''odo mege zanabina si sambua soi andre ba ya''odo zadono ya''ia, wa öŵa''ö khögu iada''e: Hagi ia, si mane sangai ono ba ndraono si lö aefa na ba mbagi zusu, ba ohe ba danö andrö, nifabu''ugu khö ndra tuara fahölusa?', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 13, 'Heza uhalö ndriwo, ba wame''e ba zi sambua soi andre? Mangarö-ngarö ira khögu, lamane: Faigi khöma ndriwo, öma!', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475697, 'OT', 'Moze IV', 11, 14, 'Tebai u''ohe noro andrö, si so ba hulugu, ba zi sambua soi andre, tebai, na ha ya''odo; no tenga inötö norogu.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 15, 'Na ölau khögu da''ö, ba si sökhinia, na ödölö wamunu ya''o, na so atö ba dödöu ndra''odo, fa böi sa''ae ufaigi-faigi wamakaogu andrö.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 16, 'Ba imane Yehowa khö Moze: Kaoni khögu niha, 70, satua Ndraono Gizeraeli, ni''ilau wa no salaŵa ira ba mbanuara ba samaigi-maigi sato; ba nose wama''ele''ö ohe ira, ena''ö la''iagö ngaimö ba da''ö.[6]', '["MozII 18:21"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 17, 'Ba möido tou dania fahuhuo khöu ba da''ö, ba uhalö ma''ifu Geheha andrö, si no ahono khöu, ba ufa''ema khöra, ena''ö latolo''ö wolohe noro andrö ba niha andre, fa böi ha ya''ugö zi onoro ya''ia.', '["MozII 18:21"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 18, 'Ba ba niha sato, ba ömane: Mifaigi, fa lö fa''ara''iömi mahemolu, so gömi diwo donia; noa sa mangarö-ngarö ami, nirongo Yehowa, me mimane: Ha niha zame''e khöma diwo, öma? Noa sa ohahau dödöma ba danö Miserayi mege! Ba so dania khömi ndriwo ibe''e Yehowa, ena''ö lö ambö ömi.[7]', '["Yos 3:5","Faigi 21:5"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 19, 'Tenga ha ma''ökhö ba tenga ha dua ngaluo, ba tenga ha lima ba tenga ha fulu ba tenga ha dua wulu ngaluo mi''amanga''ö,', '["Yos 3:5","Faigi 21:5"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 20, 'alo''o sara waŵa wa''ara dania, irege tebai sa''ae mi''ago hua, irege ogoro ami; noa sa lö ba dödömi Yehowa, si soso ba khömi, ba no mangarö-ngarö ami ba no mimane: Hadia atö, wa aheta mege ita ba danö Miserayi?[8]', '["Yos 3:5","Faigi 21:5"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 21, 'Ba imane Moze: Önö ngaotu ngahönö zabölö niha andrö, si so ndra''o, ba öfabu''u, wanguma''ö: Modiwo ira ube''e, ba tobali alo''o sara waŵa wa''ara la''amanga''ö?', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 22, 'Hadia, tola tetaba öra mbiri-biri ba sawi, balazi abönö öra?', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 23, 'Ba imane Yehowa khö Moze: Hadia, no ambö wa''abölö Yehowa? Awena dania ö''ila, na itörö nifabu''ugu khöu, ba na lö''ö.[9]', '["Yes 50:2"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 24, 'Ba möi baero Moze mangombakha ba niha sato niŵa''ö Yehowa. Ba ikaoni zi fitu ngafulu, salaŵa mbanua, baero nose ifa''aso, fasui.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 25, 'Ba möi tou Yehowa ba lawuo andrö, fahuhuo khönia. Ba ihalö ma''ifu Geheha andrö, si no ahono khönia ba ifa''ema ba zi fitu ngafulu niha andrö, salaŵa andrö. Ba me manandrösa khöra Geheha ba mama''ele''ö ira, ba dania, ba lö''ö sa''ae.[10]', '["HalZin 10:44"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 26, 'Ba darua zi no toröi furi, ba golombaseŵa; Eledado döi zi samösa ba Medado zi samösa. Ba ba khöra göi möi Geheha, noa sa awö nitanö ba zura ira, ba lö si möi ira ba nose, ba tobali ba golombaseŵa mama''ele''ö ira.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 27, 'Ba fagohi nono matua samösa, isaŵa Moze, imane khönia: Mama''ele''ö ba golombaseŵa ndra Eledado Medado!', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 28, 'Ba imane Yosua andrö, ono Nuni, si no ngoni-ngoni Moze, i''otarai iraono ia: He Tuagu, Moze, tenaŵa ira!', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 29, 'Ba imane khönia Moze: Hadia, ya''ugö zame''e lala khögu? Ena''ö na sama''ele''ö manö mbanua Yehowa fefu, ena''ö ifa''ema khöra Gehehania Yehowa!', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 30, 'Ba ifuli ia ba golombaseŵa Moze, awö zatua Ndraono Gizeraeli andrö.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 31, 'Ba tesao nangi nifatörö Yehowa, sangoloi''ö siate moroi ba mbewe nasi, ifatörö ba golombaseŵa; ma''ökhö fofanö tanö andre ba ma''ökhö fofanö tanö sa, ba zi tefasui olombaseŵa, dua hela wa''awe''e-we''e aefa ba danö.[11]', '["MozII 16:13; Sin 78:27"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 32, 'Ba maoso ira, ma''ö-ma''ökhö ba sara wongi ba ma''ö-ma''ökhö mahemolu la''ozaragö ziate; si lö oya-oya mangozaragö, ba no mato 14 ngaso''e, ba labologö ba zi tefasui olombaseŵa [ba wangoköli''ö].', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 33, 'Ba me la''aga-aga na ndriwo andrö, me lö sahori na, ba tesao wönu Yehowa khöra, ba ifatörö khöra wamakiko sabölö-bölö.[12]', '["Sin 78:30,31"]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 34, 'Andrö wa labe''e töi naha andrö Kiberoti hata''awa (lewatö zolu''a-lu''a) me ba da''ö lako''o niha solu''a-lu''a andrö.', '[]', NULL),
  (3475697, 'OT', 'Moze IV', 11, 35, 'Ba i''otarai Kiberoti hata''awa, ba lasaŵa Haseroti, ba tebato ira ba Haseroti andrö.', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 1, 'Ba laböbögö khö Moze zi lö sökhi ira Miriya A''aroni, börö ndra alawe Ndrawa Gaitiofia andrö; noa sa ira alawe Ndrawa Gaitiofia nihalönia.[1]', '["MozII 2:21"]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 2, 'Ba lamane: Hadia, ha khö Moze mege fahuhuo Yehowa? Hadia, lö si fahuhuo ia khöma?', '["MozII 2:21"]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 3, 'Ba no sebolo sibai tödö Moze andrö, moroi ba niha bö''ö fefu ba guli danö.', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 4, 'Ba i''ogomuzaö imane Yehowa khö ndra Moze A''aroni Miriya: Mi''ae ba nose wama''ele''ö, datölu ami!', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 5, 'Ba möi ira, datölu ira.', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 6, 'Ba imane: Mifondrondrongo niŵa''ögu! Na so ba khömi zama''ele''ö ba u''oroma''ö ndra''o khönia ba gangilata, ba ma ba wangifi muhededo khönia.', '["Heb 3:2","MozII 33:11"]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 7, 'Ba tenga si manö khö genonigu Moze andrö; no ba dangania tebe''e fefu hadia ia yomo khögu.[2]', '["Heb 3:2","MozII 33:11"]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 8, 'Fahuo-huo ndra''o khönia, faudu wawa ndra''aga, ba tenga ba dahö-dahö, anehe ia nga''eu Yehowa. Ba hana wa lö ata''u ami miböbögö zi lö sökhi khö genonigu andrö, khö Moze andrö?[3]', '["Heb 3:2","MozII 33:11"]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 9, 'Ba mofönu sibai khöra Yehowa, ba iheta ia,', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 10, 'ba iheta göi ia ba nose lawuo.', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 11, 'Ba imane A''aroni khö Moze: He Tua, böi be''e horöma, me no hulö zowöhö mowa ndra''aga ba me no molalö ndra''aga!', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 12, 'Böi hulö nono si no mate moroi ba dalu ia, si no matonga obou ösi, na i''otarai dalu ninania!', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 13, 'Ba i''angaröfi li Yehowa Moze, imane: He Lowalangi, fadöhö khönia!', '[]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 14, 'Ba imane Yehowa khö Moze: Hadia na no idiloi mbawania amania, ba hadia, tenga fitu bongi wa''ara aila ia? Ba fitu bongi yamu''iagö baero golombaseŵa, ni''oniagö; ba na aefa da''ö, ba hana na lafuli lafa''amöi ia.[5]', '["MozIII 13:46"]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 15, 'Ba la''oniagö Miriya, baero golombaseŵa, fitu bongi. Ba lö latohugö wofanö, irege no mufuli mufa''amöi Miriya.', '["Faigi 10:12"]', NULL),
  (3475698, 'OT', 'Moze IV', 12, 16, 'Ba aefa da''ö, ba laheta ira ba Haseroti andrö, ba ba danö si mate Farana molombase ira dania.[6]', '["Faigi 10:12"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 2, 'Fatenge niha, ena''ö lafauzei danö Gana''ana andrö, nibe''egu ba Ndraono Gizeraeli dania; samösa zambua mado mifatenge, ha sambalö salaŵara.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 3, 'Ba ifatenge Moze, moroi ba danö si mate Farana, dali goroisa Yehowa, ha sambalö si no salaŵa ba Ndraono Gizeraeli.[1]', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 4, 'Ba da''e döira: Mado Rubeno, ba Samua, ono Zakuri;', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 5, 'ba mado Zimeoni, ba Safata, ono Hori;', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 6, 'ba mado Yuda, ba Kalebi, ono Yefune; ba mado Izasari,', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 7, 'ba Igeala, ono Yosefo; ba mado Geferayi,', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 8, 'ba Hosea, ono Nuni;', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 9, 'ba mado Mbeniyami ba Falati, ono Rafu,', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 10, 'ba mado Zebuloni, ba Gadieli, ono Zodi; ba mado Yosefo,', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 11, 'mado Manase andrö, ba Gadi, ono Zusi; ba mado Dano, ba Amieli,', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 12, 'ono Gamali; ba mado Gaseri,', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 13, 'ba Seturo, ono Mikha''eli;', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 14, 'ba mado Nafetali, ba Nahebi, ono Wofisi;', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 15, 'ba mado Gado, ba Göeli, ono Makhi.', '["MozV 1:22"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 16, 'Da''ö döi niha andrö nifatenge Moze, ba wamauze tanö. Ba töi Hosea andrö, ono Nuni, ba Yosua ibe''e Moze.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 17, 'Ba ifatenge ira Moze ba wamauze tanö Gana''ana andrö. Ba imane khöra: Mi''ae miyaŵa ba da''ö ba danö tanö raya, misösö hili andrö;', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 18, 'mifaigi he wisa danö andrö, ba na sabölö niha andrö, si so ba danö, ba na samomo, ba na sambö fa''ato, ba na si no ato;', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 19, 'he wisa gamuata danö andrö, ba zi so ira, na si sökhi, ba na si lö sökhi, ba he wisa mbanua, nahiara andrö, na ba danö manö so ira, ba na ba mbanua saro;', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 20, 'ba he wisa nowi göi, na satabö sinanö, ba na safuo; na so döla geu, ba na lö''ö. Ba mi''abe''e''ö sa''ae dödömi ba mi''ohe ba da''e ösa mbua danö! Ba no baŵa mbua nagu sahulö.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 21, 'Ba möi ira misi yaŵa, lafauzei danö, i''otarai danö si mate Sini andrö, irugi Rehobi, irege wabaliŵa lala ba Hamata.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 22, 'Möi ira misi yaŵa ba danö tanö raya ba larugi Heberona, banua ndra Ahima, Sezai, Talamai, nga''ötö Genaki andrö. Ba Heberona andrö, ba mewitu fakhe föna wanaru''ö Soana ba danö Miserayi tetaru''ö mege.[2]', '["Yos 15:14"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 23, 'Ba me larugi ndraso Esikoli andrö, ba lataba zara ndraha nagu, fabaya bua, sangamohi, ba darua zamabea, ba lahalö göi mbua dalimo ösa ba bua ara ösa.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 24, 'Ba andrö wa labe''e töi ndraso andrö ndraso Esikoli, ba mbua nagu andrö, nitaba Ndraono Gizeraeli ba da''ö.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 25, 'Ba me no irugi 40 wongi, me no lafauzei danö, ba lafuli ira.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 26, 'Mowaö-waö ira, ba larugi ndra Moze A''aroni ba Iraono Gizeraeli fefu, sato, ba danö si mate Farana, ba Gadesi; ba la''ombakha''ö khöra ba ba zato fefu lua-lua, ba la''oroma''ö khöra mbua danö andrö.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 27, 'Ba ladunö-dunö khö Moze, lamane: No marugi danö andrö, nifatengeu ya''aga. Si ndruhu sa, si falawu susu ba ŵe ŵani, ba ya''e mbua danö;', '["MozV 9:2"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 28, 'ba si ndruhu göi niha andrö, si so ba danö, ba no sabölö, ba banua, ba saro ba sebua sibai, ba noa göi ma''ila ba da''ö nga''ötö Genaki andrö.[3]', '["MozV 9:2"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 29, 'Ba danö tanö raya, ba Iraono Gamaleki; ba ba hili, ba Iraono Kheti, ba Iraono Yebusi ba Iraono Gamori; ba Dawa Gana''ana zi hene asi ba fatambai Yoridano.', '["MozV 9:2"]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 30, 'Ba Kalebi zondrara tödö zato ba khö Moze, imane: Möi zui ita misi yaŵa, tahalö khöda danö; tenga safökhö sibai wolaŵa ya''ira!', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 31, 'Ba lamane awönia si fao khönia mege misi yaŵa: Tebai tasuwö niha andrö, no sabölö abe''e ira!', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 32, 'Ba si lö sökhi la''ombakha''ö ba Ndraono Gizeraeli, ba danö andrö, nifauzeira, lamane: Tanö andrö nitöröima, ba wamauze ya''ia, ba i''aga-aga niha si so ba khönia, ba niha andrö fefu, ni''ilama ba da''ö, ba no si tenga inötö fa''ebua.', '[]', NULL),
  (3475699, 'OT', 'Moze IV', 13, 33, 'Ba no ma''ila göi ba da''ö niha andrö sebua sibai, nga''ötö Genaki andrö, awö zebua sibai andrö, ba amaedola lareŵe ndra''aga fönara, wamaigima, ba si manö göi wamaigira.', '[]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 1, 'Ba mu''ira-ira niha sato fefu, mangarö-ngarö ira ba zi bongi andrö.', '["Sin 106:25"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 2, 'Ba dozi Iraono Gizeraeli, ba kumökö-kökö khö ndra Moze A''aroni, lamane khöra sato fefu: Alai ndra''aga! ena''ö na mate mege ndra''aga ba danö Miserayi, ba ma ba da''e, ba danö si mate![1]', '["Sin 106:25"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 3, 'Hana wa edöna i''ohe ita ba danö andrö Yehowa, ena''ö ba mbawa zi''öli mate ita? Ba ö nemali wo''omoda ba iraono sawuyu khöda. Hadia, tenga si sökhinia, na tafuli ita ba danö Miserayi!', '["Sin 106:25"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 4, 'Ba faoma lamane khö nawöra: Datafaigi khöda zolohe ya''ita, ba tafuli ita ba danö Miserayi!', '["Sin 106:25"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 5, 'Ba lafalögu tou ira ba danö ira Moze A''aroni, föna Ndraono Gizeraeli sato, fefu, si no owulo ba da''ö.', '[]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 6, 'Ba lasika nukhara ira Yosua, ono Nuni, Kalebi, ono Yefune, si no fao göi ba wamauze tanö andrö,', '["MozV 20:3; Rom 8:31"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 7, 'ba lamane ba Ndraono Gizeraeli sato, fefu: Tanö andrö, nitöröima, ba wamauze ya''ia, ba no tanö si maulu fa''asökhi.', '["MozV 20:3; Rom 8:31"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 8, 'Na ebua dödö Yehowa khöda, ba i''ohe ita ba danö andrö ba ibe''e khöda — tanö si falawu susu ba ŵe ŵani!', '["MozV 20:3; Rom 8:31"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 9, 'Ba böi milaŵa Yehowa ba böi mi''ata''ufi niha ba danö andrö; ta''a sa''ae ira dania. No aheta khöra mba''a-ba''ara andrö, ba ya''ita, ba nitolo Yehowa; böi mi''ata''ufi ira![2]', '["MozV 20:3; Rom 8:31"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 10, 'Ba me hatö ma''ifu tö latebu kara ira sato fefu, ba oroma lakhömi Yehowa ba Ndraono Gizeraeli fefu, ba nose wama''ele''ö.', '[]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 11, 'Ba imane Yehowa khö Moze: Ha wa''ara tebato wango''aya niha andrö ya''o, wa lö faduhu dödöra khögu, lö lai dandra andrö fefu, si no ulau ba khöra andrö!', '["MozII 32:10"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 12, 'Da''ubunu ira fökhö waba, use''e ira, ba ya''ugö ube''e furugö soi [si bohou], sebua ba sato niha moroi khöra![3]', '["MozII 32:10"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 13, 'Ba imane Moze khö Yehowa: Ba larongo Dawa Miserayi; noa sa ö''ohe miyaŵa, moroi ba khöra, soi andre fa''abölömö andrö,', '["MozII 13:21","MozV 9:28","MozII 34:6,7; Yon 4:2"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 14, 'ba la''ombakha''ö ba niha ba danö andre, ba zi no terongo, wa ba hunö niha andre so ndra''ugö, ya''ugö Yehowa, awö wa no ö''oroma''ö ndra''ugö, fa fa''ila bawa. Ya''ugö Yehowa, awö wa no so yaŵara lawuo andrö khöu, wa mowaö-waö''ö fönara, na ma''ökhö, ba boto lawuo, ba ba zi bongi, ba boto galitö.[4]', '["MozII 13:21","MozV 9:28","MozII 34:6,7; Yon 4:2"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 15, 'Ba na öbunu soi andre, hulö na ha samösa, ba lamane dania soi bö''ö, si no mamondrongo turiamö andrö:', '["MozII 13:21","MozV 9:28","MozII 34:6,7; Yon 4:2"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 16, 'Me no tebai Yehowa, i''ohe ba danö andrö, nifabu''unia khöra fahölusa, soi andrö, andrö wa ibubunu ira ba danö si mate.[5]', '["MozII 13:21","MozV 9:28","MozII 34:6,7; Yon 4:2"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 17, 'Ena''ö na oroma sibai wa''abölöu, ya''ugö Yehowa, si mane nifabu''umö, me ömane.', '["MozII 13:21","MozV 9:28","MozII 34:6,7; Yon 4:2"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 18, 'Sebolo tödö Yehowa ba si no fahöna fa''ahakhö dödö; sala ba olalöŵa, ba ibe''e aefa, ba lö''ö sa aefa sibai wotu; horö ndra ama ihuku ba ndraono, irugi tölu, öfa nga''ötö.[6]', '["MozII 13:21","MozV 9:28","MozII 34:6,7; Yon 4:2"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 19, 'Be''e aefa horö niha andre, ba wa''ebua wa''ahakhö dödöu andrö, si mane fame''eu aefa horöra i''otarai ba danö Miserayi, irugi ma''ökhö!', '["MozII 13:21","MozV 9:28","MozII 34:6,7; Yon 4:2"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 20, 'Ba imane Yehowa: Ube''e aefa khöra, u''o''ö ni''andröu.', '["MozV 1:35; Sin 95:10,11; Heb 4:3","Yos 14:9"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 21, 'Ba si ndruhu-ndruhu: faya wa no sauri ndra''o, na faya wa anönö dania guli danö lakhömi Yehowa,', '["MozV 1:35; Sin 95:10,11; Heb 4:3","Yos 14:9"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 22, 'ba na la''ila dania danö andrö niha andrö fefu, si no mangila lakhömigu andrö, awö dandra andrö fefu, nilaugu ba danö Miserayi ba ba danö si mate, ba si no manandraigö zui ya''odo, no mewulu sa''ae, ba si lö mamondrongo ligu,', '["MozV 1:35; Sin 95:10,11; Heb 4:3","Yos 14:9"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 23, 'na la''ila danö andrö, nifabu''ugu khö ndra tuara fahölusa; samösa lö sangila dania, ya''ira andrö, fefu, si no mango''aya ya''o,[7]', '["MozV 1:35; Sin 95:10,11; Heb 4:3","Yos 14:9"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 24, 'Ba enonigu Kalebi andrö, si so Eheha bö''ö, ta''ila, ba si no molo''ö sibai khögu, ba u''ohe ba danö andrö, si möi ia mege ba la''okhögö dania madounia.[8]', '["MozV 1:35; Sin 95:10,11; Heb 4:3","Yos 14:9"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 25, 'Ba Iraono Gamaleki ba Dawa Gana''ana, ba ba zalo''o tanö so. Mahemolu, ba mifuli ami, mi''ae ba danö si mate, mitörö lala saekhu ba nasi zukhu.', '["MozV 1:35; Sin 95:10,11; Heb 4:3","Yos 14:9"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 26, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 27, 'Ha wa''ara döhö wekökö-kökö niha si lö sökhi andrö khögu? Fekökö-kökö Ndraono Gizeraeli andrö khögu, ba no urongo!', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 28, 'Ömane khöra: Faya wa no sauri ndra''o, iŵa''ö Yehowa, na lö ufatörö khömi niŵa''ömi andrö, nirongo dögi dalingagu.', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 29, 'Ba danö si mate andre adudu mbotomi, ha wa''ato ami ni''ofaya no — dozi, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, ya''ami si no mukökö-kökö khögu![9]', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475700, 'OT', 'Moze IV', 14, 30, 'Samösa lö sondrugi tanö andrö, motöi ya''ami andrö, tanö si no ututuru khömi, nahami, fahölusa, baero Kalebi andrö, ono Yefune, ba Yosua, ono Nuni.[10]', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 31, 'Ba iraono sawuyu khömi, niwa''ömi ö nemali dania — da''ö u''ohe ba danö dania, ena''ö la''ila danö andrö, ni''ositengagömi.', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 32, 'Ba botomi, ba sadudu ba danö si mate.', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 33, 'Ba iraonomi, ba 40 fakhe wa''ara lakubaloi guriföra ba danö si mate, huku wolaŵami andrö, balazi no ahori ase''e ami ba danö si mate.', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 34, 'Dali zi 40 ngaluo, me mifauzei danö andrö — sara ngaluo, ba döfi labe''e — tobali 40 fakhe milu''i huku lalömi andrö; ena''ö aboto ba dödömi, he wisa na uböda dangagu!', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 35, 'Ya''odo andre, Yehowa, zanguma''ö; si ndruhu, si manö dania wolaugu ba niha si lö sökhi andrö fefu, si no mamagölö ba wolaŵa ya''odo; ba danö si mate andre ahori ira, ba da''e mate ira.', '["Faigi 26:65; Heb 3:17","Yos 14:1"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 36, 'Ba mate niha andrö nifatenge Moze, ba wamauze tanö andrö, ba si no mamobörö fekökö-kökö zato fefu khönia, me mangawuli ira, wangombakha sata''u ira ba danö andrö — niha andrö,', '["KorI 10:10; Yud 5"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 37, 'si no mangombakha sata''u ira ba danö andrö, ba mate föna Yehowa, fa''amate si lö mudöna-döna.[11]', '["KorI 10:10; Yud 5"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 38, 'Awai zi lö mate niha andrö, si no möi mamauze tanö andrö, ha Yosua, ono Nuni, ba Kalebi, ono Yefune.', '["KorI 10:10; Yud 5"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 39, 'Ba me i''ombakha''ö ba Ndraono Gizeraeli fefu niŵa''ö andrö Moze, ba abu sibai dödöra.', '[]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 40, 'Ba mahemolu ö, ba lahulö wongi wanaŵa miyaŵa hili, lamane: Omasiga möi miyaŵa ba danö andrö, niŵa''ö Yehowa; noa sa mosala ndra''aga.', '[]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 41, 'Ba imane Moze: Hana wa edöna ami misawö zui niŵa''ö Yehowa? Lö''ö sa fakhai![12]', '["MozV 1:41"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 42, 'Böi mi''ae miyaŵa, lö''ö sa fao khömi Yehowa; fa böi te''ala ami labe''e emalimi andrö.', '["MozV 1:41"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 43, 'Udumi sa ba da''ö Ndraono Gamaleki ba Dawa Gana''ana, ba mate ami ba mbawa zi''öli. Me no mi''erogö Yehowa, ba lö''ö sa''ae itolo ami!', '["MozV 1:41"]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 44, 'Ba lö alulu; möi ira miyaŵa ba hili laŵa''ö ba tawöla zura goroisa Yehowa ba he Moze, ba lö aheta ba golombaseŵa.', '[]', NULL),
  (3475700, 'OT', 'Moze IV', 14, 45, 'Ba so Ndraono Gamaleki, awö Ndrawa Gana''ana, sowanua ba hili andrö, möi ira mitou, latimba ira ba muzawili irege Horema, labe''e.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 2, 'Hede ba Ndraono Gizeraeli, ömane khöra:', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 3, 'ba na mibe''e khö Yehowa zumange nifatörö ba galitö, he sumange nitunu ba he sumange nitaba, ma ba wanörö amabu''ula li, ba ma ame''ela saoha gölö, ba ma na baŵa gowasa andrö khömi, ba wame''e samohua khö Yehowa, sawi, ba ma biri-biri,', '["MozIII 6:14"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 4, 'ba same''e sumange Yehowa andrö, khönia, ba sambua ni''ofulu hamo si sökhi nifaruka fanikha, samba hinaoya, ifao sumange ni''a.[1]', '["MozIII 6:14"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 5, 'Ba agu, sumange nibadu, ba samba hinaoya ba zi sara ono mbiri-biri, öfao ba zumange nitunu ba ba zumange nitaba.', '["MozIII 6:14"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 6, 'Ba ba mbiri-biri si matua, ba öfao sumange ni''a dombua ni''ofulu hamo si sökhi nifaruka si tölu kata fanikha, ba agu, sumange nibadu,', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 7, 'ba tölu kata öbe''e khö Yehowa, samohua.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 8, 'Ba na ono zawi, si matua öbe''e sumange nitunu, ba ma sumange nitaba, ba wanörö amabu''ula li, ba ma sumange Yehowa, fangorifi, ba nifao ba nono zawi andrö,', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 9, 'sumange ni''a, ba tölu ni''ofulu hamo si sökhi, nifaruka si sadumba fanikha.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 10, 'Ba agu, sumange nibadu, ba sadumba öbe''e, sumange Yehowa, nifatörö ba galitö, samohua.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 11, 'Si manö wolau ba nono zawi fefu ba ba mbiri-biri si matua fefu ba ba nono mbiri-biri ba ba nono nambi fefu.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 12, 'Dali ha uga geu nibe''emi, ba sage-sageu, ba mimanö.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 13, 'Dozi niha ba danö zolo''ö amakhoita andrö, na labe''e zumange Yehowa, nifatörö ba galitö, samohua.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 14, 'Ba na so ba khömi niha bö''ö, ba ma si no ahono khömi, ba si manö göi ilau, dali wolaumi.', '["MozII 12:49"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 15, 'Ha sara lala, dozi, he ya''ami, ba he niha bö''ö, si soso khömi. Amakhoita si lö tebulö da''ö, götö-götö wa''ara; ba zumange Yehowa, ba faoma, he ba niha bö''ö, ba he ba khömi.[2]', '["MozII 12:49"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 16, 'Ha sara nihohogöi ba ha sara nifakhoi, he ba khömi, ba he ba niha bö''ö, si soso ba khömi.', '["MozII 12:49"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 17, 'Ba humede Yehowa khö Moze, imane', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 18, 'Hede ba Ndraono Gizeraeli, ba ömane khöra:', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 19, 'ba na mi''a mbua danö, ba mibe''e khö Yehowa zi no amaedola wegero, föfönia.', '["MozII 23:19"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 20, 'Si a''a hamo ni''otamböni khömi, ba sagörö kue mibe''e fegero, lala wame''e fegero ba golayama mbasitö wame''emi ya''ia.', '["MozII 23:19"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 21, 'Si a''a hamo ni''otamböni andrö khömi, ba mibe''e khö Yehowa ösa, sumange fegero, götö-götö wa''ara dania.[3]', '["MozII 23:19"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 22, 'Ba na so hadia ia zi lö mitörö amakhoita andrö, si lö mu''odödögö, oroisa Yehowa andrö khö Moze,[4]', '["MozIII 4:2"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 23, 'hadia ia, ni''oroi''ö Yehowa khömi, khö Moze, i''otarai luo andrö, me ibe''e goroisa Yehowa, ba dania na, götö-götö wa''ara,', '["MozIII 4:2"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 24, 'na tenga ni''odödögö zato, wa lö mutörö da''ö, ba sato fefu zame''e ono zawi, si matua, sumange nitunu, samohua khö Yehowa, nifao sumange ni''a ba sumange nibadu, nifao-fao ba da''ö, lalania, ba sageu nambi si matua, sumange fameta horö.', '["MozIII 4:2"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 25, 'Ba na no ifaigi ere wameta sala Ndraono Gizeraeli sato, fefu, ba tebe''e aefa khöra. Noa sa tenga ni''odödögö, ba no labe''e zumange khöra, sumange Yehowa nifatörö ba galitö, awö zumange fameta horö, khö Yehowa, ba lalöra andrö.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 26, 'Ba tebe''e aefa zala Ndraono Gizeraeli sato fefu ba sala niha bö''ö, si soso ba khöra; noa sa horö zato fefu, lalö andrö.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 27, 'Ba na so zi sala si lö mu''odödögö, na ha samösa, ba nambi si döfi fa''ebua ibe''e sumange fameta horö.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 28, 'Ba yamufaigi ere wameta sala zi no mosala khö Yehowa, si tenga ni''odödögö, wolau fameta sala andrö khönia, ba tebe''e aefa khönia.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 29, 'Ha sara lala khömi — he ba niha ba danö, Iraono Gizeraeli, ba he ba niha bö''ö, si soso ba khöra, na so zolau hadia ia, si lö mu''odödögö.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 30, 'Ba na so zolalö ni''odödögö, he niha ba danö, ba he niha bö''ö, ba sanandraŵaisi Yehowa, ba nise''e ba niwara niha si manö.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 31, 'Noa sa si lö guna li Yehowa ba si lö boto goroisania ibe''e; ba lö fulitö, ba nise''e niha si manö — ilu''i horönia.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 32, 'Ba me so ba danö si mate andrö Ndraono Gizeraeli, ba falukha ira niha sangozaragö eu, me luo sabato.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 33, 'Ba la''ohe ia khö ndra Moze A''aroni ba ba zato fefu si fakhamö khönia, me i''ozaragö geu, ba lakuru ia,', '["MozIII 24:12"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 34, 'me lö''ö na oroisa ba da''ö, he lawisa khönia.[5]', '["MozIII 24:12"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 35, 'Ba imane Yehowa khö Moze: Niha andrö, ba nibunu; sato fefu zanebu kara ya''ia, baero golombaseŵa.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 36, 'Ba la''ohe ia baero golombaseŵa sato fefu ba latebu kara, labunu, dali niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 37, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 38, 'Hede ba Ndraono Gizeraeli, öŵa''ö khöra lafobowo-bowo gahe mbarura ya''ira ba madoura dania; ba bowo-bowo andrö, ba ladozigö sinali ungu sowu waru-waru.[6]', '["MozV 22:12; Mat 23:5"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 39, 'Ba da''ö geluaha mbowo-bowo andrö khömi: na mifaigi ia, ba itörö tödömi goroisa Yehowa andrö fefu, ena''ö mi''o''ö ia, ba böi mihole''ö ami ba gisö-isö dödömi ba ba gomasiö hörömi, famaelungumi ba wangerogö Yehowa.', '["MozV 22:12; Mat 23:5"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 40, 'Ena''ö lö olifu ami goroisagu andrö fefu ba ena''ö mi''o''ö, fa ni''amoni''ö ami föna Lowalangimi.', '["MozV 22:12; Mat 23:5"]', NULL),
  (3475701, 'OT', 'Moze IV', 15, 41, 'Yehowa ndra''odo, Lowalangimi, si no mangeheta ya''ami ba danö Miserayi, ba we''amöi Lowalangimi, ya''odo andre, Yehowa, Lowalangimi!', '["MozV 22:12; Mat 23:5"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 1, 'Ba molaŵa Gora, ono Yesehari ono Gahati ono Lewi, ba awönia Datano ba Abiramo, iraono Geliabi andrö, ono Walu ono Rubeno.[1]', '["Yud 11","MozII 19:6"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 2, 'Lalaŵa Moze, ba 250 niha nawöra, Iraono Gizeraeli, satua mbanua, salaŵa rafe, sebua töi.', '["Yud 11","MozII 19:6"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 3, 'Möi ira falukha khö ndra Moze A''aroni, lamane khöra: Tenga inötö khömi! Ni''amoni''ö sa zato fefu, dozi ira, ba soso khöra Yehowa; ba hana wa mibali''ö salaŵa mbanua Yehowa ami?[2]', '["Yud 11","MozII 19:6"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 4, 'Ba me irongo da''ö Moze, ba ifalögu tou ia ba danö.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 5, 'Ba imane khö Gora ba ba zato andrö khönia fefu: Mahemolu i''oroma''ö Yehowa, ha niha dana khönia ba ha niha ni''amoni''ö, fa ifa''amöi khönia; somasi ia, ba ifa''amöi khönia.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 6, 'Ba mimane: Mihalö gali ba wanunu samohua, Kora ba sato andrö khönia fefu;', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 7, 'mibe''e yaŵa galitö ba milau zamohua nitunu, föna Yehowa; ba ha niha nitehe Yehowa, da''ö ni''amoni''ö taŵa''ö. Noa irege da''ö, ya''ami ono Lewi!', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 8, 'Ba imane Moze khö Gora: Mifondrondrongo, ya''ami, ono Lewi!', '["Faigi 3:6"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 9, 'Hadia, ambö na khömi, wa no i''oniagö ami ba Ndraono Gizeraeli sato, ba wama''amöi khönia ya''ami, ena''ö mihalö-halö halöŵö andrö ba nahia Yehowa, ba ena''ö möi ngoni-ngoni zato ami ba wangai-ngai halöŵö khöra?[3]', '["Faigi 3:6"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 10, 'Ba no ifa''amöi ndra''ugö, awö dalifusöu fefu, ono Lewi, ba hadia, mi''andrö na göi khömi, ena''ö latehe ere ami?', '["Faigi 3:6"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 11, 'Andrö mamagölö ami, udu Yehowa, ya''ugö ba sato andrö khöu fefu — hadia sa Ga''aroni, wa kumökö-kökö ami khönia?', '["Faigi 3:6"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 12, 'Ba ifakaoni''ö ndra Datano Abiramo, iraono Geliabi andrö, Moze; ba lamane: Lö möiga!', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 13, 'Hadia, ambö na, wa no öhetaga ba danö si falawu susu ba ŵe ŵani, wa no ö''ohega ba da''e, ba wamunu ya''aga ba danö si mate; hadia, öbali''ö salaŵama na göi ndra''ugö?', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 14, 'Noa sa öhaogö wolohe ya''aga ba danö si falawu susu ba ŵe ŵani, awö wame''e benua khöma ba kabu nagu, tana khöma. Hadia, öwai ö''ila ö''abösi''ö niha?', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 15, 'Lö möiga!', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 16, 'Ba imane Mose khö Gora: Ya''ugö ba sato andrö khöu fefu, mahemolu mi''ondrasi Yehowa — ya''ugö ba ya''ira ba A''aroni!', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 17, 'Ba dozi ami mihalö gali ba wanunu samohua khömi, milau yaŵa zamohua, ba i''ohe föna Yehowa gali khönia zamösana — 250 gali; ba ya''ugö göi ba A''aroni, ba faoma so gali khömi.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 18, 'Ba dozi lahalö gali khöra, labe''e yaŵa galitö ba lalau zamohua nitunu. Ba la''iagö golayama nose wama''ele''ö, awö ndra Moze A''aroni.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 19, 'Ba ifalukha''ö zato fefu udura Kora, ba golayama nose wama''ele''ö. Ba to''ele ba zato fefu lakhömi Yehowa.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 20, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 21, 'Mi''oniagö ami a niha andrö, ena''ö u''ozumagö uhori ira!', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 22, 'Ba lafalögu tou ira ba danö, lamane: He Lowalangi. So''aya noso ba mboto niha fefu! Hadia, na ha samösa zamazökhi horö, ba mofönu ndra''ugö ba zato fefu.[5]', '["Faigi 27:16; Heb 12:9"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 23, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 24, 'Hede ba zato, ömane khöra: Miheta ami ba zahatö ba nahia ndra Kora, Datano, Abiramo!', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 25, 'Ba maoso Moze, möi ia khö ndra Datano Abiramo, ba la''o''ö ia satua Ndraono Gizeraeli.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 26, 'Ba humede ia ba zato, imane: Mita''i-ta''i miheta ami ba nose niha sebua horö andrö, ba böi mibabaya hadia ia nibaya-bayara, fa böi tese''e ami [göi], ba horöra andrö fefu.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 27, 'Ba laheta ira ba zahatö ba nahia ndra Kora, Datano, Abiramo. Ba Datano ba Abiramo, ba no möi tou, la''iagö newali nosera, awö wo''omora, ba onora, he segebua, ba he sigide-ide.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 28, 'Ba imane Moze: Ba da''ö dania aboto ba dödömi, wa no Yehowa zamatenge ya''odo, ba wolau nilau andrö fefu, wa tenga moroi khögu manö:', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 29, 'Na si mane fa''amate niha bö''ö fefu wa''amate da''e, na ha sanörö niha bö''ö fefu itörö ira, ba no tenga Yehowa zamatenge ya''o.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 30, 'Ba na ilau Yehowa zi lö murai murongo, na ifaboka mbawania tanö ba na itölö ira, fabaya fefu zi so khöra, na numalö ba mbanua tou, auri, ba aboto ba dödömi, wa no latandraŵaisi Yehowa niha andrö.', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 31, 'Ba me no a''ozu khönia huhuo andrö, ba fabali danö barö gahera,', '["Faigi 26:10; MozV 11:6; Sin 106:17"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 32, 'ifaboka mbawania tanö, itölö ira, fabaya nosera, ba awö niha fefu, tana khö Gora, numalö nibaya-bayara.[6]', '["Faigi 26:10; MozV 11:6; Sin 106:17"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 33, 'Numalö mitou ira ba mbanua tou, auri, fabaya fefu zi so khöra, ba fahalö danö, yaŵara, tobali taya manö ira ba hunö zato.', '["Faigi 26:10; MozV 11:6; Sin 106:17"]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 34, 'Ba dozi Iraono Gizeraeli ba zi tefasui ya''ira, ba moloi ba we''ira-irara, lamane sa: ma itölö ita göi tanö!', '[]', NULL),
  (3475702, 'OT', 'Moze IV', 16, 35, 'Ba itörö alitö, si oroi Yehowa, ba i''a niha andrö, si 250, sanunu samohua andrö.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 2, 'Ŵa''ö khö Geleazari, ono Ga''aroni ere andrö, yamuhalö gali andrö ba gakhozila andrö, ba yamufazawili galitö ba zaröu ma''ifu;', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 3, 'amonita sa''ae gali zebua horö andrö, me no mate ira; niböbözi, ni''anifi''ö ba nibe''e uli naha wame''e sumange. Noa sa la''ohe föna Yehowa, ba amonita sa''ae. Ba hana na tandra sa''ae ba Ndraono Gizeraeli.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 4, 'Ba ihalö gali töla andrö Eleazari, gali ba wanunu samohua andrö, ni''ohe zakhozi andrö ba laböbözi, la''anifi''ö, uli naha wame''e sumange,', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 5, 'tandra ba Ndraono Gizeraeli, fa samösa böi möi, si tenga nga''ötö Ga''aroni, ba wanunu samohua föna Yehowa, fa böi göna ia zi no göna Gora andrö ba awönia andrö, nifa''ombakha''ögö Yehowa khönia khö Moze.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 6, 'Ba mahemolu ö, ba kumökö-kökö Ndraono Gizeraeli sato fefu khö ndra Moze A''aroni, lamane: No mibunu niha tana khö Yehowa.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 7, 'Ba me aekhu zato udu ndra Moze A''aroni, ba lafaigi nose wama''ele''ö da''ö; ba no ibalugö ia lawuo andrö, ba to''ele lakhömi Yehowa.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 8, 'Ba möi ba golayama nose wama''ele''ö ndra Moze A''aroni.[1]', '["Heb 9:4"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475703, 'OT', 'Moze IV', 17, 9, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 10, 'Miheta ami ba zato andrö, ena''ö use''egö ira, ahou zamö''i!', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 11, 'Ba lafalögu tou ira ba danö.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 12, 'Ba ihalö gali A''aroni, si mane niŵa''ö Moze, fagohi ia, isaŵa hunö zato; noa sa ibörögö famakao ba khöra; ba itunu zamohua fameta zala zato.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 13, 'Ba me so ia ba da''ö, ba gotaluara zi mate zauri, ba döhö wamakao andrö.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 14, 'Ba fa''ato zi no tekiko ba wamakao andrö, ba no 14.700; lö lai zi tekiko mege börö Gora andrö.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 15, 'Ba ifuli ia A''aroni khö Moze, ba golayama nose wama''ele''ö, ba no döhö wamakao andrö.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 16, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 17, 'Hede ba Ndraono Gizeraeli, ŵa''ö khöra, ndramu''ohe khöu zi''o, sambua mado, ba sara zi''o, si''o zalaŵara, dozi mado, 12 zi''o fefu. Ba töi zamösana, ba sura ba zi''onia,', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 18, 'ba töi Ga''aroni, ba ba zi''o mado Lewi ösura; samösa högö mado, ba sara zi''o.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 19, 'Ba ötou''ö tou ba nose wama''ele''ö, föna dawöla zura goroisa, ba ni''oro''oroma''ögu ya''odo khöu.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 20, 'Ba si''o nituyugu, ba molewiö dania, ena''ö ufadöhö wekökö-kökö Ndraono Gizeraeli khömi, fa böi [sa''ae] abua khögu.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 21, 'Ba me no i''ombakha''ö da''ö ba Ndraono Gizeraeli Moze ba labe''e khönia zi''ora salaŵara fefu, dozi mado, samösa högö, ba sara zi''o, 12 zi''o fefu; ba lafao ba zi''ora andrö zi''o Ga''aroni.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 22, 'Ba itou''ö tou zio andrö Moze, föna Yehowa, ba nose goroisa.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 23, 'Ba mahemolu ö, me möi ba nose goroisa Moze, ba no auri zi''o Ga''aroni, si''o mado Lewi andrö, no molewi''ö ba mobowo sa''ae ba mowua, bua manalu si no o''öli.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 24, 'Ba i''ohe baero ni''amoni''ö zi''o andrö fefu Moze, i''oroma''ö ba Ndraono Gizeraeli fefu, ba lafaigi, ba ihalö zi''onia zamösana.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 25, 'Ba imane Yehowa khö Moze: Fuli be''e tou zi''o Ga''aroni andrö föna zura goroisa, ena''ö te''irö''ö ia tandra-tandra ba zabe''e tandro, ba ena''ö döhö wekökö-kököra andrö, fa böi [sa''ae] abua khögu; fa böi mate ira.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 26, 'Ba i''o''ö Moze niŵa''ö Yehowa khönia; si manö wolaunia.', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 27, 'Ba lamane Iraono Gizeraeli khö Moze: Hiza, si mate ndra''aga, si tekiko ndra''aga, dozi ndra''aga, ba si tekiko!', '[]', NULL),
  (3475703, 'OT', 'Moze IV', 17, 28, 'Ha niha zi hatö''ö ya''ia ba nose Yehowa andrö, ba si mate; hadia sa, öhori manö ndra''aga?', '[]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 1, 'Ba imane Yehowa khö Ga''aroni: Ya''ugö ba iraonou andrö ba iwami zolu''i sala ba ni''amoni''ö andrö, ba he si sala halöŵö gere andrö khömi, ba ya''ugö ba iraonou zolu''i.', '["MozV 18:5"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 2, 'Ba talifusöu andrö göi, mado Lewi, iwami, ba fa''amöi, awöu, ena''ö fao ira khöu, ngoni-ngoniu, na mihalö-halö halöŵö ba golayama nose goroisa, ya''ugö ba iraonou.[1]', '["MozV 18:5"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 3, 'Ba halöŵöra nihalö-halö khöu ba hadia nihalö-halö ba nose, ma''asambua. Ba böi lahatö''ö ira ba wakake ni''amoni''ö andrö ba ba naha wame''e sumange, fa böi faoma mate ami, he ya''ira ba he ya''ami.', '["MozV 18:5"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 4, 'Ba ndrafao khöu, ndra muhalö-halö halöŵö ba nose wama''ele''ö, fefu hadia ia halöŵö ba nose; ba niha bö''ö, ba lö tola ihatö''ö ia khömi.', '["MozV 18:5"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 5, 'Ba ya''ami zangai halöŵö ba ni''amoni''ö andrö, awö halöŵö ba naha wame''e sumange, fa böi ifuli göna fönu Ndraono Gizeraeli.', '["MozV 18:5"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 6, 'Hiza, no utuyu ba Ndraono Gizeraeli nono Lewi andrö, bualagu khömi, nibe''e tana khö Yehowa, ena''ö lahalö-halö halöŵö ba nose wama''ele''ö.', '[]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 7, 'Ba ya''ugö ba iraonou andrö, ba mihalö-halö halöŵömi, halöŵö gere, hadia ia fefu ba naha wame''e sumange, ba bakha barö mba''a-ba''a andrö; mihalö-halö halöŵö. Bualagu khömi halöŵö gere andrö: ba niha bö''ö, si hatö''ö ya''ia, ba nibunu.', '[]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 8, 'Ba imane Yehowa khö Ga''aroni: Hiza, utehe khöu nibe''e yaŵa sumangegu si no amaedola wegero andrö; ba game''ela Ndraono Gizeraeli andrö ni''amoni''ö fefu utehe khöu ba ba ndraonou, tana khömi, ömö nibe''e-be''e, si lö mamalö-malö.[2]', '["MozIII 7:35"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 9, 'Ba da''ö dana khöu ba game''ela andrö ni''amoni''ö sibai — na no muhalö dana nitunu andrö —: fefu game''elara sumange ni''a ba sumange fameta horö ba sumange ogauta, nibe''era khögu, fangali [nilimo]; khöu ba ba ndraonou, ni''amoni''ö sibai.', '["MozIII 7:35"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 10, 'Ba naha ni''amoni''ö sibai ö''a ia; dozi motöi matua zi manga ya''ia: ni''amoni''ö ia öŵa''ö.', '["MozII 29:27"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 11, 'Ba da''ö zi möi khöu si hulö wegero, ba game''elara [bö''ö] andrö, ba zumange Ndraono Gizeraeli andrö nihahae: utehe khöu ba ba nonou matua ba ba nonou alawe; ömö, nibe''e, si lö mamalö-malö; dozi si lö si ra''iö moroi yomo khöu zi manga ya''ia.[3]', '["MozII 29:27"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 12, 'Fefu zi sökhi fanikha ba fefu zi sökhi agu ba fakhe, fondrege zi sökhinia, nibe''era khö Yehowa, ba no utehe khöu.', '["MozIII 27:28"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 13, 'Fefu zi a''a mbua danö khöra, nibe''era khö Yehowa, ba khöu; dozi si lö si ra''iö, moroi yomo khöu, zi manga ya''ia.', '["MozIII 27:28"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 14, 'Fefu hadia ia nilakha''ö ba Ndraono Gizeraeli, ba khöu.[4]', '["MozIII 27:28"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 15, 'Fefu zi a''a ba wa''atumbu, fefu nibe''e-be''e khö Yehowa, he niha, ba he urifö, ba khöu, ba si a''a nono niha, ba öbe''e nisanu, ba si manö göi zi a''a nono gurifö si ra''iö.[5]', '["MozII 13:2","MozII 30:13"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 16, 'Ba ba wananu ya''ia [ba nono niha], ba na sara waŵa wa''ebua, ba ma na ebua moroi andrö öbe''e nisanu, dali watö, lima sekeli (rufia) wananu, ba zaga ni''amoni''ö, si samba sekeli, ba 20 gera.[6]', '["MozII 13:2","MozII 30:13"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 17, 'Ba si a''a nono zawi ba he ono mbiri-biri ba he ono nambi, ba lö tola öbe''e nisanu: ni''amoni''ö da''ö; donia, ba öbe''e fanefe naha wame''e sumange, ba taŵönia, ba ötunu, sumange nifatörö ba galitö, nibe''e khö Yehowa, samohua.', '["MozIII 2:13; Nga''ötII 13:5"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 18, 'Ba ösira, ba khöu, si mane osu andrö, nihahae ba faha andrö kambölö, khöu ia.', '["MozIII 2:13; Nga''ötII 13:5"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 19, 'Fefu zumange si hulö wegero andrö, föfö game''ela ni''amoni''ö andrö nibe''e Ndraono Gizeraeli amaedola wegero khö Yehowa, ba khöu utehe ba ba nonou matua ba ba nonou alawe, ömö, nibe''e, si lö mamalö-malö. Amabu''ula li nilau asio da''ö, si lö tebulö, götö-götö wa''ara, khöu ba ba nga''ötöu dania.[7]', '["MozIII 2:13; Nga''ötII 13:5"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 20, 'Ba imane Yehowa khö Ga''aroni: Lö labe''e dana khöu ba danöra, lö benuau ba khöra. Ya''odo sa dana khöu ba amaedola gondröita khöu ba hunö Ndraono Gizeraeli.[8]', '["MozV 10:9"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 21, 'Ba nitehegu ba nono Lewi, ba sambua ni''ofulu ba Ndraono Gizeraeli, amaedola gondröita, ba halöŵö andrö, nihalö-halöra, halöŵö ba nose wama''ele''ö.', '["MozV 10:9"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 22, 'Ba Iraono Gizeraeli, ba lö tola sa''ae lahatö''ö ira ba nose wama''ele''ö, fa böi lahalö horöra ba fa böi mate ira.', '["Yos 13:14"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 23, 'Ono Lewi zangai-ngai halöŵö ba nose wama''ele''ö, ba ya''ira zolu''i sala danö bö''ö, dali nifakhoi andrö khömi, si lö tebulö, götö-götö wa''ara; ba tana khöra tanö, ba lö labe''e khöra ba Ndraono Gizeraeli.[9]', '["Yos 13:14"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 24, 'Me utehe ba nono Lewi zi sambua ni''ofulu andrö ba Ndraono Gizeraeli nibe''era khö Yehowa sumange si no amaedola wegero, ube''e amaedola gondröita khöra; andrö wa no ufakhoi ba khöra andrö, wa lö labe''e khöra dana khöra tanö ba Ndraono Gizeraeli.', '[]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 25, 'Ba humede Yehowa khö Moze, imane:', '["Neh 10:38"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 26, 'Ŵa''ö ba nono Lewi, ömane khöra: Na mitema ba Ndraono Gizeraeli zi sambua ni''ofulu andrö, nitehegu khömi tana khömi ba khöra andrö, ba mibe''e ösa sumange si no amaedola wegero, khö Yehowa, sambua ni''ofulu zi sambua ni''ofulu andrö.[10]', '["Neh 10:38"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 27, 'Ba lafotöi khömi zumange fegero andrö khömi, amaedola wakhe ba golayama mbasitö ba amaedola zi töra ba wolazi nagu.', '["Neh 10:38"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 28, 'Ba si manö ba ni''ofulu andrö fefu, sinemami, nitemami ba Ndraono Gizeraeli, mibe''e ösa, sumange fegero khö Yehowa; ba sumange fegero andrö föfönia, nihonogöi khö Yehowa, ba ba danga Ga''aroni ere mibe''e.', '["Neh 10:38"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 29, 'Fefu game''ela, si möi khömi, ba lö tebulö mibe''e ösa sumange fegero khö Yehowa, fefu zi sökhinia mibe''e ösa, amakhoita. Ame''ela ni''amoni''ö, föfönia.', '["Neh 10:38"]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 30, 'Ömane khöra: Na mimanö, wame''e si sökhinia, ba tefotöi ba nono Lewi, amaedola nösi golayama mbasitö ba amaedola nösi wolazi nagu.', '[]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 31, 'Fefu gofu heza, ba tola mi''a, ya''ami ba soroiyomomi fefu, me no luomi ba halöŵömi ba nose wama''ele''ö.', '[]', NULL),
  (3475704, 'OT', 'Moze IV', 18, 32, 'Ba lö tohare khömi horö ba da''ö, asala mibe''e zi sökhinia, ba da''ö, asala mibe''e zi sökhinia, ba lö''ö sa mifatörö zalakha ba game''ela Ndraono Gizeraeli andrö, ni''amoni''ö, ba lö mate ami.', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 1, 'Ba humede Yehowa khö ndra Moze A''aroni, imane:', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 2, 'Da''ö gamakhoita, nifakhoi Yehowa, me imane:', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 3, 'Ba mibe''e ba danga Geleazari ere andrö; ba la''ohe baero, föna golombaseŵa, ba lataba ba zanehe ia.[1]', '["Heb 13:11","MozII 29:14","MozIII 14:6"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 4, 'Ba ihalö ndronia ma''ifu Eleazari ere andrö, turunia, ba mewitu itefe do andrö ösa gamaudu mbawa duasa nose wama''ele''ö.', '["Heb 13:11","MozII 29:14","MozIII 14:6"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 5, 'Aefa da''ö, ba latunu zawi andrö ba zanehe ia; ulinia ba ösinia ba donia, ba nitunu, fabaya tainia.[2]', '["Heb 13:11","MozII 29:14","MozIII 14:6"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 6, 'Ba ihalö geu eresi ere ba sufa ba kirimisi, ba itibo''ö ba galitö fanunu zawi andrö.[3]', '["Heb 13:11","MozII 29:14","MozIII 14:6"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 7, 'Aefa da''ö, ba ibabago nukhania ere ba mondri. Awena tola ifuli ia ba golombaseŵa; ba si ra''iö na gere, irege bongi.', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 8, 'Ba sanunu ya''ia [sawi andrö] göi, ba ibabago nukhania ba mondri ba si ra''iö ia, irege bongi.', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 9, 'Ba si lö si ra''iö zangozaragö awu zawi andrö, ba itou''ö tou ba naha si sökhi, baero, föna golombaseŵa, ena''ö te''irö''ö soguna ba Ndraono Gizeraeli sato, nifaruka ba nidanö fangehao; sumange fameta horö ia.[4]', '["Heb 9:13"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 10, 'Ba sangozaragö awu zawi andrö, ba ibabago nukhania ba si ra''iö ia irege bongi.', '["Heb 9:13"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 11, 'Ha niha zombambaya si mate, hadia ia mboto niha si no mate, ba fitu bongi ra''iö ia.', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 12, 'Da''ö zame''e fameta zalania ya''ia [idanö no mege], na luo si tölu ba na luo si fitu, ba abeta wa''ara''iönia. Ba na lö iheta zalania, na luo si tölu ba na luo si fitu, ba dörö-döro ra''iö ia.', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 13, 'Ha niha zombamba-mbaya si mate, boto niha si no mate, ba lö iheta zalania, ba ra''iö nose Yehowa ibe''e, ba nise''e ba Ndraono Gizeraeli niha si manö; me lö mutefe ia idanö fangehao, ba si ra''i-ra''iö ia; falemba khönia wa''ara''iönia, si lö mamalö-malö.', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 14, 'Ba da''ö gamakhoita, na so zi mate baose: Dozi si möi baose andrö ba dozi si tohöna bakha, ba fitu bongi wa''ara ra''iö.', '["Sin 51:9"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 15, 'Ba fefu nahia, si lö lagö-lagö, lagö-lagö niböbö sinali, ba ra''iö.', '["Sin 51:9"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 16, 'Si manö göi dozi si fabaya ba nibunu baero ba mbenua ba ma ba zi mate ba da''ö ba ma ba döla zi mate ba ma ba lewatö, ba fitu bongi wa''ara ra''iö.', '["Sin 51:9"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 17, 'Ba ba zi no ra''iö si manö ba ndramuhalö nawu zumange fameta horö andrö, si no mutunu, labe''e ba nahia ba lalau yaŵa nidanö gumbu.', '["Sin 51:9"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 18, 'Ba si lö fa''ara''iö zangai sufa, i''ungugö ba nidanö andrö ba itefe nose andrö, awö gama-gama fefu, awö niha, si so baose, awö zi no fabaya ba döla zi mate ba ma ba nibunu, ba ma ba zi mate manö ba ma ba lewatö.[5]', '["Sin 51:9"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 19, 'Na luo si tölu ba na luo si fitu itefe zi ra''iö si lö fa''ara''iö, ba aheta zalania ibe''e, na luo si fitu andrö. Ba ibabago nukhania ba mondri, ba aheta wa''ara''iönia na bongi.', '["Sin 51:9"]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 20, 'Ba na so zi ra''iö ba lö iheta zalania, ba nise''e ba zato zi manö; noa sa ra''iö ni''amoni''ö andrö khö Yehowa ibe''e: lö mutefe ia idanö fangehao, andrö wa si ra''iö ia.', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 21, 'Amakhoita si lö tebulö khömi da''ö, nitörö, götö-götö wa''ara. Ba sanefe idanö fangehao andrö, ba ibabago nukhania, ba sombambaya idanö fangehao, ba ra''iö, irege bongi.', '[]', NULL),
  (3475705, 'OT', 'Moze IV', 19, 22, 'Ba fefu hadia ia, nibabaya zi nora''iö andrö, ba ra''iö, ba si manö göi dozi sombambaya ya''ia, bara''iö, irege bongi.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 1, 'Ba larugi danö si mate Sini Iraono Gizeraeli fefu, ba ba Gadesi tebato ira; ba mate ba da''ö Miriya ba lako''o ia ba da''ö.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 2, 'Ba lö ö zato idanö. Ba aekhu ira khö ndra Moze A''aroni,[1]', '["MozII 17:3"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 3, 'fasoso zato khö Moze, lamane: Ena''ö na tekiko mege ndra''aga göi, me tekiko dalifusöma föna Yehowa!', '["MozII 17:3"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 4, 'Hana wa ö''ohe ba danö si mate mbanua Yehowa, ena''ö mate ba da''e ndra''aga, awö guriföma!', '["MozII 17:3"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 5, 'Hana wa no öheta ndra''aga ba danö Miserayi, ba wolohe ya''aga ba danö andre, si lö sökhi, ba zi tebai monowi ita, ba zi lö bua ara ba he agu ba he dalimo ba ba zi lö öma idanö!', '["MozII 17:3"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 6, 'Ba laröi zato ira Moze A''aroni, möi ira ba zinga mbawandruhö nose wama''ele''ö ba lafalögu tou ira ba danö; ba to''ele khöra lakhömi Yehowa.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 7, 'Ba humede Yehowa khö moze, imane: Halö zi''o, owuloi niha sato, darua ami, ga''au A''aroni ba mihede ba gara andrö, ba zanehe ira, ba alua khönia nidanö.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 8, 'Falua ba gara andrö göra idanö, asogö nibadu niha sato, awö guriföra!', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 9, 'Ba ihalö zi''o Mose, ba ni''amoni''ö, i''o''ö niŵa''ö Yehowa khönia.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 10, 'Ba la''owuloi zato ira Moze A''aroni, föna gara andrö, ba imane khöra: Mifondrondrongo, ya''ami sabe''e tandro! Hadia ma''ila maö mafalua ba gara andre gömi idanö?', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 11, 'Ba ifazaŵa dangania Moze, ibözi gara andrö si''onia, mendrua. Ba abölö nidanö salua khönia, tobali labadu niha sato ba uriföra.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 12, 'Ba imane Yehowa khö ndra Moze A''aroni: Me no aombö dödömi khögu, me no lö nifosumangemi ya''odo, ya''odo, ni''amoni''ö andre, ba zanehe Ndraono Gizeraeli, ba böi ya''ami zolohe niha andre ba danö andrö nibe''egu khöra.[2]', '["Faigi 27:14; MozV 1:37; 32:51"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 13, 'Da''ö nidanö wasosota andrö: si fasoso Ndraono Gizeraeli khö Yehowa, ni''oroma''önia khöra lakhöminia.[3]', '["Sin 81:8; 106:32"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 14, 'Ba i''otarai Gadesi ifatenge zinenge Moze khö razo Ndraono Gedomo, imane: Da''ö niŵa''ö nakhiu Izeraeli: No örongo wamakao andrö fefu, si no göna ndra''aga,', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 15, 'wa no möi ba danö Miserayi ndra tuama, awö wa no ara ndra''aga ba danö Miserayi, awö wa no lafakao sibai ndra''aga Dawa Miserayi, ba he ira tuama mege sa''ae.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 16, 'Ba no ma''angaröfi li Yehowa ba no ifondrondrongo wakaosama andrö, ba no ifatenge mala''ika; da''ö zangeheta ya''aga ba danö Miserayi. Ba ba da''e, ba Gadesi andre soga ma''ökhö, ba mbanua ba nola danöu.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 17, 'Damatörö danöu! Lö matörö nowi ba lö matörö kabu nagu, ba lö mabadu nidanö ba mba''a; lala sebua ma''osisi, lö mahole''ö ndra''aga, he ba gambölö, ba he ba gabera, irege no aefaga ba danöu.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 18, 'Ba imane razo Ndraono Gedomo: Lö tola ötörö danögu, fa böi fasuwö ndra''o khöu.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 19, 'Ba lamane khönia Iraono Gizeraeli: Lala sebua ma''osisi, ba na mabadu göu idanö, ya''aga ba uriföma, ba mabe''e mböli; ha fa matörö manö!', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 20, 'Ba imane: Lö tola ötörö!', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 21, 'Tobali lö latehe Iraono Gedomo latörö danöra Iraono Gizeraeli; ba laböhöli ira Iraono Gizeraeli, lahole''ö ira.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 22, 'Ba lafazaŵa ira ba Gadesi andrö ba lasaŵa hili Hori Iraono Gizeraeli fefu.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 23, 'Ba imane Yehowa khö ndra Moze A''aroni, ba da''ö, ba gahe hili Hori ba nola danö Ndraono Gedomo:', '["Faigi 33:38; MozV 32:50"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 24, 'A''aroni, ba ni''orudugö sa''ae khö ndra amami; lö''ö sa tola ihundragö danö andrö, nibe''egu ba Ndraono Gizeraeli, me no lö nifondrondrongomi niŵa''ögu, ba nidanö wasosota no.', '["Faigi 33:38; MozV 32:50"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 25, 'Halö Ga''aroni ba ononia Eleazari, ba ohe miyaŵa ira ba hili Hori,[4]', '["Faigi 33:38; MozV 32:50"]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 26, 'heta nukha Ga''aroni ba be''e nukha nononia Eleazari; ba A''aroni, ba ni''orudugö [khö ndra amami]; mate dania ia ba da''ö.', '["Faigi 33:38; MozV 32:50"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475706, 'OT', 'Moze IV', 20, 27, 'Ba i''o''ö Moze niŵa''ö Yehowa khönia, möi ira miyaŵa ba hili Hori ba zanehe zato fefu.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 28, 'Ba iheta nukha Ga''aroni Moze, ibe''e nukha nononia Eleazari.', '[]', NULL),
  (3475706, 'OT', 'Moze IV', 20, 29, 'Ba me la''ila sato fefu, no mate Ga''aroni, ba la''e''esi ia Iraono Gizeraeli fefu, tölu ngafulu wongi wa''ara.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 1, 'Ba me irongo Dawa Gana''ana andrö, razo Garadi, ba danö tanö raya, so moroi sa ba Gatari Ndraono Gizeraeli, ba itema fasuwö khöra ba ira''u ösa.[1]', '["Faigi 33:40"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 2, 'Ba lafabu''u lira khö Yehowa Iraono Gizeraeli, lamane: Na öbe''e ba dangama niha andrö, ba malakha''ö mbanuara.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 3, 'Ba i''o''ö wangandrö Ndraono Gizeraeli Yehowa, ibe''e ba dangara Ndrawa Gana''ana andrö; ba lalakha''ö ira, awö mbanuara. Ba tebe''e töi mbanua andrö Horema.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 4, 'Ba laheta ira ba hili Hori, latörö lala ba nasi zukhu, ba wamahene tanö Ndraono Gedomo. Ba ba lala andrö ba lö sökhi-sökhi dödö zato.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 5, 'Latahigö Lowalangi ba he Moze, lamane: Hadia, andrö mihetaga ba danö Miserayi, ena''ö tekiko ndra''aga ba danö si mate? Lö''ö sa öma kue ba lö öma idanö ba anuzu dödöma gö si lö sökhi andrö.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 6, 'Ba ifatörö khöra gulö sosöfu Yehowa, sondrou niha, tobali ato zi mate Iraono Gizeraeli.[2]', '["KorI 10:9"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 7, 'Ba möi ira khö Moze, lamane: Horöma mege, me matahigö Yehowa, awö ndra''ugö; angandrö khö Yehowa, salahimö, ena''ö iheta khöma gulö andrö!', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 8, 'Ba imane Yehowa khö Moze: Fazökhi wamaedo gulö sosöfu ba tuwu yaŵa, ba na so nidou, ba na ifaigi da''ö, ba auri ia.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 9, 'Ba ifazökhi gulö töla Moze, ba ituwu yaŵa; ba na ladou niha ulö andrö ba na ifaigi gulö töla andrö, ba auri ia.[3]', '["RazII 18:4; Yoh 3:14"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 10, 'Ba lafazaŵa ira Iraono Gizeraeli, mofanö, ba ba Goboto tebato dania.', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 11, 'Ba laheta ira ba Goboto ba ba Iye Ha''abari molombase, ba danö si mate, tanö ba gatumbukha luo, i''otarai danö Ndraono Moabi.', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 12, 'Ba mofanö ira ba da''ö, ba molombase ba ndraso Zaredi.', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 13, 'Ba mofanö ba da''ö, ba yefo Garono ba danö si mate, molombase; Arono so''ulu ba danö Ndraono Gamori. Ola Ndraono Moabi Garono andrö, tanö ba Ndraono Gamori.[4]', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 14, 'Andrö wa si mane ba zura wanuwö Yehowa: "Wahebi ba Zufa, awö ndraso andrö, Arono andrö, ba sanösö andrö,', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 15, 'ba ngai ndraso, irugi tanö ba Ari, si faola ba danö Ndraono Moabi."', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 16, 'Ba moroi ba da''ö lasaŵa Mbe''eri; da''ö gumbu andrö, niŵa''ö Yehowa, me imane khö Moze; Owuloi niha sato, ena''ö ube''e göra idanö!', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 17, 'Me luo da''ö, ba lamanö wanunö Iraono Gizeraeli: "Angumbu, ya''ugö umbu! Mi''anunö khönia!', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 18, 'Ba''a nikharu zalaŵa, nikhao zebua töi ba zato, nikharu si''o zalaŵa, nikharu si''ora!" Ba moroi ba danö si mate andrö, ba lasaŵa Matana; ba i''otarai Matana,', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 19, 'ba numalö ba Nahalieli, ba moroi ba Nahalieli, ba lasaŵa Mbamoti;', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 20, 'ba i''otarai Mbamoti ba numalö ba zalo''o andrö ba danö Ndraono Moabi, lafaudugö zuzu hili Wisiga, fetahö danö si mate.', '["Sanguhuk 11:18"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 21, 'Ba lafatenge zinenge khö Zihona, razo Ndraono Gamori, Iraono Gizeraeli, lamane khönia;[5]', '["MozV 2:26"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 22, 'Damatörö danöu; nowi ba kabu nagu, ba lö mahundragö, ba idanö ba mba''a, ba lö mabadu; lala sebua matörö, irege aefaga ba danöu.', '["MozV 2:26"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 23, 'Ba lö itehe ba Ndraono Gizeraeli Sihona latörö danönia, itema i''owuloi zabölö khönia, ba ifaondragö Ndraono Gizeraeli ba danö si mate, ba me no irugi Yahasi, ba ilau fasuwö khöra.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 24, 'Ba te''ala ia ba mbawa zi''öli labe''e Iraono Gizeraeli ba lahalö khöra danönia, i''otarai Garono, numalö ba Yaboko, irege nola Ndraono Gamoni; ola Ndraono Gamoni andrö, ba noa sa mu''aro''ö.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 25, 'Ba atu''a ba mbanua ba da''ö fefu Ndraono Gizeraeli, labali''ö banuara mbanua Ndraono Gamori fefu, Hesibona andrö, fabaya banua side-ide, si faböbö khöra, fefu.[6]', '["Yos 24:8; Sin 136:19"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 26, 'Hesibona andrö, ba banua razo Ndraono Gamori, Sihona andrö; noa sa isuwö razo Ndraono Moabi föna da''ö, ba no ihalö khönia danönia fefu, irugi ba mbewe Garono.', '["Yer 48:45","RazI 11:17"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 27, 'Andrö wa lamane sanunö: "Mitabu ba Hesibona, nitaru''ö ba ni''aro''ö mbanua Zihona andrö!', '["Yer 48:45","RazI 11:17"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 28, 'Noa sa i''otarai alitö Hesibona, hola-hola galitö i''otarai mbanua Zihona; da''ö zi manga Ari Moabi, ba ösi mbanua ba hili-hili ba mbewe Garono.[7]', '["Yer 48:45","RazI 11:17"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 29, 'Alai ndra''o ndra''ugö, Moabi! Si tekiko ami, ya''ami, banua Khamosi andrö! Tobali soloi nononia matua, ba nira''u Zihona, razo Ndraono Gamori, nononia alawe ibe''e.[8]', '["Yer 48:45","RazI 11:17"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 30, 'No ma''efasi wana khöra, ba si lö boto sa''ae Hesibona, numalö ba Dibona; no adudu mbanua mabe''e, irege Nofa; alitö malau, irugi Medeba."', '["Yer 48:45","RazI 11:17"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 31, 'Ba aro sa''ae Ndraono Gizeraeli ba danö Ndraono Gamori.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 32, 'Ba ifatenge zamauze Moze ba Ya''ezeri ba atu''a ira ba mbanua, fabaya ba halama soya khöra. Tobali latimba Ndraono Gamori sowanua ba da''ö.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 33, 'Ba lafuli ira furi ba latörö lala ba Mbazana. Ba ifaondragö ira Ogi, razo Mbazana, i''ohe zabölö khönia fefu, möi fasuwö khöra.[9]', '["MozV 3:1"]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 34, 'Ba imane Yehowa khö Moze: Böi ata''ufi ia, ube''e sa ba dangau ia, fabaya banuania fefu, ba tanönia, ba hana na ölau khönia nilaumö khö Zihona no, ba Hesibona.', '[]', NULL),
  (3475707, 'OT', 'Moze IV', 21, 35, 'Ba te''ala ia labe''e, fabaya ononia ba sabölö khönia fefu, tobali samösa lö lasaigö khönia, soloi ena''ö, ba lahalö khöra danönia.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 1, 'Aefa da''ö, ba latohugö wofanö Iraono Gizeraeli ba molombase dania ba zalo''o, ba danö Ndraono Moabi, yefo Yoridano, ba gamaudu Yerikho.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 2, 'Ba i''ila Balaki, ono Zifori andrö, fefu nilau Ndraono Gizeraeli ba Ndraono Gamori.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 3, 'Ba ata''u sibai Ndraono Mo''abi Ndraono Gizeraeli; ato sibai sa ira, ba humokha mbu Ndraono Moabi Ndraono Gizeraeli andrö.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 4, 'Ba lamane Iraono Moabi ba zalaŵa Ndraono Midiano: Ba ni''ilada ma''ökhö, ba la''a manö fefu zi tefasui ya''ita niha sato sibai andrö, si mane sawi si matua, na la''a ndru''u ba mbenua.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 5, 'Ba ifatenge zinenge khö Mbileamo, ono Mbeori, ba Wetori, ba mbewe Oiferati, ba danö niwara, ba wogaoni ya''ia, imane khönia: So niha, saheta ba danö Miserayi; no lahawui danö, ha wa''ebolo, ba iada''e, ba molombase ba gamaudugu.[1]', '["Yos 24:9"]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 6, 'Ba aine ba elifi khögu niha andrö, me tebai ulaŵa; ma atö u''ila dania u''alani ira ba utimba ba danögu. U''ila sa: nifahowu''ömö, ba dörö-dörö nifahowu''ö ba ni''elifimö, ba dörö-dörö ni''elifi!', '["Yos 24:9"]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 7, 'Ba mangefa zatua Ndraono Moabi ba satua Ndraono Midiano, la''ohe luo waetasa, ba larugi Mbileamo, ba lafa''ema khönia niŵa''ö Mbalaki.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 8, 'Ba imane khöra: Miförö, ba uŵa''ö li khömi, balazi hadia niŵa''ö Yehowa khögu.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 9, 'Ba möi Lowalangi khö Mbileamo, imane khönia: Ha niha domeu andrö?', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 10, 'Ba itema li Lowalangi Bileamo, imane: Balaki andrö, ono Zifori, razo Ndraono Moabi, no ifatenge zinenge khögu, imane:', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 11, 'Hiza niha, saheta ba danö Miserayi, no lahawui danö ha wa''ebolo, ba aine, ba elifi ira khögu ma ato abe''e ndra''o usuwö ira ba utimba.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 12, 'Ba imane Lowalangi khö Mbileamo: Lö tola möi''ö awöra, lö tola ö''elifi niha andrö, me no nifahowu''ö.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 13, 'Ba me moluo ba iŵa''ö li Bileamo ba zatua andrö khö Mbalaki, imane: Mifuli manö ami ba khömi; lö''ö sa itehe khögu Yehowa, möido awömi.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 14, 'Ba lafazaŵa ira satua Ndraono Moabi ba larugi Mbalaki ba lamane: Lö edöna Mbileamo möi awöma.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 15, 'Ba ifuli ifatenge zinenge Balaki, sato ba salaŵa, sebua moroi ba da''ö no mege.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 16, 'Ba me larugi Mbileamo da''ö, ba lamane khönia: Da''ö niŵa''ö Mbalaki, ono Zifori: Böi ŵa''ö lö möi''ö khögu!', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 17, 'Ebua sibai luou ube''e, ba fefu hadia ia niŵa''öu khögu, ba u''o''ö; ba ae elifi khögu niha andrö!', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 18, 'Ba imane Bileamo ba mbanua Mbalaki andrö: Ba he afönu nomonia firö ba ana''a ibe''e khögu Balaki, ba tebai sa atö ufadaö niŵa''ö Lowalangigu Yehowa, he ba huhuo side-ide, ba he ba huhuo sebua.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 19, 'Ba miförö göi ba da''e, bongi, ena''ö urongo, hadia niŵa''ö Yehowa iada''e.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 20, 'Ba ba zi bongi, ba möi Lowalangi khö Mbileamo, imane khönia: Na ba wogaoni ya''ugö möi niha andrö, ba faoso, ba ae awöra, ba böi lau zi tenga niŵa''ögu khöu.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 21, 'Ba ihulö wongi ifosela galidenia Bileamo, möi ia awö zalaŵa draono Moabi andrö.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 22, 'Ba mofönu Lowalangi, börö we''amöinia andrö; ba iagö lalania mala''ika Yehowa ba wanenaŵa ya''ia; no fakudo ia ba hulu galidenia ba fao khönia zawuyunia, darua.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 23, 'Ba me i''ila kalidenia, no so ba lala mala''ika Yehowa ba sara wöda ba dangania, si no isöbi, ba ihole''ö ia ba zinga lala, itörö mbenua.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 24, 'Ba i''agö zise-ise lala mala''ika Yehowa, ba gotalua kabu nagu, ba zi so öli, faoma fatambai.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 25, 'Ba me i''ila mala''ika Yehowa kalide, ba ifadege ia ba göli, ilazi gahe Mbileamo ba göli; ba ifuli ibözi ia.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 26, 'Ba ifuli mowaö-waö mala''ika Yehowa ba i''agö zise-ise sibai, si lö lala wangohole''ö, he ba gambölö ba he ba gabera.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 27, 'Ba me i''ila mala''ika Yehowa kalide, ba ibalöduhini tou danö, barö Mbileamo.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 28, 'Ba ifehede galide Yehowa; ba imane khö Mbileamo: Hadia horögu khöu, wa öbözi-bözido, no medölu sa''ae?[2]', '["FetII 2:16; Yud 11"]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 29, 'Imane Bileamo khö galide: Me no ö''o''aya ndra''odo! Ena''ö na so khögu zi''öli, ba noa sa''ae ubunu''ö!', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 30, 'Ba imane kalide khö Mbileamo: Hadia, tenga sa kalideu ndra''o, si fakudo ndra''ugö ba hulu, sagötö fa''ara, irege ma''ökhö andre? Hadia, no irai amuatagu, ulau khöu zi manö?', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 31, 'Ba ibokai hörö Mbileamo Yehowa, ba i''ila mala''ika Yehowa, si so ba lala, sara wöda nidöni ba dangania. Ba ifaondrö ia, ba ifalögu tou ia ba danö.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 32, 'Ba imane khönia mala''ika Yehowa: Hana wa öbözi-bözi galide andrö khöu, no medölu sa''ae? Ya''odo a''i zomba''a lala khöu, me no lala si lö sökhi wamaigigu.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 33, 'Ba kalide andrö, ba no i''ilado, ba no medölu ihole''ö ia khögu; na lö ihole''ö ia mena''ö, ba mege sa''ae ubunu ndra''ugö, ba ya''ia, ba u''orifi mena''ö.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 34, 'Ba imane Bileamo khö mala''ika Yehowa andrö: Horögu da''ö, lö''ö sa u''ila, wa ya''ugö zomba''a lala khögu; ba na fatuwu khöu, ba ufulido.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 35, 'Ba itema li Mbileamo mala''ika Yehowa, imane. Ae manö awö niha andrö; ba böi ŵa''ö hadia zi tenga niŵa''ögu khöu! Ba fao Mbileamo ba zalaŵa andrö khö Mbalaki.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 36, 'Ba me irongo Balaki, no so ba lala Mbileamo, ba ifaondragö ia, irege Iri Moabi ba mbewe Garono, ba wondrege nola danö.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 37, 'Ba imane Balaki khö Mbileamo: Hadia, tenga no mato mendrua ufatenge zinenge khöu, ba wogaoni ya''ugö? Hadia mbörö, wa lö möi''ö khögu? Hadia, tebai ufosumange ndra''ugö!', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 38, 'Ba imane Bileamo khö Mbalaki: Ba no sodo ae. Ba hadia, tola maö uŵa''ö hadia ia? Taroma li nibe''e Lowalangi ba mbewegu, da''ö niŵa''ögu dania!', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 39, 'Ba fao Mbileamo khö Mbalaki, ba larugi Giriati Khusoti.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 40, 'Ba ibe''e sumange Lowalangi zawi ba biri-biri Balaki, ba ifa''ohe''ö [wöfö] ö Mbileamo ba ö zalaŵa andrö, awönia fao.', '[]', NULL),
  (3475709, 'OT', 'Moze IV', 22, 41, 'Ba mahemolu ö, ba ihulö wongi Balaki wolohe Bileamo, ifasao miyaŵa ba Mbamoti Mba''ali; ba da''ö oroma khönia Ndraono Gizeraeli ösa.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 1, 'Ba imane Bileamo khö Mbalaki: Ŵa''ö wama''anö naha wame''e sumange ba da''e, fitu, ba fitu hönagö khögu ba da''e ono zawi si matua ba fitu mbiri-biri si matua.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 2, 'Ba i''o''ö Balaki niŵa''ö Mbileamo, ba labe''e zumange Balaki ba Bileamo, sambu-sambua naha wame''e sumange, ba sara-sara nono zawi ba sage-sageu mbiri-biri si matua.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 3, 'Ba imane Bileamo khö Mbalaki: Iagö da''e, ba ngai zumange nitunu; mofanö ndra''o, tabe''e ifa''ele''ö ia khögu Yehowa, ba hadia ni''oroma''önia khögu, ba u''ombakha''ö khöu.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 4, 'Ba i''oroma''ö ia Lowalangi khö Mbileamo, ba imane khönia da''ö: Naha wame''e sumange andrö, si fitu, ba no ufa''anö, ba sambu-sambua naha wame''e sumange, ba no sara-sara nono zawi ba sage-sageu mbiri-biri si matua ube''e sumange.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 5, 'Ba ibe''e ba mbewe Mbileamo daroma li Yehowa, imane khönia: Fuli''ö khö Mbalaki, ba ömanö khönia.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 6, 'Ba ifuli ia khönia; ba lö si tebulö ia ba ngai zumange andrö khönia, ba awönia zatua Ndraono Moabi fefu.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 7, 'Ba iŵa''ö niŵa''önia andrö, imane: "Moroi ba Garamo ifahalö''ö ndra''o Balaki, moroi ba hili tanö ba gatumbukha luo ifakaoni''ö ndra''o razo Ndraono Moabi: ''Ae elifi khögu ma''uwu Yakobo, ae lakha''ö khögu Ndraono Gizeraeli!''', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 8, 'He uwisa wangelifi si tenga ni''elifi Lowalangi, ba he uwisa wolakha''ö si tenga nilakha''ö Yehowa?', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 9, 'Moroi ba zokara hili sa u''ila ira, moroi ba zalaŵa tanö oroma ira khögu. Soi si no tonia nahia, si lö mamadoro ya''ia ba ngenoli niha baero.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 10, 'Ha niha zangila mangerai ngawua gawu andrö khö Yakobo, ba ha niha zangila mama''oli liwu Ndraono Gizeraeli? Ena''ö na fa''amate zatulö tödö wa''amategu dania, ba ena''ö na fa''aetu nosora wa''aetu nosogu!"', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 11, 'Ba imane Balaki khö Mbileamo: Hadia nilaumö andrö khögu! Ba wangelifi emaligu ufa''aso ndra''ugö; ba hiza, ba no öfahowu''ö!', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 12, 'Ba imane: Hadia, tenga ha sambalö nibe''e Yehowa ba mbewegu uŵa''ö?', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 13, 'Ba imane khönia Balaki: Tabu ba nahia bö''ö, soroma ira khöu — ba ha balöra öila, lö ahori ö''ila ira — ba ba da''ö elifi ira khögu.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 14, 'Ba i''ohe ia ba mbenua Zofimi ba zuzu hili Wisiga, ba fitu ifa''anö naha wame''e sumange, ba sambu-sambua naha wame''e sumange, ba sara-sara nono zawi ba sage-sageu mbiri-biri si matua ibe''e sumange.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 15, 'Ba imane Bileamo khö Mbalaki: Base''ö ba da''e, ba ngai zumange nitunu, da''ufaondragö Lowalangi ba da''ö.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 16, 'Ba ifa''ele''ö ia Yehowa khö Mbileamo, ibe''e ba mbewenia daroma li, ba imane khönia: Fuli''ö khö Mbalaki ba ömanö khönia.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 17, 'Ba irugi Mbalaki; ba lö si tebulö ia ba ngai zumange andrö khönia, ba awönia zatua Ndraono Moabi.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 18, 'Ba iŵa''ö niŵa''önia, imane: "Lau, ya''ugö Balaki, fondrondrongo! Be''e mbörö dalingau khögu, ya''ugö, ono Zifori!', '["SamI 15:29; Yak 1:17","Yer 50:20","MozI 49:9"]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 19, 'Tenga niha Lowalangi, fa ifuli linia, ba tenga ono niha, fa mangesa dödönia ba ngawalö hadia ia. Hadia, iŵa''ö hadia ia, ba lö itörö.[1]', '["SamI 15:29; Yak 1:17","Yer 50:20","MozI 49:9"]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 20, 'Famahowu''ö niŵa''ö khögu, ba da mamahowu ndra''o ba lö ufuli ligu!', '["SamI 15:29; Yak 1:17","Yer 50:20","MozI 49:9"]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 21, 'Famakao, ba lö ta''ila ba ma''uwu Yakobo, ba fa''abu dödö, ba lö falukha ba Ndraono Gizeraeli; itolo ira Lowalangira Yehowa, ba fa''owua-wua dödö zalaŵa tarongo ba khöra.[2]', '["SamI 15:29; Yak 1:17","Yer 50:20","MozI 49:9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475710, 'OT', 'Moze IV', 23, 22, 'No iheta ira ba danö Miserayi Lowalangi; no fa''abölö göröbao wa''abölöra.', '["SamI 15:29; Yak 1:17","Yer 50:20","MozI 49:9"]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 23, 'Lö fakhai wanaka ba ma''uwu Yakobo, ba lö molemba gelemu ba Ndraono Gizeraeli. Awai niŵa''öda ma''ökhö, ba khö ma''uwu Yakobo, ba khö Ndraono Gizeraeli andrö: Wa''ebua nilau Lowalangi!', '["SamI 15:29; Yak 1:17","Yer 50:20","MozI 49:9"]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 24, 'Famazaŵa zingo si alawe ya''ia wamazaŵara ya''ira, ba femaoso zingo si matua wemaosora; lö mörö ira, na lö mu''a gahulua ua, na lö mubadu ndro nibunu!"[3]', '["SamI 15:29; Yak 1:17","Yer 50:20","MozI 49:9"]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 25, 'Ba imane Balaki khö Mbileamo: Böi elifi ira ba böi fahowu''ö.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 26, 'Itema li Mbalaki Bileamo, imane khönia: Tenga no uŵa''ö khöu: Fefu hadia ia niŵa''ö Yehowa, da''ö ulau.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 27, 'Ba imane Balaki khö Mbileamo: Tabu, da''u''ohe ndra''ugö ba nahia bö''ö, ma itehe Lowalangi, ba da''ö ö''elifi ira khögu.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 28, 'Ba i''ohe ba zuzu hili Weoro Mbileamo Balaki, hili si otahögö tanö si mate.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 29, 'Ba imane Bileamo khö Mbalaki: Ŵa''ö wama''anö naha wame''e sumange khögu, fitu, ba fitu rozi hönagö khögu ba da''e ono zawi ba fitu nga''eu biri-biri si matua.', '[]', NULL),
  (3475710, 'OT', 'Moze IV', 23, 30, 'Ba i''o''ö Balaki niŵa''ö Mbileamo; ba sambu-sambua naha wame''e ba sara-sara nono zawi ba sage-sageu mbiri-biri si matua ibe''e sumange.', '[]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 1, 'Ba me i''ila Bileamo, omasi Yehowa, tefahowu''ö Ndraono Gizeraeli, ba lö i''alui wama''ele''ö si mane ba zi mendrua mege, itema i''otahögö danö si mate.', '[]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 2, 'Ba me ifakhölö ia, ba me i''ila Ndraono Gizeraeli solombase ba da''ö, sambu-sambua mado ba sambu-sambua nahia, ba so khönia Geheha Lowalangi.', '[]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 3, 'Ba iŵa''ö niŵa''önia, imane: "Da''e niŵa''ö Mbileamo andre, ono Mbeori; da''e niŵa''ö niha andrö, si no teboka hörö.', '["SamI 15:8","MozI 12:3"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 4, 'Da''e niŵa''ö zamondrongo fehede Lowalangi, sanehe angilata khö Zi lö ambö fa''abölö, si no alau tou ba si no muheta balu-balu hörö:', '["SamI 15:8","MozI 12:3"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 5, 'Ha lö agasökhi nosemi, ya''ami ma''uwu Yakobo! nahiami andrö, ya''ami Iraono Gizeraeli.', '["SamI 15:8","MozI 12:3"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 6, 'Si mane daso, si no ebolo misa, si mane kabu ba mbewe nidanö sebua, si mane göna farasi, nitanö Yehowa, si mane eresi ba mbewe nidanö!', '["SamI 15:8","MozI 12:3"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 7, 'Aduwa nidanö ba dimba andrö khönia, ba si lö ambö idanö nowinia. Sabölö moroi khö Agagi andrö razora, sebua sibai wa''asalaŵania.[1]', '["SamI 15:8","MozI 12:3"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 8, 'Lowalangi andrö zangeheta mege ba danö Miserayi, ba no amaedola wa''abölö göröbao khöra. Niha si fa''emali khöra, ba la''a, larasa döla, lafatö nono wana khöra.', '["SamI 15:8","MozI 12:3"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 9, 'No lafadölö ira, mörö ira tou, si mane singo, ba si mane singo si alawe; ha niha zi keani ya''ira? Ha niha zamahowu''ö ya''ugö, ba nifahowu-howu''ö, ba ha niha zangelifi ya''ugö, ba ni''elifi!"[2]', '["SamI 15:8","MozI 12:3"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 10, 'Ba mofönu sibai Mbalaki khö Mbileamo, ilau datawo. Ba imane khö Mbileamo: Ba wangelifi emaligu ufakaoni''ö ndra''ugö, ba no ha sambalö famahowu khöu, no medölu ae!', '[]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 11, 'Ba fuli''ö manö sa''ae khömi; tödögu, ba u''ebua''ö luou, ba si lö luo ndra''ugö ibe''e Yehowa.', '[]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 12, 'Ba imane Bileamo khö Mbalaki: Hadia, tenga no uŵa''ö ba zinenge andrö, nifatengeu khögu:', '["Neh 13:2"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 13, 'He afönu nomonia firö ba ana''a ibe''e khögu Balaki, ba tebai zui ufadaö niŵa''ö Yehowa ba tebai ulau zomasi ndra''o, ha nibe''e Yehowa ba dödögu, ha da''ö uŵa''ö.[3]', '["Neh 13:2"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 14, 'Ba ufulido sa''ae ba niwama; ba hiza, da''ubokai khöu hadia nilau niha andrö ba mbanuau dania.', '["Neh 13:2"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 15, 'Ba iŵa''ö niŵa''önia, imane: "Da''e niŵa''ö Mbileamo andre, ono Mbeori, niha andrö, si no teboka hörö.', '["SamII 8:2; Yer 48:45","SamII 8:14"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 16, 'Da''e niŵa''ö zamondrongo fehede Lowalangi, si no aboto ba dödö Fondrege zalaŵa andrö, sanehe angilata khö Zi lö ambö fa''abölö, si no alau tou ba si no muheta balu-balu hörö;', '["SamII 8:2; Yer 48:45","SamII 8:14"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 17, 'U''ila ia, ba lö''ö na anehedo ia, ba aröu na ma''ifu. Tumbu ndröfi ba ma''uwu Yakobo, ba si''o zalaŵa i''otarai Ndraono Gizeraeli; da''ö worasa dangi-dangi Ndraono Moabi, fabaya amu''u ma''uwu Zeti fefu.[4]', '["SamII 8:2; Yer 48:45","SamII 8:14"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 18, 'Tanö Ndraono Gedomo, ba möi barö mbawara, ba Se''ira, emalira, ba möi barö mbawara. Ba sebua turia nilau Ndraono Gizeraeli,[5]', '["SamII 8:2; Yer 48:45","SamII 8:14"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 19, 'Ba ma''uwu Yakobo i''otarai salaŵa, ba ihori zi no moloi mege, ba mbanua misa!"', '["SamII 8:2; Yer 48:45","SamII 8:14"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 20, 'Ba me i''ila Ndraono Gamaleki, ba iŵa''ö niŵa''önia, imane: "Si a''a niha baero andrö, ba ya''ia Ndraono Gamaleki, ba fozunia, ba fa''atekiko!"[6]', '["SamI 15:3"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 21, 'Ba me i''ila ma''uwu Geni andrö, ba iŵa''ö niŵa''önia, imane: "No aro nahiamö, nifanuge ba dete gara gazunimö.[7]', '["MozI 15:19"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 22, 'Ba fa''atekiko sa ato föna Ga''ino, ha wa''ara tö na, ba la''oloi''ö ndra''ugö Dawa Asiria."', '["MozI 15:19"]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 23, 'Ba imane na: "Alai ita, ha niha zauri, na ifatörö zi manö Lowalangi!', '[]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 24, 'Ba hiza nowo moroi sa ba Ndrawa Giti, fangöhöndrögö Ndrawa Asiria, fangöhöndrögö danö si yefo; ba da''ö göi, ba fa''atekiko fönania."', '[]', NULL),
  (3475712, 'OT', 'Moze IV', 24, 25, 'Ba ifazaŵa ia Bileamo, ba wamuli ya''ia ba khöra, ba mofanö göi Mbalaki.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 1, 'Ba me soso ba Zitimi Ndraono Gizeraeli, ba ibörötaigö lahorö-horöni nono alawe Ndraono Moabi.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 2, 'Lakaoni ira ba wemanga ba wame''e adu khöra Iraono Moabi; ba manga ira ba mangalulu ba nadu khöra.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 3, 'Ba molemba ba Mba''ali-Weoro Ndraono Gizeraeli;', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 4, 'Ba imane Yehowa khö Moze: Owuloi zatua mbanua fefu, ba taŵi ira ba zino, khö Yehowa, ena''ö döhö wönu Yehowa andrö ba Ndraono Gizeraeli, si no abölö-bölö.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 5, 'Ba imane Moze ba zanguhuku ba Ndraono Gizeraeli: Ibunu mbanuania zamösana, ya''ami, banuania si no molemba ba Mba''ali-Weoro andrö![2]', '["MozII 32:27"]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 6, 'Ba so zamösa, Iraono Gizeraeli, solohe ba khöra ono alawe Ndraono Midiano, ba zanehe Moze ba Iraono Gizeraeli sato, fefu, me mangarö-ngarö ira ba golayama nose wama''ele''ö.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 7, 'Ba me i''ila da''ö Fineha, ono Geleazari, ma''uwu Ga''aroni ere, ba maoso ia ba hunö zato, ituyu doho,', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 8, 'ba i''o''ö mbanuara andrö misi bakha, ba faoma itaru''ö ba dalu doho, darua ira iwara andrö alawe andrö;', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 9, 'Ba fa''ato zi no tekiko ba wamakao andrö, ba no 24.000.[3]', '["KorI 10:8"]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 10, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 11, 'Fineha andrö, ono Geleazari, ma''uwu Ga''aroni ere, ba no ibe''e alö wönugu ba Ndraono Gizeraeli, me no mofönu ia khöra, si mane na mofönu-fönu ndra''o khöra, ba tobali lö uhori Ndraono Gizeraeli, ba wönugu andrö.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 12, 'Andrö öŵa''ö khönia: Hiza, ufabu''u khönia wangorifi khögu.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 13, 'Nitehe ere ia, awö nga''ötönia dania, götö-götö wa''ara; böli gölönia, me no mofönu ia ba zöfönu Lowalanginia, ba me no ifaigi wameta sala ba Ndraono Gizeraeli.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 14, 'Ba töi mbanuara andrö nibunu, awö ndra alawe Iraono Midiano andrö, ba Simeri, ono Zalu, satua mbanua ba mado Zimeoni.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 15, 'Ba ira alawe Iraono Midiano nibunu andrö, ba Kosibi döi, ono Zuri, satua mbanua, satua zi sawu ba Ndraono Midiano.', '[]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 16, 'Ba humede Yehowa khö Moze, imane:', '["Faigi 31:2"]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 17, 'Misuwö Ndraono Midiano, mi''alani ira.', '["Faigi 31:2"]', NULL),
  (3475713, 'OT', 'Moze IV', 25, 18, 'Noa sa lasuwö ami falimosara andrö, nilaura khömi, ba Weoro andrö ba ba mbanuara andrö, Kosibi, ono zalaŵa Ndraono Midiano nibunu me luo tefatörö khömi wamakao andrö, ba Weoro andrö.[4]', '["Faigi 31:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 1, 'Ba me no döhö wamakao andrö, ba imane Yehowa khö Moze, ba khö Geleazari, ono Ga''aroni ere:', '["Faigi 1:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 2, 'Mi''ofaya Ndraono Gizeraeli fefu, si 20 fakhe ba si a''a moroi andrö, sambu-sambua mado, dozi solohe baluse ba Ndraono Gizeraeli.[1]', '["Faigi 1:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 3, 'Ba laŵa''ö li ira Moze Eleazari khöra, ba zalo''o tanö Ndraono Moabi, ba gamaudu Yerikho,', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 4, 'khöra si 20 fakhe ba si a''a moroi andrö, dali niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 5, 'Rubeno, si a''a Ndraono Gizeraeli. Ba iraono Rubeno, ba Hanokhi, tua nga''ötö Hanokhi andrö; ba Walu, tua nga''ötö Walu andrö.[2]', '["MozI 46:8 b.t."]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 6, 'Ba Heseroni, tua nga''ötö Heseroni andrö; ba Karemi, tua nga''ötö Garemi andrö.', '["MozI 46:8 b.t."]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 7, 'Da''ö nga''ötö Rubeno andrö. Ba fa''ato ni''ofaya ya''ira, ba no 43.730.', '["MozI 46:8 b.t."]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 8, 'Ba ono Walu andrö, ba Eliabi.', '["Faigi 16:1 b.t.","Sin 42:1"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 9, 'Ba iraono Geliabi, ba Nemueli ba Datano ba Abiramo. Da''ö zalaŵa rafe andrö, Datano ba Abiramo, si fao khö Gora no, me fasoso ira khö Yehowa,[3]', '["Faigi 16:1 b.t.","Sin 42:1"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 10, 'me ifaboka mbawania tanö, me itölö ira, awö Gora, me tekiko zi fao andrö, me i''a alitö zi 250 niha, me tobali tandra [famangelama] ira.', '["Faigi 16:1 b.t.","Sin 42:1"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 11, 'Ba lö si tekiko ndraono Gora.[4]', '["Faigi 16:1 b.t.","Sin 42:1"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 12, 'Ba ba nga''ötö ndraono Zimeoni, ba Nemueli, tua nga''ötö Nemueli andrö, ba Yamini, tua nga''ötö Yamini andrö, ba Yakhino, tua nga''ötö Yakhino andrö,', '["Faigi 16:1 b.t.","Sin 42:1"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 13, 'ba Sera, tua nga''ötö Zera andrö, ba Saulo, tua nga''ötö Zaulo andrö;', '["Faigi 16:1 b.t.","Sin 42:1"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 14, 'da''ö nga''ötö Zimeoni andrö, no 22.200.', '["Faigi 16:1 b.t.","Sin 42:1"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 15, 'Ba ba nga''ötö ndraono Gado andrö, ba Sefono, tua nga''ötö Zefono andrö, ba Hagi, tua nga''ötö Hagi andrö, ba Suni, tua nga''ötö Zuni andrö,', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 16, 'ba Osini, tua nga''ötö Gosini andrö, ba Eri,', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 17, 'tua nga''ötö Geri andrö, ba Arodi, tua nga''ötö Garodi andrö, ba Areli, tua nga''ötö Gareli andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 18, 'Da''ö nga''ötö ndraono Gado andrö, ha wa''ato ira, ni''ofaya, no 40.500.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 19, 'Ba ono Yuda, ba Eri ba Onani, ba Eri andrö ba Onani, ba si mate ba danö Gana''ana.[5]', '["MozI 38:3,4"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 20, 'Ba ba nga''ötö ndraono Yuda andrö, ba Sela, tua nga''ötö Zela andrö, ba Faresi, tua nga''ötö Waresi andrö, ba Sera, tua nga''ötö Zera andrö.', '["MozI 38:3,4"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 21, 'Ba ba ndraono Waresi andrö, ba Eseromo, tua nga''ötö Geseromo andrö, ba Hamuli, tua nga''ötö Hamuli andrö.', '["MozI 38:3,4"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 22, 'Da''ö nga''ötö Yuda andrö, ha wa''ato ira, ni''ofaya no 76.500.', '["MozI 38:3,4"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 23, 'Ba ba nga''ötö Isasari andrö, ba Tola, tua nga''ötö Dola andrö, ba Fuwa, tua nga''ötö Wuwa andrö,', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 24, 'ba Yasubi, tua nga''ötö Yasubi andrö, ba Simeroni, tua nga''ötö Zimeroni andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 25, 'Da''ö nga''ötö Isasari andrö, ha wa''ato ira, ni''ofaya, no 64.300.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 26, 'Ba ba nga''ötö Zebuloni, ba Seredi, tua nga''ötö Zeredi andrö, ba Elono, tua nga''ötö Gelono andrö, ba Yaleeli, tua nga''ötö Yaleeli andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 27, 'Da''o nga''ötö Zebuloni andrö, ha wa''ato ira, ni''ofaya, no 60.500.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 28, 'Ba nga''ötö Yosefo, ba ononia andrö, Manase ba Eferayi.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 29, 'Ba ba ndraono Manase, ba Makhiro, tua nga''ötö Makhiro andrö. Ono Makhiro, ba Gileadi, tua nga''ötö Gileadi andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 30, 'Ono Gileadi andrö, ba Yezeri, tua nga''ötö Yezeri andrö, ba Heleki, tua nga''ötö Heleki andrö,', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 31, 'ba Aserieli, tua nga''ötö Gaserieli andrö, ba Sikhema, tua nga''ötö Zikhema andrö,', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 32, 'ba Semida, tua nga''ötö Zemida andrö, ba Heferi, tua nga''ötö Heferi andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 33, 'Ba Selofadi andrö, ono Heferi, ba si lö ono matua, ha ono alawe; ba töi nononia alawe andrö, ba Mala ba Noa ba Hogela ba Milika ba Tirisa.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 34, 'Da''ö nga''ötö Manase, ha wa''ato ira ni''ofaya, no 52.700.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 35, 'Ba da''e nga''ötö ndraono Geferayi andrö: Sutela, tua nga''ötö Zutela andrö, ba Bekheri, tua nga''ötö Mbekheri andrö, ba Tahana, tua nga''ötö Dahana andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 36, 'Ba da''e Ndraono Zutela andrö: Erano, tua nga''ötö Gerano andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 37, 'Da''ö nga''ötö ndraono Geferayi, ha wa''ato ira, ni''ofaya, no 32.500. Da''ö nga''ötö ndraono Yosefo andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 38, 'Ba ba nga''ötö ndraono Mbeniyami, ba Bela, tua nga''ötö Mbela andrö ba Asibeli, tua nga''ötö Gasibeli andrö, ba Ahiramo, tua nga''ötö Gahiramo andrö,', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 39, 'ba Sufama, tua nga''ötö Zufama andrö, ba Hufama, tua nga''ötö Hufama andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 40, 'Ba ono Mbela andrö, ba Aradi ba Na''ama; Aradi, ba tua nga''ötö Garadi andrö, ba Na''ama, ba tua nga''ötö Na''ama andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 41, 'Da''ö nga''ötö ndraono Mbeniyami andrö, ha wa''ato ira, ni''ofaya, no 45.600.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 42, 'Ba da''e nga''ötö ndraono Dano andrö: Suha, tua nga''ötö Zuha andrö; da''ö nga''ötö Dano, ba watalifusöta andrö khöra.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 43, 'Fefu nga''ötö Zuha andrö, ha wa''ato ira, ni''ofaya, ba no 64.400.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 44, 'Ba ba nga''ötö ndraono Gaseri, ba Yimena, tua nga''ötö Yimena andrö, ba Yisiwi, tua nga''ötö Yisiwi andrö, ba Beria, tua nga''ötö Mberia andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 45, 'Ba iraono Mberia, ba Heberi, tua nga''ötö Heberi andrö, ba Malekieli, tua nga''ötö Malekieli andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 46, 'Ba ono Gaseri alawe, ba Sera döi.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 47, 'Da''ö nga''ötö ndraono Gaseri, ha wa''ato ira, ni''ofaya, no 53.400.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 48, 'Ba ba nga''ötö ndraono Nafatali, ba Yaseeli, tua nga''ötö Yaseeli andrö, ba Guni, tua nga''otö Guni andrö,', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475714, 'OT', 'Moze IV', 26, 49, 'ba Yeseri, tua nga''ötö Yeseri andrö, ba Silemi, tua nga''ötö Zilemi andrö.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 50, 'Da''ö nga''ötö Nafetali ba wafalitusöta andrö khöra, ba fa''ato ni''ofaya, ya''ira, ba no 45.400.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 51, 'Da''ö ni''ofaya, Iraono Gizeraeli, no 601.730.', '[]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 52, 'Ba humede Yehowa khö Moze, imane:', '["Faigi 33:54; Yos 14:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 53, 'Khöra andrö lafaosa danö, nitutu tanö, balazi ha wa''ato ira.', '["Faigi 33:54; Yos 14:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 54, 'Sato niha, ba ebolo danö labe''e tana khöra, ba ba zi öna-öna fa''ato, ba la''önaigö wogoi tana khöra; balazi ha wa''ato ni''ofaya, ya''ira, ba wogoi tana khöra.[6]', '["Faigi 33:54; Yos 14:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 55, 'Ba nilau dahö-dahö ba wamaosa tanö, sambu-sambua mado zanema, balazi döi duara.', '["Faigi 33:54; Yos 14:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 56, 'Dali dahö-dahö, ba wamaosa khöra, tana khöra, ba zato niha ba ba zambö fa''ato.', '["Faigi 33:54; Yos 14:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 57, 'Ba da''ö ni''ofaya ono Lewi, sambu-sambua watalifusöta: Gereso andrö, tua nga''ötö Gereso, ba Kahati, tua nga''ötö Gahati andrö, ba Merari, tua nga''ötö Merari andrö.[7]', '["MozII 6:16","MozII 6:20","MozIII 10:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 58, 'Da''ö nga''ötö Lewi andrö: nga''ötö Libeni andrö, ba nga''ötö Heberona, ba nga''ötö Maheli, ba nga''ötö Husi, ba nga''ötö Gora. Ba ono Gahati, ba Ameramo andrö;', '["MozII 6:16","MozII 6:20","MozIII 10:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 59, 'ba fo''omo Gameramo, ba Yokhebe, ono Lewi alawe, ononia ba danö Miserayi; ba ono da''ö khö Gameramo, ba A''aroni ba Moze ba talifusöra alawe andrö, Miriya.[8]', '["MozII 6:16","MozII 6:20","MozIII 10:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 60, 'Ba ono Ga''aroni, ba Nadabi ba Abihu ba Eleazari ba Itamari.', '["MozII 6:16","MozII 6:20","MozIII 10:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 61, 'Ba Nadabi andrö ba Abihu, ba mate, me la''ohe föna Yehowa galitö si tenga.[9]', '["MozII 6:16","MozII 6:20","MozIII 10:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 62, 'Ba fa''ato ni''ofaya, ya''ira, ba no 23.000, dozi motöi matua, si sara waŵa fa''ebua ba si a''a moroi andrö. Lö''ö sa mufao ira ba wangofaya Iraono Gizeraeli bö''ö mege, me lö sinemara tana khöra tanö, ba ngai Ndraono Gizeraeli bö''ö.', '["MozII 6:16","MozII 6:20","MozIII 10:2"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 63, 'Da''ö ni''ofaya ndra Moze Eleazari ere andrö, sangofaya Iraono Gizeraeli ba zalo''o tanö Ndraono Moabi, ba mbewe Yoridano, ba gamaudu Yerikho.', '["Faigi 14:23"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 64, 'Ba samösa lö''ö sa''ae ba da''ö ni''ofaya ndra Moze A''aroni ere no, me la''ofaya Ndraono Gizeraeli ba danö si mate ba gahe hili Zina''i.', '["Faigi 14:23"]', NULL),
  (3475714, 'OT', 'Moze IV', 26, 65, 'Noa sa iŵa''ö khöra Yehowa, si mate ba danö si mate ira; ba no tobali samösa lö si tosai, ya''ira andrö, baero Galebi, ono Yefune, ba Yosua, ono Nuni.[10]', '["Faigi 14:23"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 1, 'Ba so nono Zelofadi alawe, Selofadi ono Heferi ono Gileadi ono Makhiro ono Manase, nga''ötö Manase andrö, ono Yosefo, ba töi nononia andrö, ba Mala ba Noa ba Hogela ba Milika ba Tirisa.', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 2, 'La''ondrasi ndra Moze Eleazari ere andrö ba satua ba sato fefu, ba golayama nose wama''ele''ö, lamane:', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 3, 'Amama, ba no mate ba danö si mate, tenga awö zi fao khö Gora no, si maoso no, solaŵa Yehowa; ba horönia [samösa ya''ia] mate ia. Ba lö ono matua khönia.', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 4, 'Ba hana wa labe''e taya döi namama ba nga''ötö andrö khöra, me no lö ono matua khönia; Khöma mibe''e dana khöma tanö, ba ngai dalifusö namama!', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 5, 'Ba i''ohe khö Yehowa huhuora andrö Moze.', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 6, 'Ba imane Yehowa khö Moze:', '["Faigi 36:2"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 7, 'Si ndruhu niŵa''ö nono Zelofadi andrö. Öbe''e sa''ae khöra dana khöra, ba ngai dalifusö namara, tana khö namara ena''ö, ba khöra möi öbe''e.[1]', '["Faigi 36:2"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 8, 'Ba ömane ba Ndraono Gizeraeli: Na so zi mate lö ono matua, ba khö nononia alawe möi dana khönia tanö mibe''e.', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 9, 'Ba na lö''ö göi ono alawe khönia, ba ba dalifusönia mitehe dana khönia andrö.', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 10, 'Ba na lö''ö göi talifusönia, ba ba dalifusö namania mitehe.', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 11, 'Ba na lö''ö göi talifusö namania, ba ba zabölö ahatö khönia ba nga''ötöra andrö möi mibe''e; da''ö sa''ae zokhö.', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 12, 'Ba imane Yehowa khö Moze: Ae miyaŵa ba hili Gabari andrö, ba faigi danö andrö, nibe''egu ba Ndraono Gizeraeli.[2]', '["MozV 32:49","Faigi 20:28","Faigi 20:12"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 13, 'Ba na no öfaigi, ba la''orudugö göi ndra''ugö khö ndra tuau, si mane ga''au A''aroni, si no mu''orudugö,[3]', '["MozV 32:49","Faigi 20:28","Faigi 20:12"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 14, 'me no lö nifondrondrongomi niŵa''ögu andrö, ba danö si mate Sini, me fasoso zato, me mifolakhömi mena''ö ndra''odo ba zanehe ira, ba nidanö andrö (Idanö wasosota andrö da''ö ba Gadesi, ba danö si mate Sini)[4]', '["MozV 32:49","Faigi 20:28","Faigi 20:12"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 15, 'Ba humede Moze khö Yehowa, imane:', '["Faigi 16:22","Mat 9:36"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 16, 'Ena''ö na ifataro zamösa solohe sato Yehowa andrö, So''aya noso ba mboto niha fefu,[5]', '["Faigi 16:22","Mat 9:36"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 17, 'solohe ya''ira na mofanö ba na mangawuli, solohe ya''ira na möi, heza, ba na lafuli ira baose, fa böi hulö mbiri-biri si lö kubalo mbanua Yehowa andrö.[6]', '["Faigi 16:22","Mat 9:36"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 18, 'Ba imane Yehowa khö Moze: Halö khöu Yosua andrö, ono Nuni, niha si so Eheha, tufa högönia tangau,[7]', '["MozV 1:38","MozII 28:30"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 19, 'ba ohe khö Geleazari ere andrö ba ba zato fefu, ba wamataro ya''ia ba zanehe ira;', '["MozV 1:38","MozII 28:30"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 20, 'ba öhare''ö khönia ösa lakhömimö andrö, ena''ö lafondrondrongo linia Iraono Gizeraeli sato, fefu.', '["MozV 1:38","MozII 28:30"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 21, 'Yamöi khö Geleazari ere, ena''ö idöni ba duna Urimi andrö, khö Yehowa; balazi dania niŵa''önia na mofanö ira, ba na molombase, ya''ia ba Iraono Gizeraeli fefu, sato fefu.[8]', '["MozV 1:38","MozII 28:30"]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 22, 'Ba i''o''ö Moze niŵa''ö Yehowa khönia: ihalö Yosua andrö ba i''ohe khö Geleazari ere ba ba zato fefu.', '[]', NULL),
  (3475715, 'OT', 'Moze IV', 27, 23, 'Ba itufa högönia tanga, ifataro ia, dali niŵa''ö Yehowa, nifa''ema Moze.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 1, 'Ba humede Yehowa khö Moze, imane:', '["MozIII 3:11; 21:6"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 2, 'Be''e li ba Ndraono Gizeraeli, ömane khöra: Böi olifu ami wame''e ame''ela sumange andrö khögu na inötö, ögu, sumange nifatörö ba galitö, nihonogöi khögu, samohua khögu.[1]', '["MozIII 3:11; 21:6"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 3, 'Ömane na khöra: Da''ö zumange nifatörö ba galitö, nibe''emi khö Yehowa: Sero ma''ökhö, ba dua rozi nono mbiri-biri, si lö sala, sumange nitunu, si lö aefa-aefa.[2]', '["MozII 29:38","Faigi 15:4"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 4, 'Ono mbiri-biri si sara, ba na mahemolu mbanua öbe''e, ba si sara, ba na tanö owi, ba tölu kata hamo si sökhi,', '["MozII 29:38","Faigi 15:4"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 5, 'ninifakhöyö fanikha mbua zai nifufu, samba kata, sumange ni''a.[3]', '["MozII 29:38","Faigi 15:4"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 6, 'Da''ö zumange nitunu andrö, si lö aefa-aefa, nibe''e no, ba gahe hili Zina''i, samohua, nibe''e khö Yehowa, sumange nifatörö ba galitö.', '["MozII 29:38","Faigi 15:4"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 7, 'Ba nifao ba zi sara-sara ono mbiri-biri, sumange nibadu, ba samba-samba kata. Ba ni''amoni''ö labe''e khö Yehowa zumange nibadu andrö, agu nilau famasa.', '["MozII 29:38","Faigi 15:4"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 8, 'Ba ono mbiri-biri si sara, ba na tanö owi öbe''e; ba nifao zumange ni''a, si mane ba zanguhulö wongi mege, awö zumange nibadu andrö, nifao khönia, sumange nifatörö ba galitö, nibe''e khö Yehowa, samohua.', '["MozII 29:38","Faigi 15:4"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 9, 'Ba na luo sabato, ba dua rozi nono mbiri-biri si döfi fa''ebua, si lö sala, ba tölu hinaoya hamo si sökhi nifaruka fanikha, sumange ni''a, ba sumange nibadu andrö, nifao ba da''ö.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 10, 'Da''ö zumange nitunu andrö, ero na luo sabato, baero zumange nitunu andrö, si lö aefa-aefa, ba sumange nibadu andrö, nifao ba da''ö.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 11, 'Ba ero na fasulöna mbaŵa khömi, ba mibe''e sumange Yehowa, ba dua rozi nono zawi, si matua ba sageu mbiri-biri si matua ba fitu rozi nono mbiri-biri, si döfi fa''ebua, si lö sala;', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 12, 'ba sara-sara ono zawi, ba dua-dua dumba nifao hamo si sökhi nifaruka fanikha, sumange ni''a, ba sage-sageu biri-biri si matua, ba tölu-tölu hinaoya hamo si sökhi, nifaruka fanikha, sumange ni''a,', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 13, 'ba sara-sara ono mbiri-biri, ba tölu-tölu kata hamo si sökhi, nifaruka fanikha, sumange ni''a — sumange nitunu, samohua, sumange nifatörö ba galitö, nibe''e khö Yehowa.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 14, 'Ba ba zumange nibadu andrö, nifao ba da''ö, ba sara-sara ono zawi, ba samba-samba hinaoya nagu ba sage-sageu biri-biri si matua, ba samba-samba kata a matonga, ba sara-sara ono mbiri-biri, ba samba-samba kata.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 15, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, nibe''e khö Yehowa; baero zumange nitunu andrö, si lö aefa-aefa, ba baero zumange nibadu andrö, nifao ba da''ö, wame''e da''ö.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 16, 'Ba ba zi meweleöfa ba mbaŵa si föföna, ba telau wasa andrö, khö Yehowa.[4]', '["MozII 12:18,21; MozIII 23:5","MozIII 23:7"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 17, 'Ba ba zi mewelelima ba mbaŵa da''ö, ba aekhu ba danö gowasa andrö. Fitu bongi wa''ara te''a roti si lö mu''aisöni.', '["MozII 12:18,21; MozIII 23:5","MozIII 23:7"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 18, 'Na luo si föföna andrö, ba owulo ba ni''amoni''ö ba lö tola mihalö hadia ia halöŵö ba da''ö.[5]', '["MozII 12:18,21; MozIII 23:5","MozIII 23:7"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 19, 'Ba nibe''e khö Yehowa sumange nifatörö ba galitö, sumange nitunu, ba dua rozi nono zawi, si matua, ba sageu mbiri-biri si matua ba fitu rozi nono mbiri-biri; si lö sala, mibe''e.', '["MozII 12:18,21; MozIII 23:5","MozIII 23:7"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 20, 'Ba nifao ba da''ö, sumange ni''a, ba hamo si sökhi, nifaruka fanikha, dua dumba zi fao ba nono zawi, ba tölu hinaoya ba mbiri-biri si matua andrö;', '["MozII 12:18,21; MozIII 23:5","MozIII 23:7"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 21, 'ba sara-sara ono mbiri-biri si fitu andrö, ba tölu-tölu kata mifao.', '["MozII 12:18,21; MozIII 23:5","MozIII 23:7"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 22, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, ba wameta salami andrö.', '["MozII 12:18,21; MozIII 23:5","MozIII 23:7"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 23, 'Da''ö [fefu] mibe''e, lö lai zumange nitunu andrö ba zanguhulö wongi, nibe''e sumange nitunu si lö aefa-aefa.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 24, 'Sumange da''ö nibe''e khö Yehowa, ö sumange nifatörö ba galitö, samohua, ero ma''ökhö, fitu bongi wa''ara; baero zumange nitunu andrö si lö aefa-aefa andrö, ba baero zumange nibadu andrö, nifao ba da''ö wame''e ya''ia.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 25, 'Ba na luo si fitu, ba owulo ami ba ni''amoni''ö, ba lö tola mihalö hadia ia halöŵö ba da''ö.', '[]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 26, 'Ba na baŵa wamasi sahulö, na mibe''e zumange Yehowa, sumange ni''a, föfö mbua zahulö, na owasa wendrakose khömi, ba owulo ami ba ni''amoni''ö; ba lö tola mihalö hadia ia halöŵö ba da''ö.[6]', '["MozIII 23:15"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 27, 'Ba sumange nitunu, samohua, nibe''emi khö Yehowa, ba dua rozi nono zawi ba sageu mbiri-biri si matua ba fitu rozi nono mbiri-biri.', '["MozIII 23:15"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 28, 'Ba nifao ba da''ö sumange ni''a, ba hamo si sökhi nifaruka fanikha, sara-sara ono zawi ba dua-dua dumba, ba ba mbiri-biri si matua andrö,', '["MozIII 23:15"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 29, 'ba tölu hinaoya, ba sara-sara ono mbiri-biri si fitu andrö, ba tölu-tölu kata;', '["MozIII 23:15"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 30, 'ba sageu nambi si matua, ba wameta salami.', '["MozIII 23:15"]', NULL),
  (3475716, 'OT', 'Moze IV', 28, 31, 'Baero zumange nitunu andrö, si lö aefa-aefa andrö, ba baero zumange ni''a ba sumange nibadu, nifao ba da''ö, wame''emi ya''ia; si lö sala mibe''e.', '["MozIII 23:15"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 1, 'Ba na tesa''a lö faoro, na baŵa si fitu, ba owulo ami ba ni''amoni''ö, ba lö tola mihalö hadia ia halöŵö ba da''ö, baŵa wolau torofe fangekhugö niha ia khömi, miŵa''ö.[1]', '["MozIII 23:24"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 2, 'Ba sumange nitunu, samohua, nibe''emi khö Yehowa ba da''ö, ba sara nono zawi, si matua, ba sageu mbiri-biri, si matua ba fitu rozi nono mbiri-biri, si döfi fa''ebua, si lö sala.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 3, 'Ba nifao ba da''ö, sumange ni''a, hamo si sökhi, nifaruka fanikha, ba dua dumba ba nono zawi andrö, ba tölu hinaoya ba mbiri-biri si matua andrö,', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 4, 'ba sara-sara ono mbiri-biri andrö si fitu, ba tölu-tölu kata.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 5, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, ba wameta salami,', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 6, 'baero zumange nitunu andrö na fasulöna, awö zumange ni''a, nifao ba da''ö, ba baero zumange nitunu andrö sero ma''ökhö ba sumange ni''a andrö, ba sumange nibadu, nifao, nifakhoi andrö — samohua, sumange nifatörö ba galitö, nibe''e khö Yehowa.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 7, 'Ba ba zi mewulu, ba mbaŵa si fitu andrö, ba owulo ami ba ni''amoni''ö ba mangalulu ami; hadia ia halöŵö, ba lö tola mihalö ba da''ö.[2]', '["MozIII 23:27"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 8, 'Ba sumange nitunu, nibe''emi khö Yehowa, samohua, ba sara nono zawi, si matua, ba sageu mbiri-biri si matua ba fitu rozi nono mbiri-biri si döfi fa''ebua; si lö sala mibe''e.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 9, 'Ba nifao ba da''ö, sumange ni''a, ba hamo si sökhi nifaruka fanikha, dua dumba ba nono zawi andrö, ba tölu hinaoya ba mbiri-biri si matua,', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 10, 'ba sara-sara ono mbiri-biri andrö, ba tölu-tölu kata.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 11, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange fameta horö andrö, ba wameta salami, ba lö lai zumange nitunu andrö, sero ma''ökhö ba sumange ni''a ba sumange nibadu, nifao ba da''ö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 12, 'Ba ba duli ba mbaŵa si fitu andrö göi, ba owulo ami ba ni''amoni''ö; ba lö tola mihalö hadia ia halöŵö ba da''ö; owasa nilau khö Yehowa, fitu bongi wa''ara.[3]', '["MozIII 23:34"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 13, 'Ba sumange nitunu nibe''emi sumange nifatörö ba galitö, samohua khö Yehowa, ba feledölu nono zawi, si matua, ba dua geu mbiri-biri si matua, ba feleöfa nono mbiri-biri, si döfi fa''ebua; ba si lö sala.', '["MozIII 23:34"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 14, 'Ba nifao ba da''ö, sumange ni''a, ba hamo si sökhi, nifaruka fanikha, sara-sara ono zawi andrö, si feledölu, ba dua-dua dumba, ba sage-sageu biri-biri si matua, ba tölu-tölu hinaoya,', '["MozIII 23:34"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 15, 'ba sara-sara ono mbiri-biri andrö, si feleöfa, ba tölu-tölu kata.', '["MozIII 23:34"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 16, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange nitunu andrö, sero ma''ökhö ba sumange ni''a ba sumange nibadu, nifao ba da''ö.', '["MozIII 23:34"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 17, 'Ba mahemolu ö, ba felendrua rozi nono zawi, si matua, ba dua geu mbiri-biri si matua, ba feleöfa rozi nono mbiri-biri, si döfi fa''ebua, si lö sala,', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 18, 'awö zumange ni''a andrö ba sumange nibadu, nifao ba da''ö, ba nono zawi andrö ba ba mbiri-biri si matua ba ba nono mbiri-biri andrö, dali wa''oya, balazi nifakhoi andrö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 19, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange nitunu andrö, sero ma''ökhö ba sumange ni''a andrö ba sumange nibadu, nifao ba da''ö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 20, 'Ba mahemolu ö, ba felezara rozi nono zawi, ba dua geu mbiri-biri si matua, ba feleöfa nono mbiri-biri si lö sala,', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 21, 'si döfi fa''ebua, awö zumange ni''a andrö ba sumange nibadu, nifao ba da''ö, ba nono zawi andrö ba ba mbiri-biri si matua ba ba nono mbiri-biri andrö, dali wa''oya, balazi nifakhoi andrö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 22, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange nitunu andrö, sero ma''ökhö, ba sumange ni''a andrö ba sumange nibadu, nifao ba da''ö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 23, 'Ba mahemolu ö, ba fulu rozi nono zawi, ba dua geu mbiri-biri si matua ba feleöfa rozi nono mbiri-biri, si lö sala, si döfi fa''ebua,', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 24, 'awö zumange ni''a andrö ba sumange nibadu, nifao ba da''ö, ba nono zawi andrö ba ba mbiri-biri si matua ba ba nono mbiri-biri andrö, dali wa''oya, balazi nifakhoi andrö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 25, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange nitunu andrö, sero ma''ökhö ba sumange ni''a andrö ba sumange nibadu, nifao ba da''ö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 26, 'Ba mahemolu ö, ba siŵa rozi nono zawi, ba dua geu mbiri-biri si matua ba feleöfa rozi nono mbiri-biri, si lö sala, si döfi fa''ebua,', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 27, 'awö zumange ni''a andrö ba sumange nibadu, nifao ba da''ö, ba nono zawi andrö ba ba mbiri-biri si matua ba ba nono mbiri-biri andrö, dali wa''oya, balazi nifakhoi andrö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 28, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange nitunu andrö, sero ma''ökhö, ba sumange ni''a andrö ba sumange nibadu, nifao ba da''ö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 29, 'Ba mahemolu ö, ba ŵalu rozi nono zawi ba dua geu mbiri-biri si matua ba feleöfa rozi nono mbiri-biri, si lö sala ba si döfi fa''ebua,', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475717, 'OT', 'Moze IV', 29, 30, 'awö zumange ni''a andrö ba sumange nibadu, nifao ba da''ö, ba nono zawi andrö ba ba mbiri-biri si matua ba ba nono mbiri-biri andrö, dali wa''oya, balazi nifakhoi andrö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 31, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange nitunu andrö, sero ma''ökhö, ba sumange ni''a andrö ba sumange nibadu, nifao ba da''ö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 32, 'Ba mahemolu ö, ba fitu rozi nono zawi ba dua geu mbiri-biri si matua ba feleöfa nono mbiri-biri, si lö sala, si döfi fa''ebua,', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 33, 'awö zumange ni''a andrö ba sumange nibadu, nifao ba da''ö, ba nono zawi andrö ba ba mbiri-biri si matua ba ba nono mbiri-biri andrö, dali wa''oya, balazi nifakhoi andrö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 34, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange nitunu andrö, sero ma''ökhö, ba sumange ni''a andrö ba sumange nibadu, nifao ba da''ö.', '[]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 35, 'Ba na luo si ŵalu, ba owulo ami; ba lö tola mihalö hadia ia halöŵö ba da''ö.[4]', '["MozIII 23:36"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 36, 'Ba sumange nitunu, nibe''emi sumange nifatörö ba galitö, samohua khö Yehowa, ba sara nono zawi ba sageu mbiri-biri si matua, ba fitu rozi nono mbiri-biri, si lö sala, si döfi fa''ebua,', '["MozIII 23:36"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 37, 'awö zumange ni''a andrö ba sumange nibadu, nifao ba da''ö, ba nono zawi andrö ba ba mbiri-biri si matua ba ba nono mbiri-biri andrö, dali wa''oya, balazi nifakhoi andrö.', '["MozIII 23:36"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 38, 'Ba baero ö, ba sageu nambi si matua, sumange fameta horö, lö lai zumange nitunu andrö, sero ma''ökhö, ba sumange ni''a andrö ba sumange nibadu, nifao ba da''ö.', '["MozIII 23:36"]', NULL),
  (3475717, 'OT', 'Moze IV', 29, 39, 'Da''ö zumange nibe''emi khö Yehowa, na baŵa gowasa andrö khömi, baero nibe''emi sumange nitunu ba sumange ni''a ba sumange nibadu ba sumange fangorifi, he na ba wanörö amabu''ula li, ba he na saoha gölö.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 1, 'Ba ibe''e li ba Ndraono Gizeraeli Moze, dali manö niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 2, 'Ba humede Moze ba zatua mado Ndraono Gizeraeli, imane:', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 3, 'Na so zamabu''u linia khö Yehowa, ma na möi ba hölu, wamabu''u famoni hadia ia, ba lö tola ifuli linia, yamutörö sibai niŵa''önia andrö.[1]', '["MozIII 27:2; MozV 23:21; Sin 50:14"]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 4, 'Ba na ono alawe zamabu''u linia khö Yehowa, na ifabu''u wamoni hadia ia, fatua ono alawe na ia baomo namania,', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 5, 'ba na irongo amania gamabu''ula linia ba famoni andrö, nifabu''unia, ba na lö hede-hedenia, ba tebai awu''a gamabu''ula linia fefu, ba famoninia fefu, nifabu''unia, ba tebai awu''a.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 6, 'Ba na itenaŵa ia amania, na luo irongo, ba si lö''ö gamabu''ulania fefu, awö wamoni andrö, nifabu''unia; ba ibe''e aefa zalania Yehowa, me no amania zanenaŵa ya''ia.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 7, 'Ba na lahalö ia lö mutörö gamabu''ula li, ba ma hadia niŵa''önia, si lö mu''odödögö sibai, wamabu''u hadia ia,', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 8, 'ba na irongo sangai ya''ia, ba na lö hede-hedenia ba da''ö, na luo irongo, ba lö awu''a gamabu''ula linia, ba famoninia andrö, nifabu''unia, ba lö awu''a.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 9, 'Ba na itenaŵa ia fo''omonia, na luo irongo, ba amaedola zi lö''ö gamabu''ula li andrö, si lö mutörö na, ibe''e, awö niŵa''önia andrö, si lö mu''odödögö sibai, wamabu''u hadia ia, ba ibe''e aefa zalania Yehowa.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 10, 'Ba amabu''ula li zi no mate donga ba amabu''ula li ndra alawe nitibo''ö, fefu nifabu''ura, ba lö awu''a khöra.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 11, 'Ba na baomo wo''omonia ifabu''u linia, ma si möi ba hölu, wamabu''u hadia ia wamoni, ba na irongo fo''omonia,', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 12, 'ba na lö hede-hedenia ba da''ö, ba na lö itenaŵa ia, ba tebai awu''a gamabu''ula linia fefu, ba famoni andrö fefu, nifabu''unia, ba tebai awu''a.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 13, 'Ba na awu''a ibe''e fo''omonia, na luo irongo nifabu''u andrö, ba amaedola zi lö''ö fefu niŵa''önia, he na amabu''ula li, ba he na famoni nifabu''unia; no si lö''ö ibe''e fo''omonia, andrö wa ibe''e aefa zalania Yehowa.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 14, 'Fefu gamabu''ula linia ba fefu wamabu''unia famoni, ba wamakao ya''ia, si no möi ba hölu ia, ba fo''omonia zangila mame''e aro, ba fa''omonia göi zangila mame''e si lö''ö.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 15, 'Na lö hede-hede wo''omonia ba da''ö, ha uga bongi, ba tebai awu''a ibe''e gamabu''ula linia fefu, si lö mutörö na, ba he famoninia fefu; börö wa lö hede-hedenia, me luo irongo; ba da''ö tebai awu''a.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 16, 'Ba na amaedola zi lö''ö ibe''e, na no irongo mege, ba ihalö horönia horö ndra alawe andrö ba da''ö.', '[]', NULL),
  (3475718, 'OT', 'Moze IV', 30, 17, 'Da''ö gamakhoita, niŵa''ö Yehowa khö Moze, amakhoita ba ndra matua ba khö wo''omonia, ba amakhoita khö nama ba khö nononia alawe, si lö muhalö, si so baomo namania na.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 1, 'Ba humede Yehowa khö Moze, imane:', '["Faigi 25:17"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 2, 'Lau mbalö Ndraono Gizeraeli ba Ndraono Midiano andrö; ba na aefa da''ö, ba ni''orudugö khö ndra tuau ndra''ugö.[1]', '["Faigi 25:17"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 3, 'Ba humede Moze ba zato, imane: Mi''a''aro''ö niha, banuami ba wanuwö, ena''ö lasuwö Ndraono Midiano andrö, ba wolau balö Yehowa ba Ndraono Midiano.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 4, 'Dozi mado Ndraono Gizeraeli, ba hönö-hönö zambu-sambua mado mifatenge ba wanuwö andrö.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 5, 'Ba latutuyu ba ngahönö Ndraono Gizeraeli hönö-hönö zambu-sambua mado, ni''a''aro''ö ba wanuwö andrö, felendrua ngahönö fefu.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 6, 'Ba ifatenge ira ba wanuwö Moze, hönö-hönö zambu-sambua mado; ba ifao khöra Wineha andrö, ono Geleazari andrö, ba wanuwö; solohe fakake ni''amoni''ö andrö da''ö, ba torofe fangekhugö niha.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 7, 'Ba möi ira manuwö Iraono Midiano, dali niŵa''ö Yehowa khö Moze, ba labunu fefu motöi matua.', '["Yos 13:21"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 8, 'Ba he razo ba Ndraono Midiano ba labubunu, awö ni''ö''ötöra andrö, ya''ia Ewi andrö ba Dekemi ba Suri ba Huri ba Reba, razo Ndraono Midiano, si dalima; ba he Bileamo andrö, ono Mbeori, ba labunu bawa zi''öli.[2]', '["Yos 13:21"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 9, 'Ba lara''u ndra alawe Ndraono Midiano Iraono Gizeraeli, fabaya iraono sawuyu khöra, ba la''ohe, ba uriföra sonoro fefu ba uriföra bö''ö fefu, awö nibaya-bayara fefu, ba la''ohe, ahuluara.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 10, 'Ba banuara ba nahiara fefu, ba osera fefu, ba latunu.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 11, 'Ba lahalö fefu nihalöra andrö, ahulua andrö fefu, he niha, ba he urifö,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 12, 'ba la''ohe khö Moze niha andrö, nira''ura ba ahulua bö''ö, awö nibaya-baya andrö, nihalöra, ba khö Geleazari ere ba ba Ndraono Gizeraeli sato, ba golombaseŵa ba zalo''o tanö Ndraono Moabi ba ndraso Yoridano, ba gamaudu Yerikho.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 13, 'Ba lafaondragö ira ira Moze Eleazari ere ba satua mbanua fefu, baero golombaseŵa.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 14, 'Ba mofönu Moze ba zolohe sanuwö, ba gumandra zi hönö ba ba gumandra zi otu, si oroi, manuwö.', '["Faigi 25:1; FetII 2:15; Fam 2:14","Sanguhuk 21:11"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 15, 'Imane khöra Moze: Hadia, no ahori mi''orifi ndra alawe?', '["Faigi 25:1; FetII 2:15; Fam 2:14","Sanguhuk 21:11"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 16, 'No ya''ira mbörö wangerogö Ndraono Gizeraeli Yehowa, me no iŵa''ö khöra Bileamo andrö, ba Weoro andrö, tobali itörö mbanua Yehowa famakao.[3]', '["Faigi 25:1; FetII 2:15; Fam 2:14","Sanguhuk 21:11"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 17, 'Ba mibunu fefu motöi matua ba ndraono andrö, ba dozi ira alawe ba zi no orudu ira matua, ba mibunu;[4]', '["Faigi 25:1; FetII 2:15; Fam 2:14","Sanguhuk 21:11"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 18, 'ba dozi ono alawe ba zi lö irai orudu ira matua, ba mi''orifi khömi.', '["Faigi 25:1; FetII 2:15; Fam 2:14","Sanguhuk 21:11"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 19, 'Ba ya''ami, ba fitu bongi mi''iagö baero golombaseŵa; dozi ami si no mamunu niha ba si no mombambaya nibunu, ba na luo si tölu ba na luo si fitu, ba misala''ö ami, fabaya ni''ohemi andrö, nirabu.[5]', '["Faigi 19:11"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 20, 'Ba si manö göi nukha fefu ba gama-gama uli zawi ba gama-gama bu mbiri-biri fefu ba fakake eu fefu, misala''ö.', '["Faigi 19:11"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 21, 'Ba imane Eleazari ere ba zabölö andrö, si no möi manuwö mege: Da''ö goroisa andrö, ni''oroi''ö Yehowa khö Moze.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 22, 'Ba ana''a ba firö ba töla ba si''öli ba simo mbanua ba simo itö,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 23, 'fefu hadia ia zanaha ba galitö, ba mifatörö ba galitö, ba aheta wa''ara''iönia; hatö fanasa ya''ia ba nidanö fangehao andrö. Ba fefu hadia ia zi lö manaha ba galitö, ba ba nidanö mifatörö.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 24, 'Ba na no mibabago nukhami, na luo si fitu andrö, ba no aheta wa''ara''iömi, ba tola sa''ae mifuli ami ba golombaseŵa.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 25, 'Ba humede Yehowa khö Moze, imane:', '["SamI 30:24"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 26, 'Ofaya fefu ha wa''oya gahulua andrö, nihalö, he niha, ba he urifö, ya''ugö ba Eleazari ere ba satua mbanua.', '["SamI 30:24"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 27, 'Ba si matonga, ba öbe''e ba zi no fao ba wanuwö, si no möi mege, ba si matonga, ba ba zato.[6]', '["SamI 30:24"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 28, 'Ba ba zanuwö andrö, si no möi mege, ba öhalö mbeo, khö Yehowa, sambua ba zi 500, he niha ba he sawi ba he kalide ba he biri-biri.', '["SamI 30:24"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 29, 'Ba zi matonga tana khöra mihalö ba mibe''e ba danga Geleazari ere, sumange fegero khö Yehowa.', '["SamI 30:24"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 30, 'Ba ba zi matonga ba Ndraono Gizeraeli, ba sambu-sambua ötutuyu ba zi lima-lima wulu, he niha ba he sawi ba he kalide ba he biri-biri — urifö andrö fefu — ba öbe''e ba danga nono Lewi, sangai-ngai halöŵö andrö ba nose Yehowa.', '["SamI 30:24"]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 31, 'Ba la''o''ö niŵa''ö Yehowa khö Moze ira Moze Eleazari ere.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 32, 'Ba fa''oya gahulua andrö, si tosai ahulua zanuwö andrö, ba no 675.000 nga''eu mbiri-biri,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 33, 'ba 72.000 zawi,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 34, 'ba 61.000 galide:', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 35, 'ba ba niha, ba fa''ato nono alawe andrö, ba zi lö irai orudu ira matua, ba no 32.000 niha.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 36, 'Ba si matongania andrö, tana ba zi no möi manuwö, ba 337.500 mbiri-biri,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 37, 'ba beo khö Yehowa, biri-biri andrö, ba no 675 nga''eu, ba 36.000 zawi,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 38, 'ba beo da''ö khö Yehowa, ba 72 nga''eu, ba 30.500 galide,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 39, 'ba beo da''ö khö Yehowa, ba 61 nga''eu;', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 40, 'ba 16.000 niha ba beo da''ö khö Yehowa, ba 32 niha.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 41, 'Ba beo andrö, nibe''e sumange fegero khö Yehowa, ba ibe''e ba danga Geleazari ere Moze, dali niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 42, 'Ba ba zi matongania andrö, tana ba Ndraono Gizeraeli, ni''oniagö Moze ba dana ba zanuwö andrö,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 43, '(ba dana ba zato, si matonga andrö, ba no 337.500 mbiri-biri,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 44, 'ba 36.000 zawi,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 45, 'ba 30.500 galide,', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 46, 'ba 16.000 niha) —', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 47, 'ba zi matonga andrö, tana ba Ndraono Gizeraeli, ba itutuyu Moze, sambu-sambua ba zi limalima wulu, he niha, ba he urifö, ba ibe''e ba danga nono Lewi, sangai-ngai halöŵö andrö ba nose Yehowa, dali niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 48, 'Ba la''ondrasi Moze kumandra ngahö-ngahönö zanuwö andrö, kumandra zi hönö ba kumandra zi otu, lamane khö Moze:', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 49, 'No la''ofaya wa''ato zanuwö andrö ni''ohema, enonimö, ba samösa lö nirongoma si lö''ö;', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 50, 'andrö mabe''e zumange Yehowa, fangandrö nosoma khö Yehowa, hadia nihalö zamösana ahulua gama-gama ana''a ba köla ba töla gasa ba laeduru ba saeru dalinga ba aya bö''ö.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 51, 'Ba lahalö khöra gana''a andrö ira Moze Eleazari ere — hadia ia ngawalö naya.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 52, 'Ba fa''ebua gana''a andrö, nibe''era sumange si no amaedola wegero khö Yehowa, ba no 16.750 sekeli; nibe''e gumandra zi hönö ba kumandra zi otu.', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 53, 'Ba sanuwö sato, ba no oi zara morabu göi:', '[]', NULL),
  (3475720, 'OT', 'Moze IV', 31, 54, 'Ba lahalö gana''a andrö khö gumandra zi hönö ba khö gumandra zi otu ira Moze Eleazari ere, ba labe''e ba nose wama''ele''ö, ena''ö itörö-törö tödö Yehowa Ndraono Gizeraeli.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 1, 'Ba ba mado Rubeno ba ba mado Gado, ba no oya sibai gurifö, no fahöna. Ba me no lafaigi danö Ya''ezeri andrö ba tanö Gileadi, ba la''ila, sökhi sibai tanö zoya urifö danö andrö.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 2, 'Ba so ira, mado Gado ba mado Rubeno, lamane khö ndra Moze Eleazari ere ba ba zatua mbanua:', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 3, 'Ataroto andrö ba Dibona ba Ya''ezeri ba Nimera ba Eleale ba Sebama ba Nebo ba Beono,', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 4, 'tanö andrö, nitolo Yehowa Iraono Gizeraeli, ba wame''e barö mbawara, ba no sökhi sibai tanö zoya urifö, ba no soya urifö zawuyumö andre.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 5, 'Ba lamane na: Na no ato falukha ndra''aga wa''ebua dödöu, ba he wisa na tetehe ba zawuyumö andre danö da''ö, khöra ba ba nga''ötöra mitou; böi fa''ötö ba Yoridano ndra''aga!', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 6, 'Ba imane Moze ba mado Gado andrö ba ba mado Rubeno: Hana, si möi manuwö dalifusömi, ba si iagö da''e ami?', '["Faigi 13:24","Yos 15:17"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 7, 'Hana wa mibe''e ata''u dalifusömi, we''amöi miyefo ba danö andrö, nibe''e Yehowa khöra?', '["Faigi 13:24","Yos 15:17"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 8, 'Si manö sibai wolau ndra amami mege, me ufatenge ira no, i''otarai Gadesi Mbarenea, ba wamaigi tanö andrö.', '["Faigi 13:24","Yos 15:17"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 9, 'Me no larugi ndraso Esikoli, ba lafeta''u Ndraono Gizeraeli, tobali lö edöna möi ira ba danö andrö, nibe''e Yehowa khöra.[1]', '["Faigi 13:24","Yos 15:17"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 10, 'Ba me luo da''ö, ba mofönu Yehowa, ba fahölu ia, imane:', '["Faigi 13:24","Yos 15:17"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 11, 'Niha andrö, si otarai danö Miserayi, si no dua wulu fakhe ba si a''a moroi andrö, ba böi yala''ila danö andrö, nifabu''ugu khö ndra Aberahamo, Iza''aki, Yakobo, fahölusa, me no lö ni''oigöra tödöra wolo''ö khögu,', '["Faigi 13:24","Yos 15:17"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 12, 'baero Galebi andrö, ono Yefune, ma''uwu Geni andrö, ba Yosua, ono Nuni, me no ya''ira zolo''ö sibai khögu.[2]', '["Faigi 13:24","Yos 15:17"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 13, 'Ba mofönu Yehowa ba Ndraono Gizeraeli; ba ifangörö-ngörö ira ba danö si mate, öfa wulu fakhe wa''ara, erege no ahori mate zi sagötö niha andrö, si no mosala khö Yehowa.', '["Faigi 13:24","Yos 15:17"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 14, 'Ba iada''e, ba no maoso ami, fangali ndra namami, madou zamazökhi horö, ba wondrou''ö na fönu Yehowa andrö ba Ndraono Gizeraeli, si no to''ua abölö-bölö.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 15, 'Ba na mi''erogö ia, ba iradö na ira ba danö si mate, ba mibe''e tekiko ira fefu.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 16, 'Ba la''ondrasi ia, ba lamane: Damafazökhi kandra mbiri-biri ba da''e, nahia guriföma andrö, ba mataru''ö mbanua nahia [wo''omoma ba nahia], ndraono suwuyu khöma;', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 17, 'ba ya''aga, ba ma''aro''ö ndra''aga, ba föna Ndraono Gizeraeli soga, irege no ma''ohe ira ba nahara; ba ba mbanua saro la''iagö [fo''omoma ba] iraono sawuyu khöma, börö niha ba danö andrö, [si fa''emali khöda].', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 18, 'Lö mangawuliga ba nahiama, irege no möi ba Ndraono Gizeraeli fefu dana khöra andrö, tanö.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 19, 'Lö''ö sa manema ndra''aga tana khöma, awöra, yefo Yoridano, no tana khöma danö tanö ba gatumbukha luo, i''otarai Yoridano.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475721, 'OT', 'Moze IV', 32, 20, 'Ba imane khöra Moze: Na mimanö, na mi''aro''ö ami, föna Yehowa, ba wanuwö,[3]', '["Yos 1:12"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 21, 'ba na mi''ötö Yoridano, föna Yehowa, dozi ami, si no mangaro, irege no itimba fönania zi fa''udu khönia, ba na awena dania mifuli ami,', '["Yos 1:12"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 22, 'na no ibe''e barö mbawania danö Yehowa, ba aefa ami ba khö Yehowa ba ba Ndraono Gizeraeli, ba tana khömi dania danö andre, dali zomasi Yehowa.', '["Yos 1:12"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 23, 'Ba na tenga si manö wolaumi, ba mosala ami ba da''ö khö Yehowa, ba mi''ila dania hadia zi göna ami, ba lalömi andrö.', '["Yos 1:12"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 24, 'Mitaru''ö khömi mbanua, nahia [wo''omomi ba nahia] ndraono sawuyu khömi, ba mifazökhi kandra mbiri-birimi ba mi''o''ö niŵa''ögu khömi.', '["Yos 1:12"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 25, 'Ba latema li Moze mado Gado ba mado Rubeno, lamane: La''o''ö niŵa''öu sawuyumö, ya''ugö Tua!', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 26, 'Iraono sawuyu khöma ba fo''omoma, ba uriföma, numalö uriföma sonora fefu, ba hana na toröi furi ba da''e, ba mbanua Gileadi andre.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 27, 'Ba ya''aga sawuyumö andre, ba ma''ötö Yoridano föna Yehowa, ba wanuwö, ha wa''ato ndra''aga, si no mangarö, si mane niŵa''öu, ya''ugö Tua.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 28, 'Ba ibe''e li Moze khö Geleazari ere ba khö Yosua, ono Nuni ba ba zatua mado Ndraono Gizeraeli, ba khöra andrö; imane khöra Moze:', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 29, 'Na no möi miyefo Yoridano mado Gado ba mado Rubeno, awömi, föna Yehowa, ba wanuwö, ha wa''ato ira, si no mangaro, ba na no mube''e barö mbawami danö, ba mibe''e khöra danö Gileadi, tana khöra ba ba nga''ötöra mitou.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 30, 'Ba na lö fao ira khömi miyefo, si no mangaro ba wanuwö, ba ba danö Gana''ana tefataro ira, ba ngaimi.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 31, 'Ba lamane mado Gado ba mado Rubeno: Hadia niŵa''ö Yehowa ba khöma, ya''aga, sawuyumö andre, ba ma''o''ö.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 32, 'Mangaro ndra''aga ba möiga miyefo ba danö Gana''ana, föna Yehowa, ena''ö lö tebulö khöma dana khöma ba zi tambai Yoridano.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 33, 'Ba ibe''e khöra Moze — ba mado Gado ba ba mado Rubeno ba ba zi matonga mado Manase, ono Yosefo — ibe''e khöra, ba amatöröŵa Zihona andrö, razo Ndraono Gamori, awö gamatöröŵa Ogi andrö, razo Mbazana, tanö andrö, fabaya banua ba danö, awö mbenuara, banua ba danö misa.[4]', '["MozV 3:12"]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 34, 'Ba mado Gado andrö, ba lafuli lataru''ö Dibona ba Ataroto ba Aroeri,', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 35, 'ba Ateroti Zofana ba Ya''ezeri ba Yogebeha,', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 36, 'ba Beti Nimera ba Beti Harana, banua saro, awö kandra mbiri-biri.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 37, 'Ba mado Rubeno, ba lafuli lataru''ö Hesibona ba Eleale ba Kiriata''i,', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 38, 'ba Nebo ba Ba''ali Meono, nifalalini töi, ba Sibema; ba banua andrö nifulira fanaru''ö, ba lafotöi si bohou.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 39, 'Ba iraono Makhiro andrö, ono Manase, ba ba Gileadi möi, ba lahalö khöra, latimba Ndraono Gamori, banua si tohöna andrö.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 40, 'Ba itehe khö Makhiro, ono Manase, Gileadi andrö Mose, ba ibali''ö banuania.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 41, 'Ba Ya''iro andrö, ono Makhiro, ba möi mu''okhögö halama soya khöra, ba ibe''e töinia halama soya khö Ya''iro.', '[]', NULL),
  (3475721, 'OT', 'Moze IV', 32, 42, 'Ba Noba andrö, ba möi mu''okhögö Genata, fabaya halama soya khöra, ba töinia Noba andrö ibe''e töi.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 1, 'Da''e döröŵa Ndraono Gizeraeli, nitöröra, me la''otarai danö Miserayi, me solohe ndra Moze A''aroni.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 2, 'Ba itanö ba zura Moze mbanua andrö si ota-otarai ira wofanö-fanö, i''o''ö niŵa''ö Yehowa; ba da''e döroŵara i''ota''otarai nahia si sambua, numalö ba zi sambua.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 3, 'Ba Ramesi la''otarai wofanö, me tuli ba mbaŵa si föföna. Sara wongi aefa wasa mangefa Ndraono Gizeraeli; no mangaro, ba zanehe Ndrawa Miserayi fefu,[1]', '["MozII 12:37","MozII 13:20"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 4, 'me lako''o-ko''o Dawa Miserayi ndraono si a''a andrö fefu, nibunu Yehowa khöra; noa sa i''oroma''ö ba Lowalangira wa''abölönia Yehowa.', '["MozII 12:37","MozII 13:20"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 5, 'Ba mangefa Ndraono Gizeraeli ba Ramesi, ba ba Zukota molombase.', '["MozII 12:37","MozII 13:20"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 6, 'Ba laheta ira ba Zukota ba ba Getama molombase, ba zinga danö si mate[2]', '["MozII 12:37","MozII 13:20"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 7, 'Ba laheta ira ba Getama ba lasaŵa Wi-Hahiroti, tanö ba gatumbukha luo i''otarai Mba''ali Zefono, ba ba Migidola molombase.[3]', '["MozII 14:2","MozII 15:23","MozII 15:27","MozII 16:1","MozII 17:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 8, 'Ba laheta ira ba Wi-Hahiroti, ba la''ötö nasi andrö, miyefo ba danö si mate, ba tölu ngaluo fofanö mowaö-waö ba danö si mate ba Getama, ba ba Mara molombase.[4]', '["MozII 14:2","MozII 15:23","MozII 15:27","MozII 16:1","MozII 17:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 9, 'Ba laheta ira ba Mara, ba larugi Gelima; ba ba Gelima andrö, ba felendrua gumbu nidanö ba fitu ngafulu nga''eu döla khorema, ba molombase ira ba da''ö.[5]', '["MozII 14:2","MozII 15:23","MozII 15:27","MozII 16:1","MozII 17:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 10, 'Ba laheta ira ba Gelima, ba ba mbewe nasi zukhu molombase.', '["MozII 14:2","MozII 15:23","MozII 15:27","MozII 16:1","MozII 17:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 11, 'Ba laheta ira ba mbewe nasi zukhu, ba ba danö si mate Sini molombase.[6]', '["MozII 14:2","MozII 15:23","MozII 15:27","MozII 16:1","MozII 17:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 12, 'Ba laheta ira ba danö si mate Sini, ba ba Dofeka molombase.', '["MozII 14:2","MozII 15:23","MozII 15:27","MozII 16:1","MozII 17:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 13, 'Ba laheta ira ba Dofeka, ba ba Galusi molombase.', '["MozII 14:2","MozII 15:23","MozII 15:27","MozII 16:1","MozII 17:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 14, 'Ba laheta ira ba Galusi, ba ba Rafidi molombase; ba lö ö zato idanö ba da''ö.[7]', '["MozII 14:2","MozII 15:23","MozII 15:27","MozII 16:1","MozII 17:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 15, 'Ba laheta ira ba Rafidi, ba ba danö si mate ba gahe hili Zina''i molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 16, 'Ba laheta ira ba danö si mate ba gahe hili Zina''i, ba ba niko''o solu''a-lu''a andrö molombase.[8]', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 17, 'Ba laheta ira ba niko''o solu''a-lu''a, ba ba Haseroti molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 18, 'Ba laheta ira ba Haseroti, ba ba Ritima molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 19, 'Ba laheta ira ba Ritima, ba ba Rimo Waresi molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 20, 'Ba laheta ira ba Rimo Waresi, ba ba Libena molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 21, 'Ba laheta ira ba Libena, ba ba Risa molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 22, 'Ba laheta ira ba Risa ba ba Gehelata molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 23, 'Ba laheta ira ba Gehelata, ba ba gahe hili Zaferi molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 24, 'Ba laheta ira ba gahe hili Zaferi, ba ba Harada molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 25, 'Ba laheta ira ba Harada, ba ba Makeloti molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 26, 'Ba laheta ira ba Makeloti, ba ba Dahata molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 27, 'Ba laheta ira ba Dahata, ba ba Dara molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 28, 'Ba laheta ira ba Dara, ba ba Mitika molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 29, 'Ba laheta ira ba Mitika, ba ba Hasimona molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 30, 'Ba laheta ira ba Hasimona, ba ba Mozeroti molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 31, 'Ba laheta ira ba Mozeroti, ba ba Mbene Ya''aka molombase.[9]', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 32, 'Ba laheta ira ba Mbene Ya''aka, ba ba Hori Hagidigada molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 33, 'Ba laheta ira ba Hori Hagidigada, ba ba Yotabata molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 34, 'Ba laheta ira ba Yotabata, ba ba Gaberona molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 35, 'Ba laheta ira ba Gaberona, ba ba Gesionogeberi molombase.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 36, 'Ba laheta ira ba Gesionogeberi, ba ba danö si mate Sini molombase, ya''ia ba Gadesi andrö.[10]', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 37, 'Ba laheta ira ba Gadesi, ba ba gahe hili Hori molombase, ba nola danö Ndraono Gedomo.', '["Faigi 11:34","MozV 10:6","Faigi 20:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 38, 'Ba möi miyaŵa ba hili Hori andrö Ga''aroni ere, niŵa''ö Yehowa, ba mate ia ba da''ö, öfa wulu fakhe dania aefa wa''aheta Ndraono Gizeraeli ba danö Miserayi; me tesa''a lö faoro ba mbaŵa si lima[11]', '["Faigi 20:25"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 39, 'No otu a dua wulu a tölu fakhe Ga''aroni, me mate ia ba hili Hori andrö.', '["Faigi 20:25"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 40, 'Ba irongo so moroi sa Ndraono Gizeraeli Dawa Gana''ana andrö, razo Garadi, ba danö Gana''ana tanö raya.[12]', '["Faigi 21:1"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 41, 'Ba laheta ira ba gahe hili Hori, ba ba Zalomona molombase.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 42, 'Ba laheta ira ba Zalomona, ba ba Wuno molombase.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 43, 'Ba laheta ira ba Wuno, ba ba Gobota molombase.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 44, 'Ba laheta ira ba Gobota, ba ba Iye Abari molombase, ba danö Ndraono Moabi.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 45, 'Ba laheta ira, ba Iye Abari, ba ba Dibona Gado molombase.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 46, 'Ba laheta ira ba Dibona Gado, ba ba Galimona Dibelata''i molombase.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 47, 'Ba laheta ira ba Galimona Dibelata''i ba ba gahe hili Gabari molombase, tanö ba gatumbukha, i''otarai Nebo.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 48, 'Ba laheta ira ba gahe hili Gabari, ba ba zalo''o tanö Ndraono Moabi molombase, ba ndraso Yoridano, ba gamaudu Yerikho.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 49, 'Ba ndraso Yoridano molombase ira, i''otarai Mbeti Hayezimota, irugi Habeli Hasili, ba zalo''o tanö Ndraono Moabi andrö.', '[]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 50, 'Ba humede Yehowa khö Moze ba zalo''o tanö Ndraono Moabi andrö, ba ndraso Yoridano ba gamaudu Yerikho, imane:', '["MozV 7:5","Yos 14:2","Sanguhuk 2:3"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 51, 'Hede ba Ndraono Gizeraeli, ba ömane khöra: Na no mi''ötö Yoridano, na no mirugi danö Gana''ana,', '["MozV 7:5","Yos 14:2","Sanguhuk 2:3"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 52, 'ba mitimba fönami fefu niha ba danö, ba adura, ba ahori mifufu: adura nifahele göi fefu mirasa, ba hili-hili andrö khöra fefu, ba midudugö.[13]', '["MozV 7:5","Yos 14:2","Sanguhuk 2:3"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 53, 'Ba mi''okhögö danöra ba ba da''ö so ami: noa sa ube''e khömi danö andrö, ena''ö ya''ami zokhö.', '["MozV 7:5","Yos 14:2","Sanguhuk 2:3"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 54, 'Ba fadahö-dahösa wamaosa tanö, sambu-sambua mado; ba zato niha, ba ebolo labe''e tana khö tanö, ba ba zambö niha, ba si öna-öna labe''e. Heza zi göna dahö-dahö khönia, da''ö tana ba zamösana; ba zi sambu-sambua mado tebe''e tana khö danö.[14]', '["MozV 7:5","Yos 14:2","Sanguhuk 2:3"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 55, 'Ba na lö mitimba fönami niha ba danö andrö, ba tobali doi ba hörömi nisaigömi andrö ba zuzumö ba ngaimi, ba lafakao dania ami ba danö andrö, ba zi so ami,[15]', '["MozV 7:5","Yos 14:2","Sanguhuk 2:3"]', NULL),
  (3475722, 'OT', 'Moze IV', 33, 56, 'ba khömi dania ufatörö zi so ba dödögu, nifatörögu khöra mena''ö.', '["MozV 7:5","Yos 14:2","Sanguhuk 2:3"]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 1, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 2, 'Be''e li ba Ndraono Gizeraeli, ömane khöra: Na mirugi danö Gana''ana andrö, ba tanömi dania da''ö, si möi khömi ba ba nga''ötömi mitou: tanö Gana''ana andrö, ma''asagörö.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 3, 'Ola tanö raya, ba i''otarai danö si mate Sini mibe''e, sangehene tanö Ndraono Gedomo; böröta nola raya tanö ba gatumbukha luo, ba balö zilua''asi nasio.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 4, 'Ba itörö raya Akerabi olami andrö, isaŵa misa Zini, ba tetohugö, irugi mbalönia, raya Gadesi Mbarenea. Ba numalö ba Hasara Adara, ba misa ba Asemona.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 5, 'Ba moroi ba Asemona, ba ituturu mbombo Miserayi andrö, irege ba mbewe nasi aetu.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 6, 'Ba ola tanö ba gaekhula luo khömi, ba asi sebua andrö; da''ö nolami tanö ba gaekhula.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 7, 'Ba olami tanö yöu, ba i''otarai nasi sebua, numalö ba hili Hori mibe''e ia;', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 8, 'ba i''otarai hili Hori, ba mirugi lala ba Hamata, ba balö nola, ba Sedadi.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 9, 'Ba itörö Ziferono, ba irugi Hasara Enana, balönia. Da''ö nolami tanö yöu.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 10, 'Ba ola tanö ba gatumbukha luo nibe''emi, ba i''otarai Hasara Enana ba isaŵa Zefama.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 11, 'Ba i''otarai Zefama, ba numalö mitou ba Haribela, tanö ba gatumbukha, i''otarai Ga''ini; ba numalö mitou na ba ihene mboto hili andrö, tanö ba gatumbukha i''otarai mbaŵa Kinereti.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 12, 'Ba numalö mitou ba mbewe Yoridano nola, irugi zilua''asi nasio, balönia. Da''ö nola danömi, fasui.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 13, 'Ba ibe''e li ba Ndraono Gizeraeli Moze, imane: Da''ö danö andrö, nifosasi khömi, tana khömi, balazi dahö-dahö, niŵa''ö Yehowa, nibe''e ba zi siŵa mado a matonga andrö.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 14, 'Ba mado Rubeno andrö, fatalifusöta andrö khöra, ba mado Gado, fatalifusöta andrö khöra, ba si matonga mado Manase, ba no latema dana khöra.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 15, 'Si dombua mado a motonga, ba yefo Yoridano tanö ba gatumbukha, ba gamaudu Yerikho no latema dana khöra.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 16, 'Ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 17, 'Da''ö döi zamaosa tanö khömi: Eleazari ere andrö ba Yosua, ono Nuni.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 18, 'Ba samö-samösa zambu-sambua mado miŵa''ö awöra, salaŵa, ba wamaosa tanö andrö.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 19, 'Ba da''ö döi da''ö: Ba mado Yuda, ba Kalebi andrö, ono Yefune.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 20, 'Ba ba mado Zimeoni, ba Samueli, ono Gamihudi.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 21, 'Ba ba mado Mbeniyami, ba Elidado, ono Giselono.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475723, 'OT', 'Moze IV', 34, 22, 'Ba salaŵa ba mado Dano, ba Buki, ono Yogelisi.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 23, 'Ba ba ndraono Yosefo andrö: salaŵa ba mado Manase, ba Hanieli, ono Gefodi.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 24, 'Ba salaŵa ba mado Geferayi, ba Kemueli, ono Zifetano.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 25, 'Ba salaŵa ba mado Zebuloni, ba Elisafa, ono Waranakhi.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 26, 'Ba salaŵa ba mado Isasari, ba Falatieli, ono Gasana.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 27, 'Ba salaŵa ba mado Gaseri, ba Ahihudi, ono Zelomi.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 28, 'Ba salaŵa ba mado Nafetali, ba Fedaheli, ono Gamihudi.', '[]', NULL),
  (3475723, 'OT', 'Moze IV', 34, 29, 'Da''ö ira, ba niŵa''ö Yehowa famaosa ba Ndraono Gizeraeli tana khöra ba danö Gana''ana andrö.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 1, 'Ba humede Yehowa khö Moze, ba zalo''o tanö Ndraono Moabi andrö, ba ndraso Yoridano, ba gamaudu Yerikho, imane:', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 2, 'Be''e li ba Ndraono Gizeraeli, ena''ö latehe banua Nono Lewi, nahiara, mbanua tana khöra ösa; ba ba mbanua andrö ba Nono Lewi, ba mifao mbenua si tefasui ya''ira, nidudura urifö.[1]', '["Yos 21:2"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 3, 'Ba banua andrö, ba nahiara, ba benua, ba ba guriföra sonoro ba ba ngawalö guriföra bö''ö.', '["Yos 21:2"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 4, 'Ba benua andrö ba zinga mbanua, nitehemi ba Nono Lewi, ba hönö hela wa''ebolo, i''otarai göli mbanua fasui, mibe''e.', '["Yos 21:2"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 5, 'Ba misu''a baero mbanua, tanö ba gatumbukha, ba 2.000 hela, ba si manö göi tanö raya, 2.000 hela, ba tanö ba gaekhula luo 2.000 hela ba tanö yöu 2.000 hela, ba dalu bakha so mbanua.', '["Yos 21:2"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 6, 'Ba ba mbanua andrö nitehemi ba Nono Lewi, ba önö mitehe banua fangorifi, ena''ö ba da''ö isaŵa woloi si no mamunu niha; ba 42 na baero ö mitehe khöra.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 7, 'Fa''oya mbanua fefu, nitehemi ba Nono Lewi, ba 48 mbanua, awö mbenua andrö, nifao ba da''ö.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 8, 'Mado Ndraono Gizeraeli sato niha, ba oya latehe banua tana khöra, ba sambö fa''ato, ba fa''onaigö; balazi wa''ebolo danö, nibe''e khöra, tana khöra, ba wamaigi ha uga mbanua, nitehe zi sambua mado ba Nono Lewi.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 9, 'Ba humede Yehowa khö Moze, imane:', '["MozII 21:13","MozV 4:41; Yos 20:7"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 10, 'Hede ba Ndraono Gizeraeli ba ömane khöra: Na no mi''ötö Yoridano, na no mirugi danö Gana''ana,', '["MozII 21:13","MozV 4:41; Yos 20:7"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 11, 'ba miŵa''ö mbanua si göna, ena''ö banua fangorifi khömi; ba da''ö yamusaŵa si no mange''e, si no manunu niha, si lö mu''odödögö.[2]', '["MozII 21:13","MozV 4:41; Yos 20:7"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 12, 'Saŵatö khömi mbanua andrö, ba zolau balö, fa böi labunu zange''e andrö, lö mu''etu''ö huku ba walukhata mbanua.', '["MozII 21:13","MozV 4:41; Yos 20:7"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 13, 'Ba banua fangorifi andrö, nitehemi, ba önö.', '["MozII 21:13","MozV 4:41; Yos 20:7"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 14, 'Tölu mitehe banua yefo Yoridano ba tölu göi ba danö Gana''ana. Banua fangorifi dania.[3]', '["MozII 21:13","MozV 4:41; Yos 20:7"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 15, 'Saŵatö mbanua andrö, si önö, he ba Ndraono Gizeraeli, ba he ba niha bö''ö, ba zi fatewu gana ba khömi, ena''ö ba da''ö lasaŵa dozi si no mamunu niha, si lö mu''odödögö.', '["MozII 21:13","MozV 4:41; Yos 20:7"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 16, 'Ba na fakake si''öli wamözinia ya''ia, wamunu ya''ia, ba no sange''e ia, ba sange''e, ba nibunu göi.[4]', '["MozII 21:12","MozV 19:11"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 17, 'Ba na no igönaisi kara, wamunu ya''ia, kara si so ba dangania mege, sikhamö famunu niha, ba no sange''e, ba nibunu göi.', '["MozII 21:12","MozV 19:11"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 18, 'Ba na no ibözi fakake eu, wamunu ya''ia, fakake si so ba dangania mege, sikhamö famunu niha, ba no sange''e ia, ba sange''e, ba nibunu göi.', '["MozII 21:12","MozV 19:11"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 19, 'Ba solau balö zamunu sange''e andrö; na fakhamö ia khönia, ba yamubunu.', '["MozII 21:12","MozV 19:11"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 20, 'Ba na no ituli''ö börö ba watiusa, ba ma na no ihaluni hadia ia, ni''odödögö, wamunu ya''ia,[5]', '["MozII 21:12","MozV 19:11"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 21, 'ba ma na igukhui, börö ba watiusa, wamunu ya''ia, ba nibunu göi zogukhui ya''ia; no sange''e; solau balö zamunu sange''e andrö, na fakhamö ia khönia.', '["MozII 21:12","MozV 19:11"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 22, 'Ba na no ituli''ö lö mu''ödödögö, lö fatiusa, ba ma na no ihaluni hadia ia, lö mu''odödögö, ma kara,', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 23, 'sikhamö famunu niha, igönaisi, wamunu ya''ia, ba na lö si fatiu dödönia khönia, na tenga tödönia wolau khönia si lö sökhi,', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 24, 'ba banua zamatunö huhuora sange''e solau balö,', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 25, 'ba ndramu''orifi zange''e andrö banua, ba zolau balö andrö; lafa''ohe''ö mangawuli ia ba mbanua andrö, nisaŵania woloi, ba wangorifi ya''ia, ba yamu''iagö da''ö, irege mate gere sebua andrö, nibayoini fanikha ni''amoni''ö.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 26, 'Ba na iheta ia ba danö mbanua andrö, nisaŵania,', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 27, 'sauri ia, ba na fakhamö khönia zolau balö, baero danö mbanua andrö, saŵatönia, ba na ibunu dania zange''e andrö solau balö, ba lö horönia.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 28, 'Sangiagö banua andrö saŵatönia sa zange''e andrö, irege mate gere sebua, ba na no mate gere sebua, ba tola mangawuli ba dana khönia zange''e andrö.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 29, 'Da''ö huku ba khömi dania, gotö-götö wa''ara dania, ba mbanuami fefu.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 30, 'Na so zamunu niha, ba nibunu zange''e andrö, balazi hadia niŵa''ö zi so ba mbörö; ba tebai tebunu niha, na ha samösa zi so ba mbörö.[6]', '["MozV 19:15"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 31, 'Ba lö tola mitema höli nosonia ba zange''e, nibunu ena''ö; nibunu sa''ae ia.', '["MozV 19:15"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 32, 'Ba lö''ö göi tola mitema höli, fa alakha lö isaŵa mbanua andrö, sauari ia, fa tola mangawuli ia, fa tola i''iagö heza ba danö, fatua lö si mate gere sebua.', '["MozV 19:15"]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 33, 'Ba böi mibe''e rai''ö danö andrö si so ami; do andrö, ba ra''iö danö ibe''e, ba lö''ö sa aheta ba danö zala andrö, ba ndro andrö, na tenga ba ndro niha andrö, same''e aduwa ya''ia.', '[]', NULL),
  (3475724, 'OT', 'Moze IV', 35, 34, 'Ba böi mibe''e ra''iö danö andrö, si so ami, si so ya''odo göi: ba hunö Ndraono Gizeraeli sa so ndra''o, ya''odo andre, Yehowa.', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 1, 'Ba so zatua nga''ötö ndraono Gileadi andrö, ono Makhiro ono Manase, nga''ötö ndraono Yosefo andrö; so niŵa''öra khö Moze ba ba zalaŵa, satua mado Ndraono Gizeraeli, lamane:', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 2, 'No iŵa''ö khöu Yehowa, ya''ugö Tua, dahö-dahö mbalazi ba wame''e ba Ndraono Gizeraeli tana khöra tanö; ba noa göi ötema goroisa khö Yehowa, ya''ugö Tua, ondröita niwama Selofadi andrö, ba öbe''e ba nononia alawe.[1]', '["Faigi 27:7; Yos 17:4"]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 3, 'Ba na mado Ndraono Gizeraeli bö''ö zangai ya''ira, ba tobali aefa ba dana khö niwama dana khöra tanö andrö, ba möi ba dana ba mado andrö sangai ya''ira, ba te''ambösi dana khöma andrö.', '["Faigi 27:7; Yos 17:4"]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 4, 'Ba irugi dania döfi wa''owua-wua dödö andrö, ba tobali tefaböbö ba dana ba mado andrö, sangai ya''ira, dana khöra, ba aheta ba dana niwama.', '["Faigi 27:7; Yos 17:4"]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 5, 'Ba ibe''e li ba Ndraono Gizeraeli Moze, dali niŵa''ö Yehowa, imane: Si ndruhu niŵa''ö nga''ötö ndraono Yosefo andrö.', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 6, 'Da''ö ni''oroi''ö Yehowa, ba ndraono Zelofadi andrö: Hana na heza zomasi ira möi nihalö ira, asala iwara zangai ya''ira,', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 7, 'fa böi tefa''ema ba mado bö''ö khöra dana ba Ndraono Gizeraeli tanö; dozi Iraono Gizeraeli, ba böi laböhöli dana ba niwara.', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 8, 'Ba dozi ono alawe sanema ondröita ba mado Ndraono Gizeraeli heza, ba ba niwara möi nihalö ira, fa böi aefa ba Ndraono Gizeraeli fefu gondröita ndra amara;', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 9, 'ba böi tefa''ema ba mado si sambua dana ba zi sambua; dozi mado Ndraono Gizeraeli, ba böi ndra muböhöli dana khöra andrö.', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 10, 'Ba ono Zelofadi andrö, ba la''o''ö niŵa''ö Yehowa khö Moze,', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 11, 'Mala andrö ba Tirisa ba Hogela ba Milika ba Noa, ba si fasamba ama khöra zangai.', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 12, 'Nga''ötö ndraono Manase andrö, ono Yosefo, zangai ya''ira, tobali lö tebulö ba madora dana khöra tanö, ba mado ndra amara.', '[]', NULL),
  (3475725, 'OT', 'Moze IV', 36, 13, 'Da''ö goroisa Yehowa, ba da''ö nifakhoinia ba zalo''o tanö Ndraono Moabi andrö, ba ndraso Yoridano, ba gamaudu Yerikho, nifaŵa''ögönia khö Moze.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 1, 'Da''e huhuo Moze yefo Yoridano, ba danö si mate, ba zalo''o tanö andrö, ba gamaudu Zufi, ba gotaluara Warana Dofeli Labano Haseroti Disahaba, huhuonia ba Ndraono Gizeraeli fefu.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 2, 'Felezara ngaluo fofanö lala ba hili Ze''ira, i''otarai hili Horebi, irugi Gadesi Mbarenea.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 3, 'Ba ba ndröfi si öfa wulu, me tesa''a lö faoro, ba mbaŵa si felezara, ba i''ombakha''ö ba Ndraono Gizeraeli Moze fefu hadia ia ni''oroi''ö Yehowa khönia, niŵa''ö khöra,', '["MozIV 21:24"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 4, 'me no aefa i''alani razo Ndraono Gamori andrö, Sihona, ba Hesibona, ba Ogi andrö, razo Mbazana, ba Gasaroto, ba zinga Gedera no andrö.[1]', '["MozIV 21:24"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 5, 'Yefo Yoridano, ba danö Ndraono Moabi, ibörötaigö Moze ibotokhi khöra goroisa andrö,', '["MozI 15:18"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 6, 'imane: No imane khöda Lowalangida Yehowa, ba gahe hili Horebi no: Noa wa''arami ba gahe hili andre,', '["MozI 15:18"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 7, 'mifazaŵa ami ba midölö ami ba hili Ndraono Gamori andrö ba ba zi faola tanö khöra, ba zalo''o tanö, ba ba hili ba ba ndraso ba tanö raya ba ba mbewe nasi, ba danö Ndrawa Gana''ana ba ba hili Libano ba irugi nidanö sebua andrö, Oiferati.', '["MozI 15:18"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 8, 'Tanö da''ö ube''e sa''ae khömi, misaŵa ia, ba mi''okhögö, si no möi ba hölu Yehowa khö ndra tuami Aberahamo, Iza''aki, Yakobo, ba wame''e khöra ba ba ma''uwura mitou.[2]', '["MozI 15:18"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 9, 'Ba me luo da''ö, ba no umane khömi: Tebai utaha, na ha ya''o zi onoro tödö ya''ami.[3]', '["MozII 18:18 MozIV 11:12"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 10, 'No ato sibai ami ibe''e Lowalangimi Yehowa, fa''oya ndröfi ba mbanua sa''ae ami ma''ökhö.', '["MozII 18:18 MozIV 11:12"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 11, 'Ba yamube''e Lowalangi ndra tuami, Yehowa, mehönö wa''atomi andrö tedou ami, ba yamufahowu''ö ami, si mane nifabu''unia!', '["MozII 18:18 MozIV 11:12"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 12, 'Ba hadia, tola utaha wamakao andrö khömi ba fa''abu dödö ba huhuo andrö fefu khömi, na ha ya''odo?', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 13, 'Mi''ohe khögu niha satua-tua, si sökhi turia, dozi mado, ena''ö ufataro satuami.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 14, 'Ba no mitema ligu, no mimane: Si sökhi niŵa''ömö andrö!', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 15, 'Ba uhalö högö mado andrö khömi, niha satua-tua, si sökhi turia, ba ufataro satuami, högö zi hönö ba högö zi otu ba högö zi lima wulu ba högö zi dafulu, kumandru ba madomi andrö.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 16, 'Ba me luo da''ö, ba ube''e li ba zanguhuku ya''ami andrö, umane: Misekhegö niwami andrö, ba mi''atulö''ö wanguhuku, he na so nifadönira ba niwara, ba he na ba niha bö''ö.', '["MozIII 19:15; Nga''ötII 19:6; MozII 18:22"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 17, 'Böi ebua dödömi zambuana, ba wanguhuku hadia ia; faoma mifondrondrongo niŵa''öra, he si numana, ba he sebua töi! Böi mi''ata''ufi niha; khö Lowalangi sa wanguhuku. Ba na so huhuo si tebai mi''asiwai, ba mi''ohe khögu, ena''ö usekhegö ira.[4]', '["MozIII 19:15; Nga''ötII 19:6; MozII 18:22"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 18, 'Si manö wame''egu li khömi, me luo da''ö, ba halöŵömi andrö fefu.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 19, 'Ba me aefa da''ö ba tafazaŵa ita ba gahe hili Horebi andrö, ba tatörö danö si mate andrö sebolo sibai ba sata''u ita, ma''asagörö, dali goroisa Lowalangida, Yehowa, tasaŵa hili Ndraono Gamori andrö. Ba me no tarugi Gadesi Mbarenea, ba umane khömi:', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 20, 'Ba no mirugi hili Ndraono Gamori andrö, nibe''e Lowalangida, Yehowa khöda.', '["MozIV 13:3"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 21, 'Hiza, noa sa''ae ibe''e ba dangau danö andrö Lowalangiu, Yehowa; ba ae okhögö, o''ö niŵa''ö Lowalangi ndra tuau andrö, Yehowa, khöu. Böi ata''u ndra''ugö, ba böi abu dödöu!', '["MozIV 13:3"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 22, 'Ba mi''ondrasido, dozi ami, ba nimane: Da tafowaö-waö ösa, ba wamauze tanö andrö khöda, ba ena''ö la''ombakha''ö khöda lala, lalada miyaŵa, ba he wisa mbanua andrö, nirugida dania.[5]', '["MozIV 13:3"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 23, 'Ba me si sökhi da''ö uŵa''ö, ba ututuyu niha ba khömi, felendrua, samösa zambua mado.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 24, 'Ba ladölö ira miyawa ba hili da''ö, larugi ndraso Esikoli ba lafauzei danö.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 25, 'Ba lahalö göi ösa mbua danö, la''ohe khöda, mitou. Ba la''ombakha''ö khöda, lamane: Tanö andrö, nibe''e Lowalangida, Yehowa, khöda, ba no si sökhi.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 26, 'Ba lö edöna ami möi misi yaŵa, ba mitandro niŵa''ö Lowalangimi, Yehowa.', '["Faigi 9:2"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 27, 'Mukökö-kökö ami baose khömi, mimane: Fatiusa Yehowa khöda, wa no iheta ita ba danö Miserayi, ba wame''e ba danga Ndraono Gamori andrö ya''ita, ena''ö lahori ita.', '["Faigi 9:2"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 28, 'Ba heza atö tasaŵa! Iwada andrö zame''e atalö dödöda, wanguma''ö: Sebua niha ira, salaŵa moroi khöda, ba banua, ba no sebua sibai, irugi mbanua si yaŵa fa''alaŵa göli, ba ma''uwu Genaki na''i ma''ila ba da''ö.[6]', '["Faigi 9:2"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 29, 'Ba umane khömi: Böi muhokha mbumi ba böi mi''ata''ufi ira!', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 30, 'Si fasöndra salahimi dania Lowalangimi, Yehowa, sowaö-waö fönami, si mane me itolo ami ba danö Miserayi no, si no anehe ita,', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 31, 'ba si mane ba danö si mate, ni''ila höröu, nilu''i Lowalangimö, Yehowa, ya''ugö, nifolu''i niha ononia, ma''asara lala andrö, nitörömi, irege ofeta ami ba da''e.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 32, 'Ba lö lai da''ö fefu, ba lö fanötönami khö Yehowa,', '["MozII 13:21"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 33, 'Lowalangimi, sowaö-waö fönami ba lala, ba wamaigi olombaseŵa khömi: ba zi bongi, ba ba galitö, ena''ö oroma khömi lala nitörömi, ba na ma''ökhö ba ba lawuo.[7]', '["MozII 13:21"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 34, 'Ba me irongo wehedemi andrö Yehowa, ba mofönu ia, fahölu ia, imane:', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 35, 'Ba niha andrö, niha si lö sökhi, ba samösa lö sangila dania tanö si sökhi andrö, nifabu''ugu khö ndra tuami fahölusa.[8]', '["MozIV 14:23"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 36, 'Ha Kalebi andrö, ono Yefune, zangila dania; khönia ba ba ndraononia ube''e dania danö andrö, si no möi ia, me no a''oi dödönia wolo''ö khö Yehowa.', '["MozIV 14:23"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 37, 'Khögu göi mofönu Yehowa, börö ami, tobali imane: Ba ya''ugö göi, ba lö örugi[9]', '["MozIV 20:12","MozIV 14:31"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 38, 'Yosua andrö, ono Nuni, si lö aefa-aefa ngoni-ngoniu, da''ö zondrugi dania; abe''e''ö dödönia, ya''ia dania zamaosa ba Ndraono Gizeraeli [tanö andrö].', '["MozIV 20:12","MozIV 14:31"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 39, 'Ba iraonomi andrö, niŵa''ömi, ö nemali dania! onomi matua, si lö mangila na ma''ökhö hadia zi sökhi ba hadia zi lö sökhi, da''ö dania zondrugi; khöra ube''e [danö] ba ya''ira zi okhögö.[10]', '["MozIV 20:12","MozIV 14:31"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 40, 'Ba ya''ami andrö, ba mifuli ami, mifazaŵa ami ba misaŵa danö si mate andrö, lala ba nasi zukhu mitörö!', '["MozIV 20:12","MozIV 14:31"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 41, 'Ba mitema ligu, mimane khögu: Horöma khö Yehowa da''ö; da möiga miyaŵa manuwö, ma''o''ö manö niŵa''ö Lowalangida Yehowa khöda! Ba mangaro ami fefu, ba möi ami miyaŵa ba hili, sambö era-era.[11]', '["MozIV 14:40"]', NULL),
  (3399635, 'OT', 'Moze V', 1, 42, 'Ba imane khögu Yehowa: Ömane khöra: Böi mi''ae miyaŵa, böi manuwö, lö''ö sa fao ndra''o khömi; fa böi te''ala ami ba nemalimi andrö!', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 43, 'Ba uŵa''ö khömi, ba lö mifondrondrongo, mitandro manö niŵa''ö Yehowa, mi''abe''e''ö manö dödömi, we''amöi miyaŵa ba hili.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 44, 'Ba faondra khömi Ndraono Gamori ba hili andrö, ba lagohi ami, hulö ŵani, ba lafazawili ami ba Ze''ira, irugi Horema.', '[]', NULL),
  (3399635, 'OT', 'Moze V', 1, 45, 'Ba me no mangawuli ami, ba mangarö-ngarö ami khö Yehowa, ba i''osilömilagö wangarö-ngarömi Yehowa,', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3399635, 'OT', 'Moze V', 1, 46, 'i''osilömurongogö. Ba ara ami ba Gadesi, ha wa''ara we''asomi ba da''ö.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 1, 'Ba tafuli ita, tasaŵa danö si mate, lala ba nasi zukhu tatörö, dali niŵa''ö Yehowa khöda.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 2, 'ba imane khögu Yehowa:', '["MozIV 21:4","MozI 36:8"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 3, 'Noa sa''ae wa''ara wamasuimi hili andrö, miyöu sa''ae misaŵa.', '["MozIV 21:4","MozI 36:8"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 4, 'Ba öbe''e li ba zato, ömane: So fönami wanörö tanö dalifusömi andrö, tanö ndraono Gezau ba Ze''ira, ba ata''u ira ami dania;', '["MozIV 21:4","MozI 36:8"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 5, 'ba mi''angelama sibai, fa böi misuwö ira, samba lahe sa lö ube''e khömi tanöra; hili Ze''ira andrö, ba noa sa utehe khö Gezau, tana khönia ba ba nga''ötönia.[2]', '["MozIV 21:4","MozI 36:8"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 6, 'Ömi, ba mi''öli khöra, mibe''e gana''a, soguna ömi; ba ömi idanö, ba mi''öli göi khöra.', '["MozIV 21:4","MozI 36:8"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 7, 'Noa sa ato ifahowu''ö ndra''ugö Lowalangiu Yehowa, ba nilaumö, fefu; no irorogö ndra''ugö ba wanöröu tanö si mate andre, si no ebolo sibai: öfa wulu fakhe iada''e zi no fao-fao khöu Lowalangiu Yehowa; lö hadia ia zambö khöu.', '["MozIV 21:4","MozI 36:8"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 8, 'Ba me taröi dalifusöda andrö, iraono Gezau, ba Ze''ira, wanörö lala ba danö si mate, moroi ba Gelata ba ba Gesionogeberi, ba tadölö ita ba danö si mate andrö, tanö Ndraono Moabi.', '["Faigi 9:2","Nga''ötI 20:4"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 9, 'Ba imane khögu Yehowa: Böi suwö Ndraono Moabi andrö, böi fasuwö ami; ma''ifu sa lö ube''e khöu tanöra, me no utehe tana ba nga''ötö Loti andrö Gari andrö.', '["Faigi 9:2","Nga''ötI 20:4"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 10, '(Meföna, ba Dawa Gemi zi so ba danö andrö, niha sebua sibai, ba si no ato, salaŵa boto, timba nga''ötö Genaki andrö.[3]', '["Faigi 9:2","Nga''ötI 20:4"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 11, 'Dawa Refa''i göi ira, si mane nga''ötö Genaki andrö, ba töira ba Ndraono Moabi, ba Dawa Gemi.[4]', '["Faigi 9:2","Nga''ötI 20:4"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 12, 'Ba sowanua ba Ze''ira meföna, ba Dawa Hori, ba latimba da''ö iraono Gezau ba lahori, ba fangalira ba danö, ba ya''ia ndraono Gezau andrö; nifolau Ndraono Gizeraeli ba danö andrö, nibe''e Yehowa tana khöra).', '["Faigi 9:2","Nga''ötI 20:4"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 13, 'Ba mifazaŵa sa''ae ami ba mi''ötö mbombo Saredi andrö! Ba ta''ötö mbombo Saredi.', '["MozIV 14:29"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 14, 'Tölu ngafulu a ŵalu fakhe ita ba lala, i''otarai Gadesi Mbarenea, irugi wangötöda mbombo Saredi andrö, irege no ahori mate ba golombaseŵa zi sagötö niha andrö, sabölö andrö, itörö niŵa ö Yehowa khöra, si no möi ba hölu ia.[5]', '["MozIV 14:29"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 15, 'Udura na göi danga Yehowa, ba wangohori ya''ira ba golombaseŵa, irege samösa lö si tosai.', '["MozIV 14:29"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 16, 'Dozi solohe baluse ba khöra, ba no mate.', '["MozIV 14:29"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 17, 'Ba humede khögu Yehowa, imane:', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 18, '"Ötörö iada''e danö Ndraono Moabi, Ari andrö;', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 19, 'ba ahatö sibai dania ndra''ugö ba Ndraono Gamoni andrö; böi suwö ira, böi fa''udu ami! Ma''ifu sa lö ube''e khöu tanö Ndraono Gamoni, me no utehe tana ba ma''uwu Loti andrö mitou."', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 20, 'Ya''ia göi, ba tanö Ndrawa Refa''i laŵa''ö; meföna, ba Dawa Refa''i zi so ba danö; Dawa Zamisumi labe''e töira Iraono Gamoni.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 21, 'Niha sebua sibai ba sato, salaŵa boto, si mane nga''ötö Genaki andrö. Ba no ihori ira fönara Yehowa, tobali Iraono Gamoni zi okhögö tanö, la''iagö fangalira,', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 22, 'irege ma''ökhö andre, nifolaunia ba ndraono Gezau, ba Ze''ira, wangohori fönara Dawa Hori andrö, wa tobali la''okhögö danö, ba la''iagö fangalira, irege ma''ökhö andre.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 23, 'Ba Dawa Gawi andrö göi, si fahalama, irugi tanö ba Gasa, ba Dawa Gafatori, si otarai Gafatori, zangohori, ba la''iagö danö, fangalira.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 24, 'Ba mifazaŵa ami ba mi''ötö Garono. Hiza, ube''e ba dangau Ndraono Gamori andrö, Sihona, razo ba Hesibona, fabaya tanönia; börötaigö okhögö [danö] ba suwö ia!', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 25, 'I''otarai da''e, ba uhawui fa''ata''u ba fehokha mbu ba khöu andrö fefu soi ba guli danö, fefu gofu heza: ha larongo ndra''ugö, ba manizi-nizi ba mogikhi dödö ba khömö andrö."', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 26, 'Ba ufatenge zinenge khö Zihona andrö, razo ba Hesibona, moroi ba danö si mate Kedemoti, huhuo nihaogö u''oroi''ö, umane:', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 27, 'Omasido utörö danöu, ba ha sambalö lala sebua utörö, lö uhole''ö ndra''odo, he ba gambölö, ba he ba gabera.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 28, 'Öma, fa böi olofo ndra''aga, ba ö''amawa khöma, mabe''e gana''a, ba ba göma idanö, ba mabe''e khöu mböli. Ha lala barö gahegu, ba wanörö, u''andrö, —', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 29, 'noa göi latehe khögu da''ö iraono Gezau, ba Ze''ira, ba Iraono Moabi, ba Gari, — irege u''ötö Yoridano, miyefo, ba danö andrö, nibe''e Lowalangima, Yehowa, khöma dania.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 30, 'Ba lö edöna Zihona, razo ba Hesibona, itehe khöda wanörö, me no tebai alulu gera-erania ba no abe''e dödönia ibe''e Lowalangiu, Yehowa, ena''ö ibe''e ba dangau ia, si no alua ma''ökhö.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 31, 'Ba imane khögu Yehowa: Hiza, noa sa''ae ube''e ba dangau Zihona andrö, fabaya tanönia, ba börötaigö okhögö, wangai khömi tanönia.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 32, 'Ba me ifaondragö ita Sihona, awö zabölö khönia fefu, me möi fasöndra khöda ba zinga Yahasi,[6]', '["MozIV 21:23"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 33, 'ba ibe''e ba dangada ia Lowalangida, Yehowa, tobali ta''alani ia, awö nononia, awö zabölö andrö khönia fefu.', '["MozIV 21:23"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 34, 'Ba atu''a ita ba mbanuania fefu, me luo da''ö, ba dozi banua, ba talakha''ö, he ira matua, ba he ira alawe, ba he iraono; samösa lö ta''orifi.', '["MozIV 21:23"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 35, 'Ha urifö andrö ba hadia nihalöda ba mbanua andrö, si no atu''a ita, ba tahalö khöda ahuluada.', '["MozIV 21:23"]', NULL),
  (3400490, 'OT', 'Moze V', 2, 36, 'I''otarai Garoeri, ba mbewe Garono ba i''otarai mbanua ba ndraso andrö, numalö ba Gileadi, ba lö banua saro, si no töra fa''alaŵa khöda mena''ö; ahori ibe''e ba dangada Lowalangida, Yehowa.', '[]', NULL),
  (3400490, 'OT', 'Moze V', 2, 37, 'Ha tanö Ndraono Gamoni andrö, ba lö öbabaya, fefu, tanö ba Yaboko, ba banua ba hili andrö, ba hadia ia fefu, nitenaŵa Lowalangida, Yehowa, ya''ita.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 1, 'Ba me tasaŵa Mbazana, ba ifaondragö ita Ogi andrö, razo Mbazana, awö zabölö andrö khönia fefu, möi fasöndra khöda ba zinga Gederai andrö.[1]', '["MozIV 21:33"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 2, 'Ba imane khögu Yehowa: Böi ata''ufi ia! Ube''e sa ba dangau ia, fabaya banuania fefu ba tanönia, ba hana na ölau khönia nilaumö khö Zihona andrö, razo Ndraono Gamori, ba Hesibona.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 3, 'Ba ibe''e ba dangada göi Ogi andrö, razo Mbazana, Lowalangida, Yehowa, fabaya sabölö andrö khönia, fefu, ba tobali ta''alani sibai ia, irege samösa lö si tosai khönia, soloi mena''ö.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 4, 'Ba me luo da''ö, ba atu''a ita ba mbanuania fefu; sambua lö''ö sa''ae banua saro, si lö tahalö khöda: önö ngafulu mbanua, tanö Garigobi andrö ma''asagörö, amatöröŵa Ogi andrö ba Mbazana, fefu, —', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 5, 'oi banua saro: öli, ba no alaŵa ba lagö mbawa göli, ba nilazi, — ba baero ö, ba oya na mbanua ba danö, si lö mu''aro''ö.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 6, 'Ba talakha''ö, si mane mege, khö Zihona andrö, razo ba Hesibona, dozi banua, ba tahori, he ira matua ba he ira alawe, fabaya iraono;', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 7, 'ba urifö fefu ba hadia nirabuda ba mbanua andrö ba tahalö khöda ahuluada.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 8, 'Ba ta''okhögö danö andrö, me luo da''ö, tanö razo Ndraono Gamori andrö, si darua, yefo Yoridano, i''ötarai Garono, irugi hili Heremono,', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 9, '— töi hili Heremono andrö ba mbanua Zidona, ba Siriono, ba töinia ba Ndraono Gamori, ba Seniri, —', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 10, 'banua ba ndraso andrö fefu, sagörö tanö Gileadi ba Bazana fefu, irugi Zalikha ba Ederai, banua ba gamatöröŵa Ogi andrö, ba Mbazana.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 11, 'Ogi andrö, razo Mbazana, ba angohorita zi tosai Dawa Refa''i andrö; faratenia si''öli, ba so na ma''ökhö ba Rabata Ndraono Gamoni; siŵa hela wa''anau ba öfa hela wa''ebolo, hela nisi''ugö.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 12, 'Tanö da''ö ta''okhögö, me luo da''ö, I''otarai Garoeri andrö, ba mbewe Garono ube''e ba mado Gado, awö zi matonga hili Gileadi andrö, fabaya banua ba da''ö.[2]', '["MozIV 32:33"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 13, 'Ba ba zi matonga mado Manase, ba ube''e zi tosai tanö Gileadi ba tanö Mbazana ma''afefu, amatöröŵa Ogi andrö, tanö Garigobi andrö fefu; ba tanö Mbazana andrö, ma''asagörö, ba ya''ia nifotöi tanö Ndrawa Refa''i.', '["MozIV 32:33"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 14, 'Ba Ya''iro andrö, ma''uwu Manase, ba no ibe''e barö nibawania danö Garigobi andrö ma''afefu, irugi nola Ndrawa Gesuri ba ola Ndrawa Ma''akhati, ba no ibe''e töi danö Mbazana andrö mbanua Ya''iro, — i''ohia''ö döinia — irugi ma''ökhö andre.[3]', '["MozIV 32:41"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 15, 'Ba khö Makhiro ube''e Gileadi.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 16, 'Ba ba mado Rubeno ba ba mado Gado, ba i''otarai Gileadi, numalö ba mbewe Garono, irugi dalu ndraso andrö ba nola, irugi Yakobo, ola Ndraono Gamoni.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 17, 'Ba tanö salo''o andrö, ola Yoridano, i''otarai mbaŵa Kinereti, irugi zilua''asi ba zalo''o tanö andrö, silua''asi nasio, ba gahe hili Wisiga; tanö ba gatumbukha luo.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 18, 'Ba no ube''e li khömi, me luo da''ö, no umane: No ibe''e okhötami danö andre Lowalangimi, Yehowa, ba ya''ami, ba mi''aro''ö ami, dozi ami, solohe baluse, ba mi''iagö föna dalifusömi Iraono Gizeraeli, —', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 19, 'ha fo''omomi ba iraonomi ba urifömi (u''ila wa no oya gurifömi) zahono ba mbanua andrö, nitehegu khömi —', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 20, 'irege ahono dalifusömi, si mane ya''ami, ibe''e Yehowa, ba irege no la''okhögö danö andrö, nibe''e Lowalangimi, Yehowa, khöra, yefo Yoridano. Ba awena dania mangawuli ami, isaŵa dana khönia zamösana, tanö nitehegu khömi.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 21, 'Ba ube''e li khö Yosua, me luo da''ö, umane: No anehe ndra''ugö fefu hadia ia nifatörö Lowalangimi, Yehowa, ba razo andrö si darua, no höröu zangila; si manö dania ilau Yehowa ba zalaŵa andrö fefu, si yefo, ba zi möi ndra''ugö dania.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 22, 'Alakha lö ö''ata''ufi ira; Lowalangimi, Yehowa, sa''ae zi fasöndra salahimi.', '[]', NULL),
  (3402367, 'OT', 'Moze V', 3, 23, 'Ba mangandrö göi ndra''o khö Yehowa, me luo da''ö, u''andrö wa''ahakhö dödö, umane:', '["Sin 89:7"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 24, 'He So''aya, Yehowa, noa sa''ae ö''oroma''ö khö genoniu andre wa''asalaŵamö ba fa''abe''e dangau; heza so Lowalangi bö''ö, he ba zorugo, ba he ba guli danö, sangila molau si manö, nifolau zabölö, si mane ya''ugö andrö?[4]', '["Sin 89:7"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 25, 'Fa''amöido miyefo, ena''ö i''ila hörögu danö si sökhi andrö, yefo Yoridano hili si sökhi andrö ba hili Libano!', '["Sin 89:7"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 26, 'Ba mofönu khögu Yehowa, börö ba khömi, ba lö i''o''ö khögu; imane sa khögu Yehowa: Noa manö da''ö! Böi sa''ae hede-hede khögu ba da''ö![5]', '["MozIV 20:12","MozIV 27:12"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 27, 'Ae miyaŵa ba zuzu hili Wisiga ba fakhölö''ö misa ba gaekhula luo ba miyöu ba miraya ba ba gatumbukha luo, ena''ö i''ila höröu; Yoridano andrö, ba lö''ö sa ö''ötö.[6]', '["MozIV 20:12","MozIV 27:12"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 28, 'Ba khö Yosua, ba öbe''e li, farou dödönia ba abe''e''ö; ya''ia sa zolohe miyefo ya''ira andre, ba ya''ia zamaosa khöra tanö andrö, ni''ila höröu.', '["MozIV 20:12","MozIV 27:12"]', NULL),
  (3402367, 'OT', 'Moze V', 3, 29, 'Ba ta''iagö ndraso andrö, ba gamaudu Mbeti-Weoro.', '["MozIV 20:12","MozIV 27:12"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 1, 'Ba iya''e, ba mifondrondrongo gamakhoita andrö, awö huku andrö ba nifahaögu ya''ami, ya''ami Iraono Gizeraeli, ena''ö mi''o''ö ia ba ena''ö auri ami ba ena''ö möi khömi danö andrö, nibe''e Yehowa, Lowalangi ndra tuami andrö, khömi dania.', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 2, 'Oroisa andrö, nifa''emagu khömi, ba böi midou''ö ba böi miwuwu; oroisa andrö, nibe''e Lowalangimi, Yehowa, nifa''emagu khömi, ba mi''o''ö.[1]', '["Faigi 12:32"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 3, 'No hörömi zangila nilau Lowalangi, börö Mba''ali-Weoro andrö: dozi si olembai Ba''ali-Weoro andrö, ba no ihori ba hunömi Lowalangiu Yehowa,[2]', '["MozIV 25:4"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 4, 'ba ya''ami andrö, si lö faröi, si lö mamöhöi Lowalangimi Yehowa, ba ahori auri, irege ma''ökhö andre.', '["MozIV 25:4"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 5, 'Hiza, no ufahaö ami ba gamakhoita ba ba huku, dali niŵa''ö Lowalangiu, Yehowa, khögu, ena''ö mi''o''ö dania ba da''ö, ba danö andrö, ba zi möi ami, ba wangokhögö ya''ia.', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 6, 'Mitöngöni ba mi''o''ö! Da''ö sa dania wa''atua-tuami ba fa''onekhemi wamaigi niha baero; na larongo dania gamakhoita andrö fefu, ba lamane: Si ndruhu, soi satua-tua ba sonekhe soi sebua andrö!', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 7, 'Heza atö so soi sebua si so Lowalangi, si no si manö fa''ahatö khöra, si mane Lowalangida, Yehowa [khöda], ero na ta''angaröfi li ia?', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 8, 'Ba heza so soi sebua, si no si manö fa''amo''ahonoa amakhoita, awö huku, si mane oroisa andrö fefu, ni''ombakha''ögu khömi ma''ökhö?', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 9, 'Ba angelama ba faigi-faigi, fa böi olifu''ö ngawalö andrö ni''ila höröu, ba fa böi aefa ba dödöu, götö wa''anau nosou; ö''ombakha''ö ba ndraonou ba ba ma''uwumö.[3]', '["Faigi 6:7"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 10, 'Baŵa andrö, me so''ö föna Lowalangiu Yehowa, ba gahe hili Horebi andrö, me imane khögu Yehowa: Falukha''ö khögu zato! Da''ufarongogö khöra daroma ligu andrö, ena''ö lafamaha ira ba wangata''ufi ya''odo, götö wa''anau nosora ba guli danö ba ena''ö lafahaö göi ndraonora.', '["Faigi 6:7"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 11, 'Ba mi''ondrasi, mi''iagö gahe hili; ba humola-hola hili andrö, irugi mbanua si yaŵa, ba [baero ö, ba] fa''ogömi-gömi ba lawuo ba salu.[4]', '["MozII 19:16"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 12, 'Humede khömi Yehowa moroi ba dalu galitö; linia, ba mirongo, ha li, ba lö soroma khömi nga''eu.', '["MozII 19:16"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 13, 'I''ombakha''ö khömi wawu''usa li andrö khönia, niŵa''önia khömi folo''ö, taroma li si fulu andrö, ba isura ba gara wanura si dombua.', '["MozII 19:16"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 14, 'Ba khögu iŵa''ö Yehowa, me luo da''ö, wamahaö ya''ami ba gamakhoita andrö ba ba huku andrö, ena''ö mi''o''ö ba danö andrö, si möi ami miyefo, ba wangokhögö ya''ia.', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 15, 'Ba mifaigi sibai — nosomi mbalazi — me no lö ni''ilami hadia ia nga''eu, me luo humede khömi Yehowa moroi ba galitö, ba gahe hili Horebi,', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 16, 'fa böi miwöwöi wamakiko, wamazökhi khömi adu nifoe, hadia ia wamaedo, he nga''eu ndra matua, ba he nga''eu ndra alawe,', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 17, 'ba he nga''eu zaliŵa-liŵa ba danö, hadia ia, si öfa ahe, ba he nga''eu wofo so''afi, sihombo ba dalu mbanua,', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 18, 'ba he nga''eu zanana ba danö, ba he nga''eu gi''a, si so ba nidanö barö danö.', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 19, 'Ba na öfakhölö''ö miyaŵa ba mbanua, na öfaigi-faigi luo ba baŵa ba döfi, ngahönö andrö fefu ba mbanua si yaŵa, ba fa böi elungu''ö, wangalulu khönia, awö wamosumange ya''ia, me no ibe''e ba soi niha bö''ö fefu, ba guli danö misa Lowalangiu, Yehowa.[5]', '["Faigi 29:26"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 20, 'Ba ya''ami, ba no nihalö Yehowa khönia, no iheta ami ba galitö famahele zi''öli andrö, ba danö Miserayi, ena''ö soi tana khönia ami, si mane ma''ökhö.[6]', '["MozII 19:5"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 21, 'Ba khögu, ba no mofönu Yehowa, börö ba khömi, irege tobali fahölu ia, lö tola u''ötö Yoridano, ba lö tola uhundragö danö si sökhi andrö, nibe''e Lowalangiu, Yehowa, khöu.[7]', '["MozIV 20:12"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 22, 'Ba danö andre mate ndra''o iŵa''ö, lö u''ötö Yoridano, ba ya''ami ba mi''ötö ba wangokhögö tanö si sökhi andrö.', '["MozIV 20:12"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 23, 'Mifaigi sibai, fa böi olifu ami wawu''usa li andrö, me no fawu''u li khömi Lowalangimi, Yehowa, ba fa böi mifazökhi khömi nadu, famaedo hadia ia, nitenaŵa Lowalangiu, Yehowa, ya''ugö.', '["Heb 12:28","Faigi 30:19"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 24, 'Alitö si manga-manga hadia ia sa Lowalangiu andrö, Yehowa, no Lowalangi solohu.[8]', '["Heb 12:28","Faigi 30:19"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 25, 'Ba na miwöwöi wamakikomi, na no mo''ono ndra''ugö ba na no tumbu ma''uwumö, na no ara ami ba danö, na mifazökhi khömi nadu, famaedo hadia ia, wamazökhi horö khö Lowalangimi, Yehowa, na tobali mofönu ia,', '["Heb 12:28","Faigi 30:19"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 26, 'ba ukaoni si so ba mbörö ba khömi andrö mbanua si yaŵa ba tanö tou, ma''ökhö andre, wa lö arara dania, ba tehori ami ba danö andrö, ba zi möi ami dania, miyefo Yoridano, ba wangokhögö ya''ia, lö''ö sa ara dania ami ba danö; nise''e ami.[9]', '["Heb 12:28","Faigi 30:19"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 27, 'Ba niha baero ifazawili ami Yehowa; lö''ö sa atoto dania ami, si tosai, ba mbanua niha baero andrö, ba ni''oloi''ö Yehowa ya''ami dania.[10]', '["Faigi 28:62","Sin 115:4; 135:15"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 28, 'Lowalangi nifazökhi danga niha dania mifosumange ba da''ö, eu ba kara, si lö mangila niha ba si lö mamondrongo li niha, ba si lö manga ba si lö mangago hua hadia ia.[11]', '["Faigi 28:62","Sin 115:4; 135:15"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 29, 'Ba ba da''ö dania ö''alui Lowalangimö, Yehowa, ba ösöndra, na moroi si''aikö ba dödöu ba na moroi si''aikö ba gera-erau fefu wehulu dödöu khönia.[12]', '["Faigi 30:2; Yer 29:13"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 30, 'Ba ba wa''abu dödöu andrö dania, na no göna ndra''ugö da''ö fefu, ba ba gafuriata, ba öfalalini gera-erau, öfuli''ö khö Lowalangiu, Yehowa, ba öfondrondrongo linia.', '["Faigi 30:2; Yer 29:13"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 31, 'Me no Lowalangi sahakhö tödö Lowalangimö andrö, Yehowa, lö iböhöli ndra''ugö, ba lö omasi ia tekiko ndra''ugö, ba lö olifu ia wawu''usa li andrö, me fawu''u li ia khö ndra tuau mege, si no möi ba hölu ia khöra.', '["Faigi 30:2; Yer 29:13"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 32, 'Sofu atö, he wisa ba götö föna, me lö ya''ugö na, i''otarai luo andrö, me ifazökhi niha ba guli danö Lowalangi; sofu, i''otarai wondrege danö, numalö ba wondrege tanö sa, na no irai itörö si manö fa''ebua, na no murai murongo zi manö!', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 33, 'Na so na soi bö''ö, si no irai mamondrongo fehede Lowalangi, si oroi ba galitö, si mane nirongou, ba na lö si mate ira.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3405105, 'OT', 'Moze V', 4, 34, 'Ma na no so Lowalangi bö''ö, si no manandraigö fe''amöi, ba wangoroma''ö fa''abölö ba ba wolau tandra ba ila-ila ba fanuwö, ba wangai khönia sambua soi ba hunö mbö''ö, tangania sabe''e ba ta''ionia ni''oro''ö, ba ba wa''abölönia sahöli-höli dödöda; nifolau Lowalangimö andrö, Yehowa, khömi, ba danö Miserayi, ba zanehe ami mege!', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 35, 'Höröu mege zangila, ena''ö aboto ba dödöu, wa no Yehowa Lowalangi, awö wa lö Lowalangi baeronia.[13]', '["Faigi 6:4; Nga''ötI 17:20"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 36, 'Moroi ba zorugo ifarongogö khöu linia ba wamobawa lala khöu, ba ba guli danö i''oroma''ö khöu galitö sebua andrö khönia, ba moroi ba galitö andrö örongo mege daroma linia.', '["Faigi 6:4; Nga''ötI 17:20"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 37, 'Ba me no i''omasi''ö ndra tuau ba me no ituyu ma''uwura furira, ba me no ya''ia zangeheta ya''ugö ba danö Miserayi, ba wa''abölönia andrö, si tenga inötö;[14]', '["MozII 33:14"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 38, 'tödönia, itimba fönau soi sebua moroi khöu ba sabölö moroi khöu, ena''ö ya''ugö i''ohe ba danö ba ena''ö khöu ibe''e,', '["MozII 33:14"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 39, 'okhötamö, si mane ma''ökhö, ba ya''aboto sa''ae ba dödöu, ba ötanö ba dödöu, wa no Yehowa Lowalangi ba zorugo yaŵa ba ba guli danö tou, awö wa lö Lowalangi baeronia.', '["MozII 33:14"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 40, 'Ba ö''o''ö nifakhoinia andrö ba oroisania, nifa''emagu khöu ma''ökhö, ena''ö sohahau tödö ndra''ugö, fabaya iraonou furiu dania, ba ena''ö lö tebulö wa''anau nosou ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu dania.', '[]', NULL),
  (3405105, 'OT', 'Moze V', 4, 41, 'Ba ihonogöi mbanua Moze, banua yefo Yoridano, tanö ba gatumbukha luo, tölu,[15]', '["MozIV 35:13"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 42, 'ena''ö ba da''ö isaŵa, na so zi no mamunu awönia si lö mu''odödögö ba si lö fatiusania khönia, mege sa''ae, ba ena''ö i''ila i''orifi ia, wanaŵa banua da''ö zambua:', '["MozIV 35:13"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 43, 'Beseri andrö, ba danö si mate ba zalo''o hili, ba ba mado Rubeno, ba ba mado Gado, ba Ramoti ba Gileadi ba ba mado Manase, ba Golana ba Mbazana.', '["MozIV 21:24"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 44, 'Ba da''ö goroisa andrö, nifa''ema Moze ba Ndraono Gizeraeli.', '["MozIV 21:24"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 45, 'Da''ö lala ba da''ö, nifakhoi andrö, awö huku andrö ni''ombakha''ö Moze ba Ndraono Gizeraeli, me aheta ira ba danö Miserayi,', '["MozIV 21:24"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 46, 'yefo Yoridano, ba ndraso, ba gamaudu Mbeti-Weoro, ba danö razo Ndraono Gamori andrö, Sihona andrö, ba Hesibona, ni''alani Moze ba Iraono Gizeraeli, me la''otarai danö Miserayi,[16]', '["MozIV 21:24"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 47, 'nihalöra tanö, si mane tanö Ogi andrö, razo Mbazana, tanö razo Ndraono Gamori andrö, si darua, yefo Yoridano, tanö ba gatumbukha luo,', '["MozIV 21:24"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 48, 'i''otarai Garoeri, ba mbewe Garono, irugi hili Ziono,', '["MozIV 21:24"]', NULL),
  (3405105, 'OT', 'Moze V', 4, 49, 'ya''ia Heremono andrö, fabaya salo''o tanö andrö, ba zi tambai Yoridano, tanö ba gatumbukha luo, fefu, irugi zilua''asi andrö ba zalo''o tanö ba gahe hili Wisiga.', '["MozIV 21:24"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 1, 'Ba humede Moze ba Ndraono Gizeraeli fefu, ba imane khöra: Mifondrondrongo, ya''ami Iraono Gizeraeli, nifakhoi andrö, awö huku andrö, nifarongogögu khömi ma''ökhö andre! Mitanö ba dödö, ba mitöngöni, ba wolo''ö ya''ia.', '["MozII 19:5"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 2, 'Lowalangida, Yehowa, ba no fawu''u li khöda, ba gahe hili Horebi.[1]', '["MozII 19:5"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 3, 'Tenga sa khö ndra tuada fawu''u li Yehowa, no khöda, sauri andre, khöda fefu, si so ba da''e ma''ökhö.', '["MozII 19:5"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 4, 'Si no fa''ila bawa ami khö Yehowa, me humede ia khömi ba hili andrö, moroi ba galitö.', '["MozII 19:5"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 5, 'Ba ya''odo, ba ba gotaluami Yehowa sodo, me luo da''ö, ba wama''ema khömi taroma li Yehowa, me no ata''u ami galitö andrö, ba me lö möi miyaŵa ba hili ami. Ba no imane:[2]', '["MozI 1:20–18"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 6, 'Ya''odo Yehowa, Lowalangiu, si no mangeheta ya''ugö ba danö Miserayi, ba danö andrö, si no möi sawuyu ami.[3]', '["Ayati 6–28: MozII 20"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 7, 'Böi so khömö Lowalangi tanö bö''ö, baero ndra''o.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 8, 'Böi fazökhi khöu nadu, famaedo hadia ia, he si so si yaŵa ba mbanua, ba he si so si tou ba guli danö, ba he si so ba nidanö barö danö.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 9, 'Böi angalulu khönia ba böi fosumange ia; me no Lowalangi solohu adra''o, ya''odo andre, Lowalangiu, Yehowa, sanguhuku horö ndra ama, ba ndraono ba ba ma''uwu mitou, irugi tölu, irege öfa nga''ötö, khöra si fatiu tödö khögu,', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 10, 'ba si hakhösi tödö sangomasi''ö ya''o ba solo''ö oroisagu, irugi hönö nga''ötö.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 11, 'Böi tötöi döi Lowalangiu Yehowa ba waya; lö''ö sa zi lö ihuku Yehowa zanötöi töinia ba waya.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 12, 'Ame''egö tödö luo wolombase andrö, ba we''amoni''ö ya''ia, dali niŵa''ö Lowalangiu, Yehowa, khöu.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 13, 'Önö ngaluo mohalöŵö ndra''ugö ba öhalö halöŵöu fefu, ba ero fitu bongi,', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 14, 'ba luo wolombase khö Lowalangiu, Yehowa; böi babaya hadia ia halöŵö ba da''ö, he ya''ugö, ba he onou matua, ba he onou alawe, ba he sangai halöŵö khöu ira matua, ba he sangai halöŵö khöu ira alawe, ba he uriföu, ba he si fatewu khöu, ba mbanuami; ena''ö la''ila molombase sangai halöŵö khöu, ira matua ba ira alawe, si mane ya''ugö.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 15, 'Törö-törö tödöu, wa no sawuyu göi ndra''ugö mege, ba danö Miserayi, awö wa no iheta''ö ba da''ö Lowalangiu, Yehowa, tangania sabe''e ba ta''ionia ni''oro''ö. Da''ö mbörö, wa no iŵa''ö khöu we''amoni''ö luo sabato andrö Lowalangiu, Yehowa.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 16, 'Fosumange namau, awö ninau, dali niŵa''ö Lowalangiu, Yehowa, khöu, ena''ö anau nosou ba ena''ö ohahau dödöu ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 17, 'Böi ange''e. Böi ohorö. Böi anagö. Böi böbögö khö nawöu zi lö duhu.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 18, 'Böi isö wo''omo nawöu. Böi isö nomo nawöu, ba he benuania, ba he sangai halöŵö khönia, ira matua ba ira alawe, ba he öröbaonia, ba he kudonia, ba he fefu gofu hadia zi so khö nawöu.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 19, 'Ha da''ö niŵa''ö Yehowa ba khömi sato fefu; ebua linia, ba hili andrö, moroi ba galitö andrö ba moroi ba zalu ba moroi ba zogömi-gömi. Ba isura ba gara wanura, si dombua, ba ibe''e khögu.[4]', '["MozII 31:18"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 20, 'Ba me mirongo li andrö moroi bakha ba zogömi-gömi andrö, me humola-hola hili andrö, ba mi''ondrasi ndra''o, satua mado khömi ba salaŵami, ba mimane:', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 21, 'No i''oroma''ö khöda lakhöminia ba fa''asalaŵania Lowalangida, Yehowa, ba no tarongo linia moroi ba galitö andrö, ba tobali no faduhu dödöda, tola muhede Lowalangi ba niha lö mate niha.', '["Faigi 4:33; Sanguhuk 13:22","MozII 19:8"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 22, 'Ba hana wa mate na ita iada''e ena''ö? I''a sa [ena''ö] ita alitö sebua andrö; na itohugö na tarongo li Lowalangida, ba si mate ita.', '["Faigi 4:33; Sanguhuk 13:22","MozII 19:8"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 23, 'Heza sa so ba nösi guli danö, fefu zi no mamondrongo li Lowalangi sauri andrö, sihede moroi ba galitö, si mane famondrongoda, ba souri na dania?[5]', '["Faigi 4:33; Sanguhuk 13:22","MozII 19:8"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 24, 'Ya''ugö andrö ondrasi ba fondrondrongo, hadia ia niŵa''ö Lowalangida, Yehowa, ba ya''ugö dania zama''ema khöma fefu hadia ia, niŵa''ö Lowalangida, Yehowa, khöu, ena''ö marongo ba ena''ö ma''o''ö.[6]', '["Faigi 4:33; Sanguhuk 13:22","MozII 19:8"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 25, 'Ba irongo limi Yehowa, me fahuhuo ami khögu, ba imane khögu Yehowa: No urongo huhuo niha andrö khöu; si ndruhu niŵa''öra.', '["Sin 81:14"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 26, 'Ena''ö na si manö-manö dödöra dania göi, ena''ö la''ata''ufi ndra''odo ba ena''ö na la''o''ö goroisagu andrö, fefu, fa sohahau tödö ira, awö ma''uwura, si lö mamalö-malö![7]', '["Sin 81:14"]', NULL),
  (3444250, 'OT', 'Moze V', 5, 27, 'Ae hede khöra, ömane: Mifuli manö ami baose khömi!', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 28, 'Ba ya''ugö iagö da''e khögu, ena''ö u''ombakha''ö khöu goroisa andrö fefu, awö gamakhoita, awö huku andrö, ba nifahaömö ya''ira dania, ena''ö la''o''ö ba danö andrö, nibe''egu khöra dania.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 29, 'Ba mitöngöni sa''ae, ena''ö mi''o''ö niŵa''ö Lowalangimi, Yehowa, khömi, fa böi mihole''ö ami, he ba gambölö ba he ba gabera.', '[]', NULL),
  (3444250, 'OT', 'Moze V', 5, 30, 'Mitörö sibai lala andrö, nifakhoi Lowalangimi, Yehowa, khömi, fa böi mate ami, ba ena''ö sohahau tödö ami ba sanau noso ba danö andrö, ni''okhögömi dania.', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 1, 'Da''ö goroisa andrö, awö gamakhoita andrö, awö huku, ba nifahaögu ya''ami, dali niŵa''ö Lowalangimi, Yehowa, ena''ö mi''o''ö ba da''ö, ba danö andrö, ba zi möi ami, miyefo,', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 2, 'ba wangokhögö ya''ia, ena''ö ö''ata''ufi Lowalangiu, Yehowa, ba ena''ö ö''o''ö nifakhoinia andrö ba oroisania fefu, nifa''emagu khöu, ba ena''ö anau nosou.', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 3, 'Ba na no mirongo, ya''ami Iraono Gizeraeli, ba mitöngöni, ba wolo''ö ya''ia, ena''ö sohahau tödö ami, ba ena''ö ato sibai ami dania, si mane nifabu''u Lowalangi ndra tuami andrö, Yehowa, tanö si no falawu susu ba ŵe ŵani.', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 4, 'Mifondrondrongo, ya''ami Iraono Gizeraeli! Yehowa, ba no Lowalangida, ha Yehowa, ha ya''ia![1].', '["Faigi 4:35; Yes 44:8; Mar 12:29–30","Mat 22:37; Luk 10:27"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 5, 'Ba ö''omasi''ö Yehowa andrö, Lowalangiu, moroi si''aikö ba dödöu ba moroi si''aikö ba gera-erau fefu, ö''oigö wa''abölöu.[2].', '["Faigi 4:35; Yes 44:8; Mar 12:29–30","Mat 22:37; Luk 10:27"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 6, 'Taroma li andre, niŵa''ögu khöu ma''ökhö, ba ötanö ba dödöu.', '["Faigi 11:19"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 7, 'Ba öfahaö göi ndraonou ba da''ö, itörö-törö liu, na yomo so''ö, ba he na ba wekoli; na möi''ö mörö ba na maoso''ö.[3].', '["Faigi 11:19"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 8, 'Öböbögö ba dete dangau, tandra, ba ba mbörö nikhumö, amaedola mbala högö;', '["Faigi 11:19"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 9, 'ba ösura ba gehomo nomou, ba ba lagö mbawa göli khöu.', '["Faigi 11:19"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 10, 'Ba na i''ohe dania ndra''ugö Lowalangiu, Yehowa, ba danö andrö, nibe''enia khöu dania, dali wahölusania mege khö ndra tuau Aberahamo, Iza''aki, Yakobo, tanö si so banua sebua ba si sökhi, si tenga nitaru''ömö,', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 11, 'ba omo si no mo''ösi gama-gama si sökhi, tenga moroi khöu, ba ba''a nikhao ba gara, si tenga nikhaomö, ba kabu nagu ba kabu falo, si tenga nitanöu; ba na manga ndra''ugö na abuso''ö, ba faigi sibai,', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 12, 'fa böi olifu''ö Yehowa, si no mangeheta ya''ugö ba danö Miserayi, ba danö si no möi sawuyu ndra''ugö.', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 13, 'Lowalangiu andrö, Yehowa, ba ö''ata''ufi ba öfosumange ba ba döinia möi''ö ba hölu,', '["Moz 11:17–7; Mat 4:7"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 14, 'ba lö tola mi''o''ö Lowalangi bö''ö, Lowalangi niha andrö, si tefasui ya''ami.', '["Moz 11:17–7; Mat 4:7"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 15, 'Me no Lowalangi solohu Lowalangimö andrö, Yehowa, ba khömi, fa böi mofönu khöu Lowalangimö, Yehowa, ba fa böi ise''e ndra''ugö ba guli danö!', '["Moz 11:17–7; Mat 4:7"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 16, 'Böi mitandraigö Lowalangimi, Yehowa, si mane fanandraigömi ya''ia no, ba Masa.[4].', '["Moz 11:17–7; Mat 4:7"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 17, 'Oroisa Lowalangimi Yehowa andrö, ba mi''o''ö, lala andrö ba amakhoita nibe''enia khömi, ba mitörö;', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 18, 'hadia zatulö ba hadia zi sökhi, wamaigi Yehowa, da''ö ötörö, ena''ö sohahau tödö ndra''ugö, ba ena''ö örugi danö si sökhi andrö, nifabu''u Yehowa khö ndra tuau, fahölusa, ba ena''ö ö''okhögö,', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 19, 'wanimba fönau si fa''udu khöu andrö, fefu, dali nifabu''u Yehowa.', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 20, 'Na isofu dania khöu onou, na imane: Hadia niŵa''ö andrö ba amakhoita andrö ba huku andrö, nioroi''ö Lowalangida, Yehowa?[5],', '["MozII 12:26"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 21, 'ba ömane khö nonou andrö: No sawuyu Wara''o ndra''aga mege, ba danö Miserayi, ba no ihetaga ba danö Miserayi Yehowa, tangania andrö, si no abe''e.', '["MozII 12:26"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 22, 'No ilau dandra ba ila-ila sebua ba famakiko Yehowa, ba danö Miserayi, khö Wara''o ba ba zoroiyomonia fefu, ba zanehe ndra''aga;', '["MozII 12:26"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 23, 'ba ya''aga, ba no iheta ba da''ö, ba wolohe ya''aga ba danö andrö ba ba wame''e khöda tanö andrö, nifabu''unia khö ndra tuada, fahölusa.', '["MozII 12:26"]', NULL),
  (3444615, 'OT', 'Moze V', 6, 24, 'Ba no iŵa''ö khöma Yehowa wolo''ö nifakhoi andrö fefu, wangata''ufi Lowalangida, Yehowa, ena''ö lö tebulö wa sohahau tödö ita, ba ena''ö i''oriorifi ita, si mane ma''ökhö.', '[]', NULL),
  (3444615, 'OT', 'Moze V', 6, 25, 'Ba niha satulö ita, na lö olifu ita wolo''ö oroisa andrö fefu, föna Lowalangida Yehowa, si mane niŵa''önia khöda.', '[]', NULL),
  (3444616, 'OT', 'Moze V', 7, 1, 'Na no i''ohe dania ndra''ugö ba danö andrö Lowalangiu Yehowa, ba danö andrö, ba zi möi''ö, ba wangokhögö ya''ia, ba na no oya soi itimba fönau: Iraono Kheti ba Iraono Girigasi ba Iraono Gamori ba Dawa Gana''ana ba Iraono Weresi ba Iraono Hewi ba Iraono Yebusi, fitu soi sebua moroi khöu ba sabölö moroi khöu,', '["MozIV 33:52; Yos 11:11","MozII 23:32; KorII 6:14","RazI 11:2"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 2, 'na no ibe''e ba dangau Lowalangiu, Yehowa, ba na no ölaŵa ira, ba ölakha''ö ira; lö tola fawu''u li ndra''ugö khöra, ba lö tola öhakhösi tödö.[1]', '["MozIV 33:52; Yos 11:11","MozII 23:32; KorII 6:14","RazI 11:2"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 3, 'Ba lö''ö göi tola fahalö ami; lö tola öbe''e khö nonora matua nonou alawe ba lö tola öhalö khö nonou matua nonora alawe.[2]', '["MozIV 33:52; Yos 11:11","MozII 23:32; KorII 6:14","RazI 11:2"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 4, 'Ma dania i''erogö ndra''o onou matua labe''e, ma tobali ifosumange Lowalangi bö''ö, ba mofönu khömi Yehowa ba ita''i-ta''i ihori ami.[3]', '["MozIV 33:52; Yos 11:11","MozII 23:32; KorII 6:14","RazI 11:2"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 5, 'Mimane sa''ae wolau khöra: Naha wame''e sumange khöra, ba midudugö, gowe andrö khöra, ba mirasa, eu ni''amoni''ö khöra, ba mi''obö, ba adura, ba mitunu ba galitö,[4]', '["MozII 23:24; MozIV 33:52","MozII 19:6; Sin 135:4"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 6, 'me no soi ni''amoni''ö khö Lowalangiu, Yehowa, ndra''ugö; no ya''ugö nituyu Lowalangiu, Yehowa, khönia, soi tana khönia, ni''oniagö ba soi bö''ö fefu, ba guli danö.[5]', '["MozII 23:24; MozIV 33:52","MozII 19:6; Sin 135:4"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 7, 'Tenga sa me no sato niha ami, moroi ba soi bö''ö, wa no ebua dödö Yehowa khöu, wa no ya''ami nituyu — noa sa fondrege zide-ide ami, ba ngai soi bö''ö fefu — börö me i''omasi''ö ami,', '["MozII 20:6","Nah 1:2"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 8, 'ba me edöna ia itörö zi no möi ba hölu ia khö ndra tuami mege; andrö iheta ami tanga sabe''e, i''efa''ö ami ba wa''asawuyu, ba danga Wara''o, razo Miserayi,', '["MozII 20:6","Nah 1:2"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 9, 'ena''ö aboto ba dödöu, wa no Lowalangi [si ndruhu] Lowalangiu andrö, Yehowa, wa no Lowalangi si lö faröi, si lö mamöhöi fawu''usa li ba fa''ebua dödö andrö, irege hönö nga''ötö, khöra sangomasi''ö ya''ia ba solo''ö oroisania,[6]', '["MozII 20:6","Nah 1:2"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 10, 'ba solau sulö, nifatörö khöra, ba zi fatiu tödö khönia, fefu, wangohori ya''ira. Lö''ö sa fa''ebolo dödönia ba zi fatiu tödö khönia, khönia ifatörö zulö.[7]', '["MozII 20:6","Nah 1:2"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 11, 'Andrö ö''o''ö goroisania, awö gamakhoita andrö, awö huku andrö, nifa''emagu khöu ma''ökhö, ena''ö öbe''e tali wolaumö ia.', '[]', NULL),
  (3444616, 'OT', 'Moze V', 7, 12, 'Ba na mifondrondrongo huku andrö ba na mi''o''ö, ba lö''ö göi ibulö''ö khöu Lowalangiu, Yehowa, wawu''usa li andrö, awö wa''ebua dödö, si no möi ba hölu ia khö ndra tuau:[8]', '["MozIII 26:3 b.t."]', NULL),
  (3444616, 'OT', 'Moze V', 7, 13, 'i''omasi''ö ndra''ugö ba ifahowu''ö ndra''ugö ba i''oya''ö ami; tabinamö andrö ba bua nowiu, fakheu, ba ösi mbua nagu, awö wanikha khöu, ba ono zaŵi khöu, ba fo''ono mbiri-biri khöu, fabaya nambi, ba ifahowu''ö, ba danö andrö, nibe''enia khöu dania, dali wahölusania andrö khö ndra tuau.', '["MozIII 26:3 b.t."]', NULL),
  (3444616, 'OT', 'Moze V', 7, 14, 'Nifahowu''ö dania ndra''ugö, föna soi bö''ö fefu; he ba ndra matua khöu ba he ba ndra alawe, ba lö si lö mo''ono, ba si manö göi ba gurifömö.[9]', '["MozII 23:26"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 15, 'Fefu ngawalö wökhö, ba itimba khöu Yehowa, ba sambalö lö igönaisi ndra''ugö fökhö Ndrawa Miserayi andrö, teu mbanua andrö, si no ö''ila föna; ba zi fa''udu khöu ihare''ö da''ö.[10]', '["MozII 9:3"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 16, 'Ba fefu soi andrö, nibe''e Lowalangiu, Yehowa, ba dangau, ba öhori. Böi ahakhö dödöu, wamaigi ya''ira, ba böi fosumange Lowalangira andrö; tandraŵa sa khöu da''ö ena''ö.', '[]', NULL),
  (3444616, 'OT', 'Moze V', 7, 17, 'Ba na ömane dödöu ena''ö: Sato moroi khögu soi andrö, he uwisa wanimba ya''ira?', '["Faigi 29:3","MozII 23:28"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 18, 'ba böi ata''ufi, törö manö tödöu nifatörö Lowalangiu, Yehowa khö Wara''o no, ba ba Ndrawa Miserayi fefu.', '["Faigi 29:3","MozII 23:28"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 19, 'Fa''abölö andrö, nifa''ele''ö, ni''ila höröu, tandra andrö, ba ila-ila, tanga sabe''e andrö ba ta''io ni''oro''ö, khö Lowalangiu, Yehowa, wamawu''a ya''ugö! Si manö dania ilau Lowalangiu, Yehowa, ba niha bö''ö andrö fefu, ni''ata''ufimö.[11]', '["Faigi 29:3","MozII 23:28"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 20, 'Ba ifatörö na khöra geto Lowalangiu, Yehowa, irege ahori zi tosai andrö, si no mamini''ö ya''ira mege khöu.[12]', '["Faigi 29:3","MozII 23:28"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 21, 'Böi humokha mbumö khöra! me no so ba khöu Lowalangiu, Yehowa, Lowalangi sebua ba sata''u ita,', '["MozII 23:29"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 22, 'ba izara-zara wanimba fönau soi andrö Lowalangiu, Yehowa. Böi osamuzaigö wangohori ya''ira, ma dania abölö khöu gutu ndru''u.[13]', '["MozII 23:29"]', NULL),
  (3444616, 'OT', 'Moze V', 7, 23, 'Ibe''e ba dangau Lowalangiu, Yehowa, ba fawuka ibe''e, irege no ahori ira.', '[]', NULL),
  (3444616, 'OT', 'Moze V', 7, 24, 'Ba razora, ba ibe''e ba dangau, ena''ö olifu niha ba guli danö döira öbe''e. Samösa lö solaŵa ya''ugö, irege no öhori ira.', '[]', NULL),
  (3444616, 'OT', 'Moze V', 7, 25, 'Famaedo Lowalangira andrö, ba mitunu, ba firönia ba ana''ania, ba böi isö, böi halö khöu, fa böi tobali fama''alamö. Me no sogoro Lowalangiu, Yehowa, zi mane da''ö.', '[]', NULL),
  (3444616, 'OT', 'Moze V', 7, 26, 'Ba sogoro ita, ba böi ohe yomo ba nomou, fa böi möi salakha göi ndra''ugö, si mane ya''ia.', '[]', NULL),
  (3444616, 'OT', 'Moze V', 7, 27, 'Ö''ogorofi ba si hokha mbumö ia, me no mulakha''ö.', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 1, 'Oroisa andrö fefu, nifa''emagu khömi ma''ökhö, ba mi''o''ö, ena''ö auri ami ba ena''ö ato ami, ba ena''ö mirugi danö andrö ba wangokhögö ya''ia, tanö andrö nifabu''u Yehowa khö ndra tuami, fahölusa.', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 2, 'Törö-törö tödöu wamasao Lowalangiu, Yehowa ya''ugö, no öfa wulu fakhe wa''ara, ba danö si mate andrö, ba döröŵau andrö, fadoro, ba wangöhöndrögö ya''ugö ba ba wanandraigö ya''ugö, ena''ö isöndra he wisa dödöu, na edöna ö''o''ö goroisania, ba na lö''ö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3444626, 'OT', 'Moze V', 8, 3, 'No ihöndrögö ndra''ugö, ifatörö khöu lofo, ba aefa da''ö, ba ibe''e öu "mana" andrö, si lö mirai mila, he ira tuau, ba wama''ele''ö khöu, wa tenga ha ba gönia auri niha, wa tola göi fangorifinia hadia ia daroma li, si otarai mbawa Yehowa.[1].', '["MozII 16:15; Mat 4:4","Faigi 29:5"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 4, 'Nukhau andrö, ba lö sadudu, ba aheu, ba lö sabao, si öfa wulu fakhe andrö.[2].', '["MozII 16:15; Mat 4:4","Faigi 29:5"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 5, 'Ba yafaduhu sa''ae dödöu, i''ohe ba zi sökhi ndra''ugö Lowalangiu, Yehowa, nifamatörö si''aikö nama ononia.', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 6, 'Ba o''ö goroisa Lowalangiu, Yehowa andrö, wanörö lala andrö khönia, awö wangata''ufi ya''ia.', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 7, 'Ba danö si sökhi sa i''ohe ndra''ugö Lowalangiu, Yehowa, ba danö si so mbombo ba umbu nidanö ba baŵa, so''ulu ba zalo''o ba so''ulu ba hili;', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 8, 'tanö si so fakhe ba si so rigi ba agu ba bua ara ba dalimo, tanö si so falo ba si so ŵe ŵani;', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 9, 'tenga tanö sambö-ambö balazo, no tanö si so manö fefu hadia ia, tanö sosi''öli kara ba nikharu töla garamba ba hili.', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 10, 'Ba na no manga''ö dania, na no abuso''ö, ba ösuno Lowalangiu Yehowa, börö danö si sökhi andrö nibe''enia khöu.[3].', '["KorI 10:31; TimI 4:4"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 11, 'Faigi sibai, fa böi olifu''ö Lowalangiu, Yehowa, fa böi öbato wolo''ö oroisania andrö, awö huku andrö, awö gamakhoita, nifa''emagu khöu ma''ökhö.', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 12, 'Na abuso ndra''ugö dania ba ölau khöu nomo si sökhi,', '["MozIV 21:6; MozII 17:6"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 13, 'na itugu oya zaŵiu ba biri-birimö ba na fahöna khöu wirö ba ana''a, na tedou fefu hadia ia zi so khöu,', '["MozIV 21:6; MozII 17:6"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 14, 'ba böi fayaŵa dödöu, ba böi olifugö''ö Lowalangiu, Yehowa, si no mangeheta ya''ugö ba danö Miserayi andrö, ba danö, ba zi no möi''ö sawuyu,', '["MozIV 21:6; MozII 17:6"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 15, 'si no mamatörö ya''ugö ba danö si mate andrö, sebolo sibai ba sata''u ita, ba zi so ulö sosöfu ba tongo, ba danö si no oköli-köli ba si lö idanö, si no mame''e öu idanö sangumbu-ngumbu moroi ba gara sabe''e,[4],', '["MozIV 21:6; MozII 17:6"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 16, 'si no mame''e öu "mana" andrö, ba danö si mate, ö si lö larai mila ira tuau, ba wangöhöndrögö ya''ugö ba ba wanadraigö ya''ugö, ena''ö ihaogö khöu ba götö dania,', '["MozIV 21:6; MozII 17:6"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 17, 'ba böi ömane dödöu: Fa''abölögu ba fa''abe''e dangagu mbörö, wa so khögu wo''ana''a andre.', '["MozIV 21:6; MozII 17:6"]', NULL),
  (3444626, 'OT', 'Moze V', 8, 18, 'Törö tödöu Lowalangiu, Yehowa, me no ya''ia zame''e fa''abölö, ba wangalui ana''a, ba wamalua amabu''ula linia andrö, si no möi ba hölu ia khö ndra tuau, si mane ma''ökhö.', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 19, 'Ba na olifu''ö zui Lowalangiu, Yehowa, wolo''ö Lowalangi bö''ö, na öfosumange da''ö, ba na mangalulu''ö khöra, ba ma''ifu lö ubini''ö khömi ma''ökhö, wa si tekiko ami dania.', '[]', NULL),
  (3444626, 'OT', 'Moze V', 8, 20, 'Si mane niha baero andrö, nifakiko Yehowa fönami, si manö göi wa''atekikomi, fotu; me lö nifondrondrongomi li Lowalangimi, Yehowa.', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 1, 'Mifondrondrongo, ya''ami Iraono Gizeraeli! Ö''ötö iya''e Yoridano andrö, ba wolaŵa soi sato moroi khöu ba sabölö moroi khöu, ba ena''ö atu''a ndra''ugö ba mbanua, si no ebua ba si no aro, sirugi ba mbanua si yaŵa öli,', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 2, 'ena''ö ölaŵa soi sato niha ba salaŵa boto, Dawa Genaki andrö, si no i''ila höröu ba si no örongo, na laŵa''ö: Ha niha zangila molaŵa Dawa Genaki andrö?', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 3, 'Ba böi zi lö aboto ba dödöu sa''ae, wa no Lowalangiu, Yehowa zowaö-waö fönau, amaedola galitö si manga-manga hadia ia; ya''ia zangohori, ya''ia zangöhöndrögö ya''ira fönau, ba tobali lö arara ö''animba''ö ya''ira ba lö arara ö''angohori''ö, itörö nifabu''u Yehowa khöu.', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 4, 'Ba na itimba dania ira fönau Lowalangiu, Yehowa, ba böi ömane dödöu: Börö wa''atulö dödögu, wa ya''o zokhö tanö andre, ibe''e Yehowa; me no börö horö niha andrö, wa itimba ira fönau Yehowa.[1]', '["MozI 15:16; MozIII 20:23"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 5, 'Tenga sa ba wa''atulö dödöu ba tenga ba wa''adölö dödöu möi khöu danöra andrö, börö horö soi andrö, wa itimba ira fönau Lowalangiu, Yehowa, ba ena''ö itörö gamabu''ula linia andrö, nifabu''u Yehowa khö ndra tuau Aberahamo, Iza''aki, Yakobo, si no möi ba hölu ia.', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 6, 'Ba ya''aboto ba dödöu, wa tenga börö wa''atulö dödöu, wa ibe''e okhötau danö si sökhi andre Lowalangiu, Yehowa: noa sa soi sabe''e tandro ndra''ugö.', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 7, 'Törö-törö tödöu ba böi olifugö''ö he wisa wangandrö-ngandröu fönu Lowalangiu, Yehowa, ba danö si mate! I''otarai luo andrö, me aheta ami ba danö Miserayi, irege mirugi da''e, ba sabe''e tandro ami khö Yehowa.[2]', '["MozII 14:11","MozII 32:4"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 8, 'Ba gahe hili Horebi andrö mi''andrö wönu Yehowa, ba abao dödönia khömi, irege ihori ami mena''ö.[3]', '["MozII 14:11","MozII 32:4"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 9, 'No möido miyaŵa ba hili, ba wanema kara wanura andrö, kara nisura fawu''usa li andrö, nilau Yehowa khömi, ba öfa wulu ngaluo ba öfa wulu mbongi wa''aragu ba hili andrö, lö ni''agu roti ba lö nibadugu idanö.[4]', '["MozII 24:18"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 10, 'Ba ibe''e ba dangagu Yehowa gara wanura andrö, si dua görö, nisua turu Lowalangi, si so taroma li andrö fefu, niŵa''ö Yehowa khömi, moroi ba galitö, me luo walukhata, ba hili andrö.[5]', '["MozII 31:18"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 11, 'Me no aefa zi öfa wulu ngaluo ba si öfa wulu wongi, ba ibe''e ba dangagu Yehowa gara wanura andrö, si dua görö, kara andrö nisura oroisa andrö.', '["MozII 31:18"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 12, 'Ba imane sa''ae khögu Yehowa: Labu, ta''i-ta''i mitou, noa sa lalau wamakiko banuau andrö, nihetamö ba danö Miserayi. No alio sibai laröi lala andrö, nifakhoigu khöra: no lafazökhi khöra nadu nifahele.', '["MozII 32:9"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 13, 'Ba imane na khögu Yehowa: U''ila sibai sa''ae soi andrö, wa no soi sabe''e börö du''i.[6]', '["MozII 32:9"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 14, 'Ba böhölido sa''ae, ena''ö uhori ira, ubunu döira ba guli danö ba ubali''ö furugö soi ndra''ugö, furugö soi sabölö moroi khöra ba sato niha.', '["MozII 32:9"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 15, 'Ba maoso ndra''o ufulido mitou moroi ba hili sihola-hola na, dua dangagu wolohe kara andrö, si dua görö, sura goroisa.', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 16, 'Ba awena u''ila, ba hiza, ba no mifazökhi horö khö Lowalangimi, Yehowa, no milau nono zaŵi nifahele; no alio sibai miröi lala andrö, nifakhoi Yehowa khömi.', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 17, 'Ba utuyu gara andrö, si dua görö, ba dua dangagu wamazaumba ya''ia, murasa|urasa, ba zanehe ami.', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 18, 'Ba ufalögu tou ndra''o föna Yehowa; si mane mege, öfa wulu ngaluo ba öfa wulu mbongi, lö u''a roti ba lö ubadu nidanö, börö horömi andrö fefu, nifazökhimi, me no milau zi lö omasi Yehowa, fangandrö wönunia.[7]', '["MozII 34:28"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 19, 'Sata''u sa''ae ndra''o fönu Yehowa ba bakhu-bakhu dödönia khömi, wa ihori ami mena''ö. Ba ifondrondrongo khögu Yehowa, ba da''ö göi.', '["MozII 34:28"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 20, 'Ba khö Ga''aroni göi, ba mofönu sibai ia, irege ifakiko mena''ö, ba ba khö Ga''aroni göi mangandrö ndra''o, me luo da''ö.', '[]', NULL),
  (3444629, 'OT', 'Moze V', 9, 21, 'Ba horömi andrö, nilaumi, ono zaŵi andrö, ba uhalö, utunu, ba ututu, ufaulugö ufufu, balazi no ohama sibai, ba si hulö gawu-gawu andrö, ba utibo''ö ba mbombo andrö, si otarai hili moroi yaŵa.[8]', '["MozII 32:20"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 22, 'Ba baero da''ö, ba ba Dabera mi''andrö wönu Yehowa ba ba Masa ba ba niko''o solu''a-lu''a.[9]', '["MozIV 11:3; MozII 17:7; MozIV 11:34"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 23, 'Ba he me ifatenge ami Yehowa, moroi ba Gadesi-Mbarenea, wanguma''ö khömi: Mi''ae misi yaŵa ba mi''okhögö danö, nibe''egu khömi, ba te khömi goroisa Lowalangimi, Yehowa, ba lö faduhu dödömi khönia ba lö mifondrondrongo khönia.[10]', '["MozIV 14:1"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 24, 'No sabe''e börö du''i ami khö Yehowa, i''otarai me awena u''ila ami.', '["MozIV 14:1"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 25, 'Ba me sodo manö tou ba danö, föna Yehowa, si öfa wulu ngaluo öfa wulu mbongi, si no ufalögu tou ndra''odo, me no idaö''ö-daö''ö Yehowa ihori ami,', '["MozIV 14:13; Yos 7:7"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 26, 'ba mangandrödo khö Yehowa, umane: He So''aya, Yehowa böi fakiko mbanua tana khöu andrö, ni''efa''ömö fa''abölöu andrö si tenga inötö, nihetau ba danö Miserayi tangau andrö, si no abe''e![11]', '["MozIV 14:13; Yos 7:7"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 27, 'Törö-törö tödöu genoniu andrö, Aberahamo ba Iza''aki ba Yakobo! Ba böi be''e balazi wa''abe''e mbörö du''i mbanuau andrö ba he falösökhira andrö ba he horöra.', '["MozIV 14:13; Yos 7:7"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 28, 'Fa böi laŵa''ö niha ba danö andrö, ba nihetau ya''ira: Me tebai i''ohe ira Yehowa ba danö andrö, nifabu''unia khöra, ba me no fatiu dödönia khöra, ba ba wame''e tekiko ya''ira ba danö si mate iheta ira!', '["MozIV 14:13; Yos 7:7"]', NULL),
  (3444629, 'OT', 'Moze V', 9, 29, 'Noa sa atö banuau ira, no tana khöu, nihetau fa''abölöu andrö si tenga inötö, ba ta''iomö andrö ni''oro''ö.', '["MozIV 14:13; Yos 7:7"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 1, 'Ba me luo da''ö, ba imane khögu Yehowa: Toto khöu gara wanura, dua görö, si mane mege, ba ae khögu miyaŵa ba hili; ba öfazökhi göi khöu tawöla eu.[1].', '["MozII 34:1"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 2, 'Usura dania ba gara andrö daroma li andrö, si so ba gara mege, nirasamö, ba öbe''e barö tawöla andrö dania.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 3, 'Ba ufazökhi tawöla, bana geunia, ba utoto gara wanura, dombua, si mane mege, ba möido miyaŵa ba hili, u''ohe tangagu gara andrö, si dombua.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 4, 'Ba isura ba gara andrö daroma li andrö, si fulu, niŵa''önia mege khömi ba hili, moroi ba galitö, me luo walukhata andrö, si mane fanura mege wanura ya''ia. Ba ibe''e ba dangagu Yehowa.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 5, 'Ba möido mitou, moroi ba hili, ba ube''e barö tawöla andrö, nifazökhigu, gara andrö ba ba da''ö ahono, dali niŵa''ö Yehowa khögu.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 6, 'Ba laheta ira ba Mbe''eroti-Bene-Ya''aka Iraono Gizeraeli, lasaŵa Mosera. Ba ba da''ö mate Ga''aroni ba ba da''ö lako''o ia, ba ononia Eleazari wangalinia ere.[2].', '["MozIV 33:31"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 7, 'Ba moroi ba da''ö, ba lasaŵa Gudigoda, ba moroi ba Gudigoda, ba lasaŵa Yotiba, tanö soya mbombo.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 8, 'Ba me luo da''ö, ba i''oniagö mado Lewi Yehowa, ba wolohe-lohe tawöla nahia zura goroisa Yehowa, ba ena''ö föna Yehowa so ira, ngoni-ngoninia, si lö tebulö, ba ena''ö mamahowu ira ba döinia, si lö mamalö-malö, ero ma''ökhö.[3].', '["MozIV 3:12; 6:23","MozIV 18:20; Hes 44:28"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 9, 'Andrö lö manema mado Lewi tanö, lö tana khöra si lö tebulö, si mane ba dalifusöra; tana khöra, ba Yehowa, dali nifabu''u Lowalangiu Yehowa khöra.[4].', '["MozIV 3:12; 6:23","MozIV 18:20; Hes 44:28"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 10, 'Ba ya''odo, ba si lö tebulö ba hili, si mane mege, ba zi föföna, öfa wulu ngaluo ba öfa wulu mbongi, ba ifondrondrongo khögu Yehowa ba zi samuza andrö göi: Lö ifakiko ndra''ugö Yehowa.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 11, 'Ba imane khögu Yehowa: Labu, ae''e, ba wolohe ya''ira, mofanö ami ena''ö larugi danö andrö ba ena''ö la''okhögö, tanö andrö nibe''egu khöra dania, dali we''amöigu ba hölu khö ndra tuara andrö.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 12, 'Ba iya''e, ya''ami Iraono Gizeraeli, hadia niŵa''ö Lowalangimi, Yehowa khömi, na tenga fa ö''ata''ufi Lowalangiu, Yehowa, ba ena''ö böi öbulö''ögö ba lala andrö khönia, ba ena''ö ö''omasi''ö ia, ba ena''ö enoni Lowalangiu, Yehowa, ndra''ugö, moroi si''aikö ba dödöu ba moroi si''aikö ba gera-erau,', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 13, 'wolo''ö oroisa andrö ba amakhoita nifakhoi Yehowa nifa''emagu khöu ma''ökhö, fangohahau dödöu.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 14, 'He sa no khö Lowalangiu, Yehowa, mbanua si yaŵa, irugi ba wondrege yaŵa, awö danö ba ösinia fefu,[5]', '["Sin 24:1; 115:16","Faigi 4:20"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 15, 'ba noa zui ha khö ndra tuau ebua dödö Yehowa, wangomasi''ö ya''ira, ba no ituyu ami, ma''uwura andrö, ba niha bö''ö fefu, si mane ma''ökhö.[6].', '["Sin 24:1; 115:16","Faigi 4:20"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 16, 'Ba miboto sa''ae mbotolö dödömi andrö, ba böi sa''ae sabe''e börö du''i ami![7].', '["Faigi 30:6; Yer 4:4","Yob 34:19; HalZin 10:34; Rom 2:11; Efes 6:9; FetI 1:17; Fam 17:14"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 17, 'Me no Lowalangi Lowalangi bö''ö Lowalangimi andrö, Yehowa, ba me no So''aya sokhö, Lowalangi sebua ba sabölö ba sata''u ita, si lö ebua tödö zambuana ba si lö manga gana''a,[8]', '["Faigi 30:6; Yer 4:4","Yob 34:19; HalZin 10:34; Rom 2:11; Efes 6:9; FetI 1:17; Fam 17:14"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 18, 'solohe ba lala huhuo zi lö ama, si lö ina, ba sangomasi''ö niha bö''ö, wame''e balazo khönia, awö nukha.', '["Faigi 30:6; Yer 4:4","Yob 34:19; HalZin 10:34; Rom 2:11; Efes 6:9; FetI 1:17; Fam 17:14"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 19, 'Ba mi''omasi''ö niha bö''ö, me no niha bö''ö ami göi ba danö Miserayi no.', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 20, 'Ö''ata''ufi Lowalangiu Yehowa ba öfosumange, khönia molemba ndra''ugö ba ba döinia möi''ö ba hölu!', '[]', NULL),
  (3444631, 'OT', 'Moze V', 10, 21, 'Fangebua duriamö ia ba Lowalangiu, si no molau khöu sebua andrö ba sata''u ita, ni''ila höröu.', '["MozI 46:27"]', NULL),
  (3444631, 'OT', 'Moze V', 10, 22, 'Fitu ngafulu niha wa''ato ndra tuau, me lasaŵa danö Miserayi, ba iya''e, ba no timba wa''oya ndröfi ba mbanua, ibe''e Lowalangiu, Yehowa.[9]', '["MozI 46:27"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 1, 'Ba ö''omasi''ö sa''ae Lowalangiu, Yehowa, ba ö''o''ö niŵa''önia ni''o''ö, nifakhoinia andrö ba huku andrö khönia ba oroisania, sagötö ya''ugö,', '["MozII 14:26","MozIV 16:32"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 2, 'ba ya''aboto ba dödömi ma''ökhö, — tenga sa ba ndraonomi, si lö''ö na mege, si lö mangila ya''ia [humede ndra''o] — wotu Lowalangimi, Yehowa, ba fa''asalaŵania ba tangania andrö, si no abe''e ba ta''ionia, si no mu''oro''ö,', '["MozII 14:26","MozIV 16:32"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 3, 'ba tandra andrö khönia ba folaunia ba danö Miserayi, khö Wara''o, razo Miserayi, ba ba danönia ma''asagörö,', '["MozII 14:26","MozIV 16:32"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 4, 'nifatörönia ba zabölö Miserayi ba ba kudora ba ba guretara, me ihawui ira asi zukhu andrö, me lagohi ami, wangohori ya''ira, irugi ma''ökhö andre,[1]', '["MozII 14:26","MozIV 16:32"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 5, 'ba he iwisa khömi ba danö si mate, irugi no mikhamö da''e,', '["MozII 14:26","MozIV 16:32"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 6, 'awö nilaunia khö ndra Datano Abiramo, iraono Geliabi andrö, mado Rubeno, me ifaboka mbawania tanö, me itölö ira ba hunö Ndraono Gizeraeli fefu, fabaya nahiara, awö nosera, awö fefu hadia ia zi fao-fao khöra.[2]', '["MozII 14:26","MozIV 16:32"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 7, 'Noa sa''ae hörömi zangila sebua andrö fefu, nilau Yehowa.', '[]', NULL),
  (3444651, 'OT', 'Moze V', 11, 8, 'Ba mi''o''ö sa''ae goroisa andrö fefu, nifa''emagu khömi ma''ökhö, ena''ö abölö ami, ba wondrugi tanö andrö ba ba wangokhögö ya''ia, tanö si möi ami miyefo iya''e, ba wangai ya''ia khömi,', '[]', NULL),
  (3444651, 'OT', 'Moze V', 11, 9, 'ba ena''ö anau nosomi ba danö andrö, si no möi ba hölu Yehowa khö ndra tuami, ba wame''e khöra ba ba ma''uwura, — tanö ba zi falawu susu ba ŵe ŵani.', '[]', NULL),
  (3444651, 'OT', 'Moze V', 11, 10, 'Tanö andrö sa, ba zi möi ndra''ugö, ba wangokhögö ya''ia, ba no tenga si mane tanö Miserayi andrö, saheta ami, nifo''idanömö aheu, na no ötaru danömöu, amaedola kabu gule.', '[]', NULL),
  (3444651, 'OT', 'Moze V', 11, 11, 'Tanö andrö, ba zi möi ami miyefo ba wangokhögö ya''ia, ba no tanö si so hili ba si so daso, tanö samadu teu, na atoru moroi yaŵa,[3]', '["Faigi 8:7"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 12, 'tanö nirorogö Lowalangiu, Yehowa; lö aefa hörö Lowalangiu, Yehowa, khönia, döfi fasui.', '["Faigi 8:7"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 13, 'Ba na a''oi dödömi wolo''ö oroisagu andrö, nibe''egu khömi ma''ökhö, wangomasi''ö Lowalangimi Yehowa, na moroi si''aikö ba dödömi ba na moroi si''aikö ba gera-erami möi ami enoninia,', '["Faigi 28:12; Yoel 2:23"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 14, 'ba ufatörö ba danömi deu, na inötö, teu sahulö ba teu sara, ena''ö ö''ila ö''ozaragö mbua nowi khöu ba bua nagu khöu ba fanikha.[4]', '["Faigi 28:12; Yoel 2:23"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 15, 'Ba ufodu''u mbenuamö, ö guriföu, ena''ö ösöndra göu ba ena''ö abuso''ö.', '["Faigi 28:12; Yoel 2:23"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 16, 'Mifaigi sibai, fa böi ibe''e nifowöhö ia tödömi, ba wamosumange Lowalangi bö''ö, ba ba wangalulu ba da''ö;', '["Faigi 28:23"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 17, 'fa böi tesao wönu Yehowa khömi, fa böi ikusi mbanua si yaŵa, tobali lö teu sa''ae ba lö''ö sa''ae bua danö, ba lö arara, ba ahori ami ba danö si sökhi andrö, nibe''e Yehowa khömi.[5]', '["Faigi 28:23"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 18, 'Ba mibe''e ba dödömi niŵa''ögu andre, böi olifu ami; miböbögö ba dete dangami, tandra-tandra, ba ba mbörö nikhumi mibe''e, amaedola mbala högö![6]', '["Faigi 6:8"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 19, 'Mifahaö ndraonomi ba da''ö, ya''itörö limö na yomo so''ö ba na ba wekoli, na möi''ö mörö ba na maoso''ö;[7]', '["Faigi 4:10"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 20, 'ösura ba gehomo nomou ba ba lagö mbawa göli khöu,', '["Faigi 4:10"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 21, 'ena''ö anau nosomi ba he noso ndraonomi dania, sagötö banua yaŵa danö, ba danö andrö, nifabu''u Yehowa khö ndra tuami, fahölusa.', '["Faigi 4:10"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 22, 'Ba na moroi ba dödömi mifaigi wolo''ö oroisa andrö fefu, nifa''emagu khömi, na mi''omasi''ö Lowalangimi, Yehowa, ba na lö tebulö wa lala andrö khönia mitörö ba khönia molemba ami,', '[]', NULL),
  (3444651, 'OT', 'Moze V', 11, 23, 'ba itimba dania fönami soi andrö fefu Yehowa, ba mitema gondröita soi sato niha, moroi khömi, ba sabölö, moroi khömi.', '[]', NULL),
  (3444651, 'OT', 'Moze V', 11, 24, 'Fefu danö, nihundragö gahemi, ba khömi dania, i''otarai danö si mate andrö, numalö ba hili Libano, ba i''otarai mboto nidanö andrö, Oiferati, numalö ba mbewe nasi tanö ba gaekhula luo, ba tanömi dania.[8]', '["Yos 1:3","MozII 23:27"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 25, 'Lö sabe''e moroi khömi dania; sagörö tanö si möi ami ihawui dania ira Lowalangimi, Yehowa, fa''ata''ura ami ba fehokha mbura khömi, itörö nifabu''unia khömi.[9]', '["Yos 1:3","MozII 23:27"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 26, 'Hiza, howu-howu ba fangelifi ufaedo khömi ma''ökhö:[10]:', '["Faigi 30:1"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 27, 'howu-howu na mi''o''ö goroisa Lowalangimi, Yehowa, andrö, nifa''emagu khömi ma''ökhö,', '["Faigi 30:1"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 28, 'ba fangelifi, na lö mi''o''ö goroisa Lowalangimi, Yehowa, na miröi lala andrö, nifakhoigu khömi ma''ökhö, ba wolo''ö Lowalangi bö''ö, si lö mirai mila mege.', '["Faigi 30:1"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 29, 'Ba na no i''ohe dania ndra''ugö Lowalangiu, Yehowa, ba danö andrö, ba zi möi''ö, ba wangokhögö ya''ia, ba ba hili Gerisi öbe''e howu-howu, ba fengelifi, ba ba hili Gebala öbe''e.[11]', '["Faigi 27:12; Yos 8:33"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 30, 'Hili andrö yefo Yoridano ba zi tambai lala andrö tanö ba gatumbukha luo, ba danö Ndrawa Gana''ana andrö ba Garaba, ba gamaudu Giligala, ba ngai gatua manawa More.', '["Faigi 27:12; Yos 8:33"]', NULL),
  (3444651, 'OT', 'Moze V', 11, 31, 'Mi''ötö sa''ae Yoridano, ba wangokhögö tanö andrö, nibe''e Lowalangimi, Yehowa, khömi. Ba na no mihalö khömi, na no ahono ami ba danö,', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3444651, 'OT', 'Moze V', 11, 32, 'ba mifaigi, böi zi lö mi''o''ö nifakhoi andrö fefu, awö huku andrö, ni''ombakha''ögu khömi ma''ökhö.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 1, 'Da''e nifakhoi, ba da''e huku, nitöngönimi ba wolo''ö ya''ia, si lö mamalö-malö, ba danö andrö, nibe''e Lowalangi ndra tuau, Yehowa, khöu, götö wa''anau nosomi ba guli danö.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 2, 'Mifaulugö wanudugö nahia andrö fefu, ba nifosumange soi niha andrö, nitimbami, Lowalangira mege, ba hili salaŵa, ba ba hili-hili ba ba mbörö geu sauri fefu.[1]', '["MozII 34:13","Sanguhuk 2:2","MozII 20:24; RazI 8:29"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 3, 'Midudugö naha wame''e sumange andrö khöra, ba gowe khöra, ba mirasa, ba eu ni''amoni''ö andrö khöra, ba mitunu, ba famaedo Lowalangira, ba mifufu, mibe''e mate döinia ba nahania andrö.[2]', '["MozII 34:13","Sanguhuk 2:2","MozII 20:24; RazI 8:29"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 4, 'Ba böi mimanö ba khö Lowalangimi, Yehowa.[3]', '["MozII 34:13","Sanguhuk 2:2","MozII 20:24; RazI 8:29"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 5, 'Naha andrö, nihonogöi Lowalangimi, Yehowa, dania, nituyunia ba madomi andrö fefu, ba wamonahia töinia ba da''ö, ba böi miböhöli, ba da''ö möi-möi''ö.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 6, 'Ba da''ö mi''ohe zumange nitunu andrö khömi ba sumange nitaba, ba si sambua ni''ofulu andrö khömi ba hadia nibe''emi sumange si no amaedola wegero, ba amabu''ula limi. Ba saoha gölömi ba si a''a ba wa''atumbu ba zaŵimi ba ba mbiri-birimi.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 7, 'Ba da''ö milau manga föna Lowalangimi, Yehowa, ba ba da''ö omuso dödömi, soroiyomomi fefu, mi''omusoi''ö tödö gölömi, nisöndrami andrö, nifahowu''ö Lowalangiu, Yehowa, ya''ugö.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 8, 'Böi mitohugö wolau-lauda iya''e, me ilau zomasi ia zamösana.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 9, 'Irugi maökhö sa, ba lö nikhamömi fa''ahono ba tenga na khömi danö, nibe''e Lowalangiu, Yehowa, dania.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 10, 'Ba na no mi''ötö Yoridano, na no ahono ami ba danö andrö, nibe''e Lowalangimi, Yehowa, okhötami ba na no itimba nemalimi fefu, fasui, fa ahono ami,', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 11, 'fa lö hadia ia sa''ae khömi, awena dania mo''ahonoa, wa ba naha andrö, mi''ohe fefu hadia ia ni ŵa''ögu khömi, ba naha andrö, nituyu Lowalangimi, Yehowa, ba wamonahia töinia ba da''ö; sumange nitunu andrö khömi ba sumange nitaba, ba si sambua ni''ofulu andrö khömi, ba hadia nibe''emi sumange si no amaedola wegero, ba sumange amabu''ula li andrö khömi, nitutuyu, nifabu''umi khö Yehowa.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 12, 'Ba omuso dödömi föna Lowalangimi, Yehowa, ya''ami ba iraonomi matua ba iraonomi alawe ba sawuyumi, ira matua ba ira alawe, awö nono Lewi andrö, si fatewu khömi, me lö khönia tanö, lö tana khönia, ondröita dania.[4]', '["MozIV 18:20"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 13, 'Faigi sibai, fa böi sate öbe''e zumange nitunu andrö khöu:', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 14, 'ba naha nituyu Yehowa ba madomi andrö, heza, ba da''ö öbe''e zumange nitunu andrö khöu, ba ba da''ö ölau fefu hadia ia niŵa''ögu khöu.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 15, 'Ba hana sa na ötaba öu zomasi''ö ba mbanuami fefu, misa, ha wa''oya nibe''e khöu, howu-howu Lowalangiu, Yehowa; he si ra''iö ba he si lö fa''ara''iö, ba hana na la''a, amaedola nago ba amaedola mböhö.', '["MozI 9:4"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 16, 'Ha do zi lö tola mi''a; öfanuwagö idanö ba danö.[5]', '["MozI 9:4"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 17, 'Ba si sambua ni''ofulu andrö khöu, he bua danö ba he agu ba he fanikha, ba lö tola ö''a ba mbanuami misa, ba he si a''a ba wa''atumbu andrö ba zaŵiu ba ba mbiri-biriu, ba he hadia ia gamabu''ula li andrö, nifabu''umö, ba he ame''elamö saoha gölö, ba he hadia ia nibe''eu sumange fegero;', '["Faigi 14:23"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 18, 'föna Lowalangiu Yehowa, ba naha andrö nituyu Lowalangiu, Yehowa, ö''a ia, ya''ugö ba onou matua ba onou alawe, ba sawuyumö, ira matua ba ira alawe, awö nono Lewi andrö, si fatewu ba mbanuami, ba ö''omusoi''ö tödö fefu hadia ia, nisöndrau föna Lowalangiu, Yehowa.[6]', '["Faigi 14:23"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 19, 'Ba faigi sibai, fa böi ö''ositengagö nono Lewi andrö, götö wa''anau nosou ba danömi.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 20, 'Ba ebolo dania danöu, ibe''e Lowalangiu, Yehowa, na itörö nifabu''unia khöu, ba na ömane dania: Omasido ndriwo! me no mamio-mio dölö-tölöu ba da''ö, ba hana na ö''a ndriwo, ha wa''oya zomasi''ö.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 21, 'Ba na no abölö aröu naha andrö, nituyu Lowalangiu, Yehowa, ba wamonahia töinia ba da''ö, ba taba-taba, si mane niŵa''ögu khöu, saŵimö ba biri-birimö, nibe''e Yehowa khöu, ba a ia, ba nahiau andrö, ha wa''oya zomasi''ö.', '["MozIII 17:11"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 22, 'Si mane na la''a nago ba böhö wemangau ya''ia; he si ra''iö, ba he si lö fa''ara''iö, ba faoma tola la''a wöfö.', '["MozIII 17:11"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 23, 'Ba böi awu''a, wa böi manö ö''a ndro; me no noso ndro andrö, ba lö tola öfao wemanga noso, na ö''a nösi.[7]', '["MozIII 17:11"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 24, 'Lö tola ö''a, öfanuwagö idanö ba danö tou.', '["MozIII 17:11"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 25, 'Lö tola ö''a, ena''ö sohahau dödö ndra''ugö ba iraonou furiu, na ö''o''ö zatulö, wamaigi Yehowa.', '["MozIII 17:11"]', NULL),
  (3445146, 'OT', 'Moze V', 12, 26, 'Ba hadia nibe''eu ame''ela ni''amoni''ö ba sumange amabu''ula li andrö khöu, ba ba naha andrö, nituyu Yehowa, ö''ohe,', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 27, 'ba ba naha wame''e sumange khö Lowalangiu, Yehowa, öbe''e zumange nitunu andrö khöu, ösi ba do, ba do zumange nitunu andrö khöu, ba nifaduwa ba naha wame''e sumange khö Lowalangiu, Yehowa; ba ösi, ba tola ö''a.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 28, 'Töngöni goroisa andrö fefu, nifa''emagu khöu, ba o''ö, ena''ö lö mamalö-malö, wa sohahau tödö ndra''ugö, fabaya onou furiu dania, na ölau zatulö ba si sökhi, wamaigi Lowalangiu, Yehowa.', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 29, 'Ba na ihori fönau soi niha andrö Lowalangiu, Yehowa, soi si möi''ö mutimba, ba na no ötimba ira ba na no ahono ndra''ugö ba danöra,', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 30, 'ba angelama, fa böi elungu ndra''ugö, ba wolo''ö huku khöra, na no muhori ira fönau, ba fa böi özofu-zofu Lowalangira andrö, fa böi ömane: Hewisa atö wamosumange soi andrö Lowalangira, ena''ö umanö göi wolau?', '[]', NULL),
  (3445146, 'OT', 'Moze V', 12, 31, 'Lö tola ömanö wolau ba khö Lowalangimö, Yehowa; nilaura khö Lowalangira sa, ba oi sogoro Yehowa ba oi si fatuwu khönia, onora matua na''i ba onora alawe, ba latutunu ö Lowalangira.[8]', '["Faigi 18:9"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 1, 'Fefu goroisa andrö, nibe''egu khömi, ba mitöngöni, ba wolo''ö ya''ia; böi minönö, ba böi miwuwu.', '[]', NULL),
  (3445164, 'OT', 'Moze V', 13, 2, 'Na so zi maoso ba khömi sama''ele''ö, ba ma sangifi, sangombakha khöu tandra ba ma ila-ila,[1]', '["Mat 7:15"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 3, 'ba na itörö tandra andrö ba ma ila-ila andrö, ni''ombakha''önia khöu, wanguma''ö: Data''o''ö Lowalangi bö''ö — [Lowalangi] si lö örai mila — ba tafosumange!', '["Mat 7:15"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 4, 'ba böi fondrondrongo li zama''ele''ö andrö, ba he na sangifi, me no fanandraigö Lowalangimi, Yehowa, ya''ami, ba wamaigi, na moroi si''aikö ba dödömi mi''omasi''ö Lowalangimi, Yehowa, ba na moroi si''aikö ba gera-erami.', '["Mat 7:15"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 5, 'Khö Lowalangimi, Yehowa, mi''o''ö, mi''ata''ufi ia, mi''o''ö goroisania ba mifondrondrongo linia, ya''ia nifosumangemi, ba khönia molemba ami.', '[]', NULL),
  (3445164, 'OT', 'Moze V', 13, 6, 'Ba sama''ele''ö andrö ba ma zui sangifi andrö, ba nibunu, me no ifarou niha ba wolaŵa Lowalangimi, Yehowa, si no mangeheta ya''ami ba danö Miserayi, si no mangefa''ö ya''ugö ba zi no möi''ö sawuyu, ba wamaelungu ya''ugö, ena''ö öröi lala andrö, niŵa''ö Lowalangiu, Yehowa, khöu fanörö; tobali öhori zi lö sökhi ba khömi.[2]', '["Faigi 18:20; Yer 28:16"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 7, 'Na so zamowöhö ya''ugö, nibini''ö, he na talifusöu, ono ninau, ba he na onou matua, ba he na onou alawe, ba he na fo''omou, nitalaguimö bagi, ba he na si fahuwu khöu, somasi''ö, timba nosou, na imane khöu: Talabu, tafosumange Lowalangi niha bö''ö! — [Lowalangi] si lö mirai mi''ila, he ira tuau mege,[3]', '["Faigi 17:2"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 8, 'Lowalangi soi andrö, si tefasui ya''ami, he ba zahatö, ba he ba zaröu, i''otarai wondrege danö, numalö ba wondrege tanö sa —', '["Faigi 17:2"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 9, 'ba böi o''ö, böi fondrondrongo linia; ba böi ahakhö dödöu, wamaigi ya''ia, böi alimagö ia khöu ba böi bini''ö horönia,', '["Faigi 17:2"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 10, 'öbunu ia; tangau zi oföna tohare khönia, ba wamunu ya''ia, ba awena dania danga zato fefu.', '["Faigi 17:2"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 11, 'Ötebu kara ia, wamunu ya''ia, me no i''alui wamabali ya''ugö khö Lowalangiu, Yehowa, si no mangeheta ya''ugö ba danö Miserayi, ba zi no möi''ö sawuyu.', '["Faigi 17:2"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 12, 'Ba yalarongo Iraono Gizeraeli fefu, ena''ö ata''u ira, fa böi sa''ae falukha ba khömi zama-zökhi horö si mane da''ö.[4]', '["Faigi 19:20"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 13, 'Na örongo, ba mbanua andrö, heza, nibe''e Lowalangiu, Yehowa nahiau,', '[]', NULL),
  (3445164, 'OT', 'Moze V', 13, 14, 'no maoso niha si lö ngaroro, banuami, ba no lafowöhö mbanuara, wanguma''ö: Talabu, tafosumange Lowalangi bö''ö! — [Lowalangi] si lö mirai mila —', '[]', NULL),
  (3445164, 'OT', 'Moze V', 13, 15, 'ba haogö wanekhegö, alu-alui sibai, ba na oroma dania, wa tenga faya, wa no telau ba khömi zogoro ita andrö,', '[]', NULL),
  (3445164, 'OT', 'Moze V', 13, 16, 'ba öbunu mbanua andrö si''öli, ölakha''ö mbanua andrö, awö nösinia fefu, awö guriföra, si''öli.', '[]', NULL),
  (3445164, 'OT', 'Moze V', 13, 17, 'Fefu hadia ia zi möi ba dangami ba mbanua andrö, ba ö''owuloi baewali sebolo khöra, ba ötunu mbanua, fabaya nihalömi andrö, fefu, sumange Lowalangiu, Yehowa, sa''oi so, ba ya hili-hili adudula ia, si lö tebulö, böi yatetaru''ö sa''ae.', '[]', NULL),
  (3445164, 'OT', 'Moze V', 13, 18, 'Böi falemba ba dangau hadia ia nilakha''ö andrö, ena''ö alö wönu Yehowa andrö, si no abölö-bölö, ba ena''ö ahakhö dödönia ndra''ugö, ba ena''ö ato ami, ibe''e, ba wa''ahakhö dödönia andrö, si mane nifabu''unia khö ndra tuau, si no möi ba hölu ia,[5]', '["Faigi 7:26"]', NULL),
  (3445164, 'OT', 'Moze V', 13, 19, 'na öfondrondrongo li Lowalangiu, Yehowa, wolo''ö oroisania andrö fefu, nifa''emagu khöu ma''ökhö, awö wolau satulö, wamaigi Lowalangiu, Yehowa.', '["Faigi 7:26"]', NULL),
  (3445173, 'OT', 'Moze V', 14, 1, 'Ono Lowalangimi, Yehowa, ami; ba böi mikhoi nösimi, na so zi mate ba böi mitöwö mbumi yaŵa gangango.[1]', '["MozIII 19:28","MozII 19:6"]', NULL),
  (3445173, 'OT', 'Moze V', 14, 2, 'No soi ni''amoni''ö khö Lowalangiu, Yehowa, ndra''ugö, ba no ya''ugö nituyu Yehowa ba niha bö''ö fefu ba guli danö, ena''ö khönia ndra''ugö, soi tana khönia.[2]', '["MozIII 19:28","MozII 19:6"]', NULL),
  (3445173, 'OT', 'Moze V', 14, 3, 'Böi a hadia ia zogoro ita!', '["MozIII 11:2 b.t."]', NULL),
  (3445173, 'OT', 'Moze V', 14, 4, 'Da''ö zaliŵa-liŵa ba danö si tola mi''a:', '["MozIII 11:2 b.t."]', NULL),
  (3445173, 'OT', 'Moze V', 14, 5, 'Saŵi ba biri-biri ba nambi, ba böhö ba nago ba öröbao ba felandru ba bate ba selandra ba böhö dandri.[3]', '["MozIII 11:2 b.t."]', NULL),
  (3445173, 'OT', 'Moze V', 14, 6, 'Fefu zi öfa ahe ba si no fabali sa''a si dombua ba samomendrua fonganga göra, ba zi öfa ahe andrö, ba tola mi''a.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 7, 'Ba ba zamomendrua fonganga göra ba ba zi no alua fabali sa''a, ba da''ö zi lö tola mi''a: Ondra ba kawelu ba kelindri; lafomendrua sa wonganga göra ba tenga si no fabali sa''a — si ra''iö ira miŵa''ö;', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 8, 'ba bawi; noa sa si fabali sa''a ia, ba tenga samomendrua fonganga gönia — si ra''iö ia miŵa''ö. He ösinia ba he amatelania, ba lö tola mibabaya.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 9, 'Ba da''ö zi tola mi''a saliŵa-liŵa ba nidanö, fefu: Fefu zi so fere-fere ba huna-huna, ba tola mi''a:', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 10, 'ba ba zi lö ferfere ba si lö hunhuna, ba sambua lö''ö si tola mi''a; si ra''iö ira miŵa''ö.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 11, 'Fefu wofo, si tenga si ra''iö, ba tola mi''a;', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 12, 'ba da''ö zi lö tola mi''a: Moyo ba hela ba razö wali,', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 13, 'ba sayowa ba ala-ala ba fefu motöi hela nasi,', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 14, 'ba fefu motöi gaga,', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 15, 'ba fofo ondra ba katawaena ba samari ba fefu motöi fötö.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 16, 'Ba tugöu ba lamuhu ba meu,', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 17, 'ba engangi ba bangau ba belibi,', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 18, 'ba laki-laki ba fefu motöi kotoli ba meragai ba bögi.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 19, 'Fefu ngawalö zaliŵa-liŵa ba danö so''afi, ba salakha miŵa''ö; lö tola te''a.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 20, 'Fefu wofo, si tenga si ra''iö, ba tola mi''a.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 21, 'Hadia ia gamatela, ba lö tola mi''a; ba niha bö''ö, si fatewu ba mbanuami ba hana na öbe''e, önia, ba he na öbe''e önia, ba he na ö''amawa ba niha bö''ö, ba hana; me no soi ni''amoni''ö khö Lowalangiu, Yehowa, ndra''ugö. Ono mbiri-biri, ba böi rino ba nösi zusu ninania[4]', '["MozII 23:19"]', NULL),
  (3445173, 'OT', 'Moze V', 14, 22, 'Ba mbua zinanöu ba danö fefu, ba öhalö zambua ni''ofulu, ero röfi,[5]', '["MozIII 27:30","Faigi 12:18"]', NULL),
  (3445173, 'OT', 'Moze V', 14, 23, 'ba föna Lowalangiu, Yehowa, ba naha andrö, nituyunia, ba wamonahia töinia ba da''ö, ö''a zi sambua ni''ofulu andrö, bua nowi khöu ba agu ba fanikha khöu ba si a''a nono zaŵi ba si a''a nono mbiri-biri khöu, ba wamamaha ya''ugö ba wangata''ufi Lowalangiu, Yehowa, götö wa''anau nosou.[6]', '["MozIII 27:30","Faigi 12:18"]', NULL),
  (3445173, 'OT', 'Moze V', 14, 24, 'Ba na abölö aröu öŵa''ö, na tebai ö''ohe ba da''ö, me no aröu naha andrö, nituyu Lowalangiu, Yehowa, nahia döinia, ba na no ifahowu''ö ndra''ugö Lowalangiu, Yehowa,', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 25, 'ba be''e böli gana''a, ba ohe gana''a andrö, böi taya, ba ae ba naha andrö, nituyu Lowalangiu, Yehowa,', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 26, 'ba öli hadia ia zomasi''ö — ana''a andrö be''e böli — saŵi ba biri-biri ba agu ba hadia nibadu na, sabe''e, ba hadia ia fefu zomasi''ö, ba manga''ö ba da''ö föna Lowalangiu, Yehowa, ba ya''omuso dödöu, awö zoroiyomou fefu.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 27, 'Ba böi olifugö''ö ba da''ö nono Lewi, si so ba khömi, me lö khönia tanö, lö tana khönia, ba ngaimö.', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 28, 'Ba na no irugi medölu fakhe, ba ö owuloi zi sambua ni''ofulu nisöndrau ba ndröfi da''ö, fefu, öbe''e tou ba nahiamö,', '[]', NULL),
  (3445173, 'OT', 'Moze V', 14, 29, 'ena''ö möi nono Lewi andrö, si lö tanö, si lö tana khöra, ba ngaimö, awö niha bö''ö andrö, ba si lö ama, si lö ina, awö lakha mbanua, si so ba khömi, ba ena''ö la''abusoi''ö ira, ena''ö ifahowu''ö ndra''ugö Lowalangiu, Yehowa, ba nilaumö andrö fefu, halö-halöŵö dangau andrö.', '[]', NULL),
  (3445218, 'OT', 'Moze V', 15, 1, 'Ba na no irugi mewitu fakhe, ba milau ndröfi wangefa.[1]', '["Yer 34:14"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 2, 'Ba mimane ba wangefa andrö: Dozi sosugilö, ba böi sa''ae lasugi nibe''era nifalali khö nawöra; böi lasasagö nawöra iwara, me no mufarongogö wangefa andrö khö Yehowa.', '["Yer 34:14"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 3, 'Niha bö''ö, ba hana na ösasagö, ba sugilöu ba niwami, ba ölulu.', '["Yer 34:14"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 4, 'Ba lö''ö sa si numana ba khömi dania; ifahowu''ö sibai sa''ae ndra''ugö dania Yehowa, ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu, tana khöu ba tana ba madoumö dania, ena''ö ö''okhögö,', '[]', NULL),
  (3445218, 'OT', 'Moze V', 15, 5, 'asala öfondrondrongo sibai li Lowalangiu, Yehowa, wanöngöni oroisa andrö fefu, nifa''emagu khöu ma''ökhö, ba wolo''ö ya''ia.', '[]', NULL),
  (3445218, 'OT', 'Moze V', 15, 6, 'No''a sa ibe''e khöu howu-howu andrö Lowalangiu, Yehowa, si mane nifabu''unia khöu, tobali oya soi nibe''eu nifalali; ba ya''ugö, ba alakha lö öfalali gana''a, ba oya soi dania zi so barö mbawau; ba lö''ö sa si möi ndra''ugö barö mbawa.[2]', '["Faigi 28:12"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 7, 'Na so ba khömi zi numana, iwami, ha niha, ba mbanuami, heza, ba danömi andrö, nibe''e Lowalangimi, Yehowa, khömi, ba böi zi lö ahakhö dödöu, ba böi gokhöi dangau ba niwami andrö, si numana,[3]', '["MozIII 25:35; YohI 3:17"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 8, 'öbokai dangau khönia, ba ya aoha gölöu wame''e nifalali khönia, ha wa''ebua zoguna khönia, ba wa''ambö andrö khönia, si no göna ia.', '["MozIII 25:35; YohI 3:17"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 9, 'Ba angelama, fa böi tumbu ba dödöu gera-era si lö sökhi, fa böi ömane dödöu: No ahatö ndröfi si fitu andrö, döfi wangefa! ba fa böi afökhö dödöu wamaigiu iwami andrö, si numana, fa lö öbe''e khönia, ba na i''angaröfi li dania Yehowa, ba khömö andrö, ba tobali horöu.', '["Mat 5:42; Luk 6:35","Mat 26:11; Yoh 12:8"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 10, 'Öbe''e khönia ba böi abua gölöu wame''e khönia; börö sa wolau si manö, wa ifahowu''ö dania ndra''ugö Lowalangiu, Yehowa, ba nilaumö fefu, hadia ia, halö-halöŵö dangau.[4]', '["Mat 5:42; Luk 6:35","Mat 26:11; Yoh 12:8"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 11, 'Lö''ö sa aefa-aefa, wa so ba danö zi numana, andrö uŵa''ö khöu: böi abua gölöu wamokai tangau ba niwami andrö si tosasa ba si numana, ba danömi.[5]', '["Mat 5:42; Luk 6:35","Mat 26:11; Yoh 12:8"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 12, 'Na so zamawa ya''ia khöu, iwami; Heberaio, he ira matua ba he ira alawe, ba me''önö fakhe sawuyumö ia, ba ba ndröfi si fitu, ba ö''efa''ö ia.[6]', '["MozII 21:2"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 13, 'Ba na ö''efa''ö ia, ba böi fofanö ia lö noro danga,', '["MozII 21:2"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 14, 'öfonoro ia biri-biri khöu ba bua nowi ba agu, sabönö noronia, nifahowu''ö Lowalangiu, Yehowa, ya''ugö, ba öbe''e khönia ösa.', '["MozII 21:2"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 15, 'Ba ötörö tödöu wa no sawuyu ndra''ugö göi ba danö Miserayi no, awö wa no i''efa''ö ndra''ugö Lowalangiu, Yehowa; andrö uŵa''ö khöu da''ö ma''ökhö.', '["MozII 21:2"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 16, 'Ba na imane khöu: Lö edönado aefa khöu — börö wa''omasinia ndra''ugö ba soroiyomou fefu, me no ohahau dödönia yomo khöu —', '["MozII 21:6"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 17, 'ba halö wörögi, ba tögi dalingania ba mbawandruhö, ba sawuyumö ia, si lö mamalö-malö; ba he ba zawuyumö ira alawe, ba ömanö göi wolau.[7]', '["MozII 21:6"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 18, 'Böi afökhö khöu, na ni''efa''ö ia, noa sa timba zi darua mogazi enoni wohalöŵönia khöu zi me''önö fakhe andrö; ba tobali ifahowu''ö ndra''ugö Lowalangiu, Yehowa, ba nilaumö, fefu.', '[]', NULL),
  (3445218, 'OT', 'Moze V', 15, 19, 'Fefu nono si a''a, si matua, ono zaŵiu ba ono mbiri-biriu, ba ö''amoni''ö khö Lowalangiu, Yehowa. Si a''a nono zaŵiu, ba lö öfohalöŵö, ba ba zi a''a nono mbiri-biriu, ba lö tola öguti mbu.[8]', '["MozII 13:2","Faigi 12:5"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 20, 'Ba naha andrö nituyu Yehowa, ö''a ia, föna Lowalangiu, Yehowa, ero röfi, ba awöu zoroiyomou fefu.[9]', '["MozII 13:2","Faigi 12:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3445218, 'OT', 'Moze V', 15, 21, 'Ba na so khönia zi sala, ma fa''ombuyu-mbuyu döla, ba ma fa''au''a ba ma bö''önia sala sebua, ba lö tola öbe''e sumange Lowalangiu, Yehowa.[10]', '["MozIII 22:20","Faigi 12:10"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 22, 'Ba nahiamö ö''a zi manö, ba he si ra''iö ba he si lö fa''ara''iö, ba i''a, nifemanga nago ba ma böhö.', '["MozIII 22:20","Faigi 12:10"]', NULL),
  (3445218, 'OT', 'Moze V', 15, 23, 'Ha do zi lö tola ö''a, öfanuwagö idanö, ba danö tou.[11]', '["MozIII 22:20","Faigi 12:10"]', NULL),
  (3445220, 'OT', 'Moze V', 16, 1, 'Töngöni mbaŵa Abibi andrö, ba wolau fasa khö Lowalangiu, Yehowa; no ba mbaŵa Abibi iheta ndra''ugö ba danö Miserayi Lowalangiu, Yehowa, ba zi bongi.', '["MozII 12:2; MozIII 23:53 b.t."]', NULL),
  (3445220, 'OT', 'Moze V', 16, 2, 'Ba ötaba fasa khö Lowalangiu, Yehowa, mbiri-biri ba saŵi, ba naha andrö, nituyu Yehowa, ba wamonahia töina ba da''ö.[1]', '["MozII 12:2; MozIII 23:53 b.t."]', NULL),
  (3445220, 'OT', 'Moze V', 16, 3, 'Ba lö tola ö''a hadia ia ni''aisöni, awönia; fitu ngaluo wa''ara ö''a roti si lö mu''aisöni, roti ba wa''anumana; — me no soloi ndra''ugö ba danö Miserayi mege — ena''ö itörö tödöu mbaŵa wa''ahetamö ba danö Miserayi, sagötö ya''ugö.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 4, 'Fitu bongi wa''ara, ba lö tola falukha danömö roti ba mbanuami fefu, ba ösi nitabamö sumange, tanö owi, na luo si föföna andrö, ba lö tola tosai irege mahemolu mbanua.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 5, 'Ba fasa andrö, ba lö tola ölau ba mbanua heza, nibe''e Lowalangiu Yehowa khöu,', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 6, 'ba naha andrö, nituyu Lowalangiu, Yehowa, dania, ba wamonahia töinia ba da''ö, ötaba wasa andrö, tanö owi, na aekhu luo, ba wa''alaŵa luo saheta''ö ba danö Miserayi,', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 7, 'ba örino ba ö''a ba naha andrö, nituyu Lowalangiu, Yehowa, dania, ba si hulö wongi mahemolu ö, ba öfazaŵa''ö, ba wangawuli.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 8, 'Önö ngaluo wa''ara ö''a roti si lö mu''aisöni, ba na luo si fitu, ba owuloa khö Lowalangiu, Yehowa, ba lö tola öhalö hadia ia halöŵö ba da''ö.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 9, 'Fitu migu ö''erai; ba mböröta sibai wamasi öbörögö wangerai migu andrö, si fitu.[2]', '["MozIII 23:15"]', NULL),
  (3445220, 'OT', 'Moze V', 16, 10, 'Ba aefa da''ö, ba ölau gowasa migu andrö khö Yehowa, öbe''e zumange saoha gölö, nibe''e dangau, dali wa''ebua howu-howu andrö, nibe''e Lowalangiu, Yehowa, khöu.', '["MozIII 23:15"]', NULL),
  (3445220, 'OT', 'Moze V', 16, 11, 'Ba omuso dödöu föna Lowalangiu, Yehowa, ya''ugö ba onou matua ha onou alawe, ba sawuyumö, ira matua ba ira alawe, ba ono Lewi andrö, si so ba khömi, awö niha bö''ö andrö ba si lö ama, si lö ina, awö lakha mbanua, ba khömi, ba naha andrö, nituyu Lowalangiu, Yehowa, ba wamonahia töinia ba da''ö.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 12, 'Ba ötörö-törö tödöu, wa no sawuyu ndra''ugö ba danö Miserayi mege, ba ötöngöni gamakhoita andrö, ba wolo''ö ya''ia.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 13, 'Ba folaumö owasa nose daha geu, ba fitu bongi wa''ara, na no ö''ozaragö mbua nowi khöu, awö nösi mbua nagu.[3]', '["MozIII 23:34 b.t."]', NULL),
  (3445220, 'OT', 'Moze V', 16, 14, 'Ba somuso tödö ndra''ugö ba gowasa andrö khöu, ya''ugö ba onou matua ba onou alawe ba sawuyumö, ira matua ba ira alawe, ba ono Lewi andrö, awö niha bö''ö andrö ba si lö ama, si lö ina, awö lakha mbanua si so ba khömi.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 15, 'Fitu bongi wa''ara ölau, khö Lowalangiu, ba naha andrö, nituyu Yehowa dania; ifahowu''ö sa ndra''ugö Lowalangiu, Yehowa, ba mbua zinanöu fefu ba ba halö-halöŵö dangau fefu, andrö wa ö''omusoi''ö sibai dödöu.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 16, 'Medölu zi döfi la''oroma''ö ira föna Lowalangiu, Yehowa, dozi motöi matua ba khömi, ba naha andrö, nituyunia dania: ba gowasa roti si lö mu''aisöni ba ba gowasa migu andrö ba ba gowasa nose daha geu, ba föna Yehowa, ba lö ta''oroma''ö ita lö ta''ohe hadia ia;', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 17, 'si tola itaha ölönia i''ohe zamösana, dali howu-howu andrö, nibe''e Lowalangiu, Yehowa, khöu.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 18, 'Fefu mado ba dozi banua khöu, nibe''e Lowalangiu, Yehowa, khöu, ba öfataro khöu zanguhuku ba kumandru, sangatulö''ö fanguhuku niha sato.', '[]', NULL),
  (3445220, 'OT', 'Moze V', 16, 19, 'Böi fuyu''ö huku, böi ebua dödöu zambuana, böi a gana''a; ö ana''a andrö, ba abösi zatua-tua ibe''e, ba ifuyu''ö huhuo satulö.[4]', '["MozII 23:8","Mat 6:33"]', NULL),
  (3445220, 'OT', 'Moze V', 16, 20, 'Ha satulö öfaigi, ena''ö auri ndra''ugö ba ena''ö lö aefa khöu danö andrö, nibe''e Lowalangiu, Yehowa, khöu.[5]', '["MozII 23:8","Mat 6:33"]', NULL),
  (3445220, 'OT', 'Moze V', 16, 21, 'Böi taru''ö khöu geu ni''amoni''ö, hadia ia ngawalö geu, ba ngai naha wame''e sumange andrö, khö Lowalangiu, Yehowa, nifa''anömö khöu,', '["MozII 23:8","Mat 6:33"]', NULL),
  (3445220, 'OT', 'Moze V', 16, 22, 'ba he gowe si fatuwu khö Lowalangiu, Yehowa, ba böi taru''ö.', '["MozII 23:8","Mat 6:33"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 1, 'Böi be''e sumange Lowalangiu, Yehowa, zaŵi ba ma biri-biri, si so sala, hadia ia zi lö sökhi, me no sogoro Lowalangiu, Yehowa, da''ö.[1]', '["MozIII 22:20"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 2, 'Na falukha ba mbanuami andrö heza, nibe''e Lowalangiu, Yehowa, khöu, niha, he ira matua, ba he ira alawe, solau si lö omasi Lowalangiu, Yehowa, wanawö fawu''usa li andrö khönia,[2]', '["Faigi 13:6","Faigi 4:19"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 3, 'na möi ia mamosumange Lowalangi bö''ö ba na mangalulu khöra, ba ba luo ba ma ba mbaŵa ba ma ba ngahönö andrö fefu, ba mbanua si yaŵa, si tenga nitehegu,[3]', '["Faigi 13:6","Faigi 4:19"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 4, 'ba na te''ombakha''ö khöu, ba na tesöndra — na no musekhegö — si ndruhu, no mulau zi manö — sogoro ita — ba Ndraono Gizeraeli,', '["Faigi 13:6","Faigi 4:19"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 5, 'ba ö''ohe baero mbawa göli niha andrö, he ira matua, ba he ira alawe; solau si lö sökhi andrö, ba he ira matua, ba he ira alawe, ba ötebu kara, wamunu ya''ia.', '["Faigi 13:6","Faigi 4:19"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 6, 'Ba niŵa''ö zi darua, ba ma si datölu, si so ba mbörö, tebunu zi manö, na no mu''etu''ö huku, ba lö tola labunu ia, na ha samösa zi so ba mbörö.[4].', '["Faigi 19:15 Mat 18:16"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 7, 'Si so ba mbörö andrö zi börötaigö mamunu ya''ia, ba awena dania zato fefu, ba tobali öhori ba khömi zi lö sökhi andrö.', '["Faigi 19:15 Mat 18:16"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 8, 'Na so huhuo sabölö afökhö famatunö öŵa''ö, ma na fange''e mbörö ba ma famadöni hadia ia, ba ma fabagosa, huhuo ba mbanuami, ba fazaŵa''ö ba ae ba naha andrö nituyu Lowalangiu, Yehowa,', '[]', NULL),
  (3445231, 'OT', 'Moze V', 17, 9, 'dania, ba ötunö khö gere, ono Lewi ba ba zanguhuku andrö, si so na luo da''ö, ösofu lala, ba ya''ira zangombakha khöu he wisa huku.', '[]', NULL),
  (3445231, 'OT', 'Moze V', 17, 10, 'Ba ö''o''ö niŵa''öra, ni''ombakha''öra khöu ba naha andrö nituyu Yehowa; fefu nilaumö dania, ba dali sibai lala andrö, ni''ombakha''öra khöu.', '[]', NULL),
  (3445231, 'OT', 'Moze V', 17, 11, 'Lala andrö, ni''ombakha''öra khöu, ba huku andrö, ni''etu''öra öbe''e dali ba wolaumö, niŵa''öra andrö khöu, ba ötörö, böi hole''ö ndra''ugö, he ba gambölö, ba he gabera.', '[]', NULL),
  (3445231, 'OT', 'Moze V', 17, 12, 'Ba na so zi fayaŵa, si lö mamondrongo li gere andrö, si no so ba da''ö, enoni Lowalangiu, Yehowa, ba he li zangukuku andrö, ba si mate da''ö; öhori zi lö sökhi ba Ndraono Gizeraeli,', '[]', NULL),
  (3445231, 'OT', 'Moze V', 17, 13, 'ena''ö larongo sato fefu ba ena''ö ata''u ira, fa böi falukha zi fayaŵa.', '[]', NULL),
  (3445231, 'OT', 'Moze V', 17, 14, 'Na no örugi danö andrö, nibe''e Lowalangiu, Yehowa, khöu, na no ö''okhögö ba na no ahono ndra''ugö ba danö, ba na ömane dania: Da''ufataro khögu razo, högögu, si mane ba niha baero fefu, si tefasui ya''o,[5]', '["SamI 8:5"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 15, 'ba ha nituyu Lowalangiu, Yehowa, öfataro razo khöu. Iwami öfataro razo khöu; niha bö''ö, si tenga ya''ami, ba lö tola öfataro khöu.', '["SamI 8:5"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 16, 'Ba fa böi soya kudo ia ba böi yamu''ohe mangawuli ami ba danö Miserayi, ba wangoya''ö kudonia, me noa sa''ae iŵa''ö khömi Yehowa: Böi manö mifuli ami ba da''ö![6]', '["RazI 4:26","RazI 11:1 Yes 2:7"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 17, 'Ba böi yamu''oya''ö ndrongania, fa böi i''erogö [Yehowa], ba böi yamuhöna khönia wirö ba ana''a.[7]', '["RazI 4:26","RazI 11:1 Yes 2:7"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 18, 'Ba na no dumadao dania ia ba dadaoma razo, ba yamusura khönia zambua zura goroisa andre, khö gere ono Lewi andrö ihalö;', '["Yos 1:8"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 19, 'ba böi aefa-aefa khönia, ba ibaso-baso sagötö ya''ia, ena''ö ifamaha ia ba wangata''ufi Lowalanginia, Yehowa, ba ena''ö itöngöni daroma li goroisa andre, awö nifakhoi andrö, fefu, ba wolo''ö ya''ia,[8]', '["Yos 1:8"]', NULL),
  (3445231, 'OT', 'Moze V', 17, 20, 'fa böi fayaŵa ia ba niwania andrö, ba böi zi lö itörö goroisa andrö, böi yamuhole''ö ia, he ba gambölö, ba he ba gabera, ena''ö ara razo ia ba Ndraono Gizeraeli, he ya''ia, ba he ononia dania.', '["Yos 1:8"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 1, 'Ba gere ono Lewi andrö ba ba mado Lewi fefu, ba lö tebe''e danö, tana khöra, ondröita dania, si mane ba Ndraono Gizeraeli bö''ö; sumange Yehowa andrö, nifatörö ba galitö ba hadia ia dana khönia, mbalazora.[1]', '["Faigi 10:9; KorI 9:13","Hes 44:28"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 2, 'Tana khöra tanö, ba lö labe''e khöra ba ngai niwara andrö; no Yehowa dana khöra, si mane nifabu''unia khöra.[2]', '["Faigi 10:9; KorI 9:13","Hes 44:28"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 3, 'Ba da''ö zinehe ba gere, ba zato, ba zanaba sumange, he saŵi ba he biri-biri: Khö gere labe''e da''io ba simbi ba betu''a ebua.', '["Faigi 10:9; KorI 9:13","Hes 44:28"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 4, 'Fondrege zi sökhi mbua nowi khöu ba agu ba fanikha, ba he fondrege zi sökhi mbu mbiri-biri khöu, ba khönia öbe''e.', '["MozIV 18:6"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 5, 'Noa sa''ae ya''ia nituyu Lowalangiu, Yehowa, ba madomi andrö fefu, ena''ö lö mamalö-malö, wa ya''ia ba iraononia dania zangai-ngai halöŵö ba döi Yehowa.[3].', '["MozIV 18:6"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 6, 'Ba na so zi möi ba naha andrö, nituyu Yehowa, ono Lewi, si oroi mbanuami heza, ba Ndraono Gizeraeli fefu, ba zi so ia si fatewu, ba balazi manö ia, na möi ia,', '[]', NULL),
  (3445730, 'OT', 'Moze V', 18, 7, 'ba tola ihalö-halö halöŵö ba döi Lowalanginia Yehowa, si mane ira talifusönia ono Lewi, fefu, si no möi enoni Yehowa ba da''ö.', '[]', NULL),
  (3445730, 'OT', 'Moze V', 18, 8, 'Lafagölö-gölö wamaosa gö andrö, lö lai zi no so khönia, böli gondröita ndra amania.', '[]', NULL),
  (3445730, 'OT', 'Moze V', 18, 9, 'Na örugi danö andrö, nibe''e Lowalangiu, Yehowa, khöu, ba böi famaha''ö ba wolo''ö sogoro ita andrö, ba niha andrö.[4]', '["MozIII 18:3"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 10, 'Böi falukha ba khömi zamatörö ba galitö ononia matua ba ma ononia alawe, ba he si faeta ba he sanahö lawuo ba he sanaka [ulö] ba he si fakelemu;[5]', '["MozIII 18:21; 20:27; Yes 8:19","Mat 5:48"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 11, 'ba he sanaka, bö''önia, ba he samahede bekhu, ma bekhu waetasa, sanofu ba zi no mate, hadia ia.', '["MozIII 18:21; 20:27; Yes 8:19","Mat 5:48"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 12, 'Me no sogoro Yehowa dozi solau si manö, ba börö zogoro ia andrö, wa ihori ira fönau Lowalangiu, Yehowa.', '["MozIII 18:21; 20:27; Yes 8:19","Mat 5:48"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 13, 'Ha sambalö Lowalangiu Yehowa manö ö''olembai.[6].', '["MozIII 18:21; 20:27; Yes 8:19","Mat 5:48"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 14, 'Soi niha andrö sa, nitimbamö, ba lafondrondrongo niŵa''ö zanahö lawuo ba si faeta; ba khöu, ba lö itehe zi manö Lowalangiu, Yehowa.', '["MozIII 18:21; 20:27; Yes 8:19","Mat 5:48"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 15, 'I''asogö dania khöu zama''ele''ö Lowalangiu, Yehowa, oi ya''ami, iwami, sama''ele''ö si mane ya''odo; li da''ö dania mifondrondrongo.[7].', '["Mat 17:5; Yoh 1:46; HalZin 3:22; 7:37"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 16, 'Ba ahori itörö ni''andröu khö Lowalangiu, Yehowa, me luo walukhata ba gahe hili Horebi, me ömane: Sökhi na lö''ö sa''ae urongo li Lowalangigu, Yehowa, ba na lö''ö sa''ae u''ila galitö sebua andrö, fa lö matedo![8].', '["MozII 20:19"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 17, 'Ba imane khögu Yehowa:', '["Yoh 4:25; 6:14"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 18, 'Si ndruhu niŵa''öra! Sama''ele''ö u''asogö khöra, si mane ya''ugö; ba niwara uhalö; ba mbawania ube''e daroma ligu ba ya''ia zangombakha khöra fefu ni''oroi''ögu khönia;[9]', '["Yoh 4:25; 6:14"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 19, 'ba na so zi lö mamondrongo ligu andrö, ni''ombakha''önia, salahigu, ba ya''o zanofu li ba zi manö.', '["Yoh 4:25; 6:14"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 20, 'Ba na so zama''ele''ö, si lö ata''u managö töigu, wangombakha hadia ia, si lö niŵa''ögu fangombakha khönia, ma na töi Lowalangi bö''ö itötöi ba wehedenia — ba si mate zama''ele''ö si manö![10].', '["Faigi 13:5; Yer 14:14"]', NULL),
  (3445730, 'OT', 'Moze V', 18, 21, 'Ba ma ömane dödöu: Ba heza ma''ila, wa tenga niŵa''ö Yehowa, na so niŵa''ö hadia ia?', '[]', NULL),
  (3445730, 'OT', 'Moze V', 18, 22, 'Na iŵa''ö sama''ele''ö ni''oroi''ö Yehowa khönia, ba na lö itörö niŵa''önia, ba no tenga niŵa''ö Yehowa daroma li andrö. Fayaŵasa zama''ele''ö andrö wangombakha ya''ia; alakha lö ö''ata''ufi.', '[]', NULL),
  (3445731, 'OT', 'Moze V', 19, 1, 'Na ihori dania Lowalangiu, Yehowa, soi andrö, ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu, ba na no ötimba ira ba na no ahono ndra''ugö ba mbanuara ba ba nomora,', '["MozIV 35:10"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 2, 'ba tölu oniagö khöu banua ba danömi andrö, nibe''e Lowalangiu, Yehowa, khöu, okhötamö.[1]', '["MozIV 35:10"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 3, 'Öhaogö lala khöu, ba tanö andrö, nibe''e Lowalangiu, Yehowa, khöu, ba wangokhögö ya''ia, ba ö''otölu, ena''ö tola ba da''ö lasaŵa woloi dozi si no mamunu niha.', '["Faigi 4:42"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 4, 'Ba si mane ba zi no mamunu niha andrö, si tola manaŵa da''ö woloi, ba wangorifi ya''ia: Na so zamunu awönia, si lö mu''odödögö ba na lö fatiusa khönia, mege sa''ae,[2]', '["Faigi 4:42"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 5, 'ma na no fao khönia nawönia ba gatua, ba wolobö eu, ba na ibaha watonia tangania, ba wolobö eu, ba na adeha wato, na göna khö nawönia, famununia; niha si manö, ba hana na isaŵa zambua mbanua andrö, ba wangorifi ya''ia,', '["Faigi 4:42"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 6, 'fa böi igohi zamunu niha andrö solau balö, na saukhu tödö ia, ba fa böi ikhamö, na aröu, ba wamunu ya''ia, he ŵa''ae tenga manö huku famunu hukunia, me lö si fatiu ia khönia mege.', '["Faigi 4:42"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 7, 'Andrö uŵa''ö khöu da''e: Tölu ö''oniagö khöu banua.', '["Faigi 4:42"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 8, 'Ba na ebolo danöu ibe''e Lowalangiu, Yehowa, nifabu''unia khö ndra tuau, si no möi ba hölu ia khöra, na ma''asagörö ibe''e khöu danö andrö, nifabu''unia fame''e khö ndra tuau,', '[]', NULL),
  (3445731, 'OT', 'Moze V', 19, 9, 'ha megara öbe''e ba dödöu wolo''ö oroisa andrö, fefu, nifa''emagu khöu ma''ökhö, na lö mamalö-malö wangomasi''öu Lowalangiu, Yehowa, awö wanörö lala andrö, khönia, ba tölu tö önönö mbanua andrö, si tölu,', '[]', NULL),
  (3445731, 'OT', 'Moze V', 19, 10, 'ena''ö böi aduwa ndro zi lö horö, ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu, ba fa böi öhalö ba hulumö, horöu.', '[]', NULL),
  (3445731, 'OT', 'Moze V', 19, 11, 'Ba na so zanaŵa banua andrö, zambua, woloi, si no manarogö awönia, börö watiusa, na no itema ibözi, famunu,[3]', '["MozIV 35:16"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 12, 'ba lafahalö''ö ia ba da''ö satua mbanuara, ba labe''e ba danga zolau balö, ena''ö mate ia.', '["MozIV 35:16"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 13, 'Böi faigi-faigi ia, wangahakhösi tödö ya''ia, öhori ba Ndraono Gizeraeli ndro zi lö horö, ena''ö sohahau tödö ndra''ugö.', '["MozIV 35:16"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 14, 'Böi fawu''a nola nawöu, nitaru''ö ndra tua, ba zinga mbenuau, si möi khöu dania, ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu.[4]', '["Faigi 27:17; Yob 24:2; Amaed 22:28; 23:10"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 15, 'Si ha samösa, ba lö tola möi sasi, udu nisekhegö, na so hadia ia horö, ba ma ölalöŵa — hadia ia zala, si sala niha, ha niha ia; ba niŵa''ö zi darua ba ma si datölu aro huhuo.[5]', '["MozIV 35:30; Mat 18:16; Yoh 8:17; KorII 13:1; Hebr 10:28"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 16, 'Na so si maoso sasi sofaya, udu nawönia, ba wamöbögö khönia lalö, hadia ia,', '["Amaed 19:5; 21:28"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 17, 'ba ndramöi föna Yehowa zi darua andrö, si fagua-gua, föna gere ba föna zanguhuku, na luo da''ö,', '["Amaed 19:5; 21:28"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 18, 'ba ndramusekhogö sibai sanguhuku, ba na oroma, sasi sofaya sasi andrö, iböbögö zi lö duhu khö dalifusönia,', '["Amaed 19:5; 21:28"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 19, 'ba khönia mifatörö zomasi ia lafatörö khö dalifusönia andrö; öhori ba khömi zi lö sökhi andrö.[6]', '["Amaed 19:5; 21:28"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 20, 'Ba larongo niha bö''ö, ba ata''u ira, ba lö''ö sa''ae lalau zi lö sökhi si mane da''ö, ba khömi.', '["MozII 21:24"]', NULL),
  (3445731, 'OT', 'Moze V', 19, 21, 'Böi ahakhö dödöu wamaigi niha: noso wangali noso ba hörö wangali hörö ba boha wangali mboha ba tanga wangali danga ba ahe wangali gahe![7]', '["MozII 21:24"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 1, 'Na möi''ö musuwö nemaliu ba na ö''ila kudo ba kureta ba sabölö khöra, sato moroi khömi, ba böi ata''ufi ira, me itolo ndra''ugö Lowalangiu, Yehowa, solohe miyaŵa ya''ugö moroi ba danö Miserayi.', '[]', NULL),
  (3445735, 'OT', 'Moze V', 20, 2, 'Ba na milau sa''ae khöra, ba yamufa''aso ia ere, ba yamuhede ba zato,', '["Faigi 1:21"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 3, 'imane khöra: Mifondrondrongo, ya''ami Iraono Gizeraeli! Si möi manuwö emalimi ami ma''ökhö; mi''abe''e''ö dödömi, böi ata''u, böi manizi-nizi ami ba böi tokea ami khöra;[1]', '["Faigi 1:21"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 4, 'fao sa''ae khömi Lowalangimi, Yehowa, ba wanuwö emalimi, fönami, ba ba wame''e fa''abölö khömi.', '["Faigi 1:21"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 5, 'Ba lamane kumandru ba zanuwö: Ha niha zi no molau omo, si lö mu''amoni''ö na, ba hana na iheta ia, hana na mangawuli, fa böi mate ia ba wasöndrata, ba fa böi niha bö''ö zi amoni''ö [omonia].', '["MozIII 19:23","Faigi 24:5"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 6, 'Ba ha niha zi no mamazökhi kabu nagu, si lö mu''a bua na, ba yamuheta ia, yamangawuli, fa böi mate ia ba wasöndrata, ba fa böi niha bö''özi manga mbua.[2]', '["MozIII 19:23","Faigi 24:5"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 7, 'Ba ha niha zi no mamaigi niha, si lö muhalö na, ba yamuheta ia, yamangawuli, fa böi mate ia ba wasöndrata, ba fa böi niha bö''ö zangai [alawe andrö].[3]', '["MozIII 19:23","Faigi 24:5"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 8, 'Ba lamane na ira kumandru ba zanuwö: Ha niha zata''u ba satalö tödö, ba yamuheta ia, yamangawuli, fa böi atalö göi dödö dalifusönia, si mane tödönia, ibe''e.[4]', '["Sanguhuk 7:3"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 9, 'Ba na no awai wehede ndra kumandru ba zato, ba lafataro sangoloi''ö sato gumandra andrö.', '["Sanguhuk 7:3"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 10, 'Na mamasui banua ndra''ugö ena''ö, ba öwa''ö khöra wangatulö ua.', '["Yos 8:27"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 11, 'Ba na latehe wangatulö andrö, na labokai khöu mbawa göli ba öbe''e same''e-me''e beo khöu mbanua andrö fefu ba si so barö mbawau.', '["Yos 8:27"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 12, 'Ba na lö edöna ira wa''atulö, na omasi ira fasuwö khöu, ba öfasui mbanua,', '["Yos 8:27"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3445735, 'OT', 'Moze V', 20, 13, 'ba na no ibe''e ba dangau ia Lowalangiu, Yehowa, ba öbunu si''öli ndra matua ba mbanua bakha, fefu,', '["Yos 8:27"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 14, 'ba ira alawe ba iraono ba urifö ba hadia ia fefu ba mbanua bakha, fefu zahulu ami bakha, ba öhalö ahuluamö, ba ö''a zahulu ndra''ugö ba nemaliu andrö, nibe''e Lowalangiu, Yehowa, khöu.[5]', '["Yos 8:27"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 15, 'Si manö wolaumö ba mbanua andrö fefu, si no aröu khöu, si tenga si faböbö ba mbanua niha andre.', '["Faigi 7:2"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 16, 'Ba ba mbanua niha andre, nibe''e Lowalangiu, Yehowa, khöu, ba samösa lö ö''orifi niha;[6]', '["Faigi 7:2"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 17, 'ölakha''ö ira, Iraono Kheti ba Iraono Gamori ba Dawa Gana''ana ba Iraono Weresi ba Iraono Hewi ba Iraono Yebusi, si mane niŵa''ö Lowalangiu, Yehowa, khöu.', '["Faigi 7:2"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 18, 'Fa böi lafahaö ami ba wolo''ö sogoro ita andrö, khöra, fefu, nilaura khö Lowalangira andrö, ba fa böi mifazökhi horö khö Lowalangimi, Yehowa.', '["Faigi 7:2"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 19, 'Na ara tebai atu''a ndra''ugö ba mbanua, nisuwömö, ba wangai ya''ia khöu, ba böi fakiko geu sowua ba ngainia, wolobö ya''ia; a mbuania, ba böi obö. Hadia, niha döla geu ba mbenua, fa ösuwö ia?', '["Faigi 7:2"]', NULL),
  (3445735, 'OT', 'Moze V', 20, 20, 'Ha töla geu, ni''ilau lö la''a mbua, ba hana na öfakiko, hana na ö''obö, ba wolau ba''a-ba''a khöu ba mbanua andrö nisuwömö, irege atu''a ami bakha.', '["Faigi 7:2"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 1, 'Na lasöndra nibunu ba mbenua, ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu, ba na lö mu''ila, ha niha zamunu ya''ia,', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 2, 'ba ndramöi zatua khömi ba sanguhuku ba lasu''a wa''aröu mbanua, si tefasui nibunu andrö.', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 3, 'Ba na no musöndra, he mbanua sahatö khönia, ba ndramuhalö zihene zaŵi satua mbanua andrö, ono zaŵi si lö murai mufohalöŵö, si lö mufokalo mbagi na;', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 4, 'ba la''ohe mitou ba ndraso nono zaŵi andrö salaŵa mbanua andrö, ba ndraso si so idanö si lö ogo''ö, daso si lö muhalö-halö ba si lö mutaru fakhe, ba ba da''ö ba ndraso andrö, lafatö mbagi nono zaŵi andrö.', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 5, 'Ba ndramu''ondrasi ere andrö, ono Lewi — me no ya''ira nitutuyu Lowalangiu, Yehowa, ena''ö enoninia ira ba ena''ö ba döi Yehowa mamahowu ira, ba balazi niŵa''öra ba wanguhuku hadia ia wamadöni ba hadia zokho[1] —', '["Faigi 17:9"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 6, 'ba dozi salaŵa mbanua andrö, sabölö ahatö ba nibunu no mege, ba lasasai dangara yaŵa nono zaŵi andrö, nifatö bagi, ba da''ö ba ndraso, ba latema lamane:', '["Faigi 17:9"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 7, 'Tenga tangama zame''e aduwa ndro andrö, ba höröma, ba tenga sangila.', '["Faigi 17:9"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 8, 'Be''e aefa, ya''ugö Yehowa, ba mbanuau Iraono Gizeraeli, ni''orifimö, ba böi be''e ba hulu mbanuamö Iraono Gizeraeli ndro niduwagö, si lö horö! Ba aefa khöra horö fange''e andrö,', '["Faigi 17:9"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 9, 'ba öhori ba khömi ndro andrö niduwagö, si lö horö, ena''ö ohahau dödöu, na ölau zatulö, wamaigi Yehowa.', '["Faigi 17:9"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 10, 'Na möi''ö fasuwö ba nemaliu ba na ibe''e ba dangau ira Lowalangiu, Yehowa, na mi''oloi''ö niha ösa,', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 11, 'ba na ö''ila ba ni''oloi''ö andrö ndra alawe si sökhi bawa, ba na tesao khöu wa''omasi, na omasi''ö öhalö dongau,', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 12, 'ba ohe ia baomou, ena''ö ifatöwö''ö ia, ba itaba za''ania,', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 13, 'ba ifalalini nukhania, nukhania mege, me lara''u ia, ba yaso yomo khöu, ba yamu''e''esi namania ba inania, sara waŵa wa''ara, ba na aefa da''ö, ba hana na möi''ö khönia, hana na öhalö ia, fa dongau ia.', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 14, 'Ba na lö''ö sa''ae omasi''ö ia, ba öbe''e aefa manö, ma''ifu lö tola ö''amawa ia, böli gana''a, lö tola ö''osawuyu ia, me no orudu''ö khönia.', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 15, 'Na so zi dombua donga ba na abölö i''omasi''ö zi sambua, na i''ositengagö zi sambua, ba na faoma mo''ono khönia, ono matua, he ni''omasi''ö andrö, ba he ni''ositengagö, ba na ono ni''ositengagö andrö zi a''a ndraononia,[2]', '["MozI 29:31"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 16, 'ba na ifaosa dania ba ndraononia gana''ania, ondröitania, ba lö tola itehe khö nono ni''omasi''ö andrö zinehe ba zi a''a, wangambösi ono ni''ositengagö andrö: me no ya''ia zi a''a,', '["MozI 29:31"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 17, 'si ndruhu si a''a, ono ni''ositengagö andrö, ba ibe''e si a''a, ifo dua winaeta zinemania ba zi so khönia, fefu, me no si a''a nisöndrania ba wa''abölönia, khönia zinehe ba zi a''a.', '["MozI 29:31"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 18, 'Na so zi so ono matua si lö ngaroro ba si lö mamondrongo li, si lö mame''e ba dödö na ifarou ia ba zi zökhi amania, ba ma inania, ba si lö molo''ö na göi, na no aefa la''otu''ö ia,', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 19, 'ba ndramutuyu da''ionia ira amania ba ndramudöni ba zalaŵa mbanuara, baero mbawa göli mbanua khöra,', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 20, 'ba lamane ba zalaŵa mbanuara: Onoma andre, ba no si lö ngaroro ba sabe''e tandro, lö ifondrondrongo lima, no sanibo-nibo ana''a ba si mabu-mabu tuo!', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 21, 'Ba ndramutebu kara ia banuara fefu, wamunu ya''ia; öhori ba khömi zi lö sökhi andrö, ba ndramurongo Iraono Gizeraeli fefu ba ndramu''ata''ufi.', '[]', NULL),
  (3445738, 'OT', 'Moze V', 21, 22, 'Na so nibunu, si no mamazökhi horö börö wamunu ya''ia, na no mutaŵi ia ba ndraha geu,', '["Yos 8:29; Gal 3:13"]', NULL),
  (3445738, 'OT', 'Moze V', 21, 23, 'ba böi laröi ba ndraha geu mbotonia ba zi bongi; na luo da''ö öko''o ia, me no ni''elifi khö Lowalangi nitaŵi, ba böi be''e ra''iö danömi andrö, nibe''e Lowalangiu, Yehowa, khöu. [3]', '["Yos 8:29; Gal 3:13"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 1, 'Na ö''ila zaŵi dalifusöu si suna ba ma biri-birinia, ba böi zi lö ötolo; ö''ohe mangawuli khö dalifusöu.[1]', '["MozII 23:4","Mat 12:11; Luk 14:5"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 2, 'Ba na aröu mbanua dalifusöu andrö, ba ma na lö ö''ila ha niha, ba öhalö khöu ua, öfonaha ba khöu, irege i''alui talifusöu andrö, ba öfuli khönia dania.', '["MozII 23:4","Mat 12:11; Luk 14:5"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 3, 'Ba ömanö göi na kalidenia, ba he na nukhania ba he hadia ia fefu, si no aekhu khö dalifusöu, na no ösöndra; lö tola lö örorogö.', '["MozII 23:4","Mat 12:11; Luk 14:5"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 4, 'Na ö''ila no alau galide dalifusöu, ba lala, ba ma saŵinia, ba böi zi lö ötolo, ölului khönia ba wamaoso.[2]', '["MozII 23:4","Mat 12:11; Luk 14:5"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 5, 'Ira alawe, ba böi yamu''onukha nukha ndra matua, ba ira matua, ba böi yamu''onukha nukha ndra alawe; dozi sa solau si manö, ba sogoro Lowalangiu, Yehowa.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 6, 'Na ö''ila ba zinga lala ba hogu geu, ba ma ba danö tou, gazuni wofo, si so ono, ba ma si so adulo ba na ifaukhu na nononia, ba ma adulo, ina, ba böi halö nina fabaya ono;', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 7, 'öfoloi nina ba öhalö khöu nono, ena''ö sohahau tödö ndra''ugö ba ena''ö anau nosou.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 8, 'Na molau omo ndra''ugö, ba öfotarali zagö khöu, fa böi tohare ba nomou horö fange''e öbe''e, na so zaekhu tou, moroi yaŵa, niha.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 9, 'Böi fodua balö zinanö ba kabu nagu khöu, fa böi tobali ni''amoni''ö fefu, he bua zinanö andrö, nitarumö, ba he bua nagu ba kabu andrö.[3].', '["MozIII 19:19; MozIV 18:27"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 10, 'Böi faedo ira zaŵi galide ba wamotokhi tanö.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 11, 'Böi fake nukha si dua balö bana, bu mbiri-biri ba tarafali, ba wanoso ya''ia mege.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 12, 'Öfobowo-bowo watalinga mbarumö sebua andrö, si öfa, barumö luni-lunimö andrö.[4]', '["MozIV 15:38"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 13, 'Na so zi no mangai ira alawe, ba na anuzu dödönia dania, na no orudu ia khönia,', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 14, 'na iböbögö khönia zi lö sökhi, na obou döinia ibe''e, wanguma''ö: No uhalö galawe andrö, ba orududo khönia, ba u''ila wa tenga ono alawe,', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 15, 'ba ndramuhalö ira ama nono alawe andrö dandra wa ono alawe ia, ba ndramu''ohe baero, ba mbawa göli ba zalaŵa mbanua,', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 16, 'ba imane dania ba zalaŵa ama nono alawe andrö: No ube''e ba niha andre nonogu, ba me anuzu dödönia iya''e,', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 17, 'ba iböbögö khönia horö, wanguma''ö: Tenga ono alawe nonou andrö, u''ila, ba ya''e dandra wa ono alawe nonogu! Ba ndramubologö lembe andrö föna zalaŵa mbanua.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 18, 'Ba noa da''ö, ba ndramuhalö niha andrö salaŵa mbanua andrö ba ndramuŵa''ö wangotu''ö ya''ia,', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 19, 'ba lakhau göi ia, otu rufia, ba wame''e khö nama galawe andrö. Noa sa ibe''e obou döi nono alawe Ndraono Gizeraeli [niha andrö], ba böi yatebulö dongania, ba sagötö ya''ia lö tola itibo''ö.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 20, 'Ba na si ndruhu niŵa''önia andrö, na tebai tefaduhu''ö, wa ono alawe zi bohou muhalö andrö,', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 21, 'ba la''ohe ba golayama namania galawe andrö, ba latebu kara ia banuara, wamunu ya''ia, me no horö sebua ifazökhi ba Ndraono Gizeraeli, me no mohorö ia baomo khö namania. Ömanö wangohori si lö sökhi ba khömi.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 22, 'Na so nira''u baewawö, na ihoröni ndronga zodonga, ba faoma mate ira, he ira matua, si horöni alawe andrö ba he ira alawe andrö. Ömanö wangohori si lö sökhi ba Ndraono Gizeraeli.[5]', '["MozIII 20:10"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 23, 'Na so zi falukha khö nono alawe, si no mufohu, bakha ba mbanua, ba na ihoröni,', '["MozIII 20:10"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 24, 'ba mi''ohe baero mbawa göli mbanua andrö, faoma darua ira, ba mitebu kara, wamunu ya''ira, ono alawe andrö, me lö ni''ekhugönia niha, bakha ba mbanua, ba ira matua andrö, me no ihoröni ndra alawe nawönia. Ömanö wangohori si lö zökhi ba khömi.', '["MozIII 20:10"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 25, 'Ba na ba danö falukha ndra matua andrö khö nono alawe andrö, si no mu''onihagö, ba na ilangögö manö, na ihoröni, ba ha ira matua, si horöni ya''ia, zi mate.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 26, 'Ba ono alawe andrö, ba böi lababaya; lö''ö sa nifazökhinia horö börö wamunu; ba zi manö, ba no timba na itema ibunu nawönia niha.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 27, 'Me no ba danö falukha ia khönia, ba ma no mu''ao nono alawe andrö, si no mufohu, ba ma lö si möi manolo ya''ia.', '[]', NULL),
  (3445745, 'OT', 'Moze V', 22, 28, 'Ba na so zi falukha khö nono alawe si lö mufohu na, ba na ira''u ba na ihoröni, ba na nira''u baewawö,[6]', '["MozII 22:16"]', NULL),
  (3445745, 'OT', 'Moze V', 22, 29, 'ba 50 rufia ibe''e khö nama nono alawe andrö niha andrö, si horöni ya''ia, ba labe''e khönia, dongania, me no ihoröni, ba sagötö ya''ia, ba lö tola itibo''ö.', '["MozII 22:16"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 1, 'Lö tola ihalö ndronga namania niha, lö tola ifahoi gambala namania.[1]', '["MozIII 18:8"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 2, 'Tebai banua Yehowa zi no aboto bazili ba he si no mukhai.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 3, 'Tebai banua Yehowa nono horö, ba he madou nono horö, he irege fulu nga''ötö, ba tebai banua Yehowa.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 4, 'Iraono Gamoni ba Iraono Moabi, ba tebai banua Yehowa, ba sagötö fa''ara, ba lö tola göi möi banua Yehowa madoura, he irege fulu nga''ötö,[2]', '["Neh 13:1","MozIV 22:5"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 5, 'me lö nifaondragöra ya''ami ba lala, me mi''otarai danö Miserayi, molohe gö ba idanö khömi, ba me no la''oni udumi Mbileamo andrö, ono Mbeori, banua Wetori ba Mezofotamia, ba wangelifi ya''ami.[3]', '["Neh 13:1","MozIV 22:5"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 6, 'Ba no lö edöna Lowalangiu, Yehowa, ifondrondrongo niŵa''ö Mbileamo andrö; no ibali''ö famahowu wangelifi andrö, khöu, Lowalangiu, Yehowa; me no i''omasi''ö ndra''ugö Lowalangiu, Yehowa.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 7, 'Sagötö ya''ugö, ba böi alui wa''ohahau dödöra ba fangorifira.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 8, 'Iraono Gedomo, ba böi ogorofi, me no talifusöu; ba Dawa Miserayi göi, ba böi ogorofi, me no so''ö ba danöra mege, amaedola zi fatewu;', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 9, 'si dua götö ma''uwura, ba hana na möi banua Yehowa.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 10, 'Na möi''ö manuwö emaliu, ba böi babaya hadia ia zi lö göna.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 11, 'Na so ba khömi zi no göna hadia ia, ba zi bongi, si no ra''iö ba da''ö, ba yamöi baero golombaseŵa, ba lö tola ifuli ia bakha;', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 12, 'irege no mondri ia, na tanö owi; awena dania tola ifuli ia ba golombaseŵa, na aekhu luo.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 13, 'Ba öfaigi göi khöu gamöila, baero golombaseŵa.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 14, 'Ba yaso ba wakakemö go''o-ko''o danö ba na möi''ö ba nidanö, baero, ba ökharu danö, ba öfuli öbalugö dania zi ta''unö andrö khöu.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 15, 'Me sanörö-nöröi olombaseŵamö Lowalangiu, Yehowa, ba wangorifi ya''ugö ba ba wame''e ba dangau emaliu; andrö wa ni''amoni''ö golombaseŵamö, fa böi i''ila ba khömö hadia ia zogoro ia, ba fa böi iheta ia khöu.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 16, 'Sawuyu sanaŵa ya''ugö, soloi khö zokhö ya''ia, ba böi fuli khö zokhö ya''ia.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 17, 'Yamu''iagö khöu, ba danöu, heza zatulö dödönia, ba mbanuami heza, somasi ia, ba lö tola öfakao ia.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 18, 'Ba nono alawe Ndraono Gizeraeli, ba lö tola falukha nibe''e nihoröni, ba ba nono matua, khöra ba lö tola falukha nibe''e sohorö.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 19, 'Böi ohe ba nomo Lowalangiu, Yehowa, mböli gölö ba wohorö ba he böli gölö nasu, ba gamabu''ula li, hadia ia, me no sogoro Lowalangiu, Yehowa, zi dua balö andrö göi.', '[]', NULL),
  (3445856, 'OT', 'Moze V', 23, 20, 'Ba dalifusöu, ba böi ŵa''ö hare, he hare gana''a, ba he hare gö ba he hare hadia ia fefu, nibe''e nifalali, nifohare.[4]', '["MozII 22:25"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 21, 'Ba niha bö''ö, ba hana na ötema hare, ba ba dalifusöu, ba lö tola öŵa''ö, ena''ö ifahowu''ö ndra''ugö Lowalangiu, Yehowa, ba nilau dangau, fefu, ba danö andrö, si möi''ö, ba wangokhögö ya''ia.', '["MozII 22:25"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 22, 'Na öfabu''u hadia ia khö Lowalangiu, Yehowa, ba böi aragö wanörö ya''ia, fa böi isugi''ö Lowalangiu, Yehowa, ba no masala ndra''ugö.[5]', '["MozIV 30:3; HalZin 18:18"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 23, 'Ba na lö öfabu''u hadia ia, ba lö horöu.', '["MozIV 30:3; HalZin 18:18"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 24, 'Hadia zi no alua ba liu, ba böi awu''a, ötörö nifabu''umö khö Lowalangiu, Yehowa, saoha gölö, si no alua baehau.', '["MozIV 30:3; HalZin 18:18"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 25, 'Na möi''ö ba kabu nagu khö nawöu, ba hana na ö''a mbua, ha wa''oya zomasi''ö irege abuso''ö ba ma''ifu lö tola öbe''e ba nahia khöu.', '["Mat 12:1"]', NULL),
  (3445856, 'OT', 'Moze V', 23, 26, 'Ba na ötörö nowi nawöu, ba hana na öburusi lai tangau; ba sabi, ba lö tola öfatörö ba zinanö nawöu.[6]', '["Mat 12:1"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 1, 'Na so zangai ira alawe, na i''owalu, ba na tebai i''omasi''ö dania, me no i''ila ba khönia zi fatuwu khönia, ba na no ibe''e khönia zura wangefa ba na no ifofanö baomonia,[1]', '["Mat 5:31; 19:7; Mar 10:4"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 2, 'ba na noa sa''ae möi donga niha bö''ö, me no aefa aheta ia baomonia,', '["Mat 5:31; 19:7; Mar 10:4"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 3, 'ba na no ibe''e göi zura wangefa, na no ifofanö göi baomonia ira matuania si samösa andrö, me anuzu dödönia göi khönia, ma na no mate ndrongania si samösa andrö, sangowalu ya''ia mege:', '["Mat 5:31; 19:7; Mar 10:4"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 4, 'ba lö tola ifuli ihalö ira matuania si föföna andrö, sangefa''ö ya''ia mege, ena''ö dongania zui, me no itehe, ra''iö ia labe''e, me no sogoro Yehowa zi manö, ba böi fatörö horö ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu, okhötau.', '["Mat 5:31; 19:7; Mar 10:4"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 5, 'Na so zi bohou mangowalu, ba akha lö fao ia ba wanuwö, ba lö lafo''ömö ia hadia ia; döfi aefa ia, fa böi mofanö-fanö ia, ena''ö i''omusoi''ö dödö ndra alawe andrö, nihalönia.[2]', '["Faigi 20:7"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 6, 'Böi lahalö gade lösu, ba he ha halu; amaedola lahalö gade noso, na lahalö da''ö.', '["MozII 21:16"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 7, 'Na te''ila zondra''u iwania, Iraono Gizeraeli, ba na i''osawuyu, ba ma na i''amawa, ba si mate zanagö andrö. Öhori ba khömi zi lö sökhi.[3]', '["MozII 21:16"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 8, 'Faigi-faigi sibai ba wamakao andrö, bou auri andrö; ötöngöni sibai niŵa''ö gere, ono Lewi, ba ö''o''ö; oroisagu andrö khöra, ba mitörö sibai.[4]', '["MozIII 13:2"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 9, 'Törö-törö tödö hadia nifatörö Lowalangiu, Yehowa, khö Miriya no, ba lala, me mi''otarai danö Miserayi![5]', '["MozIV 12:10"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 10, 'Na öbe''e khö nawöu nifalali, hadia ia, ba lö tola möi''ö ba nomonia mangai gade khönia.', '[]', NULL),
  (3445876, 'OT', 'Moze V', 24, 11, 'Tou ö''iagö, ba nibe''eu nifalali, ba i''ohe tou khöu gade.', '[]', NULL),
  (3445876, 'OT', 'Moze V', 24, 12, 'Ba na niha si numana ia, ba böi mörö''ö so ba dangau gade andrö nibe''enia;', '["MozII 22:26"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 13, 'na aekhu luo, ba öfuli khönia gade andrö, ena''ö ibe''e balu-balunia mbarunia sebua, na mörö ia, ba ena''ö ifahowu''ö ndra''ugö, ba niha satulö ndra''ugö iŵa''ö Lowalangiu, Yehowa.[6]', '["MozII 22:26"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 14, 'Enoni si numana ba sambö balazo, ba böi fakao, he na oi ya''ami, ba he na niha bö''ö, si so ba danömi, ba mbanuami misa.[7]', '["MozIII 19:13"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3445876, 'OT', 'Moze V', 24, 15, 'Ero owi öbe''e luonia, böi na''i öbase''ö wa''aekhu luo, me no si numana ia ba me humulu dödönia wanema, fa böi i''angaröfi li Yehowa, ba khömö andrö, ba fa böi tobali horöu.', '["MozIII 19:13"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 16, 'Böi mate nama börö ndraono, ba böi mate ndraono börö nama; ba horönia mate zamösana.[8]', '["RazII 14:6; Yer 30:31; Hez 18:20"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 17, 'Böi fuyu''ö huku, na so huhuo niha bö''ö ba ma na huhuo zi lö ama, si lö ina; ba böi halö gade mbaru lakha mbanua.[9]', '["MozII 23:9; Faigi 16:19"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 18, 'Törö-törö tödöu, wa no sawuyu ndra''ugö ba danö Miserayi mege, awö wa no i''efa''ö ndra''ugö ba da''ö Lowalangiu, Yehowa, andrö uŵa''ö khöu wolau si manö.', '["MozII 23:9; Faigi 16:19"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 19, 'Na öbasi mbua nowiu, ba na so zolifu''ö ba danö, fakhe, ba böi fuli''ö wangai; akha ö niha bö''ö ba ö zi lö ama, si lö ina ba ö lakha mbanua, ena''ö ifahowu''ö ndra''ugö Lowalangiu, Yehowa, ba nilau dangau, fefu.[10]', '["MozIII 19:9"]', NULL),
  (3445876, 'OT', 'Moze V', 24, 20, 'Ba na öteteu mbua falo khöu, ba böi alu-alui wo''u-wo''u ba ndraha misa; akha ö niha bö''ö, ba ö zi lö ama, si lö ina ba ö lakha mbanua.', '[]', NULL),
  (3445876, 'OT', 'Moze V', 24, 21, 'Ba na ö''ozaragö mbua nagu ba kabu khöu, ba böi ozaragö na göi wo''u-wo''u dania; akha ö niha bö''ö ba ö zi lö ama, si lö ina ba ö lakha mbanua.', '[]', NULL),
  (3445876, 'OT', 'Moze V', 24, 22, 'Törö-törö tödöu, wa no sawuyu ndra''ugö ba danö Miserayi mege; andrö uŵa''ö khöu wolau si manö.', '[]', NULL),
  (3446314, 'OT', 'Moze V', 25, 1, 'Na no mu''ohe ba rafe niha si fagua-gua ba na no mu''etu''ö huku, na no mube''e aefa zi lö horö ba na no mu''etu''ö huku zi so horö,', '[]', NULL),
  (3446314, 'OT', 'Moze V', 25, 2, 'ba na nibözi zi so horö andrö, ba yamuŵa''ö sanguhuku lafadölö tou, ba lahare''ö khönia, ba zi so sanguhuku, ndrohu-ndrohu ba zalania andrö.', '[]', NULL),
  (3446314, 'OT', 'Moze V', 25, 3, 'Öfa wulu zi tola iŵa''ö lahare''ö khönia, ba böi italu''i da''ö, fa böi te''o''aya dalifusöu, wamaigiu, na oya na baero ö lahare''ö khönia.[1]', '["KorII 11:24"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 4, 'Böi fosare''a göröbao samöbörö fakhe.[2]', '["KorI 9:9; TimI 5:18"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 5, 'Na so zorudu ba mbanua si fatalifusö, ba na mate zi samösa lö ono matua, ba böi yamöi nihalö niha bö''ö, baero, wo''omonia; solakha ya''ia andrö zi möikhönia, ihalö dongania, itörö khönia gömö zolakha andrö.[3]', '["MozI 33:8; Mat 22:24"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 6, 'Ba na mo''ono ia, ono matua si a''a, ba lafotöi ono zi mate andrö, fa böi taya döinia ba Ndraono Gizeraeli.', '["MozI 33:8; Mat 22:24"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 7, 'Ba na lö edöna ndra matua andrö ihalö lakhania, ba yamöi ba mbawa göli, ba zalaŵa, lakhania andrö, ba imane: Lö edöna ga''agu andrö i''orifi döi dalifusönia, ba Ndraono Gizeraeli; lö itörö khögu gömö zolakha andrö.[4]', '["Rut 4:6"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 8, 'Ba ndramufakaoni''ö ia salaŵa mbanuara andrö, ndrafahuhuo khönia, ba na lö alulu dödönia, na imane:', '[]', NULL),
  (3446314, 'OT', 'Moze V', 25, 9, 'Lö omasido uhalö ia, ba yamöi khönia lakhania, ba zi so salaŵa no mege, iheta mbadagahe ba gahenia zambua, ba idiloi mbawa, ba itema imane: Da''ö milau ba ndra matua fefu, si lö edöna mamonga''ötö talifusöra.', '[]', NULL),
  (3446314, 'OT', 'Moze V', 25, 10, 'Ba töi nga''ötönia ba Ndraono Gizeraeli sa''ae, ba "Nga''ötö zi lö badagahe."', '[]', NULL),
  (3446314, 'OT', 'Moze V', 25, 11, 'Na so zi fasöndra, si fatalifusö, ba na so ndra alawe zi samösa, ba wangefa''ö dongania ba danga zamago ya''ia, ba na ira''u wamatua da''ö,', '[]', NULL),
  (3446314, 'OT', 'Moze V', 25, 12, 'ba ö''eŵa dangania andrö, böi hakhösi tödö.', '[]', NULL),
  (3446314, 'OT', 'Moze V', 25, 13, 'Böi dombua zaga ba dokosa khöu, sambua zebua ba sambua zide-ide.[5]', '["MozIII 19:35"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 14, 'Ba böi dombua lauru baomou, sambua zebua ba sambua zide-ide.', '["MozIII 19:35"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 15, 'Saga satulö, si lö ambö, öfake, awö lauru satulö, si lö ambö, ena''ö anau nosou ba danö andrö, nibe''e Lowalangiu,yehowakhöu.', '["MozIII 19:35"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 16, 'Me no sogoro Lowalangiu,yehowa, dozi solau si manö, dozi sanörö si lö atulö.', '["MozIII 19:35"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 17, 'Törö-törö tödöu hadia nilau Ndraono Gamaleki andrö khöu, me mi''otarai danö Miserayi no.[6]', '["MozII 17:8"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 18, 'Wa lö la''ata''ufi Lowalangi, wangahawui ya''ugö ba lala, me si tebai sa''ae ndra''ugö, ba me no erege dödöu, wa fabali manö khöu fefu zi tebai andrö, si so moroi furi, labe''e.', '["MozII 17:8"]', NULL),
  (3446314, 'OT', 'Moze V', 25, 19, 'Ba na no ahono dania ndra''ugö ba danö, ibe''e Lowalangiu, Yehowa, ba danö andrö nibe''e Lowalangiu, Yehowa, khöu, ondröitamö ba madoumö dania, na no itimba nemali fefu, si tefasui ya''ugö, ba öhori ba danö Ndraono Gamaleki andrö, fabaya töira; böi olifugö''ö![7]', '["SamI 15:3"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 1, 'Na no örugi dania danö andrö, nibe''e Lowalangiu, Yehowa, khöu, okhötamö, na no ö''okhögö ba na no ahono''ö ba danö,', '["MozII 23:19"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 2, 'ba öhalö ösa zi a''a ngawalö mbua danö fefu, nisöndrau ba danöu andrö, nibe''e Lowalangiu, Yehowa, khöu, öbe''e ba ndraga ba möi''ö ba mbanua andrö, nituyu Lowalangiu, Yehowa, nahia döinia dania;[1]', '["MozII 23:19"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 3, 'ba ö''ondrasi gere, ere na luo da''ö, ba ömane khönia: Ufaduhu''ö ma''ökhö khö Lowalangiu, Yehowa, wa no urugi danö andrö, nifabu''u Yehowa fame''e khöda, si no möi ba hölu ia khö ndra tuada.', '["MozII 23:19"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 4, 'Ba yamutema ba dangau ndraga andrö ere, yamube''e föna naha wame''e sumange andrö khö Lowalangiu, Yehowa,', '["MozI 46:1"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 5, 'ba ötema ömane dania föna Lowalangiu, Yehowa: Dawa Garamo sanörö-nöröi tanö duagu mege ba isaŵa misi tou danö Miserayi, lö atoto zi fao khönia, ba si fatewu ia ba da''ö, ba tobali soi sebua ba da''ö, sato niha ba sabölö.[2]', '["MozI 46:1"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 6, 'Ba me la''osiwawöi ita Dawa Miserayi, me lafakao ita ba me lafohalöŵö ita halöŵö sabe''e,', '["MozI 46:1"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 7, 'ba ta''angaröfi li Yehowa, Lowalangi ndra tuada andrö, ba ifondrondrongo wangarö-ngaröda andrö Yehowa, ba i''ila wa''anumanada ba famakaoda ba fa''atosasada.', '["MozI 46:1"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 8, 'Ba iheta ita ba danö Miserayi Yehowa tangania sabe''e andrö ba ta''ionia andrö, si no mu''oro''ö, fa''abölönia sata''u ita, ba no fao dandra ba ila-ila.', '[]', NULL),
  (3446320, 'OT', 'Moze V', 26, 9, 'Ba no i''ohe ita ba da''e ba no ibe''e khöda danö andre, tanö zi falawu susu ba ŵe ŵani.', '[]', NULL),
  (3446320, 'OT', 'Moze V', 26, 10, 'Ba ya''e ni''ohegu, si a''a mbua danö andrö, nibe''eu khögu, ya''ugö Yehowa! Ba öbe''e khö Lowalangiu, Yehowa, ba mangalulu ndra''ugö khö Lowalangiu, Yehowa,', '[]', NULL),
  (3446320, 'OT', 'Moze V', 26, 11, 'ba ö''omusoi''ö dödöu ba howu-howu andrö fefu, nibe''e Lowalangiu Yehowa, khöu, ba awöu zoroiyomou fefu ba ono Lewi andrö ba niha bö''ö, si so ba khömi.', '[]', NULL),
  (3446320, 'OT', 'Moze V', 26, 12, 'Ba na no ahori dania öbe''e zi sambua ni''ofulu nisöndrau fefu, na döfi si tölu andrö, döfi nibe''e ni''ofulu andrö, na no öbe''e ba nono Lewi ba ba niha bö''ö andrö ba ba zi lö ama, si lö ina ba ba lakha mbanua, ena''ö la''a ba mbanuami ba ena''ö abuso ira,[3]', '["Faigi 14:28"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 13, 'ba ömane föna Lowalangiu, Yehowa: No uheta yomo ni''amoni''ö andrö, no ube''e ba nono Lewi ba ba niha bö''ö andrö ba ba zi lö ama, si lö ina ba ba lakha mbanua, no u''o''ö sibai goroisa andrö, nibe''eu khögu; sambalö lö nisawögu oroisamö, sambalö lö solifudo.', '["Faigi 14:28"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 14, 'Ma''ifu lö ni''agu me abu dödögu ba ma''ifu lö nihalögu, me si ra''iö ndra''odo ba ma''ifu lö nibe''egu fangasi. No ufondrondrongo goroisa Lowalangigu, Yehowa, no ahori u''o''ö ni''oroi''ömö khögu.', '["Faigi 14:28"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 15, 'Faigi mitou moroi ba nahiamö andrö, ni''amoni''ö, moroi ba zorugo, ba fahowu''ö mbanuau, Iraono Gizeraeli, awö danö andrö nibe''eu khöma, si mane niŵa''öu khö ndra tuama, si no möi''ö ba hölu, tanö si falawu susu ba ŵe ŵani.', '["Faigi 14:28"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 16, 'Ma''ökhö andre iŵa''ö khöu Lowalangiu, Yehowa, gamakhoita andrö, awö huku andrö ni''o''ö; ba töngöni sa''ae ba o''ö moroi si''aikö ba dödöu ba moroi si''aikö ba gera-erau!', '[]', NULL),
  (3446320, 'OT', 'Moze V', 26, 17, 'No örongo khö Yehowa ma''ökhö, wa edöna ia Lowalangiu ia, awö wa sanörö lala andrö khönia ndra''ugö, ba solo''ö nifakhoinia ba oroisania ba hukunia, ba samondrongo linia.', '[]', NULL),
  (3446320, 'OT', 'Moze V', 26, 18, 'Ba no iŵa''ö khöu ma''ökhö Yehowa, öfabu''u, wa soi tana khönia ndra''ugö, awö wa edöna''ö ö''o''ö goroisania fefu,[4]', '["MozII 19:5; Yes 43:1; Tit 2:14"]', NULL),
  (3446320, 'OT', 'Moze V', 26, 19, 'ena''ö alaŵa yaŵa niha bö''ö fefu, nifazökhinia, ndra''ugö ibe''e, nisuno ba ni''ebua''ö töi ba nifosumange, ba ena''ö soi ni''amoni''ö khö Lowalangiu, Yehowa, ndra''ugö, ena''ö itörö niŵa''önia andrö.', '["MozII 19:5; Yes 43:1; Tit 2:14"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 1, 'Ba labe''e li ba zato Moze ba salaŵa Ndraono Gizeraeli, lamane: Mi''o''ö goroisa andrö fefu, nifa''emagu khömi ma''ökhö!', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 2, 'Ba na no mi''ötö Yoridano, na no mirugi danö andrö, nibe''e Lowalangiu, Yehowa, khöu, ba ötaru''ö khöu gowe sebua, ö''afusi''ö bötua,[1]', '["Yos 4:3"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 3, 'ba ösura ba detenia daroma li goroisa andrö fefu; ha si''ai örugi si yefo, ena''ö ökhamö danö andrö, nibe''e Lowalangiu, Yehowa, khöu, ena''ö itörö nifabu''u Lowalangi ndra tuau, Yehowa, khöu, tanö si falawu susu ba ŵe ŵani.', '["Yos 4:3"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 4, 'Ha si''ai mi''ötö Yoridano, ba mitaru''ö gowe andrö, niŵa''ögu khömi ma''ökhö; ba hili Gebala mitaru''ö ba mi''afusi''ö bötua.', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 5, 'Ba öfa''anö göi naha wame''e sumange khö Lowalangiu, Yehowa, ba da''ö, naha wame''e sumange kara, si tenga nitotou si''öli;', '["MozII 20:25"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 6, 'kara si lö mutoto öbe''e naha wame''e sumange khö Lowalangiu, Yehowa, ba öbe''e zumange Lowalangiu, Yehowa, ba detenia, sumange nitunu,[2]', '["MozII 20:25"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 7, 'ba sumange fangorifi ötaba, ba ö''a ba da''ö, ba omuso dödöu föna Lowalangiu, Yehowa.', '["MozII 20:25"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 8, 'Ba ba dete gowe no mege, ba ösura daroma li goroisa andrö fefu, öhaogö wanura.', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 9, 'Ba humede Moze ba ere ono Lewi ba Ndraono Gizeraeli fefu, lamane: Mihonogö ami ba mifondrondrongo, ya''ami Iraono Gizeraeli! Ma''ökhö andre, ba no tobali banua Lowalangimi, Yehowa, ami;', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 10, 'ba mifondrondrongo sa''ae li Lowalangimi, Yehowa, ba mi''o''ö goroisania, awö nifakhoinia, nifa''emagu khöu maökhö.', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 11, 'Ba ibe''e li ba zato Moze, me luo da''ö, imane: Na no mi''ötö Yoridano, ba ndramu''iagö hili Garisi ösa,', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 12, 'ba wamahowu''ö sato, ya''ia mado Zimeoni ba mado Lewi ba mado Yuda ba mado Isasari ba mado Yosefo ba mado Mbeniyami;', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 13, 'ba tanö bö''ö andrö, ba ba hili Gebala la''iagö, ba wangelifi, ya''ia mado Rubeno ba mado Gado ba mado Gaseri ba mado Zebuloni ba mado Dano ba mado Nafetali.', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 14, 'Ba ono Lewi, ba latema la''ebua''ö lira, lamane ba Ndraono Gizeraeli fefu:', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 15, 'Ni''elifi zamazökhi adu nifofoe ba ma nifahele, nekhe-nekhe duka ba same''e ba nahania, nibini''ö! Ba latema dania li sato fefu, lamane: Yaduhu![3]', '["MozII 20:4"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 16, 'Ni''elifi zango''aya amania ba ma inania! Ba lamane sato fefu: Yaduhu![4]', '["MozII 21:17"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 17, 'Ni''elifi zamawu''a gowe nola khö nawönia! Ba lamane sato fefu: Yaduhu![5]', '["Faigi 19:14"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 18, 'Ni''elifi zamaelungu niha sau''a! Ba lamane sato fefu: Yaduhu![6]', '["MozIII 19:14"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 19, 'Ni''elifi zamuyu''ö huku, na so huhuo niha bö''ö ba huhuo zi lö ama, si lö ina, ba huhuo lakha mbanua; ba lamane sato fefu: Yaduhu![7]', '["MozII 23:6"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 20, 'Ni''elifi zi horöni donga namania! me no ibokai gambala khö namania. Ba lamane sato fefu: Yaduhu![8]', '["MozIII 18:8"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 22, 'Ni''elifi zi horöni hadia ia zaliŵa-liŵa ba danö! Ba lamane sato fefu: Yaduhu![9]', '["MozII 22:19"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 23, 'Ni''elifi zi horöni inania matuania! Ba lamane sato fefu: Yaduhu!', '[]', NULL),
  (3446330, 'OT', 'Moze V', 27, 24, 'Ni''elifi zamunu awönia, ba zi tobini! Ba lamane sato fefu: Yaduhu![11]', '["MozII 21:12"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 25, 'Ni''elifi zi manga gana''a, ba wamunu si lö horö! Ba lamane sato fefu: Yaduhu![12]', '["MozII 23:8"]', NULL),
  (3446330, 'OT', 'Moze V', 27, 26, 'Ni''elifi zi lö manörö taroma li oroisa andrö, wolo''ö ya''ia! Ba lamane sato fefu: Yaduhu![13]', '["Gal 3:10"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 1, 'Na lö tebulö dania wamondrongou li Lowalangiu, Yehowa, ba na ötöngöni sibai goroisania fefu, nifa''emagu khöu ma''ökhö, ba wolo''ö ya''ia, ba alaŵa yaŵa niha bö''ö ba guli danö fefu ndra''ugö ibe''e Lowalangiu, Yehowa,[1]', '["MozIII 26:3 b.t.; Faigi 26:19"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 2, 'ba möi khöu howu-howu andrö fefu, alua khöu, na ö''o''ö li Lowalangiu, Yehowa.', '["MozIII 26:3 b.t.; Faigi 26:19"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 3, 'Nifahowu''ö ndra''ugö yomo ba mbanua, ba nifahowu''ö baero ba danö.[2]', '["Faigi 7:13 b.t."]', NULL),
  (3448018, 'OT', 'Moze V', 28, 4, 'Nifahowu''ö dabinamö ba bua danö khöu, ba beto guriföu ba ono zaŵiu ba fo''ono mbiri-biriu.', '["Faigi 7:13 b.t."]', NULL),
  (3448018, 'OT', 'Moze V', 28, 5, 'Nifahowu''ö ndragamö, awö naha wamaruka roti khöu.', '["Faigi 7:13 b.t."]', NULL),
  (3448018, 'OT', 'Moze V', 28, 6, 'Nifahowu''ö ndra''ugö na so''ö, ba nifahowu''ö na mofanö''ö.', '["Faigi 7:13 b.t."]', NULL),
  (3448018, 'OT', 'Moze V', 28, 7, 'Yehowa zamözi tou fönau emaliu, si maoso udumö; ha sara lalara, na so ira, ba wanuwö ya''ugö, ba fitu rozi lalara, na moloi ira, öbe''e.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 8, 'Yamufao khöu howu-howu Yehowa, ba halasamö ba ba nilau dangau fefu, yamufahowu''ö ndra''ugö ba danö andrö, nibe''e Lowalangiu, Yehowa, khöu!', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 9, 'Yamubali''ö soi ni''amoni''ö ndra''ugö khönia Yehowa, si mane niŵa''önia khöu, si no möi ba hölu ia, na ö''o''ö goroisa Lowalangiu, Yehowa, ba na ötörö lala andrö khönia,', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 10, 'ena''ö la''ila niha baero, ba guli danö fefu wa no dali döi Yehowa mege, ba wamatörö töimö, ba ena''ö la''ata''ufi ndra''ugö!', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 11, 'Ba fahöna dania khöu zi sökhi, ibe''e Yehowa, he ono khöu ba he ono guriföu, ba he bua danö khöu, ba danö andrö, nifabu''u Yehowa fame''e khöu khö ndra tuau, si no möi ba hölu ia.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 12, 'Ibokai khöu Yehowa naha girö-girö andrö khönia, si no fahöna, banua si yaŵa andrö, ba wame''e teu ba danöu, na inötö, ba ba wamahowu''ö halöŵö dangau fefu, tobali ato niha nibe''eu nifalali, ba ya''ugö, ba alakha lö''ö manö mamalali''ö hadia ia.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 13, 'Ba ibe''e högö ndra''ugö Yehowa ba tenga i''o, ba itugu manöi ndra''ugö, ba lö''ö manö toulö ndra''ugö, na ö''o''ö goroisa Lowalangiu, Yehowa, andrö, nifa''emagu khöu ma''ökhö, na ötöngöni ba na ö''o''ö,', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 14, 'na ötörö fefu niŵa''ögu khöu ma''ökhö, na lö öhole''ö ndra''ugö, he ba gambölö, ba he ba gabera, ba wolo''ö ba Lowalangi bö''ö ba ba wamosumange da''ö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 15, 'Ba na lö ö''o''ö niŵa''ö Lowalangiu, Yehowa, niŵa''önia khöu, ba wolo''ö sibai oroisa andrö, awö nifakhoi andrö fefu, nifa''emagu khöu ma''ökhö, ba tohare khöu wangelifi andrö fefu, alua khöu dania.[3]', '["MozIII 20:14 b.t.; Dan 9:11"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 16, 'Ni''elifi ndra''ugö yomo ba mbanua ba ni''elifi baero ba danö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 17, 'Ni''elifi ndragamö ba ni''elifi naha wamaruka roti khöu.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 18, 'Ni''elifi dabinamö ba bua danö khöu ba ono zaŵiu ba fo''ono mbiri-biriu.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 19, 'Ni''elifi ndra''ugö na so''ö, ba ni''elifi na mofanö''ö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 20, 'Ifatörö khöu Yehowa wangelifi andrö ba fa''atobali dödö ba fa lö howu-howu ba halöŵöu fefu, nihalö dangau, irege tehori ndra''ugö, si lö arara, irege tekiko ndra''ugö, börö walösökhi wolaumö andrö, wa no ö''erogö ndra''odo.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 21, 'I''olembai dania ndra''ugö fökhö waba, ibe''e Yehowa, irege ahori ndra''ugö ibe''e, ba danö andrö, ba zi möi''ö, ba wangokhögö ya''ia.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 22, 'Ibözi''ö fökhö baösi Yehowa, ba fogikhi ba faosa ba fa''aukhu ba fa''oköliköli [danö] ba fa''akhozi lai wakhe ba fa''ahohomö; da''ö zi lö aefa-aefa khöu, irege no tekiko ndra''ugö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 23, 'Töla dania mbanua si yaŵa, yaŵau, ba si''öli danö barö gaheu.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 24, 'Ibali''ö gawu-gawu ba ene deu ba danöu Yehowa, da''ö dania zatoru khöu moroi yaŵa, irege no tekiko ndra''ugö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 25, 'Tegaölö tou ndra''ugö föna nemaliu ibe''e Yehowa; ha sara lalamö, na awena möi''ö fasuwö khöra, ba fitu rozi lala, na moloi''ö labe''e, ba tobali dozi niha bö''ö ba guli danö ba muhokha mbu wamaigi ya''ugö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 26, 'Ba ö wofo ba dalu mbanua fefu ba ö gutu ndru''u dania mboto zi mate khöu, lö sanaboi ya''ira.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 27, 'Ibözi dania ndra''ugö Yehowa faosa Ndrawa Miserayi ba faosa sembili ba gigimö ba böni, si lö famadöhö.[4]', '["MozII 9:9"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 28, 'Ibözi''ö Yehowa fa''owöhö ba fa''au''a ba fa''afawuka dödö.', '["MozII 9:9"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 29, 'Öbaya-bayaisi manö hadia ia ba zi laluo, si mane na ibayaisi niha sau''a ba zogömi-gömi andrö, ba si lö fozu nilau-laumö andrö; fadoro manö nifakao ndra''ugö ba ni''anagöi, ba lö sanolo ya''ugö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3448018, 'OT', 'Moze V', 28, 30, 'Öfohu khöu ndra alawe, ba niha bö''ö zi horöni ya''ia; ö''otomosi nomo, ba lö ö''onahia; öfazökhi kabu nagu, ba lö''ö sa ö''a mbuania.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 31, 'Ba zanehe ndra''ugö tetaba zaŵiu ba ma''ifu lö''ö labe''e öu; terabu galideu, ni''ila höröu, ba lö''ö sa''ae mangawuli khöu; ba danga nemaliu möi mbiri-biriu, ba lö sanolo ya''ugö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 32, 'Onou matua ba onou alawe, ba tebe''e ba danga niha bö''ö [sawuyu], i''ila höröu, ba mo''ala, ba wehulu dödöu khöra, ma''ö-ma''ökhö, ba tebai ölau hadia ia.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 33, 'Bua danö khöu ba hadia ia gölöu fefu, si no erege dödöu, ba soi si lö örai mila zi manga, ba fadoro manö nifakao ndra''ugö ba nihundragö,', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 34, 'ba owöhö ndra''ugö, ba wamaigi-maigi ni''ila höröu andrö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 35, 'Ibözi ndra''ugö gigimö sanandraŵa, si lö dalu-dalu ba mbalöduhiu ba ba waha, ba i''otarai narö kahe, numalö ba galizuzu.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 36, 'Ya''ugö ba razo andrö, nifataromö khöu, ba i''ohe ba niha bö''ö Yehowa, ba niha si lö mirai mila, ya''ugö ba ira tuau mege; Lowalangi bö''ö nifosumangeu ba da''ö dania, balö geu ba kara.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 37, 'Börö wa''atobali dödö dania ndra''ugö ba börö wango''aya ba börö wangehera, ba niha andrö fefu, ba ni''ohe Yehowa ya''ugö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 38, 'Oya öbe''e ba danö tanömö zinanö, ba lö oya-oya öbasi bua, tamo sa''ae zi manga ya''ia.[5].', '["Mikh 6:15"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 39, 'Öfazökhi kabu nagu ba öhaogö-haogö, ba lö dania öu, ösi nagu nibadu, ba lö nibe''e ba naha; era sa''ae zi manga döla.', '["Mikh 6:15"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 40, 'Öfatutu wananö ono zai ba mbenuau, ba lö fanikha dania, ba wamayoiniu ya''ugö, me sadoru-doru mbua zai.', '["Mikh 6:15"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 41, 'Mo''ono ndra''ugö, ono matua ba ono alawe, ba tenga onou dania, me ni''oloi''ö dania ira.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 42, 'Fefu geu sowua khöu ba sinanöu ba danö, ba gola faruwu zi okhögö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 43, 'Niha bö''ö, si fatewu khöu, ba itugu ebua manö moroi khöu, ba ya''ugö ba sahöndrö-höndrö;', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 44, 'ya''ia zame''e-me''e nifalali khöu, ba ya''ugö, ba tenga same''e nifalali khönia hadia ia; ya''ia dania högö ba ya''ugö, ba i''o.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 45, 'Fangelifi andrö fefu zanörö ya''ugö dania, lö aefa-aefa khöu ba alua ba khöu, balazi no ahori ndra''ugö, me no lö nifondrondrongou li Lowalangiu, Yehowa ba me lö ni''o''ömö oroisania ba amakhoita andrö, nifakhoinia khöu;', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 46, 'ba tandra dania ia ba ila-ila, ba khöu ba ba madoumö dania, götö-götö wa''ara.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 47, 'Me no lö nifosumangeu Lowalangiu, Yehowa, saoha gölö ba soroi ba dödö, me no fahöna khöu fefu hadia ia,', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 48, 'ba möi''ö sawuyu nemaliu, nifatörö Yehowa khöu, göna''ö fa''olofo ba fa''owökhi dödö ba fa lö nukha ba fa''ambö manö hadia ia fefu, ba ibe''e ba mbagiu galo mbagi si''öli, irege no ihori ndra''ugö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 49, 'Ikaoni udumö niha, moroi ba zaröu, moroi ba wondrege danö, Yehowa, hulö na itörö moyo, na so moroi sa, niha si lö ö''ila li,[6]', '["Yer 5:15"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 50, 'niha sabe''e hörö, si lö ba dödö si no tohare huwa, ba si lö fa''ahakhö dödö ono matua.', '["Yer 5:15"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 51, 'La''a nono guriföu ba bua danö khöu, irege no ahori ndra''ugö; lö lasaigö khöu, he fakhe ba he ŵe nagu ba he fanikha, he ono zaŵiu ba he ono mbiri-biriu, balazi no lafakiko ami.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 52, 'Lafa''u''u ami ba mbanuami fefu, irege no adudu göli kara andrö khömi, si no alaŵa ba si no aro, nidöna-dönami, ba danömi misa fefu; lafasui ami ba mbanuami fefu, ba danömi misa, ba danö nibe''e Lowalangiu, Yehowa, khöu.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 53, 'Ba ba wa''abu dödö andrö ba ba wa''atosasa, ba nemali andrö, ba ö''a ndraonou, ösi nonou matua ba ösi nonou alawe, nibe''e Lowalangiu, Yehowa, khöu.[7]', '["Yer 19:9"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 54, 'Ba he sabölö ombuyu mege ba si hulö nono omasiö ba khömi, ba safökhö tödö dania khö dalifusönia ba ba ndra alawe andrö, nitalaguinia ba ba ndraono andrö, si tosai na khönia.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 55, 'Khöra fefu, ba lö ibe''e wöfö nösi nononia andrö ni''ania, me lö hadia ia zi tosai khönia, ba wa''abu dödö andrö ba ba wa''atosasa, ba nemali andrö, ba mbanuami fefu.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 56, 'Ira alawe sabölö ombuyutö ba sabölö mangeha-ngehao khönia fefu hadia ia ba khömi, si lö irai manandraigö manguhundragö tanö, ba wa''ombuyu-mbuyu ba ba wangeha-ngehao, ba afökhö dödönia ba ndra matuania, nitalaguinia ba ba nononia matua ba ba nononia alawe,', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 57, 'i''afökhöi tödö khöra nawö nono andrö, si otarai dalunia ba ono andrö, ni''adonogönia, i''a sa''ae, nibini''ö, me lö hadia ia khönia, ba wa''abu dödö andrö ba ba wa''atosasa, ba nemali andrö, ba mbanuami fefu.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 58, 'Na lö ötöngöni daroma li oroisa andrö fefu, nitanö ba zura andre, ba wolo''ö ya''ia, wangata''ufi Lowalangiu, Yehowa, töi andrö, sebua lakhömi ba sata''u ita.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 59, 'Ba ifatörö khöu ba ba madoumö dania wamakao si tenga inötö Yehowa, famakao sabölö-bölö ba sara, ba fökhö sabe''e sibai ba sara göi.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 60, 'Ba ifuli ifatörö khöu wökhö Ndrawa Miserayi andrö fefu, si hokha mbumö i''olembai ndra''ugö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 61, 'Ba ifatörö na göi khöu Yehowa ngawalö wökhö ba famakao, si lö ba zura goroisa andre, irege no tetiko ndra''ugö.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 62, 'Fa''oya ndröfi ba mbanua si yaŵa ami mena''ö, ba ha fasamösa dania zi tosai ya''ami, me no lö nifondrondrongou li Lowalangiu, Yehowa.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 63, 'Ba si mane fa''omuso dödö Yehowa mege wame''e fa''ohahau dödö khömi, awö wangoya''ö ya''ami, si manö wa''omuso dödö Yehowa dania wamakiko ya''ami, awö wangohori ya''ami, tobali tetimba ami ba danö andrö, ba zi möi ami iada''e, ba wangokhögö ya''ia.', '[]', NULL),
  (3448018, 'OT', 'Moze V', 28, 64, 'Ifazawili dania ndra''ugö ba niha baero fefu, i''otarai wondrege danö, numalö ba wondrege tanö sa; ba öfosumange dania Lowalangi bö''ö, ba da''ö, si lö mirai mila mege, ya''ugö ba ira tuau mege, balö geu ba kara.[8]', '["Faigi 4:27; Neh 1:8"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 65, 'Ba si lö ahono ndra''ugö ba niha andrö dania, ba lö naha solombase gaheu; tödö sanizi-nizi ibe''e khöu ba da''ö Yehowa, awö hörö sariri ba fa''abu dödö.', '["Faigi 4:27; Neh 1:8"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 66, 'Nosou, ba hulö zanaŵa-naŵa fönau wamaigiu; lö bongi lö ma''ökhö, ba manizi-nizi ndra''ugö ba lö ödöna-döna auri''ö, öŵa''ö.', '["Faigi 4:27; Neh 1:8"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 67, 'Ba zanguhulö wongi, ba ömane: Ena''ö na bongi! ba na bongi, ba ömane: Ena''ö na ifuli moluo! börö wa''abu dödöu andrö ba famaigiu hadia ni''ila höröu andrö.', '["Faigi 4:27; Neh 1:8"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 68, 'Ifuli ifoloyo ndra''ugö ba danö Miserayi Yehowa; ifatörö ba lala andrö, niŵa''ögu khöu no: Lö''ö sa''ae i''ila ia höröu, ba ba da''ö te''oro''ö dania ami sawuyu, ira matua ba ira alawe, ba nemalimi, ba lö sedöna mowöli ya''ami.', '["Faigi 4:27; Neh 1:8"]', NULL),
  (3448018, 'OT', 'Moze V', 28, 69, 'Da''ö daroma li ba wawu''usa li andrö, me fawu''u li Moze ba Ndraono Gizeraeli, ba danö Ndraono Moabi, niŵa''ö Yehowa khönia, lö lai wawu''usa li andrö, me fawu''u li ia khöra ba gahe hili Horebi.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 1, 'Ba humede Moze ba Ndraono Gizeraeli fefu ba imane khöra: No mi''ila fefu hadia ia nilau Yehowa ba danö Miserayi, khö Wara''o ba ba mbanuania fefu ba ba danönia ma''asagörö, ba zanehe ami:[1]', '["MozII 19:4","Faigi 7:19"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 2, 'fangoroma''önia fa''abölönia andrö, si tenga inötö, ni''ila höröu, tandra andrö ba ila-ila, si no ebua.[2]', '["MozII 19:4","Faigi 7:19"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 3, 'Ba irege ma''ökhö andre, ba lö nibe''e Yehowa khömi fa''aboto ba dödö ba wanöndra eluaha, ba lö nibe''enia hörö, ba wangila, ba he tögi dalinga, ba wamondrongo.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 4, 'Ba no u''ohe ami, öfa wulu fakhe wa''ara, ba danö si mate andrö; nukhami andrö, ba lö sadudu, ba badagahemi, ba lö sobou ba gahemi.[3]', '["Faigi 8:4"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 5, 'Lö ömi roti, ba he agu, ba he bö''önia, nibadu, sabe''e, ena''ö aboto ba dödömi, wa ya''odo Yehowa Lowalangimi.', '["Faigi 8:4"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 6, 'Ba me no mirugi danö da''e, ba me möi fasuwö khöda Zihona andrö, razo ba Hesibona ba Ogi andrö, razo ba Mbazana, ba no sabölö ita moroi khöra,[4]', '["Faigi 3:1","MozIV 32:33"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 7, 'ba no ta''okhögö danöra, ba no tabe''e ba mado Rubeno ba ba mado Gado ba ba zi matonga mado Manase, tana khöra ba ba madoura dania.[5]', '["Faigi 3:1","MozIV 32:33"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 8, 'Ba mitöngöni sa''ae daroma li ba wawu''usa li andre, ba wolo''ö, ena''ö mofozu mibe''e fefu hadia ia nilaumi.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 9, 'Föna Lowalangimi, Yehowa, so ami fefu, ma''ökhö, salaŵa mado khömi ba madomi andrö ba satua ba kumandru khömi, dozi ira matua Ndraono Gizeraeli,', '["MozI 17:7"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 10, 'ba iraonomi ba ira alawemi, awö niha bö''ö andrö khömi, si so ba golombaseŵami, he soleŵa-leŵa eu ba he sana''u-na''u idanö khömi,', '["MozI 17:7"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 11, 'ena''ö fawu''u li ami Lowalangiu, Yehowa, ba wefao khönia, si möi ba hölu ami, famagölö Lowalangiu, Yehowa, khöu ma''ökhö,', '["MozI 17:7"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 12, 'ena''ö ifataro banuania ndra''ugö ma''ökhö ba ena''ö Lowalangiu göi ia, si mane nifabu''unia khöu, si no möi ba hölu ia khö ndra tuau Aberahamo, Iza''aki, Yakobo.[6]', '["MozI 17:7"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 13, 'Ba tenga ha ba khömi fawu''u li ndra''o iada''e, tenga ha ya''ita zi faböbö, si möi ba hölu ita,', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 14, 'no he ba zi so ba da''e khöda föna Lowalangida, Yehowa, iya''e, ba he ba zi lö khöda ba da''e ma''ökhö a''ine.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 15, 'Itörö sa tödömi we''asoda ba danö Miserayi mege ba fanöröda talu danö niha baero, nitöröda andrö,', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 16, 'ba fangilami sogoro ita andrö khöra ba adura andrö, eu ba kara ba firö ba ana''a, si so khöra.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 17, 'Böi manö falukha ba khömi, he ira matua, ba he ira alawe, ba he fatalifusöta ba he mado, si erogö Lowalangida, Yehowa, tödönia, ma''ökhö, ba we''amöi mamosumange Lowalangi niha baero andrö! Böi manö falukha ba khömi mbaya sowua langu ba hiya![7]', '["HalZin 8:23; Heb 12:15"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 18, 'Ma so zanötöna manö fefu hadia ia zi sökhi, na irongo daroma li ba wamagölö andre, ni''aro''ö fahölusa, ma imane dödönia: Lö gönado fama''ala, he ŵa''ae u''o''ö wa''abe''e dödögu andrö. Ba fozunia, ba tehori nibasöi, fabaya si no oköli-köli.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 19, 'Ba niha si manö, ba lö ibe''e aefa horö Yehowa, muhola dania wönu Yehowa ba fa''afökhö dödönia ba niha si manö, ba tohare dania khönia wangelifi andrö fefu, nisura ba zura andre, ba ibunu döinia ba guli danö Yehowa.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 20, 'Iheta ba mado Ndraono Gizeraeli bö''ö mado si manö Yehowa famakikonia, itörö sibai niŵa''ö ba wangelifi andrö, ba wawu''usa li, nitanö ba zura goroisa andre.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 21, 'Ba lamane dania nga''ötömi, iraonomi andrö, sawena ebua furimi dania, awö niha bö''ö andrö, si otarai danö saröu, na la''ila wamakao andrö ba fökhö andrö, nifatörö Yehowa ba danö andre —', '["MozI 19:24","Yer 22:8"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 22, 'na hatö talö balera ba asio ba akhozila danönia tou, tobali tebai tehalö nowi ba lö auri hadia ia, sinanö hadia ia, ba lö motalinga ba khönia, wa no adudula, si mane ba Zodoma ba ba Gomora ba ba Gadama ba ba Zebo''i, nidudugö Yehowa no, irugi danö tou ba wönunia andrö ba ba mbakhu-bakhu dödönia[8] —', '["MozI 19:24","Yer 22:8"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 23, 'si ndruhu, niha baero fefu, ba lamane dania: Hadia mbörö, wa no ilau da''ö ba danö andrö Yehowa? He moroi wehola wönunia andrö, si tenga inötö?[9]', '["MozI 19:24","Yer 22:8"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 24, 'Ba lamane dania: Me lö nitöngönira fawu''usa li andrö, me fawu''u li khöra Yehowa, Lowalangi duara andrö, me iheta ira ba danö Miserayi,', '["Faigi 4:19"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 25, 'ba me no möi ira mamosumange Lowalangi bö''ö, awö wangalulu ba da''ö, ba Lowalangi si lö larai mila föna ba si tenga nituturunia khöra.[10]', '["Faigi 4:19"]', NULL),
  (3448027, 'OT', 'Moze V', 29, 26, 'Da''ö mbörö wa tesao wönu Yehowa ba danö andre ba tobali ifatörö khönia wangelifi andrö fefu, nitanö ba zura andre mege.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 27, 'Ba no ideha ira ba danöra Yehowa ba wönunia andrö ba ba mbakhu-bakhu dödönia ba ba wa''abao dödönia andrö, si no abölö-bölö, ba no ifazaumba ira ba danö bö''ö, si mane ma''ökhö.', '[]', NULL),
  (3448027, 'OT', 'Moze V', 29, 28, 'Si tobini na ua, ba balazi Lowalangida, Yehowa, ba si no teboka, ba khöda ba ba ndraonoda, götö-götö wa''ara, ena''ö ta''o''ö fefu daroma li oroisa andre.', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 1, 'Ba na no itörö dania ndra''ugö da''ö fefu, howu-howu andrö ba fangelifi andrö, niŵa''ögu khöu, ba na öbe''e ba dödöu dania ba niha baero andrö fefu, ba nitibo''ö Lowalangiu, Yehowa, ya''ugö,', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 2, 'ba na öfuli''ö khö Lowalangiu, Yehowa, awö ndraonou, soroi si''aikö ba dödö ba soroi si''aikö ba gera-era, ba na ö''o''ö linia ba niŵa''ögu khöu maökhö fefu,', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 3, 'ba ifuli ifaigi lala khöu Lowalangiu, Yehowa, ihakhösi tödö ndra''ugö, ba ifuli i''ozaragö ami ba niha andrö fefu, ba nifazaewe Lowalangimi, Yehowa, ya''ami.', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 4, 'Ba he ba wondrege danö so ösa, sizaewe, föfömi, ba i''ozaragö ami ba da''ö Lowalangimi, Yehowa, ba ihalö ami ba da''ö.', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 5, 'Ba Lowalangiu, Yehowa zolohe ya''ugö ba danö andrö, si no tanö ndra tuau mege, ena''ö tanöu, ba ohahau dödöu ba ato ami ibe''e, moroi khö ndra tuami mege.', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 6, 'Iboto dödöu ba tödö madoumö dania Lowalangiu, Yehowa, ena''ö moroi si''aikö ba dödöu ba moroi si''aikö ba gera-erau ö''omasi''ö Lowalangiu, Yehowa, börö wangorifiu andrö.[1]', '["Yer 24:7; 32:39; Hes 36:26"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 7, 'Ba ba nemaliu andrö ba ba zi fatiu tödö khöu, si no molohi ya''ugö, ifatörö wangelifi andrö fefu Lowalangiu, Yehowa.', '["Yer 24:7; 32:39; Hes 36:26"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 8, 'Ba ya''ugö, ba öfuli öfondrondrongo li Yehowa ba ö''o''ö goroisania andrö fefu, nifa''emagu khöu ma''ökhö,', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 9, 'ba ihöna dania zi sökhi ba halöŵöu andrö fefu, nihalö dangau ba ba dabinau ba ba mbeto guriföu ba ba mbua danö khöu; ifuli sa omuso dödö Yehowa ndra''ugö, fangorifiu, si mane fa''omuso dödönia ndra tuau mege,', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 10, 'na öfondrondrongo li Lowalangiu, Yehowa, wolo''ö oroisania, awö nifakhoinia andrö, nitanö ba zura goroisa andre, na moroi si''aikö ba dödöu ba na moroi si''aikö ba gera-erau öfuli''ö khö Lowalangiu, Yehowa.', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 11, 'Ba goroisa andre sa, nifa''emagu khöu ma''ökhö, ba tenga si tebai ndra''ugö, tenga si tebai ökhamö.', '["Rom 10:6"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 12, 'Tenga si yaŵa ba zorugo so ia, fa öŵa''ö ena''ö: Ha niha khöda zi möi yaŵa ba zorugo ba wangai ya''ia mitou ba ba wangombakha khöda, ena''ö ta''o''ö?[2]', '["Rom 10:6"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 13, 'Ba tenga göi yefo nasi so ia, fa oŵa''ö ena''ö: Ha niha khöda zi möi misi yefo nasi, mangai ya''ia khöda, ba wangombakha ya''ia khöda, ena''ö ta''o''ö?', '["Rom 10:6"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 14, 'No sahatö sibai khöu daroma li andrö, ba mbeweu ba ba dödöu [tabe''e ia], tobali ö''ila ö''o''ö.', '["Rom 10:6"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 15, 'Hiza, no ufaedo khöu ma''ökhö wa''auri, awö wa''ohahau dödö, ba fa''amate, awö wamakao.[3]', '["Faigi 11:26; Yer 21:8"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 16, 'Na ö''o''ö goroisa Lowalangiu, Yehowa, nifa''emagu khöu ma''ökhö, wa ö''omasi''ö Lowalangiu, Yehowa, na ötörö lala andrö khönia, ba na ötöngöni goroisania, awö nifakhoinia andrö, awö hukunia, ba auri ndra''ugö ba ato ami dania, ba ifahowu''ö ndra''ugö Lowalangiu, Yehowa, ba danö andrö, ba zi möi''ö, ba wangokhögö ya''ia.', '["Faigi 11:26; Yer 21:8"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 17, 'Ba na fa''ero dödöu, na lö öfondrondrongo li, na tobali öbe''e nifowöhö ndra''ugö, ba wangalulu ba Lowalangi bö''ö, ba ba wamosumange da''ö, ba uŵa''ö khömi ma''ökhö:', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 18, 'Lö zi lö tekiko ami; tenga sanau noso ami, ba danö andrö, ba zi möi ami miyefo Yoridano, ba wangokhögö ya''ia.', '[]', NULL),
  (3448035, 'OT', 'Moze V', 30, 19, 'Ukaoni si so ba mbörö ba khömi andrö ma''ökhö mbanua si yaŵa, awö danö tou, wa no ufaedo ira khöu wa''auri wa''amate, ba howu-howu ba fangelifi, ba no ufaedo khöu; ba fa''auri sa''ae tuyu, ena''ö auri''ö, ya''ugö andrö, awö nga''ötömö dania;[4]', '["Faigi 4:26"]', NULL),
  (3448035, 'OT', 'Moze V', 30, 20, 'omasi''ö Lowalangiu, Yehowa, ba fondrondrongo linia ba olemba, khönia, da''ö sa wangorifiu ba fanganau nosou, ena''ö lö tebulö''ö ba danö andrö, nifabu''u Yehowa fame''e, khö ndra tuau Aberahamo, Iza''aki, Yakobo, si no möi ba hölu ia khöra!', '["Faigi 4:26"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 1, 'Ba möi muhede ba Ndraono Gizeraeli fefu Moze,', '["MozIV 27:12"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 2, 'imane khöra: Otu a dua wulu fakhe wa''aragu ba guli danö iada''e, ba si tebai fao-fao sa''ae ndra''odo; ba noa göi imane khögu Yehowa; Lö ö''ötö Yoridano andrö![1]', '["MozIV 27:12"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 3, 'Lowalangiu, Yehowa zangötö fönau, ba ya''ia zangohori niha andrö fönau, ba ö''ila ö''okhögö danöra. Yosua andrö zangolöi''ö ya''ugö; dali niŵa''ö Yehowa.[2]', '["MozIV 27:18","MozIV 21:24","Faigi 7:2","Yos 1:5; Heb 13:5"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 4, 'Ilau khöra Yehowa wolaunia me ifakiko razo Ndraono Gamori andrö, Sihona ba Ogi, fabaya tanöra.[3]', '["MozIV 27:18","MozIV 21:24","Faigi 7:2","Yos 1:5; Heb 13:5"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 5, 'Ibe''e ba dangami ira Yehowa, ba mi''o''ö sibai goroisa andrö, mibe''enia khömi, wolau khöra.[4]', '["MozIV 27:18","MozIV 21:24","Faigi 7:2","Yos 1:5; Heb 13:5"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 6, 'Böi atalö dödömi, mi''abe''e''ö ami! Böi mi''ata''ufi ba böi toke''a ami khöra! Fao sa khöu Lowalangiu, Yehowa, lö iböhöi ndra''ugö, lö faröi ia khöu.[5]', '["MozIV 27:18","MozIV 21:24","Faigi 7:2","Yos 1:5; Heb 13:5"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 7, 'Ba humede Moze khö Yosua ba imane khönia, ba zi so Ndraono Gizeraeli, fefu. Böi atalö dödöu, abe''e''ö ndra''ugö! Ya''ugö sa zolohe ya''ira ba danö andrö, nifabu''u Yehowa fame''e khö ndra tuara mege, si no möi ba hölu ia khöra, ba ya''ugö zamaosa khöra.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 8, 'Ba Yehowa zowaö-waö fönau, itolo ndra''ugö, lö iböhöi''ö ba lö faröi ia khöu. Böi ata''ufi ba böi abu dödöu.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 9, 'Ba isura goroisa andrö Moze ba ibe''e ba danga gere andrö, ono Lewi, sangosa''ö tawöla zura goroisa Yehowa andrö, ba ba danga zalaŵa Ndraono Gizeraeli fefu.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 10, 'Ba iŵa''ö li khöra Moze, imane: Na no irugi mewitu fakhe, na döfi wangefa andrö, ba na owasa nose daha geu,[6]', '["MozV 15:1"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 11, 'na möi falukha khö Lowalangiu, Yehowa, Ndraono Gizeraeli fefu, ba naha andrö nituyunia dania, ba öbaso zura goroisa andre, öfarongogö khöra.', '["MozV 15:1"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 12, 'Falukha''ö zato, ira matua ba ira alawe ba iraono, awö niha bö''ö andrö khöu, si so ba mbanuami, ena''ö larongo ba ena''ö latöngöni, ba wangata''ufi Lowalangimi, Yehowa, ba ba wolo''ö sibai taroma li oroisa andre fefu.', '["MozV 15:1"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3448039, 'OT', 'Moze V', 31, 13, 'Ba iraonora andrö, si lö mangila ya''ia na, ba ndramufondrondrongo, ena''ö lafahaö ira ba wangata''ufi Lowalangimi, Yehowa, götö we''asomi ba danö andrö, ba zi möi ami miyefo Yoridano, ba wangokhögö ya''ia.', '["MozV 15:1"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 14, 'Ba imane Yehowa khö Moze: Hiza, no irugi inötö wa''amateu; hede khö Yosua ba mi''ae ba nose wama''ele''ö, ena''ö uŵa''ö li khönia. Ba möi ndra Moze Yosua, lasaŵa baose wama''ele''ö.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 15, 'Ba oroma Yehowa baose, ba mboto lawuo andrö, ba i''agö zinga mbawandruhö nose boto lawuo andrö.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 16, 'Ba imane Yehowa khö Moze: Hiza, si möi mörö ndra''ugö ba ngai ndra tuau; ba maoso dania niha andre ba lafosumange Lowalangi bö''ö, ba khöra, ba danö andrö ba zi möi ira, ba la''erogö ndra''odo, ba fawu''usa li andrö khögu, si fawu''u li ndra''o khöra, ba ladudugö.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 17, 'Ba na luo da''ö, ba tesao wönugu khöra ba faröi ndra''o khöra ba ubini''ö mbawagu khöra, ba famakiko lasaŵa, oya ngawalö zi göna ira famakao ba fangabu dödö. Ba na luo da''ö, ba lamane: Hadia, tenga andrö göna ita famakao andrö, me lö''ö sa''ae Lowalangida ba khöda?', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 18, 'Ba ya''odo, ba ufaulugö ubini''ö mbawagu, na luo da''ö, börö zi lö sökhi andrö fefu, nilaura, me no lasaŵa Lowalangi bö''ö.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 19, 'Ba mitanö ba zura khömi zinunö andrö, ba mifahaö Ndraono Gizeraeli ba da''ö, böi aefa ba mbewera, ena''ö amaedola zi so ba mbörö khögu ba Ndraono Gizeraeli zinunö andrö.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 20, 'U''ohe sa ira ba danö andrö, nifabu''ugu khö ndra tuara fahölusa, tanö si falawu susu ba ŵe ŵani, ba manga ira ba abuso ba esolo, ba aefa da''ö, ba la''otahögö Lowalangi bö''ö ba lafosumange da''ö, ba ya''odo, ba si lö ba dödöra dania, ba fawu''usa li andrö khögu, ba adudu labe''e.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 21, 'Ba na oya dania zi göna ira famakao ba fangabu dödö, ba sinunö andrö dania, wamaduhu''ö khöra lö''ö sa atö aefa-aefa dania ia ba mbewe madoura — u''ila sa gera-erara, si so ba dödöra ma''ökhö [sa''ae], he lö ni''ohegu ya''ira na ba danö andrö, nifabu''ugu khö ndra tuara, fahölusa.[7]', '["Yer 17:10; Fam 2:23"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 22, 'Ba me luo da''ö itanö ba zura zinunö andrö Moze, ba ifahaö Ndraono Gizeraeli ba zinunö andrö.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 23, 'Ba iŵa''ö li khö Yosua, ono Nuni andrö, [Lowalangi], imane khönia: Böi atalö dödöu, abe''e''ö ndra''ugö! me ya''ugö zolohe Iraono Gizeraeli ba danö andrö, nifabu''ugu khöra fahölusa, ba ya''o zanolo ya''ugö.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 24, 'Ba me no ahori itanö ba zura daroma li oroisa andrö fefu Moze,', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 25, 'ba ibe''e li ba nono Lewi andrö, sangosa''ö tawöla andrö, naha zura goroisa Yehowa, imane:', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 26, 'Mihalö zura goroisa andre ba mibe''e ba ngai dawöla naha zura goroisa Lowalangimi, Yehowa, ena''ö amaedola zi so ba mbörö ia ba khömi, ba da''ö.', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 27, 'Noa sa u''ila wanandrou ba fa''abe''e mbörö du''imö. He iada''e sa''ae, ba we''asogu na ba khömi, ba noa sa''ae te khömi niŵa''ö Yehowa; ba mendrua manö dania, na no mate ndra''o!', '[]', NULL),
  (3448039, 'OT', 'Moze V', 31, 28, 'Mifalukha''ö khögu zalaŵa madomi fefu, awö gumandru khömi, ena''ö ufarongogö khöra daroma li andre ba ena''ö ukaoni si so ba mbörö ba khöra andrö mbanua si yaŵa ba tanö tou.[8]', '["MozV 4:26"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 29, 'U''ila sa, na no mate ndra''o dania, ba mifakiko manö wolau, wondröi lala andrö, nituturugu khömi; ba göna dania ami famakao andrö, me solau si fatuwu khö Yehowa ami, wangandrö fönunia folau-laumi andrö.', '["MozV 4:26"]', NULL),
  (3448039, 'OT', 'Moze V', 31, 30, 'Ba ahori ifarongogö ba Ndraono Gizeraeli fefu daroma li sinunö andre Moze, imane:', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 1, 'Mifondrongondrongo, ya''ami banua si yaŵa, muhede sa''ae ndra''o, ba yamurongo tanö wehede mbewegu andre!', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 2, 'Ya hulö deu moroi yaŵa wamahaögu, yamowöi hulö namo wehedegu, ya si mane teu ba ndru''u danö, si mane böiböi ba mbulu ndru''u!', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 3, 'Töi Yehowa sa''ae ufarongogö: Mifosumange Lowalangida!', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 4, 'Gowe ia, so''ahonoa wolaunia; me no satulö lala andrö khönia fefu, Lowalangi si lö faröi ia, lö falimosa khönia, satulö tödö ba sadölö tödö ia!', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 5, 'Si lö sökhi nilaura khönia, si tenga ononia andrö, ba fangaila ira, nga''ötö si no tefuyu ba si no tekiko.', '["Mal 1:6"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 6, 'Hadia, si manö wamasulönimi [sisökhi] khö Yehowa, ya''ami niha sambö era-era ba si lö tödö? Hadia, tenga ya''ia namau, somböi ya''ugö mege? Tenga ya''ia zangasogö ya''ugö ba samataro ya''ugö?[1]', '["Mal 1:6"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 7, 'Törö tödöu götö föna andrö, töngö-töngöni götö nga''ötö niha si no numalö! Sofu khö namau, ena''ö i''ombakha''ö khöu; ba zi no tohare huwa ba khömi sofu, ena''ö latunö khöu.', '["HalZin 17:26"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 8, 'Me ibe''e tana ba niha danö Fondrege zalaŵa, me iföfö''ö nono niha, ba ifakhoi nola soi, dali wa''ato Ndraono Gizeraeli andrö.[2]', '["HalZin 17:26"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 9, 'Tana khö Yehowa sa mbanuania andrö, okhötania, si lö tebulö, nifakhoi khönia ma''uwu Yakobo.[3]', '["Faigi 4:20","MozII 19:4"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 10, 'Ba danö si mate isöndra, ba danö si mate sata''u ita, si lö niha-niha. Ba no irorogö, lö aefa-aefa hörönia khöra; no irorogö, nifondrorogö ono hörönia.', '["Faigi 4:20","MozII 19:4"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 11, 'Si mane moyo same''awa ononia ba gazuni ba sanaha-nahae yaŵa nononia andrö, si manö wamologönia afinia, ihalö ira ba itaya afinia.[4]', '["Faigi 4:20","MozII 19:4"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 12, 'Ha Yehowa zolohe ya''ira ba lö awönia Lowalangi bö''ö.', '["Sin 81:17"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 13, 'Ba zalaŵa tanö ifatörö ira, ba bua danö ibe''e öra. Ba gara lasisiö ŵe ŵani ibe''e ba ba gowe lasisiö wanikha,[5]', '["Sin 81:17"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 14, 'fabaya fanikha zusu zaŵi ba susu nambi, awö dawö nono mbiri-biri ba tawö mbiri-biri si matua. Saŵi Mbazana, si matua [ibe''e khöra], awö mbiri-biri si matua ba fondrege zi sökhi gandru, ba no mibadu nösi mbua nagu, timba nagu saukhu.', '["Sin 81:17"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 15, 'Ba atabö Yesuru andrö, ba fasifa — satabö ndra''ugö ba sesolo ba so''ösi! Ba i''erogö Lowalangi, somböi ya''ia mege, ba lö''ö sa''ae ba dödönia gowe andrö, fangorifinia.[6]', '["Yes 44:2"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 16, 'La''andrö wönunia, börö Lowalangi bö''ö andrö, sogoro ita labe''e famaosi dödönia.', '["Yes 44:2"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 17, 'Labe''e gö mbekhu, si tenga Lowalangi, ö Lowalangi si lö larai mila mege; si bohou tumbu, sawena so, si tenga ni''ata''ufi ndra tuami mege.', '["Yes 44:2"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 18, 'Gowe andrö, so''ono ya''ugö mege, ba lö itörö tödöu, ba no olifu''ö Lowalangi andrö, sadono ya''ugö.', '["Yes 44:2"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 19, 'Ba i''ila Yehowa ba itibo''ö [mbanuania andrö], ba wönunia ba nononia matua ba ba nononia alawe andrö.', '["Rom 10:19","Yer 15:14"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 20, 'Imane: Da''ubalugö mbawagu khöra, da''ufaigi he wisa lua-lua dania khöra. Me no niha si tefuyu sibai tödö ira, iraono si lö falöfaröi.', '["Rom 10:19","Yer 15:14"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 21, 'No la''andrö wönugu, börö zi tenga Lowalangi andrö, no labaosi dödögu ba nadu faya andrö khöra, ba da''ube''e famasugi wönura niha si tenga niha, ba ube''e famaosi dödöra niha baero.[7]', '["Rom 10:19","Yer 15:14"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 22, 'Humola sa''ae galitö wönugu, irugi zabakha mbanua tou feholania, i''a danö, fabaya sauri ba gulinia, ira''i daya-daya hili.[8]', '["Rom 10:19","Yer 15:14"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 23, 'Da''uhawui ira famakao, uhori nono wana khögu, wolau khöra.', '["Rom 10:19","Yer 15:14"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 24, 'Ba na no afuo dania ira ba wa''olofo ba na no ariri ba wa''aukhu wökhö waba ba ba wökhö bö''ö, sabe''e sibai, ba ufatörö khöra nifö gutu ndru''u ba söfu gulö, ba danö tou.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 25, 'Na baero, ba ahori ira ba mbawa zi''öli; ba na yomo, ba ba wa''ata''u, ono matua ba ono alawe ba iraono ba mbagi zusu ba si no tohare huwa.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 26, 'Umane ena''ö: Da''uwuwusi misa ira, olifu niha bö''ö ira ube''e,', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 27, 'na lö ata''udo wa''abu dödögu ba zi fa''udu andrö, ma lö aboto ba dödö zamakao ya''ira andrö, ma lamane dödöra: Tangama zabölö, ba tenga Yehowa, zolau da''ö fefu.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 28, 'Noa sa niha si lö famobawa lala ira, niha si lö bakha tödö.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 29, 'Na satua-tua ira, ba aboto ba dödöra ena''ö, ba lafatou-tou ena''ö lua-lua, si so fönara.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 30, 'Hana wa i''ila igohi zi hönö si ha samösa, ba hana wa moloi zi fulu ngahönö labe''e si darua, na lö ni''amawa gowera andrö ya''ira ba na lö niböhöli Yehowa ya''ira.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 31, 'Gowera andrö, ba tenga sa si mane goweda; emalida zamaduhu''ö da''ö.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 32, 'Ina ŵeŵe nagu khöra sa, ba ŵeŵe nagu Zodoma ba ba danö Gomora moroi khöra. Bua nagu khöra, ba langu, fa''afeto gawökhu wa''afeto mbua andrö.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 33, 'Ilo naga nösi nagura andrö, ba söfu gulö, sata''u ita.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 34, 'Hadia tenga no mube''e yaŵa da''ö yomo khögu, tenga ba mbate''e girö-girö khögu so ia, nifotandro?', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 35, 'Folombase mbaŵa wolau balö, baŵa wame''e sulö, na luo mangiwa gahera. Noa sa ahatö ia, mbaŵa wamakikora andrö, i''aliogö ia moroi sa nihonogöi khöra andrö.[9]', '["Rom 12:19; Heb 10:30"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 36, 'I''ohe sa ba zatulö huhuo mbanuania Yehowa, ihakhösi tödö ngoni-ngoninia, na i''ila, no taya wa''abölö ba si lö boto nono matua, fabaya iraono.', '["Faigi 6:4; SamI 2:6"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 37, 'Imane dania: Heza so iada''e Lowalangira andrö? gowe andrö, saŵatöra mege?', '["Faigi 6:4; SamI 2:6"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 38, 'si manga dawö zumange andrö khöra mege, samadu agu sumange nibadu andrö khöra? Hana na maoso da''ö, ba wanolo ya''ami, ndramöi ba''a-ba''ami!', '["Faigi 6:4; SamI 2:6"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 39, 'Ya''oroma sa''ae khömi wa ya''odo, ya''odo andre, awö wa lö Lowalangi bö''ö baerogu. Samunu niha ndra''o ba sangorifi göi, samesokho ba samedöhö göi, ba lö sangila mangefa''ö ba dangagu niha.[10]', '["Faigi 6:4; SamI 2:6"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 40, 'U''oro''ö sa''ae dangagu miyaŵa ba mbanua si yaŵa, ba umane: Sauri ndra''o, irugi zi lö aetu!', '["Rom 15:10"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 41, 'Na no udali zi''öligu andrö si takile, na ubabaya wanguhuku, ba ulau mbalögu ba zamakao ya''odo, ulau zulö ba zi fatiu tödö khögu!', '["Rom 15:10"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 42, 'Mabu do nono wana khögu ube''e ba i''a nösi niha si''öligu — do nibunu andrö ba do nira''u ba nagole högö zolohe emali andrö.', '["Rom 15:10"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 43, 'Misuno mbanuania, ya''ami niha baero, me no solau balö ndro ngoni-ngoninia ia, ilau mbalönia ba zamakao ya''ia ba isala''ö zi lö sökhi ba danö mbanuania.[11]', '["Rom 15:10"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 44, 'So Moze, ifarongogö ba zato daroma li sinunö andrö fefu, ya''ia ba Yosua, ono Nuni andrö.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 45, 'Ba me no i''o''ozui ba Ndraono Gizeraeli fefu daroma li andrö Moze, ba imane khöra:', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 46, 'Mitanö ba dödömi daroma li andrö fefu, niŵa''ögu sibai khömi ma''ökhö, ena''ö miŵa''ö ba ndraonomi, ena''ö latöngöni, ba wolo''ö taroma li oroisa andrö fefu.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 47, 'Tenga sa faya-faya da''ö khömi, balazi nosomi, ba da''ö sibai misöndra wa''anau noso ba danö andrö, ba zi möi ami miyefo Yoridano, ba wangokhögö ya''ia.', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 48, 'Ba me luo da''ö, ba humede Yehowa khö Moze, imane:', '[]', NULL),
  (3448051, 'OT', 'Moze V', 32, 49, 'Ae miyaŵa ba hili Nebo andrö, famadoro hili Gabari, ba danö Ndraono Moabi, tanö ba gatumbukha, i''otarai Yerikho, ba faigi danö Gana''ana andrö, nibe''egu ba Ndraono Gizeraeli dania, khöra ba ba madoura dania.[12]', '["MozIV 27:12","MozIV 33:38","MozIV 20:12"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 50, 'Ba mate dania ndra''ugö ba hili andrö, ba zi möi''ö yaŵa, ba te''orudugö ndra''ugö khö ndra tuau, si mane ga''au A''aroni, si mate ba hili Hori mege, ba si no mu''orudugö khö ndra tuami,[13]', '["MozIV 27:12","MozIV 33:38","MozIV 20:12"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 51, 'börö me no mosala ami khögu, ba hunö Ndraono Gizeraeli, ba nidanö wasosota no andrö, ba Gadesi, ba danö si mate Sini, me lö nifosumangemi ya''odo, ni''amoni''ö andrö, bakha ba hunö Ndraono Gizeraeli.[14]', '["MozIV 27:12","MozIV 33:38","MozIV 20:12"]', NULL),
  (3448051, 'OT', 'Moze V', 32, 52, 'Moroi yefo andre sa öfaigi danö, ba lö örugi danö andrö, nibe''egu ba Ndraono Gizeraeli dania.', '["MozIV 27:12","MozIV 33:38","MozIV 20:12"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 1, 'Da''e wamahowu''ö Moze, enoni Lowalangi andrö, famahowu''önia Iraono Gizeraeli, me no ahatö wa''amatenia.', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 2, 'Imane: Ba Zina''i i''otarai mege Yehowa, moroi ba Ze''ira humaga ia khöra; moroi ba hili Warana ifohaga hagania andrö; i''otarai zi liwu [mala''ika], oroisa so''alitö khöra ba dangania kambölö.[1]', '["HalZin 7:53; Yuda 14"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 3, 'Irorogö mbanuania, i''omasi''ö. Ba dangania so ni''amoni''ö andrö khönia, fefu; föna gaheu mudadao ira ba latema daroma limö.', '["HalZin 7:53; Yuda 14"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 4, 'No iŵa''ö khöda goroisa Moze, ondröita dania ba mbanua ma''uwu Yakobo.', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 5, 'Ba no razo Yesuru ia (Yehowa) me falukha zatua mbanua, me a''oi so mado Ndraono Gizeraeli.', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 6, 'Ya''auri mado Rubeno, böi mate, fa böi alö wa''ato niha khöra![2]', '["MozI 49:3 b.t."]', NULL),
  (3448148, 'OT', 'Moze V', 33, 7, 'Ba da''e ba mado Yuda, imane: Fondrondrongo wangarö-ngarö mado Yuda, ya''ugö Yehowa, ba ohe mangawuli ira, ba niwara! Lau fasöndra tangau, fönara, ba tolo ira ba zamakao ya''ira andrö!', '["MozI 49:3 b.t."]', NULL),
  (3448148, 'OT', 'Moze V', 33, 8, 'Ba ba mado Lewi, ba imane: "Tumimi" ba "urimi" andrö khöu, ba no ba niha sadöni tödö khöu, nitandraigömö andrö ba Masa no, si fasoso ndra''ugö no, ba nidanö ba Meriba andrö;[3]', '["MozII 28:30; MozIV 20:13","MozII 32:29"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 9, 'ba zanguma''ö khö ndra amania inania: Lö ni''ilagu ya''ira, si lö manehe talifusönia ba si lö ba dödö ononia. Lö''ö sa laböhöli niŵa''öu, ba lö aefa khöra goroisamö.[4]', '["MozII 28:30; MozIV 20:13","MozII 32:29"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 10, 'Lafahaö ma''uwu Yakobo ba hukumö andrö ba Iraono Gizeraeli ba nifakhoimö; lafa''ago''ö khöu hua zumange, ba labe''e ba naha wame''e sumange khöu zumange sa''oi so.', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 11, 'Fahowu''ö gölöra, ya''ugö Yehowa, ba sökhi na omasi ndra''ugö halöŵö dangara andrö! Rasa löwi-löwi nudura, awö löwi-löwi si fatiu tödö khöra, fa böi sa''ae maoso ira.', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 12, 'Ba ba mado Mbeniyami, ba imane: Omasiö Yehowa ira, khönia soso ira, lö hadia ia. Itimba zi lö sökhi khöra, lö mamalö-malö, ba gotalua mboto hili khöra ibe''e nahiania.[5]', '["SamII 12:25; Yer 11:15"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 13, 'Ba ba mado Yosefo, ba imane: Nifahowu''ö Yehowa danöra, nifahowu''ö buala mbanua si yaŵa, fondrege zebua böli, namo andrö, ba boto nidanö, tou ba danö;', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 14, 'fondrege zebua böli, ni''asogö luo, ba fondrege zebua böli, si tumbu ba haga mbaŵa.', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 15, 'Fondrege zi sökhi ba hili andrö, si no arara, ba fondrege zebua böli ba hili-hili, si no götö-götö fa''ara.', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 16, 'Fondrege zebua böli ba danö, awö zi no fahöna khönia! Ba fa''ebua dödö zi so ba ngafu za''a-sa''a mao no, ba yatohare ba högö mado Yosefo, ba galizuzu zi no mufanaembu ba niwara andrö!', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 17, 'No tefasui lakhömi zi a''a nono zaŵi khönia, si matua, tandru göröbao ndru''u dandrunia, ibe''e fanandru tou soi niha fefu, irugi ba wondrege danö. Da''ö zi liwu mado Geferayi, ba da''ö ngahönö mado Manase!', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 18, 'Ba ba mado Zebuloni, ba imane: Omusoi''ö tödöu döröŵamö andrö, ya''ugö mado Zebuloni, ba ya''ugö, mado Isasari, ba ö''omusoi''ö tödöu nosemö andrö!', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 19, 'Lakaoni ba hili soi niha, ba labe''e zumange si ndruhu ba da''ö, lasisiö sa''ae zi no fahöna andrö ba nasi, fabaya girö-girö andrö, si no tobalu ene.', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 20, 'Ba ba mado Gado, ba imane: Ya''ahowu zamonaha mado Gado andrö! No mörö ira tou, si mane si alawe zingo, sanasawi ta''io ba alizuzu ira.', '["MozIV 32:33; Faigi 34:6"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 21, 'No ituyu khönia zi a''a [tanö], me no tohöna ba da''ö dana ba zalaŵa [mado]. Ba i''orudugö ia ba zalaŵara, wamatörö huku satulö andrö, khö Yehowa, ifatörö ba lala Yehowa Ndraono Gizeraeli.[6]', '["MozIV 32:33; Faigi 34:6"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 22, 'Ba ba mado Dano, ba imane: Ono zingo mado Dano, moroi ba Mbazana ifanoka ia.[7]', '["Sanguhuk 13:25"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 23, 'Ba ba mado Nafetali, ba imane: Mado Nafetali, ba ni''abusoi''ö fa''ebua dödö, ba no fahöna khöra howu-howu Yehowa, asi ba tanö tanö raya la''okhögö!', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 24, 'Ba ba mado Gaseri, ba imane: Ya ono fondrege nifahowu''ö mado Gaseri; ya ni''omasi''ö dalifusöra ira, ba ndramu''ungugö ba wanikha gahera!', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 25, 'Ya si''öli ba tola gödomi, ba böi alö wa''abölömi, götö wa''anou nosomi!', '[]', NULL),
  (3448148, 'OT', 'Moze V', 33, 26, 'Lö Lowalangi si mane Lowalangi Yesuru andrö, sanörö banua si yaŵa ba wanolo ya''ugö, itörö lawuo, ba lakhöminia andrö.[8]', '["Faigi 32:15"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 27, 'Saŵatö Lowalangi andrö, si lö aetu; ba ba da''e tou, ba ta''ionia si lö tebulö. No itimba nemali fönau, ba no imane:', '["Faigi 32:15"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 28, 'Hori! Ba no ahono Ndraono Gizeraeli, lö hadia ia, no tonia gumbu ma''uwu Yakobo, ba danö si no fahöna fakhe ba ösi nagu, ba moroi ba mbanua yaŵa khönia, ba mowöi namo.[9]', '["Yer 23:6"]', NULL),
  (3448148, 'OT', 'Moze V', 33, 29, 'Ya''ahowu ami, ya''ami Iraono Gizeraeli! Ha niha zi fagölö-gölö khömi? — Soi si möna, ibe''e Yehowa! Ya''ia mbaluse andrö, fangorifiu, ba no si''öliu göi ia, lakhömiu! Sangalulu khöu dania nemaliu, ba ötörö hili andrö khöra.', '["Yer 23:6"]', NULL),
  (3448153, 'OT', 'Moze V', 34, 1, 'Ba möi miyaŵa ba hili Nebo Moze, i''oroi ndraso Ndraono Moabi andrö, isaŵa zuzu hili Wisiga, ba gamaudu Yerikho; ba da''ö i''oroma''ö khönia danö ma''asagörö Yehowa, tanö Gileadi ba irugi Dano,[1]', '["Faigi 3:27"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3448153, 'OT', 'Moze V', 34, 2, 'ba tanö mado Nafetali ma''asagörö ba tanö mado Geferayi ba tanö mado Manase ba tanö mado Yuda ma''afefu, irege nasi tanö ba gekhula luo,', '["Faigi 3:27"]', NULL),
  (3448153, 'OT', 'Moze V', 34, 3, 'ba tanö tanö raya ba daso Yoridano, daso mbanua khorema andrö, Yerikho, irugi Zoara.', '["Faigi 3:27"]', NULL),
  (3448153, 'OT', 'Moze V', 34, 4, 'Ba imane khönia Yehowa: Da''ö danö andrö nifabu''ugu khö ndra Aberahamo, Iza''aki, Yakobo, si no möi ba hölu ndra''o khöra, wanguma''ö: Ba ma''uwumö dania ube''e ia. No i''ila höröu ube''e, ba lö''ö sa örugi![2]', '["MozI 12:7"]', NULL),
  (3448153, 'OT', 'Moze V', 34, 5, 'Ba mate Moze, enoni Yehowa andrö, ba da''ö, ba danö Ndraono Moabi andrö, itörö niŵa''ö Yehowa,', '[]', NULL),
  (3448153, 'OT', 'Moze V', 34, 6, 'ba iko''o ia ba ndraso ba danö Ndraono Moabi, ba gamaudu Mbeti-Weoro; ba lö sangila heza so lewatönia, irugi ma''ökhö andre.', '[]', NULL),
  (3448153, 'OT', 'Moze V', 34, 7, 'Ba 120 fakhe Moze, me mate ia, lö sabözi hörönia ba lö salö wa''abe''enia.', '[]', NULL),
  (3448153, 'OT', 'Moze V', 34, 8, 'Ba la''e''esi Moze Iraono Gizeraeli ba ndraso Ndraono Moabi andrö, tölu ngafulu wongi wa''ara, awena ahöwö mbongi wange''esi Moze andrö.', '[]', NULL),
  (3448153, 'OT', 'Moze V', 34, 9, 'Ba fahöna Geheha fa''atua-tua khö Yosua andrö, ono Nuni, me no itufa ia tangania Moze, ba lafondrondrongo linia Iraono Gizeraeli, la''o''ö goroisa andrö, nibe''e Yehowa khö Moze.[3]', '["MozIV 27:18"]', NULL),
  (3448153, 'OT', 'Moze V', 34, 10, 'Ba lö''ö sa''ae maoso ba Ndraono Gizeraeli zama''ele''ö si mane Moze, ba zi fahuhuo Yehowa, si fa''ila bawa ira;[4]', '["MozII 33:11"]', NULL),
  (3448153, 'OT', 'Moze V', 34, 11, 'dali dandra andrö fefu ba ila-ila, nilaunia, nifatenge Yehowa ya''ia, ba danö Miserayi, khö Wara''o ba ba mbanuania fefu ba ba danönia ma''asagörö,', '["MozII 33:11"]', NULL),
  (3448153, 'OT', 'Moze V', 34, 12, 'ba dali wa''abölönia andrö fefu, si tenga inötö, ba fa''abe''enia andrö, sata''u ita, ni''oroma''ö Moze, ba zanehe Ndraono Gizeraeli fefu.', '["MozII 33:11"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 1, 'Ba me no mate Moze, enoni Yehowa andrö, ba imane Yehowa khö Yosua, ono Nuni, enoni Moze:[1]', '["MozII 33:11"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 2, 'No mate genonigu Moze andrö, ba labu sa''ae, ötö Yoridano andrö, ya''ugö ba banua [gu] andrö fefu, misaŵa danö andrö, nibe''egu khöra, ba Ndraono Gizeraeli andrö.', '["MozV 11:24","MozV 31:6","MozV 5:32","Sin 1:2"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 3, 'Dozi nahia nihundragö gahemi, ba no ube''e khömi, itörö niŵa''ögu khö Moze.[2]', '["MozV 11:24","MozV 31:6","MozV 5:32","Sin 1:2"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 4, 'I''otarai danö si mate ba hili Libano andrö, numalö ba nidanö sebua andrö, Farati, tanö Ndraono Kheti andrö, ma''afefu, ba irugi ba nasi sebua andrö, mafi ba gaekhula luo, ba tanömi dania.', '["MozV 11:24","MozV 31:6","MozV 5:32","Sin 1:2"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 5, 'Lö sabe''e moroi khöu, götö wa''anau nosou, si mane fanologu Moze, si manö göi wanologu ya''ugö, lö ubödado ba lö faröido khöu.[3]', '["MozV 11:24","MozV 31:6","MozV 5:32","Sin 1:2"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 6, 'Ya''abölö ndra''ugö, abe''e''ö dödöu, öfaosa sa''ae dania tana ba niha andre danö nifabu''ugu fahölusa khö ndra tuara, ba wame''e khöra.', '["MozV 11:24","MozV 31:6","MozV 5:32","Sin 1:2"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 7, 'Ha fa abölö ndra''ugö ba fa abe''e dödöu, ba wamaigi folo''ö oroisa andrö fefu, niŵa''ö genonigu Moze andrö khöu. Böi hole''ö ndra''ugö, he ba gambölö ba he ba gabera, ena''ö mofozu wolaumö, gofu heza möi''ö[4]', '["MozV 11:24","MozV 31:6","MozV 5:32","Sin 1:2"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 8, 'Böi aefa-aefa ba mbaweu nösi zura goroisa andrö ba öfatou-tou tödöu, bongi ma''ökhö, ena''ö ö''alui wolo''ö fefu hadia ia nitanö ba zura andrö, ba sökhi lua-lua wolaumö ba falukha''ö zalöfö.[5]', '["MozV 11:24","MozV 31:6","MozV 5:32","Sin 1:2"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 9, 'Tenga no uŵa''ö khöu: Ya''abölö ndra''ugö, ya''abe''e dödöu? Böi ata''u ndra''ugö ba böi mangiwa dödöu, me si fao-fao khöu Yehowa, Lowalangiu, gofu heza ösaŵa.', '["MozV 11:24","MozV 31:6","MozV 5:32","Sin 1:2"]', NULL),
  (3474626, 'OT', 'Yosua', 1, 10, 'Ba ibe''e goroisa Yosua ba zatua mbanua, imane:', '[]', NULL),
  (3474626, 'OT', 'Yosua', 1, 11, 'Mitöröi golombaseŵa, ba mimane ba zato: Mifaigi khömi nifatö''ö; tölu bongi tö, ba mi''ötö Yoridano andrö, ba we''amöi ba danö andrö ba ba wangokhögö nibe''e Yehowa, Lowalangimi, khömi, ba wangai ya''ia.', '[]', NULL),
  (3474626, 'OT', 'Yosua', 1, 12, 'Ba ba mado Rubeno andrö ba ba mado Gado ba ba zi matonga mado Manase, ba imane Yosua:', '["MozIV 32:20 b.t."]', NULL),
  (3474626, 'OT', 'Yosua', 1, 13, 'Mitörö tödömi daroma li andrö, niŵa''ö genoni Yehowa, Moze, khömi, me imane: Ahono ami ibe''e Yehowa, Lowalangimi, ibe''e khömi danö andre.[6]', '["MozIV 32:20 b.t."]', NULL),
  (3474626, 'OT', 'Yosua', 1, 14, 'Fo''omomi ba iraonomi ba urifömi andrö, ba akha toröi ba danö nibe''e Moze khömi, ba zi tambai Yoridano, tanö andre, ba ya''ami andrö, ba si möi miyefo, mifa''anö ami, föna dalifusömi, dozi sabölö, ba wanolo ya''ira,', '["MozIV 32:20 b.t."]', NULL),
  (3474626, 'OT', 'Yosua', 1, 15, 'irege ahono dalifusömi ibe''e Yehowa, si mane ya''ami, ba irege la''okhögö göi danö andrö, nibe''e Yehowa, Lowalangimi, khöra. Awena dania mangawuli ami ba danö tana khömi, ba khömi sa''ae, nibe''e genoni Lowalangi andrö, Moze, khömi ba zi tambai Yoridano, tanö ba gatumbukha luo.', '["MozIV 32:20 b.t."]', NULL),
  (3474626, 'OT', 'Yosua', 1, 16, 'Ba latema li Yosua, lamane: Fefu hadia ia, niŵa''ömö khöma, ba ma''o''ö, ba fefu gofu heza öfatenge ndra''aga, ba möiga.', '[]', NULL),
  (3474626, 'OT', 'Yosua', 1, 17, 'Si mane sibai nifondrondrongoma khö Moze, si manö göi mafondrondrongo khöu; ha fa itolo''ö Yehowa, Lowalangiu, si mane fanolonia Moze andrö.', '[]', NULL),
  (3474626, 'OT', 'Yosua', 1, 18, 'Dozi si lö edöna molo ö oroisamö ba si lö mamondrongo liu, fefu hadia ia niŵa''öu, ba nibunu. Hatö fa abölö ndra''ugö ba fa abe''e dödöu.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 1, 'Ba darua ifatenga Yosua, ono Nuni andrö, niha, si möi mamauze, moroi ba Ziti, lö ifarongogö, ba imane: Mi''ae mifaigi danö andrö ba banua Yerikho! Ba möi ira ba larugi yomo khö zohorö, ira alawe, Rakhaba döi, ba mörö ira ba da''ö.[1]', '["Mat 1:7; Heb 11:31; Yak 2:25"]', NULL),
  (3474627, 'OT', 'Yosua', 2, 2, 'Ba te''ombakha''ö khö razo Yerikho, lamane: Hiza, no so niha, bongi, Iraono Gizeraeli, ba wamauze tanö.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 3, 'Ba ifatenge khö Rakhaba razo Yerikho, imane khönia: Ohe tou niha andrö, si no möi khöu, baomou, me no ba wamauze tanö fefu möi ira.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 4, 'Ba ihalö niha andrö si darua ira alawe andrö, ibini''ö, ba imane: Duhu, no möi khögu niha, ba lö u''ila, he moroi ira.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 5, 'Ba me inötö lakusi mbawa göli, me bongi, ba möi baero niha andrö; lö u''ila, heza lasaŵa. Mita''i-ta''i migohi ira, ena''ö mikhamö!', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 6, 'Ba no i''ohe yaŵa ira ba dete nomo ba no ibini''ö barö döla daliö, nifa''anönia ba dete nomo yaŵa.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 7, 'Ba lagohi ira banuara andrö, ba lala ba Yoridano, ba götöna andrö; ba lakusi mbawa göli, me no latörö solohi andrö.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 8, 'Ba lö si mörö ira na, ba möi yaŵa ndra alawe andrö ba dete nomo khöra.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 9, 'Ba imane ba niha andrö: U''ila, wa no ibe''e khömi danö andre Yehowa, awö wa no ihawui ndra''aga fa''ata''uma ami, awö wa no atalö dödö niha ba danö fefu, ba khömi andrö.', '["MozII 14:21; MozIV 21:24","MozV 4:39"]', NULL),
  (3474627, 'OT', 'Yosua', 2, 10, 'Noa sa marongo, he wisa Yehowa wangogo''öisi asi zukhu andrö fönami, me aheta ami ba danö Miserayi, ba hadia nilaumi ba razo Ndraono Gamori andrö, si darua, yefo Yoridano, Sihona ba Ogi, nifakikomi.[2]', '["MozII 14:21; MozIV 21:24","MozV 4:39"]', NULL),
  (3474627, 'OT', 'Yosua', 2, 11, 'Me marongo da''ö, ba atalö dödöma, ba samösa lö''ö sa''ae sabe''e tödö, ba khömi andrö, me no Lowalangi ba mbanua si yaŵa ba ba guli danö si tou Lowalangimi andrö, Yehowa.[3]', '["MozII 14:21; MozIV 21:24","MozV 4:39"]', NULL),
  (3474627, 'OT', 'Yosua', 2, 12, 'Ba mi''ae ba hölu sa''ae khögu, ba khö Yehowa, wa mihakhösi tödö zoroiyomo namagu fefu, si mane fa''ahakhö dödögu ami, ba mibe''e khögu dandra, wa tenga si falimo ami.', '["MozII 14:21; MozIV 21:24","MozV 4:39"]', NULL),
  (3474627, 'OT', 'Yosua', 2, 13, 'Mi''orifi namagu ba inagu ba talifusögu matua ba talifusögu alawe, awö dozi zi faböbö khöra, böi mibe''e mate ndra''aga.', '["MozII 14:21; MozIV 21:24","MozV 4:39"]', NULL),
  (3474627, 'OT', 'Yosua', 2, 14, 'Ba lamane khönia niha andrö: Alakha aetu nosoma salahimi! Na lö mi''ombakha''ö we''amöima andre, ba lö zi lö mahakhösi tödö ndra''ugö, na ibe''e khöma danö andre Yehowa, lö malimo''ö.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 15, 'Awena idada ira ba zandrela sinali, me no fasinga ba göli mbanua nomonia; ba dete göli so nahiania.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 16, 'Ba imane khöra: Misaŵa hili, fa böi lakhamö ami solohi andrö, ba mibini''ö ami, ba da''ö tölu bongi, irege mangawuli zolohi andrö, ba awena dania mofanö ami.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 17, 'Ba lamane khönia niha andrö: Ba aefa ndra''aga ba hölu andrö, ni''andröu khöma [na lö ö''o''ö niŵa''öma khöu].', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 18, 'Hiza, na marugi danö, ba ötaŵi zinali soyo andre ba zandrela, ba nidadamö ya''aga, ba ö''owuloi yomo khöu ndra amau inau ba ira talifusöu, awö zoroiyomo namau fefu.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 19, 'Ba ha niha zanörö ora, we''amöi tou baolayama, ba bali-balinia nosonia ba lö horöma, ba dozi sorudu yomo khöu, ba ya''aga zolu''i noso, na so zombambaya ya''ira.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 20, 'Ba na ö''ombakha''ö we''amöima andre, ba aefa göi ndra''aga ba hölu andrö, ni''andröu khöma.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 21, 'Ba imane: Ya''itörö niŵa''ömi! Ba i''efa''ö ira, ba mofanö ira. Ba itaŵi ba zandrela zinali soyo andrö.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 22, 'Ba mofanö ira, larugi hili ba la''iagö ba da''ö, tölu bongi, irege no mangawuli zolohi andrö; ba la''alui ira solohi, ma''asara lala andrö, ba lö lasöndra.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 23, 'Ba mangawuli niha andrö, si darua, latueli hili, möi ira miyefo khö Yosua, ono Nuni, ba ladunö-dunö khönia fefu zi no falukha ira.', '[]', NULL),
  (3474627, 'OT', 'Yosua', 2, 24, 'Ba lamane khö Yosua: No ibe''e ba dangada danö andrö ma''afefu Yehowa ba noa göi atalö dödö niha ba danö fefu ba khöda andre.', '[]', NULL),
  (3474628, 'OT', 'Yosua', 3, 1, 'Ba ihulö wongi wemaoso Yosua, ba laheta ira ba Ziti ba larugi mbewe Yoridano, ya''ia ba Iraono Gizeraeli fefu, ba molombase ira ba da''ö, atö la''ötö.', '[]', NULL),
  (3474628, 'OT', 'Yosua', 3, 2, 'Ba aefa tölu bongi, ba latörö golombaseŵa satua,', '["MozII 19:10"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 3, 'laŵa''ö li ba zato, lamane: Na mi''ila dawöla gamabu''ula li andrö khö Lowalangimi, Yehowa, ba ere andrö, ono Lewi, samabea ya''ia, ba milabu, miröi nahami ba mi''o''ö.', '["MozII 19:10"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 4, 'Ba böi mihatö''ö ami, mifo''otalua, mato dua ngahönö hela, nisu''a. Böi fadege ami khönia, ena''ö mi''ila lala nitörömi; tenga sa taŵa''ö, no mitörö lala da''ö menewi ba me dua wongi.', '["MozII 19:10"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 5, 'Ba imane Yosua ba zato: Mi''amoni, ilau sa''ae zahöli-höli dödö Yehowa, ba hunömi, mahemolu.[1]', '["MozII 19:10"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 6, 'Ba iŵa''ö Yosua ba gere andrö, wanguma''ö: Mifabea dawöla gamabu''ula li ba mi''owaö-waö föna zato!', '[]', NULL),
  (3474628, 'OT', 'Yosua', 3, 7, 'Ba imane Yehowa khö Yosua: Ma''ökhö andre ubörögö wangebua ya''ugö, nifaigi Ndraono Gizeraeli, ena''ö la''ila, wa utolo ndra''ugö; si mane fanologu Moze mege.', '[]', NULL),
  (3474628, 'OT', 'Yosua', 3, 8, 'Ba be''e li sa''ae ba gere andrö, samabea tawöla gamabu''ula li, ömane: Na mirugi zinga nidanö Yoridano, ba mibadugö ami ba mbewe Yoridano.', '[]', NULL),
  (3474628, 'OT', 'Yosua', 3, 9, 'Ba imane Yosua ba Ndraono Gizeraeli; Mi''aine, ba mifondrondrongo li Lowalangimi Yehowa.', '["Sin 114:3"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 10, 'Ba imane Yosua: Ba da''ö aboto ba dödömi so ba hunömi Lowalangi sauri, ba ifofanö fönami Ndrawa Gana''ana, Iraono Kheti ba Iraono Hewi ba Iraono Weresi ba Iraono Girigasi ba Iraono Gamori ba Iraono Yebusi.', '["Sin 114:3"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 11, 'Hiza, mowaö-waö fönami dawöla gamabu''ula li andrö khö Zo''aya tanö ma''afefu, ba wangötö Yoridano andrö.', '["Sin 114:3"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 12, 'Ba mitutuyu khömi niha, felendrua, ba mado Gizeraeli, samösa zambua mado.', '["Sin 114:3"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 13, 'Ba tobali dania, na tebato ba nidanö Yoridano gahe gere andrö, samabea tawöla gamabu''ula li andrö khö Yehowa, So''aya tanö ma''afefu, ba aetu nidanö Yoridano, idanö andrö, si otarai nulu, tebato ia, hulö mba''a-ba''a.[2]', '["Sin 114:3"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 14, 'Ba tobali me laröi nosera sato, ba wangötö Yoridano, awö gere andrö, samabea tawöla gamabu''ula li, sawaö-waö föna zato,[3]', '["HalZin 7:45","Sin 66:6"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 15, 'ba me larugi Yoridano samabea tawöla, me lahundragö zinga nidanö ere andrö samabe''a tawöla (ba no falawu fefu ngöfi Yoridano, götö mbaŵa wamasi),', '["HalZin 7:45","Sin 66:6"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 16, 'ba tebato nidanö, si otarai nulu; ahono, hulö mba''a-ba''a, aröu sibai, ba ngai Gadamo, banua andrö ba zi tambai Zarata, ba soluaha miyöu ba zilua''asi ba zalo''o tanö, silua''asi sasi-asi andrö, ba aetu manö. Ba la''ötö sato, ba gamaudu Yerikho.[4]', '["HalZin 7:45","Sin 66:6"]', NULL),
  (3474628, 'OT', 'Yosua', 3, 17, 'Ba la''iagö manö dalu Yoridano ere andrö samabea tawöla gamabu''ula li andrö, khö Yehowa, no otufo naha gahera; ba la''ötö Iraono Gizeraeli fefu, no otufo, irege no alua la''ötö Yoridano, dozi ira.', '["HalZin 7:45","Sin 66:6"]', NULL),
  (3474629, 'OT', 'Yosua', 4, 1, 'Ba me no alua la''ötö Yoridano sato, ba imane Yehowa khö Yosua:', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 2, 'Mitutuyu niha ba zato, felendrua, samösa zambua mado,', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 3, 'ba miŵa''ö li khöra, mimane: Mihalö khömi gara, felendrua, ba da''e, ba dalu Yoridano, ba naha andrö, ba zi so gere andrö mege, ba mi''ohe miyefo ba mitou''ö tou ba golombaseŵa, ba zi mörö ami bongi.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 4, 'Ba humede Yosua ba niha andrö si felendrua, nihonogöinia ba Ndraono Gizeraeli, samösa zambua mado,', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 5, 'ba imane khöra Yosua: Mi''ae miyefo, mi''owaö-waö föna dawöla gamabu''ula li khö Lowalangimi, Yehowa, ba dalu Yoridano, ba mihare''ö ba galisimi gara, sambua zamösa, ena''ö i''ohia''ö wa''oya mado Ndraono Gizeraeli, ena''ö tobali tandra ba khömi.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 6, 'Na lasofu dania iraonomi, na lamane: Hadia guna gara andre?', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 7, 'Ba mimane khöra: Me no aetu nidanö Yoridano föna dawöla gamabu''ula li khö Yehowa; me lafatörö ba Yoridano, ba aetu nidanö Yoridano; ba tandra gara andre, fa böi olifu Ndraono Gizeraeli, irugi zi lö aetu.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 8, 'Ba la''o''ö da''ö Iraono Gizeraeli, si mane niŵa''ö Yosua, lahalö gara, felendrua, ba dalu Yoridano, si mane niŵa''ö Yehowa khö Yosua, i''ohia''ö wa''oya mado Ndraono Gizeraeli; ba la''ohe miyefo ba golombaseŵa ba latou''ö tou ba da''ö.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 9, 'Ba felendrua ifatanö''ö kara Yosua ba dalu Yoridano ba naha andrö, ba zi so gere andrö mege, samabea tawöla gamabu''ula li, ba lö tebulö ba da''ö, irege ma''ökhö andre.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 10, 'Ba la''iagö dödö Yoridano ere andrö, samabea tawöla gamabu''ula li, irege no awai fefu ni''oroi''ö Yehowa, niŵa''ö ba zato, dali goroisa Moze andrö khö Yosua. Ba la''aliogö ira sato, we''amöi miyefo.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 11, 'Ba me no dozi la''ötö sato, ba lafa''ötö göi dawöla gamabu''ula li khö Yehowa ere andrö, la''iagö föna zato.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 12, 'Ba möi miyefo mado Rubeno ba mado Gado ba si matonga mado Manase andrö, nifa''oli föna Ndraono Gizeraeli, si mane niŵa''ö Moze khöra.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 13, 'Mato öfa wulu ngahönö zabölö, sowaö-waö föna Yehowa, ba wanuwö ba ndraso ba Yerikho andrö.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 14, 'Me luo da''ö i''ebua''ö Yosua Yehowa, föna Ndraono Gizeraeli fefu, ba la''ata''ufi ia, si mane fangata''ufira Moze mege, götö wa''anau nosonia.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 15, 'Ba humede Yehowa khö Yosua, imane:', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 16, 'Ŵa''ö ba gere andrö, samabea tawöla gamabu''ula li, ndramöi miyaŵa moroi ba Yoridano.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 17, 'Ba ibe''e li Yosua ba gere andrö, imane: Mi''ae miyaŵa moroi ba Yoridano!', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 18, 'Ba tobali, me möi miyaŵa gere andrö, samabea tawöla gamabu''ula li khö Yehowa, moroi ba dalu Yoridano, me lahundragö zabe''e tanö ahe gere andrö, ba mangawuli ba nahania nidanö Yoridano, moluaha, si mane menewi ba si mane me dua wongi, ilawui ngöfi fefu.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 19, 'Ba möi miyaŵa, ira moroi ba Yoridano ba zi mewulu ba mbaŵa si föföna, ba molombase ba Giligala, ba nola, tanö ba gatumbukha luo i''otarai Yerikho.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 20, 'Ba kara andrö si felendrua, ni''ohera moroi ba Yoridano, ba ifatanö''ö Yosua, ba Giligala.', '[]', NULL),
  (3474629, 'OT', 'Yosua', 4, 21, 'Ba imane ba Ndraono Gizeraeli: Na lasofu dania khö namara iraonomi, na lamane: Hadia guna gara andre?[1]', '["MozV 6:20","MozII 14:21"]', NULL),
  (3474629, 'OT', 'Yosua', 4, 22, 'Ba mi''ombakha''ö ba ndraonomi, mimane: Tanö sabe''e lala Ndraono Gizeraeli, me latörö Yoridano andrö,', '["MozV 6:20","MozII 14:21"]', NULL),
  (3474629, 'OT', 'Yosua', 4, 23, 'me no i''ogo''öisi nidanö Yoridano Lowalangimi, Yehowa, fönami, irege no mi''ötö, si mane folau Lowalangimi, Yehowa, ba nasi zukhu andrö, ni''ogo''öisinia fönama, irege no ma''ötö,[2]', '["MozV 6:20","MozII 14:21"]', NULL),
  (3474629, 'OT', 'Yosua', 4, 24, 'ena''ö aboto ba dödö niha ba guli danö fefu danga Yehowa andrö, he wisa wa''abölönia, ena''ö la''ata''ufi Lowalangira Yehowa, si lö mamalö-malö.', '["MozV 6:20","MozII 14:21"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 1, 'Ba tobali me larongo razo Ndraono Gamori fefu, yefo Yoridano, tanö ba nasi, ba razo Ndrawa Gana''ana, si hene asi wa no i''ogo''öisi Yehowa nidanö Yoridano föna Ndraono Gizeraeli, irege no la''ötö, ba atalö dödöra ba lö''ö sa''ae fa''abe''e dödö khöra, ba Ndraono Gizeraeli.[1]', '["MozII 15:15"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 2, 'Ba me luo da''ö, ba imane Yehowa khö Yosua: Fazökhi khöu wörögi kara, ba fuli boto Ndraono Gizeraeli, zamuza tö.', '[]', NULL),
  (3474630, 'OT', 'Yosua', 5, 3, 'Ba ifazökhi khönia wörögi kara Yosua, ba iboto Ndraono Gizeraeli ba gahe hili-hili Garolati.', '[]', NULL),
  (3474630, 'OT', 'Yosua', 5, 4, 'Ba da''e mbörö, wa iboto ira Yosua: Fefu niha, saheta mege ba danö Miserayi, ira matua, fefu zabölö, ba no mate ba danö si mate andrö, ba lala, me la''otarai danö Miserayi.', '["MozIV 14:22"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 5, 'Noa sa muboto, ira, dozi ira, saheta andrö. Ba dozi si tumbu ba danö si mate, ba lala, me la''otarai danö Miserayi, ba lö muboto.', '["MozIV 14:22"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 6, 'Öfa wulu fakhe sa''ae mowaö-waö Ndraono Gizeraeli ba danö si mate andrö, irege no ahori fefu niha sabölö, saheta mege ba danö Miserayi, me lö lafondrondrongo li Yehowa; da''ö mbörö wa fahölu khöra Yehowa, lö tola la''ila danö andrö, si möi ba hölu Yehowa khö ndra tuara, ba wame''e khöda, tanö si falawu susu ba ŵe ŵani[2]', '["MozIV 14:22"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474630, 'OT', 'Yosua', 5, 7, 'Ba onora andrö, ba i''e''ebua, fangalira; da''ö niboto Yosua, me no si lö muboto; lö''ö sa muboto ba lala mege.', '["MozIV 14:22"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 8, 'Ba me no ahori muboto ira ba la''iagö golombaseŵa, irege döhö wa''afökhö.', '["MozIV 14:22"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 9, 'Ba imane Yehowa khö Yosua: Ma''ökhö andre no uheta khömi wa''aila andrö, si otarai danö Miserayi. Ba labe''e töi naha andrö Giligala (famagaölö), irugi ma''ökhö andre.', '[]', NULL),
  (3474630, 'OT', 'Yosua', 5, 10, 'Ba molombase Ndraono Gizeraeli ba Giligala ba lalau wasa andrö, ba zi mewele''öfa, ba ndraso ba Yerikho andrö.', '["MozII 12:39"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 11, 'Ba la''a mbua danö, me sara wongi aefa wasa, roti si lö mu''aisöni ba böra nifakoe, me luo da''ö.[3]', '["MozII 12:39"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 12, 'Ba tebato "mana" andrö, me sara wongi aefa da''ö, me la''a mbua danö, ba lö''ö sa''ae "mana" ba Ndraono Gizeraeli, ba la''a mbua danö Gana''ana, ba ndröfi andrö.', '["MozII 12:39"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 13, 'Ba me so ba zinga Yerikho Yosua, ba ifaöga hörönia, ifakhölö ia, ba hiza niha ba gamaudunia, sara wöda, si no idöni, ba dangania. Ba i''ondrasi ia Yosua, imane khönia: Hadia, awöma ndra''ugö, ma awö nemalima?[4]', '["MozII 23:23"]', NULL),
  (3474630, 'OT', 'Yosua', 5, 14, 'Ba imane: Tenga, solohe sanuwö andrö, khö Yehowa, ndra''odo; awena si''ai sodo.', '[]', NULL),
  (3474630, 'OT', 'Yosua', 5, 15, 'Ba imane solohe sanuwö andrö, khö Yehowa, khö Yosua: Heta mbadagaheu ba gahemö, me no ni''amoni''ö naha andrö, ba zi so''ö. Ba i''o''ö da''ö Yosua.[5]', '["MozII 3:5"]', NULL),
  (3474631, 'OT', 'Yosua', 6, 1, 'Ba no laduhö mbawa göli Yerikho, no mukusi föna Ndraono Gizeraeli, lö si möi baero ba lö si möi miyomo.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 2, 'Ba imane Yehowa khö Yosua: Hiza, no ube''e ba dangau Yerikho andrö, fabaya razora, niha sabölö andrö.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 3, 'Ba mihene göli mbanua, dozi sabölö, mifasui zamuza; önö ngaluo ölau zi manö.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 4, 'Ba dafitu gere solohe torofe sebua li, fitu, föna dawöla gamabu''ula li. Ba na luo si fitu, ba mewitu mifasui mbanua ba ndramulau dorofe ere andrö.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 5, 'Ba na lalau dorofe, na mirongo linia, ba ndramu''abölögö we''ao sato fefu, ba adudu göli mbanua ba ndramusawö sato, yamudölö ia zamösana.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 6, 'Ba humede ba gere andrö Yosua, ono Nuni, imane khöra: Mifabea dawöla gamabu''ula li! ba dafitu gere solohe torofe sebua li fitu, föna dawöla gamabu''ula li khö Yehowa.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 7, 'Ba lamane ba zato: Milabu, mifasui mbanua ba la''iagö föna dawöla gamabu''ula li khö Yehowa si no mangaro.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 8, 'Ba me no ibe''e li ba zato Yosua, ba mangefa gere andrö, si dafitu, solohe torofe andrö, sebua li, si fitu, föna Yehowa, ba lalau dorofe, ba lafago''ö khöra dawöla gamabu''ula li khö Yehowa.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 9, 'Ba mowaö-waö föna gere andrö, samoli torofe, zi no mangaro andrö, ba sato, ba la''o''ö dawöla gamabu''ula li ba lö la''etu''ö wolau torofe.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 10, 'Ba no ibe''e li Yosua ba zato, no imane: Böi mi''ao, böi mifarongogö limi, sambua li böi aefa ba mbewemi, irugi luo uŵa''ö khömi: Mi''ao! awena dania mu''ao ami.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 11, 'Ba lafatörö dawöla gamabu''ula li, lafasui mbanua zamuza, ba larugi golombaseŵa ba mörö ira ba da''ö.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 12, 'Ba ihulö wongi wemaoso Yosua ba lafabea dawöla gamabu''ula li khö Yehowa ere andrö.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 13, 'Ba ere andrö si dafitu, solohe torofe andrö sebua li, si fitu, föna dawöla gamabu''ula li khö Yehowa, ba fadoro lalau dorofe, ba mowaö-waö fönara si no mangaro andrö ba sato fefu, ba la''o''ö dawöla gamabu''ula li khö Yehowa ba lö aetu wolau torofe.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 14, 'Ba mahemolu ö, ba lafuli lafasui mbanua, zamuza, ba mangawuli ira ba golombaseŵa. Ba önö ngaluo lalau zi manö.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 15, 'Ba me luo si fitu, ba lahulö wongi wemaoso, me afusi wali, ba lafasui mbanua, si manö zui, mewitu; ha me luo da''ö wa mewitu lafasui mbanua.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 16, 'Ba ba zi mewitu, me no lalau dorofe ere andrö, ba imane Yosua ba zato: Milau mu''ao, noa sa ibe''e ba dangami mbanua andre Yehowa!', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 17, 'Ba salakha mbanua andre, ya''ia ba si so bakha fefu, khö Yehowa; ha Rakhaba andrö, sohorö andrö, ni''orifi, ya''ia ba sorudu yomo khönia fefu; me no ibini''ö zinenge andrö, nifatengeda.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 18, 'Ba böi mibabaya zalakha andrö, ma dania lö mi''amoni''ö, ma mihalö zalakha andrö ösa, ba mibali''ö salakha golombaseŵa Ndraono Gizeraeli ba mifobörö wa''atekiko.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 19, 'Ba fefu wirö ba ana''a ba fefu wakake töla ba fakake si''öli, ba ni''amoni''ö khö Yehowa; ba girö-girö andrö khö Yehowa labe''e.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 20, 'Ba mu''ao zato ba lalau dorofe. Ba tobali me larongo li dorofe sato, ba la''ebua''ö lira we''ao, ba adudu göli, ba lasawö göli sato, idölö manö ia zamösana, ba atu''a ira ba mbanua.[1]', '["Heb 11:30","MozV 20:13"]', NULL),
  (3474631, 'OT', 'Yosua', 6, 21, 'Ba lalakha''ö fefu zi so ba mbanua bakha, i''otarai ndra matua, numalö ba ndra alawe, ba i''otarai nono matua, numalö ba zi no tohare huwa ba ba zaŵi ba ba mbiri-biri ba ba galide, la''ö''ötö föda.[2]', '["Heb 11:30","MozV 20:13"]', NULL),
  (3474631, 'OT', 'Yosua', 6, 22, 'Ba imane Yosua ba niha andrö, si darua, si möi no, ba wamauze tanö: Mi''ae ba nomo ndra alawe andrö, sohorö andrö, ba mi''ohe tou ndra alawe andrö, awö fefu dana khönia, si mane fahölusami khönia.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 23, 'Ba möi nono matua andrö, samauze andrö, la''ohe tou Rakhaba andrö ba amania ba inania ba ira talifusönia, awö fefu zi so khönia, si samba omo ya''ira, la''ohe baero ba lafa''aso baero, föna golombaseŵa Ndraono Gizeraeli.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 24, 'Ba banua andrö, ba latunu alitö, fabaya ösinia fefu; ha firö ba ana''a ba fakake töla ba fakake si''öli nibe''e ba naha girö-girö ba nomo Yehowa.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 25, 'Ba Rakhaba andrö, sohorö andrö, ba soroiyomo namania fefu, awö fefu dana khönia, ba i''orifi Yosua. Ba ba Ndraono Gizeraeli so ia, irugi ma''ökhö andre, me no ibini''ö zinenge andrö, nifatenge Yosua, ba wamauze Yerikho andrö.', '[]', NULL),
  (3474631, 'OT', 'Yosua', 6, 26, 'Ba i''ohe ira ba hölu Yosua, me luo da''ö imane: Ni''elifi khö Yehowa niha si maoso ba wanaru''ö banua andre, Yerikho andre! Ya mate nononia si a''a, na ibe''e tou doyo ba ononia si akhi, na ibe''e duhö-duhö mbawa göli![3]', '["RazI 16:34"]', NULL),
  (3474631, 'OT', 'Yosua', 6, 27, 'Ba itolo Yosua Yehowa ba humöngö duriania ba danö ma''asagörö.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 1, 'Ba numalö danga Ndraono Gizeraeli ba zalakha andrö, ihalö zalakha Akhano, ono Kharimi ono Zabadi ono Zera, mado Yuda. Ba mofönu Yehowa ba Ndraono Gizeraeli.[1]', '["Faigi 22:20"]', NULL),
  (3474632, 'OT', 'Yosua', 7, 2, 'Ba ifatenge niha Yosua, moroi ba Yerikho, ifatenge ba Ga''i, ba ngai Mbeti Avena, tanö ba gatumbukha luo i''otarai Mbetieli, imane khöra: Mi''ae misi yaŵa ba mifauzei danö.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 3, 'Ba lafuli ira khö Yosua, lamane khönia: Alakha lö ahori möi misi yaŵa niha! Na mato dua ngahönö, irege tölu ngahönö, zi möi misi yaŵa, ba wanuwö A''i andrö. Böi fakao zato fefu; lö''ö sa atoto ira.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 4, 'Ba möi misi yaŵa ira, mato tölu ngahönö niha, ba te''ala ira labe''e banua Ga''i andrö.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 5, 'Ba mato tölu ngafulu a önö labunu khöra banua Ga''i ba lagohi ira baero mbanua, irugi Zabari ba lalau khöra ba zanaere hili. Ba amaedola zangulu dödö zato, timba zi tobali idanö.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 6, 'Ba isika nukhania Yosua, ifalögu tou ia ba danö, föna dawöla gamabu''ula li khö Yehowa, irugi bongi, ya''ia ba satua ndraono Gizeraeli, lalau gawu-gawu ba högöra.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 7, 'Ba imane Yosua: He So''aya, Yehowa, hadia wa no öfa''ötö ba Yoridano niha andre, ba wame''e ba danga Ndraono Gamori ya''aga, ba wamakiko ya''aga? Ena''ö na ahono dödöma mege ba na ma''iagö manö yefo Yoridano!', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 8, 'Fondrondrongo, So''aya! Hadia niŵa''ögu, me no labali''ö ira furi Iraono Gizeraeli, föna nemalira?', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 9, 'Ba larongo dania Dawa Gana''ana, dozi soi ba danö andre ba lafa''u''u ndra''aga ba lahori ba danö motöi ya''aga, ba he öwisa ba döimö andrö, sebua andrö?', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 10, 'Ba imane Yehowa khö Yosua: Faoso, hana wa no öfalögu tou ndra''ugö?', '["MozII 19:10"]', NULL),
  (3474632, 'OT', 'Yosua', 7, 11, 'No mamazökhi horö Ndraono Gizeraeli, no lasawö gamakhoita andrö khögu, nifakhoigu khöra; noa sa lahalö zalakha andrö ösa; noa sa managö ba no labini''ö na; noa na''i labini''ö barö gama-gamara.', '["MozII 19:10"]', NULL),
  (3474632, 'OT', 'Yosua', 7, 12, 'Ba tebai lalaŵa nemalira Iraono Gizeraeli; labali''ö ira furi föna nemalira, me no tobali salakha ira. Lö''ö sa''ae utolo ami, na lö miheta ba khömi zalakha andrö.', '["MozII 19:10"]', NULL),
  (3474632, 'OT', 'Yosua', 7, 13, 'Faoso, famoni ira fefu, ömane: Mi''amoni, irege mahemolu! Imane sa Yehowa, Lowalangi Ndraono Gizeraeli: No so ba khömi zalakha, ya''ami Iraono Gizeraeli; tebai milaŵa nemalimi, irege no miheta ba khömi zalakha andrö.[2]', '["MozII 19:10"]', NULL),
  (3474632, 'OT', 'Yosua', 7, 14, 'Ba mi''ondrasi, si hulö wongi, sambu-sambua mado; ba mado andrö, si göna khö Yehowa, ba ndramu''ondrasi, sara-sara daha; ba si sara daha andrö, si göna khö Yehowa, ba la''ondrasi, samba-samba omo; ba si samba omo andrö, si göna khö Yehowa, ba la''ondrasi samö-samösa.', '["MozII 19:10"]', NULL),
  (3474632, 'OT', 'Yosua', 7, 15, 'Ba si göna dania ba zalakha andrö, ba nitunu ba galitö, ya''ia ba si so khönia fefu, börö me no isawö nifakhoi Yehowa ba me no ifazökhi horö ba Ndraono Gizeraeli.', '["MozII 19:10"]', NULL),
  (3474632, 'OT', 'Yosua', 7, 16, 'Ba ihulö wongi wemaoso Yosua, iŵa''ö la''ondrasi Iraono Gizeraeli, sambu-sambua mado, ba göna mado Yuda.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 17, 'Ba iŵa''ö la''ondrasi daha mado Yuda, ba göna ma''uwu Zera. Ba iŵa''ö la''ondrasi ma''uwu Zera samö-samösa, ba göna Zabadi.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 18, 'Ba iŵa''ö la''ondrasi si samba omo ya''ira, samö-samösa, ba göna Nakhano, ono Kharimi ono Zabadi ono Zera, mado Yuda.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 19, 'Ba imane Yosua khö Nakhano: He onogu, fosumange Yehowa, Lowalangi Ndraono Gizeraeli, ba suno ia ba ombakha''ö khögu nilaumö, böi bini''ö khögu.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 20, 'Ba itema li Yosua Akhano, imane: Si ndruhu, no ufazökhi horö khö Yehowa, Lowalangi Ndraono Gizeraeli, da''u''ombakha''ö zilalö dangagu:', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 21, 'No u''ila ba nihalöda andrö mbaru sebua, baru Zineara, si sökhi, ba firö, dua ngaotu ba rufia ba sambua wamakhai mbaru, ana''a, lima wulu rufia fanimba, ba terou dödögu, ba uhalö, ba hiza, no mubini''ö barö danö, ba dalu nose khögu, fabaya firö andrö.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 22, 'Ba ifatenge zinenge Yosua, ba fagohi da''ö, lasaŵa nose, ba hiza, no mubini''ö ba nose khönia, fabaya firö andrö.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 23, 'Ba lahalö ba da''ö baose ba la''ohe khö Yosua ba ba Ndraono Gizeraeli fefu, latou''ö tou föna Yehowa.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 24, 'Ba ihalö Yosua Nakhano andrö, ma''uwu Zera, awö wirö andrö, awö mbaru, awö wamakhai mbaru andrö, ba ononia matua ba ononia alawe, fabaya saŵinia ba kalidenia, ba biri-birinia, ba osenia, awö fefu hadia ia zi so khönia; ba fao Ndraono Gizeraeli fefu; la''ohe miyaŵa ba ndraso Nakhori.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 25, 'Ba imane Yosua: Ha lö atekiko ndra''aga öbe''e! Yamufakiko ndra''ugö Yehowa, ma''ökhö! Ba latebu kara ia Iraono Gizeraeli fefu ba latunu ira ba lahawui kara.', '[]', NULL),
  (3474632, 'OT', 'Yosua', 7, 26, 'Ba oya la''owuloi kara, balu-balunia, irugi ma''ökhö andre.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 1, 'Ba imane Yehowa khö Yosua: Böi ata''u ndra''ugö ba böi atalö dödöu. Ohe zabölö fefu ba labu, ae misi yaŵa ba Ga''i. Hiza, no ube''e ba dangau razo Ga''i andrö, awö mbanuania, awö danönia.[1]', '["MozI 15:1 b.t.","MozV 20:14"]', NULL),
  (3474633, 'OT', 'Yosua', 8, 2, 'Ba ölau ba mbanua Ga''i ba khö razora nilaumö ba Yerikho ba khö razora; ba hadia nisöndrami khöra ba uriföra, ba hana na mihalö khömi. Ba öfatenge ösa, niha, samini''ö ya''ira ba gero mbanua.[2]', '["MozI 15:1 b.t.","MozV 20:14"]', NULL),
  (3474633, 'OT', 'Yosua', 8, 3, 'Ba maoso Yosua, awö zabölö fefu, ba we''amöi misi yaŵa ba Ga''i. Ba itutuyu zi tölu ngafulu sabölö Yosua ba ifatenge, ba zi bongi.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 4, 'Ba ibe''e li khöra, imane: Si tobini dania ami ba gero mbanua; böi aröu ami ba ngai mbanua ba si te''anö manö ami fefu.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 5, 'Ba ya''odo, awö fefu zi fao khögu, ba mahatö''ö ndra''aga ba mbanua; ba na möi ira baero, si mane no, ba wangondrasi ya''aga, ba moloi ndra''aga.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 6, 'Ba lagohi dania ndra''aga, irege no aefa ira ba mbanua mabe''e; lamane sa dania dödöra: moloi ira, si mane ba zi föföna mege.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 7, 'Ba moloi manö ndra''aga. Ba so dania ami, moroi ba mbini-mbini andrö, ba atu''a ami ba mbanua mibe''e; Yehowa, Lowalangimi, zame''e ba dangami.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 8, 'Ba na no atu''a ami mibe''e, ba migule''ö galitö ba mbanua andrö. Mi''o''ö niŵa''ö Yehowa. Hiza, no ube''e li khömi!', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 9, 'Ba i''efa''ö ira Yosua, ba lasaŵa mbini-mbini andrö, la''iagö gotaluara Mbetieli Ga''i, tanö ba gaekhula luo i''otarai Ga''i. Ba lö aefa Yosua ba zi möi manuwö, ba zi bongi andrö.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 10, 'Ba ihulö wongi Yosua wamöfö''ö sanuwö, ba isaŵa misi yaŵa Ga''i, awö zatua Ndraono Gizeraeli, la''iagö föna zanuwö.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 11, 'Ba dozi sabölö, awönia, ba fao misi yaŵa, lahatö''ö ira, larugi gamaudu mbanua, ba molombase ira tanö yöu, i''otarai Ga''i, daso ba gotaluara Ga''i.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 12, 'Awena iföfö''ö niha, mato lima ngahönö, ba ifatenge ba mbini-mbini andrö, ba gotaluara Mbetieli Ga''i, tanö ba gaekhula luo, i''otarai mbanua.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 13, 'Ba dozi sanuwö, sabölö fefu, yöu mbanua, awö zi so moroi furi, ba fafa''ese tanö ba gaekhula, i''otarai mbanua. Ba Yosua, ba isaŵa dalu ndraso, ba zi bongi andrö.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 14, 'Ba me i''ila da''ö razo Ga''i, ba la''aliogö banua Ga''i, lahulö wongi, wangondrasi Iraono Gizeraeli, ba wasöndrata ena''ö, razo awö zabölö khönia fefu ba naha nihonogöi, föna-föna zalo''o. Ba lö i''ila, wa no so zi tobini tanö ba gaekhula, i''otarai mbanua.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 15, 'Ba labe''e ni''alani ira Yosua ba Iraono Gizeraeli fefu, moloi ira, lasaŵa danö si mate.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 16, 'Ba la''oroi''ö fefu zi so yomo ba mbanua na, ba wolohi ya''ira, ba lagohi Yosua, ba aröu aefa ira ba mbanua.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 17, 'Ba samösa lö si tosai ba Ga''i ba ba Mbetieli, si lö möi ba wolohi Iraono Gizeraeli, ba lö''ö sa mukusi mbawa göli mbanua furira, ba lagohi Ndraono Gizeraeli.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 18, 'Ba imane Yehowa khö Yosua: Oro''ö doho, si so ba dangau, ba Ga''i andrö; ube''e sa''ae ba dangau! Ba i''oro''ö Yosua doho andrö si so ba dangania, ifaudugö Ga''i.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 19, 'Ba la''aliogö ira si tobini andrö, laröi nahara, fulöi ira, me i''oro''ö danga Yosua, lasaŵa miyomo, atu''a ira; ba lada''i-da''i wogule''ö alitö.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 20, 'Ba me labali''ö ira furi banua Ga''i no mege, ba la''ila miyaŵa zimbo mbanua andrö, ba atata dölara, tebai moloi ira, heza göi lasaŵa ena''ö. Ba si no moloi andrö, sanaŵa tanö si mate ba labali''ö ira furi ba zolohi andrö.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 21, 'Ba la''ila ira Yosua ba Iraono Gizeraeli fefu wa no atu''a ba mbanua zi tobini andrö, awö zimbo mbanua miyaŵa, ba lafuli ira, ba fasöndra ba mbanua Ga''i andrö.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 22, 'Ba lafaondragö ira si so yomo ba mbanua, tobali tolazi ira ba gotalua Ndraono Gizeraeli, so moroi föna ba so moroi furi. Ba la''ö''ötö tou, irege samösa lö si tosai, soloi ena''ö ba sauri.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 23, 'Ba razo Ga''i andrö ba lara''u auri ba la''ohe khö Yosua.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 24, 'Ba me no ahori labunu Iraono Gizeraeli mbanua Ga''i andrö, solohi ya''ira mege, baero ba mbenua, ba danö si mate, me no ahori mate ba mbawa zi''öli, irege samösa lö si tosai, ba mangawuli ba Ga''i Ndraono Gizeraeli fefu ba labunu zi so yomo ba mbanua.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 25, 'Ba tobali felendrua ngahönö zi mate, me luo da''ö ira matua ba ira alawe, banua Ga''i andrö fefu.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 26, 'Ba lö iböda dangania Yosua wangoro''ö toho no mege, irege no ahori tefakiko mbanua Ga''i andrö.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 27, 'Ha uriföra ba hadia ia nisöndrara ba mbanua, ba lahalö khöra Iraono Gizeraeli, dali niŵa''ö Yehowa, oroisania khö Yosua.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 28, 'Ba ifatunu''ö Ga''i Yosua, labali''ö adudula si lö mamalö-malö, tanö si mate, irugi ma''ökhö, andre.', '["MozV 21:23"]', NULL),
  (3474633, 'OT', 'Yosua', 8, 29, 'Ba ifataŵi''ö ba döla geu razo Ga''i, irugi tanö owi. Ba me aekhu luo, ba iŵa''ö Yosua, laheta ba döla geu mbotonia, ba latibo''ö baero mbanua ba lahöna gara balu-balunia; irugi ma''ökhö andre.[3]', '["MozV 21:23"]', NULL),
  (3474633, 'OT', 'Yosua', 8, 30, 'Ba ifazökhi naha wame''e sumange Yosua khö Yehowa, Lowalangi Ndraono Gizeraeli, ba hili Gebala,', '["MozII 20:25; MozV 27:4"]', NULL),
  (3474633, 'OT', 'Yosua', 8, 31, 'i''o''ö niŵa''ö genoni Yehowa andrö, Moze ba Ndraono Gizeraeli, nitanö ba zura goroisa andrö khö Moze: naha wame''e sumange kara si lö mutoto, si lö mufatörö fakake si''öli, ba labe''e zumange nitunu khö Yehowa, ba detenia ba lataba zumange fangorifi.[4]', '["MozII 20:25; MozV 27:4"]', NULL),
  (3474633, 'OT', 'Yosua', 8, 32, 'Ba isura ba da''ö ba dete gara goroisa Moze andrö, nisurania ba Ndraono Gizeraeli.', '["MozII 20:25; MozV 27:4"]', NULL),
  (3474633, 'OT', 'Yosua', 8, 33, 'Ba dozi Iraono Gizeraeli ba satuara ba kumandru ba sanguhuku, ba no lafatambai dawöla gamabu''ula li, no fangai ba gere ono Lewi andrö, samabea tawöla gamabu''ula li khö Yehowa, he niha bö''ö, ba he madora, matonga tanö ba hili Garisi ba matonga tanö ba hili Gebala, la''o''ö niŵa''ö genoni Lowalangi andrö, Moze, föna, ba wamahowu''ö mado Gizeraeli.[5]', '["MozV 27:12"]', NULL),
  (3474633, 'OT', 'Yosua', 8, 34, 'Ba noa da''ö, ba ibaso [Yosua] fefu daroma li oroisa andrö, famahowu''ö ba fangelifi, dali sibai zi so ba zura goroisa andrö.', '[]', NULL),
  (3474633, 'OT', 'Yosua', 8, 35, 'Sambua li lö''ö, niŵa''ö Moze, si lö ibaso Yosua ba Ndraono Gizeraeli fefu, sorudu, ba he ba ndra alawe ba he ba ndraono ba he ba niha bö''ö, si no fao khöra.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 1, 'Ba me larongo da''ö razo fefu, yefo Yoridano, ba hili ba ba zalo''o ba si hene asi sebua fefu irege tanö ba hili Libano, Dawa Kheti andrö ba Iraono Gamori ba Dawa Gana''ana ba Dawa Weresi ba Dawa Hewi ba Dawa Yebusi,', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 2, 'ba la''orudugö ira, ha sara dödö, ba wanimba Yosua ba Iraono Gizeraeli.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 3, 'Ba larongo banua Gibeona andrö hadia nilau Yosua ba Yerikho ba ba Ga''i.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474634, 'OT', 'Yosua', 9, 4, 'Ba la''onekhe''ö göi, maoso ira, lafatö''ö göra ba lala, si''e satua labe''e ba hulu galidera, awö naha nagu satua, si no asika, niböbö.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 5, 'Ba badagahe satua, si no mubalo labe''e ba gahera, la''onukha nukha satua ba fefu kue, nifatö''öra, ba no oköli, kiwo''ö sa''ae.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 6, 'Ba möi ira khö Yosua ba golombaseŵa ba Giligala, ba lamane khönia ba ba Ndraono Gizeraeli: Ma''otarai danö saröu, ba datalau fawu''u li.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 7, 'Ba lamane Iraono Gizeraeli ba Ndrawa Hewi andrö: Ma dania ba da''e khöda so mbanuada khömi, ba he mawisa fawu''u li khömi?', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 8, 'Ba lamane khö Yosua: Sawuyumö ndra''aga. Ba imane Yosua: Ha niha ami ba heza mi''otarai?', '["MozIV 21:24"]', NULL),
  (3474634, 'OT', 'Yosua', 9, 9, 'Ba lamane khönia: Tanö saröu sibai ma''otarai, ya''aga sawuyumö, börö duria Lowalangimö andrö, Yehowa; noa sa marongo duriania, he hadia ia fefu nilaunia ba danö Miserayi andrö,', '["MozIV 21:24"]', NULL),
  (3474634, 'OT', 'Yosua', 9, 10, 'ba he zui fefu nilaunia ba razo Ndraono Gamori andrö si darua, yefo Yoridano, Sihona, razo Hesibona ba Ogi, razo Mbazana ba Gasaroti.[1]', '["MozIV 21:24"]', NULL),
  (3474634, 'OT', 'Yosua', 9, 11, 'Ba lamane khöma satuama ba banuama fefu: Mifaigi gömi ba lala ba mifaondragö ira, ba mimane khöra: Sawuyumi ndra''aga, ba milau fawu''u li khöma.', '["MozIV 21:24"]', NULL),
  (3474634, 'OT', 'Yosua', 9, 12, 'Ya''e kue andre khöma; aukhu na, me mafa''anö ba khöma, öma ba lala, me mofanöga we''amöi khömi, ba hiza, no oköli ba kiwo''ö.', '["MozIV 21:24"]', NULL),
  (3474634, 'OT', 'Yosua', 9, 13, 'Ba ya''e naha nagu khöma: bohou me mafo''ösi, ba iada''e, ba no atika; ba ya''e nukhama ba badagahema: no ahakhö sibai, börö wa''arama ba lala.', '["MozIV 21:24"]', NULL),
  (3474634, 'OT', 'Yosua', 9, 14, 'Ba lahalö göra andrö ösa Iraono Gizeraeli, ba lö lasofu mbawa Yehowa.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 15, 'Ba ilau fahuwu khöra Yosua, fawu''u li ira, ba wangorifi ya''ira. Ba möi ba hölu khöra zatua mbanua.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 16, 'Ba ha tölu bongi aefa fawu''u li ira, ba larongo wa sahatö ira, wa ba da''ö khöra so mbanuara.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 17, 'Ba maoso Ndraono Gizeraeli, ba ha dua wongi, ba larugi mbanua khöra. Ba töi mbanuara andrö, ba Gibeona ba Kafira ba Be''eroti ba Kiriati Yeari.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 18, 'Ba la''orifi ira Iraono Gizeraeli, me no möi ba hölu khöra zatua mbanua ba khö Yehowa, Lowalangi Ndraono Gizeraeli.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 19, 'Ba lamane salaŵa fefu ba zato: No möi ba hölu ndra''aga khöra ba khö Yehowa, Lowalangi Ndraono Gizeraeli, andrö wa lö tola tababaya ira.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 20, 'Talau khöra zane ba ta''orifi ira, fa böi göna fönu [Lowalangi] ita, me no möi ita ba hölu khöra.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 21, 'Ba lamane khöra salaŵa: Ni''orifi ira. Ba tobali sangai eu ba sana''u idanö ira ba mbanua fefu, si mane niŵa''ö zalaŵa andrö khöra.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 22, 'Ba ifahede''ö khöra Yosua, ba imane khöra: Hana wa milimo ndra''aga, wanguma''ö: Banua saröu ndra''aga, ba no ba da''e khöda mbanuami?', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 23, 'Andrö ya ni''elifi ami ba böi yamalö-malö wa sawuyu ami, sangai eu ba sana''u idanö ba nomo Lowalangigu!', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 24, 'Ba latema li Yosua, lamane: No te''ombakha''ö khöma, ya''aga sawuyumö, hadia niŵa''ö Lowalangiu Yehowa ba genoninia Moze andrö, wa edöna ibe''e khömi danö ma''afefu, awö wa edöna ihori fönami fefu niha ba danö. Ba ata''u sibai ndra''aga mibunuga; andrö wa mamanö.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 25, 'Ba iya''e, ba ba dangau so ndra''aga; satulö dödöu ba somasi''ö, ba fatörö khöma.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 26, 'Ba ilau khöra zi manö, i''efa''ö ira ba danga Ndraono Gizeraeli, fa böi labunu.', '[]', NULL),
  (3474634, 'OT', 'Yosua', 9, 27, 'Ba ibali''ö sangai eu ba sana''u idanö ba mbanua fefu ba ba naha wame''e sumange khö Yehowa ira Yosua, me luo da''ö, irugi ma''ökhö andre, ba nahia nituyu Yehowa dania.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 1, 'Ba me irongo Adonisede, razo Yeruzalema, wa no atu''a ira ba Ga''i ibe''e Yosua, awö wa no ifakiko ira, wa no ilau ba Ga''i ba khö razora nilaunia ba Yerikho ba khö razora, awö wa no fawu''u li ira mbanua Gibeona Ndraono Gizeraeli, wa no lasaigö ira ba ngaira, ba ata''u sibai ira,', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 2, 'me no banua sebua Gibeona andrö, fondrege zebua ba danö; ebua moroi ba Ga''i, ba oi sabölö sibai mbanuara.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 3, 'Ba ifatenge Adonisede andrö, razo Yeruzalema, zinenge khö Hohama, razo Heberona ba khö Wireamo, razo Yaramuti ba khö Yafia, razo Lakhisi ba khö Debiri, razo Negelona, imane khöra:', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 4, 'Mi''ae khögu ba mitolodo, ba wanuwö banua Gibeona andrö, me no atulö ira khö Yosua ba ba Ndraono Gizeraeli.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 5, 'Ba la''orudugö ira razo Ndraono Gamori andrö, si dalima, ba so moroi sa: razo Yeruzalema ba razo Heberona ba razo Yaramuti ba razo Lakhasi, ba razo Negelona, awö zabölö khöra fefu; ba lafasui Gibeona, labörötaigö lasuwö.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 6, 'Ba lafatenge khö Yosua ba golombaseŵa ba Giligala banua Gibeona, lamane khönia: Böi lulu zawuyumö; ta''i-ta''i miyaŵa khöma, orifiga, tologa; noa sa la''orudugö ira uduma dozi razo Ndraono Gamori andrö, si so ba hili.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 7, 'Ba möi miyaŵa Yosua, moroi ba Giligala, awö zi möi fasuwö fefu, dozi sabölö.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 8, 'Ba imane Yehowa khö Yosua: Böi ata''ufi ira, ube''e sa ba dangau ira; samösa lö ba khöra sabölö moroi khöu!', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 9, 'Ba irugi ira Yosua, lö mudöna-döna, me no sara wongi mowaö-waö ndra Yosua, la''oroi Giligala.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 10, 'Ba humufa ira ibe''e Yehowa, föna Ndraono Gizeraeli, ba la''alani sibai ira, ba zinga Gibeona ba lagohi ira ba lala ba zanösö andrö ba Mbeti Horona, moloi labe''e, irugi ba Gaseka ba irugi Makeda.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 11, 'Ba me no larugi zanue andrö ba Mbeti Horona, woloi föna Ndraono Gizeraeli, ba ihawui ira kara segebua Yehowa, moroi ba mbanua si yaŵa, irugi ba Gaseka, ba mate ira, ba ato zi mate ba deu kara andrö, moroi ba nibunu Ndraono Gizeraeli si''öli.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 12, 'Me luo da''ö humede Yosua khö Yehowa, me ibe''e ba danga Ndraono Gizeraeli Ndraono Gamori andrö Yehowa; imane ba zanehe Ndraono Gizeraeli: "Batogö''ö, ya''ugö luo, ba Gibeona, ba ya''ugö baŵa, ba ndraso ba Nayalona!"', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 13, 'Ba ibadugö ia luo ba tebato wofanö mbaŵa, irege no lalau mbalöra Iraono Gizeraeli ba nemalira. Hadia, lö musura da''ö ba "zura zatulö" andrö? Ba tebato luo ba dalu lalania ba mbanua ba lö aösö ia aekhu, arakha ma''ö-ma''ökhö.[1]', '["Yes 28:21; SamII 1:18"]', NULL),
  (3474635, 'OT', 'Yosua', 10, 14, 'Ba sara lö luo si mane da''ö, he föna ö ba he furi ö, wa i''o''ö li niha Yehowa; Yehowa sa atö zi fasuwö, salahi Ndraono Gizeraeli.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 15, 'Ba mangawuli ba golombaseŵa ba Giligala Yosua, awö Ndraono Gizeraeli fefu.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 16, 'Ba moloi razo andrö, si dalima, ba labini''ö ira ba dögi narö hili, ba zinga Makeda.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 17, 'Ba te''ombakha''ö khö Yosua: No labini''ö ira ba dögi narö hili, ba zinga Makeda, razo andrö, si dalima.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 18, 'Ba imane Yosua: Mifagaölö gara sebua ba mbawa dögi andrö, ba mifataro niha, ba ngai, ba wanaro.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 19, 'Ba ya''ami, ba böi mibato, migohi nemalimi, mibubunu moroi furi, böi mifa''amöi miyomo ba mbanuara; noa sa atö ibe''e ba dangami ira Lowalangimi, Yehowa!', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 20, 'Ba me no alua latimba ira Yosua ba Iraono Gizeraeli, me no te''ala sibai labe''e, irege arakha ahori — si tosai na, ba no lakhamö mbanua saro —', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 21, 'ba mangawuli niha fefu khö Yosua, ba golombaseŵa, ba Makeda, lö hadia ia, si göna ira; ba lö''ö sa''ae si lö ata''u molaŵa Iraono Gizeraeli.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 22, 'Ba imane Yosua: Mibokai mbawa dögi andrö ba mihalö khögu razo andrö, si dalima, bakha ba dögi.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 23, 'Ba la''o''ö da''ö; la''ohe razo andrö, si dalima, ba dögi andrö: razo Yeruzalema ba razo Heberona ba razo Yaramuti ba razo Lakhisi ba razo Negelona.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 24, 'Ba me no la''ohe khö Yosua razo andrö, ba ifakaoni''ö ndra matua Ndraono Gizeraeli fefu; ba imane ba zangoloi''ö sanuwö, si fao khönia mege: Mi''ae ba da''e ba mihundragö mbagi razo andre! Ba la''ondrasi, lahundragö mbagi.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 25, 'Ba imane khöra Yosua: Böi mi''ata''ufi ba böi atalö dödömi! Mi''abe''e''ö dödö ba ya''abölö ami; si manö sa nifatörö Yehowa ba nemalimi fefu, nitimbami!', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 26, 'Aefa da''ö, ba ifabunu''ö ira Yosua ba me no labunu, ba ifataŵi''ö, lima nga''eu döla geu; ba manaŵa-naŵa ira ba döla geu andrö, irege tanö owi.', '["MozV 21:23"]', NULL),
  (3474635, 'OT', 'Yosua', 10, 27, 'Ba me aekhu-aekhu luo, ba ifaheta''ö ba döla geu andrö Yosua; ba latibo''ö ba dögi narö hili andrö, ba nibini''öra ya''ira mege; ba lafagaölö gara segebua ba mbawa dögi andrö; irugi ma''ökhö andre.[2]', '["MozV 21:23"]', NULL),
  (3474635, 'OT', 'Yosua', 10, 28, 'Ba me luo da''ö, ba atu''a göi ira ba Makeda ibe''e Yosua, lalaŵa bawa zi''öli, ba ilakha''ö razora Yosua, awö mbanua, awö niha fefu, si so ba mbanua bakha, samösa lö ibe''e moloi; ba khö razo Makeda ba ilau nilaunia khö razo Yerikho.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 29, 'Aefa da''ö, ba iheta ia ba Makeda Yosua, awö Ndraono Gizeraeli fefu, lasaŵa Libena ba lasuwö mbanua Libena.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 30, 'Ba ibe''e ba danga Ndraono Gizeraeli mbanua da''ö göi Yehowa, fabaya razora, lalaŵa bawa zi''öli, ahori labunu niha si so ba mbanua bakha, samösa lö labe''e moloi; ba khö razora, ba lalau nilaura khö razo Yerikho.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 31, 'Aefa da''ö, ba iröi Libena Yosua, awö Ndraono Gizeraeli fefu, lasaŵa Lakhisi, lafasui ba lasuwö.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 32, 'Ba ibe''e ba danga Ndraono Gizeraeli Lakhisi andrö Yehowa; mahemolu ö, ba atu''a ira, lalaŵa bawa zi''öli, ahori labunu niha ba mbanua, lafatörö si''aikö nifatöröra ba Libena.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 33, 'Ba möi miyaŵa Horamo, razo Geseri, ba wanolo banua Lakhisi. Ba i''alani ia, fabaya sabölö andrö khönia Yosua, irege samösa lö falukha moloi, ya''ira andrö.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 34, 'Aefa da''ö, ba iröi Lakhisi Yosua, awö Ndraono Gizeraeli fefu, lasaŵa Negelona andrö; lafasui ba lasuwö.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 35, 'Ba atu''a ira, me luo da''ö, lalaŵa bawa zi''öli, labunu fefu niha ba mbanua, me luo da''ö; ifatörö si''aikö Yosua nifatörönia ba Lakhisi.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 36, 'Aefa da''ö, ba iröi Negelona Yosua, awö Ndraono Gizeraeli fefu, lasaŵa Heberona ba lasuwö.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 37, 'Atu''a ira ba lalaŵa bawa zi''öli, labunu razo, fabaya banua si fasui fefu, fefu niha, si so ba mbanua bakha, tobali samösa lö falukha moloi; ifatörö si''aikö Yosua nifatörönia ba Negelona: ilakha''ö mbanua, fabaya niha fefu, si so ba mbanua bakha.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 38, 'Ba isaŵa Debira Yosua, awö Ndraono Gizeraeli fefu, ba lasuwö.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 39, 'Te''ala labe''e, fabaya razo, ba banua si fasui, ba lalaŵa bawa zi''öli, lalakha''ö fefu niha ba mbanua, tobali samösa lö falukha moloi; nifatörö Yosua ba Heberona, ba ifatörö si''aikö ba Debira ba khö razora ba si mane nifatörönia ba Libena ba khö razora.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 40, 'Si manö wangai Yosua khönia tanö ma''asagörö, hili ba tanö raya ba salo''o ba sanaere hili; ba razora fefu i''alani, tobali samösa lö falukha moloi, ba ilakha''ö fefu zauri, si mane niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 41, 'Ba te''ala ibe''e Yosua, i''otarai Gadesi Mbarenea, numalö ba Gasa ba tanö Gosena andrö ma''asagörö, irugi Gibeona.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 42, 'I''osamuzaigö wolaŵa razo andrö fefu Yosua ba fangai khönia tanöra; Yehowa, Lowalangi Ndraono Gizeraeli sa''ae zanuwö, salahi Ndraono Gizeraeli.', '[]', NULL),
  (3474635, 'OT', 'Yosua', 10, 43, 'Aefa da''ö, ba ifuli ia ba golombaseŵa ba Giligala Yosua, awö Ndraono Gizeraeli fefu.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 1, 'Ba me irongo da''ö Yabino, razo Hasora, ba ifatenge khö Yobabi, razo Madona ba khö razo Zimerono ba khö razo Nakhisafi,', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 2, 'ba ba razo yöu, ba zohili ba ba zalo''o, raya Gineroti, ba ndraso ba ba hili ba Dora ba mbewe nasi.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 3, 'Dawa Gana''ana ba gatumbukha ba ba gaekhula, Iraono Gamori ba Dawa Kheti ba Dawa Weresi ba Dawa Yebusi ba hili ba Dawa Hewi, ba gahe hili Heremono ba danö Misefa.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 4, 'Da''ö zi so moroi si yaŵa, awö zabölö khöra fefu, ato sibai, timba ngawua nene ba mbewe nasi, ba oya göi kudo ba kureta.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 5, 'Ba mamagölö razo andrö fefu, so ira ba molombase ira ba zinga mbombo Meromo, ba wolau ba Ndraono Gizeraeli.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 6, 'Ba imane Yehowa khö Yosua: Böi ata''ufi ira; na mane wa''alaŵa luo mahemolu, ba no tou ba danö so ira fefu, nibunu Ndraono Gizeraeli, ube''e; ni''eŵa gölu-ölu kudo khöra ba nitunu guretara.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 7, 'Ba ikhamö ira Yosua, awö zabölö khönia fefu, lö mudöna-döna, ba zinga mbombo Meromo andrö, ba lahawui ira.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 8, 'Ba ibe''e ira ba danga Ndraono Gizeraeli Yehowa ba te''ala labe''e, ba lagohi irugi Zidona, banua sebua andrö, ba irugi Misirefo Mayi ba irege ba ndraso ba Misefe, tanö ba gatumbukha, ba labunu tou, irege samösa lö tosai, soloi.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 9, 'Ba ifatörö khöra Yosua, niŵa''ö Yehowa khönia: ifa''eŵa''ö gölu-ölu kudo khöra ba ifatunu''ö guretara.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 10, 'Ba mangawuli Yosua, me luo da''ö ba atu''a ira ba Hasora, ba ifabunu''ö razora. Högö mbanua ba nöri andrö fefu föna Hasora andrö.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 11, 'Ba labunu niha fefu, si so ba mbanua bakha, lalakha''ö, lö lasaigö zonoso; ba ifatunu''ö Hasora andrö Yosua.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 12, 'Ba möi ba danga Yosua mbanua razo andrö fefu, fabaya razora fefu, ba ifabunu''ö, ilakha''ö, i''o''ö niŵa''ö genoni Lowalangi andrö, Moze.[1]', '["MozV 20:13"]', NULL),
  (3474636, 'OT', 'Yosua', 11, 13, 'Ba fefu mbanua nitaru''ö ba zuzu hili-hili ba lö latunu Iraono Gizeraeli, ha si''aikö Hasora andrö ifatunu''ö Yosua.', '["MozV 20:13"]', NULL),
  (3474636, 'OT', 'Yosua', 11, 14, 'Ba hadia ia fefu nisöndrara ba mbanua andrö ba uriföra, ba lahalö khöra Iraono Gizeraeli; ba niha fefu, ba labunu, lahori, samösa lö la''orifi.', '["MozV 20:13"]', NULL),
  (3474636, 'OT', 'Yosua', 11, 15, 'Si mane niŵa''ö Yehowa khö genoninia Moze, si manö mege niŵa''ö Moze khö Yosua; da''ö ifatörö Yosua; ma''ifu lö''ö si lö i''o''ö niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 16, 'Ba ihalö khönia danö andrö, ma''afefu, sohili andrö ba tanö raya, ma''afefu, ba tanö Gosena, ma''asagörö, ba daso andrö ba salo''ö ba hili Ndraono Gizeraeli andrö ba daso si faböbö ba da''ö,', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 17, 'i''otarai hili andrö si lö eu-eu, sanösö, mafi ba Ze''ira, irugi Mba''ali Gado ba ndraso ba gahe hili Libano, ba gahe hili Heremono; ba dozi razora, ba möi ba dangania, ba te''ala ibe''e, ibunu.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 18, 'Ba ara i''anuwö''ö razo andrö fefu Yosua.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 19, 'Ba sambua lö banua sangalulu ba Ndraono Gizeraeli, ha Dawa Hewi andrö, banua Gibeona; oi ba wanuwö möi khöra.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 20, 'Moroi khö Yehowa sa, wa abe''e dödöra, ba wasöndrata ba Ndraono Gizeraeli, ena''ö tola lafakiko ira, lö fa''ahakhö dödö, ena''ö tola lahori, si mane niŵa''ö Yehowa khö Moze.', '[]', NULL),
  (3474636, 'OT', 'Yosua', 11, 21, 'Ba me luo da''ö, ba maoso Yosua, ba wangohori Iraono Genaki andrö ba hili, ba Heberona ba ba Debira ba ba Ganaba, ba hili Ndraono Yuda andrö ba ba hili Ndraono Gizeraeli, ma''afefu; ba ifakiko ira, fabaya banua khöra.[2]', '["MozIV 13:23","SamI 17:4"]', NULL),
  (3474636, 'OT', 'Yosua', 11, 22, 'Lö nisaigö Iraono Genaki, ba danö Ndraono Gizeraeli, ha ba Gasa ba ba Gata ba ba Gasoto so zi tosai.[3]', '["MozIV 13:23","SamI 17:4"]', NULL),
  (3474636, 'OT', 'Yosua', 11, 23, 'Ba ihalö khönia danö ma''afefu Yosua, itörö sibai niŵa''ö Yehowa khö Moze, ba ibe''e tana khö ba Ndraono Gizeraeli, dali wabaliŵara ba madora. Ba lö''ö sa''ae fanuwö ba danö, ahono.', '["MozIV 13:23","SamI 17:4"]', NULL),
  (3474637, 'OT', 'Yosua', 12, 1, 'Ba da''e döi razo ba danö, nisuwö Ndraono Gizeraeli ba nihalöra tanö, yefo Yoridano, tanö ba gatumbukha luo, i''otarai mboto Garono, irugi hili Heremono ba he salo''o tanö fefu, tanö ba gatumbukha luo:', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 2, 'Sihona, razo Ndraono Gamori, banua Hesibona, si so barö mbawa tanö andrö, i''otarai Naroeri andrö ba mbewe Garono ba talu ndraso andrö ba si matonga Gileadi, irugi mboto Yaboko, ola Ndraono Gamori,[1]', '["MozIV 21:24","MozV 3:11"]', NULL),
  (3474637, 'OT', 'Yosua', 12, 3, 'ba salo''o andrö, irugi mbaŵa Kineroti, tanö ba gatumbukha, ba irugi zilua''asi ba zalo''o, silua''asi nasio, tanö ba gatumbukha, tanö ba Mbeti Yesimoti ba tanö raya, ba gahe hili Wisiga.', '["MozIV 21:24","MozV 3:11"]', NULL),
  (3474637, 'OT', 'Yosua', 12, 4, 'Ba tanö Ogi andrö, razo Mbazana, si tosai sebua niha andrö, banua Gasaroti ba Ederai[2]', '["MozIV 21:24","MozV 3:11"]', NULL),
  (3474637, 'OT', 'Yosua', 12, 5, 'si so barö mbawa hili Heremono ba Selekha ba tanö Mbazana ma''afefu, irege nola Ndrawa Gesuri ba ola Ndrawa Ma''akhati ba si matonga Gileadi, irugi nola khö Zihona andrö, razo Hesibona.', '["MozIV 21:24","MozV 3:11"]', NULL),
  (3474637, 'OT', 'Yosua', 12, 6, 'ba Moze andrö, enoni Lowalangi, zame''e tanö andrö tana ba mado Rubeno ba ba mado Gado ba ba zi matonga mado Manase.[3]', '["MozV 3:12"]', NULL),
  (3474637, 'OT', 'Yosua', 12, 7, 'Ba da''e döi razo nilaŵa Yosua ba Iraono Gizeraeli ba danö ba zi tambai Yoridano, tanö ba gaekhula luo, i''otarai Mba''ali Gado ba ndraso, ba gahe hili Libano, irugi hili andrö si lö eu-eu, so''anösöla ba Ze''ira, nibe''e Yosua tana ba mado Ndraono Gizeraeli, dali wabaliŵara,', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 8, 'ba hili ba ba ndraso ba ba salo''o ba ba zanaere ba ba danö si mate ba tanö raya:', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 9, 'Samösa razo Yerikho ba samösa razo Ga''i, ba ngai Mbetieli.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 10, 'Ba samösa razo Yeruzalema ba samösa razo Heberona.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474637, 'OT', 'Yosua', 12, 11, 'Ba samösa razo Yaramuti ba samösa razo Lakhisi.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 12, 'Ba samösa razo Negelona ba samösa razo Gezeri.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 13, 'Ba samösa razo Debira ba samösa razo Gederi.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 14, 'Ba samösa razo Horama ba samösa razo Garadi.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 15, 'Ba samösa razo Libena ba samösa razo Gadula.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 16, 'Ba samösa razo Makeda ba samösa razo Mbetieli.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 17, 'Ba samösa razo Dafua ba samösa razo Heferi.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 18, 'Ba samösa razo Gafeka ba samösa razo Lasaro.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 19, 'Ba samösa razo Madona ba samösa razo Hasora.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 20, 'Ba samösa razo Zimerono Merono ba samösa razo Nakhizafi.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 21, 'Ba samösa razo Da''anakhi ba samösa razo Megido.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 22, 'Ba samösa razo Gedesi ba samösa razo Yokenea, ba gahe hili Garemeli.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 23, 'Ba samösa razo Dora, banua Nafoti Dora, ba samösa razo niha baero andrö, ba Giligala.', '[]', NULL),
  (3474637, 'OT', 'Yosua', 12, 24, 'Ba samöza razo Diresa.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 1, 'Ba me no atua Yosua, me no numalö ndröfi khönia, ba imane Yehowa khönia:', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 2, 'Ba da''ö danö si tosai na, si lö muhalö: Tanö Ndrawa Wilisiti ma''afefu ba tanö Gesuri ma''asagörö.[1]', '["SamI 27:8","Faigi 11:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 3, 'I''otarai Zihora andrö, ola danö Miserayi, tanö ba gatumbukha luo, irugi nola Nekerona andrö, tanö yöu, ba tanö Ndrawa Gana''ana labe''e: salaŵa Wilisiti andrö si dalima, salaŵa Gasa ba salaŵa Gasoto ba salaŵa Gasekalo ba salaŵa Gata ba salaŵa Nekerona, awö Ndrawa Gawi andrö, tanö raya.', '["SamI 27:8","Faigi 11:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 4, 'Tanö Ndrawa Gana''ana andrö, ma''asagörö, ba tanö Meara, tanö mbanua Zidona, irugi Gafeka, irugi nola Ndraono Gamori,', '["SamI 27:8","Faigi 11:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 5, 'ba tanö mbanua Gebala andrö, ba hili Libano ma''afefu, tanö ba gatumbukha, i''otarai Mba''ali Gado, ba gahe hili Heremono, irugi tanö ba Hamata.', '["SamI 27:8","Faigi 11:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 6, 'Dozi banua ba hili andrö, i''otarai hili Libano, irugi Misirefo Mayi, fefu mbanua Zidona, ba ya''odo zanimba föna ndraono Gizeraeli; faoso manö ba Ndraono Gizeraeli, lau dahö-dahö, tana khöra si lö tebulö ba nga''ötöra, si mane niŵa''ögu khöu.[2]', '["SamI 27:8","Faigi 11:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 7, 'Ba fosasi sa''ae danö andrö, tana khö, ba mado andrö si siŵa ba ba zi matonga mado Manase.', '["SamI 27:8","Faigi 11:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 8, 'Awö da''ö [awö zi matonga] latema mege dana khöra mado Rubeno ba mado Gado, me ifakhoi khöra Moze, yefo Yoridano, tanö ba gatumbukha, itörö nibe''e Moze, enoni Yehowa andrö, khöra.[3]', '["MozIV 32:33","MozV 3:11","MozIV 18:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 9, 'I''otarai Garoeri andrö, ba mbewe Garono, mbanua andrö ba dalu ndraso, awö zalo''o andrö ma''afefu — Medeba ba Dibona —', '["MozIV 32:33","MozV 3:11","MozIV 18:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 10, 'awö fefu mbanua Zihona andrö, razo Ndraono Gamori, ba Hesibona, irugi nola Ndraono Gamoni,', '["MozIV 32:33","MozV 3:11","MozIV 18:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 11, 'ba Gileadi, awö danö Gesuri andrö ba tanö Ma''akhati, ba he hili Heremono, ma''afefu, ba tanö Mbazana ma''afefu,', '["MozIV 32:33","MozV 3:11","MozIV 18:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 12, 'irugi Zalekha, tanö Ogi andrö, razo Mbazana, ba Gasaroti ba ba Gederai. Si tosai sebua niha andrö da''ö, nilaŵa Moze ba nitimbania.[4]', '["MozIV 32:33","MozV 3:11","MozIV 18:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 13, 'Ba banua Gesuri andrö ba banua Ma''akhati, ba lö latimba Iraono Gizeraeli, ba lö tebulö ba Ndraono Gizeraeli mbanua Gesuri, ba banua Ma''akhati ösa, irugi ma''ökhö andre.', '["MozIV 32:33","MozV 3:11","MozIV 18:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 14, 'Ha ba mado Lewi lö ibe''e dana khö; Yehowa, Lowalangi Ndraono Gizeraeli, dana khöra, si mane nifabu''unia khöra.[5]', '["MozIV 32:33","MozV 3:11","MozIV 18:8"]', NULL),
  (3474638, 'OT', 'Yosua', 13, 15, 'Ba no ibe''e ba mado Rubeno Moze, i''ohia''ö wabaliŵara.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 16, 'Ba tana khöra i''otarai Garoeri andrö, ba mbewe Garono, mbanua andrö ba dalu ndraso ba salo''o andrö fefu ba ngai Medeba.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 17, 'Hesibona ba banua si raböbö khöra, ba salo''o tanö andrö, Dibona ba Bamoti Mba''ali ba Beti Mba''ali Meono,', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 18, 'ba Yasa ba Kedemoti ba Mefa''ata,', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 19, 'ba Kiriata''i ba Sibema ba Sereti Sahara, ba hili ba ba ndraso.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 20, 'Ba Beti Weoro ba sanaere hili Wisiga ba Beti Yezimoti,', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 21, 'awö fefu mbanua ba salo''o ba he ma''asagörö danö Zihona andrö, razo Ndraono Gamori, ba Hesibona, nisuŵo Moze no, fabaya salaŵa Ndraono Midiano andrö: Ewi ba Rekema ba Suri ba Huri ba Reba, awö Zihona andrö, ba danö.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 22, 'Ba he si faeta andrö, Bileamo, ono Mbeori, ba labunu Iraono Gizeraeli si''öli, awö danö bö''ö andrö nibunura.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 23, 'Ba ola mado Rubeno zui, ba Yoridano, bewenia andrö. Da''ö dana ba wabaliŵa mado Rubeno andrö, banua andrö, awö halama soya khöra.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 24, 'Ba no ibe''e ba mado Gado Moze i''ohia''ö wabaliŵara;', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 25, 'ba tana khöra, ba Ya''ezeri, awö mbanua Gileadi fefu ba matonga danö Ndraono Gamoni, irugi Garoeri andrö, tanö ba gatumbukha, i''otarai Raba.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 26, 'Ba i''otarai Hesibona, irugi Ramata Misefe ba Betoni, ba i''otarai Mahana''i, irugi nola Debira.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 27, 'Ba ba ndraso, ba Beti Harama ba Beti Nimera ba Sukhota ba Safona, si tosai banua Zihona andrö, razo Hesibona, ola Yoridano, irugi mbalö mbaŵa Kineroti, yefo Yoridano, tanö ba gatumbukha.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 28, 'Da''ö dana ba mado Gado, balazi wabaliŵara, banua andrö, awö halama soya khöra.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 29, 'Ba no ibe''e ba zi matonga mado Manase Moze, ba da''e dana ba zi matonga mado Manase andrö, balazi wabaliŵara:', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 30, 'Tanöra andrö, ba i''otarai Mahana''i ba te''u''u danö Mbazana ma''afefu, tanö Ogi andrö, razo Mbazana, ma''asagörö, awö fefu zi fahalama andrö khö Ya''iro, ba Mbazana, önö ngafulu banua.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 31, 'Ba si matonga danö Gileadi ba Asaroti ba Ederai, banua sebua andrö ba danö Ogi ba Mbazana. Da''ö zi möi ba Ndraono Makhiro andrö, ono Manase, ba wabaliŵa zi matonga Ndraono Makhiro.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 32, 'Da''ö danö nifaosa Moze, ba zalo''o tanö Moabi, yefo Yoridano, tanö ba gatumbakha, ba gamaudu Yerikho.', '[]', NULL),
  (3474638, 'OT', 'Yosua', 13, 33, 'Ba ba mado lewi, ba lö ibe''e Moze dana khöra tanö; Yehowa, Lowalangi ndraono Gizeraeli, dana khöra, si mane nifabu''unia khöra.', '[]', NULL),
  (3474639, 'OT', 'Yosua', 14, 1, 'Da''ö nitema Ndraono Gizeraeli tana khöra, ba danö Gana''ana, nifaosa Geleazari ere andrö ba Yosua, ono Nuni, ba satua zalaŵa mado Ndraono Gizeraeli khöra.', '["MozIV 26:55","MozIV 35:2"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 2, 'Me lafaosa khöra, me fadahö-dahö, si mane niŵa''ö Yehowa, nifa''ema Moze, ba wame''e ba madora andrö si siŵa a matonga.[1]', '["MozIV 26:55","MozIV 35:2"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 3, 'Ba ba zi dombua a matonga mado andrö, ba noa sa''ae ibe''e Moze dana khöra, yefo Yoridano. Ba ba mado Lewi, ba lö ibe''e dana khöra tanö, ba ngaira.', '["MozIV 26:55","MozIV 35:2"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 4, 'Me no dombua mado Ndraono Yosefo, Manase ba Eferayi. Andrö lö labe''e ba mado Lewi dana khö ba danö, ha banua, nahiara, ba benua, ba nikubaloi urifö, ba gama-gamara.[2]', '["MozIV 26:55","MozIV 35:2"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 5, 'Si mane niŵa''ö Moze, si manö lafatörö Iraono Gizeraeli, ba lafaosa danö.', '["MozIV 26:55","MozIV 35:2"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 6, 'Ba la''ondrasi Yosua ba Giligala, Iraono Yuda ba imane khönia Kalebi andrö, ono Yefune, ma''uwu Genasi andrö: Ö''ila niŵa''ö Yehowa khö Moze, enoni Lowalangi andrö, ba Gadesi Mbarenea, ba khögu andre ba ba khöu.[3]', '["MozIV 14:24","MozIV 13:23"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 7, 'Öfa wulu fakhe ndra''o, me ifatenge ndra''odo Moze, enoni Yehowa andrö, moroi ba Gadesi Mbarenea, ba wamauze tanö, ba u''ombakha''ö khönia zi faduhu dödögu.', '["MozIV 14:24","MozIV 13:23"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 8, 'Ba talifusögu andrö, si möi awögu misi yaŵa, ba atalö dödö mbanuada labe''e, ba ya''odo, ba no u''o''ö sibai khö Lowalangigu, Yehowa.', '["MozIV 14:24","MozIV 13:23"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 9, 'Ba fahölu Moze, me luo da''ö, imane: Si ndruhu-ndruhu, khöu ba khö ma''uwumö danö andrö, nihundragö gaheu, tana khömi, si lö tebulö, irugi zi lö aetu, me no ö''o''ö sibai khö Lowalangiu, Yehowa!', '["MozIV 14:24","MozIV 13:23"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 10, 'Ba faigi iada''e, no i''orifi ndra''odo Yehowa, itörö niŵa''önia, si öfa wulu a lima fakhe andrö, i''otarai me iŵa''ö da''ö khö Moze Yehowa götö wangörö-ngörö Ndraono Gizeraeli ba danö si mate, ba tobali ŵalu ngafulu a lima fakhe ndra''odo iada''e.', '["MozIV 14:24","MozIV 13:23"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 11, 'Ba fa''abölögu na ma''ökhö, ba si mane me luo ifatenge ndra''o Moze; faoma wa''abe''e mbotogu, he me luo da''ö, ba he ma''ökhö andre, ba wasöndrata ena''ö ba ba wofanö-fanö heza möi.', '["MozIV 14:24","MozIV 13:23"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 12, 'Ba iada''e, ba tehe khögu hili andre, nitörö li Yehowa, me luo da''ö; noa sa örongo, me luo da''ö, wa so Ndraono Genaki ba da''ö, si so banua sebua ba saro. Te itolodo Yehowa, ba wanimba ya''ira, si mane niŵa''ö Yehowa.[4]', '["MozIV 14:24","MozIV 13:23"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 13, 'Ba ifahowu''ö ia Yosua ba itehe khö Galebi andrö, ono Yefune, Heberona andrö, tana khönia, si lö tebulö mitou.[5]', '["Sanguhuk 1:20"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 14, 'Ba tobali khö Galebi, ono Yefune, ma''uwu Genasi, Heborona andrö, tana khönia si lö tebulö, irugi ma''ökhö andre, börö me no i''o''ö sibai khö Yehowa, Lowalangi Ndraono Gizeraeli.', '["Sanguhuk 1:20"]', NULL),
  (3474639, 'OT', 'Yosua', 14, 15, 'Ba töi Heberona andrö föna, ba Kiriati Garaba (banua Garaba); fondrege zabölö ba ndraono Genaki Garaba andrö. Ba lö''ö sa''ae fanuwö ba danö, no ahono.', '["Sanguhuk 1:20"]', NULL),
  (3474640, 'OT', 'Yosua', 15, 1, 'Ba tana ba Ndraono Yuda andrö ba wabaliŵara, ba tanö ba nola Ndraono Gedomo, miraya, tanö ba danö si mate Sini andrö, fondrege raya.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 2, 'Ba olara tanö raya ba i''otarai mbalö zilua''asi, sadöni ia andrö miraya.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 3, 'Ba tohu-tohunia irege raya hili Nakerabi, misa ba Zini ba misi yaŵa, miraya, i''otarai Kadesi Mbarenea, ba numalö ba Heserona ba miyaŵa ba Gadara, ba manalinga zi''u ba irugi Garaka,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 4, 'ba numalö misa ba Gasemo ba irugi nidanö Miserayi andrö ba aetu ba mbewe nasi.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 5, 'Da''ö nola tanö raya. Ba ola tanö ba gatumbukha ba silua''asi nasio, irugi luaha Yoridano. Ba ola miyöu, ba i''otarai mbalö zilua''asi, luaha Yoridano andrö.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 6, 'Ba numalö misi yaŵa ba Mbeti Hogela ba misa, irugi yöu Mbeti Garaba ba miyaŵa, irege gowe Mbohani andrö, ma''uwu Rubeno.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 7, 'Ba numalö miyaŵa ba Debira, i''otarai ndraso Akhori andrö, ba isaŵa miyöu Giligala, ba gamaudu hili Gadumi, raya mbombo andrö. Ba numalö ba gumbu luo andrö ba irugi gumbu Rogeli.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 8, 'Ba numalö misi yaŵa ba ndraso khö Mbeni Hinomo, raya hili Ndraono Yebusi, ya''ia Yeruzalema andrö. Ba itohugö miyaŵa, ba zuzu hili andrö, tanö ba gatumbukha na ta''otarai ndraso khö Mbeni Hinomo ba mbalö zalo''o tanö Refa''i, tanö yöu.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 9, 'Ba moroi ba zuzu hili andrö, ba numalö ba gumbu nidanö Nefetoa andrö, ba irugi mbanua andrö ba hili Geferona, ba manaköi ba Mba''ala, ya''ia Kiriati Ye''ari.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 10, 'Ba moroi ba Mba''ala, ba isaŵa gaekhula luo, hili Ze''ira, ba itörö gahe hili Yeari, tanö yöu; ya''ia Gezalo, ba numalö misa ba Mbeti Zemesi ba misa ba Dimena.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 11, 'Ba itohugö miyöu, irege hili Nekerona andrö ba manaköi ba Zikherona, numalö ba hili Mba''ala ba itohugö irege Yabeneli, ba tobali aetu ba mbewe nasi.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 12, 'Ba ola tanö ba gaekhula luo, ba asi sebua, bewenia andrö. Da''ö nola Ndraono Yuda andrö, ba wabaliŵara, fasui.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 13, 'Ba khö Galebi, ono Yefune andrö, ba ibe''e tana khö ba danö Ndraono Yuda andrö, dali niŵa''ö Yehowa khö Yosua, mbanua Garaba andrö, ama Genaki, ya''ia Heberona andrö.', '["MozIV 13:23","Sanguhuk 1:12—15","MozIV 33:12"]', NULL),
  (3474640, 'OT', 'Yosua', 15, 14, 'Ba itimba ba da''ö Kalebi nono Genaki andrö, si datölu, Sezai ba Ahima ba Talamai, nga''ötö Genaki.[1]', '["MozIV 13:23","Sanguhuk 1:12—15","MozIV 33:12"]', NULL),
  (3474640, 'OT', 'Yosua', 15, 15, 'Ba moroi ba da''ö möi ia misi yaŵa, ba wanuwö banua Debira. Ba töi Debira andrö föna, ba Kiriati Zeferi.', '["MozIV 13:23","Sanguhuk 1:12—15","MozIV 33:12"]', NULL),
  (3474640, 'OT', 'Yosua', 15, 16, 'Ba imane Kalebi: Na so zolaŵa Giriati Zeferi, na atu''a ia, ba ube''e khönia nonogu Akhesa.[2]', '["MozIV 13:23","Sanguhuk 1:12—15","MozIV 33:12"]', NULL),
  (3474640, 'OT', 'Yosua', 15, 17, 'Ba atu''a Gotenieli, ono Genasi, akhi Galebi, ba ibe''e dongania nononia Akhesa.[3]', '["MozIV 13:23","Sanguhuk 1:12—15","MozIV 33:12"]', NULL),
  (3474640, 'OT', 'Yosua', 15, 18, 'Ba me tehalö ia, ba ifarou Gotenieli, ba wangandrö benua, sagörö, khö namania. Möi ia tou moroi ba galide; ba imane khönia Kalebi: Hana?', '["MozIV 13:23","Sanguhuk 1:12—15","MozIV 33:12"]', NULL),
  (3474640, 'OT', 'Yosua', 15, 19, 'Ba imane: Be''e khögu howu-howu! Noa sa''ae öbe''e ndra''o miraya, ba öbe''e göi khögu gumbu nidanö! Ba ibe''e khönia gumbu si yaŵa ba umbu si tou.', '["MozIV 13:23","Sanguhuk 1:12—15","MozIV 33:12"]', NULL),
  (3474640, 'OT', 'Yosua', 15, 20, 'Da''ö dana ba Ndraono Yuda andrö, ba wabaliŵara.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 21, 'Ba banua ba mbalö danö Ndraono Yuda andrö, ba nola Ndraono Gedomo, tanö raya, ba da''e döi: Kabize''eli ba Ederi ba Yagura,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 22, 'ba Kina ba Dimona ba Adada,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 23, 'ba Kedesi ba Hasora ba Yitenani,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 24, 'ba Sifi ba Telemi ba Bealoti,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 25, 'ba Hasara Hadata ba Kerioti Heserona, ya''ia Hasora,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 26, 'ba Amana ba Sema ba Molada,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 27, 'ba Hasara Gada ba Hesimona ba Beti Feleti,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 28, 'ba Hasara Suali ba Beri Seba ba Bisiotia,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 29, 'ba Ba''ala ba Iyima ba Esema,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 30, 'ba Eletoladi ba Kesila ba Horama,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 31, 'ba Sikelagi ba Madimana ba Sanasana,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 32, 'ba Lebaoti ba Silihima ba A''ina ba Rimona — dua wulu a siŵa banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 33, 'Ba ba ndraso, ba Esa''ola ba Sorea ba Asena,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 34, 'ba Sanoa ba Eni Gani ba Tafua ba Enamo,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 35, 'ba Yaramuti ba Adula ba Sokho ba Aseka,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 36, 'ba Sa''ara''i ba Adita''i ba Gedera ba Gederota''i — feleöfa banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 37, 'Ba Senana ba Hadasa ba Migidala Gado.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 38, 'Ba Dileano ba Misefe ba Yokite''eli,', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474640, 'OT', 'Yosua', 15, 39, 'ba Lakhisi ba Bosakati ba Egelona,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 40, 'ba Kabona ba Lamasi ba Kiteli,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 41, 'ba Gederoti ba Beti Dagono ba Na''ama ba Makeda, — feleönö banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 42, 'Ba Libena ba Eteri ba Asana,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 43, 'ba Yifita ba Asena ba Nesibi,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 44, 'ba Kegila ba Akhisibi ba Maresa, — siŵa banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 45, 'Ba Ekerona, awö zi faböbö ba da''ö ba si fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 46, 'Fefu, i''otarai Nekerona, numalö ba mbewe nasi, ba ngai Gasoto, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 47, 'Ba Asoto andrö ba si faböbö khöra ba si fahalama, ba Gasa, awö zi faböbö khöra, awö zi fahalama, irugi nidanö Miserayi andrö; ba ola nasi sebua andrö, bewenia.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 48, 'Ba ba zohili, ba Samiri ba Yatiri ba Sokho,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 49, 'ba Dana ba Kiriati Sana, ya''ia Debira andrö,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 50, 'ba Anaba ba Esihemo ba Anima,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 51, 'ba Gosena ba Holono ba Gilo — felezara banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 52, 'Ba Araba ba Duma ba Eseano,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 53, 'ba yanuma ba Beti Tafua, ba Afeka,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 54, 'ba Humeta ba Kiriati Garaba, ya''ia Heberona andrö, ba Siora — siŵa banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 55, 'Ba Ma''ona ba Karemeli ba Sifi ba Yuta,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 56, 'ba Yezere''eli ba Yokedea ba Sanoa,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 57, 'ba Ka''ino ba Gibea ba Timena —fulu banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 58, 'Ba Halihula ba Betisuri ba Gedoro,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 59, 'ba Ma''arata ba Beti Anota ba Eleteko, — önö banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 60, 'Ba Kiriati Mba''ali, ya''ia Giriati Yeari, ba Raba — dombua banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 61, 'Ba ba danö si mate, ba Beti Garaba ba Midini ba Sekhakha,', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 62, 'ba Nibesana ba Iri Hamelakhi ba Engedi, — önö banua, awö zi fahalama khöra.', '[]', NULL),
  (3474640, 'OT', 'Yosua', 15, 63, 'Ba Iraono Yebusi andrö, banua, Yeruzalema, ba tebai latimba Iraono Yuda, ba tobali orudu ba Ndraono Yuda Ndraono Yebusi andrö ba Yeruzalema, irugi ma''ökhö andre.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 1, 'Ba latema dana khöra Iraono Yosefo, i''otarai Yoridano ba gamaudu Yerikho, tanö ba gatumbukha, i''otarai nidanö andrö ba Yerikho, tanö si mate andrö miyaŵa, i''otarai Yerikho, numalö ba hili Mbetieli andrö.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 2, 'Ba i''otarai Mbetieli [ola andrö] isaŵa Lusi ba misa ba danö Gareki, ba Gataroti.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 3, 'Ba isaŵa mitou ba gaekhula luo, ba danö Ndraono Yefeleti, irugi danö Mbeti Horona tou ba irege Geseri ba aetu ba mbewe nasi.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 4, 'Da''ö nitema Ndraono Yosefo andrö, Manase ba Eferayi, tana khöra ba ndraono mitou.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 5, 'Ba da''e nola Ndraono Geferayi, ba wabaliŵara: Ola danöra tanö ba gatumbukha, ba Ateroti Adara, ba numalö ba Mbeti Horona yaŵa, ba itohugö irugi mbewe nasi.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 6, 'Ba ola tanö yöu, ba Mikhemeta ba isaŵa tanö ba gatumbukha ba Da''anata Silo ba itörö zinga da''ö, tanö ba gatumbukha, i''otarai Yanoha.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 7, 'Ba i''otarai Yanoha, ba numalö mitou ba Gataroti ba ba Na''arata ba faola ba danö Yerikho andrö ba aetu ba mbewe Yoridano.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 8, 'Ba i''otarai Dafua, ba ituturu gaekhula luo, numalö ba mbombo Kana ba aetu ba mbewe nasi. Da''ö dana ba Ndraono Geferayi, ba wabaliŵara, si lö tebulö ba Ndraono mitou.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 9, 'Ba banua andrö, ni''oniagö banua Ndraono Geferayi ba danö Ndraono Manase, banua andrö fefu, awö zi fahalama khöra.', '[]', NULL),
  (3474641, 'OT', 'Yosua', 16, 10, 'Ba lö latimba Ndrawa Gana''ana ba Geseri. Ba tobali orudu ba Ndraono Geferayi Ndrawa Gana''ana, irugi ma''ökhö andre, ba tobali sangai halöŵö khöra.', '[]', NULL),
  (3474642, 'OT', 'Yosua', 17, 1, 'Ba latema dana khöra mado Manase, me no si a''a ndraono Yosefo Manase andrö. Tana khö Makhiro, si a''a ndraono Manase, ama Gileadi, ba tanö Gileadi ba tanö Mbazana, me no sabölö ba wanuwö ia.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 2, 'Ba dozi ma''uwu Manase, si tosai, ba latema dana khöra, balazi wabaliŵara: ma''uwu Gabiezeri ba ma''uwu Heleki ba ma''uwu Gazerieli ba ma''uwu Zekhema ba ma''uwu Heferi ba ma''uwu Zemida. Da''ö ndra matua, ma''uwu Manase, ono Yosefo, ba wabaliŵara.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 3, 'Ba khö Zelofadi, ono Heferi ono Gileadi ono Makhiro ono Manase, ba lö ono matua, ha ono alawe; ba da''e döi nononia alawe: Mala ba Noa ba Hogela ba Milika ba Tirisa.[1]', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 4, 'Ba möi ira khö Geleazari ere andrö ba khö Yosua, ono Nuni, ba ba zalaŵa andrö, lamane: No iŵa''ö Yehowa, labe''e dana khöma göi, ba ngai ndra talifusöma. Ba ibe''e khöra, dali goroisa Yehowa andrö, dana khöra, ba ngai ndra talifusö namara.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 5, 'Tobali dafulu mo''urakha ba mado Manase, lö lai danö Gileadi ba tanö Mbazana, yefo Yoridano,', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 6, 'me latema göi dana khöra ma''uwu Manase ono alawe, ba ngai mi''uwunia ono matua. Ba tanö Gileadi andrö, ba tana ba zi tosai ma''uwu Manase.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 7, 'Ba ola danö mado Manase, ba i''otarai danö Mado Gaseri, numalö ba Mikhimeta, tanö ba gatumbukha i''otarai Zikhema. Ba isaŵa gambölö ba mbanua Neni Dafua.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 8, 'Tanö Dafua andrö, ba ba mado Manase ba banua Dafua, ba nola Manase, ba ba mado Geferayi.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 9, 'Ba itohugö mitou ola, ba mbombo Kana, bewe nidanö tanö raya; banua da''ö, ba gotalua mbanua mado Manase, ba tana ba mado Geferayi. Ba i''ötö nidanö ola mado Manase, ihene mbewenia tanö yöu ba aetu ba mbewe nasi.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 10, 'Tanö raya, ba ba mado Geferayi, ba tanö yöu, ba ba mado Manase, ba ola mbewe nasi. Ba tanö yöu, ba faola ba mado Gaseri, ba tanö ba gatumbukha, ba ba mado Isasari.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 11, 'Ba ba danö mado Isasari ba ba danö mado Gaseri, ba banua Manase na Mbeti Zeana ba si fahalama khöra, ba Yibelea ba si fahalama khöra ba banua Dora ba si fahalama khöra ba banua Neni Dora ba si fahalama khöra ba banua Da''anakhi ba si fahalama khöra, ba si tölu hili banua Megido ba si fahalama khöra andrö.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 12, 'Ba tebai latimba mbanua da''ö no mege mado Manase, ba tobali falukha Ndrawa Gana''ana lö tebulö ira ba danö da''ö.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 13, 'Ba me itugu abölö Ndraono Gizeraeli, ba labe''e sangai halöŵöra Ndrawa Gana''ana andrö: ba lö alua latimba.', '["MozIV 27:1 b.t."]', NULL),
  (3474642, 'OT', 'Yosua', 17, 14, 'Ba humede Ndraono Yosefo andrö khö Yosua, lamane: Hana wa ha sambua mado motanö, ha sambua mado mo''urakha öbe''e khöma, ba no ato ndra''aga, me no ifahowu''ö ndra''aga Yehowa, irugi ma''ökhö andre?', '[]', NULL),
  (3474642, 'OT', 'Yosua', 17, 15, 'Ba imane khöra Yosua: Na no ato ami, ba mi''ae miyaŵa ba hili ba zatua eu, molahoi khömi ba da''ö, ba danö Ndraono Weresi ba ba danö Ndrawa Refa''i, na ambö tanö khömi ba hili mado Geferayi!', '[]', NULL),
  (3474642, 'OT', 'Yosua', 17, 16, 'Ba lamane Iraono Yosefo: Ambö tanöma hili andrö, ba no mokureta si''öli Ndrawa Gana''ana andrö fefu, ba ndraso andrö ba banua Mbeti Zeana, awö zi fahalama khöra ba ba ndraso Yezere''eli andrö.', '[]', NULL),
  (3474642, 'OT', 'Yosua', 17, 17, 'Ba imane Yosua ba ma''uwu Yosefo andrö, mado Geferayi, ba ba mado Manase: Ato ami ba sabölö, böi ha sambua mado motanö khömi;', '[]', NULL),
  (3474642, 'OT', 'Yosua', 17, 18, 'labe''e khömi zambua hili: na no satua eu, ba mi''obö, ba khömi göi zi faola ba da''ö. Mitimba sa''ae Ndrawa Gana''ana andrö, me no mokureta si''öli ira ba me no sabölö.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 1, 'Ba owulo mbanua Ndraono Gizeraeli fefu, ba Zilo. Ba da''ö lafa''anö nose gamabu''ula li andrö, me no möi barö mbawara danö.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 2, 'Ba fitu mado zi tosai Iraono Gizeraeli, ba zi lö mufaosa tanö na.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 3, 'Ba imane Yosua ba Ndraono Gizeraeli: Ha wa''ara arörö manö ami, wa lö möi ami, ba wangai khömi tanö andrö, nibe''e Yehowa, Lowalangi ndra tuami, khömi?', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 4, 'Mi''ohe khögu niha, datölu zambua mado, ba da''ufatenge ira, ena''ö möi ira manöröi tanö, ena''ö labe''e ba zura he ndrege dana khöra, ba mangawuli ira khögu.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 5, 'Ba ndramu''ofitu, wamaosa khöra. Ba mado Yuda dana khöra raya ba ba mado Yosefo dana khöra yöu, lö tebulö.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 6, 'Ba ya''ami, na no mi''ofitu, ba mibe''e ba zura ba mi''ohe khögu ba da''e, ena''ö ulau dahö-dahö khömi ba da''e, föna Lowalangida Yehowa.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 7, 'Ba mado Lewi sa, ba lö tana khöra tanö ba ngaimi; fa''a''ere andrö khö Yehowa dana khöra. Ba mado Gado andrö ba mado Rubeno ba si matonga mado Manase, ba no latema dana khöra yefo Yoridano, tanö ba gatumbukha, nihonogöi genoni Yehowa andrö, Moze, khöra.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 8, 'Ba maoso ira, mofanö.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 9, 'Ba mofanö ira, latöröi danö, la''ofitu wame''e ba zura, lafaigi mbanua, ba lafuli ira khö Yosua ba golombaseŵa ba Zilo.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 10, 'Ba ilau dahö-dahö khöra Yosua, föna Yehowa ba Zilo, ifaosa ba da''ö danö ba Ndraono Gizeraeli, dali wabaliŵara.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 11, 'Ba alua dahö-dahö ba mado Mbeniyami, ba wabaliŵara, ba tana khöra ba gotaluara mado Yuda mado Yosefo andrö.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 12, 'Ba olara tanö yöu, ba i''otarai Yoridano, ba numalö miyaŵa ba mboto hili, yöu Yerikho, ba itohugö miyaŵa ba hili andrö, tanö ba gaekhula, ba numalö ba danö si mate andrö, ba Mbeti Awena.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 13, 'Ba i''otarai da''ö, ba numalö ba Lusi, ihene danö raya mboto hili Lusi andrö, ya''ia Mbetieli andrö, ba numalö misi tou ba Gateroti Adara, ba hili andrö, raya Mbeti Horona tou.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 14, 'Ba iköi''ö ia, ituturu misi tou, raya hili andrö, föna-föna Mbeti Horona, tanö raya, ba aetu tanö ba Giriati Mba''ali, ya''ia Giriati Yeari, banua Ndraono Yuda. Da''ö nola tanö ba gaekhula luo.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 15, 'Ba ola tanö raya, ba i''otarai mbalö mbanua Giriati Yeari ba numalö misa, ituturu nasi, ba irugi gumbu nidanö Nefetoa andrö.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 16, 'Ba numalö mitou ba mbalö hili andrö, ba ngai ndraso khö Mbeni Hinomo, tanö ba gatumbukha, yöu ndraso Refa''i. Ba isaŵa mitou ba ndraso khö Hinomo, raya mboto hili Ndrawa Yebusi andrö, ba itohugö mitou ba gumbu Rogeli.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 17, 'Ba iköi''ö ia miyöu, isaŵa Neni Zemesi ba itohugö, irege Gelilota, ba gamaudu hili Gadumi. Ba numalö mitou ba gowe Mbohani andrö, ono Rubeno,', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 18, 'isaŵa mboto hili andrö ba gamaudu Garaba, tanö yöu, ba mitou ba Garaba.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 19, 'Ba numalö misa, irugi yöu mboto hili Mbeti Hogela ba aetu ba mbalö zilua''asi nasio tanö yöu, ba luaha Yoridano. Da''ö nola tanö raya.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 20, 'Ba tanö ba gatumbukha, ba Yoridano nola. Da''ö nola dana ba mado Mbeniyami, ba wabaliŵara.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 21, 'Ba töi mbanua mado Mbeniyami, ba Yerikho ba Beti Hogela ba Emeki Kesisi,', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 22, 'ba Beti Garaba ba Semara''i ba Betieli,', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 23, 'ba Awimi ba Hafara ba Ofera,', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 24, 'ba Kefara Amoni ba Ofeni ba Geba — felendrua banua, awö zi fahalama khöra.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 25, 'Ba Gibeona ba Rama ba Be''eroti', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 26, 'ba Misefe ba Kefira ba Mosa.', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 27, 'Ba Rekema ba Yirife''eli ba Tarala,', '[]', NULL),
  (3474643, 'OT', 'Yosua', 18, 28, 'ba Sela ba Elefi ba banua ndraono Yebusi andrö, ya''ia Yeruzalema, ba Gibeati ba Kiriati — feleöfa banua, awö zi fahalama khöra. Da''ö dana ba mado Mbeniyami ba wabaliŵara.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 1, 'Ba dahö-dahö fanete si föföna andrö, ba tana ba mado Zimeoni, ba wabaliŵa Ndraono Zimeoni andrö. Ba tana khöra, ba te''u''u ba dana ba mado Yuda.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 2, 'Tana khöra Mbereseba ba Saba ba Molada;', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 3, 'ba Hasara Zuala ba Bala ba Esema', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 4, 'ba Eli Dolada ba Betuli ba Horama,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 5, 'ba Sikelagi, ba Beti Marakobo ba Hasara Zusa,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 6, 'ba Beti Leba''oti ba Saruhe — feledölu banua, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 7, 'Ba Eni Rimono ba Eteri ba Asana — öfa banua, awö zi fahalama khöra;', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 8, 'fabaya banua side-ide fefu, si tefasui banua sebua andrö no mege, irugi Mba''alati Mbe''eri ya''ia Rama raya. Da''ö dana ba mado Zimeoni ba wabaliŵara.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 9, 'Ba no ba dana ba mado Yuda lahalö dana ba mado Zimeoni. Me no töra wa''ebolo ba mado Yuda, andrö wa labe''e ba Ndraono Zimeoni ösa khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 10, 'Ba dahö-dahö si tölu, ba tana ba mado Zebuloni, ba wabaliŵara, ba irugi ba Zaridi dana khöra andrö.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 11, 'Ba tanö ba gaekhula, ba numalö miyaŵa nolara, ba Marela, itörö zinga Dabeseti ba bewe mbombo andrö, ba ngai Yokenea tanö ba gatumbukha.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 12, 'Ba tanö ba gatumbukha luo, ba ituturu danö Gisiloti Dabora, i''otarai Zarida, ba itohugö ba Daberata ba miyaŵa ba Yafia.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 13, 'Ba i''otarai da''ö, ba isaŵa ba gatumbukha luo Gata Heferi ba Eti Gasimi ba itohugö ba Rimona ba iköi''ö ia ba Nea.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 14, 'Ba ifasui da''ö miyöu, ba Hanato, ba aetu ba ndraso Yefita Eli.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 15, 'Katata ba Nahala ba Simerono ba Yidala ba Betilekhema, — felendrua banua, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 16, 'Da''ö dana ba mado Zebuloni ba wabaliŵara: banua no mege, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 17, 'Ba dahö-dahö si öfa, ba tana ba mado Isasari, ba wabaliŵara.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 18, 'Tana khöra Yezere''eli ba Kesuloti ba Sunema,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 19, 'ba Hafara''i ba Siona ba Anaharata', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474644, 'OT', 'Yosua', 19, 20, 'ba Rabiti ba Kisiona ba Ebesi,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 21, 'ba Remeti ba Eni Gani ba Eni Hada ba Beti Wasesi,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 22, 'ba ihene Dabora ola andrö ba Sahasima ba Beti Zemesi ba aetu ba Yoridano — feleönö banua, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 23, 'Da''ö dana ba mado Isasari, ba wabaliŵara: banua andrö, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 24, 'Ba dahö-dahö si lima, ba tana ba mado Gaseri, ba wabaliŵara.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 25, 'Khöra Helikata ba Hali ba Beteni ba Akhisafi,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 26, 'ba Alamelekhi ba Ameada ba Miseala, ba irugi hili Garemeli, tanö ba mbewe nasi, ba Sihora Libenati.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 27, 'Ba isaŵa tanö ba gatumbukha Mbeti Dagono ola andrö, ihene danö mado Zebuloni ba daso Yefita Eli, yöu, ba Beti Emeki ba Negieli ba itohugö miyöu ba Gabula,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 28, 'ba ba Geberono ba ba Rehobo ba ba Gamoni ba ba Kana ba irugi mbanua sebua andrö, Sidona.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 29, 'Ba ifuli furi ba Rama, ba irugi mbanua saro andrö, Tiro; ba isaŵa Hosi, ba aetu ba mbewe nasi, tanö ba Nakhisibi.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 30, 'Ba Ako ba Afeki ba Rehobo — dua wulu a rua banua, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 31, 'Da''ö dana ba mado Gaseri, ba wabaliŵara: banua no mege, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 32, 'Ba dahö-dahö si önö, ba tana ba mado Nafetali, ba wabaliŵara.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 33, 'Ba olara, ba i''otarai Helefi, manawa andrö ba zinga Za''anani, ba Adami Nekebi ba Yabine''eli, ba irugi Lakuma ba aetu ba Yoridano.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 34, 'Ba isaŵa misi tou Gasinoti Dabora, ba itohugö ba Hukoko, ihene raya danö mado Zebuloni ba tanö mado Gaseri, tanö ba gaekhula; Yoridano tanö ba gatumbukha.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 35, 'Ba banua saro Zidimi ba Seri ba Hamata ba Rakata ba Kinereti,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 36, 'ba Adama ba Rama ba Hasora,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 37, 'ba Kedesi ba Ederai ba Eni Hasora,', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 38, 'ba Yireono ba Migedali Eli ba Horema ba Beti Ganata ba Beti Zemesi — sambua ambö dua wulu banua, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 39, 'Da''ö dana ba mado Nafetali, ba wabaliŵara: banua andrö, awö zi fahalama khöra.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 40, 'Ba tana ba mado Dano ba wabaliŵara, ba dahö-dahö si fitu.', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 41, 'Ba tana khöra, ba Sorea ba Esa''ola ba Iri Zemesi,', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 42, 'ba Sa''alabi ba Ayalona ba Yitela,', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 43, 'ba Elono ba Timenata ba Ekerona,', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 44, 'ba Eliteke ba Gibetona ba Ba''alata,', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 45, 'ba Yehudi ba Bene Mbaraki ba Gata Rimona, ba Me Yarako ba Rakona,', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 46, 'fabaya tanö tanö ba Yafo.', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 47, 'Ba tetimba mado Dano andrö, lahalö danöra niha bö''ö. Ba maoso mado Dano, lasuwö Lasema lalaŵa bawa zi''öli ba lahalö nahiara mbanua andrö ba labe''e töi Lesema andrö Dano, töi wurugöra Dano andrö.[1]', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 48, 'Da''ö dana ba mado Dano andrö, ba wabaliŵara: banua andrö, awö zi fahalama khöra.', '["Sanguhuk 18:27 b.t."]', NULL),
  (3474644, 'OT', 'Yosua', 19, 49, 'Ba me no awai lafaosa danö ma''asagörö, ba labe''e dana khö Yosua, ono Nuni, Iraono Gizeraeli, ba danöra andrö.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 50, 'La''o''ö niŵa''ö Yehowa, latehe khönia mbanua andrö, ni''andrönia, Timenata Zera, ba hili mado Geferayi. Ba i''aro''ö mbanua andrö ba ibali''ö nahiania.', '[]', NULL),
  (3474644, 'OT', 'Yosua', 19, 51, 'Da''ö dana khöra, nifaosa Geleazari ere andrö ba Yosua, ono Nuni ba satua mado Ndraono Gizeraeli andrö, ba Zilo, föna Yehowa, ba zinga mbawandruhö nose gamabu''ula li, nilau dahö-dahö. Ba tobali awai wamaosa tanö.', '[]', NULL),
  (3474645, 'OT', 'Yosua', 20, 1, 'Ba humede Yehowa khö Yosua, imane:', '["MozII 21:13; MozIV 35:10 b.t."]', NULL),
  (3474645, 'OT', 'Yosua', 20, 2, 'Ömane ba Ndraono Gizeraeli: Mihonogöi mbanua saŵatö andrö, ni''oroi''ögu khö Moze, niŵa''ö khömi:[1]', '["MozII 21:13; MozIV 35:10 b.t."]', NULL),
  (3474645, 'OT', 'Yosua', 20, 3, 'Ena''ö isaŵa da''ö na so zi no mamunu niha si tenga ni''odödögö, si lö mudöna-döna, ena''ö saŵatömi ba zolau balö.', '["MozII 21:13; MozIV 35:10 b.t."]', NULL),
  (3474645, 'OT', 'Yosua', 20, 4, 'Ba sanaŵa banua da''ö, ba yamu''iagö zinga mbawa göli mbanua ba yamu''ombakha''ö ba zatua mbanua andrö huhuonia ba ndramufa''amöi ia yomo khöra, ndramutehe khönia nahia, ba wangiagö da''ö khöra.', '["MozII 21:13; MozIV 35:10 b.t."]', NULL),
  (3474645, 'OT', 'Yosua', 20, 5, 'Ba na igohi ia solau balö, ba lö tola labe''e ba dangania zange''e andrö, me tenga ni''odödögö wamununia awönia, me tenga fatiusa mege mbörö.', '["MozII 21:13; MozIV 35:10 b.t."]', NULL),
  (3474645, 'OT', 'Yosua', 20, 6, 'Ba yamu''iagö mbanua andrö, irege no mu''ohe ia ba walukhata mbanua, ba wangetu''ö hukunia — irege mate gere sebua, ere sebua na luo da''ö. Awena dania tola mangawuli zange''e andrö ba mbanuara ba ba nomonia, ba mbanua ba zi otorai ia mege woloi.', '["MozII 21:13; MozIV 35:10 b.t."]', NULL),
  (3474645, 'OT', 'Yosua', 20, 7, 'Ba la''amoni''ö Gedesi ba Galilaia, ba hili mado Nafetali ba Sikhema ba hili mado Geferayi ba Kiriati Garaba, Heberona andrö, ba hili mado Yuda.', '[]', NULL),
  (3474645, 'OT', 'Yosua', 20, 8, 'Ba yefo Yoridano, ba gamaudu Yerikho, tanö ba gatumbukha, lahonogöi Mbeseri ba danö si mate, ba zalo''o, banua mado Rubeno, ba Ramoti ba danö Gileadi, banua mado Gado, ba Golana, ba danö Mbazana, banua mado Manase.', '[]', NULL),
  (3474645, 'OT', 'Yosua', 20, 9, 'Da''ö mbanua andrö, nihonogöi ba Ndraono Gizeraeli fefu ba ba niha bö''ö, si fatewu gana khöra, ena''ö ba da''ö lasaŵa dozi samunu niha, si lö mu''odödögö, ena''ö lö ibunu ira solau balö, lö mu''ohe ba walukhata mbanua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 1, 'Ba la''ondrasi Geleazari ere andrö ba Yosua, ono Nuni, ba satua mado Ndraono Gizeraeli satua mado Lewi,', '["MozIV 35:2 b.t."]', NULL),
  (3474646, 'OT', 'Yosua', 21, 2, 'lamane khöra ba da''ö ba Zilo ba danö Gana''ana: No iŵa''ö Yehowa, nifa''ema Moze tebe''e khöma mbanua, nahiama, awö mbenua ba ngai, ba nikubaloi uriföma.[1]', '["MozIV 35:2 b.t."]', NULL),
  (3474646, 'OT', 'Yosua', 21, 3, 'Ba labe''e ba mado Lewi Iraono Gizeraeli dana khöra ösa, mbanua andrö, awö mbenua ba ngai, ba nikubaloi uriföra, la''o''ö niŵa''ö Yehowa.[2]', '["Nga''ötI 6:54 b.t."]', NULL),
  (3474646, 'OT', 'Yosua', 21, 4, 'Ba alua dahö-dahö ba nga''ötö Gahati andrö; ba tebe''e ba ndraono Ga''aroni ere andrö, mado Lewi, ba feledölu banua, nilau dahö-dahö; banua mado Yuda ba banua mado Zimeoni ba banua mado Mbeniyami.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 5, 'Ba ba ma''uwu Gahati tanö bö''ö, ba fulu banua, nilau dahö-dahö, banua wabaliŵa mado Geferayi ba banua mado Dano ba banua zi matonga mado Manase.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 6, 'Ba ba ma''uwu Gereso, ba feledölu banua, nilau dahö-dahö, banua wabaliŵa mado Isasari ba banua mado Gaseri ba banua mado Nafetali ba banua zi matonga mado Manase ba Mbazana.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 7, 'Ba ba wabaliŵa ma''uwu Merari, ba felendrua banua, banua mado Rubeno ba banua mado Gado ba banua mado Zebuloni.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 8, 'Ba latehe ba mado Lewi andrö Iraono Gizeraeli mbanua no mege, fabaya benua ba ngai, dali dahö-dahö, la''o''ö ni''oroi''ö Yehowa khö Moze.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 9, 'Ba latehe mbanua mado Yuda andrö ba banua mado Zimeoni andrö, nitötöi töi.', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 10, 'Ba tetehe ba ndraono Ga''aroni, nga''ötö Gahati, ono Lewi, khöra sa dahö-dahö si föföna.', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 11, 'Latehe khöra mbanua Garaba andrö, ama Genoki, ya''ia Heberona, ba hili mado Yuda, awö mbenua si tefasui ya''ia.', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 12, 'Ba naha zinanö ba ngai mbanua, awö halama, si faböbö khönia, ba labe''e khö Galebi, ono Yefune, tana khönia, si lö tebulö.[3]', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 13, 'Ba ba ma''uwu Ga''aroni, ere andrö, ba latehe mbanua saŵatö zange''e andrö, Heberona andrö, fabaya benua ba ngai ba Libena, fabaya benua,', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 14, 'ba Yatiro, fabaya benua ba Esemoa, fabaya benua,', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 15, 'ba Holona, fabaya benua, ba Debira, fabaya benua,', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 16, 'ba Asana, fabaya benua, ba Yuta, fabaya benua, ba Beti Zemesi, fabaya benua — siŵa banua, banua mado no mege, si dombua.', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 17, 'Ba banua mado Mbeniyami: Gibeona, fabaya benua ba ngai, ba Geba, fabaya benua,', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 18, 'ba Anatoti, fabaya benua, ba Alamo, fabaya benua — öfa banua.', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 19, 'Tobali tetehe ba ma''uwu Ga''aroni, ere andrö, ba feledölu banua fefu, fabaya benua ba ngai.', '["Yos 14:14; 15:13"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 20, 'Ba ba wabaliŵa ma''uwu Gahati, mado Lewi, ba zi tosai nga''ötö Gahati, ba si göna ba dahö-dahö khöra, ba banua mado Geferayi.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 21, 'Latehe khöra mbanua saŵatö zange''e andrö, Sikhema, fabaya benua ba ngai, ba hili mado Geferayi ba Geseri, fabaya benua,', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 22, 'ba Kibisa''i, fabaya benua, ba Beti Horona, fabaya benua — öfa banua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 23, 'Ba banua mado Dano: Eliteke, fabaya benua, ba Gibetona, fabaya benua,', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 24, 'ba Ayalona, fabaya benua, ba Gata Rimono, fabaya benua — öfa banua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 25, 'Ba banua zi matonga mado Manase: Ta''anakhe, fabaya benua, ba Yibelea, fabaya benua — dombua banua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 26, 'Tobali tetehe ba wabaliŵa ma''uwu Gahati, si tosai andrö, ba fulu banua fefu, fabaya benua ba ngai.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 27, 'Ba ba ma''uwu Gereso andrö, fabaliŵa mado Lewi, ba dombua tetehe banua zi matonga mado Manase: banua saŵatö zange''e andrö, Golana ba Mbazana, fabaya benua, ba Be''eseri, fabaya benua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 28, 'Ba banua mado Isasari: Kisiona, fabaya benua, ba Daberata, fabaya benua,', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 29, 'ba Yaramuta, fabaya benua, ba Eni Gani, fabaya benua — öfa banua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 30, 'Ba banua mado Gaseri: Mizeali, fabaya benua, ba Abedono, fabaya benua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 31, 'Ba Helikata, fabaya benua ba Rehobo, fabaya banua — öfa banua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 32, 'Ba banua mado Nafetali: banua saŵatö zange''e andrö, Kedesi ba Galilaia, fabaya benua, ba Hamoti Dora, fabaya benua ba Karatana fabaya benua — tölu banua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 33, 'Tobali tetehe ba wabaliŵa ma''uwu Gereso andrö feledölu banua, fabaya benua ba ngai.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 34, 'Ba ba wabaliŵa ma''uwu Merari andrö, si tosai mado Lewi, ba tetehe, banua mado Zebuloni, Yokenea, fabaya benua, ba Karata, fabaya benua,', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 35, 'ba Dimena, fabaya benua, ba Nahalala, fabaya benua — öfa banua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 36, 'Ba banua mado Rubeno: banua saŵatö zange''e andrö, Beseri andrö, ba danö si mate, fabaya benua, ba Yasa, fabaya benua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 37, 'Ba Kedemoti, fabaya benua, ba Mefa''ata, fabaya benua — öfa banua.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 38, 'Ba banua mado Gado: banua saŵatö zange''e andrö, Ramoti ba danö Gileadi, fabaya benua, ba Mahana''i, fabaya benua,', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 39, 'ba Hesibona, fabaya benua, ba Ya''ezeri, fabaya benua — öfa banua fefu.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 40, 'Tobali tetehe ba wabaliŵa ma''uwu Merari andrö, si tosai fabaliŵa mado Lewi, felendrua banua fefu, tana khöra, nilau dahö-dahö.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 41, 'Ba banua mado Lewi andrö, ba no öfa wulu a ŵalu, fabaya benua, si te''u''u ba dana Ndraono Gizeraeli [bö''ö].', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 42, 'Ba banua no mege, ba sambu-sambua banua, fabaya benua, si tefasui ya''ia; dozi banua no mege, ba si manö.', '[]', NULL),
  (3474646, 'OT', 'Yosua', 21, 43, 'Ba ibe''e ba danga Ndraono Gizeraeli danö ma''asagörö Yehowa, si no fahölu ia khö ndra tuara, ba wame''e khöra; ba lahalö khöra ba mowanua ira ba da''ö.', '["Faigi 23:14"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 44, 'Ba tefasui danöra, ba ahono ibe''e Yehowa, itörö nifabu''unia, khö ndra tuara, fahölusa. Lö si lö te''ala khöra emalira; ibe''e ba dangara nemalira fefu Yehowa.', '["Faigi 23:14"]', NULL),
  (3474646, 'OT', 'Yosua', 21, 45, 'Sambua lö aekhu ba danö taroma li si sökhi andrö, niŵa''ö Yehowa ba ma''uwu Gizeraeli; ahori itörö.[4]', '["Faigi 23:14"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 1, 'Me luo da''ö ifakaoni''ö Yosua mado Rubeno ba mado Gado ba si matonga mado Manase,', '["MozIV 32:20 b.t.","MozV 29:9","MozV 10:12"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 2, 'ba imane khöra: No mi''ö''ö fefu niŵa''ö genoni Yehowa andrö, Moze, khömi ba no mifondrondrongo ligu, fefu hadia ia niŵa''ögu khömi.[1]', '["MozIV 32:20 b.t.","MozV 29:9","MozV 10:12"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 3, 'Lö si faröi ami ba dalifusömi, götö wa''ara andrö, irugi ma''ökhö andre, ba no mi''o''ö goroisa Lowalangimi, Yehowa, lö si fahole.[2]', '["MozIV 32:20 b.t.","MozV 29:9","MozV 10:12"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 4, 'Ba no falukha wa''ahono dalifusömi, ibe''e Lowalangimi, Yehowa, itörö nifabu''unia khöra; ba mifuli sa''ae ami khömi, ba danö tana khömi, nitehe genoni Yehowa andrö, Moze, khömi, yefo Yoridano.', '["MozIV 32:20 b.t.","MozV 29:9","MozV 10:12"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 5, 'Ba böi olifu ami, yamoroi si''aikö ba dödömi wolo''ö oroisa andrö nibe''e genoni Yehowa andrö, Moze, khömi ba amakhoitania, fa mi''omasi''ö Lowalangi, Yehowa, fa böi mamalö-malö wanörömi lala andrö khönia, fa mi''o''ö goroisania, fa molemba ami khönia, fa mihorigö dödömi ba era-erami, we''amöi enoninia![3]', '["MozIV 32:20 b.t.","MozV 29:9","MozV 10:12"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 6, 'Ba i''efa''ö ira Yosua, ifahowu''ö ba ifofanö, ba lafuli ira khöra.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 7, 'Ba ba zi matonga mado Manase ba no ituturu Moze danö Mbazana; ba ba zi matonga, ba no ituturu Yosua ba ngai dalifusöra ba zi tambai Yoridano, tanö ba gaekhula.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 8, 'ba lafuli ira khöra; no oya khöra girö-girö, oya sibai gurifö ba firö ba ana''a ba töla ba si''öli ba no fahöna nukha, ba lafaosa, labe''e ba dalifusöra ösa, nihalöra ba nemalira andrö.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 9, 'Tobali lafuli ira mado Rubeno ba mado Gado ba si matonga mado Manase, laröi Ndraono Gizeraeli bö''ö, ba Zilo, ba danö Gana''ana, ba we''amöi ba danö Gileadi, ba danö tana khöra, ba zowanua ira, dali goroisa Yehowa andrö, nifa''ema Moze.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 10, 'Ba me larugi danö ba zinga Yoridano, ba danö Gana''ana, ba lafazökhi naha wame''e sumange, sebua, mado Rubeno ba mado Gado ba si matonga mado Manase, ba da''ö ba mbewe Yoridano.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 11, 'Ba larongo Iraono Gizeraeli bö''ö: Hiza, no lafazökhi naha wame''e sumange mado Rubeno ba mado Gado ba si matonga mado Manase, ba gamaudu danö Gana''ana, ba zinga Yoridano, ba danö ba zi tambai Ndraono Gizeraeli.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 12, 'Ba me larongo da''ö Iraono Gizeraeli, ba falukha mbanuara fefu ba Zilo, ba wanuwö ya''ira.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 13, 'Ba lafatenge zinenge Iraono Gizeraeli, ba we''amöi ba mado Rubeno ba ba mado Gado ba ba zi matonga mado Manase, Fineha andrö,', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 14, 'ono Geleazari ere andrö, awö zalaŵa, dafulu, samösa zambua mado, mado Ndraono Gizeraeli fefu; dozi ira, ba no satua wabaliŵa madora, ba ngahönö Ndraono Gizeraeli andrö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474647, 'OT', 'Yosua', 22, 15, 'Ba me no larugi mado Rubeno ba mado Gado ba si matonga mado Manase, ba danö Gileadi, ba fahuhuo ira khöra, lamane:', '["MozV 12:13 b.t.","MozIV 25:3"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 16, 'Da''ö niŵa''ö mbanua Yehowa fefu khömi: Hadia, wa faröi ami khö Lowalangi Ndraono Gizeraeli, wa mi''erogö Yehowa ma''ökhö, wamazökhi naha wame''e sumange khömi, wa milaŵa Yehowa ma''ökhö?[4]', '["MozV 12:13 b.t.","MozIV 25:3"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 17, 'Hadia, ambö na horöda famosumange Ba''ali Weoro andrö, si lö tebulö ba huluda, irege ma''ökhö andre, börö wa göna famakao mbanua Yehowa?[5]', '["MozV 12:13 b.t.","MozIV 25:3"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 18, 'Ba ya''ami, ba edöna mi''erogö Yehowa ma''ökhö? Ba lö fulitö: ya''ami zolaŵa Yehowa maökhö, ba mahemolu, ba göna fönu mbanua Ndraono Gizeraeli fefu.', '["MozV 12:13 b.t.","MozIV 25:3"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 19, 'Ba na salakha danö andrö, nitemami tana khömi, ba mitabu miyefo ba danö tana khö Yehowa, ba zi so nahia Yehowa, ba mi''iagö ba ngaima. Ba lö tola milaŵa Yehowa, ba he ya''aga, ba lö tola milaŵa, wamazökhi naha wame''e sumange, nifasambua, baero naha wame''e sumange andrö khö Lowalangida, Yehowa.', '["Faigi 7"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 20, 'Hadia, lö si göna fönu mbanua Ndraono Gizeraeli fefu, me no numalö danga Nakhano andrö, ono Zera, me falimo ia, ba zalakha andrö, wa ma''ifu tenga ha ya''ia zi mate ba horönia andrö.[6]', '["Faigi 7"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 21, 'Ba latema lira mado Rubeno ba mado Gado ba si matonga mado Manase, lamane ba zatua ngahöno Ndraono Gizeraeli:', '["Sin 50:1"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 22, 'Sabölö andrö, Lowalangi, Yehowa — Sabölö andrö, Lowalangi, Yehowa zangila, ba ndra murongo Iraono Gizeraeli göi: Na folaŵa ba na faröisama khö Yehowa — ba bato ma''ökhö wanolo ya''aga[7] —', '["Sin 50:1"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 23, 'wa no mafa''anö khöma naha wame''e sumange, ba wangerogö Yehowa; na no tanima wame''e sumange nitunu ba sumange ni''a, yaŵa, ba ma sumange fangorifi, ba yamulau mbalö Yehowa!', '["Sin 50:1"]', NULL),
  (3474647, 'OT', 'Yosua', 22, 24, 'Ba na tenga da''ö dödöma, wa malau ia: ma so hadia ia; me itörö tödöma, ma lamane dania ma''uwumi ba ma''uwuma: "Hadia khömi khö Yehowa, Lowalangi Ndraono Gizeraeli andrö?', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 25, 'Noa sa ibe''e ola Yoridano Yehowa ba gotaluada, ya''ami mado Rubeno ba mado Gado; saefa ami khö Yehowa!" Ba ma labato wamosumange Yehowa ma''uwuma labe''e ma''uwumi.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 26, 'Andrö maŵa''ö tödöma: Da''ö malau, mafazökhi khöma naha wame''e sumange; tenga ba wame''e sumange nitunu ba sumange nitaba;', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 27, 'ena''ö famaduhu''ö ia, he khöma ba he khömi ba ba ma''uwuda, fa mafosumange Yehowa fönania, wame''e sumange nitunu ba sumange nitaba ba sumange fangorifi khöma, fa tebai laŵa''ö dania ma''uwumi ba ma''uwuma: Saefa ami khö Yehowa!', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 28, 'Mamane dödöma: Na lamanö dania khöma, ba ma ba ma''uwuma, ba mamane: Mifaigi wama''anö naha wame''e sumange andrö khö Yehowa, nifa''anö ndra tuama, tenga ba wame''e sumange nitunu ba sumange nitaba; ena''ö famaduhu''ö ia, he khöma ba he khömi.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 29, 'Ya aröu khöma wolaŵa Yehowa ba fangerogö Yehowa ma''ökhö, wamazökhi naha wame''e sumange nitunu ba sumange ni''a ba sumange nitaba, nifasambua, baero naha wame''e sumange andrö khö Lowalangida, Yehowa, si so ba golayama nahiania andrö.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 30, 'Ba me larongo ira Fineha ere andrö ba salaŵa mbanua andrö, satua ngahönö Ndraono Gizeraeli, awönia, niŵa''ö mado Rubeno ba mado Gado ba si matonga mado Manase, ba ahono dödöra.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 31, 'Ba imane Fineha, ono Geleazari ere andrö, ba mado Rubeno ba ba mado Gado ba ba zi matonga mado Manase: "Oroma khöma ma''ökhö andre, wa fao khöda Yehowa, me no tenga fangerogö Yehowa wolaumi andrö; ba no ni''orifi Ndraono Gizeraeli, fa lö göna fönu Yehowa.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 32, 'Ba mangawuli Wineha andrö, ono Geleazari ere andrö, ba salaŵa no mege, laröi danö Gileadi, mado Rubeno ba mado Gado andrö; lafuli ira ba danö Gana''ana ba Ndraono Gizeraeli, la''ombakha''ö nirongora.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 33, 'Ba omasi Ndraono Gizeraeli ni''ombakha''öra andrö ba lasuno Lowalangi, ba lö''ö sa''ae itörö tödöra wanuwö ya''ira no mege ba famakiko tanö andrö sowanua mado Rubeno ba mado Gado.', '[]', NULL),
  (3474647, 'OT', 'Yosua', 22, 34, 'Ba lafotöi naha wame''e sumange andrö mado Rubeno ba mado Gado, lamane: Famaduhu''ö ia khöda, wa no Lowalangi Yehowa."', '[]', NULL),
  (3474648, 'OT', 'Yosua', 23, 1, 'Ba me no ara, me no ahono Ndraono Gizeraeli ibe''e Yehowa, ba nemalira andrö fefu, fasui, ba me no atua Yosua, me no numalö ndröfi,', '[]', NULL),
  (3474648, 'OT', 'Yosua', 23, 2, 'ba ifalukha''ö Ndraono Gizeraeli fefu Yosua, satuara ba salaŵara ba sanguhuku ba kumandru, ba imane khöra:', '[]', NULL),
  (3474648, 'OT', 'Yosua', 23, 3, 'Ba no mi''ila fefu hadia ia nilau Lowalangimi Yehowa ba niha andrö fefu fönami; Lowalangimi andrö, Yehowa, sa''ae zi fasöndra salahimi.', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 4, 'Ba hiza, ba no ututuru tana khömi niha andrö, si tosai, tana ba madomi, wolau dahö-dahö; i''otarai Yoridano, fefu soi, nihorigu, irege nasi sebua, tanö ba gaekhula luo.', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 5, 'Ba itimba ira fönami Lowalangimi, Yehowa, ifofanö fönami, ena''ö mihalö khömi danö, si mane nifabu''u Lowalangimi, Yehowa.[1]', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 6, 'Ba mi''abe''e''ö sibai dödömi, ba wolo''ö ba ba wolau fefu hadia ia zi so ba zura goroisa andrö khö Moze, fa böi mihole''ö ami, he ba gambölö ba he ba gabera.[2]', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 7, 'Fa böi mifaruka ami ba niha andrö, si tosai na ba khömi, ba fa böi mitötöi döi Lowalangira, we''amöi ba hölu ba khöra, ba böi mifosumange ba böi mangalulu ami khöra.[3]', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 8, 'Lowalangimi andrö, Yehowa, mi''olembai, si mane folaumi irugi ma''ökhö andre.[4]', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 9, 'Andrö itimba fönami soi sebua ba sabölö Yehowa; samösa lö niha sabölö moroi khömi, irugi ma''ökhö andre.', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 10, 'Ha samösa motöi ya''ami, ba hönö moloi ibe''e, me no Lowalangimi, Yehowa, zi fasöndra salahimi, si mane nifabu''unia khömi.[5]', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 11, 'Ba na omasi ami auri, ba mifaigi sibai, fa mi''omasi''ö Lowalangimi, Yehowa.', '["MozIV 33:53","MozV 4:2","MozII 23:13","MozV 11:22 b.t.","MozIII 26:8; Yes 30:17"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 12, 'Ba na faröi ami ena''ö, na mifaböbö ami ba zi tosai soi niha andrö ba khömi, na fambambatö ami ba na fahalö,', '["MozII 23:33; MozIV 33:55"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 13, 'ba böi zi lö aboto ba dödömi: ba lö''ö sa itohugö Lowalangimi Yehowa wanimba soi andrö fönami; tobali fesu ba tandraŵa ira khömi, ba bözi-bözi ba ngaimi ba doi ba hörömi, irege ahori ami ba danö si sökhi andre, nitehe Lowalangimi, Yehowa, khömi.[6]', '["MozII 23:33; MozIV 33:55"]', NULL),
  (3474648, 'OT', 'Yosua', 23, 14, 'Ba na utörö iada''e lala andrö, nitörö niha fefu dania, ba böi zi lö aboto sibai ba dödömi: sambua lö saekhu ba danö taroma li si sökhi andrö, niŵa''ö Lowalangimi, Yehowa, ba khömi andrö, no ahori itörö khömi, sambua lö saekhu ba danö.', '["MozV 28:15 b.t."]', NULL),
  (3474648, 'OT', 'Yosua', 23, 15, 'Ba si mane amabu''ula li andrö, nifabu''u Lowalangimi, Yehowa, khömi, wa no ahori itörö, si manö göi dania wamatörö Yehowa fameta''unia ya''ami andrö, fefu, irege no ihori ami ba danö si sökhi andre, nibe''e Lowalangimi, Yehowa, khömi.[7]', '["MozV 28:15 b.t."]', NULL),
  (3474648, 'OT', 'Yosua', 23, 16, 'Na misawö gamakhoita Lowalangimi, Yehowa, andrö, nifakhoinia khömi, ba na möi ami mamosumange Lowalangi bö''ö, wangalulu khöra, ba tesao wönu Yehowa khömi, ba lö ara, ba ahori ami ba danö si sökhi andre, nitehenia khömi.', '[]', NULL),
  (3474649, 'OT', 'Yosua', 24, 1, 'Ba ifalukha''ö mado Gizeraeli fefu Yosua ba Zikhema, ifakaoni''ö zatua Ndraono Gizeraeli ba salaŵara ba sanguhuku ba kumandru khöra, ba la''ondrasi Lowalangi.', '[]', NULL),
  (3474649, 'OT', 'Yosua', 24, 2, 'Ba imane Yosua ba zato fefu: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli; "Ba götö föna sibai, ba yefo nidanö [Oiferati] so wurugömi, Tara andrö, ama ndra Aberahamo Nakhori, ba lafosumange Lowalangi bö''ö.[1]', '["MozI 11:31"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 3, 'Ba ufawu''a wurugömi Aberahamo, uheta ba danö yefo nidanö andrö ba ufatöröi''ö ba danö Gana''ana ma''asagörö, ba ato ma''uwunia ube''e, ube''e khönia Giza''aki andrö.[2]', '["MozI 21:2","MozI 25:24; 36:8; 46:5"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 4, 'Ba khö Giza''aki ba ube''e Yakobo andrö ba Ezau; ba khö Gezau andrö, ba utehe hili Ze''ira andrö, ena''ö ihalö khönia; ba Yakobo ba ononia, ba lasaŵa danö Miserayi.[3]', '["MozI 21:2","MozI 25:24; 36:8; 46:5"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 5, 'Ba ufatenge ndra Moze A''aroni, ufakao Ndrawa Miserayi, wolau nilaugu andrö ba khöra, ba aefa da''ö, ba ufawu''a ami.[4]', '["MozII 3:10","MozII 14:5, b.t."]', NULL),
  (3474649, 'OT', 'Yosua', 24, 6, 'Uheta ndra amami ba danö Miserayi, ba mirugi nasi. Ba lagohi ndra amami Dawa Miserayi, la''ohe gureta ba wanuwö ba fao zi fakudo, irugi ba mbewe nasi zukhu andrö.[5]', '["MozII 3:10","MozII 14:5, b.t."]', NULL),
  (3474649, 'OT', 'Yosua', 24, 7, 'Ba la''angöröfi li Yehowa ba ogömi-gömi ba gotaluami Ndrawa Miserayi ibe''e; ba ifatörö khöra nasi, tobali alömö ira. Ba i''ila hörömi, nifatörögu ba Ndrawa Miserayi andrö, ba ara dania ami ba danö si mate andrö.', '["MozII 3:10","MozII 14:5, b.t."]', NULL),
  (3474649, 'OT', 'Yosua', 24, 8, 'Ba u''ohe ami ba danö Ndraono Gamori andrö, sowanua yefo Yoridano ba fasöndra ira khömi; ba ube''e ba dangami ira ba mihalö khömi danöra, ba uhori ira fönami.[6]', '["MozIV 21:25","MozIV 22:5"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 9, 'Ba maoso Mbalaki andrö, ono Zifora, razo Ndraono Moabi, ba wanuwö Iraono Gizeraeli. Ba ifatenge zinenge, ifakaoni''ö Mbileamo andrö, ono Mbeori, ba wangelifi ya''ami.[7]', '["MozIV 21:25","MozIV 22:5"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 10, 'Ba lö edöna ufondrondrongo li Mbileamo andrö. Ba ifahowu''ö ami ba tobali u''efa''ö ami ba dangania.', '["MozIV 21:25","MozIV 22:5"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 11, 'Ba mi''ötö Yoridano, ba mirugi Yerikho, ba fasöndra khömi mbanua Yerikho andrö, Iraono Gamori ba Dawa Weresi ba Dawa Gana''ana ba Iraono Kheti ba Iraono Girigasi ba Iraono Hewi ba Iraono Yebusi ba ube''e ba dangami ira.[8]', '["Yos 6:1 b.t.","MozII 23:28; Sin 44:4"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 12, 'Ba ufowaö-waö fönami geto, ba moloi ira fönami labe''e, razo Ndraono Gamori andrö, si felendrua; tenga ba zi''ölimi ba tenga ba wanami![9]', '["Yos 6:1 b.t.","MozII 23:28; Sin 44:4"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 13, 'Ba ube''e khömi danö ba zi lö erege dödömi, ba banua si tenga nitaru''ömi, ba mibali''ö nahiami, ba kabu nagu ba kabu nohi, si tenga nitanömi, ba mi''a mbua."[10]', '["MozV 6:10 b.t."]', NULL),
  (3474649, 'OT', 'Yosua', 24, 14, 'Ba mi''ata''ufi sa''ae Yehowa ba mifosumange ia moroi si''aikö ba dödömi ba böi faröi ami, ba miheta nadu andrö, nifosumange ndra tuami yefo nidanö andrö ba ba danö Miserayi, ba mifosumange Yehowa.[11]', '["SamI 7:3"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 15, 'Ba na lö omasi ami wamosumange Yehowa, ba mihonogöi ma''ökhö, ha niha nifosumangemi, na Lowalangi andrö, nifosumange ndra tuami, si so yefo nidanö andrö, ba na Lowalangi Ndraono Gamori andrö, si so ami ba danö; ba ya''odo ba soroiyomogu fefu, ba Yehowa mafosumange!', '["SamI 7:3"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 16, 'Ba latema li sato, lamane: Ya aröu khöma wangerogö Yehowa, ba wamosumange Lowalangi bö''ö!', '["MozII 20:2"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 17, 'Yehowa sa Lowalangima; ya''ia sa zolohe miyaŵa ya''ita ba ira amada moroi ba danö Miserayi, ba zi no möi sawuyu ita, ba solau sahöli-höli dödö andrö, ba zanehe ita, ba sondrorogö ya''ita ba lala andrö fefu, nitöröda, ba ba niha fefu, nitöröda tanö.[12]', '["MozII 20:2"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 18, 'Ba no ahori itimba fönada Yehowa soi andrö, awö Ndraono Gamori, si so ba danö. Ya''aga göi mamosumange Yehowa, me no ya''ia Lowalangima!', '["MozII 20:2"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 19, 'Ba imane Yosua ba zato: Tebai samosumange Yehowa ami, me no Lowalangi ni''amoni''ö ia; Lowalangi solohu ia: lö ibe''e aefa khömi lalömi ba horömi andrö![13]', '["MozII 20:5; MozIII 19:2"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 20, 'Na mi''erogö Yehowa, wamosumange Lowalangi bö''ö, ba i''erogö göi ami ba ifatörö khömi zi lö sökhi ba ihori ami, lö lai wa no si sökhi ifatörö khömi mege.', '["MozII 20:5; MozIII 19:2"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 21, 'Lamane sato khö Yosua: Böi, Yehowa mafosumange![14]', '["Sin 10:5 b.t."]', NULL),
  (3474649, 'OT', 'Yosua', 24, 22, 'Ba imane Yosua ba zato: Ya''ami zi so ba mbörö khömi, wa no mihonogöi, Yehowa nifosumangemi.', '[]', NULL),
  (3474649, 'OT', 'Yosua', 24, 23, 'Ba miheta Lowalangi bö''ö andrö, si so ba khömi, ba ena''ö khö Lowalangi Ndraono Gizeraeli andrö, Yehowa, aolo dödömi![15]', '["MozI 35:2"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 24, 'Ba lamane sato khö Yosua; Lowalangima, Yehowa andrö, mafosumange ba linia mofondrondrongo!', '[]', NULL),
  (3474649, 'OT', 'Yosua', 24, 25, 'Ba fawu''u li ira Yosua niha sato, me luo da''ö, ba ibe''e goroisa khöra Yosua ba ifakhoi lala, ba da''ö, ba Zikhema.[16]', '["RazII 23:3"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 26, 'Ba itanö ba zura goroisa Lowalangi huhuo andrö Yosua; ba ihalö gowe sebua, ifasindro ba da''ö ba mbörö manawa, si te''u''u ba ni''amoni''ö khö Yehowa andrö.', '["RazII 23:3"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 27, 'Ba imane Yosua ba niha sato fefu: Hiza, si so ba mbörö khöda gowe andre, noa sa irongo fefu daroma li andrö, huhuo Yehowa khöda; andrö si so ba mbörö ia, ba khömi andrö, fa böi mi''osilö''ögö Lowalangimi.[17]', '["MozI 31:48"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 28, 'Aefa da''ö, ba ifofanö ira Yosua, isaŵa dana khönia zamösana.', '["MozI 31:48"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 29, 'Ba noa da''ö, ba mate Yosua andrö, ono Nuni, enoni Yehowa, fulu töra otu fakhe wa''arania ba guli danö.', '["Nga''ötII 34:33"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 30, 'Ba lako''o ia ba danö tana khönia, ba Dimenata Zera, ba hili mado Geferayi, yöu hili Gasi andrö.', '["Nga''ötII 34:33"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 31, 'Ba lafosumange Yehowa Iraono Gizeraeli, götö wa''ara Yosua andrö, ba he ba götö zatua andrö, sanau noso moroi khö Yosua, si no mangila folau Yehowa andrö, nilaunia ba Ndraono Gizeraeli.[18]', '["Nga''ötII 34:33"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 32, 'Ba boto Yosefo andrö, ni''ohe Ndraono Gizeraeli moroi ba danö Miserayi, ba lako''o ba Zikhema, ba mbenua andrö, ni''öli Yakobo no ba Ndraono Hemori, soböli si otu kesita, ba tebe''e tana ba ma''uwu Yosefo.[19]', '["MozI 33:19; 50:25"]', NULL),
  (3474649, 'OT', 'Yosua', 24, 33, 'Ba mate göi Geleazari andrö, ono Ga''aroni, ba lako''o ia ba Gibea, banua nononia Fineha andrö, nitehe khönia ba hili mado Geferayi andrö.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 1, 'Ba tobali me no mate Yosua, ba lasofu khö Yehowa Iraono Gizeraeli, lamane: Ha niha ndra''aga zi föföna möi misiyaŵa ba Ndrawa Gana''ana, fasuwö khöra?', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 2, 'Imane Yehowa: Mado Yuda zi föföna möi misiyaŵa; ube''e ba dangara danö.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 3, 'Ba lamane mado Yuda ba dalifusöra mado Zimeoni: Mitabu awöma ba dana khöma, ena''ö tasuwö Ndrawa Gana''ana, ba möiga göi awömi dania ba dana khömi! Ba fao khöra mado Zimeoni.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 4, 'Ba möi mado Yuda ba ibe''e ba dangara Yehowa Ndrawa Gana''ana ba Dawa Weresi, tobali la''alani ba Mbeseki, 10,000 [zi mate].', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 5, 'Ba fakhamö ira Gadoni Beseki ba Mbeseki, fasöndra ira, ba la''alani Ndrawa Gana''ana, fabaya Dawa Weresi.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 6, 'Ba moloi Gadoni Beseki, ba lagohi ia. Lara''u ba la''eŵa duturu sebua ba danga ba ba gahe.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 7, 'Ba imane Adoni Beseki: Fitu ngafulu razo si no mu''eŵa tuturu danga ba tuturu kahe sebua, zangozaragö akhökhöla barö meza khögu: Nilaugu andrö, be isulöni khögu Lowalangi! Awena la''ohe ia ba Yeruzalema, ba da''ö mate ia.[1]', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 8, 'Ba lasuwö Yeruzalema mado Yuda, ba atu''a ira, lalaŵa bawa zi''öli, ba banua, ba latunu.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 9, 'Aefa da''ö, ba möi misi tou mado Yuda, ba wanuwö Dawa Gana''ana andrö, si so ba hili andrö ba danö tanö raya ba ba zalo''o tanö andrö.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 10, 'Ba lasaŵa Ndrawa Gana''ana andrö ba Heberona mado Yuda. Ba töi Heberona föna, ba Kiriati Garaba. Ba te''ala Zezai ba Ahima ba Talamai, nga''ötö Genaki andrö, labe''e.[2]', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 11, 'Ba moroi ba da''ö, ba lasaŵa mbanua Debira; ba töi Debira föna, ba Kiriati Zeferi.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 12, 'Ba ifabu''u Kalebi, imane. Ha niha zolaŵa Kiriati Zeferi andrö, ba satu''a ba da''ö, khönia ube''e nonogu Akhasa.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 13, 'Ba atu''a Gotenieli, ono Genasi andrö, akhi Galebi, ba ibe''e khönia nononia Akhasa [Kalebi].', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 14, 'Ba me la''ohe khönia, ba ifarou, ena''ö i''andrö mbenua khö namania. Ba ahele ia moroi ba hulu galide, ba imane khönia Kalebi:', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 15, 'Hana ndra''ugö! Ba imane khönia: Be''e atö khögu mbuala ba wofanö. Noa sa öbe''edo ba danö tanö raya, si no oköliköli, ba be''e atö khögu gumbu nidanö! Ba ibe''e khönia gumbu ba hili ba umbu ba ndraso Kalebi.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 16, 'Ba no möi misi yaŵa nono Ndraono Geni andrö, la''o Mose, no laheta ira ba mbanua khorema andrö, awö mado Yuda, no lasaŵa danö mado Yuda andrö, tanö si mate, ba zanaere, ba Garada, möi ira mowanua, ba da''ö, ba ngai Ndraono Gamaleki.[3]', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 17, 'Ba fao ba dalifusöra mado Zimeoni mado Yuda, ba la''alani Ndrawa Gana''ana, banua Zefata, ba lafakiko; andrö wa labe''e töi mbanua andrö Horima.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 18, 'Ba mado Yuda andrö, ba lahalö göi khöra Gasa, fabaya tanöra, ba Asekalo, fabaya tanöra, ba Ekerona, fabaya tanöra.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 19, 'Ba itolo mado Yuda Yehowa, tobali la''okhögö mboto hili andrö. Ba banua ba zalo''o andrö, ba tebai latimba, börö me so khöra gureta si''öli.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 20, 'Ba Heberona andrö, ba latehe khö Galebi, la''o''ö ni''oroi''ö Mose, ba itimba ba da''ö nga''ötö Genaki andrö, si datolu.[4]', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 21, 'Ba Iraono Yebusi andrö, banua Yeruzalema, ba tebai latimba mado Yuda. Ba tobali lö tebulö Ndraono Yebusi andrö ba ngai mado Yuda ba Yeruzalema, irege ma''ökhö andre.', '["MozIII 24:19","Yos 15:14, b.t.","MozIV 10:29; Faigi 4:11","MozIV 14:24; Yos 14:13"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 22, 'Ba iraono Yosefo andrö, ba möi göi misi yaŵa ba Mbetieli, ba itolo ira Yehowa.', '["MozI 28:19"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 23, 'Ba lafauzei Mbetieli andrö iraono Yosefo; ba töi mbanua andrö föna, ba Lusi.[5]', '["MozI 28:19"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 24, 'Ba samauze andrö, ba la''ila niha si otarai moroi yomo. Ba lamane ba da''ö: Oroma''ö khöma lalama ba mbanua ba matolo''ö göi.', '["MozI 28:19"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 25, 'Ba i''oroma''ö khöra zolala ira miyomo ba lalaŵa mbanua andrö bawa zi''öli; ba niha no mege ba si sawōē ya''ira, ba la''orifi.', '["MozI 28:19"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 26, 'Ba isaŵa danö Ndraono Kheti niha andrö, itaru''ö mbanua ba ibe''e töinia Lusi; ba da''ö döinia irugi ma''ökhö.', '["MozI 28:19"]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 27, 'Ba iraono Manase, ba lö latimba mbanua Mbeti Zeana andrö ba banua si faböbö khöra, ya''ia Da''anakhi ba si faböbö khöra, ba banua Dora ba si faböbö khöra, ba banua Yibelea ba si faböbö khöra, ba banua Megido ba si faböbö khöra. Tobali falukha Ndrawa Gana''ana, lö tebulö ira ba danö da''ö.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 28, 'Ba me abölö Ndraono Gizeraeli, ba labe''e barö mbawara Ndrawa Gana''ana andrö, enonira: fanimba ya''ira, ba tebai.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 29, 'Ba Iraono Geferayi, ba lö latimba Ndrawa Gana''ana banua Geseri, ba tobali lö tebulö Ndrawa Gana''ana ba ngaira, ba Geseri.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 30, 'Ba Iraono Zebuloni, ba lö latimba mbanua Giterono ba banua Nahaloli, ba tobali lö tebulö ba ngaira Ndrawa Gana''ana, ba tobali enonira ba gafuriata.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 31, 'Ba Iraono Gaseri, ba lö latimba mbanua Ako ba banua Zidona, femöi Gahalaba ba Akhisiba ba Heleba ba Afika ba Rehobo.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474650, 'OT', 'Sanguhuku', 1, 32, 'Ba tobali tefasui Dawa Gana''ana Ndraono Gaseri, Dawa Gana''ana sokhö tanö, me tebai latimba.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 33, 'Ba Iraono Nafetali, ba lö latimba mbanua Mbeti Zemesi ba banua Mbeti Anata. Ba tobali tefasui ira Dawa Gana''ana sokhö tanö; ba banua Mbeti Zemesi ba banua Mbeti Anata, ba enonira dania.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 34, 'Ba Iraono Gamori zondregeni ba hili mado Dano, lö latehe möi mitou ira ba zalo''o.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 35, 'Tobali falukha Ndraono Gamori andrö lö tebulö ira ba Hari Heresi ba ba Nayalono ba ba Za''alibi. Ba me abölö dania ma''uwu Yosefo, moroi khöra, ba tobali enonira ira.', '[]', NULL),
  (3474650, 'OT', 'Sanguhuku', 1, 36, 'Ba tanö Ndraono Gedomo, ba i''otarai lala dongo andrö, ba irugi Zela ba miyaŵa na.', '[]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 1, 'Ba so zinenge Yehowa si otarai Giligala, we''amöi misi yaŵa ba Mbokhimi, ba imane: No u''ohe miyaŵa ami moroi ba danö Miserayi ba no ufasao ami ba danö andre, nifabu''ugu khö ndra tuami, fahölusa. Ba no ufabu''u: Lö uwu''ai wawu''usa li andrö khögu khömi, irugi zi lö aetu;[1]', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 2, 'ba böi fawu''u li ami ba niha ba danö andre; naha wame''e sumange andrö khöra, ba midudugö. Ba no lö nifondrondrongomi oroisagu — hadia nilaumi?[2]', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 3, 'Ba iada''e, ba uwa''ö khömi: Lö utimba ira fönami, ena''ö amaedola ndroi ira ba ngaimi, ba Lowalangira, ba ena''ö amaedola dandraŵa khömi.[3]', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 4, 'Ba me iŵa''ö da''ö ba Ndraono Gizeraeli fefu sinenge Lowalangi andrö, ba me''ge''ege niha sato fefu.', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 5, 'Andrö wa labe''e töi naha andrö Mbokhimi (sege-ege). Ba labe''e zumange Yehowa ba da''ö.', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 6, 'Me no ifofanö niha Yosua, ba lafazaŵa ira Iraono Gizeraeli, möi ira mu''okhögö danö, isaŵa dana khönia zamösana.', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 7, 'Ba la''o''ö khö Yehowa niha sato ba götö Yosua andrö ba ba götö zatua andrö, sanau noso moroi khö Yosua, si no anehe zebua andrö, nilau Yehowa ba Ndraono Gizeraeli.[4]', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 8, 'Ba mate Yosua andrö, ono Nuni, enoni Yehowa, 110 fakhe wa''anau nosonia.', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 9, 'Ba lako''o ia ba dana khönia tanö andrö, ba Dimenata Heresi, ba hili mado Geferayi, yöu hili Gasi.', '["MozI 17:7","MozV 7:2; 12:3","MozV 7:16; Yos 23:13","Yos 24:31"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 10, 'Ba ahori te''orudugö khö ndra tuara zi sagötö niha andrö, ba sagötö zi so dania furira, niha si lö mangila Yehowa ba he nilaunia andrö ba Ndraono Gizeraeli.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 11, 'Ba si lö omasi Yehowa lalau Iraono Gizeraeli, lafosumange Mba''ali andrö.[5]', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 12, 'Ba la''erogö Yehowa, Lowalangi ndra tuara, si no mangeheta ya''ira ba danö Miserayi, lago''ögo''ö Lowalangi bö''ö, Lowalangi soi niha andrö, si tefasui ya''ira ösa, mangalulu ira khöra, ba fangandrö fönu Yehowa da''ö.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 13, 'Ba me la''erogö Yehowa, me lafosumange Mba''ali ba Asera andrö,', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 14, 'ba mofönu Yehowa ba Ndraono Gizeraeli, ba ibe''e ba danga zamara''u, ena''ö laraburabu hadia ia khöra; ilulu ira ba danga nemalira, si fasui, tobali tebai sa''ae lalaŵa nemalira andrö.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 15, 'Gofu heza möi ira, ba udura danga Yehowa, ba wamakiko, itörö nidaö''ö-daö''ö Yehowa, si fahölu ia khöra. Ba tosasa sibai ira ibe''e [Yehowa].[6]', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 16, 'Ba i''asogö zanguhuku Yehowa; da''ö dania zangefa''ö ya''ira ba danga zamara''u andrö.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 17, 'Ba he li zanguhuku andrö khöra, ba lö lafondrondrongo, omasi ira Lowalangi bö''ö ba mangalulu ba da''ö. No alio sibai laröi lala andrö, nitörö ndra tuara mege, wolo''ö oroisa Lowalangi: bö''ö wolaura.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 18, 'Ba na i''asogö khöra zanguhuku Yehowa, ba itolo zanguhuku andrö Yehowa, wangefa''ö ya''ira ba danga nemalira, götö wa''ara zanguhuku andrö. So sa wa''ahakhö dödö Yehowa ba wangarö-ngaröra andrö ba zamakao ya''ira, ba zamalangögö ya''ira andrö.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 19, 'Ba na no mate zanguhuku, ba lafuli lalau zi lö sökhi, sabölö-bölö moroi ba nilau ndra amara, wolo''ö ba Lowalangi bö''ö, ba wamosumange da''ö ba ba wangalulu khöra. Lö laböhöli wolaura andrö ba bua-buara andrö, bua-bua zabe''e tandro.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 20, 'Ba mofönu Yehowa ba Ndraono Gizeraeli, ba imane: Me no isawö soi andre gamakhoita ba wawu''usa li andrö khögu, nifakhoigu khö ndra amara, ba me lö ni''o''öra oroisagu andrö,', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 21, 'ba samösa lö''ö sa''ae utimba fönara soi niha andrö, nisaigö Yosua, me mate ia,[7]', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 22, 'ba wame''e fanandraigö Ndraono Gizeraeli ya''ira andrö, na latöngöni lala andrö khö Yehowa, ba wanörö ya''ia, si mane fanöngöni ndra tuara föna, ba na lö''ö.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474651, 'OT', 'Sanguhuku', 2, 23, 'Ba tobali itehe Lowalangi, lö tebulö soi niha andrö; lö ida''i-da''i wa nimba ya''ira ba lö ibe''e ba danga Yosua.', '["MozIV 25:1 b.t.; RazII 2:1 b.t; Faigi 8:33","MozIII 26:17","Yos 23:13"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 1, 'Ba da''ö soi andrö, nisaigö Yehowa, ba wame''e fanandraigö Ndraono Gizeraeli ya''ira, fanandraigö fefu zi lö anehe mege fasöndrata andrö ba wangokhögö tanö Gana''ana,', '["MozV 7:3"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 2, '— börö mado Gizeraeli andrö, ba wamahaö ya''ira ba wanuwö, ya''ira si lö anehe fasöndrata andrö föna:', '["MozV 7:3"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 3, 'Razo Ndrawa Wilisiti andrö, si lima, ba Dawa Gana''ana fefu, banua Zidona ba Iraono Hewi, ba hili Libano, i''otarai hili Mba''ali Heremono, irege lala ba Hamata.', '["MozV 7:3"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 4, 'Fanandraigö Ndraono Gizeraeli ira, ba wamaigi, na la''o''ö goroisa Yehowa andrö, nibe''enia khö ndra tuara, nifa''ema Mose.', '["MozV 7:3"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 5, 'Ba tobali tefasui Ndraono Gizeraeli Dawa Gana''ana ba Iraono Kheti ba Iraono Gamori ba Iraono Weresi ba Iraono Hewi ba Iraono Yebusi,', '["MozV 7:3"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 6, 'lahalö nonora alawe ba labe''e ba nonora matua nonora, ba lafosumange Lowalangira andrö.[1]', '["MozV 7:3"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 7, 'Ba si lö omasi Yehowa lalau Iraono Gizeraeli; olifu ira Lowalangira, Yehowa, ba lafosumange Mba''ali ba Asera andrö.', '["MozV 7:3"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 8, 'Ba mofönu Yehowa ba Ndraono Gizeraeli ba ibe''e ira ba danga Gusa Risata''i, razo Garamo Nahara''i; meŵalu fakhe barö mbawa Gusa Risata''i Ndraono Gizeraeli.', '["MozV 7:3"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 9, 'Awena la''angaröfi li Yehowa Iraono Gizeraeli, ena''ö itolo ira. Ba i''asogö ba Ndraono Gizeraeli zangorifi Yehowa, sangefa''ö ya''ira: Otenieli andrö, ono Gena, akhi Galebi.[2]', '["Faigi 1:13"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 10, 'Ba so khönia Geheha Yehowa, ba ifaigi lala ba Ndraono Gizeraeli. Ba möi ia fasuwö, ba ibe''e ba dangania Gusa Risata''i, razo Garamo andrö, Yehowa, ba ilaŵa Gusa Risata''i.', '["Faigi 1:13"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 11, 'Ba öfa wulu fakhe, ba lö hadia ia ba danö. Ba mate Gotenieli, ono Gena.', '["Faigi 1:13"]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 12, 'Ba lafuli lalau zi lö omasi Yehowa Iraono Gizeraeli. Ba ibe''e ba danga Negelono, razo Ndraono Moabi, Ndraono Gizeraeli Yehowa, me no lalau zi lö omasi Yehowa.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 13, 'Ba ihalö awönia Ndraono Gamoni ba Iraono Gamaleki da''ö, möi ia, isuwö Ndraono Gizeraeli ba i''okhögö mbanua khorema andrö.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 14, 'Feleŵalu fakhe Ndraono Gizeraeli barö mbawa Negelono, razo Ndraono Moabi.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 15, 'Ba la''angaröfi li Yehowa Iraono Gizeraeli, ba i''asogö khöra zangorifi Yehowa, Ehudi andrö, ono Gera, mado Mbeniyami, niha si takera. Ya''ia zama''ema beo Ndraono Gizeraeli khö Negelono, razo Ndraono Moabi.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 16, 'Ba ifazökhi khönia göri Ehudi, göri si faoma bawa, ha lito wa''anau, ba ibe''e ba löwi-löwinia, barö mbarunia, ba gambölönia.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 17, 'I''ohe, me möi ia molohe beo andrö khö Negelono, razo Ndraono Moabi. Ba Egelono andrö, ba no niha sesolo sibai.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 18, 'Ba me no ifa''ema mbeo andrö, Ehudi, ba ifasao mangawuli niha andrö, sonoro beo andrö mege;', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 19, 'ba ya''ia, ba ifuli ia, me no larugi nadu andrö ba Giligala, ba imane khö Negelono: So niŵa''ögu khöu razo, ba zi lö niha! Ba imane: Bö''ua! Ba möi baero fefu zi so ba ngainia.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 20, 'Ba me no möi si bakha khönia Ehudi, me ha ya''ia zidadao ba mbate''e yaŵa, ba zokafukafu, ba imane Ehudi: So khögu niŵa''ö Lowalangi khöu! Ba maoso ia, moroi ba dadaomania.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 21, 'Ba isöbi zi''öli ba gambölonia Ehudi tangania kabera,', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 22, 'itaru''ö ba dalunia, irege ahöndrö na bakha ndranga göi, fabaya ösi, ba te''u''u ba dawö nösi, lö''ö sa ifuli idöni zi''öli ba dalunia, no atöla dambai.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 23, 'Ba möi baulu Gehudi. Iduhö mbawandruhö mbate''e yaŵa, furinia, ba ilazi.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 24, 'Ba ha si''ai mofanö ia, ba so wazuri Negolono. Ba me la''ila, no mulazi mbawandruhö mbate''e yaŵa, ba lamane dödöra: Te no möi ia ba nidanö ba mbate''e ba zokafukafu andrö.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 25, 'Ba labazebaze''ö manö. Ba me lö''ö manö na ibokai mbawandruhö mbate''e yaŵa, ba lahalö wogoe ba lakoe, ba hiza tou ba zalo zokhö ya''ira, no mate.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 26, 'Ba barö wa''aröröra andrö, ba no moloi Gehudi, no irugi nadu andrö, ba ikhamö Ze''ira.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 27, 'Ba me no irugi yomo mbanua, ba ilau dorofe ba hili Geferayi. Ba möi mitou Ndraono Gizeraeli, awönia, moroi ba hili, ba ya''ia zangoloi''ö.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 28, 'Ba iŵa''ö li khöra, imane: Mitabu awögu, mitou, noa sa ibe''e ba dangami nemalimi andrö, Iraono Moabi, Yehowa. Ba möi ira mitou, awönia, laba''a götöna ba Yoridano, tanö ba danö Ndraono Moabi, samösa lö lafatörö.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 29, 'Ba te''ala Ndraono Moabi, labe''e, me luo da''ö, mato 10.000 zi mate, oi sabölö, solohe baluse, samösa lö soloi labe''e.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 30, 'Ba tobali möi barö mbawa Ndraono Gizeraeli Ndraono Moabi, me luo da''ö. Ba 80 fakhe wa''ara, ba lö hadia ia khöra ba danö. Ba sanguhuku ya''ira Gehudi, irugi wa''amatenia.', '[]', NULL),
  (3474652, 'OT', 'Sanguhuku', 3, 31, 'Ba aefa da''ö, ba Samigaro, ono Ganata; sangalani Dawa Wilisiti da''ö, 600 ibunu bözi-bözi göröbao, ba sangorifi Iraono Gizeraeli ia göi.', '[]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 1, 'Ba lafuli zui lalau zi lö omasi Yehowa Iraono Gizeraeli — noa sa mate Gehudi.[1]', '["SamI 12:9; Yos 11:11"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 2, 'Ba i''amawa ira Yehowa ba danga Yabino andrö, razo Ndrawa Gana''ana, ba Hasora. Ba kumandra sebua khönia Zisera, banua Haroseti niha baero.', '["SamI 12:9; Yos 11:11"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 3, 'Ba la''angaröfi li Yehowa Iraono Gizeraeli. Siŵa ngaotu sa khö Zisera gureta si''öli ba iforege wamakao Iraono Gizeraeli, dua wulu fakhe wa''ara.', '["SamI 12:9; Yos 11:11"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 4, 'Ba me luo da''ö, ba sanguhuku Iraono Gizeraeli, ba Debora, fo''omo Lafidoti, sama''ele''ö ira alawe.', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 5, 'Barö nohi Debora andrö so nomonia, ba gotaluara Rama Mbetieli, ba hili Geferayi, ba möi-möi khönia Ndraono Gizeraeli, ba wamatunö huhuora.', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 6, 'Ba ifatenge zinenge, ifakaoni''ö Mbaraki andrö, ono Gabinoa, banua Gedesi ba Ndraono Nafetali, ba imane khönia: Si ndruhu! no iŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Labu, ae ba hili Dabora ba ohe awöu zi 10,000 niha, mado Nafetali ba mado Zebuloni;[2]', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 7, 'ba u''ohe Zisera andrö, kumandra andrö khö Yabino, awö gureta andrö khönia, awö zato khönia, ba wamaondragö ya''ugö, ba zinga mbombo Kizono, ba ube''e ba dangau ira.', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 8, 'Ba imane khönia Baraki: Na möi ndra''ugö awögu, ba möido, ba na lö möi''ö awögu, ba lö möido!', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 9, 'Ba imane: Möido sa awöu, ba tenga khöu dania wa''ebua duria, ba we''amöimö andrö, ba danga ndra alawe dania i''amawa Zisera andrö Yehowa. Ba maoso Debora, möi ia awö Mbaraki ba Gedesi.', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 10, 'Ba ifakaoni''ö ba Gedesi mado Zebuloni, awö mado Nafetali Baraki; 10,000 niha si fao khönia misi yaŵa ba fao göi khönia misi yawa Debora.', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 11, 'Ba Heberi andrö, Iraono Geni, ba no iheta ia khö Ga''ino andrö, ma''uwu Hobabi, matua Moze, ba sate idaru-daru''ö nosenia, irugi manawa andrö ba ngai Za''ana''i, sahatö ba Gedesi.[3]', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 12, 'Ba me la''ombakha''ö khö Zisera, no möi misi yaŵa ba hili Dabora Mbaraki andrö, ono Gabinoa,', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 13, 'ba i''oroi''ö guretania andrö fefu Sisera, 900 gureta si''öli, awö zabölö andrö fefu, si fao-fao khönia; la''otarai Haroseti niha baero andrö, lasaŵa mbombo Kizono.', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 14, 'Ba imane Debora khö Mbaraki: Labu! me no da''e mbaŵa andrö, ba nibe''e Yehowa ba dangau Sisera andrö; noa sa Yehowa zi möi, mowaö-waö fönau! Ba möi mitou Mbaraki moroi ba hili Dabora, ba 10,000 zolo''ö ya''ia niha.', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 15, 'Ba ikeani Zisera, awö guretania fefu, awö zabölö khönia fefu, Yehowa, föna Mbaraki, me la''abölögö wolau khöra; ba möi tou Zisera, moroi ba gureta, moloi, itörö tanö.[4]', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 16, 'Ba igohi gureta andrö ba sanuwö andrö Baraki, irugi Haroseti niha baero, ba ahori mate ba mbawa zi''öli zabölö andrö khö Zisera, samösa lö si tosai.', '["Heb 11:32","MozIV 10:29","Sin 83:10"]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 17, 'Ba Sisera, ba no moloi, no itörö tanö ba no isaŵa nose Ya''ela andrö, fo''omo Ndraono Geni andrö, Heberi; lö''ö sa si fa''udu ira Yabino, razo Hasora, zi samba omo andrö Heberi, Iraono Geni.', '[]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 18, 'Ba möi tou Ya''ela, ifaondragö Zisera, imane khönia: Ae baose Tua, ae baose khögu; lö hadia ia ni''ata''ufi! Ba möi ia baose khönia, ba ibalugö ia tufo.', '[]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 19, 'Ba imane khönia: Hadia, lö öbe''e ögu nidanö ma''ifu? Owökhi dödögu. Ba ibokai naha zusu zaŵi, ibe''e önia; ba ifuli ihawui ambala.', '[]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 20, 'Ba imane khönia: Iagö mbawandruhö nose, ba na so niha, na isofu khöu, na imane: Hadia, so ba da''e niha? ba ömane: Lö''ö!', '[]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 21, 'Ba ihalö gosö-osö nose Ya''ela andrö, fo''omo Heberi, ba ituyu warökha, lö ida''i-da''i we''amöi ba ngainia ba ibözi ba dangi-danginia gosö-osö andrö, irege tetaru ba danö, noa sa mörö ia. Ba ono matelö ia ba mate.', '[]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 22, 'Ba ba da''ö sibai so Mbaraki, solohi Sisera. Ba möi tou Ya''ela, i''ondrasi ia, imane khönia: Ae ba da''e, da''uroma''ö khöu niha andrö, ni''aluimö! Ba me möi ia baose khönia, ba i''ila tou Zisera, si no mate, ba lö si tebulö ba dangi-danginia gosö-osö andrö;', '[]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 23, 'Si manö wa''ate''ala Yabino andrö, razo Ndrawa Gana''ana, labe''e Iraono Gizeraeli, me luo da''ö, itolo Lowalangi.', '[]', NULL),
  (3474653, 'OT', 'Sanguhuku', 4, 24, 'Ba itugu lahöndrö-höndrögö Yabino andrö, salaŵa Ndrawa Gana''ana, Iraono Gizeraeli, irege lafalua wamakiko ya''ia.', '[]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 1, 'Ba manunö ndra Debora Baraki, ono Gabinoa, me luo da''ö, lamane:', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 2, '"Wa so zolohe Iraono Gizeraeli, wa no aoha gölö zato — misuno Yehowa!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 3, 'Mifondrondrongo, ya''ami razo, mibe''e mbörö dalingami, ya''ami salaŵa! Edönado usuno Yehowa, da''ulau mbiola khö Yehowa, Lowalangi Ndraono Gizeraeli!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 4, 'Me mangefa ndra''ugö ba Ze''ira, ya''ugö Yehowa, me mofanö''ö, me ö''otarai zalo''o andrö ba Ndraono Gedomo, ba moduru danö ba mowöi mbanua si yaŵa; mowöi idanö lawuo.[1]', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 5, 'Mangiwa hili föna Yehowa, Sina''i andrö, föna Yehowa, Lowalangi Ndraono Gizeraeli.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 6, 'Me luo Zamigaro andrö, ono Ganata, me luo Ya''ela andrö, ba lö sanörö lala; ba sanörö lala ena''ö, ba lala saköi latörö.[2]', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 7, 'Ahono zalaŵa Ndraono Gizeraeli, ahono ira, irege maoso ndra''ugö, ya''ugö Debora, irege maoso''ö ina Ndraono Gizeraeli!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 8, 'Latutuyu Lowalangi si bohou; fasöndrata ba zinga mbawa göli, me luo da''ö. Baluse, ba lö mu''ila, ba he toho, ba zi 40.000 andrö ba Ndraono Gizeraeli.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 9, 'Khö zolohe Iraono Gizeraeli dödögu; ya''ami si no aoha ölö ba zato andrö, misuno Yehowa!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 10, 'Ya''ami, si fakudo ba hulu galide si alawe soyo''oyo, ba ya''ami sidao-dao ba dufo, ba ya''ami, sanörö lala, ba mihede!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 11, 'Ba zi no aröu aefa ba wagua-guasa zi fafana andrö, ba gotalua hele andrö, ba da''ö ndra mudunö-dunö wanguhuku Yehowa andrö, fanguhuku zalaŵa andrö khönia ba Ndraono Gizeraeli! Me luo da''ö möi mitou ba mbawa göli Ndraono Gizeraeli!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 12, 'Labu, labu Debora; labu, labu, anunö! Faoso Baraki, ra''u zondra''u ya''ugö mena''ö, ya''ugö, ono Gabinoa!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 13, 'Me luo da''ö möi mitou zi tosai salaŵa, si tosai sabölö. Möi mitou awögu Yehowa, awö zabölö andrö.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 14, 'Mado Geferayi, soŵa''a ba danö Ndraono Gamaleki; la''o''ö ndra''ugö, ya''ugö mado Mbeniyami, fao ba zato andrö khöu; möi mitou ma''uwu Makhiro, sangoloi''ö, ba ma''uwu Zebuloni, solohe si''o zalaŵa.[3]', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 15, 'Ba salaŵa mado Isasari möi awö Debora, ba no si mane Isasari Mbaraki andrö; i''oloi''ö ia ba ndraso ahenia. Ba zinga mbombo andrö ba mado Rubeno, ba abölö wangera-ngera.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 16, 'Hadia wa no dumao-dao ndra''ugö ba gotalua kandra mbiri-biri, ba wamondrondrongo fambehesa ngawawa andrö? Ba zinga mbombo andrö ba mado Rubeno, ba no abölö wangera-ngera.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 17, 'Gileadi andrö, ba no ahono-hono yefo Yoridano; ba mado Dano, ba hana wa la''iagö manö nowo andrö? Mado Gaseri, ba ahono-hono manö ba mbewe nasi, lö tebulö ira ba mbewe dalu andrö khöra.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474654, 'OT', 'Sanguhuku', 5, 18, 'Sebuloni andrö, ba no soi si lö ata''u mate, ba si manö göi Nafetali ba mbawö andrö.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 19, 'So razo andrö, fasöndra; fasöndra razo Ndrawa Gana''ana andrö, me luo da''ö, ba Da''anakhe, ba mbewe nidanö andrö ba Megido: ba lö si falukha ira ahulua firö!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 20, 'Moroi ba mbanua si yaŵa fasöndra ndröfi; moroi ba lalara andrö fasöndra ira khö Zisera andrö.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 21, 'No ahani ira ba mbombo Kizono andrö, ba "mbombo wasöndrata" andrö, mbombo Kizono. Faoso, ya''ugö tödögu, abölö''ögö!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 22, 'Me luo da''ö labörö danö kudo, me mandruo, me lafandruo sabölö andrö khöra.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 23, 'Mi''elifi Merosi andrö! iŵa''ö mala''ika Yehowa andrö, mi''elifi mbanuara, me lö si möi ira manolo Yehowa, me lö nitolora Yehowa, awö zabölö andrö!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 24, 'Nisuno Ya''ela andrö, föna ndra alawe bö''ö; fo''omo Heberi andrö, ma''uwu Geni, föna ndra alawe [fefu], baose ndramusuno ia!', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 25, 'Idanö i''andrö [Sisera] ba susu ibe''e; ba mako si sökhi i''oro''ö khönia wanikha zusu.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 26, 'Ba ituyu gosö-osö andrö ba ihalö kambölönia warökha, iböbözi Zisera, iboto högönia, irasa dangi-danginia, itöla''ö.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 27, 'Ba iköröbui ia fönania, alau ia, adölö tou; fönania iköröbui ia, alau, ba ba niköröbuinia ya''ia adölö ia tou, no mate.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 28, 'Ba ifaigi ba zandrela ina Zisera, mu''ao ba darali, imane: "Hana wa ara mangawuli guretania? Hana wa ahou gahe kudonia?"', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 29, 'Ba fondrege zatua-tua wo''omo zalaŵa andrö khöra zanema linia, ba ya''ia göi ifuli iŵa''ö niŵa''önia mege:', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 30, '"Lö zi lö lasöndra mege gahulua ba ma awena lafaosa, sambua, ba ma dombua nono alawe zamösa, ba ahulua nukha soginigini khö Zisera; ahulu nukha soginigini, nila''a-la''a ba wanoso, nukha soginigini, dua görö zalendra ba mbagi wo''omo zalaŵa."', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474654, 'OT', 'Sanguhuku', 5, 31, 'Si manö zi nangea wa''atekiko zi fa''udu khöu fefu, ya''ugö Yehowa! Ba sangomasi''ö ya''ia, ba no hulö wa''atumbu luo, ba lakhöminia andrö." Ba lö''ö sa''ae hadia ia ba danö, öfa wulu fakhe wa''ara.', '["Sin 68:8","Faigi 3:31","Faigi 12:15"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 1, 'Ba me lalau zi lö omasi Yehowa Iraono Gizeraeli, ba ibe''e ira ba danga Ndraono Midiano Yehowa, mewitu fakhe.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 2, 'Ba lafakao Ndraono Gizeraeli Iraono Midiano. Ba labali''ö nahara mbawö andrö ba hili Iraono Gizeraeli, ba tögi narö hili andrö, awö nahia saro ba hili, ba Ndraono Midiano andrö.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 3, 'Ba na no manaru Ndraono Gizeraeli, ba möi miyaŵa khöra Ndraono Midiano, awö Ndraono Gamaleki, awö zowanua tanö ba gatumbukha luo.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 4, 'Ba tebato ba da''ö khöra, ba lafufu zinanö ba danö, irugi tanö ba Gasa; ma''ifu lö lasaigö gaurifa ba Ndraono Gizeraeli, ba he biri-biri ba he saŵi ba he kalide.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 5, 'La''ohe sa''ae guriföra ba osera, na möi ira miyaŵa, timba wa''oya wali, na so ira, ba he ya''ira, ba he ondra khöra, ba tebai ni''erai.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 6, 'Ba wamakiko möi ira ba danö. Ba tobali numana sibai Ndraono Gizeraeli, börö Ndraono Midiano andrö. Ba la''angaröfi li Yehowa Iraono Gizeraeli.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 7, 'Ba me mangarö-ngarö khö Yehowa Ndraono Gizeraeli, ba Ndraono Midiano andrö,', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 8, 'ba ifatenge ba Ndraono Gizeraeli zama''ele''ö Yehowa, ba imane khöra da''ö: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: No u''ohe miyaŵa ami, moroi ba danö Miserayi, no uheta ami ba nahia wa''asawuyu;', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 9, 'no u''efa''ö ami ba danga Ndrawa Miserayi, ba ba danga zamakao ya''ami fefu, ba no utimba ira fönami ba no ube''e khömi danöra.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 10, 'Ba no umane khömi: Yehowa ndra''o, Lowalangimi; böi mi''ata''ufi Lowalangi Ndraono Gamori andrö, si so ami ba danö. Ba lö''ö sa nifondrondrongomi ligu.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 11, 'Ba so mala''ika Yehowa andrö, mudadao ia ba mbörö manawa andrö, ba Gofera, banua Yo''asi andrö, ma''uwu Gabieseri. Ba samöbörö fakhe nono Yo''asi, Gideono, ba wolazi nagu, ba wangoloi''ö ya''ia, ba Ndraono Midiano andrö.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 12, 'Ba i''oroma''ö ia khönia mala''ika Yehowa andrö, imane khönia: Itolo''ö Yehowa, ya''ugö sabölö!', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 13, 'Ba imane khönia Gideono: He Tuha, na itologa Yehowa, ba hana sa wa göna ndra''aga da''ö fefu? Ba heza so dandra andrö khönia fefu, nidunö-dunö ndra tuama khöma, me lamane: Hadia, tenga no i''ohe miyaŵa ndra''aga Yehowa, moroi ba danö Miserayi? Ba iada''e, ba no i''erogö ita Yehowa ba no ibe''e ba danga Ndraono Midiano ita.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 14, 'Ba i''otahögö ia Yehowa, imane: Ae''e, ba wa''abölöu andrö, ba efa''ö Ndraono Gizeraeli ba danga Ndraono Midiano. Hadia, tenga ya''o zamatenge ya''ugö?[1]', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 15, 'Ba imane khönia; He Tuha, hadia ube''e fangefa''ö Ndraono Gizeraeli? Hiza, no fondrege zi numana ba mado Manase watalifusöta khöma, ba ya''odo, ba no fondrege zide-ide ba zi samba omo ndra amagu.[2]', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 16, 'Ba imane khönia Yehowa: Ya''o zanolo ya''ugö, ba ö''alani Ndraono Midiano, hulö na ha samösa niha.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 17, 'Ba imane khönia: Na no atö falukhado wa''ebua dödöu wamaigiu, ba lau khögu dandra, wa no ya''ugö zi fahuhuo khögu.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 18, 'Böi ofanö a''i, irege sodo, irege u''ohe baero game''elagu, ba wanou''ö tou fönau. Ba imane: U''agö da''e, irege mangawuli''ö.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 19, 'Ba möi miyomo Gideono, i''asiwai nono nambi ba kue si lö mu''aisöni, ösi zi samba yöu hamo. Ösi nono nambi andrö, ba ibe''e ba gude, ba dinonia, ba ilau ba mbowoa, ba i''ohe baero khönia, ba mbörö manawa itou''ö tou fönania.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 20, 'Ba imane khönia mala''ika Lowalangi andrö: Halö nambi andrö, awö kue andrö, si lö mu''aisöni, ba tou''ö tou ba dete gowe andre, ba dino andrö, ba faduwa. Ba i''o''ö da''ö.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 21, 'Ba i''oro''ö mbalö zi''onia, si so ba dangania, mala''ika Yehowa andrö, ituko nambi andrö ba kue andrö, si lö mu''aisöni, ba alua galitö ba gowe andrö ba i''a nambi, awö kue andrö, si lö mu''aisöni. Ba taya mala''ika Yohowa andrö, lö''ö sa''ae oroma khönia.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 22, 'Awena i''ila Gideono, wa no mala''ika Yehowa. Ba imane Gideono: Alai ndra''o, So''aya, Yehowa, me no fa''ila bawa ndra''o ba mala''ika Yehowa![3]', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 23, 'Ba imane khönia Yehowa: Ya''ohahau dödöu! böi ata''ufi, lö mate''ö!', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 24, 'Ba ifa''anö naha wame''e sumange ba da''ö Gideono ba ibe''e töinia "fangorifi Yehowa". Ba irugi ma''ökhö, ba lö tebulö ba da''ö, ba Gofera, banua ma''uwu Gabieseri.', '["Heb 11:32","MozII 3:11","MozI 16:13; MozII 33:20; Faigi 13:22"]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 25, 'Ba ba zi bongi andrö, ba imane khönia Yehowa: Ohe niha, dafulu, sawuyumö, ba saŵi si matua, si mewitu fakhe; ba dudugö naha wame''e sumange khö Mba''ali khö namau, ba Asera andrö, ba ngainia, ba eŵa.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 26, 'Ba khö Lowalangiu, Yehowa fa''anö naha wame''e sumange ba zuzu hati andre, ba asiwai. Ba halö zaŵi andrö, si sageu, ba be''e sumange nitunu; eu Gasera andrö, ni''eŵamö dania, be''e fanunu.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 27, 'Ba dafulu, i''ohe niha Gideono, sawuyunia, ba i''o''ö niŵa''ö Yehowa khönia. Ba me ata''u ia ndra amania ba banuara ilau ba zi ma''ökhö, andrö wa ba zi bongi ilau.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 28, 'Ba me maoso mbanuara, si hulö wongi, ba hiza, ba no mududugö naha wame''e sumange andrö khö Mba''ali, ba Asera andrö ba ngainia, ba no mu''eŵa, ba saŵi andrö, si sageu, ba no mube''e sumange ba naha wame''e sumange andrö, nifa''anö andrö.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 29, 'Ba faoma lamane khö nawöra: Ha niha zolau da''ö? Ba la''alu-alui ba lazofu-zofu ba lamane: Gideono, ono Yo''asi zolau da''ö.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 30, 'Ba lamane banuara khö Yo''asi: Da khöma nonou andrö, ba wamunu ya''ia, me no idudugö naha wame''e sumange andrö khö Mba''ali ba me no i''eŵa Gasera andrö, ba ngainia.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 31, 'Ba imane Yo''asi khöra fefu, si so ba da''ö khonia: Hadia, ya''ami zamatunö huhuo Mba''ali andrö; ya''ami zangorifi ya''ia? Ha niha zamatunö ya''ia, ba nibunu irege mahemolu mbanua. Na Lowalangi ia, ba yamufatunö huhuonia, me no ladudugö naha wame''e sumange andrö khönia.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 32, 'Ba me luo da''ö, ba labe''e töi Gideono Yerubi-Mba''ali, lamane: Yamufatunö huhuonia khönia Ba''ali, me no idudugö naha wame''e sumange andrö khönia.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 33, 'Ba la''owuloi ira dozi Iraono Midiano ba Iraono Gamaleki, awö zowanua ba gatumbukha luo, dozi manö ira, ba la''ötö Yoridano ba tebato ba ndraso andrö, ba Yezere''eli.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 34, 'Ba so Geheha Yehowa khö Gideono, ba ilau dorofe fogaoni ma''uwu Gabieseri, ba wefao khönia.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 35, 'Ba ifatenge zinenge ba mado Manase fefu, ba tefakaoni''ö ira göi, ba wefao khönia. Ba he ba mado Gaseri ba ba mado Zebuloni ba ba mado Nafetali, ba ifatenge göi. Ba möi ira miyaŵa, lafaondragö.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 36, 'Ba imane Gideono khö Lowalangi: Na omasi''ö ö''efa''ö Ndraono Gizeraeli tangagu andre, si mane niŵa''öu —', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 37, 'ba hiza, ubologö ba golayama mbasitö mbu mbiri-biri niguti; ba na ha bu mbiri-biri andrö zonamo, ba na otufo danö ma''afefu, ba aboto ba dödögu, ö''orifi Ndraono Gizeraeli tangagu andre, itörö niŵa''öu.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 38, 'Ba itörö. Ba mahemolu ö, ba ihulö wongi wemaoso, ifera''ö mbu mbiri-biri andrö, namo andrö, samba figa nidanö.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 39, 'Ba imane Gideono khö Lowalangi: Böi ofönu khögu, ba hatö samuza tö muhededo. Hatö samuza tö utandraigö ba mbu mbiri-biri andrö. Ya''otufo mbu mbiri-biri, ha ya''ia, ba yamonamo danö ma''afefu.', '[]', NULL),
  (3474655, 'OT', 'Sanguhuku', 6, 40, 'Ba i''o''ö khönia da''ö Lowalangi, ba zi bongi andrö, ha bu mbiri-biri zotufo, ba no monamo danö fefu.', '[]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 1, 'Ba ihulö wongi wemaoso Yerubi-Mba''ali, ya''ia Gideono, i''ohe niha andrö fefu, si fao khönia; ba ba zinga gumbu Harodi molombase ira. Ba no yöunia golombaseŵa Ndraono Midiano, i''otarai hili More, ba ndraso misa.', '["MozV 20:8"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 2, 'Ba imane Yehowa khö Gideono: Abölö ato niha andrö, si fao khöu, tebai ube''e ba dangara Ndraono Midiano andrö, ma dania lasuno ira khögu Iraono Gizeraeli, ma lamane: Tangama wangorifima!', '["MozV 20:8"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 3, 'Ba ao, farongogö ba zato, ömane: Ha niha zata''u ba satalö tödö, ba yamufuli ia, yamuheta ia ba hili Gileadi! Ba 22,000 zangawuli niha, tobali hatö 10,000 zi tosai.[1]', '["MozV 20:8"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 4, 'Ba imane Yehowa khö Gideono: Töra zui na niha; ohe mitou ira ba mbewe nidanö, ena''ö uföfö''ö ira ba da''ö. Ba niŵa''ögu khöu dania: Da''ö zi fao khöu, ba fao, ba dozi niŵa''ögu khöu: Böi fao da''ö, ba lö möi.', '["MozV 20:8"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 5, 'Ba i''ohe mitou ira ba mbewe nidanö. Ba imane Yehowa khö Gideono: Dozi samelai idanö lelara, nifamelai nasu, ba oniagö, ba si manö göi dozi samalöduhini tanö, ba we''amadugö tanga.', '["MozV 20:8"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 6, 'Ba fa''ato zamelai idanö, ba no 300; ba tanö bö''ö fefu, ba no samalöduhini tanö, ba wamadu idanö.', '["MozV 20:8"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 7, 'Ba imane Yehowa khö Gideono: Si tölu ngaotu niha andrö, samelai idanö, ube''e sangorifi ya''ami, da''ö u''oguna''ö ba wame''e ba dangau Iraono Midiano andrö; ba tanö bö''ö fefu, ba ndra mofanö, yamufuli ia khöra zamösana.', '["MozV 20:8"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 8, 'Ba lahalö mbalazo andrö khöra, awö dorofe khöra; ba Iraono Gizeraeli bö''ö fefu, ba iföfanö, hana na ifuli ia khöra zamösana, ha si 300 isaigö khönia. Ba olombaseŵa Ndraono Midiano, ba no tounia, ba Ndraso.', '["MozV 20:8"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 9, 'Ba ba zi bongi andrö, ba imane khönia Yehowa: Faoso, misaŵa golombaseŵa, tou andrö, noa sa ube''e ba dangau ia!', '[]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 10, 'Ba na ata''u''ö möi mitou, ba ohe ngoni-ngoniu andrö, Fura andrö, ba mi''ae mitou ba zinga golombaseŵa,', '[]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 11, 'ba fondrongondrongo, hadia niŵa''ö-ŵa''ö ba da''ö, ba abe''e dödöu dania, ba wanaŵa olombaseŵa. Ba i''ohe ngoni-ngoninia Fura andrö, möi ira mitou, lahatö''ö sibai ira ba zanuwö andrö, ba golombaseŵa.', '[]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 12, 'No orudu ba da''ö, ba ndraso, Ndraono Midiano andrö ba Iraono Gamaleki ba si oroi danö tanö ba gatumbukha luo, fa''oya wali wa''atora, ba ondra khöra, ba lö mutaha mu''erai, fa''oya ngawua nene ba mbewe nasi wa''oya.', '[]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 13, 'Ba me no ahatö Gideono, ba hiza zanunö khö nawönia fangifinia, imane: No mangifi ndra''o: U''ila roti gandru, si tegaölö mitou ba golombaseŵa Ndraono Midiano, irugi nose zalaŵa, göna ba da''ö, ba aso''a nose, tobali arö ibe''e [roti andrö], ba tou ba danö so nose.', '[]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 14, 'Ba itema linia si samösa, imane: Tenga bö''ö da''ö, no si''öli Ndraono Gizeraeli andrö, si''öli Gideono andrö, ono Yo''asi. No ibe''e ba dangania Ndraono Midiano, fabaya olombaseŵa ma''afefu, Lowalangi.', '[]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 15, 'Ba me no irongo Gideono nitunö Ndraono Midiano andrö, fangifi andrö, ba eluahania, ba mangalulu ia; ba ifuli ia ba golombaseŵa Ndraono Gizeraeli, mu''ao ia, imane: Talabu! noa sa''ae ibe''e ba dangami golombaseŵa Ndraono Midiano.', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 16, 'Ba i''otölu zi 300 niha andrö, tölu bawa ibe''e, ba idozigö ira torofe, awö migö si lö ösi, ba dangara; ba bakha ba migö andrö, ba sulu.', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 17, 'Ba imane khöra: Mifaigi ndra''o ba mi''o''ö khögu; na no urugi zinga golombaseŵa, ba milau nilaugu.', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 18, 'Na ulau dorofe, awö zi fao khögu fefu, ba ya''ami göi molau torofe ba zi fasui olombaseŵa fefu, ba mu''ao ami, mimane: Föda khö Yehowa, föda Gideono!', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 19, 'Ba irugi zinga golombaseŵa Gideono awönia zi otu andrö, si fao khönia, me talu mbongi, me awena sibai lafataro zanaro, ba lalau dorofe ba laboto migö andrö ba dangara, ba tölu bawa manö,', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 20, 'ba molau torofe, laboto migö, ba latuyu tangara kabera zulu, ba ba gambölö, ba torofe, ba wolau, ba mu''ao ira, lamane: Föda khö Yehowa, föda Gideono!', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 21, 'Ba lö ibulö''ö ia ba nahania zamösana, ba zi fasui olombaseŵa. Ba mu''awa manö ba golombaseŵa ma''afefu, ba moloi, mu''ira-ira.', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 22, 'Ba me lalau dorofe si tölu ngaotu andrö, ba faoma la''ö''ötö nawöra [Iraono Midiano] ba golombaseŵa ma''afefu, ibe''e Yehowa, ba moloi zi so ba golombaseŵa, larugi Mbeti Hasita, tanö ba Zereda, irugi mbewe nidanö ba Habeli Mehola, ba zinga Dabata.[2]', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 23, 'Ba tekaoni göi Ndraono Gizeraeli, mado Nafetali ba mado Gaseri ba mado Manase ma''afefu, ba lagohi Ndraono Midiano.', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 24, 'Ba ifatenge göi zinenge Gideono ba hili mado Geferayi ma''asambua, ifaŵa''ögö khöra [ba da''ö]: Mi''ae mitou, mifaondragö Ndraono Midiano andrö ba miba''a khöra götöna ba nidanö misa ba ba Yoridano! Ba so mado Geferayi fefu, laba''a götöna ba nidanö misa, irugi Mbeti Bara ba ötöna ba Yoridano.', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474656, 'OT', 'Sanguhuku', 7, 25, 'Ba lara''u zalaŵa Ndraono Midiano andrö, si darua, Orebi ba Sebi, ba ba gowe Gorebi labunu Gorebi ba Sebi, ba ba wolazi Zebi. Ba lagohi Ndraono Midiano. Ba bögö ndra Orebi Sebi andrö, ba la''ohe khö Gideono, miyefo Yoridano.[3]', '["Sin 83:10","Yes 10:26"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 1, 'Ba lamane khönia mado Geferayi: Hana wa ömanö khöma, wa lö muhede''ö khöma? No ha ya''ugö zi möi fasuwö ba Ndraono Midiano andrö! ba fasoso sibai ira khönia.[1]', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 2, 'Ba imane khöra: Hadia sa nilaugu, timba nilaumi? Tenga no ebua wo''uwo''u ni''ozaragö mado Geferayi, moroi ba mbua khö Gabiezeri mege?', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 3, 'Ba dangami ibe''e zalaŵa Ndraono Midiano andrö, Orebi ba Sebi, Lowalangi. Ba hadia nilaugu timba nilaumi? Ba me iŵa''ö da''ö, ba alö wönura khönia.', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 4, 'Ba me no irugi Yoridano Gideono ba me no i''ötö, awö zi tölu ngaotu andrö, si fao khönia, ba si no erege tödö wolohi [emali andrö],', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 5, 'ba mangandrö ia ba mbanua Zukota, imane: Mibe''e kue ba niha andre, ni''ohegu, no erege dödöra; solohi salaŵa Ndraono Midiano andrö, Seba ba Salamuna, ndra''odo.', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 6, 'Ba lamane salaŵa mbanua: Hadia, no so ba dangau gokhö ndra Seba Salamuna, wa mabe''e kue ba zabölö andrö khöu?', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 7, 'Ba imane Gideono: Lau, na ibe''e ba dangagu ndra Seba Salamuna Yehowa, ba ufufu nösimi doi manaze nihalö ba danö si mate.', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 8, 'Ba moroi ba da''ö isaŵa Wenieli, ba imanö göi khöra. Ba lamanö göi khönia banua Wenieli, si mane banua Zukota mege.', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 9, 'Ba imane göi ba mbanua Wenieli andrö: Na mangawulido lö hadia ia khögu, ba ududugö hati andre!', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 10, 'Ba ba Garakoro so ndra Seba Salamuna, awö zanuwö andrö khöra, mato 15,000 niha, dozi si tosai sanuwö andrö, soroi ba gatumbukha luo; ba si no mate, ba no 120,000, oi solohe si''öli.', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 11, 'Ba itörö lala zikoli Gideono, tanö ba gatumbukha i''otarai Noba ba Yogebeha, ba ihawui golombaseŵa, me no ahono manö tou zanuwö andrö.', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 12, 'Ba moloi ndra Seba Salamuna; ba igohi ira ba ira''u zalaŵa Ndraono Midiano andrö si darua, Seba ba Salamuna, ba sanuwö andrö fefu, ba zumaewe ibe''e.[2]', '["Faigi 12:1","Sin 83:12"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 13, 'Ba mangawuli Gideono, ono Yo''asi, me no irugi lala miyaŵa ba Heresi, ibato wolohi ya''ira.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 14, 'Ba ira''u zamösa, nono matua, banua Zukota no mege, ba isekhegö, ba iŵa''ö khönia wanura töi zalaŵa Zukota ba satua mbanua, 77 niha.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 15, 'Ba me irugi mbanua Zukota, ba imane: Ya''e ndra Seba Salamuna, nibe''emi börö wango''aya ya''odo, me mimane: Hadia no so ba dangau sa''ae gokhö ndra Seba Salamuna, wa mabe''e kue ba nawöu andrö, si no erege tödö?', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 16, 'Ba ihalö zalaŵa mbanua andrö ba ituyu ndraha manaze sodoi, ifabözi''ö mbanua Zukota andrö.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 17, 'Ba hati andrö, ba Wenieli, ba idudugö, ba ibunu tou mbanuara andrö.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 18, 'Ba isofu khö ndra Seba Salamuna, imane: He wisa nga''eu niha andrö, nibunumi ba gahe hili Dabora? Ba lamane: Adölö si mane ya''ugö ira göi; dozi ira, ba ono zalaŵa wamaigida!', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 19, 'Ba imane: No talifusögu, iraono ninagu. Ba wa''aduhu wa''auri Yehowa: ena''ö na no mi''orifi ira, ba lö ubunu ami!', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 20, 'Ba imane khö nononia si a''a, Yetero: Labu, ö''ötö ira! Ba lö isöbi zi''öli ono matua andrö, ata''u, me iraono na ia.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 21, 'Ba lamane ira Seba Salamuna: Faoso, ya''ugö andrö, ba bunuga! he wisa niha sa, si manö göi wa''abölönia. Ba maoso Gideono, i''ö''ötö ndra Seba Salamuna. Ba ihalö khönia ni''obaŵa andrö, side-ide, aya gondrara ba mbagi.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474657, 'OT', 'Sanguhuku', 8, 22, 'Ba lamane khö Gideono Iraono Gizeraeli: Iagö salaŵama, he ya''ugö, ba he onou dania, ba he ma''uwumö! me no ya''ugö zangefa''ö ya''aga ba danga Ndraono Midiano.', '["MozII 32:2","MozII 28:6"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 23, 'Ba imane khöra Gideono: Lö möiga salaŵami he ya''odo, ba he onogu dania, Yehowa zalaŵami!', '["MozII 32:2","MozII 28:6"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 24, 'Ba imane na khöra Gideono: So ni''andrögu khömi ma''ifu: Mibe''e khögu dauge andrö, ahuluami mege, dozi ami. (Me ma''uwu Zima''eli zanuwö andrö, ba no si so dauge)', '["MozII 32:2","MozII 28:6"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 25, 'Ba lamane: Mabe''e khöu da''ö saoha gölöma! Ba labologö tou mbaru sebua, ba dozi latou''ö tou ba da''ö dauge andrö, ahuluara mege.[3]', '["MozII 32:2","MozII 28:6"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 26, 'Ba fa''abua dauge ana''a andrö, ni''andrönia khönia, ba no 1700 fondruyu, lö lai ni''obaŵa andrö ba saeru dalinga ba baru luo, baru zalaŵa Ndraono Midiano, ba lö lai naya gondrara andrö, aya ba mbagi.', '["MozII 32:2","MozII 28:6"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 27, 'Ba ibali''ö adu Gideono ba ibe''e ba mbanuara Ofera. Ba mamosumange adu andrö Ndraono Gizeraeli fefu, ba tobali tandraŵa khö Gideono ba ba zoroiyomonia fefu.[4]', '["MozII 32:2","MozII 28:6"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 28, 'Ba tobali lahöndrögö Ndraono Midiano Iraono Gizeraeli, tobali tebai sa''ae maoso. Öfa wulu fakhe wa''ara, ba lö hadia ia ba danöra, götö wa''anau noso Gideono.', '["MozII 32:2","MozII 28:6"]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 29, 'Ba ifuli ia ba khöra Yerubi-Mba''ali andrö, ono Yo''asi, ba nomonia soso sa''ae ia.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 30, 'Ba 70 ngafulu nono matua khö Gideono, si ndruhu nononia, me no oya ndrongania.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 31, 'Ba dongania ba döi andrö, banua Zikhema, ba mo''ono göi khönia, ono matua, ba Abimelekhi ibe''e töi nono da''ö.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 32, 'Ba mate Gideono andrö, ono Yo''asi, no atua sibai, ba lako''o ia ba lewatö namania Yo''asi andrö, ba Gofera, banua ma''uwu Gabiezeri.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 33, 'Ba me no mate Gideono ba lafosumange zui Mba''ali Iraono Gizeraeli, labe''e Lowalangira Mba''ali Mberiti andrö.', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 34, 'Ba lö itörö tödö Ndraono Gizeraeli Lowalangira Yehowa, si no mangefa''ö ya''ira ba danga nemalira fefu si tefasui ya''ira;', '[]', NULL),
  (3474657, 'OT', 'Sanguhuku', 8, 35, 'ba lö''ö göi la''omasi''ö nga''ötö Yerubi-Mba''ali Gideono andrö, timba zi sökhi andrö, nilaunia ba Ndraono Gizeraeli, mena''ö.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 1, 'Ba möi ba Zikhema, khö ndra sibayania, Gabimelekhi andrö, ono Yerubi-Mba''ali ba imane khöra ba ba nuwunia fefu:', '["RazII 11:2","Yos 24:26"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 2, 'Misofu sibai ba mbanua Zikhema fefu, mimane: He zohahau dödömi, na fitu ngafulu, iraono Yerubi-Mba''ali andrö fefu, zalaŵami, ba ma na ha samösa zamatörö ya''ami? Ba böi göi olifu ami, wa no föfömi ndra''odo!', '["RazII 11:2","Yos 24:26"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 3, 'Ba fahuhuo sibai ndra sibayania andrö ba mbanua Zikhema fefu, ba khönia, dali manö niŵa''önia andrö, ba tobali adöni dödöra khö Gabimelekhi; lamane sa: No ono mbene''öda.', '["RazII 11:2","Yos 24:26"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 4, 'Ba labe''e khönia gana''a, fitu ngafulu rufia, nihalö ba gosali Mba''ali Mberiti andrö; ba ibe''e luo niha si si lö yaŵa, si lö ngaroro, Abimelekhi, ba ya''ia zolohe ya''ira.', '["RazII 11:2","Yos 24:26"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 5, 'Ba möi ia ba gödo namania, ba Gofera, ba ibunu ndra talifusönia andrö, ono Yerubi-Mba''ali, fitu ngafulu niha, ha sambua tete kara naha wamunu ya''ira. Hatö ono Yerubi-Mba''ali si akhi, Yotamo, zi tosai, me no ibini''ö ia.[1]', '["RazII 11:2","Yos 24:26"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 6, 'Ba falukha mbanua Zikhema fefu, awö nösi Milo andrö, möi ira mamataro razo Abimelekhi andrö ba mbörö manawa ba harefa andrö, ba ngai Zikhema.[2]', '["RazII 11:2","Yos 24:26"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 7, 'Ba me terongo da''ö khö Yotamo, ba möi ia ba hili Garisi, i''iagö zuzu hili, ba mu''ao ia khöra, imane: Mifondrondrongo khögu, ya''ami, banua Zikhema, ena''ö ifondrondrongo limi Lowalangi!', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 8, 'Möi döla geu me föna, ba wamayoini khöra razo; ba lamane ba döla zai: Iagö razoma![3]', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 9, 'Ba imane khöra töla zai: Hadia, uböhöi wa''amofanikha andrö khögu, ba nisuno Lowalangi ya''o, awö niha, ba möido manaha-nahae yaŵa hogu geu bö''ö?', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 10, 'Ba lamane ba döla ara töla geu andrö: Tabu, ya''ugö iagö razoma!', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 11, 'Ba imane töla ara: Hadia uböhöi wa''amigu andrö ba buagu si sökhi sibai, ba möido manaha-nahae yaŵa hogu geu bö''ö?', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 12, 'Ba lamane ba ŵeŵe nagu töla geu andrö: Ba tabu, ya''ugö iagö razoma!', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 13, 'Ba imane khöra agu: Hadia, uböhöi nösigu andrö, somuso dödö Lowalangi ba tödö niha, ba möido manaha-nahae yaŵa hogu geu bö''ö?[4]', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 14, 'Ba lamane ba manaze töla geu andrö fefu: Ba tabu, ya''ugö iagö razoma!', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 15, 'Ba imane manaze ba döla geu andrö: Na moroi ba dödömi mibayoini razomi ndra''odo, ba mifaigi khömi nahia ba lumögu! Ba na tenga da''ö, ba alitö dania zi otarai manaze andre, ba i''a geresi ba hili Libano!', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 16, 'Ba lau, na satulö nilaumi ba na sadölö, me no mibali''ö razo Gabimelekhi andrö, na si sökhi nilaumi khö Yerubi-Mba''ali ba ba nga''ötönia, ba na no misulöni khönia nilaunia ba khömi andrö, ya''ami andrö,', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 17, 'si no möi belebele namagu ba wasuwöta, ba nibelegönia nosonia, ni''efa''önia ba danga Ndraono Midiano, ba ya''ami,', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 18, 'ba no milaŵa nga''ötö namagu ma''ökhö; ononia andrö, fitu ngafulu niha, ba no mibunu, ha sambua tete gara naha wamunu ya''ira, ba no mibali''ö razo mbanua Zikhema Gabimelekhi andrö, ono zawuyu namagu, me no ono mbene''ömi —', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 19, 'ba na no atö satulö ba sadölö nilaumi khö Yerubi-Mba''ali ba ba nga''ötönia, ba mi''omusoi''ö dödömi ba khö Gabimelekhi andrö ba yamu''omusoi''ö dödönia ba khömi.', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 20, 'Ba na tenga da''ö, ba alitö yamu''otarai Gabimelekhi, ba yamu''a mbanua Zikhema, fabaya ösi Milo andrö, ba yamu''otarai göi mbanua Zikhema ba ösi Milo andrö alitö, ba yamu''a Gabimelekhi!', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 21, 'Ba moloi Yotamo, ba irugi Mbe''eri ba woloinia andrö; ba da''ö i''iagö; lö ikhamö ia ga''ania Abimelekhi.', '["RazII 14:9","Sin 104:15"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 22, 'Ba me no medölu fakhe razo Ndraono Gizeraeli Gabimelekhi,', '["SamII 15:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 23, 'ba ifatörö mbekhu wa''udusa khö Gabimelekhi ba ba mbanua Zikhema Lowalangi, ba tobali fabali khö Gabimelekhi mbanua Zikhema,', '["SamII 15:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 24, 'ena''ö tesulöni horöra andrö ba ndraono Yerubi-Mba''ali andrö si fitu ngafulu, ba ena''ö tohare ba nono mbene''öra Abimelekhi, samunu ya''ira, ndrora andrö, ba ba mbanua Zikhema, si no manolo ya''ia ba wamunu talifusönia, ibe''e [Lowalangi].', '["SamII 15:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 25, 'Ba lafatenge niha, udunia, banua Zikhema, niha samini''ö ya''ira ba zuzu hili, niha sorabu, gofu ha niha zanörö lala. Ba te''ombakha''ö da''ö khö Gabimelekhi.', '["SamII 15:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 26, 'Ba so Ga''ali, ono Yobeli ba talifusönia; lasaŵa Zikhema ba tobali faduhu dödö mbanua Zikhema khönia.', '["SamII 15:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 27, 'Ba möi ira ba danö, la''ozaragö mbua nagu ba lalazi, ba owulo ira, ba wangandrö saoha gölö, möi ira ba gosali Lowalangira, manga ira ba mamadu agu ba la''eli''elifi Gabimelekhi.', '["SamII 15:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 28, 'Ba imane Ga''ali, ono Yobeli: Ha niha Gabimelekhi, ha niha nono Yerubi-Mba''ali andrö, wa tafondrondrongo linia? Tenga banua Zikhema ia ba tenga kumandrunia Zebuli andrö? Ba hana na ifondrondrongo khönia, awö nga''ötö Hemori andrö, furugö mbanua Zikhema. Ba ya''ita, ba hadia wa ta''o''ö khönia?', '["SamII 15:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 29, 'Ena''ö na ya''o zalaŵa niha andre, ba utimba Gabimelekhi ba umane khönia: Oya''ö zabölö khöu ba labu![5]', '["SamII 15:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 30, 'Ba me terongo khö Zebuli andrö, kumandru mbanua, wehede Ga''ali andrö, ono Yobeli, ba mofönu ia,', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 31, 'ba i''onekhesi wamatenge sinenge khö Gabimelekhi, imane khönia: Hiza, no möi ba Zikhema Ga''ali andrö, ono Yobeli, awö dalifusönia andrö, ba molaŵa khöu mbanua labe''e!', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 32, 'Ba faoso, ya''ugö, awö niha andrö, si fao-fao khöu, mitörö bongi ba mibini''ö ami ba mbenua;', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 33, 'ba ba zanguhulö wongi, na tumbu luo, ba faoso, ba mihawui mbanua; ba na ifaondragö ndra''ugö, awö zi fao khönia andrö, ba lau khönia zenahöi ndra''ugö.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 34, 'Ba maoso Gabimelekhi, awö zabölö andrö fefu, si fao khönia, ba zi bongi, ba labini''ö ira ba gamaudu Zikhema, öfa bawa.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 35, 'Ba me so Ga''ali andrö, ono Yobeli, me itörö mbawa göli, we''amöi baero, ba maoso Gabimelekhi, awö zi fao khönia, laröi mbini-mbini andrö khöra.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 36, 'Ba i''ila zanuwö andrö Ga''ali ba imane khö Zebuli: Hiza zanuwö moroi yaŵa ba zuzu hili! Ba imane khönia Sebuli: Öbali niha lumö hili!', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 37, 'Ba ifuli imane Ga''ali: Si ndruhu, sanuwö zi otarai wusö danö mitou ba sambawa zi otarai manawa zebua elemu andrö!', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 38, 'Ba imane khönia Sebuli: Ba heza so wa''abe''e mbawa andrö, me ömane: Ha niha Gabimelekhi andrö, wa tafondrondrongo linia? Da''ö zabölö andrö, si lö ba dödöu mege! Ba labu ba lau fasöndra khöra!', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 39, 'Ba föna mbanua Zikhema Ga''ali we''amöi. Ba fasöndra ira khö Gabimelekhi.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 40, 'Ba moloi ira ibe''e Abimelekhi ba ato zi mate, irugi fönaföna mbawa göli mbanua.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 41, 'Ba ba Garuma soso Gabimelekhi, fatua itimba Ga''ali ba talifusönia Sebuli; tobal tebai sa''ae la''iagö Zikhema.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 42, 'Ba mahemolu ö, ba milo mbanua Zikhema, lahulö wöngi. Ba te''ombakha''ö khö Gabimelekhi.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 43, 'Ba i''ohe zabölö andrö khönia, ifotölu bawa, ba labini''ö ira ba mbenua. Ba me i''ila, möi ba danö mbanua Zikhema, ba ifaondragö ba ilau khöra.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 44, 'Ba ya''ia [Abimelekhi], awö zi sambawa andrö, si fao khönia, ba möi mitou, la''iagö föna mbawa göli, fatua lalau ba zi so baero ba mbenua fefu si dombua bawa andrö, fatua labunu tou.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 45, 'Ba awena ilau ba mbanua Abimelekhi, ma''öma''ökhö, ba atu''a ia bakha; ba ösi mbanua ba la''ö''ötö, ba banua ba ladudugö, ba lafazaewe nasio ba nahania.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 46, 'Ba me larongo da''ö si so ba hati andrö ba Zikhema, fefu, ba möi ira yaŵa ba zi sagötö ba gosali Lowalangi Mberiti andrö khöra.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 47, 'Ba me te''ombakha''ö khö Gabimelekhi: No owulo fefu nösi hati andrö ba Zikhema!', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 48, 'ba möi yaŵa ba hili Zalomono andrö Gabimelekhi, awö zabölö andrö fefu, si fao khönia. Ba ituyu wato Abimelekhi, i''eŵa ndraha geu, ba ihalö ba i''angalisigö. Ba iŵa''ö ba zabölo andrö, si fao khönia: Hadia ni''ilami nilaugu, ba mita''i-ta''i mi''o''ö!', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 49, 'Ba dozi la''eŵa göi ndraha geu awönia andrö, ba la''o''ö Gabimelekhi, ba latibö''ö ba gosali [ndraha geu andrö], latunu gosali, ba tobali ahori mate nösi zi hulö hati andrö ba Zikhema — mato 1.000 niha, ira matua ba ira alawe.', '[]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 50, 'Ba möi ba Debesi Gabimelekhi, lafasui ba atu''a ira.', '["SamII 11:21","SamI 31:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 51, 'Ba ba dalu mbanua bakha, ba so zi hulö hati; ba da''ö lasaŵa ösi mbanua fefu, ira matua ba ira alawe. La''aro''ö mbawandruhö furira ba möi ira yaŵa ba lote ba hati andrö.', '["SamII 11:21","SamI 31:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 52, 'Ba so Gabimelekhi, ba wanudugö hati andrö. Ba me ihatö''ö ia ba mbawandruhönia, ba wanunu ya''ia,', '["SamII 11:21","SamI 31:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 53, 'ba ifazaumba ba högö Gabimelekhi gara gisa wakhe ira alawe, moroi yaŵa, aboto högönia ibe''e.[6]', '["SamII 11:21","SamI 31:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 54, 'Ba igösö muhede khö ngoni-ngoninia, solohe fangönania, imane khönia: Söbi zi''öliu ba falua bunudo, fa böi laŵa''ö dania: Nibunu ndra alawe! Ba itaru''ö khönia zi''öli ngoni-ngoninia andrö, ba mate ia.[7]', '["SamII 11:21","SamI 31:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 55, 'Ba me la''ila Iraono Gizeraeli, no mate Gabimelekhi, ba ifuli ia khöra zamösana.', '["SamII 11:21","SamI 31:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 56, 'Si manö wamasulöni Lowalangi horö Gabimelekhi andrö, horönia khö namania, me ibunu dalifusönia andrö, si fitu ngafulu,', '["SamII 11:21","SamI 31:4"]', NULL),
  (3474658, 'OT', 'Sanguhuku', 9, 57, 'ba he horö mbanua Zikhema andrö fefu, ba ihare''ö ba högöra Lowalangi. Ba tobali itörö ba khöra wangelifi Yotamo andrö, ono Yerubi-Mba''ali.', '["SamII 11:21","SamI 31:4"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 1, 'Furi Gabimelekhi andrö, ba maoso Dola, ono Wua, ma''uwu Dodo, mado Isasari, ba wangorifi Iraono Gizeraeli. Banuania Zamiri, ba hili mado Geferayi.', '["MozIV 32:41"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 2, 'Dua wulu a tölu fakhe wa''ara sanguhuku Iraono Gizeraeli ia, ba mate ia ba ba Zamiri lako''o.', '["MozIV 32:41"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 3, 'Ba furinia, ba maoso Ya''iro, banua Gileadi, ba 22 fakhe wanguhukunia Iraono Gizeraeli Tölu ngafulu nononia matua,', '["MozIV 32:41"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 4, 'si fakudo ba nono galide, tölu ngafulu, ba tölu ngafulu khöra mbanua, halama soya khö Ya''iro döi, irugi ma''ökhö, ba danö Gileadi.', '["MozIV 32:41"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 5, 'Ba mate Ya''iro andrö, ba ba Gamono lako''o.[1]', '["MozIV 32:41"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 6, 'Ba lafuli lalau zi fatuwu khö Yehowa Iraono Gizeraeli, lafosumange Mba''ali ba Asaroti andrö, ba adu Ndrawa Garamo andrö ba adu Zidona ba adu Ndraono Moabi ba adu Ndraono Gamoni, ba adu Ndrawa Wilisiti, ba la''erogö Yehowa ba lö lafosumange.[2]', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 7, 'Ba mofönu Yehowa ba Ndraono Gizeraeli, ba i''amawa ira, ibe''e ba danga Ndrawa Wilisiti ba ba danga Ndraono Gamoni.', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 8, 'Da''ö zamakao Iraono Gizeraeli ba sanguhundragö ya''ira, me luo da''ö, ba meweleŵalu fakhe dania, dozi Iraono Gizeraeli yefo Yoridano, ba danö Ndraono Gamori andrö, ba danö Gileadi.', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 9, 'Ba la''ötö göi Yoridano Iraono Gamoni, ba wolau ba mado Yuda göi ba ba mado Mbeniyami ba ba ma''uwu Geferayi, tobali abu sibai dödö Ndraono Gizeraeli.', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 10, 'Ba la''angaröfi li Yehowa Iraono Gizeraeli, lamane: Horöma khöu, wa no ma''erogö Lowalangima, awö wa no mafosumange Mba''ali andrö!', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 11, 'Ba imane Yehowa ba Ndraono Gizeraeli: Hadia, tenga no lafakao göi ami Dawa Miserayi ba Iraono Gamori ba Iraono Gamoni ba Dawa Wilisiti,', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 12, 'ba banua Zidona ba Iraono Gamaleki ba Iraono Midiano, ba mi''angaröfi li ndra''o, ba u''efa''ö ami ba dangara?', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 13, 'Ba ya''ami, ba no mi''erogö ndra''o ba no mifosumange Lowalangi bö''ö. Andrö wa lö''ö sa''ae edönado u''orifi ami.[3]', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 14, 'Mi ae mi''angaröfi li Lowalangi andrö, nitutuyumi khömi! Hana na ya''ira zangorifi ya''ami, na tosasa ami!', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 15, 'Ba lamane Iraono Gizeraeli khö Yehowa: Horöma; hadia zomasi''ö ba lau khöma, ha fa ö''orifi ndra''aga iya''e!', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 16, 'Ba latibo''ö nadu niha baero andrö, laheta ba mbanuara, ba lafosumange Yehowa. Ba ahakhö dödönia wamakao Ndraono Gizeraeli andrö.[4]', '["Faigi 2:13","Yer 2:13","MozI 35:2; MozII 3:7"]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 17, 'Ba so Ndraono Gamoni, la''iagö danö Gileadi. Ba möi göi Ndraono Gizeraeli, ba ba ngai Misefa la''iagö.', '[]', NULL),
  (3474659, 'OT', 'Sanguhuku', 10, 18, 'Ba faoma lamane khö nawöra salaŵa Gileadi: Ha niha zi börötaigö fasöndra ba Ndraono Gamoni andrö? Da''ö dania nibe''e salaŵa mbanua Gileadi fefu!', '[]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 1, 'Niha sabölö Yefita andrö, banua Gileadi, ba no ono horö ia. Gileadi nama Yefita andrö.[1]', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 2, 'Ba me mo''ono ndronga Gileadi khönia, ono matua, ba me itugu ebua ndraono ndrongania andrö, ba latimba Yefita, lamane khönia: Tebai manema ondröita dania ndra''ugö moroi yomo khöma, me no ono ndra alawe bö''ö ndra''ugö.[2]', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 3, 'Ba moloi Yefita labe''e talifusönia andrö, i''iagö danö Tobi. Ba la''ondrasi ia niha si lö ngaroro, fao-fao ira khönia.[3]', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 4, 'Ba lö ara, ba labörötaigö lasuwö-suwö Ndraono Gizeraeli Iraono Gamoni.', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 5, 'Ba me labörötaigö manuwö Iraono Gizeraeli Iraono Gamoni, ba maoso zalaŵa ba danö Gileadi, möi ira muhalö Yefita, ba danö Tobi.', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 6, 'Lamane khö Yefita: Tabu, iagö solohe ya''aga, ba talau fasuwö ba Ndraono Gamoni andrö!', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 7, 'Ba imane Yefita ba zalaŵa Gileadi: Hadia, tenga si fatiu ami khögu ba tenga sanimba ya''odo baomo namagu ami? Ba hana wa möi ami khögu, na abu dödömi?', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 8, 'Ba lamane khö Yefita salaŵa Gileadi: Hiza, mafuli möi khöu, ba na möi''ö awöma ba wasuwöta ba Ndraono Gamoni andrö, ba mahalö högöma ndra''ugö, dozi banua ba danö Gileadi.', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 9, 'Ba imane Yefita ba zalaŵa Gileadi andrö: Na mihalö mangawuli ndra''odo, ba wasuwöta andrö ba Ndraono Gamoni, ba na ibe''e ba dangagu ira Yehowa, ba högömi ndra''odo!', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 10, 'Ba lamane khö Yefita salaŵa Gileadi andrö: Yamufondrongondrongo khöda Yehowa, na lö ma''o''ö niŵa''öu andrö.', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 11, 'Ba fao Yefita ba zalaŵa Gileadi andrö, ba lafataro ia högöra ba solohe ya''ira sato. Ba i''ombakha''ö khö Yehowa ba Misefa fefu hadia ia zi so ba dödönia Yefita.', '["Heb 11:32","MozI 21:10","SamI 22:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474660, 'OT', 'Sanguhuku', 11, 12, 'Ba ifatenge zinenge Yefita khö razo Ndraono Gamoni, imane khönia: Hadia nihalöu khögu, wa so''ö moroi sa khögu, ba wanuwö banuagu?', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 13, 'Ba imane razo Ndraono Gamoni ba zinenge Yefita: No lahalö khöra danögu Iraono Gizeraeli, me la''otarai danö Miserayi, i''otarai Garono numalö ba Yaboko ba irege mbewe Yoridano: ba fuli khögu, saoha gölöu!', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 14, 'Ba ifuli ifatenge zinenge Yefita khö razo Ndraono Gamoni, ena''ö lamane khönia:', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 15, 'Da''ö niŵa''ö Yefita: Lö nihalö Ndraono Gizeraeli tanö Ndraono Moabi ba tanö Ndraono Gamoni.[4]', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 16, 'Me la''otarai danö Miserayi Iraono Gizeraeli, me no latörö danö si mate, irugi nasi zukhu ba irugi Gadesi,', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 17, 'ba lafatenge zinenge Iraono Gizeraeli khö razo Ndraono Gedomo, lamane: Tehe khönia wanörö tanöu! Ba lö itehe razo Ndraono Gedomo. Ba lafatenge göi khö razo Ndraono Moabi ba te khönia. Ba la''iagö Gadesi Iraono Gizeraeli.[5]', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 18, 'Ba latörö danö si mate, lahene danö Ndraono Gedomo ba tanö Ndraono Moabi ba larugi danö tanö ba gatumbukha luo, i''otarai danö Ndraono Moabi andrö, ba yefo Garono molombase ira, lö lahundragö danö Ndraono Moabi; ola Ndraono Moabi sa Garono andrö.', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 19, 'Ba lafatenge zinenge Iraono Gizeraeli khö razo Ndraono Gamori Sihona andrö, razo ba Hesibona, lamane khönia Iraono Gizeraeli: Tehe khöma wanörö tanöu, ba we''amöi ba danöma![6]', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 20, 'Ba mamaudu dödö Zihona ba Ndraono Gizeraeli, lö itehe khöra wanörö tanönia, i''owuloi zabölö khönia fefu, ba zinga Yasa la''iagö, ba lalau ba Ndraono Gizeraeli:', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 21, 'Ba ibe''e ba danga Ndraono Gizeraeli Zihona, fabaya banuania fefu, Yehowa, Lowalangi Ndraono Gizeraeli; möna Ndraono Gizeraeli ba lahalö khöra danö Ndraono Gamori andrö, si so ba danö andrö, ma''asagörö.', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 22, 'Tobali la''okhögö danö Ndraono Gamori andrö, ma''afefu, i''otarai Garono numalö ba Yaboko, ba i''otarai danö si mate, numalö ba mbewe Yoridano.', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 23, 'Ba hiza, no itimba Ndraono Gamori andrö föna mbanuania Iraono Gizeraeli Lowalangi Ndraono Gizeraeli andrö, Yehowa, ba hadia, ya''ugö zangai tana khöra?', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 24, 'Hadia, na so nituturu Lowalangiu Kamosi andrö khöu, ba hadia, lö öhalö? ba ha niha göi nitimba Lowalangima, Yehowa, fönama, da''ö nihalöma si so khönia.', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 25, 'Ba hadia, no si sökhi ndra''ugö, moroi khö Mbalaki andrö, ono Zifori, razo Ndraono Moabi? Hadia, no irai ifadöni hadia ia ba Ndraono Gizeraeli ba no irai fasuwö khöra?[7]', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 26, 'Götö wa no ahono Ndraono Gizeraeli ba Hesibona ba ba mbanua si faböbö khöra ba ba Garoeri ba ba zi faböbö ba da''ö, mumalö ba mbanua fatambai Garono, no 300 fakhe wa''ara, ba hana wa lö mi''okhögö barö ö?', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 27, 'Ya''odo, ba lö nifakaogu ya''ugö, ba si lö atulö ölau khögu, wanuwö ya''odo: Yohowa andrö, sanguhuku, ba yamu''asiwai huhuo Ndraono Gizeraeli ba Ndraono Gamoni.', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 28, 'Ba razo Ndraono Gamoni andrö, ba lö ifondrondrongo nifaŵa''ögö Yefita khönia.', '["MozIV 21:13 b.t.; MozV 2:9. 19; Yos 13:25","MozIV 20:17","MozIV 21:21 b.t.","MozIV 22:2"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 29, 'Ba so Geheha Yehowa khö Yefita, ba itörö danö Gileadi ba tanö mado Manase, isaŵa Misefa ba danö Gileadi, ba moroi ba Misefa ba danö Gileadi i''otarai we''amöi fasuwö ba Ndraono Gamoni.', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 30, 'Ba ifabu''u linia khö Yehowa Yefita, imane: Na si ndruhu öbe''e ba dangagu Ndraono Gamoni andrö,', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 31, 'ba khö Yehowa zi föföna mamaondragö ya''o baewali khögu, na mangawulido moroi ba Ndraono Gamoni lö hadia ia, ba ube''e sumange nitunu.', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 32, 'Ba möi fasuwö ba Ndraono Gamoni Yefita, ba wolau khöra, ba ibe''e ba dangania ira Yehowa.', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 33, 'Abölö sibai te''ala ira ibe''e, i''otarai Garoeri, irugi Miniti,', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 34, 'Ba me irugi nomonia ba Misefa Yefita, ba möi sibai tou nononia alawe, ibözi waritia ba manari. Awai nononia, ha si sambua andröi; lö ononia bö''ö, he ono matua, ba he ono alawe.[8]', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 35, 'Ba me i''ila ia, ba itika nukhania, imane: Alai ndra''o ndra''ugö onogu! Abu sibai dödögu öbe''e; ya''ugö sibai zolohe ba wamakao ya''odo. Noa sa numalö ligu khö Yehowa, ba tebai ufuli!', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 36, 'Ba imane khönia: He ama, na no numalö liu khö Yehowa, ba lau khögu niŵa''öu andrö. Noa sa atö ibe''e Yehowa, ö''ila ölau mbalöu ba nemaliu andrö, Iraono Gamoni.', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 37, 'Ba i''andrö khö namania: Sambalö tehe khögu: dua waŵa wa''ara böhölido, ena''ö möido misa ba hili ba wange''esi fa''ono''alawe andrö khögu, ya''odo ba awögu ono alawe.', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 38, 'Ba imane khönia: Ba ae''e! ba dua waŵa itehe khönia. Ba möi ia ba fao khönia nawönia ono alawe, ba ba hili i''e''esi wa''ono''alawenia.', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 39, 'Ba me no irugi dua waŵa, ba ifuli ia khö namania, ba ifatörö khönia gamabu''ula linia andrö. Ba no lö irai orudu khönia ndra matua. Ba tobali huku ba Ndraono Gizeraeli:', '["MozII 15:20"]', NULL),
  (3474660, 'OT', 'Sanguhuku', 11, 40, 'Ero röfi möi nono Ndraono Gizeraeli alawe, ba wanuno ono Yefita andrö, banua Gileadi, öfa''öfa ngaluo wa''ara.', '["MozII 15:20"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 1, 'Ba owulo mado Geferayi, möi ira ba Zafono ba lamane khö Yefita: Hana wa möi''ö manö fasuwö ba Ndraono Gamoni ba lö sihede''ö khöma, ena''ö faoga khöu? Damatunu nomou si so''ö yomo![1]', '["Faigi 8:1","Mat 26:73"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 2, 'Ba imane khöra Yefita: Fagua-gua sibai mege ndra''aga ba Ndraono Gamoni andrö, ya''odo ba banuagu, ba u''angaröfi li ami, ba lö''ö sa mi''efa''ö ndra''o ba dangara.', '["Faigi 8:1","Mat 26:73"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 3, 'Ba me u''ila, lö edöna mitolo ndra''o, ba ubelegö nosogu, möido fasuwö ba Ndraono Gamoni ba ibe''e ba dangagu ira Yehowa. Ba hadia wa möi ami khogu ma''ökhö, ba wolau khögu?', '["Faigi 8:1","Mat 26:73"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 4, 'Ba ifakaoni''ö mbanua Gileadi fefu Yefita, ba ilau ba mado Geferayi, ba te''ala sibai mado Geferayi, labe''e banua Gileadi andrö. Noa sa lamane: Mado Geferayi soloi ami: Si te''u''u ba danö mado Geferayi Gileadi andrö ba ba danö mado Manase.', '["Faigi 8:1","Mat 26:73"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 5, 'Ba laba''a götöna ba Yoridano banua Gileadi, tanö ba mado Geferayi. Ba na so zoloi andrö, mado Geferayi, na mu''ao: Mifolala ndra''o miyefo! ba lamane khönia banua Gileadi: Hadia, mado Geferayi ndra''ugö? Ba na imane: Tenga!', '["Faigi 8:1","Mat 26:73"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 6, 'ba lamane khönia: Ŵa''ö: Skhibolet! ba na imane: Sibolet! na lö itörö tödönia, i''atulö''ö wanötöi, ba lara''u ia ba la''ö''ötö ia ba da''ö ba götöna andrö ba Yoridano. Tobali 42,000 zi mate mado Geferayi, me luo da''ö.[2]', '["Faigi 8:1","Mat 26:73"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 7, 'Ba meönö fakhe ihuku Ndraono Gizeraeli Yefita andrö. Aefa da''ö, ba mate Yefita, banua Gileadi, ba ba mbanua Gileadi lako''o ia.', '["Faigi 8:1","Mat 26:73"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 8, 'Ba furinia, ba Ebesana banua Mbetilekhema zanguhuku Iraono Gizeraeli.', '["Faigi 10:4","Faigi 5:14"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 9, 'Tölu ngafulu nononia matua, ba tölu ngafulu nono alawe nibe''enia nihalö ba mbanua baero ba tölu ngafulu ihalö khö nononia matua ono alawe mbanua bö''ö. Mewitu fakhe ihuku Ndraono Gizeraeli;', '["Faigi 10:4","Faigi 5:14"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 10, 'aefa da''ö, ba mate Gebesana ba ba Mbetilekhema lako''o.', '["Faigi 10:4","Faigi 5:14"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 11, 'Ba furinia, ba Elono, mado Zebuloni zanguhuku Iraono Gizeraeli, mewulu fakhe.', '["Faigi 10:4","Faigi 5:14"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 12, 'Ba aefa da''ö, ba mate Gelono andrö, mado Zebuloni, ba ba Nayalona, ba danö mado Zebuloni, lako''o ia.', '["Faigi 10:4","Faigi 5:14"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 13, 'Ba furi da''ö, ba Abedono, ono Hileli, banua Wiratono, zanguhuku Iraono Gizeraeli.', '["Faigi 10:4","Faigi 5:14"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 14, 'Öfa wulu nononia matua ba tölu ngafulu ma''uwunia, si fakudo ba hulu nono galide, fitu ngafulu nga''eu. Meŵalu fakhe ihuku Ndraono Gizeraeli.[3]', '["Faigi 10:4","Faigi 5:14"]', NULL),
  (3474661, 'OT', 'Sanguhuku', 12, 15, 'Aefa da''o, ba mate Gabedono andrö, benua Wiratono, ono Hileli, ba ba Wiratono lako''o ia, ba danö mado Geferayi, ba hili Ndraono Gamaleki andrö.[4]', '["Faigi 10:4","Faigi 5:14"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 1, 'Ba lalau zui zi fatuwu khö Yehowa Iraono Gizeraeli; ba ibe''e ba danga Ndrawa Wilisiti ira Yehowa, öfa wulu fakhe wa''ara.', '["MozIV 6:3","SamI 1:11","Luk 1:13 b.t."]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 2, 'Ba so niha, banua Zorea, mado Dano, Manoa döi, ba dongania, ba si lö ono, lö irai mo''ono.', '["MozIV 6:3","SamI 1:11","Luk 1:13 b.t."]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 3, 'Ba i''oroma''ö ia ba ndra alawe andrö mala''ika Yehowa andrö, imane khönia: Hiza sa, si lö ono ndra''ugö, lö örai mo''ono, ba manabina dania ndra''ugö ba mo''ono''ö, ono matua.', '["MozIV 6:3","SamI 1:11","Luk 1:13 b.t."]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 4, 'Ba amoni''ö, böi badu nagu ba he hadia ia zi mabu niha, ba böi a hadia ia zi ra''iö.[1]', '["MozIV 6:3","SamI 1:11","Luk 1:13 b.t."]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 5, 'Ba manabina dania ndra''ugö ba mo''ono''ö ono matua; ba lö tola dania lafatörö wanöwö ba högö nono andrö, me ni''amoni''ö khö Yehowa dania ia, i''otarai dalu ninania, ba ya''ia zi börögö dania mangefa''ö Iraono Gizeraeli ba danga Ndrawa Wilisiti.[2]', '["MozIV 6:3","SamI 1:11","Luk 1:13 b.t."]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 6, 'Ba möi ndra alawe andrö, itunö khö ndrongania, imane: No möi khögu genoni Lowalangi; hulö mala''ika Lowalangi wamaigigu, — sata''u sibai ita, ba lö nisofugu khönia heza moroi ia, ba töinia, ba lö ni''ombakha''önia khögu.', '["MozIV 6:3","SamI 1:11","Luk 1:13 b.t."]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 7, 'Ba imane khögu: Na manabina dania ndra''ugö ba na mo''ono''ö, ono matua, ba böi badu nagu ba he hadia ia zi mabu niha, ba böi a hadia ia zi ra''iö, me ni''amoni''ö khö Lowalangi dania nono andrö, i''otarai dalu ninania, numalö ba wa''amatenia.[3]', '["MozIV 6:3","SamI 1:11","Luk 1:13 b.t."]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 8, 'Ba mangandrö Manoa khö Yehowa, imane: He So''aya! Ena''ö na ifuli ia khöma enoni Lowalangi andrö, nifatengemö, ba ena''ö na ifahaö ndra''aga, he mawisa ba khö nono andrö, si tumbu dania!', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 9, 'Ba i''o''ö khö Manoa Lowalangi, tobali ifuli ia ba ndra alawe andrö mala''ika Lowalangi andrö, me no dumadao ia ba nowi, lö ira matuania, Manoa.', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 10, 'Ba fagohi ndra alawe andrö, i''ombakha''ö khö ndrongania, imane: Hiza, no ifuli i''oroma''ö ia khögu niha andrö, si no möi khögu bohou na!', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 11, 'Ba maoso Manoa, i''o''ö ndrongania, ba me irugi zi so niha andrö, ba imane khönia: Hadia, ya''ugö niha andrö si fahuhuo ba ndra alawe andre? Ba imane: Ya''ia!', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 12, 'Ba imane Manoa: Ba na itörö niŵa''öu andrö, ba he mawisa ba nono andrö, he wisa lala?', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 13, 'Ba imane mala''ika Yehowa khö Manoa: Fefu hadia ia niŵa''ögu ba ndra alawe andre, ba lö ibabaya.', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 14, 'Ma''ifu manö lö tola i''a hadia ia zi otarai ŵeŵe nagu; agu ba hadia ia zi mabu niha, ba lö tola ibadu, ba hadia ia zi ra''iö, ba lö tola i''a: fefu hadia ia niŵa''ögu khönia, ba itöngöni.', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 15, 'Ba imane Manoa khö mala''ika Yehowa andrö: Omasiga mataha''ö ba mabe''e öu nono nambi.', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 16, 'Ba imane mala''ika Yehowa khö Manoa: Ba he ŵa''ae ötahado ena''ö, ba lö''ö sa atö u''a wöfö göu; ba na edöna''ö ö''asiwai zumange nitunu, ba khö Yehowa tandrösaigö. Lö''ö sa i''ila Manoa wa no mala''ika Yehowa andrö.', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 17, 'Ba imane Manoa khö mala''ika Yehowa andrö: Ha niha döimö? Na itörö dania niŵa''öu, ba mafosumange ndra''ugö.', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 18, 'Ba imane khönia mala''ika Yehowa: Hadia wa osofu döigu? — noa sa atö sahöli-höli dödö![4]', '["MozI 32:29; MozII 3:13; Yes 9:6"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 19, 'Ba ihalö nono nambi andrö Manoa, fabaya sumange ni''a andrö, ibe''e sumange Yehowa, ba dete gara. Ba hiza zahöli-höli dödö, anehe Manoa ba dongania.', '["MozII 33:20; Faigi 6:23","Heb 11:32"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 20, 'Me ebua miyaŵa ba mbanua hola-hola galitö ba naha wame''e sumange, ba numalö miyaŵa mala''ika Yehowa andrö ba hola-hola galitö andrö ba naha wame''e sumange. Ba me la''ila da''ö Manoa ba dongania, ba lafalögu tou ira ba danö.', '["MozII 33:20; Faigi 6:23","Heb 11:32"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 21, 'Ba lö''ö sa''ae i''oroma''ö ia khö Manoa ba khö ndrongania mala''ika Yehowa andrö. Ba aboto ba dödö Manoa, wa no mala''ika Yehowa.', '["MozII 33:20; Faigi 6:23","Heb 11:32"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 22, 'Ba imane Manoa khö ndrongania: Si mate ita, me no ta''ila Lowalangi![5]', '["MozII 33:20; Faigi 6:23","Heb 11:32"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 23, 'Imane khönia dongania: Na nilau dödö Yehowa ibunu ita, ba lö itema mena''ö khöda zumange nitunu ba sumange ni''a, ba lö i''oroma''ö khöda da''ö fefu ba lö ifarongogö khöda zi mane da''ö.', '["MozII 33:20; Faigi 6:23","Heb 11:32"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 24, 'Ba mo''ono ndra alawe andrö, ono matua, ba Simesono ibe''e töi; ba manöi nono andrö ba ifahuwu''ö ia Yehowa.[6]', '["MozII 33:20; Faigi 6:23","Heb 11:32"]', NULL),
  (3474662, 'OT', 'Sanguhuku', 13, 25, 'Ba ibörötaigö i''o''ou ia Eheha Yehowa ba golombaseŵa mado Dano andrö, ba gotaluara Zorea Gesa''oli.', '["MozII 33:20; Faigi 6:23","Heb 11:32"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 1, 'Ba möi misi tou ba Dimenata Zimesono, ba i''ila ba da''ö nono alawe, Dawa Wilisiti, ba Dimenata andrö.', '["MozV 7:3"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 2, 'Ba ifuli ia misi yaŵa manutunö da''ö khö ndra amania, imane: No u''ila nono alawe, Dawa Wilisiti, ba Dimenata, mitehe khögu wangai ya''ia.', '["MozV 7:3"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 3, 'Ba lamane khönia ira amania: Hadia lö''ö sa''ae ira alawe ba nono dalifusöu, ba niwada fefu, wa ba niha baero, ba Ndrawa Wilisiti andrö, ba niha si lö muboto, öhalö khöu? Ba imane Simesono khö namania: Da''ö be''e khögu, omasido![1]', '["MozV 7:3"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 4, 'Ba lö''ö sa aboto ba dödö ndra amania, wa moroi ba Lowalangi da''ö, me sangalui börö ia, ba Ndrawa Wilisiti. Me luo da''ö, ba Dawa Wilisiti zamatörö Iraono Gizeraeli.', '["MozV 7:3"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 5, 'Ba möi ba Dimenata Zimesono, awö ndra amania inania. Ba me larugi kabu nagu mbanua Dimetata andrö, ba faondra khönia nono zingo, si lö mudöna-döna, mundröndrö-ndröndrö.', '["SamI 17:35"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 6, 'Ba so khönia Geheha Yehowa, ba isasawi nono zingo andrö, nifanasawi ono nambi, ba lö''ö sa hadia ia ba dangania. Ba lö''ö sa i''ombakha''ö khö ndra amania nilaunia andrö.[2]', '["SamI 17:35"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 7, 'Ba möi mitou ia, fahuhuo ia khö nono alawe andrö ba faduhu dödö Zimesono khönia.', '["SamI 17:35"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 8, 'Ba lö ara, ba ifuli möi, ba wangai ya''ia. Ba möi ia ba zinga lala, ba wamaigi amatela zingo no mege, ba hiza ŵani ba gamatela zingo andrö, ba mo''ösi.', '["SamI 17:35"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 9, 'Ba ilau ba lalu''ania ba ifelai barö wowaö-waönia andrö. Ba me fakhamö ia khö ndra amania, ba ibe''e öra ösa, ba lö''ö sa i''ombakha''ö, wa ba gamatela zingo andrö mege ihalö ŵe ŵani andrö.', '["SamI 17:35"]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 10, 'Ba möi misi tou khö nono alawe andrö namania, ba ilau walöŵa ba da''ö Zimesono, si manö sa huku ba nono matua.', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 11, 'Ba me ata''u ira Zimesono, ba tölu ngafulu labe''e awönia niha, si lö aefa-aefa khönia.', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 12, 'Ba imane ba da''ö Simesono: Da''uŵa''ö khömi dahö-dahö. Na misöndra geluaha barö zi fitu bongi walöŵa andre, na mi''ila miŵa''ö, ba tölu ngafulu ube''e khömi kameza ba tölu ngafulu baru ba walöŵa,', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 13, 'ba na tebai misöndra khögu, ba ya''ami zame''e khögu, tölu ngafulu gameza ba tölu ngafulu mbaru luo. Ba lamane khönia: Ŵa''ö dahö-dahö andrö khöu, ena''ö marongo.', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 14, 'Ba imane khöra: Ö, si otarai zi manga ba sami, si otarai zabölö. Ba tölu bongi wa''ara ba lö lasöndra geluaha dahö-dahö andrö.', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 15, 'Ba mahemolu ö, ba la''andrö khö ndronga Zimesono, lamane: Ŵa''ö khö wo''omou andrö, ena''ö i''ombakha''ö khöma geluaha dahö-dahö andrö, ba na lö ötologa, ba masului ndra''ugö, fabaya si samba omo ndra amau. Te ba wanganumana ya''aga mikaoni ndra''aga!', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 16, 'Ba mege-ege ndronga Zimesono khönia, imane: Ha sambalö fa''abua gölöu khögu, ba tenga fa''omasi; no öŵa''ö ba dalifusögu dahö-dahö ba lö ni''ombakha''öu khögu! Ba imane khönia: Ba khö namagu ba khö ninagu, ba lö ni''ombakha''ögu, ba u''ombakha''ö khöu!', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 17, 'Ba mege-ege ia khönia, irege no alua zi fitu bongi andrö, götö mbongi walöŵa andrö. Ba me luo si fitu andrö, ba i''ombakha''ö khönia, me no iforege sibai khönia. Ba ya''ia zangombakha eluaha dahö-dahö andrö ba dalifusöra.', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 18, 'Me luo si fitu andrö, ba la''ombakha''ö khönia banua da''ö, gasa-gasa wa möi ia si bakha khö ndrongania, lamane: Hadia zami moroi ba ŵe ŵani, ba hadia zabölö moroi ba zingo? Ba imane khöra: Na lö mifake mena''ö nono zaŵi khögu, ba wanguhundra laza khömi, ba lö''ö sa misöndra mena''ö geluaha dahö-dahö andrö khögu!', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 19, 'Ba so khönia Geheha Yehowa ba möi ia misi tou ba Gasekalo, ba tölu ngafulu ibunu niha, banuara. Ba ihalö nukhara ba ibe''e ba zanöndra eluaha dahö-dahö andrö khönia mbaru andrö, baru ba walöŵa. Ba mofönu sibai ia, ba ifuli ia misi yaŵa khö namania.', '[]', NULL),
  (3474663, 'OT', 'Sanguhuku', 14, 20, 'Ba donga Zimesono andrö, ba tebe''e khö nawönia, nihalönia khönia awö fao.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 1, 'Ba lö ara furi ö, me baŵa wamasi gandru, ba so Zimesono, i''ohe nono nambi, möi ia mufaigi ndrongania andrö, imane: Mifa''amöido si bakha khö ndrongagu! Ba lö ifa''amöi ia amania matuania.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 2, 'Imane sa amania andrö: Uwai sabua ölö ndra''ugö khönia, ba no ube''e khö nawöu andrö; ba si sökhi moroi khönia na''i nakhinia andrö: hana na khöu da''ö, fangalinia.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 3, 'Ba imane khöra Simesono: Si samuza andre, ba lö horögu ba Ndrawa Wilisiti andrö, na ulau khöra hadia ia!', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 4, 'Ba maoso Zimesono, möi mondra''u asu gatua, tölu ngaotu rozi, ba ihalö zulu, ba ifaböbö gi''o nasu gatua andrö, dua-dua rozi, ba sara-sara ibe''e sulu ba gotalua gi''o andrö, si dua-dua rozi.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 5, 'Ba itunu zulu andrö, ba ifoloi nasu gatua, ba mbasitö Ndrawa Wilisiti, ba akhozi zi no mulau ba ngamböbö, fabaya si lö mutaba na ibe''e, awö kabu zai.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 6, 'Ba me lasofu Dawa Wilisiti: Haniha zolau da''ö? ba lamane: Simesono andrö, umönö mbanua Dimenata andrö, — me no ibe''e ba niha bö''ö ndrongania [amania andrö]! Ba so Ndrawa Wilisiti, ba lasului galawe andrö, awö namania.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 7, 'Ba imane khöra Simesono: Na milau zi mane da''ö, ba lö ahono dödögu, irege no ulau mbalögu khömi!', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 8, 'Ba iforege iböbözi ira, afatö waha ba sola. Ba möi misi tou ia, i''iagö dögi narö gara, ba Getama.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 9, 'Ba so moroi sa Ndrawa Wilisiti ba ba danö mado Yuda tebato ira, ba lahawui Lehi.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 10, 'Ba me lasofu mado Yuda: Hadia wa möi ami khöma? ba lamane: Ba wondra''u Simesono andrö soga, ba wolau khönia nilaunia khöma.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 11, 'Ba 3000 zi möi mitou mado Yuda, ba dögi narö gara andrö ba Getama, ba mu''ao ira khö Zimesono, lamane: Hadia, lö ö''ila, wa no samatörö ya''ita Ndrawa Wilisiti? Ba hana sa, wa ölau khöma da''ö? Ba imane khöra:', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474664, 'OT', 'Sanguhuku', 15, 12, 'Nilaura khögu usulöni khöra. Ba lamane khönia: Ba wondra''u ya''ugö möiga, ba wame''e ba danga Ndrawa Wilisiti ya''ugö! Ba imane khöra Simesono: Ba mi''ae ba hölu khögu, wa tenga ya''ami zamunu ya''odo!', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 13, 'Ba lamane khönia: Tenga, ha ba wondra''u ya''ugö ba ba wame''e ba dangara ya''ugö — tenga samunu ya''ugö ndra''aga! Ba laböbö ia sinali si bohou, dua rozi, ba la''ohe miyaŵa ia, moroi ba narö gara andrö.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 14, 'Ba me irugi Lehi, me lakaraini sa''ae wa''iki Dawa Wilisiti, me no so ia, ba so khönia Geheha Yehowa, ba tobali hulö mbana, si no akhozi ba galitö wesu andrö ba nuwu gölönia ba timba zalau mböbö andrö ba mbagi mbulökhania.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 15, 'Ba i''ila tou döla zimbi galide, si bohou, ba ituyu, ba hönö ibunu niha töla zimbi andrö.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 16, 'Ba imane Simesono: "No uhaogö wanöwö ya''ira töla zimbi galide, hönö no ubunu niha töla zimbi galide andrö".', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 17, 'Ba me aefa iŵa''ö da''ö, ba itibo''ö döla zimbi andrö, ba labe''e töi naha andrö Ramata Lehi (hili zimbi).', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 18, 'Ba me no owökhi sibai dödönia, ba i''angaröfi li Yehowa, imane: No fangorifi sebua i''asogö tanga genoniu öbe''e — ba hadia, si mate owökhi dödö ndra''o iada''e, ba nilulu ba danga niha andrö, si lö muboto?', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 19, 'Ba ifobawa zahöndrö andrö ba Lehi Lowalangi, ba mangumbu moroi tou nidanö. Ba me no ibadu, ba te''ali nosonia, ifuli auri. Andrö wa labe''e töi gumbu andrö "umbu zi angaröfi li [Lowalangi]"; so ia, ba Lehi andrö, irugi ma''ökhö andre.', '[]', NULL),
  (3474664, 'OT', 'Sanguhuku', 15, 20, 'Ba 20 fakhe wa''ara ihuku Ndraono Gizeraeli Samesono, ba götö Ndrawa Wilisiti andrö.', '[]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 1, 'Ba möi ba Gasa Zimesono. Ba falukha ia ndra alawe sohorö-horö, ba da''ö, ba orudu ia khönia.', '[]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 2, 'Ba me terongo ba mbanua Gasa andrö, no möi ba da''ö Zimesono, ba lafa''u''u ia, sara wongi manö latarogö ba mbawa göli, lö nini-ninira, sara wongi, lamane dödöra: Na moluo dania, ba tabunu ia.', '[]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 3, 'Ba lö ibulö''ö ia Simesono, irugi talu mbongi. Ba me talu mbongi, ba maoso ia ba ituyu lagö mbawa göli andrö, dua görö, fabaya boha, si dua andrö, ifazaŵa, awö wolazi. I''osa''ö dalu ba i''ohe ba zuzu hili andrö, ba gamaudu Heberona.', '[]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 4, 'Ba aefa da''ö, ba omasi ia ndra alawe ba mbewe mbombo Soreki, Delila döi.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 5, 'Ba möi miyaŵa khö Delila andrö zalaŵa Ndrawa Wilisiti, ba lamane khönia: Tandraigö sofu khönia, ena''ö örongo hadia mbörö wa''abölönia andrö, ba he mawisa wolaŵa ya''ia, ena''ö maböbö ia ba ena''ö malaŵa, ba 1.100 rufia zamösa mabe''e khöu!', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 6, 'Ba isofu khö Zimesono Delila, imane: Ombakha''ö khögu, hadia mbörö wa''abölöu andrö ba hadia ena''ö mböbö, ba wolaŵa ya''ugö.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 7, 'Ba imane khönia Simesono: Na laböbö ena''ö ndra''o, fitu rozi sinali si bohou, sauri, ba amomo ndra''o, tobali si mane niha bö''ö.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 8, 'Ba la''ohe khönia salaŵa Ndrawa Wilisiti fitu rozi sinali si bohou, sauri, ba ibe''e böbönia.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 9, 'Ba no so si bakha niha, ni''oroi''ö Delila, sanaro. Ba me imane khönia: Hiza khöu Ndrawa Wilisiti, Simesono! Na i''etu''ö zinali no mege, nifangetu''ö gumigumi nukha, na no abölö ahatö ba galitö, — ba lö''ö sa aboto ba dödöra mbörö wa''abölönia.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 10, 'Ba imane Delila khö Zimesono: No ölimodo, faya niŵa''öu khögu! Ba ombakha''ö khögu iada''e, hadia zi göna böbö, ba wamöbö ya''ugö.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 11, 'Ba imane khönia: Na laböbö ndra''o sinali si bohou, si lö murai mu''oguna''ö ba halöŵö hadia ia, ba amomo ndra''o, tobali si mane niha bö''ö.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 12, 'Ba ihalö zinali si bohou, ibe''e böbönia, iböbö, ba imane khönia: Hiza khöu Ndrawa Wilisiti, Simesono! no so si bakha niha, sanaro. Ba i''etu''ö zinali andrö ba nuwu gölönia, hulö mbana.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 13, 'Ba imane khönia Delila: Ölimodo manö na, faya ölau khögu: ombakha''ö khögu, hadia zi göna böbö, ba wamöbö ya''ugö! Ba imane khönia: Na öfakhai ena''ö ba luze mbewewö, ni''ofitu fondrandra andre ba högögu,', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 14, 'ba na ö''aro''ö fangaronia andrö, ba amomo ndra''o, tobali si mane niha bö''ö. Ba me mörö Zimesono, ba ituyu ni''ofitu fondrandra andrö ba högönia Delila ba ifakhai ba luze mbewewö, ba i''aro''ö fangaronia andrö. Ba imane khönia: Hiza khöu Ndrawa Wilisiti, Simesono! Ba tokea ia, ba adeha wangaro andrö, fabaya luze mbewewö ibe''e.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 15, 'Ba imane khönia Delila: Hadia wa öŵa''ö: omasido ndra''ugö, me no fa''ero dödö khögu? No medölu ölimodo, ba lö ö''ombakha''ö khögu hadia mbörö wa''abölöu andrö!', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 16, 'Ba me lö ibatobato, me iforege manö ba me ifakao ia, irege omasi manö ia mate,', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 17, 'ba lö''ö manö sa''ae ibini''ö khönia zi duhu, imane khönia: Lö irai itörö högögu fanöwö, me no ni''amoni''ö khö Lowalangi ndra''odo, i''otarai dalu ninagu — na tetöwö ndra''o ena''ö, ba taya khögu wa''abölögu andrö; amomo ndra''o, tobali si mane niha bö''ö fefu.[1]', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 18, 'Ba me no aboto ba dödö Delila, lö''ö manö nibini''önia khönia si duhu, ba ifatenge, ifakaoni''ö zalaŵa Ndrawa Wilisiti, imane khöra: Lö tola lö möi ami zi samuza andre, noa sa ifaulugö wamokai khögu si duhu. Ba so zalaŵa Wilisiti andrö, la''ohe gana''a andrö.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 19, 'Ba ifaförö Zimesono, ba gahetania, ba muhede ia ba niha, sanöwö khönia ni''ofitu fondrandra andrö ba högönia. Ba itugu alö''alö wa''abölö, ba taya.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 20, 'Ba me imane zui: Hiza khöu Ndrawa Wilisiti, Simesono! ba me tokea ia, ba imane dödönia: Aefado sa atö, si mane mege göi, ha me uga sa''ae; u''ewegö ira — ba lö''ö sa i''ila, wa no aheta khönia Yehowa.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 21, 'Ba lara''u ia Dawa Wilisiti ba lakoe hörönia. Ba aefa da''ö, ba la''ohe misi tou ia ba Gasa, labe''e mbilagu töla, ba labe''e sokisa fakhe ia ba gurunga.', '["MozIV 6:5"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 22, 'Ba ibörötaigö ifuli anau mbunia, me no aefa latöwö ia.', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 23, 'Ba owulo Ndrawa Wilisiti, ba wame''e sumange sebua ba nadura Dagono andrö, ba wolau owasa, somuso dödöra, lamane: No ibe''e ba dangada nemalida Simesono andrö Lowalangida![2]', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 24, 'Ba me la''ila ia sato, ba lasuno Lowalangira andrö, lamane sa: Lowalangida andrö, ba no ibe''e ba dangada nemalida andrö, samakiko tanöda, si no mamubunu banuada, wa''ato sa''ae!', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 25, 'Ba me omuso sa''ae dodöra, ba lamane: Mitema mifahalö''ö Zimesono andrö, ena''ö ma''iki ita ibe''e! Ba lafahalö''ö Zimesono ba gurunga labe''e sama''iki ya''ira. Ba gotalua gehomo labe''e nahania.', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 26, 'Ba imane Simesono khö zawuyu andrö, solohe tangania: Böhöido, ena''ö utuyu gehomo andrö, fangabe''e nomo, ena''ö ube''e tendrotendrogu.', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 27, 'Ba no fahöna yomo niha, ira matua ba ira alawe; ba so göi zalaŵa Ndrawa Wilisiti fefu, ba mato 3.000 ba dete nomo yaŵa, ira matua ba ira alawe, samaigi-maigi me famaimai Zimesono.', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 28, 'Ba i''angaröfi li Yehowa Simesono, imane: He So''aya, Yehowa! törö tödöu ndra''o, ba abölö''ö ndra''o, hatö si samuza andre, ya''ugö, Lowalangi, ena''ö u''osamuzaigö wolau balö hörögu andre si dombua, ba Ndrawa Wilisiti andre!', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 29, 'Ba italagui gehomo andrö Simesono, ehomo si dua, ba dalu, fangabe''e nomo, sara ba dangania kambölö ba sara ba gabera, ba ilangögö.', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 30, 'Imane Simesono: Yagumate, awö Ndrawa Wilisiti andre! ba i''abölögö ifaöndrö ia, tobali adudu nomo, ilangö zalaŵa, fabaya sato fefu, si so yomo, ba ato zi mate nibununia ba wa''amatenia andrö, moroi ba nibununia ba götönia mege.', '["SamI 5:2"]', NULL),
  (3474665, 'OT', 'Sanguhuku', 16, 31, 'Ba so moroi si yaŵa ndra talifusöra, falifusöta fefu, la''ohe misi yaŵa mbotonia ba lako''o ba lewatö namania Manoa, ba gotaluara Zorea Esa''oli. No 20 fakhe wa''ara ihuku Ndraono Gizeraeli.', '["SamI 5:2"]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 1, 'Ba so ba hili mado Geferayi andrö niha, Mikha döinia;', '["MozI 31:19; MozIII 16:32; SamI 19:13"]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 2, 'ba imane niha da''ö khö ninania: Rufia andrö, si 1.100, si no taya khöu, ni''elifiu sanagö, ba zi so ya''o, ba hiza, khögu so rufia andrö, ya''o zangai: ba ufuli sa''ae khöu. Ba imane khönia inania: Ya''ahowu ndra''ugö khö Yehowa, onogu!', '["MozI 31:19; MozIII 16:32; SamI 19:13"]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 3, 'Ba ifuli khö ninania rufia andrö, si 1.100. Ba imane inania: Ube''e ni''amoni''ö khö Yehowa gana''a andrö, ululu khöu, ya''ugö onogu, ena''ö tebali''ö adu nifoe ba adu nifahele.', '["MozI 31:19; MozIII 16:32; SamI 19:13"]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 4, 'Ba ihalö zi 200 rufia inania, ibe''e khö duka gana''a ba ibali''ö adu nifoe ba adu nifahele. Ba tebe''e ba nomo Mikha.', '["MozI 31:19; MozIII 16:32; SamI 19:13"]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 5, 'Ba tobali so nahia Lowalangi khö Mikha andrö. Ba ifo''awö baru gere ba siraha, ba ifataro ere khönia nononia samösa.[1]', '["MozI 31:19; MozIII 16:32; SamI 19:13"]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 6, 'Me luo da''ö, ba lö razo samatörö Iraono Gizeraeli; ilau manö nikhoi dödönia zamösana.', '["MozI 31:19; MozIII 16:32; SamI 19:13"]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 7, 'Ba so nono matua ba Mbetilekhema Yuda, si so ba mado Yuda andrö, ono Lewi, si fatewu ba da''ö.', '[]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 8, 'Ba iheta ia ba Mbetilekhema Yuda, sate fatewu ia dania, ba irugi hili mado Geferayi, nomo Mikha andrö, ba itohugö wofanö dania ena''ö.', '[]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 9, 'Ba imane khönia Mikha: Heza ö''otarai? Ba imane: Ono Lewi ndra''o, u''oroi Mbetilekhema Yuda, sawu''a ndra''o, sate u''iagö dania.', '[]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 10, 'Ba imane khönia Mikha: Iagö khögu, amagu ba ere khögu, fulu rufia döfi ube''e khöu ba utaha nukhau ba balazou.', '[]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 11, 'Ba itehe ono Lewi andrö i''iagö ba niha andrö, ba hulö zi fadoro ononia khönia nono matua andrö.', '[]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 12, 'Ba ifataro nono Lewi andrö Mikha, tobali ere khönia nono matua andrö, ba yomo khö Mikha i''iagö.', '[]', NULL),
  (3474666, 'OT', 'Sanguhuku', 17, 13, 'Ba imane Mikha: Eaduhu sa''ae dödögu, ifahowu''ö ndra''o Yehowa, me no ere khögu nono Lewi andrö.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 1, 'Me luo da''ö, ba lö razo, samatörö Iraono Gizeraeli, ba la''alui khöra danö, saro khöra, mado Dano, me luo da''ö: irugi da''ö sa, ba lö mufakhoi khöra zi lö tebulö khöra, ba ngai mado Ndraono Gizeraeli bö''ö.[1]', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 2, 'Ba dalima lafatenge zabölö mado Dano, iwara, nitutuyu ba zato khöra, banua Zorea ba banua Esa''oli ba wamauze tanö, ba ba wangalu-ngalui, lamane khöra: Mi''ae mifaigi danö! Ba larugi hili mado Geferayi, nomo Mikha andrö, ba mörö ira ba da''ö.', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 3, 'Ba me so ira ba da''ö, me falukha ira zi so yomo khö Mikha, ba larongo li nono matua andrö, ono Lewi andrö, ba möi ira khönia, lamane khönia: Ha niha zolohe ya''ugö ba da''e? Hadia wa so''ö ba da''e, hadia halöŵöu?', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 4, 'Ba imane khöra: No isane khögu Mikha andrö; no i''oni ndra''o ba no tobali ere ndra''o khönia.', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 5, 'Ba lamane khönia: Tema sofu khö Lowalangi, ena''ö marongo, na mofozu we''amöima andre!', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 6, 'Ba imane khöra ere andrö: Mi''ae''e manö, böi mi''abusi tödö! Somasi Yehowa we''amöimi andre!', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 7, 'Ba mofanö niha andrö si dalima, ba larugi La''isi. Ba la''ila wa no sohahau tödö manö mbanua da''ö, amuata mbanua Zidona andrö, lö hadia ia khöra, lö fangabu dödö; lö hadia ia zambö ira ba danö, ba so''ana''a ira. Ba no aröu göi mbanua Zidona ba lö sangörö-ngörö khöra.', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 8, 'Ba lafuli ira ba niwara ba Zorea ba ba Esa''oli, lamane khöra: Hana wa no ahono-hono manö ami?', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 9, 'Talabu, tasuwö ira! Noa sa mafaigi danö, ba si ndruhu, sökhi sibai! Ba manufa na dödömi? Boi miradö ami, milabu, mi''ae''e, ba wangokhögö tanö andrö!', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 10, 'Ba na mirugi, ba no niha si lö fangabu dödö zi falukha ami, ba tanö andrö, ba no ebolo, fasui manö. Si ndruhu, Lowalangi zame''e ba dangami — banua ba zi lö ambö hadia ia zi so ba guli danö!', '["Faigi 1:34"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 11, 'Ba maoso mado Dano, banua da''ö, banua Zorea ba banua Esa''oli, 600, solohe baluse ba fangöna.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 12, 'Ba ba lalara andrö, ba molombase ira ba Giriati Yeari banua mado Yuda. Andrö wa labe''e töi naha andrö golombaseŵa mado Dano, iruge ma''ökhö andre, ba zi tambai Giriati Yeari andrö.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 13, 'Ba moroi ba da''ö lasaŵa hili mado Geferayi andrö, ba larugi nomo Mikha no mege.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 14, 'Ba humede zi dalima andrö, si no möi ba La''isi mege, ba wamauze tanö, lamane ba niwara andrö: Hadia, noa göi mirongo, wa so mbaru gere ba siraha ba adu nifoe ba adu nifahele ba nomo andre!', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 15, 'Ba mifaigi he miwisa! Ba lasaŵa da''ö, larugi nomo nono matua andrö, ono Lewi, omo Mikha andrö, ba lasofu khönia, na lö hadia ia khönia.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 16, 'Ba 600 niha, mado Dano andrö zombase''ö ba mbawa göli; oi si so fangöna.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 17, 'Ba möi miyomo zi dalima andrö, si möi mege, ba wamauze tanö, möi ira ba nomo, lahalö nadu andrö, fabaya baru gere ba siraha, awö nifahele andrö. Ba ba mbawa göli so gere andrö, awö zi 600 niha andrö, si so fangöna.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 18, 'Ba ba nomo Mikha möi da''ö no mege, lahalö nadu andrö, awö mbaru gere ba siraha, awö nifahele andrö. Ba isofu khöra ere andrö, imane:', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 19, 'Hana ami? Ba lamane khönia: Böi hede-hede! Okhö mbawau, tabu, iagö khöma amama ba ere khöma! Hadia zomasi''ö, na ere yomo ba zi ha samösa ndra''ugö, ba ma na ere zi sambua mado, ere zi sawu Iraono Gizeraeli?', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 20, 'Ba saboto ba dödö gere andrö da''ö, ba ihalö mbaru gere andrö, ba siraha ba adu nifoe, awö nifahele andrö ba möi ba hunö niha andrö ia.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 21, 'Ba mofanö sa''ae ira, ba labe''e fönara ndraono ba urifö ba hadia ia zebua böli.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 22, 'Ba ha si''ai aefa ira ba nomo Mikha ba aekhu niha andrö, si fahatö omo khö Mikha, ba lakhamö mado Dano andrö.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 23, 'Mu''ao ira khöra; ba labali''ö ira furi mado Dano, lamane khö Mikha: Hana ami, wa no aekhu ami?', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 24, 'Ba imane: Adu andrö nifazökhigu khögu, ba no mihalö, fabaya ere andrö, ba sofanö ami, ba hadia zi tosai khögu? Ba hadia wa misofu na:', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 25, 'Hana ndra''ugö? Ba lamane khönia mado Dano andrö: Böi sa''ae forongogö khöma hadia ia, ma dania lalau khöu sabao tödö, ba horöu na mate ndra''ugö, awö zi so khöu!', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 26, 'Ba lalau mofanö mado Dano andrö. Ba aboto ba dödö Mikha, wa no sabölö moroi khönia ira, ba ifuli ia khöra.', '[]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 27, 'Ba la''ohe nifazökhi Mikha andrö, fabaya ere andrö khönia, ba lasuwö La''isi, niha sahono-hono ba si lö fangabu dödö; la''ö''ötö tou ira, ba banua, ba latunu.', '["MozII 2:22"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 28, 'Lö sanolo ya''ira; Sidona andrö, ba no aröu, ba lö sangörö-ngörö khöra, ba ndraso ba ngai Mbeti Rehobo so mbanua andrö. Ba lafuli lataru''ö mbanua andrö [mado Dano] ba labali''ö banuara,', '["MozII 2:22"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 29, 'ba labe''e töi mbanua [göi] Dano, dali döi wurugöra Dano, ono Gizeraeli; föna, ba no La''isi döi mbanua andrö.', '["MozII 2:22"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 30, 'Ba labe''e adura nadu no mege mado Dano andrö, ba ere ba mado Dano andrö, ba Yonata, ono Gereso, ma''uwu Moze ba ononia, irugi aheta ba danö Ndraono Gizeraeli.[2]', '["MozII 2:22"]', NULL),
  (3474667, 'OT', 'Sanguhuku', 18, 31, 'Lafedadao khöra nadu andrö nifazökhi Mikha, götö wa''ara ba Zilo nose Lowalangi andrö.', '["MozII 2:22"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 1, 'Ba me luo da''ö — me lö razo samatörö Iraono Gizeraeli — ba so ba dalu hili mado Geferayi nono Lewi, samösa, si fatewu ba da''ö; ba ihalö nono alawe, banua Mbetilekhema Yuda, dongania ba döi.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 2, 'Ba mohorö ndra alawe andrö, baeronia, ba moloi khönia, isaŵa ndra namania ba Mbetilekhema Yuda, ba öfa waŵa ia ba da''ö.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 3, 'Ba maoso ndra matuania andrö, möi fahuhuo khönia, ba wolohe mangawuli ya''ia; i''ohe zawuyunia samösa ba dua geu galide. Ba me irugi khöra, me i''ila ia ama galawe andrö, ba omuso dödönia, me no so ia.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 4, 'Ira''u dangania matuania, ama galawe andrö, i''ohe yomo, ba tölu bonginia khönia. Manga ira ba mörö ba da''ö.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 5, 'Ba me aefa zi tölu bongi andrö, me lahulö wongi wemaoso, me mofanö ena''ö, ba imane ama galawe andrö khö numönönia: Abe''e''ö ndra''ugö ua, a wakhe mato sambawa, ba hana na mofanö ami dania.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 6, 'Ba tebato na ira, ba orudu manga zi darua andrö. Ba imane ama galawe andrö khö numönönia: Hana na mörö''ö na, akha somuso tödö ndra''ugö.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 7, 'Ba maoso zui ia, mofanö ena''ö; ba iforege sibai khönia matuania, ba mörö ia zamuza tö.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 8, 'Ba me ihulö wongi wemaoso, me mahemolu ö, ba wofanö, ba imane ama galawe andrö: Abe''e''ö ndra''ugö ua, ba mibase''ö, irege tanö owī dania. Ba manga zi darua andrö.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 9, 'Ba me maoso niha andrö, ba wofanö, awö ndrongania ba döi andrö ba sawuyunia, ba imane matuania, ama galawe andrö: Hiza, no numalö luo, bongi: miförö! Hiza, lö alaŵa tö luo; förö, akha somuso tödö ndra''ugö! Ba mahemolu mbanua, ba hana na mofanö ami, ena''ö öfuli''ö ba khömi.', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 10, 'Ba lö''ö sa''ae edöna mörö niha andrö; möfanö sa''ae ia, ba irugi gamaudu Yebusi andrö, ya''ia Yeruzalema. Ba dua geu khönia galide, nifosela ba fao ndrongania ba döi andrö.[1]', '["Yos 15:63"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 11, 'Ba me no larugi gamaudu Yebusi, ba me no tanötanö owi, ba imane sawuyu andrö, khö zokhö ya''ia: Tabu miyomo ba mbanua Ndraono Yebusi andrö, ba wemörö ba da''ö!', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 12, 'Ba imane khönia sokhö ya''ia: Lö möi ita ba mbanua niha bö''ö, ba zi lö Iraono Gizeraeli, tarugi Gibea.', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 13, 'Ba imane na khö zawuyunia andrö: Tabu ba mbanua andrö, ba wemörö, ma ba Rama!', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 14, 'Ba latohugö wofanö, ba me no arakha larugi Gibea andrö, banua mado Mbeniyami, ba aekhu ira luo.', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 15, 'Ba möi ira miyomo ba da''ö, ba wemörö ba Gibea andrö. Ba me irugi, ba ibadugö ia ba newali mbanua, ba lö sama''amöi ya''ira yomo khönia, ba wemörö.', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 16, 'Ba so niha satua, si otarai halöŵönia ba nowi, me bongi; banua ba hili mado Geferayi mböröta ba si fatewu ia ba Gibea; ba banua da''ö, ba mado Mbeniyami.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474668, 'OT', 'Sanguhuku', 19, 17, 'Ba me ifakhölö ia da''ö ba me i''ila zikoli andrö baewali mbanua, ba imane niha satua andrö: Heza möi''ö ba heza ö''otarai?', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 18, 'Ba itema linia, imane: Sikoli ndra''aga, ma''otarai Mbetilekhema Yuda ba masaŵa dalu hili mado Geferayi: ba da''ö mbanuama: No möido ba Mbetilekhema Yuda ba ufulido ba khöma, ba lö sama''amöi yomo khönia ya''odo!', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 19, 'So sa khöma ndru''u ba ö galidema, ba he kue ba agu, öma sawuyumö ira alawe andre ba ö ngoni-ngoni andre, ni''ohe zawuyumö andre; lö hadia ia zambö khöma.', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 20, 'Ba imane niha satua andrö: Tabu manö yomo, ba na so hadia ia zi lö khöu, ba no khögu so: lö''ö sa tola ba danö mörö''ö.', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 21, 'Ba i''ohe ia yomo khönia, ba ilau gö galide; ba lasasai gahera ba manga ira.', '[]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 22, 'Ba me no ohahau dödöra, ba hiza, lafasui nomo banua da''ö, niha si si lö yaŵa, latutu lagö mbawandruhö ba lamane ba niha satua andrö, sokhö omo: Ohe baero niha andrö, si no möi tomeu, ena''ö oruduga khönia![2]', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 23, 'Ba möi tou khöra zokhö omo, imane khöra: Böi ga''a; böi mifazökhi horö! Me no möi tomegu niha andrö, ba böi milau zi lö sökhi andrö![3]', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 24, 'Hiza nonogu, ono alawe, ba dongania ba döi andrö; da''ö ube''e baero khömi, ba hana na mifakao, hana na milau khöra zomasi ami; ba ba niha andrö, ba lö tola mifazökhi horö si manö!', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 25, 'Ba lö''ö sa lafondrondrongo khönia niha andrö. Ba ituyu ndrongania ba döi andrö tome andrö, ba i''ohe tou khöra baewali, ba lahoröni, la''o''aya, sara wongi manö, moluo awena la''efa''ö ia.', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 26, 'Ba me moluo, ba so ndra alawe andrö, ba tegaölö tou barö mbato zi so yomo ira matuania, ba ba da''ö so, irege tumbu luo.', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 27, 'Ba me maoso ndra matuania, si hulö wongi, me ibokai mbawandruhö, we''amöi tou ba wofanö, ba hiza ndra alawe andrö, dongania ba döi, baro mbatö, no itugelai doyo mbawandruhö.', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 28, 'Ba imane khönia: Faoso, mofanö ita! ba lö fanema li. Ba ihare''ö ba galide khönia ba mofanö ia ba khöra.', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 29, 'Ba me no irugi khöra, ba ihalö zi''öli ba ituyu mboto ndrongania ba döi andrö, itema ikhökhö, i''ofelendrua ba ifa''ohe''ö, idozigö mado Ndraono Gizeraeli.', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474668, 'OT', 'Sanguhuku', 19, 30, 'Ba dozi sangila, ba lamane: Lö murai mulau zi manö ba lö murai mu''ila, götö wa no aefa Ndraono Gizeraeli ba danö Miserayi, irugi ma''ökhö andre! Ba mifatou-tou tödömi zi manö ba mi''ombakha''ö lala, mihede!', '["MozI 19:4 b.t.; Hos 9:9; 10:9","MozI 34:7; SamII 13:12"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 1, 'Ba maoso Ndraono Gizeraeli fefu, falukha ira föna Yehowa ba Misefa, ha wa''ato ira, ha sara dödö, i''otarai Dano, numalö ba Mbereseba, ba banua Gileadi.[1]', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 2, 'Ba högöra fefu, dozi mado Ndraono Gizeraeli, ba ahori so ba walukhata mbanua Lowalangi andrö — 400.000 niha, sanörö tanö, solohe si''öli.', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 3, 'Ba larongo mado Mbeniyami, no möi ba Misefa Ndraono Gizeraeli. Ba lamane Iraono Gizeraeli: Mi''ombakha''ö, he wisa ba wolau si lö sökhi andrö mege!', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 4, 'Ba imane ono Lewi andrö, sodonga ira alawe nibunu andrö: Urugi Gibea ba danö mado Mbeniyami, awö ndrongagu ba döi andrö, ba wemörö ba da''ö.', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 5, 'Ba maoso khögu mbanua Gibea andrö, lafasui nomo ba zi bongi, so dödöra si lö sökhi khögu: ya''odo, ba labunu mena''ö, ba dongagu ba döi andrö, ba no lafakao, no labe''e mate.', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 6, 'Ba utuyu ndrongagu ba döi andrö, utema ukhökhö, ufa''ohe''ö, udozigö banua Ndraono Gizeraeli; noa sa manao horö ira, no si lö sökhi lafazökhi ba Ndraono Gizeraeli!', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 7, 'Ba no ahori so ami, ya''ami, Iraono Gizeraeli! Ba miŵa''ö huku ba da''ö, mifaigi lala![2]', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 8, 'Ba maoso ira fefu, ha sara dödö, ba lamane: Ya''ita fefu, ba samösa lö tola mofanö, samösa lö tola mangawuli ba khöra!', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 9, 'Hiza, da''ö talau ba mbanua Gibea andrö: talau dahö-dahö khöra.', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 10, 'Dafulu tatutuyu ba zi otu ba mado Ndraono Gizeraeli fefu, otu ba zi hönö ba hönö ba zi fulu ngahönö, ena''ö lafaigi mbalazo zato, ena''ö tasulöni ba Gibea mado Mbeniyami horö andrö, nifazökhira ba Ndraono Gizeraeli.', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 11, 'Ba owulo Ndraono Gizeraeli ba zinga mbanua andrö, ha sara dödö.', '["Faigi 11:11; SamI 7:5","MozI 34:7"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 12, 'Ba lafatenge zinenge ba mado Mbeniyami fefu mado Ndraono Gizeraeli andrö, lamane khöra: Hadia horö andrö, nirongoda ba khömi?', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 13, 'Ba mibe''e baero niha si si lö yaŵa andrö, banua Gibea, ena''ö mabunu, ena''ö mahori zi lö sökhi andrö ba Ndraono Gizeraeli! Ba te khö mado Mbeniyami wolo''ö niŵa''ö dalifusöra andrö, Iraono Gizeraeli.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 14, 'Ba so mado Mbeniyami, banua bö''ö, möi ba Gibea, möi fasuwö ba Ndraono Gizeraeli.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 15, 'Ba fa''ato mado Mbeniyami, banua no mege misa, me luo da''ö, ba no 26.000, solohe si''öli, lö lai mbanua Gibea andrö, 700 da''ö nitutuyu.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 16, 'Ba ba niha da''ö fefu, ba 700 nitutuyu zi takera; ba dozi enahöi sibai waribosa, göna mbu si ha sara labe''e, lö''ö manö fasala.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 17, 'Ba sabölö Ndraono Gizeraeli, lö lai mado Mbeniyami, ba no 400.000 solohe si''öli, oi sabölö.', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 18, 'Ba maoso ira, lasaŵa misi yaŵa Mbetieli, lasofu khö Lowalangi, lamane: Ha niha zi börötaigö manuwö mado Mbeniyami. Ba imane Yehowa: Mado Yuda ua.', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 19, 'Ba maoso Ndraono Gizeraeli, lahulö wongi, ba fönaföna Gibea tebato ira.', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 20, 'Ba möi zabölö Ndraono Gizeraeli andrö, ba wolau ba mado Mbeniyami, lafa''oli ira ba gametahöra, ba gamaudu Gibea.', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 21, 'Ba so moroi yomo ba Gibea mado Mbeniyami, ba 22.000 la''ö''ötö tou, Iraono Gizeraeli [mado Mbeniyami], me luo da''ö.', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 22, 'Ba möi misi yaŵa Ndraono Gizeraeli, mege-ege föna Yehowa, irege bongi; ba lasofu khö Yehowa, lamane: Hadia, mafuli möi manuwö talifusöma andrö, mado Mbeniyami? Ba imane Yehowa:', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 23, 'Mifuli mi''ae''e! Ba la''abe''e''ö dödöra sato, sabölö Ndraono Gizeraeli andrö, ba lafuli lafa''oli ira, ba zi so ira me luo labörötaigö.', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 24, 'Ba me lafuli lafaondragö mado Mbeniyami Iraono Gizeraeli, me mahemolu ö,', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 25, 'ba so moroi yomo ba Gibea mado Mbeniyami, me luo da''ö [göi], ba 18.000 zui la''ö''ötö tou Iraono Gizeraeli — oi solohe si''öli.', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 26, 'Ba möi misi yaŵa ba Mbetieli Ndraono Gizeraeli fefu, sato fefu, ba ba da''ö la''iagö, mege-ege föna Yehowa ba mamoni ba gö, me luo da''ö, irege bongi. Ba labe''e khö Yehowa zumange nitunu ba sumange fangorifi.[3]', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 27, 'Ba lafuli lasofu khö Yehowa Iraono Gizeraeli — me luo da''ö, ba ba da''ö so dawöla, naha zura goroisa Lowalangi, ba Fineha andrö,', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 28, 'ono Geleazari, ma''uwu Ga''aroni, zangai-ngai halöŵö ba khönia — lamane: Hadia, mafuli möi, zamuza tö, manuwö talifusöma andrö, mado Mbeniyami, ma maböhöli? Ba imane Yehowa: Mi''ae''e, mahemolu ube''e sa ba dangami ira.', '["SamI 7:6"]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 29, 'Ba lafatenge Iraono Gizeraeli zamini''ö ya''ira ba zinga Gibea, fasui.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 30, 'Ba mahemolu ö, ba so Ndraono Gizeraeli, ba wolau ba mado Mbeniyami, lafa''oli ira ba gamaudu Gibea, si mane si mendrua mege.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 31, 'Ba so moroi yomo mado Mbeniyami, lafaondragö ira, ba tedönisi, aefa ba zinga mbanua, ba labörötaigö labubunu ösa Ndraono Gizeraeli, si mane mege, ba lala andrö, sara zaekhu misi yaŵa ba Mbetieli ba si sara, ba sanörö benua, saekhu ba Gibea; mato 30 niha, Iraono Gizeraeli, labunu.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 32, 'Ba lamane dödöra mado Mbeniyami: Te''ala zui ira khöda, si mane mege. Ba noa sa mamagölö Ndraono Gizeraeli, no lamane: Talau moloi [ua], ena''ö tadönisi ira ba lala andrö, aefa ba mbanua.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 33, 'Ba mozo Ndraono Gizeraeli fefu, owulo ira, la''iagö zinga Mba''ali Damara, ba so göi nawöra andrö, la''oroi nahara mbini-mbini, ba zi tambai Gibea, tanö ba gaekhula luo.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 34, 'Ba 10.000 sabölö Ndraono Gizeraeli nitutuyu zanaŵa gamaudu Gibea ba tobali fasöndrata sabölö-bölö sibai, ba ikhamö ira famakiko, si lö mudöna-döna.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 35, 'Te''ala mado Mbeniyami ba Ndraono Gizeraeli ibe''e Yehowa, ba 25.100 niha la''ö''ötö tou, mado Mbeniyami, Iraono Gizeraeli, me luo da''ö, oi solohe si''öli.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 36, 'Ba aboto ba dödö mado Mbeniyami, wa no te''ala ira. Lafolala mado Mbeniyami Iraono Gizeraeli, ladöna-döna sa ba nifatarora ba mbini-mbini andrö, ba zinga Gibea.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 37, 'Ba lagösö lasaŵa Gibea si so ba mbini-mbini andrö, möi ira mu''ö''ötö tou mbanua Gibea fefu.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 38, 'Ba no mamagölö Ndraono Gizeraeli ba zi so ba mbini-mbini andrö, ena''ö latunu nomo, yomo ba mbanua, tandra khöra.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 39, 'Ba me moloi Ndraono Gizeraeli, ba wasöndrata andrö ba me labörötaigö mado Mbeniyami labunu ösa Ndraono Gizeraeli — mato tölu ngafulu — me lamane dödöra: Te''ala sa ira khöda, si mane ba wasöndrata si föföna mege!', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 40, '— ba hiza zimbo andrö, si oroi moroi yomo mbanua, tandra no mege, ba me lafaigi furira mado Mbeniyami, ba humola sa''ae mbanua ma''asambua, irugi mbanua si yaŵa hola-hola.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 41, 'Ba lafuli ira furi Iraono Gizeraeli, ba tobali dödö mado Mbeniyami, aboto sa''ae ba dödöra, wa no ikhamö ira famakiko.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 42, 'Ba lawuwu ira furi labe''e Iraono Gizeraeli, latörö lala saekhu ba danö si mate, ba lalau-lau na khöra moroi furi. Ba lafa''u''u göi ira si oroi mbanua misa, ba la''ö''ötö tou.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 43, 'Lafasui mado Mbeniyami, la''o''ö irege zolombase ira ena''ö ba lahundragö, irugi ba gamaudu Gibea, tanö ba gatumbukha luo.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 44, 'Ba 18.000 zi mate ba da''ö, mado Mbeniyami, oi sabölö.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 45, 'Ba moloi sa''ae ira, lasaŵa danö si mate, tanö ba gara Rimono andrö, ba ba lala andrö, ba 5.000 tö na labunu Iraono Gizeraeli ba lagohi ira, irugi Gideomo, ba 2.000 labunu na barö ö.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 46, 'Ba fa''ato nibunu fefu, me luo da''ö, mado Mbeniyami, ba no 25.000 solohe si''öli, oi sabölö.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 47, 'Hatö 600 zoloi, sanaŵa tanö si mate, ba ngai gara Rimono andrö, ba öfa waŵa ira ba ngai gara Rimono.', '[]', NULL),
  (3474669, 'OT', 'Sanguhuku', 20, 48, 'Ba lafuli ira Iraono Gizeraeli, ba zi tosai mado Mbeniyami, la''ö''ötö tou si''öli zi tosai banuara, ba he urifö, fefu zi falukha ira, ba banua bö''ö fefu göi, ba latunu.', '[]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 1, 'Ba no möi ba hölu Ndraono Gizeraeli ba Misefa, no lamane: Ya''ita fefu, ba lö tola tabe''e ba mado Mbeniyami nonoda alawe!', '["Faigi 20:18"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 2, 'Ba möi ira ba Mbetieli, ba la''iagö da''ö, irege bongi, föna Lowalangi. Ba labörötaigö mege-ege, ebua lira,[1]', '["Faigi 20:18"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 3, 'lamane: He Yehowa, Lowalangi Ndraono Gizeraeli! Hana wa itörö Ndraono Gizeraeli si mane da''ö, wa sambua mado manö zi lö''ö ba khöra?', '["Faigi 20:18"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 4, 'Ba mahemolu ö, ba lahulö wongi sato, wama''anö naha wame''e sumange, ba labe''e zumange nitunu ba sumange fangorifi.', '["Faigi 20:18"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 5, 'Ba lamane Iraono Gizeraeli: Ha niha, mado Ndraono Gizeraeli fefu, si lö möi ba da''e khö Yehowa, awö zato andre? Noa sa möi ira ba hölu: ha niha zi lö möi misi yaŵa khö Yehowa ba Misefa, ba lö tola lö mate!', '["Faigi 20:18"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 6, 'Ba no aröu-röu ba dödö Ndraono Gizeraeli dalifusöra, mado Mbeniyami, lamane: Sambua mado manö zi no muse''e ba Ndraono Gizeraeli!', '["Faigi 20:18"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 7, 'He tawisa wamaigi ira alawe ba zi tosai andrö, me no möi ba hölu ita khö Yehowa, ma''ifu lö tabe''e khöra nonoda alawe?', '["Faigi 20:18"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 8, 'Ba lamane ba da''ö: Hadia, so ha niha, zi lö möi ba da''e, khö Yehowa, ba Misefa? Ba hiza, samösa lö si möi ba golombaseŵa, ba walukhata, banua Yabesi ba danö Gileadi.', '["MozIV 31:17"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 9, 'La''ofaya niha, ba hiza, samösa lö''ö, banua Yabesi ba danö Gileadi.', '["MozIV 31:17"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 10, 'Ba lafatenge zabölö, 12.000, lamane khöra: Mi''ae mi''ö''ötö si''öli mbanua Yabesi andrö, ba danö Gileadi, fabaya ira alawe ba iraono.', '["MozIV 31:17"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 11, 'Mimane wolau: Dozi motöi matua ba dozi ira alawe, ba zi no orudu ira matua, ba mibunu, ba ono alawe, ba mi''orifi! Ba la''o''ö da''ö.[2]', '["MozIV 31:17"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 12, 'Ba öfa ngaotu zi falukha ira ba mbanua Yabesi andrö, ba danö Gileadi, ono alawe, ba zi lö irai orudu ira matua, ba la''ohe ba golombaseŵa ba Zilo, ba danö Gana''ana.', '["MozIV 31:17"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 13, 'Ba lafatenge sato fefu zi fahuhuo ba mado Mbeniyami andrö, ba ngai gara Rimono, lafabu''u khöra wa''atulö.', '["MozIV 31:17"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 14, 'Ba lafuli ira mado Mbeniyami andrö, ba labe''e khöra ndra alawe no mege, ni''orifira andrö, ono alawe, ba mbanua Yabesi, ba danö Gileadi.', '["MozIV 31:17"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 15, 'Ba ambö na''i fa''ato. Ba aröu-röu ba dödö zato mado Mbeniyami, me no hulö zi fambambö mado Ndraono Gizeraeli, ibe''e Yehowa.', '["MozIV 31:17"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 16, 'Ba lamane satua mbanua: He tawisa wamaigi ira alawe ba zi tosai andrö? Noa sa muhori ndra alawe ba mado Mbeniyami!', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 17, 'Ba lamane: Ba mado Mbeniyami andrö, sauri, ba tenga nibulö''ö dana khöra tanö, fa böi sambua mado manö ahori ba Ndraono Gizeraeli;', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 18, 'ba onoda alawe, ba tebai tabe''e khöra! Noa sa möi ba hölu Ndraono Gizeraeli, no lamane: Ni''elifi zame''e ba mado Mbeniyami ira alawe!', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 19, 'Ba lamane: Ero röfi a''i, ba owasa khö Yehowa ba Zilo, yöu Mbetieli, ba ngai lala andrö si otarai Mbetieli saekhu ba Zikhema, tanö ba gatumbukha, ba raya Lebona.', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 20, 'Ba lafobawa lala ba mado Mbeniyami, lamane: Mi''ae midaro-darogö ba kabu nagu andrö,', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 21, 'ba na mi''ila dania, so moroi yomo ba Zilo nono alawe, ba wanari, ba so ami moroi ba kabu nagu ba oi zara mirabu dongami nono alawe andrö, si otarai Zilo; ba misaŵa danö mado Mbeniyami.', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 22, 'Ba na so dania ndra amara ba ira talifusöra matua, na lafasosoni ndra''aga ba mamane dania khöra: Mibe''e bualami khöma; dozi ndra''aga, ba lö nisöndrama ira alawe, khöma, ba wanuwöda Yabesi andrö. Ba tenga sa nibe''emi khöra; na si manö mena''ö, ba no si so sala ami!', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 23, 'Ba la''o''ö da''ö mado Mbeniyami, lahalö khöra ndra alawe, ndrohu-ndrohu zoguna khöra, sanari andrö, nirabu. Ba lafuli ira ba dana khöra, ba lafuli lataru''ö mbanua misa, nahiara.', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 24, 'Ba mofanö sa''ae göi Ndraono Gizeraeli, ifuli ia ba madora ba ba daliföesöra zamösana, laheta ira ba da''ö, oi zara lasaŵa dana khöra.', '["Faigi 17:6"]', NULL),
  (3474670, 'OT', 'Sanguhuku', 21, 25, 'Me luo da''ö, ba lö razo samatörö Iraono Gizeraeli; ilau manö nikhoi dödönia zamösana.[3]', '["Faigi 17:6"]', NULL),
  (3474515, 'OT', 'Ruti', 1, 1, 'Me luo zanguhuku andrö, ba samuza ma''ökhö, ba lofo ba danö. Ba so zaheta, banua Mbetilekhema Yuda, i''ohe wo''omonia ba ononia matua, dombua, ba isaŵa danö Ndraono Moabi.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 2, 'Töi zawu''a andrö, ba Elimelekhi, ba Na''emi döi wo''omonia ba Maloni ba Khiliyoni döi nononia andrö — mado Geferayi, banua Mbetilekhema Yuda. Ba larugi danö Ndraono Moabi ba la''iagö da''ö.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 3, 'Ba mate wo''omo Na''emi andrö, Elimelekhi, ba hatö ya''ia ba ononia andrö si dombua.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 4, 'Ba mangowalu nononia andrö, ono Ndraono Moabi lahalö; Orafa döi zi sambua ba Ruti zi sambua. Ba soso ira ba da''ö, mato mewulu fakhe.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 5, 'Ba mate göi zi darua andrö, Maloni ba Khiliyoni, ba ira alawe andrö zi tosai, lö''ö sa''ae ononia andrö, si darua, ba lö fo''omonia andrö.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 6, 'Ba maoso Na''emi, i''ohe numönönia andrö, mangawuli, aheta ia ba danö Ndraono Moabi, me no irongo ba da''ö, ba danö Ndraono Moabi, no ihakhösi tödö mbanuania Yehowa ba no ifuli ibe''e khöra mbalazo.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 7, 'Ba iröi mbanua andrö, ba zi soso ia mege, ba fao khönia numönönia andrö si dombua. Ba me ba lala so ira, ba wangawuli ba danö mado Yuda,', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 8, 'ba imane Na''emi khö numönönia andrö, si dombua:', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 9, 'Na mitema da''ö khö Yehowa, ba lö zi lö misöndra zahono ami, yomo khö ndra matuami dania, darua ami! Ba fa''ago bawa ia khöra.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 10, 'Ba mege-ege sibai ira, ba lamane khönia: Fao sa''ae ndra''aga khöu ba niwami andrö!', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 11, 'Ba imane Na''emi: Mifuli ami, onogu, hadia, wa fao ami khögu? Hadia, so na nono matua ba dalugu, fo''omomi dania?', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 12, 'Mifuli ami, ya''ami onogu, mi''ae''e! satua sa''ae ndra''odo; tebai sa''ae möido nihalö. Ba na umane dödögu ena''ö: So na dötönafögu! ba na bongi andre falukhado ndra matua ba na mo''onodo ono matua, ena''ö,', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 13, 'ba hadia, mibase''ö irege ebua da''ö? Hadia, nitaha manö ami, lö möi nihalö? Böi, ya''ami ira onogu! Abu sibai sa dödögu ami; ya''odo sa, ba no si göna tanga Yehowa!', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474515, 'OT', 'Ruti', 1, 14, 'Ba ifuli mege-ege sibai ira; ba Orafa, ba fa''ago bawa khö ninania, ba Ruti andrö, ba i''olembai ia.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 15, 'Ba imane Na''emi: Me no ifuli ia kala''edomö ba niwara ba khö Lowalangira, ba fuli''ö göi, o''ö gala''edomö!', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 16, 'Ba imane Ruti: Böi forege khögu, uröi ndra''ugö, fa ufulido, lö faodo khöu! Ba zi möi ndra''ugö sa, ba da''ö möi ndra''o göi, ha ba zi so''ö, ba da''ö göi sodo, iwau niwagu, ba Lowalangiu Lowalangigu;', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 17, 'ba zi mate ndra''ugö, ba da''ö göi matedo, ba ba da''ö ndramuko''o ndra''odo; yamulau khögu nilau dödönia Yehowa — ha fa''amate zamabali ya''ita!', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 18, 'Ba me i''ila Na''emi, no aro dödö da''ö, ba wefao khönia, ba ibato wamarou ya''ia.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 19, 'Ba mofanö zi darua andrö ba larugi Mbetilekhema. Ba me möi ira miyomo ba Mbetilekhema, ba humufa mbanua ma''asambua, ba khöra andrö, ba lamane: Da''ö Na''emi andrö?', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 20, 'Ba imane khöra: Böi mibe''e töigu Na''emi (wa''omasigu) Mara (sabu tödö) mibe''e töigu; noa sa''ae oya nifatörö Zi lö ambö fa''abölö khögu fa''abu dödö.', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 21, 'Si so ndra''o, me mofanödo ba si lö''ö, me i''ohe mangawuli ndra''odo Yehowa; ba hadia wa mibe''e töigu Na''emi, me noa sa''ae ihöndrögö ndra''o Yehowa, me no ifatörö khögu wa''abu dödö Si lö ambö fa''abölö?', '[]', NULL),
  (3474515, 'OT', 'Ruti', 1, 22, 'Ba böröta wamasi gandru, me larugi Mbetilekhema Na''emi andrö ba umönönia Ruti andrö, Iraono Moabi, si no fao khönia, moroi ba danö Ndraono Moabi.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 1, 'Ba so nakhi Na''emi andrö, talifusö Gelimelekhi, niha so''ana''a, Boasi döinia.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 2, 'Ba imane Ruti andrö, Iraono Moabi, khö [ninania] Na''emi: Damöido ba nowi [zonowi] ba wangozaragö lai, moroi furi zebua tödö khögu!', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 3, 'Ba möi ia, irugi ba mangozaragö lai ia ba nowi andrö, moroi furi zamasi: ba hulö zi no muŵa''ö khönia, wa no khö Mboasi andrö nowi andrö, Boasi talifusö Gelimelekhi.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 4, 'Ba hiza ba so moroi yomo ba Mbetilikhema Mboasi, ba i''owai zamasi, imane: Yamutolo ami Yehowa!', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 5, 'Ba imane Boasi khö zawuyunia andrö, sanaro samasi: Ha ökhö nono alawe andrö?', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 6, 'Ba imane khönia sawuyu andrö, sanaro samasi: Ono Ndraono Moabi, ya''ia zi fao khö Na''emi no moroi ba danö Ndraono Moabi.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 7, 'No isofu, imane: Hadia, tola u''ozaragö lai, he ba gotalua ngamböbö, moroi furi zamasi? ba so ia, ba lö nibatonia, i''otarai zi hulö wongi, irugi iada''e, ba ma''ifu lö solombase ia.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 8, 'Ba imane Boasi khö Ruti: Örongo, onogu: Böi ae ba nowi bö''ö, ba wangozaragö lai, böi röi da''e; fao-fao''ö ba nono alawe khögu.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 9, 'Töngöni nowi andre, ba zamasi ira, ba o''ö ira: noa sa ube''e li ba zawuyugu andrö, fa böi lategu''ö. Ba na owökhi dödöu, ba ae ba migö andrö, ba badu nita''u zawuyugu.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 10, 'Ba ifalögu tou ia ba danö, imane khö Mboasi: He moroi, wa falukhado khöu wa''ebua dödö, wa öfaigi ndra''o, lö lai wa no niha baero ndra''odo?', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 11, 'Ba itema linia Boasi, imane khönia: Noa sa la''ombakha''ö khögu fefu, he wisa ndra''ugö khö ninau andrö, me no mate wo''omou, awö wa no öröi ndra amau inau ba banuami, we''amöi ba niha bö''ö, si lö örai mila mege.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 12, 'Yamusulöni khöu Yehowa nilaumö andrö, ya lö ambö luou khö Yehowa, Lowalangi Ndraono Gizeraeli, ba zi möi''ö mangalui saŵatö, barö gafinia.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 13, 'Ba imane khönia: He Tua, ena''ö na sebua tödö ndra''ugö khögu! Noa sa örara dödögu ba no öhaogö wehede khö genoniu ira alawe, lö lai wa tenga si mane enoni ira alawe khöu ndra''odo.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 14, 'Ba me inötö wemanga, ba imane khönia Boasi: Ae ba da''e ba a wöfö göma, ba ungugö ba nirö aisö andrö göu kue! Ba mudadao ia ba ngai zamasi andrö, ba ibe''e önia mböra nifakoe, tobali abuso ia ba so zi tosai khönia.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 15, 'Ba me ifuli möi, ba wangozaragö lai, ba ibe''e li ba zawuyunia Boasi, imane: Hana na ba gotalua ngamböbö göi itutuyu, böi mitegu ia.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 16, 'Midöni na''i ma''ifu khönia ba ngamböbö, miröi tou, ena''ö i''ozaragö, ba böi mihede-hede''ö ia!', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 17, 'Ba mangozaragö lai ia ba nowi da''ö, irege bongi, ba me iböbörö ni''ozaragönia, ba no arakha dombua yöu gandru.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 18, 'Ba i''ohe, ba me irugi yomo, ba i''ila inania ni''ozaragönia. Ba isao''ö baero zi tosai khönia mege, me abuso ia, ibe''e khö ninania.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 19, 'Ba imane khönia inania: Heza mangozaragö lai ndra''ugö ma''ökhö, heza mohalöŵö''ö? Ya''ahowu zanolo ya''ugö!', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 20, 'Ba imane Na''emi khö numönönia: Yamufahowu''ö ia Yehowa, me lö nibödania fa''ahakhö dödönia, he ba zauri andre ba he ba zi no mate andrö. Ba imane na khönia Na''emi: Ga''ada niha andrö, sananu ya''ita ena''ö.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 21, 'Ba imane Ruti, Iraono Moabi andrö: Noa sa göi iŵa''ö khögu: Fao-fao ndra''ugö ba zöhalöŵö khögu, irege awai mbasitögu khöra.', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 22, 'Ba imane Na''emi khö numönönia Ruti: Lau, onogu! fao ndra''ugö khö nono alawe andrö khönia; lö''ö mötö lafasao''ö ba nowi niha bö''ö!', '[]', NULL),
  (3474516, 'OT', 'Ruti', 2, 23, 'Ba fao-fao ia ba nono alawe andrö khö Mboasi, irege awai wamasi rigi ba famasi gandru: ba khö ninania sa''ae i''iagö.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 1, 'Ba imane khönia inania Na''emi: Ufaigi khöu zahono Ndra''ugö, onogu, ena''ö sohahau tödö ndra''ugö.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 2, 'Hiza, Boasi andrö, si fao-fao''ö ba nono alawe andrö, ba no ga''ada, ba manöri gandru ia ba golayama mbasitö bongi.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 3, 'Ba ondri, bayoini fanikha ndra''ugö, ba onukha ba ae mitou ba golayama mbasitö; ba böi i''ila wa ya''ugö, irege no aefa manga ia, ba irege no ibadu nagu.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 4, 'Ba na aefa da''ö, na mörö ia, ba töngöni naha, heza mörö ia; ba ae''e ba bokai gambala tanö ba gahenia ba förö tou; ba iŵa''ö dania khöu, he öwisa.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 5, 'Ba imane: Fefu hadia ia niŵa''öu, ba u''o''ö!', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 6, 'Ba möi ia mitou, ba golayama mbasitö, ahori i''o''ö niŵa''ö ninania khönia.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 7, 'Ba me no manga Mboasi ba me no ibadu nagu, me ohahau sa''ae dödönia, ba möi ia mörö ba gero mbaho ngamböbö gandru.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 8, 'Ba me talu mbongi, ba tokea Mboasi, ba me ifaöga ia, ba hiza ndra alawe tanö ba gahenia.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 9, 'Ba imane: Ha niha ndra''ugö? Ba imane Ruti: Ruti ndra''odo, sawuyumö: bologö gafiu yaŵa zawuyumö, me no sananu ndra''ugö.[1]', '["Hez 16:8"]', NULL),
  (3474517, 'OT', 'Ruti', 3, 10, 'Ba imane Boasi: Ya nifahowu''ö Yehowa ndra''ugö, onogu! Ebua na wa''omasimö safuria, moroi ba zi föföna andrö, me no lö nigohiu ono matua, he si numana, ba he so''ana''a.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 11, 'Ba hiza, ba böi busi dödöu, ya''ugö onogu! Fefu hadia ia niŵa''öu, ba utörö khöu. Samba banua manö ndra''aga, ba lö si lö aboto ba dödö, wa no ira alawe si sökhi bua-bua ndra''ugö.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 12, 'Ba hiza, si ndruhu sa, sananu ndra''odo; ba so na zananu bö''ö, sahatö moroi khögu.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 13, 'Iagö da''e bongi: ba na isanu ndra''ugö mahemolu mbanua, ba yamusanu''ö; ba na lö omasi ia isanu''ö, ba faya wa no sauri Yehowa, na tenga ya''odo zananu ya''ugö! Förö, irege moluo!', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 14, 'Ba mörö ia irege moluo, tanö ba gahenia. Ba maoso ia, gasa-gasa wa''oroma döi niha.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 15, 'Ba imane: Bologö lembeu andrö!', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 16, 'Ba irugi yomo mbanua.', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 17, 'Gandru andre, si samba lauru a matonga, ibe''e khögu, imane sa: Lö tola lö monoro danga ndra''ugö wangawuli khö ninau!', '[]', NULL),
  (3474517, 'OT', 'Ruti', 3, 18, 'Ba imane inania: Honogö''ö, onogu, irege ö''ila, he wisa lua-lua da''ö! Lö''ö sa ibato niha andrö, balazi ifalua da''ö ma''ökhö!', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 1, 'Ba möi miyaŵa ba mbawa göli Mboasi ba mudadao ia ba da''ö. Ba me itörö sibai sananu andrö, niŵa''ö Mboasi, ba imane khönia: Ae ba da''e, sane, dadao tou!', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 2, 'Ba dafulu iŵa''ö satua Boasi, imane: Midadao tou, ba da''e! Ba me no dumadao ira, ba imane khö zananu andrö:', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 3, 'Benua andrö khö ga''ada Elimelekhi andrö, ba no i''amaŵa Na''emi andrö, si no mangawuli moroi ba danö Ndraono Moabi.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 4, 'Ba no uŵa''ö tödögu, ufarongogö khöu, umane: Tema sanu ia, ba zi so andre, ba zi so satua mbanuada andre. Na nilau dödöu sananu ndra''ugö, ba sanu ia. Ba na lö omasi''ö ösanu, ba ombakha''ö khögu, ena''ö u''ila watahögö! Baeromö, ba samösa lö si tola mananu ya''ia, hatö ya''o, na aefa ndra''ugö!', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 5, 'Ba imane Boasi: Ba na luo ö''öli mbenua andrö khö Na''emi, ba khöu göi Ndraono Moabi andrö, lakha zi no mate andrö, ba wangorifi töi zi mate andrö ba dana khönia tanö andrö.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 6, 'Ba imane sananu no mege: Ba tebai usanu, fa böi tefara''u dana khögu ube''e. Sanu khöu nisanugu ena''ö, me tebai ya''odo zananu.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 7, 'Ba ba Ndraono Gizeraeli me föna, amaedola nitutu tanö, na so nisanu ba ma nifalalini, ba iheta mbadagahenia ba ibe''e khö nawönia — da''ö wangaro hadia ia ba Ndraono Gizeraeli.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 8, 'Ba imane sananu andrö [ena''ö] khö Mboasi: Sanu ia khöu! ba iheta mbadagahenia.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 9, 'Ba imane Boasi ba zatua mbanua ba ba zato fefu: Ya''ami zi so ba mbörö ma''ökhö, wa no u''öli gokhöta Gelimelekhi andrö fefu ba okhöta ndra Maloni Khiliyoni fefu, khö Na''emi andrö.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 10, 'Ba baero ö, ba no uhalö göi Ndraono Moabi andrö, Ruti andrö, lakha Maloni, ba wangorifi töi zi no mate andrö ba dana khönia tanö, ena''ö böi taya döi zi no mate andrö ba watalifusöta ba ba mbawa göli mbanuara — ya''ami zi so ba mbörö ma''ökhö!', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 11, 'Ba lamane sato fefu, ba da''ö ba mbawa göli, awö zalaŵa: Si so ba mbörö ndra''aga! Yamutolo ndra alawe andrö, si möi yomo khöu Yehowa, ena''ö si mane Rakhela ba Lea, awe Ndraono Gizeraeli andrö si darua! Ya salaŵa ndra''ugö ba Geferata ba ya teturia döimö ba Mbetilekhema![2]', '["MozI 29","MozI 38:29"]', NULL),
  (3474518, 'OT', 'Ruti', 4, 12, 'Ba ya si mane omo Weresi andrö, ono Yuda khö Damara, nomou, ba nga''ötö andrö, nibe''e Yehowa khöu dania, ono ndra alawe andrö, si hulö nono alawe na.[3]', '["MozI 29","MozI 38:29"]', NULL),
  (3474518, 'OT', 'Ruti', 4, 13, 'Ba ihalö Ruti andrö Boasi, tobali fo''omonia. Ba me orudu ia khönia, ba ibe''e khönia Yehowa manabina ia, ba mo''ono, ono matua.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 14, 'Ba lamane ira alawe khö Na''emi: Nisuno Yehowa, si no manehe khöu sananu ma''ökhö, tobali tetötöi dania döinia ba Ndraono Gizeraeli.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 15, 'Da''ö zangokafui tödöu ba sondrorogö ya''ugö ba wa''atuamö, me no umönöu andrö, sangomasi''ö ya''ugö, zadono ya''ia — ya''ia andrö, si no abölö moguna khöu, moroi ba zi dafitu ono matua.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 16, 'Ba ihalö nono andrö Na''emi, ihagi ba tobali sangai ono ia.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 17, 'Ba lafatörö döi ira alawe si fahatö omo khönia, lamane: No mo''ono Na''emi; ba Obedi labe''e töinia — ya''ia nama nama Dawido andrö, Iza''i.', '[]', NULL),
  (3474518, 'OT', 'Ruti', 4, 18, 'Ba da''e nga''ötö Weresi andrö: Ono Weresi, ba Eseromo,[4]', '["Nga''ötI 2:5; Mat 1:3 b.t."]', NULL),
  (3474518, 'OT', 'Ruti', 4, 19, 'ba ono Geseromo ba Aramo, ba ono Garamo, ba Aminadabi,', '["Nga''ötI 2:5; Mat 1:3 b.t."]', NULL),
  (3474518, 'OT', 'Ruti', 4, 20, 'ba ono Gaminadabi, ba Nahaso, ba ono Nahaso, ba Salemo,', '["Nga''ötI 2:5; Mat 1:3 b.t."]', NULL),
  (3474518, 'OT', 'Ruti', 4, 21, 'ba ono Zalemo, ba Boasi, ba ono Mboasi, ba Obedi.', '["Nga''ötI 2:5; Mat 1:3 b.t."]', NULL),
  (3474518, 'OT', 'Ruti', 4, 22, 'Ba ono Gobedi, ba Iza''i, ba ono Giza''i, ba Dawido.', '["Nga''ötI 2:5; Mat 1:3 b.t."]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 1, 'So niha, banua Ramata''i, ma''uwu Zufi, ba hili mado Geferayi, Elikana döi, ono Yeroha ono Gelihu ono Dohu ono Zufi, mado Geferayi.[1]', '["Nga''ötI 6:34","MozII 23:17","MozI 16:2"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 2, 'Ba dombua ndrongania: Khana döi zi sambua ba Fenina zi sambua; ba Fenina, ba si so ono, ba lö ono Khana.', '["Nga''ötI 6:34","MozII 23:17","MozI 16:2"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 3, 'Ba ero röfi möi misi yaŵa niha andrö, moroi ba khöra, ba wangalulu khö Yehowa ngahönö ba Zilo, ba ba wame''e sumange. Ba so ba da''ö ndraono Eli andrö, si darua, Hofini ba Fineha, ere khö Yehowa.[2]', '["Nga''ötI 6:34","MozII 23:17","MozI 16:2"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 4, 'Ba ero na ibe''e zumange Elikana andrö, ba ifo''urakha wo''omonia Fenina ba ononia matua ba ononia alawe fefu;', '["Nga''ötI 6:34","MozII 23:17","MozI 16:2"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 5, 'ba khö Khana, ba ha samösa mo''urakha ibe''e, lö lai wa no abölö i''omasi''ö Khana; ba no iduhö dalunia Yehowa.[3]', '["Nga''ötI 6:34","MozII 23:17","MozI 16:2"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 6, 'Ba ibusi dödönia udunia andrö (Fenina) fehede famaosi tödönia, ba wangandrö fönunia, me no iduhö dalunia Yehowa.', '["Nga''ötI 6:34","MozII 23:17","MozI 16:2"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 7, 'Ba ero röfi, ba si manö-manö wolaunia: ero na möi ira misi yaŵa ba nomo Yehowa ibaosi dödönia. Ba mege-ege Khana, ba lö manga.', '["Nga''ötI 6:34","MozII 23:17","MozI 16:2"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 8, 'Ba imane khönia fo''omonia Elikana: He Khana, hana wa mege-ege ndra''ugö ba hana wa lö manga''ö? hadia mbörö wa si lö sökhi-sökhi dödöu? Hadia, lö omasi''ö ndra''odo, moroi ba zi dafulu, ono matua?', '["Nga''ötI 6:34","MozII 23:17","MozI 16:2"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 9, 'Ba samuza ma''ökhö, me no manga ira ba Zilo, ba me no labadu nagu, ba maoso Khana, i''ondrasi Yehowa, ba no dumao-dao ba kurusi Eli, ere andrö, ba zinga mbawandruhö gosali Yehowa.', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 10, 'Ba mangandrö Khana khö Yehowa, ba wa''abu dödönia andrö, mege-ege sibai ia, ba ifabu''u linia,', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 11, 'imane: He Yehowa ngahönö! Na öfaigi lala ba wa''abu dödö genoniu andre, na itörö tödöu ndra''odo, na lö olifu''ö genoniu andre, wame''e ono matua khönia, ba khö Yehowa ufuli ia, sagötö ya''ia, ba böi tefatörö ba högönia wanöwö![4]', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 12, 'Ba me i''aragö wangandrö khö Yehowa, ba ifaigi-faigi mbawania Eli.', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 13, 'Lö''ö sa alua baeha Khana wehedenia, ha bewenia zametu-metu, ba linia, ba lö terongo, — ba ibali si mabu Eli.', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 14, 'Ba imane khönia: Ha wa''ara dania döhö wemabumö?', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 15, 'Tayaigö wemabu andrö! Ba imane Khana: Tenga Tua; ira alawe sabu tödö ndra''odo a''ine! Agu ba hadia ia zi mabu niha, ba lö nibadugu, ba no ubokai dödögu, khö Yehowa.[5]', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 16, 'Böi bali si lö ngaroro genonimö andre; börö wehedegu irege da''e, ba fa''alangu dödögu ba fa''abu dödögu.', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 17, 'Ba imane khönia Eli: Fuli''ö, ya''ohahau dödöu, ibe''e sa''ae khöu Lowalangi Ndraono Gizeraeli ni''andröu khönia!', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 18, 'Ba imane: Ena''ö na falukha genoniu andre wa''ebua dödöu khönia! Ba mofanö ndra alawe andrö ba manga ba döhö wa''abu dödö.', '["MozIV 6:5","Sin 62:9"]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 19, 'Ba mahemolu ö, ba lahulö wongi wangandrö khö Yehowa ba lafuli ira ba Rama. Ba me orudu Elikana khö wo''omonia Khana, ba itörö tödö Yehowa ia.', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 20, 'Ba me no ituo wunia, ba no manabina Khana, ba no mo''ono ia, ono matua, ba Samueli ibe''e töi nono andrö, imane: Me ni''andrögu khö Lowalangi.', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 21, 'Ba me ifuli möi misi yaŵa Elikana andrö, awö zoroiyomonia fefu, ba wame''e khö Yehowa sumange andrö, sero röfi ba hadia nifabu''unia na,', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 22, 'ba lö fao Khana, imane sa khö ngambatönia: Na aefa ba mbagi zusu nono; awena dania u''ohe ia, ena''ö i''oroma''ö ia khö Yehowa, ba ena''ö lö''ö sa''ae tebulö ia ba da''ö.', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 23, 'Ba imane khönia fo''omonia Elikana: Balazi ndra''ugö, iagö furi, irege aefa ia ba mbagi zusu. Yamube''e Yehowa itorö niŵa''öu! Ba toröi furi ndra alawe andrö ba ifaenufaenu nononia, irege aefa ba mbagi zusu.', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 24, 'Ba me no i''efa''ö ba mbagi zusu, ba i''ohe misi yaŵa, ba sara nono zaŵi, si no medölu fakhe, ba dua lauru hamo ba samba nahia nagu, i''ohe ba nomo Yehowa ba Zilo.', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 25, 'Ba lataba nono zaŵi andrö, ba i''ondrasi Eli ina nono andrö, i''ohe nono.', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 26, 'Ba imane: Hiza Tua, faya wa no sauri ndra''ugö, ya''ugö Tua, na tenga ya''odo ndra alawe andrö, si no so ba da''e no, fönau, ba wangandrö khö Yehowa.', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 27, 'Ono andre ni''andrögu, ba no ifondrondrongo Yehowa wangandrögu, no ibe''e khögu ni''andrögu.', '[]', NULL),
  (3474976, 'OT', 'Samueli I', 1, 28, 'Ba ya''o, ba ube''e niwawalö Yehowa göi [nono]; sagötö ya''ia, ba ya niwawalö Yehowa! Ba iröi sa''ae ba da''ö [nono], föna Yehowa.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474977, 'OT', 'Samueli I', 2, 1, 'Ba mangandrö Khana, imane: "Owua-wua dödögu ibe''e Yehowa; no alaŵa yaŵa dandrugu ibe''e Lowalangigu; no faboka mbawagu ba khö zi fa''udu khögu, me no omuso dödögu wangorifimö ya''odo![1]', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 2, 'Samösa lö ni''amoni''ö si mane Yehowa, lö''ö sa baeromö; sambua sa lö gowe, timba Lowalangida.[2]', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 3, 'Böi mimane-mane: Fa''asalaŵa! fa''asalaŵa! Böi alua baehami wayaŵasa! Me no Lowalangi sangila [fefu hadia ia] Yehowa; no Lowalangi sanulo folau [niha].[3]', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 4, 'Fana zabölö, ba nirasa, ba salau-lau, ba la''amöbö talu wa''abölö.', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 5, 'Si no abuso mege, ba no möi enoni, ba wangalui göra, ba ba zolofo mege, ba no döhö wa''olofo. Fitu sa''ae nono zi lö ono mege, ba soya ono, ba sariri.[4]', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 6, 'Yehowa, ba no samunu [niha] ba sangorifi göi, itibo''ö ba mbanua tou ba i''ohe miyaŵa göi.[5]', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 7, 'Ifa''anumana niha Yehowa ba ifo''ana''a göi; ihöndrögö ba ibali''ö salaŵa göi.', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 8, 'Isöbi yaŵa moroi ba gawu-gawu tou zi no amomo, ba moroi ba dambu i''ohe yaŵa zi numana, ba ngai zalaŵa ifedadao, ituturu khöra naha nifosumange. Khö Yehowa sa gehomo danö, ba no ya''ia zame''e dayadaya danö ya''ia,[6]', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 9, 'Ifaigi-faigi gahe zatulö tödö andrö khönia, ba sebua horö, ba si tekiko ba zogömi-gömi. Tenga sa ba wa''abölönia möna niha:[7]', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 10, 'Si fa''udu khö Yehowa, ba nirasa! Ife''ugu-ugu mbanua si yaŵa, yaŵara; Yehowa zanguhuku balö danö misa. Ibe''e wa''abölö ba zalaŵa andrö khönia, i''alaŵa''ö yaŵa dandru nibayoininia andrö!"[8]', '["Luk 1:46 b.t.","MozV 3:24; Sin 18:32","Heb 4:13","Sin 34:11; Gal 4:27","MozV 32:39","Yob 5:11; Sin 24:1; 104:5; 113:7","Sin 91:11","Sin 89:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 11, 'Ba ifuli ia ba Rama [Khana]. Ba ono no mege, ba ihalö-halö halöŵö föna Yehowa, barö mbawa Eli ere andrö.', '[]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 12, 'Ba no si lö ngaroro ndraono Eli andrö, lö ba dödöra Yehowa,', '[]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 13, 'ba lö''ö göi latöngöni hadia zinema gere ba niha sato: Na so zame''e sumange, ba so ngoni-ngoni gere, fatua so bawu na nagole, sara garafu si tölu bawa ba dangania,', '[]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 14, 'ba itaru''ö ba gali ba ma ba mbowoa ba ma ba mbalanga ba ma ba mako: ba hadia ia nifahö garafu andrö, ba ihalö khönia ere. Si manö wolaura ba Ndraono Gizeraeli fefu, si möi ba da''ö ba Zilo.', '[]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 15, 'Ba lö''ö na mutunu dawö, ba so ngoni-ngoni gere andrö, ba imane ba zame''e sumange: Da nösi, nisala ö gere! Lö omasi ia zasoso khöu, ha sataha!', '[]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 16, 'Ba na imane da''ö: Ni''ofönai''ö wanunu tawö; awena dania öhalö khöu zomasi''ö! ba imane: Tenga, dölö be''e — ba na lö''ö, ba u''anösö''ö wangai.', '[]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 17, 'Tobali ebua sibai horö nono matua andrö [si darua] khö Yehowa, me lö ba dödöra zumange Yehowa.', '[]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 18, 'Ba Samueli andrö, ba no sangai halöŵö föna Yehowa, iraono sobaru ba doto, tarafali.', '["Faigi 1:27"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 19, 'Ba itagutagu khönia na mbaru sanau, side-ide, inania, ero röfi i''ohe khönia, na möi ia misi yaŵa, awö ngambatönia, ba wame''e sumange andrö, sero röfi.', '["Faigi 1:27"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 20, 'Ba ero so ira, ba ifahowu''ö Elikana andrö, awö wo''omonia, Eli, imane: Yamu''ali khöu nga''ötö ba ndra alawe andre Yehowa, fangali nibe''e niwawalö andrö khö Yehowa! Ba awena dania lafuli ira khöra.[9]', '["Faigi 1:27"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 21, 'Ba itolo Khana Yehowa, ba tölu tö khönia nono matua ba dombua nono alawe. Ba ononia Samueli, ba si tedou-dou ba da''ö, khö Yehowa.', '["Faigi 1:27"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 22, 'Ba Eli andrö, ba no niha si no atua sibai. Ba na irongo, hadia ia fefu nilau ndraononia ba Ndraono Gizeraeli fefu, awö wa lahoröni ndra alawe andrö, sangai-ngai halöŵö ba golayama nose wama''ele''ö,[10]', '["MozII 38:8","MozII 21:6","Luk 2:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 23, 'ba imane khöra: Hana wa milau zi manö, nirongogu ba mbanua Yehowa fefu.', '["MozII 38:8","MozII 21:6","Luk 2:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 24, 'Böi mimanö, ya''ami iraonogu! turia si lö sökhi da''ö, nirongogu, ni''ombakhambakha''ö Ndraono Gizeraeli!', '["MozII 38:8","MozII 21:6","Luk 2:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 25, 'Na ba nawönia niha mosala niha ba salaŵa zanguhuku; ba na so horönia khö Yehowa, ba ha niha zi möi sanguhuku? — Ba lö lafondrondrongo niŵa''ö namara; noa sa ihonogöi Yehowa, ibunu ira.[11]', '["MozII 38:8","MozII 21:6","Luk 2:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 26, 'Ba ono matua andrö, Samueli, ba itugu tedou ba itugu falukha ia wa''ebua dödö Yehowa ba fa''ebua dödö niha.[12]', '["MozII 38:8","MozII 21:6","Luk 2:25"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 27, 'Ba so genoni Lowalangi, si möi khö Eli, imane khönia: Da''ö niŵa''ö Yehowa: Noa sa u''oroma''ö ndra''o khö ndra tuau, me sawuyu ira na ba danö Miserayi, barö mbawa ndra Fara''o,', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 28, 'ba no utuyu ira khögu, ere, ba mado Ndraono Gizeraeli andrö fefu, ena''ö same''e sumange ira ba naha wame''e sumange andrö khögu ba sanunu samohua, ba ena''ö ya''ira ziobaru baru ba doto andrö, fönagu, ba no ba danga ndra tuau ube''e zumange andrö nifatörö ba galitö fefu, nibe''e Ndraono Gizeraeli[13] —', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 29, 'Ba hana wa mihundra-hundra zumangegu andrö, nitaba, awö zumange ni''a, niŵa''ögu nibe''e, ba nose andrö? Ba no ebua dödöu ba ndraonou andrö, moroi ba wa''ebua dödöu khögu, tobali esolo ami ba zi sökhi ba zumange andrö fefu, nibe''e Ndraono Gizeraeli khögu.', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 30, 'Andrö imane Yehowa, Lowalangi Ndraono Gizeraeli: Noa sa uŵa''ö, böi tebulö fönagu nga''ötöu, nga''ötö ndra tuau andrö — ba iya''e, ba imane Yehowa: Lö edönado! Ha niha zamosumange ya''o, a''ine, ba ufosumange göi, ba sangositengagö ya''o, ba ni''ositengagö göi.', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 31, 'Irugi baŵa dania, ba urasa da''iomö ba ta''io nga''ötöu, tobali lö''ö sa''ae satua moroi yomo khöu.', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 32, 'Ba anehe''ö dania zi sökhi andrö fefu nibe''egu ba Ndraono Gizeraeli; ba moroi yomo khöu, ba alösu lö''ö sa''ae satua.[14]', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 33, 'Ba ha samösa nga''ötöu zi lö ufaogö ba wangohori ya''ira, ba naha wame''e sumange khögu, ena''ö sabözi ia dania ba ena''ö salangu tödö; ba sato nga''ötöu fefu, ba si mate ba mbawa zi''öli niha.[15]', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 34, 'Tandra khöu zi göna nonou andrö si darua, Hofini ba Fineha: ha samuza ma''ökhö, ba endronga mate ira![16]', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 35, 'Ba ufataro dania khögu gere si lö faröi, solo''ö nikhoi dödögu ba somasi ndra''o; khönia ulau nomo si lö tebulö, ena''ö lö mamalö-malö, wa föna nibayoini andrö khögu soso ia.', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474977, 'OT', 'Samueli I', 2, 36, 'Ba hiza dania: na so zi tosai na nga''ötöu, ba möi mangalulu khönia, mangandrö kefe, ba ma kue sagörö, wanguma''ö: Tehe khögu halöŵö gere hadia ia, ena''ö usöndra gögu ma''ifu!', '["MozII 28:6; MozIII 10:14","RazI 2:27","SamI 22:18","Faigi 4:11"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 1, 'Ba ono matua andrö, Samueli, ba no sangai halöŵö föna Yehowa, barö mbawa Eli. Ba fehede Yehowa, ba ha ŵaraö, me luo da''ö, ba angilata, ba mo''otalua sibai.[1]', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 2, 'Ba me luo da''ö, me mörö Eli ba nahania — no abösi hörönia, lö''ö sa''ae i''ila niha;', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 3, 'ba lö''ö na sa mubunu wandru andrö khö Lowalangi; ba Samueli, ba no mörö göi, ba gosali Yehowa, ba zi so tawöla andrö khö Lowalangi[2] —', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 4, 'ba mu''ao Yehowa khö Zamueli, ba imane:', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 5, 'Ya''e ndra''odo! Ba möi ia khö Eli, imane: Ya''e ndra''odo, me no mu''ao''ö khögu. Ba imane Eli: Lö si''aodo khöu, ae fuli förö! Ba möi ia, ifuli mörö.', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 6, 'Ba mu''ao zamuza tö Yehowa, imane: He Samueli! Ba maoso Zamueli, möi khö Eli, imane: Ya''e ndra''odo, noa sa mu''ao''ö khögu! Ba imane Eli: Lö si''aodo khöu, onogu; ae fuli förö!', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 7, 'Lö''ö na sa aboto ba dödö Zamueli Yehowa ba lö''ö na sihede khönia Yehowa.', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 8, 'Ba ifuli mu''ao Yehowa khö Zamueli, medölu sa''ae. Ba maoso Zamueli, möi khö Eli, imane: Ya''e ndra''odo, noa sa mu''ao''ö khögu! Awena aboto ba dödö Eli, wa no Yehowa zi''ao ba ndraono andrö.', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 9, 'Andrö imane Eli khö Zamueli: Ae fuli förö; ba na muhede ia khöu, ba ömane: Hede Yehowa! Irongo enoniu! Ba möi Zamueli, ifuli mörö ba nahania.', '["Amos 8:11","MozII 27:20"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 10, 'Ba so Yehowa, i''agö da''ö ba mu''ao, si mane mege: He Samu''eli! He Samueli! Ba imane Samueli:', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 11, 'Hede, irongo enoniu! Ba imane Yehowa khö Zamueli: Hiza, so dania nilaugu ba Ndraono Gizeraeli, ba dozi samondrongo, ba afökhö dögi dalinga ma''adombua.[3]', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 12, 'Na luo da''ö, ba ahori ufatörö khö Eli niŵa''ögu ba zi samba omo andrö khönia — ubörögö ba u''asiwai göi.', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 13, 'Ba ya''ugö zangombakha khönia, wa no u''etu''ö huku zi samba omo andrö khönia, si lö fulitö, me no i''ila, wa no sango''aya Lowalangi ndraononia andrö, ba me lö nitenaŵania ya''ira.', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 14, 'Ba no fahölu ndra''o, ba zi samba omo ndra Eli andrö, no umane: Si ndruhu, irugi zi lö aetu, ba lö fameta horö zi samba omo ndra Eli andrö, he sumange nitaba, ba he sumange ni''a!', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 15, 'Ba mörö Zamueli, irege moluo. Ba me moluo, ba maoso ia mamokai bawandruhö gosali Yehowa. Ba ata''u Zamueli i''ombakha''ö khö Eli ni''ilania andrö.', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 16, 'Ba humede Eli khö Zamueli, imane: He onogu Samueli! Ba imane: Ya''e ndra''odo!', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 17, 'Ba imane Eli: Hadia ia, niŵa''önia khöu? Böi bini''ö khögu; yamulau khöu Lowalangi, na öbini''ö khögu hadia ia, niŵa''önia khöu!', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 18, 'Ba ahori i''ombakha''ö khönia Samueli, lö hadia ia ibini''ö. Ba imane Eli: Yehowa ia; yamulau zomasi ia![4]', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 19, 'Ba manöi Zamueli, ba itolo ia Yehowa; lö ibe''e aekhu ba danö hadia ia niŵa''önia mege.', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 20, 'Ba aboto ba dödö Ndraono Gizeraeli fefu, i''otarai Dano, numalö ba Mbereseba, wa no sama''ele''ö si lö faröi Zamueli, khö Yehowa.', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474978, 'OT', 'Samueli I', 3, 21, 'Ba itohugö Yehowa, wangoroma''ö ya''ia ba Zilo; khö Zamueli sa''ae i''oroma''ö ia Yehowa ba Zilo: humede khönia Yehowa.', '["Yer 19:3","SamII 15:26"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 1, 'Ba humede Zamueli ba Ndraono Gizeraeli fefu; ba maoso Ndraono Gizeraeli, möi fasuwö ba Ndrawa Wilisiti, la''iagö ngai Ebeni Haezeri, ba ba ngai Nafeki so Ndrawa Wilisiti.', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 2, 'Ba lalau ba Ndraono Gizeraeli Dawa Wilisiti; ba lö''ö sa fagölö-gölö wa''abe''e wasöndrata; te''ala Ndraono Gizeraeli labe''e Dawa Wilisiti; mato 4.000 zi mate, ba zi fasöndra ira, ba mbolo mbenua.', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 3, 'Ba me no mangawuli ba golombaseŵa zato, ba lamane salaŵa Ndraono Gizeraeli: Hana wa ibe''e Yehowa te''ala ita ba Ndrawa Wilisiti ma''ökhö? Datahalö khöda dawöla zura goroisa Yehowa ba Zilo, ena''ö möi ia awöda, ba wangefa''ö ya''ita ba danga nemalida andrö!', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 4, 'Ba lafatenge ba Zilo sato, ba lahalö dawöla goroisa Yehowa ngahönö, sidadao yaŵa Kerubi; ba iraono Eli andrö si darua, Hofini ba Fineha, ba fao ba dawöla goroisa Lowalangi andrö.[1]', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 5, 'Ba me irugi golombaseŵa tawöla goroisa Yehowa, ba lakaraini wa''iki Iraono Gizeraeli fefu, irege humisi danö.', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 6, 'Ba me larongo wa''owua-wua dödö andrö Dawa Wilisiti, ba lamane: Hadia wa''iki andrö, sabölö-bölö sibai, ba golombaseŵa niha Heberaio? Ba me larongo, no irugi golombaseŵa tawöla andrö, khö Yehowa,', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 7, 'ba ata''u Ndrawa Wilisiti, lamane sa''ae dödöra: Lowalangi zi möi khöra ba golombaseŵa. Ba lamane: Alai ita sa''ae, lö''ö sa irai föna si mane da''ö! Alai ita!', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 8, 'Ha niha zangefa''ö ya''ita ba danga Lowalangi sabölö andrö? Da''ö Lowalangi andrö, samatörö ba Ndrawa Miserayi no ngawalö wamakao ba fökhö waba!', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 9, 'Ba mi''abe''e''ö dödömi, ya sabölö ami, ya''ami, Dawa Wilisiti, fa böi möi sawuyu niha Heberaio ami, si mane ya''ira, me no möi sawuyumi. Ya sabölö ami, ba milau![2]', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 10, 'Ba lalau Dawa Wilisiti; ba te''ala Ndraono Gizeraeli ba moloi, isaŵa khöra zamösana: No abölö sibai wa''ate''ala; 30.000 zi mate Iraono Gizeraeli, si lö kudo.', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 11, 'Ba tawöla andrö khö Lowalangi, ba larabu [Dawa wilisiti] ba iraono Eli andrö, si darua, Hofini ba Fineha, ba mate nibunu.[3]', '["MozII 25:22; Sin 80:2","Sanguhuk 13:1","Faigi 2:34"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 12, 'Ba so zoloi, samösa, mado Mbeniyami, iröi wasöndrata ba irugi Zilo, me luo da''ö; no isika nukhania ba no ilau danö ba högönia.[4]', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 13, 'Ba me irugi, ba no dumadao Eli ba kurusi, ba ngai mbawa göli, ifaigi-faigi lala; ibusi tödö sa''ae dawöla khö Lowalangi. Ba me so niha andrö, ba wangombakha ba mbanua, ba mu''ira-ira mbanua andrö, dozi.', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 14, 'Ba me irongo wekira andrö Eli, ba imane: Hadia wagua-guasa andrö? Ba i''aliogö ia niha andrö, ba wangombakha khö Eli.', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 15, 'Ba Eli andrö, ba no 98 fakhe, ba no abösi hörönia, tobali lö''ö sa''ae i''ila niha.', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 16, 'Ba me imane niha andrö khö Eli: Ya''odo zi otarai wanuwö andrö, ma''ökhö andre u''otarai wasöndrata andrö. Ba imane Eli: He wisa, onogu?', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 17, 'Ba itema linia sangombakha andrö, imane: No moloi Ndraono Gizeraeli labe''e Dawa Wilisiti, ba no ato sibai zi mate motöi khöda, ba he iraonou si darua, Hofini ba Fineha, ba no mate göi, ba tawöla khö Lowalangi, ba no mu''oloi''ö!', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 18, 'Ba me itorö linia dawöla andrö khö Lowalangi, ba tobö''a furi Eli moroi ba kurusi, alau, afatö mbagi ba mate ia, me no niha satua, sesolo sibai. No öfa wulu fakhe sanguhuku ia ba Ndraono Gizeraeli.', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 19, 'Ba umönönia, fo''omo Wineha, ba no manabina. Ba me irongo duria andrö, wa no muhalö dawöla andrö khö Lowalangi, awö wa no mate namania andrö ba fo''omonia, ba tegaölö tou ia ba madono; afökhö sa''ae hulunia.', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 20, 'Ba me aetu nosonia, ba lamane ira alawe, si so ba ngainia: Böi busi dödöu, ono matua nonou andre! Ba lö''ö sa itema li, lö ba dödönia,[5]', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 21, 'ibe''e töi nononia, andrö Ikabodi (si lö töi), imane: No taya lakhömi Ndraono Gizeraeli! — börö wa''ataya dawöla andrö, khö Lowalangi, ba amania andrö ba fo''omonia.[6]', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474979, 'OT', 'Samueli I', 4, 22, 'Ba mu''ao ia, imane: No taya lakhömi Ndraono Gizeraeli, me no mu''oloi''ö dawöla khö Lowalangi!', '["Yos 7:6; SamII 1:2","MozI 35:17","Sin 78:61"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 1, 'Ba no lahalö khöra dawöla andrö khö Lowalangi Dawa Wilisiti; la''ohe ba Gasoto, la''otarai Ebeni Haezeri.', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 2, 'Ba latema lahalö dawöla andrö khö Lowalangi Dawa Wilisiti, la''ohe ba gosali Dagono, ba ngai Dagono labe''e.[1]', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 3, 'Ba mahemolu ö, me möi ba gosali Dagono mbanua Gasoto, ba hiza, no aso''a Dagono andrö, föna dawöla khö Yehowa, no tetaru mbagi. Ba lahalö Dagono, lafuli lafasindro ba nahania.', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 4, 'Ba mahemolu ö, si hulö wongi, ba hiza, ba no ifuli tetaru mbagi Dagono föna dawöla khö Yehowa, högönia ba tangania ma''adua ba no ateu, ba doyo mbawandruhö so; hatö botonia zi tosai.', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 5, 'Andrö wa lö lahundragö doyo mbawandruhö Dagono ba Gasoto ere andrö khönia ba ma ha niha, na so zi möi ba gosalinia, irugi ma''ökhö andre.', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 6, 'Ba no tohare sibai ba mbanua Gasoto andrö danga Yehowa, ifeta''u ira ba ibözi ira faosa waba [fökhö famunu], banua Gasoto, fabaya si tefasui ya''ira.[2]', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 7, 'Ba me la''ila da''ö banua Gasota andrö, ba lamane: Böi ya soso ba khöda dawöla andrö khö Lowalangi Ndraono Gizeraeli; noa sa tohare sibai khöda dangania, ba khö Lowalangida Dagono.', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 8, 'Ba lafatenge, ba lafalukha''ö zalaŵa Ndrawa Wilisiti fefu, ba khöra, ba lamane: He mawisa dawöla andrö khö Lowalangi Ndraono Gizeraeli? Ba lamane [salaŵa no mege]: Ndramu''ohe ba Gata dawöla andrö, khö Lowalangi Ndraono Gizeraeli. Ba la''ohe ia ba da''ö.', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 9, 'Ba me no irugi da''ö ba göna tanga Yehowa mbanua da''ö, fa''atobali dödö sabölö-bölö sibai: ibözi mbanua andrö, he satua, ba he iraono, ba tobali tumbu-tumbu khöra waosa.', '["Sanguhuk 16:23","Sin 78:66"]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 10, 'Ba lafa''ohe''ö ba Nekerona dawola andrö khö Lowalangi. Ba me irugi Nekerona, ba mangarö-ngarö mbanua Nekerona, lamane: No la''ohe khöma dawöla andrö khö Lowalangi Ndraono Gizeraeli, ba wamunu ya''aga, banuama fefu!', '[]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 11, 'Ba lafatenge, lafalukha''ö zalaŵa Ndrawa Wilisiti fefu, lamane: Mifa''ohe''ö dawöla andrö khö Lowalangi Ndraono Gizeraeli, ena''ö mangawuli ba nahania ba ena''ö böi möi famunuma ba famunu mbanuama! Noa sa tobali sibai dödö mbanuara fefu, sahatö-hatö famunura; no tohare sibai khöra danga Lowalangi.', '[]', NULL),
  (3474980, 'OT', 'Samueli I', 5, 12, 'Ba si lö mate, ba tefakao faosa waba, ba terongo ba mbanua si yaŵa wangarö-ngarö mbanua andrö.', '[]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 1, 'Ba me no fitu waŵa dawöla andrö ba danö Ndrawa Wilisiti,', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 2, 'ba humede Ndrawa Wilisiti ba gere ba ba zi faeta, lamane: He tawisa ba dawöla andrö khö Yehowa? Mi''ombakha''ö khöma, he tawisa wamuli ya''ia ba nahania.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 3, 'Ba lamane: Na mifa''ohe''ö dawöla andrö, khö Lowalangi Ndraono Gizeraeli, ba böi mifa''ohe''ö manö, lö mufo''awö; mifao sa''ae khönia wanala''ö, ba döhö dania wökhömi, ba oroma khömi, hana wa lö aefa khömi dangania.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 4, 'Ba lamane: Hadia nibe''e fanala''ö? Ba lamane [si faeta no mege]: Dali wa''ato zalaŵa Ndrawa Wilisiti: lima ngawua famaedo waoso waba andrö, ana''a ba lima wamaedo de''u ndröfi, ana''a, me no faoma göna ami famakao andrö, he ya''ami, ba he salaŵami.[1]', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 5, 'Ba mifazökhi wamaedo waosa waba andrö khömi ba famaedo de''u ndröfi khömi, samakiko tanö, ba wamosumange Lowalangi Ndraono Gizeraeli andrö: ma atö lö itohugö ihare''ö dangania khömi ba khö Lowalangimi andrö ba ba danömi.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 6, 'Hana sa wa edöna ami mi''abe''e''ö dödömi, si mane Dawa Miserayi föna, me la''abe''e''ö dödöra, awö Wara''o? Hadia, fayagu? me i''o''aya ira, awena lafofanö [Ndraono Gizeraeli]?[2]', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 7, 'Ba milabu, mihalö [zoguna] ba mifazökhi kureta si bohou, ba mihalö zigelo zaŵi, si bohou mo''ono, dua geu, ba zi lö irai tohare galo mbagi; mibe''e sondröni kureta andrö saŵi andrö ba miheta khöra nonora, mifuli mi''ohe ba nahara.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 8, 'Ba mihalö dawöla andrö khö Yehowa, mibe''e ba gureta andrö. Ba ana''a andrö, nibe''emi fanala''ö, ba mibe''e ba wetifeti, ba ngainia, ba mifofanö.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 9, 'Ba mifaigi: na itörö lala ba wangawuli ba Mbetiseme, ba no Ya''ia [Lowalangi] zamatörö khöda famakao sabölö-bölö andrö; ba na tenga, ba aboto ba dödöda, wa tenga tangania zi tohare khöda: so manö, lö mila, zi no göna ita.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474981, 'OT', 'Samueli I', 6, 10, 'Ba la''o''ö da''ö, dua geu lahalö saŵi si bohou mo''ono, ba labe''e sondröni kureta; ba onora, ba lö lafa''amöi.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 11, 'Ba labe''e ba gureta dawöla andrö khö Yehowa, fabaya fetifeti, si so bakha famaedo de''u ndröfi ana''a andrö, awö wamaedo waosara andrö.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 12, 'Ba ladölö ira ba Mbetiseme saŵi andrö; lala sebua manö latörö, labato wendröndröndröndrö, ba lö lahole''ö ira, he ba gambölö, ba he ba gabera; ba la''o''ö salaŵa Ndrawa Wilisiti, irugi ba nola Mbetiseme.', '["Yos 13:3","MozII 8:11; MozII 12:31"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 13, 'Ba banua Mbetiseme, ba mamasi sibai gandru ba ndraso. Ba me lafakhölö ira ba me la''ila dawöla, ba omuso dödöra, me no so ia.', '[]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 14, 'Ba me no irugi nowi Yosua kureta andrö, ba tebato ia ba da''ö. Ba no so gowe sebua ba da''ö. Ba lasila geu gureta andrö, ba labe''e sumange Yehowa nitunu zaŵi andrö.', '[]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 15, 'Ba labe''e tou dawöla khö Yehowa ono Lewi, fabaya feti-feti andrö ba ngainia, si so bakha ana''a andrö, ba latou''ö tou ba dete gowe sebua andrö. Ba banua Mbetiseme andrö, ba labe''e zumange nitunu, lataba khö Yehowa zumange nitaba, me luo da''ö.', '[]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 16, 'Ba lafaigi-faigi salaŵa Ndrawa Wilisiti andrö, si dalima ba awena lafuli ira ba Nekerona, oi me luo da''ö.', '[]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 17, 'Ba da''ö wamaedo waosa waba andrö, nibe''e Ndrawa Wilisiti khö Yehowa, fanala''ö: sambua ba Gasoto ba sambua ba Gasa, ba sambua ba Asekalo, ba sambua ba Gata, ba sambua ba Nekerona.', '[]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 18, 'Ba awö de''u ndröfi ana''a andrö, dali wa''oya mbanua Ndrawa Wilisiti andrö fefu, barö mbawa zalaŵa andrö, si dalima, ba banua saro andrö, ba he banua side-ide ba danö misa. Ba no tandra-tandra gowe sebua andrö, ba nibe''era ba dete tawöla khö Yehowa, ba mbenua Yosua andrö, banua Mbetiseme, irugi ma''ökhö andre.', '[]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 19, 'Ba iraono Yekhonia, banua Mbetiseme, ba te''ala, me no lafaigi nösi dawöla andrö khö Yehowa; 70 ibunu banuara. Ba abu dödö zato, me no si manö wa''ato ibunu banuara Yehowa.[3]', '["MozIV 4:20; SamII 6:6,7"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 20, 'Lamane banua Mbetiseme andrö: Ha niha zi lö te''ala föna Yehowa, Lowalangi ni''amoni''ö andrö? Ba ha khö idölö ia, ba khöda andre?', '["MozIV 4:20; SamII 6:6,7"]', NULL),
  (3474981, 'OT', 'Samueli I', 6, 21, 'Ba lafatenge ba mbanua Giriati Yeari, lamane khöra: No la''ohe mangawuli dawöla khö Yehowa Dawa Wilisiti, mi''ae mitou, mihalö ia miyaŵa khömi!', '["MozIV 4:20; SamII 6:6,7"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 1, 'Ba so mbanua Giriati Yeari, lahalö miyaŵa dawöla khö Yehowa; ba nomo Gabinadabi la''ohe, ba hili-hili, ba lafataro nononia Eleazari, ba wamaigi-maigi tawöla andrö, khö Yehowa.', '["Nga''ötI 13:6"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 2, 'Ba i''otarai luo labe''e ba Giriati Yeari dawöla, ba ara dania, ikhamö dua wulu fakhe; ba lafuli ira khö Yehowa ma''uwu Gizeraeli fefu.[1]', '["Nga''ötI 13:6"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 3, 'Ba humede Zamueli ba ma''uwu Gizeraeli fefu, imane: Na a''oi dödömi wamuli ya''ami khö Yehowa, ba miheta ba khömi Lowalangi niha baero andrö ba Asaroti andrö; khö Yehowa midölö dödömi, ha ya''ia mifosumange — ba i''efa''ö ami ba danga Ndrawa Wilisiti.[2]', '["MozI 35:2; Yos 24:23","Sanguhuk 10:6,16","Faigi 10:17; Sanguhuk 11:11; 20:1"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 4, 'Ba laheta Mba''ali andrö, fabaya Asaroti, Iraono Gizeraeli, ba hatö Yehowa lafosumange.[3]', '["MozI 35:2; Yos 24:23","Sanguhuk 10:6,16","Faigi 10:17; Sanguhuk 11:11; 20:1"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 5, 'Ba imane Samueli: Mifalukha''ö Ndraono Gizeraeli fefu, ba Misefa, ba mangandrö ndra''o khö Yehowa, salahimi![4]', '["MozI 35:2; Yos 24:23","Sanguhuk 10:6,16","Faigi 10:17; Sanguhuk 11:11; 20:1"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 6, 'Ba owulo ira ba Misefa ba lata''u nidanö ba lafaduwa föna Yehowa ba mamoni ba gö ira, me luo da''ö, ba latehe ba da''ö, lamane: No mafazökhi horö khö Yehowa. Ba ifatunö huhuo Ndraono Gizeraeli Samueli, ba Misefa.', '["MozI 35:2; Yos 24:23","Sanguhuk 10:6,16","Faigi 10:17; Sanguhuk 11:11; 20:1"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 7, 'Ba me larongo Dawa Wilisiti, wa no owulo Ndraono Gizeraeli ba Misefa, ba so moroi sa zalaŵa Ndrawa Wilisiti, möi fasuwö ha Ndraono Gizeraeli. Ba me larongo da''ö Iraono Gizeraeli, ba ata''u ira Ndrawa Wilisiti andrö;', '["Faigi 12:23"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 8, 'ba mangandrö ira khö Zamueli, lamane: Böi bato we''angaröfi li Lowalangida, Yehowa, salahima, ena''ö i''efa''ö ita ba danga Ndrawa Wilisiti![5]', '["Faigi 12:23"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 9, 'Ba ihalö nono mbiri-biri, si lö aefa na ba mbagi zusu, ba ibe''e sumange Yehowa, nitunu, sumange sahori latunu. Ba fakao khö Yehowa Zamueli, salahi Ndraono Gizeraeli, ba ifondrondrongo khönia Yehowa.', '["Faigi 12:23"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 10, 'Ba me itunu si''aikö zumange andrö Samueli, ba so Ndrawa Wilisiti, ba wasuwöta andrö ba Ndraono Gizeraeli. Ba ife''ugu-ugu sibai mbanua Yehowa, ba Ndrawa Wilisiti andrö, me luo da''ö, ba fawuka dödöra ibe''e, ba tobali abölö Ndraono Gizeraeli.', '["Faigi 12:23"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 11, 'Ba laröi Misefa Iraono Gizeraeli, lagohi Ndrawa Wilisiti ba labubunu, irugi tou Mbetikari.', '["Faigi 12:23"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 12, 'Ba ihalö gowe sebua Samueli ba itaru''ö ba gotaluara Misefa Yesana. Ba ibe''e töinia Ebeni-Haeseri (gowe wanolo) ba imane: Irugi da''e no itolo Yehowa!', '["Faigi 12:23"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 13, 'Tobali tehöndrögö Ndrawa Wilisiti, tobali lö''ö sa''ae larugi danö Ndraono Gizeraeli, tohare sa''ae ba Ndrawa Wilisiti danga Yehowa, götö wa''anau noso Zamueli.', '["Faigi 12:23"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 14, 'Ba banua Ndraono Gizeraeli andrö, ni''okhögö Ndrawa Wilisiti, ba mangawuli ba Ndraono Gizeraeli, i''otarai Nekerona, numalö ba Gata; ba tanöra göi, ba lafadöni ba Ndrawa Wilisiti Iraono Gizeraeli. Ba atulö ira Ndraono Gizeraeli Ndraono Gamori.', '["Faigi 12:23"]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 15, 'Ba sanguhuku Iraono Gizeraeli Zamueli, sagötö ya''ia.', '[]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 16, 'Ba ero röfi itöröi mbanua, itörö Mbetieli ba Giligala ba Misefa, ba ifatunö huhuo Ndraono Gizeraeli ba mbanua andrö fefu.', '[]', NULL),
  (3474982, 'OT', 'Samueli I', 7, 17, 'Awena dania ifuli ia ba Rama; ba da''ö sa so nomonia, ba ba da''ö ifatunö huhuo bö''ö. Ba ifa''anö ba da''ö naha wame''e sumange khö Yehowa.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 1, 'Ba me atua sa''ae Zamueli, ba iraononia ifataro sanguhuku Iraono Gizeraeli.', '["Nga''ötI 6:13","MozV 16:19"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 2, 'Töi nononia si a''a, ba Yoeli, ba Abia döi nakhinia; da''ö zamatunö huhuo, ba Mbereseba.[1]', '["Nga''ötI 6:13","MozV 16:19"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 3, 'Ba lö la''o''ö gamuatania iraononia andrö: la''alui harera ba manga gana''a ba lafuyu''ö huku.[2]', '["Nga''ötI 6:13","MozV 16:19"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 4, 'Ba falukha zalaŵa Ndraono, Gizeraeli, möi khö Zamueli ba Rama,[3]', '["Faigi 7:17","MozV 17:14; Hos 13:10; HalZin 13:21"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 5, 'lamane khönia: Hiza, atua ndra''ugö, ba iraonou andrö, ba lö la''o''ö gamu''atamö andrö: ba fataro sa''ae khöma razo, samatörö ya''aga, si mane ba niha baero fefu.[4]', '["Faigi 7:17","MozV 17:14; Hos 13:10; HalZin 13:21"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 6, 'Ba fatuwu khö Zamueli, me laŵa''ö: Be''e khöma razo, samatörö ya''aga. Ba mangandrö Zamueli khö Yehowa.', '["Faigi 7:17","MozV 17:14; Hos 13:10; HalZin 13:21"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 7, 'Ba imane Yehowa khö Zamueli: Fondrondrongo li zato, fefu hadia ia niŵa''öra khöu. Tenga sa ya''ugö nitibo''öra, ya''odo a''ine nitibo''öra, fa böi sa''ae razora ndra''odo.', '["Faigi 7:17","MozV 17:14; Hos 13:10; HalZin 13:21"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 8, 'No faudu sibai ira nilaura khöu iada''e nilaura föna sa''ae, i''otarai luo u''ohe ira miyaŵa moroi ba danö Miserayi, me no la''erogö ndra''o ba me no lafosumange Lowalangi bö''ö.', '["Faigi 7:17","MozV 17:14; Hos 13:10; HalZin 13:21"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 9, 'Ba o''ö sa''ae niŵa''öra, ba faulugö göi wamangelama ya''ira, ombakha''ö khöra gömöra khö razo andrö, samatörö ya''ira dania.', '["Faigi 7:17","MozV 17:14; Hos 13:10; HalZin 13:21"]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 10, 'Ba ahori i''ombakha''ö Samueli niŵa''ö Yehowa khönia, ba niha sato, sangandrö razo khönia, ba imane na:', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 11, 'Amaedola zugilö razo andrö, samatörö ya''ami, dania khömi, ba ihalö nonomi matua ba ibali''ö tuka gureta khönia ba tuka kudo, ena''ö latari-tari föna guretania, si fagohi,', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 12, 'ba ena''ö ibe''e kumandra zi hönö ba kumandra zi lima wulu, ba ba wamaku nowinia ba ba wamasi basitönia, ba ena''ö lafazökhi fangöna khönia ba fakake gureta.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 13, 'Ba onomi alawe, ba ihalö, ba ibe''e samazökhi dalu-dalu ba same''e bawu gö ba sogore kue.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 14, 'Ba ba nowimi ba ba kabu nagu khömi ba ba kabu falo, ba si sökhi, ba ihalö, ba ibe''e ba genoninia.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 15, 'Ba bua nowimi ba bua nagu khömi, ba sambua ni''ofulu ihalö, ba ibe''e ba zawuyunia ba ba ngoni-ngoninia.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 16, 'Sawuyumi, ira matua ba ira alawe, fabaya saŵimi fondrege zi sökhi ba kalidemi, ba ihalö, ba i''oguna''ö ba halöŵö andrö khönia.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 17, 'Ba ba mbiri-birimi, ba sambua ni''ofulu i''okhögö.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 18, 'Ba na mangarö-ngarö ami dania, börö razomi andrö, nituyumi khömi, ba lö''ö sa ifondrondrongo khömi Yehowa.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 19, 'Ba lö edöna niha sato lafondrondrongo niŵa''ö Zamueli, lamane: Böi, razo zomasiga!', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 20, 'Ena''ö fagölö-gölö ndra''aga ba niha baero andrö, fefu, ena''ö samatunö huhuoma razoma andrö ba solohe ya''aga ba wanuwö.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 21, 'Ba ifondrongondrongo Samueli niŵa''ö zato, fefu, ba ifa''ema khö Yehowa.', '[]', NULL),
  (3474983, 'OT', 'Samueli I', 8, 22, 'Ba imane Yehowa khö Zamueli: O''ö ni''andröra ba fataro khöra razo! Ba imane Samueli ba Ndraono Gizeraeli: Mifuli ami, yamusaŵa mbanuara zamösana![5]', '["Ayati 7,9"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 1, 'Ba so mbanua Gibea ba mado Mbeniyami, Kisi döinia, ono Gabieli, ma''uwu Zeroro, dua götö ma''uwu Mbekhorati, tölu nga''ötö ma''uwu Gafia, ono mado Mbeniyami, no niha sabölö.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 2, 'Ba so nononia matua, Saulo döi, sebua niha ba si sökhi boto; lö falukha ba Ndraono Gizeraeli si sökhi moroi khönia: ha famalaŵa baginia niha sato fefu.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 3, 'Ba no musuna galide si alawe khö Kisi andrö, Ama Zaulo. Ba imane Kisi khö nononia Saulo: Ohe awöu zawuyu, samösa, ba ae alui galide andrö.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 4, 'Ba latörö hili mado Geferayi andrö ba tanö Zaliza, ba lö lasöndra. Ba latörö danö Za''alimi, ba lö ya''ira: awena dania latörö danö mado Mbeniyami, ba lö lasöndra.[1]', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 5, 'Ba me larugi danö Zufi, ba imane Saulo khö nono matua andrö, ni''ohenia awönia: Tabu, tafuli ita; ma iböhöli galide andrö amagu, ma ya''ita i''abusi tödö.[2]', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 6, 'Ba imane khönia: Ba mbanua da''e, ba so genoni Lowalangi, niha sebua turia: fefu hadia niŵa''önia, ba lö zi lö itörö. Taisa khönia! ma i''ombakha''ö khöda lalada, nitöröda.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 7, 'Ba imane Saulo khö nono matua andrö: Lau, ba na möi ita khönia, ba hadia ta''ohe ö niha andrö? Noa sa ahori roti andrö ba mbolada, ba lö khöda buala, ni''oheda ena''ö khö genoni Lowalangi andrö. Hadia zi so khöda?', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 8, 'Ba ifuli muhede nono matua andrö khö Zaulo, imane: Hiza, so na khögu zambua hua tali, hana na öbe''e da''ö khö genoni Lowalangi andrö, ena''ö iŵa''ö khöda, he lala nitöröda.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 9, 'Me föna sa, ba lamane ba Ndraono Gizeraeli, na möi manofu khö Lowalangi: Mitabu, möi ita khö zangi''ila andrö! Nifotöi sama''ele''ö iada''e, ba me föna, ba sangi''ila labe''e töira.[3]', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 10, 'Ba imane Saulo khö nono matua andrö khönia: Si ndruhu niŵa''öu. Tabu, möi ita khönia! Ba lasaŵa miyomo ba mbanua andrö, ba zi so enoni Lowalangi andrö.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 11, 'Ba ba lala miyaŵa ba mbanua, ba falukha ira nono alawe, si möi mitou, ba wana''u idanö; ba lamane ba da''ö: Hadia, so ba da''e zangi''ila andrö?', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 12, 'Ba latema lira, lamane: So, hiza ia fönami; awena sibai irugi yomo ba mbanua — me mame''e sumange niha sato ba hili-hili ma''ökhö.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 13, 'Na mirugi yomo, ba fakhamö sibai na ami khönia, gasa-gasa we''amöinia ba wemanga ba naha wame''e sumange andrö. Lö''ö sa manga zato, na lö ya''ia, me ya''ia zamahowu''ö sumange andrö, ba awena dania manga nikaoni andrö. Ba mi''ae manö miyaŵa, fakhamö sibai ami khönia iada''e.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 14, 'Ba möi ira miyaŵa, miyomo. Ba me no latörö sibai mbawa göli, ba faondra khöra Zamueli moroi yomo, ba we''amöi miyaŵa ba naha wame''e sumange.', '["Yoh 3:23","Faigi 10:2","RazII 17:13; Nga''ötI 9:22; MozIV 24:3"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 15, 'Ba no ibokai khö Zamueli Yehowa, sara wongi lö Saulo na, no imane:', '[]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 16, 'Mane wa''alaŵa luo mahemolu, ba ufatenge khöu niha, si oroi danö mado Mbeniyami, da''ö öbayoini razo mbanuagu Iraono Gizeraeli. Ya''ia dania zangefa''ö banuagu ba danga Ndrawa Wilisiti; noa sa unehegö wamakao banuagu andrö, me no irugi ndra''o wangarö-ngaröra andrö.', '[]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 17, 'Ba me i''ila Zaulo andrö Samueli, ba imane khönia Yehowa: Da''ö niha andrö, niŵa''ögu khöu, da''ö dania zamatörö banuagu.', '[]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 18, 'Ba i''ondrasi Zamueli Saulo, ba dalu mbawa göli andrö, imane: Ombakha''ö khögu, hezo nomo zangi''ila andrö.', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 19, 'Ba imane Samueli khö Zaulo: Ya''odo zangi''ila andrö, taisa miyaŵa ba naha wame''e sumange! Manga ami khögu ma''ökhö, ba mahemolu mbanua, ba ufofanö ndra''ugö ba u''ombakha''ö khöu fefu hadia ia zabu dödöu.', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 20, 'Ba ba zigelo galide sisuna khöu, me tölu bongi, ba böi abusi tödö: no musöndra. Ba ha khö fefu hadia ia zebua böli ba Ndraono Gizeraeli? Hadia, tenga khöu ba ba zi samba omo ndra amau, fefu?', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 21, 'Ba imane Saulo: Ba ha sa mado Mbeniyami ndra''odo, mado Ndraono Gizeraeli side-ide, ba si sawu ya''aga, ba no fondrege zide-ide ba ngafu mado Mbeniyami andrö; ba hana wa ömanö wehede khögu?[4]', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 22, 'Ba i''ohe Zaulo ba ono matua andrö khönia, i''ohe yomo, ba tanö yaŵa ifedadao ira, ba ngai nikaoni andrö; so mato tölu ngafulu ira.', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 23, 'Ba imane Samueli ba zangai gö: Be''e gurakha andrö, nibe''egu ba dangau, niŵa''ögu khöu: Be''e yaŵa ua.', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 24, 'Ba ibe''e da''io andrö, awö zi fadoro khönia, sangai gö andrö, ibe''e ö Zaulo. Ba imane Samueli: Hiza zi tosai, labe''e öu, a ia, noa sa labe''e yaŵa khöu, irege ginötö andrö, me no uŵa''ö: Ukaoni niha. Ba urudu manga Zaulo khö Zamueli, me luo da''ö.', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 25, 'Ba lafuli ira mitou, miyomo, ba yaŵa ba dete nomo lafaigi naha wemörö khö Zaulo, ba mörö ia.', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 26, 'Ba me moluo, ba mu''ao Zamueli khö Zaulo, miyaŵa ba dete nomo, imane: Faoso, ena''ö faodo khöu! Ba maoso Zaulo, ba möi ira tou, darua ira Samueli.', '["Faigi 15:17"]', NULL),
  (3474984, 'OT', 'Samueli I', 9, 27, 'Ba me larugi si tou mbalö mbanua, ba imane Samueli khö Zaulo: Fowaö-waö nono matua andrö khöu, ba ya''ugö, ba badugö''ö ba da''e, ena''ö u''ombakha''ö khöu niwa''ö Lowalangi.', '["Faigi 15:17"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 1, 'Ba ituyu mbulibuli wanikha Samueli ba ifaduwa ba högö Zaulo, fa''ago bawa ia khönia, imane: Famayoini Yehowa ya''ugö razo mbanuania andrö, Iraono Gizeraeli. Samatörö banua Yehowa dania ndra''ugö ba ö''efa''ö ira ba danga nemalira. Ba ya da''ö dandra khöu ba da''ö, wa no ibayoini razo ndra''ugö Yehowa, razo ba dana khönia andrö:', '["MozI 35:19","Ayati 10","Faigi 13:8"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 2, 'Na no fabali dania ndra''ugö khögu, na örugi lewatö Rakhela, ba nola mado Mbeniyami, ba falukha''ö niha, darua, ba lamane khöu: Sigelo galide andrö, ni''aluimö, ba no musöndra. Ba lö''ö sa''ae itörö tödö namau galide andrö, ya''ami i''abusi tödö, no imane: He uwisa ba khö nonogu andrö?[1]', '["MozI 35:19","Ayati 10","Faigi 13:8"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 3, 'Ba na mowaö-waö''ö, i''otarai da''ö, ba örugi manawa Dabora andrö, ba falukha''ö niha, datölu, si möi miyaŵa khö Lowalangi ba Mbetieli; si samösa, ba tölu rozi ono nambai, si matua, noronia, ba ba zi samösa, ba tölu roti, ba ba zi samösa, ba samba nahia agu.', '["MozI 35:19","Ayati 10","Faigi 13:8"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 4, 'Ba la''owai ndra''ugö, ba dombua labe''e khöu roti, ba öhalö khöra.', '["MozI 35:19","Ayati 10","Faigi 13:8"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 5, 'Ba aefa da''ö, ba örugi Gibea andrö khö Lowalangi, ba zi so harefa Ndrawa Wilisiti andrö; ba na örugi da''ö, yomo ba mbanua, ba faondra khöu zama''ele''ö, sambawa, si otarai moroi yaŵa naha wame''e sumange. Ba fönara, ba biola nitika, sebua, ba faritia ba sigu ba biola nitika, sideide, ba ya''ira, ba si so eheha zama''ele''ö.', '["MozI 35:19","Ayati 10","Faigi 13:8"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 6, 'Ba so dania khöu Geheha Yehowa ba sama''ele''ö göi ndra''ugö, si mane ya''ira, ba tobali niha si bohou ndra''ugö.[2]', '["MozI 35:19","Ayati 10","Faigi 13:8"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 7, 'Ba na ö''ila dania itörö dandra andrö, ba lau nilaumö, itolo''ö sa Lowalangi.', '["MozI 35:19","Ayati 10","Faigi 13:8"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 8, 'Ba taisa mitou ba Giligala; ba möido dania khöu mitou, ba wame''e sumange nitunu, ba ba wanaba sumange fangorifi: fitu bongi base''ö, irege möido khöu, ba wangombakha khöu, he öwisa.[3]', '["MozI 35:19","Ayati 10","Faigi 13:8"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 9, 'Ba me ibali''ö ia, ba wondröi Samueli ba ifalalini dödönia Lowalangi, ba tandra no mege ba ahori alua me luo da''ö.', '["Faigi 19:20—24"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 10, 'Me larugi Gibea andrö, ba faondra khönia zama''ele''ö, sambawa, ba so khönia Geheha Lowalangi, ba mama''ele''ö ia awöra.[4]', '["Faigi 19:20—24"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 11, 'Ba me la''ila ia dozi si no fa''ila li khönia föna, wa mama''ele''ö ia, awö zama''ele''ö andrö, ba faoma lamane khö nawöra sato: Hadia zi göna ono Kisi andrö? Hadia, awö zama''ele''ö göi Zaulo andrö?', '["Faigi 19:20—24"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 12, 'Ba so ba da''ö zanema li, imane: Ba ha niha namara? Ba da''ö tumbu gamaedola andrö: Hadia, awö zama''ele''ö göi Zaulo?', '["Faigi 19:20—24"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 13, 'Ba me no ibato wama''ele''ö, ba ifuli ia khöra.', '["Faigi 19:20—24"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 14, 'Ba imane ga''a Zaulo khönia ba khö nono matua andrö khönia: Heza möi mege ami? Ba imane Saulo: Ba wangalui sigelo galide andrö; ba me lö''ö manö masöndra, ba möiga khö Zamueli.', '["Faigi 19:20—24"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 15, 'Ba imane ga''a Zaulo: Ombakha''ö khögu hadia niŵa''ö Zamueli khömi.', '["Faigi 19:20—24"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 16, 'Ba imane Saulo khö ga''ania: I''ombakha''ö khöma, wa no musöndra galide andrö. Ba hadia niŵa''ö Zamueli ba wamataro razo ya''ia, ba lö i''ombakha''ö khönia.', '["Faigi 19:20—24"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 17, 'Ba ifalukha''ö zato Samueli, khö Yehowa, ba Misefa.', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 18, 'Ba imane ba Ndraono Gizeraeli: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: No u''ohe miyaŵa Ndraono Gizeraeli, moroi ba danö Miserayi, ba no u''efa''ö ami ba danga Ndrawa Miserayi andrö ba ba danga razo andrö fefu, samakao ya''ami.', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 19, 'Ba ya''ami, ba no mi''erogö Lowalangimi ma''ökhö, Lowalangi andrö, si no manolo ya''ami ba wamakaomi ba ba wa''atosasami, fefu, me no mimane: Böi! razo öfatara khöma! Ba lau, ba mi''ondrasi Yehowa, dali madomi ba dali ngahönö andrö khömi![5]', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 20, 'Ba ifa''aso mado Ndraono Gizeraeli fefu Samueli, ba göna mado Mbeniyami.[6]', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 21, 'Ba ifa''aso mado Mbeniyami andrö, sawu-sawu, ba göna zi sawu nga''ötö Materi. Ba ifa''aso zi sawu nga''ötö Materi andrö, samö-samösa, ba göna Zaulo, ono Kisi. Ba la''alui ia, ba lö lasöndra.', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 22, 'Ba lafuli lasofu khö Yehowa, lamane: Hadia, no möi ba da''e niha andrö? Ba imane Yehowa: Hiza, no ibini''ö ia ba gama-gama andrö.', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474985, 'OT', 'Samueli I', 10, 23, 'Ba fagohi ira mangai ya''ia ba da''ö. Ba me möi ia ba hunö niha bakha, ba ha falaŵa baginia niha sato fefu.', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 24, 'Ba imane Samueli ba niha sato fefu: Hadia, no mi''ila, wa lö ba niha sato si fagölö-gölö ba nituyu Yehowa andrö? Ba mu''ao niha sato fefu, lamane: Ya anau noso razo andrö![7]', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 25, 'Ba i''ombakha''ö ba zato huku ba wa''arazo andrö Samueli, ba itanö ba zura ba ibe''e föna Yehowa. Aefa da''ö, ba ifofanö zato fefu Samueli, ena''ö ifuli ia khöra zamösana.[8]', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 26, 'Ba Saulo göi, ba ifuli ia ba Gibea, ba fao khönia zabölö, nifaduhu''ö Lowalangi tödö;', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474985, 'OT', 'Samueli I', 10, 27, 'ba so ösa si si lö yaŵa, sanguma''ö: Hadia guna da''ö khöda? Ba la''ositengagö ia ba lö mamuala ira khönia.[9]', '["Faigi 8:7","Faigi 14:41; Yos 7:16","RazI 1:25","Faigi 8:11; MozV 17:14—20","Faigi 11:12"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 1, 'Ba mato sara waŵa, ba so moroi sa Nahasi, Iraono Gamoni ba wanuwö Yabesi ba danö Gileadi. Ba lamane banua Yabesi andrö fefu khö Nahasi: Datalau fawu''u li, ba möiga barö mbawau.[1]', '["Faigi 31:11","Yer 39:7"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 2, 'Ba imane khöra Nahasi, Iraono Gamoni: Ba da''ö fawu''u li ita, udozigö ami wogu hörömi kambölö, fango''aya Iraono Gizeraeli fefu![2]', '["Faigi 31:11","Yer 39:7"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 3, 'Ba lamane satua mbanua Yabesi khönia: Fonoso ndra''aga, fitu bongi, ena''ö mafatenge zinenge ba danö Ndraono Gizeraeli ma''asagörö; ba na lö dania sanolo ya''aga, ba mabe''ega ba dangau!', '["Faigi 31:11","Yer 39:7"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 4, 'Ba me larugi Gibea, banua Zaulo andrö, sinenge, me la''ombakha''ö ba zato niŵa''öra, ba mege-ege sibai niha sato fefu.', '["Faigi 31:11","Yer 39:7"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 5, 'Ba hiza, so Zaulo, i''otarai nowi, molohe saŵi ba da''ö. Ba isofu Saulo, imane: Hadia ba niha sato, wa mege-ege? Ba la''ombakha''ö khönia niŵa''ö mbanua Yabesi andrö.', '["Sanguhuk 14:6","Sanguhuk 19:29"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 6, 'Ba me no irongo, he wisa, ba so khönia Geheha Lowalangi, ba mofönu sibai ia.[3]', '["Sanguhuk 14:6","Sanguhuk 19:29"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 7, 'Dua geu ira''u saŵi ba itatawi ba ifatöröi''ö ba danö Ndraono Gizeraeli ma''asagörö, imane: Ha niha zi lö fao khö ndra Saulo Samueli, ba lamanö göi ba zaŵinia! Ba ihawui fa''ata''u khö Yehowa zato fefu, ba möi ira, ha sara dödö.[4]', '["Sanguhuk 14:6","Sanguhuk 19:29"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 8, 'Ba me i''ofaya ira ba Mbeseki, ba no 300.000 Iraono Gizeraeli ba 30.000 ma''uwu Yuda.', '["Sanguhuk 14:6","Sanguhuk 19:29"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 9, 'Ba imane ba zinenge andrö, si möi khöra mege: Mi''ombakha''ö ba mbanua Yabesi ba danö Gileadi: Mahemolu, na aukhu zino, ba so zangorifi ya''ami! Ba lafuli ira sinenge andrö, ba la''ombakha''ö ba mbanua Yabesi, ba omuso dödöra.', '["Sanguhuk 14:6","Sanguhuk 19:29"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 10, 'Ba lafaŵa''ögö khö Nahasi banua Yabesi, lamane: Mahemolu malulu ndra''aga khömi: ba hana na milau khöma zomasi ami.', '["Sanguhuk 14:6","Sanguhuk 19:29"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 11, 'Ba mahemolu mbanua, ba i''otölu bawa niha Saulo, ba lahawui golombaseŵa si hulö wongi, ba ato sibai labubunu Iraono Gamoni, irege aukhu zino. Ba si tosai, ba muzaewe, lö''ö sa''ae si fao si darua khöra.', '["Faigi 10:27","Faigi 14:45","Faigi 10:8"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 12, 'Ba lamane sato khö Zamueli: Ha niha zanguma''ö no: Hadia, razoda Zaulo andrö? Mi''ohe ba dae, ena''ö tabunu ira![5]', '["Faigi 10:27","Faigi 14:45","Faigi 10:8"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 13, 'Ba imane Saulo: Lö tola mate niha ma''ökhö, me no itolo Ndraono Gizeraeli Yehowa ma''ökhö andre.[6]', '["Faigi 10:27","Faigi 14:45","Faigi 10:8"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 14, 'Ba imane Samueli ba niha sato: Mitabu, möi ita ba Giligala, ba wangaro''ö fa''arazo ba da''ö.[7]', '["Faigi 10:27","Faigi 14:45","Faigi 10:8"]', NULL),
  (3474986, 'OT', 'Samueli I', 11, 15, 'Ba möi ba Giligala zato fefu ba lafataro razo Zaulo föna Yehowa ba da''ö, ba Giligala. Ba lataba zumange fangandrö saoha gölö, ba da''ö föna Yehowa, ba somuso sibai tödö Zaulo ba ira matua Ndraono Gizeraeli.', '["Faigi 10:27","Faigi 14:45","Faigi 10:8"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 1, 'Ba imane Samueli ba Ndraono Gizeraeli fefu: Hiza, no ufondrondrongo limi fefu hadia ia niŵa''ömi khögu, ba no ufataro khömi razo.[1]', '["Faigi 8:7,22; 11:25","MozIV 16:15"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 2, 'Ba hiza iada''e, ba sowaö-waö fönami razo andrö; ba ya''o, ba si no atua, ba si no tohare huwa; ba hiza, iraonogu zi so khömi. Ba i''otarai iraono ndra''o, irugi ma''ökhö andre, ba no anehe ami döröŵagu.', '["Faigi 8:7,22; 11:25","MozIV 16:15"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 3, 'Ba ya''e ndra''odo, mi''ae udugu föna Yehowa ba föna nibayoininia andrö! Ha saŵi ba ha kalide nihalögu? Ha niha nifakaogu ba ha niha nihundragögu? Ba heza u''a gana''a, wamakifu hörögu? Mi''adugö ndra''o, ba da''ufuli khömi![2]', '["Faigi 8:7,22; 11:25","MozIV 16:15"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 4, 'Ba lamane: Lö nifakaomö ba lö nihudragömö ya''aga, samösa lö nihalömö hadia ia. Ba imane khöra:', '["Faigi 8:7,22; 11:25","MozIV 16:15"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 5, 'Ya si so ba mbörö Yehowa, ba khömi andrö, ba he nibayoininia andrö, ba ya si so ba mbörö ma''ökhö, wa lö nisöndrami hadia ia, ba dangagu. Ba lamane: Ya''ia da''ö!', '["Faigi 8:7,22; 11:25","MozIV 16:15"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 6, 'Ba imane Samueli ba zato: Si so ba mbörö Yehowa andrö, somböi ira Moze A''aroni, ba solohe miyaŵa ira tuami, moroi ba danö Miserayi!', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 7, 'Ba mi''ondrasi, ena''ö u''ombakha''ö khömi, föna Yehowa, ba ena''ö ufasugi ba dödömi wa''ebua dödö Yehowa andrö fefu, khömi ba khö ndra tuami.', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 8, 'Me no irugi danö Miserayi Yakobo, ba lafakao ira Dawa Miserayi. Ba la''angaröfi li Yehowa ira tuami, ba ifatenge ndra Moze A''aroni, sangeheta ira tuami ba danö Miserayi ba ba danö da''e ifataro ira.', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 9, 'Ba olifu ira Lowalangira Yehowa. Ba i''amawa ira ba danga Zisera andrö, kumandra Yabino andrö, razo Hasora, ba ba danga Ndrawa Wilisiti andrö, ba ba danga razo Ndraono Moabi; tobali lalau khöra.[3]', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 10, 'Ba la''angaröfi li Yehowa, lamane: Horöma, me no ma''erogö Yehowa ba me no mafosumange Mba''ali andrö ba Asera andrö: ba iya''e, ba efa''ö ndra''aga ba danga nemalima andrö, ba ya''ugö mafosumange!', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 11, 'Ba ifatenge Yerubi-Mba''ali andrö Yehowa, ba Baraki ba Yefita ba Samueli, i''efa''ö ami ba danga nemalimi andrö, fasui, tobali lö''ö sa''ae hadia ia khömi, ahono ami baomomi.[4]', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 12, 'Ba me mi''ila, so moroi sa Nahasi andrö, razo Ndraono Gamoni, ba wanuwö ya''ami, ba mimane khögu: Böi! razo zamatörö ya''aga! — lö lai wa no Lowalangimi, Yehowa, razomi.[5]', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 13, 'Ba lau, ba hiza razomi andrö, nituyumi, no ifataro khömi razo Yehowa.', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 14, 'Na mi''ata''ufi Yehowa, na mifosumange ia ba na mifondrondrongo linia, na lö mifadaö niŵa''ö Yehowa, na mi''o''ö khö Lowalangimi Yehowa, he ya''ami, ba he razo andrö, samatörö ya''ami (ba itolo ami Yehowa).', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 15, 'Ba na lö mifondrondrongo li Yehowa, ba na te khömi goroisa Yehowa, ba udumi dania danga Yehowa ba udu razomi andrö.', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 16, 'Ba mi''ondrasi, ba minehegö zebua andrö, nilau Yehowa, ba zanehe ami.', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 17, 'Hadia, tenga baŵa wamasi gandru iada''e? Ba mangandrö ndra''o khö Yehowa, ena''ö mu''ugu mbanua ba ena''ö moteu ibe''e: ba mi''ila dania ba aboto ba dödömi wa''ebua lalömi wamaigi Yehowa, me no mi''andrö razo!', '["Sanguhuk 4:2; 10:7; 13:1; 3:12","Sanguhuk 6:14; 11:29; Faigi 7:3","Faigi 8:19"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 18, 'Ba mangandrö Zamueli khö Yehowa, ba mu''ugu mbanua ba moteu ibe''e Yehowa, me luo da''ö. Ba ata''u sibai niha sato Yehowa ba Samueli.', '["MozV 32:37,38","MozII 19:6","Faigi 7:8","RazII 17:39"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 19, 'Ba lamane khö Zamueli niha sato fefu: Angandrö khö Lowalangimö, Yehowa, salahi zawuyumö andre, fa böi tekiko ndra''aga, me no manönö na horöma andrö fefu lalö andrö, fangandrö razo!', '["MozV 32:37,38","MozII 19:6","Faigi 7:8","RazII 17:39"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 20, 'Ba imane Samueli ba niha sato: Böi mi''abusi tödö: si ndruhu sa, no milau zi lö atulö andrö, fefu — ba böi atö mibato sa''ae, wolo''ö khö Yehowa, mifosumange Yehowa, moroi si''aikö ba dödömi,', '["MozV 32:37,38","MozII 19:6","Faigi 7:8","RazII 17:39"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 21, 'ba böi mi''o''ö waya-faya andrö, si lö guna ba si tenga fangorifimi, me no si lö boto.[6]', '["MozV 32:37,38","MozII 19:6","Faigi 7:8","RazII 17:39"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 22, 'Lö''ö sa itibo''ö mbanuania Yehowa, börö döinia andrö, si no ebua; noa sa atö omasi Yehowa, ibali''ö banuania ami.[7]', '["MozV 32:37,38","MozII 19:6","Faigi 7:8","RazII 17:39"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 23, 'Ba ya aröu göi khögu wamazökhi horö khö Yehowa, wamöhöi fangandrö salahimi: u''oroma''ö sa khömi lala si sökhi andrö, lala sadölö.[8]', '["MozV 32:37,38","MozII 19:6","Faigi 7:8","RazII 17:39"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 24, 'Ba mi''ata''ufi Yehowa, ba böi faröi ami khönia, wamosumange ya''ia, soroi si''aikö ba dödömi; mitöngöni sa''ae zebua andrö, nilaunia khömi![9]', '["MozV 32:37,38","MozII 19:6","Faigi 7:8","RazII 17:39"]', NULL),
  (3474987, 'OT', 'Samueli I', 12, 25, 'Ba na si lö sökhi milau, ba nihori ami, fabaya razomi andrö.', '["MozV 32:37,38","MozII 19:6","Faigi 7:8","RazII 17:39"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 1, 'öfa wulu fakhe Zaulo, me tobali razo ia, ba dua wulu a rua fakhe razo ia ba Ndraono Gizeraeli.', '["Faigi 14:49"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 2, 'Ba itutuyu khönia zi 3.000 niha ba Ndraono Gizeraeli Saulo; 2.000 nawö Zaulo ba Mikhima, ba ba hili ba Mbetieli, ba 1.000 nawö Yonata ba Gibea, ba mado Mbeniyami. Ba si tosai sabölö, ba ifofanö, hana na ifuli ia ba khöra zamösana.', '["Faigi 14:49"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 3, 'Ba irasa harefa Ndrawa Wilisiti andrö ba Geba Yonata. Ba larongo Dawa Wilisiti: No molaŵa niha Heberaio! Ba noa sa''ae ifalau''ö dorofe Saulo, ba danö misa, ma''asagörö,[1]', '["Faigi 14:49"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 4, 'ba larongo Iraono Gizeraeli fefu: No irasa harefa Ndrawa Wilisiti andrö Saulo, ba na aböu manö döi Ndraono Gizeraeli ba Ndrawa Wilisiti. Ba tefakaoni''ö zato, awö Zaulo, ba Giligala,', '["Faigi 14:49"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 5, 'ba noa göi te''anö Ndrawa Wilisiti, ba wanuwö Iraono Gizeraeli, 3.000 gureta ba 6.000 zi fakudo; ba si lö kudo, ba no fa''oya ngawua nene ba mbewe nasi; ba so ira moroi sa, ba ba zinga Mikhima tebato, ba gamaudu Mbeti Awena.', '["Faigi 14:49"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 6, 'Ba me la''ila Iraono Gizeraeli wa''atosasara (no abu sibai dödöra), ba labini''ö ira ba dögi narö hili, ba dögi danö, ba dögi narö gara ba ba lösulö suba ba mba''a,', '["Faigi 14:49"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 7, 'ba latörö götöna ba Yoridano, lasaŵa danö mado Gado ba tanö Gileadi. Ba ba Giligala na sa so Zaulo; ba no laröi ia sabölö fefu, ba wa''ata''ura andrö.', '["Faigi 14:49"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 8, 'Ba fitu bongi ibaloi, irugi ginötö nihonogöi Zamueli, ba lö möi ba Giligala Zamueli. Ba me muzaewe manö niha, me laröi ia,[2]', '["Faigi 10:8","HalZin 13:22"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 9, 'ba imane Saulo: Mi''ohe khögu zumange nitunu andrö, ba sumange fangorifi! ba ibe''e zumange nitunu.', '["Faigi 10:8","HalZin 13:22"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 10, 'Ba me no awai khönia wame''e sumange andrö, ba so Zamueli. Ba ifaondragö ia Saulo, ba wangowai ya''ia.', '["Faigi 10:8","HalZin 13:22"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 11, 'Ba imane Samueli: Hadia nilaumö? Ba imane Saulo: No u''ila, wa muzaewe manö niha, wa laröi ndra''odo; ba irugi inötö, ba lö ya''ugö, lö lai, wa no owulo Ndrawa Wilisiti, ba Mikhima.', '["Faigi 10:8","HalZin 13:22"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 12, 'Ba umane dödögu: Möi mitou sa''ae Ndrawa Wilisiti, khögu, ba Giligala, ba lö ni''andrögu fa''ebua dödö Yehowa; ba u''abe''e''ö dödögu, wame''e sumange andrö.', '["Faigi 10:8","HalZin 13:22"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 13, 'Ba imane Samueli khö Zaulo: No sambö era-era ndra''ugö; oroisa andrö, nibe''e Lowalangiu, Yehowa, khöu, ba no lö ni''o''öu; i''aro''ö ena''ö iya''e Yehowa wa''arazomö ba Ndraono Gizeraeli, fa böi tebulö.', '["Faigi 10:8","HalZin 13:22"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 14, 'Ba me no si manö, ba tenga si lö tebulö wa''arazomö andrö. Noa sa i''alui khönia Yehowa niha si faduhu dödönia, ba wame''e razo mbanuania ya''ia. Me no lö ni''o''ömö niŵa''ö Yehowa khöu.[3]', '["Faigi 10:8","HalZin 13:22"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 15, 'Ba maoso Zamueli, iröi Giligala, ifuli ia. Ba si tosai sabölö, ba la''o''ö Zaulo, ba wamaondragö sanuwö. Ba me no larugi Gibea, ba mado Mbeniyami, me la''otarai Giligala, ba i''ofaya zabölö andrö si fao na khönia Saulo, so mato 600.', '["Sanguhuk 5:8"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 16, 'Ba ba Geba, ba mado Mbeniyami, la''iagö Saulo ba ononia Yonata, awö niha andrö, si fao khöra na, ba ba Mikhima tebato mege Ndrawa Wilisiti.', '["Sanguhuk 5:8"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 17, 'Ba so zi otarai golombaseŵa Ndrawa Wilisiti si möi farabu, tölu bawa: Si sambawa, ba lasaŵa Gofera, möi ba danö Zuala, ba si sambawa,', '["Sanguhuk 5:8"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 18, 'ba ba Mbeti Horona ladölö ira, ba si sambawa, fanete da''ö, ba möi ba hili andrö, si otahögö daso andrö nifotöi daso Zebo''i ba tanö si mate tanö sa.', '["Sanguhuk 5:8"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 19, 'Ba lö falukha ziambu ba danö Ndraono Gizeraeli ma''asagörö (lamane dödöra Dawa Wilisiti: Ma dania laböbözi khöra zi''öli ba toho niha Heberaio andrö!)[4]', '["Sanguhuk 5:8"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 20, 'Dozi Iraono Gizeraeli, ba lö tola lö''ö, mitou ba Ndrawa Wilisiti möi, na so ni''ambukhi, ma si''öli wamali''ö danö, ba ma faku ba ma fato ba ma tambila.', '["Sanguhuk 5:8"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 21, 'Na no afuru mbawa zi''öli wamali''ö danö ba he faku ba he garafu andrö ba he fato ba he ba wangadölö tukotuko zi matua zaŵi.', '["Sanguhuk 5:8"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 22, 'Ba na so wasuwöta, ba lö si''öli ba lö toho ba zabölö andrö fefu, si fao khö ndra Saulo ononia Yonata; ba so sa khö Zaulo ba khö nononia Yonata.', '["Sanguhuk 5:8"]', NULL),
  (3474988, 'OT', 'Samueli I', 13, 23, 'Ba sambawa Dawa Wilisiti, ba larugi mbawa danö andrö fönaföna Mikhima.', '["Sanguhuk 5:8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 1, 'Ba samuza ma''ökhö, ba imane Yonata, ono Zaulo, khö nono matua andrö, solohe fangönania: Tabu, möi ita miyefo ba Ndrawa Wilisiti si sambawa andrö, tanö sa! lö''ö sa ifarongogö khö namania.', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 2, 'Ba Saulo, ba no dumadao ba nola Gibea, ba mbörö dalimo, ba ngai Migerono. Ba fa''ato niha si so khönia, ba mato 600.', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 3, 'Ba si obaru baru ba doto andrö, baru gere, ba Ahia, ono Gahitubi, ga''a Ikabodi andrö, ono Wineha andrö ono Eli, ere khö Yehowa ba Zilo. Ba lö''ö sa nirongo zato, wa no mofanö Yonata.[1]', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 4, 'Ba ba dalu mbawa danö andrö ni''ötö Yonata ena''ö, ba wolau ba Ndrawa Wilisiti andrö, ba no faoma fatambai so gara satarö; töi zi sambua, ba Bosesi, ba si sambua, ba Sene döi.', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 5, 'Si sambua, ba tanö yöu, no musindro, ba gamaudu Mikhima, ba si sambua, ba tanö raya, ba gamaudu Geba.', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 6, 'Ba imane Yonata khö nono matua andrö, solohe fangönania: Tabu, möi ita miyefo, ba zi lö muboto andrö, si sambawa. Ma atö itolo ita Yehowa ba wasöndrata; lö''ö sa fa''atebai khö Yehowa, na itolo ita, he ato niha ba he lö ato![2]', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 7, 'Ba itema linia solohe fangöna, imane: Lau zi so ba dödöu, fefu; ya''e ndra''odo, ba we''amöi awöu: hadia nilau dödöu, ba no nilau dödögu göi.', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 8, 'Ba imane khönia Yonata: Ba hiza, na möi ita miyefo iada''e, ba niha andrö,', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 9, 'ba na la''ila ita, ba na lamane khöda: Mibase''ö, irege marugi ami! Ba tabadugö ita ba zi so ita, lö möi ita miyaŵa khöra.', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 10, 'Ba na lamane: Mi''ae miyaŵa khöma, ba möi miyaŵa ita; na si manö, ba noa sa''ae ibe''e ba dangada ira Yehowa. Da''ö dania dandra khöda!', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 11, 'Ba me la''ila zi darua andrö Dawa Wilisiti, ba lamane Dawa Wilisiti: Hiza niha Heberaio si otarai dögi narö hili, ba nibini''öra ya''ira!', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 12, 'Ba mu''ao zanaro andrö khö Yonata ba khö zolohe fangönania, lamane: Mi''ae miyaŵa khöma, ba so dania nirongomi khöma! Ba imane Yonata khö zolohe fangönania: O''ö ndra''o miyaŵa, noa sa''ae ibe''e ba dangada ira Yehowa!', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 13, 'Ba manana Yonata, miyaŵa, ba i''o''ö ia solohe fangönania. Ba moloi ira föna Yonata, ba i''ö''ötö tou ira, ba solohe fangönania zamalua famunu, moroi furinia.[3]', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 14, 'Ba mato 20 niha zi mate ba wamunu si föföna andrö, khö ndra Yonata solohe fangönania andrö, ha mato tölu lauru tanömö wa''ebolo danö.', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 15, 'Ba ihawui ira fa''ata''u, ba golombaseŵa ba sanuwö andrö fefu; ba si manö göi zanaro andrö, fabaya si sambawa, si möi farabu mege. Ba humeu göi danö, tobali fameta''u sabölö-bölö.', '["Faigi 4:19,21","Sanguhuk 7:7; Nga''ötII 14:10","MozIII 26:7,8"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 16, 'Ba me lafaigi sanaro andrö khö Zaulo ba Gibea, ba mado Mbeniyami, ba oi humufa ba golombaseŵa.', '["Faigi 4:3","Sanguhuk 7:22; Nga''ötII 30:23"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 17, 'Ba imane Saulo, ba zi so khönia ba da''ö: Mi''ofaya niha ba mifaigi, ha niha khöda zofanö! Ba la''ofaya, ba Yonata zi lö''ö ba solohe fangöna khönia.', '["Faigi 4:3","Sanguhuk 7:22; Nga''ötII 30:23"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 18, 'Ba imane Saulo khö Gahia: Ohe ba da''e mbaru gere andrö! ya''ia zi obaru baru ba doto andrö, baru gere, me luo da''ö, föna Ndraono Gizeraeli.[4]', '["Faigi 4:3","Sanguhuk 7:22; Nga''ötII 30:23"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 19, 'Ba me humede na Zaulo khö gere andrö, ba tedou manö na wagua-guasa ba golombaseŵa Ndrawa Wilisiti, ba imane Saulo khö gere andrö: Akha lö''ö ua!', '["Faigi 4:3","Sanguhuk 7:22; Nga''ötII 30:23"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 20, 'Ba maoso Zaulo ba awönia sabölö andrö fefu, ba me larugi naha wasöndrata andrö, ba i''ö''ötö manö nawönia zamösana, abölö-bölö sibai wa''afakuyu.[5]', '["Faigi 4:3","Sanguhuk 7:22; Nga''ötII 30:23"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 21, 'Ba niha Heberaio andrö, si no arara barö mbawa Ndrawa Wilisiti ba si no fao khöra ba wanuwö andrö, ba laheta ira khöra göi, ba wefao ba Ndraono Gizeraeli andrö, awö ndra Saulo Yonata.', '["Faigi 4:3","Sanguhuk 7:22; Nga''ötII 30:23"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 22, 'Ba he Iraono Gizeraeli andrö fefu si no mamini''ö ya''ira mege ba hili mado Geferayi, me larongo no moloi Ndrawa Wilisiti, ba lagohi göi, ba wolau khöra.', '["Faigi 4:3","Sanguhuk 7:22; Nga''ötII 30:23"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 23, 'Tobali möna Ndraono Gizeraeli me luo da''ö, ibe''e Yehowa. Ba fazöndrazöndra na, irugi ba zi tambai Mbeti Awena.', '["Faigi 4:3","Sanguhuk 7:22; Nga''ötII 30:23"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 24, 'Oi fao khö Zaulo zato fefu, mato 10.000 ira, ba fabali ira ba wasöndrata andrö ba hili —, ba mosala Zaulo, me luo da''ö, sala sebua. Ibe''e ba hölu zato, imane: Ni''elifi dozi si manga hadia ia, irege bongi dania, irege no ulau mbalögu ba nemaligu andrö! Ba dozi ira, ba lö manga.', '[]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 25, 'Ba so gazuni ŵani ba mbenua.', '[]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 26, 'Ba me larugi gawa''awa andrö sato, ba hiza, ba no moloi ŵani. Ba lö''ö zui samelai, me ata''u ira wahölusa andrö.', '[]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 27, 'Ba lö''ö sa nirongo Yonata, me ibe''e ba hölu zato amania. Ba i''oro''ö mbalö zi''o, si so ba dangania, ituko gawa''awa, ba ifelai, ba ifuli ohahau hörönia.', '[]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 28, 'Ba humede khönia nawönia, samösa, imane: No ibe''e ba hölu sabe''e zato amau, no imane: Ni''elifi dozi si manga hadia ia ma''ökhö! Ba no serege tödö niha sato.', '[]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 29, 'Ba imane Yonata: Ibunu ita amagu; hiza sa wa''ohahau hörögu, me no ufelai ŵe ŵani andrö, si ha ma''ifu;', '[]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 30, 'ba mendrua manö ena''ö, na no lafaulugö sato wemanga ma''ökhö zahulu ira ba nemali andrö — ba ba zi mane, ba no öna-öna sibai wa''ate''ala Ndrawa Wilisiti andrö!', '[]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 31, 'Ba la''alani Ndrawa Wilisiti, me luo da''ö, i''otarai Mikhima, numalö ba Nayalona, ba erege sibai dödöra.', '[]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 32, 'Ba latuyu gahulua andrö sato, lahalö mbiri-biri ba saŵi fabaya ono, lataba, tou ba danö, ba la''a sato, fabaya do.[6]', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474989, 'OT', 'Samueli I', 14, 33, 'Ba la''ombakha''ö khö Zaulo lamane: Mosala khö Yehowa zato, me no fabaya ndro ba göra. Ba imane: Salakha khömi da''ö! Mifagaölö khögu gara sebua ba da''e!', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 34, 'Ba imane na Saulo: Mitöröi zato, ba mimane khöra: Yamu''ohe khögu ba da''e zamösana zaŵinia ba ma biri-birinia, ba da''e itaba ba i''a, fa böi mosala ami khö Yehowa, wemanga ya''ia, fabaya do! Ba dozi ira, ba la''ohe zi so khöra, ba ba da''ö lataba.', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 35, 'Ba ifa''anö naha wame''e sumange khö Yehowa Saulo; böröta naha wame''e sumange, nifa''anö Zaulo khö Yehowa, da''ö.', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 36, 'Ba imane Saulo: Datagohi Ndrawa Wilisiti, ba zi bongi, ena''ö tahalö khoda zi so khöra ba ena''ö tahori ira, samösa böi tasaigö! Ba lamane: Lau manö zomasi''o! Ba imane ere: Ta''ondrasi Lowalangi ba da''e.', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 37, 'Ba me isofu khö Lowalangi Saulo: Hadia, ugohi Ndrawa Wilisiti? Hadia, öbe''e ba danga Ndraono Gizeraeli ira? ba lö itema linia, me luo da''ö.[7]', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 38, 'Ba imane Saulo: Mi''ae ba da''e, ya''ami, salaŵa mbanua fefu, ba mizofu-zofu, ha niha zosala ma''ökhö!', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 39, 'Faya sa, wa no sauri Yehowa, same''e möna Ndraono Gizeraeli, na lö mate zosala andrö, he onogu Yonata zamuza! Ba lö ba zato andrö fefu sanema linia.', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 40, 'Ba imane ba Ndraono Gizeraeli fefu: Mi''agö ba zi tambai, ba ba zi tambai, ba daruaga, onogu Yonata. Ba lamane sato khö Zaulo: Lau zomasi ndra''ugö!', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 41, 'Ba imane Saulo: He Yehowa, Lowalangi Ndraono Gizeraeli, hadia ia, wa lö ötema li genoniu, ma''ökhö? Na ya''odo zi so sala ba ma onogu Yonata, ba Urimi fa''ele''ö; ba na ba mbanuau Iraono Gizeraeli so, ba Tumimi fa''ele''ö! Ba ira Yonata Saulo zi göna, ba sato, ba aefa.[8]', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 42, 'Ba imane Saulo: Milau dahö-dahö ba khöma onogu Yonata! Ba göna Yonata.', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 43, 'Ba imane Saulo khö Yonata: Ombakha''ö khögu hadia nilaumö! Ba i''ombakha''ö khönia Yonata, imane: Ha ma''ifu ufelai ŵe ŵani ba mbalö zi''ogu ba dangagu, ba hadia, famunugu da''ö?![9]', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 44, 'Ba imane Saulo; Yamulau khögu zomasi ia Lowalangi: si mate ndra''ugö, Yonata!', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 45, 'Ba lamane sato khö Zaulo: Hadia, nibunu Yonata andrö, samobörö fangorifi sebua andrö, ba Ndraono Gizeraeli? Lö tola da''ö! faya wa no sauri Yehowa, na aekhu tou ba danö zara bu ba högönia, me no itolo ia Lowalangi ba wolaunia, ma''ökhö. Ba la''efa''ö Yonata niha sato, fa böi mate ia.', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 46, 'Ba ifuli ia misi yaŵa Saulo, iböhöli wolohi Dawa Wilisiti, ba lafuli ira khöra Dawa Wilisiti.', '["MozIII 3:17","Ayati 18; Faigi 23:9","Faigi 10:20","Yos 7:19"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 47, 'Ba me no aro khö Zaulo wa''arazo ba Ndraono Gizeraeli, ba fasuwö ia ba nemalira fefu, fasui: ba Ndraono Moabi ba ba Ndraono Gamoni ba ba Ndraono Gedomo ba ba razo Zoba ba ba Ndrawa Wilisiti, ba fefu gofu heza möi ia, ba ya''ia zabölö.', '["Nga''ötI 9:39","Faigi 17:55"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 48, 'Ba ifa''ele''ö göi wa''abölö wolau ba Ndraono Gamaleki, i''efa''ö Ndraono Gizeraeli ba danga zi farabu ba khöra.', '["Nga''ötI 9:39","Faigi 17:55"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 49, 'Ba ono Zaulo, ono matua, ba Yonata ba Isiyo ba Malekizua, ba ononia alawe si dombua, ba Merabi zi a''a ba Mikhala zi akhi.[10]', '["Nga''ötI 9:39","Faigi 17:55"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 50, 'Ba fo''omo Zaulo, ba Ahinoa, ono Gahimasi andrö; ba kumandra sebua khönia, ba Abineri, ono Neri andrö, tana nama Zaulo.[11]', '["Nga''ötI 9:39","Faigi 17:55"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 51, 'No faoma ono Gabieli, he Kisi, ama Zaulo, ba he Neri, ama Gabineri andrö.', '["Nga''ötI 9:39","Faigi 17:55"]', NULL),
  (3474989, 'OT', 'Samueli I', 14, 52, 'Ba götö wa''ara Zaulo, ba lö aefa-aefa wasuwöta sabölö-bölö, ba Ndrawa Wilisiti. Ba na i''ila zabölö ba si no to''ölö ba wasuwöta Saulo, ba ihalö awönia.', '["Nga''ötI 9:39","Faigi 17:55"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 1, 'Ba imane Samueli khö Zaulo: No iŵa''ö khögu Yehowa wamayoini ya''ugö razo mbanuania Iraono Gizeraeli; ba fondrondrongo goroisa Yehowa.[1]', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 2, 'Da''ö niŵa''ö Yehowa ngahönö: No uŵa''ö tödögu, nilau balö nilau Ndraono Gamaleki ba Ndraono Gizeraeli, womba''a lala khöra, me so ira moroi si tou, ba danö Miserayi.[2]', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 3, 'Ba ae suwö Ndraono Gamaleki andrö ba ölakha''ö ira, awö zi so khöra fefu, böi hakhösi tödö; bunu ira, he ira matua, ba he ira alawe ba ono matua ba si lö aefa na ba mbagi zusu, ba saŵi ba biri-biri ba ondra ba kalide![3]', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 4, 'Ba ifahede''ö ba niha sato Saulo. Ba i''ofaya ira ba Delami: 200.000 zi lö kudo ba 10.000 ma''uwu Yuda.', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 5, 'Ba isaŵa mbanua sebua ba Ndraono Gamaleki Saulo, ba ifatenge ba ndraso mbombo andrö ösa, samini''ö ya''ira ba da''ö.', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 6, 'Ba imane Saulo ba ma''uwu Geni andrö: Mifaoso, miheta ami! mifabali ami ba Ndraono Gamaleki, ena''ö lö uhori ami awöra, me no si sökhi nilaumi ba Ndraono Gizeraeli fefu, me la''otarai danö Miserayi. Ba laheta ira ba ngai Ndraono Gamaleki ma''uwu Geni andrö.[4]', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 7, 'Ba ilau ba Ndraono Gamaleki Saulo, i''otarai Delami, numalö ba Zuri, tanö ba gatumbukha luo i''otarai danö Miserayi.', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 8, 'Ba Agagi andrö, razo Ndraono Gamaleki, ba lara''u auri, ba sato fefu, ba la''ö''ötö tou bawa zi''öli.', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 9, 'Ba Saulo ba sato, ba la''orifi Agagi andrö ba si sökhi mbiri-biri ba si sökhi zaŵi, satabö ba nibula ba hadia ia fefu zebua böli, te khöra lafakiko da''ö; ba hadia zi lö böli ba si lö töi, ba lafakiko.', '["Faigi 10:1","MozII 17:8–16; MozV 25:17–19","MozIV 21:2","Sanguhuk 1:16"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 10, 'Be humede Yehowa khö Zamueli, imane:', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 11, 'Mangesa dödögu, me no ube''e razo Zaulo andrö; noa sa i''erogö ndra''o ba lö nitörönia niŵa''ögu. Ba afökhö khö Zamueli, ba sara wongi manö i''angaröfi li Yehowa.', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 12, 'Ba ihulö wongi ifaondragö Zaulo Samueli. Ba la''ombakha''ö khö Zamueli: No mangawuli Zaulo, no isaŵa hili Garemeli, ba da''ö no itaru''ö harefa khönia, ba no iröi da''ö, no isaŵa misi tou Giligala.', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 13, 'Ba me falukha Zamueli khö Zaulo, ba imane khönia Saulo: Ya''ahowu ndra''ugö khö Yehowa!', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 14, 'No utörö niŵa''ö Yehowa. Ba imane Samueli: Ba hadia wambehesa mbiri-biri andrö ba dögi dalingagu, ba fe''ao-ao zaŵi andrö, nirongo-rongogu?', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 15, 'Ba imane Saulo: Ni''ohera moroi ba Ndraono Gamaleki; noa sa la''orifi zi sökhi mbiri-biri ba si sökhi zawi sato, ba wame''e sumange Lowalangiu Yehowa; ba tanö bö''ö, ba no mabunu.', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 16, 'Ba imane Samueli khö Zaulo: Böi ua! ena''ö u''ombakha''ö khöu, hadia wehede Yehowa khögu, me owi!', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 17, 'Ba imane: ŵa''ö! Ba imane Samueli: Tenga si manö: he ŵa''ae niha side-ide ndra''ugö wamaigiu, ba noa zui högö mado Ndraono Gizeraeli ndra''ugö, me no ibayoini razo Ndraono Gizeraeli ndra''ugö Yehowa,[5]', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 18, 'ba no ifatenge ndra''ugö Yehowa, no iŵa''ö khöu: Ae fakiko zebua horö andrö, Iraono Gamaleki, lau khöra, irege no ahori ira öbe''e!', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 19, 'Ba hana wa lö ö''o''ö goroisa Yehowa andrö, bana wa no öfahulö gahulua andrö, wolau si fatuwu khö Yehowa?', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 20, 'Ba itema li Zamueli Saulo imane: Ba no u''o''ö niŵa''ö Yehowa: ba nifatenge Yehowa ya''o, ba no möido, ba no u''ohe razo Ndraono Gamaleki, Agagi andrö, ba Iraono Gamaleki andrö, ba no ufakiko.', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 21, 'Ba no lahalö mbiri-biri, ba saŵi sato, ahulua andrö ösa, si sökhi nilakha''ö andrö, ba wame''e sumange Lowalangiu, Yehowa, ba Giligala.', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 22, 'Ba imane Samueli: Ba hadia, no faoma wa''ebua dödö Yehowa, he ba zumange nitunu, awö ba zumange nitaba, ba he ba wolo''ö linia? Hiza, sökhi wolo''ö, moroi ba zumange, ba sökhi wamondrongo li, moroi ba dawö zi matua mbiri-biri;[6]', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 23, 'fa lö molo''ö sa, ba no timba horö fakelemusa, ba fa''abe''e dandro, ba no falaŵalaŵa ba wa''aefa ba Lowalangi ba ba wame''e adu! Ba me no lö ba dödöu niŵa''ö Yehowa, ba noa göi tebai razo ndra''ugö, wamaiginia.[7]', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 24, 'Ba imane Saulo khö Zamueli: Horögu da''ö, me no usawö goroisa Yehowa, awö nifakhoinia andrö; ba no ata''udo zato, ba no tobali u''o''ö niŵa''öra.', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 25, 'Ba iya''e, ba be''e aefa khögu horögu, ba taisa awögu ba wangawuli, ena''ö mangalulu ndra''o khö Yehowa!', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 26, 'Ba imane Samueli khö Zaulo: Lö möido awöu ba wangawuli: me no lö ba dödöu oroisa Yehowa, ba noa göi tebai razo Ndraono Gizeraeli ndra''ugö, wamaigi Yehowa.', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 27, 'Ba me ibali''ö ia Samueli, ba wofanö, ba ituyu watalinga mbarunia sebua Saulo, ba aetu da''ö.', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 28, 'Ba imane khönia Samueli: No iheta khöu wa''arazo ba Ndraono Gizeraeli Yehowa maökhö, no i''etu''ö, ba no ibe''e ba niha bö''ö, si sökhi moroi khöu.[8]', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 29, 'Ba lö''ö sa mofaya "lakhömi" Ndraono Gizeraeli andrö, ba lö mangesa dödönia, me no tenga niha ia, wa mangesa ena''ö dödönia.[9]', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 30, 'Ba imane: Horögu sa, ba fosumange atö ndra''o, föna zalaŵa ba föna zato, we''amöi awögu ba wangawuli, ena''ö mangalulu ndra''o khö Lowalangiu, Yehowa!', '["Faigi 9:21","Hos 6:6; Yes 1:11; Mat 9:13; 12:7","Faigi 16:1","Faigi 28:17","MozIV 23:19"]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 31, 'Ba mangawuli Zamueli, i''o''ö Zaulo, ba mangalulu khö Yehowa Zaulo.', '[]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 32, 'Ba imane Samueli: Ndramu''ohe khögu ba da''e razo Ndraono Gamaleki andrö, Agagi andrö! Ba i''ondrasi ia Agagi, no ohahau mbawa; imane Agagi: Hiza, no taya wa''afökhö wa''amate!', '[]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 33, 'Ba imane Samueli: Si mane fangohorimö iraono ndra alawe bö''ö, si''ölimö, si manö göi lahori ndraono ninau, moroi ba wangohori iraono ndra alawe bö''ö! Ba igögötö tou Agagi Samueli, föna Yehowa ba Giligala.', '[]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 34, 'Ba isaŵa Rama Samueli, ba Saulo, ba ifuli ia ba khöra misi yaŵa ba Gibea, banua Zaulo.', '[]', NULL),
  (3474990, 'OT', 'Samueli I', 15, 35, 'Ba lö''ö sa''ae falukha Zamueli khö Zaulo, irege mate ia, noa sa abu dödö Zamueli ba khö Zaulo andrö, ba no mangesa dödö Yehowa, me no ifataro razo Ndraono Gizeraeli Zaulo.', '[]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 1, 'Ba imane Yehowa khö Zamueli: Ha wa''ara döhö wa''abu dödöu khö Zaulo andrö, me noa sa atö tebai salaŵa Ndraono Gizeraeli ia, wamaigigu? Fo''ösi fanikha dandru andrö khöu ba labu: ufatenge ndra''ugö khö Giza''i andrö, banua Mbetilekhema, me no ba nononia ufaigi khögu zamösa, nibe''e razo.[1]', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 2, 'Ba imane Samueli: He uwisa we''amöi? Na irongo Saulo, ba ibunudo! Ba imane Yehowa: Ohe nono zaŵi ba ömane: Ba wame''e sumange Yehowa möido.', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 3, 'Ba kaoni Giza''i andrö, ba wemanga sumange; ba ya''o zangombakha khöu, he öwisa; nitötöigu khöu, ba öbayoini khögu.', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 4, 'Ba i''o''ö Samueli niŵa''ö Yehowa. Ba me irugi Mbetilekhema, ba lafaondragö ia satua mbanua, si no tobali tödö, ba lamane: Hadia, ba zi sökhi möi''ö?[2]', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 5, 'Ba imane: Ya''ia! Ba wame''e sumange Yehowa möido; mi''amoni ba mitabu ba wemanga zumange andrö! Ba ifamoni ndra Iza''i ononia ba ikaoni ira ba wemanga zumange andrö.', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 6, 'Ba me so ira, ba ifaigi Geliabi andrö, imane dödönia: Si ndruhu, ya''ia nibayoini khö Yehowa!', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 7, 'Ba imane Yehowa khö Zamueli: Böi faigi nga''eunia ba fa''alaŵania, tenga sa ya''ia nituyugu. Famaigi Lowalangi sa, ba no tenga si mane famaigi niha. Nga''eu nifaigi niha, ba tödö nifaigi Lowalangi![3]', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 8, 'Ba khö Gabinadabi muhede Giza''i, i''ohe khö Zamueli. Ba imane Samueli: Da''ö göi, ba tenga nituyu Yehowa.', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 9, 'Ba Sama i''ohe khönia Iza''i; ba imane: Da''ö göi, ba tenga mituyu Yehowa.', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 10, 'Ba fitu i''ohe khö Zamueli ononia Iza''i; ba imane Samueli khö Giza''i: Lö nituyu Yehowa ba da''ö![4]', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 11, 'Ba imane na Samueli khö Giza''i: Hadia, awai nonou matua? Ba imane: Hatö si akhi, no möi kubalo mbiri-biri. Ba imane Samueli khö Giza''i: Fatenge, fahalö''ö ia, lö''ö sa manga ita, na lö ya''ia.[5]', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 12, 'Ba ifatenge, ifahalö''ö; ba no soyo bu ba si sökhi hörö, ba si sökhi manö wamaigida. Ba imane Yehowa: Faoso, bayoini ia, da''ö ia.', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 13, 'Ba ituyu dandru wanikha Samueli, ibayoini [Dawido] ba zi so ira ga''ania. Ba so Geheha Yehowa khö Dawido, i''otarai luo da''ö, lö tebulö. Ba ifazaŵa ia Samueli, isaŵa Rama.[6]', '["Faigi 15:23,35","RazII 9:18","HalZin 10:34; Sin 7:10","Nga''ötI 2:13–15","Faigi 17:14","SamII 2:4; 5:3"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 14, 'Ba me no aheta Geheha Yehowa khö Zaulo, ba ifakao ia bekhu si lö sökhi, nifatenge Yehowa.[7]', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 15, 'Ba lamane khö Zaulo ira awönia: Hiza sa, ifakao ndra''ugö bekhu si lö sökhi khö Lowalangi,', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 16, 'ba yamuŵa''ö manö niŵa''önia sokhö ya''aga; ya''e ndra''aga, sawuyumö andre, ba ma''alui niha, sonekhe ba wolau biola: ba na so khöu mbekhu si lö sökhi andrö, khö Lowalangi, ba yamulau mbiola, ba aoha khöu.[8]', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 17, 'Ba imane Saulo ba ngoni-ngoninia andrö: Ba mifaigi khögu niha si no to''ölö ba wolau biola, ba mi''ohe khögu.', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 18, 'Ba imane si samösa: So ni''ilagu, ono Giza''i andrö, banua Mbetilekhema si no to''ölö ba wolau biola, niha sabölö ba sonekhe ba watelesa ba sabölö ba huhuo, niha si sökhi boto, ba itolo-tolo ia Yehowa.', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 19, 'Ba ifatenge zinenge Saulo, khö Giza''i, imane khönia: Fatenge khögu nonou Dawido andrö, kubalo mbiri-biri andrö.', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 20, 'Ba ihalö roti Iza''i, fulu, ba samba nahia nagu ba sara nono nambi, si matua, ifa''ohe''ö khö Zaulo, khö nononia Dawido andrö.', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 21, 'Ba möi khö Zaulo Dawido, möi ngoni-ngoninia, ba i''omasi''ö Saulo, ba tobali solohe fangöna Zaulo Dawido.', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 22, 'Ba ifatenge khö Giza''i Saulo, imane khönia: Akha so khögu Dawido, ngoni-ngonigu, me no omasido ia.', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474991, 'OT', 'Samueli I', 16, 23, 'Ba ero na ira''u Zaulo bekhu si lö sökhi andrö, khö Lowalangi, ba ituyu mbiola Dawido ba ifoli; ba okafu khö Zaulo, aoha, ba aheta khönia mbekhu si lö sökhi andrö.[9]', '["Faigi 18:10","RazII 3:15","Ayati 14"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 1, 'Ba la''owuloi zabölö khöra Dawa Wilisiti, ba wanuwö; ba Zokho, ba danö mado Yuda, owulo ira, ba ba ngai Nefesi Damimi tebato ira, ba gotaluara Zokho Naseka.', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 2, 'Ba Saulo ba Iraono Gizeraeli, ba no owulo göi, ba ba ndraso andrö, sabölö manawa, tebato ira; ba lafa''anö ira, ba wolau ba Ndrawa Wilisiti.', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 3, 'Ba no lafatambai: tanö andre, ba gahe hili, ba Dawa Wilisiti, ba si yefo, ba Iraono Gizeraeli, tobali otaluara ndraso andrö.', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 4, 'Ba möi baero moroi ba naha Ndrawa Wilisiti mbohalima, Goliato döi, banua Gata, önö hela a lito wa''alaŵania;[1]', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 5, 'tetenaulu töla ba högönia ba barunia sabe''e, ba sohuna-huna: ba fa''abua mbarunia sabe''e andrö, ba so safiku.', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 6, 'Ba so mbalu-balu wahania, töla, ba baluse töla ba galisinia,', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 7, 'ba ezai hao dotoa mburusania, ba mato 6 kilo wa''abua nösi mburusa, si''öli; ba mowaö-waö fönania zolohe dangenia.', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 8, 'Ba so ia ba mu''ao ia ba Ndraono Gizeraeli, imane: Hadia wa so ami, wama''anö ya''ami, ba wolau khöma? Hadia, tenga Dawa Wilisiti andrö ndra''o, ba tenga sawuyu Zaulo ami? Mifaigi zamösa ba khömi, solau khögu!', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 9, 'Na tola fatele ia khögu, ba na ya''ia zabölö, ba möiga barö mbawami; ba na ya''odo zabölö, na te''ala ia ube''e, ba ya''ami zi möi barö mbawama, ba sawuyuma ami.', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 10, 'Imane Dawa Wilisiti andrö: No u''o''aya zabölö Ndraono Gizeraeli ma''ökhö: mifaigi khögu zamösa, ena''ö fatele ndra''aga![2]', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 11, 'Ba me larongo wehede Ndrawa Wilisiti andrö Saulo ba Iraono Gizeraeli fefu, ba tobali dödöra ba ata''u sibai ira.', '["Yos 11:22","RazII 19:4,16"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 12, 'Ba Dawido andrö, ba ono mbanua Geferata, banua Mbetilekhema ba mado Yuda, Iza''i döi, ŵalu nono da''ö, ono matua. Ba me luo Zaulo, ba niha satua sa''ae niha da''ö, no numalö ndröfi.', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 13, 'Ba ono Giza''i, si a''a, ba no fao khö Zaulo ba wasuwöta andrö, datölu ira. Ba töi nononia si a''a andrö, si no fao ba wasuwöta andrö, ba Eliabi zi a''a, ba fanetenia, ba Abinadabi, ba fanete da''ö, ba Sama.[3]', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 14, 'Ba fondrege zi akhi Dawido, ba si datölu, si a''a, ba no fao khö Zaulo.', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 15, 'Ba no auli iheta ia khö Zaulo Dawido, ifulifuli ia ba khöra, ba wokubaloi biri-biri namania ba Mbetilekhema.', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 16, 'Ba he na mahemolu mbanua, ba he na tanö owi, ba so Ndrawa Wilisiti andrö no mege, i''iagö da''ö, 40 wongi wa''ara.', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 17, 'Ba imane Iza''i khö nononia Dawido: Halö ö ndra ga''au zi dombua yöu böra nifakoe andre ba si fulu ngawua roti andre, ba ta''i-ta''i ohe khö ndra ga''au ba golombaseŵa;', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 18, 'ba si fulu ngawua kezu zusu andre, ba ohe khö gumandra, ba sofu he wisa khö ndra ga''au; ba andrö khöra dandra-tandra.', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 19, 'Saulo ba ya''ira andrö, ba Iraono Gizeraeli fefu, ba ba ndraso andrö, sabölö manawa, so, ba wasuwöta ba Ndrawa Wilisiti.', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 20, 'Ba mahemolu ö, ba ihulö wongi Dawido, ibe''e rorogöfö zanaro mbiri-biri, i''ohe noronia ba mofanö, i''o''ö niŵa''ö namania Iza''i. Ba me irugi naha andrö ni''ölini kureta, ba möi sibai ira fasöndra, no lafa''anö ira, ba lahahagö.', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 21, 'He Iraono Gizeraeli, ba he Dawa Wilisiti, ba faoma no mana''ano, faondra ngenolira.', '["Faigi 16:6,8,9"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 22, 'Ba itou''ö tou noronia Dawido, iröi ba danga zanaro gama-gama, ba fao ia ba ngenoli zi fasöndra. Ba me irugi, ba isofu khö ndra ga''ania, na lö hadia ia khöra.', '["Faigi 16:6,8,9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474992, 'OT', 'Samueli I', 17, 23, 'Ba fatua fahuo-huo ia khöra, ba hiza mbohalima andrö — Dawa Wilisiti andrö, Goliato, banua Gata, döinia — mowaö-waö ia föna Ndrawa Wilisiti ba iŵa''ö niŵa''önia andrö, tobali irongo Dawido.', '[]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 24, 'Ba me la''ila niha andrö Iraono Gizeraeli, ba moloi ira fefu khönia, ata''u sibai ira.', '[]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 25, 'Ba so zi''ao, Iraono Gizeraeli, imane: Hadia, no mi''ila niha andrö moroi sa? Ba wango''aya Iraono Gizeraeli so ia, ba na so zamunu ya''ia, ba ifo''ana''a sebua razo ba ibe''e khönia nononia alawe, ba i''efa''ö ba wame''e beo nga''ötö namania, ba Ndraono Gizeraeli!', '[]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 26, 'Ba imane Dawido ba zi so ba ngainia: He lawisa ba zamunu Dawa Wilisiti andrö ba sangefa''ö Iraono Gizeraeli ba wango''aya andrö? Ha niha Ndrawa Wilisiti andrö, si mate lö mboto, wa tola i''o''aya zabölö andrö khö Lowalangi?', '[]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 27, 'Ba lafuli lamanö, khönia göi, lamane: Da''ö no mege latörö ba zamunu ya''ia.', '[]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 28, 'Ba me irongo ga''ania si a''a, Eliabi andrö, fahuhuo ia ba niha andrö, ba mofönu sibai Geliabi khö Dawido, imane: Hadia atö, wa so ndra''ugö, ba ha ba danga öröi mbiri-biri andrö, si lö oya-oya, ba danö si mate? No u''ila hokhamö andrö ba tödöu andrö, si lö sökhi: ba wamaigi wasuwöta andrö so ndra''ugö!', '[]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 29, 'Ba imane Dawido: Ba hadia zalagu? Tenga ha ligu manö?', '[]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 30, 'Ba i''erogö ga''ania, ba isofu ba niha bö''ö, ba lamanö zui khönia, si mane mege ba mböröta.', '[]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 31, 'Ba me terongo niŵa''ö Dawido, ba la''ombakha''ö khö Zaulo, ba ifakaoni''ö ia.', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 32, 'Ba imane Dawido khö Zaulo: He Tua, böi busi dödöu: möi fatele ba Ndrawa Wilisiti andrö zawuyumö andre.', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 33, 'Ba imane Saulo khö Dawido: Tebai möi''ö fatele ba Ndrawa Wilisiti andrö, me iraono ndra''ugö, ba me no bohalima ia, i''otarai iraono ia!', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 34, 'Ba imane Dawido khö Zaulo: No ikubaloi mbiri-biri namania sawuyumö andre: ba na so zingo ba ma berua, na i''oloi''ö zageu mbiri-biri andrö nikubaloi,', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 35, 'ba ugohi ia, ba ubözi ba usöbi ba mbawania mbiri-biri: ba na ilaŵa ndra''o, ba utuyu gambinia ba ubunu ia.', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 36, 'He singo, ba he berua, ba no ibunu sawuyumö andre, ba nifatörö ba khöra andrö, da''ö göi nifatörö ba Ndrawa Wilisiti andrö, si mate lö mboto, me no i''o''aya zabölö andrö khö Lowalangi sauri!', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 37, 'Ba imane na Dawido: Yehowa andrö, si no mangefa''ö ya''odo ba za''a zingo ba ba za''a mberua, ba i''efa''ö göi ndra''o ba danga Ndrawa Wilisiti andrö! Ba imane Saulo khö Dawido: Ba ae''e, ba itolo''ö Yehowa!', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 38, 'Ba ibe''e baru Dawido mbarunia ba wanuwö Saulo ba tetenaulu töla ibe''e ba högönia ba ifamaru sabe''e ia,', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 39, 'ba ibe''e ba löwi-löwinia wödania Dawido, ba dete mbaru ba wanuwö andrö, ba i''a''u''ö mowaö-waö, me lö irai itandraigö. Ba imane Dawido khö Zaulo: Tebai mofanödo ba zi mane, lö urai utandraigö! Ba lafuli laheta khönia wangöna andrö,', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 40, 'ba i''ohe tangania zi''onia, ba lima ngawua itutuyu ono gara salösö, ba mbombo, ibe''e ba mbola gubalo andrö si so khönia, ba löwi-löwinia, ba ituyu ribo-ribo ba i''ondrasi Ndrawa Wilisiti andrö.[4]', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 41, 'Ba ifaondragö Dawido Dawa Wilisiti andrö, ba mowaö-waö fönania zolohe dangenia andrö.', '["Nga''ötI 11:23"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 42, 'Ba me ifaigi Dawa Wilisiti andrö, ba me i''ila Dawido, ba i''ositengagö, me iraono na, soyo bu ba si sökhi boto.[5]', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 43, 'Ba imane Dawa Wilisiti andrö khö Dawido: Hadia, asu ndra''o, wa si''o ö''ohe, we''amöi khögu? Ba i''elifi Dawido Dawa Wilisiti andrö, ba Lowalanginia.', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 44, 'Ba imane na Dawa Wilisiti andrö khö Dawido: Ae ba da''e, ena''ö ube''e ö wofo ba dalu mbanua ba ö zaliŵa-liŵa ba danö nösiu![6]', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 45, 'Ba imane Dawido khö Ndrawa Wilisiti andrö: Ya''ugö, ba solohe si''öli ba toho ba dange, wamaondragö ya''odo, ba ya''o, ba ba döi Yehowa ngahönö möido khöu, ba döi Lowalangi zabölö Ndraono Gizeraeli andrö ni''o''ayamö:', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 46, 'ma''ökhö andre ibe''e ba dangagu ndra''ugö Yehowa ba ubunu ndra''ugö ba u''eŵa mbagiu, ba botou ba boto zabölö Ndrawa Wilisiti andrö, ba ma''ökhö ube''e ö wofo ba dalu mbanua ba ö gutu ndru''u ba danö, ena''ö aboto ba dödö niha ba guli danö fefu, so Lowalangi Ndraono Gizeraeli,', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 47, 'ba ena''ö la''ila dozi si so ba da''e, tenga si''öli ba tenga toho ibe''e fangorifi niha Yehowa; khö Yehowa sa wasöndrata andrö, ba ya''ia zame''e ba dangama ya''ami.', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 48, 'Ba me ilabu Dawa Wilisiti andrö, me so ia, ba wamaondragö Dawido, ba fulöi Dawido wamaondragö Dawa Wilisiti andrö, tanö ba zi so sato.', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 49, 'Ba ituyu nono gara andrö, zambua, ba mbolania, faribo ia, ba göna ba gangango Ndrawa Wilisiti andrö; ahöndrö ba gangangonia nono gara andrö, ba tobali telögu ia tou ba danö.', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 50, 'Ilaŵa Ndrawa Wilisiti andrö Dawido ribo-ribo ba ono gara ba ibunu; ba lö si''öli khö Dawido.', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 51, 'Ba fagohi ia, möi ia ba ngai Ndrawa Wilisiti andrö, ituyu wödania, isöbi ba ifalua ibunu Goliato. Ba awena ibe''e foleŵa mbaginia wöda andrö. Ba me la''ila Dawa Wilisiti, no mate zabölöra andrö, ba lalau moloi.', '["Faigi 16:12","Hez 29:5"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 52, 'Ba maoso Ndraono Gizeraeli, awö Ndraono Yuda, lahahagö ba lagohi Ndrawa Wilisiti, irege tanö ba Gata ba irege ba mbawa göli Nekerona, tobali fönaföna mbawa göli na mate Ndrawa Wilisiti andrö, nibunu, he ba Gata, ba he ba Nekerona.', '["Faigi 14:50"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 53, 'Ba lafuli ira Iraono Gizeraeli, laböhöli wolohi Dawa Wilisiti, ba lahalö gama-gama ba golombaseŵa.', '["Faigi 14:50"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 54, 'Ba ihalö högö Ndrawa Wilisiti andrö Dawido, i''ohe ba Yeruzalema; ba fangönania, ba ibe''e ba nosenia.', '["Faigi 14:50"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 55, 'Ba me i''ila mege Saulo, ifaondragö Ndrawa Wilisiti andrö Dawido, ba imane khö gumandra sebua khönia, Abineri andrö: Ha ono nono matua andrö, Abineri? Ba imane Abineri: Faya wa no sauri ndra''ugö, razo, na u''ila.[7]', '["Faigi 14:50"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 56, 'Ba imane razo: Sofu, ha ono nono matua andrö.', '["Faigi 14:50"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 57, 'Ba me mangawuli Dawido, me no ibunu Ndrawa Wilisiti andrö, ba i''ohe ia khö Zaulo Abineri: lö tebulö ba dangania högö Ndrawa Wilisiti andrö.', '["Faigi 14:50"]', NULL),
  (3474992, 'OT', 'Samueli I', 17, 58, 'Ba imane khönia Saulo: Ha ono ndra''ugö, ono matua? Ba imane Dawido: Ono zawuyumö Iza''i, banua Mbetilekhema, ndra''odo.', '["Faigi 14:50"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 1, 'Ba me no awai huhuo Dawido khö Zaulo, ba fahuwu ira Yonata Dawido, i''omasi''ö Dawido Yonata, si mane fa''omasinia ia.', '["Faigi 16:22; 17:15","Faigi 19:1; 20:17; 23:18; SamII 1:26; 21:7","Ayati 14"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 2, 'Ba ihalö khönia Dawido Saulo, me luo da''ö; lö''ö sa''ae itehe khönia wangawuli khö ndra amania[1]', '["Faigi 16:22; 17:15","Faigi 19:1; 20:17; 23:18; SamII 1:26; 21:7","Ayati 14"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 3, 'Ba fawu''u li khönia Yonata, me no i''omasi''ö ia, si mane fa''omasinia ia.[2]', '["Faigi 16:22; 17:15","Faigi 19:1; 20:17; 23:18; SamII 1:26; 21:7","Ayati 14"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 4, 'Iheta mbarunia sebua Yonata ibe''e khö Dawido, fabaya barunia sabe''e ba si''ölinia ba fanania ba böbö talunia.', '["Faigi 16:22; 17:15","Faigi 19:1; 20:17; 23:18; SamII 1:26; 21:7","Ayati 14"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 5, 'Ba na möi fasuwö Dawido, heza ifatenge ia Saulo, ba mofozu, ba tobali ibe''e högö zabölö ia Saulo. Ba oi la''omasi''ö ia niha sato, ba he awö Zaulo andrö.[3]', '["Faigi 16:22; 17:15","Faigi 19:1; 20:17; 23:18; SamII 1:26; 21:7","Ayati 14"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 6, 'Ba me mangawuli ira, me ifuli ia Dawido, me no ibunu Ndrawa Wilisiti andrö, ba dozi banua Ndraono Gizeraeli, ba lafaondragö Dawido ira alawe, manari ba labözi rafa''i, owua-wua dödö, ba labözi waritia.[4]', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 7, 'Ba latema lamane ira alawe andrö: "Hönö ae nibunu Zaulo, ba fulu ngahönö Dawido!"[5]', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 8, 'Ba mofönu sibai Zaulo, abao dödönia ba niŵa''öra andrö, ba imane: Fulu ngahönö labe''e khö Dawido, ba khögu, ba ha hönö; hatö fa''arazo zi lö khönia na!', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 9, 'Ba afökhö dödö Zaulo khö Dawido, i''otarai luo da''ö ba si manö-manö dania.', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 10, 'Ba mahemolu ö, ba ira''u Zaulo bekhu si lö sökhi khö Lowalangi, ba hulö zowöhö ia ba gödonia. Ba Dawido, ba solau biola, halöŵönia sero ma''ökhö, ba sara doho ba danga Zaulo.[6]', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 11, 'Ba ihandrogö doho Saulo, imane dödönia: Da''utandro ba mbagolö Dawido. Ba mendrua ihole''ö ia khönia Dawido.[7]', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 12, 'Ba ata''u sibai Zaulo Dawido, me itolo-tolo ia Yehowa, ba khö Zaulo, ba no iböda ia.', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 13, 'Ba iheta yomo khönia Dawido Saulo, ifataro kumandra zi hönö; ya''ia zolohe sato andrö, heza möi.', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 14, 'Ba hadia nilau Dawido, ba mofozu, me itolo-tolo ia Yehowa.[8]', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 15, 'Ba me i''ila Saulo, si sökhi manö wozu hadia ia khönia, ba muhokha mbunia khönia.', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 16, 'Ba dozi Iraono Gizeraeli, ba he ma''uwu Yuda, ba la''omasi''ö Dawido, me ya''ia zolohe ya''ira, heza möi.', '["Sanguhuk 11:34","Faigi 21:12; 29:5","Faigi 16:14","Faigi 19:10; 20:33","Ayati 5"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 17, 'Ba imane Saulo khö Dawido: Hiza zi a''a nonogu alawe, Meraba, da''ö ube''e khöu — ba sabölö ndra''ugö khögu, ba wasuwöta andrö niŵa''ö Yehowa. Imane sa dödönia Saulo: Lö uhalö tangagu wamunu ya''ia, ba hana na labunu ia Dawa Wilisiti.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 18, 'Ba itema li Zaulo Dawido, imane: Ha niha ndra''odo, ba ha niha zi sawu ya''aga, nga''ötö namagu andrö, ba Ndraono Gizeraeli, wa möido umönö razo?', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 19, 'Ba me irugi baŵa wame''e khö Dawido Meraba andrö, ono Zaulo, ba khö Gaderieli andrö, banua Mehola, labe''e ia.[9]', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 20, 'Ba somasi Dawido Mikhala andrö, si akhi nono Zaulo. Ba me lafarongogö da''ö khö Zaulo, ba atulö dödönia.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 21, 'Imane sa dödönia Saulo: Da''ube''e khönia, ena''ö tandraŵa khönia, ba ena''ö labunu ia Dawa Wilisiti. Ba imane sa''ae Saulo khö Dawido: Dua balö uŵa''ö khöu, ba tola möi''ö umönögu ma''ökhö.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 22, 'Ba ibe''e li ba ngoni-ngoninia Saulo, imane: Mifahuhuo khö Dawido, ba zi lö niha, mimane: Hiza, i''omasi''ö ndra''ugö razo, ba he awönia fefu, ba oi somasi ya''ugö, ba tola möi''ö umönö razo.[10]', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 23, 'Ba laŵa''ö da''ö khö Dawido ngoni-ngoni Zaulo andrö. Ba imane Dawido: Hadia, side-ide da''ö ba dödömi, na möi ita umönö razo? Ba ya''odo, ba no niha si numana, niha si lö töi.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 24, 'Ba la''ombakha''ö khö Zaulo niŵa''ö Dawido andrö.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 25, 'Ba imane Saulo: Mimane khö Dawido: Lö iŵa''ö khöu mböwö razo, ha otu botolö Ndrawa Wilisiti, ba wolau balö ba nemali razo andrö. Da''ö sa dödö Zaulo, ena''ö labunu Dawido Dawa Wilisiti.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 26, 'Ba me la''ombakha''ö da''ö khö Dawido ngoni-ngoni Zaulo andrö, ba atulö dödö Dawido, möi ia umönö razo; ba lö''ö na sa irugi inötö.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 27, 'Ba maoso Dawido, i''ohe nawönia andrö, ba otu labunu Dawa Wilisiti, ba i''ohe mbotolö andrö khöra ba i''erai khö razo, ena''ö tola möi ia umönö razo; ba ibe''e khönia nononia Mikhala Saulo.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 28, 'Ba me itugu aboto na ba dödö Zaulo itolo-tolo Dawido Yehowa ba oi la''omasi''ö ia Iraono Gizeraeli fefu,', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 29, 'ba itugu manö na göi ata''u ia Dawido. Ba tobali fa''udu Zaulo khö Dawido, sagötö ya''ia.[11]', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474993, 'OT', 'Samueli I', 18, 30, 'Ba so zui zalaŵa Ndrawa Wilisiti, möi manuwö. Ba abölö möna Dawido, moroi ba genoni Zaulo andrö, ero na möi ira; tobali teturia sibai döinia.', '["Sanguhuk 15:2","Faigi 22:14","Ayati 12"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 1, 'Ba i''ombakha''ö Saulo khö nononia Yonata ba ba nawönia fefu, wa edöna ibunu Dawido. Ba no omasi sibai Yonata, ono Zaulo, Dawido andrö;[1]', '["Faigi 18:3","Faigi 17:50"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 2, 'andrö wa i''ombakha''ö khö Dawido da''ö, imane: I''alui wamunu ya''ugö amada; angelama mahemolu mbanua, bini''ö ndra''ugö ba böi oroma''ögö ua.', '["Faigi 18:3","Faigi 17:50"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 3, 'Ba ya''o, ba möido baero, ba u''iagö ngai namada, ba mbenua, ba zi so ya''ugö, ba fahuhuodo khö namada, ba khömö andrö, ba hadia nirongogu dania, ba u''ombakha''ö khöu.', '["Faigi 18:3","Faigi 17:50"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 4, 'Ba isuno Dawido Yonata khö namania Saulo, imane khönia: Böi yamuhalö horönia razo wolau hadia ia khö ngoni-ngoninia Dawido, lö''ö sa horönia khöu, ba si no moguna sibai khöu wolaunia andrö fefu.', '["Faigi 18:3","Faigi 17:50"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 5, 'Hulö zi lö ba dödönia nosonia mege, me ibunu Ndrawa Wilisiti andrö, ba no möna sibai Ndraono Gizeraeli fefu, ba da''ö, ibe''e Yehowa. No höröu zangila, ba no somuso tödö ndra''ugö mege. Ba hana sa wa öhalö horöu ndro zi lö horö andrö, wamunu Dawido, si lö börö-börö?[2]', '["Faigi 18:3","Faigi 17:50"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 6, 'Ba ifondrondrongo niŵa''ö Yonata Saulo, fahölu ia, imane: Faya wa no sauri Yehowa, na labunu Dawido!', '["Faigi 18:3","Faigi 17:50"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 7, 'Ba mu''ao Yonata khö Dawido, ba i''ombakha''ö khönia huhuo andrö, fefu. Ba ifuli i''ohe khö Zaulo Dawido Yonata, ba soso ia khönia, si mane mege.', '["Faigi 18:3","Faigi 17:50"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 8, 'Ba me ifuli tesao wanuwö, ba möi Dawido fasöndra ba Ndrawa Wilisiti; ato sibai nibunu, ba moloi zi tosai ibe''e.', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 9, 'Ba ifuli ira''u Zaulo bekhu zi lö sökhi andrö khö Lowalangi; no dumadao ia ba nomonia ba sara dohonia ba dangania, ba solau biola Dawido tangania.[3]', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 10, 'Ba itandro ena''ö ba mbagolö Dawido Saulo. Ba ihole''ö ia Dawido khö Zaulo, ba tobali tetaru ba mbagolö doho. Ba maoso Dawido, moloi.', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 11, 'Ba ba zi bongi andrö, ba ifatenge zinenge Saulo, ba nomo Dawido, ba wanaro ya''ia, ena''ö i''ila ibunu na moluo. Ba i''ombakha''ö khö Dawido fo''omonia Mikhala, imane: Na lö ö''orifi''ö bongi, ba labunu''ö mahemolu![4]', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 12, 'Ba ifatörö ba zandrela Dawido Mikhala, wanada ya''ia tou; ba moloi ia, aefa.', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 13, 'Ba ihalö ziraha Mikhala, ifalea tou ba gaso, ba ibe''e ba lulu, tanö ba högö, gambala bu nambi, ba baru ibe''e ambalania.', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 14, 'Ba me ifatenge zinenge Saulo, ba wangai Dawido, ba imane Mikhala: Mofökhö.', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 15, 'Ba ifuli ifatenge zinenge andrö Saulo, ba wamaigi Dawido, imane: Mi''ohe ia, fabaya farate, ena''ö ubunu ia!', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 16, 'Ba me larugi sinenge andrö, ba hiza ziraha ba warate ba ambala bu nambi ba lulu.', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 17, 'Ba imane Saulo khö Mikhala: Hana wa ömanö wolimo ya''o, wa no öfofanö zi fa''udu khögu, wa no moloi ia? Ba imane Mikhala khö Zaulo: No imane khögu: Fofanö ndra''o, fa böi ubunu''ö!', '["Faigi 18:10,11","Sin 59:1"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 18, 'Ba moloi Dawido, aefa ia, isaŵa Zamueli ba Rama ba i''ombakha''ö khönia hadia ia fefu nilau Zaulo khönia, ba fao ia khö Zamueli ba ba Nayoti soso ira, ba Rama.', '["Faigi 10:10–12"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 19, 'Ba te''ombakha''ö khö Zaulo: Ba Nayoti, ba Rama so Dawido!', '["Faigi 10:10–12"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 20, 'Ba ifatenge zinenge Saulo, ba wangai Dawido. Ba me la''ila zama''ele''ö andrö, sangombakha, sambawa manö, awö Zamueli, solohe ya''ira, ba so Geheha Lowalangi, hulö ira''u zinenge Zaulo andrö, tobali mama''ele''ö ira göi.[5]', '["Faigi 10:10–12"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 21, 'Ba me la''ombakha''ö da''ö khö Zaulo, ba ifatenge zinenge bö''ö; ba ya''ira göi, ba mama''ele''ö göi. Ba me ifatenge na Saulo, medölu fefu, ba mama''ele''ö göi da''ö.', '["Faigi 10:10–12"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 22, 'Ba Saulo sa''ae zi möi ba Rama. Ba me irugi mba''a andrö, ba zinga golayama mbasitö andrö, ba hili si lö eueu, ba imane: Heza so Zamueli ba Dawido? Ba lamane: Ba Nayoti, ba Rama,', '["Faigi 10:10–12"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 23, 'ba me möi ia ba Nayoti, ba Rama, i''otarai da''ö no mege, ba so khönia göi Geheha Lowalangi, ba mama''ele''ö ia ba wowaö-waö, irege irugi Nayoti, ba Rama.', '["Faigi 10:10–12"]', NULL),
  (3474994, 'OT', 'Samueli I', 19, 24, 'Ba iheta nukhania, ba mama''ele''ö föna Zamueli, so manö tou ia ba zalo lö nukha, zi ma''öma''ökhö andrö, ba sara wongi dania. Andrö wa laŵa''ö-ŵa''ö: "Hadia, awö zama''ele''ö göi Zaulo?"', '["Faigi 10:10–12"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 1, 'Ba moloi Dawido, iheta ia ba Nayoti, ba Rama, möi ia fahuhuo khö Yonata, imane: Hadia nilaugu? Hadia lalögu? Hadia horögu khö namau, wa i''alu-alui wamunu ya''o?', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 2, 'Ba imane khönia Yonata: Böi; lö''ö sa mate''ö! he sebua, ba he side-ide. Hiza, lö''ö sa ilau hadia ia amada, si lö ifarongogö khögu; ba hana wa ibini''ö khögu da''ö amada?', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 3, 'Tebai si manö! Ba itema linia Dawido, imane: Lö''ö sa tobini khö namau, wa no somasi ya''o ndra''ugö, ba imane dödönia: Alakha lö irongo Yonata, ma dania i''abus tödö; ba faya sa, wa no sauri Yehowa, awö wa no sauri ndra''ugö, na tenga hatö sambeka ba gotaluama wa''amate!', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 4, 'Ba imane Yonata khö Dawido: Hadia ni''andröu, ba u''o''ö khöu.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 5, 'Ba imane Dawido khö Yonata: Mahemolu, ba fasulöna, ba tebai möido manga khö razo, ba efa''ö ndra''o, ena''ö ubini''ö ndra''odo irege bongi.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 6, 'Ba na isofu ndra''o amau, ba ömane: No i''andrö ia khögu Dawido, ena''ö tola isölaisi khöra ba Mbetilekhema, me mame''e sumange andrö si döfidöfi zi sawu ya''ira fefu.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 7, 'Ba na imane: Lau! ba lö angana khö zawuyumö andre; ba na mofönu ia, ba aboto sa''ae ba dödöu, no i''etu''ö ba wamakiko.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 8, 'Ba da''ö ö''oroma''ö wa''omasimö zawuyumö andre: noa sa atö fawu''u li ndra''ugö khö zawuyumö andre, khö Yehowa. Ba na si so horö ndra''o, ba ya''ugö bunudo; hana sa wa ö''ohe ndra''o khö namau?[1]', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 9, 'Ba imane Yonata: Böi ömanö dödöu! na urongo sa''ae, no i''etu''ö amada, ba wamakiko ya''ugö, ba hadia, lö ufarongogö khöu?', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 10, 'Ba imane Dawido khö Yonata: Ena''ö na so zangombakha khögu, na sofönu dania namau, wanema liu!', '["Faigi 18:3"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474995, 'OT', 'Samueli I', 20, 11, 'Ba imane Yonata khö Dawido: Tabu baero ba mbenua! Ba möi ira ba mbenua, darua ira.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 12, 'Ba imane Yonata khö Dawido: Ya si so ba mbörö Yehowa, Lowalangi Ndraono Gizeraeli: na usekhegö namada, mahemolu, ba na si sökhi dödönia khö Dawido — ba hadia, lö ufatenge khöu, ba lö ufarongogö khöu?', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 13, 'Yamulau khö Yonata Yehowa: na no tödö namada, ifakiko ndra''ugö — ba ufarongogö khöu ba ufofanö ndra''ugö, fa böi göna''ö hadia ia, ba itolo''ö Yehowa, si mane fanolonia amada mege.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 14, 'Ba hadia, lö ötolodo göi, na anau na nosogu, lö öhakhösi tödö ndra''o, si mane fa''ahakhö dödö Yehowa andrö, fa böi mate ndra''o?', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 15, 'Böi manö bulö''ö wa''ahakhö dödöu ba nga''ötö namada; ba na izara-zara Yehowa wangohori ba guli danö zi fa''udu khö Dawido,', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 16, 'ba böi tese''e döi Yonata labe''e si samba omo ndra Dawido, ba yamulau mbalö ba zi fa''udu khö Dawido Yehowa!', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 17, 'Ba samuza tö möi ba hölu Yonata khö Dawido, ba wa''omasinia ia andrö; noa sa moroi ba dödö i''omasi''ö ia.[2]', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 18, 'Ba imane khönia Yonata: Mahemolu, ba fasulöna, ba la''ila daia, wa lö ya''ugö, na lafaigi ba nahau.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 19, 'Ba ba zi dua wongi, ba abölö itörö tödö, wa lö ya''ugö; ba fa''aso''ö ba zi so''ö no andrö, me lafagönaisi ndra''ugö, ba nibini''öu ya''ugö, ba dadao ba ngai hili-hili danö andrö:', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 20, 'ba u''efasi dania nono wana, ba zi dua wongi, ufatörö ba ngai hili-hili andrö, hulö na utalini dandra.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 21, 'Ba ufatenge ndraono, umane: Ae alui nono wana andrö! Ba na umane we''ao ba ndraono andrö: Ya''e furiu nono wana andrö, ohe! ba fuli''ö, lö angana khöu, lö salania, ba wa''aduhu wa''auri Yehowa.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 22, 'Ba na umane khö nono matua andrö: Hiza fönau nono wana! ba labu''ögö, me no Yehowa zamofanö ya''ugö.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 23, 'Ba ba lida andrö, huhuoda, darua ita, ba no Yehowa zi so ba mbörö khöda, irugi zi lö aetu.', '["Faigi 18:3"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 24, 'Ba ibini''ö ia Dawido, ba mbenua. Ba me fasulöna, ba mudadao razo, ba wemanga,', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 25, 'ba nahanahania dumadao razo, si erogö bagolö ba tou dumadao Yonata, ba Abineri, ba ba ngai Zaulo; ba Dawido, ba lö''ö, ba nahania.', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 26, 'Ba lö hede-hede Zaulo, me luo da''ö, imane dödönia: Si lö mu''odödögö; no ra''iö ia, me lö nifahaogö''önia ya''ia.[3]', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 27, 'Ba sara wongi aefa wasulöna, me lö''ö zui Dawido, ba nahania, ba isofu Saulo khö nononia Yonata: Hana wa lö möi manga nono Giza''i andrö, he menewi, ba he ma''ökhö?', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 28, 'Ba itema li Zaulo Yonata, imane: No i''andrö ia khögu Dawido, ba we''amöi ba Mbetilekhema;', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 29, 'no imane: Hadia, lö öfa''amöi ndra''o, me mame''e sumange zi sawu ya''aga, ba da''ö, ba mbanuama, ba no laŵa''ö khögu ira ga''agu; na ebua dödöu khögu, ba fa''amöido, ba wamaigi ira talifusögu. Da''ö mbörö, wa lö si möi ia manga khö razo.', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 30, 'Ba mofönu Zaulo khö Yonata, imane khönia: He ono horö! U''ila sa, wa no solemba khö nono Giza''i andrö ndra''ugö, fangailau ba fangaila zaila ninau.', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 31, 'Götö sa wa''anau noso nono Giza''i ba guli danö, ba lö fakhai khöu, ba he ba wa''arazomö. Ba fatenge, fahalö''ö ia khögu; lö''ö sa tola auri ia.', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 32, 'Ba itema li namania Saulo Yonata, imane khönia: Hana wa labunu ia? Hadia horönia?', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 33, 'Ba ihandrogö khönia doho Saulo, ena''ö göna khönia. Ba me aboto ba dödö Yonata, no i''etu''ö amania, ibunu Dawido,[4]', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 34, 'ba maoso ia, mofönu sibai, iböhöli wemanga, lö i''a gönia, ba zi sambua desa''a andrö; afökhö ae bakha dödönia, börö Dawido andrö, me no itandraŵaisi amania.', '["MozIII 15; MozV 23:11","Faigi 18:11"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 35, 'Ba mahemolu ö, ba ihulö wongi Yonata we''amöi ba mbenua, me inötö niŵa''önia khö Dawido, i''ohe awönia ndraono.', '["MozI 33:3,4"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 36, 'Ba imane ba ndraono andrö khönia: Fulöi, alui nono wana andrö, ni''efasigu! Ba me fulöi nono matua andrö, ba i''efasi nono wana Yonata, sanalui ya''ia.', '["MozI 33:3,4"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 37, 'Ba me irugi ono matua andrö zaekhu ono wana andrö, ni''efasi Yonata, ba mu''ao khönia Yonata, imane: Hiza, tanö sa fönau!', '["MozI 33:3,4"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 38, 'Ba samuza tö mu''ao Yonata khönia: Ta''i-ta''i, böi bato! Ba ihalö nono wana no mege ono matua andrö, ba i''ohe khö zokhö ya''ia.', '["MozI 33:3,4"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 39, 'Ba lö''ö sa aboto ba dödö ndraono andrö, ha Yonata ba Dawido zangila eluaha.', '["MozI 33:3,4"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 40, 'Ba ibe''e ba danga nono matua andrö khönia wanania Yonata, imane khönia: Ae ohe miyomo!', '["MozI 33:3,4"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 41, 'Ba me mangawuli ndraono andrö, ba maoso Dawido, ba ngai hili-hili danö andrö ba ifalögu tou ia ba danö ba medölu ifaöndrö ia, ba fa''ago bawa ira ba faoma mege-ege, irege abölö-bölö sibai wege-ege Dawido[5]', '["MozI 33:3,4"]', NULL),
  (3474995, 'OT', 'Samueli I', 20, 42, 'Ba imane Yonata khö Dawido: Ae''e, böi busi dödöu: ba zi no möi ita ba hölu, darua ita, ba döi Yehowa, ba lö aefa si so ba mbörö Yehowa, he khöda ba he ba nga''ötöda dania, götö-götö wa''ara.', '["MozI 33:3,4"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 1, 'Ba maoso Dawido, mofanö ia, ba Yonata, ba ifuli ia ba khöra, miyomo.', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 2, 'Ba irugi Nobi Dawido, khö Gahimelekhi ere andrö. Ba i''ondrasi Dawido Ahimelekhi, mangalulu, imane khönia: Hana wa ha ya''ugö, wa samösa lö awöu.', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 3, 'Ba imane Dawido khö Gahimelekhi ere: No ibe''e li khögu razo, no imane khögu: Böi irongo niha hadia mbörö wamatengegu ya''ugö ba hadia goroisagu khöu; andrö wa no u''oroi''ö ba nono matua andrö khögu, we''amöi ba zane.', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 4, 'Ba iya''e, ba na lima ngawua roti khöu, ba da khögu, ba ma hadia ia mbö''önia zi so khöu!', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 5, 'Ba imane ere andrö khö Dawido: Lö hadia ia roti bö''ö khögu, ha roti ni''amoni''ö zi so; asala lö sorudu ba ndra alawe nono matua andrö.[1]', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 6, 'Ba itema li gere Dawido, imane khönia: Tölu bongi mege lö mutehe khöma ndra alawe, me mofanöga, ba lö salakha ba gama-gama nono matua andrö; ba he tenga ni''amoni''ö we''amöima andre, ba no ni''amoni''ö sa''ae ira ba wakake andrö.', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 7, 'Ba ibe''e khönia ni''amoni''ö ere; lö''ö sa roti bö''ö, ha roti nifaigi-faigi andrö, nihetaheta föna Yehowa, ba wame''e roti si bohou, na luo laheta ia.[2]', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 8, 'Ba me luo da''ö, ba so nitaha ba da''ö, föna Yehowa, ngoni-ngoni Zaulo, Dugi döinia, Iraono Gedomo, sabölö nawö Zaulo andrö.[3]', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 9, 'Ba imane Dawido khö Gahimelekhi: Hadia, so khöu hadia ia doho ba ma föda ba da''e? Lö''ö sa ni''ohegu si''öligu, ba he fangönagu bö''ö, me no aösö sibai goroisa razo.', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 10, 'Ba imane ere: Hiza sa zi''öli Goliato, Dawa Wilisiti andrö, nibunumö ba ndraso andrö, sabölö manawa; no mu''olohuni lembe ba gero mbaru ba doto andrö: na omasi''ö, ba halö, lö''ö sa bö''önia ba da''e. Ba imane Dawido: Lö si fagölö-gölö ba da''ö: da khögu![4]', '["MozIII 24:5–9; MozIII 22:3–7; MozII 19:15","Mat 12:3","Faigi 22:9,18","Faigi 17:50,51"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 11, 'Ba maoso Dawido, itohugö woloi khö Zaulo, isaŵa Nakhisi, razo Gata.[5]', '["Sin 56:1","Faigi 18:7; 29:5","Sin 34:1"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 12, 'Ba lamane khö Nakhisi ira awönia: Da''ö Dawido andrö, razo ba danö dania [khöra]; ya''ia nisuno zanari no, me lamane: "Hönö nibunu Zaulo, ba fulu ngahönö Dawido!"[6]', '["Sin 56:1","Faigi 18:7; 29:5","Sin 34:1"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 13, 'Ba itanö ba dödönia wehede andrö Dawido, ba ata''u sibai ia Nakhisi andrö, razo Gata.', '["Sin 56:1","Faigi 18:7; 29:5","Sin 34:1"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 14, 'Andrö wa i''osowöhö ia fönara, nifolau zowöhö nilaunia khöra ba da''ö, igukhugukhui lagö mbawa göli, ba mowöi ba gambinia gilonia.[7]', '["Sin 56:1","Faigi 18:7; 29:5","Sin 34:1"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 15, 'Ba imane Akhisi ba nawönia: Mi''ila wa no sowöhö niha andrö, hadia wa mi''ohe ba da''e khögu?', '["Sin 56:1","Faigi 18:7; 29:5","Sin 34:1"]', NULL),
  (3474996, 'OT', 'Samueli I', 21, 16, 'Hadia, ambö sowöhö khögu, wa mi''ohe da''ö, ena''ö faweawea ia khögu ba da''e? Da''ö ni''ohe ba gödo khögu?', '["Sin 56:1","Faigi 18:7; 29:5","Sin 34:1"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 1, 'Ba iheta ia ba da''ö Dawido, isaŵa dögi narö gara andrö ba zinga Gadula. Ba me larongo da''ö ira ga''ania ba si sawu ya''ira fefu, ba möi ira mitou khönia ba da''ö.[1]', '["Sin 57:1","Sanguhuk 11:3","Faigi 23:14; Sin 63:1"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 2, 'Ba fao khönia nifakao, ha niha ira, ba dozi si tosasa ba gömö ba ha niha zi lö sökhi-sökhi tödö, ba tobali högöra Dawido. Mato 400 niha, si fao khönia.[2]', '["Sin 57:1","Sanguhuk 11:3","Faigi 23:14; Sin 63:1"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 3, 'Ba moroi ba da''ö, ba isaŵa Misefa ba danö Ndraono Moabi Dawido, ba imane khö razo Ndraono Moabi: Hadia na ba khömi so ndra amagu inagu, irege u''ila, he wisa Lowalangi khögu?', '["Sin 57:1","Sanguhuk 11:3","Faigi 23:14; Sin 63:1"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 4, 'Ba iröi ira ba ngai razo Ndraono Moabi, khönia la''iagö, götö we''aso Dawido ba da''ö ba hili.', '["Sin 57:1","Sanguhuk 11:3","Faigi 23:14; Sin 63:1"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 5, 'Ba imane khönia sama''ele''ö andrö, Gado: Böi iagö hili andrö; labu, ae ba danö mado Yuda. Ba maoso Dawido mofanö ia, ba irugi Ya''ari Hereti.[3]', '["Sin 57:1","Sanguhuk 11:3","Faigi 23:14; Sin 63:1"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 6, 'Ba te''ombakha''ö khö Zaulo, wa no murongo heza so Dawido ba awönia fao andrö — ba Saulo, ba sidadao ba mbörö manawa ba Gibea, ba hili-hili, sara doho ba dangania, ba no lafasui ia ngoni-ngoninia andrö, fefu —', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 7, 'ba imane Saulo ba ngoni-ngoninia andrö, si tefasui ya''ia: Mifondrondrongo, ya''ami, ma''uwu Mbeniyami! Hadia, ibe''e maö göi khömi fefu nowi ba kabu nagu ono Giza''i andrö; hadia, ifataro ami fefu kumandra zi hönö ba kumandra zi otu?', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 8, 'Wa no mamagölö ami fefu, udugu, wa no samösa lö sahakhö tödö ya''odo, ba wangombakha khögu nirongoda ma''ökhö, wa no ifa''udu khögu zawuyugu andrö onogu?[4]', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 9, 'Ba humede Dugi andrö, Iraono Gedomo — no so ia ba da''ö ba ngai ngoni-ngoni Zaulo andrö — imane: No u''ila me irugi Gahimelekhi andrö, ono Gahitubi ba Nobi, ono Giza''i andrö.[5]', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 10, 'Ba isofu niŵa''ö Yehowa khönia da''ö; ba no ibe''e göi mbalazo khönia, ba si''öli Ndrawa Wilisiti andrö, Goliato, ibe''e khönia.[6]', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 11, 'Ba ifakaoni''ö razo Gahimelekhi andrö, ere, ono Gahitubi, ba si sawu ya''ira, ere andrö ba Nobi, ba so ira, dozi, la''ondrasi razo.', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 12, 'Ba imane Saulo: Fondrondrongo, ya''ugö, ono Gahitubi! Ba imane: Urongo, Tua!', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 13, 'Ba imane khönia Saulo: Hana wa no mamagölö ami, ya''ugö ba ono Giza''i andrö, udugu, wa no öbe''e khönia mbalazo ba si''öli, awö wa no ösofu mbawa Lowalangi khönia, fa tola ilaŵa ndra''odo, ni''ilada ma''ökhö?', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 14, 'Ba itema li razo Ahimelekhi, imane: Ba ha niha ba genoniu andrö fefu zi faduhu dödöda, si mane khö Dawido, lö lai wa no umönö razo ia ba högö wazuri khöu, awö wa nifosumange ia yomo khöu?[7]', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 15, 'Hadia, faefa mege ubörötaigö wanofu bawa Lowalangi khönia? Tenga! Böi yamube''e horögu razo ba böi yamube''e horö zi sawu ya''aga hadia ia, ma''ifu sa lö nirongo zawuyumö da''ö fefu!', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 16, 'Ba imane razo: Si mate ndra''ugö, Ahimelekhi, ya''ugö ba si sawu ya''ami fefu!', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 17, 'Ba imane razo ba nawönia andrö ba ngainia: Milabu, mibunu gere Yehowa andrö! Noa sa latolo göi Dawido, ba lö ni''ombakha''öra khögu, he ŵa''ae no la''ila, wa soloi ia. Ba lö edöna ngoni-ngoni razo andrö, lahalö tangara wamunu ere Yehowa andrö.', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 18, 'Ba imane razo khö Dugi andrö: Ba ya''ugö faoso, ba bunu gere andrö! Ba maoso Ndraono Gedomo andrö, Dugi, ya''ia zamunu ere andrö, 85 niha samaru baru ba doto andrö tarafali, ibunu me luo da''ö.', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 19, 'Ba banua Nobi andrö, banua gere, ba i''ö''ötö tou, he ira matua ba he ira alawe ba ono matua ba si lö aefa na ba mbagi zusu, ba saŵi ba kalide ba biri-biri, ba i''ö''ötö tou.[8]', '["Faigi 18:3","Ayati 22; Sin 52:2","Faigi 21:7–10","Faigi 18:22,27","Faigi 21:2"]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 20, 'Ha samösa zoloi, ono Gahimelekhi, ma''uwu Gahitubi, Abiataro döi, isaŵa Dawido, fao ia ba nawö Dawido andrö.', '[]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 21, 'Ba i''ombakha''ö khö Dawido Abiataro, imane: No ibunu gere Yehowa Saulo!', '[]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 22, 'Ba imane Dawido khö Gabiataro: Noa sa''ae u''ila me luo da''ö no, börö me no so ba da''ö Dugi andrö, Iraono Gedomo; u''ila sa''ae, wa i''ombakha''ö dania khö Zaulo: ba hulugu so noso niha andrö fefu, si sawu ya''ami!', '[]', NULL),
  (3474997, 'OT', 'Samueli I', 22, 23, 'Iagö khögu; böi busi dödöu, ha samunu ya''odo zamunu ya''ugö göi, rorogöfögu ndra''ugö.', '[]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 1, 'Ba lamane khö Dawido: Lasuwö Kegila Dawa Wilisiti, laraburabu wakhe ba golayama mbasitö![1]', '["Yos 15:44","Faigi 19:8"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 2, 'Ba isofu khö Yehowa Dawido, imane: Hadia, möido molau ba Ndrawa Wilisiti andrö? Ba imane Yehowa khö Dawido: Ae''e, ba lau ba Ndrawa Wilisiti andrö ba efa''ö Kegila.', '["Yos 15:44","Faigi 19:8"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 3, 'Ba lamane khö Dawido ira awönia: Ba ba da''e sa''ae, ba danö mado Yuda, ba ata''u ita, ba hadia, möi ita na ba Kegila, fasuwö ba Ndrawa Wilisiti sato?', '["Yos 15:44","Faigi 19:8"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 4, 'Ba ifuli isofu khö Yehowa Dawido, ba imane khönia Yehowa: Labu, ae misi tou ba Kegila, ube''e sa ba dangau Ndrawa Wilisiti.', '["Yos 15:44","Faigi 19:8"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 5, 'Ba möi ba Kegila Dawido ba awönia andrö, lalau ba Ndrawa Wilisiti, larabu guriföra, ba abölö sibai te''ala Ndrawa Wilisiti labe''e, me fasöndra ira. Tobali i''orifi mbanua Kegila andrö Dawido.[2]', '["Yos 15:44","Faigi 19:8"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 6, 'Ba mege, me isaŵa Dawido Abiataro andrö, ba no i''ohe misi tou mbaru ba doto.', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 7, 'Ba me te''ombakha''ö khö Zaulo, ba Kegila so Dawido, ba imane Saulo: Noa sa ibe''e ba dangagu ia Lowalangi; me no möi ia ba mbanua si so bawa göli nifolazi, ba no ya''ia zokuru ya''ia.', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 8, 'Ba humede Zaulo ba zato fefu, ba wanuwö, ba we''amöi ba Kegila, ba wama''u''u Dawido ba awönia andrö.', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 9, 'Ba me irongo Dawido, so dödö Zaulo si lö sökhi khönia, ba imane khö Gabiataro ere andrö: Ohe ba da''e mbaru ba doto andrö![3]', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 10, 'Ba mangandrö Dawido, imane: He Yehowa, Lowalangi Ndraono Gizeraeli! No irongo sawuyumö andre, wa no tödö Zaulo möi ia ba Kegila, ba wamakiko banua andrö, börö ndra''odo:', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 11, 'hadia, labe''e ba dangania dania ndra''odo banua Kegila andrö? hadia, möi mitou Zaulo andrö, itörö nirongo zawuyumö andre? He Yehowa, Lowalangi Ndraono Gizeraeli! Ombakha''ö khö zawuyumö andre! Ba imane Yehowa:', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 12, 'Itörö! Ba imane Dawido: Hadia, labe''e dania ba danga Zaulo ndra''odo ba awögu andrö banua Kegila andrö? Imane Yehowa: Labe''e.', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 13, 'Ba maoso Dawido ba awönia andrö, mato 600 ira, laheta ira ba Kegila ba sate latöröi danö misa. Ba me te''ombakha''ö khö Zaulo, no aefa ba Kegila Dawido, ba lö alua möi ia.', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 14, 'Ba ba danö si mate soso Dawido, ba hili misa, ya''ia ba hili ba danö si mate Sifi andrö. Ba i''alu-alui ia Saulo, sagötö fa''ara, ba lö ibe''e ba dangania Lowalangi.[4]', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 15, 'Ba ata''u Dawido, me möi Zaulo mangalui famunu ya''ia. Ba ba Horesi so Dawido, ba danö si mate Sifi.', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 16, 'Ba maoso nono Zaulo, Yonata, möi ia khö Dawido ba Horesi, ifuli i''abe''e''ö dödönia ba Lowalangi,', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 17, 'imane khönia: Böi ata''ufi, lö''ö sa möi''ö ba danga namada Saulo; razo Ndraono Gizeraeli dania ndra''ugö, ba tambalinamö dania ndra''odo — ba he amada Saulo, ba i''ila göi da''ö.', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 18, 'Ba fawu''u li ira föna Yehowa. Ba lö ibulö''ö ia ba Horesi Dawido ba ifuli ia khöra Yonata.[5]', '["Faigi 30:7","Ayati 19; Faigi 24:1","Faigi 18:3"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 19, 'Ba möi misi yaŵa ba Gibea khö Zaulo mbanua Zifi andrö, lamane: Hadia, tenga ba khöma ibini''ö ia Dawido, ba hili misa, ba Horesi, ba Gibeata Hakhila, tanö miraya, i''otarai danö si mate andrö?[6]', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 20, 'Ba ha wa''ara zomasi''ö a''i, ya''ugö razo, möi''ö mitou, ba tabu, ba ya''aga sa''ae zame''e ba danga razo ya''ia!', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 21, 'Ba imane Saulo: Ya''ahowu ami khö Yehowa, me no ahakhö dödömi ndra''odo.', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 22, 'Ba lau! ba mifaigi-faigi na, ba mita''i-ta''i misofu, heza so ia, heza tebato ia; noa sa la''ombakha''ö khögu, wa no sonekhe sibai.', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 23, 'Mizofu-zofu hadia mbini-mbini, nibini''önia ya''ia, ba mi''ombakha''ö khögu zi ndruhu-ndruhu, ena''ö möido awömi. Na so ia ba danö, ba u''alu-alui ia ba ngahönö ma''uwu Yuda.', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 24, 'Ba mowaö-waö ira föna Zaulo, ba danö si mate Sifi. Ba Dawido ba awönia, ba ba danö si mate Ma''ono so, ba zalo''o, raya danö si mate no mege.', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 25, 'Ba me möi Zaulo ba awönia andrö, ba wangalui Dawido; ba te''ombakha''ö khö Dawido, ba iheta ia ba gara andrö, ba danö si mate Ma''ono, möi ia mitou. Ba irongo Saulo ba i''o''ö Dawido ba danö si mate Ma''ono.', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 26, 'Ba ira Zaulo, ba ahe hili tanö andre latörö, ba ira Dawido, ba ahe hili ba zi tambai, ba ita''i-ta''i Dawido, fa böi ikhamö ia Saulo, ba Zaulo, ba i''alui wama''u''u ira Dawido.', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 27, 'Ba so zinenge, si lö mudöna-döna, möi ia khö Zaulo, imane: Ta''i-ta''i, fuli''ö! no larugi danöda sanuwö, Dawa Wilisiti.', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474998, 'OT', 'Samueli I', 23, 28, 'Ba iböhöli wolohi Dawido Saulo, möi mufaondragö Ndrawa Wilisiti. Andrö wa labe''e töi naha andrö Zea Mahelekoto (kara wa''aefa).', '["Faigi 26:1; Sin 54:2"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 1, 'Ba iheta ia ba da''ö Dawido, möi ia misi yaŵa, ba yaŵa ba hili ba Engedi i''iagö.[1]', '["Faigi göi Faza 26","Sin 142:1","SamII 1:14; Sin 105:15"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3474999, 'OT', 'Samueli I', 24, 2, 'Ba me no mangawuli Zaulo, me i''otarai wasuwöta ba Ndrawa Wilisiti, ba lamane khönia: Ba danö si mate Engedi so Dawido iada''e.', '["Faigi göi Faza 26","Sin 142:1","SamII 1:14; Sin 105:15"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 3, 'Ba i''ohe zi 3000 sabölö, nitutuyu ba Ndraono Gizeraeli fefu, möi ia, ba wangalui ira Dawido ba gara nago andrö.', '["Faigi göi Faza 26","Sin 142:1","SamII 1:14; Sin 105:15"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 4, 'Ba irugi kandra nambi andrö, ba ngai lala. Ba so dögi narö hili ba da''ö. Ba möi bakha Zaulo, ba we''amöi ba nidanö, ba Dawido ba awönia andrö, ba no dumadao ba da''ö, ba wondrege dögi andrö.[2]', '["Faigi göi Faza 26","Sin 142:1","SamII 1:14; Sin 105:15"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 5, 'Ba lamane khö Dawido ira awönia: Hiza, da''e mbaŵa andrö, niŵa''ö Yehowa khöu, me imane: Ube''e ba dangau dania nemaliu andrö, ena''ö ö''ila ölau khönia zomasi''ö! Ba maoso Dawido, ikumokumo wanaba watalinga mbaru Zaulo.', '["Faigi göi Faza 26","Sin 142:1","SamII 1:14; Sin 105:15"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 6, 'Ba dania, ba manutu dödö Dawido, me no itaba watalinga mbaru Zaulo andrö,', '["Faigi göi Faza 26","Sin 142:1","SamII 1:14; Sin 105:15"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 7, 'ba imane ba nawönia: Yamutegu ndra''o Lowalangi, na ulau zi mane da''ö khö zokhö ya''o, khö nibayoini Yehowa andrö, wombambaya ya''ia, me no nibayoini Yehowa ia.[3]', '["Faigi göi Faza 26","Sin 142:1","SamII 1:14; Sin 105:15"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 8, 'Ba itegu sibai nawönia Dawido, lö itehe khöra lalau khö Zaulo. Ba maoso Zaulo, iheta ia ba dögi narö hili andrö, mofanö ia.', '["Faigi göi Faza 26","Sin 142:1","SamII 1:14; Sin 105:15"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 9, 'Ba maoso göi Dawido, i''o''ö moroi ba dögi, ba mu''ao ia khö Zaulo, imane: He sokhö ya''o, razo! Ba ibali''o ia Saulo; ba ifalögu ia tou ba danö Dawido, mangalulu khönia.', '["Rom 12:19; FetI 2:23"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 10, 'Ba imane khö Zaulo: Hana wa öfondrondrongo deatea mbewe niha, na laŵa''ö: I''alui wamunumö Dawido?', '["Rom 12:19; FetI 2:23"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 11, 'Ma''ökhö andre, ba no höröu zangila, wa no ibe''e ba dangagu ndra''ugö Yehowa, ba dögi narö hili andrö, ma''ökhö. No laŵa''ö khögu: Bunu ia, ba salimagö ndra''ugö uŵa''ö, no umane: Lö ubabaya zokhö ya''o, me no nibayoini Yehowa!', '["Rom 12:19; FetI 2:23"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 12, 'Ba hiza, Ama, faigi ba dangagu watalinga mbarumö andrö! wa lö ubunu''ö, me utaba watalinga mbarumö andrö. Ya''aboto ba dödöu, ba ötöngöni, wa lö hadia ia zi lö sökhi ba dödögu, wa lö lalögu, wa lö horögu khöu. Ba ya''ugö, ba ö''alui wamunu ya''odo.', '["Rom 12:19; FetI 2:23"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 13, 'Yehowa zangasiwai huhuo andrö khöda, Yehowa dania zolau balögu khöu, ba lö uhalö tangagu wolau khöu.[4]', '["Rom 12:19; FetI 2:23"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 14, 'Itörö niŵa''ö ba gamaedola andrö khö ndra tua: Ba zanao horö moroi horö — ba lö uhalö tangagu wolau khöu.', '["Rom 12:19; FetI 2:23"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 15, 'Ha niha ni''alui razo Ndraono Gizeraeli? Ha niha nigohimö? Asu si no mate, landrindri si ha sambu-sambua!', '["Rom 12:19; FetI 2:23"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 16, 'Ba yamu''asiwai huhuo andrö khöda Yehowa, yamufaigi, yamufatunö huhuogu khöu ba yamu''ohe ba lala.', '["Rom 12:19; FetI 2:23"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 17, 'Ba me no i''o''ozui wehedenia andrö khö Zaulo Dawido, ba imane Saulo: Hadia, tenga liu da''ö, ya''ugö, onogu Dawido? Ba mege-ege sibai Zaulo.', '["Faigi 23:17"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 18, 'Ba imane khö Dawido: Satulö ndra''ugö moroi khögu: si sökhi nilaumö khögu, ba si lö sökhi nilaugu khöu.', '["Faigi 23:17"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 19, 'Ba no önönö na ma''ökhö zi sökhi andrö nilaumö khögu, me lö öbunu ndra''o, he ŵa''ae no ibe''e ba dangau ndra''odo Yehowa.', '["Faigi 23:17"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 20, 'Na so zi fakhamö khö nemalinia, ba hadia, ifofanö manö lö ilau khönia? Ba isulöni dania khöu si sökhi zi sökhi andrö, nilaumö khögu ma''ökhö andre.', '["Faigi 23:17"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 21, 'Ba hiza aboto sa''ae ba dödögu wa razo dania ndra''ugö, awö wa ba dangau aro dania wa''arazo andrö ba Ndraono Gizeraeli.[5]', '["Faigi 23:17"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 22, 'Ba ae ba hölu khögu khö Yehowa, fa böi öhori nga''ötögu ba fa böi öse''e döigu ba niwama.', '["Faigi 23:17"]', NULL),
  (3474999, 'OT', 'Samueli I', 24, 23, 'Ba fahölu Dawido khö Zaulo, ba ifuli ia ba khöra Saulo; ba Dawido ba awönia, ba möi miyawa ba zuzu hili.', '["Faigi 23:17"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 1, 'Ba mate Zamueli, ba uwulo Ndraono Gizeraeli fefu, ba wange''esi ya''ia, ba lako''o ia ba ngai nomonia ba Rama. Ba maoso Dawido, möi ia misi tou ba danö si mate Ma''ono.[1]', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 2, 'Ba so ba Ma''ono andrö niha sebua ana''a ba ba Garemeli so gurifönia; 3.000 nga''eu khönia mbiri-biri ba 1.000 nga''eu nambi. Ba moguti bu mbiri-birinia ia ba Garemeli, me luo da''ö.', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 3, 'Ba töi niha andrö, ba Nabalo, ba töi wo''omonia, ba Abigaila. Ira alawe satödö ba si sökhi bawa, ba ira matua andrö, ba no safaito ba si lö sökhi; ma''uwu Galebi ia.', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 4, 'Ba me irongo Dawido, ba danö si mate, moguti bu mbiri-biri Nabalo,', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 5, 'ba dafulu ifatenge ono matua, imane khöra: Mi''ae misi yaŵa ba Garemeli khö Nabalo, mi''owai ia khögu,', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 6, 'ba mimane khö ga''agu andrö: Sohahau tödö ndra''ugö, ba ba zi samba omo ya''ami, ba lö hadia ia, ba he ba zi so khöu fefu.', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 7, 'Ba no urongo, wa soguti bu mbiri-biri ami. Ba me no ba ngaima mege soso gubalo andrö khöu, me lö ni''o''ayama ya''ira ba me lö si taya hadia ia khöra, götö we''asora ba Garemeli —', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 8, 'sofu manö ba nono matua andrö khöu, ba la''ombakha''ö khöu — ba hana na ö''ebua''ö dödöu ba nono matua andre; noa sa ba mbaŵa si sökhi möiga khöu! Ba be''e ba zawuyumö andrö ba khö nonou Dawido hadia zi tola ö''efasi!', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 9, 'Ba me larugi sinenge Dawido andrö, ba ahori lafa''ema niŵa''ö Dawido, ba labase''ö lua-lua.', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 10, 'Ba imane Nabalo ba zinenge Dawido andrö: Ha niha Dawido andrö? ha niha nono Giza''i? Lö''ö sa ambö ma''ökhö zawuyu soloi khö zokhö ya''ira!', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 11, 'Hadia, ube''e ba niha si lö u''ila na''i heza moroi ira roti andrö khögu ba agu khögu ba urifögu andrö, nitabagu, ö zoguti andrö khögu?', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 12, 'Ba maoso zinenge Dawido andrö, mangawuli ira ba ahori la''ombakha''ö khö Dawido da''ö no mege.', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 13, 'Ba imane Dawido ba nawönia andrö: Dozi ami, ba mi''ani''öli! Ba mani''oli ira fefu. Ba ibe''e göi ba mböbö talunia zi''ölinia Dawido, ba mofanö ira, Dawido zolohe, mato 400 ira; ba 200 zi toröi, awö gama-gama.', '["Faigi 28:3"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 14, 'Ba barö ö, ba i''ombakha''ö ono matua samösa khö Abigaila, fo''omo Nabalo, imane: Hiza, no ifatenge zinenge Dawido, moroi ba danö si mate, ba wangowai sokhö ya''ita, ba no ihangöi ira.', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 15, 'Ba ya''ira andrö, ba no si sökhi si''ai tödö khöda; lö mu''o''aya ndra''aga ba lö irai taya khöma hadia ia, na soga ba danö, götö wanöröima sahatö khöra.', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 16, 'No timba göli kara ira khöma, götö wokubaloima biri-biri ba ngaira.', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 17, 'Andrö era-era tödöu, he öwisa wolau iada''e, noa sa la''etu''ö huku, ba wamakiko sokhö ya''ita, fabaya soroiyomonia fefu; ba ya''ia, ba si no töra fa''afaito, tebai fahuhuo ita khönia.', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 18, 'Ba i''aliogö Abigaila, ihalö zi 200 ngawua roti ba dombua nahia agu ba lima nga''eu biri-biri si no mu''asiwai, ba lima hinaoya böra nifakoe, ba 200 ngamohi bua nagu soköli ba 200 nga''örö kue mbua ara,', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 19, 'ifa''anö ba hulu galide, ba imane ba nono matua andrö khönia: Mi''owaö-waö, u''o''ö ami dania. Ba lö''ö sa i''ombakha''ö khö wo''omonia Nabalo.', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 20, 'Ba fakudo ia ba hulu galide. Ba me isaŵa mitou, ba zi toba''a hili, ba hiza moroi yaŵa Dawido ba awönia andrö, faondra ira.', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 21, 'Ba no imane dödönia Dawido: Hiza, fefu hadia ia gokhöta niha andrö, ba no ufaigi-faigi, ba danö si mate, saoha gölögu, tobali lö irai taya hadia ia motöi khönia: ba no isulöni khögu si lö sökhi zi sökhi andrö!', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 22, 'Yamulau khö Dawido Lowalangi, na usaigö irege moluo mahemolu zi kiöini bagolö, si so khönia, fefu!', '[]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 23, 'Ba me i''ila Dawido Abigaila, ba möi ia tou moroi ba hulu galide, ifalögu tou ia ba danö, föna Dawido, ira''u gahenia,', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 24, 'imane: He Tua, ya''odo zi so sala andrö! Ena''ö na tola muhede khöu zawuyumö andre, ba ena''ö na öfondrondrongo niŵa''önia!', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 25, 'Ena''ö na i''ositengagö zokhö ya''o niha si lö ngaroro andrö, Nabalo andrö; i''ohia''ö sa''ae döinia: Nabalo (sowöhö mowa) döinia, ba no fahöna khönia wa''owöhö mowa: ba ya''odo andre, sawuyumö, ba lö ni''ilagu zinengemö, nifatengeu andrö.', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 26, 'Ba iya''e, ya''ugö Tua, ba wa''aduhu wa''auri Yehowa ba ba wa''aduhu wa''aurimö, ya''ugö andrö, nitaha Yehowa tanga, fa böi mamunu niha ndra''ugö ba fa böi öhalö tangau wangorifi ya''ugö: hiza, hana na nifalaŵalaŵa khö Nabalo andrö zi fa''udu khöu, fabaya sangalui famunumö, ya''ugö Tua!', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 27, 'Ba hiza, ame''ela andrö, ni''ohe zawuyumö khöu, ya''ugö Tua, ba öbe''e ba nono matua andrö, awöu fao heza möi''ö.', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 28, 'Efa''ö khö zawuyumö andre lalö andrö, me si lö tebulö [razo] dania nga''ötöu ibe''e Yehowa, ya''ugö Tua, me no fanuwö khö Yehowa nilaumö ba me lö falukha khöu zi lö atulö, sagötö ya''ugö.', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 29, 'Na so zi maoso solohi ya''ugö ba sangalui famunu ya''ugö, ba ya nifarahugö ba ngamböbö zauri khö Lowalangiu, Yehowa, nosou, ya''ugö Tua ba noso zi fa''udu khöu andrö, ba yamufazaumba riboribo!', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 30, 'Ba na ifatörö dania khöu Yehowa nifabu''unia khöu si sökhi, ya''ugö Tua, ba na ifataro ndra''ugö razo Ndraono Gizeraeli:[2]', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 31, 'ba lö tobali fangala khöu, ba lö tobali tandraŵa, wa no aduwa ndro zi lö horö öbe''e, wa no öhalö tangau wangorifi ya''ugö, ya''ugö Tua. Ba na itolo''ö dania Yehowa, ya''ugö Tua, ba törö tödöu zawuyumö andre.', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 32, 'Ba imane Dawido khö Abigaila: Nisuno Yehowa, Lowalangi Ndraono Gizeraeli, samatenge ya''ugö ba wamaondragö ya''o,', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 33, 'ba nisuno wa''onekhemö andrö, nisuno ndra''ugö, ya''ugö si no manaha tangagu ma''ökhö, fa böi mamunu niha ndra''odo, fa böi uhalö tangagu, wangorifi ya''o!', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 34, 'Ba ba wa''aduhu wa''auri Yehowa, Lowalangi Ndraono Gizeraeli, si no manaha tangagu, fa böi ubunu ndra''ugö: na lö öta''i-ta''i mena''ö wamaondragö ya''odo, ba irege moluo mahemolu, ba lö tosai ena''ö khö Nabalo zi kiöini bagolö.', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 35, 'Ba ihalö Dawido ni''ohe Abigaila khönia, ba imane khönia: Fuli''ö ba khömi, böi busi dödöu. Hiza u''o''ö niwa''öu ba no so ba dödögu ndra''ugö!', '["SamII 5:2"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 36, 'Ba me irugi khöra, khö Nabalo, Abigaila, ba hiza gowuloa khönia yomo, timba gowuloa khö razo. Ba somuso tödö Nabalo ba no mabu sibai ia. Ba ma''ifu lö hede-hede Abigaila khönia, irege moluo.', '["SamII 3:15"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 37, 'Ba ba zanguhulö wongi, me no döhö wemabu Nabalo, ba itunö khönia da''ö no mege fo''omonia. Ba mate bakha dödönia, tobali hulö gara.', '["SamII 3:15"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 38, 'Ba so mato fulu bongi, ba ibözi Nabalo Yehowa, ba mate ia.', '["SamII 3:15"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 39, 'Ba me irongo Dawido no mate Nabalo, ba imane: Nisuno Yehowa, si no molau balö wango''aya ya''o andrö khö Nabalo ba si no manaha tanga genoninia andre, fa böi ilau zi lö atulö; ba no ifuli ifatörö khö Nabalo zi lö sökhi andrö nilaunia! Ba ifatenge Dawido, isofu Abigaila, ba wangai ya''ia.', '["SamII 3:15"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 40, 'Ba me larugi Abigaila, ba Garemeli, ba fahuhuo ira khönia, lamane: Dawido zamatenge ya''aga khöu, ba wangai ya''ugö, ena''ö fo''omonia ndra''ugö.', '["SamII 3:15"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 41, 'Ba maoso ia ba ifalögu tou ia ba danö, ba imane: Hiza, no ngoni-ngoni zawuyumö andre, iŵa''ö, ba wanasai ahe zinenge zokhö ya''o!', '["SamII 3:15"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 42, 'Ba maoso Abigaila, i''aliogö, fakudo ia ba hulu galidenia ba si manö nono alawe andrö khönia, dalima, awö-awönia fao. I''o''ö zinenge Dawido andrö ba tobali fo''omo Dawido ia.', '["SamII 3:15"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 43, 'Ba Ahinoa andrö, ba no ba Yezere''eli ihalö Dawido; ba fo''omo Dawido ira, darua, ira, ifakaerua.', '["SamII 3:15"]', NULL),
  (3475000, 'OT', 'Samueli I', 25, 44, 'Ba Mikhala andrö, ono Zaulo, fo''omo Dawido, ba no ibe''e Saulo khö Walati, ono La''isi, banua Galimo.[3]', '["SamII 3:15"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 1, 'Ba möi khö Zaulo ba Gibea mbanua Zifi andrö, lamane:[1] Hadia, tenga ba hili Hakhila, ba zinga danö si mate andrö, ibinibini''ö ia Dawido?[2]', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 2, 'Ba maoso Zaulo, 3000 i''ohe sabölö, nitutuyu ba Ndraono Gizeraeli, ba lasaŵa misi tou danö si mate Sifi, ba wangalui Dawido ba da''ö.', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 3, 'Ba ba hili Hakhila tebato Zaulo, ba zinga danö si mate, ba ngai lala; ba Dawido, ba no i''iagö danö si mate. Ba me irongo, no irugi danö si mate andrö Saulo wolohi ya''ia,', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 4, 'ba ifatenge zamauze, ba irongo, wa si ndruhu no so Zaulo.', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 5, 'Ba maoso Dawido, isaŵa zi tebato Saulo.[3] Ba me i''ila naha andrö, solombase Saulo, awö gumandra andrö khönia, Abineri, ono Neri — bakha barö göli kureta mörö Zaulo, ba no lafasui ia wemörö awönia andrö —', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 6, 'ba imane Dawido khö Ndrawa Kheti andrö, Ahimelekhi, ba khö Gabiza''i, ono Zeruya, talifusö Yoabi: Ha niha zi möi awögu mitou khö Zaulo ba golombaseŵa? Ba imane Abiza''i: Ya''o zi möi awöu mitou!', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 7, 'Ba me no larugi ira Dawido Abiza''i, ba zi bongi, ba hiza Zaulo, no mörö bakha barö göli kureta, ba no mutaru''ö ba danö dohonia, tanö ba högönia, ba Abineri ba sato, ba no lafasui ia.', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 8, 'Ba imane Abiza''i khö Dawido: No ibe''e ba dangau nemaliu andrö Lowalangi ma''ökhö: ba da''utandro ia ba danö toho andrö, ha samuza, alakha lö mendrua.[4]', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 9, 'Ba imane Dawido khö Gabiza''i: Böi bunu ia, ha niha sa zi no mombambaya nibayoini Yehowa lö fotu?', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 10, 'Ba imane na Dawido: Ba wa''aduhu wa''auri Yehowa! Lö zi lö mate ia, ma ibözi ia Yehowa ba irugi manö baŵa wa''amatenia, ba ma zui ba wasuwöta tekiko ia.[5]', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 11, 'Yamutimba ndra''o Yehowa, fa böi ubabaya nibayoini Yehowa! Ba halö doho andrö tanö ba högönia, awö mako nidanö khönia, ba mofanö ita.', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 12, 'Ba i''ohe sa''ae doho andrö, awö mako nidanö, si so tanö ba högö Zaulo, Dawido, ba lalau mofanö, lö sangila ya''ira, lö sanehe, lö si tokea; no ahori mörö ira, me no ihawui ira femörö sabölö-bölö si oroi Yehowa.[6]', '["Faigi göi Faza 24","Faigi 23:19; Sin 54:2","Faigi 14:50; 17:55","SamII 16:9","Faigi 28:10; 24:13","MozI 2:21; 15:12"]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 13, 'Ba möi miyefo Dawido, iagö zaröu ma''ifu, zuzu hili, tobali aröu gotaluara.', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 14, 'Ba mu''ao ia ba zato andrö, ba khö Gabineri, ono Neri, imane: Hadia, lö ötema li, Abineri? Ba imane Abineri: Ha niha ndra''ugö, si''ao khö razo?', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 15, 'Ba imane Dawido khö Gabineri: No sabölö ndra''ugö ae; ha niha zi fagölö-gölö khöu ba Ndraono Gizeraeli? — ba hana wa lö öfaigi-faigi zokhö ya''ugö, razo? Noa sa irugi sanuwö, ba wamunu sokhö ya''ugö andrö, razo?', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 16, 'Tenga si sökhi wolaumö andrö. Faya wa no sauri Yehowa, na tenga si mate ami ena''ö, me lö nifaigi-faigimi sokhö ya''ami andrö, nibayoini Yehowa! Ba faigi heza so doho razo ba heza so mako nidanö andrö, si so tanö ba högönia mege!', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 17, 'Ba irongo Saulo, wa li Dawido da''ö, ba imane: Hadia, tenga liu da''ö, ya''ugö onogu Dawido? Ba imane Dawido: Ya''ia, sokhö ya''o, razo!', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 18, 'ba imane na: Hana wa igohi zawuyunia andre sokhö ya''o? Hadia horögu atö, hadia zi lö sökhi khögu?', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 19, 'Ba ena''ö na ifondrondrongo iada''e sokhö ya''o razo niŵa''ö zawuyunia andre! Hadia, Yehowa zamarou ya''ugö ba wa''udusa khögu, ba da lafa''ago''ö khönia zumange; ba na niha zamarou ya''ugö, ba ni''elifi föna Yehowa, me no sanibo ya''odo maökhö, fa böi mo''urakha ndra''o ba nibe''e Yehowa, me laŵa''ö: Labu''ögö, fosumange Lowalangi bö''ö!', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 20, 'Ba böi mowöi ba danö ndrogu ba zi no aröu aefa khö Yehowa, me no möi razo Ndraono Gizeraeli, ba wangalui famunu ya''o, si mane na lagohi manu danö ba hili misa!', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 21, 'Ba imane Saulo: Horögu da''ö, fuli''ö, ya''ugö, onogu Dawido, lö''ö sa''ae ufakao''ö, sulö wa no ebua mböli nosogu öŵa''ö. U''ila sa''ae, no nifolau zambö tödö wolaugu ba no ebua sibai horögu!', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 22, 'Ba itema linia Dawido, imane: Ba ya''e doho razo; yamöi miyefo ba da''e zamösa, ba wangai ya''ia.', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 23, 'Ba Yehowa zanulöni ba zamösana fa''atulönia ba fa lö faröi; noa sa ibe''e ba dangagu ndra''ugö Yehowa, ma''ökhö, ba lö edönado uhalö tangagu wamunu nibayoini Yehowa.', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 24, 'Ba si mane fa''ebua mböli nosou khögu ma''ökhö, ya si manö wa''ebua mböli nosogu khö Yehowa, ba yamu''efa''ö ndra''o ba wa''atosasa fefu!', '[]', NULL),
  (3475001, 'OT', 'Samueli I', 26, 25, 'Ba imane Saulo khö Dawido: Ya''ahowu ndra''ugö, onogu Dawido: öfalua dania ba si möna ndra''ugö! Ba mofanö Dawido ba ifuli ia ba khöra Saulo.', '[]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 1, 'Ba imane dödönia Dawido: Samuza ma''ökhö dania, ba mate sa atö ndra''o ba danga Zaulo; si sökhinia, na moloi ndra''o, na usaŵa danö Ndrawa Wilisiti, ba ibato mötö Saulo wangalui ya''o ba danö Ndraono Gizeraeli ma''asagörö; ba tobali aefa ndra''o ba dangania.', '["Faigi 21:11; RazI 2:39","Faigi 25:40–43","Yos 15:31; Sanguhuk 1:19"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 2, 'Ba maoso Dawido, awö zi 600 niha andrö, si fao khönia, lasaŵa Nakhisi andrö, ono Ma''okhi, razo Gata.[1]', '["Faigi 21:11; RazI 2:39","Faigi 25:40–43","Yos 15:31; Sanguhuk 1:19"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 3, 'Ba khö Nakhisi ba Gata i''iagö Dawido ba awönia andrö, awö zoroiyomora fefu; fao göi wo''omo Dawido andrö, si dombua: Ahinoa, banua Yezere''eli ba Abigaila, lakha Nabalo andrö, banua Garemeli.[2]', '["Faigi 21:11; RazI 2:39","Faigi 25:40–43","Yos 15:31; Sanguhuk 1:19"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 4, 'Ba me te''ombakha''ö khö Zaulo, no isaŵa Gata Dawido, ba ibato Saulo wangalui ya''ia.', '["Faigi 21:11; RazI 2:39","Faigi 25:40–43","Yos 15:31; Sanguhuk 1:19"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 5, 'Ba imane Dawido khö Nakhisi: Na ebua atö dödöu khögu, ba te ötuturu khögu naha sambua, ba mbanua ba danö, heza u''iagö; hadia sa wa i''iagö ngaimö sawuyumö andre, ba mbanua sebua andre?', '["Faigi 21:11; RazI 2:39","Faigi 25:40–43","Yos 15:31; Sanguhuk 1:19"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 6, 'Ba ituturu khönia Zikelagi Akhisi, me luo da''ö; ba tobali banua razo mado Yuda Zikelagi andrö, irugi ma''ökhö andre.[3]', '["Faigi 21:11; RazI 2:39","Faigi 25:40–43","Yos 15:31; Sanguhuk 1:19"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 7, 'Ba fa''ara Dawido ba danö Ndrawa Wilisiti, ba öfa waŵa töra döfi.', '["Faigi 21:11; RazI 2:39","Faigi 25:40–43","Yos 15:31; Sanguhuk 1:19"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 8, 'Ba möi misi yaŵa Dawido, i''ohe nawönia andrö, ba lasuwö mbanua Gesuri andrö ba Iraono Girisi ba Iraono Gameleki; da''ö zowanua ba danö andrö, i''otarai Delama, numalö ba Zuri ba ba danö Miserayi mitou.', '["MozI 34:30; MozII 5:21"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 9, 'Ba na isuwö mbanua da''ö Dawido, ba lö isaigö, he ira matua, ba he ira alawe, ahori ibunu; ba biri-biri ba saŵi ba kalide ba ondra, fabaya gama-gama, ba i''ohe, ba ifuli ia khö Nakhisi.', '["MozI 34:30; MozII 5:21"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475002, 'OT', 'Samueli I', 27, 10, 'Ba na isofu Akhisi: Heza möi ami manuwö ma''ökhö? ba imane Dawido: Ba danö mado Yuda, tanö raya; ba ma: Ba ndraono Yerame''eli, tanö raya; ba ma zui: Ba ma''uwu Geni, tanö raya.', '["MozI 34:30; MozII 5:21"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 11, 'Ba samösa lö i''orifi Dawido, he ira matua, ba he ira alawe, lö ifa''amöi ba Gata, imane dödönia: Ma dania möi ira sasi, ma la''ombakha''ö: Da''ö nilau Dawido! Si manö wolau-launia, götö we''asonia ba danö Ndrawa Wilisiti.', '["MozI 34:30; MozII 5:21"]', NULL),
  (3475002, 'OT', 'Samueli I', 27, 12, 'Ba faduhu dödö Nakhisi khö Dawido, imane: No aböu döinia ba niwara, Iraono Gizeraeli, ba lö tebulö ia ba da''e enonigu.[4]', '["MozI 34:30; MozII 5:21"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 1, 'Ba me luo da''ö, ba owulo Ndrawa Wilisiti, ba wanuwö Iraono Gizeraeli. Ba imane Akhisi khö Dawido: Böi zi lö aboto ba dödöu, wa khögu fao ndra''ugö, fabaya banuau andrö, ba wanuwö.', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 2, 'Ba itema li Nakhisi Dawido, imane: Lau, ö''ila sa dania wolau zawuyumö andre! Ba imane Akhisi khö Dawido: Ba lau, ba ufataro samaigi-maigi ya''o ndra''ugö, götö wa''anau nosogu.', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 3, 'Ba Samueli, ba no mate; ba no la''e''esi ia Iraono Gizeraeli fefu, ba no lako''o ia, ba Rama. Ba no ifofanö zogaoni bekhu ba si faeta Saulo, no iheta ba danö.[1]', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 4, 'Ba owulo sa''ae Ndrawa Wilisiti ba larugi Zunema, ba da''ö tebato ira. Ba i''owuloi göi Ndraono Gizeraeli fefu Saulo, ba ba hili Giliboa tebato da''ö.', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 5, 'Ba me i''ila golombaseŵa Ndrawa Wilisiti Saulo, ba ata''u ia, manizi-nizi bakha dödönia.', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 6, 'Ba manofu khö Yehowa Zaulo, ba lö itema linia Yehowa, he ba wangifi, ba he ba "Urimi" andrö, ba he ba zama''ele''ö,[2]', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 7, 'Ba imane Saulo ba nawönia: Mi''alui khögu ndra alawe si so elemu, ba wogaoni bekhu, ena''ö möido khönia, ba wanofu khönia. Ba lamane awönia andrö: Ba Gendroro so ndra alawe, si so elemu ba wogaoni bekhu.[3]', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 8, 'Ba ibini''ö Saulo, wa ya''ia, nukha bö''ö i''onukha ba möi ia, ba darua nawönia fao. Ba ba zi bongi möi ira yomo ba ndra alawe andrö. Ba imane Saulo: Eta''ö khögu ba gelemu ba wogaoni bekhu andrö ba kaoni khögu nitötöigu töi khöu.', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 9, 'Ba imane khönia ira alawe andrö: No örongo ae nilau Zaulo, wa no ihori ba danö zogaoni bekhu, awö zi faeta, ba hana wa ölau dandraŵa khögu, ba wamunu ya''odo?', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 10, 'Ba möi ba hölu khönia Zaulo khö Yehowa, imane: Faya wa no sauri Yehowa, na tebe''e horöu dania da''ö!', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 11, 'Ba imane ira alawe andrö: Ha niha nikaonigu khöu? Ba imane: Samueli kaoni khögu.', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 12, 'Ba me i''ila Zamueli ira alawe andrö, ba mu''ira-ira ia. Ba imane khö Zaulo: Hana wa no ölimodo? Saulo ndra''ugö!', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 13, 'Ba imane khönia razo: Böi busi dödöu: hadia ni''ilau? Ba imane ira alawe andrö khö Zaulo: Bekhu u''ila moroi tou, barö danö.', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 14, 'Ba imane khönia: He wisa ia wamaigiu ya''ia? Ba imane: Niha satua zi möi yaŵa, baru sebua mbarunia. Ba aboto ba dödö Zaulo, wa Samueli, ba ifalögu tou ia ba danö, mangalulu.', '["Faigi 25:1; MozII 22:17","MozII 28:30; Faigi 14,37; 23:9","HalZin 16:16"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 15, 'Ba imane Samueli khö Zaulo: Hana wa öbusi dödögu wamakaoni''ö ya''odo? Ba imane Saulo: No tasasa sibai ndra''o. Lasuwö ndra''odo Dawa Wilisiti, ba no iheta ia khögu Lowalangi, lö''ö sa''ae itema ligu, he ba zama''ele''ö, ba he ba wangifi, ba andrö ufakaoni''ö ndra''ugö, ena''ö ö''ombakha''ö khögu he uwisa.', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 16, 'Ba imane Samueli: Ba hadia wa ösofu khögu, me no iheta ia khöu Yehowa, ba me no tobali si fa''udu khöu?', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 17, 'No ifatörö khöu Yehowa nifaŵa''ögönia khöu khögu no: no iheta khöu dadaoma wa''asalaŵa ba no ibe''e ba mbö''ö, khö Dawido andrö ibe''e.', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 18, 'Me no lö ni''o''ömö oroisa Yehowa, ba me lö nifatöröu fönunia andrö sabölö-bölö ba Ndraono Gamaleki, andrö ilau khöu zi manö Yehowa, ma''ökhö.[4]', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 19, 'Ifarahugö ami Ndraono Gizeraeli, wame''e ba danga Ndrawa Wilisiti; mahemolu a mate ndra''ugö, fabaya onou. Ba he sabölö Ndraono Gizeraeli andrö, ba ibe''e ba danga Ndrawa Wilisiti Yehowa.', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 20, 'Ba alau tou ba danö Zaulo, ba wa''atokea, adölö manö tou ba danö. Ihawui ia fa''ata''u sabölö-bölö ba niŵa''ö Zamueli andrö; ba noa sa''ae si lö döladöla ia, me no ma''öma''ökhö menewi ba sara wongi lö si manga ia.', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 21, 'Ba möi khö Zaulo ndra alawe andrö, ba me i''ila, wa no si tokea sibai ia, ba imane khönia: Hiza, no ifondrondrongo liu enoniu andre, ba no u''ositengagö manö nosogu, wolo''ö somasi''ö, niŵa''öu khögu.', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 22, 'Ba ö''o''ö sa''ae göi niŵa''ö genoniu andre khöu. Da''uhalö khöu zambawa roti, ba ö''a, ena''ö abe''e ndra''ugö, ba wangawuli.', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 23, 'Ba lö edöna ia, imane: Lö mangado! Ba me laforege ira awönia ba ira alawe andrö, ba i''o''ö niŵa''öra, maoso ia ba zalo ba mudadao ba gaso.', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 24, 'Ba no so barö mbatö ndra alawe andrö nono zaŵi nibula; ba igösö itaba, ba ihalö hamo, ifaruka ba ibali''ö kue.', '["Faigi 15:18,19"]', NULL),
  (3475003, 'OT', 'Samueli I', 28, 25, 'Ba ifa''oli khö ndra Saulo awönia, ba me no manga ira, ba maoso ira mofanö, ba zi bongi andrö.', '["Faigi 15:18,19"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 1, 'Ba la''owuloi zabölö khöra fefu Dawa Wilisiti ba Afeki, ba ba zinga gumbu nidanö ba Yezere''eli tebato Ndraono Gizeraeli.[1]', '["Faigi 4:1","Faigi 18:7"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 2, 'Ba me so zalaŵa Ndrawa Wilisiti, me la''ohe ngaotu khöra, awö ngahönö khöra ba me so göi moroi furi Dawido ba awönia andrö, awö Nakhisi,', '["Faigi 4:1","Faigi 18:7"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 3, 'ba lamane salaŵa Ndrawa Wilisiti: Hadia lawai niha Heberaio andrö? Ba imane Akhisi ba zalaŵa Ndrawa Wilisiti: Dawido da''ö, si so khö Zaulo mege, Saulo razo Ndraono Gizeraeli, no mendrua fakhe ia khögu, ba i''otarai luo da''ö, me isaŵa ndra''o, irege ma''ökhö, ba lö ni''ilagu hadia ia [zi sala] khönia.', '["Faigi 4:1","Faigi 18:7"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 4, 'Ba mofönu khönia zalaŵa Ndrawa Wilisiti, ba lamane khönia: Fatenge mangawuli niha andrö! Yamufuli ia ba nahania andrö, niŵa''öu khönia, böi fao ia khöda ba wanuwö, fa böi i''a mbölida ba wanuwö andrö. Hadia zi sökhi böli wa''ebua dödö zokhö ya''ia khönia, moroi ba högö mbanuada andre?', '["Faigi 4:1","Faigi 18:7"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 5, 'Hadia, tenga ya''ia Dawido andrö, nisunora no andrö, me manari, me lamane: "Ngahönö nibunu Zaulo, ba no ba ngafulu ngahönö nibunu Dawido?"[2]', '["Faigi 4:1","Faigi 18:7"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 6, 'Ba ifakaoni''ö Dawido Akhisi, ba imane khönia: Faya wa no sauri Yehowa, na tenga sadölö tödö ndra''ugö, ba somasi ndra''o, na awö-awögu ndra''ugö ba wanuwö, lö''ö sa ni''ilagu khöu si lö atulö, i''otarai me ösaŵa ndra''o, irugi ma''ökhö andre — ba salaŵa bö''ö andrö, ba lö omasi ira ndra''ugö.', '["SamII 19:28"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 7, 'Ba fuli''ö, ya lö hadia ia khöu, fa böi ölau hadia ia zi fatuwu ba zalaŵa Ndrawa Wilisiti andrö.', '["SamII 19:28"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 8, 'Ba imane Dawido khö Nakhisi: Ba hadia horögu? hadia, ni''ilau khö zawuyumö andre, i''otarai me möido enoniu, irugi ma''ökhö andre, wa lö möido fasuwö ba nemali razo sokhö ya''odo?', '["SamII 19:28"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 9, 'Ba itema li Dawido Akhisi, imane khönia: U''ila sa, wa no somasi ndra''o ndra''ugö, si mane mala''ika Lowalangi: ha salaŵa Ndrawa Wilisiti zanguma''ö: lö tola möi ia awöda ba wanuwö![3]', '["SamII 19:28"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 10, 'Ba mahemolu, ba faoso, awö mbanua zokhö ya''ugö, si fao khöu mege, me so''ö, mihulö sibai wongi, ba mifuli ami ba nahami andrö, niŵa''ögu khömi, ba böi mamaudu dödöu khögu, omasido sa ndra''ugö — mifaoso, si hulö si''ai wongi mahemolu, ena''ö na moluo sibai mangefa ami.', '["SamII 19:28"]', NULL),
  (3475004, 'OT', 'Samueli I', 29, 11, 'Ba manguwuli sa''ae ba danö Ndrawa Wilisiti Dawido ba awönia andrö, lahulö wongi. Ba lasaŵa misi yaŵa Yezere''eli Dawa Wilisiti.', '["SamII 19:28"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 1, 'Ba dua wongi, ba larugi Zikelagi Dawido ba awönia andrö. Ba no lasuwö danö andrö tanö raya, fabaya Zikelagi, Iraono Gamaleki, no morabu ira ba Zikelagi, ba no latunu mbanua.', '["Faigi 25:42,43"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 2, 'Ira alawe, ba ha niha zi so, he iraono, ba he satua, ba no lara''u; ba lö''ö sa nibunura, no la''ohe manö, ba no mofanö ira.', '["Faigi 25:42,43"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 3, 'Ba me larugi ira Dawido, ba no mutunu mbanua, ba ira alawera ba onora matua ba onora alawe, ba no mu''ohe nirabu.', '["Faigi 25:42,43"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 4, 'Ba mege-ege sibai Dawido ba awönia andrö, irege tebai sa''ae mege-ege ira.', '["Faigi 25:42,43"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 5, 'Ba fo''omo Dawido andrö, si darua, ba no murabu göi: Ahinoa andrö, banua Yezere''eli, ba Abigaila, fo''omo Nabalo no, banua Garemeli.[1]', '["Faigi 25:42,43"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 6, 'Ba abu sibai dödö Dawido, me latebu kara ia ena''ö sato, oi sa''ae afökhö ba dödö zato fefu nonora matua ba onora alawe. Ba i''abe''e''ö dödönia ba khö Lowalanginia Yehowa Dawido.', '["Faigi 25:42,43"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 7, 'Ba imane Dawido khö Gabiataro ere andrö: Tema ohe khögu mbaru ba doto andrö! Ba ihalö mbaru ba doto andrö Abiataro, ibe''e khö Dawido.[2]', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 8, 'Ba isofu khö Yehowa Dawido, imane: Hadia, ugohi zanuwö andrö? Hadia ukhamö ira maö? Ba imane khönia Yehowa: Gohi ira! Lö zi lö ökhamö ira ba lö zi lö ö''orifi [nirabu andrö].', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 9, 'Ba möi Dawido, i''ohe zi 600 niha andrö, si so khönia, ba larugi ndraso Mbezori. Ba toröi furi ösa.', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 10, 'Ba itohugö wolohi sanuwö andrö Dawido, awö zi 400 niha andrö; ba 200 zi toröi furi, no erege dödö, ba lö la''ötö Mbezori andrö.', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 11, 'Ba lasöndra Ndrawa Miserayi, ba lala, ba mbenua, ba la''ohe khö Dawido, ba labe''e önia roti ba lafabadugö khönia nidanö,', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 12, 'ba samba sinaba kue nilau bua ara ba dua ngamohi bua nagu soköli labe''e önia, ba ifuli auri: noa sa tölu ngaluo ba tölu mbongi lö si manga ia ba lö nibadunia idanö[3]', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 13, 'Ba isofu khönia Dawido, imane: Ha khö ndra''ugö ba heza ö''otarai? Ba imane: Ono matua Dawa Miserayi ndra''odo, sawuyu Ndraono Gamaleki. No iröido furi sokhö ya''o, me mofökhödo, tölu bongi ma''ökhö.', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 14, 'No möiga manuwö ba danö Ndrawa Gereti tanö raya ba ba danö mado Yuda ba ba danö ma''uwu Galebi, tanö raya, ba no matunu Zikelagi.[4]', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 15, 'Ba imane khönia Dawido: Hadia, ö''ohega ba zanuwö andrö? Ba imane: Ae ba hölu khögu khö Lowalangi, wa lö öbunudo, awö wa lö öfuli ba danga zokhö ya''o ndra''odo, ba u''ohe ami ba zanuwö andrö.', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 16, 'Ba ifasao ira, ba hiza, ba no muzaewe ba danö zanuwö andrö, manga-manga ira ba labadu-badu hadia ia, timba nilau owasa, börö nirabu andrö fefu, soya sibai, nihalöra ba danö Ndrawa Wilisiti ba ba danö mado Yuda.', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 17, 'Ba ilau khöra Dawido, i''otarai wa''amoluo, numalö ba wa''abongi, ba ibunu ira, tobali samösa lö soloi, ha öfa ngaotu, ono matua, si fakudo ba hulu gondra, awai zoloi.', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 18, 'Ba dozi nirabu Ndraono Gamaleki, ba i''efa''ö Dawido; he fo''omonia andrö, si dombua, ba i''efa''ö.', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 19, 'Tobali lö hadia ia zi taya, he side-ide, ba he sebua, he nirabu andrö [bö''önia] ba he ono matua ba he ono alawe, ba he hadia ia fefu, nirabura: ahori i''ohe mangawuli Dawido.', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 20, 'Ba lahalö fefu mbiri-biri ba saŵi, la''ohe khönia, ba lamane: Ahulua Dawido da''ö!', '["Faigi 23:9","Sanguhuk 15:19","SamII 8:18; Yos 14:13"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 21, 'Ba me irugi Dawido zi 200 niha no mege, si no erege tödö mege, ba si tebai fao khö Dawido, niröira ba ndraso Mbezori andrö, ba lafaondragö Dawido ba awönia andrö, ba me ahatö ndra Dawido, ba la''owai.', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 22, 'Ba humede niha si lö sökhi ba si lö ngaroro, si fao khö Dawido, lamane: Me lö si fao ira khöda, ba lö''ö göi tabe''e khöra gahulua andrö, nihalöda mangawuli, ha fo''omo zamösana ba iraononia: hana na la''ohe da''ö, ba akha mofanö ira.', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 23, 'Ba imane Dawido: Böi mimanö, me no itolo ita Yehowa, me no irorogö ita ba me no ibe''e ba dangada zanuwö andrö, si no mameta''u ya''ita!', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 24, 'Ba ha niha göi zamondrongo limi ba da''ö? Si mane tana ba zi möi ba wasuwöta andrö, si manö göi dania ba zi toröi furi, awö gama-gama: nifagölö-gölö wamaosa khöra![5] —', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 25, 'Ba si manö-manö dania, i''otarai luo da''ö. Da''ö ifakhoi ba ibe''e huku ba Ndraono Gizeraeli, irugi ma''ökhö andre.', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 26, 'Ba me no irugi zui Zikelagi Dawido, ba ihalö ösa gahulua no mege, ba ifa''ohe''ö ba zalaŵa mado Yuda, si fahuwu khönia, imane khöra: Hiza khömi mbuala, föfö nirabu zi fa''udu khö Yehowa!', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 27, 'Ba ba Mbetieli ifa''ohe''ö, ba ba Ramata, ba danö tanö raya, ba ba Yatiri,', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 28, 'ba ba Garara, ba ba Zifimoti ba ba Esemoa,', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 29, 'ba ba Garemeli ba ba mbanua ma''uwu Yerame''eli andrö, ba ba mbanua ma''uwu Geni,', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 30, 'ba ba Horama, ba ba Mborasa, ba ba Gatakhi.', '["MozIV 31:27"]', NULL),
  (3475005, 'OT', 'Samueli I', 30, 31, 'Ba ba Heberona, ba ba mbanua andrö fefu, nidörö-döröi Dawido ba awönia andrö mege.', '["MozIV 31:27"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 1, 'Ba barö ö, ba no lalau ba Ndraono Gizeraeli Dawa Wilisiti, ba no moloi Ndraono Gizeraeli labe''e Dawa Wilisiti, ba hiza tou ba danö nibunu, ba hili Giliboa.[1]', '["Ayati 1–13: Nga''ötI 10:1–12","Sanguhuk 9:54"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 2, 'Ba lö laböhöli Dawa Wilisiti wolohi Saulo ba ononia, ba labunu nono Zaulo, Yonata ba Abinadabi ba Malikhizua.', '["Ayati 1–13: Nga''ötI 10:1–12","Sanguhuk 9:54"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 3, 'Ba laforege wasöndrata khö Zaulo ba no la''ila ia si fafana ösa. Ba ata''u sibai Zaulo zi fafana andrö.', '["Ayati 1–13: Nga''ötI 10:1–12","Sanguhuk 9:54"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 4, 'Ba imane Saulo khö zolohe fangönania: Söbi wödamö ba fahö ndra''odo, fa böi möi zi lö muboto andrö, ba wango''aya ya''o! Ba lö edöna zolohe fangönania, ata''u sibai ia. Ba ituyu wöda Saulo, itaru''ö ba dödönia.[2]', '["Ayati 1–13: Nga''ötI 10:1–12","Sanguhuk 9:54"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 5, 'Ba me i''ila solohe fangönania, no mate Zaulo, ba itaru''ö göi khönia wödania ba mate ba ngai Zaulo.', '["Ayati 1–13: Nga''ötI 10:1–12","Sanguhuk 9:54"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 6, 'Tobali endronga mate ira, me luo da''ö, Saulo ba ononia andrö, si datölu, ba solohe fangönania.', '["Ayati 1–13: Nga''ötI 10:1–12","Sanguhuk 9:54"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 7, 'Ba me larongo Iraono Gizeraeli ba zi tambai zalo''o andrö ba yefo Yoridano, no moloi Ndraono Gizeraeli ba no mate Zaulo, fabaya iraononia andrö, ba laheta ira yomo khöra, moloi. Ba so Ndrawa Wilisiti ba la''iagö yomo khöra.', '["Ayati 1–13: Nga''ötI 10:1–12","Sanguhuk 9:54"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 8, 'Ba mahemolu ö, ba so Ndrawa Wilisiti, ba wangai gama-gama nibunu andrö, ba hiza Zaulo ba iraononia andrö, si datölu, ba hili Giliboa.', '["Faigi 11:1–11","SamII 1:12"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 9, 'Ba lataba mbaginia ba laheta khönia mbarunia sabe''e, ba lafatenge [zinenge], sanöröi tanö Ndrawa Wilisiti, ba wanuriaigö turia somuso dödö andrö ba nadura ba ba niha sato.', '["Faigi 11:1–11","SamII 1:12"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 10, 'Ba fangöna ba labe''e ba gosali Gasera ba botonia, ba lataŵi ba göli kara ba Mbetisana.', '["Faigi 11:1–11","SamII 1:12"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 11, 'Ba me larongo banua Yabesi ba danö Gileadi hadia nilau Ndrawa Wilisiti khö Zaulo,[3]', '["Faigi 11:1–11","SamII 1:12"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 12, 'ba maoso zabölöra fefu, sara wongi ira ba lala, ba latagö mboto Zaulo ba boto ndraononia andrö ba göli kara ba Mbetisana; ba lafuli ira ba Yabesi ba latunu ba da''ö, ba tölara,', '["Faigi 11:1–11","SamII 1:12"]', NULL),
  (3475006, 'OT', 'Samueli I', 31, 13, 'ba lahalö ba lako''o ba mbörö manawa ba Yabesi, ba mamoni ba gö ira, fitu bongi wa''ara.[4]', '["Faigi 11:1–11","SamII 1:12"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 1, 'Me no mate Zaulo ba me no mangawuli Dawido moroi ba wolohi Iraono Gamaleki andrö, ba dua wonginia ba Zikelagi, 2— ba mahemolu ö, ba hiza niha, samösa, awö Zaulo mege, no isika nukhania ba no ilau danö ba högönia. Ba me irugi Dawido, ba ifalögu tou ia ba danö, mangalulu.', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 3, 'Ba imane khönia Dawido: Heza ö''otarai? Ba imane: U''otarai Ndraono Gizeraeli, fasuwöta andrö.', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 4, 'Ba imane khönia Dawido: He wisa? Ombakha''ö khögu. Ba imane: No moloi zabölö, ba wasuwöta andrö ba no ato zi mate nibunu: ba he Saulo ba ononia Yonata, ba no mate.', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 5, 'Ba imane Dawido khö nono matua andrö, sangombakha khönia: Heza örongo, wa no mate Zaulo ba ononia Yonata?', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 6, 'Ba imane ono matua andrö, sangombakha: Urugi hili Giliboa, lö udöna-döna, ba hiza Zaulo, no itundreheni ia ba dohonia, ba lö aefa moroi furinia gureta ba si fakudo.[1]', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 7, 'Ba ibali''ö ia furi, ba me i''ila ndra''o, ba humede ia khögu, ba umane: Urongo!', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 8, 'Ba imane khögu: Ha niha ndra''ugö? Ba umane khönia: Iraono Gamaleki ndra''odo.', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 9, 'Ba imane khögu: Aine ba bunu ndra''o, noa sa ihawui ndra''o fekhölö-khölö mbanua, ba ma''ifu lö''ö na sa saetu nosogu!', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 10, 'Ba u''ondrasi ia, ubunu ia, me no u''ila lö auri ia, börö wa''ate''alania andrö. Ba uhalö zaembunia, ba högönia, ba töla gasa ba mbulökhania, ba hiza, ba no u''ohe khöu, ya''ugö Tua.', '["SamI 31:1—3"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 11, 'Ba ituyu nukhania Dawido, isika ba si manö göi nawönia fefu;[2]', '["MozI 37:29","SamI 31:13","SamI 24:7","Faigi 4:10,12","RazI 2:23,33"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 12, 'ba abu dödöra ba mege-ege ira ba mamoni ba gö, irege bongi, ba khö Zaulo ba ba khö nononia Yonata ba ba mbanua Yehowa andrö, ma''uwu Gizeraeli, me no mate ira ba mbawa zi''öli.[3]', '["MozI 37:29","SamI 31:13","SamI 24:7","Faigi 4:10,12","RazI 2:23,33"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 13, 'Ba imane Dawido khö nono matua andrö, sangombakha khönia: Ha banua ndra''ugö? Ba imane: Ono zi fatewu gana ndra''odo, Iraono Gamaleki.', '["MozI 37:29","SamI 31:13","SamI 24:7","Faigi 4:10,12","RazI 2:23,33"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 14, 'Ba imane khönia Dawido: Ba hadia, ba lö ata''u''ö öhalö tangau wamunu nibayoini Yehowa andrö?[4]', '["MozI 37:29","SamI 31:13","SamI 24:7","Faigi 4:10,12","RazI 2:23,33"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 15, 'Ba humede Dawido ba nawönia, ono matua, imane: Ae ba da''e ba bunu ia! Ba i''ö''ötö tou ba mate.[5]', '["MozI 37:29","SamI 31:13","SamI 24:7","Faigi 4:10,12","RazI 2:23,33"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 16, 'Ba imane na khönia Dawido: Ba hulumö sa so ndromö! No beweu zangetu''ö hukumö, me no ömane: No ubunu nibayoini Yehowa andrö.[6]', '["MozI 37:29","SamI 31:13","SamI 24:7","Faigi 4:10,12","RazI 2:23,33"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 17, 'Ba i''e''esi Zaulo ba ononia Yonata Dawido,', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 18, 'ba iŵa''ö, lafahaö ma''uwu Yuda, ba wange''esi andrö; hiza, no musura ba "zura zadölö tödö" andrö, imane:', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475007, 'OT', 'Samueli II', 1, 19, '"Famoadumi, ya''ami Iraono Gizeraeli, ba no mate nibunu ba hilimi! Alai wa''amate zabölö andrö!', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 20, 'Böi mi''ombakha''ö ba Gata; böi mifarongogö ba newali Gasekalo, fa böi omuso dödö nono Ndrawa Wilisiti alawe, fa böi ma''iki nono alawe ba niha si lö muboto.[7]', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 21, 'Ya''ami hili Giliboa, böi ya göna ami namo ba he teu, ya''ami benua si falimo! Me no ba da''ö tetibo mbaluse zabölö, baluse Zaulo andrö, lö mubayoini fanikha.[8]', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 22, 'Ba ndro nibunu andrö ba ba dawö zabölö, ba lö saböda fana Yonata, ba lö sangawuli föda Zaulo, lö ahulua.', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 23, 'Saulo ba Yonata, ba no faoma omasi ira nawöra ba no faoma ebua dödöra khö nawöra, me auri ira, ba no tenga göi si fabali ba wa''amate; ya''ira andrö, si no alio, moroi ba moyo ba si no abölö, moroi ba zingo.', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 24, 'Ya''ami, ono Ndraono Gizeraeli alawe, mi''e''esi Zaulo andrö, si no mamonukha ya''ami baru luo ungu, samuso dödömi, si no mamo''aya nukhami aya ana''a!', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 25, 'Alai wa''amate zabölö andrö, me hino wasöndrata — Yonata andrö, ba no mate nibunu ba hilimi!', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 26, 'Abu dödögu ndra''ugö, ya''ugö ga''agu Yonata; no omasiö ndra''ugö khögu! Wa''omasigu mege wa''omasimö ndra''odo, moroi ba wa''omasi ndra alawe ndra matua!', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475007, 'OT', 'Samueli II', 1, 27, 'Alai wa''amate zabölö andrö ba fa''afufu wangaro andrö ba wasöndrata!"', '["Mikh 1:10; SamI 18:6","MozIV 15:18—21"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 1, 'Aefa da''ö, ba isofu khö Yehowa Dawido, imane: Hadia, möido ba mbanua Yuda heza? Ba imane khönia Yehowa: Ae''e. Ba imane Dawido: Heza mbanua möido? Ba imane: Ba Heberona.[1]', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 2, 'Ba möi ba da''ö Dawido, awö wo''omonia andrö, si dombua, Ahinoa andrö, banua Yezere''eli ba Abigaila, lakha Nabalo andrö, banua Garemeli.[2]', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 3, 'Ba i''ohe göi nawönia andrö Dawido, awö zoroiyomora fefu, ba la''iagö mbanua andrö si tefasui Heberona.', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 4, 'Ba so mado Yuda, ba labayoini razo ma''uwu Yuda Dawido. Ba me la''ombakha''ö khö Dawido, wa no lako''o Zaulo banua Yabesi ba danö Gileadi,[3]', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 5, 'ba ifatenge zinenge Dawido ba mbanua Yabesi andrö ba danö Gileadi, imane khöra: Ya''ahowu ami khö Yehowa, me no mi''omasi''ö Zaulo andrö, sokhö ya''ami, ba me no miko''o ia!', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 6, 'Ba yamu''omasi''ö ami Yehowa ba böi ya faröi khömi, ba ya''odo göi, ba utolo ami, me no milau da''ö.', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 7, 'Ba iada''e, ba böi mi''ata''ufi hadia ia, ya sabölö ami. Noa sa mate Zaulo andrö, sokhö ya''ami mege, ba noa göi labayoini razora ndra''odo ma''uwu Yuda.', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 8, 'Ba ihalö Eseba''ali andrö, ono Zaulo, Abineri, kumandra khö Zaulo, i''ohe ba Mahana''i,[4]', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 9, 'ba ibali''ö razo ba danö Gileadi ba ba mado Gaseri ba ba Yezere''eli ba ba mado Geferayi ba ba mado Mbeniyami, razo Ndraono Gizeraeli fefu. 10öfa wulu fakhe Eseba''ali andrö, ono Zaulo, me tobali razo Ndraono Gizeraeli ia, ba mendrua fakhe wa''ara razo ia. Ha mado Yuda zolo''ö khö Dawido.', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 11, 'Ba fa''ara wa''arazo Dawido ba mado Yuda, ba Heberona, ba mewitu fakhe a matonga.', '["SamI 30:8","SamI 25:42,43","Faigi 5:3; SamI 16:13; 31:12","SamI 14:50"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 12, 'Ba maoso Gabineri andrö, ono Neri, i''ohe mbanua Eseba''ali andrö, ono Zaulo, ba lasaŵa Gibeona, la''otarai Mahana''i.', '[]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 13, 'Ba ifaondragö ira Yoabi, ono Zeruya andrö, i''ohe mbanua Dawido andrö, la''otarai Heberona, ba ba zinga mbaŵa nidanö andrö ba Gibeona fakhamö ira, ba lafatambai mbaŵa andrö.', '[]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 14, 'Ba imane Abineri khö Yoabi: Akha fasöndra nono matua ba zanehe ita! Ba imane Yoabi: Lau!', '[]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 15, 'Ba maoso ira, faondra ira, ni''ofaya, 12 mado Mbeniyami, banua Eseba''ali, ono Zaulo, ba 12 göi mbanua Dawido.', '[]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 16, 'Ba dozi latuyu mbu nudura ba lafahö ngai, ba tobali ahori mate ira, endronga. Andrö wa labe''e töi naha andrö "mbenua zi falimo", ba ngai Gibeona.', '[]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 17, 'Ba tobali fasöndrata sabölö-bölö sibai, me luo da''ö. Ba te''ala Gabineri ba awönia Iraono Gizeraeli andrö labe''e banua Dawido andrö.', '[]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 18, 'Ba no datölu zi so ba da''ö ono Zeruya andrö, Yoabi ba Abiza''i ba Azaheli; ba Azaheli andrö, ba no saoha sibai ahe, si mane nago ba mbenua.[5]', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 19, 'Ba igohi Gabineri Azaheli, si fulöi ia wolohi Abineri ba lö ihole''ö ia, he ba gambölö ba he ba gabera.', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 20, 'Ba ibali''ö ia furi Abineri, ba imane: Hadia, ya''ugö da''ö, Azaheli? Ba imane: Yaodo!', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 21, 'Ba imane khönia Abineri: Tema hole''ögö, ma ba gambölö, ba ma ba gabera, ra''u zamösa nono matua andrö ba halö khöu wangönania: Ba lö edöna iböhöli ia Azaheli.', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 22, 'Ba ifuli imane Abineri khö Gazaheli: Bato wolohi ya''odo! Hana wa u''ö''ötö tou ndra''ugö dania? Ba hadia, tola ufaöga na dania mbawagu khö ga''au Yo''abi?', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 23, 'Ba me lö edöna iböhöi ia, ba itaru''ö ba dalunia gi''o doho Abineri, tobali atöla dambai, alua ba hulunia doho ba tegaölö tou ia, mate, ba zi so ia. Ba dozi sondrugi naha andrö, si mate tou Gazaheli, ba labadugö ira.[6]', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 24, 'Ba lagohi Gabineri ira Yoabi Abiza''i, ba me aekhu luo, ba no larugi Gibeata Ama, ba zinga lala ba danö si mate, ba Gibeona,', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 25, 'ba owulo mado Mbeniyami, ni''ohe Gabineri, la''orudugö manö ira ba la''iagö zuzu hili ba Gibeata Ama.', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 26, 'Ba mu''ao Gabineri khö Yoabi, imane: Hadia, lö''ö manö tebato wemanga zi''öli, irugi zi lö aetu? Hadia, lö ö''ila, wa fa''abao dödö lua-lua dania? Ha wa''ara na, irege öŵa''ö ba zato, labato wolohi talifusöra?', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 27, 'Ba imane Yoabi: Ba wa''aduhu wa''auri Yehowa! Na lö öŵa''ö mena''ö, ba irege mahemolu mbanua, ba lö labato wolohi andrö, dozi ira.', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 28, 'Ba ifalau''ö dorofe Yoabi, ba labadugö ira sato fefu, laböhöli wolohi Iraono Gizeraeli, labato wasöndrata.', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 29, 'Ba mofanö Gabineri ba awönia, latörö zalo''o andrö, sara wongi, ba la''ötö Yoridano, latörö mbawa danö andrö, ma''asara ba larugi Mahana''i.', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 30, 'Ba i''owuloi zabölö andrö khönia fefu Yoabi, me no iböhöli wolohi Abineri; ba si lö''ö, banua Dawido, ba ha 19, lö lai Gazaheli andrö,', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 31, 'ba nibunu mbanua Dawido, mado Mbeniyami, awö Gabineri, ba no 360.', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475008, 'OT', 'Samueli II', 2, 32, 'Ba lahalö Gazaheli ba lako''o ia ba lewatö andrö khö namania, ba Mbetilekhema. Ba mofanö Yoabi ba awönia andrö, sara wongi manö ira ba lala, ba moluo me larugi Heberona.', '["Nga''ötI 2:16","Faigi 3:27"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 1, 'Ba me ara manö fazuwözuwö ira mbanua nono Zaulo mbanua Dawido, ba itugu abölö Dawido ba itugu awuwu mbanua nono Zaulo.[1]', '["Faigi 5:10","Nga''ötI 3:1—4; Faigi 13:1","RazI 1:5"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 2, 'Ba tumbu-tumbu ndraono khö Dawido ba Heberona: si a''a nononia, ba Amoni, ononia khö Gahinoa andrö, banua Yezere''eli.[2]', '["Faigi 5:10","Nga''ötI 3:1—4; Faigi 13:1","RazI 1:5"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 3, 'Ba fanete da''ö ba Kileabi, ononia khö Abigaila, lakha Nabalo andrö, banua Garemeli. Ba fanete da''ö, ba Abisalomi, ononia khö Ma''akha andrö, ono Dalamai, razo Gesuri.', '["Faigi 5:10","Nga''ötI 3:1—4; Faigi 13:1","RazI 1:5"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 4, 'Ba fanete da''ö, ba Adonia, ononia khö Hagita, ba fanete da''ö, ba Sefatia, ononia khö Gabitala.[3]', '["Faigi 5:10","Nga''ötI 3:1—4; Faigi 13:1","RazI 1:5"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 5, 'Ba fanete da''ö, ba Yiterea, ononia khö wo''omonia Egela. Da''ö zi tumbu khö Dawido ba Heberona.', '["Faigi 5:10","Nga''ötI 3:1—4; Faigi 13:1","RazI 1:5"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 6, 'Ba me ara manö fazuwözuwö ira mbanua nono Zaulo mbanua Dawido, ba khö nono Zaulo fa''awö Gabineri, lö iböhöi.', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 7, 'Ba so mege ndronga Zaulo, donga ba döi, Risifa döi, ono Aya. Ba imane Eseba''ali, ono Zaulo, khö Gabineri: Hana wa orudu ndra''ugö khö ndronga namagu andrö?[4]', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 8, 'Ba mofönu sibai Gabineri ba wanofu Eseba''ali andrö, ba imane: Hadia, asu mado Yuda ndra''o? Uhakhösi tödö nga''ötö namau Saulo ma''ökhö, fabaya si fatalifusö khöra ba si fahuwu khöra, ba lö möi''ö ba danga Dawido ube''e — ba ötegudo ma''ökhö, börö ndra alawe!', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 9, 'Yamulau khö Gabineri Lowalangi — hadia nifabu''u Yehowa khö Dawido, ba ya''odo zamalua:', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 10, 'Uheta ba nga''ötö Zaulo wa''arazo ba ufedadao dadaoma wa''asalaŵa khö Dawido, fa''asalaŵa ba Ndraono Gizeraeli ba ba mado Yuda, i''otarai Dano, numalö ba Mbereseba.', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 11, 'Ba tebai itema li Gabineri Eseba''ali, sambua li lö''ö, fa''ata''unia ia.', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 12, 'Ba ifatenge zinenge Abineri khö Dawido, ba Heberona, imane: Ha niha zokhö tanö? Datalau fawu''u li ba utolo''ö, ena''ö la''o''ö khöu Iraono Gizeraeli fefu öbe''e.', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 13, 'Ba imane Dawido: Lau, talau fawu''u li, ba sambalö niŵa''ögu khöu: lö fa''ila bawa ndra''ugö khögu, na lö ö''ohe Mikhala andrö, ono Zaulo, na möi''ö khögu.', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 14, 'Ba ifatenge zinenge Dawido khö Eseba''ali, ono Zaulo, imane khönia: Fa''ohe''ö khögu wo''omogu Mikhala, nibe''egu böwö botolö Ndrawa Wilisiti andrö, si otu![5]', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 15, 'Ba ifatenga Eseba''ali, ifadöni''ö khö wo''omonia Falatieli, ono La''isi.[6]', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 16, 'Ba fao khönia wo''omonia, i''o''ö, mege-ege manö, irugi Mbahurimi. Ba imane khönia Abineri: Labu''ögö, fuli''ö! Ba ifuli ia.', '["Faigi 21:8","SamI 18:25—27","SamI 25:44"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 17, 'Ba no fahuhuo Gabineri ba zatua Ndraono Gizeraeli, no imane khöra: No ara sa''ae omasi ami, na razomi Dawido:', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 18, 'ba mifalua iada''e, noa sa imane Yehowa ba khö Dawido andrö: Tanga genonigu Dawido andrö ufake dania, ba wangefa''ö banuagu Iraono Gizeraeli ba danga Ndrawa Wilisiti ba ba danga nemalira fefu.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 19, 'Ba si manö göi huhuo Gabineri ba mado Mbeniyami, ba möi ia na göi ba wangombakha khö Dawido ba Heberona he wisa dödö Ndraono Gizeraeli ba tödö mado Mbeniyami ma''afefu.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 20, 'Ba me larugi Dawido ba Heberona Abineri ba awönia andrö si 20, ba ifodiwo Gabineri ba awönia andrö Dawido.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 21, 'Ba imane Abineri khö Dawido: Damöido, ba wangowuloi khö razo sokhö ya''o Iraono Gizeraeli fefu, ena''ö fawu''u li ami — ba hana na razo ndra''ugö, heza ndrege zomasi''ö. Ba ifofanö Gabineri Dawido, ba mofanö ia lö hadia ia.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 22, 'Ba hiza, ba so zabölö andrö khö Dawido, awö Yoabi, la''otarai manuwö, ba no ebua gahulua, ba lö''ö sa''ae Abineri khö Dawido ba Heberona; noa sa ifofanö lö hadia ia.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 23, 'Ba me so Yoabi, awö zabölö andrö fefu, si no fao khönia, ba la''ombakha''ö khö Yoabi, lamane: No möi khö razo Gabineri andrö, ono Neri, ba no ifuli ifofanö lö hadia ia.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 24, 'Ba möi khö razo Yoabi imane: Hadia nilaumö andrö! Hiza, no möi khöu Gabineri: ba hana sa wa öfuli öfofanö ia?', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 25, 'Hadia, lö aboto ba dödöu, wa ba wolimo ya''ugö möi Gabineri andrö, ono Neri, ba ba wamauze fofanöu ba fangawuliu ba hadia ia fefu nilaumö andrö?', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 26, 'Ba me no iröi Dawido Yoabi ba ifatenge zinenge, solo''ö Abineri ba solohe mangawuli ya''ia, moroi ba Mbori Hasira; ba lö''ö sa nirongo Dawido.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 27, 'Ba me irugi Heberona Abineri, ba isöbi ia ba zi lö niha Yoabi, ba zinga, barö mbawa göli, ena''ö fahuhuo ia khönia ba zi ha ya''ira, ba itaru''ö ba dalunia zi''öli, ba mate ia, balö ndro nakhi Yo''abi Azaheli.[7]', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 28, 'Ba me irongo dania da''ö Dawido, ba imane: Ya''odo ba fa''arazogu, ba no si lö horö ba ndro Gabineri andrö, ono Neri, khö Yehowa, irugi zi lö aetu.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 29, 'Yatohare ba hulu Yoabi ba ba hulu nga''ötö namania fefu, ba böi ya mamalö-malö ba zi samba omo ndra Yoabi zi so sonana ba bou auri, awö niha sani''oni''o, ba si mate ba mbawa zi''öli ba sambö balazo!', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 30, 'Ba börö wa labunu mege Gabineri andrö Yoabi ba akhinia Abiza''i, ba me no ibunu nakhira Azaheli, ba wasöndrata no, ba Gibeona.', '["RazI 2:5; Faigi 2:23"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 31, 'Ba ibe''e li Dawido khö Yoabi ba ba zi so khönia andrö fefu, imane: Misika nukhami ba mi''olembe gonigoni ba mi''owaö-waö föna Gabineri, wange''esi ya''ia! Ba i''o''ö hasi razo, Dawido, ba me lako''o Gabineri,', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 32, 'ba Heberona, ba mege-ege sibai Dawido, i''otahögö lewatö Gabineri, ba mege-ege göi zato.[8]', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 33, 'Ba ilau wanunö andre khö Gabineri razo, imane: "Hadia, fa''amate zebua horö wa''amate Gabineri andrö?', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 34, 'Lö''ö sa muböbö dangau, ba lö murate gaheu. Fa''amateu andrö, ba no fa''amate ba danga zi lö sökhi." Ba tedou na wange''esi zato ya''ia.', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 35, 'Ba fatua lö bongi na, ba so zato, ba wamarou Dawido, ena''ö i''a gönia. Ba fahölu Dawido, imane: Yamulau khögu Lowalangi, na u''a roti, ba ma hadia ia, irege aekhu luo dania!', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 36, 'Ba me larongo da''ö sato, ba omasi ira. Fefu hadia ia nilau razo, ba omasi zato.', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 37, 'Ba aboto ba dödö zato, ba dödö Ndraono Gizeraeli fefu, me luo da''ö, wa tenga moroi khö razo wamunu Gabineri andrö, ono Neri.', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 38, 'Ba imane göi razo ba nawönia: Hadia, lö aboto ba dödömi, wa no salaŵa ba sebua Ndraono Gizeraeli zi mate ma''ökhö?[9]', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475009, 'OT', 'Samueli II', 3, 39, 'Ya''odo andre ma''ökhö, ba no samomo, he ŵa''ae no mubayoini razo ndra''odo, ba ya''ira andrö, Iraono Zeruya, ba no sabölö moroi khögu. Yamusuloni Yehowa awönia si lö sökhi zi lö sökhi andrö nilau zamösana.', '["SamI 30:4","SamI 26:15"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 1, 'Ba me irongo Eseba''ali ono Zaulo, no mate Gabineri, ba Heberona, ba atalö dödönia, ba Iraono Gizeraeli fefu, ba tobali dödö.', '["Faigi 9:3"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 2, 'Ba darua genoni Eseba''ali, ono Zaulo, solohe sanuwö, töi zi samösa, ba Ba''ana, ba töi zi samösa, ba Rekhabi, ono Rimono, banua Mbe''eroti, mado Mbeniyami; noa sa mube''e banua mado Mbeniyami göi Mbe''eroti andrö.', '["Faigi 9:3"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 3, 'Ba no moloi mbanua Mbe''eroti, no lasaŵa Gita''i ba ba da''ö la''iagö si fatewu gana, irugi ma''ökhö andre.', '["Faigi 9:3"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 4, 'Ba so nono Yonata, ono Zaulo, ono sombuyu-mbuyu ahe ma''adua: melima fakhe ia mege, me larongo duria ndra Saulo Yonata andrö, moroi ba Yezere''eli. Ba ituyu ia sangai ya''ia, ira alawe, ba moloi; ba ba wulöisa andrö, ba ahele ia ba dangania, ba fabesu gahe; ba töinia, ba Meriba''ali.[1]', '["Faigi 9:3"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 5, 'Ba maoso ndraono Rimono andrö, banua Mbe''eroti, Rekhabi ba Ba''ana, lasaŵa nomo Eseba''ali, me hino wa''aukhu zino, me no ilau mörö, me no aefa laluo.', '["Faigi 9:3"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 6, 'Ba sanaro ba mbawandruhö nomo, ira alawe, ba no alau hörö, ba wanafi fakhe, no mörö. Ba lakumokumo ira Rekhabi ba akhinia Ba''ana, lasaŵa yomo,', '["Faigi 9:3"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 7, 'ba labunu Eseba''ali, si no mörö si bakha, ba gasonia, ba la''eŵa mbagi. Ba lahalö högö, ba mofanö, latörö zalo''o andrö, sara wongi manö,', '["Faigi 9:3"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 8, 'ba la''ohe khö Dawido, ba Heberona, högö Eseba''ali, ba lamane khö razo: Ya''e khöu högö Eseba''ali andrö, ono nemaliu, Saulo, sangalui famunu ya''ugö mege; noa sa ilau mbalö zokhö ya''o, razo, Yehowa, ma''ökhö, khö Zaulo ba ba nga''ötönia.', '["Faigi 9:3"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 9, 'Ba itema lira Dawido, li ndra Rekhabi akhinia Ba''ana, ono Rimono, banua Mbe''eroti, imane khöra: Ba wa''aduhu wa''auri Yehowa, si no mangefa''ö nosogu ba wamakao andrö fefu:', '["Faigi 1:15"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 10, 'Sangombakha khögu no: No mate Zaulo, sanguma''ö tödönia sangombakha turia zalöfö ia, ba no ufara''u''ö ba Zikelagi ba no ufabunu''ö, wame''e luo wangombakha andrö khönia.[2]', '["Faigi 1:15"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 11, 'Ba na so a''i niha si lö sökhi, samunu satulö yomo khönia, ba gasonia — ba hadia, lö usugi ami ba ndronia andrö, ba hadia, lö uhori ami ba danö?', '["Faigi 1:15"]', NULL),
  (3475010, 'OT', 'Samueli II', 4, 12, 'Ba ibe''e li ba nawönia Dawido, ba la''ö''ötö tou ira, la''eŵa danga fabaya ahe, ba lataŵi ira ba zinga mbaŵa nidanö ba Heberona. Ba högö Eseba''ali andrö, ba lahalö, ba lako''o ba lewatö Gabineri, ba Heberona.', '["Faigi 1:15"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 1, 'Ba owulo khö Dawido ba Heberona mado Ndraono Gizeraeli fefu, lamane khönia: Hiza, no föföu ndra''aga![1][2]', '["Ayati 1—10: Nga''ötI 11:1—9","Faigi 19:13","SamI 13:14; 25:30","Faigi 2:4; SamI 16:13","RazI 2:11; Nga''ötI 29:27"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 2, 'No ara ae, me razoma na Zaulo, ba no ya''ugö sa''ae zolohe Iraono Gizeraeli ba wasuwöta ba solohe mangawuli ya''ira. Ba noa na ifabu''u khöu Yehowa, manguma''ö: Ya''ugö dania zokubaloi banuagu Iraono Gizeraeli ba razora ndra''ugö![3]', '["Ayati 1—10: Nga''ötI 11:1—9","Faigi 19:13","SamI 13:14; 25:30","Faigi 2:4; SamI 16:13","RazI 2:11; Nga''ötI 29:27"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 3, 'Ba la''ondrasi razo ba Heberona satua Ndraono Gizeraeli fefu, ba fawu''u li ira razo, Dawido, ba da''ö, ba Heberona, föna Yehowa, ba labayoini razo Ndraono Gizeraeli Dawido.[4]', '["Ayati 1—10: Nga''ötI 11:1—9","Faigi 19:13","SamI 13:14; 25:30","Faigi 2:4; SamI 16:13","RazI 2:11; Nga''ötI 29:27"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 4, 'Tölu ngafulu fakhe Dawido, me tobali razo ia; ba öfa wulu fakhe wa''ara razo ia.[5]', '["Ayati 1—10: Nga''ötI 11:1—9","Faigi 19:13","SamI 13:14; 25:30","Faigi 2:4; SamI 16:13","RazI 2:11; Nga''ötI 29:27"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 5, 'Ba Heberona, ba mewitu fakhe a matonga razo ia ba mado Yuda, ba ba Yeruzalema, ba tölu ngafulu a tölu fakhe, ba Ndraono Gizeraeli ba ba mado Yuda, fefu.', '["Ayati 1—10: Nga''ötI 11:1—9","Faigi 19:13","SamI 13:14; 25:30","Faigi 2:4; SamI 16:13","RazI 2:11; Nga''ötI 29:27"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 6, 'Ba me möi ba Yeruzalema razo, me i''ohe zabölö andrö khönia, ba wanuwö Iraono Yebusi, sowanua ba danö andrö, ba lamane khö Dawido: Tebai ösösö da''ö; sau''a ba sombuyu-mbuyu töla zanimba ya''ugö; eluahania: tebai ilaŵa ira Dawido.', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 7, 'Ba atu''a Dawido ba hati Siona andrö, ya''ia mbanua Dawido andrö.', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 8, 'Me luo da''ö, ba imane Dawido: Ha niha zame''e te''ala Ndraono Yebusi ba sau''a andrö ba sombuyu-mbuyu töla andrö, si fatiu tödö Dawido [ba tabe''e högö ba kumandra ia]. Andrö wa lawa''ö: "Lö möi yomo niha sau''a ba sombuyu-mbuyu töla."', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 9, 'Ba i''iagö hati andrö Dawido ba ibe''e töinia mbanua Dawido. Ba i''aro''ö na Dawido, fasui, i''otarai Milo andrö, ba numalö miyomo.', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475011, 'OT', 'Samueli II', 5, 10, 'Ba itugu tedou wa''abölö Dawido, itolo ia Yehowa, Lowalangi ngahönö.[6]', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 11, 'Ba ifatenge zinenge khö Dawido Hiramo, razo Diro, ifa''ohe''ö geu, eresi, ba fao duka, sotomo, ba sanoto kara, ba wangotomosi gödo khö Dawido.[7]', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 12, 'Ba aboto ba dödö Dawido, wa no i''aro''ö ia razo Ndraono Gizeraeli Yehowa, awö wa no i''ebua''ö wa''asalaŵania, börö mbanuania andrö, Iraono Gizeraeli.', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 13, 'Ba ba Yeruzalema, ba itohugö na Dawido wangai ira alawe, donga ba döi ösa, ba si ndruhu ndronga ösa, me no aheta ia ba Heberona, ba tumbu-tumbu na khönia ndraono, ono matua ba ono alawe.', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 14, 'Ba töi zi tumbu khönia ba Yeruzalema, ba Samua ba Sobaba ba Natano ba Selomo,[8]', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 15, 'ba Yibihari ba Elizua ba Nefegi ba Yafia,', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 16, 'ba Elizama ba Beliada ba Elifeleti.', '["Faigi 3:1","Ayati 11—25: Nga''ötI 14:1—16","Luk 3:21; Mat 1:6"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 17, 'Ba me larongo Dawa Wilisiti, wa no labayoini razo Ndraono Gizeraeli Dawido, ba so ira moroi si tou, dozi ira, ba wondra''u Dawido. Ba terongo khö Dawido ba möi ia mitou ba hati.', '["SamI 30:8"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 18, 'Be me no larugi danö Dawa Wilisiti, me no tebato ira ba ndraso ba Refa''i,', '["SamI 30:8"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 19, 'ba isofu khö Yehowa Dawido, imane: Hadia, ufaondragö miyaŵa Ndrawa Wilisiti? Hadia, öbe''e ba dangagu ira? Ba imane Yehowa khö Dawido: Ae''e, lö zi lö ube''e ba dangau Ndrawa Wilisiti.[9]', '["SamI 30:8"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 20, 'Ba irugi Mba''ali Werasi Dawido. Ba me no ilau khöra ba da''ö Dawido, ba imane: No ifabali fönagu nemaligu Yehowa, si mane na ihanigö hadia ia idanö; andrö wa labe''e töi naha andrö Mba''ali Werasi.', '["SamI 30:8"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 21, 'Ba laröi furi ba da''ö nadura, ba lahalö ira Dawido.', '["SamI 30:8"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 22, 'Ba mangawuli zamuza tö Ndrawa Wilisiti ba lahawui ndraso andrö ba Refa''i.', '["SamI 30:8"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 23, 'Ba me isofu khö Yehowa Dawido, ba imane khönia: Böi faondragö ira miyaŵa, fasui ira moroi furi ba ö''otarai mbörö keretau andrö wolau khöra.', '["SamI 30:8"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 24, 'Ba na örongo ruru zanörö ba hogu geretau andrö, ba labu, noa sa mowaö-waö fönau Yehowa, ba da''ö, ba wolau ba Ndrawa Wilisiti, ba zanuwö andrö.', '["SamI 30:8"]', NULL),
  (3475011, 'OT', 'Samueli II', 5, 25, 'Ba i''o''ö Dawido niŵa''ö Yehowa khönia, ba te''ala Ndrawa Wilisiti ibe''e, i''otarai Gibeona, irugi misa Gezeri.', '["SamI 30:8"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 1, 'Ba ifuli zui i''owuloi Dawido fefu nitutuyu andrö, Iraono Gizeraeli, 30.000.[1]', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 2, 'Ba maoso Dawido, awö niha andrö fefu, si fao khönia, lasaŵa Mba''ali ba mado Yuda, ba wangai miyaŵa moroi ba da''ö dawöla Lowalangi andrö, nibe''e börö döi töi Yehowa ngahönö andrö, sidadao yaŵa Kerubi.[2]', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 3, 'Ba lahare''ö ba gureta si bohou dawöla Lowalangi andrö, laheta ba nomo Gabinadabi andrö, ba hili; ba ono Gabinadabi, Usa ba Ahio, zolohe kureta.[3]', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 4, 'Ba ngai dawöla Lowalangi i''iagö Usa, ba sowaö-waö föna dawöla Gahio.', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 5, 'Ba Dawido ba ma''uwu Gizeraeli fefu, ba molaya föna Yehowa, a''oi dölara, ba manunö, lalau kezafi ba dandri ba rebana ba labözi waritia ba aramba.', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 6, 'Ba me larugi golayama mbasitö khö Nakhono, ba ira''u dawöla Lowalangi Usa, i''ohe, me lahole''ö ira saŵi andrö.', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 7, 'Ba mofönu sibai Yehowa khö Usa ba ibözi ia Lowalangi ba da''ö, me no ira''u dawöla, tobali ba da''ö mate ia, ba ngai dawöla Lowalangi.[4]', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 8, 'Ba lö sökhi-sökhi dödö Dawido, me no ira''u manö Usa andrö Yehowa, ba labe''e sa''ae töi naha andrö Weresi Usa [Fondra''u Usa], irugi ma''ökhö andre.', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 9, 'Ba ata''u Dawido Yehowa, me luo da''ö, ba imane: He lawisa wolohe khögu dawöla Yehowa andrö?', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 10, 'Ba anuzu sa''ae dödö Dawido, i''ohe miyaŵa khönia ba mbanua Dawido andrö dawöla Yehowa, ba ifabe''e''ö yomo khö Gobedi-Edomo, banua Gata.', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 11, 'Ba tölu waŵa dawöla Yehowa ba nomo Gobedi-Edomo, banua Gata. Ba ifahowu''ö Gobedi-Edomo andrö ba soroiyomonia fefu Yehowa.', '["Ayati 1—11: Nga''ötI 13","Yos 15:9; MozII 25:22","SamI 7:1","MozIV 4:15; SamI 6:19"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 12, 'Ba la''ombakha''ö khö razo Dawido,[5] lamane: No ifahowu''ö Yehowa zi samba omo ndra Obedi-Edomo andrö, awö fefu hadia ia nibaya-bayania, börö dawöla Lowalangi andrö. Ba maoso Dawido, ihalö dawöla Lowalangi andrö ba nomo Gobedi-Edomo, ba i''ohe ba mbanua Dawido andrö,', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 13, 'ba owua-wua dödöra, ba mame''e-me''e sumange ia ba da''ö. Ha önö mbeka la''ofanöi sangosa''ö tawöla Yehowa, ba sara nono zaŵi sebua-bua ba sara nono zaŵi nibula ibe''e sumange.[6]', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 14, 'Ba molaya Dawido föna Yehowa, a''oi dölania; ba no mobaru baru ba doto tarafali Dawido.', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 15, 'Ba la''ohe miyaŵa dawöla Yehowa ira Dawido ba ma''uwu Gizeraeli fefu, no owua-wua dödöra ba laforege lalau dorofe.', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 16, 'Ba me la''ohe miyomo ba mbanua Dawido dawöla Yehowa, ba ifaigi Mikhala, ono Zaulo, ba zandrela. Ba me i''ila razo, Dawido, me ifanoka ia föna Yehowa ba me molaya, ba anuzu dödönia ia.', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 17, 'Ba la''ohe miyomo dawöla Yehowa ba labe''e ba nahania, baose andrö, nilau Dawido nahania;[7] ba mame''e sumange Dawido föna Yehowa, sumange nitunu ba sumange fangorifi.', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 18, 'Ba me no i''o''ozui Dawido wame''e sumange andrö nitunu ba fangorifi, ba ifahowu''ö niha sato, ba döi Yehowa ngahönö;', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 19, 'ba ifaosa kue, ba niha satu, ba Ndraono Gizeraeli fefu, ha wa''ato ira, he ira matua, ba he ira alawe, sagörö kue roti ba samba botoboto agu ba sagorö kue nifaruka bua nagu zamösa. Ba mofanö niha sato, isaŵa khöra zamösana.', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 20, 'Ba me mangawuli yomo Dawido, ba wamaigi soroiyomonia, ba ifaondragö ia Mikhala, ono Zaulo, imane khönia: Wa''amoadu nilau razo Ndraono Gizeraeli ma''ökhö, me no iheta nukhania ma''ökhö, ba zanehe nono alawe, sawuyu mbanuania, si mane na iheta nukhania niha si lö ngaroro!', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 21, 'Ba imane Dawido khö Mikhala: Föna Yehowa molaya ndra''o, Yehowa sanuyu ya''o, föna namau ba föna nga''ötönia fefu, ba wamataro razo ya''odo, razo mbanua Yehowa, Iraono Gizeraeli, ba föna Yehowa edöna famaimai ndra''o.[8]', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 22, 'Edönado ide-ide na, moroi andrö, edönado tou sodo uŵa''ö. Ba ba nono alawe andrö, sawuyu andrö, niŵa''öu, ba ena''ö na ya''ira zamosumange ya''o.', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475012, 'OT', 'Samueli II', 6, 23, 'Ba Mikhala andrö, ono Zaulo, ba si lö ono, irugi wa''amatenia.', '["Ayati 12—16: Nga''ötI 15","RazI 8:5","Ayati 17—19: Nga''ötI 16","Faigi 5:2"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 1, 'Ba samuza ma''ökhö, me no ahono razo ba gödonia[1] — lö''ö sa''ae ameta''uö emali khönia ibe''e Yehowa,', '["Faigi göi Nga''ötI 17","Sin 132"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 2, 'fasui manö — ba imane razo khö zama''ele''ö andrö, Natano: Hiza sa, ba nomo eresi so ndra''o, ba nahia dawöla Lowalangi andrö, ba ose tufo![2]', '["Faigi göi Nga''ötI 17","Sin 132"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 3, 'Ba imane Natano khö razo: Ba faoso, ba lau hadia zi so ba dödöu; itolo''ö sa Yehowa.', '["Faigi göi Nga''ötI 17","Sin 132"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 4, 'Ba ba zi bongi andrö, ba so niŵa''ö Yehowa khö Natano, imane:', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 5, 'Ae khö genonigu Dawido, ba ömane khönia: Da''ö niŵa''ö Yehowa: Hadia, khögu ölau nomo, nahiagu?[3]', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 6, 'Ba lö''ö sa urai u''onahia nomo, i''otarai me uheta ba danö Miserayi Ndraono Gizeraeli, irugi ma''ökhö andre — barö nose tufo sa''ae utöröi danö.[4]', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 7, 'Götö me utöröi danö, ba Ndraono Gizeraeli, hadia, no urai uŵa''ö zambua li ba zanguhuku Iraono Gizeraeli, ha niha ia, ba niŵa''ögu wokubaloi banuagu andrö, Iraono Gizeraeli, wanguma''ö: Hana wa lö milau khögu gödo eresi?', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 8, 'Ba ömane dania khö genonigu Dawido: Da''ö niŵa''ö Yehowa ngahönö: No uhalö ndra''ugö, me kubalo mbiri-biri ndra''ugö, ena''ö razo mbanuagu Iraono Gizeraeli ndra''ugö,[5]', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 9, 'no utolo''ö ba ngawalö hadia ia fefu, nilaumö andrö, ba no uhori fönau nemaliu fefu, ba no u''asogö khöu döi, si falaŵalaŵa ba döi wondrege zebua ba guli danö,', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 10, 'ba ufonaha mbanuagu Iraono Gizeraeli, ba utanö ba da''ö, ena''ö la''iagö da''ö ba ena''ö lö''ö sa''ae ata''u ira, ba ena''ö lö''ö sa''ae lafakao ira niha si lö sökhi, si mane mege,', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 11, 'i''otarai me ufataro zanguhuku andrö, ba mbanuagu Iraono Gizeraeli, ba sahono ira ube''e, utimba nemalira fefu, tobali i''ombakha''ö khöu Yehowa, wa ya''ia zolau omo khöu.', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 12, 'Na no irugi baŵau dania, na no öleagö tou ndra''ugö, ba ngai ndra tuau, awena dania uhonogöi fangaliu ma''uwumö andrö, nga''ötöu, ba u''aro''ö wa''asalaŵania.[6]', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 13, 'Da''ö dania zolau omo ba döigu ba si lö tebulö dadaoma wa''asalaŵania, ube''e, irugi zi lö aetu.[7]', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 14, 'Amania ndra''o ba onogu ia. Ba na mosala ia, ba bözi-bözi ba niha uhalö fanegunia, famözi ba niha ube''e fotu.[8]', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 15, 'ba fa''ahakhö dödögu andrö, ba lö uböda khönia, tenga si mane famödagu ya''ia khö razo andrö, fönau.', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 16, 'Si lö tebulö fönagu nga''ötöu razo, irugi zi lö aetu: dadaomamö andrö, ba si lö awu''a, götö-götö wa''ara![9]', '["Nga''ötI 22:8; RazI 5:17","RazI 8:16,27; Yes 66:1","SamI 16:11—13","RazI 8:20; Yez. 9:6","RazI 5:19; 6:12; Sin 89:4,5","Sin 89:27; Heb 1:5; Luk 1:32","Sin 72:17; Yes 55:3"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 17, 'Ba dali sibai daroma li andrö, ba gangilata andrö, khö Natano ba wehedenia khö Dawido.', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 18, 'Ba möi baose Dawido, mudadao ia föna Yehowa, ba imane: He So''aya, Yehowa! Ha niha ndra''odo, ba ha niha zoroiyomogu fefu, wa no ötolodo, irugi da''e?[10]', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 19, 'Ba lö''ö na sa ahono dödöu ba da''ö, ya''ugö So''aya, Yehowa, noa na göi öfabu''u limö ba nga''ötö zawuyumö, si ogötö''ö dania, ba famahaö niha da''ö, ya''ugö So''aya, Yehowa.', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 20, 'Ba hadia na niŵa''ö Dawido khöu? Noa sa aboto ba dödöu zawuyumö andre, ya''ugö So''aya, Yehowa!', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 21, 'Börö zawuyumö andre ba dali dödöu ba wolaumö da''ö, wa no öfarongogö khö zawuyumö andre zi sökhi si''ai andrö, fefu.', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 22, 'Andrö wa sabölö ndra''ugö, ya''ugö So''aya, Yehowa; lö''ö sa si fagölö-gölö khöu ba lö Lowalangi, baerou, dali nirongoma tögi dalingama.', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 23, 'Ba heza so ba guli danö soi niha, si fagölö-gölö ba mbanuau Iraono Gizeraeli, si no möi Lowalangi ba wangöhöli ya''ia banuania, ba ba wangebua töinia, ba ba wamatörö khöra sebua andrö, ba sata''u ita, wanimba soi bö''ö, fabaya Lowalangira, föna mbanuania andrö?[11]', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 24, 'Ba no öhonogöi banuau mbanuamö Iraono Gizeraeli, si lö tebulö dania, götö-götö wa''ara, ba no tobali Lowalangira ndra''ugö, ya''ugö Yehowa.', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 25, 'Ba iya''e, ya''ugö So''aya, Yehowa, ba fatörö gamabu''ula limö andrö, nifobu''umö ba khö zawuyumö andre ba ba nga''ötönia, böi bulö''ö, götö-götö wa''ara, törö niŵa''öu andrö!', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 26, 'Ba si lö tebulö dania wa''ebua döimö, götö-götö wa''ara; Yehowa ngahöna, Lowalangi Ndraono Gizeraeli döimö — ba si lö tebulö fönau dania nga''ötö zawuyumö Dawido.', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 27, 'Noa sa ömane, ya''ugö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli, no ömane khö zawuyumö andre: Ya''odo zolau omo khöu. Andrö wa isöndra tödönia sawuyumö andre wangandrö andre khöu.[12]', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 28, 'Ba lau, ya''ugö So''aya, Yehowa, Lowalangi ndra''ugö ba no si ndruhu daroma limö andrö: me no öfabu''u zi sökhi andrö khö zawuyumö andre,[13]', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475013, 'OT', 'Samueli II', 7, 29, 'ba ena''ö na öfahowu''ö nga''ötö zawuyumö, ena''ö böi tebulö fönau, irugi zi lö aetu! Noa sa muhede ndra''ugö, ya''ugö So''aya, Yehowa, ba ba wamahowu''ömö andrö, ba nifahowu''ö nga''ötö zawuyumö andre, irugi zi lö aetu!', '["MozI 32:11","MozV 4:7","Yes 50:5","RazI 8:26"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 1, 'Ba aefa da''ö, ba ilau ba Ndrawa Wilisiti Dawido,[1] ihöndrögö ira; ifadöni khöra wamatörö andrö, ba mbanua sebua khöra.', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 2, 'Ba ilau göi ba Ndraono Moabi ba isu''a ira sinali, ifa''oli tou ba danö, nifama''oli dasa, ba dua-dua ndrohu sinali nibunu ba sandrosandrohu ni''orifi. Ba tobali barö mbawa Dawido Ndraono Moabi, same''e-me''e beo.', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 3, 'Ba isuwö na göi razo Zoba, Hadadezeri, ono Rehobo, Dawido, ba lala, me möi ia mamadöni tanö ba ndraso Warati. 41700 zi fakudo ba 20.000 zi lö kudo ifara''u''ö Dawido, banuara andrö, ba ba kudo, ba ahori ifa''eŵa''ö gölu''ölu, ha 100 nga''eu isaigö.[2]', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 5, 'Ba me so Ndrawa Garamo, banua Ndramaseko, ba wanolo Hadadezeri andrö, razo Zoba, ba 22.000 ibunu Dawido Dawa Garamo.', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 6, 'Ba ifataro gumandru Dawido ba danö Garamo, si tefasui Damaseko, ba tobali barö mbawa Dawido Ndrawa Garamo, same''e-me''e beo ira. Tobali abölö Dawido, fefu gofu heza irugi, ibe''e Yehowa.', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 7, 'Ba ihalö göi khönia Dawido mbaluse ana''a andrö, baluse genoni Hadadezeri andrö, ba i''ohe ba Yeruzalema.', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 8, 'Ba ebua sibai zahulu razo, Dawido, töla garamba ba mbanua Hadadezeri andrö, ba Deba ba ba Mberota''i.', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 9, 'Ba me irongo To''u, razo Hamata, no te''ala zabölö andrö khö Hadadezeri, fefu, ibe''e Dawido,', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 10, 'ba ifatenge khö razo Dawido nononia Hadoramo To''u andrö, ba wangowai ya''ia, ba ba wamahowu''ö ya''ia ba wanuwönia Hadadezeri andrö, si no abölö ia — noa sa fasuwö ira göi föna, Do''u Hadadezeri — ifa''ohe''ö khönia gama-gama ana''a ba firö ba töla.', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 11, 'Ba da''ö göi, ba i''amoni''ö khö Yehowa Dawido, awö wirö andrö, ba awö gana''a, ni''amoni''önia, nihalönia ba niha andrö fefu, nibe''enia barö mbawania:', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 12, 'ba Ndraono Gedomo ba ba Ndraono Moabi ba ba Ndraono Gamoni ba ba Ndrawa Wilisiti ba ba Ndraono Gamaleki, awö gahuluania andrö khö Hadadezeri, ono Rehobo, razo Zoba.', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 13, 'Ba ebua döinia ibe''e Dawido, ba me no mangawuli ia, me no te''ala Ndrawa Garamo ibe''e, ba ilau ba Ndraono Gedomo ba ndra''so nasio, 18.000 zi mate.[3]', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 14, 'Ba ifataro gumandru ba danö Ndraono Gedomo, ba danöra ma''asagörö, tobali barö mbawa Dawido Ndraono Gedomo ma''afefu. Ba abölö Dawido ibe''e Yehowa, fefu gofu heza irugi.[4]', '["Faigi göi Nga''ötI 18","Yos 11:9","Sin 60:2","MozI 27:40"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 15, 'Ba no razo ba Ndraono Gizeraeli fefu Dawido, huku satulö ifatörö ba mbanuania fefu.', '["Faigi 20:23—26","Faigi 15:18; SamI 30:14; Nga''ötI 18:17; RazI 4:5"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 16, 'Ba kumandra zabölö, ba Yaobi andrö, ono Zeruya, ba anofula, ba Yosafati, ono Gahiludi.[5]', '["Faigi 20:23—26","Faigi 15:18; SamI 30:14; Nga''ötI 18:17; RazI 4:5"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 17, 'Ba ere, ba Sadoki, ono Gahitubi, ba Abiataro, ono Gahimelekhi; ba Seraya, ba durutuli.', '["Faigi 20:23—26","Faigi 15:18; SamI 30:14; Nga''ötI 18:17; RazI 4:5"]', NULL),
  (3475014, 'OT', 'Samueli II', 8, 18, 'Ba högö wazuri, ba Benaya, ono Yehoyada. Ba iraono Dawido, ba ere göi.[6]', '["Faigi 20:23—26","Faigi 15:18; SamI 30:14; Nga''ötI 18:17; RazI 4:5"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 1, 'Ba isofu Dawido, imane: Hadia, so na zi tosai nga''ötö Zaulo? Da''uhakhösi tödö ia, börö Yonata.', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 2, 'Ba so na genoni Zaulo, Siba döinia, da''ö lafakaoni''ö khö Dawido. Ba imane khönia razo: Hadia, Siba döimö? Ba imane: Sawuyumö.[1]', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 3, 'Ba imane razo: Hadia, lö si tosai nga''ötö Zaulo, ena''ö uhakhösi tödö ia fa''ahakhö dödö Lowalangi? Ba imane Siba khö razo: So na nono Yonata sombuyu-mbuyu ahe.[2]', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 4, 'Ba imane khönia razo: Heza so ia? Ba imane Siba khö razo: Yomo khö Makhiro andrö, ono Gamieli, ba Lodebara.[3]', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 5, 'Ba ifatenge razo, Dawido, ifahalö''ö ba Lodebara, yomo khö Makhiro andrö, ono Gamieli.', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 6, 'Ba me irugi Dawido Meriba''ali andrö, ono Yonata, ma''uwu Zaulo, ba ifalögu tou ia, mangalulu. Ba imane Dawido: He Meriba''ali! Ba imane: Ya''odo, sawuyumö.', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 7, 'Ba imane khönia Dawido. Böi busi dödöu, uhakhösi tödö sa''ae ndra''ugö, börö namau, Yonata, ba ufuli khöu mbenua duau Saulo, fefu, ba ya''ugö, ba khögu manga-manga''ö, ero ma''ökhö.', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 8, 'Ba mangalulu Meriba''ali, ba imane: Ha niha zawuyumö andre, wa no so ba dödöu nasu si mate, ya''odo andre.[4]', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 9, 'Ba humede razo khö Ziba andrö, enoni Zaulo, imane khönia: Benua zi samba omo ndra Saulo, ba ube''e khö nono zokhö ya''ugö mege,', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 10, 'ba ya''ugö zangahalö khönia ba iraonou ba sawuyumö ba öbasi khönia, ena''ö isöndra mbalazo ono zokhö ya''ugö, önia; ba Meriba''ali, ono zokhö ya''ugö mege, ba khögu manga-manga, ero ma''ökhö. Ba no 15 ndraono Ziba andrö, ono matua, ba 20 zawuyu.', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 11, 'Ba imane Siba khö razo: Dali niŵa''ö zokhö ya''o, razo, khö zawuyunia, i''o''ö sibai sawuyumö andre. Ba khö Dawido manga-manga Meriba''ali, si mane ono razo.[5]', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 12, 'Ba so nono Meriba''ali, ono matua, Mikha döi. Ba dozi si so yomo khö Ziba, ba no sawuyu Meriba''ali.', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475015, 'OT', 'Samueli II', 9, 13, 'Ba ba Yeruzalema soso Meriba''ali, me khö razo manga-manga ia, ero ma''ökhö. Ba no sombuyu-mbuyu ahe ia, ahenia ma''adua.[6]', '["Faigi 16:1","Faigi 4:4","Faigi 17:27","SamI 24:15","Faigi 19:29","Ayati 3"]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 1, 'Ba aefa da''ö, ba mate razo Ndraono Gamoni, ba fangalinia razo, ba ononia Hanuno.[1]', '["Faigi göi Nga''ötI 19"]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 2, 'Ba imane Dawido: Da u''oroma''ö wa''ebua dödögu khö Hanuno andrö, ono Nahasi, si mane fa''ebua dödö namania mege khögu. Ba ifatenge khönia Dawido, ena''ö larara dödö Hanuno enoni Dawido andrö, ba khö namania. Ba me larugi danö Ndraono Gamoni sinenge Dawido,', '["Faigi göi Nga''ötI 19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475016, 'OT', 'Samueli II', 10, 3, 'ba lamane satua Ndraono Gamoni khö razora Hanuno: Hadia, faduhu dödöu, wa sumange namau khö Dawido wamatengenia khöu sondrara tödöu? Faya na tenga ba wamauze banua ifatenge khöu genoninia Dawido, ba wamauze ua ba ba wanudugö dania.', '["Faigi göi Nga''ötI 19"]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 4, 'Ba ifara''u''ö zinenge Dawido Hanuno, tambai ifatöwö''ö gambira ba barura, ba lafalo''ö irege ba daro''ö, ba ifatenge mangawuli ira.', '["Faigi göi Nga''ötI 19"]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 5, 'Ba me te''ombakha''ö da''ö khö Dawido, ba ifatenge zamaondragö ya''ira — noa sa mu''o''aya sibai ira — imane khöra Dawido: Mi''iagö Yerikho, irege ifuli anau gambimi, ba awena dania mifuli ami.', '["Faigi göi Nga''ötI 19"]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 6, 'Ba me aboto ba dödö Ndraono Gamoni, wa no abao dödö Dawido khöra, ba lafatenge, la''oni Ndrawa Garamo ba Mbeti Rehobo ba Dawa Garamo ba Zoba, 20.000 zabölö, si lö kudo, awö razo Ma''akha ba banua Gisitoba, 12.000.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 7, 'Ba me irongo da''ö Dawido, ba ifatenge Yoabi, awö zabölö fefu, saradadu andrö.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 8, 'Ba so moroi yomo Ndraono Gamoni, la''angenoligö ira fönaföna mbawa göli mbanua, ba Dawa Garamo no mege, banua Zoba ba banua Rehobo ba banua Gisitoba ba banua Ma''akha, ba baero ba mbenua la''iagö.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 9, 'Ba me i''ila Yoabi, faoma dania lalau khönia, he moroi föna, ba he moroi furi, ba ituyu zabölö ba nono matua Ndraono Gizeraeli fefu, ba i''ohe, ba wamaondragö Dawa Garamo andrö.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 10, 'Ba si tosai, sato, ba ibe''e ni''ohe nakhinia Abiza''i, ba wolau ba Ndraono Gamoni.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 11, 'Ba ibe''e li ba da''ö, imane: Na tebai ulaŵa Ndrawa Garamo, ba möi''ö manolo ya''odo; ba na tebai ölaŵa Ndraono Gamoni, ba so ndra''o, ba wanolo ya''ugö.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 12, 'Abe''e''ö dödöu ba ena''ö faoma abe''e ita, ba wangorifi banuada ba banua Lowalangida andrö — ba yamulau zomasi ia Yehowa!', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 13, 'Ba ifaondragö Ndrawa Garamo Yoabi, ba wolau khöra, i''ohe zabölö andrö, si fao khönia, ba moloi Ndrawa Garamo ibe''e.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 14, 'Ba me la''ila Iraono Gamoni moloi Ndrawa Garamo andrö, ba moloi göi ira föna Gabiza''i, lawuwu ira miyomo ba mbanua. Ba iböhöli Ndraono Gamoni Yoabi, ifuli ia ba Yeruzalema.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 15, 'Ba me la''ila Dawa Garamo andrö, no te''ala ira labe''e Iraono Gizeraeli, ba la''owuloi ira,', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 16, 'ba ifatenge Hadadezeri, ifakaoni''ö Ndrawa Garamo yefo Oifarati. Ba larugi Helami, ba solohe ya''ira, ba Sobakhi, kumandra andrö khö Hadadezeri.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 17, 'Ba me te''ombakha''ö da''ö khö Dawido, ba i''owuloi Ndraono Gizeraeli fefu, ba la''ötö Yoridano ba larugi Helami. Ba lafaondragö Dawido Dawa Garamo, fasöndra khönia.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 18, 'Ba moloi Ndrawa Garamo labe''e Iraono Gizeraeli, ba labunu ira Dawido kudo Ndrawa Garamo, 700, kudo sondröni kureta, ba 40.000 niha nibunu; ba mesokho göi gumandrara Sobakhi, labe''e, ba mate ia ba da''ö.', '[]', NULL),
  (3475016, 'OT', 'Samueli II', 10, 19, 'Ba me la''ila razo andrö fefu, si so barö mbawa Hadadezeri, no te''ala ira labe''e Iraono Gizeraeli, ba la''atulö''ö ira ba Ndraono Gizeraeli, möi barö mbawara, ba ata''u sa''ae Ndrawa Garamo, latolo na Ndraono Gamoni.', '[]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 1, 'Ba döfi furi ö, me baŵa wanuwö razo, ba ifatenge Yoabi Dawido, awö zi so barö mbawania andrö ba Iraono Gizeraeli fefu. Ba lafufu danö Ndraono Gamoni ba lafasui Raba, ba no toröi ba Yeruzalema Dawido.[1]', '["Nga''ötI 20:1","Mat 5:28,29","Faigi 23:39","MozIII 15:18"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 2, 'Ba samuza ma''ökhö, me tanö owi, me no maoso Dawido, ba manörö-nörö ia ba dete gödonia; ba i''ila moroi yaŵa ba dete gödo andrö ndra alawe si mondri. Ba no si sökhi si''ai bawa ndra alawe andrö.[2]', '["Nga''ötI 20:1","Mat 5:28,29","Faigi 23:39","MozIII 15:18"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 3, 'Ba ifatenge Dawido, ifasofu''ö ha niha ndra alawe andrö. Ba la''ombakha''ö khönia, lamane: Baseba da''ö, ono Geliami, fo''omo Guria andrö, ma''uwu Kheti.[3]', '["Nga''ötI 20:1","Mat 5:28,29","Faigi 23:39","MozIII 15:18"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 4, 'Ba ifatenge zinenge Dawido, ifahalö''ö. Ba me so ia, ba orudu khönia Dawido, ba ifuli mondri, iheta khönia zi ra''iö andrö. Ba ifuli ia khöra.[4]', '["Nga''ötI 20:1","Mat 5:28,29","Faigi 23:39","MozIII 15:18"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 5, 'Ba no abeto galawe andrö. Ba ifatenge khö Dawido, imane khönia: No abeto ndra''odo.', '["Nga''ötI 20:1","Mat 5:28,29","Faigi 23:39","MozIII 15:18"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 6, 'Ba ifatenge khö Yoabi Dawido, imane: Fatenge khögu Guria andrö, ma''uwu Kheti. Ba ifatenge khö Dawido Guria.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 7, 'Ba me irugi yomo khö Dawido Uria, ba isofu khönia Dawido, na lö hadia ia khö Yoabi ba he ba zato ba he wisa wasuwöta andrö.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 8, 'Ba imane na khönia Dawido: Ae mitou khömi ba sasai gaheu. Ba me möi tou Guria, me iröi gödo, ba la''ohe khönia, moroi furinia, mbuala razo.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 9, 'Ba ilau mörö Uria, ba zinga mbawandruhö ba gödo, awö genoni zokhö ya''ia fefu, lö möi ia mitou khöra.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 10, 'Ba me lamane khö Dawido: Lö si möi mitou khöra Guria, ba imane khönia Dawido: ö''otarai wekoli a''i, ba hana wa lö möi''ö mitou khömi?', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 11, 'Ba imane Uria khö Dawido: Ba nose soso dawöla andrö, ba Iraono Gizeraeli, ba ma''uwu Yuda, ba ba danö tou mörö-mörö zolohe ya''o andrö, Yoabi, ba banua zokhö ya''o, ba hadia, ba nomogu möi ndra''o, ba wemanga ba ba wamadu hadia ia ba ba wanalagui fo''omogu? Faya wa no sauri Yehowa ba faya wa sauri ndra''ugö, na ulau zi manö![5]', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 12, 'Ba imane Dawido khö Guria: Ba lau, ba iagö da''e bongi, ba mahemolu, ba ufofanö ndra''ugö. Ba i''iagö Yeruzalema Uria, me luo da''ö.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 13, 'Ba mahemolu ö, ba ifakaoni''ö ia Dawido, ba wemanga khönia ba ba wamadu agu, ba ibusi agu. Ba me bongi, ba möi ia baero, ba wemörö, awö genoni zokhö ya''ia; ba lö''ö sa möi ia mitou ba nomonia.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 14, 'Ba mahemolu ö, ba ifazökhi zura Dawido, khö Yoabi, ifa''ohe''ö khönia khö Guria.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 15, 'Imane ba zura andrö: Tanö föna, ba zabe''e fasöndrata mibe''e Guria, ba miwuwu ami furinia, ena''ö mate ia ba wasöndrata andrö.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 16, 'Ba ba ni''ilania so zabölö ibe''e Guria Yoabi, ba wama''u''ura banua andrö.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 17, 'Ba me so moroi yomo mbanua da''ö, ba wolau khö Yoabi, ba so zi mate ösa, sabölö, banua Dawido. Ba mate göi Guria andrö, ma''uwu Kheti.', '["SamI 4:4"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 18, 'Ba ifatenge Yoabi, ifa''ombakha''ögö khö Dawido he wisa wasöndrata andrö fefu;', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 19, 'imane sa''ae khö zinenge andrö: Na no ahori ö''ombakha''ö khö razo he wisa wasöndrata andrö fefu,', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 20, 'ba na mofönu razo, na imane: Hana wa no mihatö''ö ami ba mbanua, ba wasöndrata andrö? Hadia, lö mi''ila, wa moroi yaŵa ba göli lafana ami?', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 21, 'Ha niha mege zamunu Abimelekhi andrö, ono Yerubi-Mba''ali? Hadia, tenga ira alawe zanibo tou, ba högönia, kara gisa wakhe, moroi ba göli, ba Debesi, si mate ia? Hana wa no mihatö''ö ami ba göli? — ba ömane: Enoniu Uria andrö, ma''uwu Kheti, ba no mate göi![6]', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 22, 'Ba möi zinenge andrö, ba me irugi, ba i''ombakha''ö khö Dawido fefu niŵa''ö Yoabi khönia, he wisa wasöndrata andrö fefu. Ba mofönu Dawido khö Yoabi, ba imane khö zinenge andrö: Ba hana wa mihatö''ö ami ba mbanua, ba wasöndrata andrö? Hadia, lö mi''ila, wa moroi yaŵa ba göli lafana ami? Ha niha mege zamunu Abimelekhi andrö, ono Yerubi-Mba''ali? Hadia, tenga ira alawe zanibo tou, ba högönia, kara gisa wakhe, moroi ba göli, ba Debesi, si mate ia? Hana wa no mihatö''ö ami ba göli?', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 23, 'Ba imane sinenge andrö khö Dawido! No abölö ira moroi khöma, no lafaondragö ndra''aga, larugi si tou mbenua, ba andrö matimba ira, irugi ba mbawa göli.', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 24, 'Ba lafana moroi yaŵa ba göli genonimö si fafana andrö, ba mate genoni razo, mato feleŵalu, ba mate göi genonimö Uria andrö, ma''uwu Kheti.', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 25, 'Ba imane Dawido khö zinenge andrö: ömane khö Yoabi: Böi busi dödöu da''ö, si''öli andrö sa, ba ma''ökhö da''e ba mahemolu da''ö i''a; abölögö lau ba mbanua andrö ba dudugö! — abe''e''ö dödönia.', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 26, 'Ba me irongo fo''omo Guria andrö, no mate wo''omonia Uria, ba i''e''esi ngambatönia andrö.', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475017, 'OT', 'Samueli II', 11, 27, 'Ba me no ahöwö mbaŵa wa''abu dödö andrö, ba ifatenge Dawido, ifahalö''ö ia ba gödonia, ba tobali fo''omonia, ba mo''ono ia, ono matua.[7]', '["Sanguhuk 9:53","MozII 20:13,14"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 1, 'Ba lö omasi Yehowa nilau Dawido, ba ifatenge khö Dawido Natano andrö, sama''ele''ö. Ba möi yomo khönia da''ö, ba imane khönia: So niha föna, darua, ha sambua mbanuara, so''ana''a zi samösa, ba si numana zi samösa.', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 2, 'Ba khö zo''ana''a andrö, ba oya sibai mbiri-biri ba saŵi,', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 3, 'ba ba zi numana andrö, ba lö hadia ia, ha si''ai sara nono mbiri-biri, ni''ölinia ba ni''e''ebuania, ebua ia khönia, si faedo ononia. I''a wöfö gönia ba i''amadugö mako khönia, ba gahetania mörö ba timba nono alawe khönia.', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 4, 'Ba so dome zo''ana''a andrö, ba alimagö khönia, ihalö zageu mbiri-birinia ba ma saŵinia, ba wame''e ö domenia andrö, si no möi khönia, ba ihalö nono mbiri-biri zi numana andrö ba ibe''e ö domenia.', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 5, 'Ba mofönu sibai Dawido ba niha andrö, ba imane khö Natano: Ba wa''aduhu wa''auri Yehowa, niha andrö, solau da''ö, ba nibunu,', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 6, 'ba ono mbiri-biri andrö, ba mewitu i''ali, me no ilau da''ö ba me lö fa''ahakhö dödönia![1]', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 7, 'Ba imane Natano khö Dawido: Ya''ugö niha andrö! Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: No ya''odo zamayoini razo Ndraono Gizeraeli ya''ugö ba no ya''odo zangefa''ö ya''ugö ba danga Zaulo,', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 8, 'ba no ube''e khöu gödo zokhö ya''ugö mege, ba ira alawe zokhö ya''ugö, ba no ube''e khöu, nitalagui; ba ma''uwu Gizeraeli ba ma''uwu Yuda, ba no ube''e barö mbawau, ba na ambö na da''ö ena''ö, ba unönö na wame''e khöu, hadia ia na.', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 9, 'Ba hana wa ö''ositengagö li Yehowa ba hana wa ölau zi fatuwu khönia? Uria andrö, ma''uwu Kheti, ba no öbunu si''öli, ba fo''omonia ba no öhalö dongau, ba ya''ia, ba no öbunu si''öli Ndraono Gamoni.[2]', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 10, 'Ba böi sa''ae yamuböhöli zi samba omo ya''ami si''oli, götö-götö wa''ara, fotu, me no lö ba dödöu ya''o, ba me no öhalö dongau wo''omo Guria andrö, ma''uwu Kheti![3]', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 11, 'Imane Yehowa: Moroi yomo khöu u''asogö wamakao ya''ugö, ba uhalö ngambatöu, ba zanehe ndra''ugö, ba ube''e ba danga niha bö''ö, ena''ö orudu ia khöra, ba zi moluo.[4]', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 12, 'Ya''ugö, ba no ba zi tobini ölau da''ö, ba ya''odo, ba ba zanehe Ndraono Gizeraeli fefu ba ba zi moluo ulau niŵa''ögu andre!', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 13, 'Ba imane Dawido khö Natano: Horögu da''ö khö Yehowa. — Ba itema li Dawido Natano, imane: Ba noa göi i''efa''ö khöu horöu Yehowa; lö mate ndra''ugö.', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 14, 'Ba me no ö''o''aya Yehowa ba nilaumö andrö, ba si mate nono andrö, si no tumbu khöu.[5]', '["MozII 21:37","Faigi 11; RazI 15:5","Faigi 13:28,29; 18:14; RazII 25:7","Faigi 16:22; Yob 31:9,10","Faigi 11:27"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 15, 'Ba mangawuli khöra Natano. Ba ibözi nono andrö Yehowa, ono wo''omo Guria andrö khö Dawido, ba mofökhö.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 16, 'Ba i''angaröfi li Lowalangi Dawido ba nono andrö, ba mamoni ba gö ia ba möi ia si bakha, ba tou ba zalo manö so ia, sara wongi.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 17, 'Ba möi khönia zatua baomonia, ba wangandrö khönia, ena''ö maoso ia, ba lö i''o''ö ba lö manga ia awöra.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 18, 'Ba önö bongi, ba mate nono andrö. Ba ata''u genoni Dawido andrö, la''ombakha''ö khönia, wa no mate nono andrö, lamane dödöra: Lö''ö sa ifondrondrongo khöda, me auri na nono, me humede ita khönia, ba he tawisa wangombakha khönia: No mate nono, ma dania ilau hadia ia.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 19, 'Ba i''ila Dawido, me fangöngö-ngöngö genoninia andrö; ba da''ö aboto ba dödönia, wa no mate nono. Ba imane Dawido ba genoninia andrö: Hadia, no mate nono? Ba lamane: Noa.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 20, 'Ba maoso Dawido, isasai mbawania, ibayoini ia fanikha ba ifohani ia. Ba möi ia ba nose Yehowa mangalulu ia, ba ifuli ia ba nomonia mangandrö gö; ba me no lahalö gönia, ba manga ia.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 21, 'Ba lasofu khönia enoninia andrö, lamane: He wisa wolaumö andrö, ba khö nono andrö? Me auri ia na, ba mamoni ba gö ndra''ugö, ba mege-ege''ö — ba iada''e, me no mate nono, ba maoso ndra''ugö ba manga''ö!', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 22, 'Ba imane: Fatua auri na nono, ba mamoni ba gö ndra''o ba mege-egedo, me no umane dödögu: Ha zangila, ma dania ahakhö dödö Lowalangi, fa böi mate nono andrö.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 23, 'Ba iada''e, me no mate ia, ba hadia, wa mamoni ba gö ndra''o? Hadia, u''ila u''orifi? Möido sa khönia dania, ba lö''ö sa ifuli ia khögu.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 24, 'Ba me no irara dödö wo''omonia Baseba andro Dawido, ba möi ia si bakha khönia, orudu ia khönia. Ba mo''ono ia, ono matua. Ba Selomo ibe''e töi nono andrö Dawido; ba i''omasi''ö Yehowa nono andrö.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 25, 'Ba ibe''e rorogöfö Natano, sama''ele''ö andrö, Dawido, ba ibe''e töinia Yedidiya (omasiö Yehowa) Natano, börö Yehowa.', '[]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 26, 'Ba isuŵosuwö Raba, banua Ndraono Gamoni, Yoabi, ba atu''a ia ba mbanua nidanö andrö.[6][7]', '["Ayati 26—31: Nga''ötI 20:1—3","Yer 49:2"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 27, 'Ba ifatenge zinenge khö Dawido Yoabi, imane khönia: No usuwö Raba ba no atu''a ndra''o ba mbanua nidanö andrö —', '["Ayati 26—31: Nga''ötI 20:1—3","Yer 49:2"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 28, 'ba owuloi zi tosai sabölö, ba suwö mbanua andrö, ba ya atu''a ndra''ugö, fa böi ya''o zatu''a ba mbanua ba fa böi töigu nitötöi, na lafatunö.', '["Ayati 26—31: Nga''ötI 20:1—3","Yer 49:2"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 29, 'Ba i''owuloi khönia zabölö fefu Dawido, ba lasaŵa Raba, lasuwö, ba atu''a ira.', '["Ayati 26—31: Nga''ötI 20:1—3","Yer 49:2"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 30, 'Ba ihalö zaembu ba högö [nadu] Milikomo, 49 kilo [ana''a] wa''abua, si so mani-mani, sambua, sebua sibai böli. Ba i''anaembu Dawido, ba ebua sibai la''ohe misa, sahulu ira ba mbanua andrö.', '["Ayati 26—31: Nga''ötI 20:1—3","Yer 49:2"]', NULL),
  (3475018, 'OT', 'Samueli II', 12, 31, 'Ba la''ohe göi niha andrö, si so ba mbanua, ba ifataro sogaragazini eu ba samaku tanö ba solau eu ba samazökhi kara tembo. Ba si manö göi wolaunia ba mbanua Ndraono Gamoni bö''ö, fefu. Ba mangawuli ba Yeruzalema Dawido, awö zato fefu.', '["Ayati 26—31: Nga''ötI 20:1—3","Yer 49:2"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 1, 'Ba so nakhi Gabisalomi ono Dawido, ono alawe si sökhi si''ai bawa, Tamara döi. Ba tobali omasi Gamoni, ono Dawido Damara andrö.[1]', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 2, 'Ba tobali abu sibai dödö Gamoni, irege mofökhö ia, börö nakhinia Tamara andrö. Ono alawe Damara, ba lö isöndra lala Amoni, ba wa''orudu khönia.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 3, 'Ba so zi fahuwu khö Gamoni, Yonadabi döi, ono ga''a Dawido, Simea; ba no niha sonekhe sibai Yonadabi andrö.[2]', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 4, 'Ba imane da''ö khö Gamoni: Hana wa ariri ma''ökhö ndra''ugö, ono razo? Hadia, lö ö''ombakha''ö khögu? Ba imane khönia Amoni: Omasido Damara, akhi nakhigu Abisalomi.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 5, 'Ba imane khönia Yonadabi: Ae mörö, ö''osofökhö ndra''ugö, ba na so namau, ba wamaigi ya''ugö, ba ömane khönia: Ena''ö na möi ba da''e nakhigu Tamara, ba wame''e gögöe ma''ifu! Na i''asiwai gö ba zanehe ndra''o, na i''ila hörögu, ba u''a zoroi ba dangania.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 6, 'Ba möi mörö Gamoni i''osofökhö ia. Ba me so razo, ba wamaigi ya''ia, ba imane Amoni khö razo: Ena''ö na möi ba da''e nakhigu Tamara, ba wogore kue, dua görö, ba zanehe ndra''o, ena''ö u''a zoroi ba dangania!', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 7, 'Ba ifatenge Dawido, ba nomonia, khö Damara, imane khönia: Ae ba nomo ga''au Amoni ba halö gönia.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 8, 'Ba möi ba nomo ga''ania Amoni Damara, me mörö-mörö Gamoni. Ihalö gomböila roti, iferafera, ifazökhi, ba zanehe ia, ba igore kue andrö.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 9, 'Ba humede ia ba zangai halöŵö ba itou''ö tou föna Gamoni kue andrö. Ba lö edöna manga Gamoni. Imane sa: Dozi ndramöi baulu.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 10, 'Ba dozi ira, ba möi baulu. Ba imane Amoni khö Damara: Ohe si bakha sibai gö andrö, ba u''a ba dangau. Ba ihalö kue andrö Tamara, i''ohe khö ga''ania Amoni si bakha sibai.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 11, 'Ba me i''oro''ö khönia, ba ira''u ia, imane khönia: Förö ba ngaigu, akhi![3]', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 12, 'Ba imane khönia: Böi ga''a, böi höwö ndra''odo, tenga si manö wolau ba Ndraono Gizeraeli: böi fazökhi horö si manö![4]', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 13, 'Heza sa u''ohe wa''ailagu andrö? Ba tobali awö zebua horö ndra''ugö, ba Ndraono Gizeraeli, ena''ö: sökhi na öŵa''ö khö razo, lö zi lö ilulu ndra''o khöu!', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 14, 'Ba lö edöna ifondrondrongo linia, ilangögö manö, ihöwö, orudu ia khönia.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 15, 'Ba aefa da''ö, ba anuzu sibai dödö Gamoni ia; abölö sa''ae wa''anuzu dödönia khönia, moroi ba wa''omasinia ia mege. Ba imane khönia Amoni: Faoso, labu''ögö!', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 16, 'Ba imane khönia: Böi ga''a! Na öfofanö ndra''o, ba ebua horö da''ö, moroi ba nilaumö khögu mege! Ba lö ifondrondrongo khönia,', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 17, 'humede sa''ae ia khö nono matua andrö, ngoni-ngoninia, imane: Ohe tou baewali da''e khögu, ba lazi mbawandruhö furinia!', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 18, 'Ba baru si so ta''io mbarunia — si manö sa mbaru nono razo alawe, i''otarai föna sa''ae, götö wa ono alawe ira —. Ba me no i''ohe tou Damara baewali ngoni-ngoni Gamoni andrö ba me no ilazi mbawandruhö furinia, ba ilau nawu ba högönia,', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 19, 'Tamara, ba ire''a mbarunia andrö, si so ta''io, ba itufa tanga högönia, ba mofanö, mu''ira-ira.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 20, 'Ba imane khönia ga''ania Abisalomi: Hadia, no orudu khöu ga''au Amoni? Ba böi hede-hede, ya''ugö akhigu — no ga''au ia! Böi busi dödöu da''ö! Ba i''iagö yomo khö ga''ania Abisalomi Tamara, sabu tödö.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 21, 'Ba me irongo da''ö fefu Dawido, ba mofönu sibai ia, ba lö edöna ia ibusi dödö Gamoni, me no omasi ia Gamoni, me no si a''a nononia.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 22, 'Ba lö fahede Gabisalomi khö Gamoni, sambua li lö''ö, he si lö sökhi, ba he si sökhi; noa sa abao sibai dödö Gabisalomi khö Gamoni, me no ihöwö nakhinia Tamara andrö.', '["Faigi 3:2,3","SamI 16:9","MozIII 18:9","MozV 22:21"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 23, 'Ba mendrua fakhe aefa da''ö, ba samuza ma''ökhö, ba moguti bu mbiri-biri Gabisalomi, ba Mba''ali Hasora, ba nola mado Geferayi; ba ikaoni ba da''ö nono razo fefu Abisalomi.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 24, 'Ba möi khö razo göi Gabisalomi, imane: ö''ila, moguti bu mbiri-biri zawuyumö, ena''ö na möi göi razo, awö genoninia!', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 25, 'Ba imane razo khö Gabisalomi: Böi, onogu! Böi ahori möi ndra''aga, fa böi möiga noro dödöu! Ba iforege khönia, ba lö edöna möi razo, ifofanö ia.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475019, 'OT', 'Samueli II', 13, 26, 'Ba imane Abisalomi: Ba na lö möi''ö, ba hana na ga''agu Amoni zi möi awöma. Ba imane razo: Hana wa ya''ia zi möi awöu?', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 27, 'Ba me iforege wangandrö, ba ifatenge awönia Gamoni ba ono razo fefu. Ba ifodiwo ira Abisalomi, si mane na ibe''e gö niha razo.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 28, 'Ba ibe''e li ba zangai halöŵö khönia Abisalomi, imane: Na no mabu agu ma''ifu Gamoni, ba na umane khömi: Mi''ö''ötö Gamoni! Ba mibunu ia! Böi mi''abusi tödö: ya''odo sa zanguma''ö khömi — mi''abe''e''ö dödömi, ya sabölö ami![5]', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 29, 'Ba la''o''ö da''ö sangai halöŵö khö Gabisalomi, ba khö Gamoni, dali niŵa''ö Gabisalomi. Ba maoso nono razo fefu, möi ira yaŵa ba hulu kudo kalide khöra ba moloi ira.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 30, 'Ba me so ba lala na ira, ba no irongo duria da''ö Dawido, no lamane khönia: No ahori ibunu nono razo Abisalomi, samösa lö si tosai!', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 31, 'Ba maoso razo, isika nukhania, ba ifadölö tou ia ba danö; ba lasika göi nukhara enoninia fefu, si so ba ngainia.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 32, 'Ba humede Yonadabi andrö, ono ga''a Dawido Simea, imane: Böi faduhu dödöu, ya''ugö sokhö ya''o, wa no ahori labunu nono matua andrö, ono razo: ha Amoni zi mate, noa sa oroma wa''abao mbawa Gabisalomi, i''otarai luo, me ihöwö Damara Amoni.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 33, 'Ba böi yamuŵa''ö tödönia sokhö ya''o, razo, no ahori mate nono razo — ha sa Amoni zi mate.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 34, 'Ba moloi Gabisalomi. Ba me ifakhölö ia enoni andrö, sanaro, ba i''ila, ato niha si otarai moroi yaŵa ba hili, ba lala ba Horona''i. Ba so zanaro andrö, i''ombakha''ö khö razo, imane: No u''ila niha moroi yaŵa ba hili ba lala ba Horona''i.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 35, 'Ba imane Yonadabi khö razo: Hiza, so nono razo: itörö niŵa''ö zawuyumö.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 36, 'Ba me aefa sibai iŵa''ö da''ö, ba larugi sa''ae ono razo ba mege-ege. Ba mege-ege sibai göi razo ba enoninia andrö fefu.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 37, 'Ba lö mamalö-malö wa''abu dödö razo khö nononia andrö. Ba no moloi Gabisalomi, isaŵa Dalamai andrö, ono Gamihudi, razo Gesuri.[6]', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 38, 'Ba medölu fakhe ia ba da''ö.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475019, 'OT', 'Samueli II', 13, 39, 'Ba humulu dödö razo, ena''ö falukha ia khö Gabisalomi; noa sa irara dödönia ba wa''amate Gamoni.', '["MozIII 20:17","Faigi 3:3; 14:23"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 1, 'Ba me aboto ba dödö Yoabi, ono Zeruya, lö aefa dödö razo khö Gabisalomi,', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 2, 'ba ifatenge ba Dekoa Yoabi, ifakaoni''ö ndra alawe satua-tua ba da''ö, ba imane khönia: Osabu tödö ndra''ugö, nukha ba wange''esi onukha, ena''ö hulö zange''esi si mate ndra''ugö, si no arara.', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 3, 'Ba ae yomo khö razo, ba ömane khönia: — Ba ibe''e li khönia Yoabi, hadia niŵa''önia.', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 4, 'Ba möi yomo khö razo ndra alawe andrö, banua Dekoa, ifalögu tou ia ba zalo, mangalulu, ba imane: Tolodo, ya''ugö razo, tolodo!', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 5, 'Ba imane khönia razo: Hadia zabu dödöu? Ba imane: Alai ndra''o! lakha mbanua ndra''odo, fo''omogu, ba no mate.', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 6, 'Ba dombua mege nono matua khö zawuyumö, ba fasoso ira ba nowi, ba lö sanenaŵa, ba ibözi dalifusönia si samösa, ibunu.', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 7, 'Ba maoso udu zawuyumö dalifusö fefu, lamane: Be''e baero zange''e andrö, samunu talifusönia, ena''ö mabunu ia, balö noso dalifusönia andrö, nibununia, ena''ö ma''etu''ö nga''ötö! Tobali labunu mbo andrö, si tosai na khögu, ena''ö lö lasaigö khö ngambatögu döi ba he nga''ötö, ba guli danö.[1]', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 8, 'Ba imane razo ba ndra alawe andrö: Fuli''ö ba khömi, da''ube''e li, ba huhuomö andrö.', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 9, 'Ba imane ira alawe andrö, banua Dekoa, khö razo: Ya ba hulugu so horö andrö, ya''ugö sokhö ya''o, razo, ba ba hulu zi samba omo ndra amagu, ba ya si lö horö razo, awö dadaomania andrö!', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 10, 'Ba imane razo: Ohe khögu zanguma''ö khöu da''ö no mege — ba lö''ö sa''ae ibabaya ndra''ugö ube''e.', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 11, 'Ba imane: Ena''ö na itörö tödö razo Lowalanginia Yehowa, fa böi sa''ae itohugö wamakiko solau balö andrö, ba fa böi ibunu nonogu andrö! Ba imane razo: Faya wa no sauri Yehowa na sara mbu nonou atoru ba danö![2]', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 12, 'Ba imane ira alawe andrö: Ena''ö na tola iŵa''ö na zambua li khö zokhö ya''o razo, sawuyumö andre! Ba imane: ŵa''ö!', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 13, 'Ba imane ira alawe andrö: Hana wa si manö dödöu ba mbanua Lowalangi andrö — ba wangetu''ö razo da''ö, ba hukunia i''etu''ö, wa lö ifakaoni''ö mangawuli nitibo''önia andrö razo?', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 14, 'Si mate sa ita, ba no timba nidanö ita, niduwagö ba danö, si tebai lafuli lahalö ba lö''ö sa i''etu''ö Lowalangi noso zangera-ngera, he iwisa wangai mangawuli khönia si no mutibo''ö.[3]', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 15, 'Ba hiza, fe''amöigu ba da''e, ba wanguma''ö da''ö khö zokhö ya''o, razo, ba me no lafeta''u ndra''o sato; ba no imane dödönia sawuyumö andre: Ba da''uŵa''ö khö razo, ma atö i''o''ö razo zomasi zawuyunia.', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 16, 'Ifondrondrongo sa ligu razo, ba wangefa''ö sawuyunia ba danga niha andrö, sangalui fangohori ya''aga onogu andrö, ba mbanua Lowalangi andrö.', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 17, 'Andrö wa no imane dödönia sawuyumö andre: Fondrara dödögu dania daroma li zokhö ya''o, razo, me no timba mala''ika Lowalangi zokhö ya''o, razo, faoma ifondrondrongo, he si sökhi, ba he si lö sökhi — ba yamutolo''ö Lowalangiu Yehowa![4]', '["MozV 19:11—13","SamI 14:45; RazI 1:52","Hez 18:23","Faigi 19:28"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 18, 'Ba humede razo, imane ba ndra alawe andrö: Ba böi bini''ö khögu hadia ia nisofugu khöu! Ba imane ira alawe andrö: Yamuhede manö zokhö ya''o, razo.', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 19, 'Ba imane Dawido: Hadia, tenga Yoabi zamarou ya''ugö, ba da''ö fefu? Ba imane ira alawe andrö: Ba wa''aduhu wa''aurimö, ya''ugö sokhö ya''o, razo, ya''ia. Tebai tahole''ö ita ba niŵa''ö zokhö ya''o, razo, fefu, he ba gambölö, ba he ba gabera: ya''ia sa, enonimö Yoabi zanguma''ö khögu, ya''ia zamowawa sawuyumö, ba niŵa''ö andrö, fefu.', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 20, 'Ba wamini''ö si duhu, andrö wa no imanö enoniu Yoabi: ba no timba mala''ika Lowalangi zokhö ya''o, ba wa''atua-tua andrö, no ahori isöndra hadia ia, ba guli danö.[5]', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 21, 'Ba imane razo khö Yoabi: Ba hiza, ba u''o''ö da''ö: ba ae''e sa''ae ba halö mangawuli nono matua andrö, Abisalomi!', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 22, 'Ba ifalögu tou ia ba zalo Yoabi, mangalulu, ba ifahowu''ö razo. Ba imane Yoabi: Ma''ökhö aboto ba dödö zawuyumö, wa no sebua tödö khögu zokhö ya''o, razo, me no ifondrondrongo razo wangandrö zawuyunia!', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 23, 'Ba maoso Yoabi, möi ia ba Gesuri ba i''ohe mangawuli ba Yeruzalema Gabisalomi.[6]', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 24, 'Ba imane razo: Hana na ifuli ia ba khöra, ba böi yamu''oroma''ö ia khögu! Ba isaŵa nomonia Abisalomi, ba lö i''oroma''ö ia khö razo.', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 25, 'Ba ba Ndraono Gizeraeli fefu, ba lö famaedo wa''asökhi mboto Gabisalomi, ba lö nisuno si mane ya''ia: i''otarai narö kahe, numalö ba galizuzu, ba lö hadia ia zinegu.', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 26, 'Ba na ifaguti''ö mbunia — ero röfi ifaguti''ö; me abölö abua khönia, andrö ifaguti''ö — ba 200 zekeli (rufia) wa''abuania, ba zaga razo.', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 27, 'Ba tölu zi tumbu khö Gabisalomi ono matua, ba sambua nono alawe, Tamara döi; ba ono alawe si sökhi bawa da''ö.[7]', '["Ayati 17","Faigi 13:37","Faigi 13:1"]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 28, 'Ba mendrua fakhe wa''ara i''iagö Yeruzalema Abisalomi, lö i''oroma''ö ia khö razo.', '[]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 29, 'Ba aefa da''ö, ba ifatenge khö Yoabi Abisalomi, ena''ö ifalukha''ö ia khö razo; ba lö edöna möi khönia Yoabi. Ba ifuli ifatenge, ba te khönia möi ia.', '[]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 30, 'Ba imane ba zangai halöŵö khönia: Hiza, so nowi Yoabi ba ngai khögu ba so gandru: mi''ae mitunu! Ba latunu zinanö andrö sangai halöŵö khö Gabisalomi.', '[]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 31, 'Ba maoso Yoabi, möi ia yomo khö Gabisalomi, imane khönia: Hana wa no latunu zinanö khögu sangai halöŵö andrö khöu?', '[]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 32, 'Ba imane Abisalomi khö Yoabi: Ba no ufatenge khöu, ba no umane: Ae khögu, ena''ö ufatenge ndra''ugö khö razo, ba wanofu khönia: Hadia wa no ufuli ndra''o moroi ba Gesuri? Omasido lö tebulödo ba da''ö — ba iya''e, ba möido sa mangoroma''ö ya''odo khö razo: na so horögu, ba yamubunu ndra''o!', '[]', NULL),
  (3475020, 'OT', 'Samueli II', 14, 33, 'Ba möi khö razo Yoabi, i''ombakha''ö khönia. Ba ifahede''ö khö Gabisalomi. Ba i''ondrasi razo Abisalomi, ifalögu tou ia ba zalo, föna razo; ba fa''ago bawa razo khö Gabisalomi.', '[]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 1, 'Ba aefa da''ö, ba i''öli khönia gureta, awö kudo, Abisalomi, ba lima wulu ihalö khönia niha si fao-fao khönia [fazurinia][1]', '["RazI 1:5"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 2, 'Ba na mahemolu mbanua, ba ba zinga lala fönaföna mbawa göli i''iagö Abisalomi, ba na so zi so huhuo, ha niha, ni''ohenia khö razo ena''ö, ba wamatunö, ba humede khönia Gabisalomi, imane khönia: Ha banua ndra''ugö? Ba na imane: Ma''uwu Gizeraeli zawuyumö andre!', '["RazI 1:5"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 3, 'Ba imane Abisalomi: Si sökhi huhuomö ba si duhu, ba lö''ö sa khö razo samondrongo khöu.', '["RazI 1:5"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 4, 'Ba imane na Abisalomi: Alai ndra''o! Ena''ö na ya''o nifataro sanguhuku ba danö, ba ena''ö khögu möi na so zi so famadöni, ba ma huhuo, ba ena''ö ube''e ba lala huhuonia!', '["RazI 1:5"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 5, 'Ba na so zangondrasi ya''ia, ba wangalulu khönia, ba ira''u danga, fa''ago bawa ia khönia.', '["RazI 1:5"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 6, 'Si manö-manö Gabisalomi ba Ndraono Gizeraeli fefu, sangandrö famatunö huhuo khö razo ba tobali mangai tödö Ndraono Gizeraeli ia.', '["RazI 1:5"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 7, 'Ba mendröfa fakhe, ba imane Abisalomi khö razo: Hadia na möido ba Heberona, ba wanörö amabu''ula ligu andrö, nifabu''ugu khö Yehowa?', '["MozI 28:20; Faigi 13:38","SamI 20:42","Faigi 23:34"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 8, 'No imane wamabu''u khö Yehowa sawuyumö, me sodo ba Gesuri, ba danö Ndrawa Garamo: Na si ndruhu i''ohe mangawuli ndra''o ba Yeruzalema Yehowa, ba ufosumange Yehowa.[2]', '["MozI 28:20; Faigi 13:38","SamI 20:42","Faigi 23:34"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 9, 'Ba imane khönia razo: Ba ae''e, böi busi dödöu! Ba mofanö sa''ae ia ba Heberona.[3]', '["MozI 28:20; Faigi 13:38","SamI 20:42","Faigi 23:34"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 10, 'Ba no ifatenge zinenge Abisalomi, ba mado Ndraono Gizeraeli fefu, no imane: Na mirongo li dorofe, ba mimane: No tobali razo Gabisalomi, ba Heberona!', '["MozI 28:20; Faigi 13:38","SamI 20:42","Faigi 23:34"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 11, 'Ba 200 zi fao khö Gabisalomi niha, moroi ba Yeruzalema, niŵa''önia; möi manö, lö famaudu dödö, lö nirongora hadia ia.', '["MozI 28:20; Faigi 13:38","SamI 20:42","Faigi 23:34"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 12, 'Ba ifatenge göi Abisalomi, barö wame''enia sumange andrö, ifakaoni''ö Gahitofeli andrö, banua Gilo, anofula Dawido, ba mbanuara Gilo. Ba itugu abölö wolaŵa andrö, tedou-dou wa''ato nawö Gabisalomi, niha sato.[4]', '["MozI 28:20; Faigi 13:38","SamI 20:42","Faigi 23:34"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 13, 'Ba so zi möi khö Dawido, sangombakha khönia, lamane: Dozi la''omasi''ö Gabisalomi Iraono Gizeraeli!', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 14, 'Ba imane Dawido ba genoninia andrö fefu, si so khönia ba da''ö, ba Yeruzalema: Talabu, moloi ita! lö''ö sa fangorifida, ibe''e Abisalomi: mita''i-ta''i, mofanö ita, fa böi ihawui manö ita, lö mudöna-döna, ba fa böi ifatörö khöda wamakiko, wangö''ötö manö tou banuada andre![5]', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 15, 'Ba lamane enoni razo andrö khönia: Balazi manö dödö zokhö ya''aga, razo — noa sa sawuyumö ndra''aga!', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 16, 'Ba mofanö razo ba latete ia si samba omo ya''ira; ba dafulu iröi furi dongania ba döi razo, awö nomo.', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 17, 'Ba mofanö razo, ba latete ia enoninia andrö fefu. Ba ba mbalö mbanua, ba labadugö ira,', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 18, 'labe''e sowaö-waö zato fefu, awö wazuri andrö, fefu; ba mowaö-waö göi nawö Gita''i andrö, banua Gata, fefu, 600 ira, ni''ohenia moroi ba Gata.[6]', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 19, 'Ba imane razo khö Gita''i andrö, banua Gata: Hana wa fao göi ndra''ugö khöma? Fuli''ö ba iagö awö razo: niha bö''ö sa atö ndra''ugö, ba noa na nitibo''ö mbanuami.[7]', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 20, 'Menewi so ndra''ugö, ba hadia, ba ma''ökhö uŵa''ö khöu wefao khöma, ba lala elungua, na mofanö ndra''o, sate urugi? Fuli''ö ba ohe mbanuami andrö; falukha''ö dania wa''ebua dödö ba fa lö faröi khö Yehowa!', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 21, 'Ba imane Ita''i khö razo: Ba wa''aduhu wa''auri Yehowa ba ba wa''aduhu wa''auri zokhö ya''o, razo: ba zi so zokhö ya''o, razo — he ba wa''amate ba he ba wa''auri — ba da''ö göi so genonimö andre!', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 22, 'Ba imane Dawido khö Gita''i: Ba lau, ba owaö-waö! Ba itörö Ita''i andrö, banua Gata, ba awönia fefu, ba iraono fefu, si fao khönia.', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 23, 'Ba mege-ege sibai niha ba danö, fefu, me latörö sato. Ba ba mbewe Gendrona so razo, me latörö ia sato fefu, ba lala ba zai andrö, ba danö si mate.[8]', '["Sin 3:1","Faigi 8:18","Faigi 18:2","Yoh 18:1"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 24, 'Ba so göi ba da''ö ndra Sadoki Abiataro ba ono Lewi fefu, sangosa''ö tawöla zura goroisa andrö, khö Lowalangi; ba latou''ö tou dawöla Lowalangi, irege no ahori latörö sato, moroi yomo ba mbanua.', '["Faigi 10:12; SamI 3:18","RazI 1:42"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 25, 'Ba imane razo khö Zadoki: Fuli miyomo dawöla Lowalangi: na ahakhö dödö Yehowa ndra''odo, ba i''ohe mangawuli ndra''o, ba ifa''ila''ö ia khögu, fabaya nahiania andrö.', '["Faigi 10:12; SamI 3:18","RazI 1:42"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 26, 'Ba na iŵa''ö tödönia: Lö omasido ndra''ugö — ba ya''e ndra''odo, yamulau khögu nilau dödönia.[9]', '["Faigi 10:12; SamI 3:18","RazI 1:42"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 27, 'Ba imane razo khö gere sebua andrö, Sadoki: Fuli''ö miyomo ba mbanua, böi busi dödöu, ba ya fao khömi nonou, Ahimasi, ba Yonata, ono Gabiataro — onomi andrö, si dombua.[10]', '["Faigi 10:12; SamI 3:18","RazI 1:42"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 28, 'Hiza, ubase''ö ba zinga götöna andrö, ba danö si mate, irege mifatenge, irege urongo he wisa.', '["Faigi 10:12; SamI 3:18","RazI 1:42"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 29, 'Ba la''ohe mangawuli ba Yeruzalema dawöla Lowalangi ira Sadoki Abiataro, ba yomo la''iagö.', '["Faigi 10:12; SamI 3:18","RazI 1:42"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 30, 'Ba isösö hili wanikha Dawido, mege-ege ia ba wowaö-waö ba no ibalugö högönia. Ba lö badagahenia. Ba noa göi labalugö högöra sato fefu, awönia andrö, ba fadoro mege-ege ira ba wanösö hili.', '["Faigi 10:12; SamI 3:18","RazI 1:42"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 31, 'Ba me la''ombakha''ö khö Dawido: Ahitofeli andrö, ba no awö zolaŵa andrö göi, awö Gabisalomi! ba imane Dawido: He Yehowa! Bali''ö fa''owöhö mowa dödö Gahitofeli andrö!', '["Faigi 10:12; SamI 3:18","RazI 1:42"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 32, 'Ba me no irugi Dawido zuzu hili andrö, ba nifosumasumange Lowalangi, ba hiza, ba i''ondrasi ia si fahuwu khönia, Huza''i, ma''uwu Garakhi, no isika mbarunia ba no ilau danö ba högönia.', '["Faz. 17:7","Faigi 17:15—17","Nga''ötI 27:33"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 33, 'Ba imane khönia Dawido: Na fao''ö khögu, ba tobali noro dödögu ndra''ugö;', '["Faz. 17:7","Faigi 17:15—17","Nga''ötI 27:33"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 34, 'ba na öfuli''ö miyomo ba na ömane khö Gabisalomi: "Omasido, na enoniu ndra''odo, ya''ugö razo; mege, ba enoni namau ndra''o, ba iya''e, ba omasido möido enonimö", ba öbali''ö si lö boto gera-era Gahitofeli.[11]', '["Faz. 17:7","Faigi 17:15—17","Nga''ötI 27:33"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 35, 'So sa atö göi awöu ba da''ö, gere andrö, Sadoki ba Abiataro: ba hadia ia nirongou ba gödo razo, ba hana na ö''ombakha''ö khö ndra Sadoki Abiataro ere.', '["Faz. 17:7","Faigi 17:15—17","Nga''ötI 27:33"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 36, 'So khöra ba da''ö nonora andrö si dombua, Ahimasi, ono Zadoki ba Yonata, ono Gabiataro, hana na da''ö nibe''e sama''ema khögu hadia nirongomi.[12]', '["Faz. 17:7","Faigi 17:15—17","Nga''ötI 27:33"]', NULL),
  (3475021, 'OT', 'Samueli II', 15, 37, 'Ba möi miyomo Huza''i andrö, si fahuwu khö Dawido; ba Abisalomi, ba möi göi ba Yeruzalema.[13]', '["Faz. 17:7","Faigi 17:15—17","Nga''ötI 27:33"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 1, 'Ba me no italu''i ma''ifu zuzu hili Dawido, ba hiza Ziba andrö, sawuyu Meriba''ali, samaondragö ya''ia, dua geu khönia kalide, si no mufosela, sonoro balazo, 200 roti, ba 100 nga''örö kue nifaruka bua nagu ba 100 nga''örö nifaruka bua geu bö''ö ba samba nahia nagu.', '["Faigi 19:27"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 2, 'Ba imane razo khö Ziba: Hadia guna da''ö? Ba imane Siba: Kalide andre, ba ena''ö na la''okudo soroiyomo razo, ba roti andre ba bua geu, ba ö genoniu, ba agu andre, ba ena''ö na labadu serege tödö, ba danö si mate.', '["Faigi 19:27"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 3, 'Ba imane razo: Ba heza so nono zokhö ya''ugö mege? Ba imane Siba khö razo: No toröi ba Yeruzalema, me no imane dödönia: Lafuli sa''ae khögu iya''e gamatöröŵa namagu ma''uwu Gizeraeli![1]', '["Faigi 19:27"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 4, 'Ba imane razo khö Ziba: Ba khöu sa''ae gokhöta Meriba''ali fefu! Ba imane Siba: Mangalulu ndra''o khöu! Ya''ebua dödöu khögu, ya''ugö sokhö ya''o, razo!', '["Faigi 19:27"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 5, 'Ba me no irugi Mbahuri razo Dawido, ba hiza moroi yomo niha, iwa Zaulo, Sime''i döi, ono Gera; mangelingelifi moroi yomo,[2]', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 6, 'ba itebu kara Dawido, ba enoni razo fefu, he ŵa''ae no lafatambai ia niha sato ba saradadu andrö fefu.', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 7, 'Mu''ao Zime''i, imane wangelingelifi: Labu''ögö, labu''ögö, si tebai abuso do, si si lö yaŵa!', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 8, 'No ilau khöu mbalö ndro zi samba omo ndra Saulo Yehowa, Saulo si no möi''ö fangali razo, ba fa''arazomö andrö, ba no ibe''e khö nonou Abisalomi Yehowa, ba hiza, ba itörö''ö sa''ae famakao, me no si tebai abuso do ndra''ugö!', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 9, 'Ba imane Abiza''i andrö, ono Zeruya, khö razo: Hana wa tola i''elifi zokhö ya''o, razo, asu si mate andrö? Damöido mangetu''ö baginia![3]', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 10, 'Ba imane razo: Hana ami khögu, ya''ami iraono Zeruya andrö! Na mangelifi ia, ba na no Yehowa zanguma''ö khönia: Ae elifi Dawido! ba ha niha zi tola manofu: Hana wa ölau zi manö?[4]', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 11, 'Ba imane Dawido khö Gabiza''i ba ba genoninia fefu: Na i''alui wamunu ya''odo onogu andrö, nga''ötögu, ba tenga mendrua manö mado Mbeniyami andrö? Böi mitenaŵa ia; hana na mangelifi ia, noa sa Yehowa zanguma''ö khönia.', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 12, 'Ma atö inehegö wamakaogu andre Yehowa, ba ma ifatörö khögu wa''ohahau dödö, fangali wangelifi andrö, si göna ndra''o ma''ökhö.', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 13, 'Ba mofanö Dawido ba awönia fao, ba fao göi Zime''i, itörö gahe hili, ba mangelingelifi ba wofanö andrö, ba itebu kara Dawido ba ihawui tanö.', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 14, 'Ba irugi ndraso Yoridano Dawido, awö zato andrö fefu, si fao khönia, no erege dödö; ba molombase ia ba da''ö.', '["RazI 2:8; MozII 22:27","SamI 26:8","Faigi 19:23"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 15, 'Ba no irugi Yeruzalema Abisalomi, awö ndra matua Ndraono Gizeraeli fefu; ba awönia göi Gahitofeli.', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 16, 'Ba me irugi Gabisalomi si fahuwu khö Dawido no mege, Huza''i, ma''uwu Garakhi, ba imane khö Gabisalomi: Ya''ahowu razo! Ya''ahowu razo![5]', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475022, 'OT', 'Samueli II', 16, 17, 'Ba imane Abisalomi khö Huza''i: Hadia da''ö, fa''omasiu zi fahuwu khöu? Hana wa lö möi''ö awö zi fahuwu khöu andrö?', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 18, 'Ba imane Huza''i khö Gabisalomi: Lö''ö, khö nituyu Yehowa ba soi andre, Iraono Gizeraeli fefu, ndra''odo, khönia sodo.', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 19, 'Ba sambalö na: Ha khö möido enoni? Hadia, tenga khö nononia? Si mane me möidomöido enoni namau mege, si manö we''amöigu enoniu dania.', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 20, 'Ba imane Abisalomi khö Gahitofeli: Mifobawa lala khöda, he tawisa!', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 21, 'Ba imane Ahitofeli khö Gabisalomi: Ae förö ba ngai ndronga namau, donga ba döi andrö, niröinia furi, awö nomo, ba larongo mötö Iraono Gizeraeli fefu, wa no aböu döimö khö namau öbe''e, ba abe''e dödö zolemba khöu, fefu.[6]', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 22, 'Ba lalau nose khö Gabisalomi, yaŵa be dete nomo, ba möi mörö ba ngai ndronga namania Gabisalomi, donga ba döi andrö, ba zanehe Ndraono Gizeraeli fefu.[7]', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL),
  (3475022, 'OT', 'Samueli II', 16, 23, 'Hadia niŵa''ö Gahitofeli andrö, me luo da''ö, ba no hulö nisofu khö Lowalangi — si manö wa''afaduhu dödö ndra Dawido Abisalomi khö Gahitofeli.', '["Faigi 15:37; SamI 10:24","Faigi 15:16","Faigi 12:11; MozIII 18:8"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 1, 'Ba imane Ahitofeli khö Gabisalomi: Da''utuyu khögu niha, 12.000, ba möido molohi Dawido, ba zi bongi,[1]', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 2, 'ba ulau khönia, fatua erege na dödö ba fatua lö lala dödönia na: ba tokea ia ube''e, ba moloi zato fefu, awönia andrö ba u''ila ubunu razo, na ha ya''ia.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 3, 'Ba u''ohe mangawuli khöu zato fefu, timba wangawuli nono nihalö khö zangai ya''ia: ha sa atö samösa ni''aluimö famunu; ba lö hadia ia dania ba niha sato fefu.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 4, 'Ba si sökhi da''ö wamaigi Gabisalomi, ba he satua Ndraono Gizeraeli fefu.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 5, 'Ba imane Abisalomi: Mihede göi khö Huza''i andrö, ma''uwu Garakhi, ena''ö tarongo hadia niŵa''önia.[2]', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 6, 'Ba me i''ondrasi Gabisalomi Huza''i, ba i''ombakha''ö khönia Abisalomi niŵa''ö Gahitofeli, ba isofu khönia, imane: Hadia, ta''o''ö niŵa''önia andrö? Ba na lö''ö, ba ŵa''ö niŵa''öu.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 7, 'Ba imane Huza''i khö Gabisalomi: Si samuza andre, ba lö enahöi niŵa''ö Gahitofeli.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 8, 'Ba imane na Huza''i: No ö''ila namau ba awönia andrö, wa no sabölö ira ba si ono wönutö, timba zi alawe mberua ba ndru''u, nihalö ono; ba amau ba no bohalima, si lö mörö ba zi bongi, fabaya awönia andrö.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 9, 'Hiza, tabe''e no ibini''ö ia iada''e ba mbawa danö, ba ma heza — ba na so zi mate ösa, ba mböröta ba na larongo da''ö niha sato, ba lamane dania: No te''ala nawö Gabisalomi andrö!', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 10, 'Ba tobali he sabölö, sabe''e tödö, si mane singo, ba atalö manö dödö, me no la''ila Iraono Gizeraeli fefu, wa no bohalima namau, awö wa no sabölö nawönia andrö.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 11, 'Ba tödögu, ba si sökhinia na la''owuloi khöu Ndraono Gizeraeli fefu, i''otarai Dano, numalö ba Mbereseba, timba ngawua nene ba mbewe nasi wa''oya, ba si möi göi ndra''ugö, awöra.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 12, 'Ba na takhamö ia heza, ba nibase''önia ya''ita, ba tahawui ia, timba namo, na aekhu ba danö, ba samösa böi ya tosai, he ya''ia, ba he awönia andrö fefu!', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 13, 'Ba na miyomo ba mbanua heza iwuwu ia, ba ndramu''amöhögö zinali ba mbanua andrö Iraono Gizeraeli fefu, ba tadöni ba ndraso, irege sambua lö falukha kara sa''ae ba da''ö.', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 14, 'Ba imane Abisalomi ba Iraono Gizeraeli fefu: Sökhi niŵa''ö Huza''i, ma''uwu Garakhi, moroi ba niŵa''ö Gahitofeli! — Noa sa i''ohe ba lala Yehowa, ena''ö tobali si lö boto zenahöi andrö, niŵa''ö Gahitofeli; ba ena''ö ifatörö wamakiko khö Gabisalomi Yehowa.[3]', '["Sin 71:11","Faigi 16:16","Faigi 15:31,34"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 15, 'Ba i''ombakha''ö Huza''i khö ndra ere, Sadoki ba Abiataro, hadia niŵa''ö Gahitofeli khö Gabisalomi ba ba zatua Ndraono Gizeraeli ba hadia niŵa''önia göi, ba imane khöra:', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 16, 'Ba mita''i-ta''i, mifatenge khö Dawido, mimane khönia: Böi förö ba zinga götöna andrö, ba danö si mate; ö''ötö sa''ae ena''ö lö mate razo, fabaya sato fefu, awönia andrö.', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 17, 'Ba no ba zinga gumbu Rogeli soso ndra Yonata Ahimasi, ba itari möi zawuyu ono alawe, ba wangombakha khöra hadia nirongo, ba möi-möi dania ira, ba wama''ema khö razo Dawido, lö''ö sa tola la''oroma''ö ira, lö tola möi miyomo ba mbanua.[4]', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 18, 'Ba samuza ma''ökhö, ba so zangila ya''ira, ono matua, ba i''ombakha''ö khö Gabisalomi. Ba lagösö moloi si darua andrö, larugi nomo mbanua Mbahuri, si so ba''a ba ngai nomo; ba möi ira bakha ba mba''a andrö,', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 19, 'ba ihalö gambala ira alawe niha andrö, ibologö söwusöwu mbawa mba''a ba ilau yaŵa mböra, tobali lö hadia ia zoroma.', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 20, 'Ba me larugi yomo ndra alawe andrö sinenge Gabisalomi, me lasofu: Heza so ndra Ahimasi Yonata? ba imane khöra ira alawe andrö: No la''ötö mbombo andrö. Ba la''alui, ba me lö lasöndra, ba lafuli ira ba Yeruzalema.', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 21, 'Ba me no mofanö ira, ba lafuli ira yaŵa ono matua no mege, moroi ba mba''a ba mofanö, larugi Dawido, ba la''ombakha''ö khönia hadia niŵa''ö. Lamane khönia: Milabu, migösö mi''ötö Yoridano; da''ö sa niŵa''ö Gahitofeli, nilau khömi!', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 22, 'Ba maoso Dawido ba sato fefu, awönia andrö, la''ötö Yoridano. Ba me moluo, ba samösa lö si tosai; no ahori la''ötö.', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 23, 'Ba me i''ila Ahitofeli, lö mu''o''ö niŵa''önia, ba ifosela galidenia ba mofanö ia, isaŵa ba khöra, mbanuara; ba i''oroi''ö ni''oroi''önia, ba ihie mbaginia. Ba me no mate ia, ba lako''o ia ba lewatö namania.[5]', '["RazI 1:9","Mat 27:5"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 24, 'Ba no irugi Mahana''i Dawido, me i''ötö Yoridano Abisalomi, awö Ndraono Gizeraeli fefu.', '["Faigi 19:14","Faigi 9:4; RazI 2:7","Faigi 16:2"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 25, 'Ba fangali Yoabi, ba Amasa ibe''e solohe sabölö Abisalomi. Ba Amasa andrö, ba ono niha sotöi Yitera, ma''uwu Zimaeli, si no mohorö khö Abigala, ono Giza''i, talifusö Zeruya andrö, ina Yoabi.[6]', '["Faigi 19:14","Faigi 9:4; RazI 2:7","Faigi 16:2"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 26, 'Ba ba danö Gileadi tebato Ndraono Gizeraeli ba Abisalomi.', '["Faigi 19:14","Faigi 9:4; RazI 2:7","Faigi 16:2"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 27, 'Ba me irugi Mahana''i Dawido, ba no la''ohe ba da''ö zoguna ira Sobi, ono Nahasi, banua razo ba Ndraono Gamoni, ba Makhiro, ono Gamieli, banua Lodebara ba Barasilai, banua Gileadi, banua Rogeli,[7]', '["Faigi 19:14","Faigi 9:4; RazI 2:7","Faigi 16:2"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 28, 'kaso ba ambala ba balanga ba bowoa tanö ba gandru ba rigi ba hamo ba böra nifakoe ba harita safusi ba harita magoyo,', '["Faigi 19:14","Faigi 9:4; RazI 2:7","Faigi 16:2"]', NULL),
  (3475023, 'OT', 'Samueli II', 17, 29, 'ba ŵe ŵani ba susu ba biri-biri ba kezu zusu zaŵi, ba labe''e ö Dawido ba ö nawönia sato; no lamane dödöra: no olofo ira ba erege dödöra ba owökhi dödöra, ba danö si mate.[8]', '["Faigi 19:14","Faigi 9:4; RazI 2:7","Faigi 16:2"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 1, 'Ba i''ofaya zabölö, awönia andrö, Dawido ba ifataro zolohe ya''ira, ba zi hönö-hönö ba ba zi otu''otu.', '["Faigi 15:19","Ayati 12"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 2, 'Ba ifotölu bawa ira, sambawa barö mbawa Yoabi ba sambawa barö mbawa nakhi Yoabi, Abiza''i andrö, ono Zeruya, ba si sambawa, ba barö mbawa Gita''i andrö, banua Gata. Ba imane khöra Dawido: Fao göi ndra''o khömi.[1]', '["Faigi 15:19","Ayati 12"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 3, 'Ba lamane: Lö tola fao ndra''ugö! Na moloi ena''ö ndra''aga, ba si lö ba dödö zato, ba he matonga mate ndra''aga, ba si lö ba dödö, ba ya''ugö, ba no timba zi 10.000, awöma. Ba sökhi göi iya''e, na moroi yomo ba mbanua öfaigi wanolo ya''aga.', '["Faigi 15:19","Ayati 12"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 4, 'Ba imane khöra razo: Hadia zomasi ami, ba u''o''ö. Ba i''iagö zinga mbawa göli, me latörö sato, hönö-hönö ba otu''otu.', '["Faigi 15:19","Ayati 12"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 5, 'Ba ibe''e li razo khö ndra Yoabi Abiza''i Ita''i, imane: Mihaogö khö nono matua andrö, Abisalomi! Ba larongo sato fefu, me ibe''e li ba zolohe ya''ira fefu razo, ba khö Gabisalomi.[2]', '["Faigi 15:19","Ayati 12"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 6, 'Ba möi ira, ba wamaondragö Iraono Gizeraeli. Ba ba gatua mado Geferayi, ba molau ira.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 7, 'Ba da''ö latimba Ndraono Gizeraeli sabölö andrö khö Dawido, tobali abölö sibai te''ala ira me luo da''ö, 20.000 zi mate.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 8, 'Ba no ebolo danö, si fazöndrazöndra ira ba da''ö, ba ato zi mate ba gatua andrö, moroi ba zi mate ba mbawa zi''öli, me luo da''ö.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 9, 'Ba fakhamö khö Gabisalomi genoni Dawido. Si fakudo ba kudo kalide Gabisalomi, ba itörö zi fadege sibai manawa kudonia, ba tokhai ba ndraha manawa högönia ba tobali manaŵanaŵa ia ba dalu mbanua, ba moloi kudonia barönia.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 10, 'Ba so zangila, ba i''ombakha''ö khö Yoabi, imane: No u''ila mege Gabisalomi, no manaŵanaŵa ba ndraha manawa.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 11, 'Ba imane Yoabi ba niha andrö, sangombakha khönia: Ba na no ö''ila ia, ba hana wa lö adölö öbözi dalu? Ba ya''o ena''ö zame''e luou, fulu rufia ba sara mböbö talu.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 12, 'Ba imane niha andrö khö Yoabi: Ba he hönö rufia la''erai ba dangagu, ba lö''ö sa ubabaya nono razo andrö: tenga no marongo, me ibe''e li khömi Abiza''i Ita''i razo, me imane: Mifaigi khögu nono matua andrö, Abisalomi![3]', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 13, 'Ba na no ulimo ia mena''ö — ma''ifu sa atö lö''ö, si tobini khö razo —, ba öböda sa atö ndra''ugö ena''ö.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 14, 'Ba imane Yoabi: Lö''ö manö tola arörödo khöu! ba tölu rozi ituyu toho, ba itaru''ö ba dödö Gabisalomi. Ba me lö saetu nosonia na ba ndraha manawa andrö,', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 15, 'ba dafulu zangondrasi, ono matua, solohe fangöna khö Yoabi, ba lafalua labunu Gabisalomi.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 16, 'Ba ifalau''ö dorofe Yoabi; ba labato wolohi Iraono Gizeraeli sabölö andrö, me itenaŵa ira Yoabi.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 17, 'Ba lahalö Gabisalomi, ba latibo''ö ba gohokoho danö sebua, ba gatua, ba oya sibai lafa''anö kara ba detenia. Ba Iraono Gizeraeli, ba noa sa''ae moloi, no isaŵa khöra zamösana.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 18, 'Ba no ihalö harefa ba ndraso khö razo Abisalomi, me auri ia na, ba no itaru''ö khönia, me no imane dödönia: Lö onogu, ba fa böi mate döigu! ba töinia, ba no ibe''e töi harefa andrö. Andrö wa harefa Gabisalomi döinia, irugi ma''ökhö andre.', '["Ayati 5"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 19, 'Ba imane Ahimasi, ono Zadoki: Da fagohido, ba wangombakha khö razo, wa no itolo ia Yehowa ba zi fa''udu khönia andrö, wa no i''ohe ba zatulö.[4]', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 20, 'Ba imane khönia Yoabi: Lö göna sangombakha ndra''ugö, ma''ökhö; na so zui dania, ba hana na ya''ugö zangombakha: ma''ökhö andre, ba lö tola ya''ugö zanuriaigö, me no ono razo zi mate.', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 21, 'Ba imane Yoabi khö Khusi: Ae ombakha''ö khö razo ni''ila höröu! Ba mangalulu Khusi khö Yoabi ba mofanö, fagohi.', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 22, 'Ba ifuli humede khö Yoabi Gahimasi, imane: Gofu he wisa dania, da''u''o''ö zui Khusi andrö, fagohido! Ba imane Yoabi: Hadia guna na moi''ö, onogu? lö''ö sa atö labe''e khöu luo zangombakha.', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 23, 'Ba imane: Gofu itörö dania — möido! Ba imane khönia: Ba ae''e! Ba fagohi Gahimasi, itörö lala ba ndraso Yoridano, ba ihulö Khusi!', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 24, 'Ba Dawido, ba no dumadao ba gotalua mbawa göli si dombua. Ba möi yaŵa ba dete mbawa göli zanaro andrö, tanö ba göli. Ba me ifakhölö ia, ba i''ila, so moroi sa niha si fagohi, ha samösa.', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 25, 'Ba mu''ao zanaro khö razo, i''ombakha''ö khönia. Ba imane razo: Na ha samösa, ba turia si sökhi i''ohe. Ba fagohigohi niha no mege, ba no ahatö ia.', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 26, 'Ba i''ila zamösa tö moroi sa sanaro. Ba mu''ao ia mitou, ba mbawa göli, imane: Samösa tö niha, si fagohi moroi sa! Ba imane razo:', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 27, 'Turia si sökhi göi ni''ohe da''ö! Ba imane sanaro: Famaigigu, ba hulö wagohisa Gahimasi, ono Zadoki, wagohisa zi föföna andrö. Ba imane razo: Niha si sökhi da''ö, ba turia si sökhi i''ohe!', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 28, 'Ba so Gahimasi, ba imane khö razo: Ya''ahowu! ba ifalögu tou ia ba danö, ba imane: Nisuno Yehowa, Lowalangiu, si no mame''e ba dangau niha andrö, si no molaŵa sokhö ya''o, razo!', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 29, 'Ba imane razo: He wisa, lö hadia ia khö nono matua, Abisalomi? Ba imane Ahimasi: No u''ila, aekhu niha sato sibai, me ifatenge zawuyumö andre Yoabi, ba lö nirongogu, he wisa.', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 30, 'Ba imane razo: Ae sa, iagö da''ö! Ba itörö ba i''iagö da''ö.', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 31, 'Ba hiza Khusi, ba imane: Turia si sökhi u''ohe, ya''ugö sokhö ya''o, razo, noa sa itolo''ö Yehowa ma''ökhö ba zolaŵa ya''ugö andrö fefu, no i''ohe ba zatulö!', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 32, 'Ba imane razo khö Khusi: He wisa, lö hadia ia khö nono matua, Abisalomi? Ba imane Khusi: Ena''ö na fagölö-gölö khö nono matua andrö nemali zokhö ya''o, razo, fefu, awö zolaŵa ya''ugö, ba wangalani ya''ugö, fefu!', '["Faigi 15:36; 17:17"]', NULL),
  (3475024, 'OT', 'Samueli II', 18, 33, 'Ba tobali sibai dödö razo, ba möi ia yaŵa ba mbate''e ba dete nomo ba mege-ege ia. Ba imane ba wowaö-waö andrö: He onogu Abisalomi! He onogu, onogu Abisalomi! Ena''ö na ya''o zi mate salahiu! He Abisalomi onogu, onogu!', '["Faigi 15:36; 17:17"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 1, 'Ba la''ombakha''ö khö Yoabi, lamane: Mege-ege razo, abu dödönia ba wa''amate Gabisalomi.', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 2, 'Ba tobali fa''abu dödö wemöna andrö, ba zato fefu, me luo da''ö, me no larongo sato: Abu dödö razo nononia andrö!', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 3, 'Ba so manö niha sato, lö nini-nini, me luo da''ö, ba wamuli ya''ira miyomo ba mbanua, si mane na so zanuwö, si no tehawu fa''aila, me no moloi ira ba wasöndrata.', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 4, 'Ba no ibalugö mbawania razo ba mege-ege ia, imane: He onogu Abisalomi! He Abisalomi, onogu, onogu!', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 5, 'Ba möi yomo khö razo Yoabi, imane khönia: Aila manö genoniu fefu öbe''e ma''ökhö, enoniu si no mangorifi ya''ugö ba onou matua ba onou alawe ba fo''omou ba dongau donga ba döi, ma''ökhö,', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 6, 'me ö''omasi''ö zi fa''udu khöu ba me fa''udu''ö ba zangomasi''ö ya''ugö: noa sa ö''oroma''ö ma''ökhö, wa lö khöu solohe sabölö, awö wa lö enoniu — u''ila sa''ae: na auri mena''ö Gabisalomi ba na ya''aga fefu zi mate, ba satulö manö dödöu da''ö.', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 7, 'Ba faoso, ae tou, ba haogö wehedeu ba mbanuamö! Möido ba hölu khöu, khö Yehowa: na lö ö''oroma''ö ndra''ugö, ba samösa lö si iagö khöu bongi andre, ba abölö-bölö da''ö, moroi ba wamakao bö''ö fefu, si no göna ndra''ugö, i''otarai iraono ndra''ugö, irugi ma''ökhö andre.', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 8, 'Ba maoso razo, möi mudadao ba mbawa göli. Ba me la''ombakha''ö ba niha sato: No dumadao ba mbawa göli razo, ba la''ondrasi sato fefu. Ba Iraono Gizeraeli, ba no moloi, no isaŵa khöra zamösana.', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 9, 'Ba mowasoso zato fefu; dozi mado Ndraono Gizeraeli, ba lamane: No i''efa''ö ita ba danga nemalida razo, ba danga Ndrawa Wilisiti, ba ya''ia zangefa''o ya''ita; ba no moloi ia ba danö ibe''e Abisalomi;', '["Faigi 5:1","Nga''ötI 2:16,17; Faigi 17:35"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 10, 'ba Abisalomi andrö, nibayoinida khöda [razo], ba no mate ba wasöndrata andrö — ba iada''e, ba hana wa lö liŵa-liŵami, ba wangai mangawuli ena''ö razo?', '["Faigi 5:1","Nga''ötI 2:16,17; Faigi 17:35"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 11, 'Ba te''ombakha''ö khö razo hadia niŵa''ö-ŵa''ö Ndraono Gizeraeli fefu. Ba ifatenge khö ndra Sadoki Abiataro ere andrö razo, imane: Mifahuhuo ba zatua mado Yuda, mimane: Hana wa mi''iagö furi, ba wolohe mangawuli razo ba gödonia?', '["Faigi 5:1","Nga''ötI 2:16,17; Faigi 17:35"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 12, 'No iwagu ami, föfö nösigu: ba hana wa mi''iagö furi, ba wolohe mangawuli razo.[1]', '["Faigi 5:1","Nga''ötI 2:16,17; Faigi 17:35"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 13, 'Ba khö Gamasa, ba mimane: Föfö nösigu sa atö ndra''ugö — yamulau khögu zomasi ia Lowalangi, na tenga kumandra sebua ndra''ugö khögu, fangali Yoabi, götö wa''anau nosou![2]', '["Faigi 5:1","Nga''ötI 2:16,17; Faigi 17:35"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 14, 'Ba ombuyu dödö ma''uwu Yuda fefu ibe''e, tobali ha sara dödöra wangandrö khö razo: Fuli''ö, ya''ugö ba enoniu fefu!', '["Faigi 5:1","Nga''ötI 2:16,17; Faigi 17:35"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 15, 'Ba mangawuli razo. Ba me irugi Yoridano ba no larugi Giligala mado Yuda, ba wamaondragö razo, ba ba wama''ötö ya''ia ba Yoridano.', '["Faigi 5:1","Nga''ötI 2:16,17; Faigi 17:35"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 16, 'Ba so göi Zime''i andrö, ono Gera, mado Mbeniyami, banua Mbahuri, igösö ifaondragö mitou razo, Dawido, awö mado Yuda andrö,[3]', '["Faigi 16:5","Faigi 16:10"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 17, 'ba 1000 zi fao khönia mado Mbeniyami. Ba no ita''i-ta''i wowaö-waö föna razo, mitou ba Yoridano, Siba andrö, satua zangai halöŵö khö Zaulo no, awö nononia matua, si felelima ba sawuyunia andrö, si dua wulu; no la''ötö Yoridano,', '["Faigi 16:5","Faigi 16:10"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 18, 'ba götöna andrö, ba wama''ötö awö razo, ba wanolo ya''ira. Ba so Zime''i andrö, ono Gera, mangalulu ia khö razo, me i''ötö sibai Yoridano ena''ö,', '["Faigi 16:5","Faigi 16:10"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 19, 'imane khö razo: He Tua! Böi be''e horögu lalögu no, ba böi törö tödöu zi sala ndra''o, me öheta''ö ba Yeruzalema, ya''ugö Tua, razo, böi tanö ba dödöu:', '["Faigi 16:5","Faigi 16:10"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 20, 'aboto sa ba dödö zawuyumö andre, wa no si sala ia; ba hiza ma''ökhö, ba ya''odo zi föföna ma''uwu Yosefo, si möi mitou ba wamaondragö sokhö ya''o, razo.', '["Faigi 16:5","Faigi 16:10"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 21, 'Ba humede Gabiza''i, ono Zeruya, imane: Hadia, andrö lö labunu Zime''i andrö? Ba no i''elifi niibayoini Yehowa!', '["Faigi 16:5","Faigi 16:10"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 22, 'Ba imane sa Dawido: Hana ami khogu, ya''ami ono Zeruya andrö, wa samowöhö ya''odo ami ma''ökhö? Hadia, so zi mate Iraono Gizeraeli ma''ökhö? Ma öwai lö aboto ba dödögu, wa no ma''ökhö andre tobali razo Ndraono Gizeraeli ndra''odo?[4]', '["Faigi 16:5","Faigi 16:10"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 23, 'Ba imane razo khö Zime''i: Lö mate''ö! Ba möi ba hölu khönia razo.', '["Faigi 16:5","Faigi 16:10"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 24, 'Ba noa göi so moroi si yaŵa Meriba''ali andrö, ma''uwu Zaulo, ba wangondrasi razo; lö nisasainia ahenia ba lö nisukhunia gambinia, ba nukhania, ba lö nibabagonia, i''otarai luo, me mofanö razo no, irugi luo, me mangawuli ia lö hadia ia.', '["Faigi 9:7"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 25, 'Ba me so ia moroi ba Yeruzalema, ba wangondrasi razo, ba imane khönia razo: Hana wa lö fao ndra''ugö khögu, Meriba''ali, me aheta ndra''odo?', '["Faigi 9:7"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 26, 'Ba imane: He Tua, razo! No ilimodo sawuyugu. Noa sa iŵa''ö khönia sawuyumö andre: Fosela khögu galide, fakudo ndra''o, ba wefao khö razo! — me no sombuyumbu ahe zawuyumö andre.', '["Faigi 9:7"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 27, 'Ba no itandraŵaisi zawuyumö andre khö zokhö ya''o, razo. Ba noa sa timba mala''ika Lowalangi zokhö ya''o, razo: ba lau zatulö dödöu!', '["Faigi 9:7"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 28, 'Lö''ö sa atö nidöna-döna nga''ötö duagu khö zokhö ya''o, razo, ha famunu. Ba noa na öhalö awö zorudu manga khöu zawuyumö andre — ba hadia na ni''andrögu folohe ba lala, hadia na niŵa''ögu khö razo?[5]', '["Faigi 9:7"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 29, 'Ba imane khönia razo: Hana wa ö''oya''ö na li? Da''ö niŵa''ögu: Ya''ugö ba Siba andrö, ba mibago dalu khömi mbenua andrö.', '["Faigi 9:7"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 30, 'Ba imane Meriba''ali khö razo: Hana na ahori na''i ihalö, me no mangawuli zokhö ya''o, razo, lö hadia ia.', '["Faigi 9:7"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 31, 'Ba no möi mitou moroi ba Rogeli Mbarasilai andrö, banua Gileadi, ba fao ia khö razo ba Yoridano, ba wamasao ya''ia miyefo.[6]', '["Faigi 17:27"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475025, 'OT', 'Samueli II', 19, 32, 'Ba no atua sibai Mbarasilai andrö, no 80 fakhe. Ba no ibalazoi razo, götö we''aso razo ba Mahana''i; no niha sebua sibai ana''a ia.', '["Faigi 17:27"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 33, 'Ba imane razo khö Mbarasilai: Fao ndra''ugö khögu, ena''ö urorogö ndra''ugö khögu ba Yeruzalema, ba wa''atuamö.', '["Faigi 17:27"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 34, 'Ba imane Barasilai khö razo: Ha wa''anau tö na nosogu, wa faodo khö razo, ba Yeruzalema? 35ŵalu ngafulu fakhe ndra''o iada''e, ba hadia, u''ila na hezo zi sökhi ba hezo zi lö sökhi, ba hadia, i''ila na enonimö andre wa''ami gö ba he nibadu? Ba hana sa wa möi na noro dödö zokhö ya''o, razo, genonimö andre?', '["Faigi 17:27"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 36, 'Ha ma''ifu fao khö razo genonimö andre, ba hana wa imanö razo wanulöni khögu?', '["Faigi 17:27"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 37, 'Hana na mangawuli genonimö, ena''ö na ba mbanua ndra tuagu mate ndra''o, ba ngai lewatö ndra amagu inagu: hiza sawuyumö Kimihami, hana na da''ö zi fao khö zokhö ya''o, razo; khönia fatörö zomasi ndra''ugö.', '["Faigi 17:27"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 38, 'Ba imane razo: Ba lau, ba hana na Kimihami zi möi awögu ba somasi ndra''ugö ufatörö khönia, ba hadia ia fefu, ni''andröu khögu, ba utörö khöu.', '["Faigi 17:27"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 39, 'Ba la''ötö Yoridano sato fefu, ba i''ötö göi razo. Ba fa''ago bawa razo khö Mbarasilai, ba ifofanö; ba ifuli ia ba khöra Barasilai.', '["Faigi 17:27"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 40, 'Ba isaŵa Giligala razo, ba fao khönia Gimihami no mege. Ba sato mado Yuda, ba fao khö razo, ba sato Iraono Gizeraeli, ba matonga zi fao.', '["Faigi 17:27"]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 41, 'Ba i''ogomuzaö la''ondrasi göi razo Iraono Gizeraeli fefu [si tosai]. Ba lamane khö razo: Hana wa no la''oloi''ö ndra''ugö iwada ma''uwu Yuda, hana wa lafa''ötö ba Yoridano razo ba soroiyomonia, fabaya awö Dawido fefu?', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 42, 'Ba lamane ba Ndraono Gizeraeli ma''uwu Yuda fefu: Ba no iwama. Ba hana wa mofönu ami ba da''ö? Hadia, no ma''a wöfö gö razo, ba hadia no ma''oloi''ö ia?', '[]', NULL),
  (3475025, 'OT', 'Samueli II', 19, 43, 'Ba lamane Iraono Gizeraeli ba ma''uwu Yuda: Fulu ni''ofelendrua khöma ba razo, ba noa na si a''a ndra''o moroi khöu; ba hadia sa wa lö ba dödöu ndra''odo? Ba hadia, tenga ya''o zi föföna manguma''ö, tahalö mangawuli razoda? Ba abölö na wasosota ma''uwu Yuda, moroi ba Ndraono Gizeraeli.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 1, 'Ba so göi ba da''ö zi lö mudöna-döna, niha si lö ngaroro, mado Mbeniyami, Seba döi, ono Mbikhiri; ba ilau dorofe ba mu''ao ia, imane: Tenga khöda Dawido. Ba lö sinemada khö nono Giza''i: yamusaŵa khöra zamösana, ya''ami Iraono Gizeraeli!', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 2, 'Ba la''erogö Dawido Iraono Gizeraeli fefu ba la''o''ö Zeba andrö, ono Mbikhiri; ba ma''uwu Yuda, ba la''owuloi ira khö razora, i''otarai Yoridano, numalö ba Yeruzalema.', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 3, 'Ba me no irugi gödonia ba Yeruzalema Dawido, ba ifa''ohe''ö ba nomo bö''ö ndrongania andrö, donga ba döi, si dafulu niröinia furi mege, awö gödo, ba ibalazoi ira ba da''ö, ba lö''ö sa''ae orudu ia khöra. Tobali ni''oniagö ira, irugi mate ira; amaedola lakha mbanua.', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 4, 'Ba imane razo khö Gamasa: Owuloi khögu ma''uwu Yuda, barö zi tölu bongi andre; ba so''ö dania ba da''e!', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 5, 'Ba mofanö Gamasa, ba wangowuloi ma''uwu Yuda. Ba me italu''i ginötö andrö, ni''ötö Dawido khönia,', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 6, 'ba imane Dawido khö Yoabi: Tobali sa abölö ifakao ita Seba andrö, ono Mbikhiri, moroi khö Gabisalomi mege. Ya''ugö ohe genoni zokhö ya''ugö, ba gohi ia, fa böi atu''a ia ba mbanua saro, ba fa böi abu dödöda ibe''e.', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 7, 'Ba mofanö sa''ae Yoabi, awö Gabiza''i, i''ohe zabölö andrö khönia, awö wazuri andrö ba saradadu. Mangefa ira ba Yeruzalema, ba wolohi Seba andrö, ono Mbikhiri.[1]', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 8, 'Ba me so ira ba zinga gara sebua andrö, ba ngai Gibeona, ba itörö fönara Amasa. Ba no so ba danga Yoabi wöda, barö mbarunia, ba sara göi ba mböbö talunia, ba dete mbaru, wöda, nifakhai ba löwi-löwinia saembu; ba ahele da''ö, aekhu tou ba danö.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 9, 'Ba imane Yoabi khö Gamasa: He wisa ga''a, lö hadia ia khöu? Ba ituyu gambi Gamasa Yoabi tangania kambölö, ba wa''agosa bawa.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 10, 'Ba lö ni''ila Gamasa föda andrö ba danga Yoabi kabera, ba itaru''ö ba dalunia Yoabi, tobali aduwa ba danö mbetu''ania ba mate ia; ba lö ifomendrua wanaru''ö khönia Yoabi. Ba lagohi Zeba, ono Mbikhiri, Yoabi ba akhinia Abiza''i.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 11, 'Ba samösa nifataro ba ngai mboto Gamasa, awö Yoabi, si''ao: Ha niha zi möi awö Yoabi ba awö Dawido, ba yamu''o''ö Yoabi!', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 12, 'Ba me no so manö ba dödö lala Gamasa, tou ba ndronia andrö, ba me i''ila niha andrö no mege, oi labadugö ira sanörö, ba ifagaölö ba ngai lala mboto Gamasa, ba ndru''u ba ibalugö baru sebua, me no i''ila, oi labadugö ira sanörö.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 13, 'Ba me no iheta ba lala, ba dozi la''o''ö Yoabi, ba wolohi Seba, ono Mbikhiri.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 14, 'Ba Seba, ba itöröi mado Ndraono Gizeraeli fefu, irugi Habeli Beti Ma''akha, ba so nga''ötö Mbikhiri fefu ba la''o''ö ia miyomo ba da''ö.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 15, 'Ba so göi ndra Yoabi ba lasuwö ia ba Habeli Beti Ma''akha, lako''o fari, lafasui mbanua, ba möi hawu-hawu mbandra da''ö. Ba lafo''arö göli sato fefu, awö Yoabi, ba wanudugö ya''ia.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 16, 'Ba so zi''ao moroi yomo, ira alawe satua-tua, imane: Mifondrondrongo! mifondrondrongo! Miŵa''o khö Yoabi, yamöi ba da''e, so niŵa''ögu khönia!', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 17, 'Ba me ihatö''ö ia, ba imane ira alawe andrö: Hadia, Yoabi ndra''ugö? Ba imane: Ya''ia. Ba imane khönia: Ba fondrondrongo li zawuyumö andre!', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 18, 'Ba imane: Urongo! Ba imane ira alawe andrö: Ba götö föna, ba so gamaedola: "Misofu atö ba Habeli ba ba Dano, na no', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 19, 'muböhöli niŵa''ö zi lö faröi andrö, Iraono Gizeraeli." ö''alui wamakiko banua ba ina ba Ndraono Gizeraeli: Hana wa öfufu dana khö Yehowa?', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 20, 'Ba imane Yoabi: Tenga da''ö dödögu, ma''ifu lö''ö; tenga samakiko ndra''o ba tenga samufu.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 21, 'Tenga da''ö danigu, ba so niha, banua ba hili ba mado Geferayi, Seba döi, ono Mbikhiri, solaŵa razo, Dawido; mibe''e baero ia, ba maböhöli wanuwö banuami! Ba imane ira alawe andrö khö Yoabi: Ba la''anema''ö lafazaumba khöu högönia, moroi ba göli.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 22, 'Ba ifawe''e mbanuara, samba banua manö, ba wa''atua-tuania andrö, ba la''eŵa mbagi Zeba, ono Mbikhiri, ba lafazaumba khö Yoabi högö. Ba ifalau''ö dorofe Yoabi, ba muzaewe zanuwö, laböhöli mbanua andrö, isaŵa khöra zamösana; ba ifuli ia khö razo ba Yeruzalema Yoabi.', '[]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 23, 'Ba solohe sabölö, ba Yoabi; ba högö wazuri, ba Benaya ono Yehoyada;', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 24, 'ba samaigi si göna rodi, ba Adoniramo; ba anofula, ba Yozafati, ono Gahiludi;', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 25, 'ba durutuli, ba Seya; ba ere, ba Sadoki ba Abiataro.', '["Faigi 8:18"]', NULL),
  (3475026, 'OT', 'Samueli II', 20, 26, 'Ba Ira andrö, ma''uwu Ya''iro, ba ere göi khö Dawido.[2]', '["Faigi 8:18"]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 1, 'Samuza me razo Dawido, ba lofo sebua, medöla fakhe, fatete manö. Ba i''andrö khö Yehowa wama''ele''ö Dawido. Ba imane Yehowa: So na ba hulu ndra Saulo nga''ötönia horö fange''e, me no ibunu mbanua Gibeona no.', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 2, 'Ba i''oroi''ö mbanua Gibeona razo ba isofu khöra — tenga sa föfö Ndraono Gizeraeli mbanua Gibeona andrö, si tosai Dawa Gamori ira, ba he ŵa''ae no möi ba hölu khöra Ndraono Gizeraeli [ba wangorifi ya''ira], ba i''alui zui Saulo wangohori ya''ira, ba wa''aukhu dödönia föna Ndraono Gizeraeli ba föna ma''uwu Yuda.[1] —', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 3, 'Ba imane Dawido ba mbanua Gibeona andrö: He uwisa khömi, wangezosi, ena''ö mifuli mifahowu''ö dana khö Yehowa?', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 4, 'Ba lamane khönia banua Gibeona: Tenga sangandrö ana''a ba ma firö ndra''aga khö Zaulo ba ba nga''ötönia, ba lö tola göi mabunu niha ba Ndraono Gizeraeli. Ba imane: Ba hadia ni''andrömi, he uwisa khömi?', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 5, 'Ba lamane khö razo: Niha andrö, samakiko ya''aga, ba sangalui fangohori ya''aga, tobali lö nahinahiama sa''ae ba danö Ndraono Gizeraeli ma''asagörö —', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 6, 'nga''ötönia mibe''e ba dangama, dafitu, ena''ö mataŵi khö Yehowa, ba Gibeona, ba hili Yehowa andrö. Ba imane razo: Ube''e ba dangami.', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 7, 'Ba i''orifi Meriba''ali andrö ono Yonata, ma''uwu Zaulo, börö wahölusa andrö, me no faoma fahölu ira khö nawöra, khö Yehowa, Dawido ba Yonata, ono Zaulo.[2]', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 8, 'Ba nibe''enia ba danga mbanua Gibeona, ba ono Zaulo andrö si darua, Arimoni ba Meriba''ali, ononia khö Risifa andrö, ono Aya, ba ono nono Zaulo andrö alawe, Meraba, si dalima, ononia khö Gaderieli andrö, ono Mbarasilai, banua Mehola.[3]', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 9, 'Ba lataŵi ira föna Yehowa, ba hili. Tobali endronga mate zi dafitu andrö, me böröta mbaŵa wamasi tebunu ira.', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 10, 'Ba ihalö mbarunia gonigoni Risifa andrö, ono Aya, ibologö tufonia ba dete gara, i''otarai mböröta wamasi andrö, irugi göna ira teu ba tobali itaboi wofo ba dalu mbanua, na ma''ökhö ba utu ndru''u ba zi bongi, fa böi la''a [mboto zi mate andrö].', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 11, 'Ba te''ombakha''ö khö Dawido nilau ndronga Zaulo andrö, donga ba döi, Risifa, ono Aya.', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 12, 'Ba maoso Dawido, ifahalö''ö döla Zaulo ba töla nononia Yonata, ba mbanua Yabesi ba danö Gileadi, nitagöra ba onga ba Metisana, ba nitaŵi Ndrawa Wilisiti ya''ira, me no te''ala Zaulo ba hili Giliboa labe''e.[4]', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 13, 'Ifaheta''ö ba da''ö döla Zaulo ba töla nononia Yonata; ba la''ozaragö göi döla nitaŵi andrö, ba lako''o,', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 14, 'awö döla ndra Saulo ononia Yonata, ba danö mado Mbeniyami, ba Zela, ba lewatö nama Zaulo, Kisi. La''o''ö sibai goroisa razo. Ba i''otarai da''ö, ba ifuli alö dödö Lowalangi ba niha ba danö.', '["Yos 9:19","SamI 18:3","SamI 18:19; Faigi 3:7","SamI 31:1 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 15, 'Ba tesao zui wanuwö, lasuwö Ndraono Gizeraeli Dawa Wilisiti. Ba möi misi tou Dawido ba enoninia, ba wanimba Dawa Wilisiti. Ba me no tebato ira ba Gobi, ba maoso Dodo,', '["Ayati 18—21: Nga''ötI 20:4—8","Nga''ötI 20:4 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 16, 'nga''ötö niha sebua sibai andrö, ba wamunu Dawido ena''ö; 300 zekeli töla wa''abua nösi dohonia, ba föda si bohou ba löwi-löwinia.', '["Ayati 18—21: Nga''ötI 20:4—8","Nga''ötI 20:4 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 17, 'Ba itolo Dawido Abiza''i, ono Zeruya, ibunu Ndrawa Wilisiti andrö. Ba fahölu khö Dawido zabölö andrö khönia lamane: Lö tola sa''ae fao ndra''ugö khöma, ba wasuwöta, fa böi mate wandru ba Ndraono Gizeraeli öbe''e!', '["Ayati 18—21: Nga''ötI 20:4—8","Nga''ötI 20:4 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 18, 'Ba furi ö, ba fasuwö na zui ira ba Ndrawa Wilisiti, ba ngai Gobi.[5] Ba da''ö ibunu Zafo andrö, nga''ötö niha sebua andrö göi, Sibekhai, banua Husa.[6]', '["Ayati 18—21: Nga''ötI 20:4—8","Nga''ötI 20:4 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 19, 'Ba me samuza tö fasuwö ba Ndrawa Wilisiti, ba Gobi, ba ibunu Goliato, banua Gata Elehana, banua Mbetilekhema; ezai hao dotoa mburusa Goliato andrö.', '["Ayati 18—21: Nga''ötI 20:4—8","Nga''ötI 20:4 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 20, 'Ba samuza tö fasöndra na ira ba ngai Gata. Ba so ba da''ö niha sebua sibai; onö''önö duturu danga ba önö''önö göi duturu kahe, tobali 24 fefu — no nga''ötö niha sebua sibai andrö ia göi.', '["Ayati 18—21: Nga''ötI 20:4—8","Nga''ötI 20:4 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 21, 'Ba me i''o''aya Ndraono Gizeraeli da''ö, ba ibunu ia Yonata andrö, ono ga''a Dawido, Sime''i,', '["Ayati 18—21: Nga''ötI 20:4—8","Nga''ötI 20:4 b.t."]', NULL),
  (3475027, 'OT', 'Samueli II', 21, 22, 'Nga''ötö niha sebua sibai andrö, banua Gata, zi daöfa andrö, nibunu ndra Dawido enoninia andrö.', '["Ayati 18—21: Nga''ötI 20:4—8","Nga''ötI 20:4 b.t."]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 1, 'Ba humede Dawido, manunö, ia khö Yehowa, me luo da''ö,[1] me no i''efa''ö ia Yehowa ba danga nemalinia fefu ba ba danga Zaulo,', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 2, 'imane: "Hili dödögu Yehowa ba wa''atosasagu ba sangorifi ya''odo.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 3, 'Nahiagu saro Lowalangigu, ba khönia u''alui zaŵatö; balusegu ia ba tandru fangorifigu, hatigu ba saŵatögu, sangefa''ö ya''odo; ya''ugö zangefa''ö ya''o, na tefakao ndra''odo![2]', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 4, 'U''angaröfi li Yehowa, si nangea nisuno andrö, ba te''efa''ö ndra''o ba danga zi fatiu tödö khögu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 5, 'Noa sa ifasui ndra''o dulu, ba no ifeta''u ndra''o hohou famunu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 6, 'No mukabi ndra''o böbö si oroi mbanua tou ba no ihawui ndra''o tandraŵa famunu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 7, 'No mu''ao ndra''o ba wa''atosasagu andrö, ba no u''angaröfi li Lowalangigu: No ifondrondrongo ligu ba gödonia andrö ba no irugi dögi dalingania we''aogu andrö khönia.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 8, 'Ifaigi — ba humeu danö; humisi dayadaya mbanua yaŵa ba mudögö, me no mofönu ia.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 9, 'Manimbo nikhunia ba i''otarai mbawania alitö si manga hadia ia; humola mbo galitö, si oroi khönia.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 10, 'Idada mbanua si yaŵa, möi ia tou, ba sogömi-gömi barö gahenia.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 11, 'Ba hulu Kerubi möi ia, muhombo misa; manahanahae ia ba gafi nangi.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 12, 'Ibali''ö balu-balunia zogömi-gömi, osenia fasui, salu ba lawuo saitö.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 13, 'Moroi ba haga andrö fönania itörö lawuo andrö khönia, teu kara ba bo galitö.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 14, 'Ba mu''ugu-ugu mbanua si yaŵa ibe''e Yehowa, ba ifarongogö linia Fondrege zalaŵa andrö.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 15, 'I''efasi nono wana khönia, ifazawili ira, ba ilau gari mbanua, ikeani ira.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 16, 'Ba oroma nungo nidanö, ba aheta mbalu-balu dayadaya danö, ba wanegumö andrö, ya''ugö Yehowa, ba wangöhöfu geheha nikhumö andrö.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 17, 'I''oro''ö dangania moroi si yaŵa, ira''udo, isöbido moroi ba nidanö sebua.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 18, 'Ifadöni ndra''o ba nemaligu andrö, si no abölö, ba ba zi fatiu tödö khögu, me no tebai ulaŵa ira.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 19, 'No lahawui ndra''o, me baŵa wa''ate''alagu, ba no tobali fanologu Yehowa.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 20, 'Ba no i''ohe baero ndra''o, ba zebolo tanö; no i''efa''ö ndra''odo, me no omasi ia ndra''o.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 21, 'No isulöni khögu wa''atulö dödögu Yehowa; no ibe''e khögu zulö, dali wa lö hadia ia zi falemba ba dangagu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 22, 'Noa sa utörö lala Yehowa, lö solalö ndra''o ba khö Lowalangigu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 23, 'Noa sa so ba gametahögu huku andrö khönia, fefu, ba amakhoitania andrö, ba lö ni''aröu''ögu khögu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 24, 'No adölö dödögu khönia, ba no ata''u ndra''o ulau zi lö atulö.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 25, 'Ba no isulöni khögu wa''atulö dödögu andrö Yehowa, dali wa lö hadia ia zi falemba ba dangagu, wamaiginia.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 26, 'Ba zebua tödö ebua dödöu, ba ba zadölö tödö adölö dödöu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 27, 'Ba zohau-hau ohau-hau ndra''ugö, ba ba zabila tödö abila göi ndra''ugö.[3]', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 28, 'Ya''ugö sa zanolo niha si göna famakao, ba öhöndrögö hörö zi fayaŵa, fefu.[4]', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 29, 'Ya''ugö sa zamohaga fandrugu, ifohaga zogömi-gömi andrö khögu Yehowa, Lowalangigu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 30, 'Na ötolodo, ba ududugö göli kara, ba na awögu Lowalangigu, ba usawö mba''a-ba''a.[5]', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 31, 'Lala Lowalangi andrö, ba no so''ahonoa! Taroma li Lowalangi andrö, ba si no ohao-hao, baluse ia ba zangalui saŵatö khönia, fefu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 32, 'Ha niha sa Lowalangi, baero Yehowa andrö? Ba ha niha nahia saro, baero Lowalangida?', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 33, 'Lowalangi andrö, same''e böbö talugu fa''abölö, ba sangehao lala khögu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 34, 'Samali''ö ahe mböhö ahegu ba samataro ya''o ba zalaŵa yaŵa.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 35, 'Samahaö tangagu ba wasöndrata ba ta''iogu ba wogai fana töla.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 36, 'Ba no öbe''e khögu mbaluse fangorifi andrö khöu, ba fa''ebua dödöu wangebuagu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 37, 'No ö''ebolo''ö naha gahegu, ba lö sangiwa mbu''u kawonogu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 38, 'No ugohi nemaligu ba no ukhamö, ba lö nifuligu ya''o furi, balazi no ufakiko ira.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 39, 'No ufakiko ira, ba no urasa, tobali lö''ö sa''ae maoso ira; tegaölö tou ira barö gahegu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 40, 'Ba no öfamöbö talu ndra''o fa''abölö, ba wasöndrata, no öfaöndrö barögu zi fa''udu khögu.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 41, 'Moloi nemaligu andrö öbe''e; ba si fatiu tödö khögu ba no uhori!', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475028, 'OT', 'Samueli II', 22, 42, 'Mangarö-ngarö ira, ba lö sangorifi — khö Yehowa, ba lö itema lira.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 43, 'Ba no ufufu ira, timba gawu-gawu ba danö, uhundra-hundra ira, timba dambu baewali, uduwagö.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 44, 'No ö''efa''ö ndra''o ba wasöndrata niha, no öfataro högö soi niha ndra''odo: tobali möi barö mbawagu niha si lö urai mila.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 45, 'Ha larongo ligu, ba la''o''ö khögu, lahaogö-haogö wehedera khögu ono niha bö''ö.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 46, 'Sariri nono niha bö''ö, laröi gödora, manizi-nizi.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 47, 'Sauri Yehowa, ba nisuno nahiagu saro andrö, ba ni''ebua''ö döi Lowalangi fangorifogu andrö!', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 48, 'Lowalangi andrö, si no manolo ya''o ba wolau balö, si no mame''e barö mbawagu soi niha.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 49, 'Sangefa''ö ya''o ba nemaligu andrö, ba no öbe''e yaŵa zi fa''udu khögu ndra''odo; no ö''efa''ö ndra''o ba danga niha andrö samakao awönia.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 50, 'Andrö usuno ndra''ugö ba niha baero, ya''ugö Yehowa; usuno döimö.', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475028, 'OT', 'Samueli II', 22, 51, 'Ya''ugö, sangebua fangorifi ba razo andrö khönia, ba sangebua tödö ba nibayoininia andrö, khö Dawido ba ba ma''uwunia, irugi zi lö aetu."', '["Faigi göi Sin 18","Luk 1:69","MozIII 26:24","Sin 113:7","SamI 17:45"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 1, 'Da''e zinunö Dawido safuria: "Niŵa''ö Dawido, ono Giza''i; niŵa''ö niha andrö, si no salaŵa sebua, nibayoini Lowalangi Yakobo, omasiö sanunö ba Ndraono Gizeraeli,', '["Faigi 7:16"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 2, 'imane: "No muhede khögu Geheha Yehowa, ba taroma linia zi so ba mbewegu.', '["Faigi 7:16"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 3, 'No muhede Lowalangi Ndraono Gizeraeli; khögu no muhede gowe Ndraono Gizeraeli andrö, imane: Sangatulö''ö famatörö niha, sangata''ufi Lowalangi ba wamatörönia andrö,[1]', '["Faigi 7:16"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 4, 'ba no hulö haga zi moluo, na tumbu luo, na mahemolu mbanua, na lö lawuo, na tumbu ndru''u ba danö ba haga zino, na no aefa deu.', '["Faigi 7:16"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 5, 'Hadia, tenga si manö ndra''aga, ya''aga si samba omo, ba khö Lowalangi? Noa sa ifabu''u linia khögu, si lö tebulö, irugi zi lö aetu; si no muhonogöi, ba si no mu''aro''ö, gofu he wisa wamaigida. Ba fangorifigu fefu ba fa''omasigu, hadia, lö ifatumbu''ö da''ö?', '["Faigi 7:16"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 6, 'Ba si lö ngaroro andrö, ba no timba ndroi nitibo''ö ira, fefu, si lö tababaya tangada.', '["Faigi 7:16"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 7, 'Sedöna mombambaya ya''ia, ba i''ohe zi''öli, ba ma toho, ba ahori tetunu ba galitö."', '["Faigi 7:16"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 8, 'Da''e döi zabölö andrö khö Dawido:[2] Iseba''ali, ma''uwu Hakhimono, högö zi datölu andrö. Ilau dohonia, ba 800 zi mate, ha samuza.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 9, 'Ba fanetenia ba zi datölu andrö, sabölö, ba Eleazari, ono Dodo, ma''uwu Gahohi. Ya''ia nawö Dawido ba Wasi Dami, me no uwulo ba da''ö Ndrawa Wilisiti ba wanuwö. Ba me lawuwu ira furi Iraono Gizeraeli,', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 10, 'ba lö ibulö''ö ia, ilau ba Ndrawa Wilisiti, irege atage dangania, irege falemba ba ndranga zi''öli; tobali möna sibai ia ibe''e Yehowa, me luo da''ö. Ba mangawuli zato, la''o''ö ia — hatö ba wangai sahulu ira.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 11, 'Ba fanetenia, ba Sama, ono Age, banua Harari. Samuza ma''ökhö, ba owulo Ndrawa Wilisiti ba Lehi. Ba so ba da''ö kabu harita. Ba me moloi zato, ba Ndrawa Wilisiti andrö,', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 12, 'ba i''agö dalu kabu andrö, itimba Ndrawa Wilisiti, ilau khöra, ba möna sibai ia ibe''e Yehowa.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 13, 'Ba samuza ma''ökhö, ba datölu — ba zi tölu ngafulu, högöra andrö — zi möi misi tou khö Dawido ba dögi narö gara andrö, ba hati Adula, me no so ba ndraso, ba Refa''i, Ndrawa Wilisiti, sambawa.[3]', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 14, 'Ba hati andrö so Dawido, me luo da''ö, ba so nifataro ba Mbetilekhema Dawa Wilisiti.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 15, 'Ba itörö tödö Dawido [nidanö si sökhi] ba imane: Ha niha zana''u ögu idanö ba mba''a andrö ba zinga mbawa göli ba Mbetilekhema?', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 16, 'Ba latörö golombaseŵa Ndrawa Wilisiti sabölö andrö si datölu, lata''u nidanö ba mba''a andrö, ba zinga mbawa göli ba Mbetilekhema, ba la''ohe khö Dawido. Ba lö edöna ibadu, iduwagö kho Yehowa, [sumange],', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 17, 'imane: Yamutimba khögu Yehowa wolau si manö! Do zabölö andrö, si lö ba dödö nosora we''amöi! — ba lö''ö manö ibadu. Da''ö nilau zabölö andrö si datölu.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 18, 'Ba Abiza''i andrö, akhi Yoabi, ono Zeruya, ba no högö zi tölu ngafulu göi. Ilau dohonia, ba 300 zi mate, ba sebua töi ia ba zi tölu ngafulu andrö.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 19, 'Ba zi tölu ngafulu andrö, ba nifosumange ia, ba ya''ia högöra, ba lö ikhamö zi datölu andrö.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 20, 'Ba Benaya andrö, ono Yehoyada, niha sabölö, si teturia ba nilaunia andrö, ba banua Gabese''eli. Ya''ia zamunu ono Garieli andrö, Iraono Moabi. Ba samuza ma''ökhö, me no aekhu deu si baku, ba ya''ia göi zamunu singo, si tou ba mba''a.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 21, 'Ba ibunu göi Ndrawa Miserayi, samösa, niha sebua sibai; sara doho ba danga Ndrawa Miserayi andrö, ba ya''ia, ba ha si''o i''ohe, ba wolau khönia. Ba ira''u ba danga Ndrawa Miserayi andrö doho andrö ba ibunu ia tohonia.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 22, 'Da''ö nilau Mbenaya andrö, ono Yehoyada. Sebua turia ia ba zi tölu ngafulu andrö, sabölö.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 23, 'Ba zi tölu ngafulu andrö, ba nifosumange ia, ba si datölu andrö, ba lö''ö sa ikhamö. Ba ibe''e högö wazuri andrö khönia ia Dawido.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 24, 'Ba samösa göi Gazaheli andrö, akhi Yoabi, ba zi tölu ngafulu andrö; ba baero ö, ba Elehana, ono Dodo, banua Mbetilekhema;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 25, 'ba Sama, banua Harodi;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 26, 'ba Elika, banua Harodi; ba Helesi, banua Welete; ba Ira, ono Ike, banua Dekoa;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 27, 'ba Abiezeri, banua Ganatoti; ba Sibekhai, banua Husa;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 28, 'ba Salemona, banua Gahohi; ba Maharai, banua Netofa;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 29, 'ba Heledi, ono Mba''ana, banua Netofa; ba Ita''i, ono Ribai, banua Gibea andrö, ba mado Mbeniyami;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 30, 'ba Benaya, banua Wireato; ba Hida''i, banua Nahale-Ga''asi;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 31, 'ba Abieli, banua Mbeti Araba; ba Asimaweti, banua Mbahuri;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 32, 'ba Eliyaba, banua Za''alibona; ba Yaseno, ma''uwu Guni; ba Yonata,', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 33, 'ono Zama, banua Harari; ba Ahiami, ono Zarari, banua Harari;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 34, 'ba Elifeleti, ono Ahasibai, banua Ma''akha; ba Eliami, ono Gahitofeli, banua Gilo;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 35, 'ba Hesero, banua Garemeli; ba Fa''ari, ma''uwu Garakhi;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 36, 'ba Yigala, ono Natano, banua Zoba; ba Bani, mado Gado;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 37, 'ba Seleki, Iraono Gamoni andrö; ba Naharai, banua Mbe''eroti, solohe fangöna khö Yoabi, ono Zeruya;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 38, 'ba Ira, banua Yatiri; ba Garebi, banua Yatiri;', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475029, 'OT', 'Samueli II', 23, 39, 'ba Uria andrö, Iraono Kheti; — tölu ngafulu a fitu fefu.', '["Ayati 8—39: Nga''ötI 11:10—41","SamI 22:1"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 1, 'Ba ifuli tesao wönu Yehowa ba Ndraono Gizeraeli,[1] tobali ifarou khöra Dawido, wanguma''ö khönia: Labu! ofaya Ndraono Gizeraeli, fabaya mado Yuda![2]', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 2, 'Ba imane Dawido khö Yoabi ba ba gumandra andrö barö mbawania: Mitöröi mado Ndraono Gizeraeli fefu, i''otarai Dano, numalö ba Mbereseba, ba mi''ofaya niha, ena''ö urongo wa''ato niha ba danö!', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 3, 'Ba imane Yoabi khö razo: Ba he meotu tö wa''atora inönö niha Lowalangiu, Yehowa, ba götö zokhö ya''o, razo — gofu ha wa''ato ira sa''ae — ba hana wa omasi zokhö ya''o, razo, zi manö?', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 4, 'Ba abe''e li razo khö Yoabi ba ba gumandra andrö; ba laröi razo ira Yoabi kumandra andrö, ba wangofaya Iraono Gizeraeli.', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 5, 'La''ötö Yoridano ba ba Garuri labörötaigö ba ba mbanua andrö ba ndraso, ba ngai lala ba mado Gado ba ba Yaezeri.[3]', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 6, 'Ba larugi danö Gileadi ba ola danö Ndraono Kheti, tanö ba Gadesi. Ba aefa da''ö, ba larugi Dano; ba moroi ba da''ö, ba lahole''ö ira tanö ba Zidona.', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 7, 'Ba larugi mbanua saro andrö, Tiro, ba latörö mbanua Ndraono Hewi ba banua Ndrawa Gana''ana, fefu, ba lasaŵa danö si raya, tanö mado Yuda, Mbereseba.', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 8, 'Ba me no latöröi danö ma''asagörö, siŵa waŵa a dua wulu wongi wa''ara, ba lafuli ira ba Yeruzalema.', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 9, 'Ba i''ombakha''ö khö razo Yoabi wa''ato niha ni''ofayara: fa''ato Ndraono Gizeraeli, ba 800.000 zabölö, solohe baluse, ba fa''ato mado Yuda, ba 500.000.', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 10, 'Ba itegu Dawido tödönia, me no iŵa''ö wangofaya niha. Ba imane Dawido khö Yehowa: No ebua horögu, me no ulau da''ö. Ba iada''e, ya''ugö Yehowa, ba efa''ö horö genonimö andre, noa sa owöhö sibai ndra''odo![4]', '["Faigi göi Nga''ötI 21","Faigi 21:1","Yos 12:2","Faigi 12:13"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 11, 'Ba me maoso Dawido, me moluo, ba so niŵa''ö Yehowa khö Gado andrö, sama''ele''ö, sangi''ila andrö khö Dawido, imane:', '["Nga''ötI 21:15 b.t."]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 12, 'Ae ŵa''ö khö Dawido: Da''ö niŵa''ö Yehowa; Tölu balö uŵa''ö khöu, tuyu zomasi''ö ulau khöu!', '["Nga''ötI 21:15 b.t."]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 13, 'Ba möi yomo khö Dawido Gado, i''ombakha''ö khönia, imane khönia: Hadia zomasi''ö: medölu fakhe lofo sebua ba danöu, ba ma tölu waŵa lagohi''ö emaliu ba i''alui ndra''ugö si''öli, ba ma zui tölu bongi wökhö waba ba danöu? Ba timba tödöu ba faigi, hadia nifuligu khö zamatenge ya''o!', '["Nga''ötI 21:15 b.t."]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 14, 'Ba imane Dawido khö Gado: Ata''u sibai ndra''o — yagöna ita tanga Yehowa, me no ebua sibai wa''ahakhö dödönia. Ba lö''ö sa omasido na gönado tanga niha!', '["Nga''ötI 21:15 b.t."]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 15, 'Ba ituyu khönia wökhö waba Dawido. Ba baŵa si''aikö wamasi gandru, me ibörötaigö fökhö andrö, ba mate niha ba danö, i''otarai Dano, numalö ba Mbereseba, 70.000.', '["Nga''ötI 21:15 b.t."]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 16, 'Ba me ba Yeruzalema i''oro''ö dangania mala''ika andrö, ba wamakiko ya''ira, ba aröuröu ba dödö Yehowa wamunu andrö, ba imane khö mala''ika andrö, samakiko niha: Noa, bato sa''ae! — Ba ba zinga golayama mbasitö khö Garafa, Iraono Yebusi andrö, so mala''ika Yehowa.[5]', '["Nga''ötI 21:15 b.t."]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 17, 'Ba me i''ila Dawido ibunu niha sato mala''ika andrö, ba imane khö Yehowa: Hiza, ya''o zamazökhi horö, ya''o zolalö, ba hadia horö mbiri-biri andrö? Ya''odo otu''ö, si sawu ya''aga!', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 18, 'Ba me luo da''ö, ba möi khö Dawido Gado andrö, imane khönia: Ae miyaŵa ba fa''anö naha wame''e sumange khö Yehowa, ba golayama mbasitö khö Garafa andrö, Iraono Yebusi![6]', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 19, 'Ba möi miyaŵa Dawido, i''o''ö niŵa''ö Gado, dali goroisa Yehowa.', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 20, 'Ba me ifakhölö ia Arafa, me i''ila moroi sa razo ba awönia, ba möi ia tou, ifaöndrö ia föna razo, irugi tou danö bawania.', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 21, 'Ba imane Arafa: Hadia wa möi zokhö ya''o, razo, khö zawuyunia? Ba imane Dawido: Ba wowöli khöu olayama mbasitö andrö, ena''ö ufa''anö naha wame''e sumange khö Yehowa, ena''ö tebato wamakao andrö ba mbanuada.', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 22, 'Ba imane Arafa khö Dawido: Yamuhalö manö zomasi ia sokhö ya''o, razo, ba yamube''e sumange; hiza zaŵi sumange ba kureta famöbörö wakhe andrö ba fakake zaŵi,', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 23, 'eu — ahori ibe''e buala da''ö khö razo sawuyu zokhö ya''o, razo. Ba imane na khö razo: Yamuhakhösi tödö ndra''ugö Lowalangiu, Yehowa!', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 24, 'Ba imane razo khö Garafa: Böi, ube''e mböli, u''öli khöu: lö ube''e sumange Lowalangiu Yehowa, sumange nitunu, nibe''e buala khögu. Ba i''öli golayama mbasitö andrö, awö zaŵi, Dawido, 50 rufia mböli.', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475030, 'OT', 'Samueli II', 24, 25, 'Ba ifa''anö ba da''ö naha wame''e sumange khö Yehowa Dawido, ba ibe''e zumange nitunu ba sumange fangorifi. Ba ahakhö dödö Yehowa niha ba danö ba döhö wamakao andrö ba Ndraono Gizeraeli.[7]', '["Nga''ötII 3:1","Sin 30"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 1, 'Ba me no atua Dawido, me no numalö ndröfinia, ba oafu-afu manö ia, he ŵa''ae la''olohuni ambala.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 2, 'Ba lamane khönia enoninia: Dala''alui nono alawe khö zokhö ya''aga, razo, ono alawe si lö irai falukha ba ndra matua, ena''ö ngoni-ngoni razo ia ba sondrorogö ya''ia; na ötalagui da''ö, ba döhö wa''oafu zokhö ya''aga, razo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 3, 'Ba la''alui ba danö Ndraono Gizeraeli ma''asagörö nono alawe si sökhi bawa ba lasöndra, Abizagi, banua Zunema ba la''ohe khö razo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 4, 'Ba no ono alawe si sökhi si''ai bawa, ba tobali sondrorogö razo ia, ngoni-ngoninia, ba lö''ö sa orudu khönia razo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 5, 'Ba maoso Gadonia, ono Hagita andrö, imane: Ya''odo zi tobali razo dania! Ba i''öli sa''ae khönia gureta ba kudo, ba 50 ifa''aso khönia niha, sowaö-waö fönania.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 6, 'Ba lö irai ibusi dödönia amania, ba götönia, wanguma''ö khönia: Hana wa ömanö? Ba no si sökhi si''ai boto ia, ba no fanete Gabisalomi, ba wa''atumbu.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 7, 'Ba fahuhuo Gadonia khö Yoabi, ono Zeruya, ba khö Gabiataro andrö, ere, ba fa''awö ira khönia.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 8, 'Ba Sadoki andrö, ere, ba Benaya, ono Yehoyada ba Natano sama''ele''ö, ba he Sime''i ba Re''i, ba saradadu andrö khö Dawido, ba no tenga si fa''awö khö Gadonia.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 9, 'Ba me itaba mbiri-biri ba saŵi ba ono zaŵi nibula Adonia, ba gara gulö andrö, ba ngai gumbu Rogeli, ba ikaoni dalifusönia fefu, ono razo, awö ma''uwu Yuda, fefu, enoni Dawido; ba si lö ikaoni,', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 10, 'ba Natano, sama''ele''ö, ba Benaya ba saradadu andrö ba akhinia Selomo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 11, 'Ba imane Natano khö Mbaseba, ina Zelomo: Tabe''e no orongo, wa no tobali razo Adonia, ono Hagita; lö nirongo Dawido, sokhö ya''ita.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 12, 'Ba da''ufobawa lala khöu, he öwisa wangorifi ya''ugö ba onou Selomo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 13, 'Ae yomo khö Dawido, ba ömane khönia: Hadia, lö si möi''ö ba hölu khö genoniu ira alawe andre, ya''ugö sokhö ya''o, razo, wanguma''ö: Onou Selomo dania razo, fangaligu, ba ya''ia dania zidadao ba dadaomagu? Ba hana wa no Adonia zi tobali razo?', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 14, 'Ba fatua fahuhuo na ndra''ugö ba da''ö khö razo, ba so göi ndra''o, u''o''ö ndra''ugö yomo, ba ufaduhu''ö niŵa''öu.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 15, 'Ba möi si bakha khö razo Mbaseba; ba si no atua sibai razo, ba no Abizagi, banua Zunema, ngoni-ngoninia.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 16, 'Ba mangalulu Mbaseba, ifalögu tou ia, ba imane razo: Hadia ni''andröu?', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 17, 'Ba imane khönia: He sokhö ya''o, no möi ba hölu ndra''ugö khö genonimö andre, ba khö Lowalangiu, Yehowa, wanguma''ö: Onou Selomo dania razo fangaligu, ba ya''ia dania zidadao ba dadaomagu!', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 18, 'Ba hiza, ba no Adonia zi tobali razo, ba lö''ö sa nirongou, ya''ugö sokhö ya''o, razo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 19, 'Ba no oya itaba saŵi si matua ba ono zaŵi nibula ba biri-biri, ba no ikaoni ba da''ö nono razo fefu, ba Abiataro, ere, ba Yoabi, kumandra sebua; ba enoniu Selomo, ba lö nikaoninia.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 20, 'Ba ya''ugö, sokhö ya''o, razo, nitöngöni Ndraono Gizeraeli fefu, ena''ö ö''ombakha''ö khöra, ha niha dania zidadao ba dadaomamö, fangaliu, ya''ugö sokhö ya''o, razo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 21, 'Ha si''ai dania öleagö tou ndra''ugö ba ngai ndra tuau, ya''ugö sokhö ya''o, razo, ba mobahulu ndra''aga onogu Selomo!', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 22, 'Ba lö saetu na huhuonia khö razo, ba hiza Natano, sama''ele''ö.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 23, 'Ba lamane khö razo: Hiza Natano, sama''ele''ö! Ba i''ondrasi razo, ifalögu tou ia ba zalo, fönania,', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 24, 'ba imane: He sokhö ya''o, razo! hadia, ya''ugö zanguma''ö: Adonia zi tobali razo fangaligu, ya''ia dania zidadao ba dadaomagu?', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 25, 'Noa sa möi ia mitou ma''ökhö, ba no oya itaba saŵi si matua ba ono zaŵi nibula ba biri-biri, ba no ikaoni nono razo fefu ba kumandra ba Abiataro ere. Ba hiza, ba manga ira khönia ba labadu nagu, ba lamane: Ya''ahowu razo Adonia!', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 26, 'Ba ya''odo, enonimö andre, ba Sadoki ere ba Benaya, ono Yehoyada ba enoniu Selomo, ba lö nikaoninia.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475031, 'OT', 'Razo I', 1, 27, 'Hadia, ya''ugö zanguma''ö da''ö, ba lö öfarongogö ba genonimö ha niha dania zidadao ba dadaomamö, fangaliu, ya''ugo sokhö ya''o, razo?', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 28, 'Ba itema linia razo, Dawido, imane: Mihede khögu khö Mbaseba! Ba so ia, i''ondrasi razo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 29, 'Ba fahölu razo, imane: Ba wa''aduhu wa''auri Yehowa, si no mangefa''ö ya''o ba ngawalö wamakao andrö fefu, 30— dali we''amöigu ba hölu khöu, ba khö Yehowa, Lowalangi Ndraono Gizeraeli, me umane: Onou Selomo dania razo furigu, ba ya''ia dania zidadao ba dadaomagu, fangaligu, da''ö utörö ma''ökhö.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 31, 'Ba ifaöndrö ia Baseba tou ba zalo, mangalulu ia khö razo, ba imane: Ya anau noso zokhö ya''o, razo, Dawido!', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 32, 'Ba imane razo Dawido: Mihede khögu khö Zadoki, ere, ba khö Natano, sama''ele''ö, ba khö Mbenaya, ono Yehoyada. Ba möi ira yomo khö razo.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 33, 'Ba imane razo: Mi''ohe genoni zokhö ya''ami, ba mifakudo nonogu Selomo ba kudo kalide khögu ba mi''ohe mitou ia ba Gihona.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 34, 'Ba da''ö dania labayoini ia razo Ndraono Gizeraeli Sadoki ere ba Natano sama''ele''ö; ba aefa da''ö, ba milau dorofe, ba mu''ao ami, mimane: Ya''ahowu razo Selomo!', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 35, 'Ba mi''o''ö sa''ae ia miyaŵa, ena''ö möi ia miyomo ba ena''ö mudadao ia ba dadaomagu, fa ya''ia razo fangaligu; noa sa ya''ia niŵa''ögu, ena''ö ya''ia razo ba Ndraono Gizeraeli ba ba mado Yuda.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 36, 'Ba itema li razo Benaya, ono Yehoyada, imane: Ya''ia da''ö! Yamutehe Yehowa, Lowalangi zokhö ya''o, razo!', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 37, 'Si mane fanolo Yehowa sokhö ya''o, razo, ya si manö göi wanolonia Selomo ba yamu''alaŵa''ö na yaŵa dadaomania, moroi ba wa''alaŵa dadaoma zokhö ya''o, razo Dawido!', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 38, 'Ba möi ira mitou, ira Sadoki ere Natano sama''ele''ö ba Benaya, ono Yehoyada, awö wazuri andrö, ba lafakudo Zelomo ba hulu kudo kalide andrö khö razo Dawido, ba la''ohe ia ba mbewe Gihona.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 39, 'Ba ihalö dandru wanikha andrö ba nose Sadoki ere, ba ibayoini Zelomo. Ba aefa da''ö, ba lalau dorofe, ba mu''ao zato fefu, lamane: Ya ahowu razo Selomo!', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 40, 'Ba la''o''ö ia miyaŵa niha sato fefu ba lalau zurune sato andrö, ba lakaraini wa''iki, ma''ifu tö, ba asila danö, ba wangehegö andrö khöra.', '[]', NULL),
  (3475031, 'OT', 'Razo I', 1, 41, 'Ba irongo Adonia, awö nikaoninia andrö fefu, si so khönia, me no aefa sibai manga ira. Ba me irongo li dorofe andrö Yoabi, ba imane: Hadia zebua li andrö ba fagua-guasa, yomo ba mbanua?', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 42, 'Ba me humede na ia, ba so Yonata andrö, ono Gabiataro ere. Ba imane Adonia: Ae ba da''e, niha si faduhu dödöda ndra''ugö, turia si sökhi ö''ohe khöda!', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 43, 'Ba itema li Gadonia Yonata, imane khönia: Si ndruhu! noa sa ibali''ö razo Zelomo sokhö ya''ita, razo Dawido!', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 44, 'Ba noa sa ibe''e awönia razo Zadoki ere ba Natano sama''ele''ö ba Benaya, ono Yehoyada, awö wazuri andrö; ba no lafakudo ia ba kudo kalide khö razo.', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 45, 'Ba no labayoini razo ia ba Gihona ira Sadoki ere Natano sama''ele''ö, ba no möi ira miyaŵa, moroi ba da''ö, no owua-wua dödö, no tobali humufa mbanua. Da''ö wagua-guasa andrö nirongomi.', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 46, 'Ba no mudadao Zelomo ba dadaoma razo.', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 47, 'Ba noa sa''ae möi genoni razo, ba wamahowu''ö sokhö ya''ita, razo Dawido, wanguma''ö: Yamu''ebua''ö na döi Zelomo Lowalangimö, moroi ba döimö, ba yamu''alaŵa''ö na yaŵa dadaomania, moroi ba dadaomamö andrö! Ba no mangalulu razo ba gasonia.[1]', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 48, 'Ba noa na imane razo: Nisuno Yehowa, Lowalangi Ndraono Gizeraeli, samedadao ba dadaomagu fangaligu, ma''ökhö, ba zanehe hörögu!', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 49, 'Ba tokea fefu nikaoni Gadonia ba maoso ira, ifuli ia khöra zamösana.', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 50, 'Ba ata''u sibai Gadonia Zelomo, ba maoso ia, möi ia mu''olembai dandru andrö ba naha wame''e sumange.', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 51, 'Ba la''ombakha''ö khö Zelomo, lamane: Hiza, no i''olembai dandru ba naha wame''e sumange Adonia, ba wa''ata''unia razo Selomo, ba no imane: Yamöi ba hölu khögu ua razo Selomo, wa lö ifabunu''ö genoninia andre.', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 52, 'Ba imane Selomo: Na niha satulö tödö ia dania, ba sara mbu ba högönia lö atoru ba danö; ba na ta''ila ilau zi lö sökhi, ba si mate ia!', '["MozI 47:31"]', NULL),
  (3475031, 'OT', 'Razo I', 1, 53, 'Ba lahalö ia ba zinga naha wame''e sumange; ba me irugi yomo, ba ifalögu tou ia föna razo Selomo. Ba imane khönia Selomo: Fuli''ö ba khömi!', '["MozI 47:31"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 1, 'Ba me no ahatö wa''amate khö Dawido, ba ibe''e li khö nononia Selomo,', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 2, 'imane: Na utörö sa''ae lala niha fefu, ba abe''e''ö dödöu, ya sabölö ndra''ugö.', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 3, 'O''ö hadia niŵa''ö Yehowa, lala khönia törö, ba o''ö gamakhoitania ba oroisa, awö huku, awö wamaduhu''ö andrö, dali zi so ba zura goroisa Moze, ena''ö mofozu fefu nilaumö ba ena''ö si sökhi lua-lua döröŵamö, gofu heza möi''ö.[1]', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 4, 'Ena''ö itörö niŵa''ö Yehowa, niŵa''önia ba khögu andre, me imane: Na lafaigi-faigi lalara iraonou, na lö faröi ira wanörö lalara fönagu, na a''oi dödöra ba na a''oi gera-erara, ba lö tebulö nga''ötömö ba dadaoma razo ba Ndraono Gizeraeli.[2]', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 5, 'Ba noa göi ö''ila, hadia nilau Yoabi, ono Zeruya, khögu, he iwisa ba gumandra Ndraono Gizeraeli andrö si darua, Abineri, ono Neri, ba Amasa, ono Yeteri, wamunu ya''ira, timba wanuwö, me lö fanuwö, modo mböbö löwi-löwinia ibe''e, do si mane saduwa ba wanuwö, ba he badagahe ba gahenia.[3]', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 6, 'Ba faigi he oŵisa, ba wa''atua-tuamö andrö, ba fa böi atulötulö manö ikhamö narö danö huwania andrö.', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 7, 'Ba iraono Mbarasilai andrö, banua Gileadi, ba öhakhösi tödö, öbe''e sorudu manga khöu ira; si manö sa göi wolaura khögu no, me moloi ndra''o ibe''e Abisalomi.[4]', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 8, 'Ba so na göi khöu ba da''ö Zime''i andrö, ono Gera, mado Mbeniyami, banua Mbahuri: si no mangelifi sibai ya''o da''o, me luo usaŵa Mahana''i. Ba me ifaondragö zui ndra''o furi ö, mitou ba mbewe Yoridano, ba möido ba hölu khönia, khö Yehowa, no umane: Lö ufabunu''ö ndra''ugö![5]', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 9, 'Ba ya''ugö, ba böi zi lö ö''otu''ö ia; noa sa niha satua-tua ndra''ugö ba ö''ila he öwisa khönia, ena''ö togule ndro ba huwania mitou barö danö öbe''e.', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 10, 'Ba mate Dawido, itörö lala ndra tuania, ba lako''o ia ba mbanua Dawido andrö.[6]', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 11, 'Ba fa''ara wamatörö Dawido Iraono Gizeraeli, ba no öfa wulu fakhe; ba Heberona, ba mewitu fakhe, ba ba Yeruzalema, ba tölu ngafulu a tölu.[7]', '["MozV 17:18; Yos 1:7","Sin 132:12","SamII 3:27; 20:10","SamII 17:27","SamII 16:5; 19:23","HalZin 2:29","SamII 5:4"]', NULL),
  (3475032, 'OT', 'Razo I', 2, 12, 'Ba no dumadao ba dadaoma namania Dawido Zelomo, ba itugu aro wa''arazonia.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 13, 'Ba möi yomo khö Mbaseba, ina Zelomo, Gadonia andrö, ono Hagita. Ba imane Baseba: Hadia, ba zi sökhi we''amöimö? Ba imane: Ba zi sökhi.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 14, 'Ba imane khö Mbaseba: So niŵa''ögu khöu. Ba imane: ŵa''ö.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 15, 'Ba imane Adonia: No örongo, wa no khögu wa''arazo, mege, awö wa no ladöna-döna Iraono Gizeraeli ya''odo dania razo, ba he wisa wa''atobalinia dania, wa no khö nakhigu möi wa''arazo, me no Yehowa zangohonogöi khönia.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 16, 'Ba iada''e, ba ha sambalö ni''andrögu khöu; böi zi lö öfondrondrongo khögu! Ba imane khönia: ŵa''ö.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 17, 'Ba imane: Andrö khö razo Selomo — na ya''ugö, ba i''o''ö — ena''ö ibe''e dongagu Gabizagi andrö, banua Zunema.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 18, 'Ba imane Baseba: Lau, fahuhuo ndra''o khö razo, ba ni''andröu andrö.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 19, 'Ba möi yomo khö razo, Selomo Mbaseba, ba huhuo andrö khö Gadonia. Ba maoso razo, ifaondragö ia, ifaöndrö ia föna ninania, ba mudadao ia ba dadaomania; ba labe''e göi dadaoma nina razo, ba mudadao göi ia, ba gambölö razo.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 20, 'Ba imane: So ni''andrögu khöu ma''ifae, böi zi lö öfondrondrongo khögu! Ba imane khönia razo: ŵa''ö manö, ina, lö zi lö ufondrondrongo khöu.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 21, 'Ba imane inania: Ena''ö na labe''e donga ga''au Adonia Gabizagi andrö, banua Zunema.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 22, 'Ba itema li ninania razo Selomo, imane: Ai, hana wa [ha] Abizagi andrö, banua Zunema, ö''andrö khö Gadonia, sökhi manö ödölö wangandrö khönia wa''arazo göi — noa sa atö ga''agu ia — khönia ba khö Gabiataro ere ba khö Yoabi, ono Zeruya.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 23, 'Ba fahölu Zelomo ba khö Yehowa, imane: Yamulau khögu Lowalangi, na tenga si mate Gadonia, me no i''andrö da''ö!', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 24, 'Faya, wa no sauri Yehowa, si no mangaro''ö ya''o ba si no mamedadao ba dadaoma namagu Dawido ya''o, ba si no mame''e satua baomo ndra''odo, dali niŵa''önia andrö, na tenga ma''ökhö andre labunu Gadonia![8]', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 25, 'Ba iŵa''ö li razo, Selomo khö Mbenaya, ono Yoyada; ba da''ö zanaru''ö si''öli khö Gadonia, ba mate ia.', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 26, 'Ba imane razo khö Gabiataro ere andrö: Ae ba Ganatoti ba kabumö andrö, si mate sa ndra''ugö. Ba tenga sa ma''ökhö ubunu ndra''ugö, me no sangosa''ö tawöla Zo''aya, Yehowa, ndra''ugö, sowaö-waö föna namagu Dawido, ba me no ahori göi ötaögö wamakao andrö nitaögö namagu.[9]', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 27, 'Ba tobali itibo''ö Gabiataro andrö Selomo, fa böi sa''ae ere ia khö Yehowa, ena''ö itörö li Yehowa andrö, niŵa''önia ba Zilo no, ba nga''ötö Eli andrö.[10]', '["SamII 7:12","SamI 22:20; SamII 15:24","SamI 2:31 b.t."]', NULL),
  (3475032, 'OT', 'Razo I', 2, 28, 'Ba irongo duria da''ö Yoabi. Noa sa awö Gadonia mege Yoabi, he ŵa''ae lö si möi ia awö Gabisalomi me föna. Ba moloi Yoabi, isaŵa nose Yehowa ba i''olembai dandru andrö ba naha wame''e sumange.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 29, 'Ba la''ombakha''ö khö razo Selomo, lamane: No moloi Yoabi, no isaŵa nose Yehowa, ba i''iagö zinga naha wame''e sumange! Ba ifatenge Mbenaya, ono Yoyada, Selomo, imane khönia: Ae bunu ia!', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 30, 'Ba irugi nose Yehowa Benaya, ba imane khö Yoabi: Da''ö niŵa''ö razo: Ae baero! ba imane: Böi, ba da''e matedo! Ba ifuli khö razo Benaya, imane: Da''ö niŵa''ö Yoabi, da''ö wanemania ligu.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 31, 'Ba imane khönia razo: O''ö niŵa''önia, bunu ia, ba ko''o, ena''ö öheta ba hulugu ba ba hulu nga''ötögu ndro andrö, niduwagö Yoabi lö börö,', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 32, 'ba ena''ö ba hulunia ihare''ö ndronia Yehowa, me no darua ibunu niha satulö moroi khönia ba si sökhi moroi khönia; no ibunu lö nirongo namagu Dawido: Abineri andrö, ono Neri, kumandra Ndraono Gizeraeli, ba Amasa, ono Yeteri, kumandra ma''uwu Yuda.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 33, 'Ba ba hulu Yoabi sa''ae yatohare ndro andrö ba ba hulu nga''ötönia, si lö mamalö-malö, ba ya ahowu khö Yehowa Dawido, awö nga''ötönia, si sawu ya''ira, ba he dadaomania, irugi zi lö aetu!', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 34, 'Ba möi miyaŵa Mbenaya, ono Yoyada, itaru''ö zi''öli khö Yoabi, ibunu; ba ba lewatönia ba danö si mate lako''o ia.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 35, 'Ba Benaya andrö, ono Yoyada, ibe''e fangalinia, högö zabölö, razo; ba Sadoki ere andrö, ba ibe''e fangali Gabiataro. IV.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 36, 'Ba ifatenge razo, ifakaoni''ö Zime''i andrö, imane khönia: Ba Yeruzalema lau nomou, ba ba da''ö iagö, böi manö ofanö ba da''ö, gofu heza.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 37, 'Ba na mofanö''ö, na ö''ötö Gendrona, ba si mate ndra''ugö, böi zi lö aboto ba dödöu; ba hulumö dania so ndromö.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 38, 'Ba imane Sime''i khö razo: Lau, i''o''ö niŵa''ö zokhö ya''o, razo, sawuyumö andre. Ba ba Yeruzalema soso Zime''i, ara ma''ifu.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 39, 'Ba medölu fakhe, ba so zoloi sawuyu Zime''i, darua, lasaŵa Nakhisi andrö, ono Ma''akha, razo Gata. Ba me la''ombakha''ö khö Zime''i: Hiza, ba Gata so zawuyumö andrö!', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 40, 'ba ifosela galidenia Sime''i ba mofanö ia, isaŵa Gata khö Nakhisi, ba wangalui sawuyunia. Irugi Gata ba ihalö zawuyunia ba da''ö.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 41, 'Ba la''ombakha''ö khö Zelomo, no iröi Yeruzalema Sime''i, no möi ba Gata ba no mangawuli ia.', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 42, 'Ba ifatenge razo, ifakaoni''ö Zime''i, ba imane khönia: Hadia, tenga no ube''e ba hölu ndra''ugö khö Yehowa, ba tenga no uŵa''ö khöu: Ha si''ai mofanö ndra''ugö heza, ba si mate ndra''ugö — böi zi lö aboto ba dödöu? Ba no ömane khögu: Lau, urongo!', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 43, 'Ba hana sa, wa no olifu''ö wa no möi''ö ba hölu ba khö Yehowa, ba hana wa lö ö''o''ö goroisa andrö, nibe''egu khöu?', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 44, 'Ba imane na razo khö Zime''i: No ö''ila zi lö sökhi andrö fefu, nitegu dödöu ya''ugö, nilaumö khö namagu Dawido. Ba yamuhare''ö ba hulumö horöu andrö Yehowa:', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 45, 'ba ya ahowu razo Selomo, ba ya''aro dadaoma Dawido andrö, föna Yehowa, irugi zi lö aetu!', '[]', NULL),
  (3475032, 'OT', 'Razo I', 2, 46, 'Ba ibe''e li khö Mbenaya, ono Yoyada, razo; ba möi tou da''ö, itaru''ö zi''öli khö Zime''i, ba mate ia.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 1, 'Ba me aro sa''ae wa''arazo ba danga Zelomo,[1] ba ifakhai si tengabö''ö Wara''o, razo Miserayi. Ihalö nono Wara''o, i''ohe ba mbanua Dawido, gasa-gasa wolaunia gödonia ba osali Yehowa, awö wangasiwai öli Yeruzalema, öli kara.[2]', '["Ayati 1—4: Nga''ötII 1:1—6","Faigi 7:8","SamI 9:12; Nga''ötI 21:29"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 2, 'Ba hili-hili na mame''e sumange zato, irugi da''ö, ba lö''ö na sa mulau nahia döi Yehowa.', '["Ayati 1—4: Nga''ötII 1:1—6","Faigi 7:8","SamI 9:12; Nga''ötI 21:29"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 3, 'Ba Selomo, ba i''omasi''ö Yehowa, i''o''ö nifakhoi namania Dawido, ha fa ba hili-hili na göi mame''e sumange ia ba manunu kumöyö.', '["Ayati 1—4: Nga''ötII 1:1—6","Faigi 7:8","SamI 9:12; Nga''ötI 21:29"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 4, 'Ba möi ba Gibeona razo, ba wame''e sumange ba da''ö, me no da''ö gamaedola zi a''a hili-hili andrö. Hönö nga''eu sumange ibe''e Selomo ba naha wame''e sumange andrö.[3]', '["Ayati 1—4: Nga''ötII 1:1—6","Faigi 7:8","SamI 9:12; Nga''ötI 21:29"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 5, 'Ba i''oroma''ö ia Yehowa khö Zelomo, ba Gibeona, ba zi bongi, ba wangifi.[4] Ba imane Lowalangi: andrö hadia nibe''egu khöu.[5]', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 6, 'Ba imane Selomo: No ebua sibai dödöu khö genoniu andrö, amagu Dawido, ba noa sa göi itörö lalania, sanehe ndra''ugö, lö si faröi ia ba no satulö tödö ia ba sadölö era-era khöu; ba no lö nibulö''öu khönia fa''ebua dödö andrö, wame''e ono matua khönia, sidadao ba dadaomania, si mane ma''ökhö.', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 7, 'Ba hiza, ya''ugö Yehowa, Lowalangigu, no öbali''ö razo genoniu andre, fangali namagu Dawido. Ba ya''o, ba iraono, lö u''ila he wisa wofanö ba lö u''ila he wisa wangawuli.', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 8, 'Ba no so ba hunö mbanuau genoniu andre, ba hunö mbanuamö andrö, nituyumö, banua sebua andrö, si lö mutaha mu''erai, ba wa''ato, ba si tebai ta''ofaya.', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 9, 'Ba ena''ö na öbe''e khö genonimö andre dödö samondrongo li, ena''ö tola ifatörö mbanuamö andrö ba ena''ö i''ila hadia zi sökhi ba hadia zi lö sökhi. Ha niha sa zangila mamatörö banuamö andrö, si no ato sibai?', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 10, 'Ba omasi Zo''aya, me da''ö ni''andrö Zelomo.', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 11, 'Ba imane khönia Lowalangi: Me no da''o ni''andröu, ba me tenga fa''anau noso ba tenga fa''ebua gana''a ba tenga fa''amate zi fa''udu khöu ö''andrö, me no fa''atua-tua ni''andröu, ba wamondrongo si duhu,', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 12, 'ba u''o''ö ni''andröu andrö: ube''e khöu dödö satua-tua si so era-era, ena''ö lö famaedou, he ba götö mege ba he ba götö dania.[6]', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 13, 'Ba ube''e göi khöu zi tenga ni''andröu, he fa''ebua gana''a ba he fa''ebua döi, ena''ö lö famaedou ba zalaŵa, götö wa''anau nosou.[7]', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 14, 'Ba na ötörö lala andrö khögu, na ö''o''ö nifakhoigu andrö ba oroisagu, si mane fanörö namau Dawido mege, ba ube''e göi khöu wa''anau noso.', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 15, 'Ba me tokea Zelomo, ba hiza, ba fangifi. Ba me no irugi Yeruzalema, ba möi ia föna dawöla zura goroisa Yehowa, mame''e sumange ia, sumange nitunu ba sumange fangorifi; ba ibe''e gö genoninia fefu.', '["Ayati 3:5—13: Nga''ötII 1:7—12","Faigi 9:2","Sangomb 1:16","Mat 6:33"]', NULL),
  (3475033, 'OT', 'Razo I', 3, 16, 'Ba darua zi möi khö razo, me luo da''ö, ira alawe sohorö, la''ondrasi ia.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 17, 'Ba imane si samösa: He Tua, no oruduga yomo galawe da''e, ba mo''ono ndra''o ba zi so ia, yomo ba da''ö.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 18, 'Ba tölu bongi aefa wadonogu, ba madono göi galawe da''e; no orudu ndra''aga, ba lö khöma niha bö''ö yomo, ha ya''aga, daruaga.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 19, 'Ba mate nono galawe da''e, ba zi bongi, noa sa ilangö ba wemörö.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 20, 'Ba maoso ia, me talu mbongi, ihalö nonogu ba ngaigu, me no mörö zawuyumö andre, ba ifaförö ba ngainia; ba ononia si no mate, ba ibe''e ba ngaigu.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 21, 'Ba me maoso ndra''o me moluo, ba wamaenu onogu, ba hiza, ba no mate. Be me no ufaigi sibai, me no abölö moluo, ba hiza, ba no tenga onogu, ni''adonogögu.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 22, 'Ba imane ira alawe si sambua: Faya, onogu zauri, ba onou zi mate! Ba imane si samösa: Fayau, onou zi mate ba onogu zauri! Ba fagua-gua ira ba da''ö, föna razo.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 23, 'Ba imane razo: Niŵa''ö da''e, ba: Onogu da''ö, sauri, ba onou zi mate! Ba niŵa''ö da''ö, ba: Faya, onou zi mate, ba onogu zauri!', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 24, 'Ba imane na razo: Mihalö khögu wöda! Ba me la''ohe khö razo wöda andrö, ba imane:', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 25, 'Misila nono andrö, sauri, ba tambai ba da''e ba tambai ba da''ö mibe''e.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 26, 'Ba humede ndra alawe andrö, sauri ono, khö razo — me no ahakhö sibai dödönia nononia — imane: He Tua, mibe''e manö auri khönia nono andrö, ba böi mibunu! Ba imane si samösa: Böi möi khögu, ba böi möi khöu: misila!', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 27, 'Ba itema linia razo, imane: Sanguma''ö mege: Mibe''e manö auri khönia nono andrö, ba böi mibunu! — da''ö ninania.', '[]', NULL),
  (3475033, 'OT', 'Razo I', 3, 28, 'Ba me larongo wangetu''ö huku andrö khö razo Iraono Gizeraeli fefu, ba la''ata''ufi razo, me aboto ba dödöra, so khönia wa''atua-tua Lowalangi, ba wamatörö huku satulö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475034, 'OT', 'Razo I', 4, 1, 'Ba razo ba Ndraono Gizeraeli fefu sa''ae Zelomo.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 2, 'Ba da''e högö genoninia: Ere Gasariya andrö, ono Zadoki.[1]', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 3, 'Ba durutuli Gelihorefi ba Ahiya, faoma ono Zisa. Ba sa''asa sebua Yozafati, ono Gahiludi.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 4, 'Ba Benaya andrö, ono Yoyada, ba kumandra zabölö. Ere göi Zadoki ba Abiataro.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 5, 'Ba Asaria, ono Natano, ba no mufataro högö gumandru. Ba Sabudu, ono Natano, ba ere ba si fahuwu khö razo.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 6, 'Ba Ahisari, ba mandru ba gödo, ba Adonira, ono Gabada, ba mandru rodi.[2]', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 7, 'Ba felendrua khö Zelomo gumandru, ba Ndraono Gizeraeli fefu. Da''ö zama''ema balazo khö razo ba ba zoroiyomonia fefu, sara-sara waŵa zamösa ba zi döfi.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 8, 'Ba da''e döira: Ono Huri ba hili mado Geferayi; ba ono Dekeri ba Makasi,', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 9, 'numalö ba Za''alabi ba ba Mbeti Zemesi ba ba Elono, irugi Mbeti Hanana;', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 10, 'ba ono Hezedi ba Garuboti, khönia göi Zokho ba tanö Heferi, ma''afefu;', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 11, 'ba ono Gabinadabi ba Nafata Dora, ma''asagörö; fo''omonia Dafata, ono Zelomo.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 12, 'Ba Ba''ana, ono Gahiludi, ba Da''anakha ba ba Megido ba ba Mbeti Zeana ma''asagörö, ba ngai Zaretana, tou Yezere''eli, i''otarai Mbeti Zeana, numalö ba Habeli Mehola, irugi ba zi tambai Yokemea;', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 13, 'ba ono Geberi ba Ramoti, ba danö Gileadi, khönia mbanua Ya''iro andrö, ono Manase, ba danö Gileadi ba khönia göi danö Garagoba ba Mbazana, 60 mbanua sebua, banua nifo''öli ba nifolazi töla;[3]', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 14, 'ba Ahinadabi, ono Ido, ba Mahana''i;', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 15, 'ba Ahimasi ba mado Nafetali; fo''omonia, ba ono Zelomo göi, Basimata andrö.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 16, 'Ba Ba''ana, ono Huza''i, ba mado Gaseri ba ba Mbealoti;', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 17, 'ba Yozafati, ono Warua, ba mado Isasari;', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 18, 'ba Sime''i, ono Ela, ba mado Mbeniyami;', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 19, 'ba Geberi, ono Guri, ba danö Gileadi, ba danö Zihona andrö, razo Ndraono Gamori, ba ba danö Ogi, razo Mbazana.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 20, 'Ba ma''uwu Yuda ba Iraono Gizeraeli, ba no ato sibai, timba wa''oya ngawua nene ba mbewe nasi, ba si manga-manga ira ba somuso tödö.', '["Faigi 2:35","Faigi 12:18","MozIV 32:41"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 21, 'Ba razo sa''ae Zelomo ba gamatöröŵa razo fefu, i''otarai mboto Oifarati, irugi danö Miserayi; la''ohe zumange ba barö bawa Zelomo ira, sagötö ya''ia.[4]', '["MozI 5:18; Sin 72:8","MozIII 26:5; Mikh 4:4","MozV 17:16 b.t."]', NULL),
  (3475034, 'OT', 'Razo I', 4, 22, 'Ba balazo Zelomo ma''ökhö, ba 12 fiku hamo si sökhi ba 24 fiku hamo bö''ö,', '["MozI 5:18; Sin 72:8","MozIII 26:5; Mikh 4:4","MozV 17:16 b.t."]', NULL),
  (3475034, 'OT', 'Razo I', 4, 23, 'ba 10 nga''eu saŵi nibula ba 20 nga''eu saŵi nikubaloi, ba 100 nga''eu biri-biri, lö lai mböhö ba nago ba laosi ba bebe ba manu, satabö.', '["MozI 5:18; Sin 72:8","MozIII 26:5; Mikh 4:4","MozV 17:16 b.t."]', NULL),
  (3475034, 'OT', 'Razo I', 4, 24, 'Noa sa möi barö mbawania fefu, irugi mbewe Oifarati, i''otarai Difisa, numalö ba Gasa, fefu razo, irugi mboto Oifarati; ba lö''ö manö famadöni, fasui.', '["MozI 5:18; Sin 72:8","MozIII 26:5; Mikh 4:4","MozV 17:16 b.t."]', NULL),
  (3475034, 'OT', 'Razo I', 4, 25, 'Tobali ahono manö ma''uwu Yuda ba Iraono Gizeraeli, barö ŵeŵe nagu khönia ba barö marafalania so zamösana, i''otarai Dano, numalö ba Mbereseba, götö wa''anau noso Zelomo.[5]', '["MozI 5:18; Sin 72:8","MozIII 26:5; Mikh 4:4","MozV 17:16 b.t."]', NULL),
  (3475034, 'OT', 'Razo I', 4, 26, 'Ba 40.000 khö Zelomo kudo gureta ba 12.000 nifake ba wakudosa.[6]', '["MozI 5:18; Sin 72:8","MozIII 26:5; Mikh 4:4","MozV 17:16 b.t."]', NULL),
  (3475034, 'OT', 'Razo I', 4, 27, 'Ba kumandru andrö ba samaigi balazo razo Selomo, fabaya balazo zi manga-manga khönia, sara-sara waŵa zamösa; lö labe''e ambö hadia ia.', '["MozI 5:18; Sin 72:8","MozIII 26:5; Mikh 4:4","MozV 17:16 b.t."]', NULL),
  (3475034, 'OT', 'Razo I', 4, 28, 'Awö gandru ba töla gandru, soguna ba kudo gureta ba ba kudo ba wakudosa, ba la''ohe ba zi so razo, na inötö ba zamösana.', '["MozI 5:18; Sin 72:8","MozIII 26:5; Mikh 4:4","MozV 17:16 b.t."]', NULL),
  (3475034, 'OT', 'Razo I', 4, 29, 'Ba ihöna khö Zelomo wa''atua-tua Lowalangi ba fa''aboto ba dödö, ba fotödö ihöna khönia, timba nene ba mbewe nasi,', '["Nga''ötI 2:6; Sin 89:1"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 30, 'tobali abölö wa''atua-tua Zelomo, moroi ba wa''atua-tua niha bö''ö fefu, tanö ba gatumbukha luo ba moroi ba wa''atua-tua Ndrawa Miserayi fefu.', '["Nga''ötI 2:6; Sin 89:1"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 31, 'Ba no atua-tua ia, moroi ba niha bö''ö fefu, he Etano andrö, ma''uwu Zera, ba he Hemano ba Khalikoli ba Darada, ono Maholi, ba teturia ia ba niha baero, fasui.[7]', '["Nga''ötI 2:6; Sin 89:1"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 32, 'Tölu ngahönö ilau amaedola, ba sinunönia, ba no lima töra hönö.', '["Nga''ötI 2:6; Sin 89:1"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 33, 'Iwawakha''ö he wisa ngawalö geu, i''otarai geresi ba hili Libano, numalö ba zufa, si tumbu ba göli kara. Ba ifatunö he wisa zaliŵa-liŵa ba danö ba fofo ba kuö-kuö ba i''a.', '["Nga''ötI 2:6; Sin 89:1"]', NULL),
  (3475034, 'OT', 'Razo I', 4, 34, 'Ba dozi soi, ba möi, ba wamondrondrongo fa''atua-tua Zelomo, sinenge zalaŵa ba guli danö fefu, ba zi no teruria wa''atua-tuania andrö.', '["Nga''ötI 2:6; Sin 89:1"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 1, 'Ba ifatenge khö Zelomo genoninia Hiramo andrö, razo Diro;[1] me no irongo no labayoini razo Zelomo, fangali namania. Sagötö fa''ara, ba no si fehuwu sibai khö Dawido Hiramo andrö.[2]', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 2, 'Ba ifatenge khö Hiramo Selomo, imane khönia:', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 3, 'No örongo, wa no tebai ilau nomo döi Lowalanginia Yehowa amagu Dawido, börö wanuwö-nuwö andrö si tefasui ya''ia, irege ibe''e barö gahenia ira Yehowa.[3]', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 4, 'Ba no ahono manö fasui, ibe''e khögu Lowalangigu, Yehowa, tobali lö''ö sa''ae si fa''udu ba lö''ö sa''ae si fatimba.', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 5, 'Ba no uŵa''ö tödögu ulau nomo döi Lowalangigu, Yehowa, dali niŵa''ö Yehowa khö namagu Dawido, me imane: Onou andrö, nifedadaogu dania ba dadaomamö, fangaliu, da''ö dania zolau omo döigu![4]', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 6, 'Ba ŵa''ö sa''ae, ena''ö lalau khögu geresi ba hili Libano, ba akha fao ba genoniu genonigu; ba ya''o zame''e luo genoniu, dali manö nifatömö. Noa sa''ae ö''ila, wa samösa lö ba khöma sangila molau eu, si mane banua Zidona andrö.', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 7, 'Ba me irongo niŵa''ö Zelomo Hiramo, ba omuso sibai dödönia, ba imane: Nisuno Yehowa ma''ökhö, si no mame''e ono satua-tua khö Dawido, högö soi sebua andrö!', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 8, 'Ba ifatenge khö Zelomo Hiramo, imane: No urongo niŵa''öu khögu. Ba ya''odo, ba ahori u''asogö hadia zomasi''ö töla geresi ba töla zenobari.', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 9, 'Akha la''ohe mitou ba mbewe nasi enonigu, moroi ba hili Libano, ba ya''o zanguma''ö forake ya''ia, irugi mbanua niŵa''öu khögu, ba ba da''ö, ba uŵa''ö wanudugö, ena''ö ya''ugö zamahalö''ö. Ba ya''ugö, ba ö''o''ö ni''andrögu, öbalazoi ndra''aga, ya''aga si samba omo.', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 10, 'Ba ifa''ema khö Zelomo döla geresi ba töla zenobari Hiramo, ha wa''oya zomasi ia.', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 11, 'Ba Selomo, ba ifa''ohe''ö khö Hiramo, ba 40.000 fiku gandru ba 4000 fiku fanikha mbua zai nifufu, balazora, ya''ira si samba omo. Ero röfi ifa''ohe''ö da''ö khö Hiramo Selomo.', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 12, 'Ba no ibe''e wa''atua-tua khö Zelomo Yehowa, itörö nifabu''unia khönia mege. Ba ha sara dödöra Hiramo Zelomo, ba fawu''u li ira.', '["Ayati 1—16: Nga''ötII 2","SamII 5:11; Nga''ötII 2:3 b.t.","Nga''ötI 28:3","Nga''ötI 22:10"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 13, 'Ba i''ofaya zohalöŵö rodi Selomo, ba Ndraono Gizeraeli fefu, ba fa''ato zi göna rodi andrö, ba 30.000.', '["Faigi 4:6","Hez 27:9"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 14, 'Ba ifalalilali wamatenge ya''ira ba hili Libano, sara-sara waŵa, ba fulufulu ngahönö; tobali sara-sara waŵa ira ba hili Libano ba dua-dua waŵa ba khöra. Ba Adonira mandru ba rodi andrö.[5]', '["Faigi 4:6","Hez 27:9"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 15, 'Ba 70.000 khö Zelomo sonoro ba 80.000 zanoto kara ba hili, lö lai högöra ba mandru,', '["Faigi 4:6","Hez 27:9"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 16, 'khö Zelomo, satua zangai halöŵö, 3.300 da''ö, samaigi-maigi niha andrö, sohalöŵö.', '["Faigi 4:6","Hez 27:9"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 17, 'Ba iŵa''ö razo wamo''a kara sebua, si sökhi, kara nitoto, toyo gosali andrö dania.', '["Faigi 4:6","Hez 27:9"]', NULL),
  (3475035, 'OT', 'Razo I', 5, 18, 'Ba manoto-noto duka andrö khö Zelomo, la''asiwai mbalo, awö gara, ba wolau osali dania.[6]', '["Faigi 4:6","Hez 27:9"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 1, 'öfa ngaotu a ŵalu ngafulu fakhe i''otarai wa''aheta Ndraono Gizeraeli ba danö Miserayi ba no alua medölu fakhe razora Zelomo,[1] me ifobörö wolau osali andrö khö Yehowa, ba mbaŵa Sifi, baŵa si dua.[2]', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 2, 'Ba osali andrö, nilau razo Selomo, ba 60 hela wa''anau ba 20 hela wa''ebolo ba 30 hela wa''alaŵa.', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 3, 'Ba ewe''ewe andrö, föna zi ndruhu nomo, ba no 20 hela wa''anau, dali wa''ebolo gosali, ba 10 hela wa''ebolo, föna gosali.[3]', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 4, 'Ba ifosandrela gosali, nifotarali.', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 5, 'Ba baero mbagolö, ba isahe na, fasui, ifasui gosali, awö nifo''oto''oto andrö, tanö furi, ibali''ö bate''e baero, fasui.', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 6, 'Si sagötö zahe-sahe andrö, tanö tou, ba 5 hela wa''ebolo, ba si sagötö, fanete, ba 6 hela ba si sagötö tanö yaŵa, ba 7 hela; noa sa ibosi mbagolö tanö baero, fasui, fa böi tefa''a ba mbagolö.', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 7, 'Ba me la''otomosi gosali andrö, ba kara si no mudölö mutoto mege, me labo''ai, lafa''anö, tobali lö murongo li wakake si''öli ba wotomo andrö, he farökha ba he fahö.', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 8, 'Ba bawandruhö ba zi sagötö tanö tou, ba ngai, ba tanö raya so, ba ora miyaŵa ba zi tatalu, ba ba zi sagötö tanö yaŵa.', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 9, 'Ilau sa''ae gosali andrö ba i''asiwai; ba sagö gosali fafa, ba gasö matua, ba oi eresi.', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 10, 'Ba ilau zahe-sahe andrö, ba gosali ma''afefu (fasui), lima hela zagötö, wa''alaŵa, ba ifaböbö ba gosali buatö eresi.', '["Faigi göi Nga''ötII 3:1—13","HalZin 7:47","Yoh 10:23"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 11, 'Ba humede Yehowa khö Zelomo,', '["SamII 7:12"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 12, 'imane: Ba gosali andrö, nilaumö: Na ötörö nifakhoigu andrö ba na ö''o''ö huku khögu ba na ötöngöni goroisagu, ba wanörö ya''ia, ba utörö khöu niŵa''ögu, fehedegu khö namau Dawido,', '["SamII 7:12"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 13, 'ba ba hunö Ndraono Gizeraeli u''iagö, ba lö u''erogö mbanuagu, Iraono Gizeraeli.[4]', '["SamII 7:12"]', NULL),
  (3475036, 'OT', 'Razo I', 6, 14, 'Ba ilau gosali andrö Selomo ba i''asiwai.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 15, 'Ba bagolö tanö bakha ba gosali, ba bagolö eresi ibe''e, i''otarai zalo, irugi narö zagö ibalugö bagolö, tanö bakha. Ba fafa zalo tou, ba senobari.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 16, 'Ba ibalugö fafa eresi zi 20 hela andrö, tanö ba hambo gosali (tanö bakha), i''otarai zalo, numalö barö zagö; ba da''ö ilau zi hulö mbate''e ba hambo, fondrege ni''amoni''ö andrö.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 17, 'Ba 40 hela wa''anau zi hulö dalu zalo, föna wondrege ni''amoni''ö andrö.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 18, 'Ba bagolö eresi tanö bakha, nisua, la''izu ndru''u ba bunga; oi eresi; lö oroma kara.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 19, 'Ba tanö bakha ilau wondrege ni''amoni''ö andrö, ena''ö ba da''ö labe''e dawöla zura goroisa Yehowa.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 20, 'Ba föna wondrege ni''amoni''ö andrö, si 20 hela fa''anau ba 20 hela fa''ebolo ba 20 hela fa''alaŵa, nifo''uli balaki, ifazökhi naha wame''e sumange, eresi.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 21, 'Ba tanö bakha, ba ifo''uli balaki gosali Selomo, ba ifatörö rate balaki föna wondrege ni''amoni''ö andrö, nifo''uli balaki göi.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 22, 'Osali ma''asambua ifo''uli balaki, fatutu; ba he naha wame''e sumange andrö föna wondrege ni''amoni''ö, ba ifo''uli balaki, ma''asambua.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 23, 'Ba ba wondrege ni''amoni''ö andrö, ba dombua ifazökhi Kerubi, eu, töla zai, fulu hela wa''alaŵa.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 24, 'Lima hela wa''anau gafi Kerubi si sambua, ba lima hela göi gafi zi sambua, tobali fulu hela, i''otarai mbalö gafinia si sara, numalö ba mbalö zi sara.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 25, 'Ba fulu hela göi Kerubi si sambua; faoma manö Kerubi si dombua, he nga''eu, ba he fa''ebua.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 26, 'Faoma fulufulu hela wa''alaŵa Kerubi andrö, si dombua.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 27, 'Ba bakha ba wondrege ni''amoni''ö andrö ibe''e Kerubi andrö, ba no nibologö gafira, tobali irugi mbagolö ba zi tambai afi zi sambua, ba ba mbagolö ba zi tambai irugi afi zi sambua, ba ba dalu ba faondra gafi.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 28, 'Ba ifo''uli balaki Kerubi andrö.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 29, 'Ba ba mbagolö gosali, fasui, ba ifasua''ö Kerubi ba ohi ba bunga, bakha ba wondrege ni''amoni''ö ba baulu.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 30, 'Ba salo gosali göi, ba ifo''uli balaki, bakha ba wondrege ni''amoni''ö ba baulu.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 31, 'Ba bawandruhö wondrege ni''amoni''ö, ba ifolagö [eu] zai. Ba lesi mbawandruhö ba ehomo fatambai, ba no ni''olima sagi.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 32, 'Ba ba lagö mbawandruhö zai andrö, si dua görö, ba ifasua''ö Kerubi ba ohi ba bunga, ba ifo''uli balaki Kerubi andrö ba ohi, balaki niböbözi, ni''anifi''ö.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 33, 'Ba he ba mbawandruhö baulu, ba ifalau''ö gehomo zai, si öfa sagi,', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 34, 'ba dua görö lagö, senobari, ba faoma no mutaba dalu, tobali dua-dua görö nifuyu''ö.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 35, 'Ba ifasua''ö Kerubi ba ohi ba bunga, ba ifo''uli balaki, si fatöfa ba nisua andrö.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 36, 'Ba ikölini golayama fönaföna gosali, tölu winaeta kara si öfa sagi ba sawinaeta balo eresi.', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 37, 'Ba ndröfi si öfa, ba mbaŵa Sifi tebe''e tou doyo gosali Yehowa andrö,', '[]', NULL),
  (3475036, 'OT', 'Razo I', 6, 38, 'ba ba ndröfi si felezara, ba mbaŵa buli, baŵa si ŵalu, ba te''asiwai gosali, fefu hadia ia zi faböbö khönia, he wisa wolau ya''ia, tobali mewitu fakhe i''olau''ö.', '[]', NULL),
  (3475037, 'OT', 'Razo I', 7, 1, 'Ba gödonia andrö, ba meweledölu fakhe i''olau''ö Selomo, irege maulu wa''awai.[1]', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 2, 'Eu gatua ba hili Libano nomo andrö, 100 hela wa''anau ba 50 hela wa''ebolo, ba 30 hela wa''alaŵa; tölu ngenoli gehomo eresi, moroi tou ba buatö eresi ba mbalö gehomo.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 3, 'Ba sagö, ba eresi, yaŵa mbate''e ba hambo; si tohare ba gehomo andrö, ehomo si 45, felefelelima zangenoli.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 4, 'Ba tölu winaeta mbuatö, ba sandrela, ba no fatahö, tölutölu ngenoli.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 5, 'Ba bawandruhö ba sandrela fefu, ba no si öfa sagi, eu balo, ba si fatahö zandrela, tölutölu ngenoli.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 6, 'Ba ilau zerambi, ni''otarunahe gehomonia, 50 hela wa''anau ba 30 hela wa''ebolo, ba sambua tö zerambi föna da''ö, nifo''ehomo si manö göi, ba nibosi mbalö.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 7, 'Ba sambua zeri balai, naha dadaoma, ba nifatunö huhuo, seri balai wanguhuku, ilau, oi nibalugö bagolö eresi, tanö bakha; i''otarai zalo, numalö barö zagö.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 8, 'Ba omonia, nahiania, ba golayama si sambua, misa, i''otarai zerambi no mege, ba si manö göi wolau. Ba khö nono Wara''o andrö nihalönia, ba ilau göi nomo Selomo, buata zerambi andrö?[2]', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 9, 'Ba [omo] andrö fefu, ba kara sebua böli, nibana ba wanoto, nigaragazini, he tanö bakha ba he tanö baero, i''otarai doyo tou, numalö barö zagö, ba tanö baero, irugi golayama sebolo andrö.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 10, 'Ba toyo tou, ba no kara sebua böli, kara sebua, so zi 10 hela ba so zi 8 hela.', '["Faigi 10:17","Faigi 3:1"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475037, 'OT', 'Razo I', 7, 11, 'Ba miyaŵa, ba kara sebua böli, nifatörö siku ba wanoto, ba eu, eresi.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 12, 'Ba öli golayama sebolo andrö, fasui, ba tölu winaeta gara si öfa sagi ba sawinaeta geu balo, eresi, si mane olayama gosali Yehowa, tanö bakha, ba si mane olayama zerambi andrö ba gödo.', '["Faigi 10:17","Faigi 3:1"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 13, 'Ba ifatenge ba Diro razo Selomo, ifakaoni''ö Hiramo andrö, banua Diro.[3]', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 14, 'Ono lakha mbanua, mado Nafetali Hiramo andrö, ba amania, ba banua Diro; siambu ia, tuka döla, si fahöna fa''onekhe, awö wa''atua-tua, awö wa''aboto ba dödö, ba wolau hadia ia, töla. Ba möi ia khö razo, ilau nilau andrö khönia fefu.[4]', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 15, 'Ifahele daru nahe andrö, si dua, töla, ba gewe''ewe andrö ba gosali.[5] Feleŵalu hela wa''alaŵa daru nahe andrö ba daöfa manalagu wa''esolo, ni''okowu, öfa turu wa''awe''e-we''e; si fagölö-gölö manö zi dua andrö.[6]', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 16, 'Ba dombua ilau högö, nifahele, töla, högö daru nahe andrö; faoma limalima hela wa''alaŵa högö andrö.', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 17, 'Ba ifazökhi zi hulö ni''otaraŵa, raeŵe-raeŵe, amaedola mbalu-balu högö daru nahe andrö, faoma ma''adombua ibe''e ni''otaraŵa si manö.', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 18, 'Ba ifazökhi wamaedo mbua dalimo, töla, dua-dua winali wamaedo mbua dalimo zambua ni''otaraŵa.', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 19, 'Ba 200 wamaedo mbua dalima zambua ni''otaraŵa, fasui, ni''ofinaligö, ifagölö-gölö manö wolau ba högö daru nahe si dombua.', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 20, 'Ba högö daru nahe andrö, ba no famaedo mbunga zömasöma safusi, öfa hela.', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 21, 'Ba ifasindro daru nahe andrö ewe''ewe gosali; ifasindro zi sara ba gambölö, ba ibe''e töinia Yakhino, ba si sara, ba gabera, ba Boasi ibe''e töi da''ö.', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 22, 'Ba högö daru nahe andrö, ba no famaedo mbunga zömasöma safusi. Ba awai wolau taru nahe andrö.', '["Nga''ötII 2:13,14","MozII 31:3","Ayati 15—21: Nga''ötII 3:15—17","RazII 25:17"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 23, 'Ba ifazökhi gala sebua andrö, nifahele, 10 hela wa''ebolo mbawa, no owulo, ba 5 hela wa''alaŵa, dafulu manalagu wa''ebua.[7]', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 24, 'Ba tou mbewenia, ba famaedo la''izu ndru''u, fulu hela, fasui, dua winali, nidölö famahele mege.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 25, 'Ba fa''awe''e-we''e gala, ba lalu''a, ba bewenia, ba si mane bewe mako, no famaedo mbunga zömasöma safusi; ba ösinia, ba 266 ngaso''e idanö.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 26, 'Felendrua wamaedo zaŵi zolu''i, 3 tanö miyou, ba 3 tanö ba gaekhula luo ba 3 tanö miraya ba 3 tanö ba gatumbukha. Ba si tohare ba hulura gala andrö, ba oi mibakha doyora.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 27, 'Ba ifazökhi göi dayadaya andrö, töla, fulu fefu, öfa hela wa''anau ba öfa hela wa''ebolo ba tölu hela wa''alaŵa.[8]', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 28, 'Ba si mane wamazökhi dayadaya andrö:', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 29, 'Nifolesi ngai, ba ba ngai andrö, nifasui lesi, ba famaedo zingo ba famaedo zaŵi ba famaedo Kerubi; ba si manö göi ba lesi andrö. Ba he yaŵa zingo andrö ba yaŵa zaŵi ba he tanö tou, ba bunga ni''oraeŵe-raeŵe nifanaŵanaŵa.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 30, 'Ba öfa roda zambua dayadaya, ba döladöla roda, ba töla. Ba nifo''alisi watalinga si öfa. Amaedola galisi, nifahele, daoma-daoma mbalanga andrö.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 31, 'Ba sobawa daoma-daoma andrö, ba sowulo mbawania, sahela a matonga wa''eŵaŵa; ba nisua göi da''ö; ba lesinia, ba si öfa sagi, tenga sowulo.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 32, 'Ba tou lesi roda andrö, si öfa. Ba döladöla roda, ba no nifaböbö ba nösi dayadaya andrö. Ba fa''alaŵa roda, ba sahela a matonga.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 33, 'Ba no nifolau roda gureta roda andrö. Ba he döladölania ba he ösinia ma''afefu, ba oi nifahele.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 34, 'Ba watalinga si öfa, ba si hulö galisi, nidölö famahele ba nösi.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 35, 'Ba ba dete dayadaya andrö, ba si hulö daoma-daoma, 1/2 hela wa''alaŵa, fasui, ni''owuloi''ö: Ba dete dayadaya andrö so daoma-daoma andrö, si so sekhesekhe mbalanga, nidölö famahele mege ba ngainia andrö ba ba lesinia.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 36, 'Ba ba wolowolo ngainia andrö, ba isua Kerubi ba singo ba ohi, ha wa''oya zonaha ba zi sagö-sagörö; ba bunga ni''oraeŵe-raeŵe, fasui.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 37, 'Si manö wamazökhi dayadaya andrö, si fulu si faoma famahele ba si faoma fa''ebua ba si faoma nga''eu.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 38, 'Ba fulu göi ifazökhi balanga töla; 5 zo''e nösi zi sambua balanga, öfa hela wa''eŵaŵa mbawa. Sambu-sambua mbalanga ba dayadaya si fulu andrö.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 39, 'Ba lima ibe''e tanö raya gosali ba lima tanö yöu, dayadaya andrö; ba gala sebua andrö, ba tanö ba gambölö ibe''e, tanö föna, tanö miraya.', '["Ayati 23—26: Nga''ötII 4:2—5","Ayati 27—39: Nga''ötII 4:6—10"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 40, 'Ba ifazökhi mbowoa ba sundrusundru ba figa Hiramo andrö ba i''asiwai nilau andrö fefu,[9] nilaunia khö Zelomo ba gosali Yehowa andrö:', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 41, 'Taru nahe andrö, si dua, ba högö daru nahe, ni''owuloi''ö, si dombua ba ni''otaraŵa andrö, balu-balu högö daru nahe andrö —', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 42, 'ba famaedo mbua dalimo andrö, si 400, ba ni''otaraŵa andrö, si dombua, si dua winali zambua ni''otaraŵa, balu-balu högö daru nahe andrö, si dombua;', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 43, 'awö dayadaya andrö, si fulu, fabaya balanga andrö si fulu ba dayadaya andrö; ba gala sebua andrö,', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 44, 'si ha sambua ba saŵi andrö, si felendrua, solu''i gala andrö;', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 45, 'ba bowoa andrö ba sundrusundru ba figa. Ba gama-gama andrö fefu, nifazökhi Hiramo andrö khö razo Selomo, ba gosali Yehowa andrö, ba no töla ni''alösöigö.', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 46, 'Ba ndraso Yoridano ifafahele''ö razo, ba golabuta tanö, ba gotaluara Zukota Zaretano.', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 47, 'Ba lö itulo gama-gama andrö fefu Selomo, börö me no oya sibai; lo muhonogöi wa''abua döla andrö.', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 48, 'Ba ifafazökhi''ö Selomo gama-gama andrö fefu,[10] si so ba gosali Yehowa dania: naha wame''e sumange andrö, ana''a, awö meza andrö, ana''a, si so yaŵa roti nifaigi-faigi andrö,[11]', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 49, 'awö naha wandru andrö, lima ga gambölö ba lima ba gabera, naha wandru ana''a, föna wondrege ni''amoni''ö, ba famaedo mbunga andrö ba fandru ba guti wandru, ana''a,', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 50, 'ba figa sebua ba rosö, ba figa side-ide ba mako ba gali, balaki. Ba izi lagö mbawandruhö andrö, si dua görö mibakha — ba wondrege ni''amoni''ö — ba izi mbawandruhö andrö ba gosali, si dua görö, bawandruhö ba zi hulö dalu zalo, ba ana''a göi.', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475037, 'OT', 'Razo I', 7, 51, 'Ba me no awai nilau andrö, fefu, nifalau''ö razo Selomo ba gosali Yehowa andrö, ba i''ohe bakha Selomo ni''amoni''ö namania Dawido, firö andrö ba ana''a andrö, ba gama-gama, ibe''e ba mbate''e girö-girö andrö ba gosali Yehowa.', '["40—47: Nga''ötII 4:11—18","Ayati 48—51: Nga''ötII 4:19—5:1","MozII 30:1; 25:23"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 1, 'Ba ifalukha''ö zatua Ndraono Gizeraeli Selomo,[1] awö hogö mado, salaŵa niwa Ndraono Gizeraeli, khönia, ba Yeruzalema, ba wolohe miyaŵa tawöla zura goroisa Yehowa, moroi ba mbanua Dawido, ya''ia Ziona andrö.[2]', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 2, 'Ba owulo khö razo Selomo ndra matua Ndraono Gizeraeli fefu, ba mbaŵa Etani, ba gowasa — ya''ia mbaŵa si fitu andrö.[3]', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 3, 'La''ondrasi satua Ndraono Gizeraeli,', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 4, 'ba lafazaŵa dawöla ere, ba la''ohe miyaŵa dawöla Yehowa andrö, fabaya ose wama''ele''ö, awö gama-gama ni''amoni''ö andrö fefu, si so baose andrö — da''ö ni''ohe gere ba ono Lewi miyaŵa.', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 5, 'Ba razo Selomo ba banua Ndraono Gizeraeli fefu, si no mangondrasi ya''ia, ba la''iagö föna dawöla, wame''e sumange biri-biri ba saŵi, irege lö mutaha mu''erai ha wa''oya.', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 6, 'Ba ere andrö, ba la''ohe ba nahania dawöla zura goroisa Yehowa, ba zi hulö mbate''e, tanö ba hambo, ba wondrege ni''amoni''ö andrö, barö gafi Kerubi andrö.', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 7, 'Noa sa mubologö gafi Kerubi andrö, yaŵa naha dawöla, ba tobali amaedola lafondrundru dawöla, fabaya heaheania, Kerubi, moroi yaŵa.', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 8, 'Ba fa''anau heahea andrö, ba irege oroma khö zi iagö föna wondrege ni''amoni''ö; ba moroi baero, ba lö oroma. Ba ba da''ö soso, irugi ma''ökhö andre.', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 9, 'Ba bakha barö dawöla andrö, ba ha kara wanura andrö, si dua görö, nibe''e Moze bakha, ba gahe hili Horebi no, kara wanura ba wawu''usa li andrö, me fawu''u li Yehowa ba Ndraono Gizeraeli, me aheta ira ba danö Miserayi.[4]', '["Faigi göi Nga''ötII 5—7","SamII 6:17","MozIII 22:34","MozII 25:21; Heb 9:4"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 10, 'Ba me laröi ni''amoni''ö ere, ba ifönui gosali Yehowa lawuo andrö,', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 11, 'tobali tebai möi mangai halöŵöra ere, ba lawuo andrö, me no ifönui gosali Yehowa lakhömi Yehowa.[5]', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 12, 'Ba imane Selomo:[6] "Luo andrö, ba no ifataro ba mbanua si yaŵa. Ba no iŵa''ö Yehowa, ba zogömi-gömi i''iagö.[7]', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 13, 'Ba no ulau nomo, nahiau, nahia si soso''ö, irugi zi lö aetu." Ba zura zinunö so da''ö.', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 14, 'Ba ibali''ö ia furi razo ba ifahowu''ö zato Ndraono Gizeraeli fefu, no muziozio zato fefu.', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 15, 'Ba imane: Nisuno Yehowa, Lowalangi Ndraono Gizeraeli, si no mamabu''u li khö namagu Dawido bewenia, ba si no mamalua ya''ia tangania,', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 16, 'me imane: I''otarai luo me uheta ba danö Miserayi mbanuagu Iraono Gizeraeli, ba lö nituyugu ba mado Ndraono Gizeraeli banua, ena''ö lalau gosali, ena''ö ba da''ö monahia döigu. Ba aefa da''ö, ba utuyu Yeruzalema, nahia döigu, ba no utuyu Dawido, ena''ö razo mbanuagu Iraono Gizeraeli ia.[8]', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 17, 'Ba no iŵa''ö tödönia amagu Dawido, ilau gosali döi Yehowa, Lowalangi Ndraono Gizeraeli;', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 18, 'ba imane Yehowa khö namagu Dawido: Me no öŵa''ö tödöu ölau gosali döigu, ba si sökhi da''ö, me no si manö dödöu.', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 19, 'Ba tenga sa ya''ugö zolau osali andrö, onou dania, nga''ötöu, zolau osali döigu.', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 20, 'Ba no itörö gamabu''ula li andrö ibe''e Yehowa. So ndra''o, fangali namagu Dawido, mudadao ndra''o ba dadaoma razo Ndraono Gizeraeli, itörö nifabu''u Yehowa, ba no ulau gosali döi Yehowa, Lowalangi Ndraono Gizeraeli.', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 21, 'Ba no ufonahia ba da''ö dawöla andrö, tawöla goroisa ba wawu''usa li andrö khö Yehowa, fawu''usa li me fawu''u li ia khö ndra tuada, me iheta ira ba danö Miserayi.', '["MozII 40:34","Ayati 12—53: Nga''ötII 6:1—40","MozII 20:21","SamII 7:6"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 22, 'Ba möi föna naha wame''e sumange andrö khö Yehowa Zelomo, anehe Ndraono Gizeraeli sato, fefu, i''oro''ö dangania miyaŵa ba zorugo,', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 23, 'ba imane: "He Yehowa, Lowalangi Ndraono Gizeraeli! Samösa lö Lowalangi si mane ya''ugö, he si yaŵa ba zorugo, ba he si tou ba guli danö; ya''ugö, ba lö öbulö''ö wawu''usa li andrö ba fa''ebua dödöu ba genoniu andrö, sanörö lala khöu, soroi si''aikö ba dödö,', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 24, 'ba no ötörö khö genoniu andrö, amagu Dawido nifabu''umö khönia. Ya''ia, nifabu''umö khönia beweu, ba no öfalua tangau, si mane ma''ökhö.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 25, 'Ba iada''e, ya''ugö Yehowa, Lowalangi Ndraono Gizeraeli, törö khö genoniu, amagu Dawido, nifabu''umö khönia, me ömane: Sagötö fa''ara dania, ba lö ambö khöu [nga''ötöu], fönagu, sidadao ba dadaoma razo Ndraono Gizeraeli, asala lafaigi-faigi lalara iraonou, ena''ö latörö fönagu, si mane fonöröu ya''ia fönagu.[9]', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 26, 'Ba iada''e, ya''ugö Lowalangi Ndraono Gizeraeli, ena''ö na itorö gamabu''ula limö andrö, nifabu''umö andrö khö genoniu, amagu Dawido.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 27, 'Ba hadia, si ndruhu, ba guli danö i''iagö Lowalangi? Hiza, lö lataha ia sorugo ba fondrege zorugo, ba he moroi itaha ia osali andre, nilaugu?[10]', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 28, 'Ba otahögö wangandrö genonimö andre ba fakaosania, ya''ugö Yehowa, Lowalangigu, ena''ö öfondrondrongo wangarö-ngarö andrö ba fangandrö andrö, fangandrö genoniu andre khöu, ma''ökhö;', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 29, 'ena''ö bongi ma''ökhö manö öfaigi-faigi gosali andre, nahia andrö, nifabu''umö limö, me ömane: Töigu zi soso ba da''ö dania; fa öfondrondrongo wangandrö genoniu ba naha andre.[11]', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 30, 'Ba ena''ö na öfondrondrongo wakaosa genoniu andre ba fakaosa mbanuau, Iraono Gizeraeli, na mangandrö ira ba naha andre; ya''ia, ena''ö na öfondrondrongo ba naha andrö, ba zidadao ya''ugö, ba zorugo; ba na örongo, ba öbe''e aefa zala!', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 31, 'Na so zi sala khö nawönia ba na labe''e ba hölu ia, ena''ö i''aro''ö [niŵa''önia] ba hölu andrö, ba na so ia, na möi ba hölu ia, föna naha wame''e sumange ba nomo andre:[12]', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 32, 'ba fondrondrongo ba zorugo, ba tolo ba ohe ba lala huhuo genonimö, ena''ö ö''etu''ö huku zi so sala, wangahare''ö ba hulunia wolaunia andrö, ba ena''ö aefa zi lö horö öŵa''ö, dali wa''atulö dödönia.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 33, 'Ba na te''ala mbanuau Iraono Gizeraeli labe''e emalira, na moloi ira labe''e, me no molalö ira khöu, ba na lafuli ira khöu, na faduhu dödöra ba döimö andrö ba na mangandrö ira khöu, na la''angaröfi li ndra''ugö ba nomo andre:[13]', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 34, 'ba öfondrondrongo ba zorugo ba öbe''e aefa horö mbanuau, Iraono Gizeraeli, ba ö''ohe mangawuli ira ba danö andrö, nibe''eu khö ndra tuara.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 35, 'Ba na no teduhö mbanua si yaŵa, na lö teu, me no molalö ira khöu, ba na mangandrö ira ba naha andre ba na faduhu dödöra ba döimö andrö, na lafalalini gera-erara, na laböhöi horö, me no öhöndrögö ira:[14]', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 36, 'ba öfondrondrongo ba zorugo, ba öbe''e aefa horö genoniu, horö mbanuau, Iraono Gizeraeli, wanuturu khöra lala si sökhi andrö, nitöröra; ba öfoteu danöu andrö, nibe''eu ba mbanuau andrö, ondröita dania ba nga''ötöra.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 37, 'Ba ma lofo mbanua ba danö ba ma fökhö waba, ba na fa''akhozi ngalai wakhe ba ma loyomö ba ma so damo, ba ma föla, ba ma lafakao ira emalira, ba mbanuara heza, ba ma hadia wamakao, ba ma hadia ia wökhö:', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 38, 'ba na so zangandrö, ha niha, ba ma si angaröfi li ya''ugö, banuau Iraono Gizeraeli fefu, ha niha, — na itegu ira tödöra, dozi ira — na i''oro''ö dangania ba nomo andre:', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 39, 'ba öfondrondrongo ba zorugo, ba nahiau andrö, ba zidadao ndra''ugö, ba öbe''e aefa zala ba öfaigi, ena''ö ösulöni sibai ba zamösana nitörönia, he wisa wamaigiu tödönia — ha sa ya''ugö zangila tödö nono niha fefu![15] —', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 40, 'Ena''ö la''ata''ufi ndra''ugö si lö mamalö-malö, götö we''asora ba danö andrö, nibe''eu khö ndra tuama.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 41, 'Ba he ba niha bö''ö si tenga banuau Iraono Gizeraeli, na so ia moroi ba danö saröu, börö döimö andrö, —', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 42, 'larongo sa''ae dania döimö sebua andrö ba tangau sabölö ba ta''iomö, si no ö''oro''ö — na so ia, ba na mangandrö ia ba golayama gosali andre,', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 43, 'ba öfondrondrongo ba zorugo, ba nahiau andrö, sidadao ndra''ugö, ba ö''o''ö fefu ni''andrö niha bö''ö andrö, ena''ö aboto ba dödö niha fefu ba guli danö döimö andrö, ena''ö la''ata''ufi ndra''ugö, si mane banuau Iraono Gizeraeli, ba ena''ö aboto ba dödöra, wa no töimö mbörö döi gosali andre, nilaugu.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 44, 'Ba na möi fasuwö ba nemalira mbanuau, na latörö lala ba nifatengeu ya''ira, ba na mangandrö ira khö Yehowa, na la''otahögö mbanua andre, nituyumö ba osali andre,', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 45, 'nilaugu nahia döimö: ba öfondrondrongo ba zorugo wangandröra ba fe''angaröfira li ya''ugö, ba ötolo ira.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 46, 'Ba na molalö ira khöu — samösa sa lö niha si lö olalöŵa — ba na mofönu''ö khöra, na öbe''e ba danga nemalira ira, na tobali la''oloi''ö ira samakao ya''ira, ba danö nemali, he ba zaröu, ba he ba zahatö.[16]', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 47, 'ba na la''era-era tödöra, ba danö andrö, ba ni''oloi''ö ya''ira, na lafalalini gera-erara ba na la''angaröfi li ndra''ugö ba danö zamakao ya''ira, na lamane: No mosala ndra''aga, no malau zi lö atulö, no sebua horö ndra''aga!', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 48, 'ba na lafuli ira khöu, soroi si''aikö ba dödöra ba ba gera-erara fefu, ba danö nemalira andrö, sangoloi''ö ya''ira, ba na mangandrö ira khöu, na la''otahögö danöra andrö, nibe''eu khö ndra tuara, mbanua andrö, nituyumö, ba omo andre, nilaugu nahia döimö:', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 49, 'ba öfondrondrongo wangandröra ba fe''angaröfira li ya''ugö, ba zorugo, ba naha andrö, ba zidadao ndra''ugö ba ötolo ira,', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 50, 'ba öbe''e aefa zala mbanuau, hadia ia horöra khöu, awö lalöra fefu, solalö ira khöu, ba ena''ö lahakhösi tödö ira sangolöi''ö ya''ira mege, öbe''e, ena''ö ogolö dödöra ira.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 51, 'Me no banuau ira ba me no ya''ugö zokhö ya''ira, nihetamö ba danö Miserayi, amaedola ba dalu galitö famahele zi''öli.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 52, 'Ena''ö lö aefa höröu ba wakaosa genoniu ba ba wakaosa mbanuau Iraono Gizeraeli, ena''ö ö''o''ö khöra fefu ni''andröra khöu.', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 53, 'Noa sa ö''oniagö ira khöu, tana khöu, ba niha bö''ö fefu ba guli danö, dali nifabu''umö, nifa''ema genoniu Moze, me öheta ba danö Miserayi ndra tuama, ya''ugö So''aya, Yehowa".[17]', '["Sin 132:11","Yes 66:1; Yer 23:24","MozV 12:11","MozII 22:11","MozV 30:2","Faigi 17:7","Sin 7:10; HalZin 1:24","Amaed 20:9; Yak 3:2; YohI. 1:8","MozII 19:5; MozV 9:26"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 54, 'Ba me no i''etu''ö Selomo wangandrö ba fe''angarofi li Yehowa, ba maoso ia föna naha wame''e sumange khö Yehowa, ba nibalöduhininia tanö mege, wangoro''ö tangania miyaŵa ba zorugo,', '["Yos 21:45","MozV 4:35"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 55, 'ba i''otahögö Ndraono Gizeraeli sato, ba ifahowu''ö ira, i''ebua''ö linia, imane:', '["Yos 21:45","MozV 4:35"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 56, 'Nisuno Yehowa, si no mame''e ahono Ndraono Gizeraeli, si mane nifabu''unia mege; sambalö lö saekhu ba danö amabu''ula li si sökhi andrö fefu, nifabu''unia, nifa''ema genoninia Moze![18]', '["Yos 21:45","MozV 4:35"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 57, 'Yamutolo ita Lowalangida, Yehowa, si mane fanolonia ira tuada mege. Böi yamu''erogö ita, ba böi yamutibo''ö ita,', '["Yos 21:45","MozV 4:35"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 58, 'ena''ö khönia gaso''ala dödöda ibe''e, ba ena''o lala khönia, tatörö, si lö mamalö-malö, ba ena''ö oroisania ba amakhoitania ba hukunia tatöngöni, niŵa''önia khö ndra tuada.', '["Yos 21:45","MozV 4:35"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 59, 'Ba ena''ö bongi ma''ökhö lö olifu Lowalangida, Yehowa, ligu andre, niŵa''ögu khö Yehowa, we''angaröfi li ya''ia, ena''ö ero ma''ökhö i''ohe ba lala huhuo genoninia, awö huhuo mbanuania, Iraono Gizeraeli,', '["Yos 21:45","MozV 4:35"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475038, 'OT', 'Razo I', 8, 60, 'ena''ö aboto ba dödö niha fefu, ba guli danö, wa no Lowalangi Yehowa, ha ya''ia.[19]', '["Yos 21:45","MozV 4:35"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 61, 'Ba böi dua-dua dödömi khö Lowalangida Yehowa, ena''ö mitörö nifakhoinia, ba mi''o''ö goroisania, si mane ma''ökhö.', '["Yos 21:45","MozV 4:35"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 62, 'Ba labe''e zumange nitaba khö Yehowa razo ba Iraono Gizeraeli fefu, awönia.[20]', '["Ayati 62—66: Nga''ötII 7:4—10"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 63, 'Sumange fangorifi ibe''e Selomo, itaba khö Yehowa, 22.000 zaŵi, ba 120.000 mbiri-biri. Ba la''amoni''ö gosali Yehowa razo ba Iraono Gizeraeli fefu.', '["Ayati 62—66: Nga''ötII 7:4—10"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 64, 'Me luo da''ö i''amoni''ö razo golayama ba dalu andrö, föna gosali Yehowa, wame''e sumange ba da''ö, sumange nitunu ba sumange ni''a ba tawö zumange fangorifi. Me no ambö fa''ebua naha wame''e sumange töla andrö, föna Yehowa, lö itaha zumange nitunu andrö, ba sumange ni''a ba tawö zumange fangorifi.', '["Ayati 62—66: Nga''ötII 7:4—10"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 65, 'Ilau gowasa Selomo, me luo da''ö, ba Iraono Gizeraeli fefu, awönia, owuloa sebua sibai, [dozi banua] i''otarai ba lala ba Hamata, numalö ba mbombo andrö ba nola danö Miserayi, föna Lowalangida Yehowa, mendrua wa fitu bongi, tobali feleöfa ngaluo.', '["Ayati 62—66: Nga''ötII 7:4—10"]', NULL),
  (3475038, 'OT', 'Razo I', 8, 66, 'Ba me luo si ŵalu, ba ifofanö niha sato. Ba la''angonasi razo ba lafuli ira khöra, omuso dödöra ba abe''e dödöra, ba zi sökhi andrö fefu, nibe''e Yehowa khö genonia Dawido ba ba mbanuania, Iraono Gizeraeli.', '["Ayati 62—66: Nga''ötII 7:4—10"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 1, 'Ba me no i''asiwai Selomo wolau osali Yehowa,[1] awö gödo razo ba hadia ia fefu nifakhoi dödönia, somasi ia ifalua,', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 2, 'ba ifuli i''oroma''ö ia khö Zelomo Yehowa, si mane fangoroma''önia ya''ia ba Gibeona no.[2]', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 3, 'Ba imane khönia Yehowa: No urongo wangandröu ba fakaosamö khögu. Osali andrö nilaumö, ba no ube''e ni''amoni''ö, wamonahia töigu ba da''ö, si lö mamalö-malö, ba hörögu ba tödögu, ba si lö aefa-aefa ba da''ö.', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 4, 'Ba na ötörö sa''ae lala nifakhoigu, si mane fanörö namau Dawido, ba wa''adölö dödö ba ba wa''atulö, fa ö''o''ö sibai niŵa''ögu khöu ba ötöngöni nifakhoigu, awö lala andrö khögu,', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 5, 'ba u''aro''ö dadaoma wa''arazomö ba Ndraono Gizeraeli, irugi zi lö aetu, si mane nifabu''ugu khö namau Dawido, me umane: Lö aetu dania khöu [nga''ötöu] sidadao ba dadaoma razo Ndraono Gizeraeli.[3]', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 6, 'Ba na mi''erogö zui ndra''o, ya''ami ba iraonomi, na lö mi''o''ö goroisagu, awö nifakhoigu, niŵa''ögu khömi, na möi ami mamosumange Lowalangi bö''ö, na khöra mangalulu ami,[4]', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 7, 'ba uhori Ndraono Gizeraeli ba danö andre, nibe''egu khöra; ba osali andre, si no u''amoni''ö nahia döigu, ba timba nitibo''ö ube''e, lö''ö sa''ae ufaigi; ba Iraono Gizeraeli, ba ube''e ni''o''aya niha bö''ö fefu ba niheraherai.[5]', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 8, 'Ba osali andre, si no alaŵa yaŵa, ba tobali adudula dania; dozi sanörö, ba tobali dodö ba fasi, ba na lasofu: Hana wa ilau da''ö Yehowa ba danö andre ba ba gosali andre?[6]', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 9, 'Ba lamane: Börö me no la''erogö Lowalangira, Yehowa andrö, si no mangeheta ira tuara ba danö Miserayi ba me no la''olembai Lowalangi bö''ö ba me no ba da''ö mangalulu ira, me no da''ö lafosumange, — andrö wa no ifatörö khöra Yehowa wamakao andrö fefu!', '["Ayati 1—9: Nga''ötII 7:11—22","Faigi 3:5","SamII 7:16; Faigi 6:12","Sin 89:31","MozV 28:37","Yer 22:8"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 10, 'Ba me no numalö zi dua wulu fakhe andrö, ba nilau Zelomo omo andrö, si dombua, — osali Yehowa andrö, awö gödo razo,[7]', '["Faigi 6:38","Yos 19:27"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 11, 'ba nitolo Hiramo, razo Diro, Selomo balo eresi ba balo senobari ba ana''a, ha wa''ebua zomasi ia — ba me luo da''ö, ba 20 i''amualagö Selomo khö Hiramo banua ba danö Galilaia.', '["Faigi 6:38","Yos 19:27"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 12, 'Ba so Hiramo, moroi ba Diro, ba wamaigi banua andrö, nitehe Zelomo khönia, ba lö omasi ia.', '["Faigi 6:38","Yos 19:27"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 13, 'Ba imane: Hadia mbanua da''ö, nibe''eu khögu, ga''a? Andrö wa labe''e töi danö da''ö Kabuli (mane si lö boto), irugi ma''ökhö andre.[8]', '["Faigi 6:38","Yos 19:27"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 14, 'Ba 27.772 balaki zi no ifa''ohe''ö khö Zelomo ana''a Hiramo.', '["Faigi 6:38","Yos 19:27"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 15, 'Ba si mane rodi andrö, niŵa''ö razo Selomo, ba wolau osali Yehowa andrö, awö gödonia, awö [hati] Milo andrö, awö göli Yeruzalema ba öli Hasora ba öli Megido ba öli Gezeri, oi öli kara.', '["MozIII 25:39"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 16, 'Noa sa möi miyaŵa Wara''o, razo Miserayi, no atu''a ia ba Gezeri andrö ba no itunu ba no la''ö''ötö tou Ndrawa Gana''ana andrö, banua da''ö; ba no ibe''e buala [mbanua da''ö] khö nononia, fo''omo Zelomo.', '["MozIII 25:39"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 17, 'Ba i''aro''ö Selomo Gezeri andrö ba Beti Horona tou,', '["MozIII 25:39"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 18, 'ba Ba''alati ba Tamara ba danö si mate.', '["MozIII 25:39"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 19, 'Ba banua, ba ni''irö''ö balazo, fefu, ba banua gureta ba banua zi fakudo andrö ba hadia ia na, somasi Zelomo ilau, he ba Yeruzalema, ba he ba hili Libano ba ba danö si so barö mbawania, ma''asagörö.', '["MozIII 25:39"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 20, 'Ba dozi si tosai Iraono Gamori ba Iraono Kheti ba Iraono Weresi ba Iraono Hewi ba Iraono Yebusi, si tenga Iraono Gizeraeli, 21— nga''ötöra andrö, si tosai na ba danö, si tebai lahori Iraono Gizeraeli, — da''ö ni''ofaya Zelomo ba rodi andrö, ba irugi ma''ökhö andre.', '["MozIII 25:39"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 22, 'Ba Iraono Gizeraeli, ba samösa lö ibali''ö sawuyu Selomo; ya''ira, ba no saradodu ba kumandru khönia ba kumandra ba si fasöndra moroi ba gureta khönia ba solohe kureta, awö zi fakudo.[9]', '["MozIII 25:39"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 23, 'Ba högö mandru andrö, sanaro sohalöŵö khö Zelomo, ba no 550.', '["MozIII 25:39"]', NULL),
  (3475039, 'OT', 'Razo I', 9, 24, 'Ba möi miyaŵa nono Wara''o andrö, moroi ba mbanua Dawido, isaŵa nomonia nilau Zelomo khönia. Ba ilau Milo andrö Selomo.', '[]', NULL),
  (3475039, 'OT', 'Razo I', 9, 25, 'Ba medölu zi döfi mame''e sumange Zelomo, sumange nitunu ba sumange fangorifi, ba naha wame''e sumange andrö, nifazökhinia khö Yehowa, ba manunu kumöyö.', '[]', NULL),
  (3475039, 'OT', 'Razo I', 9, 26, 'Ba owo göi ilau Selomo ba Geseono Geberi, ba ngai Geloti, ba mbewe nasi zukhu ba danö Ndraono Gedomo.', '[]', NULL),
  (3475039, 'OT', 'Razo I', 9, 27, 'Ba ifatenge ba nowo andrö mbanuania Hiramo — durumudi ba ono nowo, si no to''ölö ba nasi — ifa''amöi awö mbanua Zelomo.', '[]', NULL),
  (3475039, 'OT', 'Razo I', 9, 28, 'Ba larugi Gofiri ba lahalö gana''a ba da''ö, 97.000 balaki, ba la''ohe khö Zelomo.', '[]', NULL),
  (3475040, 'OT', 'Razo I', 10, 1, 'Ba me irongo duria Zelomo razo Zaba, ira alawe,[1] ba möi ia ba wanandraigö Selomo dahö-dahö.[2]', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 2, 'Irugi Yeruzalema ba ato sibai nawönia fao, awö gondra, sonoro famasa gö ba dalu-dalu ba ana''a sebua sibai ba feremata. Ba i''ondrasi Zelomo ba i''ombakha''ö khönia fefu hadia ia zi so ba dödönia.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 3, 'Ba itema linia Selomo ba ngawalö hadia ia fefu, nisofunia khönia; lö hadia ia zi lö aboto ba dödö razo, ba si tebai itema linia.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 4, 'Ba me no irongo wa''atua-tua Zelomo andrö fefu razo Zaba, ba me no i''ila gödo andrö nilaunia, ba öra andrö,', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 5, 'ba omo genoni Zelomo, ba halöŵö ngoni-ngoni andrö khönia, awö nukhara, ba same''e yomo gö khönia ba sumange nitunu andrö, nibe''e-be''enia ba gosali Yehowa, ba tobali dödönia,', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 6, 'ba imane khö razo: Si ndruhu manö nirongogu ba danögu, he wisa ba khömö ba fa''atua-tuamö andrö.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 7, 'Hulö zi tebai faduhu dödögu, irugi we''amöigu andre, ba irege i''ila hörögu; ba ambö matonga na''i ni''ombakha''ö khögu; ebua sibai na moroi ba duria andrö, nirongogu, wa''atua-tuamö andrö ba ana''amö.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 8, 'Ya ahowu ndra alawemö andrö ba ya ahowu genonimö andre, si lö aefa-aefa khöu, wamondrongondrongo fa''atua-tuamö!', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 9, 'Nisuno Yehowa, Lowalangimö andrö, si no mangomasi''ö ya''ugö, wamedadao ya''ugö ba dadaoma razo Ndraono Gizeraeli; me no si lö mamalö-malö wa''omasi Yehowa Ndraono Gizeraeli, andrö wa ifataro razo ndra''ugö, ena''ö huku satulö öfatörö.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 10, 'Ba 27.772 balaki ibe''e bualania khö razo, ana''a, ba oya sibai wamasa gö ba dalu-dalu ba feremata; lö''ö sa''ae dania si manö wa''oya wamasa gö ba dalu-dalu, si mane nibe''e razo Zaba andrö buala khö razo Selomo.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 11, 'Ba soloyo andrö göi khö Hiramo, sangai ana''a ba Gofiri, ba oya göi lasao''ö eu zendrana ba feremata.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 12, 'Ba eu zendrana andrö, ba ibali''ö daoma-daoma Selomo, he ba gosali ba he ba gödonia, ba biola nitika, side-ide ba sebua, ba zanunö andrö; zendrana andrö, si manö wa''oya, ba lö''ö sa''ae muhalö, lö mu''ila, irugi ma''ökhö andre.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 13, 'Ba Selomo, ba ibe''e khö razo Zaba fefu hadia ia zomasi ia, fefu hadia ia ni''andrönia, lö lai nibe''enia khönia fa''oböwö razo. Ba mofanö sa''ae ia, ifuli ia ba danönia, awö genoninia andrö.', '["Ayati 1—28: Nga''ötII 9:1—28","Mat 12:42"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 14, 'Ba fa''ebua gana''a, nisöndra Zelomo, döfidöfi, ba no 153.846 balaki,', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 15, 'lö lai nisöndrania ba zanöröi tanö ba waniaga ba ba zolafo ba ba razo Gerebi andrö, ba ba gumandru ba danö.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 16, 'Ba 200 ibago dange Selomo, ana''a niböbözi, 600 fondruyu zambua;', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 17, 'ba 300 mbaluse, ana''a niböbözi, 150 fondruyu zambua. Ba ibe''e ba nomo eu gatua Libano andrö razo.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 18, 'Ba baero da''ö ba ifazökhi razo dadaoma sebua, ifö guaza, ba ifo''uli balaki. 19önö mbosi dadaoma andrö, ba högönia, tanö furi, ba ni''owuloi''ö; ba daoma-daoma, ba no mufatambai latalata da''io, ba ba zinga latalata da''io andrö, ba dua geu zingo.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 20, 'Ba felendrua nga eu zingo ba mbosi andrö, si önö, fatambai. Lö murai mufazökhi zi manö ba razo bö''ö, heza.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 21, 'Ba fefu mako Zelomo, ba ana''a; fefu gama-gama ba nomo eu gatua Libano andrö, ba no balaki manö; lö hadia ia wirö, me si lö ba dödö wirö, ba götö Zelomo andrö.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 22, 'Noa sa so ba nasi nowo Darisi khö razo, si fao-fao ba nowo Hiramo andrö; samuza zi medölu fakhe so nowo Darisi andrö ba lasao''ö mbalaki ba firö ba ifö guaza ba ba''e ba fofo mera.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 23, 'Ba italu''i razo ba guli danö fefu razo Selomo, ba wa''ebua gana''a ba ba wa''atua-tua.[3]', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 24, 'Ba dozi niha ba guli danö omasi mangila Selomo, ba wamondrondrongo fa''atua-tuania, nibe''e Lowalangi ba dödönia.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 25, 'Ba ero rofi, ba dozi mamuala ira khönia, gama-gama firö ba gama-gama ana''a ba nukha ba fangöna, ba famasa gö ba dalu-dalu ba kudo ba kudo kalide.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 26, 'Ba oya i''asogö kureta ba si fakudo Selomo;[4] 1400 khönia gureta ba 12.000 zi fakudo; ba mbanua gureta andrö ifataro da''ö ba ba ngai razo, ba Yeruzalema.[5]', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 27, 'Fagölö-gölö ira wa''oya wirö wa''oya gara ba Yeruzalema, ibe''e razo, ba fa''oya döla waringi ba mbewe nasi döla geresi.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 28, 'Ba danö Miserayi lahalö kudo andrö khö Zelomo, samba-sambawa lahalö saniaga andrö khö razo, la''öli.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475040, 'OT', 'Razo I', 10, 29, 'Sambu-sambua kureta nihalö miyaŵa moroi ba danö Miserayi, ba önö ngaotu rufia, ba sagesageu kudo, ba otu a lima wulu. Ba si manö wama''emara ba razo Ndraono Kheti fefu, ba ba razo Ndrawa Garamo.', '["Faigi 3:13","Ayati 26—29: Nga''ötII 1:14—17","MozV 17:16; Nga''ötII 1:14"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 1, 'Ba oya zomasi Zelomo ira alawe, ono niha baero, awö nono Wara''o andrö: Iraono Moabi ba Iraono Gamoni ba Iraono Gedomo ba banua Zidona andrö ba Iraono Kheti,[1]', '["MozV 17:17","MozV 7:1 b.t.","Sanguhuk 2:13","MozIV 21:29"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 2, 'oi niha niŵa''ö Yehowa ba Ndraono Gizeraeli: Böi mi''ae''ae khöra ba böi möi ira khömi, fa böi labe''e ba Lowalangira aolo dödömi! Da''ö zomasi Zelomo,[2]', '["MozV 17:17","MozV 7:1 b.t.","Sanguhuk 2:13","MozIV 21:29"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 3, 'Ba si ndruhu ndrongania, ba 700; ba 300 ndronga ba döi, ba ira alawenia zamowöhö ya''ia.', '["MozV 17:17","MozV 7:1 b.t.","Sanguhuk 2:13","MozIV 21:29"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 4, 'Ba me no atua sa''ae Zelomo, ba lafaelungu ia ira alawenia, ba tobali i''olembai Lowalangi bö''ö, ba tenga sa''ae ha sambalö khö Lowalanginia Yehowa dödönia, si mane tödö namania Dawido mege.', '["MozV 17:17","MozV 7:1 b.t.","Sanguhuk 2:13","MozIV 21:29"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 5, 'Itörö lala khö Asitore andrö, Lowalangi Zidona, Selomo, awö lala khö Milikomo andrö, sogoro ita ba Ndraono Gamoni.[3]', '["MozV 17:17","MozV 7:1 b.t.","Sanguhuk 2:13","MozIV 21:29"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 6, 'Ilau zi fatuwu khö Yehowa, ba lö a''oi dödönia wolo''ö khö Yehowa, si mane amania Dawido.', '["MozV 17:17","MozV 7:1 b.t.","Sanguhuk 2:13","MozIV 21:29"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 7, 'Me luo da''ö ifa''anö naha wame''e sumange khö Kamosi andrö, sogoro ita ba Ndraono Moabi, ba hili andrö, tanö ba gatumbukha luo, i''otarai Yeruzalema, ba ba Molokho andrö, sogoro ita ba Ndraono Gamoni.[4]', '["MozV 17:17","MozV 7:1 b.t.","Sanguhuk 2:13","MozIV 21:29"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 8, 'Ba si manö wolaunia ba khö ndrongania niha baero andrö fefu, ba manunununu kumöyö ira ba mame''e-me''e sumange.', '["MozV 17:17","MozV 7:1 b.t.","Sanguhuk 2:13","MozIV 21:29"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 9, 'Ba mofönu Yehowa khö Zelomo, me no i''erogö Yehowa, Lowalangi Ndraono Gizeraeli, si no mangoroma''ö ya''ia khönia, no mendrua ae,[5]', '["Faigi 3:5; 9:2","Faigi 12:16"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 10, 'ba si no mame''e oroisa andrö khönia, böi itörö lala Lowalangi bö''ö; ba hadia niŵa''ö Yehowa khonia, ba lö ni''o''önia.', '["Faigi 3:5; 9:2","Faigi 12:16"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 11, 'Andrö wa imane Yehowa khö Zelomo: Me no öfa''amöi ba dödöu zi manö ba me lö nitöngöniu fawu''usa li andrö khögu ba he nifakhoigu andrö, niŵa''ögu khöu, ba uheta khöu wa''arazo, ba ube''e khö genoniu.[6]', '["Faigi 3:5; 9:2","Faigi 12:16"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 12, 'Ba tenga sa ba götömö ulau da''ö, börö namau Dawido; ba khö nonou dania, ba uheta.', '["Faigi 3:5; 9:2","Faigi 12:16"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 13, 'Ba lö ahori uheta khönia gamatöröŵa andrö sambua mado ube''e khö nonou, börö genonigu Dawido ba börö na Yeruzalema andrö, nituyugu.', '["Faigi 3:5; 9:2","Faigi 12:16"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 14, 'Ba maoso zi fa''udu khö Zelomo, ibe''e Yehowa, Iraono Gedomo andrö, Hadada, nga''ötö razo ba Ndraono Gedomo.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 15, 'Me föna no, me ihori Ndraono Gedomo Dawido, me möi gumandra Yoabi, ba wogo''o si mate andrö, ba me i''ö''ötö tou fefu motöi matua ba Ndraono Gedomo[7] —', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 16, 'önö waŵa Yoabi ba da''ö, awö Ndraono Gizeraeli fefu, irege no ihori fefu motöi matua ba Ndraono Gedomo —', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 17, 'ba moloi Hadada andrö ba Iraono Gedomo ösa, sangai halöŵö khö namania mege ba wanaŵa tanö Miserayi. Ba iraono sibai na Hadada.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 18, 'Ba latohugö wofanö, laheta ira ba danö Ndraono Midiano ba larugi Warana; ba la''ohe awöra mbanua Warana ba larugi danö Miserayi, Wara''o andrö, razo Miserayi. Ba ibe''e khönia nomo Fara''o ba ituturu mbalazo, ba tanö ibe''e khö Hadada.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 19, 'Ba itugu ebua sibai dödö Wara''o khö Hadada, tobali ibe''e dongania ga''a wo''omonia Takhifene andrö.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 20, 'Ba mo''ono khönia ga''a Dakhifene andrö, ononia Genubati andrö; Ba Takhifene zange''ebua ba gödo Wara''o, ba tobali ba gödo Wara''o manö soso Genubati, awö ndraono Wara''o.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 21, 'Ba me irongo Hadada ba danö Miserayi, no mate Dawido ba no mate göi Yoabi, kumandra sebua ba imane Hadada khö Wara''o: Efa''ö ndra''o, ena''ö ufulido ba khöma.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 22, 'Ba imane khönia Wara''o: Hadia zambö ndra''ugö khögu, wa omasi''ö öfuli''ö ba khömi? Ba imane:', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 23, 'Lö''ö sa, ba fofanö ndra''o. Ba samösa tö i''asogö khö Zelomo udunia Lowalangi, Resono andrö, ono Geliada, si no moloi khö zokhö ya''ia, khö Hadadezeri razo Zoba.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 24, 'Ikhai awönia niha bö''ö ba tobali solohe si möi manuwö-nuwö ia, me luo ifabunu''ö niha andrö ba Ndrawa Garamo Dawido; ba atu''a ia ba Ndramaseko ba i''iagö da''ö, ba tobali razo ia ba Ndramaseko.[8]', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 25, 'Ba udu Ndraono Gizeraeli ia götö Zelomo andrö, lö lai wamakao andrö khö Hadada no mege; no si fatuwu sibai khönia Ndraono Gizeraeli, ba no razo Ndrawa Garamo ia.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 26, 'Ba ilaŵa göi razo Yerobeamo andrö, ono Nebati, mado Geferayi, banua Zereda, enoni Zelomo (Serua döi ninania, lakha mbanua).[9]', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 27, 'Ba da''ö mbörö, wa ilaŵa razo: Me ilau Milo andrö Selomo, ba iduhö zatöla öli na ba mbanua Dawido andrö, banua namania.[10]', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 28, 'Ba Yerobeamo andrö, ba no ono matua sabölö. Ba me i''ila Selomo, sowölö-ölö nono matua andrö, ba ibali''ö mandru zi göna rodi andrö, mado Yosefo.', '["SamII 8:14; Nga''ötI 18:12","SamII 10:18","Nga''ötII 13:6","Faigi 9:15"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 29, 'Ba samuza ma''ökhö, me luo da''ö, me mofanö Yerobeamo, me no iröi Yeruzalema, ba falukha khönia ba lala Gahia andrö sama''ele''ö, banua Zilo; no mobaru si bohou, baru sebua, Gahia; ba ha ya''ira, darua ira, ba da''ö ba lala.', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 30, 'Ba ituyu mbarunia si bohou andrö Ahia, ire''a,', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 31, 'i''ofelendrua, ba imane khö Yerobeamo: Halö khöu zi fulu! Imane sa Yehowa, Lowalangi Ndraono Gizeraeli: Hiza, uheta ba danga Zelomo gamatöröŵania andrö,', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 32, 'ba fulu mado ube''e khöu — ba mado si sambua andrö, ba böi tebulö khönia, börö genonigu Dawido ba börö na Yeruzalema, banua andrö nituyugu ba mado Ndraono Gizeraeli fefu, 33— me no la''erogö ndra''odo ba me no mangalulu ira khö Asitore andrö, Lowalangi mbanua Zidona, ba khö Gamosi, Lowalangi Ndraono Moabi ba khö Milikomo, Lowalangi Ndraono Gamoni, ba me lö nitöröra lala andrö khögu, ba wolo''ö mena''ö somasi ndra''o, awö nifakhoigu, awö huku andrö khögu, si mane amania Dawido mege.', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 34, 'Ba lö ahori uheta khönia gamatöröŵa andrö, ba lö''ö sa ubulö''ö ia razo, gotö wa''anau nosonia, börö Dawido, enonigu andrö, notuyugu, si no molo''ö oroisagu, awö nifakhoigu andrö.', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 35, 'Ba ba danga nononia dania, ba uheta gamatöröŵa andrö, ba ube''e khöu, si fulu tua andrö.', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 36, 'Ba khö nononia, ba sambua mado ube''e, ena''ö lö mate-mate wandru khö genonigu Dawido, fönagu, ba Yeruzalema, ba mbanua andrö, nituyugu khögu, ba wamonahia töigu ba da''ö.[11]', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 37, 'Ba ya''ugö, ba uhalö, ena''ö samatörö ndra''ugö, irugi zomasi''ö fefu, ba ena''ö razo Ndraono Gizeraeli ndra''ugö.', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 38, 'Ba na ahori ö''o''ö niŵa''ögu khöu ba na ötörö lala andrö khögu ba na somasi ndra''o ölau, wanöngöni nifakhoigu andrö ba oroisagu, nifolau genonigu Dawido mege, ba utolo ndra''ugö, ba ulau khöu nomo si lö tebulö, si mane nilaugu khö Dawido, ba ube''e ba dangau Ndraono Gizeraeli.', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 39, 'Ba nga''ötö Dawido andrö, ba uhöndrögö, börö da''ö no mege, ba tenga sa si lö mamalö-malö.', '["Faigi 15:4; Sin 132:17"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475041, 'OT', 'Razo I', 11, 40, 'Ba i''alu-alui Selomo wamunu Yerobeamo; ba maoso Yerobeamo, isaŵa danö Miserayi, khö Zizaki andrö, razo Miserayi, ba ba da''ö i''iagö, irugi wa''amate Zelomo.', '["Faigi 15:4; Sin 132:17"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 41, 'Ba hadia na nitunö, bö''önia, ba khö Zelomo,[12] ba hadia nilaunia fefu ba fa''atua-tuania andrö, ba hadia, tenga ba zura hikaya Zelomo so da''o?', '["Ayati 41—43: Nga''ötII 9:29—31"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 42, 'Ba fa''ara wa''arazo Zelomo ba Yeruzalema, ba Ndraono Gizeraeli fefu, ba no 40 fakhe.', '["Ayati 41—43: Nga''ötII 9:29—31"]', NULL),
  (3475041, 'OT', 'Razo I', 11, 43, 'Ba mate Zelomo, itörö lala ndra amania mege ba ba mbanua Dawido, banua namania, lako''o ia. Ba ononia Rehabeamo zi tobali razo, fangalinia.', '["Ayati 41—43: Nga''ötII 9:29—31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 1, 'Ba me irongo Yerobeamo, ono Nebati — ba danö Miserayi na so ia, nisaŵania, me moloi ia khö Zelomo — me irongo, no mate Zelomo, ba ifuli ia moroi ba danö Miserayi.[1]', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 2, 'Ba möi ba Zikhema Rehabeamo, noa sa lasaŵa Zikhema Iraono Gizeraeli fefu, ba wamataro razo ya''ia.', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 3, 'Ba lafatenge, lafakaoni''ö ia. Ba so Yerobeamo, awö Ndraono Gizeraeli sato, fefu, ba fahuhuo ira khö Rehabeamo, lamane:', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 4, 'Kalo mbagi safökhö nihare''ö namau khöma; ba ya''ugö, ba kaohasi khöma rodi sabe''e andrö, kalo mbagi safökhö andrö, nihare''ö namau khöma, ba barö mbawau so ndra''aga.', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 5, 'Ba mane khöra: Mihonogö ami ua, tölu bongi, ba mifuli ami khögu. Ba mofanö niha sato.', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 6, 'Ba mamagölö razo Rehabeamo ba zatua andrö, enoni namania mege, me lö si mate ia, imane: He wisa ba dödömi, hadia taŵa''ö ba niha andrö?', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 7, 'Ba lamane khönia: Na ö''o''ö khöra ma''ökhö, na alulu dödöu khöra, na öfondrondrongo khöra ba na öhaogö wehedeu khöra, ba lö''ö göi tebulö wolo''öra khöu.', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 8, 'Ba lö ibe''e ba dödönia niŵa''ö zatua andrö, itema mamagölö ba nono matua, si faziazia''a khönia,', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 9, 'si no möi enoninia, imane khöra: Ba ya''ami, ha miŵa''ö, he tawisa wanema li niha andrö, si no manguma''ö khögu: Kaohasi khöma galo mbagi andrö nihare''ö namau khöma?', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 10, 'Ba latema linia ono matua andrö, si faziazia''a khönia, lamane: ömane wanema li niha andrö, sanguma''ö khöu: Amau, ba no kalo mbagi safökhö ihare''ö khöma, ba ya''ugö, ba kaohasi ia khöma — ömane khöra: Turugu si akhi, ba no esolo, moroi ba lafoyo namagu!', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 11, 'Ba lau, na no kalo mbagi safökhö nihare''ö namagu khömi, ba ya''o, ba udou''ö na galo mbagi andrö; na no i''otu''ö ami bözi-bözi amagu, ba ya''o, ba "tongo" uhalö ba wangotu''ö ya''ami!', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 12, 'Ba la''ondrasi Rehabeamo ira Yerobeamo, awö niha sato fefu, me no aefa zi tölu bongi andrö, dali niŵa''ö razo, me imane: Tölu bongi, ba mifuli ami khögu!', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 13, 'Ba sabe''e wehede razo ba niha sato, lö i''o''ö niŵa''ö zatua andrö khönia,', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 14, 'niŵa''ö nono matua andrö ibe''e dali, me imane khöra: Na no kalo mbagi safökhö nihare''ö namagu khömi, ba ya''o, ba udou''ö na galo mbagi andrö; na no i''otu''ö ami bözi-bözi amagu, ba ya''o ba "tongo" uhalö, ba wangotu''ö ya''ami!', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 15, 'Tobali lö ifondrondrongo razo niŵa''ö zato; noa sa Yehowa zamatörö da''ö, ena''ö i''aro''ö linia andrö, nifaŵa''ögönia khö Gahia andrö, banua Zilo, khö Yerobeamo, ono Nebati.[2]', '["Ayati 1—19: Nga''ötII 10","Faigi 11:31"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 16, 'Ba me aboto ba dödö Ndraono Gizeraeli fefu, lö ifondrondrongo khöra razo, ba latema li razo, lamane: "Hadia gurakhama khö Dawido? Lö ondröita nono Giza''i khöma! Mifuli ami ba khömi, ya''ami Iraono Gizeraeli! Ba faigi, he öwisa yomo khöu, ya''ugö Dawido!" Ba mangawuli ba khöra Ndraono Gizeraeli.[3]', '["SamII 20:1","Faigi 4:6"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 17, 'Ba ba Ndraono Gizeraeli ba mbanua mado Yuda misa, ba no Rehabeamo razo.', '["SamII 20:1","Faigi 4:6"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 18, 'Ba me ifatenge razo Rehabeamo mandru rodi andrö Adonira, ba latebu kara Iraono Gizeraeli fefu, labunu. Ba maoso razo Rehabeamo, itibo''ö tou ia, moroi ba guretania, moloi, isaŵa Yeruzalema.[4]', '["SamII 20:1","Faigi 4:6"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 19, 'Ba tobali fabali ba nga''ötö Dawido Ndraono Gizeraeli, irugi ma''ökhö andre.', '["SamII 20:1","Faigi 4:6"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 20, 'Ba me larongo Iraono Gizeraeli fefu, no mangawuli Yerobeamo, ba lafatenge, lafakaoni''ö ia ba walukhata, ba lafataro razo ia, razo Ndraono Gizeraeli fefu. Lö solo''ö nga''ötö Dawido, ha mado Yuda.', '["SamII 20:1","Faigi 4:6"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 21, 'Ba me no irugi Yeruzalema Rehabeamo, ba ifalukha''ö ma''uwu Yuda fefu, awö mado Mbeniyami, 180.000 zabölö, ba wanuwö Iraono Gizeraeli, ena''ö mangawuli khö Rehabeamo, ono Zelomo, wa''arazo.', '[]', NULL),
  (3475042, 'OT', 'Razo I', 12, 22, 'Ba humede Lowalangi khö Zemaya, enoni Lowalangi andrö, imane:', '[]', NULL),
  (3475042, 'OT', 'Razo I', 12, 23, 'Hede khö Rehabeamo andrö, ono Zelomo, razo mado Yuda, ba ba ma''uwu Yuda ba ba ma''uwu Mbeniyami, fefu, ba ba niha bö''ö andrö, ömane:', '[]', NULL),
  (3475042, 'OT', 'Razo I', 12, 24, 'Da''ö niŵa''ö Yehowa: Böi mi''ae''e; böi misuwö dalifusömi Iraono Gizeraeli: yamufuli ia ba khöra zamösana, me no ya''odo zamatörö da''ö! Ba me larongo li Yehowa, ba lafuli ira, mofanö ira, la''o''ö goroisa Yehowa.', '[]', NULL),
  (3475042, 'OT', 'Razo I', 12, 25, 'Ba i''aro''ö Zikhema ba hili mado Geferayi Yerobeamo, ba ba da''ö i''iagö; ba aefa da''ö, ba mofanö ia, iröi Zikhema ba i''aro''ö Wenieli.[5]', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 26, 'Ba imane dödönia Yerobeamo: Te sa mangawuli dania ba nga''ötö Dawido wa''arazo.', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 27, 'Na möi misi yaŵa dania niha, ba wame''e sumange nitaba, ba gosali Yehowa ba Yeruzalema, ba ifuli adöni dödöra khö zokhö ya''ira andrö, Rehabeamo, razo mado Yuda, ba labunu ndra''o, ba lafuli ira khö Rehabeamo andrö, razo mado Yuda.', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 28, 'Andrö i''era-era tödönia razo, ba dua rozi ifalau''ö ono zaŵi, balaki, ba imane ba zato: Biha sa''ae we''amöi-möimi ba Yeruzalema! Hiza Lowalangimi, ya''ami Iraono Gizeraeli, solohe miyaŵa ya''ami mege, moroi ba danö Miserayi.[6]', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 29, 'Ba ba Mbetieli ibe''e zi sara, ba si sara, ba ba Dano.', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 30, 'Ba tobali horö ba Lowalangi da''ö.', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 31, 'Ba ifalau''ö göi gosali ba hili misa, ba gofu ha niha manö ifataro ere, si tenga mado Lewi.[7]', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 32, 'Ba ilau gowasa Yerobeamo ba zi mewelelima ba mbaŵa si ŵalu, dali gowasa andrö ba mado Yuda; ba möi ia miyaŵa ba naha wame''e sumange. Si manö wolaunia ba Mbetieli, ba wanaba sumange ba nono zaŵi andrö, nifalau''önia, ba ifataro ba halöŵöra ba Mbetieli gere hili-hili andrö, niŵa''önia.', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475042, 'OT', 'Razo I', 12, 33, 'Ba möi ia miyaŵa ba naha wame''e sumange andrö, nifa''anönia ba Mbetieli, ba zi mewelelima ba mbaŵa si ŵalu, baŵa nikhoi dödönia, ba wolau owasa ba Ndraono Gizeraeli. Ba möi ia miyaŵa ba naha wame''e sumange, ba wanunu kumöyö.', '["MozI 32:30","MozII 32:4","MozIV 3:10; Nga''ötII 11:15"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 1, 'Ba hiza genoni Lowalangi, mado Yuda, niŵa''ö Yehowa, irugi si''aikö Mbetieli, me ba zinga naha wame''e sumange so Yerobeamo, ba wanunu kumöyö.', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 2, 'Ba ihede-hede''ö naha wame''e sumange, niŵa''ö Yehowa khönia, imane: He naha wame''e sumange! Da''ö niŵa''ö Yehowa: So dania nga''ötö Dawido, Yosia döinia, sanaba bagi gere hili-hili andrö ba detemö, bagi gere sanunu kumöyö ba detemö iada''e, ba töla niha itunu ba detemö![1]', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 3, 'Ba i''ombakha''ö dandra me luo da''ö, imane: Da''ö dania dandra, wa no Yehowa zanguma''ö: Si fabali dania naha wame''e sumange andrö ba muzaewe nawu dawö andrö, si so ba detenia.', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 4, 'Ba me irongo razo niŵa''ö genoni Lowalangi andrö, fanegunia naha wame''e sumange andrö ba Mbetieli, ba i''oro''ö dangania, moroi ba zinga naha wame''e sumange, imane: Mira''u ia! Ba oköliköli dangania, ni''oro''önia ba khönia, ba tebai ifuli iböda.', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 5, 'Ba fabali naha wame''e sumange no mege, ba muzaewe nawu dawö andrö moroi yaŵa, itörö dandra andrö ni''ombakha''ö genoni Lowalangi andrö, niŵa''ö Yehowa khönia.', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 6, 'Ba humede razo, imane khö genoni Lowalangi andrö: Tema andrö wa''ahakhö dödö Lowalangiu Yehowa, andrö khönia, salahigu, ena''ö u''ila ufuli uböda dangagu! Ba i''andrö wa''ahakhö dödö Yehowa enoni Lowalangi andrö, ba i''ila ifuli iböda dangania razo, tobali si mane mege.', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 7, 'Aefa da''ö ba humede zui razo khö genoni Lowalangi andrö, imane: Tabu ba nomogu, lau manga, ba mamuala ndra''o khöu!', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 8, 'Ba imane enoni Lowalangi andrö khö razo: Ba he öbe''e khögu zi matonga zi so khöu, fefu, ba lo''ö zui möido awöu; lö mangado ba lö ubadu nidanö ba khömi andre.', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 9, 'Noa sa muŵa''ö khögu, taroma li Yehowa, no imane: Lö tola manga''ö, ba lö tola öbadu nidanö ba lö tola ötörö mangawuli lalamö mege, me so''ö!', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 10, 'Ba mofanö ia, itörö lala bö''ö, lö ifuli itörö lalania mege, me awena möi ia ba Mbetieli.', '["RazII 23:15,16; Yes 44:28"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 11, 'Ba so ba Mbetieli zama''ele''ö satua; khönia möi ndraononia ba ladunö-dunö khönia fefu hadia ia nilau genoni Lowalangi andrö ba Mbetieli, me luo da''ö, ba hadia huhuonia khö razo. Ba me no la''ombakha''ö da''ö khö namara,', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 12, 'ba isofu khöra amara, imane: Heza itörö ba wangawuli? Ba latuturu khönia ira ononia lala nitörö genoni Lowalangi andrö, si otarai ba mado Yuda.', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 13, 'Ba imane ba ndraononia: Mifosela khögu galide. Ba me no lafosela galide, ba möi ia yaŵa, fakudo ia,', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 14, 'i''o''ö genoni Lowalangi andrö ba ikhamö ia, me dumadao ia ba mbörö manawa andrö. Ba imane khönia: Hadia, ya''ugö genoni Lowalangi andrö, si otarai mado Yuda? Ba imane: Ya''ia.', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 15, 'Ba imane khönia: Tabu awögu ba lau manga.', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 16, 'Ba imane: Tebai mangado ba lö ubadu nidanö ba da''e.', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 17, 'Noa sa mufa''ema khögu li Yehowa, imane: Lö tola manga''ö ba lö tola öbadu nidanö, ba lö tola öfuli ötörö lalamö mege, me awena so''ö!', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 18, 'Ba imane khönia sama''ele''ö andrö: Sama''ele''ö göi ndra''odo, si mane ya''ugö, ba no muhede khögu mala''ika, niŵa''ö Yehowa, no imane: Ohe mangawuli ia, awöu, ena''ö manga ia ba ena''ö ibadu nidanö. Ba fayania.', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 19, 'Ba ifuli ia, awönia, manga ia khö zama''ele''ö andrö ba mamadu idanö.', '[]', NULL),
  (3475043, 'OT', 'Razo I', 13, 20, 'Ba barö wemangara andrö, ba humede Yehowa khö zama''ele''ö andrö, solohe mangawuli ya''ia.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 21, 'Ba amaedola ihangoi genoni Lowalangi andrö, si otarai mado Yuda, imane: Da''ö niŵa''ö Yehowa: Me no lö nifondrondrongou niŵa''ö Yehowa, ba me lö nitöngöniu oroisa andrö, nibe''e Lowalangiu Yehowa khöu, me no öfuli ndra''ugö,', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 22, 'me no manga''ö ba me no öbadu nidanö ba mbanua andrö niŵa''önia khöu: Lö tola manga''ö ba lö tola öbadu nidanö! ba lö möi ba lewatö ndra tuau dania mbotou!', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 23, 'Ba me no manga ia ba me no ibadu nidanö, ba lafosela khönia galide zama''ele''ö andrö, solohe mangawuli ya''ia mege.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 24, 'Ba me no mofanö ia, ba falukha khönia zingo, ba lala, samunu ya''ia. Ba adölö manö ba lala mbotonia, ba kalidenia ba singo andrö, ba no so ba ngai mboto.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 25, 'Ba me so zanörö, ba la''ila mboto zi mate andrö, si no adölö ba lala, ba hiza zingo andrö ba ngainia. Ba möi ira mu''ombakha''ö yomo ba mbanua andrö, ba zi so sama''ele''ö satua andrö.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 26, 'Ba me irongo sama''ele''ö andrö, solohe mangawuli ya''ia mege, ba imane: Enoni Lowalangi andrö, si lö molo''ö oroisa Yehowa mege, andrö ilulu ba mbawa zingo ia Yehowa: da''ö zi bohagö ya''ia ba samunu, itörö li Yehowa andrö, niŵa''önia khönia.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 27, 'Ba imane ba ndraononia: Mifosela khögu galide!', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 28, 'Ba lafosela. Ba fakudo ia, isaŵa, ba hiza mbotonia no mege, no adölö ba lala, ba kalide ba singo ba ngai mboto zi mate. Lö ni''a zingo boto zi mate ba lö nisasawinia kalide.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 29, 'Ba ituyu mboto genoni Lowalangi andrö sama''ele''ö andrö, ihare''ö ba hulu galide, ba i''ohe mangawuli. Ba irugi mbanuara, ba wange''esi si mate andrö ba ba wogo''o ya''ia.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 30, 'Ba ba lewatönia ibe''e mboto zi mate andrö, ba la''e''esi: Alai ndra''o ndra''ugö ga''a![2]', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 31, 'Ba me no iko''o, ba imane ba ndraononia: Na no mate ndra''o, ba ba lewatö ba niko''o enoni Lowalangi andrö miko''o ndra''o; ba ngai dölania mibe''e dölagu, fa böi lafufu dania dölama, daruaga.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 32, 'Lö''ö sa zi lö itörö dania nidaö''ö-daö''önia, niŵa''ö Yehowa khönia, ba naha wame''e sumange andrö ba Mbetieli ba ba gosali ba hili-hili andrö, ba mbanua Zamaria misa, fefu.', '["RazII 23:17; Yer 22:18"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 33, 'Ba he me no aefa da''ö no mege, ba lö''ö sa iböhöli lala si lö sökhi andrö khönia Yerobeamo, ifuli a''ine ifataro ere ba hili-hili andrö gofu ha niha manö. Ha niha zomasi, ba ifo''ösi danga ba tobali ere ba hili-hili andrö.[3]', '["MozII 28:41"]', NULL),
  (3475043, 'OT', 'Razo I', 13, 34, 'Ba tobali horö zi samba omo ndra Yerobeamo da''ö, tobali famakikora ba fangohori ya''ira ba guli danö dania.', '["MozII 28:41"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 1, 'Me luo da''ö, ba mofökhö Gahia, ono Yerobeamo.', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 2, 'Ba imane Yerobeamo khö wo''omonia: Labu, onukha nukha niha bö''ö, fa böi oroma ba niha, wa fo''omo Yerobeamo ndra''ugö, ba ae ba Zilo. Tenga ba da''ö so Gahia andrö, sama''ele''ö, sanguma''ö no, wa razo ndra''o, razo soi andre?[1]', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 3, 'Ba fulu ohe roti ba kue, ba ŵe ŵani, samba migö, ba ae yomo khönia. Ba i''ombakha''ö dania khöu, he wisa khö nono andrö.', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 4, 'Ba i''o''ö da''ö fo''omo Yerobeamo, maoso ia, isaŵa Zilo, möi ia yomo khö Gahia. Ba Ahia andrö, ba lö''ö sa''ae i''ila niha, no abösi hörönia, me no atua sibai ia.', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 5, 'Ba no imane Yehowa khö Gahia: Hiza, so wo''omo Yerobeamo, ba wanofu khöu, he wisa khö nononia, sofökhö; ba ombakha''ö khönia niŵa''ögu khöu. Ba irugi fo''omo razo, ba ibini''ö wa ya''ia.', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 6, 'Ba irongo Ahia hozihozi gahenia, me möi ia yomo, ba imane: Ae yomo, fo''omo Yerobeamo, hana wa öbini''ö na, wa ya''ugö, me no safökhö niŵa''ö khögu, nifa''ema khöu?', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 7, 'Ae ŵa''ö khö Yerobeamo: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli; börö me no utuyu ndra''ugö bakha ba hunö niha sato, ba me no ufataro razo ndra''ugö, razo mbanuagu Iraono Gizeraeli,', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 8, 'ba me no uheta ba danga nga''ötö Dawido wa''arazo ba me no ube''e khöu — ba ya''ugö, ba no tenga si mane enonigu Dawido, si no manöngöni oroisagu ba si no a''oi tödö wolo''ö khögu, ba ha sambalö somasi ndra''o ilau;[2]', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 9, 'tobali sa no ebua zi lö sökhi nilaumö, moroi ba nilau zi so fönau mege, fefu: no möi''ö mamazökhi khöu Lowalangi bö''ö, adu nifahele, ba wangandrö fönugu, ba ya''o, ba no ö''erogö:[3] —', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 10, 'Andrö ufatörö sa''ae wamakiko ba zi samba omo ndra Yerobeamo ba uhori khö Yerobeamo zi kiöni bagolö, iraono ba satua ba Ndraono Gizeraeli, ba ubözini zi samba omo ndra Yerobeamo, nifamözini sasao, irege no ahori ira fefu.[4]', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 11, 'Si mate yomo ba mbanua, ba zi samba omo ndra Yerobeamo, ba ö nasu; ba si mate baero ba mbenua, ba ö wofo ba dalu mbanua; noa sa Yehowa zanguma''ö!', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 12, 'Ba ya''ugö, ba fuli''ö manö: na ihundragö aheu newali ba mbanua, ba mate nono matua andrö.', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 13, 'Ba la''e''esi dania ia Iraono Gizeraeli fefu, ba lako''o ia; ha sa ya''ia ba zi samba omo ndra Yerobeamo zi möi ba lewatö, me no ba khönia falukha na ma''ifu zomasi Lowalangi Ndraono Gizeraeli, Yehowa, ba zi samba omo ndra Yerobeamo.', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 14, 'Ba i''asogö khönia Yehowa razo Ndraono Gizeraeli sangohori si sawu ndra Yerobeamo. Ba he wisa iada''e sa''ae?[5]', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 15, 'Ba ibözi Ndraono Gizeraeli Yehowa, si mane sukhu si heuheu ba nidanö, ba ideha ira ba danö si sökhi andre, nibe''enia khö ndra tuara mege, ba ifazawili ira miyefo mboto nidanö andrö [Oifarati], börö Gasera andrö khöra, nifazökhira, wangandrö fönu Yehowa.[6]', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 16, 'Ba ilulu Ndraono Gizeraeli, börö horö Yerobeamo andrö, nifazökhinia ba ba nifaelungunia Iraono Gizeraeli!', '["Faigi 11:31","SamI 13:14; Sin 89:21","Neh 9:26; Sin 89:21","SamI 25:22; MozV 32:36","Faigi 15:29","Sanguhuk 6:25"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 17, 'Ba ifuli ia fo''omo Yerobeamo ba irugi Dirisa, ba me ihundragö si''aikö mbagi nora yomo, ba mate nono no mege.', '[]', NULL),
  (3475044, 'OT', 'Razo I', 14, 18, 'Ba lako''o ia, ba la''e''esi ia Iraono Gizeraeli fefu, itörö niŵa''ö Yehowa, nifa''ema genoninia Ahia andrö sama''ele''ö.', '[]', NULL),
  (3475044, 'OT', 'Razo I', 14, 19, 'Ba hadia nidunö-dunö na ena''ö, ba khö Yerobeamo andrö, he wisa wanuwönia ba fa''arazonia, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '[]', NULL),
  (3475044, 'OT', 'Razo I', 14, 20, 'Ba fa''ara wa''arazo Yerobeamo, ba no 22 fakhe. Ba mate ia, itörö lala ndra amania, ba ononia Nadabi razo, fangalinia.', '[]', NULL),
  (3475044, 'OT', 'Razo I', 14, 21, 'Ba razo ba mado Yuda, ba Rehabeamo, ono Zelomo.[7] Öfa wulu a sara fakhe Rehabeamo, me tobali razo ia, ba mewelewitu fakhe razo ia ba Yeruzalema, ba mbanua andrö, nituyu Yehowa ba mado Ndraono Gizeraeli fefu, nahia döinia. Ba töi ninania, ba Na''ama, Iraoni Gamoni.[8]', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 22, 'Ba mado Yuda andrö, ba lalau zi fatuwu khö Yehowa, abölö afökhö dödönia labe''e, moroi ba wa''afökhö dödönia ba nilau ndra tuara mege, fefu, börö horöra andrö, nifazökhira.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 23, 'Ya''ira sa''ae göi, ba lafa''anö khöra naha wame''e sumange ba hili-hili ba harefa ba Asera, ladozigö hili-hili salaŵa ma''ifu ba ba mbörö geu sauri fefu.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 24, 'Ba so göi zohorö ba danö, la''o''ö zogoro ita andrö ba niha baero andrö, nitimba Yehowa föna Ndraono Gizeraeli.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 25, 'Ba me no alua mendröfa fakhe razo Rehabeamo, ba so moroi si tou Zizaki, razo Miserayi, möi musuwö Yeruzalema,[9]', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 26, 'ihalö girö-girö andrö ba gosali Yehowa, awö girö-girö ba gödo razo; ahori manö ihalö, fabaya dange andrö ba baluse andrö, ana''a, fefu, nibago Zelomo.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 27, 'Ba ifafazökhi''ö fangali, töla, razo Rehabeamo ba ibe''e ba danga gumandra wazuri andrö, sanaronaro ba zinga mbawandruhö gödo razo.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 28, 'Ba ero na möi ba gosali Yehowa razo, ba la''ohe fazuri, ba lafulifuli ba naha wazuri.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 29, 'Ba hadia na nidunö-dunö ena''ö ba khö Rehabeamo andrö, hadia fefu nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475044, 'OT', 'Razo I', 14, 30, 'Ba fazuwözuwö manö ira Rehabeamo Yerobeamo, sagötö ya''ira.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475044, 'OT', 'Razo I', 14, 31, 'Ba mate Rehabeamo, itörö lala ndra amania, ba ba lewatö ndra amania, ba mbanua Dawido lako''o ia. Ba töi ninania ba Na''ama, Iraono Gamoni. Ba si tobali razo fangalinia, ba ononia Abia.', '["Ayati 21—31: Nga''ötII 12","Nga''ötII 12:13","Nga''ötII 12:5"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 1, 'Ba me no alua mewelewitu fakhe razo Yerobeamo andrö, ono Nebati, ba tobali razo mado Yuda Gabia.[1]', '["Ayati 1—8: Nga''ötII 13","Faigi 11:36","SamII 11:6 b.t.","Nga''ötII 14:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 2, 'Medölu fakhe razo ia ba Yeruzalema; ba töi ninania, ba Ma''akha, ono Gabisalomi.', '["Ayati 1—8: Nga''ötII 13","Faigi 11:36","SamII 11:6 b.t.","Nga''ötII 14:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 3, 'Ba itörö lala si lö sökhi andrö khö namania, horö andrö fefu, nifazökhi da''ö, fönania, ba lö adölö dödönia khö Lowalanginia, Yehowa, tenga si mane tödö duania Dawido.', '["Ayati 1—8: Nga''ötII 13","Faigi 11:36","SamII 11:6 b.t.","Nga''ötII 14:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 4, 'Börö sa Dawido, wa ibe''e khönia wandru ba Yeruzalema Lowalanginia, Yehowa, wa ibe''e auri nononia furinia, awö wa lö ibe''e adudu Yeruzalema,[2]', '["Ayati 1—8: Nga''ötII 13","Faigi 11:36","SamII 11:6 b.t.","Nga''ötII 14:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 5, 'me no ilau zomasi Yehowa Dawido, lö hadia ia zi lö itörö ni''oroi''önia khönia, sagötö ya''ia, ha ba khö Guria andrö, Iraono Kheti.[3]', '["Ayati 1—8: Nga''ötII 13","Faigi 11:36","SamII 11:6 b.t.","Nga''ötII 14:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 6, 'Ba fazuwözuwö manö ira Rehabeamo Yerobeamo, sagötö ya''ia.', '["Ayati 1—8: Nga''ötII 13","Faigi 11:36","SamII 11:6 b.t.","Nga''ötII 14:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 7, 'Ba hadia nidunö-dunö na ena''ö ba khö Gabia andrö, fefu hadia ia nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda. Ba fasuwö ira Gabia Yerobeamo.', '["Ayati 1—8: Nga''ötII 13","Faigi 11:36","SamII 11:6 b.t.","Nga''ötII 14:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 8, 'Ba mate Gabia, itörö lala ndra amania, ba ba mbanua Dawido lako''o ia. Ba razo fangalinia, ba ononia Asa.[4]', '["Ayati 1—8: Nga''ötII 13","Faigi 11:36","SamII 11:6 b.t.","Nga''ötII 14:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 9, 'Me no alua sara ambö dua wulu fakhe razo Ndraono Gizeraeli Yerobeamo tobali razo mado Yuda Asa andrö.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 10, 'Ba 41 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Ma''akha ono Gabisalomi.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 11, 'Ba somasi Yehowa ilau Asa, si mane tuania Dawido.[5]', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 12, 'Itibo''ö zohorö andrö ba ihori nadu andrö fefu, nifazökhi ndra tuania.[6]', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 13, 'Ba iheta göi ninania Ma''akha, fa böi sa''ae salaŵa ia, me no ifazökhi nadu khö Gasera andrö. I''eŵa nadu andrö khönia Asa ba itunu ba ndraso Kendrona.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 14, 'Ba hili-hili andrö, ba lö''ö sa ibulö''ö. Ba tödö Asa andrö, ba noa sa adölö manö khö Yehowa, sagöto ya''ia.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 15, 'Ba ifabe''e''ö ba gosali Yehowa ni''amoni''ö namania, awö ni''amoni''önia — firö ba ana''a ba gama-gama.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 16, 'Ba fazuwözuwö ira Asa Mbaesa, razo Ndraono Gizeraeli, sagötö ya''ira.[7]', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 17, 'Möi musuwö mado Yuda Mbaesa, razo Ndraono Gizeraeli, i''aro''ö Rama, fa böi mangörö-ngörö niha khö Asa, razo mado Yuda.[8]', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 18, 'Ba ihalö Asa wirö ba ana''a fefu, si tosai na ba naha girö-girö ba gasali Yehowa, awö girö-girö ba gödo razo, ba ibe''e ba danga genoninia; ba ifatenge ira khö Mbenihada andrö, ono Dabirimo, ma''uwu Heziono, razo Ndrawa Garamo, ba Ndramaseko, imane khönia:', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 19, 'No fawu''u li ita, ba no fawu''u li ira namagu namamö. Hiza, ufa''ohe''ö khöu mbuala, firö ba ana''a; ba ae dudugö wawu''usa li andrö khönia Baesa, razo Ndraono Gizeraeli, ena''ö iböhöli wanuwö ya''odo.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 20, 'Ba i''o''ö khö razo Asa Benihada ifatenge gumandra andrö khönia, ba wanuwö banua Ndraono Gizeraeli ba lafufu Iyono ba Dano ba Habeli Beti Ma''akha ba tanö Kineroti, ma''asagörö, fabaya tanö mado Nafetali ma''afefu.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 21, 'Ba me irongo da''ö Baesa ba iböhöli wangaro''ö Rama, ifuli ia ba Dirisa.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 22, 'Ba i''owuloi mado Yuda fefu razo Asa — samösa lö iröi furi. Ba lahalo gara andrö, awö geu balo, ni''oguna''ö Mbaesa ba wangaro''ö Rama ba ibe''e fangaro Geba ba mado Mbeniyami razo Asa, ba fangaro Misefa.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 23, 'Ba hadia na ena''ö nidunö-dunö ba khö Asa andrö, ba fa''abölönia andrö fefu, ba hadia ia nilaunia, fefu, ba banua andrö, ni''aro''önia, ba noa sa mutanö ba zura hikaya razo mado Yuda. Ba ba wa''atuania, ba sofökhö ahe ia.', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 24, 'Ba mate Asa, itörö lala ndra amania, ba ba mbanua duania Dawido lako''o ia, ba ngai ndra tuania. Ba razo fangalinia, ba ononia Yozafati.[9]', '["Ayati 15:11—15: Nga''ötII 14:1—4; 15:16—18","Faigi 22:47","Ayati 16—24: Nga''ötII 16:1—10","Nga''ötII 16:1 b.t.","Nga''ötII 17:1"]', NULL),
  (3475045, 'OT', 'Razo I', 15, 25, 'Ba Nadabi, ono Yerobeamo, zi tobali razo Ndraono Gizeraeli, me no arakha mendrua fakhe razo Asa, ba mado Yuda, ba mendrua fakhe razo Nadabi andrö, ba Ndraono Gizeraeli.', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 26, 'Ba si fatuwu khö Yehowa ilau, itörö lala namania andrö, horönia andrö, famaelungunia Iraono Gizeraeli.', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 27, 'Ba maoso udunia Mbaesa andrö, ono Gahia, mado Isasari, mamagölö ia ba niha bö''ö, ba ibunu Nadabi, ba Gibetono, banua Ndrawa Wilisiti; sanuwö Gibetono Nadabi ba Iraono Gizeraeli fefu, me luo da''ö.', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 28, 'Ba tobali ibunu Nadabi Baesa, me no arakha medölu fakhe razo mado Yuda Asa andrö, ba tobali razo Mbaesa, fangali Nadabi.', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 29, 'Ba me no razo ia, ba ibunu nga''ötö Yerobeamo, fefu, samösa lö isaigö motöi nga''ötö Yerobeamo, si so noso, ihori manö, dali niŵa''ö Yehowa, nifa''ema genoninia Ahia, banua Zilo,[10]', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 30, 'börö horö Yerobeamo andrö, nifazökhinia, famaelungunia Iraono Gizeraeli, wangandrö fönu Lowalangi Ndraono Gizeraeli, Yehowa.', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 31, 'Ba hadia na ena''ö nidunö-dunö ba khö Nadabi andrö, hadia ia fefu, nilaunia, ba no mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 32, 'Ba fazuwözuwö ira Asa Mbaesa andrö, razo Ndraono Gizeraeli, sagötö ya''ira.', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 33, 'Ba me no arakha medölu fakhe razo mado yuda Asa, ba tobali razo Ndraono Gizeraeli fefu Mbaesa andrö, ono Gahia, ba 24 fakhe razo ia ba Dirisa.', '["Faigi 14:10 b.t."]', NULL),
  (3475045, 'OT', 'Razo I', 15, 34, 'Ba si fatuwu khö Yehowa ilau, itörö lala Yerobeamo andrö ba horö andrö ba nifaelungunia Iraono Gizeraeli.', '["Faigi 14:10 b.t."]', NULL),
  (3475046, 'OT', 'Razo I', 16, 1, 'Ba humede Yehowa khö Yehu andrö, ono Hanani, fanegu Mbaesa andrö, imane:[1]', '["Nga''ötII 16:7; 19:2; 20:32","Faigi 14:11","Faigi 15:29"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 2, 'Me no tou ba danö utuyu ndra''ugö ba me no ufataro''ö razo mbanuagu Iraono Gizeraeli, ba me noa zui ötörö lala Yerobeamo andrö ba me no öfowöhö mbanuagu Iraono Gizeraeli, ba wamazökhi horö, fa la''andrö wönugu, ba horöra andrö,', '["Nga''ötII 16:7; 19:2; 20:32","Faigi 14:11","Faigi 15:29"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 3, 'ba hiza, ba uhori Mbaesa, fabaya nga''ötönia, ba ufatörö ba zi sawu ya''ami nifatörögu ba zi sawu ndra Yerobeamo andrö, ono Nebati.', '["Nga''ötII 16:7; 19:2; 20:32","Faigi 14:11","Faigi 15:29"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 4, 'Si mate yomo ba mbanua, soroiyomo Mbaesa, ba ö nasu, ba si mate baero ba mbenua, ba ö wofo ba dalu mbanua.[2]', '["Nga''ötII 16:7; 19:2; 20:32","Faigi 14:11","Faigi 15:29"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 5, 'Ba hadia na ena''ö nidunö-dunö ba khö Mbaesa andrö, hadia nilaunia, ba fa''abölönia andrö, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["Nga''ötII 16:7; 19:2; 20:32","Faigi 14:11","Faigi 15:29"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 6, 'Ba mate Mbaesa, itörö lala ndra amania ba ba Dirisa lako''o ia. Ba ononia Ela zi tobali razo, fangalinia.', '["Nga''ötII 16:7; 19:2; 20:32","Faigi 14:11","Faigi 15:29"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 7, 'Ba no ifa''ema sama''ele''ö andrö, Yehu, ono Hanani, niŵa''ö Yehowa fotu Mbaesa, fabaya si samba omo ya''ira; sambalö, ba zi lö sökhi andrö fefu, nilaunia, wamaigi Yehowa, me no i''andrö wönu Yehowa, ba nifazökhi dangania andrö, fa ifatörö khönia nifatörönia ba zi samba omo ndra Yerobeamo, ba sambalö, ba me no ihori da''ö.[3]', '["Nga''ötII 16:7; 19:2; 20:32","Faigi 14:11","Faigi 15:29"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 8, 'Me no alua 25 fakhe razo mado Yuda Asa, ba tobali razo Ndraono Gizeraeli Ela andrö, ono Mbaesa, ba mendrua fakhe razo ia ba Dirisa.', '["RazII 9:31"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 9, 'Ba ilaŵa ia enoninia Simeri, kumandra zi matonga gureta andrö, mamagölö ia ba niha bö''ö. Ba me no mabu agu Ela, ba Dirisa, ba nomo Garasa, mandru ba gödo ba Dirisa,', '["RazII 9:31"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 10, 'ba so moroi tou Zimeri, ibunu Ela, me no alua 26 fakhe razo mado Yuda Asa andrö: ba tobali razo Zimeri, fangali Ela.[4]', '["RazII 9:31"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 11, 'Ba me no razo ia, me no dumadao ia ba dadaomania, ba ibunu fefu motöi si samba omo ndra Baesa, ma''ifu lö isaigö, irege zi kiöni bagolö, fabaya talifusöra ba si fahuwu khöra.', '["RazII 9:31"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 12, 'Tobali ihori zi samba omo ndra Baesa Simeri, dali niŵa''ö Yehowa andrö, nifa''ema Yehu, sama''ele''ö andrö,', '["RazII 9:31"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 13, 'fotu ba horö Mbaesa, börö horö Mbaesa andrö fefu, awö horö nononia Ela, nifazökhira, famaelungura Iraono Gizeraeli, fa la''andrö wönu Lowalangi Ndraono Gizeraeli, Yehowa, ba nadu faya andrö khöra.', '["RazII 9:31"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 14, 'Ba hadia na ena''ö nidunö-dunö ba khö Ela andrö, ba hadia ia fefu, nilaunia, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["RazII 9:31"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 15, 'Me no alua 26 fakhe razo mado Yuda Asa, tobali razo Zimeri andrö, ha fitu bongi, ba Dirisa, me luo lasuwö Gibetono sato, Gibetono banua Ndrawa Wilisiti.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 16, 'Ba me larongo niha sato, ba golombaseŵa, no mamagölö ba niha bö''ö Zimeri, ba no ibunu razo, ba latema lafataro razo Omeri andrö, kumandra sebua khöra, Iraono Gizeraeli fefu, me luo da''ö, ba da''ö, ba golombaseŵa.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 17, 'Ba iröi Gibetono Omeri, i''ohe Ndraono Gizeraeli fefu, möi ira musuwö Dirisa.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 18, 'Ba me i''ila Simeri atu''a ira ba mbanua, ba möi ia ba gödo razo, ba itunu gödo yaŵania, ba mate ia, akhozi,', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 19, 'börö horönia andrö, nifazökhinia, wolau si fatuwu khö Yehowa, wanörö lala Yerobeamo andrö, fabaya horönia andrö, nifazökhinia, wamaelungu ba horö Iraono Gizeraeli göi.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 20, 'Ba hadia na ena''ö nidunö-dunö ba khö Zimeri andrö ba famagölönia andrö, folaŵania, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 21, 'Ba me luo da''ö ba fabali Ndraono Gizeraeli. Si matonga niha sato, ba khö Dibini, ono Ginata, la''o''ö, ba wamataro razo da''ö, ba si matonga, ba si lö aefa khö Omeri.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 22, 'Ba abölö zi fao khö Omeri, moroi ba zi fao khö Dibini, ono Ginata. Ba mate Dibini, ba tobali razo Omeri.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 23, 'Me no alua 30 fakhe razo mado Yuda Asa tobali razo Ndraono Gizeraeli Omeri andrö, mewelendrua fakhe; meönö fakhe ba Dirisa.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 24, 'Ba i''öli hili Zamaria andrö, khö Zemeri, 8824 rufia, ba i''aro''ö hili andrö, ba Samaria ibe''e töi mbanua andrö, nitaru''önia, i''ohia''ö döi Zemeri andrö, sokhö hili andrö mege.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 25, 'Ba si fatuwu khö Yehowa ilau Omeri, abölö-bölö walösökhi, moroi ba razo fönania mege fefu;', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 26, 'itörö sibai lala Yerobeamo andrö, ono Nebati, awö horönia andrö, famaelungunia Iraono Gizeraeli, fa la''andrö wönu Lowalangi Ndraono Gizeraeli, Yehowa, ba nadu faya andrö khöra.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 27, 'Ba hadia na ena''ö nidunö-dunö ba khö Omeri andrö, ba hadia ia fefu nilaunia, ba fa''abölönia andrö, ni''oroma''önia, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 28, 'Ba mate Omeri, itörö lala ndra amania, ba ba Zamaria lako''o ia. Ba razo fangalinia, ba ononia Ahabi.', '[]', NULL),
  (3475046, 'OT', 'Razo I', 16, 29, 'Me no alua 37 fakhe razo mado Yuda Asa, tobali razo Ndraono Gizeraeli Gahabi andrö, ono Omeri, ba 22 fakhe razo ia ba Zamaria.', '["MozV 7:3","Yos 6:26"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 30, 'Ba si fatuwu khö Yehowa ilau Ahabi, ono Omeri; abölö-bölö walösökhi, moroi ba razo fönania fefu.', '["MozV 7:3","Yos 6:26"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 31, 'Ba side-idenia na, wa ifazökhi göi horö Yerobeamo, ono Nebati; ba ihalö Izebela andrö, ono Etiba''ali, razo Zidona, ba möi ia mamosumange Ba''ali andrö, awö we''angaröfi li ya''ia.[5]', '["MozV 7:3","Yos 6:26"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 32, 'Ba ifa''anö naha wame''e sumange khö Mba''ali, ba gosali Mba''ali andrö, nilaunia ba Zamaria.', '["MozV 7:3","Yos 6:26"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 33, 'Ba ifazökhi göi Gasera andrö Ahabi, ba ilau na göi wangala bö''ö, ba wangandrö fönu Lowalangi Ndraono Gizeraeli, Yehowa, abölö-bölö moroi ba razo Ndraono Gizeraeli fefu, fönania.', '["MozV 7:3","Yos 6:26"]', NULL),
  (3475046, 'OT', 'Razo I', 16, 34, 'Ba me luo razo ia ifuli itaru''ö Yerikho Hieli andrö, banua Mbetieli, ba mate nononia si a''a Abiramo, me ibe''e tou doyo, ba ononia si akhi, Segubi, me i''asiwai mbawa göli, itörö niŵa''ö Yehowa, nifa''ema Yosua, ono Nuni.[6]', '["MozV 7:3","Yos 6:26"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 1, 'Ba imane Eliya andrö, banua Disebe, ba danö Gileadi, khö Gahabi: Faya wa no sauri Yehowa, Lowalangi Ndraono Gizeraeli, si no möido enoni, na so namo mbanua ba he teu ba ndröfi andre, ha me uga fakhe, na tenga ya''o zanguma''ö![1]', '["Yak 5:17"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 2, 'Ba humede khönia Yehowa, imane:', '["Yak 5:17"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 3, 'Ofanö, tanö ba gatumbukha luo saŵa ba bini''ö ndra''ugö ba mbewe mbombo Keriti andrö, si handro Yoridano.', '["Yak 5:17"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 4, 'Ba öu idanö mbombo andrö, ba no uŵa''ö ba gaga, ena''ö la''uri ndra''ugö ba da''ö.', '["Yak 5:17"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 5, 'Ba i''o''ö niŵa''ö Yehowa, möi ia ba i''iagö mbewe mbombo Keriti andrö, si handro Yoridano.', '["Yak 5:17"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 6, 'Ba la''ohe-ohe khönia gaga kue ba diwo, ba zanguhulö wongi ba na tanö owi, ba önia idanö mbombo andrö.', '["Yak 5:17"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 7, 'Ba lö ara sibai, ba ogo''ö mbombo andrö, me lö''ö sa''ae teu ba danö.', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 8, 'Ba humede khönia Yehowa, imane:', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 9, 'Faoso, ae ba Zarefa, banua Zidona andrö, ba iagö da''ö; noa sa uŵa''ö ba ndra alawe ba da''ö, lakha mbanua, ena''ö i''uri ndra''ugö.[2]', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 10, 'Ba maoso ia, isaŵa Zarefa, ba me irugi mbawa göli mbanua, ba hiza ndra alawe, lakha mbanua, sangozaragö tuturu geu. Ba humede ia khönia, imane: Ta''u khögu nidanö ma''ifu ba nahia, ubadu!', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 11, 'Ba me möi mana''u, ba mu''ao na khönia Geliya, imane: Ohe göi khögu mato sambawa roti!', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 12, 'Ba imane: Faya wa no sauri Lowalangiu, Yehowa, na so khögu hadia ia zasoso, ha mato tambai tanga hamo ba rumbi ba ha ma''ifu wanikha ba migö; ba awena u''ozaragö geu ma''ifu, ba ufulido, ba wangasiwai khöma onogu, ba na no ma''a, ba hatö fa''amate.', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 13, 'Ba imane khönia Eliya: Böi busi dödöu! Ae''e, ba lau niŵa''öu andrö; ba ö''asiwai khögu ua zagörö kue side-ide ba ohe khögu baero; ba ömi onou, ba dania ö''asiwai.', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 14, 'Imane sa Yehowa, Lowalangi Ndraono Gizeraeli: Lö ahori hamo ba rumbi ba lö alö wanikha ba migö, irugi luo ba nibe''e Yehowa teu ba guli danö.', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 15, 'Ba möi ia, i''o''ö niŵa''ö Geliya; ba ara lö ambö öra, datölu ira.', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 16, 'Lö ahori hamo ba rumbi ba lö alö wanikha ba migö, itörö niŵa''ö Yehowa andrö, nifa''ema Geliya.', '["Luk 4:25"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 17, 'Ba aefa da''ö, ba mofökhö nono ndra alawe andrö, sokhö omo, ba tedou-dou manö wökhönia, irege aetu nosonia.', '["Luk 7:15"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 18, 'Ba imane ira alawe andrö khö Geliya: Hadia niŵa''öu khögu, ya''ugö enoni Lowalangi? Fe''amöimö khögu, ba ena''ö tefasugi ba dödö [Lowalangi] lalögu, ba wamunu onogu!', '["Luk 7:15"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 19, 'Ba imane khönia: Da nonou! Ba ihalö ba gaheta ninania, i''ohe yaŵa ba mbate''e ba zi sagötö, ba nahiania andrö, ba ibe''e ba gasonia.', '["Luk 7:15"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 20, 'Ba i''angaröfi li Yehowa, imane: He Yehowa, Lowalangigu, hadia wa no öfakao lakha mbanua andrö, si no möido tome, wamunu ononia?', '["Luk 7:15"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 21, 'Ba medölu ifadölö ia yaŵa nono, i''angaröfi li Yehowa, imane: He Yehowa, Lowalangigu, be''e mangawuli noso nono matua andre![3]', '["Luk 7:15"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 22, 'Ba ifondrondrongo wangandrö Geliya Yehowa, ba mangawuli noso nono andrö, tobali ifuli auri.', '["Luk 7:15"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 23, 'Ba ihalö nono Eliya, i''ohe tou moroi ba mbate''e ba zi sagötö; i''ohe yomo ba ibe''e khö ninania. Imane Eliya: Hiza, no ifuli auri nonou!', '["Luk 7:15"]', NULL),
  (3475047, 'OT', 'Razo I', 17, 24, 'Ba imane ira alawe andrö khö Geliya: Awena aboto ba dödögu, wa no enoni Lowalangi ndra''ugö, awö wa si duhu manö daroma li Yehowa, nifa''emamö!', '["Luk 7:15"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 1, 'Ba ara, ba humede Yehowa khö Geliya, me no alua mendrua fakhe, imane: Ae oroma''ö ndra''ugö khö Gahabi, ena''ö ufoteu guli danö.', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 2, 'Ba moi Geliya, ba wangoroma''ö ya''ia khö Gahabi. Ba no abölö-bölö sibai lofo ba Zamaria.', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 3, 'Ba ifakaoni''ö Gobadia, mandru yomo, Ahabi. Ba Obadia andrö, ba no sangata''ufi Yehowa, no si lö faröi.', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 4, 'Andrö wa otu i''ohe sama''ele''ö ba ibini''ö ba dögi narö hili, limalima wulu, ba i''uri, ibe''e roti ba idanö, me luo ifahori''o zama''ele''ö andrö khö Yehowa Izebela.', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 5, 'Ba imane Ahabi khö Gobadia. Talabu! ta''alui misa ba danö gumbu nidanö fefu, ba daso mbombo, ma atö tasöndra ndru''u, fangorifi kudo, awö kudo kalide, fa böi tabunu ösa!', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 6, 'Ba fabali fofanö ira ba wanöröi tanö. Sara lala Gahabi, ba sara lala Gobadia.', '["HalZin 8:39"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475048, 'OT', 'Razo I', 18, 7, 'Ba me no so ba lala Gobadia, ba falukha ia Geliya. Ba me i''ila wa ya''ia, ba ifalögu tou ia, imane: Hadia, si ndruhu ya''ugö, Tuagu Eliya?', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 8, 'Ba imane khönia: Ya''odo! Ae ŵa''ö khö zokhö ya''ugö: No so Geliya!', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 9, 'Ba imane: Hadia horögu, wa öbe''e ba danga Gahabi zawuyumö andre, ba wamunu ya''odo?', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 10, 'Faya wa no sauri Yehowa, Lowalangiu, na so soi ba na so mbanua, ba zi lö ifatenge sokhö ya''o, wangalui ya''ugö. Ba na lamane: Lö ya''ia, ba ibe''e ba hölu niha andrö, öri andrö, na no la''ila ndra''ugö.', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 11, 'Ba ömane sa''ae: Ae ŵa''ö khö zokhö ya''ugö: No so Geliya!', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 12, 'Ba na uröi ndra''ugö, ba i''oloi''ö ndra''ugö Eheha Yehowa, ba ha niha zangila, heza i''ohe''ö! Ba na urugi, ba wangombakha khö Gahabi, ba na lö isöndra ndra''ugö, ba ibunudo; ba noa sa atö i''ata''ufi Yehowa sawuyumö andre, i''otarai iraono ia.[1]', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 13, 'Hadia, lö mu''ombakha''ö khöu, ya''ugö Tua, wolaugu, me ifabunu''ö zama''ele''ö andrö Izebela, wa no otu ubini''ö sama''ele''ö, limalima wulu. Ba dögi narö hili, awö wa no u''uri ira roti ba idanö.', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 14, 'Ba ömane iada''e: Ae ŵa''ö khö zokhö ya''ugö! No so Geliya — ena''ö ibunudo!', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 15, 'Ba imane Eliya: Faya wa no sauri Yehowa ngahönö, si no möido enoni, na tenga ma''ökhö andre u''oroma''ö ndra''o khönia.', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 16, 'Ba möi Gobadia, ifaondragö Gahabi ba i''ombakha''ö khönia; ba möi Gahabi mamaondragö Eliya.', '["HalZin 8:39"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 17, 'Ba me i''ila Geliya Ahabi, ba imane khönia: No so''ö, samakao Iraono Gizeraeli?[2]', '["Amos 7:10; HalZin 24:5"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 18, 'Ba imane Eliya: Tenga ya''odo zamakao Iraono Gizeraeli, ya''ugö ba si samba omo ya''ami, me no lö ba dödömi goroisa Yehowa ba me no mi''o''ö khö Mba''ali andrö.', '["Amos 7:10; HalZin 24:5"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 19, 'Ba iya''e, ba fatenge, ba falukha''ö khögu Ndraono Gizeraeli fefu, ba hili Garemeli, awö zama''ele''ö andrö khö Mba''ali, si 450, ba sama''ele''ö andrö khö Gasera, si 400, ni''uri''uri Gizebela.', '["Amos 7:10; HalZin 24:5"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 20, 'Ba ifatenge ba Ndraono Gizeraeli fefu misa Ahabi ba ifalukha''ö zama''ele''ö andrö, ba hili Garemeli.', '["Amos 7:10; HalZin 24:5"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 21, 'Ba i''ondrasi zato Eliya, ba imane: Ha wa''ara döhö wanufa dödömi? Na Yehowa Lowalangi, ba mi''o''ö khönia, ba na Ba''ali, ba khönia mi''o''ö! Ba lö latema linia sato.[3]', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 22, 'Ba imane Eliya ba zato: Hatö ya''o zama''ele''ö khö Yehowa, ba sama''ele''ö khö Mba''ali, ba no 450.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 23, 'Ba da khöma nono zaŵi, dua rozi; ba ndra mutuyu khöra zara ba ndramutatawi ba ndramube''e ba geu nibahogö, ba böi labe''e galitö; ba ya''o zangasiwai ono zaŵi si sara ba ube''e ba geu nibahogö, lö ube''e galitö.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 24, 'Ba mi''angaröfi li Lowalangimi andrö, ba ya''o, ba u''angaröfi li Yehowa: ba heza dania Lowalangi sanema li alitö, da''ö tabe''e Lowalangi! Ba latema linia sato fefu, lamane: Ya''ia da''ö!', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 25, 'Ba imane Eliya ba zama''ele''ö andrö, khö Mba''ali: Mituyu khömi nono zaŵi, sara, ba mi''asiwai; oföna ami, me no ato ami, ba mi''angaröfi li Lowalangimi andrö; ba lö tola mibe''e galitö.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 26, 'Ba lahalö nono zaŵi andrö, la''asiwai, ba la''angaröfi li Mba''ali andrö, i''otarai zi hulö wongi, numalö ba zi laluo, lamane: Fondrondrongo lima, Ba''ali! Ba lö lili, lö fanema lira. Ba lafanoka ira, lafazui-zui naha wame''e sumange andrö, nifa''anöra.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 27, 'Ba me laluo sa''ae, ba i''o''aya ira Eliya, imane: Mi''ebua''ö limi, Lowalangi sa atö ia! Ma hadia nifatou-tounia tödönia, ba ma hadia rörönia, ba ma no mofanö, ba ma no mörö, ba tokea ia dania.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 28, 'Ba la''ebua''ö lira we''ao ba lakhoi nösira si''öli ba ikhu doho, huku ba khöra, irege mangele tou ndro.[4]', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 29, 'Ba me no aefa laluo, ba hulö zowöhö ira, irugi ginötö wame''e sumange ni''a andrö; ba lö lili, lö fanema lira, ba he famondrongo.[5]', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 30, 'Ba imane Eliya ba niha sato fefu: Mi''ae ba da''e khögu! Ba la''ondrasi ia sato. Ba ifuli ifa''anö naha wame''e sumange andrö khö Yehowa, si no dumudugö.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 31, 'Ba 12 ihalö kara Eliya, dali wa''oya mado Ndraono Yakobo andrö — Yakobo ba zi hede Yehowa, me imane: Izeraeli sa''ae döimö![6]', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 32, 'Ba ifa''anö naha wame''e sumange gara andrö, ba döi Yehowa, ba ifasui bandra naha wame''e sumange andrö, mato dua lauru tanömö wa''ebolo.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 33, 'Ba ibahogö geu andrö, itatawi nono zaŵi, ba ibe''e ba dete geu.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 34, 'Aefa da''ö, ba imane: öfa timba mita''u idanö, ba miwuwui zumange nitunu andrö, awö geu! Ba la''o''ö da''ö. Ba imane: Milau zamuza tö! Ba lalau. Ba imane: Samuza tö! Ba la''o''ö, no medölu.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 35, 'Ba mangele mitou nidanö, ba gahe naha wame''e sumange fasui. Ba he bandra andrö göi ba ifo''ösi idanö.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 36, 'Ba me inötö wame''e sumange ni''a andrö, ba so Geliya, ba imane: He Yehowa, Lowalangi ndra Aberahamo, Iza''aki, Izeraeli, oroma''ö ma''ökhö, wa no ya''ugö Lowalangi ba Ndraono Gizeraeli, awö wa no enoniu ndra''odo andre, awö wa no dali khögu goroisamö, ba wolau da''e fefu.', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 37, 'Fondrondrongo ligu, Yehowa, fondrondrongo, ena''ö aboto ba dödö soi andre, wa no ya''ugö Lowalangi, ya''ugö Yehowa andrö, awö wa no ya''ugö zamalalini era-erara!', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 38, 'Ba aekhu galitö moroi yaŵa khö Yehowa, i''a zumange nitunu andrö, awö geu, awö gara, fabaya tanö tou, ba he idanö andrö ba mbandra, ba ifelai.[7]', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 39, 'Ba me la''ila da''ö niha sato, ba lafalögu tou ira, ba lamane: Yehowa Lowalangi! Yehowa Lowalangi!', '["Yos 24:15","MozIII 19:28","MozII 29:39; SamI 18:10","MozI 32:28; Yos 4:8","MozIII 9:24"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 40, 'Ba imane khöra Eliya: Mira''u zama''ele''ö andrö khö Mba''ali! Samösa böi mibe''e moloi! Ba lara''u, ba i''ohe ira mitou ba mbewe mbombo Kizono, ba itaba mbagira ba da''ö.[8]', '["MozV 13:5; RazII 10:19"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 41, 'Ba imane Eliya khö Gahabi: Ae miyaŵa ba lau manga; urongo sa''ae goso-goso deu.', '["MozV 13:5; RazII 10:19"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 42, 'Ba möi miyaŵa Gahabi, ba wemanga. Ba möi ba zuzu hili Garemeli Geliya, ifaöndrö ia tou ba danö, ilazi mbawania balöduhinia.', '["MozV 13:5; RazII 10:19"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 43, 'Ba imane khö ngoni-ngoninia andrö: Ae miyaŵa ba fakhölö''ö tanö ba nasi! Ba möi miyaŵa da''ö, ifakhölö ia ba imane: Lö hadia ia! Ba imane Eliya: Fuli ae''e! Ba ifuli möi nono matua andrö, mewitu.', '["MozV 13:5; RazII 10:19"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 44, 'Ba ba zi mewitu, ba imane: So moroi tou lawuo, ezai lalu''a, moroi tou ba nasi. Ba imane Eliya: Ae miyaŵa, ba ömane khö Gahabi: Fa''anö gureta ba ae yaŵa ba saŵa mitou, fa böi ikhamö''ö teu!', '["MozV 13:5; RazII 10:19"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 45, 'Ba i''ogomuzaö alu manö mbanua ba tesao nangi, ba tenga ono deu. Ba möi ba gureta Gahabi ba isaŵa Yezere''eli.', '["MozV 13:5; RazII 10:19"]', NULL),
  (3475048, 'OT', 'Razo I', 18, 46, 'Ba ikhamö Geliya tanga Yehowa ba mamöbö talu ia, ba ihulö Gahabi, irugi Yezere''eli.', '["MozV 13:5; RazII 10:19"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 1, 'Ba i''ombakha''ö khö Gizebela Ahabi fefu nilau Geliya, awö wa no ahori ibunu si''öli zama''ele''ö andrö.', '["Yon 4:3","MozII 34:28; Mat 4:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 2, 'Ba ifatenge zinenge khö Geliya Izebela, imane khönia: Ndramulau khögu Lowalangi andrö zomasi ira, na tenga mane wa''alaŵa luo mahemolu ufatörö ba nosou nifatörö ba noso zama''ele''ö andrö fefu.', '["Yon 4:3","MozII 34:28; Mat 4:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 3, 'Ba ata''u ia, maoso ia, ilau mofanö, ba wangorifi ya''ia. Ba me no irugi Mbereseba andrö, ba mado Yuda, ba iröi ba da''ö ngoni-ngoninia andrö.', '["Yon 4:3","MozII 34:28; Mat 4:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 4, 'Ba ya''ia, ba isaŵa danö si mate, ma''ökhö fofanö, ba möi mudadao ba mbörö da''uli. Ba omasi ia mate, ba imane: Noa sa''ae, halö sa''ae nosogu, Yehowa; tenga si sökhi moroi khö ndra tuagu ndra''odo![1]', '["Yon 4:3","MozII 34:28; Mat 4:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 5, 'Ba ifadölö tou ia ba mbörö da''uli andrö ba mörö. Ba i''ogomuzaö ituko ia mala''ika, imane: Faoso, lau manga!', '["Yon 4:3","MozII 34:28; Mat 4:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 6, 'Ba me ifakhölö ia, ba hiza tanö ba högönia kue nibogö, sagörö, ba samba migö nidanö. Ba manga ia ba ibadu nidanö, ba ifuli ilau mörö.', '["Yon 4:3","MozII 34:28; Mat 4:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 7, 'Ba ifuli so mala''ika Yehowa, ituko, ba imane: Faoso, a göu, aröu sibai na sa döröŵau!', '["Yon 4:3","MozII 34:28; Mat 4:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 8, 'Ba maoso ia, manga ia ba ibadu nidanö, ba mowaö-waö ia ba wa''abölönia ba gö andrö, öfa wulu ngaluo ba öfa wulu mbongi irugi hili Lowalangi andrö, Horebi.[2]', '["Yon 4:3","MozII 34:28; Mat 4:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 9, 'Ba ba da''ö, ba möi ia ba dögi narö hili, ba mörö ia bakha ba da''ö. Ba humede khönia Yehowa, imane khönia: Hadia nihalöu ba da''e, Eliya?', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 10, 'Ba imane: No uforege wangombakha Yehowa, Lowalangi ngahönö; ba Iraono Gizeraeli, ba no la''erogö nifakhoimö andrö, naha wame''e sumange andrö khöu, ba no ladudugö, ba sama''ele''ö khöu, ba no labunu si''öli, tobali hatö ya''odo, ba la''alu-alui wamunu ya''o.[3]', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 11, 'Ba imane khönia Yehowa: Ae baero ba agö hili, föna Yehowa! Ba itörö Yehowa, ba fönania, ba angi sabölö sibai, fabali hili ibe''e ba arasa gara; ba Yehowa, ba tenga ba nangi andrö so. Ba me aefa nangi andrö, ba so ziheu; ba Yehowa, ba tenga ba ziheu andrö so.', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 12, 'Ba me aefa ziheu andrö, ba itörö alitö; ba Yehowa, ba tenga ba galitö andrö so. Ba me aefa galitö andrö, ba itörö angi si hohohoho manö.', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 13, 'Ba me irongo da''ö Eliya, ba ibalugö mbawania barunia sebua, ba möi ia baero, i''agö mbawa dögi andrö; ba so zihede khönia, imane: Hadia nihalöu ba da''e, Eliya?', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 14, 'Ba imane: No uforege wangombakha Yehowa, Lowalangi ngahönö, ba Iraono Gizeraeli, ba noa sa la''erogö nifakhoimö andrö, naha wame''e sumange andrö khöu, ba no ladudugö, ba sama''ele''ö khöu, ba no labunu si''öli, tobali hatö ya''odo: ba la''alu-alui wamunu ya''o.', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 15, 'Ba imane khönia Yehowa: Fuli''ö, ae ba danö si mate ba Ndramaseko, ba ae miyomo ba bayoini razo Ndrawa Garamo Hazaeli andrö.[4]', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 16, 'Ba Yehu andrö, ma''uwu Nimisi, ba bayoini razo Ndraono Gizeraeli, ba Elisa andrö, ono Zafati, banua Habeli Mehola, ba öbayoini sama''ele''ö, fangaliu dania.[5]', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 17, 'Ba tobali ha niha zaefa ba mbawa zi''öli Hazaeli, ba bunusö Yehu, ba ha niha zaefa ba mbawa zi''öli Yehu, ba bunusö Gelisa.', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 18, 'Ba fitu ngahönö zi tosai Iraono Gizeraeli ube''e, dozi balöduhi si lö irai aköi föna Mba''ali andrö, ba dozi bawa, si lö irai fa''ago khönia.', '["Rom 11:3","RazII 8:13","RazII 9:2"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 19, 'Ba iheta ia ba da''ö, ba falukha ia Gelisa andrö, ono Zafati, samali''ö tanö ia: felendrua fasa zaŵi fönania, ba ya''ia zolohe fondrege tanö furi. Ba möi khönia Geliya, ihawui ia barunia sebua.', '["Luk 9:61"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 20, 'Ba iröi zaŵi no mege ba i''o''ö Geliya, imane: Tehe khögu möido fa''ago bawa khö namagu ba khö ninagu, awena dania u''o''ö ndra''ugö! Ba imane khönia: Ae''e, ba fuli''ö; böi olifugö''ö nilaugu khöu![6]', '["Luk 9:61"]', NULL),
  (3475049, 'OT', 'Razo I', 19, 21, 'Ba iröi Geliya, möi ia, ihalö zaŵi andrö si safasa ba itaba; ba fakake zaŵi andrö, ba ibe''e eu, ba wangasosoi ösi, ba ibe''e ö niha andrö. Ba maoso ia, i''o''ö Geliya ba tobali ngoni-ngoninia.', '["Luk 9:61"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 1, 'Ba i''owuloi zabölö khönia fefu Benihada, razo Garamo, 32 razo nawönia, la''ohe kudora ba kureta khöra; ba so ira moroi you, lafa''u''u mbanua Zamaria ba lasuwö.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 2, 'Ba ifatenge zinenge, miyomo khö Gahabi, razo Ndraono Gizeraeli,', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 3, 'imane khönia: Da''ö niŵa''ö Mbenihada: Firöu andrö ba ana''au, ba khögu; ba fondrege zi sökhi ndra alawe khöu ba iraonou, ba khögu.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 4, 'Ba ifafuli''ö li khönia razo Ndraono Gizeraeli, imane: Dali niŵa''öu, ya''ugö sokhö ya''o, razo! khöu ndra''odo, awö fefu zi so khögu!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 5, 'Ba mangawuli zamuza tö zinenge andrö, ba lamane: Da''ö niŵa''ö Mbenihada: Ma''ifu lö niŵa''ögu khöu, öbe''e khögu wirömö ba ana''au ba ira alawemö ba iraonou!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 6, 'Mane wa''alaŵa luo mahemolu, ba ufatenge khöu nawögu, ena''ö labu''ai nomou ba omo mbanuau ba ena''ö la''okhögö fefu hadia ia zomasi ira, ba la''ohe!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 7, 'Ba ifalukha''ö fefu zatua mbanua razo Ndraono Gizeraeli, ba imane: Aboto manö sa''ae ba dödömi zi lö sökhi andrö, si so ba dödönia! Me ifatenge khögu, me i''andrö khögu ndra alawegu ba iraonogu, awö wirögu, awö gana''agu, ba lö niŵa''ögu khönia lö ube''e!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 8, 'Ba latema linia satua andrö, awö niha sato fefu, lamane: Böi fondrondrongo ba böi tehe!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 9, 'Ba imane ba zinenge Mbenihada: Mimane khö zokhö ya''ami, razo: Fefu hadia ia niŵa''öu khö genonimö, mege ba mböröta, ba u''o''ö, ba niŵa''öu iada''e, ba tebai u''o''ö! Ba mofanö zinenge andrö ba lafa''ema khö Mbenihada.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 10, 'Ba ifatenge khönia Benihada, imane khönia: Ndramulau khögu Lowalangi zomasi ira, na irugi adudula Zamaria andrö famo''ösi danga zabölö andrö fefu, ni''ohegu!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 11, 'Ba itema li razo Ndraono Gizeraeli, imane: Sangaro, ba böi yamusuno ia, si mane sameta sa''ae fangaro!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 12, 'Ba me irongo da''ö Benihada, me mamadu-madu agu ira nawönia razo, baose, ba imane ba zato khönia: Milau khöra! Ba molau ira.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 13, 'Ba hiza zama''ele''ö si möi khö Gahabi, imane: Da''ö niŵa''ö Yehowa: Hadia, ö''ila zato sibai andrö fefu? da''ö ube''e ba dangau ma''ökhö, ena''ö aboto ba dödöu, wa no Yehowa ndra''odo!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 14, 'Ba imane Gahabi: Ha niha zolau da''ö? ba imane sama''ele''ö andrö: Da''ö niŵa''ö Yehowa: Sabölö khö ndra kumandru andrö. Ba imane Ahabi: Ba ha niha zi börötaigö fasöndrata? Ba imane: Ya''ugö.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 15, 'Ba i''ofaya zabölö khö ndra kumandru andrö, ba no 332; Ba aefa da''ö, ba i''ofaya zato, Iraono Gizeraeli fefu, 7000.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 16, 'Ba maoso ira, möi ira, me laluo, me mamadu-madu agu Mbenihada ba me mabu ia, baose, awö razo andrö, si 32, sanolo ya''ia ena''ö.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 17, 'Ba sabölö khö ndra kumandru andrö zi öföna möi baero. Ba ifatenge zamaigi Benihada ba lamane khönia da''ö: So niha moroi yomo ba Zamaria!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 18, 'Ba imane: He ba wangatulö ba he ba wasöndrata möi ira, mira''u auri ira!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 19, 'Ba ha larugi baero mbanua sabölö khö ndra kumandru andrö ba sato, solo''ö ya''ira —,', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 20, 'ba samö-samösa i''ö''ötö tou zamösana. Ba moloi Ndrawa Garamo, ba lagohi ira Iraono Gizeraeli. Ba Benihada, razo Ndrawa Garamo, ba moloi, awö kudo ba si fakudo.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 21, 'Ba so moroi yomo razo Ndraono Gizeraeli ba ihalö kudo fabaya kureta. Ba te''ala sibai Ndrawa Garamo ibe''e.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 22, 'Ba ifuli i''ondrasi razo sama''ele''ö andrö, imane khönia: Ae abe''e''ö dödöu ba faigi sibai, he öwisa; ifuli sa so razo Ndrawa Garamo andrö, ba ndröfia dania, ba wanuwö ya''ugö.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 23, 'Ba lamane enoni razo Ndrawa Garamo khönia: Lowalangi hili Lowalangira andrö, andrö abölö ira moroi khöda! Na ba ndraso ena''ö talau khöra, ba lö zi lö abölö ita!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 24, 'Ba ömane sa''ae: öheta razo andrö fefu, ba ö''ali kumandru.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 25, 'Ba ya''ugö, ba ö''owuloi khöu zabölö, fa''ato zi tekiko mege, ba kudo ba kureta, si mane mege, ba ba ndraso talau khöra, ba lö zi lö abölö ita. Ba ifondrondrongo khöra, i''o''ö da''ö.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 26, 'Ba me no irugi döfi, ba i''ofaya Ndrawa Garamo Benihada ba i''ohe ba Afeki, ba wanuwö Iraono Gizeraeli.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 27, 'Ba te''ofaya göi Ndraono Gizeraeli ba tebe''e mbalazo, ba lafaondragö. Ba Iraono Gizeraeli, ba ba gamaudu Ndrawa Garamo tebato, hulö zi dua mbawa nambi, si lö oya-oya, ba Dawa Garamo, ba anönö danö labe''e.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 28, 'Ba so genoni Lowalangi no mege, ba imane khö razo Ndraono Gizeraeli: Da''ö niŵa''ö Yehowa: Me no laŵa''ö Dawa Garamo, Lowalangi hili Yehowa, ba tenga Lowalangi ndraso, ba ube''e ba dangau zato sibai andrö, ena''ö aboto ba dödöu, wa no Yehowa ndra''odo!', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 29, 'Ba önö bongi wa''ara fatahö ira ba da''ö, ba me luo si fitu, ba fasöndra ira, ba 100.000 labunu Dawa Garamo si lö kudo Iraono Gizeraeli, ha ma''ökhö.', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 30, 'Ba si tosai, ba moloi, lasaŵa miyomo Afeki; ba adudu göli kara, ba 27.000 ilangö niha si tosai mege. Ba noa göi moloi Mbenihada, ikhamö yomo mbanua, idörö-döröi mbate''e [yomo].', '[]', NULL),
  (3475050, 'OT', 'Razo I', 20, 31, 'Ba lamane khönia enoninia: Hiza, no marongo, wa no razo sahakhö tödö razo ma''uwu Gizeraeli andrö; ba data''olembe goni ba taböbö sinali högöda, ba tabe''e ba danga razo Ndraono Gizeraeli ita, ma atö i''orifi ita.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 32, 'Ba latema la''olembe goni, ba laböbö sinali högöra, ba möi ira khö razo Ndraono Gizeraeli, lamane: Da''ö niŵa''ö zawuyumö Benihada khöu: Orifi ndra''odo! Ba imane: Hadia, lö si mate ia? Ga''agu ia.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 33, 'Ba ba dödöra andrö, ba salöfö niŵa''önia andrö, ba lagösö lasofu, na si ndruhu linia da''ö, lamane: Hadia, ga''au Mbenihada? Ba imane: Mi''ae mihalö ia. Ba möi baero khönia Mbenihada, ba ifa''amöi ia awönia ba gureta Ahabi.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 34, 'Ba imane Benihada khö Gahabi: Banua andrö, nifadöni namagu khö namau mege, ba ufuli, ba hana na ölau kade khöu ba Ndramaseko, nifolau namagu mege ba Zamaria. Ba imane Ahabi: Ba ya''o, ba u''efa''ö ndra''ugö, me no tamanö wamagölö. Ba fawu''u li ira, ba ifofanö ia Ahabi.[1]', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 35, 'Ba so nifahaö zama''ele''ö, samösa, imane khö nawönia — niŵa''ö Yehowa khönia —: Tema fesokho ndra''o: Ba lö edöna da''ö ifesokho.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 36, 'Ba imane khönia si samösa: Me lö ö''o''ö goroisa Yehowa andrö, ba ha si''aikö fabali ndra''ugö khögu, ba ifesokho ndra''ugö singo. Ba me no fabali ia khönia, ba falukha ia zingo samesokho ya''ia.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 37, 'Ba si samösa, ba ifuli imane, me falukha ia nawönia bö''ö: Tema fesokho ndra''o! Ba ifesokho ia da''ö.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 38, 'Ba möi zama''ele''ö andrö, i''agö zinga lala nitörö razo dania; no iböbö mbawania, fa böi oroma ha niha ia.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 39, 'Ba me itörö razo, ba imane khönia: No fao ba wasöndrata andrö zawuyumö andre, ba so niha bö''ö, i''ohe khögu niha, samösa, ba imane: Tarogö niha andre; ba ma lö ya''ia dania, ba nosou nibe''e fangali nosonia, ba ma zui 220 balaki öbe''e höli!', '["Faigi 15:20"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475050, 'OT', 'Razo I', 20, 40, 'Ba me soso rörö zawuyumö andre, ba i''ogomuzaö manö taya niha andrö. Ba imane khönia razo Ndraono Gizeraeli: Ba da''ö hukumö, no ya''ugö zangetu''ö.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 41, 'Ba igösö iheta mböbö mbawania, ba i''ila ha niha ia razo Ndraono Gizeraeli, wa awö zama''ele''ö ia.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 42, 'Ba imane khö razo: Da''ö niŵa''ö Yehowa: Me no ö''efa''ö ba dangau niha andrö, niŵa''ögu nibunu, ba nosou nibe''e fangali nosonia, ba banuau nibe''e fangali mbanuania.', '["Faigi 15:20"]', NULL),
  (3475050, 'OT', 'Razo I', 20, 43, 'Ba ifuli ia khöra razo Ndraono Gizeraeli, lö sökhi-sökhi dödönia ba sofönu ia; ba irugi Zamaria.', '["Faigi 15:20"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 1, 'Ba me no aefa da''ö, ba sambalö zui: So kabu nagu khö Naboti, banua Yezere''eli, ba Yezere''eli andrö, ba ngai gödo Gahabi, razo Zamaria.[1]', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 2, 'Ba humede Gahabi khö Naboti, imane: Be''e khögu kabu nagu andrö khöu, da''ubali''ö kabu gule khögu, me no ahatö ia ba ngai gödogu. Ube''e fangali khöu kabu nagu bö''ö, si sökhi moroi ba da''ö, ba ma u''öli ia khöu, na omasi''ö da''ö.', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 3, 'Ba imane Naboti khö Gahabi: Yamutimba khögu Yehowa, ululu khöu gondröita ndra tuagu![2]', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 4, 'Ba mangawuli ba gödonia Gahabi, lö sökhi-sökhi dödönia ba sofönu ia ba wanema Naboti andrö, banua Yezere''eli, linia, me imane: Tebai ululu khöu gondröita ndra tuagu. Ba möi ia mörö, i''otahögö mbagolö, ba lö manga.', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 5, 'Ba möi si bakha khönia wo''omonia Izebela, imane khönia: Hana wa lö sökhi-sökhi dödöu ba hana wa lö manga''ö?', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 6, 'Ba imane khönia: No fahuhuodo khö Naboti andrö, banua Yezere''eli, no umane khönia: Be''e khögu kabu nagu andrö khöu, u''öli, ba ma zui ube''e fangali khöu, na da''ö zomasi''ö — ba imane: Tebai ululu khöu kabu nagu andrö khögu!', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 7, 'Ba imane khönia fo''omonia Izebela: Hadia, fa''arazo khöu da''ö iada''e ba Ndraono Gizeraeli? Faoso, a göu ba rara dödöu. Ya''o zama''amöi khöu kabu nagu andrö khö Naboti, banua Yezere''eli!', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 8, 'Ba ifazökhi zura, itagö döi Gahabi, ba ifotandro tandro khö Gahabi, ba ifa''ohe''ö ba zalaŵa ba ba zatua mbanua andrö, banua ndra Naboti.', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 9, 'Imane ba zura andrö: Mifaŵa''ögö wamoni, ba tanö yaŵa dania mifedao Naboti, ba walukhata,', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 10, 'ba mifaudu wawa ira niha si si lö yaŵa, darua, si möi sasi, sanguma''ö: No ö''elifi Lowalangi ba no ö''elifi razo! Ba mi''ohe baero ia, ba mitebu kara, mibunu.', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 11, 'Ba banuara andrö, satua ba salaŵa, ba la''o''ö goroisa Gizebela khöra, niŵa''önia ba zura andrö, nifa''ohe''önia khöra.', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 12, 'Lafaŵa''ögö wamoni, ba tanö yaŵa lafedadao Naboti, ba walukhata.[3]', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 13, 'Ba so niha si si lö yaŵa andrö, la''otahögö ia wedadao, ba laböbögö manö khö Naboti niha si lö ngaroro andrö, ba zi so sato fefu, lamane: No i''elifi Lowalangi Naboti, ba he razo, ba no i''elifi! Ba la''ohe ia baero mbanua ba latebu kara, labunu.[4]', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 14, 'Ba lafaŵa''ögö khö Gizebela, lamane: No mutebu kara Naboti, no mate.', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 15, 'Ba me irongo Izebela, no mutebu kara Naboti, ba no mate, ba imane khö Gahabi; Faoso! halö khöu kabu nagu andrö khö Naboti, banua Yezere''eli, si lö ibe''e ni''öli mege; lö Naboti sa''ae, no mate.', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 16, 'Ba me irongo Ahabi, no mate Naboti, ba maoso ia, möi ia ba kabu nagu andrö khö Naboti, banua Yezere''eli, ba wangokhögö ya''ia.', '["SamI 8:14","MozIII 25:23; MozIV 36:7","Yes 58:4","MozIII 24:14"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 17, 'Ba humede Yehowa khö Geliya, banua Disebe,', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 18, 'imane: Faoso, ae misi tou khö Gahabi, razo Ndraono Gizeraeli, ba Zamaria — hiza ba kabu Naboti so ia, ba zi möi ia mitou, ba wangokhögö, 19— ba ömane khönia: Da''ö niŵa''ö Yehowa: Hadia, no mange''e''ö, ba noa göi ö''okhögö gondröita? Ba ömane na khönia: Da''ö niŵa''ö Yehowa: Ba nifelai nasu do Naboti, ba da''ö lafelai dania ndromö asu![5]', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 20, 'Ba imane Ahabi khö Geliya: Hadia, no ösöndra ndra''o, ya''ugö si fatiu tödö khögu? Ba imane: Noa! Me no ölulu ndra''ugö, ba wolau si fatuwu khö Yehowa,[6]', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 21, 'ba hiza, ba ufatörö khöu wamakiko ba ubözini ndra''ugö ba uhori nga''ötö Gahabi, irege zi kiöni bagolö, iraono ba satua, ba Ndraono Gizeraeli.[7]', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 22, 'Ba ufatörö ba zi samba omo ya''ami, nifatörögu ba zi samba omo ndra Yerobeamo, ono Nebati, ba ba zi samba omo ndra Baesa, ono Gahia, börö mbakhu-bakhu dödögu andrö, ni''andrömö, me öfowöhö Ndraono Gizeraeli ba horö.[8]', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 23, 'Ba ba khö Gizebela göi, ba so göi niŵa''ö Yehowa, imane: Asu dania zi manga Gizebela ba danö Yezere''eli.[9]', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 24, 'Ha niha zi mate yomo ba mbanua soroiyomo Gahabi, ba asu zi manga, ba ha niha zi mate baero ba ba mbenua, ba fofo ba dalu mbanua zi manga.', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 25, 'No alösu lö niha solulu ya''ia si manö, ba wolau si fatuwu khö Yehowa andrö, si mane Ahabi, nifowöhö wo''omonia Izebela.[10]', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 26, 'No sabölö sibai ogoro ita wolaunia, andrö, me no itörö lala wame''e adu andrö, lö faehu ba nilau Ndraono Gamori andrö, mege, nitimba Yehowa föna Ndraono Gizeraeli.', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 27, 'Ba me irongo niŵa''ö andrö Ahabi, ba isika nukhania, ba i''onukha goni ba mamoni ba gö; ba iföröni goni andrö, ba mowaö-waö lö nini-nini.', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 28, 'Ba humede Yehowa khö Geliya, banua Disebe, imane:', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475051, 'OT', 'Razo I', 21, 29, 'Hadia, no ö''ila, wa no i''ide-ide''ö ia fönagu Ahabi? Me no i''ide-ide''ö ia fönagu, ba tenga ba götönia ufatörö wemakiko andrö; ba götö nononia dania ufatörö ba zi sawu ya''ira.[11]', '["Faigi 22:38","RazII 17:17","RazII 9:1","Faigi 15:29; 16:3","RazII 9:36","Faigi 16:23","RazII 9:25"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 1, 'Ba medölu fakhe ahono ira, lö fasuwö ira Ndrawa Garamo Ndraono Gizeraeli.', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 2, 'Ba me arakha medölu fakhe, ba möi misi tou khö razo Ndraono Gizeraeli Yozafati, razo mado Yuda.[1]', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 3, 'Ba imane razo Ndraono Gizeraeli khö genoninia: Hadia, lö mi''ila, wa no khöda Ramoti ba danö Gileadi; ba dumadao manö ita, lö liŵa-liŵa, ba lö tafadöni khö razo Ndrawa Garamo!', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 4, 'Ba imane khö Yozafati: Hadia, möi''ö awögu ba wanuwö, ba Ramoti ba danö Gileadi. Ba imane Yozafati khö razo Ndraono Gizeraeli: Si mane ya''ugö ndra''odo, ba banuagu, ba si mane banuau, ba kudogu, ba si mane kudomö.', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 5, 'Ba imane na Yozafati khö razo Ndraono Gizeraeli: Tema sofu ua khö Yehowa, ha iŵa''ö.', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 6, 'Ba ifalukha''ö zama''ele''ö andrö razo Ndraono Gizeraeli, mato 400 ira, ba isofu khöra, imane: Hadia, möido manuwö Ramoti ba danö Gileadi, ma lö''ö? Ba lamane: Ae''e, ena''ö ibe''e ba danga razo Yehowa!', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 7, 'Ba imane Yozafati: Lö baero ö, sama''ele''ö khö Yehowa, ena''ö khönia tasofu?[2]', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 8, 'Ba imane razo Ndraono Gizeraeli khö Yozafati: So na zamosa tö, si tola taŵa''ö sanofu khö Yehowa, ba no abao dödögu khönia, me tenga si sökhi nifa''ele''ele''önia ba khögu andre, ha si lö sökhi: Mikha andrö, ono Yimela. Ba imane Yozafati:', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 9, 'Böi ŵa''ö da''ö, ya''ugö razo! Ba humede razo Ndraono Gizeraeli khö genoninia yomo, imane: Ta''i-ta''i hede khö Mikha andrö, ono Yimela!', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 10, 'Ba razo Ndraono Gizeraeli ba Yozafati, razo mado Yuda, ba no dumadao ba mbawa göli Zamaria, baru luo mbarura, ba dadaomania dumadao zamösana, ba mama''ele''ö zama''ele''ö andrö, fefu, fönara.', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 11, 'Ba ifotandru si''öli ia Sedekia, ono Gena''ana, ba imane: Da''ö niŵa''ö Yehowa: ötandru dania tou Ndrawa Garamo tandru si mane da''e, irege no ahori ira öbe''e!', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 12, 'Ba si manö wama''ele''ö zama''ele''ö andrö fefu, ba lamane: Ae ba Ramoti andrö, ba danö Gileadi, ba ibe''e ba danga razo ira Yehowa!', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 13, 'Ba imane khö Mikha andrö sinenge andrö, si no möi mogaoni ya''ia: Hiza, ha sara manö li zama''ele''ö andrö, wangombakha si sökhi khö razo, ba böi faehusi niŵa''öu ba niŵa''öra mege, dozi ira: si sökhi ŵa''ö.', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 14, 'Ba imane Mikha: Faya wa no sauri Yehowa, na tenga ha sambalö niŵa''ö Yehowa khögu uŵa''ö!', '["Nga''ötII 18:1 b.t.","RazII 3:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 15, 'Ba me irugi razo, ba imane khönia razo: Hadia Mikha, möiga manuwö Ramoti, ba danö Gileadi, ma lö''ö? Ba imane khönia: Ae''e, ba si sökhi dania wozu khöu, ba ibe''e ba danga razo Ramoti Yehowa.', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 16, 'Ba imane khönia razo: Ha me uga ube''e ba hölu ndra''ugö, ena''ö ha sambalö si duhu ö''ombakha''ö khögu, niŵa''ö Yehowa khöu?', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 17, 'Ba imane: No u''ila, no muzaewe Ndraono Gizeraeli fefu, ba hili, hulö mbiri-biri, si lö kubalo. Ba imane Yehowa: Si lö sokhö da''ö; hana na ifuli ia khöra zamösana, ya lö hadia ia khöra!', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 18, 'Ba imane razo Ndraono Gizeraeli khö Yozafati: Tenga no uŵa''ö khöu: Tenga si sökhi ifa''ele''ö, ha si lö sökhi.', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 19, 'Ba imane Mikha: Böi ua! Fondrondrongo niŵa''ö Yehowa! No u''ila, no dumadao ba dadaomania Yehowa, ba no lafatambai ia banua zorugo sato.[3]', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 20, 'Ba imane Yehowa: Ha niha zi möi mamowöhö Ahabi, ena''ö möi ia manuwö, ba ena''ö ba Ramoti andrö, ba danö Gileadi, mate ia? Ba oi fabö''ö niŵa''öra.', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 21, 'Ba so zamösa, mbekhu, i''ondrasi Yehowa, ba imane: Ya''o zi möi mamowöhö ya''ia. Ba imane khönia Yehowa: Ha öbe''e famowöhö?', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 22, 'Ba imane: Möido bekhu sofaya ba mbewe zama''ele''ö andrö khönia fefu. Ba imane Yehowa: Ya''ia da''ö öfalua dania wamowöhö andrö; ae''e, ba lau da''ö![4]', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 23, 'Ba hiza, ba no ibe''e ba mbewe zama''ele''ö andrö khöu fefu mbekhu wamakiko Yehowa.', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 24, 'Ba maoso Zedekia andrö, ono Gena''ana, itema ifalisi mbawa Mikha, ba imane: Ba hadia lala wa''aheta Geheha Yehowa khögu, ba wehedegu khöu?', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 25, 'Ba imane Mikha: Hiza, ö''ila dania, na luo ötöröi mbate''e yomo, ba wamini''ö ya''ugö!', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 26, 'Ba imane razo Ndraono Gizeraeli: Mihalö Mikha, ba mi''ohe mangawuli ia khö Gamoni, kumandru ba mbanua ba khö Yoasi ono razo.', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 27, 'Ba mimane: Da''ö niŵa''ö razo: Mikuru da''e, ba ha ma''ifu mibe''e gö ba ha ma''ifu nidanö, irege mangawulido lö hadia ia khögu.', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 28, 'Ba imane Mikha: Na mangawuli ndra''ugö lö hadia ia khöu, ba tenga li Yehowa nifa''emagu! Ba imane na: Mifondrondrongo, ya''ami niha sato fefu!', '["Mat 18:10","Yob 12:16; TesII 2:11"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 29, 'Ba lasaŵa Ramoti ba danö Gileadi razo Ndraono Gizeraeli ba Yozafati, razo mado Yuda.', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 30, 'Ba imane razo Ndraono Gizeraeli khö Yozafati: Da''u''onukha nukha niha bo''ö ba wanuwö andrö, ba ya''ugö, ba böi bulö''ö nukhamö. Ba ifohani ia razo Ndraono Gizeraeli, ba isaŵa zi fasöndra ira.', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 31, 'Ba no ibe''e li ba gumandra andrö khönia, si 32, razo Ndrawa Garamo, ba gumandra gureta zanuwö andrö khönia, no imane: Böi milau ba niha bö''ö, he ono mbanua, ba he salaŵa, ha sambalö khö razo Ndraono Gizeraeli andrö milau!', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 32, 'Ba me la''ila Yozafati kumandra gureta andrö, ba labali razo Ndraono Gizeraeli ia, ba lasaŵa ia, ba wolau khönia. Ba mu''ira-ira Yozafati.', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 33, 'Ba me la''ila kumandra gureta andrö, tenga razo Ndraono Gizeraeli ia, ba laböhöli, lafuli ira furi.', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 34, 'Ba so zogai fanania, si lö mudöna-döna, ba i''efasi, ba göna khö razo Ndraono Gizeraeli, ba gotaluara mböbö talu göröba. Ba imane khö zolohe kuretania: Bali''ö, ohe misa ndra''o, hetado ba wasöndrata; noa sa mesokho ndra''odo!', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 35, 'Ba itugu abölö-bölö wasöndrata, me luo da''ö; ba razo, ba no sizizio ba gureta, fetahö Ndrawa Garamo, irugi tanö owi, ba do zokho andrö, ba ahele ba gureta yaŵa; ba me bongibongi, ba mate razo.', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 36, 'Ba me aekhu luo, ba mu''ao niha, lafa''ema''ema ba zato, lamane: Yamufuli ia ba mbanuara ba ba danöra zamösana — noa sa mate razo!', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 37, 'Ba larugi Zamaria, ba ba da''ö lako''o razo.', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 38, 'Ba me lasasai gureta, ba mbaŵa ba Zamaria, ba lafelai asu ndro Gahabi, ba faruka ba gamondria zohorö, itörö niŵa''ö Yehowa.[5]', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 39, 'Ba hadia na nidunö-dunö ena''ö ba khö Gahabi andrö ba hadia ia fefu nilaunia, ba omo ifö guaza andrö, nila''unia ba banua andrö fefu, ni''aro''önia, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.[6]', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 40, 'Ba mate Gahabi, itörö lala ndra amania, ba fangalinia razo, ba ononia Ahaseya.', '["Faigi 21:19","Amos 3:15"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 41, 'Ba Yozafati andrö, ono Asa, ba me no alua medölu fakhe razo Ndraono Gizeraeli Gahabi andrö tobali razo mado Yuda ia.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 42, 'Tölu ngafulu a lima fakhe Yozafati, me tobali razo ia, ba 25 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Asubi, ono Zilehi.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 43, 'Ba itörö sibai lala namania Asa, lö iröi, wolau somasi Yehowa.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 44, 'Ha fa lö mubulö''ö hili-hili andrö: lö labato sato wame''e sumange ba fanunu kumöyö ba hili-hili andrö.[7]', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 45, 'Ba Yozafati andrö, ba lö fa''udu khö razo Ndraono Gizeraeli.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 46, 'Ba hadia na nidunö-dunö ena''ö ba khö Yozafati andrö, ba fa''abölönia, nifa''ele''önia, ba fanuwö-nuwönia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 47, 'Noa göi ihori ba danö zi tosai sohorö andrö, si tosai na ba götö namania Asa.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 48, 'Ba lö razo ba Ndraono Gedomo; si no amaedola razo, ba kumandru.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 49, 'Ba Yozafati, ba no ifalau''ö nowo Darisi, soloyo ba Gofiri ena''ö, ba wangai ana''a; ba lö alua woloyo, aboto nowo andrö ba Geseono Geberi.[8]', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 50, 'Ba imane Ahaseya, ono Gahabi khö Yozafati, me luo da''ö: Akha möi awö mbanuau mbanuagu, ba woloyo andrö! Ba lö itehe Yozafati.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 51, 'Ba mate Yozafati, itörö lala ndra amania; ba ba ngai ndra amania lako''o ia ba mbanua duania Dawido. Ba fangalinia razo, ba ononia Yoramo.', '["Nga''ötII 15:17","Faigi 9:26; Nga''ötII 20:36"]', NULL),
  (3475052, 'OT', 'Razo I', 22, 52, 'Ba Ahaseya andrö, ono Gahabi, ba me no alua meweleönö fakhe razo mado Yuda Yozafati tobali razo Ndraono Gizeraeli ia, ba Zamaria, ba mendrua fakhe razo ia ba Ndraono Gizeraeli.', '[]', NULL),
  (3475052, 'OT', 'Razo I', 22, 53, 'Ba si fatuwu khö Yehowa wolaunia, itörö lala namania, ba he lala ninania andrö, lala Yerobeamo, ono Nebati, si no mamowöhö Iraono Gizeraeli ba horö.', '[]', NULL),
  (3475052, 'OT', 'Razo I', 22, 54, 'Ifosumange Mba''ali andrö, mangalulu ia khönia; i''andrö wönu Lowalangi Ndraono Gizeraeli Yehowa, nifolau namania mege, lö faehu.', '[]', NULL),
  (3475053, 'OT', 'Razo II', 1, 1, 'Ba me no mate Gahabi, ba lafabali ira ba Ndraono Gizeraeli Iraono Moabi.', '["Sakh 13:4; Mat 3:4; Heb 11:37"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 2, 'Ba no aekhu ba darali ba mbate''enia ba zi sagötö ba Zamaria Gahaseya ba i''ofökhöi; ba ifatenge zinenge, imane khöra: Mi''ae misofu khö Mba''ali-Zebubi andrö, Lowalangi ba Nekerona, na döhö dania wökhögu andre.', '["Sakh 13:4; Mat 3:4; Heb 11:37"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 3, 'Ba no muhede mala''ika Yehowa khö Geliya, banua Disebe, no imane: Faoso, ae misi yaŵa, faondragö zinenge razo Zamaria andrö, ba ömane khöra: Te lö Lowalangi ba Ndraono Gizeraeli, wa möi ami manotu khö Mba''ali-Zebubi andrö, Lowalangi ba Nekerona!', '["Sakh 13:4; Mat 3:4; Heb 11:37"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 4, 'Andrö imane sa''ae Yehowa: Lö dania aheta''ö ba gaso andrö, ba zi no öleagö ndra''ugö, si mate sa''ae ndra''ugö. Ba mofanö Geliya.', '["Sakh 13:4; Mat 3:4; Heb 11:37"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 5, 'Ba lafuli ira khö Gahabi sinenge andrö. Ba imane khöra:', '["Sakh 13:4; Mat 3:4; Heb 11:37"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 6, 'Hana wa mifuli ami? Ba lamane khönia: So moroi si tou niha, no faondraga, ba imane khöma: Mifuli ami khö razo samatenge ya''ami, ba mimane khönia: Da''ö niŵa''ö Yehowa: Te lö Lowalangi ba Ndraono Gizeraeli, wa öfatenge ba wanofu khö Mba''ali-Zebubi andrö, Lowalangi ba Nekerona? Andrö lö aheta''ö ba gaso andrö, ba zi na öleagö ndra''ugö, si mate sa''ae ndra''ugö!', '["Sakh 13:4; Mat 3:4; Heb 11:37"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 7, 'Ba imane khöra: He wisa khala-khala niha andrö, si faondra khömi miyaŵa, sanguma''ö khömi da''ö?', '["Sakh 13:4; Mat 3:4; Heb 11:37"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 8, 'Ba lamane: Baru bu mbarunia ba uli zaŵi mböbö löwi-löwi. Ba imane: Eliya, banua Disebe.[1]', '["Sakh 13:4; Mat 3:4; Heb 11:37"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 9, 'Ba ifatenge khönia gumandra zi lima wulu, awö zi lima wulu andrö khönia. Ba me irugi si yaŵa Geliya kumandra andrö, ba hiza, no dumadao Geliya ba zuzu hili; ba imane khönia kumandra andrö: He enoni Lowalangi, no iŵa''ö razo: Ae mitou!', '["Luk 9:54"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 10, 'Ba itema li Eliya, imane khö gumandra zi lima wulu andrö: Na enoni Lowalangi ndra''o, ba ya aekhu galitö moroi yaŵa ba mbanua ba yamu''a''ö, awö zi lima wulu andrö khöu! Ba aekhu galitö moroi yaŵa ba mbanua, ba i''a ia, fabaya si lima wulu andrö khönia.[2]', '["Luk 9:54"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 11, 'Ba ifuli ifatenge gumandra bö''ö Ahaseya, kumandra zi lima wulu, awö zi lima wulu andrö khönia. Ba irugi si yaŵa Eliya, ba imane khönia: He enoni Lowalangi, imane razo:', '["Luk 9:54"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 12, 'Ta''i-ta''i, ae mitou! Ba itema li Eliya, imane khönia: Na enoni Lowalangi ndra''odo, ba ya aekhu galitö moroi yaŵa ba mbanua ba yamu''a''ö, awö zi lima wulu andrö khöu! Ba aekhu galitö Lowalangi, moroi yaŵa ba mbanua ba i''a ia, fabaya si lima wulu andrö khönia.', '["Luk 9:54"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 13, 'Ba ifuli ifatenge Ahaseya gumandra zi lima wulu, datölu ae, awö zi lima wulu andrö khönia. Ba möi miyaŵa da''ö — kumandra zi lima wulo andrö, fanete zi darua no mege — ba me irugi, ba ibalöduhini danö föna Geliya, mangalulu ia, imane: He enoni Lowalangi! ena''ö na ahakhö ma''ifu dödöu nosogu, awö noso zawuyumö andre, si lima wulu!', '["Luk 9:54"]', NULL),
  (3475053, 'OT', 'Razo II', 1, 14, 'Hiza, no aekhu galitö moroi yaŵa ba mbanua ba no i''a fönagu kumandra zi lima wulu andrö, si darua, awö zi limalima wulu andrö khöra; ba iya''e, ba ena''ö na ahakhö ma''ifu dödöu nosogu andre!', '["Luk 9:54"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475053, 'OT', 'Razo II', 1, 15, 'Ba imane mala''ika Yehowa khö Geliya: Ae awönia mitou, böi ata''ufi ia! Ba maoso ia, möi ia, möi ia awönia mitou khö razo.', '[]', NULL),
  (3475053, 'OT', 'Razo II', 1, 16, 'Ba imane ba da''ö: Da''ö niŵa''ö Yehowa: Me no öfatenge zinenge, ba wanofu khö Mba''ali-Zebubi andrö, Lowalangi ba Nekerona — te sa lö Lowalangi ba Ndraono Gizeraeli, nisofu li ena''ö? — ba lö aheta''ö ba gaso andrö, ba zi no öleagö tou ndra''ugö, si mate sa''ae ndra''ugö!', '[]', NULL),
  (3475053, 'OT', 'Razo II', 1, 17, 'Ba mate ia, itörö niŵa''ö Yehowa, nifa''ema Geliya; ba fangalinia razo, ba akhinia Yoramo, me no arakha mendrua fakhe razo mado Yuda Yoramo, ono Yozafati; me no si lö ono matua Gahaseya andrö.', '[]', NULL),
  (3475053, 'OT', 'Razo II', 1, 18, 'Ba hadia na ena''ö nidunö-dunö ba khö Gahaseya andrö, hadia nilaunia, ba no mutanö ba zura hikaya razo Ndraono Gizeraeli.', '[]', NULL),
  (3475054, 'OT', 'Razo II', 2, 1, 'Ba me edöna i''ohe ba zorugo Geliya Yehowa, si fao fe''ugu-ugu mbanua, ba iheta ia ba Giligala Eliya, awö Gelisa.[1]', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 2, 'Ba imane Eliya, awö Gelisa: I''agö da''e, noa sa iŵa''ö khögu Yehowa we''amöi ba Mbetieli. Ba imane khönia Elisa: Faya wa no sauri Yehowa ba faya, wa no sauri ndra''ugö, na fabalido khöu: Ba lasaŵa mitou Mbetieli.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 3, 'Ba möi baero khö Gelisa nono zekola zama''ele''ö andrö, si so ba Mbetieli, ba lamane khönia: Hadia no aboto ba dödöu, wa edöna Yehowa i''ohe yaŵa zokhö ya''ugö, iheta khöu ma''ökhö! Ba imane: U''ila göi, böi manö mihede-hede!', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 4, 'Ba imane khönia Eliya: He Elisa, iagö da''e, noa sa iŵa''ö khögu we''amöi ba Yerikho Yehowa! Ba imane khönia: Faya wa no sauri Yehowa ba faya wa no sauri ndra''ugö, na fabalido khöu! Ba larugi Yerikho.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 5, 'Ba la''ondrasi Gelisa ono zekola zama''ele''ö ba Yerikho, ba lamane khönia: Hadia, no aboto ba dödöu, wa edöna Yehowa i''ohe yaŵa zokhö ya''ugö, iheta khöu, ma''ökhö? Ba imane: U''ila göi, böi manö mihede-hede!', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 6, 'Ba imane khönia Eliya: Iagö da''e, noa sa iŵa''ö khögu we''amöi ba Yoridano Yehowa. Ba imane: Faya wa no sauri Yehowa ba faya wa no sauri ndra''ugö, na fabalido khöu! Ba fao ira.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 7, 'Ba lima wulu ono zekola zama''ele''ö zi möi, la''agö ngai lala, aröu ma''ifu; ba möi ba mbewe Yoridano zi darua.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 8, 'Ba ihalö mbarunia sebua Eliya, igölugö ba i''amözi''o idanö. Ba fabali nidanö ba latörö si darua, no sabe''e tanö.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 9, 'Ba me no larugi si yefo, ba imane Eliya khö Gelisa: Andrö hadia nilaugu khöu, gasa-gasa wangeheta ya''o khöu. Ba imane Elisa: Yatefodua winaeta khögu Gehehamö!', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 10, 'Ba imane Eliya: Safökhö ni''andröu! Na ö''ila ndra''odo, na teheta ndra''o khöu, ba tebe''e khöu da''ö; ba na lö ö''ila ndra''odo, ba lö itörö.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 11, 'Ba me la''owaö-waö''ö wamatunö da''ö, ba hiza gureta alitö ba kudo alitö, ba fabali zi darua ibe''e, ba numalö miyaŵa ba zorugo Geliya ba fao we''ugu-ugu mbanua.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 12, 'Ba i''ila Elisa, ba mu''ao ia, imane: He amagu! he amagu! kureta ba si fakudo [ndra''ugö], ba Ndraono Gizeraeli! Ba lö''ö sa''ae oroma ia khönia. Ba ituyu nukhania, isika, ifabali.[2]', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 13, 'Ba ihalö mbaru Geliya, baru sebua, si no aekhu tou khönia, ba mangawuli ia, möi ia ba mbewe Yoridano.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 14, 'Ba ituyu mbaru Geliya andrö, si no aekhu tou khönia, ba i''amözi''ö idanö, imane: Ba heza so Yehowa, Lowalangi Geliya andrö? Ba me ibözi nidanö, ba fabali, ba itörö Elisa.', '["MozI 5:24","Faigi 13:14"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 15, 'Ba me larongo da''ö ono zekola zama''ele''ö, si yefo ba Yerikho, ba lamane; No ahono khö Gelisa geheha Geliya! Ba lafaondragö ia, lafaöndrö ira fönania, irugi tou danö.', '[]', NULL),
  (3475054, 'OT', 'Razo II', 2, 16, 'Ba lamane khönia: Hiza, so ba da''e zabölö, lima wulu, enoniu; hana na möi da''ö, ba wangalui sokhö ya''ugö; ma dania no i''oloi''ö ia Eheha Yehowa; ma no ifazaumba ba hili, heza, ba ma ba ndraso, heza ia. Ba imane: Böi mifatenge!', '[]', NULL),
  (3475054, 'OT', 'Razo II', 2, 17, 'Ba me laforege sibai khönia, ba imane: Ba mifatenge! Ba lima wulu lafatenge niha, sangalui ya''ia, tölu ngaluo, ba lö lasöndra.', '[]', NULL),
  (3475054, 'OT', 'Razo II', 2, 18, 'Ba lafuli ira khönia — ba Yerikho na sa so ia — ba imane khöra: Tenga no uŵa''ö khömi: Böi mi''ae''e?', '[]', NULL),
  (3475054, 'OT', 'Razo II', 2, 19, 'Ba lamane banua Yerikho khö Gelisa: Si sökhi sa naha mbanua, ö''ila, ya''ugö Tua, ba idanö, ba lö sökhi; soso wa''adudu dalu ba danö andre.', '["Nga''ötI 16:22"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 20, 'Ba imane: Mihalö khögu wiga si bohou ba milau yaŵa nasio.', '["Nga''ötI 16:22"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 21, 'Ba lahalö khönia. Ba möi ia mitou ba gumbu nidanö, ilau bakha nasio andrö, ba imane: Da''ö niŵa''ö Yehowa: No uheta wökhö ba nidanö andrö, lö''ö sa''ae möi famunu, ba lö''ö sa''ae ibe''e adudu dalu.', '["Nga''ötI 16:22"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 22, 'Ba tobali sökhi nidanö andrö, irugi ma''ökhö andre, itörö niŵa''ö Yehowa, nifa''ema Gelisa.', '["Nga''ötI 16:22"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 23, 'Ba mofanö ia, isaŵa misi yaŵa Mbetieli. Ba me ba lala miyaŵa; ba mbanua so ia, ba so moroi yomo ndraono, la''o''aya ia, lamane: Ae miyaŵa, si mate batule! Ae miyaŵa, si mate batule![3]', '["Nga''ötI 16:22"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 24, 'Ba ibali''ö ia furi; ba me i''ila ira, ba i''elifi ira ba döi Yehowa. Ba so moroi ba gatua mberua si alawe, dua geu, ba 42 lasasawi iraono andrö.', '["Nga''ötI 16:22"]', NULL),
  (3475054, 'OT', 'Razo II', 2, 25, 'Ba i''otarai da''ö, ba isaŵa hili Garemeli, ba moroi ba da''ö ifuli ia ba Zamaria.', '["Nga''ötI 16:22"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 1, 'Ba Yoramo andrö, ono Gahabi, ba me no alua mewelewitu fakhe razo mado Yuda Yozafati, tobali razo Ndraono Gizeraeli ia ba Zamaria, ba mewelendrua fakhe razo ia.[1]', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 2, 'Ba si fatuwu khö Yehowa ilau, ba tenga sa atö si mane ira amania inania; iheta sa harefa andrö khö Mba''ali nitaru''ö namania mege.[2]', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 3, 'Ba lö''ö sa iböhöli horö Yerobeamo, ono Nebati, famowöhönia Iraono Gizeraeli; lö ibulö''ö.', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 4, 'Ba khö Mesa andrö, razo Ndraono Moabi, ba no fahöna gurifö ba no ifo''ömö ia beo razo Ndraono Gizeraeli 100.000 ono mbiri-biri ba bu mbiri-biri si matua, bu zi 100.000 nga''eu.', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 5, 'Ba me no mate Gahabi, ba ifabali ia khö razo Ndraono Gizeraeli razo Ndraono Moabi andrö, molaŵa.', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 6, 'Ba möi ba danö razo Yoramo, me luo da''ö, iröi Zamaria, ba i''ofaya Ndraono Gizeraeli fefu.', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 7, 'Ba ifatenge zinenge khö Yozafati, razo mado Yuda, imane khönia: No fabali khögu razo Ndraono Moabi; hadia moi''ö awögu, ba wanuwö Iraono Moabi? Ba imane: Möido! Si mane ya''ugö ndra''odo, ba banuagu, ba si mane banuau, ba kudogu, ba si mane kudomö.[3]', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 8, 'Ba imane [Yozafati]: Heza tatörö? Ba imane: Lala ba danö si mate ba Ndraono Gedomo tatörö.', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 9, 'Ba möi ira, datölu ira, razo Ndraono Gizeraeli ba razo mado Yuda ba razo Ndraono Gedomo. Ba me no latöröi danö, fitu ngaluo fofanö, ba lö ö zato idanö ba he ö gurifö andrö khöra.', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 10, 'Ba imane razo Ndraono Gizeraeli: Alai ita! Ba wame''e ba danga Ndraono Moabi ya''ira i''ohe ba da''e razo andre, si datölu Yehowa.', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 11, 'Ba imane Yozafati: Hadia, ba lö ba da''e sama''ele''ö khö Yehowa, ena''ö tabe''e sanofu khö Yehowa? Ba itema li razo Ndraono Gizeraeli enoni samösa, imane: So ba da''e Gelisa andrö, ono Zafati, solau idanö wombanö khö Geliya mege:[4]', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 12, 'Ba imane Yozafati: Khönia so daroma li Yehowa! Ba möi ira mitou khönia, datölu ira, razo Ndraono Gizeraeli ba Yozafati ba razo Ndraono Gedomo.', '["Faigi 1:17","RazI 12:30","RazI 22:4","RazI 22:5,7; 19:19,21"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 13, 'Ba imane Elisa khö razo Ndraono Gizeraeli: Hadia niŵa''öu khögu? Ae ba zama''ele''ö andrö khö namau mege ba ba zama''ele''ö khö ninau! Ba imane khönia razo Ndraono Gizeraeli: Böi, me no ba wame''e ba danga Ndraono Moabi ya''ira i''ohe ba da''e razo andre, si datölu, Yehowa.', '["RazI 18:15; Sin 15:4"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 14, 'Ba imane Elisa: Ba wa''aduhu wa''auri Yehowa, si no möido enoni: na lö ufaigi ena''ö Yozofati andrö, razo mado Yuda, ba lö unehegö ndra''ugö, lö ba dödögu ya''ugö![5]', '["RazI 18:15; Sin 15:4"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 15, 'Ba iya''e, ba mikaoni khögu zolau biola! Ero na so zolau biola, ba tohare khö Gelisa danga Yehowa.', '["RazI 18:15; Sin 15:4"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 16, 'Ba imane: Da''ö niŵa''ö Yehowa: Mifa''oli gohokoho ba ndraso andre.', '["RazI 18:15; Sin 15:4"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 17, 'Da''ö sa niŵa''ö Yehowa: Lö''ö sa oroma khömi nangi ba he teu, ba anönö zui idanö ndraso andre dania, ömi ba ö zato khömi ba ö gurifömi.', '["RazI 18:15; Sin 15:4"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 18, 'Ba side-idenia na da''ö, iŵa''ö Yehowa; ibe''e na göi ba dangami Ndraono Moabi,', '["RazI 18:15; Sin 15:4"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 19, 'ena''ö tobali milaŵa mbanua saro andrö khöra, fefu, ba banua nitutuyu; ba ena''ö mi''obö fefu geu sowua, ba mihawui gumbu nidanö fefu ba mifufu zi sökhi nowi fefu, milau gara.', '["RazI 18:15; Sin 15:4"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 20, 'Ba mahemolu ö, ba zanguhulö wongi, me inötö wame''e sumange ni''a andrö, ba hiza mbalö molö, si otarai danö Ndraono Gedomo, ba anönö danö ibe''e.', '["RazI 18:15; Sin 15:4"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 21, 'Ba me larongo Iraono Moabi fefu, so moroi sa razo andrö, ba wolau khöra, ba la''owuloi fefu, irege zi lö lokha lö molohe baluse, ba la''iagö nola danöra.', '["Ayati 19"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 22, 'Ba ba zanguhulö wongi, me takile nidanö ba zino, ba no oyo''oyo nidanö tanö si yefo, wamaigi Ndraono Moabi, hulö ndro.', '["Ayati 19"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 23, 'Ba lamane: Do! Tabe''e no fa''udu razo andrö, ba no fasöndra ira. Ba milabu, ba wangai sahulu ami dania, ya''ami Iraono Moabi!', '["Ayati 19"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 24, 'Ba me larugi golombaseŵa Ndraono Gizeraeli, ba maoso Ndraono Gizeraeli ba lalau ba Ndraono Moabi, tobali moloi ira labe''e. Ba ladou''ö ira föna na Iraono Gizeraeli, ba latohugö na wangalani Iraono Moabi.', '["Ayati 19"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 25, 'Ba banua, ba ladudugö, ba lahawui zi sökhi nowi fefu, sambu-sambua zamösa lalau kara, ba umbu nidanö fefu, ba lahawui, ba eu sowua fefu, ba la''obö, irege hatö öli kara ba Giri Hareseti zi tosai. Ba lafasui si faribo, ba laribo.[6]', '["Ayati 19"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 26, 'Ba i''ila razo Ndraono Moabi isaŵa wa''ate''ala ba zi manö, ba 700 i''ohe awönia, si so si''öli, ba wangalui lalania khö razo Ndraono Gedomo, ba tebai.', '["Ayati 19"]', NULL),
  (3475055, 'OT', 'Razo II', 3, 27, 'Ba ituyu nononia si a''a, fangalinia razo ena''ö, dania, ba ibe''e sumange nitunu, ba dete göli kara. Ba mofönu sibai Ndraono Gizeraeli, ba tobali laböhöli ia, lafuli ira ba khöra.', '["Ayati 19"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 1, 'Ba so ndra alawe, fo''omo nono zekola zama''ele''ö, mangarö-ngarö khö Gelisa, imane: No mate wo''omogu, enoniu andrö, ba no ö''ila, wa no sangata''ufi Yehowa ia, si lö mamalö-malö; ba iya''e, ba so zosugilö, ba wangai sawuyunia onogu matua, si dombua.', '["RazI 17:12"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 2, 'Ba imane khönia Elisa: He uwisa wanolo ya''ugö? Ombakha''ö khögu, hadia zi so khöu, yomo. Ba imane: Lö hadia ia khö zawuyumö yomo, ha sara tawu wanikha.[1]', '["RazI 17:12"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 3, 'Ba mane khönia: Ae wawalö nahia si lö ösi, ba mbanuami, ba böi sambö fa''oya;', '["RazI 17:12"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 4, 'ba ae si bakha, ba kusi mbawandruhö furimi onou andrö, ba fo''ösi nahia andrö fefu, ba safönu, ba fa''ese misa ua.', '["RazI 17:12"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 5, 'Ba möi ia, i''o''ö niŵa''ö Gelisa. Ikusi mbawandruhö furira iraononia; ba la''oro''ö khönia nahia ba ifadoro manö wamohani.', '["RazI 17:12"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 6, 'Ba me no ahori mo''ösi nahia andrö, ba imane khö nononia: Oro''ö na! Ba imane: Awai nahia. Ba awena tebato wanikha.', '["RazI 17:12"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 7, 'Ba möi ia mangombakha khö genoni Lowalangi andrö. Ba imane khönia da''ö: Ae amawa wanikha andrö ba bu''a gömöu. Ba si tosai, ba balazomi iraonou.', '["RazI 17:12"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 8, 'Ba samuza ma''ökhö, ba möi miyefo ba Zunema Gelisa. Ba so ba da''ö ndra alawe sebua ana''a, sogaoni manga ya''ia. Baero no itörö, ba möi ia yomo ba da''ö, manga.[2]', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 9, 'Ba imane ira alawe andrö khö wo''omonia: Hiza, aboto sa''ae ba dödögu, wa no enoni Lowalangi, niha ni''amoni''ö, niha andrö, sanörö-nörö ya''ita.', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 10, 'He wisa na talau mbate''e side-ide, nibagolöi, yaŵa ba zi sagötö, ba na tabe''e bakha khönia warate, awö meza, awö gurusi, awö naha wandru, ena''ö na ba da''ö idölö ia, na möi ia khöda.', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 11, 'Ba samuza ma''ökhö, ba ifuli so ia, ba möi ia ba mbate''e andrö, ba zi sagötö, ba mörö ia.', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 12, 'Ba aefa da''ö, ba imane khö ngoni-ngoninia Gehasi: Hede ba ndra alawe andrö! Ba humede ia khönia, ba i''ondrasi Gelisa.', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 13, 'Ba imane Elisa khö Gehasi: ömane khönia: Hiza, no ö''abusi tödö ndra''aga, no öforege, ba heza matolo göi ndra''ugö? Ma so khöu hadia ia nitoloma ya''ugö, wanguma''ö khö razo, ba ma khö gumandra? Ba imane: Ba ba niwama sodo [lö hadia ia].', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 14, 'Ba imane Elisa: Ba heza tatolo ia ena''ö? Ba imane Gehasi: Da''ö i! lö khönia ono matua, ba no niha satua wo''omonia!', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 15, 'Ba imane Elisa: Hede khönia! Ba humede ia khönia, ba iagö mbawandruhö.', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 16, 'Ba imane Elisa: Ba ndröfia, mane furi, ba öhagi nono matua! Ba imane: Böi Tua, enoni Lowalangi ndra''ugö, böi ö''aya zawuyumö![3]', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 17, 'Ba manabina ndra alawe andrö, ba mo''ono ia, me no alua ndröfi, me ituo wunia, itörö nifabu''u Gelisa.', '["Yos 19:18","MozI 18:10,14"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 18, 'Ba me no ebua-bua nono andrö, ba samuza ma''ökhö, ba möi ia awö namania mamaigi samasi.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 19, 'Ba mangarö-ngarö ia khö namania, imane: Afökhö sibai högögu! afökhö sibai högögu! Ba imane amania khö genoni: Lu''i ia miyomo khö ninania!', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 20, 'Ba ilu''i, i''ohe miyomo khö ninania. Ba ihagi inania, irege laluo, ba mate ia.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 21, 'Ba i''ohe yaŵa, ibe''e ba gaso genoni Lowalangi andrö, ba ikusi mbawandruhö furinia ba mofanö.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 22, 'Ba humede ia khö wo''omonia, imane: ŵa''ö khögu galide khö genoni, möido khö genoni Lowalangi andrö ba ugösö wangawuli!', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 23, 'Ba imane: Hadia, wa möi''ö khönia? Ba tenga fasulöna ma''ökhö ba tenga luo sabato. Ba imane: Lö salania.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 24, 'Ba ifosela galide si alawe andrö ba imane khö zangai halöŵö andrö: Fangaösöngaösö manö ia, böi be''e tetabi ndra''o, ba wakudosa andre, irege uŵa''ö khöu!', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 25, 'Ba mofanö ia, ba irugi genoni Lowalangi andrö, ba hili Garemeli. Ba me i''ila ia moroi sa enoni Lowalangi andrö, ba imane khö genoninia Gehasi: Hiza ndra alawe andrö, banua Zunema![4]', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 26, 'Ta''i-ta''i faondragö ia, ba ömane khönia: He wisa, lö hadia ia khöu? ba lö hadia ia khö wo''omou, ba lö hadia ia khö nono? Ba imane ira alawe andrö: Lö''ö.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 27, 'Ba me irugi genoni Lowalangi andrö, ba hili, ba ira''u gahenia. Ba so Gehasi ba wanimba ya''ia. Ba imane enoni Lowalangi andrö: Böi! noa sa sabu sibai tödö ia, ba no ibini''ö khögu Yehowa, lö nibokainia khögu.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 28, 'Ba imane ira alawe andrö: Hadia, no ya''odo zangandrö ono matua khö zokhö ya''o? Tenga no uŵa''ö khöu: Böi o''aya ndra''o?[5]', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 29, 'Ba imane Elisa khö Gehasi: Amöbö talu ba ani''o ziogu ba ae''e — na so zi falukha''ö, ba böi owai ia, ba na so zangowai ya''ugö ba böi tema linia — ba fadölö ba mbawa nono matua andrö zi''ogu.[6]', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 30, 'Ba imane ina nono andrö: Faya wa no sauri Yehowa ba faya wa no sauri ndra''ugö, na uröi''ö! Ba maoso Gelisa, i''o''ö.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 31, 'Ba no itari-tari Gehasi, no ifadölö ba mbawa nono andrö zi''o no mege; ba lö lili, lö irongo. Ba ifuli ia Gehasi, ifaondragö Gelisa ba imane khönia: Lö si tokea nono andrö.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 32, 'Ba me irugi yomo Elisa, ba hiza ba gasonia nono andrö, no mate.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 33, 'Ba möi ia si bakha, ikusi mbawandruhö furira, darua ira, ba mangandrö ia khö Yehowa.[7]', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 34, 'Awena möi ia yaŵa [ba warate], ifalögu ia ba doto nono andrö, ba ifaudugö mbawania ba mbawa nono ba hörö ba hörö ba tanga ba danga, ifaöndrö ia yaŵa nono; ba ifuli aukhu''aukhu nösi nono.[8]', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 35, 'Ba möi baulu Gelisa, mowaö-waö ia ba dalu zalo ba ifuli ia mamaöndrö ya''ia yaŵa nono. Awena bahö nono, mewitu, ba aefa da''ö, ba ifehaga ia.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 36, 'Ba humede Gelisa khö Gehasi, imane khönia: Hede ba ndra alawe andrö! Ba muhede ia khönia, ba so ia moroi tou, ba imane Elisa: Ya''e nonou, halö ia![9]', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 37, 'Ba i''ondrasi Gelisa, mangalulu ia khönia, ifaöndrö ia, irugi tou zalo; awena ihalö nononia ba möi baulu.', '["Faigi 2:25","Ayati 16","Luk 10:4","HalZin 9:40","RazI 17:21","Luk 7:15; Heb 11:35"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 38, 'Ba irugi zui Giligala Elisa. Ba no lofo ba danö. Ba me no dumadao fönania nono zekola zama''ele''ö, ba imane khö genoninia andrö: Be''e bawu mbowoa sebua ba rino gö nono zekola zama''ele''ö!', '[]', NULL),
  (3475056, 'OT', 'Razo II', 4, 39, 'Ba so zi möi ba mbenua, ba wangalui bulu ndru''u; ba isöndra zuri de''u, ba iteu mbua, mato samba bola. Ba ifuli ia, ikhökhö ba ibe''e bawu; lö''ö sa la''ila hadia.', '[]', NULL),
  (3475056, 'OT', 'Razo II', 4, 40, 'Ba ifa''oli khöra, ena''ö la''a. Ba ha si''aikö latandra, ba mu''ira-ira, lamane: Famunu ba mbowoa, ya''u gö enoni Lowalangi! ba tebai la''a.', '[]', NULL),
  (3475056, 'OT', 'Razo II', 4, 41, 'Ba imane: Da khögu hamo! Ba me no ilau ba mbowoa, ba imane: Mifa''oli khöra, ena''ö la''a! Ba lö''ö sa''ae famunu ba mbowoa.', '[]', NULL),
  (3475056, 'OT', 'Razo II', 4, 42, 'Ba so mbanua Mba''ali Zalisa samösa, solohe khö genoni Lowalangi andrö si a''a roti, 20 ngawua roti gandru, awö mböra nihama, ba mbolania. Ba imane Elisa: Be''e ba zato, ndramu''a!', '["Yoh 6:9; Mat 15:33","Mat 16:9,10"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 43, 'Ba imane enoninia: He uwisa, me no mato otu ira? Ba imane: Be''e khöra, ena''ö la''a! Imane sa Yehowa: Manga ira, ba lö ahori.[10]', '["Yoh 6:9; Mat 15:33","Mat 16:9,10"]', NULL),
  (3475056, 'OT', 'Razo II', 4, 44, 'Ba ibe''e khöra ba manga ira, ba lö ahori, itörö nifabu''u Yehowa.[11]', '["Yoh 6:9; Mat 15:33","Mat 16:9,10"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475057, 'OT', 'Razo II', 5, 1, 'Ba Na''ema andrö, kumandra sebua khö razo Ndrawa Garamo, ba no sebua töi khö zokhö ya''ia, no si teturia, no khönia mbörö wa''abölö Ndrawa Garamo, ibe''e Yehowa; ba no mobou auri ia.', '["RazI 20:7"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 2, 'Ba no larabu nono alawe Dawa Garamo, me möi manuwö, ba danö Ndraono Gizeraeli, no la''oloi''ö, ba no tobali sawuyu wo''omo Na''ema nono alawe andrö.', '["RazI 20:7"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 3, 'Ba imane khö zokhö ya''ia ira alawe. Ena''ö na möi khö zama''ele''ö ba Zamaria zokhö ya''o, ba ifodöhö ena''ö mbou aurinia!', '["RazI 20:7"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 4, 'Ba möi khö razo Na''ema, i''ombakha''ö khönia, imane: Da''ö niwa''ö nono alawe andrö, Iraono Gizeraeli.', '["RazI 20:7"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 5, 'Ba imane razo Ndrawa Garamo: Ba ae''e, da''ufa''ohe''ö zura khö razo Ndraono Gizeraeli. Ba möi ia, 46.200 rufia fanimba i''ohe firö ba 4.620 balaki ana''a, ba fulu nga''örö baru luo,', '["RazI 20:7"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 6, 'ba ibe''e ba danga razo Ndraono Gizeraeli zura no mege. Ba no imane ba zura andrö razo: Na möi ba dangau zura andre, ba ena''ö ö''ila: ufatenge khöu genonigu Na''ema, ena''ö öfadöhö mbou aurinia.', '["RazI 20:7"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 7, 'Ba me no ibaso zura andrö razo Ndraono Gizeraeli, ba isika nukhania ba imane: Hadia, Lowalangi ndra''odo, sangila mangetu''ö noso ba sangila mangorifi niha, wa ifa''andrö''ö khögu da''ö, ufadöhö mbou auri ba niha? Aboto manö sa''ae ba dödömi, wa sangalui tandraŵa.[1]', '["RazI 20:7"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 8, 'Ba me irongo enoni Lowalangi andrö, Elisa, no isika nukhania razo Ndraono Gizeraeli, ba ifatenge khö razo, imane khönia: Hadia wa no ösika nukhamö? Fatenge manö ia khögu, ba aboto dania ba dödönia so zama''ele''ö ba Ndraono Gizeraeli!', '["Luk 4:27"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 9, 'Ba so Na''ema, awö kudonia, awö gureta, ba ba golayama khö Gelisa tebato ia.', '["Luk 4:27"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 10, 'Ba ifatenge khönia Elisa, imane khönia: Ae ondri ba Yoridano, mewitu, ba te''ali nösiu ba döhö wökhöu!', '["Luk 4:27"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 11, 'Ba mofönu Na''ema ba mofanö, imane: Uwalinga möi ia tou, ba iagö da''e, ba i''angaröfi li Lowalanginia, Yehowa ba i''oro''ö dangania, i''otahögö ni''amoni''ö andrö, wamadöhö bou auri andrö.', '["Luk 4:27"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 12, 'Tenga no si sökhi moroi ba nidanö ba Ndraono Gizeraeli fefu nidanö ba Ndramaseko andrö, Abana ba Farifari? Hadia, tebai ba da''ö mondrido, ena''ö döhö wökhögu? Ba ibali''ö ia, mofanö, mofönu sibai.', '["Luk 4:27"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 13, 'Ba so genoninia, humede ira khönia, lamane: Hadia, na safökhö mena''ö iŵa''ö khöu sama''ele''ö andrö, ba hadia, lö ö''o''ö mena''ö? Ba tenga mendrua manö me no iŵa''ö khöu:', '["Luk 4:27"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 14, 'Ondri, ba döhö wökhöu! Ba möi ia mitou, fatu ia ba Yoridano, mewitu, i''o''ö niŵa''ö genoni Lowalangi andrö; ba te''ali nösinia, timba nösi nono matua, ba no döhö wökhö.[2]', '["Luk 4:27"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 15, 'Ba ifuli ia khö genoni Lowalangi andrö, fabaya awönia fefu, ba me irugi, ba i''ondrasi, ba imane: Hiza, no aboto ba dödögu, dozi tanö ba lö Lowalangi, ha ba Ndraono Gizeraeli, ba ya''e sa''ae khöu mbuala zawuyumö![3]', '["Ayati 5","Faigi 7:2"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 16, 'Ba imane Elisa: Faya wa no sauri Yehowa, si no möido enoni, na uhalö hadia ia! Ba he ŵa''ae iforege khönia, ena''ö ihalö, ba lö edöna ia.', '["Ayati 5","Faigi 7:2"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 17, 'Ba imane Na''ema: Ba hadia na labe''e atö khö zawuyumö danö da''e tou ndrohu-ndrohu noro kudo kalide, si dua geu. Lö''ö sa''ae edöna zawuyumö andre ifosumange Lowalangi bö''ö, sumange nitunu ba sumange nitaba, hatö Yehowa ifosumange.', '["Ayati 5","Faigi 7:2"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 18, 'Ba ha sambalö nibologöu tödöu khögu: na möi ba gosali Rimono zokhö ya''o, ba wangalulu ba da''ö, ba na itendro''ö ia ba da''iogu, ba na tobali fao ndra''o wangalulu ba gosali Rimono andrö, na mangalulu razo ba da''ö, ba yamubologö dödönia Yehowa, khö zawuyumö andre, ba zi sambalö andrö.[4]', '["Ayati 5","Faigi 7:2"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 19, 'Ba imane khönia Elisa: Fuli''ö khömi, böi busi dödöu!', '["Ayati 5","Faigi 7:2"]', NULL),
  (3475057, 'OT', 'Razo II', 5, 20, 'Ba me no aröu ma''ifu ia, ba imane dödönia Gehasi: Noa sa ahakhö dödö zokhö ya''o Ndrawa Garamo andrö, Na''ema, ba lö nihalönia ni''ohe Na''ema. Ba wa''aduhu wa''auri Yehowa, u''o''ö, ena''ö ibe''e khögu ösa!', '[]', NULL),
  (3475057, 'OT', 'Razo II', 5, 21, 'Ba fagohi Gehasi, i''o''ö Na''ema. Ba me i''ila Na''ema so zolo''ö ya''ia, ba möi ia tou moroi ba guretania, ifaondragö Gehasi, ba imane khönia: He wisa, lö hadia ia?', '[]', NULL),
  (3475057, 'OT', 'Razo II', 5, 22, 'Ba imane Gehasi: Lö''ö sa hadia ia, ba ifatengedo sokhö ya''o, imane khöu: So sibai zi möi tomegu, banua ba hili mado Geferayi, ono matua, darua, ono zekola zama''ele''ö, ba ena''ö na öbe''e khögu wirö, 4412 ba rufia, ba na dua görö mbaru, nibe''e khöra.', '[]', NULL),
  (3475057, 'OT', 'Razo II', 5, 23, 'Ba imane Na''ema: Na omasi''ö, ba manö tö halö! Ba iforege khönia, ilau ba mbola zi 8824 ba rufia, dombua bola, awö mbaru, si dua görö, ba ibe''e ba genoninia si darua, ba wolohe ya''ia khö Gehasi.', '[]', NULL),
  (3475057, 'OT', 'Razo II', 5, 24, 'Ba me larugi gahe hili-hili andrö, ba ihalö khöra Gehasi [norora andrö], ba i''irö''ö yomo, ba ifofanö niha andrö.', '[]', NULL),
  (3475057, 'OT', 'Razo II', 5, 25, 'Ba me no mofanö ira, ba möi ia mangondrasi sokhö ya''ia. Ba imane khönia Elisa: Heza ö''otarai, Gehasi? Ba imane: Lö''ö manö sofanö zawuyumö.', '[]', NULL),
  (3475057, 'OT', 'Razo II', 5, 26, 'Ba imane khönia Elisa: Hadia, lö si fao khöu dödögu, me so zamali''ö ya''ia khöu, ba gureta? Ba lau, ba no ötema wirö andrö, ba so sa''ae dania khöu nukha ba kabu nohi ba kabu nagu ba biri-biri ba saŵi ba sawuyu ira matua ba sawuyu ira alawe;', '[]', NULL),
  (3475057, 'OT', 'Razo II', 5, 27, 'ba bou auri Na''ema andrö, ba khöu molemba ba ba nga''ötömö dania, si lö mamalö-malö. Ba möi ia baero, no afusi bou auri, hulö nilau betua.', '[]', NULL),
  (3475058, 'OT', 'Razo II', 6, 1, 'Ba lamane ono zekola zama''ele''ö khö Gelisa: Faigi, nahama andre, sidadao ndra''aga fönau, ba no ambö;', '[]', NULL),
  (3475058, 'OT', 'Razo II', 6, 2, 'damöiga ba mbewe Yoridano ba sara zamösa mahalö eu balo, ena''ö malau nahama ba da''ö, si soga dania. Ba imane: Mi''ae''e!', '[]', NULL),
  (3475058, 'OT', 'Razo II', 6, 3, 'Ba so zangandrö khönia, samösa, imane: Hadia, na möi''ö awö genonimö?', '[]', NULL),
  (3475058, 'OT', 'Razo II', 6, 4, 'Ba imane: Lau, möido. Ba möi ia awöra. Ba me no larugi mbewe Yoridano, ba la''obö geu.', '[]', NULL),
  (3475058, 'OT', 'Razo II', 6, 5, 'Ba tofana ba nidanö wato zi samösa, me i''obö zageu. Ba mangarö-ngarö ia imane: Alai ndra''o, Tua, ba no niwawalö na''i!', '[]', NULL),
  (3475058, 'OT', 'Razo II', 6, 6, 'Ba imane enoni Lowalangi andrö: Heza tofana ia? Ba me no i''oroma''ö khönia heza, ba itaba geu Elisa ba ihandrogö ba da''ö. Ba molangi wato andrö.', '[]', NULL),
  (3475058, 'OT', 'Razo II', 6, 7, 'Ba imane: Halö ia! Ba i''oro''ö dangania, ihalö.', '[]', NULL),
  (3475058, 'OT', 'Razo II', 6, 8, 'Ba isuwö Ndraono Gizeraeli razo Ndrawa Garamo, ba mamagölö ia ba genoninia, iŵa''ö khöra, heza labinibini''ö ira.', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 9, 'Ba ifatenge khö razo Ndraono Gizeraeli enoni Lowalangi andrö, imane khönia: Angelama, böi törö da''ö; noa sa labini''ö ira ba da''ö Dawa Garamo.', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 10, 'Ba ifatenge zinenge razo Ndraono Gizeraeli ba niŵa''ö genoni Lowalangi andrö khönia. Ba ero na si manö, ba ifangelama razo Elisa, ba lö''ö sa mamalö-malö wangelamania ba niŵa''ö Gelisa, tenga ha samuza ba tenga ba mendrua.', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 11, 'Ba abu dödö razo Ndrawa Garamo ba zi manö; ba hu mede ia ba genoninia, imane khöra: Hadia, tebai mi''ombakha''ö khögu, ha niha zi manga mbölida khö razo Ndraono Gizeraeli?', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 12, 'Ba imane si samösa, enoninia: Tenga si manö, ya''ugö sokhö ya''o, razo: Elisa andrö, sama''ele''ö, si so ba Ndraono Gizeraeli, da''ö zangombakha khö razo Ndraono Gizeraeli huhuomö si bakha khöu!', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 13, 'Ba imane: Ba mi''ae mifaigi heza so ia, ena''ö ufatenge, ba wondra''u ya''ia. Ba la''ombakha''ö khönia, lamane: Hiza, ba Ndrotana so ia!', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 14, 'Ba ato ifatenge sabölö, awö kudo, awö gureta; ba zi bongi larugi, ba lafa''u''u mbanua.', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 15, 'Ba me ihulö wongi Elisa we''amöi tou, ba hiza, ba no lafasui mbanua sanuwö, awö kudo, awö gureta. Ba imane khönia enoninia: Alai ita, Tua! He tawisa?', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 16, 'Ba imane: Böi ata''ufi; me no ato nawöda, moroi ba nawöra andrö.[1]', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 17, 'Ba mangandrö Gelisa, imane: He Yehowa, bokai hörönia, ena''ö i''ila niha! Ba ibokai hörö genoninia andrö Yehowa, ba i''ila, wa no anönö hili andrö, si tefasui Elisa, kudo ba kureta alitö.', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 18, 'Ba me möi mitou Ndrawa Garamo andrö, me lafaondragö Gelisa, ba mangandrö ia khö Yehowa, imane: Tema hawui bösi niha andrö! Ba ihawui bösi, i''o''ö ni''andrö Gelisa.[2]', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 19, 'Ba imane khöra Elisa: Tenga lalami da''e ba tenga ya''ia mbanua andre. Mitabu, ba u''ohe ami ba niha andrö, ni''aluimi! Ba i''ohe ira ba Zamaria.', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 20, 'Ba me no larugi Zamaria, ba imane Elisa: He Yehowa, bokai höröra, ena''ö la''ila niha! Ba ibokai höröra Yehowa, ba hiza, ba no ba dalu golayama Zamaria so ira.', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 21, 'Ba me i''ila ira razo Ndraono Gizeraeli, ba imane khö Gelisa: Hadia, ufabunu''ö ira, ama?', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 22, 'Ba imane: Lö tola öbunu ira! Hadia öbunubunu nira''umö, börö zi''öli ba fana khöu? Be''e göra ba idanö, ena''ö manga ira ba ena''ö labadu nidanö, ba hana na lafuli ira khö zokhö ya''ira.[3]', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 23, 'Ba ifodiwo ira, ebua ihalö; ba me no manga ira, ba ifofanö ira, ba lafuli ira khö zokhö ya''ira. Ba aefa da''ö, ba lö''ö sa''ae lazuwözuwö Ndraono Gizeraeli Dawa Garamo.', '["Nga''ötI 32:7","MozI 19:11","Amaed 25:21; Nga''ötII 28:15"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 24, 'Ba ara ma''ifu, ba i''owuloi zabölö khönia fefu Benihada, razo Ndrawa Garamo, ba isaŵa Zamaria, isuwö, ifa''u''u mbanua.', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 25, 'Ba tobali lofo sebua ba Zamaria, tosasa sibai ira, tobali 80 rufia mböli högö galide, ba samba kata gö marafadi, ba 5 rufia.', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 26, 'Ba me itörö dete göli kara razo Ndraono Gizeraeli, ba so ndra alawe sangarö-ngarö khönia: Tolodo, ya''ugö sokhö ya''o razo!', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 27, 'Ba imane razo: Na lö itolo''ö Yehowa ba heza uhalö wanolo ya''ugö? Hadia ba golayama mbasitö, ba ma ba wolazi mbua nagu?', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 28, 'Ba isofu khönia razo, imane: Hadia zabu dödöu? Ba imane: No imane khögu ira alawe andre: Be''e nonou matua andrö, ena''ö öda ma''ökhö, ba mahemolu, ba onogu ta''a.', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 29, 'Ba no marino öma nonogu, ba no ma''a. Ba me umane khönia, me mahemolu ö: Da nonou, ena''ö ta''a ia! Ba no ibini''ö nononia.[4]', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 30, 'Ba me irongo wehede ndra alawe andrö razo, ba itika nukhania, ba da''ö ba dete göli kara; Ba la''ila niha sato, wa no baru bu zi no amaedola gamezania.', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 31, 'Ba imane: Yamulau khögu Lowalangi zomasi ia, na tenga ma''ökhö aetu mbagi Gelisa andrö, ono Zafati!', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 32, 'Ba Elisa, ba sidadao ba nomonia, ba no dumadao ba ngainia zatua mbanua. Ba ifowaö-waö zinenge razo. Ba lö nirugi zinenge andrö Elisa na, ba imane Elisa ba zatua andrö: Hadia, lö mi''ila, wa no ifatenge ono zange''e andrö, ba woleŵa bagigu? Mifaigi, na so zinenge andrö ba mikusi mbawandruhö ba mituwu lagö, miba''a ia. Terongo sa''ae moroi furinia hozihozi gahe zokhö ya''ia.', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475058, 'OT', 'Razo II', 6, 33, 'Ba lö saetu na wehedenia khöra, ba so moroi yaŵa razo, möi khönia, imane: Hiza wamakao andrö, nifatörö Yehowa! Hadia wa udöna-döna na wangorifi khö Yehowa?[5]', '["MozV 28:53","Amos 3:6"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 1, 'Ba imane Elisa: Mifondrondrongo niŵa''ö Yehowa! Imane Yehowa: Mane wa''alaŵa luo mahemolu, ba hatö samba rufia zi samba sea (samba lauru a matonga) hamo si sökhi, ba hatö samba rufia göi zi 3 lauru gandru, ba mbawa göli Zamaria.[1]', '["Ayati 16","Ayati 17; Faigi 5:18"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 2, 'Ba itema li genoni Lowalangi andrö kumandra andrö, ba nitendro''ö razo ya''ia ba da''io, imane: Ba he ifosandrela mbanua si yaŵa Yehowa, ba tebai itörö da''ö! Ba imane Elisa: Höröu zangila dania, ba lö''ö sa ö''a.[2]', '["Ayati 16","Ayati 17; Faigi 5:18"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 3, 'Ba so baero mbawa göli niha sobou auri, daöfa, ba faoma lamane khö nawöra: Hadia wa ta''iagö da''e, balazi mate ita?', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 4, 'Na taŵa''ö ena''ö tödöda, möi ita miyomo — lö lai wa no lofo yomo ba mbanua — ba si mate sa atö ita ba da''ö; ba na ba da''e ta''iagö, ba si mate ita. Ba datasaŵa sa''ae golombaseŵa Ndrawa Garamo. Na la''orifi ita, ba sauri ita; ba na labunu ita, ba mate ita![3]', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 5, 'Ba maoso ira, me bongibongi, ba wanaŵa olombaseŵa Ndrawa Garamo. Ba me larugi mbalö golombaseŵa, ba samösa lö soroma niha.', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 6, 'Noa sa ibe''e Lowalangi, larongo ba golombaseŵa Ndrawa Garamo ruru kudo ba ruru gureta, ruru zanuwö, si no ato sibai, ba no tobali faoma lamane khö nawöra: Hiza, no i''oni ududa razo Ndraono Kheti ba razo Miserayi razo Ndraono Gizeraeli, ba wolau khöda![4]', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 7, 'Ba maoso ira, ba moloi, me bongibongi; ba osera, awö kudo khöra, awö galide — olombaseŵa ma''afefu ba hadia zi so, ba laröi furi; ba moloi ira, ba wangorifi ya''ira.', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 8, 'Ba me larugi mbalö golombaseŵa sobou auri andrö, ba möi ira baose, ba la''a ba labadu nisöndrara, ba firö ba ana''a ba nukha, ba la''ohe baero, ba möi ira, ba wogo''o ya''ia barö danö. Ba lafuli ira, möi ba nose bö''ö ba la''ohe baero zahulu ira ba lako''o ba danö.', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 9, 'Ba faoma lamane khö nawöra: Böi tamanö: baŵa zi sökhi turia mbaŵa da''e. Na lö ta''ombakha''ö, irege moluo mahemolu, ba si göna sala ita. Möi ita miyomo ba wangombakha ya''ia ba gödo razo!', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 10, 'Ba me larugi, ba mu''ao ira ba zanaro ba mbawa göli, ba la''ombakha''ö, lamane: No möiga ba golombaseŵa Ndrawa Garamo, ba hiza, samösa lö niha, lö nirongoma li niha, ha kudo ba kalide, si no mufesu, ba osera, awö nösi bakha, fefu.', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 11, 'Ba humede zanaro ba mbawa göli ba zatua mbanua, ba da''ö zangombakha ba gödo razo.', '["Esit 4:16","Faigi 19:7"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 12, 'Ba maoso razo, ba zi bongi, imane ba genoninia: Da''u''ombakha''ö khömi, hadia nikhoi dödö Ndrawa Garamo andrö khöda. No la''ila, wa solofo ita, ba no laröi golombaseŵa ba no labini''ö ira misa, baero, no lamane dödöra: Na so ira dania moroi yomo, ba tara''u auri ira, ba atu''a ita ba mbanua.', '["Ayati 1"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 13, 'Ba imane enoninia, samösa: Ba ndramu''ohe kudo ösa, kudo si lö ahori na, si tosai ba da''e — latörö sa atö lala zato andrö, si no ahori — ba tafatenge ira, ba wamaigi.', '["Ayati 1"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 14, 'Ba dombua lahalö kureta, fabaya kudo; ba da''ö ifatenge razo, ba wolohi sanuwö andrö, Dawa Garamo, imane khöra: Mi''ae''e, ba mifaigi!', '["Ayati 1"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 15, 'Ba me la''o''ö ira, irege Yoridano, ba hiza tou nukha ba fangöna, sara lala manö, nitibo''ö Ndrawa Garamo, me no si fulöi ira. Ba lafuli ira sinenge andrö, ba la''ombakha''ö khö razo.', '["Ayati 1"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 16, 'Ba awena möi baero zato, ba lahalö hadia zahulu ira ba golombaseŵa Ndrawa Garamo, ba tobali samba rufia zi samba sea (samba lauru a matonga) hamo si sökhi, ba samba rufia göi zi tölu lauru gandru, itörö nifabu''u Yehowa.[5]', '["Ayati 1"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 17, 'Ba no ifataro sanaro ba mbawa göli gumandra no mege razo, kumandra nitendro''önia ya''ia ba da''io, no andrö. Ba lahundragö gumandra andrö niha sato, ba mbawa göli, ba mate ia, itörö li genoni Lowalangi andrö, niŵa''önia me möi mitou khönia razo;[6]', '["Ayati 2"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 18, 'me imane enoni Lowalangi andrö khö razo: Mane wa''alaŵa luo mahemolu, ba samba rufia zi tölu lauru gandru, ba mbawa göli Zamaria, ba samba rufia göi zi samba sea (samba lauru a matonga) hamo si sökhi.', '["Ayati 2"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 19, 'Ba imane ba da''ö kumandra andrö khö genoni Lowalangi andrö: Ba he ifosandrela mbanua si yaŵa Yehowa, ba tebai itörö da''ö! Ba imane: Höröu dania zangila, ba lö''ö sa ö''a!', '["Ayati 2"]', NULL),
  (3475059, 'OT', 'Razo II', 7, 20, 'Ba itörö; lahundragö sa''ae ia sato, ba mbawa göli, ba mate ia.', '["Ayati 2"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 1, 'Ba no muhede Gelisa ba ndra alawe andrö, ni''orifinia ono mege, no imane: Faoso, heta''ö ba da''e, awö zoroiyomou fefu ba ae fatewu ba niha bö''ö, heza; ifatörö sa''ae lofo mbanua ba danö Yehowa, mewitu fakhe dania; ba no ibörögö iya''e.[1]', '["Faigi 4:35"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 2, 'Ba maoso ndra alawe andrö, i''o''ö niŵa''ö genoni Lowalangi andrö: aheta ia, awö zoroiyomonia fefu, ba mewitu fakhe wa''ara la''iagö danö Ndrawa Wilisiti.', '["Faigi 4:35"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 3, 'Ba me no alua zi mewitu fakhe andrö, ba mangawuli ndra alawe andrö, moroi ba danö Ndrawa Wilisiti, ba möi ia khö razo, ba wangandrö fanolo ba nomonia ba ba mbenuania.', '["Faigi 4:35"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 4, 'Ba fahuhuo si''aikö razo khö ngoni-ngoni genoni Lowalangi andrö, Gehasi, imane: Tunö khögu fefu nilau Gelisa, si teturia andrö.', '["Faigi 4:35"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 5, 'Ba me itunö khö razo wangorifi Gelisa si mate andrö, ba hiza, ba so si''aikö ndra alawe andrö, ni''orifinia ono, ba wangandrö fanolo khö razo ba nomonia ba ba mbenuania. Ba imane Gehasi: He sokhö ya''o, razo! Da''ö ndra alawe andrö, ba da''ö nononia, ni''orifi Gelisa!', '["Faigi 4:35"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 6, 'Ba isofu ba ndra alawe andrö razo, ba itunö khönia. Ba ifatenge awönia wazuri, imane ba da''ö: Tolo ia, ena''ö mangawuli khönia fefu motöi khönia, fabaya bua nowi andrö fefu, i''otarai aheta ia ba danö, irugi ma''ökhö andre.', '["Faigi 4:35"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 7, 'Ba irugi Ndramaseko Elisa. Ba benihada, razo Ndrawa Garamo, ba no mofökhö. Ba me la''ombakha''ö khönia: No so ba da''e genoni Lowalangi andrö,', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 8, 'ba imane razo khö Hazaeli andrö: Ohe mbuala ba faondragö genoni Lowalangi andrö, ba yamusofu khö Yehowa, na döhö dania wökhögu andre.', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 9, 'Ba ifaondragö Gelisa Hazaeli, i''ohe mbuala, ngawalö hadia ia zebua böli ba Ndramaseko, 40 nga''eu gondra monoro. Ba me irugi, ba i''ondrasi Gelisa, imane: Onou Benihada andrö, razo Ndrawa Garamo, zamatenge ya''o, imane: Hadia, döhö dania wökhögu andre?', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 10, 'Ba imane khönia Elisa: Ae ŵa''ö khönia: Lö zi lö döhö wökhöu! he ŵa''ae no ibokai khögu Yehowa, wa si mate ia dania.', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 11, 'Ba itöngö ia enoni Lowalangi andrö, irege aila ia; ba me''e Gelisa.', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 12, 'Ba imane Hazaeli: Hana wa me''e''ö, Tua? Ba imane Elisa: Me no u''ila, wa samakao Iraono Gizeraeli dania ndra''ugö. Banua saro khöra, ba ötunu dania, ba ono matua khöra, ba öbunu si''öli, ba iraono sawuyu, ba örasa, ba ba zanabina, ba ösikoi dalu.[2]', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 13, 'Ba imane Hazaeli: Ha niha zawuyumö andre, asu andre, wa ilau zi manö, sabölö-bölö andrö? Ba imane Elisa: No i''oroma''ö khögu Yehowa, wa razo Ndrawa Garamo ndra''ugö dania.[3]', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 14, 'Ba iröi Gelisa, ba me irugi zokhö ya''ia ba imane khönia da''ö: Hadia niŵa''ö Gelisa khöu? Ba imane khönia: Imane khögu. Lö zi lö döhö wökhönia!', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 15, 'Ba mahemolu ö, ba ihalö gambala, i''ungugö ba nidanö ba ibe''e fangahawu mbawania; ba mate ia, ba Hazaeli zi tobali razo, fangalinia.', '["Faigi 10:32","SamI 24:15; RazI 19:15"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 16, 'Ba me no alua mendröfa fakhe razo Ndraono Gizeraeli Yoramo, ono Gahabi,[4] tobali razo mado Yuda Yehoramo, ono Yozafati.[5]', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 17, 'Tölu ngafulu a rua fakhe ia, me tobali razo ia ba meŵalu fakhe razo ia ba Yeruzalema.', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 18, 'Ba itörö lala razo Ndraono Gizeraeli, nifolau Gahabi, awö nga''ötönia; me no ono Gahabi nihalönia dongania. Tobali si fatuwu khö Yehowa ilau.[6]', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 19, 'Ba lö edöna Yehowa, ifakiko mado Yuda, börö genoninia Dawido, dali nifabu''unia ba da''ö, wa lö ibulö''ö khönia wandru, sanehe ia.[7]', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 20, 'Ba me razo Yehoramo andrö la''efa''ö ira barö mbawa Ndraono Gizeraeli Iraono Gedomo, ba lafataro khöra razo.', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475060, 'OT', 'Razo II', 8, 21, 'Ba möi miyefo ba Za''ira Yehoramo, i''ohe gureta fefu. Ba maoso ia ba zi bongi, ilau ba Ndraono Gedomo, si no mama''u''u ya''ia, ba ba gumandra gureta, ba moloi zato, lasaŵa khöra.', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 22, 'Ba tobali aefa barö mbawa Ndraono Gizeraeli Ndraono Gedomo, irugi ma''ökhö andre. Ba me luo da''ö, ba la''efa''ö göi ira banua Libena.', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 23, 'Ba hadia na ena''ö nitunö ba khö Yehoramo andrö ba hadia ia fefu nilaunia, ba no mutanö ba zura hikaya razo mado Yuda.', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 24, 'Ba mate Yehoramo, itörö lala ndra amania, ba ba ngai ndra amania, ba mbanua Dawido, lako''o ia. Ba fangalinia razo, ba ononia Ahaseyahu.', '["Ayati 16—29: Nga''ötII 21:1,5—10","RazI 22:51","Ayati 26","SamII 7:11—16; RazI 11:36"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 25, 'Me no alua mewelezara fakhe razo Ndraono Gizeraeli Yoramo, ono Gahabi,[8] tobali razo mado Yuda Gahaseyahu, ono Yehoramo.', '["Ayati 25—29: Nga''ötII 22:1—6","Ayati 18; Faigi 11:1","Faigi 9:15; 16,21"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 26, 'Dua wulu a rua fakhe Gahaseyahu andrö, me tobali razo ia. Ba ha döfi razo ia ba Yeruzalema. Ba töi ninania, ba Atalia, ma''uwu Omeri andrö, razo Ndraono Gizeraeli.[9]', '["Ayati 25—29: Nga''ötII 22:1—6","Ayati 18; Faigi 11:1","Faigi 9:15; 16,21"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 27, 'Ba itörö lala zi samba omo ndra Ahabi, me no ono alawera ia.', '["Ayati 25—29: Nga''ötII 22:1—6","Ayati 18; Faigi 11:1","Faigi 9:15; 16,21"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 28, 'Ba fao ia khö Yoramo, ono Gahabi, ba wasuwöta khö Hazaeli andrö, razo Ndrawa Garamo, ba ngai Ramoti ba danö Gileadi: ba mesokho Yoramo labe''e Dawa Garamo.', '["Ayati 25—29: Nga''ötII 22:1—6","Ayati 18; Faigi 11:1","Faigi 9:15; 16,21"]', NULL),
  (3475060, 'OT', 'Razo II', 8, 29, 'Ba mangawuli razo Yoramo, ba wamadöhö sokhonia si tenga ha sambua, sesokho ia ba Ndrawa Garamo, ba Rama, me fasuwö ia khö Hazaeli, razo Ndrawa Garamo. Ba möi misi tou Gahaseyahu, ono Yehoramo, razo mado Yuda, ba wamaigi Yoramo andrö, ono Gahabi, ba Yezere''eli, börö wökhönia andrö.[10]', '["Ayati 25—29: Nga''ötII 22:1—6","Ayati 18; Faigi 11:1","Faigi 9:15; 16,21"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 1, 'Ba humede Gelisa khö nono zekola zama''ele''ö, imane khönia: Fa''anö''ö, ba ohe mbulibuli wanikha andre, ba ae ba Ramoti ba danö Gileadi.', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 2, 'Ba na örugi, ba alui ba da''ö Yehu andrö, ono Yozafati ono Nimisi. Ba na örugi yomo khöra, ba ŵa''ö khönia, yamuzizio ba hunö nawönia, ba ohe ia yomo.', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 3, 'Ba halö mbulibuli wanikha ba faduwa ba högönia, ba ömane: Da''ö niwa''ö Yehowa: No ubayoini razo Ndraono Gizeraeli ndra''ugö! Aefa da''ö, ba bokai mbawandruhö, ba dölö oloi.[1]', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 4, 'Ba möi ba Ramoti ba danö Gileadi nono matua andrö, enoni zama''ele''ö.', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 5, 'Ba me irugi yomo, ba mbanua, ba no orudu wedadao gumandra zabölö; ba imane: So niŵa''ögu khöu, ya''ugö Tua kumandra! Ba imane Yehu: Ha niha ndra''aga niŵa''öu? Ba imane: Ya''ugö, Tua kumandra!', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 6, 'Ba maoso ia, möi yomo. Ba ifaduwa ba högönia wanikha andrö ono matua andrö, ba imane khönia: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: No ubayoini razo mbanua Yehowa ndra''ugö, razo Ndraono Gizeraeli!', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 7, 'Ba öhori nga''ötö Gahabi andrö, sokhö ya''ugö mege, ena''ö ulau mbalö ndro genonigu sama''ele''ö andrö, ba balö ndro genoni Yehowa fefu, khö Gizebela andrö.[2]', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 8, 'Si samba omo ndra Ahabi andrö, fefu, ba nibunu, ba uhori nga''ötö Gahabi andrö, irege zi kiöni bagolö, iraono ba satua, ba Ndraono Gizeraeli.[3]', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 9, 'Ba ufagölö-gölö ba zi samba omo ndra Yerobeamo, ono Nebati, ba ba zi samba omo ndra Baesa, ono Gahia zi samba ömö ndra Ahabi.[4]', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 10, 'Ba Izebela andrö, ba ni''a nasu dania ba danö Yezere''eli, ba lö sogo''o ya''ia. Ba ibokai mbawandruhö, ba moloi ia.[5]', '["RazI 19:16","RazI 21:22","RazI 14:10","RazI 15:29; 16:3,11","RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 11, 'Ba me ifuli i''ondrasi tou genoni zokhö ya''ia Yehu, ba lamane khönia: He wisa, lö hadia ia? Hana wa möi khöu zowöhö andrö? Ba imane khöra: Noa sa mi''ila niha andrö ba era-erania.', '["Mat 21:7"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 12, 'Ba lamane: Tahi! Ombakha''ö khöma! Ba imane: Da''ö niŵa''önia khögu, no imane: Da''ö niŵa''ö Yehowa: No ubayoini razo Ndraono Gizeraeli ndra''ugö!', '["Mat 21:7"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 13, 'Ba lagösö lahalö lembera — ituyu lembenia zamösana — ba labe''e tufonia, ba mbosi nora andrö, ni''agönia, ba lalau dorofe, ba lamane: No tobali razo Yehu![6]', '["Mat 21:7"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 14, 'Ba mamagölö ba nawönia Yehu andrö, ono Yozafati ono Nimisi, ba wamunu Yoramo. Ba Yaramo ba Iraono Gizeraeli fefu, ba no si möi manaro mege ba Ramoti, ba danö Gileadi, ba wolau khö Hazaeli, razo Ndrawa Garamo.', '["Faigi 8:28,29","Faigi 8:29","RazI 21:1"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 15, 'Ba no ifuli ia, no isaŵa Yezere''eli, ba wamadöhö sokhonia andrö, si tenga ha sambua, sesokho ia ba Ndrawa Garamo, me fasuwö ia khö Hazaeli, razo Ndrawa Garamo. Ba imane Yehu: Na faduhu dödömi göi, ba böi mifa''amöi baero mbanua niha, si möi ena''ö, ba wangombakha ba Yezere''eli.[7]', '["Faigi 8:28,29","Faigi 8:29","RazI 21:1"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 16, 'Ba möi yaŵa ba guretania Yehu, isaŵa Yezere''eli, me no ba da''ö so Yoramo; ba noa göi so moroi si yaŵa Gahaseyahu, razo mado Yuda, ba wamaigi Yoramo.[8]', '["Faigi 8:28,29","Faigi 8:29","RazI 21:1"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 17, 'Ba no so ba malige ba Yezere''eli zanaro. Ba me i''ila moroi sa ndra Yehu, ba imane: Oroma moroi sa niha, sambawa! Ba imane Yoramo: ŵa''ö zi fakudo, ba fatenge ia, ba wamaondragö ya''ira, ena''ö imane khöra: Hadia, ba zatulö möi ami?', '["Faigi 8:28,29","Faigi 8:29","RazI 21:1"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 18, 'Ba ifaondragö ira si fakudo andrö, ba imane: Da''ö niŵa''ö razo: Hadia, ba zatulö möi ami? Ba imane Yehu: Hana wa öhalö khöu? iagö furima, o''ö ndra''aga! Ba i''ombakha''ö sanaro andrö, imane: No irugi ira sinenge andrö, ba lö mangawuli.', '["Faigi 8:28,29","Faigi 8:29","RazI 21:1"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 19, 'Ba ifatenge zamösa tö, si fakudo. Ba me irugi ira, ba imane: Da''ö niŵa''ö razo: Hadia, ba zatulö möi ami? Ba imane Yehu: Hana wa öhalö khöu da''ö?', '["Faigi 8:28,29","Faigi 8:29","RazI 21:1"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 20, 'Iagö furi ba o''ö ndra''aga! Ba i''ombakha''ö sanaro andrö, imane: No irugi ira, ba lö mangawuli ia. Ba famandruo kudo andrö, ba no hulö wamandruo Yehu andrö, ma''uwu Nimisi; noa sa nifamandruo zowöhö khönia.', '["Faigi 8:28,29","Faigi 8:29","RazI 21:1"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 21, 'Ba imane Yoramo: Mifa''anö kudo! Ba me no lafa''anö ba guretania, ba lasaŵa, darua ira Yoramo, razo Ndraono Gizeraeli, Gahaseyahu, razo mado Yuda; lafaondragö Yehu, ba ba mbenua Naboti andrö no, banua Yezere''eli, fakhamö ira khönia.[9]', '["Faigi 8:28,29","Faigi 8:29","RazI 21:1"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 22, 'Ba me i''ila Yehu Yoramo, ba imane: Hadia, ba zatulö möi''ö, Yehu? Ba imane Yehu: Hadia zatulö, fatua lö tebato wohorö-horö ninau Izebela, awö wakelemusa andrö khönia, si lö mamalö-malö?', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 23, 'Ba ibali''ö ia Yoramo, ba woloi, ba imane khö Gahaseyahu:', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 24, 'No la''a mbölida, Ahaseyahu! Ba ituyu wana Yehu, ifana Yoramo, ba hulu göna, tobali itörö dödö ono wana andrö, ba alau tou ia ba guretania yaŵa.', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 25, 'Ba imane Yehu khö nawönia Bidekari: Halö ia ba tibo''ö ba mbenua Naboti andrö, banua Yezere''eli; itörö sa tödögu, me ta''o''ö namania Ahabi, me fakudo ita, daru-darua ita, me imane Yehowa, ba khönia andrö:[10]', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 26, 'Si ndruhu, do Naboti andrö ba do ndraononia, ba no u''ila menewi, iŵa''ö Yehowa, ba usulöni khöu ba mbenua andre, iŵa''ö Yehowa! Ba halö sa''ae ia ba tibo''ö ba mbenua andrö, dali niŵa''ö Yehowa.', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 27, 'Ba me i''ila da''ö Ahaseyahu, razo mado Yuda, ba moloi ia, itörö lala ba nose ba kabu. Ba i''ohi ia Yehu, imane: Ya''ia göi! Mifana ia! Ba lafana ia, ba gureta, ba lala miyaŵa ba Guri, ba ngai Yibela''a. Ba moloi ia, isaŵa Megido ba mate ia ba da''ö.[11]', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 28, 'Ba lahare''ö ba gureta enoninia, la''ohe ba Yeruzalema ba ba da''ö lako''o ia, ba lewatönia, ba ngai ndra amania, ba mbanua Dawido.[12]', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 29, 'Me no alua mewulu fakhe razo Yoramo, ono Gahabi, mege, tobali razo mado Yuda Gahaseyahu andrö.', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 30, 'Ba irugi Yezere''eli Yehu. Ba me irongo da''ö Izebela, ba ifosönö röngöröngönia ba ihaogö mbunia ba ifaigi ba zandrela.', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 31, 'Ba me itörö mbawa göli Yehu, miyomo, ba imane Izebela: Hadia, sohahau tödö mege Zimeri andrö, samunu sokhö ya''ia?[13]', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 32, 'Ba ifaigi miyaŵa zandrela Yehu, ba imane: Ha niha zi fa''awö khögu? ha niha? Ba me lafaigi ia moroi yaŵa enoni Gizebela, enoni yomo, darua, datölu, ba imane:', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 33, 'Mituli''ö tou ia! Ba latuli''ö tou Gizebela, tobali tokana ba mbagolö ba ba kudo ndronia, ba lahundragö ia, kudo.', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 34, 'Ba Yehu, ba möi yomo manga. Ba aefa da''ö, ba imane: Mi''ae mifaigi ni''elifi andrö, ba miko''o ia; me no ono razo.', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 35, 'Ba me möi, ba wogo''o ya''ia, ba lö''ö sa''ae hadia ia tou, ha solesole högö ba ahe ba lalu''a danga.', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 36, 'Ba lafuli ira, la''ombakha''ö khö Yehu; ba imane: No itörö niŵa''ö Yehowa andrö, nifa''ema genoninia Eliya, banua Disebe, me imane: Ba danö Yezere''eli andrö dania la''a nösi Gizebela andrö asu,[14]', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475061, 'OT', 'Razo II', 9, 37, 'ba boto Gizebela, ba si fadoro oboula ba mbörö zinanö dania, ba danö Yezere''eli andrö, fa tebai sa''ae laŵa''ö: Da''e Gizebela andrö!', '["RazI 21:19","Nga''ötII 22:7—9","Faigi 14:20, 23:30","RazI 16:10,18","Ayati 10; RazI 21:23"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 1, 'Ba 70 na nono Gahabi, ba Zamaria. Ba ifazökhi zura Yehu ba ifa''ohe''ö khö gumandra mbanua ba ba zatua mbanua ba ba nifataro satua ndraono Gahabi andrö, imane ba zura andrö:', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 2, 'Na möi ba dangami zura andre, ya''ami si so barö mbawa iraono zokhö ya''ami andrö ba kureta ba kudo ba banua saro ba fangöna,', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 3, 'ba mifaigi ha niha zi sökhi ndraono zokhö ya''ami, ha niha zabölö, ba mifedadao ba dadaoma namania, ba milau fa''awö ba nga''ötö zokhö ya''ami andrö.', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 4, 'Ba ata''u sibai ira, ba lamane: Me no tebai latimba ia razo andrö, si darua andrö, ba he wisa ita?', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 5, 'Ba lafatenge khö Yehu ira kumandra ba gödo kumandra mbanua ba salaŵa ba si no mufataro satua [ndraono Gahabi], lamane: Sawuyumö ndra''aga, ba hadia ia fefu niŵa''öu, khöma, ba ma''o''ö. Tebai mamataro razo ndra''aga; lau zomasi''ö.', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 6, 'Ba ifuli ifa''ohe''ö khöra zura, imane: Ba na khögu fa''awö ami, ba na edöna mi''o''ö niŵa''ögu, ba mihalö högö ndraono zokhö ya''ami mege, ba mi''ohe khögu ba Yezere''eli, mahemolu, na mane wa''alaŵa luo. Ba ono razo andrö, si fitu ngafulu, ba ba zatua mbanua so, da''ö zange''ebua.', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 7, 'Ba me no latema zura andrö, ba lahalö nono razo andrö ba lataba mbagi, fitu ngafulu, labe''e ba ragaraga högö ba lafa''ohe''ö khö Yehu ba Yezereeli.', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 8, 'Ba me i''ombakha''ö khönia sinenge, no la''ohe högö nono razo andrö, ba imane: Mibe''e ba zinga mbawa göli, irugi mahemolu mbanua, mifodombua nahia.', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 9, 'Ba ba zanguhulö wongi, ba möi ia baero, i''agö da''ö, ba imane ba niha sato fefu: Lö horömi! Hiza, ya''odo zamagölö ba nawögu, udu zokhö ya''o, ba no ubunu ia; ba ha niha atö zamunu da''e fefu?', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 10, 'Ba ya''aboto ba dödömi, wa sambalö lö saekhu ba danö taroma li Yehowa, niŵa''önia ba zi samba omo ndra Ahabi; noa sa ifalua Yehowa niŵa''önia, nifa''ema genoninia Eliya.[1]', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 11, 'Aefa da''ö, ba ibunu Yehu fefu zi tosai zi samba omo ndra Ahabi, ba Yezere''eli, ba salaŵa andrö khönia ba si no fa''ila li khonia ba ere andrö khönia, tobali samösa lö soloi.', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 12, 'Ba maoso ia, mofanö, isaŵa Zamaria. Ba me no irugi Mbeti Ekedi,', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 13, 'ba falukha ia ndra talifusö Gahaseyahu, razo mado Yuda. Ba imane khöra: Ha niha ami? Ba lamane: Talifusö Gahaseyahu ndra''aga, möiga misi tou falukha ba nono razo ba ba nono nina razo.[2]', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 14, 'Ba imane: Mira''u auri ira! Ba lara''u auri ba labunu ba latibo''ö ba mba''a ba Mbeti Ekedi, 42 niha, tobali samösa lö si tosai.', '["RazI 21:22","Nga''ötII 22:8"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 15, 'Ba me aefa ia ba da''ö, ba falukha ia Yonadabi, ono Rekhabi, si faondra khönia. Ba i''owai ba imane khönia: Hadia, satulö tödö khögu ndra''ugö, si mane ya''odo khöu? Ba imane Yonadabi: Si manö! Ba imane Yehu: Na si manö, ba da dangau! Ba fara''u tanga ia khönia; ba ifa''amöi ia khönia, ba gureta yaŵa,[3]', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 16, 'ba imane khönia: Ae awögu ba faigi wa''owölö-ölögu ba khö Yehowa! Ba fao ia khönia ba guretania.', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 17, 'Ba me no irugi Zamaria Yehu, ba ibunu fefu zi tosai motöi khö Gahabi, irege no ihori fefu, dali li Yehowa, niŵa''önia khö Geliya.[4]', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 18, 'Aefa da''ö, ba ifalukha''ö niha sato fefu Yehu, ba imane khöra: Lö aröuröu wamosumange Gahabi Ba''ali andrö, ba Yehu, ba iforege wamosumange ya''ia.[5]', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 19, 'Ba mihede ba zama''ele''ö andrö khö Mba''ali fefu, samosumange ya''ia ba ere andrö khönia, fefu, ba mi''asogö khögu; lö tola lö ahori so ira! So dania khögu gowasa sebua, ba wamosumange Ba''ali; dozi si lö möi, ba nibunu! Ba fa''onekhe Yehu da''ö, ba wamunu samosumange Ba''ali.', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 20, 'Ba imane Yehu: Mifarongogö, ena''ö lö olifu ira gamonita ba gowuloa andrö khö Mba''ali. Ba latarongogö ba niha.', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 21, 'Ba ifatenge zinenge Yehu ba Ndraono Gizeraeli fefu; ba ahori so zamosumange Ba''ali, lö si toröi furi, si lö möi. Ba möi ira ba gosali Mba''ali andrö, tobali afönu niha gosali Mba''ali, i''otarai gero mbawandruhö irugi miyaŵa, fefu.', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 22, 'Ba imane Yehu khö mandru ba mbate''e nukha: Dozigö nukha zamosumange Ba''ali andrö! Ba ibe''e baero khöra nukha.', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 23, 'Ba möi ba gosali Yehu, awö Yonadabi andrö, ono Rekhabi, ba imane ba zamosumange Ba''ali: Mi''alui ba mifaigi, fa böi fakhöyö ba khömi ba da''e zamosumange Yehowa, ena''ö ha sambalö samosumange Ba''ali.[6]', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 24, 'Ba möi bakha Yehu, ba wame''e sumange nitaba ba sumange nitunu; ba no 80 ifataro tou niha, no imane: Na so zame''e moloi zamösa niha andrö, nibe''egu ba dangami, ba nosonia labe''e fangali noso zoloi andrö.[7]', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 25, 'Ba me no i''asiwai zumange nitunu andrö Yehu, ba imane ba nawönia sabölö andrö: Mi''ae bakha, ba mi''ö''ötö tou ira, samösa böi mifolala baero! Ba la''ö''ötö tou ira si''öli sabölö andrö, ba lafazaumba baero ba möi ira ba hati gosali Mba''ali,[8]', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 26, 'ba la''ohe baero Gasera andrö, ba gosali Mba''ali, ba latunu;[9]', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 27, 'ba larasa wamaedo Mba''ali andrö, ba ladudugö gosalinia, ba labali''ö e''era, irugi ma''ökhö andre.[10]', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 28, 'Ba tobali ihori Mba''ali andrö Yehu, ba Ndraono Gizeraeli.', '["Yer 35:6","RazI 21:21,22","RazI 16:31—33","Ayati 15","RazI 20:39","RazI 18:40","Faigi 11:18","Faigi 3:2"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 29, 'Ba horö Yerobeamo andrö, ono Nebati, famaelungunia Iraono Gizeraeli, ba lö iböhöli Yehu, — ono zaŵi balaki andrö ba Mbetieli ba ba Dano.[11]', '["RazI 12:26—33","Faigi 15:12","Faigi 8:12","Faigi 13:1"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 30, 'Ba imane Yehowa khö Yehu: Me no öhaogö wolau somasi ndra''o me no ahori öfatörö ba zi samba omo ndra Ahabi zi so ba dödögu, ba irege tölu nga''ötö ma''uwumö dania zidadao ba dadaoma razo ba Ndraono Gizeraeli.[12]', '["RazI 12:26—33","Faigi 15:12","Faigi 8:12","Faigi 13:1"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 31, 'Ba lö itöngöni Yehu wanörö lala goroisa Yehowa, Lowalangi Ndraono Gizeraeli, soroi si''aikö ba dödö; lö iböhöli horö andrö, horö Yerobeamo, ono Nebati, famaelungunia Iraono Gizeraeli.', '["RazI 12:26—33","Faigi 15:12","Faigi 8:12","Faigi 13:1"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 32, 'Ba me luo da''ö, ba ibörötaigö mofönu Yehowa ba Ndraono Gizeraeli, ba i''alani ira Hazaeli andrö, tanö ba nola danöra, ma''asara,[13]', '["RazI 12:26—33","Faigi 15:12","Faigi 8:12","Faigi 13:1"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 33, 'i''otarai Yoridano, numalö misa ba gatumbukha luo, tanö Gileadi ma''asagörö, mado Gado ba mado Rubeno ba mado Manase, i''otarai Garuri ba mbewe Garono, he tanö Gileadi ba he tanö Mbazana [ba ibe''e barö mbawania].', '["RazI 12:26—33","Faigi 15:12","Faigi 8:12","Faigi 13:1"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 34, 'Ba hadia na ena''ö nidunö-dunö ba khö Yehu andrö, ba hadia ia fefu, nilaunia, ba fa''abölönia fefu, ba no mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["RazI 12:26—33","Faigi 15:12","Faigi 8:12","Faigi 13:1"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 35, 'Ba itörö lala ndra amania Yehu, mate ia, ba ba Zamaria lako''o ia; ba fangalinia razo, ba ononia Yoahasi.[14]', '["RazI 12:26—33","Faigi 15:12","Faigi 8:12","Faigi 13:1"]', NULL),
  (3475063, 'OT', 'Razo II', 10, 36, 'Ba fa''ara wa''arazonia ba Ndraono Gizeraeli, ba no 28 fakhe, ba Zamaria.', '["RazI 12:26—33","Faigi 15:12","Faigi 8:12","Faigi 13:1"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 1, 'Ba me irongo Atalia andrö, ina Gahaseyahu, no mate nononia, ba maoso ia, mangohori nga''ötö razo.[1][2]', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 2, 'Ba maoso Yoseba, ono razo Yehoramo alawe, talifusö Gahaseyahu, ihalö Yoasi andrö, ono Gahaseyahu, iheta ba ngai nono razo bunusö andrö, ibini''ö, i''ohe si bakha, awö babunia. Ibini''ö khö Gatalia, fa böi labunu ia.', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 3, 'Ba si tobini Yoasi, awö Yoseba, ba gosali Yehowa, meönö fakhe wa''ara, götö wa''arazo Gatalia ba danö.', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 4, 'Ba me no alua zi meöno fakhe, ba ifatenge Yoyada, ifahalö''ö gumandra zi otu andrö, fazuri ba awö razo, khönia ba gosali Yehowa. Ba ilau fawu''u li khöra, ibe''e ba hölu ira, ba gosali Yehowa. Ba awena i''oroma''ö khöra nono razo andrö.', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 5, 'Ba ibe''e li khöra, imane: Da''ö halöŵömi: Si saraö ya''ami, nifataro sanaro na luo sabato, ba sanaro ba gödo razo;', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 6, 'ba si saraö, ba ba mbawa göli Suri manaro, ba si saraö zui, ba ba mbawa göli furi nawö razo andrö, ena''ö sanaro ba gödo ami;', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 7, 'ba duata ya''ami, dozi ami nifataro sanaro na luo sabato, ba sanaro ba gosali Yehowa, awö razo.', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 8, 'Mifasui razo, fangöna ba danga zamösana, ba sanaŵa ya''ami, ba nibunu. Mi''iagö awö razo, na möi ia tou ba na möi yomo.', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 9, 'Ba la''o''ö da''ö ira kumandra zi otu, dali niŵa''ö Yoyada ere khöra; la''ohe wazuri andrö khöra, he saheta sanaro na luo sabato, ba he sawena möi sanaro, möi ira khö Yoyada ere.', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 10, 'Ba ere andrö, ba ibe''e ba danga ndra kumandra zi otu andrö doho ba baluse andrö, khö razo Dawido mege, si so ba gosali Yehowa.[3]', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 11, 'Ba la''agö golayama gosali Yehowa awö razo andrö, i''otarai tanö raya, numalö miyöu, irugi naha wame''e sumange ba mangawuli ba gosali, lafasui razo, oi dozi fangöna ba danga.', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 12, 'Ba i''ohe baero nono razo andrö Yoyada, lafanaembu ia, ba labe''e khönia wamaduhu''ö andrö [sura goroisa], lafataro razo ia ba labayoini, ba lalau datawö ba mu''ao ira, lamane: Ya ahowu razo![4]', '["Faigi göi Nga''ötII 22:10—23:21","Faigi 8:26; 9:27","SamII 8:7","MozV 17:18,19"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 13, 'Ba me irongo Atalia we''ao nawö razo andrö, fazuri, ba fe''ao niha sato, ba isaŵa niha sato, ba gosali.', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 14, 'Ba ifaigi, ba hiza, ba no muziozio ba ngai daru nahe razo — si manö huku ba razo — ba kumandra andrö ba solau-lau torofe, awö razo, ba he niha sato ba danö, ba no somuso tödö ba lalau dorofe. Ba itika nukhania Atalia ba imane:', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 15, 'Folaŵa! Folaŵa! Ba ibe''e li Yoyada ba gumandra zi otu, kumandra zabölö, imane khöra: Mi''ohe baero ia, mifatörö ba gotalua wazuri ba ha niha zolo''ö ya''ia, ba mibunu si''öli! Noa sa iŵa''ö ere, böi ba gosali Yehowa labunu ia.', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 16, 'Ba lara''u ia, ba ba lala kudo lafatörö, wolohe ba gödo razo ba ba da''ö labunu.[5]', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 17, 'Ba ifawu''u li ira Yehowa razo, awö niha sato, Yoyada, ena''ö banua Yehowa ira, ba ifawu''u li göi ira razo niha sato.', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 18, 'Aefa da''ö, ba lasaŵa gosali Mba''ali niha sato ba danö ba ladudugö. Naha wame''e sumange khönia ba famaedonia, ba lafaulugö worasa; ba Matana andrö, ere khö Mba''ali, ba labunu föna naha wame''e sumange. Aefa da''ö, ba ifataro zanaro ba gosali Yehowa ere andrö.[6]', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475064, 'OT', 'Razo II', 11, 19, 'Ba ifa''aso ndra kumandra zi otu ba fazuri ba awö razo andrö ba he niha sato ba danö, ba la''ohe mitou razo, laheta ba gosali Yehowa, ba mbawandruhö nawö razo andrö lafatörö, wolohe ya''ia ba gödo razo; ba mudadao ia ba dadaoma razo.', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 20, 'Ba oi somuso tödö niha ba danö; ba lö hadia zaekhu niha yomo ba mbanua. Ba Atalia, ba labunu si''öli, ba gödo razo.', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL),
  (3475064, 'OT', 'Razo II', 11, 21, 'Ha mewitu fakhe wa''ebua Yoasi, me tobali razo ia.', '["Neh 3:28","Faigi 10:26,27; Sanguhuk 6:25"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 1, 'Me no alua me''önö fakhe razo Yehu tobali razo Yoasi andrö, ba 40 fakhe razo ia ba Yeruzalema; ba töi ninania, ba Sibia, banua Mbereseba.[1]', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 2, 'Ba somasi Yehowa ilau Yoasi, götö wa''anau nosonia, me no ifahaö ia Yoyada ere andrö.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 3, 'Ha hili-hili andrö zi lö mubulö''ö; mame''e-me''e sumange na zato ba hili-hili andrö, ba manunu kumöyö.[2]', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 4, 'Ba imane Yoasi ba gere: Fefu gefe andrö, ni''ohe ba gosali Yehowa, buala ni''amoni''ö, ömö zamösana, nihonogöi, ba hadia ni''ohe zamösana ba gosali Yehowa,', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 5, 'saoha gölö, ba ndramuhalö ere; ba zi no fa''ila li khönia ihalö zamösana. Ba labe''e balazo ba wangazökhi si no adudu ba gosali, hadia ni''ilara si no adudu.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 6, 'Ba no alua 22 fakhe razo Yoasi, ba lö''ö na ni''a''azökhi gere si no adudu ba gosali.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 7, 'Ba ifakaoni''ö razo Yoasi högö gere andrö, Yoyada, awö gere bö''ö, ba imane khöra: Hana wa lö mi''azökhi zadudu ba gosali? Böi sa''ae göi manema ana''a ami ba zi no fa''ila li khömi, milulu sa''ae balazo ba zadudu ba gosali.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 8, 'Ba atulö dödö gere: lö''ö sa''ae latema gana''a ba zato, ba lö''ö göi la''a''azökhi zadudu ba gosali.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 9, 'Ba ihalö kotakota Yoyada ere, itöla''ö lagö-lagö, ba ibe''e ba gambölö naha wame''e sumange ba zinga lala niha, na möi ba gosali Yehowa. Ba da''ö bakha labe''e ere sanaro ba mbawandruhö, gefe andrö, ni''ohe ba gosali Yehowa.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 10, 'Ba na la''ila, no oya gefe ba kotakota andrö, ba so durutuli razo, awö gere sebua, ba labu''ugö gefe andrö, nisöndra ba gosali, ba la''erai.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 11, 'Ba na no mutulo, ba labe''e ba mandru duka andrö, samaigi-maigi ba gosali Yehowa, ba da''ö same''e ba zohalöŵö, ba duka andrö, sohalöŵö ba gosali Yehowa,', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 12, 'zanoto kara ba sama''anö kara, ba ba wowöli eu, awö gara nitoto, ena''ö te''azökhi zi no adudu ba gosali Yehowa, — balazo hadia ia fefu ni''a''azökhi ba gosali Yehowa.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 13, 'Ba ame''ela andrö, ni''ohe ba gosali, ba lö labe''e ba wamazökhi mako ba si''öli ba figa ba torofe, ba hadia ia wakake ana''a, ba ma fakake firö, soguna ba gosali Yehowa,', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 14, 'ba zohalöŵö andrö labe''e, balazo ni''a''azökhi ba gosali Yehowa.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 15, 'Ba lö''ö sa fa''era ira ba niha andrö, nibe''e ba danga kefe andrö, ba wame''e ba zohalöŵö, faduhu manö dödöra khöra.[3]', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 16, 'Ba ame''ela andrö, na so zame''e sumange ogauta, ba sumange fameta horö, ba lö la''ohe ba gosali, ba gere möi da''ö.', '["Faigi göi Nga''ötII 24","Faigi 14:4; RazI 22:44","Faigi 22:7"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 17, 'Ba me luo da''ö, ba so moroi yöu Hazaeli, razo Ndrawa Garamo, isuwö Gata, ba atu''a ia ba mbanua. Ba me isuwö göi ena''ö Yeruzalema Hazaeli,[4]', '["Faigi 10:32","RazI 15:18","Faigi 14:5","Faigi 14:1"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 18, 'ba ihalö gana''a andrö ba gosali Yoasi, razo mado Yuda, buala ni''amoni''ö andrö fefu, ni''amoni''ö ndra tuania Yozafati, Yehoramo ba amania Ahaseyahu, razo mado Yuda, ba bualania, ni''amoni''ö, awö gana''a andrö fefu, si so ba mbate''e girö-girö andrö, ba gosali Yehowa ba ba gödo razo, ba ifa''ohe''ö khö Hazaeli, razo Ndrawa Garamo. Ba lö alua isuwö Yeruzalema.[5]', '["Faigi 10:32","RazI 15:18","Faigi 14:5","Faigi 14:1"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 19, 'Ba hadia na nidunö-dunö ena''ö ba khö Yoasi andrö ba hadia ia fefu, nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["Faigi 10:32","RazI 15:18","Faigi 14:5","Faigi 14:1"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 20, 'Ba maoso genoninia, molaŵa, mamagölö, ba labunu Yoasi.[6]', '["Faigi 10:32","RazI 15:18","Faigi 14:5","Faigi 14:1"]', NULL),
  (3475065, 'OT', 'Razo II', 12, 21, 'Ira Yozakhari, ono Zimeata, Yozabadi, ono Zomeri, enoninia, zamunu ya''ia; ba ba mbanua Dawido lako''o ia, ba ngai ndra amania. Ba fangalinia razo, ba ononia Amasia.[7]', '["Faigi 10:32","RazI 15:18","Faigi 14:5","Faigi 14:1"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 1, 'Me no alua 22 fakhe razo mado Yuda Yoasi andrö, ono Gahaseyahu, tobali razo Ndraono Gizeraeli Yoahasi, ono Yehu, ba Zamaria, mewelewitu fakhe.[1]', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 2, 'Ba si fatuwu khö Yehowa ilau; i''ohia''ö horö Yerobeamo, ono Nebati, famaelungunia Iraono Gizeraeli mege; lö iböhöli da''ö.[2]', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 3, 'Ba mofönu Yehowa ba Ndraono Gizeraeli, ba ibe''e ira ba danga Hazaeli andrö, razo Ndrawa Garamo, ba ba danga Mbenihada, ono Hazaeli, sagötö fa''ara.[3]', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 4, 'Ba i''andrö wa''ebolo dödö Yehowa Yoahasi, ba ifondrondrongo khönia Yehowa, börö me i''ila wa''atosasa Ndraono Gizeraeli, me isasagö ira razo Ndrawa Garamo.', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 5, 'Ba i''asogö zangorifi Iraono Gizeraeli Yehowa, ba tobali aefa ira barö mbawa Ndrawa Garamo, ba lö''ö sa''ae hadia ia ba Ndraono Gizeraeli, ba nosera; ifuli si mane föna.[4]', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 6, 'Ba lö''ö sa laböhöli horö zi samba omo ndra Yerobeamo andrö, fama''elungunia Iraono Gizeraeli; lala da''ö latörö. Ba lö''ö göi tebulö Gasera andrö ba Zamaria.[5]', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 7, 'Lö''ö sa isaigö khö Yoahasi zabölö Yehowa, ha 50 zi fakudo ba fulu gureta ba 10.000 si lö kudo. Noa sa ihori razo Ndrawa Geramo, no ifufu.', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 8, 'Ba hadia na nidunö-dunö ena''ö ba khö Yoahasi andrö, ba hadia ia fefu nilaunia, ba fa''abölönia andrö, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 9, 'Ba mate Yoahasi, itörö lala ndra amania, ba ba Zamaria lako''o ia. Ba fangalinia razo, ba ononia Yoasi.', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 10, 'Me no alua 36 fakhe razo mado Yuda Yoasi andrö, tobali razo Ndraono Gizeraeli ba Zamaria Yoasi, ono Yoahasi, meweleönö fakhe.', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 11, 'Ba si fatuwu khö Yehowa ilau; lö iböhöli horö Yerobeamo, ono Nebati, famaelungunia Iraono Gizeraeli; lala da''ö itörö.', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 12, 'Ba hadia na nidunö-dunö ena''ö, ba khö Yoasi andrö, ba hadia ia fefu nilaunia ba fa''obölönia andrö, ba fasuwötania khö Gamasia andrö, razo mado Yuda, ba no mutanö ba zura hikaya razo Ndraono Gizeraeli.[6]', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 13, 'Ba mate Yoasi, itörö lala ndra amania, ba Yerobeamo zidadao ba dadaoma razo. Ba ba Zamaria teko''o Yoasi, ba ngai razo Ndraono Gizeraeli andrö.[7]', '["Faigi 10:35","RazI 12:26—33","Faigi 10:32","Faigi 14:27","RazI 16:33","Faigi 14:8—16","Faigi 14:23"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 14, 'Ba mafökhö Gelisa, fökhö ba wa''amate. Ba so Yoasi andrö, razo Ndraono Gizeraeli, möi mitou khönia ba mege-ege ba ngainia, imane: He amagu! he amagu! kureta Ndraono Gizeraeli, awö zi fakudo![8]', '["Faigi 2:12"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 15, 'Ba imane khönia Elisa: Da wana, awö nono! Ba ibe''e khönia wana, awö nono.', '["Faigi 2:12"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 16, 'Ba imane khö razo Ndraono Gizeraeli andrö: Tufa tangau wana andre! Ba me no itufa, ba ifalaete dangania ba danga razo Elisa.', '["Faigi 2:12"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 17, 'Ba imane: Bokai zandrela tanö ba gatumbukha luo! Ba me no ibokai, ba imane Elisa: Efasi wana! Ba i''efasi. Ba imane Elisa: Ono wana ba wemöna, khö Yehowa! Ono wana ba wolaŵa Dawa Garamo! Ba Gafeki dania ölau ba Ndrawa Garamo, irege ahori ira.', '["Faigi 2:12"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 18, 'Ba imane na: Halö nono wana andrö! Ba ihalö. Ba imane khö razo Ndraono Gizeraeli: Amözi''ö tanö! Ba medölu ibözi danö, awena ibato.', '["Faigi 2:12"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 19, 'Ba mofönu khönia genoni Lowalangi andrö, imane: Melima ena''ö öbözi, ba ma meönö, ba ölaŵa Ndrawa Garamo, irege ahori ira; ba me si manö, ba ha medölu ö''alani ira.', '["Faigi 2:12"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 20, 'Ba mate Gelisa ba lako''o ia, me luo da''ö, ba möi-möi ba danö zanuwö, Iraono Moabi.', '["MozIII 26:42","Ayati 19"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 21, 'Ba so zi mate niko''o sibai ena''ö, ba hiza moroi sa zanuwö, si lö mudöna-döna. Ba latibo''ö manö ba lewatö Gelisa zi mate andrö ba lalau moloi. Ba me fabaya ba mboto Gelisa mboto zi mate andrö, ba ifuli auri, muzizio.', '["MozIII 26:42","Ayati 19"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 22, 'Ba no ifakao Ndraono Gizeraeli Hazaeli andrö, razo Ndrawa Garamo, götö wa''anau noso Yoahasi.', '["MozIII 26:42","Ayati 19"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 23, 'Ba ifuli ebua dödö Yehowa khöra, ihakhösi tödö ira; ifuli i''otahögö ira, börö wawu''usa li andrö khönia khö ndra Aberahamo, Iza''aki, Yokobo, ba lö omasi ia tekiko ira, ba irugi da''ö, ba lö nitibo''önia ya''ira, fa lö''ö sa''ae ifaigi ira.[9]', '["MozIII 26:42","Ayati 19"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 24, 'Ba mate Hazaeli, razo Ndrawa Garamo, ba ononia Benihada zi tobali razo, fangalinia.', '["MozIII 26:42","Ayati 19"]', NULL),
  (3475066, 'OT', 'Razo II', 13, 25, 'Ba maoso Yoasi, ono Yoahasi, ifadöni mbanua andrö khö Mbenihada, ono Hazaeli, banua nifadöni Hazaeli khö nama Yoasi, Yoahasi, me isuwö ia no. Medölu te''ala Mbenihada ibo''e Yoasi, ba ihalö mangawuli mbanua Ndraono Gizeraeli andrö.[10]', '["MozIII 26:42","Ayati 19"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 1, 'Me arakha mendrua fakhe razo Ndraono Gizeraeli Yoasi andrö, ono Yoahasi, tobali razo mado Yuda Gamasia, ono Yoasi.[1][2]', '["Ayati 1—22: Nga''ötII 25:1—26:2","Faigi 12:22","Faigi 12:3, 4","Faigi 15:4","Faigi 12:21,22","MozV 24:16"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 2, 'Dua wulu a lima fakhe ia, me tobali razo ia, ba 29 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Yoadina, banua Yeruzalema.', '["Ayati 1—22: Nga''ötII 25:1—26:2","Faigi 12:22","Faigi 12:3, 4","Faigi 15:4","Faigi 12:21,22","MozV 24:16"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 3, 'Ba somasi Yehowa ilau, ba tenga sa atö si mane tuania Dawido; fefu hadia ia khönia ba nifolau namania Yoasi mege.[3]', '["Ayati 1—22: Nga''ötII 25:1—26:2","Faigi 12:22","Faigi 12:3, 4","Faigi 15:4","Faigi 12:21,22","MozV 24:16"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 4, 'Ha hili-hili andrö zi lö labulö''ö; lö mamalö-malö wame''e zato sumange, awö wanunu kumöyö ba hili-hili andrö.[4]', '["Ayati 1—22: Nga''ötII 25:1—26:2","Faigi 12:22","Faigi 12:3, 4","Faigi 15:4","Faigi 12:21,22","MozV 24:16"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 5, 'Ba me no aro ba dangania wa''arazo, ba ifabunu''ö genoninia andrö, samunu razo amania, mege.[5]', '["Ayati 1—22: Nga''ötII 25:1—26:2","Faigi 12:22","Faigi 12:3, 4","Faigi 15:4","Faigi 12:21,22","MozV 24:16"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 6, 'Ba iraono zange''e andrö, ba lö''ö sa ifabunu''ö, dali goroisa Yehowa andrö, si so ba zura goroisa andrö khö Moze, no imane: Böi labunu nama, börö ndraono, ba böi labunu ndraono, börö nama; ha ba horönia labunu zamösana.[6]', '["Ayati 1—22: Nga''ötII 25:1—26:2","Faigi 12:22","Faigi 12:3, 4","Faigi 15:4","Faigi 12:21,22","MozV 24:16"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 7, 'Ya''ia zi alani Iraono Gedomo, ba ndraso zilua asi andrö, 10.000 nibunu; ba atu''a ia ba mbanua Zela; ba ibe''e töi mbanua andrö Yokete''eli, irugi ma''ökhö andre.', '["Ayati 1—22: Nga''ötII 25:1—26:2","Faigi 12:22","Faigi 12:3, 4","Faigi 15:4","Faigi 12:21,22","MozV 24:16"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 8, 'Ba me luo da''ö, ba ifatenge zinenge Amasia, khö Yoasi andrö, ono Yoahasi, ma''uwu Yehu, razo Ndraono Gizeraeli, imane khönia: Ae khögu, datalau fatandra fa''abölö!', '["Sanguhuk 9:14"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 9, 'Ba imane Yoasi, razo Ndraono Gizeraeli khö Gamasia, razo mado Yuda: Sa''a-sa''a mao ba hili Libano, ba no ifatenge khö geresi ba hili Libano, imane: Datalau fambambatö! Ba latörö za''a-sa''a mao andrö utu ndru''u ba hili Libano, lahundra-hundra.[7]', '["Sanguhuk 9:14"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 10, 'Me no falukha''ö zalöfö, wangalani Iraono Gedomo, ba no tesao wayaŵasamö. Hana na ebua duriamö, ba böi bulö''ögö khömi! Hadia wa ö''alu-alui wamunu, ena''ö mate ndra''ugö, fabaya mado Yuda?', '["Sanguhuk 9:14"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 11, 'Ba lö ifondrondrongo Amasia. Ba möi misi yaŵa Yoasi, razo Ndraono Gizeraeli, ba fatandra fa''abölö ira, darua ira Gamasia, razo mado Yuda, ba ngai Mbetiseme, ba danö mado Yuda.', '["Sanguhuk 9:14"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 12, 'Ba te''ala mado Yuda labe''e Iraono Gizeraeli, tobali isaŵa khöra zamösana, moloi.', '["Sanguhuk 9:14"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 13, 'Ba ira''u Gamasia, razo mado Yuda, ono Yoasi ono Gahaseyahu, Yoasi, razo Ndraono Gizeraeli, ba Mbetiseme ira''u, ba i''ohe ba Yeruzalema. Ba itöla''ö göli Yeruzalema, i''otarai mbawa göli Geferayi, irugi mbawa göli ba watalinga andrö, 400 hela wa''anau.', '["Sanguhuk 9:14"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 14, 'Ba ahori ihalö gana''a, awö wirö, awö gama-gama, ba gosali Yehowa ba ba mbate''e girö-girö andrö, ba gödo razo, awö niha ösa, we''e-we''e dödö, ba ifuli ia ba Zamaria.', '["Sanguhuk 9:14"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 15, 'Ba hadia na ena''ö nidunö-dunö ba khö Yoasi andrö, hadia nilaunia ba fa''abölönia andrö, ba fasuwötania khö Gamasia, razo mado Yuda, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["Faigi 13:13","Faigi 12:21","Faigi 9:28","Faigi 15:1,2","Faigi 16:6"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 16, 'Ba itörö lala ndra amania Yoasi, mate ia, ba ba Zamaria lako''o ia, ba ngai razo Ndraono Gizeraeli andrö. Ba fangalinia razo ba ononia Yerobeamo.[8]', '["Faigi 13:13","Faigi 12:21","Faigi 9:28","Faigi 15:1,2","Faigi 16:6"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 17, 'Ba mewelelima fakhe tö na wa''anau noso Gamasia andrö, razo mado Yuda, me no mate Yoasi, ono Yoahasi, razo Ndraono Gizeraeli.', '["Faigi 13:13","Faigi 12:21","Faigi 9:28","Faigi 15:1,2","Faigi 16:6"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 18, 'Ba hadia na ena''ö nidunö-dunö ba khö Gamasia andrö, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["Faigi 13:13","Faigi 12:21","Faigi 9:28","Faigi 15:1,2","Faigi 16:6"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 19, 'Ba so zamagölö ba khönia, ba Yeruzalema, ba wamunu ya''ia. Ba moloi ia, isaŵa Lakhisi; ba lafatenge zolo''ö ya''ia ba Lakhisi, lafabunu''ö ia ba da''ö.[9]', '["Faigi 13:13","Faigi 12:21","Faigi 9:28","Faigi 15:1,2","Faigi 16:6"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 20, 'Ba labe''e yaŵa ba gureta, ba ba Yeruzalema, ba mbanua Dawido andrö, lako''o ia, ba ngai ndra amania.[10]', '["Faigi 13:13","Faigi 12:21","Faigi 9:28","Faigi 15:1,2","Faigi 16:6"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 21, 'Ba lahalö Gasaria andrö mado Yuda sato fefu, he ŵa''ae ha meweleönö fakhe na wa''ebuania, ba lafataro razo, fangali namania Amasia andrö.[11]', '["Faigi 13:13","Faigi 12:21","Faigi 9:28","Faigi 15:1,2","Faigi 16:6"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 22, 'Da''ö zangaro Elata, ifuli ihalö banua mado Yuda, me no itörö lala ndra amania razo, me no mate.[12]', '["Faigi 13:13","Faigi 12:21","Faigi 9:28","Faigi 15:1,2","Faigi 16:6"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 23, 'Me no alua meweleöfa fakhe razo mado Yuda Gamasia andrö, ono Yoasi, tobali razo ba Zamaria Yerobeamo andrö, ono Yoasi, razo Ndraono Gizeraeli, ba 41 fakhe razo ia.[13]', '["Ayati 16; Hos 1:1; Amos 1:1","RazI 12:26—33","Yon 1:1","MozV 32:36","Faigi 13:5","Faigi 15:8"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 24, 'Ba si fatuwu khö Yehowa ilau; lö iböhöli horö Yerobeamo, ono Nebati, famaelungunia Iraono Gizeraeli.[14]', '["Ayati 16; Hos 1:1; Amos 1:1","RazI 12:26—33","Yon 1:1","MozV 32:36","Faigi 13:5","Faigi 15:8"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 25, 'Ya''ia zangai mangawuli tanö Ndraono Gizeraeli andrö, i''otarai lala ba Hamata, numalö ba zilua asi andrö, ba zalo''o, dali li Yehowa, Lowalangi Ndraono Gizeraeli, nifaŵa''ögönia khö genoninia Yona andrö, ono Gamita''i, banua Gata Heferi.[15]', '["Ayati 16; Hos 1:1; Amos 1:1","RazI 12:26—33","Yon 1:1","MozV 32:36","Faigi 13:5","Faigi 15:8"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 26, 'Me no inehegö Yehowa wamakao Iraono Gizeraeli andrö, safö khö sibai; iraono ba satua, ba no ahori, ba lö sangorifi Iraono Gizeraeli.[16]', '["Ayati 16; Hos 1:1; Amos 1:1","RazI 12:26—33","Yon 1:1","MozV 32:36","Faigi 13:5","Faigi 15:8"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 27, 'Ba lö''ö sa niŵa''ö Yehowa ihori ba guli danö döi Ndraono Gizeraeli, ba tobali ibe''e sangorifi ya''ira Yerobeamo andrö, ono Yoasi.[17]', '["Ayati 16; Hos 1:1; Amos 1:1","RazI 12:26—33","Yon 1:1","MozV 32:36","Faigi 13:5","Faigi 15:8"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 28, 'Ba hadia na ena''ö nidunö-dunö ba khö Yerobeamo andrö ba hadia ia fefu nilaunia, ba fa''abölönia andrö, he wisa wasuwötania ba he iwisa wangai mangawuli ba Ndraono Gizeraeli tana ba niha Yehuda ba Ndramaseko ba ba Hamata, ba no mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["Ayati 16; Hos 1:1; Amos 1:1","RazI 12:26—33","Yon 1:1","MozV 32:36","Faigi 13:5","Faigi 15:8"]', NULL),
  (3475067, 'OT', 'Razo II', 14, 29, 'Ba itörö lala ndra amania Yerobeamo, mate ia, ba ba Zamaria lako''o ia, ba ngai razo Ndraono Gizeraeli andrö. Ba fangalinia razo, ba ononia Sakharia.[18]', '["Ayati 16; Hos 1:1; Amos 1:1","RazI 12:26—33","Yon 1:1","MozV 32:36","Faigi 13:5","Faigi 15:8"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 1, 'Me no alua 26 fakhe razo Ndraono Gizeraeli Yerobeamo tobali razo mado Yuda Gasaria andrö, ono Gamasia.[1][2]', '["Ayati 1—7: Nga''ötII 26:1.3—23","Faigi 14:21","Faigi 14,3:4","MozIII 13:46","Ayati 32"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 2, 'Meweleönö fakhe ia, me tobali razo, ba 52 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Yekholia, banua Yeruzalema.', '["Ayati 1—7: Nga''ötII 26:1.3—23","Faigi 14:21","Faigi 14,3:4","MozIII 13:46","Ayati 32"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 3, 'Ba somasi Yehowa ilau, i''ohia''ö sibai nilau namania Amasia.', '["Ayati 1—7: Nga''ötII 26:1.3—23","Faigi 14:21","Faigi 14,3:4","MozIII 13:46","Ayati 32"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 4, 'Hatö hili-hili andrö zi lö labulö''ö; lö tebulö wame''e zato sumange, awö sanunu kumöyö ba hili-hili andrö.[3]', '["Ayati 1—7: Nga''ötII 26:1.3—23","Faigi 14:21","Faigi 14,3:4","MozIII 13:46","Ayati 32"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 5, 'Ba ifatörö wamakao khö razo andrö Yehowa, mobou auri ia ibe''e Yehowa, götö wa''anau nosonia na, ba yomo soso ia. Ba satua baomo ba gödo, ba ononia Yotamo, da''ö zamatunö huhuo zato,[4]', '["Ayati 1—7: Nga''ötII 26:1.3—23","Faigi 14:21","Faigi 14,3:4","MozIII 13:46","Ayati 32"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 6, 'Ba hadia na ena''ö nidunö-dunö ba khö Gasaria andrö ba hadia ia fefu, nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["Ayati 1—7: Nga''ötII 26:1.3—23","Faigi 14:21","Faigi 14,3:4","MozIII 13:46","Ayati 32"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 7, 'Ba mate Gasaria, itörö lala ndra amania, ba ba ngai ndra amania, ba mbanua Dawido, lako''o ia. Ba fangalinia razo, ba ononia Yotamo.[5]', '["Ayati 1—7: Nga''ötII 26:1.3—23","Faigi 14:21","Faigi 14,3:4","MozIII 13:46","Ayati 32"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 8, 'Me no alua 37 fakhe razo Gasaria andrö, razo mado Yuda, tobali razo Ndraono Gizeraeli ba Zamaria Zakharia andrö, ono Yerobeamo, ba ha önö waŵa.[6]', '["Faigi 14:29","RazI 12:26—33","Ayati 14; Amos 7:9","Faigi 10:30"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 9, 'Ba si fatuwu khö Yehowa ilau, nifolau ndra amania ba ira tuania mege. Lö iböhöli horö Yerobeamo, ono Nebati, famaelungunia Iraono Gizeraeli.[7]', '["Faigi 14:29","RazI 12:26—33","Ayati 14; Amos 7:9","Faigi 10:30"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 10, 'Ba molaŵa Zalumi, ono Yabesi, mamagölö ia ba niha bö''ö, ba möi ia mubunu Zakharia, ba Yibelea, ba tobali razo ia, fangali nibununia.[8]', '["Faigi 14:29","RazI 12:26—33","Ayati 14; Amos 7:9","Faigi 10:30"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 11, 'Ba hadia na ena''ö nidunö-dunö ba khö Zakharia, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["Faigi 14:29","RazI 12:26—33","Ayati 14; Amos 7:9","Faigi 10:30"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 12, 'Tobali itörö li Yehowa, niŵa''önia khö Yehu, me imane: Irege tölu nga''ötö ma''uwumö dania zidadao ba dadaoma razo ba Ndraono Gizeraeli: Itörö niŵa''ö andrö.[9]', '["Faigi 14:29","RazI 12:26—33","Ayati 14; Amos 7:9","Faigi 10:30"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 13, 'Ba Salumi andrö, ono Yabesi, ba me no alua 38 fakhe razo mado Yuda Usia tobali razo ia, ba ha sara waŵa razo ia ba Zamaria.', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 14, 'Ba so moroi si tou, ba Dirisa Menahe andrö, ono Gadi, ba me no irugi Zamaria, ba ibunu Zalumi, ono Yabesi, ba Zamaria, ba tobali razo ia fangali nibununia.[10]', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 15, 'Ba hadia na ena''ö nidunö-dunö ba khö Zalumi andrö, ba folaŵania andrö, famagölönia ba niha bö''ö, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 16, 'Ba me luo da''ö, ba ifufu Dafua Menahe, fabaya ösi fefu ba tanöra fefu, i''otarai Dirisa, me lö nibokaira bawa göli khönia, ba dozi sanabina ba mbanua bakha, ba ifasikoi''ö dalu.', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 17, 'Me no alua 38 fakhe razo mado Yuda Gasaria andrö, tobali razo Ndraono Gizeraeli Menahe, ono Gadi, ba mewulu fakhe razo ia, ba Zamaria.', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 18, 'Ba si fatuwu khö Yehowa ilau; lö iböhöli horö Yerobeamo, ono Nebati, fefu, famaelungunia Iraono Gizeraeli.[11]', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 19, 'Ba me luo da''ö, ba isuwö ira Fulo andrö, razo Ndrawa Asiria. Ba 220.550 balaki ibe''e khö Wulo Menahe, ena''ö fa''awö ia khönia, ba ena''ö i''aro''ö wa''arazonia,', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 20, 'ba ihuku bobotolö Ndraono Gizeraeli gana''a andrö Menahe; dozi solohe baluse zame''e, ba wame''e khö razo Ndrawa Asiria, lima wulu ba rufia zamösa. Ba mangawuli razo Ndrawa Asiria, lö''ö sa''ae i''iagö danöra.[12]', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 21, 'Ba hadia na ena''ö nidunö-dunö ba khö Menahe, ba hadia ia fefu nilaunia, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 22, 'Ba mate Menahe, itörö lala ndra amania, ba fangalinia razo, ba ononia Fekaya.', '["RazI 16:17","Ayati 9","Faigi 23:25"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475068, 'OT', 'Razo II', 15, 23, 'Me no alua 49 fakhe razo mado Yuda Gasaria, tobali razo Ndraono Gizeraeli ba Zamaria Wekaya andrö, ono Menahe, ba ha Mendrua fakhe.', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 24, 'Ba si fatuwu khö Yehowa ilau; lö iböhöli horö Yerobeamo, ono Nebati, famaelungunia Iraono Gizeraeli.[13]', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 25, 'Ba molaŵa Weka, ono Remalia, awö razo, mamagölö ia ba niha bö''ö, ba wamunu razo, ba ibunu, ba Zamaria, ba gödo razo, awö ndra Aregobi Arie; ba lima wulu nawö Weka, banua Gileadi. Ba ibunu Wekaya, ba tobali razo ia, fangali nibununia.[14]', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 26, 'Ba hadia na ena''ö nidunö-dunö ba khö Wekaya andrö ba hadia ia fefu, nilaunia, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 27, 'Me no alua 51 fakhe salaŵa mado Yuda Gasaria, tobali salaŵa Ndraono Gizeraeli ba Zamaria Weka andrö, ono Remalia, ba dua wulu fakhe salaŵa ia.', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 28, 'Ba si fatuwu khö Yehowa ilau; Lö iböhöli horö Yerobeamo, ono Nebati, famaelungunia Iraono Gizeraeli.', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 29, 'Ba me luo razo Ndraono Gizeraeli Weka andrö, ba so Digelata-Filezeri, razo Ndrawa Asiria, ba atu''a ia ba Iyono ba ba Habeli Beti Ma''akha ba ba Yanoa ba ba Gedesi ba ba Hasora; ba tanö Gileadi ba tanö Galilaia ba tanö mado Nafetali ma''asagörö, ba i''okhögö, ba ösi mbanua, ba i''ohe ba danö Asiria.[15]', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 30, 'Ba molaŵa Hosea, ono Ela, mamagölö ia ba niha bö''ö, ba khö Weka, ono Remalia, ba ibunu Weka, ba tobali razo ia, fangali nibununia, me no alua 19 fakhe razo Yotamo, ono Usia.[16]', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 31, 'Ba hadia na ena''ö nidunö-dunö ba khö Weka andrö, ba hadia ia fefu nilaunia, ba noa sa mutanö ba zura hikaya razo Ndraono Gizeraeli.', '["Ayati 9","Ayati 10,14,30","Nga''ötI 5:26","Faigi 17:1; Ayati 25"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 32, 'Me no alua döfi razo Weka, ono Remalia, tobali razo mado Yuda Yotamo, ono Usia.[17][18]', '["Ayati 32—36,38: Nga''ötII 27","Ayati 5,7","Faigi 15:3,4","Faigi 16:5"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 33, 'Dua wulu a lima fakhe ia, me tobali razo ia, ba 16 fakhe razo ia, ba Yeruzalema. Ba töi ninania, ba Yerusa, ono Zadoki.', '["Ayati 32—36,38: Nga''ötII 27","Ayati 5,7","Faigi 15:3,4","Faigi 16:5"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 34, 'Ba somasi Yehowa ilau, nifolau namania Usia mege, fefu hadia ia.', '["Ayati 32—36,38: Nga''ötII 27","Ayati 5,7","Faigi 15:3,4","Faigi 16:5"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 35, 'Ha hili-hili andrö zi lö labulö''ö, lö tebulö wame''e zato sumange ba hili-hili andrö, awö wanunu kumöyö. Yotamo zolau baŵa göli tanö yaŵa, ba gosali Yehowa.[19]', '["Ayati 32—36,38: Nga''ötII 27","Ayati 5,7","Faigi 15:3,4","Faigi 16:5"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 36, 'Ba hadia na ena''ö nidunö-dunö ba khö Yotamo andrö ba hadia ia fefu nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["Ayati 32—36,38: Nga''ötII 27","Ayati 5,7","Faigi 15:3,4","Faigi 16:5"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 37, 'Ba me luo da''ö, ba ibörötaigö Yehowa wamarou Resino, razo Ndrawa Garamo ba Feka, ono Remalia, ba wanuwö mado Yuda.[20]', '["Ayati 32—36,38: Nga''ötII 27","Ayati 5,7","Faigi 15:3,4","Faigi 16:5"]', NULL),
  (3475068, 'OT', 'Razo II', 15, 38, 'Ba mate Yotamo, itörö lala ndra amania, ba ba mbanua Dawido lako''o ia, ba ngai ndra amania. Ba fangalina razo, ba ononia Ahasi.', '["Ayati 32—36,38: Nga''ötII 27","Ayati 5,7","Faigi 15:3,4","Faigi 16:5"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 1, 'Me no alua meweleönö fakhe razo Weka, ono Remalia, tobali razo mado Yuda Gahasi andrö, ono Yotamo.[1][2]', '["Faigi göi Nga''ötII 28","Faigi 15:38","Faigi 21:6; MozIII 18:21"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 2, 'Dua wulu fakhe Gahasi, me tobali razo ia, ba meweleönö fakhe wa''ara razo ia ba Yeruzalema. Ba tenga somasi Lowalanginia Yehowa ilau, tenga si mane tuania Dawido;', '["Faigi göi Nga''ötII 28","Faigi 15:38","Faigi 21:6; MozIII 18:21"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 3, 'lala razo Ndraono Gizeraeli andrö itörö. Ifatörö ba galitö nononia wangohia''ö sogoro ita andrö ba niha baero andrö, nitimba Yehowa föna Ndraono Gizeraeli.[3]', '["Faigi göi Nga''ötII 28","Faigi 15:38","Faigi 21:6; MozIII 18:21"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 4, 'Ba mame''e sumange ia ba manunu kumöyö ba hili-hili andrö, idozigö hili-hili ba börö geu sauri.', '["Faigi göi Nga''ötII 28","Faigi 15:38","Faigi 21:6; MozIII 18:21"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 5, 'Ba me luo da''ö, ba so moroi yöu Resino, razo Ndrawa Garamo, awö Weka, ono Remalia, razo Ndraono Gizeraeli, ba wanuwö Yeruzalema. Lala''u''u Gahasi, ba tebai sa atö atu''a ira.[4]', '["Yes 7:1—9","Faigi 14:22","Faigi 15:29","RazI 15:18"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 6, 'Ba me luo da''ö, ba itolo Ndraono Gedomo Resino, razo Ndrawa Garamo, ba wamadöni mangawuli Elata, itimba mado Yuda, si so ba da''ö. Ba möi ba Gelata Ndraono Gedomo, la''iagö da''ö, irugi ma''ökhö andre.[5]', '["Yes 7:1—9","Faigi 14:22","Faigi 15:29","RazI 15:18"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 7, 'Ba ifatenge zinenge Ahasi khö Digelata-Filezeri, razo Asiria, imane khönia: Sawuyumö ndra''o, ba onou göi! Ae khögu, ba efa''ö ndra''o ba danga razo Ndrawa Garamo ba ba danga Ndraono Gizeraeli, sanuwö ya''odo![6]', '["Yes 7:1—9","Faigi 14:22","Faigi 15:29","RazI 15:18"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 8, 'Ba ihalö göi wirö andrö ba ana''a ba gosali Yehowa ba ba mbate''e girö-girö, ba gödo razo, ba ifa''ohe''ö buala khö razo Asiria.[7]', '["Yes 7:1—9","Faigi 14:22","Faigi 15:29","RazI 15:18"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 9, 'Ba ifondrondrongo khönia razo Asiria, möi ia ba Ndramaseko, ba atu''a ia ba mbanua, ba ira''u nono mbanua, i''ohe ba Kiri; ba Resino, ba ifabunu''ö.', '["Yes 7:1—9","Faigi 14:22","Faigi 15:29","RazI 15:18"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 10, 'Ba möi ba Ndramaseko razo, Ahasi, möi falukha khö Digelata-Filezeri, razo Asiria, ba i''ila naha wame''e sumange andrö, ba Ndramaseko. Ba ifa''ohe''ö gambara naha wame''e sumange andrö ba tuladania, si faudu sibai, khö Guria ere.', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 11, 'Ba ifa''anö naha wame''e sumange andrö ere andrö, i''ohia''ö sibai dulada, nifa''ohe''ö razo, Ahasi, moroi ba Ndramaseko; dali da''ö khö Guria ere, me lö sangawuli na razo, Ahasi, moroi ba Ndramaseko.', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 12, 'Ba me mangawuli razo, me i''ila naha wame''e sumange andrö, ba möi ia yaŵa,', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 13, 'ba itunu zumange nitunu andrö khönia, awö zumange ni''a, ifaduwa zumange nibadu, ba itefe naha wame''e sumange do zumange fangorifi khönia.', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 14, 'Ba naha wame''e sumange töla andrö, si so ba da''ö föna Yehowa, ba iheta föna gosali, ba gotaluara naha wame''e sumange si bohou andrö gosali Yehowa ibe''e, yöu naha wame''e sumange andrö [khönia].', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 15, 'Ba ibe''e li razo, Ahasi, khö Guria ere, imane: Ba naha wame''e sumange, naha sebua andrö, ötunu zumange nitunu na mahemolu mbanua, awö zumange ni''a na owi ba sumange nitunu nibe''e razo, awö zumange ni''a andrö khönia, ba sumange nitunu nibe''e zato, fabaya sumange ni''a ba sumange nibadu khöra; ba tefe ia do zumange nitunu ba do zumange nitaba, fefu. Ba ba naha wame''e sumange töla andrö, ba da''u''era-era tödögu.', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 16, 'Ba i''o''ö sibai Uria ere niŵa''ö razo khönia.', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 17, 'Ba ifabo''a''ö göi lesi andrö ba dayadaya [mbalanga] no, ba ifaheta''ö yaŵa mbalanga; ba gala sebua andrö, ba ifaheta''ö ba dayadayania saŵi töla andrö, ba mbale labe''e.[8]', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 18, 'Ba he lala ba zabato andrö, nisagöi, nifazökhira ba gosali, lala razo moroi baero, ba iwu''ai ba gosali Yehowa, börö razo Asiria.', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 19, 'Ba hadia na ena''ö nidunö-dunö ba khö Gahasi andrö, hadia nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475069, 'OT', 'Razo II', 16, 20, 'Ba mate Gahasi, itörö lala ndra amania, ba ba ngai ndra amania lako''o ia. Ba fangalinia razo, ba ononia Hisikia.[9]', '["RazI 7:23—39","Faigi 18:1"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 1, 'Me no alua mewelezara fakhe razo mado Yuda Gahasi andrö, tobali razo Ndraono Gizeraeli ba Zamaria Hosea, ono Ela, meziŵa fakhe.[1]', '["Faigi 15:30","Faigi 18:9—12","Hos 12:2"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 2, 'Ba si fatuwu khö Yehowa ilau; ba tenga sa atö si mane razo Ndraono Gizeraeli andrö, fönania mege.', '["Faigi 15:30","Faigi 18:9—12","Hos 12:2"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 3, 'Ba so moroi si yaŵa Zalamanasa, razo Asiria, manuwö ya''ia, ba möi barö mbawa Zalamanasa Hosea, mame''e-me''e beo ia khönia.[2]', '["Faigi 15:30","Faigi 18:9—12","Hos 12:2"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 4, 'Ba me irongo razo Asiria falimo Hosea — noa sa ifatenge zinenge khö Zewe, razo Miserayi, ba lö nibe''enia khö razo Asiria beo andrö, si döfidöfi mege — ba itema ifara''u''ö ia razo Asiria, ifaböbö''ö ba ifakuru''ö.[3]', '["Faigi 15:30","Faigi 18:9—12","Hos 12:2"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 5, 'Ba so moroi si yaŵa razo Asiria, isuwö ira, ba danö ma''asagörö, ba isaŵa göi Zamaria, ifa''u''u ira, bakha ba mbanua, medölu fakhe wa''ara.', '["Faigi 15:30","Faigi 18:9—12","Hos 12:2"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 6, 'Ba me no alua meŵalu fakhe razo Hosea, ba atu''a ba Zamaria razo Asiria, ba i''oloi''ö ba danö Asiria Ndraono Gizeraeli, ba Hala ba ba Habora ifataro ira, ba mbewe Gozana ba ba mbanua Ndrawa Media andrö.', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 7, 'Noa sa molalö Ndraono Gizeraeli khö Lowalangira, Yehowa, si no mangefa''ö ya''ira ba danga Wara''o andrö, razo Ndrawa Miserayi, ba si no mangeheta ya''ira ba danö Miserayi; lafosumange Lowalangi bö''ö,', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 8, 'ba latörö lala niha baero andrö, nitimba Yehowa föna ndra tuara mege, ba he lala razo mege, nikhoi dödö da''ö.[4]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 9, 'Ba si lö atulö lalau Iraono Gizeraeli, khö Lowalangira, Yehowa, nibini''ö: lafazökhi khöra naha wame''e sumange ba hili-hili, ladozigö banua khöra, i''otarai zi ha malige, naha zanaro, numalö ba mbanua saro,', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 10, 'lataru''ö harefa ba Asera, ladozigö hili-hili salaŵa ba börö geu sauri,[5]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 11, 'ba manunu kumöyö ira ba hili-hili andrö fefu, si mane niha baero andrö, niheta Yehowa fönara. Si lö sökhi lalau, wangandrö fönu Yehowa,[6]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 12, 'ba lafosumange nadu andrö, niŵa''ö Yehowa khöra: Böi milau zi manö![7]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 13, 'Ba ifategu''ö Ndraono Gizeraeli, awö mado Yuda, Yehowa, ba zama''ele''ö andrö khönia, fefu ba ba zangi''ila andrö, fefu, imane: Miröi lala si lö sökhi andrö khömi, ba mi''o''ö goroisagu, awö nifakhoigu andrö, dali manö goroisa andrö, nibe''egu khö ndra tuami, ba dali na niŵa''ögu, nifa''ema genonigu andrö, sama''ele''ö.', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 14, 'Ba lö la''o''ö, wa''abe''e dandro, si mane ira tuara mege, si lö faduhu tödö khö Lowalangira Yehowa;', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 15, 'lö''ö manö ba dödöra nifakhoinia andrö, ba he fawu''usa li andrö khönia, me fawu''u li ia khö ndra tuara, ba he fanegunia ya''ira, la''o''ö waya-faya andrö ba lalau zi lö boto, la''ohia''ö nilau niha baero andrö, si tefasui ya''ira, he ŵa''ae no iŵa''ö khöra Yehowa, böi lafolau niha da''ö.[8]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 16, 'La''erogö goroisa Lowalangira Yehowa fefu, lafahele khöra nadu, ono zaŵi, dua rozi, ba lafazökhi Gasera, ba mangalulu ira ba ngahönö ba mbanua si yaŵa, ba lafosumange Mba''ali.[9]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 17, 'Lafatörö ba galitö nonora matua, awö nonora alawe; faetasa ba fakelemusa so ba khöra, lalulu ira, ba wolau si fatuwu khö Yehowa, wangandrö fönunia,[10]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 18, 'Ba mofönu sibai Yehowa ba Ndraono Gizeraeli, ba iheta ira ba duduma hörönia, tobali lö si tosai, ha mado Yuda andrö.', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 19, 'Ba mado Yuda andrö göi, ba lö la''o''ö goroisa Lowalangira, Yehowa, latörö nifakhoi Ndraono Gizeraeli andrö, nikhoi dödö da''ö.', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 20, 'Andrö wa itibo''ö nga''ötö Gizeraeli fefu Yehowa, ihöndrögö ira, ibe''e ba danga zi faraburabu ba khöra, irege ifalua itibo''ö ira, iheta ba duduma hörönia.', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 21, 'Me no ifabali Ndraono Gizeraeli ba nga''ötö Dawido, ba me no lafataro razo Yerobeamo andrö, ono Nebati, ba i''ohe ba wangerogö Yehowa Ndraono Gizeraeli Yerobeamo, ifaelungu ira ba horö sebua.[11]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 22, 'Ba tobali latörö lala horö andrö fefu, nifobörö Yerobeamo, Iraono Gizeraeli; lö''ö sa''ae laböhöli,', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 23, 'irege iheta ba duduma hörönia Ndraono Gizeraeli Yehowa, itörö niŵa''önia, wameta''u ya''ira, nifa''ema genoninia andrö, sama''ele''ö fefu. Ba aheta ba danöra Ndraono Gizeraeli, ni''oloi''ö, ba danö Asiria, irugi ma''ökhö andre.[12]', '["Faigi 16:3","Faigi 16:4; RazI 14:23","Ayati 8","MozII 20:2; 23:13","MozII 23:24","RazI 12:28; 16:23","RazI 12:20","MozV 28:63,64"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 24, 'Ba i''oroi''ö niha razo Asiria, ba Mbabeli ba ba Guta ba ba Gawa ba ba Hamata ba ba Zefarawa''i, ba ifataro fangali Ndraono Gizeraeli, ba mbanua Zamaria misa. Ba tobali la''okhögö danö Zamaria ba la''iagö mbanua ba da''ö.', '[]', NULL),
  (3475070, 'OT', 'Razo II', 17, 25, 'Ba me lö lafosumange Yehowa, me awena so ira, ba i''asogö khöra zingo Yehowa, samunu ya''ira.', '[]', NULL),
  (3475070, 'OT', 'Razo II', 17, 26, 'Ba la''ombakha''ö khö razo Asiria, lamane: Niha andrö, nifawu''amö, nifataromö ba mbanua. Zamaria misa, ba lö la''ila he wisa wamosumange Lowalangi ba danö andrö; andrö wa i''asogö khöra zingo, samunu ya''ira, me lö la''ila, hadia zi nangea ba Lowalangi ba danö andrö.', '[]', NULL),
  (3475070, 'OT', 'Razo II', 17, 27, 'Ba ibe''e li razo Asiria, imane: Mifatenge gere andrö samösa, ni''oloi''ögu moroi ba da''ö, hana na möi ia ba na i''iagö da''ö, ba wamahaö ya''ira, hadia zi nangea famosumange Lowalangi ba danö andrö.', '[]', NULL),
  (3475070, 'OT', 'Razo II', 17, 28, 'Ba so gere samösa, banua Zamaria, ni''oloi''ö mege, ba i''iagö Mbetieli, ifahaö sa''ae ira, he wisa wamosumange Yehowa.', '[]', NULL),
  (3475070, 'OT', 'Razo II', 17, 29, 'Ba sambu-sambua soi, ba sambu-sambua Lowalangi lafazö khi khöra, ba labe''e ba gosali andrö, ba hili-hili, nilau mbanua Zamaria andrö mege, dozi soi ba mbanuara andrö, ba zi so ira.', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 30, 'Banua Mbabeli, ba Sukota Benoti lafazökhi, ba banua Guta, ba Neregala, ba banua Hamata, ba Azina,', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 31, 'ba banua Gawa, ba Nibikha ba Tarataka; ba banua Zefarawa''i, ba latunu ndraonora, sumange Gaderamelekhi ba sumange Ganamelekhi, Lowalangi Zefarawa''i.[13]', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 32, 'Ba baero ö, ba lafosumange göi Yehowa, ba lafataro ere ba hili-hili andrö nawöra, gofu ha niha manö; da''ö zame''e sumange andrö khöra, ba gosali andrö, ba hili-hili.', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 33, 'Lafosumange Yehowa, ba Lowalangira andrö, ba lafosumange göi, dali huku ba niha andrö, ba nihalö ya''ira, wamawu''a ya''ira mege.', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 34, 'Ba irege ma''ökhö andre, ba lö aefa khöra huku föna andrö, Lö la''ata''ufi Yehowa, ba lö''ö göi latörö gamakhoita andrö khöra, ba ömöra andrö; ba lö la''o''ö goroisa Yehowa, ba he nifakhoinia, niŵa''önia ba nga''ötö Yakobo andrö, nifotöinia Izeraeli.', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 35, 'Ba no fawu''u li khöra Yehowa, no ibe''e li khöra, no imane: Böi mifosumange Lowalangi bö''ö! böi mi''angaröfi li ira, böi mi''ae enonira ba böi mibe''e zumange khöra.[14]', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 36, 'Yehowa mi''ata''ufi, Yehowa si no mangeheta ya''ami ba danö Miserayi fa''abölönia andrö, si tenga side-ide ba tangania andrö, si no mu''oro''ö, da''ö mi''angaröfi li, ba khönia mibe''e zumange!', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 37, 'Ba lala andrö, awö huku, ba oroisa ba amakhoita andrö, nifakhoinia khömi, ba mitöngöni, ena''ö lö mamalö-malö wolo''ömi, ba böi mifosumange Lowalangi bö''ö.', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 38, 'Ba böi olifu ami wawu''usa li andrö, me fawu''u li ndra''o khömi, ba böi mifusumange Lowalangi bö''ö!', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 39, 'Yehowa, Lowalangimi, mifosumange, ba i''efa''ö dania ami, ba danga nemalimi, fefu.[15]', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 40, 'Ba lö lafondrondrongo, lö laböhöli huku föna khöra.', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475070, 'OT', 'Razo II', 17, 41, 'Ba tobali lafosumange Yehowa soi niha andrö, ba labe''e-be''e göi gö nadu. Ba onora andrö ba ma''uwura, ba la''o''ö nilau ndra namara mege, irugi ma''ökhö andre.', '["Ayati 17","MozII 23:24","MozV 6:12—19"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 1, 'Me no alua mendrua fakhe razo Hosea andrö, ono Ela, razo Ndraono Gizeraeli, tobali razo mado Yuda Hisikia, ono Gahasi.[1]', '["Faigi 16:20","Nga''ötII 29:1,2","Faigi 20:3","Nga''ötII 31:1; Faigi 15:35; MozIV 21:8,9","Faigi 23:25"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 2, 'Dua wulu a lima fakhe ia, me tobali razo ia, ba 29 fakhe dania razo ia ba Yeruzalema. Ba töi ninania, ba Abiya, ono Zakharia.[2]', '["Faigi 16:20","Nga''ötII 29:1,2","Faigi 20:3","Nga''ötII 31:1; Faigi 15:35; MozIV 21:8,9","Faigi 23:25"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 3, 'Ba somasi Yehowa, ilau i''o''ö sibai wolau duania Dawido.[3]', '["Faigi 16:20","Nga''ötII 29:1,2","Faigi 20:3","Nga''ötII 31:1; Faigi 15:35; MozIV 21:8,9","Faigi 23:25"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 4, 'Ya''ia zangeheta naha wame''e sumange ba hili-hili andrö, irasa harefa andrö, i''obö Gasera ba ifufu wamaedo gulö töla andrö, nifazökhi Moze; irege da''ö sa, ba latunutunu khönia gumöyö Iraono Gizeraeli; Nehusa döinia khöra.[4]', '["Faigi 16:20","Nga''ötII 29:1,2","Faigi 20:3","Nga''ötII 31:1; Faigi 15:35; MozIV 21:8,9","Faigi 23:25"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 5, 'Khö Lowalangi Ndraono Gizeraeli idöna-döna wangorifi Hisikia, tobali lö si falaŵalaŵa khönia, furinia, ba razo mado Yuda andrö fefu, ba he fönania mege.[5]', '["Faigi 16:20","Nga''ötII 29:1,2","Faigi 20:3","Nga''ötII 31:1; Faigi 15:35; MozIV 21:8,9","Faigi 23:25"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 6, 'Yehowa i''olembai, lö iböhöli wolo''ö khönia, i''o''ö goroisa Yehowa, niŵa''önia khö Moze mege.', '["Faigi 16:20","Nga''ötII 29:1,2","Faigi 20:3","Nga''ötII 31:1; Faigi 15:35; MozIV 21:8,9","Faigi 23:25"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 7, 'Ba lö mamalö-malö wanolo Yehowa ya''ia; fefu hadia ia nilaunia, ba mofozu. Ba ifabali ia khö razo Asiria, iheta ia barö mbawania.', '["Faigi 16:20","Nga''ötII 29:1,2","Faigi 20:3","Nga''ötII 31:1; Faigi 15:35; MozIV 21:8,9","Faigi 23:25"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 8, 'Itimba Ndrawa Wilisiti, irugi Gasa, ba ifufu danöra, i''otarai malige zanaro andrö, irugi ba mbanua saro.', '["Faigi 16:20","Nga''ötII 29:1,2","Faigi 20:3","Nga''ötII 31:1; Faigi 15:35; MozIV 21:8,9","Faigi 23:25"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 9, 'Ba me no alua medölu fakhe razo Hisikia — no alua meönö fakhe Hosea andrö, ono Ela, razo Ndraono Gizeraeli — ba so moroi si tou Zalamanasa, razo Asiria, ba wanuwö Samaria, ba ifa''u''u mbanua.[6]', '["Faigi 17:3—6"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 10, 'Ba medölu fakhe, ba atu''a ia ba mbanua; me no alua melima fakhe Hisikia — ya''ia me no alua meŵalu fakhe Hosea, razo Ndraono Gizeraeli — atu''a ira ba Zamaria.', '["Faigi 17:3—6"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 11, 'Ba i''oloi''ö ba danö Asiria Ndraono Gizeraeli razo Asiria, ba ba Hala ba ba mbewe Habora, idanö ba Gozana, ifataro ira, ba ba mbanua Ndrawa Media andrö,', '["Faigi 17:3—6"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 12, 'me no lö ni''o''öra oroisa Lowalangira Yehowa, me no lasawö wawu''usa li andrö khönia — hadia ia fefu ni''oroi''ö genoni Yehowa andrö, Moze. Ya''ira, ba lö nifondrondrongora ba lö ni''o''öra.', '["Faigi 17:3—6"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 13, 'Ba me no alua meweledölu fakhe razo Hisikia,[7] ba so moroi si yaŵa Zaneribi, ba wanuwö banua saro ba mado Yuda, fefu, ba atu''a ia.', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 14, 'Ba ifatenge zinenge Hisikia khö razo Asiria, ba Lakhisi, imane khönia: No molalö ndra''o; fuli''ö, böhölido; hadia, nibe''eu ömögu, ba utörö. Ba ifo''ömö Hisikia, razo mado Yuda, razo Asiria, 66.000 balaki wirö ba 119.115 balaki gana''a.[8]', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 15, 'Ba ahori ibe''e Hisikia gana''a andrö, si so ba gosali Yehowa, awö zi so ba mbate''e girö-girö ba gödo razo.[9]', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 16, 'Ba me luo da''ö, ba ibo''a Hisikia, razo mado Yuda, gana''a ba lagö mbawandruhö gosali ba ba daru nahe nifo''ulinia ana''a, ba ibe''e khö razo Asiria.', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 17, 'Ba ifatenge Daratano ba Rabisari ba Rabisake razo Asiria, khö razo Hisikia ba Yeruzalema la''otarai Lakhisi, ato sibai la''ohe sabölö. So ira moroi si tou ba larugi Yeruzalema, ba la''iagö ba ngai hele, si oroi mbaŵa tanö yaŵa andrö, ba zinga lala ba naha wolokhoi nukha.', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 18, 'Ba lasofu razo. Ba möi baero khöra Geliaki, ono Hilikia, mandru ba gödo, ba Sebena, durutuli, ba Yoa, ono Gasafi, za''asa sebua.', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 19, 'Ba imane khöra Rabisake: Mimane khö razo, Hisikia: Da''ö niŵa''ö razo sebua andrö, razo Asiria: He moroi khöu wa''abe''e dödö andrö?', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 20, 'Hadia, öwai ha li zoguna, ba wamaigi lala dödö ba fa''abölö ba wanuwö? Ha niha atö dötönaföu, wa no fabali ndra''ugö khögu?', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 21, 'Hiza, Dawa Miserayi we''e-we''e dödöu, si''o sukhu andrö, si no tefatö; dozi ha niha zi ani''o ya''ia, ba mesokho danga, atöla tambai. Si manö Wara''o andrö, razo Miserayi, ba zame''e tötönaföra ya''ia, dozi.', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 22, 'Ba na mimane wanema ligu: Khö Lowalangima, Yehowa, manötöna ndra''aga! ba no ya''ia niheta Hisikia naha wame''e sumange ba hili-hili andrö, wanguma''ö ba mado Yuda ba ba mbanua Yeruzalema: Föna naha wame''e sumange andre, ba Yeruzalema, mangalulu ami![10]', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 23, 'Ba lau, ba milau fataru sokhö ya''o, razo Asiria: dua ngahönö ube''e khöu kudo, ba datafaigi, na ö''ila ö''asogö zi fakudo ba hulura.', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475071, 'OT', 'Razo II', 18, 24, 'He ha samösa kumandra fondrege side-ide, enoni zokhö ya''o, zolau khöu, ba he öwisa wanimba? Ba ödöna-döna ba Ndrawa Miserayi gureta, awö kudo?', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 25, 'Ba hadia, lö nitehe Yehowa wa''asogu moroi si yaŵa, ba wanudugö banua da''e? No Yehowa zanguma''ö khögu: Ae ba danöra andrö, ba fufu ia!', '["Ayati 13—37: Nga''ötII 32:1—19; Yes 36","Ayati 7","Faigi 16:8","MozII 20:24; MozV 12:14"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 26, 'Ba lamane khö Rabisake ira Eliaki, ono Hilikia, Sebena Yoa: Li Ndrawa Garamo lau ba genonimö, ma''ila sa; böi lau khöma li Heberaio, me lafondrondrongo sato, si so ba göli.', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 27, 'Ba imane khöra Rabisake: Hadia, khö zokhö ya''ugö, ba ma khöu ifatenge ndra''o sokhö ya''o, ba wamarongogö da''ö, ba tenga ba zato, si so ba göli, ena''ö faoma mi''a daimi ba mibadu giömi?', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 28, 'Ba iagö da''ö Rabisake, ba mu''ao, ebua linia, li Heberaio ilau, humede ia, imane: Mifondrondrongo li razo andrö, li razo Asiria!', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 29, 'Imane razo sebua andrö: Böi mibe''e nifowöhö Hisikia ami, tebai sa i''efa''ö ami ba dangagu.', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 30, 'Ba böi mifondrondrongo khö Hisikia, na ituturu we''e-we''e dödömi Yehowa, na imane: Lö zi lö i''orifi ita Yehowa, ba lö tebe''e ba danga razo Asiria mbanua da''e.', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 31, 'Böi mifondrondrongo khö Hisikia! Imane sa razo Asiria: Data''atulö''ö ita, milulu ami khögu, ba i''a mbua nagu khönia zamösana ba bua marafala, ba ibadu nidanö ba mba''a khönia,[11]', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 32, 'irege sodo, ba wangai ya''ami, ba wolohe ba danö si fagölö-gölö ba danömi, tanö si fahöna böra ba ösi mbua nagu, balazo, ba kabu nagu ba töla mbua zai ba ŵe ŵani, ena''ö auri ami, böi mate. Andrö böi mifondrondrongo khö Hisikia! Me ifowöhö ami, na imane: Yehowa zangorifi ya''ita!', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 33, 'He wisa ba Lowalangi niha baero andrö; hadia, no i''efa''ö ba danga razo Asiria danönia zamösana?[12]', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 34, 'Heza so Lowalangi mbanua Hamata, ba he Lowalangi mbanua Garafada? Ba heza so Lowalangi ba Zefarawa''i ba ba Hena ba ba Giwa? Ba heza so Lowalangi ba danö Zamaria, ba wangefa''ö ba dangagu Samaria mena''ö?', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 35, 'Heza so ba Lowalangi ba danö misa, fefu, zi no mangefa''ö ba dangagu tanöra, wa i''efa''ö ena''ö ba dangagu Yeruzalema Yehowa?', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 36, 'Ba lö''ö sa''ae hede-hedera, lö latema linia; me no da''ö goroisa razo: Böi mitema linia!', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475071, 'OT', 'Razo II', 18, 37, 'Ba so Geliaki, ono Hilikia, mandru ba gödo ba Sebena, durutuli, ba Yoa, ono Gasafi, sa''asa sebua, möi ira khö Hisikia, no lasika nukhara, ba latunö khönia niŵa''ö Rabisake andrö.', '["RazI 5:5","Yes 10:10,11"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 1, 'Ba me irongo da''ö no mege Hisikia, ba isika nukhania ba i''obaru mbaru bu, ba möi ia ba gosali Yehowa.[1]', '["Faigi göi Nga''ötII 32:20—23:Yes 37","Faigi 18:35","Ayati 9:35—37"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 2, 'Ba Eliaki, ono Hilikia, mandru ba gödo, ba Sebena, durutuli ba satua gere, ba ifatenge khö Yesaya, ono Gamosi, baru bu göi mbarura.', '["Faigi göi Nga''ötII 32:20—23:Yes 37","Faigi 18:35","Ayati 9:35—37"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 3, 'Ba lamane khö Yesaya: Da''ö niŵa''ö Hisikia: Baŵa wa''atosasa ma''ökhö, baŵa wotu, ba baŵa wanibo; hatö sa fa''aböla nono, ba no ambö fa''abölö, ba wadono.', '["Faigi göi Nga''ötII 32:20—23:Yes 37","Faigi 18:35","Ayati 9:35—37"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 4, 'Ma atö irongo Lowalangimö, Yehowa, wehede Rabisake andrö fefu, fehede Rabisake nifatenge zokhö ya''ia, razo Asiria, ba wango''aya Lowalangi sauri. Ba yamu''otu''ö sa''ae ira Lowalangimö, Yehowa, ba wehede andrö, nirongonia. Ba ya''ugö, ba angandrö, salahi zi tosai andrö, si lö ahori na.[2]', '["Faigi göi Nga''ötII 32:20—23:Yes 37","Faigi 18:35","Ayati 9:35—37"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 5, 'Ba me larugi Yesaya sinenge razo Hisikia,', '["Faigi göi Nga''ötII 32:20—23:Yes 37","Faigi 18:35","Ayati 9:35—37"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 6, 'ba imane khöra Yesaya: Mimane khö zokhö ya''ami: Da''ö niŵa''ö Yehowa: Böi ata''ufi wehede andrö, nirongou, fango''aya genoni razo Asiria ya''odo.', '["Faigi göi Nga''ötII 32:20—23:Yes 37","Faigi 18:35","Ayati 9:35—37"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 7, 'Hiza, ube''e khönia geheha, ena''ö irongo dania duria, ba ena''ö ifuli ia ba danönia, ba ba danönia dania ube''e nibunu si''öli ia.[3]', '["Faigi göi Nga''ötII 32:20—23:Yes 37","Faigi 18:35","Ayati 9:35—37"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 8, 'Ba ifuli ia Rabisake, ba no sanuwö Libena razo Asiria, fönanania; noa sa irongo, wa no iheta ia ba Lakhisi.', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 9, 'Ba me irongo Saneribi duria Dirihaka, razo Gaitiofia, me lamane khönia: "So ia moroi sa, möi fasuwö khöu," ba ifuli ifatenge zinenge khö Hisikia, imane:', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 10, 'Mimane khö Hisikia, razo mado Yuda: Böi be''e nifowöhö ndra''ugö, nifowöhö Lowalangimö andrö, nidöna-dönamö fangorifi, wanguma''ö tödöu: Lö''ö sa tebe''e ba danga razo Asiria Yeruzalema![4]', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 11, 'Hiza, no örongo, he lawisa razo Asiria ba danö zotanö misa fefu, me no lafakiko, ba hadia, ba saefa ndra''ugö?', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 12, 'He wisa Lowalangi soi niha andrö, nihori ndra amagu tuagu, hadia, no la''orifi? — Gozana andrö ba Harana ba Resefi ba he mado Gedena andrö, ba Delasara.[5]', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 13, 'Heza so razo Hamata ba razo Garafada; ba heza so razo mbanua Zefarawa''i, ba razo Hena ba razo Giwa?', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 14, 'Ba me no itema Hisikia zura andrö, ba danga zinenge, ba me no ibaso, ba möi ia miyaŵa ba gosali Yehowa ba ibologö zura andrö föna Yehowa.', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 15, 'Ba mangandrö Hisikia föna Yehowa, imane: "He Yehowa, Lowalangi Ndraono Gizeraeli, sidadao yaŵa Kerubi; ha ya''ugö Lowalangi ba gamatöröŵa niha ba guli danö, fefu; ya''ugö zamazökhi banua si yaŵa, awö danö.[6]', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 16, 'Be''e mbörö dalingau, ya''ugö Yehowa, ba fondrondrongo; fehaga''ö, ya''ugö Yehowa, ba faigi! Fondrondrongo niŵa''ö Zaneribi andrö, nifa''ema zinengenia, ba wanandraŵaisi Lowalangi sauri.[7]', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 17, 'Si ndruhu, ya''ugö Yehowa, noa sa lafufu niha baero, fabaya tanöra, razo Asiria andrö,', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 18, 'ba no latunu Lowalangira [adu]. Me no tenga si ndruhu Lowalangi da''ö, ha nifazökhi danga niha, eu ba kara, ba andrö la''ila lafufu.', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 19, 'Ba iya''e, ya''ugö Yehowa, Lowalangima, efa''ö ndra''aga ba dangania, ena''ö dozi banua niha ba guli danö aboto ba dödö, wa no ha ya''ugö Lowalangi, ya''ugö Yehowa!"', '["Faigi 18:30","Faigi 18:33,34","MozII 25:22; Sin 80,2","Ayati 4; SamI 17:10"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 20, 'Ba ifatenge khö Hisikia Yesaya, ono Gamosi, imane: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Hadia ni''andröu khögu, ba khö Zaneribi andrö, razo Asiria, ba no urongo.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 21, 'Da''ö daroma li, niŵa''ö Yehowa, ba khönia andrö: "Ono alawe andrö, Siona, ba si lö ba dödönia ndra''ugö, i''o''aya''ö, ifalikhö ia moroi furiu ono alawe andrö, Yeruzalema.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 22, 'Ha niha ni''o''ayamö, ha niha nitandraŵaisiu, ba ha niha nihede-hede''ömö, ba ha khö fayaŵa höröu? No khö ni''amoni''ö Ndraono Gizeraeli andrö.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 23, 'No ötandraŵaisi Zo''aya, nifa''ema zinengemö andrö, no ömane: No möido yaŵa ba zuzu hili, balazi wa''oya gureta khögu, ba wondrege hili Libano urugi; no u''obö zebua geresi ba khönia, awö zenobari nitutuyu, ose ba wondregenia no urugi, ba dalu kabu khönia.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 24, 'No ukharu mba''a ba no ubadu nidanö bö''ö, ba no u''ogo''öisi nungo nidanö ba danö Miserayi fefu lalu''a kahegu!', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 25, 'Hadia, lö nirongou? I''otarai föna sa''ae no u''asiwai, i''otarai götö föna sibai no uföfögö. Ba awena iada''e u''asogö, ena''ö ödudugö mbanua saro, ena''ö öbali''ö adudula, kara!', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 26, 'Ba ösi mbanua, ba si tobali tödö, ba wa''atebaira, ba aila, tobali hulö mbulu ndru''u ba danö, ba hulö mbulu gulegule, si mane du''u ba gero zagö, si mane sa''usö, na lö''ö na molai.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 27, 'Femaosomö ba fedadaomö, ba oroma khögu, fofanömö ba fa''asomö, ba u''ila, ba he na fabötu ndra''ugö khögu!', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 28, 'Ba me no si fabötu khögu ndra''ugö, ba me no irugi dögi dalingagu fayaŵasamö, ba ufesu nikhumö ba ube''e ba mbawau zi''öli, ba u''ohe mangawuli ndra''ugö, ufatörö''ö ba lalamö mege, me awena so''ö!"', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 29, 'Ba da''ö dania dandra khöu: Ba ndröfi da''e, ba bua zauri manö [lö mutaru] gömi, ba ba ndröfia dania, ba nalöŵa, ba ba ndröfi aefa da''ö, ba manaru ami ba mamasi, ba mifazökhi kabu nagu ba mi''a mbua.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 30, 'Ba ha niha zoloi mege, mado Yuda, si tosai, ba ifuli moŵa''a ba danö ba mowua hogu.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 31, 'Ba Yeruzalema sa la''otarai si tosai ba ba hili Ziona la''otarai soloi mege; fa''aukhu dödö Yehowa ngahönö zolau da''ö![8]', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 32, 'Andrö wa imane Yehowa, ba khö razo Asiria andrö: Lö atu''a ia ba mbanua, ba tebai ibe''e göna yomo nono wana khönia, ba lö tola i''ohe mbaluse, ba wanuwö ya''ami, ba he fogo''o fari khömi.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 33, 'Lalania mege, me awena so ia, itörö ba wangawuli, ba lö tola atu''a ia ba mbanua da''e, iŵa''ö Yehowa.', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 34, 'Ufoba''a-ba''a mbanua andre, ba wangefa''ö ya''ia, börö ndra''o ba börö na ge nonigu Dawido.[9]', '["Yes 9:6","Faigi 20:6"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 35, 'Ba ba zi bongi andrö, ba so mala''ika Yehowa, ba 185.000 ibunu niha ba golombaseŵa Ndrawa Asiria. Ba me maoso nawöra, si hulö wongi, ba hiza, ba boto zi mate manö tou da''ö fefu.', '["Ayati 7"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 36, 'Ba maoso Zaneribi, mofanö ia, ifuli ia ba Niniwe ba ba da''ö i''iagö sa''ae.', '["Ayati 7"]', NULL),
  (3475072, 'OT', 'Razo II', 19, 37, 'Ba samuza ma''ökhö, me mangandrö ia ba gosali Lowalanginia Nisirokho, ba labunu ia iraononia Aderamelekhi ba Sareseri. Ba moloi ira, lasaŵa danö Ararafa, ba fangalinia razo, ba ononia Asarahado.[10]', '["Ayati 7"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 1, 'Ba me luo da''ö, ba mofökhö Hisikia, fökhö ba wa''amate.[1] Ba möi khönia Yesaya sama''ele''ö, ono Gamosi, imane khönia: Da''ö niŵa''ö Yehowa: Oroi''ö hadia ia niŵa''öu, si mate sa''ae ndra''ugö, lö döhö wökhöu.', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 2, 'Ba ibali''ö ia, i''otahögö mbagolö, mangandrö ia khö Yehowa,', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 3, 'imane: "He Yehowa, törö tödöu, wa no utörö lala nifakhoimö, lö si faröi ndra''o, lö si dua-dua dödögu, ba no ulau zomasi ndra''ugö!" Ba mege-ege sibai Hisikia.', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 4, 'Ba ha ba golayama ba dalu na irugi Yesaya, ba humede khönia Yehowa,', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 5, 'imane: Fuli''o, ba ömane khö Hisikia, razo mbanuagu andrö: Da''ö niŵa''ö Yehowa, Lowalangi duau Dawido: No urongo wangandrömö andrö, ba taŵa höröu, ba no u''ila. Ba da''ufadöhö wökhöu; dua wongi tö, ba möi''ö miyaŵa ba gosali Yehowa.', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 6, 'Ba mewelelima fakhe udou''ö wa''anau nosou, ba baero ö na, ba u''efa''ö ndra''ugö ba banua andre ba danga razo Asiria, ba utimba zi lö sökhi ba mbanua andre, börö ndra''o ba börö na genonigu Dawido.[2]', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 7, 'Ba imane Hisikia khö Yesaya: Hadia dandra, wa abe''e ndra''o, ibe''e Yehowa, fa hatö dua wongi, ba möi ndra''o miyaŵa ba gosali Yehowa?', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 8, 'Ba imane Yesaya: Da''ö dandra khöu, nibe''e Yehowa, wa ifalua nifabu''unia: Hadia zomasi''ö, na fulu bosi idou''ö ia föna lumö andrö, ba ma fulu bosi iwuwu ia?', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 9, 'Ba imane Hisikia: Aoha na fulu bosi idou''ö ia föna lumö andrö, böi da''ö; omasido na fulu bosi iwuwu ia.', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 10, 'Ba mangandrö Yesaya khö Yehowa, ba fulu bosi ifuli ia furi lumö andrö, ba dandra luo andrö khö Gahasi, si no numalö ia mitou, ibe''e Yehowa.', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 11, 'Ba imane Yesaya: Da dalu-dalu nifalemba, bua ara. Ba lahalö ba labe''e ba waosa andrö, ba abe''e Hisikia.', '["Faigi göi Yes 38:1—8; Nga''ötII 32:24—33","Faigi 19:34"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 12, 'Ba me luo da''ö, ba ifa''ohe''ö zura ba buala khö Hisikia Merodakhi Balada, ono Mbalada, razo Mbabeli; me no irongo, wa no mofökhö Hisikia, awö wa no ifuli abe''e.', '["Faigi 24:13,14","Dan 1:3,4","SamI 3:18"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 13, 'Ba omuso dödö Hisikia ira andrö, ba i''oroma''ö khöra nomo girö-girö andrö khönia ma''asambua, awö wirö, awö gana''a, awö wamasa gö, awö wanikha sebua böli, ba omo wangöna andrö khönia, ma''asambua, awö zi so ba naha girö-girö khönia, fefu. Lö hadia ia zi lö i''oroma''ö Hisikia khöra, ba gödonia ba ba gamatöröŵania fefu.', '["Faigi 24:13,14","Dan 1:3,4","SamI 3:18"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 14, 'Ba möi khö razo Hisikia Yesaya sama''ele''ö, imane khönia: Hadia niŵa''ö niha andrö ba heza moroi ira, we''amöi khöu? Imane Hisikia: La''otarai danö saröu, ba Mbabeli moroi ira.', '["Faigi 24:13,14","Dan 1:3,4","SamI 3:18"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 15, 'Ba imane: Hadia ni''ilara ba gödomö? Ba imane Hisikia: No ahori la''ila zi so ba gödo khögu; Lö hadia ia ba naha girö-girö khögu, zi lö u''oroma''ö khöra mege.', '["Faigi 24:13,14","Dan 1:3,4","SamI 3:18"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 16, 'Ba imane Yesaya khö Hisikia: Fondrondrongo niŵa''ö Yehowa:', '["Faigi 24:13,14","Dan 1:3,4","SamI 3:18"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 17, 'Hiza, irugi baŵa dania, ba te''ohe ba Mbabeli fefu hadia ia zi so ba gödo khöu, fefu hadia ia nihöna ndra amau, awö ndra tuau; ma''ifu lö lasaigö dania, iŵa''ö Yehowa.[3]', '["Faigi 24:13,14","Dan 1:3,4","SamI 3:18"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 18, 'Ba onou andrö, nga''ötöu, ba lahalö ösa, ba wame''e mandru ya''ira ba gödo razo Mbabeli.[4]', '["Faigi 24:13,14","Dan 1:3,4","SamI 3:18"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 19, 'Ba imane Hisikia khö Yesaya: Li Yehowa andrö, nifa''emamö, ba no li si sökhi! Imane sa dödönia: Ba götögu andre, ba fa''ohahau dödö sa atö, ba lö hadia ia wamakao![5]', '["Faigi 24:13,14","Dan 1:3,4","SamI 3:18"]', NULL),
  (3475073, 'OT', 'Razo II', 20, 20, 'Ba hadia na ena''ö nidunö-dunö ba khö Hisikia andrö, ba fa''abölönia fefu, ba famazökhinia baŵa nidanö andrö, awö hele, wamatörö miyomo idanö, ba no mutanö ba zura hikaya razo mado Yuda.', '[]', NULL),
  (3475073, 'OT', 'Razo II', 20, 21, 'Ba mate Hisikia, itörö lala ndra amania, ba fangalinia razo, ba ononia Manase.', '[]', NULL),
  (3475074, 'OT', 'Razo II', 21, 1, 'Mewelendrua fakhe wa''ebua Manase, me tobali razo ia, ba 55 fakhe razo ia ba Yeruzalema.[1] Ba töi ninania, ba Hefisiba.', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 2, 'Ba si fatuwu khö Yehowa ilau, i''ohia''ö zogoro ita andrö ba niha baero andrö, nitimba Yehowa mege, föna Ndraono Gizeraeli.', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 3, 'Ba ifuli i''a''azökhi hili-hili andrö, nidudugö namania Hisikia; ifa''anö naha wame''e sumange khö Mba''ali ba ifazökhi Gasera, nifolau Gahabi, razo Ndraono Gizeraeli, ba mangalulu ia ba ngahönö ba mbanua si yaŵa [luo ba döfi] ba ifosumange da''ö.[2]', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 4, 'Ba ifa''anö naha wame''e sumange ba gosali Yehowa, ba niŵa''ö Yehowa: Yeruzalema andrö, ba ubali''ö nahia döigu.[3]', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 5, 'Ba he ba golayama gosali Yehowa si dua görö, ba ifa''anö naha wame''e sumange ba ngahönö ba mbanua yaŵa.[4]', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 6, 'Ifatörö ba galitö nononia matua, ilau wakelemusa ba faetasa ba ifataro zogaoni hekhu ba sangombakha eluaha dandra-tandra hadia ia; oya ngawalö ilau si fatuwu khö Yehowa, wangandrö fönunia.[5]', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 7, 'Ba famaedo Gasera andrö, nifazökhinia, ba ba gosali ibe''e, ba gosali niŵa''ö Yehowa khö Dawido ba khö nononia Selomo: Osali andre, awö Yeruzalema andre, nituyugu ba mado ndraono Gizeraeli fefu, ba ubali''ö nahia döigu, irugi zi lö aetu.[6]', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 8, 'Ba lö''ö sa''ae ube''e abeta ba danöra Ndraono Gizeraeli, ba danö nibe''egu khö ndra tuara; ba ha na ibe''e dödöra, la''o''ö sibai niŵa''ögu khöra ba ma''ifu lö lasawö goroisa andrö, nifa''ema genonigu Moze khöra.', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 9, 'Ba lö''ö sa la''o''ö, ba ifowöhö ira Manase, ba wolau si lö sökhi, si tedou moroi ba nilau niha baero andrö, nihori Yehowa mege, föna Ndraono Gizeraeli.', '["Faigi göi Nga''ötII 33","RazI 16:33","Ayati 7","Faigi 23:12","Faigi 16:3","RazI 8:29; 9:3"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 10, 'Ba humede Yehowa, nifa''ema genoninia andrö, sama''ele''ö, imane:', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 11, 'Me no ilau zogoro ita andrö Manase, si tedou na, moroi ba nilau Ndraono Gamori andrö fönania, fefu, ba me no ifowöhö göi mado Yuda ba wamazökhi horö, ba nadu andrö khönia,', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 12, 'andrö wa imane Yehowa, Lowalangi Ndraono Gizeraeli: Famakiko ufatörö ba Yeruzalema ba ba mado Yuda, ena''ö ma''adombua tokea dögi dalinga zamondrongo, fefu.[7]', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 13, 'Ufatörö ba Yeruzalema zinali fanua, si mane ba Zamaria mege, ba faliera ufake, si mane ba zi sawu ndra Ahabi, ba u''osi Yeruzalema, nifolosi mako, nifalögu, na no mu''osi.', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 14, 'Ba si tosai tana khögu, ba utibo''ö, ube''e ba danga nemalira, ena''ö la''oloi''ö ira emalira fefu, ba ena''ö ahulua nemalira ira,', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 15, 'börö me no lalau zi fatuwu khögu ba me no si lö aetu wangandröra fönugu, i''otarai luo me aheta ndra tuara ba danö Miserayi, irugi ma''ökhö andre.', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 16, 'Ba ato göi ifabunu''ö Manase si lö horö, irege anönö Yeruzalema do da''ö ibe''e, baero horönia andrö famowöhö mado Yuda, ba wolau si fatuwu khö Yehowa.[8]', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 17, 'Ba hadia na ena''ö nidunö-dunö ba khö Manase andrö, ba hadia ia fefu nilaunia, ba horönia andrö nifazökhinia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 18, 'Ba mate Manase, itörö lala ndra amania, ba ba lewatönia ba kabu Usa lako''o ia. Ba fangalinia razo, ba ononia Amoni.', '["SamI 3:11; Yer 19:3","Faigi 24:4"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 19, 'Dua wulu a rua fakhe Gamoni, me tobali razo ia, ba ha mendrua fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Mesulemeta, ono Harusi, banua Yotiba.', '["Ayati 19"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 20, 'Ba si fatuwu khö Yehowa ilau,', '["Ayati 19"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 21, 'nifolau namania Manase, itörö sibai lala nitörö namania mege, ifosumange nadu andrö nifosumange namania, ba da''ö mangalulu ia, ba i''erogö Yehowa,', '["Ayati 19"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 22, 'Lowalangi ndra tuania, ba lö itörö lala andrö khö Yehowa.', '["Ayati 19"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 23, 'Ba mamagölö genoni Gamoni, ba wamunu ya''ia, ba labunu razora andrö, ba gödonia.', '["Ayati 19"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 24, 'Ba maoso niha ba danö, ba lahori zi no mamagölö mege, ba wamunu razo, Amoni; ba ononia Yosia labali''ö razo, fangalinia, niha ba danö.', '["Ayati 19"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 25, 'Ba hadia na ena''ö nidunö-dunö, ba khö Gamoni andrö, ba hadia ia fefu nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["Ayati 19"]', NULL),
  (3475074, 'OT', 'Razo II', 21, 26, 'Ba ba lewatö namania, ba kabu Usa, lako''o ia; ba fangalinia razo, ba ononia Yosia.[9]', '["Ayati 19"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 1, 'Ha meŵalu fakhe wa''ebua Yosia, me tobali razo ia, ba 31 fakhe razo ia ba Yeruzalema.[1] Ba töi ninania ba Yedida, ono Gadaya, banua Mbosikata.', '["Faigi göi Nga''ötII 34:1–28","Faigi 18:3; MozV 5:29","Faigi 12:16"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 2, 'Ba somasi Yehowa ilau, itörö sibai lala duania Dawido, lö ihole''ö ia, he ba gambölö, ba he ba gabera.[2]', '["Faigi göi Nga''ötII 34:1–28","Faigi 18:3; MozV 5:29","Faigi 12:16"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475075, 'OT', 'Razo II', 22, 3, 'Ba me no alua mewelewitu fakhe razo Yosia, me baŵa si ŵalu, ba ifatenge ba gosali Yehowa durutulinia Safano, ono Gasalia ono Mesula, imane khönia:', '["Faigi göi Nga''ötII 34:1–28","Faigi 18:3; MozV 5:29","Faigi 12:16"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 4, 'Ae miyaŵa khö gere sebua, Hilikia, ba irö''ö gefe andrö ni''ohe ba gosali Yehowa, ni''ozaragö zanaro ba mbawandruhö, ba niha sato,', '["Faigi göi Nga''ötII 34:1–28","Faigi 18:3; MozV 5:29","Faigi 12:16"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 5, 'ena''ö labe''e ba mandru duka andrö, nifataro ba gosali Yehowa, ba wame''e ba zohalöŵö andrö ba gosali Yehowa, ba wanga''azökhi si no adudu ba gosali.', '["Faigi göi Nga''ötII 34:1–28","Faigi 18:3; MozV 5:29","Faigi 12:16"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 6, 'Ba duka geu ba ba zama''anö ba ba duka gara, ba he ba wowöli eu, awö gara nitoto, ba wangehao osali;', '["Faigi göi Nga''ötII 34:1–28","Faigi 18:3; MozV 5:29","Faigi 12:16"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 7, 'ba böi fa''era khöra ba gana''a andrö, nibe''e ba dangara; noa sa si faduhu dödöda ira.[3]', '["Faigi göi Nga''ötII 34:1–28","Faigi 18:3; MozV 5:29","Faigi 12:16"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 8, 'Ba imane Hilikia, ere sebua, khö Zafano durutuli: No usöndra zura goroisa, ba gosali. Ba ibe''e ba danga Zafano zura andrö Hilikia, ba ibaso.', '[]', NULL),
  (3475075, 'OT', 'Razo II', 22, 9, 'Aefa da''ö, ba möi khö razo Zafano durutuli, i''ombakha''ö khönia, imane: No lafohani gana''a andrö, si so ba gosali, enoniu ba no labe''e ba mandru duka andrö, nifataro ba gosali.', '[]', NULL),
  (3475075, 'OT', 'Razo II', 22, 10, 'Ba imane na göi Safano durutuli khö razo: No ibe''e khögu zura Hilikia ere. Ba ibaso khö razo zura andrö.', '[]', NULL),
  (3475075, 'OT', 'Razo II', 22, 11, 'Ba me irongo razo niŵa''ö ba zura goroisa andrö, ba isika nukhania.', '[]', NULL),
  (3475075, 'OT', 'Razo II', 22, 12, 'Ba humede razo khö ndra Hilikia ere, Ahika, ono Zafano, Akhiboro, ono Mikhaya, Safano durutuli ba Asaya, fazuri razo,', '[]', NULL),
  (3475075, 'OT', 'Razo II', 22, 13, 'imane: Mi''ae misofu khö Yehowa, hadia niŵa''önia khögu ba ba niha sato, ba mado Yuda fefu, ba zura andrö nisöndra; noa sa ebua wönu Yehowa, si no tesao khöda, me no lö ni''o''ö ndra tuada taroma li ba zura andrö, ba wolo''ö sibai ena''ö nitanö bakha.', '[]', NULL),
  (3475075, 'OT', 'Razo II', 22, 14, 'Ba Hilikia ere ba Ahika ba Akhiboro ba Safano ba Asaya, ba möi khö Huleda andrö, sama''ele''ö ira alawe, fo''omo Zalumi andrö, sanaro nukha, ono Dikiwa ono Haraha: ba Yeruzalema so nomora, ba mbalö mbanua tanö tou; ba fahuhuo ira khönia.', '[]', NULL),
  (3475075, 'OT', 'Razo II', 22, 15, 'Ba imane khöra: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Mimane ba niha andrö, samatenge ya''ami khögu:', '["MozV 31:29; 32:21–23","Yes 57:1,2"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 16, 'Da''ö niŵa''ö Yehowa: Si ndruhu, famakiko ufatörö ba mbanua andre ba ba nösinia, fameta''u andrö fefu, si so ba zura andrö nibaso razo mado Yuda;', '["MozV 31:29; 32:21–23","Yes 57:1,2"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 17, 'börö me no la''erogö ndra''odo, ba me no latunu gumöyö ba Lowalangi bö''ö, wangandrö fönugu, ba nifazökhi dangara andrö fefu, ba tesau sa mbakhu-bakhu dödögu ba mbanua andre, ba lö fangalö.[4]', '["MozV 31:29; 32:21–23","Yes 57:1,2"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 18, 'Ba khö razo mado Yuda andrö, samatenge ya''ami, ba wanofu khö Yehowa, ba mimane: Imane Yehowa, Lowalangi Ndraono Gizeraeli, ba niŵa''önia no mege, nirongou:', '["MozV 31:29; 32:21–23","Yes 57:1,2"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 19, 'Me no ombuyu dödöu ba me no ö''ide-ide''ö ndra''ugö föna Yehowa, me örongo hadia niŵa''ögu, nifatörögu ba mbanua andre ba ba nösinia, wa ni''elifi dania ira ba börö wehokha mbu, ba me no ötika nukhamö ba me no me''e''ö fönagu, ba no ufondrondrongo göi, iŵa''ö Yehowa.', '["MozV 31:29; 32:21–23","Yes 57:1,2"]', NULL),
  (3475075, 'OT', 'Razo II', 22, 20, 'Ba u''orudugö sa''ae ndra''ugö khö ndra amau ba khö ndra tuau, ena''ö la''ohe ba lewatömö ndra''ugö, lö hadia ia, ba ena''ö lö i''ila höröu wamakiko andrö fefu, nifatörögu dania ba mbanua andre. Ba lafa''ema khö razo.[5]', '["MozV 31:29; 32:21–23","Yes 57:1,2"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 1, 'Ba ifatenge zinenge razo ba la''owuloi khönia zatua mado Yuda ba satua mbanua Yeruzalema.[1]', '["Faigi göi Nga''ötII 34:29–36:5","Faigi 11:14; Yos 24:25"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 2, 'Ba möi miyaŵa ba gosali Yehowa razo, awö ndra matua mado Yuda ba banua Yeruzalema fefu, awö gere, awö zama''ele''ö, awö niha sato fefu, he iraono, ba he satua, ba ibaso khöra daroma li ba zura wawu''usa li andrö [oroisa andrö], ifarongogö khöra, ba zura andrö, nisöndra ba gosali Yehowa.', '["Faigi göi Nga''ötII 34:29–36:5","Faigi 11:14; Yos 24:25"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 3, 'Ba i''iagö mbörö daru nahe andrö razo, ba fawu''u li ira föna Yehowa, ba wolo''ö khö Yehowa ba ba wanöngöni oroisania, awö wamaduhu''önia andrö, awö nifakhoinia, folo''ö soroi si''aikö ba dödö ba ba gera-erara, fefu, ena''ö itörö daroma li ba wawu''usa li andrö, si so ba zura andrö. Ba dozi niha, ba latehe wawu''usa li andrö.[2]', '["Faigi göi Nga''ötII 34:29–36:5","Faigi 11:14; Yos 24:25"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 4, 'Ba ibe''e li razo khö Hilikia ere sebua ba ba gere fanete da''ö ba ba zanaro ba mbawandruhö, ba wangeheta ba gosali Yehowa fefu wakake andrö, nifazökhi ba khö Mba''ali ba ba khö Gasera ba ba ngahönö ba mbanua yaŵa. Ba ifatunu''ö ba gahe Yeruzalema, ba nitunu bötua, ba mbewe Gendrona, ba awunia, ba i''ohe ba Mbetieli.[3]', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 5, 'Ba i''efa''ö göi gere ba nadu andrö, nifataro razo mado Yuda mege, sanunununu kumöyö ba hili-hili andrö, ba mbanua Ndraono Yuda misa ba ba zi tefasui Yeruzalema, fabaya sanunununu kumöyö khö Mba''ali ba ba luo ba ba mbaŵa ba ba ndröfi, ba ngahönö andrö, ba mbanua yaŵa fefu.', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 6, 'Ba Asera andrö, ba ifaheta''ö ba gosali Yehowa, ifa''ohe''ö baero Yeruzalema, ba ndraso Gendrona, ba itunu ba mbewe Gendrona, ba ihama, ba hamahamania andrö, ba ifazawili ba dete lewatö niha si numana.', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 7, 'Ba idudugö göi nahia zohorö-horö andrö, ba zinga gosali Yehowa, ba nisoso-soso ndra alawe oloso nose Gasera.[4]', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 8, 'Ba ifakaoni''ö gere andrö, fefu, ba mbanua Ndraono Yuda misa ba ita''unöi hili-hili andrö, ba nitunutunu gere kumöyö mege, i''otarai Geba, numalö ba Mbereseba. Ba idudugö na naha wamaedo nambi si matua andrö, ba hili-hili andrö, ba zinga mbawa göli khö Yosua, kumandra mbanua, kabera na tatörö mbawa göli, we''amöi miyomo.', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 9, 'Ba ere ba hili-hili andrö, ba lö tola möi yaŵa ba zinga naha wame''e sumange khö Yehowa, ba Yeruzalema; ba la''aga''aga sa roti si lö mu''aisöni, awö dalifusöra andrö.', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 10, 'Ba ita''unöi göi naha zogoro ita andrö, ba ndraso ba Ndraono Hinomo, fa böi sa''ae ifatörö ba galitö nononia matua, ba ma ononia alawe, sumange Molokho andrö, niha, ha niha ia.[5]', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 11, 'Ba iheta kudo andrö, nibe''e razo mado Yuda sumange luo, ba zinga mbawandruhö gosali Yehowa, tanö ba mbate''e Netano-Melekhi mandru andrö, ba zahe-sahe; ba kureta ba luo andrö, ba itunu.', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 12, 'Ba he naha wame''e sumange andrö, ba mbate''e Gahasi, ba zi sagötö, nilau razo mado Yuda, ba he naha wame''e sumange, nifa''anö Manase, ba golayama gosali Yehowa, si dua görö, ba idudugö razo, iheta ba da''ö, ba adudulania, ba itibo''ö ba ndraso Gendrona.[6]', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 13, 'Ba he hili-hili andrö, tanö ba gatumbukha, na ta''otarai Yeruzalema, ba tanö miraya, na ta''otarai hili wanikha, nifazökhi Zelomo, razo Ndraono Gizeraeli, naha Astarte andrö, adu mbanua Zidona, sogoro ita, awö naha zogoro ita andrö ba Ndraono Moabi, Kamosi, ba awö naha zi hokha mbuda andrö, ba Ndraono Gamoni, Milikomo andrö, ba ifata''unöi''o razo.', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 14, 'Ba irasa harefa andrö ba i''eŵa Gasera, ba ifo''ösi töla niha nahara andrö.', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 15, 'Ba he naha wame''e sumange andrö, ba Mbetieli, hili-hili andrö, nifazökhi Yerobeamo, ono Nebati, samowöhö Iraono Gizeraeli ba horö, — naha wame''e sumange andrö, fabaya hili-hili, idudugö Yosia; itunu hili-hili andrö, ifufu, ba he Asera andrö, ba itunu.[7]', '["Faigi 21:3","RazI 14:24","Faigi 17:17; MozIII 18:21","Faigi 16:10,11; 21:4,5; Nga''ötII 28:24","RazI 12:32"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 16, 'Ba ibali''ö ia furi Yosia, ba i''ila lewatö andrö, ba da''ö ba naerenaere hili, ba ifatenge, ifahalö''ö döla zi mate andrö ba lewatö, ba itunu ba naha wame''e sumange andrö, ita''unöi naha andrö, dali niŵa''ö Yehowa, nifa''ema genoni Lowalangi no, sangombakha da''ö.[8]', '["RazI 13:2","RazI 13:30","MozII 12"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 17, 'Ba imane: Hadia dandra lewatö andrö, ni''ilagu ba da''ö? Ba lamane khönia banua da''ö: Da''ö lewatö genoni Lowalangi no, si otarai mado Yuda, sangombakha da''e, nilaumö andre, nitandrösaigö ba naha wame''e sumange ba Mbetieli.[9]', '["RazI 13:2","RazI 13:30","MozII 12"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 18, 'Ba imane: Böi mibabaya! Böi yamufahisi dölania niha, ha niha ia! Ba lö lafufu dölania, ba he töla zama''ele''ö andrö no, banua Zamaria.', '["RazI 13:2","RazI 13:30","MozII 12"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 19, 'Ba iheta göi Yosia gosali ba hili-hili andrö, fefu, ba mbanua ba Zamaria misa, nilau razo Ndraono Gizeraeli, wangandrö fönu khö Yehowa; nilaunia ba Mbetieli no mege, ilau ba da''ö göi.', '["RazI 13:2","RazI 13:30","MozII 12"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 20, 'Ba ere ba hili-hili andrö ba da''ö, fefu, ba itaba ba naha wame''e sumange andrö, ba itunu yaŵa döla niha. Aefa da''ö, ba ifuli ia ba Yeruzalema.', '["RazI 13:2","RazI 13:30","MozII 12"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 21, 'Ba ibe''e li razo ba niha sato fefu, imane: Milau wasa khö Lowalangimi, Yehowa, dali nifakhoi ba zura wawu''usa li andre.[10]', '["RazI 13:2","RazI 13:30","MozII 12"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 22, 'Me no lö mulau wasa si mane da''ö, i''otarai götö zanguhuku andrö, sanguhuku Iraono Gizeraeli, ba sagötö razo Ndraono Gizeraeli ba razo mado Yuda;', '["RazI 13:2","RazI 13:30","MozII 12"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 23, 'ha me no alua mewelewitu fakhe razo Yosia telau wasa andrö khö Yehowa, ba Yeruzalema.', '["RazI 13:2","RazI 13:30","MozII 12"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 24, 'Ba ihori göi Yosia zogaoni bekhu ba sangombakha eluaha dandra-tandra hadia ia, awö mbihara, awö nadu bö''ö, ba hadia ia zogoro ita, fefu, soroma ba danö mado Yuda ba ba Yeruzalema, ena''ö itörö niŵa''ö ba goroisa andrö, ba zura andrö, nisöndra Hilikia ere, ba gosali Yehowa.[11]', '["MozIII 20:27; MozV 29:16,17","Faigi 18:5","Faigi 21:11–16","Faigi 17:18; RazI 8:29","Faigi 9:28"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 25, 'Ba no lö fönania razo si mane ya''ia, samuli ya''ia khö Yehowa, soroi si''aikö ba dödö ba ba gera-era ba ba wa''abölö, fefu, dali sibai goroisa andrö khö Moze; ba he furinia, ba lö mu''ila zi falaŵalaŵa khönia.[12]', '["MozIII 20:27; MozV 29:16,17","Faigi 18:5","Faigi 21:11–16","Faigi 17:18; RazI 8:29","Faigi 9:28"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 26, 'Ba lö''ö sa atö döhö mbakhu-bakhu dödö Yehowa ba fönunia ba mado Yuda, börö zi fatuwu khönia andrö fefu, fangandrö Manase fönunia.[13]', '["MozIII 20:27; MozV 29:16,17","Faigi 18:5","Faigi 21:11–16","Faigi 17:18; RazI 8:29","Faigi 9:28"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 27, 'Ba imane Yehowa: Mado Yuda andrö göi, ba uheta göi ba duduma hörögu, si mane fangehetagu Iraono Gizeraeli mege, ba utibo''ö mbanua andre, nituyugu mege, Yeruzalema andre, fabaya osali, nifabu''ugu mege, wa nahia döigu ia![14]', '["MozIII 20:27; MozV 29:16,17","Faigi 18:5","Faigi 21:11–16","Faigi 17:18; RazI 8:29","Faigi 9:28"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 28, 'Ba hadia na ena''ö nidunö-dunö ba khö Yosia andrö, ba hadia ia fefu nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["MozIII 20:27; MozV 29:16,17","Faigi 18:5","Faigi 21:11–16","Faigi 17:18; RazI 8:29","Faigi 9:28"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 29, 'Ba götönia so moroi si tou Wara''o Nekho andrö, razo Miserayi, ba wanuwö razo Asiria ba Oifarati. Ba ifaondragö ia razo Yosia. Ba ibunu Yosia Fara''o, ba Megido, ha si''aikö i''ila ia.', '["MozIII 20:27; MozV 29:16,17","Faigi 18:5","Faigi 21:11–16","Faigi 17:18; RazI 8:29","Faigi 9:28"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 30, 'Ba me no mate ia, ba laheta ia ba Megido enoninia, la''ohe ba Yeruzalema, ba lako''o ia ba lewatönia. Ba lahalö Yoahasi andrö, ono Yosia, niha ba danö, ba labayoini ia, labali''ö razo, fangali namania.[15]', '["MozIII 20:27; MozV 29:16,17","Faigi 18:5","Faigi 21:11–16","Faigi 17:18; RazI 8:29","Faigi 9:28"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 31, 'Dua wulu a tölu fakhe Yoahasi, me tobali razo ia, ba ha tölu waŵa razo ia ba Yeruzalema. Ba töi ninania, ba Hamutala, ono Yeremia, banua Libena.', '["Hez 19:4","Faigi 15:20"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 32, 'Ba si fatuwu khö Yehowa ilau, nifolau ndra tuania mege, fefu hadia ia.', '["Hez 19:4","Faigi 15:20"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 33, 'Ba ifakuru''ö ia Fara''o Nekho, ba Ribila, ba danö Hamata, fa böi razo ia ba Yeruzalema, ba ikhau niha ba danö, 22.050 balaki wirö ba 39.750 balaki gana''a.[16]', '["Hez 19:4","Faigi 15:20"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 34, 'Ba ibali''ö razo Geliaki, ono Yosia, Fara''o Nekho, fangali namania Yosia, ba ifalalini döinia, Yoyaki ibe''e töinia. Ba Yoahasi andrö, ba i''ohe, ba irugi danö Miserayi Yoahasi, ba mate ia ba da''ö.', '["Hez 19:4","Faigi 15:20"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 35, 'Ba firö andrö, ba ana''a, ba ibe''e khö Wara''o Yoyaki. Ifaigi ha wa''ebua gana''a zamösana ba danö, ba wame''e ana''a andrö niŵa''ö Wara''o: balazi wa''ebua gana''a zamösana, ba wa''nguma''ö firö andrö ba ana''a, ba niha ba danö, ba wame''e khö Wara''o Nekho.[17]', '["Hez 19:4","Faigi 15:20"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 36, 'Dua wulu a lima fakhe Yoyaki andrö, me tobali razo ia, ba mewelezara fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Sebuda, ono Wedaya, banua Ruma.', '["Hez 19:4","Faigi 15:20"]', NULL),
  (3475076, 'OT', 'Razo II', 23, 37, 'Ba si fatuwu khö Yehowa ilau, nifolau ndra tuania, fefu hadia ia.', '["Hez 19:4","Faigi 15:20"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 1, 'Ba götö Yoyaki so moroi si yaŵa Nebukanesa, razo Mbabeli,[1] ba möi barö mbawania Yoyaki, medölu fakhe,', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 2, 'ba aefa da''ö, ba ifuli iheta ia. Ba ifa''amöi khönia zanuwö Yehowa, Dawa Galedaia ba Dawa Garamo ba Iraono Moabi ba Iraono Gamoni; da''ö nifatenge Yehowa sanuwö mado Yuda, ba wamakiko ya''ira dali niŵa''ö Yehowa, nifa''ema genoninia, sama''ele''ö andrö.', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 3, 'Fönu Yehowa, wa ifatörö khöra da''ö, wangeheta ya''ira ba duduma hörönia, börö horö Manase andrö, dali nilaunia andrö, fefu;[2]', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 4, 'ba do zi lö horö andrö, nibe''enia aduwa, wa no anönö Yeruzalema do zi lö horö ibe''e — da''ö zi lö edöna ibe''e aefa khönia Yehowa.', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 5, 'Ba hadia na ena''ö nidunö-dunö ba khö Yoyaki, ba hadia ia fefu nilaunia, ba noa sa mutanö ba zura hikaya razo mado Yuda.', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 6, 'Ba mate Yoyaki, itörö lala ndra amania, ba fangalinia razo, ba ononia Yoyakhi.', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 7, 'Ba lö''ö sa''ae möi miyaŵa razo Miserayi, lö''ö sa''ae iröi danönia, me no ibe''e barö mbawania razo Mbabeli danö ma''afefu, i''otarai nidanö Miserayi andrö, hadia zi so barö mbawa razo Miserayi mege, numalö ba mbewe Oifarati.', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 8, 'Meweŵalu fakhe Yoyakhi, me tobali razo ia, ba ha tölu waŵa razo ia ba Yeruzalema. Ba töi ninania, ba Nehusa, ono Gelenata, banua Yeruzalema.', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 9, 'Ba si fatuwu khö Yehowa ilau, nifolau namania, fefu hadia ia.', '["Faigi göi Nga''ötII 36:6–13","Faigi 21:10–16; 23:26,27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 10, 'Ba me luo da''ö, ba so moroi si yaŵa genoni Nebukanesa, ba wanuwö Yeruzalema, ba lafa''u''u mbanua.', '["Faigi 20:17","Yer 22:26; 24:1; RazI 25:27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 11, 'Ba me ilau ba Yeruzalema Nebukanesa, razo Mbabeli, me no lafa''u''u enoninia andrö, ba möi baero Yoyakhi,', '["Faigi 20:17","Yer 22:26; 24:1; RazI 25:27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 12, 'razo mado Yuda, i''ondrasi razo Mbabeli, ya''ia ba inania ba enoninia ba kumandra khönia ba mandru yomo khönia. Ba itaha ia razo Mbabeli, me no alua mewitu fakhe razo Nebukanesa.', '["Faigi 20:17","Yer 22:26; 24:1; RazI 25:27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 13, 'Ba ihalö fefu girö-girö ba gosali Yehowa razo Mbabeli, awö girö-girö ba gödo razo, i''ohe, ba ahori ifufu gama-gama ana''a andrö, nifazökhi Zelomo, razo Ndraono Gizeraeli, ba gosali Yehowa, itörö nidaö''ö-daö''ö Yehowa mege.[3]', '["Faigi 20:17","Yer 22:26; 24:1; RazI 25:27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 14, 'Ba banua Yeruzalema ma''afefu ba kumandra fefu ba salaŵa, fefu, 10.000, ba i''oloi''ö, awö dozi ziambu, tuka zi''öli fefu; lö nisaigö, ha niha si numana, ba danö.', '["Faigi 20:17","Yer 22:26; 24:1; RazI 25:27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 15, 'Ba i''ohe ba Mbabeli Yoyakhi razo Mbabeli; ba ina razo ba fo''omonia ba mandru yomo khönia ba salaŵa ba danö, ba ifara''u''ö ba i''oloi''ö ba Mbabeli, i''otarai Yeruzalema.[4]', '["Faigi 20:17","Yer 22:26; 24:1; RazI 25:27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 16, 'Ba dozi solohe baluse, 7.000, ba siambu ba tuka zi''öli, 1.000, oi solohe baluse — i''oloi''ö ba Mbabeli razo Mbabeli.', '["Faigi 20:17","Yer 22:26; 24:1; RazI 25:27"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 17, 'Ba ibali''ö fangali Yoyakhi razo nama Yoyakhi si akhi, Matania, ba ifalalini döinia, Sedekia ibe''e töinia.', '["Yer 52:1–3","Faigi 23:37"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 18, 'Dua wulu a sara fakhe Zedekia andrö, me tobali razo ia, ba mewelezara fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Hamutala, ono Yeremia, banua Libena.[5]', '["Yer 52:1–3","Faigi 23:37"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 19, 'Ba si fatuwu khö Yehowa ilau, nifolau Yoyaki, fefu hadia ia.[6]', '["Yer 52:1–3","Faigi 23:37"]', NULL),
  (3475077, 'OT', 'Razo II', 24, 20, 'Börö sa wönu Yehowa andrö, wa itörö Yeruzalema, awö mado Yuda, da''ö, irege itibo''ö ira, irege iheta ira ba duduma hörönia. Ba fabali khö razo Mbabeli Zedekia, molaŵa.[7]', '["Yer 52:1–3","Faigi 23:37"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 1, 'Ba me no arakha mewulu fakhe razo Zedekia,[1] ba zi mewulu ba mbaŵa si fulu, ba so Nebukanesa, razo Mbabeli, awö zabölö khönia fefu, ba wanuwö Yeruzalema; ba lafa''u''u mbanua, lako''o fari, fasui.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 2, 'Ba tobali lazuwözuŵö mbanua, irege no alua mewulu fakhe razo Zedekia.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 3, 'Ba ba zi meziŵa ba mbaŵa si öfa, ba tobali abölö-bölö sibai lofo ba mbanua, lö''ö sa''ae hadia ia, ö zato,', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 4, 'ba awena atu''a ba mbanua zanuwö; ba razo ba sabölö fefu, ba moloi, ba zi bongi, latörö mbawa göli ba gotalua göli kara andrö, ba zinga kabu razo, me samasui banua na Ndrawa Galedaia, ba latörö lala ba Garaba.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 5, 'Ba lagohi razo sabölö Ndrawa Galedaia, ba lakhamö ia ba ndraso ba ngai Yerikho, me no fabali khönia nawönia fefu, me no muzaewe.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 6, 'Ba lara''u razo ba la''ohe khö razo Mbabeli ba Ribila; ba da''ö zangetu''ö hukunia.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 7, 'Iraono Zedekia, ba labunu ba zanehe ia, ba laku hörönia, ba larate ia, ba aefa da''ö, ba la''ohe ba Mbabeli.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 8, 'Ba ba zi mewitu ba mbaŵa si lima — me no alua meweleŵalu fakhe razo Nebukanesa andrö, razo Mbabeli, — ba so Nebusa-Adana, kumandra wazuri, enoni razo Mbabeli,', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 9, 'möi ba Yeruzalema, ba itunu gosali Yehowa, fabaya gödo razo ba omo bö''ö ba Yeruzalema, fefu; omo zalaŵa fefu, ba itunu.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 10, 'Ba öli kara, si fasui Yeruzalema, ba sabölö Ndrawa Galedaia fefu zanudugö, awö kumandra wazuri andrö.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 11, 'Ba si tosai niha sato, si lö ahori yomo ba mbanua, ba soloi mege moroi yomo, sanaŵa razo Mbabeli, si tosai sato, ba i''ohe ba Mbabeli Nebusa-Adana andrö, kumandra wazuri.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 12, 'Ba niha si numana, ba danö, ba iröi furi ösa kumandra wazuri andrö, iröi sokabu nagu ba sangahalö.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 13, 'Ba taru nahe andrö töla, ba gosali Yehowa, ba he dayadaya mbalanga andrö, ba he gala sebua andrö töla, ba gosali Yehowa, ba larasa Dawa Galedaia, ba lahalö dölania andrö, la''ohe ba Mbabeli.[2]', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 14, 'Ba bowoa andrö, ba sundrusundru ba figa, fabaya nahia töla andrö, fefu, soguna ba wame''e sumange, ba lahalö.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 15, 'Awö gali andrö ba figa ba wanefe, fefu hadia ia gama-gama ana''a, awö gama-gama firö, ba ihalö kumandra wazuri.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 16, 'Taru nahe andrö, dua rozi, ba gala sebua andrö zambua, ba dayadaya no mege, nifazökhi Zelomo ba gosali Yehowa; — si tebai latulo döla gama-gama andrö fefu.[3]', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 17, 'Feleŵalu hela wa''alaŵa daru nahe andrö, ba mohögö yaŵa, högö töla; ba fa''alaŵa högö andrö, ba 5 hela, ba no mufasui ni''otaraŵa ba ni''obua dalimo högö andrö, oi töla manö; ba si manö göi ba daru nahe si sara, ba ni''otaraŵa andrö.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 18, 'Ba kumandra wazuri andrö, ba ihalö Zeraya ere sebua, awö gere fanete da''ö, Sefania, ba sanaro ba mbawandruhö andrö, si datölu.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 19, 'Ba ba mbanua, ba samösa ihalö mandru yomo khö razo, kumandra zabölö, ba dalima zi lö aefa-aefa khö razo mege, nisöndra yomo ba mbanua, awö durutuli gumandra sebua, sangofaya niha ba danö ba wasuwöta, ba 60 niha ba danö, si falukha ia yomo ba mbanua.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 20, 'Da''ö ihalö Nebusa-Adana, kumandra wazuri, ba i''ohe khö razo Mbabeli ba Ribila.', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 21, 'Ba ifabunu''ö ira razo Mbabeli ba Ribila, ba danö Hamata. Ba tobali aheta ba danöra mado Yuda, ni''oloi''ö.[4]', '["Ayati 1–21: Yer 52:4–27; 39:1–10; Nga''ötII 36:17–20","Yer 27:19–22","RazI 7:15,23,27","Faigi 23:33"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 22, 'Ba ifataro kumandru zi tosai ba danö mado Yuda Nebukanesa, razo Mbabeli, Gedalia andrö, ono Gahika, ono Zafano, kumandru nisaigönia ba danö.[5]', '["Ayati 22–26: Yer 40:5,7–9; 41:1–7; 43:5–7"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 23, 'Ba me larongo ira kumandra fefu ba sabölö, no ifataro Gedalia andrö razo Mbabeli, ba la''ondrasi Gedalia ba Misefa, ira Sima''eli, ono Netania, Yohanano, ono Garea ba Seraya, ono Danumeti, banua Netofa ba Ya''asania, ono mbanua Ma''akha andrö, ba awöra fao.', '["Ayati 22–26: Yer 40:5,7–9; 41:1–7; 43:5–7"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 24, 'Ba möi ba hölu khöra ba ba nawöra andrö Gedalia; imane khöra: Böi mi''ata''ufi Ndrawa Galedaia; böi mibulö''ö ami ba danö, mi''iagö barö mbawa razo Mbabeli, ba sohahau tödö ami!', '["Ayati 22–26: Yer 40:5,7–9; 41:1–7; 43:5–7"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 25, 'Ba me baŵa si fitu, ba ifuli so zima''eli, ono Netania ono Gelisama, nga''ötö razo, ba dafulu nawönia fao; ba labunu Gedalia, fabaya mado Yuda ba Dawa Galedaia andro, awönia ba Misefa.', '["Ayati 22–26: Yer 40:5,7–9; 41:1–7; 43:5–7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475078, 'OT', 'Razo II', 25, 26, 'Ba maoso zato fefu, he iraono, ba he satua, awö gumandra andrö, ba lasaŵa danö Miserayi, börö wa''ata''ura Ndrawa Galedaia.', '["Ayati 22–26: Yer 40:5,7–9; 41:1–7; 43:5–7"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 27, 'Ba me no arakha 37 fakhe,[6] i''otarai me la''oloi''ö Yoyakhi andrö, razo mado Yuda, ba zi 27 ba mbaŵa si felendrua, ba ihakhösi tödö Yoyakhi, razo mado Yuda, Ewili-Merodakhi, razo Mbabeli, ba ndröfi andrö, metobali razo ia; i''efa''ö ba gurunga[7]', '["Ayati 27–30: Yer 52:31–34","Faigi 24:15"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 28, 'ba ihaogö wehede khönia, ba yaŵa dadaoma zalaŵa bö''ö, si so khönia ba da''ö ba Mbabeli, ibe''e dadaomania.', '["Ayati 27–30: Yer 52:31–34","Faigi 24:15"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 29, 'Ba iheta nukhania ba gurunga Yoyakhi, ba khö razo manga-manga ia, götö wa''anau nosonia na.', '["Ayati 27–30: Yer 52:31–34","Faigi 24:15"]', NULL),
  (3475078, 'OT', 'Razo II', 25, 30, 'Ba razo zanaha balazonia — fadoro manö — ha wa''ebua zoguna khönia ma''ökhö, irugi mate ia.', '["Ayati 27–30: Yer 52:31–34","Faigi 24:15"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 1, 'Adamo, Seti, Enosi.[1]', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 2, 'Kenana, Mahalaleli, Yaredi.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 3, 'Khenoki, Metusala, Lameki.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 4, 'Noakhi, Semi, Khamo ba Yafeti.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 5, 'Ono Yafeti, ba Gomeri ba Magogi ba Madai ba Yawano ba Tubala ba Mesekhi ba Tirasi.[2]', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 6, 'Ba ono Gomeri, ba Asekena ba Rifati ba Togarema.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 7, 'Ba ono Yawano, ba Elisa ba Tarisi ba Kitimi Ba Rodanimi.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 8, 'Ba ono Khamo, ba Khusi ba Miserayi ba Futo ba Kana''ana.[3]', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 9, 'Ba ono Khusi, ba Seba ba Hawila ba Sabeta ba Raema ba Sabitekha, ba ono Raema, ba Seba ba Dedano.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 10, 'Ba nga''ötö Khusi göi Nimerodi andrö, ba ibörötaigö tobali sabölö da''ö, ba guli danö.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 11, 'Ba nga''ötö Miserayi Ndrawa Ludi ba Dawa Anami ba Dawa Lehabi ba Dawa Nafetuhi,', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 12, 'ba Dawa Waterusi ba Dawa Gasaluhi (ba da''ö dania fabali Ndrawa Wilisiti andrö) ba Dawa Gafatori.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 13, 'Ba nga''ötö Gana''ana, ba Sidona, ononia si a''a, ba Kheti,', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 14, 'ba Iraono Yebusi ba Iraono Gamori ba ba Iraono Girigasi,', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 15, 'ba Iraono Hewi ba Iraono Gariki ba Iraono Zini,', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 16, 'ba Iraono Gariwadi ba Iraono Zemari ba Iraono Hamata.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 17, 'Ba ono Zemi, ba Elama ba Asuri ba Arafasa ba Ludi ba Aramo ba Hulo ba Geteri ba Masi.[4]', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 18, 'Ba ono Garafasa, ba Sela, ba ono Zela, ba Heberi.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 19, 'Ba dombua nono Heberi, ono Matua; töi zi a''a, ba Felegi (fa''afabali), börö wa me luo da''ö fabali niha ba guli danö; ba Yoketano döi naehinia.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 20, 'Ba ono Yoketano andrö, ba Alimodada ba Salefi ba Hasamaweti ba Yara,', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 21, 'ba Hadoramo ba Usala ba Dikela,', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 22, 'ba Ebala ba Abimaeli ba Seba,', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 23, 'ba Ofiri ba Hawila ba Yobaba;', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 24, 'a''oi ono Yoketano da''ö. Semi, Arafasa, Sela,[5]', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 25, 'Heberi, Felegi, Re''u,', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 26, 'Serugi, Nakhori, Tara.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 27, 'Aberamo, ya''ia Gaberahamo andrö.', '["Faigi göi MozI 5","MozI 10:2—5","MozI 10:6—20","MozI 10:21—31","Ayati 17; MozI 11,10—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 28, 'Ba ono Gaberahamo, ba Iza''aki ba Sima''eli.[6]', '["MozI 25:13—16","MozI 25:1—3","MozI 25:19—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 29, 'Da''e nga''ötöra: ono Zima''eli, si a''a, ba Nebayoti, ba itete, ba Kedara ba Adibe''elo ba Mibisama,[7]', '["MozI 25:13—16","MozI 25:1—3","MozI 25:19—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 30, 'ba Misima ba Duma ba Masa ba Hadada ba Tema,', '["MozI 25:13—16","MozI 25:1—3","MozI 25:19—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 31, 'ba Yeturu ba Nafisi ba Kedema: Da''ö nono Zima''eli andrö.', '["MozI 25:13—16","MozI 25:1—3","MozI 25:19—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 32, 'Ba ono Getura andrö, donga Gaberahamo ba döi, ononia khönia, ba simerana ba Yokesana ba Medana ba Midiano ha Yisibaki ba Sua; ba ono Yokesana andrö, ba Seba ba Dedana.[8]', '["MozI 25:13—16","MozI 25:1—3","MozI 25:19—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 33, 'Ba ono Midiano, ba Efa ba Eferi ba Khanoki ba Abida ba Elida''a. A''oi ma''uwu Getura da''ö.', '["MozI 25:13—16","MozI 25:1—3","MozI 25:19—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 34, 'Ba ono Gaberahamo, ba Iza''aki andrö; ba ono Giza''aki ba Ezau ba Izeraeli.[9]', '["MozI 25:13—16","MozI 25:1—3","MozI 25:19—26"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 35, 'Ba ono Gezau, ba Elifasi ba Regueli ba Yehusi ba Yaelamo ba Kora.[10]', '["MozI 36:10—19","MozI 36:20—30"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 36, 'Ba ono Gelifasi andrö, ba Temano ba Omari ba Sefi ba Gaetamo ba Kena ba Timena ba Amaleki.', '["MozI 36:10—19","MozI 36:20—30"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 37, 'Ba ono Regueli, ba Nahata ba Sera ba Sama ba Misa.', '["MozI 36:10—19","MozI 36:20—30"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 38, 'Ba ono Ze''ira andrö, ba Lofana ba Sobala ba Sibeona ba Ana ba Disono ba Eseri ba Disana.[11]', '["MozI 36:10—19","MozI 36:20—30"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 39, 'Ba ono Lotana andrö, ba Hori ba Homama; ba talifusö Lotana alawe, ba Timena.', '["MozI 36:10—19","MozI 36:20—30"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 40, 'Ba ono Zobaia, ba Aliani ba Manahata ba Ebala ba Sefi ba Onamo. Ba ono Zibeona, ba Aya ba Ana.', '["MozI 36:10—19","MozI 36:20—30"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 41, 'Ba ono Ana, ba Disono; ba ono Disono ba Hamerana ba Esibana ba Yiterana ba Kerana.', '["MozI 36:10—19","MozI 36:20—30"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 42, 'Ba ono Gezeri ba, Bilihana ba Sawana ba Ya''akana. Ba ono Disana, ba Usi ba Arana.', '["MozI 36:10—19","MozI 36:20—30"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 43, 'Ba da''e razo, samatörö ba danö Ndraono Gedomo, me lö razo na ba Ndraono Gizeraeli: Bela, ono Mbeori, ba Dinihaba döi mbanuania, si soso ia.[12]', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 44, 'Ba me no mate Mbela andrö, ba fangalinia razo, ba Yobaba, ono Zera, banua Mbosera.', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 45, 'Ba me no Mate Yobaba, ba fangalinia razo, ba Husama, moroi ba danö Ndraono Demano.', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 46, 'Ba me no mate Husama, ba Hadada wangalinia razo, ono Mbedada; ya''ia zangalani Iraono Midiano, ba zalo''o, ba danö Ndraono Moabi; ba töi mbanua, si soso ia, ba Awiti.', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 47, 'Ba me no mate Hadada, ba Samila wangalinia razo, banua Mazereka.', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 48, 'Ba me no mate Zamila, ba Saulo wangalinia razo, banua Rehoboti, ba Oifarati.', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 49, 'Ba me no mate Zaulo ba Ba''ali-hanana wangalinia razo, ono Nakhibora.', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 50, 'Ba me no mate Mba''ali-hanana, ba Hadada wangalinia razo; töi mbanua si soso ia, ba Fagi, ba töi wo''omonia, ba Mehetabeli, ono Materedi, ma''uwu Mezahaba.', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 51, 'Ba mate Hadada andrö; ba salaŵa ba Ndraono Gedomo, ba salaŵa Dimena ba salaŵa Galiwa ba salaŵa Yeteti', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 52, 'ba salaŵa Goholibama ba salaŵa Ela ba salaŵa Winoni,', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 53, 'ba salaŵa Gena ba salaŵa Demano ba salaŵa Mibesaro,', '["MozI 36:31—43"]', NULL),
  (3475080, 'OT', 'Nga''ötö I', 1, 54, 'ba salaŵa Magidieli ba salaŵa Giramo. Da''ö zalaŵa ba Ndraono Gedomo andrö.', '["MozI 36:31—43"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 1, 'Da''e Ndraono Gizeraeli:[1] Rubeno ba Simeoni ba Lewi ba Yuda ba Isasari ba Sebuloni[2]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 2, 'ba Dano ba Yosefo ba Beniyami ba Nafetali ba Gado ba Aseri.', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 3, 'Ba ono Yuda, ba Geri ba Onani ba Sela, tölu; ononia khö nono Zua andrö, Dawa Gana''ana. Ba Geri andrö si a''a nono Yuda, ba ilau zi fatuwu khö Yehowa; andrö ibe''e mate ia Yehowa.[3]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 4, 'Ba mo''ono Yuda khö numönönia Tamara andrö, Feresi ba Sera döi nono da''ö. Ono Yuda, ono matua, ba lima fefu.[4]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 5, 'Ba ono Weresi, ba Heserono ba Hamuli.[5]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 6, 'Ba ono Zera, ba Simeri ba Etano ba Hemano ba Khalikoli ba Dara, lima fefu.', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 7, 'Ba ono Garimi, ba Akhari (Akhano), samobörö famakao ba Ndraono Gizeraeli, me falimo ia, me ihalö ni''amoni''ö andrö.[6]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 8, 'Ba ono Netano, ba Asaria.', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 9, 'Ba ono Heserono, si tumbu khönia, ba Yerameli ba Ramo ba Kelubai.[7]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 10, 'Ba ono Ramo, ba Aminadabi, ba ono Gaminadabi, ba Nahaso, salaŵa mado Yuda andrö;', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 11, 'ba ono Nahaso, ba Salema, ba ono Zalema ba Boasi,', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 12, 'ba ono Mboasi ba Obedi, ba ono Gobedi, ba Iza''i.', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 13, 'Ba ono Giza''i, ba Eliabi, si sa''a, ba itete, ba Abinadabi, ba itete, ba Simea,[8]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 14, 'ba itete, ba Netaneli, ba itete, ba Rada''i,', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 15, 'ba itete, ba Osema, ba itete, ba Dawido, fitu.[9]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 16, 'Ba talifusöra alawe, ba Seruya ba Abigaila; ba ono Zeruya andrö, ba Abiza''i ba Yoabi ba Azaheli, tölu.', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 17, 'Ba ono Abigaila, ba Amasa, ba ama Gamasa, ba Iraono Zima''eli, Yetero döi.[10]', '["Faigi göi Faza 4","MozI 35:22—26","MozI 38:1—7","MozI 38:29,30","MozI 46:12","Yos 7","Rut 4:19—22; Mat 1:3; Ayati 18:42","SamI 16:6—10","SamI 17:12","SamII 17:25"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 18, 'Ba Kalebi andrö, ono Heserono, ba mo''ono khö wo''omonia Asuba ba khö Yeriota, ba da''e nono da''ö: Yeseri ba Sobaba ba Aridono.[11]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 19, 'Ba me no mate Gasuba, ba ihalö Geferata andrö Kalebi, ba mo''ono ia khönia, Huri.[12]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 20, 'Ba ono Huri, ba Uri, ba ono Guri ba Besale''eli.[13]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 21, 'Ba aefa ö, ba Ihoröni nono Makhiro andrö, ama Gileadi, Heserono, ba ihalö, me no 60 fakhe ia, ba mo''ono, Segubi.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 22, 'Ba ono Zegubi ba Ya''iro; 23 mbanua da''ö ba danö Gileadi.[14]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 23, 'Ba lafadöni khöra halama soya andrö khö Ya''iro, banua Gesuri ba Dawa Garamo, Kenata andrö, awö zi faböbö khöra, önö ngafulu banua fefu. Oi nga''ötö Makhiro, ama Gileadi, da''ö.[15]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 24, 'Ba me no mate Heserono, ba möi ba Geferata Galebi. Ba fo''omo Heserono, ba Abia; ba mo''ono da''ö khönia, Asihuri, ama Dekoa andrö.[16]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 25, 'Ba ono Yerameli andrö, si a''a nono Heserono, ba Ramo, si a''a, ba Buna ba Oreni ba Osema ba Ahia.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 26, 'Ba sambua tö na ndronga Yerameli, Atara döi; da''ö nina Gonamo.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 27, 'Ba ono Ramo andrö, si a''a nono Yerameli, ba Ma''asi ba Yamini ba Ekeri.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 28, 'Ba ono Gonamo, ba Samai ba Yada, ba ono Zamai ba Nadabi ba Abisuri.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 29, 'Ba töi wo''omo Gabisuri, ba Abihaila; mo''ono da''ö khönia, Akhibana ba Molidi.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 30, 'Ba ono Nadabi, ba Seledi ba Afa''i; ba si lö nga''ötö Zeledi.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 31, 'Ba ono Gafa''i, ba Yizai; ba ono Yizai, ba Sezana; ba ono Zezana, ba Ahelai.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 32, 'Ba ono Yada, akhi Zamai, ba Yetero ba Yonata, ba si lö nga''ötö Yetero.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 33, 'Ba ono Yonata, ba Feleti ba Sasa. Da''ö nga''ötö Yerameli andrö.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 34, 'Ba Sezana andrö, ba si lö ono matua, ba sambalö ono alawe. Ba so khö Zezana zawuyu, Dawa Miserayi, Yaraha döi.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 35, 'Ba ibe''e donga zawuyunia Yaraha andrö nononia alawe Sezana; ba mo''ono da''ö khönia, Ata''i.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 36, 'Ba ono Gata''i, ba Natano, ba ono Natano, ba Sabada.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 37, 'Ba ono Zabada, ba Efilali, ba ono Gefilali, ba Obedi.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 38, 'Ba ono Gobedi, ba Yehu, ba ono Yehu, ba Asaria.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 39, 'Ba ono Gasaria, ba Helesi, ba ono Helesi, ba Eleasa.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 40, 'Ba ono Geleasa, ba Sisemai, ba ono Zisemai, ba Salumi.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 41, 'Ba ono Zalumi, ba Yekania, ba ono Yekania, ba Elisama.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475081, 'OT', 'Nga''ötö I', 2, 42, 'Ba ono Galebi andrö, akhi Yerameli, ba Mesa, si a''a nononia, ama Zifi andrö, ba ono Maresa, ama Heberona.[17]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 43, 'Ba ono Heberona, ba Kora ba Tafua ba Rekemi ba Sema.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 44, 'Ba ono Zema, ba Rahama, ama Yorekea andrö, ba ono Rekemi ba Samai.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 45, 'Ba ono Zamai, ba Ma''ono, ama Mbeti-Suri.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 46, 'Ba mo''ono Gefa, donga Galebi ba döi, Harana ba Mosa ba Gazesi döi nononia. Ba ono Harana, ba Gazesi.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 47, 'Ba ono Yeda''i, ba Regemi ba Yotamo ba Gesana ba Feleti ba Efa ba Sa''afo.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 48, 'Ba mo''ono göi Ma''akha, donga Galebi ba döi göi. Seberi ba Tirena döi nono da''ö.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 49, 'Ba ononia na göi Za''afo, ama Mademana, ba Sewa, ama Makhebena, ba ama Gibea andrö; ba ono Galebi alawe, ba Akhasa.[18]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 50, 'Da''e nga''ötö Galebi andrö. Ono Huri andrö, si a''a nono Geferata, ba Sobala, ama Giriati Yeari,[19]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 51, 'ba Salema, ama Mbetilekhema, ba Harefa, ama Mbeti-Gaderi.', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 52, 'Ba ono Zobala andrö, ama Giriati Yeari, ba Haru, si matonga mbanua Manuhota,', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 53, 'awö nga''ötö Giriati Yeari ba Iraono Yiteri ha Iraono Wuto ba Iraono Zumati ba Iraono Misera; ba ba da''ö fabali Ndraono Zoreati andrö ba Iraono Esa''oli.[20]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 54, 'Ba Iraono Zalema andrö, ba Betilekhema ba Iraono Netofati, ba Ataroti ba Beti Yoabi, ba si matonga mbanua Manati, ya''ia mbanua Zorea,[21]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475081, 'OT', 'Nga''ötö I', 2, 55, 'awö nga''ötö zangila amakhoita andrö, banua Yabesi, ba Tireati andrö ba Simeati ba Sukhati. Da''ö, Ndraono Gini andrö, nga''ötö Hamata andrö, furugö ma''uwu Rekhabi.[22]', '["Ayati 9,42","Ayati 50","MozII 31:2","Sanguhuk 10:3","RazI 4:13","Faigi 4,5.","Ayati 18","Yos 15:16; Sanguhuk 1:12","Ayati 19","Faigi 4:3","Faigi 9:16","Sanguhuk 1:16; Yer 35"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 1, 'Ba da''e nono Dawido, ononia ba Heberona: Si a''a, ba Amoni, ononia khö Gahinoa andrö, banua Yezere''eli; ba itete, ba Danieli, ono Abigaila, banua Garemeli,[1]', '["SamII 3:2–5","Faigi 14:4–7; SamII 5:14–16","SamII 13:1"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 2, 'ba itete, ba Abisalomi, ononia khö Ma''akha, ono Dalamai, razo Gesuri; ba itete, ba Adonia, ono Hagita;', '["SamII 3:2–5","Faigi 14:4–7; SamII 5:14–16","SamII 13:1"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 3, 'ba itete, ba Sefatia, ono Gabitala; ba itete, ba Yiterea, ononia khö wo''omonia Egela andrö. 4önö zi tumbu khönia ba Heberona. Mewitu fakhe a matonga razo ia ba da''ö, ba 33 fakhe ba Yeruzalema.', '["SamII 3:2–5","Faigi 14:4–7; SamII 5:14–16","SamII 13:1"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 5, 'Ba ononia ba Yeruzalema, ba Simea ba Sobaba ba Natano ba Selomo, öfa, ononia khö Mbasua (Baseba) andrö, ono Gamieli:[2]', '["SamII 3:2–5","Faigi 14:4–7; SamII 5:14–16","SamII 13:1"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 6, 'ba ononia baero ö, ba Yibihara ba Elisama ba Elifeleti,', '["SamII 3:2–5","Faigi 14:4–7; SamII 5:14–16","SamII 13:1"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 7, 'ba Noga ba Nefegi ba Yafia,', '["SamII 3:2–5","Faigi 14:4–7; SamII 5:14–16","SamII 13:1"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 8, 'ba Elisama (zui) ba Eliada ba Elifeleti, siŵa fefu.', '["SamII 3:2–5","Faigi 14:4–7; SamII 5:14–16","SamII 13:1"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 9, 'Awai nono Dawido, lö lai nononia khö ndrongania ba döi andrö. Ba talifusöra alawe, ba Tamara andrö.[3]', '["SamII 3:2–5","Faigi 14:4–7; SamII 5:14–16","SamII 13:1"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 10, 'Ba Rehabeamo nono Zelomo; ba Abia nono da''ö, ba Asa nono da''ö ba Yozafati nono da''ö,', '[]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 11, 'ba Yoramo nono da''o, ba Ahaseya nono da''ö, ba Yoasi nono da''o,', '[]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 12, 'ba Amasia nono da''ö, ba Asaria nono da''ö, ba Yotamo nono da''ö,', '[]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 13, 'ba Ahasi nono da''ö, ba Hisikia nono da''ö, ba Manase nono da''ö,', '[]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 14, 'ba Amoni nono da''ö, ba Yosia nono da''ö.', '[]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 15, 'Ba ono Yosia, ba Yohanano, si a''a, ba itete, ba Yoyaki, ba itete, ba Sedekia, ba itete, ba Salumi.', '[]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 16, 'Ba ono Yoyaki, ba Yekhonia; ba ono da''ö, ba Sedekia.', '[]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 17, 'Ba ono Yekhonia andrö, ni''oloi''ö, nikuru, ba Selatieli,[4]', '["Nga''ötII 36:10","Eser 3:2,8"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 18, 'ba Malikhira ba Fedaya ba Seneasari ba Yekamia ba Hosama ba Nebadia.', '["Nga''ötII 36:10","Eser 3:2,8"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 19, 'Ba ono Wedaya, ba Serubabeli ba Sime''i, ba ono Zerubabeli, ba Mesulami ba Hanania, ba talifusöra alawe, ba Selomita.[5]', '["Nga''ötII 36:10","Eser 3:2,8"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 20, 'Ba ononia na göi, ba Hasuba ba Oheli ba Berekhia ba Hazadia ba Yusaba-Hasedi, lima.', '["Nga''ötII 36:10","Eser 3:2,8"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 21, 'Ba ono Hanania, ba Felatia ba Yesaya; awö nga''ötö Refaya, ba he nga''ötö Garenano, ba he nga''ötö Gobadia, ba he nga''ötö Zekhania.', '["Nga''ötII 36:10","Eser 3:2,8"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 22, 'Ba ono Zekhania, ba Semaya, ba ono Zemaya, ba Hatusi ba Yigeala ba Baria, ba Nearia ba Safati, daönö ira.', '["Nga''ötII 36:10","Eser 3:2,8"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 23, 'Ba ono Nearia, ba Eliunai ba Hisikia, ba Asirika, tölu.', '["Nga''ötII 36:10","Eser 3:2,8"]', NULL),
  (3475083, 'OT', 'Nga''ötö I', 3, 24, 'Ba ono Geliunai, ba Hodawia, ba Eliazibi ba Felaya ba Akubi ba Yohanano ba Delaya ba Anani, fitu.', '["Nga''ötII 36:10","Eser 3:2,8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 1, 'Ba nga''ötö Yuda, ba Feresi ba Heserono ba Karimi ba Huri ba Sobala.[1]', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 2, 'Ba ono Reaya ono Zobala, ba Yahata; ba ono Yahata, ba Ahumai ba Lahadi. Da''ö watalifusöta mbanua Zorea andrö.[2]', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 3, 'Ba da''e ndraono Getama: Yezere''eli ba Yisima ba Yidibasi; ba talifusöra alawe, ba Haselelifoni.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 4, 'Ba ononia na, ba Fenueli, ama Gedoro, ba Ezeri, ama Husa. Da''ö nga''öto Huri andrö, ono Geferata, si a''a, ama Mbetilekhema.[3]', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 5, 'Ba dombua ndronga Gasihuri, ama Dekoa, Helea ba Naera döi.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 6, 'Ba ono Naera, ba Ahusa ba Heferi ba Timeni, ba Ahasari. Da''ö nono Naera andrö.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 7, 'Ba ono Helea, ba Sareti ba Yisihara ba Etano.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 8, 'Ba ono Gosi, ba Anubi ba Hasobeba, ba ya''ia na nga''ötö Gagareheli ono Harumi.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 9, 'Ba Yaebesi, ba no niha soadu, moroi ba dalifusönia; ba ibe''e töinia Yaebesi inania, imane: No utaha wa''afökhö mege, me u''adonogö ia.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 10, 'Ba i''angaröfi li Lowalangi Ndraono Gizeraeli Yaebesi, imane: Na öfahowu''ö ndra''odo ba na ebolo danögu öbe''e, na itolodo tangau ba na ötimba khögu wamakao; na lö gönado fa''afökhö öbe''e… Ba i''o''ö wangandrönia Lowalangi.[4]', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 11, 'Ba ono Gelubi, talifusö Zuha, ba Mehiri, ya''ia nama Gesihono.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 12, 'Ba ono Gesihono, ba Beti-Rafa, ba Fasea ba Tehina, tua mbanua Nahazi. Da''ö mbanua Rekha andrö.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 13, 'Ba ono Gena, ba Otenieli ba Seraya. Ba ono Gotenieli, ba Hatata.[5]', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 14, 'Ba ono Menota''i, ba Ofera, ba ono Zeraya, ba Yoabi, tua zi so ba ndraso andrö "benua duka"; noasa tuka ira.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 15, 'Ba ono Galebi andrö, ono Yefune, ba Iru ba Ela ba Na''ama; ba ono Ela, ba Kenasi.[6]', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 16, 'Ba ono Yehaleleli, ba Sifi ba Sifa ba Tiria ba Asereli.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 17, 'Ba ono Gesera, ba Yetero ba Meredi ba Eferi ba Yalono. Ba da''e nono Mbitia andrö, ono Wara''o, nihalö Meredi: mo''ono ia khönia, Miriya ba Samai ba Yisiba, ama Gesihemoa.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 18, 'Ba ononia khö wo''omonia niha Yehuda, ba Yeredi, ama Gedoro ba Heberi, ama Zokho, ba Yekutieli, ama Zanoa.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 19, 'Ba ono wo''omo Hodia andrö, talifusö Nahamo, ba ama Kegila, banua Garimi, ba Esihemoa, banua Ma''akhata.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 20, 'Ba ono Zimoni, ba Amoni ba Rina ba Beni-Hanana ba Tilono. Ba ono Yisei, ba Soheti ba ono Zoheti andrö.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 21, 'Ba ono Zela, ono Yuda, ba Geri, ama Lekha, ba Laeda, ama Maresa, awö watalifusöta zanoso muko andrö, banua Mbeti Asebea;[7]', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 22, 'ba Yokimi, ba banua Goseba andrö ba Yoasi ba Sarafa, samadöni tanö ba Ndraono Moabi, ba samuli ya''ira ba Mbetilekhema. Ba ba götö föna sa''ae da''o.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 23, 'Samöbözi bowoa ira, ba ba Neta''i ba ba Gedara so ira khö razo, enoninia, ira, wa ba da''ö so ira.', '["Faigi 2:4,5,7,19,50","Faigi 2:53","Faigi 2:19,50","MozI 28:20","Yos 15:17; Sanguhuk 1:13","MozIV 13:6; 14:6","Faigi 2,3"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 24, 'Ba ono Zimeoni, ba Nemueli ba Nemini ba Yaribi ba Sera ba Saulo;[8]', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 25, 'ono da''ö, ba Salumi, ba ono da''ö, ba Mibisama ba ono da''ö, ba Misima.', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 26, 'Ba ono Misima, ba Hamueli, ba ono da''ö, ba Sakuri, ba ono da''ö ba Sime''i.', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 27, 'Ba 22 nono Zime''i, 16 nono matua ba 6 nono alawe; ba talifusönia, ba sambö ono, ba tobali öna-öna wa''atedou nga''ötöra; sambua ba mado Yuda.', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 28, 'Ba banuara, ba Bereseba, ba Molada ba Hasara Zuali,', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 29, 'ba Biliha ba Eseme ba Tolada,', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 30, 'ba Betueli ba Horema ba Sikelagi,[9]', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 31, 'ba Beti Makaboti ba Hasara Zusi ba Beti Mbire''i ba Sa''ara''i. Da''ö mbanuara andrö, irugi götö me razo Dawido.', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 32, 'Ba banua side-ide khöra, ba Etama ba A''ini ba Rimono ba Tokhene ba Asana, — lima banua;', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 33, 'awö halama soya, si tefasui banua andrö, irugi Mba''ali. Da''ö nahiara, ba da''ö nga''ötöra.', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 34, 'Ba baero ö, ba Mezobaba ba Yamilekhi ba Yosa, ono Gamasia,', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 35, 'ba Yoeli ba Yehu, ono Yozibia, ono Zeraya ono Asieli,', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 36, 'ba Eliunai ba Ya''akoba ba Yezohaya ba Asaya ba Adieli,', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 37, 'ba Yezimieli ba Benaya, ba Sisa, ono Zifei ono Alono ono Yedaya ono Zimeri ono Zemaya.', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 38, 'Nitötöi töi ba da''e ba no salaŵa ba nga''ötö khöra, ba no ato sibai watalifusöta andrö khöra.', '["MozI 46:10","Yos 19:2–8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 39, 'Ba larugi tanö ba Gedoro, irege tanö ba gatumbukha luo, na ta''otarai ndraso andrö, ba wangalui sabölö du''u, ba guriföra.', '["Sanguhuk 18:7","SamI 15:3,8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 40, 'Ba lasöndra zatabö du''u, si sökhi, ba tanö, ba no ebolo, ba lö hadia ia, lö emali; niha si so ba da''ö, fönara mege, ba ma''uwu Khamo.[10]', '["Sanguhuk 18:7","SamI 15:3,8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 41, 'Ba so nitötöi mege andrö, me luo razo mado Yuda Hisikia, ladudugö nosera, lasuwö mbanua Ma''ono andrö, si no fatewu ba da''ö, ba lahori, irege ma''ökhö andre, ba la''iagö fangalira; me falukha ndru''u ba da''ö, ö guriföra.', '["Sanguhuk 18:7","SamI 15:3,8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 42, 'Ba so ösa, mado Zimeoni, zi möi misi yaŵa ba hili Ze''ira — lima ngaotu; solohe ya''ira, ba Felatia ba Nearia ba Refaya, ba Usieli, ono Yisei andrö.', '["Sanguhuk 18:7","SamI 15:3,8"]', NULL),
  (3475084, 'OT', 'Nga''ötö I', 4, 43, 'Ba labunu gangohorita Ndraono Gamaleki, ba lö labulö''ö ira ba da''ö, irugi ma''ökhö andre.[11]', '["Sanguhuk 18:7","SamI 15:3,8"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 1, 'Ba ono Rubeno, si a''a ndraono Gizeraeli, — noa sa ya''ia zi a''a; ba me no ra''iö gaso namania ibe''e, ba tebe''e ba ndraono Yosefo, ono Gizeraeli, wa''asia''a andrö khönia, fa böi tebe''e si a''a ia ba zura nga''ötö andrö.[1]', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 2, 'Noa sa Yuda andrö zi hulö zabölöra, ba ba nga''ötönia tetuyu zalaŵa, [samatörö]; ba fa''asia''a, ba khö Yosefo. —[2]', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 3, 'Ba ono Rubeno, si a''a nono Gizeraeli, ba Hanokhi ba Falu ba Heserono ba Karimi.[3]', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 4, 'Ba ono Yoeli, ba Semaya, ba ono da''ö, ba Gogi ba ono da''ö, ba Sime''i,', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 5, 'ba ono da''ö, ba Mikha, ba ono da''ö, ba Reaya, ba ono da''ö, ba Ba''ali,', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 6, 'ba ono da''ö, ba Be''era, ni''oloi''ö Digelata-Filezeri, razo Asiria; salaŵa ia, ba mado Rubeno.[4]', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 7, 'Ba talifusönia, ba watalifusöta khöra, nitanö ba zura nga''ötö, ba no Yeieli, si a''a,', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 8, 'ba Sakharia, ba Bela, ono Asa ono Zema ono Yoeli; ba Garuri so da''ö, ba irege hili Nebo ba iregi Mba''ali Meono.', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 9, 'Ba tanö ba gatumbukha luo ba irugi ba zinga danö si mate andrö, si börögö ba mbewe Oifarati: noa sa oya sibai guriföra, ba danö Gileadi.', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 10, 'Ba me luo Zaulo, ba fasuwö ira ba mbanua Hegara andrö; ba me no te''ala da''ö labe''e, ba la''okhögö nosera, sagörö tanö manö tanö ba gatumbukha, i''otarai danö Gileadi.', '["MozI 35:22; 49:4","MozI 49:8,10,22; MozV 33:7,13–17","MozII 6:14","Ayati 26"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 11, 'Ba iraono Gado, ba ba gamaudura so, ba danö Mbazana, irugi Zalikha:', '["RazII 15:32,14:23"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 12, 'Yoeli, sanuhe, ba Safama, tambalina, ba Yaenai ba Safata, ba Mbazana.', '["RazII 15:32,14:23"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 13, 'Ba talifusöra, ba ngafura andrö, ba Mikhaeli ba Masula ba Seba ba Yorai ba Yaeka ba Sia ba Eberi, fitu.', '["RazII 15:32,14:23"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 14, 'Da''ö nono Abihaila andrö ono Huri ono Yaroahi ono Gileadi ono Mikhaeli ono Yezizai ono Yado ono Mbusi.', '["RazII 15:32,14:23"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 15, 'Ba Ahi andrö, ono Abidieli ono Guni, ba no högö ngafura andrö.', '["RazII 15:32,14:23"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 16, 'Ba ba danö Gileadi so ira, ba Mbazana ba ba mbanua si faböbö ba da''ö, ba ba zabölö du''u, ba Zarona, fefu, irugi mbalönia.', '["RazII 15:32,14:23"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 17, 'Da''ö fefu nitanö ba zura, me luo razo mado Yuda Yotamo ba me luo razo Ndraono Gizeraeli Yerobeamo [II.][5]', '["RazII 15:32,14:23"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 18, 'Mado Rubeno ba mado Gado ba si matonga mado Manase, sabölö, solohe baluse ba si''öli ba sangila mogai fana ba si no to''ölö ba wasöndrata — 44.760 zabölö —', '[]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 19, 'ba fasuwö ba mbunua Hegara andrö, ba ba Ndraono Yeturi ba ba Ndraono Nafisi ba ba Ndraono Nodaba.', '[]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 20, 'Ba tetolo ira, ba tebe''e ba dangara mbanua Hegara andrö, fabaya si fa''awö khöra fefu. Noa sa la''angaröfi li Lowalangi, barö wasuwöta andrö, ba ifondrondrongo khöra, me no khönia manötöna ira.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475085, 'OT', 'Nga''ötö I', 5, 21, 'Ba urifö nudura andrö, ba la''ohe ahulua: 50.000 gondra ba 250.000 mbiri-biri ba 2000 galide ba baero ö, ba 100.000 niha.', '[]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 22, 'Noa sa ato zi mate nibunu, me no moroi ba Lowalangi wasuwöta andrö. Ba la''iagö nahiara, irugi luo la''oloi''ö ira [Dawa Asiria].', '[]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 23, 'Ba ba danö Mbazana so nga''ötö zi matonga mado Manase, irugi Mba''ali Heremono ba Senira andrö ba bawö Heremono; no ato ira.[6]', '["MozV 3:9"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 24, 'Ba da''e zatua ngafura: Eferi ba Yisei ba Elieli ba Aserieli ba Yeremia ba Hodawia ba Yadieli, oi niha sabölö ba sebua turia, högö ngafura andrö.', '["MozV 3:9"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 25, 'Ba me la''erogö Lowalangi ndra tuara, me no amaedola zohorö-horö ira ba nadu niha baero andrö, nihori Lowalangi fönara,', '["RazII 15:19; 15:29"]', NULL),
  (3475085, 'OT', 'Nga''ötö I', 5, 26, 'ba ifarou dödö Wulo andrö, razo Asiria, Lowalangi Ndraono Gizeraeli ba he tödö Digelata-Filezeri, razo Asiria; ba lasuwö mado Rubeno ba mado Gado ba si matonga mado Manase, ba la''oloi''ö ba Hala ba ba Habora ba ba Hara ba ba mbewe Gosana, irugi ma''ökhö andre.[7]', '["RazII 15:19; 15:29"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 1, 'Ba ono Lewi, ba Gereso ba Kahati ba Merari.[1]', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 2, 'Ba ono Gahati, ba Ameramo ba Yisihara ba Heberona ba Usieli.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 3, 'Ba ono Gameramo, ba A''aroni ba Moze ba Miriya. Ba ono Ga''aroni, ba Nadabi ba Abihu ba Eleazari ba Itamari.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 4, 'Ba ono Geleazari, ba Fineha, ba ono Wineha, ba Abisua.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 5, 'Ba ono Gabisua, ba Buki, ba ono Mbuki, ba Usi.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 6, 'Ba ono Usi, ba Seraya, ba ono Zeraya, ba Marayoto,', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 7, 'ba ono Marayoto, ba Amaria, ba ono Gamaria, ba Ahitubi.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 8, 'Ba ono Gahitubi, ba Sadoki, ba ono Zadoki, ba Ahimasi.[2]', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 9, 'Ba ono Gahimasi, ba Asaria, ba ono Gasaria, ba Yohanano.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 10, 'Ba ono Yohanano, ba Asaria [zui]; da''ö zangai halöŵö gere andrö, ba gosali, nilau Zelomo, ba Yeruzalema.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 11, 'Ba ono Gasaria, ba Amaria, ba ono Gamaria ba Ahitubi.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 12, 'Ba ono Gahitubi, ba Sadoki, ba ono Zadoki, ba Salumi.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 13, 'Ba ono Zalumi, ba Hilikia, ba ono Hilikia, ba Asaria.[3]', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 14, 'Ba ono Gasaria, ba Seraya, ba ono Zeraya, ba Yosadaki.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 15, 'Ba Yosadaki andrö, ba saheta, me ibe''e Yehowa i''oloi''ö mado Yuda ba banua Yeruzalema Nebukanesa.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 16, 'Ba no da''e nono Lewi: Gereso ba Kahati, ba Merari.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 17, 'Ba da''e döi nono Gereso: Libeni ba Sime''i.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 18, 'Ba ono Gahati, ba Ameramo ba Yisihara ba Heberona ba Usieli.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 19, 'Ba ono Merari, ba Maheli ba Musi. Ba da''e nga''ötö nono Lewi, ba ngafura andrö:', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 20, 'Ono Gereso, ba Libeni, ba ono da''ö, ba Yehata, ba ono da''ö, ba Sima,', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 21, 'ba ono da''ö, ba Yoa, ba ono da''ö, ba Ido, ba ono da''ö, ba Sera, ba ono da''ö, ba Yeaterai.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 22, 'Ba ono Gahati, ba Aminadabi, ba ono da''ö ba Kora, ba ono da''ö, ba Asiri,', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 23, 'ba ono da''ö, ba Elikana, ba ono da''ö, ba Ebiasafo, ba ono da''ö, ba Asiri,', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 24, 'ba ono da''ö, ba Tahata, ba ono da''ö, ba Urieli, ba ono da''ö, ba Usia, ba ono da''ö ba Saulo.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 25, 'Ba ono Elikana, ba Amiza''i ba Ahimoti;', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 26, 'ba ono da''ö, ba Elikana, ba ono da''ö, ba Sofa''i, ba ono da''ö,', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 27, 'ba Nahata, ba ono da''ö, ba Eliabi, ba ono da''ö, ba Yerohama, ba ono da''ö, ba Elikana.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 28, 'Ba ono Zamueli, ba Yoeli, si a''a, ba itete, ba Abia.[4]', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 29, 'Ba ono Merari, ba Maheli, ba ono da''ö, ba Libeni, ba ono da''ö, ba Sime''i, ba ono da''ö,', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 30, 'ba Usa, ba ono da''ö, ba Simea, ba ono da''ö, ba Hagia, ba ono da''ö ba Asaya.', '["MozII 6:16","SamII 8:17","RazII 22:4","SamI 8:1"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 31, 'Ba da''e nifataro Dawido ba wanunö, ba gosali, me no mo''ahonoa nahia dawöla andrö:', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 32, 'fanunö halöŵöra, föna nahia nose wama''ele''ö andrö, irege ilau gosali Yehowa Selomo, ba Yeruzalema, ba lafalua nifataro ya''ira, dali nifakhoi khöra.', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 33, 'Ba da''e nifataro ba da''ö ba onora: Nga''ötö Gahati: Hemano, sanunö andrö, ono Yoeli ono Zamueli', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 34, 'ono Elikana ono Yerohamo', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 35, 'ono Elieli ono Du ono Zufi ono Elikana', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 36, 'ono Mahata ono Amizai ono Elikana ono Yoeli ono Gasaria ono Zefania', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 37, 'ono Dahata ono Asiri ono Gebiasafo ono Gora[5]', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 38, 'ono Yisihara ono Gahati ono Lewi ono Gizeraeli.', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 39, 'Ba talifusönia Gasafo, si so ba gambölönia, Asafo', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 40, 'ono Mberekhia ono Zimea ono Mikhaeli ono Mba''aseya ono Malikhia', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 41, 'ono Getini ono Zera ono Gadaya', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 42, 'ono Getano ono Zima ono Zime''i', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 43, 'ono Yahata ono Gereso ono Lewi.', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 44, 'Ba talifusöra, iraono Merari, ba ba gabera la''iagö: Etano, ono Gisi ono Abidi', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 45, 'ono Malukhu ono Hazabia ono Gamasia,', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 46, 'ono Hilikia ono Gamisi', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 47, 'ono Mbani ono Zemeri ono Maheli ono Musi ono Merari ono Lewi.', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 48, 'Ba talifusöra, ono Lewi andrö, ba si no mufataro ba halöŵö andrö, fefu, ba nahia andrö, ba gosali Lowalangi.', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 49, 'Ba A''aroni ba ononia, ba same''e sumange ba naha wame''e sumange nitunu ba ba naha wanunu kumöyö, ba sangai halöŵö ba wondrege ni''amoni''ö, fefu, ba samaigi fameta horö Ndraono Gizeraeli, dali sibai nifakhoi Moze, enoni Lowalangi, khöra.[6]', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 50, 'Ba da''e nono Ga''aroni: Ononia Eleazari, ba Fineha nono da''ö, ba Abisua nono da''ö,', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 51, 'ba Buki nono da''ö, ba Usi nono da''ö, ba Seraya nono da''ö,', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 52, 'ba Merayoto nono da''ö, ba Amaria nono da''ö, ba Ahitubi nono da''ö,', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 53, 'ba Sadoki nono da''ö, ba Ahimasi nono da''ö.', '["MozIV 16:1","MozII 30:7; MozIII 16"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 54, 'Ba da''e nahiara, nibe''era osera, ba danöra: Ba nga''ötö Ga''aroni andrö, nga''ötö Gahati — me no ya''ira zi göna si a''a dahö-dahö[7] —', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 55, 'ba khöra labe''e Heberona ba danö mado Yuda, fabaya sabölö du''u, ö gurifö, si fasui ya''ia.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 56, 'Ba benua, tanö nowi, si faböbö ba mbanua andrö, awö halama soya khöra, ba khö Galebi andrö, ono Yefune, labe''e.[8]', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 57, 'Ba ba nga''ötö Ga''aroni labe''e mbanua saŵatö [zange''e] andrö, Heberona ba Libena, awö zabölö du''u si faböbö ba da''ö, ba Yatiri ba Esemoa, awö zabölö du''u ba ngai,', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 58, 'ba Holono, awö zabölö du''u ba ngai, ba Debiri, awö zabölö du''u ba ngai,', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 59, 'ba Asana, awö zabölö du''u ba ngai, ba Beti Zemesi, awö zabölö du''u ba ngai.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 60, 'Ba nilulu mado Mbeniyami, ba Geba, awö zabölö du''u khöra, ba Alemeti, awö zabölö du''u khöra ba Anatoti, awö zabölö du''u khöra. Banuara fefu, ba no feledölu, fabaya sabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 61, 'Ba ba nga''ötö Gahati, tanö bö''ö andrö, ba fulu lalulu banua fatalifusöta mado Geferayi ba mado Dano ba si matonga mado Manase, nilau dahö-dahö.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 62, 'Ba ba nga''ötö Gereso, ba watalifusöta khöra, ba feledölu lalulu banua mado Isasari ba mado Gaseri ba mado Manase ba Mbazana.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 63, 'Ba ba nga''ötö Merari, ba felendrua lalulu banua mado Rubeno ba mado Gado ba mado Zebuloni, nilau dahö-dahö.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 64, 'Si manö wanehe Ndraono Gizeraeli banua andrö, awö sabölö du''u ba zi fasui, ba nono Lewi.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 65, 'Mado Yuda ba mado Zimeoni ba mado Mbeniyami zanehe banua andrö, nitötöi mege, nilau dahö-dahö.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 66, 'Ba ba watalifusöta nga''ötö Gahati, ba ba mado Geferayi latema mbanua andrö, si göna dahö-dahö, wa khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 67, 'Banua saŵatö [zange''e] andrö, Siehema, labe''e khöra, fabaya zabölö du''u, si faböbö ba da''ö, ba hili mado Geferayi, ba Gezeri, awö zabölö du''u khöra,', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 68, 'ba Yokemea, awö zabölö du''u khöra, ba Beti Horona, awö zabölö du''u khöra,', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 69, 'ba Ayalona, awö zabölö du''u khöra, ba Gata Rimono, awö zabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 70, 'Ba nibe''e zi matonga mado manase, ba Aneri, awö zabölö du''u khöra, ba Yibelea, awö zabölö du''u khöra — ba watalifusöta nga''ötö Gahati, tanö bö''ö.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 71, 'Ba nitema nga''ötö Gereso ba zi matonga mado Manase, ba Golana, ba danö Mbazana, awö zabölö du''u khöra, ba Asaroti, awö zabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 72, 'Ba nibe''e mado Isasari, ba Kedesi, awö zabölö du''u khöra, ba Daberata, awö zabölö du''u khöra, ba Ramoti,', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 73, 'awö zabölö du''u khöra, ba Anemi, awö zabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 74, 'Ba nibe''e mado Gaseri, ba Masala, awö zabölö du''u khöra, ba Abedono, awö zabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 75, 'Ba Hukoko, awö zabölö du''u khöra, ba Rehobo, awö zabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 76, 'Ba nibe''e mado Nafetali, ba Kedesi, ba Galili, awö zabölö du''u khöra, ba Hamota, awö zabölö du''u khöra, ba Kiriata''i, awö zabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 77, 'Ba nitema nga''ötö Merari, tanö bö''ö, ba mado Zebuloni, ba Rimono, awö zabölö du''u khöra, ba Tabora, awö zabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 78, 'Ba yefo Yoridano, ba gamaudu Yerikho, ba latehe khöra mado Rubeno, ba Beseri, ba danö si mate, awö zabölö du''u khöra, ba Yasa, awö zabölö du''u khöra, mado Rubeno, ba Beseri, ba danö si mate, awö zabölö du''u khöra, ba Yasa, awö zabölö du''u khöra,', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 79, 'ba Kedemoti, awö zabölö du''u khöra, ba Mefa''ata, awö zabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 80, 'Ba nibe''e mado Gado, ba Ramoti ba danö Gileadi, awö zabölö du''u khöra, ba Mahana''i, awö zabölö du''u khöra,', '["Yos 21","Yos 21:12"]', NULL),
  (3475086, 'OT', 'Nga''ötö I', 6, 81, 'ba Hesibona, awö zabölö du''u khöra, ba Yaseri, awö sabölö du''u khöra.', '["Yos 21","Yos 21:12"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 1, 'Ba ono Isasari, ba Tola ba Fua ba Yasubi ba Simerono, öfa.[1]', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 2, 'Ba ono Dola, ba Usi ba Refaya ba ba Yerieli ba Yahema''i ba Yibisama ba Samueli; högö ba ngafu nga''ötö Dola, niha sabölö, ba watalifusöta khöra. Fa''atora, me luo Dawido, ba no 22.600.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 3, 'Ba ono Usi, ba Yisiraya, ba ono Yisiraya ba Mikhaeli ba Obadia ba Yoeli ba Yisia, lima fefu, högö.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 4, 'Ba awöra zabölö, sato, ba watalifusöta khöra ba ba ngafura: 36.000; Noa sa oya khöra ndra alawe, awö ndraono.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 5, 'Ba iwara, nga''ötö Isasari fefu, ba no niha sabölö: ba no 87.000, orudua.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 6, 'Ba ono Mbeniyami, ba Bela ba Bekheri ba Yediaeli, tölu.[2]', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 7, 'Ba ono Mbela, ba Esibona ba Usi ba Usieli ba Yerimoto ba Iri, lima, hogö ngafu, niha sabölö; 22.034 fefu, ni''ofaya.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 8, 'Ba ono Mbekheri, ba Semira ba Yoasi ba Eliezeri ba Eliunai ba Omeri ba Yeremoto ba Abia ba Anatoti ba Alemeti; oi ono Mbekheri da''ö.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 9, 'Ba fa''atora, fatalifusöta khöra, ba högö ngafu, niha sabölö, ba no 20.200.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 10, 'Ba ono Yediaeli, ba Bilihana, ba ono Mbilihana, ba Yeusi ba Beniyami ba Ehudi ba Kena''ana ba Setano ba Tarisi ba Ahisahara.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 11, 'Oi ono Yediaeli da''ö, högö ngafu, sabölö, 17.200, solohe baluse.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 12, 'Ba ono Iri Zufimi ba Hufimi: ba ono Gaheri Husimi.', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 13, 'Ba ono Nafetali, ba Yasieli ba Guni ba Yeseri ba Salumi, ma''uwu Mbiliha andrö.[3]', '["MozI 46:13; MozIV 26,23:24","Faigi 8:1,2; MozI 46:21","MozI 46:24"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475087, 'OT', 'Nga''ötö I', 7, 14, 'Ba ono Manase, ba Azerieli, ononia khö wo''omonia; ba mo''ono ia ono ndrongania ba döi, Dawa Garamo, Makhiro, ama Gileadi.[4]', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 15, 'Ba Makhiro andrö, ba ihalö dafifusö ndra Hufimi Sufimi, Ma''akha. Ba ono Manase si sambua, ba Selofadi, ba ono alawe nono Zelofadi.[5]', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 16, 'Ba mo''ono Ma''akha, fo''omo Makhiro, ono Matua, ba Feresi ibe''e töi nononia. Ba Seresi döi nakhinia, ba ono da''ö, ba Olama ba Rekemi.', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 17, 'Ba ono Olama, ba Bedana. Da''ö nga''ötö Gileadi, ono Makhiro ono Manase.', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 18, 'Ba mo''ono nakhi Makhiro, ira alawe, Hamolekheti, Isihodi ba Abiezeri ba Mahela döi nononia.', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 19, 'Ba ono Zemida, ba Ahiana ba Sekhema ba Likehi ba Aniama.', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 20, 'Ba ono Geferayi, ba Sutela; ba ono da''ö, ba Beredi, ba ono da''ö, ba Tahata, ba ono da''ö, ba Eleada, ba ono da''ö, ba Tahata [zui],[6]', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 21, 'ba ono da''ö, ba Sabada, ba ono da''ö, ba Sutela ba Ezeri ba Eleadi; ba labunu ira banua Gata andrö, niha si tohöna ba danö, me no möi misi tou ira, ba worabu uriföra.', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 22, 'Ba ara manö abu dödö duara Eferayi, ba so ndra talifusönia, ba wondrara tödönia.', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 23, 'Ba orudu ia khö ndrongania ba manabina ba mo''ono, ono matua. Ba ibe''e töi nononia andrö Mberia (ba wa''abu dödö), me no si tumbu barö wa''abu dödö andrö khöra.', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 24, 'Ba ononia alawe, ba Se''era; da''ö zanaru''ö banua Mbeti Horona tou ba Beti Horona yaŵa ba Useni Ze''era.', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 25, 'Ba ono Mberia, ba Refa ba Resefi. Ba ono Refa, ba Tela, ba ono da''ö, ba Tahana,', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 26, 'ba ono da''ö, ba Laedana, ba ono da''ö, ba Amihudi, ba ono da''ö, ba Elisama,[7]', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 27, 'ba ono da''ö, ba Nuni, ba ono da''ö, ba Yosua.[8]', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 28, 'Ba tana khöra tanö, nahiara, ba Betieli, fabaya halama soya khöra, ba tanö ba gatumbukha luo, ba Na''arana, ba tanö ba gaekhula, ba Geseri, fabaya halama soya khöra, ba baero, ö, ba Sikhema, fabaya halama soya khöra, irugi Aiya, fabaya halama soya khöra.[9]', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 29, 'Ba ba nola mado Manase, ba Beti Ze''ana, fabaya halama soya khöra, ba Ta''anakha, fabaya halama soya khöra, ba Megido, fabaya halama soya khöra, ba Dora, fabaya halama soya khöra. Da''ö nahia ndraono Yosefo, ono Gizeraeli.[10]', '["MozIV 26:29–33","MozIV 27:1","MozIV 26:35","MozIV 1:10","MozIV 13:8","Yos 16:1,10","Yos 17:11"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 30, 'Ba ono Gaseri, ba Yimina ba Yisiwa ba Yisiwi ba Beria ba talifusöra alawe Sera.[11]', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 31, 'Ba ono Mberia, ba Heberi ba Malikhieli, da''ö nama Mbirisayiti.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 32, 'Ba ono Heberi, ba Yafeleti ba Semeri ba Hotama ba talifusöra alawe Sua.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 33, 'Ba ono Yafeleti, ba Fasakha ba Bimehala ba Asiwata; da''ö nono Yafeleti andrö.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 34, 'Ba ono Zemeri, ba Ahi ba Roga ba Huba ba Aramo.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 35, 'Ba ono dalifusönia Helemi, ba Sofa ba Yimina ba Selesi ba Amala.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 36, 'Ba ono Zofa, ba Sua ba Haneferi ba Suala ba Beri ba Yimera.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 37, 'Ba Beseri ba Hodo ba Sama ba Silisa ba Yiterana ba Be''era.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 38, 'Ba ono Yeteri, ba Yefune ba Fisifa ba Ara.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 39, 'Ba ono Ola, ba Arahi ba Hanieli ba Risia.', '["MozI 46:17"]', NULL),
  (3475087, 'OT', 'Nga''ötö I', 7, 40, 'Oi ono Gaseri da''ö, högö ngafu, nitutuyu, sabölö, högö zalaŵa. Ba fa''ato ni''ofaya khöra, solohe baluse, ba no 26.000.', '["MozI 46:17"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 1, 'Ba ono Mbeniyami, ba Bela, si a''a, ba Asebeli ganete da''ö, ba Ara ganete da''ö,[1]', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 2, 'ba Noha ganete zi tölu, ba Rafa ganete zi öfa.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 3, 'Ba ono Mbela, ba Adara ba Gera ba Abihudi,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 4, 'ba Abisua ba Na''ama ba Ahoa,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 5, 'ba Gera ba Sefufana ba Huramo.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 6, 'Ba da''e nono Gehudi (högö ngafu ba mbanua Geba, nifawu''a, ni''ohe ba Manahata,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 7, 'Na''ama ba Ahia ba Gera; da''ö zamawu''a): Usa ba Ahihudi.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 8, 'Ba mo''ono Zaharai ba danö Ndraono Moabi, me no itibo''ö ndrongania Husi ba Ba''ara.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 9, 'Mo''ono ia khö wo''omonia Hodesi: Yobababa Sibia ba Mesa ba Malakama,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 10, 'ba Yeusi ba Sokhia ba Mirima. Da''ö nononia, högö ngafu.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 11, 'Ba ononia khö Husi, ba Abitubu ba Elifa''ali.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 12, 'Ba ono Gelifa''ali, ba Eberi ba Miseama ba Semeri. Da''ö zanaru''ö Gono ba Lodi, awö halama soya khöra.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 13, 'Ba Beria ba Sema (högö ngafu ba mbanua Nayalona da''ö; ya''ira zanimba banua Gata andrö), ba talifösönia Elifa''ali,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 14, 'ba Sasaki ba Yeremoto.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 15, 'Ba Sebadia ba Aradi ba Ederi,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 16, 'ba Mikhaeli ba Yisifa ba Yoha, nono Mberia.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 17, 'Ba Sebadia ba Mesula ba Hisiki ba Heberi,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 18, 'ba Yisimerai ba Yisilia ba Yobaba, nono Gelifa''ali.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 19, 'Ba Yakimi ba Sikhiri ba Sabidi,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 20, 'ba Elienai ba Sileta''i ba Elieli', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 21, 'ba Adaya ba Beraya ba Simerata nono Zime''i.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 22, 'Ba Yisifana ba Eberi ba Elieli,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 23, 'ba Abedono ba Sikhiri ba Hanamo,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 24, 'ba Hanania ba Elama ba Androtia,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 25, 'ba Yifideya ba Fenueli, nono Zasaki.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 26, 'Ba Samaserai ba Seharia ba Atalia,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 27, 'Ba Yaresia ba Elia ba Sikhiri, nono Yerohamo.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 28, 'Högö ngafu da''ö, ba watalifusöta khöra, no salaŵa; ba Yeruzalema so ira.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 29, 'Ba si so ba Gibeona ba tua Gibeona andrö, Yegueli, ba töi wo''omonia, ba Ma''akha.[2]', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 30, 'Ba si a''a nononia, ba Abedono, ba itete, ba Suri ba Kisi ba Ba''ali ba Neri ba Nadabi,', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 31, 'ba Gedoro ba Ahio ba Sekheri.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 32, 'Ba ono Mikeloto, ba Simea. Ba ba gamaudu dalifusöra so ira, ba Yeruzalema, awö dalifusöra andrö.', '["MozI 46:21","Faigi 9:35–44"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 33, 'Ba ono Neri, ba Kisi, ba ono Gisi, ba Saulo, ba ono Zaulo, ba Yonata ba Malikhisua ba Abinadabi ba Eseba''ali.[3]', '["SamI 14:51","Faigi 12:2"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 34, 'Ba ono Yonata, ba Meriba''ali ba ono Meriba''ali, ba Mikha.', '["SamI 14:51","Faigi 12:2"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 35, 'Ba ono Mikha andrö, ba Fitono ba Melekhi ba Tarea ba Ahasi.', '["SamI 14:51","Faigi 12:2"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 36, 'Ba ono Gahasi, ba Yoada, ba ono Yoada, ba Alemeti ba Asimaweti ba Simeri. Ba ono Zimeri, ba Mosa.', '["SamI 14:51","Faigi 12:2"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 37, 'Ba ono Mosa, ba Binea; ba Rafa nono da''ö, ba Eleasa nono da''ö, ba Aseli nono da''ö.', '["SamI 14:51","Faigi 12:2"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 38, 'Ba önö nono Gaseli, ono matua; Aserika ba Bokhoru ba Sima''eli ba Searia ba Obadia ba Hanano döira. Oi ono Gaseli da''ö.', '["SamI 14:51","Faigi 12:2"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 39, 'Ba ono dalifusönia Eseki, ba Olama, si a''a, ba itete, ba Ye''usi, ba itete, ba Elifeleti.', '["SamI 14:51","Faigi 12:2"]', NULL),
  (3475088, 'OT', 'Nga''ötö I', 8, 40, 'Ba ono Olama, ba no niha sabölö, si no to''ölö ba wafanata, ba ato sibai nga''ötöra, 150; Oi mado Mbeniyami da''ö fefu.[4]', '["SamI 14:51","Faigi 12:2"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 1, 'Dozi Iraono Gizeraeli, ba labe''e ba zura; ba hiza, ba zura hikaya razo Ndraono Gizeraeli so döira. Ba börö lalö mado Yuda, wa te''oloi''ö ba Mbabeli ira.[1]', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 2, 'Ba si so ba da''ö föna, ba dana khöra tanö, ba mbanuara andrö, ba no Iraono Gizeraeli, ono mbanua, ere ba Ono Lewi ba sangai halöŵö ba gosali.[2]', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 3, 'Banua Yeruzalema andrö, ba mado Yuda ba mado Mbeniyami ba mado Geferayi ba mado Manase:[3]', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 4, 'Uta''i, ono Gamihudi ono Omeri ono Imeri ono Mbani, föfö nga''ötö Weresi andrö, ono Yuda.', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 5, 'Ba föfö nga''ötö Zela, ba Asaya, si a''a, ba ononia.', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 6, 'Ba föfö nga''ötö Zera, ba Yegueli, ba talifusöra, 690.', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 7, 'Ba mado Mbeniyami, ba Salu, ono Mesula ono Hodawaya ono Hasenua.', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 8, 'Ba baero ö, ba Yibeneya, ono Yerohamo, ba Ela, ono Usi ono Mikhiri, ba Mesula, ono Zefatia ono Regueli ono Yibeniya,', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 9, 'ba iwara, ba watalifusöta khöra, 956 fefu. Högö ngafu da''ö fefu, ba ngafura andrö.', '["RazII 24:15,16","Yos 9:23; Eser 8:20","Neh 11:3–19"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 10, 'Ba ere, ba Yedaya ba Yoyaribi ba Yakhino,', '["Faigi 5:39","Faigi 2:54"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 11, 'ba Asaria, ono Hilikia ono Mesula ono Zadoki ono Merayoto ono Gahitubi, salaŵa ba gosali Lowalangi.[4]', '["Faigi 5:39","Faigi 2:54"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 12, 'Ba baero ö, ba Adaya, ono Yerohamo ono Wasuri ono Malakhia ono Maesai ono Gadieli ono Yasera ono Mesula ono Mesilemiti ono Imeri,', '["Faigi 5:39","Faigi 2:54"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 13, 'ba talifusöra, högö ngafura, 1760 fefu, niha si faduhu dödöda, ba wangaira halöŵöra, ba gosali Lowalangi.', '["Faigi 5:39","Faigi 2:54"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 14, 'Ba Ono Lewi, ba Semaya, ono Hasubu ono Asirika ono Hasabia, föfö nga''ötö Merari.', '["Faigi 5:39","Faigi 2:54"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 15, 'Ba baero ö, ba Bakabakara ba Heresi ba Galala ba Matania, ono Mikha ono Zikhiri ono Gasafo.', '["Faigi 5:39","Faigi 2:54"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 16, 'Ba Obadia, ono Zemaya ono Galala ono Yedutuno, ba Berekhia, ono Asa ono Elikana, si so ba mbanua Netofa andrö.[5]', '["Faigi 5:39","Faigi 2:54"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 17, 'Ba sanaro ba mbawandruhö, ba Salumi ba Akubu ba Talamono ba Ahimana ba talifusöra; högö Zalumi, irege ma''ökhö andre', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 18, 'sanaro ia ba mbawandruhö zalaŵa andrö, tanö ba gatumbukha luo. Da''ö zanaro ba mbawandruhö, ba nahia Nono Lewi andrö.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 19, 'Ba Salumi andrö, ono Goresi ono Gebiasafo ono Gora, ba talifusönia, si sawu ya''ira, nga''ötö Gora, ba no sangai-ngai halöŵö andrö, wanaro toyo mbawandruhö nose, si mane ira tuara föna, si no sanaro göi ba mbawandruhö ba nahia Yehowa,[6]', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 20, 'ba Fineha andrö, ono Geleazari, ba no salaŵara, ba götö föna (Yamutolo ia Yehowa!)[7]', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 21, 'Ba Sakharia andrö, ono Mezelemia, ba no sanaro ba mbawandruhö ba nose wama''ele''ö.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 22, 'Ba ya''ira fefu, si no mututuyu, ba wanaro toyo mbawandruhö, ba no 212; ba ba mbanuara latanö ba zura nga''ötö döira. No Dawido ba Samueli sangi''ila andrö zamataro ya''ira, ba halöŵöra andrö.[8]', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 23, 'Ya''ira ba onora, ba ba zinga mbawandruhö nahia Yehowa so, ba zinga mbawandruhö nahia ose andrö, ba wanaro. 24öfa nahia, zi so sanaro andrö: tanö ba gatumbukha luo ba tanö ba gaekhula ba tanö yöu ba tanö raya.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 25, 'Ba talifusöra ba mbanua side-ide khöra, ba fitufitu bongi wa''ara möi-möi ira miyomo, ba wanolo ya''ira.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 26, 'Ba satua zanaro ba mba wandruhö andrö, si daöfa, ba lö''ö sa aefa-aefa ba halöŵöra, fadoro. Da''ö Nono Lewi andrö. Ba nifaigi-faigira göi mbate''e andrö, fabaya nihöna andrö, ba gosali Lowalangi;', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 27, 'ba ba zi bongi, ba lö labulö''ö ira ba zi fasui gosali Lowalangi. Me no ya''ira zanaro ba zi bongi, ba ero na moluo, ba laku mbawandruhö.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 28, 'Ba samaigi-maigi fakake ba wame''e sumange ösa, ira; la''ofaya, na la''ohe bakha ba na lafuli baero.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 29, 'Ba so göi ösa nifataro samaigi-maigi gama-gama andrö, gama-gama ni''amoni''ö fefu, ba hamo si sökhi andrö ba agu ba fanikha ba rembaremba.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 30, 'Ba ere ösa, ba no nifataro ba wamali''ö fanikha samohua rembaremba andrö.[9]', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 31, 'Ba Matitia andrö, Ono Lewi, ono ma''uwu Gora andrö, Salumi, ono si a''a, ba no nifataro ba wogore kue.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 32, 'Ba ma''uwu Gahati ösa, iwara, ba no nifataro ba wangali roti nifaigi-faigi andrö, ero na luo sabato.[10]', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 33, 'Da''ö mege zanunö andrö, högö ngafu ba Nono Lewi; nahiara mbate''e andrö, lö halöŵöra bö''ö, me no bongi ma''ökhö lö aefa-aefa ira ba halöŵöra andrö.[11]', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 34, 'Da''ö högö ngafu andrö ba Nono Lewi, ba watalifusöta andrö khöra, amaedola wurugö. Ba Yeruzalema so ira.', '["MozIV 4:18–20","MozIV 25:7–13","SamI 9:9,11","MozII 30:23–25","MozIII 24:5,8","Ayati 14–16"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475089, 'OT', 'Nga''ötö I', 9, 35, 'Ba si so ba Gibeona, ba tua Gibeona andrö, Yeieli, ba töi wo''omonia, ba Ma''akha.[12]', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 36, 'Ba ononia si a''a, ba Abedono, ba [itete ba] Suri ba Kisi ba Ba''ali ba Neri ba Nadabi,', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 37, 'ba Gedoro ba Ahio ba Sakharia ba Mikeloto.', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 38, 'Ba ono Mikeloto, ba Simea. Ba ya''ira göi, ba ba gamaudu dalifusöra so, ba Yeruzalema, awö dalifusöra andrö.', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 39, 'Ba ono Neri, ba Kisi, ba ono Gisi, ba Saulo, ba ono Zaulo, ba Yonata, ba Malikhisua ba Abinadabi ba Eseba''ali.', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 40, 'Ba ono Yonata, ba Meriba''ali, ba ono Meriba''ali, ba Mikha.', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 41, 'Ba ono Mikha, ba Fitono ba Melekhi ba Tarea ba Ahasi.', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 42, 'Ba ono Gahasi, ba Yaera, ba ono Yaera, ba Alemeti ba Asimaweti ba Simeri; ba ono Zimeri, ba Mosa.', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 43, 'Ba ono Mosa, ba Binea. Ba ono da''ö, ba Refaya, ba ono da''ö, ba Eleasa, ba ono da''ö, ba Aseli.', '["Faigi 8:29–38"]', NULL),
  (3475089, 'OT', 'Nga''ötö I', 9, 44, 'Ba önö nono Gaseli, ono matua, Aserika ba Bokhoru ba Sima''eli ba Searia ba Obadia ba Hanano döira. Da''ö nono Gaseli andrö.', '["Faigi 8:29–38"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 1, 'Ba no lalau ba Ndraono Gizeraeli Dawa Wilisiti;[1] ba no moloi Ndraono Gizeraeli labe''e Dawa Wilisiti, ba hiza tou ba danö nibunu ba hili Giliboa.', '["Faigi göi SamI 31"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 2, 'Ba lö laböhöli ndra Saulo ononia Dawa Wilisiti, labunu sa''ae nono Zaulo, Yonata ba Abinadabi ba Malikhisua.', '["Faigi göi SamI 31"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 3, 'Ba me laforege khö Zaulo, me na la''ila ia si fafana, ba ata''u sibai ia zi fafana andrö.', '["Faigi göi SamI 31"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 4, 'Ba imane khö zolohe fangönania: Sobi zi''öliu ba fahö ndra''odo, fa böi möi dania zi lö muboto andrö, ba wango''aya ya''o! Ba lö edöna zolohe fangönania, me ata''u ia. Ba ituyu wöda Saulo, ba ilangögö.', '["Faigi göi SamI 31"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 5, 'Ba me i''ila solohe fangönania, no mate Zaulo ba ilangögö göi wödania, ba mate ia göi.', '["Faigi göi SamI 31"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 6, 'Si manö wa''amate Zaulo ba ononia si datölu, si samba omo ya''ira; endronga mate ira.', '["Faigi göi SamI 31"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 7, 'Ba me larongo Iraono Gizeraeli fefu ba ndraso, no moloi Ndraono Gizeraeli ba no mate Zaulo, fabaya ononia, ba laröi mbanuara, moloi. Ba so Ndrawa Wilisiti, ba la''okhögö nahiara.', '["Faigi göi SamI 31"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 8, 'Ba mahemolu ö, ba so Ndrawa Wilisiti, ba wangai gama-gama nibunu, ba hiza tou Zaulo ba iraononia si datölu, ba hili Giliboa.', '["SamII 2:5","SamI 15:11; 28:8"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 9, 'Ba lahalö gama-gamania, ba la''ohe högönia ba fangönania ba lafatenge zanöröi tanö Ndrawa Wilisiti, ba wangombakha ba nadura ba ba niha sato turia wemönara andrö.', '["SamII 2:5","SamI 15:11; 28:8"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 10, 'Ba fangönania, ba labe''e ba gosali Lowalangira andrö, ba högönia, ba la''osö ba nomo Dagono.', '["SamII 2:5","SamI 15:11; 28:8"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 11, 'Ba me larongo fefu nilau Ndrawa Wilisiti khö Zaulo banua Yabesi ba danö Gileadi, dozi,', '["SamII 2:5","SamI 15:11; 28:8"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 12, 'ba maoso zabölöra fefu, lahalö mboto Zaulo ba boto ndraononia, la''ohe ba Yabesi. Ba lako''o mbotora ba mbörö manawa andrö ba Yabesi, ba mamoni ba gö ira, fitu bongi.[2]', '["SamII 2:5","SamI 15:11; 28:8"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 13, 'Tobali mate Zaulo ba horönia khö Yehowa, me lö ni''o''önia oroisa Yehowa ba me no isofu ba mbekhu, ba wama''ele''ö khönia lala,[3]', '["SamII 2:5","SamI 15:11; 28:8"]', NULL),
  (3475090, 'OT', 'Nga''ötö I', 10, 14, 'me lö nisofunia khö Yehowa fama''ele''ö. Andrö wa ibe''e mate ia [Yehowa], ba fa''arazo, ba ibe''e khö Dawido, ono Giza''i.', '["SamII 2:5","SamI 15:11; 28:8"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 1, 'Ba owulo Ndraono Gizeraeli fefu, khö Dawido,[1] lamane khönia: Föfö nösiu ndra''aga![2]', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 2, 'Me föna sa''ae, me razo na Zaulo, ba no ya''ugö zolohe Iraono Gizeraeli, ba wasuwöta, ba ya''ugö göi zolohe mangawuli; ba noa göi imane khöu Lowalangiu, Yohowa: Ya''ugö dania zokubaloi banuagu Iraono Gizeraeli, ba razora ndra''ugö!', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 3, 'Ba möi khö razo ba Heberona, zatua Ndraono Gizeraeli fefu, ba fawu''u li khöra Dawido, ba Heberona, ba zanehe Yehowa; ba labayo ni razo Ndraono Gizeraeli Dawido, dali goroisa Yehowa andrö, nifa''ema Zamueli.[3]', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 4, 'Ba isaŵa Yeruzalema Dawido, awö Ndraono Gizeraeli fefu — Yeruzalema Yebusi andrö; Iraono Yebusi, niha si tohöna ba danö, zi so ba da''ö.', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 5, 'Ba lamane khö Dawido banua Yebusi andrö: Lö''ö sa atu''a''ö ba da''e! Ba iforege Dawido, ba atu''a ia ba hati Siona, ya''ia mbanua Dawido andrö.', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 6, 'Ba da''ö imane Dawido: Ha niha zi oföna mangalani Iraono Yebusi, ba labe''e kumandra ba solohe! Ba si oföna möi yaŵa, ba Yoabi, ono Zeruya, ba tobali kumandra ia.', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 7, 'Ba ba hati andrö i''iagö sa''ae Dawido, andrö wa labe''e töinia mbanua Dawido.', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 8, 'Ba i''aro''ö mbanua andrö, fasui, i''otarai Milo andrö, fasui manö; ba Yoabi zangaro bö''önia, yomo ba mbanua.', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 9, 'Ba itugu tedou wa''abölö Dawido, itolo ia Yehowa ngahönö.', '["Ayati 1–9: SamII 5:1–5","MozI 29:14","SamI 16:13,12"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 10, 'Ba da''e zalaŵa ba zabölö andrö khö Dawido,[4] sanolo sibai ya''ia, me tobali razo ia, awö Ndraono Gizeraeli fefu, ba wamataro razo ya''ia, dali goroisa Yehowa ba Ndraono Gizeraeli.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 11, 'Ba da''e wa''ato zabölö andrö khö Dawido: Yasobea, ono Hakhamoni, högö zi datölu andrö. Ilau dohonia, ba 300 zi mate, endronga.[5]', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 12, 'Ba fanetenia, ba Eleazari, ono Dodo, ma''uwu Gahohi; samösa ia ba zi datölu, sabölö.[6]', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 13, 'Awö Dawido ia ba Wasedami, me no owulo Ndrawa Wilisiti ba wasöndrata. Ba so ba da''ö mbolo nowi, gandru. Ba me moloi zato, labe''e Dawa Wilisiti,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 14, 'ba la''agö dalu nowi, lafadöni [ba nemali] ba lalau ba Ndrawa Wilisiti, ba tobali femöna sebua, itolo Yehowa.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 15, 'Ba samuza maökhö, ba datölu zi möi mitou khö Dawido, ba hati kara andrö, ba hati Adula, datölu salaŵa andrö, ba zi 30, me no ba zalo''o, ba Refa''i, labe''e golombaseŵara Dawa Wilisiti.[7]', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 16, 'Ba hati andrö so Dawido, me luo da''ö, ba ba Mbetilekhema so Ndrawa Wilisiti sato.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 17, 'Ba omasi Dawido [nidanö], ba imane: Ha niha zana''u gögu idanö, ba mba''a andrö, ba zinga mbawa göli Mbetilekhema?', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 18, 'Ba latörö golombaseŵa Ndrawa Wilisiti si datölu latimba ira, ba lata''u nidanö ba mba''a andrö, ba zinga mbawa göli Mbetilekhema, ba la''ohe khö Dawido. Ba lö edöna ibadu Dawido, iduwagö [sumange] khö Yehowa, imane:', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 19, 'Yamutenaŵa ndra''o Lowalangigu, fa böi ulau zi manö! Hadia, ubadu ndro zabölö andre, si no mangositengagö nosora, me möi ira? Lö''ö sa ba dödöra nosora, wolohe ya''ia ba da''e! — ba lö''ö manö ibadu. Da''ö nilau zabölö andrö, si datölu.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 20, 'Ba Abiza''i, akhi Yoabi, ba no högö ba zi tölu ngafulu andrö. Ilau dohonia, ba 300 zi mate, ba no sebua turia ia, ba zi 30 andrö.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 21, 'Ba zi 30, ba no sebua töi ia, ba ya''ia zolohe ya''ira, ba ba zi da tölu andrö, ba lö falaŵalaŵa ia.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 22, 'Ba Benaya, ono Yehoyada, niha sabölö, sebua ilau, banua Gabase''eli. Ya''ia zamunu ono Garieli, Iraono Moabi, si darua. Ba samuza ma''ökhö, me so deu si baku, ba ibunu zingo, si tou ba mba''a.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 23, 'Ba ibunu göi Ndrawa Miserayi, niha sebua sibai, lima hela. Sara doho ba danga Ndrawa Miserayi andrö, sezai mawö; ba ha si''o i''ohe khönia Benaya; ba ira''u doho andrö, ba danga Ndrawa Miserayi andrö, ba tohonia andrö ibe''e famununia.[8]', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 24, 'Da''ö nilau Mbenaya, ono Yehoyada, ba sebua turia ia ba zi 30 sabölö andrö.[9]', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 25, 'Ba zi tölu ngafulu, ba no sebua töi ia, ba ba zi datölu, ba lö falaŵalaŵa ia. Ba ibe''e högö wazuri ia Dawido, högö wazuri si lö aefa-aefa khönia.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 26, 'Ba sabölö andrö, ba Azaheli, akhi Yoabi, ba Elihana, ono Dodo, banua Mbetilekhema,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 27, 'ba Samoti, banua Haroro, ba Helesi, banua Walono,[10]', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 28, 'ba Ira, ono Ike, banua Dekoa, ba Abiezeri, banua Ganatoti, ba Sibekhai,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 29, 'banua Husa, ba Ilai,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 30, 'banua Gahoho, ba Maharai, banua Netofa, ba Heledi, ono Mba''ana,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 31, 'banua Netofa, ba Ita''i, ono Ribai, banua Gibea, ba mado Mbeniyami, ba Benaya, banua Wireato, ba Hurai,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 32, 'banua Nahale-Gasi ba Abieli, banua Garaba, ba Asimaweti,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 33, 'banua Mbakuri, ba Eliaba, banua Za''alabo, ba Hasemi,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 34, 'banua Gizono, ba Yonata, ono Zage,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 35, 'banua Harara, ba Ahiamo, ono Zakhara, banua Harara, ba Elifali, ono Guri,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 36, 'ba Heferi, banua Mekhera, ba Ahia,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 37, 'banua Walono, ba Hesero, banua Garemeli, ba Na''arai, ono Esibai.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 38, 'Ba Yoeli, talifusö Natano, ba Mibihara, ono Hegeri,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 39, 'ba Seleki, Iraono Gamoni, ba Naharai, banua Mbe''eroti, solohe fangöna khö Yoabi ono Zeruya,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 40, 'ba Ira, banua Yatiri, ba Garebi, banua Yatiri.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 41, 'Ba Uria, Iraono Kheti, ba Sabada, ono Gahelai,[11]', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 42, 'ba Adina, ono Zisa, mado Rubeno, salaŵa ba mado Rubeno, ba tölu ngafulu nawönia,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 43, 'ba Hanano, ono Ma''akha, ba Yozafati,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 44, 'banua Metene, ba Usia, banua Gasehera, ba Sama ba Yeieli, ono Hotama, banua Garuri,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 45, 'ba Yediaeli, ono Zimeri, ba talifusönia Yoha,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 46, 'banua Disi, ba Elieli, banua Mahana''i, ba Yeribai ba Yosawia, ono Gelina''ama, ba Yitema, Iraono Moabi,', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475091, 'OT', 'Nga''ötö I', 11, 47, 'ba Elieli ba Obedi ba Ya''asieli, banua Mesobaya.', '["Ayati 10–41: SamII 23:8–39","Faigi 27:2","Faigi 27:4","SamI 22:1","SamI 17:7,40,51","Faigi 27:5,6","Faigi 27:8,10","SamII 11:3"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 1, 'Ba da''ö zi möi awö Dawido ba Zikelagi, me no moloi ia ibe''e Saulo, ono Gisi. Föfö zabölö andrö göi ira, sanolo ba wasöndrata,[1]', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 2, 'solohe fana, ba si no to''ölö ba waribosa, he kambölö ba he kabera, ba he zui ba wafanata. Iwa Zaulo andrö, mado Mbeniyami, ba[2]', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 3, 'Ahieseri, högö, ba Yoasi, iraono Hasema''a, banua Gibea, ba Yesieli ba Feleti, iraono Gasimaweti, ba Berakha ba Yehu, banua Ganatoti.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 4, 'Ba Yisimaya, banua Gibeona, sabölö ba zi tölu ngafulu andrö ba solohe ya''ira; ba Yeremia ba Yahasieli ba Yohanano ba Yosabada, banua Gedera.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 5, 'Ba Eluzai ba Yerimoto ba Bealia ba Semaria ba Sefatia, banua Harifi;', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 6, 'ba Elikana, ba Yisiya ba Asare''eli ba Yuzeri ba Yasobeamo, ma''uwu Gora.[3]', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 7, 'Ba Yula ba Sebadia, iraono Yerohamo, banua Gedoro.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 8, 'Ba mado Gado, sanaŵa Dawido — ba hatinia andrö, ba danö si mate — niha sabölö, si no mangaro, ba wasöndrata, solohe baluse ba toho, hulö zingo wamaigida, ba no saoha ahe, si mane nago ba hili:[4]', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 9, 'Ya''ia Geseri, högö, ba fanetenia, ba Obadia, ba fanete, ba Eliabi,', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 10, 'ba fanete, ba Misimana, ba fanete,', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 11, 'ba Yeremia, ba fanete, ba Ata''i,', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 12, 'ba fanete, ba Elieli, ba fanete, ba Yohanano, ba fanete, ba Elisabada,', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 13, 'ba fanete, ba Yeremia, ba fanete, ba Makhabanai.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 14, 'Da''ö mado Gado; side-idera, ba ilaŵa zi otu, ba sabölöra, ba hönö ilaŵa.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 15, 'Da''ö zangötö Yoridano, ba mbaŵa si föföna, me no afönu ngöfi, ba same''e moloi banua ba ndraso fefu, tanö ba gatumbukha luo ba tanö ba gaekhula.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 16, 'Ba so göi ösa mado Mbeniyami, awö mado Yuda, sanaŵa Dawido, ba hati andrö.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 17, 'Ba möi tou Dawido, i''ondrasi ira, humede ia khöra, imane: Na ba wa''atulö möi ami khögu, ba wanolo ya''odo, ba data''osara''ö dödöda; ba na ba wemanga mböligu, ba zi fa''udu khögu, möi ami, he ŵa''ae lö lalögu, si togule ba dangagu, ba yamufaigi Lowalangi ndra tuada, ba yamufatörö huku!', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 18, 'Ba ifarou Gamasai, högö zi 30, Eheha, ba imane: "Khöu ndra''aga, ya''ugö Dawido, awöu, ya''ugö, ono Giza''i! Ya ahowu, ya ahowu ndra''ugö, ba ya ahowu zanolo ya''ugö; noa sa itolo''ö Lowalangiu!" Ba itema ira Dawido, ba ifataro solohe sabölö andrö khönia.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 19, 'Ba mado Manase ösa, sanaŵa Dawido, me möi ia awö Ndrawa Wilisiti, me lasuwö Zaulo ba lö''ö sa latolo Ndrawa Wilisiti, lafofanö sa''ae Dawido Dawa Wilisiti, me no mamagölö ira, lamane: Ma isaŵa zokhö ya''ia, Saulo, ba möi fa''aetu mbagida.[5]', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 20, 'Ba me isaŵa Zikelagi, ba si möi khönia mado Manase, ba Adana ba Yosabada ba Yediaeli ba Mikhaeli ba Yosabada [na] ba Elihu ba Sileta''i, högö ngahönö mado Manase.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 21, 'Ba latolo Dawido ba nemali andrö; noa sa sabölö ira fefu, ba tebe''e solohe sato ira.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 22, 'Ero ma''ökhö sa so zanaŵa Dawido, ba wanolo ya''ia, irege ato sibai khönia zabölö, hulö si mane sabölö khö Lowalangi.', '["SamI 27:6","Faigi 8:40","Faigi 25:18","SamII 2:18","SamI 29:4"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 23, 'Ba da''e wa''ato högö zi möi fasuwö, si no mangaro, si möi khö Dawido, ba Heberona, ba wama''ema khönia fa''arazo Zaulo andrö, dali goroisa Yehowa:', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 24, 'Mado Yuda, solohe baluse ba toho, si no mangaro ba wasuwöta, ba no 6.800.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 25, 'Ba mado Zimeoni, ba 7.100 zabölö.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 26, 'Ba mado Lewi, ba 4.600.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 27, 'Ba baero ö, ba Yoyada, salaŵa nga''ötö Ga''aroni, 3.700 ira,', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 28, 'ba Sadoki, ono matua sabölö; 22 zalaŵa ba watalifusöta andrö khöra.[6]', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 29, 'Ba mado Mbeniyami, iwa Zaulo, ba 3.000; sato khöra, ba lö''ö sa laböhöli nga''ötö Zaulo, irugi luo da''ö.', '["SamII 15:24; Faigi 5:34"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475093, 'OT', 'Nga''ötö I', 12, 30, 'Ba mado Geferayi, ba 20.800, sabölö ba sebua turia, ba watalifusöta andrö khöra.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 31, 'Ba si matonga mado Manase, ba 18.000, nitötöi, ena''ö möi ira, ba wamataro razo Dawido.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 32, 'Ba mado Isasari, si no aboto ba dödö inötö, sangila watahögö nilau Ndraono Gizeraeli, ba 200 högö, awö niwara fefu, barö mbawara.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 33, 'Ba mado Zebuloni, ba 50.000, sabölö ba wasuwöta, si so ngawalö wangöna, ba si no mangaro, sangendröna manolo, si ha sara dödö.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 34, 'Ba mado Nafetali, ba 1000 högö, ba 37.000 nawöra, solohe baluse ba toho.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 35, 'Ba mado Dano, ba 28.600, si no mangaro, ba wasöndrata.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 36, 'Ba mado Gaseri, ba 40.000, sabölö, sangendröna fao, ba wasuwöta.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 37, 'Ba moroi ba zi tambai Yoridano: Mado Rubeno ba mado Gado ba si matonga mado Manase, ba 120.000, si so fangöna, hadia ia ngawalö, soguna ba wasuwöta.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 38, 'Sabölö andrö fefu, si no mama''anö ba wasuwöta, zi möi ba Heberona, ha sara dödö, ba wamataro razo Ndraono Gizeraeli fefu Dawido. Ba he Iraono Gizeraeli fefu, si tosai baero ö, ba ha sara dödö, ba wamataro razo Dawido.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 39, 'Ba tölu bongi ira ba da''ö khö Dawido, ba lafodiwo ira talifusöra andrö.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475093, 'OT', 'Nga''ötö I', 12, 40, 'Ba sahatö ba da''ö, irege mado Isasari ba mado Zebuloni ba mado Nafetali, ba la''ohe mbalazo ba hulu galide ba ba hulu gondra ba ba hulu kudo kalide ba ba hulu zaŵi: öra hamo ba kue nilau bua ara ba kue nilau bua nagu ba agu ba fanikha ba saŵi ba biri-biri, oya sibai, me no somuso tödö Ndraono Gizeraeli.', '["SamII 15:24; Faigi 5:34"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 1, 'Ba mamagölö Dawido ba gumandra zi hönö ba ba gumandra zi otu ba ba zalaŵa fefu.[1]', '["Faigi göi SamII 6:1–11","Yos 15:9"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 2, 'Ba imane Dawido, ba Ndraono Gizeraeli sato, fefu: Na omasi ami [göi], ba na moroi khö Lowalangida, Yehowa, ba datafatenge ba niwada misa, si no toröi furi heza, ba danö Ndraono Gizeraeli ba ba gere ba ba Nono Lewi, ba mbanua misa, nitehe khöra, fabaya benua ba ngai, ena''ö la''ondrasi ita,', '["Faigi göi SamII 6:1–11","Yos 15:9"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 3, 'ba ena''ö tafuli tahalö khöda dawöla Lowalangida andrö; me luo razo Zaulo, ba lö''ö sa ba dödöda ya''ia.', '["Faigi göi SamII 6:1–11","Yos 15:9"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 4, 'Ba latema linia sato fefu, hana na lamanö, me omasi zato niŵa''önia andrö.', '["Faigi göi SamII 6:1–11","Yos 15:9"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 5, 'Ba ifakaoni''ö Ndraono Gizeraeli fefu Dawido, i''otarai mbewe Zihora, ba danö Miserayi, numalö ba lala ba Hamata andrö, ena''ö lahalö dawöla Lowalangi, ba Giriati Yeari.', '["Faigi göi SamII 6:1–11","Yos 15:9"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 6, 'Ba möi ba Mba''ala [ya''ia Giriati Yeari ba mado Yuda] Dawido, awö Ndraono Gizeraeli fefu, ba wolohe miyaŵa, moroi ba da''ö, tawöla Lowalangi andrö, nifotöi tawöla Yehowa sidadao yaŵa kerubi.[2]', '["Faigi göi SamII 6:1–11","Yos 15:9"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 7, 'Ba lahalö dawöla Lowalangi, ba nomo Gabinadabi, ba labe''e ba gureta si bohou, ba Usa ba Ahio zolohe kureta andrö.', '["Faigi göi SamII 6:1–11","Yos 15:9"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 8, 'Ba Dawido ba Iraono Gizeraeli fefu, ba molaya, wowaö-waö föna Lowalangi, laforege, manunö ira ba lalau mbiola nitika, side-ide ba sebua, ba labözi rafa''i ba faritia ba lalau dorofe.', '["Faigi göi SamII 6:1–11","Yos 15:9"]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 9, 'Ba me larugi golayama mbasitö andrö ba Gidono, ba i''oro''ö dangania Usa, ba wolohelohe tawöla, me no lahole''ö ira saŵi andrö.', '[]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 10, 'Ba tesao wönu Yehowa khö Usa, ba ibözi ia, ba tobali mate ia ba da''ö, föna Lowalangi.', '[]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 11, 'Ba lö sökhi-sökhi dödö Dawido, me no ira''u manö Usa andrö Yehowa, ba labe''e sa''ae töi naha andrö Weresi Usa (Fondra''u Usa), irugi ma''ökhö andre.', '[]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 12, 'Ba ata''u Dawido Lowalangi, me luo da''ö, ba imane: Ba he uwisa wolohe khögu tawöla Lowalangi andrö?', '[]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 13, 'Ba lö ifa''ohe''ö khönia ba mbanua Dawido dawöla, ba ngai lala ifa''ohe''ö, ba nomo Gobedi-Edomo, banua Gata.', '[]', NULL),
  (3475094, 'OT', 'Nga''ötö I', 13, 14, 'Ba toröi ba da''ö dawöla Lowalangi, khö Gobedi-Edomo, ba nomonia, tölu waŵa; ba ifahowu''o Yehowa zi samba omo ndra Obedi-Edomo, awö fefu hadia ia zi so khönia.', '[]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 1, 'Ba Hiramo andrö, razo Diro, ba ifatenge zinenge khö Dawido,[1] ba ifa''ohe''ö geu, eresi, ba tuka gara ba tuka geu ifatenge, ba wolau omo khö Dawido.', '["Faigi göi SamII 5:11–25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 2, 'Ba aboto ba dödö Dawido, wa no ifataro ia razo Ndraono Gizeraeli Yehowa, wa itugu ebua wa''arazonia [ibe''e Yehowa], börö mbanuania Iraono Gizeraeli.', '["Faigi göi SamII 5:11–25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 3, 'Ba ba Yeruzalema, ba ihalö na ndra alawe Dawido, ba tumbu-tumbu na khönia ndraono, ono matua ba ono alawe.', '["Faigi göi SamII 5:11–25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 4, 'Da''e döi ndraono andrö, si tumbu khönia ba Yeruzalema: Samua ba Sobaba ba Natano ba Selomo,', '["Faigi göi SamII 5:11–25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 5, 'ba Yibihara ba Elisua ba Elefeleto,', '["Faigi göi SamII 5:11–25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 6, 'ba Noga ba Nefegi ba Yafia,', '["Faigi göi SamII 5:11–25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 7, 'ba Elisama ba Be''eliada ba Elifeleti.', '["Faigi göi SamII 5:11–25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 8, 'Ba me larongo Dawa Wilisiti, no mubayoini razo Ndraono Gizeraeli fefu Dawido, ba so ira moroi si tou, dozi ira, ba wangalui Dawido. Ba me irongo da''ö Dawido, ba ifaondragö ira.', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 9, 'Ba me no larugi danö Dawa Wilisiti, me no lafazaewe ira ba zalo''o, ba Refa''i,', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 10, 'ba isofu khö Lowalangi Dawido, imane: Hadia, ufaondragö Ndrawa Wilisiti andrö, hadia, öbe''e ba dangagu ira? Ba imane khönia Yehowa: Ae''e — ube''e ba dangau ira!', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 11, 'Ba me lafa''ese ira miyaŵa, ba Mba''ali Werasi, ba ilau khöra Dawido, ba te''ala ira ibe''e. Ba imane Dawido: No muzaewe nemaligu fönagu ibe''e Lowalangi tangagu andre, si mane na atöla mba''a-ba''a nidanö! Andrö wa labe''e töi naha andrö Mba''ali Werasi (Sokhö fa''atöla)', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 12, 'Ba laröi furi ba da''ö nadura, ba ifatunu''ö Dawido.[2]', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 13, 'Ba ifuli so Ndrawa Wilisiti, labologö ira ba zalo''o.', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 14, 'Ba me ifuli isofu khö Lowalangi Dawido, ba imane khönia Lowalangi: Böi faondragö ira, fasui ira, moroi furi, ba otarai mbörö keretau andrö, wolau khöra!', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 15, 'Ba na örongo ruru zanörö ba hogu keretau andrö, ba labu; noa sa mowaö-waö fönau Lowalangi, ba wolau ba Ndrawa Wilisiti, ba zanuwö andrö.', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 16, 'Ba i''o''ö Dawido niŵa''ö Lowalangi khönia, ba te''ala Ndrawa Wilisiti labe''e, i''otarai Gibeona, irugi misa Geseri.', '["MozV 7:5,25"]', NULL),
  (3475095, 'OT', 'Nga''ötö I', 14, 17, 'Ba humöngö duria Dawido ba danö niha bö''ö, fefu, ba dozi soi, ba ihawui fa''ata''ura Dawido Yehowa.', '["MozV 7:5,25"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 1, 'Ba molau omo Dawido — tenga ha sambua — ba mbanua Dawido andrö, ba ifazökhi göi nahia dawöla Lowalangi andrö, ose ilau ba da''ö.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 2, 'Imane Dawido me luo da''ö: Tawöla Lowalangi andrö, ba lö tola la''osa''ö niha bö''ö, ha Ono Lewi andrö; me no ya''ira nitutuyu Yehowa, ba wangosa''ö tawöla Lowalangi, ba wangai-ngai halöŵö khönia, si lö mamalö-malö.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 3, 'Ba ifakaoni''ö ba Yeruzalema Ndraono Gizeraeli fefu Dawido, ba wolohe miyaŵa tawöla Yehowa ba nahiania andrö, nilaunia.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 4, 'Ba i''owuloi nga''ötö Ga''aroni Dawido, awö Nono Lewi andrö:', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 5, 'Nga''ötö Gahati andrö: Urieli, satua, ba talifusönia, 120.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 6, 'Ba he nga''ötö Merari: Asaya, satua, ba talifusönia, 220.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 7, 'Ba he nga''ötö Gereso: Yoeli, satua, ba talifusönia, 130.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 8, 'Ba he nga''ötö Elisafa: Semaya, satua, ba talifusönia, 200.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 9, 'Ba he nga''ötö Heberona: Elieli, satua, ba talifusönia, 80.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 10, 'Ba he nga''ötö Usieli: Aminadabi satua, ba talifusönia, 112.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 11, 'Ba ifa''aso gere andrö Dawido, Sadoki ba Abiataro, ba ono Lewi andrö, Urieli ba Asaya ba Yoeli ba Semaya ba Elieli ba Aminadabi,[1]', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 12, 'ba imane khöra: No satua ngafu ami ba Nono Lewi, mi''amoni, ya''ami ba talifusömi, ena''ö mi''ohe miyaŵa dawöla Yehowa, Lowalangi Ndraono Gizeraeli ba naha andrö nilaugu nahania.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 13, 'Me no lö ya''ami, ba zi föföna andrö, ba no ibözi ndra''aga Lowalangida, Yehowa, me lö ma''o''ö nifakhoinia.[2]', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 14, 'Ba mamoni gere andrö, awö Nono Lewi andrö, ba wolohe miyaŵa tawöla Yehowa, Lowalangi Ndraono Gizeraeli.', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 15, 'Ba lafazaŵa dawöla Lowalangi Ono Lewi andrö, lahare''ö ba galisira heahea andrö, la''o''ö niwa''ö Moze dali goroisa Yehowa,[3]', '["SamII 15:29","Faigi 13:9,10","MozII 25:14; MozIV 4:15"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 16, 'Ba ibe''e li Dawido ba zatua Nono Lewi andrö, ba wamataro iwara andrö, sanunö, si so fakake ba wanunö, biola nitika, sebua ba side-ide ba faritia, ena''ö lafarongogö lua-lua wa''omuso dödö, sebua li.', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 17, 'Ba nifataro Nono Lewi andrö, ba Hemano, ono Yoeli, ba talifusöra Asafo, ono Mberekhia, ba iwara, nga''ötö Merari, Etano, ono Gusaya.', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 18, 'Ba awöra iwara na, amaedola dambalina: Sakharia, ono Ya''asieli, ba Semiramoto ba Yehieli ba Uni ba Eliabi ba Benaya ba Ma''aseya ba Matitia ba Elifelehu ba Mikeneya ba Obedi-Edomo ba Yeieli, sanaro ba mbawandruhö.', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 19, 'Ba Hemano ba Asafo ba Etano, sanunö, si so faritia, ba wangebua li.[4]', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 20, 'Ba Sakharia ba Azieli ba Semiramoto ba Yehieli ba Uni ba Eliabi ba Ma''aseya ba Benaya, ba si so biola nitika sebua, si ohia''ö li nono alawe.', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 21, 'Ba Matitia ba Elifelehu ba Mikeneya ba Obedi-Edomo ba Yeieli ba Azasia, ba si so biola nitika side-ide, soli sesolo, fondrönia''ö.', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 22, 'Ba Kenania, satua Nono Lewi, ba wangosa''ö [tawöla] ba samaigi fangosa''ö andrö, me no to''ölö ia ba da''ö.', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 23, 'Ba Berekhia ba Elikana, ba no sanaro ba mbawandruhö, ba naha dawöla.', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 24, 'Ba Sebania ba Yozafati ba Netane''eli ba Amisai ba Sakharia ba Benaya ba Eliezeri, ere andrö, ba solau torofe, sowaö-waö föna dawöla Lowalangi, ba Obedi-Edomo ba Yehia, ba no sanaro ba mbawandruhö [göi], ba naha dawöla.', '["Faigi 6:18,24; 25:1"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 25, 'Ba möi Dawido,[5] awö zatua Ndraono Gizeraeli, awö gumandra ngahönö, ba wolohe miyaŵa tawöla goroisa Yehowa, moroi ba nomo Gobedi-Edomo, oi so wa''omuso dödö.', '["Ayati 25–29: SamII 6:12–16"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 26, 'Ba me itolo Lowalangi Nono Lewi andrö, sangosa''ö tawöla goroisa Yehowa, ba fitu rozi labe''e sumange ono zaŵi ba fitu nga''eu göi mbiri-biri si matua.', '["Ayati 25–29: SamII 6:12–16"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 27, 'Ba baru sebua, tarafali, mbaru Dawido ba baru Nono Lewi fefu, sangosa''ö tawöla ba baru Genania, satua zangosa''ö, [högö] zanunö. Ba baru ba doto na, tarafali, mbaru Dawido.', '["Ayati 25–29: SamII 6:12–16"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 28, 'Ba la''ohe miyaŵa dawöla goroisa Yehowa Iraono Gizeraeli fefu, no owua-wua dödö ba no ebua li dorofe sanau, ba so dorofe bö''ö ba faritia, ba biola nitika, sebua ba side-ide, lalau.', '["Ayati 25–29: SamII 6:12–16"]', NULL),
  (3475096, 'OT', 'Nga''ötö I', 15, 29, 'Ba me irugi mbanua Dawido tawöla goroisa Yehowa, ba ifaigi Mikhala andrö, ono Zaulo, moroi yaŵa ba zandrela. Ba me i''ila, wa ifaröga ia Dawido ba molaya, ba fatuwu ia khönia.', '["Ayati 25–29: SamII 6:12–16"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 1, 'Ba me no la''ohe miyomo dawöla Lowalangi ba me no labe''e ba nose andrö, nilau Dawido nahiania, ba lafosumange Lowalangi, sumange nitunu ba sumange fangorifi.[1]', '["Ayati 1–3: SamII 6:17–19"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 2, 'Ba me no i''asiwai Dawido wame''e sumange nitunu andrö, awö zumange fangorifi ba ifahowu''ö niha sato ba döi Yehowa,', '["Ayati 1–3: SamII 6:17–19"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 3, 'ba idozigö Ndraono Gizeraeli, he ira matua, ba he ira alawe, sambua roti ba samba su''a-su''a [agu] ba sagörö kue nilau bua nagu zamösa.', '["Ayati 1–3: SamII 6:17–19"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 4, 'Ba ifataro sangai halöŵö Nono Lewi ösa föna dawöla Yehowa, ba ena''ö lasuno Yehowa, Lowalangi Ndraono Gizeraeli, ena''ö la''andrö saoha gölönia [wa''ebua dödönia] ba ena''ö la''ebua''ö döinia:', '["Ayati 1–3: SamII 6:17–19"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 5, 'Asafo andrö, högö, ba Sakharia, tambalinania, ba Yeieli ba Semiramoto ba Yehieli ba Matitia ba Eliabi ba Benaya ba Obedi-Edomo ba Yeieli [na], si so nifoli, biola nitika, sebua ba side-ide; ba Asafo, ba samözi-mözi faritia,', '["Ayati 1–3: SamII 6:17–19"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 6, 'ba Benaya ba Yehezieli, ere andrö, ba si lö mamulö''ö folau torofe, föna dawöla, si so sura goroisa Lowalangi andrö.', '["Ayati 1–3: SamII 6:17–19"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 7, 'Ba me luo da''ö, ba awena ibe''e li Dawido khö Gasafo ba ba dalifusönia, ba wolau "Mi''andrö saoha gölö khö Yehowa" andrö:', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 8, 'Mi''andrö saoha gölö khö Yehowa, mi''angaröfi li döinia! Midunö-dunö ba niha baero wolaunia andrö![2]', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 9, 'Mi''anunö khönia! Misuno ia! Ena''ö itörö limi zahöli-höli dödöda andrö khönia, fefu.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 10, 'Misuno ami ba döinia andrö, ni''amoni''ö. Ya''omuso dödö zangalui Yehowa.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 11, 'Mizofu-zofu Yehowa ba fa''abölönia andrö. Böi mifamalö-malö wangalui bawania andro.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 12, 'Mitörö-törö tödömi zahöli-höli dödöda andrö khönia, nilaunia, tandra andrö khönia ba fanguhukunia, taroma linia.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 13, 'Ya''ami, nga''ötö Gizeraeli, ya''ami enoninia, ma''uwu Yakobo, nitutuyunia!', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 14, 'Ya''ia, Yehowa, ba no Lowalangida; itöröi guli danö fanguhukunia andrö.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 15, 'Irugi zi lö aetu böi olifu ami wawu''usa li andrö, khönia, taroma li andrö, niŵa''önia, ba ngahönö nga''ötö,', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 16, 'me fawu''u li ia khö Gaberahamo, ba fahölusania khö Giza''aki.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 17, 'Ba no ibe''e amakhoita khö Yakobo, fawu''usa li si lö tebulö ba Ndraono Gizeraeli,', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 18, 'me imane: Khöu ube''e danö Gana''ana andrö, tana khömi, ondröita.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 19, 'Me lö ato ami na, me ha fasamösa na, ba me si fatewu ami ba da''ö.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 20, 'Ba latöröi soi niha andrö, lafa''ema danö.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 21, 'Lö ibe''e nifakao niha bö''ö ira, ba razo i''otu''ö, börö ira.[3] 22"Böi mibabaya nibayoinigu andrö, ba böi mifakao zame''ele''ö andrö khögu!"', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 23, 'Mi''anunö khö Yehowa, dozi tanö! Mi''ombakha''ö wangorifi andrö khönia, mi''erogö ma''ökhö![4]', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 24, 'Midunö-dunö ba niha baero duriania, ba ba niha fefu zahöli-höli dödö andrö khönia.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 25, 'Me no sebua Yehowa, ba me no si nangea nisuno sibai, ni''ata''ufi, yaŵa Lowalangi bö''ö, fefu.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 26, 'Lowalangi niha baero andrö sa, fefu, ba adu, ba Yehowa, ba no samazökhi banua si yaŵa.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 27, 'Lakhömi ba fa''asalaŵa fönania, fa''abölö ba fa''owua-wua dödö ba nahiania.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 28, 'Mibe''e khö Yehowa, ya''ami ngawalö soi niha, mibe''e khö Yehowa lakhömi ba fa''abölö.[5]', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 29, 'Mibe''e khö Yehowa zumange döinia andrö; mi''ohe game''ela ba mi''ondrasi ia. Mi''angalulu khö Yehowa, mi''angehao, fangehao ni''amoni''ö.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 30, 'Mi''anizi-nizi fönania, dozi tanö! Noa göi i''aro''ö gölia uli danö, ba lö mangiwa.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475097, 'OT', 'Nga''ötö I', 16, 31, 'Ya''omuso dödö mbanua si yaŵa ba ya''owua-wua dödö guli danö, ba yalamane niha baero: No razo Yehowa!', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 32, 'Yamu''ugu-ugu nasi ba ösinia, yama''iki mbenua ba hadia ia fefu ba khönia.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 33, 'Ba fefu döla geu sa''ae ba gatua, ba owua-wua dödö föna Yehowa; so ia sa moroi sa, ba wanguhuku ösi guli danö.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 34, 'Mi''andrö saoha gölö khö Yehowa, me no si sökhi tödö ia; me si lö aetu wa''ebua dödönia andrö.[6]', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 35, 'Ba mimane: Tolo ndra''aga, Lowalangi, ya''ugö, sangorifi ya''aga, ba ozaragö ndra''aga ba efa''öga ba danga niha baero, ena''ö ma''andrö saoha gölö ba döimö andrö, ni''amoni''ö, ba ena''ö masuno ndra''aga ba wanuno ya''ugö andrö.', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 36, 'Nisuno Yehowa, Lowalangi Ndraono Gizeraeli, götö-götö wa''ara! Ba lamane sato fefu: Yaduhu! ba lasuno Yehowa.[7]', '["Ayati 8–22: Sin 105:1–15","Moz. I, 12:17; 20:3; 26:9","Ayati 23–33: Sin 96","Sin 29:1,2","Ayati 34–36: Sin 106:1,47,48","Sin 41:14"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 37, 'Ba ifataro ba da''ö föna dawöla goroisa Yehowa, Gasafo andrö ba talifusönia, ena''ö böi lafamalö-malö wangai-ngai halöŵöra föna dawöla andrö, ero ma''ökhö.', '["Faigi 21:29","MozII 29:38,39"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 38, 'Ba Obedi-Edomo, ono Yedutuno, ba Hosa ba talifusöra, 68 ira. Obedi-Edomo, ono Yedutuno, ba Hosa, ba ibe''e sanaro ba mbawandruhö.', '["Faigi 21:29","MozII 29:38,39"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 39, 'Ba Sadoki ere ba talifusönia ere andrö, ba föna nose ba hili-hili andrö ba Gibeona ifataro,[8]', '["Faigi 21:29","MozII 29:38,39"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 40, 'ena''ö böi lafamalö-malö, na mahemolu mbanua ba na tanö owi, wame''e sumange nitunu khö Yehowa, ena''ö latörö fefu gamakhoita andrö ba goroisa Yehowa, niŵa''önia ba Ndraono Gizeraeli.[9]', '["Faigi 21:29","MozII 29:38,39"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 41, 'Ba awöra ndra Hemano Yedutuno ba ha niha na ira, nitutuyu, nitötöi töi, ba wangandrö saoha gölö khö Yehowa, me si lö aetu wa''ebua dödönia.', '["Faigi 21:29","MozII 29:38,39"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 42, 'Ba awöra ndra Hemano Yedutuno no mege, ba so dorofe ba faritia ba zanunö andrö, ba hadia ia nifoli ba zinunö andrö khö Lowalangi; ba iraono Yedutuno andrö, ba ba mbawandruhö.', '["Faigi 21:29","MozII 29:38,39"]', NULL),
  (3475097, 'OT', 'Nga''ötö I', 16, 43, 'Ba mofanö zato, ifuli ia khöra zamösana. Ba ifuli göi ia Dawido, ba wangowai soroiyomonia.', '["Faigi 21:29","MozII 29:38,39"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 1, 'Ba me noa sa''ae möi yomo ba gödonia Dawido,[1] ba samuza ma''ökhö, ba imane khö Natano sama''ele''ö: Hiza, ya''o, ba ba nomo eresi sodo, ba ha oloso nose dawöla goroisa Yehowa!', '["Faigi göi SamII 7"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 2, 'Ba imane Natano khö razo: Falua hadia ia zi so ba dödöu, itolo''ö sa Lowalangi.', '["Faigi göi SamII 7"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 3, 'Ba ba zi bongi andrö, ba so niŵa''ö Lowalangi khö Natano, imane:', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 4, 'Ae khö genonigu Dawido, ba ömane khönia: Da''ö niŵa''ö Yehowa: Tenga ya''ugö zolau nahiagu omo.', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 5, 'Lö''ö sa atö ni''onahiagu omo, i''otarai me u''ohe miyaŵa Ndraono Gizeraeli, irugi ma''ökhö andre; barö nahia ose mege utöröi danö.', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 6, 'Götö zi no fao-fao ndra''o ba Ndraono Gizeraeli fefu, ba hadia, ba no urai ube''e li ba zanguhuku Iraono Gizeraeli, ha niha ia, ba niŵa''ögu fokubaloi banuagu Iraono Gizeraeli, hadia, samuza no umane: Hana wa lö milau khögu gödo eresi?', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 7, 'Ba ömane sa''ae khö genonigu Dawido: Da''ö niŵa''ö Yehowa ngahönö: No ba mbenua uhalö ndra''ugö, me kubalo mbiri-biri ndra''ugö, ena''ö razo mbanuagu Iraono Gizeraeli ndra''ugö,', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 8, 'ba no utolo''ö ba nilaumö fefu, ba no uhori fönau nemaliu; ba ebua döimö ube''e, timba döi wondrege zebua ba guli danö.', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 9, 'Ba ba mbanuagu Iraono Gizeraeli, ba ututuru nahara tanö, ba utanö ira, ba da''ö, ena''ö ba nahara andrö soso ira ba ena''ö tebai sa''ae lahori ira niha samakao awöra, si mane föna.', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 10, 'I''otarai götö zanguhuku andrö, nifatarogu högö mbanuagu Iraono Gizeraeli, ba uhöndrögö fefu zi fa''udu khöu. Ba u''ombakha''ö khöu: Yehowa zolau omo khöu.', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 11, 'Na no irugi baŵau wa''amate dania, na möi''ö ba ngai ndra tuau, awena dania uhonogöi fangaliu ma''uwumö, nga''ötöu andrö, ba u''a''aro''ö wa''asalaŵania.', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 12, 'Da''ö dania zolau omo khögu, ba si lö tebulö dadaoma zalaŵa khönia ube''e, irugi zi lö aetu.[2]', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 13, 'Amania ndra''o, ba onogu ia. Ba fa''ahakhö dödögu andrö, ba lö uböda khönia, si mane famödagu ya''ia khö razo andrö fönau.', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 14, 'Si lö tebulö ia satua baomo khögu ba razo mbanuagu, ube''e, ba dadaomania, ba si lö awu''a, götö-götö wa''ara.', '["Faigi 22:10; 28:6"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 15, 'Ba dali sibai daroma li andrö ba angilata andrö, khö Natano, ba wehedenia khö Dawido.', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 16, 'Ba möi baose Dawido, mudadao ia föna Yehowa ba imane: "He Yehowa, Lowalangigu! Ha niha ndra''odo, ba ha niha zoroiyomogu fefu, wa no ötolodo irugi da''e?[3]', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 17, 'Ba lö''ö na sa ahono dödöu ba da''ö, ya''ugö Lowalangi, noa na göi öfabu''u limö ba nga''ötö zawuyumö, götö-götö wa''ara, ya''ugö Yehowa, Lowalangi.', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 18, 'Ba hadia na niŵa''ö Dawido khöu? Noa sa aboto ba dödöu zawuyumö andre!', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 19, 'He Yehowa, börö zawuyumö andre ba dali dödöu, ba wolaumö da''ö, wa no ö''ombakha''ö khö zawuyumö andre zi sökhi andrö fefu.', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 20, 'He Yehowa, lö si falaŵalaŵa khöu ba lö Lowalangi baerou, dali fefu nirongoma tögi dalingama.', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 21, 'Ba heza ba guli danö so niha bö''ö si falaŵalaŵa ba mbanuau Iraono Gizeraeli, heza so soi, si no möi Lowalangi, ba wangöhöli ya''ia banuania, ba ba wangebua töinia, ba ba wamatörö khönia sebua ba sata''u ita, wanimba föna mbanuania andrö soi bö''ö, fabaya Lowalangira?', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 22, 'Ba ya''ugö, ba no öhonogöi banuamö mbanuau Iraono Gizeraeli, irugi zi lö aetu, ba no tobali Lowalangira ndra''ugö, ya''ugö Yehowa.', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 23, 'Ba iada''e, ya''ugö Yehowa, ba ena''ö na lö tebulö nifabu''umö andrö ba khö zawuyumö andre ba ba nga''ötönia, irugi zi lö aetu; ba törö nifabu''umö andrö.', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 24, 'Ba oroma dania, wa no si ndruhu döimö andrö ba teturia ia götö-götö wa''ara; ba da''ö döimö: Yehowa ngahönö, Lowalangi Ndraono Gizeraeli, ba si lö tebulö fönau nga''ötö zawuyumö Dawido.', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 25, 'Noa sa öbokai khö zawuyumö, wa ya''ugö zolau omo khönia, ya''ugö Lowalangi, andrö wa no abe''e dödö zawuyumö, ba wamarongogö khöu fangandrö andre.', '["MozI 32:11"]', NULL),
  (3475098, 'OT', 'Nga''ötö I', 17, 26, 'Ba hiza, ya''ugö Yehowa, no ya''ugö Lowalangi, me no öfabu''u khö zawuyumö zi sökhi sibai andrö, 27— ba iya''e, ba aohasi gölöu, ba wamahowu''ö nga''ötö zawuyumö andre, ena''ö böi tebulö fönau. Hadia sa nifahowu''ömö, ya''ugö Yehowa, ba lö tebulö nifahowu''ö!"', '["MozI 32:11"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 1, 'Aefa da''ö, ba ilau ba Ndrawa Wilisiti Dawido, ihöndrögö ira, ba ifadöni khöra Gata, fabaya halama soya khöra.[1]', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 2, 'Ba ilau göi ba Ndraono Maobi, ba tobali möi barö mbawa Dawido Ndraono Moabi, same''e beo khönia.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 3, 'Ba i''alani na göi Hadarezeri, razo Zoba, Dawido, tanö ba Hamata, me no ba lala ba Oifarati so ia, ba wangaro''ö fa''arazonia ba da''ö.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 4, 'Hönö zahulu Dawido khönia kureta ba 17.000 zi fakudo ba 20.000 zi lö kudo i''oloi''ö niha; ba ba kudo andrö, ba ahori ifa''eŵa''ö gölu''ölu Dawido, ha 100 nga''eu isaigö.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 5, 'Ba me latolo Hadarezeri, razo Zoba, Dawa Garamo ba Ndramaseko, ba 22.000 zi mate Dawa Garamo ibe''e Dawido.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 6, 'Ba ifataro gumandru ba danö Ndrawa Garamo Dawido, ba danö Ndramaseko, ba tobali möi barö mbawa Dawido Ndrawa Garamo, same''e beo khönia; tolali sabölö manö Dawido, heza möi ia, ibe''e Yehowa.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 7, 'Ba ahulu göi Dawido baluse ana''a andrö, baluse genoni Hadarezeri, ba ifa''ohe''ö ba Yeruzalema.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 8, 'Ba ebua sibai göi zahulu ia töla, ba mbanua Hadarezeri andrö, ba Deba ba ba Gunu.[2]', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 9, 'Ba me irongo To''u, razo Hamata, no te''ala zabolö andrö khö Hadarezeri, razo Zoba, fefu, ibe''e Dawido,', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 10, 'ba ifatenge khö razo, Dawido, nononia Hadoramo, ba wangowai ya''ia, ba ba wamahuwu''ö ya''ia ba wanuwönia Hadarezeri andrö, si no abölö ia — noa sa fasuwö ira göi föna Do''u Hadarezeri, — ifa''ohe''ö khönia gama-gama ana''a ba firö ba töla.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 11, 'Ba da''ö göi, ba i''amoni''ö khö Yehowa Dawido, awö wirö andrö ba awö gana''a, nihalönia ba niha andrö, fefu, ba Ndraono Gedomo ba ba Ndraono Moabi ba ba Ndraono Gamoni ba ba Ndrawa Wilisiti ba ba Ndraono Gamaleki.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 12, 'Ba Abiza''i, ono Zeruya, ba solau ba Ndraono Gedomo, ba ndraso nasio, 18.000 zi mate.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 13, 'Ba ifataro gumandru ba danö Ndraono Gedomo ba tobali barö mbawa Dawido Ndraono Gedomo fefu. Ba sabölö Dawido, ibe''e Yehowa, gofu he irugi.', '["Faigi göi SamII 8","RazI 7:23"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 14, 'Ba razo Dawido ba Ndraono Gizeraeli fefu, huku satulö ifatörö ba mbanuania fefu.', '["Faigi 24:6"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 15, 'Ba Yoabi, ono Zeruya, ba no kumandra zabölö, ba Yozafati, ono Gahiludi, ba no sa''asa sebua.', '["Faigi 24:6"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 16, 'Ba Sadoki, ono Gahitubi, ba Abimelekhi, ono Gabiataro, ba ere; ba Sawesa, ba durutuli.[3]', '["Faigi 24:6"]', NULL),
  (3475099, 'OT', 'Nga''ötö I', 18, 17, 'Ba Benaya, ono Yehoyada, ba kumandra wazuri, ba iraono Dawido, ba no amaedola zi a''a genoni razo.', '["Faigi 24:6"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 1, 'Aefa da''ö no mege, ba mate Nahasi andrö, razo Ndraono Gamoni, ba fangalinia razo, ba ononia Hanuno.[1]', '["Faigi göi SamII 10"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 2, 'Ba imane Dawido: Da''u''oroma''ö wa''ebua dödögu khö Hanuno, ono Nahasi, me no ebua göi dödö namania khögu mege. Ba ifatenge zinenge Dawido, ba wondrara tödö Hanuno ba khö namania. Ba me larugi danö Ndraono Gamoni, khö Hanuno, enoni Dawido andrö,', '["Faigi göi SamII 10"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 3, 'ba wondrara tödönia, ba lamane salaŵa Ndraono Gamoni, khö Hanuno: Hadia, faduhu dödöu, wa sumange namau khö Dawido wamatenge khöu sondrara tödöu? Faya na tenga ba wamauze banua ba ba wanudugö dania ifatenge khöu genoninia Dawido, ba ba wamauze tanö.', '["Faigi göi SamII 10"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 4, 'Ba ifara''u''ö genoni Dawido Hanuno, ifatöwö''ö ira, ba barura, ba lafalo''o, irege daro''o, ba ifatenge mangawuli ira.', '["Faigi göi SamII 10"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 5, 'Ba me so zangombakha khö Dawido, hadia nilau ba zinengenia andrö, ba ifatenge zamaondragö ya''ira — noa sa aila sibai ira — imane khöra razo: Mi''iagö Yerikho, irege ifuli anau gambimi, awena dania mifuli ami.', '["Faigi göi SamII 10"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 6, 'Ba me aboto ba dödö Ndraono Gamoni, wa no abao dödö Dawido khöra, ba 220.500 balaki lafa''ohe''ö firö ira Hanuno, ba wowöli kureta, fabaya si fakudo, ba Ndrawa Garamo ba Mezofotamia ba ba Ma''akha ba ba Zoba.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 7, 'Ba 32.000 la''öli kureta, ba fao razo Ma''akha ba sabölö andrö khönia. Ba so da''ö, ba wanuwö Medeba. Ba la''owoloi ira Iraono Gamoni, moroi ba mbanua khöra misa, ba möi manuwö.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 8, 'Ba me irongo da''ö Dawido, ba ifatenge Yoabi, awö zaradadu andrö fefu.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 9, 'Ba so moroi yomo Ndraono Gamoni, la''angenoligö ira, fönaföna mbawa göli mbanua, ba razo andrö, si no möi awöra, ba no tonia, baero ba mbenua.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 10, 'Ba me i''ila Yoabi, faoma so zolau khönia, he moroi föna, ba he moroi furi, ba itutuyu zabölö Ndraono Gizeraeli ba ifaondragö Ndrawa Garamo.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 11, 'Ba si tosai niha, ba ibe''e ni''ohe nakhinia Abiza''i, ba wolau ba Ndraono Gamoni.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 12, 'Ba imane wame''e li ba da''ö: Na tebai ulaŵa Ndrawa Garamo, ba möi''ö manolo ya''odo; ba na tebai ölaŵa Ndraono Gamoni, ba so ndra''o, ba wanolo ya''ugö.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 13, 'Abe''e''ö dödöu, ba ena''ö faoma abe''e ita, ba wangorifi banuada ba banua Lowalangida andrö — ba yamulau zomasi ia Yehowa![2]', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 14, 'Ba ifaondragö Ndrawa Garamo Yoabi, ba wolau khöra, i''ohe zabolö andrö, si fao khönia, ba moloi Ndrawa Garamo ibe''e.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 15, 'Ba me la''ila Iraono Gamoni moloi Ndrawa Garamo ibe''e Yoabi, ba moloi göi ira föna nakhinia, lawuwu ira miyomo ba mbanua. Ba ifuli ia ba Yeruzalema Yoabi.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 16, 'Ba me la''ila Dawa Garamo te''ala ira labe''e Iraono Gizeraeli, ba lafatenge zinenge, lafakaoni''ö Ndrawa Garamo yefo Oifarati; ba solohe ya''ira, ba Sofakhi, kumandra andrö khö Hadarezeri.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 17, 'Ba me la''ombakha''ö da''ö khö Dawido, ba i''owuloi Ndraono Gizeraeli fefu, i''ötö Yoridano, irugi Helami ba ibase''ö ira ba da''ö. Ba so Ndrawa Garamo, la''angenoligö ira, ba wolau khö Dawido, ba fasöndra ira khönia.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 18, 'Ba moloi Ndrawa Garamo labe''e Iraono Gizeraeli, ba 7.000 kudo sondröni kureta ba 40.000 niha si lö kudo zi mate ba Ndrawa Garamo labe''e ira Dawido, ba he Sofakhi andrö, kumandra, ba labunu.', '["SamI 3:18"]', NULL),
  (3475100, 'OT', 'Nga''ötö I', 19, 19, 'Ba me la''ila banua Hadarezeri no te''ala ira labe''e Iraono Gizeraeli, ba la''atulö''ö ira khö Dawido, möi ira barö mbawania, ba abua gölö Ndrawa Garamo latohugö wanolo Iraono Gamoni.', '["SamI 3:18"]', NULL),
  (3475101, 'OT', 'Nga''ötö I', 20, 1, 'Ba döfi aefa da''ö,[1] me baŵa wanuwö ba razo, ba i''ohe zabölö Yoabi ba ifufu danö Ndraono Gamoni. Ba möi ia musuwö Raba, ba no toröi ba Yeruzalema Dawido. Ba atu''a Yoabi ba Raba, ba idudugö.', '["Ayati 1–3: SamII 11:1:12:26–31"]', NULL),
  (3475101, 'OT', 'Nga''ötö I', 20, 2, 'Ba ihalö zaembu ba högö [nadu] Milikomo Dawido, ba itulo, ba 49 kilo [ana''a] wa''abua, si so mani-mani, sambua, sebua sibai böli. Ba i''anaembu Dawido; ba ebua sibai lahalö sahulu ira ba mbanua andrö.', '["Ayati 1–3: SamII 11:1:12:26–31"]', NULL),
  (3475101, 'OT', 'Nga''ötö I', 20, 3, 'Ba he niha, ösi mbanua, ba la''oloi''ö, ba ibali''ö dawa rate Dawido, sogaragazini eu ba samaku tanö ba solau eu. Ba si manö göi wolaunia ba mbanua Ndraono Gamoni bö''ö, fefu. Ba mangawuli ba Yeruzalema Dawido, awö zato fefu.', '["Ayati 1–3: SamII 11:1:12:26–31"]', NULL),
  (3475101, 'OT', 'Nga''ötö I', 20, 4, 'Ba aefa da''ö,[2] ba fasuwö zui ira ba Ndrawa Wilisiti, ba ngai Gezeri. Ba da''ö ibunu Sibekhai, banua Husa, Zifa''i, nga''ötö zebua niha andrö, ba tobali tehöndrögö ira.[3]', '["Ayati 4–8: SamII 21:18–22","Faigi 27,11","SamI 17:10"]', NULL),
  (3475101, 'OT', 'Nga''ötö I', 20, 5, 'Ba me fasuwö zamuza tö ba Ndrawa Wilisiti, ba ibunu Elihana, ono Ya''iro, Lami andrö, talifusö Goliato no, banua Gata, si so toho, sezai hao totoa.', '["Ayati 4–8: SamII 21:18–22","Faigi 27,11","SamI 17:10"]', NULL),
  (3475101, 'OT', 'Nga''ötö I', 20, 6, 'Ba me fasuwö zui ba ngai Gata, ba so ba da''ö niha sebua sibai, si önö''önö tuturu danga ba önö''önö duturu kahe, 24 fefu, nga''ötö zebua niha göi.', '["Ayati 4–8: SamII 21:18–22","Faigi 27,11","SamI 17:10"]', NULL),
  (3475101, 'OT', 'Nga''ötö I', 20, 7, 'Me i''o''aya Ndraono Gizeraeli da''ö, ba ibunu ia Yonata, tana nono Dawido, ono ga''ania Simea.[4]', '["Ayati 4–8: SamII 21:18–22","Faigi 27,11","SamI 17:10"]', NULL),
  (3475101, 'OT', 'Nga''ötö I', 20, 8, 'Nga''ötö zebua niha da''ö no mege, ba Dawido ba enoninia zamunu ya''ira.', '["Ayati 4–8: SamII 21:18–22","Faigi 27,11","SamI 17:10"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 1, 'Ba maoso Zatana, udu Ndraono Gizeraeli, ifarou Dawido, ba wangofaya Iraono Gizeraeli.[1]', '["Faigi göi SamII 24","MozII 30:12","Faigi 27:24"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 2, 'Ba imane Dawido khö Yoabi ba ba zalaŵa mbanua: Mi''ae mi''ofaya Ndraono Gizeraeli, mi''otarai Mbereseba, numalö ba Dano, ba mi''ombakha''ö khögu, ena''ö urongo ha wa''ato ira!', '["Faigi göi SamII 24","MozII 30:12","Faigi 27:24"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 3, 'Ba imane Yoabi: Yamunönö mbanuania Yehowa, ha wa''ato ira, yamube''e meotu tö zi manö, ba oi sa atö barö mbawa zokhö ya''o ira, ya''ugö sokhö ya''o, razo — ba hana sa wa i''oroi''ö da''ö sokhö ya''o? Hana wa tobali horö Ndraono Gizeraeli?[2]', '["Faigi göi SamII 24","MozII 30:12","Faigi 27:24"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 4, 'Ba lö tebulö li razo khö Yoabi, ba mofanö sa''ae Yoabi, itöröi mbanua Ndraono Gizeraeli fefu; ba noa da''ö, ba ifuli ia ba Yeruzalema.', '["Faigi göi SamII 24","MozII 30:12","Faigi 27:24"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 5, 'Ba i''ombakha''ö khö Dawido Yoabi wa''ato nisöndrania ba wangofaya sato: Iraono Gizeraeli fefu, ba no 1.100.000 zolohe baluse, ba mado Yuda, ba no 470.000 zolohe baluse. 6(Ba mado Lewi, ba mado Mbeniyami, ba lö ni''ofayania, me no anuzu dödö Yoabi goroisa razo andrö.)[3]', '["Faigi göi SamII 24","MozII 30:12","Faigi 27:24"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 7, 'Ba si fatuwu khö Lowalangi da''ö, ba ifakao Ndraono Gizeraeli.', '["Faigi göi SamII 24","MozII 30:12","Faigi 27:24"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 8, 'Ba imane Dawido khö Lowalangi: No ebua horögu, me no ulau da''ö. Ba iya''e, ba bologö dödöu ba lalö genoniu andre, noa sa elungu sibai ndra''o!', '["Faigi göi SamII 24","MozII 30:12","Faigi 27:24"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 9, 'Ba humede Yehowa khö Gado andrö, sangi''ila khö Dawido, imane:', '[]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 10, 'Ae hede khö Dawido, ömane: Da''ö niŵa''ö Yehowa: Tölu balö uŵa''ö khöu, tuyu zambalö nilaugu khöu!', '[]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 11, 'Ba möi yomo khö Dawido Gado, imane khönia: Da''ö niŵa''ö Yehowa; Tuyu khöu!', '[]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 12, 'Ma medölu fakhe lofo mbanua, ba ma tölu waŵa woloiloi labe''e udumö, ba ikhamö ami si''öli nemaliu, ba ma tölu ngaluo zi''öli Yehowa, fökhö waba, ba danö, mala''ika Yehowa, samakiko Iraono Gizeraeli ba mbanuara fefu. Ba faigi, hadia nifuligu khö zamatenge ya''o.', '[]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 13, 'Ba imane Dawido khö Gado: Sata''u sibai ndra''odo — hana na gönado tanga Yehowa, me no sahakhö sibai tödö ia; lö''ö sa omasido gönado tanga niha!', '[]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 14, 'Ba ifatörö wökhö waba ba Ndraono Gizeraeli Yehowa, ba 70.000 zi mate Iraono Gizeraeli.', '[]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 15, 'Ba ifatenge ba Yeruzalema mala''ika andrö Lowalangi, ba wamakiko ya''ira; ba barö wamakiko andrö, ba ifaigi Yehowa, ba mangesa dödönia ba wamakao andro, ba imane ba mala''ika andrö, samakiko ya''ira: Noa, böda sa''ae dangau! — ba yaŵa golayama mbasitö khö Gorana, Iraono Yebusi, so mala''ika andrö.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 16, 'Ba me ifaöga hörönia Dawido, ba i''ila mala''ika andrö, ba dalu mbanua, sara wöda ba dangania, si no isöbi, ni''oro''ö yaŵa Yeruzalema. Ba lafalögu tou ira Dawido ba satua mbanua, baru bu mbarura.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 17, 'Ba mangandrö Dawido khö Lowalangi, imane: Ya''odo zame''e oroisa ba wangofaya niha, ba tobali ya''odo zamazökhi horö, ba si no mosala sibai; ba ya''ira andrö, biri-biri andrö, ba hadia horöra? He Yehowa, Lowalangigu, khögu lau ba ba zi sawu ya''aga, ba böi lau ba mbanuau, fa böi ahori ira ba wökhö.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 18, 'Ba no ibe''e li khö Gado mala''ika Yehowa, ba wanguma''ö khö Dawido, yamöi miyaŵa, ba wama''anö naha wame''e sumange khö Yehowa, ba golayama mbasitö andrö khö Gorana, Iraono Yebusi.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475102, 'OT', 'Nga''ötö I', 21, 19, 'Ba möi miyaŵa Dawido, me no iŵa''ö khönia Gado, me no ifa''ema khönia niŵa''ö Yehowa.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 20, 'Ba ifuli ia Orana, ba i''ila mala''ika andrö, ba labini''ö ira iraononia andrö si öfa, si so khönia ba da''ö; samöbörö gandru Gorana.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 21, 'Ba me möi khö Gorana Dawido, ba ifakhölö ia Orana, ba i''ila Dawido moroi sa. Ba iröi golayama mbasitö, ba ifaöndrö ia föna Dawido, arakha irugi tou danö bawania.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 22, 'Ba imane Dawido khö Gorana: Be''e khögu golayama mbasitö andrö, ena''ö ba da''ö ufa''anö naha wame''e sumange khö Yehowa, ube''e khöu ndrohu-ndrohu mbölinia, lö u''ambösi, ena''ö döhö wökhö andrö ba mbanuada.[4]', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 23, 'Ba imane Orana khö Dawido: Halö ia khöu, yamulau zomasi ia sokhö ya''o, razo. Hiza, ube''e khöu zaŵi andrö sumange nitunu, ba famöbörö andrö, ba ube''e eu, ba gandru andrö, ba ube''e sumange ni''a — ahori ube''e khöu.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 24, 'Ba imane sa razo, Dawido, khö Gorana: Böi, u''öli, lö u''ambösi mböli; si so khöu, ba lö uhalö khö Yehowa, ba wame''e sumange nitunu, si lö böli.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 25, 'Ba 600 zekeli balaki ibe''e Dawido khö Gorana, böli naha andrö.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 26, 'Ba ifa''anö ba da''ö naha wame''e sumange Dawido, ba ibe''e zumange nitunu ba sumange fangorifi; ba me i''angaröfi li Yehowa, ba itema linia alitö moroi yaŵa ba mbanua, saekhu ba naha wame''e sumange nitunu.[5]', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 27, 'Ba iŵa''ö ba mala''ika andrö, ifuli isaembugö wödania.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 28, 'Ba me luo da''ö, me no i''ila Dawido, itema linia Yehowa ba golayama mbasitö andrö khö Gorana, Iraono Yebusi, ba mame''e-me''e sumange ia ba da''ö.', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 29, 'Ba ose Yehowa andrö, nilau Moze ba danö si mate, fabaya naha wame''e sumange, ba ba hili-hili andrö, ba Gibeona so, me luo da''o.[6]', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475102, 'OT', 'Nga''ötö I', 21, 30, 'Ba tebai i''oroma''ö ia ba da''ö Dawido, ba wangalui Lowalangi, me no tokea ia ba wöda mala''ika Yehowa andrö.[7]', '["MozIV 25:8","RazI 18:24","Faigi 16:39","Ayati 16"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 1, 'Ba imane Dawido: Ba da''e dania nahia Lowalangi, Yehowa, ba da''e naha wame''e sumange nitunu andrö, nibe''e Ndraono Gizeraeli.[1]', '["Nga''ötII 3:1","Nga''ötII 2:16","Faigi 29:1"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 2, 'Ba iŵa''ö Dawido, la''owuloi zi fatewu ba danö Ndraono Gizeraeli ba ifataro zanoto kara, ba wanoto kara si öfa sagi andrö soguna ba wolau osali Yehowa.[2]', '["Nga''ötII 3:1","Nga''ötII 2:16","Faigi 29:1"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 3, 'Ba ihöna zi''öli Dawido, nibali''ö osö-osö lagö mbawandruhö ba famakhai; ba töla ihöna, irege lö mutaha mutulo, ba eu balo, eresi,', '["Nga''ötII 3:1","Nga''ötII 2:16","Faigi 29:1"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 4, 'si tebai sa''ae la''erai; oya sibai sa la''ohe khö Dawido balo eresi banua Zidona ba banua Diro.', '["Nga''ötII 3:1","Nga''ötII 2:16","Faigi 29:1"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 5, 'Imane sa dödönia Dawido: Iraono na nonogu Selomo, sambö fa''abe''e na; ba osali andrö, nilau khö Yehowa, ba lö tola lö ebua sibai, ena''ö fangebua döi ba fa''amoadu ia ba da''ö dania, wamaigi niha bö''ö fefu. Ba da''uhöna khönia zoguna. Ba ihöna sibai Dawido, gasa-gasa wa''amatenia.[3]', '["Nga''ötII 3:1","Nga''ötII 2:16","Faigi 29:1"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 6, 'Ba humede ia khö nononia Selomo ba ibe''e li khönia, ba wolau osali khö Yehowa, Lowalangi Ndraono Gizeraeli.', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 7, 'Imane Dawido khö Zelomo: He onogu! No uŵa''ö tödögu, ya''o zolau osali, nahia döi Lowalangigu Yehowa.[4]', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 8, 'Ba humede khögu Yehowa, imane: No oya aduwa do niha öbe''e, ba no abölö wanuwöu: lö tola ya''ugö zolau nahia döigu, me no oya aduwa ba danö do niha, öbe''e, ba zanehe ndra''odo.', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 9, 'Ba tumbu khöu nono matua dania, ba niha sahono-hono dania da''ö, ba utimba khönia nemalinia fefu, fasui. Selomo sa döinia; ba fa''atulö ba fa''ahono ube''e ba Ndraono Gizeraeli, ba götönia.', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 10, 'Da''ö dania zolau osali, nahia döigu; onogu ia, ba amania ndra''o, ba u''a''aro''ö dadaoma zalaŵa khönia, ba Ndraono Gizeraeli, irugi zi lö aetu.', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 11, 'Ba iya''e sa''ae, ya''ugö onogu, ba yamutolo''ö Yehowa, ena''ö mofozu wolaumö, ba ena''ö ölau gosali andrö kho Lowalangiu, Yehowa, si mane nifabu''unia, nitandrösaigö khöu.', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 12, 'Yamube''e khöu wa''atua-tua ba fa''aboto ba dödö Yehowa, ba yamufataro razo Ndraono Gizeraeli ndra''ugö, ba ena''ö ö''o''ö goroisa Lowalangiu Yehowa.', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 13, 'Awena dania mofozu wolaumö, na ötörö sibai gamakhoita andrö, awö nihuku andrö, niŵa''ö Yehowa khö Moze, nifa''ema ba Ndraono Gizeraeli. Abe''e''ö dödöu, ya sabölö ndra''ugö! Böi busi dödöu ba böi be''e nikeani ndra''ugö![5]', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 14, 'Hiza, lö lai wamakaogu andrö, ba no uhöna zoguna ba wolau osali Yehowa andrö: 397.050.000 balaki gana''a ba 220.500.000 balaki wirö, ba töla ba si''öli, si lö mutaha mu''erai, me no fahöna manö. Ba he eu balo, ba he kara, ba no uhöna, ba önönö na dania.[6]', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 15, 'Ba he tuka — sanoto kara ba sama''anö, ba sotomo, — ba no fahöna khöu, ba sonekhe-nekhe ba ngawalö hadia ia,', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 16, 'ba ngawalö halöŵö, ba gana''a ba ba wirö ba ba döla ba ba zi''öli, ato sibai ira. Ba labu, ba yamutolo''ö Yehowa!', '["Faigi 17:1–14; 27:2–7","RazI 2:2,3","Faigi 29:2"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 17, 'Ba ibe''e li Dawido, ba zalaŵa ba Ndraono Gizeraeli fefu, ba wanolo ononia Selomo, [imane]:', '["Ayati 9; Faigi 23:25"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 18, 'Hadia, tenga no itolo ami Lowalangimi, Yehowa, ba tenga no ibe''e, lö hadia ia khömi fasui manö? Noa sa ibe''e ba dangagu niha [si tohöna] ba danö, ba lö tola lö mangalulu ira khö Yehowa ba ba mbanuania.[7]', '["Ayati 9; Faigi 23:25"]', NULL),
  (3475103, 'OT', 'Nga''ötö I', 22, 19, 'Ba mibe''e dödömi, ba era-era, ba wangalui Lowalangimi, Yehowa. Milabu, milau nahia ni''amoni''ö andrö khö Lowalangimi, Yehowa, ena''ö ba da''ö bakha mibe''e dawöla goroisa Yehowa andrö, fabaya fakake ni''amoni''ö andrö khö Lowalangi, ba gosali andrö, nilau ba döi Yehowa.', '["Ayati 9; Faigi 23:25"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 1, 'Ba me no atua Dawido, me no aföli ia wa''auri, ba ifataro razo Ndraono Gizeraeli nononia Selomo.[1]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 2, 'Ba ifalukha''ö zatua Ndraono Gizeraeli fefu, awö gere, awö Nono Lewi.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 3, 'Ba la''ofaya Nono Lewi, si no 30 fakhe ba si a''a moroi andrö; ba fa''atora, ni''ofaya, ba no 38.000, ira matua.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 4, '"Ba 24.000 nifataro ba halöŵö ba gosali Yehowa; ba 6.000, ba amaedola gumandru ba sanguhuku,', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 5, 'ba 4000, ba sanaro ba mbawandruhö ba 4000, ba sanuno Yehowa, wolau biola, nifazökhigu ba wanunö andrö." [Imanö Dawido].', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 6, 'Ba iföfö''ö ira Dawido, nga''ötö ndraono Lewi andrö, Gereso ba Kahati ba Merari.[2]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 7, 'Nga''ötö Gereso, ba Laedana ba Sime''i.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 8, 'Ba ono Laedana, ba Yehieli, si a''a, ba Setama ba Yoeli, tölu.[3]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 9, 'Ba ono Zime''i, ba Selomiti ba Hazieli ba Harana, tölu [göi]. Da''ö högö ngafu ba nga''ötö Laedana.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 10, 'Ba ono Zime''i, ba Yahata ba Sina ba Yeusi ba Beria; da''ö nono Zime''i, öfa.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 11, 'Ba si a''a Yahata, ba fanetenia Zina. Ba Yeusi ba Beria, ba no sambö ono, tobali ha sawu ira labe''e, wamataro ba halöŵö ya''ira.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 12, 'Ba ono Gahati ba Ameramo ba Yisihara ba Heberona ba Usieli, öfa.[4]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 13, 'Ba ono Gameramo, ba A''aroni ba Moze. Ba A''aroni, ba ni''oniagö, ena''ö ni''amoni''ö sibai ia, ya''ia ba iraononia, si lö mamalö-malö, ena''ö sanunu kumöyö khö Yehowa ira, götö-götö wa''ara, ba ena''ö enoninia ira ba samahowu''ö niha ba döi Yehowa.[5]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 14, 'Ba ba khö Moze andrö, enoni Lowalangi, ba ba mado Lewi te''ofaya ndraononia.[6]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 15, 'Ono Moze andrö, ba Gereso ba Eliezeri.[7]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 16, 'Ba ono Gereso, ba Sebueli, si a''a.[8]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 17, 'Ba ono Geliezeri, ba Rehabia, högö andrö. Awai nono Geliezeri, ono matua; ba oya sibai sa ndraono Rehabia.[9]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 18, 'Ba ono Yisihara, ba Selomiti, högö andrö.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 19, 'Ba ono Heberona, ba Yeriya, högö andrö, ba Amaria, fanetenia, ba Yahazieli, fanete da''ö, ba Yekameama, fanete da''ö.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 20, 'Ba ono Usieli, ba Mikha, högö andrö, ba Yisia, fanetenia.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 21, 'Ba ono Merari, ba Mali ba Musi; ba ono Mali, ba Eleazari ba Kisi.[10]', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 22, 'Ba Eleazari, ba si mate lö ono matua, ha ono alawe khönia. Ba sangai da''ö, ba akhira, ono Gisi.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 23, 'Ba ono Musi, ba Mali ba Ederi ba Yeremoto, tölu.', '["RazI 1:28–40","Faigi 6:1,2","Faigi 26:21","Faigi 5:28,29","Faigi 6:34; Heb 5:4; MozV 10:8","MozV 31:1","MozII 18:3,4","Faigi 26:24","Faigi 24:21–30","Faigi 6:4"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 24, 'Da''ö Nono Lewi, ba ngafura, högö ngafu, ha wa''ato ira ni''ofaya, dali döira, samö-samösa, nibe''e sangai halöŵö ba gosali Yehowa, si no 20 fakhe ba si a''a moroi andrö.', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 25, 'Imane sa Dawido: "No falukha wa''ahono mbanuania ibe''e Yehowa, Lowalangi Ndraono Gizeraeli, ba i''iagö sa''ae Yeruzalema, si lö mamalö-malö.[11]', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 26, 'Ba lö''ö sa''ae la''osa''osa''ö Ono Lewi nahia ose andrö, fabaya fakake andrö, soguna ba halö-halöŵö andrö ba khönia."', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 27, 'Ba nirongoda khö Dawido, safuria, ba te''ofaya Nono Lewi, i''otarai zi no 20 fakhe fa''ebua.', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 28, 'Halö-halöŵöra wanolo iraono Ga''aroni, ba halöŵöra ba gosali Yehowa famaigi-maigi olayama ba bate''e andrö, ba fangehao, ni''amoni''ö andrö fefu, awö ba halö-halöŵöra andrö ba gosali Lowalangi,', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 29, 'ba ba wamaigi roti nifaigi-faigi andrö, awö hamo si sökhi andrö ba zumange ni''a, awö kue andrö, si lö mu''aisöni, ba he gali, awö nifakoe andrö, awö zu''a-zu''a hadia ia,', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 30, 'ba he ba we''amöi awöra ero mahemolu, na so ira ba wangandrö saoha gölö khö Yehowa ba ba wanuno ya''ia, ba si manö göi, na tanö owi,[12]', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 31, 'ba ba wame''e sumange nitunu fefu, khö Yehowa, na luo sabato ba na fasulöna mbaŵa ba ba gowasa, ha wa''oya nibe''e-be''e khö Yehowa, si lö mamalö-malö, dali zi no mufakhoi andrö;', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475104, 'OT', 'Nga''ötö I', 23, 32, 'ena''ö lahalö-halö halöŵö ba nose wama''ele''ö andrö, awö halöŵö ba ni''amoni''ö, ba he halöŵö ba wanolo iraono Ga''aroni andrö, iwara; enoni ira ba nahia Yehowa andrö.', '["Yoel 4:21","Sin 92:3"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 1, 'Ba da''e ngenoli nga''ötö Ga''aroni: Ono Ga''aroni, ba Nadabi ba Abihu ba Eleazari ba Itamari.[1]', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 2, 'Ba Nadabi ba Abihu, ba si mate föna namara, lö nga''ötö, ba tobali Eleazari ba Itamari nifataro ere.[2]', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 3, 'Ba laföfö''ö ira ba nihalö-halöra Dawido ba Sadoki, nga''otö Geleazari, ba Ahimelekhi, nga''ötö Gitamari, balazi halöŵö ba nifataro ya''ira.[3]', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 4, 'Ba hiza, ba no ato högö ngafu ba nga''ötö Geleazari, moroi ba nga''ötö Gitamari; ba feleönö labe''e högö ngafu, nga''ötö Geleazari, ba ha daŵalu nga''ötö Gitamari.', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 5, 'Ba faoma lalau dahö-dahö, ba wamaigi nahara, faoma möi salaŵa ba ni''amoni''ö ba salaŵa khö Lowalangi, he nga''ötö Geleazari ba he nga''ötö Gitamari.', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 6, 'Ba itanö ba zura döira Semaya, ono Netane''eli, durutuli, ono Lewi, ba zi so razo [Dawido] ba satua ba Sadoki ere ba Ahimelekhi, ono Gabiataro, ba he högö ngafu andrö ba gere ba ba Nono Lewi. Ba lafasoli, sawu-sawu nga''ötö Geleazari ba sawu-sawu nga''ötö Gitamari, wolau dahö-dahö.[4]', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 7, 'Ba ba dahö-dahö si föföna, ba Yoyaribi zi göna; ba ba wanete da''ö,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 8, 'ba Yedaya, ba ba wanete zi dombua, ba Harimi, ba ba wanete zi tölu,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 9, 'ba Seorimi, ba ba wanete zi öfa, ba Malikhia, ba ba wanete zi lima,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 10, 'ba Miyami, ba ba wanete zi önö, ba Hakosi, ba ba wanete zi fitu, ba Ahia,[5]', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 11, 'ba ba wanete zi ŵalu, ba Yesua, ba ba wanete zi siŵa, ba Sekhania,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 12, 'ba ba wanete zi fulu, ba Eliasibi, ba ba wanete zi felezara, ba Yakimi,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 13, 'ba ba wanete zi felendrua, ba Hufa, ba ba wanete zi feledölu, ba Yesebeabi,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 14, 'ba ba wanete zi feleöfa, ba Biliga, ba ba wanete zi felelima, ba Imeri,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 15, 'ba ba wanete zi feleönö, ba Hesiri, ba ba wanete zi felewitu, ba Hafisi,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 16, 'ba ba wanete zi feleŵalu, ba Fetaya, ba ba wanete zi feleziŵa, ba Yehesikeli,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 17, 'ba ba wanete zi dua wulu, ba Yakhino, ba ba wanete zi dua wulu a zara, ba Gamuli,', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 18, 'ba ba wanete zi dua wulu a rua, ba Delaya, ba ba wanete zi dua wulu a tölu, ba Ma''asia.', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 19, 'Da''ö wamataro ya''ira ba halöŵöra, ba we''amöi ba gosali Yehowa, dali gamakhoita andrö, nifakhoi wurugöra A''aroni, oroisa Yehowa, Lowalangi Ndraono Gizeraeli khönia.', '["Faigi 23:6; 5:29","MozIII 10:1,2:12","Nga''ötII 8:14","Faigi 18:16","Luk 1:5"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 20, 'Ba ba nga''ötö Lewi bö''ö, ba nga''ötö Gameramo Zubaeli, ba nga''ötö Zubaeli Yedeya,', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 21, 'ba nga''ötö Rehabia Yisia, högö andrö,[6]', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 22, 'ba nga''ötö Yisihara Zelemoto, ba nga''ötö Zelemoto Yahata;', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 23, 'ba nga''ötö Heberona, ba Yeria, högö, ba Amaria, fanetenia, ba Yahasieli, fanete da''ö, ba Yekameama, fanete da''ö.', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 24, 'Ba nga''ötö Usieli, ba Mikha, ba nga''ötö Mikha Zamiri.', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 25, 'Ba talifusö Mikha Yisia; ba nga''ötö Yisia Zakharia.', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 26, 'Ba nga''ötö Merari, ba Mali ba Musi, awö nga''ötö nononia Ya''asia.', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 27, 'Nga''ötö Merari andrö, nga''ötö nononia Yasia, ba Sohama ba Sakuri ba Iberi.', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 28, 'Ba nga''ötö Mali, ba Eleazari; si lö nga''ötö Mali da''ö.', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 29, 'Ba nga''ötö Gisi, ba Yerame''eli.', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 30, 'Ba nga''ötö Musi, ba Mali ba Ederi ba Yerimoto. Da''ö nga''ötö Nono Lewi andrö ba ngafura andrö.', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475105, 'OT', 'Nga''ötö I', 24, 31, 'Ba ya''ira göi, ba fadahö-dahö göi, si mane iwara andrö, nga''ötö Ga''aroni, ba zi so razo, Dawido, ba Sadoki, ba Ahimelekhi, awö högö ngafu andrö ba gere ba ba nono Lewi, he högö ngafu andrö, ba he ira akhira.[7]', '["Faigi 23:17–23; 26:25","Faigi 25:8"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 1, 'Ba Dawido ba ira kumandra andrö, ba la''oniagö nga''ötö Gasafo, awö nga''ötö Yedutuno, si no amaedola zama''ele''ö, solau-lau biola nitika, side-ide ba sebua ba somözi-mözi faritia, lafataro ba halöŵöra. Ba fa''ato nifataro ba halöŵö andrö, ba[1]', '["Faigi 13:19","Faigi 21:9; Nga''ötII 35:15"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 2, 'nga''ötö Gasafo, ba Sakuru ba Yosefo ba Netania ba Asarela, iraono Gasafo, ni''ohe Gasafo, sama''ele''ö khö razo.', '["Faigi 13:19","Faigi 21:9; Nga''ötII 35:15"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 3, 'Ba nga''ötö Yedutuno, ba Gedalia ba Seri ba Yesaya ba Hazabia ba Matitia ba Sime''i, daönö, tohu-tohu danga namara Yedutuno, sama''ele''ö, ba wangandrö saoha gölö ba ba wanuno Yehowa, wolau biola nitika, sebua.', '["Faigi 13:19","Faigi 21:9; Nga''ötII 35:15"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 4, 'Ba nga''ötö Hemano: Bukia ba Matania ba Usieli ba Sebueli ba Yerimoto ba Hanania ba Hanani ba Eliata ba Gidalati ba Romamiti-Ezeri ba Yosibekasa ba Maloti ba Hotiri ba Mahazioto.', '["Faigi 13:19","Faigi 21:9; Nga''ötII 35:15"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 5, 'A''oi ono Hemano da''ö, Hemano sangi''ila andrö khö razo, ba wangebua turia, dali niŵa''ö Lowalangi. Feleöfa ibe''e Lowalangi ono matua khö Hemano, ba tölu nono alawe.[2]', '["Faigi 13:19","Faigi 21:9; Nga''ötII 35:15"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 6, 'Oi nifataro ba wanunö ba gosali da''ö, awö namara, samözi-mözi faritia ba solau-lau biola nitika, sebua ba side-ide, halöŵöra ba gosali Lowalangi, barö mbawa razo ba barö mbawa ndra Asafo Yedutuno Hemano.', '["Faigi 13:19","Faigi 21:9; Nga''ötII 35:15"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475106, 'OT', 'Nga''ötö I', 25, 7, 'Ba fa''atora, awö dalifusöra, nifataro ba wanunö andrö khö Yehowa, fa''ato duka andrö fefu, ba no 288.', '["Faigi 13:19","Faigi 21:9; Nga''ötII 35:15"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 8, 'Ba lalau dahö-dahö, ba wamöfö''ö halöŵöra, he si akhi ba he si a''a ba he samahaö ba he nifahaö, lafagölö-gölö.[3]', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 9, 'Ba ba dahö-dahö si föföna andrö, khö Gasafo, ba Yosefo zi göna, awö ndraononia, awö dalifusönia, 12 fefu. Ba ba wanete da''ö, ba Gedalia, awö dalifusönia, awö ndraononia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 10, 'Ba ba wanete zi dombua, ba Sakuru, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 11, 'Ba ba wanete zi tölu, ba Yisiri, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 12, 'Ba ba wanete zi öfa, ba Netania, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 13, 'Ba ba wanete zi lima, ba Bukia, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 14, 'Ba ba wanete zi önö, ba Yesarela, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 15, 'Ba ba wanete zi fitu, ba Yesaya, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 16, 'Ba ba wanete zi ŵalu, ba Matania, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 17, 'Ba ba wanete zi siŵa, ba Sime''i, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 18, 'Ba ba wanete zi fulu, ba Asare''eli, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 19, 'Ba ba wanete zi felezara, ba Hasabia, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 20, 'Ba ba wanete zi felendrua, ba Subaeli, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 21, 'Ba ba wanete zi feledölu, ba Matitia, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 22, 'Ba ba wanete zi feleöfa, ba Yeremoto, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 23, 'Ba ba wanete zi felelima, ba Hanania, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 24, 'Ba ba wanete zi feleönö, ba Yosibekasa, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 25, 'Ba ba wanete zi felewitu, ba Hanani, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 26, 'Ba ba wanete zi feleŵalu, ba Maloti, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 27, 'Ba ba wanete zi feleziŵa, ba Eliata, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 28, 'Ba ba wanete zi dua wulu, ba Hotiri, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 29, 'Ba ba wanete zi dua wulu a sara, ba Gidaliti, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 30, 'Ba ba wanete zi dua wulu a rua, ba Mahazioto, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475106, 'OT', 'Nga''ötö I', 25, 31, 'Ba ba wanete zi dua wulu a tölu; ba Romamiti-Ezeri, awö ndraononia, awö dalifusönia, 12 fefu.', '["Faigi 24:31"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 1, 'Ba ba wamöfö''ö sanaro ba mbawandruhö, ba nga''ötö Gora, ba Meselemia, ono Goresi, nga''ötö Gasafo.[1]', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 2, 'Ba ono Meselemia, ba Sakharia, si a''a, ba Yediaeli, fanetenia, ba Sebadia, fanete zi darua, ba Yatenieli, fanete zi datölu,', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 3, 'ba Elama, fanete zi daöfa, ba Yohanano, fanete zi dalima, ba Eliunai, fanete zi daönö.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 4, 'Ba ono Gobedi-Edomo, ba Semaya, si a''a, ba Yosabada, fanetenia, ba Yoa, fanete zi darua, ba Sakhara, fanete zi datölu, ba Netane''eli, fanete zi daöfa, ba Amieli,', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 5, 'fanete zi dalima, ba Isasari, fanete zi daönö, ba Feguleta''i, fanete zi dafitu — noa sa ifahowu''ö ia Lowalangi.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 6, 'Ba mo''ono göi nononia Semaya, ono matua, salaŵa ba ngafura, dania, me no niha sabölö ira.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 7, 'Ono Zemaya andrö, ba Otini ba Refaeli ba Obedi ba Elisabada, talifusönia, niha sabölö, ba Elihu ba Semakhia.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 8, 'Oi nga''ötö Gobedi-Edomo da''ö, ya''ira ba onora ba talifusöra, niha sabölö, si faduhu dödöda ba halöŵöra, 62 nga''ötö Gobedi-Edomo.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 9, 'Ba so göi nono Mezelemia, ono matua, ba talifusönia, niha sabölö, 18 fefu.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 10, 'Ba ono Hoza, nga''ötö Merari, ba Simeri, högö (me lö''ö sa''ae si a''a, andrö ibali''ö högö ia amania),', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 11, 'ba Hilikia, fanetenia, ba Tebalia, fanete zi darua, ba Sakharia, fanete zi datölu. Ono Hoza andrö ba talifusönia, ba 13 fefu.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 12, 'Da''ö ngenoli zanaro ba mbawandruhö, högö watalifusöta andrö, ba awö niwara ira ba halöŵö andrö, ba nifataro ya''ira ba gosali Yehowa.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 13, 'Ba sambu-sambua bawandruhö, ba lalau dahö-dahö, laföfö''ö ngafu [zanaro], he ba zi akhi, ba he ba zi a''a.[2]', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 14, 'Ba [ba mbawandruhö] tanö ba gatumbukha luo, ba Selemia zi göna. Ba he khö nononia Sakharia, niha satua-tua, anofula, ba lalau göi dahö-dahö, ba tanö yöu khönia.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 15, 'Ba tanö raya, ba khö Gobedi-Edomo, ba ba ndraononia, ba ba naha girö-girö.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 16, 'Ba khö Zufimi ba khö Hoza, ba [ba mbawandruhö] tanö ba gaekhula luo, awö ba mbawandruhö Salekheti, ba newali miyaŵa; nifa''oli zanaro.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 17, 'Tanö ba gatumbukha luo, ba daönö Nono Lewi, ba tanö yöu, ba daöfa ma''ökhö, ba tanö raya, badaöfa ma''ökhö, ba ba naha girö-girö, ba daru-darua;', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 18, 'ba ba Warabara, tanö ba gaekhula luo, ba daöfa ba newali ba darua ba Warabara.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 19, 'Da''ö ngenoli zanaro, andrö, nga''ötö Gora, awö nga''ötö Merari.', '["Nga''ötII 8:14; 35:15","Faigi 25:8"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 20, 'Ba iwara, Ono Lewi andrö, ba samaigi-maigi girö-girö andrö ba gosali Lowalangi, awö nihöna andrö, ame''ela ni''amoni''ö:', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 21, 'Nga''ötö Laedana, Laedana ma''uwu Gereso, högö ngafu nga''ötö Laedana, ma''uwu Gereso,[3]', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 22, 'ma''uwu Yehieli andrö, Setama ba akhinia Yoeli zamaigi-maigi girö-girö andrö ba gosali Yehowa.', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 23, 'Ba ba ma''uwu ndra Ameramo, Yisihara, Heberona, Usieli,', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 24, 'ba Sebueli andrö, ono Gereso, ma''uwu Moze, högö zamaigi-maigi girö-girö.[4]', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 25, 'Ba ba niwara andrö, ma''uwu Geliezeri, ba Rehabia nono da''ö, ba ono da''ö, ba Yesaya, ba ono da''ö, ba Yoramo, ba ono da''ö, ba Sikhiri, ba ono da''ö, ba Selomiti.', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 26, 'Ba Selomiti andrö, ba talifusönia zamaigi-maigi girö-girö fefu, ame''ela ni''amoni''ö andrö, ni''amoni''ö razo, Dawido, ba högö ngafu andrö ba solohe ngahönö ba solohe ngaotu, ba ira kumandra andrö,', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 27, '(nihalöra ba wanuwö, sahulu ira, ba no la''amoni''ö tolo-tolo ba gosali Yehowa),', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 28, 'fefu hadia ia ni''amoni''ö Zamueli, sangi''ila andrö, ba Saulo, ono Gisi, ba Abineri, ono Neri, ba Yoabi, ono Zeruya, — ni''amoni''ö andrö fefu, ba barö mbawa Zelomiti andrö so, ba barö mbawa ndra talifusönia.', '["Faigi 23:8","Faigi 23:16"]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 29, 'Ba ma''uwu Yisihara andrö, Kenania ba iraononia, ba no nifataro ba halöŵö baero, ba Ndraono Gizeraeli — kumandru ba sanguhuku.', '[]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 30, 'Ba ma''uwu Heberona andrö Hazabia ba talifusönia, niha sabölö, 1700, ba no mube''e samatörö Iraono Gizeraeli ba zi tambai Yoridano, tanö ba gaekhula luo, ba ngawalö halöŵö khö Yehowa, fefu, ba ba ngawalö halöŵö khö razo.', '[]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 31, 'Ma''uwu Heberona Yeria andrö, högö ma''uwu Heberona, ba watalifusöta khöra ba ba ngafura (me arakha 40 fakhe salaŵa Dawido, te''alui ira, ba tesöndra ba khöra niha sabölö, ba Yaezeri, ba danö Gileadi),', '[]', NULL),
  (3475107, 'OT', 'Nga''ötö I', 26, 32, 'ba iwara, sabölö, 2.700 högö ngafu; da''ö nifataro razo, Dawido, samatörö mado Rubeno ba mado Gado ba si matonga mado Manase, ba ngawalö hadia ia khö Lowalangi, fefu, ba ba ngawalö khö razo.', '[]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 1, 'Ba da''e Ndraono Gizeraeli andrö, ha wa''ato ira, högö ngafu, ba solohe ngahönö ba solohe ngaotu ba durutuli khöra, enoni razo, ba halöŵö ngenoli andrö, sara-sara waŵa we''asora, ba aheta, döfi fasui, 12 waŵa; 24.000 niha zangenoli.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 2, 'Ngenoli si föföna andrö, ba mbaŵa si föföna, ba Yasobeamo zolohe, ono Zabadieli, ba 24.000 niha ba ngenoli khönia.[1]', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 3, 'Nga''ötö Weresi ia, högö zolohe andrö fefu, ba mbaŵa si föföna.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 4, 'Ba ba ngenoli ba mbaŵa si dua, ba Eleazari zolohe, ono Doda''i andrö, ma''uwu Gahohi; ba Mikeloti mandru ba ngenoli khönia, 24.000 niha.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 5, 'Ba solohe ngenoli si tölu, ba mbaŵa si tölu, ba Benaya, ono Yoyada ere, högö ia; ba 24.000 niha ba ngenoli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 6, 'Da''ö Mbenaya andrö, sabölö ba zi tölu ngafulu; ba mandru ba ngenolinia nononia Amisabada.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 7, 'Ba fanete zi tölu, ba mbaŵa si öfa, ba Azaheli, akhi Yoabi, ba fangalinia nononia Sebadia, ba 24.000 niha ba ngenoli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 8, 'Ba fanete zi öfa, ba mbaŵa si lima, ba salaŵa andrö, Samihuti, banua Yiserahi; ba 24.000 niha ba ngenoli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 9, 'Ba fanete zi lima, ba mbaŵa si önö, ba Ira, ono Ike, banua Dekoa; ba 24.000 niha ba ngenoli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 10, 'Ba fanete zi önö, ba mbaŵa si fitu, ba Helesi, banua Welono, mado Geferayi; ba 24.000 niha ba ngenoli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 11, 'Ba fanete zi fitu, ba mbaŵa si ŵalu, ba Sibekhai, banua Husa, ma''uwu Zera; ba 24.000 niha ba ngenoli khönia[2]', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 12, 'Ba fanete zi ŵalu, ba mbaŵa si siŵa, ba Abiezeri, banua Ganatoti, mado Mbeniyami; ba 24.000 niha ba ngenoli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 13, 'Ba fanete zi siŵa, ba mbaŵa si fulu, ba Maharai, banua Netofa, ma''uwu Zera: ba 24.000 niha ba ngenöli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 14, 'Ba fanete zi fulu, ba mbaŵa si felezara, ba Benaya, banua Wiratono, mado Geferayi; ba 24.000 niha ba ngenoli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 15, 'Ba fanete zi felezara, ba mbaŵa si felendrua, ba Helida''i, banua Netofa, ma''uwu Gotenieli; ba 24.000 niha ba ngenoli khönia.', '["Ayati 2–15: Faigi göi 11:11–31","Faigi 20:4"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 16, 'Ba da''e nibe''e salaŵa mado Ndraono Gizeraeli: Salaŵa mado Rubeno, ba Eliezeri, ono Zikhiri, ba ba mado Zimeoni, ba Sefatia, ono Ma''akha,', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 17, 'ba ba mado Lewi, ba Hasabia, ono Gemueli, ba ba nga''ötö Ga''aroni,', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 18, 'ba Sadoki, ba ba mado Yuda, ba Elihu, ga''a Dawido, ba ba mado Isasari, ba Omeri, ono Mikhaeli,', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 19, 'ba ba mado Zebuloni, ba Yisimaya, ono Gobadia, ba ba mado Nafetali, ba Yerimoto, ono Gaserieli, ba ba mado Geferayi, ba Hosea,', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 20, 'ono Gasasia, ba ba zi matonga mado Manase, ba Yoeli, ono Wedaya,', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 21, 'ba ba zi matonga mado Manase, ba danö Gileadi, ba Ido, ono Zakharia, ba ba mado Mbeniyami ba Ya''asieli, ono Gabineri,', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 22, 'ba ba mado Dano, ba Asere''eli, ono Yerohamo. Da''ö zalaŵa mado Ndraono Gizeraeli andrö.', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 23, 'Ba ha wa''ato zi lö 20 fakhe na, ba lö i''ofaya Dawido, me no ifabu''u Yehowa, i''oya''ö Ndraono Gizeraeli, timba ndröfi ba mbanua yaŵa wa''oya.', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 24, 'No ibörötaigö wangofaya Yoabi, ono Zeruya, ba lö ni''o''ozuinia, me no tesao wönu [Lowalangi] ba Ndraono Gizeraeli; ba fa''ato andrö, ba lö mutanö ba zura hikaya razo Dawido.[3]', '["Faigi 21:14"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 25, 'Ba samaigi-maigi girö-girö andrö khö razo, ba Asimaweti, ono Adieli, ba girö-girö bua nowi ba ba mbanua sebua ba ba mbanua side-ide ba ba hati misa, ba Yonata, ono Usia.', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 26, 'Ba sohalöŵö ba danö, sangahalö, ba Eseri, ono Gelubi,', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 27, 'zamaigi-maigi, ba kabu nagu, ba Sime''i, banua Rama; ba hadia zi so ösi nagu, ba kabu nagu andrö, ba Sabidi, banua Zifimi.', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 28, 'Ba kabu zai ba kabu ara, ba ndraso, ba Ba''ali-Hanano, banua Gaderi, ba fanikha zai, nihöna, ba Yoasi zamaigi-maigi.', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 29, 'Ba saŵi andrö, nikuloi ba Zarona ba Siterai, banua Zarona, ba saŵi ba ndraso misa, ba Safati, ono Adelai,', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 30, 'ba ondra, ba Obili, Iraono Zima''eli, ba kalide si alawe, ba Yedeya,', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 31, 'banua Meronoto, ba biri-biri ba nambi, ba Yasisi, Dawa Hagara, zamaigi-maigi. Oi si no amaedola högö mandru ba gokhöta razo Dawido.', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 32, 'Ba Yonata, tana nama Dawido, ba no anofula; no niha satua-tua ba sangila amakhoita; ba Yehieli, ono Hakhimono, ba no samahaö iraono razo.', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 33, 'Ba Ahitofeli, ba anofula razo göi, ba Huza''i, ma''uwu Garakhi, ba no si fahuwu khö razo.[4]', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475108, 'OT', 'Nga''ötö I', 27, 34, 'Ba fanete Gahitofeli, ba Yoyada, ono Mbenaya, ba Abiataro. Ba Yoabi, ba no kumandra sebua khö razo.[5]', '["SamII 15:12; 15:27","SamII 8:16"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 1, 'Ba ifalukha''ö Dawido zatua Ndraono Gizeraeli, awö högö madora ba solohe ngenoli genoni razo andrö, ba kumandra ngahönö ba kumandra ngaotu ba högö mandru ba gokhöta razo ba ba gurifönia ba ba gurifö ndraononia ba enoninia yomo ba saradadu andrö ba dozi solohe baluse; ba Yeruzalema walukhata andrö.', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 2, 'Ba maoso Dawido, ba imane: Mifondrondrongo, ya''ami ira talifusögu ba ya''ami banuagu! No uŵa''ö tödögu, ulau nahia sahono dawöla goroisa Yehowa andrö ba baku-baku gahe andrö khö Lowalangida, ba no uhönagö ufaigi hadia ia, ba wolau ya''ia.[1]', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 3, 'Ba no imane khögu Lowalangi: Tenga ya''ugö zolau osali ba döigu andrö, me no niha sanuwö-nuwö ndra''ugö, ba me no aduwa ndro niha öbe''e.[2]', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 4, 'Ba no ituyu ndra''o Yehowa, Lowalangi Ndraono Gizeraeli, ba zi sawu ya''aga, ena''ö si lö mamamamalö-malö razo ndra''o ba Ndraono Gizeraeli. Me no mado Yuda ituyu salaŵa, ba ba mado Yuda andrö, ba si sawu ya''aga, ba ba ndraono namagu, ba ya''odo zomasi ia ibe''e razo Ndraono Gizeraeli fefu.[3]', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 5, 'Ba ba ndraonogu andrö fefu — no oya nibe''e Yehowa khögu ono matua — ba onogu Selomo ituyu, ena''ö ya''ia zidadao ba dadaoma zalaŵa andrö khö Yehowa, razo Ndraono Gizeraeli.', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 6, 'No imane khögu: Onou Selomo andrö zolau osali, awö golayama andrö khögu; noa sa ya''ia nituyugu onogu, ba amania sa''ae ndra''ö.', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 7, 'Ba u''aro''ö wa''arazonia, si lö mamalö-malö, na lö ibulö''ö wolo''ö oroisagu, awö nifakhoigu andrö, si mane ma''ökhö.', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 8, 'Ba hiza, ba zanehe Ndraono Gizeraeli fefu, banua Yehowa andre, ba ba zamondrongo Lowalangida; Mi''o''ö sibai goroisa Yehowa, Lowalangimi, fefu, ena''ö si lö tebulö ba danö si sökhi andre ami, ba ena''ö ondröitami ba nga''ötömi ia, götö-götö wa''ara.', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 9, 'Ba ya''ugö, onogu Selomo, ba ya''aboto ba dödöu Lowalangi namau, ba iagö enoninia, moroi si''aikö ba dödöu, moroi ba dödö sedöna! Isekhegö sa dödö fefu Yehowa, ba ahori i''ila nikhoi dödö, awö gera-era. Na ö''alui ia, ba ibe''e nisöndrau ia; ba na ö''erogö ia, ba itibo''ö ndra''ugö, si lö fulitö.[4]', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475110, 'OT', 'Nga''ötö I', 28, 10, 'Ba faigi, he öwisa! Noa sa ituyu ndra''ugö Yehowa, ba wolau omo, ni''amoni''ö; ba labu, abe''e''ö dödöu!', '["Faigi 22:7–10","Sam. II, 7:5","MozI 49:10; SamI 16:1,12","SamI 16:6; RazI 8:39; Sin 7:10"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 11, 'Ba ibe''e Dawido khö nononia Selomo duma-duma golayama nifosagö andrö ba duma-duma gosali, he wisa goto''oto ba he wisa mbate''e girö-girö andrö ba bate''e ba zi sagötö, ba bakha ba nösi nomo, awö nahia [dawöla, fabaya] lagö andrö,[5]', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 12, 'ba duma-duma hadia ia fefu zi so ba dödönia: olayama gosali Yehowa, ba bate''e andrö fefu, fasui, ba bate''e girö-girö ba gosali Lowalangi ba bate''e nihöna andrö, ame''ela ni''amoni''ö;', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 13, 'awö wama''oli gere ba Ono Lewi, ba he wisa halöŵö ba gosali Yehowa fefu ba duma-duma wakake fefu, soguna ba halöŵö ba gosali Yehowa.', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 14, 'Ba ana''a, ha wa''ebua moguna ba wamazökhi fakake andrö, ba ngawalö halöŵö andrö, ba soguna ba wakake firö andrö fefu, ha wa''ebua zoguna ba wakake andrö, ba ngawalö halöŵö andrö.', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 15, 'Ba soguna ba naha wandru ana''a andrö, fabaya fandru ana''a, ha wa''abua naha wandru andrö, sambu-sambua, fabaya fandrunia, ba ba naha wandru firö, ha wa''abua naha wandru andrö, sambu-sambua, fabaya fandru, dali woguna naha wandru andrö fefu.', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 16, 'Ba ana''a soguna ba wamazökhi meza andrö, ha uga, meza roti nifaigi-faigi andrö, ba firö ba meza firö,', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 17, 'ba soguna ba garafu andrö ba ba wiga ba ba gendri, balaki, ba ba mako balaki andrö, ha uga nifazökhi, awö zoguna ba mako firö andrö.', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 18, 'Ba balaki, ha wa''ebua moguna ba naha wanunu kumöyö, ba duma-duma gureta andrö, kerubi balaki, samologö afira, ba samalugö tawöla goroisa Yehowa andrö.', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 19, '"Ba zura nisura danga Yehowa so da''ö fefu; no ifahaö ndra''o ba duma-duma andro fefu, he wisa wolau". [Imano Dawido].', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 20, 'Ba imane na Dawido khö nononia Selomo: Abe''e''ö dödöu, ya sabölö ndra''ugö, ba labu ba halöŵö! Böi busi dödöu, ba böi be''e nikeani ndraugö; itolo''ö sa Lowalangi, Yehowa, Lowalangigu. Lö iböda dangania ba lö iböhöli ndra''ugö, irege no awai fefu nilau andrö ba halöŵö andrö ba gosali Yehowa.[6]', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475110, 'OT', 'Nga''ötö I', 28, 21, 'Ba hiza ngenoli gere andrö, awö ngenoli Nono Lewi, ba halöŵö andrö fefu ba gosali Lowalangi; hadia ia halöŵö, ba no so khöu niha, ha niha, si no aoha ölö, ba wolau hadia ia fefu, ba wa''atukara andrö, ba si manö göi zatua andrö, awö niha sato fefu, ba lö mamalö-malö, wa samondrongo liu ira.', '["MozII 25:9","Faigi 22:13; MozV 31:6"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 1, 'Ba imane na razo, Dawido, ba niha sato fefu: Onogu Selomo andre, ba ha ya''ia nituyu Lowalangi; ba no iraono na, sambö fa''abe''e; ba halöŵö andrö, ba no sebua sibai; tenga sa nahia niha dania gödo andrö, no nahia Lowalangi, Yehowa.[1]', '["Faigi 22:5","RazI 9:28; MozII 35:5","MozII 35:27"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 2, 'Ba no u''ositölagö wangöhöna balazo gosali Lowalangigu andrö ana''a, ba gama-gama ana''a andrö, ba firö ba gama-gama firö, ba töla ba gama-gama töla, ba si''öli ba gama-gama si''öli, ba eu ba gama-gama eu, ba he batu una, ba kara lesi, kara saitö, ba kara sola''a-la''a ba feremata, hadia ia, ba kara maremara, oya sibai.', '["Faigi 22:5","RazI 9:28; MozII 35:5","MozII 35:27"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 3, 'Ba baero ö, ba ube''e na balazo gosali Lowalangigu si so khögu, ana''a ba firö, börö wa''omuso dödögu andrö ba gosali Lowalangigu andrö, lö lai fefu zi no uhöna balazo ni''omoni''ö andrö: 42.376 fiku gana''a ba 4.927 fiku wirö, si no mutunu, ba wamo''uli bagolö tanö bakha,', '["Faigi 22:5","RazI 9:28; MozII 35:5","MozII 35:27"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 5, 'ba ana''a ba gama-gama ana''a andrö ba firö ba gama-gama firö, ba ba nilau duka andrö dania, fefu. Ba ha niha zaona ölö, ma''ökhö, ba wame''e khö Yehowa?[2]', '["Faigi 22:5","RazI 9:28; MozII 35:5","MozII 35:27"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 6, 'Ba aoha gölö högö ngafu, ba högö mado Ndraono Gizeraeli ba högö ngahönö andrö ba högö ngaotu ba satua genoni razo,', '["Faigi 22:5","RazI 9:28; MozII 35:5","MozII 35:27"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 7, 'ba labe''e, balazo ba wolau osali Lowalangi andrö, ba 3.960 fiku gana''a ba 10.000 rufia balaki ba 7.040 fiku wirö ba 18.000 fiku döla ba 100.000 fiku zi''öli.', '["Faigi 22:5","RazI 9:28; MozII 35:5","MozII 35:27"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 8, 'Ba si so feremata, ba ibe''e girö-girö ba gosali, ni''irö''ö Yehieli, ma''uwu Gereso.[3]', '["Faigi 22:5","RazI 9:28; MozII 35:5","MozII 35:27"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 9, 'Ba somuso tödö niha sato, ba wa''oböwöra andrö, me no moroi si''aikö ba dödöra labe''e khö Yehowa, saoha gölö, ba omuso sibai göi dödö razo Dawido.', '["Faigi 22:5","RazI 9:28; MozII 35:5","MozII 35:27"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 10, 'Ba isuno Yehowa Dawido ba zanehe zato fefu; imane Dawido: "Nisuno ndra''ugö, yaugo Yehowa, Lowalangi wurugöma Izeraeli, götö-götö wa''ara!', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 11, 'Khöu wa''ebua, ya''ugö Yehowa, ba khöu wa''abölö, awö lakhömi, awö wa''ebua doi, awö wa''asalaŵa, me no khöu fefu hadia ia ba zorugo ba ba guli danö. Khöu wa''asalaŵa, ya''ugö Yehowa, ba dangau so zamali''ö högö niha fefu ya''ia.[4]', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 12, 'Ba fo''ana''a ba fa''ateturia, ba ba khöu moroi; ya''ugö zamatörö fefu hadia ia. Ba ba dangau so wa''abe''e ba fa''abölö, ba he fangabe''e ba he fangabölö niha.[5]', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 13, 'Ba iada''e ya''ugö Lowalangima, ba ma''andrö saoha gölö khöu ba masuno döimö, si sökhi sibai andrö.', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 14, 'Ha niha sa ndra''odo andre, ba hadia mbanuagu andre, wa tola ena''ö mabe''e da''ö fefu, saoha gölö? Moroi ba khöu fefu hadia ia, ba moroi ba dangau wa no mabe''e ia khöu.', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 15, 'Tome sa ndra''aga fönau ba si fatewu, si mane ira tuama fefu. Hulö lumö nosoma ba guli danö, lö tötönafö.[6]', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 16, 'He Yehowa, Lowalangima, ana''a andrö fefu, si no mahöna ba wolau osali khöu — osali döimö andrö ni''amoni''ö — ba ba dangau moroi, no khöu ia fefu!', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 17, 'Ba no aboto ba dödögu, ya''ugö Lowalangigu, wa no sanekhegö tödö ndra''ugö, awö wa fa''adölö dödö zomasi''ö. Ya''odo andre, ba no sadölö tödö wame''e da''ö fefu, saoha gölo, ba iya''e, ba somuso tödö ndra''o, me no u''ila, noa göi aoha gölö mbanuamö andre, si so ba da''e, wame''e.[7]', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 18, 'He Yehowa, Lowalangi ndra tuama, Aberahamo, Iza''aki, Yakobo, böi be''e tebulö dödö si manö ba era-era si manö ba dödö mbanuau andre, ba ba khöu dönisi dödöra.', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 19, 'Ba khö nonogu Selomo, ba tödö sangendröna be''e khönia, ena''ö itöngöni goroisamö ba famaduhu''ömö ba amakhoitamö, ba ena''ö ifalua da''ö no mege, fefu, wolau gödo andrö, ni''oladaegu sa''ae."', '["Mat 6:13; Tim. I, 1:17; Fam 4:11; 5:13","Nga''ötII 20:6","Sin 39,13; 102:12; Yob 8:9; 14:2; Heb 11:13","Faigi 28:9"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 20, 'Ba imane Dawido ba zato: Misuno Lowalangimi, Yehowa! Ba lasuno Yehowa, Lowalangi ndra tuara, sato fefu, lafaöndrö ira, ba lafalögu tou ira föna Yehowa ba föna razo.', '["RazI 1:38 b.t.; Faigi 23:1","Faigi 28:5; RazI 1:35,39","RazI 3:13; Nga''ötII 1:1"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 21, 'Ba mahemolu ö, ba lahulö wongi wanaba sumange, khö Yehowa, labe''e khönia zumange nitunu: 1000 nono zaŵi si matua, ba 1000 mbiri-biri si matua ba 1000 nono mbiri-biri, awö zumange nibadu, nifao ba da''ö, ba sumange nitaba, oya sibai, nibe''e Ndraono Gizeraeli fefu.', '["RazI 1:38 b.t.; Faigi 23:1","Faigi 28:5; RazI 1:35,39","RazI 3:13; Nga''ötII 1:1"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 22, 'Ba manga-manga ira ba labadu-badu hadia ia, me luo da''ö, föna Yehowa, omuso sibai dödöra; ba samuza tö lafataro razo Zelomo, ono Dawido, ba labayoini ia khö Yehowa, labali''ö samatörö, ba labayoini göi Zadoki andrö, labali''ö ere.[8]', '["RazI 1:38 b.t.; Faigi 23:1","Faigi 28:5; RazI 1:35,39","RazI 3:13; Nga''ötII 1:1"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 23, 'Ba dumadao sa''ae ba dadaoma zalaŵa andrö khö Yehowa Zelomo, razo ia, fangali namania Dawido, ba mofozu nilaunia, ba la''o''ö khönia Iraono Gizeraeli fefu.[9]', '["RazI 1:38 b.t.; Faigi 23:1","Faigi 28:5; RazI 1:35,39","RazI 3:13; Nga''ötII 1:1"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 24, 'He kumandra andrö fefu, awö zaradadu andrö, ba he ono razo Dawido, fefu, ba möi barö mbawa razo Selomo.', '["RazI 1:38 b.t.; Faigi 23:1","Faigi 28:5; RazI 1:35,39","RazI 3:13; Nga''ötII 1:1"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 25, 'Ba ebua sibai lakhömi Zelomo, ibe''e Yehowa, ba zanehe Ndraono Gizeraeli fefu; fa''asalaŵa sebua turia ibe''e khönia, si lö irai ba razo Ndraono Gizeraeli, fönania[10]', '["RazI 1:38 b.t.; Faigi 23:1","Faigi 28:5; RazI 1:35,39","RazI 3:13; Nga''ötII 1:1"]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 26, 'Ba no razo Ndraono Gizeraeli fefu mege Dawido, ono Giza''i. 27öfa wulu fakhe wa''ara razo ia ba Ndraono Gizeraeli. Mewitu fakhe ba Heberona, ba ba Yeruzalema, ba 33 fakhe[11]', '["RazI 2:11","Faigi 21:9."]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 28, 'Ba mate ia, me no biha wa''atua, me no aföli ia wa''auri ba fo''ana''a ba sumange; ba ononia Selomo zi tobali razo, fangalinia.', '["RazI 2:11","Faigi 21:9."]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 29, 'Ba hikaya razo Dawido andrö, he hikayania me ono matua ia, ba he safuria andrö, ba no mutanö ba zura hikaya andrö, nisura Zamueli, sangi''ila andrö, ba ba zura hikaya khö Natano, sama''ele''ö, ba ba zura Gado sangi''ila,[12]', '["RazI 2:11","Faigi 21:9."]', NULL),
  (3475111, 'OT', 'Nga''ötö I', 29, 30, 'awö wa''abölönia, fa''abölö razo, ba folaunia, nifolau zabölö, ba hadia ia ba götönia andrö, ba ba götö Ndraono Gizeraeli ba ba götö gamatöröŵa niha baero, me luo da''ö.', '["RazI 2:11","Faigi 21:9."]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 1, 'Selomo, ono Dawido, ba i''aro''ö wa''arazonia, ba itolo ia Lowalanginia Yehowa, ebua sibai lakhömi ibe''e.[1][2]', '["Ayati 1–6: RazI 3:1–4","RazI 2:12,46","Nga''ötI 16:39; 21:29","SamII 6:17; Nga''ötI 13:6; 15:3,28; 16:1","MozII 38:1–8; Ayati 3"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 2, 'Ba ibe''e goroisa Selomo ba Ndraono Gizeraeli fefu, ba ba zolohe ngahönö ba ba zolohe ngaotu ba ba zanguhuku ba ba zalaŵa fefu, ba Ndraono Gizeraeli fefu, ba ba högö ngafu andrö,', '["Ayati 1–6: RazI 3:1–4","RazI 2:12,46","Nga''ötI 16:39; 21:29","SamII 6:17; Nga''ötI 13:6; 15:3,28; 16:1","MozII 38:1–8; Ayati 3"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 3, 'i''ohe zato fefu Selomo, awönia ba hili-hili andrö ba Gibeona. Ba da''ö sa so nose wama''ele''ö andrö khö Lowalangi, nilau Moze, enoni Yehowa, ba danö si mate.[3]', '["Ayati 1–6: RazI 3:1–4","RazI 2:12,46","Nga''ötI 16:39; 21:29","SamII 6:17; Nga''ötI 13:6; 15:3,28; 16:1","MozII 38:1–8; Ayati 3"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 4, '(Ba tawöla andrö khö Lowalangi, ba no i''ohe miyaŵa Dawido, moroi ba Giriati Yeari, no ibe''e ba nahia andrö, nilaunia nahania; noa sa ifazökhi nosenia ba Yeruzalema).[4]', '["Ayati 1–6: RazI 3:1–4","RazI 2:12,46","Nga''ötI 16:39; 21:29","SamII 6:17; Nga''ötI 13:6; 15:3,28; 16:1","MozII 38:1–8; Ayati 3"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 5, 'Ba he naha wame''e sumange töla andrö, nifazökhi Mbesaleeli, ono Guri, ma''uwu Huri, ba ba da''ö so, föna nose Yehowa, ba la''alui [Yehowa, ba da''ö] Selomo, awö niha sato.[5]', '["Ayati 1–6: RazI 3:1–4","RazI 2:12,46","Nga''ötI 16:39; 21:29","SamII 6:17; Nga''ötI 13:6; 15:3,28; 16:1","MozII 38:1–8; Ayati 3"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 6, 'Ba ibe''e zumange ba da''ö Selomo, ba naha wame''e sumange töla andrö, föna Yehowa, föna nose wama''ele''ö andrö, 1000 ibe''e sumange, nitunu, ba detenia.', '["Ayati 1–6: RazI 3:1–4","RazI 2:12,46","Nga''ötI 16:39; 21:29","SamII 6:17; Nga''ötI 13:6; 15:3,28; 16:1","MozII 38:1–8; Ayati 3"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 7, 'Ba ba zi bongi andrö,[6] ba i''oroma''ö ia khö Zelomo Lowalangi, imane khönia: Andrö zomasi''ö ube''e khöu![7]', '["Ayati 7–12: RazI 3:5–15","RazI 3:5 b.t.","MozI 13:16"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 8, 'Ba imane Selomo khö Lowalangi: No ebua sibai dödöu khö namagu Dawido ba no öbali''ö fangalinia razo ndra''odo.', '["Ayati 7–12: RazI 3:5–15","RazI 3:5 b.t.","MozI 13:16"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 9, 'Ba ena''ö na itörö nifabu''umö khö namagu Dawido, ya''ugö Yehowa, Lowalangi! Noa sa öfataro razo ndra''odo, razo niha si no ato sibai, timba wa''oya ngawua gawu nasi ba danö.[8]', '["Ayati 7–12: RazI 3:5–15","RazI 3:5 b.t.","MozI 13:16"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 10, 'Ba be''e sa''ae khögu wa''atua-tua ba fa''aboto ba dödö, ena''ö usöndra lala, he uwisa ba niha andre; ha niha sa ena''ö zangila mamatörö banuau andre, si no ato sibai?', '["Ayati 7–12: RazI 3:5–15","RazI 3:5 b.t.","MozI 13:16"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 11, 'Ba imane Lowalangi khö Zelomo: Me no da''ö zi so ba dödöu, ba me tenga fa''ebua gana''a ba tenga girö-girö ba tenga sumange ba tenga famunu si fa''udu khöu ni''andröu, ba me tenga göi fa''anau nosou; me no fa''atua-tua ba fa''aboto ba dödö ö''andrö, ena''ö ö''ila öfatörö mbanuagu andrö, ba nifatarogu razo ya''ugö,', '["Ayati 7–12: RazI 3:5–15","RazI 3:5 b.t.","MozI 13:16"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 12, 'ba nibe''e khöu wa''atua-tua ba fa''aboto ba dödö. Ba he fa''ebua gana''a göi ba girö-girö ba sumange, ba utehe khöu, irege zi lö irai ba razo bö''ö fönau, ba si lö''ö sa''ae göi dania furiu.', '["Ayati 7–12: RazI 3:5–15","RazI 3:5 b.t.","MozI 13:16"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 13, 'Ba iröi hili-hili andrö ba Gibeona Selomo, [naha andrö] föna nose wama''ele''ö, ifuli ia ba Yeruzalema, ba razo Ndraono Gizeraeli ia.', '["Ayati 14–17: RazI 10:26–29","RazI 4:26; 10:26 b.t.","Faigi 9:27"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 14, 'Ba oya sibai i''asogö khönia kureta Selomo, awö zi fakudo, 1400 khönia gureta ba 12.000 zi fakudo.[9] Ba mbanua gureta andrö ifataro ba ba zi tefasui razo, ba Yeruzalema.[10]', '["Ayati 14–17: RazI 10:26–29","RazI 4:26; 10:26 b.t.","Faigi 9:27"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 15, 'Ba falaŵalaŵa ira gara gana''a, wa''oya, ibe''e razo, ba falaŵalaŵa ira döla geresi döla ara gatua, ba ndraso.[11]', '["Ayati 14–17: RazI 10:26–29","RazI 4:26; 10:26 b.t.","Faigi 9:27"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 16, 'Ba kudo andrö, ba ba danö Miserayi ihalö Selomo; möi-möi zaniaga andrö khö razo, ba samba-sambawa lahalö, ni''öli;', '["Ayati 14–17: RazI 10:26–29","RazI 4:26; 10:26 b.t.","Faigi 9:27"]', NULL),
  (3475122, 'OT', 'Nga''ötö II', 1, 17, 'önö ngaotu rufia zambua kureta, wolohe miyaŵa, moroi ba danö Miserayi, ba 150 zageu kudo. Ba si manö göi wama''emara ba razo Ndraono Kheti ba ba razo Ndrawa Garamo.', '["Ayati 14–17: RazI 10:26–29","RazI 4:26; 10:26 b.t.","Faigi 9:27"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 1, 'Ba iŵa''ö Selomo, lalau gosali döi Yehowa, ba khönia, ba lalau gödo razo.[1]', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 2, 'Ba i''ofaya Selomo, zonoro, 70.000, ba 80.000 zanoto kara, ba hili, ba 3600 mandrura.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 3, 'Ba ifatenge zinenge Selomo khö Huramo, razo Diro, imane khönia: Folaumö khö namagu Dawido no, me öfa''ohe''ö khönia mbalo, eresi, ena''ö ilau gödo khönia, omonia.[2]', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 4, 'Ba hiza, ulau gosali döi Lowalangigu Yehowa, ni''amoni''ö khönia, ba wanunu samohua khönia ba ba wama''oli roti nifaigi-faigi andrö, ba ba zumange nitunu andrö, nifaföfö luo, ero ma''ökhö, ba ba luo sabato ba ba wasulöna mbaŵa ba ba gowasa andrö khö Lowalangima Yehowa, — ömö Ndraono Gizeraeli da''ö, si lö mamalö-malö.[3]', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 5, 'Ba osali andrö nilaugu, ba sebua; me no sebua moroi ba Lowalangi bö''ö fefu Lowalangima andrö.[4]', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 6, 'Ba ha niha sa zangila molau omo khönia? Me no ambö nahiania zorugo, awö zorugo fondrege zalaŵa yaŵa; ba ha niha ndra''odo, wa solau omonia ndra''o? — na tenga ha ba wanunu kumöyö khönia?[5]', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 7, 'Ba fatenge sa''ae khögu niha, samösa, si no to''ölö ba walau hadia ia, he ba gana''a ba he ba wirö ba he ba döla ba he ba zi''öli ba ba ungu soyo ba ba girimisi ba ba ungu sowu waru-waru, ba sangila manua gambara, awö duka andrö si so khögu ba mado Yuda ba ba Yeruzalema, ni''asogö namagu Dawido.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 8, 'Ba fa''ohe''ö göi khögu geu balo, eresi ba senobari ba sendrana, moroi ba hili Libano; aboto sa ba dödögu, wa no to''ölö mbanuau andrö, ba wolau eu ba hili Libano, ba banuagu, ba no te''anö, tohu-tohu danga mbanuau andrö.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 9, 'Ba oya sibai ni''a''asogö khögu eu balo, me sebua dania ba sanalu''i inötö nomo andrö, nilaugu.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 10, 'Ba ufa''ohe''ö balazo zolau eu andrö, solobö, banuau andrö, ba 40.000 ngaso''e gandru ba 40.000 ngaso''e ze''iri ba 4000 ngaso''e nagu ba 4000 ngaso''e wanikha.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 11, 'Ba itema li Zelomo Huramo, razo Diro, ifa''ohe''ö zura khö Zelomo, imane: Me no i''omasi''ö mbanuania Yehowa, andrö wa ifataro razora ndra''ugö.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 12, 'Ba imane na Huramo: Nisuno Yehowa, Lowalangi Ndraono Gizeraeli, samazökhi banua si yaŵa, awö danö, me no ibe''e khö razo Dawido nono satua-tua, si so fa''onekhe ba fa''aboto ba dödö, ba wolau osali khö Yehowa ba ba wolau gödo razo khönia.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 13, 'Ba ufatenge khöu duka, sangila watahögö, Huramo Abi andrö,[6]', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 14, 'mado Dano ninania ba banua Diro nama. Si no to''ölö ia ba wolau hadia ia, ba gana''a ba ba wirö ba ba döla ba ba zi''öli ba ba gara, ba he ba geu ba ba ungu soyo, ba he ba zowu waru-waru, ba ba darafali ba ba girimisi, ba ba wanua hadia ia ngawalö gambara, ba ba wolau hadia halöŵö duka, niŵa''ö khönia, awö duka khöu ba awö duka khö duagu amau Dawido.[7]', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 15, 'Ba fa''ohe''ö sa''ae, ö genoniu, gandru andrö, ba se''iri ba fanikha ba agu andrö, niŵa''öu, ya''ugö sokhö ya''o.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 16, 'Ba ya''aga andre, ba solau eu ba hili Libano, ha wa''oya-oya zoguna khöu, ba ma''ohe khöu ba Yafo, marakeni, ba nasi, ba ya''ugö zama''ohe''ö misi yaŵa ba Yeruzalema.', '["Faigi göi RazI 5:1–18","SamII 5:11; Nga''ötI 14:1","MozIV 28:4","Sin 86:8","RazI 8:27; Faigi 6:18","RazI 7:13","MozII 31:2–6"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 17, 'Ba i''ofaya Selomo fefu zi fatewu gana ba danö Ndraono Gizeraeli, si mane me i''ofaya amania Dawido föna; ba no 153.600.', '["Yos 9:27"]', NULL),
  (3475123, 'OT', 'Nga''ötö II', 2, 18, 'Ba 70.000 ifataro sana''una''u hadia ia, ba 80.000 ibe''e sanotonoto kara, ba hili, ba 3.600 ifataro mandru, sango''ou niha andrö ba rodi andrö.[8]', '["Yos 9:27"]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 1, 'Ba ibörötaigö Selomo wolau osali Yehowa andrö ba Yeruzalema, ba hili Moriya andrö, ba ni''oroma''ö Yehowa ya''ia khö namania Dawido, ba naha andrö ni''asiwai Dawido, ba goloyama mbasitö khö Gorana, Iraono Yebusi.[1][2]', '["Faigi göi RazI 6:7:15–22","MozI 22:2; SamII 24:28; Nga''ötI 21:18"]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 2, 'Ba zi mendrua ba mbaŵa si dua, ibörotaigö wotomo andrö, me no alua medölu fakhe razo ia.', '["Faigi göi RazI 6:7:15–22","MozI 22:2; SamII 24:28; Nga''ötI 21:18"]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 3, 'Ba da''e nifakhoi Zelomo, ba wolau osali Lowalangi andrö: Fa''anau, ba 60 hela — ba hela föna —, ba fa''ebolo, ba 40 hela.', '["Faigi göi RazI 6:7:15–22","MozI 22:2; SamII 24:28; Nga''ötI 21:18"]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 4, 'Ba ewe''ewe föna nösi nomo, nifo''oto''oto, sebua ba 10 hela wa''ebolo, ba fa''anaunia, ba mbawa duasa nomo, ba 20 hela, ba fa''alaŵa, ba 20 hela [göi]. Ba tanö bakha, ba ifo''uli si ndruhu mbalaki.', '["Faigi göi RazI 6:7:15–22","MozI 22:2; SamII 24:28; Nga''ötI 21:18"]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 5, 'Ba si hulö dalu zalo, ba ibagolöi bagalö senobari, ba awena ifo''uli balaki ba ifasua''ö wamaedo nohi ba si hulö rate.', '["Faigi göi RazI 6:7:15–22","MozI 22:2; SamII 24:28; Nga''ötI 21:18"]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 6, 'Ba ifoadu feremata; ba ana''a andrö, ba ana''a Warawa''i.', '["Faigi göi RazI 6:7:15–22","MozI 22:2; SamII 24:28; Nga''ötI 21:18"]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 7, 'Ba ifo''uli sa''ae baulu, ana''a, he buatö, ba he högö ba toyo mbawandruhö, ba he bagolö ba he lagö mbawandruhö, ba ifasua''ö wamaedo kerubi, ba mbagolö.', '["Faigi göi RazI 6:7:15–22","MozI 22:2; SamII 24:28; Nga''ötI 21:18"]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 8, 'Ba i''oniagö wondrege ni''amoni''ö andrö; fa''anaunia, ba 20 hela, dali mbolo nomo, ba fa''ebolonia, ba 20 hela göi, ba ifo''uli balaki, 2.382.300 balaki.', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 9, 'Ba fa''abua gosö-osö, ba 50 fondruyu ana''a. Ba he bate''e ba zi sagötö, ba ifo''uli ana''a.', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 10, 'Ba si bakha ba wondrege ni''amoni''ö andrö, ba ifalau''ö kerubi, dombua, nilau duka wamaedo niha, ba ifo''uli ana''a.', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 11, 'Afi kerubi andrö, ba 20 hela wa''anau, ba wa''orudu; si sara, si 5 hela, ba irugi mbagolö nomo, ba si sara, si 5 hela göi, ba irugi mbute gafi kerubi si sambua.', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 12, 'Ba si manö gafi si sara, ba kerubi si sambua, 5 hela göi, ba irugi mbagolö; ba afinia si sara, si 5 hela göi, ba irugi mbute gafi kerubi si sambua.', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 13, 'Fa''anau gafi kerubi andrö, nibologö, ba 20 hela. Ba no sizizio ira ba la''otahögö nösi nomo.', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 14, 'Ba ifalau''ö mba''a-ba''a andrö, ungu sowu waru-waru ba soyo, ba kirimisi ba tarafali, ba ifofamaedo kerubi.[3]', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 15, 'Ba föna nomo, ba dua ifalau''ö taru nahe, 35 hela wa''alaŵa, ba limalima hela högö si yaŵa.[4]', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 16, 'Ba ifalau''ö zi hulö rate nibe''e ba högö daru nahe andrö; ba 100 ifalau''ö famaedo mbua dalimo, nibe''e ba rate andrö.', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475124, 'OT', 'Nga''ötö II', 3, 17, 'Ba taru nahe andrö, ba ba mbawa duasa gosali ifasindro, sara ba gambölö, ba sara ba gabera; si so ba gambölö, ba Yakhino ibe''e töi, ba ba gabera, ba Boasi.', '["MozII 26:31","RazI 7:15 b.t."]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 1, 'Ba ifa''anö na göi naha wame''e sumange, töla, 20 hela wa''anau ba 20 hela wa''ebolo ba 10 hela wa''alaŵa.[1][2]', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 2, 'Ba ifalau''ö gala nidanö andrö, nifahele, 10 hela wa''eŵaŵa mbewe, sowulo, 5 hela wa''abakha; ba na lafasui mbewe sinali, ba 30 hela.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 3, 'Ba tou mbewenia ba famaedo zuri de''u, fasui manö — fulufulu ba zi sahe-sahela — no tefasui gala andrö, dua ngenoli zuri, nifao ba wamahele mege.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 4, 'Ba dayadayania, ba 12 wamaedo zaŵi, tölu miyöu, ba tölu zi otahögö gaekhula luo ba tölu miraya ba tölu tanö ba gatumbukha luo. Ba si tohare ba hulura gala andrö, ba toyora fefu, ba no faondra.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 5, 'Ba fa''awe''e-we''e gala, ba lalu''a, ba bewenia, ba si mane bewe mako, si mane bunga zömasöma safusi; ba 600 ngaso''e itaha idanö.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 6, 'Ba baero ö, ba 10 ifazökhi balanga; lima ibe''e ba gambölo ba lima ba gabera naha wanasa, (ba da''ö lasasai hadia ia ba zumange nitunu andrö); ba gala sebua andrö, ba ena''ö naha wanasa ba gere.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 7, 'Ba ifazökhi göi naha wandru andrö, si fulu, dali nifakhoi ba da''ö, ba ibe''e ba gosali bakha, lima ba gambölö ba lima ba gabera.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 8, 'Ba fulu göi ifazökhi meza, ba ibe''e ba gosali, lima ba gambölö ba lima ba gabera, ba otu ifazökhi figa, soguna ba wanefe hadia ia.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475125, 'OT', 'Nga''ötö II', 4, 9, 'Ba i''oniagö golayama gere, ba he olayama sebolo andrö; ba bawandruhö golayama ifazökhi; ba lagö mbawandruhö andrö, ba ifo''uli töla.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 10, 'Ba gala sebua andrö, ba raya gosali ibe''e tanö ba gatumbukha luo, si otahögö miraya.', '["Faigi göi RazI 7:23–51","Faigi 7:7"]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 11, 'Ba Huramo andrö, ba ifazökhi mbowoa andrö, ba sundrusundru ba figa, ba wanefe. Ba tobali i''asiwai Huramo nilau andrö, hadia ia nifazökhinia khö razo Selomo, ba gosali Lowalangi.', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 12, 'Dua daru nahe, awö högö andrö yaŵa, si dombua sotalosu, awö ni''otaraŵa andrö, balu-balu dalosu högö daru nahe andrö,', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 13, 'ba 400 wamaedo mbua dalimo, ba ni''otaraŵa andrö si dua görö, dua ngenoli wamaedo mbua dalimo zagörö ni''otaraŵa, balu-balu dalosu högö daru nahe andrö;', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 14, 'ba ifazökhi dayadaya andrö, si fulu, awö mbalanga andrö, si fulu,', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 15, 'ba dayadaya andrö yaŵa, ba gala sebua andrö, si ha sambua ba famaedo zaŵi andrö, si feledrua, dayadayania.', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 16, 'Ba bowoa andrö ba sundrusundru ba garafu ba fakake fefu, soguna ba da''ö, ifazökhi Huramo-Abiwi, khö Zelomo, ba gosali Yehowa, oi töla ni''alösöigö.', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 17, 'Ba ndraso Yoridano ifafahele''ö razo, ba golabuta la''uri, ba gotaluara Zukota Zereda.', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 18, 'Ba oya sibai ifafazökhi''ö Selomo fakake andrö fefu; lö''ö sa muhonogöi wa''abua döla andrö.', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 19, 'Ahori ifazökhi Selomo gama-gama andrö, ba gosali Lowalangi: Naha wame''e sumange andrö, ana''a, awö meza andrö, naha roti nifaigi-faigi,', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 20, 'awö naha wandru andrö, fabaya fandru, si ndruhu mbalaki, ena''ö latunutunu föna wondrege ni''amoni''ö,', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 21, 'dali goroisa ba da''ö, ba bunga-bunga andrö, awö naha wandru, awö guti wandru, ana''a, si ndruhu mbalaki —', '[]', NULL),
  (3475125, 'OT', 'Nga''ötö II', 4, 22, 'awö zi''öli andrö, awö wiga, ba wanefe, awö mako, awö gali, si ndruhu mbalaki. Ba ba lagö mbawandruhö, ba no ana''a lagö mbawandruhö tanö bakha ba wondrege ni''amoni''ö andrö, ba he lagö mbawandruhö ba nomo, ba zi hulö dalu zalo.', '[]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 1, 'Ba me no awai fefu hadia ia nifafazökhi''ö Zelomo ba gosali Yehowa, ba i''ohe bakha Selomo mbuala namania andrö, ni''amoni''ö; firö andrö, ba ana''a ba fakake andrö fefu, ba ibe''e ba mbate''e girö-girö ba gosali Lowalangi.[1][2]', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 2, 'Ba ifalukha''ö Selomo zatua Ndraono Gizeraeli, awö högö mado fefu, salaŵa soi Ndraono Gizeraeli ba Yeruzalema, ba wolohe miyaŵa tawöla andrö, nahia goroisa Yehowa, moroi ba mbanua Dawido Siona andrö.', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 3, 'Ba owulo ira khö razo, dozi ndra matua Iraono Gizeraeli, ba mbaŵa Etani, ba gowasa, baŵa si fitu.[3]', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 4, 'Ahori so zatua Ndraono Gizeraeli, ba lafazaŵa dawöla Ono Lewi,', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 5, 'ba la''ohe miyaŵa, fabaya ose wama''ele''ö ba fakake ni''amoni''ö andrö fefu, baose — da''ö ni''ohe gere Ono Lewi miyaŵa.', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 6, 'Ba la''iagö föna dawöla razo Selomo ba Iraono Gizeraeli sato, fefu, si no falukha khönia, wame''e sumange biri-biri ba saŵi, irege tebai sa''ae la''erai, mbalazi wa''oya, tebai la''ofaya.', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 7, 'Ba ere andrö, ba la''ohe ba nahania dawöla goroisa Yehowa, ba mbate''e tanö ba hambo gosali, ba wondrege ni''amoni''ö andrö, barö gafi kerubi andrö.', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 8, 'Noa sa mubologö gafi kerubi andrö, yaŵa naha dawöla, ba tobali samonöu tawöla, fabaya heaheania, kerubi andrö, moroi yaŵa.', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 9, 'Ba fa''anau heahea andrö, ba faoro mbalö moroi ba ni''amoni''ö, fönaföna mbate''e ba hambo andrö; ba baulu, ba lö oroma. Ba da''ö nahania, irugi ma''ökhö andre.', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 10, 'Ba ösi dawöla, ba ha kara wanura andrö si dua görö, nibe''e Moze bakha, ba gahe hili Horebi, kara wanuru ba wawu''usa li andrö, me fawu''u li Yehowa ba Ndraono Gizeraeli, me aheta ira ba danö Miserayi.', '["Faigi göi RazI 7:51; 8:1–11","Nga''ötI 28:14–18","MozIII 23:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 11, 'Ba me laheta ira ba ni''amoni''ö ere (noa sa ahori mamoni gere, si so, lö mufaigi ngenoli),', '["Nga''ötI 15:19; 16:37,41,42; 25:1–7","Sin 136; Nga''ötI 16:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 12, 'ba sanunö andrö fefu, Ono Lewi, ira Asafo, Hemano Yedutuno, fabaya onora ba talifusöra, ba ahori so ba da''ö, tanö ba gatumbukha luo, i''otarai naha wame''e sumange, baru tarafali mbarura, ba so khöra waritia ba biola nitika, sebua ba side-ide, ba 120 gere ba ngaira, solau torofe;[4]', '["Nga''ötI 15:19; 16:37,41,42; 25:1–7","Sin 136; Nga''ötI 16:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 13, 'ba hulö zi ha sara lira zolau torofe zanunö, wanuno Yehowa, awö wangandrö saoha gölö khönia. Ba me labörögö wolau torofe ba famözi faritia, ba folau hadia ia [mbö''önia] nifoli, ba fanuno Yehowa andrö: "me no si sökhi tödö ia ba me si lö aetu wa''ebua dödönia andrö!" ba anönö gosali bakha lawuo, osali Yehowa andrö,[5]', '["Nga''ötI 15:19; 16:37,41,42; 25:1–7","Sin 136; Nga''ötI 16:34"]', NULL),
  (3475126, 'OT', 'Nga''ötö II', 5, 14, 'ba lö lala gere, ba wangai halöŵöra, me no anönö gosali Lowalangi lakhömi Yehowa andrö.', '["Nga''ötI 15:19; 16:37,41,42; 25:1–7","Sin 136; Nga''ötI 16:34"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 1, 'Ba imane Selomo: No iŵa''ö Yehowa, ba zogömi-gömi zomasi ia nahiania.[1]', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 2, 'Ba no ulau nomo nahiau, nahia si soso ndra''ugö, götö-götö wa''ara.', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 3, 'Ba ibali''ö ia razo, i''owai Ndraono Gizeraeli sato fefu, wamahowu''ö ya''ira, no muziozio Ndraono Gizeraeli sato fefu.', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 4, 'Ba imane [razo]: "Nisuno Yehowa, Lowalangi Ndraono Gizeraeli, si no muhede, bawania khö namagu Dawido ba si no mamalua ya''ia tangania, me imane:', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 5, 'I''otarai luo, me uheta ba danö Miserayi mbanuagu ba sambua lö mado Ndraono Gizeraeli nituyugu banua, ba wolau osali, nahia döigu ba lö nituyugu niha, ena''ö salaŵa mbanuagu Iraono Gizeraeli ia.[2]', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 6, 'Ba Yeruzalema andrö, ba no utuyu nahia döigu, ba Dawido andrö, ba no utuyu, ena''ö salaŵa mbanuagu Iraono Gizeraeli ia.', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 7, 'Ba no so ba dödö namagu Dawido wolau osali döi Yehowa, Lowalangi Ndraono Gizeraeli;[3]', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 8, 'Ba no imane Yehowa khö namagu Dawido: Wa no öŵa''ö tödöu wolau osali döigu, ba no si sökhi, me no öŵa''ö da''ö.', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 9, 'Ba tenga sa ya''ugö zolau osali andrö, onou zolau, nga''ötöu, da''ö dania zolau osali döigu.', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 10, 'Ba no itörö gamabu''ula li andrö, nibe''enia, ibe''e Yehowa. Noa sa so ndra''o fangali namagu Dawido, ba no dumadaodo ba dadaoma zalaŵa ba Ndraono Gizeraeli, itörö nifabu''u Yehowa, ba no ulau gosali döi Yehowa, Lowalangi Ndraono Gizeraeli.', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 11, 'Ba no ube''e ba da''ö dawöla andrö, naha goroisa ba wawu''usa li andrö khö Yehowa, me fawu''u li ia ba Ndraono Gizeraeli."', '["Faigi göi RazI 8:12–53","SamII 7:6","SamII 7:2–13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 12, 'Ba i''iagö föna naha wame''e sumange andrö khö Yehowa, ba zanehe Ndraono Gizeraeli fefu, ba i''oro''ö dangania,', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 13, '(noa sa ifafazökhi''ö harehare, töla, Selomo, ba no ibe''e ba dalu golayama, 5 hela wa''anau ba 5 hela göi wa''ebolo ba 3 hela wa''alaŵa; ba da''ö yaŵa möi ia ba ibalöduhini, ba zanehe Ndraono Gizeraeli sato fefu, ba i''oro''ö dangania miyaŵa ba zorugo),', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 14, 'ba imane: "He Yehowa, Lowalangi Ndraono Gizeraeli, lö Lowalangi si falaŵalaŵa khöu, he ba zorugo, ba he ba guli danö; ya''ugö, ba lö öwu''ai wawu''usa li andrö, ba fa''ahakhö dödöu ba genonimö andrö, solo''ö niŵa''öu, soroi si''aikö ba dödöra,[4]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 15, 'no lö niwu''aimö khö genoniu, amagu Dawido, nifabu''umö khönia. No bawau zamabu''u ba no tangau zamalua, si mane ma''ökhö andre.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 16, 'Ba iya''e, ya''ugö Yehowa, Lowalangi Ndraono Gizeraeli, ba böi wu''ai khö genoniu, amagu Dawido nifabu''umö khönia, me ömane: Lö falukha dania lö khöu [nga''ötö] fönagu, sidadao ba dadaoma zalaŵa ba Ndraono Gizeraeli, asala lö laböhöli lala andrö khöra nga''ötöu, ba wolo''ö oroisagu andrö, si mane ya''ugö, me no ötörö, fönagu.[5]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 17, 'Ba iya''e, ya''ugö Lowalangi Ndraono Gizeraeli, ba ena''ö na itörö gamabu''ula limö andrö, nifabu''umö khö genoniu Dawido!', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 18, 'Ba hadia, si ndruhu i''iagö awö niha ba guli danö Lowalangi? Hiza, sorugo andrö ba fondrege zorugo, ba no ambö nahamö, ba mendrua manö gosali andre nilaugu.[6]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 19, 'Ba be''e mbörö dalingau ba wangandrö genonimö ba ba wakaosania, ya''ugö Yehowa, Lowalangigu, ena''ö öfondrondrongo we''ao-ao andrö ba fangandrö, na mangandrö genoniu.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 20, 'Ena''ö si teboka manö höröu, yaŵa gosali andre, bongi ma''ökhö, yaŵa naha andre, niŵa''öu, ba da''ö öfonahia döimö andrö; ena''ö öfondrondrongo wangandrö andrö, na mangandrö genoniu ba naha andre.[7]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 21, 'Ba ena''ö na öfondrondrongo li wakaosa andrö khö genoniu ba ba mbanuau Iraono Gizeraeli, na mangandrö ira ba naha andre. Fondrondrongo ae ba naha andrö, sidadao ndra''ugö, ba zorugo, ba na örongo, ba bologö dödöu!', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 22, 'Na so zosala khö nawönia ba na labe''e ba hölu ia, ena''ö ba hölu i''aro''ö niŵa''önia, ba na so ia, na ibaya hölu, föna naha wame''e sumange khöu, ba nomo andre:[8]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 23, 'ba fondrondrongo ba zorugo ba tolo, ba ohe ba lala huhuo genonimö, ena''ö ösuloni ba zi so horö, wangahare''ö ba hulunia nilaunia andrö, ba ena''ö öheta ba hulu zi lö horö, wanulöni khönia fa''atulö dödönia.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 24, 'Ba na te''ala mbanuau Iraono Gizeraeli labe''e emalira, me no molalö ira khöu, ba na lafalalini gera-erara ba na lafarongogö döimö, na mangandrö ira ba na fakao ira khöu, ba nomo andre:[9]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 25, 'ba ena''ö na öfondrondrongo ba zorugo, ba öbe''e aefa horö mbanuau Iraono Gizeraeli, ba ö''ohe mangawuli ira ba danö andrö, nibe''eu khöra ba khö ndra tuara mege.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 26, 'Ba na no teduhö mbanua si yaŵa, na lö teu, börö me no molalö ira khöu, ba na mangandrö ira ba naha andre, na lafarongogö döimö, na lafalalini gera-erara, na laböhöli horöra andrö, me no öhöndrögö ira:[10]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 27, 'ba ena''ö na öfondrondrongo ba zorugo ba öbe''e aefa horö genoniu andrö, horö mbanuau Iraono Gizeraeli, wanuturu khöra lala si sökhi andrö, nitörö, ba ena''ö na öfatörö deu ba danö andrö, nibe''eu ba mbanuau andrö, tana khöra, ondröita.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 28, 'Ba ma lofo mbanua ba danö, ba ma fökhö waba, ba ma fa''akhozi ngalai wakhe, ba ma fa''ahohomö, ba ma tamo, ba ma föla; ba ma lafakao ira emalira, ba mbanua khöra heza, ba ma hadia ia wamakao ba hadia ia wökhö:[11]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 29, 'na dania örongo wangandrö ba ma fakaosa, na ha niha zangandrö, ba na banuau Iraono Gizeraeli fefu, na dozi afökhö khöra wamözi andrö ba safökhö andrö, si no göna ira, ba na la''oro''ö dangara ba nomo andre:', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 30, 'ba ena''ö na öfondrondrongo ba zorugo, ba naha andrö, ba zi dadao ndra''ugö, ba öbe''e aefa horö ba ösulöni ba zamösana nitörönia fefu, balazi wangilamö tödönia — me no ha ya''ugö zangila tödö nono niha![12] —', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 31, 'ena''ö la''ata''ufi ndra''ugö, ba wanörö lala andrö khöu, si lö mamalö-malö, götö we''asora ba danö andrö, nibe''eu khö ndra tuama.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 32, 'Ba he ba niha bö''ö, si tenga banuau Iraono Gizeraeli, na möi ia, moroi ba danö saröu, börö döimö andrö, sebua, ba tangau andrö, sabölö, ba ta''iomö si no ö''oro''ö — na möi ia mangandrö ba golayama nomo andre:', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 33, 'ba ena''ö no öfondrondrongo ba zorugo, ba naha andrö, ba zi dadao ndra''ugö, ba ö''o''ö fefu hadia ia, ni''andrö niha bö''ö andrö khöu, ena''ö dozi soi ba guli danö aboto ba dödö döimö andrö, ena''ö la''ata''ufi ndra''ugö, si mane banuau Iraono Gizeraeli, ba ena''ö lasöndra wa no töimö mbörö döi gosali andre, nilaugu.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 34, 'Ba na möi fasuwö ba nemalira mbanuamö, na latörö lala niŵa''öu khöra, ba na mangandrö ira khöu, na la''otahögö mbanua andre, nituyumö, ba osali andre, nilaugu nahia döimö:[13]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 35, 'ba ena''ö na öfondrondrongo wangandröra ba fangarö-ngaröra, ba ötolo ira.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 36, 'Ba na molalö ira khöu — samösa sa lö niha, si lö horö! — ba na mofönu ndra''ugö khöra ba na öbe''e ba danga nemalira ira, na tobali la''oloi''ö ira ba danö saröu, ba ma ba danö sahatö, sabölö moroi khöra,', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 37, 'ba na mangera-ngera ira, ba danö andrö, ba nitaha ya''ira, ba na lamane: No mosala ndra''aga, no matörö lala si lö sökhi, no sebua horö ndra''aga![14]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 38, 'ba na lafuli ira khöu, soroi si''aikö ba dödöra ba ba gera-erara fefu, ba danö zamakao ya''ira, si no mangoloi''ö ya''ira, ba na mangandrö ira, na la''otahögö danöra andre, nibe''eu khö ndra tuara ba banua andre, nituyumö, ba omo andre, nilaugu nahia döimö:', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 39, 'ba ena''ö na öfondrondrongo wangandröra ba fangarö-ngaröra, soroi si''aikö ba dödö, ba zorugo khöu, ba naha andrö, ba zi so dadaomamö, ba ötolo ira, ba öbe''e aefa horö mbanuau, lalöra andrö khöu.', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 40, 'Ba ena''ö na si teboka manö höröu, ya''ugö Lowalangigu, ba na öbe''e manö mbörö dalingau ba wangandrö ba naha andre!', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 41, 'Ba iya''e, ba fazaŵa''ö, ya''ugö Lowalangi, Yehowa, saŵa zolombase ndra''ugö, ya''ugö ba tawöla wa''abölöu andrö! Ndramu''obaru wangorifi ere andrö khöu, ya''ugö Lowalangi, Yehowa, ba ya sowua-wua tödö ba zi sökhi andrö zatulö tödö andrö khöu![15]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475127, 'OT', 'Nga''ötö II', 6, 42, 'He Lowalangi, Yehowa, böi timba nibayoini andrö khöu; törö-törö tödöu wa''ahakhö dödöu andrö khö genoniu Dawido!"[16]', '["MozII 15:11; MozV 7:9","Sin 132:11; SamII 7:16","Faigi 2:5","MozII 20:24","MozII 22:10","MozV 28:25","MozV 28:23,24","Nga''ötII 20:9","Nga''ötI 29:17; Sin 7:10","Dan 6:10","Dan 9:5","Sin 132:8,9","SamII 7:13"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 1, 'Ba me no i''o''ozui wangandrö Selomo, ba aekhu galitö moroi yaŵa ba mbanua ba i''a zumange nitunu andrö, awö zumange nitaba, ba anönö bakha gosali lakhömi Yehowa,[1]', '["RazI 8:54; 18:38; MozIII 9:24; MozII 40:34","Faigi 5:13; Sin 136"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 2, 'tobali tebai möi bakha ba gosali gere, me no anönö bakha gosali Yehowa lakhömi Yehowa andrö.', '["RazI 8:54; 18:38; MozIII 9:24; MozII 40:34","Faigi 5:13; Sin 136"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 3, 'Ba me la''ila Iraono Gizeraeli fefu, aekhu moroi yaŵa galitö andrö ba ihawui gosali lakhömi Yehowa, ba latuhi danö ba lafaöndrö tou mbawara, ba mbale, mangalulu ira ba lasuno Yehowa, ba wa''ebua dödönia ba ba wa lö aetu wa''ahakhö dödönia.[2]', '["RazI 8:54; 18:38; MozIII 9:24; MozII 40:34","Faigi 5:13; Sin 136"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 4, 'Ba lataba zumange nitaba föna Yehowa, razo, awö niha sato fefu.[3][4]', '["Ayati 4–10: RazI 8:62–66","RazI 8:62 b.t.","Yos 13:3","MozIV 7:10","Ayati 11–22: RazI 9:1–9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 5, 'Ibe''e zumange fangorifi Selomo, 22.000 zaŵi ba 120.000 mbiri-biri.', '["Ayati 4–10: RazI 8:62–66","RazI 8:62 b.t.","Yos 13:3","MozIV 7:10","Ayati 11–22: RazI 9:1–9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 6, 'Ba la''iagö nahara ere ba si manö göi Nono Lewi, so ba dangara nifoli andrö, khö Yehowa, nifafazökhi''ö razo, Dawido, ba wangandrö saoha gölö khö Yehowa, me no si lö aetu wa''ebua dödönia andrö, wolau sinunö andrö khö Dawido; ba lalau dorofe ere, ba gametahöra, ba zi so Ndraono Gizeraeli fefu.', '["Ayati 4–10: RazI 8:62–66","RazI 8:62 b.t.","Yos 13:3","MozIV 7:10","Ayati 11–22: RazI 9:1–9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 7, 'Ba i''amoni''ö Selomo golayama ba dalu, föna gosali Yehowa, wame''e sumange nitunu andrö, awö dawö zumange fangorifi. Lö''ö sa itaha zumange nitunu andrö, awö zumange ni''a, awö dawö andrö, naha wame''e sumange töla andrö, nifafazökhi''ö Zelomo.', '["Ayati 4–10: RazI 8:62–66","RazI 8:62 b.t.","Yos 13:3","MozIV 7:10","Ayati 11–22: RazI 9:1–9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 8, 'Ba ilau gowasa andrö Selomo, me luo da''ö, fitu bongi wa''ara, ba awönia Ndraono Gizeraeli fefu — owuloa sebua sibai [sagörö tanö], i''otarai lala ba Hamata andrö, irugi mbombo andrö ba [nola] danö Miserayi.[5]', '["Ayati 4–10: RazI 8:62–66","RazI 8:62 b.t.","Yos 13:3","MozIV 7:10","Ayati 11–22: RazI 9:1–9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 9, 'Ba me luo si ŵalu, ba oi owulo ira, owuloa ba gowasa; me no fitu bongi khöra we''amoni''ö naha wame''e sumange andrö; no fitu bongi gowasa.[6]', '["Ayati 4–10: RazI 8:62–66","RazI 8:62 b.t.","Yos 13:3","MozIV 7:10","Ayati 11–22: RazI 9:1–9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 10, 'Ba ba zi dua wulu a tölu ba mbaŵa si fitu, ba ifofanö ba khöra niha sato [Selomo], somuso tödö ira ba si sökhi tödö, ba zi sökhi andrö fefu, nilau Yehowa khö ndra Dawido Selomo ba ba mbanuania Iraono Gizeraeli.', '["Ayati 4–10: RazI 8:62–66","RazI 8:62 b.t.","Yos 13:3","MozIV 7:10","Ayati 11–22: RazI 9:1–9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 11, 'Ba no i''asiwai Selomo gosali Yehowa andrö, awö gödo razo, no ahori i''o''ozui, hadia ia, fefu niŵa''önia tödönia mege, nilau ba gosali Yehowa ba ba gödo razo.[7]', '["Ayati 4–10: RazI 8:62–66","RazI 8:62 b.t.","Yos 13:3","MozIV 7:10","Ayati 11–22: RazI 9:1–9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 12, 'Ba i''oroma''ö ia Yehowa khö Zelomo, ba zi bongi, imane khönia: No ufondrondrongo wangandröu, ba no utuyu khögu naha wame''e sumange naha andrö.[8]', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 13, 'Na ukusi mbanua si yaŵa, na lö aekhu ba danö deu, ba na ufatörö damo, ena''ö la''a zinanö ba danö, ba na ufatörö wökhö waba ba mbanuagu,', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 14, 'ba na la''ide-ide''ö ira banuagu, nifao töigu ba döira, na mangandrö ira, na la''alui wamaigigu ya''ira ba na lafalalini gegera-era, na laböhöli mbua-buara si lö sökhi andrö, ba ufondrondrongo ba zorugo, ube''e aefa horöra ba ufaigi wangorifi ba danöra andrö.', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 15, 'Ufaigi-faigi sa''ae ba ube''e mbörö dalingagu ba wangandrö ba naha andre.[9]', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 16, 'Ba noa sa''ae utuyu gosali andre, ba no ubali''ö ni''amoni''ö, ena''ö ba da''ö monahia döigu, si lö mamalö-malö, ba ena''ö böi aefa-aefa ba da''ö hörögu ba tödögu, götö-götö wa''ara.[10]', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 17, 'Ba na ötörö lala andrö, khögu, somasido, si mane fanörö namau Dawido mege, na ö''o''ö sibai niŵa''ögu khöu ba na ötöngöni nifakhoigu, awö huku andrö khögu,', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 18, 'ba u''aro''ö dadaoma zalaŵa andrö khöu, si mane nifabu''ugu khö namau Dawido, me umane: Lö''ö manö dania ambö khöu [nga''ötöu], samatörö Iraono Gizeraeli.[11]', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 19, 'Ba na mi''erogö ndra''o, ba na miböhöli nifakhoigu ba oroisagu, niŵa''ögu khömi, ba na möi ami mamosumange Lowalangi bö''ö,', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 20, 'na ba da''ö mangalulu ami, ba udeha ira ba danö andre khögu nibe''egu khöra, ba osali andre, ni''amoni''ögu nahia döigu, ba nitibo''ö ube''e, fönagu, ba ube''e amaedola ba fama''iki niha, ba niha baero fefu.[12]', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 21, 'Ba gosali andre, si no alaŵa mege — ba dozi sanörö, ba si hokha mbu. Ba na lasofu dania: Hadia mbörö, wa ifatörö zi mane da''ö ba danö andre, ba ba gosali andre Yehowa?[13]', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475128, 'OT', 'Nga''ötö II', 7, 22, 'ba lamane: Börö me no la''erogö Yehowa andrö, Lowalangi ndra tuara, si no mangeheta tuara ba danö Miserayi, ba me no la''olembai Lowalangi bö''ö, me no ba da''ö mangalulu ira, ba me no lafosumange da''ö, — da''ö mbörö wa no ifatörö khöra wamakao andrö fefu Yehowa!', '["MozV 12:5","Faigi 6:40","Sin 132:13","SamII 7:12,13,16","MozV 28:37","MozV 29:23–26; Yer 22:8,9"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 1, 'Ba no numalö zi 20 fakhe andrö, götö wolau Zelomo osali Yehowa andrö, awö gödonia.[1]', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 2, 'Ba banua andrö, nibe''e Huramo khö Zelomo, ba i''aro''ö Selomo, ba Iraono Gizeraeli ifataro ba da''ö.', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 3, 'Ba möi musuwö Hamata Zoba Selomo, ba atu''a ia ba da''ö.', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 4, 'Ba i''aro''ö Dadimoro ba danö si mate, awö mbanua andrö nitaru''önia ba Hamata.', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 5, 'Ba ni''aro''önia na baero ö, ba Beti Horona yaŵa ba Beti Horona tou, ibali''ö banua saro, si so öli kara ba bawa göli nilazi.', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 6, 'Ba he Ba''alata ba banua andrö nihöna balazo, fefu, khö Zelomo, ba banua gureta andrö, fefu, ba banua zi fakudo, ba hadia ia fefu, somasi Zelomo ilau, ba Yeruzalema ba ba hili Libano ba ba danö si so barö mbawania, ma''asagörö.', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 7, 'Ba ha niha fefu, si tosai na, Iraono Kheti ba Iraono Gamori ba Iraono Weresi ba Iraono Hewi ba Iraono Yebusi, si tenga Iraono Gizeraeli,', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 8, '— nga''ötö niha andrö, si tosai na ba danö, nisaigö Ndraono Gizeraeli, si lö muhori, — ba i''ofaya Selomo ba rodi, sirugi ma''ökhö andre.[2]', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475129, 'OT', 'Nga''ötö II', 8, 9, 'Ba Iraono Gizeraeli, ba lö ibali''ö sawuyu Selomo ba wohalöŵö khönia; ya''ira ba si möi-möi fasuwö ba solohe si fasöndra si iagö kureta, ba solohe kureta andrö khönia, fabaya si fakudo.', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 10, 'Ba fa''ato högö gumandru khö razo Selomo, ba no 250, samaigi-maigi niha sato.', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 11, 'Ba ono Wara''o andrö, ba i''ohe ba nomo andrö, nilaunia khönia, Selomo, iheta ba mbanua Dawido. Imane sa: Böi ya soso khögu ndra alawe ba gödo Dawido, razo Ndraono Gizeraeli, me no ni''amoni''ö, me no labe''e ba da''ö dawöla andrö.[3]', '["Faigi göi RazI 9:10–28","Yos 16:10","RazI 3:1"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 12, 'Ba ibe''e sa''ae khö Yehowa zumange nitunu Selomo, ba naha wame''e sumange andrö, nifa''anönia föna gewe''ewe andrö,[4]', '["Faigi 1:3–6; Faigi 4:1","MozII 23:14; MozIV 28:2,9,11,17,26; 29:12","Nga''ötI 23–26"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 13, 'itörö nibe''e ma''ökhö, dali goroisa Moze andrö ba luo sabato ba ba sawulöna mbaŵa ba ba gowasa andrö, medölu zi döfi — ba gowasa roti si lö mu''aisöni ba ba gowasa wendrakose ba ba gowasa nose daha geu — ibe''e zumange.[5]', '["Faigi 1:3–6; Faigi 4:1","MozII 23:14; MozIV 28:2,9,11,17,26; 29:12","Nga''ötI 23–26"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 14, 'Ba i''o''ö göi nihonogöi namania Dawido, wamataro ngenoli gere andrö ba halöŵöra, ba he Ono Lewi, ba niŵa''ö khöra, ba wanunö ba ba we''amöi tohu-tohu danga gere soguna ma''ökhö; ba sanaro ba mbawandruhö andrö, ba ngenolira, ha uga mbawandruhö; si manö sa goroisa Dawido andrö, enoni Lowalangi.[6]', '["Faigi 1:3–6; Faigi 4:1","MozII 23:14; MozIV 28:2,9,11,17,26; 29:12","Nga''ötI 23–26"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 15, 'Ahori la''o''ö goroisa razo, he lawisa ba gere andrö ba ba Nono Lewi ba ba girö-girö andrö.', '["Faigi 1:3–6; Faigi 4:1","MozII 23:14; MozIV 28:2,9,11,17,26; 29:12","Nga''ötI 23–26"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 16, 'Ba tobali toföfö halöŵö Zelomo andrö, me irugi luo da''ö; fame''e tou toyo gosali ba irege wangasiwai; no awai gosali Yehowa.', '["Faigi 1:3–6; Faigi 4:1","MozII 23:14; MozIV 28:2,9,11,17,26; 29:12","Nga''ötI 23–26"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 17, 'Ba möi ba Geseono Geberi Zelomo ba ba Geloto, ba mbewe nasi, ba danö Ndraono Gedomo.', '["Faigi 1:3–6; Faigi 4:1","MozII 23:14; MozIV 28:2,9,11,17,26; 29:12","Nga''ötI 23–26"]', NULL),
  (3475129, 'OT', 'Nga''ötö II', 8, 18, 'Ba Huramo andrö, ba ifa''ohe''ö khö Zelomo nowo, fabaya ono nowo, si no to''ölö ba nasi; banuania zolohe. Ba fao ira ba mbanua Zelomo, ba larugi Gofiri, lahalö gana''a ba da''ö, 892.625 balaki ba la''ohe khö razo Selomo.', '["Faigi 1:3–6; Faigi 4:1","MozII 23:14; MozIV 28:2,9,11,17,26; 29:12","Nga''ötI 23–26"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 1, 'Ba me irongo duria Zelomo razo Zaba andrö,[1] ira alawe, ba möi ia, ba wanandraigö Selomo ba dahö-dahö; ato sibai nawönia fao, fabaya ondra, sonoro famasa ba dalu-dalu ba ana''a ba feremata, oya sibai, ni''ohe ba Yeruzalema. Ba me irugi Zelomo, ba fahuhuo ia khönia, ibokai fefu hadia ia zi so ba dödönia.[2]', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 2, 'Ba itema linia Selomo, ba nisofunia khönia fefu; lö hadia ia zi lö aboto ba dödö Zelomo, lö hadia ia zi tebai itema linia.', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 3, 'Ba me irongo wa''atua-tua Zelomo razo Zaba, ba me i''ila gödo andrö nilau Zelomo,', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 4, 'ba öra andrö ba meza khönia, ba omo genoninia, awö halö-halöŵö zangai halöŵö yomo khönia, awö nukhara, ba sama''oli gö khönia, awö nukhara, ba sumange andrö khönia, nibe''e-be''enia ba gosali Yehowa, ba tobali sibai dödönia,', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 5, 'ba imane khö razo: Si ndruhu manö nirongogu ba danögu, ba ngawalö hadia ia khömö, ba ba wa''atua-tuamö andrö!', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 6, 'Lö si faduhu dödögu nidunö-dunö niha, irege no urugi, ba irege no i''ila hörögu. Ba ambö na i matonga ni''ombakha''ö khögu, faafahöna wa''atua-tuamö andrö; ötalu''i na duria andrö, nirongogu.', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 7, 'Ya ahowu ndra alawe khöu, ba ya ahowu genoniu andre, si lö aefa-aefa khöu, wamondrongondrongo fa''atua-tuamö andrö!', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 8, 'Nisuno Yehowa, Lowalangiu andrö, si no mangomasi''ö ya''ugö, wamedadao ya''ugö ba dadaoma andrö khönia, razo khö Lowalangiu, Yehowa, börö wa''omasi Lowalangiu Ndraono Gizeraeli, fa lö ibulö''ö ira, götö-götö wa''ara; andrö wa no ibali''ö razora ndra''ugö, ena''ö huku si sökhi öfatörö ba satulö!', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 9, 'Ba ibe''e bualania khö razo, ba 476.460 balaki gana''a, ba famasa ba dalu-dalu ba feremata, oya sibai; lö''ö manö ifuli dania si manö [wa''oya] wamasa ba dalu-dalu, si mane nibe''e razo Zaba andrö khö razo Selomo.', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 10, 'Ba banua Huramo no mege göi ba banua Zelomo, si no möi mangai ana''a ba Gofiri, ba lasao''ö göi geu sendrana ba feremata.', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 11, 'Ba eu sendrana andrö, ba ibali''ö ora Selomo, he ba gosali, ba he ba gödo razo, ba biola nitika, side-ide ba sebua, fakake zanunö andrö; lö murai mu''ila zi manö föna, ba danö mado Yuda.', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 12, 'Ba razo Selomo, ba ibe''e khö razo Zaba fefu hadia ia zomasi ia, awö ni''andrönia, lö lai ni''ohenia khö razo. Ba maoso ia, mofanö, ifuli ia khöra, awö genoninia.', '["Ayati 1–28: RazI 10:1–28","RazI 10:1 b.t."]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 13, 'Ba ana''a nisöndra Zelomo döfi, ba 2.544.353 balaki,[3]', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 14, 'lö lai nisöndrania ba zi möi-möi maniaga ba ba zolafo; ba dozi razo Ndrawa Ara ba he kumandru ba danö, ba labe''e khö Zelomo gana''a ba firö.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 15, 'Ba 200 ifafazökhi Selomo dange, ana''a niböbözi: 600 fondruyu zambua;', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 16, 'ba 300 mbaluse, ana''a niböbözi: 300 fondruyu zambua. Ba ibe''e ba nomo eu hili Libano Selomo.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 17, 'Ba ifalau''ö göi dadaoma razo Selomo, dadaoma sebua, ifö guaza, ba ifo''uli balaki.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 18, 'önö mbosi dadaoma andrö ba baku-baku gahe nifadoro khönia. Ba ba dadaoma, ba no faoma fatambai latalata da''io; ba zinga latalata da''io andrö, ba dua geu wamaedo zingo.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 19, 'Ba felendrua wamaedo zingo ba mbosi no mege, si önö, fatambai. Lö murai mulau zi manö ba razo bö''ö, heza.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 20, 'Ba mako razo Selomo, mako ba wamadu, ba ana''a; ba he gama-gama [bö''ö] fefu, ba nomo eu hili Libano, ba balaki manö, lö hadia ia wirö, me no lö''ö manö ba dödöra wirö, ba götö Zelomo andrö.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 21, 'Noa sa so nowo khö razo, soloyo ba Darisi, awö mbanua Huramo andrö; ero medölu fakhe, ba so nowo andrö, soloyo ba Darisi, ba ösi, ba ana''a ba firö ba ifö guaza ba ba''e ba fofo meraki.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 22, 'Ba italu''i razo bö''ö ba guli danö fefu razo Selomo, ba wa''ebua gana''a ba ba wa''atua-tua.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 23, 'Ba dozi omasi razo ba guli danö la''ila Zelomo ba lafondrondrongo wa''atua-tuania andrö, nibe''e Lowalangi ba dödönia.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 24, 'Ba oi dozi la''ohe mbuala, gama-gama firö ba gama-gama ana''a ba nukha ba fangöna ba famasa gö ba dalu-dalu ba kudo ba kalide kudo, ero röfi.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 25, 'Ba 4000 fasa khö Zelomo kudo ba kureta, ba 12.000 zi fakudo; ba ba mbanua gureta andrö ifataro da''ö ba ba zi tefasui ya''ia ba Yeruzalema.[4]', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 26, 'Ba barö mbawania razo fefu, i''otarai Oifarati ba irugi danö Ndrawa Wilisiti ba ola danö Miserayi.[5]', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 27, 'Ba falaŵalaŵa ira gara wirö, wa''oya, ba Yeruzalema ibe''e razo, ba timba döla geresi döla ara gatua ba ndraso.[6]', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 28, 'Ba moroi ba danö Miserayi lafa''ema khö Zelomo kudo ba moroi ba danö bö''ö fefu.', '["RazI 10:14 b.t.","Faigi 1:14–17; RazI 5:6","MozI 15:18","Nga''ötII 1:15"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 29, 'Ba bö''önia hikaya Dawido,[7] he föna, ba he safuria andrö, ba no mutanö ba zura hikaya andrö khö Natano sama''ele''ö ba ba wama''ele''ö Gahia, banua Zilo, ba ba gangilata Yedo sangi''ila, khö Yerobeamo, ono Nebati.', '["Ayati 29–31: RazI 11:41–43"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 30, 'Ba 40 fakhe razo Zelomo ba Yeruzalema, razo Ndraono Gizeraeli fefu.', '["Ayati 29–31: RazI 11:41–43"]', NULL),
  (3475130, 'OT', 'Nga''ötö II', 9, 31, 'Ba mate Zelomo, itörö lala ndra amania, ba lako''o ia ba mbanua namania Dawido andrö. Ba fangalinia razo ba ononia Rehabeamo.', '["Ayati 29–31: RazI 11:41–43"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 1, 'Ba möi ba Zikhema Rehabeamo, me no ba da''ö falukha Ndraono Gizeraeli fefu, ba wamataro razo ya''ia.[1]', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 2, 'Ba me irongo Yerobeamo, ono Nebati — ba danö Miserayi so ia; ba da''ö isaŵa, me moloi ia no khö Zelomo —, me irongo, wa no mate Zelomo, ba mangawuli ia moroi ba danö Miserayi.[2]', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 3, 'Ba lafatenge, lafakaoni''ö ia. Ba so Yerobeamo ba Iraono Gizeraeli fefu, ba lamane khö Rehabeamo:', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 4, 'No rodi sabe''e ihare''ö khöma amau, ba ya''ugö, ba ökaohasi khöma ma''ifu halöŵö sabe''e, awö rodi safökhö andrö, nihare''ö namau khöma, ba soga barö mbawau.', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 5, 'Ba imane khöra: Mihonogö na ami, irege dua wongi, ba mifuli ami khögu.', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 6, 'Ba mofanö zato. Ba mamagölö razo Rehabeamo ba zatua, enoni namania Selomo, me lö si mate ia na, imane: Ha taŵa''ö ba niha andrö, hadia ba dödömi?', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 7, 'Ba latema linia, lamane khönia: Na ebua dödöu khöra andrö, ma''ökhö, na öhakhösi tödö ira, ba na öhaogö wanema lira, ba lö labulö''ö ira barö mbawau.', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 8, 'Ba lö ifondrondrongo niŵa''ö zatua andrö khönia, ba mamagölö ia ba nono matua, si faziazia''a khönia, si no möi enoninia, imane khöra:', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 9, 'Hadia ba dödömi, ha tawa''ö khöra andrö, sanguma''ö khögu: Kaohasi khöma rodi andrö, nihare''ö namau khöma?', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 10, 'Ba lamane khönia ono matua andrö, si faziazia''a khönia: ömane khöra, sanguma''ö khöu: "Amau, ba no ihare''ö khöma rodi sabe''e, ba ya''ugö, ba kaohasi khöma, — ömane khöra; Turugu si akhi, ba no esolo moroi ba löwi-löwi namagu!', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 11, 'Ba lau, ba na no rodi sabe''e ihare''ö khömi amagu, ba ya''o, ba udou''ö na wa''abe''e rodi andrö khömi: Na no i''otu''ö ami bözi-bözi kudo amagu, ba ya''o, ba "tongo" ulau khömi!"', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 12, 'Ba me lafuli la''ondrasi Rehabeamo ira Yerobeamo, awö niha sato fefu, me no aefa zi dua wongi andrö, dali niŵa''ö razo, me imane: Ba zi dua wongi mifuli ami khögu!', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 13, 'ba i''abe''e''ö linia khöra razo. Tobali lö ifondrondrongo razo Rehabeamo niŵa''ö zatua,', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 14, 'niŵa''ö nono matua andrö i''o''ö wanguma''ö khöra: Na no rodi sabe''e ihare''ö khömi amagu, ba ya''o, ba udou''ö na wa''abe''enia; na no i''otu''ö ami bözi-bözi kudo amagu, ba ya''o, ba "tongo" ulau khömi!', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 15, 'Tobali lö i''o''ö ni''andrö zato razo; me no moroi ba Lowalangi da''ö, ena''ö itörö niŵa''önia andrö, nifa''ema Gahia andrö, banua Zilo, khö Yerobeamo, ono Nebati.[3]', '["Faigi göi RazI 12:1–20","RazI 11:40","RazI 11:31"]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 16, 'Ba me no aboto ba dödö Ndraono Gizeraeli fefu, lö i''o''ö ni''andröra razo, ba lamane khönia niha sato: "Hadia nihalöda khö Dawido? Lö''ö sa tana khöda khö nono Giza''i! Mifuli ami, ya''ami Iraono Gizeraeli, yamufuli ia khöra zamösana! Ba faigi he öwisa yomo khöu, ya''ugö Dawido!" Ba lafuli ira khöra Iraono Gizeraeli fefu.', '[]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 17, 'Ba ba Ndraono Gizeraeli ba mbanua mado Yuda, ba Rehabeamo razora.', '[]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 18, 'Ba me ifatenge gumandra Hadoramo andrö Rehabeamo, ba labunu da''ö Iraono Gizeraeli, latebu kara. Ba fakhamö sibai na itibo''ö ia ba guretania yaŵa razo Rehabeamo, moloi, isaŵa Yeruzalema.', '[]', NULL),
  (3475131, 'OT', 'Nga''ötö II', 10, 19, 'Ba tobali fabali ba nga''ötö Dawido Ndraono Gizeraeli, irugi ma''ökhö andre.', '[]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 1, 'Ba me no irugi Yeruzalema Rehabeamo, ba ifakaoni''ö mado Yuda, awö mado Mbeniyami, 180.000 zabölö, nitutuyu, ba wanuwö Iraono Gizeraeli, ena''ö mangawuli khö Rehabeamo wa''arazo.[1]', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 2, 'Ba humede Yehowa khö Zemaya, enoni Lowalangi,', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 3, 'imane: Hede khö Rehabeamo, ono Zelomo, razo mado Yuda, ba ba Ndraono Gizeraeli, ma''uwu Yuda ba ma''uwu Mbeniyami,', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 4, 'ömane: Da''ö niŵa''ö Yehowa: Böi mi''ae''e, ba wanuwö talifusömi; yamufuli ia khöra zamösana, me no ya''o zanguma''ö, wa si manö. Ba me larongo niŵa''ö Yehowa, ba lafuli ira, lö alua möi ira manuwö Yerobeamo.', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 5, 'Ba i''iagö Yeruzalema Rehabeamo. Ba i''aro''ö ösa mbanua ba danö mado Yuda;', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 6, 'ya''ia Mbetilekhema ba Etama ba Tekoa,', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 7, 'ba Beti Zuri ba Sokho ba Adula,', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 8, 'ba Gata ba Maresa ba Sifi,', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 9, 'ba Adora''i ba Lakhisi ba Aseka,', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 10, 'ba Sorea ba Ayalona ba Heberona, banua ba mado Yuda ba ba mado Mbeniyami, ibali''ö banua saro.', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 11, 'Aro sibai mbanua saro andrö ibe''e, ba ifataro gumandra, ba ihöna gö, ba fanikha ba agu,', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 12, 'ba idozigö banua andrö baluse ba toho, ba i''aro''ö sibai. Ba no khönia mado Yuda, awö mado Mbeniyami.', '["Ayati 1–4: RazI 12:21–24"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 13, 'Ba ere ba Ono Lewi si so ba Ndraono Gizeraeli heza, ba so moroi ba danö heza, ba la''oro''ö ira enoninia.', '["Faigi 13:9","MozIII 17:7; RazI 12:31"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 14, 'Laröi mbenuara ba hadia ia zi so khöra ere andrö, ba lasaŵa danö mado Yuda ba Yeruzalema. Noa sa latibo''ö ira Yerobeamo ba ononia, fa böi sa''ae mo''ere ira föna Yehowa.[2]', '["Faigi 13:9","MozIII 17:7; RazI 12:31"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 15, 'Ba no ifataro khönia gere Yerobeamo, ere ba hili-hili andrö, ba ba wamaedo nambi si matua ba ba wamaedo nono zaŵi andrö, nifafazökhi''önia.[3]', '["Faigi 13:9","MozIII 17:7; RazI 12:31"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 16, 'Ba moroi ba mado Ndraono Gizeraeli fefu, ba fao khö ndra Rehabeamo zi so ba dödö wangalui Yehowa, Lowalangi Ndraono Gizeraeli. Lasaŵa Yeruzalema, ba wame''e sumange khö Yehowa, Lowalangi ndra tuara.', '["Faigi 13:9","MozIII 17:7; RazI 12:31"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 17, 'Ba abölö nöri mado Yuda labe''e, ba aro Rehabeamo, ono Zelomo, medölu fakhe, me no sanörö lala ndra Dawido Selomo ira, medölu fakhe wa''ara.', '["Faigi 13:9","MozIII 17:7; RazI 12:31"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 18, 'Ba Rehabeamo, ba ihalö Mahalata, ono Yerimoto ono Dawido; Abihaila, ono Geliabi ono Giza''i ninania;[4]', '["SamI 16:6","Faigi 21:3"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 19, 'ba mo''ono da''ö khönia, ono matua, Ye''usi ba Semaria ba Sahama.', '["SamI 16:6","Faigi 21:3"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 20, 'Ba ihalö na göi Ma''akha, ono Gabisalomi; ba mo''ono da''ö khönia, Abia ba Ata''i ba Sisa ba Selomiti.', '["SamI 16:6","Faigi 21:3"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 21, 'Ba abölö i''omasi''ö Ma''akha, ono Gabisalomi, Rehabeamo, moroi ba wa''omasinia ndrongania bö''ö, awö ndrongania ba döi; 18 sa nihalönia ira alawe, ba 60 ndrongania ba döi, ba 28 nononia matua ba 60 nono alawe.', '["SamI 16:6","Faigi 21:3"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 22, 'Ba Abia andrö, ono Ma''akha, ba ibe''e amaedola zatua baomo amania Rehabeamo, ibe''e högö dalifusönia, ibali''ö razo dania ia, dödönia.', '["SamI 16:6","Faigi 21:3"]', NULL),
  (3475132, 'OT', 'Nga''ötö II', 11, 23, 'Onekhe Rehabeamo, ifosasi nononia ösa, ifataro ba danö mado Yuda ba ba danö mado Mbeniyami misa, ba mbanua saro andrö fefu; itaha mbalazora, si lö ambö, ba oya ihalö khöra ira alawe.[5]', '["SamI 16:6","Faigi 21:3"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 1, 'Ba me no aro wa''arazo khö Rehabeamo ba me no isöndra wa''abölö, ba i''erogö goroisa Yehowa, ba awönia Ndraono Gizeraeli fefu.[1]', '["Faigi göi RazI 14:21–31","Faigi 11:5–10"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 2, 'Ba me no alua mendröfa fakhe razo Rehabeamo, ba so moroi si tou Zizaki, razo Miserayi, möi musuwö Yeruzalema, börö me no faröi ira khö Yehowa.', '["Faigi göi RazI 14:21–31","Faigi 11:5–10"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 3, '1200 gureta khö Zizaki ba 60.000 niha si fakudo, ba sato, si fao khönia moroi ba danö Miserayi, ba lö mutaha mu''erai: Dawa Libia ba Dawa Zukhi ba Dawa Gaitiofia.', '["Faigi göi RazI 14:21–31","Faigi 11:5–10"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 4, 'Atu''a ia ba mbanua saro andrö, ba danö mado Yuda, ba irugi Yeruzalema.[2]', '["Faigi göi RazI 14:21–31","Faigi 11:5–10"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 5, 'Ba so Zemaya sama''ele''ö andrö; möi ia khö ndra Rehabeamo satua mado Yuda, si no möi miyomo ba Yeruzalema, ba wa''ata''ura Zizaki, imane khöra: Da''ö niŵa''ö Yehowa: No mi''erogö ndra''odo, ba ululu sa''ae göi ami ba danga Zizaki!', '[]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 6, 'Ba mangalulu zatua mado Yuda, awö razo, ba lamane:', '[]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 7, 'Satulö nilau Yehowa! Ba me i''ila Yehowa, no mangalulu ira, ba humede ia khö Zemaya, imane: No mangalulu ira, ba lö ufakiko ira, ufaigi sa khöra wangorifi ma''ifu, fa lö ube''e ifatörö ba Yeruzalema wönugu Sizaki.', '[]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 8, 'Ba si möi barö mbawania sa ira, ena''ö la''ila, wa no faehu ira we''amöi enonigu we''amöi enoni razo niha baero.', '[]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 9, 'Ba so Zisaki, razo Miserayi, isaŵa Yeruzalema, ba ihalö girö-girö andrö ba gosali Yehowa, awö girö-girö ba gödo razo, ahori ihalö; ba he baluse ana''a andrö, nifafazökhi''ö Zelomo, ba ihalö.', '["Faigi 6:20"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 10, 'Ba i''angali''ö baluse töla Rehabeamo ba ibe''e ba danga gumandra wazuri, sanaro ba mbawandruhö gödo razo.', '["Faigi 6:20"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 11, 'Ba ero na möi ba gosali Yehowa razo, ba so wazuri andrö ba la''amaluse mbaluse no mege, ba lafuli dania ba naha wazuri.', '["Faigi 6:20"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 12, 'Ba me mangalulu razo, ba alö wönu Yehowa khönia, lö ifalua ifakiko; so sa atö na ma''ifu zi sökhi ba mado Yuda.', '["Faigi 6:20"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 13, 'Ba tobali i''aro''ö ia ba Yeruzalema razo Rehabeamo; ba Yeruzalema razo ia; 41 fakhe ia, me tobali razo ia, ba mewelewitu fakhe razo ia ba Yeruzalema, ba mbanua andrö nituyu Yehowa ba mado Ndraono Gizeraeli fefu, ba wamonahia töinia ba da''ö. Töi ninania, ba Na''ama, Iraono Moabi.[3]', '["Faigi 6:20"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 14, 'Ba si lö sökhi ilau; lö''ö sa ibe''e dödönia wangalui Yehowa.', '["Faigi 6:20"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 15, 'Ba hikaya Rehabeamo andrö, he famobörö, ba he safuria, ba no mutanö ba zura hikaya andrö khö Zemaya sama''ele''ö ba khö Ido sangi''ila andrö. Ba fasuwöta ndra Rehabeamo Yerobeamo, ba no sagötö fa''ara.', '["Faigi 6:20"]', NULL),
  (3475133, 'OT', 'Nga''ötö II', 12, 16, 'Ba mate Rehabeamo, itörö lala ndra amania, ba ba mbanua Dawido andrö lako''o ia. Ba fangalinia razo, ba ononia Abia.', '["Faigi 6:20"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 1, 'Me no alua mewelewitu fakhe razo Yerobeamo tobali razo mado Yuda Gabia.[1]', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475134, 'OT', 'Nga''ötö II', 13, 2, 'Medölu fakhe razo ia ba Yeruzalema; ba töi ninania, ba Ma''akha, ono Gurieli, banua Gibea. Ba fasuwö ira Gabia Yerobeamo.', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 3, 'Abia zi börötaigö fasuwöta andrö, ato sibai khönia zabölö, 400.000 nitutuyu. Ba ifaondragö ia Yerobeamo, no te''anö göi ira, 800.000, sabölö.', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 4, 'Ba i''agö zuzu hili Zemara''i Abia, ba hili mado Geferayi, ba mu''ao ia, imane: Mifondrondrongo, ya''ugö Yerobeamo ba ya''ami Iraono Gizeraeli!', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 5, 'Hadia, lö mi''ila ena''ö wa no khö Dawido ba ba nga''ötönia ibe''e wa''arazo ba Ndraono Gizeraeli Yehowa, Lowalangi Ndraono Gizeraeli, si lö mamalö-malö, ba wawu''usa li andrö nilau asio?[2]', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 6, 'Ba no maoso Yerobeamo andrö, ono Nebati, enoni Zelomo ono Dawido, ilaŵa zokhö ya''ia.[3]', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 7, 'Ba no mangondra khönia niha sambö era-era, niha si lö ngaroro, ba no lahöndrögö Rehabeamo, ono Zelomo; me no ono matua na Rehabeamo, sambö fa''abe''e dödö, ba tebai itimba ira.', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 8, 'Ba iada''e, ba miwai mi''ila milaŵa wa''arazo andrö khö Yehowa, si so ba danga nga''ötö Dawido, me no ato sibai ami, ba me no awömi nono zaŵi balaki andrö, nifazökhi Yerobeamo Lowalangimi.[4]', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 9, 'Hadia, tenga no mitibo''ö gere andrö khö Yehowa, nga''ötö Ga''aroni andrö, fabaya Ono Lewi, ba tenga no miwöwöi khömi gere, si mane ere ba niha baero? Ha niha zolohe ono zaŵi, sageu, ba biri-biri si matua, fitu nga''eu, ba wamamataro''ö ya''ia ere, ba tefataro ere ba zi tenga Lowalangi.[5]', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 10, 'Ba Lowalangima, ba Yehowa, ba lö ni''erogöma ya''ia, ba ere khö Yehowa nga''ötö Ga''aroni, ba lahalö-halö halöŵöra Ono Lewi,', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 11, 'ero mahemolu ba ero owi latunutunu khö Yehowa zumange nitunu ba kumöyö ba hadia ia zamohua, ba lafa''oli roti andrö ba meza balaki, ba ero owi, ba latunu wandru, ba naha wandru ana''a andrö. Me matöngöni nifakhoi Lowalangima, Yehowa, ba ya''ami, ba no mi''erogö ia![6]', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 12, 'Si ndruhu, itolo ndra''aga Lowalangi, solohe ya''aga, ba no fao khöma gere andrö khönia ba torofe andrö fangekhugö niha, ba wangekhugö niha, khömi. He ya''ami, Iraono Gizeraeli! Böi milaŵa Yehowa, Lowalangi ndra tuami, ba wa lö boto sa atö aekhu khömi![7]', '["Faigi göi RazI 15:1–8","MozIII 2:13; MozIV 18:19","RazI 11:26","RazI 12:28","MozII 18:41; MozV 32:17; Faigi 11:15","MozII 6:12; MozIV 28:3–8","MozIV 10:8,9"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 13, 'Ba iŵa''ö Yerobeamo lafasui mado Yuda si no mamini''ö ya''ira mege; ba tobali lafaondragö mado Yuda, ba so göi moroi furi zi no tobini mege.', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 14, 'Ba me labali''ö ira furi mado Yuda, ba la''ila, faoma lalau khöra, he moroi föna ba he moroi furi. Ba la''angaröfi li Yehowa, ba lalau dorofe ere,', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 15, 'ba lahahagö mado Yuda; ba me lahahagö, ba te''ala Yerobeamo ba Iraono Gizeraeli fefu, ibe''e Lowalangi, khö Gabia ba ba ba mado Yuda.', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 16, 'Ba moloi Ndraono Gizeraeli labe''e mado Yuda, ba ibe''e ba danga mado Yuda ira Lowalangi.', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 17, 'Ba ato sibai ira nibunu ndra Abia sabölö andrö khönia, tobali 500.000 zi mate nibunu, Iraono Gizeraeli.', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 18, 'Ba tobali nihöndrögö Ndraono Gizeraeli, ba sabölö mado Yuda, me no labe''e we''e-we''e dödöra Yehowa, Lowalangi ndra tuara.', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 19, 'Ba igohi Yerobeamo Abia, ba ifadöni khönia mbanua ösa: Betieli, fabaya halama soya khöra, ba Eferona, fabaya halama soya khöra.', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 20, 'Ba no amomo Yerobeamo, ba götö Gabia andrö. Ba ibözi ia Yehowa ba mate ia.', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 21, 'Ba itugu abölö Gabia; 14 ihalö ira alawe, ba 22 nononia, ono matua, ba 16 nono alawe.', '["Faigi 12:15"]', NULL),
  (3475134, 'OT', 'Nga''ötö II', 13, 22, 'Ba hadia na niŵa''ö ena''ö, ba khö Gabia andrö, ba bua-buania ba huhuonia, ba no mutanö ba zura hikaya andrö khö Ido sama''ele''ö.[8]', '["Faigi 12:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 1, 'Ba mate Gabia, itorö lala ndra amania, ba ba mbanua Dawido andrö lako''o ia. Ba fangalinia razo, ba ononia Asa. Ba me razo da''ö, ba lö hadia ia, sahono manö ira ba danö, mewulu fakhe.[1]', '["Ayati 1–4: RazI 15:11.12","MozIII 26:30","Faigi 15:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 2, 'Ba satulö ilau Asa ba si sökhi wamaigi Lowalanginia, Yehowa.', '["Ayati 1–4: RazI 15:11.12","MozIII 26:30","Faigi 15:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 3, 'Iheta naha wame''e sumange bö''ö andrö, fabaya hili-hili andrö, irasa harefa, ba i''obö geu ni''amoni''ö.', '["Ayati 1–4: RazI 15:11.12","MozIII 26:30","Faigi 15:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 4, 'Ba iŵa''ö ba mado Yuda, Yehowa, Lowalangi ndra tuara la''olembai ba la''o''ö goroisa, awö gamakhoita.', '["Ayati 1–4: RazI 15:11.12","MozIII 26:30","Faigi 15:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 5, 'Iheta hili-hili andrö, awö nadu luo, ba mbanua mado Yuda fefu, ba sahono gamatöröŵania, ba götönia.[2]', '["Ayati 1–4: RazI 15:11.12","MozIII 26:30","Faigi 15:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 6, 'Ba i''aro''ö mbanua mado Yuda ösa; me no sahono ira ba danö, ba me lö''ö manö sanuwö ya''ira, ba götö da''ö, me no ifaigi khöra wa''ahono Yehowa.[3]', '["Ayati 1–4: RazI 15:11.12","MozIII 26:30","Faigi 15:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 7, 'Andrö wa imane Asa ba mado Yuda: Datataru''ö mbanua andrö ba ta''ölini öli kara ba tafomalige ba tafobawa göli nilazi, me no fönada manö na danö, börö me lö niböhölida Yehowa, Lowalangi ndra tuada. No ya''ia ta''olembai, ba lö hadia ia khöda, fasui manö, ibe''e. Ba lalau, ba mofozu.', '["Ayati 1–4: RazI 15:11.12","MozIII 26:30","Faigi 15:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 8, 'Ba no ato zabölö khö Asa, solohe baluse ba toho: mado Yuda, ba 300.000, ba mado Mbeniyami, ba 280.000, solohe baluse ba sogai fana — oi sabölö.', '["Ayati 1–4: RazI 15:11.12","MozIII 26:30","Faigi 15:15"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 9, 'Ba so moroi si tou Zera, Dawa Gaitiofia, möi manuwö ya''ira, 1.000.000 khönia zabölö ba 300 gureta, ba irugi Maresa.', '["SamI 14:6"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 10, 'Ba ifaondragö ia Asa, ba ndraso Zefata lafa''anö ira, ba ngai Maresa.', '["SamI 14:6"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 11, 'Ba i''angaröfi li Lowalanginia Yehowa Asa, mangandrö ia, imane: "He Yehowa, ha ya''ugö zangila manolo si tebai ba zabölö. Tologa, ya''ugö Yehowa, Lowalangima! Ya''ugö sa we''e-we''e dödö, ba no moroi ba döimö, wa no mafaondragö zato sibai andrö. He Yehowa, Lowalangima ndra''ugö; lö sangila molaŵa ya''ugö niha si mate andrö!"[4]', '["SamI 14:6"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 12, 'Ba ibözi Ndrawa Gaitiofia Yehowa, föna Asa ba föna mado Yuda, ba moloi ira.', '["SamI 14:6"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 13, 'Ba lagohi ira Asa ba awönia sabölö andrö, irugi ba Gerara. Ba ato sibai zi mate Dawa Gaitiofia, lö fangorifi sa''ae; nirasa sa''ae ira khö Yehowa ba ba zabölö andrö khönia. Ba ebua sibai zahulu mado Yuda,', '["SamI 14:6"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 14, 'ba atu''a ira ba mbanua andrö fefu, si tefasui Gerara; noa sa ihawui fa''ata''u khö Yehowa mbanua andrö. Ba la''oloi''ö gana''a ba hadia ia na ba mbanua andrö fefu [mado Yuda], ebua sibai nisöndrara khöra.', '["SamI 14:6"]', NULL),
  (3475135, 'OT', 'Nga''ötö II', 14, 15, 'Ba ose gurifö, ba lahawui ba oya sibai la''oloi''ö biri-biri ba ondra, ahuluara, ba lafuli ira ba Yeruzalema.', '["SamI 14:6"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 1, 'Ba so Geheha Lowalangi khö Gasaria, ono Gobedi,', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 2, 'ba möi ia tou, ifaondragö Asa, ba imane khönia: Mifondrondrongo khögu, ya''ugö Asa ba ya''ami mado Yuda ba mado Mbeniyami, fefu! Itolo ami Yehowa, na lö aefa ami khönia! Na mi''alui ia, ba i''oro''ö ia khömi; ba na mi''erogö ia, ba i''erogö göi ami.[1]', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 3, 'Ara manö, wa lö Lowalangi si ndruhu ba Ndraono Gizeraeli ba lö ere. Samahaö ya''ira, ba lö oroisa.[2]', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 4, 'Ba aefa da''ö, ba lafuli ira khö Yehowa, Lowalangi Ndraono Gizeraeli, me no tosasa ira; ba me la''alui ia, ba i''oro''ö ia khöra.[3]', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 5, 'Ba me luo da''ö, ba sata''u manö zofanö ba sata''u göi zangawuli; dozi niha ba danö, ba oi humufa manö.[4]', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 6, 'Si fa''obi manö soi, ba he banua, me no Lowalangi zamahufa ya''ira wamatörö famakao, hadia ia ngawalö.[5]', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 7, 'Ba ya''ami, ba mi''abe''e''ö dödömi, böi adada dangami, tefoluo sa dania wolaumi![6]', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 8, 'Ba me irongo Asa niŵa''ö andrö ba fama''ele''ö Gasaria, ono Godedi, ba i''abe''e''ö dödönia ba ifaheta''ö zogoro ita andrö, ba danö mado Yuda, ba ba danö mado Mbeniyami, ma''asagörö, ba ba mbanua andrö, nifadöninia, ba hili mado Geferayi; ba i''azökhi naha wame''e sumange khö Yehowa, föna gewe''ewe andrö, khö Yehowa.', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 9, 'Ba ifalukha''ö mado Yuda, awö mado Mbeniyami, fefu, awö mado Geferayi andrö ba mado Manase ba mado Zimeoni, si no fatewu khöra; noa sa ato zi möi khönia Iraono Gizeraeli, me no la''ila itolo ia Lowalanginia Yehowa.', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 10, 'Ba owulo ira ba Yeruzalema, me baŵa si tölu, me no alua meweleöfa fakhe razo Asa,', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 11, 'ba lataba khö Yehowa gahulua andrö ösa, nihalöra, 700 nga''eu zaŵi ba 7000 nga''eu mbiri-biri.', '["Nga''ötI 28:9; Yer 29:13; Mat 7:7","Hos 3:4","MozV 4:29; Yer 29:13,14","Mat 24:21","Mat 24:7","KorI 15:58"]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 12, 'Ba lafabu''u sibai, moroi si''aikö ba dödöra ba ba gera-erara lö laböhöi Yehowa, Lowalangi ndra tuara;[7]', '["Yos 24:25","Faigi 14:5,6; 20:30","Ayati 16–18: RazI 15:13–15","RazI 15:13 b.t."]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 13, 'ba na so ha niha, zangerogö Yehowa, Lowalangi Ndraono Gizeraeli, ba nibunu, he iraono, ba he satua, he ira matua, ba he ira alawe.', '["Yos 24:25","Faigi 14:5,6; 20:30","Ayati 16–18: RazI 15:13–15","RazI 15:13 b.t."]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 14, 'Ba fahölu ira khö Yehowa, la''ebua''ö lira ba fao wa''owua-wua dödö ba folau torofe, he torofe nidödöni.', '["Yos 24:25","Faigi 14:5,6; 20:30","Ayati 16–18: RazI 15:13–15","RazI 15:13 b.t."]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 15, 'Ba omuso dödö mado Yuda fefu, ba wahölusa andrö, me no moroi si''aikö ba dödöra fahölu ira, ba no moroi si''aikö ba dödö göi wangalui Yehowa, ba i''oro''ö göi ia khöra, ba lö hadia ia khöra ibe''e, fasui manö.[8]', '["Yos 24:25","Faigi 14:5,6; 20:30","Ayati 16–18: RazI 15:13–15","RazI 15:13 b.t."]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 16, 'Iheta göi salaŵa ninania Ma''akha Asa,[9] me no ifazökhi nadu khö Gasera. Ba adu andrö khönia, ba i''eŵa Asa, irasa ba itunu ba ndraso Gendrona.[10]', '["Yos 24:25","Faigi 14:5,6; 20:30","Ayati 16–18: RazI 15:13–15","RazI 15:13 b.t."]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 17, 'Ba hili-hili andrö, ba lö''ö sa mubulö''ö ba Ndraono Gizeraeli, ba Asa, ba no sadölö tödö, götö wa''anau nosonia.', '["Yos 24:25","Faigi 14:5,6; 20:30","Ayati 16–18: RazI 15:13–15","RazI 15:13 b.t."]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 18, 'Ba ifabe''e''ö göi ba gosali Lowalangi ni''amoni''ö namania, awö mbualania ni''amoni''ö — ana''a ba firö ba gama-gama.', '["Yos 24:25","Faigi 14:5,6; 20:30","Ayati 16–18: RazI 15:13–15","RazI 15:13 b.t."]', NULL),
  (3475136, 'OT', 'Nga''ötö II', 15, 19, 'Ba lö sanuwö ya''ira, irugi no alua 35 fakhe razo Asa.', '["Yos 24:25","Faigi 14:5,6; 20:30","Ayati 16–18: RazI 15:13–15","RazI 15:13 b.t."]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 1, 'Ba me no alua 35 fakhe razo Asa, ba so moroi si yaŵa Mba''esa, razo Ndraono Gizeraeli, ba wanuwö mado Yuda; i''aro''ö Rama, ba womba''a lala niha khö Asa, razo mado Yuda.[1][2]', '["Ayati 1–6: RazI 15:16–22","RazI 15:17 b.t."]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 2, 'Ba ihalö wirö ba ana''a Asa ba nahia girö-girö ba gosali Yehowa ba ba gödo razo, ifa''ohe''ö khö Mbenihada, razo Ndrawa Garamo, ba Ndramaseko, imane khönia:', '["Ayati 1–6: RazI 15:16–22","RazI 15:17 b.t."]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 3, 'Si no fawu''u li ita ba ira amada mege. Ba hiza, ba ufa''ohe''ö khöu wirö ba ana''a: ba labu, dudugö wawu''usa li andrö khömi Ba''esa, razo Ndraono Gizeraeli, ena''ö ibato wanuwö ya''o.', '["Ayati 1–6: RazI 15:16–22","RazI 15:17 b.t."]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 4, 'Ba ifondrondrongo li razo Asa, Benihada, ba ifatenge ba mbanua Ndraono Gizeraeli gumandra khönia, ba ladudugö Niyono ba Dano, ba Habeli Ma''i ba omo mbalazo nihöna fefu, ba mbanua mado Nafetali.', '["Ayati 1–6: RazI 15:16–22","RazI 15:17 b.t."]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 5, 'Ba me irongo da''ö Ba''esa, ba iböhöli wangaro''ö Rama, i''etu''ö halöŵönia.', '["Ayati 1–6: RazI 15:16–22","RazI 15:17 b.t."]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 6, 'Ba i''ohe mado Yuda fefu razo Asa, ba lahalö gara andrö ba eu balo, ni''oguna''ö Mba''esa fangaro Rama, ba ibe''e fangaro Geba ba fangaro Misefa Asa.', '["Ayati 1–6: RazI 15:16–22","RazI 15:17 b.t."]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 7, 'Ba me luo da''ö, ba möi khö Asa, razo mado Yuda, Hanani sangi''ila andrö, imane khönia: Me no öbe''e we''e-we''e dödöu razo Ndrawa Garamo, ba me tenga Yehowa, Lowalangi, ba no aefa ba dangau zabölö Ndrawa Garamo andrö.', '["Nga''ötII 14:9; Faigi 14:8–12","Yob 34:21; Sin 34:16; Sakh 4:10","Faigi 18:26; Mat 14:3"]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 8, 'Hadia, tenga no ato sibai Ndrawa Gaitiofia no ba Dawa Libia, ba tenga no oya sibai khöra gureta, awö zi fakudo? Ba me no öbe''e we''e-we''e dödöu Yehowa, ba no ibe''e ba dangau ira.[3]', '["Nga''ötII 14:9; Faigi 14:8–12","Yob 34:21; Sin 34:16; Sakh 4:10","Faigi 18:26; Mat 14:3"]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 9, 'Ihörö-hörögö sa guli danö ma''asagörö Yehowa, ena''ö i''abölögö wanolo si no adölö tödö khönia. Nifolau zi lö tödö khöu da''ö; i''otarai da''e sa, ba lö aefa-aefa khöu wasuwöta![4]', '["Nga''ötII 14:9; Faigi 14:8–12","Yob 34:21; Sin 34:16; Sakh 4:10","Faigi 18:26; Mat 14:3"]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 10, 'Ba mofönu Asa khö zangi''ila andrö ba ifakuru''ö, börö wönunia khönia ba da''ö. Ba ifakao mbanuania ösa Asa, me luo da''ö.[5]', '["Nga''ötII 14:9; Faigi 14:8–12","Yob 34:21; Sin 34:16; Sakh 4:10","Faigi 18:26; Mat 14:3"]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 11, 'Ba hikaya Asa andrö, he famobörö mege, ba he safuria andrö, ba no mutanö ba zura hikaya razo mado Yuda ba ba hikaya razo Ndraono Gizeraeli.[6]', '["Ayati 16:11–14:RazI 15:23.24","Faigi 21:19; MozII 50:2; Yer 34:5"]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 12, 'Ba me no alua 38 fakhe razo ia, ba mofökhö ia, fökhö gahe; abölö-bölö sibai wökhönia andrö. Ba he ba wökhönia andrö, ba lö i''alui Yehowa, ha same''e dalu-dalu.', '["Ayati 16:11–14:RazI 15:23.24","Faigi 21:19; MozII 50:2; Yer 34:5"]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 13, 'Ba mate Asa, itörö lala ndra amania, me no alua 40 fakhe razo ia.', '["Ayati 16:11–14:RazI 15:23.24","Faigi 21:19; MozII 50:2; Yer 34:5"]', NULL),
  (3475137, 'OT', 'Nga''ötö II', 16, 14, 'Ba lako''o ia ba lewatönia andrö, nifakharu''önia khönia ba mbanua Dawido. Labe''e ba gaso, si no mulau dalu-dalu ba hadia ia ngawalö zamohua, nifaruka, si mane na lafaruka dalu-dalu nigule''ö; ba ebua latunu samohua khönia.[7]', '["Ayati 16:11–14:RazI 15:23.24","Faigi 21:19; MozII 50:2; Yer 34:5"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 1, 'Ba ononia Yozafati zi tobali razo fangalinia, ba abe''e da''ö, udu Ndraono Gizeraeli.[1]', '["RazI 15:24","RazI 10:25; Faigi 18:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 2, 'Ba idozigö banua saro wamataro sabölö, ba ba danö mado Yuda ba ba mbanua mado Geferayi andrö, nifadöni namania Asa khöra, ba ifataro zanaro.', '["RazI 15:24","RazI 10:25; Faigi 18:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 3, 'Ba itolo Yozafati Yehowa, me no sanörö lala duania Dawido ia, lala ba mböröta, ba tenga si olembai Ba''ali andrö ia,', '["RazI 15:24","RazI 10:25; Faigi 18:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 4, 'lö''ö sa iböhöli Lowalangi duania andrö, i''o''ö goroisania, tenga si mane Iraono Gizeraeli.', '["RazI 15:24","RazI 10:25; Faigi 18:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 5, 'Andrö tedou wa''asalaŵa, me ya''ia zolohe, ibe''e Yehowa; ba mado Yuda fefu, ba momamuala khö Yozafati, ba tobali fahöna khönia gana''a, ba he sumange.[2]', '["RazI 15:24","RazI 10:25; Faigi 18:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 6, 'Ba me itugu abe''e dödönia wanörö lala andrö, nifakhoi Yehowa, ba iheta göi hili-hili andrö, fabaya eu ni''amoni''ö andrö, ba mado Yuda.', '[]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 7, 'Ba me no alua mendrua fakhe razo ia, ba ifatenge nawönia salaŵa andrö: Benihaili ba Obadia ba Sakharia ba Netana''eli ba Mikhaya, ba wamahaö banua mado Yuda,', '[]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 8, 'ba ibe''e awöra Nono Lewi: Semaya ba Netania ba Sebadia ba Azaheli ba Semiramoto ba Yonata ba Adonia ba Tobia ba Tobi-Adonia, Ono Lewi andrö, ba fao na göi gere, Elisama ba Yoramo.', '[]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 9, 'Da''ö zamahaö mado Yuda; la''ohe zura goroisa Yehowa ba latöröi mbanua mado Yuda fefu, mamahaö niha sato.', '[]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 10, 'Ba ihawui fa''ata''u Yehowa gamatöröŵa niha baero fefu, si tefasui mado Yuda, ba tobali lö lasuwö Yozafati.', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 11, 'Ba Dawa Wilisiti ösa, ba la''ohe mbuala khö Yozafati, ba firö, beo; ba he Dawa Ara, ba la''ohe khönia gurifö side-ide: 7700 mbiri-biri si matua, ba 7.700 nambi si matua.[3]', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 12, 'Ba tobali itugu tedou manö wa''abölö Yozafati, irege no fahöna, ba itaru''ö hati ba danö mado Yuda ba banua ba nihöna balazo.', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 13, 'Ba no fahöna khöra mbalazo ba mbanua mado Yuda andrö ba ato zabölö ba Yeruzalema.', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 14, 'Ba da''ö wama''oli ya''ira, ba ngafura andrö: högö ngahönö ba mado Yuda, ba Adena, högö, ba 800.000 nawönia sabölö;', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 15, 'aefa da''ö, ba Yohanano, högö göi,', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 16, 'ba 280.000 nawönia sabölö, ba aefa da''ö, ba Amasia, ono Zikhiri, si no mangoro''ö ya''ia khö Yehowa, saoha gölö, ba 200.000 nawönia sabölö.', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 17, 'Ba mado Mbeniyami, ba Eliada sabölö andrö, ba 200.000 nawönia si no mangaro, fana ba baluse,', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 18, 'ba aefa da''ö, ba Yosabada ba 180.000 nawönia, si no mangaro, ba wasuwöta.', '["RazI 5:1"]', NULL),
  (3475138, 'OT', 'Nga''ötö II', 17, 19, 'Da''ö genoni razo andrö, lö lai nifataronia ba mbanua saro andrö, ba danö mado Yuda ma''asagörö.', '["RazI 5:1"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 1, 'Ba tobali fahöna gana''a ba lakhömi khö Yozafati, ba fambambatö ia khö Gahabi.[1][2]', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 2, 'Ba so medölu fakhe, ba möi ia misi tou khö Gahabi ba Zamaria. Ba oya nga''eu ihalö Ahabi biri-biri ba saŵi, diwonia ba diwo nawönia fao, ba ifowöhö ia ba wefao ba wanuwö Ramoti ba danö Gileadi.', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 3, 'Imane Ahabi, razo Ndraono Gizeraeli, khö Yozafati, razo mado Yuda: Hadia, möi''ö awögu ba Ramoti ba danö Gileadi? Ba imane khönia: Si mane ya''ugö ndra''odo; ba banuagu, ba si mane banuau, ba möido awöu ba wanuwö!', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 4, 'Ba imane na Yozafati khö razo Ndraono Gizeraeli: Tema sofu ua, ha iŵa''ö Yehowa![3]', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 5, 'Ba ifalukha''ö zama''ele''ö andrö razo Ndraono Gizeraeli, 400, ba isofu khöra, imane: Hadia, möido manuwö Ramoti ba danö Gileadi, ba ma alakha lö''ö? Ba lamane khönia: Ae''e, ena''ö ibe''e ba danga razo ira Lowalangi!', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 6, 'Ba imane Yozafati: Hadia, lö baero ö sama''ele''ö khö Yehowa, ena''ö khönia tasofu?', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 7, 'Ba imane razo Ndraono Gizeraeli khö Yozafati: So na zamösa tö, si tola tabe''e sanofu khö Yehowa; ba no abao dödögu khönia, me tenga si sökhi nifa''ele''ele''önia ba khögu andre, ha si lö sökhi: Mikha andrö, ono Yimela. Ba imane Yozafati: Böi ŵa''ö da''ö, ya''ugö razo.', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 8, 'Ba humede razo Ndraono Gizeraeli khö genoninia, imane: Ta''i-ta''i hede khö Mikha andrö, ono Yimela!', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 9, 'Ba razo Ndraono Gizeraeli ba Yozafati, razo mado Yuda, ba no dumadao ba mbawa göli Zamaria, baru luo mbarura, ba dadaomania dumadao zamösana, ba mama''ele''ö zama''ele''ö andrö fefu fönara.', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 10, 'Ba ifotandru si''öli ia Sedekia, ono Gena''ana, ba imane: Da''ö niŵa''ö Yehowa: ötandru dania tou Ndrawa Garamo tandru si mane da''e, irege no ahori ira öbe''e!', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 11, 'Ba si manö wama''ele''ö andrö fefu, ba lamane: Ae ba Ramoti andrö, ba danö Gileadi, ba si sökhi dania wozu khöu, ba ibe''e ba danga razo ira Yehowa!', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 12, 'Ba imane khö Mikha andrö sinenge andrö, si no möi mogaoni ya''ia: Hiza, ha sara manö li zama''ele''ö andrö, wangombakha si sökhi khö razo, ba böi faehusi niŵa''öu ba niŵa''öra fefu; si sökhi ŵa''ö.', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475139, 'OT', 'Nga''ötö II', 18, 13, 'Ba imane Mikha: Faya wa no sauri Yehowa, na tenga ha sambalö niŵa''ö Lowalalangigu khögu uŵa''ö!', '["Faigi göi RazI 22","Faigi 17:5","SamI 23:2; RazII 3:11"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 14, 'Ba me irugi razo, ba imane khönia razo: He Mikha, hadia, möiga manuwö Ramoti ba danö Gileadi, ma lö''ö? Ba imane: Mi''ae''e, ba mofozu wolaumi, ba tebe''e ba dangami ira.', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 15, 'Ba imane khönia razo: Ha me uga ube''e ba hölu ndra''ugö, ena''ö ha sambalö si duhu ö''ombakha''ö khögu ba döi Yehowa?', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 16, 'Ba imane: No u''ila, no muzaewe Ndraono Gizeraeli fefu, ba hili, hulö mbiri-biri si lö kubalo. Ba imane Yehowa: Si lö sökhi da''ö; hana na ifuli ia khöra zamösana, ya lö hadia ia khöra!', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 17, 'Ba imane razo Ndraono Gizeraeli khö Yozafati: Tenga no uŵa''ö khöu: Lö hadia ia zi sökhi ifa''ele''ö ba khögu andre, ha si lö sökhi?', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 18, 'Ba imane Mikha: Böi ua! Mifondrondrongo niŵa''ö Yehowa! No u''ila, no dumadao Yehowa ba dadaomania, ba no lafatambai ia banua zorugo sato.', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 19, 'Ba imane Yehowa: Ha niha zi möi mamowöhö Ahabi andrö, razo Ndraono Gizeraeli, ena''ö möi ia manuwö, ba ena''ö ba Ramoti ba danö Gileadi mate ia? Ba oi fabö''ö niŵa''öra.', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 20, 'Ba so zamösa mbekhu, i''ondrasi Yehowa, ba imane: Ya''o zi möi mamowöhö ya''ia! Ba imane khönia Yehowa: Ha öbe''e famowöhö?[4]', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 21, 'Ba imane: Möido bekhu sofaya ba mbewe zama''ele''ö andrö khönia fefu. Ba imane Yehowa: Ya''ia da''ö, öfalua dania wamowöhö andrö; ae''e ba lau da''ö!', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 22, 'Ba hiza, ba no ibe''e ba mbewe zama''ele''ö andrö khöu fefu mbekhu sofaya Yehowa, ba noa sa ihonogöi khöu wamakiko Yehowa.', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 23, 'Ba maoso Zedekia andrö, ono Gena''ana, itema ifalisi mbawa Mikha, ba imane: Ba hadia lala wa''aheta Geheha Yehowa khögu, ba wehedegu khöu?[5]', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 24, 'Ba imane Mikha: Hiza, ö''ila dania, na luo ötöröi mbate''e yomo, ba wamini''ö ya''ugö!', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 25, 'Ba imane razo Ndraono Gizeraeli: Mihalö Mikha, ba mi''ohe mangawuli ia khö Gamoni kumandra ba mbanua ba khö Yoasi, ono razo,', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 26, 'ba mimane: Da''ö niŵa''ö razo: Mikuru da''e, ba ha ma''ifu mibe''e gö ba ha ma''ifu nidanö, irege mangawulido lö hadia ia khögu.[6]', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 27, 'Ba imane Mikha: Na mangawuli ndra''ugö lö hadia ia khöu, ba tenga taroma li Yehowa nifa''emagu! Ba imane na: Mifondrondrongo, ya''ami niha fefu!', '["Yob 1:6","Mar 14:25; HalZin 23:2; Ayati 10","Faigi 16:10"]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 28, 'Ba möi razo Ndraono Gizeraeli, awö Yozafati, razo mado Yuda, lasaŵa Ramoti ba danö Gileadi.', '[]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 29, 'Ba imane razo Ndraono Gizeraeli khö Yozafati: Da''u''onukha nukha niha bö''ö, ba wanuwö andrö, ba ya''ugö, ba böi bulö''ö nukhamö. Ba ifohani ia razo Ndraono Gizeraeli, ba lasaŵa zi fasöndra ira.', '[]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 30, 'Ba no ibe''e li razo Ndrawa Garamo ba gumandra gureta ba wanuwö andrö khönia, no imane: Böi milau ba niha bö''ö, he ono mbanua ba he salaŵa, ha sambalö khö razo Ndraono Gizeraeli andrö!', '[]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 31, 'Ba me la''ila Yozafati kumandra gureta andrö, ba lamane: Da''ö razo Ndraono Gizeraeli andrö! Ba lafa''u''u ia, ba wolau khönia. Ba mu''ira-ira Yozafati, ba itolo ia Yehowa, idönisi misa ira Lowalangi, ena''ö laböhöli ia.', '[]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 32, 'Ba me la''ila kumandra gureta andrö, wa tenga razo Ndraono Gizeraeli ia, ba laböhöli ia, lafuli ira.', '[]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 33, 'Ba so zogai fanania, si lö mudöna-döna, ba i''efasi, ba göna khö razo Ndraono Gizeraeli, ba gotaluara mböbö talu göröba. Ba imane khö zolohe kuretania: Bali''ö, ohe misa ndra''o, hetado ba wasöndrata; noa sa mesokho ndra''o!', '[]', NULL),
  (3475139, 'OT', 'Nga''ötö II', 18, 34, 'Ba itugu abölö-bölö wasöndrata, me luo da''ö, ba razo Ndraono Gizeraeli, ba sizizio ba gureta, fetahö Ndrawa Garamo, irugi tanö owi; ba me aekhu-aekhu luo, ba mate ia.', '[]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 1, 'Ba Yozafati, razo mado Yuda, ba ifuli ia khöra ba Yeruzalema, lö hadia ia.', '["SamI 9:9; Sin 139:21","Nga''ötII 17:6; Faigi 17:3–6"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 2, 'Ba i''ondrasi ia Yehu sangi''ila andrö, ono Hanani, imane khö razo Yozafati: Hadia, sanolo sebua horö ndra''ugö ba somasi si fa''udu khö Yehowa? Andrö wa tohare sa''ae khöu wönu Yehowa![1]', '["SamI 9:9; Sin 139:21","Nga''ötII 17:6; Faigi 17:3–6"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 3, 'Ba ma''ifu zui musöndra khöu si sökhi: noa sa öhori ba danö Gasera andrö ba no aso''ala dödöu wangalui Lowalangi![2]', '["SamI 9:9; Sin 139:21","Nga''ötII 17:6; Faigi 17:3–6"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 4, 'Ba ba Yeruzalema i''iagö Yozafati. Ba awena dania ifuli itöröi mbanuania, i''otarai Mbereseba, numalö ba hili mado Geferayi; ba ifalalini gera-erania, ifuli ia khö Yehowa, Lowalangi ndra tuania.', '["MozV 1:17","Yob 34:10; Rom 2:11; MozII 18:21; MozV 10:17","MozV 17:8; 19:17"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 5, 'Ba ifataro zanguhuku ba danö, ba mbanua saro andrö ba mado Yuda, fefu, idozigö banua.', '["MozV 1:17","Yob 34:10; Rom 2:11; MozII 18:21; MozV 10:17","MozV 17:8; 19:17"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 6, 'Ba imane ba zanguhuku andrö: Mifaigi, he miwisa wolau! Tenga sa niha zanguma''ö khömi wanguhuku andrö, no Yehowa zanguma''ö, ba itolo ami ba wanguhuku.[3]', '["MozV 1:17","Yob 34:10; Rom 2:11; MozII 18:21; MozV 10:17","MozV 17:8; 19:17"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 7, 'Ba ena''ö ahono khömi wangata''ufi Yehowa! Mifaigi sibai, he wisa wolaumi andrö — khö Lowalangida Yehowa sa, ba lö fa''amuyu''ö huku, ba lö fa''ebua dödö zambuana ba lö femanga gana''a![4]', '["MozV 1:17","Yob 34:10; Rom 2:11; MozII 18:21; MozV 10:17","MozV 17:8; 19:17"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 8, 'Ba ba Yeruzalema göi ifataro Yozafati Nono Lewi ösa ba ere ba högö ngafu Ndraono Gizeraeli ösa, ba huhuo Yehowa, ba na so nifadöni mbanua Yeruzalema.[5]', '["MozV 1:17","Yob 34:10; Rom 2:11; MozII 18:21; MozV 10:17","MozV 17:8; 19:17"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 9, 'Ba imane wame''e li khöra: Mimanö sa''ae wolau, mi''ata''ufi Yehowa, böi falimo ami ba sadölö tödö ami.', '["MozV 1:17","Yob 34:10; Rom 2:11; MozII 18:21; MozV 10:17","MozV 17:8; 19:17"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 10, 'Ba ba ngawalö huhuo fefu, ni''ohe dalifusömi andrö, ba mbanuara misa, khömi, he na fange''e mbörö, ba he na oroisa ba ma amakhoita, ba he na hadia ia lala, ba ma hadia ia huku mbörö, ba mibotokhi ba dödöra, ena''ö böi mosala ira khö Yehowa ba fa lö göna ami fönu, ya''ami ba ira talifusömi. Mimanö wolau, ena''ö böi mosala ami!', '["MozV 1:17","Yob 34:10; Rom 2:11; MozII 18:21; MozV 10:17","MozV 17:8; 19:17"]', NULL),
  (3475140, 'OT', 'Nga''ötö II', 19, 11, 'Ba satuami, na so hadia ia huhuo Yehowa, ba Amaria ere sebua; ba na hadia ia huhuo razo, ba Sebadia, ono Zima''eli, salaŵa ba ma''uwu Yuda, zatuami. Ba si no amaedola gumandru khömi, ba Ono Lewi. Mi''abe''e''ö dödömi ba mimanö wolau; itolo zadölö tödö Yehowa!', '["MozV 1:17","Yob 34:10; Rom 2:11; MozII 18:21; MozV 10:17","MozV 17:8; 19:17"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 1, 'Ba aefa da''ö, ba so moroi sa Ndraono Moabi ba Iraono Gamoni ba banua Moini andrö ösa, si fao khöra, ba wanuwö Yozafati.', '["Sanguhuk 20:26","Faigi 15:9–15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 2, 'Ba me so zangombakha khö Yozafati: So moroi sa zanuwö ya''ugö, ato sibai, moroi yefo zilua asi moroi ba danö Ndraono Gedomo, no larugi Haseso Damara (ya''ia Engedi andrö)!', '["Sanguhuk 20:26","Faigi 15:9–15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 3, '— ba ata''u Yozafati, ba itema i''alui Yehowa, ba ifaŵa''ögö wamoni ba mado Yuda fefu.[1]', '["Sanguhuk 20:26","Faigi 15:9–15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 4, 'Ba owulo mado Yuda, ba we''angaröfi li Yehowa; moroi ba mbanua fefu misa so ira, ba wangalui Yehowa.[2]', '["Sanguhuk 20:26","Faigi 15:9–15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 5, 'Ba i''ondrasi zato, mado Yuda ba banua Yeruzalema, Yozafati, ba gosali Yehowa, fönaföna golayama si bohou andrö,', '["Nga''ötI 29:12; Faigi 14:10","RazI 8:37; Faigi 6:28–30","MozV 2:4,5,9,10,19"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 6, 'ba imane: "He Yehowa Lowalangi ndra tuama, hadia, tenga ya''ugö Lowalangi ba zorugo, ba hadia, tenga ya''ugö zamatörö fefu gamatöröŵa niha baero! Ba dangau so wa''abölö ba fa''abe''e, ba lö solaŵa ya''ugö.[3]', '["Nga''ötI 29:12; Faigi 14:10","RazI 8:37; Faigi 6:28–30","MozV 2:4,5,9,10,19"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 7, 'Ya''ugö mege zanimba niha ba danö andre, föna mbanuau Iraono Gizeraeli, ya''ugö Lowalangima, ba no öbe''e ba ma''uwu Gaberahamo andrö, si no fahuwu khöu, danö andre, si lö tebulö.', '["Nga''ötI 29:12; Faigi 14:10","RazI 8:37; Faigi 6:28–30","MozV 2:4,5,9,10,19"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 8, 'Ba no mowanua ira ba danö, ba no lalau khöu ni''amoni''ö, nahia döimo, lamane:', '["Nga''ötI 29:12; Faigi 14:10","RazI 8:37; Faigi 6:28–30","MozV 2:4,5,9,10,19"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 9, 'Na gönaga famakao, ma fanuwö ba ma fotu, hadia ia, ba ma fökhö waba ba ma lofo mbanua, ba möiga, ba golayama gosali andre, ma''ondrasi ndra''ugö — noa sa nahia döimö gosali andre — ba ma''angaröfi li ndra''ugö ba wa''atosasama andrö, ena''ö öfondrondrongo lima ba ena''ö ö''orifiga![4]', '["Nga''ötI 29:12; Faigi 14:10","RazI 8:37; Faigi 6:28–30","MozV 2:4,5,9,10,19"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 10, 'Ba hiza iada''e Ndraono Gamoni, awö Ndraono Moabi ba si oroi hili Ze''ira, ba zi lö öfa''amöi ba danö Iraono Gizeraeli, me la''otarai danö Miserayi; no lahole''ö ira khöra ba lö lahori.[5]', '["Nga''ötI 29:12; Faigi 14:10","RazI 8:37; Faigi 6:28–30","MozV 2:4,5,9,10,19"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 11, 'Ba iada''e, ba lasulöni khöma, so ira, ba wanimba ya''aga ba danöu andre, nibe''eu khöma!', '["Nga''ötI 29:12; Faigi 14:10","RazI 8:37; Faigi 6:28–30","MozV 2:4,5,9,10,19"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 12, 'He Lowalangima! Hadia, lö ö''otu''ö ira? Me no si tebai ndra''aga, ba niha sato sibai andrö, si so moroi sa, ba wanuwö ya''aga; ya''aga, ba lö ma''ila he mawisa, khöu mafaöga höröma!"', '["Nga''ötI 29:12; Faigi 14:10","RazI 8:37; Faigi 6:28–30","MozV 2:4,5,9,10,19"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 13, 'Ba ahori so mado Yuda ba da''ö, föna Yehowa, awö ndraono sawuyu khöra, ba awö wo''omora ba awö nonora matua.', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 14, 'Ba so Geheha Yehowa khö Yahazieli, ono Zakharia ono Mbenaya ono Yeieli ono Matania, ono Lewi, nga''otö Gasafo, ba hunö niha sato bakha, ba mu''ao ia,', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 15, 'imane: Mifondrondrongo, ya''ami mado Yuda ba ya''ami, banua Yeruzalema ba ya''ugö razo Yozafati! Imane khömi Yehowa: Böi mi''ata''ufi, ba böi tokea ami ba niha sato sibai andrö; tenga sa ya''ami zi fasöndra, no Lowalangi zi fasöndra![6]', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 16, 'Mifaondragö ira mitou mahemolu; so ira moroi sa, ba lala miyaŵa ba Zisi, ba ba lulu ndraso mbombo andrö fakhamö ami, tanö ba gatumbukha luo, na ta''otarai danö si mate andrö ba Yerueli.', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 17, 'Tenga ya''ami zi fasöndra zi samuza andre; mi''agö da''ö, ba mi''ila wangorifi andrö, fangorifi Yehowa ya''ami, ya''ami mado Yuda ba banua Yeruzalema. Böi mi''ata''ufi ba böi tokea ami! Mifaondragö ira mahemolu, ba itolo ami Yehowa!', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 18, 'Ba mangalulu Yozafati, irugi tou danö bawania; ba lafalögu tou ira mado Yuda fefu ba banua Yeruzalema, föna Yehowa, ba wangalulu khönia.', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 19, 'Ba maoso Nono Lewi andrö, nga''ötö ndra Kahati Kora, ba wanuno Yehowa, Lowalangi Ndraono Gizeraeli, la''ebua''ö lira.', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 20, 'Ba mahemolu ö, ba lahulö wongi wanaŵa tanö si mate andrö, ba Dekoa. Ba me mofanö sa''ae ira, ba so Yozafati, ba imane: Mifondrondrongo, ya''ami mado Yuda ba ya''ami banua Yeruzalema! Midöna-döna khö Lowalangimi, Yehowa, ba so wangorifi; midöna-döna ba zama''ele''ö andrö, khönia, ba mofozu khömi![7]', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 21, 'Ba mamagölö ia ba zato, ba ifataro zanunö khö Yehowa, sangehao, fangehao ni''amoni''ö, ena''ö manunö ira; wowaö-waö föna zi no mangaro andrö, ena''ö lamane: "Mi''andrö saoha gölö khö Yehowa, me no si lö aetu wa''ebua dödönia andrö!"[8]', '["MozII 14:13,14","MozII 14:31; Yes 28:16","Sin 106"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 22, 'Ba ha si''aikö labörögö wangehehegö ba fanuno, ba ifatörö zi tobini mege Yehowa, ba Ndraono Gamoni ba ba Ndraono Moabi ba ba mbanua ba hili Ze''ira andrö, sanuwö mado Yuda ena''ö.[9]', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 23, 'Ba tobali udu mbanua ba hili Ze''ira andrö Ndraono Gamoni, awö Ndraono Moabi, ba wangö''ötö tou ya''ira ba ba wangohori, ba me no lahori mbanua Ze''ira andrö, ba faoma lafakiko nawöra.[10]', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 24, 'Ba me larugi mboto hili mado Yuda, ba zi faoro tanö si mate andrö, ba me lafaigi niha sato andrö, ba hiza, ba no boto zi mate manö, tou ba danö; samösa lö soloi.', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 25, 'Ba lasaŵa ira Yozafati ba sabölö andrö khönia, ba wangai hadia zi so khöra mege, ahulua, ba hiza gurifö, wa''oya, ba hadia ia ni''ohera mege ba nukha ba gama-gama bö''ö sebua böli, ba lahalö, ha wa''oya, irege tebai sa''ae la''ohe. Tölu ngaluo wa''ara lahalö-halö, balazi wa''ebua gahulua andrö.', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 26, 'Ba aefa da''ö, ba mahemolu ö, ba owulo ira ba ndraso wanunö andrö. Ba da''ö sa''ae lasuno Yehowa; andrö wa labe''e töi ndraso andrö "Ndraso wanunö", irugi ma''ökhö andre.', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 27, 'Ba lafuli ira mado Yuda fefu ba banua Yeruzalema ba Yozafati, solohe ya''ira, ba wangawuli ba Yeruzalema, omuso sibai dödöra, noa sa i''omusoi''ö dödöra Yehowa, ba nemalira andrö.', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 28, 'Ba larugi Yeruzalema, osali Yehowa, wolau biola nitika, sebua ba side-ide, ba torofe.', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 29, 'Ba dozi amatöröŵa niha baero, ba ihawui fa''ata''u, khö Lowalangi, me larongo, wa no Yehowa zi fasöndra ba nemali Ndraono Gizeraeli.[11]', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 30, 'Ba samatörö nifatörönia Yozafati, lö hadia ia; no ahono manö zi tefasui ya''ia ibe''e Lowalanginia.[12]', '["Sin 48 ba 83","SamI 14:20","Nga''ötII 17:10","Faigi 15:15"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 31, 'Ba razo mado Yuda Yozafati; 35 fakhe ia, me tobali razo ia, ba 25 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Asuba, ono Zilehi.[13][14]', '["Ayati 31: Faigi 21:1; RazI 22:41–51","RazI 22:41","RazI 22:52–54","RazI 22:49"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 32, 'Ba itörö lala namania Asa, lö ihole''ö ia; somasi Yehowa ilau.', '["Ayati 31: Faigi 21:1; RazI 22:41–51","RazI 22:41","RazI 22:52–54","RazI 22:49"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 33, 'Ha hili-hili andrö zi lö muheta ba tenga na khö Lowalangi ndra tuara dödö niha sato.', '["Ayati 31: Faigi 21:1; RazI 22:41–51","RazI 22:41","RazI 22:52–54","RazI 22:49"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 34, 'Ba bö''önia hikaya Yozafati, he famobörö, ba he safuria andrö, ba no mutanö ba zura hikaya khö Yehu andrö, ono Hanani, si no mufadoro ba zura hikaya Ndraono Gizeraeli.', '["Ayati 31: Faigi 21:1; RazI 22:41–51","RazI 22:41","RazI 22:52–54","RazI 22:49"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 35, 'Ba ifaböbö ia khö Gahaseya, razo Ndraono Gizeraeli Yozafati, razo mado Yuda, ba no niha sebua horö da''ö.[15]', '["Ayati 31: Faigi 21:1; RazI 22:41–51","RazI 22:41","RazI 22:52–54","RazI 22:49"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 36, 'Ba ihalö awönia, ba wolau owo, soloyo ba Darisi; ba lalau nowo ba Geseono Geberi.[16]', '["Ayati 31: Faigi 21:1; RazI 22:41–51","RazI 22:41","RazI 22:52–54","RazI 22:49"]', NULL),
  (3475141, 'OT', 'Nga''ötö II', 20, 37, 'Ba mama''ele''ö Geliezeri, ono Dodawahu, banua Maresa, ba khö Yozafati, imane: Me no öfaböbö ndra''ugö khö Gahaseya, ba irasa nilaumö andrö Yehowa! Ba aboto nowo andrö, tebai larugi Darisi.', '["Ayati 31: Faigi 21:1; RazI 22:41–51","RazI 22:41","RazI 22:52–54","RazI 22:49"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 1, 'Ba mate Yozafati itörö lala ndra amania, ba lako''o ia ba ngai ndra amania, ba mbanua Dawido. Ba fangalinia razo, ba ononia Yehoramo.[1][2]', '["Faigi göi RazII 8:16–22","RazII 8:16 b.t.","Sanguhuk 9:5","SamII 7:12,16; RazI 11:36; Sin 132:17"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 2, 'Ba so nakhi da''ö, ono Yozafati: Asaria ba Yehieli ba Sekhariahu ba Asariahu ba Mikhaeli, ba Sefatiahu; oi ono Yozafati razo Ndraono Gizeraeli da''ö, ono matua.', '["Faigi göi RazII 8:16–22","RazII 8:16 b.t.","Sanguhuk 9:5","SamII 7:12,16; RazI 11:36; Sin 132:17"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 3, 'Ba no ebua mbuala nibe''e namara khöra, firö ba ana''a ba gama-gama ba banua saro, ba mado Yuda. Ba fa''arazo, ba khö Yehoramo itehe, me no si a''a da''ö.', '["Faigi göi RazII 8:16–22","RazII 8:16 b.t.","Sanguhuk 9:5","SamII 7:12,16; RazI 11:36; Sin 132:17"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 4, 'Ba me no tobali razo Yehoramo ba gamatöröŵa namania, ba me no i''aro''ö ia, ba ifabunu''ö nakhinia andrö fefu, fabaya satua Ndraono Gizeraeli ösa.[3]', '["Faigi göi RazII 8:16–22","RazII 8:16 b.t.","Sanguhuk 9:5","SamII 7:12,16; RazI 11:36; Sin 132:17"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 5, 'Tölu ngafulu a rua fakhe Yehoramo, me tobali razo ia, ba meŵalu fakhe razo ia ba Yeruzalema.', '["Faigi göi RazII 8:16–22","RazII 8:16 b.t.","Sanguhuk 9:5","SamII 7:12,16; RazI 11:36; Sin 132:17"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 6, 'Ba itörö lala razo Ndraono Gizeraeli, lala zi sawu ndra Ahabi, noa sa ono Gahabi wo''omonia. Ba si fatuwu khö Yehowa ilau.', '["Faigi göi RazII 8:16–22","RazII 8:16 b.t.","Sanguhuk 9:5","SamII 7:12,16; RazI 11:36; Sin 132:17"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 7, 'Ba lö edöna Yehowa, ifakiko nga''ötö Dawido, börö wawu''usa li andrö, me no fawu''u li ia khö Dawido; dali nifabu''unia, wa lö edöna ibulö''ö wandru khö Dawido ba ba nga''ötönia.[4]', '["Faigi göi RazII 8:16–22","RazII 8:16 b.t.","Sanguhuk 9:5","SamII 7:12,16; RazI 11:36; Sin 132:17"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 8, 'Ba götönia aheta Ndraono Gedomo barö mbawa mado Yuda, ba lafataro khöra razo.', '[]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 9, 'Ba isaŵa ira miyefo Yehoramo, awö gumandra khönia, awö guretania fefu. Ba maoso ia ba zi bongi, ba ilau ba Ndraono Gedomo andrö, si no mama''u''u ya''ia, ba ba zolohe kureta khöra.', '[]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 10, 'Ba aheta barö mbawa Ndraono Gizeraeli Ndraono Gedomo, irugi ma''ökhö andre. Ba me luo da''ö, ba aheta göi Libena, barö mbawa Yehoramo, me no i''erogö Yehowa, Lowalangi ndra tuania.', '[]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 11, 'Ba ifazökhi göi hili-hili ba mbanua mado Yuda misa, ifowöhö mbanua Yeruzalema, ba wame''e adu, ba fabali [khö Yehowa] mado Yuda ibe''e.', '[]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 12, 'Ba ifa''ohe''ö zura khönia Eliya sama''ele''ö, imane: Da''ö niŵa''ö Yehowa, Lowalangi duau Dawido: Me no lö nitöröu lala namau Yozafati ba he lala Asa, razo mado Yuda,', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 13, 'me no ö''o''ö mbua-bua razo Ndraono Gizeraeli ba me no öfowöhö ba wame''e adu mado Yuda, fabaya banua Yeruzalema, si mane si sawu ndra Ahabi, si no samowöhö ba nadu göi, ba me no öfabunu''ö göi ndra akhiu, nga''ötö namau, si sökhi moroi khöu, ba hiza,', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 14, 'ba ihare''ö khömi dania wamakao sebua, ba mbanuau ba ba ndraonou ba ba ngambatöu ba ba zi so khöu, fefu.', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 15, 'Ba ya''ugö, ba si göna fökhö sabe''e dania, fökhö talu, ba mato mendrua fakhe dania, ba adudu mbetu''amö!', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 16, 'Ba ifarou udu Yehoramo Ndrawa Wilisiti Yehowa, awö Ndrawa Ara andrö, ba ngai Ndrawa Gaitiofia,', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 17, 'ba tobali möi ira musuwö mado Yuda, ba atu''a ira ba mbanua, ba lahalö fefu hadia ia zi so ba gödo razo, fabaya iraononia, awö ngambatönia; la''oloi''ö ahulua; lö si tosai ononia, ha Yoakhasi, ononia si akhi.[5]', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 18, 'Ba noa da''ö fefu, ba ibözi ia Yehowa fökhö mbetu''a si lö dalu-dalu.', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 19, 'Ba moröfi, ba me arakha alua mendrua fakhe, ba adudu mbetu''ania, ba wökhönia andrö, ba mate ia, fa''amate safökhö sibai. Ba lö latunu zamohua khönia banuania, si mane khö ndra amania mege.[6]', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475142, 'OT', 'Nga''ötö II', 21, 20, 'Tölu ngafulu a rua fakhe ia, me tobali razo ia, ba meŵalu fakhe razo ia ba Yeruzalema. Ba alele ia lö somasi na mangawuli ia ena''ö. Ba ba mbanua Dawido lako''o ia, ba tenga sa ba lewatö razo.[7]', '["RazII 8:25","Faigi 16:14","Ayati 5; Faigi 24:25"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 1, 'Ba lafataro fangalinia razo nononia si akhi,[1] Ahaseyahu, banua Yeruzalema, me no labunu zi a''a fefu sanuwö andrö, Dawa Ara, me larugi golombaseŵa no. Ba tobali razo Gahaseyahu andrö, ono Yehoramo, razo mado Yuda.[2]', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 2, 'Dua wulu a rua fakhe Gahaseyahu, me tobali razo ia, ba ha döfi razo ia ba Yeruzalema. Ba töi ninania, ba Atalia, ma''uwu Omeri andrö, razo Ndraono Gizeraeli.', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 3, 'Ba itörö lala zi sawu ndra Ahabi, me no inania andrö zamobawa lala khönia, ba wanao horö.', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 4, 'Ba tobali si fatuwu khö Yehowa ilau, si mane si sawu ndra Ahabi; da''ö sa zamobawa lala khönia, me no mate namania, ba tobali famakikonia.', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 5, 'Lira göi ifondrondrongo, ba wefao khö Yoramo, ono Gahabi, razo Ndraono Gizeraeli, ba wanuwö Hazaeli andrö, razo Ndrawa Garamo, ba Ramoti, ba danö Gileadi; ba mesokho Yoramo labe''e Dawa Garamo.', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 6, 'Ba mangawuli ia, isaŵa Yezere''eli, ba wamadöhö sokhonia andrö, si tenga ha sambua, sesokho ia ba Rama, me fasuwö ia khö Hazaeli andrö, razo Ndrawa Garamo. Ba Ahaseyahu, ono Yehoramo razo mado Yuda, ba no möi mitou mamaigi Yoramo, ono Gahabi, ba Yezere''eli, me no mofökhö.', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 7, 'Ba tobali famunu Gahaseyahu, nifatörö Lowalangi, we''amöinia khö Yoramo. Me no irugi, ba fao ia khö Yoramo we''amöi khö Yehu andrö, nifabayoini''ö Yehowa, ena''ö ihori zi sawu ndra Ahabi.[3]', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 8, 'Ba me ifatörö huku andrö Yehu, ba zi sawu ndra Ahabi, ba falukha ia zatua mado Yuda ba iraono dalifusö Gahaseyahu, enoni Gahaseyahu, ba ifabunu''ö ira.[4]', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 9, 'Ba ifa''alui''ö göi Gahaseyahu, ba lara''u ia, me no ibini''ö ia ba Zamaria. Ba la''ohe khö Yehu, ba labunu. Ba lako''o ia, lamane sa: no ono Yozafati andrö, si lö aefa-aefa mege khö Yehowa, soroi si''aikö ba dödö! Ba samösa lö''ö sa''ae si sawu ndra Ahaseyahu, si tola tefataro razo.[5]', '["Ayati 1–6: RazII 8:25–29","Faigi 21:17","RazI 19:16; RazII 9:2,6","RazII 10:12–14","RazII 9:27–29"]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 10, 'Ba me irongo Atalia,[6] ina Gahaseyahu, no mate nononia, ba itema ifabunu''ö fefu nga''ötö razo ba mado Yuda.[7]', '["Ayati 10–12: RazII 11:1–3","RazII 11:1 b.t."]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475143, 'OT', 'Nga''ötö II', 22, 11, 'Ba maoso Yozabata, ono razo, alawe, ihalö Yoasi, ono Gahaseyahu, ba hunö nono razo bunusö andrö, ibini''ö, i''ohe si bakha ba wöröma, awö babunia. Tobali ibini''ö [Yoasi] Yozabata, ono razo Yehoramo, fo''omo Yoyada ere — me talifusö Gahaseyahu ia — ibini''ö khö Gatalia, fa böi ibunu.', '["Ayati 10–12: RazII 11:1–3","RazII 11:1 b.t."]', NULL),
  (3475143, 'OT', 'Nga''ötö II', 22, 12, 'Ba khöra tobini ia, ba gosali Lowalangi, meönö fakhe wa''ara, götö wa''asalaŵa Gatalia ba danö.', '["Ayati 10–12: RazII 11:1–3","RazII 11:1 b.t."]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 1, 'Ba me no alua me''önö fakhe,[1] ba maoso Yoyada, i''ohe awönia gumandra zi otu andrö — Asaria, ono Yerohama, ba Sima''eli, ono Yohanano, ba Asariahu, ono Gobedi, ba Ma''aseya, ono Gadaya, ba Elisafati, ono Zikhiri — si fa''awö khönia.', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 2, 'Da''ö zanöröi banua mado Yuda, ba la''owuloi Nono Lewi, moroi ba mbanua mado Yuda fefu, awöhögö ngafu Ndraono Gizeraeli, ba we''amöi ba Yeruzalema.', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 3, 'Ba fawu''u li khö razo zato andrö fefu, ba gosali Lowalangi. Ba imane khöra [Yoyada]: Ono razo andrö nibe''e razo, dali nifabu''u Yehowa ba khö nga''ötö Dawido andrö.[2]', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 4, 'Ba mimane wolau: Si saraö ya''ami — ere ba ono Lewi — nifataro na luo sabato, ba nibe''e sanaro ba mbawandruhö tou,', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 5, 'ba si saraö, ba ba gödo razo tumaro, ba si saraö zui, ba ba mbawandruhö Yezodi, ba niha sato, ba ba golayama gosali Yehowa.', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 6, 'Ba ba gosali Yehowa, ba lö tola möi niha, ha niha ia, ha ere andrö ba Ono Lewi, sangai-ngai halöŵö. Ya''ira zi tola möi, me no ni''amoni''ö ira. Ba niha sato fefu, ba la''o''ö nifakhoi Yehowa.[3]', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 7, 'Ba labe''e ba hunöra bakha razo Ono Lewi andrö; dozi ira, ba fangöna ba dangara, ba sanöndragö ya''ia ba gosali, ba nibunu. Ba mi''iagö awö razo, na möi ia tou ba na ifuli ia yomo.', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 8, 'Ba la''o''ö Ono Lewi niŵa''ö Yoyada khöra, i''ohe nawönia zamösana, he saheta sanaro na luo sabato, ba he sawena möi sanaro; lö''ö sa ni''efa''ö Yoyada ere ngenolira andrö.', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 9, 'Ba Yoyada ere, ba ibe''e ba gumandra zi otu andrö doho andrö ba baluse, khö razo Dawido mege, si so ba gosali Lowalangi.', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 10, 'Ba ifataro samasui razo niha sato fefu, — oi dozi fangöna ba danga, i''otarai ngai gosali tanö raya, numalö ba ngainia tanö yöu, irugi naha wame''e sumange, ba mangawuli ba gosali.', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 11, 'Ba la''ohe baero nono razo andrö, lafanaembu ia, ba labe''e khönia zura goroisa, ba lafataro razo ia; ba labayoini ia Yoyada ba ononia, ba mu''ao ira, lamane: Ya ahowu razo!', '["Faigi göi RazII 11:4–20","Faigi 21:7","Nga''öt. I, 23:28"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 12, 'Ba me irongo we''ao zato Atalia, fe''ao zi hurufai ya''ira, samahowu''ö razo, ba isaŵa niha sato ba gosali.', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 13, 'Ba i''ila sa''ae razo, ba zinga mbawandruhö, ba nahania, awö gumandra andrö ba solau torofe ba ngai razo, awö niha ba danö fefu, si no omuso tödö ba solau-lau torofe, ba sanunö andrö, solau hadia ia nifoli, wame''e tandra ba wanunö. Ba itika nukhania Atalia ba imane: Folaŵa! Folaŵa!', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 14, 'Ba humede Yoyada ere ba gumandra zi otu andrö, solohe sabölö, ba imane khöra: Mi''ohe baero ia ba gotalua ngenoli, ba solo''ö ya''ia, ba nibunu si öli! Noa sa imane ere: Böi mibunu ia ba gosali Yehowa bakha.', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 15, 'Ba lara''u ia, ba me no larugi mbawandruhö kudo ba gödo razo, ba labunu ia ba da''ö.', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 16, 'Ba fawu''u li ira Yoyada niha sato, awö razo, wa edöna ira banua Yehowa ira sa''ae.[4]', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 17, 'Ba lasaŵa gosali Mba''ali sato fefu ba ladudugö; naha wame''e sumange khönia ba famaedonia andrö, ba lafufu; ba labunu Matana andrö, ere khö Mba''ali, föna naha wame''e sumange.[5]', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 18, 'Aefa da''ö, ba ifataro zanaro ba gosali Yehowa Yoyada, ere ono Lewi andrö, ni''angenoligö Dawido no [ba halöŵö] ba gosali Yehowa, ena''ö labe''e-be''e zumange nitunu andrö khö Yehowa, dali goroisa Moze, si fao fa''owua-wua dödö ba fanunö, si mane nifakhoi Dawido.[6]', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 19, 'Ba ifataro ba zinga mbawandruhö gosali Yehowa zanaro ba mbawandruhö, fa böi möi bakha zi so fa''ara''iö hadia ia.[7]', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 20, 'Ba i''ohe gumandra zi otu ba satua ba samatörö niha sato, awö niha ba danö fefu, ba ifasao mitou razo, la''otarai gosali Yehowa. Ba me no latörö mbawandruhö tanö yaŵa andrö, me no tohare ira ba gödo, ba lafedadao ba dadaoma zalaŵa razo.', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475144, 'OT', 'Nga''ötö II', 23, 21, 'Ba oi omuso dödö niha sato, ba sahono manö mbanua. Ba Atalia, ba labunu si''öli.', '["Faigi 15:12","MozV 13:9","Moz. III, 1:3; Faigi 29:30","MozIV 3:10"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 1, 'Ha mewitu fakhe wa''ebua Yehoasi,[1] me tobali razo ia, ba 40 fakhe razo ia ba Yeruzalema; ba töi ninania, ba Sibia, banua Mbereseba.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 2, 'Ba somasi Yehowa ilau Yehoasi, fatua lö si mate Yoyada ere andrö.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 3, 'Yoyada zamangowalu ya''ia, dombua ihalö khönia ira alawe, ba mo''ono ia, ono matua ba ono alawe.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 4, 'Ba iŵa''ö tödönia Yehoasi, ihaogö gosali Yehowa.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 5, 'Ba ifalukha''ö gere ba Ono Lewi, ba ibe''e li khöra, imane: Mitöröi mbanua mado Yuda, ba miŵa''ö mbalazo ba Ndraono Gizeraeli fefu, ena''ö ero röfi ta''azökhi gosali Lowalangimi; ba mita''i-ta''i wolau da''ö! Ba lö la''aliogö Ono Lewi andrö.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 6, 'Ba ifakaoni''ö Yoyada högö [gere] razo, ba imane khönia: Hana wa lö ibe''e dödöu wanguma''ö ba Nono Lewi, ena''ö la''ozaragö ba mado Yuda ba ba mbanua Yeruzalema mbobotolö andrö, niŵa''ö Moze, enoni Yehowa, ömö Ndraono Gizeraeli sato, balazo nose goroisa.[2]', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 7, 'Me no adudu ösa ba gosali Lowalangi labe''e Atalia, ira alawe sebua horö andrö, ba iraononia, ba no ahori manö lafake ba Mba''ali andrö game''ela andrö, nibe''e ba gosali Yehowa, ni''amoni''ö.[3]', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 8, 'Ba lafazökhi kotakota, niŵa''ö razo, ba labe''e ba zinga mbawandruhö gosali Yehowa.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 9, 'Ba lafarongogö ba mado Yuda, ba ba mbanua Yeruzalema, ndramube''e khö Yehowa mbobotolö andrö niŵa''ö Moze, enoni Lowalangi, ba Ndraono Gizeraeli, ba danö si mate.[4]', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 10, 'Ba omuso dödö zatua, awö niha sato fefu, ba la''ohe ba labe''e ba kotakota andrö, dozi ira.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 11, 'Ba ero na ifa''ohe''ö ba zamaigi nifataro razo kotakota andrö, ba Nono Lewi, ba na la''ila, oya bakha ana''a, ba so durutuli razo, awö nifatenge gere sebua, ba lahalö nösi kotakota ba lafuli ia ba nahania. Ba la''erogö maökhö zi manö ba ebua la''ozaragö ana''a.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 12, 'Ba labe''e ba mandru duka andrö, ba halöŵö ba gosali Yehowa, razo ba Yoyada, ba da''ö dania zangoni sanoto kara ba sotomo, ba wanga''azökhi osali Yehowa, ba he siambu si''öli ba töla, ba wangehao osali Yehowa.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 13, 'Ba mohalö-halöŵö duka andrö, ba tedou wanga''azökhi andrö labe''e, ba tobali lafuli lafazökhi gosali Lowalangi, dali nifakhoi andrö, lafuli lahaogö.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 14, 'Ba me no awai khöra da''ö, ba la''ohe khö razo ba khö Yoyada gana''a andrö, si tosai, ba labali''ö fakake ba gosali Yehowa — fakake ba halöŵö andrö ba ba wame''e sumange, figa ba gama-gama bö''ö, ana''a ba firö. Ba lö lafamalö-malö wame''e-me''e sumange nitunu ba gosali Yehowa, götö wa''anau noso Yoyada.', '["Faigi göi RazII 12","MozII 30:12,13","Faigi 22:3,4","Ayati 6"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 15, 'Ba atua Yoyada ba aföli wa''auri ba mate ia, 130 fakhe ia, me mate ia.', '["Sanguhuk 6:34; Nga''ötII 15:2","Mat 23:35; Heb 11:27"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 16, 'Ba ba mbanua Dawido, ba ngai razo lako''o ia, me no si sökhi nilaunia ba Ndraono Gizeraeli, ba he khö Lowalangi ba ba gosalinia.', '["Sanguhuk 6:34; Nga''ötII 15:2","Mat 23:35; Heb 11:27"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 17, 'Ba me no mate Yoyada, ba la''ondrasi razo satua mado Yuda, mangalulu ira khönia; ba ifondrondrongo khöra razo.', '["Sanguhuk 6:34; Nga''ötII 15:2","Mat 23:35; Heb 11:27"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 18, 'Ba la''erogö gosali Yehowa, osali Lowalangi ndra tuara, ba lafosumange Gasera andrö ba adu nifofu. Ba göna fönu sabölö-bölö [fönu Lowalangi] mado Yuda ba banua Yeruzalema, börö lalöra andrö.', '["Sanguhuk 6:34; Nga''ötII 15:2","Mat 23:35; Heb 11:27"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 19, 'Ba ifatenge khöra zama''ele''ö, solohe mangawuli ya''ira khö Yehowa ena''ö. Ba moroi si''aikö ba dödöra lafarou ira ba lö lafondrondrongo.', '["Sanguhuk 6:34; Nga''ötII 15:2","Mat 23:35; Heb 11:27"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 20, 'Ba ira''u Zakharia, ono Yoyada ere, Eheha Lowalangi, ba möi ia ba niha sato, ba imane khöra: Da''ö niŵa''ö Lowalangi: Hana wa misawö goroisa Yehowa? andrö wa si lö fozu wolaumi. Me no mi''erogö Yehowa, andrö wa no i''erogö göi ami.[5]', '["Sanguhuk 6:34; Nga''ötII 15:2","Mat 23:35; Heb 11:27"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 21, 'Ba mamagölö ira ba khönia andrö, ba labunu ia, latebu kara, ba golayama gosali Yehowa, niŵa''ö razo khöra.[6]', '["Sanguhuk 6:34; Nga''ötII 15:2","Mat 23:35; Heb 11:27"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 22, 'Lö''ö sa''ae itörö tödö razo Yehoasi wa''ahakhö dödö nama Zakharia Yoyada khönia, ifabunu''ö nononia. Ba imane da''ö, me mate ia: Yehowa zangila ba ilau mbalö dania!', '["Sanguhuk 6:34; Nga''ötII 15:2","Mat 23:35; Heb 11:27"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 23, 'Ba me no alua ndröfi andrö, ba so moroi si yaŵa zabölö Ndrawa Garamo, ba wanuwö Yehoasi. Ba me no larugi danö mado Yuda ba banua Yeruzalema, ba lahori fefu zatua mbanua ba mbanuara; ba hadia ia gahulua fefu, sahulu ira ba khöra, ba lafa''ohe''ö khö razo ba Ndramaseko.', '["Faigi 21:20"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 24, 'Ba he ŵa''ae lö ato sibai zabölö Ndrawa Garamo, ba ibe''e zui ba dangara Yehowa zato sibai [Iraono Gizeraeli], me no la''erogö Yehowa, Lowalangi ndra tuara, ba tobali lafatörö khö Yehoasi huku andrö khö Lowalangi.', '["Faigi 21:20"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 25, 'Ba me laböhöli ia — mofökhö sibai ia, me mofanö ira —, ba mamagölö genoninia, ba khönia, börö wamununia ono Yoyada ere andrö, ba labunu ia ba gasonia tou. Ba mate ia, ba ba mbanua Dawido lako''o ia, ba tenga sa ba lewatö razo.[7]', '["Faigi 21:20"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 26, 'Ba da''e zamagölö mege, ba wamunu ya''ia: Sabada, ono Ndraono Gamoni andrö, ira alawe, Simeata ba Yosabada, ono Zimeriti, Iraono Moabi ira alawe.', '["Faigi 21:20"]', NULL),
  (3475145, 'OT', 'Nga''ötö II', 24, 27, 'Ba ononia andrö, ba ha wa''ebua gömönia labe''e [Dawa Garamo] ba fanga''azökhi osali andrö, ba hiza, ba no mutanö ba zura hikaya razo. Ba fangalinia razo, ba ononia Amasia.', '["Faigi 21:20"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 1, 'Dua wulu a lima fakhe Gamasia,[1] me tobali razo ia, ba 29 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Yoadana, banua Yeruzalema.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 2, 'Ba somasi Yehowa ilau, ba lö a''oi dödönia.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 3, 'Ba me no aro wa''arazonia ba ifabunu''ö genoninia andrö, samunu amania razo mege.[2]', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 4, 'Ba iraonora, ba lö ifabunu''ö, i''o''ö nifakhoi Yehowa, si so ba zura goroisa andrö khö Moze, me imane: Böi mate nama, fabaya iraono, ba böi mate Ndraono, fabaya ira ama, ha ba horönia labunu zamösana.[3]', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 5, 'Ba i''owuloi mado Yuda Amasia, iföfö''ö ira, sawu-sawu, dali gumandra ngahönö andrö ba kumandra ngaotu, ba mado Yuda fefu ba ba mado Mbeniyami. Ba i''ofaya ira, i''otarai zi 20 fakhe fa''ebua ba si a''a moroi andrö, ba hiza, ba no 300.000 nitutuyu, sabölö, solohe toho ba baluse.[4]', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 6, 'Ba 100.000 na i''oni Iraono Gizeraeli sabölö, 22.050 balaki ba rufia ibe''e ana''a.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 7, 'Ba so zi möi khönia enoni Lowalangi, imane khönia: He razo! Böi ohe awöu zabölö Ndraono Gizeraeli, lö''ö sa itolo Ndraono Gizeraeli Yehowa, mado Geferayi andrö fefu.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 8, 'Ae''e manö, ha ya''ugö, ba abe''e''ö dödöu ba wasuwöta andrö; ma te''ala ndra''ugö ba nudumö andrö ibe''e Lowalangi. So sa wa''abölö khö Lowalangi, he ba wanolo, ba he ba wangalani.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 9, 'Ba imane Amasia khö genoni Lowalangi andrö: Ba he lawisa zi 22.050 balaki andrö, nibe''egu ba zabölö Ndraono Gizeraeli andrö? Ba imane khönia enoni Lowalangi andrö: Sebua moroi ba da''ö i''ila ibe''e khöu Yehowa!', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 10, 'Awena i''oniagö Amasia zabölö andrö, si no mangondrasi ya''ia, mado Geferayi, ena''ö lafuli ira. Ba mofönu sibai ira ba mado Yuda, ba lafuli ira, abao sibai dödöra.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 11, 'Ba i''abe''e''ö dödönia Amasia, i''ohe mbanuania, lasaŵa ndraso nasio andrö, ba lalau ba mbanua Ze''ira andrö, 1.000 zi mate.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 12, 'Ba 10.000 lara''u mado Yuda, ba la''ohe ba zuzu gara, ba hili, ba latuli''ö si tou moroi ba da''ö, ba ahori arasa.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 13, 'Ba sabölö no mege, nifofanö Gamasia, fa böi fao ira ba wasuwöta andrö, ba lahawui mbanua mado Yuda, i''otarai Zamaria, irugi Mbeti Horona; 3.000 labunu niha, ba ebua sibai gahulua la''oloi''ö.', '["Faigi göi RazII 14:1–22","Faigi 24:25","MozV 24:16","MozIV 1:3"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 14, 'Ba me mangawuli Gamasia, me no i''alani Ndraono Gedomo, ba i''ohe nadu mbanua Ze''ira andrö, ba ifedadao adunia, ba ba da''ö mangalungalulu ia ba manunununu kumöyö.', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 15, 'Ba mofönu Yehowa khö Gamasia, ba ifatenge khönia zama''ele''ö. Ba imane khönia da''ö: Hana wa ö''olembai Lowalangi niha andrö, si tebai mangefa''ö ba dangau mege banuara andrö?', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 16, 'Ba me imanö wehede khö razo, ba imane khönia razo: Hadia no mafataro ndra''ugö samobawa lala khö razo? Bato, fa böi labözi''ö! Ba ibato sama''ele''ö andrö, imane: Aboto sa''ae ba dödögu, wa no ihonogöi Lowalangi wamakiko ya''ugö, me no ömanö wolau ba me lö öfondrondrongo niŵa''ögu khöu!', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 17, 'Ba me no mamagölö [ba nawönia] Gamasia, razo mado Yuda, ba ifatenge khö Yoasi, ono Yoahasi ono Yehu, razo Ndraono Gizeraeli, imane khönia: Talabu talau fatandra fa''abölö!', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 18, 'Ba ifafuli''ö li khö Gamasia, razo mado Yuda, Yoasi, razo Ndraono Gizeraeli, imane: No ifatenge ba döla geresi, ba hili Libano, sa''a-sa''a mao ba hili Libano, imane khönia: Datalau fambambatö! Ba latörö za''a-sa''a mao andrö utu ndru''u ba hili Libano, lahundra-hundra.[5]', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 19, 'ömane dödöu: Noa sa u''alani Ndraono Gedomo andrö! Ba ifowöhö''ö tödöu ba wayaŵasa. Iagö manö khömi! Hana wa ö''arö wamunu, ena''ö te''ala ndra''ugö, fabaya mado Yuda?', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 20, 'Ba lö ifondrondrongo Amasia; noa sa nifatörö Lowalangi da''ö, ba wame''e ba danga nudura ya''ira, me no la''olembai Lowalangi Ndraono Gedomo.', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 21, 'Ba so Yoasi, razo Ndraono Gizeraeli, ba fatandra fa''abölö ira Gamasia, razo mado Yuda, ba zinga Mbetiseme, banua mado Yuda.', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 22, 'Ba te''ala mado Yuda labe''e Iraono Gizeraeli, moloi ira, isaŵa khöra zamösana.', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 23, 'Ba ira''u Gamasia, ono Yoasi ono Yehoahasi razo mado Yuda, Yoasi, razo Ndraono Gizeraeli, ba Mbetiseme, ba i''ohe ba Yeruzalema. Ba idudugö göli Yeruzalema, öli kara, i''otarai mbawa göli Geferayi, irugi mbawa göli ba watalinga, 400 hela wa''anau.', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 24, 'Ba ahori ihalö gana''a ba firö ba fakake ba gosali Lowalangi, khö Gobedi-Edomo, fabaya girö-girö ba gödo razo, awö niha, we''e-we''e dödö, ba ifuli ia ba Zamaria.', '["Sanguhuk 9:8,14"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 25, 'Ba mewelelima fakhe tö na noso Gamasia, ono Yoasi, razo mado Yuda, me no mate Yoasi andrö, ono Yoahasi, salaŵa Ndraono Gizeraeli.', '["Faigi 24:25"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 26, 'Ba bö''önia hikaya Gamasia, he famobörö mege, ba he safuria andrö, ba noa sa mutanö ba zura razo mado Yuda ba ba zura razo Ndraono Gizeraeli.', '["Faigi 24:25"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 27, 'Ba i''otarai luo me i''erogö Yehowa Amasia, ba so zamagölö, banua Yeruzalema, ba wamunu ya''ia. Ba moloi ia, isaŵa Lakhisi; ba lafatenge zolo''ö ya''ia ba Lakhisi, samunu ya''ia ba da''ö.[6]', '["Faigi 24:25"]', NULL),
  (3475146, 'OT', 'Nga''ötö II', 25, 28, 'Ba labe''e ba gureta, ba ba Yeruzalema, ba mbanua Dawido, lako''o ia ba ngai ndra amania.', '["Faigi 24:25"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 1, 'Ba lahalö Usia andrö niha sato ba danö,[1] ba lafataro razo ia, fangali namania Amasia, he ŵa''ae ha meweleönö fakhe na wa''ebuania.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 2, 'Da''ö zangaro''ö Eloto, ifuli ihalö banua mado Yuda, me no mate razo [amania].', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 3, 'Meweleönö fakhe wa''ebua Usia andrö, me tobali razo ia, ba 52 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Yekholia, banua Yeruzalema.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 4, 'Ba somasi Yehowa ilau, i''ohia''ö sibai nilau namania Amasia mege.[2]', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 5, 'I''alu-alui zi lö aefa ia khö Lowalangi, götö wa''anau noso Zakharia andrö, samahaö ba wangata''ufi Lowalangi; ba fatua lö iböhöli Yehowa, ba mofozu nilaunia ibe''e Lowalangi.[3]', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 6, 'Möi ia musuwö Ndrawa Wilisiti, idudugö göli Gata ba öli Yabene ba öli Gasoto ba itaru''ö mbanua ba ngai Gasoto ba heza na ba danö Ndrawa Wilisiti.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 7, 'Ba itolo ia Lowalangi ba Ndrawa Wilisiti ba ba Ndrawa Ara andrö, ba Guri-Mba''ali ba ba mbanua Moini andrö.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 8, 'Ba Iraono Gamoni göi, ba mame''e beo khö Usia, ba irugi danö Miserayi, ba terongo duriania, me no sabölö sibai ia.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 9, 'Ba ilau malige Usia, ba Yeruzalema, ba mbawa göli ba watalinga ba ba mbawa göli ba ndraso ba ba zanalinga si''u, ba i''a''aro''ö.[4]', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 10, 'Ba ilau göi malige ba danö si mate, ba oya ifakhao''ö ba''a. Me no oya sibai gurifö khönia he ba ndraso, ba he ba zalo''o, ba sonowi khönia ba tuka kabu nagu, he ba hili, ba he ba danö nowi ba zalo''o; me no somasi fangahalö ia.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 11, 'Ba ato khö Usia sabölö, ato sibai na möi fasuwö; ha wa''ato ni''ofaya durutuli andrö, Yeieli, ba kumandru andrö, Ma''aseya, barö mbawa Hanania, kumandru sebua khö razo.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 12, 'Fa''ato högö ngafu andrö, niha sabölö, ba no 2.600.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 13, 'Da''ö zolohe sato, 307.500, sabölö sibai ba wasuwöta, ba wanolo razo ba nemali.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 14, 'Khöra fefu ifaigi wangöna Usia: baluse ba toho ba tetenaulu ba öröba ba kara riboribo.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 15, 'Ba ifafazökhi''ö na nekhe-nekhe fana ba Yeruzalema, nibe''e ba malige andrö, ba ba watalinga göli; ba wamazaumba ono wana ba kara sebua. Ba aröu misa humöngö duriania, me no sahöli-höli dödöda wanolo [Yehowa] ya''ia, irege sabölö sibai ia.', '["Faigi göi RazII 14:21.22; 15:1–7","Faigi 25:2","RazII 12:2","Neh 3:19"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 16, 'Ba me no sabölö sa''ae ia, ba fayaŵa dödönia, famakiko, ba mosala ia khö Lowalanginia Yehowa; möi ia ba gosali Yehowa, ba wanunu kumöyö ba naha wanunu.[5]', '["Faigi 25:19","MozIV 18:7","MozIV 12:10","MozIV 5:2","Yes 1:1; 6:1"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 17, 'Ba la''o''ö ia Asaria ere andrö, awö gere bö''ö, 80, ere Yehowa, sadölö tödö.', '["Faigi 25:19","MozIV 18:7","MozIV 12:10","MozIV 5:2","Yes 1:1; 6:1"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 18, 'Latenaŵa razo Usia, lamane khönia: Tenga halöŵöu wanunu kumöyö khö Yehowa, ya''ugö Usia, halöŵö gere nga''ötö Ga''aroni da''ö, ere si no mu''amoni''ö ba wanunu kumöyö. Heta''ö ba ni''amoni''ö andre, no mosala ndra''ugö; tenga fangebua döimö khö Yehowa, Lowalangi![6]', '["Faigi 25:19","MozIV 18:7","MozIV 12:10","MozIV 5:2","Yes 1:1; 6:1"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 19, 'Ba mofönu Usia, naha gumöyö ba dangania, ba wanunu. Ba barö wofönunia ba gere andrö, ba tumbu ba gangangonia mbou auri, ba zanehe gere andrö, ba gosali Yehowa, ba ngai naha wanunu kumöyö.[7]', '["Faigi 25:19","MozIV 18:7","MozIV 12:10","MozIV 5:2","Yes 1:1; 6:1"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 20, 'Ba me lanehegö ia Asaria, ere sebua ba ere andrö fefu, ba hiza, ba no mobou auri ia ba gangango. Ba lafangaösö ia, lafofanö, ba ya''ia göi, ba aösö we''amöi baero, me no ibözi ia Yehowa.', '["Faigi 25:19","MozIV 18:7","MozIV 12:10","MozIV 5:2","Yes 1:1; 6:1"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 21, 'Ba sobou auri razo Usia, irugi mate ia; ba yomo so ia si no tonia, sobou auri; lö''ö sa tola möi ia ba gosali Yehowa. Ba satua baomo ba gödo, razo, ba ononia Yotamo, ya''ia göi zamatunö huhuo niha ba danö.[8]', '["Faigi 25:19","MozIV 18:7","MozIV 12:10","MozIV 5:2","Yes 1:1; 6:1"]', NULL),
  (3475147, 'OT', 'Nga''ötö II', 26, 22, 'Ba bö''önia hikaya Usia, he famobörö, ba he safuria andrö, ba no Yesaya sama''ele''ö, ono Gamosi, zanura.[9]', '["Faigi 25:19","MozIV 18:7","MozIV 12:10","MozIV 5:2","Yes 1:1; 6:1"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475147, 'OT', 'Nga''ötö II', 26, 23, 'Ba mate Usia, itörö lala ndra amania, ba ba ngai ndra amania lako''o ia, ba mbenua, ba ngai lewatö razo; lamane sa: Sobou auri! Ba fangalinia razo, ba ononia Yotamo.', '["Faigi 25:19","MozIV 18:7","MozIV 12:10","MozIV 5:2","Yes 1:1; 6:1"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 1, 'Dua wulu a lima fakhe Yotamo,[1] me tobali razo ia, ba 16 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Yerusa, ono Zadoki.', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 2, 'Ba somasi Yehowa ilau, i''ohi''a''ö sibai nilau namania Usia mege, ha fa lö möi ba gosali. Ba sato, ba lalau-lau na zi lö sökhi.[2]', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 3, 'Ya''ia zolau bawandruhö andrö ba gosali Yehowa, tanö si yaŵa; ba lö''ö göi aetu wohalöŵö ba göli Gofeli andrö.[3]', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 4, 'Ba itaru''ö na göi mbanua ba hili mado Yuda misa, ba ba gatua misa, ba ilau hati ba malige.', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 5, 'Ba fasuwö göi ia khö razo Ndraono Gamoni, ba te''ala da''ö ibe''e. Ba ifo''ömö Ndraono Gamoni, ba ndröfi andrö: 22.050 balaki ba rufia (firö) ba 20.000 ngaso''e gandru ba 20.000 ngaso''e ze''iri; ba si manö göi labe''e Iraono Gamoni ba ndröfi dania ba ba ndröfi fanete da''ö.', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 6, 'Ba tedou manö wa''abölö Yotamo, me no lala sadölö manö itörö föna Lowalanginia Yehowa.', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 7, 'Ba hadia na niŵa''ö baero ö, ba khö Yotamo andrö, fasuwötania ba hadia ia nilaunia na, ba no mutanö ba zura razo Ndraono Gizeraeli ba ba zura razo mado Yuda.', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 8, 'Dua wulu a lima fakhe ia, me tobali razo ia, ba 16 fakhe razo ia ba Yeruzalema.', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475148, 'OT', 'Nga''ötö II', 27, 9, 'Ba mate Yotamo, itörö lala ndra amania, ba ba mbanua Dawido lako''o ia. Ba fangalinia razo, ba ononia Ahasi.', '["Faigi göi RazII 15:32–38","Faigi 26:16","Nga''ötII 33:14"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 1, 'Dua wulu fakhe Gahasi,[1] me tobali razo ia, ba 16 fakhe razo ia ba Yeruzalema. Ba tenga somasi Yehowa wolaunia, tenga si mane tuania Dawido.', '["Faigi göi RazII 16:1–14","MozIII 18:21; RazII 21:6; Yer 7:31","Yes 7:1"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 2, 'Itörö lala razo Ndraono Gizeraeli; ba ifalau''ö nadu Ba''ali, nifahele.', '["Faigi göi RazII 16:1–14","MozIII 18:21; RazII 21:6; Yer 7:31","Yes 7:1"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 3, 'Manunu kumöyö ia ba ndraso Mbeni-Hinomo, ba ifatörö ba galitö nononia matua, ba i''ohia''ö zogoro ita andrö ba niha baero, nitimba Yehowa mege, föna Ndraono Gizeraeli.[2]', '["Faigi göi RazII 16:1–14","MozIII 18:21; RazII 21:6; Yer 7:31","Yes 7:1"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 4, 'Mame''e sumange ia ba manunu kumöyö ba hili-hili andrö misa, ba idozigö börö geu sauri.', '["Faigi göi RazII 16:1–14","MozIII 18:21; RazII 21:6; Yer 7:31","Yes 7:1"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 5, 'Andrö wa ibe''e ba danga razo Ndrawa Garamo ia Lowalanginia Yehowa: te''ala ia labe''e ba ato sibai lara''u banuania, ba la''oloi''ö ba Ndramaseko. Ba ba danga razo Ndraono Gizeraeli göi tebe''e ia; abölö sibai te''ala ia ibe''e da''ö [göi].[3]', '["Faigi göi RazII 16:1–14","MozIII 18:21; RazII 21:6; Yer 7:31","Yes 7:1"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 6, '120.000 ibunu Feka, ono Remalia, mado Yuda, ha ma''öma''ökhö, oi niha sabölö, börö me no la''erogö Yehowa, Lowalangi ndra tuara.', '["Faigi göi RazII 16:1–14","MozIII 18:21; RazII 21:6; Yer 7:31","Yes 7:1"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 7, 'Ba Sikhiri, sabölö mado Geferayi, ba ibunu Ma''aseya, ono razo, ba Asirika, mandru ba gödo, ba Elikana, tambalina razo.', '["Faigi göi RazII 16:1–14","MozIII 18:21; RazII 21:6; Yer 7:31","Yes 7:1"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 8, 'Ba 200.000 la''oloi''ö talifusöra [mado Yuda], ira alawe ba ono matua ba ono alawe, ba ebua sibai zahulu ira ba mado Yuda, ba la''ohe ba Zamaria gahulua andrö.', '["Faigi göi RazII 16:1–14","MozIII 18:21; RazII 21:6; Yer 7:31","Yes 7:1"]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 9, 'Ba so ba da''ö zame''ele''ö khö Yehowa, Odedi döinia. Ba i''ondrasi zanuwö andrö, me mangawuli ira ba Zamaria, ba imane khöra: Si ndruhu, börö wönu Yehowa, Lowalangi ndra tuami, ba mado Yuda, wa no ibe''e ba dangami ira, wa tola mibubunu ira, ba mbakhu-bakhu dödömi andrö, sirugi ba mbanua si yaŵa.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 10, 'Ba iya''e, ba edöna ami mibali''ö sawuyumi mado Yuda andrö ba banua Yeruzalema, ira matua ba ira alawe. Ba hadia, si lö horö ami khö Lowalangimi Yehowa?', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 11, 'Ba mifondrondrongo ligu, ba mifofanö nira''u andrö, ni''oloi''ömi, talifusömi, alakha mangawuli ira; noa sa tohare khömi wönu Yehowa, fönu sabölö-bölö!', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 12, 'Ba maoso zatua mado Geferayi ösa, Asaria, ono Yohanano, ba Berekhia, ono Mesilemoto, ba Hisikia, ono Zalumi, ba Amasa, ono Hadilai, latenaŵa zangawuli andrö, si oroi manuwö, lamane khöra:', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 13, 'Lö tola mi''ohe ba da''e nira''u andrö! Edöna minönö horöda, awö lalöda andrö, nönö-nönö lalöda andrö khö Yehowa, ba huluda. Noa sa ebua sibai horöda, ba no tohare ba Ndraono Gizeraeli wönu [Yehowa], fönu sabölö-bölö.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 14, 'Ba labe''e aefa nira''u andrö ba lafuli gahulua andrö, ba zi so satua, awö niha sato fefu.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 15, 'Ba maoso niha andrö nitötöi töi mege, latolo nira''u andrö, lafonukha fefu zi lö nukha, ahulua no mege la''oguna''ö, labe''e khöra nukha ba badagahe ba labe''e gö, ba ha wa''ato zi tebai mofanö, ba lafokalide, ba la''ohe ba Yerikho, banua khorema andrö, ba zahatö ba niwara, ba lafuli ira ba Zamaria.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 16, 'Ba me luo da''ö, ba ifatenge ba razo Asiria razo Ahasi, ena''ö latolo ia.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 17, 'Ba so na göi Ndraono Gedomo, ba te''ala mado Yuda, ba la''oloi''ö ösa nira''u.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 18, 'Ba lasuwö mbanua ba zalo''o ba ba danö mado Yuda tanö raya Dawa Wilisiti, atu''a ira ba Mbetiseme ba ba Nayalona ba ba Gederoti ba ba Zokho ba ba halama soya khöra, ba ba Dimena ba ba halama soya khöra, ba ba Gimeso ba ba halama soya khöra, ba la''iagö manö da''ö.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 19, 'Yehowa sa''ae zi höndrögö mado Yuda, börö Gahasi andrö, razo Ndraono Gizeraeli, me ifobörö wa lö ngaroro ba mado Yuda, ba me no faröi ia khö Yehowa.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 20, 'Ba so moroi sa Digilata-Filineze, razo Asiria, ba wanuwö ya''ia, isasagö, faya wanolonia ya''ia.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 21, 'Ihalö sa''ae gana''a ba gosali Yehowa ba ba gödo razo ba ana''a zatua mbanua Ahasi, ba ibe''e khö razo Asiria, ba si lö boto.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 22, 'Ba he me luo isasagö ia razo Asiria ba ifuli mosala khö Yehowa razo Ahasi.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 23, 'Ifosumange Lowalangi Ndramaseko, si no mangalani ya''ia, imane: Lowalangi razo Ndrawa Garamo zanolo ya''ira mege; da''o ufosumange, ena''ö latolo ndra''o göi. Ba tobali famakikonia ba famakiko Ndraono Gizeraeli fefu.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 24, 'Ba i''ozaragö gama-gama ba gosali Lowalangi Ahasi ba ifufu; ikusi mbawandruhö gosali Yehowa, ba idozigö fatalinga Yeruzalema wama''anö naha wame''e sumange khönia.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 25, 'Ba banua mado Yuda fefu, ba idozigö wamazökhi hili-hili, ba wanunu kumöyö ba Lowalangi bö''ö, ba tobali i''andrö wönu Yehowa, Lowalangi ndra tuania.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 26, 'Ba bö''önia hikayania, ba hadia nilaunia fefu, he famobörö mege, ba he safuria andrö, ba no mutanö ba zura razo Ndraono Gizeraeli.', '[]', NULL),
  (3475149, 'OT', 'Nga''ötö II', 28, 27, 'Ba mate Gahasi, itörö lala ndra amania, ba ba Yeruzalema lako''o ia, bakha ba mbanua; lö''ö sa labe''e ba lewatö razo Ndraono Gizeraeli. Ba fangalinia razo, ba ononia Hisikia.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 1, 'Dua wulu a lima fakhe Hisikia, me tobali razo ia, ba 29 fakhe razo ia ba Yeruzalema. Ba töi ninania, ba Abiya, ono Zakharia.[1]', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 2, 'Ba somasi Yehowa ilau, i''o''ö sibai nilau duania Dawido mege.', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 3, 'Ba mbawa si föföna ba ndröfi wa''arazonia si föföna ibokai mbawandruhö gosali Yehowa ba ifuli i''azökhi.', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 4, 'Ba i''oroi''ö gere, awö Nono Lewi ba i''owuloi ira ba golayama tanö ba gatumbukha luo.', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 5, 'Ba imane khöra: Mifondrondrongo, ya''ami Ono Lewi! Mi''amoni sa''ae ba mi''amoni''ö gosali Yehowa, Lowalangi ndra tuami, ba miheta zi ta''unö ba ni''amoni''ö andrö!', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 6, 'Noa sa mosala ndra amada ba no lalau zi fatuwu khö Lowalangida Yehowa, ba no la''erogö ia. No laböhöli wangotahögö nahia Yehowa, no la''erogö.', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 7, 'Ba no lakusi mbawandruhö ba gewe''ewe andrö, ba fandru, ba no labunu, ba lö nitunura kumöyö, ba lö nibe''era sa''ae sumange khö Lowalangi Ndraono Gizeraeli, ba ni''amoni''ö andrö.', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 8, 'Andrö wa no göna fönu Yehowa mado Yuda ba banua Yeruzalema, fönu sabölö-bölö, awö wa no ibe''e fameta''u niha ira ba börö wehokha mbu, awö wa fasi niha bö''ö, no hörömi zangila.[2]', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 9, 'Ba hiza, ba no mate ba mbawa zi''öli ndra amada, ba onoda matua ba onoda alawe ba ira alaweda, ba no mu''oloi''ö, börö da''ö.[3]', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 10, 'Ba no uŵa''ö tödögu, fawu''u li ndra''o khö Yehowa, Lowalangi Ndraono Gizeraeli, ena''ö alö wönunia sabölö-bölö andrö khöda.', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 11, 'Ba böi areu ami, ya''ami iraonogu! Me no ya''ami nitutuyu Yehowa, ena''ö fönania so ami, ngoni-ngoninia, ba ena''ö enoninia ami, ba wanunu kumöyö khönia.', '["RazII 18:1–3","RazI 9:8","Faigi 28:8"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 12, 'Ba maoso Nono Lewi andrö: Mahata, ono Gamasai, ba Yoeli, ono Gasaria, ma''uwu Gahati. Ba ma''uwu Merari, ba Kisi, ono Gabidi, ba Asaria, ono Yehaleleli. Ba ma''uwu Gereso, ba Yoa, ono Zima ba Edena, ono Yoa.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 13, 'Ba ma''uwu Gelisafa, ba Simeri ba Yeieli. Ba ma''uwu Gasafo, ba Sakharia ba Matania.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 14, 'Ba ma''uwu Hemano, ba Yehieli ba Sime''i. Ba ma''uwu Yedutuno, ba Semaya ba Usieli.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 15, 'Da''ö zamalukha''ö iwara, mamoni ira, ba möi ira, ba wangehao osali, la''o''ö goroisa razo, dali nifakhoi Yehowa.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 16, 'Ba möi bakha ba gosali gere andrö, ba wangehao; fefu zi ta''unö ba gosali Yehowa, ba labe''e baero ba golayama, ba latema Ono Lewi, ba wanibo ba nidanö ba Gendrona.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 17, 'Me sambua desa''a ba mbaŵa si föföna labörötaigö wamoni ba ba zi meŵalu, ba larugi gewe''ewe andrö khö Yehowa: ba lahaogö gosali Yehowa, 8 ngaluo, ba ba zi sese, ba mbaŵa si föföna andrö, ba awai khöra.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 18, 'Ba möi ira yomo khö razo Hisikia, ba lamane: No mahaogö gosali Yehowa, ma''asambua, awö naha wame''e sumange nitunu, awö wakake andrö khönia, fefu, he meza andrö, naha roti nifaigi-faigi, fabaya fakake khönia, fefu.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 19, 'Ba fakake andrö fefu, nitibo''ö razo Ahasi, si lö ba dödönia, ba götö wa''arazonia, börö wangerogönia Yehowa, ba no mafuli ba nahania ba no mafuli ma''amoni''ö; no so ba da''ö, föna naha wame''e sumange, khö Yehowa.', '[]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 20, 'Ba ihulö wongi razo Hisikia, i''owuloi zatua mbanua fefu, ba möi ira miyaŵa ba gosali Yehowa.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 21, 'Ba mame''e sumange ba da''ö, fitu nga''eu nono zaŵi ba fitu nga''eu mbiri-biri si matua ba fitu rozi nono mbiri-biri; ba baero ö, ba fitu nga''eu nambi si matua, sumange fameta horö, tana ba wa''arazo ba ba ni''amoni''ö ba ba mado Yuda. Ba ibe''e li [razo] ba ma''uwu Ga''aroni, ere andrö, ba naha wame''e sumange andrö khö Yehowa labe''e.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 22, 'Ba lataba zaŵi andrö, ba la''edogö ndro ere, ba labe''e fanefe naha wame''e sumange. Ba lataba mbiri-biri si matua andrö, ba labe''e fanefe naha wame''e sumange ndro. Ba lataba göi nono mbiri-biri; ba labe''e fanefe naha wame''e sumange ndro.[4]', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 23, 'Ba aefa da''ö, ba la''ohe föna razo ba föna zato nambi si matua andrö, sumange fameta horö, ba latufa tangara.[5]', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 24, 'Ba lataba ere ba labe''e ba naha wame''e sumange ndro, fameta horö, ba wameta sala Ndraono Gizeraeli fefu; me no iŵa''ö razo: ba Ndraono Gizeraeli fefu zumange nitunu andrö, awö zumange fameta horö.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 25, 'Ba föna gosali Yehowa ifataro Nono Lewi, si so faritia ba biola nitika, sebua ba side-ide, dali nifakhoi Dawido föna ba Gado andrö, sangi''ila khö razo, ba Natano sama''ele''ö. Me no nifakhoi Yehowa da''ö, ba sama''ema zama''ele''ö andrö khönia.[6]', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 26, 'Ba so ba da''ö Nono Lewi andrö, si so nilau-lau andrö, khö Dawido, ba torofe ba gere.[7]', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 27, 'Ba iŵa''ö Hisikia la''ohe ba naha wame''e sumange zumange nitunu andrö; ba ha si''aikö lafobörö wame''e sumange nitunu andrö, ba labörötaigö göi zinunö andrö khö Yehowa ba lalau dorofe, dali nilau-lau andrö khö Dawido, razo Ndraono Gizeraeli.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 28, 'Ba lafalögu tou ira sato fefu; ba manunö zanunö andrö ba telau dorofe — oi irege awai wame''e sumange nitunu andrö.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 29, 'Ba me no awai wame''e, ba labalöduhini tou danö razo ba awönia andrö fefu, ba lafalögu tou ira.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 30, 'Ba laŵa''ö ba Nono Lewi razo Hisikia ba satua andrö, lasuno Yehowa fanunö ndra Dawido Asafo sangi''ila andrö. Ba lalau wanunö andrö, somuso tödö ira, ba lafaöndrö ira ba lafalögu tou ira.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 31, 'Ba humede Hisikia, imane: No [mifuli] mi''amoni''ö ami khö Yehowa; ba mi''ae mi''ohe ba gosali Yehowa zumange nitaba ba sumange fanuno! Ba la''ohe zumange nitaba ba sumange fanuno sato, ba dozi si terou tödö, ba labe''e zumange nitunu.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 32, 'Ba sumange fefu nibe''e zato, ba 70 nga''eu zaŵi ba 100 nga''eu mbiri-biri si matua ba 200 rozi nono mbiri-biri; oi sumange nitunu, sumange Yehowa.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 33, 'Ba ni''amoni''öra, ba 600 nga''eu zaŵi ba 3000 nga''eu mbiri-biri.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 34, 'Ba ambö ere; tebai ahori labo''ai guli zumange; ba latolo ira iwara, Ono Lewi andrö, irege awai halöŵöra ba irege la''amoni''ö ira ere; me no moroi ba dödö ba Nono Lewi andrö wamoni; ambö ba gere.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 35, 'Ba oya sibai göi zumange nitunu, awö dawö zumamange fangorifi, awö zumange nibadu, nifao ba zumange nitunu andrö. Ba tobali no mufuli mu''ohe ba lala wame''e sumange andrö ba gosali Yehowa.', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475150, 'OT', 'Nga''ötö II', 29, 36, 'Ba somuso tödö Hisikia, awö niha sato fefu, börö ni''asogö Lowalangi khöra; noa sa i''ogomuzaö manö da''ö fefu.[8]', '["MozIII 8:15; Heber. 9:21","Moz. III, 4:15","Nga''ötI 16:4; 23:5","MozIV 10:10","RazI 8:66"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 1, 'Ba ifatenge Hisikia ba Ndraono Gizeraeli fefu, ba ba mado Yuda ba ifa''ohe''ö göi zura ba mado Geferayi ba ba mado Manase, ena''ö möi ira ba gosali Yehowa, ba Yeruzalema, ba wolau fasa khö Yehowa, Lowalangi Ndraono Gizeraeli.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 2, 'Ba lahonogöi sa''ae salaŵa ba satua mbanua andrö khönia, ba banua Yeruzalema fefu, ba mbaŵa si dua lalau wasa.[1]', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 3, 'No tebai mege lalau-lau ba ginötönia, me no ambö ere si amoni''ö ya''ira, ba me lö''ö na sowulo niha sato ba Yeruzalema.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 4, 'Ba somasi razo ba somasi zato fefu wamagölö andrö.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 5, 'Ba lahonogöi na, ba Ndraono Gizeraeli fefu, i''otarai Mbereseba, numalö ba Dano, ba lafarongogö, ena''ö möi ira, ba wolau fasa andrö khö Yehowa, Lowalangi Ndraono Gizeraeli, ba Yeruzalema. Noa sa''ae ara lö nilaura ya''ia, lö mu''o''ö nifakhoi.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 6, 'Ba latöröi mbanua Ndraono Gizeraeli ba banua mado Yuda fefu si fagohi andrö, la''ohe zura andrö nibe''e razo ba satua mbanua andrö khönia, ba la''ombakha''ö ni''oroi''ö razo, no imane: Ya''ami Iraono Gizeraeli, mifuli ami khö Yehowa, Lowalangi [ndra tuami] Aberahamo Iza''aki, Izeraeli, ena''ö ifuli i''otahögö zoloi andrö, si no aefa ba danga razo Asiria, si tosai na, ya''ami.[2]', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 7, 'Böi mifaomagö ami khö ndra amami ba ba niwami andrö, si no faröi khö Yehowa, Lowalangi ndra tuara, ba no tobali ibe''e nifakiko ira, sanehe ami.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 8, 'Ba böi sabe''e tandro ami, si mane ira amami; mira''u danga Yehowa ba mi''ae ba ni''amoni''ö andrö khönia, ni''amoni''önia, si lö tebulö, ba mi''o''ö niŵa''ö Lowalangimi Yehowa, ena''ö döhö wönunia khömi, fönu sabölö-bölö andrö.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 9, 'Na mifalalini gera-erami, wamuli ya''ami khö Yehowa, ba falukha wa''ahakhö dödö dalifusömi ba iraonomi, fa''ahakhö dödö zangoloi''ö ya''ira mege, fa tola mangawuli ira ba danö andre. Me no sebua tödö ba sahakhö tödö Lowalangimi Yehowa, ba lö i''erogö ami, na mifuli ami khönia.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 10, 'Ba latöröi mbanua si fagohi andrö, ba danö mado Geferayi ba ba danö mado Manase, ba irugi danö mado Zebuloni, ba la''igi''igi''ö ira ba la''o''aya.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 11, 'Ba so ösa — lö atoto — mado Gaseri ba mado Manase ba mado Zebuloni, sangide-ide''ö ya''ira, ba möi ba Yeruzalema.[3]', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 12, 'Ba ifahisi göi mado Yuda tanga Lowalangi, i''osara''ö dödöra, ba wolo''ö oroisa andrö, nibe''e razo ba satua andrö khönia, dali ni''oroi''ö Yehowa.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 13, 'Ba owulo niha ba Yeruzalema ato sibai, ba wolau owasa roti si lö mu''aisöni, ba mbaŵa si dua, owuloa sato sibai niha.', '["MozII 12:6; MozIV 9:11","RazII 15:16","RazI 6:5"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 14, 'Ba latema laheta naha wame''e sumange [ba nadu], ba Yeruzalema; ba he naha wanunu kumöyö andrö fefu, ba laheta, ba latibo''ö ba mbombo, ba Gendrona.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 15, 'Ba aefa da''ö, ba lataba wasa, ba zi meweleöfa, ba mbaŵa si dua. Ba saila gere ba Ono Lewi, ba la''omoni''ö ira, ba la''ohe ba gosali Yehowa zumange nitunu.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 16, 'Ba la''iagö nahiara, dali nifakhoi khöra ba goroisa Moze, enoni Lowalangi andrö; ere zogule''ö do andrö, nifa''ema Nono Lewi khöra.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 17, 'Ato sa ba gowuloa andrö, si lö mu''amoni''ö, ba Ono Lewi sa''ae zanaba ono mbiri-biri fasa andrö, salahi zi ra''iö fefu, ba we''amoni''ö ya''ira khö Yehowa.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 18, 'Niha sato andrö sa, mado Geferayi ba mado Manase ba mado Isasari ba mado Zebuloni — ato ira — ba lö nihaogöra ya''ira, la''a wasa, ba tenga solo''ö nifakhoi. Ba no mangandrö Hisikia, salahira, no imane: Yehowa si no ebua tödö,', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 19, 'ba yamubologö dödönia khöra fefu, si no mame''e ba dödöra wangalui Lowalangi, Yehowa, Lowalangi ndra tuara, lö lai wa lö mutörö wangehao andrö, soguna ba ni''amoni''ö andrö.[4]', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 20, 'Ba ifondrondrongo li Hisikia Yehowa ba i''orifi niha sato.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 21, 'Ba lalau gowasa roti si lö mu''aisöni Iraono Gizeraeli andrö, si so ba Yeruzalema, fitu ngaluo, omuso sibai dödöra, ba ero ma''ökhö lasuno Yehowa Ono Lewi ba ere, a''oi dölara.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 22, 'Ba ihaogö wehedenia Hisikia ba Nono Lewi fefu, saboto ba dödö Yehowa. Ba la''aga''aga zumange andrö, fitu bongi wa''ara, ladabadaba zumange fangorifi ba lasuno Yehowa, Lowalangi ndra tuara.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 23, 'Ba mamagölö zato fefu, fitu bongi tö na lö la''etu''ö gowasa, ba fitu ngaluo tö lalau zowua-wua dödöra.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 24, 'No 1000 nono zaŵi ba 7000 mbiri-biri nibe''e Hisikia, razo mado Yuda, saoha gölönia ba zato; ba satua mbanua göi, ba 1000 göi labe''e ono zaŵi ba 10.000 mbiri-biri, saoha gölöra. Ba ato zi amoni''ö ya''ira ere.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 25, 'Ba somuso tödö zato, mado Yuda, awö gere, awö Nono Lewi, awö zato andrö fefu, Iraono Gizeraeli si no mangondra, awö niha bö''ö andrö, si oroi danö Ndraono Gizeraeli, ba he si fatewu ba mado Yuda.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 26, 'Ba no fa''omuso dödö sebua ba Yeruzalema; me no lö ni''ilara sa''ae si mane da''ö, ba Yeruzalema, i''otarai luo Zelomo, ono Dawido, razo Ndraono Gizeraeli.', '["MozIV 9:6","MozIV 6:23"]', NULL),
  (3475151, 'OT', 'Nga''ötö II', 30, 27, 'Ba maoso gere andrö, ono Lewi, ba lafahowu''ö zato, ba terongo lira, ba fangandröra, ba irugi nahia Yehowa andrö, ni''amoni''ö, ba zorugo.[5]', '["MozIV 9:6","MozIV 6:23"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475152, 'OT', 'Nga''ötö II', 31, 1, 'Ba me no awai da''ö fefu, ba lasaŵa mbanua mado Yuda Iraono Gizeraeli fefu, si so mege, ba larasa harefa andrö ba la''obö Gasera ba ladudugö hili-hili andrö, fabaya naha wame''e sumange ba mado Yuda fefu ba ba mado Mbeniyami ba ba mado Geferayi ba ba mado Manase, irege ahori fefu labe''e. Ba awena lafuli ira khöra Iraono Gizeraeli fefu, ba mbanuara.[1]', '["MozV 7:5; RazII 18:4","MozIV 28","MozIII 27:30"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 2, 'Ba ifataro ngenoli gere andrö Hisikia, ba Ono Lewi, dali ngenolira andrö, balazi hadia halöŵö zamösana, halöŵö gere ba halöŵö Nono Lewi, ba wame''e sumange nitunu ba sumange fangorifi, ena''ö enoni ira ba golayama nahia Yehowa, ba ena''ö lalau wangandrö zaoha gölö ba fanuno.', '["MozV 7:5; RazII 18:4","MozIV 28","MozIII 27:30"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 3, 'Ba buala razo, ana''ania, ba böli zumange nitunu andrö, sumange nitunu na mahemolu mbanua, ba na tanö owi ba ba luo sabato ba ba wasulöna ba ba gowasa andrö, dali nifakhoi ba goroisa Yehowa andrö.[2]', '["MozV 7:5; RazII 18:4","MozIV 28","MozIII 27:30"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 4, 'Ba ibe''e li razo ba zato, banua Yeruzalema, ba wame''e ba gere ba ba Nono Lewi tana khöra, fa böi laböhöli goroisa Yehowa.', '["MozV 7:5; RazII 18:4","MozIV 28","MozIII 27:30"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 5, 'Ba me no larongo niŵa''önia andrö Iraono Gizeraeli, ba labe''e zi a''a mbua nowi ba agu ba fanikha ba ŵe ŵani, si a''a mbua nowi fefu, oya sibai, sambua ni''ofulu hadia ia fefu la''ohe, ba no fahöna.', '["MozV 7:5; RazII 18:4","MozIV 28","MozIII 27:30"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 6, 'Ba Iraono Gizeraeli, awö mado Yuda, ba mbanua mado Yuda misa, ba sambua ni''ofulu göi la''ohe saŵi ba biri-biri, ba sambua ni''ofulu göi mbuala andrö ni''amoni''ö khö Lowalangira Yehowa; oi laföfö''ö wame''e tou.[3]', '["MozV 7:5; RazII 18:4","MozIV 28","MozIII 27:30"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 7, 'Ba mbaŵa si tölu labörötaigö wangöhöna andrö, ba ba mbaŵa si fitu mo''ahonoa khöra.', '["MozV 7:5; RazII 18:4","MozIV 28","MozIII 27:30"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 8, 'Ba so Hisikia, awö zatua mbanua, lafaigi nihöna andrö, ba lasuno Yehowa ba banuania Iraono Gizeraeli.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 9, 'Ba me isofu ba gere ba ba Nono Lewi lala nihöna andrö Hisikia,', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 10, 'ba imane khönia Asaria, ere sebua, ma''uwu Zadoki: I''otarai me labörötaigö molohe ba gosali Yehowa saoha gölö andrö, ba manga-manga ndra''aga, abusoga ba ebua na zi tosai; noa sa ifahowu''ö mbanuania Yehowa, ba tobali tosai na khöma zi fahöna andre.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 11, 'Ba iŵa''ö Hisikia, lafo''oto''oto mbate''e ba gosali Yehowa; ba me no awai da''ö,[4]', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 12, 'ba lahaogö wolohe ba da''ö mbuala andrö nibe''e saoha gölö ba si sambua ni''ofulu andrö, awö mbuala ni''amoni''ö. Ba samaigi-maigi, ba Ono Lewi andrö, Khanania, ba tambalinania nakhinia Sime''i. Ba nibe''e tohu-tohu danga ndra Khanania akhinia Sime''i,', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 13, 'ba Yehieli ba Azasia ba Mahata ba Azaheli ba Yerimoto ba Yosabada ba Elieli ba Yesimakhia ba Mahata ba Benaya, dali nifakhoi razo Hisikia awö Gasaria, satua ba gosali Yehowa.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 14, 'Ba samaigi-maigi buala andrö, nibe''e saoha gölö khö Lowalangi, ba Ono Lewi andrö, Kore, ono Yimina, sanaro ba mbawandruhö, ena''ö tebe''e mbuala andrö, saoha gölö, tana khö Yehowa, awö game''ela andrö, ni''amoni''ö sibai.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 15, 'Ba barö mbawania ndra Edena Miniyami ba Yesua ba Semaya ba Amaria ba Sekhania, ena''ö la''atulö''ö wame''e ba niwara ba mbanua gere andrö, ni''angenoligö, he ba zatua, ba he ba ndraono, lö lai ndra matua andrö,', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 16, 'si no mutanö ba zura nga''ötö, i''otarai zi medölu fakhe fa''ebua ba si a''a moroi andrö, dozi si möi-möi ba gosali Yehowa, na inötö zamösana, ba wangai halöŵöra, sangesangenoli, dali nifakhoi khöra.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 17, 'Ba ba wananö ba zura nga''ötö andrö ere andrö, ba sawu-sawu latanö, ba ba Nono Lewi, ba i''otarai zi 20 fakhe, ba si a''a moroi andrö, dali halö-halöŵöra, ba ngenolira.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 18, 'Ba fabaya onora sawuyu ba fo''omora ba onora matua ba onora alawe — khöra fefu — latanö; noa sa a''oi dödöra we''amoni''ö ya''ira, ba ni''amoni''ö andrö.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 19, 'Ba so ba nga''ötö Ga''aroni, ere andrö, ba nowi ba mbenua andrö, si faböbö ba mbanuara andrö, niha — no mutötöi döira — same''e ba ndra matua, ere, fefu, ba ba Nono Lewi fefu, si no mutanö ba zura, tana khöra.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 20, 'Si manö wolau Hisikia ba mado Yuda fefu; si sökhi ba satulö ba si duhu wamaigi Lowalanginia Yehowa ilau.', '["RazI 6:5"]', NULL),
  (3475152, 'OT', 'Nga''ötö II', 31, 21, 'Fefu hadia ia nilaunia ba halöŵö andrö, ba gosali Yehowa ba ba goroisa andrö ba ba gamakhoita, ba wangalui Lowalanginia, ba no soroi ba dödö, ba mofozu göi.', '["RazI 6:5"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 1, 'Ba me aefa da''ö,[1] fa''atarö dödö Hisikia [ba zi sökhi], ba so moroi sa Zaneribi, razo Asiria. Isaŵa danö mado Yuda ba isuwö mbanua saro, ena''ö na atu''a ia dödönia.', '["Faigi göi RazII 18:13 b.t.; Yes 36:1 b.t.","RazI 9:24","RazII 6:16","Yer 17:5; YohI. 4:4"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 2, 'Ba me i''ila Hisikia, so moroi sa Zaneribi, ba wanuwö Yeruzalema,', '["Faigi göi RazII 18:13 b.t.; Yes 36:1 b.t.","RazI 9:24","RazII 6:16","Yer 17:5; YohI. 4:4"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 3, 'ba mamagölö ia ba zatua mbanua andrö khönia, ena''ö na labunu hele baero mbanua; ba latolo ia [ba da''ö].', '["Faigi göi RazII 18:13 b.t.; Yes 36:1 b.t.","RazI 9:24","RazII 6:16","Yer 17:5; YohI. 4:4"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 4, 'Ba ato zowulo niha, ba wamunu hele, awö mbombo andrö, sanörö tanö andrö, lamane: Hana wa tabe''e lö ambö idanö khö ndra razo Asiria, na so ira?', '["Faigi göi RazII 18:13 b.t.; Yes 36:1 b.t.","RazI 9:24","RazII 6:16","Yer 17:5; YohI. 4:4"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 5, 'Ba i''abe''e''ö dödönia [Hisikia], ba i''a''azökhi zaukha göli kara, fefu; möi ia ba malige andrö ba ba göli tanö baero, ba i''aro''ö Milo andrö ba mbanua Dawido, ba oya ifafazökhi''ö ono wana ba baluse.[2]', '["Faigi göi RazII 18:13 b.t.; Yes 36:1 b.t.","RazI 9:24","RazII 6:16","Yer 17:5; YohI. 4:4"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 6, 'Ba ifataro gumandra, solohe sato; ba ifalukha''ö khönia da''ö, ba newali, fönaföna mbawa göli, ba ihaogö wehedenia khöra, imane:', '["Faigi göi RazII 18:13 b.t.; Yes 36:1 b.t.","RazI 9:24","RazII 6:16","Yer 17:5; YohI. 4:4"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 7, 'Mi''abe''e''ö dödömi, böi mangiwa! Böi mi''abusi tödö ba böi mibe''e nikeani razo Asiria ami; ba he ba zato sibai andrö ni''ohenia, ba böi tokea ami! Me no ebua nawöda, moroi ba nawönia.[3]', '["Faigi göi RazII 18:13 b.t.; Yes 36:1 b.t.","RazI 9:24","RazII 6:16","Yer 17:5; YohI. 4:4"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 8, 'Awönia, ba fa''abölö niha, ba awöda, ba Lowalangida Yehowa, ba wanolo ya''ita, ba ena''ö ya''ia zi fasuwö salahida![4]', '["Faigi göi RazII 18:13 b.t.; Yes 36:1 b.t.","RazI 9:24","RazII 6:16","Yer 17:5; YohI. 4:4"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 9, 'Ba ifatenge genoninia Saneribi, razo Asiria (ba ya''ia, ba sanuwö Lakhisi, awö zato andrö khönia), ifatenge ba Yeruzalema, khö Hisikia razo mado Yuda, ba ba mado Yuda fefu, ba Yeruzalema, imane khöra:', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 10, 'Da''ö niŵa''ö Zaneribi, razo Asiria: Hadia dötönafömi, wa mi''iagö manö Yeruzalema, na lasasagö ami?', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 11, 'Si ndruhu, Hisikia andrö zamowöhö ya''ami, ena''ö ibe''e mate olofo ba mate owökhi dödö ami, wanguma''ö: I''efa''ö dania ita ba danga razo Asiria Lowalangida Yehowa!', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 12, 'Hadia, tenga Hisikia da''ö göi zanudugö mege hili-hili andrö khönia, fabaya naha wame''e sumange, ba sanguma''ö ba mado Yuda ba ba mbanua Yeruzalema: Ha sambua naha wame''e sumange, sangalulu ami, ba ha ba da''ö mitunu zumange?', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 13, 'Hadia, lö nirongomi he mawisa ba niha baero fefu misa, ira amagu ndra''aga? He wisa Lowalangi niha baero andrö, ba danöra misa, hadia no la''ila la''efa''ö ba dangagu danöra andrö?', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 14, 'Ha niha ba Lowalangi niha andrö fefu, nihori ndra amagu, zangila mege i''efa''ö ena''ö ba dangagu mbanuania, wa iefa''ö ena''ö ami göi ba dangagu Lowalangimi andrö?', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 15, 'Ba böi sa''ae mibe''e nifowöhö Hisikia ami, böi yamufaelungu ami ba zi manö! Böi mifati linia! Lö''ö sa Lowalangi ba niha fefu ba ba zalaŵa, heza, sangila mangefa''ö ba dangagu banuania, ba he ba danga ndra amagu mege; ba lö''ö göi i''efa''ö ami ba dangagu Lowalangimi andrö.', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 16, 'Ba latohugö na wanandraŵai si Lowalangi, Yehowa, ba enoninia Hisikia sinenge Zaneribi andrö.', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 17, 'Ba sura göi ifa''ohe''ö, ba wanandraŵaisi Yehowa, Lowalangi Ndraono Gizeraeli, ba ba wamöbögö khönia hadia ia, imane: Si mane Lowalangi niha baero andrö, si tebai mangefa''ö ba dangagu banuara, si manö göi Lowalangi Hisikia andrö, wa tebai i''efa''ö ba dangagu mbanuania.', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 18, 'Ba mu''ao ira [sinenge no mege] ba mbanua Yeruzalema andrö, si so ba dete göli kara, la''ebua''ö lira, li Ndraono Gizeraeli, ba wameta''u ya''ira, ena''ö tokea ira, ba ena''ö möi ba dangara [ba danga zanuwö] mbanua.', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 19, 'Itörö lira Lowalangi Yeruzalema andrö, lafaomagö ba Lowalangi niha baero andrö, nifazökhi danga niha.[5]', '["Sin 135:15"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 20, 'Ba me mangandrö razo Hisikia, awö Yesaya sama''ele''ö, ono Gamosi, börö da''ö no mege, me la''angaröfi li Yehowa,', '["RazII 19:37"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 21, 'ba ifatenge mala''ika Yehowa, sangohori sanuwö fefu, awö zolohe ya''ira, awö gumandra, ba nahia razo Asiria; ba tobali ifuli ia ba danönia, no tehawu ia fa''aila. Ba me möi ia ba gosali Lowalanginia, ba so ndraononia, ba labunu ia si''öli[6]', '["RazII 19:37"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 22, 'Si manö wangefa''ö Yehowa Hisikia ba banua Yeruzalema ba danga Zaneribi, razo Asiria, ba ba danga danö bö''ö fefu, ba lö''ö sa''ae hadia ia khöra, fasui manö, ibe''e.', '["RazII 19:37"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 23, 'Ba ato zolohe ba Yeruzalema buala khö Yehowa, ba khö Hisikia, razo ba Yeruzalema, ba gama-gama sebua böli labe''e. Ba razo sebua ia, me aefa da''ö, wamaigi niha baero fefu.', '["RazII 19:37"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 24, 'Ba me luo da''ö, ba mofökhö Hisikia, fökhö fanunu. Ba mangandrö ia khö Yehowa. Ba humede khönia Yehowa ba ibe''e khönia dandra, sahöli-höli dödö.[7]', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 25, 'Ba lö isulöni Hisikia nilau khönia, fa''ahakhö dödö andrö, fayaŵa ia; andrö wa tohare khönia wönu, fönu sabölö-bölö, khönia ba ba mado Yuda, ba ba mbanua Yeruzalema.', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 26, 'Ba mangalulu Hisikia, me no fayaŵa dödönia; andrö wa lö itörö ira na fönu Yehowa, fönu sabölö-bölö andrö, ba götö Hisikia.', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 27, 'Ba no ebua sibai gana''a Hisikia, ba no sabölö sibai ia. No ilau khönia mbate''e girö-girö, firö ba ana''a ba mani-mani ba rembaremba ba baluse ba hadia ngawalö gama-gama na, sebua böli,', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 28, 'ba omo ba nihöna hadia ia ilau, nahia mbua nowi ba agu ba fanikha; ba he kandra ngawalö gurifö, ba ilau göi, ba kandra mbiri-biri, ba mbenua.', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 29, 'Ba banua itaru''ö ba no oya sibai khönia gurifö, biri-biri ba saŵi; noa sa i''ebua''ö gana''ania Lowalangi.', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 30, 'Da''ö Hisikia andrö somba''a ungo nidanö Gihona si yaŵa, samatörö mitou ba ba mbanua Dawido, tanö ba gaekhula luo; ba hadia ia fefu, nilau Hisikia, ba mofozu.', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 31, 'Ba me so zinenge andrö, nifatenge razo Mbabeli khönia, ba wanofu tandra andrö sahöli-höli dödö, ba danö mege, ba ilulu Hisikia Lowalangi, ba wanandraigö ya''ia, ena''ö oroma fefu hadia ia zi so ba dödönia bakha.', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 32, 'Ba bö''önia hikaya Hisikia andrö, ba hadia ia nilaunia si sökhi, ba no mutanö ba zura wama''ele''ö andrö khö Yesaya sama''ele''ö, ono Gamosi, ba ba zura razo mado Yuda ba ba zura razo Ndraono Gizeraeli.', '["RazII 20"]', NULL),
  (3475153, 'OT', 'Nga''ötö II', 32, 33, 'Ba mate Hisikia, itörö lala ndra amania, ba ba lewatö ma''uwu Dawido lako''o ia, tanö miyaŵa; ba lafosumange ia ba wa''amatenia mado Yuda fefu ba banua Yeruzalema. Ba fangalinia razo, ba ononia Manase.', '["RazII 20"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 1, 'Ha mewelendrua fakhe Manase,[1] me tobali razo ia, ba 55 fakhe razo ia ba Yeruzalema.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 2, 'Ba si fatuwu khö Yehowa ilau, i''ohia''ö zogoro ita ba niha baero andrö, nitimba Yehowa mege föna Ndraono Gizeraeli.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 3, 'Ifuli i''a''azökhi hili-hili andrö, nidudugö namania Hisikia mege, ba ifa''anö naha wame''e sumange ba Mba''ali andrö, ba ifazökhi Gasera, ba mangalulu ia ba ngahönö ba mbanua si yaŵa ba ifosumange da''ö.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 4, 'Ba ifa''anö göi naha wame''e sumange [ba nadu] bakha ba gosali Yehowa, ba niŵa''ö Yehowa: Ba Yeruzalema nahia döigu, si lö mamalö-malö.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 5, 'Ba ba golayama gosali Yehowa, si dua görö, ba ifa''anö naha wame''e sumange ba ngahönö andrö fefu, ba mbanua si yaŵa.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 6, 'Ononia matua ifatörö ba galitö, ba ndraso Mbeni-Hinomo, fakelemu ia ba faeta ba hadia ia nekhe-nekhe bö''ö ba zi tobini; ba ifataro zogaoni bekhu ba sangombakha eluaha gila-ila; oya ngawalö ilau si fatuwu khö Yehowa, ba wangandrö fönunia.[2]', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 7, 'Ba adu nifu andrö, nifalau''önia, ba ibe''e ba gosali Lowalangi, ba niŵa''ö Lowalangi khö Dawido ba khö nononia Selomo: Osali andre, awö Yeruzalema, nituyugu, ba mado Ndraono Gizeraeli fefu, ba ubali''ö nahia döigu, götö-götö wa''ara.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 8, 'Ba lö''ö sa''ae uwu''ai gahe Ndraono Gizeraeli ba danö andrö, nibe''egu khö ndra tuami, balazi na so ba dödöra wolo''ö fefu hadia ia niŵa''ögu khöra, na latörö sibai goroisa andrö, awö gamakhoita, awö lala andrö, nifa''ema Moze.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 9, 'Ba tobali ifowöhö mado Yuda ba banua Yeruzalema Manase, ba wolau si lö sökhi, sabölö-bölö moroi ba nilau niha baero andrö, nihori Yehowa föna Ndraono Gizeraeli.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 10, 'Ba humede Yehowa khö Manase ba ba mbanuania, ba lö lafondrondrongo.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 11, 'Ba ifa''amöi khöra Yehowa zolohe sanuwö khö razo Asiria; ba lara''u Manase khai-khai, ba laböbö ba la''ohe ba ba Mbabeli.', '["Faigi göi RazII 21","MozV 18:10,11"]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 12, 'Ba me no abu dödönia, ba i''alui wa''ebolo dödö Lowalanginia Yehowa, i''ide-ide''ö sibai ia föna Lowalangi ndra tuania.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 13, 'Ba me mangandröngandrö ia khönia, be ifondrondrongo linia. I''o''ö khönia wakaosania andrö, ba i''ohe mangawuli ia ba Yeruzalema, ifuli ifataro razo. Ba awena aboto ba dödö Manase, wa Yehowa Lowalangi.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 14, 'Ba aefa da''ö, ba ifalau''ö göli kara andrö, tanö baero, ba mbanua Dawido, tanö ba gaekhula luo, mitou ba Gihona, ba ndraso, irugi ba lala miyomo ba mbawa göli gi''a, ifasui Gofeli andrö, öli salaŵa sibai. Ba ifataro göi gumandra ba mbanua saro, ba mado Yuda, fefu.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 15, 'Ba iheta ba gosali Yehowa nadu andrö, adu niha baero, ba adu famaedo andrö, fabaya naha wame''e sumange fefu, nifa''anönia ba hili gosali Yehowa ba ba Yeruzalema, itibo''ö baero mbanua.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 16, 'Ba ifuli i''azökhi naha wame''e sumange khö Yehowa ba ibe''e zumange fangorifi ba sumange fangandrö saoha gölö, ba da''ö; ba ibe''e li ba mado Yuda, ena''ö Yehowa, Lowalangi Ndraono Gizeraeli lafosumange.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 17, 'Ba niha sato, ba si dörö-dörö mame''e sumange ba hili-hili andrö, he ŵa''ae khö Lowalangira Yehowa labe''e.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 18, 'Ba bö''önia hikaya Manase ba fangandrönia andrö khö Lowalanginia, awö niŵa''ö zangi''ila andrö, sama''ema khönia niŵa''ö Lowalangi Ndraono Gizeraeli, ba no mutanö ba zura hikaya razo Ndraono Gizeraeli.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 19, 'Ba fangandrönia andrö, ba he wisa wamondrongo Yehowa linia, awö horönia andrö fefu, ba falimosania, awö naha andrö misa, ba nifazökhinia hili-hili, awö nibe''enia Asera ba adu nifu, me lö ni''ide-ide''önia ya''ia na, ba no mutanö ba zura hikaya nisura zangi''ila andrö.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 20, 'Ba mate Manase, itörö lala ndra amania, ba ba ngai nomonia lako''o ia. Ba fangalinia razo, ba ononia Amoni.', '[]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 21, 'Dua wulu a rua fakhe Gamoni, me tobali razo ia, ba ha mendrua fakhe razo ia ba Yeruzalema,[3]', '["RazII 21:19 b.t."]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 22, 'Ba si fatuwu khö Yehowa ilau, si mane amania Manase mege. Ba nadu nifu andrö fefu, nifazökhi Manase mege, ba i''oya''ö zumange Amoni, enoni da''ö ia.', '["RazII 21:19 b.t."]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 23, 'Ba lö''ö sa i''ide-ide''ö ia föna Yehowa, si mane amania mege; ya''ia, Amoni, ba ihöna manö horö ba hulunia.', '["RazII 21:19 b.t."]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 24, 'Ba mamagölö genoninia, ba wamunu ya''ia, ba labunu ia ba gödonia.', '["RazII 21:19 b.t."]', NULL),
  (3475154, 'OT', 'Nga''ötö II', 33, 25, 'Ba labunu göi fefu zamagölö mege ba wamunu razo Amoni niha ba danö; ba lafataro fangalinia razo nononia Yosia niha ba danö.', '["RazII 21:19 b.t."]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 1, 'Ha meŵalu fakhe na Yosia,[1] me tobali razo ia, ba 31 fakhe razo ia ba Yeruzalema.', '["Faigi göi RazII 22:1–23:20","RazI 13:3","MozIII 26:30","RazI 13:2"]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 2, 'Ba somasi Yehowa ilau, itörö lala duania Dawido, lö ihole''ö ia, he ba gambölö, ba he ba gabera.', '["Faigi göi RazII 22:1–23:20","RazI 13:3","MozIII 26:30","RazI 13:2"]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 3, 'Ba me no alua mewitu fakhe razo ia, me iraono na ia, ba ibörötaigö mangalui Lowalangi duania Dawido, ba me no alua mewelezara fakhe, ba ibörötaigö mangehao tanö mado Yuda, awö Yeruzalema, wangeheta hili-hili andrö ba Asera andrö ba adu nifu ba adu nifahele.[2]', '["Faigi göi RazII 22:1–23:20","RazI 13:3","MozIII 26:30","RazI 13:2"]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 4, 'Ba zi so ya''ia ladudugö naha wame''e sumange khö Mba''ali, ba la''eŵa nadu luo andrö, ba dete yaŵa: ba Asera andrö ba adu nifu ba adu nifahele, ba irasa, ifufu ba ifazawili ba dete lewatö zamosumange me mege.[3]', '["Faigi göi RazII 22:1–23:20","RazI 13:3","MozIII 26:30","RazI 13:2"]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 5, 'Ba töla gere andrö, ba itunu ba dete naha wame''e sumange andrö khöra, wangehao tanö mado Yuda, awö Yeruzalema.[4]', '["Faigi göi RazII 22:1–23:20","RazI 13:3","MozIII 26:30","RazI 13:2"]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 6, 'Ba ba mbanua mado Manase ba ba mbanua mado Geferayi ba ba mbanua mado Zimeoni ba irugi ba mado Nafetali — ba gadudula khöra misa —', '["Faigi göi RazII 22:1–23:20","RazI 13:3","MozIII 26:30","RazI 13:2"]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 7, 'ba idudugö naha wame''e sumange, irasa ba ifufu Gasera andrö ba adu nifu; ba adu luo andrö, ba i''eŵa, ba danö Ndraono Gizeraeli ma''asagörö. Ba ifuli ia ba Yeruzalema.', '["Faigi göi RazII 22:1–23:20","RazI 13:3","MozIII 26:30","RazI 13:2"]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 8, 'Ba me no alua mewelewitu fakhe razo ia, me ihaogö-haogö danö ba osali, ba ifatenge Zafana andrö, ono Gasalia, ba kumandra ba mbanua andrö, Ma''aseya, ba sa''asa sebua, Yoa, ono Yoahasi, ba wanga''azökhi osali Lowalanginia Yehowa.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 9, 'Ba möi ira khö gere sebua, Hilikia, ba labe''e ba dangania gana''a andrö, si no mube''e ame''ela ba gosali Lowalangi, ni''ozaragö Nono Lewi andrö, sanaro ba mbawandruhö, ni''ozaragö ba mado Manase ba ba mado Geferayi ba ba mado Gizeraeli bö''ö, fefu, ba he ba mado Yuda fefu ba ba mado Mbeniyami ba ba mbanua Yeruzalema.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 10, 'Ba labe''e ba danga högö duka, nifataro ba gosali Yehowa; ba ya''ira zame''e ba zohalöŵö ba gosali Yehowa, ba wanga''azökhi osali, ba ba wangehao.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 11, 'Ba zotomo ba ba duka gara labe''e, ena''ö la''öli gara nitoto ba eu famaböbö andrö ba buatö ba nomo andrö, nidudugö razo mado Yuda mege.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 12, 'Ba mohalö-halöŵö niha, tenga si falimo, lahalö-halö halöŵö andrö, niŵa''ö khöra: Ono Lewi andrö, Yahata ba Obadia, ma''uwu Merari ba Sakharia ba Mesula, ma''uwu Gahati, ba wamaigi-maigi. Ba Ono Lewi andrö — dozi si no to''ölö molau hadia nifoli ba wanunö — ba labe''e mandru zonoro.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 13, 'Ba dozi si so halöŵö hadia ia, ba nifomandru. Ba ba Nono Lewi andrö, ba no durutuli ösa, ba amaedola gumandru ösa ba sanaro ba mbawandruhö ösa.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 14, 'Ba me lasao''ö baero gefe andrö, si no mube''e ba gosali Yehowa, ba isöndra zura goroisa Yehowa Hilikia ere, sura khö Moze no andrö.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 15, 'Ba humede Hilikia, imane khö durutuli Safana: No usöndra zura goroisa, ba gosali Yehowa. Ba ibe''e ba danga Zafana zura andrö Hilikia.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 16, 'Ba i''ohe khö razo Safana ba i''ombakha''ö khö razo mbö''önia göi, imane: Fefu hadia ia halöŵö niŵa''öu ba genoniu, ba no lahalö.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 17, 'No lafaduwa gefe andrö, ba gosali Yehowa, ba no labe''e ba danga nifataro samaigi-maigi ba ba danga högö duka.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 18, 'Ba imane na göi khö razo Safana durutuli: No ibe''e khögu zura Hilikia ere. Ba ibaso ösa Safana, khö razo.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 19, 'Ba me irongo daroma li oroisa andrö razo, ba itika nukhania.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 20, 'Ba ibe''e li razo khö ndra Hilikia Ahikamo, ono Zafana, Abedono, ono Mikha, Safana, durutuli, Asaya, ngoni-ngoni razo, imane:', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 21, 'Mi''ae misofu khö Yehowa, ba khögu andre ba ba zi tosai na Iraono Gizeraeli ba mado Yuda, ba zura andrö nisöndra; ebua sibai sa wönu Yehowa, si no tesao khöda, me no lö ba dödö ndra tuada oroisa Yehowa, ba wolo''ö sibai mena''ö si so ba zura andrö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475155, 'OT', 'Nga''ötö II', 34, 22, 'Ba Hilikia andrö, awö nitöföi razo töi andrö, ba möi khö Huleda andrö, sama''ele''ö ira alawe, fo''omo Zalumi, samaigi-maigi nukha, ono Dokahata ono Hasera; ba Yeruzalema so nomonia, tanö si tou, ba humede ira khönia, lasofu khönia.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 23, 'Ba imane khöra: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Mimane ba niha andrö, samatenge ya''ami khögu:', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 24, 'Da''ö niŵa''ö Yehowa: Si ndruhu, famakao ufatörö ba mbanua andre, ba ba nösinia, fangelifi andrö fefu, si so ba zura andrö, nibasora khö razo mado Yuda;', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 25, 'börö me no la''erogö ndra''o, ba me no lafosumange Lowalangi bö''ö, ba wangandrö fönugu nilau dangara andrö fefu; andrö wa tesao wönugu sebua ba mbanua andre, si tebai tebato.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 26, 'Ba khö razo mado Yuda, samatenge ya''ami, ba wanofu khö Yehowa, ba mimane: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli, ba daroma li andrö, nirongou:', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 27, 'Me no ombuyu dödöu, ba me no ö''ide-ide''ö ndra''ugö föna Lowalangi, me örongo niŵa''önia nitandrösaigö ba mbanua da''e ba ba nösinia, me no ö''ide-ide''ö ndra''ugö fönagu, ba me no ötika nukhau, ba me no mege-ege''ö fönagu, ba noa göi ufondrondrongo khöu, iŵa''ö Yehowa.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 28, 'Hiza, u''orudugö ndra''ugö khö ndra amau, ena''ö te''ohe ba lewatömö ndra''ugö lö hadia ia ba ena''ö lö i''ila höröu wamakao andrö fefu, nifatörögu ba mbanua andre dania! Ba laombakha''ö khö razo.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 29, 'Ba ifatenge razo, ifakaoni''ö zatua mado Yuda ba satua mbanua Yeruzalema, fefu.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 30, 'Ba möi miyaŵa ba gosali Yehowa razo, awö ndra matua mado Yuda ba banua Yeruzalema, fefu, fabaya ere ba Ono Lewi, awö niha sato fefu, he satua, ba he iraono, ba ibaso khöra niŵa''ö ba zura wawu''usa li andrö fefu, sura nisöndra ba gosali Yehowa.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 31, 'Ba i''agö nahania razo ba fawu''u li föna Yehowa, wa edöna la''o''ö khö Yehowa, wa edöna latöngöni goroisania ba famaduhu''önia ba amakhoitania, soroi si''aikö ba dödö ba ba gera-era fefu, ba wolo''ö taroma li ba wawu''usa li andrö, si so ba zura andrö.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 32, 'Ba iŵa''ö razo latehe wawu''usa li andrö banua Yeruzalema fefu, awö mado Mbeniyami, fefu. Ba banua Yeruzalema andrö, ba labe''e dali khöra wawu''usa li andrö khö Lowalangi, Lowalangi ndra tuara.', '[]', NULL),
  (3475155, 'OT', 'Nga''ötö II', 34, 33, 'Ba ihori fefu zogoro ita Yosia, ba danö Ndraono Gizeraeli fefu, ba dozi niha ba danö Ndraono Gizeraeli, ba ifarou ba wamosumange Lowalangira Yehowa. Ba fatua lö si mate ia, ba lö laböhöli wolo''ö khö Yehowa, Lowalangi ndra tuara.', '[]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 1, 'Ba ilau wasa khö Yehowa Yosia,[1] ba Yeruzalema, lataba wasa andrö ba zi meweleöfa, ba mbaŵa si föföna.[2]', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 2, 'Ba ifataro gere andrö, ba halöŵöra, ba ifarou dödö ba halöŵöra ba gosali Yehowa.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 3, 'Ba imane ba Nono Lewi andrö, samahaö Iraono Gizeraeli fefu, ba si no mu''amoni''ö khö Yehowa: Mibe''e ba gosali dawöla ni''amoni''ö, ba gosali nilau Zelomo, ono Dawido, razo Ndraono Gizeraeli. Böi sa''ae mi''osa''osa''ö. Mi''ae sa''ae enoni Lowalangimi Yehowa ba enoni mbanuania Iraono Gizeraeli.[3]', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 4, 'Ba mifa''anö ami, ba ngafumi, ba ngenolimi, dali nifakhoi Dawido, razo Ndraono Gizeraeli, awö goroisa nononia Selomo.[4]', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 5, 'Mi''agö ni''amoni''ö, dali ngenoli ngafu niwami andrö, sato, sange-sangenoli zawu-sawu Nono Lewi.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 6, 'Ba mitaba wasa, ba mi''amoni, ba mi''asiwai ö ndra talifusömi, dali wolaumi goroisa Yehowa andrö, nifa''ema Moze.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 7, 'Ba Yosia, ba ibe''e saoha gölönia ba zato nono mbiri-biri ba ono Nambi — oi sumange fasa ba zi so andrö, 30.000 fefu — ba 3000 nga''eu zaŵi, oi okhöta razo mege.[5]', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 8, 'Ba satua mbanua andrö khönia, ba labe''e göi, saoha gölöra, ba zato ba ba gere ba ba Nono Lewi. Hilikia andrö ba Sakharia ba Yehieli, satua ba gosali Lowalangi, ba labe''e ba gere, sumange fasa, ba 2600 [nono mbiri-biri] ba 300 nga''eu zaŵi.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 9, 'Ba Khanania ba Semaya ba Netane''eli, talifusönia, ba Hasabia ba Yeieli ba Yozabada, satua Nono Lewi, ba labe''e saoha gölöra ba Nono Lewi, sumange fasa, ba 5000 [nono mbiri-biri] ba 500 nga''eu zaŵi.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 10, 'Ba no mube''e ba lala wame''e sumange andrö, ba la''agö nahara ere ba Ono Lewi, ba ngenolira, dali niŵa''ö razo.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 11, 'Ba lataba wasa, ba latema ba dangara ndro ere ba latefe nitefe, ba Ono Lewi zamo''a uli [zumange].', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 12, 'Ba la''oniagö nibe''e sumange nitunu, ba wame''e ba danga ngafu zato, ena''ö la''o''ö nifakhoi ba zura Moze, ba lamanö göi ba zaŵi andrö.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 13, 'Ba latunu ba galitö wasa andrö, dali nifakhoi, ba ame''ela ni''amoni''ö andrö, ba larino ba mbalanga ba ba mbowoa ba ba mako ba lata''i-ta''i labe''e ba niha sato fefu.[6]', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 14, 'Ba aefa da''ö, ba la''asiwai khöra, fabaya ö gere. Irugi bongi sa, ba lö aefa gere, ma''uwu Ga''aroni, ba wame''e sumange nitunu andrö, fabaya tawö andrö, andrö wa Ono Lewi zangasiwai göra ba ö gere, ma''uwu Ga''aroni.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 15, 'Ba la''iagö nahara sanunö andrö, ma''uwu Gasafo, dali nifakhoi ndra Dawido, Asafo, Hemano ba Yedutuno sangi''ila andrö khö razo, ba si manö göi zanaro ba mbawandruhö fefu. Alakha lö laböhöi halöŵö, me no iwara andrö, Ono Lewi zangasiwai göra.[7]', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 16, 'Ba tobali no mube''e ba lala wamosumange Yehowa andrö fefu, me luo da''ö lalau wasa andrö ba labe''e zumange nitunu ba naha wame''e sumange andrö khö Yehowa, dali nifakhoi razo Yosia.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 17, 'Tobali lalau wasa Iraono Gizeraeli, si so andrö, me luo da''ö, fabaya owasa roti si lö mu''aisöni, fitu ngaluo wa''ara.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 18, 'Ba lö murai mulau wasa si manö, i''otarai luo Zamueli sama''ele''ö, samösa lö razo Ndraono Gizeraeli mege, solau fasa, si mane nilau Yosia ba ere andrö ba Ono Lewi, awö mado Yuda, awö Ndraono Gizeraeli fefu, si so andrö, ba banua Yeruzalema.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 19, 'Me no alua mewelewitu fakhe razo Yosia telau wasa andrö.', '["Faigi göi RazII 23:21–30","MozII 12:6","Nga''ötI 23:26","Nga''ötI 24","Faigi 30:24","MozII 12:8","Nga''ötI 16:7"]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 20, 'Ba me aefa da''ö fefu — me no ifuli i''azökhi gosali Yosia — ba so moroi si tou Nekho, razo Miserayi, ba wanuwö ba Garikemi, ba mbewe Oifarati. Ba ifaondragö ia Yosia.', '[]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 21, 'Ba ifatenge zinenge khönia Nekho, imane: Hadia horögu khöu, ya''ugö razo mado Yuda? Tenga ya''ugö usuwö iada''e, udugu usuwö, ba no ifangaösö ndra''o Lowalangi. Böi laŵa Lowalangi andrö, si oawögö ya''o, fa böi ifakiko ndra''ugö!', '[]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 22, 'Ba lö iböhöli ia Yosia, noa sa ihonogöi sibai, ilau khönia. Andrö wa lö ifondrondrongo li Nekho andrö, niŵa''ö Lowalangi, ifaondragö, ba wolau ba ndraso andrö ba Megido.', '[]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 23, 'Ba lafana razo Yosia si fafana. Ba imane razo khö genoninia: Mi''ohe misa ndra''o, noa sa mesokho ndra''o, sokho sebua!', '[]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 24, 'Ba laheta ia ba gureta [zanuwö] enoninia, labe''e ba guretania si sambua, ba me no larugi Yeruzalema, ba mate ia, ba ba lewatö ndra amania lako''o ia. Ba la''e''esi Yosia mado Yuda ba banua Yeruzalema fefu.', '[]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 25, 'Ba ilau ngenu-ngenu Yeremia ba khö Yosia andrö, ba dozi sanunö, he ira matua, ba he ira alawe, ba itörö lira Yosia ba ngenu-ngenura andrö, irugi ma''ökhö andre. Ba labali''ö huku ba Ndraono Gizeraeli da''ö, ba no mutanö ba zura, ba zura ngenu-ngenu andrö.', '[]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 26, 'Ba bö''önia hikaya Yosia ba hadia nilaunia si sökhi, wolo''ö nifakhoi ba goroisa,', '[]', NULL),
  (3475156, 'OT', 'Nga''ötö II', 35, 27, 'he hikayania famobörö mege, ba he safuria andrö, ba no mutanö ba zura razo Ndraono Gizeraeli ba ba zura razo mado Yuda.', '[]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 1, 'Ba lahalö Yoahasi andrö,[1] ono Yosia, niha ba danö, ba labali''ö razo ba Yeruzalema, fangali namania.', '["Faigi göi RazII 23:30–25:21"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 2, 'Dua wulu a tölu fakhe Yoahasi, me tobali razo ia, ba ha tölu waŵa razo ia ba Yeruzalema.', '["Faigi göi RazII 23:30–25:21"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 3, 'Ba iheta ia razo razo Miserayi, ba tenga sa''ae razo ia ba Yeruzalema. Ba ifo''ömö ira ba danö [razo Miserayi], 22.050 balaki wirö ba 3970 1/2 balaki gana''a.', '["Faigi göi RazII 23:30–25:21"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 4, 'Ba razo Miserayi andrö, ba ibali''ö razo ba mado Yuda ba ba Yeruzalema Geliaki, ga''a Yoahasi, ba ifalalini döinia, Yoyaki ibe''e töinia. Ba akhininia Yoahasi andrö, ba i''ohe ba danö Miserayi [Fara''o] Nekho.', '["Faigi göi RazII 23:30–25:21"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 5, 'Dua wulu a lima fakhe Yoyaki, me tobali razo ia, ba mewelezara fakhe razo ia ba Yeruzalema. Ba si fatuwu khö Lowalanginia Yehowa ilau.', '["RazII 24:1; Yer 22:18"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 6, 'Ba so moroi si tou Nebukanesa, razo Mbabeli, ba wanuwö ya''ia, ba irate ia, ba wolohe ba Mbabeli.[2]', '["RazII 24:1; Yer 22:18"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 7, 'Ba he gama-gama ba gosali Yehowa ösa, ba i''ohe ba Mbabeli Nebukanesa, ba ibe''e ba gödonia ba Mbabeli.', '["RazII 24:1; Yer 22:18"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 8, 'Ba bö''önia hikaya Yoyaki ba adu andrö khönia, sogoro ita, nifafazökhi''önia, ba hadia ia na [zi lö sökhi] khönia, ba no mutanö ba zura razo Ndraono Gizeraeli ba ba zura razo mado Yuda. Ba fangalinia razo, ba ononia Yoyakhi.', '["RazII 24:1; Yer 22:18"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 9, 'Ha meŵalu fakhe Yoyakhi, me tobali razo ia, ba ha tölu waŵa a fulu bongi razo ia ba Yeruzalema. Ba si fatuwu khö Yehowa ilau.[3]', '["RazII 24:8 b.t.","Yer 37:1; Dan 1:2"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 10, 'Ba me no alua ndröfi, ba ifahalö''ö ia Nebukanesa, ifa''ohe''ö ba Mbabeli, fabaya gama-gama andrö, sebua böli, ba gosali Yehowa, ba Sedekia, ama Yoyakhi si akhi ibali''ö razo mado Yuda ba razo Yeruzalema.[4]', '["RazII 24:8 b.t.","Yer 37:1; Dan 1:2"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 11, 'Dua wulu a sara fakhe Zedekia, me tobali razo ia, ba mewelezara fakhe razo ia ba Yeruzalema.[5]', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 12, 'Ba si fatuwu khö Lowalanginia Yehowa ilau; lö i''ide-ide''ö ia khö Yeremia andrö, sama''ema khönia niŵa''ö Yehowa.', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 13, 'Ba lö''ö göi i''o''ö khö razo Nebukanesa, si no mame''e ba hölu ya''ia khö Lowalangi; i''abe''e''ö dandronia ba tödönia, ba tobali lö ifuli ia khö Yehowa, Lowalangi Ndraono Gizeraeli.', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 14, 'Ba he satua gere ba he niha sato, ba no ebua sibai walimosa, wangohia''ö sogoro ita andrö, ba niha baero, ba la''ohe ba gosali Yehowa zalakha, ba gosali ni''amoni''ö Yehowa, ba Yeruzalema.', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 15, 'Ba lö adage-dage Yehowa, Lowalangi ndra tuara, lö ibato wamatenge khöra sinengenia; me no ahakhö dödönia mbunuania ba he nahiania andrö.[6]', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 16, 'Ba la''o''aya zinenge Lowalangi andrö, lö ba dödöra linia, ba la''igi''igi''ö zama''ele''ö andrö, irege ebua sibai wönu Yehowa, irege lö fangorifi sa''ae.', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 17, 'Ba i''ohe khöra razo Ndrawa Galedaia, ifabunu''ö si''öli nono matua khöra, bakha ba ni''amoni''ö andrö khöra; lö ihakhösi tödö, he ono matua, ba he ono alawe, ba he satua, he si no tohare huwa, — ahori manö ibe''e ba dangania.', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 18, 'Ba he gama-gama andrö ba gosali Lowalangi, he side-ide, ba he sebua, fabaya girö-girö andrö ba gosali Yehowa ba girö-girö khö razo ba girö-girö zatua mbanua khönia — ba ahori i''ohe ba Mbabeli.[7]', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 19, 'Latunu gosali Yehowa, ba ladudugö göli Yeruzalema, awö gödo khöra fefu, ba latunu, tobali ahori akhozi gama-gamara sebua böli.', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 20, 'Ba si lö ikhamö bawa zi''öli, ba i''ohe ba Mbabeli [razo Mbabeli] i''oloi''ö, ba tobali enoninia ira ba enoni ndraononia, irege labe''e barö mbawara ira Dawa Weresia, ena''ö itörö niŵa''ö Yehowa,', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 21, 'nifa''ema Yeremia, "irege te''ali ba danö ndröfi wolombase andrö; solombase manö ia, götö wa no amaedola danö si mate ia," irege alua zi 70 fakhe.[8]', '["RazII 24:18 b.t. Yer 52:1","Yer 25:4","RazII 20:17","MozIII 26:34; Yer 25:11"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 22, 'Ba me awena razo Giro andrö, razo Weresia — lö döfi na — ena''ö itörö li Yehowa andrö, nifa''ema Yeremia — ba ibe''e ba dödö Giro andrö, razo Weresia, Yehowa wame''e oroisa ba mbanuania fefu — nifa''ohe''ö sura göi — imane:[9]', '["Yer 29:10"]', NULL),
  (3475157, 'OT', 'Nga''ötö II', 36, 23, 'Da''e niŵa''ö Giro, razo Weresia: "Fefu gamatöröŵa ba guli danö, ba no ibe''e khögu Yehowa, Lowalangi zorugo, ba ya''ia zanguma''ö khögu wolau osali khönia ba Yeruzalema ba danö mado Yuda. Ba ha niha ami mbanuania, ba yamutolo ia Lowalanginia, ba yamöi misi yaŵa!"', '["Yer 29:10"]', NULL),
  (3448040, 'OT', 'Esera', 1, 1, 'Ba me awena razo Giro andrö, razo Weresia — lö döfi na — ena''ö itörö li Yehowa andrö, nifa''ema Yeremia — ba ibe''e ba dödö Giro, razo Weresia, Yehowa wame''e oroisa ba mbanuania fefu—nifa''ohe''ö sura göi—imane: [1]', '["Nga''ötII 36:22-23; Yer 29:10"]', NULL),
  (3448040, 'OT', 'Esera', 1, 2, 'Da''e niŵa''ö Giro, razo Weresia: Fefu gamatöröŵa ba guli danö, ba no ibe''e khögu Yehowa, Lowalangi zorugo, ba ya''ia zanguma''ö khögu wolau osali khönia ba Yeruzalema ba danö mado Yuda.', '[]', NULL),
  (3448040, 'OT', 'Esera', 1, 3, 'Ba ha niha ba khömi mbanuania, ba yamutolo ia Lowalanginia, ba yamöi misi yaŵa ba Yeruzalema ba yamulau gosali andrö khö Yehowa, Lowalangi Ndraono Gizeraeli; da''ö Lowalangi andrö, ba Yeruzalema.', '[]', NULL),
  (3448040, 'OT', 'Esera', 1, 4, 'Ba ha niha zi tosai na, ba mbanua heza, fefu, si fatewu ia, ba ndramutolo ia banuara, firö ba ana''a ba balazo ba urifö, lö lai nibe''e saoha gölö, balazo gosali Lowalangi andrö, ba Yeruzalema.', '[]', NULL),
  (3448040, 'OT', 'Esera', 1, 5, 'Ba maoso zatua ngafōē mado Yuda ba mado Mbeniyami ba ere ba Ono Lewi — dozi nibe''e Lowalangi ba dödö fe''amöi misi yaŵa, ba wolau osali Yehowa ba Yeruzalema.', '[]', NULL),
  (3448040, 'OT', 'Esera', 1, 6, 'Ba dozi niha si so ba ngaira, ba latolo ira gama-gama firö ba ana''a ba balazo ba urifö ba aya, lö lai fefu hadia ia nibe''e saoha gölö.', '[]', NULL),
  (3448040, 'OT', 'Esera', 1, 7, 'Ba razo Kiro, ba ibe''e baero gama-gama andrö ba gosali Yehowa, ni''oloi''ö Nebukanesa mege, nihalö ba Yeruzalema, nibe''enia ba gosali Lowalanginia. [2]', '["Nga''ötII 36:7-18"]', NULL),
  (3448040, 'OT', 'Esera', 1, 8, 'Da''ö nibe''e Giro, razo Weresia, ba danga Miteredata sangirö ana''a, ba da''ö zangofaya khö zalaŵa mado Yuda Sesibasa [Serubabeli]. [3]', '["Faigi 3:2"]', NULL),
  (3448040, 'OT', 'Esera', 1, 9, 'Ba da''e wa''oya: 30 wiga ana''a ba 1.000 wiga firö ba 29 gali', '[]', NULL),
  (3448040, 'OT', 'Esera', 1, 10, 'ba 30 mako ana''a, ba 410 mako firö, ba 1.000 ngawua gama-gama bö''ö,', '[]', NULL),
  (3448040, 'OT', 'Esera', 1, 11, '— oruduania ba no 5400 ngawua gama-gama ana''a ba gama-gama firö. Da''ö fefu ni''ohe Zesibasa misi yaŵa, me te''ohe mangawuli ba Yeruzalema ni''oloi''ö andrö, moroi ba Mbabali.', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 1, 'Ba da''e mbanua ba danö [mado Yuda] sangawuli misi yaŵa ba Yeruzalema ba ba danö mado Yuda, nitaha mege, ni''oloi''ö Nebukanesa, razo Mbabeli, ba Mbabeli; — ifuli ia ba mbanuara zamösana —,', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 2, 'si fao khö ndra Serubabeli, Yesua, Nehemia, Seraya, Re''elia, Morodokhai, Bilisana, Misifari, Bigewai, Rehumi, Ba''ana. Ba fa''ato ndra matua Ndraono Gizeraeli, andrö, ba [2]', '["F. 1, 8. A. 63"]', NULL),
  (3448042, 'OT', 'Esera', 2, 3, 'Ma''uwu Wareo, ba 2172, ba', '["F. 1, 8. A. 63"]', NULL),
  (3448042, 'OT', 'Esera', 2, 4, 'Ma''uwu Zefatia, ba 372, ba', '[]', NULL),
