  (3448042, 'OT', 'Esera', 2, 19, 'Ma''uwu Hasumi, ba 223, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 20, 'Banua Gibeona ba 95, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 21, 'Banua Mbetilekhema, ba 123, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 22, 'Banua Netofa, ba 56, ba', '[]', NULL),
