INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3448042, 'OT', 'Esera', 2, 28, 'Banua Mbetieli ba banua Ga''i, ba 223, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 29, 'Banua Nebo, ba 52, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 30, 'Ma''uwu Magibi, ba 156, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 31, 'Ma''uwu Gelama si samösa, ba 1254 ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 32, 'Ma''uwu Harimi, ba 320, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 33, 'Banua Lodo ba banua Hadidi ba banua Gono, ba 725, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 34, 'Banua Yerikho, ba 345, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 35, 'Banua Zena''a, ba 3630, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 36, 'Ere andrö: Ma''uwu Yedaya, si sawu ndra Yesua, ba 973, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 37, 'Ma''uwu Gimeri, ba 1052, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 38, 'Ma''uwu Wasuri, 1247, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 39, 'Ma''uwu Harimi, ba 1017, ba', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 40, 'Ono Lewi andrö: mu''uwu Yesua ba ma''uwu Gadimi''eli, nga''ötö Hodawia, ba 74,', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 41, 'ba Sanunö andrö:', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 42, 'Ma''uwu Gasafo, ba 128, ba ma''uwu zanaro ba mbawandruhö: ma''uwu Zalumi ba ma''uwu Gateri ba ma''uwu Dalamono ba ma''uwu Akubi, ba ma''uwu Hatita ba ma''uwu Zobai, 139 fefu. [3]', '["Nga''ötI 9:2"]', NULL),
  (3448042, 'OT', 'Esera', 2, 43, 'Ba sangai halöŵö ba gosali, enoni andrö: ma''uwu Ziha ba ma''uwu Hasufa ba ma''uwu Daba''oti,', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 44, 'ba ma''uwu Gero, ba ma''uwu Zi''eha ba ma''uwu Wadona,', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 45, 'ba ma''uwu Lebana ba ma''uwu Hagaba ba ma''uwu Akubi', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 46, 'ba ma''uwu Hagabi ba ma''uwu Zalamai ba ma''uwu Hanani', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 47, 'ba ma''uwu Gideli ba ma''uwu Gaharo ba ma''uwu Reaya', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 48, 'ba ma''uwu Resino ba ma''uwu Nekoda ba ma''uwu Gasama', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 49, 'ba ma''uwu Usa ba ma''uwu Wasea ba ma''uwu Mbezai', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 50, 'ba ma''uwu Gasena ba ma''uwu Moini ba ma''uwu Nefisi', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 51, 'ba ma''uwu Mbakibuku ba ma''uwu Hakufa ba ma''uwu Harihuru', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 52, 'ba ma''uwu Mbaseluti ba ma''uwu Mehida ba ma''uwu Haresa', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 53, 'ba ma''uwu Mbarako ba ma''uwu Zisera ba ma''uwu Dema', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 54, 'ba ma''uwu Nesia ba ma''uwu Hatifa.', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 55, 'Ba ma''uwu zawuyu Zelomo andrö: ma''uwu Zota''i ba ma''uwu Zofereti ba ma''uwu Weruda [4]', '["RazI 9, 21"]', NULL),
  (3448042, 'OT', 'Esera', 2, 56, 'ba ma''uwu Ya''ela ba ma''uwu Darikono ba ma''uwu Gideli,', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 57, 'ba ma''uwu Zefatia ba ma''uwu Hatili ba ma''uwu Wokhereti-Hasebaima ba ma''uwu Gami,', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 58, 'sangai halöŵö ba gosali ba ma''uwu zawuyu Zelomo, fefu, ba no 392.', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 59, 'Ba da''e zi fao misi yaŵa, banua Deli-Mela ba Teli-Haresa ba Kherubi ba Adana ba Imeri, si lö mangila manutunö ha nga''ötö ira, ha niha duara, na Iraono Gizeraeli ira, ba na tenga:', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 60, 'ma''uwu Delaya ba ma''uwu Dobia ba ma''uwu Nekoda, 652 fefu.', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 61, 'Ba ma''uwu Gera andrö, ösa: ma''uwu Habaya ba ma''uwu Hakosi ba ma''uwu Mbarasilai andrö, si no mangai ono Mbarasilai, banua Gileadi ba nibe''e töi töi matuania andrö. [5].', '["SamII 19, 31"]', NULL),
  (3448042, 'OT', 'Esera', 2, 62, 'La''alu-alui zura nga''ötö khöra, ba lö lasöndra, andrö wa lö lafa''amöi ere ira.', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 63, 'Ba itenaŵa ira kumandru ba wemanga ni''amoni''ö sibai andrö, irege so gere solau "Urimi" ba "Tumimi" andrö. [6].', '["MozIV 27, 21. MozII 28, 30. MozV 33, 8. A. 2"]', NULL),
  (3448042, 'OT', 'Esera', 2, 64, 'Ba ya''ira fefu, ba no 42,360 niha,', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 65, 'lö lai zawuyu, ira matua ba ira alawe, 7337 da''ö; ba baero ö na, ba 200 zanunö, ira matua ba ira alawe.', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 66, 'Ba kudo khöra, ba 736, ba kudo kalide, ba 245,', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 67, 'ba ondra, ba 435, ba kalide, ba 6720.', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 68, 'Ba so ösa högö ngafu andrö, same''e saoha gölöra, balazo gosali Lowalangi, me no larugi naha gosali ba Yeruzalema, ba wolau ya''ia zui ba nahania andrö.', '[]', NULL),
  (3448042, 'OT', 'Esera', 2, 69, 'Dali wa''ebua gana''ara ba wame''e balazo gosali andrö: ana''a, ba 61,000 hua balaki, ba firö, ba 18.382 balaki, ba 100 nga''örö mbaru gere. [7].', '["RazI 10, 17. Nga''ötI 29, 7"]', NULL),
  (3448042, 'OT', 'Esera', 2, 70, 'Ba ere ba Ono Lewi ba niha sato ösa ba sanaro ba mbawandruhö ba sangai halöŵö ba gosali, enoni andrö, ba la''iagö mbanuara; ba Iraono Gizeraeli fefu, ba ba mbanuara so.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 1, 'Ba me aefa da''ö, ba ibali''ö salaŵa Hamano razo Ahasiwero, Hamano ono Hamedata, ma''uwu Agagi, i''ebua''ö, ba yaŵa dadaoma zalaŵa bö''ö fefu ba ngainia ibe''e dadaomania.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 2, 'Ba dozi enoni razo, si so ba gödo khö razo, ba latuhi danö ba lafalögu tou ira föna Hamano, me no oroisa razo da''ö ba khönia. Ba Morodokhai, ba lö ituhi danö ba lö ifalögu tou ia.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 3, 'Ba lamane enoni razo, si so ba gödo khönia, khö Morodokhai: Hana wa ösawö goroisa razo?', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 4, 'Ba ero ma''ökhö lamanö khönia, ba lö ifondrondrongo, ba la''ombakha''ö khö Hamano, ba wamaigi, na lö te''ala Morodokhai; noa sa i''ombakha''ö khöra, wa niha Yehuda ia.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 5, 'Ba me i''ila Hamano, lö ituhi danö fönania Morodokhai ba lö ifalögu tou ia, ba mofönu sibai ia.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 6, 'Ba faya-faya iŵa''ö tödönia, na ha samösa Morodokhai ibunu; me no la''ombakha''ö khönia ha soi Morodokhai, ba i''alui lala Hamano, ba wangohori niha Yehuda, iwa Morodokhai, fefu; ba danö Ahasiwero, ma''asagörö.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 7, 'Ba ba mbaŵa si föföna — baŵa Nisana —, me no alua mewelezara fakhe razo Ahasiwero, ba lalau "wuri" — dahö-dahö — föna Hamano, la''erogö ma''ökhö ba la''erogö baŵa, ba göna ba zi meweledölu ba mbaŵa si felendrua — baŵa Adara.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 8, 'Ba imane Hamano khö razo Ahasiwero: So soi sambua, si no muzaewe ba niha bö''ö, ba danö fefu, barö mbawau ba si no tonia; huku khöra, ba no faehu ba huku niha bö''ö fefu, ba oroisa razo, ba lö la''o''ö, ba no tenga si nangea, itehe manö khöra da''ö razo.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 9, 'Ba na atulö khö razo, ba nibe''e sura, ba wangohori ya''ira, ba ube''e ba danga ndra tua kumandru wirö, 44,120,000 ba rufia, ena''ö labe''e ba nahia girö-girö khö razo.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 10, 'Ba isöbi ba durunia laeduru razo, laeduru si so tandro, ba ibe''e khö Hamano andrö, ono Hamedata, ma''uwu Agagi, udu niha Yehuda. [1]', '["MozI 41: 42; F. 8:2"]', NULL),
  (3448043, 'OT', 'Esera', 3, 11, 'Ba imane razo khö Hamano: Firö andrö, ba khöu labe''e, ba ba niha andrö, ba lau zomasi''ö.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 12, 'Ba humede ira ba durutuli razo ba zi meweledölu ba mbaŵa si föföna; ba latörö sibai nihonogöi Hamano, wama''ohe''ö sura ba nifataro razo ba ba gumandru ba zi sagö-sagörö tanö, ba ba zalaŵa soi niha misa, dali wanura khöra ba danöra ba he li soi andrö misa. Töi razo Ahasiwero nibe''e ba zura goroisa andrö, ba lafotandro tandro ba laeduru andrö, khö razo.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 13, 'Ba ladozigö tanö barö mbawa razo, wama''ohe''ö sura andrö ba zinenge si fagohi, ba wangohori niha Yehuda, ba wamakiko, ba wamunu, he iraono ba he satua, ba iraono sawuyu ba ira alawe, ha ma''öma''ökhö, ba zi meweledölu ba mbaŵa si felendrua — baŵa Adara —, ba ba worabu zi so khöra, amaedola zi lö sokhö.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 14, 'Ba da''ö niŵa''ö ba zura andrö: ladozigö tanö wame''e oroisa, ena''ö dozi niha zamondrongo, ba ena''ö no te''anö ira, na irugi baŵa da''ö.', '[]', NULL),
  (3448043, 'OT', 'Esera', 3, 15, 'Ba la''aliogö sinenge andrö, si fagohi, la''o''ö niŵa''ö razo, me ha si''aikö tebe''e goroisa andrö, ba gödo, ba Zusa. Ba mudadao manga razo, awö Hamano; ba banua Zusa, ba si tobali tödö.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 1, 'Ba me larongo udu mado Yuda ba udu mado Mbeniyami lalau gosali khö Yehowa, Lowalangi Ndraono Gizara''eli sangawuli andrö moroi ba ni''oloi''ö ya''ira,', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 2, 'ba möi ira khö Zerubabeli ba ba högö ngafu andrö, ba lamane khöra: Damalului wolau; sangalui Lowalangimi sa ndra''aga göi, si mane ya''ami, ba khönia mabe''e-be''e zumange, i''otarai luo Gasarabado andrö, razo Asiria, solohe ya''aga ba da''e. [1]', '["RazII 17: 34 b.t."]', NULL),
  (3448044, 'OT', 'Esera', 4, 3, 'Ba lamane khöra ira Serubabeli Yesua, awö högö ngafu Ndraono Gizeraeli bö''ö andrö: Tenga awöma ami, fa ta''orudugö ita ba wolau osali khö Lowalangida, ya''aga manö zolau khö Yehowa, Lowalangi Ndraono Gizeraeli, ha ya''aga, dali goroisa Giro, razo Weresia.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 4, 'Ba adada zui danga mado Yuda labe''e niha ba danö andrö, latenaŵa ira ba wotomo andrö, lasölö niha,', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 5, 'samo''esuanö ya''ira, fa böi lafalua zi so ba dödöra, götö wa''ara Giro andrö, razo Weresia, ba irege razo Dario, razo Weresia.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 6, 'Ba me razo Ahasiwero, me awena tobali razo ia, ba lafa''ohe''ö zura wangadu, la adugö mbanua mado Yuda ba banua Yeruzalema.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 7, 'Ba me razo Aretazasa, ba lafa''ohe''ö zura ira Biselama, Miteredata, Tabe''eli, ba awöra, khö Aretazasa andrö, razo Weresia, Nisura ba li Ndrawa Garamo zura andrö ba ni''ali. Ba li Ndrawa Garamo:', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 8, 'Rehumi kumandru ba Simisai durutuli zama''ohe''ö sura khö razo Aretazasa, fangombakha banua Yeruzalema andrö, lamane:', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 9, '"Rehumi no, kumandru ba Simisai, durutuli, ba awöra bö''ö andrö, banua Dina ba banua Yafarasatekha ba banua Darafela ba banua Gafarasa ba banua Garakhi ba banua Mbabilona ba banua Zusa ba banua Deha ba banua Gelama, ba soi bö''ö andrö,', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 10, 'nifawu''a Gasanafari andrö sebua ba sihöngö turia, ni''ohenia ba mbanua Zamaria ba ba danö bö''ö misa, yefo Oifarati tanö andre, ba tohu-tohunia.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 11, 'Da''e nösi zura andrö, nifa''ohe''öra khö razo Aretazasa: "Enoniu andre, banua si yefo Oifarati tanö andre, ba tohu-tohunia.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 12, 'Böi zi lö irongo razo, wa no larugi ndra''aga, ba Yeruzalema, niha Yehuda andrö, si no so moroi si tou khöu. Labörö-börötaigö lafuli lataru''ö mbanua si lö sökhi andrö, banua zolaŵa-laŵa; la''asiwai göli ba lafuli lahaogö dayadaya.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 13, 'Ba böi zi lö aboto ba dödö razo: na no mufuli mutaru''ö mbanua andrö dania ba na no awai göli, ba lö''ö sa''ae labe''e mbeo ba hua zago; ba rodi lala, ba lö''ö sa''ae la o''ö, ba tobali te''ambösi zinema razo labe''e.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 14, 'Ba me no si manga-manga nasio ba gödo razo ndra''aga ba me tebai mafaigi-faigi na te''ala razo, andrö wa mafatenge, ba wangombakha da''ö khö razo,', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 15, 'ena''ö la''alu-alui ba zura hikaya ndra tuau andrö; ba ösöndra dania ba zura hikaya andrö ba aboto ba dödöu, wa no banua solaŵa-laŵa mbanua andrö, banua samakao razo ba he niha ba danö, baero, misa, awö wa no götö-götö wa''ara lafobörö wolaŵa; ba da''ö göi mbörö, wa no mududugö mbanua andrö.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 16, 'Andrö böi zi lö aboto ba dödöu: na lafuli lataru''ö mbanua andrö, ba na no awai göli dania, ba tobali börö da''ö, wa latimba manö ndra''ugö dania yefo Oifarati, tanö andre."', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 17, 'Ba ifa''ohe''ö zura razo, fanema li ndra Rehumi kumandru, Simisai, durutuli, ba awöra bö''ö andrö, ba Zamaria ba ba danö yefo Oifarati, imane: "Ya ahowu! ba tohu-tohunia.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 18, 'Sura andrö, nifa''ohe''ömi ehöma, ba no lahaogö wombaso khögu.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 19, 'Ba no ube''e goroisa, ba no la''alui, ba no lasöndra, wa no samadaö li razo mbanua andrö, i''otarai götö föna sibai sa''ae, wa no tesaosao manö ba da''ö wolaŵa ba fa''erosa.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 20, 'Ba no razo sabölö mege razo Yeruzalema andrö, ba no labe''e barö mbawara danö andrö fefu, yefo Oifarati, ba no la''o''ö khöra ba mbeo ba ba hua zago ba ba rodi lala.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 21, 'Ba niŵa''ö sa''ae, labato halöŵöra niha andrö, fa böi lafuli lataru''ö mbanua andrö, irege ya''odo zanguma''ö.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 22, 'Ba mifaigi-faigi, fa böi arörö ami, fa böi tumbu ba da''ö de''ala sebua, fa''ate''ala razo!"', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 23, 'Ba me no mubaso zura andrö, nifa''ohe''ö razo Aretazasa, khö Rehumi ba khö Zimisai durutuli ba ba nawöra bö''ö andrö, ba lata''i-ta''i we''amöi ba niha Yehuda, ba Yeruzalema, ba latenaŵa ira, la''anösö''ö.', '[]', NULL),
  (3448044, 'OT', 'Esera', 4, 24, 'Ba tebato halöŵö ba gosali Lowalangi, ba Yeruzalema, me luo da''ö, lö latohugö, irege no alua döfi razo Dario andrö, razo Weresia.', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 1, 'Ba mama''ele''ö ndra Haga''i Sakharia ono Ido, sama''ele''ö andrö, li Lowalangi Ndraono Gizeraeli, si so yaŵara, lafa''ema ba niha Yehuda ba danö mado Yuda ba ba Yeruzalema. [1]', '["Hag 1:1; Sakh 1:1"]', NULL),
  (3448045, 'OT', 'Esera', 5, 2, 'Ba maoso ndra Serubabeli, ono Zelatieli, Yesua, ono Yosadaki, labörötaigö wolau osali Lowalangi ba Yeruzalema, ba awöra zama''ele''ö andrö khö Lowalangi, latolo ira.', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 3, 'Ba me luo da''ö, ba möi khöra Datenai, kumandru ba danö yefo Oifarati, tanö andre, ba Sitara-Bosinai ba awöra, ba lamane khöra: Ha niha zanehe khömi folau osali andre, awö wangasiwai öli kara andrö?', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 4, 'Ba lamane na göi: Ha niha döi niha andrö, sotomo?', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 5, 'Ba ihörö-hörögö wolau niha Yehuda andrö Lowalangira, ba tobali tebai latenaŵa ira, irege no irongo huhuo andrö Dario, ba irege ifa''ohe''ö khöra zura, hadia niŵa''önia.', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 6, 'Da''e zura andrö, nifa''ohe''ö Datenai, kumandru ba danö yefo Oifarati tanö andre ba Sitara-Bosinai ba awönia andrö, banua Gafarasekhi, si so ba danö yefo Oifarati tanö andre, nifa''ohe''ö khö razo Dario—fangombakha khönia,', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 7, 'lamane ba zura andrö —: "Khö razo Dario, ya ahowu!', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 8, 'Böi zi lö irongo, razo, wa no möiga ba danö mado Yuda, ba gosali Lowalangi sebua andrö; la''otomosi gosali andrö, kara sebua, kara nitoto, ba lahare''ö yaŵa mbuatö: owölö-ölö sibai ira ba halöŵö andrö ba alio tedou ba dangara.', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 9, 'Ba no masofu ba zatuara, no mamane khöra: Ha niha zanehe khömi folau osali andre, awö wangasiwai öli kara andrö?', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 10, 'Ba he töira göi, ba no masofu khöra, ba wangombakha khöu, ba no mabe''e ba zura khöu döi högöra andrö.', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 11, 'Ba no lamane wangombakha khöma: Enoni Lowalangi andrö ndra''aga, si no Lowalangi zorugo ba Lowalangi danö, ba mafuli malau gosali andrö, si no mulau föna, ha uga götö niha fönama, me ilau razo Ndraono Gizeraeli, sebua, ba me i''asiwai. [2]', '["RazI 6:1"]', NULL),
  (3448045, 'OT', 'Esera', 5, 12, 'Ba me no la''andrö wönu Lowalangi zorugo andrö ira tuama, ba ibe''e ira ba danga Nebukanesa, razo Mbabeli, Dawa Galedaia; da''ö zanudugö osali andrö ba sangoloi''ö niha ba Mbabeli. [3]', '["RazII 24:10 b.t."]', NULL),
  (3448045, 'OT', 'Esera', 5, 13, 'Ba me awena razo Giro andrö, razo Mbabeli, me lö döfi na, ba itehe razo Kiro andrö lafuli lalau gosali Lowalangi andre. [4]', '["F. 1:1"]', NULL),
  (3448045, 'OT', 'Esera', 5, 14, 'Ba he gama-gama andrö, ba gosali Lowalangi, ana''a ba firö, ni''oloi''ö Nebukanesa moroi ba gosali ba Yeruzalema, nibe''enia ba gosali ba Mbabeli, ibe''e baero razo Kiro, ihalö ba gosali ba Mbabeli, ba tebe''e ba danga nifataronia kumandru andrö, Sesibasa döinia.', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 15, 'Ba ibe''e li khönia, imane: ''Halö gama-gama andre, ba ae''e, ba be''e ba gosali ba Yeruzalema; ba lafuli lalau gosali Lowalangi ba nahania föna.''', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 16, 'Ba möi Zesibasa andrö, ibe''e tou doyo gosali Lowalangi, ba Yeruzalema, ba i''otarai luo da''ö, ba la''otomo-tomosi ia, ba lö sawai na.', '[]', NULL),
  (3448045, 'OT', 'Esera', 5, 17, 'Ba iya''e, ba na omasi razo, ba ndra mu''alu-alui ba nomo girö-girö andrö, khö razo, ba da''ö, ba Mbabeli, na si ndruhu si manö, na no itehe razo Kiro, lalau gosali Lowalangi andrö, ba Yeruzalema; ba yamufarongogö khöma dödönia ba huhuo andrö."', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 1, 'Ba ibe''e li razo Dario ena''ö la''alui ba naha zura andrö, ba ni''irö''ö göi girö-girö ba Mbabeli.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3448046, 'OT', 'Esera', 6, 2, 'Ba lasöndra zura ba gödo ba Gameta, ba danö Media, mane nösinia:', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 3, '"Nitanö ba dödö: Me awena razo Giro, me lö döfi na, ba ibe''e goroisa, imane: ''Osali andrö ba Yeruzalema, — lafuli lalau gosali andrö, naha ba nibe''e-be''e sumange, Toyonia ba böi mangiwa. Fa''alaŵania, ba 60 hela, ba fa''ebolonia, ba 60 hela göi:', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 4, 'Tölu winaeta gara sebua, kara nitoto, ba sawinaeta geu balo, ba balazonia, ba ba gödo razo lahalö.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 5, 'Ba nifuli göi gama-gama andrö ba gosali Lowalangi, ana''a ba firö, ni''oloi''ö Nebukanesa moroi ba gosali ba Yeruzalema, ni''ohenia ba Mbabeli, ena''ö ba nahania ba gosali ba Yeruzalema labe''e fefu; ba gosali Lowalangi öbe''e''.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 6, 'Ba böi mihatö''ö ami khöra — ya''ugö Tatenai, kumandru ba danö yefo Oifarati, ba ya''ugö Sitara-Bosinai ba awömi andrö, banua Gafarasekhi, ba danö yefo Oifarati.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 7, 'Böi mitenaŵa halöŵö ba gosali Lowalangi andrö; alakha lafuli lalau gosali Lowalangi andrö, ba nahania föna, kumandru niha Yehuda andrö ba satua niha Yehuda.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 8, 'Ba no ube''e li ba nibe''e ba zatua niha Yehuda andrö, ba wolau osali Lowalangi andrö. Ahori la''ali khöra mbalazo andrö; sinema razo, beo andrö ba danö yefo Oifarati labe''e, ba böi sarörö!', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 9, 'Ba hadia zoguna, he ono saŵi si matua, ba he biri-biri si matua ba ono mbiri-biri, sumange nitunu khö Lowalangi zorugo, ba gandru ba asio ba agu ba fanikha, ba tenga ni''ambösi wame''e khöra, ero ma''ökhö, dali niŵa''ö gere andrö, ba Yeruzalema,', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 10, 'ena''ö labe''e khö Lowalangi zorugo zumange samohua, ba ena''ö la''andrö wa''anau noso razo ba fa''anau noso nga''ötönia.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 11, 'Ba no ube''e li: na so zowu''ai oroisa andrö, ba ladeha zara mbuatö ba nomonia ba laforöfa ia ba mbuatö andrö, ba omonia, ba labali''ö oboula fangatabö zinanö, börö da''ö.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 12, 'Ba Lowalangi andrö, samonahia töinia ba da''ö, ba yamutimba zalaŵa fefu, awö soi fefu, sangoro''ö tangara, ba wowu''ai, ba ma ba wanudugö osali Lowalangi andrö, ba Yeruzalema; Ya''odo andre, Dario, zame''e oroisa andre, ba nihaogö famalua."', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 13, 'Ba la''o''ö sibai sa''ae goroisa andrö, no mege, nibe''e razo Dario, ira Tatenai, kumandru ba danö ba zi tambai Oifarati, Sitara-Bosinai, ba awöra andrö.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 14, 'Ba motomo zatua niha Yehuda ba tedou domosa; fangabe''era wama''ele''ö ndra Haga''i sama''ele''ö, Sakharia ono Ido. Ba la''asiwai gosali, dali goroisa Lowalangi Ndraono Gizeraeli ba oroisa ndra Kiro, Dario, Aretazasa, razo Weresia.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 15, 'Ba ba zi medölu, ba mbaŵa Adara, me no alua melima fakhe razo Dario, razo [Weresia], awai gosali andrö.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 16, 'Ba lalau we''amoni''ö osali Lowalangi andrö Iraono Gizeraeli — ere ba Ono Lewi, awö niha bö''ö andrö, si no mangawuli moroi ba ni''oloi''ö ya''ira mege, omuso dödöra.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 17, 'Ba labe''e sumange ba we''amoni''ö osali Lowalangi andrö: 100 nga''eu zaŵi si matua ba 200 nga''eu mbiri-biri si matua ba 400 rozi nono mbiri-biri; ba sumange fameta horö, ba Ndraono Gizeraeli fefu, ba 12 nga''eu nambi si matua, i''ohia''ö wa''oya mado Ndraono Gizeraeli.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 18, 'Ba lafataro gere andrö, dali mbosira, ba Ono Lewi, dali ngenolira, ba halöŵö andrö khö Lowalangi, ba Yeruzalema, dali nifakhoi andrö ba zura Moze. [1]', '["MozIV 3:6"]', NULL),
  (3448046, 'OT', 'Esera', 6, 19, 'Ba lalau wasa si no mangawuli moroi ba ni''oloi''ö ya''ira mege, ba zi meweleöfa ba mbaŵa si föföna lalau. [2]', '["MozII 12:6"]', NULL),
  (3448046, 'OT', 'Esera', 6, 20, 'Noa sa lahaogö ira ere ba Ono Lewi, dozi; oi si no muhaogö ira. Ba lataba wasa tana ba zi no mangawuli andrö moroi ba ni''oloi''ö ya''ira mege fefu, ba tana ba dalifusöra ere andrö, ba tana khöra.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 21, 'Ba la''a Iraono Gizeraeli, si no mangawuli moroi ba ni''oloi''ö ya''ira mege, awö dozi si no mangondrasi ya''ira, si no mangoniagö ya''ira ba wa''ara''i-ra''iö niha baero andrö ba danö, ba wangalui Yehowa, Lowalangi Ndraono Gizeraeli.', '[]', NULL),
  (3448046, 'OT', 'Esera', 6, 22, 'Ba lalau gowasa roti si lö mu''aisöni andrö, fitu ngaluo, ba somuso tödö ira. Noa sa omuso sibai dödöra ibe''e Yehowa, me no idönisi khöra dödö razo Asiria, ba wanolo ya''ira ba halöŵöra andrö, ba gosali Lowalangi Ndraono Gizeraeli.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 1, 'Ba me aefa da''ö no mege, me razo Aretazasa, razo Weresia, ba möi misi yaŵa Gesera andrö, ono Zeraya ono Gasaria ono Hilikia', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 2, 'ono Zalumi ono Zadoki ono Gahitobi', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 3, 'ono Gamaria ono Gasaria ono Merayoto', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 4, 'ono Zeraya ono Usi ono Mbuki', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 5, 'ono Gabisua ono Wineha ono Geleazari ono Ga''aroni ere sebua andrö. —', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 6, 'Esera andrö zi möi misi yaŵa, moroi ba Mbabeli. Ba sangila amakhoita ia, si no mangila sibai oroisa andrö, khö Moze, nibe''e Yehowa, Lowalangi Ndraono Gizeraeli; ba itehe khönia ni''andrönia fefu razo, me itolo ia tanga Lowalanginia Yehowa.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 7, 'Ba so zi fao khönia ba Yeruzalema Iraono Gizeraeli ösa ba ere ba Ono Lewi ba sanunö ba sanaro ba mbawandruhö ba sangai halöŵö ba gosali, enoni andrö, me no alua meönö fakhe razo Aretazasa.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 8, 'Ba irugi Yeruzalema, me baŵa si lima, döfi si fitu khö razo.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 9, 'Ba zi sambua desa''a ba mbaŵa si föföna iŵa''ö wangefa ba Mbabeli, ba ba zi sambua desa''a ba mbaŵa si lima larugi Yeruzalema, me no itolo ia tanga Lowalanginia, sebua tödö khönia.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 10, 'Me no ibe''e dödönia Esera i''alu-alui goroisa Yehowa ba i''o''ö, ba ifahaö Ndraono Gizeraeli ba gamakhöita andrö ba ba huku.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 11, 'Ba da''e zura andrö, nibe''e razo Aretazasa khö Gesera sangila amakhoita; si no to''ölö ba niŵa''ö ba goroisa Yehowa ba ba gamakhoitania ba Ndraono Gizeraeli, imane:', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 12, '"[Nibe''e] Aretazasa fondrege razo khö Gesera andrö ere ba sanura oroisa Lowalangi zorugo andrö — ba tohu-tohunia.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 13, 'No ube''e goroisa: dozi Iraono Gizeraeli ba mbanuagu ba ere khöra ba Ono Lewi, sedöna möi ba Yeruzalema, ba ndra möi awöu,', '["Esit 1:14"]', NULL),
  (3448047, 'OT', 'Esera', 7, 14, 'me no nifatenge razo ndra''ugö ba nifatenge ganofulania andrö si dafitu, dali goroisa Lowalangiu andrö, si so ba dangau, ba wamaigi he wisa ba mado Yuda ba ba Yeruzalema, [1]', '["Esit 1:14"]', NULL),
  (3448047, 'OT', 'Esera', 7, 15, 'ba ba wolohe khöra firö andrö ba ana''a, nibe''e razo ba anofulania saoha gölöra khö Lowalangi Ndraono Gizeraeli si so nahia ba Yeruzalema,', '["Esit 1:14"]', NULL),
  (3448047, 'OT', 'Esera', 7, 16, 'ba he firö andrö ba ana''a, fefu, nifalau khöu ba danö Mbabeli ma''asagörö, awö nibe''e zato [Iraono Gizeraeli] ba ere, saoha gölöra, wame''e balazo gosali Lowalangira ba Yeruzalema, saoha gölö.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 17, 'Andrö wa öfaigi sibai wame''e ana''a andrö, ba wowöli saŵi si matua ba biri-biri si matua ba ono mbiri-biri, awö zumange ni''a ba sumange nibadu, nifao ba da''ö, ba öbe''e ba naha wame''e sumange andrö, ba gosali Lowalangimi ba Yeruzalema.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 18, 'Ba ba zi tosai firö andrö ba ana''a ba balazi dödöu ba tödö niwami andrö, heza mi''oguna''ö, dali zomasi Lowalangimi.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 19, 'Ba gama-gama andrö, ba halöŵö, ba gosali Lowalangimö, nibe''e ba dangau, ba ahori ötou''ö tou föna Lowalangi andrö, ba Yeruzalema.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 20, 'Ba hadia na zoguna khöu, ba gosali Lowalangiu andrö, balazo, ba hana na ba nomo girö-girö khö razo öhalö.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 21, 'Ba ya''odo, razo Aretazasa, ba no ube''e li ba zangirö ana''a andrö, fefu, ba danö, ba zi tambai Oifarati tanö andrö, no umane: Fefu hadia ia ni''andrö Gesera andrö, sanura oroisa andrö, oroisa Lowalangi zorugo, ni''andrönia khömi, ba mi''o''ö sibai khönia,', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 22, 'irege 22,050 balaki wirö ba 200 ngaso''e gandru ba 20 ngaso''e nagu ba 20 ngaso''e wanikha, ba asio, ba si lö muŵa''ö ha wa''oya.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 23, 'Fefu hadia ia zoguna, dali goroisa Lowalangi zorugo andrö, ba tenga ni''ambösi fame''e ba gosali Lowalangi zorugo andrö, fa böi göna fönu mbanua razo ba banua ndraononia. [2]', '["F. 6, 10"]', NULL),
  (3448047, 'OT', 'Esera', 7, 24, 'Ba ya''ami, ba böi zi lö mirongo: dozi ami, ba ba gere andrö ba ba Nono Lewi ba ba zanunö andrö ba ba zanaro ba mbawandruhö ba ba zangai halöŵö ba gosali Lowalangi andrö, ba lö tola miwa''ö mbeo ba ma hua zago ba ma rodi lala.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 25, 'Ba ya''ugö Esera, ba öfataro zanguhuku ba samatörö ba wa''atua-tua andrö khö Lowalangiu, si no so khöu, ena''ö lafatunö huhuo niha sato fefu, ba danö ba zi tambai Oifarati tanö andrö, — huhuo zi no aboto ba dödö oroisa Lowalangiu andrö; ba ha niha zi lö mangila ya''ia [na], ba mifahaö.', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 26, 'Ba dozi ha niha zi lö molo''ö oroisa Lowalangiu ba oroisa razo, ba nihaogö fanguhuku, he ba wamunu ya''ia, ba he ba wanibo''ö ya''ia, ba he ba wogau, ba he ba wokuru."', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 27, 'Nisuno Yehowa, Lowalangi ndra tuada, si no mame''e ba dödö razo da''ö, ba wamolakhömi osali Lowalangi andrö, ba Yeruzalema,', '[]', NULL),
  (3448047, 'OT', 'Esera', 7, 28, 'ba si no mame''e falukha wa''ebua dödö razo ndra''odo, khö razo ba ba ganofulania andrö ba ba gumandru sebua andrö khö razo fefu! Ba u''abe''e''ö dödögu, me no itolodo tanga Lowalangigu Yehowa, ba u''owuloi zatua Ndraono Gizeraeli, ena''ö möi ira awögu misi yaŵa.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 1, 'Ba da''e döi duara ba töi nga''ötö da''ö, si fao khögu misi yaŵa, me luo razo Aretazasa.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 2, 'Ma''uwu Wineha, ba Gereso. Ba ma''uwu Gitamari, ba Dani''eli. Ba ma''uwu Dawido, ba Hatusi, ono Zekhania.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 3, 'Ba ma''uwu Wareo, ba Sakharia, ba nitanö ba zura awönia, ba 150 ndra matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 4, 'Ba ma''uwu Wahata-Moabi, ba Eliyeho''enai, ono Zerahia, ba 200 naŵonia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 5, 'Ba ma''uwu Zatu, ba Sekhania, ono Yehazi''eli, ba 300 nawönia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 6, 'Ba ma''uwu Gadini, ba Ebedi, ono Yonata, ba 50 nawönia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 7, 'Ba ma''uwu Gelama, ba Yesaya, ono Gatalia, ba 70 nawönia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 8, 'Ba ma''uwu Zefatia, ba Sebadia, ono Mikha''eli, ba 80 nawönia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 9, 'Ba ma''uwu Yoabi, ba Obadia ono Yehi''eli, ba 218 nawönia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 10, 'Ba ma''uwu Mbani, ba Selomiti, ono Yosifia, ba 160 nawönia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 11, 'Ba ma''uwu Mbebai, ba Sakharia, ono Mbebai, ba 28 nawönia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 12, 'Ba ma''uwu Asigada, ba Yohanano, ono Hakatana, ba 110 nawönia, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 13, 'Ba ma''uwu Gadonika, si akhi ba wa''atumbu, Elifeleti ba Ye''ieli ba Semaya döira, ba 60 nawöra, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 14, 'Ba ma''uwu Mbigewai, ba Uta''i ba Sabudi, ba 70 nawöra, ira matua.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 15, 'Ba u''owuloi ira ba mbewe nidanö andrö, si saŵa miyou Ahawa, ba ma''iagö da''ö ua, tölu ngaluo. Ba me ufaigi niha sato, awö gere, ba no samösa lö ono Lewi ba da''ö.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 16, 'Ba ufatenge ndra Eli''ezeri, Ari''eli, Semaya, Elinata, Yaribi, Elinata, Natano, Sakharia, Mesula, oi satua, ba Yoyaribi ba Elinata, guru, ufatenge khö Ido,', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 17, 'satua ba mba nua Gasifia, ba ube''e li khöra, hadia niŵa''ö khö Ido ba ba dalifusönia ba ba zangai halöŵö ba gosali, banua Gasifia, ba wamaigi khöma sangai halöŵö ba gosali Lowalangima. 18Ba me no itologa tanga Lowalangida, si hakhösi tödö ya''aga, ba la''ohe khöma niha satua-tua, ma''uwu Maheli ono Lewi ono Gizeraeli, Serebia andrö, awö ndraononia ba awö dalifusönia,', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 18, 'fefu, ba Hasabia,', '["Yos 9, 21. Nga''ötI 9, 2"]', NULL),
  (3448048, 'OT', 'Esera', 8, 19, 'awö Yesaya ma''uwu Merari ba talifusönia ba iraonora, 20 fefu.', '["Yos 9, 21. Nga''ötI 9, 2"]', NULL),
  (3448048, 'OT', 'Esera', 8, 20, 'Ba sangai halöŵö ba gosali, nihonogöi Dawido ba awönia salaŵa, tohu-tohu danga Nono Lewi: 220 zangai halöŵö ba gosali, oi nitötöi töi. [1]', '["Yos 9, 21. Nga''ötI 9, 2"]', NULL),
  (3448048, 'OT', 'Esera', 8, 21, 'Ba ufaŵa''ögö wamoni ba gö, ba da''ö, ba mbewe Gahawa, ena''ö ma''ide-ide''ö ndra''aga föna Lowalangida, ba ba wangandrö khönia, ena''ö lö gönaga hadia ia, ba lala, ya''aga ba iraonoma ba si so khöma.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 22, 'Aila sa ndra''o, u''andrö khö razo zabölö ba si fakudo, ba wanimba khöma emali, ba lala. Noa sa mamane khö razo: Lö aefa danga Lowalangima ba zangalui ya''ia fefu, ba wangorifi ya''ira; ba ba zangerogö ya''ia, fefu, ba tohare wa''abölönia ba fönunia.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 23, 'Ba mamoni ndra''aga ba ma''andrö da''ö khö Lowalangida, ena''ö ifondrondrongo khöma, ba ifondrondrongo lima.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 24, 'Ba 12 ututuyu satua gere: Serebia ba Hasabia ba dafulu nawöra, talifusöra,', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 25, 'ba utulo khöra wirö andrö ba ana''a, awö gama-gama andrö — buala andrö ba gosali Lowalangida, nibe''e razo ba anofulania ba keomandrunia ba Iraono Gizeraeli fefu, si so ba da''ö, saoha gölöra.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 26, 'Utulo ba dangara: 460 fiku wirö; ba gama-gama firö, 70 fiku; ba ana''a 80 fiku.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 27, 'Ba 20 mako ana''a, 1000 hua balaki [fowöli], ba dombua na nahia hadia ia, töla si sökhi, nifosönö gana''a, timba gana''a ba mböli.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 28, 'Ba umane khöra: No ni''amoni''ö ami, khö Yehowa; ba gama-gama andrö, ba no ni''amoni''ö, ba firö andrö ba ana''a, ba no nibe''e saoha gölö khö Yehowa, Lowalangi ndra tuami.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 29, 'Ba mihaogö wangirö''ö ya''ia, irege mitulo ia ba zi so satua gere ba satua Nono Lewi, awö högö ngafu Ndraono Gizeraeli, ba Yeruzalema, ba mbate''e andrö ba gosali Yehowa.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 30, 'Ba lahalö wirö andrö ere ba Ono Lewi, awö gana''a, awö gama-gama andrö, nitulo, ba wolohe ba Yeruzalema, ba gosali Lowalangima.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 31, 'Ba mangefa ndra''aga ba mbewe Gahawa, ba zi mewelendrua, ba mbaŵa si föföna, ba wanaŵa Yeruzalema; ba itologa tanga Lowalangida, lö ilulu ndra''aga ba danga nemali ba ba danga zanaro-narogö ya''aga ba zinga lala.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 32, 'Ba marugi Yeruzalema, ba tölu bongi ndra''aga ba da''ö.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 33, 'Ba mahemolu ö, ba latulo wirö andrö, awö gana''a, awö gama-gama andrö, ba gosali Lowalangida, labe''e ba danga Merimoto ere, ono Guria — ba awönia Geleazari, ono Wineha, ba awöra na Nono Lewi andrö, Yosabada, ono Yesua ba Noadia, ono Mbinui —', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 34, 'ahori la''erai ba latulo khöra; ba fa''abua fefu, ba latanö ba zura, me luo da''ö.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 35, 'Ba si no so andrö, si no mangawuli moroi ba ni''oloi''ö ya''ira mege, ba mame''e sumange nitunu khö Lowalangi Ndraono Gizeraeli: 12 nga''eu zaŵi, si matua, tana ba Ndraono Gizeraeli fefu, ba 96 nga''eu mbiri-biri si matua, ba 77 rozi nono mbiri-biri, ba 12 nga''eu nambi si matua sumange fameta horö — oi sumange nitunu khö Yehowa.', '[]', NULL),
  (3448048, 'OT', 'Esera', 8, 37, 'Ba labe''e ba danga nifataro zalaŵa andrö ba ba danga ndra kumandru ba zi tambai Oifarati tanö andre, nifakhoi zalaŵa, ba latolo niha [Yehuda], ba he ba wolau osali Lowalangi andrö.', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 1, 'Ba me no mu''asiwai da''ö, ba la''ondrasi ndra''o satua, ba lamane: Lö ni''oniagö Ndraono Gizeraeli sato ba ere ba Ono Lewi ya''ira ba niha baero ba danö, si no si nangea ena''ö, ba zogoro ita andrö, ba Ndrawa Gana''ana andrö ba ba Ndraono Kheti ba ba Ndraono Weresi ba ba Ndraono Yebusi ba ba Ndraono Gamoni ba ba Ndrawa Miserayi.', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 2, 'Noa sa lahalö nonora alawe ösa fo''omora ba fo''omo ndraonora, ba tobali faruka danömö niha ni''amoni''ö andrö ba danömö niha ba danö, ba no salaŵa ba satua zamobörö lalö andrö. [1]', '["MozV 7:3"]', NULL),
  (3448049, 'OT', 'Esera', 9, 3, 'Ba ha si''aikö urongo wangadu andrö, ba utika mbarugu, awö lembegu ba udödöni mbu högögu, awö gambigu, ba mudadaodo tou, lö hede-hede, börö lalö zangawuli andrö moroi ba ni''oloi''ö ya''ira mege.', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 4, 'Ba la''ondrasi ndra''o dozi sangata''ufi oroisa Lowalangi Ndraono Gizeraeli. Ba dumao-dao manö ndra''o lö hede-hede, irugi ginötö wame''e sumange tanö owī. [2]', '["MozII 29:41"]', NULL),
  (3448049, 'OT', 'Esera', 9, 5, 'Ba me inötö wame''e sumange tanö owī, ba maoso ndra''o, ubato wamakao ya''o andrö ba ufuli utika mbarugu, awö lembegu; ba utuhi danö tou ba u''oro''ö dangagu khö Lowalangigu Yehowa.', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 6, 'Ba umane: "He Lowalangi, saila sibai ndra''odo, tobali tebai ufaöga mbawagu khöu, ya''ugö, Lowalangigu! Noa sa ilawui ndra''aga lalöma, no ebua sibai horöma, irugi mbanua si yaŵa. [3]', '["Sin 38:5"]', NULL),
  (3448049, 'OT', 'Esera', 9, 7, 'I''otarai götö ndra tuama, ba no ebua horöma, ba irugi ma''ökhö andre. Ba börö lalöma andrö, wa no nilulu manö ndra''aga, ya''aga ba salaŵa ba ere khöma, wa no mube''e ba danga razo niha baero ndra''aga ba ba mbawa zi''öli ba ba wangoloi''ö ya''aga ba ba worabu niha bö''ö ba ba wa''aila, si mane ma''ökhö.', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 8, 'Ba iya''e, ba no falukhaga wa''ahakhö dödö Lowalangima Yehowa, si lö arara na, me no isaigö na khöma zauri, ösa, si lö atotó, ba me no [ifuli] ifonahia ndra''aga ba naha ni''amoni''ö andre khönia, ena''ö ifehaga höröma Lowalangima, ba ena''ö [ifuli] ibe''e khöma wa''auri ma''ifu, ba wa''asawuyuma andre.', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 9, 'Noa sa sawuyu ndra''aga, ba no lö''ö zui ni''erogö Lowalangima ya''aga, ba wa''asawuyuma andre, noa sa ibe''e falukha wa''ahakhö dödö razo Weresia ndra''aga, ba no tobali la''orifi ndra''aga, ba wolau osali Lowalangima andrö, ba ba wanga''azökhi adudulania, ba ba wolau nahiama ba danö mado Yuda ba ba Yeruzalema, nahia nikölini öli kara.', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 10, 'Ba iya''e, ya''ugö Lowalangima, hadia niŵa''öma ba da''ö?', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 11, 'Me no ma''erogö goroisamö, nifabe''e''ömö khöma ba genonimö andrö, sama''ele''ö andrö, me ömane: Tanö andrö, nirugimi dania, ba wangokhögö ya''ia, ba no tanö si ra''i-ra''iö, börö wa''ara''i-ra''iö niha ba danö andrö, sogoro ita andrö khöra, nihönara ba danö ma''asagörö, ba wa''ara''i-ra''iöra andrö. [4]', '["MozII 18:25"]', NULL),
  (3448049, 'OT', 'Esera', 9, 12, 'Ba böi mibe''e ba nonora matua nonomi alawe, ba böi mihalö umönömi nonora alawe, ba böi mitolo ira ba wangalui fa''ohahau dödöra ba sohare ira, götö-götö wa''ara dania, ena''ö ya''ami zabölö ba ena''ö mi''aga''aga zi sökhi ba danö, ba ena''ö lö mamalö-malö, ondröitami ba nga''ötömi mitou. [5]', '["MozV 23:6"]', NULL),
  (3448049, 'OT', 'Esera', 9, 13, 'Ba ba zi no göna ndra''aga, fefu, ba mbua-buama andrö si lö sökhi ba ba horöma andrö, si no ebua — ba noa na ö''osilömilagö ösa, lalöma andrö, ya''ugö, Lowalangima, ba noa na ötehe khöma, tosai zi manö —,', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 14, 'ba hadia, mafuli masawö goroisamö, ba wambambatösa ba niha andrö, si no to''ölö ba zogoro ita andrö? Ba hadia, lö öhori ena''ö ndra''aga, ba wönumö, irege lö''ö sa''ae si tosai, ba irege lö fangorifi sa''ae?', '[]', NULL),
  (3448049, 'OT', 'Esera', 9, 15, 'He Yehowa Lowalangi Ndraono Gizeraeli, no satulö ndra''ugö; ba no si tosai ndra''aga, sauri, ma''ökhö: Ya''e ndra''aga, fönau, ba horöma andrö; börö da''ö, wa tabai mataha wönumö!" [6]', '["Sin 143:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3448050, 'OT', 'Esera', 10, 1, 'Ba me imanö wangandrö Esera, me mege-ege ia, wangombakha horö andrö, me no ifalögu tou ia ba danö, ba no ato sibai zowulo khönia Iraono Gizeraeli, ira matua ba ira alawe ba iraono, oi sa sege-ege sibai niha sato [göi].', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 2, 'Ba humede Zekhania, ono Yehi''eli, ma''uwu Gelama, imane khö Gesera: No molalö ndra''aga khö Lowalangida, me no mahalö ndra alawe bö''ö, ba niha ba danö; ba so zui na dötönafö ba Ndraono Gizeraeli, ba da''ö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 3, 'Ba datafabu''u khö Lowalangida, tatibo''ö ndra alawe andrö fefu, fabaya onora, dali niŵa''ö zokhö ya''o, awö niŵa''ö zangata''ufi oroisa Lowalangida andrö; oroisa ni''o''ö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 4, 'Faoso, khöu mangawuli huhuo andrö, ba matolo''ö; abe''e''ö dödöu ba labu!', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 5, 'Ba maoso Gesera, ba ibe''e ba hölu zatua gere ba satua Nono Lewi ba satua Ndraono Gizeraeli fefu, ba wolo''ö da''ö; ba möi ira ba hölu.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 6, 'Ba mofanö Gesera, iröi nahania andrö, föna gosali Lowalangi, möi ia ba mbate''e Yohanano andrö, ono Geliasibi. Ba da''ö mörö ia, lö manga ia ba lö ibadu nidanö; me no abu dödönia ba horö zangawuli andrö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 7, 'Ba lafakaoni''ö mado Yuda ba banua Yeruzalema, awö dozi si no mangawuli moroi ba ni''oloi''ö ya''ira mege, enaö la''owuloi ira ba Yeruzalema.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 8, 'Ba si lö so, na no aefa dua wongi. Si lö molo''ö niŵa''ö zatua ba salaŵa, ba labe''e balazo gosali zi so khönia, fefu, ba ya''ia, ba ni''efa''ö banua zangawuli andrö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 9, 'Ba owulo ndra matua mado Yuda ba mado Mbeniyami fefu, ba Yeruzalema, me no aefa dua wongi; ba zi dua wulu ba mbaŵa si siŵa. Ba no dumadao niha sato fefu ba golayama, föna gosali Lowalangi, manizi-nizi ira, börö huhuo andrö ba he teu.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 10, 'Ba maoso Gesera ere, ba imane khöra: No molalö ami, no mihalö ndra alawe bö''ö, ba wonönö na horö Ndraono Gizeraeli. [1]', '["MozV 7:3"]', NULL),
  (3448050, 'OT', 'Esera', 10, 11, 'Ba mitehe iada''e [horömi], khö Yehowa Lowalangi ndra tuami, ba mi''o''ö zomasi ia, wamabali ya''ami ba niha ba danö ba ba ndra alawe bö''ö andrö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 12, 'Ba latema linia niha sato fefu, ebua lira, lamane: Ya''itörö niŵa''öu!', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 13, 'Ba niha, ba no ato, ba no baŵa deu, tobali tebai baero manö so ita; ba tenga göi ha ma''öma''ökhö ba tenga ha dua ngaluo wangasiwai huhuo andre, me no oya ngawalö lalöda nifatunö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 14, 'Ba alakha lahuhuo''ö satuada, salahi zato, ba banuada fefu, si no mangai ira alawe bö''ö, ba akha lafa''aso''aso ira ba ginötö niŵa''ö khöra, awö zatua ba awö zanguhuku ba mbanuara, irege alö wönu Lowalangida khöda, ba golalöŵa andrö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 15, 'Ba ha Yonata, ono Gazaheli ba Yehasia, ono Dikiwa, zamadaö da''ö; ba si fa''awö khöra, ba Mesula ba Sabata''i, Ono Lewi.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 16, 'Ba la''o''ö da''ö si no mangawuli moroi ba ni''oloi''ö ya''ira mege. Ba itutuyu khönia niha Esera ere, högö ngafura andrö, oi nitötöi töi, ba falukha ira, ba zi sambua desa''a ba mbaŵa si fulu, ba wanguhuhuo''ö da''ö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 17, 'Ba irugi zi sambua desa''a ba mbaŵa si föföna, ba awai huhuo ba niha andrö fefu, si no mangai ira alawe bö''ö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 18, 'Ba da''e nga''ötö gere, si no mangai ira alawe bö''ö: Ma''uwu Yesua, ono Yosadaki, ba ma''uwu dalifusönia: Ma''aseya ba Eli''ezeri ba Yaribi ba Gedalia.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 19, 'Da''ö zondra''u tanga ndra Esera, lafabu''u latibo''ö ndra alawera andrö ba sageu labe''e biri-biri si matua ömöra ba lalöra andrö.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 20, 'Ba ma''uwu Imeri, ba Hanani ba Sebadia.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 21, 'Ba ma''uwu Harimi, ba Ma''aseya ba Elia ba Semaya ba Yehi''eli ba Usia.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 22, 'Ba ma''uwu Wasuri, ba Eliyo''enai ba Ma''aseya ba Sima''eli ba Netane''eli ba Yosabada ba Eleasa.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 23, 'Ba Ono Lewi, ba Yosabada ba Sime''i ba Kelaya — ya''ia Kelita andrö — ba Fetaya ba Yuda ba Eli''ezeri.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 24, 'Ba sanunö andrö, ba Eliasibi. Ba sanaro ba mbawandruhö, ba Salumi ba Telemi ba Uri.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 25, 'Ba Iraono Gizeraeli sato: Ma''uwu Wareo, ba Ramia ba Yisia ba Malakhia ba Miyamini ba Eleazari ba Malakhia ba Benaya.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 26, 'Ba ma''uwu Gelama, ba Matania ba Sakharia ba Yehi''eli ba Abidi ba Yeremoto ba Elia.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 27, 'Ba ma''uwu Zatu, ba Eliyo''enai ba Eliasibi ba Matania ba Yeremoto ba Sabada ba Asisa.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 28, 'Ba ma''uwu Mbebai, ba Yohanano ba Hanania ba Sabai ba Atalai.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 29, 'Ba ma''uwu Mbani, ba Mesula ba Malukha ba Adaya ba Yasubi ba Seala ba Yeramoto.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 30, 'Ba ma''uwu Wahata-Moabi, ba Adena ba Kelala ba Benaya ba Ma''aseya ba Matania ba Besale''eli ba Binui ba Manase.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 31, 'Ba ma''uwu Harimi ba Eli''ezeri ba Yisia ba Malakhia ba Semaya ba Simeoni,', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 32, 'ba Beniyami ba Malukha ba Semaria.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 33, 'Ba ma''uwu Hasumi, ba Matanai ba Matata ba Sabada ba Elifeleti ba Yeremai ba Manase ba Sime''i.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 34, 'Ba ma''uwu Mbani, ba Ma''adai ba Ameramo ba Ueli,', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 35, 'ba Benaya ba Bedia ba Keluhi', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 36, 'ba Wania ba Meremoto ba Eliasibi', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 37, 'ba Matania ba Matanai ba Ya''asai', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 38, 'ba Bani ba Binui ba Sime''i', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 39, 'ba Selenia ba Natano ba Adaya', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 40, 'ba Makhanadabai ba Sasai ba Sarai', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 41, 'ba Asare''eli ba Selemia ba Semaria', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 42, 'ba Salumi ba Amaria ba Yosefo.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 43, 'Ba ma''uwu Nebo, ba Yeïeli ba Matitia ba Sabada ba Sebina ba Yada''i ba Yo''eli ba Benaya.', '[]', NULL),
  (3448050, 'OT', 'Esera', 10, 44, 'Oi si no mangai ira alawe bö''ö da''ö, ba so zi no mo''ono ösa, ira alawe andrö.', '[]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 1, 'Hikaya khö Nehemia andrö, ono Hakalia. Me baŵa Kisilewi, döfi si dua wulu, me sodo ba gödo ba Zusa,[1]', '["Faigi 2:1","RazII 25:10"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 2, 'ba möi khögu nakhigu Hanani, awö mado Yuda ösa. Ba me usofu khöra, he wisa ba niha Yehuda sauri andrö, si tosai ni''oloi''ö no, ba he wisa ba Yeruzalema,', '["Faigi 2:1","RazII 25:10"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 3, 'ba lamane khögu: Si tosai andrö, si lö ahori ni''oloi''ö no, ba danö andrö, ba no numana sibai ba no si tehawu fa''aila, me no mududugö göli Yeruzalema öli kara, ba me no mutunu mbawa göli.[2]', '["Faigi 2:1","RazII 25:10"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 4, 'Ba me urongo duria andrö, ba mudadaodo tou, mege-egedo ba mangarö-ngarödo, mato dua wongi wa''ara; ba mamoni ba gö ndra''o ba mangandröngandrö ndra''o khö razo zorugo, umane:', '["Dan 9:4","MozV 4:27"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 5, '"He Yehowa, Lowalangi ba zorugo, Lowalangi sebua ba sata''u ita, si lö mowu''ai fawu''usa li fa''ahakhö dödö andrö ba zangomasi''ö ya''ugö ba ba zolo''ö oroisamö.[3]', '["Dan 9:4","MozV 4:27"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 6, 'Be''e mbörö dalingamö ba bokai höröu, ena''ö örongo wangandrö genoniu andre, si lö ubato khöu iada''e, bongi ma''ökhö, salahi Ndraono Gizeraeli, enoniu andrö, wangombakha khöu horö Ndraono Gizeraeli, horöma khöu; he ya''odo andre, ba ya''aga si samba omo, ba oi si no molalö khöu.', '["Dan 9:4","MozV 4:27"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 7, 'No tenga side-ide horöma khöu, ba lö ni''o''öma oroisamö, awö nifakhoimö, awö hukumö andrö, niŵa''öu khö genoniu Moze.', '["Dan 9:4","MozV 4:27"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 8, 'Törö tödöu daroma limö andrö, niŵa''öu, khö genoniu Moze, me ömane: Na molalö ami, ba ufazaewe ami ba niha baero![4]', '["Dan 9:4","MozV 4:27"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 9, 'Ba na mifalalini gera-erami, na mifuli ami khögu, ba na mibe''e ba dödömi goroisagu ba na mi''o''ö, ba he ba wondrege, ba gahe mbanua so nifazawili andrö khömi, ba u''ozaragö zui ira ba u''ohe mangawuli ba danö andrö, nituyugu, ba wamonahia töigu ba da''ö.', '["Dan 9:4","MozV 4:27"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 10, 'Noa sa ato enoniu ira ba banuau, ni''orifimö mege, ba wa''abölöu andrö, tangau sabe''e andrö.', '["Dan 9:4","MozV 4:27"]', NULL),
  (3475422, 'OT', 'Nehemia', 1, 11, 'He So''aya, be''e mbörö dalingau ba wangandrö genoniu andre ba ba wangandrö genoniu sato, somasi mangata''ufi töimö andrö: tolo, ena''ö mofozu nilau genonimö andre ma''ökhö, ba ena''ö falukha ia wa''ahakhö dödö razo andrö!" Ba ya''odo, ba same''e yomo gö khö razo.', '["Dan 9:4","MozV 4:27"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 1, 'Ba me baŵa Nisana, me no alua sara ambö dua wulu fakhe razo Aretazasa, me so fönania nagu, ba uhalö nagu andrö ba u''oro''ö khö razo ba lö ufa''ila''ö khönia ena''ö, wa lö sökhi-sökhi dödögu.', '["Faigi 5:14"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 2, 'Ba imane khögu razo: Hana wa no afusi mbawau, ba tenga sa ato sofökhö ndra''ugö.', '["Faigi 5:14"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 3, 'Ba ata''u sibai ndra''o. Ba umane khö razo: Ya anau manö noso razo! Hana wa lö afusi mbawagu, na no adudu mbanua andrö, si so lewatö ndra tuagu, ba na no akhozi mbawa gölinia?', '["Faigi 5:14"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 4, 'Ba imane khögu razo: Ba hadia ato ni''andröu? Ba mangandrö ndra''o khö Lowalangi ba zorugo;', '["Faigi 5:14"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 5, 'ba awena umane khö razo: Na atulö khö razo, ba na si tola genoniu andre öŵa''ö —: fa öfatenge ndra''o ba danö mado Yuda, ba mbanua andrö, si so lewatö ndra tuagu, ena''ö ufuli utaru''ö.', '["Faigi 5:14"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 6, 'Ba imane khögu razo — no dumadao ba ngainia ngambatönia — imane: Ha wa''ara ndra''ugö, na möi''ö, ha wa''ara öfuli''ö? Tobali atulö khö razo ifatenge ndra''odo; ba u''ötö khönia mbongi.[1]', '["Faigi 5:14"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 7, 'Ba umane na khö razo: Na atulö khö razo, ba ndramube''e khögu zura ba gumandru ba danö andrö, yefo Oifarati, ena''ö böi lataha ndra''o, balazi urugi danö mado Yuda,', '["Faigi 5:14"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 8, 'ba sura khö Gasafo andrö, samaigi-maigi eu ba gatua khö razo, ena''ö ibe''e khögu geu balo, boha mbawa göli khögu ba mbawa göli hati andrö, ba ngai gosali, ba soguna ba göli mbanua ba ba nomo andrö nahiagu. Ba itehe khögu razo, me no itolodo tanga Lowalangigu, sebua tödö khögu.', '["Faigi 5:14"]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 9, 'Ba me urugi ndra kumandru ba danö yefo Oifarati, ba ube''e ba dangara zura razo; ba no ifatenge göi gumandra ba si fakudo razo, awögu.', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 10, 'Ba me larongo ira Sanabala, banua Horono, Tobia enoni andrö, Iraono Gamoni, ba afökhö khöra, me no so zanolo Iraono Gizeraeli, ena''ö ohahau dödöra.', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 11, 'Ba urugi Yeruzalema, ba me no tölu bongi ndra''o ba da''ö, ba maoso ndra''o, utörö bongi,', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 12, 'lö atoto nawögu, lö ni''ombakha''ögu ba niha bö''ö hadia nibe''e Lowalangigu ba dödögu fanologu Yeruzalema, ba lö u''ohe kudo, ha si sageu andrö, ba zi fakudo ndra''o.', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 13, 'Ba utörö mbawa göli ba ndraso, ba zi bongi, mitou ba gumbu naga ba ba mbawa göli golawua; ba u''amaigi''ö öli Yeruzalema si no abökha, ba bawa göli, si no akhozi.', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 14, 'Ba usaŵa mbaŵa göli ba mba''a ba baŵa razo; ba lö''ö sa''ae naha gahe kudogu, tebai itörö, barögu.', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 15, 'Ba u''osisi miyaŵa ndraso, ba zi bongi, ba u''amaigi''ö öli. Ba ba mbawa göli ba ndraso zui utörö, wangawuli miyomo.', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 16, 'Ba satua, ba lö la''ila, heza möido, ba hadia danigu, irege da''ö, ba lö ni''ombakha''ögu, he ba niha Yehuda [sato], ba he ba gere ba he ba zalaŵa ba he ba zatua ba he ba danö bö''ö fefu, sohalö-halöŵö.', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 17, 'Ba umane khöra: Mi''ila wangabu dödö andrö khöda, me no adudu Yeruzalema ba me no akhozi mbawa göli. Talabu, ta''azökhi göli Yeruzalema, fa böi sa''ae la''igi''igi''ö ita!', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 18, 'Ba awena u''ombakha''ö khöra, wa no itolodo tanga Lowalangigu, si no ebua tödö khögu, awö niŵa''ö razo khögu. Ba lamane: Talabu, talau! Ba la''abe''e''ö ira ba halöŵö si sökhi andrö.', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 19, 'Ba me larongo da''ö ira Sanabala, banua Horono, Tobia, enoni andrö, Iraono Gamoni ba Gesemi, Dawa Ara, ba la''o''aya ndra''aga, ma''iki ira khöma, ba lamane: Hadia da''ö khömi, nilaumi andrö?', '[]', NULL),
  (3475425, 'OT', 'Nehemia', 2, 20, 'Hadia, milaŵa razo? Ba utema lira, umane khöra: Lowalangi andrö ba zorugo zame''e mofozu khöma dania; ba ya''aga, enoninia andre, ba malau, ma''azökhi. Ba ya''ami, ba tenga awö ami, lö tana khömi, ba tenga si lö olifu mbanua Yeruzalema dania ami.', '[]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 1, 'Ba maoso Geliasibi ere sebua ba talifusönia ere andrö, ba lalau mbawa göli mbiri-biri andrö. Ba la''amoni''ö ba labe''e lagönia. Ba latohugö, irugi malige Hamea andrö, ba la''amoni''ö da''ö göi, ba latohugö, irugi malige Hanane''eli.[1]', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 2, 'Ba sohalöŵö ba ngaira, ba banua Yerikho. Ba ba ngai da''ö, ba Sukuri, ono Imeri.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 3, 'Ba bawa göli gi''a, ba banua Zana''a zolau; labe''e mboha ba lafa''anö lagö, awö lazi, ba si no amaedola mbuatö.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 4, 'Ba sangazökhi ba ngai da''ö, ba no Meremoto, ono Guria ono Hakosi, ba ba ngai da''ö, ba Mesula, ono Mberekhia ono Mesesabe''eli. Ba ba ngai da''ö, ba Sadoki, ono Mba''ana.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 5, 'Ba ba ngai da''ö, ba banua Dekoa; ba salaŵara, ba lö la''o''ö niŵa''ö zamatörö ya''ira.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 6, 'Ba sangazökhi bawa göli ba mbanua satua, ba Yoyada, ono Wasea, ba Mesula, ono Mbesodia, labe''e mboha ba lafa''anö lagö, awö lazi ba si no amaedola mbuatö.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 7, 'Ba ba ngai da''ö, ba Melatia, banua Gibeona, ba Yadono, banua Meronoti, awö mbanua Gibeona andrö, awö mbanua Misefa, amatöröŵa gumandru ba danö ba zi tambai Oifarati tanö andre.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 8, 'Ba ba zi tambai da''ö, ba Usieli zangazökhi, ono Haraya, awö duka gana''a andrö. Ba ba ngai da''ö, ba Hanania tuka dalu-dalu nifalemba; la''azökhi [göli] Yeruzalema, irugi göli sawe''e-we''e andrö.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 9, 'Ba ba ngai da''ö, ba Refaya zangazökhi, ono Huri, satua zi matonga mbanua Yeruzalema.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 10, 'Ba ba ngai da''ö, ba Yedaya, ono Harumafa, ba gamaudu nomonia. Ba ba ngai da''ö, ba Hatusi, ono Hasabeneya.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 11, 'Ba sandroro lahaogö Malakhia, ono Harimi ba Hasubi, ono Wahata-Moabi, fabaya malige danuri andrö.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 12, 'Ba ba ngai da''ö, ba Salumi, ono Halohe, satua zi matonga mbanua Yeruzalema — ya''ia ba ononia alawe.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 13, 'Ba bawa göli ba ndraso, ba Hanuni zolau, awö mbanua Zanoa, lafasindro ba fa''anö lagö, awö lazi ba si no amaedola mbuatö, ba latohugö wangazökhi öli, 1.000 hela, irugi mbawa göli golawua.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 14, 'Ba bawa göli golawua andrö, ba Malakhia zangazökhi, ano Rekhabi, satua mbanua Mbeti Kheremi; ifasindro ba ifa''anö lagö, awö lazi ba si no amaedola mbuatö.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 15, 'Ba bawa göli ba mba''a, ba Saluni zangazökhi, ono Kholi-Hose, satua mbanua Misefa — ifasindro ba ifosagö ba ifa''anö lagö, awö lazi ba si no amaedola mbuatö —, ba itohugö wangazökhi öli ba zinga mbaŵa ba nulu hele, ba kabu razo, ba irugi nibosi andrö, moroi yaŵa ba mbanua Dawido.[2]', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 16, 'Ba tohu-tohu da''ö, ba Nehemia zangazökhi, ono Gasibuki, satua zi matonga mbanua Mbetisuri, irugi ba gamaudu lewatö Dawido ba irugi mbaŵa andrö, nifazökhi, ba irugi nomo zaradadu andrö.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 17, 'Ba ba zi tambai da''ö, ba Ono Lewi Rehumi, ono Mbani [zolohe ya''ira]. Ba ba ngai da''ö, ba Hasabia, satua zi matonga mbanua Gegila, nifakhoi ba mbanuara lalau.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 18, 'Ba ba zi tambai da''ö, ba iwara. Bawai, ono Henedada, satua zi matonga mbanua Gegila [zolohe].', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 19, 'Ba ba ngaira, ba Ezeri, ono Yesua, satua mbanua Misefa, sandroro göi lalau, ba gamaudu lala miyaŵa ba nomo wangöna ba watalinga.[3]', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 20, 'Ba ba zi tambai da''ö, miyaŵa ba hili, ba Barukhi, ono Zabai, sandroro göi, i''otarai watalinga, irugi gamaudu mbawandreehö nomo Geliasibi ere sebua.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 21, 'Ba ba ngai da''ö, ba Meremoto, ono Guria ono Hakosi, sandroro göi, i''otarai ba gamaudu mbawandruhö nomo Geliasibi, irugi ba hambo nomonia.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 22, 'Ba ba ngai da''ö, ba ere, banua ba zalo''o.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 23, 'Ba ba ngai da''ö, ba Beniyami ba Hasubi, ba gamaudu nomora. Ba ba ngai da''ö, ba Asaria, ono Ma''aseya ono Ganania, ba ngai nomonia.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 24, 'Ba ba zi tambai da''ö, ba Binui, ono Henadada, sandroro göi, i''otarai nomo Gasaria, irugi watalinga andrö ba sanalinga si''u.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 25, 'Ba Falala, ono Usai, ba ba gamaudu watalinga andrö ba ba gamaudu malige tanö yaŵa, si no tedou moroi ba gödo razo, si fadoro ba gurunga. Ba ba ngai da''ö, ba Fedaya, ono Wareo.[4]', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475426, 'OT', 'Nehemia', 3, 26, 'Ba sangai halöŵö ba gosali, enoni andrö, ba ba Gofeli andrö so nomora, irugi ba gamaudu mbawa göli ba nidanö, tanö ba gatumbukha luo ba irugi malige si no tedou andrö.[5]', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 27, 'Ba ba zi tambai da''ö, ba banua Dekoa zui, sandroro tö, ba gamaudu malige si no tedou, ba irugi göli Gofeli andrö.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 28, 'Ba yaŵa mbawa göli kudo, ba ere zangazökhi; ba gamaudu nomonia ilau zamösana.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 29, 'Ba ba ngai da''ö ba Sadoki, ono Imeri, ba gamaudu nomonia. Ba ba zi tambai da''ö, ba Semaya, ono Zekhania, sanaro ba mbawa göli tanö ba gatumbukha luo.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 30, 'Ba ba ngai da''ö, ba Hanania, ono Zelemia ba Hanuni, ono Zalafi, lima moroi ba zi a''a, sandroro zui. Ba ba ngai da''ö, ba Mesula, ono Mberekhia, ba gamaudu mbate''enia.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 31, 'Ba ba zi tambai da''ö, ba Malakhia andrö, tuka gana''a, irugi nomo zangai halöŵö ba gosali, ba ba ngai da''ö, ba solafo, ba gamaudu mbawa göli Mifikada, ba irugi ba gamaudu mbate''e andrö ba zi sagötö, ba watalinga.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475426, 'OT', 'Nehemia', 3, 32, 'Ba ba gotalua da''ö mbawa göli mbiri-biri, ba tuka gana''a göi ba solafo zangazökhi.', '["Yer 31:38","RazII 20:20","Nga''ötII 26:9","Yer 32:2","Nga''ötII 27:3"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 1, 'Ba me irongo Sanabala la''a''azökhi göli, ba mofönu ia ba abao sibai dödönia. Ba i''igi''igi''ö niha Yehuda.', '[]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 2, 'Imane, ba zi so talifusönia, awö zabölö Ndrawa Zamaria: "Hadia nilau niha Yehuda samomo andrö? Hadia, lafuli laböhöli dania? Hadia, mame''e sumange ira dania? Hadia, la''asiwai ma''ökhö? Hadia, lafuli lafahalö gara adudula andrö, si no fabali ba galitö?"', '[]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 3, 'Ba no so ba ngainia Dobia andrö, Iraono Gamoni, ba imane da''ö: "Alakha lalau, ba na möi yaŵa nasu, ba adudu göli kara andrö khöra ibe''e!"', '[]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 4, 'Fondrondrongo, ya''ugö Lowalangima, he wisa wa lö ba dödö niha bö''ö ndra''aga! Be''e mangawuli ba hulura wango''ayara andrö, ba be''e ni''oloi''ö ba danö bö''ö ira, ba be''e nirabu zi so khöra.', '[]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 5, 'Böi balugö lalöra, ba böi bunu [ba zura] horöra, fönamö; me no la''andrö wönumö, ba zanehe zangazökhi öli andrö!', '[]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 6, 'Ba sangazökhi öli ndra''aga, ba teduhö göli, ma''asara, irugi zi matonga wa''alaŵania, ba no owölö-ölö sibai niha sato ba halöŵö andrö.', '[]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 7, 'Ba me larongo ira Sanabala Tobia ba Dawa Ara ba Iraono Gamoni ba banua Gasoto andrö, te''azökhi göli Yeruzalema ba ibörötaigö teduhö zabökha andrö, ba mofönu sibai ira,', '[]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 8, 'ba möi ira ba hölu, dozi ira, lafa''aso ira, lawa''ö, ba wanuwö Yeruzalema ba ba wangalani ya''ira.', '[]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 9, 'Ba mangandrö ndra''aga khö Lowalangima, ba bongi ma''ökhö mafataro zanaro, ba khora andrö, fa''ata''uma ira.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 10, 'Ba lamane mado Yuda: Erege dödö zana''u andrö, me no abölö fahöna gadudula, ba tobali tebai ma''azökhi göli andrö.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 11, 'Ba lamane uduma andrö: Alakha lö larongo ba alakha lö la''ila, irege no tarugi bakha hunöra, ba ta''ö''ötö ira ba tebato halöŵö tabe''e!', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 12, 'Ba me so niha Yehuda, banua sahatö khöra, me no mato mewulu laŵa''ö khöma, dozi banua: Lö tola lö mifuli ami khöma!', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 13, 'Ba ufataro niha, sawu-sawu, ba zahöndrö tanö, ba gero göli, ba mbandra, sangaro, si''öli ba toho ba fana.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 14, 'Ba ufaigi; ba maoso ndra''o ba umane ba zalaŵa ba ba zatua ba ba niha sato: Böi mi''ata''ufi ira. Mitörö tödömi zokhö ya''ita, si no ebua ba sata''u niha, ba milau fasöndra, ba wangorifi talifusömi ba iraonomi, matua ba alawe, ba fo''omomi; ba omomi mifatou-tou tödömi.[1]', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 15, 'Ba me larongo uduma andrö, no terongo khöma ba no aekhu ba wa lö boto dödöra andrö ibe''e Lowalangi, ba tola mangawuli ba göli ndra''aga fefu ba tola ifaigi halöŵönia zamösana.[2]', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 16, 'Ba i''otarai luo da''ö, ba ha si matonga nono matua andrö khögu zohalöŵö ba göli; ba si matonga, ba solohe si''öli ba toho ba baluse ba fana ba öröba, ba satua, ba la''iagö furi mado Yuda sato, sohalöŵö ba göli.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 17, 'Ba sonoro andrö, ba no mangaro; lahalö-halö halöŵöra tangara si sara, ba si sara, ba solohe toho.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 18, 'Ba sama''anö kara, ba dozi no labe''e ba löwi-löwira zi''ölira, ba lafa''anö''anö gara; ba ba ngaigu so zolau torofe.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 19, 'Ba umane ba zalaŵa ba ba zatua, ba ba zato: Halöŵöda, ba no ebua ba no ebolo zi so ita, ba tobali si no muzaewe ita, ba göli, no aröu gotaluada.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 20, 'Ba heza mirongo li dorofe, ba da''ö mi''owuloi ami khöma; Lowalangida dania zi fasöndra, salahida.[3]', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 21, 'Ba mahalö-halö halöŵöma ba göli, ba si matonga, ba solohe toho, i''otarai wa''amoluo ba irugi oroma ndröfi.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 22, 'Ba umane göi ba niha sato, me luo da''ö: Dozi ami, ba ba Yeruzalema mörö ami, awö ngoni-ngonimi, ena''ö sanaro ba zi bongi khöda da''ö, ba ba zi ma''ökhö, ba ba wangazökhi öli.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475427, 'OT', 'Nehemia', 4, 23, 'Ba lö''ö manö maheta nukhama, he ya''o, ba he talifusögu, ba he ono matua andrö khögu, ba he sanaro andrö, si so barö mbawagu; ba dozi ndra''aga, ba si so fangöna ba gambölö.', '["MozV 20:3","Yoh 5:12","MozII 14:14; MozV 1:30"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 1, 'Ba mangarö-ngarö sibai niha sato, awö wo''omora, ba iwara andrö, niha Yehuda.', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 2, 'So zanguma''ö: Iraonoma matua ba iraonoma alawe, ba mabe''e gade; ndramufaigi khöma wakhe, ena''ö manga ndra''aga ba ena''ö auriga!', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 3, 'Ba so göi zanguma''ö: Nowima ba kabu nagu khöma, ba omoma, ba mabe''e gade; ba ndramufaigi khöma wakhe, ba lofo andre![1]', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 4, 'Ba so göi zanguma''ö: No mabe''e gade mbenuama, awö kabu nagu khöma, ba wamalali kefe, ömöma beo ba zalaŵa.', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 5, 'Ba iya''e, ba he ŵa''ae no faoma ira mbotoma mboto dalifusöma andrö, awö wa no faoma ira ndraonoma ndraonora, ba malulu zui sawuyu ndraonoma matua, fabaya iraonoma alawe; noa sa tobali sawuyu nonoma alawe ösa. Ba no tebai matimba da''ö, me noa sa ato niha bö''ö zokhö benuama, awö kabu nagu khöma.', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 6, 'Ba mofönu sibai ndra''o, me urongo wangarö-ngaröra, awö niŵa''öra andrö.', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 7, 'Ba u''era-era tödögu; ba utegu zalaŵa ba satua, umane khöra: Hadia, sangebua hare ami, na mibe''e nifalali ba nawömi? Ba ulau walukhata sebua ba khöra andrö,[2]', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 8, 'ba umane khöra: Ya''aga, ba no mahöli dalifusöda niha Yehuda andrö, si no mu''amawa ba niha baero, ndrege nisöndrama lala. Ba ya''ami, ba samawa talifusömi na''i ami, ena''ö te''amawa ira khöda? Ba lö hede-hedera, tebai latema ligu.[3]', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 9, 'Ba umane: Si lö sökhi wolaumi andrö! Hadia, tenga sangata''ufi Lowalangida ami ena''ö, ba nilaumi andrö, börö wango''aya niha baero andrö, ududa?', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 10, 'Ba ya''o ba ira talifusögu ba ono matua andrö khögu, ba no mabe''e nifalali khöra gana''a ba fakhe; ba alakha lö tasugi zugilöda andrö.', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 11, 'Ma''ökho andre mifuli khöra mbenuara ba kabu nagu khöra ba kabu zai ba omora, ba böi sa''ae misugi mibe''emi nifalali khöra, ana''a ba fakhe ba agu ba fanikha.', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 12, 'Ba lamane: Mafuli, ba lö''ö sa''ae masugi ira; ma''o''ö zomasi ndra''ugö. Ba ufakaoni''ö gere, ba ube''e ba hölu ira, wa la''o''ö niŵa''ögu.', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 13, 'Ba u''anotogö mbarugu ba dotogu ba umane: Ya''imane Lowalangi wanimba dozi si falimo ba nifabu''ura andrö, yamutimba ira baomora ba ba zi so khöra, ba ni''anotogö ira si manö göi, balazi lö ösi sa''ae! Ba lamane niha sato fefu: Ya duhu! ba lasuno Yehowa. Ba la''o''ö da''ö no mege sato.', '["MozI 47:20","MozII 22:23","MozIII 25:48"]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 14, 'Ba i''otarai luo da''ö, me tefataro ndra''o amaedola gumandru ba danö mado Yuda — i''otarai ndröfi si 20, irugi ndröfi si 32 khö razo Aretazasa, mewelendrua fakhe wa''ara — ba lö ni''agu ö gumandru, awö ndra talifusögu,', '[]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 15, 'he ŵa''ae no lafo''ömö niha sato kumandru föna, fönagu, 40 rufia ma''ökhö, böli göra roti ba böli göra agu; ba no lafakao niha sato ono matua andrö khöra. Ba tenga si manö wolaugu, fa''ata''ugu Lowalangi.', '[]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 16, 'Ba he ba wangazökhi öli andre, ba no mohalö-halöŵö göi ndra''odo, ba lö''ö sa ni''ölima benua; ba ono matua andrö khögu, ba no ahori so, ba halöŵö andrö.', '[]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 17, 'Ba khögu manga-manga niha Yehuda andrö, he satua andrö, otu a lima wulu, ba he si möi khöma, banua niha baero, si tefasui ya''aga.', '[]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 18, 'Ba hadia nihalö-halö, öra sirugi ma''ökhö — sagesageu zaŵi si matua ba önö''önö nga''eu mbiri-biri nitutuyu ba hadia ia wofo —, ba ya''o zanaha, ba fulufulu bongi, ba hadia ia ngawalö nagu, ni''oya''ö. Ba ba da''ö fefu, ba lö uŵa''ö ögu gö gumandru, me no abe''e rodi ba niha sato.', '[]', NULL),
  (3475428, 'OT', 'Nehemia', 5, 19, 'Böi olifugö''ö ndra''o, ya''ugö Lowalangigu, ba nitologu niha andre, fefu, ba wolohe ba zi sökhi hadia ia khögu!', '[]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 1, 'Ba me terongo khö ndra Sanabala, Tobia, Gesemi Dawa Ara, ba ba nuduma bö''ö andrö, wa no u''azökhi göli ba lö sadudu sa''ae — he ŵa''ae lö''ö na mufa''anö lagö mbawa göli, irugi luo da''ö —,', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 2, 'ba lafatenge khögu ira Sanabala Gesemi, lamane khögu: Tabu, ena''ö falukha ita ba mbanua heza, ba ndraso Gono! Ba tödöra, ba si lö sökhi lalau khögu.[1]', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 3, 'Ba ufatenge zinenge khöra, umane: Ebua sibai halöŵögu, ba tebai möido mitou khömi. Tebai teröi halöŵö, fa uböhöi ena''ö, ba we''amöi mitou khömi.', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 4, 'Ba mendröfa lafatenge khögu, si manö-manö, ba umanö-manö göi khöra.', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 5, 'Ba samuza tö ifatenge khögu Sanabala, melima möi da''ö, enoninia ifatenge, sagörö zura ba dangania, sura si lö löwölöwö.', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 6, 'Imane ba zura andrö: No teturia ba niha baero, ba iŵa''ö göi Gasimu: Tödöu ba tödö niha Yehuda, ba edöna molaŵa ami, andrö halö-halöŵöu wangazökhi öli, ba ena''ö tobali razora ndra''ugö; soroma ba da''ö fefu.', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 7, 'Ba noa göi öfataro zama''ele''ö laŵa''ö, ena''ö latolo''ö we''ao ba Yeruzalema: Razo mado Yuda ia! Ba irongo dania duria da''ö razo. Andrö tabu, ena''ö falukha ita!', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 8, 'Ba ufuli ufatenge khönia, umane: Faya manö niŵa''öu andrö, nifakhaimö da''ö tödöu.', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 9, 'Dozi ira sa, ba no sameta''u ya''aga ena''ö, lamane dödöra: Atata dania dangara ba laböhöli wangazökhi öli, ba tobali lö awai. Andrö abe''e''ö dangagu! [umanö wangandrö].', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 10, 'Ba möido yomo khö Zemaya, ono Delaya ono Mehetabe''eli, me no yomo manö soso ia. Ba imane: Tafao ba gosali Lowalangi, ba ni''amoni''ö, ba takusi mbawandruhönia, so sa dania zi möi mamunu ya''ugö, ba zi bongi so ira, ba wamunu ya''ugö!', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 11, 'Ba umane: Hadia, soloi niha si mane ya''odo? Ba hadia, tola möi ita bakha ba gosali, ya''ita andre, si lö mate ita? lö möido bakha ba da''ö.', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 12, 'Aboto sa''ae ba dödögu, tenga Lowalangi zamatenge ya''ia; me no Tobia ba Sanabala zangoni ya''ia, andrö wa mama''ele''ö ia ba khögu.', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 13, 'Ba da''ö danira wangoni ya''ia: ena''ö ata''u ndra''o, ba ena''ö uhalö horögu wolau da''ö, ba wamatou ya''o dania, ena''ö la''ila latandraŵaisi ndra''odo.', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 14, 'Böi olifugö''ö, ya''ugö Lowalangigu, ndra Tobia Sanabala, ba nilaura andrö; ba sama''ele''ö ira alawe andrö, Noadia, awö zama''ele''ö bö''ö andrö, sameta''u ya''o mena''ö!', '["Nga''ötI 8:12"]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 15, 'Ba awai göli ba zi dua wulu a lima ba mbaŵa Eluli, 52 wongi wa''ara.', '[]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 16, 'Ba me larongo da''ö uduma andrö fefu, ba ihawui fa''ata''u niha baero fefu, si tefasui ya''aga, ariri sibai ira wamaigira, ba aboto sa''ae ba dödöra, wa no moroi ba wanolo Lowalangima, wa no awai göli andrö.', '[]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 17, 'Ba oya göi lafa''ohe''ö sura khö Dobia salaŵa mado Yuda me luo da''ö, ba oya göi ifa''ohe''ö khöra Tobia.', '[]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 18, 'Me no ato mado Yuda, si no möi ba hölu khönia, me no umönö Zekhania, ono Ara, ia, ba me umönö Mesula, ono Mberekhia, nononia Yohanano.', '[]', NULL),
  (3475429, 'OT', 'Nehemia', 6, 19, 'Ba ladunö-dunö göi khögu dödönia si sökhi, ba lafulifuli khönia niŵa''ögu; ba sura ifa''ohe''ö Tobia, ba wameta''u ya''o.', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 1, 'Ba me no mu''azökhi göli, ba ufa''anö lagö mbawa göli, ba tefataro zanaro ba mbawa göli ba sanunö ba Ono Lewi.', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 2, 'Ba banua Yeruzalema, ba ube''e barö mbawa ndra akhigu Hanani Hanania kumandra ba hati, me no niha si faduhu dödöda ba sangata''ufi Lowalangi [Hanania]; lö ato wamaedonia.', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 3, 'Ba ube''e li khöra, umane: Lö aösö labokai mbawa göli Yeruzalema; balazi aukhu zino. Ba ba zi so zanaro na, laduhö mbawa göli, ba lalazi. Ba aefa da''ö, ba banua Yeruzalema lafataro sanaro, ifaigi nahania zamösana ba gamaudu nomora.', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 4, 'Ba banua, ba no ebua, no ebolo, ba niha, ba lö ato sibai, ba so na nomo si lö mufuli mutaru''ö na.', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 5, 'Ba ibe''e ba dödögu Lowalangi ufalukha''ö zalaŵa ba satua, awö niha sato, ba wamazökhi sura nga''ötö. Ba usöndra zura nga''ötö zi föföna so moroi si tou, si mane ba zura andrö:', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 6, 'Da''e mbanua ba danö mado Yuda, si so moroi si tou, moroi ba ni''oloi''ö ya''ira, ni''oloi''ö Nebukaneza, razo Mbabeli, si no möi misi yaŵa ba Yeruzalema ba ba danö mado Yuda; isaŵa mbanuara zamösana,[1]', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 7, 'si fao khö ndra Serubabeli, Yesua, Nehemia, Asaria, Ra''amia, Nahemani, Marodokhai. Bilisana, Misifereti, Bigewai, Nehumi, Ba''ana. Fa''ato ndra matua Ndraono Gizeraeli, ba', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 8, 'Ma''uwu Wareo, ba 2.172.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 9, 'Ma''uwu Zefatia, ba 372.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 10, 'Ma''uwu Ara, ba 652.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 11, 'Ma''uwu Wahata-Moabi, nga''ötö ndra Yesua Yoabi, ba 2818.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 12, 'Ma''uwu Gelama, ba 1.254.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 13, 'Ma''uwu Zatu, ba 845.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 14, 'Ma''uwu Zakai, ba 760.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 15, 'Ma''uwu Mbinui, ba 648.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 16, 'Ma''uwu Mbebai, ba 628.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 17, 'Ma''uwu Asigada, ba 2.322.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 18, 'Ma''uwu Gadonika, ba 667.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 19, 'Ma''uwu Mbigewai, ba 2.067.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 20, 'Ma''uwu Gadino, ba 655.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 21, 'Ma''uwu Gateri, banua Hisikia, ba 98.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 22, 'Ma''uwu Hasumi, ba 328.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 23, 'Ma''uwu Mbesai, ba 324.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 24, 'Ma''uwu Harifo, ba 112.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 25, 'Ma''uwu Gibeona, ba 95.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 26, 'Ba banua Mbetilekhema ba banua Netofa, ba 188.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 27, 'Ba banua Ganatoti, ba 128.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 28, 'Ba banua Mbeti-Asimaweti, ba 42.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 29, 'Ba banua Giriati-Yeari ba banua Gafira ba banua Mbe''eroti, ba 743.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 30, 'Ba banua Rama ba banua Geba, ba 631.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 31, 'Ba banua Mikhimasi, ba 122.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 32, 'Ba banua Mbetieli ba banua Ga''i, ba 123.', '["Eser 2","Eser 2:63"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475430, 'OT', 'Nehemia', 7, 33, 'Ba banua Nebo, ba 52.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 34, 'Ba ma''uwu Gelama si samösa, ba 1254.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 35, 'Ba ma''uwu Harimi, ba 320.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 36, 'Ba banua Yerikho, ba 345.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 37, 'Ba banua Lodo ba banua Hadidi ba banua Gono, ba 721.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 38, 'Ba banua Zena''a, ba 3.930.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 39, 'Ba ere: Ma''uwu Yedaya si sawu ndra Yesua, ba 973.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 40, 'Ba ma''uwu Imeri, ba 1.052.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 41, 'Ba ma''uwu Wasuri, ba 1.247.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 42, 'Ba ma''uwu Harimi, ba 1.017.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 43, 'Ba Ono Lewi: Ma''uwu ndra Yesua Kadimieli, nga''ötö Hodeya, ba 74.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 44, 'Ba sanunö: Ma''uwu Gasafo, ba 148.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 45, 'Ba sanaro ba mbawandruhö: Ma''uwu ndra Salumi, Ateri, Talamono, Akubu, Hatita, Sobai, ba 138.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 46, 'Ba sangai halöŵö ba gosali: Ma''uwu ndra Siha, Hasufa, Taba''oto,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 47, 'Kero, Sia, Fadona,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 48, 'Lebana, Hagaba, Salamai,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 49, 'Hanano, Gideli, Gahara,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 50, 'Reaya, Resino, Nekoda,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 51, 'Gasama, Usa, Fasea,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 52, 'Besa''i. Ba ma''uwu mbanua Moini andrö ba ma''uwu mbanua Nefisi.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 53, 'Ba ma''uwu ndra Bakibuku, Hakufa, Harihuri,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 54, 'Baseliti, Mehida, Haresa,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 55, 'Barako, Sisera, Tema,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 56, 'Nesia, Hatifa.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 57, 'Ba ma''uwu zawuyu Zelomo andrö: Ma''uwu ndra Sota''i Sofereti, Ferida,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 58, 'Ya''ala, Darako, Gideli,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 59, 'Sefatia, Hatili, Fokhereti-Hasibai, Amoni;', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 60, 'sangai halöŵö ba gosali, fefu, awö ma''uwu zawuyu Zelomo andrö, ba no 392.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 61, 'Ba da''e na zi möi miyaŵa göi, si oroi Deli-Mela ba Teli-Haresa ba Kherubi ba Adono ba Imeri, si lö mangila ha niha duara ba ha nga''ötö ira, na Iraono Gizeraeli ira, ba na tenga:', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 62, 'Ma''uwu ndra Delaya, Tobia, Nekoda, 642 fefu.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 63, 'Ba ere: Ma''uwu ndra Habaya, Hakosi, Barasilai andrö, si no mangai ono Mbarasilai, banua Gileadi, ba si no mube''e töi töi da''ö.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 64, 'La''alu-alui zura nga''ötö khöra da''ö, ba lö lasöndra, andrö wa lö tetehe ere ira.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 65, 'Ba lö itehe khöra kumandru sumange ni''amoni''ö sibai andrö, irege ifuli so gere solau "Urimi" ba "Tumimi" andrö.[2]', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 66, 'Ba ya''ira fefu, ba no 42.360 niha, lö lai zawuyu,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 67, 'ira matua ba ira alawe, no 7.337 da''ö; ba baero ö na, ba 245 zanunö, ira matua ba ira alawe.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 68, 'Ba kudo khöra, ba 736, ba kudo kalide, ba 245,', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 69, 'ba ondra, ba 435, ba kalide, ba 6.720.', '["Eser 2","Eser 2:63"]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 70, 'Ba so ösa, högö ngafu andrö, same''e saoha gölöra, balazo gosali. Ibe''e kumandru, balazo da''ö: ana''a, ba 1.000 hua balaki ba 50 wiga, ba wanefe, ba 30 nga''örö mbaru gere.', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 71, 'Ba nibe''e högö ngafu andrö ösa, balazo da''ö, ba ana''a, ba 20.000 hua balaki, ba firö, ba 161.700 ba rufia.', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 72, 'Ba nibe''e zato, ba ana''a, ba 20.000 hua balaki ba firö, ba 147.000 ba rufia, ba 67 nga''örö mbaru gere.', '[]', NULL),
  (3475430, 'OT', 'Nehemia', 7, 73, 'Ba oi ba mbanuara so ira, he ere ba he Ono Lewi ba he sanaro ba mbawandruhö ba he sanunö, awö niha sato ösa, ba he sangai halöŵö ba gosali ba Iraono Gizeraeli fefu.', '[]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 1, 'Ba me irugi baŵa si fitu, me no so ba mbanuara Ndraono Gizeraeli, ba owulo niha sato ha sara dödö, ba golayama sebolo, fönaföna mbawa göli ba nidanö. Ba la''andrö khö Gesera sangila amakhoita, ena''ö ihalö zura goroisa andrö khö Moze, sura niŵa''ö Lowalangi ba Ndraono Gizeraeli.', '["Nga''ötII 34:30"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 2, 'Ba i''ohe zura goroisa Esera ere, ba zi falukha andrö, ira matua ba ira alawe, awö dozi si biha tödö, ba wamondrondrongo, ba zi sambua desa''a, ba mbaŵa si fitu.[1]', '["Nga''ötII 34:30"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 3, 'Ba ibaso, ba golayama andrö, fönaföna mbawa göli ba nidanö, i''otarai zi hulö wongi, irugi laluo, ba zi so ira matua ba ira alawe, awö zaboto ba dödö sa''ae, ba lafondrongondrongo Iraono Gizeraeli fefu niŵa''ö ba zura goroisa andrö.', '["Nga''ötII 34:30"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 4, 'Ba ba harehare eu yaŵa so Gesera sangila amakhoita, harehare nifa''anöra nahania, ba ba ngainia so ndra Matitia. Sema, Anaya, Uria, Hilikia, Ma''aseya, ba gambölö; ba ba gaberania ba ira Fedaya, Mizaeli, Malakhia, Hasumi, Hasibadana, Sakharia, Mesula.', '["Nga''ötII 34:30"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 5, 'Ba ibokai zura Esera, ba zanehe niha sato fefu — no alaŵa nahania, moroi ba zi so niha sato fefu —, ba me ibokai zura, ba muzizio niha sato fefu.', '["Nga''ötII 34:30"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 6, 'Ba isuno Yehowa, Lowalangi sebua, Esera, ba ladedema niha sato, lamane: Ya duhu, ya duhu! ba lafazaŵa dangara ba da''ö ba lafaöndrö ira, ba lafalögu tou ira ba danö, föna Yehowa.', '["Nga''ötII 34:30"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 7, 'Ba labotokhi ba dödö zato goroisa ira Yesua, Bani, Serebia, Yamini, Akubu, Sabata''i, Hodia, Ma''aseya, Kelita, Asaria, Yosabada, Hanano, Felaya, Ono Lewi andrö, ba si lö tebulö ba nahara niha sato.', '["Nga''ötII 34:30"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 8, 'Ba lahaogö wombaso sura goroisa Lowalangi, ba labotokhi geluaha, ba tobali aboto ba dödöra.', '["Nga''ötII 34:30"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 9, 'Ba Nehemia kumandru ba Esera ere, sangila amakhoita, ba Ono Lewi andrö, samahaö niha, ba lamane ba niha sato fefu: Baŵa ni''amoni''ö khö Lowalangimi Yehowa ma''ökhö; böi mi''angarö-ngarö ba böi mi''ege-ege! Noa sa mege-ege niha sato fefu, me larongo daroma li, oroisa andrö.', '["MozI 16:11"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 10, 'Ba imane khöra: Mi''ae''e, mi''a zatabö ba mibadu zami, ba mifo''urakha zi lö''ö, me no baŵa ni''amoni''ö khö zokhö ya''ita ma''ökhö. Andrö böi abu dödomi, me no fangabe''eda wa''omuso dödöda andrö ba khö Yehowa![2]', '["MozI 16:11"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 11, 'Ba larara göi dödö niha sato fefu Ono Lewi, lamane: Mihonogö ami, me no baŵa ni''amoni''ö ma''ökhö, andrö böi abu dödömi!', '["MozI 16:11"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 12, 'Ba möi manga ira fefu, ba ba wama''ohe''ö urakha ba nawöra; amaedola gowasa sebua lalau, somuso dödöra, noa sa latöngöni nibotokhi ba dödöra.', '["MozI 16:11"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 13, 'Ba mahemolu ö, ba falukha högö ngafu zato fefu ba ere ba Ono Lewi, khö Gesera sangila amakhoita, ba wamondrongo na taroma li, oroisa.', '["MozIII 23:34","Nga''ötII 34:18"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 14, 'Ba lasöndra ba zura goroisa andrö, nifaŵa''ögö Yehowa khö Moze, wa ose daha geu la''iagö Iraono Gizeraeli ba mbongi gowasa andrö, ba mbaŵa si fitu,[3]', '["MozIII 23:34","Nga''ötII 34:18"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 15, 'awö wa labe''e li ba mbanua misa khöra fefu ba ba Yeruzalema, wa lamane: Mi''ae ba hili ba mihalö ndraha falo ba daha falo ndru''u ba daha malimbi ba bulu nandrulo ba daha geu si fadege bulu na, ba wolau ose daha geu, dali nifakhoi andrö.', '["MozIII 23:34","Nga''ötII 34:18"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 16, 'Ba möi baero ira, lahalö ndraha geu, ba labali''ö ose khöra; ba dete nomonia ilau zamösana, ba ba golayama khöra, ba ba golayama gosali Lowalangi, ba ba golayama sebolo andrö, fönaföna mbawa göli ba nidanö ba fönaföna mbawa göli ba mado Geferayi.', '["MozIII 23:34","Nga''ötII 34:18"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 17, 'Ba dozi niha, ha wa''ato ira, si no mangawuli moroi ba ni''oloi''ö ya''ira mege, ba solau ose daha geu ba ba da''ö la iagö. Lö''ö sa nilau Ndraono Gizeraeli si manö, i''otarai luo Yosua, ono Nuni, irugi luo da''ö; ba tobali omuso sibai dödöra.[4]', '["MozIII 23:34","Nga''ötII 34:18"]', NULL),
  (3475431, 'OT', 'Nehemia', 8, 18, 'Ba la''erogö ma''ökhö wombasombaso sura goroisa Lowalangi, ha uga mbongi gowasa andrö. Ba fitu bongi wa''ara lalau gowasa andrö, ba me luo si ŵalu, ba owuloa sebua, dali nifakhoi.', '["MozIII 23:34","Nga''ötII 34:18"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 1, 'Ba ba zi dua wulu a öfa ba mbaŵa da''ö, ba owulo Ndraono Gizeraeli, mamoni ba gö ira ba baru gonigoni mbarura, ba no lalau gawu-gawu ba högöra.[1]', '["Yon 3:5"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 2, 'Ba la''oniagö ira ba niha bö''ö fefu nga''ötö Ndraono Gizeraeli, ba so ira ba la''ombakha''ö horö, fabaya lalö ndra tuara mege.', '["Yon 3:5"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 3, 'Ba muzizio ira ba nahara andrö, ba so zombaso sura goroisa Lowalangira Yehowa, matonga zi matonga luo wa''ara, ba matonga zi matonga luo göi wa''ara wangombakha''öra horöra, ba lafalögu tou ira föna Lowalangira Yehowa.', '["Yon 3:5"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 4, 'Ba ba harehare andrö ia''agö Ono Lewi, ira Yesua, Bani, Kadimieli, Sebania, Buni, Serebia, Bani, Khenani, ba la''angaröfi li Lowalangira Yehowa, la''ebua''ö lira.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 5, 'Ba humede Nono Lewi andrö, ira Yesua, Bani, Kadimieli, Hasabineya, Serebia, Hodia, Sebania, Fetaya, lamane: "Mifaoso, misuno Yehowa, Lowalangimi, götö-götö wa''ara? Ba nisuno döimö andrö, sebua turia, si no manalu''i fangandrö saoha gölö fefu, awö wanuno!', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 6, 'Ha ya''ugö, Yehowa; no ya''ugö zamazökhi banua si yaŵa, banua si yaŵa irugi ba wondrege, awö ngahönö andrö khönia, ba tanö, awö nösi guli danö fefu, ba asi, awö nosinia fefu, ba oi ya''ugö zangorifi, ba no sangalulu khöu ngahönö andrö ba mbanua si yaŵa.[2]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 7, 'No ya''ugö, Yehowa, Lowalangi, sanuyu mege Aberamo, sangeheta ya''ia ba Guri ba danö Galedaia, same''e töinia Aberahamo andrö.[3]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 8, 'Ba me no ö''ila dödönia, wa no si tebai faröi khöu, ba no öfabu''u sibai khönia, öbe''e ba ma''uwunia danö Ndrawa Gana''ana andrö ba tanö Ndraono Kheti ba tanö Ndraono Gamori ba tanö Ndraono Weresi ba tanö Ndraono Yebusi ba tanö Ndraono Girigasi, ba no ötörö nifabu''umö, me no satulö ndra''ugö.[4]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 9, 'Ba me ö''ila wamakao ndra tuama ba danö Miserayi, ba fangarö-ngaröra ba mbewe nasi zukhu,[5]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 10, 'ba ölau zahöli-höli dödö ba ila-ila khö Wara''o ba ba genoninia fefu ba ba mbanua ba danönia fefu, me no ö''ila, wa no lafakao ira [ndra tuama]; ba no ö''ebua''ö döimö, irugi ma''ökhö andre.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 11, 'Ba asi, ba öfabali fönara, tobali latörö dalu, abe''e lalara; ba solohi ya''ira, ba ötibo''ö ba namö, hulö gara, ba zabölö hou.[6]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 12, 'Ba öfasao ira boto lawuo na ma''ökhö ba boto galitö ba zi bongi, ba wohagaini lalara nitöröra.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 13, 'Ba möi''ö tou, ba hili Zina''i, humede ndra''ugö khöra, moroi ba zorugo, öbe''e khöra huku satulö ba oroisa si ndruhu; amakhoita ba oroisa si sökhi öbe''e khöra.[7]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 14, 'No ö''ombakha''ö khöra luo sabato andrö khöu, ni''amoni''ö, ba oroisa ba amakhoita ba huku öfaŵa''ögö khöra khö genoniu Moze.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 15, 'Ba no öbe''e khöra kue moroi ba mbanua si yaŵa, ba wa''olofora, ba idanö öfangumbu ba gara, me owökhi dödöra. Ba no öŵa''ö khöra we''amöi ba danö andre, ba wangokhögö ya''ia, nifabu''umö khöra, öbe''e khöra, me ö''oro''ö dangau [ba wahölusa].[8]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 16, 'Ba ira tuama, ba fayaŵa ba no abe''e mbörö du''i, ba lö la''o''ö goroisamö andrö.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 17, 'No tekhöra wamondrongo, ba lö itörö tödöra zahöli-höli dödö andrö, nilaumö khöra mege, manandro ira ba latuyu zolohe ya''ira, ba wangawuli ba wa''asawuyu ba danö Miserayi. Ba no Lowalangi somasi mame''e aefa horö ndra''ugö, ba sebua tödö, ba sahakhö tödö ba sebolo tödö, ba si fahöna fa''asökhi dödö [ba niha] ba lö ni''erogöu ya''ira.[9]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 18, 'Ba he me lafazökhi nono zaŵi nifahele ba me lamane: Da''ö Lowalangimi, sangeheta ya''ami ba danö Miserayi mege, me la''abölögö wango''aya [ya''ugö],[10]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 19, 'ba no lö ni''erogöu ya''ira ba danö si mate, ba wa''ahakhö dödöu andrö, si no ebua: lö saheta khöra mboto lawuo andrö ba zi ma''ökhö, ba wamasao ya''ira ba lalara, ba he boto galitö andrö, ba zi bongi, ba wohagaini lalara, nitöröra.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 20, 'Ba no öbe''e khöra Gehehamö andrö, si sökhi ba wamahaö ya''ira, ba lö nibödau ba mbawara "mana" andrö, ba no öbe''e göra idanö, na owökhi dödöra.[11]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 21, 'Ba no örorogö ira ba danö si mate, öfa wulu fakhe wa''ara, tobali lö ambö khöra hadia ia; lö sadudu nukhara ba lö sabao gahera.[12]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 22, 'Ba no öbe''e khöra gamatöröŵa [niha bö''ö] ba soi [bö''ö]; ba no öfaosa da''ö, öhonogöi nola, ba la''okhögö danö Zihona andrö, tanö razo Hesibona, ba tanö Ogi andrö, razo Mbazana.[13]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 23, 'Ba no ö''oya''ö nga''ötöra, no timba ndröfi ba mbanua si yaŵa wa''oya öbe''e, ba no ö''ohe ba danö andrö nituturu tanöra, ba wangokhögö ya''ia, dali nifabu''umö khö ndra tuara.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 24, 'Ba iraonora zondrugi, ba la''okhögö danö andrö, ba öbe''e barö mbawara niha ba danö, Dawa Gana''ana andrö, öbe''e ba dangara ira, he razora, ba he niha sato ba danö, ena''ö balazi manö ira, he lawisa khöra.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 25, 'Ba atu''a ira ba mbanua saro, ba la''okhögö danö, satabö sinanö, fabaya omo niha, ba zi no fahöna ngawalö gama-gama, ba he ba''a nikhau ba kabu nagu ba kabu zai ba eu sowua, wa''oya. Ba manga-manga ira, ba abuso ba esolo, la''omusoi''ö dödöra ba wa''oböwömö andrö.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 26, 'Ba manandro ira, ba lalaŵa ndra''ugö, ba la''erogö goroisamö andrö; ba sama''ele''ö andrö, sanenaŵa ya''ira, ba wolohe mangawuli ya''ira khöu, ba labubunu, ba la''abölögö wanandraŵaisi [ya''ugö].', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 27, 'Ba öbe''e ira ba danga zamakao ya''ira; ba lafakao ira. Ba na no tosasa ira, ba la''angaröfi li ndra''ugö, ba öfondrondrongo lira, moroi ba zorugo, ba ö''asogö khöra zangorifi, ba wa''ahakhö dödöu andrö, si no ebua, ena''ö da''ö zangefa''ö ya''ira ba danga zamakao ya''ira.[14]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 28, 'Ba ha si''aikö lö hadia ia khöra sa''ae, ba lafuli lalau zi lö sökhi fönau, ba öfuli ölulu ira ba danga nemalira, ena''ö da''ö zalaŵara. Ba lafuli la''angaröfi li ndra''ugö, ba öfondrondrongo lira, moroi ba zorugo, ba ö''orifi ira, ba wa''ahakhö dödöu andrö si no ebua, ha me uga.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 29, 'Ba öfangelama ira, ena''ö lafuli la''o''ö goroisamö; ba no si fayaŵa ira, ba lö lafondrondrongo goroisamö, ba lasawö nifakhoimö andrö, nibe''e fangorifi zolo''ö ena''ö. No abe''e mbörö du''ira, la''erogö ndra''ugö, manandro, lö lafondrondrongo liu.[15]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 30, 'Ba sebolo tödö ndra''ugö khöra, ha me uga fakhe, ba öfangelama ira Ehehamö, nifa''ema zama''ele''ö andrö, ba lö''ö zui lafondrondrongo. Ba öbe''e ira ba danga niha ba danö, niha baero,[16]', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 31, 'ba ba wa''abölö wa''ahakhö dödöu andrö, ba lö öhori ira, ba lö öfalua wangerogö ya''ira, me no Lowalangi sebua tödö ba sahakhö tödö ndra''ugö.', '["MozI 1:1; MozV 10:14; Sin 146:6","MozI 11:31; 17:5","MozI 15:6; 12:7","MozII 3:7; 14:10","MozII 15:10","MozII 19:20","MozII 16:15; 17:6","MozIV 14:4; MozII 34:6","MozII 32","MozII 11:17","MozV 2:7; 8:4","MozIV 21:21 b.t.","Sanguhuk 2:14","MozIII 18:5","RazII 17:13; Nga''ötII 36:15"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 32, 'Ba iya''e, ya''ugö Lowalangima, Lowalangi sebua ba sabölö ba sata''u niha, si lö mamöhöi fawu''usa li, fa''ebua dödö andrö, böi bali ambö fa''ebua wamakao andrö fefu, si no göna ndra''aga, he razoma, ba he satuama, ba he ere, ba he sama''ele''ö andrö khöma, ba he ira tuama ba banuau andrö fefu, i''otarai luo razo Ndrawa Asiria andrö, irugi ma''ökhö andre.', '["MozV 32:4; Dan 9:14"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 33, 'Ba no dörödöro satulö ndra''ugö, ba da''ö fefu, si no göna ndra''aga; me no si lö faröi ndra''ugö, ba ya''aga, ba no sebua horö.[17]', '["MozV 32:4; Dan 9:14"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 34, 'Ba razoma ba satuama ba ere khöma ba ira tuama, ba no lö ni''o''öra oroisamö, ba lö nitöngönira amakhoitamö ba famaroumö tödöra.', '["MozV 32:4; Dan 9:14"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 35, 'Ba he ŵa''ae ba danöra so ira, nifa''u''u howu-howu sebua andrö, nibe''eu khöra, bualau, ba danö sebolo andrö, satabö sinanö, niteheu khöra, ba lö''ö zui laföndrondrongo limö, ba lö laböhöli mbua-buara si lö sökhi andrö.', '["MozV 32:4; Dan 9:14"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 36, 'Hiza, ya''aga andre, ba no sawuyu iya''e, ba tanö andre, nibe''eu khö ndra tuama, ena''ö la''a mbuania, awö zi sökhi andrö khönia — ba danö da''ö no sawuyu ndra''aga.', '["MozV 32:4; Dan 9:14"]', NULL),
  (3475432, 'OT', 'Nehemia', 9, 37, 'Buania sabölö andrö, ba no razo andrö, nibe''eu barö mbawa ya''aga — börö horöma andrö — zi manga; ya''ira zamatörö botoma ba uriföma, ba zomasi ira, ba no tobali sebua famakao ndra''aga."', '["MozV 32:4; Dan 9:14"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 1, 'Ba mafabu''u lima — börö da''ö no mege fefu — ba mabe''e dandro tanga. Ba ba nifotandro andrö, ba so döi zalaŵama ba töi Nono Lewi ba töi gere khöma.', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 2, 'Da''e döi ba zura nifotandro andrö: Nehemia kumandru, ono Hakalia ba Sedekia,', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 3, 'ba Seraya ba Asaria ba Yeremia', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 4, 'ba Fasuri ba Amaria ba Malakhia', '["Eser 2:70"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475433, 'OT', 'Nehemia', 10, 5, 'ba Hatusi ba Sebania ba Malukhi', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 6, 'ba Harimi ba Meremoto ba Obadia', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 7, 'ba Danieli ba Ginitono ba Barukhi', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 8, 'ba Mesula ba Abia ba Miyanini', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 9, 'ba Ma''asia ba Biligai ba Semaya; da''ö gere andrö.', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 10, 'Ba Ono Lewi: Yesua, ono Asania, ba Binui, ma''uwu Henadada,', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 11, 'ba Kadimieli ba talifusöra: Sebania ba Hodia ba Kelita ba Felaya ba Hanano', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 12, 'ba Mikha ba Rehobo ba Hasabia', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 13, 'ba Sakuru ba Serebia ba Sebania', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 14, 'ba Hodia ba Bani ba Beninu.', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 15, 'Ba högö mbanua: Fareo ba Fahata-Moabi ba Elama ba Satu ba Bani', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 16, 'ba Buni ba Asigada ba Bebai', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 17, 'ba Adonia ba Bigiwai ba Adini', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 18, 'ba Ateri ba Hisikia ba Asuri', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 19, 'ba Hodia ba Hasumi ba Besai', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 20, 'ba Harifi ba Anatoti ba Nobai', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 21, 'ba Magifia ba Mesula ba Hesiri', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 22, 'ba Mesesabe''eli ba Sadoki ba Yadua,', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 23, 'ba Felatia ba Hanano ba Anaya,', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 24, 'ba Hosea ba Hanania ba Hasubi', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 25, 'ba Halohe ba Filiha ba Sobeki', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 26, 'ba Rehumi ba Hasabena ba Ma''aseya', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 27, 'ba Ahia ba Hanano ba Anani', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 28, 'ba Malukhi ba Harimi ba Ba''ana.', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 29, 'Ba ha niha baero ö na — ere ba Ono Lewi ba sanaro ba mbawandruhö ba sanunö ba sangai halöŵö ba gosali, ba ha niha na fefu, si no mamabali ya''ira ba niha [baero] ba danö, wolo''ö oroisa Lowalangi —, ba fo''omora ba iraonora, matua ba alawe, ba dozi si no biha fa''ebua, fa aboto ba dödöra.[1]', '["Eser 2:70"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 30, 'Ba fao ba dalifusöra salaŵa, ba möi ba hölu, wamabu''u lira, wa edöna latörö lala goroisa Lowalangi andrö, nifa''ema Moze, enoni Lowalangi, wa edöna latöngöni goroisa Yehowa, So''aya ya''ita, fefu, awö huku, awö gamakhoita fefu, wa edöna la''o''ö;[2]', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 31, 'ya''ia wa lö mabe''e ba niha [baero] ba danö nonoma alawe, awö wa lö mahalö umönöma nonora;', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 32, 'awö wa lö mahalö ba luo sabato, ba ma ba luo bö''ö ni''amoni''ö, na la''ohe niha ba danö waniaga ba ma bua danö hadia ia ngawalö, ni''amawa. Ba ero mewitu fakhe, ba lö mahalö nowi, ba lö masugi zugilöma.[3]', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 33, 'Ba mahonogöi na ömöma, öfa hua döfi mabe''e soguna ba gosali Lowalangima,[4]', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 34, 'böli roti nifaigi-faigi andrö, ba böli zumange ni''a andrö, nibe''e-be''e, fabaya sumange nitunu, si lö aefa-aefa ba he sumange ba luo sabato ba ba wasulöna ba sumange ba gowasa, ba sumange fangandrö saoha gölö ba sumange fameta hörö, ba wameta horö Ndraono Gizeraeli, ba balazo hadia ia fefu ni''a''azökhi ba gosali Lowalangima.', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 35, 'Ba malau dahö-dahö, ya''aga ba ere, ba Ono Lewi ba sato, ba game''ela eu andrö, ena''ö sawu-sawu zame''e, ero röfi, na inötö, ba gosali Lowalangima, eu ba naha wame''e sumange khö Lowalangima Yehowa, dali nifakhoi ba zura goroisa.[5]', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 36, 'Ba si a''a mbua nowi khöma ba si a''a mbua geu fefu, hadia ia ngawalö geu sowua nibe''e ba gosali Yehowa, ero röfi;[6]', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 37, 'ba si a''a nonoma matua ba si a''a nono guriföma, dali nifakhoi ba goroisa, si a''a nono zaŵima ba si a''a nono mbiri-birima, nibe''e ba gosali Lowalangima, ba danga gere, sangai halöŵö andrö ba nomo Lowalangima.[7]', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 38, 'Ba he si a''a hamo andrö khöma ba si a''a zumange nihalö fegero saoha gölö andrö khöma ba si a''a mbua geu fefu ba si a''a nagu ba si a''a wanikha, nibe''e ba gere andrö ba mbate''e andrö ba gosali Lowalangima, ba sambua ni''ofulu danö nowima nitehe ba Nono Lewi; ya''ira, Ono Lewi sa, ba sangozaragö si sambu-sambua ni''ofulu ba mbanua zangahalö khöma, fefu.[8]', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 39, 'Ba si so göi gere andrö, nga''ötö Ga''aroni, na la''ozaragö zi sambu-sambua ni''ofulu andrö Ono Lewi, ba Ono Lewi, ba sambu-sambua ni''ofulu zi sambu-sambua ni''ofulu la''ohe ba gosali Lowalangima, ba mbate''e andrö ba nomo girö-girö labe''e.[9]', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475433, 'OT', 'Nehemia', 10, 40, 'Ba mbate''e andrö sa labe''e Iraono Gizeraeli ba Ono Lewi saoha gölöra bua nowi ba agu ba fanikha, me no ba da''ö so nahia hadia ia ba ni''amoni''ö, ba ere sangai halöŵö ba sanaro ba mbawandruhö ba sanunö; ba lö ma''ositengagö gosali Lowalangima andrö.', '["Yos 24:25; Sin 119:106","MozII 20:10; 23:11; Faigi 13:15,16; Amos 8:5","RazII 12:14","MozIII 6:12","MozII 23:19","MozII 13:12","MozIII 23:17; MozIV 15:19; 18:24","MozIV 18:26"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 1, 'Ba ba Yeruzalema so zalaŵa; ba niha sato, ba fadahö-dahö, ena''ö samösa ba zi dafulu lafa''aso yomo ba da''ö [göi], ena''ö ba Yeruzalema, ba mbanua ni''amoni''ö andrö, so ia, ba si dasidasiŵa, ba ba mbanua bö''ö lafa''aso.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 2, 'Ba lafahowu''ö sato fefu zaoha ölö, ba wangiagö Yeruzalema.[1]', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 3, 'Ba da''e zalaŵa ba danö, si so ba mbanua Yeruzalema ba ba mbanua mado Yuda — ba mbanuara so ira, i''iagö danönia zamösana: Iraono Gizeraeli ba ere ba Ono Lewi ba sangai halöŵö ba gosali ba ma''uwu zawuyu Zelomo andrö —:', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 4, 'Ba Yeruzalema, ba faoma so, he mado Yuda, ba he mado Mbeniyami. Mado Yuda ba Ataya, ono Usia ono Zakharia ono Gamaria ono Zefatia ono Mahalale''eli, nga''ötö Weresi,', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 5, 'ba Ma''aseya ono Mbarukhi ono Kholi-Hose ono Hasaya ono Gadaya ono Yoyaribi ono Zakharia ono ma''uwu Zela andrö.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 6, 'Fa''ato nga''ötö Weresi fefu, si so ba Yeruzalema, ba no 468, solohe baluse.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 7, 'Ba mado Mbeniyami, ba Salu ono Mesula ono Yudi ono Wedaya ono Golaya ono Ma''aseya ono Itieli ono Yesaya,', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 8, 'ba aefa da''ö ba Yibineya, 928 fefu.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 9, 'Ba Yoeli ono Zikhiri zatuara, ba satua mbanua, tambalinania, ba Yuda, ono Hasinua.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 10, 'Ba ere, ba Yedaya ba Yoyaribi ba Yakhino; ba Seraya,', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 11, 'ono Hilikia ono Mesula ono Zadoki ono Merayoti ono Gahitubi, da''ö högö [gere] ba gosali Lowalangi,[2]', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 12, 'ba talifusöra sangai halöŵö ba gosali, 822 fefu, ba Adaya, ono Yeroha ono Welalia ono Gamisi ono Zakharia ono Wasuri ono Malakhia,', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 13, 'ba talifusönia, högö ngafu, 242 fefu, ba Amasai, ono Gasare''eli ono Gaza''i ono Mesilemoto ono Imeri,', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 14, 'ba talifusöra, niha sabölö, 128 fefu.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 15, 'Högöra Zabidieli, ono Hagedoli. Ba ono Lewi, ba Semaya, ono Hasubi ono Gasirika ono Hasabia, nga''ötö Merari,', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 16, 'ba Sabata''i ba Yosabada, samaigi-maigi halöŵö baero andrö, ba gosali Lowalangi, högö ngafu ba Nono Lewi,[3]', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 17, 'ba Matania ono Mikha ono Zabidi ono Gasafo, samatörö fanunö andrö samobörö "mi''andrö saoha gölö" andrö ba wangandrö, ba Bakibukia, tambalina andrö ba dalifusönia, ba Abada, ono Zamua ono Galala ono Yedutuno,', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 18, 'a''oi Ono Lewi ba mbanua ni''amoni''ö andrö, 284 fefu.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 19, 'Ba sanaro ba mbawandruhö, ba Akubu ba Talamono ba talifusöra, sanaro ba mbawandruhö andrö, 172 fefu.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 20, 'Ba Iraono Gizeraeli bö''ö, ere ba Ono Lewi, ba ba mbanua bö''ö misa so ba mbanua mado Yuda; tanönia i''iagö zamösana.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 21, 'Ba sangai halöŵö ba gosali, ba ba Gofeli andrö so nomora, ba mandrura Ziha ba Gisifa.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 22, 'Ba satua Nono Lewi ba Yeruzalema, ba Usi, ono Mbani ono Hasabia ono Matania ono Mikha, nga''ötö Gasafo, sanunö, ba nilau-lau ba gosali Lowalangi.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 23, 'Noa sa ibe''e goroisa razo, ba khöra andrö, wamabu''u sibai ba zanunö andrö, tebe''e khöra zoguna khöra, ero ma''ökhö.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 24, 'Ba Fetaya, ono Mesesabe''eli, nga''ötö Zera, ono Yuda, nifataro razo ba wamatunö huhuo niha sato fefu.', '["Ayati 3–12: Nga''ötI 9:2–17","Nga''ötII 31:13","Nga''ötI 26:19"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 25, 'Ba ba mbanua side-ide andrö, ba danöra misa, ba ba Giriati-Araba ba ba halama soya khöra so mado Yuda ösa, ba ba Dibona ba ba halama soya khöra, ba ba Yekabise''eli ba ba halama soya khöra,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 26, 'ba ba Yesua ba ba Molada ba ba Mbetifeleti,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 27, 'ba ba Hasara Zuala ba ba Mbereseba ba ba halama soya khöra,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 28, 'ba ba Zikelagi ba ba Mekhona ba ba halama soya khöra,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 29, 'ba ba Eni Rimono ba ba Zorea ba ba Yaramuti,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 30, 'ba ba Zanoa ba ba Adula ba ba halama khöra, ba ba Lakhisi ba ba mbenuara ba ba Aseka ba ba halama soya khöra. Tobali i''otarai Mbereseba, irugi ndraso Hinomo la''iagö.', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 31, 'Ba mado Mbeniyami, ba ba Geba ba ba Mikhimasi ba ba Naya ba ba Mbetieli ba ba halama soya khöra,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 32, 'ba ba Ganatoti ba ba Nobi ba ba Ganania,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 33, 'ba ba Hasora ba ba Rama ba ba Gita''i,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 34, 'ba ba Hadidi ba ba Zebo''i ba ba Nebalati,', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 35, 'ba ba Lodi ba ba Gono, ba ndraso duka andrö.[4]', '["Nga''ötI 4:14"]', NULL),
  (3475434, 'OT', 'Nehemia', 11, 36, 'Ba Ono Lewi, ba ba mado Yuda ösa ba ba mado Mbeniyami ösa.', '["Nga''ötI 4:14"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 1, 'Ba da''e döi gere ba töi Nono Lewi, si no fao khö ndra Serubabeli, ono Zelatieli, Yesua, moroi si tou: Seraya ba Yeremia ba Esera,[1]', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 2, 'ba Amaria ba Malukhi ba Hatusi', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 3, 'ba Sekhania ba Rehumi ba Meremoto,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 4, 'ba Ido ba Ginitoi ba Abia,[2]', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 5, 'ba Miyamini ba Ma''adia ba Biliga', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 6, 'ba Semaya ba Yoyaribi ba Yedaya', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 7, 'ba Salu ba Amoki ba Hilikia ba Yedaya; da''ö högö gere ba högö dalifusöra, ba götö Yesua andrö.', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 8, 'Ba Ono Lewi, ba Yesua ba Binui ba Kadimieli ba Serebia ba Yuda ba Matania andrö, satua ba wanunö fangandrö saoha gölö, awö ndra talifusönia;', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 9, 'ba Bakibuki ba Uni, talifusöra, ba gamaudura, ngenoli samalamalali.', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 10, 'Ba ono Yesua, ba Yoyaki, ba ono Yoyaki, ba Eliasibi, ba ono Geliasibi, ba Yoyada,[3]', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 11, 'ba ono Yoyada, ba Yonata, ba ono Yonata, ba Yadua.', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 12, 'Ba me luo Yoyaki, ba da''e högö ngafu ba gere: Salahi Zeraya Merari ba salahi Yeremia Hanania,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 13, 'ba salahi Gesera Mesula ba salahi Gamaria Yohanano,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 14, 'ba salahi Malukhi Yonata ba salahi Zebania Yosefo,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 15, 'ba salahi Harimi Gadena, ba salahi Merayoti Helikai,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 16, 'ba salahi Ido Zakharia ba salahi Ginitono Mesula,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 17, 'ba salahi Gabia Zikhiri, ba so göi zalahi Miniyami, ba salahi Moadia Wilita''i,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 18, 'ba salahi Mbiliga Zamua ba salahi Zemaya Yonata,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 19, 'ba salahi Yoyaribi Matanai ba salahi Yedaya Usi,', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 20, 'ba salahi Zalai Galai ba salahi Gamoki Geberi', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 21, 'ba salahi Hilikia Hasabia ba salahi Yedaya Netane''eli.', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 22, 'Ba Ono Lewi: Ba götö ndra Eliasibi, Yoyada, Yohanano, Yadua tetanö ba zura högö ngafu ba ere, irugi razo Dario andrö, razo Ndrawa Weresia.[4]', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 23, 'Högö ngafu, ma''uwu Lewi nitanö ba zura hikaya, irugi götö Yohanano, ma''uwu Geliasibi.', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 24, 'Ba högö Nono Lewi, ba Hasabia ba Serebia ba Yesua ba Bani ba Kadimieli ba talifusöra, ba gamaudura, ba wanunö, fanunö fangandrö saoha gölö, dali nifakhoi Dawido, enoni Lowalangi, wa mamalamalali ngenoli andrö:[5]', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 25, 'Matania ba Bakibukia ba Obadia ba Mesula. Ba sanaro ba mbawandruhö Dalamono ba Akubi, sanaro ba mbate''e girö-girö andrö, ba mbawandruhö.[6]', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 26, 'Da''ö [högö ngafu] ba götö Yoyaki, ono Yesua ono Yosadaki, ba ba götö ndra Nehemia kumandru Esera ere sangila amakhoita.[7]', '["Eser 2:2","Luk 1:5","Ayati 1. 26. Faigi 3:1,20","Ayati 10,11","Nga''ötI 27:17; Nga''ötI 25; Nga''ötII 29:25","Faigi 11:17,19; Nga''ötII 8:14; Nga''ötI 26:15,17","Ayati 10; Nga''ötI 5:40,41; Faigi 5:14; Eser 7:1–6"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 27, 'Ba ba we''amoni''ö öli mbanua Yeruzalema, ba lafakaoni''ö Nono Lewi, ladozigö banua si so ira, ena''ö möi ira ba Yeruzalema, ena''ö owua-wua dödöra ba ena''ö mangandrö saoha gölö ira, ba we''amoni''ö andrö, wolau fanunö ba famözi faritia ba folau biola nitika, sebua ba side-ide.', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 28, 'Ba owulo ngenoli zanunö andrö, he öri Yeruzalema, ba öri Netofa,[8]', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475435, 'OT', 'Nehemia', 12, 29, 'ba he banua Mbeti Giligala ba banua Geba ba banua Asimaweti; noa sa ba zi tefasui Yeruzalema labe''e zi no amaedola halama soya khöra sanunö andrö.', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 30, 'Ba lahaogö ira ere ba Ono Lewi ba he niha sato, ba bawa göli ba öli, ba lahaogö.', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 31, 'Ba uŵa''ö möi ba göli yaŵa zatua mado Yuda, ba ufa''aso zangandrö saoha gölö, dua mbawa sebua, dua ngenoli: Si sambawa sangandrö saoha gölö, ba lasaŵa gambölö, mbawa göli golawua, tete göli lala,[9]', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 32, 'ba solo''ö moroi furi Hosaya ba si matonga zatua mado Yuda,', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 33, 'ba Asaria ba Esera ba Mesula,', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 34, 'mado Yuda ba mado Mbeniyami ba Semaya ba Yeremia, ba ere ösa,', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 35, 'si so torofe, ba Sakharia, ono Yonata ono Zemaya ono Matania ono Mikhaya ono Zaturu ono Gasafo;', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 36, 'ba talifusönia: Semaya ba Asare''eli ba Milalai ba Gilalai ba Ma''ai ba Netane''eli ba Yuda ba Hanani, solohe nifoli andrö, khö Dawido, enoni Lowalangi; ba föna so Gesera sangila amakhoita.[10]', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 37, 'Ba lasaŵa mbawa göli ba gumbu, ba ladölö ira miyaŵa, latöro nibosi andrö, ba mbanua Dawido, ba zanösö ba göli, yaŵa gödo Dawido, ba larugi mbawa göli ba nidanö tanö ba gatumbukha luo.[11]', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 38, 'Ba si sambawa sangandrö saoha gölö, ba ba gabera lasaŵa, ba ya''odo zolo''ö da''ö, awö zi matonga zato, ba dete göli, matörö malige "danuri" andrö, marugi göli sawe''e-we''e andrö,[12]', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 39, 'ba matörö mbawa göli ba mado Geferayi ba bawa göli ba mbanua satua ba bawa göli gi''a ba malige Hanane''eli ba malige Mea, ba marugi mbawa göli mbiri-biri, ba la''iagö zinga mbawa göli ba gurunga.', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 40, 'Ba tobali ba ngai gosali Lowalangi so zangandrö saoha gölö andrö, si dua mbawa, ba so göi ndra''o ba si matonga zatua, awögu,', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 41, 'ba ere andrö Eliaki ba Ma''aseya ba Miniami ba Mikhaya ba Eliunai ba Sakharia ba Hanania, si so torofe,', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 42, 'ba Ma''aseya ba Semaya ba Eleazari ba Usi ba Yohanano ba Malakhia ba Elama ba Ezeri. Ba manunö zanunö andrö, ba Yiseraya zatuara.', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 43, 'Ba sumange sebua labe''e, me luo da''ö, ba omuso dödöra, me no ibe''e khöra wa''omuso dödö sebua Lowalangi, ba he ira alawe ba iraono, ba no somuso tödö, ba tobali aröu misa terongo wa''omuso dödö Yeruzalema.', '["RazII 25:23","Faigi 2:13; 3:13","Nga''ötI 23:5","Faigi 3:26","Faigi 3:11"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 44, 'Ba me luo da''ö, ba tefataro zamaigi-maigi ba mbate''e andrö, ba nibe''e buala andrö, saoha gölö, si a''a hadia ia ba si sambu-sambua ni''ofulu, ba nihöna ya''ia, ena''ö ba da''ö la''owuloi mbalazo gere ba balazo Nono Lewi, ame''ela mbanua misa, bua nowi; noa sa omuso dödö mado Yuda gere andrö ba Ono Lewi, sangai-ngai halöŵö.[13]', '["Nga''ötI 25. Faigi 10:37; 13:5","Faigi 10:39; MozIV 18:26"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 45, 'Famosumange Lowalangira halöŵö da''ö ba fangehangehao andrö. Ba sanunö andrö ba sanaro ba mbawandruhö, ba la''o''ö nifakhoi ndra Dawido ononia Selomo.', '["Nga''ötI 25. Faigi 10:37; 13:5","Faigi 10:39; MozIV 18:26"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 46, 'Noa sa ba götö föna sa''ae ba götö ndra Dawido Asafo högö zanunö, ba so wanunö ba fangandrö saoha gölö, khö Lowalangi.', '["Nga''ötI 25. Faigi 10:37; 13:5","Faigi 10:39; MozIV 18:26"]', NULL),
  (3475435, 'OT', 'Nehemia', 12, 47, 'Ba dozi Iraono Gizeraeli, ba götö Zerubabeli ba ba götö Nehemia, ba labe''e mbobotolö andrö, balazo zanunö ba balazo zanaro ba mbawandruhö, ndrohu-ndrohu mbalazora ma''ökhö; ba danga Nono Lewi labe''e game''ela ni''amoni''ö andrö, ba Ono Lewi zame''e ba ma''uwu Ga''aroni ame''ela ni''amoni''ö.[14]', '["Nga''ötI 25. Faigi 10:37; 13:5","Faigi 10:39; MozIV 18:26"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 1, 'Ba me luo da''ö, ba labaso ba niha sato zura Moze, ba lasöndra, wa no musura ba da''ö, wa ö''ö manö tola möi banua Lowalangi Ndraono Gamoni ba Iraono Moabi,[1]', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 2, 'me no lö la''ohe ö Ndraono Gizeraeli roti ba idanö, föna no, ba me no la''oni Mbileamo andrö, ba wangelifi ya''ira, fangelifi andrö nibali''ö Lowalangida howu-howu.[2]', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 3, 'Ba me larongo goroisa andrö, ba laheta ba Ndraono Gizeraeli niha bö''ö fefu.', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 4, 'Ba föna da''ö sa''ae, ba no maoso Geliasibi ere, si tengabö''ö Dobia, si no mufataro samaigi-maigi ba mbate''e andrö ba gosali Lowalangida,[3]', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 5, 'no ihaogö nahia Dobia andrö mbate''e sebua; ba mege, ba sumange ni''a andrö ni''irö''ö ba da''ö ba kumöyö ba gama-gama ba si sambu-sambua ni''ofulu mbua nowi ba agu ba fanikha, sinema Nono Lewi ba sanunö ba sanaro ba mbawandruhö, awö mbuala saoha gölö andrö, balazo gere.[4]', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 6, 'Be me luo da''ö, ba lö ya''o ba Yeruzalema, noa sa möido khö razo, ba ndröfi si 31 khö Aretazasa, razo Mbabeli; ba lö ara, ba ufuli u''andrö aefa ndra''o khö razo,[5]', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 7, 'ba me urugi Yeruzalema, ba u''ila horö Geliazibi andrö, me no ihaogö khö Dobia mbate''e ba zinga golayama gosali Lowalangi.', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 8, 'Ba abao sibai dödögu ba da''ö, ba utema uheta ba mbate''e andrö gama-gama Dobia, ahori utibo''ö baero,', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 9, 'ba uŵa''ö lafuli lahaogö mbate''e andrö; ba ufuli bakha gama-gama ba gosali Lowalangi, awö zumange ni''a, awö gumöyö.', '["MozV 23:3–6","MozIV 22:5,6; Yos 24:9","Hez 8:7","MozIV 18:21","Faigi 11:24"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 10, 'Ba urongo na göi, wa lö mube''e mbobotolö andrö, sinema Nono Lewi, ba no tobali laheta ira Ono Lewi ba sanunö andrö, nifataro ba halöŵöra; no isaŵa mbenuania zamösana.', '["Faigi 10:40","MozIV 18:21","Nga''ötI 26:20"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 11, 'Ba utahigö zatua, umane: Hana wa no la''erogö gosali Lowalangi? Ba ufakaoni''ö ira, ba ufuli ufataro ira ba nahara.[6]', '["Faigi 10:40","MozIV 18:21","Nga''ötI 26:20"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 12, 'Ba dozi niha Yehuda, ba la''ohe zi sambu-sambua ni''ofulu, bua nowi ba agu ba fanikha, labe''e ba mbate''e wangöhöna andrö.[7]', '["Faigi 10:40","MozIV 18:21","Nga''ötI 26:20"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 13, 'Ba ufataro samaigi-maigi ba mbate''e wangöhöna andrö Zelemia ere ba Sadoki sangila amakhoita ba Fedaya Ono Lewi, ba tohu-tohu dangara Hanano, ono Zakuru ono Matania; da''ö sa zi faduhu dödöma, ba ba dangara tebe''e wamaosa ba dalifusöra.[8]', '["Faigi 10:40","MozIV 18:21","Nga''ötI 26:20"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 14, 'Törö-törö tödöu khögu da''ö, ya''ugö Lowalangigu, ba böi olifugö''ö zi sökhi andrö, nilaugu ba gosali Lowalangigu ba ba halöŵö ba da''ö.', '["Faigi 10:40","MozIV 18:21","Nga''ötI 26:20"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 15, 'Ba me luo da''ö, ba u''ila ösa ba mado Yuda, solazi bua nagu ba luo sabato ba solohe yomo bua nowi ba samonoro kalide ösi nagu ba bua nagu ba bua ara ba hadia ia na ngawalö, ba solohe yomo ba Yeruzalema, ba luo sabato. Ba utegu ira na la''amawa hadia ia mbalazo.[9]', '["Faigi 10:32; Yer 17:21–27"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 16, 'Ba banua Diro andrö, si no fatewu khöra ba da''ö, ba la''ohe yomo gi''a ba hadia ia ngawalö waniaga, ba la''amawa ba niha Yehuda ba Yeruzalema, ba luo sabato.', '["Faigi 10:32; Yer 17:21–27"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 17, 'Ba utahigö zalaŵa niha Yehuda, umane khöra: He moroi wa mosala manö ami, wa lö mi''amoni''ö luo sabato?', '["Faigi 10:32; Yer 17:21–27"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 18, 'Hadia, tenga no lamanö göi ira tuami, si tobali börö wa ifatörö khöda ba ba mbanua andre wamakao andrö fefu Lowalangida? Ba ya''ami, ba minönö na wönu Lowalangi andrö ba Ndraono Gizeraeli, wolau salakha ba luo sabato!', '["Faigi 10:32; Yer 17:21–27"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 19, 'Ba ha si''aikö ogömi ba mbawa göli, sara wongi lö sabato, ba uŵa''ö laduhö mbawa göli; ba u''oroi''ö na: lö tola lafuli labokai, irege no aefa luo sabato. Ba ufataro ösa nono matua andrö khögu, ba zinga mbawa göli, fa böi la''ohe yomo waniaga, ba luo sabato.', '["Faigi 10:32; Yer 17:21–27"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 20, 'Ba baero mbanua Yeruzalema la''iagö saniaga ba samawamawa hadia ia ba kade, ba zi bongi, mato dua wongi.', '["Faigi 10:32; Yer 17:21–27"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 21, 'Ba utegu ira, umane khöra: Hadia wa baero göli dumao-dao ami ba zi bongi! Na samuza tö, ba ufara''u''ö ami! Ba i''otarai da''ö, ba labato we''amöi na luo sabato.', '["Faigi 10:32; Yer 17:21–27"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 22, 'Ba ube''e göi li ba Nono Lewi: lahaogö ira ba möi manaro ba mbawa göli ba we''amoni''ö luo sabato. Ba da''ö göi törö tödöu khögu, ya''ugö Lowalangigu, ba hakhösi tödö ndra''o, ba wa''ebua dödöu andrö, si no fahöna!', '["Faigi 10:32; Yer 17:21–27"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 23, 'Ba me luo da''ö, ba möido göi mufaigi niha Yehuda andrö, si no mangai ira alawe [baero], banua Gasoto ba Iraono Gamoni ba Iraono Moabi.', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 24, 'Onora, ba matonga lalau li Gasoto, ba ma li soi no mege, ba lö la''ila li niha Yehuda.', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 25, 'Ba utahigö ira, u''elifi ira, ba ubago ösa ndra matua andrö ba udödöni mbura, ba ube''e ba hölu ira khö Lowalangi, umane: Böi mibe''e ba nonora matua nonomi alawe, ba böi mihalö umönömi, ba ma dongami, nonora alawe![10]!', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 26, 'Tenga no da''ö mbörö horö Zelomo, razo Ndraono Gizeraeli? Ba niha baero andrö fefu, ba no lö razo si mane ya''ia, ba no ibali''ö razo Ndraono Gizeraeli fefu ia Lowalangi, balazi wa''omasi Lowalanginia ia. Ba ya''ia göi, ba ira alawe baero zamowöhö, ba wamazökhi horö.[11]', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 27, 'Ba iya''e, ba tarongo khömi, mosala sebua ami, sala andrö fefu, wamazökhi horö ba Lowalangida, me mihalö-halö ndra alawe baero?', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 28, 'Ba no umönö Zanabala andrö, banua Horona, nono Yoyada ono Geliasibi ere sebua; ba ufofanö da''ö, uheta ia ba ngaigu.', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 29, 'Törö-törö tödöu khöra, ya''ugö Lowalangigu, me no lalau zalakha ba gere ba ba nibe''e ömöra, ya''ira ere ba Ono Lewi!', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 30, 'Ba tobali uhaogö ira, uheta khöra huku niha baero fefu, ba uhonogöi halöŵö gere ba halöŵö Nono Lewi, hadia halöŵö zamösana,', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475436, 'OT', 'Nehemia', 13, 31, 'ba he fame''e eu andrö, na inötö, awö zi a''a hadia ia. Törö-törö tödöu khögu [da''ö], ya''ugö Lowalangigu, ba zi sökhi!', '["MozV 7:3","SamII 12:24; RazI 3:13; 11:4"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 1, 'Ba me luo razo Ahasiwero andrö — Ahasiwero si no razo i''otarai danö Ndrawa Hindru, irugi danö Gaitiofia, razo zi 127 nga''örö danö —,', '[]', NULL),
  (3475455, 'OT', 'Esitera', 1, 2, 'me luo da''ö, me dumadao razo Ahasiwero andrö ba dadaoma razo ba gödo ba Zusa,', '[]', NULL),
  (3475455, 'OT', 'Esitera', 1, 3, 'me no alua mendrua fakhe razo ia, ba ilau fatome, ikaoni nawönia salaŵa fefu ba enoninia, tobali owulo khönia gumandra ba danö Weresia ba ba danö Media ba salaŵa ba kumandru ba danö misa,', '[]', NULL),
  (3475455, 'OT', 'Esitera', 1, 4, 'ba ifa''ele''ö wa''ebua wa''arazonia, awö lakhömi wa''ebuania, ha uga bongi — 180 ngaluo wa''ara —.', '[]', NULL),
  (3475455, 'OT', 'Esitera', 1, 5, 'Ba me no ahori mbongi da''ö, ba ibe''e gö zato fefu razo, ö niha si so ba da''ö ba gödo, ba Zusa, he satua ba he iraono, owuloa si fitu bongi fa''ara, barö göli kabu ba ngai gödo razo.', '[]', NULL),
  (3475455, 'OT', 'Esitera', 1, 6, 'Na lataŵi gulambu safusi ba baru luo sowu waru-waru, nifosinga sinali tarafali ungu, ba firö ni''olaeduru andrö, famakhai ba zi hulö daru nahe maremara. Ba kaso dadaoma niha, ba no böna ame ba firö ba mbale fuwala ba maremara ba baluri ba lazuridi.', '[]', NULL),
  (3475455, 'OT', 'Esitera', 1, 7, 'Ba ana''a mako wamadu, ba oi si faehufaehu mako andrö; ba agu khö razo, ba no fahöna, ba ginötö khö razo soböwö.', '[]', NULL),
  (3475455, 'OT', 'Esitera', 1, 8, 'Ba ba wamadu, ba no mube''e li, wa lö famarou; da''ö sa goroisa razo ba zatua fefu ba gödonia: balazi manö zamösana.', '[]', NULL),
  (3475455, 'OT', 'Esitera', 1, 9, 'Ba fo''omo razo, Wasi, göi, ba ibe''e göi gö ba ndra alawe ba gödo razo Ahasiwero.', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 10, 'Ba me no önö ngaluo zilalö, me no owua-wua dödö razo, ba nagu, ba ibe''e li khö ndra Mehuma, Bisita, Harabona, Bigita, Abagata, Setara, Kharaka, si dafitu, enoni yomo, sangai halöŵö khö razo Ahasiwero,', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 11, 'ena''ö la''ohe khö razo wo''omonia Wasi, sobala högö wo''omo razo, ba wama''ele''ö fa''asökhinia, ba niha sato ba ba zalaŵa, me no si sökhi sibai bawa ia.', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 12, 'Ba lö edöna möi Wasi, fo''omo razo, lö i''o''ö niŵa''ö razo, nifa''ema genoni andrö. Ba mofönu sibai razo, humola bakha dödönia.', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 13, 'Ba humede razo ba zatua-tua andrö, sonekhe ba wamaigi inötö — fefu hadia ia sa niŵa''ö razo, ba lafatimba''ö ba zonekhe ba huku ba ba wolohe ba lala huhuo;[1]', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 14, 'ba si no amaedola zahatö khönia, ba Kharesena ba Setara ba Adamata ba Tarisi ba Meresi ba Maresena ba Memukha, salaŵa Ndrawa Weresia ösa ba salaŵa Ndrawa Media ösa, si dafitu andrö, si fa''ila-ila bawa khö razo ba si no högö ba gamatöröŵania andrö, ba imane razo:[2]', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 15, 'Hadia huku nifatörö khö Wasi fo''omo razo, me no lö ni''o''önia oroisa razo Ahasiwero, nifa''ema genoni andrö?', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 16, 'Ba imane Memukha khö razo ba ba zalaŵa andrö: Tenga ha sambalö horö khö razo horö Wasi fo''omo razo, no horö ba zalaŵa fefu ba ba niha sato fefu ba danö razo Ahasiwero fefu.', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 17, 'Dozi ira alawe, ba larongo dania wolau wo''omo razo, ba tobali la''ositengagö ndra matuara, na lamane: No iŵa''ö razo Ahasiwero, la''ohe khönia wo''omonia Wasi, ba tekhönia möi.', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 18, 'Ma''ökho andre ladunö-dunö ba nawö razo salaŵa fo''omo zalaŵa Ndrawa Weresia ba fo''omo zalaŵa Ndrawa Media, si no mamondrongo wolau wo''omo razo andrö ba lö ambö dania wa lö ba dödö ba fangabu dödö.', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 19, 'Na möi dödö razo, ba yamube''e goroisa, nitanö ba zura goroisa ba Ndrawa Weresia ba ba Ndrawa Media, fa tebai awu''a: wa lö tola sa''ae i''oroma''ö ia khö razo Ahasiwero Wasi, ba fa''asalaŵania, ba ibe''e ba ndra alawe bö''ö razo, ba ndra alawe si sökhi moroi khönia.[3]', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 20, 'Ba na larongo goroisa razo andrö, nifarongogö ba gamatöroŵania — si no ebua sibai — ma''asagörö, ba la''ata''ufi ndra matuara ira alawe fefu, he salaŵa, ba he ono mbanua.', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 21, 'Ba omasi razo ba awönia salaŵa niŵa''önia andrö; ba i''o''ö razo niŵa''ö Memukha.', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475455, 'OT', 'Esitera', 1, 22, 'Ba ifa''ohe''ö zura, idozigö öri barö mbawa razo, sara öri, ba sagörö zura, ha soi ira, ba hadia lira: ira matua zamatörö si so baomonia; ba lira ilau.[4]', '["Nga''ötI 12:32","Eser 7:14","Dan 6:8","Neh 13:24"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 1, 'Ba me no aefa da''ö, me no alö wönu razo Ahasiwero, ba itörö tödönia Wasi, awö wolaunia andrö, awö nihonogöi mege, ba khönia andrö.', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 2, 'Ba lamane ono matua andrö khö razo, ngoni-ngoninia: Akha la''alui khö razo nono alawe sawuyu-wuyu ba si sökhi,', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 3, 'yamufataro zamaigi razo, yamudozigö öri ba gamatöröŵania, sangowuloi ono alawe sawuyu-wuyu ba si sökhi, fefu, ba wolohe ba gödo, ba Zusa, ba nomo ndra alawe andrö, barö Mbawa Hega''i samaigi-maigi ira alawe, ba ndra mufatörö wangehao andrö;', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 4, 'ba heza dania zomasi razo, ono alawe, ba ya da''ö wo''omo razo, fangali Wasi. Ba omasi razo niŵa''öra, ba i''o''ö da''ö.', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 5, 'Ba no so ba gödo, ba Zusa niha Yehuda, Morodokhai döi, ono Ya''iro ono Zime''i ono Gisi, mado Mbeniyami, ni''oloi''ö no,', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 6, 'moroi ba Yeruzalema, awö ni''oloi''ö andrö, si fao khö Yekhonia, razo mado Yuda, ni''oloi''ö Nebukanesa, razo Mbabeli.[1]', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 7, 'Ba Morodokhai andrö, ba sange''ebua Hadasa — Esitera —, ono dana namania, me no si lö ama ba si lö ina Hadasa andrö. Ba no si sökhi sibai boto nono alawe andrö, ba si sökhi sibai bawa; ba me mate ndra amania inania mege, ba isou ia ononia Morodokhai.', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 8, 'Ba me no terongo niŵa''ö razo, oroisania andrö, me la''oya''ö wolohe ba gödo, ba Zusa, barö mbawa Hega''i, ono alawe, ba la''ohe göi Gesitera ba gödo razo, barö mbawa Hega''i, samaigi-maigi ira alawe.', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 9, 'Ba omasi ia nono alawe andrö, ebua dödönia khönia; ba i''aliogö wamaigi fangebao andrö khönia, ibe''e dana khönia andrö, ba ifa''aso khönia ngoni-ngoninia andrö, nitehe khönia, si dafitu, ono alawe, moroi ba gödo razo, ba ibe''e nahiania ba he nahia ngoni-ngoninia andrö wondrege zi sökhi mbate''e ba nomo ndra alawe.', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 10, 'Ba lö ni''ombakha''ö Gesitera ha mado ia ba ha niha niwara; noa sa iŵa''ö khönia Morodokhai, böi yamu''ombakha''ö.', '["RazII 24:14"]', NULL),
  (3475456, 'OT', 'Esitera', 2, 11, 'Ba ero ma''ökhö manörö-nörö Morodokhai fönaföna golayama nomo ndra alawe, ba wamaigi-maigi na lö hadia ia khö Gesitera, ba heza la''ohe ia.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 12, 'Ba ero na irugi inötö, ba möi yomo khö razo Ahasiwero nono alawe, samösa, na no irugi zi 12 waŵa andrö, ba nifatörö khönia nihonogöi ba ndra alawe andrö, — si manö sa wa''ara wangehao andrö khöra: önö waŵa lagule''ö wanikha emuri, ba önö waŵa göi zamohua bö''ö, ba hadia ia na wangehao ndra alawe —:', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 13, 'ba na möi yomo khö razo nono alawe, samösa, ba lö tola lö labe''e khönia fefu hadia ia zomasi ia, ena''ö i''ohe ba gödo razo, na i''otarai nomo ndra alawe andrö.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 14, 'Na bongi möi ia yomo [khö razo], ba na moluo, ba ifuli ia, ba ba nomo ndra alawe si sambua möi ia ba da''ö, barö mbawa Za''asa-gasa, enoni yomo khö razo, samaigi-maigi dongania ba döi; ba lö tola sa''ae möi ia khö razo, ha na no omasi razo ia, ba na ifakaoni''ö.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 15, 'Ba me no irugi inötö khö Gesitera, ono Gabihailo, tana nama Morodokhai andrö, si no manou ya''ia ononia, me no irugi inötö khönia, ba möi ia yomo khö razo, ba lö hadia ia i''andrö, ha niŵa''ö Hega''i andrö, enoni yomo khö razo, samaigi-maigi ira alawe. Ba la''omasi''ö Gesitera dozi sangila ya''ia.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 16, 'Ba lahalö yomo khö razo Ahasiwero, ba gödo razo khönia, Gesitera, ba mbaŵa si fulu — baŵa Tebeti —, me no alua meönö fakhe razo ia.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 17, 'Ba omasi razo Gesitera, moroi ba wa''omasinia ndra alawe bö''ö fefu, ba ebua dödönia khönia, moroi ba wa''ebua dödönia ba nono alawe bö''ö fefu. Ba ibe''e ba högönia mbala högö wo''omo razo ba ibali''ö fo''omo razo, fangali Wasi.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 18, 'Ba ilau walöŵa sebua razo, ikaoni nawönia salaŵa ba enoninia, fefu; falöŵa ba wangai Esitera, ba ba danö göi itehe wolombase, ba mame''e buala ia, fa''oböwö razo.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 19, 'Ba me lafuli la''owuloi nono alawe, ba no dumadao ba zinga mbawandruhö khö razo Morodokhai —.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 20, 'Ba lö ni''ombakha''ö Gesitera ha niha niwara ba ha mado ia, no i''o''ö niŵa''ö Morodokhai khönia, no ifondrondrongo niŵa''ö Morodokhai, si mane mege, me iraono ia na baomonia.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 21, 'Me luo da''ö, me no dumadao ba zinga mbawandruhö khö razo Morodokhai, ba tesao wa''afökhö dödö genoni yomo khö razo, darua ira, Bigitana ba Teresi, sanaro ba mbawandruhö, ba la''alui wamunu razo Ahasiwero.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 22, 'Ba irongo da''ö Morodokhai ba i''ombakha''ö khö Gesitera, fo''omo razo, ba Esitera zama''ema khö razo niŵa''ö Morodokhai.', '[]', NULL),
  (3475456, 'OT', 'Esitera', 2, 23, 'Ba lasekhegö ba larongo, wa tenga faya, ba lataŵi zi darua andrö ba gatunga. Ba tetanö ba zura da''ö, ba zura hikaya khö razo.', '[]', NULL),
  (3475458, 'OT', 'Esitera', 3, 1, 'Ba me aefa da''ö, ba ibali''ö salaŵa Hamano razo Ahasiwero, Hamano ono Hamedata, ma''uwu Agagi, i''ebua''ö, ba yaŵa dadaoma zalaŵa bö''ö fefu ba ngainia ibe''e dadaomania.', '[]', NULL),
  (3475458, 'OT', 'Esitera', 3, 2, 'Ba dozi enoni razo, si so ba gödo khö razo, ba latuhi danö ba lafalögu tou ira föna Hamano, me no oroisa razo da''ö ba khönia. Ba Morodokhai, ba lö ituhi danö ba lö ifalögu tou ia.', '[]', NULL),
  (3475458, 'OT', 'Esitera', 3, 3, 'Ba lamane enoni razo, si so ba gödo khönia, khö Morodokhai: Hana wa ösawö goroisa razo?', '[]', NULL),
  (3475458, 'OT', 'Esitera', 3, 4, 'Ba ero maokhö lamanö khönia, ba lö ifondrondrongo, ba la''ombakha''ö khö Hamano, ba wamaigi, na lö te''ala Morodokhai; noa sa i''ombakha''ö khöra, wa niha Yehuda ia.', '[]', NULL),
  (3475458, 'OT', 'Esitera', 3, 5, 'Ba me i''ila Hamano, lö ituhi danö fönania Morodokhai ba lö ifalögu tou ia, ba mofönu sibai ia.', '["MozI 41:42; Faigi 8:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475458, 'OT', 'Esitera', 3, 6, 'Ba faya-faya iŵa''ö tödönia, na ha samösa Morodokhai ibunu; me no la''ombakha''ö khönia ha soi Morodokhai, ba i''alui lala Hamano, ba wangohori niha Yehuda, iwa Morodokhai, fefu; ba danö Ahasiwero, ma''asagörö.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 7, 'Ba ba mbaŵa si föföna — baŵa Nisana —, me no alua mewelezara fakhe razo Ahasiwero, ba lalau "wuri" — dahö-dahö — föna Hamano, la''erogö ma''ökhö ba la''erogö baŵa, ba göna ba zi meweledölu ba mbaŵa si felendrua — baŵa Adara.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 8, 'Ba imane Hamano khö razo Ahasiwero: So soi sambua, si no muzaewe ba niha bö''ö, ba danö fefu, barö mbawau ba si no tonia; huku khöra, ba no faehu ba huku niha bö''ö fefu, ba oroisa razo, ba lö la''o''ö, ba no tenga si nangea, itehe manö khöra da''ö razo.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 9, 'Ba na atulö khö razo, ba nibe''e sura, ba wangohori ya''ira, ba ube''e ba danga ndra tua kumandru wirö, 44.120.000 ba rufia, ena''ö labe''e ba nahia girö-girö khö razo.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 10, 'Ba isöbi ba durunia laeduru razo, laeduru si so tandro, ba ibe''e khö Hamano andrö, ono Hamedata, ma''uwu Agagi, udu niha Yehuda.[1]', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 11, 'Ba imane razo khö Hamano: Firö andrö, ba khöu labe''e, ba ba niha andrö, ba lau zomasi''ö.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 12, 'Ba humede ira ba durutuli razo ba zi meweledölu ba mbaŵa si föföna; ba latörö sibai nihonogöi Hamano, wama''ohe''ö sura ba nifataro razo ba ba gumandru ba zi sagö-sagörö tanö, ba ba zalaŵa soi niha misa, dali wanura khöra ba danöra ba he li soi andrö misa. Töi razo Ahasiwero nibe''e ba zura goroisa andrö, ba lafotandro tandro ba laeduru andrö, khö razo.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 13, 'Ba ladozigö tanö barö mbawa razo, wama''ohe''ö sura andrö ba zinenge si fagohi, ba wangohori niha Yehuda, ba wamakiko, ba wamunu, he iraono ba he satua, ba iraono sawuyu ba ira alawe, ha ma''öma''ökhö, ba zi meweledölu ba mbaŵa si felendrua — baŵa Adara —, ba ba worabu zi so khöra, amaedola zi lö sokhö.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 14, 'Ba da''ö niŵa''ö ba zura andrö: ladozigö tanö wame''e oroisa, ena''ö dozi niha zamondrongo, ba ena''ö no te''anö ira, na irugi baŵa da''ö.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475458, 'OT', 'Esitera', 3, 15, 'Ba la''aliogö sinenge andrö, si fagohi, la''o''ö niŵa''ö razo, me ha si''aikö tebe''e goroisa andrö, ba gödo, ba Zusa. Ba mudadao manga razo, awö Hamano; ba banua Zusa, ba si tobali tödö.', '["MozI 41:42; Faigi 8:2"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 1, 'Ba me irongo Morodokhai niŵa''ö andrö fefu, ba isika nukhania, i''onukha gonigoni ba ilau nawu ba högönia, ba möi ia baero ba newali, mangarö-ngarö sibai ba mege-ege.[1]', '["SamII 1:11; 13:31","Yob 42:6; Yon 3:5","Faigi 3:9"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 2, 'Ba irugi fönaföna mbawa göli khö razo. Ba bawa göli khö razo, ba lö tola itörö sobaru gonigoni.', '["SamII 1:11; 13:31","Yob 42:6; Yon 3:5","Faigi 3:9"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 3, 'Ba dozi tanö, heza terongo niŵa''ö razo, oroisania andrö, ba abu sibai dödö niha Yehuda, ba mamoni ba gö ira ba mege-ege ba mangarö-ngarö, ba ato zamöröni gonigoni ba awu.[2]', '["SamII 1:11; 13:31","Yob 42:6; Yon 3:5","Faigi 3:9"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 4, 'Ba so ngoni-ngoni Gesitera, ono alawe ba enoninia ira matua, la''ombakha''ö khönia da''ö, ba abu sibai dödö wo''omo razo andrö. Ba ifa''ohe''ö nukha, nukha Morodokhai, ena''ö ifuli iheta gonigoni andrö; ba lö ihalö.', '["SamII 1:11; 13:31","Yob 42:6; Yon 3:5","Faigi 3:9"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 5, 'Ba humede Gesitera khö Hatakha, enoni yomo khö razo, nibe''enia enoni Gesitera, ba ifatenge khö Morodokhai, ba wanofu hadia geluaha da''ö fefu, hana wa lamanö.', '["SamII 1:11; 13:31","Yob 42:6; Yon 3:5","Faigi 3:9"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 6, 'Ba möi tou Hatakha khö Morodokhai ba newali, fönaföna mbawa göli khö razo.', '["SamII 1:11; 13:31","Yob 42:6; Yon 3:5","Faigi 3:9"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 7, 'Ba ahori i''ombakha''ö khönia Morodokhai, he lawisa khönia mege ba fa''ebua wirö andrö, nifabu''u Hamano, nitulo, nibe''e ba nahia girogirö khö razo, ba niha Yehuda, ena''ö labunu ira.[3]', '["SamII 1:11; 13:31","Yob 42:6; Yon 3:5","Faigi 3:9"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 8, 'Ba ibe''e göi khönia zura goroisa andrö, sagörö, oroisa moroi ba Zusa, ba wangohori niha Yehuda, ena''ö i''oroma''ö khö Gesitera, ba ena''ö i''ombakha''ö khönia, wangandrö khönia yamöi yomo khö razo, ba wangandrö khönia fa''ahakhö dödö ba fangorifi iwara.', '["SamII 1:11; 13:31","Yob 42:6; Yon 3:5","Faigi 3:9"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 9, 'Ba so Hatakha, i''ombakha''ö khö Gisitera niŵa''ö Morodokhai.', '["RazII 7:4"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 10, 'Ba ifafuli''ö li khö Morodokhai khö Hatakha andrö, imane:', '["RazII 7:4"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 11, 'Dozi enoni razo, ba he niha sato ba danö razo, ba no larongo, wa ha sara huku, huku mate, na so zi möi bakha khö razo, ba golayama tanö bakha, na si lö mukaoni, fefu gofu ha niha, he ira matua, ba he ira ala''we, ato na so ni''oro''ö razo si''o razo andrö khönia, ena''ö auri ia. Ba ya''odo, ba no sara waŵa sa''ae, ba lö sihede khögu, ba we''amöi khö razo.', '["RazII 7:4"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 12, 'Ba me no lafuli khö Morodokhai niŵa''ö Gesitera,', '["RazII 7:4"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 13, 'ba ifafuli''ö göi li khö Gesitera Morodokhai, imane: Böi ŵa''ö tödöu, ha ya''ugö dania zauri niha Yehuda, me no ba gödo razo so''ö.', '["RazII 7:4"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 14, 'Na si ndruhu sa lö hede-hedeu ba götö da''e, ba so dania wangefa niha Yehuda ba fangorifira, ta''ila heza moroi, ba ya''ugö ba si samba omo ya''ami, ba si mate. Ha zangila, na tenga börö götö da''e, wa no tobali fo''omo razo ndra''ugö!', '["RazII 7:4"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 15, 'Ba ifafuli''ö zui li khö Morodokhai Esitera, imane:', '["RazII 7:4"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 16, 'Ae falukha''ö niha Yehuda, banua Zusa, ba mi''amoni ba gö, khögu: tölu ngaluo ba tölu mbongi, ba böi manga ami, ba böi mibadu hadia ia; ba ya''o göi, ba umanö göi wamoni, awö ngoni-ngonigu andrö, ono alawe. Ba aefa da''ö, ba möido yomo khö razo, he ŵa''ae no fanawö oroisa da''ö. Na matedo, ba hana na matedo![4]', '["RazII 7:4"]', NULL),
  (3475459, 'OT', 'Esitera', 4, 17, 'Ba mofanö Morodokhai, i''o''ö sibai nifaŵa''ögö Gesitera khönia.', '["RazII 7:4"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 1, 'Ba me no aefa dua wongi, ba i''obaru mbaru wo''omo razo Esitera, ba i''agö golayama tanö bakha, ba gödo razo, ba gamaudu gödo, me no dumadao ba dadaoma razo khönia razo, yomo ba gödo, ba gamaudu mbawandruhö ba gödo.', '["Mar 6:23"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 2, 'Ba me i''ila wo''omonia Esitera, tou ba golayama, razo, ba ebua dödönia khönia, ba i''oro''ö khö Gesitera zi''onia ana''a, si so ba dangania, razo. Ba i''ondrasi Esitera, ibabaya mbalö zi''o.', '["Mar 6:23"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 3, 'Ba imane khönia razo: Hadia khöu, fo''omo razo, Esitera, hadia ni''andröu? He irege zi matonga gamatöröŵagu, ba latehe khöu!', '["Mar 6:23"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 4, 'Ba imane Esitera: Na atulö khö razo, ba yamöi manga khögu ma''ökhö, awö Hamano, ba gö andrö, si no u''asiwai khönia.', '["Mar 6:23"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 5, 'Ba imane razo: Mita''i-ta''i mihede khö Hamano, ena''ö ma''o''ö zomasi Gesitera! Ba me no so razo, awö Hamano, ba wemanga gö andrö, ni''asiwai Gesitera,', '["Mar 6:23"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 6, 'ba imane razo khö Gesitera, me ibadu-badu nagu razo: Hadia ni''andröu, ena''ö labe''e khöu? Hadia zomasi''ö? He irege zi matonga gamatöröŵagu, ba latehe khöu![1]', '["Mar 6:23"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 7, 'Ba itema linia Esitera, imane: Da''ö ni''andrögu ba da''ö zomasido:', '["Mar 6:23"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 8, 'na no falukhado wa''ebua dödö, wamaigi razo, ba na omasi razo ibe''e ni''andrögu ba itörö khögu zomasido, ba yamufuli möi manga khögu razo, awö Hamano, ba gö andrö, ni''asiwaigu khöra dania, ba mahemolu u''o''ö niŵa''ö razo.', '["Mar 6:23"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 9, 'Ba mofanö Hamano, omuso dödönia ba lö sabu dödönia hadia ia, me luo da''ö. Ba me i''ila Morodokhai ba zinga mbawa göli khö razo, me i''ila lö maoso, ba lö i''ata''ufi ia, ba mofönu sibai Hamano ba khö Morodokhai andrö.', '["Faigi 9:10"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 10, 'Ba itaha zui dödönia Hamano. Ba me irugi khöra, ba ifakaoni''ö zi fahuwu khönia ba fo''omonia Seresi.', '["Faigi 9:10"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 11, 'Ba itunö khöra wa''ebua gana''ania ba fa''oya nononia matua, awö wamosumange razo ya''ia, awö wa no yaŵa zalaŵa andrö ba yaŵa genoninia ibe''e ira razo.[2]', '["Faigi 9:10"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 12, 'Ba imane na Hamano: Ba fo''omo razo, Esitera, ba lö nikaoninia, awö razo, ba gö andrö, nihalönia, ha ya''odo andre; ba he mahemolu, ba no ya''o nikaoni, awö razo.', '["Faigi 9:10"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 13, 'Ba ambö na khögu da''ö fefu, fatua u''ila na dumao-dao ba zinga mbawa göli razo niha Yehuda andrö, Morodokhai.', '["Faigi 9:10"]', NULL),
  (3475460, 'OT', 'Esitera', 5, 14, 'Ba imane khönia fo''omonia Seresi, awö zi fahuwu khönia andrö fefu: Ndramufazökhi gatunga, 50 hela wa''alaŵa, ba mahemolu mbanua, ba öŵa''ö khö razo, ena''ö lataŵi ba da''ö Morodokhai; ba na aefa da''ö, ba ae manga, awö razo, ba ya omuso dödöu! Ba omasi Hamano niŵa''öra, ba ifafazökhi''ö gatunga andrö.', '["Faigi 9:10"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 1, 'Ba ba zi bongi andrö, ba lö alau hörö razo. Ba i''oroi''ö zura hikaya, ba labaso khönia.', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 2, 'Ba lasöndra, wa no mutanö ba zura andrö, wa no i''ombakha''ö Morodokhai, me labunu ena''ö razo Ahasiwero enoni yomo andrö khö razo, si darua, Bigitana ba Teresi, sanaro ba mbawandruhö.', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 3, 'Ba imane razo: Hadia mege nibe''e ba da''ö khö Morodokhai sumange ba si sökhi? Ba lamane ngoni-ngoni razo:', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 4, 'Lö mube''e hadia ia. Ba imane razo: Ha niha ba golayama? No irugi sibai golayama tanö baero ba gödo razo Hamano, ba wangandrö khö razo, ena''ö lataŵi Morodokhai, ba gatunga andrö, nifalau''önia khönia.', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 5, 'Ba lamane khö razo ngoni-ngoninia: Hamano zi so ba golayama. Ba imane razo: Yamöi yomo!', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 6, 'Ba möi yomo Hamano, ba imane khönia razo: He lawisa ba niha somasi razo ifosumange? Ba imane dödönia Hamano: Ha niha zomasi razo ifosumange, na tenga ya''odo?', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 7, 'Ba imane khö razo: Na so zomasi razo ifosumange,', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 8, 'ba ndramuhalö mbaru razo, ni''obaru razo mege. Awö kudo, ni''okudo razo, nifanaembu saembu khö razo,', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 9, 'ba ndramube''e ba danga nawö razo salaŵa mbaru andrö, awö kudo, ena''ö labe''e baru niha andrö, somasi razo ifosumange, ba ena''ö lafakudo ia ba kudo andrö, ba lafanörö-nörö ba newali, ba ndra mu''ao fönania: Da''e nilau ba niha, somasi razo ifosumange![1]', '["MozI 41:43"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 10, 'Ba imane razo khö Hamano: Ta''i-ta''i halö mbaru andrö, awö kudo si mane niŵa''öu, ba lau da''ö khö Morodokhai, niha Yehuda andrö, sidao-dao ba zinga mbawa göli khö razo; böi ambösi niŵa''öu andrö, fefu!', '["SamII 15:30"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 11, 'Ba ihalö mbaru andrö Hamano, awö kudo, ifobaru Morodokhai ba ifakudo ba ifanörö-nörö ba newali ba mu''ao ia fönania, imane: Si mane wolau ba niha, somasi razo ifosumange!', '["SamII 15:30"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 12, 'Ba ifuli ia ba zinga mbawa göli khö razo Morodokhai. Ba fulöi Hamano, isaŵa khöra, no abu dödönia ba no ibalugö högönia.[2]', '["SamII 15:30"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 13, 'Ba itunö khö wo''omonia Seresi ba ba zi fahuwu khönia da''ö no mege fefu. Ba lamane khönia satua-tua andrö khönia: Na iwa niha Yehuda Morodokhai andrö — me no ibörötaigö ahöndrö ndra''ugö fönania — ba tebai ölaŵa ia, ba tobali alua manö ahöndrö ndra''ugö khönia.', '["SamII 15:30"]', NULL),
  (3475461, 'OT', 'Esitera', 6, 14, 'Ba lö saetu huhuora na, ba so genoni razo, samangaösö Hamano ba gö andrö, nihalö Gesitera.', '["SamII 15:30"]', NULL),
  (3475462, 'OT', 'Esitera', 7, 1, 'Ba so razo, awö Hamano, ba wemanga khö Gesitera.', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 2, 'Ba isofu khö Gesitera, me luo da''ö göi, me labadu-badu nagu, imane: Hadia ni''andröu fo''omo razo, Esitera, ena''ö labe''e khöu? Hadia zomasi''ö? He irege zi matonga gamatöröŵagu, ba latehe khöu.', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 3, 'Ba itema linia fo''omonia Esitera, imane: Na no falukhado wa''ebua dödö wamaigiu, ya''ugö, razo, ba na atulö khö razo, ba alakha la''orifi ndra''o, börö wangandrögu andre, ba he iwama, börö zomasido andrö.', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 4, 'Noa sa mu''amawa ndra''aga, ya''odo andre ba iwama, ba wangohori ya''aga, ba wamunu, ba wamakiko. Na ni''amawa sawuyu ira matua ba sawuyu ira alawe na ato ndra''aga, ba lö hede-hedegu ena''ö; tenga sa si nangea nuduma andrö, wa te''ala razo ibe''e.', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 5, 'Ba humede razo Ahasiwero, imane khö wo''omonia Gesitera: Ha niha da''ö ba heza so ia, sama''amöi ba dödönia folau da''ö?', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 6, 'Ba imane Esitera: Uduma anrö si fatiu tödö khöma, ba ya''ia Hamano andre, si lö sökhi! Ba tokea sibai Hamano khö razo ba khö wo''omonia.', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 7, 'Ba maoso razo, ba wönunia, iböhöli wamadu agu, möi ia ba kabu, ba ngai gödo; ba toröi Hamano, ba wakaosa khö Gesitera, ena''ö lö labunu ia; aboto sa''ae ba dödönia, wa no i''etu''ö hukunia razo, huku famunu.', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 8, 'Ba me mangawuli yomo ba naha wemanga no mege razo, moroi ba kabu, ba no ibalöduhini gaso andrö, dadaoma Gesitera, Hamano. Ba imane razo: Hadia, ibunu wo''omo razo ba da''e yomo khögu? Ba ha si''aikö iŵa''ö da''ö razo, ba labalugö sa''ae mbawa Hamano.', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 9, 'Ba imane Herebona, enoni yomo khö razo, sangai-ngai hadia ia khönia: Hiza gatunga andrö, ba ngai nomo Hamano, 50 hela wa''alaŵa, nifalau''ö Hamano khö Morodokhai, si no mama''ema fangorifi khö razo. Ba imane razo: Mitaŵi ia ba da''ö!', '[]', NULL),
  (3475462, 'OT', 'Esitera', 7, 10, 'Ba lataŵi Hamano ba gatunga andrö, nifalau''önia khö Morodokhai. Ba awena alö wönu razo.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 1, 'Ba me luo da''ö, ba ibe''e bualania khö Gesitera razo nomo Hamano, udu Niha Yehuda. Ba molala khö razo Morodokhai, me no i''ombakha''ö khö razo Esitera, wa sahatö khönia Morodokhai.', '["MozI 41:42"]', NULL),
  (3475463, 'OT', 'Esitera', 8, 2, 'Ba iheta laedurunia razo, laeduru si so tandro, nihalönia mangawuli khö Hamano mege, ba ibe''e khö Morodokhai. Ba Esitera, ba ibe''e satua baomo ba nomo Hamano Morodokhai.[1]', '["MozI 41:42"]', NULL),
  (3475463, 'OT', 'Esitera', 8, 3, 'Ba ifuli humede Gesitera khö razo, ituhi zalo fönania, mege-ege ia, ba i''andrö wa''ahakhö dödö razo, ena''ö itolo, fa böi alua nifakhai Hamano andrö, ma''uwu Agagi, ba Niha Yehuda, famunu andrö.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 4, 'Ba i''oro''ö zi''onia ana''a andrö khö Gesitera. Ba maoso Gesitera, i''agö föna razo,', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 5, 'ba imane: Na atulö khö razo, ba na no falukhado wa''ahakhö dödönia, ba na si nangea iŵa''ö razo ba na omasi ia ndra''odo, ba yamufa''ohe''ö zura, yamu''oroi''ö wangai mangawuli zura no, tödö Hamano andrö, ono Hamedata, ma''uwu Agagi, nifasura''önia, ba wamunu Niha Yehuda ba danö barö mbawa razo, fefu.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 6, 'Tebai sa utaha ufaigi wamunu andrö, si göna niwama ena''ö, ba tebai utaha ufaigi wangohori iwama andrö!', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 7, 'Ba imane razo Ahasiwero khö wo''omonia Esitera, ba khö Morodokhai Niha Yehuda: Noa sa ube''e bualagu khö Gesitera nomo Hamano, ba ya''ia, ba no mutaŵi ba gatunga, me no ibabaya Niha Yehuda.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 8, 'Ba ya''ami, ba hana na mifa''ohe''ö zura, hana na töi razo mibe''e ba Niha Yehuda andrö, he wisa zomasi ami, ba mifotandro tandro ba laeduru khö razo. Me no tebai niwu''ai li ba zura, nibe''e töi razo ba si no mufotandro tandro andrö ba laeduru khö razo.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 9, 'Ba humede ira ba durutuli razo, me luo da''ö, ba zi 23, ba mbaŵa si tölu — baŵa Siwana — ba lafazökhi, zura la''o''ö niŵa''ö Morodokhai, ba Niha Yehuda, ba ba nifataro razo ba ba gumandru ba ba zalaŵa, ba nöri andrö fefu, si 127, i''otarai danö Ndrawa Hindru, numalö ba danö Gaitiofia, dali wanura ba zi sara-sara öri ba he li zi sambu-sambua soi, ba ba Niha Yehuda, ba ba wanurara ba ba lira.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 10, 'Ba ifabe''e''ö döi razo Ahasiwero ba ifotandro tandro andrö ba laeduru khö razo; ba ifa''ohe''ö ba zinenge si fakudo, saösö, kudo ba kandra khö razo kudora.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 11, 'Sura andrö, ba no fanehe razo ba Niha Yehuda ba mbanua misa fefu, hana na la''owuloi ira, ba wanimba samunu ya''ira, ba wangohori sato andrö, ba danö misa samunu ya''ira ena''ö, ba he iraono, ba he ira alawe, ba wamunu, ba wamakiko, ba hana na larabu zi so khöra, amaedola zi lö sokh''o,', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 12, 'ha ma''öma''ökhö, ba nöri barö mbawa razo Ahasiwero, fefu, ba zi me 13, ba mbaŵa si 12, — baŵa Adara.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 13, 'Ba taroma li ba zura andrö, ba nibe''e oroisa, nidozigö öri, ena''ö dozi soi zamondrongo, ba ena''ö na si no te''anö Niha Yehuda, na luo da''ö, ba wolau balöra ba nemalira.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 14, 'Ba ha si''aikö tebe''e goroisa andrö, ba gödo ba Zusa, ba mofanö zinenge andrö, saösö, si fakudo ba hulu kudo khö razo, salio ahe, la''o''ö niŵa''ö razo, la''aliogö ira, lafandruo kudo.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 15, 'Ba möi tou Morodokhai, iröi razo, baru zalaŵa mbarunia, biru-laŵi ba safusi, ba mosaembu ana''a ia ba mobaru sebua, tarafali ba ungu, ba owua-wua dödö mbanua Zusa, ba omuso dödöra.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 16, 'Noa sa falukha wa''ohahau dödö ba fa''omuso dödö ba fa''owua-wua dödö ba sumange Niha Yehuda.', '[]', NULL),
  (3475463, 'OT', 'Esitera', 8, 17, 'Ba dozi öri ba dozi banua, heza irugi niŵa''ö razo ba oroisania andrö, ba so wa''omuso dödö ba Niha Yehuda ba fa''owua-wua dödö ba femanga-manga, ba owuloa. Ba ato zi tobali Niha Yehuda niha baero, me no ihawui ira fa''ata''ura Niha Yehuda.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 1, 'Ba ba zi me 13 ba mbaŵa si 12, — baŵa Adara — ba nifalua ena''ö niŵa''ö razo, oroisania andrö, luo nidöna-döna zi fatiu tödö ba Niha Yehuda, ba wolaŵa ya''ira, ba zi no tobali, ba nilaŵa Niha Yehuda si fatiu dödö khöra: ba la''owuloi ira,', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 2, 'ba mbanuara, ba danö barö mbawa razo Ahasiwero, ba wamunu samunu ya''ira ena''ö. Ba lö solaŵa ya''ira, me no dozi soi ihawui fa''ata''ura Niha Yehuda.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 3, 'Ba latolo Niha Yehuda dozi salaŵa ba danö, ba he nifataro razo ba kumandru ba kumandra, me no ihawui ira fa''ata''ura Morodokhai.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 4, 'No sebua ae Morodokhai, ba genoni razo, ba itöröi danö fefu turiania, me itugu tedou manö wa''ebua Morodokhai andrö.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 5, 'Ba te''ala sibai zi fatiu tödö khöra fefu labe''e Niha Yehuda, lafafahö ba la''ö''ötö, labubunu; somasi ira lafatörö ba zi fatiu tödö khöra.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 6, 'Ba ba hati ba Zusa, ba 500 niha labunu Niha Yehuda, lafakiko.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 7, 'Fabaya Farasandrata ba Dalafono ba Asafata,', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 8, 'ba Forata ba Adalia ba Aridata,', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 9, 'ba Faramasa ba Arisai ba Arida''i ba Wayesata, ono Hamano andrö,', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 10, 'si dafulu, ba ba labubunu, ono Hamano ono Hamedata, udu Niha Yehuda, ba si so khöra, ba lö lababaya.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 11, 'Ba me luo da''ö, ba irongo razo wa''ato nibunu ba hati ba Zusa.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 12, 'Ba imane razo khö wo''omonia Esitera: Ba hati, ba Susa, ba no 500 nibunu Niha Yehuda niha, fabaya ono Hamano, si dafulu, ba ta''ila he wisa wolaura ba nöri bö''ö barö mbawa razo! Ba hadia ni''andröu, ena''ö latehe khöu? Ba hadia zomasi''ö, ena''ö latörö khöu?', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 13, 'Ba imane Esitera: Na atulö khö razo, ba ena''ö mahemolu göi latehe ba Niha Yehuda ba Zusa nilaura ma''ökhö; ba ono Hamano andrö, si dafulu, ba ena''ö na lataŵi ba gatunga.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 14, 'Ba ibe''e li razo, la''o''ö da''ö; ba tebe''e goroisa ba Zusa, ba ono Hamano andrö, si dafulu, ba lataŵi.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 15, 'Ba owulo zui Niha Yehuda ba Zusa, ba zi me 14, ba mbaŵa Adara, ba 300 labunu niha ba Zusa. Ba si so khöra, ba lö lababaya.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 16, 'Ba Niha Yehuda ba nöri bö''ö barö mbawa razo, ba owulo, ba latimba zamunu ya''ira ena''ö, wolau balöra ba nudura andrö, ba 75.000 labunu si fatiu tödö khöra, ba si so khöra, ba lö lababaya.', '[]', NULL),
  (3475464, 'OT', 'Esitera', 9, 17, 'Ba zi me 13 ba mbaŵa Adara lalau da''ö, ba ba zi me 14, ba molombase ira, ba labali''ö baŵa gowuloa ba baŵa wa''omuso dödö.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 18, 'Ba Niha Yehuda ba Zusa, ba no faoma owulo [ba wamunu udura], he ba zi me 13, ba he ba zi me 14, ba tobali ba zi me 15 molombase ira, ba luo da''ö labali''ö baŵa gowuloa ba baŵa wa''omuso dödö.', '["Neh 8:10","Faigi 3:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475464, 'OT', 'Esitera', 9, 19, 'Andrö wa si me 14, ba mbaŵa Adara, labali''ö baŵa wa''omuso dödö ba baŵa gowuloa, si no amaedola gowasa Niha Yehuda ba danö, ba mbanua si zaewe ba danö misa, ba faoma lafa''ohe''ö khö nawöra gurakha.[1]', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 20, 'Ba itanö ba zura da''ö fefu Morodokhai, ba ifa''ohe''ö zura ba Niha Yehuda, idozigö öri barö mbawa razo Ahasiwero, he sahatö, ba he saröu;', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 21, 'ifakhoi huku da''ö khöra: ero röfi, ba labe''e baŵa si sökhi zi me 14 ba si me 15, ba mbaŵa Adara, —', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 22, 'la''ohia''ö mbaŵa andrö mege, ba nitimba Niha Yehuda si fatiu tödö khöra, ba baŵa si tobali fa''omuso dödö fa''atosasa, ba sitobali luo gowuloa fa''abu dödö — wamali''ö baŵa gowuloa ba baŵa wa''omuso dödö, ba zi faoma lafa''ohe''ö khö nawöra urakha, ba ba nibe''e-be''e buala ba zi numana.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 23, 'Ba labe''e huku [ba khöra Niha Yehuda] zi no lafobörö andrö, awö nisura Morodokhai khöra.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 24, 'Me no tödö Hamano andrö, ono Hamedata, ma''uwu Agagi, udu Niha Yehuda fefu, wamunu Niha Yehuda, ba me no ifalau''ö "wuri" — dahö-dahö —, ba wamakiko ya''ira ba ba wangohori,[2]', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 25, 'ba me no iŵa''ö razo — me no fahuhuo khönia Gesitera — me no ibe''e zura, alakha khönia tofana mangawuli dödönia famakiko andrö ba lataŵi ia ba gatunga, fabaya iraononia.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 26, 'Andrö wa labe''e töi mbaŵa andrö "wurimi", börö "wuri" andrö, ba ösi zura no mege fefu, awö zi no falukha ira, ba he nirongora.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 27, 'Ba lahonogöi huku da''ö Niha Yehuda, ba khöra ba ba nga''ötöra dania, ba he ba zi möi banuara, huku si tebai awu''a: la''amoni''ö mbaŵa andrö, si dua ngaluo, dali zi no mube''e ba zura ba fangohonogöi ya''ia.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 28, 'Ba fa böi olifu ira mbaŵa da''ö ba ena''ö latörö, götö-götö wa''ara dania, dozi omo ba dozi öri ba dozi banua, fa böi taya ba Niha Yehuda mbaŵa "wurimi" andrö, böi manö olifu nga''ötöra mitou.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 29, 'Ba labe''e ba zura fo''omo razo, Esitera, ono Gabihailo, ba Morodokhai, Niha Yehuda andrö, labe''e fangaronia wa''asalaŵara andrö, ba wame''e sura "wurimi" andrö si sambua.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 30, 'Ba ifa''ohe''ö zura ba Niha Yehuda fefu ba nöri andrö si 127, amatöröŵa Gahasiwero ma''asagörö ihaogö linia khöra, soroi ba dödö,', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 31, 'ba wame''e huku mbaŵa "wurimi" andrö, ba ginötö nihonogöi, dali wa no labe''e huku Morodokhai Niha Yehuda ba fo''omo razo Esitera, awö wa no labe''e huku khöra ba ba nga''ötöra mitou gamakhoita andrö ba wamoni ba gö ba ba wangarö-ngarö.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475464, 'OT', 'Esitera', 9, 32, 'Ba tobali huku nifakhoi ba "wurimi" andrö ba goroisa Gesitera; ba tetanö ba zura.', '["Neh 8:10","Faigi 3:7"]', NULL),
  (3475465, 'OT', 'Esitera', 10, 1, 'Ba ifobeo niha ba danö ba ba hulo razo Ahasiwero.', '[]', NULL),
  (3475465, 'OT', 'Esitera', 10, 2, 'Ba fangoroma''önia fa''ebuania ba fa''abölönia, ba fangombakha lakhömi Morodokhai, me no ifolakhömi ia razo, ba no mutanö ba zura hikaya razo ba Media ba ba Weresia.', '[]', NULL),
  (3475465, 'OT', 'Esitera', 10, 3, 'Niha Yehuda andrö Morodokhai, ba no tambalina razo Ahasiwero, ba no ebua döinia ba niha Yehuda, ba omasiö niwara fefu ia, me no sangalui fangorifi madora, ba me sohare niwara i''alui ba huhuonia iefu.', '[]', NULL),
  (3475466, 'OT', 'Yobi', 1, 1, 'So niha [föna], ba danö Usi, Yobi döinia, niha satulö ba sadölö tödö, sangata''ufi Lowalangi ba si fa''udu ba zi lö sökhi.[1]', '["Hez 14:14; Yak 5:11"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 2, 'Ba fitu nononia matua ba tölu nono alawe.', '["Hez 14:14; Yak 5:11"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 3, 'Ba 7.000 khönia mbiri-biri ba 3.000 gondra, ba 500 fasa zaŵi ba 500 galide si alawe, ba ato sibai zawuyunia; tobali salaŵa niha da''ö, moroi ba niha bö''ö fefu, tanö ba gatumbukha luo.', '["Hez 14:14; Yak 5:11"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 4, 'Ba maoso-maoso nononia matua, lalau fatome, samösa ma''ökhö, ba lafakaoni-kaoni''ö dalifusöra alawe si datölu andrö, ba wemanga khöra.', '["Hez 14:14; Yak 5:11"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 5, 'Ba na no fatutu watomesa andrö, ba ifaŵa''ögö khöra Yobi, ena''ö na lasala''ö ira. Ba ihulö wongi wemaoso, ibe''e zumange nitunu, i''ohia''ö wa''atora. Imane sa''ae Yobi: Ma dania no molalö nonogu andrö, ma no la''erogö Lowalangi tödöra! Si manö-manö wolau Yobi andrö.', '[]', NULL),
  (3475466, 'OT', 'Yobi', 1, 6, 'Ba samuza ma''ökhö, ba so nono Lowalangi, ba wangondrasi Yehowa, ba fao göi khöra Zatana.[2]', '["Faigi 38:7; Nga''ötI 21:1; RazI 22:19"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 7, 'Ba imane Yehowa khö Zatana: Heza ö''otarai?', '[]', NULL),
  (3475466, 'OT', 'Yobi', 1, 8, 'Ba imane Yehowa khö Zatana: Hadia, no önehegö göi genonigu Yobi andrö? Lö''ö sa famaedonia ba guli danö, ba wa''atulö ba ba wa''adölö dödö, ba wangata''ufinia Lowalangi ba ba wa''udusa ba zi lö sökhi.', '[]', NULL),
  (3475466, 'OT', 'Yobi', 1, 9, 'Itema li Yehowa Satana, imane: Hadia, i''ata''ufi göi Lowalangi Yobi, lö böli gölönia? Tenga no öfoba''a-ba''a ia ba omonia, fabaya fefu zi so khönia, fasui?', '[]', NULL),
  (3475466, 'OT', 'Yobi', 1, 10, 'Halöŵö dangania, ba no öfahowu''ö, ba itugu oya manö gurifönia ba danö.', '[]', NULL),
  (3475466, 'OT', 'Yobi', 1, 11, 'Ba tema oro''ö dangau ba babaya zi so khönia fefu, ba lö zi lö ikaoni ba mbawau, wa i''erogö ndra''ugö.', '[]', NULL),
  (3475466, 'OT', 'Yobi', 1, 12, 'Ba imane Yehowa khö Zatana: Hiza, fefu hadia ia, zi so khönia, ba ya so ba dangau, ba böi babaya mbotonia!', '[]', NULL),
  (3475466, 'OT', 'Yobi', 1, 13, 'Ba ha samuza ma''ökhö, me manga-manga nono Yobi ono matua ba ononia alawe, ba nomo ga''ara si a''a, ba me labadu-badu nagu,', '["RazII 1:12"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 14, 'ba so zangombakha turia khö Yobi; imane: No manguhundra laza zaŵi ba mangalui göra galide si alawe, ba hinölu,', '["RazII 1:12"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 15, 'ba so manö Ndrawa Zaba, la''oloi''ö, ba la''ö''ötö si''öli zawuyu, ba ha ya''o zoloi, ba wangombakha khöu.', '["RazII 1:12"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 16, 'Ba lö saetu na li da''ö, ba so zamösa tö, imane: No aekhu galitö Lowalangi, moroi ba mbanua si yaŵa, ba no i''a mbiri-biri, fabaya sawuyu, ba ha ya''o zoloi, ba wangombakha khöu.[4]', '["RazII 1:12"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 17, 'Ba lö saetu na li da''ö, ba so zamösa tö, imane: Tölu bawa zabölö Ndrawa Galedaia, ba lahawui manö gondra, larabu; ba sawuyu, ba la''ö''ötö si''öli, ba ba ya''o zoloi, ba wangombakha khöu.', '["RazII 1:12"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 18, 'Ba lö saetu na li da''ö zui, ba so zamösa tö, imane: Manga-manga mege nonou matua ba onou alawe, ba nomo ga''ara si a''a,', '["RazII 1:12"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 19, 'ba i''ozumagö so nangi sabölö, moroi ba danö si mate, telobi ba nomo andrö, ba watalingania ma''a''öfa, ba adudu, ilangö ndraonou andrö ba mate ira, ba ha ya''o zoloi, ba wangombakha khöu.', '["RazII 1:12"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 20, 'Ba maoso Yobi, isika nukhania, ifatöwö''ö mbunia; ba ifalögu tou ia ba danö, mangalulu ia.[5]', '["MozI 37:29; Eser 9:3","Sangomb 5:14; TimI 6:7"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 21, 'Imane: Lö nukhagu, me u''otarai dalu ninagu, ba lö nukhagu, na mangawulido dania, Yehowa zame''e ba Yehowa zangai; nisuno döi Yehowa![6]', '["MozI 37:29; Eser 9:3","Sangomb 5:14; TimI 6:7"]', NULL),
  (3475466, 'OT', 'Yobi', 1, 22, 'Ba da''ö fefu, ba lö lalö Yobi, ba lö iŵa''ö si lö göna nilau Lowalangi.[7]', '["Faigi 2:10"]', NULL),
  (3475467, 'OT', 'Yobi', 2, 1, 'Ba samuza ma''ökhö, ba ifuli momöi nono Lowalangi, ba wangondrasi Yehowa; ba möi awöra Zatana göi, ba wangondrasi Yehowa.[1]', '["Faigi 1:6"]', NULL),
  (3475467, 'OT', 'Yobi', 2, 2, 'Ba imane Yehowa khö Zatana: Heza ö''otarai?', '[]', NULL),
  (3475467, 'OT', 'Yobi', 2, 3, 'Ba imane Yehowa khö Zatana: Hadia, noa göi önehegö genonigu Yobi andrö? Lö''ö sa famaedonia ba guli danö, ba wa''atulö ba ba wa''adölö dödö ba ba wangata''ufi Lowalangi ba ba wa''udusa ba zi lö sökhi. Lö''ö na niböhölinia satulö andrö khönia, ba no öfarou ndra''o, ba wamakao ya''ia, lö börö-börö!', '[]', NULL),
  (3475467, 'OT', 'Yobi', 2, 4, 'Itema li Yehowa Satana, imane: Uli zalahi guli! — ba fefu hadia ia, okhöta niha, ba ilulu, asala auri ia!', '[]', NULL),
  (3475467, 'OT', 'Yobi', 2, 5, 'Ba tema oro''ö dangau, babaya nösinia, ba lö zi lö ikaoni ba mbawau, wa i''erogö ndra''ugö!', '[]', NULL),
  (3475467, 'OT', 'Yobi', 2, 6, 'Ba imane Yehowa khö Zatana: Hiza, ba dangau so ia, ba böi etu''ö nosonia!', '[]', NULL),
  (3475467, 'OT', 'Yobi', 2, 7, 'Ba mofanö Zatana, iröi Yehowa, ba ibözi Yobi bio, i''otarai narö kahe, numalö ba gagalizuzu.[2]', '["MozV 28:35"]', NULL),
  (3475467, 'OT', 'Yobi', 2, 8, 'Ba ihalö duga lawu, ba woga''a-ga''a ösinia, dumadao ia bawu.[3]', '["SamII 13:19; Esit 4:3"]', NULL),
  (3475467, 'OT', 'Yobi', 2, 9, 'Ba imane khönia fo''omonia: Hadia, aro zui na dödöu ba zatulö andrö khöu? Tema efa''ögö khö Lowalangi ba yagö mate!', '[]', NULL),
  (3475467, 'OT', 'Yobi', 2, 10, 'Ba imane khönia: Fehede zi lö tödö wehedeu. Si sökhi andrö, ba no tatema khö Lowalangi, ba hadia tatimba zi lö sökhi? Ba da''ö fefu, ba lö horö mbewe Yobi.', '[]', NULL),
  (3475467, 'OT', 'Yobi', 2, 11, 'Ba larongo zi fahuwu khö Yobi — datölu ira — fefu wamakao andrö, si no göna ia, ba maoso ira, i''otarai mbanua khöra zamösana: Elifasi, banua Dema ba Bilidado, banua Zua ba Sofari, banua Na''ama, mamagölö ira, ba we''amöi, ba wangoroma''ö fa''ahakhö dödöra ba ba wondrara tödönia.[4]', '["Mat 25:36; Faigi 32:1 b.t.","Ngenu 2:10"]', NULL),
  (3475467, 'OT', 'Yobi', 2, 12, 'Ba me lafaöga höröra, me aröu na ma''ifu ira, ba lö la''ila wa ya''ia; ba mege-ege ira, ba lasika nukhara, dozi ira, lafazaumba miyaŵa gawu-gawu, satoru ba högöra.[5]', '["Mat 25:36; Faigi 32:1 b.t.","Ngenu 2:10"]', NULL),
  (3475467, 'OT', 'Yobi', 2, 13, 'Ba dumadao ira, awönia, ba zalo, fitu ngaluo ba fitu mbongi, samösa lö sihede khönia, sambua li lö''ö, me no la''ila, wa no falawu wa''afökhö andrö khönia.', '["Mat 25:36; Faigi 32:1 b.t.","Ngenu 2:10"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 1, 'Aefa da''ö, ba humede Yobi, i''elifi mbaŵa wa''atumbunia.[1]', '["Faigi 10:18; Yer 15:10; 20:14"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 2, 'Humede ia, imane:', '["Faigi 10:18; Yer 15:10; 20:14"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 3, '"Yatekiko mbaŵa andrö, ba zi tumbu ndra''o, ba bongi andrö, me laŵa''ö: No tumuge nono matua!', '["Sin 23:4"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 4, 'Ya''ogömi-gömi mbaŵa da''ö; böi yamusofu ia Lowalangi si yaŵa ba böi yatobaha khönia fa''amoluo!', '["Sin 23:4"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 5, 'Ndramu''andrö mangawuli ia fa''ogömi-gömi ba si bongi; yamuhawui ia salu ba yamufeta''u ia fangogömi-gömisi zi moluo.[2]', '["Sin 23:4"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 6, 'Bongi andrö, ba yamöi ondra''ua zogömi-gömi: Böi omuso dödönia ba ngenoli mbaŵa ndröfi andrö, böi yala''erai awö mbaŵa bö''ö.', '["Sin 23:4"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 7, 'Ya lö tumbu niha sa''ae ba mbongi da''ö: böi ya''owua-wua dödö niha ba khönia!', '["Sin 23:4"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 8, 'Ndramu''elifi ia sangelifi baŵa, sangila mamarou maliu.', '["Sin 23:4"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 9, 'Yandrundrumö ndröfinia na arakha moluo: yamudöna-döna haga — zaya-zaya gölö! alösu böi yamu''ila hörö wa''amoluo!', '["Sin 23:4"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 10, 'Me lö niduhönia khögu talu ninagu ba me lö nibini''önia khögu famakao, fa böi i''ila hörögu!', '["Sin 23:4"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 11, 'Hana wa lö mate ndra''odo ba dalu ninagu? hana wa lö aetu nosogu, me böla ndra''o?', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 12, 'Hana wa nihagi na ndra''odo ba hana wa la''oro''ö khögu mbalö meme, nisisiögu?', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 13, 'Tobali no adölö tou ndra''o mena''ö iada''e, ba molombase; mörö mena''ö ndra''o ba ahono dödögu,', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 14, 'awö razo ba awö gumandru, sangotomosi khöra adudula,', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 15, 'ba ma awö zalaŵa sebua ana''a, samo''ösi omora firö.', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 16, 'Ba ma zui si mane tabina saekhu, niko''o ba danö; lö''ö manö ya''odo, si mane tabina, si lö irai mangila haga zi moluo.', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 17, 'Ba da''ö labato wabötusa sebua horö ba ba da''ö ahono zi no atage.', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 18, 'Sohahau dödö nikuru fefu, lö larongo li mandru.', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 19, 'He iraono ba he satua, ba fagölö-gölö ba da''ö, ba aefa zawuyu khö zokhö ya''ia.', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 20, 'Hana wa ifohaga zi numana, ba hana wa i''orifi zabu tödö?', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 21, 'Si döna-döna fa''amate ba lö alua, sangalui ya''ia moroi ba wangaluinia ana''a.[3]', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 22, 'Somuso sibai tödö, si karaini fa''iki ena''ö, na falukha lewatö. —', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 23, 'Hana wa tefohaga niha, si no tobini lala, niba''a Lowalangi fasui?[4]', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 24, 'Noa sa salahi gögu wangarö-ngarö ba no amaedola gelea wege-egegu andre.', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 25, 'Na ata''udo hadia ia, ba no gönado ya''ia, ba hadia zihokha mbugu, ba itörödo.', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475468, 'OT', 'Yobi', 3, 26, 'Lö si falukhado na wa''ahono, ba he folombase ba he fa''ohahau dödö, ba hiza sa''ae [zui] wamahufa!"', '["Fam 9:6","Faigi 19:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 1, 'Ba itema li Yobi Elifasi, banua Dema, imane:', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 2, '"Ma dania abua khöu, na taŵa''ö ma''ifu khöu niŵa''öda; ba ha niha zangila momba''a taroma linia?', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 3, 'Hiza, no ato nifolalamö tödö, ba no öfuli ö''abe''e-be''e''ö danga si no adada.', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 4, 'Ha niha zalau mena''ö, ba no taroma liu zangabe''e, ba no ö''abölö''ö gahe si no mangiwa.', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 5, 'Ba iada''e, me ya''ugö zi göna, ba abu dödöu; me itörö ndra''ugö, ba tokea''ö.', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 6, 'Hadia, tenga fangabe''e dödöu wangata''ufiu Lowalangi, ba tenga tötönaföu wa''atulömö andrö?', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 7, 'Era-era tödöu, na no irai falukha zi tekiko, si lö horö; hadia, no irai tehori zatulö tödö?', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 8, 'Ndrege ni''ilagu, ba samaku si lö sökhi ba sanaru famakao, da''ö göi zamasi ya''ia.[1]', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 9, 'Ihehaini ira Lowalangi, ba tekiko ira, ba hanu-hanu wönunia andrö ariri.', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 10, 'Fendröndrö-ndröndrö zingo ba li harimo — ba ifö nono zingo, ba no mufatö.', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 11, 'Mowaö-waö manö zingo, si lö boto, me no ambö ahulua — ba ono zingo, ba muzaewe.', '["Amaed 1:31; 22:8; Hez 10:13; Gal 6:8"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 12, 'Ba no urongo daroma li, si lö abölö-bölö; möi ba dögi dalingagu wangöngö-ngöngösa.', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 13, 'Na ifakoli ia era-era ba gangilata ba zi bongi, na ihawui niha femörö sabe''e.', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 14, 'No ihawuido fanizi-nizi ba fogikhi, manizi-nizi dölagu fefu.', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 15, 'Itörödo angi ba mutaro mbörö bu ba nösigu.', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 16, 'Ba so ia fönagu — khala-khala mbawania, ba lö u''ila — famaedo niha ba duduma hörögu; ba urongo wangöngö-ngöngösa, imane:', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 17, '''Hadia, so maö niha, satulö föna Lowalangi, hadia, so zamösa, si no ohau-hau föna zomböi ya''ia?''[2]', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 18, 'Hiza, ba genoninia andrö aombö dödönia ba ba mala''ika andrö khönia so wa''elungu iŵa''ö.[3]', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 19, 'Ba tenga mendrua manö ba zi so ba nose la''uri, si otarai gawu-gawu tou wamobörö, safufu na itörö hama.[4]', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 20, 'Lö ikhamö ma''ökhö, ba arasa, tekiko ira lö fangorifi sa''ae, ba lö same''e ba dödö.', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475469, 'OT', 'Yobi', 4, 21, 'Na aetu zinali ba nosera andrö [nosora] ba mate manö ira, ba wa''ambö tödö andrö.', '["Sin 143:2; Rom 3:10","Faigi 15:15","KorII 5:1"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 1, '"Tema ao! Hadia so maö zanema liu? Ha khö ötandrösaigö liu, ba ni''amoni''ö andrö?', '["Sin 37:35; 73:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475470, 'OT', 'Yobi', 5, 2, 'Ba zambö tödö, ba möi famununia walösökhi-sökhi dödönia, ba sowöhö mowa, ba ibunu fökhö dödönia.', '["Sin 37:35; 73:19"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 3, 'No u''ila zambö tödö soŵa''a, ba u''anema''ö u''elifi nahiania.[1]', '["Sin 37:35; 73:19"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 4, 'Ba ndraononia, ba no aröu wangorifi; möi ira nihundragö ba mbawa göli, lö sangorifi.', '["Sin 37:35; 73:19"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 5, 'Basitönia, ba i''a solofo — he niba''a doi, ba ihalö — ba sowökhi tödö zorabu nibaya-bayania.', '["Sin 37:35; 73:19"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 6, 'Tenga sa ba gawu-gawu tumbu wamakiko, ba famakao, ba tenga sauri ba danö.', '["Sin 37:35; 73:19"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 7, 'Niha andrö, ba ba wamakao sa''ae tumbu, si mane fa''atokana miyaŵa nono galitö ba hola-hola galitö.', '["Sin 37:35; 73:19"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 8, 'Ba na ya''o, ba ufuli ena''ö khö Zi lö ambö fa''abölö, ba Lowalangi utunö huhuogu ena''ö.', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 9, 'Ba zolau sebua, si tebai aboto ba dödö niha, ba sahöli-höli dödö, si lö mutaha mu''erai,[2]', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 10, 'same''e teu ba danö ba sombuwui bolo nowi.', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 11, 'Sangalaŵa''ö yaŵa si so tou, ba wolohe ba wangorifi sabu tödö,[3]', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 12, 'Si lö boto ibe''e nifakhai zonekhe, fa tebai mofozu nilau dangara.[4]', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 13, 'Ira''u zatua-tua, ba wa''onekhera andrö, ba amaedola zi tetaru bagi nikhoi dödö zi töra fa''onekhe.[5]', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 14, 'Ba zi ma''ökhö ihawui ira fa''ogömi-gömi, ba hulö na ba zi bongi labayaisi lalara ba zi laluo.[6]', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 15, 'Ba tobali i''efa''ö zi numana ba mbawa zi''öli si otarai mbewera, ba ba danga zabölö i''efa''ö.', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 16, 'Ba tumbu wanötöna [fangorifi], ba zide-ide ba tefa''afu mbawa walösökhi.[7]', '["Sin 40:6; 72:10; Rom 11:33","SamI 2:7; Sin 113:7; Luk 1:52","SamII 17:14; Yes 8:10","KorI 3:19","MozV 28:29","Sin 107:42"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 17, 'Hiza, ya''ahowu niha nitegu Lowalangi! — andrö böi fatuwu khöu wotu andrö khö Zi lö ambö fa''abölö.[8]', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 18, 'Ifesokho sa niha, ba ifuli göi idalu-daluni; ifufu, ba sangorifi dangania.[9]', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 19, 'Önö ngawalö wa''atosasa, ba i''efa''ö ndra''ugö, ba ba wanete zi önö, ba lö göna''ö si lö sökhi.[10]', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 20, 'Na lofo mbanua, ba i''orifi''ö, fa lö mate ndra''ugö, ba ba wanuwö, ba itimba khöu mbawa zi''öli.[11]', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 21, 'Teba''a ndra''ugö ba mbözi-bözi lela andrö, ba lö ata''u''ö na itörö famufu.', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 22, 'Sa''iki ndra''ugö, na so wamufu ba ma fa''ebua mböli mbalazo, ba alakha lö ata''u''ö gutu ndru''u.', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 23, 'Noa sa fawu''u li ndra''ugö ba gara ba danö, ba no fahuwu khöu gutu ndru''u.[12]', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 24, 'Ba falukha''ö lö hadia ia ba noseu, ba na öfaigi nibaya-bayamö ba nahiau, ba lö hadia zi lö''ö.', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 25, 'Ba falukha''ö ato ma''uwumö, ba madoumö, ba si mane du''u ba danö.', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 26, 'Ba ginötö wa''atua örugi lewatö, si mane na te''ohe miyaŵa mbua nowi, na inötö.', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475470, 'OT', 'Yobi', 5, 27, 'Hiza, da''ö ia ni''alu-aluima tödöma, si manö ia; fondrondrongo, ba be''e ba dödöu!"', '["Amaed 3:11; Heb 12:5; Yak 1:12","SamI 2:6; Hos 6:1","Sin 91:4; Amaed 24:16","RazI 17:14; Sin 18:30","Hos 2:18"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 1, 'Ba itema linia Yobi, imane:', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 2, '"Ena''ö na latulo walösökhi-sökhi dödögu, ba ena''ö na labe''e ba wali''era wamakao andre khögu,', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 3, 'ba abua ena''ö, ta''ila, moroi ba wa''abua nene ba mbewe nasi, — andrö elungu-lungu ligu.', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 4, 'Noa sa tetaru ba nösigu nono wana Zi lö ambö fa''abölö: ibadu zöfunia tödögu, isuwö, ndra''odo ameta''uö andrö khö Lowalangi![1]', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 5, 'Hadia, mudele maö galide ba zabölö du''u, ba hadia mundröndrö zaŵi si matua ba zí sökhi gö?', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 6, 'Hadia, tola ta''a zi nami-namitö lö asio, ba hadia, ami zafusi gadulo?', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 7, 'Anuzu dödögu wanuyu ya''ia; ö sowoyu zi manö, uŵa''ö.', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 8, 'Ena''ö na itörö zomasido, ba ena''ö na ibe''e Lowalangi zihulu dödögu!', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 9, 'Ena''ö na nilau dödö Lowalangi ifufu ndra''odo, ena''ö na ifonumalö dangania, ba wangetu''ö ya''o!', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 10, 'Ba fondrara dödögu na atö [da''ö], — ba ufaröga ena''ö ndra''odo ba wa''afökhö andre, si lö fa''ahakhö dödö — wa lö urai uböhöli daroma li Ni''amoni''ö andrö.', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 11, 'Ba hadia ato wangabe''egu, wa mombase-mbase na ndra''o, ba he wisa wozu khögu, wa utaha manö dödögu?', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 12, 'Hadia, fa''abe''e gowe wa''abe''egu andrö, hadia, no töla garamba nösigu?', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 13, 'Hadia, tenga si lö''ö manö fangorifi ndra''odo; tenga no tetimba manö khögu we''e-we''e fefu?', '["Faigi 16:13; Sin 38:3"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 14, 'Saragu-ragu tödö, ba no si nangea lahakhösi tödö awönia, he na iböhöli wangata''ufi Si lö ambö fa''abölö.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 15, 'No lalimodo talifusögu, si mane mbombo, si mane ungo nidanö, si falawu.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 16, 'No olotu idanö sabe''e, ilau ia bakha si baku deu.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 17, 'Na aukhu zino khönia, ba ogo''ö; na abe''e lökhö, ba taya ba nahania.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 18, 'Lahole''ö ira sikoli, lasaŵa miyaŵa danö si mate ba tekiko.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 19, 'Lafaigi-faigi sikoli, banua Dema; sanörö, Dawa Zaba, ba ladöna-döna.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 20, 'Ba tobali si lö boto wanötönara andrö; larugi, ba no saekhu ölö.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 21, 'Si manö sa''ae ami khögu: mi''ila zata''u ita; ba humokha mbumi!', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 22, 'Hadia, no uŵa''ö: ''Mi''ohe khögu, ba mibe''e buala famawe''e gana''ami, khögu;', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 23, 'mi''efa''ö ndra''o ba danga zi fa''udu ba mihöli ndra''odo ba wa''abölö zamakao ya''o?''', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 24, 'Mifahaö ndra''o, ba ubato wehede, ba si no elungu ndra''o, ba mi''ombakha''ö khögu.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 25, 'Hiza, taroma li si duhu, ba manandrösa! Ba hadia nitegu wanegumi andrö?!', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 26, 'Hadia, mitegu daroma li, niŵa''ö? — Fehede zaragu-ragu tödö, ba humombo ba nangi!', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 27, 'He ba zi lö ama si lö ina, ba milau fadahö-dahö ena''ö, ba si fahuwu khömi, ba mi''amawa.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 28, 'Ba iada''e, ba mitöngöni ndra''odo; hadia, si ndruhu lö ata''udo ulimo ami.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 29, 'Mitandraigö zamuza tö, böi mifatörö zi lö atulö; mifuli mitandraigö, atulö na khögu.', '["Amaed 17:4"]', NULL),
  (3475471, 'OT', 'Yobi', 6, 30, 'Hadia, so ba mbewegu zabila? Hadia, lö i''ila wamakiko ararogu?"[2]', '["Amaed 17:4"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 1, '"Hadia, tenga amaedola halöŵö zanuwö halöŵö niha ba guli danö, ha hadia, lö itörö nitörö genoni?', '[]', NULL),
  (3475472, 'OT', 'Yobi', 7, 2, 'Si mane sawuyu sihulu tödö, ba we''amöi ba lumö ba si mane enoni, si döna-döna luonia,', '[]', NULL),
  (3475472, 'OT', 'Yobi', 7, 3, 'si manö wa no mutörö khögu mbaŵa wamakao, awö wa no te''erai khögu mbongi wa''afökhö.', '[]', NULL),
  (3475472, 'OT', 'Yobi', 7, 4, 'Na möido mörö, ba umane: Ha wa''ara dania maosodo? Ba ara zi bongi, ba atage ndra''o wombali-mbali ya''odo, irege ibörötaigö moluo.', '[]', NULL),
  (3475472, 'OT', 'Yobi', 7, 5, 'Balu-balu nösigu gukuö ba goa-goa, si hulö danö; molawa kuligu, ba ifuli atöla.', '[]', NULL),
  (3475472, 'OT', 'Yobi', 7, 6, 'Alio welalö mbaŵagu, moroi ba zi''ua ba zanoso; taya-taya manö, lö tötönafö.', '[]', NULL),
  (3475472, 'OT', 'Yobi', 7, 7, 'Törö-törö tödöu, wa no hulö nangi we''asogu ba guli danö! Lö''ö sa''ae ifuli i''ila wa''ohahau dödö hörögu andre.[1]', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 8, 'Hörö zangila ya''odo iada''e, ba lö''ö sa''ae i''ilado dania; na i''alui ndra''o höröu, ba lö ya''odo sa''ae.', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 9, 'Si mane lawuo si taya ba silalö misa, si manö wa lö mangawuli miyaŵa zi no numalö ba mbanua tou.', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 10, 'Lö''ö sa''ae ifuli ia ba nomonia, ba lö''ö sa''ae i''ila ia nahiania mege.', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 11, 'Ba lö''ö sa göi utenaŵa mbewegu, muhede ndra''o, ba wa''atosasa dödögu andre, ba mangarö-ngarödo, ba wa''abu dödögu.', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 12, 'Hadia, asi ndra''odo, ba ma hiu, wa öfataro zanaro ya''odo?', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 13, 'Na umane dödögu: Fondrara dödögu dania kasogu, itolodo wolu''i famakaogu kasogu andrö,', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 14, 'ba ökeani ndra''o fangifi ba öfeta''udo angilata,', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 15, 'tobali omasido, na nitögi bagi ndra''o, omasido wa''amate, moroi ba zi no hato töla andre.', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 16, 'Ariri manö ndra''o, tenga sauri si lö aetu ndra''odo: böhöido, angi sa we''asogu ba guli danö!', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 17, 'Hadia niha, wa no ebua ia ba dödöu, wa no soso dödöu ia?[2]', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 18, 'Wa ö''erogö mahemolu, wamaigi-maigi ya''ia, wa lö aedu''aedu ötandraigö ia?', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 19, 'Ha wa''ara dania ö''efa''ö höröu khögu; ha wa''ara lö''ö manö öböhöido, irege utölö gilogu?', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 20, 'Na so horögu — ba hadia nilaugu khöu, ya''ugö sihörö-hörögö niha? Hana wa öbali''ö tandrösa ndra''o khöu, irege abua ndra''o khögu?', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475472, 'OT', 'Yobi', 7, 21, 'Ba hana wa lö öbe''e aefa khögu horögu, hana wa lö öheta lalögu? Ufalögu sa''ae ndra''o tou, ba gawu-gawu, ba na ö''alui ndra''o, ba lö ya''odo sa''ae."', '["Faigi 14:1; Sin 90:5; 144:4; Yak 4:14","Sin 8:5; 144:3; Heb 2:6"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 1, 'Ba itema li Yobi Bilidado andrö, banua Zua, imane:', '["Faigi 1:18"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 2, '"Ha wa''ara lö öbato huhuo si manö, wa no hulö nangi sabölö mbeweu andrö!', '["Faigi 1:18"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 3, 'Hadia, ifuyu''ö huku Lowalangi, ba hadia, ibila''ö zatulö Si lö ambö fa''abölö?', '["Faigi 1:18"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 4, 'Na no so horö ndraonou khönia, ba no ilulu ira ba huku horöra andrö.[1]', '["Faigi 1:18"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 5, 'Na öforege wangandrö khö Lowalangi, na ökao khö Zi lö ambö fa''abölö, —', '["Faigi 1:18"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 6, 'na no ohau-hau ndra''ugö ba na sadölö dödöu, ba lö zi lö ifaigi-faigi''ö ba i''azökhi naha wa''atulö andrö khöu.', '["Faigi 1:18"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 7, 'Ba na fa''ide-ide mege mbörötau, ba fondrege wa''ebua dania gamozua.', '["Faigi 1:18"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 8, 'Sofu manö sa khö ndra tua, ba töngöni hadia ni''alu-alui ndra amara tödöra.[2]', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 9, 'Ya''ita sa, ba ha sara wongi na, ba si lö mangila watahögö hadia ia, me no amaedola lumö-lumö we''asoda ba guli danö andre.', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 10, 'Ba ya''ira zamahaö ya''ugö, la''ombakha''ö khöu, latunö khöu dödöra andrö.', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 11, 'Hadia, auri zukhu, na tenga ba dambu, ba ebua höi, na lö idanö?', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 12, 'Auri na, lö mutaba — ba alio oköli, moroi ba ndru''u bö''ö fefu.[3]', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 13, 'Da''ö dania lala zolifu Lowalangi, dozi, ba tobali faya dötönafö zebua horö.[4]', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 14, 'Saedu''aedu zabe''e dödönia, ba timba gu''ö galaŵa nidöna-dönania.', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 15, 'Abe''e dödönia nomonia, ba adudu; i''olembai, ba aso''a.', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 16, 'Auri ia ba manöi ba zino, ba ihawui kabunia lewiönia.', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 17, 'Iböbö gara tou ŵa''ania, isösö gotalua gara.', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 18, 'Ba na Ya''ia zondreha ba nahania, ba i''osilö''ögö ia [nahania andrö], imane: "Lö urai u''ila''ö!', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 19, 'Hiza, da''ö wa''omuso dödö ba lalania andrö, ba moroi ba danö tou, ba tumbu mbö''önia!"', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 20, 'Hiza, tenga si lö ba dödö Lowalangi zatulö tödö, ba lö ira''u danga zamazökhi horö.', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 21, 'Ba ihöna wa''iki ba mbawau ba fanunö ba mbeweu.[5].', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475473, 'OT', 'Yobi', 8, 22, 'Si fatiu tödö khöu, ba la''onukha wa''aila, ba ose zebua horö, ba lö''ö sa''ae."', '["MozV 4:32; MozI 47:9; Nga''ötI 29:15","Sin 129:6","Faigi 11:20; Sin 112:10; Amaed 10:28","Faigi 5:18,22"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 1, 'Ba itema linia Yobi, imane:', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475474, 'OT', 'Yobi', 9, 2, '"Ya''ia, u''ila, wa si manö — he iwisa niha wabu''asa khö Lowalangi![1]', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 3, 'Na omasi ia fasoso, ba he hönö ngawalö isofu, ba sambalö lö i''ila ibu''a niha.[2]', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 4, 'Si no atua-tua tödö ba si no fahöna fa''abölö — ha niha zirai fatandro khönia, ba si lö göna hadia ia?', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 5, 'Ya''ia andrö, samawu''a hili, si lö oroma, wanuli''ö ba wönunia;', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 6, 'Samahisi tanö ba nahania, fa mangiwa gehomonia.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 7, 'Sanenaŵa luo, ta böi tumbu, ba somba''a döfi.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 8, 'Samologö banua yaŵa, ha ya''ia, ba sanörö talu nasi.[3]', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 9, 'Somböi dofi soya ba "si tölu", awö "zara" andrö, fabaya bate''e [ndröfi] andrö tanö raya.[4]', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 10, 'Solau sebua, si tebai aboto ba dödö niha, ba sahöli-höli dödö, si lö mutaha mu''erai.[5]', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 11, 'Hiza, itörö ngaigu, ba lö u''ila ia; amaedola zihombo ia, wanörö, ba lö oroma khögu.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 12, 'Na ihori niha, ba ha niha zanenaŵa ya''ia? Ha niha zi tola manguma''ö khönia: Hadia nilaumö?[6]', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 13, 'Lö i''alösi wönunia Lowalangi — noa sa laköwö ira fönania sanolo Dawa Miserayi[7] —', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 14, 'ba mendrua manö tebai fabu''a ndra''o khönia; tebai usöndra niŵa''ögu khönia,', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 15, 'ya''odo, si tebai manema li, he na lö horögu; sangandrö fa''ahakhö dödö ena''ö ndra''o khönia sanguhuku ya''odo.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 16, 'Ba he ŵa''ae itema ligu, na u''angaröfi li ia, ba tebai faduhu dödögu, wa ifondrondrongo khögu.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 17, 'Irasa na''i ndra''o angi sabölö, ba inönö zokhogu, lö börö.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 18, 'Lö itehe khögu wangahasugö ya''odo, i''abusoi''ö ndra''o safökhö sibai khögu.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 19, 'Na fa''abe''e zabölö mbalazi, ba hiza ia! ba na lala huku mbalazi, ba ha niha zogaoni ya''odo!', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 20, 'Na lala khögu, ba bewegu zangetu''ö hukugu; ba na lö horögu, ba si falimo ndra''o ibe''e [bewegu andrö].[8]', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 21, 'Lö''ö sa horögu — ba lö ba dödögu nosogu; anuzu dödögu we''asogu ba guli danö.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 22, 'Oi faoma manö, andrö ufalua baeha: faoma ibunu, he satulö ba he si so horö.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 23, 'Na adölö famunu niha mbözi-bözi andrö, ba ma''iki ia ba wa''aragu-ragu dödö zi lö horö.', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 24, 'Uli danö andre, ba no mube''e ba danga zebua horö, hörö zanguhuku, ba i''okhö: na tenga ya''ia, ba ha niha na sa!', '["Sin 143:2","Faigi 38","MozI 1:7","Faigi 38:31; Amos 5:8; Yes 40:26","Faigi 5:9; Sin 77:15; 86:10","Yes 45:9; Rom 9:20","Yes 30:7; 51:9; Sin 87:4; 89:11","Mat 12:37"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 25, 'No alio mbaŵagu andrö, moroi ba zi fagohi, moloi, lö mu''ila wa''ohahau dödö.[9]', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 26, 'No itörö manö, amaedola dundraha saoha, amaedola moyo sondra''u.', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 27, 'Na umane dödögu: Da''u''osolifuagö wa''abu dödögu andrö, da''uböhöli wa lö sökhi-sökhi dödögu ba u''ohau-hau''ö mbawagu;', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 28, 'ba humokha mbugu zafökho andrö khögu fefu — u''ila wa lö öbe''e aefa ndra''odo.', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 29, 'Lö tola tenga si so horö ndra''odo, ba hadia wa u''eregeisi na dödögu si lö boto?', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 30, 'He usasai ndra''o taŵa deu si baku ba he udukhu idanö nawu dangagu,[10]', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 31, 'ba ö''ungugö ndra''o ba getuna ba tobali ogoro nukhagu ndra''odo.', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 32, 'Tenga niha si mane ya''odo ia, fa u''ila utema linia, fa tola fabu''a ndra''aga föna zanguhuku.[11]', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 33, 'Lö khöma same''e ba lala, si faoma manufa tanga ya''aga.', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 34, 'Ena''ö na iheta ba hulugu mbözi-bözinia, ba ena''ö na lö ikeani ndra''odo fameta''u andrö khönia:', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475474, 'OT', 'Yobi', 9, 35, 'Ba humede ndra''o, lö ata''udo ia; tenga sa si manö dögögu."', '["Faigi 7:7","Yer 2:22","Sangomb 6:10; Yer 49:19"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 1, '"Anuzu dödögu wa''aurigu, ba lö ubato wangarö-ngarö, humede ndra''o, ba wa''afökhö bakha dödögu.', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 2, 'Umane khö Lowalangi: Böi etu''ö hukugu; farongogö khögu, hadia mbörö, wa no hulö ösuwö ndra''odo.', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 3, 'Hadia, sökhi dödöu, na öfakao niha? na ötibo''ö niwöwöi dangau, ba na ötehe nikhoi dödö zebua horö?', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 4, 'Hadia, no hörö nösi niha höröu, ba no famaigi niha wamaigiu?', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 5, 'Hadia, ha fa''anau noso niha wa''anau nosou; hadia, ha sagötö niha götöu?', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 6, 'Wa ö''alui lalögu, wa ö''obini horögu?', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 7, 'He ŵa''ae no ö''ila, wa si lö horö ndra''odo, awö wa no lö sangefa''ö [ya''o] ba dangau.', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 8, 'No tangau zomböi ya''o, nihaogö, botogu ma''asambua — ba hadia, öfakiko ndra''odo?[1]', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 9, 'Törö tödöu, wa no öfazökhi ndra''o, amaedola wamöbözi la''uri, ba hadia, öfuli öfufu ndra''odo?[2]', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 10, 'Hadia, tenga no öfaduwa tou ndra''o, amaedola wamaduwa susu, ba tenga no abe''e ndra''o hulö kezu, öbe''e?[3]', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 11, 'No öfobalu-balu ndra''odo uli ba nagole, ba no öbe''e dayadayania döla ba uo.', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 12, 'No öfonoso ndra''o ba no falukhado wa''ebua dödö khöu, ba no öfaigi-faigi ndra''o, no ororogö hanu-hanugu.', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 13, 'Ba no öbini''ö da''ö ba dödöu; u''ila wa no nikhoi dödöu zi manö:', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 14, 'Na molalö ndra''o, ba ödaro-darogö, ba lö zi lö ö''otu''ö ndra''o ba horögu.', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 15, 'Na so horögu ena''ö, ba alai ndra''o! Ba he si lö sala ndra''o, ba lö''ö zui ufaöga mbawagu, ya''odo si no fahöna fa''aila, ba sanehenehe famakao!', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 16, 'Ba na maöga mbawagu, ba ögohi ndra''odo, timba wolohi zingo, ba ö''oromaroma''ö ba khögu andrö wa''abölöu ba wolau sahöli-höli dödö.[4]', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 17, 'Lö öbato wama''aso sasi, udugu, ba öhöna wönumö khögu, mangalingali manö zanuwö ya''odo, öbe''e.', '["Sin 119:73","MozI 2:7; 3:19","Sin 139:15","Yes 38:13; Ngenu 3:10"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 18, 'Hana wa no ösöbi ndra''o moroi ba dalu ninagu? Ena''ö na mate mege ndra''o, fatua lö i''ilado hörö niha![5]', '["Faigi 3:11"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 19, 'Ena''ö na hulö zi lö irai alua ndra''odo, ena''ö na nidölö ba lewatö ndra''o, i''otarai dalu ninagu!', '["Faigi 3:11"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 20, 'Lö anau tö nosogu — ba yamuböhölido, yamu''erogö ndra''o, fa ohahau dödögu, ma''ifu,', '["Faigi 3:11"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 21, 'gasa-gasa usaŵa zi lö fangawuli, tanö sogömi-gömi, si so lumö wa''amate,', '["Faigi 3:11"]', NULL),
  (3475475, 'OT', 'Yobi', 10, 22, 'tanö nihawui fa''ogömi-gömi, si mane na talu mbongi, si göna lumö wa''amate ba si fakuyu manö; hagania, ba no si mane talu mbongi."', '["Faigi 3:11"]', NULL),
  (3475476, 'OT', 'Yobi', 11, 1, 'Ba itema li Yobi Sofari andrö, banua Na''ama, imane:', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 2, '"Hadia, lö tadema-dema huhuo si no fahöna andrö, ba alakha lö tebu''a wehede zi beweasö andrö?', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 3, 'Hadia, lö''ö sa''ae hede-hede niha bö''ö ibe''e beweu andrö? Hadia, sango''aya ndra''ugö, ba lö la''ailasi''ö?', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 4, 'Ömane: ''Satulö niŵa''ögu ba lö salagu, na öfaigidö''.', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 5, 'Ba ena''ö na muhede Lowalangi, ena''ö na ifalua baeha niŵa''önia, famu''a wehedeu;', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 6, 'ena''ö na ifarongogö khöu zi no tobini andrö, fa''atua-tua, wa no mendrua manö wa''aduhu da''ö, — ba aboto ena''ö ba dödööe, wa i''osilömilagö na Lowalangi horöu ösa.', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 7, 'Hadia, ösöndra dödö Lowalangi, ba ökhamö wondrege andrö khö Zi lö ambö fa''abölö?', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 8, 'Italu''i mbanua si yaŵa — he öwisa? Abakha moroi ba mbanua tou — hadia nisöndrau?', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 9, 'No ebua moroi ba guli danö, ma''asagörö, ba no ebolo moroi ba nasi.', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 10, 'Na itörö, ba na ira''u niha, ba na ifalukha''ö zalaŵa rafe — ba ha niha zanenaŵa ya''ia?', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 11, 'Ya''ia zangila niha sofaya, oroma khönia horö, he lö ifaigi sibai.', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 12, 'Ba isöndra gera-era si lö tödö ba tobali niha nono galide gatua.', '[]', NULL),
  (3475476, 'OT', 'Yobi', 11, 13, 'Ba na ö''adölö''ö dödöu, na ö''oro''ö dangau khönia —', '["MozIII 26:5","Sin 4:9; Amaed 3:24","Faigi 8:13"]', NULL),
  (3475476, 'OT', 'Yobi', 11, 14, 'ba no falemba ba dangau horö, heta ia ba böi tehe zi lö atulö ba noseu! —', '["MozIII 26:5","Sin 4:9; Amaed 3:24","Faigi 8:13"]', NULL),
  (3475476, 'OT', 'Yobi', 11, 15, 'Ba tola sa''ae öfaöga mbawau, lö sala; si lö mangiwa ndra''ugö ba si lö fa''ata''u.', '["MozIII 26:5","Sin 4:9; Amaed 3:24","Faigi 8:13"]', NULL),
  (3475476, 'OT', 'Yobi', 11, 16, 'Ba taya sa''ae ba dödöu wamakao andrö; na itörö tödöu, ba hulö nidanö, si no ahele misa, öŵa''ö.', '["MozIII 26:5","Sin 4:9; Amaed 3:24","Faigi 8:13"]', NULL),
  (3475476, 'OT', 'Yobi', 11, 17, 'Ba mohaga dödöu, moroi na laluo, ba he na ogömi-gömi, ba si mane na moluo dania.', '["MozIII 26:5","Sin 4:9; Amaed 3:24","Faigi 8:13"]', NULL),
  (3475476, 'OT', 'Yobi', 11, 18, 'Ba ödöna-döna zi sökhi, me so na sa dötönafö; ba he na ödaro-darogö na, ba möi''ö manö mörö, lö abu dödöu.[1]', '["MozIII 26:5","Sin 4:9; Amaed 3:24","Faigi 8:13"]', NULL),
  (3475476, 'OT', 'Yobi', 11, 19, 'Ba mörö-mörö''ö, lö si keani ya''ugö, ba ato zomasi mangai tödöu.[2]', '["MozIII 26:5","Sin 4:9; Amaed 3:24","Faigi 8:13"]', NULL),
  (3475476, 'OT', 'Yobi', 11, 20, 'Ba hörö zebua horö, ba ariri; lö''ö sa''ae saŵatö khöra, ba tötönaföra, ba fa''aetu noso".[3]', '["MozIII 26:5","Sin 4:9; Amaed 3:24","Faigi 8:13"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 1, 'Ba itema linia Yobi, imane:', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 2, '"Ya''ia, si ndruhu ami, ba na mate ami dania, ba aetu wa''atua-tua?', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 3, 'Ba satödö göi ndra''odo, si mane ya''ami; tenga si tohude ami, moroi khögu, ba ha niha zi lö aboto ba dödö da''ö?', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 4, 'Aya zi fahuwu khögu sa''ae ndra''odo, ya''odo andre, nifondrondrongo Lowalangi, me u''angaröfi li ia; aya zatulö tödö ba si lö lalö![1]', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 5, 'Si göna famakao, ba lö ba dödö zohahau tödö — tetuli''ö na zi no mangiwa ahe.', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 6, 'Lö hadia ia ba nose zorabu, ba lö fa''abu dödö ba zangandrö fönu Lowalangi, samali''ö Lowalangira gokhöra.[2]', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 7, 'Ba sofu ato ba gurifö niha, ba lafahaö ndra''ugö, ba ba wofo ba dalu mbanua, ba la''ombakha''ö khöu.', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 8, 'Ba ma zui tanö tou öfaigi, ba ibotokhi ba dödöu; ba i''a ba nasi, ba latunö khöu.', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 9, 'Ha niha zi lö aboto ba dödö, ba da''ö fefu, wa no tanga Yehowa zamazökhi si manö.', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 10, 'Ya''ia andrö, si so ba danga noso zauri fefu, awö hanu-hanu nösi niha fefu?', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 11, 'Hadia, lö itandra daroma li tögi dalinga, si mane araro, na itandra wa''ami gö?[3]', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 12, 'Ba zi no tohare huwa so wa''atua-tua, ba ba wa''ara ba guli danö fao wa''aboto ba dödö.[4]', '["Amaed 14:2","Sin 37:1; 73:12; 92:8; Yer 12:1","Faigi 34:3","Faigi 8:8"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 13, 'Ba Khönia so wa''atua-tua ba fa''abölö; Khönia so lala dödö ba fa''aboto ba dödö.', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 14, 'Na idudugö hadia ia, ba tebai lafuli la''otomosi; nikurunia, ba lö''ö sa''ae te''efa''ö.[5]', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 15, 'Na iba''a nidanö, ba ogo''ö; ba na itöla''ö, ba aruru danö ibe''e.', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 16, 'Ba Khönia so wa''abölö ba fa''aro; Khönia zelungu, fabaya samöwöhö.', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 17, 'I''oloi''ö zalaŵa rafe, niheta gama-gama, ba awöhö mowa zanguhuku ibe''e.[6]', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 18, 'Itoto''ö wesu razo [famesura niha bö''ö] ba ifesu lafoyora,', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 19, 'I''oloi''ö gere, niheta baru, ba itimba zi no aro ŵa''a.', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 20, 'Ifa''afu mbawa zi no to''ölö ba huhuo, ba ibunu dödö zatua.', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 21, 'Ihawui fa lö ba dödö niha bö''ö zalaŵa, ba ilulu mböbö talu zabölö.[7]', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 22, 'Ibokai zi no tobini sibai ba zogömi-gömi, i''ohe ba zohaga zi so ba dalu zogömi-gömi.[8]', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 23, 'I''abölö''ö soi niha, ba ifuli ifufu; ato sibai ibe''e, ba ifuli ilulu, ni''oloi''ö.', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475477, 'OT', 'Yobi', 12, 24, 'Itayaigö dödö zalaŵa niha ba danö, selungu ira, ibe''e, ba zi lö lala, ba danö si mate.[9]', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475477, 'OT', 'Yobi', 12, 25, 'Labayaisi lalara ba zogömi-gömi sibai ba alau-lau ira, hulö zi mabu, ibe''e."', '["Yes 22:22","SamII 17:14; Yes 29:14","Sin 107:40","Mat 10:26; KorI 4:5","Sin 107:4"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 1, '"Hiza, no i''ila hörögu da''ö fefu; no irongo tögi dalingagu ba no utanö ba dödögu.', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 2, 'Ni''ilami andrö, ba u''ila göi; tenga sambö moroi khömi ndra''odo.', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 3, 'Ba omasido muhede khö Zi lö ambö fa''abölö, fabu''asa khö Lowalangi nilau dödögu.', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 4, 'Samakhai faya sa''ae ami ba same''e dalu-dalu si lö boto.[1]', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 5, 'Ena''ö na mibato wehede, ba tobali fa''atua-tua, wamaigi niha bö''ö!', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 6, 'Mifondrondrongo ato wanegugu [ya''ami]; mibe''e mbörö dalingami ba watahisa mbewegu andre.', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 7, 'Hadia, miŵa''ö zi lö atulö, ba wango''awögö Lowalangi, ba milau waya, ba wamohare ya''ia?', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 8, 'Hadia, si fa''awö khö Lowalangi ami, hadia, samu''a ba hulu Lowalangi nilaunia ami?', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 9, 'Hadia, sökhi maö lawulawu, na isekhegö ami, ma edöna mi''o''aya, si mane fango''aya niha awöra?', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 10, 'Lö''ö, lö zi lö i''otu''ö ami, na fa''awö ami, famini tödö.', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 11, 'Hadia, lö tokea ami ibe''e fa''asalaŵania, ba lö ihawui ami fameta''unia [ya''ami]?', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 12, 'Timba nawu daroma limi, ba ba''a-ba''ami, ba no ba''a-ba''a la''uri.', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 13, 'Böi mihede-hede khögu, ba ya''odo zihede; gofu itörö khögu!', '["Faigi 16:2"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 14, 'Hana wa u''usu nösigu; wolohe ya''ia? Da''ugogohe tangagu nosogu.', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 15, 'Hiza, ibunu ndra''o, ba udöna-döna khönia; ba ufa''ele''ö khönia gamuatagu.', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 16, 'Da''ö sa''ae wangorifigu, wa tebai i''ondrasi ia sebua horö.', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 17, 'Ba mifondrondrongo sibai wehedegu; yamöi ba dögi dalingami wamu''agu andre!', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 18, 'Hiza, no ufobörö huhuo andrö, u''ila wa no satulö khögu.', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 19, 'Ha niha zi tola fasoso khögu? ba lö''ö sa hede-hedegu ena''ö; mate manö ndra''odo.', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 20, 'Ha dua balö zi böi öfatörö khögu, ba lö''ö sa''ae ubini''ö ndra''odo, ba wamaigiu ya''o.', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 21, 'Böda dangau khögu, ba böi ifeta''u ndra''o fameta''u andrö khöu.[2]', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 22, 'Ba ao khögu, ba ya''o zanema liu; ba ma ya''odo zihede, ba ya''ugö zanedema.', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 23, 'Ha wa''oya ato lalögu ba ha wa''oya horögu? Farongogö khögu golalöŵagu, awö horögu!', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 24, 'Hana wa öbini''ö mbawau, ba hana wa öbe''e si fa''udu khöu ndra''odo?[3]', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 25, 'Hadia öfe''awa mbulu lehu ni''oloi''ö nangi, ba hadia, ögohi döla wakhe si no oköli?', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 26, 'Wa no safeto sibai öhonogöi khögu, wa utema amaedola gondröita horögu me ono matua ndra''o?[4]', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 27, 'Wa öbe''e ba galo gahegu, wa ödaro-darogö nitörögu fefu, awö wa öfa''u''u lalu''a kahegu?[5]', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475478, 'OT', 'Yobi', 13, 28, 'Ba no niha sadudu dania ndra''odo, amaedola ni''a go, ba amaedola mbaru ni''a hama."', '["Faigi 9:34","Faigi 19:11; 33:10","Sin 25:7","Faigi 33:11"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 1, '"Niha ni''adonogö ndra alawe, ba lö anunau noso, ba no fahöna wa lö ahono-hono.[1]', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 2, 'Amaedola wa''atumbu mbunga wa''atumbunia, ba ifuli aleu, taya, hulö lumö, lö arara.', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 3, 'Ba öhörö-hörögö zi manö, ba ödöni ndra''o, ba wanguhuku ya''o!', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 4, 'Hadia, so maö zi lö si lö sökhi ba zi otarai zi lö sökhi? Samösa lö''ö![2]', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 5, 'Na no muhonogöi mbonginia, ba na no öhuku mbaŵania; na no öhonogöi wondregenia, si tebai italu''i,', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 6, 'ba efa''ö höröu khönia, ena''ö molombase ia, ba ena''ö omasi ia mbaŵania andrö, si mane enoni ba halöŵö.[3]', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 7, 'Ba döla geu, ba so sa dötönafö: na te''obö ia, ba ifuli molewiö, lö''ö sa si lö madounia.', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 8, 'He ŵa''ae atua ŵa''ania barö danö, ba he ŵa''ae mate duhenia, ba gawu-gawu tou,', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 9, 'ba ba hua nidanö andrö, ba ifuli auri ba falukha lewiö, hulö si mane si bohou tumanö.', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 10, 'Ba na mate niha, ba adölö tou, na aetu noso niha, ba heza so ia?', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 11, 'Si mane fa''ataya nidanö ba mbaŵa, ba si mane fa''ogo''ö mboto nidanö sebua, si mane fa''otufonia,', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 12, 'si manö wamadölö niha ya''ia, ba lö''ö sa''ae ifuli maoso. Irege adudu mbanua si yaŵa, ba lö tokea ira, ba lö liŵa-liŵara ba wemöröra andrö.[4]', '["Faigi 7:7","Rom 5:12; Efes 2:3","Faigi 7:2","Faigi 19:26; Dan 12:2 b.t."]', NULL),
  (3475479, 'OT', 'Yobi', 14, 13, 'Ena''ö na ba mbanua tou öbini''ö ndra''odo, ena''ö na öfoba''a-ba''a ndra''o, irege alö wönumö andrö, na öhonogöi wondrege khögu ba na ifuli itörö tödöu ndra''odo.[5]', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 14, 'Hadia na mate niha, hadia, ifuli auri? Na si manö, ba alakha lö aetu wanötönagu, götö wasöndratagu andre, irege aefa ndra''o![6]', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 15, 'Ba mu''ao ena''ö ndra''ugö, ba utema liu; humulu ena''ö dödöu ba gomböila dangau andre.', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 16, 'Ba iada''e, ba ö''ofaya mbekagu, ba lö''ö sa ö''osilömilagö horögu.[7]', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 17, 'No mufotandro lalögu, bakha ba dokosa, ba no ölau wamakhitö ba horögu.[8]', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 18, 'Ba si mane hili, sadudu, na aruru, ba si mane kara ba hili, sawu''a,', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 19, 'ba si mane na adudu gara ibe''e idanö, si mane na ihanigö danö hohounia, si manö wamufumö tötönafö niha.', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 20, 'Öhöndrögö ia, öfaulugö, ba taya ia; tobali mbawania öbe''e, ba ötimba ia.', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 21, 'Na lasöndra wa''ebua döi iraononia, ba lö i''ila; ba na ahöndrö ira, ba lö ba dödönia ya''ira.', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475479, 'OT', 'Yobi', 14, 22, 'Ha safökhö khönia i''ila ösinia; ha ya''ia ni''abusinia tödö."', '["Yes 26:20","Faigi 7:1","Faigi 34:21; Sin 56:9; Yer 32:19","MozV 32:34"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 1, 'Ba itema li Yobi Elifasi andrö, banua Dema, imane:[1]', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 2, '"Hadia, ilau maö huhuo nifahokha niha satua-tua, wanedema li, ba hadia, ifo''ösi narö dotonia angi timu —', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 3, 'fasosota si lö boto ba huhuo si lö guna?', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 4, 'Ba öfara''u na''i wangata''ufi Lowalangi, ba taya gera-era ba wangandrö khö Lowalangi, öbe''e.', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 5, 'Horöu andrö sa''ae wangatua-tua mbeweu, ba huhuo zonekhe ötuyu.', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 6, 'Bawau andrö zangetu''ö hukumö, ba beweu andrö zi möi sasi, udumö.', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 7, 'Hadia, si a''a niha ndra''ugö, me tumbu''ö, ba si a''a ndra''ugö moroi ba hili ba danö, me börötau?', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 8, 'Hadia, no örongo dödö Lowalangi, ba no öra''ui wa''atua-tua?[2]', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 9, 'Hadia ni''ilau, si lö ma''ila ena''ö, ba hadia zaboto ba dödöu, si lö aboto ba dödöma?', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 10, 'Ba khöma göi so zatua ba si no tohare huwa, sara ba guli danö, moroi ba wa''ara namau![3]', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 11, 'Hadia, ambö khöu wondrara tödö andrö, khö Lowalangi, ba fangehao li andrö khöu?', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 12, 'Hadia wa ifarou ndra''ugö falösökhi-sökhi dödöu, ba hadia wa tegaölögaölö bakha höröu,', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 13, 'wa no maoso dödöu khö Lowalangi, wa alua ba mbeweu wehede [si manö]?[4]', '["Yer 49 b.t.","Rom 11:34","Yer 49:7","Yak 3:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 14, 'Hadia niha, fa sohau-hau ia ena''ö, ba he moroi wa''atulö ni''adonogö ndra alawe?[5]', '["Faigi 4:17; Sin 14:3","Faigi 25:5; 1:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 15, 'Hiza, ba ni''amoni''ö andrö khönia na''i aombö dödönia, ba banua si yaŵa, ba tenga sohau-hau wamaiginia.[6]', '["Faigi 4:17; Sin 14:3","Faigi 25:5; 1:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 16, 'Ba mendrua manö ni''ogorofi andrö, si no fakuyu manö — niha andrö, samamadu idanö si lö atulö.', '["Faigi 4:17; Sin 14:3","Faigi 25:5; 1:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 17, 'Da''u''ombakha''ö khöu, fondrongondrongo khögu, ba hadia zi no i''ila hörögu, ba udunö-dunö khöu.', '["Faigi 4:17; Sin 14:3","Faigi 25:5; 1:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 18, 'Ni''ombakha''ö zatua-tua andrö, si lö labini''ö, si otarai götö ndra tua sa''ae.', '["Faigi 4:17; Sin 14:3","Faigi 25:5; 1:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 19, 'Khöra manö na danö; lö''ö na sa niha bö''ö si fatewu khöra.', '["Faigi 4:17; Sin 14:3","Faigi 25:5; 1:6 b.t."]', NULL),
  (3475480, 'OT', 'Yobi', 15, 20, 'Ba zebua horö, ba sagötö ya''ia, ba lö aefa wa''afökhö, ba no muhuku ndröfi ba zi höndrögö awönia.', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 21, 'Humöngö ba dögi dalingania zata''u ita; na lö hadia ia taŵa''ö, ba ihawui ia samufu.[7]', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 22, 'Aetu khönia wanötöna fa''aefa ba zogömi-gömi, ba no muhonogöi khönia mbawa zi''öli.', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 23, 'Mowaö-waö ia misa, mangalui gö — ba heza so? — i''ila, wa no mube''e fönania mbaŵa si lö haga.[8]', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 24, 'Ikeani ia fa''abu dödö ba fa''ata''u; ira''u ia, si mane razo si no mama''anö ya''ia ba wanuwö,', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 25, 'me no i''oro''ö dangania, fa''udusa ba Lowalangi, ba me no ilaŵa Zi lö ambö fa''abölö.', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 26, 'Amaedola isuwö — no abe''e mbörö du''i — ilau hulu mbalusenia, si no awe''e-we''e,', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 27, 'me no ibe''e balu-balu mbawania dawö ba me no motawö göi löwi-löwinia,[9]', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 28, 'me no i''agö mbanua nilakha''ö, ba me no i''onahia nomo, si lö tola so niha, si no muhonogöi adudula.[10]', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 29, 'Lö falukha mo''ana''a, ba lö aro ba dangania nibaya-bayania, ba lö adada ba danö nifa''ua zi manö.', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 30, 'Lö aefa ia ba zogömi-gömi; lewiönia, ba oköli ba galitö, ariri ia ba wönu Lowalangi.[11]', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 31, 'Böi abe''e dödönia ba waya, elungu ia: faya sa dania wangali.', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 32, 'Lö''ö na sa irugi baŵania, ba no itörö, ba aleu mbulu nohi khönia.', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 33, 'Itorugö mbuania si lakiritö, si mane agu, wa''atoru mbowonia, si mane fa''atoru mbowo falo.', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 34, 'Nga''ötö zebua horö, ba no timba zi mate, ba alitö zi manga nose zi manga gana''a.', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475480, 'OT', 'Yobi', 15, 35, 'Manabina famakao ira, ba la''adonogö wamakiko; faya lua-lua dalura."[12]', '["TesI 5:3","Sin 59:16; 109:10","MozV 32:15; Sin 17:10","RazI 16:34","Faigi 4:9","Sin 7:15; Yes 59:4"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 1, 'Ba itema li Gelifasi andrö Yobi, imane:', '["Faigi 13:4"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 2, '"No fahöna urongo zi manö; sondrara tödö fangabu dödö ami fefu.[1]', '["Faigi 13:4"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 3, 'Hadia, aetu sa''ae huhuo si lö boto andrö? ma hadia wamarou dödöu, wanedema ligu?', '["Faigi 13:4"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 4, 'Tola sa ulau göi huhuo nilaumi, asala si mane tödögu göi dödömi; tola sa ufakhai ena''ö huhuo khömi, ba tola ufalikhö ndra''o ba khömi andrö.', '["Faigi 13:4"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 5, 'Ba u''abe''e''ö ena''ö dödömi bawagu andre ba urara dödömi bewegu.', '["Faigi 13:4"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 6, 'Na humede ndra''o, ba lö alö wa''afökhö andre khögu; ba na lö hede-hedegu, ba hadia wa''alö?', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 7, 'Ba iya''e, ba no erege dödögu ibe''e; no öse''e zoroiyomogu fefu;', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 8, 'no öra''u ndra''odo, da''ö wamaduhu''ö. Tobali udugu wa''aririgu andrö, ikaoni ba mbawagu wangadugö ya''o.[2]', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 9, 'Isasawi ndra''o fönunia andrö, isuwö ndra''odo; ifatangi mbohania khögu: no udugu ia, i''atarösi hörönia khögu.[3]', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 10, 'No lafaboka mbawara khögu, lafalisi mbawagu, fa''ailagu; la''osara''ö dödöra fefu, udugu.[4]', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 11, 'No ilulu ndra''o Lowalangi, ba zolau si lö atulö, no itou''ö ndra''o ba danga zebua horö.[5]', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 12, 'Sohahau tödö mege ndra''odo, ba i''ogomuzaö ifufu ndra''o; no ituyu mbörö du''igu, ba no irasa ndra''o, ba no ibe''edo tandra wana khönia.', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 13, 'Tehawu ndra''o ono wana khönia; ifabali mbuagu, lö fa''ahakhö dödö, aduwa ba danö nösi gawökhu khögu ibe''e.[6]', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 14, 'Atölatöla ndra''odo ibe''e, ihawui ndra''o, si mane sanuwö.', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475481, 'OT', 'Yobi', 16, 15, 'No ube''e balu-balu gigimögu andrö gonigoni, utagu, ba no utaru''ö ba danö tou dandrugu.[7]', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 16, 'No oyo sibai mbawagu, ba wege-ege andrö, ba ba mbu hörögu, ba so lumö wa''amate.', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 17, 'He ŵa''ae lö si lö atulö, si falemba ba dangagu, ba he ŵa''ae lö famini tödö ba wangandrögu andrö.', '["Faigi 10:17","Faigi 13:24","Mikh 5:1","Sin 22","Faigi 6:4","Faigi 30:19"]', NULL),
  (3475481, 'OT', 'Yobi', 16, 18, 'He ya''ugö tanö, böi balugö ndrogu andrö! Böi yafalukha wolombase wangarö-ngarögu andrö:', '[]', NULL),
  (3475481, 'OT', 'Yobi', 16, 19, 'Iya''e sa''ae, ba hiza, ba ba zorugo andrö so zamaduhu''ö, khögu, ba ba zalaŵa yaŵa so zi so ba wali khögu.', '[]', NULL),
  (3475481, 'OT', 'Yobi', 16, 20, 'He ŵa''ae fasali khögu nawögu, ba khö Lowalangi ifaöga ia hörögu, mo''ala''ala.', '[]', NULL),
  (3475481, 'OT', 'Yobi', 16, 21, 'Ena''ö ibu''a ba hulu niha, khö Lowalangi, ba ba hulu nono niha, ba khö nawönia.', '[]', NULL),
  (3475481, 'OT', 'Yobi', 16, 22, 'Lö''ö sa oya tö ndröfi, ba utörö lala si lö fangawuli."', '[]', NULL),
  (3475482, 'OT', 'Yobi', 17, 1, '"Aböu hanu-hanugu, no ahori mbaŵa khögu, idöna-döna ndra''o lewatö.', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 2, 'Ba hiza, ba la''o''aya na ndra''odo, anehe ndra''o wasosota andrö khöra!', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 3, 'Be''e gade, ae ba wali khögu khöu! Ha niha na sa zi fara''u tanga khögu?[1]', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 4, 'Tödöra andrö, ba no öduhö, fa böi fa''aboto bakha, andrö göi lö öbe''e möna ira.', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 5, 'Na so zi manga mböli nawönia, ba ariri hörö nononia.', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 6, 'No ibe''e amaedola ndra''o, ba niha sato, tobali ladidiloi mbawagu.[2]', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 7, 'Ba balunö bakha hörögu ba wa''abu dödö, ba hato lumö ndroto-ndrotogu fefu.[3]', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 8, 'Ba da''ö tobali dödö zatulö tödö, ba maoso dödö zi lö horö ba zolau si lö sökhi andrö.', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 9, 'Ba lö''ö sa iböhöli lalania satulö tödö andrö, ba si lö hadia ia zi falemba ba danga, ba itugu abölö na.', '["Faigi 9:33","Faigi 30:9","Sin 6:8; 31:18"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 10, 'Ba ya''ami fefu, ba mi''ondrasi da''e ya''o; lö''ö sa ato usöndra zatua-tua ba khömi andrö.', '["Faigi 7:7; 9:25","Faigi 11:17"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 11, 'No numalö mbaŵa khögu; no aetu gera-era dödögu andrö, omasiö dödögu.[4]', '["Faigi 7:7; 9:25","Faigi 11:17"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 12, 'Labe''e si maokhö zi bongi, ahatö zi moluo laŵa''ö, ba si bongi zi so.[5]', '["Faigi 7:7; 9:25","Faigi 11:17"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 13, 'Na udöna-döna nahiagu mbanua tou, na ba zogömi-gömi ubologö dufogu;', '["Faigi 7:7; 9:25","Faigi 11:17"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 14, 'na fa''ama ndra''o ba lewatö, ba na fa''inado ba gukuö, ba ma na ga''agu lawe ube''e töinia,', '["Faigi 7:7; 9:25","Faigi 11:17"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 15, 'ba heza so dötönafögu? nidöna-dönagu, ba ha khö oroma?', '["Faigi 7:7; 9:25","Faigi 11:17"]', NULL),
  (3475482, 'OT', 'Yobi', 17, 16, 'Ba lazi mbawandruhö mbanua tou isaŵa mitou, na ba gawu-gawu tou ato so wa''ahono dödö."', '["Faigi 7:7; 9:25","Faigi 11:17"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 1, 'Ba itema li Yobi Bilidado andrö, banua Zua, imane:', '[]', NULL),
  (3475483, 'OT', 'Yobi', 18, 2, '"Ha wa''ara dania mibato wama''ua bewe andrö? Mi''era-era tödömi, ba awena dania fahuhuo ita.', '[]', NULL),
  (3475483, 'OT', 'Yobi', 18, 3, 'Hana wa mifaedo ita ba zaliŵa-liŵa ba danö, ba hana wa si lö tödö ita, wamaigimi?', '[]', NULL),
  (3475483, 'OT', 'Yobi', 18, 4, 'Ya''ugö andrö, sanasawi ya''ugö ba wönu andrö — hadia, lö niha sa''ae ba guli danö öbe''e, ba awu''a gara ba hili?', '[]', NULL),
  (3475483, 'OT', 'Yobi', 18, 5, 'Mate sa wandru zebua horö, ba hola-hola galitö khönia, ba no si lö haga.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 6, 'Taya haga baose khönia, ogömi-gömi, ba fandrunia, yaŵania, ba mate.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 7, 'Aböda mbekania, beka zabölö andrö, ba möi famakikonia nikhoi dödönia.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 8, 'Alau sa''ae gahenia ba gu''ö, ba itörö mbalu-balu lösu-lösu.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 9, 'Ikhai mbörö sisinia tandraŵa, iböbö ia fesu.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 10, 'Tou ba danö no labini''ö wesu khönia, fabaya aruru''a khönia ba lala.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 11, 'No te''u''u ia ba gameta''uö, mu''awa ia ibe''e, heza ihundragö danö.[1]', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 12, 'I''isö ia famakiko, ba i''olembai ngainia famufu.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 13, 'I''a ndroto-ndroto nösinia; i''ö''ökhi ndroto-ndrotonia si a''a nono wa''amate.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 14, 'Tesöbi da''ionia, teheta ia ba nosenia, nidönadönia, lö tola lö i''ondrasi razo gameta''uö andrö.[2]', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 15, 'Ba nosenia, ba monahia mbö''önia; tehawui talö balera nahiania mege.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 16, 'Moroi tou, ba mate ŵa''ania, ba ba hogu, ba aleu ndraha.[3]', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 17, 'Olifu niha ba danö ia; lö töinia sa''ae ba danö misa.[4]', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 18, 'Latimba ia ba zohaga, latuli''ö ba zogömi-gömi; lö''ö sa''ae lafonaha ia ba guli danö.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 19, 'Lö lewiönia sa''ae ba lö madounia ba niwara, ba lö sauri ba nahiania.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 20, 'Ba mbaŵania andrö tobali dödö mbanua tanö ba gaekhula, ba humokha mbu mbanua tanö ba gatumbukha.', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475483, 'OT', 'Yobi', 18, 21, 'Si manö sa''ae lala nahia zebua horö, si manö lala mbanua zi lö ba dödö Lowalangi."', '["Faigi 15:21; Yer 6:25; 46:5","Faigi 8:14","MozI 19:24","Sin 109:13; Amaed 2:22"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 1, 'Ba itema linia Yobi, imane:', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 2, '"Ha wa''ara na mibusi dödögu ba mirasa ndra''odo huhuomi andrö?', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 3, 'No mewulu sa''ae mitandraŵaisi ndra''o; lö aila ami mifakaodo.', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 4, 'Ba he meziŵa no molalö ndra''o, ba ha sambalö khögu mangawuli.', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 5, 'Na si ndruhu edöna fayaŵa ami khögu, ba mi''oroma''ö duruturu, börö wa''ailagu.', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 6, 'Ya''aboto ba dödömi, wa Lowalangi zamaöndrö ya''o, awö wa no ifa''u''u ndra''o u''önia andrö.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 7, 'Hiza, mu''ao ndra''o, umane: ''Famakao!'' ba lö samondrongo; u''andrö wanolo, ba lö folohe ba lala.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 8, 'No iba''a lalagu, fa tebai utörö, no ihawui fa''ogömi-gömi döröŵagu.[1]', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 9, 'Sumangegu, ba no ituyu, ba saembu ba högögu, ba no iheta.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 10, 'No ifasui ndra''o, wanudugö ya''odo ba taya ndra''o, ba no ideha dötönafögu, timba wondreha eu.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 11, 'Humola wönunia khögu, ba ifaedogö ndra''o ba zi fa''udu khönia.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 12, 'So moroi sa zanuwö andrö khönia, lafari lalara khögu ba lafasui nosegu olombaseŵara.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 13, 'Talifusögu, ba no aröu ifabali khögu, ba no fabö''ö sibai khögu zi fahuwu khögu mege.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 14, 'Lö''ö sa''ae möi khögu golembatagu, ba si no fa''ila li khögu, ba no olifu ira ndra''odo.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 15, 'Moroi yomo khögu ba sawuyugu ono alawe, ba labe''e niha bö''ö ndra''odo, no Dawa ndra''odo wamaigira.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 16, 'Na muhededo ba zawuyugu, ba lö itema ligu, na lö fakaodo khönia.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 17, 'Ogoro ngambatögu hanu-hanugu, ba si manö dalifusögu, ono ninagu, ba wa''aböugu andre.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 18, 'Numalö iraono, ba lö ba dödöra ya''odo; na maosodo ena''ö, ba lahede-hede''ö ndra''o.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 19, 'Dozi la''ogorofi ndra''odo si no fahuwu sibai khögu mege, ba somasi ndra''o ba no tobali udugu.[2]', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 20, 'Falemba ba dölagu guligu ba nagolegu, ba hato uli ba mbohagu zauri.', '["Faigi 3:23; Ngenu 3:7","Sin 38:12; 41:10; 69:9; 88:9"]', NULL),
  (3475484, 'OT', 'Yobi', 19, 21, 'Mihakhösi tödö ndra''o, mihakhösi tödö ndra''o, ya''ami si fahuwu khögu, noa sa gönado tanga Lowalangi!', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 22, 'Hana wa migohido, si mane Lowalangi, ba hana wa lö abuso ami wanasawi ya''odo?', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 23, 'Ena''ö na tetanö ba zura ligu andre; ena''ö na lasura ba gara wanura, —', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 24, 'nisura fanura si''öli ba simo, nisua ba gara, si lö tebulö, irugi zi lö aetu!', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 25, 'Ba u''ila: sauri zangorifi ya''odo, ba ifazaŵa dania ia, safuria, yaŵa gawu-gawu andrö.', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 26, 'Ba na no adudu guligu andre, ba anehedo Lowalangi, lö ösigu andre!', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 27, 'U''ila dania ia, fangorifigu, hörögu ya''o zangila ya''ia, ba tenga niha bö''ö: ariri dödögu, barö dotogu!', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 28, 'Ba na mimane: ''He tawisa wolohi ya''ia?'' na miwai, ba khögu so mbörö,', '[]', NULL),
  (3475484, 'OT', 'Yobi', 19, 29, 'ba mi''ata''ufi mbawa zi''öli — fönu sa, ba horö zi''öli — ena''ö aboto ba dödömi, so huku."', '[]', NULL),
  (3475485, 'OT', 'Yobi', 20, 1, 'Ba itema li Yobi Sofari andrö, banua Na''ama, imane:', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 2, '"Andrö wa hulö itema ligu era-eragu, me no humulu sibai bakha barö dotogu.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 3, 'Fanegu fangailagu urongo, ba i''ombakha''ö sa ato khögu geluaha eheha andrö ba wa''aboto ba dödögu.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 4, 'Hadia, lö örai örongo zi no arara andrö, fa''ara niha ba guli danö:', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 5, 'wa lö anau gölö wa''iki zebua horö, wa ha mamö''i hörö wa''ara wa''omuso dödö zi lö sökhi?[1]', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 6, 'He irugi mbanua si yaŵa wayaŵasania, ba he ibaya lawuo högönia,', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 7, 'ba si mane fa''ataya lazania, wa alua lö ya''ia dania, ba sangila ya''ia [mege], ba lamane: Heza so ia?', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 8, 'Si mane fa''ataya wangifi wa''atayania, lö oroma sa''ae, tefoloi, si mane lumö-lumö ba zi bongi.[2]', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 9, 'Hörö sangila ya''ia mege, ba lö''ö sa''ae i''ila ia, ba lö mangawuli ia ba nahania.[3]', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 10, 'Sondrara tödö zi numana nononia dania, ba samuli ana''a [ondra''ua] dangania.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 11, 'He no fahöna wa''abölö dölania, fa''abölö nono matua, ba fao dania khönia, ba wemörö barö danö.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 12, 'Na ami ba mbawania zi lö sökhi, na ibini''ö barö lelania,', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 13, 'na i''irö''ö ba na lö iböhöli, na ifalemba ba gararonia:', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 14, 'ba tobali gönia ba mbetu''ania bakha, tobali awökhu gulö ba dalunia.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 15, 'No i''a gana''a ba ifuli i''uta''ö, ifuli iheta ba dalunia Lowalangi.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 16, 'Söfu gulö isisiö mege, ba ibunu ia lela gulö sosöfu.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 17, 'Lö tola i''omusoi''ö dödönia ba gelea ŵe ŵani ba ba gelea susu andrö.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 18, 'Ifuli isao''ö baero gölönia, lö tola itölö: tebai omuso dödönia ba gana''a andrö nitukania.', '["Sin 37:35 b.t.","Sin 73:20","Faigi 7:8"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 19, 'Me no ifakao zi numana ba me lö nitolonia ya''ira — no i''okhögö nomo, ba lö i''aro''ö.', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 20, 'Me lö sahono-hono dalunia wangisö, ba tebai i''ohe zomasi ia ba wangorifi ya''ia ena''ö.', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 21, 'Lö fangorifi, ba wolu''a-lu''ania andrö, ba andrö wa si lö fozu gana''ania.', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 22, 'Ba wa''afahöna zi no a''oi so khönia tosasa ia; ihawui ia fa''abölö wa''anumana andrö.', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 23, 'Ba hiza dania: ba wamo''ösi dalunia, ba itewugö bakha [Lowalangi] hola-hola wönunia; ilau khönia deu, ba mbetu''ania bakha.', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 24, 'Na moloi ia, ba göröba si''öli, ba atöla ia ba nono wana töla.[4]', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 25, 'Ba isöbi, ba adöni ba nösinia, ba gawökhunia mege irugi ikhu zi''öli: ba ihawui ia, fa''ata''unia wa''amate.', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 26, 'No muhöna wamakiko, hadia ia ngawalö, ba girö-girönia andrö; i''a ia alitö, si tenga ni''ebua''ö niha; ihori zi tosai ba nosenia.[5]', '["Amos 5:19","Faigi 1:16"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475485, 'OT', 'Yobi', 20, 27, 'Ibokai hörönia banua si yaŵa, ba möi udunia danö.', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 28, 'Sawu''a gölönia baomonia, idanö sahele misa, na baŵa wönu Lowalangi.', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475485, 'OT', 'Yobi', 20, 29, 'Da''ö gurakha niha sebua horö, khö Lowalangi, da''ö dana khönia, ondröita, nihonogöi Wondrege zalaŵa khönia."', '["Amos 5:19","Faigi 1:16"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 1, 'Ba itema linia Yobi, imane:', '[]', NULL),
  (3475486, 'OT', 'Yobi', 21, 2, '"Mifondrondrongo, mifondrondrongo ligu andre! ya salahi wondrarami tödö da''ö.', '[]', NULL),
  (3475486, 'OT', 'Yobi', 21, 3, 'Böi abua khömi ndra''odo, na humededo, ba na aefa wehedegu, ba hana na ö''o''aya ndra''o.', '[]', NULL),
  (3475486, 'OT', 'Yobi', 21, 4, 'Hadia, ba niha, wa mangarö-ngarö ndra''odo, ba hana wa lö ambö wa''ebolo dödögu?', '[]', NULL),
  (3475486, 'OT', 'Yobi', 21, 5, 'Minehegö ndra''o, ba ya tobali dödömi, ba mi''okhö mbawami!', '[]', NULL),
  (3475486, 'OT', 'Yobi', 21, 6, 'Na itörö tödögu ine, ba tokeado, ba humokha mbu nösigu.', '[]', NULL),
  (3475486, 'OT', 'Yobi', 21, 7, 'Hana wa anau noso zanao horö, hana wa sara ba guli danö ira, ba hana wa itugu abölö ira.[1]', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 8, 'Sabölö nga''ötöra ba ngaira, ba zanehe ira, madoura andrö, la''ila-ila.', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 9, 'Lö hadihadia ba nahiara, lö ameta''uö: lö tohare khöra mbözi-bözi khö Lowalangi.', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 10, 'Saŵi si matua khönia [khö zanao horö andrö] ba fahömba ba ma''ono, sökhi wo''ono zigelo zaŵi khönia, ba lö saekhu.', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 11, 'Ladudu nono matua khöra, timba mbiri-biri, mamaröga misa ndraonora.', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 12, 'Manunö ira, labözi garamba ba lalau mbiola, la''omusoi''ö dödöra ba li zurune.[2]', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 13, 'Sagötö ya''ira, ba sohahau tödö ira; ba i''ogomuzaö dania, ba ahöndrö ira ba mbanua tou.', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 14, 'Ba noa sa lamane khö Lowalangi: ''Böi hatö''ögö khöma, lö omasiga aboto ba dödöma lala andrö khöu!', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 15, 'Ha niha Zi lö ambö fa''abölö andrö, wa möiga enoninia, ba hadia guna khöma, na ma''angaröfi li ia?''', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 16, 'Hiza, tenga moroi ba khöra wa''ohahau dödöra — ya aröu khögu dödö zebua horö andrö!', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 17, 'Ha ŵaraö ato mate wandru zebua horö, ha ŵara''ö itörö ira famakiko? Ha ŵaraö ilau wesu khöra ba wönunia?[3]', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 18, 'Ha ŵaraö hulö döla wakhe ira ba nangi, hulö ndrami, ni''oloi''ö nangi sabölö?[4]', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 19, '[Ba mimane:] ''Ibe''e yaŵa Lowalangi wamakikora, nifatörö ba nonora dania''. Khönia yamube''e zulö, ena''ö i''ila wa''afökhö![5]', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 20, 'Ena''ö hörönia zangila famakikonia andrö, ena''ö na ya''ia zamadu fönu Zi lö ambö fa''abölö andrö!', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 21, 'Hadia, abu maö dödönia nga''ötönia, na no mate ia, na no aetu mbaŵania andrö?', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 22, 'Hadia ta''atua-tua''ö Lowalangi andrö, sanguhuku si so ba zorugo?[6]', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 23, 'Si samösa, ba mate na hino wa''abölö na, lö''ö na hadia ia, lö fangabu dödö;', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 24, 'mo''ösi na susu rumbi andrö khönia, famo''ösi dölania uto.', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 25, 'Ba si samösa, ba mate abu dödö, lö irai i''ila wa''ohahau dödö.', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 26, 'Ba no faedo ira barö danö ba faoma tehawu ira kukuö.', '["Yer 12:1","Yes 5:12","Faigi 18:6; 20:29","Sin 1:4","Faigi 20:10","Faigi 15:12,13; Yes 40:13"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 27, 'Hiza, u''ila gera-erami, awö nikhoi dödömi andrö, wamalangögö ya''odo.', '["Faigi 18:15","Faigi 15:32"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 28, 'Na mimane: ''Heza so nomo zi faitoisi awönia, ba heza so nose andrö, nahia zebua horö mege?''[7]', '["Faigi 18:15","Faigi 15:32"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 29, 'Ba misofu manö ba zanörö lala, — tebai zi lö faduhu dödömi ba ni''ombakha''öra —', '["Faigi 18:15","Faigi 15:32"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 30, 'wa lö si göna hadia ia niha si lö sökhi, me baŵa wamakao, wa no te''ohe misa, me baŵa wa''atesao wönu.[8]', '["Faigi 18:15","Faigi 15:32"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 31, 'Ha niha zame''e famago mbawania bua-buania andrö? Ba na no ilau hadia ia, ba ha niha zanulöni khönia?', '["Faigi 18:15","Faigi 15:32"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 32, 'Ba lewatö te''ohe ia, ba sanaro na ia ba dete lewatö.', '["Faigi 18:15","Faigi 15:32"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 33, 'Ba okafukafu khönia danö ba ndraso, ba solo''ö ya''ia dozi niha, si mane si no mowaö-waö, si lö mutaha mu''erai.', '["Faigi 18:15","Faigi 15:32"]', NULL),
  (3475486, 'OT', 'Yobi', 21, 34, 'Ba hadia wa mirara dödögu faya-faya? Fanedemami andrö, ba ha sambalö si lö sökhi."', '["Faigi 18:15","Faigi 15:32"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 1, 'Ba itema li Yobi Elifasi andrö, banua Dema, imane:', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 2, '"Hadia, khö Lowalangi moguna wolau niha? Tenga sa khönia, sambua ya''ia, moguna nilau zatua-tua.[1]', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 3, 'Hadia, Si lö ambö fa''abölö zohare, na satulö tödö ndra''ugö? hadia, harenia, na lö sinegu khöu ba nitörömö andrö?', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 4, 'Hadia, i''otu''ö wangata''ufiu Lowalangi? da''ö mbörö, wa i''ohe ba huku ndra''ugö?', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 5, 'Hadia, lö ebua zi lö sökhi andrö khöu, ba tenga no si lö aetu lalöu?', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 6, 'Noa sa öhalö gade nibaya-baya dalifusöu, lö börö-börö, ba no öhalö gama-gama zi lö balu-balu.[2]', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 7, 'Lö nifabadugöu idanö ba zi mate owökhi dödö, ba lö nibe''eu ö ba zolofo.[3]', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 8, 'Niha sabölö zokhö tanö, ba salaŵa sotöi zi onahia.', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 9, 'Si no mate ira matua, ba öfofanö lö ni''odöra, ba nirasa da''io zi lö ama, si lö ina.', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 10, 'Andrö wa no tefasui ndra''ugö fesu, ba ikeani ndra''ugö ameta''u''ö, lö mudöna-döna.', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 11, 'Ma lö ö''ila wa''ogömi-gömi, awö molö andrö, si nönöi ya''ugö?', '["Faigi 35:7; Luk 17:10","MozII 22:26","Faigi 31:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 12, 'Hadia, tenga fa''alaŵa mbanua si yaŵa wa''alaŵa yaŵa Lowalangi? Faigi wondrege ndröfi andrö, ha wa''alaŵa yaŵa?', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 13, 'Ba ömane na sa: ''Hadia ni''ila Lowalangi? Hadia, molala wanguhukunia, ba lawuo sogömi-gömi?[4]', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 14, 'Ba''a-ba''a khönia lawuo, fa lö i''ila hadia ia, ba ba dete mbanua yaŵa manörö-nörö ia.''', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 15, 'Hadia, ötörö lala ba götö föna, nitörö niha sanaonao horö?', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 16, 'ya''ira andrö, nira''u, me tenga inötö na, sahele dayadaya, timba nidanö?[5]', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 17, 'Sanguma''ö khö Lowalangi: ''Böi hatö''ögö khöma!'' ba hadia nilau Zi lö ambö fa''abölö khöra ena''ö?[6]', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 18, 'Ba noa zui ihöna howu-howu baomo khöra — ya aröu khögu dödö zebua horö andrö![7]', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 19, 'La''ila satulö tödö, ba omuso dödöra, ba i''o''aya ira si lö horö [imane]:', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 20, '''Si ndruhu, no muhori nuduma, ba si tosai khöra ba no i''a alitö!''', '["Sin 10:11","MozI 6:13","Faigi 21:14","Faigi 21:16"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 21, 'Lau fahuwu khönia, fa ohahau dödöu, fama''ema howu-howu khöu.', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 22, 'Töngöni lala, ba niŵa''önia andrö, ba tanö ba dödöu daroma linia.', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 23, 'Na öfuli''ö khö Zi lö ambö fa''abölö, na ö''ide-ide''ö ndra''ugö, na öheta baose khöu zi lö atulö, na ö''aröu''ö[8] —', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 24, 'tema tibo''ö ba danö lele garamba andrö, ba orudugö ba nene ba mbombo mbalaki! —', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 25, 'ba tobali ana''au Zi lö ambö fa''abölö, ba firöu, safusi sibai.', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 26, 'Owua-wua sa dania dödöu Zi lö ambö fa''abölö andrö, ba öfaöga mbawau khö Lowalangi.', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 27, 'Na ö''angaröfi li ia, ba ifondrondrongo khöu, ba öbu''a gamabu''ula limö andrö.[9]', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 28, 'Na ölau hadia ia, ba mofozu, ba mohaga döröŵau andrö.', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 29, 'Na mitou isaŵa, ba ömane: Ohe yaŵa! ba itolo zi köwö ya''ia,[10]', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475487, 'OT', 'Yobi', 22, 30, 'I''orifi zi tenga si lö horö, te''orifi me lö hadia ia zi falemba ba dangau."', '["Faigi 8:5","Sin 50:14","Amaed 29:23; Mat 23:12; Yak 4:6"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 1, 'Ba itema linia Yobi, imane:', '["Faigi 13:17 b.t."]', NULL),
  (3475488, 'OT', 'Yobi', 23, 2, '"Irege ma''ökhö andre fatandro wege-egegu, abua wa''atohare dangania ba wangarö-ngarögu.', '["Faigi 13:17 b.t."]', NULL),
  (3475488, 'OT', 'Yobi', 23, 3, 'Ena''ö na u''ila, heza usöndra ia, ena''ö na ukhamö dadaomania andrö!', '["Faigi 13:17 b.t."]', NULL),
  (3475488, 'OT', 'Yobi', 23, 4, 'Ba ufarongogö khönia huhuogu andrö, ba uhöna wanutunö ngamohi.', '["Faigi 13:17 b.t."]', NULL),
  (3475488, 'OT', 'Yobi', 23, 5, 'Omasido u''ila hadia niŵa''önia wanema ligu, ba omasido urongo hadia linia khögu.', '["Faigi 13:17 b.t."]', NULL),
  (3475488, 'OT', 'Yobi', 23, 6, 'Hadia fasoso maö ia khögu ba wa''afahöna wa''abölönia? Tenga; ha ifondrongondrongo khögu.[1]', '["Faigi 13:17 b.t."]', NULL),
  (3475488, 'OT', 'Yobi', 23, 7, 'Ba fabu''abu''a sa''ae khönia zadölö tödö, ba u''osamuzaigö wangefa''ö ya''odo ba zanguhuku ya''o.', '["Faigi 13:17 b.t."]', NULL),
  (3475488, 'OT', 'Yobi', 23, 8, 'Ba hiza — na usaŵa gatumbukha luo, ba lö ya''ia, ba na möido tanö ba gaekhula, ba lö oroma ia khögu.', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 9, 'Yöu ilau nilaunia, ba lö u''ila ia, ba ihole''ö ia miraya, ba lö anehedo ia.', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 10, 'Noa sa''ae i''ila gangosisilagu mege; na itandraigö ndra''odo ena''ö, ba timba mbalaki wa''oromagu.', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 11, 'Lö saefa gahegu ba lahenia, lala khönia ni''osisigu, lö nihole''ögu ya''odo.', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 12, 'Amakhoitania andrö, nibe''enia, ba lö misawögu, ba barö dotogu u''irö''ö daroma linia niŵa''önia.[2]', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 13, 'Ba ya''ia, ba si manö-manö — ha niha zanenaŵa ya''ia? Sedöna dödönia, ba ifalua.[3]', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 14, 'I''o''ozui sa''ae nihonogöi khögu, wa''oya na ba dödönia si manö.', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 15, 'Andrö wa tokea ndra''odo, na ifaigido; na ufatou-tou, ba manizi-nizido khönia.[4]', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 16, 'Noa sa atalö dödögu, ibe''e Lowalangi; sata''u ndra''o ibe''e Si lö ambö fa''abölö.', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475488, 'OT', 'Yobi', 23, 17, 'Tenga sa ba wamakao andrö mbörö, wa hulö zi no afufu ndra''o, ba tenga ba khögu andre, sambua ya''o, si no tehawu fa''ogömigomi."[5]', '["Rom 7:23","Sin 115:3","Faigi 21:6","Faigi 17:1,13"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 1, '"Hana wa lö ihonogöi ginötö [wanguhuku] Si lö ambö fa''abölö, ba hana wa lö la''ila mbaŵa andrö khönia si lö faröi khönia?', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 2, 'Lawu''ai nola [niha si lö sökhi], larabu gurifö ba lakubaloi.[1]', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 3, 'La''oloi''ö kudo zi lö ama si lö ina, ba lahalö gade zaŵi lakha mbanua.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 4, 'Latimba zi numana, ba lala: samini''ö ya''ira dozi sebua famakao ba danö.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 5, 'Hiza, hulö göröbao ndru''u ba danö si mate we''amöira ba halöŵöra, mangalui gö; ba danö si mate lasöndra gö nonora.[2]', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 6, 'Ba nowi latataba gö gurifö, ba ba kabu zebua horö la''ozaragö wo''uwo''u.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 7, 'Mörö manö lö balu-balu, lö nukha ba lö ambala ba wa''oafu.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 8, 'Oi hambunö ira, ba deu ba hili, ba la''olembai gara ba hili, lö ose. —', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 9, 'Larabu zi lö ama, ba mbagi zusu nina, ba lahalö gade nibaya-baya zebua famakao.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 10, 'Mowaö-waö manö lö balu-balu, lö nukha, ba olofo, wangohu basitö.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 11, 'Barö göli [khö zokhö ya''ira] lalazi wanikha, lahundragö wolazi nagu, ba sowökhi tödö ira.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 12, 'Moroi ba mbanua misa terongo wangarö-ngarö zi mate, mu''ira-ira ni''ö''ötö, ba i''osilömilagö zi lö atulö andrö Lowalangi.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 13, 'Ba so ösa, ba zi fatuwu haga; lala andrö khönia, ba lö la''ila, lö latörö zinörö andrö khönia.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 14, 'Na ogömi-gömi na ifazaŵa ia sange''e, ibubunu zebua famakao ba si numana, ba ba zi bongi, ba amaedola zanagö ia.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 15, 'Ba si möi mohorö, ba ibase''ö wa''abongi, imane dödönia: ''Lö sangila ya''odo'', ba ifobalu-balu mbawania.[3]', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 16, 'Ba zi bongi manöi yomo, ba ba zi ma''ökhö, ba labini''ö ira, lö omasi ira haga.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475489, 'OT', 'Yobi', 24, 17, 'Khöra fefu, ba no timba dalu mbongi wa''amoluo, ba gameta''uö ba zi bongi, ba no to''ölö ira.', '["MozV 19:14","MozI 16:12","Sin 10:11"]', NULL),
  (3475489, 'OT', 'Yobi', 24, 18, 'Hulö zihombo ba guli nasi ia; ni''elifi dana khöra tanö; lö''ö sa''ae itörö lala ba kabu nagu.[4]', '["Faigi 5:3 b.t."]', NULL),
  (3475489, 'OT', 'Yobi', 24, 19, 'Na lökhö ba na aukhu zino, ba ogo''ö daŵa deu, ba si manö wemanga mbanua tou si no mamazökhi horö.', '["Faigi 5:3 b.t."]', NULL),
  (3475489, 'OT', 'Yobi', 24, 20, 'Olifu ninania ia, inania sadono ya''ia: kukuö zi manga-manga ya''ia; lö''ö sa''ae itörö tödö niha bö''ö ia, ba hulö wa''afatö geu wa''afatö wanao horö andrö.', '["Faigi 5:3 b.t."]', NULL),
  (3475489, 'OT', 'Yobi', 24, 21, 'Ya''ia andrö, si anagöi si lö ono, ba si lö irai manolo si no mate ira matua.', '["Faigi 5:3 b.t."]', NULL),
  (3475489, 'OT', 'Yobi', 24, 22, 'Ba itolo zi faitoisi awönia, fa''abölönia andrö; ifuli abe''e zi manö, na noa sa''ae idöna-döna wa''amate.', '["Faigi 5:3 b.t."]', NULL),
  (3475489, 'OT', 'Yobi', 24, 23, 'Ifa''ema khönia wa lö hadia ia, ba te''abe''e''ö ia, ba ihörö-hörögö lalara.', '["Faigi 5:3 b.t."]', NULL),
  (3475489, 'OT', 'Yobi', 24, 24, 'No alaŵa yaŵa ira — ba lö arara, ba lö ya''ira sa''ae; sahöndrö ira — nitutuyu, si mane tanö bö''ö fefu, nitataba, si mane ngalai wakhe.', '["Faigi 5:3 b.t."]', NULL),
  (3475489, 'OT', 'Yobi', 24, 25, 'Ba na tenga si manö, ba ha niha zanguma''ö solau faya ndra''o; ha niha zame''e si lö boto niŵa''ögu?"', '["Faigi 5:3 b.t."]', NULL),
  (3475490, 'OT', 'Yobi', 25, 1, 'Ba itema li Yobi Bilidado andrö, banua Zua, imane:', '["Faigi 4:17; 15:14"]', NULL),
  (3475490, 'OT', 'Yobi', 25, 2, '"Khönia wamatörö ba fa''asalaŵa; no atulö ba zalaŵa yaŵa andrö khönia, ibe''e.', '["Faigi 4:17; 15:14"]', NULL),
  (3475490, 'OT', 'Yobi', 25, 3, 'Hadia, tataha mu''erai zato sibai andrö khönia, ba hezo zi lö isului hagania andrö?', '["Faigi 4:17; 15:14"]', NULL),
  (3475490, 'OT', 'Yobi', 25, 4, 'Ba he moroi atulö niha föna Lowalangi, ba heza ihalö wa lö da''i ni''adonogö ndra alawe [niha]?[1]', '["Faigi 4:17; 15:14"]', NULL),
  (3475490, 'OT', 'Yobi', 25, 5, 'Hiza, numalö baŵa yaŵa, ba ambö fa''atara haga, ba döfi, ba tenga si lö da''i wamaiginia.', '["Faigi 4:17; 15:14"]', NULL),
  (3475490, 'OT', 'Yobi', 25, 6, 'Ba mendrua manö niha, bonga andrö, ba ono niha, si no timba gukuö!"', '["Faigi 4:17; 15:14"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 1, 'Ba itema linia Yobi, imane:', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 2, '"No maulu wanolou si tebai ba fangabe''eu ta''io, sambö fa''abe''e.', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 3, 'Wa''asökhi wamolalamö ba zambö tödö ba fama''ele fa''atua-tua, si no fahöna!', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 4, 'Ha khö öfarongogö huhuo andrö, ba ha eheha zalua ba mbeweu?', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 5, 'Manizi-nizi mbekhu tou nasi, ba tou zaliŵa-liŵa bakha.', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 6, 'Lö balu-balu mbanua tou, fönania, ba lö ba''a-ba''a gawuwukha.[1]', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 7, 'Ibologö mbanua si yaŵa yöu, yaŵa zi lö ösi andrö, ba no ifanaŵanaŵa danö yaŵa zi lö''ö.[2]', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 8, 'Teu andrö, ba no ibu''ugö ba lawuo andrö khönia, ba lö asika lawuo ba wa''abuania.', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 9, 'Iba''a wamaigi dadaomania, wamologö lawuo andrö khönia, fönania.', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 10, 'No ifakhoi nola ba guli nasi, irugi ba wabaliŵara zi moluo zi bongi.[3]', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 11, 'Mangiwa gehomo mbanua si yaŵa ba tokea, na mofönu ia.', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 12, 'Ba wa''abölönia ifahufa nasi, ba ba wa''aboto ba dödönia irasa Rakhaba andrö.[4]', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 13, 'Ba hanu-hanunia tehoi zalu mbanua, ba no ifahö dalu naga soloiloi andrö tangania.[5]', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475491, 'OT', 'Yobi', 26, 14, 'Ba hiza, ba ha singasinga nitörönia da''ö, ba hulö ha tiutiu li nirongoda khönia! Ba fe''ugu-ugu wa''abölönia si lö ambö andrö, ba ha niha zaboto ba dödö!"', '["Sin 139:8; Amaed 15:11; Yer 5:22","Sin 104:2","MozI 8:22; Yer 5:22; Amaed 8:29","Faigi 9:13; Yes 51:9","Sin 33:6"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 1, 'Ba itohugö huhuonia Yobi, imane:', '[]', NULL),
  (3475492, 'OT', 'Yobi', 27, 2, '"Ba wa''aduhu wa''auri Lowalangi, si no momba''a khögu lala, fa''auri Zi lö ambö fa''abölö andrö, si no mamusi tödögu —', '[]', NULL),
  (3475492, 'OT', 'Yobi', 27, 3, 'A''oi sa so na nosogu barö dotogu, ba hanu-hanu Lowalangi andrö ba nikhugu —:', '[]', NULL),
  (3475492, 'OT', 'Yobi', 27, 4, 'Tenga faya nilau mbewegu, ba tenga falimosa lua-lua lelagu.', '[]', NULL),
  (3475492, 'OT', 'Yobi', 27, 5, 'Ya aröu khögu wanehe niŵa''ömi andrö; irege aetu nosogu, ba lö uböhöli wa lö horögu.', '[]', NULL),
  (3475492, 'OT', 'Yobi', 27, 6, 'U''aro''ö khögu wa''atulögu, lö uböhöi; sara luo khögu lö itegudo tödögu.', '[]', NULL),
  (3475492, 'OT', 'Yobi', 27, 7, 'Ya oroma, wa solalö nudugu andrö, awö wa si lö atulö zolaŵa ya''odo!', '[]', NULL),
  (3475492, 'OT', 'Yobi', 27, 8, 'Hadia sa dötönafö zanaonao horö, na i''etu''ö nosonia Lowalangi, na ideha ba dotonia?', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 9, 'Hadia, ifondrondrongo we''aonia Lowalangi, na göna ia fa''atosasa?[1]', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 10, 'Hadia, tola i''omusoi''ö tödönia Zi lö ambö fa''abölö, ba tola ero ma''ökhö i''angaröfi li Lowalangi?', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 11, 'Da''ufahaö ami ba nilau danga Lowalangi andrö; lö ubini''ö khömi, he wisa dödö Zi lö ambö fa''abölö.', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 12, 'Hiza, no mi''ila, ya''ami andrö, dozi; ba hana wa mifa''ua waya-faya?', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 13, 'Da''ö dana ba niha si lö sokhi khö Lowalangi, da''ö zinema zamakao awönia, nitemania khö Zi lö ambö fa''abolö:[2]', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 14, 'Na oya nononia, ba ö mbawa zi''öli, ba madounia, ba no sambö balazo.', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 15, 'Si tosai soroiyomonia, ba möi barö danö, na teu mbanua, ba lö mange''esi lakha mbanua andrö khönia.', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 16, 'Na ihöna wirö, timba nene, ba na i''oya''ö nukha, timba dambu newali [wa''oya] —', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 17, 'ya''ia zangöhöna, ba satulö zi onukha, ba firö andrö, ba lafaosa khöra si lö horö.[3]', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 18, 'Ilau nahiania, nifolau galaŵa; hulö nose, nitaru''ö zanaro hadia ia, ibe''e.', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 19, 'Sebua ana''a na ia, na möi ia mörö, ba lö''ö sa''ae samuza tö; tokea ia, ba lö ya''ia sa''ae.', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 20, 'Ihawui ia ameta''uö, hulö molö; ba zi bongi i''oloi''ö ia angi sabölö.[4]', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 21, 'Ifazaŵa ia angi timu, ba numalö misa; i''oloi''ö ia, aheta ba nahania.', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 22, 'Ilau khönia [Lowalangi], lö fa''ahakhö dödö, ba moloiloi ia, ba dangania andrö [ba danga Lowalangi].', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475492, 'OT', 'Yobi', 27, 23, 'Ba lalau datawo khönia, ba fasi khönia, moroi ba nahania mege."', '["Sin 18:42; Yes 1:15; Yer 11:11; Hez 8:18; Mikh 3:4; Yoh 9:31","Faigi 20:29","Amaed 28:8","Faigi 18:11"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 1, '"So sa nisöndra firö ba so naha gana''a, ba nikhozi ya''ia.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 2, 'Si''öli, ba nihalö ba danö, ba lalaugö gara, ba alua döla garamba.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 3, 'Lö''ö sa''ae sogömi-gömi labe''e, ba irugi ba wondrege la''alu-alui ngawalö gara si no tobini ba zogömi-gömi sibai.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 4, 'Lakhao mitou dögi, sabakha, i''otarai zonahia ba dete danö yaŵa; manaŵanaŵa ira, taya ba dödö zanörö [tete yaŵa], aröu niha bö''ö.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 5, 'Alua ba danö mbalazo, ba sabakhania si tou, ba lafahufa, hulö nifatörö alitö.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 6, 'Feremata nila nisöndra ba gara andrö, ba faruka göi mbalaki.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 7, 'Lala andrö, ba lö i''ila moyo, lö irai i''ila hörö zumbila.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 8, 'Lö itörö utu ndru''u sebua, ba tenga göi töröŵa zingo.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 9, 'Laboto gowe, tobali arö hili labe''e.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 10, 'Lafo''arö gara ba hili, lala niha, ba oya i''ila hörönia ngawalö omasiö [sebua böli].', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 11, 'Laba''a gelea, fa böi bölaböla, ba la''ohe ba zohaga zi no tobini mege.', '[]', NULL),
  (3475493, 'OT', 'Yobi', 28, 12, 'Ba fa''atua-tua andrö, ba heza lasöndra da''ö? ba heza so nahia wa''aboto ba dödö?[1]', '["Amaed 2:6,8; Yak 1:5","Amaed 3:14"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 13, 'Samösa lö sangila lala wangai ya''ia, ba lö falukha ba danö, ba danö niha sauri.', '["Amaed 2:6,8; Yak 1:5","Amaed 3:14"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 14, 'Imane namö: ''Lö ya''ia ba khögu''. Ba imane asi: ''Ba khögu lö falukha''.', '["Amaed 2:6,8; Yak 1:5","Amaed 3:14"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 15, 'Tebai bölinia mbalaki satua, ba he firö, ba tebai latulo bölinia.[2]', '["Amaed 2:6,8; Yak 1:5","Amaed 3:14"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 16, 'Tebai lafatimba ana''a Gofiri, ba he feremata una ba nila.', '["Amaed 2:6,8; Yak 1:5","Amaed 3:14"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 17, 'Tebai tefaedogö khönia mbalaki, ba he sörömi, ba tebai labe''e fanukania gama-gama balaki.', '["Amaed 2:6,8; Yak 1:5","Amaed 3:14"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 18, 'Meredia ba baluri, ba lö oroma ba ngainia; ba na tasöndra wa''atua-tua, ba ebua moroi ba mani-mani.', '["Amaed 2:6,8; Yak 1:5","Amaed 3:14"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 19, 'Retana sambaka Gaitiofia, ba lö fagölö-gölö khönia; tebai lafatimba si ndruhu mbalaki.', '["Amaed 2:6,8; Yak 1:5","Amaed 3:14"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 20, 'Ba fa''atua-tua andrö, ba heza i''otarai, ba heza falukha wa''aboto ba dödö?', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 21, 'No tobalu; lö i''ila hörö niha sauri fefu, ba he ba wofo ba dalu mbanua, ba lö oroma.', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 22, 'Banua tou andrö ba fa''amate, ba lamane: ''No irongo tögi dalingama duriania.''', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 23, 'Lowalangi zangila lala khönia, ya''ia zangila heza tesöndra.', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 24, 'Ikhamö sa''ae hörönia wondrege danö; fefu gofu hadia zi so barö mbanua si yaŵa, ba i''ila.', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 25, 'Me itulo wa''abölö nangi, ba me ifakhoi wondrege nasi,[3]', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 26, 'ba me ifakhoi lala deu ba töröŵa gari mbanua.', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 27, 'ba da''ö i''ila [wa''atua-tua andrö] ba ifa''ele''ö, ba ifaedogö ba i''alu-alui gamuata.', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475493, 'OT', 'Yobi', 28, 28, 'Ba imane ba niha: "Hiza, fangata''ufi So''aya, da''ö wa''atua-tua, ba na lö tebabaya zi lö sökhi, da''ö wa''aboto ba dödö."[4]', '["Sin 135:7","Sin 111:10; Amaed 1:7; 9:10; Sangomb 12:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 1, 'Ba itohugö huhuonia Yobi, imane:', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 2, '"Ena''ö na si mane me baŵa föna ndra''odo, si mane me luo irorogö ndra''o Lowalangi,', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 3, 'me ihagaini högögu sulunia andrö, me ba hagania utörö zogömi-gömi andrö,', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 4, 'si mane me baŵa lökhö khögu, me ilumö''ö nosegu fahuwusa Lowalangi,[1]', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 5, 'me fao-fao na khögu Zi lö ambö fa''abölö, me so ba ngaigu na nonogu matua;', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 6, 'me ufemondrimondri gahegu ba zusu zaŵi, ba me mo''elea fanikha gara ba hili, ba ngaigu;[2]', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 7, 'me möidomöido barö mbawa göli ba mbanua, me baewalinia ube''e dadaomagu.', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 8, 'Na la''ila ndra''o ono matua, ba labini''ö ira, ba satua, ba maoso ba muziozio.', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 9, 'Salaŵa, ba labato huhuo, la''okhö mbawara.', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 10, 'Si lö li sa''ae zebua töi, falemba ba gararora lelara.', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 11, 'Na irongo [ligu] tögi dalinga niha, ba ifahowuhuwu''ö ndra''odo; ba na i''ilado hörönia ba ifaduhu''ö ndra''o.', '["Sin 25:14; Amaed 3:32; Amos 3:7","MozV 32:13"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 12, 'Me no sangorifi sebua famakao ndra''odo, na mangarö-ngarö ia, awö zi lö ama, si lö ina, si lö sanolo.[3]', '["Sin 72:12"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 13, 'Lafahowu-howu''ö ndra''o si tekiko mena''ö, ba owua-wua dödö zi no mate ira matua, ube''e.', '["Sin 72:12"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 14, 'U''onukha wa''atulö, ba amaedola i''onukha ndra''o fa''atulö andrö; hulö mbaru sebua ba hulö zaembu oti khögu wa''adölö dödögu andrö.', '["Sin 72:12"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 15, 'Ba zi lö hörö, ba hörö ndra''odo, ba ahe ndra''o ba zi no ombuyu-mbuyu töla.', '["Sin 72:12"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 16, 'Ama ndra''o ba zi numana, ba u''alui lala ba huhuo zi lö irai fa''ila li ndra''odo.', '["Sin 72:12"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 17, 'Urasa zimbi zamakao awönia, ba usöbi ba niföra gondra''uara.', '["Sin 72:12"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 18, 'Ba umane dödögu: ''Ba zinga gazunigu andrö mate dania ndra''o, ba fa''anau noso wofo fenisi wa''anau nosogu.', '["MozI 49:24","MozV 32:2"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 19, 'Molala nidanö ba ŵa''agu, ba mörö namo mbanua ba ndrahagu.', '["MozI 49:24","MozV 32:2"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 20, 'Mangalingali wa''ebua döigu andrö, ba ifulifuli bohou wanagu andrö, ba dangagu.''[4]', '["MozI 49:24","MozV 32:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475494, 'OT', 'Yobi', 29, 21, 'Khögu lafondrongondrongo ba mombasembase, ba lö hede-hedera, na ufolala hadia ia.', '["MozI 49:24","MozV 32:2"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 22, 'Na no fahuhuo ndra''odo, ba lö hede-hedera sa''ae; amaedola zowoi khöra moroi yaŵa huhuogu andrö.[5]', '["MozI 49:24","MozV 32:2"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 23, 'Labazebaze''ö ndra''o, amaedola wombase''ö teu, lafaboka mbawara, si mane ba deu sara andrö.', '["MozI 49:24","MozV 32:2"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 24, 'No uboho mbawagu wa''iki khöra, na no aragu-ragu dödöra; ba lö irai labe''e taya wehaga mbawagu andrö.', '["MozI 49:24","MozV 32:2"]', NULL),
  (3475494, 'OT', 'Yobi', 29, 25, 'U''alui lala khöra, dumadaodo salaŵara, si mane razo ba hunö zabölö, si mane sondrara tödö zabu tödö."', '["MozI 49:24","MozV 32:2"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 1, '"Ba iada''e, ba la''igi''igi''ö ndra''odo si akhi moroi khögu, ba ira amara, ba no si tenga si nangea ube''e awö nasu gubalo khögu.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 2, 'Ba fa''abölö dangara, ba hadia guna khögu? Sariri so ato ira.[1]', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 3, 'Soköliköli sa''ae ira, ba wa''ambö gö ba ba wa''olofo, la''ö''ökhi danö si mate, si bongi ba zasai''ö ba ba ndrekha.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 4, 'Lakhete mbulu ndru''u, ba ŵa''a da''uli göra.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 5, 'Latimba ira niha bö''ö; mu''ao ba khöra andrö, hulö ba zanagö.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 6, 'Ba mbaho danö sihokha mbuda nahiara, ba dögi narö hili ba ba dögi gara.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 7, 'Ba dalu zasai''ö mundröndröndröndrö ira, ba mbörö lato orudu ira.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 8, 'Ono zowöhö mowa ba ono zi lö töi: lafofanö ba danö, labözi-bözi moroi furi.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 9, 'Ba iada''e, ba ayara ndra''o, amatoulara.[2]', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 10, 'La''ogorofi ndra''o, la''aröu''ö ira khögu; lö ata''u ira wondriloi bawagu.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 11, 'Noa sa ilulu zinaligu Lowalangi, ba no ifaöndrö ndra''o; ba lalau-lau manö khögu.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 12, 'Ba gambölö maoso zi si lö yaŵa andrö, latimba gahegu ba lafari lalara khögu, lala ba wamakiko.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 13, 'Lalagu, ba no ladudugö, latolo ba wolaugö ya''odo, ya''ira andrö, si lö sanolo.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 14, 'Hulö zanörö si no ebolo atöla göli wa''asora; adudula latörö, wanguhurufai ya''odo.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 15, 'Ameta''uö ba gamaudugu, te''oloi''ö wa''asalaŵagu, timba ba nangi sabölö, ba hulö wa''ataya lawuo wa''ataya wa''ohahau dödögu.', '["Faigi 24:7 b.t.","Faigi 7:6; Sin 69:13; Ngenu 3:14"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 16, 'Ba iada''e, ba maniö nosogu barö dotogu, itahado baŵa wamakao.', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 17, 'Manögi ba dölagu zi bongi, faefa ibe''e, ba no si lö mörö zi ö''ökhi ya''odo.', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 18, 'Ba wa lö ambö fa''abölö andrö, ba hulö zi tobali mbarugu, si mane töla mbagi kameza khögu wa''afatöfania khögu.[3]', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 19, 'No ituli''ö ba dambu ndra''odo, ba no fadoro gawu-gawu ba awu ndra''o.', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 20, 'U''angaröfi li ndra''ugö, ba lö ötema ligu; sodo ba da''ö, ba ötöngötöngö manö ndra''o.', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 21, 'Öbali''ö si lö fa''ahakhö dödö ndra''ugö khögu, udugu ndra''ugö, ba wa''abölö dangau andrö.[4]', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 22, 'Öfazaŵa ndra''o, öbe''edo ba nangi sabölö, numalö misa ndra''o öbe''e, humombo ndra''o ba nangi.', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 23, 'U''ila sa''ae: ba wamunu ö''ohe ndra''o ba ba gorudua zauri, fefu.[5]', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 24, 'Ba hadia, lö ta''oro''ö dangada, na alau ita? Ba hadia, lö mu''ira-ira ita, na alömö ita?', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 25, 'Ba hadia, lö ni''e''esigu si no göna famakao, ba lö sahakhö dödögu si numana?[6]', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 26, 'Si sökhi sa udöna-döna, ba itörödo si lö sökhi; haga udöna-döna, ba sogömi-gömi zalua.', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 27, 'Si fadoro mo''otu bakha narö dotogu; ihawuido baŵa wamakao.', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 28, 'Mawaö-waödo manö, no aitö ndra''odo, ba tenga moroi ba wa''aukhu zino; maoso ndra''o mangarö-ngarö, ba zowulo niha.', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 29, 'No tobali iwa nasu ana''a ndra''odo ba awö wofo ondra.[7]', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 30, 'No aitö guligu, abo''a ba nösigu, ba hulö zi no akhozi dölagu; ba wa''aukhu andrö.[8]', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475495, 'OT', 'Yobi', 30, 31, 'Ba no tobali fangarö-ngarö li mbiola khögu, ba fege-ege li zurune."', '["Faigi 16:15","Faigi 16:9","Heb 9:27","Sin 35:13; Rom 12:15; Faigi 29:12 b.t.","Mikh 1:8","Sin 102:4; 119:83; Ngenu 4:8; 5:10"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 1, '"No u''abe''e''ö nifakhoigu ba hörögu andre ba hana wa uleke''ö mena''ö nono alawe![1]', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 2, 'Hadia nifatörö Lowalangi mena''ö moroi yaŵa ba hadia dana khögu khö Zi lö ambö fa''abölö ba mbanua si yaŵa?', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 3, 'Hadia, tenga famakiko dana ba zanaonao horö, ba tenga famakao ba zamazökhi si lö sökhi?', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 4, 'Hadia, lö anehe ia lalagu andrö, ba bekagu, ba hadia, lö i''erai?[2]', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 5, 'Na si falimolimo ndra''odo ba na i''ohi waya-faya ahegu, —', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 6, 'ba yamutulo ndra''o Lowalangi, ba waliera, si lö fa''angaya, ena''ö i''ila, wa si lö horö ndra''o. —', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 7, 'Na no uhole''ö mbekagu ba zinga lala, ba na no i''o''ö hörögu tödögu, ba na no togule ba dangagu zi lö sökhi,', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 8, 'ba hana na manaru ndra''o, ba na niha bö''ö zi manga dania, ba hana na tedeha lewiö zinanögu.[3]', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 9, 'Na no owöhö dödögu ba ndra alawe, na no udaro-darogö barö mbatö nawögu,', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 10, 'ba yamöi sanutu fakhe niha bö''ö ngambatögu, ba ndramutalagui ia niha bö''ö.[4]', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 11, 'Horö sebua zi manö, olalöŵa, ni''otu''ö zanguhuku;[5]', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 12, 'alitö sa''ae ia, si manga-manga hadia ia, irugi gohokoho si tou, same''e aetu ŵa''a zi so khögu, fefu.', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 13, 'Na lö ba dödögu lala khö zawuyugu ira matua ba khö zawuyugu ira alawe, na so nifadönima, —', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 14, 'ba he uwisa göi, na maoso ena''ö Lowalangi, na izofu-zofu, ba hadia niŵa''ögu wanema linia?', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 15, 'Hadia, tenga somböi ya''odo zomböi göi ya''ia, ba dalu ninania, tenga ha samösa zamazökhi ya''aga, ba dalu ninama andrö![6]', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 16, 'Na so zi lö u''o''ö somasi zi numana, ba na no ube''e ariri hörö zi no mate ira matua,', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 17, 'na u''a manö gögu, ha ya''o, na lö ukhete ba si lö ama, si lö ina: —', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 18, 'Lö''ö; i''otarai ono matua na ndra''odo, ba no amaedola namania ndra''o, ba wanöinia andrö, ba i''otarai ono sawuyu ndra''o, ba u''ohe-ohe danga zi lö ira matua.', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 19, 'Na u''ila zi numana si lö nukha, ba ma si lö ambala,', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 20, 'na lö nifahowu''ö zolania ya''odo, ba na lö si möi famadöhö wa''oafunia mbu nono mbiri-biri khögu;', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 21, 'na no ubaha dangagu ba zi lö ama, si lö ina, me no udöna-döna nawögu barö mbawa göli,', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 22, 'ba yafaefa mbu''u galisigu ba ya afatö döla da''iogu.', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 23, 'Sata''u ndra''o sa''ae wamakiko andrö, nifatörö Lowalangi khögu, ba si tebai ndra''o, ba wa''asalaŵania andrö.', '["Mat 5:28","Nga''ötII 16:9","MozIII 26:16; MozV 28:38","Yes 47:2; Luk 17:35","MozI 38:24; MozIII 20:10; MozV 22:22","Faigi 34:19; Amaed 14:31"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 24, 'Na no ube''e tötönafögu gana''a ba na no ube''e töi mbalaki "wondrara dödögu";[7]', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 25, 'na no omuso dödögu ba wa''ebua gana''agu, ba me no fahöna gölögu[8] —', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 26, 'Na ufaigi-faigi haga luo, fa''atarania andrö, ba fa''asökhi mbaŵa ba lalania andrö,[9]', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 27, 'ba na no tefowöhö dödögu, si lö oroma, ba na no u''ago dangagu, wangoro''ö ya''ia[10] —', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 28, 'ba olalöŵa göi da''ö mena''ö, ni''otu''ö zanguhuku, me no samini tödö ndra''o khö Lowalangi yaŵa.', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 29, 'Na omuso ena''ö dödögu, na göna famakao zi fa''udu khögu, na owua-wua ena''ö dödögu, na itörö ia si lö sökhi[11] —', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 30, 'ba lö urai utehe ba mbewegu wolau si lö sökhi, wangelifi ya''ia, ena''ö aetu nosonia.[12]', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 31, 'Na lö lamane mena''ö awögu baomogu: ''Ha niha zi lö abuso diwo andrö nibe''enia?!''', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 32, 'Lö tola mörö ba danö niha bö''ö; no ufa''amö amöi yomo zikoli.', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 33, 'Na no ubini''ö horögu, si mane Tuada Adamo no, wamalugö barö dötö''agu lalögu,[13]', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 34, 'börö wa''ata''ugu zato, awö wa u''ata''ufi tetibo ndra''o ba dödö soi niha; tobali uhonogö ndra''o, lö möido tou.', '["Mar 10:24; TimI 6:17","Sin 62:11","MozV 4:19","RazI 19:18","Amaed 4:17","Mat 5:44; Rom 12:14","Heb 13:2; FetI 4:9"]', NULL),
  (3475508, 'OT', 'Yobi', 31, 35, 'Ena''ö na so zamösa samondrongo khögu! Ya''e dandro tangagu — yamutema ligu Si lö ambö fa''abölö! Ba ena''ö na so ba dangagu zura andrö, nisura nudugu andrö!', '[]', NULL),
  (3475508, 'OT', 'Yobi', 31, 36, 'Si ndruhu, u''angalisigö ena''ö; ube''e saembu ba högögu.', '[]', NULL),
  (3475508, 'OT', 'Yobi', 31, 37, 'U''ofaya khönia mbekagu; salaŵa ndra''o wangondrasi ya''ia.', '[]', NULL),
  (3475508, 'OT', 'Yobi', 31, 38, 'Na mangarö-ngarö nowigu, börö ndra''o, ba na me''e gowotonia fefu;', '[]', NULL),
  (3475508, 'OT', 'Yobi', 31, 39, 'na no u''a mbuania lö usulöni, ba na no u''etu''ö noso zokho,', '[]', NULL),
  (3475508, 'OT', 'Yobi', 31, 40, 'ba yatumbu za''a-sa''a mao, salahi wakhe, ba du''u salahi rigi!" Ba da''e aetu huhuo Yobi andrö.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 1, 'Ba me lö''ö sa''ae ladema-dema li Yobi si datölu andrö, me ibu''abu''a manö ba hulunia,', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 2, 'ba mofönu Gelihu andrö, ono Mbarakheli, banua Mbusi, ma''uwu Rami. Khö Yobi mofönu ia, me no si fabu''abu''a khö Lowalangi.', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 3, 'Ba ba zi datölu, si fahuwu khönia, mofönu ia, me lö lasöndra wanedema li, ba wamaduhu''ö sala Yobi.', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 4, 'Ba no ibazebase''ö Elihu, ba wolau huhuonia khö Yobi, me no si a''a ira moroi khönia.', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 5, 'Ba me i''ila Elihu, lö fanedema li sa''ae ba zi datölu, ba tesao wönunia.', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 6, 'Ba humede Gelihu andrö, ono Mbarakheli, banua Mbusi, imane: "Iraono na ndra''o, ba satua ami, ba no alaŵö-laŵödo, si ba''a-ba''aö ndra''o, ba wangombakha khömi wangilagu.', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 7, 'No umane dödögu: Akha fahuhuo zatua, yamufahaö ita ba wa''atua-tua si no ara ba guli danö!', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 8, 'Ba eheha andrö, si so barö doto niha ba hanu-hanu Zi lö ambö fa''abölö, da''ö zama''ema khöra fa''aboto ba dödö.[1]', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 9, 'Tenga sa si no ara ba guli danö wondrege zatua-tua, ba tenga si no satua zangila hadia zatulö.', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 10, 'Andrö uŵa''ö: Fondrongondrongo khögu; da''utunö göi zaboto ba dödögu.', '["Amaed 2:6; Faigi 38:36; Sangomb 2:26; Yak 1:5"]', NULL),
  (3475496, 'OT', 'Yobi', 32, 11, 'Hiza, no ubazebaze''ö huhuomi, no ufondrongondrongo wamahaömi, irege misöndra ena''ö zi ndruhu famu''a.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 12, 'Noa sa utöngötöngöni khömi, ba hiza, ba samösa lö ba khömi sangila mamu''a niŵa''ö Yobi, lö sangila manedema huhuonia.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 13, 'Böi miwa''ö: ''No falukhaga wa''atua-tua; ha Lowalangi zangila molaŵa ya''ia, tenga niha!''', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 14, 'Khögu, ba lö si fabu''a ia; ba lö ugo''ögo''ö niŵa''ömi, wanema linia.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 15, 'No tobali dödöra, lö fanema li sa''ae; lö lili sa''ae, no aetu.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 16, 'Ba hadia, ubazebaze''ö, me lö hede-hedera, me so manö ba da''ö, ba lö''ö sa''ae fanema li?', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 17, 'Da''udema-dema göi, ndrohundruhu khögu, utunö göi hadia ni''ilagu.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 18, 'Noa sa afönu ndra''o huhuo, i''o''udo tödögu, barö dotogu.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 19, 'Hiza, hulö duo so''otu''otu, si lö lala, bakha dödögu; mamoka dania, si mane nahia si bohou mufo''ösi.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 20, 'Edönado fahuhuo, ena''ö molala dödögu; humede ndra''o, ba wamu''a.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 21, 'Lö u''ebua''ö dödögu zambuana; lö u''alösöigö lelagu ba niha, ha niha ia.', '[]', NULL),
  (3475496, 'OT', 'Yobi', 32, 22, 'Lö''ö sa to''ölödo ba wa''alösö lela; lö ara ena''ö, ba i''etu''ö nosogu somböi ya''o."', '[]', NULL),
  (3475497, 'OT', 'Yobi', 33, 1, '"Ba fondrongondrongo sa''ae huhuogu, ya''ugö Yobi, ba be''e mbörö dalingau ba daroma ligu andre fefu.', '["MozI 2:7; Faigi 10:9","Faigi 13:21"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 2, 'Hiza sa, ubokai mbawagu, ba muhede lelagu, barö gararogu.', '["MozI 2:7; Faigi 10:9","Faigi 13:21"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475497, 'OT', 'Yobi', 33, 3, 'Moroi ba dödö sadölö ligu andre; hadia ni''ila mbewegu, ba ifalua, sadölö.', '["MozI 2:7; Faigi 10:9","Faigi 13:21"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 4, 'Eheha Lowalangi zomböi ya''odo, ba hanu-hanu Zi lö ambö fa''abölö wamonoso ya''o.', '["MozI 2:7; Faigi 10:9","Faigi 13:21"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 5, 'Na ö''ila öbu''a niŵa''ögu, ba bu''a; fa''anö ndra''ugö udugu, faoso!', '["MozI 2:7; Faigi 10:9","Faigi 13:21"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 6, 'Hiza, no faoma ita khö Lowalangi, no fagölö-gölö mbörötada la''uri.[1]', '["MozI 2:7; Faigi 10:9","Faigi 13:21"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 7, 'Alakha lö tokea''ö, wangata''ufi ya''odo, ba lö''ö sa ilangö ndra''ugö fa''ebuagu.[2]', '["MozI 2:7; Faigi 10:9","Faigi 13:21"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 8, 'Ba no urongo niŵa''öu — taroma liu andrö no urongo [me ömane]:', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 9, '''Sohau-hau ndra''o, lö horögu; lö sinegu khögu ba lö lalö.[3]', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 10, 'Hiza, fatiusa ifakhai khögu, ibe''e udunia ndra''odo.[4]', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 11, 'Ibe''e ba galo gahegu; idaro-darogö nitörögu fefu.''[5]', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 12, 'Hiza, da''ö zi lö atulö khöu, uŵa''ö khöu; noa sa ebua Lowalangi moroi ba niha.', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 13, 'Hana wa fasoso ndra''ugö khönia, wa no sambua lö itema liu?', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 14, 'Humede sa Lowalangi, samuza, mendrua — ba lö tatöngöni.[6]', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 15, 'Ba wangifi, ba gangilata ba zi bongi, na ihawui niha femörö sabölö-bölö, ba wemörö andrö ba gasora,[7]', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 16, 'ba da''ö ibokai dögi dalinga niha ba ifotandro wanegu ya''ira.[8]', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 17, 'Ba wanenaŵa niha, ba wolaunia andrö, ba ba wanimba ba ndra matua fayaŵasa.', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 18, 'Irorogö nosonia, fa lö aekhu ba dögi, fa lö aetu noso ba nono wana.', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 19, 'Ba te''otu''ö göi ia fa''afökhö, ba gasonia tou; lö mamalö-malö wasöndrata andrö ba dölania.', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 20, 'Ba ogoro ia gönia ibe''e nosonia andrö, anuzu dödönia zami khönia mege.[9]', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 21, 'Ariri nösinia, irege lö sökhi-sökhi sa''ae, timba zi lö oroma sa''ae nösinia andrö, si no oköliköli.', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 22, 'Tobali sahatö ba lewatö nosonia, no sahatö ba mbekhu samunu niha.', '["Faigi 16:17","Faigi 13:24","Faigi 13:27","Faigi 35:13","MozI 20:3; 31:24; Dan 4:2; Mat 2:19","Faigi 36:10","Sin 107:18"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 23, 'Ba na so dania salahinia mala''ika si lului manguma''ö, awö ngahönö andrö, ba wanguma''ö lala ba niha,[10]', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 24, 'na ahakhö dödönia ia ba na imane: ''Orifi ia, ba böi fonumalö ia ba gohokoho; no utema höli'',[11]', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 25, 'awena dania ifuli abe''e nösinia, timba nono matua, mangawuli ia ba götö wa''onomatua.', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 26, 'I''angaröfi li Lowalangi, ba ihakhösi tödö ia; ifa''ele''ö khönia mbawania, suwua-wua dödö niha, ba isulöni ba niha wolau-launia satulö andrö.[12]', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 27, 'Manunö ia, ba zi so niha bö''ö, imane: ''Noa sa ufazökhi horö, ba no ubila''ö lala, ba lö''ö sa musulöni khögu.', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 28, 'No i''orifi nosogu, lö ibe''e numalö ba gohokoho, ba omuso dödögu ba zohaga.''', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 29, 'Hiza, da''ö fefu ilau Lowalangi ba niha, irege mendrua, irege medölu,', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 30, 'ba wangefa''ö ba gohokoho nosonia, ena''ö humaga khönia haga ba wa''auri andrö.[13]', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 31, 'Töngöni, ya''ugö Yobi, fondrongondrongo khögu; böi hede-hede, hana na ya''odo zi fahuhuo!', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 32, 'Na so khöu daroma li, ba bu''a niŵa''ögu; hede manö, amasido wamu''au.', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475497, 'OT', 'Yobi', 33, 33, 'Ba na lö''ö, ba öfondrongondrongo khögu; böi hede-hede, ena''ö ufahaö ndra''ugö ba wa''atua-tua."', '["Faigi 23:8; MozII 23:20","TimI 2:6; Heb 9:12","Sin 50:15; Yes 58:9","Sin 56:14"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 1, 'Ba itohugö Elihu, imane:', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 2, '"Mifondrongondrongo niŵa''ögu, ya''ami satua-tua, ba mibe''e mbörö dalingami, ya''ami si so tödö!', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 3, 'Itandra sa daroma li tögi dalinga, si mane fanandra gararo gö.[1]', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 4, 'Data''alu-alui zatulö, ena''ö faoma tasöndra zi sökhi.', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 5, 'Noa sa imane Yobi: ''Lö horögu, ba tenga ba lala ifatörö khögu Lowalangi.', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 6, 'Hadia, mofaya ndra''o, lö lai wa no lala khögu? No gönado ono wana si tebai nifadöhö, ba lö horögu.''[2]', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 7, 'Heza so niha si mane Yobi andrö, samamadu idanö fanandraŵa,[3]', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 8, 'si möi awö zolau si lö sökhi ba si fao ba zanao horö?[4]', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 9, 'Noa sa imane: ''Lö hare niha, na fahuwu ia khö Lowalangi''.[5]', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 10, 'Andrö mifondrongondrongo khögu, ya''ami si so fa''aboto ba dödö: Böi manö taŵa''ö, ilau zi lö sökhi Lowalangi ba ifatörö zi lö atulö Si lö ambö fa''abölö![6]', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 11, 'Lö''ö, ha folau niha isulöni khönia, dali wamatörönia ba niha mbua-bua niha.[7]', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 12, 'Si ndruhu, lö ibila''ö lala Lowalangi, ba lö iwu''ai huku Si lö ambö fa''abölö.', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 13, 'Ha niha zame''e ba dangania tanö? Ba ha niha zolata tanö''a ma''afefu?', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 14, 'Na ha ya''ia zi so ba dödönia ena''ö, na iböda Gehehania ba hanu-hanunia andrö,[8]', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 15, 'ba ahori adudu nösi guli danö fefu, ba ifuli tobali gawu-gawu niha.', '["Faigi 12:11","Faigi 13:18; 27:2","Faigi 15:16","Sin 1:1","Faigi 22:2 b.t.","MozV 32:4; Nga''ötII 19:7; Rom 9:14","Sin 62:13; Yer 32:19; Mat 16:27; KorII 5:10; Kol 3:25; FetI 1:17","Sin 104:29; Sangomb 12:7"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 16, 'Na si so tödö ndra''ugö, ba fondrondrongo da''e, be''e mbörö dalingau ba daroma ligu!', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 17, 'Hadia, tola maö samatörö zi lö omasi satulö? Ma öbali''ö si lö atulö Zi lö ambö fa''atulö andrö?[9]', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 18, 'Ya''ia andrö, sanguma''ö khö razo: ''Si lö ngaroro ndra''ugö!'' ba ba zi so töi: ''Sebua horö ami!''', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 19, 'Si lö mamaigi bawa zalaŵa ba si lö ebua tödö ba zo''ana''a, moroi ba zi numana, me no nilau dangania dozi ira.[10]', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 20, 'I''ogomuzaö mate ira, ba na talu mbongi, ba tefahisi soi niha, ba taya; tetimba zabölö, ba tenga tanga niha.', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 21, 'Anehe sa ia lala zamösana, fefu mbekania, ba i''ila.[11]', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 22, 'Lö si bongi ba lö sogömi-gömi sibai, ba nibini''ö zamazökhi si lö sökhi ya''ira ena''ö.[12]', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 23, 'Alakha sa lö ifaigi-faigi niha, ena''ö i''ondrasi Lowalangi, nihuku.', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 24, 'Ifufu zabölö, lö musekhegö, ba ibe''e fangalira niha bö''ö.', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 25, 'Tobali aboto ba dödönia mbua-buara ba ba zi bongi itimba ira, ba afufu.', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 26, 'Ihare''ö khöra mbözi-bözi, si mane ba zi no manao horö, ba ba zanehe niha fefu.', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 27, 'Börö wa no fabali ira khönia awö wa lö ba dödöra lala andrö khönia fefu,', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 28, 'ba wamarongogö khönia si yaŵa fangarö-ngarö zi numana, ba ena''ö irongo wege-ege zebua famakao.', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 29, 'Ba na ifaigi wondrara, ba ha niha zanguhuku [ya''ia]? Ba na ibini''ö mbawania, ba ha niha zangila ya''ia? He ba zato ba he ba zi ha samö-samösa göi.[13]', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 30, 'Ena''ö lö möi salaŵa niha si lö sökhi, fa böi tandraŵa ba niha.', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 31, 'Hadia sa, taŵa''ö maö khö Lowalangi: ''Ulu''i; lö ulau zi lö sökhi;[14]', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 32, 'hadia zi lö i''ila hörögu, ba oroma''ö khögu: na no ulau zi lö atulö, ba ubato sa''ae?''', '["MozI 18:25; Faigi 8:3","MozV 10:17; Faigi 34:27","Nga''ötII 16:9","Sin 139:12","Yes 50:9; Rom 8:34","Ngenu 3:27"]', NULL),
  (3475498, 'OT', 'Yobi', 34, 33, 'Hadia, ifatörö ba zomasi ndra''ugö wanulöni; me no ökököni; tobali ya''ugö zanguhuku, ba tenga ya''odo? Ba hadia ni''ilau, ba falua baeha!', '[]', NULL),
  (3475498, 'OT', 'Yobi', 34, 34, 'Niha si so fa''aboto ba dödö ba niha satua-tua, samondrongo khögu, ba lamane khögu:', '[]', NULL),
  (3475498, 'OT', 'Yobi', 34, 35, '''Ba huhuo Yobi andrö, ba lö fa''aboto ba dödö, ba si lö mutimba tödö niŵa''önia andrö.''', '[]', NULL),
  (3475498, 'OT', 'Yobi', 34, 36, 'Ena''ö na tetandraigö Yobi, irugi ba wondrege, ba wamadaönia andrö, famadaö zi so horö!', '[]', NULL),
  (3475498, 'OT', 'Yobi', 34, 37, 'Inönö sa''ae horönia olalöŵa; mango''aya ia, ba khöda andre, ba mangöhöna famadaö khö Lowalangi.', '[]', NULL),
  (3475499, 'OT', 'Yobi', 35, 1, 'Ba itohugö huhuonia Elihu, imane:', '["Faigi 34:9","Faigi 22:2; Rom 11:35"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 2, '"Hadia, da''ö zatulö öŵa''ö, wanguma''ö: satulö ndra''o föna Lowalangi,', '["Faigi 34:9","Faigi 22:2; Rom 11:35"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 3, 'wa ösofu, hadia gunania khöu: ''Hadia haregu moroi na ufazökhi horö''?[1]', '["Faigi 34:9","Faigi 22:2; Rom 11:35"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 4, 'Da''ubu''a khöu ba khö zi fahuwu khöu andrö, awöu.', '["Faigi 34:9","Faigi 22:2; Rom 11:35"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 5, 'Faöga höröu miyaŵa, ba mbanua, nehegö lawuo andrö, si no alaŵa yaŵau.', '["Faigi 34:9","Faigi 22:2; Rom 11:35"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 6, 'Na öfazökhi horö, ba heza irugi ia? ba na oya lalöu, ba hezo zi te''ala ia?', '["Faigi 34:9","Faigi 22:2; Rom 11:35"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 7, 'Na satulö ndra''ugö, ba hadia game''elau khönia, ba hadia nitemania ba dangau?[2]', '["Faigi 34:9","Faigi 22:2; Rom 11:35"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 8, 'Ba niha si mane ya''ugö manandrösa walösökhiu; ba khöu, ya''ugö ono niha, manandrösa wa''atulömö.', '["Faigi 34:9","Faigi 22:2; Rom 11:35"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 9, 'Mangarö-ngarö sa niha ba wa''afahöna wamalangögö, ba mangandrö tolo ba wamakao zalaŵa,', '["Sin 19:3; 42:9","Faigi 27:9; Yer 11:11"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 10, 'ba lö sanguma''ö: ''Hezo Lowalangi, somböi ya''odo, sangoro''ö fanunö, ba zi bongi,[3]', '["Sin 19:3; 42:9","Faigi 27:9; Yer 11:11"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 11, 'same''e famahaö ya''ita utu ndru''u andrö, ba fangatua-tuada fofo ba dalu mbanua?''', '["Sin 19:3; 42:9","Faigi 27:9; Yer 11:11"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 12, 'Ba la''angaröfi li ia, ba lö ifondrondrongo khöra, börö wayaŵasa zebua horö andrö.[4]', '["Sin 19:3; 42:9","Faigi 27:9; Yer 11:11"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 13, 'Lö''ö, faya-faya, ba lö irongo Lowalangi, lö itöngöni Si lö ambö fa''abölö;', '["Sin 19:3; 42:9","Faigi 27:9; Yer 11:11"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 14, 'böhöi wa öŵa''ö, lö oroma ia khöu; no so ba duduma hörönia huhuo andrö ba ödöna-döna khönia.', '["Sin 19:3; 42:9","Faigi 27:9; Yer 11:11"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 15, 'Ba iada''e, me lö''ö na si tesao wönunia, fotu, ba hadia, lö''ö manö ni''ilania maö fayaŵasa andrö?', '["Sin 19:3; 42:9","Faigi 27:9; Yer 11:11"]', NULL),
  (3475499, 'OT', 'Yobi', 35, 16, 'Ba tobali faya-faya nilau Yobi, fahöna huhuo, ba lö fa''aboto ba dödö."', '["Sin 19:3; 42:9","Faigi 27:9; Yer 11:11"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 1, 'Ba itohugö Elihu, imane:', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 2, '"Base''ö ma''ifu khögu, ba ufahaö ndra''ugö; so na sa niŵa''ö ba khö Lowalangi andrö.', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 3, 'Ba zaröu uhalö wa''aboto ba dödögu, ba u''ohe ba lala hadia ia khö zomböi ya''odo.', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 4, 'Si ndruhu sa, tenga faya niŵa''ögu; si no a''oi so fa''aboto ba dödö zi fahuhuo khöu.', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 5, 'Hiza, no sabölö Lowalangi, ba lö''ö zui i''ositengagö niha, no fahöna wa''abölö wa''aboto ba dödö.[1]', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 6, 'Lö i''orifi zebua horö; ba huhuo zebua famakao, ba ibe''e ba lala.', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 7, 'Lö iböhöli wamaigi satulö tödö ba awö razo ba dadaoma ifedadao ira, si lö mamalö-malö, ena''ö salaŵa ira.[2]', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 8, 'Ba na no murate ira, na no tofesu ira fesu famakao,', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 9, 'na ifarongogö khöra wolaura, awö horöra andrö, wa no fayaŵa ira,', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 10, 'na tobali ibokai dögi dalingara, ba wanenaŵa andrö, ena''ö laböhöli zi lö sökhi:[3]', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 11, 'Ba na lafondrondrongo, na la''o''ö, ba sohahau tödö ira, ba we''asora na ba guli danö, somuso tödö ba zi tosai götöra.', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 12, 'Ba na lö lafondrondrongo, ba si mate ba nono wana dania ira; aetu nosora lö fa''aboto ba dödö.', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 13, 'Ba niha si tefuyu tödö, ba so mbao dödö, lö fakao, na ifesu ira;', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 14, 'ba wa''a''onomatua aetu nosora, mate ira, si mane sohorö-horö.', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 15, 'Sebua famakao, ba i''orifi, ibe''e fangorifinia wamakaonia andrö; ba ibe''e famokai dögi dalingara wa''atosasara andrö.', '["Faigi 9:4; 12:13","SamI 2:8; Sin 33:18; 34:16; 113:8","Faigi 33:16"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 16, 'Ba ya''ugö göi, ba idönisi, wangefa''ö ya''ugö ba mbawa wamakao andrö, i''ohe ba zebolo tanö, ba zi lö fa''atosasa, ba satabö nifa''oli tou diwou.[4]', '["Sin 18:20; 23:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475500, 'OT', 'Yobi', 36, 17, 'Ba no fahöna khöu wangetu''ö huku, si mane ba zebua horö; ba fangetu''ö huku ba famatörö huku, ba no fago''ö.', '["Sin 18:20; 23:5"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 18, 'Böi ya ifowöhö ndra''ugö ba wango''aya bao dödöu andrö; ba böi elungu''ö ba wa''ebua höli andrö.', '["Sin 18:20; 23:5"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 19, 'Hadia, i''efa''ö ndra''ugö ba wa''atosasa andrö fe''ao-aomö andrö, na no a''oi dölau?', '["Sin 18:20; 23:5"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 20, 'Böi ya humulu dödöu, ena''ö na bongi, fa humufa soi niha ba nahara.', '["Sin 18:20; 23:5"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 21, 'Angelama, böi otahögö zi lö sökhi; da''ö sa zomasi''ö, moroi ba wanaha famakao.', '["Sin 18:20; 23:5"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 22, 'Hiza, nifolau zalaŵa wolau Lowalangi, ba wa''abölönia andrö; heza so zamatörö, si mane ya''ia?', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 23, 'Ha niha zamakhoi khönia lala, ba ha niha zanguma''ö: ''No ölau zi lö atulö?[5]', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 24, 'Alui tödöu, ena''ö ö''ebua''ö döi wolaunia andrö, nisunosuno niha.', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 25, 'Dozi niha, ba sowua-wua tödö ba da''ö, moroi ba zaröu la''ila niha danö.', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 26, 'Hiza, no salaŵa Lowalangi ba tebai aboto ba dödöda ia; lö mutaha mu''erai ndröfinia.[6]', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 27, 'I''ofaya sa''ae mböi nidanö; mowöi taŵa deu, na mosau khönia.', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 28, 'Satoru moroi yaŵa ba lawuo, saekhu ba niha, si no ato.', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 29, 'Ba mendrua manö, na aboto ena''ö ba dödöda wa''ebolo lawuo andrö [ba] fa''ofetu ba nosenia andrö.[7]', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 30, 'Hiza, ifasui ia hagania andrö; ba ibalugö ŵa''a nasi.', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 31, 'Da''ö sa''ae ibe''e fanguhuku soi niha, ba ihöna mbalazo.', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 32, 'Dua dangania ibalugö haga, ba ibe''e fanimba zi fa''udu.', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475500, 'OT', 'Yobi', 36, 33, 'Ifarongogö ia ugu-ugunia andrö, ba saŵi na''i zangila, na so ia moroi sa."', '["Faigi 34:10","Sin 90:2; 93:2; 102:27; Dan 6:26","Sin 18:12"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 1, '"Si ndruhu, ba da''ö tobali dödögu ba tokea ba nahania andrö.', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 2, 'Mifondrondrongo! Mifondrondrongo wendröndröndröndrö linia andrö, ugu-ugu andrö, si otarai mbawania![1]', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 3, 'Barö mbanua ma''afefu i''efa''ö, awö haga andrö khönia, irugi wondrege danö.', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 4, 'Moroi furinia mundröndröndröndrö; mu''ugu-ugu linia andrö, li zalaŵa, lö itaha gari mbanua andrö, na terongo linia.[2]', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 5, 'Ife''ugu-ugu linia Lowalangi, sahöli-höli dödöda, wolau sebua andrö, si tebai aboto ba dödöda.', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 6, 'Imane sa''ae ba deu si baku andrö: Torugö''ö ba danö! ba si manö ba deu laöhö andrö, ba deu sabölö-bölö sibai.[3]', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 7, 'Ifotandro danga niha fefu, ena''ö aboto ba dödö niha fefu wolaunia andrö.', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 8, 'Ba labini''ö ira utu ndru''u, ahono ba nahara.', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 9, 'Ba mbate''enia i''otarai angi sabölö, ba moroi ba nangi moroi yöu wa''oafu.[4]', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 10, 'Ba hanu-hanu Lowalangi abe''e nidanö ba tobali tofera wa''ebolo nidanö.', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 11, 'Ifonoro teu lawuo, ibologö misa lawuo andrö khönia, sihaga.', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 12, 'Ba itörö misa, fasui, nifatörönia ba wamalua fefu niŵa''önia khönia;', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 13, 'so, ba fotu, na moguna ba guli danönia andrö, ba so, ba howu-howu zalua khönia, ibe''e.', '["Sin 29:3","Faigi 5:9; 36:26","Sin 147:16","Faigi 9:9"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 14, 'Da''ö be''e ba dödöu, ya''ugö Yobi: Badugö''ö, ba töngöni zahöli-höli dödö andrö khö Lowalangi!', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 15, 'Hadia, aboto ba dödöu, na ibe''e goroisa Lowalangi, ba na ifohaga lawuo andrö khönia?', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 16, 'Hadia, aboto ba dödöu wanahanahae lawuo andrö, sahöli-höli dödö andrö, khö zi no ahori so fa''aboto ba dödö?', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 17, 'Ya''ugö andrö, saukhu nukha, na aukhu''aukhu danö, na angi moroi raya.', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 18, 'Hadia, no awönia ndra''ugö wamologö banua si yaŵa, si no abe''e, hulö zörömi nifahele?', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 19, 'Ombakha''ö khöma, hadia niŵa''öma khönia! — Lö ma''ila maŵa''ö hadia ia, ba wa''ogömi-gömi [dödöma].', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 20, 'Hadia, tefarongogö khönia, wa muhede ndra''o? ma hadia, no irai i''andrö niha, tefufu ia?', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 21, 'Iada''e sa, ba lö oroma khöda haga luo, sihaga sibai ba gero lawuo, ba itörö angi, ifahoi.', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 22, 'Moroi yöu i''otarai balaki, ba no tefasui Lowalangi lakhömi sihokha mbuda.', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 23, 'Si lö ambö fa''abölö andrö, ba lö takhamö, ya''ia andrö, si no fahöna fa''abölö; ba sadölö lala ba si no a''oi so fa''atulö, ba lö ibila''ö.', '["Faigi 34:19"]', NULL),
  (3475501, 'OT', 'Yobi', 37, 24, 'Andrö la''ata''ufi ia niha, ba si no atua-tuafö, ba lö ba dödönia."[5]', '["Faigi 34:19"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 1, 'Ba humede Yehowa khö Yobi ba we''ugu-ugu mbanua, imane:[1]', '["RazI 19:11; Hez 1:4","Faigi 42:3"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 2, '"Ha niha ba da''ö, zamalugö tödö [gu] andrö fehede si lö fa''aboto ba dödö?[2]', '["RazI 19:11; Hez 1:4","Faigi 42:3"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 3, 'Faoso, amöbö talu, si mane ira matua, ba uzofu-zofu khöu, ba öfahaö ndra''odo!', '["RazI 19:11; Hez 1:4","Faigi 42:3"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 4, 'Heza so ndra''ugö, me ulata danö? Ombakha''ö, na so wa''aboto ba dödöu.[3]', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 5, 'Ha niha zi honogöi su''ania — na ö''ila ha niha zamatörö khönia fanu''a!', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 6, 'Hadia dayadaya gehomonia, ba ha niha zame''e tou toyo ba watalinga.', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 7, 'Me ma''iki-iki madala andrö fefu, ba me owua-wua dödö nono Lowalangi, dozi.[4]', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 8, 'Ha zame''e ba''a-ba''a nasi, lagö mbawandruhö, me alua ia, me böla ia, timba ba dalu nina,[5]', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 9, 'me ube''e nukhania lawuo, ba me ube''e lölönia zogömi-gömi sibai?', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 10, 'Me ufakhoi wondregenia ba me ube''e lagö mbawandruhönia, fabaya lazi.', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 11, 'ba me umane: "Ba da''e örugi ba lö ösawö, ba ba da''e aboto ndrulumö andrö, si no fayaŵa!"[6]', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 12, 'Hadia, no örai öbe''e goroisa ba zi moluo andrö, no örai öŵa''ö naha wa''oyo mbanua na mahemolu mbanua,', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 13, 'ena''ö itugelai wondrege danö, ba ena''ö tetimba tou zolau si lö sökhi?', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 14, 'Tobali si mane galögalö andrö ba dandro, ba hulö nukha fefu, hadia ia.', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 15, 'Ba aböda haga ba zolau si lö sökhi, ba terasa da''io, si no mu''oro''ö.', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 16, 'Hadia, no örugi dawuyu andrö ba nasi, ba hadia, no mowaö-waö''ö ba doyo namö?', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 17, 'Hadia, no teboka khöu mbawandruhö ba wa''amate, ba hadia, no anehe''ö mbawa göli mbanua tou, si no ogömi-gömi sibai?', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 18, 'Hadia, no irugi höröu wamaigi fa''ebolo danö? Ombakha''ö, na no ahori ö''ila da''ö?', '["Amaed 30:4","Sin 19:2","Amaed 8:29","Yer 5:22"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 19, 'Heza ato so lala ba zonahia haga, ba fa''ogömi-gömi andrö — ba heza ato so nahiania?', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 20, 'Fa ö''ohe ba kandrania, fa ö''ila lala ba nomonia?', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 21, 'Ö''ila, me luo da''ö sa tumbu ndra''ugö; no ara ndra''ugö ba guli danö.', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 22, 'Hadia, no örugi zi fahöna teu si baku andrö, ba no ö''ila halasa deu kara,', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 23, 'nihönagu, ba mbaŵa wamakao dania, ba mbaŵa wasöndrata, ba mbaŵa wanuwö?[7]', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 24, 'Heza so lala ba zi fabali haga, ba zi otarai angi timu andrö, wanörö uli danö misa.', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 25, 'Ha zamatörö lala deu, awö lala gari mbanua andrö,', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 26, 'ba wame''e aekhu deu ba danö si lö niha, ba danö si mate, si lö banua niha,', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 27, 'ba wangabusoi''ö si lö sinanö ba tanö si mate, ena''ö ifuli tumbu ndru''u?[8]', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 28, 'Hadia, so nama deu andrö, ba ha niha nama mböiböi namo andrö?', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 29, 'Ha niha zi adonogö idanö sabe''e andrö, ba ha ono namo si baku moroi yaŵa ba mbanua.', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 30, 'Abe''e nidanö, timba gara, ba fadoro wa''abe''e dete nasi.', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 31, 'Hadia, ö''ila öfaböbö "zara" andrö, ba ö''ila ötoto''ö wesu "zi tölu".', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 32, 'Hadia ö''ila ö''ohe baero ndröfi sebua andrö, na inötö, ba samatörö "berua" andrö, awö nononia, ndra''ugö?', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 33, 'Hadia, ö''ila nifakhoi andrö si yaŵa ba mbanua; hadia, no ya''ugö zamakhoi famatörönia uli danö?', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 34, 'Hadia, mu''ao ndra''ugö ba lawuo, ena''ö ihawui ndra''ogö teu sabölö-bölö?', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 35, 'Ya''ugö zolau gari mbanua, ena''ö itörö ba ena''ö imane khöu: Ya''e ndra''o?', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 36, 'Ha zame''e ba mbua [niha] fa''atua-tua ba ha niha zamotödö zilatao?[9]', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 37, 'Ha zangofaya lawuo ba wa''atua-tuania, ba asoa andrö ba mbanua si yaŵa, ba ha zamatutue?', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 38, 'Fa farafö tou gawu-gawu, fa fakhitö danö sabe''e.', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 39, 'Hadia, ahulu ndra''ugö ö zi alawe zingo, ba döhö wangisö nono zingo öbe''e,[10]', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 40, 'na laköŵö ira ba nahara, na manaronaro ira ba ndru''u?[11]', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475502, 'OT', 'Yobi', 38, 41, 'Ha zangasiwai gö gaga, na la''angaröfi li Lowalangi ononia, na manörö-nörö ira lö ö?"[12]', '["Yos 10:11; Yes 30:30","Sin 107:35","Faigi 32:8","Sin 104:21","Sin 10:9","Sin 147:9"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 1, '"Hadia, ö''ila ginötö wo''ono nago, ba hadia, ötöngöni wa''afökhö hulu ba mböhö?[1]', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 2, 'Hadia, ö''ofaya mbaŵara, ba ö''ila mbaŵa wo''onora?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 3, 'Laköröbui ira, ba böla nonora, ba döhö wa''afökhö hulura.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 4, 'Ba abe''e nonora, manöi ba ndru''u, moloi, ba lö''ö sa''ae mangawuli.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 5, 'Ha zamoloi galide ndru''u ba ha zi dudu si so ba ndru''u andrö,[2]', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 6, 'nibe''egu tanö si mate, ba we''aso ba da''ö, ba dekha mo''asio, nahiania?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 7, 'Ma''iki ia ba gua-gua andrö yomo ba mbanua, ba fe''ao zamatörö, ba lö irongo.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 8, 'Hadia ni''ilania ba hili, ba önia, ba i''alu-alui ngawalö ndru''u sauri, fefu.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 9, 'Hadia, edöna möi ngoni-ngoniu göröbao ndru''u; hadia möi ia mörö ba kandra khöu?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 10, 'Hadia, ö''ila öbe''e ba wesu göröbao ndru''u andrö, ba wanguhundra laza; hadia, igo''ögo''ö maö ndra''ugö, ba wonowi ba ndraso?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 11, 'Hadia, ödöna-döna khönia, me no sabölö, ba öbe''e balazi ia halöŵömö andrö?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 12, 'Hadia, ödöna-döna khönia i''ohe baose mbasitömö, i''ohe ba golayama mbasitö khöu?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 13, 'Mangafongafo wofo ondra, omuso dödö; ba hadia, no afi dumbao ba bu dumbao [fofo si no ahono-hono]?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 14, 'Tenga ya''ia; itou''ö manö tou ba danö gadulonia ba ifaukhu ba zogawu-gawu tou,', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 15, 'ba lö itörö tödönia, ma ihundragö sanörö ba ma amama ba gahe gutu ndru''u.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 16, 'Safaito ia ba khö nononia, hulö zi tenga khönia; lö i''abusi tödö na zaya-zaya gölö wa''erege dödönia.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 17, 'Noa sa lö nibe''e Lowalangi fa''atua-tua khönia; lö nifo''urakhania ya''ia tödö.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 18, 'Ba na ifanoka ia, ba i''igi''igi''ö kudo, fabaya si fakudo ba hulu.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3475503, 'OT', 'Yobi', 39, 19, 'Hadia, ya''ugö zame''e fa''abölö ba kudo? Hadia, ya''ugö zamonukha baginia bu zöri sangafongafo andrö?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 20, 'Hadia, ya''ugö zamanoka, fa amaedola kao mböhö? Sata''u ita wehöfuhöfunia andrö, si no ebua li![3]', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 21, 'Ikha''akha''ai danö ba ndraso; omuso dödönia, ba wa''abölönia andrö; ifaondragö zi no mangaro.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 22, 'I''igi''igi''ö wa''ata''u, ba lö tokea, ba lö ibali''ö ia furi, na i''ila zi''öli.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 23, 'Rumiti ba hulunia naha nono wana, ba takile doho ba kalakala.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 24, 'Ikha''akha''ai tou danö, ba walö''ahono ba ba wofönu, ba lö ahono ia, na telau dorofe.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 25, 'Ero na moli dorofe ba imane: ''Labu!'' ba moroi ba zaröu i''ago wasöndrata; irongo we''ao zolohe, si ugu-ugu, ba fangahahagö andrö.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 26, 'Hadia, ba wa''aboto ba dödöu andrö ifaliŵa gafinia fahaneŵa andrö, ba ibologö miraya?', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 27, 'Hadia, ba niŵa''öu isaŵa miyaŵa moyo, ba mangazuni ba zalaŵa yaŵa?[4]', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 28, 'Ba dete gara ba hili i''iagö, ba da''ö monahia ia ba duturu gara, naha zanaro.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 29, 'Moroi ba da''ö idaro-darogö gönia; ikhamö zaröu hörönia.', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475503, 'OT', 'Yobi', 39, 30, 'Ba labadu ndro ononia, ba ba zi so nibunu tou, ba da''ö so ia.[5]', '["Sin 29:9","Faigi 24:5; Yer 2:24","Yoel 2:4","Yer 49:16; Obad 4","Mat 24:28"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 1, 'Ba humede na Yehowa khö Yobi, imane:', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 2, '"Hadia, ifasosoni Zi lö ambö fa''abölö si fadegu-degu andrö? Yamutema li sangadugö Lowalangi andrö!"', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 3, 'Ba itema li Yehowa Yobi, imane:', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 4, '"Hiza, no abölö ide-ide ndra''odo; hadia niŵa''ögu wanema liu? U''okhö mbawagu.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 5, 'No samuza muhede ndra''o, ba lö ufuli uŵa''ö zamuza tö; lö hede-hedegu sa''ae!"', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 6, 'Ba itema li Yobi Yehowa, moroi ba nangi sabölö, imane:', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 7, '"Labu, amöbö talu, si mane ira matua: Da''uzofu-zofu khöu, ba ya''ugö zangombakha khögu:[1]', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 8, 'Hadia, si lö boto öbe''e zatulö andrö khögu, ö''etu''ö hukugu, ena''ö lala khöu?[2]', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 9, 'Hadia no si mane ta''io Lowalangi da''iomö? ba hadia, mu''ugu-ugu maö limö, si mane linia?', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 10, 'Ba angehao, fa''ahelanö ba fa''ebua; onukha lakhömi ba fa''asalaŵa!', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 11, 'Alakha falawu wönumö, ba tuli''ö tou zi fayaŵa fefu, ha fanöngöu ya''ira.', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 12, 'Hana na ha famaigiu ya''ira wangöhöndrögö zi fayaŵa andrö, ba timba tou zebua horö.', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 13, 'Balugö gawu-gawu ira fefu, balugö ba zi tobini mbawara.', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 14, 'Ba ya''o göi zanuno ya''ugö, wa i''orifi''ö tangau kambölö!', '["Faigi 38:3","Sin 51:6; Rom 3:4"]', NULL),
  (3475504, 'OT', 'Yobi', 40, 15, 'Faigi ato mbehemoti andrö, niwöwöigu ba ngaimö: i''a ndru''u si mane öröbao!', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 16, 'Faigi ato wa''abölönia ba löwi-löwinia ba fa''abe''enia ba nuo dalunia andrö.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 17, 'I''oro''ö gi''onia timba döla geresi; no abe''e wa''afafali nuo ba wahania.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 18, 'Tölania, ba no timba koro töla garamba; no timba gukhu zi''öli dölania andrö.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 19, 'Da''ö zi a''a niwöwöi Lowalangi; somböi ya''ia, ba no i''oro''ö khönia wöda.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 20, 'Ba hili sa so gönia, ba zi famaimai utu ndru''u fefu.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 21, 'Barö zukhu mörö-mörö ia ba mbini-mbini barö honu ba dambu.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 22, 'Ibalugö ia sukhu, lumö khönia, te''u''u ia daha ge''oyo ba mbewe nidanö.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 23, 'Na molö, ba lö ata''u ia, sahono-hono manö ia, he sara Yoridano zanaŵa bawania.', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 24, 'Ba tema ra''u ia ba zanehe ia, ba ena''ö na latema latögi nikhunia si''öli!', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 25, 'Hadia, ö''ila ögaini mbuaya, ba ö''ila öfesu lelania sinali gai?', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 26, 'Hadia, ö''ila öfatörö ba nikhunia zilai, ba ö''ila ötögi mbo''önia khai-khai?', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 27, 'Hadia, ihöna maö wangalulu khöu? hadia ihaogö-haogö wehede khöu?', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 28, 'Hadia, fawu''u li ia khöu, fa öhalö sawuyumö ia, si lö mamalö-malö?', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 29, 'Hadia, famaimai ndra''ugö khönia, si mane ba nono wofo? ba hadia, ö''ila öfesu ia, aya nonou alawe?', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 30, 'Hadia, lafatö mbölinia khö nawöra sangai-ngai i''a, ba lafaosa ba zaniaga?', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 31, 'Hadia, ö''ila öfahöfahö gulinia? ba hadia, manga maö ba högönia watebusa?', '[]', NULL),
  (3475504, 'OT', 'Yobi', 40, 32, 'Tema babaya ia — ba törö-törö tödöu, he wisa wasöndrata andrö! lö''ö sa''ae öfuli ölau.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 1, 'Hiza, no tobali faya nidöna-dönania andrö; ha i''ila, ba tegaölö tou ia.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 2, 'Samösa lö si lö ata''u isuko, — ba ha niha zangila molaŵa ya''odo?', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 3, 'Ha niha zi no mame''e khögu hadia ia mege, nisulönigu ena''ö? Fefu hadia ia zi so ba guli danö, ba no khögu.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 4, 'Tebai zi lö utunö ndroto-ndrotonia andrö, ba fa''abölönia ba fa''asökhi wangaronia andrö.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 5, 'Ha niha zi no mamahoi barunia, ba ha ha niha zombambaya ifönia andrö si dua ngenoli?', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 6, 'Ha niha zi no mamokai bawandruhö mbawania, si dua görö lagö andrö? Ifönia andrö fasui, ba no sata''u ita!', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 7, 'Famoadu huna-hunania sabe''e andrö, si no mulau fangaro, ba wamatöfa.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 8, 'No te''oli manö, lö itörö oho gatalua.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 9, 'Oi fatöfa, faduhö manö, tebai fawöhöi.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 10, 'Bahönia, ba sihaga, ba hörönia, ba no hulö mbu hörö wa''amoluo.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 11, 'I''otarai mbawania sulu, bo galitö moroi bakha.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 12, 'Zauzau zalua ba dögi nikhunia, hulö si mane ba mbowoa nidanö so''otu ba galitö.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 13, 'Hanu-hanunia andrö, ba ifohola mbo galitö, hola-hola galitö zalua ba mbawania.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 14, 'Ba mbaginia so wa''abölö andrö, ba molaya fönania wa''ata''u.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 15, 'Tebai faefa mbu''u mbotonia, no timba nifahele, tebai mangiwa.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 16, 'Tödönia, ba no sabe''e, hulö gara, fa''abe''e gara gisa wakhe tanö tou.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 17, 'Na ifazaŵa ia, ba ata''u zabölö, tokea ba fawuka dödö.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 18, 'Na lalau khönia zi''öli, ba lö i''a, ba he toho, ba he ono wana, ba he fatebusa.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 19, 'Töla wakhe zi''öli wamaiginia; ba eu si no le''afö döla garamba.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 20, 'Tenga fanaboinia nono wana, ba kara riboribo, ba no timba ndrami wakhe khönia.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 21, 'Töla wakhe mbago gama wamaiginia, ba ma''iki ia ba wehöngö doho.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 22, 'Barönia, ba no hulö gabotola zörömi; molade wamöbörö wakhe ba dambu.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 23, 'Mo''otu''otu namö ibe''e, hulö mbowoa bawu, ba ibali''ö balanga fondrino dalu-dalu nidanö sebua.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 24, 'Humaga lahenia furinia, hulö huwa hohou taŵa''ö.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 25, 'Lö ba guli danö si falaŵa khönia, ya''ia andrö, niwöwöi ba wa böi manö ata''u.', '[]', NULL),
  (3475505, 'OT', 'Yobi', 41, 26, 'Fefu wa''asalaŵa, ba i''ositengagö; no razo zebua fayaŵasa ia."', '[]', NULL),
  (3475506, 'OT', 'Yobi', 42, 1, 'Ba itema li Yehowa Yobi, imane:', '["Faigi 38:2; Amaed 28:13; YohI 1:9","Faigi 38:3"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 2, '"U''ila, wa lö hadia ia, si tebai ndra''ugö, awö wa lö tödöu, si tebai öfalua.', '["Faigi 38:2; Amaed 28:13; YohI 1:9","Faigi 38:3"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 3, '''Ha niha zombalugö tödö [Lowalangi], niha sambö tödö andrö''? Andrö uŵa''ö, ba wa lö tödö andrö, ngawalö si tebai aboto ba dödögu, si lö u''ila watahögö.[1]', '["Faigi 38:2; Amaed 28:13; YohI 1:9","Faigi 38:3"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 4, '''Ba fondrondrongo, alakha ya''odo zihede; da''usofu khöu, ba öfahaö ndra''o.''[2]', '["Faigi 38:2; Amaed 28:13; YohI 1:9","Faigi 38:3"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 5, 'Ha turiamö nirongogu mege, ba iya''e, ba no i''ila''ö hörögu!', '["Faigi 38:2; Amaed 28:13; YohI 1:9","Faigi 38:3"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 6, 'Andrö ufuli ligu, ba mangesa dödögu, ba gawu-gawu tou ba ba nawu!"', '["Faigi 38:2; Amaed 28:13; YohI 1:9","Faigi 38:3"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 7, 'Ba me no i''o''ozui huhuonia andrö khö Yobi Yehowa, ba imane khö Gelifasi, banua Dema: "No tesao wönugu khöu ba ba zi fahuwu khöu andrö, si darua, me no tenga satulö huhuomi andrö, wamatou ya''o, no tenga si mane huhuo genonigu Yobi.', '["Hez 14:14"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 8, 'Ba mihalö nono zaŵi, fitu rozi, ba biri-biri si matua, fitu nga''eu, ba mi''ae khö genonigu Yobi ba mibe''e zumange nitunu, tana khömi, ba akha mangandrö genonigu Yobi, salahimi, me no ha sambalö famaigigu ya''ia, wa utaha na dödögu, ba wolau khömi, me no tenga satulö huhuomi andrö, wamatou ya''o, no tenga si mane khö genonigu Yobi."[3]', '["Hez 14:14"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 9, 'Ba möi ndra Elifasi, banua Dema, Bilidado, banua Zua, Sofari, banua Na''ama, la''o''ö niŵa''ö Yehowa khöra; ba ifondrondrongo khö Yobi Yehowa.', '["Hez 14:14"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 10, 'Ba ifadöhö wamakao Yobi andrö Yehowa, me mangandrö ia salahi zi fahuwu khönia andrö; ifabali sa''ae khö Yobi fefu zi so khönia föna.[4]', '["Faigi 8:7","MozIV 27:8–11","MozI 25:8"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 11, 'Ba möi khönia dalifusönia fefu, matua ba alawe, awö zi no fa''ila li khönia mege, fefu, manga ira khönia, ba nomonia, lafa''ele''ö wa''ahakhö dödöra, ba larara dödönia ba wamakao andrö fefu, nifatörö Yehowa khönia; ba mamuala ira khönia, sagörö hua balaki ba sambua laeduru ana''a zamösa.', '["Faigi 8:7","MozIV 27:8–11","MozI 25:8"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 12, 'Ba abölö ifahowu''ö Yobi Yehowa ba zi tosai noso Yobi, moroi me föna; falukha ia mbiri-biri, 14.000 nga''eu, ba ondra, 6.000 nga''eu, ba saŵi, 1.000 fasa, ba kalide si alawe, 1.000 nga''eu.', '["Faigi 8:7","MozIV 27:8–11","MozI 25:8"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 13, 'Ba tumbu khönia ndraono, 7 nono matua ba 3 nono alawe;', '["Faigi 8:7","MozIV 27:8–11","MozI 25:8"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 14, 'ba töi zi sambua khönia, ba Yemima ba si sambua, ba Kasia, ba si akhi, ba Kerene-Hafukha.', '["Faigi 8:7","MozIV 27:8–11","MozI 25:8"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 15, 'Ba ba danöra ma''asagörö, ba lö ira alawe si manö fa''asökhi bawa, si mane ono Yobi; ba ifanema ira ondröita amara, ba ngai dalifusöra matua.[5]', '["Faigi 8:7","MozIV 27:8–11","MozI 25:8"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 16, 'Ba aefa da''ö, ba 140 fakhe tö noso Yobi, ba tölu nga''ötö i''ila ma''uwunia.', '["Faigi 8:7","MozIV 27:8–11","MozI 25:8"]', NULL),
  (3475506, 'OT', 'Yobi', 42, 17, 'Ba mate Yobi, me no atua sibai ia ba me no aföli ia wa''auri.[6]', '["Faigi 8:7","MozIV 27:8–11","MozI 25:8"]', NULL),
  (3402597, 'OT', 'Sinunö', 1, 1, 'Ya''ahowu niha si lö molo''ö nikhoi dödö zebua horö andrö, ba si lö manörö lala zolalö andrö, ba si lö dumadao ba zi dadao zango''aya. [1]', '["Sin 119:1; 26:4; Amaed 4:14; Yer 15:17","Sin 119:35; 47:70-97; Yos 1:8; MozV 6:7","Sin 92:13-16; Yer 17:8"]', NULL),
  (3402597, 'OT', 'Sinunö', 1, 2, 'Same''e fa''omuso dödönia oroisa Yehowa ba sangalui eluaha goroisania, bongi ma''ökhö. [2]', '["Sin 119:1; 26:4; Amaed 4:14; Yer 15:17","Sin 119:35; 47:70-97; Yos 1:8; MozV 6:7","Sin 92:13-16; Yer 17:8"]', NULL),
  (3402597, 'OT', 'Sinunö', 1, 3, 'Hulö geu sowua nitanö ba mbewe nidanö, zi manö sowua buania na inötö. Bulunia ba tebai aleu, ba hadia ia nifazökhinia ba mofozu. [3]', '["Sin 119:1; 26:4; Amaed 4:14; Yer 15:17","Sin 119:35; 47:70-97; Yos 1:8; MozV 6:7","Sin 92:13-16; Yer 17:8"]', NULL),
  (3402597, 'OT', 'Sinunö', 1, 4, 'Ba tenga si manö zebua horö andrö; tobali sa hulö gadaya ira, ni''oloi''ö nangi. [4]', '["Sin 35:5; Yob 21:18; Hos 13:3","Sin 37:18; Yob 23:10; TimII 2:19"]', NULL),
  (3402597, 'OT', 'Sinunö', 1, 5, 'Andrö tebai manaha zebua horö andrö, no tefatörö huku, ba lö aro zolalö andrö ba mbanua zateolö.', '["Sin 35:5; Yob 21:18; Hos 13:3","Sin 37:18; Yob 23:10; TimII 2:19"]', NULL),
  (3402597, 'OT', 'Sinunö', 1, 6, 'Noa sa i''ila Yehowa lala zatulö, ba lala zebua horö andrö, ba si lö fozu. [5]', '["Sin 35:5; Yob 21:18; Hos 13:3","Sin 37:18; Yob 23:10; TimII 2:19"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 1, 'Hana wa mofönu niha baero, ba hana wa la''alu-alui soi zi lö boto? [1]', '["Hal Zin 4:25-30","Fam 11:18; 19:19","Yer 2:22-55; Luk 19:14","Sin 37:13; 59:9","Yes 34"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 2, 'Molaŵa zalaŵa ba guli danö, ba samatörö andrö, ba mamagölö, ba khö Yehowa ba ba khö nibayoini-Nia andrö. [2]', '["Hal Zin 4:25-30","Fam 11:18; 19:19","Yer 2:22-55; Luk 19:14","Sin 37:13; 59:9","Yes 34"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 4, 'Ba ma''iki zidadao ba zorugo, i''o''aya ira So''aya. [4]', '["Hal Zin 4:25-30","Fam 11:18; 19:19","Yer 2:22-55; Luk 19:14","Sin 37:13; 59:9","Yes 34"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 5, 'Ba muhede Ia khöra ba wönu-Nia, ba ifeta''u ira bakhu-bakhu dödönia andrö. [5]', '["Hal Zin 4:25-30","Fam 11:18; 19:19","Yer 2:22-55; Luk 19:14","Sin 37:13; 59:9","Yes 34"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 6, '"Noa sa atö Ufataro razo andrö Khögu ba Ziona, ba hili ni''amoni''ö andrö Khögu.', '["Hal Zin 4:25-30","Fam 11:18; 19:19","Yer 2:22-55; Luk 19:14","Sin 37:13; 59:9","Yes 34"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 7, 'Da''u''ombakha''ö hadia ba dödö: No imane khögu Yehowa: "Ono-Gu ndra''ugö, ma''ökhö andre no U''onogö ndra''ugö. [6]', '["Sin 89:27-30; Hal Zin 13:33; Heb 1: 5; 5:5","Dan 7:13","Fam 2:27; 12:5; 19:15"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 8, 'Andrö khö-Gu, ba Ube''e tana khöu soi niha, ba ya khöu mbalö danö. [7]', '["Sin 89:27-30; Hal Zin 13:33; Heb 1: 5; 5:5","Dan 7:13","Fam 2:27; 12:5; 19:15"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3402601, 'OT', 'Sinunö', 2, 9, 'Örasa dania ira si''o si''öli, hulö mbowoa tanö öfufu ira." [8]', '["Sin 89:27-30; Hal Zin 13:33; Heb 1: 5; 5:5","Dan 7:13","Fam 2:27; 12:5; 19:15"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 10, 'Ba iya''e, ba mi''era-era tödömi ya''ami razo, mibe''e nitegu ami ya''ami sanguhuku ba guli danö.', '["Fil 2:12; Heb 12:28","SamI 10:1; Sin 34:9; 84:13; Yes 30:18"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 11, 'Mi''ae enoni Yehowa, mi''ata''ufi; mi''omusoi''ö dödömi, ba tambai manizi-nizi ami. [9]', '["Fil 2:12; Heb 12:28","SamI 10:1; Sin 34:9; 84:13; Yes 30:18"]', NULL),
  (3402601, 'OT', 'Sinunö', 2, 12, 'Mifa''ago bawa khö Nono, fa böi mofönu Ia, ba fa böi tekiko ami ba lala: ahatö sa wa''atesao wönu-Nia. Ya''ahowu dozi sanaŵa Ya''ia! [10]', '["Fil 2:12; Heb 12:28","SamI 10:1; Sin 34:9; 84:13; Yes 30:18"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 1, 'Sinunö khö Dawido, me moloi ia, me igohi ia ononia Abisalomi. [1]', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 2, 'He Yehowa, no ato sibai zamakao ya''o, no ato sibai zi maoso udugu.', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 3, 'Ato zanguma''ö khögu: "Lö fanolo Lowalangi khönia".', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 4, 'Ba baluse sa Ndra''ugö khögu, ya''ugö Yehowa! sumangegu Ndra''ugö ba samaöga bawagu. [2]', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 5, 'Mu''aodo khö Yehowa, ba no Itema ligu, moroi ba hili ni''amoni''ö andrö khö-Nia.', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 6, 'No uleagö tou ndra''o mege, ba mörödo. Ba no tokeado; I''abe''e''ö sa ndra''o Yehowa. [3]', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 7, 'Lö ata''udo ngahönö niha, samasui ya''o. [4]', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 8, 'Faoso, Yehowa! tolodo, Lowalangigu! Öfeta''u sa mbawa zi fa''udu khögu fefu, Örasa nifö zebua horö andrö. [5]', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3405029, 'OT', 'Sinunö', 3, 9, 'Khö Yehowa wangorifi; yamöi ba mbanua-U andrö howu-howu-Mö andrö. [6]', '["SamII 15:14","Sin 84:12","Sin 4:9. Amaed 3:24","Sin 27:3","Sin 58:7","Yer 3:23"]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 1, 'Khö duka wanunö andrö, solau biola. Sinunö khö Dawido.', '[]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 2, 'Na mu''aodo khöu, ba fondrongondrongo khögu, ya''ugö Lowalangi fa''atulögu andrö. No öbologö dödögu, me no tofera. Ebua''ö dödöu khögu ba fondrondrongo wangandrögu.', '["Sin 17:7","Efes 4:26; Sin 16:7","Sin 51:19,21"]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 3, 'He ya''ami, niha! Heza irugi, wa tobali fango''oya zumangegu? Mi''alui waya, wangomasi''ö si lö boto.', '["Sin 17:7","Efes 4:26; Sin 16:7","Sin 51:19,21"]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 4, 'Ya aboto ba dödömi, wa ifaehusi Yehowa zatulö tödö andrö khönia. Ifondrondrongo Yehowa, na mu''aodo khönia.[1]', '["Sin 17:7","Efes 4:26; Sin 16:7","Sin 51:19,21"]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 5, 'Mi''ofönu, ba böi mifazökhi horö! Mifatou-tou tödömi ba gasomi andrö ba mihonogö ami.[2]', '["Sin 17:7","Efes 4:26; Sin 16:7","Sin 51:19,21"]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 6, 'Mibe''e zumange, soroi ba wa''atulö dödö, ba midöna-döna khö Yehowa hadia ia.[3]', '["Sin 17:7","Efes 4:26; Sin 16:7","Sin 51:19,21"]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 7, 'Ato zanguma''ö: "Ha niha zangoroma''ö khöda si sökhi?" He Yehowa, faöga yaŵama haga mbawamö andrö![4]', '["MozIV 6:25,26","MozIII 26:6; Sin 3:6"]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 8, 'No ö''omusoi''ö dödögu, moroi me oya mbua nowira ba agura.', '["MozIV 6:25,26","MozIII 26:6; Sin 3:6"]', NULL),
  (3476013, 'OT', 'Sinunö', 4, 9, 'Ufadölö ndra''o ba u''anema''ö mörö, lö hadia ia. Ya''ugö Yehowa sa zamaigi, fa ahono ndra''o ba nahagu, he ba zi ha ya''o.[5]', '["MozIV 6:25,26","MozIII 26:6; Sin 3:6"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 1, 'Khö duka wanunö andrö, solau surune. Sinunö khö Dawido.', '[]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 2, 'Fondrondrongo ligu Yehowa, be''e ba dödöu lua-lua dödögu andre![1]', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 3, 'Be''e mbörö dalingau ba we''aogu andre, ya''ugö, razogu ba Lowalangigu; khöu sa mangandrö ndra''odo.[2]', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 4, 'He Yehowa, ba zanguhulö wongi fondrondrongo ligu! Uhulö wongi ufa''anö zumange khöu, ba udöna-döna khöu wangorifi.', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 5, 'Tenga sa Lowalangi somasi si lö sökhi ndra''ugö; lö monaha khöu niha si lö sökhi.[3]', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 6, 'Tebai lafaigi mbawau si fayaŵa, ba no fa''udu ndra''ugö ba zamazökhi si lö sökhi.', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 7, 'Solau faya, ba öbunu. I''ogorofi Yehowa zange''enge''e ba si falimolimo.', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 8, 'Ba ya''o, ba tola möi ba nomou, börö wa''ebua dödöu andrö, si no fahöna, mangalulu ndra''o ba gosaliu andrö, ni''amoni''ö, u''ata''ufi ndra''ugö.[4]', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 9, 'He Yehowa, ohe dangagu, ba wa''atulö dödöu andrö, ba zi fa''udu khögu andrö; adölö''ö fönagu lala andrö khöu.', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 10, 'Lö''ö sa hadia ia zi duhu ba mbewera, tödöra andrö, ba famakiko; lewatö sobawa dölö-tölöra, ba no alösö-lösö lelara.[5]', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 11, 'Otu''ö ira, Lowalangi, ena''ö tobali faya nifakhoi dödöra. Tuli''ö ira, ba wa''oya lalöra andrö; samadaö limö sa ira andrö.', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 12, 'Ena''ö omuso dödö dozi sanötöna khöu, ena''ö owua-wua dödöra, si lö aetu. Ba fobelebele ira, ena''ö ma''iki ira ba khöu andrö; sangomasi''ö töimö andrö.[6]', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476014, 'OT', 'Sinunö', 5, 13, 'Ya''ugö i, ba öfahowu''ö zatulö tödö, ya''ugö, Yehowa, öfobelebele ia fa''ebua dödöu, hulö nifobaluse.[7]', '["Sin 17:1","Sin 84:4","Sin 34:17","Sin 26:8","Rom 3:13","Sin 40:17","Sin 103:4"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 1, 'Khö duka wanunö andrö, solau biola, lala si ŵalu. Sinunö khö Dawido.', '[]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 2, 'He Yehowa, böi fatörö khögu huku, ba wönumö andrö, ba böi otu''ö ndra''o, ba wa''abao dödöu andrö![1]', '["Sin 38:2; Yer 10:24","Sin 51:10","Sin 13:2,3","Sin 30:10; 88:11; 115:17","Sin 31:10; Yob 17:7"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 3, 'Bologö dödöu khögu, me sariri sa''ae ndra''odo, abe''e''ö ndra''o, Yehowa, me no a''oi manizi-nizi dölagu.[2]', '["Sin 38:2; Yer 10:24","Sin 51:10","Sin 13:2,3","Sin 30:10; 88:11; 115:17","Sin 31:10; Yob 17:7"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 4, 'Ba tödögu, ba no tobali sibai. Ba ya''ugö, Yehowa, ba ha lö ara''ö![3]', '["Sin 38:2; Yer 10:24","Sin 51:10","Sin 13:2,3","Sin 30:10; 88:11; 115:17","Sin 31:10; Yob 17:7"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 5, 'Fuli''ö, Yehowa, orifi nosogu, tolodo, ba wa''ebua dödöu andrö.', '["Sin 38:2; Yer 10:24","Sin 51:10","Sin 13:2,3","Sin 30:10; 88:11; 115:17","Sin 31:10; Yob 17:7"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 6, 'Ba wa''amate sa, ba lö itörö tödö ndra''ugö; ha niha zangandrö saoha gölö khöu ba mbanua tou?[4]', '["Sin 38:2; Yer 10:24","Sin 51:10","Sin 13:2,3","Sin 30:10; 88:11; 115:17","Sin 31:10; Yob 17:7"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 7, 'Erege dödögu wangarö-ngarögu andre; ufemondri gasogu, sara wongi manö, mo''idanö dufogu ube''e, ba daŵa hörögu andrö.', '["Sin 38:2; Yer 10:24","Sin 51:10","Sin 13:2,3","Sin 30:10; 88:11; 115:17","Sin 31:10; Yob 17:7"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 8, 'No alulu mbawagu ba wa''abu dödö andrö, hulö zatua, börö zamakao ya o andrö, fefu.[5]', '["Sin 38:2; Yer 10:24","Sin 51:10","Sin 13:2,3","Sin 30:10; 88:11; 115:17","Sin 31:10; Yob 17:7"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 9, 'Milabu ami, miheta ami khögu, ya''ami, samazökhi si lö sökhi, fefu; noa sa ifondrondrongo li we''ge''egegu andrö Yehowa.', '["Sin 35:4,26; 40:15"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 10, 'Fangarö-ngarögu andre, ba no ifondrondrongo Yehowa. Lö itimba wangandrögu Yehowa.', '["Sin 35:4,26; 40:15"]', NULL),
  (3476015, 'OT', 'Sinunö', 6, 11, 'Saila dania fefu zi fa''udu khögu ba si tokea sibai; i''ogomuzaö lafuli ira dania, ba aila.[6]', '["Sin 35:4,26; 40:15"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 1, 'Fangarö-ngarö Dawido khö Yehowa, börö niŵa''ö Khusi andrö, mado Mbeniyami.[1]', '["SamI 24:10; 26:19; SamII 16:5–11"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 2, 'He Yehowa, Lowalangigu, saŵatögu ndra''ugö, tolodo, ba zolohi ya''o andrö fefu, ba orifido!', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 3, 'Fa böi isasawi dödögu, si mane singo, fa böi ifufu, lö sangorifi.[2]', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 4, 'He Yehowa, Lowalangigu! Na no atö ulau zi manö, na no togule ba dangagu zi lö atulö,[3]', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 5, 'Na no ulau zi lö sökhi, ba zi sökhi tödö khögu, ba na no u''alani nudugu, lö börö-börö,', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 6, 'ba yamugohi nosogu si fatiu tödö andrö, ba yamura''u, yamuhundragö tou nosogu, yamutou''ö ba danö lakhömigu andrö.', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 7, 'Faoso, Yehowa, ba wönumö andrö! fazaŵa''ö, ba wolaŵa wo''otu dödö zamakao ya''o; faoso, ondrasido! noa sa öhonogöi huku.', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 8, 'Ndramufasui ndra''ugö ngahönö soi, ba fuli''ö miyaŵa, yaŵara.', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 9, 'Ihuku soi niha Yehowa. Huku ndra''o, Yehowa, dali wa''atulögu ba fa''adölö dödögu![4]', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 10, 'Ena''ö tebato walösökhi ba zi lö sökhi andrö; abe''e''ö zatulö tödö! Ya''ugö zanekhegö tödö, awö mbua, ya''ugö, Lowalangi satulö.[5]', '["Sin 10:8,9","Yob 31:7–34","Sin 18:21–27","Sin 104:35; Yer 11:20; 17:10; Fam 2:23"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 11, 'Lowalangi zolohe baluse khögu, itolo zadölo tödö.[6]', '["Sin 3:4","Sin 9:5","MozV 32:41; Ngenu 2:4; 3:12","Amaed 26:27"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 12, 'Sanguhuku si no atulö Lowalangi, Lowalangi sameta''u niha, ero ma''ökhö.[7]', '["Sin 3:4","Sin 9:5","MozV 32:41; Ngenu 2:4; 3:12","Amaed 26:27"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 13, 'Na so zi lö mamalalini era-erania, ba no idali wödania, ba no ikhai wanania ba italini.[8]', '["Sin 3:4","Sin 9:5","MozV 32:41; Ngenu 2:4; 3:12","Amaed 26:27"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 14, 'Ifaudugö ono wana famunu zi manö, ifo''alitö nono wana andrö khönia.', '["Sin 3:4","Sin 9:5","MozV 32:41; Ngenu 2:4; 3:12","Amaed 26:27"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 15, 'Hiza, so zi lö sökhi ba dödö zi manö. No abeto ia famakao, ba i''adonogö waya.', '["Sin 3:4","Sin 9:5","MozV 32:41; Ngenu 2:4; 3:12","Amaed 26:27"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 16, 'No ikhao lösu-lösu, no i''abakha''ö, ba ya''ia zaekhu bakha, ba lösu-lösu andrö, nikhaonia.[9]', '["Sin 3:4","Sin 9:5","MozV 32:41; Ngenu 2:4; 3:12","Amaed 26:27"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 17, 'Ba högönia mangawuli wamakao andrö khönia, ba galizuzunia göna dania horönia andrö.', '["Sin 3:4","Sin 9:5","MozV 32:41; Ngenu 2:4; 3:12","Amaed 26:27"]', NULL),
  (3476016, 'OT', 'Sinunö', 7, 18, 'Ba ya''o, ba u''andrö saoha gölö khö Yehowa, dali wa''atulönia andrö, ba usuno döi Yehowa, Fondrege zalaŵa.', '["Sin 3:4","Sin 9:5","MozV 32:41; Ngenu 2:4; 3:12","Amaed 26:27"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 1, 'Khö duka wanuno andrö. Sinunö khö Dawido.', '[]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 2, 'He Yehowa, salaŵama, wa''ebua lakhömi döimö andrö, ba guli danö, ma''asagörö! No öfolakhömi mbanua si yaŵa lakhömimö andrö.', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 3, 'No ö''a''asogö wa''abölö, moroi ba mbewe ndraono ba moroi ba mbewe zi so ba mbagi zusu. Börö nudumö andrö. Ba wangöhöndrögö si fatiu tödö andrö, awö zangalui folau balö andrö.[1]', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 4, 'Na ufaigi mbanua si yaŵa andrö khöu, nifazökhi durumö andrö, baŵa ba döfi andrö, nifataromö.[2]', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 5, 'Ba hadia niha si mate andrö, waitörö tödöu ia? Ba ono niha andrö, wa ötolo ia?[3]', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 6, 'Ha ma''ifu ö''ambösi ia mege, moroi ba Lowalangi, ba no öfotakula ia sumange ba fa''amoadu.[4]', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 7, 'No öbe''e samatörö nifazökhi dangau andrö ia; fefu hadia ia, ba no öbe''e barö gahenia.[5]', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 8, 'Biri-biri ba öröbao, fefu, awö gutu ndru''u andrö.', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 9, 'Fofo ba dalu mbanua ba i''a ba nasi ba hadia zaliŵa-liŵa ba nasi andrö.', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476017, 'OT', 'Sinunö', 8, 10, 'He Yehowa, samatörö ya''aga, ha lö ebua duria döimö andrö, ba guli danö, ma''asagörö!', '["Mat 21:16","Sin 19:2","Sin 144:3; Heb 2:6–9","MozI 1:26","Mat 28:18; KorI 15:18"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 1, 'Khö duka wanunö andrö, dali: "Mate''ö salahi nono." Sinunö khö Dawido.', '[]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 2, 'Damangandrödo saoha gölö khö Yehowa, moroi si''aikö ba dödögu, da''utunö zahöli-höli dödöda andrö khönia.', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 3, 'Da''u''omusoi''ö dödögu khöu, akha ma''iki dödögu, da''usuno döimö, ya''ugö Fondrege zalaŵa.', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 4, 'Börö wa lawuwu ira furi si fa''udu khögu andrö; tegaölö tou ira ba tekiko, ba wanöngöu ya''ira.', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 5, 'Noa sa ya''ugö zamaigi lala ba khögu andre, no ö''asiwai huhuo andrö khögu; no mudadao''ö ba dadaoma zanguhuku andrö, sanguhuku satulö.[1]', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 6, 'No ötenaŵa niha baero, ba no öfakiko zebua horö; no öbunu döira, si lö fangorifi, irugi zi lö aetu.', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 7, 'No aetu nemali andrö, no tobali adudula, si lö mamalö-malö, no tobali arö mbanuara öbe''e; lö''ö sa''ae itörö tödö niha bö''ö.[2]', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 8, 'Ba mudadao ba dadaomania Yehowa, lö mamalö-malö, no i''aro''ö dadaomania, ba wanguhuku.[3]', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 9, 'Ba ihuku golia uli danö, ba wa''atulö, i''asiwai huhuo soi niha ba wa''adölö.[4]', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 10, 'Belebele nifakao Yehowa, ba''a-ba''a, na baŵa lö lala dödö.', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 11, 'Andrö manötöna khöu zi no mangila töimö andrö, me lö si faröi ndra''ugö ba zanofu-nofu ya''ugö, Yehowa.', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 12, 'Mi''anunö khö Yehowa, sonahia ba Ziona, midunö-dunö ba niha misa wolau-launia.[5]', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 13, 'Me i''alu-alui horö, fange''enge''e andrö, me itörö tödönia; lö olifu ia wangarö-ngarö zanaha famakao.[6]', '["Sin 7:12","Sin 34:17","Sin 103:19","Sin 96:13","Sin 132:13","MozI 4:10"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 14, 'Ebua''ö dödöu khögu, Yehowa, faigi wamakao zi fa''udu andrö ya''o; ya''ugö, samazaŵa ya''o moroi ba mbawandruhö ba wa''amate andrö.', '["Sin 22:23; 40:10–11; 13:6","Sin 7:16","Sin 7:17","Sin 22:25; 10:17,18","Sin 59:14"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 15, 'Ena''ö udunö-dunö duriamö andrö fefu, ena''ö ma''iki dödögu ba mbawa göli Nono Ziona alawe andrö, ba wangorifi andrö khöu.[7]', '["Sin 22:23; 40:10–11; 13:6","Sin 7:16","Sin 7:17","Sin 22:25; 10:17,18","Sin 59:14"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 16, 'No alau niha baero andrö, ba lösu-lösu nikhaora, no tokhai gahera ba gu''ö andrö nifadölöra.[8]', '["Sin 22:23; 40:10–11; 13:6","Sin 7:16","Sin 7:17","Sin 22:25; 10:17,18","Sin 59:14"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 17, 'No terongo Yehowa, wa sanguhuku ia. Ba nilau-lau dangania fafali zebua horö.[9]', '["Sin 22:23; 40:10–11; 13:6","Sin 7:16","Sin 7:17","Sin 22:25; 10:17,18","Sin 59:14"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 18, 'Ba mbanua tou numalö zebua horö andrö; fefu niha baero andrö, si no olifu Lowalangi.', '["Sin 22:23; 40:10–11; 13:6","Sin 7:16","Sin 7:17","Sin 22:25; 10:17,18","Sin 59:14"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 19, 'Tenga si lö mamalö-malö, wa olifu ia zi numana, ba tenga si lö tebulöbulö, wa lö boto wanötöna zabu tödö andrö.[10]', '["Sin 22:23; 40:10–11; 13:6","Sin 7:16","Sin 7:17","Sin 22:25; 10:17,18","Sin 59:14"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 20, 'Faoso, Yehowa! Fa böi fayaŵa niha; alakha tehuku niha baero andrö, tanö fönau.', '["Sin 22:23; 40:10–11; 13:6","Sin 7:16","Sin 7:17","Sin 22:25; 10:17,18","Sin 59:14"]', NULL),
  (3476018, 'OT', 'Sinunö', 9, 21, 'Hawui ira fa''ata''u, ya''ugö Yehowa, ena''ö aboto ba dödö niha baero, wa niha si mate ira.[11]', '["Sin 22:23; 40:10–11; 13:6","Sin 7:16","Sin 7:17","Sin 22:25; 10:17,18","Sin 59:14"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 1, 'Hana wa ba zaröu so''ö, Yehowa, hana wa öbini''ö ndra''ugö, na baŵa lö lala dödö?[1]', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 2, 'Ba wayaŵasa zebua horö mogikhi zabu tödö andrö, te''u''u ira ba nikhoi dödö da''ö.', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 3, 'Isuno ia sebua horö ba wangisö dödönia andrö, ba somasi ana''a, ba i''erogö Yehowa ba i''o''aya.', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 4, 'Imane sebua horö ba hokhania: "Lö izofu-zofu (Lowalangi) Lö Lowalangi." Awai gera-erania.', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 5, 'Mofozu wolau-launia, lö mamalö-malö; aröu si yaŵa na huku khöu, lö oroma khönia; ihangöi fefu zi fa''udu khönia.[2]', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476019, 'OT', 'Sinunö', 10, 6, 'Imane dödönia: "Lö mangiwa ndra''o, götö-götö wa''ara, ba lö''ö manö göna ndra''o fa''abu dödö."', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 7, 'No fahöna ba mbewenia wangelifi ba faya ba famalangögö awönia, barö lelania so wamakiko ba famakuyu.', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 8, 'Manaronaro ia ba gero mbanua misa, ba zi tobini, ibunu zi lö horö, idaro-darogö zi tebai, hörönia.', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 9, 'Manaronaro ia ba zi tobini, hulö zingo ba zasai''ö du''u; idaro-darogö, ba wondra''u sabu tödö andrö. Ira''u zabu tödö andrö, ifa''u''u ba gu''önia.[3]', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 10, 'Iköwö ia, tou ba danö, ba ira''u sa''ania zi tebai andrö.', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 11, 'Imane dödönia: "No olifu Lowalangi, no ibini''ö mbawania; lö''ö manö i''ila, sagötö fa''ara."[4]', '["Sin 44:25","Amos 6:3","Sin 17:12","Sin 94:7"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 12, 'Faoso, Yehowa! fazaŵa dangau, Lowalangi! böi olifugö''ö nifakao andrö.', '["Sin 68:6; MozII 22:22","Sin 37:10,36","Sin 99:1"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 13, 'Hana wa tola i''o''aya Lowalangi sebua horö andrö, ba hana wa tola iŵa''ö tödönia, lö özofu-zofu?', '["Sin 68:6; MozII 22:22","Sin 37:10,36","Sin 99:1"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 14, 'O''ila; öfaigi sa wamakao ba fa''abu dödö, ba wanura ya''ia ba lalu''a dangau; khöu manötöna zi tebai; ötolo zi lö ama, si lö ina.[5]', '["Sin 68:6; MozII 22:22","Sin 37:10,36","Sin 99:1"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 15, 'Tema fatö mbölökha zebua horö andrö, ba ba zi lö sökhi andrö, ba lau mbalö, ena''ö taya ia fönau.[6]', '["Sin 68:6; MozII 22:22","Sin 37:10,36","Sin 99:1"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 16, 'Razo Yehowa, götö-götö wa''ara, no taya niha baero andrö, ba danö andrö khönia.[7]', '["Sin 68:6; MozII 22:22","Sin 37:10,36","Sin 99:1"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 17, 'No öfondrondrongo wehulu dödö nifakao andrö, ya''ugö Yehowa, ö''abe''e''ö dödöra, öfondrondrongo khöra.', '["Sin 68:6; MozII 22:22","Sin 37:10,36","Sin 99:1"]', NULL),
  (3476019, 'OT', 'Sinunö', 10, 18, 'Ba wangasiwai huhuo zi lö ama, si lö ina, awö huhuo nifakao andrö, fa böi sa''ae ifeta''u nawönia niha guli danö andrö.', '["Sin 68:6; MozII 22:22","Sin 37:10,36","Sin 99:1"]', NULL),
  (3476020, 'OT', 'Sinunö', 11, 1, 'Khö Yehowa abe''e dödögu. Hana wa mimane khögu: "Mi''oloi ba hili andrö khömi, si mane fofo?"[1]', '["SamI 26:20","Sin 37:14; 64:4,5"]', NULL),
  (3476020, 'OT', 'Sinunö', 11, 2, 'Si ndruhu sa, lakhai wana sebua horö andrö; no lafaedogö nono wana ba zinali andrö, ba wamana sadölö tödö, ba zogömi-gömi.[2]', '["SamI 26:20","Sin 37:14; 64:4,5"]', NULL),
  (3476020, 'OT', 'Sinunö', 11, 3, 'Na tedudugö zilalö yaŵa andrö, ba hadia nilau zatulö andrö!', '["SamI 26:20","Sin 37:14; 64:4,5"]', NULL),
  (3476020, 'OT', 'Sinunö', 11, 4, 'Ba gödonia ni''amoni''ö andrö so Yehowa; Yehowa si so dadaoma ba zorugo, ifakhölö ia, ifaigi-faigi nono niha hörönia.[3]', '["Hab 2:20; Yes 66:1; Sin 33:13,14","Sin 5:5","MozI 19:24","Sin 33:5; 17:15"]', NULL),
  (3476020, 'OT', 'Sinunö', 11, 5, 'Ifaigi-faigi zatulö andrö Yehowa, ba i''ogorofi tödönia zebua horö andrö ba somasi mamakao awönia.[4]', '["Hab 2:20; Yes 66:1; Sin 33:13,14","Sin 5:5","MozI 19:24","Sin 33:5; 17:15"]', NULL),
  (3476020, 'OT', 'Sinunö', 11, 6, 'Ihawui dania fesu zebua horö andrö; alitö ba talö balera ba angi saukhu gurakhara, ba makora andrö.[5]', '["Hab 2:20; Yes 66:1; Sin 33:13,14","Sin 5:5","MozI 19:24","Sin 33:5; 17:15"]', NULL),
  (3476020, 'OT', 'Sinunö', 11, 7, 'Satulö sa Yehowa, i''omasi''ö wa''atulö. Ihörö-hörögö zadölö tödö.[6]', '["Hab 2:20; Yes 66:1; Sin 33:13,14","Sin 5:5","MozI 19:24","Sin 33:5; 17:15"]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 1, 'Khö duka wanunö andrö; lala si ŵalu. Sinunö khö Dawido.', '[]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 2, 'Tolo, Yehowa, noa sa ahori zatulö, noa sa''ae taya zi lö faröi andrö, ba nono niha.', '["Sin 73:8,9"]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 3, 'Lalau waya, zamösana khö nawönia; lahaogö-haogö bewera ba dua dödöra, na muhede ira.', '["Sin 73:8,9"]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 4, 'Ena''ö na ihori Yehowa dozi bewe si haogö-haogö fehede faya, awö lela, solau hokha.', '["Sin 73:8,9"]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 5, 'Sanguma''ö: "Ba lelama abölö ndra''aga; itolo ndra''aga bewema; ha niha Zo''aya ya''aga?"[1]', '["Sin 73:8,9"]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 6, 'Börö me tefalangögö zahakhö dödöda ba fangarö-ngarö zi numana, wa ufazaŵa ndra''o, iŵa''ö Yehowa, edöna u''orifi zihulu tödö ba da''ö.', '["Sin 19:9","Amaed 28:12"]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 7, 'Taroma li sohau-hau daroma li Yehowa andrö, firö, si no mukhozi ba mbalanga ba danö, no mewitu tekhozi.[2]', '["Sin 19:9","Amaed 28:12"]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 8, 'Ya''ugö Yehowa zanaro ya''aga, ötimba khöma niha andrö, irugi zi lö aetu.', '["Sin 19:9","Amaed 28:12"]', NULL),
  (3476021, 'OT', 'Sinunö', 12, 9, 'No tefasui ndra''aga sebua horö, na möna wa lö ngaroro ba nono niha.[3]', '["Sin 19:9","Amaed 28:12"]', NULL),
  (3476022, 'OT', 'Sinunö', 13, 1, 'Khö duka wanunö andrö. Sinunö khö Dawido.', '[]', NULL),
  (3476022, 'OT', 'Sinunö', 13, 2, 'Ha wa''ara na, Yehowa, wa olifu''ö ndra''odo, si lö mamalö-malö? Ha wa''ara na, wa öbini''ö mbawau khögu?[1]', '["Sin 77:8; Hab 1:2","Sin 9:15"]', NULL),
  (3476022, 'OT', 'Sinunö', 13, 3, 'Ha wa''ara na utaha wa''afökhö andrö, bakha ba dödögu, fa''abu dödögu andrö, sero ma''ökhö? Ha wa''ara na ihöndrögö ndra''o si fatiu tödö khögu?', '["Sin 77:8; Hab 1:2","Sin 9:15"]', NULL),
  (3476022, 'OT', 'Sinunö', 13, 4, 'Faigi Yehowa, Lowalangigu, fondrondrongo ligu! Bokai hörögu, fa böi alau ba wa''amate.', '["Sin 77:8; Hab 1:2","Sin 9:15"]', NULL),
  (3476022, 'OT', 'Sinunö', 13, 5, 'Fa böi iŵa''ö si fatiu tödö khögu: "No uhöndrögö ia;" fa böi ma''iki zamakao ya''o, na mangiwa ndra''odo.', '["Sin 77:8; Hab 1:2","Sin 9:15"]', NULL),
  (3476022, 'OT', 'Sinunö', 13, 6, 'Ba ya''o, ba udöna-döna wa''ebua dödöu: ma''iki dödögu, ba wanolomö andrö. Usuno Yehowa, me no ebua dödönia khögu.[2]', '["Sin 77:8; Hab 1:2","Sin 9:15"]', NULL),
  (3476023, 'OT', 'Sinunö', 14, 1, 'No iwa''ö tödönia sambö tödö: "Lö Lowalangi!" Famakiko, sogoro ita, wolaura; samösa lö''ö, solau si sökhi.', '["Sin 33:13","MozI 6:12; Rom 3:10–12","Mikh 3:3"]', NULL),
  (3476023, 'OT', 'Sinunö', 14, 2, 'No ifaigi Yehowa nono niha, moroi ba zorugo, ba wamaigi, na so zatua-tua, na so zangalui Lowalangi, mato samösa.[1]', '["Sin 33:13","MozI 6:12; Rom 3:10–12","Mikh 3:3"]', NULL),
  (3476023, 'OT', 'Sinunö', 14, 3, 'No ahori fabali ira, no dozi tekiko, alösu lö solau si sökhi, samösa lö''ö.[2]', '["Sin 33:13","MozI 6:12; Rom 3:10–12","Mikh 3:3"]', NULL),
  (3476023, 'OT', 'Sinunö', 14, 4, 'Hadia, lö fa''aboto ba dödö khöra fefu, solau si lö sökhi, si manga mbanuagu andrö, nifemanga roti? Lö la''angaröfi li Lowalangi.[3]', '["Sin 33:13","MozI 6:12; Rom 3:10–12","Mikh 3:3"]', NULL),
  (3476023, 'OT', 'Sinunö', 14, 5, 'Ba ihawui ira fa''ata''u, so sa Lowalangi ba niha satulö tödö andrö.', '["Sin 12:6"]', NULL),
  (3476023, 'OT', 'Sinunö', 14, 6, 'Hana na mi''igi''igi''ö gera-era zahakhö dödöda andrö, me no saŵatönia Yehowa.[4]', '["Sin 12:6"]', NULL),
  (3476023, 'OT', 'Sinunö', 14, 7, 'Ena''ö na irugi Ndraono Gizeraeli fangorifi andrö, si oroi Ziona! Na i''efa''ö Yehowa mbanuania andrö, ba ma''iki Ndraono Yakobo, ba somuso tödö Ndraono Gizeraeli.', '["Sin 12:6"]', NULL),
  (3476024, 'OT', 'Sinunö', 15, 1, 'He Yehowa, ha niha zi iagö ose andrö khömö? Ha niha zonahia ba hilimö andrö, ni''amoni''ö?[2]', '["Sin 84:5","Yes 33:15","MozII 22:24"]', NULL),
  (3476024, 'OT', 'Sinunö', 15, 2, 'Sanörö lalania, si lö sinegu, solau satulö ba solau si duhu, fehedenia, soroi ba dödö.[3]', '["Sin 84:5","Yes 33:15","MozII 22:24"]', NULL),
  (3476024, 'OT', 'Sinunö', 15, 3, 'Si lö mamöbögö si lö duhu, lelania, si lö mamakao awönia, si lö mandraŵaisi awönia.', '["Sin 84:5","Yes 33:15","MozII 22:24"]', NULL),
  (3476024, 'OT', 'Sinunö', 15, 4, 'Sangositengagö tödönia nitibo''ö Lowalangi ba samosumange sangata''ufi Yehowa; na no möi ia ba hölu ba zi te''ala ia, ba lö iwu''ai.', '["Sin 84:5","Yes 33:15","MozII 22:24"]', NULL),
  (3476024, 'OT', 'Sinunö', 15, 5, 'Si lö mamohare ana''ania ba si lö manga gana''a ba zi lö borö; solau si manö, ba lö mangiwa, irugi zi lö aetu.[4]', '["Sin 84:5","Yes 33:15","MozII 22:24"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 1, 'Timba khögu zi lö sökhi, Lowalangi, khöu udöna-döna!', '["Sin 73:25","Ngenu 3:24","Sin 4:5; 17:3"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 2, 'Umane khö Yehowa: Ya''ugö Zo''aya ya''o; lö si sökhi khögu, baerou![1]', '["Sin 73:25","Ngenu 3:24","Sin 4:5; 17:3"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 3, 'Ni''amoni''ö andrö, si so ba danö, da''ö zoadu, somasido, oi so wa''omasigu.', '["Sin 73:25","Ngenu 3:24","Sin 4:5; 17:3"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 4, 'Oya ngawalö wa''afökhö ba zolo''ö Lowalangi bö''ö; lö edönado ube''e zumange nibadu andrö khöra, do andrö, ba lö edönado utötöi döira bewegu.', '["Sin 73:25","Ngenu 3:24","Sin 4:5; 17:3"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 5, 'Yehowa gurakhagu ba ösi makogu andrö; ö''abe''e''ö dahö-dahö andrö khögu.[2]', '["Sin 73:25","Ngenu 3:24","Sin 4:5; 17:3"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 6, 'Ba wondrege zomasi ita göna wanu''a andrö khögu, ba somasido dana khögu andrö.', '["Sin 73:25","Ngenu 3:24","Sin 4:5; 17:3"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 7, 'Usuno Yehowa, si no mamolala tödögu, ba ba zi bongi ifarou ndra''o buagu.[3]', '["Sin 73:25","Ngenu 3:24","Sin 4:5; 17:3"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 8, 'No ube''e ba gametahögu Yehowa, si lö mamalö-malö: na so ia ba gambölögu, ba lö mangiwa ndra''o.', '["MozI 49:6","HalZin 2:25–32; 13:35–37"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 9, 'Andrö omuso dödögu, ba ma''iki lakhömigu andrö, ba ösigu göi molombase, lö hadia ia.[4]', '["MozI 49:6","HalZin 2:25–32; 13:35–37"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 10, 'Lö''ö sa ölulu ba mbanua tou nosogu ba lö ötehe, i''ila satulö tödö andrö khöu wa''obou barö danö.[5]', '["MozI 49:6","HalZin 2:25–32; 13:35–37"]', NULL),
  (3476025, 'OT', 'Sinunö', 16, 11, 'Öfarongogö khögu lala ba wa''auri andrö: ahonoa wa''omuso dödö fönau ba somasi ita ba gambölöu, si lö aetu.', '["MozI 49:6","HalZin 2:25–32; 13:35–37"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 1, 'Fondrondrongo Yehowa huhuo satulö! Be''e mbörö dalingau ba we''aogu andre! Be''e ba dödöu wangandrögu, si oroi mbewe si lö faya.', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 2, 'Yai''otarai mbawau huku andrö khögu; satulö i''ila höröu.[1]', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 3, 'Na ötandraigö dödögu, na öfaigi ba zi bongi, na öhaogö wanekhegö ya''odo, ba lö ösöndra gera-era si lö sökhi ba dödögu bakha, ba lö solalö mbewegu.[2]', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 4, 'Ba wolau niha andrö, ba no utarogö daroma liu, fa böi utörö lala zamakao awönia.', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 5, 'No u''abe''e''ö wanara lahemö, lö sangiwa wemekaigu.', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 6, 'U''angaröfi li ndra''ugö, öfondrondrongo sa ligu, ya''ugö Lowalangi, hatö''ö mbörö dalingau khögu, fondrondrongo wehedegu!', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 7, 'Oroma''ö wa''ebua dödöu andrö, soya ngawalö, ena''ö ahöli-höli dödöma, ya''ugö, sangorifi sanaŵa ya''ugö kambölöu, ba zi fa''udu khöra.[3]', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 8, 'Rorogö ndra''o nifondrorogö ono hörö, bini''ö ndra''o ba lumö gafiu andrö.[4]', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 9, 'Ba zebua horö andrö, samalangögö ya''o, ba zi fatiu tödö khögu, samazui-zui ya''odo.', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 10, 'No laduhö dödöra tawö, ba lalau hokha bewera.', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 11, 'Heza mahundragö danö, ba no lafasui ndra''aga, la''alu-alui wolaugö ya''aga.', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 12, 'Hulö zingo, somasi mondra''u, ba hulö nono zingo ba mbini-mbini.[5]', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 13, 'Faoso Yehowa! hulö ia, timba ia tou! Orifi nosogu, ba zebua horö andrö födamö,', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 14, 'ba niha andrö, ya''ugö Yehowa, tangau, ba niha guli danö andre, so''urakha ba götö da''e, nifo''osiu talu ame''elamö andrö! Ya''ira, ba tenga sambö ono, ba ondröitara khö nonora zi töra khöra.[6]', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476026, 'OT', 'Sinunö', 17, 15, 'Ba ya''odo, ba u''ila mbawau, börö wa''atulö [gu], abuso ndra''o khala-khalamö, na tokea ndra''odo.', '["Sin 43:1","Sin 16:7; 139:1","Sin 4:4","MozV 32:10","Sin 10:9","Luk 16:25; Fil 3:19"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 1, 'Khö duka wanunö andrö. Khö genoni Yehowa andrö, Dawido andrö, sanandrösaigö khö Yehowa taroma li zinunö andre, me no i''efa''ö ia Yehowa ba wa''abölö zi fa''udu khönia, fefu, ba ba danga Zaulo. Imane:[1]', '["SamII 22"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 2, 'Omasido ndra''ugö, Yehowa, fa''abölögu!', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 3, 'Hili dödögu Yehowa ba saŵatögu ba sangorifi ya''o. Lowalangigu, ba no nahiagu, khönia manötöna ndra''o, no balusegu ia ba tandru fangorifi khögu ba hatigu.[2]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 4, 'U''angaröfi li Yehowa, si nangea nisuno andrö, ba te''orifi ndra''o, aefa ndra''o ba zi fatiu tödö khögu.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 5, 'Noa sa ifasui ndra''o dulu ba no ifeta''u ndra''o hohou famunu.[3]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 6, 'No ikabi ndra''o böbö moroi ba mbanua tou, ba no ihawui ndra''o tandraŵa famunu.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 7, 'No mu''ao ndra''o khö Yehowa, ba wa''atosasagu andrö, no u''angaröfi li Lowalangigu, no ifondrondrongo ligu ba gödonia andrö ba no irugi dögi dalingania we''aogu andrö khönia.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 8, 'Ba humeu danö, moduru, ba humisi dayadaya hili ba mangiwa, me no tesao wönunia.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 9, 'Manimbo nikhunia ba i''otarai mbawania alitö si manga badia ia, humola mbo galitö, si oroi khönia.[4]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 10, 'Idada mbanua, möi ia tou, sogömi-gömi barö gahenia.[5]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 11, 'Ba hulu Kerubi möi ia, humombo misa, manahanahae ia ba gafi nangi.[6]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 12, 'Ibali''ö balu-balunia zogömi-gömi, osenia fasui, salu ba lawuo saitö.[7]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 13, 'Moroi ba haga andrö fönania itörö lawuo andrö teu kara ba bo galitö.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 14, 'Ba mu''ugu-ugu Yehowa ba mbanua si yaŵa, ba ifarongogö linia Fondrege zalaŵa andrö.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 15, 'I''efa''ö nono wana khönia, ifazawili, ba ifazaumba gari mbanua, ifakuyu.[8]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 16, 'Ba oroma nungo nidanö ba aheta mbalu-balu dayadaya danö, ba wanegumö andrö, ya''ugö Yehowa, ba wangöhöfu geheha nikhumö andrö.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 17, 'I''oro''ö dangania moroi yaŵa, ira''udo, isöbido moroi ba nidanö sebua.[9]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 18, 'Ifadöni ndra''o ba zi fatiu tödö khögu, sabölö, ba ba zi fa''udu khögu, me no tebai ulaŵa ira.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 19, 'No lahawui ndra''o, me baŵa wa''ate''ala khögu, ba no tobali tolo-tolo khögu Yehowa.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 20, 'Ba no i''ohe baero ndra''o ba zebolo tanö, no i''efa''ö ndra''odo, me no omasi ia ndra''o.[10]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 21, 'No isulöni khögu wa''atulö dödögu Yehowa, no ibe''e khögu zulö, me no lö hadia ia zi falemba ba dangagu.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 22, 'Noa sa utörö lala Yehowa, lö solalö ndra''o ba khö Lowalangigu.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 23, 'Noa sa so ba gametahögu huku andrö khönia, fefu, ba amakhoitania andrö, ba lö ni''aröu''ögu khögu.[11]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 24, 'No adölö dödögu khönia ba no u''ata''ufi, fa böi ufazökhi zi lö atulö.[12]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 25, 'Ba no isulöni khögu wa''atulö dödögu Yehowa, balazi wa lö hadia ia zi falemba ba dangagu, wamaiginia.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 26, 'Ba zebua tödö ebua dödöu, ba ba zadölö tödö adölö dödöu,', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 27, 'Ba zohau-hau ohau-hau ndra''ugö, ba ba zabila tödö abila ndra''ugö.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476027, 'OT', 'Sinunö', 18, 28, 'Ya''ugö sa zanolo niha si göna famakao, ba öhöndrögö hörö si fayaŵa.[13]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 29, 'Ya''ugö sa zamohaga fandrugu, ifohaga zogömi-gömi andrö khögu Yehowa, Lowalangigu.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 30, 'Na ötolodo, ba ududugö göli kara, ba na awögu Lowalangigu, ba usawö mba''a-ba''a.[14]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 31, 'Lala Lowalangi andrö, ba no mo''ahonoa, taroma li Yehowa, ba no muhaogö; baluse ia ba zanötöna khönia, fefu.[15]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 32, 'Ha niha sa Lowalangi, baero Yehowa? ba ha niha nahia saro, baero Lowalangida!', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 33, 'Lowalangi andrö, same''e böbö talugu fa''abölö, sangehao lala khögu;', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 34, 'sombali''ö ahe mböhö ahegu, ba samataro ya''o ba hili.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 35, 'Samahaö tangagu ba wasöndrata ba ta''iogu ba wogai fana.[16]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 36, 'Ba no öbe''e khögu mbaluse fangorifi andrö khöu, ba no ituwu ndra''o kambölöu, ba fangide-ide''öu ya''ugö zangebua''ö ya''odo.[17]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 37, 'No ö''ebolo''ö naha gahegu ba lö sangiwa mbu''u kawonogu.[18]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 38, 'No ugohi nemaligu, ba no ukhamö, ba lö nifuligu ya''o furi, balazi no ufakiko ira.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 39, 'No urasa ira, fa tebai maoso sa''ae, tegaölö tou ira barö gahegu.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 40, 'Ba no öfoböbö talu ndra''o fa''abölö ba wasöndrata, no öfaöndrö barögu zi fa''udu khögu.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 41, 'Moloi khögu zi fatiu tödö khögu, öbe''e, ba si fa''udu khögu, ba no uhori.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 42, 'Mangarö-ngarö ira, ba lö sangorifi — khö Yehowa, ba lö itema lira.[19]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 43, 'Ba no ufufu ira, si mane gawu-gawu nangi; hulö dambu baewali utibo''ö ira.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 44, 'No ö''efa''ö ndra''o ba wasöndrata niha, no öfataro högö soi niha ndra''odo; tobali la''o''ö khögu niha si lö urai mila.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 45, 'Ha larongo ligu, ba la''o''ö khögu, lahaogö-haogö wehedera khögu ono niha bö''ö.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 46, 'Ariri nono niha bö''ö, laröi gödora, manizi-nizi.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 47, 'Sauri Yehowa, ba nisuno nahiagu saro andrö, ba ni''ebua''ö döi Lowalangi fangorifigu andrö!', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 48, 'Lowalangi andrö, sanolo ya''o ba wolau balö, same''e barö mbawagu soi niha;', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 49, 'sangefa''ö ya''o ba nemaligu andrö. Si ndruhu, no öbe''e yaŵa zi fa''udu khögu ndra''odo; no ö''efa''ö ndra''o ba niha andrö samakao awönia.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 50, 'Andrö usuno ndra''ugö, ya''ugö Yehowa, ba niha baero, usuno döimö.[20]', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476027, 'OT', 'Sinunö', 18, 51, 'Ya''ugö, sangebua''ö fangorifi razo, sangebua''ö tödö ba nibayoinimö andrö, khö Dawido ba khö ma''uwunia, irugi zi lö aetu.', '["MozV 32:5","Sin 116:3","MozII 19:18","Sin 144:5","Sin 99:1","Yes 50:3","SamI 7:10","Sin 144:7; 69:2,3","Ayati 37","MozV 17:19","Sin 15:2","Yob 22:29","Sin 60:14","Sin 19:9","Sin 144:1","Amaed 15:33","Sin 31:9","Amaed 1:28","Rom 15:9"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 1, 'Khö duka wanunö andrö. Sinunö khö Dawido.', '[]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 2, 'Idunö-dunö lakhömi Lowalangi andrö banua si yaŵa, ba i''ombakha''ö nifazökhi dangania sebolo andrö.[1]', '["Rom 1:20","Rom 10:18","Sin 104:19"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 3, 'Ifa''ema ba zi ma''ökhö mahemolu si ma''ökhö ma''ökhö, ba si bongi andre, ba i''ombakha''ö ba zi bongi mahemolu.', '["Rom 1:20","Rom 10:18","Sin 104:19"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 4, 'Lö turia ba lö taroma li, si lö terongo li.', '["Rom 1:20","Rom 10:18","Sin 104:19"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 5, 'Fanu''ania andrö, ba irugi ma''afefu danö, ba balö danö irugi linia; luo andrö, ba no ifolose ba khönia.[2]', '["Rom 1:20","Rom 10:18","Sin 104:19"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 6, 'Hulö zangowalu ia, si otarai mbate''enia; somuso tödö ia, hulö zabölö, ba wanörö lalania andrö.', '["Rom 1:20","Rom 10:18","Sin 104:19"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 7, 'Ba wondrege danö i''otarai, ba itöröi, irugi wondrege tanö sa, ba lö hadia ia zi tobini ba wa''aukhunia andrö.[3]', '["Rom 1:20","Rom 10:18","Sin 104:19"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 8, 'Si no mo''ahonoa goroisa Yehowa andrö, fangokafu dödö; si lö mangiwa wamaduhu ö Yehowa andrö, i''atua-tua''ö zambö tödö.[4]', '["Sin 119:50,130","Sin 12:7; 18:31; 119:105","Sin 119:70"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 9, 'Niŵa''ö Yehowa, ba satulö, fangomuso dödö; ba goroisa Yehowa andrö, ba lö hadia ia zi fabaya; famehaga hörö ia.[5]', '["Sin 119:50,130","Sin 12:7; 18:31; 119:105","Sin 119:70"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 10, 'Fangata''ufi Yehowa andrö, ba no ohau-hau, lö mamalö-malö; huku Yehowa, ba si duhu, atulö, ma''afefu.', '["Sin 119:50,130","Sin 12:7; 18:31; 119:105","Sin 119:70"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 11, 'Somasi ita, moroi ba gana''a, moroi na oya mbalaki: ba ami, moroi ba ŵe ŵani ba moroi ba nösi gawa''awa andrö.[6]', '["Sin 119:50,130","Sin 12:7; 18:31; 119:105","Sin 119:70"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 12, 'Ba tefarou göi dödö genoniu khönia; luo sebua isöndra, na i''o''ö.', '["Sin 119:50,130","Sin 12:7; 18:31; 119:105","Sin 119:70"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 13, 'Olalöŵa andrö, ba ha niha zaboto ba dödö ha me uga? heta khögu zi tobini andrö![7]', '["Yob 9:3; Sin 130:3","Sin 18:24"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 14, 'Timba khö genonimö zi fayaŵa: böi tehe, ya''ira zamatörö ya''o! Ba lö sinegu khögu, ba lö falemba khögu golalöŵa sebua.[8]', '["Yob 9:3; Sin 130:3","Sin 18:24"]', NULL),
  (3476029, 'OT', 'Sinunö', 19, 15, 'Ena''ö na omasi ndra''ugö wehede mbewegu, awö gera-era dödögu andrö, ya''ugö Yehowa, nahiagu saro ba sangorifi ya''odo!', '["Yob 9:3; Sin 130:3","Sin 18:24"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 1, 'Khö duka wanunö andrö. Sinunö khö Dawido.', '[]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 2, 'Yamufondrondrongo liu Yehowa, na baŵa wamakao; yamöi ba''a-ba''a khöu döi Lowalangi Yakobo andrö![1]', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 3, 'Yamufa''ohe''ö khöu wangorifi, moroi ba ni''amoni''ö andrö, yamutolo''ö moroi ba Ziona!', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 4, 'Yamutörö tödönia zumange ni''a andrö khöu, fefu, ba yamutema zumange nitunu andrö, nibe''eu!', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 5, 'Yamube''e khöu zomasi dödöu ba yamufo''ungo fefu nifakhoi dödöu.[2]', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 6, 'Ena''ö na omuso dödöma ba wanolo andrö nisöndrau, ba ena''ö na mataŵi mandrera ba döi Lowalangida andrö. Yamube''e khöu Yehowa ni''andröu fefu!', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 7, 'Awena u''ila, wa itolo nibayoininia andrö Yehowa; ifondrondrongo khönia, moroi ba zorugo andrö khönia, ni''amoni''ö, ba wa''abölönia ba ba wanolo gambölönia andrö.[3]', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 8, 'Ya''ira, ba sanötöna ba gureta ba ba kudo, ba ya''ita, ba ta''angaröfi li döi Lowalangida andrö.[4]', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 9, 'Ya''ira, ba salau ba si tegaölö tou, ba ya''ita, ba ta''adölö''ö huluda, muzizio manö.', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476030, 'OT', 'Sinunö', 20, 10, 'He Yehowa, tolo razo ba fondrondrongo lima, na mu''ao ndra''aga!', '["Amaed 18:10","Sin 21:3","MozII 15:6","MozV 20:1; Yes 31:1"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 1, 'Khö duka wanunö andrö. Sinunö khö Dawido.', '[]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 2, 'He Yehowa! Ba wa''abölömö andrö omuso dödö razo, ba owua-wua sibai dödönia ba wanolou andrö.', '["Sin 20:5; 37:4","Sin 132:18"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 3, 'Somasi dödönia, ba no öbe''e khönia, ba ni''andrö mbewenia, ba no ö''o''ö.[1]', '["Sin 20:5; 37:4","Sin 132:18"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 4, 'Noa sa öfaondragö ia, wame''e howu-howu, awö zi sökhi, no öfanaembu ia saembu balaki.[2]', '["Sin 20:5; 37:4","Sin 132:18"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 5, 'Fangorifi no i''andrö khöu, ba no öbe''e khönia, fa''anau noso, si lö mamalö-malö, si lö aetu.', '["Sin 20:5; 37:4","Sin 132:18"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 6, 'Ebua duriania ba wanolomö andrö; no ö''ebua''ö döinia ba no öfolakhömi ia.', '["Sin 20:5; 37:4","Sin 132:18"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 7, 'Noa sa öfataro ia famahowu, si lö aetu, no ö''omusoi''ö dödönia tanö fönau.', '["Sin 20:5; 37:4","Sin 132:18"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 8, 'Khö Yehowa sa''ae manötöna razo, ba lö mangiwa ia ibe''e fa''ebua dödö Wondrege zalaŵa andrö.', '["Sin 20:5; 37:4","Sin 132:18"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 9, 'Ikhamö tangau zi fa''udu khöu fefu, ikhamö kambölöu zi fatiu tödö khöu.[3]', '["SamII 12:26–30","Sin 109:13","Yes 8:10","Sin 7:13"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 10, 'Öbali''ö dania baho galitö ira, na so''ö; ihori ira Yehowa ba wönunia andrö, ba i''a ira alitö.', '["SamII 12:26–30","Sin 109:13","Yes 8:10","Sin 7:13"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 11, 'Madoura öhori ba danö, ba ma''uwura, ba öhori ba nono niha.[4]', '["SamII 12:26–30","Sin 109:13","Yes 8:10","Sin 7:13"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 12, 'Lakhoi tödöra zi lö sökhi, fa''udusa khöu, lafakhai horö, ba lö mo''ungo.[5]', '["SamII 12:26–30","Sin 109:13","Yes 8:10","Sin 7:13"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 13, 'Moloi sa ira öbe''e, öfaudugö mbawara fanamö andrö.[6]', '["SamII 12:26–30","Sin 109:13","Yes 8:10","Sin 7:13"]', NULL),
  (3476031, 'OT', 'Sinunö', 21, 14, 'Faoso Yehowa, ba wa''abölömö andrö! ba manunö ndra''aga, masuno wa''abölöu.', '["SamII 12:26–30","Sin 109:13","Yes 8:10","Sin 7:13"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 1, 'Khö duka wanunö andrö. Dali: "Böhö si alawe, na moluo." Sinunö khö Dawido.', '[]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 2, 'He Lowalangigu! He Lowalangigu! Hana wa no ö''erogö ndra''o? No aröu ndra''ugö, ba wangorifi ya''o ena''ö ba ba wamondrongo ligu, fangarö-ngarögu andre.[1]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 3, 'He Lowalangigu! Mu''ao ndra''o, na ma''ökhö, ba lö ötema ligu, ba ba zi bongi, ba lö falukha wondrara dödö.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 4, 'Ba ni''amoni''ö sa atö ndra''ugö, sidadao yaŵa wanunö Ndraono Gizeraeli andrö.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 5, 'Khöu manötöna ndra tuama föna, ladöna-döna, ba no ö''orifi ira.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 6, 'Ya''ugö la''angaröfi li, ba lasöndra wangorifi; khöu ladöna-döna, ba lö si te''ailaisi ira.[2]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 7, 'Ba ya''odo, ba no kukuö ba tenga niha; fama''iki niha ndra''odo ba si lö ba dödö zato![3]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 8, 'La''o''aya ndra''o dozi sangila ya''odo, labobo mbawara ba lafalikhö ira.[4]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 9, '"Be''e balazi Yehowa! Yamu''orifi ia, yamu''efa''ö; i''omasi''ö sa atö ia."', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 10, 'Ya''ia, ya''ugö zanöbi ya''odo mege moroi ba dalu ninagu, ba lö sabu dödögu, ba mbalö meme ninagu, öbe''e.[5]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 11, 'Ya''ugö dötönafögu, i''otarai dalu ninagu; i''otarai ba gaheta ninagu, ba Lowalangigu ndra''ugö.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 12, 'Böi aröu''ögö khögu, me no ahatö wa''atosasa, lö''ö sa sangorifi.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 13, 'Oya zamasui ya''o öröbao, lafa''u''u ndra''o si matua göröbao Mbazana andrö.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 14, 'Lafaboka mbawara khögu, hulö si mane singo, si manga niha, si ndröndröndröndrö.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 15, 'No tefaduwa ndra''o, hulö nidanö, ba no ahori faefa mbu''ugu; no tobali hulö zigu-sigu dödögu, no mangulu barö dotogu.[6]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 16, 'No oköli gararogu, hulö duga lawu, falemba lelagu ba dölö-tölögu ba öbali''ö oboula zi mate ndra''odo.[7]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 17, 'Noa sa lafasui ndra''o asu, lafa''u''u ndra''o sebua horö, no owulo; no latöla''ö dangagu awö gahegu.[8]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 18, 'U''ila u''erai dölagu fefu. Lafaigi-faigi, latöngötöngö ndra''o, fa''omasira.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 19, 'Lafaosa khöra nukhagu ba fadahö-dahö ba gamezagu.[9]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 20, 'Ba ya''ugö, Yehowa, ba böi aröu''ögö! ya''ugö fa''abölögu, ta''i-ta''i tolodo!', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 21, 'Efa''ö ndra''o ba mbawa zi''öli andrö, nosogu, si ha sambu-sambua andrö, efa''ö ba nasu.[10]', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 22, 'Fasöbido ba mbawa zingo! Noa sa öfondrondrongo ligu, ba dandru göröbao andrö.', '["Mat 27:46","Sin 25:2,3","Sin 69:8; Yes 53:3; Mat 27:39–44","Yob 16:4,10","Sin 71:6","Luk 22:44","Yoh 19:28","Yoh 20:25,27","Yoh 19:24","Sin 35:17"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 23, 'Edöna u''ombakha''ö döimö ba dalifusögu, ba hunö zowulo niha usuno ndra''ugö.[11]', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 24, 'Ya''ami sangata''ufi Yehowa, misuno ia! Ya''ami, madou Yakobo, mifosumange ia, ba mi''ata''ufi ia, ya''ami ma''uwu Gizeraeli fefu.', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 25, 'Tenga sa fa lö ba dödönia wamakao zi göna famakao andrö ba lö ni''ogorofinia; ba me no mangarö-ngarö khönia, ba no ifondrondrongo.[12]', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 26, 'Börö ndra''ugö, wa manunö ndra''o ba gowuloa sebua; ubu''a nifabu''ugu tanö föna zangata''ufi ya''ia.', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 27, 'Falukha manga zi göna famakao andrö ba abuso; lasuno dania Yehowa sangalui ya''ia; ya auri dödömi, si lö aetu![13]', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 28, 'Lasöndra tödöra balö danö fefu ba mangawuli khö Yehowa; ba fönamö latuhi danö fefu soi niha baero.', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 29, 'Khö Yehowa sa wa''asalaŵa ba ya''ia zamatörö soi niha.', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 30, 'Ha fönania lalaugö tou ira ba danö dozi satabö ba guli danö andre; fönania lafaöndrö ira dozi sanaŵa tanö andrö tou, ba ha niha si lö mangila mangorifi nosonia.[14]', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 31, 'Ma''uwu da''ö zi möi enoninia dania. Ladunö-dunö Zo''aya ba niha dania.[15]', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476032, 'OT', 'Sinunö', 22, 32, 'La''ombakha''ö wa''atulö dödönia ba niha si tumbu mitou, wa no ifolua-lua.[16]', '["Sin 9:15; Heb 2:12; Yoh 20:17","Sin 9:13; Heb 5:7","Sin 69:23","Faigi 2:10","Yes 53:10","Sin 110:3; Yoh 19:30"]', NULL),
  (3476033, 'OT', 'Sinunö', 23, 1, 'Yehowa gubalogu, lö ambö ndra''o hadia ia.[1]', '["MozI 48:15; Yoh 10:12–16","Hez 34:14; Fam 7:17","Yer 31:25","Sin 46:3","Sin 36:9","Sin 84:4,5"]', NULL),
  (3476033, 'OT', 'Sinunö', 23, 2, 'Ibe''e molombase ndra''o, ba zodu''u sauri, ba i''ohe ndra''o ba zinga nidanö sahono-hono ndra''odo.[2]', '["MozI 48:15; Yoh 10:12–16","Hez 34:14; Fam 7:17","Yer 31:25","Sin 46:3","Sin 36:9","Sin 84:4,5"]', NULL),
  (3476033, 'OT', 'Sinunö', 23, 3, 'I''okafui dödögu; ifatörö ndra''o ba lala satulö, börö döinia andrö.[3]', '["MozI 48:15; Yoh 10:12–16","Hez 34:14; Fam 7:17","Yer 31:25","Sin 46:3","Sin 36:9","Sin 84:4,5"]', NULL),
  (3476033, 'OT', 'Sinunö', 23, 4, 'Ba he utörö mbawa danö andrö, si göna lumö wa''amate andrö, ba lö ata''udo zi lö sökhi; awögu sa ndra''ugö; si''ou andrö ba we''e-we''e andrö khöu, da''ö wondrara dödögu.[4]', '["MozI 48:15; Yoh 10:12–16","Hez 34:14; Fam 7:17","Yer 31:25","Sin 46:3","Sin 36:9","Sin 84:4,5"]', NULL),
  (3476033, 'OT', 'Sinunö', 23, 5, 'Öfa''oli gögu fönagu, fametahö zi fa''udu khögu; öbayoini fanikha högögu, öfo''ösi khögu mako, öfönui.[5]', '["MozI 48:15; Yoh 10:12–16","Hez 34:14; Fam 7:17","Yer 31:25","Sin 46:3","Sin 36:9","Sin 84:4,5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476033, 'OT', 'Sinunö', 23, 6, 'Ha sambalö si sökhi ba fa''ebua dödö zolo''ö-lo''ö ya''odo, sagötö ya''o; ba si lö tebulö ba nomo Yehowa ndra''odo, sagötö fa''ara.[6]', '["MozI 48:15; Yoh 10:12–16","Hez 34:14; Fam 7:17","Yer 31:25","Sin 46:3","Sin 36:9","Sin 84:4,5"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 1, 'Khö Yehowa danö, awö nösinia, uli danö andrö, awö zowanua ba detenia.[2]', '["Sin 50:12; KorI 10:26","MozI 1:9,10","Sin 15","Yes 48:18","Rom 2:28,29"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 2, 'Me no ya''ia zolata, yaŵa nasi, sanga''aro''ö ya''ia yaŵa hohou andrö.[3]', '["Sin 50:12; KorI 10:26","MozI 1:9,10","Sin 15","Yes 48:18","Rom 2:28,29"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 3, 'Ha niha zi tola möi yaŵa ba hili Yehowa andrö, ba ha niha zi tola mangiagö naha ni''amoni''ö andrö khönia?[4]', '["Sin 50:12; KorI 10:26","MozI 1:9,10","Sin 15","Yes 48:18","Rom 2:28,29"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 4, 'Si lö hadia ia zi falemba ba danga ba sohau-hau tödö; si lö mangalui falimosa ba si lö möi ba hölu, na faya.', '["Sin 50:12; KorI 10:26","MozI 1:9,10","Sin 15","Yes 48:18","Rom 2:28,29"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 5, 'Da''ö zanema howu-howu khö Yehowa, ba fa''atulö khö Lowalangi andrö, sangorifi ya''ia.[5]', '["Sin 50:12; KorI 10:26","MozI 1:9,10","Sin 15","Yes 48:18","Rom 2:28,29"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 6, 'Da''ö niha andrö, sanofu-nofu ya''ia, sangalui fangila bawau, ya''ugö Lowalangi Yakobo andrö.[6]', '["Sin 50:12; KorI 10:26","MozI 1:9,10","Sin 15","Yes 48:18","Rom 2:28,29"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 7, 'Mifazaŵa ami, ya''ami bawa göli! Mi''alaŵa ö ami, ya''ami bawandruhö si no arara, ena''ö itörö razo andrö, solakhömi![7]', '["Yes 40:3,4"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 8, 'Ha niha razo andrö, solakhömi? Yehowa andrö, sabe''e ba sabölö! Yehowa, sabölö ba wasöndrata.', '["Yes 40:3,4"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 9, 'Mifazaŵa ami, ya''ami bawa göli! Mi''alaŵa''ö ami, ya''ami bawandruhö si no arara andrö, ena''ö itörö razo andrö, solakhömi!', '["Yes 40:3,4"]', NULL),
  (3476034, 'OT', 'Sinunö', 24, 10, 'Ba ha niha atö razo andrö, solakhömi? Yehowa zato andrö, da''ö razo andrö, solakhömi.', '["Yes 40:3,4"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 1, 'Khöu, Yehowa, ufazaŵa dödögu.', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 2, 'Khöu udöna-döna, ya''ugö Lowalangigu! böi be''e aila ndra''o, böi tehe khö zi fatiu tödö khögu, la''igi''igi''ö ndra''odo!', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 3, 'Dozi sa atö sanötöna khöu, ba lö''ö manö falukha aila; ba aila dania zi faröi lö börö.[1]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 4, 'He Yehowa, tuturu khögu lala andrö khömö, fahaö ndra''o ba zinörö andrö khöu.[2]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 5, 'Tolodo, ena''ö utörö zi duhu andrö khöu, ba fahaö ndra''o; ya''ugö sa Lowalangi andrö, sangorifi ya''odo; khöu udöna-döna, lö mamalö-malö.', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 6, 'Törö tödöu wa''ahakhö dödöu andrö, ya''ugö Yehowa, ba fa''ebua dödöu andrö; moroi ba zi lö böröta sa ia.', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 7, 'Böi angeragö horögu me ono matua ndra''odo ba he lalögu andrö; törö tödöu ndra''odo, dali wa''ebua dödöu andrö, börö wa''asökhi dödöu, ya''ugö Yehowa![3]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 8, 'Sebua tödö ba sadölö tödö Yehowa, andrö i''ombakha''ö lala ba zi so horö andrö.', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 9, 'Ba lala satulö ifatörö zi numana ba ifahaö zi numana ba lala andrö khönia.', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 10, 'Lala Yehowa andrö fefu, ba ha sambalö fa''ebua dödö ba fa''aduhu, khöra si lö mamöhöi fawu''usa li andrö ba famaduhu''ö andrö khönia.', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 11, 'Be''e börö döimö andrö, ya''ugö Yehowa, wangefa''ö horögu; no ebua sa''ae!', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 12, 'Ba ha niha zangata''ufi Yehowa? Ifahaö dania ia ba lala andrö, nitörönia.[4]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 13, 'Sohahau tödö dania zi manö, ba ma''uwunia zokhö tanö.[5]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 14, 'Khö zangata''ufi ya''ia fahuwu Yehowa, ba ifarongogö khöra nifakhoinia andrö.[6]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 15, 'Lö aefa-aefa hörögu khö Yehowa; i''efa''ö sa gahegu ba gu''ö andrö.', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 16, 'Otahögö ndra''o ba ebua''ö dödöu khögu! noa sa aomö-aomö ndra''o ba si numana!', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 17, 'No fahöna wa''abu dödögu; efa''ö ndra''o ba wa''atosasagu andrö!', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 18, 'Faigi wa''anumanagu ba fa''abu dödögu andrö, ba be''e aefa khögu horögu fefu.', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 19, 'Nehegö zi fatiu tödö khögu, me no ato; ba me si lö atulö watiusara khögu.[7]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 20, 'Rorogö nosogu ba orifi ndra''o, böi be''e aila ndra''o, me udöna-döna khöu.[8]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 21, 'Yamutolo ndra''o fa lö horö ba fa''adölö dödö! Udöna-döna sa khöu.[9]', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476035, 'OT', 'Sinunö', 25, 22, 'He Lowalangi! Efa''ö Ndraono Gizeraeli ba wa''abu dödöra fefu!', '["Yes 49:23","Sin 27:11","Yob 13:26","Sin 32:8","Sin 37:9","Yob 29:4","Sin 35:19","Sin 16:1","Yob 1:1"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 1, 'Huku ndra''o Yehowa, noa sa utörö lalagu, lö horö; no manötöna ndra''o khö Yehowa, lö sangiwa ndra''odo.', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 2, 'Sekhegö ndra''o Yehowa ba tandraigödo, haogö mbuagu ba tödögu.[1]', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 3, 'Utöngötöngöni wa''ebua dödöu andrö, ba no utörö zi duhu andrö khöu.', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 4, 'Lö si dadaodo awö niha sofaya ba lö si fao-fao ndra''o ba zi falimo.[2]', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 5, 'Fatuwu khögu gowuloa zamazökhi si lö sökhi, ba lö si dadao ndra''o awö zebua hörö.', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 6, 'Uhalö fanasa dangagu wa lö horö, ba da ufazui-zui naha wame''e sumange andrö khöu, ya''ugö Yehowa.[3]', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 7, 'Ba wamarongogö taroma li wangandrö saoha gölö ba ba wanutunö sahöli-höli dödö andrö khöu, fefu.', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 8, 'He Yehowa, omasido nahiau omo andrö, nahia lakhömiu.[4]', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 9, 'Böi halö nosogu, awö zamazökhi horö, böi bunudo, awö zange''enge''e andrö,', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 10, 'si falemba horö ba danga, si no mo''ösi ö horö danga kambölö.', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 11, 'Ba ya''o, ba utörö lalagu, lö horö. Orifi ndra''o ba ebua''ö dödöu khögu!', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476036, 'OT', 'Sinunö', 26, 12, 'Ba lala sadölö manandrösa gahegu: Usuno Yehowa ba zowulo niha.[5]', '["Sin 17:3","Sin 1:1","Sin 122","Sin 27:4","Sin 22:23"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 1, 'Haga khögu Yehowa ba fangorifi, ha niha zata''u ndra''o? ba''a-ba''a khögu ba nosogu Yehowa, ha niha zi tokea ndra''o?[1]', '["Sin 56:5; Yes 12:2","Yob 19:22","Sin 3:7"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 2, 'Na lahatö''ö ira khögu sanao horö, ba wemanga ösigu — si fa''udu khögu ba si fatiu tödö — ba manendre ira ba alau.[2]', '["Sin 56:5; Yes 12:2","Yob 19:22","Sin 3:7"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 3, 'Na latarogö ndra''o sanuwö, ba lö ata''u dödögu; na tesuwö ndra''o, ba lö abu dödögu.[3]', '["Sin 56:5; Yes 12:2","Yob 19:22","Sin 3:7"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 4, 'Sambalö u''andrö khö Yehowa, da''ö zihulu dodögu: ena''ö monahia ndra''o ba nomo Yehowa andrö, götö wa''anau nosogu, ba wamaigi fa''asökhi Yehowa andrö ba ba wangomusoi''ö tödögu ba gosalinia.[4]', '["Sin 23:6; 26:6–8; 42:5; 63:3; 84:4,5","Sin 31:21; 40:3"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 5, 'Ifonaha sa''ae ndra''o baose, na baŵa wamunu, ibini''ö ndra''o ba mbini-mbini ba nosenia andrö; i''alaŵa''ö yaŵa ndra''o ba dete gowe.[5]', '["Sin 23:6; 26:6–8; 42:5; 63:3; 84:4,5","Sin 31:21; 40:3"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 6, 'Ba tefaöga mbawagu yaŵa zi fa''udu khögu, si tefasui ya''o, ba sumange nilau torofe ube''e ba nosenia, manunö ndra''o khö Yehowa ba ulau mbiola.', '["Sin 23:6; 26:6–8; 42:5; 63:3; 84:4,5","Sin 31:21; 40:3"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 7, 'Fondrondrongo Yehowa, mu''ao ndra''odo! Ba ebua''ö dödöu khögu ba tema ligu!', '["MozV 4:29","Yes 49:15","Sin 25:4; 86:11; 139:24","Sin 142:6; Yes 38:11"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 8, 'Iŵa''ö tödögu, khöu i''otarai taroma li andrö: "Mi''alui mbawagu!" — Bawau andrö, Yehowa, u''alui.[6]', '["MozV 4:29","Yes 49:15","Sin 25:4; 86:11; 139:24","Sin 142:6; Yes 38:11"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 9, 'Böi bini''ö khögu mbawau; böi timba genonimö andre, ba wönumö. No sanolo ya''o ndra''ugö, böi tibo''ö ndra''o ba böi röido, ya''ugö Lowalangi fangorifigu!', '["MozV 4:29","Yes 49:15","Sin 25:4; 86:11; 139:24","Sin 142:6; Yes 38:11"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 10, 'Noa sa laröi ndra''o ira amagu inagu, ba ifonaha ndra''o Yehowa.[7]', '["MozV 4:29","Yes 49:15","Sin 25:4; 86:11; 139:24","Sin 142:6; Yes 38:11"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 11, 'Fahaö ndra''o Yehowa, ba lala andrö khöu ba fatörödo ba lala sadölö, börö zi fa''udu khögu andrö.[8]', '["MozV 4:29","Yes 49:15","Sin 25:4; 86:11; 139:24","Sin 142:6; Yes 38:11"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 12, 'Böi lulu ndra''o ba wofönu zamakao ya''o! Noa sa maoso khögu sasi sofaya ba sangalui famunu.', '["MozV 4:29","Yes 49:15","Sin 25:4; 86:11; 139:24","Sin 142:6; Yes 38:11"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 13, 'Na lö faduhu dödögu ena''ö, u''ila dania wa''ebua dödö Yehowa andrö, ba danö zauri andrö![9]', '["MozV 4:29","Yes 49:15","Sin 25:4; 86:11; 139:24","Sin 142:6; Yes 38:11"]', NULL),
  (3476037, 'OT', 'Sinunö', 27, 14, 'Döna-döna khö Yehowa! Abe''e''ö ndra''ugö ba böi busi dödöu, ba döna-döna khö Yehowa!', '["MozV 4:29","Yes 49:15","Sin 25:4; 86:11; 139:24","Sin 142:6; Yes 38:11"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 1, 'Khöu, Yehowa, mu''ao ndra''o; böi zi lö ötema li, ya''ugö we''e-we''e dödögu, fa böi fagölö-gölö ndra''o ba zilalö ba gohokoho, na lö hede-hedeu.[1]', '["Sin 143:7","RazI 8:30; Ngenu 3:41","Sin 29:9","Yes 5:12"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 2, 'Fondrondrongo li wangandrögu andrö, na mu''aodo khöu, na ufazaŵa dangagu ba ni''amoni''ö sibai andrö khöu![2]', '["Sin 143:7","RazI 8:30; Ngenu 3:41","Sin 29:9","Yes 5:12"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 3, 'Böi fakiko ndra''o awö zebua horö ba awö zamazökhi si lö sökhi, sangehaogö fehede ba nawöra, lö lai wa so ba dödöra zi lö sökhi.[3]', '["Sin 143:7","RazI 8:30; Ngenu 3:41","Sin 29:9","Yes 5:12"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 4, 'Sulöni khöra wolaura ba falösökhi nifazökhira andrö; be''e luora ba nifazökhi dangara ba be''e zulö nilaura khö nawöra.', '["Sin 143:7","RazI 8:30; Ngenu 3:41","Sin 29:9","Yes 5:12"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 5, 'Lö''ö sa ba dödöra nilau Yehowa andrö, ba he nifazökhi dangania. Ifakiko dania ira ba lö ifuli i''azökhi.[4]', '["Sin 143:7","RazI 8:30; Ngenu 3:41","Sin 29:9","Yes 5:12"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 6, 'Nisuno Yehowa; noa sa ifondrondrongo li wangandrögu andrö.', '["Sin 18:2"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 7, 'Ba''a-ba''agu Yehowa ba balusegu; khönia manötöna dödögu ba no te''orifi ndra''odo; andrö owua-wua dödögu, ba usuno ia sinunögu andrö.[5]', '["Sin 18:2"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 8, 'Yehowa wangabe''e mbanuania, ya''ia mba''a-ba''a fangorifi ba nibayoininia andrö.', '["Sin 18:2"]', NULL),
  (3476038, 'OT', 'Sinunö', 28, 9, 'Orifi mbanuau ba fahowu''ö dana khöu; ba kubaloi ira, ba taya tangau, irugi zi lö aetu.', '["Sin 18:2"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 1, 'Mibe''e khö Yehowa, ya''ami ono zabölö, mibe''e khö Yehowa lakhömi ba fa''abölö![1]', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 2, 'Mibe''e khö Yehowa lakhömi döinia andrö! Mi''angalulu khö Yehowa, ba wa''amoadu andrö, ni''amoni''ö![2]', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 3, 'Yaŵa nidanö terongo li Yehowa andrö; mu''ugu-ugu Lowalangi lakhömi andrö, Yehowa yaŵa nidanö sebua.[3]', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 4, 'Li Yehowa andrö, ba sabölö, li Yehowa andrö, ba sihöngö.', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 5, 'Ifatö geresi li Yehowa andrö, ifatö Yehowa geresi andrö ba hili Libano.', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 6, 'Manoka ira, hulö nono zawi, ibe''e, Libano andrö ba Siriono andrö, hulö nono göröbao.[4]', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 7, 'Ifazawili hola-hola galitö li Yehowa andrö.', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 8, 'Moduru danö si mate ibe''e li Yehowa andrö, ifahisi danö si mate Kadesi andrö Yehowa.', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 9, 'Afökhö hulu mböhö si alawe ibe''e li Yehowa andrö, ba iserei geu ba gatua, ba ba gosalinia, ba ha sambua li: lakhömi!', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 10, 'Yaŵa nidanö sebua dumadao mege Yehowa, ba fedadao Yehowa andrö, ba no fedadao razo, sirugi si lö aetu.', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476039, 'OT', 'Sinunö', 29, 11, 'Ibe''e wa''abölö ba mbanuania Yehowa, ifahowu''ö mbanuania Yehowa, fa''atulö.[5]', '["Sin 89:7; 103:20","Sin 110:3","Yob 37:2","MozV 3:8,9","Sin 28:8,9"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 1, 'Sinunö. Ba we''amoni''ö omo; khö Dawido.', '[]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 2, 'Da''usuno döimö Yehowa, me no ö''efa''ö ndra''o ba me lö niteheu omuso dödö zi fa''udu khögu, ba khögu andre.[1]', '["Sin 35:19,24","Sin 116:3,4","Yes 54:7"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 3, 'He Yehowa, Lowalangigu! Khöu mu''ao ndra''odo mege, ba no ö''orifi ndra''odo.', '["Sin 35:19,24","Sin 116:3,4","Yes 54:7"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 4, 'He Yehowa! No ö''ohe yaŵa nosogu moroi ba mbanua tou; no öfuli ö''orifi ndra''o, moroi ba ngai zi no mulalö mitou ba gohokoho.[2]', '["Sin 35:19,24","Sin 116:3,4","Yes 54:7"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 5, 'Misuno Yehowa, ya''ami satulö tödö andrö khönia! Mi''andrö saoha gölö ba döinia andrö, ni''amoni''ö!', '["Sin 35:19,24","Sin 116:3,4","Yes 54:7"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 6, 'Ha sa mamö''i hörö wa''ara wönunia, ba sagötö niha wa''ebua dödönia; ba zi bongi so wege-ege, ba irege mahemolu mbanua, ba fa''iki.[3]', '["Sin 35:19,24","Sin 116:3,4","Yes 54:7"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 7, 'Noa sa umane, me sohahau tödö ndra''odo: "Lö mangiwa ndra''o, irugi zi lö aetu."', '["Sin 6:6","Yoh 16:20","Sin 16:9"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 8, 'He Yehowa! ba wa''ebua dödöu andrö öfataro mege ndra''odo ba hili si lö mangiwa: ba öbini''ö mbawau, ba si tokea ndra''odo.', '["Sin 6:6","Yoh 16:20","Sin 16:9"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 9, 'Khöu Yehowa mu''ao ndra''o, no u''angaröfi li Yehowa, umane:', '["Sin 6:6","Yoh 16:20","Sin 16:9"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 10, '"Hadia hareu ba ndrogu andrö, na numalö ndra''o ba gohokoho? Hadia, i''ila isuno ndra''ugö gawu-gawu? Hadia, i''ombakha''ö wa si lö faröi ndra''ugö?"[4]', '["Sin 6:6","Yoh 16:20","Sin 16:9"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 11, 'Fondrondrongo Yehowa ba hakhösi tödö ndra''odo! He Yehowa, orifi ndra''odo!', '["Sin 6:6","Yoh 16:20","Sin 16:9"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 12, 'No öbali''ö fanunö wangarö-ngarögu andrö; no öheta khögu nukha ba wange''esi andrö ba no öfolembe ndra''odo fa''omuso dödö.[5]', '["Sin 6:6","Yoh 16:20","Sin 16:9"]', NULL),
  (3476040, 'OT', 'Sinunö', 30, 13, 'Ena''ö isuno ndra''ugö tödögu, ena''ö lö ibato. He Yehowa, Lowalangigu, usuno ndra''ugö, si lö mamalö-malö![6]', '["Sin 6:6","Yoh 16:20","Sin 16:9"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 1, 'Khö duka wanunö andrö Sinunö khö Dawido.', '[]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 2, 'Khöu Yehowa, manötöna ndra''odo, böi manö be''e aila ndra''o; orifi ndra''o, ba wa''atulö dödöu andrö!', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 3, 'Fondrondrongo khögu, ta''i-ta''i orifi ndra''odo! Ena''ö gowe saŵatö ndra''ugö khögu, ba hati saro, ba wangorifi ya''odo![1]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 4, 'Gowe sa ndra''ugö khögu ba hatigu, ba öfasao ndra''o, ö''ohe dangagu, börö döimö andrö.[2]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 5, 'Ö''efa''ö ndra''o ba gu''ö andrö, nilaura khögu, nibini''ö; ba''a-ba''a sa ndra''ugö khögu.[3]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 6, 'Ba dangau utou''ö nosogu; ö''orifi ndra''o, ya''ugö Yehowa, Lowalangi si lö faröi![4]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 7, 'Fa''udu ndra''ugö ba zi olembai adu faya andrö, ba ya''odo, ba sanötöna khö Yehowa.', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 8, 'Ena''ö ma''iki ndra''o ba ena''ö omuso dödögu, ba wa''ebua dödöu andrö, wa no onehegö wa''anumanagu andrö, wa no öbe''e ba dödöu wa''atosasa dödögu.', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476041, 'OT', 'Sinunö', 31, 9, 'Lö nilulumö ya''o ba wa''abölö zi fatiu tödö khögu, no öfonaha gahegu ba zebolo tanö.[5]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 10, 'Hakhösi tödö ndra''o, ya''ugö Yehowa, sata''u tödö sa ndra''odo! Aokö hörögu ba wa''abu dödö andrö, ariri nosogu ba ösigu.[6]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 11, 'Sagötö ya''o sa''ae, ba fa''alangu dödö, ha me uga fakhe ndra''o, ba fangarö-ngarö manö. Taya wa''abölögu, börö horögu, ba no alö dölaga, börö zamakao ya''o andrö fefu.', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 12, 'No tobali ni''o''aya sibai ndra''odo ba nawögu ba fameta''u ba zi fa''ila li khögu; si falukha khögu baewali, ba moloi.[7]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 13, 'No olifu niha bö''ö ndra''odo, no taya ndra''o ba dödöra; no tobali hulö mbowoa saboto ndra''odo.', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 14, 'Noa sa urongo wanandraŵaisi zato: "Ameta''uö, fasui!" Mamagölö ira ba khögu andre, wangalui famunu ya''odo.[8]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 15, 'Ba ya''odo, ba sanötöna khöu, ya''ugö Yehowa; no umane: "Lowalangigu ndra''ugö!"', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 16, 'Ba dangau so lalagu andrö. Efa''ö ndra''o ba danga zi fa''udu khögu ba ba zolohi ya''odo![9]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 17, 'Fohaga mbawau yaŵa genoniu, orifi ndra''o, ba wa''ebua dödöu andrö.[10]', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 18, 'He Yehowa, böi be''e aila ndra''o! noa sa u''angaröfi li ndra''ugö. Ena''ö aila zebua horö andrö, ena''ö lö hede-hedera sa''ae, ba mbanua tou.', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 19, 'Ena''ö lö''ö sa''ae hede-hede mbewe sofaya andrö, sangosiwawöi satulö, ba hokhara andrö ba ba wa lö ba dödö.', '["Sin 18:3","Sin 23:3","Sin 25:15","Luk 23:46","Sin 18:37","Sin 6:8","Sin 69:11–13","Yer 20:10; 46:5","Sin 139:16","MozIV 6:25; Sin 80:4"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 20, 'Ha lö abölö wa''ebua dödöu andrö, nitenagöu ba zangata''ufi ya''ugö; ni''oroma''öu, ba zanehe niha, ba zanötöna khöu andrö.', '["Sin 27:5","Sin 17:7","Sin 116:11","Sin 27:14"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 21, 'Öba''a ira ba''a-ba''a bawau andrö, na aekhu niha, öbini''ö ira baose, ba wasosota lela andrö.[11]', '["Sin 27:5","Sin 17:7","Sin 116:11","Sin 27:14"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 22, 'Nisuno Yehowa, me no i''oroma''ö khögu wa''ebua dödönia andrö, sahöli-höli dödö, ba mbanua saro.[12]', '["Sin 27:5","Sin 17:7","Sin 116:11","Sin 27:14"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 23, 'Ba ya''o, ba umane, ba wa''atobali dödögu andrö: "No toba''a ndra''o ba höröu." Ba no öfondrondrongo zui li wangandrögu andrö, me mu''aodo khöu.[13]', '["Sin 27:5","Sin 17:7","Sin 116:11","Sin 27:14"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 24, 'Mi''omasi''ö Yehowa, ya''ami, satulö tödö andrö khönia, dozi! Irorogö Yehowa zi lö faröi andrö ba lö i''ambösi zulö ba zama''ua fayaŵasa.', '["Sin 27:5","Sin 17:7","Sin 116:11","Sin 27:14"]', NULL),
  (3476041, 'OT', 'Sinunö', 31, 25, 'Mirara dödömi ba mi''abe''e''ö, dozi ami, sanötöna khö Yehowa.[14]', '["Sin 27:5","Sin 17:7","Sin 116:11","Sin 27:14"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 1, 'Ya ahowu niha ni''efa''ö olalöŵa andrö, nibalugö horö![1]', '["Rom 4:6–9","Sin 3:11; 51:10","Amaed 28:13"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 2, 'Ya ahowu niha ba zi lö ibe''e horö lalö andrö Yehowa ba si lö falimosa ba dödö.', '["Rom 4:6–9","Sin 3:11; 51:10","Amaed 28:13"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 3, 'Me lö u''ombakha''ö, ba ariri dölagu, ba wangarö-ngarögu andrö, si lö mamalö-malö.[2]', '["Rom 4:6–9","Sin 3:11; 51:10","Amaed 28:13"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 4, 'Bongi ma''ökhö sa tohare khögu dangau; otufo nidanö nösigu, mane na baŵa lökhö.', '["Rom 4:6–9","Sin 3:11; 51:10","Amaed 28:13"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 5, 'Ba u''ombakha''ö khöu horögu, ba lö ubini''ö lalögu andrö. Umane: "Da''u''ombakha''ö khö Yehowa golalöŵagu andrö." Ba awena ö''efa''ö khögu horögu, lalögu andrö.[3]', '["Rom 4:6–9","Sin 3:11; 51:10","Amaed 28:13"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 6, 'Andrö ya mangandrö khöu dozi satulö, na baŵa ö''oroma''ö ndra''ugö; he ŵa''ae anönö danö molö sebua, ba lö ikhamö ira.', '["Rom 4:6–9","Sin 3:11; 51:10","Amaed 28:13"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 7, 'Ba''a-ba''a ndra''ugö khögu, ötimba khögu wamakao; öfasui ndra''o fa''iki ba wangorifi.', '["Rom 4:6–9","Sin 3:11; 51:10","Amaed 28:13"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 8, 'Ufahaö ndra''ugö, ufobawa lala khöu, nitöröu, ufolala dödöu, wangöhörögö ya''ugö.[4]', '["Sin 25:12","Amaed 26:3","Sin 33:1"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 9, 'Böi mifaomagö ami ba kudo ba ba kudo kalide, si lö tödö; sinali ba si''öli ba mbawa, fakakera, wamatörö; na lö da''ö, ba lö möi khöu.[5]', '["Sin 25:12","Amaed 26:3","Sin 33:1"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 10, 'Oya ngawalö wamakao ba zebua horö, ba sanötöna khöu, Yehowa, ba ifasui fa''ebua dödö.', '["Sin 25:12","Amaed 26:3","Sin 33:1"]', NULL),
  (3476042, 'OT', 'Sinunö', 32, 11, 'Mi''omusoi''ö dödömi khö Yehowa ba mi''owua-wua''ö dödömi, ya''ami satulö tödö, ba mi''a''iki dozi sadölö tödö.[6]', '["Sin 25:12","Amaed 26:3","Sin 33:1"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 1, 'Mi''owua-wua''ö dödömi, ya''ami satulö tödö, ba khö Yehowa andrö; si nangea ba zadölö tödö andrö, ba fanuno.[1]', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 2, 'Misuno Yehowa biola nitika zide-ide, milau khönia mbiola sebua, si fulu sinali!', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 3, 'Mi''anunö khönia sinunö si bohou; mi''abölögö mitika mbiola, ena''ö muhöngö.[2]', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 4, 'Si duhu sa daroma li Yehowa andrö; ba folaunia fefu, ba ba wa lö faröi.', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 5, 'Somasi ia, ba fa''atulö ba huku; ba no anönö danö fa''ebua dödö Yehowa.', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 6, 'Taroma li Yehowa wamazökhi mbanua si yaŵa ba eheha mbawania wamazökhi nösinia fefu.[3]', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 7, 'I''owuloi nasi, hulö ba nasoa, ibe''e ba halasa hounia.[4]', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 8, 'Yamu''ata''ufi Yehowa ösi guli danö ma''afefu, ya manizi-nizi fönania dozi sowanua ba guli danö!', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 9, 'Ha muhede ia, ba itörö; iŵa''ö, ba no so.', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 10, 'Ifufu Yehowa nikhoi dödö niha baero; lö fakhai gera-era soi niha ibe''e.', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 11, 'Tödö Yehowa andrö, ba lö tebulö, irugi zi lö aetu, ba era-era dödönia andrö, ba lö mamalö-malö.', '["Sin 32:11","Sin 40:4; 96:1; Fam 5:9","MozI 1:6,14","Sin 104:9"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 12, 'Ya ahowu niha si no mangai Lowalangira Yehowa andrö, niha nitutuyunia tana khönia![5]', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 13, 'Ifaigi-faigi Yehowa moroi ba zorugo, i''ila nono niha fefu.', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 14, 'Moroi ba nahania ifaigi-faigi, inehegö fefu zowanua ba guli danö.', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 15, 'Ya''ia, samazökhi tödöra fefu, si hörö-hörögö nilaura andrö fefu.', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 16, 'Tenga ba wa''ato zabölö khönia möna razo, ba sabölö, ba lö auri ba wa''afahöna wa''abölönia.[6]', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 17, 'Faya kudo, ba wangorifi, ba lö i''orifi niha fa''abölönia andrö.[7]', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 18, 'Hiza, hörö Yehowa andrö, ba i''ila zangata''ufi ya''ia ba sanötöna fa''ebua dödönia.[8]', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 19, 'Ba wangefa''ö nosora ba wa''amate, ba wangorifi ya''ira na lofo mbanua.[9]', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 20, 'Khö Yehowa manötona dödöda fangorifida ia ba baluseda.[10]', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 21, 'Ba khönia sa''ae omuso dödöda, me no manötöna ita ba döinia andrö, ni''amoni''ö.', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476043, 'OT', 'Sinunö', 33, 22, 'Ya so yaŵama wa''ebua dödöu andrö, ya''ugö Yehowa, ya itörö wanötönama khöu!', '["MozV 33:29","SamI 17","Sin 20:8","Sin 34:16,18","Sin 34:10,11","Sin 3:4"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 1, 'Khö Dawido, me i''osowöhö ia, khö Gabimelekhi, me ifofanö ia da''ö ba me iheta ia.[1]', '["SamI 21:14–16"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 2, 'Usuno Yehowa, si lö mamalö-malö, böi ya tebulö ba mbewegu wanuno ya''ia.', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 3, 'Yamusuno ia tödögu, ba khö Yehowa, ya larongo si numana, ba ya omuso dödöra.', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 4, 'Mifolakhömi Yehowa, awögu; datafaoma ta''ebua''ö döinia!', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 5, 'Ha me uga u''alui Yehowa, ba ifondrondrongo khögu, ba no i''efa''ö ndra''o ba wa''atosasagu fefu.', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 6, 'Ba zamaöga höröra khönia mohaga mbawa, ba alakha lö afusi mbawara.', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 7, 'No mu''ao zi numana andre, ba no irongo Yehowa, ba no i''efa''ö ba wa''atosasania fefu.', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 8, 'Ifasui mala''ika Yehowa zangata''ufi ya''ia ba i''efa''ö ira.[2]', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 9, 'Mitandra ba mifaigi, wa no sebua tödö Yehowa, ya ahowu zanötöna khönia![3]', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 10, 'Mi''ata''ufi Yehowa, ya''ami ni''amoni''ö andrö khönia; lö''ö sa ambö hadia ia ba zangata''ufi ya''ia.[4]', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 11, 'Ba nono zingo ambö gö ba olofo, ba ba zangalui Yehowa, ba lö ambö, fefu gofu hadia.[5]', '["MozI 32:2; Sin 91:11","FetI 2:3","Sin 37:19","Sin 33:18,19; 37:25; Luk 1:53"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 12, 'Mi''aine iraono, mifondrondrongo khögu, da''ufahaö ami ba wangata''ufi Yehowa.', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 13, 'Ha niha zomasi auri, somasi fa''anau noso, ena''ö falukha ia wa''ohahau dödö?', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 14, 'Taha lelau, ba zi lö sökhi, ba beweu, fa böi ilau waya![6]', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 15, 'Aröu''ögö ba zi lö sökhi ba lau zi sökhi; alui wa''atulö, gohi![7]', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 16, 'Itöngö Yehowa zamazökhi si lö sokhi, ba wangohori töira ba guli danö.', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 17, 'Ba ihörö-hörögö Yehowa zatulö tödö ba ibe''e mbörö dalingania ba we''aora.[8]', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 18, 'Mu''ao ira, ba irongo Yehowa ba i''efa''ö ira ba wa''abu dödöra fefu.', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 19, 'Ahatö Yehowa ba zi no arasa tödö ba itolo zi no atata era-era.[9]', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 20, 'Oya ngawalö wamakao ba zatulö, ba i''efa''ö ia Yehowa ba da''ö fefu.', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 21, 'Irorogö dölania fefu, fa böi afatö zara.[10]', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 22, 'Sebua horö andrö ibunu bua-bua si lö sökhi; ba si fatiu tödö ba zatulö tödö, ba göna huku dania.', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476044, 'OT', 'Sinunö', 34, 23, 'I''orifi noso genoninia Yehowa, ba dozi sanötöna khönia, ba lö göna huku.', '["FetI 3:10–12","Sin 37:27","Amaed 10:7","Sin 51:19","KorII 1:5"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 1, 'Lau fasöndra, Yehowa, ba zi fasöndra khögu, suwö zanuwö ya''odo.', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 2, 'Tuyu mbaluse, awö ndrange, ba faoso, tolo ndra''odo![1]', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 3, 'Halö doho ba ba''a lala föna zolohi ya''odo; ömane ba dödögu: "Fangorifiu ndra''odo!"', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 4, 'Ena''ö aila zangalui nosogu, ena''ö tobali lö fozu; ena''ö tofana furi ba ena''ö tehawu fa''aila zamakhai famunugu.[2]', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 5, 'Ya hulö guliho ba nangi ira, na itimba ira mala''ika Yehowa.', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 6, 'Ya ogömi-gömi lalara ba ya aelo, na igohi ira mala''ika Yehowa.', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 7, 'Noa sa lalau khögu gu''öra, lö börö, nibini''ö, no lakharu lösu-lösu nosogu, lö börö.[3]', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 8, 'Ya göna ia famakiko, si lö mudöna-döna, ba ya te''u''u ia ba gu''önia andrö, nilaunia, nibini''ö, ya alau ba wamakiko![4]', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 9, 'Ba owua-wua dania dödögu, ba khö Yehowa, omuso dödögu, ba wangorifinia andrö.', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 10, 'Imane ösigu fefu: "Ha niha zi fagölö-gölö khöu, Yehowa? Sangefa''ö sebua famakao ba zabölö moroi khönia, ba sebua famakao ba si numana ba zi anagöi ya''ia."', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 11, 'So sasi sofaya; hadia zi lö u''ila lasofu khögu.', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 12, 'Si sökhi lasulöni khögu si lö sökhi; fa lö ono gurakhagu.[5]', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 13, 'Ba ya''o, ba no u''onukha gonigoni, me mofökhö ira, no ufakao ndra''o lö manga, ba fangandrögu, ba mangawuli barö dotogu.[6]', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 14, 'Hulö na si fahuwu, hulö na talifusö wa''abu dödögu, no ufatugu ndra''o, hulö zange''esi inania.', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 15, 'Ba no omuso dödöra ba wa''alaugu andrö ba no la''owuloi ira khögu; niha bö''ö zangowuloi ya''ira khögu, si lö urai mila; lö mamalö-malö wanandraŵara.', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 16, 'La''igi''igi''ö ndra''odo, la''o''ayado, wamatangi bohara khögu.[7]', '["Sin 7:13,14","Sin 40:15","Ayati 19","Sin 9:16","Sin 38:21","Rom 12:15; Yob 31:29","Yob 16:9"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 17, 'He So''aya, heza irugi, wa öfaigi-faigi manö? Okafui dödögu, efa''ö ba wamufura andrö; efa''ö ba nono zingo zi lö awö-awö andrö khögu.[8]', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 18, 'Da''usuno ndra''ugö ba gowuloa sebua, ba zato niha u''ebua''ö döimö andrö.[9]', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 19, 'Böi be''e omuso dödö khögu zi fa''udu khögu, si lö börö; böi be''e lafamö''i höröra si fatiu tödö khögu, si lö börö.[10]', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 20, 'Tenga sa fa''atulö nifatunöra, ba lafakhai waya ba khö zahono-hono ba danö.', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 21, 'No lafaboka mbawara khögu, lamane: Ha! Ha! No i''ila höröda!"[11]', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 22, 'No ö''ila, ya''ugö Yehowa; böi zi lö hede-hede ndra''ugö! He So''aya, böi aröu''ögö khögu!', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 23, 'Faoso ba fazaŵa''ö, ba wamatunö huhuo andrö khögu, ya''ugö Lowalangigu ba So''aya ya''o, ba wolohe ba lala.[12]', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 24, 'Ohe ba zadölö huhuo andrö khögu, dali wa''atulömö andrö, ya''ugö Yehowa, Lowalangigu, ba böi be''e omuso dödöra khögu.', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 25, 'Böi tehe lamane dödöra: "Ha, da''ö zomasiga!" Böi lamane: "No tafakiko ia!"', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 26, 'Ena''ö aila ira, öbe''e; ena''ö tehawu fa''aila, dozi somuso tödö ba wa''abu dödögu andrö, ena''ö balu-balura wa''aila ba fa''iki niha bö''ö khöra, ya''ira si fayaŵa khögu.[13]', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476045, 'OT', 'Sinunö', 35, 27, 'Akha owua-wua dödö zomasi na falukhado zatulö, akha omuso dödöra, ena''ö lö mamalö-malö lamane: "Ya ebua Yehowa, somasi na auri genoninia andrö."[14]', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476045, 'OT', 'Sinunö', 35, 28, 'Ba ifatunö wa''atulömö andrö lelagu, ba fanuno ya''ugö, si lö mamalö-malö.', '["Sin 22:21","Sin 22:23","Sin 25:19; 19:5; Yoh 15:25","Sin 40:16","Sin 44:24","Ayati 4","Sin 40:17"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 1, 'Khö duka wanunö andrö. Khö genoni Yehowa andrö, Dawido.', '[]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 2, 'So wehede horö ba hunö dödö zebua horö andrö; ba wamaiginia, ba lö fangata''ufi Lowalangi.[1]', '["Rom 3:18","Mikh 2:1"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 3, 'No ihaogö-haogö khönia, wamaiginia, ena''ö terongo golalöŵania, ba ena''ö göna ia fatiusa.', '["Rom 3:18","Mikh 2:1"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 4, 'Famakiko ba faya daroma li mbewenia, no iböhöli wa''atua-tua ba folau si sökhi.', '["Rom 3:18","Mikh 2:1"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 5, 'Famakiko i''alu-alui ba gasonia, isaŵa lala sabila, lö i''ogorofi zi lö sökhi.[2]', '["Rom 3:18","Mikh 2:1"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 6, 'He Yehowa! irugi mbanua si yaŵa wa''ebua dödöu, irugi lawuo wa lö faröi ndra''ugö.[3]', '["Sin 57:11; 108:5","Sin 135:1,2","Sin 23:5","Yer 2:13"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 7, 'Fa''ebua hili Lowalangi andrö wa''atulömö ba huku andrö khöu, ba si mane namö sebua; ö''orifi niha ba saliŵa-liŵa ba danö, ya''ugö Yehowa.[4]', '["Sin 57:11; 108:5","Sin 135:1,2","Sin 23:5","Yer 2:13"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 8, 'Omasiö sibai wa''ebua dödöu, ya''ugö Lowalangi, labini''ö ira ono niha ba lumö gafiu andrö.', '["Sin 57:11; 108:5","Sin 135:1,2","Sin 23:5","Yer 2:13"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 9, 'Labadu zi no fahöna andrö ba nomomö, abuso ira, öfabadugö khöra hohou wa''omuso dödö andrö khöu.[5]', '["Sin 57:11; 108:5","Sin 135:1,2","Sin 23:5","Yer 2:13"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 10, 'Ba khöu sa so gumbu wangorifi andrö; ba haga andrö khömö ma''ila haga.[6]', '["Sin 57:11; 108:5","Sin 135:1,2","Sin 23:5","Yer 2:13"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 11, 'Böi bulö''ö wa''ebua dödöu andrö ba zi no fa''ila khöu, ba fa''atulömö ba zadölö tödö.', '["Sin 57:11; 108:5","Sin 135:1,2","Sin 23:5","Yer 2:13"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 12, 'Böi ya ikhamödo ahe zebua hokha andrö, ba böi yamutimba ndra''odo tanga zebua horö.', '["Sin 57:11; 108:5","Sin 135:1,2","Sin 23:5","Yer 2:13"]', NULL),
  (3476046, 'OT', 'Sinunö', 36, 13, 'Ba da''ö mege alau zamazökhi si lö sökhi, tetimba tou ira ba tebai maoso sa''ae.', '["Sin 57:11; 108:5","Sin 135:1,2","Sin 23:5","Yer 2:13"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 1, 'Böi ofönu ba khö zamazökhi si lö sökhi andrö: böi afökhö dödöu ba zolau si lö atulö.[2]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 2, 'Lö''ö sa arara, ba tetaba ira, si mane du''u, ba aleu, si mane bulu ndru''u ba danö.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 3, 'Döna-döna khö Yehowa ba lau zi sökhi; iagö danö ba fa''ua wa''adölö dödö.[3]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 4, 'Ba omuso dödöu ba khö Yehowa, ba ibe''e khöu zomasi dödöu.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 5, 'Be''e balazi Yehowa nitörömö andrö, ba döna-döna khönia, ba ya''ia zamaigi lala.[4]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 6, 'Ba ifatumbu''ö wa''atulö dödöu andrö si mane fa''amoluo, ba lala andrö khöu, si mane haga na laluo.[5]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 7, 'Honogö''ö föna Yehowa ba bazebaze''ö khönia; böi ofönu ba khö zamalua ni''alui dödönia, si lö hadia ia, ba ba niha solau sabila.[6]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 8, 'Röi wönu andrö ba böhöli wa''abao dödö; böi maoso dödöu; ha ba wamazökhi si lö sökhi aekhu da''ö.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 9, 'Nihori sa dania zanao horö, ba sanötöna khö Yehowa andrö zokhö tanö dania.[7]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 10, 'Hatö ma''ifu tö, ba lö''ö sa''ae sebua horö andrö, ba na öfaigi nahania, ba lö ya''ia sa''ae.[8]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 11, 'Ba sebolo tödö andrö zokhö tanö dania, ba owua-wua dödöra ba wa''afahöna wangorifi.[9]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 12, 'Sebua horö, ba ifakhai wamakiko satulö tödö, ifatangi mbohania khönia.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 13, 'Ba ma''iki Zo''aya khönia; noa sa i''ila, wa irugi baŵania dania.[10]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 14, 'No lasöbi wöda sebua horö ba no lakhai wana, ba wamakiko sebua famakao ba si numana, ba wamunu sanörö lala sadölö.[11]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 15, 'Ba ba dödöra göna dania wödara, ba nifatö dania wanara.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 16, 'Sökhi zi lö oya-oya ba zatulö tödö, moroi ba zi fahöna ba zebua horö andrö, si no ato.[12]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 17, 'Ta''io zebua horö andrö sa, ba nifatö, ba satulö tödö, ba ituwu Yehowa.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 18, 'I''ila Yehowa mbaŵa zadölö tödö, ba si so khöra, ba lö tebulö.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 19, 'Lö te''ailasi ira, na baŵa wamakao, ba na baŵa lofo, ba te''abusoi''ö ira.[13]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 20, 'Si tekiko sa zebua horö andrö, ba si fa''udu khö Yehowa, ba hulö wa''asökhi ndru''u ba danö, ariri, taya, hulö zimbo.[14]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 21, 'Sebua horö, ba mamalali ana''a, ba lö ibu''a, ba satulö tödö, ba oböwö, ibe''e ba nawönia göi.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 22, 'Nifahowu''önia sa zokhö tanö dania, ba ni''elifinia, ba nihori.[15]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 23, 'Yehowa sa zangabe''e''ö ahe niha, na omasi ia nitörönia.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 24, 'Na alau ia, ba lö adölö ba danö, ituwu sa dangania Yehowa.[16]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 25, 'Me iraono ndra''o föna ba me satua ndra''o ma''ökhö, ba lö urai u''ila, numana zatulö tödö, ba lö urai u''ila mangandrö gö ma''uwunia.[17]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 26, 'Lö mamalö-malö wa''oböwönia, ibe''e-be''e nifalali, ba nifahowu''ö ma''uwunia.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 27, 'Aröu''ögö ba zi lö sökhi, ba lau zi sökhi, ba si lö tebulö ba danö ndra''ugö.[18]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 28, 'Huku satulö sa zomasi Yehowa, ba lö faröi ia ba zatulö tödö andrö khönia.[19]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 29, 'Satulö tödö zokhö tanö dania, ya''ira zowanua ba danö, si lö mamalö-malö.[20]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 30, 'Fa''atua-tua wehede zatulö tödö andrö, ba huku satulö ifatunö.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 31, 'No so ba dödönia goroisa Lowalanginia, ba lö mangiwa gahenia.[21]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 32, 'Idaro-darogö zatulö tödö andrö sebua horö, i''alui wamunu ya''ia.[22]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 33, 'Ba lö ilulu ba dangania Yehowa, ba lö ibe''e ni''etu''ö huku, na tehuku ia.[23]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 34, 'Döna-döna khö Yehowa ba törö lala andrö khönia, ba ibali''ö salaŵa ndra''ugö, ena''ö möi khöu danö. Na tehori zebua horö andrö, ba samaigi-maigi ndra''ugö.[24]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 35, 'No u''ila zebua horö, solau hokha, samologö ya''ia, si mane eresi andrö ba hili Libano.[25]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 36, 'Ba me ufuli utörö, ba lö ya''ia sa''ae; ba u''alui ia, ba lö usöndra.[26]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 37, 'Töngöni zi lö sala ba faigi zadölö tödö andrö, wa moma''uwu niha somasi fa''atulö.[27]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 38, 'Solalö, ba tehori fefu; nga''ötö zebua horö, ba ni''etu''ö.', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 39, 'Khö Yehowa i''otarai fangorifi satulö tödö andrö, ba''a-ba''ara ia, na baŵa wamakao.[28]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476047, 'OT', 'Sinunö', 37, 40, 'Ba itolo ira Yehowa, i''orifi ira; i''efa''ö ira ba zebua horö andrö ba ilului khöra, me no saŵatöra ia.[29]', '["Amaed 24:19","Ayati 27,29","FetI 5:7","Sin 97:11; 112:4; Yob 11:17","Sin 73:3","Ayati 11,22,29,34","Ayati 35","Ayati 9; Mat 5:5","Yob 18:20","Sin 11:2","Amaed 15:16","Sin 33:14","Sin 68:3","Ayati 9","Amaed 24:16","Sin 34:10,11","Sin 34:15","Sin 11:7","Yes 60:21","Sin 40:9","Sin 10:8–10","Sin 34:23","Yob 5:3–5; 20:6,7; Hez 31:3–14","Ayati 10","MozI 39:8,9","Sin 46:2","Luk 18:8"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 1, 'Khö Dawido, ba wamasugi ba dödö.[1]', '["Faigi göi Sin 6"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 2, 'He Yehowa! böi huku ndra''o ba wönumö ba böi otu''ö ndra''o ba wa''abao dödöu andrö![2]', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 3, 'Noa sa manga ba nösigu nono wana andrö khöu, ba no tohare khögu dangau.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 4, 'Lö hadia ia ba nösigu zi lö sokho, ba wönumö andrö; lö hadia ia ba dölagu zi lö fökhö, ba horögu andrö.[3]', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 5, 'Noa sa ihawui ndra''o lalögu andrö, hulö noro sabua, tebai ulu''i sa''ae.[4]', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 6, 'Aböu zesokho andrö khögu ba monana, börö me no sowöhö mowa ndra''odo.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 7, 'No aköi hulugu, tenga ha ma''ifu aöndrö, mowaö-waö manö ndra''o, abu dödö, ma''ö-ma''ökhö.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 8, 'Sawai alitö ngaigu ba lö hadia ia ba nösigu zi lö sokho.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 9, 'Erege dödögu ba no arasa manö dölagu; mangarö-ngarö ndra''o, ebua ligu, moroi ba li zingo.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 10, 'He So''aya! Fefu wehulu dödögu, ba no oroma khöu, ba lö tobini khöu wangarö-ngarögu.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 11, 'Manutunutu sibai dödögu, ba no taya wa''abölögu; numalö fa''atara ba hörögu, ba lö''ö.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 12, 'Somasi ya''odo ba si no fahuwu khögu, ba la''ewegö ira, ba wa''afökhö andrö khögu.[5]', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 13, 'Ba sangalui famunu ya''o, ba lalau wesu khögu; ba somasi famakaogu, ba mamagölö ba wamakiko, lafakhai waya, lö mamalö-malö.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 14, 'Ba ya''odo, ba hulö zafiso; lö urongo; ba hulö zi lö hede, si lö mamokai bawania.[6]', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 15, 'No tobali hulö zi lö mamondrongo li niha ndra''odo, si lö famadaö ba mbewe.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 16, 'Noa sa udöna-döna khöu, ya''ugö Yehowa, ya''ugö zamondrongo ligu, ya''ugö, Yehowa, Lowalangigu.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 17, 'Noa sa umane: "Ena''ö lö omuso dödöra ba khögu andre!" Me ahele gahegu, ba fayaŵa ira khögu.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 18, 'Lö aröu tö, ba alau ndra''o, ba lö''ö manö döhö wa''afökhö andrö khögu.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 19, 'U''ombakha''ö sa''ae zalagu ba abu dödögu horögu andrö.[7]', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 20, 'Ba auri zi fa''udu khögu, abölö ira, ba ato zi fatiu tödö khögu lö börö.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 21, 'Ba lasulöni si lö sökhi zi sökhi, lasukosuko ndra''odo, börö wa u''alui zi sökhi.[8]', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 22, 'Böi böhöli ndra''o, ya''ugö Yehowa, Lowalangigu, böi aröu''ögö khögu!', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476048, 'OT', 'Sinunö', 38, 23, 'Ta''i-ta''i tolodo, ya''ugö So''aya fangorifigu.', '["Yob 6:4; Sin 32:4","Sin 51:10","Ngenu 1:14","Sin 31:12; Yob 19:14","Sin 39:3","Sin 32:5","Sin 35:12"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 1, 'Khö duka wanunö andrö; khö Yedutuno. Sinunö khö Dawido.[1]', '["Nga''ötI 25:1,3"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 2, 'No umane: "Da''ufaigi-faigi lalagu andrö, fa böi ufazökhi horö lelagu andre; da''udaro-darogö mbewegu, ufosare''a, götö wa so ba ngaigu zebua horö andrö."', '["Sin 38:14","Sin 9:12; Yob 14:5","Sin 90:5","Sangomb 2:18,21; Luk 12:18–20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 3, 'No lö hede-hedegu, no ahono ndra''odo, lö sihededo, lö si sökhi khögu; ba tesao wa''afökhö khögu.[2]', '["Sin 38:14","Sin 9:12; Yob 14:5","Sin 90:5","Sangomb 2:18,21; Luk 12:18–20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 4, 'Aukhu bakha dödögu, humola, ba wamatou-tou andrö; umane lelagu:', '["Sin 38:14","Sin 9:12; Yob 14:5","Sin 90:5","Sangomb 2:18,21; Luk 12:18–20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 5, '"He Yehowa, ombakha''ö khögu wozugu ba ha wa''anau nosogu, ena''ö u''ila wa lö arara ndra''odo![3]', '["Sin 38:14","Sin 9:12; Yob 14:5","Sin 90:5","Sangomb 2:18,21; Luk 12:18–20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 6, 'Hiza, nisu''a ba lalu''a mbaŵagu andrö, öbe''e, ba fa''anau nosogu, ba hulö zi lö''ö, fönau, ha sambalö angi niha fefu, gofu ha wa''abe''e.[4]', '["Sin 38:14","Sin 9:12; Yob 14:5","Sin 90:5","Sangomb 2:18,21; Luk 12:18–20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 7, 'Hulö lumö-lumö mowaö-waö misa niha, fagua-gua ba zi lö boto. Lahöna girö-girö, ba lö la''ila, ha khö möi dania.[5]', '["Sin 38:14","Sin 9:12; Yob 14:5","Sin 90:5","Sangomb 2:18,21; Luk 12:18–20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 8, 'Ba iya''e, ba hadia nidöna-dönagu, ya''ugö So''aya? Ha khömö manötöna ndra''odo.', '["SamII 16:10","Ayati 6","MozIII 25:23; Sin 119:19; FetI 2:11; Heb 11:13","Yob 10:20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 9, 'Efa''ö khögu lalögu andrö fefu; böi be''e ni''o''aya zowöhö mowa ndra''odo.', '["SamII 16:10","Ayati 6","MozIII 25:23; Sin 119:19; FetI 2:11; Heb 11:13","Yob 10:20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 10, 'Lö hede-hedegu sa''ae, lö ubokai mbawagu; ya''ugö sa zolau.[6]', '["SamII 16:10","Ayati 6","MozIII 25:23; Sin 119:19; FetI 2:11; Heb 11:13","Yob 10:20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 11, 'Efa''ö khögu wamakao andrö khöu; ba wombambaya dangau andrö ariri ndra''odo.', '["SamII 16:10","Ayati 6","MozIII 25:23; Sin 119:19; FetI 2:11; Heb 11:13","Yob 10:20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 12, 'Öhuku niha, ö''otu''ö ba golalöŵania andrö, ba taya zi sökhi andrö khönia öbe''e, hulö ni''a hama; si ndruhu, angi niha fefu.[7]', '["SamII 16:10","Ayati 6","MozIII 25:23; Sin 119:19; FetI 2:11; Heb 11:13","Yob 10:20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 13, 'Fondrondrongo wangandrögu, ya''ugö Yehowa, be''e ba dödöu we''aogu andre! Böi zi lö hede-hede ndra''ugö ba wege-egegu! Niha bö''ö sa ndra''o khöu, si fatewu, si mane ira tuagu fefu.[8]', '["SamII 16:10","Ayati 6","MozIII 25:23; Sin 119:19; FetI 2:11; Heb 11:13","Yob 10:20"]', NULL),
  (3476049, 'OT', 'Sinunö', 39, 14, 'Böi faigi-faigido sa''ae, ena''ö okafu dödögu, fatua lö mofanö ndra''o, si lö ya''odo sa''ae![9]', '["SamII 16:10","Ayati 6","MozIII 25:23; Sin 119:19; FetI 2:11; Heb 11:13","Yob 10:20"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 1, 'Khö duka wanunö andrö. Khö Dawido. Sinunö.', '[]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 2, 'Lö niböhöigu fanötöna khö Yehowa, ba no ihatö''ö ia khögu ba no ifondrondrongo we''aogu andrö.', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 3, 'No idöni yaŵa ndra''odo, moroi ba gohokoho famakiko andrö, moroi ba dambu sombuyu; ba no ifonaha gahegu ba dete gara ba no i''abe''e''ö mbekagu.', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 4, 'Ba no ibe''e ba mbewegu zinunö si bohou, fanuno Lowalangi andrö. Ato zangila, ba ata''u, ba manötöna khö Yehowa.[1]', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 5, 'Ya ahowu niha same''e tötönafönia Yehowa ba si lö möi ba zi fayaŵa ba ba zamahole''ö ya''ira ba waya.', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 6, 'Oya ngawalö zahöli-höli dödöma khöu ba era-erau, nifatöröu khöma, ya''ugö Yehowa, Lowalangigu; lö hadia ia zi fagölö-gölö khöu! na lafatunö ena''ö, na itörö li, ba abölö oya, tebai lazara-zara.[2]', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 7, 'Sumanga nitaba ba sumange ni''a, ba lö omasi ndra''ugö, ba no ökhau khögu dögi dalinga; sumange nitunu ba sumange fameta horö, ba lö ba dödöu.[3]', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 8, 'Ba umane: Hiza, sodo dania, ba nga''ölu zura itörö li ndra''odo.', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 9, 'Folo''ö somasi ndra''ugö, ya''ugö Lowalangigu, ba no fa''omasigu; ba oroisamö, ba no so ba dödögu bakha.', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476050, 'OT', 'Sinunö', 40, 10, 'No u''ombakha''ö wa''atulömö, ba gowuloa sebua; hiza, lö nitahagu bewegu, — ya''ugö Yehowa zangila![4]', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 11, 'Fa''atulömö andrö, ba lö nibini''ögu ba dödögu bakha; fa lö faröi ndra''ugö ba fangorifi andrö khöu, ba no ufatunö; fa''ebua dödöu ba fa''aduhumö andrö, ba lö nibalugögu ba gowuloa sebua.', '["Sin 33:3","Sin 139:17,18","Sin 51:18; Heb 10:5–10; Yes 50:5","Sin 22:23, 26"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 12, 'Lö''ö sa öböda wa''ahakhö dödöu khögu, ya''ugö Yehowa, lö tebulö, wa irorogö ndra''odo fa''ebua dödöu andrö ba fa lö faröi ndra''ugö.', '["Ayati 14–18: Sin 70","Sin 6:11","Sin 35:21,25","Sin 109:22"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 13, 'Noa sa tefasui ndra''odo famakao, si tebai te''erai; no ikhamö ndra''o olalöŵagu andrö, fa tebai u''ila niha; no oya, moroi ba wa''oya rozi mbu ba högögu, ba no atoru dödögu. [5]', '["Ayati 14–18: Sin 70","Sin 6:11","Sin 35:21,25","Sin 109:22"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 14, 'Ena''ö omasi ndra''ugö wangorifi ya''odo, ya''ugö Yehowa! He Yehowa, ta''i-ta''i tolodo!', '["Ayati 14–18: Sin 70","Sin 6:11","Sin 35:21,25","Sin 109:22"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 15, 'Ena''ö aila ira fefu, öbe''e, ena''ö tehawu fa''aila, sangalui famunu ya''odo, fangetu''ö nosogu; ena''ö awuwu furi ba ena''ö falukha wa''aila zomasi famunugu![6]', '["Ayati 14–18: Sin 70","Sin 6:11","Sin 35:21,25","Sin 109:22"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 16, 'Ena''ö tobali dödö zanguma''ö: Ha! ha! ba wa''ailara andrö.[7]', '["Ayati 14–18: Sin 70","Sin 6:11","Sin 35:21,25","Sin 109:22"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 17, 'Akha ma''iki dozi sangalui ya''ugö, ba akha omuso dödöra; somasi fangorifi andrö khöu, ba hana na lö aetu laŵa''ö: "Razo Yehowa!"', '["Ayati 14–18: Sin 70","Sin 6:11","Sin 35:21,25","Sin 109:22"]', NULL),
  (3476050, 'OT', 'Sinunö', 40, 18, 'Ba he sebua akaola ndra''odo ba si numana, ba irorogö ndra''o So''aya. Sanolo ya''o ba sangorifi ya''o ndra''ugö; böi aragö''ö, ya''ugö Lowalangigu![8]', '["Ayati 14–18: Sin 70","Sin 6:11","Sin 35:21,25","Sin 109:22"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 1, 'Khö duka wanunö andrö. Sinunö khö Dawido.', '[]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 2, 'Ya ahowu zi so ba dödö niha si numana! Na baŵa wamakao, ba i''orifi ia Yehowa.[1]', '["Amaed 19:17"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 3, 'Irorogö ia Yehowa ba i''anau''ö nosonia; ohahau dödönia ba danö ba lö ölulu ia ba wa''afökhö dödö zi fatiu tödö khönia.', '["Amaed 19:17"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 4, 'Ituwu narö galogonia Yehowa ba wökhönia, tou ba zalo; ötolo ia ba wökhönia fefu.', '["Amaed 19:17"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 5, 'No umane: Hakhösi tödö ndra''o Yehowa! Fadöhö wökhö dödögu; noa sa ufazökhi horö khöu.[2]', '["Sin 6:3","Sin 55:14; Yoh 13:18; HalZin 1:16"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 6, 'Si lö sökhi wehede zi fa''udu khögu, lamane, ba khögu andre: "Ha wa''ara mate ia, ha wa''ara taya döinia."', '["Sin 6:3","Sin 55:14; Yoh 13:18; HalZin 1:16"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 7, 'Ba na so zi möi mamaigi ya''odo, ba falimosa wehedenia; ihöna wamakiko tödönia — möi ia baero ba ifatunö.', '["Sin 6:3","Sin 55:14; Yoh 13:18; HalZin 1:16"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 8, 'Dozi si fatiu tödö khögu, ba fangöngö-ngöngö ba khögu andre, lafakhai wamakiko ya''odo.', '["Sin 6:3","Sin 55:14; Yoh 13:18; HalZin 1:16"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 9, '"No itörö ia horö, ba me no alau ia, ba lö maoso sa''ae."', '["Sin 6:3","Sin 55:14; Yoh 13:18; HalZin 1:16"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 10, 'Ba satulö tödö khögu na''i, si faduhu dödögu, si manga wöfö gögu, ba no ifazaŵa mbörö sisinia khögu.[3]', '["Sin 6:3","Sin 55:14; Yoh 13:18; HalZin 1:16"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 11, 'Ba ya''ugö Yehowa, ba hakhösi tödö ndra''o ba fuli fazaŵado, ena''ö usulöni khöra!', '["Sin 72:18; 89:53; 106:48; 150:6"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 12, 'Ba da''ö aboto ba dödögu, wa omasi''ö ndra''odo, me lö tola iherai ndra''o si fatiu tödö khögu.', '["Sin 72:18; 89:53; 106:48; 150:6"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 13, 'Börö wa''adölö dödögu, wa lö öbe''e alau ndra''o, ba no öfataro ba gamaudumö ndra''odo, si lö mamalö-malö.', '["Sin 72:18; 89:53; 106:48; 150:6"]', NULL),
  (3476051, 'OT', 'Sinunö', 41, 14, 'Nisuno Yehowa, Lowalangi Ndraono Gizeraeli, götö-götö wa''ara! Yaduhu! Yaduhu![4]', '["Sin 72:18; 89:53; 106:48; 150:6"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 1, 'Khö duka wanunö andrö. Famahaö; nilau Ndraono Gora andrö.', '[]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 2, 'Si mane fa''owökhi dödö mböhö, ba wamadu idanö soluaha, si manö wa''owökhi dödögu khöu, ya''ugö Lowalangi.', '["Sin 84:3","Sin 27:4","Ayati 12; Sin 43:5"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 3, 'Owökhi dödögu khö Lowalangi sauri andrö. Ha wa''ara tö ukhamö wangoroma''ö ya''odo khö Lowalangi?[1]', '["Sin 84:3","Sin 27:4","Ayati 12; Sin 43:5"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 4, 'Ubadu-badu daŵa hörögu, bongi ma''ökhö, börö wa ma''öma''ökhö lasofu khögu: "Heza so Lowalangiu andrö?"', '["Sin 84:3","Sin 27:4","Ayati 12; Sin 43:5"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 5, 'Da''ö u''angeragö, ba ufaduwa nösi dödögu bakha, me fao ndra''o ba zato andrö, me u''ohe ira ba nomo Lowalangi, me manunö-nunö ndra''aga ba me mangandröga saoha gölö — sato, si möi ba gowasa.[2]', '["Sin 84:3","Sin 27:4","Ayati 12; Sin 43:5"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 6, 'Hadia wa no ökaöndrö''ö, ya''ugö tödögu, wa lö ahono''ö bakha? Döna-döna khö Lowalangi! Usuno na sa ia, fangorifigu ba Lowalangigu.[3]', '["Sin 84:3","Sin 27:4","Ayati 12; Sin 43:5"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 7, 'No ikaöndrö ia bakha tödögu, andrö itörö tödögu ndra''ugö, moroi ba danö Yoridano ba moroi ba hili Heremono, moroi ba hili side-ide andrö.[4]', '["SamI 15:30 b.t.","Sin 88:8","MozV 32:4; Sin 43:2","Ayati 6"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 8, 'Mu''ao hohou ba nawönia hohou, ba we''ugu-ugu lawulawu nidanö andrö khöu; no itörö högögu dulu ba hohou andrö khöu fefu.[5]', '["SamI 15:30 b.t.","Sin 88:8","MozV 32:4; Sin 43:2","Ayati 6"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 9, 'Ba zi ma''ökhö i''oro''ö wa''ebua dödönia Yehowa ba ba zi bongi utandrösaigö khönia wanunögu, fangandrö khö Lowalangi fangorifigu andrö.', '["SamI 15:30 b.t.","Sin 88:8","MozV 32:4; Sin 43:2","Ayati 6"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 10, 'Umane khö gowegu Lowalangi andrö: "Hana wa no olifu''ö ndra''odo? Hana wa moŵaö-waö manö ndra''o, abu dödö, ba wamakao zi fatiu tödö khögu ya''odo?"[6]', '["SamI 15:30 b.t.","Sin 88:8","MozV 32:4; Sin 43:2","Ayati 6"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 11, 'Hulö wemanga henu ba dölagu wango''aya zamakao ya''o andrö ya''odo, me lö mamalö-malö, wa lamane khögu: "Heza so Lowalangiu andrö?"', '["SamI 15:30 b.t.","Sin 88:8","MozV 32:4; Sin 43:2","Ayati 6"]', NULL),
  (3476052, 'OT', 'Sinunö', 42, 12, 'Hadia wa no ökaöndrö''ö, ya''ugö tödögu, wa lö ahono''ö bakha? Döna-döna khö Lowalangi. Usuno na sa ia, fangorifigu ba Lowalangigu![7]', '["SamI 15:30 b.t.","Sin 88:8","MozV 32:4; Sin 43:2","Ayati 6"]', NULL),
  (3476053, 'OT', 'Sinunö', 43, 1, 'Faigi khögu zatulö, ya''ugö Lowalangi, ohe ba lala huhuogu ba niha andrö, si lö fa''omasi; efa''ö ndra''o ba niha sebua faya, solau si lö atulö![1]', '["Sin 26:1","Sin 42:10","Sin 15:1","Sin 63:3","Sin 42:6, 12"]', NULL),
  (3476053, 'OT', 'Sinunö', 43, 2, 'Lowalangi ba''a-ba''agu sa ndra''u''gö. Hana wa no ötibo''ö ndra''odo? Hana wa mowaö-waö manö ndra''o, abu dödö, ba wamakao zi fatiu tödö khögu ya''odo?[2]', '["Sin 26:1","Sin 42:10","Sin 15:1","Sin 63:3","Sin 42:6, 12"]', NULL),
  (3476053, 'OT', 'Sinunö', 43, 3, 'Fa''ohe''ö hagamö ba si duhu andrö khöu! Da''ö zamasao ya''odo, solohe ya''o ba hili ni''amoni''ö andrö khöu, ba ba nahamö andrö.[3]', '["Sin 26:1","Sin 42:10","Sin 15:1","Sin 63:3","Sin 42:6, 12"]', NULL),
  (3476053, 'OT', 'Sinunö', 43, 4, 'Fa ukhamö naha wame''e sumange khö Lowalangi ba Lowalangi fa''omuso dödögu andrö, sowua-wua dödögu, ena''ö usuno ndra''ugö, wolau biola nitika andrö side-ide, ya''ugö Lowalangi, Lowalangigu![4]', '["Sin 26:1","Sin 42:10","Sin 15:1","Sin 63:3","Sin 42:6, 12"]', NULL),
  (3476053, 'OT', 'Sinunö', 43, 5, 'Hadia wa no ökaöndrö''ö, ya''ugö tödögu, wa lö ahono''ö bakha! Döna-döna khö Lowalangi. Usuno na sa ia, fangorifigu ba Lowalangigu.[5]', '["Sin 26:1","Sin 42:10","Sin 15:1","Sin 63:3","Sin 42:6, 12"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 1, 'Khö duka wanunö andrö. Nilau Ndraono Gora andrö, Famahaö.[1]', '["Faigi göi Sin 60:SamII 8:3–14"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 2, 'He Lowalangi! No irongo tögi dalingama, no latunö khöma ira amama, ira tuama zebua andrö, nilaumö ba götöra, ba götö föna andrö.[2]', '["MozV 6:20–25","Sin 74:12","Sin 20:8"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 3, 'No ötimba soi niha tangamö andrö, ba no öfataro ira (ndra tuama); no öfakiko soi niha, ba no öbologö ira (ndra tuama)', '["MozV 6:20–25","Sin 74:12","Sin 20:8"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 4, 'Tenga moroi ba wangönara, wa tola la''okhögö danö, ba tenga moroi ba da''iora, wa möna ira, ha moroi ba dangau kambölö ba moroi ba da''iomö ba moroi ba haga mbawau andrö, me no ö''omai''ö ira.', '["MozV 6:20–25","Sin 74:12","Sin 20:8"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 5, 'Ya''ugö sa razogu, ya''ugö Lowalangi; ŵa''ö wangorifi Ndraono Yakobo andrö![3]', '["MozV 6:20–25","Sin 74:12","Sin 20:8"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 6, 'Moroi khöu, wa ma''ila matimba zamakao ya''aga ba moroi ba döimö andrö, wa mahundragö tou zi fa''udu khöma.', '["MozV 6:20–25","Sin 74:12","Sin 20:8"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 7, 'Ba wanagu lö''ö sa udöna-döna, ba si''öligu andrö, ba lö i''orifido.[4]', '["MozV 6:20–25","Sin 74:12","Sin 20:8"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 8, 'Ha sa ya''ugö zangefa''ö ya''aga ba zamakao ya''aga, ba aila zi fatiu tödö khöma öbe''e.', '["MozV 6:20–25","Sin 74:12","Sin 20:8"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 9, 'Ba khö Lowalangi masuno ndra''aga, si lö mamalö-malö, ba irugi zi lö aetu masuno döimö andrö.', '["MozV 6:20–25","Sin 74:12","Sin 20:8"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 10, 'Ba noa zui ötibo''ö ndra''aga ba no öbe''e aila ndra''aga, ba lö''ö sa''ae fao ndra''ugö ba zi möi fasuwö andrö khöma.', '["Sin 79:4; RazI 9:7"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 11, 'Moloi ndra''aga ba zamakao ya''aga öbe''e, ba no morabu zi fatiu tödö khöma.', '["Sin 79:4; RazI 9:7"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 12, 'No ölulu ndra''aga, hulö mbiri-biri nitaba ö, ba no öfazawili ndra''aga ba niha baero.', '["Sin 79:4; RazI 9:7"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 13, 'No ö''amawa mbanuau, side-ide böli, lö ni''ebua''ömö bölinia.', '["Sin 79:4; RazI 9:7"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 14, 'Laherai ndra''aga si so ba ngaima öbe''e, irege la''igi''igi''ö ndra''aga si tefasui ya''aga ba la''o''ayaga.[5]', '["Sin 79:4; RazI 9:7"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 15, 'No öbe''e amaedola ndra''aga ba niha baero, awö wa lafalikhö ira khöma soi niha.', '["Sin 79:4; RazI 9:7"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 16, 'Lö mamalö-malö ba duduma hörögu wa''ailagu andrö, no tehawu ndra''o fa''aila andrö, si no göna ndra''odo.', '["Sin 79:4; RazI 9:7"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 17, 'Börö li zango''aya ya''odo, awö li zanandraŵaisi ya''o ba si fatiu tödö andrö, ba somasi folau balö, ni''ila-ila hörögu.', '["Sin 79:4; RazI 9:7"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 18, 'Da''ö fefu zanörö ya''aga, he ŵa''ae lö olifuga ndra''ugö, ba he ŵa''ae lö si falimo ndra''aga, ba wawu''usa li andrö khöu.', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 19, 'Lö si fabali dödöma ba lö nihole''öma ya''aga, wondröi lala andrö khöu.', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 20, 'Wa no öfufu ndra''aga ba naha nasu ana''a andrö, awö wa no öhawui ndra''aga fa''ogömi-gömi.', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 21, 'Na no olifuga mena''ö döi Lowalangima andrö, na no ma''oro''ö dangama ba Lowalangi bö''ö,', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 22, 'ba hadia, lö i''alui da''ö Lowalangi? I''ila sa atö zi tobini ba dödö.[6]', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 23, 'Börö sa ndra''ugö, wa tebunubunu ndra''aga, si lö mamalö-malö, hulö mbiri-biri nitataba ndra''aga, ba dödö niha bö''ö.[7]', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 24, 'Faoso! Hana wa mörö''ö, ya''ugö So''aya? Faoso! Böi tibo''ö ndra''aga si lö fulitö![8]', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 25, 'Hana wa öbini''ö mbawau ba hana wa olifu''ö wa''anumanama ba famakao ya''aga andrö?[9]', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 26, 'Noa sa aöndrö dödöma, irugi ba gawu-gawu tou, no fatöfa ba danö daluma.', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476054, 'OT', 'Sinunö', 44, 27, 'Fazaŵa''ö, ba wanolo ya''aga ba orifi ndra''aga ba wa''ebua dödöu andrö!', '["Sin 7:10","Rom 8:36","Sin 35:23","Sin 10:1"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 1, 'Khö duka wanunö andrö, dali "Ladari mböhö" andrö; nilau Ndraono Gora. Fanuno fa''omasi andrö.[1]', '["Fam 19:7"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 2, 'Falawu dödögu fehede omasiö. Umane: Khö razo utandrösaigö nilaugu andrö. Lelagu andre ba no fanura, khö zanura si no to''ölö.', '["SinSeb 5:10–16","Sin 72:4","SamII 7:13; Heb 1:8,9","Amos 3:15"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 3, 'Si sökhi ndra''ugö, lö famaedou ba niha bö''ö. No tefaduwa ba mbeweu zomasi nawöu; da''ö mbörö, wa no ifahowu''ö ndra''ugö Lowalangi, si lö mamalö-malö.[2]', '["SinSeb 5:10–16","Sin 72:4","SamII 7:13; Heb 1:8,9","Amos 3:15"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 4, 'Be''e ba mböbö löwi-löwiu wödamö andrö, ya''ugö sabölö, lakhömiu ba fa''asalaŵamö andrö!', '["SinSeb 5:10–16","Sin 72:4","SamII 7:13; Heb 1:8,9","Amos 3:15"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 5, 'Törö, owaö-waö ba wamatörö si duhu ba fa''ebolo dödö ba fa''atulö, ba yamufahaö''ö kambölöu ba zata''u niha.[3]', '["SinSeb 5:10–16","Sin 72:4","SamII 7:13; Heb 1:8,9","Amos 3:15"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 6, 'Satarö nono wana andrö khöu, mate barö gaheu soi niha, tekiko zi fa''udu khö razo.', '["SinSeb 5:10–16","Sin 72:4","SamII 7:13; Heb 1:8,9","Amos 3:15"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 7, 'Dadaomamö andrö, ya''ugö Lowalangi, ba si lö tebulö; si''o ba wa''atulö zi''o zalaŵa andrö khöu.[4]', '["SinSeb 5:10–16","Sin 72:4","SamII 7:13; Heb 1:8,9","Amos 3:15"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 8, 'Somasi fa''atulö ndra''ugö ba si fa''udu ba zabila; andrö wa no ibayoini ndra''ugö Lowalangi, Lowalangiu andrö, fanikha somuso dödö, moroi ba nawöu fefu.', '["SinSeb 5:10–16","Sin 72:4","SamII 7:13; Heb 1:8,9","Amos 3:15"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 9, 'Oi emuri ba ŵe göna farasi ba kuli mani nukhau fefu; omuso dödöu ibe''e li mbiola, si oroi gödo ifö guaza.[5]', '["SinSeb 5:10–16","Sin 72:4","SamII 7:13; Heb 1:8,9","Amos 3:15"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 10, 'Fasoli ono razo alawe zomasi''ö andrö; no so ba gambölöu ngambatöu, mo''aya ana''a Gofiri.', '["MozI 2:24"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 11, 'Fondrondrongo ono alawe ba faigi ba be''e mbörö dalingau, ba hana na olifu''ö niwami ba omo namau andrö.[6]', '["MozI 2:24"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 12, 'Ba na omasi razo wa''asökhimö andrö — sokhö ya''ugö sa ia —, ba fosumange ia.', '["MozI 2:24"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 13, 'Ba la''alui wa''ebua dödöu banua Diro andrö, mamuala ira khöu, fondrege zebua ana''a, banuara.', '["MozI 2:24"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 14, 'Ha sambalö lakhömi nono razo alawe yomo, böna ame manö nukhania.', '["MozI 2:24"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 15, 'Nukha nifotalakhoi nukhania, na la''ohe khö razo; la''ohe dania khöu nono alawe (bö''ö), moroi furinia, awönia.', '["MozI 2:24"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 16, 'Omuso dödö niha ba ma''iki-iki, na la''ohe; möi ira yomo ba gödo razo.', '["MozI 2:24"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 17, 'Fangali ndra amau dania nonou; sagörö tanö misa öfataro ira salaŵa.', '["MozI 2:24"]', NULL),
  (3476055, 'OT', 'Sinunö', 45, 18, 'Ba itörö tödö nga''ötö dania fefu döimö ube''e; andrö lasuno dania ndra''ugö soi niha, irugi zi lö aetu.', '["MozI 2:24"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 1, 'Khö duka wanunö andrö; nilau Ndraono Gora; dali ba nono alawe andrö. Sinunö.[1]', '["RazII 19:35 b.t."]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 2, 'Saŵatöda ba fangabe''eda Lowalangi, fanolo sabölö, ba wa''abu dödö.', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 3, 'Andrö lö ata''u ita, he ŵa''ae adudu danö, he ŵa''ae awu''a hili, wanaŵa talu nasi.', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 4, 'Hana na mu''ugu nasi ba hana na modulu, hana na muhisi hili ba wedulunia: Yehowa ngahönö andrö nawöda, ba hati khöda Lowalangi Yakobo.', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 5, 'Boto nidanö — omuso dödö mbanua Lowalangi ibe''e dahadahania; ni''amoni''ö andrö, naha Wondrege zalaŵa.[2]', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 6, 'Ba dalunia so Lowalangi, tebai mangiwa ia; itolo ia Lowalangi, na moluo.', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 7, 'Fagua-gua soi niha, mangiwa nöri; ifarongogö linia, alau danö.', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 8, 'Yehowa ngahönö andrö nawöda, hati khöda Lowalangi Yakobo.', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 9, 'Mi''aine, mifaigi nilau Yehowa, si no mame''e tobali dödö niha ba guli danö.[3]', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 10, 'Sanenaŵa fanuwö irugi wondrege danö, samatö fana, soleŵa totoa doho, sanunu alitö kureta![4]', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 11, 'Mibato, ba ya''aboto ba dödömi, wa ya''odo Lowalangi; salaŵa ndra''odo, salaŵa soi niha, salaŵa ba guli danö!', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476056, 'OT', 'Sinunö', 46, 12, 'Yehowa ngahönö andrö nawöda, hati khöda Lowalangi Yakobo.', '["Sin 48:3; RazII 19:21; Yes 12:3","RazII 19:35","Sin 76:4"]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 1, 'Khö duka wanunö andrö. Nilau Ndraono Gora. Sinunö.', '[]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 2, 'Ya''ami, niha fefu, milau datawo! Mi''owua-wua''ö dödömi khö Lowalangi, mi''ebua''ö limi!', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 3, 'Ni''ata''ufi sa Yehowa, Fondrege zalaŵa andrö, razo sebua; barö mbawania guli danö ma''afefu.', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476057, 'OT', 'Sinunö', 47, 4, 'No ibe''e barö mbawada soi niha ba barö gaheda niha baero.', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 5, 'No ituyu khöda dana khöda andrö, lakhömi ma''uwu Yakobo andrö, somasi ia.[1]', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 6, 'No möi misi yaŵa Lowalangi, fao wa''owua-wua dödö; no möi misi yaŵa Yehowa, fao li dorofe.[2]', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 7, 'Misuno Lowalangi, mi''anunö! Misuno razo andrö, mi''anunö!', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 8, 'Razo sa Lowalangi ba guli danö ma''afefu; mi''anunö, si so tödö![3]', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 9, 'Lowalangi zamatörö soi niha. No mudadao Lowalangi ba dadaomania andrö, ni''amoni''ö.', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL),
  (3476057, 'OT', 'Sinunö', 47, 10, 'No owulo zalaŵa soi niha, awö mbanua Lowalangi Gaberahamo andrö; khö Lowalangi sa mbaluse ba guli danö; salaŵa sebua ia.[4]', '["Sin 16:6","Sin 68:19","Sin 93:1","Sin 89:19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 1, 'Sinunö; nilau Ndraono Gora.', '[]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 2, 'Sebua Yehowa ba nisuno sibai ba mbanua Lowalangi andrö, ba hili ni''amoni''ö khönia.[1]', '["Sin 46:5","Ngenu 2:5; Mat 5:35","RazII 19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 3, 'I''alaŵa''ö ia omasiö hili Ziona andrö, fa''omuso dödö nösi guli danö ma''afefu, tanö miyöu, banua razo sebua andrö.[2]', '["Sin 46:5","Ngenu 2:5; Mat 5:35","RazII 19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 4, 'No i''oroma''ö ia Lowalangi, ba gödonia andrö, wa ya''ia mba''a-ba''ania.', '["Sin 46:5","Ngenu 2:5; Mat 5:35","RazII 19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 5, 'Hiza sa, no owulo razo, no so ira moroi sa, dozi.[3]', '["Sin 46:5","Ngenu 2:5; Mat 5:35","RazII 19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 6, 'Ba ha la''ila, ba tobali dödöra, tokea ira ba moloi, ata''u.', '["Sin 46:5","Ngenu 2:5; Mat 5:35","RazII 19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 7, 'Ihawui ira fogikhi ba da''ö ba fanizi-nizi, hulö ba zadono.', '["Sin 46:5","Ngenu 2:5; Mat 5:35","RazII 19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 8, 'Angi timu khöu wamoto nowo Darisi.', '["Sin 46:5","Ngenu 2:5; Mat 5:35","RazII 19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 9, 'Si mane famondrongoma ya''ia wangilama ba mbanua Yehowa ngahönö andrö, ba mbanua Lowalangida; i''aro''ö ia Lowalangi, irugi zi lö aetu.', '["Sin 46:5","Ngenu 2:5; Mat 5:35","RazII 19"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 10, 'Mafatou-tou wa''ebua dödöu andrö, ya''ugö Lowalangi, bakha ba gosali andrö khöu.', '["Yes 25:9"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 11, 'Si mane töimö andrö, ya''ugö Lowalangi, si manö göi wa''aterongo duriamö, irugi ba wondrege danö; no fahöna wa''atulö ba dangau kambölö.', '["Yes 25:9"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 12, 'Omuso dödö hili Ziona andrö, owua-wua dödö nono Yakobo alawe, börö wanguhukumö andrö.', '["Yes 25:9"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 13, 'Mifasui Ziona andrö, milili, mi''erai maligenia.', '["Yes 25:9"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 14, 'Minehegö mba''a-ba''ania andrö, mifaigi gödonia andrö, ena''ö midunö-dunö ba zi sagötö niha dania.', '["Yes 25:9"]', NULL),
  (3476058, 'OT', 'Sinunö', 48, 15, 'Wa no Lowalangida Lowalangi andrö, si lö mamalö-malö; ya''ia zolohe tangada, irugi wa''amate.[4]', '["Yes 25:9"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 1, 'Khö duka wanunö andrö. Nilau Ndraono Gora; Sinunö.[1]', '["Faigi göi Sin 37"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 2, 'Mifondrondrongo, ya''ami, dozi soi! Mibe''e ba dödö, ya''ami sowanua ba guli danö fefu.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 3, 'Ya''ami, ono niha fefu, he so''ana''a ba he numana!', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 4, 'Ilau wa''atua-tua bewegu, ba nifatou-tougu tödögu, ba fangila watahögö.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 5, 'Ube''e mbörö dalingagu ba niŵa''ö, ba ubokai dahö-dahö andrö khögu, wolau biola nitika side-ide.[2]', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 6, 'Hana wa ata''udo, na baŵa si lö sökhi, na tefasui ndra''o, horö zi hundragö ya''odo?', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 7, 'Sabe''e tödö ba zi so khöra ba sanuno ya''ira ba wa''ebua gana''ara andrö.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 8, 'Lö sangila mangöhöli talifusönia, lö sangila mame''e höli khö Lowalangi.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 9, '(Abölö ebua höli nosora; ibato sa''ae, irugi zi lö aetu)[3]', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 10, 'Ena''ö lö aetu nosonia, ena''ö lö i''ila gohokoho.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 11, 'Oroma sa''ae khönia: Mate zatua-tua, tekiko zambö tödö, awö zi lö tödö, laröi ba niha bö''ö zi so khöra.[4]', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 12, 'Lawai lö tebulö nomora, irugi zi lö aetu ba lö mamalö-malö nahiara, götö-götö wa''ara; labe''e töi danö döira andrö.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 13, 'Ba tenga si lö tebulö niha andrö, si so töi; no fagölö-gölö ba zaliŵa-liŵa ba danö andrö, nihori.[5]', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 14, 'Da''ö lala zabe''e tödö ba khöra, ba si so furira dania, ba la''omasi''ö wehedera.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 15, 'Ahöndrö si tou ira, ba mbanua tou, hulö mbiri-biri, fa''amate zokubaloi ya''ira, ba ba zanguhulö wongi andrö, ba sadölö tödö zabölö moroi khöra, ba taya nga''eura; banua tou andrö nahiara.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 16, 'Ba Lowalangi zangefa''ö nosogu ba wa''abölö mbanua tou andrö; ihalö sa ndra''o khönia.[6]', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 17, 'Böi ata''ufi, na so zanöndra ana''a, ba na tedou lakhömi, yomo khönia.[7]', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 18, 'Na mate ia, ba lö''ö sa i''ohe da''ö fefu, lö fao khönia mitou lakhöminia andrö.[8]', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 19, 'He ŵa''ae ifahowu''ö ia ba wa''aurinia — ba he lasuno ndra''ugö, na öhaogö-haogö khöu.[9] —', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 20, 'Ikhamö zi sagötö andrö, ndra amania, si lö mangila haga sa''ae.', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476059, 'OT', 'Sinunö', 49, 21, 'Niha si so lakhömi ba si lö tödö, ba no hulö zaliŵa-liŵa ba danö, nihori dania.[10]', '["Sin 78:2","Mat 16:26","Sangomb 2:16; 6:2","Sangomb 3:19; FetII 2:12","Hos 13:14","Yob 21:7–15","Sangomb 5:13,14","Luk 16:19–31","Ayati 13"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 1, 'Sabölö andrö, Lowalangi, Yehowa, zihede ba si''ao ba danö, i''otarai ba gatumbukha luo, irugi ba gaekhulania.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 2, 'Moroi ba Ziona, fondrege zi zökhi andrö, humaga Lowalangi.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 3, 'So moroi sa Lowalangida ba lö ibato wehede; alitö si manga-manga hadia ia fönania, ba no tefasui ia angi sabölö.[3]', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 4, 'Mu''ao ia ba mbanua si yaŵa, ba ba danö, ba wanguhuku banuania.[4]', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 5, '"Mi''owuloi khögu zatulö andrö khögu, si no fawu''u li khögu ba zumange andrö."[5]', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 6, 'Ba i''ombakha''ö wa''atulönia banua si yaŵa; Lowalangi sa zanguhuku.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 7, 'Mifondrondrongo, ya''ami banuagu, edöna muhede ndra''o; ya''ami Iraono Gizeraeli, da''ufaduhu''ö khömi: Lowalangi ndra''odo, Lowalangimi.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 8, 'Tenga börö zumange andrö khöu, wa utegu ndra''ugö, lö''ö sa tebulö fönagu zumange nitunu andrö khöu.[6]', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 9, 'Lö omasido utema nono zawi, moroi yomo khöu, ba he biri-biri si matua, moroi ba kandra khöu.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 10, 'Khögu sa fefu zaliŵa-liŵa ba danö, barö gatua, urifö niha ba hili, ba ngahönö.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 11, 'U''ila fefu wofo ba hili, ba hadia zaliŵa-liŵa ba mbenua, ba u''ila.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 12, 'Na olofo ndra''o mena''ö, ba lö utunö khöu; khögu sa guli danö, awö nösinia.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 13, 'Hadia, u''a nösi zawi, ba hadia, ubadu ndro mbiri-biri si matua?', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 14, 'Be''e sumange Lowalangi wangandrö saoha gölö, ba bu''a khö Wondrege zalaŵa andrö gamabu''ula limö!', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 15, 'Ba angaröfi li ndra''o, na baŵa wamakao, ba u''orifi ndra''ugö, ba ösuno ndra''o dania.[7]', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 16, 'Ba ba zebua horö iŵa''ö Lowalangi "Hadia wa ötunö gamakhoita andrö khögu, ba hadia wa öhalö ba mbeweu gamabu''ula ligu.[8]', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 17, 'Ba tekhöu sa wamondrongo famobawa lala andrö ba no ö''erogö daroma ligu.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 18, 'Na ö''ila zanagö ba omasi ndra''ugö, ba fao-fao ndra''ugö ba zohorö.[9]', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 19, 'Lö nitahamö beweu, ba zi lö sökhi, ba no ifakhai walimosa lelau.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 20, 'No dumadao ndra''ugö wamatou talifusöu; ono ninau no ötandraŵaisi.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 21, 'Da''ö nilaumö, ba lö sihede ndra''o, ba öwai no fagölö-gölö ndra''o khöu. Ba u''ohe ba huku ndra''ugö, u''oroma''ö khöu.[10]', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 22, 'Ba mitöngöni da''ö, ya''ami solifu Lowalangi, fa böi usasawi ami, si lö sangorifi.', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476060, 'OT', 'Sinunö', 50, 23, 'Same''e sumange fangandrö saoha gölö, da''ö zamolakhömi ya''odo, ba ba zi lö sinegu ba mbua-buania u''oroma''ö wangorifi andrö khö Lowalangi."', '["Sin 96:13","Yes 1:2","MozII 24:4–8","Yes 1:11","Sin 81:8; 91:15; Yob 22:27","Rom 2:21–23","Efes 5:11","Sin 73:11"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 1, 'Khö duka wanunö andrö. Sinunö khö Dawido, me so Natano andrö, sama''ele''ö,', '["SamII 12"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 2, 'me no ihalö dongania Mbaseba andrö Dawido.[1]', '["SamII 12"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 3, 'He Lowalangi, hakhösi tödö ndra''o, ba wa''ebua dödöu andrö; heta golalöŵagu, ba wa''ahakhö dödöu andrö, si no ebua.[2]', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 4, 'Haogö sasai khögu zalagu andrö, haogö ndra''o, heta horögu.', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 5, 'Aboto sa ba dödögu golalöŵagu ba lö tebulö ba duduma hörögu andrö.[3]', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 6, 'Khöu no mosala ndra''odo, ha sambalö khöu; ba no ulau zi lö omasi''ö, ena''ö satulö ndra''ugö, na muhede''ö, ba ena''ö lö hadia ia, ba wanguhukumö andrö.[4]', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 7, 'Hiza, fao zi lö atulö, me tumbu ndra''o ba fao horö, me itemado inagu.[5]', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 8, 'Hiza, omasi ndra''ugö zi duhu, ba dödö, ba botokhi ba dödögu, ba zi tobini, wa''atua-tuamö andrö.', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 9, 'Heta horögu sufo, ena''ö aheta zi ra''i-ra''iö. Sasai ndra''odo, ena''ö afusi ndra''o moroi ba mbetua.[6]', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 10, 'Farongogö khögu wa''omuso dödö ba fa''owua-wua dödö, ena''ö ma''iki dölagu andrö, nirasamö.[7]', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 11, 'Balugö mbawau, böi faigi horögu, ba heta golalöŵagu andrö, fefu.', '["Luk 18:13","Sin 32:5","Rom 3:4,19","Yoh 3:6","MozIII 14:6,7; Yes 1:18","Sin 32:3,4"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 12, 'Asogö khögu dödö sohau-hau, ya''ugö Lowalangi, ba eheha si bohou ba saro, ba dödögu bakha.[8]', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 13, 'Böi tibo''ö ndra''o, fa lö öfaigido sa''ae, ba böi heta khögu Gehehamö andrö, ni''amoni''ö.', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 14, 'Fuli omusoi''ö dödögu fangorifimö andrö, ba abe''e''ö ndra''o eheha sedöna tödö.', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 15, 'Ba ufahaö zolalö, ba lala andrö khömö, ba lafuli ira khöu si so horö.', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 16, 'Efa''ö khögu horö fange''e andrö, ya''ugö Lowalangi, Lowalangi fangorifigu, ba isuno wa''atulömö andrö lelagu.', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 17, 'Bokai mbewegu, So''aya, ena''ö itunö duriamö bawagu andre.', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 18, 'Lö''ö sa omasi''ö zumange, ube''e sa khöu ena''ö, ba sumange nitunu, ba lö ba dödöu.[9]', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 19, 'Sumange Lowalangi andrö, ba ya''ia narö doto si no ombuyu; tödö si no arasa ba si no aboto, ba tenga si lö ba dödöu, ya''ugö Lowalangi.[10]', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 20, 'Lau zi sökhi, ba mbanua Ziona, ba wa''ebua dödöu andrö; a''azökhi göli kara andrö ba Yeruzalema.', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476061, 'OT', 'Sinunö', 51, 21, 'Awena dania omasi ndra''ugö zumange si no atulö, sumange nitunu ba sumange sa''oi so; ba la''ohe ba naha wame''e sumange khöu nono zawi.', '["Hez 36:26","Sin 40:7; 50:8–13","Sin 34:19"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 1, 'Khö duka wanunö andrö, Famahaö; khö Dawido,', '["SamI 22:9–19"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 2, 'me möi khö Zaulo Doegi andrö, Iraono Gedomo, me i''ombakha''ö: "No möi khö Gabimelekhi Dawido."[1]', '["SamI 22:9–19"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 3, 'Hadia wa ösuno''ö ba walösökhi andrö, ya''ugö sabölö? Lö''ö sa mamalö-malö wa''ebua dödö Lowalangi.', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 4, 'Famakiko ifakhai lelau, wolau falimosa, hulö wanöwö wa''atarö.', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 5, 'Omasi ndra''ugö zi lö sökhi, moroi ba zi sökhi, omasi''ö molau faya, moroi ba zi duhu.', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 6, 'Fehede famakiko nilau dödöu, lela falimosa.', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 7, 'Ba ifakiko göi ndra''ugö Lowalangi, i''etu''ögö; ira''u ndra''ugö, itimba''ö baose khöu, ideha''ö ba danö niha sauri.', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 8, 'Ba la''ila satulö ba ata''u, ba la''igi''igi''ö ia (lamane):[2]', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 9, '"Hiza niha andrö, si lö mame''e ba''a-ba''ania Lowalangi, sanötöna ba wa''ebua gana''ania, ba si no abölö ba zi lö sökhi andrö, nilaunia."', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 10, 'Ba ya''odo, ba hulö döla falo sauri, ba nomo Lowalangi, udöna-döna ba wa''ebua dödö Lowalangi andrö, lö mamalö-malö.[3]', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476062, 'OT', 'Sinunö', 52, 11, 'Lö ufamalö-malö wanuno ya''ugö, me no ömanö; udöna-döna ba döimö andrö, si sökhi sa ia, wamaigi zatulö tödö andrö khöu.', '["Sin 91:8","Sin 92:13–16"]', NULL),
  (3476063, 'OT', 'Sinunö', 53, 1, 'Khö duka wanunö andrö; dali Makhalata andrö. Famahaö; khö Dawido. [1]', '["Faigi göi Sin 14"]', NULL),
  (3476063, 'OT', 'Sinunö', 53, 2, 'Iŵa''ö tödönia sowöhö mowa: "Lö Lowalangi." No lalau zi lö sökhi, manao horö ira, sogoro ita; samösa lö solau si sökhi.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476063, 'OT', 'Sinunö', 53, 3, 'No ifaigi mitou nono niha Lowalangi, ena''ö i''ila, na so zamösa satua-tua sanofu Lowalangi.', '[]', NULL),
  (3476063, 'OT', 'Sinunö', 53, 4, 'No ahori fabali ira, dozi no tekiko; lö solau si sökhi, samösa lö''ö.', '[]', NULL),
  (3476063, 'OT', 'Sinunö', 53, 5, 'Hadia, lö fa''aboto ba dödö zolau si lö sökhi? Si manga mbanuagu nifemanga roti, ba lö''ö sa la''angaröfi li Lowalangi.', '[]', NULL),
  (3476063, 'OT', 'Sinunö', 53, 6, 'Ba da''ö ihawui ira fa''ata''u, lö lai wa lö börö wa''ata''u; ifazawili sa Lowalangi döla zanuwö ya''ugö. Aila ira öbe''e, me no itibo''ö ira Lowalangi.', '[]', NULL),
  (3476063, 'OT', 'Sinunö', 53, 7, 'Ena''ö na so wangorifi Ndraono Gizeraeli andrö, si otarai Ziona! Na i''efa''ö mbanuania Lowalangi ba gurungara andrö, ba ma''iki Ndraono Yakobo, omuso dödö Ndraono Gizeraeli andrö.', '[]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 1, 'Khö duka wanuno andrö, fao mbiola. Famahaö; khö Dawido, me so mbanua Zifi andrö,', '["SamI 23:19; 26:1"]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 2, 'me lamane khö Zaulo: "Hadia, tenga ba khöma ibini''ö ia Dawido?"[1]', '["SamI 23:19; 26:1"]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 3, 'He Lowalangi! Orifi ndra''odo töimö andrö; ohe ba zatulö, ba wa''abölömö andrö.', '["Sin 59:11"]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 4, 'Fondrondrongo wangandrögu Lowalangi, be''e mbörö dalingau ba wehede mbewegu andre.', '["Sin 59:11"]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 5, 'Noa sa maoso niha bö''ö, udugu, sabölö zangalui famunu ya''odo; lö ba duduma höröra Lowalangi.', '["Sin 59:11"]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 6, 'Hiza, Lowalangi zanolo ya''o, So''aya zanganau''ö nosogu.', '["Sin 59:11"]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 7, 'Mangandrauli ba zi fa''udu khögu zi lö sökhi andrö; fakiko ira, ba wa''aduhumö andrö!', '["Sin 59:11"]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 8, 'Ba ufosumange ndra''ugö, soroi ba dödö, usuno döimö andrö, ya''ugö Yehowa, me no si sökhi.', '["Sin 59:11"]', NULL),
  (3476064, 'OT', 'Sinunö', 54, 9, 'Noa sa i''orifi ndra''o ba wa''abu dödö andrö fefu; wa''omasigu wamaigigu si fa''udu khögu andrö.[2]', '["Sin 59:11"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 1, 'Khö duka wanunö andrö; fao wolau biola. Famahaö; khö Dawido.', '[]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 2, 'Be''e mbörö dalingau, ya''ugö Lowalangi, ba wangandrögu andre; böi bini''ö ndra''ugö, na u''angaröfi li ndra''ugö!', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 3, 'Faigi ndra''o ba fondrondrongo khögu; elungu-lungu misa ndra''o ba wangarö-ngarögu andre, ba me''e dödögu.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 4, 'Ba wagua-guasa zi fa''udu andrö ba ba wamalangögö zebua horö awöra; lahawui sa''ae ndra''o famakiko ba abölö sibai watiusara khögu.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 5, 'Manizi bakha dödögu ba no ihawui ndra''o fa''ata''ugu wa''amate.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 6, 'Ata''u ndra''o ba mogikhido ba ibalugö ndra''o fehokha mbu.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 7, 'Ba umane: Ena''ö mo''afi ndra''odo, si mane marafadi, ba muhombo ena''ö ndra''o misa, fa ahono ndra''odo.[1]', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 8, 'Hiza, usaŵa zaröu ena''ö, ba u''iagö danö si mate.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 9, 'U''aliogö ena''ö woloi, usaŵa zi lö gönado angi ba teu laöhö.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 10, 'Fakiko ira, So''aya, fabali lelara! Noa sa u''ila wamalangögö ba fasosota ba mbanua.[2]', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 11, 'Bongi ma''ökhö lafasui ba dete göli, ba famakuyu ba fangabu dödö bakha.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 12, 'Famakiko bakha; famalangögö awöra ba falimosa lö mamalö ba kade khöra.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 13, 'Tenga sa si fa''udu zango''aya ya''odo; na si manö, ba utaha; tenga si fatiu zi fayaŵa khögu; na si manö, ba ubini''ö ena''ö ndra''o khönia.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 14, 'Ya''ugo sa''ae, niha si mane ya''odo, si fahuwu ba si no fa''ila li khögu.[3]', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 15, 'No fahuo-huo ita ba zi ha ya''ita, no fao ita we''amöi ba nomo Lowalangi, awö zato andrö.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 16, 'Yamukhamö ira fa''amate si lö mudöna-döna, ndramusaŵa mbanua tou, auri! Si lö sökhi sa ba nomora, ba dödöra bakha.', '["Sin 11:1","SamII 17:14","Sin 41:10; SamII 15:12"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 17, 'Ba ya''odo, ba u''angaröfi li Lowalangi, ba i''orifi ndra''o Yehowa.', '["Sin 102:27","Yer 9:7; Sin 57:5","FetI 5:7","Sin 102:25"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 18, 'Na owi ba na mahemolu mbanua ba na laluo mangarö-ngarö ndra''o, ba me''e ndra''o, ba ifondrondrongo ligu.', '["Sin 102:27","Yer 9:7; Sin 57:5","FetI 5:7","Sin 102:25"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 19, 'I''orifi nosogu, i''atulö''ö, fa böi lalau khögu, ato sa''ae zi fa''udu khögu.', '["Sin 102:27","Yer 9:7; Sin 57:5","FetI 5:7","Sin 102:25"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 20, 'Ifondrondrongo Lowalangi ba ihöndrögö ira, sidadao sa ia, no arara; lö''ö sa lafalalini gera-erara ba lö la''ata''ufi Lowalangi.[4]', '["Sin 102:27","Yer 9:7; Sin 57:5","FetI 5:7","Sin 102:25"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 21, 'No i''oro''ö dangania, wombambaya si no atulö khönia, no ibe''e ba zalakha wawu''usa li andrö khönia.', '["Sin 102:27","Yer 9:7; Sin 57:5","FetI 5:7","Sin 102:25"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 22, 'Hulö dawö mbawi wa''alösö mbewenia, ba fanuwö dödönia; salösö moroi ba wanikha wehedenia, ba si ndruhunia, ba bawa wöda.[5]', '["Sin 102:27","Yer 9:7; Sin 57:5","FetI 5:7","Sin 102:25"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 23, 'Be''e noro Yehowa norou andrö, ba i''orifi''ö, lö ibe''e mangiwa zatulö tödö, irugi zi lö aetu.[6]', '["Sin 102:27","Yer 9:7; Sin 57:5","FetI 5:7","Sin 102:25"]', NULL),
  (3476065, 'OT', 'Sinunö', 55, 24, 'Ba ya''ugö Lowalangi zanimba ya''ira si tou ba mbawa gohokoho; sange''enge''e andrö ba si falimolimo andrö, ba lö ikhamö talu niha nosora, ba ya''odo, ba sanötöna khöu.[7]', '["Sin 102:27","Yer 9:7; Sin 57:5","FetI 5:7","Sin 102:25"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 1, 'Khö duka wanunö andrö, dali: "Marafadi si lö li, ba niha bö''ö;" khö Dawido; umanö, me lara''u ia Dawa Wilisiti ba Gata.[1]', '["SamI 21:11–16"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 2, 'Hakhösi tödö ndra''o, Lowalangi, la''isö sa''ae ndra''o niha, lasasagö ndra''o sanuwö, si lö mamalö-malö.', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 3, 'Ma''oma''ökhö la''isö ndra''o si fa''udu khögu; ato sa''ae zi fasuwö khögu, sebua hokha.', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 4, 'Na luo ata''u ndra''o, ba manötöna ndra''o khöu.', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 5, 'Moroi ba Lowalangi wa usuno daroma linia; khö Lowalangi manötöna ndra''odo, lö ata''udo; hadia nilau nösi niha khögu?[2]', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 6, 'Ma''öma''ökhö latandraŵaisi ligu; ha sambalö ba zi lö sökhi aekhu gera-erara khögu.', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 7, 'Orudu ira, manaronaro; ladaro-darogö mbekagu, si mane sangalui famunu ya''odo.', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 8, 'Hadia, ni''orifi ira ba horöra andrö? Timba tou soi niha andrö, ya''ugö Lowalangi, ba wönumö.[3]', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 9, 'No ö''erai woloiloigu andrö. Be''e ba nahia andrö khöu daŵa hörögu andrö. Tenga no so ia ba zura khöu?', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 10, 'Ba lafuli ira furi sanuwö ya''odo, na luo mu''ao ndra''o; lö mangiwa dödögu, wa no awögu Lowalangi.', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 11, 'Moroi ba Lowalangi wa usuno daroma linia andrö. Moroi ba khö Yehowa usuno daroma li andrö.', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 12, 'Khö Lowalangi udöna-döna; lö ata''u ndra''odo; hadia nilau niha khögu?', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 13, 'Hadia nifabu''ugu khöu, ba ömögu, ya''ugö Lowalangi: ubu''a khöu zumange fangandrö saoha gölö!', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476067, 'OT', 'Sinunö', 56, 14, 'Noa sa ö''efa''ö nosogu ba wa''amate, lö ahele gahegu öbe''e ae, ena''ö föna Lowalangi mowaö-waö ndra''o ba haga zauri.[4]', '["Sin 27:1; 118:6; Yes 12:2; 51:12; Heb 13:6","Sin 55:24","Sin 116:8; Yob 33:30"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 1, 'Khö duka wanunö andrö, dali: "Böi fakiko!" Khö Dawido; umanö, me moloi ia, khö Zaulo, me isaŵa dögi narö hili andrö.[1]', '["SamI 22:1"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 2, 'Hakhösi tödö ndra''o, Lowalangi, hakhösi tödö ndra''o! Khöu sa''ae isaŵa tödögu, ba lumö gafiu u''alui zaŵatö khögu, irege no numalö misa wamakiko andrö.[2]', '["Sin 91:1,2","Sin 7:16"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 3, 'Khö Lowalangi, Fondrege zalaŵa mu''ao ndra''odo, khö Lowalangi andrö, sangasiwai huhuogu.', '["Sin 91:1,2","Sin 7:16"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 4, 'Ifatenge moroi si yaŵa ba zorugo, i''orifi ndra''odo, ibe''e ni''o''aya zangisö ya''odo andrö; ifa''ohe''ö Lowalangi wa''ebua dödönia ba fa''aduhunia andrö.', '["Sin 91:1,2","Sin 7:16"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 5, 'Ba hunö zingo so nosogu; awö zamalua hola-hola galitö ndra''o tou, awö nono niha so''ifö toho ba ono wana, si so lela föda satarö.', '["Sin 91:1,2","Sin 7:16"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 6, 'Ae yaŵa, Lowalangi, yaŵa mbanua si yaŵa, ya tehawui guli danö ma''asagörö lakhömimö andrö!', '["Sin 91:1,2","Sin 7:16"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 7, 'No lalau gu''ö gahegu, no lafaöndrö dödögu; no lakharu lösu-lösu fönagu, ba ya''ira zaekhu bakha.[3]', '["Sin 91:1,2","Sin 7:16"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 8, 'Abe''e dödögu, Lowalangi, abe''e dödögu, manunö ndra''o ba ulau mbiola.[4]', '["Ayati 8–12: Sin 108:2–6","Sin 16:9","Sin 36:6"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 9, 'Faoso, tödögu, faoso biola nitika sebua ba biola nitika side-ide! da''ususugi wa''amoluo.[5]', '["Ayati 8–12: Sin 108:2–6","Sin 16:9","Sin 36:6"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 10, 'Usuno ndra''ugö, So''aya, ba niha misa; ulau numanö khöu ba niha baero.', '["Ayati 8–12: Sin 108:2–6","Sin 16:9","Sin 36:6"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 11, 'Abölö sibai sa wa''ebua dödöu, irugi mbanua si yaŵa, ba irugi lawuo wa''aduhumö andrö.[6]', '["Ayati 8–12: Sin 108:2–6","Sin 16:9","Sin 36:6"]', NULL),
  (3476068, 'OT', 'Sinunö', 57, 12, 'Ae yaŵa, Lowalangi, yaŵa mbanua si yaŵa; ya tehawui guli danö ma''asagörö lakhömimö andrö!', '["Ayati 8–12: Sin 108:2–6","Sin 16:9","Sin 36:6"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 1, 'Khö duka wanunö andrö, dali: "Böi fakiko": khö Dawido; umanö.', '[]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 2, 'Hadia, si ndruhu satulö niŵa''ömi, ya''ami Lowalangi, no adölö wanguhukumi ono niha?[1]', '["Sin 82","Sangomb 10:11"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 3, 'Famuyu sa''ae mifakhai tödömi, famalangögö itulo tangami, ba danö.', '["Sin 82","Sangomb 10:11"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 4, 'Sebua horö andrö, ba no fabali, i''otarai dalu ninara, ba solau faya andrö, ba no elungu, i''otarai wa''atumbura.', '["Sin 82","Sangomb 10:11"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 5, 'Timba zöfu gulö zöfura andrö, hulö zöfu gulö safiso, sanozo tögi dalingania.', '["Sin 82","Sangomb 10:11"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 6, 'Si lö mamondrongo li zi fakelemu, li zi no to''ölö fanaka.[2]', '["Sin 82","Sangomb 10:11"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 7, 'He Lowalangi, teu niföra ba mbawara andrö; rasa mboha nono zingo andrö, ya''ugö Yehowa.', '["Sin 7:9"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 8, 'Ena''ö mangulu ira, ena''ö tobali idanö, sahele misa; na ifaudugö nono wana andrö khönia, ba ya hulö nifalo''o.', '["Sin 7:9"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 9, 'Ya hulö mbae''a ira, sangulu barö wananania andrö, hulö dabina saekhu, si lö mangila haga zi moluo.', '["Sin 7:9"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 10, 'Ya lö fakhamö la''ila zodoi andrö bowoami, ba ibözini auri ia (Lowalangi)', '["Sin 7:9"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 11, 'Omuso dania dödö zatulö tödö, na i''ila wolau balö andrö; isasai dania gahenia ba ndro zebua horö andrö.', '["Sin 7:9"]', NULL),
  (3476069, 'OT', 'Sinunö', 58, 12, 'Ba lamane dania: "Si ndruhu, moböli gölö zatulö tödö andrö; tenga faya, so Lowalangi, sanguhuku ba guli danö.[3]', '["Sin 7:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 1, 'Khö duka wanunö andrö, dali: "Böi fakiko;" khö Dawido; umanö; me ifatenge Saulo, me latarogö Dawido barö nomo, ba wamunu ya''ia.[1]', '["SamI 19:11"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 2, 'Tolodo, Lowalangi, ba zi fa''udu andrö khögu; ba zi lö gönado hadia ia fataro ndra''o, ba zi maoso andrö, udugu.', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 3, 'Efa''ö ndra''o ba zanao horö ba tolodo, ba zange''enge''e andrö.', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 4, 'Hiza sa, latarogö nosogu, orudu zabölö, udugu; ba lö salagu ba lö horögu, ya''ugö Lowalangi.', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 5, 'Fagohi ira, lö lai wa lö horögu, ba lafa''anö ira. Faoso, faondragö ndra''odo ba faigi.[2]', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 6, 'Ba ya''ugö Yehowa, Lowalangi ngahönö, Lowalangi Ndraono Gizeraeli, faoso, ba wanguhuku niha baero, fefu! Samösa böi hakhösi tödö, si manga mböli andrö, sanao horö.', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 7, 'Na bongi mangawuli ira, mukao, hulö nasu, ba lafasui mbanua.[3]', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 8, 'Hiza, manandraŵa mbawara, föda ba mbewera, lamane: "Ha niha zamondrongo?"', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 9, 'Ba ö''igi''igi''ö ira, ya''ugö Yehowa, ayau niha baero, fefu.', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 10, 'Fa''abölögu ndra''ugö, khöu manötöna ndra''odo; hatigu sa Lowalangi.[4]', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 11, 'Ifaondragö khögu wa''ebua dödönia Lowalangigu andrö; wa''omasigu wamaigi si fa''udu khögu, ibe''e Lowalangi.[5]', '["Sin 44:24","Ayati 15","Sin 2:4","Sin 54:9"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 12, 'Böi bunu ira, ena''ö lö olifu mbanuagu; fazawili ira fa''abölömö andrö ba timba tou ira, yaugö So''aya, balusema!', '["Ayati 7"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 13, 'Horö mbawara daroma li mbewera andrö; ena''ö tefa''u''u ira ba hokhara andrö ba ba wangelifi andrö, ba ba waya andrö, nilaura.', '["Ayati 7"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 14, 'Fakiko ira, ba wönumö andrö, fakiko, ena''ö lö ya''ira sa''ae, ena''ö aboto ba dödöra, Lowalangi zamatörö Iraono Yakobo, irugi ba wondrege danö.', '["Ayati 7"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 15, 'Ba ero owi, ba mangawuli ira, mukao, hulö nasu, ba lafasui mbanua.[6]', '["Ayati 7"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 16, 'Mowaö-waö misa ba wangalui gö; ba na lö abuso ira, ba la''osarawongigö.', '["Ayati 7"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 17, 'Ba ya''odo, ba usuno wa''abölöu, ba ba zanguhulö wongi, ba owua-wua dödögu wa''ebua dödöu andrö; noa sa''ae hatigu ndra''ugö ba saŵatögu, me baŵa wa''atosasagu.', '["Ayati 7"]', NULL),
  (3476070, 'OT', 'Sinunö', 59, 18, 'Da''usuno ndra''ugö, ya''ugö fa''abölögu; hatigu sa Lowalangi, Lowalangigu andrö, sebua tödö.', '["Ayati 7"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 1, 'Khö duka wanunö andrö, dali: "Ladari mböhö ba wamaduhu''ö"; umanö; khö Dawido; famahaö,', '["Sin 44; SamII 8:3,13 b.t.; 10:13,18"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 2, 'me fasuwö ia ba Ndrawa Ziria ba Mezofatamia ba ba Zoba, me mangawuli Yoabi, me i''alani Ndraono Gedomo ba ndraso nasio, si felendrua ngahönö.[1]', '["Sin 44; SamII 8:3,13 b.t.; 10:13,18"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 3, 'He Lowalangi, no ötibo''ö ndra''aga, no öfazawiliga; sofönu ndra''ugö; ohe mangawuli ndra''aga.', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 4, 'No öfahisi danö, no öfabali; fadöhö zasilania, humeu sa''ae.', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 5, 'Fa''abe''e ni''oroma''öu ba mbanuau andrö: no öfabadugö khöma nagu, salimbuanö ndra''aga.[2]', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 6, 'Ba ba zangata''ufi ya''ugö, ba no öbe''e dandra, ena''ö lafazaŵa ira, börö zi duhu andrö.[3] [4]', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476071, 'OT', 'Sinunö', 60, 7, 'Ba ena''ö auri zomasi ndra''ugö, ba tologa tangau kambölö ba fondrondrongo khöma.', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 8, 'No muhede Lowalangi, ba wa''ohau-haunia andrö: Sowua-wua tödö ndra''odo, ufosasi Zikhema ba usu''a ndraso Zukota.', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 9, 'Khögu mado Gileadi, ba khögu mado Manase; nöugu ba högögu mado Geferayi ba si''o zalaŵa khögu mado Yuda.[5]', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 10, 'Naha wanasa khögu Ndraono Moabi, ba Ndraono Gedomo ufazaumba mbadagahegu, ba sowua-wua tödö ndra''ugö khögu, ya''ugö tanö Ndrawa Wilisiti.', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 11, 'Ha niha zolohe ya''odo ba mbanua saro? Ha niha zamasao ya''o, irugi ba Ndraono Gedomo?', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 12, 'Hadia, tenga ya''ugö zanibo''ö ya''aga, Lowalangi, ba si lö möi awö zanuwö andrö khöma, ya''ugö Lowalangi?', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 13, 'Tologa, ba zanasagö ya''aga andrö; faya sa''ae wangorifi ba niha!', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476071, 'OT', 'Sinunö', 60, 14, 'Na awö Lowalangi, ba malau, nifolau zabölö; ya''ia zi hundragö tou sanasagö ya''aga.', '["Yes 51:17,22","Sin 20:6","Ayati 5–12: Sin 108:7–14","MozI 49:10"]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 1, 'Khö duka wanunö andrö, nilau biola; khö Dawido.', '[]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 2, 'Fondrondrongo Lowalangi, wangarö-ngaröngu andre, be''e mbörö dalingau ba wangandrögu!', '["Sin 18:2,3; 71:3","Sin 63:3","Sin 21:5","SamII 7:16"]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 3, 'Moroi ba wondrege danö mu''aodo khöu, na olofo dödögu; ohedo yaŵa ba dete gara, sabölö alaŵa khögu.', '["Sin 18:2,3; 71:3","Sin 63:3","Sin 21:5","SamII 7:16"]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 4, 'Saŵatö sa''ae ndra''ugö khögu, hati saro, ba nemali andrö.[1]', '["Sin 18:2,3; 71:3","Sin 63:3","Sin 21:5","SamII 7:16"]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 5, 'Ba nose khöu sodo, irugi zi lö aetu, usöndra wangorifi, na ibalugödo afiu.[2]', '["Sin 18:2,3; 71:3","Sin 63:3","Sin 21:5","SamII 7:16"]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 6, 'Noa sa öfondrondrongo gamabu''ula ligu andrö, ya''ugö Lowalangi, no öbe''e khögu dana zangata''ufi töimö.', '["Sin 18:2,3; 71:3","Sin 63:3","Sin 21:5","SamII 7:16"]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 7, 'Ö''anau''ö noso razo, ena''ö götö-götö wa''ara ndröfinia.[3]', '["Sin 18:2,3; 71:3","Sin 63:3","Sin 21:5","SamII 7:16"]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 8, 'Lö tebulö ia ba gametahö Lowalangi, irugi zi lö aetu; oroi ö wa''ebua dödö ba fa''aduhu, ba wondrorogö ya''ia.[4]', '["Sin 18:2,3; 71:3","Sin 63:3","Sin 21:5","SamII 7:16"]', NULL),
  (3476072, 'OT', 'Sinunö', 61, 9, 'Ba usuno döimö andrö si lö mamalö-malö, wamu''a amabu''ula ligu andrö, ero ma''ökhö.', '["Sin 18:2,3; 71:3","Sin 63:3","Sin 21:5","SamII 7:16"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 1, 'Khö duka wanunö andrö, khö Yedutuno andrö, nilau Dawido.[1]', '["Nga''ötI 25:1"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 2, 'Ha khö Lowalangi manötöna dödögu, no ahono-hono, khönia i''otarai wangorifigu.[2]', '["Yes 30:15","Sin 18:2,3","Sin 61:4"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 3, 'Ha ya''ia we''e-we''e dödögu ba fangorifigu, hatigu, tebai manö mangiwa ndra''o.', '["Yes 30:15","Sin 18:2,3","Sin 61:4"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 4, 'Heza irugi misuwö niha si ha samösa, wa edöna midudugö ia, hulö mbagolö si no aolo, hulö göli kara, si no muhisi?', '["Yes 30:15","Sin 18:2,3","Sin 61:4"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 5, 'Ha da''ö wamagölöra, he lawisa wanimba tou ya''ia, moroi ba nahania salaŵa; faya zomasi ira; ba mbewera, ba famahowu, ba ba dödöra, ba fangelifi.', '["Yes 30:15","Sin 18:2,3","Sin 61:4"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 6, 'Ha khö Lowalangi manötöna dödögu, no ahono-hono, khönia sa''ae i''otarai fangorifigu.', '["Yes 30:15","Sin 18:2,3","Sin 61:4"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 7, 'Ha ya''ia we''e-we''e dödögu ba fangorifigu, hatigu saro; tebai manö mangiwa ndra''o.[3]', '["Yes 30:15","Sin 18:2,3","Sin 61:4"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 8, 'Khö Lowalangi usöndra wangorifigu ba turiagu; dane-dane wa''abe''egu ba fanötönagu, ba khö Lowalangi so.[4]', '["Yes 30:15","Sin 18:2,3","Sin 61:4"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 9, 'Böi ya mamalö-malö wanötönami khönia, ya''ami ono niha; mibokai dödömi khönia; tötönaföda Lowalangi.', '["Yes 30:15","Sin 18:2,3","Sin 61:4"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 10, 'Faya-faya manö nono niha, faya nono zalaŵa; na latulo, ba isaŵa yaŵa; dozi ira, ba no angi.', '["Mat 19:22; Luk 12:19,20; TimI 6:17","Rom 2:6–11"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 11, 'Böi midöna-döna ba wemanga gana''a ba böi mohokha ami ba nirabu; na misöndra gana''a, ba böi molemba dödömi khönia.[5]', '["Mat 19:22; Luk 12:19,20; TimI 6:17","Rom 2:6–11"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 12, 'Samuza no muhede Lowalangi, no mendrua urongo da''ö, wa no khö Lowalangi wa''abölö.', '["Mat 19:22; Luk 12:19,20; TimI 6:17","Rom 2:6–11"]', NULL),
  (3476073, 'OT', 'Sinunö', 62, 13, 'Ba khöu wa''ebua dödö, ya''ugö So''aya: ösulöni sa ba zamösana nilaunia.[6]', '["Mat 19:22; Luk 12:19,20; TimI 6:17","Rom 2:6–11"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 1, 'Sinunö khö Dawido, me so ia ba danö si mate, tanö mado Yuda.[1]', '["SamI 22:5; 23:14; 24:1"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 2, 'He Lowalangi, Lowalangigu ndra''ugö, uhulö wongi wangalui ya''ugö; owökhi dödögu khöu, no sodufodufo lela nösigu, ba danö si mate, si no oköliköli, si lö idanö.[2]', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 3, 'Si manö wamaigigu ya''ugö, ba ni''amoni''ö andrö, ena''ö u''ila wa''abölöu, awö lakhömiu andrö.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 4, 'Sökhi moroi ba wa''auri wa''ebua dödöu andrö. Isuno ndra''ugö bewegu.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 5, 'Ba götö wa''anau nosogu usuno ndra''ugö, ufazaŵa dangagu ba döimö andrö.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 6, 'Hulö ni''abusoi''ö uto döla ba tawö dödögu, ba manunö mbawagu, ma''iki mbewegu.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 7, 'Na itörö tödögu ndra''ugö ba gasogu; ufatou-tou tödögu ndra''ugö ba zi bongi.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 8, 'Fanologu sa''ae ndra''ugö, ba ba lumö gafiu andrö ma''iki ndra''odo.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 9, 'Lö iböhöli ndra''ugö tödögu; ituwu ndra''odo tangau kambölö.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 10, 'Ba ya''ira, sangalui nosogu, ba wamakiko ya''odo, ba ba wondrege gohokoho danö nahara dania.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 11, 'Ba mbawa zi''öli tetou''ö ira, ba ö nasu ana''a ira dania.', '["Sin 42:3; 143:6"]', NULL),
  (3476074, 'OT', 'Sinunö', 63, 12, 'Ba omuso dödö razo ba khö Lowalangi; lasuno ira dozi si fahölu ba khönia; tefa''afu sa''ae mbawa zolau faya.', '["Sin 42:3; 143:6"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 1, 'Khö duka wanunö andrö, sinunö; khö Dawido.', '[]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 2, 'Fondrondrongo ligu Lowalangi, ba wangarö-ngarö andre; orifi ndra''o, ba gameta''uö emali andrö.', '["Sin 57:5","Sin 11:2","Sin 94:7"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 3, 'Bini''ö ndra''o, ba wamagölö zanao horö andrö, si no tobini; ba zolau si lö sökhi andrö, si no orudu, si fagua-gua.', '["Sin 57:5","Sin 11:2","Sin 94:7"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 4, 'Sangatarösi lelara, fa hulö nikhu gari: lafo''ösi wanara fehede safökhö.[1]', '["Sin 57:5","Sin 11:2","Sin 94:7"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 5, 'Ba wamana satulö tödö andrö, ba zi lö oroma; lafana ia lö mudöna-döna, lö ata''u ira.[2]', '["Sin 57:5","Sin 11:2","Sin 94:7"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 6, 'Abe''e ira ba wolau si lö sökhi, itörö lira wolau fesu, ba lamane: Ha niha zangila?[3]', '["Sin 57:5","Sin 11:2","Sin 94:7"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 7, 'Lafakhai zi lö sökhi, lamane: "No awai khöda, no tafagölösi." Ba arö doto niha ba tödönia, ba no abakha.', '["Sin 57:5","Sin 11:2","Sin 94:7"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 8, 'Ba ifana ira Lowalangi; so nono wana si lö mudöna-döna ba mesokho ira.', '["Sin 7:16"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 9, 'Ba salau tou ira, ilangö ira lelara, ba dozi sangila ya''ira, ba lafatalikhö ira.[4]', '["Sin 7:16"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 10, 'Ba ata''u niha fefu, ba ladunö-dunö wolau Lowalangi andrö, ba aboto ba dödöra halöŵönia.', '["Sin 7:16"]', NULL),
  (3476075, 'OT', 'Sinunö', 64, 11, 'Ba omuso dödö zatulö tödö andrö, ba khö Yehowa, ba abe''e dödönia khönia; ba lasuno ira dozi sadölö tödö.', '["Sin 7:16"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 1, 'Khö duka wanunö andrö; umanö; khö Dawido; sinunö.', '[]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 2, 'Si nangea nisuno ndra''ugö, ba Ziona, ya''ugö Lowalangi; labu''a khöu gamabu''ula li andrö.', '["Sin 84","Sin 89:10"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 3, 'Samondrondrongo fangandrö ndra''ugö; dozi niha mangondrasi ya''ugö.', '["Sin 84","Sin 89:10"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 4, 'No ilangö ndra''o ngawalö golalöŵa; ba salama andrö, ba ya''ugö zangefa''ö.', '["Sin 84","Sin 89:10"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 5, 'Ya ahowu nituyumö, niteheu fa''ahatö khöu, ena''ö ba golayamamö so ia; abuso ndra''aga si sökhi andrö, ba nomo khöu, awö ni''amoni''ö andrö ba gosalimö andrö.[1]', '["Sin 84","Sin 89:10"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 6, 'Ötema lima sata''u ndra''aga, ba wa''atulö, ya''ugö Lowalangi fangorifima, saŵatö nösi guli danö fefu, irugi ba wondrege, awö nösi nasi, fondrege zaröu.', '["Sin 84","Sin 89:10"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 7, 'Samedadao hili andrö, ba wa''abölönia, si no mamöbö talu fa''abe''e.', '["Sin 84","Sin 89:10"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 8, 'Sangahonogö ugu-ugu nasi andrö, awö wegoso-goso ndrulu andrö, awö wagua-guasa soi niha, andrö.[2]', '["Sin 84","Sin 89:10"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 9, 'Ba la''ata''ufi dandra andrö khöu si so ba wondrege danö; owua-wua dödö niha öbe''e, ba gatumbukha luo ba ba gaekhula.', '["Sin 84","Sin 89:10"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 10, 'No ötörö danö, wamaigi ya''ia, öfatörö khönia nidanö, abölö mbuania öbe''e. Ba gumbu andrö khö Lowalangi, ba no fahöna nidanö. Öfowua khöra danö; si manö sa wangazökhiu ya''ia.[3]', '["Sin 40:5","Sin 104:13–16"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 11, 'Öfo''idanö gowotonia, fangombuyu nifaku andrö; adudu öbe''e, ba deu andrö, öfahowu''ö zinanö khönia.[4]', '["Sin 40:5","Sin 104:13–16"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 12, 'No öfo''aya ba högö ndröfi wa''ebua dödöu andrö; sahele fanikha laheu andrö.', '["Sin 40:5","Sin 104:13–16"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 13, 'Mowöi ndraso ba danö si mate, ba la''okaero wa''owua-wua dödö hili.', '["Sin 40:5","Sin 104:13–16"]', NULL),
  (3476077, 'OT', 'Sinunö', 65, 14, 'Tefo''aya biri-biri mbenua ba tefobalu-balu bua danö ndraso; oi owua-wua dödö, oi manunö.', '["Sin 40:5","Sin 104:13–16"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 1, 'Mi''owua-wua''ö dödömi khö Lowalangi, dozi tanö!', '["MozII 14:21; Yos 3:17"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 2, 'Misuno duria döinia andrö, mibe''e zumange fanuno ya''ia.', '["MozII 14:21; Yos 3:17"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 3, 'Mimane khö Lowalangi: "Ha lö ata''u ita wolaumö andrö! Börö wa''abölöu wa laköwö ira fönau si fa''udu khöu.', '["MozII 14:21; Yos 3:17"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 4, 'Dozi tanö mangalulu khöu dania, ba lasuno ndra''ugö, ladunö-dunö döimö andrö."', '["MozII 14:21; Yos 3:17"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 5, 'Mitabu, mifaigi halöŵö Lowalangi andrö; sata''u ita nilaunia ba nono niha.', '["MozII 14:21; Yos 3:17"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 6, 'No ibali''ö tanö sabe''e nasi andrö; latörö tanö nungo idanö andrö, ba no omuso dödöda khönia ba da''ö.[1]', '["MozII 14:21; Yos 3:17"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 7, 'Samatörö ia si lö mamalö-malö, ba wa''abölönia andrö; ifaigi-faigi hörönia soi niha andrö; tebai maoso zi fatandro andrö.', '["MozII 14:21; Yos 3:17"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 8, 'Misuno Lowalangida andrö, ya''ami soi niha, mi''ebua''ö limi, wanutunö turiania.', '["Amaed 3:3","Yes 43:2"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 9, 'Sanganau''ö nosoda, ba si lö mame''e ahele gaheda.', '["Amaed 3:3","Yes 43:2"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 10, 'Noa sa ötandraigö ndra''aga, ya''ugö Lowalangi, no ölaugö ndra''aga, nifolaugö firö.[2]', '["Amaed 3:3","Yes 43:2"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 11, 'No öfa''u''u ndra''aga ba gu''ö, ba no öfonoro sabua zolama.', '["Amaed 3:3","Yes 43:2"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 12, 'No öfatörö ba högöma yaŵa niha, ba galitö ba ba nidanö marugi, ba no ö''ohe yaŵa ndra''aga ba zebolo tanö.[3]', '["Amaed 3:3","Yes 43:2"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 13, 'Möido ba gosali khöu, u''ohe zumange nitunu ba ubu''a khöu gamabu''ula ligu andrö,', '["Amaed 28:9; Yoh 9:31"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 14, 'nifabokagu bewegu, si no alua ba mbawagu, ba wa''atosasagu andrö.', '["Amaed 28:9; Yoh 9:31"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 15, 'U''ohe khöu zumange nitunu, satabö, awö mbiri-biri si matua, samohua ba galitö; sawi ba biri-biri si matua ube''e sumange.', '["Amaed 28:9; Yoh 9:31"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 16, 'Mi''aine, mifondrondrongo, dozi ami, sangata''ufi Lowalangi, ba udunö-dunö nilaunia ba nosogu andre,', '["Amaed 28:9; Yoh 9:31"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 17, 'Khönia mu''ao mbawagu, fanuno ba lelagu.', '["Amaed 28:9; Yoh 9:31"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 18, 'Na no ufakhai mena''ö zi lö atulö, tödögu, ba lö ifondrondrongo mena''ö ligu So''aya.[4]', '["Amaed 28:9; Yoh 9:31"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 19, 'Ba no ifondrondrongo Lowalangi, no ibe''e ba dödönia li wangandrögu andrö.', '["Amaed 28:9; Yoh 9:31"]', NULL),
  (3476078, 'OT', 'Sinunö', 66, 20, 'Nisuno Lowalangi, si lö mangositengagö wangandrögu andrö, si lö mamöda fa''ebua dödönia khögu.', '["Amaed 28:9; Yoh 9:31"]', NULL),
  (3476079, 'OT', 'Sinunö', 67, 1, 'Khö duka wanunö andrö; sinunö; umanö.', '[]', NULL),
  (3476079, 'OT', 'Sinunö', 67, 2, 'Yamu''ebua''ö dödönia khöda Lowalangi ba yamufahowu''ö ita; yamufohaga mbawania khöda.[1]', '["MozIV 6:24,25","Sin 117:1","Sin 65:10","Sin 33:8"]', NULL),
  (3476079, 'OT', 'Sinunö', 67, 3, 'Ena''ö aboto ba dödö niha ba guli danö lala andrö khöu, ba ena''ö aboto ba dödö niha baero wangorifi andrö khöu.', '["MozIV 6:24,25","Sin 117:1","Sin 65:10","Sin 33:8"]', NULL),
  (3476079, 'OT', 'Sinunö', 67, 4, 'Sanuno ya''ugö soi niha, ya''ugö Lowalangi, sanuno ya''ugö dozi soi.[2]', '["MozIV 6:24,25","Sin 117:1","Sin 65:10","Sin 33:8"]', NULL),
  (3476079, 'OT', 'Sinunö', 67, 5, 'Somuso tödö soi niha misa ba sowua-wua tödö, me ö''ohe ba wa''adölö wanguhuku soi, me öfatörö soi niha misa.', '["MozIV 6:24,25","Sin 117:1","Sin 65:10","Sin 33:8"]', NULL),
  (3476079, 'OT', 'Sinunö', 67, 6, 'Sanuno ya''ugö soi niha, ya''ugö Lowalangi, sanuno ya''ugö dozi soi.', '["MozIV 6:24,25","Sin 117:1","Sin 65:10","Sin 33:8"]', NULL),
  (3476079, 'OT', 'Sinunö', 67, 7, 'No ibe''e baero mbuania tanö; ifahowu''ö ita Lowalangi, Lowalangida andrö.[3]', '["MozIV 6:24,25","Sin 117:1","Sin 65:10","Sin 33:8"]', NULL),
  (3476079, 'OT', 'Sinunö', 67, 8, 'Ifahowu''ö ita Lowalangi ba la''ata''ufi ia balö danö fefu.[4]', '["MozIV 6:24,25","Sin 117:1","Sin 65:10","Sin 33:8"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 1, 'Khö duka wanunö andrö; khö Dawido; sinunö; umanö. [1]', '["Faigi göi SamII 12:26–31"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 2, 'Ya maoso Lowalangi, ya zumaewe zi fa''udu khönia, ya moloi zi fatiu tödö khönia.[2]', '["MozIV 10:35","Yes 57:14","Sin 10:14"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 3, 'Si mane simbo ba nangi, ya si manö wamoloimö ya''ira; si mane sigu-sigu, salau ba galitö, wa''adudu zebua horö, föna Lowalangi.', '["MozIV 10:35","Yes 57:14","Sin 10:14"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 4, 'Ba somuso tödö zatulö andrö, sowua-wua tödö tanö föna Lowalangi, ba sa''iki ba wa''omuso dödö andrö.', '["MozIV 10:35","Yes 57:14","Sin 10:14"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 5, 'Misuno Lowalangi, midunö-dunö döinia andrö; mifolala zanörö benua andrö; Yehowa döinia. Ba mi''owua-wua''ö dödömi tanö fönania![3]', '["MozIV 10:35","Yes 57:14","Sin 10:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476080, 'OT', 'Sinunö', 68, 6, 'Ama zi lö ama, si lö ina, ia, Lowalangi, ba nabiania ni''amoni''ö andrö.[4]', '["MozIV 10:35","Yes 57:14","Sin 10:14"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 7, 'Lowalangi, samaigi omo ba zi lö omo; sangefa''ö nikuru, solohe ba wa''ohahau dödö; ba si lö molo''ö li, ba ba danö si mate so nahiara.', '["MozIV 10:35","Yes 57:14","Sin 10:14"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 8, 'He Lowalangi, me mowaö-waö ndra''ugö no, föna mbanuau, me ötörö danö,[5]', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 9, 'ba humeu danö, ba mowöi göi mbanua si yaŵa, tanö föna Lowalangi; ba da''ö, ba hili Zina''i, föna Lowalangi, Lowalangi Ndraono Gizeraeli andrö.[6]', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 10, 'No ötefe teu sabönö dana khöu andrö, ya''ugö Lowalangi, hadia zi no ököli, ba ö''okafui.', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 11, 'No monahia ba khönia zato andrö khöu, no öhaogö nahia zi numana, ba wa''ebua dödöu andrö, ya''ugö Lowalangi.', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 12, 'Terongo li zi möna, ibe''e So''aya; ato sibai zangombakha turia si sökhi, ira alawe.[7]', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 13, 'Moloi razo zato, moloi, ba ifaosa nihalö khöra ira alawe yomo.', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 14, 'Na molombase ami ba gotalua kandra mbiri-biri, ba hulö gafi marafadi ami, sosönö wirö; sosönö gana''a sa''usö mbura.[8]', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 15, 'Me ifazawili ba da''ö Si lö ambö fa''abölö razo andrö, ba hulö nifazaewe bötua hili Zalomono.', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 16, 'Hili khö Lowalangi hili Mbazana andrö; hili soya zuzu hili Mbazana.', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 17, 'Hana wa afökhö dödömi, ya''ami hili soya zuzu, ba hili andrö somasi Lowalangi dadaomania? Ba lö mamalö-malö, wa nahia Lowalangi ia.[9]', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 18, 'Kureta Lowalangi andrö, ba no ba ngafulu ngahönö, mehönö wa hönö; no so ba khöra Zo''aya: — hili Zina''i, ni''amoni''ö.[10]', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 19, 'No möi miyaŵa ndra''ugö, no ö''ohe nikuru nikuru andrö; no ötema game''ela ba niha, he ba zi lö molo''ö li, ena''ö lö tebulö Yehowa, Lowalangi.[11]', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 20, 'Nisuno Zo''aya, ero ma''ökhö i''onoro noroda. Fangorifida Lowalangi.[12]', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 21, 'Lowalangi wangorifi khöda, Lowalangi andrö, ba Yehowa, So''aya andrö, ba i''ila lala wangefa ba wa''amate.', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 22, 'Si ndruhu, iboto högö zi fatiu tödö khönia Lowalangi, ba alizuzu zanörö lala horö.', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 23, 'No iŵa''ö So''aya: "U''ohe mangawuli ira, moroi ba Mbazana, moroi ba doyo nasi u''ohe ira miyaŵa.', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 24, 'Ena''ö öfemondri ba ndro gaheu, ba ena''ö mo''urakha dölö-tölö nasumö, ba zi fatiu tödö khöu."', '["MozII 13:21; Sanguhuk 5:4,5","MozII 19:16–18","Yes 52:7","Sanguhuk 5:16","Sin 132:13","RazII 6:17; Dan 7:10","Efes 4:8–10","RazI 10:13"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 25, 'No lö la''ila, me ötörö, ya''ugö Lowalangi, me itörö Lowalangigu andrö, razogu, we''amöi ba ni''amoni''ö andrö.[13]', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 26, 'Mowaö-waö, zanunö, ba itete, ba solau biola, ba hunö nono alawe, samözi faritia.', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 27, 'Misuno Lowalangi, So''aya, ba gowuloa andrö; ya''ami si oroi gumbu Ndraono Gizeraeli andrö![14]', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 28, 'So ba da''ö Mbeniyami, si akhi andrö, samatörö, ba salaŵa Ndraono Yuda, sato andrö khöra, ba salaŵa Ndraono Zebuloni ba salaŵa Ndraono Nafetali.', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 29, 'No i''oroi''ö Lowalangi wa''asalaŵau. He Lowalangi, a''aro''ö nifa''emau khöma!', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 30, 'Börö gosalimö andrö, ba Yeruzalema, wa la''ohe zumange khöu razo.[15]', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 31, 'Tenaŵa zaliŵa-liŵa andrö, barö zukhu, awö ngawawa zawi si mantua andrö, awö nono zawi niha baero, ena''ö mangalulu ira, wolohe boto wirö. Fazawili soi andrö, somasi manuwö.', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 32, 'So dania razo Miserayi; i''aliogö i''oro''ö dangania khö Lowalangi tanö Gaitiofia andrö.[16]', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 33, 'Ya''ami öri niha ba guli danö, misuno Lowalangi, misuno Zo''aya!', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 34, 'Misuno zanörö banua fondrege si yaŵa andrö, si no götö-götö fa''ara; hiza, ifarongogö linia andrö, li sabölö.', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 35, 'Mitehe khö Lowalangi wa''abölö; famatörö Iraono Gizeraeli wa''asalaŵania andrö ba famatörö banua si yaŵa wa''abölönia.[17]', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476080, 'OT', 'Sinunö', 68, 36, 'Sata''u ita nilau Lowalangi, moroi ba ni''amoni''ö andrö khönia; Lowalangi Ndraono Gizeraeli andrö zame''e fa''abölö ba fa''abe''e ba mbanuania. Nisuno Lowalangi![18]', '["SamII 6:13,14; Sin 24:7; MozII 15:20","Yes 48:1","Sin 72:10,15","Yes 19:21; Sin 87:4","Sin 29:1","Sin 29:11"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 1, 'Khö duka wanunö andrö, dali: "Ladari mböhö." Khö Dawido.', '[]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 2, 'Orifido Lowalangi, irugi sa''ae nosogu molö andrö!', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 3, 'No alömö ndra''o ba laza sabakha, si lö dane-dane gahegu; no urugi namö nidanö, ba itörö högögu molö andrö.', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 4, 'Erege dödögu we''aogu, no odufodufo dölö-tölögu, alö sa''ae hörögu wombalo-mbaloi Lowalangigu andrö.', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 5, 'Oya moroi ba rozi mbu ba högögu zi fatiu tödö khögu, lö börö; ato zamakiko ya''o, si fa''udu khögu ba waya; labe''e ni''aligu zi tenga nirabugu.[1]', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 6, 'He Lowalangi, ya''ugö zangila wa si no ambö tödö ndra''odo, ba tenga si tobini khöu lalögu andrö.', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 7, 'Böi be''e aila ba khögu andre zanötöna khöu, ya''ugö So''aya, Yehowa ngahönö andrö! Böi aila ba khögu andre zangalui ya''ugö, ya''ugö Lowalangi Ndraono Gizeraeli!', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 8, 'Börö ndra''ugö, wa utaha wango''aya, wa tobalu mbawagu fa''aila.[2]', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 9, 'No tobali niha bö''ö ndra''o ba dalifusögu, lö''ö sa''ae la''ilado ono ninagu andrö.[3]', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 10, 'Noa sa''ae i''ado fönu andrö, ba nomomö ba no gönado fango''aya zango''aya ya''ugö andrö.[4]', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 11, 'Me''e dödögu ba lö manga-mangado, ba tobali fango''aya ya''odo.', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 12, 'U''onukha gonigoni, ba tobali amaedola ndra''o khöra.', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 13, 'Lafatou ndra''o sidadao ba mbawa göli ba samadu-madu tuo, na manunö.[5]', '["Sin 35:19; Yoh 15:25","Sin 44:23","Sin 38:12; Yob 19:13","Yoh 2:17; Rom 15:3","Yob 30:9"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 14, 'Ba ya''odo, ba khöu utandrösaigö wangandrögu, ya''ugö Yehowa, na baŵa wa''ebua dödöu; he Lowalangi, ba wa''abölö wa''ebua dödöu andrö tema ligu fanolou andrö, si lö faröi![6]', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 15, 'Söbi yaŵa ndra''o moroi ba laza andre, fa böi alömö ndra''o; ena''ö aefa ndra''odo ba zi fatiu tödö khögu ba ba namö nidanö andre.', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 16, 'Böi be''e itörö högögu yaŵa molö ba böi be''e ahöndrö ndra''o ba namö, ba böi tehe iduhö mbawania yaŵagu kohokoho.', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 17, 'Fondrondrongo ligu, Yehowa, omasiö sa wa''ebua dödöu andrö, otahögö ndra''o, ba wa''ahakhö dödöu andrö, si no ebua.', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 18, 'Ba böi bini''ö mbawau khö genoniu andre; sata''u sa''ae ndra''odo; ta''i-ta''i fondrondrongo khögu!', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 19, 'Hatö''ögö ba dödögu, orifi; efa''ö ndra''odo, börö zi fatiu tödö andrö khögu.', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 20, 'Ya''ugö zangila fango''aya ya''o andrö ba fa''ailagu ba fahöwösa andrö, nilau khögu; no so ba gametahöu zamakao ya''o fefu.', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 21, 'Matedo ibe''e fango''aya andrö, u''ofökhöi; ubazebaze''ö wa''ahakhö dödö, ba lö''ö, ba sondrara tödö, ba lö falukha.[7]', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 22, 'Labe''e ögu gawökhu, ba me owökhi dödögu ba lafabadugö khögu niro aisö.[8]', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 23, 'Ya tobali fesu naha göra fönara, ya tobali tandraŵa ba zi lö fa''abu dödö![9]', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 24, 'Ya ndrundrumö höröra, fa böi la''ila niha, ya mangiwangiwa zolara, si lö mamalö-malö!', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 25, 'Hawui ira bakhu-bakhu dödöu andrö, yamukhamö ira hola-hola wönumö andrö!', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 26, 'Ya adudu nahiara, ya lö niha ba nosera andrö![10]', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 27, 'Me no solohi nibagou andrö ira, ba sanutunö fa''afökhö zesokho khöu.[11]', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 28, 'Nönö horö horöra andrö, ba böi be''e lakhamö wa''atulö andrö fönau,[12]', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 29, 'Nibunu döira ba zura wa''auri andrö, ba tebai tetanö ba zura döira, awö döi zatulö.[13]', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 30, 'Ba ya''odo, ba no si numana ba si no fahöna fa''afökhö, ba folohe yaŵa ya''o wangorifi andrö khöu, ya''ugö Lowalangi.', '["Yes 40:8","Ngenu 1:2,9","Mat 27:34,48","Rom 11:9,10","HalZin 1:20","Yes 53:4","Rom 1:24","Luk 10:20"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 31, 'Da''usuno döi Lowalangi ba wanunö, u''ebua''ö duriania fangandrö saoha gölö.', '["Sin 50:8–14","Sin 22:27"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 32, 'Da''ö zomasi Yehowa, moroi ba zawi si matua, moroi ba nono zawi si so tandru ba sa''a.[14]', '["Sin 50:8–14","Sin 22:27"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 33, 'La''ila si numana ba omuso dödö; ya''ami, sangalui Lowalangi, ya auri dödömi![15]', '["Sin 50:8–14","Sin 22:27"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 34, 'Ifondrondrongo sa Yehowa li zi numana, ba lö i''ositengagö nikuru andrö khönia.', '["Sin 50:8–14","Sin 22:27"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 35, 'Yamusuno ia banua si yaŵa ba tanö ba asi, awö zaliŵa-liŵa bakha, fefu!', '["Sin 50:8–14","Sin 22:27"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 36, 'Itolo sa Ziona Lowalangi ba ifuli itaru''ö mbanua Ndraono Yuda, ba monahia ira ba da''ö, ba khöra sa''ae.', '["Sin 50:8–14","Sin 22:27"]', NULL),
  (3476081, 'OT', 'Sinunö', 69, 37, 'Ba latema ondröita ma''uwu genoninia, ba somasi töinia zi soso ba da''ö dania.', '["Sin 50:8–14","Sin 22:27"]', NULL),
  (3476082, 'OT', 'Sinunö', 70, 1, 'Khö duka wanunö andrö; khö Dawido. Famasugi ba dödö.[1] [2]', '["Sin 33:1","Faigi göi Sin 40:14–18"]', NULL),
  (3476082, 'OT', 'Sinunö', 70, 2, 'He Lowalangi, ta''i-ta''i orifi ndra''odo; aliogö, Yehowa, tolodo!', '[]', NULL),
  (3476082, 'OT', 'Sinunö', 70, 3, 'Hana na aila zangalui famunu ya''o, hana na tehawu fa''aila; hana na lafuli ira furi ba na tobali fama''iki niha bö''ö zomasi fa''ate''alagu.', '[]', NULL),
  (3476082, 'OT', 'Sinunö', 70, 4, 'Ndra mangawuli furi ba wa''ailara andrö zanguma''ö: Ha! ha!', '[]', NULL),
  (3476082, 'OT', 'Sinunö', 70, 5, 'Ya sowua-wua tödö khöu ba ya somuso tödö dozi sangalui ya''ugö, ba dozi somasi fangorifi andrö khöu, ba ena''ö na lö mamalö-malö we''aora: "Ebua Lowalangi!"', '[]', NULL),
  (3476082, 'OT', 'Sinunö', 70, 6, 'Ba ya''odo, ba no sebua akaola ba si numana; ta''i-ta''i, ae khögu, ya''ugö Lowalangi! Sanolo ya''o ndra''ugö ba sangorifi ya''o; he Yehowa, böi aragö''ö!', '[]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 1, 'Khöu Yehowa, manötona ndra''o; böi manö be''e aila ndra''odo!', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 2, 'Orifi ndra''o, dali wa''atulö dödöu andrö, ba efa''ö ndra''o; be''e mbörö dalingau khögu ba tolodo!', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 3, 'Ena''ö na naha saro ndra''ugö khögu, nahiagu, saŵatögu, si lö mamalö-malö; tete gara as ndra''ugö khögu ba hatigu![1]', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 4, 'He Lowalangigu, efa''ö ndra''o ba danga zebua horö andrö, ba gokhö zanao horö ba ba gokhö zi höndrögö ya''odo!', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 5, 'Tötönafögu sa ndra''ugö, ya''ugö So''aya, Yehowa, we''e-we''e dödögu, i''otarai iraono ndra''odo.', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 6, 'Khöu utendrotendro''ö ndra''o, i''otarai dalu ninagu; no ya''ugö zondröni ya''o moroi ba dalu ninagu; ya''ugö nisunogu, si lö mamalö-malö.[2]', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 7, 'Ato zahöli-höli tödö khögu, ba ya''ugö zaŵatögu, si lö mangiwa.[3]', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 8, 'No fahöna ba mbewegu wanuno ya''ugö ba famolakhömi ya''ugö, ma''öma''ökhö.', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 9, 'Böi tibo''ö ndra''odo, na itugu atua ndra''o; na alö dölagu, ba böi faröi ndra''ugö khögu![4]', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 10, 'Lafatou sa ndra''o si fatiu tödö khögu, ba sanarogö nosogu, ba mamagölö;', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 11, 'Ba lamane: "No i''erogö ia Lowalangi; migohi ia, mira''u, lö''ö sa sangorifi!"', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 12, 'He Lowalangi! böi aröu''ögö khögu; ta''i-ta''i tolodo, ya''ugö, Lowalangigu!', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 13, 'Ena''ö na aila zangalui famunugu, ba ena''ö na tekiko; ya tebawu wa fama''iki niha ira ba fa''aila zomasi fa''ate''alagu!', '["Sin 18:3; 31:3,4","Sin 22:10","Sin 4:4","Ayati 18"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 14, 'Ba ya''o, ba lö uböhöli wanötöna ba udou''ö duriamö fefu.', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 15, 'Yamudunö-dunö wa''atulömö andrö bewegu, ba fangorifi andrö khöu, ero ma''ökhö, me tebai u''erai.[5]', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 16, 'U''ohe nilau Zo''aya, Yehowa, sebua andrö, sambalö fa''atulömö andrö usuno.', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 17, 'He Lowalangi, no öfahaö ndra''o, i''otarai iraono ndra''o; ba irugi ma''ökhö udunö-dunö zahöli-höli dödö andrö khöu.[6]', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 18, 'Ba irege atuado göi, irege mohuwa ndra''o, ba böi röido, ya''ugö Lowalangi, ena''ö u''ombakha''ö dangamö ba zi sagötö niha dania ba fa''abölömö andrö ba zi so dania, fefu.[7]', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 19, 'Fa''atulömö andrö sa, ya''ugö Lowalangi, ba irugi mbanua si yaŵa, ya''ugö, si no molau sebua andrö, ya''ugö Lowalangi; ha niha zi fagölö-gölö khöu![8]', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 20, 'Ya''ugö, si no mamatörö khöma fa''afökhö ba fa''abu dödö, soya ngawalö, ba öfuli ö''orifi ndra''aga, öfuli ö''ohe yaŵa ndra''aga, moroi ba gohokoho danö andrö.[9]', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 21, 'Ödou''ö dania wa''asalaŵagu ba öfuli örara dödögu.', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 22, 'Ba ya''odo göi, usuno ndra''ugö wolau biola, usuno wa lö; faröi ndra''ugö, ya''ugö Lowalangigu, ulau khöu mbiola nitika, side-ide, wanunö ya''ugö, ya''ugö ni''amoni''ö ba Ndraono Gizeraeli!', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 23, 'Sanunö dania mbewegu, na usuno ndra''ugö, ba sanunö dödögu, ni''orifimö andrö.', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476083, 'OT', 'Sinunö', 71, 24, 'Ba ifatunö wa''atulömö andrö lelagu, ero maokhö; me no aila zomasi fa''ate''alagu, me no tobali fama''iki niha.', '["Ayati 8; Sin 40:6","SamI 7:12","Ayati 9; Yes 46:4","MozII 15:11","SamI 2:6"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 1, 'He Lowalangi, be''e khö razo wanguhuku andrö khömö; ba khö nono razo andrö be''e wa''atulömö.', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 2, 'Ena''ö i''atulö''ö wanguhuku banuamö andrö, ba ena''ö i''ohe ba wa''adölö wanguhuku si numana.', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476084, 'OT', 'Sinunö', 72, 3, 'Ena''ö mowua fa''ohahau dödö hili ba mbanuamö andrö, awö hili-hili andrö, ba wa''atulö.[1]', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 4, 'Yamu''ohe ba wa''atulö huhuo zabu tödö ba mbanua, yamutolo nono zi numana, ba yamufufu zamalangögö awöra.[2]', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 5, 'Ndramu''ata''ufi ndra''ugö götö wa''ara luo, ba götö wa''ara mbaŵa, götö-götö wa''ara.', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 6, 'Ya numalö mitou, si mane teu, ba mbenua, si bohou lasabi du''u, si mane teu sabölö-bölö andrö, fombasöi danö.', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 7, 'Ya mobowo zatulö tödö andrö ba götönia, ya fahöna wa''atulö, irugi lö baŵa sa''ae.', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 8, 'Ya salaŵa ia, i''otarai nasi, numalö ba nasi ba zi tambai, ba i''otarai mboto nidanö, numalö ba wondrege danö.[3]', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 9, 'Ya mangalulu khönia zowanua ba danö si mate, ya lafelai gawu-gawu si fatiu tödö khönia.[4]', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 10, 'Ndramufosumange ia razo Darisi andrö, awö razo ba hulö, ndramu''ohe game''ela razo Zaba ba razo Zeba andrö.[5]', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 11, 'Ba latuhi danö fönania razo fefu, möi enoninia dozi niha baero.[6]', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 12, 'I''orifi zi numana, na i''angaröfi li ia, ba sabu tödö, si lö sanolo.[7]', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 13, 'Ihakhösi tödö zi lö töi ba si numana ba idou''ö noso zi numana.', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 14, 'I''efa''ö nosora ba wamakao ba ba wamalangögö; ebua mböli ndrora wamaiginia.[8]', '["Sin 85:9–14","Ayati 12","Sakh 9:10","Yes 49:23","Sin 68:30; Yes 60:9","Sin 2:8,10–12","Yob 36:15; Sin 35:10","Sin 9:13"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 15, 'Ba sauri ia: ba labe''e sumangenia gana''a Zaba andrö ösa, ba lö mamalö-malö wangandrö, salahinia, ero ma''ökhö lasuno ia.[9]', '["Ayati 10; Sin 84:10","MozI 12:3; 22:18","Sin 41:14; Yes 6:3"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 16, 'Fahöna mbua nowi ba danö, ba hili yaŵa; mururu mbuania, si mane ba hili Libano; mobowo ira, i''oroi mbanua, si mane sinanö ba danö.', '["Ayati 10; Sin 84:10","MozI 12:3; 22:18","Sin 41:14; Yes 6:3"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 17, 'Si lö tebulö döinia; götö wa''ara luo yaŵa mamadomadohu döinia, ba ba khönia lafahowu''ö ira niha, lasuno dania ia dozi, niha baero, wa no sohahau tödö ia.[10]', '["Ayati 10; Sin 84:10","MozI 12:3; 22:18","Sin 41:14; Yes 6:3"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 18, 'Nisuno Yehowa, Lowalangi andrö, Lowalangi Ndraono Gizeraeli; ha ya''ia zolau sahöli-höli dödö.', '["Ayati 10; Sin 84:10","MozI 12:3; 22:18","Sin 41:14; Yes 6:3"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 19, 'Ba nisuno döinia soadu andrö, irugi zi lö aetu. Ya anönö danö ma''asagörö lakhöminia andrö! Ya duhu, Ya duhu![11]', '["Ayati 10; Sin 84:10","MozI 12:3; 22:18","Sin 41:14; Yes 6:3"]', NULL),
  (3476084, 'OT', 'Sinunö', 72, 20, 'Awai wangandrö Dawido andrö, ono Giza''i.', '["Ayati 10; Sin 84:10","MozI 12:3; 22:18","Sin 41:14; Yes 6:3"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 1, 'Si ndruhu, ebua dödö Lowalangi ba Ndraono Gizeraeli, ba zohau-hau tödö andrö.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 2, 'Ha ma''ifu tö, ba mangiwa mena''ö gahegu; ezai mutö tö, ba ahele ndra''o.[2]', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 3, 'Afökhö sa''ae dödögu ba zi fayaŵa andrö, me u''ila wa''ohahau dödö zebua horö andrö.[3]', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 4, 'Lö''ö sa fa''afökhö khöra, irugi mate ira, ba so''ösi mbotora.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 5, 'Lö sabu dödöra, si mane ba niha bö''ö; ba lö tefakao ira, si mane awöra.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 6, 'Ba da''ö moroi, wa no hulö naya ba mbagi khöra hokha andrö, awö wa no hulö mbarura wamakao awöra.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 7, 'No ahöndrö höröra, ba wa''esolo mbawara; falawu nifakhai dödöra andrö.[4]', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 8, 'Mango''aya ira ba itörö lira wamalangögö awöra, ba walösökhira andrö; fayaŵasa wehedera andrö.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 9, 'Lafayaŵa mbawara, irugi mbanua si yaŵa ba itöröi guli danö lelara.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 10, 'Andrö göi la''o''ö khöra banua, ba lö ambö öra idanö.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 11, 'Ba lamane: "Hana wa i''ila Lowalangi? Hadia, so wangila khö Wondrege zalaŵa andrö?"[5]', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 12, 'Hiza, da''ö zebua horö andrö; lahöna gana''a, ba wa lö mamalö-malö wa''ohahau dödö.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 13, 'Ba he wisa, zaya-zaya gölö, wa no u''ohau-hau''ö dödögu, wa usasai dangagu ba wa lö sala?', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 14, 'Ba hadia, nifakao ndra''o, ero ma''ökhö, ba ero mahemolu so wotugu?', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 15, 'Na uŵa''ö mena''ö tödögu: "Umanö göi wehede," ba hiza, ba no faröi ndra''o ba nga''ötö nonou andrö.', '["Sin 94:18","Yob 21:7","Yob 15:27","Sin 10:11"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 16, 'Ba no mangera-ngera ndra''o, ena''ö aboto ba dödögu, ba abu dödögu, wamaigigu ya''ia.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 17, 'Irege möido ba ni''amoni''ö andrö khö Lowalangi, wanöngöni amozuara.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 18, 'Si ndruhu, no öfataro ira ba zaelo tanö, alau ira obe''e, ena''ö afufu.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 19, 'Ha lö alio adudu ira, si lö mudöna-döna, no tekiko ira, no aetu, ba gameta''uö.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 20, 'Ötayaigö ba dödöu khala-khalara, ya''ugö So''aya, na tokea''ö; hulö wangifi, na aefa wemörö.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 21, 'Me abao dödögu ba me manögi ba mbuagu,', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 22, 'ba sambö tödö ndra''o ba lö saboto ba dödögu; hulö zaliŵa-liŵa ba danö ndra''o fönau.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 23, 'Ba lö''ö zui uröi ndra''ugö; ya''ugö zolohe tangagu kambölö.[6]', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 24, 'Öfasao ndra''o, balazi dödöu, ba ötema ndra''o dania, fao zumange. Ha niha khögu ba zorugo?', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 25, 'Ba na khögu ndra''ugö, ba lö hadia ia zomasido ba guli danö.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 26, 'Alakha alö nösigu ba alakha ariri dödögu; we''e-we''e dödögu Lowalangi ba urakhagu, irugi zi lö aetu.[7]', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 27, 'Hiza sa, tekiko zangerogö ya''ugö; öhori fefu zi faröi khöu.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476085, 'OT', 'Sinunö', 73, 28, 'Ba khögu, ba fa''ohahau dödö, na faböbö ndra''o khö Lowalangi, khö Zo''aya, Yehowa manötöna ndra''o, ba wanutunö folaunia andrö, fefu.', '["Rom 8:35–39","Sin 16:5"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 1, 'He Lowalangi, hana wa no ötibo''ö ndra''aga, si lö fulitö? hana wa no abölö sibai wönumö ba mbiri-biri andrö, rorogöföu?', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 2, 'Törö tödöu mbanuau andrö, nihöliu ba götö föna sa''ae, nitabamö höli, ena''ö soi tana khöu; törö tödöu hili Ziona andrö, nahiau.[1]', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 3, 'Fazaŵa''ö, ae ba gadudula andrö, si lö mamalö-malö andrö; fefu hadia ia ba ni''amoni''ö andrö, ba no lafufu emali.', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 4, 'Mundröndröndröndö zi fa''udu khöu, barö gosali khöu; tandra khöra andrö no labe''e tandra.', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 5, 'Hulö zamazaŵa fato ba zatua eu, wamaigida.', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 6, 'Ba larasa sa''ae gamoelania fefu, lalau wato ba farökha.', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 7, 'No latunu ni''amoni''ö andrö khöu, ba no ladudugö nahia döimö andrö, na lata''unöi.[2]', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 8, 'No lamane dödöra: "Tafakiko ira fefu!" Fefu gosali Lowalangi ba danö, ba no latunu.[3]', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 9, 'Tandra andrö khöda, ba lö ta''ila; lö sama''ele''ö sa''ae, ba lö khöma sangila ha wa''ara.', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 10, 'He Lowalangi, heza irugi manandraŵa manö zi fa''udu andrö, heza irugi wa lö mamalö-malö i''o''aya döimö andrö si fatiu tödö?', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 11, 'Hana wa öböda dangau, kambölömö andrö? Söbi ia barö mbarumö ba dotou ba fakiko ira!', '["Sin 132:13","RazII 25:9","Sin 83:13"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 12, 'Razogu sa atö Lowalangi, i''otarai götö föna sa''ae, sangasogö fangorifi ba guli danö.', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 13, 'Ya''ugö zamabali asi no, ba wa''abölömö andrö, no öboto högö zaliwaliŵa andrö, sata''u ita, ba nasi bakha.[4]', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 14, 'No örasa högö mbuaya, no öbe''e ö zi so ba danö si mate.', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 15, 'Ya''ugö zamangumbu idanö, elea andrö; ya''ugö zangetu''ö idanö si lö irai aetu.[5]', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 16, 'Khöu zi ma''ökhö ba khöu zi bongi; ya''ugö zamazökhi baŵa, fabaya luo.[6]', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 17, 'Ya''ugö zi honogöi ola danö fefu; baŵa lökhö ba baŵa deu, ba ya''ugö zomböi.', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 18, 'Törö tödöu: no i''o''aya Yehowa si fatiu tödö andrö, no itandraŵaisi döimö soi sowöhö mowa.', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 19, 'Böi lulu ba gutu ndru''u noso wune andrö khöu; böi olifugö''ö noso zi numana andrö khöu, si lö mamalö-malö!', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 20, 'Nehegö wawu''usa li andrö; no fahöna nahia wamalangögö ba mbini-mbini andrö ba danö.', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 21, 'Böi ya mangawuli aila nifakao andrö; ena''ö lasuno döimö sabu tödö andrö ba si numana!', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 22, 'Fazaŵa''ö, Lowalangi, fatunö huhuo andrö khöu! Törö tödöu wango''aya andrö, nilau zowöhö mowa andrö khöu, si lö mamalö-malö.', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476086, 'OT', 'Sinunö', 74, 23, 'Böi olifugö''ö we''ao-ao zi fatiu tödö andrö, awö wagua-guasa zi fa''udu, silalö miyaŵa, si lö aetu.', '["MozII 14:21; 15:8–10","Sin 104:10","Sin 104:19"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 1, 'Khö duka wanunö andrö, dali: "Böi fakiko!" Sinunö; khö Gasafo; umanö. [1]', '["Faigi göi RazII 19; Sin 46"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 2, 'Ma''andrö saoha gölöu, ya''ugö Lowalangi, ma''andrö saoha gölöu, ba tenga saröu, döimö andrö; ladunö-dunö zahöli-höli dödöma andrö khöu![2]', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 3, '"Ufaigi sa''ae ginötö, u''ohe ba wa''adölö huhuo.', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 4, 'Na mangulu danö, awö zowanua ba gulinia, fefu, ba ya''odo zangaro''ö ehomonia."', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 5, 'Umane ba zi fayaŵa: "Böi misuno ami!" ba ba zebua horö: "Böi mi''alaŵa''ö dandrumi!"', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 6, 'Böi mi''alaŵa''ö yaŵa dandrumi; böi milau hokha, wamazaŵa bagimi.', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 7, 'Tenga sa moroi ba gatumbukha ba tenga moroi ba gaekhula ba tenga moroi ba danö si mate i''otarai fa''ebua.', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 8, 'Lowalangi sa''ae zanguhuku; ihöndrögö zi samösa ba i''alaŵa''ö yaŵa zi samösa.[3]', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 9, 'So sa''ae ba danga Yehowa mako so''ösi agu so''otu, no afönu nifaruka andrö, ba ifabadugö ba niha, ba irege wöröwörönia, ba lö tola lö lasowo dozi sebua horö andrö ba guli danö, ba lö tola lö labadu.[4]', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 10, 'Ba ya''odo, ba udunö-dunö, irugi zi lö aetu; usuno Lowalangi Yakobo andrö.', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476087, 'OT', 'Sinunö', 75, 11, 'Ba u''eŵa fefu dandru zebua horö andrö; ba ya alaŵa yaŵa dandru zatulö tödö!', '["Yes 46:13","SamI 2:7","Sin 60:5"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 1, 'Khö duka wanunö andrö; nilau biola; sinunö; khö Gasafo; umanö.', '[]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 2, 'No te''ila Lowalangi ba Ndraono Yuda; no ebua döinia ba Ndraono Gizeraeli.', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 3, 'Ba Zalema so nosenia ba ba Ziona nahiania.[1]', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 4, 'Ba da''ö ifatö no gari wana andrö ba baluse ba föda, ba no i''etu''ö wanuwö.[2]', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 5, 'Si takile ndra''ugö, si so lakhömi, moroi ba hili worabu andrö.', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 6, 'No te''osindra''ui gama-gama zabölö andrö; no alau höröra, mörö, ba no adada danga zabe''e fanuwö, fefu.', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 7, 'Ba wanegumö andrö, ya''ugö Lowalangi Yakobo, tehawu femörö gureta, awö kudo.', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 8, 'Sata''u ita ndra''ugö, ya''ugö andrö; ha niha zanaha khöu, na tesao wönumö.', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 9, 'No öfarongogö wanguhuku moroi ba zorugo, ba tokea guli danö ba lö hede-hede,[3]', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 10, 'me maoso Lowalangi, ba wangorifi si numana ba guli danö, fefu.', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 11, 'Isuno sa ndra''ugö fönu niha andrö, ba öhalö böbö talumö zi tosai fönu andrö.', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 12, 'Mifabu''u zumange khö Lowalangimi Yehowa, ba mibu''a göi; dozi si tefasui ya''ia, ba ndramu''ohe game''ela khö zata''u ita andrö![4]', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476088, 'OT', 'Sinunö', 76, 13, 'Sangohori fa''abe''e dödö ba zebua, ba sata''u zalaŵa ba guli danö.', '["Sin 132:13","Sin 46:10","Sin 46:11; Hab 2:20","MozII 15:11; MozV 7:21"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 1, 'Khö duka wanunö andrö, khö Yedutuno andrö; khö Gasafo; sinunö. [1]', '["Faigi göi Nga''ötI 16:41"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 2, 'Yamurongo ligu Lowalangi, da''mu''aodo, ufarongogö ligu khö Lowalangi, ena''ö ifondrondrongo khögu.', '["Sin 143:5","Sin 85:6"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 3, 'U''alui Zo''aya, na baŵa wa''abu dödögu; ba zi bongi u''oro''ö dangagu, lö atage; lö edöna terara dödögu.', '["Sin 143:5","Sin 85:6"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 4, 'Itörö tödögu Lowalangi, ba mangarö-ngarödo; mangera-ngera ndra''odo, ba alangu dödögu.', '["Sin 143:5","Sin 85:6"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 5, 'Lö alau hörögu öbe''e; si lö ahono-hono ndra''o, ba tebai muhededo.', '["Sin 143:5","Sin 85:6"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 6, 'Itörö tödögu götö föna andrö, döfi si no numalö, föna sa''ae.[2]', '["Sin 143:5","Sin 85:6"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 7, 'Ba zi bongi u''angeragö wolaugu biola andrö; ufatou-tou tödögu ba i''alu-alui tödögu.', '["Sin 143:5","Sin 85:6"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476089, 'OT', 'Sinunö', 77, 8, 'Hadia, irugi zi lö aetu itibo''ö ita So''aya? hadia, lö''ö sa''ae i''ebua''ö dödönia khöda?[3]', '["Sin 143:5","Sin 85:6"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 9, 'Hadia, no alua aetu wa''ebua dödönia? lö si tosai wa lö faröi ia, götö-götö wa''ara?', '["Sin 143:5","Sin 85:6"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 10, 'Hadia, no olifu Lowalangi wangebua tödönia? Hadia, no iduhö wa''ahakhö dödönia, ba wönu andrö?', '["Sin 143:5","Sin 85:6"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 11, 'Ba umane: "Famakaogu da''ö, götö danga kambölö khö Wondrege zalaŵa andrö."', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 12, 'Itörö tödögu wolau Yehowa, usuno: ufatou-tou sa''ae wolaumö andrö ba götö föna, sahöli-höli dödö.', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 13, 'U''era-era tödögu halöŵöu andrö fefu, u''alu-alui tödögu zebua andrö, nilaumö.', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 14, 'He Lowalangi, ni''amoni''ö iala andrö khöu! Ha niha Lowalangi sebua, si mane Lowalangi?[4]', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 15, 'Ha ya''ugö Lowalangi, solau sahöli-höli dödö; no öfa''ele''ö wa''abölöu, ba niha baero andrö.', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 16, 'No ö''efa''ö mbanuau, tangau andrö, ma''uwu ndra Yakobo Yosefo.', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 17, 'I''ila ndra''ugö asi, ya''ugö Lowalangi, i''ila ndra''ugö asi, ba humisi, ba manizi-nizi namö.', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 18, 'Aekhu ba danö deu andrö ba lawuo, mu''ugu mbanua si yaŵa, ba itörö mbanua garinia andrö khöu.', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 19, 'Terongo mbanua andrö ba dawuyu nangi, ihagaini guli danö gari mbanua andrö, moduru danö, humisi.', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 20, 'Ba nasi lalamö ba ba nidanö sebua döröŵau, ba lö oroma laheu.', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476089, 'OT', 'Sinunö', 77, 21, 'No öfasao mbanuau andrö, hulö mbiri-biri; ira Moze A''aroni zolohe.[5]', '["MozII 15:11","MozII 12:37; 14:22"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 1, 'Mifondrondrongo, ya''ami banuada, wamahaögu andre, mibe''e mbörö dalingami ba daroma ligu andre.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 2, 'Da''ubokai mbawagu, ba wolau amaedola, da''utunö dahö-dahö, si oroi götö föna sa''ae.[2]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 3, 'Si no tarongo, si no itörö, nidunö-dunö ndra amada khöda.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 4, 'Ba lö tabini''ö ba ma''uwura wanutunö ba götö dania turia Yehowa andrö ba fa''abölönia ba sahöli-höli dödöda khönia, nilaunia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 5, 'Noa sa i''asogö wamaduhu''ö ba Ndraono Yakobo, ba no ibe''e goroisa ba Ndraono Gizeraeli, ni''oroi''önia khö ndra tuada, ena''ö la''ombakha''ö ba ndraonora.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 6, 'Ena''ö la''ila ba götö dania, iraono andrö, si tumbu dania, ba ena''ö maoso da''ö, ba wanutunö mitou, ba ndraonora.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 7, 'Ena''ö tötönaföra Lowalangi, ba böi olifu ira zebua andrö, nilau Lowalangi, ba ena''ö la''o''ö goroisania.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 8, 'Ba böi si mane ira tuara ira, niha si faröi ba samadaö li; niha si lö aro tödö, saefa-aefa era-era khö Lowalangi.[3]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 9, 'Iraono Geferayi andrö, solohe fana, ba wafanata, ba no moloi, me luo wanuwö.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 10, 'Laböhöi wawu''usa li andrö khö Lowalangi ba lö edöna latörö lala andrö khönia, ba goroisa.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 11, 'Olifu ira nilaunia andrö ba sahöli-höli dödö andrö, nifa''ele''önia khöra.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 12, 'No ilau zahöli-höli dödö ba zi so ira tuara, ba danö Miserayi, ba zalo''o ba Zoana.[4]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 13, 'No ifabali nasi, ifatörö ira; i''abe''e''ö nasi, hulö mba''a-ba''a [fatambai].[5]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 14, 'Ba ifasao ira, lawuo, na ma''ökhö, ba sara wongi dania, ba haga galitö.[6]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 15, 'Isila gara ba danö si mate andrö, ifabadugö khöra zi hulö nidanö sebua.[7]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 16, 'Ifangumbu mbombo moroi ba gara, ifangele nidanö, si hulö nidanö sebua.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 17, 'Ba latohugö zui wamazökhi horö khönia ba fangandrö fönu Wondrege zalaŵa, ba danö si mate.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 18, 'Latandraigö Lowalangi tödöra, wangandrö gö somasi ira.[8]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 19, 'Lafatou Lowalangi, lamane: Hadia, i''ila Lowalangi ifa''oli göda, ba danö si mate?', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 20, 'Hiza, no ibözi gara, ba mangumbu nidanö khönia, ahele, mo''ungo; hadia, i''ila göi ibe''e göda? Hadia i''ila i''asogö ndriwo mbanuania?"', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 21, 'Andrö mofönu Yehowa, me irongo da''ö, ba humola galitö ba Ndraono Yakobo, tesao wönu ba Ndraono Gizeraeli.[9]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 22, 'Me lö mamati ira ba li Lowalangi andrö, ba me lö latötöna wangorifi andrö khönia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 23, 'Ba i''oroi''ö ba lawuo si yaŵa, ibokai mbawandruhö mbanua si yaŵa.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 24, 'Moteu "mana" ba khöra ibe''e, ena''ö la''a, ibe''e khöra mböra mbanua si yaŵa.[10]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 25, 'Ö mala''ika göra, dozi ira; no ifa''ohe''ö khöra mbalazo, fahöna.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 26, 'Ifasugi nangi moroi ba gatumbukha ba mbanua, ba ifatörö nangi moroi raya, ba wa''abölönia andrö.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 27, 'Moteu diwo ba khöra, ibe''e, hulö gawu-gawu, ba fofo so''afi, hulö nene ba mbewe nasi.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 28, 'Ba dalu golombaseŵara i''ekhugö, tefasui nahiara.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 29, 'Ba la''a, ba maulu wa''abusora; ibe''e khöra zomasi ira.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 30, 'Ba lö si döhö na wangisöra andrö, so na ba mbawara göra andrö,', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 31, 'ba tesao wönu Lowalangi khöra, ba ibunu zesolo andrö khöra ösa ba ibözi tou nono matua Ndraono Gizeraeli.[11]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 32, 'Ba latohugö wanao horö, lö lai da''ö, lö mamati ira ba zahöli-höli dödö andrö khönia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 33, 'Ba ibe''e taya-taya mbaŵara, tobali angi, ba döfira, ba sata''u ita wa''alio.[12]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 34, 'Na ibubunu ira, ba lazofu-zofu ia; lafuli ira, ba laforege wangalui Lowalangi.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 35, 'Ba itörö tödöra, wa no we''e-we''e dödöra Lowalangi, wa sangorifi ya''ira Lowalangi Fondrege zalaŵa andrö.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 36, 'Ba lahaogö-haogö mbewera khönia, ba lelara, ba solau faya khönia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 37, 'Ba lö aro dödöra khönia, si faröi ira, ba wawu''usa li andrö khönia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 38, 'Ba ya''ia, ba sahakhö tödö, i''efa''ö lalöra andrö ba lö ifakiko ira; asese i''alösi wönunia, ba lö iforege wamaosi tödönia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 39, 'Itörö sa tödönia, wa no ösi niha ira, wa angi, silalö misa ba si lö mangawuli.[13]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 40, 'Ha me uga molaŵa ira khönia, ba danö si mate andrö, ha me uga labusi dödönia ba danö si lö niha-niha![14]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 41, 'Lö döhö latandraigö Lowalangi, afökhö bakha dödö ni''amoni''ö ba Ndraono Gizeraeli, labe''e.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 42, 'Lö itörö tödöra wa''abölö dangania, ba he baŵa andrö, me i''efa''ö ira ba danga nemalira.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 43, 'Me ilau dandra andrö khönia, ba danö Miserayi ba sahöli-höli dödö andrö, ba ndraso Zoana.[15]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 44, 'No ibali''ö do nidanö sebua khöra, awö mbombo, fa tebai labadu.[16]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 45, 'Ifa''amöi khöra ndri manu, si manga ya''ira; ba talaho, famakikora.[17]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 46, 'Ibe''e ö lamanua mbua danö khöra, ba ö damo gölöra.[18]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 47, 'Ifabözi''ö nagu khöra teu kara, ba bua ara khöra teu sabe''e.[19]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 48, 'Göna teu kara georiföra ibe''e, ba göna zaerezaere mbiri-birira ba saŵira.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 49, 'Ifatörö khöra hola-hola wönunia andrö ba fa''abao dödö ba bakhu-bakhu dödö ba famakao, awö ngawawa mala''ika samakiko.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 50, 'Ifolala wönunia andrö, lö itimba wa''aetu nosora, ilulu ba wökhö waba.[20]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 51, 'Ibözi fefu nono si a''a ba danö Miserayi, si a''a zabölö andrö ba nose ma''uwu Khamo.[21]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 52, 'Ba awu''a mbanuania andrö, hulö mbiri-biri, ibe''e, ba ifasao ira, hulö nikubaloi, ba danö si mate andrö.[22]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 53, 'Ihaogö wolohe ya''ira, fa böi ata''u ira; ba emalira andrö, ba no ibalugö asi.[23]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 54, 'Ba i''ohe ira ba danö ni''amoni''ö andrö khönia; ba hili andre, ni''okhögö gambölönia.[24]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 55, 'Ba itimba fönara niha baero andrö; ifaosa tana khöra ba dahö-dahö, ifatewu ba nosera mado Ndraono Gizeraeli andrö.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 56, 'Ba latandraigö Lowalangi Fondrege zalaŵa, la''andrö wönunia, ba lö la''o''ö wamaduhu''ö andrö khönia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 57, 'La''erogö Lowalangi, fabali, si mane ira tuara; labali''ö ira furi, hulö wana si falimo.[25]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 58, 'Ba labaosi dödönia, ba hili-hili andrö khöra, afökhö bakha dödönia, labe''e ba nadura andrö.[26]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 59, 'Ba irongo Lowalangi, ba mofönu ia, ba ifaulugö i''erogö Ndraono Gizeraeli.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 60, 'Ba iböhöli nahiania andrö ba Zilo, ose andrö, si soso ia ba niha.[27]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 61, 'Ba ibe''e nirabu wa''abölönia andrö; lakhöminia andrö tawöla gamabu''ula li, ba ilulu ba danga nemali.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 62, 'Ba itou''ö ba mbawa zi''öli mbanuania andrö, mofönu ia ba dana khönia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 63, 'Ono matua andrö khönia, ba i''a alitö, ba lö falukha wanunö ba walöŵa nono alawe khönia.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 64, 'Mate ni''ö''ötö gere andrö khönia, ba lö mange''esi lakha mbanua.[28]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 65, 'Ba tokea Zo''aya, hulö zi no mörö, hulö zabölö, si karaini wa''iki, wamadu agu.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 66, 'Ba itimba nemalinia andrö; aila ira, si lö aetu, ibe''e.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 67, 'Ba i''erogö nose Ndraono Yesefo andrö, tenga mado Geferayi nituyu.[29]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 68, 'Mado Yuda sa''ae ituyu, hili Ziona andrö, somasi ia.[30]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 69, 'Ba ilau ni''amoni''ö andrö khönia, timba wa''alaŵa mbanua si yaŵa wa''alaŵa, si mane tanö andrö, nilatania, si lö tebulö.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 70, 'Ba ituyu genoninia andrö, Dawido andrö, ba zinga kandra mbiri-biri ihalö.[31]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 71, 'Ba nikubaloinia biri-biri si bohou mo''ono ihalö, ena''ö ikubaloi mbanuania, ma''uwu Yakobo, tana khönia andrö, Iraono Gizeraeli.[32]', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476090, 'OT', 'Sinunö', 78, 72, 'Ba ikubaloi ira, dali wa''adölö dödönia andrö; ba enahöi dangania, wolohe ya''ira.', '["Sin 49:4,5; Mat 13:35","MozV 32:5,6","Yes 19:11","MozII 14:21,22","MozII 13:21","MozII 17:6; MozIV 20:7–11","MozII 16:3; MozIV 11:4","MozIV 11:1","MozII 16:4,14,15","MozIV 11:33","MozIV 14:23","Sin 103:14–16","MozIV 14:22","Ayati 12","MozII 7:19,20","MozII 8:2,20","MozII 10:13","MozII 9:25","MozII 9:15","MozII 12:29","Sin 77:21","MozII 14:19,22,27","MozII 15:17","Hos 7:16","MozI 32:21","SamI 1:3; 4:11","SamI 4:17,20","Ayati 9","Nga''ötII 6:6","SamI 16:11,12","SamII 7:8"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 1, 'He Lowalangi! No larugi dana khöu niha baero; no lata''unöi gosali andrö khöu, ni''amoni''ö; no labali''ö adudula Yeruzalema andrö.[2]', '["Yer 9:11","Sin 44:14","Sin 80:5","Yer 10:25"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 2, 'No labe''e ö wofo ba dalu mbanua mboto genoniu andrö, si mate, ba ö gutu ndru''u, nösi zatulö tödö andrö khöu.', '["Yer 9:11","Sin 44:14","Sin 80:5","Yer 10:25"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 3, 'No aduwa ndrora, hulö nidanö, labe''e si tefasui Yeruzalema, ba lö sogo''o.', '["Yer 9:11","Sin 44:14","Sin 80:5","Yer 10:25"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 4, 'Fango''aya zahatö banua ndra''aga, famahera ba fama''iki zi so ba ngaima.[3]', '["Yer 9:11","Sin 44:14","Sin 80:5","Yer 10:25"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 5, 'He So''aya, heza irugi, wa lö mamalö-malö wönumö andrö? Hadia, muhola wa''afökhö ba dödöu andrö, si mane alitö?[4]', '["Yer 9:11","Sin 44:14","Sin 80:5","Yer 10:25"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 6, 'Ba niha baero, si lö mangila ya''ugö, tandrösaigö wa''abao dödöu andrö, ba ba nöri si lö mangaröfi li töimö andrö.[5]', '["Yer 9:11","Sin 44:14","Sin 80:5","Yer 10:25"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 7, 'Noa sa la''a ma''uwu Yakobo ba no ladudugö nahiara.', '["Yer 9:11","Sin 44:14","Sin 80:5","Yer 10:25"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 8, 'Böi be''e horöma golalöŵa ndra tuama; ta''i-ta''i faondragö khöma wa''ahakhö dödöu andrö, noa sa amomo sibai ndra''aga.', '["Sin 42:4; 115:2; Yoel 2:17","Sin 137:7"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 9, 'Tologa, ya''ugö Lowalangi fangorifima, börö duria döimö andrö; orifi ndra''aga, ba efa''ö khöma horöma, börö döimö.', '["Sin 42:4; 115:2; Yoel 2:17","Sin 137:7"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 10, 'Hana wa tola laŵa''ö niha baero: "Heza so Lowalangira?" Akha oroma ba niha baero, ba zi so ya''aga, wolau balö ndro genoniu andrö, si no mufaduwa![6]', '["Sin 42:4; 115:2; Yoel 2:17","Sin 137:7"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 11, 'Akha irugi dögi dalingau fangarö-ngarö nikuru andrö; orifi mbunusö andrö, ba wa''abölö dangamö.', '["Sin 42:4; 115:2; Yoel 2:17","Sin 137:7"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 12, 'Fitu winaeta sulöni ba zi so ba ngaima, barö dotora bakha, wango''aya andrö, fango''ayara ya''ugö, ya''ugö So''aya.[7]', '["Sin 42:4; 115:2; Yoel 2:17","Sin 137:7"]', NULL),
  (3476091, 'OT', 'Sinunö', 79, 13, 'Ba ya''aga, banuau andre, biri-biri nikubaloimö, ba lö mafamalö-malö wangandrö saoha gölö khöu, ba madunö-dunö duriamö, götö-götö wa''ara.', '["Sin 42:4; 115:2; Yoel 2:17","Sin 137:7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 1, 'Khö duka wanunö andrö, dali: "Ladari mböhö." Famaduhu''ö; khö Gasafo; umanö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476092, 'OT', 'Sinunö', 80, 2, 'Fondrondrongo, ya''ugö kubalo Ndraono Gizeraeli! Ya''ugö solohe tanga Ndraono Yosefo, nifolohe biri-biri! Sidadao yaŵa Kerubi, oroma''ögö!', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 3, 'Oroma''ö wa''abölöu tanö föna Ndraono Geferayi ba tanö föna Ndraono Mbeniyami ba tanö föna Ndraono Manase! tologa!', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 4, 'He Lowalangi! fuli azökhi ndra''aga, ba fohaga mbawau, ena''ö auri ndra''aga![1]', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 5, 'He Yehowa, Lowalangi ngahönö, heza irugi, wa mofönu ndra''ugö, na mangandrö mbanuamö?', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 6, 'Atoru daŵa hörö ba gö andrö, nibe''eu khöra, öfabadugö khöra daŵa hörö, si no fahöna.[2]', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 7, 'Öbe''e amadöniŵa zi so ba ngaima ndra''aga, ba la''o''aya ndra''aga si fa''udu khöma.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 8, 'He Lowalangi ngahönö, fuli azökhi ndra''aga, ba fohaga mbawau, ena''ö auri ndra''aga![3]', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 9, 'Ŵeŵe nagu no ödeha ba danö Miserayi! no ötimba niha baero, ba no ötanö ia.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 10, 'No öfonaha fönania, ba moŵa''a ia, ibalugö danö.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 11, 'Telumö hili khönia, ba ibalugö geresi Lowalangi andrö dahania.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 12, 'Ibologö ndrahania, irugi nasi ba lewiönia, irugi nidanö sebua andrö [Oifarati].', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 13, 'Hana wa no ödudugö gölinia, fa lafafatö ia dozi sanörö?[4]', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 14, 'Isulagö ia la''imba''imba ba gatua, ba la''a ia saliŵa-liŵa ba danö.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 15, 'He Lowalangi ngahönö, ena''ö na öfuli''ö! Faigi moroi ba zorugo ba nehegö, ba tolo ŵeŵe nagu andrö,', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 16, 'tanömö andrö, nitanö dangau kambölö, ono andrö, ni''abe''e''ömö khöu.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 17, 'No i''a alitö, no lafalo''o; ba wönu mbawamö andrö mate ira.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 18, 'Balugö tangau niha gambölöu andrö, ono niha andrö ni''abe''e''ömö khöu.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 19, 'Ba lö faröi ndra''aga khöu! Orifi ndra''aga, ba ma''angaröfi li döimö.', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476092, 'OT', 'Sinunö', 80, 20, 'He Yehowa, Lowalangi ngahönö, fuli azökhi ndra''aga! Fohaga mbawau, ena''ö auri ndra''aga.[5]', '["Ayati 7,19","Sin 102:10","Ayati 3,19; Yes 5:1–7; Hos 10:1","Sin 89:42","Ayati 3,7"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 1, 'Khö duka wanunö andrö, dali Gititi andrö; khö Gasafo.', '[]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 2, 'Milau manunö khö Lowalangi fangabe''eda andrö, mi''omusoi''ö dödömi ba khö Lowalangi Yakobo.', '["MozIII 23:24,34","MozII 17:7; MozIV 20:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 3, 'Milau manunö ba mibözi garamba, mifoli ngawalö mbiola, somasi ita.', '["MozIII 23:24,34","MozII 17:7; MozIV 20:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 4, 'Milau zurune, ba wasulöna, ba ba duli, ba mbaŵa gowasa andrö khöda.[1]', '["MozIII 23:24,34","MozII 17:7; MozIV 20:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 5, 'Huku sa da''ö ba Ndraono Gizeraeli, nifakhoi Lowalangi Yakobo.', '["MozIII 23:24,34","MozII 17:7; MozIV 20:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 6, 'Ba wamaduhu''ö ihonogöi ba khö Yosefo, me möi ia, me itörö danö Miserayi. No urongo li, si lö u''ila (imane):', '["MozIII 23:24,34","MozII 17:7; MozIV 20:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 7, '"No uheta noro andrö ba hulunia, no aheta ba dangania raga-raga andrö.', '["MozIII 23:24,34","MozII 17:7; MozIV 20:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 8, 'No mangarö-ngarö ndra''ugö, ba wamakao andrö, ba no u''efa''ö ndra''ugö; no utema liu, moroi ba mbalu-balu mbanua andrö; no utandraigö''ö ba nidanö wasosota andrö.[2]', '["MozIII 23:24,34","MozII 17:7; MozIV 20:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 9, 'Mifondrondrongo, ya''ami banuagu, ba da''ufaduhu''ö khömi. Ena''ö na mifondrondrongo khögu, ya''ami Iraono Gizeraeli!', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 10, 'Böi falukha ba khömi Lowalangi bö''ö, ba böi mangalulu ami ba Lowalangi Ndrawa, baero.[3]', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 11, 'Ya''odo Yehowa, Lowalangimö, si no molohe miyaŵa ya''ugö, moroi ba danö Miserayi; faboka mbawau, da''ufo''ösi.', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 12, 'Ba lö nifondrondrongo mbanuagu ligu, ba lö ni''o''ö Ndraono Gizeraeli khögu.', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 13, 'Ba no ululu ira, ba wa''abe''e dödöra andrö, ba latörö nikhoi dödöra.[4]', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 14, 'Ena''ö na lafondrondrongo khögu banuagu andrö, ena''ö na latörö lala andrö khögu Iraono Gizeraeli!', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 15, 'Ba lö ara, ba uhöndrögö zi fa''udu khöra, ba ulau ba zamakao ya''ira andrö.', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 16, 'Ba fahuwu ena''ö khöra zi fatiu tödö khö Yehowa, ba lö tebulö ira, irugi zi lö aetu.', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476093, 'OT', 'Sinunö', 81, 17, 'Ba ubalazoi ena''ö ira fakhe si sökhi, ba u''abusoi''ö ami ŵe ŵani moroi ba dögi gara.[5]', '["MozII 20:2,3","HalZin 14:16","MozV 32:13"]', NULL),
  (3476094, 'OT', 'Sinunö', 82, 1, 'No so Lowalangi ba mbanua Lowalangi andrö, sanguhuku ia, ba hunö Lowalangi (sanguhuku) andrö.[1]', '["Ayati 6","MozV 1:17","Yes 1:17","Ayati 1; MozII 21:6; Yoh 10:34"]', NULL),
  (3476094, 'OT', 'Sinunö', 82, 2, '"Ha wa''ara na mibalia''ö huku, wango''awögu solau si lö sökhi?[2]', '["Ayati 6","MozV 1:17","Yes 1:17","Ayati 1; MozII 21:6; Yoh 10:34"]', NULL),
  (3476094, 'OT', 'Sinunö', 82, 3, 'Mi''ohe ba lala huhuo zide-ide andrö ba huhuo zi lö ama, si lö ina; mitolo nifakao ba si numana, ba mi''atulö''ö.[3]', '["Ayati 6","MozV 1:17","Yes 1:17","Ayati 1; MozII 21:6; Yoh 10:34"]', NULL),
  (3476094, 'OT', 'Sinunö', 82, 4, 'Mi''efa''ö zide-ide ba si numana, mi''efa''ö ia ba danga zolau si lö sökhi andrö."', '["Ayati 6","MozV 1:17","Yes 1:17","Ayati 1; MozII 21:6; Yoh 10:34"]', NULL),
  (3476094, 'OT', 'Sinunö', 82, 5, 'Lö la''ila hadia ia ba lö saboto ba dödöra, ba zogömi-gömi lalara; andrö humeuheu latalata danö fefu.', '["Ayati 6","MozV 1:17","Yes 1:17","Ayati 1; MozII 21:6; Yoh 10:34"]', NULL),
  (3476094, 'OT', 'Sinunö', 82, 6, 'Ya''o zanguma''ö: "Lowalangi ami, ono Wondrege zalaŵa ami fefu.[4]', '["Ayati 6","MozV 1:17","Yes 1:17","Ayati 1; MozII 21:6; Yoh 10:34"]', NULL),
  (3476094, 'OT', 'Sinunö', 82, 7, 'Ba mate zui ami, fa''amate niha, ba fa''atekiko zalaŵa andrö wa''atekikomi dania."', '["Ayati 6","MozV 1:17","Yes 1:17","Ayati 1; MozII 21:6; Yoh 10:34"]', NULL),
  (3476094, 'OT', 'Sinunö', 82, 8, 'Faoso Lowalangi, huku guli danö, ya''ugö sa atö zokhö fefu soi niha!', '["Ayati 6","MozV 1:17","Yes 1:17","Ayati 1; MozII 21:6; Yoh 10:34"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 1, 'Sinunö; khö Gasafo.', '[]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 2, 'He Lowalangi, böi si lö liŵa-liŵa ndra''ugö, böi si lö hede-hede, ba böi sahono manö, ya''ugö Lowalangi!', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 3, 'Hiza sa, fagua-gua zi fa''udu khöu, ba fayaŵa zi fatiu tödö khöu.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 4, 'La''alui lala, ba wangalani banuau, la''onekhesi; mamagölö ira, ba wolau ba nirorogömö andrö.[1]', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 5, 'Lamane: "Talabu! tahori ira, ena''ö adudu ira, ena''ö lö''ö sa''ae itörö tödö niha Ndraono Gizeraeli andrö."', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 6, 'Mamagölö sa''ae ira, ha sara dödö, lafaböbö ira udumö.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 7, 'Ösi nose Ndraono Gedomo andrö ba ösi nose Ndraono Zima''eli. Iraono Moabi ba ma''uwu Hagara;', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 8, 'Iraono Gebala ba Iraono Gamoni ba Iraono Gamaleki ba Dawa Wilisiti, fabaya banua Diro andrö.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 9, 'Ba no lafaböbö ira göi khöra Dawa Asiria andrö, no tobali ta''io ma''uwu Loti ira.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 10, 'Lau khöra, si mane folaumö ba Ndraono Midiano no, si mane khö Zisera ba si mane khö Yabino no, ba mbewe Gizona![2]', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 11, 'Nihori no ba Gendrora, si no tobali oboula, fangatabö zinanö ba danö.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 12, 'Fatörö ba zalaŵara nifatörö khö Gorebi no ba khö Zebi ba khö Zeba ba khö Zalamuna, ba nibayoini andrö khöra, fefu.[3]', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 13, 'Sanguma''ö: "Tahalö khöda naha Lowalangi."[4]', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 14, 'He Lowalangigu, bali''ö zi hulö tawuyu nangi ira, si mane dami wakhe ba nangi.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 15, 'Si mane alitö, na akhozi gatua, ba si mane hola-hola galitö, na itörö hili.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 16, 'Ömanö wolohi ya''ira angi andrö khöu, ba öfeta''u ira angi sabölö khöu.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 17, 'Hawui mbawara fa''aila, ena''ö lasofu döimö, ya''ugö Yehowa.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 18, 'Alakha aila ira, ba alakha tobali dödöra, si lö mamalö-malö; hana na aila ira ba hana na tekiko.', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476095, 'OT', 'Sinunö', 83, 19, 'Ba akha aboto ba dödöra, wa no ha ya''ugö zotöi Yehowa, wa ha ya''ugö Wondrege zalaŵa ba guli danö ma''asagörö.[5]', '["Sin 27:5; 35:20","Sanguhuk 7:22; 4:15,21,23","Sanguhuk 7:35; 8:21","Sin 74:8","Hos 12:6"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 1, 'Khö duka wanunö andrö, dali Gititi, ba Ndraono Gora andrö; sinunö.[1]', '["Nga''ötI 26:1"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 2, 'Wa''asökhi nahiamö andrö, ya''ugö Yehowa ngahönö!', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 3, 'Humulu dödögu, ba we''amöi ba golayama Yehowa andrö, olofo. Tödögu ba ösigu ma''iki, wangondrasi Lowalangi sauri andrö.[2]', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 4, 'No isöndra nahia siliŵi, ba katawaena, ba no isöndra gazuni khönia, ba nifonahara onora; naha wame''e sumange andrö khöu, ya''ugö Yehowa ngahönö, razogu ba Lowalangigu.[3]', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 5, 'Ya''ahowu zonahia ba nomo andrö khöu, lasuno na ndra''ugö dania.[4]', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 6, 'Ya''ahowu, niha, si no mangai fa''abölönia ya''ugö: lö olifu ira lala nitörö andrö.', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 7, 'Na latörö ndraso andrö si lö idanö, ba labali''ö si so umbu; ihawui howu-howu teu sahulö andrö.', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 8, 'Mowaö-waö ira, ba tedou-dou wa''abölö, ba tanö föna Lowalangi ba Ziona so ira.', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 9, '(Lamane:) He Lowalangi ngahönö, fondrondrongo wangandrögu! Be''e ba dödöu, ya''ugö, Lowalangi Yakobo!', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 10, 'Faigi lala, ya''ugö Lowalangi balusema, ba faigi mbawa nibayoinimö andrö.[5]', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 11, 'Sökhi zi ha ma''öma''ökhö ba golayamamö, moroi ba zi hönö ngaluo bö''ö. Omasido ba mbagi nora ba nomo Lowalangigu mörödo, moroi ba nomo zi so horö so nahagu.[6]', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 12, 'Luo ba baluse Yehowa, Lowalangi. Fa''ebua dödö ba lakhömi ifa''ema Yehowa. Lö zi lö ibe''e zi sökhi ba zanörö lala satulö.[7]', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476096, 'OT', 'Sinunö', 84, 13, 'He Yehowa ngahönö! Ya ahowu niha, sanötöna khöu.', '["Sin 42:3,5","Sin 5:3","Sin 65:5","Sin 72:15","Sin 27:4","Sin 3:4; 34:11"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 1, 'Khö duka wanunö andrö, nilau Ndraono Gora andrö; sinunö.', '[]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 2, 'No ahakhö dödöu mbanuau andrö, ya''ugö Yehowa, no ö''ohe mangawuli nira''u andrö, ma''uwu Yakobo.', '["Sin 89:50","Sin 77:8"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 3, 'No öbe''e aefa lalö mbanuau andrö, ba horöra fefu, ba no öbalugö.[1]', '["Sin 89:50","Sin 77:8"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 4, 'No ötaha wa''abao dödöu ba no öböhöli wa''aukhu wönumö andrö.', '["Sin 89:50","Sin 77:8"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 5, 'Fuli asökhi ndra''aga, ya''ugö Lowalangi sangorifi ya''aga, ba böhöi wa lö sökhi dödöu khöma!', '["Sin 89:50","Sin 77:8"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 6, 'Hadia, irugi zi lö aetu edöna mofönu''ö khöma? hadia, lö mamöhöi wönumö andrö, götö-götö wa''ara?[2]', '["Sin 89:50","Sin 77:8"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 7, 'Hadia, lö öfuli ö''orifiga, ena''ö omuso dödö mbanuau andrö khöu?', '["Sin 89:50","Sin 77:8"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 8, 'Oroma''ö khöma wa''ebua dödöu, ya''ugö Yehowa; ba be''e bualamö khöma wangorifi andrö khöu.', '["Sin 89:50","Sin 77:8"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 9, 'Da''ufondrongondrongo hadia niŵa''ö Lowalangi, Yehowa; ifabu''u sa wa''ohahau dödö ba mbanuania ba ba zatulö tödö andrö khönia; ba böi lafuli ira ba waya-faya.[3]', '["Sin 72:3"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 10, 'Si ndruhu, no ahatö wangorifi andrö khönia, ba zangata''ufi ya''ia, ena''ö monahia zui lakhömi ba danöma andre.', '["Sin 72:3"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 11, 'Faondra ira wa''ebua dödö wa''aduhu, fa''ago bawa ira wa''atulö wa''ohahau dödö.', '["Sin 72:3"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 12, 'Auri moroi barö danö wa''aduhu, ba ifaigi moroi ba mbanua si yaŵa fa''atulö.', '["Sin 72:3"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 13, 'Fefu hadia ia zi sökhi ibe''e Yehowa, ba i''oro''ö mbua zinanö khönia tanöma andre.', '["Sin 72:3"]', NULL),
  (3476097, 'OT', 'Sinunö', 85, 14, 'Mowaö-waö fönania wa''atulö, itöngöni lala nibekainia.', '["Sin 72:3"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 1, 'Be''e mbörö dalingau, ya''ugö Yehowa, ba fondrondrongo khögu; no sabu tödö ndra''o ba si numana.', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 2, 'Rorogö nosogu, me no satulö tödö ndra''o; tolo genonimö, sanötöna khöu, ya''ugö Lowalangigu![1]', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 3, 'Hakhösi tödö ndra''o, So''aya, khöu sa mu''ao ndra''o, ma''öma''ökhö.[2]', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 4, 'Omusoi''ö dödö genoniu; khöu sa ufaöga dödögu, So''aya.', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 5, 'Me no si sökhi tödö ndra''ugö, ba me sebolo tödö, ya''ugö So''aya, ba me no fahöna wa''ebua dödöu ba zi angaröfi li ya''ugö, fefu.[3]', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 6, 'Be''e ba dödöu wangandrögu, Yehowa, ba fondrondrongo li we''aogu andre.', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 7, 'U''angaröfi li ndra''ugö, na baŵa wa''afökhö khögu, öfondrondrongo sa ligu.[4]', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 8, 'Lö Lowalangi si mane ya''ugö, ya''ugö So''aya, ba lö si mane folaumö andrö.[5]', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 9, 'Dozi soi, niwöwöimö andrö, ba möi dania mangalulu khöu, ya''ugö So''aya, awö wamosumange töimö andrö.', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 10, 'Me no sebua ndra''ugö ba me solau sahöli-höli dödö; ha ya''ugö Lowalangi.', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476098, 'OT', 'Sinunö', 86, 11, 'Ombakha''ö khögu lala andrö khöu, Yehowa, ena''ö utörö ia, ba zi faduhu dödöu; osambalö''ö dödögu ba wangata''ufi töimö andrö.[6]', '["Sin 18:21–27","Sin 6:3","Ayati 15","Sin 50:15","Sin 71:19","Sin 27:11"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 12, 'U''andrö saoha gölö khöu, ya''ugö So''aya, Lowalangigu, moroi si''aikö ba dödögu, ba usuno döimö, si lö aetu.', '["MozII 34:6","Sin 116:16"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 13, 'Me no ebua sibai dödöu khögu, ba me no ö''efa''ö nosogu ba mbaho mbanua tou andrö.', '["MozII 34:6","Sin 116:16"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 14, 'He Lowalangi, no maoso khögu zebua fayaŵasa, ba la''alui nosogu sabölö, si no orudu, ba lö ba dödöra ya''ugö.', '["MozII 34:6","Sin 116:16"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 15, 'Ba Lowalangi sahakhö tödö ndra''ugö ba sebua tödö, ya''ugö So''aya, sebolo tödö ndra''ugö ba si no fahöna fa''asökhi dödö ba fa lö faröi.[7]', '["MozII 34:6","Sin 116:16"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 16, 'Otahögö ndra''o ba ebua''ö dödöu khögu; be''e khö genoniu andre wa''abölöu ba tolo nono genoniu ira alawe andrö.[8]', '["MozII 34:6","Sin 116:16"]', NULL),
  (3476098, 'OT', 'Sinunö', 86, 17, 'Fazökhi dandra ba khögu ba zi sökhi, ena''ö la''ila si fatiu tödö khögu, ba ena''ö aila ira, me no ötolo ndra''o, ya''ugö Yehowa, ba me no örara dödögu.', '["MozII 34:6","Sin 116:16"]', NULL),
  (3476099, 'OT', 'Sinunö', 87, 1, 'Nitaru''önia ba hili ni''amoni''ö andrö,', '["Yes 30:7; Sin 68:32"]', NULL),
  (3476099, 'OT', 'Sinunö', 87, 2, 'I''omasi''ö Yehowa mbawa göli Ziona andrö, moroi ba nahia ma''uwu Yakobo fefu.', '["Yes 30:7; Sin 68:32"]', NULL),
  (3476099, 'OT', 'Sinunö', 87, 3, 'Si sökhi sibai duriamö, ya''ugö banua Lowalangi.', '["Yes 30:7; Sin 68:32"]', NULL),
  (3476099, 'OT', 'Sinunö', 87, 4, 'Utötöi Rakhaba [Miserayi] ba Babeli, si no fa''ila li khögu. Hiza danö Wilisiti ba Tiro ba Aitiofia: si no tumbu ba da''ö.[1]', '["Yes 30:7; Sin 68:32"]', NULL),
  (3476099, 'OT', 'Sinunö', 87, 5, 'Ba lamane dania ba mbanua Ziona: Oi ba khöra tumbu ira ba ya''ia zangaro''ö ya''ira, Fondrege zalaŵa andrö.', '["Yes 30:7; Sin 68:32"]', NULL),
  (3476099, 'OT', 'Sinunö', 87, 6, 'I''erai dania soi niha andrö Yehowa, ba itanö ba zura: "Si no tumbu ba da''ö."', '["Yes 30:7; Sin 68:32"]', NULL),
  (3476099, 'OT', 'Sinunö', 87, 7, 'Ba manunö ira ba molaya (ba lamane): Ba khöu so gumbu andrö khögu, fefu.', '["Yes 30:7; Sin 68:32"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 1, 'Sinunö, nilau Ndraono Gora andrö, khö duka wanunö andrö, dali ba wanunö "Mahalata" andrö; famahaö; khö Hemano andrö, ma''uwu Zera.', '[]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 2, 'He Yehowa, Lowalangi sangorifi ya''o, na luo mu''aodo khöu ba zi bongi,', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 3, 'ba yamurugi ndra''ugö fangandrögu, be''e mbörö dalingau ba wangarö-ngarögu!', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 4, 'No aföli dödögu wamakao, no ahatö ba mbanua tou nosogu.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 5, 'Hulö zilalö mitou ba gohokoho, wamaigi niha bö''ö ya''odo, hulö niha si no amomo ndra''odo.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 6, 'No mululu ndra''o, awö zi no mate, hulö nibunu tou, si no mutanö, ba lewatö, si lö itörö tödöu sa''ae, si no ötibo''ö.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 7, 'No öbe''e ndra''o ba gohokoho, ba mbaho, ba zogömi-gömi, ba namö ba nasi.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 8, 'Khögu tohare wa''abao dödöu, ba öhawui ndra''o dulu andrö khöu.[1]', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 9, 'No ö''aröu''ö khögu zi no fa''ila li khögu; no ogoro ira ndra''o öbe''e; si no mukuru ndra''o, ba tebai aefada.[2]', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 10, 'Itugu abösi hörögu ba wamakao andrö; u''angaröfi li ndra''ugö, ya''ugö Yehowa, ero ma''ökhö, u''oro''ö dangagu khöu.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 11, 'Hadia, öfazökhi dandra ba zi no mate? Hadia, ifuli auri lumö, ba wanunö ya''ugö?[3]', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 12, 'Hadia, ba lewatö lafatunö wa ebua dödöu, ba ba gawuwukha lafatunö, wa si lö faröi ndra''ugö?', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 13, 'Hadia, aboto ba dödö dandra andrö khöu, ba zogömi-gömi, ba aboto ba dödö wa''atulömö andrö ba danö wa''olifu?', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 14, 'Ba ya''o, ba khöu mu''aodo, ya''ugö Yehowa; uhulöhulö wongi, wangandrö khöu.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 15, 'Hana wa lö ba dödöu nosogu, ya''ugö Yehowa, ba hana wa öbini''ö khögu mbawau?', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 16, 'Sebua akaola ndra''o ba si mate, i''otarai iraono ndra''o; utaha wameta''u andrö khöu, ba lö lala dödögu.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 17, 'No itörödo fönumö sabölö-bölö andrö, no terasa ndra''o ba gameta''uö andrö khöu.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 18, 'No te''u''u ndra''o khönia, hulö na ba nidanö, ma''öma''ökhö, no tefasui manö ndra''o khönia.', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476100, 'OT', 'Sinunö', 88, 19, 'No ö''aröu''ö khögu zi fahuwu khögu, fabaya awögu, lö oroma zi no fa''ila li khögu.[4]', '["Sin 42:8","Ayati 19; Sin 31:12; 38:12","Sin 6:6","Ayati 9"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 1, 'Famahaö khö Getano, ma''uwu Zera.[1]', '["Faigi göi SamII 7:8–16"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 2, 'Da''usuno wa''ebua dödö Yehowa andrö, irugi zi lö aetu, götö-götö wa''ara u''ombakha''ö bewegu andre, wa si lö faröi ndra''ugö.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 3, 'Noa sa ömane: "Si lö aetu wa''atedou wa''ebua dödö andrö"; ba mbanua si yaŵa ö''aro''ö, wa lö faröi ndra''ugö.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 4, '"No fawu''u li ndra''o khö nituyugu andrö, no fahölu ndra''o khö genonigu Dawido andrö:[2]', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 5, 'Irugi zi lö aetu lö ubulö''ö madoumö andrö, irugi nga''ötö mitou u''a''aro''ö dadaomamö."', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 6, 'Ba lasuno banua si yaŵa zahöli-höli dödö andrö khöu, ya''ugö Yehowa, ba fa lö faröi ndra''ugö ba walukhata niha ni''amoni''ö.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 7, 'Ha niha atö ba lawuo si yaŵa zi mane Yehowa? Ha niha zi mane Yehowa ba ndraono Lowalangi andrö?[3]', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 8, 'Sata''u ita Lowalangi ba walukhata sebua ba niha ni''amoni''ö ba sihokha mbu niha, fefu zi tefasui ya''ia.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 9, 'He Yehowa, Lowalangi ngahönö, ha niha zi mane ya''ugö, salaŵa sebua? ba no tefasui ndra''ugö wa lö faröi andrö, khöu.[4]', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 10, 'Ba dangau so hokha nasi andrö; na ebua ndrulunia, ba ya''ugö zangahono.[5]', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 11, 'Ya''ugö mege zanguhundragö Rakhaba [Miserayi] andrö, hulö nibunu, tou ba danö, no öfazawili zi fa''udu khöu tangau sabölö andrö.[6]', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 12, 'Khöu mbanua si yaŵa ba khöu göi danö; uli danö, ba ösinia, ba ya''ugö mege zomböi.[7]', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 13, 'Yöu ba raya, ba ya''ugö zamazökhi; Tabora ba Heremono ba lakaraini wa''iki, ba döimö andrö.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 14, 'Sabölö sibai mbulökhamö ba sabe''e dangau, ba no alaŵa gambölöu andrö.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 15, 'Fa''atulö ba fa''adölö dayadaya dadaomamö andrö; ba sanaro fönau wa''ebua dödö ba fa''aduhu.[8]', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 16, 'Ya ahowu soi, sangila ma''iki; sanörö lalara ba haga mbawau andrö, ya''ugö Yehowa.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 17, 'Ba döimö andrö lakaraini wa''iki, si lö mamalö-malö ba wa''atulömö andrö salaŵa ira.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 18, 'Fa''amoadu wa''abölöra ndra''ugö, ba ba wa''asökhi dödöu andrö alaŵa dandrura andrö.', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 19, 'Khö Yehowa sa mbalusema andrö, ba khö ni''amoni''ö andrö ba Ndraono Gizeraeli razoma.[9]', '["Sin 132:11; Yes 55:3; HalZin 2:30","Yob 1:6","Sin 115:3","Mat 8:26; Sin 65:8","Sin 87:4","Sin 24:1","Sin 97:2","Sin 47:10"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 20, 'Me no andrö, ba no muhede ndra''ugö ba zatulö tödö andrö khöu, ba gangilata, ömane: "No utolo zabölö, no ubali''ö salaŵa nono matua, ono mbanua.[10]', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 21, 'No usöndra genonigu Dawido andrö, no ubayoini ia fanikha ni''amoni''ö andrö khögu.[11]', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 22, 'Lö aefa dangagu khönia, ba i''abe''e''ö ia bulökhagu.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 23, 'Lö tola ilimo ia si fatiu tödö, ba lö tola ifakao ia si lö atulö.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 24, 'Ufufu dania fönania zi fa''udu khönia, ba ubözi tou zi fatiu tödö khönia.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 25, 'I''o''awögö ia fa lö faröi ndra''o ba fa''ebua dödögu andrö; ba ba döigu dania alaŵa dandrunia andrö.[12]', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 26, 'Ufababaya''ö khönia nasi, ba ibabaya mboto nidanö kambölönia ube''e.[13]', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 27, 'Imane dania wangaröfi li ya''o: "Amagu ndra''ugö, Lowalangigu ba fangabe''e dödögu, ba wangorifigu andrö."[14]', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 28, 'Ba ya''o göi, ube''e si a''a ia, fondrege zalaŵa ba guli danö.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 29, 'Irugi zi lö aetu, lö ubulö''ö khönia wa''ebua dödögu andrö, ba böi awu''a wawu''usa li andrö khöma.[15]', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 30, 'Ba lö ube''e aetu nga''ötönia, ba dadaomania, ba fa''ara mbanua si yaŵa ube''e.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 31, 'Na la''erogö goroisagu ononia, na lö latörö lala andrö, khögu;', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 32, 'na la''o''aya gamakhoitagu ba na lö la''o''ö goroisagu,', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 33, 'ba u''otu''ö ira bözi-bözi ba horöra andrö, ba famakao ba lalöra.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 34, 'Ba lö''ö zui ubulö''ö khönia wa''ebua dödögu, lö ulimo ia, lö faröi ndra''o.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 35, 'Lö u''o''aya wawu''usa li andrö khögu, ba lö uwu''ai niŵa''ögu.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 36, 'Sambalö si fahölu ndra''o ba wa''atulögu andrö, si ndruhu-ndruhu lö ulimo Dawido andrö.', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 37, 'Lö tola aetu nga''ötönia; ba dadaomania, ba hulö luo, fönagu.[16]', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 38, 'Si mane baŵa si yaŵa lö tebulö ia, ba lö faröi zamaduhu''ö andrö ba mbanua yaŵa."[17]', '["Ayati 4; SamI 13:14","SamI 16:13","SamI 2:10; Sin 132:17","Sin 72:8","SamII 7:14","Yes 54:10","Sin 72:17","MozI 9:13"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 39, 'Ba noa sa''ae ötibo''ö, ba no lö ba dödöu: no mofönu ndra''ugö khö nibayoinimö andrö.[18]', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 40, 'No ö''ositengagö wawu''usa li andrö khö genoniu andrö, no öhundragö tou zaembunia.', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 41, 'No ödudugö göli andrö khönia fefu, no öbali''ö adudula hatinia andrö.', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 42, 'Larabu hadia ia khönia dozi sanörö, no tobali fama''iki ia ba zi so ba ngainia.[19]', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 43, 'No ö''alaŵa''ö gambölö zamakao ya''ia, no ö''omusoi''ö dödö zi fatiu tödö khönia, fefu.', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 44, 'No öbe''e mangandrauli mbawa wödania, ba lö ni''abe''e''ömö ya''ia ba wanuwö.', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 45, 'No öbe''e taya lakhöminia, ba no öso''agö dadaomania.', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 46, 'No ö''ambösi khönia mbaŵa wa''ono matua, no öbalugö manö ia fa''aila.', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 47, 'Ha wa''ara na sa, wa lö mamalö-malö öbini''ö ndra''ugö, ya''ugö Yehowa? Ba ha wa''ara na muhola wönumö andrö, hulö galitö?[20]', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 48, 'Törö tödöu, wa lö anaunau nosogu andre; he wisa wa lö boto andrö, ba nifazökhiu ono niha fefu.[21]', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 49, 'Heza so niha, sauri manö, si lö mangila fa''amate, sangefa''ö bekhunia ba wa''abölö mbanua tou andrö?', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 50, 'Hezo wa''ebua dödöu föna, ya''ugö So''aya, nifabu''umö khö Dawido, fahölusa, ba wa lö faröi ndra''ugö?[22]', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 51, 'Törö tödöu, So''aya, wa''aila genonimö andrö, wa ulu''i wango''aya niha sato, soya soi.', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 52, 'Sanandraŵa — si fa''udu khöu, Yehowa, sanandraŵaisi lahe nibayoinimö andrö.', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476101, 'OT', 'Sinunö', 89, 53, 'Nisuno Yehowa, irugi zi lö aetu. Ya duhu, Ya duhu![23]', '["Sin 44:10–25; 74:79","Sin 80:13","Sin 85:6","Sin 90:9,10","Sin 85:2","Sin 41:14"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 1, 'He So''aya! Saŵatöma ndra''ugö, götö-götö wa''ara.', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 2, 'Me lö''ö na si tumbu hili, me lö niwöwöimö na tanö, awö golia uli danö fefu, götö-götö wa''ara, ba no Lowalangi ndra''ugö.', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 3, 'Öfuli öbali''o gawu-gawu niha, ba öfuli öŵa''ö: Mifa''aso ami, ono niha![1]', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 4, 'Hulö zi ma''ökhö menewi, na no numalö ia, si manö khöu zi hönö fakhe, hulö zango''öfa zi sara wongi.[2]', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 5, 'Öhanigö ira, fangifi ira; ba na mahemolu mbanua, ba hulö ndru''u, si fuli molöndru.[3]', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 6, 'Sobowo si hulö wongi ba sobulu, ba na tanö owi, ba lataba ia ba aleu.', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 7, 'Fönumö andrö sa zi manga ya''aga ba ba wa''abao dödöu andrö tekeani ndra''aga.', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 8, 'Horöma no öbe''e ba gamaudumö, ba folauma si lö oroma, ba no öbe e ba haga mbawamö andrö.', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 9, 'Taya-taya sa mbongima fefu, ba wa''abao dödöu andrö; hulö deatea mbewe wa''anumalö ndröfima andrö.', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 10, 'Fa''anau nosoma andrö, ba fitu ngafulu fakhe, ba na anau, ba ŵalu ngafulu fakhe, ba si sökhinia, ba fangerege dödö ba famakao, si fulöi ia wa''anumalö, sihombo ndra''aga.[4]', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 11, 'Ha niha zaboto ba dödö fa''abölö wönumö andrö, ba fa''abao dödöu andrö, wangata''ufi ya''ia?', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 12, 'Fahaö ndra''aga ba wangerai bongima, ena''ö masöndra dödö satua-tua.[5]', '["Sangomb 1:4; 12:7","FetII 3:8","Sin 102:12; 103:15; Yob 14:2; Yes 40:6,7","Sangomb 1:3,8","Sin 39:5"]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 13, 'Fuli''ö, Yehowa: Ha lö ara''ö! ba hakhösi tödö genonimö andre.', '[]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 14, 'Hulö wongi abusoi''ö ndra''aga fa''ebua dödöu andrö, ba owua-wua dödöma ba omuso dödöma, sagötö ya''aga.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476102, 'OT', 'Sinunö', 90, 15, 'Omusoi''ö dödöma, ndrohugö mbaŵa, si mane me öhöndrögö ndra''aga mege, ba ndrohugö ndröfi, si mane me ma''ila zi lö sökhi.', '[]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 16, 'Oroma''ö ba genonimö halöŵöu andrö, ba oroma''ö lakhömiu ba ndra''onora.', '[]', NULL),
  (3476102, 'OT', 'Sinunö', 90, 17, 'Ya oroma khöma wa''asökhi dödö Zo''aya, Lowalangima, khöma; tolo ndra''aga ba halöŵö dangama andrö; ya''ia, ba halöŵö dangama andrö tologa!', '[]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 1, 'Sonahia barö mba''a-ba''a andrö khö Wondrege zalaŵa andrö, da''ö zahono ba lumö Wondrege zabölö andrö.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 2, 'Umane khö Yehowa: "Saŵatögu ndra''ugö ba hatigu, Lowalangigu, tötöna fögu!"[1]', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 3, 'I''efa''ö ndra''ugö ba dandraŵa andrö khö zolau tandraŵa wofo, ba i''orifi''ö ba wökhö waba famunu andrö.[2]', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 4, 'Ibalugö ndra''ugö afinia, ba barö gafinia andrö auri ndra''ugö; no ba''a-ba''a ba baluse zi duhu andrö khönia.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 5, 'Lö tola ata''u ndra''ugö gameta''uö andrö ba zi bongi, ba he ono wana sanörö, na ma''ökhö.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 6, 'Fökhö waba andrö, sanörö sogömi-gömi, teu mbanua andrö, famakiko na laluo.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 7, 'He hönö zi mate ba ngaimö, ba he fulu ngahönö zi mate ba gambölöu, ba ya''ugö, ba lö göna.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 8, 'Ha höröu zangila, ba anehe''ö wamasulö andrö ba zolau si lö sökhi.[3]', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 9, 'Me no öŵa''ö: "Ya''ugö sa''ae dötönafögu, Yehowa;" Fondrege zalaŵa andrö no öbe''e saŵatöu.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 10, 'Lö itörö ndra''ugö sabu dödöu, ba lö ihatö''ö ia ba noseu famakao.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 11, 'Iŵa''ö ba mala''ika andrö khönia, ba khömö andrö, ena''ö larorogö ndra''ugö, ba lalamö andrö fefu.[4]', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 12, 'Lataya dania tangara ndra''ugö, fa böi manendre gaheu ba gara.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 13, 'Öhundra-hundra tou zingo ba ulö sosöfu, amama barö gaheu nono zingo, awö naga.[5]', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 14, '"Me i''omasi''ö ndra''o, andrö u''orifi ia, u''efa''ö ia, me no aboto ba dödönia döigu andrö.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 15, 'Na i''angaröfi li ndra''o, ba ufondrondrongo khönia, awönia ndra''o ba wamakao; u''efa''ö ia ba teturia ia ube''e.', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476103, 'OT', 'Sinunö', 91, 16, 'U''abusoi''ö ia fa''anau noso, ba anehe ia wangorifi andrö khögu ube''e."', '["Sin 18:3","Sin 124:7","Sin 54:9","Mat 4:6","Luk 10:19"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 1, 'Fanunö na luo sabato.', '[]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 2, 'Si sökhi, na te''andrö saoha gölö khö Yehowa, ba na masuno döimö, ya''ugö Fondrege zalaŵa.[1]', '["Sin 147:1","Sin 33:2","Sin 104:24; Yes 55:9","Sin 37:2","Sin 97:9"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 3, 'Na te''ombakha''ö wa''ebua dödöu, na mahemolu mbanua, ba fa lö faröi ndra''ugö, ba zi bongi.', '["Sin 147:1","Sin 33:2","Sin 104:24; Yes 55:9","Sin 37:2","Sin 97:9"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 4, 'Ba zi fulu sinali ba ba mbiola nitika, sebua, ba folau somasi ita, ba mbiola nitika, side-ide.[2]', '["Sin 147:1","Sin 33:2","Sin 104:24; Yes 55:9","Sin 37:2","Sin 97:9"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 5, 'Me ö''omusoi''ö dödögu, ya''eogö Yehowa folau-laumö andrö; ma''iki dödögu ba halöŵö dangau andrö.[3]', '["Sin 147:1","Sin 33:2","Sin 104:24; Yes 55:9","Sin 37:2","Sin 97:9"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 6, 'Halöŵö sebua halöŵömö andrö, Yehowa! No anau sibai gera-eramö andrö.', '["Sin 147:1","Sin 33:2","Sin 104:24; Yes 55:9","Sin 37:2","Sin 97:9"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 7, 'Ba niha si lö tödö, ba lö fa''aboto ba dödö, ba ba zambö tödö, ba lö fangila.', '["Sin 147:1","Sin 33:2","Sin 104:24; Yes 55:9","Sin 37:2","Sin 97:9"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 8, 'Na manöi zebua horö andrö, hulö ndru''u ba danö, ba na mobowo zamazökhi si lö sökhi, ba ena''ö tefakiko ira, si lö fangorifi.[4]', '["Sin 147:1","Sin 33:2","Sin 104:24; Yes 55:9","Sin 37:2","Sin 97:9"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 9, 'Ba ya''ugö, ba si no salaŵa, irugi zi lö aetu, ya''ugö Yehowa![5]', '["Sin 147:1","Sin 33:2","Sin 104:24; Yes 55:9","Sin 37:2","Sin 97:9"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 10, 'Hiza sa zi fa''udu khöu, Yehowa! hiza sa zi fa''udu khöu, tekiko; nifazaewe dania fefu zamazökhi si lö sökhi.', '["Sin 23:5","Sin 91:8","Sin 52:10","Sin 84:3","Sin 1:3","MozV 32:4"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 11, 'Ba tandrugu, ba ö''alaŵa''ö, si mane tandru goröbao; tehawui ndra''o fanikha samohua.[6]', '["Sin 23:5","Sin 91:8","Sin 52:10","Sin 84:3","Sin 1:3","MozV 32:4"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 12, 'Omuso dödögu wamaigi sanarogö ya''o andrö; ba omuso dödögu wamondrongo he wisa ba zi maoso udugu andrö, safökhö tödö khögu.[7]', '["Sin 23:5","Sin 91:8","Sin 52:10","Sin 84:3","Sin 1:3","MozV 32:4"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 13, 'Satulö, ba manöi, hulö döwua, ebua ia, hulö geresi ba hili Libano.[8]', '["Sin 23:5","Sin 91:8","Sin 52:10","Sin 84:3","Sin 1:3","MozV 32:4"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 14, 'Nitanö ba nomo Yehowa, ba mobowo ba golayama Lowalangida andrö.[9]', '["Sin 23:5","Sin 91:8","Sin 52:10","Sin 84:3","Sin 1:3","MozV 32:4"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 15, 'Molewiö na ba wa''atua, ba fahöna nidanö döla ba mobulu si bohou.[10]', '["Sin 23:5","Sin 91:8","Sin 52:10","Sin 84:3","Sin 1:3","MozV 32:4"]', NULL),
  (3476104, 'OT', 'Sinunö', 92, 16, 'Ba wangombakha fa''adölö dödö Yehowa, we''e-we''e andrö khögu, ba lö si lö atulö ba khönia.[11]', '["Sin 23:5","Sin 91:8","Sin 52:10","Sin 84:3","Sin 1:3","MozV 32:4"]', NULL),
  (3476105, 'OT', 'Sinunö', 93, 1, 'No razo Yehowa, no monukha ia lakhömi; nukha Yehowa, ba fa''abölö, no i''olembe. Ba aro sa''ae danö, lö mangiwa.[1]', '["MozII 15:18; Sin 97:1; 99:1; 96:10","Sin 19:8–11"]', NULL),
  (3476105, 'OT', 'Sinunö', 93, 2, 'No aro dadaomamö, götö-götö wa''ara sa''ae; ya''ugö, ba si otarai zi lö böröta ae.', '["MozII 15:18; Sin 97:1; 99:1; 96:10","Sin 19:8–11"]', NULL),
  (3476105, 'OT', 'Sinunö', 93, 3, 'Mugoso-goso nidanö, Yehowa; tesao wegoso-goso nidanö, tesao we''ugu-ugu nidanö.', '["MozII 15:18; Sin 97:1; 99:1; 96:10","Sin 19:8–11"]', NULL),
  (3476105, 'OT', 'Sinunö', 93, 4, 'Ba abölö moroi ba wegoso-goso nidanö sebua Yehowa si yaŵa, abölö moroi ba ndrulu nasi andrö, sabe''e sibai.', '["MozII 15:18; Sin 97:1; 99:1; 96:10","Sin 19:8–11"]', NULL),
  (3476105, 'OT', 'Sinunö', 93, 5, 'Aro sibai wamaduhu''ö andrö khöu si nangea ni''amoni''ö nomomö andrö, ya''ugö Yehowa, irugi zi lö aetu.[2]', '["MozII 15:18; Sin 97:1; 99:1; 96:10","Sin 19:8–11"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 1, 'He Lowalangi solau balö, ya''ugö Yehowa! He Lowalangi salau balö, oroma''ögö![1]', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 2, 'Faoso, sanguhuku ösi guli danö, be''e zulö ba zebua hokha andrö![2]', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 3, 'Ha wa''ara zebua horö andrö, Yehowa! ha wa''ara omuso dödö zebua horö andrö?', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 4, 'Lalau huhuo fayaŵasa, lasuno ira dozi samasökhi si lö sökhi.', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 5, 'Larasa mbanuau andrö, Yehowa, ba lafalangögö dana khöu andrö.', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 6, 'Labunu lakha mbanua, awö zi fatewu andrö, ba la''e''eli zi lö ama, si lö ina.', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 7, 'Ba lamane: "Lö i''ila Yehowa, lö anehe Lowalangi Yakobo."[3]', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 8, 'Mibe''e ba dödömi, ya''ami si lö tödö ba niha andre; ba ya''ami sowöhö mowa, ba ha wa''ara atua-tua ami?[4]', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 9, 'Samataro tögi dalinga andrö, hadia lö irongo? Somböi hörö andrö, hadia, lö i''ila?[5]', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 10, 'Sangotu''ö soi niha, hadia, lö ilau mbalö? Ya''ia, samahaö niha ba wa''aboto ba dödö?', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 11, 'I''ila gera-era niha Yehowa, wa no si lö boto.[6]', '["MozV 32:35","MozI 18:25","Sin 10:11","Sin 92:7","MozII 4:11","KorI 3:20"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 12, 'Ya ahowu niha, ni''otu''ömö, ya''ugö Yehowa, nifahaömö ba goroisa andrö khöu![7]', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 13, 'Ba wamaigi khönia sahono ia, na baŵa wamakao, gasa-gasa wa tekhao gohokoho ba zebua horö andrö.[8]', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 14, 'Lö''ö sa itibo''ö mbanuania Yehowa, ba lö faröi ia ba dana khönia andrö.', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 15, 'Mangawuli sa ba wa''atulö huku andrö, ba la''o''ö ia dozi sadölö tödö.', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 16, 'Ha niha zi möi belebelegu, ba zebua horö andrö, ba ha niha zanolo ya''o, ba zamazökhi si lö sökhi?', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 17, 'Na tenga Yehowa zanolo ya''o mena''ö, ba te no irugi danö si lö liŵa-liŵa nosogu andre.[9]', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 18, 'Na umane: "Ahele gahegu", ba ituwu ndra''o fa''ebua dödöu andrö, ya''ugö Yehowa.', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 19, 'Ba wa''oya ngawalö wa''abu dödögu andrö, ba i''okafui dödögu fondrara tödö andrö khöu.[10]', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 20, 'Hadia, faböbö khöu dadaoma wamakiko andrö, somböi fangabu dödö, samali''ö huku?', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 21, 'Lahawui noso zatulö andrö, ba la''etu''ö huku zi lö horö.', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 22, 'Ba belebelegu Yehowa, ba we''e-we''e dödögu Lowalangigu, saŵatögu.', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476106, 'OT', 'Sinunö', 94, 23, 'Isulöni khöra horöra ba ifakiko ira, börö walösökhira andrö, ifakiko ira Yehowa, Lowalangida.', '["Sin 19:12–14; Yob 5:17","Sin 37:7","Sin 115:17","KorII 1:4,5"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 1, 'Talabu, ta''omusoi''ö dödöda ba khö Yehowa, talau ma''iki, börö we''e-we''e dödöda andrö ba wangorifi!', '["Sin 96:4","Sin 100:3; Yoh 10:27,28; Heb 3:7; 4:7"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 2, 'Ta''ondrasi ia wangandrö saoha gölö, ta''omusoi''ö dödöda khönia ba zinunö.', '["Sin 96:4","Sin 100:3; Yoh 10:27,28; Heb 3:7; 4:7"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 3, 'Lowalangi sebua sa Yehowa, razo sebua, yaŵa Lowalangi bö''ö fefu.[1]', '["Sin 96:4","Sin 100:3; Yoh 10:27,28; Heb 3:7; 4:7"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 4, 'Si so ba danga hunö danö andrö, sokhö zuzu hili yaŵa.', '["Sin 96:4","Sin 100:3; Yoh 10:27,28; Heb 3:7; 4:7"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 5, 'Sokhö asi andrö; ya''ia zamazökhi; ba tanö sabe''e andrö, ba no tangania zomböi.', '["Sin 96:4","Sin 100:3; Yoh 10:27,28; Heb 3:7; 4:7"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 6, 'Talabu, tafalögu tou ita, mangalulu ita, tabalöduhini tou danö, föna Yehowa, somböi ya''ita!', '["Sin 96:4","Sin 100:3; Yoh 10:27,28; Heb 3:7; 4:7"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 7, 'Me no Lowalangida ia, ba me no banuania ita, rorogöfönia, nikubaloi dangania.[2]', '["Sin 96:4","Sin 100:3; Yoh 10:27,28; Heb 3:7; 4:7"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 8, 'Ma''ökho andre, na mirongo linia, ba böi mi''abe''e''ö dödömi, si mane ba Meriba no, si mane me luo wanandraigö no, ba danö si mate andrö,', '["MozII 17:2,7","MozIV 14:22,23"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 9, 'ba nitandraigö ndra tuami ya''o, me lafaigi zu''agu, he ŵa''ae no la''ila wolaugu andrö.[3]', '["MozII 17:2,7","MozIV 14:22,23"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 10, 'Öfa wulu fakhe wa''ara abu dödögu niha andrö, ba umane: "Niha selungu tödö ira." Ba lö aboto ba dödöra lala andrö khögu.', '["MozII 17:2,7","MozIV 14:22,23"]', NULL),
  (3476107, 'OT', 'Sinunö', 95, 11, 'Tobali fahölu ndra''o, ba wönugu andrö,(umane): "Böi ya lakhamö wolombase andrö khögu."[4]', '["MozII 17:2,7","MozIV 14:22,23"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 1, 'Mi''anunö khö Yehowa, sinunö si bohou. Mi''anunö khö Yehowa, dozi tanö.[1][2]', '["Faigi göi Nga''ötI 16:23–33","Sin 33:3"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 2, 'Mi''anunö khö Yehowa, misuno döinia andrö; mi''ombakha''ö wangorifi andrö khönia, ero ma''ökhö.', '["Faigi göi Nga''ötI 16:23–33","Sin 33:3"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 3, 'Midunö-dunö ba niha baero duriania, ba ba niha fefu zahöli-höli dödö andrö khönia.', '["Faigi göi Nga''ötI 16:23–33","Sin 33:3"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 4, 'Me no sebua Yehowa, ba me no si nangea nisuno sibai, ni''ata''ufi, yaŵa Lowalangi bö''ö, fefu.', '["Faigi göi Nga''ötI 16:23–33","Sin 33:3"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 5, 'Lowalangi niha baero andrö sa, ba adu; ba Yehowa, ba no samazökhi banua si yaŵa.', '["Faigi göi Nga''ötI 16:23–33","Sin 33:3"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 6, 'Lakhömi ba fa''amoadu fönania; fa''abölö ba lakhömi ba ni''amoni''ö andrö khönia.', '["Faigi göi Nga''ötI 16:23–33","Sin 33:3"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 7, 'Mibe''e khö Yehowa, ya''ami ngawalö soi niha, mibe''e khö Yehowa zumange ba fa''abölö.', '["Sin 72:10","Sin 93:1","Sin 98:7–9; Yes 49:13"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 8, 'Mibe''e khö Yehowa zumange döinia andrö; mi''ohe game''ela ba mi''ae ba golayama andrö khönia.[3]', '["Sin 72:10","Sin 93:1","Sin 98:7–9; Yes 49:13"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 9, 'Mi''angaröfi li Yehowa, mi''ohe wangehao ni''amoni''ö andrö; mi''anizi-nizi fönania, dozi tanö.', '["Sin 72:10","Sin 93:1","Sin 98:7–9; Yes 49:13"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 10, 'Mimane ba niha baero: Razo sa''ae Yehowa! Ba no aro göi golia uli danö, tebai mangiwa. Ifatörö ba zadölö soi niha andrö.[4]', '["Sin 72:10","Sin 93:1","Sin 98:7–9; Yes 49:13"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 11, 'Omuso dödö mbanua si yaŵa, ba ma''iki guli danö, mu''ugu-ugu nasi ba ösinia andrö.[5]', '["Sin 72:10","Sin 93:1","Sin 98:7–9; Yes 49:13"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 12, 'Ikaraini wa''iki benua andrö ba hadia ia ba khönia; ba fefu döla geu sa''ae dania ba gatua, ba omuso sibai dödö.', '["Sin 72:10","Sin 93:1","Sin 98:7–9; Yes 49:13"]', NULL),
  (3476108, 'OT', 'Sinunö', 96, 13, 'Föna Yehowa; so ia sa moroi sa, so ia, ba wanguhuku ösi guli danö. Ihuku dania golia uli danö ba wa''atulö, ba ihuku soi niha ba wa''aduhu andrö khönia.', '["Sin 72:10","Sin 93:1","Sin 98:7–9; Yes 49:13"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 1, 'No razo Yehowa, ya owua-wua dödö nösi guli danö, ya omuso dödö zi so ba hulo soya andrö.[1]', '["Sin 93:1","Sin 89:15","Hab 3:3–6","Sin 19:2"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 2, 'Si no tefasui lawuo ba fa''ogömi-gömi ia; dane-dane dadaomania ba huku sadölö ba fa''atulö.[2]', '["Sin 93:1","Sin 89:15","Hab 3:3–6","Sin 19:2"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 3, 'Mowaö-waö fönania galitö, si manga zi fa''udu khönia, fasui.[3]', '["Sin 93:1","Sin 89:15","Hab 3:3–6","Sin 19:2"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 4, 'Isului guli danö gari mbanua andrö khönia; i''ila uli danö, ba muhisi.', '["Sin 93:1","Sin 89:15","Hab 3:3–6","Sin 19:2"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 5, 'Alau hili, hulö zigu-sigu, föna Yehowa andrö, föna Zo''aya tanö, ma''asagörö.', '["Sin 93:1","Sin 89:15","Hab 3:3–6","Sin 19:2"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 6, 'Idunö-dunö wa''atulönia andrö banua si yaŵa, ba dozi soi mangila lakhöminia.[4]', '["Sin 93:1","Sin 89:15","Hab 3:3–6","Sin 19:2"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 7, 'Falukha wa''aila dania dozi samosumange balö geu, sanuno ya''ira ba nadu andrö; mi''angalulu khönia, ya''ami Lowalangi fefu![5]', '["Heb 1:6","Fil 4:4,5","Sin 96:4","Amos 5:14,15","Sin 112:4"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 8, 'Irongo Siona, ba omuso dödö; ba owua-wua dödö nono Ndraono Yuda alawe, börö wanguhukumö andrö, ya''ugö Yehowa![6]', '["Heb 1:6","Fil 4:4,5","Sin 96:4","Amos 5:14,15","Sin 112:4"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 9, 'Ya''ugö sa Wondrege zalaŵa, Yehowa, ba guli danö, ma''asagörö, alaŵa yaŵa Lowalangi bö''ö fefu ndra''ugö.[7]', '["Heb 1:6","Fil 4:4,5","Sin 96:4","Amos 5:14,15","Sin 112:4"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 10, 'Mi''ogorofi zi lö sökhi, ya''ami sangomasi''ö Yehowa! Ya''ia zondrorogö noso zatulö tödö andrö khönia; i''efa''ö ira ba danga zebua horö andrö.[8]', '["Heb 1:6","Fil 4:4,5","Sin 96:4","Amos 5:14,15","Sin 112:4"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 11, 'Tumbu haga khö zatulö tödö, ba fa''omuso dödö ba zadölö era-era.[9]', '["Heb 1:6","Fil 4:4,5","Sin 96:4","Amos 5:14,15","Sin 112:4"]', NULL),
  (3476109, 'OT', 'Sinunö', 97, 12, 'Mi''omusoi''ö dödömi ba khö Yehowa, ya''ami satulö tödö, ba misuno döinia andrö, ni''amoni''ö!', '["Heb 1:6","Fil 4:4,5","Sin 96:4","Amos 5:14,15","Sin 112:4"]', NULL),
  (3476110, 'OT', 'Sinunö', 98, 1, 'Mi''anunö khö Yehowa, sinunö si bohou! Noa sa ilau zahöli-höli dödö, no itolo ia kambölönia, ta''ionia ni''amoni''ö andrö.[1]', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476110, 'OT', 'Sinunö', 98, 2, 'No ifarongogö Yehowa wangorifi andrö khönia; ba zanehe niha baero andrö ifa''ele''ö wa''atulönia andrö.', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL),
  (3476110, 'OT', 'Sinunö', 98, 3, 'No itörö tödönia wa''ebua dödönia andrö, awö wa lö si faröi ia ba ma''uwu Gizeraeli; no la''ila wangorifi andrö khö Lowalangida fondrege danö fefu.[2]', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL),
  (3476110, 'OT', 'Sinunö', 98, 4, 'Mi''owua-wua''ö dödö, ya''ami dozi tanö! Mi''a''iki ba mi''anunö!', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL),
  (3476110, 'OT', 'Sinunö', 98, 5, 'Misuno Yehowa, milau mbiola nitika, sebua, milau mbiola ba mifao li wanunö!', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL),
  (3476110, 'OT', 'Sinunö', 98, 6, 'Milau dorofe side-ide, awö dorofe nidödöni, mi''owua-wua''ö dödömi tanö föna razo andrö, Yehowa![3]', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL),
  (3476110, 'OT', 'Sinunö', 98, 7, 'Ya mu''ugu-ugu nasi, fabaya ösinia, ba uli danö andre, awö zowanua ba detenia.[4]', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL),
  (3476110, 'OT', 'Sinunö', 98, 8, 'Ndramulau datawo boto nidanö andrö ba ya owua-wua dödö hili, fefu.', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL),
  (3476110, 'OT', 'Sinunö', 98, 9, 'Tanö föna Yehowa; so ia sa moroi sa, ba wanguhuku uli danö. I''atulö''ö wanguhuku uli danö ba ifatörö ba niha baero zadölö.', '["Sin 33:3","Yes 52:10","MozIV 23:21","Sin 96:11–13"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 1, 'Razo Yehowa; sanizi-nizi niha baero; yaŵa Kerubi dumadao ia, humisi danö.[1]', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 2, 'Ebua Yehowa, ba Ziona, yaŵa niha bö''ö fefu ia.', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 3, 'Ya lasuno döimö andrö, sebua, sata''u niha; ni''amoni''ö ia.', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 4, 'Awö wa''abölö razo andrö, somasi huku satulö; nifatöröu ba ma''uwu Yakobo andrö, ba sadölö ba satulö.[2]', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 5, 'Mifosumange Yehowa, Lowalangida, mi''angalulu föna mbaku-baku gahe andrö khönia: ni''amoni''ö ia!', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 6, 'Awö gere andrö khönia ndra Moze A''aroni, ba awö zi angaröfi li ya''ia Zamueli andrö; mangandrö ira khö Yehowa, ba ifondrondrongo lira.[3]', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 7, 'Ba lawuo andrö fahuhuo ia khöra; la''o''ö wamaduhu''ö andrö khönia ba amakhoita andrö, nifakhoinia khöra.', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 8, 'He Yehowa, Lowalangima, no öfondrondrongo lira. Lowalangi sebolo tödö ndra''ugö khöra ba solau balö ba zi lö sökhi andrö, nifazökhira.', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476111, 'OT', 'Sinunö', 99, 9, 'Mifosumange Yehowa, Lowalangida andrö, mi''angalulu ba gahe hili andrö khönia, ni''amoni''ö. Ni''amoni''ö sa Yehowa, Lowalangida andrö!', '["Sin 93:1; 80:2","Yes 9:6","Yer 15:1"]', NULL),
  (3476112, 'OT', 'Sinunö', 100, 1, 'Mi''owua-wua''ö dödömi khö Yehowa, ya''ami dozi tanö!', '["Sin 95:7","Sin 106:1"]', NULL),
  (3476112, 'OT', 'Sinunö', 100, 2, 'Mi''aohasi gölömi we''amöi enoni Yehowa; mi''ondrasi ia, mi''a''iki!', '["Sin 95:7","Sin 106:1"]', NULL),
  (3476112, 'OT', 'Sinunö', 100, 3, 'Ya aboto ba dödömi, wa no Lowalangi Yehowa! Ya''ia zamazökhi ya''ita ba no khönia ita, banuania ba biri-biri, nikubaloinia.[1]', '["Sin 95:7","Sin 106:1"]', NULL),
  (3476112, 'OT', 'Sinunö', 100, 4, 'Mitörö mbawa göli andrö khönia, wangandrö saoha gölö; mi''ae ba golayamania, wanuno ya''ia; mi''andrö saoha gölö khönia ba misuno döinia andrö!', '["Sin 95:7","Sin 106:1"]', NULL),
  (3476112, 'OT', 'Sinunö', 100, 5, 'Si sökhi tödö sa Yehowa: fa''ebua dödönia andrö, ba no si lö aetu, ba lö faröi ia, götö-götö wa''ara.[2]', '["Sin 95:7","Sin 106:1"]', NULL),
  (3476113, 'OT', 'Sinunö', 101, 1, 'Da''udunö-dunö wa''ebua dödö andrö ba fa''atulö andrö; ya''ugö, Yehowa, nisunogu!', '["Amaed 20:8,28","Amaed 22:11","Amaed 20:26"]', NULL),
  (3476113, 'OT', 'Sinunö', 101, 2, 'Da''uhaogö-haogö wanörö lala, lala sadölö; ha wa''ara möi''ö khögu? Da''u''adölö''ö dödögu, wolau hadia ia baomo khögu.', '["Amaed 20:8,28","Amaed 22:11","Amaed 20:26"]', NULL),
  (3476113, 'OT', 'Sinunö', 101, 3, 'Lö ube''e ba duduma hörögu zi lö sökhi; u''ogorofi wolau si fahole; böi ya fatöfa khögu.[1]', '["Amaed 20:8,28","Amaed 22:11","Amaed 20:26"]', NULL),
  (3476113, 'OT', 'Sinunö', 101, 4, 'Ya aröu khögu dödö si falimo; lö edönado zi lö sökhi.', '["Amaed 20:8,28","Amaed 22:11","Amaed 20:26"]', NULL),
  (3476113, 'OT', 'Sinunö', 101, 5, 'Sanandraŵaisi awönia ba zi tobini, ba ufakiko; si fayaŵa ba sebua hokha, ba tekhögu.', '["Amaed 20:8,28","Amaed 22:11","Amaed 20:26"]', NULL),
  (3476113, 'OT', 'Sinunö', 101, 6, 'Unehegö zi lö faröi andrö, ba danö, ena''ö khögu soso ira; sanörö lala sadölö, da''ö genonigu.[2]', '["Amaed 20:8,28","Amaed 22:11","Amaed 20:26"]', NULL),
  (3476113, 'OT', 'Sinunö', 101, 7, 'Böi ya so baomo khögu zi falimo; solau faya, ba böi yamonaha fönagu.', '["Amaed 20:8,28","Amaed 22:11","Amaed 20:26"]', NULL),
  (3476113, 'OT', 'Sinunö', 101, 8, 'U''erogö mahemolu wamakiko samazökhi horö, ba danö, ba wangohori ba mbanua Yehowa andrö solau si lö sökhi.[3]', '["Amaed 20:8,28","Amaed 22:11","Amaed 20:26"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 1, 'Fangandrö zi numana, na abu dödönia, na ifarongogö khö Yehowa wangarö-ngarönia.', '[]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 2, 'He Yehowa, fondrondrongo wangandrögu, akha irugi dögi dalingau we''aogu andre!', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 3, 'Böi bini''ö khögu mbawau, na baŵa wa''ata''ugu; be''e mbörö dalingau khögu, na u''angaröfi li ndra''ugö; ta''i-ta''i fondrondrongo khögu!', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 4, 'Taya-taya sa''ae mbaŵagu, hulö zimbo, ba timba ni''a galitö dölagu.', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 5, 'Tödögu bakha, ba no aleu, no oköli, hulö ndru''u ba danö; olifudo sa''ae wemanga gögu.', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 6, 'Falemba ba nagolegu dölagu, balazi wa''abölö-bölö wangarö-ngarögu andrö.[1]', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 7, 'No si fagölö-gölö ba dumbao ba mbewe nasi ndra''odo, hulö lamuhu ba gadudula mbanua.', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 8, 'Lö salau hörögu, hulö wofo, si ha sambu-sambua ba gero zagö.', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 9, 'Ma''öma''ökhö latandraŵaisi ndra''o si fa''udee khögu, ba sabao tödö khögu, ba labe''e hölu ndra''odo.', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 10, 'Ufemanga wakhe sa''ae nawu, ba ufaruka ba nibadugu daŵa hörö.[2]', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 11, 'Börö wönumö andrö ba bakhu-bakhu dödöu; noa sa öfazaŵa ndra''o, ba no ötibo''ö tou ndra''odo.', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 12, 'Hulö lumö, si no adöni, mbaŵagu andrö, ba saleu ndra''o, hulö ndru''u.[3]', '["Yob 19:20","Sin 80:6","Sin 90,5; Yob 14:2"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 13, 'Ba ya''ugö, Yehowa, ba si no dumadao, si lö mamalö-malö, ba lö tebulö duriamö, götö-götö wa''ara.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 14, 'Maoso dania ndra''ugö ba öhakhösi tödö Ziona andrö; baŵa sa''ae, fa ö''ebua''ö dödöu khönia; noa sa irugi inötö.[4]', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 15, 'Omasi sa genonimö garania andrö ba ahakhö dödöra gadudulania.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 16, 'Ba la''ata''ufi döi Yehowa andrö niha baero; ba dozi salaŵa ba guli danö, ba la''ata''ufi lakhömiu.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 17, 'Me no ifuli itaru''ö Ziona Yehowa, me no i''oroma''ö ia ba lakhöminia andrö.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 18, 'Me no ifondrondrongo wangandrö zi numana ba me lö ni''ositengagönia fangandröra andrö.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 19, 'Nitanö ba zura da''ö, nifa''ema ba zi sagötö niha dania; ba niha niwöwöi dania, ba lasuno Yehowa.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 20, 'Me no ifaigi moroi ba zalaŵa yaŵa andrö khönia, ni''amoni''ö; me no inehegö guli danö Yehowa moroi ba zorugo.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 21, 'Ba wamondrondrongo fangarö-ngarö nikuru andrö, ba wangefa''ö si mate mena''ö.[5]', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 22, 'Ena''ö ladunö-dunö döi Yehowa ba Ziona ba turiania ba Yeruzalema.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 23, 'Na la''orudugö ira soi niha fefu ba öri andrö, ba wamosumange Yehowa.[6]', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 24, 'No ihöndrögö wa''abölögu, ba lala, no i''ambösi wa''anau nosogu.', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 25, 'Ba umane: "He Lowalangigu, böi etu''ö nosogu, ha talu niha! Fa''anau nosou andrö, ba götö-götö wa''ara.[7]', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 26, 'Ba götö föna sa''ae ölata danö, ba nifazökhi dangau mbanua si yaŵa.[8]', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 27, 'Ya''ia andrö, ba si taya dania, ba ya''ugö, ba si lö tebulö; atua dania ia fefu, hulö mbaru; öfamalalini baru, ba tobali.[9]', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 28, 'Ba ya''ugö andrö, ba ya''uya''ugö manö, ba döfiu andrö, ba lö ahori.[10]', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476114, 'OT', 'Sinunö', 102, 29, 'Monahia ndraono genoniu andrö, ba ma''uwura, ba si lö tebulö fönau."[11]', '["Sin 14:7","Sin 79:11","Sin 87:4","Sin 55:24","Heb 1:10–12; Sin 90:2","FetII 3:10","Ayati 13","YohI 2:17"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 1, 'Suno Yehowa, ya''ugö tödögu, ba hadia ia zi so bakha ba dödögu, fefu, ba yamusuno döinia ni''amoni''ö andrö!', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 2, 'Suno Yehowa, ya''ugö tödögu, ba böi olifugö''ö zi sökhi andrö, fefu, nibe''enia khöu.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 3, 'Same''e aefa khöu lalöu fefu, ba samadöhö fökhöu fefu.[1]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 4, 'Sangefa''ö nosou ba wa''atekiko, samotakula ya''ugö fa''ebua dödö ba fa''ahakhö dödö.[2]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 5, 'Sangabusoi''ö si sökhi ya''ugö ba wa''atuamö; tebohouni wa''ono matua khöu, hulö ba moyo.[3]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 6, 'Sateolö ilau Yehowa, ba i''ohe ba lala huhuo nifakao, fefu.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 7, 'No ifarongogö khö Moze lala andrö khönia, ba no i''oroma''ö ba Ndraono Gizeraeli wolaunia andrö, sebua.[4]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 8, 'Sahakhö tödö Yehowa ba sebua tödö; ebolo sibai dödönia ba no oböwö sibai ia.[5]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 9, 'Tenga si lö mamalö-malö watahisania, ba fönunia, ba tenga si lö aetu.[6]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 10, 'Lö nibe''enia dali horöda ba lö nisulöninia khöda olalöŵada.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 11, 'Si mane fa''alaŵa mbanua si yaŵa sa, yaŵa danö, si manö wa''ebua dödönia ba zangata''ufi ya''ia.[7]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 12, 'Si mane otaluara gatumbukha gaekhula, si manö wa''ebua gotaluada lalöda ibe''e.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 13, 'Si mane fa''ahakhö dödö nama nononia, si manö wa''ahakhö dödö Yehowa zangata''ufi ya''ia.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 14, 'I''ila sa gamuatada, ya''ita nifazökhinia; itörö tödönia, wa no gawu-gawu ita.[8]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 15, 'Noso niha andrö, ba no hulö ndru''u ba danö; mobowo ia, hulö mbowo ndru''u ba mbenua.[9]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 16, 'Na itörö angi, ba lö ya''ia sa''ae, ba lö''ö sa''ae i''ila ia nahania andrö.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 17, 'Ba fa''ebua dödö Yehowa andrö, ba götö-götö wa''ara, ba zangata''ufi ya''ia; ba fa''atulö dödönia andrö, ba irugi ma''uwu.[10]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 18, 'Ba zi lö mamöhöi fawu''usa li andrö khönia ba ba zi lö olifu oroisania, ba wolo''ö ya''ia.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 19, 'Yehowa andrö, ba no ifazökhi dadaomania ba zorugo, ba fa''asalaŵania andrö, ba irugi fefu hadia ia.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 20, 'Misuno Yehowa, ya''ami mala''ikania, ya''ami sabölö, samalua niŵa''önia, wolo''ö taroma linia andrö![11]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 21, 'Misuno Yehowa, ya''ami, sato khönia, enoninia, samalua somasi ia.', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476115, 'OT', 'Sinunö', 103, 22, 'Misuno Yehowa, ya''ami nifazökhinia fefu, fefu gofu heza, ba gamatöröŵania. Suno Yehowa, ya''ugö tödögu![12]', '["Sin 32:1","Sin 5:13","Yes 40:31","MozII 33:13","MozII 34:6; Sin 86:15","Yes 57:1","Sin 36:6","Yob 10:9; MozI 2:7; 3:19","Sin 90:5,6; FetI 1:24,25","Ngenu 3:22; Luk 1:50","Sin 29:1; Dan 7:10","Sin 148"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 1, 'Suno Yehowa, ya''ugö tödögu! He Yehowa, Lowalangigu, salaŵa sebua ndra''ugö; fa''asalaŵa ba lakhömi nukhau.[1]', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 2, 'Si obaru haga, samologö banua si yaŵa, hulö dufo sebolo.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 3, 'Same''e hare nomonia idanö, ba same''e kuretania lawuo andrö, sanörö afi nangi.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 4, 'Samali''ö sinengenia angi ba samali''ö enoninia hola-hola galitö.[2]', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 5, 'No ilata danö dayadayania andrö, fa böi mangiwa ia, irugi zi lö aetu.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 6, 'No öbalugö ia idanö, hulö nifobaru, no anönö hili idanö andrö.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 7, 'Ba ahele, me ötenaŵa, ba we''ugu-ugu limö andrö fulöi ia.[3]', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 8, 'Tumbu sa''ae hili ba ahöndrö ndraso, ba naha nihonogöimö khönia.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 9, 'No öbe''e nola khönia, si tebai isawö; lö mangawuli, ba wamalugö tanö.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 10, 'Samangumbu idanö, sanaŵa daso, ba mbawa danö misa itörö.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 11, 'Ö zaliŵa-liŵa ba danö fefu ia; ifadöhö wa''owökhi dödönia kalide ndru''u andrö.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 12, 'Monahia ba mbewenia wofo ba dalu mbanua; lafarongogö lira moroi ba ndraha geu andrö.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 13, 'Samo''idanö hili, moroi ba nahiania andrö si yaŵa; fangabuso danö lua-lua wolaumö andrö.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 14, 'Samatumbu''ö du''u, ö gurifö niha ba sinanö, soguna ba niha, wamalua balazo moroi ba danö.[4]', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 15, 'Ba agu, fa''omuso dödö niha, ba ena''ö takile mbawa ba wanikha, ba ena''ö möi fangabe''e dödö niha roti.[5]', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 16, 'Fahöna nidanö ba döla geu andrö, khö Yehowa, ba döla geresi andrö, nitanönia.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 17, 'Ba zangazuni fofo; tumbao andrö, sonahia ba hogu naru''u.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 18, 'Hili salaŵa andrö, ba no saŵatö nago, ba arö gara, ba saŵatö laosi.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 19, 'Baŵa no ifazökhi, ba wamaigi inötö; luo andrö, ba i''ila wa''aekhunia.[6]', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476116, 'OT', 'Sinunö', 104, 20, 'Na ölau wa''ogömi-gömi, ba bongi; ba ba zi bongi andrö, ba maliŵa-liŵa fefu gutu ndru''u andrö.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 21, 'Ono zingo andrö si ndröndröndröndrö, wangalui ahulua, sangandrö göra khö Lowalangi.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 22, 'Ba tumbu luo, ba mangawuli ira furi ba mörö ba nahiara.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 23, 'Ba möi tou niha ba halöŵönia, mangai nihalönia, irege bongi.', '["Faigi göi MozI 1","Heb 1:7","Yob 38:8–11","Sin 147:8","Sanguhuk 9:13; Sangomb 10:19","Sin 19:7; 74:16"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 24, 'Ha lö oya ngawalö halö-halöŵöu, ya''ugö Yehowa; fa''atua-tuamö wamalua ya''ia fefu, no anönö danö niwöwöimö andrö!', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 25, 'Hiza nasi andrö, no ebua ba no ebolo misa, ba saliŵa-liŵa bakha, lö mutaha mu''erai, side-ide ba sebua.', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 26, 'Lala nowo ia: ba da''ö so gi''a sebua andrö, nifazökhiu, ena''ö famaimai ba da''ö.', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 27, 'Ba oi dozi manötöna khöu, ena''ö öbe''e göra, na inötö.[7]', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 28, 'Ba öbe''e khöra, ba latutuyu; öbokai dangau, ba abuso ira si sökhi.', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 29, 'Ba öbini''ö mbawau, ba tokea ira; öböda nosora, ba aetu, tobali gawu-gawu ira mangawuli.[8]', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 30, 'Öfalua Gehehamö, ba tewöwöi ira, ba öbohouni guli danö.', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 31, 'Lakhömi Yehowa andrö, ba si lö aetu; omuso dödö Yehowa nifazökhinia andrö;', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 32, 'Na inehegö danö, ba humisi; na itufa tangania hili, ba manimbo.[9]', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 33, 'Damanunö ndra''o khö Yehowa, götö wa''anau nosogu; usuno Lowalangigu, götö wa''ara ndra''odo.', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 34, 'Ena''ö na omasi ia nifakhai dödögu; ya''odo, ba no somuso tödö khö Yehowa!', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476116, 'OT', 'Sinunö', 104, 35, 'Ena''ö taya ba guli danö zamazökhi horö, ena''ö lö''ö sa''ae sebua horö. Suno Yehowa, ya''ugö tödögu! Haleluya!', '["Sin 145:15,16","MozI 3:19","Sin 144:5"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 1, 'Misuno Yehowa, mi''angaröfi li döinia andrö! Midunö-dunö ba niha baero wolaunia andrö.[1][2]', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 2, 'Mi''anunö khönia! Misuno ia! Ena''ö itörö limi zahöli-höli dödöda andrö khönia, fefu.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 3, 'Misuno ami ba döinia andrö ni''amoni''ö! Ya omuso dödö zangalui Yehowa!', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 4, 'Mizofu-zofu Yehowa, awö wa''abölönia andrö! Böi mifamalö-malö wangalui bawania!', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 5, 'Mitörö-törö tödömi zahöli-höli dödöda andrö khönia, nilaunia, tandra andrö khönia ba fanguhukunia, taroma linia!', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 6, 'Ya''ami, ma''uwu genoninia Aberahamo, ya''ami ma''uwu Yakobo andrö, nitutuyunia.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 7, 'Ya''ia, Yehowa, ba no Lowalangida; itöröi guli danö fanguhukunia andrö.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 8, 'Lö olifu ia gamabu''ula linia andrö, irugi zi lö aetu, taroma li andrö, nihonogöinia, ba ngahönö nga''ötö.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 9, 'Fawu''usa li andrö, me fawu''u li ia khö Gaberahamo, ba fahölusania andrö khö Giza''aki.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 10, 'Ba no ibe''e amakhoita khö Yakobo, amabu''ula li si lö tebulö khö Gizeraeli andrö,', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 11, 'wanguma''ö: "Khöu ube''e danö Gana''ana andrö, tana khömi, ondröita."[3]', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 12, 'Me lö ato ira na, me ha fasamösa na, ba me si fatewu ira ba danö.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 13, 'Ba latöröi soi niha andrö; ba nöri si sambua so ira ma''ökhö, ba mahemolu, ba ba niha hö''ö.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 14, 'Lö ibe''e nifakao niha bö''ö ira, ba i''otu''ö razo, börö ira.[4]', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 15, '"Böi mibabaya nibayoinigu andrö ba böi mifakao zame''ele''ö andrö khögu."', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 16, 'Ba ikaoni ba danö lofo mbanua, ifatö dendrotendro gö fefu.[5]', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 17, 'Ifowaö-waö khöra zamösa; te''amawa sawuyu Yosefo andrö.[6]', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 18, 'Lalazi gahenia ba galö, tefa''u''u si''öli nosonia.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 19, 'Irege itörö niŵa''önia andrö; taroma li Yehowa wamaduhu''ö ya''ia.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 20, 'Ba ifatenge razo, idudu ia; salaŵa soi niha andrö, i''efa''ö ia.[7]', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 21, 'Ibali''ö satua baomo khönia; ifataro samatörö si so khönia fefu.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 22, 'Ba wamöbö salaŵa andrö khönia, na omasi ia, ba ba wangatua-tua''ö satua andrö khöra.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 23, 'Ba isaŵa danö Miserayi Izeraeli, i''iagö danö ma''uwu Khamo Yakobo, si fatewu.[8]', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 24, 'Ba i''oya''ö ndraono ba mbanuania andrö, ato ira, moroi ba zamakao ya''ira, ibe''e.[9]', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 25, 'Ibali''ö dödö da''ö, ena''ö fatiu ba mbanuania andrö, ena''ö lalau zi lö atulö ba genoninia.', '["Faigi göi Nga''ötI 16:8,22; Sin 48:1–15","Yes 12:14","MozI 12:7","MozI 12:17; 20:3,7","MozI 41:54","MozI 37:28","MozI 41:14","MozI 46:1","MozII 1:7,12"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 26, 'Ifatenge genoninia Moze ba A''aroni andrö, nituyunia.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 27, 'Lafazökhi dandra andrö khönia, ba khöra ba sahöli-höli dödö ba danö ma''uwu Khamo.[10]', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 28, 'Ifatörö wa''ogömi-gömi, ogömi danö ibe''e, ba lö aetu lafadaö linia.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 29, 'Ibali''ö do nidanö khöra, mate gi''a khöra ibe''e.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 30, 'Molihaliha ba danöra dalaho, irege ba mbate''e razora.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 31, 'Muhede ia, ba tesao ndri manu, ba di mböhö, ba danöra, ma''asagörö.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 32, 'Ifatörö khöra deu kara, salahi deu bö''ö, alitö sihola-hola ifatörö ba danöra.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 33, 'Ibözi ŵeŵe nagu khöra, awö mbua ara, ifatö ndraha geu ba danöra.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 34, 'Muhede ia, ba tesao damo ba lamanua, tebai te''erai.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 35, 'Ahori la''a ndru''u ba danöra, ba öra göi mbua danö khöra.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 36, 'Ba ibözi tou fefu nono si a''a, ba danöra, si a''a zabölö andrö khöra fefu.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 37, 'Ba aheta ira ibe''e, fao wirö ba fao gana''a; ba lö salau ba madora andrö.[11]', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 38, 'Omuso dödö Ndrawa Miserayi, me aheta ira; noa sa ihawui ira fa''ata''u, ba khöra andrö.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 39, 'Ibologö lawuo, balu-balu, ba alitö, ba wohagaini si bongi.[12]', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 40, 'Mangandrö ira, ba ifatörö ziate ba i''abusoi''ö ira kue moroi ba mbanua si yaŵa.[13]', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 41, 'Itöla''ö gara, ba mangele nidanö, mo''ungo misa ba danö si mate, timba nidanö sebua.[14]', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 42, 'Itörö sa tödönia daroma linia andrö, ni''amoni''ö, ba enoninia Aberahamo andrö.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 43, 'Ba ifawu''a mbanuania andrö, omuso dödö; owua-wua dödö nitutuyunia andrö.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 44, 'Ba ibe''e khöra danö niha baero andrö; möi tana khöra gödo soi andrö.', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476117, 'OT', 'Sinunö', 105, 45, 'Ena''ö la''o''ö gamakhoitania andrö, ba ena''ö lö lasawö goroisania. Haleluya!', '["MozII 3–12","MozII 12:35","MozII 13:21","MozII 16:13–15; Yoh 6:31","MozII 17:6"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 1, 'Haleluya! Mi''andrö saoha gölö khö Yehowa! Me no si sökhi tödö ia, me si lö aetu wa''ebua dödönia andrö.[1]', '["Sin 107:1; 118:1; 136:1"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 2, 'Ha niha zangila manutunö nilau Yehowa andrö, fa''abölönia, ba ha niha zangila mamarongogö fanuno ya''ia andrö, fefu?', '["Sin 107:1; 118:1; 136:1"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 3, 'Ya ahowu zolo''ö huku andrö, ba si lö mamamalö-malö folau satulö!', '["Sin 107:1; 118:1; 136:1"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 4, 'Törö tödöu ndra''odo, ya''ugö Yehowa, dali wa''omasiu mbanuau andrö; fatörö khögu wangorifi andrö khöu.', '["Sin 107:1; 118:1; 136:1"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 5, 'Ena''ö anehe ndra''o wa''ohahau dödö nitutuyumö andrö; ena''ö omuso dödögu göi ba wa''omuso dödö mbanuau, ba ena''ö usuno ndra''o, awö dana khöu andrö.', '["Sin 107:1; 118:1; 136:1"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 6, 'No mafazökhi horö, si mane tuama andrö; no mo''olalöŵa ndra''aga, no malau zi lö sökhi.[2]', '["Dan 9:5","MozII 14:11,12","MozII 15"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 7, 'Lö saboto ba dödö duama ba danö Miserayi zahöli-höli dödö andrö khöu; lö itörö tödöra wa''afahöna wa''ebua dödöu andrö, ba molaŵa ba mbewe nasi andrö, ba nasi zukhu.[3]', '["Dan 9:5","MozII 14:11,12","MozII 15"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 8, 'Ba itolo ira, börö döinia andrö, ba wama''ele''ö fa''abölönia.', '["Dan 9:5","MozII 14:11,12","MozII 15"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 9, 'Ba ihede-hede''ö nasi zukhu andrö, ba otufo, ifatörö ira ba dalu hou andrö, nifamatörö ba danö si mate.', '["Dan 9:5","MozII 14:11,12","MozII 15"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 10, 'Ba i''efa''ö ira ba danga zi fatiu tödö khöra, ba danga zi fa''udu i''efa''ö ira.', '["Dan 9:5","MozII 14:11,12","MozII 15"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 11, 'Ba tebalugö asi zi fa''udu khöra andrö; samösa lö''ö si tosai.', '["Dan 9:5","MozII 14:11,12","MozII 15"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 12, 'Awena mamati ira ba daroma linia ba lasuno ia.[4]', '["Dan 9:5","MozII 14:11,12","MozII 15"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 13, 'Ba lö ara, ba olifu ira nilaunia andrö, ba lö latöngöni dödönia andrö.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 14, 'Ba tesao wangisö, ba danö si mate andrö, ba latandraigö Lowalangi ba danö si lö niha-niha.[5]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 15, 'Ba ibe''e khöra zomasi ira, ba ifatörö khöra wökhö baosi.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 16, 'Ba afökhö dödöra khö Mose ba golombaseŵa ba khö Ga''aroni, ni''amoni''ö Yehowa andrö.[6]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 17, 'Ba asila danö, itölö Datano andrö, ibalugö zi fao khö Gabiramo andrö.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 18, 'Te''ebua''ö galitö ba zangorudu ya''ira andrö, i''a alitö zanao horö andrö.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 19, 'Lafazökhi nono zawi ba gahe hili Horebi, mangalulu ira ba wamaedo andrö, nifahele.[7]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 20, 'Lafalalini lakhömira, lahalö wamaedo zawi si matua, si manga ndru''u.[8]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 21, 'Olifu ira Lowalangi, sangorifi ya''ira, si no molau sebua andrö ba danö Miserayi.[9]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 22, 'Sahöli-höli dödö ba danö ma''uwu Khamo andrö, ba sata''u niha ba nasi zukhu andrö.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 23, 'Ba iŵa''ö tödönia, itakiko ira, na lö ibelegö ia mena''ö fönara Moze andrö, nituyunia, ba wangalösi fönunia, ena''ö lö ifakiko ira.[10]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 24, 'Ba lö ba dödöra danö si sökhi andrö, ba lö lafati linia.[11]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 25, 'Ba mukökö-kökö ira, baose andrö khöra, ba lö lafondrondrongo li Yehowa.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 26, 'Ba fahölu ia khöra, ibözi tou ira ba danö si mate andrö,', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 27, 'ba ifazawili ma''uwura ba niha baero, ba danö niha bö''ö ifazaewe, iŵa''ö.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 28, 'Ba la''olembai Mba''ali-Weoro andrö, la''a zumange zi lö noso [sumange nadu].[12]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 29, 'Ba la''andrö wönunia folaura andrö, ba itörö ira famakao.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 30, 'Ba maoso Wineha andrö, ba wangatulö, ba döhö wamakao andrö.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 31, 'Ba tebe''e fa''atulö dödönia da''ö, götö-götö wa''ara, irugi zi lö aetu.[13]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 32, 'Ba labaosi dödö Lowalangi, ba nidanö wasosota andrö, ba itörö Mose si lö sökhi, börö ira.[14]', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 33, 'Lafadaö sa''ae dödönia, ba iŵa''ö bewenia zi lö mutulo tödö.', '["MozIV 11:4–6","MozIV 16","MozII 32","Rom 1:23","MozV 32:18","Hez 13:5","MozIV 14:2–4","MozIV 25:3","MozI 15:6; MozIV 25:12","MozIV 20:2–13"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 34, 'Lö lahori soi niha andrö, niŵa''ö Yehowa khöra, nihori.[15]', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 35, 'Lafaruka ira ba niha baero andrö ba latöngöni wolaura.', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 36, 'Lafosumange nadura, ba tobali tandraŵa khöra da''ö.', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 37, 'Labe''e sumange mbekhu nonora matua, awö nonora alawe.[16]', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 38, 'Aduwa ndro zi lö horö labe''e, do nonora matua ba do nonora alawe, nibe''era sumange nadu Ndrawa Gana''ana; tobali teta''unöi danö do.', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 39, 'Togule khöra zi lö sökhi ba wolaura andrö; sohorö ira folaura andrö.', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476118, 'OT', 'Sinunö', 106, 40, 'Ba tesao wönu Yehowa ba mbanuania andrö, ba i''ogorofi dana khönia.', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 41, 'Ibe''e ira ba danga niha baero andrö; ba samatörö ya''ira zi fatiu tödö khöra.[17]', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 42, 'Lafakao ira si fa''udu khöra, tehöndrögö ira barö mbawara.', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 43, 'Lö aetu i''orifi ira, ba no sabe''e tandro ira, ba nifakhai dödöra andrö, ba ahöndrö ira ba lalöra andrö.', '["MozV 7:1,2; 12:2,3; Sanguhuk 1:28","MozIII 18:21","Sanguhuk 2:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 44, 'Ba inehegö wamakaora andrö, me irongo wangarö-ngaröra.', '["Ayati 47,48: Nga''ötI 16:35–36","MozV 30:3","Sin 41:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 45, 'Ba itörö tödönia khöra wawu''usa li andrö khönia ba aröuröu ba dödönia, balazi wa''ebua dödönia andrö.', '["Ayati 47,48: Nga''ötI 16:35–36","MozV 30:3","Sin 41:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 46, 'Ibe''e falukha ira wa''ahakhö dödö zanaha ya''ira, fefu.', '["Ayati 47,48: Nga''ötI 16:35–36","MozV 30:3","Sin 41:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 47, 'Orifi ndra''aga, ya''ugö Yehowa, Lowalangima, fuli ozaragö ndra''aga ba mbanua niha baero andrö, ena''ö ma''andrö saoha gölö, ba döimö andrö ni''amoni''ö, ena''ö masuno ndra''aga ba wanuno ya''ugö andrö![18][19]', '["Ayati 47,48: Nga''ötI 16:35–36","MozV 30:3","Sin 41:14"]', NULL),
  (3476118, 'OT', 'Sinunö', 106, 48, 'Nisuno Yehowa, Lowalangi Ndraono Gizeraeli andrö, götö-götö wa''ara, ba ya lamane niha fefu: Ya duhu! Haleluya![20]', '["Ayati 47,48: Nga''ötI 16:35–36","MozV 30:3","Sin 41:14"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 1, '"Mi''andrö saoha gölö khö Yehowa, me no si sökhi tödö ia ba me si lö aetu wa''ebua dödönia andrö!"[1]', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 2, 'Ya lamanö ni''orifi Yehowa andrö, ni''efa''önia ba danga zamakao ya''ira.', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 3, 'Ni''ozaragönia ba danö zotanö misa, moroi ba gatumbukha ba moroi ba gaekhula, moroi yöu ba moroi ba mbewe nasi.', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 4, 'No elungu-lungu ira ba danö si mate, ba danö si lö niha-niha, ba zi lö lala; banua sahono ira mena''ö, ba lö lasöndra.', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 5, 'Solofo ira ba sowökhi tödö ba sata''u bakha dödöra.', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 6, 'Ba la''angaröfi li Yehowa, ba wa''abu dödöra andrö, ba i''efa''ö ira ba wa''atosarara andrö.[2]', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 7, 'I''ohe ira ba zadölö lala, ba wogamö banua, sonahia ya''ira.', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 8, 'Ndramu''andrö saoha gölö khö Yehowa wa''asökhi dödönia andrö ba sahöli-höli dödö andrö, nilaunia ba nono niha![3]', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 9, 'Me no i''okafui dödö zowökhi tödö ba me no ihöna zi sökhi ba zolofo andrö.[4]', '["Sin 106:1","Ayati 13,19,28","Ayati 15,21,31","Luk 1:53"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 10, 'Sidadao ba zögömi-gömi ba ba lumö wa''amate, nikalo famakao ba si''öli.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 11, 'Me no lafadaö niŵa''ö Lowalangi, me no lö ba dödöra dödö Wondrege zalaŵa andrö.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 12, 'Ba ihöndrögö dödöra famakao andrö, tegaölö tou ira ba lö sangorifi.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 13, 'Ba la''angaröfi li Yehowa, ba wa''abu dödöra andrö, ba i''efa''ö ira ba wa''atosasara andrö.[5]', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 14, 'Ba iheta ira ba zogömi-gömi andrö ba ba lumö wa''amate no mege, i''etu''ö mböbö andrö khöra.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 15, 'Ndramu''andrö saoha gölö khö Yehowa wa''asökhi dödönia andrö ba sahöli-höli dödö andrö, nilaunia ba nono niha![6]', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 16, 'Me no iboto lagö mbawandruhö töla andrö, ba me no i''eŵa lazi si''öli.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 17, 'Göna famakao zambö tödö, ba lalöra andrö ba ba zi lö atulö andrö khöra.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 18, 'Ogoro dödöra fefu ngawalö gö, ba larugi mbawa göli ba wa''amate.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 19, 'Ba la''angaröfi li Yehowa, ba wa''abu dödöra andrö, ba i''efa''ö ira ba wa''atosasara andrö.[7]', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 20, 'Ifa''ohe''ö linia, ifadöhö wökhöra; i''efa''ö ira ba gohokoho andrö khöra.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 21, 'Ndramu''andrö saoha gölö khö Yehowa wa''asökhi dödönia andrö ba sahöli-höli dödö andrö, nilaunia ba nono niha![8]', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 22, 'Ndramube''e zumange fangandrö saoha gölö, ndramudunö-dunö wolaunia, ya fao wa''owua-wua dödö.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 23, 'Soloyo andrö ba nasi, si möi ba nasi sebua maniaga,', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 24, 'ba la''ila nilau Yehowa andrö ba sahöli-höli dödö, ba namö.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 25, 'Muhede ia, tesao nangi sabe''e ibe''e, famaoso ndrulu, sebua sibai.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 26, 'Lasaŵa miyaŵa mbanua ba numalö mitou ba gohokoho, ariri dödöra wa''afökhö andrö.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 27, 'Manawuyu ira ba humeu, hulö zi mabu, ba tobali faya wa''onekhera fefu.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 28, 'Ba la''angaröfi li Yehowa, ba wa''abu dödöra andrö, ba i''efa''ö ira ba wa''atosasara andrö.[9]', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 29, 'Ibali''ö oho mbade andrö, ba tebato ndrulu.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 30, 'Ba omuso dödöra, me ahono; ba i''ohe ira ba labua, somasi ira.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 31, 'Ndramu''andrö saoha gölökhö Yehowa wa''asökhi dödönia andrö ba sahöli-höli dödö andrö, nilaunia ba nono niha![10]', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 32, 'Ndramudou''ö duriania, ba zowulo zato, ba ndramusuno ia ba walukhata zatua.', '["Ayati 6","Ayati 8"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 33, 'Ibali''ö tanö si mate nungo nidanö ba ibali''ö tanö soköliköli gumbu.', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 34, 'Tanö satabö sinanö ibali''ö dekha mo''asio, börö walösökhi zowanua ba da''ö.', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 35, 'Ba ibali''ö baŵa nidanö danö si mate; ba tanö si no oköliköli, ba ibali''ö umbu nidanö.', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 36, 'Ifataro ba da''ö zolofo, ba lataru''ö mbanua, nahiara.', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 37, 'Mangahalö ira ba lafazökhi kabu nagu, ba ero röfi mowua.', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 38, 'Ba ifahowu''ö ira, tobali ato sibai ira ba ibe''e khöra gurifö, tenga ha ma''ifu.', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 39, 'Ba tobali alö wa''atora, ahöndrö ira, ilangö ira fangabu dödö ba fa''alangu dödö.', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 40, '"Ihawui fa lö ba dödö zalaŵa, ba elungu-lungu ira ba danö si lö niha-niha ba si lö lala, ibe''e."', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 41, 'Iheta ba wamakao zi numana, mongawawa nga''ötönia ibe''e.', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 42, 'Anehe zadölö tödö, ba omuso dödöra, ba lö''ö sa''ae hede-hede zi lö atulö."[11]', '["Yob 22:19,20"]', NULL),
  (3476119, 'OT', 'Sinunö', 107, 43, 'Ha niha zatua-tua, ba yamutöngöni zi manö; ba ndramube''e ba dödö wa''ebua dödö Yehowa andrö.', '["Yob 22:19,20"]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 1, 'Umanö. Sinunö khö Dawido.[1]', '["Ayati 1–7: Sin 57:5–12"]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 2, 'Abe''e dödögu Lowalangi, manunö ndra''o ba ulau mbiola; tödögu andre göi.', '["Sin 16:9","Ayati 8–14: Sin 60:7–14"]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 3, 'Faoso biola nitika sebua ba biola nitika side-ide! Da''ususugi wa''amoluo![2]', '["Sin 16:9","Ayati 8–14: Sin 60:7–14"]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 4, 'Usuno ndra''ugö Yehowa, ba niha misa; ulau manunö khöu ba niha baero!', '["Sin 16:9","Ayati 8–14: Sin 60:7–14"]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 5, 'Noa sa abölö wa''ebua dödöu andrö, italu''i mbanua si yaŵa, ba irugi lawuo wa''aduhumö andrö.', '["Sin 16:9","Ayati 8–14: Sin 60:7–14"]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 6, 'Ae yaŵa, Lowalangi, yaŵa mbanua si yaŵa; ya tehawu guli danö ma''asagörö lakhömimö andrö!', '["Sin 16:9","Ayati 8–14: Sin 60:7–14"]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 7, 'Ena''ö te''orifi ni''omasi''ömö andrö, ba tolo kambölöu ba fondrondrongo khögu! [3]', '["Sin 16:9","Ayati 8–14: Sin 60:7–14"]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 8, 'No muhede Lowalangi ba wa''ohau-haunia andrö: Sowua-wua tödö ndra''odo; ufosasi Zikhema ba usu''a ndraso Zukota.', '[]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 9, 'Khögu Gileadi ba khögu Ndraono Manase, nöugu ba högögu Ndraono Geferayi, ba si''o zalaŵa khögu Ndraono Yuda.', '[]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 10, 'Naha wanasa khögu Ndraono Moabi, ba Ndraono Gedomo ufazaumba mbadagahegu, ba sowua-wua tödö ndra''o ba danö Ndrawa Wilisiti andrö.', '[]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 11, 'Ha niha zolohe ya''odo ba mbanua saro? Ha niha zamasao ya''o irugi ba Ndraono Gedomo?', '[]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 12, 'Hadia, tenga ya''ugö zanibo''ö ya''aga, Lowalangi, ba si lö möi awö zanuwö khöma, ya''ugö Lowalangi?', '[]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 13, 'Tologa ba zanasagö ya''aga andrö; faya sa''ae wangorifi ba niha!', '[]', NULL),
  (3476120, 'OT', 'Sinunö', 108, 14, 'Na awö Lowalangi, ba malau, nifolau zabölö; ya''ia zi hundragö tou zanasagö ya''aga.', '[]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 1, 'He Lowalangi, nisunogu! Böi zi lö muhede ndra''ugö!', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 2, 'Noa sa teboka mbawa zanao horö, awö mbawa zi falimo, udugu; no lalau khögu lela sofaya.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 3, 'No lafasui ndra''o fehede fatiusa, ba lasuko ndra''odo, lö börö.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 4, 'Fa''udu ira khögu, sulö wa''omasigu ya''ira, ba ya''o, ba lö ubulö''ö wangandrö.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 5, 'Lasulöni si lö sökhi khögu zi sökhi andrö, ba fa''omasigu andrö, ba lasulöni fatiusa.[1]', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 6, 'Be''e barö mbawa zebua horö ia ba ya so ba gambölönia zangadugö ya''ia.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 7, 'Na tehuku ia, ba ya oroma, wa si so horö ia, ba ya tobali sala wangandrönia.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 8, 'Ya lö anau nosonia, ba ya möi halöŵö niha bö''ö halöŵönia andrö.[2]', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 9, 'Ya tobali si lö ama nononia ba ya tobali lakha mbanua ngambatönia.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 10, 'Ndramutöröi danö misa ononia, mangandröngandrö gö, ndramangalui aurifara ba zi no aröu aefa ba gadudula mbanuara.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 11, 'Yamufa''u''u fefu zi so khönia sanugi ba ndramurabu gölönia niha bö''ö.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 12, 'Ya lö''ö sa''ae sebua tödö khönia, ba sahakhö tödö ononia, na si lö ama ba si lö ina.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 13, 'Ena''ö te''etu''ö nga''ötönia, ena''ö taya döira ba zi sagötö dania sa''ae.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 14, 'Ya itörö tödö Yehowa golalöŵa ndra amania ba olalöŵa ndra tua; ba ya lö aefa horö ninania andrö.[3]', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 15, 'Ya böi tebulö ba duduma hörö Yehowa; ba ena''ö ibe''e taya döira ba guli danö.[4]', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 16, 'Me no lö itörö tödönia wangebua tödönia ba niha bö''ö, ba me no igohi niha sebua famakao ba si numana ba si no aragu-ragu tödö, ba wamunu ya''ia.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 17, 'Ba no omasi ia wangelifi: ba yatumörö ia; ba lö ba dödönia howu-howu: ba ya aröu khönia.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 18, 'Ba i''obaru wangelifi: ba yamusösö nösinia, hulö nidanö, ba tölania, hulö wanikha![5]', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 19, 'Ya hulö mbaru khönia, balu-balunia, ba ya hulö mböbö talu, si lö aefa ba löwi-löwinia.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 20, 'Ena''ö na luo zi fa''udu khögu da''ö, khö Yehowa, ba luo zamatou ya''odo.', '["Sin 35:12","HalZin 1:20","MozII 20:5","Amaed 10:7","MozIV 5:22"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 21, 'Ba ya''ugö Yehowa, So''aya, iagö salahigu, börö döimö andrö; fondrara dödö wa''asökhi dödöu andrö, ba orifi ndra''odo!', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 22, 'Sebua famakao sa ndra''o ba si numana, ba no mesokho bakha dödögu.', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 23, 'Ariri ndra''o, hulö lumö, na adöni ia; tetaboi ndra''o, hulö lareŵe.', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 24, 'No ombuyu-mbuyu mbalöduhigu, ba wa lö si manga, ba no alö nösigu.', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 25, 'Ba no tobali aya ndra''o khöra; na la''ila ndra''odo, ba lafalikhö ira.[6]', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 26, 'Tolodo Yehowa, Lowalangigu! Orifi ndra''o ba wa''ahakhö dödöu andrö.', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 27, 'Hana na aboto ba dödöra, wa no tangau da''ö, wa ya''ugö Yehowa zolau da''ö.', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 28, 'Akha mangelifi ira, ba ya''ugö, ba fahowu''ö [ndra''o]; na maoso ira, ba be''e aila ira, ba akha omuso dödö genoniu andre.[7]', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 29, 'Nifobaru fa''aila zi fa''udu khögu andrö; akha la''obaru wa''ailara andrö, baru zebua.[8]', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 30, 'U''abölögö wanuno Yehowa bewegu andre; bakha ba hunö zato usuno ia.', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476121, 'OT', 'Sinunö', 109, 31, 'Me no i''iagö gambölö zi numana, ba wangefa''ö ya''ia ba danga zanguhuku ya''ia.', '["Sin 22:8","Mat 5:11","Sin 35:26"]', NULL),
  (3476122, 'OT', 'Sinunö', 110, 1, 'No iŵa''ö Yehowa khö Zo''aya ya''o andrö: "Dadao ba gambölögu, irege ube''e dane-dane gaheu zi fa''udee khöu andrö."[2]', '["KorI 15:25; Heb 10:12,13","Sin 2:6","Sin 29:2","MozI 14:18–20; Heb 5:10; 6:20; 7:17,21","Sin 2:2,5,9","Fil 2:8,9"]', NULL),
  (3476122, 'OT', 'Sinunö', 110, 2, 'Moroi ba Ziona i''oro''ö Yehowa zi''o wa''abölöu andrö; "ya salaŵa ndra''ugö ba zi fa''udu khöu andrö."[3]', '["KorI 15:25; Heb 10:12,13","Sin 2:6","Sin 29:2","MozI 14:18–20; Heb 5:10; 6:20; 7:17,21","Sin 2:2,5,9","Fil 2:8,9"]', NULL),
  (3476122, 'OT', 'Sinunö', 110, 3, 'La''o''ö banuau, moroi si''aikö ba dödö, nana baŵa wa''abölöu; ba hili ni''amoni''ö. Moroi ba gaheta wa''amoluo tumbu khöu nono matua andrö, timba namo.[4]', '["KorI 15:25; Heb 10:12,13","Sin 2:6","Sin 29:2","MozI 14:18–20; Heb 5:10; 6:20; 7:17,21","Sin 2:2,5,9","Fil 2:8,9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476122, 'OT', 'Sinunö', 110, 4, 'No fahölu Yehowa ba lö ifuli mangesa dödönia: "Ere ndra''ugö, irugi zi lö aetu, dali gamuata Melekhisede andrö."[5]', '["KorI 15:25; Heb 10:12,13","Sin 2:6","Sin 29:2","MozI 14:18–20; Heb 5:10; 6:20; 7:17,21","Sin 2:2,5,9","Fil 2:8,9"]', NULL),
  (3476122, 'OT', 'Sinunö', 110, 5, 'Irasa razo So''aya, si so ba gambölöu, na baŵa wönunia andrö.[6]', '["KorI 15:25; Heb 10:12,13","Sin 2:6","Sin 29:2","MozI 14:18–20; Heb 5:10; 6:20; 7:17,21","Sin 2:2,5,9","Fil 2:8,9"]', NULL),
  (3476122, 'OT', 'Sinunö', 110, 6, 'Ihuku dania niha baero, fahöna mboto zi mate ibe''e; iboto högö ba zebolo tanö.', '["KorI 15:25; Heb 10:12,13","Sin 2:6","Sin 29:2","MozI 14:18–20; Heb 5:10; 6:20; 7:17,21","Sin 2:2,5,9","Fil 2:8,9"]', NULL),
  (3476122, 'OT', 'Sinunö', 110, 7, 'Ibadu mbombo ba zinga lala; andrö ifaöga mbawania.[7]', '["KorI 15:25; Heb 10:12,13","Sin 2:6","Sin 29:2","MozI 14:18–20; Heb 5:10; 6:20; 7:17,21","Sin 2:2,5,9","Fil 2:8,9"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 1, 'Haleluya! Da''usuno Yehowa, moroi si''aikö ba dödögu ba zowulo zadölö tödö andrö ba ba zi falukha mbanua.', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 2, 'Sebua nilau Yehowa; la''alu-alui tödöra dozi somasi ya''ia.[1]', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 3, 'Fa''ebua ba lakhömi wolaunia andrö, ba fa''atulönia andrö, ba irugi zi lö aetu.', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 4, 'No ihonogöi, fa böi olifu niha zahöli-höli dödö andrö khönia; sebua tödö Yehowa ba sahakhö tödö.', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 5, 'No ibe''e gö ba zangata''ufi ya''ia; lö mamalö-malö wa itörö tödönia wawu''usa li andrö khönia.[2]', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 6, 'No ifa''ele''ö ba mbanuania wa''abölö wolaunia, wame''e tana khöra tana ba niha baero andrö.', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 7, 'Si duhu ba satulö wolau dangania andrö; si lö mangiwa goroisania andrö, fefu.', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 8, 'Saro, si lö mamalö-malö, irugi zi lö aetu, dali zi duhu ba sadölö.', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 9, 'No ifa''ohe''ö wangorifi ba mbanuania, no i''aro''ö gamabu''ula linia, si lö tebulö.', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476123, 'OT', 'Sinunö', 111, 10, 'Böröta wa''atua-tua wangata''ufi Yehowa andrö; sangila watahögö dozi sanörö lalania; si lö tebulö duriania andrö.[3]', '["Sin 104:24","Sin 145:15","Amaed 1:7"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 1, 'Haleluya! Ya ahowu niha sangata''ufi Lowalangi, somasi sibai oroisania andrö![1]', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 2, 'Sabölö ba guli danö dania ma''uwunia, ba sebua howu-howu dania nga''ötö zadölö tödö.[2]', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 3, 'So baomo khöra mbalazo ba ana''a; ba fa''atulöra, ba lö tebulö, irugi zi lö aetu.', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 4, 'Ba zadölö todö andrö, ba tumbu haga ba dalu zogömi-gömi; sebua tödö ba sahakhö tödö ba satulö.[3]', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 5, 'Ya ahowu niha sahakhö tödö ba same''e nifalali! Lö te''ala ia ba huhuo nifatunö.[4]', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 6, 'Lö''ö sa mangiwa ia, irugi zi lö aetu; götö-götö wa''ara lö olifu niha zatulö andrö.', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 7, 'Lö tokea ia, na irongo duria si lö sökhi; abe''e dödönia, manötöna khö Yehowa.', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 8, 'Aro dödönia; lö ata''u ia, irege omuso dödönia, na i''ila zi göna si fa''udu khönia.[5]', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 9, 'Mamazaewe ia, mame''e ame''ela ba zi numana; si lö mamalö-malö wa''atulönia; alaŵa dandrunia, moturia.[6]', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476124, 'OT', 'Sinunö', 112, 10, 'I''ila sebua horö, ba lö sökhi-sökhi dödönia: ifatangi mbohania ba ariri; ba waya aekhu wangisö zebua horö.[7]', '["Sin 1:1","Amaed 20:7","Sin 37:6","Sin 41:2","Sin 91:8","KorII 9:9","Sin 35:16"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 1, 'Haleluya! Mi''anunö, ya''ami enoni Yehowa andrö! Misuno döi Zo''aya!', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 2, 'Nisuno döi Yehowa andrö, i''otarai da''e, ba irugi zi lö aetu!', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 3, 'I''otarai gatumbukha luo numalö ba gaekhulania, ba nisuno döi Yehowa andrö!', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 4, 'Yehowa andrö, ba no salaŵa niha bö''ö fefu; ba italu''i mbanua si yaŵa lakhöminia andrö.', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 5, 'Ha niha zi fagölö-gölö khö Lowalangida Yehowa andrö? sidadao ba zalaŵa yaŵa andrö.[1]', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 6, 'Ba sangide-ide''ö ya''ia, ba wamaigi banua si yaŵa ba tanö tou.[2]', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 7, 'Samazaŵa si lö töi, moroi ba danö, ba samaoso si numana, moroi ba dambu.[3]', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 8, 'Ena''ö ifataro ba ngai zalaŵa, ba ngai zalaŵa mbanuania andrö.', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476125, 'OT', 'Sinunö', 113, 9, 'Sangahonogö si lö ono baomo, si mane ina nono matua somuso tödö. Haleluya![4]', '["MozII 15:11; Yes 57:15","Luk 1:48","MozI 41:40; SamI 2:8","MozI 21:2; SamI 1:20; 2:21; Luk 1:57,58"]', NULL),
  (3476126, 'OT', 'Sinunö', 114, 1, 'Me aheta Ndraono Gizeraeli ba danö Miserayi, me aheta ma''uwu Yakobo ba niha andrö si fabö''ö li,[1]', '["MozII 12:41","MozII 14:21,22; Yos 3:13,16","Sin 68:9"]', NULL),
  (3476126, 'OT', 'Sinunö', 114, 2, 'ba tobali ni''amoni''ö khönia Ndraono Yuda ba amatöröŵania Ndraono Gizeraeli.', '["MozII 12:41","MozII 14:21,22; Yos 3:13,16","Sin 68:9"]', NULL),
  (3476126, 'OT', 'Sinunö', 114, 3, 'I''ila asi, ba aböda; ibali''ö ia furi Yoridano andrö.[2]', '["MozII 12:41","MozII 14:21,22; Yos 3:13,16","Sin 68:9"]', NULL),
  (3476126, 'OT', 'Sinunö', 114, 4, 'Manoka hili, hulö mbiri-biri si matua, awö hili-hili, hulö nono mbiri-biri.[3]', '["MozII 12:41","MozII 14:21,22; Yos 3:13,16","Sin 68:9"]', NULL),
  (3476126, 'OT', 'Sinunö', 114, 5, 'Hana ndra''ugö, ya''ugö asi, wa aböda''ö, ba ya''ugö Yoridano, wa öbali''ögö furi?', '["MozII 12:41","MozII 14:21,22; Yos 3:13,16","Sin 68:9"]', NULL),
  (3476126, 'OT', 'Sinunö', 114, 6, 'Ba ya''ami hili, wa manoka ami, hulö mbiri-biri si matua, ba ya''ami hili-hili, wa hulö ba nono mbiri-biri wanokami?', '["MozII 12:41","MozII 14:21,22; Yos 3:13,16","Sin 68:9"]', NULL),
  (3476126, 'OT', 'Sinunö', 114, 7, 'Ba wamaigi Zo''aya ya''ugö anizi-nizi, ya''ugö tanö, ba wamaigi Lowalangi Yakobo andrö ya''ugö.', '["MozII 12:41","MozII 14:21,22; Yos 3:13,16","Sin 68:9"]', NULL),
  (3476126, 'OT', 'Sinunö', 114, 8, 'Samali''ö baŵa nidanö soewe, ba samali''ö umbu gowe sabe''e.', '["MozII 12:41","MozII 14:21,22; Yos 3:13,16","Sin 68:9"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 1, 'Böi be''e nifosumange ndra''aga, Yehowa, böi ya''aga, ha töimö andrö nifosumange, börö wa''ebua dödöu ba fa''aduhumö andrö.', '["Sin 42:4","Ayati 4–11: Sin 135:15–20","MozV 4:28; Yes 44:9–20"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 2, 'Hana wa tola laŵa''ö niha baero: "Heza atö so Lowalangira?"[1]', '["Sin 42:4","Ayati 4–11: Sin 135:15–20","MozV 4:28; Yes 44:9–20"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 3, 'Ba ba zorugo so Lowalangima, hadia zomasi ia, fefu, ba iwöwöi. [2]', '["Sin 42:4","Ayati 4–11: Sin 135:15–20","MozV 4:28; Yes 44:9–20"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 4, 'Adura andrö, ba no firö ba ana''a, nifazökhi danga niha.[3]', '["Sin 42:4","Ayati 4–11: Sin 135:15–20","MozV 4:28; Yes 44:9–20"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 5, 'Mobawa, ba lö muhede; mohörö, ba lö la''ila niha.', '["Sin 42:4","Ayati 4–11: Sin 135:15–20","MozV 4:28; Yes 44:9–20"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 6, 'Motögi dalinga, ba lö larongo li niha; mo''ikhu, ba lö la''ago hadia ia.', '["Sin 42:4","Ayati 4–11: Sin 135:15–20","MozV 4:28; Yes 44:9–20"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 7, 'Lö lababaya hadia ia tangara; lö la''ofanö''ö gahera; ba lö hede-hedera ba dölö-tölöra.', '["Sin 42:4","Ayati 4–11: Sin 135:15–20","MozV 4:28; Yes 44:9–20"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 8, 'Ba no fagölö-gölö khöra zamazökhi ya''ira, awö dozi sanötöna khöra.', '["Sin 42:4","Ayati 4–11: Sin 135:15–20","MozV 4:28; Yes 44:9–20"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 9, 'Khö Yehowa manötöna ami, ya''ami Iraono Gizeraeli! Ya''ia wangorifira ba balusera.[4]', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 10, 'Ya''ami ma uwu Ga''aroni, khö Yehowa manötöna ami! Ya''ia wangorifira ba balusera.[5]', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 11, 'Ya''ami, sangata''ufi Yehowa, khö Yehowa manötöna ami! Ya''ia wangorifira ba balusera.[6]', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 12, 'No itörö tödö Yehowa ita, ifahowu''ö ita. Ifahowu''ö ma''uwu Gizeraeli, ifahowu''ö ma''uwu Ga''aroni.', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 13, 'Ifahowu''ö zangata''ufi Yehowa andrö, he iraono ba he satua.', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 14, 'Yamunönö ami Yehowa, ya''ami ba iraonomi.', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 15, 'Nifahowu''ö Yehowa ami, nifahuwu''ö Yehowa andrö, samazökhi banua, awö danö.', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 16, 'Banua si yaŵa andrö, ba no banua Yehowa; ba tanö andre, ba no ibe''e ba nono niha.', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 17, 'Si no mate, ba lö lasuno Yehowa, ba si manö göi dozi silalö mitou ba zahono ira.[7]', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476127, 'OT', 'Sinunö', 115, 18, 'Ba ya''ita, ba no sanuno Yehowa, i''otarai da''e ba irugi zi lö aetu. Haleluya!', '["Sin 118:2","Sin 118:3","Sin 118:4","Sin 6:6; Yes 38:18"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 1, 'Omasido Yehowa, me no ifondrondrongo ligu, fangandrögu.', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 2, 'Me no ibe''e mbörö dalingania khögu; ba u''angaröfi li ia, sagötö ya''o.', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 3, 'No tefa''u''u ndra''o fesu wa''amate, ba no göna ndra''o fa''ata''ugu mbanua tou; falukha ndra''o wa''atosasa ba fangabu dödö.[1]', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 4, 'Ba u''angaröfi li döi Yehowa andrö, umane: He Yehowa! orifi nosogu!', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 5, 'Sebua tödö Yehowa ba satulö, ba sahakhö tödö Lowalangida.', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 6, 'Samaigi-maigi sadölö tödö Yehowa! no numana ndra''o, ba no i''orifido.', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 7, 'Fuli''ö, ya''ugö tödögu, fuli honogö''ö, me no si sökhi nifatörö Yehowa khöu.[2]', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 8, 'Noa sa ö''efa''ö nosogu ba wa''amate, no ö''otufoi daŵa hörögu, ba no ö''abe''e''ö gahegu, fa böi alau ndra''odo.', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 9, 'Utörö sa''ae lalagu andrö, föna Yehowa, ba danö niha sauri.[3]', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 10, 'No mamati ndra''o, andrö humede ndra''o. Si no aöndrö sibai ndra''odo.[4]', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 11, 'Umane ba wa''ata''ugu andrö: Solau faya niha, fefu.[5]', '["Ayati 8; Sin 18:6","Sin 42:6","Sin 27:13; 56:14","KorII 4:13","Rom 3:4"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 12, 'He uwisa wanulöni khö Yehowa si sökhi andrö fefu, nilaunia khögu?', '["Sin 72:14"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 13, 'Da''utuyu mako fangorifi andrö, ba u''angaröfi li döi Yehowa.', '["Sin 72:14"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 14, 'Ubu''a khö Yehowa gamabu''ula ligu andrö, ba zi so mbanuania fefu.', '["Sin 72:14"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 15, 'Omasiö wa''amate zatulö tödö andrö khönia, wamaigi Yehowa.[6]', '["Sin 72:14"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 16, 'Ya''ia Yehowa! — Enoniu sa ndra''odo; enoniu ndra''o, ono genoniu ira alawe andrö; no ötoto''ö wesugu andrö.', '["Sin 72:14"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 17, 'Khöu u''ohe zumange fangandrö saoha gölö ba u''angaröfi li döi Yehowa andrö.', '["Sin 72:14"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 18, 'Ubu''a khö Yehowa gamabu''ula ligu andrö, ba zi so mbanuania fefu.', '["Sin 72:14"]', NULL),
  (3476128, 'OT', 'Sinunö', 116, 19, 'Ba golayama föna ba nomo Yehowa andrö; ba dalumö, ya''ugö Yeruzalema! Haleluya!', '["Sin 72:14"]', NULL),
  (3476129, 'OT', 'Sinunö', 117, 1, 'Misuno Yehowa, ya''ami niha baero, fefu! Misuno ia, fefu soi niha![1]', '["Rom 15:11","MozII 34:6"]', NULL),
  (3476129, 'OT', 'Sinunö', 117, 2, 'Me no abölö ba khöda wa''ebua dödönia andrö, ba si lö aetu wa lö faröi Yehowa. Haleluya![2]', '["Rom 15:11","MozII 34:6"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 1, 'Mi''andrö saoha gölö khö Yehowa, me no si sökhi tödö ia, me si lö aetu wa''ebua dödönia andrö.[1][2]', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 2, 'Ba ndramuŵa''ö Iraono Gizeraeli: "Si lö aetu wa''ebua dödönia andrö!"[3]', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 3, 'Ndramuŵa''ö ma''uwu Ga''aroni andrö: "Si lö aetu wa''ebua dödönia!"', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 4, 'Ba ndramuwa''ö sangata''ufi Yehowa andrö: "Si lö aetu wa''ebua dödönia!"', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 5, 'Ba wa''atosasa u''angaröfi li Yehowa, ba no ifondrondrongo ligu Yehowa ba no i''ohedo ba zebolo tanö.', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 6, 'Awögu Yehowa, ba lö ata''u ndra''o. Hadia nilau niha khögu ena''ö?[4]', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 7, 'Awögu Yehowa, awö zanolo ya''odo andrö, wa''omasigu dania wamaigi si fatiu tödö khögu.[5]', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 8, 'Sökhi na tasaŵa Yehowa, moroi na tadöna-döna ba niha.', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 9, 'Sökhi na tasaŵa Yehowa, moroi na tadöna-döna ba zalaŵa.[6]', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 10, 'Lafasui ndra''o dozi niha baero, ba ba döi Yehowa andrö, ba lö zi lö u''ö''ötö ira.', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 11, 'Lafasui ndra''o, lafa''u''u ndra''o, ba ba döi Yehowa andrö, ba lö zi lö u''ö''ötö ira.', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 12, 'No lafasui ndra''o, hulö ŵani, ba mate fa''amate galitö ba ngafu za''a-sa''a mao; ba döi Yehowa andrö, ba lö zi lö u''ö''ötö ira.[7]', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 13, 'No ö''abölögö ötuli''ö ndra''odo, ena''ö alaudo; ba no itolodo Yehowa.', '["Faigi göi Eser 2:10 b.t.","Sin 107:1","Sin 115:9–13","Sin 56:5; Heb 13:6","Sin 54:9","Sin 146:3","Yes 33:12"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 14, 'Fa''abölögu Yehowa ba fanunögu, ba no tobali fangorifigu ia.[8]', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 15, 'Terongo wa''omuso dödö ba fangorifi baose ba zatulö tödö: Sabölö gambölö Yehowa andrö!', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 16, 'Si no alaŵa gambölö Yehowa andrö, sabölö gambölö Yehowa.', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 17, 'Tenga si mate ndra''odo, sauri ndra''o ba sangombakha nilau Yehowa andrö.', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 18, 'No i''abölögö i''otu''ö ndra''o Yehowa, ba lö nilulunia ya''odo ba wa''amate.[9]', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 19, 'Mibokai khögu mbawa göli andrö ba wa''atulö, ena''ö utörö, ba wanuno Yehowa!', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 20, 'Da''e mbawa göli andrö khö Yehowa; latörö satulö tödö andrö.[10]', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476130, 'OT', 'Sinunö', 118, 21, 'U''andrö saoha gölö khöu, wa no öfondrondrongo ligu, wa no tobali fangorifigu ndra''ugö.', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 22, 'Gowe andrö, nitibo''ö zotomo andrö, ba no tobali toyo ba watalinga.[11]', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 23, 'Moroi khö Yehowa, wa si manö ba sahöli-höli dödöda wamaigi.', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 24, 'Da''e mbaŵa andrö, ni''asogö Yehowa. Ba data''owua-wua''ö dödöda, hana na somuso tödö ita khönia.', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 25, 'He Yehowa, tolo! He Yehowa, ena''ö na si sökhi lua-lua öbe''e!', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 26, 'Ya ahowu zi so andrö ba döi Yehowa! Mafahowu''ö ami, moroi ba nomo Yehowa.[12]', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 27, 'Lowalangi Yehowa, ba no ifohaga ita. Miböbö zumange andrö, irugi dandru andrö ba naha wame''e sumange.', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 28, 'Lowalangigu ndra''ugö, ba mangandrö saoha gölö ndra''odo khöu. He Lowalangigu, da''u''ebua''ö duriamö andrö!', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476130, 'OT', 'Sinunö', 118, 29, 'Mi''andrö saoha gölö khö Yehowa, me no si sökhi tödö ia ba me si lö aetu wa''ebua dödönia andrö!', '["MozII 15:2","KorII 6:9","Sin 119:71","Yes 28:16; Mat 21:42","Mat 21:9; 23:39"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 1, 'Ya ahowu zi lö sinegu ba nitöröra andrö, sanörö lala goroisa Yehowa.[1]', '["Sin 1:1,2; 112:1"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 2, 'Ya ahowu zolo''ö famaduhu''ö andrö khönia, sangalui ya''ia, soroi si''aikö ba dödö.', '["Sin 1:1,2; 112:1"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 3, 'Si lö molau si lö atulö, sanörö lala andrö khönia.', '["Sin 1:1,2; 112:1"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 4, 'Amakhoitamö andrö, ba no öŵa''ö, ba wanörö ya''ia, soroi ba dödö.', '["Sin 1:1,2; 112:1"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 5, 'Ena''ö na ba da''ö itörö lalagu, ba wolo''ö amakhoitamö andrö!', '["Sin 1:1,2; 112:1"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 6, 'Ba lö falukhado wa''aila, na utöngöni goroisamö andrö.', '["Sin 1:1,2; 112:1"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 7, 'Moroi ba dödögu usunö ndra''ugö, na utanö ba dödögu gamakhoitamö andrö, satulö.', '["Sin 1:1,2; 112:1"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 8, 'Lö uböhöli ni''oroi''ömö andrö; böi falua wamöhöli ya''odo!', '["Sin 1:1,2; 112:1"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 9, 'He iwisa ono matua, fa böi fabaya hadia ia, ba döröŵania andrö? Na ibe''e dali daroma limö andrö.', '["Ayati 26:64,68","Ayati 24; Rom 7:22; Ayati 61"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 10, 'Moroi si''aikö ba dödögu u''alui ndra''ugö; böi be''e elungu ndra''o, wamöhöi oroisamö andrö.', '["Ayati 26:64,68","Ayati 24; Rom 7:22; Ayati 61"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 11, 'No u''irö''ö ba dödögu bakha niŵa''ömö andrö, fa böi molalö ndra''o khöu.', '["Ayati 26:64,68","Ayati 24; Rom 7:22; Ayati 61"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 12, 'Nisuno ndra''ugö Yehowa; fahaö ndra''o ba gamakhöitamö andrö.[2]', '["Ayati 26:64,68","Ayati 24; Rom 7:22; Ayati 61"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 13, 'Udunö-dunö bewegu goroisa mbawau andrö, fefu.', '["Ayati 26:64,68","Ayati 24; Rom 7:22; Ayati 61"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 14, 'Fa''omuso dödögu lala wamaduhu''ömö andrö, timba wa''omuso dödö ba gana''a.', '["Ayati 26:64,68","Ayati 24; Rom 7:22; Ayati 61"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 15, 'Ufatou-tou tödögu goroisamö andrö, ba utöngöni lala andrö khöu.', '["Ayati 26:64,68","Ayati 24; Rom 7:22; Ayati 61"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 16, 'Ba gamakhoitamö u''omusoi''ö dödögu, lö olifudo daroma limö.[3]', '["Ayati 26:64,68","Ayati 24; Rom 7:22; Ayati 61"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 17, 'Ebua''ö dödöu khö genoniu andre, ena''ö aurido, ba ufondrondrongo daroma limö andrö.', '["Sin 39:13","MozV 27:26","Ayati 35"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 18, 'Bokai hörögu, ena''ö u''ila zahöli-höli dödögu ba goroisamö andrö.', '["Sin 39:13","MozV 27:26","Ayati 35"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 19, 'Tome ndra''odo ba guli danö andre: Böi bini''ö khögu goroisamö andrö.[4]', '["Sin 39:13","MozV 27:26","Ayati 35"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 20, 'No arasa dödögu ba wehulu andrö ba zatulö andrö khöu, lö mamalö-malö.', '["Sin 39:13","MozV 27:26","Ayati 35"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 21, 'No ötenaŵa zebua hokha andrö; ni''elifi zelungu andrö, samöhöi oroisamö.[5]', '["Sin 39:13","MozV 27:26","Ayati 35"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 22, 'Heta khögu wango''aya andrö, awö wa''aila andrö; utöngöni sa wamaduhu''ömö andrö.', '["Sin 39:13","MozV 27:26","Ayati 35"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 23, 'He ŵa''ae no dumadao zalaŵa, mamagölö, ba khögu, andre: ba ifatou-tou sa atö tödönia enoniu gamakhoitamö andrö.', '["Sin 39:13","MozV 27:26","Ayati 35"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 24, 'Wa''omasigu sa''ae wamaduhu''ömö andrö, anofulagu.[6]', '["Sin 39:13","MozV 27:26","Ayati 35"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 25, 'Si no falemba ba danö nosogu; orifi ndra''odo fatörö niŵa''öu andrö!', '[]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 26, 'No utunö lalagu andrö, ba öfondrondrongo ligu; fahaö ndra''o ba gamakhoitamö andrö.', '[]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 27, 'Be''e aboto ba dödögu lala nifakhoimö andrö, ba ufatou-tou tödögu zahöli-höli dödö andrö khöu.', '[]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 28, 'Mangulu dödögu, ba wa''abu dödö andrö; abe''e''ö ndra''o, dali limö andrö.', '[]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 29, 'Aröu''ö khögu lala waya andrö, ba ebua''ö dödöu khögu, wamahaö ya''odo.', '[]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 30, 'No utuyu lala zi duhu andrö. No ube''e ba duduma hörögu zatulö andrö khöu.', '[]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 31, 'Tebai aefa ndra''odo ba wamaduhu''ömö andrö, ya''ugö Yehowa; böi be''e aila ndra''o.', '[]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 32, 'Utörö lala goroisamö andrö; ba öbologö dödögu.', '[]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 33, 'Fahaö ndra''odo, Yehowa, ba lala gamakhoitamö andrö, ena''ö utörö, irugi gamozua.', '["Ayati 47"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 34, 'Fa''aboto ba dödö be''e khögu, ena''ö utöngöni goroisamö andrö, ba ena''ö moroi ba dödögu u''o''ö.', '["Ayati 47"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 35, 'Fatörödo ba lala goroisamö andrö; omasido sa ia.[7]', '["Ayati 47"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 36, 'Ombuyu''ö dödögu ba wamaduhu''ömö andrö, ba böi ba wangalui ana''a.', '["Ayati 47"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 37, 'Hole''ö hörögu, fa böi ifaigi waya-faya; orifido ba lala andrö khöu!', '["Ayati 47"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 38, 'Fatörö khö genoniu andre gamabu''ula limö andrö, nibe''e famasugi wangata''ufi ya''ugö.', '["Ayati 47"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 39, 'Heta wa''ailagu andrö, sata''u ndra''odo; si sökhi sa nifakhoimö andrö.', '["Ayati 47"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 40, 'Hiza, humulu dödögu ba goroisamö andrö; orifido fa''atulö andrö khöu.', '["Ayati 47"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 41, 'Ena''ö na falukhado wa''ebua dödö andrö khöu, ya''ugö Yehowa, fangorifi andrö khöu, dali daroma limö!', '["Mat 10:18; Rom 1:16","Ayati 70"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 42, 'Ena''ö u''ila utema li zango''aya ya''o; udöna-döna sa''ae ba limö andrö.', '["Mat 10:18; Rom 1:16","Ayati 70"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 43, 'Ba böi hori ba mbewegu daroma li si duhu andrö; ba zatulö andrö khöu sa''ae manötöna ndra''odo.', '["Mat 10:18; Rom 1:16","Ayati 70"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 44, 'Ba lö ubulö''ö wolo''ö oroisamö andrö, lö ufamalö-malö, irugi zi lö aetu.', '["Mat 10:18; Rom 1:16","Ayati 70"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 45, 'Ena''ö utörö zebolo tanö; u''alu-alui sa tödögu nifakhoimö andrö.', '["Mat 10:18; Rom 1:16","Ayati 70"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 46, 'Ba ufatunö wamaduhu''ömö andrö ba zalaŵa; lö ailado.[8]', '["Mat 10:18; Rom 1:16","Ayati 70"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 47, 'Ube''e fa''omuso dödögu goroisamö andrö, somasi ndra''o sa''ae.[9]', '["Mat 10:18; Rom 1:16","Ayati 70"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 48, 'Ba ufazaŵa dangagu ba goroisamö andrö, somasi ndra''o sa''ae, ba u''alu-alui tödögu nifakhoimö andrö.', '["Mat 10:18; Rom 1:16","Ayati 70"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 49, 'Törö tödöu limö andrö khö genoniu andre, nibe''eu tötönafögu.', '["Sin 19:8"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 50, 'Da''ö wondrara dödögu ba wa''anumanagu andre, wa i''orifido taroma limö andrö.[10]', '["Sin 19:8"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 51, 'No laforege wango''aya ya''o sebua hokha; — ba lö niböhöligu oroisamö andrö.', '["Sin 19:8"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 52, 'No itörö tödögu zatulö andrö khöu, si otarai mböröta sa''ae, ya''ugö Yehowa, ba terara dödögu.', '["Sin 19:8"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 53, 'Mifönu sibai bakha dödögu ba zebua horö andrö, samöhöi oroisamö andrö.', '["Sin 19:8"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 54, 'Börö wanunö khögu gamakhoitamö andrö, ba danö si fatewu gana ndra''odo.', '["Sin 19:8"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 55, 'Ba zi bongi itorö tödögu döimö, ya''ugö Yehowa, ba utöngöni goroisamö.', '["Sin 19:8"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 56, 'Da''ö nihonogöi khögu: ena''ö u''o''ö nifakhoimö andrö.', '["Sin 19:8"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 57, 'Umane: He Yehowa! Tana khögu wanöngöni taroma limö andrö.', '["Ayati 83","Sin 42:9","Sin 33:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 58, 'Moroi si''aikö ba dödögu u''angaröfi li ndra''ugö; ebua''ö dödöu khögu, fatörö khögu gamabu''ula limö andrö.', '["Ayati 83","Sin 42:9","Sin 33:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 59, 'No ufatou-tou tödögu lala andrö khögu, ba no usaŵa wamaduhu''ö andrö khöu.', '["Ayati 83","Sin 42:9","Sin 33:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 60, 'No u''alio''ö ndra''odo, lö sarörö ndra''o, ba wolo''ö oroisamö.', '["Ayati 83","Sin 42:9","Sin 33:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 61, 'No tefa''u''u ndra''o fesu ba zebua horö andrö; ba lö solifudo oroisamö.[11]', '["Ayati 83","Sin 42:9","Sin 33:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 62, 'Na talu mbongi, ba maoso ndra''odo, ba wangandrö saoha gölö khöu amakhoitamö andrö, satulö.[12]', '["Ayati 83","Sin 42:9","Sin 33:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 63, 'Awö zangata''ufi ya''ugö andrö fefu ndra''odo andre, ba awö zanöngöni nifakhoimö andrö.', '["Ayati 83","Sin 42:9","Sin 33:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 64, 'He Yehowa, no anönö danö wa''ebua dödöu andrö; fahaö ndra''o ba nifakhoimö andrö.[13]', '["Ayati 83","Sin 42:9","Sin 33:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 65, 'No ölau zi sökhi khö genoniu andre, ya''ugö Yehowa, itörö niŵa''öu andrö.[14]', '["Sin 17:41","Ayati 75; Yes 28:19","Ayati 12","Ayati 78","Ayati 77","Sin 118:21","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 66, 'Si sökhi fangila ba fa''aboto ba dödö be''e khögu; mamati sa ndra''o ba goroisamö andrö.', '["Sin 17:41","Ayati 75; Yes 28:19","Ayati 12","Ayati 78","Ayati 77","Sin 118:21","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 67, 'Me lö mu''ide-ide''ö ndra''odo na, ba selungu ndra''o, ba iya''e, ba utöngöni niŵa''öu.[15]', '["Sin 17:41","Ayati 75; Yes 28:19","Ayati 12","Ayati 78","Ayati 77","Sin 118:21","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 68, 'Si sökhi tödö ndra''ugö ba soböwö, fahaö ndra''o ba gamakhoitamö andrö.[16]', '["Sin 17:41","Ayati 75; Yes 28:19","Ayati 12","Ayati 78","Ayati 77","Sin 118:21","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 69, 'Lafakhai waya khögu sebua hokha andrö; — ba ya''odo, ba moroi ba dödögu u''o''ö nifakhoimö andrö.[17]', '["Sin 17:41","Ayati 75; Yes 28:19","Ayati 12","Ayati 78","Ayati 77","Sin 118:21","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 70, 'No abe''e dödöra, motawö; ba ya''odo, ba u''omusoi''ö dödögu ba goroisamö andrö.[18]', '["Sin 17:41","Ayati 75; Yes 28:19","Ayati 12","Ayati 78","Ayati 77","Sin 118:21","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 71, 'Fangorifigu me te''ide-ide''ö ndra''odo, ena''ö utöngöni nifakhoimö andrö.[19]', '["Sin 17:41","Ayati 75; Yes 28:19","Ayati 12","Ayati 78","Ayati 77","Sin 118:21","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 72, 'Omasido goroisa mbawau andrö, moroi ba ngahönö gana''a ba moroi ba ngahönö wirö.[20]', '["Sin 17:41","Ayati 75; Yes 28:19","Ayati 12","Ayati 78","Ayati 77","Sin 118:21","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 73, 'Tangau zomböi ya''odo, tangau zamazökhi; be''e khögu wa''aboto ba dödö, ena''ö utöngöni goroisamö andrö.', '["Ayati 67","Sin 109:21","Ayati 143","Ayati 85:86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 74, 'La''ila dania ndra''o sangata''ufi ya''ugö, ba omuso dödöra me sanötöna ba daroma limö ndra''odo.', '["Ayati 67","Sin 109:21","Ayati 143","Ayati 85:86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 75, 'U''ila wa no satulö hukumö andrö, ya''ugö Yehowa, awö wa ba wa lö faröi ndra''ugö ö''ide-ide''ö ndra''odo.[21]', '["Ayati 67","Sin 109:21","Ayati 143","Ayati 85:86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 76, 'Ena''ö na fondrara dödögu wa''ebua dödöu andrö, ena''ö na itörö nifabu''umö andrö khö genoniu andre.[22]', '["Ayati 67","Sin 109:21","Ayati 143","Ayati 85:86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 77, 'Ena''ö na falukhado wa''ahakhö dödö khöu, ena''ö aurido; wa''omasigu sa goroisamö andrö.[23]', '["Ayati 67","Sin 109:21","Ayati 143","Ayati 85:86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 78, 'Akha aila zebua hokha andrö, me lahöndrögö ndra''o, lö börö, ba ya''odo, ba u''alu-alui tödögu geluaha goroisamö andrö.[24]', '["Ayati 67","Sin 109:21","Ayati 143","Ayati 85:86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 79, 'Ena''ö na fao-fao khögu zangata''ufi ya''ugö ba si no aboto ba dödö wamaduhu''ömö andrö!', '["Ayati 67","Sin 109:21","Ayati 143","Ayati 85:86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 80, 'Ya adölö dödögu wolo''ö amakhoitamö andrö, ena''ö lö falukha wa''aila ndra''odo.', '["Ayati 67","Sin 109:21","Ayati 143","Ayati 85:86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 81, 'Humulu dödögu ba wangorifi andrö khöu; udöna-döna ba daroma limö andrö.', '["Ayati 93","Ayati 69","Ayati 149"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 82, 'Omasi sibai hörögu daroma limö andrö, ba umane: "Ha wa''ara örara dödögu!"', '["Ayati 93","Ayati 69","Ayati 149"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 83, 'Hulö guli nambi ba zimbo sa''ae ndra''odo, ba lö solifudo nifakhoimö andrö.[25]', '["Ayati 93","Ayati 69","Ayati 149"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 84, 'Ha wa''anau noso genoniu andre? Ha wa''ara öhuku zolohi ya''odo?', '["Ayati 93","Ayati 69","Ayati 149"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 85, 'No lakharu khögu lösu-lösu sebua hokha andrö; ya''ira andrö, si lö faudu ba goroisamö andrö.[26]', '["Ayati 93","Ayati 69","Ayati 149"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 86, 'Oroisamö andrö fefu, ba no si duhu; lagohido lö börö: tolo ndra''odo!', '["Ayati 93","Ayati 69","Ayati 149"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 87, 'Hatö ma''ifu tö, ba labunudo mena''ö ba danö andre, ba lö''ö zui niböhöligu oroisamö andrö.', '["Ayati 93","Ayati 69","Ayati 149"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 88, 'Orifido ba wa''ebua dödöu andrö, ena''ö utöngöni wamaduhu''ö mbawau andrö![27]', '["Ayati 93","Ayati 69","Ayati 149"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 89, 'Taroma limö andrö, ya''ugö Yehowa, ba lö tebulö ba zorugo, irugi zi lö aetu.[28]', '["Yes 40:8","Ayati 50; Yer 15:16","Ayati 109","Ayati 45"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 90, 'Fa lö faröi ndra''ugö, ba götö-götö wa''ara; ya''ugö zamazökhi tanö, ba no aro.', '["Yes 40:8","Ayati 50; Yer 15:16","Ayati 109","Ayati 45"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 91, 'Dali nihonogöimö andrö, wa so manö fefu hadia ia, irugi ma''ökhö andre; oi sa ngoni-ngoniu fefu.', '["Yes 40:8","Ayati 50; Yer 15:16","Ayati 109","Ayati 45"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476131, 'OT', 'Sinunö', 119, 92, 'Na tenga fa''omuso dödögu goroisamö andrö mena''ö, ba noa sa''ae otufo gilogu ba wa''anumanagu andre.[29]', '["Yes 40:8","Ayati 50; Yer 15:16","Ayati 109","Ayati 45"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 93, 'Sagötö ya''odo, ba lö olifudo goroisamö andrö; noa sa öbe''e fangorifigu.[30]', '["Yes 40:8","Ayati 50; Yer 15:16","Ayati 109","Ayati 45"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 94, 'Khöu ndra''odo, tolodo! U''alu-alui sa goroisamö andrö.[31]', '["Yes 40:8","Ayati 50; Yer 15:16","Ayati 109","Ayati 45"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 95, 'Ladaro-darogö ndra''o sebua horö andrö, ba wamunu ya''odo. — Utöngötöngöni wamaduhu''ömö andrö.', '["Yes 40:8","Ayati 50; Yer 15:16","Ayati 109","Ayati 45"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 96, 'Fozu zo''ahonoa fefu, ba fa''aetu, u''ila: ba oroisamö andrö, ba si lö aetu.', '["Yes 40:8","Ayati 50; Yer 15:16","Ayati 109","Ayati 45"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 97, 'Ha lö omasido goroisamö andrö! Ma''öma''ökhö lö aefa ba dödögu.[32]', '["Sin 1:2","MozV 4:6","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 98, 'No ö''atua-tua''ö ndra''odo, moroi ba zi fa''udu khögu, oroisamö andrö, me no tana khögu, irugi zi lö aetu.[33]', '["Sin 1:2","MozV 4:6","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 99, 'Atua-tua ndra''odo, moroi ba zamahaö ya''o fefu; me ufatou-tou tödögu wamaduhu''ömö andrö.', '["Sin 1:2","MozV 4:6","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 100, 'Atua-tua ndra''o, moroi ba zatua, me utöngöni goroisamö andrö.', '["Sin 1:2","MozV 4:6","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 101, 'Lö urai uhundragö lala si lö sökhi, ena''ö u''o''ö limö andrö.', '["Sin 1:2","MozV 4:6","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 102, 'Lö uböhöli zatulö andrö khöu; me no öfahaö ndra''odo.', '["Sin 1:2","MozV 4:6","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 103, 'Wa''ami ba lelagu gamabu''ula limö andrö; ami moroi ba ŵe ŵani ba mbawagu![34]', '["Sin 1:2","MozV 4:6","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 104, 'Fangatua-tuagu goroisamö andrö; andrö u''ogorofi fefu lala waya andrö.', '["Sin 1:2","MozV 4:6","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 105, 'Fandru föna gahegu daroma limö andrö, ba haga ba lalagu.[35]', '["FetII 1:19","Ayati 67,71","Sin 19:15","Ayati 141"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 106, 'No fahölu ndra''odo, ba u''o''ö, ba wanöngöni amakhoitamö andrö, si no atulö.', '["FetII 1:19","Ayati 67,71","Sin 19:15","Ayati 141"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 107, 'No aöndrö sibai ndra''odo. He Yehowa orifi ndra''o, fatörö ba limö andrö?[36]', '["FetII 1:19","Ayati 67,71","Sin 19:15","Ayati 141"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 108, 'Ena''ö na omasi ndra''ugö game''ela mbewegu andrö, soroi ba dödö, ya''ugö Yehowa, ba ena''ö na öfahaö ndra''odo ba gamakhoitamö andrö.[37]', '["FetII 1:19","Ayati 67,71","Sin 19:15","Ayati 141"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 109, 'Ugogohe tangagu nosogu, si lö mamalö-malö, ba lö olifudo goroisamö andrö.[38]', '["FetII 1:19","Ayati 67,71","Sin 19:15","Ayati 141"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 110, 'No lalau wesu khögu sebua horö andrö, ba lö selungu ndra''o, lö niböhöligu oroisamö andrö.', '["FetII 1:19","Ayati 67,71","Sin 19:15","Ayati 141"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 111, 'Tana khögu, irugi zi lö aetu, wamaduhu''ömö andrö, me no fa''omuso dödögu.', '["FetII 1:19","Ayati 67,71","Sin 19:15","Ayati 141"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 112, 'No aolo dödögu ba wolo''ö amakhoitamö andrö, si lö mamalö-malö, irugi gamozua.', '["FetII 1:19","Ayati 67,71","Sin 19:15","Ayati 141"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 113, 'U''ogorofi zi dua tödö, ba oroisamö andrö, ba omasido.[39]', '["Sin 31:7","Sin 3:4"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 114, 'Nöugu ba balusegu ndra''ugö; manötöna ndra''o ba daroma limö andrö.[40]', '["Sin 31:7","Sin 3:4"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 115, 'Miheta ami khögu, ya''ami, solau si lö sökhi! ena''ö utöngöni goroisa Lowalangigu andrö.', '["Sin 31:7","Sin 3:4"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 116, 'Tuwu galogogu, dali nifabu''umö andrö, ena''ö aurido ba böi be''e aila ndra''o, ba wanötönagu andrö.', '["Sin 31:7","Sin 3:4"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 117, 'Abe''e''ö ndra''o, ena''ö falukhado wanolo, ba lö ufamalö-malö wanöngöni amakhoitamö andrö.', '["Sin 31:7","Sin 3:4"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 118, 'Selungu andrö, samöhöli nifakhoimö andrö, ba lö ba dödöu; me si lö boto wayara andrö.', '["Sin 31:7","Sin 3:4"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 119, 'Hulö na latibo''ö gakhozila ötibo''ö fefu zebua horö ba guli danö; andrö omasido wamaduhu''ömö andrö.', '["Sin 31:7","Sin 3:4"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 120, 'Muhokha mbugu, fa''ata''ugu ndra''ugö, ata''u ndra''odo wanguhukumö andrö.', '["Sin 31:7","Sin 3:4"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 121, 'No utörö zadölö ba satulö; böi lulu ndra''odo ba zamalangögö ya''o!', '["Sin 19:14","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 122, 'Oawögö genoniu andre, ba wangorifi ya''ia, fa böi lafakao ndra''o si fayaŵa andrö![41]', '["Sin 19:14","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 123, 'Omasido sibai u''ila wangorifi andrö ba taroma li satulö andrö khöu.', '["Sin 19:14","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 124, 'Be''e dali wa''ebua dödöu andrö, wamatörö enoniu andre, ba fahaö ndra''o ba gamakhoitamö andrö.', '["Sin 19:14","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 125, 'Enoniu ndra''odo; fa''atua-tua be''e khögu, ena''ö aboto ba dödögu wamaduhu''ömö andrö.', '["Sin 19:14","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 126, 'Baŵa wolau sa''ae khö Yehowa; no labe''e faya goroisamö andrö.', '["Sin 19:14","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 127, 'Da''ö mbörö, wa omasido goroisamö andrö, moroi ba gana''a, moroi ba mbalaki.[42]', '["Sin 19:14","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 128, 'Andrö utehe fefu nifakhoimö andrö; fefu lala waya, ba u''ogorofi.', '["Sin 19:14","Sin 19:11"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 129, 'Sahöli-höli dödö wamaduhu''ömö andrö; andrö itöngöni tödögu.', '["Sin 19:8","Sin 17:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 130, 'Nat teboka daroma limö andrö, ba mohaga; falukha wa''aboto ba dödö zadölö tödö.[43]', '["Sin 19:8","Sin 17:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 131, 'Ubokai mbawagu, owökhi dödögu, humulu ba goroisamö andrö.', '["Sin 19:8","Sin 17:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 132, 'Otahögö ndra''odo ba ebua''ö dödöu khögu, törö lala ba zangomasi''ö töimö andrö!', '["Sin 19:8","Sin 17:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 133, 'Abe''e''ö mbekagu ba lala limö andrö ba böi be''e ifatörö si lö atulö hadia ia![44]', '["Sin 19:8","Sin 17:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 134, 'Efa''ö ndra''o ba wamakao niha ya''odo, ena''ö u''o''ö goroisamö andrö.', '["Sin 19:8","Sin 17:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 135, 'Hagaini genonimö andre bawau, ba fahaö ndra''o ba gamakhoitamö andrö.', '["Sin 19:8","Sin 17:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 136, 'No falawu idanö hörögu, mo''elea, me lö mu''o''ö goroisamö andrö.', '["Sin 19:8","Sin 17:5"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 137, 'Satulö ndra''ugö Yehowa, ba satulö wanguhukumö andrö.', '["Sin 69:10","Ayati 153","Ayati 174"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 138, 'Famaduhu''ömö andrö, ba ba wa''atulö ö''oroi''ö mege, ba ba wa''aduhu manö.', '["Sin 69:10","Ayati 153","Ayati 174"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 139, 'I''ado sa''ae fönugu andrö, me no olifu zamakao ya''o daroma limö andrö.[45]', '["Sin 69:10","Ayati 153","Ayati 174"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 140, 'Si lö fabaya hadia ia daroma limö andrö, ba i''omasi''ö enonimö andre.', '["Sin 69:10","Ayati 153","Ayati 174"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 141, 'Side-ide ndra''odo, ba si lö ba dödö niha bö''ö, ba lö solifudo oroisamö andrö.[46]', '["Sin 69:10","Ayati 153","Ayati 174"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 142, 'Fa''atulömö andrö, ba no fa''atulö si lö mamalö-malö, ba no si duhu goroisamö andrö.', '["Sin 69:10","Ayati 153","Ayati 174"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 143, 'No göna ndra''o fa''abu dödö ba fa''atosasa; ba fa''omuso dödögu goroisamö andrö.[47]', '["Sin 69:10","Ayati 153","Ayati 174"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 144, 'Fa''atulö wamaduhu''ömö andrö, ba si lö mamalö-malö; be''e khögu wa''aboto ba dödö, ena''ö aurido!', '["Sin 69:10","Ayati 153","Ayati 174"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 145, 'Mu''ao ndra''o, moroi si''aikö ba dödögu: Fondrondrongo khögu, Yehowa! U''o''ö gamakhoitamö andrö.', '["Ayati 114","Ayati 88,154,159","Ayati 86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 146, 'U''angaröfi li ndra''ugö, tolodo, ena''ö u''o''ö gamakhoitamö andrö!', '["Ayati 114","Ayati 88,154,159","Ayati 86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 147, 'Lö börö moluo na, ba mu''ao ndra''o; udöna-döna ba limö andrö.[48]', '["Ayati 114","Ayati 88,154,159","Ayati 86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 148, 'Ihulö wamosasi zi bongi andrö hörögu, ba wamatou-tou taroma limö andrö.', '["Ayati 114","Ayati 88,154,159","Ayati 86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 149, 'Fondrondrongo ligu, ba wa''ebua dödöu andrö; he Yehowa, orifi ndra''o, dali lala andrö khöu![49]', '["Ayati 114","Ayati 88,154,159","Ayati 86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 150, 'Lahatö''ö ira sanao horö, si no aröu oroisamö andrö.[50]', '["Ayati 114","Ayati 88,154,159","Ayati 86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 151, 'Sahatö ndra''ugö, ya''ugö Yehowa, ba si duhu manö goroisamö andrö fefu.', '["Ayati 114","Ayati 88,154,159","Ayati 86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 152, 'No ara sa''ae u''ila ba wamaduhu''ömö andrö, wa no öhonogöi ia sirugi si lö aetu.', '["Ayati 114","Ayati 88,154,159","Ayati 86"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 153, 'Faigi wa''anumanagu andre, ba efa''ö ndra''odo! Lö''ö sa solifudo oroisamö andrö.[51]', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 154, 'Fatunö huhuogu andrö ba efa''ö ndra''o; orifido, fatörö ba limö andrö!', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 155, 'Ba zebua horö andrö, ba no aröu wangorifi, me lö ba dödöra amakhoitamö andrö.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 156, 'No ebua wa''ahakhö dödöu andrö, ya''ugö Yehowa, orifido, fatörö ba lala andrö khöu.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 157, 'No ato zolohi ya''odo ba samakao ya''o, ba lö uböhöli wamaduhu''ömö andrö.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 158, 'No u''ila zo''olalöŵa andrö, ba ogoro ndra''o, me lö ba dödöra taroma limö andrö.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 159, 'Nehegö, wa no somasi oroisamö andrö ndra''odo; he Yehowa, orifido, ba wa''ebua dödöu andrö!', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 160, 'Ahonoa daroma limö andrö, ba si duhu, ba si lö aetu lala wa''atulö andrö khöu.[52] Ŵ.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 161, 'Lagohi ndra''o salaŵa, lö börö, ba taroma limö andrö zata''u dödögu.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 162, 'Omuso dödögu niŵa''ömö andrö, fa''omuso dödö zanöndra hare sebua.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 163, 'Si fatuwu ba dödögu waya ba u''ogorofi; ba oroisamö andrö, ba omasido.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 164, 'Mewitu ma''ökhö usuno ndra''ugö ba nifakhoimö andrö, satulö andrö.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 165, 'Ba zomasi oroisamö andrö, ba fahöna wa''ohahau dödö, ba lö manendre ira.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 166, 'Udöna-döna wangorifi andrö khöu, ya''ugö Yehowa, ba u''o''ö goroisamö andrö.[53]', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 167, 'Itöngöni wamaduhu''ömö andrö tödögu, ba no tobali omasido sibai ia.', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 168, 'U''o''ö goroisamö, awö wamaduhu''ömö andrö; duduma höröu sa atö lalagu andrö fefu.[54]', '["Ayati 176","Yoh 17:17","MozI 49:18","Sin 18:22"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 169, 'Akha irugi ndra''ugö fangarö-ngarögu andrö, ya''ugö Yehowa; be''e khögu wa''aboto ba dödö, fatörö ba niŵa''öu andrö.', '["Sin 1:2; Amaed 6:22","Yes 53:6; Ayati 16"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 170, 'Folala khöu wakaosagu andrö; orifi ndra''odo, fatörö ba niŵa''öu andrö.', '["Sin 1:2; Amaed 6:22","Yes 53:6; Ayati 16"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 171, 'Luaha wanuno ya''ugö dania mbewegu, öfahaö sa ndra''o ba gamakhoitamö andrö.', '["Sin 1:2; Amaed 6:22","Yes 53:6; Ayati 16"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 172, 'Sanuno taroma limö andrö dania legagu, me no satulö goroisamö andrö fefu.[55]', '["Sin 1:2; Amaed 6:22","Yes 53:6; Ayati 16"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 173, 'Ya möi fanolo khögu dangau andrö; noa sa utuyu khögu goroisamö andrö.', '["Sin 1:2; Amaed 6:22","Yes 53:6; Ayati 16"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 174, 'Omasido wangorifi andrö khöu, ya''ugö Yehowa; ba fa''omuso dödögu goroisamö andrö.', '["Sin 1:2; Amaed 6:22","Yes 53:6; Ayati 16"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 175, 'Akha anau nosogu, ena''ö usuno ndra''ugö; ba hana na itolo ndra''o hukumö andrö.', '["Sin 1:2; Amaed 6:22","Yes 53:6; Ayati 16"]', NULL),
  (3476131, 'OT', 'Sinunö', 119, 176, 'Si no elungu ndra''odo; alui genonimö andre, nifangalui biri-biri si suna; lö''ö sa solifudo oroisamö andrö.[56]', '["Sin 1:2; Amaed 6:22","Yes 53:6; Ayati 16"]', NULL),
  (3476132, 'OT', 'Sinunö', 120, 1, 'No u''angaröfi li Yehowa, ba wa''abu dödögu andrö, ba no ifondrondrongo khögu.', '[]', NULL),
  (3476132, 'OT', 'Sinunö', 120, 2, 'He Yehowa, efa''ö ndra''odo ba mbewe andrö, sofaya, ba ba lela si falimo!', '[]', NULL),
  (3476132, 'OT', 'Sinunö', 120, 3, 'Hadia nilau lela si falimo khöu, ba hadia ninönönia khöu?', '[]', NULL),
  (3476132, 'OT', 'Sinunö', 120, 4, 'Ono wana ba zabölö ni''atarösi, ba bo galitö, ba manaze.', '[]', NULL),
  (3476132, 'OT', 'Sinunö', 120, 5, 'Alai ndra''o, me no si fatewu ba Mesekhi ndra''odo, me ba nose Gedara sodo!', '[]', NULL),
  (3476132, 'OT', 'Sinunö', 120, 6, 'No abölö ara ndra''odo ba zi fa''udu ba wa''atulö!', '[]', NULL),
  (3476132, 'OT', 'Sinunö', 120, 7, 'Satulö ndra''o, ba na muhededo, ba lasao''ö wasöndrata.', '[]', NULL),
  (3476133, 'OT', 'Sinunö', 121, 1, 'Ufaöga hörögu, ufaigi hili andrö: Heza i''otarai fangorifigu?', '["MozIV 6:24"]', NULL),
  (3476133, 'OT', 'Sinunö', 121, 2, 'Fangorifigu andrö, ba i''otarai Yehowa, samazökhi banua si yaŵa, awö danö.', '["MozIV 6:24"]', NULL),
  (3476133, 'OT', 'Sinunö', 121, 3, 'Lö''ö sa ibe''e mangiwa gaheu; samaigi-maigi ya''ugö andrö, ba lö manuköu.', '["MozIV 6:24"]', NULL),
  (3476133, 'OT', 'Sinunö', 121, 4, 'Hiza, lö manuköu zamaigi-maigi Iraono Gizeraeli andrö ba lö mörö.', '["MozIV 6:24"]', NULL),
  (3476133, 'OT', 'Sinunö', 121, 5, 'Sondrorogö ya''ugö Yehowa; ilumö''ö ndra''ugö Yehowa ba gambölöu.', '["MozIV 6:24"]', NULL),
  (3476133, 'OT', 'Sinunö', 121, 6, 'Lö ihandro ndra''ugö sino na ma''ökhö, ba he baŵa ba zi bongi.', '["MozIV 6:24"]', NULL),
  (3476133, 'OT', 'Sinunö', 121, 7, 'Irorogö ndra''ugö Yehowa, itimba zi lö sökhi fefu, irorogö nosou.[1]', '["MozIV 6:24"]', NULL),
  (3476133, 'OT', 'Sinunö', 121, 8, 'Yehowa zamaigi-maigi fofanöu, awö wangawuliu, i''otarai da''e, irugi zi lö aetu.', '["MozIV 6:24"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476134, 'OT', 'Sinunö', 122, 1, 'Omuso dödögu, me lamane khögu: "Möi ita ba gosali Yehowa andrö!"[1]', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476134, 'OT', 'Sinunö', 122, 2, 'Ba mbawa gölimö tebato ndra''aga, ya''ugö Yeruzalema!', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476134, 'OT', 'Sinunö', 122, 3, 'Yeruzalema andrö, si no mufuli mutaru''ö, banua nihaogö famaböbö!', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476134, 'OT', 'Sinunö', 122, 4, 'Ba zi möi misi yaŵa mado andrö, mado khö Yehowa andrö, dali goroisa andrö ba Ndraono Gizeraeli, ba wanuno töi Yehowa.', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476134, 'OT', 'Sinunö', 122, 5, 'Ba da''ö sa tefedadao dadaoma andrö, ba wanguhuku, dadaoma nono Dawido andrö.', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476134, 'OT', 'Sinunö', 122, 6, 'Mifahowu''ö Yeruzalema andrö! Ya falukha wa''ohahau dödö zomasi ya''ugö![2]', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476134, 'OT', 'Sinunö', 122, 7, 'Ya atulö bakha barö göli khöu, ba ya monaha wa''ohahau dödö ba gödo andrö khöu!', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476134, 'OT', 'Sinunö', 122, 8, 'Börö dalifusögu ba si fahuwu khögu, wa umane: "Ya monaha wa''atulö khöu!"', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476134, 'OT', 'Sinunö', 122, 9, 'Börö nomo Lowalangida Yehowa andrö, wa u''alui zi sökhi khöu.', '["Sin 26:6–8","Sakh 4:7"]', NULL),
  (3476135, 'OT', 'Sinunö', 123, 1, 'Khöu ufaöga hörögu ya''ugö sidadao ba zorugo.', '[]', NULL),
  (3476135, 'OT', 'Sinunö', 123, 2, 'Hiza, si mane hörö genoni ono matua, sanöngöni tanga zokhö ya''ira, ba si mane hörö genoni ono alawe, ba danga zokhö ya''ira ira alawe, si manö göi höröda ba khö Lowalangida So''aya, irege ihakhösi tödö ita.', '[]', NULL),
  (3476135, 'OT', 'Sinunö', 123, 3, 'Hakhösi tödö ndra''aga Yehowa, hakhösi tödö ndra''aga! noa sa aföli sibai ndra''aga wango''aya andrö.', '[]', NULL),
  (3476135, 'OT', 'Sinunö', 123, 4, 'No biha wa''aföli dödöma wa''iki zebua hokha andrö, awö wa lö ba dödö zi fayaŵa andrö ya''aga.', '[]', NULL),
  (3476136, 'OT', 'Sinunö', 124, 1, 'Na tenga Yehowa mena''ö zi oawögö ya''aga — ya lamanö Iraono Gizeraeli.', '["Sin 42:8; 69:16","Sin 121:2"]', NULL),
  (3476136, 'OT', 'Sinunö', 124, 2, 'Na tenga Yehowa mena''ö zi oawögö ya''aga, me maoso khöma niha,', '["Sin 42:8; 69:16","Sin 121:2"]', NULL),
  (3476136, 'OT', 'Sinunö', 124, 3, 'ba noa sa''ae latölö auri ndra''aga mena''ö, me tesao wönura khöma.', '["Sin 42:8; 69:16","Sin 121:2"]', NULL),
  (3476136, 'OT', 'Sinunö', 124, 4, 'Noa sa''ae inönöi mena''ö ndra''aga idanö andrö, ba no itörö mena''ö nosoma idanö sebua andrö.[1]', '["Sin 42:8; 69:16","Sin 121:2"]', NULL),
  (3476136, 'OT', 'Sinunö', 124, 5, 'No itörö mena''ö nosoma idanö andrö sebua hokha.', '["Sin 42:8; 69:16","Sin 121:2"]', NULL),
  (3476136, 'OT', 'Sinunö', 124, 6, 'Nisuno Yehowa, si lö molulu ya''aga ö mbohara andrö.', '["Sin 42:8; 69:16","Sin 121:2"]', NULL),
  (3476136, 'OT', 'Sinunö', 124, 7, 'No aefa nosoma, hulö wofo ba wesu ba zolau fesu wofo; no aetu wesu andrö, ba no aefa ndra''aga.', '["Sin 42:8; 69:16","Sin 121:2"]', NULL),
  (3476136, 'OT', 'Sinunö', 124, 8, 'Fangorifima andrö, ba ba döi Yehowa so ia, ba döi Yehowa andrö samazökhi banua si yaŵa, awö danö.[2]', '["Sin 42:8; 69:16","Sin 121:2"]', NULL),
  (3476137, 'OT', 'Sinunö', 125, 1, 'Sanötöna khö Yehowa andrö, ba no hulö hili Ziona andrö, si lö mangiwa, si lö tebulö, irugi zi lö aetu.', '["Sin 36:7","Gal 6:16"]', NULL),
  (3476137, 'OT', 'Sinunö', 125, 2, 'Si tefasui Yeruzalema, ba hili, ba Yehowa zamasui banuania andrö, i''otarai da''e, irugi zi lö aetu.[1]', '["Sin 36:7","Gal 6:16"]', NULL),
  (3476137, 'OT', 'Sinunö', 125, 3, 'Tenga sa si lö tebulö wamatörö zanao horö tana ba zatulö tödö, fa böi mulalö danga zatulö tödö, ba horö.', '["Sin 36:7","Gal 6:16"]', NULL),
  (3476137, 'OT', 'Sinunö', 125, 4, 'Ebua''ö dödöu, Yehowa, ba zatulö andrö ba ba zadölö tödö.', '["Sin 36:7","Gal 6:16"]', NULL),
  (3476137, 'OT', 'Sinunö', 125, 5, 'Ba sanaŵa lala sabila, ba ya meziŵa ilulu Yehowa, awö zanao horö andrö. Ya falukha wa''ohahau dödö Ndraono Gizeraeli![2]', '["Sin 36:7","Gal 6:16"]', NULL),
  (3476138, 'OT', 'Sinunö', 126, 1, 'Me i''ohe mangawuli Yehowa zangawuli andrö, banua Ziona, ba no hulö zangifi ita.[1]', '["Sin 14:7","Mat 5:4"]', NULL),
  (3476138, 'OT', 'Sinunö', 126, 2, 'Fahöna ba mbawama wa''iki ba fahöna ba lelama lua-lua wa''omuso dödö.', '["Sin 14:7","Mat 5:4"]', NULL),
  (3476138, 'OT', 'Sinunö', 126, 3, 'Ba lamane niha baero: "Sebua nilau Yehowa khöra!" Ya''ia, sebua nilau Yehowa khöda, ba omuso dödöda.', '["Sin 14:7","Mat 5:4"]', NULL),
  (3476138, 'OT', 'Sinunö', 126, 4, 'He Yehowa, ohe mangawuli ni''oloi''ö andrö, si mane na öfuli öfo''idanö mbombo ba danö si raya.', '["Sin 14:7","Mat 5:4"]', NULL),
  (3476138, 'OT', 'Sinunö', 126, 5, 'Se''ege-ege ba wanaru, ba ma''iki-iki dania ba wamasi.[2]', '["Sin 14:7","Mat 5:4"]', NULL),
  (3476138, 'OT', 'Sinunö', 126, 6, 'Mege-ege ia, na möi ia molohe ba danö tanömö andrö, ba na mangawuli, na manao bua nowi ia, ba ma''iki-iki.', '["Sin 14:7","Mat 5:4"]', NULL),
  (3476139, 'OT', 'Sinunö', 127, 1, 'Na tenga Yehowa zangotomosi omo, ba zaya-zaya gölö halöŵö zotomo andrö. Na tenga Yehowa zanaro banua ba zaya-zaya gölö wa lö mörö zanaro andrö.', '["Amaed 10:22","MozI 33:5; Sin 128:3,4"]', NULL),
  (3476139, 'OT', 'Sinunö', 127, 2, 'Zaya-zaya gölö wa ahulö maoso ami, awö wa alaŵa mbongi möi mörö, wemanga ölömi, serege dödömi, si manö göi wame''enia ba zomasi ia, barö wemörö.[1]', '["Amaed 10:22","MozI 33:5; Sin 128:3,4"]', NULL),
  (3476139, 'OT', 'Sinunö', 127, 3, 'Hiza, okhöta nibe''e Yehowa ndraono, böli gölö nga''ötö andrö.[2]', '["Amaed 10:22","MozI 33:5; Sin 128:3,4"]', NULL),
  (3476139, 'OT', 'Sinunö', 127, 4, 'Si mane ono wana ba danga zabölö, si manö nono matua ba wa''abölö mege.', '["Amaed 10:22","MozI 33:5; Sin 128:3,4"]', NULL),
  (3476139, 'OT', 'Sinunö', 127, 5, 'Ya ahowu niha andrö, si fahöna da''ö ba naha nono wana, lö falukha ira wa''aila; na so huhuora ba zi fa''udu khöra, ba mbawa göli.', '["Amaed 10:22","MozI 33:5; Sin 128:3,4"]', NULL),
  (3476140, 'OT', 'Sinunö', 128, 1, 'Ya ahowu dozi sangata''ufi Yehowa, sanörö lala andrö khönia.', '["Sin 127:3","Sin 125:5"]', NULL),
  (3476140, 'OT', 'Sinunö', 128, 2, 'Ö''a gölö dangau andrö; ya ahowu ndra''ugö, sohahau tödö ndra''ugö.', '["Sin 127:3","Sin 125:5"]', NULL),
  (3476140, 'OT', 'Sinunö', 128, 3, 'Fo''omou andrö, ba no hulö ŵeŵe nagu sowua, baomou, ba iraono andrö khöu, ba no hulö ndraha falo, tefasui meza khöu.[1]', '["Sin 127:3","Sin 125:5"]', NULL),
  (3476140, 'OT', 'Sinunö', 128, 4, 'Hiza, si manö howu-howu ba niha sangata''ufi Yehowa.', '["Sin 127:3","Sin 125:5"]', NULL),
  (3476140, 'OT', 'Sinunö', 128, 5, 'Yamufahowu''ö ndra''ugö Yehowa, moroi ba Ziona, ba yagö mu''ila wa''ohahau dödö Yeruzalema andrö, fa''omuso dödöu, götö wa''anau nosou.', '["Sin 127:3","Sin 125:5"]', NULL),
  (3476140, 'OT', 'Sinunö', 128, 6, 'Ba yagö falukha ma''uwu! Ya falukha wa''ohahau dödö Ndraono Gizeraeli![2]', '["Sin 127:3","Sin 125:5"]', NULL),
  (3476141, 'OT', 'Sinunö', 129, 1, 'No lö aetu lafakao ndra''o, i''otarai iraono ndra''odo — ya lamanö sa''ae Iraono Gizeraeli.', '["Yes 50:6; 51:23","Rut 2:4"]', NULL),
  (3476141, 'OT', 'Sinunö', 129, 2, 'No lö aetu lafakao ndra''o, i''otarai iraono ndra''odo, ba tebai sa atö lahöndrögö ndra''odo.', '["Yes 50:6; 51:23","Rut 2:4"]', NULL),
  (3476141, 'OT', 'Sinunö', 129, 3, 'No lafaku-faku hulugu sonowi andrö, no ebolo lafahufa.[1]', '["Yes 50:6; 51:23","Rut 2:4"]', NULL),
  (3476141, 'OT', 'Sinunö', 129, 4, 'No i''etu''ö Yehowa wesu andrö, nilau zebua horö; Yehowa satulö andrö.', '["Yes 50:6; 51:23","Rut 2:4"]', NULL),
  (3476141, 'OT', 'Sinunö', 129, 5, 'Si falukha fa''aila ba sangawuli furi dania zi fa''udu ba Ziona andrö.', '["Yes 50:6; 51:23","Rut 2:4"]', NULL),
  (3476141, 'OT', 'Sinunö', 129, 6, 'Ya hulö ndru''u ba gero zagö ira, saleu sa''ae, na lö''ö na''i molai;', '["Yes 50:6; 51:23","Rut 2:4"]', NULL),
  (3476141, 'OT', 'Sinunö', 129, 7, 'si lö möi ba danga zamasi, ba si lö möi noro zanutuyu ngalai.', '["Yes 50:6; 51:23","Rut 2:4"]', NULL),
  (3476141, 'OT', 'Sinunö', 129, 8, 'Ba böi laŵa''ö sanörö: "Yawahowu''ö ami Yehowa! Mafahowu''ö ami ba döi Yehowa andrö![2]', '["Yes 50:6; 51:23","Rut 2:4"]', NULL),
  (3476142, 'OT', 'Sinunö', 130, 1, 'Moroi ba gohokoho u''angaröfi li ndra''ugö, Yehowa![1]', '["Sin 69:3","Sin 19:13","Yes 55:7; Rom 6:1,2","Mat 1:21"]', NULL),
  (3476142, 'OT', 'Sinunö', 130, 2, 'He So''aya, fondrondrongo ligu andre! Be''e mbörö dalingau ba li wangandrögu!', '["Sin 69:3","Sin 19:13","Yes 55:7; Rom 6:1,2","Mat 1:21"]', NULL),
  (3476142, 'OT', 'Sinunö', 130, 3, 'Na ötanö ba dödöu ena''ö horö andrö, ya''ugö Yehowa, ba ha niha zi tola, ya''ugö So''aya?[2]', '["Sin 69:3","Sin 19:13","Yes 55:7; Rom 6:1,2","Mat 1:21"]', NULL),
  (3476142, 'OT', 'Sinunö', 130, 4, 'Ba no so ba khöu wangefa horö, ena''ö la''ata''ufi ndra''ugö.[3]', '["Sin 69:3","Sin 19:13","Yes 55:7; Rom 6:1,2","Mat 1:21"]', NULL),
  (3476142, 'OT', 'Sinunö', 130, 5, 'Udöna-döna khö Yehowa, ibazebaze''ö tödögu, ba udöna-döna lua-lua linia andrö.', '["Sin 69:3","Sin 19:13","Yes 55:7; Rom 6:1,2","Mat 1:21"]', NULL),
  (3476142, 'OT', 'Sinunö', 130, 6, 'Ibazebaze''ö Zo''aya tödögu, moroi ba wombase''ö zanaro andrö fa''amoluo; ya''ia, moroi ba wombase''ö zanaro andrö fa''amoluo,', '["Sin 69:3","Sin 19:13","Yes 55:7; Rom 6:1,2","Mat 1:21"]', NULL),
  (3476142, 'OT', 'Sinunö', 130, 7, 'Midöna-döna khö Yehowa, ya''ami Iraono Gizeraeli; khö Yehowa sa so wa''ahakhö dödö, ba fangorifi andrö, ba no fahöna khönia.', '["Sin 69:3","Sin 19:13","Yes 55:7; Rom 6:1,2","Mat 1:21"]', NULL),
  (3476142, 'OT', 'Sinunö', 130, 8, 'Ba ya''ia zameta ba Ndraono Gizeraeli lalöra fefu.[4]', '["Sin 69:3","Sin 19:13","Yes 55:7; Rom 6:1,2","Mat 1:21"]', NULL),
  (3476143, 'OT', 'Sinunö', 131, 1, 'He Yehowa, lö fayaŵa dödögu ba tenga si so hokha hörögu andre. Lö ubabaya zi tebai ndra''o ba si lö aboto ba dödögu.', '["Sin 130:7"]', NULL),
  (3476143, 'OT', 'Sinunö', 131, 2, 'Si ndruhu, no uhonogö dödögu, lö hede-hedenia, hulö ndraono si no aefa ba mbagi zusu, khö ninania; si mane si no aefa ba mbagi zusu bakha dödögu.', '["Sin 130:7"]', NULL),
  (3476143, 'OT', 'Sinunö', 131, 3, 'Midöna-döna khö Yehowa, ya''ami Iraono Gizeraeli, ya i''otarai da''e, ya'' irugi zi lö aetu.[1]', '["Sin 130:7"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 1, 'Törö tödöu, ya''ugö Yehowa, khö Dawido andrö, fefu wamakao andrö, si no göna ia!', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 2, 'Si no fahölu khö Yehowa, si no mamabu''u linia ba zabölö andrö khö Yakobo, wanguma''ö:', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 3, '"Lö möido yomo ba nomogu ose andrö ba lö möido mörö ba gasogu andrö;', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 4, 'lö utehe ba hörögu wemörö, ba lö utehe ba guli hörögu wa''alau:', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 5, 'Balazi no usöndra naha khö Yehowa, omo khö zabölö andrö khö Yakobo."[2]', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 6, 'Hiza, no tarongo ba Geferata so ia; ba ndraso andrö ba Ya''ari tasöndra ia.[3]', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 7, 'Damöi ita ba nahiania andrö, ba wangalulu föna mbaku-baku gahenia andrö.', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 8, 'Faoso, Yehowa, saŵa zolombase ndra''ugö, ya''ugö andrö, awö dawöla wa''asalaŵamö andrö![4]', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 9, 'Ndramu''obaru wa''atulö ere andrö khöu, ba ndrama''iki zatulö tödö andrö khömö.', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 10, 'Böi timba mbawa nibayoinimö andrö, börö genoniu Dawido andrö!', '["HalZin 7:46","SamI 7:1; SamII 6:3","MozIV 10:35; Nga''ötII 6:41,42"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 11, 'No fahölu Yehowa khö Dawido, si ndruhu-ndruhu, si lö iwu''ai, no imane: "Ma''uwumö ufedadao ba dadaomamö andrö."[5]', '["Sin 89:4","Sin 68:17; 76:3","Luk 1:69; Sin 89:25"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 12, 'Na lö laböhöli iraonou wawu''usa li andrö khögu ba famaduhu''ögu, ba nifahaögu ya''ira, ba dumadao göi dania nonora ba dadaomamö andrö, si lö mamalö-malö.', '["Sin 89:4","Sin 68:17; 76:3","Luk 1:69; Sin 89:25"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 13, 'Noa sa ituyu Ziona andrö Yehowa ba omasi ia ba da''ö soso ia.[6]', '["Sin 89:4","Sin 68:17; 76:3","Luk 1:69; Sin 89:25"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 14, 'Da''e golombaseŵa khögu, si lö mamalö-malö, ba da''e soso ndra''o, me no omasido ia.', '["Sin 89:4","Sin 68:17; 76:3","Luk 1:69; Sin 89:25"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 15, 'Ufahowu''ö sibai mbalazora, abuso fakhe zi numana khöra ube''e.', '["Sin 89:4","Sin 68:17; 76:3","Luk 1:69; Sin 89:25"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 16, 'Ufobaru fangorifi gere khöra, ba omuso dödö zatulö tödö andrö khöra ba ma''iki, ube''e.', '["Sin 89:4","Sin 68:17; 76:3","Luk 1:69; Sin 89:25"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 17, 'Ba da''ö ube''e wa''abölö khö Dawido ba ufazökhi wandru khö nibayoinigu andrö.[7]', '["Sin 89:4","Sin 68:17; 76:3","Luk 1:69; Sin 89:25"]', NULL),
  (3476144, 'OT', 'Sinunö', 132, 18, 'Si fa''udu khönia andrö, ba ufobaru fa''aila; ba ba högönia, ba saembunia si takile."', '["Sin 89:4","Sin 68:17; 76:3","Luk 1:69; Sin 89:25"]', NULL),
  (3476145, 'OT', 'Sinunö', 133, 1, 'Hiza wa''asökhi, ba ha lö omasiö, na ha sara dödö moroi yomo zi fatalifusö!', '["MozII 29:7; 30:23–30"]', NULL),
  (3476145, 'OT', 'Sinunö', 133, 2, 'Si mane fanikha samohua ba högö, sowöi mitou ba mbu gambi, ba gambi Ga''aroni andrö, sowöi mitou, irege gahe mbarunia.[1]', '["MozII 29:7; 30:23–30"]', NULL),
  (3476145, 'OT', 'Sinunö', 133, 3, 'Si mane namo mbanua andrö ba hili Heremono, sangele mitou; ba da''ö sa''ae ifa''amöi howu-howu Yehowa, fangorifi, sirugi si lö aetu.', '["MozII 29:7; 30:23–30"]', NULL),
  (3476146, 'OT', 'Sinunö', 134, 1, 'Hiza, misuno Yehowa, ya''ami enoni Yehowa, fefu, si so ba gosali Yehowa andrö, ba zi bongi!', '["Sin 115:15"]', NULL),
  (3476146, 'OT', 'Sinunö', 134, 2, 'Mifazaŵa dangami ba ni''amoni''ö andrö, ba misuno Yehowa!', '["Sin 115:15"]', NULL),
  (3476146, 'OT', 'Sinunö', 134, 3, 'Yamufahowu''ö ndra''ugö Yehowa moroi ba Ziona, Yehowa andrö, samazökhi banua si yaŵa, awö danö.[1]', '["Sin 115:15"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 1, 'Haleluya! Misuno döi Yehowa andrö; misuno, ya''ami enoni Yehowa!', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 2, 'Ya''ami, si soso ba gosali Yehowa andrö; ba golayama gosali andrö, khö Lowalangida!', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 3, 'Misuno Yehowa, me no si sökhi tödö Yehowa andrö; misuno döinia, me no omasiö!', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 4, 'Noa sa ituyu Yakobo andrö Yehowa, no ihalö tana khönia Ndraono Gizeraeli.[1]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 5, 'Noa sa''ae aboto ba dödögu, wa no sebua Yehowa, awö wa italu''i fefu Lowalangi bö''ö So''aya ya''ita andrö.[2]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 6, 'Fefu hadia ia zomasi Yehowa, ba ilau, he ba mbanua si yaŵa ba he ba guli danö, ba he ba nasi ba ba zabakha si tou, fefu.', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 7, 'Solohe miyaŵa lawuo andrö, moroi ba wondrege danö, somböi teu, awö gari mbanua andrö, sanao''ö baero ba zi fahöna ia angi andrö.[3]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 8, 'Samunu mege si a''a ba wa''atumbu andrö, ba danö Miserayi, i''otarai ba niha, numalö ba guriföra.[4]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 9, 'No ifabe''e''ö khöu dandra ba sahöli-höli dödö, ya''ugö tanö Miserayi, ba khö Wara''o andrö ba ba khö ngoni-ngonia, fefu.[5]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 10, 'Sangalani soi, ha wa''oya, ba samunu razo sabölö:', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 11, 'Sihona andrö ba Ogi, razo Mbazana andrö, awö nöri Gana''ana fefu.[6]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 12, 'Ba ibe''e okhöta danöra, okhöta mbanuania Iraono Gizeraeli.[7]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 13, 'He Yehowa, si lö tebulö döimö andrö; götö-götö wa''ara, ba lö olifu niha ndra''ugö, ya''ugö Yehowa![8]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 14, 'I''ohe sa ba lala huhuo mbanuania andrö Yehowa, ba ihakhösi tödö genoninia andrö.[9] [10]', '["MozII 19:5,6; MozV 7:6","Sin 86:8","Yer 10:13","MozII 12:29","Sin 78:43–52","MozIV 21:21–35","Yos 12","Sin 102:13","MozV 32:36,43","Ayati 15–20: Sin 115:4–11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476147, 'OT', 'Sinunö', 135, 15, 'Adu niha baero andrö, ba firö ba ana''a, nifazökhi danga niha.', '["Sin 118:2–4"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 16, 'Mobawa, ba lö muhede; mohörö, ba lö la''ila niha.', '["Sin 118:2–4"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 17, 'Motögi dalinga, ba lö larongo li niha ba lö hanu-hanu ba mbawara.', '["Sin 118:2–4"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 18, 'Ba tobali fagölö-gölö khöra zamazökhi ya''ira, dozi sanötöna khöra hadia ia.', '["Sin 118:2–4"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 19, 'Ya''ami nga''ötö Gizeraeli, misuno Yehowa! Ya''ami nga''ötö Ga''aroni andrö, misuno Yehowa![11]', '["Sin 118:2–4"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 20, 'Ya''ami nga''ötö Lewi andrö, misuno Yehowa! Ya''ami, sangata''ufi Yehowa, misuno Yehowa!', '["Sin 118:2–4"]', NULL),
  (3476147, 'OT', 'Sinunö', 135, 21, 'Nisuno Yehowa moroi ba Ziona, Yehowa andrö, sowanua ba Yeruzalema andrö! Haleluya!', '["Sin 118:2–4"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 1, 'Mi''andrö saoha gölö khö Yehowa, me si sökhi tödö ia; me no si lö aetu wa''ebua dödönia andrö![1]', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 2, 'Mi''andrö saoha gölö khö Lowalangi Lowalangi andrö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 3, 'Mi''andrö saoha gölö khö Zo''aya sokhö andrö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 4, 'Solau sahöli-höli dödö, sebua, ha ya''ia, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 5, 'Samazökhi banua andrö, si yaŵa, fa''atua-tuania; me no si lö aetu wa''ebua dödönia andrö!', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 6, 'Samologö tanö andre, yaŵa nasi, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 7, 'Samazökhi sihaga andrö, sebua andrö me no si lö aetu wa''ebua dödönia andrö![2]', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 8, 'Luo andrö, samatörö si ma''ökhö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 9, 'Ba baŵa, awö ndröfi, samatörö si bongi, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 106:1","MozI 1:14–18"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 10, 'Samunu si a''a ba wa''atumbu andrö, ba danö Miserayi, me no si lö aetu wa''ebua dödönia andrö![3]', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 11, 'Ba sangeheta Iraono Gizeraeli ba khöra, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 12, 'Tangania sabölö andrö ba ta''ionia si no mufadölö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 13, 'Sanaba talu nasi zukhu andrö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 14, 'Samolala Iraono Gizeraeli ba khönia, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 15, 'Si hanigö ba nasi zukhu andrö Fara''o, awö zabölö andrö khönia, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 16, 'Solohe tanga mbanuania andrö, ba danö si mate, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 17, 'Sangalani salaŵa sebua, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 18, 'Samunu salaŵa sabölö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 19, 'Sihona andrö, razo Ndraono Gamori, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 20, 'Ba Ogi, razo Mbazana andrö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 21, 'Ba ibe''e okhöta danöra andrö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 22, 'Okhöta genoninia Iraono Gizeraeli andrö, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 23, 'Sanörö tödö ya''ita ba wa''anumanada, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 24, 'Ba sangefa''ö ya''ita ba danga zamakao ya''ita, me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 25, 'Same''e gö nösi guli danö fefu, me no si lö aetu wa''ebua dödönia andrö![4]', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476148, 'OT', 'Sinunö', 136, 26, 'Misuno Lowalangi zorugo andrö! Me no si lö aetu wa''ebua dödönia andrö!', '["Sin 78:51; 135:8–12","Sin 145:15"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 1, 'Ba mbewe nidanö andrö ba Mbabeli dumadao ndra''aga ba mege-egega, me itörö tödöma Ziona.', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 2, 'Ba ndraha mbou andrö, si so ba danö, masaitagö mbiola andrö khöma.', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 3, 'La''andrö sa khöma wanunö sangoloi''ö ya''aga andrö, ba omasi zamakao ya''aga, na omuso dödöma; lamane: "Milau khöma wanunö Ziona andrö!"', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 4, 'He mawisa malau zinunö andrö khö Yehowa, ba danö zotanö?', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 5, 'Na olifudo ndra''ugö, Yeruzalema, ba ya ombuyu-mbuyu dangagu kambölö.[1]', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 6, 'Ya falemba ba gararogu lelagu andre, na lö itörö tödögu ndra''ugö, na lö ube''e fondrege wa''omuso dödögu Yeruzalema andrö.', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 7, 'He Yehowa, sulöni ba Ndraono Gedomo mbaŵa Yeruzalema andrö, ba zi''ao andrö, wanguma''ö: "Midudugö, midudugö ia, irege doyo gehomo khönia!"[2]', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 8, 'He ya''ugö ono Mbabeli andrö alawe, nidudugö andrö, ya ahowu zanulöni khöu nilaumö khöma!', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476149, 'OT', 'Sinunö', 137, 9, 'Ya ahowu zanutuyu ono sawuyu khöu, ba sorasa högöra ba gara![3]', '["Yer 51:50","Sin 79:12; Obad 10–15","Yes 13:16"]', NULL),
  (3476150, 'OT', 'Sinunö', 138, 1, 'Mangandrö saoha gölö ndra''o khöu, moroi si''aikö ba dödögu, ba zanehe Lowalangi andrö usuno ndra''ugö.', '["Sin 26:8","Yes 2:3","Sin 113:5","Fil 1:6"]', NULL),
  (3476150, 'OT', 'Sinunö', 138, 2, 'Mangalulu ndra''o ba gamaudu gosali andrö khöu, ni''amoni''ö, ba usuno döimö andrö, börö wa''ebua dödöu ba fa lö faröi ndra''ugö, me no ö''ebua''ö gamabu''ula limö andrö, irege italu''i döimö andrö fefu.[1]', '["Sin 26:8","Yes 2:3","Sin 113:5","Fil 1:6"]', NULL),
  (3476150, 'OT', 'Sinunö', 138, 3, 'Me luo mu''ao ndra''o öfondrondrongo ligu; no ö''abe''e''ö dödögu, — no fahöna barö dotogu wa''abölö öbe''e.', '["Sin 26:8","Yes 2:3","Sin 113:5","Fil 1:6"]', NULL),
  (3476150, 'OT', 'Sinunö', 138, 4, 'Sangandrö saoha gölö khöu razo ba guli danö fefu, na no larongo daroma limö andrö.[2]', '["Sin 26:8","Yes 2:3","Sin 113:5","Fil 1:6"]', NULL),
  (3476150, 'OT', 'Sinunö', 138, 5, 'Ba lasuno lala Yehowa andrö, me no ebua lakhömi Yehowa.', '["Sin 26:8","Yes 2:3","Sin 113:5","Fil 1:6"]', NULL),
  (3476150, 'OT', 'Sinunö', 138, 6, 'No salaŵa Yehowa ba i''ila zi numana, ba no aboto ba dödönia zebua hokha, moroi ba zaröu.[3]', '["Sin 26:8","Yes 2:3","Sin 113:5","Fil 1:6"]', NULL),
  (3476150, 'OT', 'Sinunö', 138, 7, 'Na tefasui ndra''o wa''abu dödö ba lalagu andre, ba ö''orifi ndra''odo, ö''oro''ö dangau, fanimba wönu zi fa''udu khögu, ba itolodo kambölöu.', '["Sin 26:8","Yes 2:3","Sin 113:5","Fil 1:6"]', NULL),
  (3476150, 'OT', 'Sinunö', 138, 8, 'Yehowa zangasiwai fefu hadia ia khögu. He Yehowa, si lö aetu wa''ebua dödöu andrö, böi böhöli nifazökhiu tangau![4]', '["Sin 26:8","Yes 2:3","Sin 113:5","Fil 1:6"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 1, 'He Yehowa, ösekhegö ndra''o ba no aboto ba dödöu ndra''odo.[1]', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 2, 'Fedadaogu ba femaosogu, ba ö''ila, ba ösöndra gera-eragu, moroi ba zaröu.[2]', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 3, 'Ötimba tödöu wowaö-waögu ba femörögu, ba no aboto ba dödöu lalagu andrö fefu.', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 4, 'Hiza sa, sambua lö li mbewegu andre, si lö ö''ila manö, ya''ugö Yehowa.', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 5, 'No öfa''u''u ndra''odo, he moroi föna ba he moroi furi, ba no ötufa ndra''o tangau.', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 6, 'Tebai aboto ba dödögu wangila si manö, lö ukhamö — tebai ulaŵa!', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 7, 'Heza usaŵa ba Gehehamö andrö? Heza ubini''ö ndra''odo, ba wamaigiu andrö?', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 8, 'Na möido miyaŵa ba zorugo ena''ö, ba no so ndra''ugö ba da''ö; ba na ba mbanua tou u''alui khögu naha wemörö, ba no so ndra''ugö.[3]', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 9, 'Na uhalö ena''ö afigu gafi wa''amoluo andrö, na ba wondrege nasi u''alui nahiagu,[4]', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 10, 'ba ba da''ö ö''ohe dangagu, ötuyu ndra''o kambölöu.', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 11, 'Ba na umane: Yamubalugö manö ndra''odo fa''ogömi-gömi, ya tobali si bongi haga andrö, si tefasui ya''odo,[5]', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 12, 'ba tenga si töra fa''ogömi-gömi khöu zogömi-gömi andrö, ba humaga zi bongi andrö, si mane si moluo; si mane haga wa''ogömi-gömi andrö.[6]', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 13, 'No ya''ugö zamazökhi buagu andrö, no ya''ugö zomböi ya''odo, ba dalu ninagu.', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 14, 'U''andrö saoha gölö khöu wamazökhiu ya''odo, sahöli-höli dödö, si tobali dödö niha; sahöli-höli dödö wolaumö andrö, ba no aboto sibai ba dödögu.', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 15, 'Tenga si tobini khöu dölagu andre, me tefazökhi ndra''odo, ba zogömi-gömi, me tewöwöi ndra''o, nifomböwöi duka, ba hunö danö.[7]', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 16, 'No i''ila ndra''o höröu, me tanömö niha na ndra''odo, ba no tetanö ba zura khöu mbaŵa andrö fefu, nihonogöi, me sambua lö irugi na.[8]', '["Ayati 23; Sin 7:10","Yer 12:10","Amos 9:2","Yon 1:3","Yob 34:22","Yak 1:17","Sangomb 11:5","Yob 14:5"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 17, 'Ba no sebua sibai böli gera-erau khögu, ya''ugö Lowalangi, soya sibai gahonoania![9]', '["Yer 55:9","Sin 40:6; 63:7","Ayati 1","Sin 27:11"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 18, 'Na u''erai ena''ö, ba no oya, moroi ba ngawua nene; na tokea ndra''odo, ba lö si tebulö ndra''o khöu.[10]', '["Yer 55:9","Sin 40:6; 63:7","Ayati 1","Sin 27:11"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 19, 'Ena''ö na öbunu zanao horö andrö, ya''ugö Lowalangi! Ba sange''enge''e, andrö, ba ena''ö na aheta khögu!', '["Yer 55:9","Sin 40:6; 63:7","Ayati 1","Sin 27:11"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 20, 'Sanandraŵaisi ya''ugö, sanötöi töimö ba waya, si fa''udu khöu andrö.', '["Yer 55:9","Sin 40:6; 63:7","Ayati 1","Sin 27:11"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 21, 'Hadia, alakha lö fatiu dödögu ba zi fatiu tödö khöu, ya''ugö Yehowa? Ba hadia, lö u''ogorofi zolaŵa ya''ugö?', '["Yer 55:9","Sin 40:6; 63:7","Ayati 1","Sin 27:11"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 22, 'Fatiu dödögu khöra, fatiusa si no mo''ahonoa; emali ira khögu.', '["Yer 55:9","Sin 40:6; 63:7","Ayati 1","Sin 27:11"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 23, 'Sekhegö ndra''odo, Lowalangi, ya aboto ba dödöu dödögu andrö; tandraigö ndra''odo, ba ya aboto ba dödöu gera-eragu.[11]', '["Yer 55:9","Sin 40:6; 63:7","Ayati 1","Sin 27:11"]', NULL),
  (3476151, 'OT', 'Sinunö', 139, 24, 'Ba faigi na ba lala saekhu ba wa''afökhö sodo, ba ohe ndra''o ba lala ba zi lö aetu![12]', '["Yer 55:9","Sin 40:6; 63:7","Ayati 1","Sin 27:11"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 1, 'Khö duka wanunö andrö. Sinunö khö Dawido.', '[]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 2, 'Efa''ö ndra''o, Yehowa, ba niha si lö sökhi andrö, timba khögu zamakao ya''odo andrö!', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 3, 'Si no mamakhai tödöra si lö sökhi, si erogö ma''ökhö mangandrö fasöndrata.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 4, 'La''atarösi lelara, timba lela gulö, söfu gulö no so ba mbewera.[1]', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 5, 'Böi lulu ndra''odo ba danga zebua horö, ya''ugö Yehowa, timba khögu zamakao ya''o ena''ö, sangalui folaugö ya''odo.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 6, 'No lalau wesu khögu sebua hokha ba tandraŵa, ba zi tobini, no lafadölö gu''ö ba zinga lala; no lalau mbölödi.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 7, 'No umane khö Yehowa: Lowalangigu ndra''ugö! Fondrondrongo, Yehowa, li wangandrögu![2]', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 8, 'He Yehowa, So''aya ya''o, fangorifigu sabölö, ya''ugö zame''e ba''a-ba''a högögu, na baŵa wasöndrata.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 9, 'Böi o''ö zomasi zebua horö andrö, ya''ugö Yehowa; ena''ö lö fakhai nikhoi dödöra öbe''e.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 10, 'Na maoso zamasui ya''odo andrö, ba yamuhawui ira salakha andrö, ba mbewera.[3]', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 11, 'Ya tehawu ira ba galitö; timba ira ba galitö bakha ba ba gohokoho, si tebai möi ira yaŵa.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 12, 'Lö fozu ba danö niha si so lela fanandraŵa, ba samalangögö awönia, ba igohi famakao, itukotuko.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 13, 'U''ila, wa i''ohe ba lala huhuo zebua famakao Yehowa, awö wa i''ohe ba zatulö hadia ia ba zi numana.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476152, 'OT', 'Sinunö', 140, 14, 'Ba lasuno dania döimö satulö tödö andrö, ba monahia fönau zadölö tödö.', '["Rom 8:13","Sin 22:11","Sin 7:17"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 1, 'He Yehowa, mu''aodo khöu, ta''i-ta''i ondrasido! Fondrondrongo ligu, na u''angaröfi li ndra''ugö!', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 2, 'Akha sumange nifanimbo wangandrögu andre, wamaigiu; ba famazaŵagu tangagu andre, ba akha sumange ni''a, na tanö owi.[1]', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 3, 'Fataro zanaro bawagu, ya''ugö Yehowa, ba faigi-faigi mbawandruhö mbewegu andre.[2]', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 4, 'Böi tehe ihole''ö ia tödögu ba zi lö sökhi, fa ufazökhi horö, awö niha solau si lö atulö; ba ena''ö na lö u''a zami khöra andrö.[3]', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 5, 'Yamubagodo niha satulö, fa''omasinia ndra''odo, yamutegudo, ba fanikha mbugu da''ö, ba böi abua ba högögu; ulau mangandrö na sa, famatimba zi lö sökhi andrö khöra.[4]', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 6, 'Nilau si tou ba zisindro gara ba hili zalaŵara; ba larongo daroma ligu andrö, omasiö.', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 7, 'Hulö na mamaku niha, na lafahufa danö, si manö wamazaewe tölama andrö ba zinga mbawa göli mbanua tou.', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 8, 'Ba ya''ugö sa''ae utöngöni, ya''ugö Yehowa, So''aya ya''o, saŵatögu ndra''ugö, böi tibo''ö nosogu!', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 9, 'Böi lulu ndra''o ba wesu andrö, nilaura khögu; ba ba mbölödi, nilau zamazökhi si lö atulö andrö.', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476153, 'OT', 'Sinunö', 141, 10, 'Hana na alau zebua horö andrö fefu, ba wesu andrö khöra, gasa-gasa wanörögu.[5]', '["MozII 30:7; 29:39","Sin 39:2","Sin 119:36","MozIII 19:17; Amaed 27:5,6","Sin 7:16"]', NULL),
  (3476154, 'OT', 'Sinunö', 142, 1, 'Famahaö; khö Dawido, me so ia ba dögi narö hili andrö. Fangandrö.[1]', '["SamI 24:4"]', NULL),
  (3476154, 'OT', 'Sinunö', 142, 2, 'Mu''aodo khö Yehowa, ebua ligu; ukao khönia, ebua ligu.', '["Sin 138:7","Sin 27:13","Sin 7:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476154, 'OT', 'Sinunö', 142, 3, 'Ubokai khönia zabu dödögu, safökhö khögu u''ombakha''ö khönia.', '["Sin 138:7","Sin 27:13","Sin 7:2"]', NULL),
  (3476154, 'OT', 'Sinunö', 142, 4, 'Na no erege bakha dödögu, ba ya''ugö zangila lalagu andrö. No lalau wesu khögu, nibini''ö, ba lala andrö nitörögu.[2]', '["Sin 138:7","Sin 27:13","Sin 7:2"]', NULL),
  (3476154, 'OT', 'Sinunö', 142, 5, 'Hole''ö ba gambölö höröu, ba faigi: samösa lö sangila ya''odo; lö''ö manö saŵatögu; samösa lö sanofu ya''odo.', '["Sin 138:7","Sin 27:13","Sin 7:2"]', NULL),
  (3476154, 'OT', 'Sinunö', 142, 6, 'Mu''aodo khöu, ya''ugö Yehowa, umane: Saŵatögu ndra''ugö, urakhagu ba danö niha sauri.[3]', '["Sin 138:7","Sin 27:13","Sin 7:2"]', NULL),
  (3476154, 'OT', 'Sinunö', 142, 7, 'Fondrondrongo wangarö-ngarögu; noa sa erege sibai dödögu; efa''ö ndra''o ba danga zolohi ya''odo andrö, me tebai ulaŵa ira![4]', '["Sin 138:7","Sin 27:13","Sin 7:2"]', NULL),
  (3476154, 'OT', 'Sinunö', 142, 8, 'Heta ba gurunga andrö nosogu, ena''ö usuno döimö andrö! Lafasui dania ndra''odo satulö tödö, na öfatörö khögu zi sökhi.', '["Sin 138:7","Sin 27:13","Sin 7:2"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 1, 'He Yehowa, fondrondrongo wangandrögu, be''e mbörö dalingau ba wakaosagu andre! Ba wa lö faröi ndra''ugö fondrondrongo khögu, ba wa''atulömö andrö.', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 2, 'Ba böi ohe ba huku genonimö andre, lö''ö sa satulö fönau, niha sauri.[1]', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 3, 'Noa sa igohi ndra''odo si fatiu tödö andrö, no ihundragö tou ba danö nosogu, no ifaförö ndra''o ba zogömi-gömi sibai, si mane si mate ba götö föna andrö.', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 4, 'Ba no ariri bakha dödögu, no oköli dödögu, barö dotogu.', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 5, 'Itörö tödögu götö föna andrö, u''alu-alui tödögu wolaumö andrö fefu, ufatou-tou tödögu, halöŵö dangau andrö.[2]', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 6, 'U''oro''ö dangagu khöu, humulu bakha dödögu khöu, hulö danö soköli.[3]', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 7, 'Ta''i-ta''i fondrondrongo khögu, ya''ugö Yehowa! Humulu dödögu: Böi bini''ö khögu mbawau, fa böi fagölö-gölö ndra''odo ba zilalö mitou ba gohokoho.[4]', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 8, 'Hulö wongi farongogö khögu wa''ebua dödöu andrö, udöna-döna sa''ae khöu; oroma''ö khögu lala andrö, nitörögu, khöu sa''ae ufazaŵa dödögu!', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 9, 'Efa''ö ndra''o ba danga zi fatiu tödö khögu, ya''ugö Yehowa! Khöu usaŵa.', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 10, 'Fahaö ndra''o ba wolo''ö somasi ndra''ugö, Lowalangigu sa ndra''ugö; yamu''ohe dangagu Ehehamö si sökhi andrö, ba lala sadölö![5]', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 11, 'Ba döimö andrö, ya''ugö Yehowa, orifi ndra''odo; ba wa''atulömö andrö efa''ö dödögu ba wa''abu dödö andrö![6]', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476155, 'OT', 'Sinunö', 143, 12, 'Ba hori zi fatiu tödö khögu, ba wa''ebua dödöu andrö, ba fakiko zamakao ya''odo fefu, me no enoniu ndra''odo![7]', '["Sin 130:3; Yob 9:2","Sin 77:6","Sin 42:2,3; 63:2","Sin 28:1","Sin 25:5","Sin 23:3; 119:25","Sin 116:16"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 1, 'Nisuno Yehowa, we''e-we''e dödögu andrö, samahaö tangagu ba wanuwö ba tuturugu ba wasöndrata.[1]', '["Sin 18:35","Sin 18:3","Sin 8:5","Yob 14:2","Sin 18:10; 104:32","Ayati 11"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 2, 'Fangabe''egu, ba hili khögu, hatigu, ba sangorifi, ya''odo, balusegu ba tötönafögu, same''e barö mbawagu banuagu andrö.[2]', '["Sin 18:35","Sin 18:3","Sin 8:5","Yob 14:2","Sin 18:10; 104:32","Ayati 11"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 3, 'He Yehowa, hadia niha andrö, wa öbe''e ba dödöu, ba hadia nono niha, wa öfaigi ia?[3]', '["Sin 18:35","Sin 18:3","Sin 8:5","Yob 14:2","Sin 18:10; 104:32","Ayati 11"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 4, 'Hulö nangi niha, ba hulö lumö sanörö mbaŵania andrö.[4]', '["Sin 18:35","Sin 18:3","Sin 8:5","Yob 14:2","Sin 18:10; 104:32","Ayati 11"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 5, 'He Yehowa, dada mbanua si yaŵa andrö khöu ba ae mitou; babaya hili andrö, ba manimbo![5]', '["Sin 18:35","Sin 18:3","Sin 8:5","Yob 14:2","Sin 18:10; 104:32","Ayati 11"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 6, 'Lau gari mbanua ba fazawili ira; efasi nono wana andrö khöu, ba wameta''u ya''ira!', '["Sin 18:35","Sin 18:3","Sin 8:5","Yob 14:2","Sin 18:10; 104:32","Ayati 11"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 7, 'Oro''ö dangau moroi si yaŵa; söbido moroi ba nidanö sebua ba orifido; efa''ö ndra''o ba danga nono niha bö''ö andrö.', '["Sin 18:35","Sin 18:3","Sin 8:5","Yob 14:2","Sin 18:10; 104:32","Ayati 11"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 8, 'Niha solau faya bewera, ba kambölöra, ba no kambölö si falimo.[6]', '["Sin 18:35","Sin 18:3","Sin 8:5","Yob 14:2","Sin 18:10; 104:32","Ayati 11"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 9, 'He Lowalangi, ulau khöu zinunö si bohou; ulau khöu mbiola nitika andrö, si fulu sinali.[7]', '["Sin 33:2,3","Ayati 8","Sin 128:3","MozV 33:29"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 10, 'Khöu, sangabölö''ö razo, sangefa''ö enoninia Dawido ba mbawa zi''öli famunu andrö.', '["Sin 33:2,3","Ayati 8","Sin 128:3","MozV 33:29"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 11, 'Fadönidö, efa''ö ndra''odo ba danga nono niha bö''ö andrö; niha solau faya bewera, ba kambölöra, ba no kambölö si falimo.[8]', '["Sin 33:2,3","Ayati 8","Sin 128:3","MozV 33:29"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 12, 'Ena''ö hulö zinanö nihaogö fange''ebua nono matua khöma, gasa-gasa wa''amo''ahonoa wa''ebua; ba ono alawe andrö khöma, ba ena''ö hulö daru nahe nifoe andrö, taru nahe ba gödo.[9]', '["Sin 33:2,3","Ayati 8","Sin 128:3","MozV 33:29"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 13, 'Ena''ö mo''ösi halasama, naha ngawalö mbalazo; ya mo''ono mbiri-birima andrö, ba ngahönö, ba ngafulu ngahönö, ba mbenuama.', '["Sin 33:2,3","Ayati 8","Sin 128:3","MozV 33:29"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 14, 'Ya abeto zigelo zaŵima — böi ya atöla göli ba böi falukha wa''atu''a [nemali]; böi ya terongo wangarö-ngarö ba newalima.', '["Sin 33:2,3","Ayati 8","Sin 128:3","MozV 33:29"]', NULL),
  (3476156, 'OT', 'Sinunö', 144, 15, 'Ya ahowu soi andrö, si falukha si manö! Ya ahowu soi andrö, si möi Lowalangi Yehowa andrö![10]', '["Sin 33:2,3","Ayati 8","Sin 128:3","MozV 33:29"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 1, 'Da''ufarongogö duriamö andrö, ya''ugö Lowalangigu, razo; ba lö ubulö''ö wanuno töimö andrö, irugi zi lö aetu!', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 2, 'U''erogö ma''ökhö wanuno ya''ugö, irugi zi lö aetu lö ubulö''ö wanuno töimö andrö!', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 3, 'Sebua Yehowa ba niforege fanuno, ba tebai isöndra tödö niha wa''ebuania andrö.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 4, 'Yamusuno si sagötö niha halöŵömö andrö, ba zi sagötö, ndramu''ombakha''ö wolaumö andrö, folau zabölö."', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 5, 'Da''udunö-dunö lakhömi wa''asalaŵamö andrö, soadu andrö, awö zahöli-höli dödö andrö khöu.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 6, 'Ba ndramufatunö wa''abölö walaumö andrö, sata''u niha, ba halöŵöu sebua andrö, ba ya''odo zamatunö.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 7, 'Ndramufalua baero wamasugi ba dödö fa''ebua dödöu andrö, si no fahöna, ba ya owua-wua dödöra ba wa''atulömö andrö.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 8, 'Sebua tödö Yehowa ba sahakhö tödö, ebolo dödönia ba no fahöna wa''asökhi dödö.[1]', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 9, 'Idozigö niha wangebua tödönia khöra, ba irugi niwöwöinia fefu fa''ahakhö dödönia andrö.[2]', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 10, 'Lasuno ndra''ugö Yehowa, fefu niwöwöimö andrö, ba satulö tödö andrö khöu, ba manunö khöu.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 11, 'Lafatunö lakhömi wa''asalaŵamö andrö, ba itörö lira wa''abölöu.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 12, 'Ba wame''e ba dödö niha folaumö andrö, folau zabölö, awö wa''ebua lakhömi wa''asalaŵamö andrö.[3]', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 13, 'Amatöröŵau andrö, ba no amatöröŵa si lö tebulö, irugi zi lö aetu, ba famatöröu andrö, ba no si götö-götö fa''ara.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 14, 'Ituwu Yehowa fefu zalau ena''ö, ba ifaöga fefu zi no aöndrö.[4]', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 15, 'Dozi hörö niha manötöna khöu, ba öbe''e göra na inötö.[5]', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 16, 'Obokai dangau ba ö''abusoi''ö fefu zauri somasi ira.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 17, 'Satulö Yehowa, ba lala andrö khönia fefu, ba sebua tödö, ba wolaunia, fefu.[6]', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 18, 'No ahatö Yehowa, ba zi angaröfi li ya''ia, fefu, ba zi angaröfi li ya''ia soroi ba dödö.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 19, 'I''o''ö zomasi zangata''ufi ya''ia, ifondrondrongo we''aora ba itolo.[7]', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 20, 'Irorogö Yehowa zangomasi''ö ya''ia, fefu, ba dozi sebua horö andrö, ba ihori ba danö.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476157, 'OT', 'Sinunö', 145, 21, 'Ba yamufarongogö wanuno Yehowa bewegu andre ba yamusuno döinia ni''amoni''ö andrö ösi guli danö, fefu, si lö mamalö-malö ba sirugi si lö aetu.', '["MozII 34:6","Rom 11:32","Ayati 5","Sin 146:8; Luk 1:52","Sin 104:27,28; 136:25","MozV 32:4","Amaed 10:24"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 1, 'Haleluya, suno Yehowa, ya''ugö tödögu!', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 2, 'Da''usuno Yehowa, götö wa''anau nosogu: ba manunödo khö Lowalangi, götö wa''ara ndra''odo ba guli danö.', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 3, 'Böi midöna-döna ba zalaŵa, ono niha, si lö fangorifi.[1]', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 4, 'Na aetu nosonia, ba ifuli tobali tanö; na luo da''ö, ba awai nikhoi dödönia.[2]', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 5, 'Ya ahowu ba zi no möi sangorifi Lowalangi Yakobo andrö, sanötöna khö Lowalanginia Yehowa,', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 6, 'samazökhi banua, awö danö, ba asi, awö nösinia andrö fefu; si lö faröi ia, irugi zi lö aetu.', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 7, 'Solohe ba lala huhuo nifalangögö andrö, same''e gö ba zolofo; i''efa''ö nikuru andrö Yehowa.', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 8, 'Yehowa zamokai hörö zau''a andrö; Yehowa zamaöga si no aöndrö; i''omasi''ö zatulö tödö Yehowa.[3]', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 9, 'Irorogö zi fatewu andrö Yehowa; itolo zi lö ama, si lö ina, awö lakha mbanua andrö; ba sebua horö andrö, ba i''ohe ba lala elungua.[4]', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476158, 'OT', 'Sinunö', 146, 10, 'Razo Yehowa, irugi zi lö aetu, Lowalangiu andrö, ya''ugö Siona, götö-götö wa''ara. Haleluya![5]', '["Sin 118:8,9; Yer 17:5","MozI 3:19; Sangomb 12:7","Sin 145:14","MozII 22:20,21; Sin 10:14; 68:6","Sin 93:1"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 1, 'Haleluya! Misuno Yehowa, me si sökhi wanunö andrö khö Lowalangida, me omasiö; si nangea wanunö andrö.[1]', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 2, 'Ifuli itaru''ö Yeruzalema andrö Yehowa; i''ozaragö Ndraono Gizeraeli andrö, nifazawili.', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 3, 'Ya''ia andrö, sangebe''e''ö si no arasa tödö andrö, sodalu-daluni safökhö khöra.', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 4, 'Sangerai ha wa''oya ndröfi andrö, sanötöi töira fefu.[2]', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 5, 'No ebua Zo''aya ya''ita andrö, ba no fahöna wa''abölö khönia: no si lö fondrege wa''aboto ba dödönia andrö.', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 6, 'I''abe''e''ö nifakao andrö Yehowa ba ihöndrögö zebua horö, irugi danö tou.[3]', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 7, 'Mi''anunö khö Yehowa, ya fao wangandrö saoha gölö; misuno Lowalangida, wolau biola nitika andrö side-ide!', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 8, 'Sangalu banua lawuo, same''e teu ba danö, samatumbu''ö du''u ba hili.', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 9, 'Same''e gö ba gurifö niha andrö ba ba nono gaga andrö, si''ao khönia.[4]', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 10, 'Tenga somasi ia wa''abölö kudo, ba lö ba dödönia wa''esolo waha niha.', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 11, 'Somasi Yehowa, ba sangata''ufi ya''ia, sanötöna fa''ebua dödönia andrö.', '["Sin 92:2","Yes 40:26","Luk 1:52","Yob 38:41"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 12, 'Suno Yehowa, ya''ugö Yeruzalema; suno Lowalangimö andrö, ya''ugö Siona!', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 13, 'Ya''ia zangaro lazi andrö ba mbawa göli khöu, ba samahowu''ö iraono baewali khömö.', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 14, 'Lö ifa''amöi ba danöu zanuwö, i''abusoi''ö ndra''ugö fakhe si sökhi.[5]', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 15, 'Ifa''ema ba danö goroisania; si fagohi daroma linia andrö.', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 16, 'Ilau deu si baku andrö, hulö mbu mbiri-biri, ba ilau namo sabe''e, hulö nawu.[6]', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 17, 'Ilau si tou deu kara andrö, fa''ebua zi samba-sambawa; ha niha zanaha fa''oafu andrö khönia?', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 18, 'Ba ilau linia, ba mangulu ibe''e; ifatörö nangi andrö khönia, ba mangele nidanö.', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 19, 'Ifarongogö khö Yakobo daroma linia ba khö Gizeraeli gamakhoitania, awö lala andrö khönia.', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476159, 'OT', 'Sinunö', 147, 20, 'Ba niha bö''ö, ba lö nilaunia si manö; ba lala andrö khönia, ba lö la''ila. Haleluya![7]', '["Sin 81:17","Sin 148:9; Yob 38:22–30","MozV 4:7; HalZin 14:16; Rom 3:2"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 1, 'Haleluya! Misuno Yehowa, moroi ba mbanua si yaŵa, misuno ia ba zalaŵa yaŵa!', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 2, 'Misuno ia, ya''ami mala''ika khönia fefu; misuno ia, ya''ami, sabölö khönia, dozi![1]', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 3, 'Misuno ia, ya''ugö luo ba ya''ugö baŵa; misuno ia, ya''ami döfi sihaga andrö, fefu.', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 4, 'Misuno ia, ya''ami fondrege mbanua si yaŵa ba ya''ami idanö, si so yaŵa mbanua si yaŵa andrö!', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 5, 'Ndramusuno döi Yehowa andrö; me no börö niŵa''önia, wa tefazökhi ira.[2]', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 6, 'Ba no ihonogöi naha khöra, si lö tebulö; no ifakhoi lala, si tebai lasawö.', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 7, 'Misuno Yehowa, moroi ba guli danö; ya''ami saliŵa-liŵa ba nasi, awö zabakha si tou andrö, fefu!', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 8, 'Ya''ami alitö ba teu kara ba teu si baku ba simbo, ba angi sabölö andrö, samalua niŵa''önia andrö.', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 9, 'Hili andrö, ba hili-hili fefu, eu sowua andrö, ba eresi fefu;', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 10, 'saliŵa-liŵa ba danö ba urifö niha, fefu, ba kuö-kuö ba fofo andrö sihombo;', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 11, 'razo ba guli danö, awö soi niha fefu, samatörö niha ba sanguhuku ba guli danö, fefu.', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 12, 'Ono matua ba ono alawe ba satua ba iraono.', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 13, 'Ndramusuno döi Yehowa, me no ha töinia zebua: italu''i danö ba italu''i mbanua si yaŵa lakhöminia andrö!', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476160, 'OT', 'Sinunö', 148, 14, 'Ba no i''alaŵa''ö dandru andrö ba mbanuania, fanuno satulö tödö andrö khönia, fefu, Iraono Gizeraeli andrö, banua sahatö khönia. Haleluya."[3]', '["Sin 103:20–22","Sin 33:9","Sin 132:17"]', NULL),
  (3476161, 'OT', 'Sinunö', 149, 1, 'Haleluya! Milau khö Yehowa zinunö si bohou; nisuno ia ba mbanua satulö tödö andrö![1]', '["Sin 96:1","Sin 100:3; 93:1"]', NULL),
  (3476161, 'OT', 'Sinunö', 149, 2, 'Ya omuso dödö Ndraono Gizeraeli zomböi ya''ia andrö, ya owua-wua dödö nono matua Ziona razora andrö.[2]', '["Sin 96:1","Sin 100:3; 93:1"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476161, 'OT', 'Sinunö', 149, 3, 'Ndramusuno döinia andrö, ba wolaya, ndramanunö khönia wamözi aramba, awö wolau biola nitika andrö sebua!', '["Sin 96:1","Sin 100:3; 93:1"]', NULL),
  (3476161, 'OT', 'Sinunö', 149, 4, 'Me no i''omasi''ö mbanuania andrö Yehowa; ifoadu fangorifi zebua famakao andrö.', '["Sin 96:1","Sin 100:3; 93:1"]', NULL),
  (3476161, 'OT', 'Sinunö', 149, 5, 'Ya owua-wua dödö zatulö tödö ba lakhömi andrö, ndrama''iki ba gasora tou.', '["Sin 96:1","Sin 100:3; 93:1"]', NULL),
  (3476161, 'OT', 'Sinunö', 149, 6, 'Fanuno Lowalangi ba mbewera ba gari si faoma bawa ba dangara.', '["Sin 96:1","Sin 100:3; 93:1"]', NULL),
  (3476161, 'OT', 'Sinunö', 149, 7, 'Ba wolau balö ba niha baero ba ba wangotu''ö soi bö''ö.', '["Sin 96:1","Sin 100:3; 93:1"]', NULL),
  (3476161, 'OT', 'Sinunö', 149, 8, 'Ba worate razora ba ba wokalo si''öli si so töi khöra.', '["Sin 96:1","Sin 100:3; 93:1"]', NULL),
  (3476161, 'OT', 'Sinunö', 149, 9, 'Ba wamatörö khöra huku andrö, si so ba zura; tobali lakhömi zatulö tödö andrö khönia, fefu, zi manö. Haleluya!', '["Sin 96:1","Sin 100:3; 93:1"]', NULL),
  (3476162, 'OT', 'Sinunö', 150, 1, 'Haleluya! Misuno Lowalangi ba ni''amoni''ö andrö khönia! Misuno ia ba hati saro andrö khönia!', '["Sin 41:14; Fam 5:13"]', NULL),
  (3476162, 'OT', 'Sinunö', 150, 2, 'Misuno ia ba wolaunia andrö, nifolau zabölö! Misuno ia, dali wa''afahöna wa''asalaŵania andrö!', '["Sin 41:14; Fam 5:13"]', NULL),
  (3476162, 'OT', 'Sinunö', 150, 3, 'Misuno ia, milau dorofe! Misuno ia, milau mbiola nitika, sebua, awö mbiola nitika, side-ide!', '["Sin 41:14; Fam 5:13"]', NULL),
  (3476162, 'OT', 'Sinunö', 150, 4, 'Misuno ia, mibözi garamba ba mi''olaya! Misuno ia, milau mbiola nidekha ba mifao zurune!', '["Sin 41:14; Fam 5:13"]', NULL),
  (3476162, 'OT', 'Sinunö', 150, 5, 'Misuno ia, mibözi waritia si sökhi li! Misuno ia, mibözi waritia sebua li!', '["Sin 41:14; Fam 5:13"]', NULL),
  (3476162, 'OT', 'Sinunö', 150, 6, 'Fefu zi so hanu-hanu, ba ndramusuno Yehowa! Haleluya![1]', '["Sin 41:14; Fam 5:13"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 1, 'Amaedola khö Zelomo, ono Dawido, razo Ndraono Gizeraeli.[1]', '["RazI 5:9-12","Faigi 9:10; Sin 111:10; Yob 28:28"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 2, 'Ena''ö tesöndra wa''atua-tua ba fangenanö, ena''ö aboto ba dödö huhuo zatua-tua', '["RazI 5:9-12","Faigi 9:10; Sin 111:10; Yob 28:28"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 3, 'Ena''ö latema wotu, fangatua-tua, ba fa''atulö ba fa''adölö ba fanörö lala si sökhi.', '["RazI 5:9-12","Faigi 9:10; Sin 111:10; Yob 28:28"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 4, 'Ena''ö lasöndra wa''aboto ba dödö si lö mangila watahögö na, ba ena''ö atua-tua nono matua ba ena''ö motödö.', '["RazI 5:9-12","Faigi 9:10; Sin 111:10; Yob 28:28"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 5, 'Na ifondrondrongo satua-tua, ba tedou wa''aboto ba dödönia, ba si no motödö, ba isöndra lala sadölö,', '["RazI 5:9-12","Faigi 9:10; Sin 111:10; Yob 28:28"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 6, 'fa aboto ba dödönia gamaedola side-ide ba amaedola sebua, awö daroma li zatua-tua, awö dahö-dahö andrö khöra.', '["RazI 5:9-12","Faigi 9:10; Sin 111:10; Yob 28:28"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 7, 'Fangata''ufi Yehowa mböröta wa''aboto ba dödö, ba ba zambö tödö, ba lö ba dödö wa''atua-tua ba he fotu.[2]', '["RazI 5:9-12","Faigi 9:10; Sin 111:10; Yob 28:28"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 8, 'Fondrondrongo, onogu, wamangalama namau, ba böi ositengagö wamahaö ninau andrö.[3]', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 9, 'Saembu omasiö sa''ae da''ö ba högöu ba hulö nifatali ba mbagiu.[4]', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 10, 'He onogu! Na ladönisi ndra''ugö samazökhi si lö sokhi, ba böi o''ö.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 11, 'Na lamane: "Tabu, datatarogö zadölö tödö, ba tafagönaisi zi lö horö, lö börö-börö.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 12, 'Tatölö auri ira, si mane banua tou, ba si lö horö, ba si mane silalö mitou ba goho-koho.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 13, 'Ba tasöndra ngawalö gana''a si sökhi; ba tafo''ösi nomoda nirabu andrö.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 14, 'Fagölö-gölö dania gurakhada; ha sambua mbolada, ya''ita fefu."', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 15, 'Ba ya''ugö, onogu, ba böi fao ndra''ugö khöra; böi hundragö lalara andrö.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 16, 'Ba zi lö sökhi lasaŵa; aösö ira wamunu niha.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 17, 'Zaya-zaya gölö sa, na lalau gu''ö ba zanehe wofo fefu.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 18, 'Ya''ira, ba la''alui wamunura, la''alui lala wangetu''ö nosora.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 19, 'Da''ö lalara, dozi ira, sangisö ana''a; ibunu ira fangisöra andrö.', '["Faigi 6:20","Faigi 4:9"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 20, 'Mu''ao wa''atua-tua baewali, ifarongogö linia ba golayama.', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 21, 'Ba zinga misa, ba zato niha baolayama, mu''ao ia; ba mbawa göli ba mbanua fahuhuo ia, imane:[5]', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 22, '"He ya''ami, si lö tödö, ha wa''ara tö na omasi ami walötödö andrö? Ba ha wa''ara na omasi zango''aya wango''aya andrö, ba ha wa''ara na fa''udu zambö tödö ba wa''aboto ba dödö?', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 23, 'Mi''otahögö wotu andrö khögu! Hiza, ufalua khömi Gehehagu; aboto ba dödömi daroma ligu ube''e.', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 24, 'Me no mu''ao ndra''o, ba me tekhömi, me no u''oro''ö dangagu, ba me lö same''e ba dödö.[6]', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 25, 'Me no mi''ositengagö sa''ae wamolalagu tödömi, fefu, ba me lö ni''o''ömi fotu andrö khögu.', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 26, 'Ba ma''iki göi ndra''odo, na göna ami famakiko, u''o''aya ami, na itörö ami ameta''uö.[7]', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 27, 'Na itörö ami sata''u ami, hulö deu laöhö, ba na so moroi sa wamakikomi, hulö nangi sabölö, na ihawui ami famakao ba fa''atosasa.', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 28, 'Awena dania la''angaröfi li ndra''o, ba lö utema lira; la''alui ndra''o, ba lö lasöndrado.[8]', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 29, 'Börö me no fatuwu khöra wa''aboto ba dödö, ba me lö nitehera fangata''ufi Yehowa.', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 30, 'Lö edöna ira mege wamolalagu tödöra, ba no la''ositengagö wotu andrö khögu, fefu.', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 31, 'Andrö la''a dania lua-lua nitöröra andrö, ba abuso ira nikhoi dödöra andrö.[9]', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 32, 'Famunu zowöhö-wöhö andrö wanandrora, ba famakiko zambö tödö wa lö ba dödö andrö khöra.[10]', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405236, 'OT', 'Amaedola Zelomo', 1, 33, 'Ba ha niha zamondrongo khögu, ba ahono ba danö, ba lö abu dödö; lö fa''ataunia wamakiko.[11]', '["Faigi 8:1","Yes 65:2-12","Faigi 3:34","Yes 59:2; Mikh 3:4","Yes 3:10-11","Faigi 8:36","Faigi 8:34"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 1, 'He onogu, na ötehe huhuogu ba na ötanö ba dödöu goroisagu,', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 2, 'fa öbe''e mbörö dalingau ba wa''atua-tua, fa aolo dödöu ba wangera-ngera.', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 3, 'Na ökaoni wa''aboto ba dödö, na öfahede wangila watahögö;[1]', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 4, 'na ögohi ia, nifolohi firö; na ö''alui nifangalu-ngalui girö-girö si no tobini —', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 5, 'Awena dania aboto ba dödöu wangata''ufi Yehowa andrö, ba awena ösöndra wa ö''ila watahögö Lowalangi.', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 6, 'Yehowa sa zame''e fa''atua-tua, ba mbawania alua wa''aboto ba dödö, awö gera-era dödö.', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 7, 'No ibe''e yaŵa wangorifi khö zadölö tödö, irorogö zanörö lala si sökhi.[2]', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 8, 'Ena''ö lö tebulö ira ba lala satulö ibe''e, ba itimba zi lö sökhi ba lala zatulö tödö andrö khönia.', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 9, 'Awena dania aboto ba dödöu hadia zatulö ba hadia lala, awö wa''adölö, awö fefu zinörö si sökhi.', '["Yak 1:5","Sangomb 7:29"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 10, 'Na no möi ba dödöu wa''atua-tua ba na omasiö dödöu wa''aboto ba dödö andrö.', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 11, 'Ba ba''a-ba''a zi lö sökhi khöu wangenanö andrö ba sondrorogö ya''ugö gera-era dödö,', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 12, 'ba wangefa''ö ya''ugö ba lala si lö sökhi andrö, ba niha solau huhuo sabila,', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 13, 'ba zondroi lala sadölö andrö, wanörö lala sogömi-gömi,', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 14, 'somuso tödö ba wamazökhi si lö zökhi, ba sa''iki ba zabila,', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 15, 'somasi lala sabila, ba sanörö lala elungua.', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 16, 'Itimba khöu fa''atua-tua andrö ndra alawe bö''ö andrö, ira alawe baero, salösö lela.[3]', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 17, 'Si no fabali khö zi fahuwu khönia, me ono alawe ia, ba si no olifu wawu''usa li andrö, khö Lowalanginia.', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 18, 'Omonia ba no aolo ba wa''atekiko, ba ba mbanua niha tou aekhu lalania andrö.[4]', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 19, 'Dozi si möi khönia yomo, ba lö mangawuli; ba lö''ö sa''ae lasöndra lala wangorifi.', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 20, 'Ena''ö ötörö lala niha si sökhi; böi hole''ögö moroi ba lala zatulö tödö.', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405237, 'OT', 'Amaedola Zelomo', 2, 21, 'Satulö sa zi so ba danö dania, ba si lö horö zi tosai ba danö.[5]', '["Faigi 6:24; 7:5","Faigi 5:5–6","Sin 37:9–29; Mat 5:5","Sin 37:10–22"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 1, 'He onogu, böi olifugö''ö goroisagu andrö, ba tanö ba dödö nifakhoigu.', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 2, 'Ya''ia sa zame''e fahöna khöu wa''anau noso, noso ba ndröfi ba fa''ohahau dödö![1]', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 3, 'Fa böi aefa khöu wa''omasi ba fa lö faröi; be''e aya ba mbagi khöu, ba ba naha zura ba dödöu tanö ia.[2]', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 4, 'Ba ösöndra wa''ebua dödö ba fa''afaduhu dödö, ba Lowalangi ba ba niha.[3]', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 5, 'Döna-döna khö Yehowa, moroi si''aikö ba dödöu, ba böi abe''e dödöu ba wa''onekheu.', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 6, 'Böi aefa dödöu khönia, gofu hadia ia lala khöu, ba ya''ia zangadölö töröŵau.', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 7, 'Böi bali satua-tua ndra''ugö: ata''ufi Yehowa ba aröu''ögö ba zi lö sökhi.[4]', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 8, 'Da''ö wangabe''e nösiu ba fangokafu dölamö.[5]', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 9, 'Fosumange Yehowa ana''au andrö ba si a''a nisöndra fefu.[6]', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 10, 'Ba fahöna dania nösi halasamö ba falawu agu wolazi andrö khöu.', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 11, 'He onogu, böi ositengagö wotu khö Yehowa, ba böi fatuwu khöu wanegunia.[7]', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 12, 'Somasi Yehowa sa, ba i''otu''ö, ba ba nono sebua dödönia, ba ifatörö zafökhö.[8]', '["Faigi 4:10; MozIII 18:5","Faigi 6:21; 7:3; MozV 6:8; Yer 31:33","Luk 2:52","Yes 5:21","Faigi 4:22","MozII 23:19","Yob 5:17–19; Heb 12:5–6","Fam 3:19"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 13, 'Ya''ahowu zanöndra fa''atua-tua, awö niha sogamö fa''aboto ba dödö.[9]', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 14, 'Fanöndra ya''ia, ba no tohude moroi ba wanöndra firö, ba hare ba khönia, ba italu''i gana''a.[10]', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 15, 'Si sökhi moroi ba mani-mani ia, ba fefu ngawalö mbarasi khöu, ba lö fagölö-gölö khönia.[11]', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 16, 'Ba dangania kambölö, ba fa''anau noso ba ba dangania kabera, ba ana''a ba fa''ebua döi.[12]', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 17, 'Lalania andrö, ba no lala omasiö, ba fefu döröŵa andrö khönia, ba ba wa''ohahau dödö aekhu.', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 18, 'Eu sowua fangorifi ia, ba zi olembai ya''ia, ba ya''ahowu zi lö mamöhöi.', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 19, 'Fa''atua-tua mege wolata danö khö Yehowa, ba era-era dödö khönia wamazökhi mbanua si yaŵa.[13]', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 20, 'Era-erania wamabali nidanö, ba mowöi namo, moroi yaŵa ba lawuo.', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 21, 'He onogu, böi aefa-aefa ia ba duduma höröu, böi böhöli wa''aboto ba dödö ba fangila watahögö.', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 22, 'Ba tobali fangorifiu ba aya ba mbagiu.[14]', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 23, 'Awena dania ötörö lalamö, lö hadia ia, ba lö manendre''ö.', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 24, 'Na öleagö tou ndra''ugö, ba lö si tokea''ö, ba na mörö''ö, ba si sökhi wemöröu.[15]', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 25, 'Lö ameta''uö si tobali dödöu, ba lö ata''u''ö wamakiko sebua horö andrö na itörö.', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 26, 'Tötönaföu sa Yehowa, ya''ia zamatörö aheu, fa böi alau ba gu''ö.[16]', '["Mat 13:44","Faigi 8:10–19","Mat 13:45–46","Ayati 2","Faigi 8:24–30","Faigi 1:9","Sin 3:6; 4:9","Faigi 10:29"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 27, 'Böi abua gölöu wanolo si numana, na ö''ila ötolo.', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 28, 'Böi ŵa''ö khö nawöu: "Ae''e ua, ba fuli''ö khögu, mahemolu ube''e khöu"; me no so khöu.', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 29, 'Böi fakhai zi lö sökhi khö nawöu, si no ahono-hono ba ngaiu.', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 30, 'Böi fasosoni niha, si lö börö-börö, na lö horönia khöu.', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 31, 'Böi afökhöi tödö zamalangögö awönia, ba sara böi omasi ndra''ugö lalania andrö.', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 32, 'Ni''ogorofi Yehowa sa''ae zanörö lala elungua; ba si fahuwu ia ba zadölö tödö.[17]', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 33, 'Göna fangelifi Yehowa nomo zebua horö, ba nahia zatulö tödö, ba ifahowu''ö.', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3405244, 'OT', 'Amaedola Zelomo', 3, 34, 'I''o''aya zango''aya, ba ba zangide-ide''ö ya''ira, ba i''ebua''ö dödönia.', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL),
  (3405244, 'OT', 'Amaedola Zelomo', 3, 35, 'Sumange lasöndra satua-tua, ba sambö era-era, ba lalu''i wa''aila.[18]', '["Sin 25:14","Faigi 1:26; FetI 5:5"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 1, 'Mifondrondrongo, ya''ami ono matua, wamangelama nama, mitöngöni, ena''ö misöndra wa''aboto ba dödö.', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 2, 'Famahaö si sökhi sa ulau khömi, böi olifu ami goroisagu.', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 3, 'Me iraono na ndra''o khö namagu, ono si lö abölö na, si ha sambu-sambua, rorogöfö ninagu,', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 4, 'ba ifahaö ndra''o amagu, imane khögu: "Tanö ba dödöu daroma ligu: böi olifugö''ö goroisagu, ba auri ndra''ugö![1].', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 5, 'Alui wa''atua-tua; alui wa''aboto ba dödö; böi olifu''ö huhuogu andre, ba böi böhöli![2].', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 6, 'Böi aefa ia ba dödöu, ba irorogö ndra''ugö; omasi''ö, ba itimba khöu zi lö sökhi.', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 7, 'Da''ö mböröta wa''atua-tua: Alui wa''atua-tua ba alui wa''aboto ba dödö; be''e bölinia fefu hadia ia zi so khöu.', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 8, 'Ya ebua ba dödöu ia, ba ibali''ö salaŵa ndra''ugö; ebua döimö ibe''e, na ötalagui ia.', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 9, 'Ifo''aya högöu aya omasiö; saembu si sökhi sibai ifa''ema khöu.[3].', '["MozIII 18:5","Faigi 3:1","Faigi 1:9"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 10, 'Fondrondrongo onogu, be''e ba dödöu huhuogu, andre, ba anau nosou.[4].', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 12, 'Na mowaö-waö''ö, ba lö hadia ia zi fatimba ba gaheu, ba fagohi''ö, ba lö alau''ö.', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 13, 'Olembai wamahaö andrö; böi böhöli; aro''ö khöu me fangorifiu.', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 14, 'Böi saŵa lala zebua horö, ba böi törö döröŵa zi lö sökhi.[6].', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 15, 'Böi hundragö ba böi törö; hole''ögö, törö zi tambai!', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 16, 'Tebai sa mörö ira, na lö nifazökhira si lö sökhi; lö alau höröra, na lö nibe''era te''ala niha.', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 17, 'Ö horö göra, ba famalangögö niha wangokafu dödöra, no timba nagu.', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 18, 'Lala zatulö andrö, ba mohaga ba wa''amoluo, si tedou-dou, irege haga ba zi ma''ökhö.', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 19, 'Ba lala zebua horö andrö, ba no ogömi-gömi, si mane si bongi; lö oroma khöra hadia nitendrera.[7].', '["Faigi 3:2","Sin 32:8; 27:11","Faigi 1:10; Sin 1:1","Faigi 13:9; 24:20"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 20, 'He onogu, fondrondrongo niŵa''ögu, be''e mbörö dalingau ba huhuogu andre.', '["Faigi 3:8; 13:16","Heb 12:13","MozV 5:29"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 21, 'Böi aefa-aefa ia ba duduma höröu, tanö ba hunö dödöu!', '["Faigi 3:8; 13:16","Heb 12:13","MozV 5:29"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 22, 'Fangorifi sa ia ba zanöndra eluahania, dalu-dalu nösi ma''asambua.[8].', '["Faigi 3:8; 13:16","Heb 12:13","MozV 5:29"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 23, 'Ba si a''ania, ba faigi-faigi dödöu; khönia i''otarai fa''auri.', '["Faigi 3:8; 13:16","Heb 12:13","MozV 5:29"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 24, 'Böhöli wa''atefuyu huhuo, ba timba walimosa mbewe.', '["Faigi 3:8; 13:16","Heb 12:13","MozV 5:29"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 25, 'Ya''adölö höröu, ba ya atulö miföna guli dalimbou andrö.', '["Faigi 3:8; 13:16","Heb 12:13","MozV 5:29"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 26, 'Tulo tödöu nitörö gaheu, ba böi ya mangiwa lala andrö khöu fefu.[9].', '["Faigi 3:8; 13:16","Heb 12:13","MozV 5:29"]', NULL),
  (3405251, 'OT', 'Amaedola Zelomo', 4, 27, 'Böi hole''ögö, he ba gambölö ba he ba gabera; böi itörö aheu zi lö sökhi.[10].', '["Faigi 3:8; 13:16","Heb 12:13","MozV 5:29"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 1, 'He onogu, fondrondrongo wa''atua-tua andre khögu; be''e mbörö dalingau ba wa''aboto ba dödö.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 2, 'Ena''ö lö aefa khöu wotödö, ba ena''ö lö aefa ba mbeweu, wa ö''ila watahögö.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 3, 'Sowöi ŵe ŵani sa mbewe ndra alawe bö''ö andrö, ba salösö moroi ba wanikha lelania.[1]', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 4, 'Ba ba gafuriata, ba afeto ia moroi ba gawökhu ba atarö, si mane gari si faoma bawa.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 5, 'Ba wa''atetiko mitou isaŵa, ba ba mbanua tou aekhu lalania.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 6, 'Lö''ö manö isöndra lala wangorifi, no muzaŵa döröŵania, ba lö aboto ba dödönia.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 7, 'Andrö mifondrondrongo khögu, ya''ami ono matua, böi olifu ami huhuogu andre!', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 8, 'Aröu''ögö khönia; böi hatö''ögö ba mbagi nora khönia.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 9, 'Fa böi ölulu ba niha bö''ö wa''asökhi döimö, ba böi ötehe ndröfimö andrö ba zi lö fa''ahakhö dödö.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 10, 'Fa böi la''a gölöu niha bö''ö, ba böi te''oloi''ö ba nomo niha bö''ö lua-lua wa''erege dödöu.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 11, 'Fa böi sangarö-ngarö ndra''ugö ba gafuriata, na ariri nösiu.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 12, 'Fa böi ömane dania: Hadia, wa no fatuwu khögu wamangelama mege, hadia wa lö ba dödögu wotu?', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 13, 'Wa lö ufondrondrongo li zamahaö ya''o, wa lö u''o''ö khö zangombakha lala khögu?', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 14, 'Hatö ma''ifu tö, ba falukhado wa''atekiko bakha ba hunö gowuloa mbanua.', '["Faigi 2:16–19"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 15, 'Ba mba''a khöu badu nidanö, hadia zalua ba gumbu khömö.', '["Sangomb 9:9"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 16, 'Ma dania isaŵa baero idanö gumbu khöu, ma itörö newali luaha hele.', '["Sangomb 9:9"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 17, 'Fa''u''u ia khöu, böi tehe ba mbö''ö, ba ngaiu.', '["Sangomb 9:9"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 18, 'Ya ahowu gumbu andrö khöu, ba ena''ö omuso dödöu ndra alaweu me ono matua ndra''ugö!', '["Sangomb 9:9"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 19, 'Si hulö mböhö si alawe omasiö, si hulö zi alawe nago si sökhi sibai; ya hulö zi fadoro mabu ndra''ugö zusunia, ba ya owua-wua dödöu wa''omasinia andrö, böi yamamalö-malö.[2]', '["Sangomb 9:9"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 20, 'Hana sa wa edöna owöhö''ö ba mbö''ö, ya''ugö onogu; hana wa edöna ötalagui ndra alawe baero?', '["Sangomb 9:9"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 21, 'Lala niha fefu, ba noa sa''ae oroma khö Yehowa; fefu döröŵa niha, ba itulo tödönia.', '["Sangomb 9:9"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 22, 'Ba horönia andrö alau zebua horö, ba zinali golalöŵania tekabi.', '["Sangomb 9:9"]', NULL),
  (3405256, 'OT', 'Amaedola Zelomo', 5, 23, 'Tekiko ia, me no ambö fotu mege; elungu ia ba wa''abölö wa''awöhö mowa andrö khönia.', '["Sangomb 9:9"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 1, 'He onogu, na no möi''ö ba wali khö nawöu, na no ötangai hadia ia ba niha bö''ö,[1],', '["Faigi 11:15; 17:18; 20:16"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 2, 'na no öfesu ndra''ugö beweu, na no muböbö dangau taröma liu.', '["Faigi 11:15; 17:18; 20:16"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 3, 'ba o''ö khögu da''e, onogu: fuli efa''ö ndra''ugö; me no ölulu ndra''ugö ba danga nawöu; ae''e, angalulu ba forege khö nawöu andrö.', '["Faigi 11:15; 17:18; 20:16"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 4, 'Böi tehe ua wemörö ba höröu, abe''e''ö guli höröu, fa böi alau.', '["Faigi 11:15; 17:18; 20:16"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 5, 'Alui wangefa''ö ya''ugö ba dangania, si mane nago, si mane fofo ba danga zolau fuka.', '["Faigi 11:15; 17:18; 20:16"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 6, 'Ae faigi zikhö andrö, ya''ugö si no areu; faigi gamuatania, ena''ö ösöndra wa''atua-tua.[2]', '["Faigi 10:4; 26:4","Faigi 24:33–34"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 7, 'Lö salaŵa khöra, lö mandru, lö solohe,', '["Faigi 10:4; 26:4","Faigi 24:33–34"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 8, 'Ba la''alui zui mbalazora, na baŵa mosino, lahöna göra, na baŵa wamasi.', '["Faigi 10:4; 26:4","Faigi 24:33–34"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 9, 'Ha wa''ara na öfadölö ndra''ugö ba zalo, ya''ugö sareu? Ha wa''ara maoso''ö, wamöhöli femörö?', '["Faigi 10:4; 26:4","Faigi 24:33–34"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 10, 'Ma''ifu tö wemörö, ma''ifu tö wemörö-mörö manu andrö, ma''ifu tö wamatahö tanga,[3],', '["Faigi 10:4; 26:4","Faigi 24:33–34"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 11, 'ba so moroi sa wa''anumana, hulö zikoli ba fa''ambö, si mane niha si no mangaro.', '["Faigi 10:4; 26:4","Faigi 24:33–34"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 12, 'Niha si lö guna, niha si si lö yaŵa zolau-lau faya bewenia.[4]', '["Faigi 10:31–32","Faigi 10:10"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 13, 'Ifamö''i hörönia, ifaudugö ahenia hadia ia, ituturu turunia.[5]', '["Faigi 10:31–32","Faigi 10:10"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 14, 'No tefuyu dödönia, fadoro ifakhai zi lö sökhi, ifobörö wasosota.', '["Faigi 10:31–32","Faigi 10:10"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 15, 'Andrö göna ia famakao si lö mudöna-döna; i''ogomuzaö afufu ia, lö samadöhö.', '["Faigi 10:31–32","Faigi 10:10"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 16, 'Önö balö zi fatuwu ba hörö Yehowa, ba fitu ni''ogorofinia.', '["Faigi 10:31–32","Faigi 10:10"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 17, 'Hörö si fayaŵa, ba lela sofaya, ba tanga samunu niha si lö horö,', '["Faigi 10:31–32","Faigi 10:10"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 18, 'ba tödö, samakhai si lö atulö, ba ahe si fagohi ba zi lö sökhi.', '["Faigi 10:31–32","Faigi 10:10"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 19, 'Ba sasi sofaya, solau si lö duhu, ba samobörö fagua-guasa ba zi fatalifusö.', '["Faigi 10:31–32","Faigi 10:10"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 20, 'He onogu, o''ö goroisa namau andrö, ba böi zi lö ba dödöu wamangelama ninau.[6]', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 21, 'Tanö ba dödöu, böi aefa-aefa; taŵi ba mbagiu.[7]', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 22, 'Na mofanö''ö, ba ena''ö ya''ia zamatörö ya''ugö, ba na mörö''ö, ba ya''ia zamaigi-maigi ya''ugö, ba na tokea''ö, ba ya''ia zihede khöu.[8]', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 23, 'Fandru sa goroisa andrö ba sulu wamangelama; ba fanegu ba fotu andrö, ba no lala wangorifi.', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 24, 'Ena''ö lö öbabaya ndra alawe si lö sökhi andrö, ba ena''ö lö öfondrondrongo lela ndra alawe baero andrö, si no alösö.[9]', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 25, 'Böi i''isö tödöu wa''asökhi mbawania, ba böi ifesu ndra''ugö bu hörönia.', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 26, 'Ira alawe somasi fohorö, ba ifa''anumana ita, irege lö öda sa''ae, ba donga zodonga, ba möi famunuda, i''oloi''ö nosoda, sebua böli andrö.', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 27, 'Hadia, ta''ila tabe''e galitö ba nono mbaruda, ba lö akhozi mbaru?', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 28, 'Ba ta''ila tatörö mbo galitö, ba lö ariri gaheda?', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 29, 'Si manö göi lala zi möi ba ndra alawe nawönia; lö zi lö fotu ba zombambaya ya''ia.[10]', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 30, 'Ebolo na dödö ba zanagö, na managö ia ba wamo''ösi talunia, na olofo ia.', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 31, 'Ba na lara''u ia ba mewitu i''ali, he ahori nibaya-bayania.', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 32, 'Ba ha niha zi horöni donga zodonga, ba si lö tödö; sedöna mamakiko ya''ia zolau si manö.[11]', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 33, 'Fa''ate''ala ba fa''aila isöndra; tebai sa''ae i''ezosi ia, ba wa''ailania andrö.', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 34, 'Mofönu sa ndra matua ibe''e fa''olohu andrö, ba lö fa''ebolo dödö, na baŵa wolau balö.', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405262, 'OT', 'Amaedola Zelomo', 6, 35, 'Lö ba dödönia hölu, ba he ana''a sebua öbe''e khönia, ba lö itema.', '["Faigi 1:8","Faigi 3:3","Sin 119:172","Faigi 2:16","Faigi 5:10–14","KorI 6:18"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 1, 'He onogu, böi olifugö''ö huhuogu andre, ba iro''irö''ö ba dödöu goroisagu.', '["Faigi 3:3","Faigi 2:16"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 2, 'Böi taya ba dödöu goroisagu, ba auri''ö; töngöni nifakhoigu andrö, nifamaigi-maigi ono hörö.', '["Faigi 3:3","Faigi 2:16"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 3, 'Böbö ia ba durumö, ba ba naha zura ba dödöu ötanö ia.[1].', '["Faigi 3:3","Faigi 2:16"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 4, 'Be''e töi wa''atua-tua dalifusöu alawe, ba töi wa''aboto ba dödö zomasi ya''ugö, ono alawe.', '["Faigi 3:3","Faigi 2:16"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 5, 'Ena''ö itimba khöu ndra alawe bö''ö andrö, ira alawe baero, salösö lela.[2].', '["Faigi 3:3","Faigi 2:16"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 6, 'Noa sa ufaigi ba zandrela nomogu, ba darali andrö.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 7, 'Ba u''ila nono matua si lö tödö, ba zi lö mangila watahögö na, ba nono matua andrö oroma khögu.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 8, 'Itörö newali, ihene watalinga, isaŵa nomo ndra alawe andrö.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 9, 'Me bongi, me ibörötaigö ogömi-gömi ba zi bongi.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 10, 'Ba hiza, ifaondragö ia ira alawe, monukha ndra alawe si lö sökhi ba si lö sökhi bakha dödö.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 11, 'Ira alawe sabao, safaito, si tebai ahono-hono yomo;', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 12, 'so, ba ba onga so ia, ba so, ba ba newali ba mbini-mbini fefu manaro ia.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 13, 'Da''ö zondra''u ya''ia, fa''ago bawa khönia, ba imane khönia, lö aila-aila:', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 14, '"So mege gömögu sumange fangorifi, ba no ube''e me maökhö nifabu''ugu andrö.', '["MozIII 3:3–4"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3405275, 'OT', 'Amaedola Zelomo', 7, 15, 'Andrö möido mamaondragö ya''ugö, ba wangalui ya''ugö, ba noa göi falukha ita.[3].', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 16, 'No uhaogö gasogu, no ube''e gambala, awö lembe sigara-gara, muko Ndrawa Miserayi.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 17, 'No ulau emuri ba aloe ba kuli mani ba gasogu.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 18, 'Tabu, talau famasimasi, sara wongi; ta''omusoi''ö dödöda, wanalagui awöda.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 19, 'Ira matua, ba noa sa mofanö, no möi mukoli ba zaröu.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 20, 'No i''ohe dokosa gana''a, awena ba duli mangawuli ia?"', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 21, 'Ifaelungu nono matua andrö fehede nihaogö-haogö, idönisi bewenia salösö andrö.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 22, 'Ba i''anema''ö i''o''ö khönia, hulö göröbao, ni''ohe ba wanaba, ba hulö zowöhö, nifesu ahe.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 23, 'Irege ifabali gatenia ono wana; si mane fofo sondrölö ya''ia ba wesu, si lö mangila, wa famununia.', '["MozIII 3:3–4"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 24, 'Andrö mi''o''ö khögu, ya''ami ono matua, ba mibe''e ba dödömi huhuogu andre.', '["Faigi 2:18–19"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 25, 'Böi yamuhole''ö ia tödöu ba lala andrö khönia, ba böi elungu''ö ba nitörönia andrö.', '["Faigi 2:18–19"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 26, 'No ato tou nibunu, nibözinia tou; ba nibununia fefu, ba tenga ha ma''ifu.', '["Faigi 2:18–19"]', NULL),
  (3405275, 'OT', 'Amaedola Zelomo', 7, 27, 'Omonia andrö, ba no lala ba mbanua tou, ba mbate''e zi mate aekhu.[4].', '["Faigi 2:18–19"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 1, 'Hadia, lö mu''ao wa''atua-tua andrö? Hadia, lö ifarongogö linia fa''aboto ba dödö?[1]', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 2, 'Ba zuzu hili yaŵa ba zinga lala ba ba waerua lala i''iagö.', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 3, 'Ba zinga mbawa göli, ba mbalö mbanua, ba mbawa lala miyomo mu''ao ia, imane:', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 4, '"Khömi, ira matua, muhede ndra''o, ba nono niha ufarongogö ligu:', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 5, 'Ya''ami soŵöhöwöhö, mifondrondrongo wangila watahogö ba ya''ami si lö tödö mifondrondrongo wa''aboto ba dödö!', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 6, 'Mifondrondrongo, ba hadia zoadu ufatunö, satulö wehede mbewegu.', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 7, 'Si duhu ilau lelagu, ba hadia ia horö, ba i''ogorofi bewegu.', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 8, 'Satulö fefu wehede mbawagu; lö hadia ia zi tefuyu ba lö si lö atulö.', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 9, 'Ahori isöndra geluaha sangila watahögö, ba lö si fatimba ba zi no manöndra fa''aboto ba dödö.', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 10, 'Andrö mi''omasi''ö wamangelama andre khögu, moroi ba wirö, ba mi''omasi''ö wa''aboto ba dödö zi duhu, moroiba mbalaki.[2]', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 11, 'Ebua sa mböli wa''atua-tua, moroi ba mböli mani-mani; fefu hadia ia zomasi niha, ba lö fagölö-gölö khönia."', '["Faigi 1:20–33","Faigi 3:14"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 12, '"Ya''odo fa''atua-tua, ba no si so fa''onekhe, ba ufa''ema wa''aboto ba dödö.', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 13, 'Fangata''ufi Yehowa, ba no fa''ogoro ba zi lö sökhi; hokha ba fayaŵasa ba fanörö lala si lö sökhi, ba no sogoro ndra''o.[3]', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 14, 'Khögu so wamolala tödö ba fangabe''e; fa''aboto ba dödö ndra''odo; khögu wa''abölö.', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 15, 'Balazi ndra''o, wa la''ila mamatörö niha bö''ö razo, awö wa lahonogöi zatulö samatörö andrö.[4]', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 16, 'Samatörö andrö ba salaŵa, dozi sanguhuku ba guli danö, ba moroi khögu, wa no salaŵa ira.', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 17, 'U''omasi''ö zomasi ya''odo, ba sangalui ya''odo, fatua ono matua ira, ba lasöndra ndra''o.', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 18, 'So khögu gana''a ba fa''ebua döi, girö-girö si lö tebulö ba fa''atulö.[5]', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 19, 'Fangata''ufi ya''odo, ba no tohude moroi ba gana''a, moroi ba mbalaki; ba nisöndra khögu, ba no tohude, moroi ba wirö si sökhi.', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 20, 'Lala satulö utörö, tödö lala sadölö,', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 21, 'ba wamo''ana''a somasi ya''odo, ba wamo''ösi arö dawöla khöra."', '["Faigi 6:12–19","Faigi 16:12; Sangomb 10:16","Faigi 3:16"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 22, '"Yehowa mege zomböi ya''odo, böröta lala andrö khönia, böröta halöŵönia föna.[6]', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 23, 'Ba götö föna sibai sa''ae tefataro ndra''odo, ba mböröta, me tefobörö danö.', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 24, 'Me lö''ö na mu''abakha''ö nasi, tumbu ndra''o; me lö umbu na, sabölö idanö.', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 25, 'Lö''ö na mufadane dane hili ba lö hili-hili na, ba no tumbu ndra''odo.', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 26, 'Me lö nifazökhinia tanö na, awö mbenua misa, awö mböröta danö andrö.', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 27, 'Me ifazökhi mbanua si yaŵa sa ba no sodo; me i''aro''ö zi no amaedola wayo yaŵa nasi;[7]', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 28, 'Me ifataro lawuo si yaŵa ba me ihonogöi gumbu ba zabakha si tou.', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 29, 'Me ihonogöi wondrege nasi, fa böi isawö niŵa''önia dulu, ba me ilata danö;[8]', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 30, 'Ba ya''odo duka khönia, fa''omuso dödö ndra''o [khönia], ero ma''ökhö, famai ndra''o fönania, lö mamalö-malö.', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 31, 'Famaido ba guli danö andrö khönia, ba somuso tödö ndra''o ba nono niha." [9]', '["Yob 28:27","Yob 26:10","Yob 38:11–12; Sin 104:9","MozV 33:3"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 32, '"Andrö mifondrondrongo khögu, ya''ami ira onogu; ya ahowu sa zanörö lala andrö khögu!', '["Faigi 3:2"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 33, 'Mifondrondrongo wamangelama andre, ena''ö atua-tua ami; böi mi''ositengagö!', '["Faigi 3:2"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 34, 'Ya ahowu niha, samondrongo khögu, ba wanaronaro ba zinga mbawandruhö khögu, ba wamaigi-maigi ehomo fatambai mbawandruhö andrö khögu!', '["Faigi 3:2"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 35, 'Sanöndra ya''odo sa, ba isöndra wa''auri; falukha ia wa''ebua dödö khö Yehowa.[10]', '["Faigi 3:2"]', NULL),
  (3405304, 'OT', 'Amaedola Zelomo', 8, 36, 'Ba si lö manöndra ya''o, ba i''alani ia; dozi si fa''udu khögu, ba somasi fa''atekiko."', '["Faigi 3:2"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 1, 'No ilau nomonia fa''atua-tua andrö, fitu daru nahe nifofoe.', '["Mat 22:4","Faigi 1:22"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 2, 'No itaba göröbao ba hadia nitaba bö''önia; no ifaruka nagu andrö khönia, no ihaogö meza.[1]', '["Mat 22:4","Faigi 1:22"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 3, 'No ifatenge zi manga gazi ono alawe, ba wogaoni niha ba wondrege hili mbanua.', '["Mat 22:4","Faigi 1:22"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 4, '"Ha niha zadölö tödö? Ya möi ba da''e!" Imane ba zambö tödö:', '["Mat 22:4","Faigi 1:22"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 5, '"Mitabu, mi''a gö andrö khögu ba mibadu nagu andrö nifarukagu!', '["Mat 22:4","Faigi 1:22"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 6, 'Miböhöli walötödö andrö, ba auri ami; ba mitörö lala wa''aboto ba dödö!"[2]', '["Mat 22:4","Faigi 1:22"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 7, 'Sangotu''ö sango''aya, ba ihalö khönia wangaila, ba sanegu sebua horö, ba ita''unöi ia.', '["Faigi 23:9","Faigi 1:7","Faigi 3:2–16"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 8, 'Ba böi tegu zango''aya, fa böi fatiu dödönia khöu; satua-tua tegu, ba i''omasi''ö ndra''ugö.[3]', '["Faigi 23:9","Faigi 1:7","Faigi 3:2–16"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 9, 'Fahaö zatua-tua, ba tedou wa''atua-tuania, fobawa lala ba zatulö tödö, ba monönö wangilania.', '["Faigi 23:9","Faigi 1:7","Faigi 3:2–16"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 10, 'Böröta wa''atua-tua, ba fangata''ufi Yehowa, ba fa''aboto ba dödö Ni''amoni''ö andrö, ba no fa''amotödö.[4]', '["Faigi 23:9","Faigi 1:7","Faigi 3:2–16"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 11, 'Moroi ba khögu sa tedou wa''anau nosou, ba moroi ba khögu monönö ndröfi götöu andrö.[5]', '["Faigi 23:9","Faigi 1:7","Faigi 3:2–16"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 12, 'Na atua-tua ndra''ugö, ba khöu moguna wa''atua-tuamö, ba na sango''aya ndra''ugö, ba ha ya''ugö zolu''i.', '["Faigi 23:9","Faigi 1:7","Faigi 3:2–16"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 13, 'Ira alawe andrö sowöhö mowa, ba lö ahono-hono, si lö tödö ia, ba lö i''ila watahögö hadia ia.', '["Faigi 20:17"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 14, 'Dumadao barö nomo khönia, ba dadaoma ba hili-hili ba mbanua,', '["Faigi 20:17"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 15, 'ba wehede ba zanörö, sondrölö ya''ira ba lalara, imane:', '["Faigi 20:17"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 16, '"Ha niha zowöhö-wöhö, ba ya möi ba da''e!" Ba ba zi lö tödö, ba imane:', '["Faigi 20:17"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 17, '"Ami nidanö nitagö ba omasiö kue nibini''ö."[6]', '["Faigi 20:17"]', NULL),
  (3405311, 'OT', 'Amaedola Zelomo', 9, 18, 'Ba lö i''ila, wa no lumö-lumö zi so ba da''ö, wa ba zabakha ba mbanua tou so nikaoninia andrö.', '["Faigi 20:17"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 1, 'Fa''omuso dödö namania nono matua satua-tua; ba fangabu dödö ninania nono si lö tödö.[1]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 2, 'Ana''a nisöndra ba zi lö atulö, ba si lö guna; ba fa''atulö dödö, ba i''efa''ö ba wa''amate.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 3, 'Lö ibe''e Yehowa olofo zatulö tödö, ba itimba wangisö zebua horö.[2]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 4, 'Numana dania zareu tanga, ba isöndra gana''a tanga zawölö-ölö.[3]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 5, 'Sangöhöna na baŵa wonowi, ba no ono satua-tua; ba si mörö na baŵa wamasi, ba ono sangailasi ira amania.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 6, 'Fahöna dania huwuhowu ba högö zatulö tödö, ba bewe zebua horö, ba no tobalu falöatulö.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 7, 'Famahowu wa lö olifu niha bö''ö zatulö tödö; ba töi zebua horö, ba obou.[4]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 8, 'Satutua tödö, ba ihalö khönia goroisa andrö; ba si so bewe zowöhö mowa, ba salau dania.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 9, 'Sanörö lala sadölö, ba lö fangabu dödö ba lala, ba sanörö lala sabila, ba oroma dania.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 10, 'Samamö''i hörö, fango''aya, ba ibaosi dödö nawönia; ba si lö aiwö wanegu niha, ba i''atulö''ö ira.[5]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 11, 'Umbu wa''auri mbawa zatulö tödö; ba bewe zebua horö, ba no tobalu falöatulö.[6]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 12, 'Lua-lua watiusa, ba fasosota; ba fa''omasi andrö, ba no balu-balu golalöwa, fefu.[7]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 13, 'Ba mbewe zi so tödö, ba tesöndra wa''atua-tua; ba bözi-bözi zi nangea ba hulu zi lö tödö.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 14, 'Satua-tua, ba lö la''oroma''ö wa''aboto ba dödöra, ba ba mbewe zi lö tödö, ba no ahatö wa''adudu.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 15, 'Sebua ana''a, ba idöna-döna ba gana''ania we''e-we''e dödönia; ba si numana, ba abu dödö ba wa''anumanania.[8]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 16, 'Ölö zatulö tödö, ba tobali fangorifi; ba nisöndra zebua horö, ba tobali horö.[9]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 17, 'Lala ba wa''auri lala zamondrondrongo fotu; ba si lö ba dödö fanegu, ba elungu.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 18, 'Samini''ö fatiusa, ba no sobewe solau faya; ba sama''ema famöbögö si lö sökhi, ba si lö tödö.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 19, 'Ba zoya li, ba lö zi lö olalöŵa; ba sanaha bewenia, ba no sangenanö.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 20, 'Firö omasiö lela zatulö tödö; ba tödö zebua horö, ba hulö zi lö guna.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 21, 'Bewe zatulö tödö, ba same''e gö ba zato; ba si lö tödö andrö, ba mate ba wa''ambö tödö.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 22, 'Ifo''ana''a niha howu-howu khö Yehowa andrö; ba ma''ifu lö inönö fangerege dödö.[10]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 23, 'Ba zi lö tödö, ba omasiö wamazökhi si lö sökhi; ba ba zaboto ba dödö, ba omasiö wa''atua-tua.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 24, 'Sebua horö, ba falukha zata''u ia, ba ba zatulö tödö, ba itörö zomasi ira.[11]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 25, 'Na itörö angi sabölö, ba aetu zebua horö; ba satulö tödö, ba no si so dane-dane si lö mangiwa.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 26, 'Si mane niro aisö[12] ba mboha ba si mane simbo ba hörö, si manö zareu khö zamatenge ya''ia.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 27, 'Fangata''ufi Yehowa, ba i''anau''ö noso; ba niböda ndröfi zebua horö.[13]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 28, 'Fombalo-mbaloi zatulö tödö, ba tobali fa''omuso dödö: ba fanötöna zebua horö, ba tobali faya.[14]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 29, 'Famatörö Yehowa andrö, ba no ba''a-ba''a ba zatulö tödö; ba famakiko ia ba zamazökhi si lö sökhi.[15]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 30, 'Satulö tödö, ba lö mangiwa, irugi zi lö aetu; ba sebua horö, ba si lö nahia ba danö dania.[16]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 31, 'Lua-lua mbawa zatulö tödö, ba fa''atua-tua; ba lela si tefuyu, ba nideha.[17]', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405315, 'OT', 'Amaedola Zelomo', 10, 32, 'Bewe zatulö tödö, ba i''ila hadia zomasi niha bö''ö; ba bawa zebua horö, ba no ha sambalö fa''atefuyu.', '["Faigi 15:20; 17:21–25","Sin 37:19–20","Faigi 6:6–11; 12:24; 27:19; 15:28–19","Yob 18:17; Sin 9:6","Faigi 6:13","Ayati 31; Faigi 13:14","FetI 4:8","Faigi 18:11","Luk 16:19","Sin 127:2","Faigi 1:17; Sin 37:4","zuka","Faigi 9:11; 14:27","Sin 9:19; Yob 8:13","Faigi 3:26","Sin 112:6; F 2:22","Ayati 11 Sin 37:30"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 1, 'Fali''era si lö atulö, ba no ni''ogorofi Yehowa; ba saga si lö ambö, ba omasi ia.[1]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3405336, 'OT', 'Amaedola Zelomo', 11, 2, 'Na so wayaŵasa, ba so göi wa''aila; ba ba zangide-ide''ö ya''ia, ba so wa''atua-tua.[2]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 3, 'Fa''adölö dödö zatulö andrö zamasao ya''ira; ba famakiko zi faröi andrö wa''atefuyura.[3]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 4, 'Ana''a, ba lö i''orifi ita, na baŵa wanguhuku; ba no fangorifi wa''atulö dödö.[4]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 5, 'Fa''atulö zadölö tödö andrö, ba no fangadölö lalania; ba sebua horö, ba alau ba gamuatania andrö, ba horö.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 6, 'I''orifi zadölö tödö fa''atulönia andrö; ba si faröi andrö, ba te''u''u ba wangisönia andrö.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 7, 'Na mate niha sebua horö, ba awai wanötönania; si tobali faya sa wanötöna zanao horö.[5]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 8, 'Satulö tödö, ba te''efa''ö ba wa''atosasa; ba möi fangalinia zebua horö.[6]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 9, 'Ba zanaonao horö, ba bewenia wamakiko nawönia; ba fa''aboto ba dödö wangorifi zatulö.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 10, 'Na ohahau dödö zatulö, ba owua-wua dödö mbanua; ba ma''iki na tekiko zebua horö.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 11, 'Fangazökhi mbanua howu-howu zatulö; ba fanudugö ya''ia mbawa zebua horö.[7]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 12, 'Sambö tödö, ba sango''aya awönia, ba saboto ba dödö, ba lö hede-hede.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 13, 'Samokai si tobini zamatou awönia; ba sadölö tödö, ba ibalugö, na so hadia ia.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 14, 'Ba zi lö folohe, ba adudu mbanua, ba ohahau dödö ba zi lö ambö samolala.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 15, 'Lö zi lö te''ala zi möi fali niha bö''ö; ba si lö omasi fe''amöi ba wali, ba lö fangabu dödö.[8]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 16, 'Ira alawe omasiö, ba isöndra zumange, si mane fanöndra zamalangögö awöra ana''a.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 17, 'Ba niha sebua tödö, ba khönia zi sökhi nisöndrania; ba safaito, ba ifakao nösinia.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 18, 'Sebua horö, ba isöndra hare faya; ba sanaru fa''atulö dödö, ba isöndra mböli gölö si ndruhu.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 19, 'Lua-lua zi ndruhu fa''atulö dödö, ba fa''auri; ba solohi si lö sökhi, ba falukha wa''amate.[9]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 20, 'Si tefuyu tödö, ba ni''ogorofi Yehowa; ba sanörö lala si sökhi, ba i''omasi''ö.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 21, 'Da dangau! Lö zi lö te''otu''ö niha si lö sökhi, ba nga''ötö zatulö tödö, ba te''orifi.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 22, 'Hulö naya balaki ba nikhu zigelo, si manö ndra''alawe si sökhi bawa ba si lö fangenanö.[10]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 23, 'Somasi satulö tödö, ba ha sambalö si sökhi, ba fanötöna zebua horö, ba falukha wanguhuku.[11]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 24, 'Si samösa, ba oya ibe''e, ba tedou-dou manö zi so khönia, ba si samösa, ba i''atalisi zi nangea nibe''e, ba tedou wa''anumanania.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 25, 'Sebua tödö, ba ni''abusoi''ö, ba sangokafui tödö nawönia, ba ni''okafui tödö dania.[12]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 26, 'Si lö edöna mamawa fakhe, ba ni''elifi niha, ba ba högö zamawa, ba tohare howu-howu.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 27, 'Sangalui si sökhi, ba fa''omasi i''alui; ba solohi si lö sökhi, ba nitörö zi lö sökhi.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 28, 'Sanötöna ba gana''ania, ba alau dania; ba satulö tödö, ba auri, si mane bulu zinanö.[13]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 29, 'Samakuyu soroiyomonia, ba angi isöndra, ba sawuyu zatua-tua dania zi lö tödö.', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 30, 'Bua-bua zatulö tödö, ba eu sowua fangorifi, ba satua-tua, ba isöndra dödö niha.[14]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405336, 'OT', 'Amaedola Zelomo', 11, 31, 'Hiza, isöndra ba guli danö luonia satulö tödö, ba mendrua manö zebua horö ba samazökhi si lö sökhi.[15]', '["Faigi 16:11; 20:10; MozIII 19:35","Faigi 16:18; 18:12","Sin 52:7","Faigi 10:2","Faigi 10:28","Faigi 21:18; Yes 43:3","Faigi 28:12; 29:2","Faigi 6:1–2","Faigi 19:23","Faigi 31:30","Ayati 7","Faigi 19:17","Sin 52:9–10","Faigi 3:18; 15:4","FetI 4:17–18"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 1, 'Somasi fotu, ba omasi göi wa''oboto ba dödö, ba si lö omasi fanegu, ba no si lö tödö.[1]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 2, 'Niha si sökhi tödö, ba isöndra wa''omasi Yehowa ia, ba samakhai si lö sökhi, ba ihuku Yehowa.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 3, 'Ba wanao horö, ba lö falukha wa''arö, ba si tebai adeha ŵa''a zatulö tödö.[2]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 4, 'Ira alawe si sökhi tödö, ba no amaedola zaembu aya ba ndramatuania; ba solau si lö moadu, ba hulö wangobou dölania.[3]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 5, 'Era-era zatulö tödö, ba sadölö, ba nikhoi dödö zebua horö, ba falimosa.[4]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 6, 'Fehede zebua horö, ba fangalui famunu niha bö''ö; ba bawa zatulö tödö, ba fangorifira.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 7, 'Nibali''ö arö zebua horö, fa böi ya''ira sa''ae; ba omo zatulö, ba lö tebulö.[5]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 8, 'Dali wa''atua-tuania, na tesuno niha; ba si no tefuyu tödö, ba lö ba dödö nawönia.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 9, 'Sökhi zi lö töi, ba si so sangai halöŵö, moroi ba zi fayaŵa ba sambö balazo.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 10, 'Satulö tödö, ba ihakhösi tödö gurifönia, ba tödö zebua horö, ba no safaito.[6]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 11, 'Sangahalö, ba isöndra zabönö balazo; ba solohi faya-faya, ba si lö tödö.[7]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 12, 'Sebua horö, ba i''isö nösi gu''ö zi lö sökhi; ba ŵa''a zatulö tödö, ba no sanau ölö.[8]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 13, 'Ba golalöŵa mbewenia ifesu ia si lö sökhi; ba satulö tödö, ba lö falukha wamakao.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 14, 'Moroi ba mbua-bua mbewenia fahöna zi sökhi ba niha; ba hadia nilau danga niha, ba mangawuli khönia.[9]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 15, 'Lala zi lö tödö andrö, ba no si sökhi, wamaiginia; ba satua-tua, ba itöngöni, ba tefobawa lala khönia.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 16, 'Fa''abao dödö zi lö tödö, ba i''anema''ö oroma, ba satua-tua, ba ibini''ö wa''aila.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 17, 'Solau si duhu, ba satulö ifalua, ba sasi sofaya, ba falimo.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 18, 'So ösa si falela-lela manö, ba hulö nikhu gari; ba lela zatua-tua, ba no dalu-dalu.[10]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 19, 'Bewe si ndruhu, ba lö tebulö; ba lela sofaya, ba si lö arara.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 20, 'Falimosa zi so ba dödö zamakhai si lö sökhi; ba ba zamarou ba wa''atulö ba fa''ömuso dödö.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 21, 'Satulö tödö, ba lö göna famakao; ba ba zebua horö, ba fahöna wangabu dödö.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 22, 'Bewe sofaya, ba ni''ogorofi Yehowa; ba somasi ia zolau si duhu.[11]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 23, 'Niha satua-tua, ba ibini''ö wa''aboto ba dödönia, ba tödö zi lö tödö, ba ifarongogö wa''owöhö mowa andrö khönia.[12]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 24, 'Samatörö dania danga zowölö-ölö; ba si göna rodi dania danga zareu.[13]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 25, 'Fa''abu dödö niha, ba ihöndrögö tou dödö; ba fondrara dödö daroma li nihaogö.[14]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 26, 'Satulö tödö, ba ifaigi wangorifinia; ba ba gelungua aekhu lala zebua horö.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 27, 'Sareu, ba lö ibe''e maliŵa gahuluania; ba fa''owölö-ölö, ba no girö-girö sebua böli, ba niha.[15]', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405337, 'OT', 'Amaedola Zelomo', 12, 28, 'Ba lala satulö, ba so wangorifi; ba tenga ba wamunu aekhu lala sadölö.', '["Faigi 13:1–18","Ayati 12","Faigi 31:10–31","RazI 12:6–19","Faigi 10:25; Yob 8:13–19","MozII 23:5","Faigi 28:19","Ayati 3","Rom 2:6","Faigi 13:3","Faigi 6:17","Faigi 29:11","Faigi 10:4","Faigi 16:24","Ayati 24"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 1, 'Ono matua satua-tua, ba ifondrondrongo wotu namania; ba sango''aya, ba lö irongo wanegu.[1].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 2, 'Moroi ba mbua-bua mbewenia i''a zi sökhi niha; ba fangisö zi faröi andrö, ba no famalangögö awöra.[2].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 3, 'Sanaro bewenia, ba irorogö nosonia; ba samonumalö manö bewenia, ba falukha wa''adudu.[3].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 4, 'Tödö zareu, ba mangisö, ba lö boto; ba ba zowölö-ölö, ba fahöna dania wangokafu dödö.[4].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 5, 'Satulö tödö, ba i''ogorofi waya''; ba sebua horö, ba si lö sökhi ba saila ita ilau. 6 Fa''atulö dödö, ba lö ibe''e elungu; ba fanao horö andrö, ba ibe''e alau zi so horö.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 7, 'So zi hokhaini ana''a, ba no si lö''ö; ba so zanguma''ö si numana ia, ba no ebua gana''a.[5].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 8, 'Höli noso niha gana''ania, ba ba zi numana, ba lö tefarongogö wameta''u.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 9, 'Fandru zatulö tödö, ba no si sökhi wehola; ba sulu zebua horö, ba mate.[6].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 10, 'Lua-lua wayaŵasa, ba ha sambalö fasosota; ba samondrongo famobawa lala, ba no si so fa''atua-tua.[7].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 11, 'Ana''a nisöndra ba waya, ba taya-taya; ba sangozaragö si sagosagokhö, ba tedou-dou ibe''e.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 12, 'Tötönafö sogasa, ba ifofökhö dödö; ba na alua zomasi ita, ba no amaedola geu sowua fangorifi.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 13, 'Si lö ba dödö taroma li Lowalangi, ba tekiko; ba sangata''ufi oroisa, ba moböli gölö.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 14, 'Famahaö zatua-tua, ba no umbu wangorifi, fangefa ba dandraŵa wa''amate.[8].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 15, 'Na motödö ita, ba ebua dödö niha khöda ibe''e; ba lala zi faröi andrö, ba no asai''ö.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 16, 'Satua-tua ba motödö wolau hadia ia fefu, ba si lö tödö, ba ifalua waya-faya.[9].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 17, 'Sinenge si lö sökhi, ba alau ba te''ala; ba sinenge si lö faröi, ba ifa''ema wangorifi.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 18, 'Sangositengagö fotu, ba falukha wa''anumana ba fa''aila; ba same''e ba dödö fanegu, ba nifosumange dania.[10].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 19, 'Na itörö somasi ita, ba sökhi dödöda ibe''e, ba famöhöi si lö sökhi, ba fatuwu ba zi lö tödö.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 20, 'Si fao-fao ba zatua-tua, ba atua-tua dania; ba si möi awö zi lö tödö, ba falukha wamunu.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 21, 'Igohi zi so horö famakao; ba ba zatulö tödö, ba tesulöni wa''ohahau tödö.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 22, 'Niha si sökhi, ba ifa''ema ba ma''uwunia zi so khönia; ba ana''a zi so horö, ba ba zatulö tödö möi dania.[11].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 23, 'Na molahoi daso zi numana, ba fahöna mbalazo dania; ba ato zi tekiko ba wa lö atulö.', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 24, 'Ba zalimagö bözi-bözi, ba lö fa''omasinia nononia matua; ba sangomasi''ö ononia, ba i''otu''ö fatua iraono.[12].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405340, 'OT', 'Amaedola Zelomo', 13, 25, 'Satulö tödö, ba manga-manga irege abuso; ba talu zebua horö, ba maoho.[13].', '["Faigi 1:8; 12:1","Faigi 12:14","Faigi 12:18; 21:23","Faigi 10:4","Mat 5:3; Fam 2:9; 3:17","Faigi 24:20; Yob 5:14; 18:5; 6:18","Faigi 28:25; 1:5","Faigi 10:11; 14:27","Faigi 12:23; 15:2","Faigi 12:1","Faigi 14:14–19; 28:8; Sangomb 2:26","Faigi 22:15","Sin 34:11"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 1, 'Fa''atua-tua ndra''alawe, ba i''otomosi nomonia; ba falötödö andrö ba idudugö tangania.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 2, 'Sadölö tödö wanörö lalania, ba no sangata''ufi Yehowa, ba sanörö lala sabila, ba no sangositengagö ya''ia.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 3, 'Ba mbawa zi lö tödö, ba so mbözi-bözi ba wayaŵasa; ba bewe zatua-tua, ba no ba''a-ba''a zi lö sökhi.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 4, 'Ba zi lö saŵi, ba lö ösi luha; ba ebua tesöndra balazo ba wa''abölö göröbao.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 5, 'Sasi si ndruhu, ba lö ifakhai waya; ba sasi sofaya, ba ifalua baeha waya.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 6, 'Sango''aya, ba i''alui wa''atua-tua, ba lö falukha; ba ba zi so tödö, ba aoha wangalui fa''aboto ba dödö.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 7, 'Erogö niha si lö tödö; lö''ö sa atö ö''ila wa''aboto ba dödö ba mbewenia.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 8, 'Da''ö wa''atua-tua zi so tödö, na aboto ba dödönia lalania andrö; ba fa''owöhö mowa zi lö tödö, ba no famaelungu.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 9, 'Ba zi lö tödö, ba tobali fango''aya ya''ira zumange fameta horö; ba sadölö tödö, ba no si sökhi tödö khö nawöra.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 10, '[Ha] tödö zangila safökhö khönia; ba tebai ihalö khönia niha bö''ö wa''omuso dödö zamösana.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 11, 'Omo zebua horö, ba nidudugö; ba ose zadölö tödö, ba no amaedola zobowo.[1]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 12, 'So lala si no adölö taŵa''ö, ba lua-luania, ba saekhu ba wa''amate.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 13, 'Barö wa''iki göi afökhö bakha dödö; ba fozu wa''omuso dödö ba fangabu dödö.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 14, 'Tödö si tefuyu, ba abuso dania lalania andrö; ba fangabuso niha si sökhi, ba bua-buania.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 15, 'Sambö tödö, ba ifati fefu hadia ia niŵa''ö; ba satua-tua, ba ifaigi nibekainia.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 16, 'Satua-tua, ba ata''u, ba i''erogö zi lö sökhi; ba sambö tödö, ba mofönu-fönu, ba lö i''ata''ufi hadia ia.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 17, 'Si ono wönutö, ba ilau nilau zowöhö; ba ba zamakhai falimosa, ba fatiu dödö niha bö''ö.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 18, 'Sambö tödö, ba falukha wa''owöhö; ba satua-tua, ba la''anaembu wa''aboto ba dödö.[2]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3405342, 'OT', 'Amaedola Zelomo', 14, 19, 'Si lö sökhi ba lötolalö mangalulu ba zi sökhi; ba sebua horö, ba mangalulu ba mbawa göli ba zatulö tödö.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 20, 'Ba zi numana, ba fa''udu göi zahatö khönia; ba somasi si so ana''a, ba no ato.[3]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 21, 'Si lö ba dödö awönia, ba no salalö; ba ya ahowu zi hakhösi tödö si göna famakao![4]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 22, 'Hadia, tenga selungu zamakhai si lö sökhi? Ba si falukha fa''omasi ba fa lö faröi zangalui si sökhi.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 23, 'Fefu ngawalö wa''erege dödö, ba mofozu; ba teatea mbewe andrö, ba isaŵa wa''anumana.[5]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 24, 'Ba niha satua-tua, ba saembu ana''a khöra gana''ara; ba fa lö tödö zi lö tödö andrö, ba ha sambalö fa lö tödö.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 25, 'Samaduhu''ö si duhu, ba no sangorifi niha; ba samalua si lö duhu, ba no si falimo.[6]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 26, 'Sangata''ufi Yehowa, ba no si so fanötöna si lö mangiwa; ba ono zi manö, ba no si so saŵatö.[7]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 27, 'Umbu wangorifi wangata''ufi Yehowa andrö, ena''ö lö alau ita ba gu''ö famunu.[8]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 28, 'Fa''ato niha, ba no lakhömi razo; ba na ambö niha, ba si lö boto zalaŵa.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 29, 'Ba zebolo tödö, ba no fahöna wa''atua-tua; ba ba zi ono wönutö, ba fa lö tödö lua-lua.[9]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 30, 'Fa''ebolo dödö, ba no fangorifi mboto, ba fa''afökhö dödö, ba no fa''obou döla.[10]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 31, 'Samalangögö si numana, ba i''o''aya Zomböi; ba si hakhösi tödö si numana, ba ifosumange Zomböi ya''ia.[11]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 32, 'Sebua horö, ba nituli''ö, ba wamakao andrö, si göna ia; ba satulö tödö, ba lö i''abusi tödö na''i wa''amate.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 33, 'Ba dödö zi so tödö andrö, ba no ahono wa''atua-tua; ba si so ba dödö zi lö tödö, ba oroma.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 34, 'Fa''atulö ba no fondrou''ö yaŵa nöri; ba fangailasi soi niha horö.', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405342, 'OT', 'Amaedola Zelomo', 14, 35, 'Enoni satua-tua, ba no fa''omasi razo; ba solau saila ita, ba göna fönu.[12]', '["Yob 18:14; F 12:7","Efes 5:15","Faigi 19:4–7","Sin 41:2","Faigi 10:4","Faigi 12:17","Faigi 18:10","Faigi 13:14","Faigi 16:32; 19:11","Faigi 12:4","Faigi 17:5; 19:17","MozI 41:38"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 1, 'Fanema li nihaogö, ba i''alösi wönu; ba fangandrö wönu wehede sabe''e.[1]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 2, 'Lela zatua-tua, ba ifalua wa''aboto ba dödö; ba ba mbawa zi lö tödö, ba mangumbu wa''owöhö mowa.[2]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 3, 'Fefu gofu heza, ba ikhamö hörö Yehowa, wamaigi-maigi si lö sökhi, awö zi sökhi.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 4, 'Fa''ehao lela andrö, ba no eu sowua fangorifi; ba fa''atefuyunia, ba mesokho bakha dödö ibe''e.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 5, 'Si lö tödö, ba i''ositengagö wotu andrö khö namania; ba sanöngöni fanegu, ba no satua-tua.[3]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 6, 'Ba nomo zatulö tödö, ba fahöna mbalazo; ba ba nisöndra zebua horö, ba faruka wangadudu.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 7, 'Bewe zatua-tua, ba ifazaewe wa''aboto ba dödö; ba tödö zi lö tödö, ba no tefuyu.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 8, 'Sumange nibe''e zebua horö, ba i''ogorofi Yehowa, ba fangandrö zadölö tödö, ba omasi ia.[4]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 9, 'Lala zebua horö andrö, ba ni''ogorofi Yehowa; ba solohi fa''atulö, ba i''omasi''ö.[5]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 10, 'Ba zondröi lala sadölö, ba te''abe''e''ö wotu; ba sogoro fotu, ba fa''amate fönania.[6]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 11, 'Narako ba awuwukha, ba i''ila-ila Yehowa, ba tenga mendrua manö i''ila-ila dödö nono niha![7]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 12, 'Sango''aya, ba lö omasi, na lategu ia; lö i''orudugö ia ba zatua-tua.[8]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 13, 'Na omuso dödö, ba ohahau göi mbawa; ba na so wa''abu dödö, ba aragu-ragu göi ia.[9]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 14, 'Tödö zatua-tua, ba i''alui wa''aboto ba dödö; ba bewe zi lö tödö, ba ilau waya-faya.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 15, 'Ba zi no göna famakao, ba lö baŵa si sökhi; ba ba zomuso tödö, ba ero ma''ökhö walöŵa.[10]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 16, 'Sökhi zi lö oya-oya, na fao wangata''ufi Yehowa, moroi ba zi no fahöna, na fao wa lö ahono dödö.[11]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 17, 'Sökhi zi samba figa höwa, na fao wa''omasi, moroi ba göröbao satabö, na fao watiusa.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 18, 'Si ono wönutö, ba ifobörö wasosota; ba sebolo tödö, ba ihonogö wagua-guasa.[12]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 19, 'Lala zareu, ba no hulö zi toba''a sa''a-sa''a mao; ba töröŵa zadölö tödö, ba no muhaogö.[13]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 20, 'Ono satua-tua, ba no fa''omuso dödö namania; ba niha si lö tödö, ba i''ositengagö ninania.[14]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 21, 'Si lö tödö, ba omuso dödö ba waya-faya; ba niha satua-tua, ba itörö lala sadölö.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 22, 'Na lö famagölö, ba tobali lö boto niŵa''ö; ba na ato zi so ba huhuo, ba mofozu.[15]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 23, 'Fa''omuso dödö niha mbewenia, wanema li nawönia; ba taroma li ba ginötö, ba ha lö asökhi!', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 24, 'Ba zatua-tua, ba miyaŵa isaŵa lala wangorifi andrö khönia, fa böi alua ia ba mbanua tou.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 25, 'Idudugö Yehowa nomo zi fayaŵa, ba i''aro''ö nola lakha mbanua.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 26, 'Ni''ogorofi Yehowa gera-era si lö sökhi; ba sökhi [iŵa''ö] wehede omasiö.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 27, 'Samohu fa''omasi gana''a, ba adudu nomonia ibe''e; ba sogoro femanga gana''a, ba isöndra wa''auri.[16]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 28, 'Tödö zatulö, ba i''alu-alui, he iwisa wanema li; ba moroi ba mbawa zebua horö, ba mangumbu zi lö sökhi.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 29, 'Ba zebua horö, ba aröu Yehowa; ba fangandrö zatulö tödö, ba ifondrondrongo.[17]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 30, 'Fangomuso dödö haga hörö, ba fangabe''e döla duria si sökhi.[18]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 31, 'Tögi dalinga samondrongo fanegu fangorifi, ba ba hunö niha satua-tua monahia.', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 32, 'Si lö ba dödö fotu, ba ya''ia i''ositengagö; ba samondrongo fanegu, ba isöndra wa''atua-tua.[19]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405682, 'OT', 'Amaedola Zelomo', 15, 33, 'Fangata''ufi Yehowa andrö, ba no famamaha ba wa''atua-tua, ba föna zumange, ba mowaö-waö wa lö fayaŵa.[20]', '["Ayati 18 RazI 12:13–16","Faigi 12:23","Ayati 32; Faigi 13:1","Ayati 29; Faigi 21:27; 28:9; MozI 4:4–5; Yes 1:11–15; Luk 18:9–14","Faigi 11:20","Faigi 10:17; 29:1","Yob 26:6; Sin 139:8; Yer 17:10","Faigi 9:8; 13:1","Ayati 15","Ayati 13; Faigi 17:22","Faigi 16:8; 17:1; Sin 37:16","Ayati 1; Faigi 26:21; 29:22","Faigi 24:30–31","Faigi 10:1","Faigi 11:14","Sin 15:5","Ayati 8 Yoh 9:31","Faigi 25:25","Ayati 5","Faigi 1:7; 18:12"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 1, 'Ba niha so nikhoi dödö; ba moroi khö Yehowa wanema li.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 2, 'Fefu lala niha, ba no si sökhi iŵa''ö tödönia; ba Yehowa zanulo tödö [niha].[1]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 3, 'Be''e balazi Yehowa wolau-laumö andrö; ba mofozu nikhoi dödöu.[2]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 4, 'Fefu hadia ia, ba Yehowa zamazökhi, so daninia; he göi sebua horö andrö, ba mbaŵa wamakao andrö.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 5, 'Dozi sebua hokha, ba ni''ogorofi Yehowa; da dangau! lö zi lö te''otu''ö ira.[3]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 6, 'Sulö golalöŵa wa''omasi ba fa lö faröi; ba famöhöi zi lö sökhi wangata''ufi Yehowa andrö.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 7, 'Na omasi Yehowa lala niha, ba i''atulö''ö göi khönia zi fa''udu khönia.[4] 8 Sökhi zi lö oya-oya, nisöndra ba wa''atulö, moroi ba hare sebua ba wa lö atulö.[5]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 9, 'Ikhoi tödönia lalania niha, ba Yehowa zamatörö bekania.[6]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 10, 'Taroma li faetasa zi so ba mbewe razo; böi ya mosala linia ba wangetu''ö huku.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 11, 'Faliera si lö angaya ba bulu waliera si sökhi, ba no khö Yehowa moroi; nilaunia fefu zaga ba dokosa.[7]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 12, 'Famazökhi si lö sökhi, ba la''ogorofi salaŵa; fa''atulö sa wangarö dadaomara.[8]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 13, 'Bewe satulö zomasi razo; ba solau fehede sadölö, da''ö ni''omasi''öra.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 14, 'Fönu razo, ba no timba zinenge solohe fa''amate; ba satua-tua, ba i''ila i''alösi.[9]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 15, 'Ba wehaga hörö razo so wangorifi, ba fa''omasinia, ba no hulö lawuo ba deu sahulö.[10]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 16, 'Sökhi na tasöndra wa''atua-tua, moroi na tasöndra gana''a; ba fanöndra fa''aboto ba dödö, ba no sökhi moroi ba wanöndra firö.[11]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 17, 'Lala zatulö tödö, ba no famöhöi si lö sökhi; ba samaigi-maigi lalania, ba irorogö nosonia.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 18, 'Föna wa''atekiko mowaö-waö wayaŵasa; ba föna wa''alau, ba hokha.[12]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 19, 'Sökhi na ta''ide-ide''ö ita, awö zi lö fayaŵasa, moroi na tatema dana khöda nirabu, awö sebua hokha.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 20, 'Sanöngöni taroma li andrö, ba isöndra wa''ohahau dödö; ba sanötöna khö Yehowa, ba ya ahowu!', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 21, 'Si so fa''aboto ba dödö, ba lafotöi satua-tua; ba ba wa''ami mbewe, ba tedou wamahaö.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 22, 'Umbu wangorifi wa''aboto ba dödö, ba zi so ia; ba fotu zi lö tödö wa''owöhö mowa andrö.[13]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 23, 'Tödö zatua-tua andrö, ba onekhe mbawa ibe''e, ba idou''ö wamahaö ba mbewenia.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 24, 'Awa''awa ŵe ŵani wehede omasiö, ami ba dödö ba no dalu-dalu ba nösi.[14]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 25, 'So lala si no adölö taŵa''ö, ba lua-luania, ba no lala ba wa''amate.[15]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 26, 'Fa''olofo zohalöŵö zangai halöŵönia, i''o''ou sa''ae ia tölö-tölönia.[16]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 27, 'Niha si lö ngaroro, ba ikharu wamakiko; ba ba mbewenia, ba no hulö galitö sihola-hola.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 28, 'Niha si falimolimo, ba ifobörö wa''udusa; ba samatou awönia, ba ifabali göi zabölö fahuwusa.[17]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 29, 'Samalangögö awönia, ba ifowöhö zahatö khönia, i''ohe ba lala si lö sökhi.[18]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 30, 'Samakifu hörönia, ba no samakhai falimosa; ba songanga bewenia, ba no ifazökhi zi lö sökhi.[19]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 31, 'Saembu lakhömi huwa andrö, ba lala satulö tesöndra ia.[20]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 32, 'Yaŵa zabölö zebolo tödö; ba sangila mangöhöndrögö tödönia, ba no yaŵa zatu''a ba mbanua nisuwönia.[21]', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405683, 'OT', 'Amaedola Zelomo', 16, 33, 'Dahö-dahö andrö, ba lalau ba gaheta, ba moroi khö Yehowa fefu wa''agöna.', '["Faigi 21:2","Sin 37:5","Faigi 11:21","MozI 31:24; 33:4","Faigi 15:16","Faigi 19:21","Faigi 11:1","Faigi 20:28; 25:5; 29:14","Faigi 20:2","Faigi 19:12","Faigi 3:14; 8:10; 11:19","Faigi 18:12","Faigi 13:14; 14:27","Faigi 12:25","Faigi 14:12","Faigi 18:7","Faigi 6:14–19","Faigi 1:10–14","Faigi 6:13","Faigi 20:29","Faigi 14:29"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 1, 'Sökhi zi sambawa kue, si lö awö-awö, na fao wa''atulö, moroi na afönu nomo öröbao, na fao wasosota.[1]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 2, 'Sawuyu satua-tua, ba tobali samatörö ono zokhö ya''ia, solau saila ita; ba motana khö, na lafosasi khöra gondröita si fatalifusö.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 3, 'Famahele wirö duga lawu ba fanunu gana''a galitö; ba sanandraigö tödö niha, ba ya''ia Yehowa.[2]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 4, 'Sanao horö, ba ifondrongondrongo mbewe si lö sökhi; irongo waya ba lela famakiko.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 5, 'Si igi''igi''ö si numana, ba i''o''aya Zomböi; ba somuso tödö ba wamakao nawönia, ba lö zi lö te''otu''ö.[3]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 6, 'Saembu zatua ma''uwu, ba lakhömi namara ndraono.[4]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 7, 'Khö zi lö tödö, ba lö moadu wehede hokha, ba mendrua manö lö moadu mbewe sofaya ba zalaŵa.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 8, 'Amaedola mani-mani omasi''ö gö horö ba zanema ya''ia, iŵa''ö; gofu heza isaŵa, ba mofozu nilaunia.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 9, 'Sangalui fa''omasi zamalugö olalöŵa; ba si fuli mamokai huhuo, ba fa''ero dödö zi fahuwu ibe''e.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 10, 'Ba zi so tödö, ba abakha göna wanegu li, moroi na meotu tohare mbözi-bözi ba zi lö tödö.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 11, 'Ha sambalö si lö sökhi ifa''ua solaŵa salaŵa; ba lafatenge khönia zinenge si lö fa''ahakhö dödö.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 12, 'Alakha falukha ita zi alawe mberua, si no lahalö ono, ba böi ba zi lö tödö ba wa''owöhö mowa andrö khönia.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 13, 'Na so zame''e sulö zi sökhi si lö sökhi, ba lö tebato yomo khönia wamakao.[5]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 14, 'Böröta wasosota, ba no hulö na tatöla''ö mba''a-ba''a nidanö; andrö bato wasosota, fatua lö oroma nifö.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 15, 'Samu''a horö ba hulu zi so sala ba sangetu''ö huku zi lö horö, ba i''ogorofi Yehowa, faoma darua ira.[6]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 16, 'Hadia sa guna gana''a ba danga zi lö tödö, ba wowöli fa''atua-tua; me lö''ö sa atö fa''aboto ba dödö.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 17, 'Si ndruhu si fahuwu, ba no fadoro i''omasi''ö nawönia; ba ba wamakao, ba tumbu ia si fatalifusö.[7]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 18, 'Niha si lö tödö zi fara''u tanga, si möi ba wali khö nawönia.[8]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3405685, 'OT', 'Amaedola Zelomo', 17, 19, 'Somasi fasosota, ba i''omasi''ö horö; ba sangalaŵa''ö bawandruhö khönia, ba no sangalui fa''adudu.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 20, 'Si no tefuyu tödö, ba lö isöndra wa''ohahau dödö; ba sabila lela, ba falukha wa''ate''ala.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 21, 'So''ono si lö tödö, ba falukha wa''abu dödö, ba tebai omuso dödö nama zowöhö mowa.[9]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 22, 'Fa''omuso dödö, ba tobali fangorifi; ba fa''arasa dödö andrö, ba oköli döla ibe''e.[10]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 23, 'Sebua horö, ba i''a gana''a, nibini''ö fame''e, ba wamila''ö lala satulö.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 24, 'Ba zi so fa''aboto ba dödö, ba no so ba duduma hörö wa''atua-tua; ba si lö tödö, ba fondrege danö ifaigi.[11]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 25, 'Ono si lö tödö, ba fangabu dödö namania, ba fa''alangu dödö zadono ya''ia.[12]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 26, 'Na lakhau göi zi lö horö, ba si lö sökhi da''ö, ba mendrua manö, na labözi zatulö tödö.', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 27, 'Sanaha bewenia, ba no si so fa''aboto ba dödö; ba sebolo tödö, ba no niha si so era-era.[13]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405685, 'OT', 'Amaedola Zelomo', 17, 28, 'He si lö tödö, na lö hede-hede, ba satua-tua taŵa''ö; si so tödö wamaigida, na lö ifonumalö mbewenia.[14]', '["Faigi 15:17; 16:18","Sin 66:10","Faigi 14:31","Sin 128:6","Sin 109:5","Yes 5:23","Faigi 18:24","Faigi 6:1","Faigi 10:1","Faigi 15:13–15","Faigi 4:25","Ayati 21","Faigi 10:19; Yak 1:19","Yob 13:5"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 1, 'Si oniagö ya''ia, ba ha somasi ia i''alui; ba fefu hadia ia zaboto ba dödöda, ba fatuwu khönia.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 2, 'Si lö tödö, ba lö omasi wa''aboto ba dödö; ha da''ö zomasi ia, na oroma gera-erania.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 3, 'Na so zebua horö, ba fago''ö wango''aya, ba awö wa''aila wanandraŵa.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 4, 'Idanö sabakha daroma li, si otarai mbawa niha, mbombo sangumbungumbu, umbu wa''atua-tua.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 5, 'Lö sökhi na fa''awö ita ba zebua horö, ba wamalangögö satulö, ba wangetu''ö huku.[1].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 6, 'Bewe zi lö tödö, ba no samobörö fasosota, ba sangandrö bözi-bözi mbawania.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 7, 'Bawa zi lö tödö, ba tobali fama''alania, ba bewenia, ba no tandraŵa nosonia.[2].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 8, 'Taroma li zamatou awönia, ba no hulö gö sami, numalö mitou ba dalu bakha.[3].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 9, 'He sambö fa''atarö dödö ba halöŵönia, ba no akhi zamufu.[4].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 10, 'Hati saro döi Yehowa andrö, ba da''ö isaŵa satulö tödö, ba tebai lakhamö ia.[5].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 11, 'Ana''a zi so ana''a, ba no banua saro khönia; öli kara si no alaŵa iŵa''ö tödönia.[6].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 12, 'Föna wa''atekiko niha wayaŵasa dödö; ba föna zumange, ba fa lö fayaŵa.[7].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 13, 'Na so zanema li, na lö nifondrondrongonia, ba tebe''e falötödö ba fangaila khönia.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 14, 'Fa''abe''e dödö ba niha, ba itaögö wökhö; ba fa''arasa dödö, ba ha niha zanaha?[8].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 15, 'Tödö zi so tödö, ba isöndra wa''atua-tua, ba tögi dalinga zatua-tua, ba i''alui wa''aboto ba dödö.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 16, 'Buala niha zamonaha ya''ia, i''ohe ia ba ngai zalaŵa.[9].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 17, 'Si föföna molohe ba huhuo hadia ia, ba khönia zatulö taŵa''ö, ba so si samösa, ba isekhegö ia.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 18, 'Dahö-dahö wolohe ba lala wagua-guasa, fa''ero zabölö ibe''e.[10].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 19, 'Talifusö si no mulimo, ba abe''e moroi ba mbanua saro, ba fagua-guasa, ba no hulö lazi ba mbawandruhö ba gödo.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 20, 'Bua-bua mbawania, ba no fangabuso dalu niha; i''abusoi''ö ia lua-lua mbewenia.[11].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 21, 'Fa''amate ba fa''auri, ba no faoma so ba wa''abölö lela; ba somasi ya''ia, ba i''a mbuania.[12].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 22, 'Si no manöndra ira alawe, ba no isöndra zi sökhi, ba no falukha ia wa''ebua dödö Yehowa.[13].', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 23, 'Si fakao zi numana, ba fanema li, na itema so''ana''a, ba no fehede zafaito.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405689, 'OT', 'Amaedola Zelomo', 18, 24, 'Ba zi no ato zi fahuwu, ba no ahatö wa''ate''ala; ba so zi fahuwu saro moroi ba zi fatalifusö.', '["MozV 1:17","Faigi 13:3; 16:26","Faigi 26:22","Faigi 10:4","Faigi 14:26; Sin 20:2","Faigi 10:15","Faigi 16:18; 15:33","Faigi 15:13–15","MozI 43:11","Faigi 16:33","Faigi 12:14; 13:2","Faigi 13:3","Faigi 19:14; 31:10"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 1, 'Sökhi zi numana, sanörö lalania, lö sinegu, moroi ba zi tefuyu bewe ba si lö tödö.[1]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 2, 'Ba wa''ambö wa''aboto ba dödö, ba lö si sökhi; ba ba zi lö fangenanö ba wofanö, ba fasala wamekai.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 3, 'Ba walötödö ba niha tefuyu lalania, ba abao dania dödönia khö Yehowa.[2]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 4, 'Ato zi fahuwu ibe''e ana''a, ba si numana, ba i''erogö si fahuwu khönia.[3]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 5, 'Sasi sofaya, ba lö zi lö te''otu''ö, ba solau si lö duhu, ba tebai aefa.[4]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 6, 'Ato zangalui fa''ebua dödö zalaŵa, ba ba zame''e-me''e buala, ba oi dozi fahuwu niha.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 7, 'Ba zi numana, ba oi fa''udu zi fatalifusö khönia, ba tenga mendrua manö la''erogö ia si fahuwu khönia [ena''ö]. Ba na ifati niŵa''öra, ba si lö boto.[5]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 8, 'Sangalui fa''aboto ba dödö, ba i''omasi''ö nosonia, ba samaigi era-era dödö, ba isöndra wa''ohahau dödö.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 9, 'Sasi sofaya, ba lö zi lö te''otu''ö, ba solau si lö duhu, ba tekiko.[6]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 10, 'Ba zi lö tödö, ba no tenga si nangea wa''ohahau dödö, ba mendrua manö tenga si nangea, na möi samatörö salaŵa zawuyu.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 11, 'Fa''aboto ba dödö andrö, ba ebolo dödö niha ibe''e; ba teturia ia, na ibologö dödönia ba golalöŵa.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 12, 'Fa''abao dödö razo, ba no hulö wendröndröndröndrö zingo; ba fa''omasinia, ba no hulö namo mbanua ba zinanö.[7]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 13, 'Ono matua si lö tödö, ba no famakuyu namania; ba no taŵa gahe zagö si lö aetu wasosota ndra alawe.[8]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 14, 'Omo ba ana''a, ba no ondröita zatua; ba khö Yehowa moroi ndra alawe si so fa''aboto ba dödö.[9]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 15, 'Fa''areu andrö, ba abölö wemörö ibe''e; ba si lö mohalöŵö, ba solofo dania.[10]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 16, 'Same''e ba dödö oroisa, ba ibe''e ba dödö nosonia; ba si lö mamaigi lalania, ba tekiko.[11]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 17, 'Si hakhösi tödö si numana, ba khö Yehowa ibe''e nifalali, ba ya''ia zanulöni khönia fa''ebua dödönia andrö.[12]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 18, 'Otu''ö nonou; so na sa wanötöna; ba böi fonumalö dödöu ba wamunu ya''ia.[13]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 19, 'Si ono wönutö, ba ibu''a gogauta; na ötenaŵa, ba tedou öbe''e.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 20, 'Fondrondrongo wamolala tödö, ba tema wanegu, ena''ö atua-tua''ö sa''ae.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 21, 'Oya ngawalö nikhoi dödö niha; ba nikhoi Yehowa zofozu.[14]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 22, 'Somasi niha, ba fa''ebua dödönia; ba no sökhi zi numana, moroi ba zolau faya.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 23, 'Fangata''ufi Yehowa andrö, ba tobali fangorifi; möröi ta, lö fa''olofo, lö itörö famakao.[15]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 24, 'Na no irugi wiga tanga zareu; ba tebai na''i ifuli ba mbawania.[16]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 25, 'Na öbago zango''aya, ba atua-tua zi no owöhö-wöhö; ba na tategu zi so tödö, ba isöndra wa''aboto ba dödö.[17]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 26, 'Samakao amania ba samofanö inania, ba no ono samobörö fa''aila ba fango''aya.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 27, 'Bato wamondrongo fotu, ya''ugö onogu, ba wa''elungu, ba wamöhöi famahaö zaboto ba dödö.[18]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 28, 'Sasi si lö boto, ba i''o''aya huku; ba isowo zi lö atulö bawa zebua horö.', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3405696, 'OT', 'Amaedola Zelomo', 19, 29, 'Ba zango''aya andrö, ba no muhönagö mo''e''asiwai wotu, ba si manö mbözi-bözi ba hulu zi lö tödö.[19]', '["Faigi 28:6","Ngen Yer 3:29","Faigi 14:20","Ayati 9; Faigi 21:28; MozV 19:18–21","Ayati 4","Ayati 5","Faigi 20:2; 16:14–15","Faigi 10:1","Faigi 18:22","Faigi 10:4; 23:1","Faigi 16:17","Faigi 14:31; Sin 41:2–4; Mat 25:40","Efes 6:4","Faigi 16:9; Yer 10:23","Faigi 14:27","Faigi 26:15","Faigi 21:17","Yak 1:22","Faigi 26:3"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 1, 'No sango''aya nagu andrö ba si fagua-gua zi mabu ita; dozi ha niha zi mabu-mabu da''ö, ba tebai atua-tua.[1]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 2, 'Fameta''u zalaŵa, ba no hulö wendröndröndröndrö zingo; ha niha zangandrö fönunia, ba no sama''ua famunu.[2]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 3, 'I''ebua''ö duriania niha, na lö ihatö''ö ia ba wasosota; ba ha niha zi lö tödö, ba no somasi fagua-guasa.', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 4, 'Sareu, ba lö mangahalö na baŵa, ba na idöna-döna dania mbua nowi, na baŵa wamasi, ba lö hadia ia.[3]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 5, 'Idanö sabakha nikhoi dödö niha barö doto, ba si so tödö, ba isousou yaŵa.[4]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 6, 'Ahatö dozi niha falukha zebua tödö, ba ha niha zanöndra niha si lö faröi?', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 7, 'Na so zatulö tödö, sanörö lalania lö sinegu, ba falukha wa''ohahau dödö nononia furinia.[5]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 8, 'Razo sidadao ba dadaoma wanguhuku, ba ifazawili fefu zi lö sökhi, hörönia.[6]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 9, 'Ha niha zi tola manguma''ö: "No uhaogö dödögu; no aheta horögu?"[7]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 10, 'Dombua zaga ba dombua zu''a-zu''a, ba no faoma ni''ogorofi Yehowa.[8]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 11, 'Su''a nono matua sa''ae, ba oroma ba mbua-buania, na sohau-hau ba na sadölö dödönia.[9]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 12, 'Tögi dalinga samondrongo ba hörö sangila niha, ba faoma niwöwöi Yehowa.', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 13, 'Böi omasi''ö wemörö, fa böi numana ndra''ugö; faboka höröu, ba lö ambö göu.[10]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 14, '"Si lö sökhi! si lö sökhi!" iŵa''ö sowöli; ba na no aefa ia, ba isuno ia.', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 15, 'So sa gana''a, ba no fahöna mani-mani, ba aya sebua böi mbewe si so fa''aboto ba dödö.', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 16, 'Na so zi möi ba wali ba niha bö''ö, ba halö mbarunia, ba halö gade khönia, börö niha bö''ö andrö.[11]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 17, 'Ami ba mbawa niha gö nilimo, ba dania ba fazozo ba mbawania nene.[12]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 18, 'Lua-lua wamagölö nihonogöi, ba haogö wamatörö, na manuwö''ö.', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 19, 'Samokai si tobini, ba no sanandraŵaisi awönia; andrö böi fabaya ndra''ugö ba zoya bewe.[13]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 20, 'Sangelifi amania ba inania, ba no si mate fandru ba dalu zogömi-gömi.[14]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 21, 'Ondröita, nikhamö ba wa''aösö wamobörö, ba lö howu-howu ba gafuriata.', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 22, 'Böi ŵa''ö; "Usulöni zi lö sökhi"; döna-döna khö Yehowa, ba itolo''ö.[15]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 23, 'Famodombua saga ba i''ogorofi Yehowa, ba si lö sökhi waliera falimosa.[16]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 24, 'Yehowa zanguhuku beka niha; ba niha andrö — he moroi wa''aboto ba dödönia lalania?', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 25, 'Tandraŵa niha, na iŵa''ö manö: "Ni''amoni''ö", ba na awena itulo tödönia, na no awai ifabu''u.', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 26, 'Razo satua-tua, ba ifazawili zebua horö, ba ifatörö khöra gaolo wamöbörö wakhe.[17]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 27, 'Fandru nitunu Yehowa dödö niha, isului mbate''e mboto fefu.[18]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 28, 'Nöu razo wa''omasi ba fa lö faröi; ba ibe''e tuwutuwu dadaomania wa''omasi andrö.[19]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 29, 'Lakhömi nono matua wa''abölöra; ba aya zatua, ba huwa andrö.[20]', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476164, 'OT', 'Amaedola Zelomo', 20, 30, 'Fangeheta zi lö sökhi zokho sendro ba bözi-bözi sanösö ösi, irege ba zabakha.', '["Faigi 23:29–35; 31:5","Faigi 16:14; 19:12","Faigi 6:6–8","Faigi 18:4","Faigi 14:26; Sin 112:2","Sin 101:3–8","Faigi 28:13; 30:12","Ayati 23; Faigi 11:1","Faigi 22:6","Faigi 6:10","Faigi 6:1–5; 27:13","Faigi 9:17","Faigi 24:6","MozII 21:17","Faigi 24:29; Rom 12:17–19","Ayati 10","Sin 101:8","KorI 2:11","Faigi 16:12","Faigi 16:31"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 1, 'Amaedola nidanö ba mbombo dödö razo, ba danga Yehowa; ba zomasi ia ifatörö, fefu gofu heza.[1]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 2, 'Ba wamaigi niha, ba no adölö lalania fefu; ba Yehowa zanulo tödö [niha].[2]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 3, 'Folau satulö ba sadölö zomasi Yehowa, moroi ba zumange nitaba.[3]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 4, 'Hokha hörö ba fayaŵasa dödö — fangahalö zebua horö, ba no horö.[4]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 5, 'Lua-lua nikhoi dödö zowölö-ölö, ba no hare; ba ba zi da''i-da''i manö, ba isaŵa wa''ate''ala.[5]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 6, 'Ana''a nisöndra ba walimosa, ba no angi, ba zangalui famunu.[6]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 7, 'Famalangögö zebua horö awöra, ba i''oloi''ö ira, me no tekhöra wolau satulö.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476165, 'OT', 'Amaedola Zelomo', 21, 8, 'Lala niha sonoro horö, ba no akiŵö-kiŵö; ba sohau-hau tödö, ba satulö ilau.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 9, 'Sökhi na ba mbumbu nomo yaŵa so ita, moroi na orudu ita yomo ba ndra alawe si fasoso-soso.[7]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 10, 'Tödö zebua horö, ba no somasi si lö sökhi; lö falukha nawönia wa''ahakhö dödö khönia.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 11, 'Na la''otu''ö zango''aya, ba atua-tua zi no adölö tödö; ba na lafahaö zatua-tua, ba ihalö khönia wa''aboto ba dödö.[8]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 12, 'Satulö (Lowalangi) zamaigi-maigi omo zebua horö; göna fa''atekiko zebua horö ibe''e.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 13, 'Sondruhö tögi dalingania ba wangarö-ngarö zi numana, ba lö''ö göi tefondrondrongo linia, na baŵa mangarö-ngarö ia.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 14, 'Fangalösi wönu game''ela si lö mu''oroma''ö, ba famadöhö wa''abao dödö mbuala nibini''ö ba nono mbaru.[9]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 15, 'Ba zatulö tödö, ba fa''omuso dödö wolau satulö; ba ba zolau si lö sökhi, ba sata''u ira.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 16, 'Niha sondröi lala wa''atua-tua, ba ba zorudu bekhu zi mate ahono dania.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 17, 'Somasi fangomuso dödö, ba numana dania; ba somasi agu ba fanikha samohua, ba lö isöndra wo''ana''a.[10]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 18, 'Höli zatulö tödö dania zebua horö, ba fangali zadölö tödö zi faröi.[11]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 19, 'Sökhi na ba danö si mate so nomoda, moroi na so khöda ndra alawe si fasoso-soso ba sofönu-fönu.[12]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 20, 'Girö-girö omasiö ba fanikha zi so ba nomo zatua-tua; ba niha si lö tödö, ba zumaewe ibe''e.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 21, 'Solohi fa''atulö ba fa''ebua dödö, ba isöndra wa''auri ba fa''atulö dödö ba fa''ebua döi.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 22, 'Satua-tua andrö, ba atu''a ba mbanua zabölö, ba idudugö göli, si no abe''e dödöra.[13]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 23, 'Sanaro bewenia, awö lelania, ba lö göna ia famakao ibe''e.[14]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 24, 'Si fayaŵa ba sebua hokha, ba lafotöi sango''aya, solau hokha si tenga inötö.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 25, 'Ba zareu, ba tobali famunu wangisönia, me lö edöna mohalöŵö dangania.[15]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 26, 'Si lö aetu wangisö zareu; ba satulö tödö, ba mame''e; lö fa''atali.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 27, 'Sumange nibe''e zebua horö, ba no ni''ogorofi Yehowa; ba mendrua manö, na horö mbörö wame''e ya''ia.[16]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 28, 'Sasi sofaya, ba tekiko dania, ba fehede zamondrongo li, ba si möna.[17]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 29, 'Sabe''e bawa zebua horö; ba satulö tödö, ba ifaigi heza itörö.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 30, 'Lö fa''atua-tua ba lö fa''aboto ba dödö ba lö nikhoi dödö, solaŵa Yehowa.', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476165, 'OT', 'Amaedola Zelomo', 21, 31, 'Lafangaro kudo, na baŵa wanuwö, ba femöna, ba khö Yehowa moroi.[18]', '["Sin 33:15","Faigi 16:2; 24:12","SamI 15:22; Yes 1:11–18; Hos 6:6","Yes 2:11","Faigi 22:29","Faigi 10:2","Ayati 19; Faigi 25:24","Faigi 19:25","SamI 25:18","Faigi 23:21","Faigi 11:8","Ayati 9","Faigi 24:5","Faigi 13:3","Faigi 13:4","Faigi 15:8","Faigi 19:5,9","Sin 33:12; Yes 31:1,3"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 1, 'Sebua böli döi si sökhi moroi ba gana''a sebua, ba si sökhi moroi ba wirö ba moroi ba mbalaki wa''ebua dödö.[1]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 2, 'Falukha ira zo''ana''a zi numana; somböi ya''ira fefu, ba ya''ia Yehowa.', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 3, 'Satua-tua, ba i''ila wamakao, ba ibini''ö ia; ba sowöhö-wöhö, ba latörö manö, ba te''ala.[2]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 4, 'Luo wa lö fayaŵa, luo wangata''ufi Yehowa, ba fa''ebua gana''a ba fa''ebua döi ba fa''auri.', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 5, 'Ba lala zabila tödö, ba so ndroi ba so wesu gahe; ba sondrorogö nosonia, ba ihene.', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 6, 'Fahaö nono matua, faigi ginötö; ba lö''ö göi iböhöli, na satua ia.[3]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 7, 'Samatörö si numana zo''ana''a; ba samalali ana''a, ba tobali sawuyu zame''e nifalali.', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 8, 'Sanaru si lö atulö, ba ibasi wamakiko; ba bözi-bözinia, na mofönu ia, ba ariri.[4]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 9, 'Si sökhi tödö, ba falukha howu-howu; me ikhete ö zi numana mbalazonia.[5]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 10, 'Fofanö zango''aya, ba fao khönia wasosota; ba tebato wagua-guasa ba fangaila.[6]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 11, 'Somasi fa''ohau-hau dödö, si so bewe omasiö, khönia fahuwu razo.[7]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 12, 'Hörö Yehowa zondrorogö fa''aboto ba dödö; ba fehede zi faröi andrö, ba lö boto ibe''e.', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 13, 'Imane zareu; "So zingo baero, ma dania nibunu ndra''o ba golayama."[8]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 14, 'Kohokoho sabakha mbawa ndra alawe bö''ö, ba da''ö bakha alau zofönu Yehowa.[9]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 15, 'Ba dödö nono matua, ba no faböbö wa''owöhö mowa; ba bözi-bözi fangotu''ö wameta ya''ia khönia.[10]', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 16, 'Na lafakao zi numana, ba mohare ia; ba na mame''e ba zo''ana''a, ba fa''ate''alania.', '["Sangomb 7:1","Faigi 27:12","Faigi 20:11","Yob 4:8","Faigi 19:17","Faigi 26:20; MozI 21:9,10","Sin 101:6","Faigi 26:13","Faigi 5:3,4; 23:27","Faigi 23:14; 29:17"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 17, 'Be''e mbörö dalingau ba fondrondrongo, li zatua-tua ba faudugö tödöu wa''aboto ba dödögu andrö.', '[]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 18, 'Sökhi sa, na ö''irö''ö ba dödöu; ena''ö na lö awu''a ia fefu, ba mbeweu.', '[]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 19, 'Ena''ö manötöna ndra''ugö khö Yehowa, ba da''ö ufahaö ndra''ugö ma''ökhö, ya''ugö nifahaögu.', '[]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 20, 'Hadia, tenga si sökhi nisuragu khöu, famobawa lala ba famotokhi?', '[]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 21, 'Ena''ö ufarongogö khöu zi duhu, taroma li saro, fa ö''ohe li salakha lö mangiwa dödö, ba zamatenge ya''ugö.', '[]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 22, 'Böi osindra''ui zi so khö zi numana, me no si numana ia, ba böi hundragö zi no göna famakao, ba mbawa göli.', '["Faigi 23:11","Faigi 29:22","Faigi 6:1","Faigi 23:10; MozV 27:17","Faigi 21:5"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 23, 'Yehowa sa zolohe ba lala huhuora, ba i''etu''ö noso zi anagöi ya''ira.[11]', '["Faigi 23:11","Faigi 29:22","Faigi 6:1","Faigi 23:10; MozV 27:17","Faigi 21:5"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 24, 'Böi ae awö zofönu-fönu, ba böi fao-fao ndra''ugö ba zi ono wönutö.[12]', '["Faigi 23:11","Faigi 29:22","Faigi 6:1","Faigi 23:10; MozV 27:17","Faigi 21:5"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 25, 'Fa böi öfamaha ndra''ugö ba nitörönia andrö, ba fa böi öwöwöi dandraŵa wamunumö.', '["Faigi 23:11","Faigi 29:22","Faigi 6:1","Faigi 23:10; MozV 27:17","Faigi 21:5"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 26, 'Böi orudugö ndra''ugö ba zi fara''ura''u tanga, ba zi möi ba wali ba gömö.[13]', '["Faigi 23:11","Faigi 29:22","Faigi 6:1","Faigi 23:10; MozV 27:17","Faigi 21:5"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 27, 'Na lö khöu famu''a gömö dania, ba hana wa ölulu dofou baröu?', '["Faigi 23:11","Faigi 29:22","Faigi 6:1","Faigi 23:10; MozV 27:17","Faigi 21:5"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 28, 'Böi wu''ai nola föna, nitaru''ö ndra tuau.[14]', '["Faigi 23:11","Faigi 29:22","Faigi 6:1","Faigi 23:10; MozV 27:17","Faigi 21:5"]', NULL),
  (3476166, 'OT', 'Amaedola Zelomo', 22, 29, 'Na ö''ila niha satarö tödö ba halöŵönia, ba tola möi ia enoni razo, alakha lö möi ia ba zi lö töi.[15]', '["Faigi 23:11","Faigi 29:22","Faigi 6:1","Faigi 23:10; MozV 27:17","Faigi 21:5"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 1, 'Na mudadao ndra''ugö ba wemanga, ba böi olifugö''ö ha niha zi so ba ngaiu.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 2, 'Ba faudugö zi''öli ba dödötölöu, na sanani ndra''ugö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 3, 'Böi isö zami andrö khönia, me no ö si falimo.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 4, 'Böi eregeisi dödöu, ba wangebua ana''a; böhöli wa''onekheu andrö.[1]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 5, 'Hadia, edöna öfaigi-faigi ia, ba no tobali angi? Lö zi lö ifaigi khönia gafi, si mane afi moyo, si saŵa banua si yaŵa.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 6, 'Böi a gö nibe''e zafökhö tödö, ba böi isö zami andrö khönia.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 7, 'Hulö zamatou-tou tödönia ia; imane khöu: A! badu! ba lö fao dödönia khöu.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 8, 'Si no ö''a, ba öfuli ö''uta''ö; ba hadia zi no öhaogö fehedeu, ba no zaya-zaya gölö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 9, 'Böi farongogö ba zi lö tödö wehedeu; lö''ö sa atö ba dödönia wa''atua-tua andrö ba daroma limö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 10, 'Böi wu''ai nola föna, ba böi hundragö mbenua zi lö ama.[2]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 11, 'Me no sabölö zangorifi ya''ira — ya''ia zolohe ba lala huhuora khöu.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 12, 'Lulu dödöu ba wotu, ba be''e mbörö dalingau ba wehede si so fa''aboto ba dödö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 13, 'Böi ambösi wotu ba nono matua; lö''ö sa mate ia, na öhare''ö khönia nue.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 14, 'Öbözi sa ia ue, ba tobali ö''efa''ö mbekhunia ba narako.[3]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 15, 'He onogu, na atua-tua dödöu, ba omuso göi dödögu.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 16, 'Ba owua-wua bakha mbuagu, na satulö ilau beweu.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 17, 'Böi afökhö dödöu ba zamazökhi horö; fangata''ufi Yehowa onorogöi tödö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 18, 'Si ndruhu, so na sa zi so fönada, ba tenga faya wanötönamö andrö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 19, 'Fondrondrongo, ya''ugö onogu, ba ya atua-tua ndra''ugö, ba faudugö tödöu lala sadölö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 20, 'Böi orudu ndra''ugö ba zamadu-madu tuo ba ba zolu''a-lu''asi diwo.[4]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 21, 'Numana sa dania zamadu-madu tuo, fabaya solu''a-lu''a, ba lua-lua wemörö-mörö, ba fa hatö atuala nukha.[5]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 22, 'Fondrondrongo li namau so''ono ya''ugö, ba böi ositengagö ninau, na atua ia.[6]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 23, 'Si duhu öli, ba böi fuli amawa, fa''atua-tua ba fangenanö ba fa''aboto ba dödö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 24, 'Owua-wua sibai dödö zi so''ono satulö tödö; ba si no mo''ono satua-tua, ba omuso dödö khönia.[7]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 25, 'Ya omuso dödö ndra amau inau, ba ya owua-wua dödö zadono ya''ugö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 26, 'Khögu be''e dödöu, ya''ugö onogu, ba ya omasi höröu lala andrö khögu.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 27, 'Kohokoho sabakha sa ndra alawe somasi fohorö, ba ba''a side-ide bawa ndra alawe bö''ö.[8]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 28, 'Sanaro-naro ia, si mane sorabu, ba ato zi faröi niha ibe''e.[9]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 29, 'Ha khö so wa''alai? Ha khö so wa''afa''aökö? ha khö so wasosota? ha khö so wangarö-ngarö? ha niha zesokho, lö börö-börö? ha niha zi ndrundrumö hörö?', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 30, 'Ya''ia zi bongisi wamadu-madu tuo, si möi ba wanandra nifolaru.[10]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 31, 'Böi faigi-faigi duo, na no oyo''oyo, na si takile ia ba mako, na sökhi wa''ahele ba dölö-tölö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 32, 'Ba lua-luania, ba si fara''u ia, hulö gulö, si fa''usu, hulö gö''ö.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 33, 'Si tenga inötö i''ila dania höröu, ba si fakuyu ilau tödöu.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 34, 'Ba hulö zi mörö ba dalu nasi ndra''ugö, ba hulö zi mörö ba mbalö döla loyo.', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476167, 'OT', 'Amaedola Zelomo', 23, 35, '"No labözi-bözido, ba lö safökhö khögu; no labago-bagodo, ba lö u''ila. Ha wa''ara tokeado? Ba utohugö wolau zui."[11]', '["Faigi 28:22; Sangomb 9:11","Faigi 22:28","Faigi 13:24; 22:15","Luk 21:34","Ayati 25–35; Faigi 21:17; 20:13","Faigi 1:8","Faigi 10:1","Faigi 22:14","Faigi 7:12","Faigi 20:1; Yes 5:11,22","Yes 56:12"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 1, 'Böi afökhö dödöu ba niha si lö sökhi tödö, ba böi omasi ndra''ugö, möi''ö awöra.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 2, 'Famalangögö awöra sa zomasi dödöra, ba famakao nilau mbewera.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 3, 'Fa''atua-tua wangotomosi nomo, ba era-era ba dödö wangaronia.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 4, 'Ba fa''aboto ba dödö wamo''ösi naha girö-girö, girö-girö sebua böli ba girö-girö omasiö.[1]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 5, 'Sabölö niha satua-tua, ba ba niha si so fa''aboto ba dödö, ba oi so wa''abe''e.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 6, 'Na sökhi wamatörö, ba möna ndra''ugö ba wanuwö; ba ba zi lö ambö samolala tödö, ba so wangorifi.[2]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 7, 'Si lö tödö, ba lö ikhamö wa''atua-tua, ba lö hede-hedenia ba mbawa göli.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 8, 'Sangalui folau si lö sökhi, ba lafotöi sanao horö.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 9, 'Fa''owöhö mowa horö andrö, ba sogoro niha bö''ö zango''aya.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 10, 'Na hulö zi lö döladöla ndra''ugö, na baŵa wamakao, ba si lö boto wa''abölöu.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 11, 'Orifi nisöbi ta''io ba wamunu, ba sanaŵa nitaba bagira lö döladöla, ba tenaŵa![3]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 12, 'Ba na öŵa''ö ena''ö: "Lö nirongoma hadia ia", ba si ndruhu, aboto ba dödö zanulo tödö niha andrö, ba sangila zamaigi-maigi nosou, ba isulöni ba niha wolaunia.[4]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476168, 'OT', 'Amaedola Zelomo', 24, 13, 'A ŵe ŵani, ya''ugö onogu, me no si sökhi, ba sami ba gararou nösi gawa''awa.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 14, 'Amaedola da''ö be''e ba dödöu wa''atua-tua andrö: na no ösöndra ia, ba so na sa zi so fönau, ba tebai tobali faya wanötönamö.[5]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 15, 'Böi daro-darogö nahia zatulö tödö, ya''ugö sebua horö, ba böi dudugö waratenia.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 16, 'Mewitu sa alau zatulö tödö, ba mewitu ifuli maoso; ba sebua horö, ba tetaru mbagi, na göna famakao.[6]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 17, 'Na alau zi fatiu tödö khöu, ba böi omusoi''ö tödö; ba na tetaru mbaginia, ba böi owua-wua dödöu.[7]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 18, 'Fa böi i''ila Yehowa, ba abua khönia, ba lö''ö sa''ae mofönu ia ba da''ö no mege.', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 19, 'Böi maoso dödöu ba zamazökhi si lö sökhi, ba böi afökhö dödöu ba zebua horö.[8]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 20, 'Lö''ö sa si so föna zi lö sökhi; fandru zebua horö, ba mate.[9]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 21, 'Ata''ufi Yehowa, ya''ugö onogu, ba ata''ufi razo, böi ae awö zolaŵa.[10]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 22, 'Itörö dania ira famakiko, lö mudöna-döna; ha zangila ha wa''ara, ba faoma tekiko ira.[11]', '["Faigi 31:10–31","Faigi 20:18; 11:14","Yob 29:12; Sin 82:4","Faigi 16:2; SamI 16:7; Rom 2:6","Faigi 23:18","Yob 5:19; Sin 37:24","Yob 31:29","Faigi 3:31; Sin 37:1; 73:3","Faigi 13:9","FetI 2:17","Rom 13:2"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 23, 'Niŵa''ö zatua-tua göi da''e: Na ebua dödö zambuana ba wanguhuku, ba no si lö sökhi.[12]', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 24, 'Sanguma''ö ba zi so horö: "Lö horöu", ba ni''elifi niha sato, ni''elifi soi niha.', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 25, 'Ba sangatulö''ö fanguhuku, ba falukha wa''ohahau dödö, möi khöra howu-howu ba si sökhi.', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 26, 'Si fa''ago bawa khö nawönia zi göna fanema li.[13]', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 27, 'Asiwai halöŵöu baero, haogö wonowi, awena dania molau omo ndra''ugö khöu.', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 28, 'Böi ae sasi ba khö nawöu, lö börö; hadia, edöna''ö ölau waya beweu?[14]', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 29, 'Böi ömane: "Nilaunia khögu ulau khönia göi, usulöni ba zamösana wolaunia."[15]', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 30, 'No utörö hinölu nowi niha sareu, ba singa kabu nagu ba niha si lö tödö,', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 31, 'ba hiza, no tehawu o''o, no tobalu du''u mbolonia, ba ölinia, ba no aso''a.', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 32, 'Ba unehegö, utöngöni, ufaigi ba uhalö fanenaŵa khögu.', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 33, 'Femörö ma''ifu, fa''alau hörö ma''ifu, famatahö tanga ma''ifu, ba wolombase.[16]', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476168, 'OT', 'Amaedola Zelomo', 24, 34, 'Ba itörö''ö moroi sa fa''anumana, hulö niha sanörö tanö, awö wa''ambö, timba zi no mangaro.[17]', '["MozIII 19:15","Faigi 15:23","Faigi 19:5","Faigi 20:22","Faigi 6:9–11","Faigi 10:4"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 1, 'Niŵa''ö Zelomo göi da''e. Ni''ozaragö zi so khö Hisikia razo mado Yuda andrö.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 2, 'Ba Lowalangi, ba fangebua duriania, na ibini''ö hadia ia, ba ba razo niha, ba fangebua duria, na la''alui sibai, na so hadia ia.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 3, 'Si mane fa''alaŵa mbanua si yaŵa ba si mane fa''abakha danö si tou, si manö göi dödö razo, wa tebai tesöndra.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 4, 'Na laheta gakhozila ba wirö, ba mofozu gama-gama nifazökhi duka gana''a.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 5, 'Nifofanö ba ngai razo zolau si lö sökhi, ba möi fangaro dadaomania wa''atulö.[1]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 6, 'Böi mohokha ndra''ugö föna razo, ba böi bali''ö nahau naha zebua.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 7, 'Sökhi na lamane khöu: Fa''ese''ö miyaŵa; moroi na tanö tou labe''e ndra''ugö, ba zanehe zalaŵa, si no ö''ila mege.[2]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 8, 'Böi alio fasoso ndra''ugö; he öwisa sa dania, na no aila ndra''ugö ibe''e awöu?', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 9, 'Fatunö huhuou khö nawöu, ba böi bokai hadia zi tobini khö nawöu;[3]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 10, 'Fa böi i''ailasi ndra''ugö samondrongo, ba tebai sa''ae döhö duriamö si lö sökhi.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 11, 'Si mane bua gae balaki ba wiga firö, si manö daroma li ba ginötö.[4]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 12, 'Si mane walewale ana''a ba aya balaki, si manö zame''e lala ba dögi dalinga samondrongo.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 13, 'Si mane fa''okafukafu deu si baku, na baŵa wamasi, si manö zinenge si lö faya, ba zamatenge ya''ia; okafukafu dödö zokhö ya''ia ibe''e.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 14, 'Si mane lawuo, awö nangi si lö teu, si manö niha sanuno ya''ia ba mbuala, si lö ibe''e.[5]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 15, 'Fa''ebolo dödö wangai dödö zanguhuku, ba famatö döla lela si lö fönu.[6]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 16, 'Na ösöndra ŵe ŵani, ba a ndrohu-ndrohu, ena''ö böi töra fa''abuso, fa böi öfuli ö''uta''ö.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 17, 'Böi asese''ö we''amöi yomo ba nomo nawöu, fa böi aföli ia ndra''ugö ba fa böi fatuwu ndra''ugö khönia.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 18, 'Farökha ba gari ba ono wana satarö niha, si möi sasi sofaya ba khö nawönia.[7]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 19, 'Amaedola mboha si no obou hunö ba amaedola gahe si no fabesu wanötöna ba zi faröi na baŵa wamakao.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 20, 'Si mane sameta baru na baŵa wa''oafu ba si mane folau asio ba gigimö, si manö zanunö ba zabu tödö.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 21, 'Na olofo zi fatiu tödö khöu, ba be''e gönia, ba na owökhi dödönia, ba fabadugö khönia nidanö.[8]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 22, 'Na ömanö, ba ö''owuloi mbo galitö ba högönia, ba Yehowa zanulöni khöu.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 23, 'Angi moroi yöu, ba ifa''aso deu, ba falelalelasa nibini''ö, ba ifobörö wa''abao mbawa.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 24, 'Sökhi na ba mbumbu nomo yaŵa so ita, moroi na orudu yomo ita ba ndra alawe si fasoso-soso.[9]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 25, 'Si mane idanö kafu ba lela si no odufodufo, si manö duria si sökhi, moroi ba danö saröu.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 26, 'Si mane umbu si no olotu ba si mane ba''a nifakuyu, si manö zatulö sangiwa föna zebua horö.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 27, 'Na abölö oya ta''a ŵe ŵani, ba lö sökhi; ba na ta''alu-alui tödöda zafökhö fangalui, ba ebua döida.', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476169, 'OT', 'Amaedola Zelomo', 25, 28, 'Si tebai manaha tödönia, ba no hulö mbanua si no atu''a sanuwö, banua si lö öli.[10]', '["Faigi 16:12","Luk 4:7–11","Faigi 20:19","Faigi 15:23","FetII 2:17","Faigi 15:1","Faigi 19:5","Rom 12:20; Mat 5:44","Faigi 21:9,19","Faigi 29:11"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 1, 'Si mane teu si baku, na baŵa wa''aukhu zino ba si mane teu na baŵa wamasi, si manö wa lö faböbö zumange ba zi lö tödö.[1]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 2, 'Si mane siliŵi sanörö ba si mane katawaena si hombo, si manö wangelifi si lö börö, lö göna.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 3, 'Ba kudo, ba bözi-bözi, ba ba galide, ba fesu mbawa, — si manö wa''afaböbö nue ba hulu zi lö tödö.[2]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 4, 'Böi be''e dali walötödö khönia wanema li zi lö tödö, ba böi öfalaŵalaŵa ndra''ugö khönia.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 5, 'Be''e zui dali walötödö khönia wanema li zi lö tödö, fa böi ibali satua-tua ia.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 6, 'Sanaba ahenia ba sanölö famakao zangoroi''ö hadia ia khö zi lö tödö.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 7, 'Si mane ahe zombuyu-mbuyu, si no manaŵanaŵa, si manö gamaedola ba mbewe zi lö tödö.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 8, 'Hulö zamatöfa kara ba riboribo, si manö zamosumange si lö tödö.[3]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 9, 'Si mane lua-lua ndroi ba danga zi no mabu tua, si manö gamaedola ba mbewe zi lö tödö.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 10, 'Lua-lua zoya, ba fefu hadia ia, ba isaŵa zi lö boto böli gölö zi lö tödö, awö zangoni ya''ia.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 11, 'Hulö nasu samuli ya''ia ba gutania, si manö zi lö tödö samulimuli molau fa lö tödö andrö.[4]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 12, 'Na ö''ila niha sanguma''ö tödönia satua-tua ia — ba abe''e na dödö ba zowöhö mowa, moroi ba khönia andrö.[5]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 13, 'Imane sareu: "So zingo ba lala, singo ba dalu newali."[6]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 14, 'Si mane lagö mbawandruhö, si tefuyu-fuyu ba izinia andrö, si manö zareu ba dufonia.[7]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 15, 'Na no ifonumalö ba wiga dangania niha sareu, ba afökhö khönia wamuli ba mbawania.[8]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 16, 'Ba dödö zareu, ba atua-tua ia, moroi ba zi dafitu, si no atua-tua wanema li.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 17, 'Si maoso tödö ba wagua-guasa si tenga huhuonia, ba no amaedola zondra''e talinga nono nasu sanörö.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 18, 'Si mane sowöhö, samazaumba alitö ba solau ono wana famunu,', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 19, 'si manö niha, si no molimo awönia ba sanguma''ö dania: "Budegu manö."', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 20, 'Na lö eu sa ae, ba mate galitö, ba na lö samatou awönia, ba döhö wasosota.[9]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 21, 'Fonönö mbo, ba akho ba fonönö galitö, ba eu, ba si manö niha somasi fasosota, no fondrou''ö wagua-guasa.[10]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 22, 'Li zamatou awönia, ba no hulö gö sami; abakha si tou isaŵa.[11]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 23, 'Si mane sönö wirö nilau ba gero mbowoa tanö, si manö mbewe zabao, ba tödö si lö sökhi.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 24, 'Si fatiu tödö, ba ibini''ö dödönia bewenia, ba bakha barö dotonia, ba ifakhai waya.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 25, 'Na ihaogö linia, ba böi faduhu dödöu khönia; fitu ngawalö sa zogoro ita, si so ba dödönia.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 26, 'He miziŵa tobini watiusa andrö barö walimosa, ba teboka zui walösökhi zi manö, ba zi falukha banua.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 27, 'Sogaru lösu-lösu, ba alau bakha, ba samagaölö gowe, ba khönia tegaölö mangawuli.[12]', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476170, 'OT', 'Amaedola Zelomo', 26, 28, 'Lela sofaya, ba fatiu ba nifufunia; ba bewe nihaogö-haogö, ba ilaugö nawönia.', '["Ayati 8","Sin 32:9; Faigi 10:13","Ayati 1","FetII 2:22","Faigi 3:7","Faigi 22:13","Faigi 6:9–11","Faigi 19:24","Faigi 22:10","Faigi 15:18","Faigi 18:8","Sin 7:16; Sangomb 10:8"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 1, 'Böi suno ndra''ugö irege mahemolu, me lö ö''ila hadia zi tumbu ma''ökhö.[1]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 2, 'Yamusuno ndra''ugö niha bö''ö, ba böi bawau; niha baero, ba böi beweu.[2]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 3, 'Alakha abua gara ba alakha noro nene, ba no abua moroi ba zi dombua andrö wa''abao dödö zi lö tödö.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 4, 'Alakha mo''otu wa''abao dödö ba alakha falawu wönu — ba ha niha zanaha fa''olohu andrö?', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 5, 'Sökhi wanegu, si lö mubini''ö, moroi ba wa''omasi, si lö mu''oroma''ö.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 6, 'Moroi ba dödö si sökhi, ba ibago ita sangomasi''ö ya''ita, ba no si falawu, na fa''ago bawa khöda zi fatiu tödö khöda.[3]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 7, 'Si no abuso, ba ihundra-hundra nösi ŵani, ba ba zolofo, ba ami göi zafeto fefu.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 8, 'Hulö wofo soloi, sondröi azuninia, si manö niha sondröi omonia.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 9, 'Fangomuso dödö wanikha, awö nitutunu samohua; ba ami khöda zi fahuwu khöda, na ifobawa lala khöda, soroi ba dödö.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 10, 'Böi röi zi fahuwu khöu ba si fahuwu khö namau, ba böi ae ba nomo dalifusöu, na baŵa göna''ö safökhö khöu. Sökhi zi fahatö omo ba zahatö andrö, moroi ba dalifusö si no aröu.[4]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 11, 'Ya atua-tua ndra''ugö, ya''ugö onogu; omusoi''ö dödögu, ena''ö u''ila ubu''a, na so zanandraŵaisi ya''odo.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 12, 'Satua-tua, ba i''ila wamakao, ba ibini''ö ia: ba sambö tödö, ba latörö manö, ba te''ala.[5]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 13, 'Halö mbarunia, me no möi ia ba wali ba niha bö''ö, ba halö gade zi so khönia, börö huhuo mbö''ö.[6]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 14, 'Na so zangebua linia wangowai awönia, na mahemolu mbanua, ba labali fangelifi khönia.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 15, 'Ahe zagö na baŵa deu ba ira alawe somasi fasoso-soso, ba no fagölö-gölö.[7]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 16, 'Sanenaŵa ya''ia, ba no sanenaŵa angi, ba no sondra''u fanikha tangania kambölö.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 17, 'Si''öli, ba no angatarösi zi''öli, ba si manö wa i''atarösi dödö nawönia niha niha.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 18, 'Sangehao töla marafala, ba i''a mbuania; ba samaigi-maigi hadia zoguna khö zokhö ya''ia, ba nifosumange.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 19, 'Si mane ba nidanö, wa oroma khala-khala mbawada, si manö göi dödö niha khö nawönia niha.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 20, 'Banua tou ba awuwukha, ba tebai abuso, si manö göi wa tebai abuso hörö niha.[8]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 21, 'Tuga lawu ba wolaogö firö, ba alitö ba luha yaŵa ba wolaugö ana''a, ba ba niha, ba dali nisuno, bua-buania.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 22, 'He na ötutu ba lösu zi lö tödö halu, nifao ba wakhe, ba lö''ö zui döhö walötödö andrö khönia.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476171, 'OT', 'Amaedola Zelomo', 27, 23, 'Faigi sibai he wisa mbiri-biri khöu, hörö-hörögö rorogöföu.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 24, 'Tenga si lö mamalö-malö wa''aso, ba hadia, götö-götö wa''ara zaembu?[9]', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 25, 'Na no ahori ndru''u, ba na no ifuli molewiö, ba na no la''ohe baose ndru''u hili,', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 26, 'ba so khöu nono mbiri-biri ba wamonukha ya''ugö ba si matua mbiri-biri, böli mbenua.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476171, 'OT', 'Amaedola Zelomo', 27, 27, 'Ba irugi balazou ösi zusu nambi ba balazo zoroiyomou fefu ba lalazo zi manga gazi khöu ono alawe.', '["Yak 4:13,14","KorII 10:12","Sin 141:5","Faigi 14:20","Faigi 21:29; 22:3","Faigi 20:16","Faigi 19:13; 25:24","Faigi 30:15,16; Sangomb 1:8","TimI 6:7"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 1, 'Sebua horö, ba moloi, he ŵa''ae lö solohi, ba satulö, ba sabe''e tödö, si mane ono zingo.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 2, 'Ba wa lö atulö ba danö ato zalaŵa, ba na so niha si so fa''aboto ba dödö ba fangila watahögö, ba lö tebulö wa''atulö.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 3, 'Niha si no numana ba si no samakao si numana, ba no hulö deu si hanigö hadia ia ba si lö molohe balazo.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 4, 'Sangositengagö oroisa, ba lasuno zebua horö; ba solo''ö oroisa, ba mofönu khöra.[1]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 5, 'Niha si lö sökhi, ba lö la''ila hadia zatulö, ba ba zangalui Yehowa, ba ahori aboto ba dödö fefu hadia ia.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 6, 'Sökhi zi numana, sanörö lalania, lö sinegu, moroi ba zo''ana''a sanörö lala sabila.[2]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 7, 'Solo''ö oroisa, ba no ono satua-tua; ba si fao-fao ba zolu''a-lu''a, ba no fangaila namania.[3]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 8, 'Sangebua''ö ana''ania ba hare ba ba wabalisö, ba khö zi hakhösi tödö si numana dania ni''ozaragönia.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 9, 'Si lö mame''e börö dalingania ba wamondrondrongo oroisa, ba ni''ogorofi na''i wangandrönia.[4]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 10, 'Samaelungu sadölö tödö, solohe ba lala si lö sökhi, ba aekhu ba lösu-lösu andrö khönia, ba si lö horö, ba lasöndra zi sökhi.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 11, 'Ba dödö zo''ana''a, ba satua-tua ia, ba isöndra dödönia si numana, si so tödö.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 12, 'Na omuso dödö zatulö, ba ebua lakhömi; ba na möi yaŵa zebua horö, ba labini''ö ira niha [bö''ö].[5]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 13, 'Samini''ö horönia, ba si lö fozu; ba sangombakha horönia ba samöhöi, ba falukha wa''ahakhö dödö.[6]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 14, 'Ya ahowu zi lö mamalö-malö fa''ata''u; ba sangabe''e''ö tödönia, ba göna famakao.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 15, 'Amaedola zingo si ndröndröndröndrö ba amaedola mberua solu''a-lu''a zalaŵa sebua horö, ba niha si numana.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 16, 'Salaŵa si lö tödö, ba si no abölö famalangögö niha! Si ogorofi ana''a si lö atulö, ba anau gölö.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 17, 'Niha si so ba hulu do nibunu, ba no si lö ahono-hono irege mbewe gohokoho; böi tatabigö ia![7]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 18, 'Sanörö lalania lö sinegu, ba no si falukha fangorifi; ba sanörö lala sabila, ba alau lö mudöna-döna.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 19, 'Sangahalö, ba fahöna mbalazo isöndra; ba solohi si lö boto, ba no si fahöna fa''anumana dania.[8]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 20, 'Niha solösu lö falimosa, ba no sebua howu-howu; ba khö zaösö ba wangebua ana''a, ba lö zi lö sala.[9]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 21, 'Na ebua dödö zambuana, ba si lö sökhi; ba so, ba ha sambawa gö mbörö, wa ifazökhi horö niha.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 22, 'Niha safökhö tödö, ba ida''i-da''i wangebua ana''ania, ba lö aboto ba dödönia wa göna ia fa''ambö dania.[10]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 23, 'Sanegu niha sangawuli furi, ba falukha wangandrö saoha gölö, moroi ba zanuno.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 24, 'Si anagöi ira amania inania, wanguma''ö: "Tenga horö", ba no awö zamakiko.[11]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 25, 'Sangisö ana''a, ba ifobörö wasosota; ba khö zanötöna khö Yehowa, ba fahöna dania wangokafu dödö.', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 26, 'Sanötöna ba dödönia, ba no si lö tödö; ba si no atua-tua wanörö lalania, ba saefa dania.[12]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 27, 'Sanolo si numana, ba lö falukha wa''ambö; ba samalugö hörönia, ba asese te''elifi.[13]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476172, 'OT', 'Amaedola Zelomo', 28, 28, 'Na möi yaŵa zebua horö, ba labini''ö ira niha [bö''ö], ba na tekiko ira, ba tedou wa''ato zatulö.[14]', '["Sin 49:14","Faigi 19:1","Faigi 13:22","Faigi 21:27","Faigi 11:10,11","Sin 32:3–5; YohI. 1:8,9","MozI 4:14","Faigi 6:6–11; 10:4; 12:11","Ayati 22; Faigi 22:21","Ayati 20; Faigi 23:4; TimI 6:9","Mat 15:5","Faigi 3:5","KorII 9:6,9","Faigi 29:2"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 1, 'Niha si no asese mutegu ba sabe''e börö du''i, ba i''ozumagö adudu, si lö fangorifi.[1]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 2, 'Na tedou wa''ato zatulö, ba omuso dödö niha sato; ba na salaŵa zebua horö, ba mangarö-ngarö zato.[2]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 3, 'Somasi fa''atua-tua, ba omuso dödö namania ibe''e; ba sorudu ba zomasi fohorö, ba no sangohori ana''a.[3]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 4, 'Razo solau satulö, ba i''a''azökhi mbanua; ba sangöhöna beo, ba no samufu.[4]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 5, 'Sangehangehao linia khö nawönia, wamini tödö, ba no samadölö u''ö föna gahenia.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 6, 'Ba horö niha si lö sökhi, ba no tobini dandraŵa; ba satulö, ba ma''iki ba amuso dödö.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 7, 'Satulö tödö, ba isöndra, na lö horö zide-ide; ba ba zebua horö, ba lö falukha wa''aboto ba dödö.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 8, 'Sango''aya, ba humola mbanua labe''e; ba satua-tua, ba la''alösi wönu.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 9, 'Na so huhuo zatua-tua khö zi lö tödö, ba mofönu da''ö ba ma''iki ba lö falukha wa''ahono.[5]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 10, 'Niha sange''enge''e, ba fa''udu ba zi lö horö; ba na so zadölö tödö, ba la''alui wamunu da''ö.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 11, 'Fefu wa''abao dödönia, ba ifalua baero si lö tödö; ba satua-tua, ba i''alösi ba dödö.[6]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 12, 'Ba zalaŵa samondrongo faya, ba oi dozi sebua horö ngoni-ngoni.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 13, 'Si numana ba sangebua hare, ba falukha; ba samehaga höröra, darua ira, ba ya''ia Yehowa.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 14, 'Ba zalaŵa, sangatulö''ö fanguhuku si numana, ba lö mangiwa dadaoma, irugi zi lö aetu.[7]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 15, 'Bözi-bözi ba fanegu, ba ifa''ema wa''atua-tua; ba ono matua, si lö mu''otu''ö, ba möi fangaila ninania.[8]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 16, 'Na tedou wa''ato zebua horö, ba tedou wa''oya golalöŵa, ba anehe dania zatulö, na te''ala ira.[9]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 17, 'Otu''ö nonou, ba omuso dödöu khönia; owua-wua bakha dödöu ibe''e.[10]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 18, 'Na lö fama''ele''ö, ba lö sökhi mbua-bua zato; ba ya ahowu zolo''ö oroisa.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 19, 'Taroma li, ba lö möi fangazökhi zawuyu; he meziŵa aboto ba dödönia sa''ae, ba lö i''o''ö.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 20, 'Na ö''ila zalio bewe, — ba abölö na''i tadöna-döna ba zi lö tödö, moroi ba zi manö.[11]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 21, 'Na so zi haogö-haogö manö khö zawuyunia, i''otarai iraono ia, ba tobali famalua zi lö sökhi, ba gafuriata.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 22, 'Si ono wönutö, ba ifobörö wasosota; ba ba zalio abao tödö, ba fahöna horö.[12]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 23, 'Fayaŵasa andrö, ba ihöndrögö tou niha; ba si lö fayaŵasa, ba isöndra zumange.[13]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 24, 'Si manga urakhania sinagö, ba no si lö omasi nosonia; irongo wangelifi, ba lö i''ombakha''ö.[14]', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 25, 'Fangata''ufi niha, ba tobali tandraŵa; ba sanötöna khö Yehowa, ba ni''orifi.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 26, 'Ato zangalui bawa zalaŵa, ba moroi khö Yehowa wangetu''ö huku niha.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476173, 'OT', 'Amaedola Zelomo', 29, 27, 'Solau si lö atulö, ba no ni''ogorofi zatulö tödö; ba sogoro zebua horö zanörö lala sadölö.', '["Faigi 15:10","Faigi 11:10","Luk 15:13","Yes 32:7","Mat 11:17","Faigi 25:28; 12:23","Faigi 16:12","Ayati 17; Faigi 22:15","Sin 37:36","Faigi 23:13","Sangomb 5:1,2; Yak 1,19","Faigi 15:18; 26:21","Mat 23:12; FetI 5:5","MozIII 5:1"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 1, '"No erege dödögu, Lowalangi; no erege dödögu, ya''ugö Lowalangi, ariri ndra''o.', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 2, 'Noa sa abölö owöhö-wöhö ndra''odo, fa laŵa''ö, niha ndra''odo, ba tödö niha, ba lö khögu.', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 3, 'Ba lö nitöngönigu fa''atua-tua, fa aboto ba dödögu ena''ö Ni''amoni''ö andrö.', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 4, 'Ha niha zi no möi miyaŵa ba zorugo ba sangawuli mitou? Ha niha zi gokhöi angi? Ha niha zi olöwösi idanö andrö ba lembe? Ha niha zolata balö danö fefu? Ha niha döinia, ba ha niha döi nononia? — na no örongo.[1]', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 5, 'Fefu huhuo Lowalangi, ba no nihaogö; baluse ia ba zangalui saŵatö khönia.[2]', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 6, 'Böi nönö daroma linia, fa böi i''otu''ö ndra''ugö ba fa böi tobali solau faya ndra''ugö.[3]', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 7, 'Dua balö ni''andrögu khöu, böi zi lö ö''o''ö khögu ba da''ö, gasa-gasa wa''amategu:', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 8, 'Faya-faya ba falimosa, ba aröu''ö khögu. Fa''anumana ba fo''ana''a, ba böi fatörö khögu, ba tolodo, ena''ö usöndra ndruhundrohu mbalazogu.[4]', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 9, 'Ma dania u''osilö''ögö ndra''ugö, na no abölö abuso ndra''odo, ma umane: Ha niha Yehowa? ba fa böi managö ndra''o, ba wa''anumana, wango''aya töi Lowalangigu.', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 10, 'Böi fatou zawuyu khö zokhö ya''ia, ba böi i''elifi ndra''ugö, ba ya''ugö zolu''i.', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 11, 'Ono niha sangelifi amara ba si lö mamahowu''ö inara;', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 12, 'ono niha sanguma''ö sohau-hau ira, ba lö''ö sa sumasai zi ta''unö;[5]', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 13, 'ono niha — ha lö abölö wayaŵasa höröra, ha lö abölö lafayaŵa guli hörö![6]', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 14, 'Ono niha so''ifö föda, ba soboha si''öli, ba wemanga sebua famakao, ba wangohori ba guli danö, fabaya si numana ba niha!', '["Yob 38","Sin 12:7; 18:31","MozV 4:2","TimI 6:6–8; Mat 6:11","Faigi 20:9","Faigi 21:4"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 15, 'Dombua nono lita, ono alawe: Da! Da! Tölu zi tebai abuso; öfa zi lö manguma''ö: Noa!', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 16, 'Banua tou ba naha nono ba dalu, si no teduhö (si lö ono) ba tanö tou, si tebai abuso idanö, ba alitö, si lö manguma''ö: Noa!', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 17, 'Hörö zango''aya amania ba si lö ba dödö wolo''ö li ninania, ba gaga ba ndraso zondrou dania ba ono moyo zi manga.[7]', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 18, 'Tölu ngawalö zi tebai ukhamö, ba öfa zi lö aboto ba dödögu:', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 19, 'Lala moyo ba dalu mbanua ba lala gulö ba dete gara misa ba lala nowo ba dalu nasi ba lala ndra matua ba nono alawe.[8]', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 20, 'Si manö lala ndra alawe sabao: itema, ba i''osi mbawania ba imane: Lö nifazökhigu horö.', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 21, 'Tölu balö zi duru danö, ba öfa zi tebai itaha:', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 22, 'Sawuyu, na tobali salaŵa, ba niha si lö sökhi, na no fahöna mbalazo.[9]', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 23, 'Ba si lö mu''omasi''ö, na te''owalu, ba sawuyu ono alawe, na itimba zokhö ya''ia ira alawe.', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 24, 'Öfa zide-ide ba guli danö, ba noa zui atua-tua sibai:', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 25, 'Sikhö andrö, ba tenga banua sabölö, ba lahöna zui mbalazo fatua bawa lökhö.[10]', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 26, 'Sigölu, tenga göi banua sabölö, ba ba dögi gara labe''e nahara.', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 27, 'Lareŵe andrö, ba lö salaŵa, ba mongawawa zui wofanö, lö fakuyu.', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 28, 'Kiliŵi, ba ö''ila öra''u tangau, ba noa zui ba nomo razo so ia.', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 29, 'Tölu zabe''e fofanö ba öfa zabölö fanörö:', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 30, 'Singo andrö, fondrege zabölö ba zaliŵa-liŵa ba danö, si lö ata''u hadia ia;', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 31, 'ba si so böbö talu andrö (kudo?), ba nambi si matua, ba salaŵa ba hunö mbanuania.', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 32, 'He no owöhö''ö, na si fayaŵa ndra''ugö, ba he si so era-era — ba balugö mbawau!', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476174, 'OT', 'Amaedola Zelomo', 30, 33, 'Na lafera zusu zaŵi, ba tobali matega, ba na tefera''ö nikhu ba mendro, ba na tefera''ö (na tesuko) wönu, ba alua wasosota.', '["Faigi 22:20","Faigi 6:16","Sangomb 10:6","Faigi 6:6–8; 10:5"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 1, 'Taroma li Lemueli, razo Masa, famaha''ö ninania ya''ia.', '[]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 2, 'Hadia [niŵa''ögu khöu], ya''ugö onogu? Hadia, ya''ugö ono moroi ba dalugu? Hadia, ya''ugö ono nifabu''ugu?', '["MozV 17:17; RazI 11:1","Faigi 20:1","Yob 29:12,15"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 3, 'Böi lulu ba ndra alawe wa''abölöu, ba böi lulu ba zamakiko razo döröŵamö.[1]', '["MozV 17:17; RazI 11:1","Faigi 20:1","Yob 29:12,15"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 4, 'Tenga amuata razo, ya''ugö Lemueli, tenga amuata razo wamadu tuo; tenga ö razo zi mabu ita.[2]', '["MozV 17:17; RazI 11:1","Faigi 20:1","Yob 29:12,15"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 5, 'Fa böi mabu ia ba fa böi olifu ia gamakhoita, wamuyu''ö huhuo zi numana fefu.', '["MozV 17:17; RazI 11:1","Faigi 20:1","Yob 29:12,15"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 6, 'Ba zi tekiko mibe''e zi mabu niha, ba ba zabu tödö mibe''e nagu.', '["MozV 17:17; RazI 11:1","Faigi 20:1","Yob 29:12,15"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 7, 'Ena''ö ibadu ba ena''ö olifu ia wa''anumanania, ena''ö lö''ö sa''ae itörö tödönia wamakaonia.', '["MozV 17:17; RazI 11:1","Faigi 20:1","Yob 29:12,15"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476175, 'OT', 'Amaedola Zelomo', 31, 8, 'Bokai mbawau, ba wanolo si lö hede ba ba wamatunö huhuo niha sariri.[3]', '["MozV 17:17; RazI 11:1","Faigi 20:1","Yob 29:12,15"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 9, 'Bokai mbawau, atulö''ö wanguhuku, ba ohe ba lala huhuo zi no göna famakao ba huhuo zi numana.', '["MozV 17:17; RazI 11:1","Faigi 20:1","Yob 29:12,15"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 10, 'Ira alawe si sökhi bua-bua — ha niha zanöndra? — ba aröu ebua mböli, moroi ba mani-mani.[4]', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 11, 'Khönia manötöna dödö ngambatönia, ba lö ambö harenia.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 12, 'Ilau khönia zomasi ia, ba sagötö ya''ia, ba lö ibusi dödönia.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 13, 'I''alui gafasi ba sinasa, ba owölö-ölö dangania, wohalöŵö.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 14, 'Amaedola nowo zaniaga ia: ba zaröu ihalö mbalazo.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 15, 'Na ogömi-gömi na maoso ia, ba ibe''e gö zi so yomo khöra, ifasasi ndrohu-ndrohu ba zawuyu ono alawe.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 16, 'I''alui mbenua ba isöndra; ölö dangania wolau kabu nagu.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 17, 'I''amöbö talu wa''abölö ba wohalöŵö, ba i''abe''e''ö mbulökhania.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 18, 'I''ila wa soguna gölönia; sara wongi lö mate wandrunia.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 19, 'Ituyu tangania gafasi nigadi, ba mogadi duturunia.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 20, 'Ira''u danga zi no göna famakao, ba i''oro''ö dangania ba zi numana.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 21, 'Lö ata''u ia baomonia deu si baku andrö, noa sa''ae baru luo nukha zoroiyomonia fefu.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 22, 'Ambala ifazökhi khönia; muko ba orona si sökhi nukhania.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 23, 'Fo''omonia, ba no moturia ba mbawa göli, na falukha ira zalaŵa ba danö.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 24, 'Itagu kameza si sökhi, ba i''amawa; böbö dalu i''amawa ba zaniaga.[5]', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 25, 'Fa''abölö ba fa''asalaŵa mbarunia, ba lö abu dödönia he wisa mahemolu.[6]', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 26, 'Fa''atua-tua lua-lua mbewenia, ba famahaö omasiö ilau lelania.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 27, 'Ifaigi-faigi he wisa gamuata baomo khönia, ba tenga ba wa''areu i''a gönia.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 28, 'Ba maoso nononia matua ba lafahowu-howu''ö ia, ba isuno ia fo''omonia:', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 29, '"Ato nono alawe si sökhi amuata, ba ya''ugö, ba no ahori ötalu''i ira."', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 30, 'Si lö boto wa''asökhi nga''eu ba faya wa''asökhi mbawa; ba ira alawe sangata''ufi Yehowa, ba nisuno.[7]', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476175, 'OT', 'Amaedola Zelomo', 31, 31, 'Mibe''e khönia gölö dangania, ba ndramusuno ba mbawa göli nilaunia.', '["Faigi 12:4; 18:22","HalZin 9:39","Yob 5:22; Mat 6:34","Faigi 11:22"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 1, 'Taroma li zangombakha andrö, ono Dawido, razo ba Yeruzalema.[1]', '["Sin 62:10","Faigi 2:22"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 2, 'Faya-faya si tumbu ba zi lö boto! iŵa''ö sangombakha andre; faya-faya si tumbu ba zi lö boto! Oi faya-faya manö!', '["Sin 62:10","Faigi 2:22"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 3, 'Hadia hare niha ba wa''erege dödönia andrö fefu, ba ni''eregesinia tödönia ba guli danö?[2]', '["Sin 62:10","Faigi 2:22"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 4, 'Mulalö zi sagötö niha, ba so zi sagötö, ba tanö andre, ba si lö tebulö, irugi zi lö aetu.[3]', '["Sin 104:5","Amaed 27:20","Faigi 3:15"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 5, 'Ba tumbu luo ba aekhu, si fulöi ia, isaŵa zi tumbu ia dania.', '["Sin 104:5","Amaed 27:20","Faigi 3:15"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 6, 'Tefuyu nangi miraya, ba irugi yöu; tefuyu-fuyu manö ia, ba ifulifuli ia ba nifasuinia mege.', '["Sin 104:5","Amaed 27:20","Faigi 3:15"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 7, 'Ba nasi numalö nidanö fefu, ba lö''ö sa falawu nasi: ba zi numalö idanö andrö, ba da''ö manö zui lua-lua dania.', '["Sin 104:5","Amaed 27:20","Faigi 3:15"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 8, 'Fefu hadia ia, ba serege tödö; tebai ahori idunö-dunö niha; lö abuso hörö wamaigi, ba lö afönu dögi dalinga ba wamondrongo.[4]', '["Sin 104:5","Amaed 27:20","Faigi 3:15"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 9, 'Hadia zi no aefa, da''ö zui zi so dania, ba si no numalö, ba ifuli itörö dania, ba lö hadia ia zi bohou so ba guli danö.[5]', '["Sin 104:5","Amaed 27:20","Faigi 3:15"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 10, 'Hadia, so hadia ia niŵa''öda: Hiza, sawena so da''ö? No föna sa''ae so, ba götö fönada.', '["Sin 104:5","Amaed 27:20","Faigi 3:15"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 11, 'Lö''ö sa''ae itörö tödö zi so mege, fönada, ba he si so dania, furida, ba lö dania itörö tödö zi so furira zui dania.', '["Sin 104:5","Amaed 27:20","Faigi 3:15"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 12, 'Ya''odo, sangombakha andre, ba no razo Ndraono Gizeraeli ndra''o, ba Yeruzalema.', '["RazI 4:29 b.t.","RazI 3:12; Faigi 2:9","Faigi 2:12; 7:26"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 13, 'Ba no ube''e dödögu ba wangalungalui ba ba wamaigi-maigi fefu hadia ia ba guli danö, ba wa''atua-tuagu: famakao, nibe''e Lowalangi ba nono niha, wangeregesi tödö ba da''ö![6]', '["RazI 4:29 b.t.","RazI 3:12; Faigi 2:9","Faigi 2:12; 7:26"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 14, 'No ahori u''ila nilau-lau ba guli danö, ba si ndruhu: oi si lö boto ba folohi angi.', '["RazI 4:29 b.t.","RazI 3:12; Faigi 2:9","Faigi 2:12; 7:26"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 15, 'Sabila, ba tebai adölö, ba sambö-ambö, ba tebai ni''erai.', '["RazI 4:29 b.t.","RazI 3:12; Faigi 2:9","Faigi 2:12; 7:26"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 16, 'Ba umane dödögu: Si ndruhu, no usöndra wa''atua-tua, ba itugu tedou-dou, italui fefu zalaŵa ba Yeruzalema, fönagu, no fahöna wa''atua-tua ba fa''aboto ba dödö ni''ila dödögu.[7]', '["RazI 4:29 b.t.","RazI 3:12; Faigi 2:9","Faigi 2:12; 7:26"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 17, 'Ba me u''alu-alui, ena''ö aboto ba dödögu wa''atua-tua ba he fa''owöhö mowa ba fa''ambö tödö, ba usöndra, wa folohi angi da''ö göi.[8]', '["RazI 4:29 b.t.","RazI 3:12; Faigi 2:9","Faigi 2:12; 7:26"]', NULL),
  (3476236, 'OT', 'Sangombakha', 1, 18, 'Na no fahöna wa''atua-tua, ba fahöna göi wa''abu dödö, ba na so zangöhöna fa''aboto ba dödö, ba no sangöhöna fa''afökhö göi.', '["RazI 4:29 b.t.","RazI 3:12; Faigi 2:9","Faigi 2:12; 7:26"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 1, 'No umane dödögu: Ba da''utandraigö wa''omuso dödö andrö, u''owua-wua''ö dödögu si sökhi! Ba hiza, no si lö boto da''ö göi.', '[]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 2, 'No umane ba wa''iki andrö: Owöhö''ö! ba ba wa''omuso dödö: Hadia nilau da''ö?', '[]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 3, 'U''alu-alui tödögu wondrorogö botogu wamadu agu, fatua ifa''ua wa''atua-tua tödögu, ba wangolembai fa''owöhö-wöhö, irege u''ila hadia zoguna lalau niha, ba götöra ba guli danö.', '[]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 4, 'Sebua ulau: ulau khögu nomo, ba ufazökhi khögu kabu nagu;', '["RazI 11:3"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 5, 'utanö zinanö ba ngai nomo ba ufazökhi kabu nihaogö, ba utanö geu sowua ba da''ö, hadia ia ngawalö;', '["RazI 11:3"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 6, 'ufazökhi mbaŵa nidanö, ba wamo''idanö börö geu ba gatua, sanöi-nöi;', '["RazI 11:3"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 7, 'ba uhöli zawuyu, ira matua ba ira alawe, ba so göi khögu zi no tumbu yomo khögu. Ba so göi khögu ngawawa zaŵi ba biri-biri, oya moroi ba gokhöta zi so ba Yeruzalema fönagu.', '["RazI 11:3"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 8, 'No uhöna göi khögu wirö ba ana''a, nihalö ba zalaŵa ba niha ba danö; ba u''asogö khögu zanunö, ira matua ba ira alawe, awö wa''omuso dödö niha ba guli danö; uhöna ndra alawe.[1]', '["RazI 11:3"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 9, 'Ba tobali sebua ndra''o, sebua moroi ba danö bö''ö fefu, fönagu ba Yeruzalema; ba he göi fa''atua-tuagu, ba lö tebulö khögu.', '["RazI 11:3"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 10, 'Ba fefu hadia ia gomasiö hörögu, ba utehe khönia, ba hadia ia zomasi dödögu, ba u''o''ö khönia, omuso sa dödögu wa''akaogu andrö fefu, da''ö haregu ba wa''erege dödögu andrö fefu.', '["RazI 11:3"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 11, 'Ba me ufaigi halöŵögu andrö fefu nilau dangagu, ba fa''arege dödögu; ölögu andrö, ba wolau ya''ia, ba u''ila: oi si lö boto ba folohi angi, ba lö hare ba guli danö.', '["RazI 11:3"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 12, 'Ba u''otahögö wa''atua-tua ba fa''owöhö mowa ba fa lö tödö, ba wamaigi da''ö; he iwisa sa niha andrö, si so dania, na lö''ö sa''ae razo andre? Si no mulau föna sa''ae ilau!', '["Sin 49:11","Ayati 21:26; Sin 39:7"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 13, 'Ba u''ila, wa no tohude wa''atua-tua, moroi ba wa lö tödö, timba haga, si tohude moroi ba wa''ogömi-gömi.', '["Sin 49:11","Ayati 21:26; Sin 39:7"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 14, 'Ba zatua-tua, ba so hörö ba mbawania, ba sambö tödö, ba ba zogömi-gömi lalania. Ba u''ila göi, wa no si fagölö-gölö manö zi göna ira.', '["Sin 49:11","Ayati 21:26; Sin 39:7"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 15, 'Ba umane dödögu: Göna göi ndra''o si göna zambö tödö, ba hadia guna wa no satua-tua sibai ndra''odo? Ba uŵa''ö tödögu, faya-faya göi da''ö.', '["Sin 49:11","Ayati 21:26; Sin 39:7"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 16, 'Faoma sa lö ara itörö tödö niha dania, he satua-tua, ba he sambö tödö; ba götö dania, ba olifu manö niha ira fefu, ba mate manö zatua-tua, awö zambö tödö.[2]', '["Sin 49:11","Ayati 21:26; Sin 39:7"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 17, 'Ba anuzu dödögu wa''auri, lö''ö sa omasido nilau-lau ba guli danö; oi sa si lö boto manö ba folohi angi!', '["Sin 49:11","Ayati 21:26; Sin 39:7"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 18, 'Ba anuzu dödögu wa''erege dödögu andrö fefu, fa''akaogu andrö ba guli danö, me ba zi so furigu uröi furi dania.[3]', '["Sin 49:11","Ayati 21:26; Sin 39:7"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 19, 'Ba ha niha zangila, na satua-tua da''ö, ba na sambö tödö? Ba ya''ia dania zamatörö si no erege dödögu, si no ufakao ndra''o, ba zi no atua-tua ndra''o ba guli danö — ba da''ö göi, ba no si lö boto!', '["Sin 49:11","Ayati 21:26; Sin 39:7"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 20, 'Ba u''erogö, ena''ö aragu-ragu manö dödögu, ba wa''erege dödö andrö fefu, nifakaogu ya''o, ba guli danö.', '["Faigi 1:3","Yob 14:1","Faigi 3:12,22; 5:17; 9:7","Yob 27:16 b.t.; Amaed 28:8; 13:22"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 21, 'Na so zi so fa''atua-tua ba fa''aboto ba dödö, ba si faduhu dödöda ba wangainia halöŵönia, ba iröi furi dania okhöta niha si lö erege tödö khönia: si lö boto göi da''ö ba famakao sebua.', '["Faigi 1:3","Yob 14:1","Faigi 3:12,22; 5:17; 9:7","Yob 27:16 b.t.; Amaed 28:8; 13:22"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 22, 'Hadia atö nisöndra niha, ba wa''erege dödönia andrö fefu ba ba wangalungalui dödönia, nifakaonia ya''ia ba guli danö?[4]', '["Faigi 1:3","Yob 14:1","Faigi 3:12,22; 5:17; 9:7","Yob 27:16 b.t.; Amaed 28:8; 13:22"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 23, 'Ero ma''ökhö sa so wa''afökhö khönia, ba fa''abu dödö halö-halöŵönia; ba he ba zi bongi, ba lö falukha wolombase dödönia. Si lö boto göi da''ö![5]', '["Faigi 1:3","Yob 14:1","Faigi 3:12,22; 5:17; 9:7","Yob 27:16 b.t.; Amaed 28:8; 13:22"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 24, 'Awai zi sökhi ba niha: femanga-manga ba famadu-madu hadia ia ba na i''omusoi''ö dödönia ba wamakaonia andrö: ba he da''ö göi, ba ba danga Lowalangi moroi — no u''ila.[6]', '["Faigi 1:3","Yob 14:1","Faigi 3:12,22; 5:17; 9:7","Yob 27:16 b.t.; Amaed 28:8; 13:22"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 25, 'Ha niha sa zi manga ba ha niha zabuso, na lö ya''ia?', '["Faigi 1:3","Yob 14:1","Faigi 3:12,22; 5:17; 9:7","Yob 27:16 b.t.; Amaed 28:8; 13:22"]', NULL),
  (3476237, 'OT', 'Sangombakha', 2, 26, 'Ba zomasi ia sa, ba ibe''e wa''atua-tua ba fa''aboto ba dödö ba fa''omuso dödö; ba ba zi so horö, ba da''ö ibe''e halöŵönia: fangozaragö ba fangöhöna, ba wame''e ya''ia ba zomasi Lowalangi. Ba si lö boto da''ö göi ba folohi angi.[7]', '["Faigi 1:3","Yob 14:1","Faigi 3:12,22; 5:17; 9:7","Yob 27:16 b.t.; Amaed 28:8; 13:22"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 1, 'Fefu hadia ia, ba so ginötö, ba hadia ia fefu nilau ba guli danö, ba oi ba ginötönia.[1]', '["Faigi 8:6"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 2, 'So mbaŵa wa''atumbu ba so mbaŵa wa''amate. Fananö ba fondröni nitanö andrö.', '["Faigi 8:6"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 3, 'Famunu niha ba fangorifi. Fanudugö ba fangotomosi.', '["Faigi 8:6"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 4, 'Fege-ege ba fa''iki. Fa''abu dödö ba folaya.', '["Faigi 8:6"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 5, 'Fanibo kara ba fangozaragö kara. Fa''omasi ba fa lö fa''omasi.', '["Faigi 8:6"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 6, 'Fangalui ba fa''aekhu. Fangirö ba fanibo.', '["Faigi 8:6"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 7, 'Fanika ba fanagu. Fa lö hede-hede ba fehede.', '["Faigi 8:6"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 8, 'Fangomasi''ö ba fatiusa. Fasuwöta ba fa''atulö.', '["Faigi 8:6"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 9, 'Hadia hare zolau hadia ia ba ni''eregesinia tödönia?', '["Faigi 1:3","Faigi 8:17","Faigi 2:24"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 10, 'No u''ila halöŵö andrö, nibe''e Lowalangi ba nono niha, ba wangeregesi tödöra.[2]', '["Faigi 1:3","Faigi 8:17","Faigi 2:24"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 11, 'Fefu hadia ia, ba no ihaogö wolau, oi ba ginötönia, ba he si lö aetu andrö, ba noa göi ibe''e ba dödöra; ba fa tebai aboto ba dödö niha — i''otarai wamobörö, irugi ba gamozua — nilau Lowalangi andrö.[3]', '["Faigi 1:3","Faigi 8:17","Faigi 2:24"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 12, 'Ba no aboto ba dödögu, wa lö hadia ia zi sökhi ba khöra, moroi na la''omusoi''ö dödöra ba na lahaogö-haogö göra, ba götöra ba guli danö.[4]', '["Faigi 1:3","Faigi 8:17","Faigi 2:24"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 13, 'Ba he na manga-manga niha ba na ibadu-badu hadia ia, na i''abusoi''ö ia si sökhi ba wa''erege dödönia andrö fefu, ba no buala Lowalangi khönia.', '["Faigi 1:3","Faigi 8:17","Faigi 2:24"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 14, 'No aboto ba dödögu, wa si lö tebulö, irugi zi lö aetu, fefu hadia ia nilau Lowalangi; tebai tanönö ba tebai tawuwu: No imanö wolau Lowalangi, ena''ö la''ata''ufi ia niha.', '["Faigi 1:3","Faigi 8:17","Faigi 2:24"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 15, 'Hadia zi so, ba no ara, ba si so dania, ba no föna sa''ae so; ifuli sa i''alui Lowalangi zi no numalö.', '["Faigi 1:3","Faigi 8:17","Faigi 2:24"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 16, 'Ba so na ni''ilagu, ba guli danö: famuyu''ö huku ba naha wanguhuku ba famalangögö niha ba naha wangatulö.', '["Faigi 12:14","Sin 49:13,21","MozI 3:19; Sin 146:4","Faigi 12:7"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 17, 'Ba umane dödögu: he satulö tödö ba he sebua horö, ba faoma ihuku Lowalangi; fefu hadia ia nitörö ba hadia ia nilau, ba noa sa ifakhoi ginötö.[5]', '["Faigi 12:14","Sin 49:13,21","MozI 3:19; Sin 146:4","Faigi 12:7"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 18, 'Ba umane na dödögu: Börö nono niha, ena''ö itandraigö ira Lowalangi, ba ena''ö aboto ba dödöra, wa no timba zaliŵa-liŵa ba danö ira.', '["Faigi 12:14","Sin 49:13,21","MozI 3:19; Sin 146:4","Faigi 12:7"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 19, 'Me no faoma zi göna ira niha zaliŵa-liŵa ba danö — ha sara lalara: no faoma wa''amatera, ha sambua nosora; lö si tohude niha moroi ba zaliŵa-liŵa ba danö, oi sa si lö boto.[6]', '["Faigi 12:14","Sin 49:13,21","MozI 3:19; Sin 146:4","Faigi 12:7"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 20, 'Ha sara lua-lua lalara, gawu-gawu mböröta hadia ia fefu, ba si tobali gawu-gawu zui dania.[7]', '["Faigi 12:14","Sin 49:13,21","MozI 3:19; Sin 146:4","Faigi 12:7"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 21, 'Ha zangila, na miyawa isaŵa bekhu niha, ba na barö danö tou isaŵa bekhu zaliŵa-liŵa ba danö?[8]', '["Faigi 12:14","Sin 49:13,21","MozI 3:19; Sin 146:4","Faigi 12:7"]', NULL),
  (3476238, 'OT', 'Sangombakha', 3, 22, 'Ba aboto sa''ae ba dödögu, wa lö si sökhi, moroi na i''omusoi''ö dödönia niha ba nilau-launia andrö, me no da''ö dana khönia; ha niha sa zangila mama''ele''ö khönia, he wisa dania, na lö ya''ia sa''ae?', '["Faigi 12:14","Sin 49:13,21","MozI 3:19; Sin 146:4","Faigi 12:7"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 1, 'Ba u''ila göi wamalangögö andrö fefu, ba guli danö: mowöi daŵa hörö nifakao andrö, ba lö sondrara tödöra, lafakao ira samalangögö ya''ira, ba lö sondrara tödöra.', '["Amaed 6:10; 24:33"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 2, 'Ba ufahowu''ö zi no mate, si no mate föna sa''ae, moroi ba zauri, si no na ma''ökhö,', '["Amaed 6:10; 24:33"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 3, 'ba ya ahowu na moroi andrö zi lö si tumbu na, si lö mangila folau si lö sökhi andrö, ba guli danö.', '["Amaed 6:10; 24:33"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 4, 'Ba u''ila wa''erege dödö andrö fefu, awö wa''onekhe ba wolau hadia ia, fefu, wa no fa''afökhö dödöra khö nawöra. Si lö boto göi da''ö ba folohi angi.', '["Amaed 6:10; 24:33"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 5, 'Sambö tödö, ba ifatahö dangania, ba i''aga''aga nösinia.[1]', '["Amaed 6:10; 24:33"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 6, 'Sökhi zi sagokhö fa''ahono dödö, moroi ba zi sandremo fa''erege dödö ba folohi angi.', '["Amaed 6:10; 24:33"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 7, 'Ba so na ni''ilagu si lö boto, ba guli danö:', '["Sin 39:7"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 8, 'so zi ha samö-samösa, si lö awö, lö''ö göi ononia ba lö talifusö, ba ifakao zui ia, si lö aetu, ba lö abuso hörönia ana''a. Ba ha khö atö moguna, na ufakao ndra''o, ba na alimagö khögu uhaogö gögu? Si lö boto göi da''ö ba zaya-zaya gölö![2]', '["Sin 39:7"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 9, 'Si sökhinia na darua ira, moroi na ha samösa, börö me so dania mböli gölöra si sökhi, ba wa''erege dödöra andrö.', '["Sin 39:7"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 10, 'Na alau zi samösa, ba i''ila ifazaŵa nawönia si samösa; ba alai zi ha samö-samösa, na alau ia, ba lö awönia, ba wamazaŵa ya''ia.', '["Sin 39:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476239, 'OT', 'Sangombakha', 4, 11, 'Ba si manö göi na faedo zi darua ba wemörö, ba lö oafu ira; ba heza ihalö wa lö oafu si ha samösa?', '["Sin 39:7"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 12, 'Ba na so zamalangögö si ha samösa ba la''ila lalaŵa ia si darua; ba sinali si tölu winali, ba ha ŵaraö aetu?', '["Sin 39:7"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 13, 'Ono matua si numana ba si no atua-tua, ba no tohude moroi khö razo si no satua ba sambö tödö, si tebai mamondrongo sa''ae, na so zanenaŵa ya''ia.', '["SamI 15:22; Amaed 15:8"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 14, 'Me no ba gurunga i''otarai [ono matua andrö], ba we''amöi salaŵa, he ŵa''ae no ba mbanua razo andrö tumbu ia mege si numana.', '["SamI 15:22; Amaed 15:8"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 15, 'No u''ila zauri andrö fefu, sowaö-waö ba guli danö, awö nono matua andrö, si samösa andrö, si möi fangali zi samösa no mege.', '["SamI 15:22; Amaed 15:8"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 16, 'Ba si lö mutaha mu''erai niha sato andrö, fefu zi möi ia salaŵa. Ba lö''ö zui dania la''omusoi''ö tödö ia nga''ötö mitou. Me no si lö boto göi da''ö ba folohi angi.', '["SamI 15:22; Amaed 15:8"]', NULL),
  (3476239, 'OT', 'Sangombakha', 4, 17, 'Faigi-faigi gaheu, na möi''ö ba nomo Lowalangi. Na möi ita mamondrongo, ba no si sökhi, moroi na la''ohe zumange nitaba niha sambö tödö; noa sa si lö mangila watahögö ira, ba tobali lalau zi lö sökhi.[3]', '["SamI 15:22; Amaed 15:8"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 1, 'Böi alio-lio mbeweu, ba böi ida''i-da''i tödöu wanguma''ö hadia ia föna Lowalangi; noa sa ba zorugo so Lowalangi ba ya''ugö, ba ba guli danö so''ö: andrö böi oya''ö limö.[1]', '["Amaed 10:19; Mat 6:7","MozIV 30:3; MozV 23:21","Mal 2:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 2, 'Ba zi fahöna fa''abu dödö, ba so wangifi, ba ba zi fahöna li, ba so wehede zambö tödö.', '["Amaed 10:19; Mat 6:7","MozIV 30:3; MozV 23:21","Mal 2:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 3, 'Na öfabu''u hadia ia khö Lowalangi, ba böi arörö''ö wanörö, lö''ö sa omasi ia zambö tödö; hadia nifabu''umö, ba öfalua göi.[2]', '["Amaed 10:19; Mat 6:7","MozIV 30:3; MozV 23:21","Mal 2:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 4, 'Sökhi na lö öfabu''u, moroi na öfabu''u, ba lö ötörö.', '["Amaed 10:19; Mat 6:7","MozIV 30:3; MozV 23:21","Mal 2:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 5, 'Böi tehe ba mbeweu ifo''ömö mbotou, ba böi ömane khö zinenge Lowalangi: no numalö mbewegu! Hana wa [edöna''ö] mofönu Lowalangi, ba deatea mbeweu ba ifufu nilau dangau?[3]', '["Amaed 10:19; Mat 6:7","MozIV 30:3; MozV 23:21","Mal 2:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 6, 'Na fahöna wangifi ba bewe, ba fahöna göi waya-faya. Andrö wa ö''ata''ufi Lowalangi.', '["Amaed 10:19; Mat 6:7","MozIV 30:3; MozV 23:21","Mal 2:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 7, 'Na ö''ila ba danö, lafakao zi numana, ba lafuyu''ö huku ba labila''ö lala, ba böi ahöli-höli dödöu ba da''ö; ifaigi-faigi sa nawönia salaŵa, ba Fondrege zalaŵa zamaigi-maigi ya''ira [fefu].', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 8, 'Ba mohare danö ba da''ö fefu, na so razo somasi fangahalö.', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 9, 'Somasi ana''a, ba tebai abuso ana''a, ba somasi na ebua gana''ania, ba lö isöndra zi ndruhu hare ba da''ö Si lö boto göi da''ö.[4]', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 10, 'Na tedou mbalazo, ba tedou göi zi manga ya''ia, ba hadia hare zokhö, baero wamaigi?', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 11, 'Ba zohalö-halöŵö, ba fangokafu dödö wemörö, he na oya gönia, ba he na lö oya-oya; ba sebua ana''a, ba lö falukha mörö, ba wa''afahöna khönia.', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 12, 'So wamakao safökhö, ni''ilagu ba guli danö: Ana''a sebua ni''irö-irö''ö zokhö, famununia.', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 13, 'Na taya gana''a andrö, na itörö zokhö hadia ia, ba na so nononia, ba lö tosai hadia ia ba danga da''ö.', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 14, 'Si mane mege, me i''otarai dalu ninania, si manö wofanönia dania, lö balu-balu, si mane me awena so ia; ba lö hadia ia i''ohe, böli gölönia ba wa''erege dödönia andrö, noro dangania ena''ö.[5]', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 15, 'Famakao sebua göi da''ö: no fagölö-gölö sibai ira wa''asonia wofanönia, ba hadia harenia, na i''eregesi dödönia ba nangi?', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 16, 'Ba sagötö ya''ia, ba ba zogömi-gömi so ia, ba so wa''abu dödö; ba fahöna wa lö sökhi-sökhi dödönia ba fa''afökhö ba fa''abao dödö.', '["Yob 20:20","Yob 1:21; TimI 6:7"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 17, 'Si ndruhu, ni''ilagu si sökhi ba somasi ita, ba ya''ia na manga-manga niha ba na ibadu-badu hadia ia, na i''abusoi''ö ia si sökhi, ba wa''erege dödönia andrö fefu, ba nifakaonia ya''ia ba guli danö, götö wa''anau nosonia, nibe''e Lowalangi khönia; me no da''ö dana khönia.[6]', '["Faigi 2:24; 3:12"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 18, 'Ba he na so niha, nibe''e Lowalangi ana''a ba okhöta hadia ia, ba na no itolo ia ba wemanga si so andrö ba ba wanema urakhania, ba ba wangomusoi''ö tödönia halö-halöŵönia: ba buala Lowalangi da''ö.', '["Faigi 2:24; 3:12"]', NULL),
  (3476240, 'OT', 'Sangombakha', 5, 19, 'Lö''ö sa börö itörö tödö niha si manö, wa lö anau nosonia; na itehe khönia Lowalangi wa''omuso dödönia andrö.', '["Faigi 2:24; 3:12"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 1, 'So wamakao ni''ilagu ba guli danö, si no tohare sibai ba hulu niha:', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 2, 'Na so nibe''e Lowalangi ana''a ba girö-girö ba fa''ebua döi, na tobali lö ambö khönia hadia ia zomasi ia, ba na lö itehe khönia Lowalangi i''a; na niha bö''ö zi manga, ba si lö boto da''ö ba famakao safökhö.', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 3, 'Na so zi otu ono, ba na ha me uga fakhe ia ba guli danö, na anau nosonia, ba na lö i''a zi sökhi andrö, ba na lö''ö göi lako''o ia [na no mate ia], ba da''ö niŵa''ögu: tabina saekhu, ba no sohahau tödö moroi khönia.', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 4, 'Noa sa ba wa lö boto so da''ö, ba ba zogömi-gömi lalania, ba si tobalu fa''ogömi-gömi döinia;', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 5, 'ba lö''ö göi ni''ilania haga zi moluo, lö saboto ba dödönia: ba ohahau dödönia, moroi ba da''ö no mege.', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 6, 'Ba he mendrua wa hönö fakhe wa''anau nosonia, ba na lö ni''ania si sökhi, ba hadia, tenga ha sambua nahiara fefu dania?', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 7, 'Fefu hadia ia halöŵönia, ba börö dölö-tölönia; ba lö''ö manö zui döhö wangisönia andrö.', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 8, 'Hadia sa zi tohude zatua-tua, moroi ba zambö tödö? Ba hadia zi tohude zi numana, sangila manörö lala si sökhi, ba zanehe niha sauri?', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 9, 'Sökhi na ha famaigi hörö, moroi na si lö ahono-hono wangisö andrö. Si lö boto göi da''ö ba folohi angi.', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 10, 'Hadia zanörö niha, ba no ara, me lafotöi ia, ba no muhonogöi, he wisa niha dania, ba tebai fasoso ia ba zabölö moroi khönia.[1]', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 11, 'He na oya linia, fonönö wa lö boto, ba hadia hare niha?[2]', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476241, 'OT', 'Sangombakha', 6, 12, 'Ha niha sa zangila, hadia zoguna ba niha, ba we''asonia ba guli danö, götö wa''anau nosonia andrö si lö boto, silalö hulö lumö-lumö? Ha niha sa zangombakha ba niha, he wisa dania ba guli danö, na lö ya''ia sa''ae?[3]', '["Yob 4:17; 9:2","Faigi 1:3","Yob 7:7; 14:1; Sin 144:4; Faigi 8:7"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 1, 'Sökhi döi si sökhi, moroi ba wanikha [famayoini] si sökhi, ba sökhi mbaŵa wa''amate, moroi ba mbaŵa wa''atumbu.[1]', '["Amaed 22:1","KorII 7:10","Amaed 15:31","MozII 23:8"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 2, 'Sökhi we''amöi ba nomo, ba ni''e''esi si mate, moroi ba we''amöi ba nomo ba nibadu-badu tuo; amozua niha fefu sa da''ö no mege, ba möi ba dödö zi so noso na.', '["Amaed 22:1","KorII 7:10","Amaed 15:31","MozII 23:8"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 3, 'Sökhi wa''abu dödö, moroi ba wa''iki; ohahau sa dödö, na mangerau mbawa.[2]', '["Amaed 22:1","KorII 7:10","Amaed 15:31","MozII 23:8"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 4, 'Ba nomo ba ni''e''esi si mate so dödö zatua-tua, ba tödö zambö era-era, ba ba nomo ba zomuso dödö niha so.', '["Amaed 22:1","KorII 7:10","Amaed 15:31","MozII 23:8"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 5, 'Sökhi wamondrongo fanegu zatua-tua, moroi ba wamondrongo wanunö zambö tödö.[3]', '["Amaed 22:1","KorII 7:10","Amaed 15:31","MozII 23:8"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 6, 'Me no hulö wa''ofetufetu manawa, na labe''e eu galitö wa''iki zambö tödö: no faya-faya göi da''ö.', '["Amaed 22:1","KorII 7:10","Amaed 15:31","MozII 23:8"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 7, 'Si taya sa gera-era zatua-tua, na lafalangögö ia, ba na labe''e önia gana''a, ba tefuyu dödönia.[4]', '["Amaed 22:1","KorII 7:10","Amaed 15:31","MozII 23:8"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 8, 'Sökhi lua-lua hadia ia, moroi ba mbörötania. Sökhi zebolo tödö, moroi ba zi fayaŵa.', '["Yak 1:19,20","Yes 6:40"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 9, 'Böi alio-lio abao dödöu, me no barö doto zambö era-era so wa''abao dödö.[5]', '["Yak 1:19,20","Yes 6:40"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 10, 'Böi ömane: Hadia mbörö, wa no sökhi götö föna, moroi ba götö da''e? Tenga sa fanofu zatua-tua da''ö.', '["Yak 1:19,20","Yes 6:40"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 11, 'No timba göndröita zatua wa''atua-tua, ba no soguna sibai ba zangila haga zi moluo.', '["Yak 1:19,20","Yes 6:40"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 12, 'Ba''a-ba''a zino sa''ae wa''atua-tua ba ba''a-ba''a zino [göi] gana''a, ba hare ba wa''aboto ba dödö, ba i''orifi zi so ya''ia fa''atua-tua andrö.[6]', '["Yak 1:19,20","Yes 6:40"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 13, 'Faigi-faigi nilau-lau Lowalangi; ha niha sa zangila mangadölö niköi''önia?', '["Yak 1:19,20","Yes 6:40"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 14, 'Na baŵa si sökhi ba omusoi''ö dödöu; ba na baŵa si lö sökhi, ba ömane dödöu: nibe''e Lowalangi göi da''ö, si mane si sökhi andrö, ena''ö lö''ö sa''ae irongo hadia ia, baero ö, niha, dania.', '["Yak 1:19,20","Yes 6:40"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 15, 'No ahori u''ila ba götögu andre: Soso zatulö tödö, si tekiko ba wa''atulö dödöra andrö, ba soso zebua horö, sanau noso, ba walösökhira.', '["Rom 12:3","RazI 8:40; Rom 3:10"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 16, 'Böi töra wa''atulömö, ba böi atua-tua sibai ndra''ugö öŵa''ö: hana wa öfakiko''ö?[7]', '["Rom 12:3","RazI 8:40; Rom 3:10"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 17, 'Böi abölögö wanao horö ba böi sambö era-era ndra''ugö! Hana wa omasi''ö mate, na lö''ö na inötö khöu?', '["Rom 12:3","RazI 8:40; Rom 3:10"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 18, 'Sökhi na ö''aro''ö khöu zi sambalö ba na lö''ö göi iböhöli tangau zi sambalö; sangata''ufi Lowalangi sa, ba lö göna ia da''ö fefu.', '["Rom 12:3","RazI 8:40; Rom 3:10"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 19, 'Fa''atua-tua andrö, ba i''abe''e''ö zatua-tua, moroi ba zi dafulu sabölö, si so yomo ba mbanua.', '["Rom 12:3","RazI 8:40; Rom 3:10"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 20, 'Lö''ö sa niha satulö ba guli danö solau si sökhi lö olalöŵa.[8]', '["Rom 12:3","RazI 8:40; Rom 3:10"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 21, 'Böi göi töngöni deatea mbewe andrö fefu, nilau-lau, fa böi örongo i''elifi''ö sawuyumö.', '["Rom 12:3","RazI 8:40; Rom 3:10"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 22, 'Me no asese ö''elifi göi niha bö''ö, si lö olifu''ö.', '["Rom 12:3","RazI 8:40; Rom 3:10"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 23, 'Da''ö fefu, ba no utandraigö, ba wa''atua-tua andrö; no umane dödögu: "Omasido na atua-tua ndra''odo," ba lö''ö sa ihatö''ö ia khögu.', '["Rom 10:6 b.t.; 11:33","Faigi 1:17"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 24, 'No aröu zi so andrö, ba no abakha sibai; ha niha zogamö?[9]', '["Rom 10:6 b.t.; 11:33","Faigi 1:17"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 25, 'Ba no u''otahögö, no ube''e dödögu, ena''ö aboto ba dödögu ba ena''ö usöndra; ba wangalui fa''atua-tua ba fame''e ba lala, ba ena''ö aboto ba dödögu, wa no fa''ambö tödö wanao horö, awö wa fa''owöhö sa''ae wa''owöhö mowa andrö.[10]', '["Rom 10:6 b.t.; 11:33","Faigi 1:17"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 26, 'Ba no safeto moroi ba wa''amate ndra alawe usöndra; no timba gu''ö ia, ba tödönia, ba no timba dandraŵa, ba tangania, ba fesu. Somasi Lowalangi, ba lö alau khönia, ba si so horö, ba te''ala ibe''e.', '["Rom 10:6 b.t.; 11:33","Faigi 1:17"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 27, 'Hiza, da''ö nisöndragu, iŵa''ö sangombakha, no u''ozaragö, ena''ö usöndra wozu.', '["Rom 10:6 b.t.; 11:33","Faigi 1:17"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 28, 'Da''ö ni''alu-aluigu, ba lö nisöndragu: Ira matua, ba samösa ba zi hönö usöndra, ba ira alawe, ba samösa lö''ö ba da''ö fefu.', '["Rom 10:6 b.t.; 11:33","Faigi 1:17"]', NULL),
  (3476242, 'OT', 'Sangombakha', 7, 29, 'Hiza, ha da''ö nisöndragu: no adölö dödö niha, womböi Lowalangi ya''ia, ba ya''ira, ba no oya la''alui göi-köi.', '["Rom 10:6 b.t.; 11:33","Faigi 1:17"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 1, 'Ha niha zi no si mane satua-tua? ba ha niha zi no aboto ba dödö eluaha hadia ia? — Fa''atua-tua niha andrö, ba humaga mbawa niha ibe''e, ba tobali walösökhi mbawa.', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 2, 'Da''ö niŵa''ögu: töngöni goroisa razo, börö wahölusa andrö ba Lowalangi.[1]', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 3, 'Böi aösö erogö ia (razo); böi babaya huhuo si lö sökhi.', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 4, 'Fefu hadia ia sa zomasi ia, ba ilau, me no sabölö li razo ba ha niha zi tola manofu khönia: Hadia nilaumö?', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 5, 'Sanöngöni oroisania, ba lö falukha zi lö sökhi, ba inötö ba huku isöndra tödö zatua-tua.', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 6, 'Fefu hadia ia sa nilau, ba so ginöto ba so huku, me no noro niha zi lö sökhi andrö khönia.', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 7, 'Lö''ö sa i''ila hadia zi so dania; ba he wisa lala dania, ba ha niha zamokai khönia?[2]', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 8, 'Lö niha sabölö moroi ba nangi, fa i''ila ena''ö iba''a nangi, ba lö sabölö moroi ba mbaŵa wa''amate, ba lö fangefa ba wanuwö; ba fanao horö andrö, ba lö i''orifi zama''ua.[3]', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 9, 'Da''ö fefu ni''ilagu, börö me no utöngötöngöni fefu nilau-lau ba guli danö, götö wa ibali''ö ia samatörö awönia niha, ba wangalani ya''ia.', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 10, 'Ba noa göi u''ila zebua horö, niko''o, sogamö folombase, ba tenga ba naha ni''amoni''ö monahia zolau satulö mege, ba olifu mbanuara ira. Faya-faya göi da''ö.', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 11, 'Me mogasa wamatörö huku ba nilau zi lö sökhi andrö, andrö wa itugu abe''e dödö nono niha, ba wolau si lö sökhi,', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 12, 'me meotu ilau zi lö sökhi si so horö, ba anau nosonia ba da''ö, he ŵa''ae no aboto ba dödögu, wa sohahau tödö dania zangata''ufi Lowalangi, samondrongo linia.[4]', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 13, 'Ba tenga sohahau tödö dania zanao horö, no timba lumö, wa lö anau nosonia, me no tenga sangata''ufi Lowalangi ia.', '["Amaed 24:21; Rom 13:1 b.t.","Faigi 7:1","Yob 14:5; Sin 39:6","Sin 37:18; Amaed 1:33; Yes 3:10"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 14, 'So zi hulö waya, ba guli danö, ya''ia wa so zatulö tödö si falukha lua-lua wolau zebua hörö, awö wa so zebua horö si falukha lua-lua wolau zatulö tödö. Ba no umane: Faya göi da''ö![5]', '["Sin 37:11–14","Faigi 2:24; 3:12,15; 5:18"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 15, 'Ba no usuno wa''omuso dödö; me no fondrege zi sökhi ba niha ba guli danö, na manga-manga ia ba na ibadu-badu hadia ia, na i omusoi''ö dödönia; ba ya lö aefa-aefa khönia da''ö ba wa''erege dödönia andrö, götö wa''anau nosonia, nibe''e Lowalangi khönia ba guli danö.[6]', '["Sin 37:11–14","Faigi 2:24; 3:12,15; 5:18"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 16, 'Ba me ube''e dödögu, ena''ö aboto ba dödögu wa''atua-tua andrö, ba ba wamaigi-maigi nilau-lau ba guli danö, — me lö falukha alau hörö niha, he ba zi bongi ba he ba zi ma''ökhö —', '["Sin 37:11–14","Faigi 2:24; 3:12,15; 5:18"]', NULL),
  (3476243, 'OT', 'Sangombakha', 8, 17, 'ba no u''ila, wa tebai aboto ba dödö niha wolau Lowalangi fefu, folau-launia andrö ba guli danö, me i''eregeregesi dödönia niha, ba wangalui, ba me lö''ö zui isöndra, ba he na iŵa''ötödönia satua-tua, no aboto ba dödönia, ba lö''ö zui isöndra.', '["Sin 37:11–14","Faigi 2:24; 3:12,15; 5:18"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 1, 'Da''ö fefu sa, ba no utöngöni sibai ba no u''alu-alui fefu: wa no ba danga Lowalangi so zatulö tödö ba satua-tua, fabaya nilau-laura andrö; he fa''omasi, ba he fatiusa, ba tenga si no tohöna i''ila niha; oi si so fönara fefu.', '[]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 2, 'Faoma i''ila itörö ira fefu hadia ia: ha sambalö zi göna ira, he satulö tödö, ba he sebua horö, he si sökhi, sohau-hau, ba he si ra''i-ra''iö, he same''e sumange, ba he si lö mame''e sumange; si mane ba zi sökhi göi ba zi so horö, ba si mane ba zi möi ba hölu göi ba zata''u hölu.', '[]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 3, 'Famakao da''ö, ba ngawalö hadia ia fefu ba guli danö, wa no ha sara manö zi göna ira fefu, ba tobali fahöna manö ba dödö nono niha zi lö sökhi, ba fa''owöhö mowa ba dödöra, sagötö ya''ira; ba aefa da''ö, ba möi ba mbanua tou.', '[]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 4, 'Na awö zauri fefu na niha, ba lö saetu wanötöna; sökhi sa nasu sauri, moroi ba zingo si no mate.', '[]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 5, 'Sauri sa, ba no la''ila, wa si mate ira dania, ba si no mate, ba lö hadia ia la''ila, ba lö''ö sa''ae böli gölöra, lö''ö sa''ae itörö tödö niha bö''ö ira.', '[]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 6, 'He fa''omasira ba he fatiusara ba fönura, ba no ara sa''ae numalö, ba lö''ö sa''ae hadia ia zo''urakha ira, ba guli danö.', '[]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 7, 'Ba labu sa''ae, omusoi''ö dödöu wemanga göu, awö wamadu agu khöu; no ara sa''ae, me itehe wolaumö andrö Lowalangi.', '["Yer 9:23"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 8, 'Böi tebulö wa''afusi nukhau ba böi manö ambö wanikha ba mbumö.', '["Yer 9:23"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 9, 'Omusoi''ö dödöu ba wa''aurimö, awö wo''omou somasi''ö, götö wa''anau nosou andrö, si lö boto, nibe''e Lowalangi khöu, ba guli danö, si sagötö ya''ugö, si no faya-faya; me no da''ö dana khöu, ba wa''auri andrö, ba ba wa''erege dödöu andrö, nifakaomö ya''ugö, ba guli danö.', '["Yer 9:23"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 10, 'Fefu hadia ia ni''ilamö ölau tangau, ba wa''abölömö andrö, ba ölau; ba mbanua tou andrö sa, ba zi möi''ö dania, ba lö halöŵö ba lö fa''onekhe ba lö fa''aboto ba dödö ba lö fa''atua-tua.', '["Yer 9:23"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 11, 'Ba so zui ni''ilagu ba guli danö: no tenga ba zalio ahe wagohisa, ba tenga ba zabölö wanuwö, ba tenga göi ba zatua-tua gö, ba tenga ba zonekhe wa''ebua gana''a, ba tenga ba zaboto ba dödö wa''ebua dödö; no ha sambua ginötö ba no ha sara zi göna ira fefu.[1]', '["Yer 9:23"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 12, 'Lö''ö na''i i''ila ginötö khönia niha: si mane i''a nifa''u''u ba ndriala famunu ba si mane fofo, nifa''ala ba dandraŵa, — si manö göi wama''ala niha, na baŵa wamunu, na ihawui ira, si lö mudöna-döna.', '["Yer 9:23"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 13, 'Ba da''ö na göi ni''ilagu fa''atua-tua ba guli danö, ba sebua da''ö wamaigigu:', '["Amaed 21:22"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 14, 'banua side-ide, si lö atoto niha, ba isuwö ira razo sebua, ifa''u''u mbanua ba ifalau''ö mba''a-ba''a sebua ba gero göli.', '["Amaed 21:22"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 15, 'Ba no so yomo ba mbanua andrö niha si numana, samösa, satua-tua, da''ö zangorifi banua andrö ena''ö, ba wa''onekhenia; ba samösa lö si lö olifu niha si numana andrö.', '["Amaed 21:22"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 16, 'Ba umane dödögu: Si sökhi moroi ba wa''abölö wa''atua-tua, ba fa''atua-tua zi numana andrö, ba no lö ba dödö niha [bö''ö], ba linia, ba lö lafondrondrongo.[2]', '["Amaed 21:22"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476244, 'OT', 'Sangombakha', 9, 17, 'Taroma li zatua-tua, na ba wa''ahono-hono tafondrondrongo, ba no si sökhi moroi ba we''ao zalaŵa zowöhö mowa.', '["Amaed 21:22"]', NULL),
  (3476244, 'OT', 'Sangombakha', 9, 18, 'Fa''atua-tua, ba no si sökhi moroi ba wangöna, ba oya ifakuyu si sökhi niha si so horö, he ha samösa ia.', '["Amaed 21:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 1, 'Na so deteho, ba aböu ba owoyu wanikha khö zamazökhi dalu-dalu labe''e; si manö göi, wa no ebua wa''owöhö mowa, si ha ma''ifu, moroi ba wa''atua-tua ba moroi ba wa''ebua döi.', '[]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 2, 'Tödö zatua-tua, ba no ba gambölönia so, ba tödö zambö tödö, ba no ba gabera.', '[]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 3, 'Ba he ba lala, na itörö sowöhö mowa, ba no sambö tödö ia, ba idozigö niha wangombakha, wa no sowöhö mowa ia.', '[]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 4, 'Na tesao khöu wönu zalaŵa, ba böi bulö''ögö ba nahau, isösö sa horö sebua fa''ebolo dödö.', '[]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 5, 'So wamakao ni''ilagu ba guli danö, hulö zi fasala, khö zalaŵa mbörö:', '[]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 6, 'Te''alaŵa''ö yaŵa wa''owöhö mowa, alaŵa sibai, ba tou dumao-dao zebua ana''a.', '[]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 7, 'Ba hulu kudo u''ila zawuyu, ba mowaö-waö zalaŵa, si mane sawuyu.', '[]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 8, 'Sogau lösu-lösu, ba ma ya''ia zaekhu bakha, ba sanudugö öli gara, ba ma idou ia ulö.[1]', '["Sin 7:16","Sin 58:5,6","Luk 4:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 9, 'Samo''ai kara, ba ma mesokho ia khönia, ba sanila eu, ba ma tetaru ba dangania.', '["Sin 7:16","Sin 58:5,6","Luk 4:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 10, 'Na no afuru zi''öli, na lö nidalinia bawa, ba erege dödönia; ba hare ba wangehao, ba no fa''atua-tua.', '["Sin 7:16","Sin 58:5,6","Luk 4:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 11, 'Na fadou gulö lö mutaka, ba lö hare zanaka.[2]', '["Sin 7:16","Sin 58:5,6","Luk 4:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 12, 'Taroma li zatua-tua, ba no omasiö, ba bewe zambö tödö zamakiko ya''ia.[3]', '["Sin 7:16","Sin 58:5,6","Luk 4:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 13, 'Na ibörögö wehede sa, ba no fa''ambö tödö, ba fozu wehedenia, ba fa''owöhö mowa si lö sökhi.', '["Sin 7:16","Sin 58:5,6","Luk 4:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 14, 'Ba oya mbewe zowöhö mowa, ba lö''ö sa i''ila niha, he wisa dania; ba he wisa furinia dania, ba ha niha zamokai khönia?', '["Sin 7:16","Sin 58:5,6","Luk 4:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 15, 'Fangerege dödönia wamakao zambö tödö andrö, si tebai na''i möi miyomo ba mbanua.', '["Sin 7:16","Sin 58:5,6","Luk 4:22"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 16, 'Alai ndra''ugö ya''ugö tanö, ba zi no möi razo ndraono, ba ba zamorege femanga-manga ba famadu-madu hadia ia zalaŵa, na mahemolu mbanua![4]', '["Yes 3:4; 5:11","Sanguhuk 9:13; Sin 104:15","MozII 22:28"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 17, 'Ba ya ahowu ndra''ugö, ya''ugö tanö ba zi no möi razo zatulö tödö, ba ba nifaigi zalaŵa inötö wemanga, ba wangabe''e ya''ira, ba tenga ba wemabu-mabu.', '["Yes 3:4; 5:11","Sanguhuk 9:13; Sin 104:15","MozII 22:28"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 18, 'Fa''areu mbörö wa''adudu mbulu nomo, ba fa''atebai danga mbörö wa''aböla zagö.', '["Yes 3:4; 5:11","Sanguhuk 9:13; Sin 104:15","MozII 22:28"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 19, 'Ba wangomusoi''ö tödö talau manga-manga, ba owua-wua dödö ibe''e agu andrö, ba na so gana''a, ba oi so manö hadia ia fefu.[5]', '["Yes 3:4; 5:11","Sanguhuk 9:13; Sin 104:15","MozII 22:28"]', NULL),
  (3476245, 'OT', 'Sangombakha', 10, 20, 'He ha ba dödöu, ba böi elifi razo, ba ba wörömamö, ba böi elifi zebua ana''a; ma dania la''oloi''ö limö fofo ba dalu mbanua, ba ma la''ombakha''ö niŵa''öu so''afi.[6]', '["Yes 3:4; 5:11","Sanguhuk 9:13; Sin 104:15","MozII 22:28"]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 1, 'Fa''ohe''ö misi yefo mbalazou, ba na no ara, ba mangawuli khöu.', '["MozV 15:10; Amaed 19:17; Efes 5:16","Sin 139:15, Yoh 3:8"]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 2, 'Ö''ofitu, ba ma zui ö''oŵalu, lö''ö sa ö''ila, hadia wamakao dania ba guli danö.[1]', '["MozV 15:10; Amaed 19:17; Efes 5:16","Sin 139:15, Yoh 3:8"]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 3, 'Na no mo''ösi lawuo, ba aekhu ba danö deu; ba na aso''a geu, he raya, ba he yöu — ba zaso''a geu, ba da''ö lö tebulö ia.', '["MozV 15:10; Amaed 19:17; Efes 5:16","Sin 139:15, Yoh 3:8"]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 4, 'Samaigi-maigi angi, ba lö manaru, ba samaigi-maigi lawuo, ba lö mamasi.', '["MozV 15:10; Amaed 19:17; Efes 5:16","Sin 139:15, Yoh 3:8"]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 5, 'Me no lö ö''ila, hadia lala nangi, ba he wisa wanöi döla dabina ba dalu nina ba si manö göi wa lö aboto ba dödöu halöŵö Lowalangi andrö, solau-lau fefu hadia ia.[2]', '["MozV 15:10; Amaed 19:17; Efes 5:16","Sin 139:15, Yoh 3:8"]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 6, 'Ba zanguhulö wongi fazaewe danömö zinanö khöu, ba böi göi böda dangau, na tanö owi; me no lö ö''ila, heza so zofozu, na si föföna, ba na safuria, ba na faoma manö sökhi lua-lua.', '["MozV 15:10; Amaed 19:17; Efes 5:16","Sin 139:15, Yoh 3:8"]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 7, 'Ba no omasiö haga, ba fangokafu hörö, na ta''ila luo.', '[]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 8, 'Na ha me uga fakhe sa wa''anau noso niha, ba yamu''omusoi''ö dödönia, götö da''ö, ba yamutörö tödönia mbaŵa wa''ogömi-gömi andrö, wa tenga si lö ara dania. Fefu hadia ia zi falukha ita, ba no faya-faya.', '[]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 9, 'Omusoi''ö dödöu, ya''ugö ono matua, fatua ono matua ndra''ugö, ya sowua-wua dödöu, götö wa ono matua ndra''ugö, ba törö nidönisi dödöu ya''ugö, awö ni''ila höröu, ba böi zi lö aboto ba dödöu, wa i''ohe ba wanguhuku dania ndra''ugö Lowalangi, börö da''ö fefu.', '[]', NULL),
  (3476246, 'OT', 'Sangombakha', 11, 10, 'Timba wa lö sökhi-sökhi dödöu, ba faigi, fa böi ihatö''ö ia ba nösiu famakao; noa sa faya-faya wa''a''onomatua ba fa''aitö mbu.', '[]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 1, 'Ba törö-törö tödöu zomböi ya''ugö, götö wa ono matua na ndra''ugö, fatua lö baŵa si lö sökhi andrö ba fatua lö ahatö na ndröfi andrö, niŵa''öu dania: lö omasido!', '["MozI 3:19; Sin 90:3"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 2, 'Fatua lö ndrundrumö luo ba haga andrö ba baŵa ba döfi, ba fatua lö ifuli alu, na no aefa deu —', '["MozI 3:19; Sin 90:3"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 3, 'na luo manizi-nizi zanaro omo ba na laköröbui ira ira matua sabölö, ba na lö''ö sa''ae halöŵö zohama fakhe, me lö atoto sa''ae ira, na ndrundrumö sa''ae zamaigi-maigi ba zandrela,', '["MozI 3:19; Sin 90:3"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 4, 'ba na tekusi sa''ae mbawandruhö salua ba newali, na alö wekokokoko halu andrö, ba na maoso niha na irongo li wofo, ba na lö ebua-bua tö li, na manunö.', '["MozI 3:19; Sin 90:3"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 5, 'Ba na anuzu göi dödöda hili-hili, ba na so gameta''uö ba lala, ba na mobowo kare ba na amaedola zanana larewe, ba na lö fa''omuso dödö sa''ae. Na isaŵa nomonia si lö tebulö niha, ba na ladörö-dörö newali sange''esi. —', '["MozI 3:19; Sin 90:3"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 6, 'Fatua lö aetu zinali firö andrö ba fatua lö aboto mako ana''a, ba fatua lö arasa nasoa ba mba''a ba fatua lö adudu roda ba mba''a,', '["MozI 3:19; Sin 90:3"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 7, 'ba fatua lö mangawuli ba danö gawu-gawu andrö, ba zi so ia mege, ba fatua lö mangawuli ba Lowalangi mbekhu, khö Lowalangi same''e ya''ia mege.[1]', '["MozI 3:19; Sin 90:3"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 8, 'Alai waya-faya andrö, si tumbu ba waya-faya! iŵa''ö sangombakha, oi faya-faya manö.', '["MozI 3:19; Sin 90:3"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 9, 'Ba baero ö — wa no satua-tua zangombakha andrö — ba ifahaö niha sato ba wa''aboto ba dödö, ba itimbatimba tödönia ba i''alu-alui ba oya iŵa''ö amaedola.[2]', '["RazI 4:32","Faigi 7:28","MozV 6:2; 10:12","Faigi 11:9; Rom 2:16; KorII 5:10"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 10, 'I''alu-alui sangombakha andrö, ena''ö isöndra wehede omasiö, awö nitanö ba zura, ba wa''adölö dödö, taroma li si ndruhu-ndruhu.', '["RazI 4:32","Faigi 7:28","MozV 6:2; 10:12","Faigi 11:9; Rom 2:16; KorII 5:10"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 11, 'Taroma li zatua-tua, ba no timba ndroi manaze, ba timba gosö-osö nitaru''ö daroma li ni''ozaragö andrö, niŵa''ö gubalo mbiri-biri, si ha samösa.[3]', '["RazI 4:32","Faigi 7:28","MozV 6:2; 10:12","Faigi 11:9; Rom 2:16; KorII 5:10"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 12, 'Ba baero ö na: Ya''ugö onogu, ba be''e nifangelama ndra''ugö! Famazökhi zura andrö, soya sibai, ba no si lö aetu, ba fangalungalui niha andrö tödönia, ba no fangerege dödö.', '["RazI 4:32","Faigi 7:28","MozV 6:2; 10:12","Faigi 11:9; Rom 2:16; KorII 5:10"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 13, 'Fozu hadia ia fefu tafondrondrongo: Ata''ufi Lowalangi, ba o''ö goroisania! da''ö sa zi nangea ba niha fefu.[4]', '["RazI 4:32","Faigi 7:28","MozV 6:2; 10:12","Faigi 11:9; Rom 2:16; KorII 5:10"]', NULL),
  (3476247, 'OT', 'Sangombakha', 12, 14, 'Fefu hadia ia nilau sa, ba i''ohe ba wanguhuku Lowalangi, ba wanguhuku si tobini andrö fefu, he si sökhi, ba he si lö sökhi.[5]', '["RazI 4:32","Faigi 7:28","MozV 6:2; 10:12","Faigi 11:9; Rom 2:16; KorII 5:10"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 1, 'Sinunö sebua khö Zelomo.', '[]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 2, 'Ena''ö na fa''ago bawa ia khögu; no omasiö moroi ba nagu wa''omasiu ndra''odo.[1]', '["Faigi 4:10","Sin 120:5","Yes 5:1 b.t."]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 3, 'Amohua sibai dalu-dalu famayoini andrö khöu; no fanikha nifaduwa döimö andrö, andrö wa la''omasi''ö ndra''ugö ono alawe.', '["Faigi 4:10","Sin 120:5","Yes 5:1 b.t."]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 4, 'Dönisido khöu; data''aliogö ita! — ya''odo, ba no i''ohe si bakha khönia razo. Damalau ma''iki, ma''omusoi''ö dödöma khöu; fa''omasimö andrö, ba masuno, moroi ba wanunoma agu; no si nangea, na la''omasi''ö ndra''ugö!', '["Faigi 4:10","Sin 120:5","Yes 5:1 b.t."]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 5, 'Si no aitö ndra''o, ba omasiö zui, ya''ami ono alawe, banua Yeruzalema, timba nose Gedara ba timba goloso nose Zelomo.[2]', '["Faigi 4:10","Sin 120:5","Yes 5:1 b.t."]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 6, 'Böi mifaigi-faigi ndra''o, wa si no aitö ndra''odo, wa no aitö nösigu ba zino. No mofönu khögu nono ninagu, ono matua; no lafataro sanaro kabu nagu ndra''odo — kabu nagu khögu, ba lö nitarogögu![3]', '["Faigi 4:10","Sin 120:5","Yes 5:1 b.t."]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 7, 'Ombakha''ö khögu, ya''ugö somasi dödögu: Heza ö''ohe mbiri-biri khöu? heza molombase ndra''ugö, na laluo? Hana sa wa öbe''e samalugö bawania ndra''odo ba ngawawa mbiri-biri khö nawöu?', '["Faigi 4:10","Sin 120:5","Yes 5:1 b.t."]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 8, 'Na lö ö''ila, ya''ugö fondrege zi sökhi ndra alawe, ba ae si tou, osisi lahe mbiri-biri, ba ohe ba ndru''u nono nambi khöu, ba zinga nose gubalo.', '["Faigi 4:10","Sin 120:5","Yes 5:1 b.t."]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 9, 'Timba kudo si alawe khögu ba gureta Wara''o ube''e ndra''ugö, ya''ugö ono alawe si fahuwu khögu.', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 10, 'Omasiö ba mbo''ömö raeŵe-raeŵe andrö, awö naya ba mbagiu.[4]', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 11, 'Ba dalafazökhi khöu raeŵe-raeŵe ana''a, nidumbodumboi firö.', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 12, 'Götö wa dumao-dao ba gasonia razo, ba lö si tebulö wa''amohua narawasu andrö khögu.[5]', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 13, 'Somasido andrö, ba no timba nga''ölu emuri, sahono ba dotogu;', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 14, 'timba mbunga khorema, ba kabu nagu Engedi zomasi ndra''o khögu.', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 15, 'Ha lö asökhi ndra''ugö, ya''ugö si fahuwu khögu; ha lö asökhi ndra''ugö! Hörömö andrö, ba no hörö marafadi.[6]', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 16, 'Ha lö asökhi ndra''ugö, ya''ugö ira matua, somasi ndra''o, ha lö omasiö; du''u sauri dufoda.[7]', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476248, 'OT', 'Sinunö Sebua', 1, 17, 'Eu nomoda, ba no eresi, ba senobari mbagolö.', '["Amaed 2:9; 6:21; 16:16","Mat 14:3","Faigi 4:1; 5:12","Yes 33:17"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 1, 'Lahine ba mbenua Zarona ndra''odo, ladari mböhö ba ndraso.', '["Esit 7:8","Amaed 9:2","Faigi 8:3","Amaed 5:19"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 2, 'Si mane ladari mböhö barö za''a-sa''a mao, si manö zi fahuwu khögu ba gotalua nono alawe [bö''ö].', '["Esit 7:8","Amaed 9:2","Faigi 8:3","Amaed 5:19"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 3, 'Si mane ma''ufa barö geu gatua, si manö zomasi ndra''o ba gotalua nono matua [bö''ö]. Ba lumönia omasido dumadaodo, ba ami ba gararogu mbuania.', '["Esit 7:8","Amaed 9:2","Faigi 8:3","Amaed 5:19"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 4, 'No i''ohe ba nomo nagu ndra''o, ba mandrerania yaŵagu, ba no fa''omasi.[1]', '["Esit 7:8","Amaed 9:2","Faigi 8:3","Amaed 5:19"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 5, 'Mi''abe''e''ö ndra''o kue mbua nagu, mi''okafui dödögu bua ma''ufa, me no sofökhö ndra''o fökhö fa''omasi.[2]', '["Esit 7:8","Amaed 9:2","Faigi 8:3","Amaed 5:19"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 6, 'Yamutaya högögu tangania kabera, ba yamu''omösido kambölönia.[3]', '["Esit 7:8","Amaed 9:2","Faigi 8:3","Amaed 5:19"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 7, 'Ube''e ba hölu ami, ya''ami ono alawe, banua Yeruzalema, hölu nago ba böhö si alawe ba mbenua: Böi mikeani wa''omasi andrö, böi misusugi, mibe''e lalazi ia.[4]', '["Esit 7:8","Amaed 9:2","Faigi 8:3","Amaed 5:19"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 8, 'Fondrondrongo! So zomasi ndra''o! Hiza, so ia moroi sa, isawö hili, ifanokanoka ia ba hili-hili.[5]', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 9, 'No timba nago zomasi ndra''o, ba ma timba nono mböhö. No irugi gero nomoma, ifaigi-faigi ba zandrela, ihörö-hörögö ba darali.', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 10, 'Humede zomasi ndra''o, imane khögu: Faoso, si fahuwu khögu, si sökhi andrö khögu, aine!', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 11, 'Noa sa atö aefa mbaŵa wa''oafu, no döhö deu, no mumalö.', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 12, 'Tumbu mbunga ba danö; no irugi baŵa, ba woguti ŵeŵe nagu, ba terongo sa''ae li wune, ba danöda.', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 13, 'Bua ara, ba ibörötaigö asoso ba mobowo nagu, amohua. Faoso, si fahuwu khögu, si sökhi andrö khögu, aine!', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 14, 'Marafadigu, si so ba dögi gara, ba mbini-mbini andrö, ba gara, oroma''ö khögu mbawau, ba hana na urongo limö! Sami sa limö andrö ba omasiö wangila ya''ugö.[6]', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 15, 'Mifa''ala khöda nasu gatua andrö, ono nasu gatua, samufu kabu nagu, me no sobowo nagu ba kabuda.[7]', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 16, 'No khögu zomasi ndra''o andrö, ba khönia ndra''odo, khönia sokubaloi biri-birinia ba zi so ladari mböhö.[8]', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476249, 'OT', 'Sinunö Sebua', 2, 17, 'Irege okafu zino, ba irege taya lumö. Fuli''ö, ya''ugö somasi ndra''o, ya timba nago ndra''ugö, ba ma timba nono mböhö ba hili si no fahöna bawa danö andrö.', '["Yoh 3:29","Sin 27:5","Hez 13:4","Faigi 6:2"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 1, 'Ba gasogu ba zi bongi u''alu-alui zomasi dödögu andrö, no u''alu-alui ia, ba lö usöndra.[1]', '["Sin 119:55; Yes 26:9","Yoh 20:13","Faigi 2:7"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 2, 'Ba damaoso ndra''o ba utöröi newali ba mbanua; ba kade ba ba newali misa u''alui zomasi dödögu; no u''alui ia, ba lö nisöndragu ya''ia.', '["Sin 119:55; Yes 26:9","Yoh 20:13","Faigi 2:7"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 3, 'No fakhamö khögu zanaro andrö, sanörö-nöröi ewali ba mbanua, ba umane: "Somasi dödögu andrö, hadia no fakhamö ami?"[2]', '["Sin 119:55; Yes 26:9","Yoh 20:13","Faigi 2:7"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 4, 'Ba ha si''aikö utalu''i ira, ba hiza ia, somasi dödögu andrö. Ba ura''u ia ba lö uböhöli, balazi no u''ohe yomo khö ninagu, ba ba mbate''e zadono ya''odo.', '["Sin 119:55; Yes 26:9","Yoh 20:13","Faigi 2:7"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 5, 'Ube''e ba hölu ami, ya''ami ono alawe, banua Yeruzalema, nago ba böhö si alawe ba mbenua ube''e hölu: "Böi mikeani wa''omasi andrö, böi misusugi, mibe''e balazi ia."[3]', '["Sin 119:55; Yes 26:9","Yoh 20:13","Faigi 2:7"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 6, 'Hadia da''ö moroi si tou ba mbenua si mane boto zimbo, si fao hua emuri ba hua gumöyö, ba hadia ia na zamohua khö zolafo?[4]', '["Sin 45:9"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 7, 'Heahea Zelomo da''ö! Önö ngafulu niha zamasui ya''ia, sabölö Ndraono Gizeraeli.', '["Sin 45:9"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 8, 'Dozi ira, ba lö aefa-aefa danga ba zi''öli, si no to''ölö ba wasöndrata ira, sara-sara zi''öli ba mböbö löwi-löwira, ba gameta''uö andrö ba zi bongi.', '["Sin 45:9"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 9, 'No ifalau''ö khönia heahea razo Selomo, eu moroi ba hili Libano.', '["Sin 45:9"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 10, 'Döladölania, ba firö ibe''e, ba taralinia, ba ana''a, ba dadaomania, ba ungu, ba bakha, ba kaso.', '["Sin 45:9"]', NULL),
  (3476250, 'OT', 'Sinunö Sebua', 3, 11, 'Mi''ae tou, ya''ami ono alawe banua Ziona, mifemanga hörömi wamaigi razo Selomo ba takula bunga andrö, nibe''e ninania takulania, ba luo wangowalunia, ba luo wa''omuso dödönia andrö.', '["Sin 45:9"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 1, 'Si sökhi sa ndra''ugö, ya''ugö ono alawe, si fahuwu khögu; si sökhi sa ndra''ugö: höröu, ba no hörö marafadi, moroi barö mbalu-balu andrö. Bumö andrö, ba no hulö zi sambawa nambi, si no mörö ba gahe hili Gileadi.[1]', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 2, 'Ifömö andrö, ba no hulö zi sambawa biri-biri, si bohou muguti bu, ba si möi miyaŵa moroi ba gamondria; si no dozi abeto si faero, ba zi lö si lö mo''ono, sambua lö''ö.', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 3, 'Bewemö andrö, ba no hulö zinali kirimisi, ba no omasiö mbawamö. Bo''ömö, ba no hulö zi tamba-tambai mbua dalimo, moroi barö mbalu-balu andrö khöu.', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 4, 'Bagimö, ba no si hulö malige andrö khö Dawido, nilau nahia wangöna. Hönö nisaitagö khönia dange, baluse zabölö andrö fefu.', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 5, 'Susumö andrö, ba no hulö zi dua rozi ono nago, ono nago si faero, sangalui göra ba zi so ladari mböhö.', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 6, 'Irege okafu zino, ba irege taya lumö, ba möido ba hili emuri ba ba hili-hili gumöyö.', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 7, 'Sageu ya''ugö, ba no si sökhi manö, ya''ugö ono alawe si fahuwu khögu, lö hadia ia zi sala, ba mbotou.[2]', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 8, 'Tabu moroi ba hili Libano, ya''ugö ono nihalö, tabu awögu moroi ba hili Libano! Faigi mitou, moroi ba zuzu Gamana, moroi ba zuzu Zeniri ba moroi ba zuzu Heremono, moroi ba nahia zingo, moroi ba hili harimo.', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 9, 'No taya gera-eragu öbe''e, ya''ugö akhigu ono alawe, ono nihalö; no taya gera-eragu öbe''e, me no öfaigido, si ha samuza, ba me no u''ila rate side-ide andrö, si ha sara, ba nayamö andrö ba mbagiu.', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476251, 'OT', 'Sinunö Sebua', 4, 10, 'Ha lö ami wa''omasiu andrö, ya''ugö akhigu ono alawe, ono nihalö! No aröu tohude wa''omasiu andrö, moroi ba nagu, ba fa''amohua dalu-dalu andrö khöu, nigule''ö, moroi ba zamohua bö''ö fefu!', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 11, 'Ŵe ŵani zowöi ba mbeweu, ya''ugö ono nihalö, ŵe ŵani ba susu zi so ba lelamö, ba fa''amohua nukhamö, ba no timba wa''amohua ba hili Libano.[3]', '["Faigi 1:13; 6:4","Efes 5:27","Hos 6:11"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 12, 'Kabu si no mukusi bawa göli nakhigu ono alawe, ono nihalö, ba ba''a si no mukusi, ba umbu si no mufotandro.[4]', '["Yes 27:3; 58:11","Yoh 7:38","Yoh 15:5"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 13, 'Lewiömö, ba no timba kabu dalimo, si so bua sami sibai, no timba mbowo khorema, awö narawasu,', '["Yes 27:3; 58:11","Yoh 7:38","Yoh 15:5"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 14, 'ba narawasu ba kukuma ba daringu ba kuli mani ba hadia ia ngawalö döla gumöyö ba emuri ba göna farasi ba hadia ia ngawalö zamohua, fondrege zi sökhi.', '["Yes 27:3; 58:11","Yoh 7:38","Yoh 15:5"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 15, 'Umbu ba kabu ndra''ugö, umbu soluaha ba elea so''ulu ba hili Libano.[5]', '["Yes 27:3; 58:11","Yoh 7:38","Yoh 15:5"]', NULL),
  (3476251, 'OT', 'Sinunö Sebua', 4, 16, 'Faoso otarö, labu salata, törö kabu andrö khögu, ena''ö muzawili wa''amohua rembaremba andrö khönia. Ya möi ba kabunia zomasi ndra''o, ba yamu''a mbua geu andrö sami sibai.[6]', '["Yes 27:3; 58:11","Yoh 7:38","Yoh 15:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 1, 'No möido ba kabu khögu, ya''ugö akhigu, nihagu; no uteu emuri andrö khögu, awö ngawalö rembaremba khögu, no u''a gawa''awa andrö khögu, fabaya ösinia ŵe ŵani, ba no ubadu nagu, fabaya susu andrö khögu. Milau manga, ya''ami si fahuwu khögu, ba mibadu zi so andrö, hana na mabu ami, ya''ami somasi ndra''odo![1]', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 2, 'Si mörö ndra''o, ba tödögu, ba lö mörö. Fondrondrongo, ibököbökö lagö mbawandruhö somasi ndra''o! Bokai khögu, ya''ugö akhigu ono alawe, si fahuwu khögu, marafadigu, ya''ugö sohau-hau andrö, khögu! Oi namo sa''ae högögu, bugu, ba mowöi namo ba zi bongi.[2]', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 3, '[Ba umane:] No uheta mbarugu, hadia ufuli u''obaru? Ba no usasai gahegu, hadia, ufuli uta''unöi?[3]', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 4, 'Ba i''oro''ö dangania, ba humulu dödögu khönia.', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 5, 'Ba maoso ndra''o, ba wamokai khö zomasi ndra''odo, ba tangagu, ba mowöi emuri, göna ba ndranga lazi emuri sahele ba duturugu.', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 6, 'Ba ubokai khö zomasi ndra''odo, ba no iheta ia somasi ndra''o, no taya. Ba no ambö nosogu mege, me muhede ia. Ba u''alu-alui ia, ba lö usöndra; mu''aodo khönia, ba lö itema ligu.[4]', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 7, 'Ba la''ilado sanaro andrö, sanörö-nöröi ewali, ba labözi-bözido, mesokho ndra''o labe''e; balu-balu mbawagu, ba lahalö sanaro ba dete göli kara.', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 8, 'Ube''e ba hölu ami, ya''ami ono alawe, banua Yeruzalema: Na falukha ami zomasi ndra''o, ba hadia ni''ombakha''ömi khönia? — wa no mofökhö ndra''o fa''omasi![5]', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 9, 'Hadia wa''atohude zomasi ndra''ugö moroi ba zomasi mbö''ö, ya''ugö fondrege zi sökhi ndra alawe? Hadia wa''asökhi zomasi ndra''ugö, moroi ba zomasi mbö''ö, wa ömanö wame''e ba hölu ya''aga?', '["Amaed 9:5; Fam 3:20","Mat 25:5","Fam 16:15","Mikh 3:4; Yoh 7:33,34","Faigi 2:5"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 10, 'Somasi ndra''o ba no safusi sibai ba no soyo''oyo, no yaŵa zi 10.000 [ndra matua bö''ö].[6]', '["Sin 45:3","Luk 4:22"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 11, 'Högönia, ba no timba mbalaki sa''usö, ba bunia, ba no hulö mbulu nohi sadada, no aitö, si mane bu gaga.', '["Sin 45:3","Luk 4:22"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 12, 'Hörönia, ba no hulö marafadi ba mbewe mbombo, si mondri ba zusu, ba zi no fahöna.', '["Sin 45:3","Luk 4:22"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 13, 'Bo''önia, ba no amaedola gowoto rembaremba, nitanö famasa, ba bewenia, ba no timba [mbunga] ladari mböhö, ba zahele emuri.[7]', '["Sin 45:3","Luk 4:22"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 14, 'Ba tangania, ba no hulö gana''a ni''owuloi''ö, nifosinga feremata sembaka, ba botonia, ba no nekhe-nekhe ifö guaza, nifobalu-balu feremata nila.', '["Sin 45:3","Luk 4:22"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 15, 'Ba fahania, ba no timba daru nahe maremara, nifotoyo ahe ana''a sa''usö; famaigida ya''ia, ba no hulö hili Libano, nituyu, si mane töla geresi.', '["Sin 45:3","Luk 4:22"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 16, 'Araronia, ba no ha sambalö fa''ami, ba sageu ya''ia, ba ha sambalö omasiö: Da''ö zomasi ndra''odo, ba da''ö zi fahuwu khögu, ya''ami ono alawe, banua Yeruzalema!', '["Sin 45:3","Luk 4:22"]', NULL),
  (3476252, 'OT', 'Sinunö Sebua', 5, 17, 'Heza isaŵa maö somasi ndra''ugö, ya''ugö fondrege zi sökhi ndra alawe? Heza möi zomasi ndra''ugö, ena''ö matolo''ö, ba wangalui ya''ia?', '["Sin 45:3","Luk 4:22"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 1, 'Somasi ndra''o, ba no möi mitou ba kabunia, ba gowoto rembaremba andrö, ba wangalui ni''a ba kabu, ba ba wogete bunga ladari mböhö.', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 2, 'Khö zomasi ndra''o ndra''odo, ba no khögu zomasi ndra''o andrö, sokubaloi biri-biri ba zi so ladari mböhö.[1]', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 3, 'Si sökhi ndra''ugö, ya''ugö si fahuwu khögu, no timba Dirisa, ba omasiö, si mane Yeruzalema, ba sata''u ita, timba zabölö, si möi fasuwö.[2]', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 4, 'Böi töngö ndra''o, ata''udo höröu! Bumö andrö, ba no hulö zi sambawa nambi, si mörö ba gahe hili Gileadi.[3]', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 5, 'Ifömö, andrö, ba no hulö zi sambawa zigelo mbiri-biri, si otarai mondri, si no fatutu abeto si faero, ba ba zi lö si lö ono.', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 6, 'Timba zi tamba-tambai mbua dalimo mbo''ömö, moroi barö mbalu-balu mbawa andrö.[4]', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 7, 'Önö ngafulu wo''omo razo, ba 80 ndrongania ba döi, ba ono alawe andrö, ba lö mutaha mu''erai.', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 8, 'Ba ha samösa marafadigu andrö, sohau-hau andrö, khögu, si ha sambu-sambua khö ninania, nituyu zadono ya''ia. La''ila ia ono alawe andrö, ba lafahowu''ö ia, ba he fo''omo razo ba he dongania ba döi, ba oi sanuno ya''ia.[5]', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 9, 'Ha niha zihaga moroi sa, hulö na no ahatö wa''atumbu luo, si sökhi, si mane baŵa, ba sohahau si mane luo, ba sata''u ita, timba zabölö, si möi fasuwö?', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 10, 'No möido ba kabu falo, ba wangomusoi''ö tödögu ba wa''amanöi zinanö andrö ba ndraso, ba ba wamaigi na no mobene nagu, ba na no mobowo dalimo.', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476253, 'OT', 'Sinunö Sebua', 6, 11, 'Lö u''ila hadia — no ifazaŵado ba gureta niwama fehulu dödögu andrö, ba gureta niwama sadölö tödö.[6]', '["Faigi 2:16","RazI 14:17; Sin 45:12","Faigi 4:1 b.t.","Faigi 4:3","Faigi 5:2","RazII 2:12"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 1, 'Fuli''ö, fuli''ö, Sulamiti, fuli''ö, fuli''ö, ena''ö ma''ila''ö! Hadia nifaigimi khö Zulamiti? Folaya ba Mahana''i andrö.[1]', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 2, 'Ha lö asökhi gaheu andrö, ba mbadagahe, ya''ugö ono zalaŵa! Fa''obu''u zolamö, ba no hulö naya ba mbagi, nilau danga duka;', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 3, 'ahetamö, ba no hulö mako sebua, sowulo, ba zi lö ambö agu nifaruka samohua, ba talumö, ba no timba zi samba lauru fakhe, nifaduwa tou, ba nifasui bunga ladari mböhö;', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 4, 'ba no hulö nono nago zusumö andrö, hulö nono nago si faero.[2]', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 5, 'Ba bagimö, ba no amaedola malige ifö guaza; hörömö, ba no timba mbaŵa nidanö ba Hesibona, ba zinga mbawa göli Mbatarabi; ba ikhumö, ba no hulö malige andrö ba hili Libano, si otahögö Damaseko.', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 6, 'Ba högömö, ba no fakhili-khili ba hili Garemeli, ba bumö, ba högö yaŵa, ba no timba ungu, — no möi fesu razo mbu andrö!', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 7, 'Ha lö asökhi ndra''ugö ba ha lö omasiö, ya''ugö fa''omasi, ba wa''owua-wua dödö andrö!', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 8, 'Botomö andrö, ba no hulö döla khorema, ba no amaedola ngamohi mbua zusumö.', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 9, 'Ba umane dödögu: Damanöido ba döla khorema andrö, ba utuyu hakhinia. Ena''ö na no timba ngamohi mbua nagu zusumö andrö, ba ena''ö na timba hua ma''ufa hua nikhumö andrö,', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 10, 'ba ena''ö na timba wondrege zi sökhi nagu gararomö, agu sadölö ahele ba dölö-tölö zomasi ndra''o, na no itörö mbewe ba ifö.', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 11, 'Khö zomasi ndra''o ndra''odo, ba no khögu humulu dödönia.[3]', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 12, 'Tabu, ya''ugö somasi ndra''o, möi ita baero ba mbenua, ba ba halama mörö ita,', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 13, 'ba tahulö wongi ba kabu nagu, ba tafaigi, na no mobene nagu ba na no aboto mbowo, ba na no mobowo dalimo; ba da''ö dania ufa''ele''ö khöu wa''omasigu ndra''ugö.', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476254, 'OT', 'Sinunö Sebua', 7, 14, 'Amohua mbua dudayi, ba no so ba gahe zagö khöda ngawalö mbua geu omasiö; si bohou ba si no ara no ube''e yaŵa khöu, ya''ugö somasi ndra''o.[4]', '["MozI 32:1,2; Nga''ötI 22:9","Faigi 4:5","Faigi 2:16; 6:2","MozI 30:14"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 1, 'Ena''ö na hulö dalifusö ndra''ugö khögu, talifusö si no so ba mbagi zusu ninagu mege! Na falukhado khöu baero mbanua, ba fa''ago bawa ndra''o khöu, ba lö''ö sa lategu ndra''odo.', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 2, 'Ba ufasao''ö, u''ohe''ö ba nomo ninagu, ba öfahaödo ena''ö. Ba ube''e öu nagu nifaruka samohua, awö nidanö mbua dalimo khögu.', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 3, 'Yamutaya högögu tangania kabera ba yamu''omösido kambölönia.', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 4, 'Ube''e ba hölu ami, ya''ami ono alawe, banua Yeruzalema: böi mikeani wa''omasi andrö, böi misusugi, mibe''e balazi ia.[1]', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 5, 'Ha niha da''ö, si otarai moroi si tou andrö mbenua, sanundreheni ya''ia ba da''io zomasi ia? Ba mbörö ma''ufa mege ususugi ndra''ugö; ba da''ö mege i''adonogö ndra''ugö inau, safökhö khönia, ba da''ö i''adonogö''ö si asogö ya''ugö.', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 6, 'Fatöfa ndra''o ba gamaudu dödöu, amaedola laeduru, si so tandro, ba ba da''iomö. Me no timba wa''abölö wa''amate wa''abölö wa''omasi andrö, ba fehulu dödö andrö, ba no aro, timba wa''aro mbanua tou; fehölania, ba no fehola galitö, hola-hola khö Yehowa![2]', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 7, 'He idanö sebua, ba tebai ibe''e mate wa''omasi andrö, ba tebai inönöi ia hohou. Ba he na so ena''ö zame''e böli wa''omasi andrö ana''ania fefu, ba la''igi''igi''ö manö ia ena''ö.[3]', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 8, 'So khöda nakhi, ono alawe, si lö fosu na. He tawisa khö nakhida andrö, na so zanofu ya''ia dania?', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 9, 'Na no öli kara ia, ba tafa''anö ba detenia mba''a-ba''a firö; ba na bawandruhö ia, ba taba''a ia fafa eresi.', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 10, 'Öli kara ndra''odo, ba no timba malige wosugu; ba no tobali si no falukha fa''ohahau dödö ndra''odo, wamaiginia ya''o.[4]', '["Faigi 2:7","Yes 49:16; Yer 22:24","KorI 13","Faigi 6:12"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 11, 'So kabu nagu khö Zelomo, ba Mba''ali Hamono; ba no ibe''e ba danga zanaro kabu nagu andrö: 1.000 rufia zamösa labe''e böli mbua nagu ihuku khöra.[5]', '["Yes 5:1 b.t.; Mat 21:33 b.t.","Faigi 2:17"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 12, 'Ba ba kabu nagu khögu andrö, ba no balazi ndra''o. Si hönö andrö, ba khöu, ya''ugö Selomo, ba 200 ba zanaro buania!', '["Yes 5:1 b.t.; Mat 21:33 b.t.","Faigi 2:17"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 13, 'Lafondrondrongo limö, ya''ugö si so nahia ba kabu: Farongogö ia khögu!', '["Yes 5:1 b.t.; Mat 21:33 b.t.","Faigi 2:17"]', NULL),
  (3476255, 'OT', 'Sinunö Sebua', 8, 14, 'Oloi, ya''ugö somasi ndra''o, ya hulö nago ndra''ugö, ya hulö nono mböhö, ba hili rembaremba andrö![6]', '["Yes 5:1 b.t.; Mat 21:33 b.t.","Faigi 2:17"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 1, 'Fama''ele''ö andrö khö Yesaya, ono Gamosi, nifa''ele''ö khönia, me luo razo Yuda Usia ba Yatamo ba Ahasi ba Hisikia, ba nöri Yuda andrö ba ba Yeruzalema.', '[]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 2, 'Fondrondrongo, ya''ugö banua si yaŵa! Be''e mbörö dalingau, ya''ugö tanö! muhede Yehowa. No urorogö ndraono, no u''e''ebua, ba no la''erogö ndra''odo.', '["Sin 78:8; Faigi 57:3","Yer 2:30","MozV 28:51; Nga''ötII 28","MozI 19:24; Rom 9:29"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 3, 'Öröbao, ba i''ila zokhö ya''ia ba kalide, ba i''ila naha gönia, khö zokhö ya''ia andrö. Ba lö la''ila ndra''odo Iraono Gizeraeli, si lö tödö mbanuagu andrö.', '["Sin 78:8; Faigi 57:3","Yer 2:30","MozV 28:51; Nga''ötII 28","MozI 19:24; Rom 9:29"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 4, 'Alai ndra''o soi samazökhi horö andrö, sonoro olalöŵa! Niha si no tanömö zamazökhi horö, iraono solau si tefuyu. No laröi Yehowa, no latandraŵaisi Ni''amoni''ö andrö, ba Ndraono Gizeraeli, no la''erogö.[1]', '["Sin 78:8; Faigi 57:3","Yer 2:30","MozV 28:51; Nga''ötII 28","MozI 19:24; Rom 9:29"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 5, 'Hana wa latohugö wamözi ya''ami? Mitohugö sa atö wa''afabali andrö. No falawu fökhö högö ba no erege sibai dödö ma''asambua.[2]', '["Sin 78:8; Faigi 57:3","Yer 2:30","MozV 28:51; Nga''ötII 28","MozI 19:24; Rom 9:29"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 6, 'I''otarai duturu kahe, numalö yaŵa ba högö, ba lö si lö fökhö khönia, ha sambalö sokho ba mbawa zi''öli ba selezitö ba si bohou mesokho, si lö mufera''ö ba si lö mu''olohuni ba si lö mu''okafui fanikha.', '["Sin 78:8; Faigi 57:3","Yer 2:30","MozV 28:51; Nga''ötII 28","MozI 19:24; Rom 9:29"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 7, 'Tanö si mate danömi andrö, ba banua khömi, ba no i''a alitö. Bua danö khömi, ba no niha bö''ö zi manga, ba samaigi ami. Tanö si mate danö, si mane nifakiko niha bo''ö.[3]', '["Sin 78:8; Faigi 57:3","Yer 2:30","MozV 28:51; Nga''ötII 28","MozI 19:24; Rom 9:29"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 8, 'Ba si tosai ono Ziona alawe andrö, ba no hulö nose ba kabu nagu, hulö ni''otete waöhö, naha wemörö, ba kabu lawogalö, si mane banua nifa''u''u nemali.', '["Sin 78:8; Faigi 57:3","Yer 2:30","MozV 28:51; Nga''ötII 28","MozI 19:24; Rom 9:29"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 9, 'Ba na lö nisaigö Yehowa ngahönö andrö khöda gamogamo mena''ö, ba no tobali si mane Sodoma ita ba no fagölö-gölö ita ba Gomora andrö![4]', '["Sin 78:8; Faigi 57:3","Yer 2:30","MozV 28:51; Nga''ötII 28","MozI 19:24; Rom 9:29"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 10, 'Mifondrondrongo li Yehowa, ya''ami sanguhuku andrö ba Zodoma! Ya''ami, banua Gomora andrö, mifondrondrongo goroisa Lowalangida!', '["Sin 50:8; Amaed 15:8; Faigi 66:3; Yer 6:20; Amos 5:22","Amaed 1:28; Yer 14:12; Mikh 3:4"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 11, 'Hadia wa mi''oya''ö khögu zumange andrö? iŵa''ö Yehowa. No aföli ndra''odo zumange nitunu andrö, biri-biri si matua, ba tawö nibula andrö, ba lö omasido ndro nono zaŵi andrö ba do nono mbiri-biri ba do zi matua mbiri-biri andrö.[5]', '["Sin 50:8; Amaed 15:8; Faigi 66:3; Yer 6:20; Amos 5:22","Amaed 1:28; Yer 14:12; Mikh 3:4"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 12, 'No so ami, ba wangondrasi ya''odo, ba ha niha zanguma''ö khömi wanguhundra olayama andrö khögu?', '["Sin 50:8; Amaed 15:8; Faigi 66:3; Yer 6:20; Amos 5:22","Amaed 1:28; Yer 14:12; Mikh 3:4"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 13, 'Böi sa''ae mi''ohe zumange faya. Ogoro ndra''odo zumange nitunu andrö khömi. Tesa''a andrö ba sabato ba fogaoni ba gowuloa andrö, ba te khögu: si lö atulö, ba no baŵa ni''amoni''ö!', '["Sin 50:8; Amaed 15:8; Faigi 66:3; Yer 6:20; Amos 5:22","Amaed 1:28; Yer 14:12; Mikh 3:4"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 14, 'Tesa''a andrö khömi ba owasa nihonogöi andrö, ba lö edönado; no tobali noro khögu, atagedo sa''ae wolohe ya''ia.', '["Sin 50:8; Amaed 15:8; Faigi 66:3; Yer 6:20; Amos 5:22","Amaed 1:28; Yer 14:12; Mikh 3:4"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 15, 'Ba na mi''oro''ö dangami, ba ubalugö hörögu khömi, ba he mihöna wangandrö, ba lö ufondrondrongo khömi; oi do sa''ae dangami andrö.[6]', '["Sin 50:8; Amaed 15:8; Faigi 66:3; Yer 6:20; Amos 5:22","Amaed 1:28; Yer 14:12; Mikh 3:4"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 16, 'Misasai ami; mihaogö ami! Miheta mbua-bua si lö sökhi andrö khömi, fa böi u''ila sa''ae. Mibato wamazökhi si lö sökhi![7]', '["Sin 34:15; 37:27; Amos 5:15; Rom 12:9; FetI 3:11","Sin 51:9","MozV 28:2 b.t.","MozIII 20:14 b.t.; MozV 28:15 b.t."]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 17, 'Mifamaha ami ba wolau si sökhi? Migohi zatulö! Mi''oroma''ö lala ba zamakao awönia. Mi''ohe ba lala huhuo zi lö ama, si lö ina! Mifatunö huhuo lakha mbanua!', '["Sin 34:15; 37:27; Amos 5:15; Rom 12:9; FetI 3:11","Sin 51:9","MozV 28:2 b.t.","MozIII 20:14 b.t.; MozV 28:15 b.t."]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 18, 'Mitabu! iŵa''ö Yehowa, datalau fa''era! He no hulö gasumbo wa''oyo horömi, ba hulö muko safusi dania; ba he no hulö mbaru luo wa''oyo, ba hulö mbu mbiri-biri dania.[8]', '["Sin 34:15; 37:27; Amos 5:15; Rom 12:9; FetI 3:11","Sin 51:9","MozV 28:2 b.t.","MozIII 20:14 b.t.; MozV 28:15 b.t."]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 19, 'Na sedöna ami ba na solo''ö, ba mi''a zi sökhi ba danö.[9]', '["Sin 34:15; 37:27; Amos 5:15; Rom 12:9; FetI 3:11","Sin 51:9","MozV 28:2 b.t.","MozIII 20:14 b.t.; MozV 28:15 b.t."]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 20, 'Ba na te khömi ba na fabali ami, ba ö mbawa zi''öli ami dania; noa sa Yehowa zanguma''ö.[10]', '["Sin 34:15; 37:27; Amos 5:15; Rom 12:9; FetI 3:11","Sin 51:9","MozV 28:2 b.t.","MozIII 20:14 b.t.; MozV 28:15 b.t."]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 21, 'Alai wa''atobali sohorö mbanua andrö, si lö faröi mege! No fahöna khönia huku si sökhi mege, nahia huku satulö ia föna, ba iada''e, ba no nahia zange''e-nge''e.', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 22, 'Firömi andrö, ba no tobali akhozila, ba agu khömi, ba no faruka idanö.[11]', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 23, 'Salaŵami andrö, ba no faröi ba no awö zanagö-nagö. Dozi ira, ba manga gana''a ba la''alui mböli gölö; lö la''ohe ba lala huhuo zi lö ama, si lö ina, ba lö latema huhuo lakha mbanua.[12]', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 24, 'Da''ö mbörö, wa imane So''aya, Yehowa ngahönö andrö, sabölö ba Ndraono Gizeraeli andrö: Ha! urara dödögu ba zi fa''udu khögu andrö ba ulau mbalögu ba zi fatiu tödö khögu![13]', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 25, 'Ba ubaya ndra''ugö, uhaogö gakhozila andrö khöu, amaedola nilau idanö nawu, ba simo andrö khöu, ba uhori.[14]', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 26, 'Ba ufuli ufataro zanguhuku andrö khöu, si mane föna, ba samatunö huhuo andrö, si mane ba mböröta. Ba awena dania labe''e töimö mbanua satulö, banua si lö faröi.', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 27, 'Lala sadölö dania wangorifi Ziona andrö, ba fangorifi zangawuli andrö khönia, ba huku satulö.', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 28, 'Ba si göna famakiko zolalö andrö, fabaya samazökhi horö; ba sangerogö Yehowa andrö, ba nihori.[15]', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 29, 'Saila sa ira dania ba manawa andrö, somasi ami, ba afusi mbawami wa''aila ba kabu andrö, somasi ami.', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 30, 'Me hulö manawa saleu bulu ami dania, ba hulö kabu si lö idanö.', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476256, 'OT', 'Yesaya', 1, 31, 'Ba sabölö andrö, ba tobali rabo, ba nifazökhi dangania andrö, ba tobali bo galitö, ba faoma akhozi ira si lö samunu alitö.[16]', '["Hez 22:18","MozII 22:22; Yer 5:28","MozV 28:63","Mal 3:3","Sin 1:6; 92:10; 104:35","Faigi 33:11"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 1, 'Taroma li andrö, nifarongogö khö Yesaya andrö, ono Gamosi, ba nöri Yuda andrö ba ba Yeruzalema.', '["Mikh 4:1","Sin 50:2; 110:2; Luk 24:47; Yoh 4:22","Yoel 3:10","Yoh 8:12"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 2, 'Tobali, na luo safuria andrö, ba aro hili andrö, si so osali Yehowa andrö, fondrege zalaŵa hili, yaŵa hihihili andrö fefu, ba lahurufai ia niha baero fefu.[1]', '["Mikh 4:1","Sin 50:2; 110:2; Luk 24:47; Yoh 4:22","Yoel 3:10","Yoh 8:12"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 3, 'Ba lasaŵa soi niha, ha wa''oya, lamane: "Talabu, möi ita misi yaŵa ba hili Yehowa andrö, ba gosali Lowalangi Yakobo, ena''ö ifahaö ita ba lala andrö khönia, ena''ö tatörö nifatörönia andrö; moroi ba Ziona sa i''otarai oroisa andrö, ba taroma li Lowalangi andrö, ba moroi ba Yeruzalema."[2]', '["Mikh 4:1","Sin 50:2; 110:2; Luk 24:47; Yoh 4:22","Yoel 3:10","Yoh 8:12"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 4, 'Ba ya''ia zanguma''ö lala ba niha baero, oya soi ihuku, ba tobali labali''ö faku zi''ölira ba labali''ö sabi nagu dohora. Sambua lö soi sa''ae sanuyu si''öli, ba wanuwö si sambua; lö''ö sa''ae lafamaha ira ba wanuwö.[3]', '["Mikh 4:1","Sin 50:2; 110:2; Luk 24:47; Yoh 4:22","Yoel 3:10","Yoh 8:12"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 5, 'Talabu, ya''ami ma''uwu Yakobo! Tatörö haga andrö khö Yehowa![4]', '["Mikh 4:1","Sin 50:2; 110:2; Luk 24:47; Yoh 4:22","Yoel 3:10","Yoh 8:12"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 6, 'Noa sa ötibo''ö mbanuau, ma''uwu Yakobo andrö. Noa sa fahöna khöra waetasa, soroi ba gatumbukha luo, ba si fakelemu, si inane ba Ndrawa Wilisiti, ba no fara''u tanga ira ba niha bö''ö.[5]', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476257, 'OT', 'Yesaya', 2, 7, 'No fahöna ba danöra wirö ba ana''a; lö mutaha mutulo girö-giröra; anönö danöra kudo; ba kuretara, ba no si tebai ta''erai.[6]', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 8, 'Ba no fahöna ba danöra nadu, mangalulu ira ba niwöwöi dangara, ba nifazökhi duturura.[7]', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 9, 'Ba da''ö ifaöndrö ia ono mbanua, ba i''ide-ide''ö ia salaŵa, ba ya''ugö, ba tebai ö''efa''ö khöra [lalöra andrö].', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 10, 'Ae ba dögi narö gara ba bini''ö ndra''ugö, balugö''ö gawu-gawu, ba gameta''uö andrö khö Yehowa ba ba wa''abölö lakhöminia andrö.[8]', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 11, 'Tefaöndrö dania wayaŵasa niha, ba tehöndrögö hokha ndra matua, ba ha Yehowa zalaŵa, na luo da''ö.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 12, 'Irugi sa dania baŵa Yehowa ngahönö, itörö fefu zi so hokha ba salaŵa fefu ba si fayaŵa fefu, ba wangöhöndrögö ya''ira.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 13, 'Itörö fefu geresi salaŵa töla ba sebua hogu ba hili Libano ba Manawa Mbazana, fefu.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 14, 'Ba hili sebua fefu, awö hili-hili salaŵa.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 15, 'Ba itörö fefu inalige salaŵa ba öli kara saro fefu.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 16, 'Ba owo soloyoloyo ba Darisi fefu, awö fefu zomasi niha wamaigi ya''ia.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 17, 'Ba tefaöndrö hokha niha ba tehöndrögö wayaŵasa ndra matua, ba ha Yehowa zalaŵa, na luo da''ö.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 18, 'Ba adu andrö, ba nihori fefu.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 19, 'Ba möi dania niha ba dögi narö gara ba ba dögi narö hili, ba gameta''uö andrö khö Yehowa ba ba wa''abölö lakhöminia andrö, na maoso ia, ba wameta''u ösi guli danö.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 20, 'Na luo da''ö, ba lahalö nadu firö andrö, awö nadu ana''a, niha, nifazökhira, ba wangalulu khönia, ba latibo''ö ba dögi de''u ba ba dögi mbögi.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 21, 'Ba we''amöi ba dögi narö hili ba ba zi faefa gara, ba gameta''uö andrö khö Yehowa ba ba wa''abölö lakhöminia andrö, na maoso ia, ba wameta''u ösi guli danö.', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476257, 'OT', 'Yesaya', 2, 22, 'Ba miböhöli niha, si so noso ba nikhu; nadia sa''ae tabe''e töira?[9]', '["MozV 18:14","Faigi 31:1; Sin 33,17; 147:10","Sin 115:4","Luk 23:30","Yob 27:3"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 1, 'Hiza sa, iheta So''aya, Yehowa ngahönö, fefu ngawalö we''e-we''e ba Yeruzalema ba ba Ndraono Yuda; fefu we''e-we''e ba mbalazo ba fefu we''e-we''e ba nidanö.[1]', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 2, 'Sabölö ba si möi fasuwö ba sanguhuku ba sama''ele''ö ba sangi''ila ba satua.', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 3, 'Kumandra ba si so töi ba anofula ba tuka ba sonekhe ba waetasa.', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 4, 'Ba ube''e salaŵara nono matua [iŵa''ö So''aya] ba iraono zamatörö ya''ira.[2]', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 5, 'Ba famakao ba mbanua; oi zara fa''udu ira ba nawöra: afaito nono matua ba zatua ba si numana ba zalaŵa.', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 6, 'Na so zondra''u talifusönia, ono namania [wanguma''ö]: "Si so baru ndra''ugö, iagö salaŵama; ya so barö mbawau gadudula andre;"', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 7, 'ba imane dania na luo da''ö: "Te khögu wodalu-daluni sesokho; yomo khögu, ba lö balazo ba lö baru, — böi mibe''e salaŵa mbanua ndra''odo."', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 8, 'Sadudu sa Yeruzalema ba si tegaölö tou Ndraono Yuda, me si fa''udu khö Yehowa wehedera ba folaura, safökhö famaigi khönia hörönia, hörö zalaŵa.', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 9, 'Bawara zama''ele''ö ya''ira, ba lafarongogö horöra, lö labini''ö si mane banua Zodoma. Alai ira! Khöra lalau zi lö sökhi.[3]', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 10, 'Miwa''ö ba zatulö tödö andrö, lö hadia ia!', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 11, 'La''a sa lua-lua wolaura andrö. Alai zebua horö andrö! itörö ia si lö sökhi; tesulöni sa khönia wolaunia andrö.', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 12, 'Alai mbanuagu andrö! Iraono zamakao ya''ira ba ira alawe zalaŵara. He ya''ami, banuagu! samaelungu zolohe ya''ami, ba no lafakuyu lala andrö, nitörömi ena''ö.', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 13, 'No so ba da''ö Yehowa, ba wamatunö huhuo; no maoso ia, ba wanguhuku soi niha.', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 14, 'I''ohe ba huku Yehowa zatua mbanuania, fabaya salaŵara: "Ya''ami sa si manga mbua ba kabu nagu andrö khögu! Baomo khömi so nirabu ba zi numana.[4]', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 15, 'Hadia khömi da''ö, wa mifufu mbanuagu andrö, wa mirasa zi numana?" Da''ö niŵa''ö Zo''aya, Yehowa ngahönö andrö.[5]', '["MozIII 26:26","Sanguhuk 10:16","MozI 13:13; 19:5","Faigi 5:1 b.t.","Amaed 22:22"]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 16, 'Ba imane na Yehowa: Me no mohokha nono Ziona alawe, me lafaöga mbagira, na latörö ba me lafakhölö ira, lö aila-aila, me hulö zanarinari manö, ba me lafariti naya ba gahe;', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 17, 'andrö batule galizuzu nono Ziona alawe ibe''e So''aya, ba iheta mbalu-balu zaila ira Yehowa.', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 18, 'Na luo da''ö, ba iheta Yehowa naya ba gahe, si sökhi sibai andrö, awö roto,', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 19, 'awö rai, awö walewale, awö göla,', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 20, 'awö zalendra andrö, awö mbala högö, awö ritiriti ba gahe, awö mböbö dalu, awö mbulibuli zamohua andrö,', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 21, 'awö hazima, awö laeduru,', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 22, 'awö naya ba nikhu, awö mbaru ba walöŵa, awö lembe, awö gabaya,', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 23, 'awö mbola, awö walu, awö muko si sökhi andrö, awö zalendra, awö mbalu-balu mbawa andrö.', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 24, 'Ba fangali zamohua andrö zaböu, ba fangali mböbö dalu si sökhi andrö zinali, ba fangali mbu nindrandra andrö wa''abatule, ba fangali gabaya sebua goni, ba fangali wa''asökhi mbawa laheto zakhozi.', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 25, 'Bawa zi''öli wamunu ndra matua khömi, ba sabölö khömi, ba ba wanuwö mate.', '[]', NULL),
  (3476258, 'OT', 'Yesaya', 3, 26, 'Ba mangarö-ngarö dania mbawa göli mbanua, ba abu dödö, ba dumadao ia ba danö, oi ahori fefu hadia ia.', '[]', NULL),
  (3476259, 'OT', 'Yesaya', 4, 1, 'Na luo da''ö, ba dafitu ndra alawe zondra''u ira matua si ha samösa, ba lamane: "Mataha mbalazoma ba mataha nukhama, ha töimö andrö be''e töima, heta khöma wa''aila andrö."', '["Faigi 11:1; Yer 23:5; 33:14 b.t.; Sakh 3:8; 6:12","Faigi 6:13","MozII 13:22"]', NULL),
  (3476259, 'OT', 'Yesaya', 4, 2, 'Na luo da''ö, ba tobali fa''amoadu ba fangebua döi ba ni''orifi andrö ba Ndraono Gizeraeli lewiö andrö khö Yehowa, ba fa''asalaŵa, awö lakhömi mbua danö andrö.[1]', '["Faigi 11:1; Yer 23:5; 33:14 b.t.; Sakh 3:8; 6:12","Faigi 6:13","MozII 13:22"]', NULL),
  (3476259, 'OT', 'Yesaya', 4, 3, 'Ba "ni''amoni''ö" dania labe''e töi zi tosai ba Ziona ba si lö ahori ba Yeruzalema; dozi nitanö ba zura ba Yeruzalema, ni''orifi.[2]', '["Faigi 11:1; Yer 23:5; 33:14 b.t.; Sakh 3:8; 6:12","Faigi 6:13","MozII 13:22"]', NULL),
  (3476259, 'OT', 'Yesaya', 4, 4, 'Na no isasai So''aya zi ra''i-ra''iö andrö ba ndra alawe Ziona ba na no ihanigö horö Yeruzalema, fange''enge''e andrö ba mbanua, na no ifatörö nangi fanguhuku andrö, awö nangi fangohori.', '["Faigi 11:1; Yer 23:5; 33:14 b.t.; Sakh 3:8; 6:12","Faigi 6:13","MozII 13:22"]', NULL),
  (3476259, 'OT', 'Yesaya', 4, 5, 'Ba ifatörö Yehowa ba naha niha fefu ba hili Ziona ba ba zowulo ira fefu lawuo, na maökhö, ba simbo, awö haga hola-hola galitö, ba zi bongi; tefobalu-balu sa''ae fefu zi so lakhömi.[3]', '["Faigi 11:1; Yer 23:5; 33:14 b.t.; Sakh 3:8; 6:12","Faigi 6:13","MozII 13:22"]', NULL),
  (3476259, 'OT', 'Yesaya', 4, 6, 'Ba so nose, ba''a-ba''a wa''auahu zino na ma''ökhö, ba saŵatö ba nöu, na mo''angi ba na moteu.', '["Faigi 11:1; Yer 23:5; 33:14 b.t.; Sakh 3:8; 6:12","Faigi 6:13","MozII 13:22"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 1, 'Ba damanunödo, udunö-dunö ni''omasi''ögu andrö, ulau zinunö zomasido andrö, wamatunö kabu nagu andrö khönia. Somasido andrö, ba no mokabu nagu yaŵa ba hili, ba zi sökhi tanö.[1]', '["Yer 2:21; Mat 21,33. b.t.","Sin 80:13"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 2, 'Ba ifaku ba itutuyu gara, ba itanö bakha ŵeŵe nagu, si sökhi bua. Ba dalu bakha ilau malige ba ikhao wolazi, ba ibazebaze''ö, ena''ö mowua bua nagu; ba i''owua mbua nagu ndru''u.', '["Yer 2:21; Mat 21,33. b.t.","Sin 80:13"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 3, 'Ba iya''e, ya''ami banua Yeruzalema ba ya''ami, motöi Iraono Yuda, mi''ohe ba lala huhuo khöma kabu nagu andrö khögu.', '["Yer 2:21; Mat 21,33. b.t.","Sin 80:13"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 4, 'Hadia na nilau mena''ö ba kabu nagu andrö khögu, si lö nilaugu na? Ba hana wa i''owua mbua nagu ndru''u, me udöna-döna zi ndruhu nagu:', '["Yer 2:21; Mat 21,33. b.t.","Sin 80:13"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 5, 'Ba da''u''ombakha''ö khömi, he uwisa ba kabu nagu andrö khögu: Udeha gölinia, ena''ö ö zökha ia, ba ududugö göli kara andrö khönia, ena''ö lahundra-hundra ia.[2]', '["Yer 2:21; Mat 21,33. b.t.","Sin 80:13"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 6, 'Tobali modu''u ube''e, fa böi sa''ae laguti ba fa böi lafaku mbörö; ya tumbu za''a-sa''a mao, awö lato. Ba utenaŵa göi lawuo, fa böi moteu khönia.', '["Yer 2:21; Mat 21,33. b.t.","Sin 80:13"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 7, 'Ba kabu nagu andrö khö Yehowa ngahöno, ba ya''ia ma''uwu Gizeraeli, ba no sinanö omasiö khönia Ndraono Yuda. Idöna-döna zadölö — ba hiza wange''e; idöna-döna wa''atulö — ba hiza wangarö-ngarö.', '["Yer 2:21; Mat 21,33. b.t.","Sin 80:13"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 8, 'Alai ami, sama''oli omo ba samadoro benua, irege lö naha sa''ae; irege tobali hatö ya''ami ba danö.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 9, 'No irongo tögi dalingagu niŵa''ö Yehowa ngahönö andrö, [imane]: Si ndruhu! Oya dania nidudugö omo; si lö niha dania zebua ba si sökhi.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 10, 'Ha sa samba lauru dania nösi mbua nagu ba zi fulu lauru tanöma, ba si sazo''e tanömö fakhe, ba ha samba lauru mbua.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 11, 'Alai zahulö maoso, ba wangalui göra tuo, ba sara mörö ba zi bongi, irege mabu agu!', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 12, 'Si so biola nitika side-ide ba biola nitika sebua ba faritia ba surune, ba wamadu-madu agu andrö. Ba lö ba dödöra wolau Yehowa andrö, ba nifazökhinia tangania, ba lö la''ila.[3]', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 13, 'Da''ö mbörö wa te''oloi''ö mbanuagu andrö, si lö mudöna-döna; solofo dania zalaŵara, ba soköliköli zato, ba wa''owökhi dödö.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 14, 'Andrö ifaboka mbawania banua tou; si tenga inötö wa''ebua mbawania, ena''ö numalö mitou lakhömira, awö zi fagua-gua andrö, awö zomuso tödö ba khöra.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 15, 'Ba tefaöndrö niha ba te''ide-ide''ö ndra matua, ba tehöndrögö hörö zi fayaŵa andrö.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 16, 'Ba si tedou wa''asalaŵa Yehowa ba wanguhuku, ba ni''amoni''ö Lowalangi ni''amoni''ö andrö, ba wa''atulö andrö.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 17, 'Ba möi ba ndru''u ba da''ö nono mbiri-biri, hulö ba mbenua; latöröi ba la''aga''aga ndru''u ba danö si no tekiko, satabö sinanö föna.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 18, 'Alai zanöbi khöra si lö atulö sinali sala andrö ba sanöbi horö tali zao!', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 19, 'Sanguma''ö: Yamuta''i-ta''i, yamu''aliogö wolau nilaunia, ena''ö ta''ila; ya alua dödö Ni''amoni''ö Ndraono Gizeraeli andrö, ya itörö, ena''ö oroma khöma.', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 20, 'Alai zamotöi si sökhi si lö sökhi ba samotöi si lö sökhi si sökhi, samali''ö haga sogömi-gömi ba samali''ö sogömi-gömi haga; same''e ami safeto ba same''e afeto sami!', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 21, 'Alai zatua-tua wamaigira ba si no onekhe wanguma''öra![4]', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 22, 'Alai zi no abölö wamadu agu; si lö ada''u-da''u, ba wamaruka si mabu ira!', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 23, 'Si oawögö si so horö, börö gana''a, nibe''e khöra, ba samalangögö si lö horö.[5]', '["Yob 21:12; Amos 6:5","Amaed 3:7","Amaed 17:15"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 24, 'Andrö, hulö si mane na i''a ndru''u alitö, si mane na ariri ndru''u soköli ba hola-hola galitö, si manö dania wa tobali oboula ŵa''ara, awö wa humombo mbowora, hulö gawu-gawu; me lö ba dödöra gamakhoita Yehowa ngahönö, ba me la''o''aya daroma li Ni''amoni''ö Ndraono Gizeraeli andrö.[6]', '["MozII 15:7","Faigi 10:4","Faigi 8:22"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 25, 'Andrö göi tesao wönu Yehowa ba mbanuania andrö, ba i''oro''ö dangania, ba wamözi ya''ira, fa muhisi hili, fa fahöna baolayama mboto zi mate, hulö zasao. Ba lö lai da''ö fefu, ba lö''ö na döhö wönunia, lö''ö na sa iböda dangania ni''oro''ö andrö.[7]', '["MozII 15:7","Faigi 10:4","Faigi 8:22"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 26, 'Ba itaru''ö dania dandra ba niha baero ba zaröu, idönisi ira moroi ba wondrege danö; ba hiza, lö arara, ba so ira, aösö ira.', '["MozII 15:7","Faigi 10:4","Faigi 8:22"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 27, 'Lö serege tödö ba khöra ba lö salau; lö si mörö, lö salau hörö; samösa lö satoto böbö talu ba lö saetu böbö mbadagahe.', '["MozII 15:7","Faigi 10:4","Faigi 8:22"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 28, 'Ono wana khöra, ba no mu''atarösi, ba no mukhai wanara fefu. Hulö gowe za''a kudora ba hulö dawuyu nangi gaölö guretara.', '["MozII 15:7","Faigi 10:4","Faigi 8:22"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 29, 'Na mundröndrö ira, ba hulö zingo; hulö nono zingo mundröndröndröndrö ira; dumele ira, ba lara''u zahulu ira ba la''ohe, lö sangorifi.', '["MozII 15:7","Faigi 10:4","Faigi 8:22"]', NULL),
  (3476260, 'OT', 'Yesaya', 5, 30, 'Ba na mu''ugu khöra [ba Ndraono Gizeraeli] na luo da''ö, hulö si mane fe''ugu-ugu nasi, ba lafaigi tou danö, ba hiza wa''ogömi-gömi sata''u ita, ba tobalu haga ba lawuo andrö khönia.[8]', '["MozII 15:7","Faigi 10:4","Faigi 8:22"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 1, 'Ba ndröfi wa''amate Usia andrö, razo, ba u''ila Zo''aya, sidadao ba dadaoma sebua, si no alaŵa: anönö gosali ahe mbarunia.[1]', '["RazII 15:1 b.t.; Yoh 12:41","Fam 4:8","Hez 10:4","MozI 16:13; 32:30; Sanguhuk 13:22","Hez 28:14","Yer 1:9; Dan 10:10"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 2, 'Serafi fönania, önö gafi zamösa. Dua mbalu-balu mbawa ba dua mbalu-balu gahe ba dua ba wehombo.', '["RazII 15:1 b.t.; Yoh 12:41","Fam 4:8","Hez 10:4","MozI 16:13; 32:30; Sanguhuk 13:22","Hez 28:14","Yer 1:9; Dan 10:10"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 3, 'Ba faoma lamane-mane we''ao khö nawöra: Ni''amoni''ö, ni''amoni''ö, ni''amoni''ö Yehowa ngahönö andrö; no anönö lakhöminia guli danö ma''asagörö![2]', '["RazII 15:1 b.t.; Yoh 12:41","Fam 4:8","Hez 10:4","MozI 16:13; 32:30; Sanguhuk 13:22","Hez 28:14","Yer 1:9; Dan 10:10"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 4, 'Ba mudögö latalata zilötö ba wa''ebua lira, ba we''ao andrö, ba afönu nomo simbo.[3]', '["RazII 15:1 b.t.; Yoh 12:41","Fam 4:8","Hez 10:4","MozI 16:13; 32:30; Sanguhuk 13:22","Hez 28:14","Yer 1:9; Dan 10:10"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 5, 'Ba umane: Alai ndra''o! tekiko ndra''o; me no niha si ra''i-ra''iö bewe ndra''odo ba me ba niha si ra''i-ra''iö bewe sodo; noa sa i''ila hörögu razo andrö, Yehowa ngahönö![4]', '["RazII 15:1 b.t.; Yoh 12:41","Fam 4:8","Hez 10:4","MozI 16:13; 32:30; Sanguhuk 13:22","Hez 28:14","Yer 1:9; Dan 10:10"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 6, 'Ba humombo zamösa Zerafi andrö, i''ondrasido, so ba dangania nono gara, ni''oyoni ba galitö, niforönia ba naha wame''e sumange.[5]', '["RazII 15:1 b.t.; Yoh 12:41","Fam 4:8","Hez 10:4","MozI 16:13; 32:30; Sanguhuk 13:22","Hez 28:14","Yer 1:9; Dan 10:10"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 7, 'Ba ifatöfa ba mbawagu ba imane; Me no fatöfa ba bawau da''e, ba no aheta golalöŵamö ba no mubu''a horöu.[6]', '["RazII 15:1 b.t.; Yoh 12:41","Fam 4:8","Hez 10:4","MozI 16:13; 32:30; Sanguhuk 13:22","Hez 28:14","Yer 1:9; Dan 10:10"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 8, 'Ba urongo li Zo''aya, imane: Ha niha nifatengegu, ha niha zi möi khöda? Ba umane: Ya''e ndra''o, fatenge ndra''o.', '["Mat 13:14, b.t.; HalZin 28:26,27; Rom 11:8","Yoh 12:40","Faigi 4:3"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 9, 'Ba imane khögu: Ae''e, ba ömane ba niha andrö: Mifondrondrongo tögi dalingami, ba böi ya aboto ha dödömi ba mitöngöni hörömi ba böi ya misöndra geluaha![7]', '["Mat 13:14, b.t.; HalZin 28:26,27; Rom 11:8","Yoh 12:40","Faigi 4:3"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 10, 'Abe''e''ö dödö niha andrö ba awe''e-we''e''ö dögi wisora ba fobalunö höröra, ena''ö tebai la''ila höröra, ba ena''ö tebai larongo tögi dalingara, fa böi aboto ba dödöra, fa böi lafalalini gera''arara ba fa böi lasöndra wangorifi.[8]', '["Mat 13:14, b.t.; HalZin 28:26,27; Rom 11:8","Yoh 12:40","Faigi 4:3"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 11, 'Ba umane: Ha wa''ara, So''aya? Ba imane khögu: Irege no adudu mbanua andrö, fa lö niha sa''ae, fa lö ösi nomo, ba irege no muhundra-hundra nowi, irege no modu''u.', '["Mat 13:14, b.t.; HalZin 28:26,27; Rom 11:8","Yoh 12:40","Faigi 4:3"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 12, 'Irege no ifa''ohe''ö ba zaröu niha andrö Yehowa ba irege no abölö wa lö niha ba danö.', '["Mat 13:14, b.t.; HalZin 28:26,27; Rom 11:8","Yoh 12:40","Faigi 4:3"]', NULL),
  (3476261, 'OT', 'Yesaya', 6, 13, 'Ba na toröi na ba danö zambua ni''ofulu, ba nihori zui da''ö; si mane awöni ba si mane manawa, si tosai tuhe, na la''obö — tanömö ni''amoni''ö duhe andrö.[9]', '["Mat 13:14, b.t.; HalZin 28:26,27; Rom 11:8","Yoh 12:40","Faigi 4:3"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 1, 'Me luo razo mado Yuda Gahasi andrö, ono Yotamo, ma''uwu Usia, ba so moroi si yaŵa Resino, razo Garamo ba Feka andrö, razo Ndraono Gizeraeli, lasaŵa Yeruzalema, ba wanuwö ya''ira. Ba tebai atu''a ira.[1]', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 2, 'Ba me te''ombakha''ö ba ma''uwu Dawido andrö: "No larugi mado Gefarayi Dawa Garamo, molombase ira ba da''ö," ba manizi-nizi bakha dödö mbanuania, si mane na ifaheu hogu geu ba gatua angi.', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 3, 'Ba imane Yehowa khö Yesaya: Ae faondragö Gahasi, ya''ugö ba onou Seari-Yasubi (Mangawuli zi tosai), ba mbalö lala hele ba mbaŵa nidanö tanö si yaŵa, ba lala ba mbenua zolokhoi muko.[2]', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 4, 'Ba ömane khönia: "Faigi-faigi ba honogö''ö; böi ata''ufi, ba böi abu dödöu ba mbalö dudunga andrö, si dua, sanimbonimbo andrö, lö lai wa no humola dödö Resino andrö, fabaya Dawa Garamo ba fabaya ono Remalia andrö!"', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 5, 'Me no mamagölö ira, Dawa Garamo andrö ba mado Geferayi ba ono Remalia andrö, ba wolau khöu si lö sökhi, me no lamane:', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 6, '"Da möi ita ba Ndraono Yuda, tafeta''u ira, atu''a ita ba mbanua tabe''e, ba tafataro razo nono Dabe''eli andrö."', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 7, 'Ba no imane So''aya, Yehowa: Lö fakhai ba lö alua!', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 8, 'Högö Garamo andrö sa, ba Damaseko, ba högö Ndramaseko, ba ya''ia Resino andrö, ba önö ngafulu a lima fakhe tö, i''otarai da''e, ba tedudugö nöri mado Geferayi andrö, fa tenga banaua sa''ae.[3]', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 9, 'Ba Samaria andrö, ba no högö mado Geferayi, ba ono Remalia andrö, ba högö Zamaria! Na lö faduhu dödömi, ba lö fangorifimi.[4]', '["RazII 16:5","RazII 18:17; 20:20","RazII 17:24","Nga''ötII 22:28"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476262, 'OT', 'Yesaya', 7, 10, 'Ba itohugö Yehowa, imane khö Gahasi:', '["Mikh 5:3; Mat 1:23; Luk 1:31","RazII 16:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 11, 'Andrö dandra khö Lowalangiu Yehowa, ma moroi si tou ba mbanua tou ba ma moroi yaŵa ba mbanua si yaŵa.', '["Mikh 5:3; Mat 1:23; Luk 1:31","RazII 16:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 12, 'Ba imane Ahasi: Lö u''andrö, lö utandraigö Yehowa.', '["Mikh 5:3; Mat 1:23; Luk 1:31","RazII 16:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 13, 'Ba imane [Yesaya]: Ba mifondrondrongo, ya''ami ma''uwu Dawido! Hadia, ambö na khömi, na mifakao niha, wa mifakao na göi Lowalangigu?', '["Mikh 5:3; Mat 1:23; Luk 1:31","RazII 16:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 14, 'Andrö So''aya zame''e tandra khömi: Hiza, manabina dania none alawe ba i''adonogö nono matua, ba ibe''e töinia Emanueli (awöda Lowalangi)[5]', '["Mikh 5:3; Mat 1:23; Luk 1:31","RazII 16:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 15, 'Susu si baku ba ŵe ŵani gönia, irege i''ila itimba zi lö sökhi ba ituyu zi sökhi.', '["Mikh 5:3; Mat 1:23; Luk 1:31","RazII 16:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 16, 'Lö''ö sa fakhamö isöndra wanimba si lö sökhi ba fanutuyu si sökhi ono andrö, ba no adudu mbanua, ni''ata''ufiu razo si darua andrö.[6]', '["Mikh 5:3; Mat 1:23; Luk 1:31","RazII 16:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 17, 'Ba ifatörö göi khöu mbaŵa Yehowa, khöu ba ba mbanuau andrö ba ba zoroiyomou fefu, si lö irai, götö wa no fabali mado Geferayi ba Ndraono Yuda, balazi razo Asiria.[7]', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 18, 'Na luo da''ö, ba ikaoni Yehowa gulo andrö ba luaha nidanö Miserayi, awö ŵani andrö ba danö Asiria.[8]', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 19, 'Ba so ira fefu, ba latugelai mbawa danö ba so''otalua gara ba songafu sa''a-sa''a mao ba benua awuyu fefu.', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 20, 'Ba na luo da''ö, ba itöwö So''aya mbu högö ba bu ba zaila ira fanöwö andrö niwawalö ba mbewe Oifarati, razo Asiria andrö; numalö gambi, ba ihori.', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 21, 'Na luo da''ö, ba sageu saŵi, si bohou ebua ba dua geu biri-biri zamösa.', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 22, 'Ba ba wa''oya nösi zusu, ba susu si baku gönia; dozi si tosai ba danö sa, ba susu si baku ba ŵe ŵani göra.', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 23, 'Na luo da''ö, ba asai''ö fefu naha si no hönö töla nagu, si 500 rufia moböli, ba tumbu za''a-sa''a mao khönia.', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 24, 'Fa ni''ohe fana fabaya ono wana, wanörö ya''ia; sagörö tanö sa''ae, ba sasai''ö ba mosa''a-sa''a mao.', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476262, 'OT', 'Yesaya', 7, 25, 'Ba ba hili fefu, nihalö nowi iada''e, ba lö''ö sa''ae möi niha, börö wa''ata''ura za''a-sa''a mao andrö ba sasai''ö no mege. La''ohe dania zaŵi ba da''ö, ba lahundra-hundra biri-biri.', '["Nga''ötII 28:20","RazII 18:13. b.t.; 19:9"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 1, 'Ba imane na Yehowa khögu: Halö khöu gara wanura sebolo ba sura yaŵa fanura soroma, ba wombaso: "Alio so gahulua, aösö worabu."', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 2, 'Ba fa''aso khögu zi so ba mbörö, si faduhu dödöda, Uria andrö, ere, ba Sakharia ono Yerebekhia.[1]', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 3, 'Ba möido khö wo''omo zama''ele''ö ba manabina ia ba tumbu khönia nono matua. Ba imane khögu Yehowa: Be''e töinia: "Alio so gahulua, aösö worabu."', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 4, 'Lö''ö sa fakhamö fa''ama nono andrö ba lö fakhamö fa''ina, ba te''ohe khö razo Asiria gana''a Ndramaseko andrö, awö nirabu ba Zamaria.[2]', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 5, 'Ba itohugö Yehowa, imane khögu:', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 6, 'Me no lö ba dödö mbanua andre nidanö andrö ba Ziloa, si lö abölö lawulawu ba me omasi ira Resino andrö ba ono Remalia,[3]', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 7, 'ba hiza, ba ifatörö khöra So''aya nidanö sebua, si no abölö, Oifarati andrö, Razo Asiria, awö wa''abölönia fefu. Inönöi dania ndraso molö mbewenia ibe''e.', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 8, 'Ba itörö danö mado Yuda, inönöi, irege falaŵa bagi, ibalugö afinia nibologö danö, ha wa''ebolo ia, ya''ugö Emanueli![4]', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 9, 'Ya aboto ba dödömi, ya''ami soi niha ba mifondrondrongo, ya''ami ba danö saröu. Mifa''anö ami, ba mi''anizi-nizi! [Uŵa''ö khömi]: Mifa''anö ami ba mi''anizi-nizi.', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 10, 'Mi''amagölö, ba si lö fozu dania! Mifakhoi, ba si lö fakhai; noa sa awöda Lowalangi!', '["RazII 16:10","RazII 16:9","Yer 2:13; Yoh 9:7","Yes 7:14."]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 11, 'Noa sa imane khögu Yehowa, no ira''udo tangania; no itenaŵa ndra''odo, fa böi utörö lala mbanua andre [no imane]:', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 12, 'Böi ahori ni''amoni''ö khömi niŵa''ö mbanua andre ni''amoni''ö; ba sata''u ira, ba böi mi''ata''ufi ba böi tokea ami khönia!', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 13, 'Yehowa ngahönö andrö mi''amoni''ö; ena''ö na ya''ia zata''u ami, ba si tokea ami.', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 14, 'Ba ya''ia gamonita ba kara nitendre ba gowe salau ita, ba mbanua Ndraono Gizeraeli andrö si dombua, tandraŵa ba fesu ba mbanua Yeruzalema andrö.[5]', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 15, 'Ba ato khöra zanendre ba salau ba sarasa ba si te''ala ba wesu, salau.[6]', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 16, 'Irö''ö nifa''ele''ö andrö, fotandro goroisa, ba nifahaögu andrö![7]', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 17, 'Ba ubazebaze''ö khö Yehowa; si no mamini''ö bawania ba ma''uwu Yakobo, ba udöna-döna khönia.', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 18, 'Hiza, ya''odo ba iraono andrö, nibe''e Yehowa khögu, ba no tandra ba no sahöli-höli dödö ba Ndraono Gizeraeli ndra''aga, khö Yehowa ngahönö andrö si so nahia ba hili Ziona.[8]', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 19, 'Ba na lamane khömi: Misofu ba mbekhu ba ba zi faeta, si fangöngö-ngöngö, si lö alua baeha li — hadia, tenga khö Lowalanginia isofu lala soi niha? Hadia, ba zi no mate manofu ita, na börö zauri?', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 20, '"Oroisa ba famaduhu''ö." Na tenga lamanö, ba zi lö fa''amoluo,[9]', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 21, 'ba latöröi danö, no aöndrö hulu ba si mate olofo ira, ba abu dödöra, na olofo ira, ba la''elifi razora ba Lowalangira, lafaöga höröra miyaŵa,', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476263, 'OT', 'Yesaya', 8, 22, 'ba lafaigi tou danö; ba ha sambalö fa''ata''u, ba fa''ogömi-gömi, sogömi-gömi sata''u ita; ba zi bongi tefatörö ira.', '["Faigi 28:14; Luk 2:34; Rom 9:32; FetI 2:7","Mat 21:44; Luk 20:18.","Dan 12:4.","Faigi 7:3; 8:3; Heb 2:13.","Luk 16:20; Yoh 5:39; FetII 1:19"]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 1, 'Tenga sa si lö tebulö zogömi-gömi, ba zi no göna famakao. Me föna, ba no ifatörö wangaila ba dano Zebuloni ba ba danö Nafetali, ba dania, ba i''ebua''ö döi, lala ba na i andrö, singa Yoridano, tanö niha solohe adu andrö.[1]', '["RazII 15:20; Mat 4:16,17.","Luk 1:79; Efes 5:14.","Sanguhuk 7:22.","Hez 30:9.","Luk 1:32.","Yer 23:5."]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 2, 'Banua sanörö sogömi-gömi, ba la''ila haga sabölö dania. Ba zi so ba danö, si no tehawu si bongi, ba mohaga dania.[2] Omuso sibai dödö öbe''e.', '["RazII 15:20; Mat 4:16,17.","Luk 1:79; Efes 5:14.","Sanguhuk 7:22.","Hez 30:9.","Luk 1:32.","Yer 23:5."]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 3, 'Ba zi lö ni''ebua''ömö fa''omuso dödö, ba somuso tödö dania fönau, timba wa''omuso dödö ba wamasi ba timba wa''omuso dödö na lafaosa gahulua ba wanuwö.', '["RazII 15:20; Mat 4:16,17.","Luk 1:79; Efes 5:14.","Sanguhuk 7:22.","Hez 30:9.","Luk 1:32.","Yer 23:5."]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 4, 'Kalo mbagi andrö, norora, ba ue andrö si tohare ba hulura, bözi-bözi andrö ba danga mandru, ba öfatö sa''ae, si mane me leoo Midiano andrö.[3]', '["RazII 15:20; Mat 4:16,17.","Luk 1:79; Efes 5:14.","Sanguhuk 7:22.","Hez 30:9.","Luk 1:32.","Yer 23:5."]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 5, 'Fefu wangaro zangaro andrö ba wanuwö ba baru andrö, si no göna do, ba nitunu sa''ae, ö galitö.[4]', '["RazII 15:20; Mat 4:16,17.","Luk 1:79; Efes 5:14.","Sanguhuk 7:22.","Hez 30:9.","Luk 1:32.","Yer 23:5."]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 6, 'Tumbu dania khöda nono, tebe''e khöda nono matua; tebe''e ba galisinia wamatörö ba tebe''e töinia Zahöli-höli dödö ba Samolala tödö ba Lowalangi sabölö, ba Ama zi lö aetu ba Salaŵa wa''atulö.[5]', '["RazII 15:20; Mat 4:16,17.","Luk 1:79; Efes 5:14.","Sanguhuk 7:22.","Hez 30:9.","Luk 1:32.","Yer 23:5."]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 7, 'Fa''asalaŵania ba wamatörö ba fa''atulö andrö, ba si lö aetu, ba dadaoma Dawido andrö ba ba gamatöröŵania, wangaro ya''ia ba fangabe''e ya''ia fanguhuku satulö, i''otarai da''e, ba irugi zi lö aetu. Fa''aukhu dödö Yehowa ngahönö zolau si manö.[6]', '["RazII 15:20; Mat 4:16,17.","Luk 1:79; Efes 5:14.","Sanguhuk 7:22.","Hez 30:9.","Luk 1:32.","Yer 23:5."]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 8, 'No ifa''ohe''ö daroma li ba ma''uwu Yakobo Yehowa, ba ba mbanua Ndraono Gizeraeli göna.', '["Faigi 5:25"]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 9, 'Ba böi zi lö la''ila banuara fefu, mado Geferayi andrö ba banua Zamaria — ba hokhara ba ba wayaŵasa dödö andrö; me lamane:', '["Faigi 5:25"]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 10, '"Kara tembo, ba no adudu, ba tafuli ta''otomosi kara hili nitoto: töla ara, ba no mu''obö, ba ta''ali eresi."', '["Faigi 5:25"]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 11, 'Ba no i''abe''e''ö Resino andrö Yehowa, ba no ifarourou nemalira.', '["Faigi 5:25"]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 12, 'Aramo moroi ba gatumbukha ba Dawa Wilisiti moroi ba gaekhula, ba no la''a Ndraono Gizeraeli, no la''ebua''ö mbawara. Ba ba da''ö fefu, ba lö tebulö wönunia; fadoro na, i''oro''ö dangania.[7]', '["Faigi 5:25"]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 13, 'Lö''ö sa i''otahögö soi andre zamözi ya''ia; lö la''alui Yehowa ngahönö andrö.', '[]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 14, 'Andrö dania ifalo''o Yehowa högö, awö gi''o, ba hogu nohi, awö zinasa ba Ndraono Gizeraeli, ha ma''öma''ökhö wa''ara.', '[]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 15, 'Högö zalaŵa ba si so töi, ba i''o zama''ele''ö andrö, sofaya.', '[]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 16, 'Ba samatörö soi andre, ba no tobali samaelungu, ba nifatörö andrö ba no ni''ohe ba wa''atekiko.', '[]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 17, 'Andrö wa lö alimagö khö Zo''aya nono matua khöra, ba lö ihakhösi tödö zi lö ama ba si lö ina ba si no mate ira matua, ba khöra. Dozi ira sa''ae, ba no sanao horö ba samazökhi si lö sökhi, ba dozi bewe, ba no solau faya-faya. Ba ba da''ö fefu, ba lö tebulö wönu Zo''aya; fadoro na, i''oro''ö dangania.', '[]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 18, 'Humola sa walösökhi andrö, hulö galitö, i''a za''a-sa''a mao ba sasai''ö, ba ira''i gatua si fadoro, no aitö zimbo silalö miyaŵa.', '[]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 19, 'Fönu Yehowa ngahönö andrö wogozi danö, ba timba gö galitö niha; lö alimagö nawönia ba zamösana.', '[]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 20, 'Lataba öra gambölö, ba lö tebulö wa''olofo, ba manga ba gabera, ba lö abuso; i''a nagole da''ionia zamösana.', '[]', NULL),
  (3476264, 'OT', 'Yesaya', 9, 21, 'I''a Ndraono Manase Iraono Geferayi ba i''a Ndraono Geferayi Iraono Manase, ba darua ira, ba si manga Iraono Yuda. Ba ba da''ö fefu, ba lö tebulö wönu Zo''aya; fadoro na, i''oro''ö dangania.', '[]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 1, 'Alai zamakhoi si lö atulö, awö durutuli andrö, sanuranura famakao!', '[]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 2, 'Fomba''a lala huku, ba zi numana, ba fa lö lala huhuo ba zebua famakao, ba mbanuagu andrö, ena''ö öra zi no mate ira matua ba ena''ö la''ila larabu zi so khö zi lö ama, si lö ina.', '[]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 3, 'He miwisa sa na baŵa wotu ba na itörö ami angi sabölö moroi ba zaröu? Ha khö misaŵa, ba wangalui fangorifi ba heza mibe''e lakhömimi?', '[]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 4, 'Na lö iköwö ia zamösana ba gotalua niha nirabu, ba te''ö''ötö ia tou, awö nibubunu andrö. Ba ba da''ö fefu, ba lö tebulö wönu Zoaya; fadoro na, i''oro''ö dangania.', '[]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 5, 'Alai Ndrawa Asiria andrö, bago gama andrö khögu, ba wönugu, ba bözi-bözi khögu ba wa''abao dödögu andrö![1]', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 6, 'Ufatenge ia fangotu''ö soi andrö, sanao horö; u''oroi''ö ia fotu mado andrö, sofönu ndra''odo. Ena''ö la''oloi''ö gama-gamara, ena''ö la''osindra''ui, ba ena''ö lahundragö ira, nifanguhundra tambu ba golayama.', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 7, 'Ba tenga si manö gera-erania, tenga da''ö dödönia; si so ba dödönia, ba ena''ö oya ifakiko soi niha, ena''ö oya ihori.', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 8, 'Imane sa''ae: "Hadia, tenga no amaedola razo gumandru andrö khögu fefu?[2]', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 9, 'Hadia, tenga lala Garikemi mege lala Galino? ba tenga lala Garafada lala Hamata? ba tenga lala Ndramaseko andrö lala Zamaria?[3]', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 10, 'Si mane me ubaya mege nöri niha baero andrö, soya adu, moroi ba Yeruzalema ba moroi ba Zamaria —,', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 11, 'Hadia lö u''ila ulau ba Yeruzalema ba ba nadura andrö nilaugu ba Zamaria ba ba ba nadura?"[4]', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 12, 'Ba na no awai fefu halöŵö Zo''aya ba hili Ziona andrö ba ba Yeruzalema, ba möido mufaigi [iŵa''ö So''aya] mbua-bua hokha razo Asiria andrö, awö watandrosa hörönia andrö, sebua fayaŵasa.', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 13, 'Me imane: "Fa''abe''e dangagu ba fa''atua-tuagu, wa ulau da''ö, u''ila sa''ae watahögö. No uwu''ai nola soi niha ba no urabu nihönara andrö, no utimba ira ba dadaomara, si mane sabölö.', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 14, 'No ira''u tangagu gana''a soi niha, timba wondra''u azuni wofo; si mane na lahalö gadulo niröi wofo, si manö wangaigu tanö ma''afefu; lö''ö na''i samaliŵa afinia, lö samokai bawa ba lö si faki!"', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 15, 'Hadia, isuno ia maö fato khö zi oleŵa''ö ya''ia? Hadia, fayaŵa garagazi, ilaŵa zamatörö ya''ia? Amaedola na ifangaha zanuyu ya''ia bözi-bözi, ba amaedola na ifazaŵa ue zi tenga eu.[5]', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 16, 'Andrö dania ifatörö So''aya, Yehowa ngahönö andrö, wa''ariri ba zesolo andrö khönia, ba ba lakhöminia andrö, ba ebua galitö, timba zino wa''u.[6]', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 17, 'Ba haga andrö ba Ndraono Gizeraeli, ba tobali alitö, ba ni''amoni''ö andrö khöra, ba tobali hola-hola, ba humola ba i''a za''a-sa''a mao andrö ba sasai''ö andrö khöra, ha ma''öma''ökhö.[7]', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 18, 'Ba ahori gatua sabölö andrö, awö geu sowua ba kabu ibe''e, hunö fabaya ösi, timba na ariri zofökhö baosi.', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 19, 'Ba si tosai töla geu ba gatua khöra, ba lö oya-oya, irege i''ila itanö ba zura iraono.', '["Faigi 36:1 b.t.","RazII 18:24","MozI 10:10; SamII 8:9; RazII 18:34; 19:13","Faigi 36:13–20","Rom 9:20","Sin 22:30","Heb 12:29"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 20, 'Ba na luo da''ö, ba lö''ö sa''ae labe''e we''e-we''e dödöra zi no mamakao ya''ira si tosai Iraono Gizeraeli ba si no moloi ma''uwu Yakobo, Yehowa andrö, ni''amoni''ö Ndraono Gizeraeli sa''ae lahalö we''e-we''e dödöra, soroi ba dödö.', '["Faigi 7:3","Faigi 11:11; Rom 9:27,28.","Faigi 28:22","MozII 14:26","Sanguhuk 7:25; MozII 14:27"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 21, 'Si tosai andrö, ba lafuli ira ba zi sökhi; si tosai ma''uwu Yakobo, ba lafuli ira khö Lowalangi sabölö.[8]', '["Faigi 7:3","Faigi 11:11; Rom 9:27,28.","Faigi 28:22","MozII 14:26","Sanguhuk 7:25; MozII 14:27"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 22, 'He sa fa''oya ngawua nene ba mbewe nasi niha khömi, ya''ami Iraono Gizeraeli, ba ha si tosai andrö zamuli ya''ira ba zi sökhi. Noa sa muhonogöi wangohori, sanörö, satulö lala.[9]', '["Faigi 7:3","Faigi 11:11; Rom 9:27,28.","Faigi 28:22","MozII 14:26","Sanguhuk 7:25; MozII 14:27"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 23, 'Ifalua sa dania Yehowa ngahönö andrö wangohori andrö, nihonogöinia, ba dalu danö.[10]', '["Faigi 7:3","Faigi 11:11; Rom 9:27,28.","Faigi 28:22","MozII 14:26","Sanguhuk 7:25; MozII 14:27"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 24, 'Andrö wa imanö Yehowa ngahönö andrö: Ya''ami banuagu, banua Ziona, böi mi''ata''ufi Ndrawa Asiria, sangahare''ö ue khömi ba samangaha bözi-bözi khömi, si mane ba danö Miserayi föna.[11]', '["Faigi 7:3","Faigi 11:11; Rom 9:27,28.","Faigi 28:22","MozII 14:26","Sanguhuk 7:25; MozII 14:27"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 25, 'Lö''ö sa ara tö, ba alö wa''abao dödö [gu], ba ifaudugö ira fönugu, ba wangohori ya''ira.', '["Faigi 7:3","Faigi 11:11; Rom 9:27,28.","Faigi 28:22","MozII 14:26","Sanguhuk 7:25; MozII 14:27"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 26, 'Ba ibaha dania khöra mbözi-bözi Yehowa ngahönö andrö, si mane me ibago Ndraono Midiano ba gara Orebi. I''oro''ö dania zi''onia yaŵa nasi, si mane me i''oro''ö ba Ndrawa Miserayi.[12]', '["Faigi 7:3","Faigi 11:11; Rom 9:27,28.","Faigi 28:22","MozII 14:26","Sanguhuk 7:25; MozII 14:27"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 27, 'Ba na luo da''ö, ba abu''a ba galisiu noro andrö khöra, ba kalo mbagi andrö khöra, ba abu''a ba mbagiu.', '["Faigi 7:3","Faigi 11:11; Rom 9:27,28.","Faigi 28:22","MozII 14:26","Sanguhuk 7:25; MozII 14:27"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 28, 'Larugi Nayata, latörö Migerono; ba Mikhima laröi gama-gamara.', '["SamI 13:23; 10:26","SamI 25:44","SamI 22:11"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 29, 'Latörö mbawa danö andrö, ba Geba mörö ira. Tokea Rama; moloi Gibea Zaulo.[13]', '["SamI 13:23; 10:26","SamI 25:44","SamI 22:11"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 30, 'Mi''ebua''ö li we''ao, ya''ami banua Galimi! Mifondrondrongo, ya''ami La''isa! Mitema li, ya''ami Anatoti!', '["SamI 13:23; 10:26","SamI 25:44","SamI 22:11"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 31, 'Moloi Madamena, ba banua Gebimi, ba soloi göi.[14]', '["SamI 13:23; 10:26","SamI 25:44","SamI 22:11"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 32, 'Ba sara wongi ira ba Nobi; ba i''oro''ö dangania ba hili mbanua Ziona, ba hili mbanua Yeruzalema andrö.[15]', '["SamI 13:23; 10:26","SamI 25:44","SamI 22:11"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 33, 'Ba hiza, ba ilöwa tou Yehowa ngahönö andrö ndraha andrö sata''u ita. Ena''ö te''obö tou zi no alaŵa hogu andrö ba ena''ö te''ide-ide''ö zi no töra fa''ebua.', '["SamI 13:23; 10:26","SamI 25:44","SamI 22:11"]', NULL),
  (3476265, 'OT', 'Yesaya', 10, 34, 'Sasai''ö ba gatua, ba te''eŵa si''öli, ba sabölö zangohori eu ba hili Libano.', '["SamI 13:23; 10:26","SamI 25:44","SamI 22:11"]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 1, 'Tumbu dania lewiö ba duhe iza''i andrö ba mowua nono, si oroi ŵa''ania.[1]', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 2, 'Ba ahono khönia Geheha Yehowa; Eheha sama''ema fa''atua-tua ba fa''aboto ba dödö ba famolala tödö ba fa''abölö ba fangila watahögö ba fangata''ufi Yehowa.[2]', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 3, 'Samohua khönia wangata''ufi Yehowa andrö; tenga ni''ila hörönia dali wanguhukunia, ba tenga dali wangetu''ö huku nirongo dögi dalingania;', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 4, 'Satulö sa''ae dali khönia wame''e huku ba zi numana, ba i''adölö''ö wangetu''ö huku ba zebua famakao ba danö. Famözi niha guli danö khönia zi''o mbawania andrö [taroma linia] ba famunu zebua horö khönia hanu-hanu andrö ba mbewenia.[3]', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 5, 'Fa''atulö mböbö löwi-löwinia ba fa''aduhu mböbö talu khönia.', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 6, 'Ba orudu dania ba nono mbiri-biri nasu gatua ba si manö harimo ba nono mbiri-biri si matua. Ono zaŵi ba ono zingo ba saŵi nibula, ba orudu, fa tola kubalo ndraono.[4]', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 7, 'Saŵi si alawe ba berua si alawe, ba sorudu ba mbenua, ba ha sambua naha wemörö ba nonora; ba du''u dania gö zingo, du''u ö zaŵi.', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476266, 'OT', 'Yesaya', 11, 8, 'Famaimai ba mbawa dögi gulö zi lö aefa na ba mbagi zusu, ba itufa tangania hörö daritö si bohou aefa.[5]', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 9, 'Lö samakao awönia ba lö samakiko ba hili ni''amoni''ö andrö khögu ma''asambua; anönö sa''ae danö wa''aboto ba dödö niha Yehowa, si mane fa''anönö doyo nasi andrö asi.', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 10, 'Ba na luo da''ö, ba lazofu-zofu niha baero lewiö andrö, si tumbu ba ŵa''a duhe Iza''i andrö, nibe''e tandra soi niha, ba si so lakhömi nahiania.', '["Faigi 4:2","Fam 1:4","Yob 4:9; TesII 2:8; Fam 2:16.","Faigi 65:25; Hos 2:18","Amaed 23:32."]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 11, 'Ba na luo da''ö, ba ifuli i''oro''ö dangania So''aya, samuza tö, ba wangöhöli si tosai banuania andrö, si lö ahori no ba Ndrawa Asiria ba ba Miserayi ba ba Watero ba ba Gaitiofia ba ba Gelama ba ba Zineara ba ba Hamata ba ba hulo andrö ba nasi.[6]', '["MozV 30:1–5","MozII 14:21"]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 12, 'Ba itaru''ö dandra ba niha baero, ba i''owuloi zizaewe, Iraono Gizeraeli ba sizaewe Iraono Yuda, ba ifuli i''orudui, moroi ba mbalö danö andrö si öfa.', '["MozV 30:1–5","MozII 14:21"]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 13, 'Ba döhö wa''afökhö dödö Ndraono Geferayi ba nihori nudu Ndraono Yuda andrö. Lö''ö sa''ae afökhö dödö Ndraono Geferayi ba Ndraono Yuda, ba lö''ö sa''ae lafakao Ndraono Geferayi Iraono Yuda.', '["MozV 30:1–5","MozII 14:21"]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 14, 'Lalau sa''ae ira ba zanaere andrö ba Ndrawa Wilisiti tanö ba gaekhula ba la''orudugö ira wanuwö banua tanö ba gatumbukha. Latuturu Ndraono Gedomo ba Iraono Moabi, ba si möi barö mbawara Ndraono Gamoni.', '["MozV 30:1–5","MozII 14:21"]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 15, 'Ba i''ogo''öisi Yehowa zadöni asi andrö ba danö Miserayi ba i''oro''ö dangania ba nidanö sebua andrö [Oifarati], ifatörö nangi sabölö ba ifabali, fitu mbombo ibe''e, fa alakha lö muheta mbadagahe side-ide, na tatörö.', '["MozV 30:1–5","MozII 14:21"]', NULL),
  (3476266, 'OT', 'Yesaya', 11, 16, 'Ba tobali molala zi tosai banuania andrö, si lö ahori ba Ndrawa Asiria, si mane lala Ndraono Gizeraeli no, me la''otarai danö Miserayi.[7]', '["MozV 30:1–5","MozII 14:21"]', NULL),
  (3476267, 'OT', 'Yesaya', 12, 1, 'Ba na luo da''ö, ba ömane: "U''andrö saoha gölö khöu, ya''ugö Yehowa; noa sa mofönu ndra''ugö khögu, ba no döhö wönumö andrö, ba no örara dödögu.', '["MozII 15:2; Sin 118,14","Yoh 7:37","Nga''ötI 16:8; Sin 105:1."]', NULL),
  (3476267, 'OT', 'Yesaya', 12, 2, 'Hiza, fangorifigu Lowalangi; abe''e dödögu, ba lö ata''u ndra''o. Fangabe''egu sa''ae Zo''aya, Yehowa, sinunö ia khögu, ba no tobali fangorifigu ia."[1]', '["MozII 15:2; Sin 118,14","Yoh 7:37","Nga''ötI 16:8; Sin 105:1."]', NULL),
  (3476267, 'OT', 'Yesaya', 12, 3, 'Ba omuso dödömi wana''u idanö ba gumbu wangorifi andrö.[2]', '["MozII 15:2; Sin 118,14","Yoh 7:37","Nga''ötI 16:8; Sin 105:1."]', NULL),
  (3476267, 'OT', 'Yesaya', 12, 4, 'Ba mimane na luo da''ö: "Mi''andrö saoha gölö khö Yehowa; mi''angaröfi li döinia; midunö-dunö ba niha baero wolaunia andrö, mituriagö, wa no sebua döinia andrö![3]', '["MozII 15:2; Sin 118,14","Yoh 7:37","Nga''ötI 16:8; Sin 105:1."]', NULL),
  (3476267, 'OT', 'Yesaya', 12, 5, 'Misunö Yehowa! sebua sa nilaunia; yaterongo da''ö ba guli danö, ma''asagörö!', '["MozII 15:2; Sin 118,14","Yoh 7:37","Nga''ötI 16:8; Sin 105:1."]', NULL),
  (3476267, 'OT', 'Yesaya', 12, 6, 'Mi''omusoi''ö dödömi ba mi''anunö, ya''ami banua Ziona! me no sebua Ni''amoni''ö Ndraono Gizeraeli andrö ba khömi andrö!"', '["MozII 15:2; Sin 118,14","Yoh 7:37","Nga''ötI 16:8; Sin 105:1."]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 1, 'Nitandrösaigö ba Mbabeli da''e, ni''ila Yesaya andrö, ono Gamosi.', '[]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 2, 'Ba hili si lö eu''eu mitaru''ö mandrera; mi''abölögö mi''ao khöra; mikhawi ira tangami, ena''ö latörö mbaŵa göli ba zalaŵa andrö!', '[]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 3, 'No ube''e goroisa ba ni''amoni''ö andrö khögu, ba sabölö andrö khögu, ba no u''oroi''ö, ba wönugu andrö, sowua-wua tödö andrö khögu, sabe''e tödö.', '[]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 4, 'Terongo wagua-guasa, sato niha, ba hili, si mane na no ato zanuwö; rumuru soi baero andrö, si no orudu; ifaigi Yehowa ngahönö andrö he wisa zanuwö.', '[]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 5, 'La''otarai danö saröu, mbalö danö, Yehowa ba fakakenia andrö ba wönunia, ba wamakiko uli danö ma''asagörö.', '[]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 6, 'Mi''ege-ege! noa sa ahatö mbaŵa andrö khö Yehowa; irugi dania, amaedola wanudugö khö Wondrege Zalaŵa.', '[]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 7, 'Andrö adada danga, fefu; mangulu bakha dödö niha, fefu.', '[]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 8, 'Modokea ira, ihawui ira sihulu ba fa''afökhö hulu; mangiwöngiwö ira, si mane sadono; itöngö nawönia zamösana; no timba hola-hola galitö mbawara.', '[]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 9, 'Hiza, irugi baŵa andrö khö Yehowa, sata''u ita, abölö wa''abao dödö ba sihola wönu, ba wamali''ö tanö si mate tanö, ba ba wangohori ba danö sebua horö.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 10, 'Lö''ö sa''ae humaga dania ndröfi ba mbanua, hadia ia ndröfi andrö; ba luo, ba aitö, na tumbu, ba lö''ö sa''ae humaga mbaŵa.[1]', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 11, 'Ba ube''e wotu [iŵa''ö So''aya] ba niha guli danö, ba walösökhira andrö ba ba zebua horö, ba golalöŵara. Ubözini hokha zafaito andrö ba fayaŵasa zamakao awöra, ba uhöndrögö.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 12, 'Ebua dania mböli niha moroi ba mbalaki, ube''e, ba ebua mböli nono niha, moroi ba mbalaki Gofiri.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 13, 'Andrö ufahisi mbanua si yaŵa ba siheu danö ba sawu''a ba nahania, ba wa''abao dödö Yehowa ngahönö andrö, na luo humola wönunia.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 14, 'Ba dozi ira, ba hulo nago nigohi ba hulö mbiri-biri si lö kubalo, isaŵa niwara zamösana, ifuli ia khöra, moloi.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 15, 'Dozi nisöndra, ba nitaru''ö toho, ba dozi nira''u, ba ni''ö''ötö föda.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 16, 'Onora, ba nirasa ba zanehe höröra, ösi nomora, ba nirabu ba ira alawera, ba nihoröni.[2]', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 17, 'Hiza, ufarou Ndrawa Media andrö emalira, si lö ba dödö firö, ba si lö omasi ana''a.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 18, 'Fanara, ba famakiko nono matua, ba lö ahakhö dödöra dabina ba dalu, ba lö afökhö khöra ndraono.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 19, 'Ba lala Zodoma ba lala Gomora, nidudugö Lowalangi, irege doyo gehomo tou, dania lala Mbabeli andrö, fondrege zi sökhi banua, lala lakhömi Ndrawa Galedaia andrö, si no ebua hokha.[3]', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 20, 'Lö''ö sa''ae niha khönia, sagötö tanö, tenga banua, götö-götö wa''ara; lö labe''e ba da''ö nosera Dawa Ara, ba lö molombase gubalo ba da''ö.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 21, 'Utu ndru''u zi morö ba da''ö, ba omora, ba sanönö lamuhu. Fofo ondra zonahia ba da''ö ba bekhu zolaya.[4]', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476268, 'OT', 'Yesaya', 13, 22, 'Mukao nasu gatua ba gödo ba asu ana''a zikao ba nomo zalaŵa omasiö. Itugu ahatö mbaŵa andrö khöra, ba lö tefazaŵa mbongi.', '["Hez 32:7; Yoel 2:31; Mat 24:29","Sin 137:9","MozI 19:24","MozIII 16:10; Mat 12:43"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 1, 'Ihakhösi sa tödö ma''uwu Yakobo Yehowa ba ifuli ituyu Ndraono Gizeraeli, ifuli ifataro ira ba danöra. La''ondrasi dania ira niha bö''ö, möi awö ma''uwu Yakobo ira.', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 2, 'Lahalö ira niha baero, la''ohe ba nahara, ba ma''uwu Gizeraeli zokhö ya''ira (niha bö''ö andrö) ba danö Yehowa andrö, sawuyura, ira matua ba ira alawe. Tobali lara''u zondra''u ya''ira mege ba labe''e barö mbawara zamakao ya''ira mege.[1]', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 3, 'Ba na no ahono ndra''ugö ibe''e Yehowa, na no döhö wamakao ba fa lö ahono-hono andrö ba fa''asawuyu sabe''e andrö, nihare''ö khöu mege,', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 4, 'awena dania manunö ndra''ugö, fango''aya razo Mbabeli andrö, ömane: "Ha lö ahono zamakao andrö, ha lö atebato wamakao andrö!', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 5, 'No ifatö Yehowa zi''o zebua horö, si''o zalaŵa andrö,', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 6, 'samözi-mözi soi niha ba wa''abao dödönia andrö, famözi si lö aetu, sanguhundragö niha baero ba wönunia, fanguhundra si lö fondrege.', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 7, 'Ahono danö ma''asagörö, molombase: ma''iki-iki ira.', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 8, 'He naru''u, ba omuso dödö, wamaigi ya''ugö andrö, ba eresi ba hili Libano, lamane: "Götö wa no te''ala ndra''ugö, ba lö si möi miyaŵa ba da''e khöma, ba wolobö ya''aga."', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 9, 'Banua tou, ba humufa ba khöu andrö, me so''ö; ikeani fönau mbekhu zi mate, fefu zamatörö mege ba guli danö; maoso moroi ba dadaomara, iŵa''ö, fefu razo soi niha andrö.[2]', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 10, 'Ba dozi, ba latema, lamane khöu: "Hadia, ya''ugö göi zi no amomo, si mane ya''aga; no fagölö-gölö ndra''ugö khöma?', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 11, 'No numalö ba mbanua tou andre wayaŵasamö andrö, fabaya li mbiola andrö khöu; bonga sa''ae dufou, ba kuö-kuö gambalamö.', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 12, 'Ha lö atoru ndra''ugö moroi yaŵa ba mbanua, ya''ugö madala sabölö haga! Ha lö mu''obö ndra''ugö, ya''ugö si hundragö soi niha mege!"', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 13, 'Ba noa sa''ae öŵa''ö tödöu: "Da''usaŵa mbanua si yaŵa; alaŵa yaŵa ndröfi andrö khö Lowalangi ube''e dadaomagu; ba hili walukhata andrö dumadao ndra''o, ba wondrege yöu.[3]', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 14, 'Utalu''i lawuo si yaŵa, ufagölö-gölö ndra''o khö Wondrege Zalaŵa andrö!"', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 15, 'Ba tetimba ba mbanua tou ndra''ugö, ba wondrege zabakha kohokoho!', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 16, 'Sangila ya''ugö, ba lafaigi-faigi''ö, latöngöni ndra''ugö ba lamane: "Hadia, da''ö niha andrö, same''e manizi-nizi uli danö, samahisi amatöröŵa razo misa?', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 17, 'Hadia, ya''ia zamali''ö tanö si mate uli danö, sanudugö banua ba detenia, si lö mame''e mangawuli ba khöra nirabunia?"[4]', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 18, 'Dozi razo soi niha andrö — ba a''oi molombase, si lö ambö sumange, oi dozi monahia.', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 19, 'Ba ya''ugö, ba nitibo''ö, hulö ndraha geu si lö ba dödö niha, no aröu lewatömö; nihawui nibunu ndra''ugö, fabaya nitaru''ö si''öli mege, no timba gamatela nihundra-hundra.', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 20, 'Lö fao ndra''ugö ba zogamö lewatö kara tou, me no öfakiko danöu ba me no öbubunu mbanuamö; lö''ö sa''ae itörö li niha nga''ötö zebua horö andrö, götö-götö wa''ara.', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 21, 'Mifazökhi nahia, ba wanaba bagi nononia, börö horö ndra amara andrö, fa böi ebua ira, fa böi labe''e barö mbawara danö ba fa böi labe''e anönö danö adudula mbanua.[5]', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 22, 'Ba utema maoso khöra, iŵa''ö Yehowa ngahönö, ba uhori ba Mbabeli döira ba hadia zi tosai ba ono ba ma''uwu, iŵa''ö Yehowa.', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 23, 'Ba tobali naha mbogo ube''e ba tobali baŵa nidanö, ba ubözini ezoe fangohori, iŵa''ö Yehowa ngahönö andrö.[6]', '["Sakh 8:22","Amaed 2:18; Sakh 10:3","TesII 2:4","Yer 50:33","Yob 18:19; Sin 21:14; 37:28","Yes 34:11; Sef 2:14"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 24, 'No fahölu Yehowa ngahönö andrö, no imane: Si ndruhu, itörö nihonogöigu tödögu ba alua niŵa''ögu!', '["Faigi 37:36","Nga''ötII 20:6; Yob 9:12; Amaed 21:30"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 25, 'Urasa Ndrawa Asiria ba danö khögu; ba hili khögu uhundragö tou ia, ena''ö aheta galo mbagi andrö khönia ba mbagira ba ena''ö abu''a ba galisira nora andrö khönia.[7]', '["Faigi 37:36","Nga''ötII 20:6; Yob 9:12; Amaed 21:30"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 26, 'Da''ö nihonogöi, nifatörö ba guli danö ma''asagörö; da''ö danga andrö, si no mu''oro''ö yaŵa niha baero, fefu.', '["Faigi 37:36","Nga''ötII 20:6; Yob 9:12; Amaed 21:30"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 27, 'Yehowa ngahönö andrö sa zi hönogöi ya''ia, ba ha niha zi wu''ai? Na no i''oro''ö dangania, ba ha niha zamöda?[8]', '["Faigi 37:36","Nga''ötII 20:6; Yob 9:12; Amaed 21:30"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 28, 'Ba ndröfi wa''amate razo Ahasi, ba da''e niŵa''ö:[9]', '["RazII 16:20","Nga''ötII 28:18,19"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 29, 'Böi omuso dödöu, ya''ugö tanö Ndrawa Wilisiti fefu, me no afatö nue andrö, bözi-bözi si tohare khöu mege; moroi ba gamatela gulö mege alua sa''ae dania daritö ba lua-lua da''ö, ba naga sihombo.[10]', '["RazII 16:20","Nga''ötII 28:18,19"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 30, 'Ba si a''a zi numana, ba lasöndra gö, ba si lö töi ba falukha mörö lö hadia ia. Ba ŵa''amö andrö, ba ubunu fa''olofo, mate zi tosai khöu ibe''e.', '["RazII 16:20","Nga''ötII 28:18,19"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 31, 'Ege''ege, ya''ugö bawa göli! Ira''ira, ya''ugö banua! Anizi-nizi, ya''ugö tanö Ndrawa Wilisiti, ma''afefu! Moroi yöu sa''ae i''otarai simbo, ba lö si fabali ba zato khöra.', '["RazII 16:20","Nga''ötII 28:18,19"]', NULL),
  (3476269, 'OT', 'Yesaya', 14, 32, 'Ba hadia niŵa''ö, fanema li zinenge niha baero andrö? [Tamane]: Yehowa zanaru''ö banua Ziona andrö, ba ba da''ö lasöndra zaŵatö si numana mbanuania andrö.', '["RazII 16:20","Nga''ötII 28:18,19"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 1, 'Hiza, ba zi bongi tedudugö Ari-Moabi andrö, nihori! Hiza, ba zi bongi tedudugö Giri-Moabi andrö, nihori![1]', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 2, 'Möi miyaŵa ba gosali ba hili andrö Ndribona, ba wege-ege. Ba hili Nebo ba ba Medeba mege-ege Ndraono Moabi; dozi no mutöwö mbu ba högö ba no muhori gambi.[2]', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 3, 'Ba newali khöra, ba la''onukha gonigoni; ba dete nomora yaŵa ba ba kade misa, ba ha sambalö fege-ege ba fa''ahele daŵa hörö.', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 4, 'Mangarö-ngarö Hesibona ba Eleale, irugi Yahasi terongo lira. Andrö kumirakira zi no mangaro andrö Iraono Moabi, dozi afökhö bakha dödö.', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 5, 'Me''e dödögu ba Ndraono Moabi andrö; larugi Zoara soloi, Soara si no amaedola nono zaŵi si medölu fakhe. Mege-ege ira wanörö miyaŵa lala ba Luhiti, mu''ira-ira ba lala ba Horona''i.[3]', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 6, 'Noa sa otufo nidanö Nimiri; no mate ndru''u, ariri mbulu zinanö, lö sauri sa''ae.', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 7, 'Andrö lafa''ötö ba mbombo ba mbou andrö girö-giröra, nibe''era yaŵa, awö nihönara andrö.', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 8, 'Itöröi sa''ae danö Ndraono Moabi ma''afefu fangarö-ngarö andrö; irugi Negela''i, ba mege-ege ira, ba irugi Mbe''eri Elima, ba fege-egera.', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476270, 'OT', 'Yesaya', 15, 9, 'Noa sa anönö do nidanö ba Ndrimona; ba ufatörö na sa wamakao si bohou ba Ndrimona andrö, wamatenge singo ba zoloi andrö, Iraono Moabi, ba ba zi tosai andrö ba danö.', '["Yer 48; Hez 25:8 b.t.; Amos 2:1 b.t.","Hez 7:18","MozI 19:20; SamI 13:9; Yer 48:34"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 1, '"Mifa''ohe''ö nono mbiri-biri ba zalaŵa ba danö, moroi ba Zela, nifatörö ba danö si mate, ni''ohe ba hili Ziona."[1]', '["RazII 3:4; 14:7","SamII 7:16; Dan 7:27; Mikh 4:7; Luk 1:33"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 2, 'Ba larugi götöna ba Garono banua Ndraono Moabi, timba wofo sangafongafo, timba nitaboi ba gazuni.', '["RazII 3:4; 14:7","SamII 7:16; Dan 7:27; Mikh 4:7; Luk 1:33"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 3, 'Mifaigi wamolala dödö, mi''ohe ba lala! Abölögö lumöu, ba zi laluo, timba ba zi bongi; bini''ö zizaewe andrö; böi ombakha''ö zoloi andrö!', '["RazII 3:4; 14:7","SamII 7:16; Dan 7:27; Mikh 4:7; Luk 1:33"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 4, 'Alakha fatewu khöu zihufa andrö, Iraono Moabi; iagö ba''a-ba''a khöra ba zamakiko andrö; aetu sa dania zamakao andrö ba tebato wamalangögö; aheta dania ba danö zi hundragö awöra.', '["RazII 3:4; 14:7","SamII 7:16; Dan 7:27; Mikh 4:7; Luk 1:33"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 5, 'Ba fa''ebua dödö wangaro dadaoma zalaŵa, ba lö tebulö zidadao yaŵa, ba nose Dawido andrö, sanguhuku ba sangalui lala satulö ba sondrou''öndrou''ö fa''atulö.[2]', '["RazII 3:4; 14:7","SamII 7:16; Dan 7:27; Mikh 4:7; Luk 1:33"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 6, 'No tarongo wayaŵasa Ndraono Moabi andrö, wa no ebua sibai, hokhania andrö ba fayaŵasania ba wa''asilöyaŵania, bewenia faya andrö.[3]', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 7, 'Andrö la''e''esi Ndraono Moabi Iraono Moabi; oi dozi mege-ege ira. Ba gadudula Giri-Haresi mangarö-ngarö ami; si no arasa tödö ami.', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 8, 'Mate zinanö ba nowi Hesibona, agu ba Zibema, ba no lafufu salaŵa niha baero, agu andrö sirugi Ya''ezeri, selungu irege ba danö si mate, sangoro daha, sangötö zilua asi.', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 9, 'Andrö me''e ndra''o, awö mbanua Ya''ezeri, ba nagu Zibema andrö; ubasöi ami taŵa hörögu, ya''ami Hesibona ba Eleale, noa sa faudu ba wangai bua khömi ba ba wamasimi wa''igi nemali andrö.', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 10, 'No aböda wa''omuso dödö ba fa''iki, ba nowi; ba ba kabu nagu, ba lö''ö sa''ae sanunö ba lö sowua-wua tödö. Lö solazi bua nagu ba wolazi; no ufadöhö li wa''iki andrö.', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 11, 'Andrö molili bakha dalugu, hulö mbiola, ba Ndraono Moabi andrö, ba betu''agu, ba Giri-Haresi andrö.', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 12, 'Ba tobali, na so Ndraono Moabi, na erege dödöra ba hili-hili andrö naha wame''e sumange, na möi ira ba ni''amoni''ö andrö khöra, ba wangandrö, ba si lö fozu.[4]', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 13, 'Da''ö niŵa''ö Yehowa, me no andrö, nitandrösaigö ba Ndraono Moabi andrö.', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476271, 'OT', 'Yesaya', 16, 14, 'Ba iada''e, ba imane Yehowa: Lö''ö sa''ae alua medölu fakhe [inötö ndröfi zi manga gazi], ba tobali fama''iki niha lakhömi Ndraono Moabi andrö, awö wa''ato niha andrö; ba si tosai dania, ba lö atoto, ha ma''ifu, si no amomo.', '["Yer 48:29","RazI 18:26"]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 1, 'Nitandrösaigö ba Ndramaseko da''e: Hiza, nihori dania Ndramaseko andrö, fa tenga banua sa''ae, ba tobali adudula.[1]', '["Yer 49:23 b.t.; Amos 1:3 b.t."]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 2, 'Si lö niha dania mbanua Garoeri andrö, tobali nahia göröbao; mörö-mörö ba da''ö, ba lö sanaboi.', '["Yer 49:23 b.t.; Amos 1:3 b.t."]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 3, 'Si lö''ö sa''ae banua saro Ndraono Geferayi (Samaria), ba lö''ö sa''ae fa''asalaŵa ba Ndramaseko. Ba lala zi tosai ba Garamo, ba si mane lala wa''abölö Ndraono Gizeraeli, iŵa''ö Yehowa ngahönö andrö.', '["Yer 49:23 b.t.; Amos 1:3 b.t."]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 4, 'Ba na luo da''ö, ba ide-ide lakhömi ma''uwu Yakobo ba ariri wa''esolo nösira andrö.', '["Faigi 24:12"]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 5, 'Tobali hulö na ifarahugö döla wakhe samasi ba na itaba ngalai tangania; tobali si mane na la''ozaragö lai wakhe ba ndraso Refa''i.', '["Faigi 24:12"]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 6, 'Wo''uwo''u zi tosai, si mane na lateteu mbua falo, na so zi tosai irege mato tölu ngawua ba lailai, ba irege mato lima ngawua ba ndraha döla, iŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli andrö.[2]', '["Faigi 24:12"]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 7, 'Awena dania lafuli lafaöga mbagira niha ba zomböi ya''ira, ba la''alui höröra Ni''amoni''ö ba Ndraono Gizeraeli andrö.', '["Faigi 24:12"]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 8, 'Ba lö''ö sa''ae lafaigi-faigi naha wame''e sumange andrö, nifazökhi dangara ba he Asera andrö ba adu luo, niwöwöira tuturura.', '["Faigi 24:12"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476272, 'OT', 'Yesaya', 17, 9, 'Ba na luo da''ö, ba lala mbanua andrö ba gatua ba ba hili, niröi mege föna Ndraono Gizeraeli, lala mbanua saro andrö khöra: adudula gamozua.', '["Faigi 24:12"]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 10, 'Me no olifu''ö Lowalangi, fangorifiu andrö, ba me no lö ba dödöu gowe andrö, ba''a-ba''a andrö khöu: andrö wa öfazökhi kabu omasiö ba ötanö zinanö nihalö ba niha bö''ö.', '["Faigi 24:12"]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 11, 'Na luo ötanö ia, ba ökölini, ba ahulö mobowo zinanöu, öbe''e, ba si lö boto wangai bua, na luo wökhö ba fa''afökhö si lö famadöhö.', '["Faigi 24:12"]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 12, 'Alai ndra''o! Hiza we''ugu-ugu zato sibai niha — fe''ugu-ugu nasi we''ugu-ugura andrö; ba fegoso-goso soi niha andrö — fegoso-goso molö sebua wegoso-gosora.', '["Yob 24:18; Sin 1:4; 35:5.","RazII 19:35, Faigi 37:36."]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 13, 'Mugoso-goso soi niha, si mane fegoso-goso molö sebua! Ba na itegu ira Yehowa, ba moloi ira, lasaŵa zaröu, nifehombo, si mane adaya ba hili ba nangi sabölö ba si mane gawu-gawu si tefuyu ba dawuyu nangi.[3]', '["Yob 24:18; Sin 1:4; 35:5.","RazII 19:35, Faigi 37:36."]', NULL),
  (3476272, 'OT', 'Yesaya', 17, 14, 'Hiza, na tanö owi, ba fa''otobali dödö, ba lö fakhamö moluo, ba lö ya''ira. Da''ö lala zi farabu ba khöda, urakha zangosindra''ui gama-gamada.[4]', '["Yob 24:18; Sin 1:4; 35:5.","RazII 19:35, Faigi 37:36."]', NULL),
  (3476273, 'OT', 'Yesaya', 18, 1, 'Alai ndra''ugö, ya''ugö tanö wehozihozi gafi, yefo nidanö Gaitiofia![1]', '["Faigi 37:9; Nah. 3:8","Hez 31:3 b.t.","Sin 68:32, HalZin 8:27"]', NULL),
  (3476273, 'OT', 'Yesaya', 18, 2, 'Samoloyo sinengenia ba dundraha sukhu, ba Nilo. "Midölö ami, ya''ami sinenge salio, ba niha sebua boto ba safusi, ba niha sata''u niha bö''ö misa, sabölö sibai, si hundragö awöra, ba danö si so idanö sebua."', '["Faigi 37:9; Nah. 3:8","Hez 31:3 b.t.","Sin 68:32, HalZin 8:27"]', NULL),
  (3476273, 'OT', 'Yesaya', 18, 3, 'Ya''ami fefu, si so ba guli danö, ya''ami sowanua ba detenia: na la''taru''ö mandrera ba hili, ba mitöngöni; ba na lalau dorofe, ba mifondrondrongo!', '["Faigi 37:9; Nah. 3:8","Hez 31:3 b.t.","Sin 68:32, HalZin 8:27"]', NULL),
  (3476273, 'OT', 'Yesaya', 18, 4, 'Noa sa imane khögu Yehowa: Da''uhonogö ndra''odo ba ufaigi moroi ba nahagu, si mane fa''aukhu zino na lökhö ba si mane sau, na baŵa wamasi.', '["Faigi 37:9; Nah. 3:8","Hez 31:3 b.t.","Sin 68:32, HalZin 8:27"]', NULL),
  (3476273, 'OT', 'Yesaya', 18, 5, 'Gasa-gasa wangai bua sa, na no atoru mbowo, na itugu tobali bua sasoso dania wu''uwu''u andrö, ba itaba förögi mbadöbadö, iheta ndraha, ifalo''o.[2]', '["Faigi 37:9; Nah. 3:8","Hez 31:3 b.t.","Sin 68:32, HalZin 8:27"]', NULL),
  (3476273, 'OT', 'Yesaya', 18, 6, 'Ahori itehe ba wofo ba hili ba ba zaliŵa-liŵa ba danö, ba monaha ba khönia wofo, fatua baŵa lökhö, ba saliŵa-liŵa ba danö, na baŵa deu.', '["Faigi 37:9; Nah. 3:8","Hez 31:3 b.t.","Sin 68:32, HalZin 8:27"]', NULL),
  (3476273, 'OT', 'Yesaya', 18, 7, 'Ba na luo da''ö, ba la''ohe zumange niha sebua boto andrö, safusi, khö Yehowa ngahönö andrö, niha andrö, sata''u niha bö''ö misa, niha sabölö sibai, si hundragö awöra, ba danö si so idanö sebua — la''ohe ba naha döi Yehowa ngahönö andrö, ba hili Ziona.[3]', '["Faigi 37:9; Nah. 3:8","Hez 31:3 b.t.","Sin 68:32, HalZin 8:27"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 1, 'Nitandrösaigö ba Ndrawa Miserayi da''e: Hiza, fakureta Yehowa ba lawuo salio ba irugi danö Miserayi. Ba manizi-nizi nadu ba danö Miserayi, na so ia, ba mangulu dödö Ndrawa Miserayi barö dotora.[1]', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 2, 'Ba faoma ufa''udu Ndrawa Miserayi ba nawöra, ena''ö udu dalifusönia zi fatalifusö ba udu zi fahuwu khönia zi fahuwu ba udu mbanua si sambua zi sambua ba udu zi sara öri zi sara.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 3, 'Ba eheha baro dötö Ndrawa Miserayi, ba nitayaigö, ba era-erara, ba si lö boto ube''e, ba bawa nadu dania lasofu ba bawa zebua elemu ba bawa zi faeta ba bawa gere.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 4, 'Ba ube''e ba danga zalaŵa sabe''e Ndrawa Miserayi andrö; salaŵa safaito dania zamatörö ya''ira, iŵa''ö So''aya, Yehowa ngahönö andrö.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 5, 'Ogo''ö dania nidanö Nilo, otufo bakha nungo nidanö, lö idanö.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 6, 'Aböu wabaliŵania; tobali lö abakha-bakha tö nidanö niko''o andrö, ogo''ö; mate zukhu ba honu.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 7, 'Du''u ba ndraso, ba luaha Nilo, awö zinanö ba zingania, ba oköli, ariri ba lö ya''ia sa''ae.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 8, 'Tobali mangarö-ngarö zangalui i''a, abu dödö; dozi ira, he si fagai ba he si fadora, ba la''abusi tödö.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 9, 'Ba lö lala dödö zamoboto taliö, sanoso muko.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 10, 'Adudu dayadaya ba abu bakha dödö zi manga gazi, fefu.', '["Yer 46; Hez 29"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 11, 'Salaŵa ba Zoana, ba no adölö si lö tödö: anofula Wara''o andrö, fondrege zatua-tua; tobali tödö zowöhö mowa dödöra andrö. Hadia, wa mimane khö Wara''o: "Nga''ötö zatua-tua ndra''odo; nga''ötö zalaŵa föna?"[2]', '["MozIV 13:23; Sin 78:12","Faigi 9:14"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 12, 'Hezo zatua-tua andrö khöu? Ena''ö la''ombakha''ö khöu, ena''ö aboto ba dödö he wisa dödö Yehowa ngahönö andrö ba Ndrawa Miserayi.', '["MozIV 13:23; Sin 78:12","Faigi 9:14"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 13, 'Si lö tödö zalaŵa Zoana andrö, selungu zalaŵa Nofi; lafowöhö Ndrawa Miserayi samatörö banuara.', '["MozIV 13:23; Sin 78:12","Faigi 9:14"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 14, 'No ibe''e ba dödöra Geheha famowöhö Yehowa, ba lafowöhö sa''ae Ndrawa Miserayi ba nilaura fefu, timba zi mabu tuo, si hundra-hundra utania.', '["MozIV 13:23; Sin 78:12","Faigi 9:14"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 15, 'Ba lö dania ba danö Miserayi solau nilau högö ba i''o ba nilau bulu nohi ba bulu zinasa.[3]', '["MozIV 13:23; Sin 78:12","Faigi 9:14"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 16, 'Ba na luo da''ö, ba timba ndra alawe Ndrawa Miserayi, wa''atalö dödö ba fa''ata''ura danga Yehowa Ngahönö andrö, nibahania khöra.', '["MozIV 13:23; Sin 78:12","Faigi 9:14"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 17, 'Ba ata''u Ndrawa Miserayi göi danö Ndraono Yuda; dozi tehawu fa''ata''u ba nitörö lida ya''ia, börö dödö Yehowa ngahönö andrö, tödönia ba Ndrawa Miserayi.', '["MozIV 13:23; Sin 78:12","Faigi 9:14"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 18, 'Ba na luo da''ö, ba lima banua ba danö Miserayi zolau li ba danö Gana''ana ba si möi ba hölu ba khö Yehowa ngahönö, ba töi zi sambua ba banua wa''atulö labe''e dania.[4]', '["MozV 10:20","MozI 28:18; MozII 24:4; Yos 22:10","Mal 1:11"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 19, 'Na luo da''ö, ba so naha wame''e sumange Yehowa ba dalu danö Miserayi, awö gowe tandra, khö Yehowa, ba nolara.[5]', '["MozV 10:20","MozI 28:18; MozII 24:4; Yos 22:10","Mal 1:11"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 20, 'Tobali tandra da''ö khö Yehowa ngahönö ba famaduhu''ö ba danö Miserayi: na la''angaröfi li ia, ba zamakao andrö, ba ifatenge khöra zangorifi; da''ö zanimba sanuwö, wangorifi ya''ira.', '["MozV 10:20","MozI 28:18; MozII 24:4; Yos 22:10","Mal 1:11"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 21, 'Ba ifa''ele''ö ia ba Ndrawa Miserayi Yehowa, ba tobali aboto ba dödö Ndrawa Miserayi Yehowa, na luo da''ö, ba lafosumange ia sumange nitaba ba sumange bö''ö ba so dania nifabu''ura khö Yehowa ba labu''a göi.[6]', '["MozV 10:20","MozI 28:18; MozII 24:4; Yos 22:10","Mal 1:11"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 22, 'Si manö wamözi Yehowa Dawa Miserayi andrö ba famadöhönia safökhö khöra; ba lafuli dania ira khö Yehowa, ba ifondrondrongo li wangandröra ba i''orifi ira.', '["MozV 10:20","MozI 28:18; MozII 24:4; Yos 22:10","Mal 1:11"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 23, 'Na luo da''ö, ba so lala nihaogö, i''otarai danö Miserayi numalö ba danö Asiria; tobali möi ba danö Miserayi Ndrawa Asiria ba Dawa Miserayi andrö, ba möi ba danö Asiria; ba awö Ndrawa Asiria Ndrawa Miserayi wamosumange Yehowa.', '["MozV 10:20","MozI 28:18; MozII 24:4; Yos 22:10","Mal 1:11"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 24, 'Ba na luo da''ö, ba tölu soi ira, Dawa Miserayi ba Dawa Asiria, ba Iraono Gizeraeli, si faböbö khöra, howu-howu ba danö.', '["MozV 10:20","MozI 28:18; MozII 24:4; Yos 22:10","Mal 1:11"]', NULL),
  (3476274, 'OT', 'Yesaya', 19, 25, 'Famahowu''ö Yehowa ya''ira, wanguma''ö: Ya ahowu mbanuagu Dawa Miserayi ba Dawa Asiria, niwöwöigu tangagu, ba tana khögu andrö, Iraono Gizeraeli.', '["MozV 10:20","MozI 28:18; MozII 24:4; Yos 22:10","Mal 1:11"]', NULL),
  (3476275, 'OT', 'Yesaya', 20, 1, 'Me döfi möi ba Gasoto Daratano andrö, me no ifatenge ia Sarago andrö, razo Asiria, me isuwö Gasoto ba me atu''a ia.[1]', '["RazII 18:17"]', NULL),
  (3476275, 'OT', 'Yesaya', 20, 2, 'Me luo da''ö, ba imane Yehowa, nifa''ema Yesaya andrö, Ono Gamosi: Labu, heta lembe bu andrö ba löwi-löwiu ba heta mbadagahe ba gaheu! Ba i''o''ö: si lö lembe sa''ae ia ba si lö badagahe.', '["RazII 18:17"]', NULL),
  (3476275, 'OT', 'Yesaya', 20, 3, 'Ba imane Yehowa: Si mane enonigu Yesaya andrö, si lö lembe ba si lö badagahe, tandra ba amaedola ba Ndrawa Miserayi ba ba Ndrawa Gaitiofia,', '["RazII 18:17"]', NULL),
  (3476275, 'OT', 'Yesaya', 20, 4, 'medölu fakhe wa''ara, si manö dania Ndrawa Miserayi andrö ni''oloi''ö ba Dawa Gaitiofia ni''ohe misa, ibe''e razo Asiria, he iraono ba he satua, si lö baru ba si lö badagahe ba si lö balu-balu doyo, fangaila Ndrawa Miserayi andrö.', '["RazII 18:17"]', NULL),
  (3476275, 'OT', 'Yesaya', 20, 5, 'Ba tokea dania niha, ba abu dödö ba Ndrawa Gaitiofia andrö, ba nidöna-dönara fangorifi, ba ba Ndrawa Miserayi andrö, ba nisunora ya''ira.', '["RazII 18:17"]', NULL),
  (3476275, 'OT', 'Yesaya', 20, 6, 'Ba na luo da''ö, ba lamane sihene asi andrö [ba danö Ndrawa Wilisiti]: Na si manö zi göna nifaigi-faigida andrö, nisaŵada, wangalui fanolo, ena''ö auri ita khö razo Asiria andrö — ba he wisa aefa ita?', '["RazII 18:17"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 1, 'Nitandrösaigö ba danö si mate asi andrö [Babilona] da''e: Si mane angi sabe''e moroi raya, sihöngö moroi sa, si manö wa''asonia moroi ba danö si mate, moroi ba danö sata''u ita.[1]', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 2, 'No mu''oroma''ö khögu gangilata sabe''e: Mamakao awönia na zamakao andrö ba manudugö banua na zanudugö andrö! Labu misa, ya''ugö Elama! Anuwö, ya''ugö Dawa Media! Ufadöhö wangarö-ngaröra fefu!', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 3, 'Andrö dumi''adi''a zolagu, no ihawuido fa''afökhö hulu, si mane fa''afökhö hulu zadono, khumölökhölo khögu mbanua, fa lö urongo li niha; si no tokea ndra''o, fa lö u''ila niha.', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 4, 'Elungu-lungu bakha dödögu; tobali dödögu wa''ata''u; fa''abongi andrö, somasimasido mena''ö, ba u''ata''ufi ibe''e.', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 5, 'Lafazökhi meza, labologö dufo, manga ba mamadu hadia ia — milabu, ya''ami salaŵa, mibayoini mbaluse!', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 6, 'Si mane sa niŵa''ö Zo''aya khögu: Labu, fataro zamaigi-maigi! Yamu''ombakha''ö hadia ni''ilania!', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 7, 'Na i''ila zi fakudo, kudo si dua-dua geu ba si fakudo ba galide ba ma ba gondra, ba yamufondrongondrongo, yamube''e mbörö dalingania, ba wamondrongondrongo!', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 8, 'Ba mu''ao ia, timba li zingo linia, imane: "He So''aya, naha zanaro nahagu, ma''öma''ökhö, ba sara wongi lö ubulö''ö wanaro![2]', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 9, 'Ba so sibai zi fakudo; dua-dua geu kudo. Ba itema imane: "No atu''a, no atu''a nemali ba Mbabeli, ba adu khöra fefu, ba no larasa tou!"[3]', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 10, 'He ya''ami banuada, si no muböbörö ba nihundra-hundra tou! Nirongogu khö Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli, ba u''ombakha''ö khömi.', '["Faigi 14:22","Hab 2:1","Yer 51:8; Fam 14:8; 18:2"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 11, 'Nitandrösaigö ba Duma andrö da''e: So zi''ao khögu, banua Ze''ira, imane: "He sanaro, ha wa''alaŵa mbongi?[4]', '["MozI 25:14"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 12, 'Imane sanaro: Moluo ba bongi göi. Na edöna manofu ami, ba mifuli manö ami wanofu.', '["MozI 25:14"]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 13, 'Nitandrösaigö ba Ndrawa Ara da''e: Ba gatua ba danö Ara miförö, ya''ami saniaga Dawa Dedano![5]', '["MozI 25:3","Yer 25:23","Faigi 16:14; Yer 40:28 b.t."]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 14, 'Mifaondragö zowökhi tödö, mi''ohe nidanö, ya''ami sowanua ba danö Dema! Mioro''ö gö ba zoloi andrö.[6]', '["MozI 25:3","Yer 25:23","Faigi 16:14; Yer 40:28 b.t."]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 15, 'Börö zi''öli wa moloi ira, si''öli nibaha ba fana si no mukhai, fa''abölö wanuwö andrö.', '["MozI 25:3","Yer 25:23","Faigi 16:14; Yer 40:28 b.t."]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 16, 'Si manö sa niŵa''ö Zo''aya khögu: Lö''ö alua sibai ndröfi — inötö ndröfi zi manga gazi, — ba no taya wa''abölö Gedara andrö.[7]', '["MozI 25:3","Yer 25:23","Faigi 16:14; Yer 40:28 b.t."]', NULL),
  (3476276, 'OT', 'Yesaya', 21, 17, 'Ba si tosai dania fana zanuwö andrö, mado Gedara, ba lö oya-oya. Noa sa iŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli.', '["MozI 25:3","Yer 25:23","Faigi 16:14; Yer 40:28 b.t."]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 1, 'Nitandrösaigö ba ndraso wama''ele''ö andrö da''e: Hadia da''ö khömi, wa ahori möi yaŵa ami ba dete nomomi;', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 2, 'ya''ugö banua sebua ruru, sabölö fagua-guasa, ya''ugö banua saro, sowua-wua dödö niha? Tenga sa ni''ö''ötö si''öli zi no mate tou andrö khömi, tenga si mate ba wanuwö!', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 3, 'Fefu zolohe ya''ami, ba no ahori moloi ba no mura''u lö fana. Banuami fefu, ndrohu-ndrohu nikhamö, ba no ahori tera''u, he no aröu moloi.', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 4, 'Andrö umane: Böi mifaigi-faigigido! Da''uforege wege-ege! Böi mihötöi wondrara tödögu, ba wa''adudu mbanuada andrö.[1]', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 5, 'Baŵa wa''atobali dödö sa''ae moroi khö Zo''aya, Yehowa ngahönö andrö, baŵa wa''adudu, baŵa wa''afakuyu ba ndraso wama''ele''ö andrö; tedudugö göli kara ba telobi ba hili we''ira-ira.', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 6, 'No latuyu naha nono wana Dawa Gelama, fao gureta zanuwö ba si fakudo ba no laheta luniluni mbaluse banua Giri andrö.[2]', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 7, 'Ba no anönö kureta ndraso si sökhi andrö khömi, ba no lafa''anö ira si fakudo, ba gamaudu mbawa göli.', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 8, 'Ba no laheta mbalu-balu mbanua Yuda andrö, ba samaigi fangöna ami ba nomo eu gatua andrö.[3]', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 9, 'Ba mi''ila wa no fahöna zabökha öli ba mifaonö nidanö ba mbaŵa tanö tou.[4]', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 10, 'Ba mi''erai nomo ba Yeruzalema, ba midudugö ösa, fangazökhi göli kara.', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 11, 'Ba mifonaha nidanö ba gotalua göli si dua götö andrö, idanö ösi mbaŵa si no ara andrö. Ba lö''ö sa minehegö zolau ya''ia; si no mangohonogöi ya''ia föna sa''ae, ba lö mitöngöni.[5]', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 12, 'Mu''ao Zo''aya, Yehowa ngahönö andrö, me luo da''ö, ba wege-ege ba ba wange''esi ba ba wanöwö bu ba ba wonukha nukha ba wa''abu dödö.', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 13, 'Ba ha sambalö fa''iki ba fa''omuso dödö ba fanaba öröbao ba famunu biri-biri ba famadu-madu agu, femanga-manga ba famadu-madu hadia ia — "si mate sa atö ita mahemolu" [miŵa''ö]"[6]', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 14, 'Ba no ifarongo-rongogö khögu Yehowa ngahönö andrö, ba dögi dalingagu, imane: Si ndruhu, lö tebe''e aefa khömi lalömi andrö, irege mate ami — i''ŵa''ö So''aya, Yehowa ngahönö andrö.', '["Faigi 15:5; Ngenu 2:11","RazII 16:9; Faigi 11:11; Amos 1:5","RazI 10:17","SamII 5:9; Nga''ötII 32:5","RazII 25:4; Neh 3:15","Faigi 56:12; KorI 15:32"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 15, 'Si mane niŵa''ö Zo''aya, Yehowa ngahönö andrö: Labu, ae yomo khö mandru andrö, Sebena andrö, mandru yomo [ba ömane khönia]:', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 16, 'Hadia khöu ba ha niha khöu ba da''e, wa no öfakharu''ö khöu ba da''e lewatö? Ba hili yaŵa ifakharu''ö lewatönia, ba gara ifafahö''ö khönia mbate''e!', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 17, 'Hiza, i''abölögö ifazaumba ndra''ugö Yehowa, ya''ugö niha andrö; i''abe''e''ö danga, wondra''u ya''ugö!', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 18, 'I''olömbugö ndra''ugö, amaedola golömbu ifazaumba''ö baero ba danö sebolo; ba da''ö mate ndra''ugö; ba da''ö dania ofeta gureta andrö khöu, si sökhi sibai andrö, ya''ugö fangaila yomo ba nomo zokhö ya''ugö!', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 19, 'Utimba ndra''ugö ba nifataro ya''ugö andrö; lasöbi ndra''ugö, laheta''ö ba nahau.', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 20, 'Ba na luo da''ö, ba muhededo khö genonigu Eliaki andrö, ono Hilikia.[7]', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 21, 'Ba ube''e barunia mbarumö andrö ba böbö talunia mböbö talumö, ba famatörömö mege, ba ube''e ba dangania, ena''ö amaedola nama ia, ba mbanua Yeruzalema ba ba ma''uwu Yuda.', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 22, 'Ba ube''e ba dangania wogoe mbawandruhö nomo Dawido andrö, ena''ö lö sokusi, na ikoe, ba lö sogoe, na ikusi.[8]', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 23, 'Ba u''osö ia saita, ba nahia saro ia, ba ena''ö dadaoma lakhömi ia yomo ba nomo namania.', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 24, 'Ba tobali la''olembai ia fefu zi so töi yomo ba nomo namania, he daha sesolo ba he daha sise-ise, fefu gama-gama sakhökhö andrö, he figafiga andrö ba he kundri andrö fefu.', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476277, 'OT', 'Yesaya', 22, 25, 'Ba na luo da''ö — iŵa''ö Yehowa ngahönö andrö — ba adeha zaita andrö, ni''osö ba naha saro mege, tetimba ba aekhu tou, ba nisaitagö khönia, ba tefara''u; noa sa iŵa''ö Yehowa.', '["RazII 18:18","SamI 2:8"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 1, 'Nitandrösaigö ba mbanua Diro andrö da''e: Mi''ege-ege, ya''ami si otarai moloyo ba Dateso! hiza fönami wa''adudu; tobali lö omo, lö nahia sa''ae. Moroi ba danö Ndrawa Giti te''ombakha''ö khöra.[1]', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 2, 'Böi mihede-hede sa''ae, ya''ami si hene asi. No mege anönö danö saniaga andrö, banua Zidona, soloyoloyo ba nasi.', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 3, 'Ba nasi sa''ae möi khöra mbua nowi Nilo, nibasi ba ndraso nidanö sebua andrö, tobali kade niha baero ba khöra.', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 4, 'Aila ndra''ugö, ya''ugö Sidona! Noa sa imane asi, banua saro andrö ba mbewe nasi: "Lö safökhö hulugu, lö sadono ndra''odo! lö ni''urigu ono matua ba lö ni''e''ebuagu ono alawe!"[2]', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 5, 'Na terongo ba Ndrawa Miserayi, ba tobali dödöra ba duria Diro andrö.', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 6, 'Mi''oloyo, misaŵa Dateso! Mi''ege-ege, ya''ami si hene asi!', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 7, 'Hadia, da''ö mbanuami andrö, somuso dödö niha, si no götö-götö fa''ara, me tetaru''ö, sanaŵa saröu ba wanaru''ö banua misa?', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 8, 'Ha niha zi honogöi da''ö, nifatörö ba Diro andrö, banua sama''ema saembu ana''a, ba zi no salaŵa zi so lafo ba ba zi no fondrege zabölö ba guli danö zaniaga?', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 9, 'Yehowa ngahönö andrö zi no mangohonogöi, ba wango''aya famahokha gama-gama andrö fefu ba ba wame''e faya fondrege zalaŵa andrö ba guli danö, fefu.', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 10, 'Minönöi danömi, ya''ami banua Dateso, si mane Nilo andrö; lö ba''a-ba''a sa''ae.', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 11, 'No i''oro''ö dangania Yehowa yaŵa nasi, no ifahisi nöri andrö; no i''oroi''ö Yehowa ba khö Gana''ana andrö, ba wanudugö banua saro khöra.', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 12, 'No imane: Lö''ö sa''ae fa''omuso dödö khömi ya''ami banua Zidona amaedola nono alawe ni''o''aya! Milabu, misaŵa Ndrawa Giti misi yefo! Ba he ba da''ö, ba lö fa''ahono khömi.', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 13, 'Hiza danö Ndrawa Galedaia andrö — da''ö soi andrö, si no muzaewe! No latehe ba gutu ndru''u ba danö si mate Dawa Asiria. No lalau malige, naha zanaro; na lafaulugö wanudugö gödo khöra, no labali''ö adudula.', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 14, 'Andrö mi''ege-ege, ya''ami soloyo ba Dateso, me no mududugö mbanua saro andrö khömi!', '["Yer 47:4; Hez 26:27; Amos 1:9,10","SamII 24:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476278, 'OT', 'Yesaya', 23, 15, 'Ba na luo da''ö, ba fitu ngafulu fakhe wa''ara, ba lö itörö tödö niha Diro andrö, sagötö noso razo. Ba na no aefa zi fitu ngafulu fakhe, ba itörö ba Diro andrö wanunö andrö nitandrösaigö ba ndra alawe sohorö-horö [imane]:', '["Sin 84:4"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 16, '"Halö mbiola, törö-töröi newali, yaugö ira alawe sohorö-horö andrö, si lö itörö-törö tödö niha sa''ae! Haogö wolau, forege wanunö, ena''ö ifuli itörö tödö niha ndra''ugö!"', '["Sin 84:4"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 17, 'Na aefa zi fitu ngafulu fakhe, ba ifuli ifaigi Diro andrö Yehowa ena''ö ifuli isöndra luonia ba wohorö-horö andrö, ba ena''ö mohorö-horö ia ba mbanua niha fefu, ba guli danö ma''asagörö.', '["Sin 84:4"]', NULL),
  (3476278, 'OT', 'Yesaya', 23, 18, 'Ba ölönia andrö luonia wohorö-horö, ba ni''amoni''ö khö Yehowa; lö labe''e yaŵa ba lö lahöna; sabönö böli gö a''ine ba böli nukha si sökhi ba zowanua ba gamaudu nahia Yehowa andrö.[3]', '["Sin 84:4"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 1, 'Hiza, ihori nösi guli danö Yehowa ba ise''e zi so yaŵa, tobali dete danö ibe''e, ifazawili zowanua yaŵa.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 2, 'Si mane ba gere göi ba zato, ba he ba zokhö ba he ba zawuyu, he ba zokhö ira alawe ba he ba zawuyu ono alawe, he ba zamawa hadia ia ba he ba zowöli, he ba zamalali ana''a ba he ba zame''e nifalali, he ba zo''ömö ba he ba zosugilö.[1]', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 3, 'Salösu lö ösi guli danö dania, ahori terabu, noa sa''ae Yehowa zanguma''ö.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 4, 'Abu dania dödö guli danö, saleu ia, timba zotufo ilo tou danö, oköli; ba salaŵa niha ba guli danö, ba mate olofo.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 5, 'Noa sa teta''unöi danö barö gahe zowanua yaŵa; me lö ni''o''öra oroisa ba me no lasawö gamakhoita, ba me no faröi ira ba wawu''usa li andrö, si no götö-götö wa''ara.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 6, 'Andrö i''a danö fangelifi ba lalu''i horö sowanua yaŵa; ariri niha ba guli danö ba lö atoto zi tosai niha.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 7, 'Amaedola zabu tödö nösi mbua nagu ba si mate döla; ba dozi somuso tödö mege, ba mangarö-ngarö.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 8, 'Döhö wamözi aramba andrö, sowua-wua dödö niha, tebato wagua-guasa zomuso tödö, ba döhö li mbiola, si no omasiö niha mege.[2]', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 9, 'Lö''ö sa''ae labadu nagu ba wanunö ba afeto duo ba zamadu.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 10, 'No adudu mbanua faya andrö; dozi omo, ba no mukusi mbawandruhö, lö lafa''amöi yomo niha.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 11, 'Mangarö-ngarö niha ba newali, ba nagu andrö; fa''omuso dödö, ba lö''ö sa''ae; fa''asökhi dödö ba guli danö, ba no ahori taya.[3]', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 12, 'Ba mbanua, ba hatö fa''adudu; bawa göli, ba no murasa.', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 13, 'Da''ö sa zi göna uli danö, itörö niha andrö, si mane na lateteu mbua falo, amaedola wangozaragö wo''uwo''u, na no awai wangai bua nagu.[4]', '["Hez 7:12; Hos 4:9","Faigi 16:10; Yer 7:34; 16:9","Fam 18:11 b.t.","Faigi 17:6"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 14, 'Ba ya''ira andrö, ba la''ebua''ö lira wa''iki, lasuno wa''asalaŵa Yehowa tanö ba gaekhula luo [lamane]:[5]', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 15, 'Andrö mifosumange Yehowa, ya''ami si so ba danö tanö ba gatumbukha; ya''ami si hene asi, mifosumange döi Yehowa, Lowalangi Ndraono Gizeraeli!', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 16, 'Moroi ba wondrege danö tarongo wanunö, [lamane]: "Lakhömi ba zatulö tödö!" Ba umane: Itörö ndra''o fökhö! Itörö ndra''o fökhö! Alai ndra''o! Falimo zi falimo andrö, ha sambalö falimosa ba zi falimo andrö!', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 17, 'Ihawui ndra''ugö fa''ata''u, alau''ö ba lösu-lösu ba ba gu''ö, ya''ugö sowanua ba guli danö!', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 18, 'Soloi ba duria gameta''uö andrö, ba alau ba lösu-lösu; ba si falukha fe''amöi yaŵa moroi ba lösu-lösu, ba alau ba gu''ö. Teboka sa zandrela andrö ba mbanua yaŵa ba humeu dayadaya danö andrö.[6]', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 19, 'Asila danö, ofetu, abölö-bölö; aboto danö, fabali; mangiwa danö, humeu.', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 20, 'Managanagaele danö, si mane si mabu, humeu, hulö mbue; abua noronia olalöŵania andrö: alau tou ia, ba wa lö maoso sa''ae.', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 21, 'Ba na luo da''ö, ba ifatörö wotu Yehowa ba zabölö andrö si yaŵa ba mbanua yaŵa ba ba zalaŵa tou ba guli danö.[7]', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 22, 'Tekuru ira ba gohokoho, nifokuru nibe''e ba gurunga, ba tekusi; ba na no ara dania, ba tefaigi zui ira.[8]', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476279, 'OT', 'Yesaya', 24, 23, 'Ba aila mbaŵa ba afusi mbawa luo wa''aila. Yehowa ngahönö andrö sa''ae dania zalaŵa ba hili Ziona ba ba Yeruzalema, ba lakhömi föna nawönia satua.[9]', '["Faigi 12:6","Yer 48:44","Efes 2:9; 6:12; FetII 2:4; Fam 20:1–3","Fam 20:7","Faigi 13:10; Mat 24:29; Fam 21:2"]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 1, 'He Yehowa, Lowalangigu ndra''ugö! Da''u''abölögö wanuno ya''ugö, usuno döimö andrö! Noa sa ölau zahöli-höli dödö; nihonogöi föna sa''ae ba tenga faya, no si ndruhu.[1]', '["Sin 8:2","Sakh 14:14 b.t."]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 2, 'No öbali''ö baho gara mbanua, banua saro, ba no öbali''ö adudula; gödo niha bö''ö andrö, ba tenga banua sa''ae öbe''e; lö''ö sa''ae lafuli lataru''ö.', '["Sin 8:2","Sakh 14:14 b.t."]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 3, 'Andrö lafosumange dania ndra''ugö soi sabölö; la''ata''ufi ndra''ugö banua soi si höndrögö awöra.', '["Sin 8:2","Sakh 14:14 b.t."]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 4, 'Hati sa ndra''ugö ba zi lö töi, hati ba zi numana, na tosasa ira; saŵatö na so deu laöhö, lumö na aukhu zino. Me no amaedola deu laöhö, sangewe ba mbagolö, sa''ae wönu zamalangögö awöra.', '["Sin 8:2","Sakh 14:14 b.t."]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 5, 'Si mane famunu wa''aukhu zino, na no ara lö teu, si manö wamunumö fagua-guasa niha bö''ö andrö; si mane fa''aukhu zino, na haömö, na so lawuo, si manö wa''adöhö wolaya zamalangögö awöra andrö.[2]', '["Sin 8:2","Sakh 14:14 b.t."]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 6, 'Ba ilau gowuloa Yehowa ngahönö andrö, ba hili andrö, fefu soi ikaoni; ihalö öra zatabö, agu si no ara ibe''e nibadu, sotawö gö, nilau uto döla, ba agu si no arara, nihaogö.[3]', '["Sin 22:30; Luk 14:17","Hos 13:14; KorI 15:55; Fam 7:17; 21:4"]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 7, 'Iheta ba hili andrö mba''a-ba''a andrö, ba''a-ba''a soi andrö, fefu, balu-balu andrö, fombalu niha baero, fefu.', '["Sin 22:30; Luk 14:17","Hos 13:14; KorI 15:55; Fam 7:17; 21:4"]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 8, 'Ifakiko wa''amate, si lö mamalö-malö; ba i''osi So''aya Yehowa daŵa horö ba mbawa niha, idozigö, ba taya wa''aila mbanuania andrö, ibe''e, ba guli danö, ma''asagörö; noa sa Yehowa zanguma''ö.[4]', '["Sin 22:30; Luk 14:17","Hos 13:14; KorI 15:55; Fam 7:17; 21:4"]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 9, 'Na luo da''ö, ba lamane: Hiza Lowalangida, sabe''e dödöda i''orifi ita; hiza Yehowa nidöna-dönada fanolo! Ba dama''iki ita, akha omuso dödöda, ba wangorifi andrö khönia!', '["Sin 22:30; Luk 14:17","Hos 13:14; KorI 15:55; Fam 7:17; 21:4"]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 10, 'Ahono sa danga Yehowa ba hili andrö. Ba Iraono Moabi andrö, ba nihundragö tou, ba nahara, nifanguhundra du''u ba golawua so''idanö.', '["Sin 22:30; Luk 14:17","Hos 13:14; KorI 15:55; Fam 7:17; 21:4"]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 11, 'Ba labologö dangara bakha ba da''ö, si mane solangi, na ibologö ba wolangi; ba ihöndrögö wayaŵasara Yehowa, fabaya walimosa dangara andrö.', '["Sin 22:30; Luk 14:17","Hos 13:14; KorI 15:55; Fam 7:17; 21:4"]', NULL),
  (3476280, 'OT', 'Yesaya', 25, 12, 'Öli andrö khömi, si no aro ba si no alaŵa, ba ituli''ö, idudugö, aruru tou ba danö, ibe''e.', '["Sin 22:30; Luk 14:17","Hos 13:14; KorI 15:55; Fam 7:17; 21:4"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 1, 'Na luo da''ö dania, ba lamane wanunö ba danö Ndraono Yuda: "No so khöda mbanua saro! Ibali''ö öli ba ba''a-ba''a wanolonia andrö Yehowa.[1]', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 2, 'Mibokai mbawa göli, ena''ö möi miyomo soi satulö, si lö faröi.[2]', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 3, 'No aro dödö, lö öbulöbulö''ö wangorifi; khöu sa''ae ladöna-döna.', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 4, 'Böi mifamalö-malö wanötöna khö Yehowa; gowe si lö tebulö sa Zo''aya, Yehowa![3]', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 5, 'Noa sa ihöndrögö zowanua ba hili yaŵa; banua andrö si no alaŵa yaŵa, wanimba tou ya''ia, wanudugö ya''ia, irege danö tou.', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 6, 'Ahe zi numana zanguhundra tou, ahe zi lö töi andrö.', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 7, 'Lala zatulö tödö, ba ba zalo''o itörö, adölö lala zadölö tödö, nihaogöu andrö.', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 8, 'Ba lala wanguhukumö andrö, ya''ugö Yehowa, nidöna-dönama mege. Töimö andrö ba fanuno ya''ugö zomasi dödöma.', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 9, 'No humulu dödögu khöu, ba zi bongi; arö dotogu zihuluhulu khöu. Ha si''aikö sa''ae manandrösa ba guli danö wanguhukumö andrö, ba lasöndra lala satulö sowanua ba guli danö.[4]', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 10, 'Ba na falukha wa''ebolo dödö zebua horö andrö, ba lö latöngöni lala satulö, manao horö ira ba danö, ba nilau satulö ena''ö, ba lö lafaigi wa''ebua Yehowa andrö.', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 11, 'He Yehowa! si no mufazaŵa dangau andrö, ba lö la''ila. Ena''ö lanehegö wa''aukhu dödöu ba mbanuau andrö, ba ena''ö aila ira! Ena''ö i''a ira alitö andrö fangohori nudumö andrö!', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 12, 'He Yehowa! ohahau dödöma, öbe''e; noa sa ya''ugö zolau fefu hadia ia khöma.[5]', '["Sin 46:2; 125:4","Sin 118:19","Sin 25:2; Yer 17:7","Sin 119:67; 130:6","Sin 125:5"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 13, 'He Yehowa, Lowalangima! No salaŵa bö''ö zamatörö ya''aga; tenga ha ya''ugö. Ba ya''ugö matehe, töimö andrö.', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 14, 'Si no mate, ba lö ifuli auri; lumö-lumö, ba lö ifuli maoso. Andrö no öfatörö khöra huku ba no öhori ira ba lö''ö manö sa''ae itörö, tödö öbe''e.', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 15, 'No ö''oya''ö niha, ya''ugö Yehowa, no öfolakhömi ndra''ugö, no öfa''ese nola danö fefu.', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 16, 'He Yehowa! na baŵa wamakao, ba no la''alui ndra''ugö; na öfatörö khöra wotu, ba lalau mangandrö.', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 17, 'Si mane sanabina, na no irugi baŵania, na iköröbui ia, na mu''ira-ira, ba wa''afökhö hulu andrö, si manö göi ndra''aga mege, ya''ugö Yehowa, börö ndra''ugö.[6]', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 18, 'No abeto ndra''aga, no maköröbui ndra''aga, ba me no madonoga, ba no angi. Lö ma''ila mafalua wangorifi ba danö, ba tebai alua zowanua ba guli danö.[7]', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 19, 'Ena''ö ifuli auri zi mate andrö khöu; ena''ö ifuli maoso mboto zi mate andrö khögu! Mifaoso, mi''a''iki, ya''ami si no mörö nibalugö tanö, namo haga sa namo andrö khöu ba ifalua yaŵa lumö-lumö tanö andrö.', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 20, 'Ba mi''ae si bakha, ya''ami banuagu, ba mbate''e andrö khömi, ba milazi mbawandruhö furimi! Mibini''ö ami, ha mamö''i hörö wa''ara, irege alö wönu andrö.[8]', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476281, 'OT', 'Yesaya', 26, 21, 'Mangefa sa''ae ba nahania Yehowa, ba wame''e fotu ba zowanua ba guli danö, ba horöra andrö. Ba ifa''ele''ö dania, ndrora andrö tanö, lö''ö sa''ae ibalugö nibunu ba gulinia.[9]', '["Yoh 16:21","Sin 110:3; Luk 20:38; Rom 14:8; Yoh 5:29","KorII 4:17","Mikh 1:3"]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 1, 'Na luo da''ö, ba ilau zi''ölinia Yehowa ba Lewiata andrö, ulö andrö salio foloi, si''ölinia si no abe''e ba si no ebua ba si no abölö, ba ba Lewiata ulö si no mogöŵai ya''ia, ba ibunu mbuaya andrö ba Nilo.', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 2, 'Ba na luo da''ö, ba mi''anunö, nitandrösaigö ba kabu nagu omasiö andrö [mado Gizeraeli], mimane:[1]', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 3, '"Ya''odo, Yehowa, zamaigi-maigi ya''ia; lö aedu''aedu ufatörö khönia nidanö! Bongi ma''ökhö udaro-darogö, fa böi ifaitoisi niha.', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 4, 'Lö''ö sa''ae mofönu ndra''o. Ena''ö na falukhado za''a-sa''a mao ba sai''ö, ba fasöndrado khönia, ahori utunu ena''ö.', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 5, 'Atö na ladöna-döna khögu wanolo, na edöna atulö ira khögu; lö tola lö atulö ira khögu."', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 6, 'Ba dania, ba moŵa''a ma''uwu Yakobo, molehe Ndraono Gizeraeli ba mobowo; anönö guli danö buara labe''e:', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 7, 'Hadia, no ifakao ira si mane famakaonia samakao ya''ira? Ba hadia, no mubunu ira si mane nibunu da''ö?', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 8, 'No öndrohugö wangotu''ö ya''ira fanibo. No i''oloi''ö ira angi sabölö andrö khönia, me luo angi timu.', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 9, 'Andrö wa tesulöni ba da''ö lalö ma''uwu Yakobo andrö, ba da''ö gorudua lua-lua, wameta horöra andrö: labali''ö tuturu gara niboboto fefu gara naha wame''e sumange andrö, ba lö''ö sa''ae maoso Gasera andrö ba adu luo andrö.[2]', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 10, 'Aomö-aomö sa''ae mbanua saro andrö, banua si lö niha, si no muröi, amaedola danö si mate. Mangalui gö ba da''ö nono zaŵi, mörö-mörö ba da''ö ba la''aga''aga lehelehe.[3]', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 11, 'Na no oköli duturunia, ba tefafatö; so ndra alawe, ba lahalö eu galitö. Soi si lö fa''aboto ba dödö sa ira. Andrö lö ihakhösi tödö somböi ya''ia, ba lö ibologö dödö khönia samazökhi ya''ia.', '["Faigi 5:1 b.t.","MozIII 26:30; Faigi 17:8","Faigi 13:19 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 12, 'Na luo da''ö, ba iböbörö ngalai Yehowa, i''otarai Oifarati, numalö ba nidanö Miserayi andrö. Ba ya''ami Iraono Gizeraeli, ba nitutuyu, ni''ozaragö.', '["Faigi 14:1; Sakh 10:8 b.t."]', NULL),
  (3476282, 'OT', 'Yesaya', 27, 13, 'Na luo da''ö, ba telau dorofe sebua andrö, ba dozi si no elungu ba danö Asiria ba si no muzaewe ba danö Miserayi, ba mangawuli ba la''angaröfi li Yehowa ba hili ni''amoni''ö andrö ba Yeruzalema.[4]', '["Faigi 14:1; Sakh 10:8 b.t."]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 1, 'Alai zaembu ana''a andrö si no muhokhaini, ba zi mabu-mabu andrö Iraono Geferayi, awö mbunga saleu andrö, ayara andrö, si sökhi sibai ba högö ndraso andrö, satabö sinanö, daso zi no mabu agu![1]', '["RazI 16:24","RazII 17:5,6"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 2, 'So sa''ae moroi sa zabe''e ba sabölö khö Zo''aya! Hulö na laöhö deu kara, hulö nangi sabölö sibai, hulö deu toho, si nönöi tanö wanimbania tou ya''ira tangania.[2]', '["RazI 16:24","RazII 17:5,6"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 3, 'Ba tobali tehundra-hundra tou zaembu zi mabu-mabu andrö, Iraono Geferayi, si no muhokhaini.', '["RazI 16:24","RazII 17:5,6"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 4, 'Ba bunga saleu andrö, ayara andrö, si sökhi sibai ba högö ndraso andrö, satabö sinanö, ba itörö lala marafala sahulö, na lö irugi baŵa na, nidölö niha femanga, na i''ila, moroi ba danga manö.', '["RazI 16:24","RazII 17:5,6"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 5, 'Na luo da''ö, ba saembu lakhömi ba roto si no maulu Yehowa ngahönö andrö ba zi tosai banuania andrö.', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 6, 'Ba ibe''e wa''atulö dödö ba zanguhuku ba fa''abölö ba zanimba sanuwö ba mbawa göli.', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 7, 'Ba ya''ira andre göi, ba alau-lau ba nagu andrö ba mangiwa ba zi mabu-mabu ita! Ere ba sama''ele''ö, ba alau-lau ba zi mabu niha, no fawuka dödö ba nagu andrö, mukhölökhölö mbanua ba zi mabu niha, alau-lau ba wama''ele''ö andrö, mangiwa ba wangetu''ö huku.', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 8, 'Fefu meza, ba no anönö uta si ta''unö, sambua lö nahia si lö si ta''unö.', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 9, 'Ha niha nifahaönia, ena''ö aboto ba dödö, ba ha khö i''ombakha''ö lala? Hadia, ba zawena aefa famaenu, ba zawena aefa ba mbagi zusu?', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 10, 'Falaete manö sa gamakhoita, falaete manö gamakhoita; fatete manö ndrali, fatete manö ndrali; ba da''e ma''ifu ba ba da''ö ma''ifu."', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 11, 'Ya''ia! Ilau ba niha andre li si tebai alua ba mbewe, li Ndrawa bö''ö.[3]', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 12, 'Ya''ia, si no manguma''ö khöra: Da''e naha wolombase, mifolombase zerege tödö, ba da''e naha wangokafu tödö! Ba lö edöna ira mamondrongo.', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 13, 'Ba si mane sa''ae li Yehowa khöra: Falaete manö gamakhoita; falaete manö gamakhoita; fatete manö ndrali; fatete manö ndrali; ba da''e ma''ifu ba ba da''ö ma''ifu, ena''ö alau ira ba lala, ena''ö arasa döla, ena''ö tokhai gahe, ena''ö tera''u ira.', '["MozV 28:49; KorI 14:21"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 14, 'Andrö mifondrondrongo li Yehowa, ya''ami sango''aya, ya''ami samatörö soi andre ba Yeruzalema!', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 15, 'Me no miŵa''ö: No fawu''u li ndra''aga ba wa''amate, ba ba mbanua tou andrö, ba no mafataro zamaigi-maigi? Na itörö molö famakao, ba lö irugiga. Noa sa mabe''e sawatöma waya ba ba''a-ba''a khöma walimosa!"', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 16, 'Andrö imane Yehowa, So''aya: Hiza, no ube''e tou gowe dayadaya ba Ziona, gowe si no mutandraigö, gowe toyo ba watalinga sebua böli, saro dayadaya. Samati, ba alakha lö moloi.[4]', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 17, 'Ba ube''e dali wa''adölö, ba fanulo wa''atulö. Saŵatömi faya andrö, ba irasa teu kara ba ba''a-ba''a andrö khömi, ba ihanigö molö.', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 18, 'Ba fawu''usa li andrö khömi ba wa''amate ba nibunu [ba zura] ba hadia niŵa''ömi ba mbanua tou, ba si lö boto. Na itörö molö famakao andrö, ba imama ami.', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 19, 'Ero na itörö, ba ikhamö ami; ero mahemolu sa''ae itörö, he ba zi ma''ökhö, ba he ba zi bongi, ba ha sambalö fehokha mbu wamahaö da''ö.', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 20, 'Sambö fa''anau sa''ae dania gaso, tobali tebai mifadölö ami, ba sabölö ide-ide gambala, fa tebai mibalugö ami.', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 21, 'Maoso sa''ae dania Yehowa, si mane ba gahe hili Werasi, si mane ba ndraso no ba Gibeona wönunia dania, ba wolau nilaunia — hulö zi lö tarai mila wolaunia andrö! — ba ba wangai nihalönia — sahöli-höli dödö halöŵönia andrö![5]', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 22, 'Andrö böi mango''aya ami, fa böi tedou wa''aro mböbö andrö khömi; noa sa urongo khö Zo''aya, Yehowa ngahönö andrö, wa no muhonogöi wangohori, nifatörö ba guli danö ma''asagörö.[6]', '["Rom 9:33; FetI 2:6; Faigi 8:14","Yos 10:10; SamII 5:20; Nga''ötI 14:11","Faigi 10:23"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 23, 'Mibe''e mbörö dalingami ba mifondrondrongo ligu! Mitöngöni ba mifondrondrongo huhuogu!', '["Sin 86:10; Yer 32:19"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 24, 'Hadia, adölö manö sinanö dania? Hadia ha sambalö famali''ö tanö ba famoboto ba nowi?', '["Sin 86:10; Yer 32:19"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 25, 'Hadia, tenga si mane? Na no ihaogö danö, ba ifazaewe lönga ba höwa ba ifa''oli wakhe, awö rigi ba danö si no mundrohugö, ba rigi ö manu ba zinga hinölu?', '["Sin 86:10; Yer 32:19"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 26, 'No Lowalanginia zangoroma''ö khönia satulö lala, wamahaö ya''ia.', '["Sin 86:10; Yer 32:19"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 27, 'Tenga kureta famöbörö wamöbörö lönga ba lö lafatörö gaolo gureta ba höwa; famöbörö lönga, ba si''o, ba famöbörö höwa, ba ono geu.', '["Sin 86:10; Yer 32:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476283, 'OT', 'Yesaya', 28, 28, 'Böra andrö, ba hadia, nimama? Tenga nimama; lö''ö sa iböbörö manö wamatörö kureta, awö kudo: tenga nimama!', '["Sin 86:10; Yer 32:19"]', NULL),
  (3476283, 'OT', 'Yesaya', 28, 29, 'Moroi khö Yehowa ngahönö andrö da''ö göi! Sahöli-höli dödöda wamolalania hadia ia, ba no abölö sibai wa''atua-tuania.[7]', '["Sin 86:10; Yer 32:19"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 1, 'Alai ndra''ugö, ya''ugö Arieli! Arieli banua ba nibe''e Dawido nahiania. Mifatohu ndröfi; na ituo wunia, na no fatutu mbaŵa gowasa andrö,[1]', '["Hez 43:15","Luk 19:43 b.t.","Yob 21:18; Sin 1:4","Faigi 37:33–37"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 2, 'ba usasagö Garieli andrö, irege tesao wege-ege ba fangarö-ngarö, ba tobali Arieli ia khögu!', '["Hez 43:15","Luk 19:43 b.t.","Yob 21:18; Sin 1:4","Faigi 37:33–37"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 3, 'Ba ufa''u''u ndra''ugö, ufasui ndra''ugö nahiagu andrö; ufera''ö ndra''ugö fari ba ube''e mba''a-ba''a zanuwö ba gamaudumö.[2]', '["Hez 43:15","Luk 19:43 b.t.","Yob 21:18; Sin 1:4","Faigi 37:33–37"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 4, 'Ena''ö moroi ba danö tou muhede ndra''ugö, moroi ba gawu-gawu tou terongo liu; ena''ö hulö li mbekhu moroi tou barö danö limö, ba hulö zi fangöngö-ngöngö moroi tou ba gawu-gawu huhuomö.', '["Hez 43:15","Luk 19:43 b.t.","Yob 21:18; Sin 1:4","Faigi 37:33–37"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 5, 'Ba fa''ato nemaliu andrö, ba timba ngawua nene, ba fa''ato zamakao ya''ugö, ba timba ndrami wakhi sihombo ba nangi; ba i''ogomuzaö, lö mudonadona.[3]', '["Hez 43:15","Luk 19:43 b.t.","Yob 21:18; Sin 1:4","Faigi 37:33–37"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 6, 'Ifatörö Yehowa ngahönö andrö we''ugu-ugu mbanua ba siheu ba fa''ofetu, ba angi sabölö ba teu laöhö ba hola-hola galitö si manga-manga hadia ia.', '["Hez 43:15","Luk 19:43 b.t.","Yob 21:18; Sin 1:4","Faigi 37:33–37"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 7, 'Ba lala ba wangifi, lala ni''ilada ba zi bongi dania lala soi andrö fefu, sanuwö Arieli andrö, ha wa''ato ira, dozi si möi manuwö ya''ia, banua saro andrö ba hili, dozi sanasagö ya''ia.', '["Hez 43:15","Luk 19:43 b.t.","Yob 21:18; Sin 1:4","Faigi 37:33–37"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 8, 'Ba hulö na so zangifi manga ia, ba na tokea ia, ba lö tebulö wa''olofo — ba hulö zowökhi tödö na mangifi ia ibadu nidanö, ba na tokea ia, ba serege tödö ia, ba lö mamalö-malö wa''otufo bakha lela — si manö dania soi andrö fefu, ha wa''ato ira, sanuwö hili Ziona andrö.[4]', '["Hez 43:15","Luk 19:43 b.t.","Yob 21:18; Sin 1:4","Faigi 37:33–37"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 9, 'Ya atöngö ami, ya ahöli-höli dödömi! Ya tobalu hörömi, ya lö mi''ila niha! No mabu ira, ba tenga si mabu agu; mangiwa ira, ba tenga ba zi mabu niha.', '["Rom 11:8","Hez 33:31; Mat 15:8,9","Mat 11:25; KorI 1:19","Sin 94:7; Hez 8:12","Faigi 45:9; Rom 9:20"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 10, 'Me no ilau khömi Yehowa Geheha wemörö sabe''e, ba me no iduhö hörömi andrö, sama''ele''ö andrö, ba me no ibalugö högömi, sangi''ila andrö.[5]', '["Rom 11:8","Hez 33:31; Mat 15:8,9","Mat 11:25; KorI 1:19","Sin 94:7; Hez 8:12","Faigi 45:9; Rom 9:20"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 11, 'Ba fefu wama''ele''ö da''ö no mege, ba hulö daroma li, si so ba zura, si no mufotandro, khömi, na labe''e ba zangila mombaso sura ba na lamane khönia: Baso we! Ba imane: Tebai ubaso, me no mufotandro!', '["Rom 11:8","Hez 33:31; Mat 15:8,9","Mat 11:25; KorI 1:19","Sin 94:7; Hez 8:12","Faigi 45:9; Rom 9:20"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 12, 'Ba na labe''e ba zi lö mangila mombaso sura zura andrö, ba na lamane khönia: Baso we! Ba imane: Lö u''ila ubaso zura!', '["Rom 11:8","Hez 33:31; Mat 15:8,9","Mat 11:25; KorI 1:19","Sin 94:7; Hez 8:12","Faigi 45:9; Rom 9:20"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 13, 'Ba imane So''aya: Me lahatö''ö ira bawara niha andre ba me lafosumange ndra''o bewera ba me no aröu khögu dödöra ba me ha sambalö amakhoita niha, nitöngönira, wawangata''ufira Lowalangi.[6]', '["Rom 11:8","Hez 33:31; Mat 15:8,9","Mat 11:25; KorI 1:19","Sin 94:7; Hez 8:12","Faigi 45:9; Rom 9:20"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 14, 'andrö wa ba zahöli-höli dödö niha ufatörö soi andre, zamuza tö, ba zahöli-höli dödö ba ba zi lö larai mila, ena''ö taya wa''atua-tua andrö ba zatua-tuara, ba ena''ö tobini wa''onekhe ba zonekhera.[7]', '["Rom 11:8","Hez 33:31; Mat 15:8,9","Mat 11:25; KorI 1:19","Sin 94:7; Hez 8:12","Faigi 45:9; Rom 9:20"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 15, 'Alai zamorege famini''ö khö Yehowa tödöra, solau ba zagömi-gömi nilaura, sanguma''ö tödöra: Ha niha zanehe, ha niha zangila ya''aga?[8]', '["Rom 11:8","Hez 33:31; Mat 15:8,9","Mat 11:25; KorI 1:19","Sin 94:7; Hez 8:12","Faigi 45:9; Rom 9:20"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 16, 'Alai wa''atefuyu dödömi! Ma tola tefaomagö ira la''uri zamöbözi bowoa? Fa tola iŵa''ö niwöwoi ba khö zomböi ya''ia: Tenga niwöwöinia ndra''odo! ba ma fa tola iŵa''ö bowoa khö zamöbözi ya''ia: Lö i''ila watahögö hadia ia![9]', '["Rom 11:8","Hez 33:31; Mat 15:8,9","Mat 11:25; KorI 1:19","Sin 94:7; Hez 8:12","Faigi 45:9; Rom 9:20"]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 17, 'Hadia, tenga hatö ma''ifu tö, fa tobali kabu zinanö hili Libano, awö wa atua kabu zinanö, taŵa''ö.', '[]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 18, 'Na luo da''ö, ba larongo safiso daroma li si so ba zura, ba i''ila niha hörö zau''a, moroi ba wa''atebalu, moroi ba zogömi-gömi.', '[]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 19, 'Ba sebua famakao, ba ifuli omuso dödö ba khö Yehowa, ba fondrege zi numana ba niha, ba owua-wua dödö ba khö Ni''amoni''ö Ndraono Gizeraeli andrö.', '[]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 20, 'Lö''ö sa''ae samakao dania, ba nihori zango''aya, ba dozi samakhai si lö atulö mege, ba no ahori,', '[]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 21, 'samowöhö niha ba zi lö atulö, na so huhuo, solau fesu ba zolohe ba lala, ba mbawa göli, sangöhöndrögö si lö horö faya andrö.', '[]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 22, 'Andrö imane Yehowa, sangorifi Aberahamo no, ba khö Yakobo: Lö''ö sa''ae te''ailasi dania Yakobo ba lö''ö sa''ae afusi mbawania.', '[]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 23, 'Ba na i''ila dania — ma''uwunia andrö — nilau dangagu khönia, ba la''amoni''ö sa''ae döigu andrö; la''amoni''ö Ni''amoni''ö Yakobo andrö ba la''ata''ufi Lowalangi Ndraono Gizeraeli andrö.', '[]', NULL),
  (3476284, 'OT', 'Yesaya', 29, 24, 'Si no elungu tödö mege, ba lasöndra wa''aboto ba dödö, ba si fabalö mege, ba latöngöni wamahaö.', '[]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 1, 'Imane Yehowa: Alai ndraono andrö, si no abe''e tandro, samagölösi hadia ia zi tenga moroi khögu, si fawu''u li si lö omasido ba wamalaete horö!', '["Yer 37:7; Hez 17:15","Faigi 19:11","Yer 2:36","Faigi 51:9; Sin 87:4"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 2, 'Si möi misi tou ba danö Miserayi ba lö musofu li khögu, ba wangai fangabe''era fanolo Wara''o andrö ba ba wangalui saŵatö ba lumö Ndrawa Miserayi.[1]', '["Yer 37:7; Hez 17:15","Faigi 19:11","Yer 2:36","Faigi 51:9; Sin 87:4"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 3, 'Ba tobali fangabu dödö khömi wanolo Wara''o andrö ba fangaila dania zaŵatö andrö ba lumö Ndrawa Miserayi.', '["Yer 37:7; Hez 17:15","Faigi 19:11","Yer 2:36","Faigi 51:9; Sin 87:4"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 4, 'He ŵa''ae ba Zoana so gumandrunia, ba he ba Hanesi larugi sinengenia,[2]', '["Yer 37:7; Hez 17:15","Faigi 19:11","Yer 2:36","Faigi 51:9; Sin 87:4"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 5, 'dozi falukha wangabu dödö, ba niha si lö guna khöra; tenga sanolo ba tenga soguna, ha sambalö fangabu dödö ba fangaila.[3]', '["Yer 37:7; Hez 17:15","Faigi 19:11","Yer 2:36","Faigi 51:9; Sin 87:4"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 6, 'Nitandrösaigö ba zaliŵa-liŵa ba danö andrö si raya: Latörö danö si fahöna fa''atosasa ba fa''ata''u, singo si matua ba singo si alawe ba ulö ba naga sihombo latörö wolohe si so khöra, ba hulu galide, awö girö-giröra ba gebu gondra, la''ohe ba niha si lö guna khöra.', '["Yer 37:7; Hez 17:15","Faigi 19:11","Yer 2:36","Faigi 51:9; Sin 87:4"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 7, 'Fanolo Ndrawa Miserayi andrö, ba faya ba si lö boto. Andrö ube''e töinia: "Si döfa bawa ba si lö liŵa-liŵa."[4]', '["Yer 37:7; Hez 17:15","Faigi 19:11","Yer 2:36","Faigi 51:9; Sin 87:4"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 8, 'Ba iada''e, ba ae yomo; tanö ba zura khöra, fazökhi zura, famaduhu''ö ba götö dania si lö tebulö![5]', '["MozV 31:19"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 9, 'Niha sabe''e tandro sa''ae ira, ono matua si falimolimo, iraono si lö edöna mamondrongo nifakhoi Yehowa.', '["MozV 31:19"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 10, 'Sanguma''ö ba zangi''ila andrö: "Böi ya mi''ila hadia ia;" ba ba zama''ele''ö andrö: "Böi mifa''ele''ö khöma zi duhu andrö. Mi''ombakha''ö khöma zomasiga, ba mifa''ele''ö khöma waya-faya!', '["MozV 31:19"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 11, 'Miröi lala, mihole''ö ami, miböhöi nitörö andrö, böi mifarongogö khöma Ni''amoni''ö Ndraono Gizeraeli andrö."', '["MozV 31:19"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 12, 'Andrö imane Ni''amoni''ö Ndraono Gizeraeli andrö: Me no mi''ositengagö niŵa''ö andrö, ba me no abe''e dödömi ba wa''atefuyu ba ba walimosa, me no ba da''ö midöna-döna,', '["MozV 31:19"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 13, 'andrö ya hulö zabökha khömi golalöŵa andrö, hulö zabökha ba göli kara salaŵa, si tugu eŵaŵa, böröta wa''adudu, si saŵa fa''adudu si lö mudöna-döna, si ha mamö''i hörö fa''ara dania.', '["MozV 31:19"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 14, 'Ba irasa sa''ae dania, si mane na larasa mbowoa tanö, nirasa manö, lö alimagö, irege sambua lö tuga lawunia si tola fanou mbo galitö bawu, ba ma fanou nidanö ba mba''a.', '["MozV 31:19"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 15, 'Noa sa imane So''aya Yehowa, Ni''amoni''ö Ndraono Gizeraeli andrö: Na mifalalini ena''ö huku ba na mihonogö ami, ba falukha ami wangorifi; ba wa''ahono-hono ba ba wanötöna so wa''abe''emi!', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 16, 'Ba lö sedöna ami. No mimane: "Tenga ya''ia! damafandruo kudoma!" — Andrö ya soloi ami dania! ba: "Ma''okudo zalio ahe!" — andrö ya fagohi zolohi ya''ami![6]', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 17, 'Ha samösa zi''ao, ba hönö ami, soloi; dalima zi''ao, ba moloi ami fefu, erege hulö döla geu nitaru''ö ba hili zi tosai, ya''ami, hulö mandrera ba zuzu hili-hili.[7]', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 18, 'Andrö ifogasa Yehowa wangebua tödö khömi, andrö wa ahou dödönia wangahakhösi tödö ya''ami. Lowalangi ba wa''atulö sa Yehowa. Ya ahowu dozi sanötöna khönia![8]', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 19, 'Ba ya''ami banua Yeruzalema, ba hili Ziona andrö: Tenga ha sambalö fege-ege khömi; ihakhösi tödö sa ami, ba wangarö-ngarömi andrö, na irongo, ba i''o''ö khömi.', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 20, 'Ibe''e sa khömi So''aya gö ba wa''atosasa ba idanö ba wamakao, ba lö''ö sa''ae labini''ö ira samahaö ya''ami, hörömi sa''ae zangila samahaö ya''ami andrö.', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 21, 'Ba tögi dalingami zamondrongo li zanguma''ö moroi furimi: "Da''ö lala, mitörö ia!" — na mihole''ö ami ba gambölö, ba ma ba gabera.', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 22, 'Ba mi''o''aya sa''ae nadumi andrö, nifo''uli firö, awö wamaedo andrö khömi, nifahele, nifo''uli ana''a. Mitibo''ö dania, nifanibo sogoro ita, mimane: "Labu''ögö!"', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 23, 'Ba ibe''e dania deu ba zinanömi ba nowimi, ba ömi andrö, bua nowi, ba fangabe''emi, mo''ösi. Ba mangalui gö gurifömi, na luo da''ö, ba mbenua sebolo.[9]', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 24, 'Saŵi andrö ba kalide, solului halöŵö ba nowi, ba la''a gö nifaruka, nilau asio, ba si no muböbörö ba si no mutafi''ö ba niru.', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 25, 'Fefu hili salaŵa ba hili-hili salaŵa fefu, ba mombombo, mo''idanö sebua, na luo wamunu sebua andrö, na adudu malige andrö.[10]', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 26, 'Ba haga mbaŵa, ba si mane haga luo, ba haga luo, ba mewitu fa''abölö föna, si mane na orudu haga zi fitu ngaluo, na idalu-daluni wökhö mbanuania andrö Yehowa, na ifadöhö zesokho ira.', '["RazII 25:4","MozIII 26:36; MozV 32:30","Sin 2:12; Amaed 16:20; Yer 17:7","Faigi 32:15–20","Faigi 34:1–4; Yoel 3:18; Amos 9:13"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 27, 'Hiza wa''ato''ele Yehowa moroi ba zaröu; humola wönunia, lawuo salu moroi tou. Fawukhö gilo ba wa''abao dödö, ba lelania, ba no hulö hola-hola galitö, si manga-manga hadia ia.', '["Faigi 8:8; TesII 2:11","MozV 16:16","Sin 50:3","MozII 15:20","RazII 23:10; Mat 25:41"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 28, 'Amaedola nidanö, si nönöi daso, si falaŵa bagi, hanu-hanunia andrö. Ba wanafi''ö niha baero ba niru famakiko, fesu famaelungu ba zimbi soi niha.[11]', '["Faigi 8:8; TesII 2:11","MozV 16:16","Sin 50:3","MozII 15:20","RazII 23:10; Mat 25:41"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 29, 'Ba sanunö ami, si mane ba zi bongi, na tefobörö gowasa; somuso tödö ami, si mane si möi misi yaŵa, solau-lau surune, we''amöi ba hili Yehowa andrö, mangondrasi gowe Ndraono Gizeraeli andrö.[12]', '["Faigi 8:8; TesII 2:11","MozV 16:16","Sin 50:3","MozII 15:20","RazII 23:10; Mat 25:41"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 30, 'Ifarongogö Yehowa linia andrö, sabölö sibai ba ifa''ila''ö dangania, ni''oro''ö mitou, awö wönu so''otu, ba hola-hola galitö, si manga-manga hadia ia, ba fao nangi sabölö ba teu laöhö ba teu kara.[13]', '["Faigi 8:8; TesII 2:11","MozV 16:16","Sin 50:3","MozII 15:20","RazII 23:10; Mat 25:41"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 31, 'Ba tokea sa''ae Ndrawa Asiria ba we''ugu-ugu mbanua andrö khö Yehowa, na ilau zi''onia andrö.', '["Faigi 8:8; TesII 2:11","MozV 16:16","Sin 50:3","MozII 15:20","RazII 23:10; Mat 25:41"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 32, 'Ba ero na itörö bözi-bözi fotu andrö, nifatörö Yehowa khöra, ba fao wamözi aramba ba folau biola; ifaligoi dangania wanuwö ya''ira.[14]', '["Faigi 8:8; TesII 2:11","MozV 16:16","Sin 50:3","MozII 15:20","RazII 23:10; Mat 25:41"]', NULL),
  (3476285, 'OT', 'Yesaya', 30, 33, 'Noa sa ihönagö i''asiwai ganunua! Ya''ia göi ni''asiwai khö razo. Abakha ba ebolo mbaho geu khönia, no fahöna galitö, awö geu! Hanu-hanu Yehowa zanunu ya''ia, hulö zahele talö balera.[15]', '["Faigi 8:8; TesII 2:11","MozV 16:16","Sin 50:3","MozII 15:20","RazII 23:10; Mat 25:41"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 1, 'Alai zi no möi misi tou ba danö Miserayi, ba wangalui fanolo ba ba wame''e we''e-we''e dödöra kudo ba wanuwö; sanötöna ba gureta, me no oya, ba ba zi fakudo, me no ato, ba si lö manöngöni Ni''amoni''ö Ndraono Gizeraeli andrö ba si lö manofu li Yehowa.[1]', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 2, 'Ba ya''ia, ba no satua-tua göi, ba no ifatörö wa''ate''ala. Lö iwu''ai daroma linia ba maoso sa''ae ia, ba wolau ba mbanua zamazökhi si lö sökhi andrö ba ba wanimba fanolo zolalö andrö.', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 3, 'Niha sa Ndrawa Miserayi andrö, ba tenga Lowalangi: Ösi kudo kudora andrö ba tenga bekhu. Andrö tetaru mbagi zanolo andrö, na i''oro''ö dangania Yehowa, ba salau nitolo andrö, ba faoma tekiko ira, dozi ira.[2]', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 4, 'Noa sa imane khögu Yehowa: Si mane singo, ono zingo, sindröndröndröndrö ba nira''unia — no ato gubalo, nifatenge ba wamunu ya''ia, ba lö tokea ia ba we''aora, ba lö ba dödönia wa''ebu''a lira — si manö göi Yehowa ngahönö andrö, we''amöi mitou ba wanuwö ba hili Ziona andrö, ba hili-hili andrö khönia.', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 5, 'Ifoba''a-ba''a dania Yeruzalema Yehowa ngahönö andrö, hulö wofo, sanahanahae [yaŵa gazuninia] ifoba''a-ba''a ba i''orifi; alimagö khönia ba i''efa''ö.[3]', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 6, 'Mifuli ami ba zi no fabali sibai ami, ya''ami Iraono Gizeraeli!', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 7, 'Na luo da''ö, ba dozi latibo''ö sa''ae nadu firö, awö nadu ana''a khöra, nifazökhimi tangami, wamazökhi horö.[4]', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 8, 'Ba tenga si''öli niha wamakiko Ndrawa Asiria andrö, tenga si''öli niha zi manga ya''ira; ba soloi ira, ba zi''öli andrö, ba tobali sawuyu zabölöra andrö.', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476286, 'OT', 'Yesaya', 31, 9, 'Ba sariri gowera andrö, ba wa''ata''u, ba si tokea zalaŵara ba mandrera, iŵa''ö Yehowa, si so alitö ba hili Ziona ba si so farikhi ba Yeruzalema.[5]', '["Sin 20:8","Yer 17:5; Sakh 4:6","Mos. V. 32:11","MozI 35:2; Faigi 2:20","Faigi 29:1"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 1, 'Ba dania, ba so razo satulö huku ba kumandru andrö, ba ba lala sadölö lafatörö fefu hadia ia.[1]', '["Sin 45:8; 72:1; Sakh 9:9"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 2, 'Ba dozi ira, ba amaedola zaŵatö, na so nangi ba amaedola nöu, na teu laöhö ba amaedola mbombo, na no ara lö teu ba amaedola lumö gara hili, ba danö si no oköliköli.', '["Sin 45:8; 72:1; Sakh 9:9"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 3, 'Tenga sa''ae si balunö hörö zamaigi ba labe''e sa''ae mbörö dalingara samondrongo li.', '["Sin 45:8; 72:1; Sakh 9:9"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 4, 'Tödö zi lö tödö mege, ba isöndra lala, ba ba lela zangöhöna li mege ba ahele ni''ilada eluaha.', '["Sin 45:8; 72:1; Sakh 9:9"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 5, 'Ba lö''ö sa''ae lafotöi salaŵa zi lö tödö; ba he si falimo, ba lö lafotöi sebua.', '["Sin 45:8; 72:1; Sakh 9:9"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 6, 'Si lö tödö, ba falötödö wehedenia, si lö sökhi ifakhai tödönia, ba wolau si lö atulö ba ba wehede si fakuyu ba khö Yehowa, ba wa lö mame''e gö ba zolofo ba ba wa lö mame''e idanö ba zowökhi tödö.', '["Sin 45:8; 72:1; Sakh 9:9"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 7, 'Si falimo, ba i''oguna''ö wakake si lö sökhi, ifakhai zi lö atulö, ena''ö ifakiko zebua famakao huhuo falimosa, he no satulö wehede zi numana andrö.', '["Sin 45:8; 72:1; Sakh 9:9"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 8, 'Ba si ndruhu salaŵa, ba era-era sadölö gera-erania, ba lö iböhöi zadölö niha si manö.', '["Sin 45:8; 72:1; Sakh 9:9"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 9, 'Ya''ami ira alawe si lö abu tödö! Mifaoso, mifondrondrongo ligu! Ya''ami ono alawe si no ahono-hono! Mibe''e ba dödömi wehedegu andre![2]', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 10, 'Ya alu-alua ndröfi na, ba ya numalö na mbaŵa, ba tokea ami, ya''ami si lö abu tödö iada''e! Lö''ö sa''ae fangozaragö bua nagu ba lö''ö sa''ae alua wangai bua geu andrö.', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 11, 'Ya tokea ami, ya''ami si no ahono-hono! Ya humufa ami, ya''ami si lö abu todö! Miheta nukhami, mibe''e tou; mi''olembe lembe ba wa''abu dödö.', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 12, 'Labözi dania dotora ba nowi omasiö andrö ba ba nagu andrö, sabölö bua.', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 13, 'Sa''a-sa''a mao ba sai''ö zalua dania ba nowi mbanuagu andrö, ba irege ba dete nomo omasiö fefu, ba mbanua sowua-wua dödö niha mege.', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 14, 'Si lö niha dania gödo misa ba si lö nini-nini sa''ae yomo ba mbanua. Hili-hili andrö ba malige naha zanaro, ba amaedola dögi narö hili dania, götö wa''ara dania, omasiö galide ndru''u; modu''u, ö göröbao.', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 15, 'Irege telau khöra Geheha moroi yaŵa, ena''ö tobali kabu zinanö danö si mate andrö ba ena''ö hulö gatua kabu zinanö andrö wamaigida.[3]', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 16, 'Fa monahia wa''adölö ba danö si mate andrö ba fa ahono wa''atulö ba kabu zinanö no mege.', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 17, 'Ba lua-lua wa''atulö andrö, ba fa''ohahau dödö, ba bua wa''atulö, ba fa''ahono-hono ba fa lö hadia ia, götö wa''ara dania.', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 18, 'Ba mowanua mbanuagu ba nomo wa''ohahau dödö, ba nomo sabe''e dödöda ba ba golombaseŵa si lö hadia ia.[4]', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 19, 'Ba aekhu ba danö deu kara ba wa''aso''a gatua andrö, ba wa''adudu tou mbanua.', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476287, 'OT', 'Yesaya', 32, 20, 'Ya ahowu ami, ya''ami sanaru ba mbewe nidanö misa fefu, ya''ami si dudu fefu gofu heza saŵi ba kalide!', '["Faigi 3:16","Faigi 29:17; Yoel 2:28; HalZin 2:17","Yer 33:16"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 1, 'Alai ndra''ugö dania, ya''ugö zanudugö banua ba si lö mududugö banua na! Ya''ugö si falimo, ba si lö''ö na mulimo! Na no awai khöu wanudugö banua, ba nidudugö göi mbanuau; na no a''ozu khöu walimosa andrö, ba lalimo göi ndra''ugö.[1]', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 2, 'He Yehowa, hakhösi tödö ndra''aga! Khöu madöna-döna! Ena''ö na bagi mbulökhama ndra''ugö, ero mahemolu mbanua! Ba ena''ö na fangorifima ndra''ugö, na baŵa wamakao!', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 3, 'Ba wa''abölö we''ugu-ugu moloi soi niha, ba wa''ebuamö zumawili niha baero.', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 4, 'Ba mi''ozaragö zi toröi furi [gama-gama] nifangozaragö larewe; lafahulö si mane famahulö dolutolu.[2]', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 5, 'Ba salaŵa Yehowa; ba zalaŵa yaŵa so nahania: fahöna huku si sökhi ba fa''atulö ba Ziona, ibe''e.', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 6, 'Götö wa''asökhi dania khömi, si lö hadia ia; fa''atua-tua ba fa''aboto ba dödö ba fangorifi, ba fahöna dania, ba amaedola girö-giröra wangata''ufi Yehowa.', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 7, 'Mangarö-ngarö tou zabölö; mege-ege sibai zinenge andrö, si no möi mangandrö fa''atulö.[3]', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 8, 'Lö niha ba lala, molombase zikoli! No falimo ia ba wawu''usa li andrö; no ifakao mbanua, no lö ba dödönia niha.[4]', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 9, 'Sabu tödö danö, aleu zinanö, saila hili Libano, mate yaŵa geu; salo''o ba Zarona andrö, ba no hulö danö si mate; atoru mbulu geu ba Mbazana ba ba hili Garemeli.', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 10, 'Ba imane Yehowa: Maoso sa''ae ndra''o, ufaosodo sa''ae, muzizio sa''ae ndra''odo.[5]', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 11, 'Manabina ami du''u soköli ba mi''adonogö duhe wakhe; fabötusami andrö, ba no alitö, si manga-manga ya''ami.[6]', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 12, 'Ba tetunu soi niha nifanunu betua, hulö za''a-sa''a mao ni''eŵa, nitunu ba galitö.', '["Mat 7:2","Yoel 2:9","SamII 23:20","RazII 18:17","Fam 14:11; 19:3","Sef 2:14; Fam 18:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476288, 'OT', 'Yesaya', 33, 13, 'Mifondrondrongo, ya''ami saröu, hadia nilaugu, ba ya aboto ba dödömi, ya''ami sahatö, wa''abölögu andrö!', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 14, 'Tokea zamazökhi horö andrö ba Ziona, ihawui zolau si lö sökhi fanizi-nizi. Lamane: "Ha niha khöda zangila so ba zinga galitö, si manga-manga hadia ia? Ha niha khöda si tola mangiagö ngai zi lö tebulö hola-hola?"[7]', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 15, 'Sanörö lala satulö, ba solau si duhu, sangogorofi hare nisöndra ba wamakao niha bö''ö, sanuzu tödö femanga gana''a, sondruhö tögi dalingania, fa böi irongo na tefagölösi wange''e, samakifu hörönia, fa böi terou dödönia ba zi lö sökhi, na i''ila ena''ö.[8]', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 16, 'Da''ö dania zonahia ba zalaŵa yaŵa; saŵatönia hati saro ba gara ba hili; tebe''e khönia mbalazonia ba lö ogo''ö gönia idanö.', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 17, 'I''ila dania razo andrö ba lakhöminia höröu; tanö sebolo misa i''ila.[9]', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 18, 'I''angeragö dania mbaŵa wamakao andrö tödöu, ba ömane: "Hezo zangerai ana''a mege? hezo zanulo andrö? hezo zangerai malige mege?"', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 19, 'Niha safaito andrö, ba lö''ö sa''ae ö''ila, niha andrö solau li si lö ta''ila eluaha, si lö aboto ba dödöda, niha saelo lela, si lö tasöndra aekhula wehede.', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 20, 'Faigi Ziona andrö, banua gowasa khöda! I''ila höröu Yeruzalema andrö, nahia sahono ita, si lö hadia ia, ose, si lö tebulö, si lö tedeha taru-taru, irugi zi lö aetu, si lö aetu sinali fefu.[10]', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 21, 'So sa ba da''ö zi so lakhömi Yehowa andrö, fangorifida, hulö na no tefasui ita idanö sebua, sabölö hohou ba si no ebolo, si lö owo nisola ba si lö owo sebua, sanörö.', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 22, 'Yehowa sa''ae zanguhuku ya''ita, Yehowa zamatörö ya''ita, Yehowa zalaŵada, ya''ia zangorifi ya''ita.', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 23, 'No alulu zinali khöu, no tenga fangabe''e döla loyo ba tenga famadölö loyo! Ba ba da''ö tefosasi nirabu, fahöna manö, irege zombuyu-mbuyu töla, ba lakhamö nirabu, si fahöna.', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476288, 'OT', 'Yesaya', 33, 24, 'Ba samösa lö ba mbanua sanguma''ö: No gönado safökhö khögu. Niha si so ba da''ö, ba no si falukha fangefa horö.[11]', '["MozV 4:24; 9:3; Heb 12:39","Sin 15; 24:4","Sin 45:3","Sin 125:1","Yer 31:34"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 1, 'Mi''aine, ya''ami niha baero, mifondrondrongo; mibe''e mbörö dalingami, ya''ami soi bö''ö! Yamufondrondrongo uli danö ba ösinia; olia uli danö, awö fefu hadia ia zauri yaŵa!', '["Mat 24:29; FetII 3:10; Fam 6:13,14"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 2, 'Noa sa abao dödö Yehowa ba niha fefu, ha soi ira; mofönu ia ba zanuwö, fefu; no i''elifi ira ba no ilulu ira nibunu.', '["Mat 24:29; FetII 3:10; Fam 6:13,14"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 3, 'Ena''ö so manö tou nibubunu andrö khöra, ena''ö aböu tou mboto zi mate ba ena''ö ombuyu danö ba hili ba ndrora andrö.', '["Mat 24:29; FetII 3:10; Fam 6:13,14"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 4, 'Adudu nösi mbanua si yaŵa, tegölugö mbanua, hulö zura; ariri nösinia fefu, si mane fa''aleu mbulu nagu, si mane bulu lehu ba marafala.[1]', '["Mat 24:29; FetII 3:10; Fam 6:13,14"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 5, 'Noa sa mabu ba zorugo zi''öligu; ba numalö mitou ba Ndraono Gedomo, soi ni''elifigu, ba wamatörö huku khönia.', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 6, 'So khö Yehowa zi''öli, sa''oi do, saelo tawö; do nono mbiri-biri ba do zi matua ba tawö mbua ba zi matua mbiri-biri; mame''e sumange sa''ae Yehowa ba Mbosera, ilau wamunu sebua ba danö Ndraono Gedomo.[2]', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 7, 'Ba tebunu tou göröbao, fao ba da''ö, ba faonono zaŵi ba zi matua zaŵi; mabu danö do ba aelo tou ba dawö andrö.', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 8, 'Irugi sa dania khö Yehowa baŵa wolau balö, döfi wamasulö, börö ba Ziona andrö.[3]', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 9, 'Tobali kita mbombo khöra ba talö balera tou danö; kita sihola-hola sa''ae danöra andrö.[4]', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 10, 'Bongi ma''ökhö lö mate galitönia lö mamalö-malö we''amöi miyaŵa zimbonia; götögöto wa''ara, ba tanö si mate; irugi zi lö aetu, ba lö sanörö.[5]', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 11, 'Tumbao ba si''ate zangokhögö, ba lamuhu ba gaga zonahia ba khönia; ifadölö khönia zinali fanu''a zi lö niha Yehowa, ba ifatörö wanulo zi lö ösi.[6]', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 12, 'Ba zalaŵara — ba lö''ö sa''ae samataro högöra, tobali si lö''ö zamatörö ya''ira, fefu.', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 13, 'Ba gödo andrö khöra, ba tumbu za''a-sa''a mao, ba molato ba mo''o''o hatira; tobali nahia nasu ana''a ba azuni wofo ondra.', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 14, 'Falukha ira garawi nasu ana''a ba falukha-lukha göi mbekhu, ba matiana zolombase ba da''ö, falukha ia zahono ia.[7]', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 15, 'Höngö zangazuni ba da''ö, mangadulo ia ba mamaukhu, ba lumö gödo andrö ifonahia nononia: moyo zowulo ba da''ö.', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 16, 'Mi''alui ba zura andrö khö Yehowa ba mibasobaso: lö''ö sa si lö alua, oi mo''awö! Bawania sa zanguma''ö ba Ehehania zangorudugö.[8]', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476289, 'OT', 'Yesaya', 34, 17, 'No ya''ia zolau dahö-dahö khöra ba no tangania zamatörö fanu''a danö, wamaosa khöra, ba lö''ö sa''ae tebulö wa khöra, nahiara, götö-götö wa''ara.', '["Faigi 63:1","Faigi 63:4","MozI 19:24","Fam 14:11; 19:3","Sef 2:14; Fam 18:2","Faigi 13:21","Mat 24:35; Yoh 5:39"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 1, 'Somuso tödö dania danö si mate andrö, tanö andrö si lö idanö; tanö si lö sinanö, ba sowua-wua tödö ba mobowo, si mane ladari mböhö.', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 2, 'Mobowo somasi ita ba owua-wua dödö, owua-wua dödö ba ma''iki. Tebe''e khönia lakhömi hili Libano, ba fa''asökhi hili Garemeli ba fa''asökhi ndraso andrö ba Zarona. I''ila dania lakhömi Yehowa andrö ba anehe ia wa''ebua Lowalangida andrö.', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 3, 'Mi''abölö''ö danga andrö si no atata ba mi''abe''e''ö mbalöduhi andrö, sangiwangiwa![1]', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 4, 'Mimane ba zi no tobali tödö: Mi''abe''e''ö dödömi, böi ata''u ami! Hiza Lowalangimi! So wolau balö, fanulöni khö Lowalangi. Ya''ia zi so, ba i''orifi ami.[2]', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 5, 'Ba da''ö dania teboka hörö zau''a ba tögi dalinga zafiso.[3]', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 6, 'Ba manoka zi no ombuyu-mbuyu töla, hulö mböhö, ba manunö lela zi lö hede mege; ba danö si mate sa''ae göi mangumbu nidanö; mbombo, ba danö si lö sinanö.[4]', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 7, 'Ba tobali baŵa nidanö lumö-lumö andrö [ba danö si mate] ba tanö si no odufodufo mege, ba tobali umbu. Sonahia mege asu ana''a, si mörö-mörö ira, ba tobali naha zukhu ba naha honu.', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 8, 'So ba da''ö lala sasele; lala ni''amoni''ö labe''e töinia, lö itörö si no göna si ra''i-ra''iö, me no ya''ia Lowalangi zowaö-waö fönara; ba he si lö tödö, ba tebai elungu.[5]', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 9, 'Singo, ba si lö''ö ba da''ö, ba he utu ndru''u bö''önia, ba lö möi miyaŵa, sara lö falukha ba ba da''ö; ni''orifi andrö zanörö.', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476290, 'OT', 'Yesaya', 35, 10, 'Tobali mangawuli ni''efa''ö Yehowa andrö, manunö-nunö ira wangawuli ba Ziona. Fa''omuso dödö si lö aetu yaŵara, falukha ira wa''owua-wua dödö ba fa''iki; ba faabu dödö ba fangarö-ngarö, ba si taya.[6]', '["Heb 12:12","Faigi 40:9","Faigi 29:18; 42:7; Mat 11:5","Mat 15:30; Yoh 7:38","Faigi 30:21","Faigi 51:11; Fam 21:1–7"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 1, 'Me no alua meweledölu fakhe razo Hisikia andrö, ba so moroi si tou Zaneribi, razo Asiria, ba wanuwö banua saro andrö, fefu, ba Ndraono Yuda; ba atu''a ira.[1]', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 2, 'Ba ifatenge ba Yeruzalema Rabisake andrö razo Asiria, moroi ba Lakhisi, ba wanuwö razo Hisikia, ato khönia zanuwö; ba tebato ira ba lala hele ba mbaŵa nidanö tanö si yaŵa, ba zinga lala ba mbenua zolokhoi nukha.[2]', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 3, 'Ba möi baero khö Rabisake Geliaki, mandru ba gödo, awö Zebena, durutuli awö Yoakhi, za''asa sebua, ono Gasafo.', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 4, 'Ba imane khöra Rabisake: Mimane khö Hisikia: Da''ö niŵa''ö razo sebua andrö, razo Asiria: Hadia we''e-we''e dödö andrö, nidöna-dönamö?[3]', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 5, 'Ma öwai, noa mbewe fa''abe''e dödö ba fangabölö ba wanuwö? Ha niha atö zabe''e dödöu, wa no ö''erogö ndra''odo?', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 6, 'Hiza, ödöna-döna ba Ndrawa Miserayi, si''o lewuö andrö, si no afatö, ba dozi si ani''o ya''ia, ba ifahö danga, atöla ibe''e! Si manö Wara''o andrö, razo Miserayi, ba zabe''e tödö khönia, fefu.[4]', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 7, 'Ba na mimane ena''ö khögu: Khö Yehowa, Lowalangima, madöna-döna, ba no ya''ia niböhöli Hisikia hili-hili andrö, awö naha wame''e sumange, wanguma''ö ba Ndraono Yuda ba ba mbanua Yeruzalema: Föna naha wame''e sumange andre mangalulu ami!', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 8, 'Ba labu, lau fataru khö zokhö ya''o, razo Asiria: da''ube''e khöu kudo, dua ngahönö nga''eu, ba faigi, na ö''ila ösöndra zi fakudo yaŵa.', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 9, 'Ba hadia, ö''ila ötimba, he ha samösa zolau khöu kumandra, enoni zokhö ya''o, fondrege zide-ide? ba noa zui abe''e dödöu ba Ndrawa Miserayi andrö, börö gureta ba si fakudo?', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 10, 'Ba hadia, tenga sinehe Yehowa we''amöigu miyaŵa, ba wanuwö banua ba danö andre ba ba wanudugö? No ya''ia, Yehowa, zanguma''ö khögu: Ae suwö mbanua ba danö andrö ba dudugö!', '["Faigi göi RazII 18:13–27; Nga''ötII 32","Faigi 7:3","Faigi 10:5 b.t.","Hez 29:6"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 11, 'Ba lamane khö Rabisake ira Eliaki, Sebena, Yoakhi: Li Garamo lau ba genonimö, ma''ila sa''ae da''ö; böi lau li niha Yehuda, fa böi larongo sato, si so ba göli.', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 12, 'Ba imane Rabisake: Hadia, khö zokhö ya''ugö ifatenge ndra''odo sokhö ya''o, ba ma khöu, ba wangombakha da''ö? hadia, tenga ba niha si so ba göli, ba wemanga daira ba ba wamadu giöra, ifatenge ndra''odo!', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 13, 'Ba maoso Rabisake ba mu''ao ba li niha Yehuda, imane: Mifondrondrongo li razo sebua andrö li razo Asiria:', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 14, 'Da''ö niŵa''ö razo: Böi mibe''e nifowöhö Hisikia ami; tebai sa i''orifi ami.', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 15, 'Ba böi mifondrondrongo, na ituturu we''e-we''e dödömi Yehowa Hisikia, wanguma''ö: Lö zi lö i''orifi ita Yehowa; lö''ö sa telulu ba danga razo Asiria mbanua andre!', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 16, 'Böi mifondrondrongo khö Hisikia! Imane sa razo Asiria: Mi''atulö''ö ami khögu, milulu ami ba dangagu, ba i''a mbua nagu khönia, awö mbua marafala zamösana ba ibadu nidanö ba mba''a khönia.', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 17, 'Irege sodo, ba wolohe ya''ami ba danö, si fagölogölö ba danömi, tanö si fahöna bua nowi ba ösi nagu, tanö si fahöna balazo ba kabu nagu.', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 18, 'Böi mibe''e nifowöhö Hisikia ami, na imane: I''orifi ita Yehowa! He wisa Lowalangi niha baero andrö? Hadia, no i''efa''ö mbanuania zamösana ba danga razo Asiria?', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 19, 'Heza so Lowalangi andrö ba Hamata ba ba Garafada? Heza so Lowalangi ba Zefarawa''i? Ba heza so Lowalangi danö Zamaria? Hadia no la''efa''ö Zamaria ba dangagu?[5]', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 20, 'Heza so ba Lowalangi danö andrö fefu zi no mangefa''ö banuara ba dangagu, fa i''efa''ö ena''ö Yeruzalema Yehowa, ba dangagu andre?', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 21, 'Ba lö hede-hedera sa''ae, lö latema linia, sambua li lö''ö. Noa sa iŵa''ö razo:', '["RazII 14:25,28; 17:24"]', NULL),
  (3476291, 'OT', 'Yesaya', 36, 22, 'Böi mitema linia: Ba lafuli ira: ira Eliaki andrö, ono Hilikia, mandru ba gödo ba Sebena durutuli ba Yoakhi, ono Gasafo, za''asa sebua andrö khö Hisikia; no lasika nukhara, ba la''ombakha''ö khönia niŵa''ö Rabisake andrö.', '["RazII 14:25,28; 17:24"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 1, 'Ba me irongo da''ö razo Hisikia, ba isika nukhania, i''obaru mbaru bu ba möi ba gosali Yehowa.[1]', '["Faigi göi RazII 19","RazII 7:6"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 2, 'Ba ifatenge Geliaki andrö, mandru ba gödo, awö Zebena, durutuli, awö zatua gere — baru bu mbarura — khö Yesaya, ono Gamosi, sama''ele''ö andrö.', '["Faigi göi RazII 19","RazII 7:6"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 3, 'Ba lamane khönia: Da''ö niŵa''ö Hisikia: Baŵa wa''atosasa ma''ökhö, baŵa wotu, baŵa wanibo; hatö fa''atumbu nono, ba ambö fa''abölö ba wadono.', '["Faigi göi RazII 19","RazII 7:6"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 4, 'Tabe''e no irongo Yehowa, Lowalangiu, huhuo Rabisake andrö, nifatenge zokhö ya''ia, razo Asiria, ba wango''aya Lowalangi sauri. Ba yamube''e wotu, ba huhuo andrö nirongo Yehowa, Lowalangiu andrö. Ba ya''ugö, ba angandrö, salahi zi tosai andrö, si lö ahori na.', '["Faigi göi RazII 19","RazII 7:6"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 5, 'Ba me larugi Yesaya enoni razo Hisikia andrö,', '["Faigi göi RazII 19","RazII 7:6"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 6, 'ba imane khöra Yesaya: Mimane khö zokhö ya''ami: Da''ö niŵa''ö Yehowa! Böi ata''ufi huhuo andrö, nirongou, fango''aya genoni razo Asiria andrö ya''odo.', '["Faigi göi RazII 19","RazII 7:6"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 7, 'Hiza, ulau khönia Geheha, fa irongo duria ba fa mangawuli ba danönia, ba mate nibunu dania ia ba danönia ube''e![2]', '["Faigi göi RazII 19","RazII 7:6"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 8, 'Ba mangawuli Rabisake, andrö, ba fanuwö banua Libena halöŵö razo Asiria, me irugi; noa sa irongo, wa no iröi Lakhisi andrö.', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 9, 'Ba me irongo duria Diraka, razo Gaitiofia andrö, me lamane: So ia moroi si tou, ba wanuwö ya''ugö, ba ifuli ifatenge zinenge khö Hisikia imane:', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 10, 'Mimane khö Hisikia, razo Ndraono Yuda andrö: Böi be''e nifowöhö Lowalangiu andrö ndra''ugö, nihalöu we''e-we''e dödöu, wanguma''ö tödöu: Lö telulu ba danga razo Asiria Yeruzalema andre.', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 11, 'Noa sa tögi dalingau zamondrongo, he lawisa razo Asiria ba danö bö''ö misa fefu, wamakiko ya''ira, ba hadia, sauri ndra''ugö?', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 12, 'Hadia, no la''orifi Lowalangi niha baero soi andrö, nifakiko ndra tuagu amagu — Gosana andrö ba Harana ba Resefa ba banua Gedena andrö ba Delasara?', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 13, 'Heza so razo Hamata andrö ba razo Garafada ba razo mbanua Zefarawa''i ba razo Hena ba razo Iwa?"', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 14, 'Ba me no itema Hisikia zura andrö ba danga zinenge ba me no ibaso, ba möi ia miyaŵa ba gosali Yehowa ba ibologö zura andrö Hisikia föna Yehowa.', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 15, 'Ba mangandrö Hisikia khö Yehowa, imane:', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 16, '"He Yehowa ngahönö, Lowalangi Ndraono Gizeraeli, sidadao yaŵa Kerubi andrö, ha ya''ugö Lowalangi soi niha ba guli danö fefu; ya''ugö zamazökhi banua si yaŵa, awö danö.', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 17, 'Be''e mbörö dalingau, ya''ugö Yehowa, ba fondrondrongo; bokai höröu, ya''ugö Yehowa, ba faigi! Fondrongondrongo li Zaneribi andrö, nifa''ohe''önia, ba wango''aya Lowalangi sauri!', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 18, 'Si ndruhu sa, ya''ugö Yehowa, noa sa lafakiko razo Asiria andrö soi bö''ö fefu, fabaya tanöra,', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 19, 'noa sa latibo''ö ba galitö nadura andrö. Tenga sa Lowalangi da''ö, ha sambalö nifazökhi danga niha, eu ba kara, ba la''ila lafakiko.', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 20, 'Ba iya''e, ya''ugö Yehowa, Lowalangima, ba efa''ö ndra''aga ba dangania, ena''ö aboto ba dödö soi niha ba guli danö fefu, wa no ha ya''ugö Lowalangi, ya''ugö Yehowa!"', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 21, 'Ba ifatenge zinenge khö Hisikia Yesaya andrö, ono Gamosi, imane: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: "Ni''andröu khögu ba khö Zaneribi andrö, razo Asiria, ba no urongo.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 22, 'Da''ö daroma li, niŵa''ö Yehowa, ba khönia andrö: I''ositengagö ndra''ugö ono alawe andrö, ono Ziona alawe, i''o''aya ndra''ugö, ifalikhö ia moroi furiu ono Yeruzalema andrö, alawe.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 23, 'Ha niha ni''o''ayamö, ha niha nitandraŵaisiu? Ha ökhö ötandrösaigö, wehedeu andrö, ha khö öfayaŵa höröu? No khö Ni''amoni''ö Ndraono Gizeraeli andrö!', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 24, 'No ö''o''aya Zo''aya, nifa''ema genoniu andrö, no ömane: ''No u''ohe gureta andrö khögu, ha wa''oya, we''amöi yaŵa ba zuzu hili, ba wondrege hili Libano andrö, no u''obö geresi salaŵa andrö ba berosi nitutuyu andrö ba no urugi wondrege zuzunia, atua si fadoro.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 25, 'No ufakharu''ö danö ba no ubadu nidanö ba no u''ogo''öisi fefu lala nidanö ba danö Miserayi lalu''a kahegu''.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 26, 'Hadia, örongo? No ara sa''ae, me uhonogöi, ba götö föna sa''ae uföfö''ö, ba awena iada''e ufalua, fa ödudugö mbanua saro, fa öbali''ö adudula kara.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 27, 'Ba ösi mbanua, ba tokea, ba wa''atebaira ba tobali aila; tobali hulö mbulu ndru''u ba mbenua, hulö zauri moroi tou ba danö, si mane du''u ba gero zagö, si mane fakhe sariri lö fakhamö molai.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 28, 'Femaosomö ba fedadaomö, ba no oroma khögu; fofanöu ba fa''asomö, ba u''ila, awö wolaŵamö ya''odo!', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 29, 'Ba me solaŵa ya''o atö ndra''ugö, me no irugi miyaŵa dögi dalingagu fayaŵasamö andrö, ba ube''e ba nikhumö wamakhai andrö khögu, ba si''öli andrö khögu, ba ube''e ba mbawau, ba ufasao''ö mangawuli ba lala andrö nitöröu me so''ö!"[3]', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 30, 'Ba da''e dandra khöu [ya''ugö Hisikia]: Si döfi andre, ba la''a zauri manö, ba ba ndröfia dania, ba sotalinga ba mbörö duhe, ba mendrua fakhe tö, ba manaru ami ba mamasi, mifazökhi kabu nagu ba mi''a mbua.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 31, 'Ba ha niha zauri, ma''uwu Yuda, ha niha zi tosai, ba ifuli moŵa''a ba danö ba mowua yaŵa hogu.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 32, 'So sa zi otarai Yeruzalema, si tosai, sauri, si otarai hili Ziona; fa''aukhu dödö Yehowa ngahönö zolau da''ö!', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 33, 'Andrö imane Yehowa ba khö razo Asiria andrö: "Lö tola möi ia bakha ba mbanua andre ba lö tola i''efasi bakha nono wana; lö tola lahatö''ö ba mbanua mbaluze ba lö tola lako''o mba''a-ba''a baero göli.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 34, 'Lala nitörönia, me so ia, ba itörö zui ba wangawuli, ba lö isöndra lala bakha ba mbanua andrö, iŵa''ö Yehowa.', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 35, 'Ya''odo sa''ae zomba''a banua andre, ba wangorifi ya''ira, börö ndra''odo ba enonigu Dawido andrö."', '["Faigi 30:28"]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 36, 'Ba itörö mala''ika Yehowa, ibözi zi 185.000 niha ba golombaseŵa Ndrawa Asiria. Ba me maoso ira ba zanguhulö wongi, ba hiza, ba no mate da''ö fefu.', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 37, 'Ba maoso Zaneribi, razo Asiria andrö, lalau mofanö, lafuli ira ba la''iagö Niniwe.', '[]', NULL),
  (3476292, 'OT', 'Yesaya', 37, 38, 'Ba samuza ma''ökhö, me mangandrö ia ba gosali Lowalanginia Niserokho andrö, ba latema labunu ia si''öli ononia andrö, Aderamelekhi ba Sareseri, ba moloi ira, lasaŵa danö Ararata. Ba tobali razo nononia Asarado, fangalinia.', '[]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 1, 'Ba me luo da''ö, ba mofökhö Hisikia, fökhö famunu. Ba möi khönia zama''ele''ö andrö, Yesaya, ono Gamosi, imane khönia: Oroi''ö hadia ia niŵa''öu, si mate sa''ae ndra''ugö, lö auri''ö.[1]', '["Faigi göi RazII 20; Nga''ötII 32:24","Yos 10:13"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476293, 'OT', 'Yesaya', 38, 2, 'Ba ibali''ö ia Hisikia, i''otahögö mbagolö, mangandrö ia khö Yehowa,', '["Faigi göi RazII 20; Nga''ötII 32:24","Yos 10:13"]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 3, 'imane: "He Yehowa, törö tödöu, wa lö si faröi ndra''odo, wa no tenga si dua tödö ndra''o, wanörö lalagu andrö fönau, awö wa no u''o''ö zomasi ndra''ugö!" Ba mege-ege sibai Hisikia.', '["Faigi göi RazII 20; Nga''ötII 32:24","Yos 10:13"]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 4, 'Ba so niŵa''ö Yehowa khö Yesaya, imanö:', '["Faigi göi RazII 20; Nga''ötII 32:24","Yos 10:13"]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 5, '"Ae ŵa''ö khö Hisikia: Da''ö niŵa''ö Yehowa, Lowalangi duau Dawido andrö: No urongo wangandröu, ba no u''ila daŵa höröu andrö. Ba da''udou''ö nosou, mewelelima fakhe tö.', '["Faigi göi RazII 20; Nga''ötII 32:24","Yos 10:13"]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 6, 'Ba u''efa''ö ndra''ugö ba banua andre ba danga razo Asiria andrö; uba''a sa''ae mbanua andre.', '["Faigi göi RazII 20; Nga''ötII 32:24","Yos 10:13"]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 7, 'Ba da''ö dandra khöu khö Yehowa, wa ifalua da''ö Yehowa, nifabu''unia andrö:', '["Faigi göi RazII 20; Nga''ötII 32:24","Yos 10:13"]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 8, 'Mangawuli lumö andrö, ube''e, ha uge bosi, si no ahöndrö luo ba dandra luo andrö khö Gahasi, fulu bosi." Ba mangawuli luo, si fulu bosi, si no ahöndrö ia, ba dandra luo andrö.[2]', '["Faigi göi RazII 20; Nga''ötII 32:24","Yos 10:13"]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 9, 'Sura Hisikia andrö razo Ndraono Yuda me no mofökhö ia ba me no döhö wökhönia andrö:', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 10, 'No umane: "Ha talu niha ndra''odo, ba usaŵa mbanua tou, utörö mbawa gölinia, taya khögu zi tosai nosogu.[3]', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 11, 'No umane: Lö''ö sa''ae u''ila Yehowa, Yehowa andrö ba danö zauri. Lö''ö sa''ae u''ila niha ba zi so ba mbanua tou andrö.', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 12, 'No tedudugö nahiagu, no te''oloi''ö, no aefa khögu, si mane ose gubalo. No ududugö nosogu, nifolau zanoso nukha; itaba ndra''odo, i''etu''ö. Lö fakhamö bongi, ba lö ya''odo sa''ae öbe''e.[4]', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 13, 'Mangarö-ngarö ndra''odo: irege mahemolu mbanua irasa dölagu fefu, si mane singo. Lö fakhamö bongi, ba lö ya''odo sa''ae öbe''e.', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 14, 'Fakore ndra''o si mane katawaena, si mane tumbao; fakore, si mane marafadi. Mo''ala''ala hörögu, ufaöga miyaŵa [umane]: "He Yehowa, si tosasa ndra''odo; tolodo!"[5]', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 15, 'Hadia niŵa''ögu, me no muhede ia khögu ba me no ifalua? Sowaö-waö manö ndra''o, götö wa''anau nosogu, lö lai wa''abu dödögu andrö.', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 16, 'He So''aya, da''ö gaurifa niha, ba da''ö usöndra wa''abölö nosogu andrö fefu. Ba öfadöhö wökhögu, öfuli ö''orifido.', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 17, 'Hiza, fangorifigu wa no afökhö khögu zafökhö andrö. Ba no örorogö nosogu, fa lö alau ba gohokoho famakiko; noa sa ö''erogö horögu andrö fefu.[6]', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 18, 'Lö''ö sa i''andrö saoha gölö khöu banua tou, ba lö isuno''ö fa''amate; si no numalö mitou ba gohokoho, ba lö ladöna-döna wa lö faröi ndra''ugö.[7]', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 19, 'Ha sauri, sauri andrö zangandrö saoha gölö khöu, si mane ya''odo ma''ökhö. I''ombakha''ö khö nononia ama, wa no si lö faröi ndra''ugö.', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 20, 'Edöna i''orifi ndra''odo Yehowa: ba datalau mbiola, sagötö ya''ita, ba gosali Yehowa andrö!"', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 21, 'Ba iŵa''ö Yesaya, la''ohe dalu-dalu nigule''ö, bua ara, ba lagule''ö ba waosa andrö, ena''ö abe''e razo.[8]', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476293, 'OT', 'Yesaya', 38, 22, 'Ba imane Hisikia: Hadia dandra, wa möido miyaŵa dania ba gosali Yehowa?', '["Sin 102:25","Yob 4:21","Yes 59:11","Heb 12:11","Sin 6:6; 30:10","RazII 20:7 b.t."]', NULL),
  (3476294, 'OT', 'Yesaya', 39, 1, 'Me luo da''ö ifa''ohe''ö zura, awö mbuala Merodakhi-Balada, ono Mbalada, razo Mbabeli, khö Hisikia; noa sa irongo, wa no mofökhö Hisikia, awö wa no ifuli abe''e.[1]', '["Faigi göi RazII 20:12–19","Nga''ötII 32:27"]', NULL),
  (3476294, 'OT', 'Yesaya', 39, 2, 'Ba omuso dödö Hisikia ba khöra andrö, ba i''oroma''ö khöra nomo girö-girö andrö khönia, awö wirö, awö gana''a, awö dalu-dalu, awö wanikha andrö, sebua böli; fefu nahia wangöna, awö fefu hadia ia zi so ba nahia girö-girö andrö. Sambalö lö''ö, si lö i''oroma''ö khöra Hisikia, si so ba gödonia ba ba zi so barö mbawania fefu.[2]', '["Faigi göi RazII 20:12–19","Nga''ötII 32:27"]', NULL),
  (3476294, 'OT', 'Yesaya', 39, 3, 'Ba möi khö Hisikia Yesaya, sama''ele''ö andrö, imane khönia: Hadia niŵa''ö niha andrö, ba ha banua ira, wa möi ira khöu? Imane Hisikia: La''otarai danö saröu, we''amöi khögu, Mbabeli andrö.', '[]', NULL),
  (3476294, 'OT', 'Yesaya', 39, 4, 'Ba imane: Hadia ni''ilara baomou? Imane Hisikia: No ahori la''ila zi so ba gödo andre khögu; lö hadia ia ba nahia girö-girö khögu, si tenga ni''oroma''ögu khöra.', '[]', NULL),
  (3476294, 'OT', 'Yesaya', 39, 5, 'Ba imane Yesaya khö Hisikia: Fondrondrongo niŵa''ö Yehowa ngahönö:', '[]', NULL),
  (3476294, 'OT', 'Yesaya', 39, 6, 'Irugi baŵa dania, ba te''oloi''ö ba Mbabeli fefu hadia ia zi so ba gödo andre khöu, fabaya fefu nihöna ndra tuau, amau, irugi ma''ökhö andre; lö hadia ia nisaigö, iŵa''ö Yehowa.', '[]', NULL),
  (3476294, 'OT', 'Yesaya', 39, 7, 'Ba lahalö dania ösa nonou, nga''ötöu, si tumbu-tumbu khöu dania, ena''ö ngoni-ngoni ira ba gödo razo Mbabeli andrö, enoni yomo.', '[]', NULL),
  (3476294, 'OT', 'Yesaya', 39, 8, 'Ba imane Hisikia khö Yesaya: Li Yehowa andrö, nifa''emau, ba no si sökhi. Imane sa dödönia: Fa''ohahau dödö ba fa''ahono-hono sa atö ba götögu andre.', '[]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 1, 'Mirara dödö, mirara dödö mbanuagu andrö, iŵa''ö Lowalangimi!', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 2, 'Mihede ba mbanua Yeruzalema si göna ba dödö, mi''ao khöra, mifarongogö, wa no awai wasöndrata andrö khöra, wa no muheta horöra, wa no dua winaeta latema sulö horöra fefu, nibe''e Yehowa![1]', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 3, 'Fondrondrongo, so zi''ao, imane: "Ba danö si mate mihaogö lala Zo''aya, mifadaya ba mbenua lala, khö Lowalangida.[2]', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 4, 'Fefu zobawa danö, ba nifo''ösi ba fefu hili, fabaya hili-hili fefu, ba nihöndrögö. Ba sobu''u-bu''u, ba nibali''ö salo''o ba tanö sohili-hili, ba nibaliö daso.', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 5, 'Ba oroma dania lakhömi Yehowa ba endronga la''ila dozi niha; noa sa Yehowa zanguma''ö.[3]', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 6, 'Fondrondrongo! lamane: Ao! Ba imane: Hadia niŵa''ögu we''ao? — "Du''u nösi niha fefu ba fefu wa''asökhinia, ba no hulö mbowo ndru''u ba mbenua.[4]', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 7, 'Oköli ndru''u andrö, aleu mbowo no mege, me no itörö ia hanu-hanu Yehowa andrö. Si ndruhu, du''u niha andrö!', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 8, 'Oköli ndru''u andrö, aleu mbowo no mege, ba si lö tebulö daroma li Lowalangida andrö, irugi zi lö aetu."[5]', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 9, 'Ae yaŵa ba hili salaŵa, ya''ugö banua Ziona, sangombakha turia somuso dödö! Ebua''ö liu, abölögö, ya''ugö banua Yeruzalema, sangombakha turia somuso dödö; ebua''ö li, böi ata''ufi; ömane ba mbanua Ndraono Yuda andrö: Hiza Lowalangimi!', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 10, 'Hiza, so Zo''aya, Yehowa sabölö ia, tangania zamolala hadia ia khönia, fao khönia luo andrö khönia, ba mowaö-waö fönania zulö andrö khönia![6]', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 11, 'Ikubaloi rorogöfönia, si mane kubalo; ihagi nono mbiri-biri andrö, i''ohe, ba dotonia, ba ihaogö-haogö wamasao sigelo, samaenu ono.[7]', '["Faigi 61:7; Sakh 9:12","Mat 3:3","Yoh 1:14","Yob 14:2; Sin 102:12; 103:15; Yak 1:10","Mat 5:18; FetI 1:24,25","Faigi 62:11","Sin 23:1; Hez 34:23; Mikh 7:14; Yoh 10:11"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 12, 'Ha niha zanu''a asi andrö ba dangania yaŵa, ba ha niha zi litoigö banua si yaŵa, ha niha zolau ba hinaoya gawu-gawu andrö ba danö, ba ha niha zanulo ba waliera hili ba ba mbulu waliera hili-hili andrö?', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 13, 'Ha niha zaboto ba dödö Eheha Yehowa, ba ha niha zangombakha lala khönia, wamahaö ya''ia?[8]', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 14, 'Ha khö mamagölö ia, ena''ö i''atua-tua''ö ia ba ena''ö i''ombakha''ö khönia lala satulö, ba ena''ö ibotokhi ba dödönia hadia ia ba ena''ö ifarongogö khönia lala wangila fefu hadia ia?', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 15, 'Hiza, amaedola mböiböi nidanö ba doyo nasoa soi niha, amaedola gawu-gawu ba mbulu waliera wamaiginia; hiza, ifazaŵa hulo, nifamazaŵa si samba ngawua nene.', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 16, 'Ba ambö fanunu sumange geu ba hili Libano, ba utu ndru''u andrö khönia, ba lö irugi sumange nitunu.', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 17, 'Hulö zi lö''ö fönania fefu soi niha; ha sambalö faya-faya ba si lö boto wamaiginia.[9]', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 18, 'Ba ha khö mifaedo Lowalangi andrö, hadia mibe''e famaedonia?', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 19, 'Famaedo Lowalangi andrö, ba no nifahele duka, ba siambu zamo''uli ana''a, iforate firö tuka siambu.', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 20, 'Ba sambö balazo, ba wame''e si manö, ba ihalö geu si tebai obou, ba i''alui duka sonekhe, ena''ö ifataro wamaedo si tebai mangiwa.', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 21, 'Hadia, lö aboto ba dödömi? Hadia, lö mirongo? Hadia, lö mu''ombakha''ö khömi, i''otarai mböröta? Lö nitöngönimi latalata danö andrö?', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 22, 'Ya''ia zidadao yaŵa golia uli danö andrö, fa timba lareŵe zowanua ba guli danö; samologö banua si yaŵa, hulö muko sabukho; hulö nose ibologö, ena''ö monahia ita barönia.[10]', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 23, 'Same''e si lö boto salaŵa ba samali''ö faya-faya sanguhuku ba guli danö.[11]', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 24, 'Faefa tetanö ira, faefa tefazaewe danömö, awena sibai na moŵa''a ba danö mbörö, ba ihehaini ira, ba mate ba i''oloi''ö angi, si mane dami wakhe.', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 25, 'Ba ha khö atö mifaedo ndra''odo, si fakhili-khili ndra''o? iŵa''ö Ni''amoni''ö andrö.', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 26, 'Mifaöga hörömi ba mifaigi: Ha niha zomböi da''ö? Ya''ia, solohe baero ngawawa andrö, ha wa''oya ira, sanötöi töira fefu; ba wa''afahöna wa''abölönia andrö ba ba wa''abölö wa''abe''enia andrö, ba sambua lö ambö.[12]', '["Rom 11:34","Dan 4:32","MozI 1:6; Yob 9:8; Sin 104:2","Yob 12:21; Sin 107:40","Sin 147:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 27, 'Ba hana wa öŵa''ö, ya''ugö ma''uwu Yakobo, ba ya''ugö, Iraono Gizeraeli, ba hana wa ömane: No tobini khö Yehowa lalagu andrö, ba satulö andrö khögu, ba lö i''ila Lowalangi?', '["Sin 103:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 28, 'Hadia, lö ö''ila, lö nirongou: Lowalangi si lö aetu Yehowa andrö, somböi fondrege danö andrö! Lö atage ia ba lö erege dödönia: si tebai tesöndra gera-erania andrö.', '["Sin 103:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 29, 'Ibe''e wa''abölö ba zerege tödö ba ihöna wa''abe''e ba zi tebai.', '["Sin 103:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 30, 'Alakha erege dödö nono matua ba alakha atata döla ba alakha alau ndra matua sabölö na:', '["Sin 103:5"]', NULL),
  (3476295, 'OT', 'Yesaya', 40, 31, 'Ba sanötöna khö Yehowa, ba latema wa''abölö si bohou, fa manahae ira, fa mo''afi, hulö moyo; fa fagohi ira, ba lö atage, fa mowaö-waö, ba lö erege dödö.[13]', '["Sin 103:5"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 1, 'Mifondrongo-ndrongo khögu, böi mihede-hede, ya''ami hulo andrö, ba ya lasöndra wa''abölö si bohou niha baero; Ndramu''ondrasi, ba hana na humede ira — datalau fahuku.', '["Faigi 43:10; 44:6; Fam 1:8,17; 21:6"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 2, 'Ha niha zogaoni moroi ba gatumbukha si falukha fa''atulö heza ibekai danö. Ha niha zame''e barö mbawania soi niha, ba ha niha zanimba [fönania] razo? Ha niha zamali''ö gawu-gawu si''ölira ba same''e dami wakhe, ni''oloi''ö nangi, fanara andrö.', '["Faigi 43:10; 44:6; Fam 1:8,17; 21:6"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 3, 'Igohi ira, itörö manö, lö hadia ia; lö ba dödönia, na so lala ba na lö''ö.', '["Faigi 43:10; 44:6; Fam 1:8,17; 21:6"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 4, 'Ha niha zolau da''ö, ha niha zamalua? Ya''ia andrö, sogaoni nga''ötö niha, i''otarai mböröta: ya''odo, Yehowa, si lö tebulö, he ba mböröta sibai, ba he ba zafuria niha dania.[1]', '["Faigi 43:10; 44:6; Fam 1:8,17; 21:6"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 5, 'La''ila hulo andrö ba muhokha mbu; manizi-nizi wondrege danö; la''orudugö ira ba so ira moroi sa.', '["Faigi 43:10; 44:6; Fam 1:8,17; 21:6"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 6, 'Faoma latolo nawöra ba imane zamösana khö nawönia: Abe''e''ö dödöu!', '["Faigi 43:10; 44:6; Fam 1:8,17; 21:6"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 7, 'Ifarou dödö ziambu tuka andrö, ba tuka warökha, ba ifarou dödö zamözi-mözi ba dane-dane, wanguma''ö ba wamiza andrö: Sökhi! Ba i''aro''ö osö-osö, fa tebai mangiwa.', '["Faigi 43:10; 44:6; Fam 1:8,17; 21:6"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 8, 'Ba ya''ugö, Iraono Gizeraeli, enonigu, ya''ugö ma''uwu Yakobo, nituyugu! ya''ugö madou Gaberahamo andrö, somasi ya''odo mege![2]', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 9, 'Ya''ugö, nituyugu ba mbalö danö, nikaonigu ba wondregenia, wanguma''ö khöu: Enonigu ndra''ugö, no utuyu, ndra''ugö, tenga fa lö ba dödögu ya''ugö.', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 10, 'Böi busi dödöu; lö''ö sa aefado khöu? Böi tokea''ö, Lowalangiu sa ndra''odo: u''abe''e''ö ndra''ugö, ba utolo''ö, ugogohe ndra''ugö na tangagu kambölö andre, samalua satulö.', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 11, 'Hiza, si falukha fa''aila ba fama''iki niha dania, dozi si fa''udu khöu; tobali si lö boto ba si tekiko nudumö andrö, fefu.[3]', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 12, 'Ö''alui dania ira, ba lö ösöndra, niha andrö, si fasoso-soso khöu; si tekiko dania ba ha sambalö si lö''ö niha andrö, si fasöndra khöu.', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 13, 'Ya''odo sa''ae, Yehowa, Lowalangimö andrö zololohe kambölöu, ya''odo andre, sanguma''ö khöu: Böi busi dödöu, utolo''ö!', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 14, 'Böi busi dödöu, ya''ugö kukuö ma''uwu Yakobo, ba ya''ami si lö atoto, Iraono Gizeraeli! utolo ami, iŵa''ö Yehowa; sangorifi ya''ugö, Ni''amoni''ö Ndraono Gizeraeli andrö.', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 15, 'Hiza, ubali''ö gaolo famöbörö wakhe ndra''ugö, si bohou, ba satarö ba soya si''öli: ba öböbörö hili, ömama, ba hulö ndrami wakhe hili-hili öbe''e!', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 16, 'Ötafi''ö, ba i''oloi''ö angi, ifazaewe angi sabölö; ba ya''ugö, ba sowua-wua tödö ba khö Yehowa ba ösuno''ö ba khö Ni''amoni''ö Ndraono Gizeraeli andrö.', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 17, 'Sebua famakao ba si numana, ba la''alui nidanö, ba lö''ö; no otufo lelara ba wa''owökhi dödö: ba ya''o, Yehowa, zamondrongo lira; ya''odo, Lowalangi Ndraono Gizeraeli andrö, ba lö uröi ira.[4]', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 18, 'Alua nidanö ba hili si lö eu''eu ube''e, ba atöla gumbu ba dalu ndraso. Tanö si mate ba ubali''ö baŵa nidanö, ba tanö si no oköliköli, ba ubali''ö si so umbu nidanö misa.[5]', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 19, 'Mo''eu danö si mate ube''e, eresi ba bana ba malimbi ba falo; ba ba mbenua, ba utanö mberua ba simalambuo ba afoa.', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 20, 'Ena''ö la''ila, dozi, ena''ö oroma khöra, ena''ö labe''e ba dödö ba ena''ö aboto ba dödöra, wa tanga Yehowa zolau da''ö ba Ni''amoni''ö Ndraono Gizeraeli andrö zamalua.', '["MozV 7:6; 10:15; Nga''ötII 20:7; Sin 135:4","MozII 23:22; Yes 60:12","Mat 5:6","Sin 107:35; Faigi 35:7"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 21, 'Mi''ohe huhuomi, iŵa''ö Yehowa, mi''ombakha''ö mbörö, iŵa''ö razo ma''uwu Yakobo andrö.', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 22, 'Hana na möi ira, ba wangombakha khöda, he wisa ba götö dania! Mi''ombakha''ö he wisa föna, ena''ö matanö ba dödö ba ena''ö aboto ba dödöma lua-luania! Ba na lö''ö, ba mifarongogö khöma he wisa dania.[6]', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 23, 'Mi''ombakha''ö khöma zalua dania, ena''ö aboto ba dödöma, wa no Lowalangi ami. Milau manö hadia ia, he si sökhi ba he si lö sökhi, ena''ö ahöli-höli dödöma, ena''ö ma''ila, dozi ndra''aga.', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 24, 'Hiza, si ndruhu si lö''ö ami ba folaumi, ba no si lö boto manö; ni''ogorofi zolemba khömi.', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 25, 'So nikaonigu moroi yöu, ba no möi ia; moroi ba gatumbukha luo ukaoni, sangombakha töigu, ena''ö itörö gumandru, si mane na tatörö lömbu za''ua, ena''ö ihundragö, si mane na ihundra-hundra la''uri samözi bowoa.[7]', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 26, 'Ha niha zangombakha da''ö, i''otarai mböröta, ena''ö ta''ila, ba ha niha zi hönagö, ena''ö tola taŵa''ö: Itörö niŵa''önia? Ba samösa lö sangombakha, samösa lö samarongogö, lö samondrongo limi.', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 27, 'Ya''odo zi föföna manguma''ö ba mbanua Ziona: Hiza, hiza ira! Ba ufatenge ba Yeruzalema zangombakha turia somuso dödö.[8]', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 28, 'Ba na ufakhölö ndra''o, ba lö niha, ba lö sangombakha lala, ba khöra andrö, ena''ö usofu khöra ba ena''ö latema ligu.', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476296, 'OT', 'Yesaya', 41, 29, 'Hiza, faya-faya manö dozi ira; si lö boto wolaura andrö; angi nadura andrö, faya-faya.', '["Faigi 46:10","Faigi 44:28; 45:1; 46:11; 48:14","Faigi 40:9"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 1, 'Hiza genonigu andrö, si lö uböhöli, nituyugu, somasi dödögu! No uhare''ö khönia Gehehagu: i''ombakha''ö dania huku ba niha baero.[1]', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 2, 'Tenga si''ao ia, tenga sebua li; lö ifarongogö linia baewali.[2]', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 3, 'Sukhu si no mufatö''ö, ba lö ifalua ifatö, ba fandru sanimbonimbo, ba lö ifalua ibunu; si ndruhu lala itörö wangombakha huku.', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 4, 'Lö erege dödönia, ba lö atage ia, irege no ifodane-dane huku ba guli danö, ba ladöna-döna nifakhoinia si so ba hulo misa.', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 5, 'Da''ö niŵa''ö Lowalangi, Yehowa, samazökhi banua si yaŵa, samologö ya''ia ba samologö tanö fabaya sauri yaŵa, samohanu-hanu niha ba gulinia ba samonoso sowaö-waö yaŵa, [imane]:', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 6, 'Ya''o, Yehowa zogaoni ya''ugö, satulö lala utörö, ba ura''u dangau ba urorogö ndra''ugö ba ube''e fawu''usa li ba mado Ndraono Gizeraeli ndra''ugö ba ubali''ögö haga ba niha baero.[3]', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 7, 'Ba wamokai hörö zau''a, ba wangefa''ö ba gurunga nikuru, ba wolohe baero nikuru ba zögömi-gömi.[4]', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 8, 'Ya''o Yehowa — da''ö döigu; lö ube''e ba mbö''ö zumangegu ba lö ube''e ba nadu wa''ebua döigu andrö.[5]', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 9, 'Hadia ia föna, ba no itörö, ba u''ombakha''ö zi bohou; fatua lö alua ufarongogö khömi.', '["Faigi 11:1 b.t.; Mat 3:17; 12:18–21","Mat 11:29","Faigi 49:8; Luk 2:32; Yoh 8:12","Faigi 35:5; Faigi 61:1; Luk 4:18","Faigi 48:11"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 10, 'Mi''anunö khö Yehowa, fanunö si bohou! mitunö duriania ba wondrege danö: Ya mu''ugu-ugu nasi, fabaya ösinia; ya fao hulo, awö zowanua yaŵa![6]', '["Sin 33:3","Faigi 40:4","Sin 97:7; Faigi 1:29; 44:11; 45:16"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 11, 'Ya mu''ao danö si mate, awö mbanua andrö khönia — banua side-ide andrö, banua Gedara! Ya omuso dödö mbanua ba gara andrö, ndra ma''iki moroi ba zuzu hili yaŵa.', '["Sin 33:3","Faigi 40:4","Sin 97:7; Faigi 1:29; 44:11; 45:16"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476297, 'OT', 'Yesaya', 42, 12, 'Ndramufosumange Yehowa, ba ndramutunö duriania ba hulo misa!', '["Sin 33:3","Faigi 40:4","Sin 97:7; Faigi 1:29; 44:11; 45:16"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 13, 'Itörö Yehowa, fanörö zabölö, si mane sanuwö ifasugi wa''aukhu dödö: Fe''ao ba wanuwö ilau, ebua sa''ae linia we''ao, i''oroma''ö wa no abölö ia moroi ba nemalinia andrö!', '["Sin 33:3","Faigi 40:4","Sin 97:7; Faigi 1:29; 44:11; 45:16"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 14, 'No ara lö hede-hedegu, no uhonogö ndra''o, no utaha dödögu, ba iada''e, ba mu''ira-ira ndra''o, si mane sadono, muhöfu ndra''o ba ufahasu-hasudo.', '["Sin 33:3","Faigi 40:4","Sin 97:7; Faigi 1:29; 44:11; 45:16"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 15, 'Uhori geu ba hili ba ba hili-hili, ba ube''e mate yaŵa fefu zauri; ubali''ö hulo mboto nidanö ba u''ogo''öisi mbaŵa nidanö.', '["Sin 33:3","Faigi 40:4","Sin 97:7; Faigi 1:29; 44:11; 45:16"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 16, 'Ba latörö lala si lö larai mila niha sau''a ube''e, ufatörö ba lala si lö la''ila mege. Sogömi-gömi andrö fönara, ba ubali''ö sohaga, ba hadia zobu''ubu''u, ba ufadaya. Da''ö niŵa''ö — ufatörö dania, lö ube''e aekhu ba danö.[7]', '["Sin 33:3","Faigi 40:4","Sin 97:7; Faigi 1:29; 44:11; 45:16"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 17, 'Sawuwu furi dania ba saila sibai zabe''e tödö ba nadu, sanguma''ö ba wamaedo nifahele andrö: Lowalangima ami.[8]', '["Sin 33:3","Faigi 40:4","Sin 97:7; Faigi 1:29; 44:11; 45:16"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 18, 'Mifondrondrongo, ya''ami safiso, ba mifaöga hörömi, ya''ami sau''a andrö, ba wamaigi!', '["Faigi 41:8; Mat 15:14","Faigi 6:10","Dan 9:5"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 19, 'Ha niha zau''a, na tenga enonigu andrö? ba ha niha zafiso, si mane fa''afiso zinengegu andrö, nifatengegu? Ha khö so wa''au''a, si mane ba zi fahuwu andrö, ba ha khö zi mane ba genoni Yehowa andrö?[9]', '["Faigi 41:8; Mat 15:14","Faigi 6:10","Dan 9:5"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 20, 'No oya ni''ilau, ba lö nibe''eu ba dödöu; no teboka dögi dalingamö, ba lö nirongou.[10]', '["Faigi 41:8; Mat 15:14","Faigi 6:10","Dan 9:5"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 21, 'No omasi Yehowa i''ebua''ö gamakhoitania ba ifolakhömi, börö wa''atulö dödönia andrö.', '["Faigi 41:8; Mat 15:14","Faigi 6:10","Dan 9:5"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 22, 'Ba noa sa ato na niha nifakao zorabu ira, niha ni''oloi''ö si so khöra; niha nifa''u''u ba dögi narö hili misa, dozi ira, nibini''ö bakha ba gurunga; no ni''oloi''ö ira, ba lö sangila mangorifi, no okhöta niha bö''ö ira, ba lö sanguma''ö: Fuli?', '["Faigi 41:8; Mat 15:14","Faigi 6:10","Dan 9:5"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 23, 'Ba ha niha ba khömi zamondrongo da''e, ha niha zame''e ba dödö, ba wanöngöni sa''ae:', '["Faigi 41:8; Mat 15:14","Faigi 6:10","Dan 9:5"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 24, 'Ha niha zolulu ba danga zorabu ma''uwu Yakobo, ba Iraono Gizeraeli, ba danga zangosindra''ui si so khöra? Hadia, tenga Yehowa andrö, ba nifazökhida horö, si lö edöna ita, tatörö lala, ba si lö tafondrondrongo oroisa?[11]', '["Faigi 41:8; Mat 15:14","Faigi 6:10","Dan 9:5"]', NULL),
  (3476297, 'OT', 'Yesaya', 42, 25, 'Ba no ilau khöra hola-hola wönunia andrö ba alitö fanuwö andrö, tobali ifasui ira hola-hola, ba lö la''ila; ira''i ira, ba lö labe''e ba dödö.', '["Faigi 41:8; Mat 15:14","Faigi 6:10","Dan 9:5"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 1, 'Ba iya''e, ba imane Yehowa, samazökhi ya''ugö, ya''ugö Iraono Gizeraeli: Böi busi dödöu, u''orifi sa''ae ndra''ugö; utötöi döimö: khögu ndra''ugö![1]', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 2, 'Na ötörö nidanö, ba sodo ba ngaiu, ba na ötörö hohou, ba lö tola alömö ndra''ugö. Na ötörö galitö, ba si lö akhozi ndra''ugö ba lö tola ira''i ndra''ugö hola-hola.', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 3, 'Ya''odo sa''ae, Yehowa, Lowalangiu, Ni''amoni''ö Ndraono Gizeraeli andre, zangorifi ya''ugö! Dawa Miserayi andrö ube''e höliu, salahiu Gaitiofia ba Seba andrö.[2]', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 4, 'Me no ebua mböliu, wamaigigu me afökhö khögu ndra''ugö, ba me omasido ndra''ugö, ba ube''e höliu niha, soi niha ube''e böli nosou.[3]', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 5, 'Böi busi dödöu, awöu sa''ae ndra''odo; moroi ba gatumbukha u''ohe miyaŵa ma''uwumö andrö, ba moroi ba gaekhula luo u''owuloi ami.[4]', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 6, 'Umane ba danö yöu: Da khögu! ba ba danö raya: Böi taha! Ohe nonogu matua andrö, moroi ba zaröu, ba onogu alawe, moroi ba wondrege danö:', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 7, 'Dozi si so töigu ba döira, dozi niwöwöigu fangebua döigu, nifazökhigu, niwöŵöi dangagu andre!', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 8, 'Ndramu''ohe niha andrö, si no au''a, he ŵa''ae no si so hörö, ba si no afiso, he ŵa''ae no motögi dalinga!', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 9, 'Ya''ami niha baero fefu, mi''owuloi ami, dozi; ndramu''orudugö ira soi niha. Ha niha ba khöra zangombakha si manö ba samarongogö khöda hadia ia niŵa''ö föna? Ndramu''ohe sasi, ba wamu''a ba hulura, ba ena''ö larongo ba ena''ö lamane: Ya''ia da''ö![5]', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 10, 'Ya''ami zi so ba mbörö khögu, iŵa''ö Yehowa, ba enonigee andrö, nituyugu, ena''ö aboto ba dödömi ba ena''ö mifati ba ena''ö misöndra, wa ya''odo: fönagu, ba lö muwöwöi Lowalangi ba furigu, ba lö''ö![6]', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 11, 'Ya''o, ya''o Yehowa, ba lö sangorifi baerogu!', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 12, 'Ya''odo zangombakha ba sangorifi ba samarongogö, ba tenga bö''ö ba khömi, ba tobali ya''ami zi so ba mbörö khögu, iŵa''ö Yehowa.', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 13, 'Ya''odo Lowalangi! Ba no götö-götö wa''ara, ba ya''oya''odo manö, ba lö sangila mangefa''ö ba dangagu hadia ia; ya''o zolau, ba ha niha zanimba?[7]', '["MozV 4:20; 7:6","MozII 14:21, Sin 66:12; Dan 3:25","MozII 19:5","Yer 30:10; 46:27","Faigi 41:23","Faigi 41:4","Yob 9:12"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 14, 'Imane Yehowa, sangorifi ya''ami, Ni''amoni''ö Ndraono Gizeraeli andrö: Börö ami, wa no ufatenge ba Mbabeli, ba lasaŵa mitou soloi andrö fefu, ube''e, ba Dawa Galedaia, ba nowo andrö, somuso dödöra mege.', '["MozII 14:21; Yos 3:16","MozII 14:28","Sin 107:35","Luk 1:74"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 15, 'Ya''odo andre, Yehowa, Ni''amoni''ömi, somböi Iraono Gizeraeli, razomi andre.', '["MozII 14:21; Yos 3:16","MozII 14:28","Sin 107:35","Luk 1:74"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 16, 'Da''ö niŵa''ö Yehowa, samatörö lala ba nasi, samolala niha ba nidanö sebua,[8]', '["MozII 14:21; Yos 3:16","MozII 14:28","Sin 107:35","Luk 1:74"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 17, 'sama''ohe''ö kureta, awö kudo, samatenge sanuwö, sabölö: hiza tou ira fefu, ba wa lö maoso sa''ae; no mate, no alele, hulö da''a-ta''a wandru.[9]', '["MozII 14:21; Yos 3:16","MozII 14:28","Sin 107:35","Luk 1:74"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 18, 'Böi mitörö tödömi hadia ia föna, ba mi''osilömilagö hadia zi no numalö!', '["MozII 14:21; Yos 3:16","MozII 14:28","Sin 107:35","Luk 1:74"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 19, 'Hiza, ulau zi bohou: motalinga sa''ae; hadia, lö mi''ila? Ufazökhi lala, ba danö si mate ba boto nidanö ba zi lö niha-niha mege.[10]', '["MozII 14:21; Yos 3:16","MozII 14:28","Sin 107:35","Luk 1:74"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 20, 'Isuno dania ndra''o utu ndru''u, asu anala andrö ba ono wofo ondra, me ufo''idanö danö si mate ba me u''asogö mboto nidanö ba zi lö niha-niha mege, ba wame''e nibadu ba mbanuagu andrö, nituyugu.', '["MozII 14:21; Yos 3:16","MozII 14:28","Sin 107:35","Luk 1:74"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 21, 'Banua da''ö, nihaogögu khögu, zangombakha turiagu dania.[11]', '["MozII 14:21; Yos 3:16","MozII 14:28","Sin 107:35","Luk 1:74"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 22, 'Ba tenga ya''o ni''angaröfiu li, ya''ugö ma''uwu Yakobo ba lö ni''eregesiu tödöu khögu, ya''ugö Iraono Gizeraeli!', '["Faigi 1:11","Faigi 1:18","MozI 3:6"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 23, 'Lö ni''oheu khögu biri-biri, sumangegu khöu, ba lö nifosumangeu ya''odo sumange nitaba andrö khöu; lö nifakaogu ya''ugö ba zumange nitaba, ba lö nibe''egu erege dödöu ba wanunu kumöyö.[12]', '["Faigi 1:11","Faigi 1:18","MozI 3:6"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 24, 'Lö nibe''eu ana''au ba wowöli samohua khögu, ba lö nibe''eu ögu tawö zumange nitaba andrö khöu. Ba no erege dödögu öbe''e ba horöu andrö; no öfakaodo olalöŵamö.', '["Faigi 1:11","Faigi 1:18","MozI 3:6"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 25, 'Ya''o, ya''odo andre zamunu lalöu andrö [ba zura], börö ndra''o, ba lö''ö sa''ae itörö tödögu horöu.', '["Faigi 1:11","Faigi 1:18","MozI 3:6"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 26, 'Fasugi ba dödögu: datalau fa''era; ofaya, ba wamu''a ba hulumö![13]', '["Faigi 1:11","Faigi 1:18","MozI 3:6"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 27, 'Furugöu moroi yaŵa, ba no mamazökhi horö, ba sama''ema andrö khöu, ba no lalaŵa ndra''odo.[14]', '["Faigi 1:11","Faigi 1:18","MozI 3:6"]', NULL),
  (3476298, 'OT', 'Yesaya', 43, 28, 'Da''ö mbörö, wa no ube''e aya zalaŵa ni''amoni''ö, awö wa ube''e nifakiko ma''uwu Yakobo ba ube''e ni''o''aya Ndraono Gizeraeli.', '["Faigi 1:11","Faigi 1:18","MozI 3:6"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 1, 'Ba fondrongondrongo sa''ae, ya''ugö ma''uwu Yakobo, enonigu, ba ya''ugö Iraono Gizeraeli nituyugu andrö!', '["MozV 32:15","Yoel 2:28; Yoh 7:38; HalZin 2:18"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 2, 'Da''ö niŵa''ö Yehowa somböi ya''ugö, samazökhi ya''ugö, i''otarai dalu ninau, sangorifi ya''ugö, imane: Böi busi dödöu, ya''ugö enonigu ma''uwu Yakobo, ba ya''ugö banua sadölö tödö andrö nituyugu.[1]', '["MozV 32:15","Yoel 2:28; Yoh 7:38; HalZin 2:18"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 3, 'Ulau sa''ae nidanö ba zowökhi tödö ba ufatörö mbombo ba danö si no oköliköli: ulau Gehehagu ba ma''uwumö, ba howu-howu andrö khögu ba madoumö.[2]', '["MozV 32:15","Yoel 2:28; Yoh 7:38; HalZin 2:18"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 4, 'Ena''ö molöndru ira ba gotalua ndru''u, ena''ö manöi, si mane bou ba mbewe nidanö.', '["MozV 32:15","Yoel 2:28; Yoh 7:38; HalZin 2:18"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 5, 'Imane si samösa: Khö Yehowa ndra''odo, ba si samösa, ba isuno döi Yakobo, ba samösa zui, ba isura ba dete dangania: "Khö Yehowa", ba labe''e nönö-nönö döinia Gizeraeli.', '["MozV 32:15","Yoel 2:28; Yoh 7:38; HalZin 2:18"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 6, 'Da''ö niŵa''ö Yehowa, razo Ndraono Gizeraeli andrö, sangorifi ya''ira, Yehowa ngahönö andrö: Si föföna ndra''o ba safuria ndra''o, ba baerogu, ba lö Lowalangi.[3]', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 7, 'Ba ha niha zihede si mane ya''odo, ba yamufarongogö ba yamufa''ele''ö khögu! i''otarai me ufataro soi andrö, si no götö-götö fa''ara. Ba si lö''ö na, salua dania, ba ndramu''ombakha''ö![4]', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 8, 'Böi ata''u ami ba böi tokea! Hadia, tenga no ara sibai, me u''ombakha''ö khömi, me ufarongogö? Ya''ami sa''ae zi so ba mbörö khögu! Hadia, so Lowalangi, baerogu? Lö gowe (dane-dane); lö ni''ilagu![5]', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 9, 'Dozi tuka nadu andrö, ba si lö boto; ba omasiöra andrö, ba si lö guna; lö hadia ia zoroma ba zi so ba mbörö andrö khöra, lö larongo hadia ia, ba tobali saila ira.[6]', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 10, 'Ha niha zomböi Lowalangi, ha niha zamahele famaedo Lowalangi, ba walöguna?', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 11, 'Hiza, awönia fefu, ba saila dania, ba tuka andrö, ba no niha: Ndramu''owuloi ira fefu, ndramufa''aso ira; si tokea dania ira ba si falukha fa''aila, dozi ira.[7]', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 12, 'I''atarösi wahö siambu ba ifazökhi [nadu andrö] ba mbo zole, ba ifonga''eu farökha ba i''asiwai fa''abölö mbulökhania andrö; itaha wa''olofo, irege lö döladöla sa''ae; lö ibadu nidanö, irugi erege dödö.[8]', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 13, 'Ifadölö ndrali samofoe eu; isura fanura simo, ifofoe förögi ba ihuku sako, ba lua-lua nifazökhinia, ba no nga''eu ndra matua, famaedo niha, ena''ö yomo ba nomo so dania.', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 14, 'No i''obö khönia Manawa ba ihonogöi ma''usö ba tuho, ena''ö esolo ba gatua, ba ngai geu bö''ö; itanö naru''u, ba ebua ibe''e teu.', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 15, 'Ba moguna eu galitö ba niha. Ba ihalö ösa ba moleu ia; ba itunu göi fangasoso gö. Ba ifazökhi göi Lowalangi, ituhi danö, ibali''ö famaedo, ibalöduhini danö, fönania.', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 16, 'Si föfö, ba no itunu, ba si föfö, ba ibe''e fondrino ndriwo, i''a nirino andrö, ösi dalunia. Ba moleu ia ba imane: Lau, lö''ö sa''ae oafudo, irugido fa''aukhu galitö andrö!', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 17, 'Ba si tosai andrö, ba no ibali''ö Lowalangi, no ibali''ö famaedo khönia: ibalöduhini danö fönania, ifalögu tou ia, i''a ngaröfi li, imane: Orifido, me no Lowalangigu ndra''ugö!', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 18, 'Lö lasöndra ba lö aboto ba dödöra; noa sa fakabi höröra, fa lö la''ila ba tödöra, fa lö lasöndra.', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 19, 'Lö same''e ba dödö; lö fa''aboto ba dödö ba lö era-era fa iŵa''ö ena''ö zamösana: Si föfönia, ba no utunu, ba no ube''e fangasoso gö mbo, ba fondri no, ba no u''a ndriwo andrö, ba hadia, ubali''ö [famaedo] ni''ogorofi zi tosai andrö, hadia, utuhi danö föna mbalö geu?', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 20, 'Somasi awu, ba no nifowöhö dödö nilimo, fa lö i''orifi nosonia ba fa lö iŵa''ö: Hadia, tenga faya ni''olembaigu?', '["Faigi 41:4","Faigi 41:22","MozV 4:35; 32:39; SamI 2:2; Faigi 43:10","Sin 115:4","Sin 97:7; Faigi 1:29; 42:17","Yer 10:3"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 21, 'Da''ö törö tödöu, ya''ugö ma''uwu Yakobo, ba ya''ugö Iraono Gizeraeli, me no enonigu ndra''ugö! No ya''odo zomböi ya''ugö; khögu ndra''ugö, enonigu; ya''ugö Iraono Gizeraeli, böi olifugö''ö ndra''odo!', '["Sin 32:1; Sin 103:3","Sin 96:11–13; Faigi 49:13","Faigi 40:22","Nga''ötII 36:22"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 22, 'Utayaigö golalöŵamö, si mane lawuo, awö horöu, si mane sau. Tema fuli''ö khögu, me no u''orifi ndra''ugö![9]', '["Sin 32:1; Sin 103:3","Sin 96:11–13; Faigi 49:13","Faigi 40:22","Nga''ötII 36:22"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 23, 'Anunö, ya''ugö banua si yaŵa, me no ifalua Yehowa! Mi''a''iki, ya''ami, irugi barö danö. Mifarongogö li wa''owua-wua dödö, ya''ami hili ba ya''ugö atua, awö geu bakha, fefu, me no i''orifi ma''uwu Yakobo; ba ihalö lakhöminia Ndraono Gizeraeli![10]', '["Sin 32:1; Sin 103:3","Sin 96:11–13; Faigi 49:13","Faigi 40:22","Nga''ötII 36:22"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 24, 'Da''ö niŵa''ö Yehowa, sangorifi ya''ugö, somböi ya''ugö, i''otarai dalu ninau, imane: Ya''o; Yehowa, zolau fefu hadia ia, samologö banua si yaŵa, ha ya''odo, ba samologö tanö: ha niha zanolo ya''o?[11]', '["Sin 32:1; Sin 103:3","Sin 96:11–13; Faigi 49:13","Faigi 40:22","Nga''ötII 36:22"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 25, 'Same''e si lö boto tandra zolau faya andrö, ba samowöhö si faeta andrö; same''e awuwu satua-tua andrö, samali''ö fa lö tödö fangilara andrö.', '["Sin 32:1; Sin 103:3","Sin 96:11–13; Faigi 49:13","Faigi 40:22","Nga''ötII 36:22"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 26, 'Samatörö niŵa''ö genoninia, ba samalua ni''ombakha''ö zinengenia; sanguma''ö ba khö Yeruzalema andrö: Ya so zui niha ba mbanua! ba ba mbanua Ndraono Yuda andrö: Ya tetaru''ö zui; ufuli u''azökhi zadudu khöra.', '["Sin 32:1; Sin 103:3","Sin 96:11–13; Faigi 49:13","Faigi 40:22","Nga''ötII 36:22"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 27, 'Sanguma''ö ba namö: Ya ogo''ö ndra''ugö! ba boto nidanö andrö khöu, ba otufo ube''e!', '["Sin 32:1; Sin 103:3","Sin 96:11–13; Faigi 49:13","Faigi 40:22","Nga''ötII 36:22"]', NULL),
  (3476299, 'OT', 'Yesaya', 44, 28, 'Same''e töi Kiro andrö "Kubalo khögu"; ba ya''ia zamalua nihonogöigu andrö, fefu, wanguma''ö ba khö Yeruzalema andrö: Ya tetaru''ö zui! ba ba gosali andrö: Ya tefadane-dane![12]', '["Sin 32:1; Sin 103:3","Sin 96:11–13; Faigi 49:13","Faigi 40:22","Nga''ötII 36:22"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 1, 'Da''ö niŵa''ö Yehowa khö nibayoininia andrö, khö Kiro andrö — nira''ugu tanga kambölö, ba wanguhundragö fönania soi niha ba ba wameta böbö talu razo, ena''ö teboka mbawandruhö fönania ba ena''ö tenga nikusi sa''ae mbawa göli:', '["Faigi 24:28","Faigi 44:8","Ngenu 3:38; Amos 3:6"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 2, 'Mowaö-waödo fönau ba ufadaya zobu''ubu''u: lagö mbawandruhö töla, ba urasa, ba lazi si''öli, ba u''eŵa.', '["Faigi 24:28","Faigi 44:8","Ngenu 3:38; Amos 3:6"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 3, 'Ba ube''e khöu girö-girö andrö, si so ba zogömi-gömi ba ana''a andrö nibini''ö sibai ubokai khöu, ena''ö aboto ba dödöu, wa no ya''odo zanötöi töimö andrö, ya''odo andre, Lowalangi Ndraono Gizeraeli andre.', '["Faigi 24:28","Faigi 44:8","Ngenu 3:38; Amos 3:6"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 4, 'Börö genonigu Yakobo andrö ba Izeraeli, nituyugu andrö, wa utötoi döimö, wa ufatörö gamalalata döimö, me lö''ö na ö''ila ndra''odo.[1]', '["Faigi 24:28","Faigi 44:8","Ngenu 3:38; Amos 3:6"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 5, 'Ya''odo Yehowa, ba tenga bö''ö, lö Lowalangi baerogu. Ya''o zamoböbö talu ya''ugö, me lö ö''ilado na.[2]', '["Faigi 24:28","Faigi 44:8","Ngenu 3:38; Amos 3:6"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 6, 'Ena''ö aboto ba dödö niha, ba gatumbukha ba ba gaekhula, wa lö ha niha baerogu; ya''odo Yehowa, ba baerogu, ba lö''ö.', '["Faigi 24:28","Faigi 44:8","Ngenu 3:38; Amos 3:6"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 7, 'Ya''odo zamazökhi haga, ya''odo zomböi sogömi-gömi ba samalua fangorifi, ba samatörö famakao, — ya''odo, Yehowa, zolau da''ö fefu.[3]', '["Faigi 24:28","Faigi 44:8","Ngenu 3:38; Amos 3:6"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 8, 'Owöi-wöi, ya''ugö banua si yaŵa! Falua deu fa''atulö, ya''ugö lawuo! Ya teboka danö, ya mowua fangorifi, yamufao wamalua fa''atulö! Ya''o, Yehowa, zomböi.', '["Faigi 24:28","Faigi 44:8","Ngenu 3:38; Amos 3:6"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 9, 'Alai zi fasosoni samazökhi ya''ia, tuga lawu andrö, abotola mbowoa tanö! Hadia, tola iŵa''ö la''uri ba zamöbözi ya''ia: Hadia nilaumö? Ba hadia, iŵa''ö omböilamö: Lö tangania?[4]', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 10, 'Alai zanguma''ö ena''ö khö nama: Hana wa mo''ono ndra''ugö? ba ma ba ndra alawe: Hana wa safökhö hulu ndra''ugö?', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 11, 'Da''ö niŵa''ö Yehowa, Ni''amoni''ö Ndraono Gizeraeli andrö, somböi ya''ira: Misofu khögu zi so fönada na; ba ba ndraonogu andrö, omböila dangagu, ba midöna-döna khögu!', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 12, 'Ya''odo zamazökhi tanö ba ya''o zomböi niha ba guli danö yaŵa; tangagu andre zamalogö banua si yaŵa, ba ha wa''oya, si so si yaŵa andrö, ba no ya''o zame''e lala.', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 13, 'Ya''odo zama''aso ya''ia (Kiro andrö) ba zatulö lala, ba uhaogö lalania fefu. Ya''ia zanaru''ö banuagu andrö, ba i''efa''ö nitaha andrö khögu, — tenga nibe''e böli ba tenga nisulöni buala, iŵa''ö Yehowa ngahönö andrö.[5]', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 14, 'Imane Yehowa: Ölö Ndrawa Miserayi andrö, ba hare Ndrawa Gaitiofia ba banua Zeba andrö, sebua niha andrö, ba khöu möi, ya''ugö zokhö dania; la''o''ö ndra''ugö, niböbö; ba latuhi danö fönau, mangalulu ira khöu, lamane: Ha khöu so Lowalangi, ba lö baero ö, lö Lowalangi bö''ö!', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 15, 'Si ndruhu, Lowalangi si no tobini ndra''ugö, ya''ugö Lowalangi Ndraono Gizeraeli, sangorifi!', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 16, 'Si lö boto dania ba saila sibai zamazökhi adu andrö; lalau mofanö, dozi ira, aila.[6]', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 17, 'Ba Iraono Gizeraeli, ba ni''orifi Yehowa, fangorifi si lö aetu. Tenga si lö boto ami ba tenga saila, götö-götö wa''ara!', '["Yer 18:6; Rom 9:20","Nga''ötII 36:22; Eser 1:1 b.t; Faigi 44:28","Faigi 44:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 18, 'Da''ö sa niŵa''ö Yehowa, samazökhi banua si yaŵa — ba ya''ia Lowalangi, samazökhi tanö, somböi ya''ia; ya''ia zame''e ba nahania: tenga tanö si lö niha-niha ifazökhi; ena''ö mowanua yaŵa niha, wamazökhinia ya''ia, — imane: Ya''odo Yehowa ba tenga bö''ö![7]', '["Faigi 42:5","MozV 30:11","Faigi 41:22","Rom 14:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 19, 'Tenga ba zi tobini fahuhuo ndra''odo, tenga ba mbanua ba danö si no ogömi-gömi, ba lö niŵa''ögu ba ma''uwu Yakobo: Zaya-zaya gölömi wangalui ya''odo! Ya''o, Yehowa, ba no satulö huhuogu ba si duhu ni''ombakha''ögu.[8]', '["Faigi 42:5","MozV 30:11","Faigi 41:22","Rom 14:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 20, 'Mi''owuloi ami, mi''aine, mi''ondrasi, dozi ami, si tosai niha baero andrö: solohe adu eu andrö, ba si lö fa''aboto ba dödö, si angaröfi li Lowalangi, si tebai mangorifi.', '["Faigi 42:5","MozV 30:11","Faigi 41:22","Rom 14:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 21, 'Mi''ombakha''ö, mifarongogö; hana sa na mamagölö ira; hana na lamane: Ha niha zi no mangombakha da''ö, föna sa''ae? ha niha zamarongogö, si no arara? Hadia, tenga ya''o, Yehowa andre? ba lö Lowalangi, baerogu; Lowalangi si ndruhu ba sangorifi, ba lö''ö, na tenga ya''odo.[9]', '["Faigi 42:5","MozV 30:11","Faigi 41:22","Rom 14:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 22, 'Mi''otahögö ndra''o, mibe''e mi''orifi ami, ya''ami fondrege danö, fefu, ya''odo sa Lowalangi ba baerogu, ba lö''ö!', '["Faigi 42:5","MozV 30:11","Faigi 41:22","Rom 14:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 23, 'No fahölu ndra''o, ba khögu andre — si duhu wehedegu, taroma li si tebai tefuli — Khögu aköi fefu mbalöduhi, ba khögu fahölu fefu lela,[10]', '["Faigi 42:5","MozV 30:11","Faigi 41:22","Rom 14:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 24, 'lamane: "Ha khö Yehowa so wangorifi ba fangabölö"; khönia möi ba aila dozi si fa''udu khönia mege.', '["Faigi 42:5","MozV 30:11","Faigi 41:22","Rom 14:11"]', NULL),
  (3476300, 'OT', 'Yesaya', 45, 25, 'Ba khö Yehowa lasöndra wa''atulö dozi ma''uwu Gizeraeli ba lasuno ira ba khönia.', '["Faigi 42:5","MozV 30:11","Faigi 41:22","Rom 14:11"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 1, 'Beli andrö, ba no mutimba, iköwö ia Nebo andrö [adu]. Famaedora andrö, ba no mube''e noro kudo ba noro zolu''i noro. Ni''ohe-ohemi föna, ba wamatörö baolayama, ba no mube''e noro zerege tödö.', '[]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 2, 'Laköröbui ira, aso''a, fefu, tebai la''orifi noro andrö, ya''ira na''i, ba ni''oloi''ö zanuwö.', '[]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 3, 'Mifondrongondrongo khögu, ya''ami ma''uwu Yakobo ba ya''ami fefu, si tosai nga''ötö Gizeraeli, ya''ami si no noro dödögu, i''otarai dalu ninami, ni''ohe-ohegu, i''otarai me tabina ami.', '["Faigi 40:18","RazI 18:27"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 4, 'Ba irege atua ami, ba ya''oya''odo manö, irege tohare huwa, ba ya''odo zi onoro tödö ya''ami: ya''o zolau, ya''odo zanaya ya''ami; uhalö noro dödögu ami, ba ufaigi wangorifi.', '["Faigi 40:18","RazI 18:27"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 5, 'Ha niha khömi, nibe''e famaedogu, nifatahö khögu; ha niha mifagölö-gölö khögu, ena''ö faoma ndra''aga?[1]', '["Faigi 40:18","RazI 18:27"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476301, 'OT', 'Yesaya', 46, 6, 'Lafaduwa tou gana''a ba latulo ba waliera wirö; la''oni duka, siambu, ena''ö ibali''ö Lowalangi, labalöduhini tou danö, mangalulu ira.', '["Faigi 40:18","RazI 18:27"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 7, 'La''angalisigö, la''onoro ba lafataro ba nahania, ena''ö i''iagö da''ö ba böi tebulö: ba na so zi angaröfi li ya''ia, ba lö itema li, lö i''efa''ö ba wa''atosasa.[2]', '["Faigi 40:18","RazI 18:27"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 8, 'Mitörö-törö tödömi da''ö ba mitöngöni, mibe''e ba dödömi, ya''ami si fa''ero andrö!', '["Faigi 44:8; 45:5","Sin 33:11; Amaed 19:21; Heb 6:17","Faigi 41:2,25; 44:28"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 9, 'Mitörö tödömi zi no ara andrö, si otarai götö föna, wa no ya''odo Lowalangi ba tenga bö''ö; Lowalangi si lö famaedo, fefu gofu heza.[3]', '["Faigi 44:8; 45:5","Sin 33:11; Amaed 19:21; Heb 6:17","Faigi 41:2,25; 44:28"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 10, 'Sangombakha lua-lua, i''otarai mböröta, i''otarai götö föna sa''ae, lua-lua zi lö alua na; sanguma''ö: Lö tola lö alua dania nihonogöigu ba hadia fefu zi so ba dödögu, ba itörö ube''e![4]', '["Faigi 44:8; 45:5","Sin 33:11; Amaed 19:21; Heb 6:17","Faigi 41:2,25; 44:28"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 11, 'Sogaoni moyo andrö moroi ba gatumbukha, niha andrö samalua nihonogöigu andrö [ukaoni], moroi ba danö saröu; itörö ni''ombakha''ögu ube''e: ufalua nihonogöigu andrö![5]', '["Faigi 44:8; 45:5","Sin 33:11; Amaed 19:21; Heb 6:17","Faigi 41:2,25; 44:28"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 12, 'Mifondrondrongo khögu, ya''ami sabe''e tandro, si no aröu fa''atulö dödö!', '["Faigi 44:8; 45:5","Sin 33:11; Amaed 19:21; Heb 6:17","Faigi 41:2,25; 44:28"]', NULL),
  (3476301, 'OT', 'Yesaya', 46, 13, 'No uhatö''ö wa''atulö andrö khögu; tenga saröu sa''ae ia; lö''ö sa''ae iradö ia fangorifi andrö khögu. Ube''e ba mbanua Ziona wangorifi ba lakhömi ba Ndraono Gizeraeli.', '["Faigi 44:8; 45:5","Sin 33:11; Amaed 19:21; Heb 6:17","Faigi 41:2,25; 44:28"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 1, 'Ae tou ba dadao ba gawu-gawu ba danö, ya''ugö ono alawe banua Mbabeli! Dadao tou ba danö, lö dadaoma zalaŵa, ya''ugö ono Ndrawa Galedaia alawe! Lö''ö sa''ae labe''e töimö "Zerizerize" ba "Nihaogö-haogö fondrorogö".[1]', '["Faigi 13; 26:5","Nakh 3:5; Fam 17:16"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 2, 'Halö gisa ba kisa wakhe! Heta mbalu-balu mbawa, furui lembe! Fahoi gu''i ba waha, törö nidanö!', '["Faigi 13; 26:5","Nakh 3:5; Fam 17:16"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 3, 'Si lö balu-balu dania ndra''ugö, oroma zaila''ö! Ulau sa''ae mbalögu khöu ba samösa lö uhakhösi tödö, [iŵa''ö].[2]', '["Faigi 13; 26:5","Nakh 3:5; Fam 17:16"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 4, 'Sangorifi ya''ita, Yehowa ngahönö döinia, Ni''amoni''ö Ndraono Gezeraeli.', '["Faigi 13; 26:5","Nakh 3:5; Fam 17:16"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 5, 'Dadao, böi hede-hede, ba ae ba zogömi-gömi, ya''ugö ono Ndrawa Galedaia alawe! Lö''ö sa''ae labe''e töimö "Tuhe nöri misa".', '["Faigi 13; 26:5","Nakh 3:5; Fam 17:16"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 6, 'No mofönu ndra''o ba mbanuagu andrö, no u''o''aya dana khögu andrö ba no ululu ba dangau: lö nihakhösiu tödö ya''ira, he si no tohare huwa, ba no öfonoro kalo mbagi sabua andrö khöu.[3]', '["Sakh 1:15","Fam 18:7"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 7, 'Noa sa ömane: Lö tebulö samatörö ndra''odo, tobali lö öbe''e ba dödöu da''ö no mege, lö öfatou-tou tödöu lua-lua.[4]', '["Sakh 1:15","Fam 18:7"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 8, 'Ba iada''e, ba fondrondrongo da''e, ya''ugö nihaogö-haogö mege hadia ia, sidadao lö mangiwa, sanguma''ö tödönia: Ya''odo ba tenga bö''ö! Lö taŵa''ö, lakha mbanua dania ndra''odo ba lö u''ila wa lö ono!', '["Sakh 1:15","Fam 18:7"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 9, 'Ba göna dania ndra''ugö si dua balö andre, lö mudöna-döna, ha ma''öma''ökhö: fa''lö''ono ba fa lakha mbanua ndra''ugö; i''ozumagö ihawui ndra''ugö, lö lai wa no fahöna gelemu khöu, lö lai wa no fahöna wanaka.', '["Sakh 1:15","Fam 18:7"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 10, 'Fangabe''e dödöu ba walösökhi andrö khöu, fa ömane: Lö sangila ya''odo. Fa''atua-tuau ba fa''aboto ba dödöu andrö zamowöhö ya''ugö, tobali ömane dödöu: Ya''odo, ba tenga bö''ö.', '["Sakh 1:15","Fam 18:7"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 11, 'Andrö itörö ndra''ugö famakao, si tebai ötaka elemumö andrö; ihawui ndra''ugö famunu si tebai ötimba, ba i''ogomuzaö göna ndra''ugö famakiko, si lö mudöna-döna.', '["Sakh 1:15","Fam 18:7"]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 12, 'Oroma''ö dakamö andrö, awö gelemu andrö khöu, si no fahöna, serege dödöu, i''otarai iraono ndra''ugö: ma atö ö''ila ölau hadia ia, ma ata''u öbe''e!', '["Fam 18:4 b.t."]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 13, 'No ö''eregesi dödöu wangalungalui lala: ndramufa''aso ira, ndramu''orifi ndra''ugö si no to''ölö wamaigi banua si yaŵa, samaigi-maigi döfi, sangombakha si göna ndra''ugö, ero na tesa''a mbaŵa.[5]', '["Fam 18:4 b.t."]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 14, 'No tobali hulö döla wakhe, ni''a galitö, ira: tebai la''efa''ö nosora ba wa''abölö galitö andrö — tenga sa bo, ba woleu, tenga alitö bawu, si dadao ita ba ngai.', '["Fam 18:4 b.t."]', NULL),
  (3476302, 'OT', 'Yesaya', 47, 15, 'Si manö khöu ba zerege dödöu, i''otarai iraono ndra''ugö — saniaga khöu, ba no laröi, no elungu, itörö lalania zamösana; lö sangorifi ya''ugö.', '["Fam 18:4 b.t."]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 1, 'Mifondrongondrongo da''e, ya''ami ma''uwu Yakobo andrö, nifotöi töi Gizeraeli, ya''ami si otarai gumbu Yuda andrö; si fahölu ba döi Yehowa, ba si lö aefa ba mbewe töi Lowalangi Ndraono Gizeraeli andrö, he ŵa''ae tenga ni''osiduhugö ba tenga soroi ba dödö![1]', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 2, 'Ba mbanua ni''amoni''ö andrö sa''ae moroi döira ba ba Lowalangi Ndraono Gizeraeli abe''e dödöra: Yehowa ngahönö döinia.', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 3, 'Hadia ia föna andrö, ba no ara, me ufarongogö, taroma ligu, ba no u''ombakha''ö khöra. No i''ozumagö ufalua, ba itörö.[2]', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 4, 'Me no u''ila, wa no sabe''e tandro ndra''ugö, wa no amaedola nuo si''öli mbörö du''imö, awö wa no hulö döla garamba gangangou.[3]', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 5, 'Ba no ba götö föna sa''ae u''ombakha''ö khöu: fatua lö alua ufarongogö khöu, ena''ö tebai öŵa''ö: Adu andrö khögu zolau, famaedo nifoe andrö ba famaedo nifahele khögu zanguma''ö.', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 6, 'No örongo — ba nehegö sa''ae fefu! Ba ya''ami — hadia, lö fatehe dödömi? No ufarongogö khöu zi bohou, i''otarai da''e, nibini''ö mege, si lö örai örongo.', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 7, 'Awena iada''e alua, ba tenga ba götö föna; ba irege da''e, ba lö nirongou, fa böi öŵa''ö: Hiza, no tohöna u''ila.', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 8, 'Lö nirongou ba lö ni''ilau, lö si teboka dögi dalingau föna; noa sa u''ila, ha sambalö si faröi manö ndra''ugö ba no "Sanawö" döimö, i''otarai dalu ninau!', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 9, 'Börö döigu andrö, wa utaha wönugu; börö duriagu andrö, wa uhöndrögö, wamaigi ya''ugö, fa böi ufakiko''ö.[4]', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 10, 'Hiza, no ulaugö ndra''ugö, ba tenga si mane firö. No utandraigö ndra''ugö ba galitö famakao andrö.[5]', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 11, 'Börö ndra''o, ya''odo mbörö wolau ya''ia! — wa''abölö wango''aya töigu andrö ena''ö! — ba lö ululu ba mbö''ö wa''ebua döigu andrö.[6]', '["Yer 4:2","Faigi 42:9","MozII 32:9; 33:3; MozV 9:13; 31:27","MozII 34:6; Faigi 43:25","FetI 1:7; Fam 3:18","Faigi 42:8"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 12, 'Mifondrondrongo khögu, ya''ami ma''uwu Yakobo ba ya''ami Iraono Gizeraeli, nikaonigu andrö: Ya''odo, ya''odo zi foföna ba ya''odo göi zafuria![7]', '["MozII 3:14; Faigi 41:4","Sin 39:9","Faigi 45:1","Faigi 61:1","MozV 32:29; Sin 81:14","MozI 22:17"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 13, 'Tangagu andre sa atö zolata tanö, ba kambölögu zamologö banua si yaŵa. Mu''aodo khöra, ba ahori so.[8]', '["MozII 3:14; Faigi 41:4","Sin 39:9","Faigi 45:1","Faigi 61:1","MozV 32:29; Sin 81:14","MozI 22:17"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 14, 'Mi''ondrasi, ya''ami fefu, ba mifondrongondrongo! Ha niha ba khöra zangombakha si mane da''ö? Ni''omasi''ö Yehowa andrö zolau somasi ia, ba Mbabeli andrö; ya''ia zamatörö hukunia ba Ndrawa Galedaia.[9]', '["MozII 3:14; Faigi 41:4","Sin 39:9","Faigi 45:1","Faigi 61:1","MozV 32:29; Sin 81:14","MozI 22:17"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 15, 'Ya''o, ya''odo zanguma''ö ba ya''o göi zogaoni ya''ia, ba ya''o zolohe ya''ia moroi sa ba mofozu nilaunia ube''e.', '["MozII 3:14; Faigi 41:4","Sin 39:9","Faigi 45:1","Faigi 61:1","MozV 32:29; Sin 81:14","MozI 22:17"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 16, 'Mi''ondrasido, mifondrongondrongo da''e I''otarai mböröta, ba tenga ba zogömi-gömi fahuhuo ndra''odo; alua, ba so ndra''odo. Ba iada''e, ba no ifatenge ndra''o So''aya, Yehowa, awö Gehehania.[10]', '["MozII 3:14; Faigi 41:4","Sin 39:9","Faigi 45:1","Faigi 61:1","MozV 32:29; Sin 81:14","MozI 22:17"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 17, 'Imane Yehowa, sangorifi ya''ugö, Ni''amoni''ö Ndraono Gizeraeli andrö: Ya''o, Yehowa, Lowalangiu zamahaö ya''ugö ba zoguna khöu, samasao ya''ugö ba lala nitöröu.', '["MozII 3:14; Faigi 41:4","Sin 39:9","Faigi 45:1","Faigi 61:1","MozV 32:29; Sin 81:14","MozI 22:17"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 18, 'Ena''ö ötöngöni goroisagu andrö, ba hulö hohou nidanö wa''ohahau dödöu ba hulö ndrulu nasi wa''atulömö.[11]', '["MozII 3:14; Faigi 41:4","Sin 39:9","Faigi 45:1","Faigi 61:1","MozV 32:29; Sin 81:14","MozI 22:17"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 19, 'Si mane ene ena''ö ma''uwumö ba madou mbotou andrö, ba si mane fa''oya ngawua nene. Ba töira andrö, ba lö tetayaigö ba lö tebunu ba gametahögu.[12]', '["MozII 3:14; Faigi 41:4","Sin 39:9","Faigi 45:1","Faigi 61:1","MozV 32:29; Sin 81:14","MozI 22:17"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 20, 'Miheta ami ba Mbabeli andrö, mi''oloi, miröi Ndrawa Geledaia, mi''a''iki, mi''ebua''ö li! Mi''ombakha''ö, mituriaigö, miforongogö, irugi ba wondrege danö! Mimane: No i''orifi genoninia ma''uwu Yakobo andrö Yehowa![13]', '["Faigi 52:11; Yer 50:8; Fam 18:4","MozII 17:6; MozIV 20:11","Faigi 57:21"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 21, 'Ba lö owökhi dödöra, me ifatörö ira ba danö si mate; ifalua sa''ae ba gara göra idanö, ifabali gara, fa mangele nidanö![14]', '["Faigi 52:11; Yer 50:8; Fam 18:4","MozII 17:6; MozIV 20:11","Faigi 57:21"]', NULL),
  (3476303, 'OT', 'Yesaya', 48, 22, 'Ba zebua horö, ba lö fa''ohahau dödö, iŵa''ö Yehowa.[15]', '["Faigi 52:11; Yer 50:8; Fam 18:4","MozII 17:6; MozIV 20:11","Faigi 57:21"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 1, 'Mifondrongondrongo khögu, ya''ami hulo, mibe''e mbörö dalingami, ya''ami soi niha ba zaröu! No ikaonido Yehowa, i''otarai me sodo ba dalu ninagu; i''otarai me tabina ndra''odo itötöi döigu.', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 2, 'Ba no ibali''ö si''öli satarö mbewegu: ba lumö dangania ubini''ö ndra''odo; no ibali''ö ono wana salösö ndra''odo: no ibini''ö ndra''o ba naha nono wana andrö khönia.[1]', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 3, 'Ba no imane khögu: Enonigu ndra''ugö, ya''ugö Iraono Gizeraeli, ba ni''oroma''ögu lakhömigu andrö.', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 4, 'Ba no umane: Zaya-zaya gölögu wa''erege dödögu andrö, ba zi lö boto, ba ba zi lö guna uhori gölögu, ba dali Yehowa ba lala khögu, ba khö Lowalangigu mbalazi hadia luogu.', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 5, 'Ba iŵa''ö sa''ae Yehowa, si no mamali''ö enoninia ya''odo, i''otarai dalu ninagu, ena''ö u''ohe mangawuli khönia ma''uwu Yakobo ba ena''ö te''ozaragö khönia Ndraono Gizeraeli — ba nifosumange ndra''o, wamaigi Yehowa ba no tobali fangabölögu Lowalangigu andrö. —', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 6, 'Ba no imane: Wa enonigu ndra''ugö ba wanga''azökhi mado ma''uwu Yakobo andrö, ba no ambö, awö wa ö''ohe mangawuli ni''orifi andrö, Iraono Gizeraeli; ba andrö ubali''ö haga ba niha baero ndra''ugö, ena''ö irugi ba wondrege danö fangorifi andrö khögu.[2]', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 7, 'Imane Yehowa, sangorifi Iraono Gizeraeli, Ni''amoni''öra andrö, khö zi lö ba dödö niha bö''ö fefu, ni''ogorofi niha bö''ö si no tobali sawuyu zamatörö ya''ia: La''ila dania razo ba maoso — la''ila samatörö, ba latuhi danö, börö Yehowa, si lö faröi andrö, börö Ni''amoni''ö Ndraono Gizeraeli andrö, sanuyu ya''ugö mege!', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 8, 'Imane na Yehowa: Ufondrondrongo liu, na baŵa wa''omasi ba utolo''ö, na baŵa wangorifi: ba urorogö ndra''ugö, ba ube''e fawu''usa li ba mado Gizeraeli ndra''ugö, ena''ö ö''azökhi danö ba ena''ö öfuli ba zokhö zi no tanö si mate iada''e.[3]', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 9, 'Ena''ö ömane ba zi so ba gurunga: "Mi''ae baero", ba ba zi so ba zogömi-gömi: "Mitabu ba zohaga"! Ba zinga lala lasöndra göra, ba hili fefu, si no asele mege, manga-manga ira.[4]', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 10, 'Lö olofo ira ba lö owökhi dödöra, lö ilimo ira lumö-lumö andrö ba lö ihandro ira sino; sahakhö tödö ya''ira andrö sa''ae zolohe tangara ba ihaogö wamasao ba gumbu nidanö ya''ira.[5]', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 11, 'Ba fefu hili andrö khögu, ba ubali''ö lala, ba nitamba lala andrö khögu.[6]', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 12, 'Ba so dania zi otarai moroi ba zaröu ba so zi otarai moroi yöu ba moroi ba gaekhula luo, ba so zi otarai danö Sini.', '["Faigi 51:16; Heb 4:12; Fam 1:16","Faigi 42:6","KorII 6:2","Faigi 35:7; Fam 7:16","Faigi 40:4"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 13, 'A''iki, ya''ugö banua si yaŵa, ba anunö, ya''ugö tanö, mi''ebu''a''ö li, ya''ami hili, mifarongogö wa''iki! Irara sa''ae dödö mbanuania Yehowa ba ihakhösi tödö zebua famakao andrö khönia![7]', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 14, 'Ba imane Siona: "No i''erogö ndra''o Yehowa, no olifu Zo''aya ndra''odo!"', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 15, 'Hadia, olifu maö ndra alawe nononia ba mbagi zusu, fa lö ihakhösi tödö nono matua si oroi dalunia? Ba he meziŵa olifu ira [nonora], ba lö''ö zui olifu ndra''o ndra''ugö.[8]', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 16, 'Hiza ba dete dangagu no usura maedo-maedou: si lö aefa ba duduma hörögu gölimö andrö.', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 17, 'No la''ondrasi ono matua khöu, ba laheta ira khöu sanudugö ya''ugö, samakiko andrö.', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 18, 'Faöga höröu, fakhölö''ö ba faigi! No la''owuloi ira fefu, no la''ondrasi ndra''ugö! Faya wa no sauri ndra''o, iŵa''ö Yehowa, na lö öhalö ayau ira fefu, fangehaomö, na lö öbe''e ayau ira, amaedola naya nono nihalö.[9]', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 19, 'Adudula andrö ba si lö niha sa''ae ba danö andrö khöu, si no mufaitoisi, ba ambö dania naha niha [fefu], ba la''aröu''ö ira si manga ya''ugö.', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 20, 'Lamane na dania ba dögi dalingau ono andrö, ba walö''ono mege: Ambö nahagu, fonaha ndra''odo, fa u''ila ube''e nomogu!', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 21, 'Ba ömane dania dödöu: Ha niha zi adonogö khögu da''ö? — si lö ono sa mege ndra''odo, si lö nga''ötö, nitibo''ö ba si lö guna! Ba ha niha zange''ebua khögu da''ö? — ha sa ya''odo zi tosai mege, ba he moroi da''ö?', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 22, 'Andrö imane So''aya, Yehowa: Hiza, ufazaŵa dangagu ba niha solohe adu ba utaru''ö mandrera, soroma ba niha baero, fa la''ohe nonou matua, nilu''i ba lembe, fa la''angalisigö nonou alawe, wolohe khöu.[10]', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 23, 'Razo sa''ae zolaya ono khöu ba fo''omora, fo''omo razo, zamaenu. Lafalögu tou ira ba danö, wangalulu khöu ba lafelai gawu-gawu, si falemba ba gaheu, ena''ö aboto ba dödö, wa no Yehowa ndra''odo, si lö mame''e aila sanötöna khönia.[11]', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 24, 'Hadia, ta''ila musöbi ba danga zabölö nirabunia ba hadia, lasöndra woloi nitaha zabe''e?[12]', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 25, 'Imane sa Yehowa: Alakha lasöbi ba danga zabolö nitahania, ba alakha aefa ba danga zabe''e nirabunia, ba ba zi fa''udu khöu fa''udu ndra''odo, ba ya''o zangorifi onou andrö.', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476304, 'OT', 'Yesaya', 49, 26, 'Ba ube''e ö zamalangögö ya''ugö nagolera ba mabu ira dora ube''e, timba wemabu tuo; ba aboto ba dödö niha fefu dania, wa no ya''odo, Yehowa, zangorifi ya''ugö, ba sangefa''ö ya''ugö, ya''odo, sabölö andrö ba ma''uwu Yakobo.[13]', '["Faigi 44:23","Sin 27:10","Faigi 60:4","Faigi 11:12","Sin 72:9","Faigi 41:2; Mat 12:29","Fam 16:6"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 1, 'Da''ö niŵa''ö Yehowa: Heza so zura wangefa andrö khö ninami fanibogu ya''ia? Ba ba niha zosugilö khögu, ni''amawagu ya''ami! Hiza, si lö atulö andrö khömi mbörö, wa te''amawa ami, ba no olalöŵami andrö mbörö, wa tetibo ninami.[1]', '["MozV 24:1","MozII 14:21; MozIV 11:23; Faigi 59:1","MozII 10:21"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 2, 'Hana wa samösa lö niha, me sodo; hana wa lö sanema li, me mu''ao ndra''odo? Hadia, ambö sa''ae dangagu, ba wangorifi? ba hadia, lö fa''abölö khögu, ba wangefa''ö? Hiza, u''ogo''öisi sa''ae nasi, na uhede-hede''ö, ubali''ö tanö si mate mboto nidanö: obou bakha gi''a, ba wa lö idanö, mate ba wa''owökhi dödö.[2]', '["MozV 24:1","MozII 14:21; MozIV 11:23; Faigi 59:1","MozII 10:21"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 3, 'Ufonukha mbanua si yaŵa salu, ube''e balu-balunia gonigoni.[3]', '["MozV 24:1","MozII 14:21; MozIV 11:23; Faigi 59:1","MozII 10:21"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 4, 'No ibe''e khögu lela nifahaö So''aya, Yehowa, ena''ö u''ila u''okafui dödö zerege tödö huhuogu andrö; ero mahemolu isusugi ndra''odo, ititi dögi dalingagu, ena''ö urongo hadia ia, nifamondrongo nifahaö.[4]', '["Mat 11:28; Yoh 8:28","Mat 26:67; Fil 2:8","Hez 3:8,9","Rom 8:33","Yer 17:4"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 5, 'So''aya, Yehowa zamokai tögi dalingagu, ba ya''odo, ba lö si fatandrodo, lö nibödagu ya''odo.', '["Mat 11:28; Yoh 8:28","Mat 26:67; Fil 2:8","Hez 3:8,9","Rom 8:33","Yer 17:4"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 6, 'No ululu hulugu ba zamözi ya''o, ba bo''ögu ba zanöbi bu dangi-dangigu; lö nibini''ögu bawagu, ba wango''aya ba ba wondrilo.[5]', '["Mat 11:28; Yoh 8:28","Mat 26:67; Fil 2:8","Hez 3:8,9","Rom 8:33","Yer 17:4"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 7, 'Ba no itolodo So''aya, Yehowa: ba lö u''ila wa''aila. Ba andrö u''abe''e''ö mbawagu, fa''abe''e gowe; u''ila sa atö, wa tenga si falukha fa''aila ndra''o.[6]', '["Mat 11:28; Yoh 8:28","Mat 26:67; Fil 2:8","Hez 3:8,9","Rom 8:33","Yer 17:4"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 8, 'No ahatö zolohe ba lala huhuogu andrö! Ha niha zi fasoso khögu? Da mafaoma mafa''aso ndra''aga! Ha niha nudugu! Yamuhatö''ö ia khögu![7]', '["Mat 11:28; Yoh 8:28","Mat 26:67; Fil 2:8","Hez 3:8,9","Rom 8:33","Yer 17:4"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 9, 'Hiza, si fa''awö khögu Zo''aya, Yehowa! — ha niha atö zangetu''ö hukugu? Hiza, ahori adudu ira, hulö mbaru [satua], i''a ira hama!', '["Mat 11:28; Yoh 8:28","Mat 26:67; Fil 2:8","Hez 3:8,9","Rom 8:33","Yer 17:4"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 10, 'Ha niha ba khömi zangata''ufi Yehowa, ba yamufondrondrongo huhuo genoninia andrö: sanörö lala ba zogömi-gömi, si lö haga, ba ya manötöna ba döi Yehowa andrö, ba yamuhalö fangabe''enia Lowalanginia.', '["Mat 11:28; Yoh 8:28","Mat 26:67; Fil 2:8","Hez 3:8,9","Rom 8:33","Yer 17:4"]', NULL),
  (3476305, 'OT', 'Yesaya', 50, 11, 'Ba ya''ami fefu, sangebua alitö, sanunu sulu fanunu nomo — ba mi''ae bakha ba hola-hola galitö andrö ba mifatöfa ami ba zulu andrö, nitunumi! Tangagu andre zamatörö khömi si manö; ba zafökhö khömi mileagö tou ami![8]', '["Mat 11:28; Yoh 8:28","Mat 26:67; Fil 2:8","Hez 3:8,9","Rom 8:33","Yer 17:4"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 1, 'Mifondrondrongo khögu, ya''ami solohi fa''atulö, ya''ami sangalui Yehowa! Mifaigi gowe andrö, börötami ba wanoto ya''ami mege ba bawa mba''a andrö ba nikhao ya''ami![1]', '["Yes 48:1","MozI 12:1","MozI 2:8; Faigi 40:1","Faigi 42:4","Sin 102:27; Mat 24:35","Sin 37:31; Mat 10:28","Faigi 50:9"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 2, 'Mitöngöni [duami] Aberahamo andrö, furugömi ba [awemi] Sara, sadono ya''ami; ha sa samösa ia, me ukaoni ia, ba no ufahowu''ö ia, ba no atö ube''e![2]', '["Yes 48:1","MozI 12:1","MozI 2:8; Faigi 40:1","Faigi 42:4","Sin 102:27; Mat 24:35","Sin 37:31; Mat 10:28","Faigi 50:9"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 3, 'Irara sa''ae Ziona Yehowa, irara fefu gadudula khöra: ibali''ö tanö omasiö danö si mate andrö khöra, ba si lö hadia ia zauri mege, ba ibali''ö kabu Yehowa. Fa''owua-wua dödö ba fa''omuso dödö zi falukha ita ba da''ö, fangandrö saoha gölö ba fanunö, sebua li.[3]', '["Yes 48:1","MozI 12:1","MozI 2:8; Faigi 40:1","Faigi 42:4","Sin 102:27; Mat 24:35","Sin 37:31; Mat 10:28","Faigi 50:9"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 4, 'Mifondrongondrongo khögu ya''ami banuagu, mibe''e mbörö dalingami, ya''ami niha khögu! Me i''otarai ndra''o famahaö, awö huku andrö khögu, haga ba niha baero.', '["Yes 48:1","MozI 12:1","MozI 2:8; Faigi 40:1","Faigi 42:4","Sin 102:27; Mat 24:35","Sin 37:31; Mat 10:28","Faigi 50:9"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 5, 'No ahatö wa''atulö andrö khögu, i''ogomuzaö alua wangorifi andrö khögu ba tangagu andre zanguhuku niha baero. Manötöna khögu hulo misa, ladöna-döna nilau dangagu.[4]', '["Yes 48:1","MozI 12:1","MozI 2:8; Faigi 40:1","Faigi 42:4","Sin 102:27; Mat 24:35","Sin 37:31; Mat 10:28","Faigi 50:9"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 6, 'Mifaöga hörömi miyaŵa ba mbanua si yaŵa ba mifaigi tou danö: taya sa dania mbanua si yaŵa, si mane simbo, ba tanö, ba adudu, si mane baru [satua], ba sowanua yaŵa, ba mate tou, fa''amate ndri mböhö; ba fangorifi andrö khögu, ba si lö aetu ba fa''atulö andrö khögu, ba si lö tebulö.[5]', '["Yes 48:1","MozI 12:1","MozI 2:8; Faigi 40:1","Faigi 42:4","Sin 102:27; Mat 24:35","Sin 37:31; Mat 10:28","Faigi 50:9"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 7, 'Mifondrondrongo khögu, ya''ami si no mangila satulö, ya''ugö banua si so ba dödö oroisa andrö khögu: böi ata''u ami, na la''o''aya ami niha, ba böi tokea ami, na latandraŵaisi ami.[6]', '["Yes 48:1","MozI 12:1","MozI 2:8; Faigi 40:1","Faigi 42:4","Sin 102:27; Mat 24:35","Sin 37:31; Mat 10:28","Faigi 50:9"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 8, 'I''a sa dania ira hama, hulö nukha ba ifemanga mbaru luo ira teatea: ba fa''atulö andrö khögu, ba si lö aetu, ba fangorifi khögu, ba irugi wondrege ma''uwu mitou.[7]', '["Yes 48:1","MozI 12:1","MozI 2:8; Faigi 40:1","Faigi 42:4","Sin 102:27; Mat 24:35","Sin 37:31; Mat 10:28","Faigi 50:9"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 9, 'Faoso ba, faoso ba! Olohuni ndra''ugö fa''abölö, ya''ugö tanga Yehowa andrö! Faoso, si mane ba götö föna, ba nga''ötö me föna sibai! Hadia, tenga ya''ugö zi ö''ötö Rakhaba Miserayi andrö, tenga ya''ugö zangahandro ulö naga andrö?[8]', '["Yob 26:13; Sin 74:13; Faigi 30:7; Hez 29:3","MozII 14:21","Faigi 35:10","Sin 118:6; Faigi 40:6; FetI 1:24","Faigi 40:22","Yob 26:12; Yer 31:35","Faigi 49:2"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 10, 'Hadia, tenga ya''ugö zi ogo''öisi asi, asi andrö, si no ebua? sombali''ö lala niha toyo nasi, ena''ö la''ila latörö ni''orifi andrö?[9]', '["Yob 26:13; Sin 74:13; Faigi 30:7; Hez 29:3","MozII 14:21","Faigi 35:10","Sin 118:6; Faigi 40:6; FetI 1:24","Faigi 40:22","Yob 26:12; Yer 31:35","Faigi 49:2"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 11, 'Mangawuli ni''orifi Yehowa andrö, manunö-nunö ira wangawuli ba Ziona Fa''omuso dödö si lö aetu yaŵara; falukha ira wa''owua-wua dödö ba fa''iki; ba fa''abu dödö ba fangarö-ngarö, ba no taya![10]', '["Yob 26:13; Sin 74:13; Faigi 30:7; Hez 29:3","MozII 14:21","Faigi 35:10","Sin 118:6; Faigi 40:6; FetI 1:24","Faigi 40:22","Yob 26:12; Yer 31:35","Faigi 49:2"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 12, 'Ya''o, ya''odo zondrara tödömi! Ha niha ndra''ugö, wa ö''ata''ufi ena''ö niha, si mate dania, ba ono niha, sariri dania, hulö ndru''u?[11]', '["Yob 26:13; Sin 74:13; Faigi 30:7; Hez 29:3","MozII 14:21","Faigi 35:10","Sin 118:6; Faigi 40:6; FetI 1:24","Faigi 40:22","Yob 26:12; Yer 31:35","Faigi 49:2"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 13, 'Awö wa olifu''ö Yehowa, somböi ya''ugö, samologö banua si yaŵa ba solata tanö, wa fadoro ma''öma''ökhö manizi-nizi ndra''ugö ba wönu zamakao [ya''ugö] andrö, hulö na sangalui famakiko ya''ugö? Ba heza so iadae wönu zamakao andrö?[12]', '["Yob 26:13; Sin 74:13; Faigi 30:7; Hez 29:3","MozII 14:21","Faigi 35:10","Sin 118:6; Faigi 40:6; FetI 1:24","Faigi 40:22","Yob 26:12; Yer 31:35","Faigi 49:2"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 14, 'Lö ara, ba tetoto''ö wesu zi no teköröbu andrö, lö mate ia welalö ba gohokoho ba tenga sambö ö ia.', '["Yob 26:13; Sin 74:13; Faigi 30:7; Hez 29:3","MozII 14:21","Faigi 35:10","Sin 118:6; Faigi 40:6; FetI 1:24","Faigi 40:22","Yob 26:12; Yer 31:35","Faigi 49:2"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 15, 'Me si ndruhu Lowalangiu ndra''odo, ya''odo Yehowa, samodulu asi, fa mu''ugu ndrulunia: Yehowa ngahönö döinia![13]', '["Yob 26:13; Sin 74:13; Faigi 30:7; Hez 29:3","MozII 14:21","Faigi 35:10","Sin 118:6; Faigi 40:6; FetI 1:24","Faigi 40:22","Yob 26:12; Yer 31:35","Faigi 49:2"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 16, 'Ba no ube''e ba mbeweu daroma ligu ba ba lumö dangagu ubini''ö ndra''ugö, ba wamologö banua si yaŵa ba ba wolata tanö [zamuza tö] ba ba wanguma''ö ba mbanua Ziona: Banuagu ami![14]', '["Yob 26:13; Sin 74:13; Faigi 30:7; Hez 29:3","MozII 14:21","Faigi 35:10","Sin 118:6; Faigi 40:6; FetI 1:24","Faigi 40:22","Yob 26:12; Yer 31:35","Faigi 49:2"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 17, 'Faoso ba, faoso ba! Fazaŵa''ö, ya''ugö banua Yeruzalema, si no mamadu ösi mako wönu andrö, nitema ba danga Yehowa: no öbadu nösi dalosu mako andrö, salimbuanö ita, no ösowo.[15]', '["Sin 60:5; 75:9; Yer 25:15","Faigi 47:9","Ngenu 2:41","Faigi 49:26"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 18, 'Ba samösa lö samasao ya''ia iraono andrö, si no tumbu khönia, samösa lö solohe tangania, iraono andrö ni''e''ebuania.', '["Sin 60:5; 75:9; Yer 25:15","Faigi 47:9","Ngenu 2:41","Faigi 49:26"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476306, 'OT', 'Yesaya', 51, 19, 'Dua balö zi no göna ndra''ugö — ha niha zahakhö tödö ya''ugö? Fanudugö awö worasa, ba fa''olofo, awö mbawa zi''öli; he uwisa wondrara tödöu?[16]', '["Sin 60:5; 75:9; Yer 25:15","Faigi 47:9","Ngenu 2:41","Faigi 49:26"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 20, 'No tegaölö tou nono matua khöu, mabu, ba zinga newali fefu, hulö mböhö ba gu''ö, no mabu ira fönu Yehowa andrö, fanegu Lowalangiu.[17]', '["Sin 60:5; 75:9; Yer 25:15","Faigi 47:9","Ngenu 2:41","Faigi 49:26"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 21, 'Andrö fondrondrongo da''e, ya''ugö sebua famakao, si no mabu, ba tenga si mabu tuo!', '["Sin 60:5; 75:9; Yer 25:15","Faigi 47:9","Ngenu 2:41","Faigi 49:26"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 22, 'Da''ö niŵa''ö Zo''aya ya''ugö, Yehowa, Lowalangiu andrö, solohe ba wa''atulö huhuo mbanuania: Hiza, no uheta ba dangau mako zalimbuanö niha, talosu mako wönugu andrö — alakha lö öbadu sa''ae.', '["Sin 60:5; 75:9; Yer 25:15","Faigi 47:9","Ngenu 2:41","Faigi 49:26"]', NULL),
  (3476306, 'OT', 'Yesaya', 51, 23, 'Ba ube''e ba danga zamakao ya''ugö andrö, sanguma''ö khöu: Faöndrö''ö, ena''ö matörö hulumö! — ba tobali öbali''ö tanö tou, öbali''ö lala hulumö, lala zanörö ya''ia.[18]', '["Sin 60:5; 75:9; Yer 25:15","Faigi 47:9","Ngenu 2:41","Faigi 49:26"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 1, 'Faoso, ya''ugö banua Ziona, faoso ba! Olembe wa''abölö! Onukha mbaru ba walöŵa andrö khöu, ya''ugö Yeruzalema, banua ni''amoni''ö andrö! Lö''ö sa''ae ihundragö golayamamö si lö muboto ba he si so da''i.[1]', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 2, 'Anotogö gawu-gawu andrö, si no falemba khöu; fazaŵa''ö, dadao, ya''ugö Yeruzalema. Heta wesu andrö ba mbagiu, ya''ugö ono Ziona alawe, nira''u mege!', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 3, 'Imane sa Yehowa: No mu''amawa ami lö böli, ba nihöli göi ami, lö höli.', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 4, 'Da''ö sa niŵa''ö Yehowa: Ba danö Miserayi numalö misi tou mbanuagu föna, fa si fatewu ira ba da''ö, ba Dawa Asiria andrö, ba no lafakao ira lö sulö.[2]', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 5, 'Ba iada''e, ba hadia nihalögu ba da''e, iŵa''ö Yehowa, me no la''oloi''ö manö mbanuagu andrö lö böli? Fayaŵa zamatörö ya''ira, iŵa''ö Yehowa, ba te''o''aya döigu lö mamalö-malö, ma''öma''ökhö.[3]', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 6, 'Andrö ya aboto ba dödö mbanuagu andrö döigu, ya aboto ba dödöra, na luo da''ö, wa no ya''odo zanguma''ö: Ya''e ndra''o!', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 7, 'Ha lö omasiö ba hili gahe zanuriaigö fa''omuso dödö, sangombakha fa''atulö, solohe turia somuso dödö, sangombakha fangorifi, sanguma''ö ba mbanua Ziona andrö: "Razo Lowalangiu andrö!"[4]', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 8, 'Fondrondrongo, mu''ao zanaro andrö khöu, dozi ira ma''iki, me i''ila höröra wangawuli Yehowa ba Ziona, anehe ira.[5]', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 9, 'Mi''a''ki, ya''ami adudula Yeruzalema dozi, mifarongogö; irara sa''ae dödö mbanunia Yehowa, i''orifi Yeruzalema!', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 10, 'Isa''i''ö da''io mbaru Yehowa ba da''ionia ni''amoni''ö andrö, ba zanehe niha baero andrö, fefu; ba la''ila dania wangorifi andrö khö Lowalangi dozi fondrege danö![6]', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 11, 'Milabu, milabu! miheta ami ba da''ö! Böi mibabaya hadia ia zi ta''unö! Miheta ami khöra! Mihaogö ami, ya''ami solohe fakake andrö khö Yehowa![7]', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 12, 'Tenga sa sida''idai ami, wangeheta ya''ami, ba tenga soloi ami wofanö; mowaö-waö sa''ae fönami Yehowa ba moroi furimi Lowalangi Ndraono Gizeraeli.[8]', '["Faigi 51:17","MozI 46:6; RazII 17:3","Rom 2:24","Faigi 40:9; Nakh 2:1; Rom 10:15","Hez 3:17","Sin 98:2; Luk 3:6","Faigi 48:20; KorII 6:17","MozII 13:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 13, 'Hiza, mofozu wolau genonigu andrö: sanöi dania ia, salaŵa ia, yaŵa sibai!', '["Yoh 19:5","MozII 24:8; Rom 15:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 14, 'Si mane fa''atobali dödö zato mege khöu — wa''atobali mege nga''eu, tenga famaedo niha sa''ae wamaigida, ba tenga sa''ae nga''eu nono niha nga''eunia andrö —,[9]', '["Yoh 19:5","MozII 24:8; Rom 15:21"]', NULL),
  (3476307, 'OT', 'Yesaya', 52, 15, 'si manö dania, wa ato zi tokea soi niha ibe''e; börö ia dania, wa so razo si lö hede-hede, me la''ila zi lö murai mutunö khöra ba me larongo zi lö murai murongo ba khöra.[10]', '["Yoh 19:5","MozII 24:8; Rom 15:21"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 1, 'Ba ha niha zi faduhu tödö ba ni''ombakha''ö khöda, ba tanga Yehowa andrö — ba ha khö tefa''ele''ö![1]', '["Yoh 12:38; Rom 10:16","Faigi 11:1","Sin 22:7; Mar 9:12","Mat 8:17; Yoh 1:29","Rom 4:25; KorI 15:3; FetI 2:24","Mat 26:63; HalZin 8:32,33"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 2, 'No manöi ia, fönania, hulö lewiö, hulö lewiö ba ŵa''a, moroi ba danö si no oköliköli. Lö fonga''eu ba lö famoadu, fa tafaigi ena''ö ia, ba tenga omasiö, wamaigida ya''ia.[2]', '["Yoh 12:38; Rom 10:16","Faigi 11:1","Sin 22:7; Mar 9:12","Mat 8:17; Yoh 1:29","Rom 4:25; KorI 15:3; FetI 2:24","Mat 26:63; HalZin 8:32,33"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 3, 'Ni''ositengagö ia ba ni''erogö niha bö''ö; niha si no fahöna fa''afökhö ba si no to''ölö ba wökhö. Ni''ositengagö ia, irege labalugö mbawara fönania ba fa lö ba dödöda ia.[3]', '["Yoh 12:38; Rom 10:16","Faigi 11:1","Sin 22:7; Mar 9:12","Mat 8:17; Yoh 1:29","Rom 4:25; KorI 15:3; FetI 2:24","Mat 26:63; HalZin 8:32,33"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 4, 'Ba fökhöda nilu''inia ba no ihare''ö khönia zafökhö khöda; ba ba dödöda, ba ni''otu''ö ia, nibözi-bözi Lowalangi ba nifakao.[4]', '["Yoh 12:38; Rom 10:16","Faigi 11:1","Sin 22:7; Mar 9:12","Mat 8:17; Yoh 1:29","Rom 4:25; KorI 15:3; FetI 2:24","Mat 26:63; HalZin 8:32,33"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 5, 'Ba no lalöda sa mbörö, wa tefesokho ia, ba horöda mbörö, wa terasa ia. Ya''ia zolu''i huku, ena''ö sohahau tödö ita, ba moroi ba zokhonia, wa no döhö wökhöda.[5]', '["Yoh 12:38; Rom 10:16","Faigi 11:1","Sin 22:7; Mar 9:12","Mat 8:17; Yoh 1:29","Rom 4:25; KorI 15:3; FetI 2:24","Mat 26:63; HalZin 8:32,33"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 6, 'Dozi ita, ba no elungu, hulö mbiri-biri, ha lalania ni''ila zamösana; ba no ihare''ö khönia Yehowa horöda, dozi ita.', '["Yoh 12:38; Rom 10:16","Faigi 11:1","Sin 22:7; Mar 9:12","Mat 8:17; Yoh 1:29","Rom 4:25; KorI 15:3; FetI 2:24","Mat 26:63; HalZin 8:32,33"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 7, 'Nifakao ia, he ŵa''ae iköwö ia ba itaha ba lö hede-hedenia, hulö nono mbiri-biri ni''ohe ba wanaba, ba hulö zigelo mbiri-biri, si lö hede-hede ba danga zoguti bunia, si manö göi wa lö hede-hedenia.[6]', '["Yoh 12:38; Rom 10:16","Faigi 11:1","Sin 22:7; Mar 9:12","Mat 8:17; Yoh 1:29","Rom 4:25; KorI 15:3; FetI 2:24","Mat 26:63; HalZin 8:32,33"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 8, 'Famununia wamakao andrö ba huku andrö, ba ha niha ba zi faendronga khönia andrö zame''e ba dödö, wa no olalöŵa niwada andrö mbörö, wa tetibo ia moroi ba danö niha sauri, wa göna famunu ia?', '["Mat 27:57; YohI. 3:3; FetI 2:22","Mat 20:28; KorII 5:21","KorI 1:30; Fil 3:9","Mar 15:20; Luk 23:34"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 9, 'Ba ngai zebua horö labe''e lewatönia ba ba ngai zolau si lö sökhi, me no mate ia, he ŵa''ae lö nifazökhinia si lö sökhi ba he ŵa''ae lö falimosa ba mbewenia.[7]', '["Mat 27:57; YohI. 3:3; FetI 2:22","Mat 20:28; KorII 5:21","KorI 1:30; Fil 3:9","Mar 15:20; Luk 23:34"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 10, 'Ba no omasi Yehowa ifufu, ifofökhö. Na no ibe''e sumange fameta horö nosonia, ba i''ila nga''ötö, anau nosonia, ba mofozu ba dangania zomasi Yehowa.[8]', '["Mat 27:57; YohI. 3:3; FetI 2:22","Mat 20:28; KorII 5:21","KorI 1:30; Fil 3:9","Mar 15:20; Luk 23:34"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 11, 'Börö wa''erege dödönia andrö, wa i''ila dania zahono dödönia. Ba wa''aboto ba dödönia andrö, ba ato dania zi falukha fangatulö, ibe''e enonigu satulö andrö, ba lalöra andrö, ba ya''ia zolu''i.[9]', '["Mat 27:57; YohI. 3:3; FetI 2:22","Mat 20:28; KorII 5:21","KorI 1:30; Fil 3:9","Mar 15:20; Luk 23:34"]', NULL),
  (3476308, 'OT', 'Yesaya', 53, 12, 'Andrö ube''e dana khönia ba zato andrö, ba ya''ia zamaosa ba zato ahulua ba wanuwö, böli gölönia, me no ibe''e ni''etu''ö nosonia ba me no tebe''e awö zolalö ia, lö lai wa no ilu''i horö sato andrö, awö wa no mangandrö ia salahi zolalö.[10]', '["Mat 27:57; YohI. 3:3; FetI 2:22","Mat 20:28; KorII 5:21","KorI 1:30; Fil 3:9","Mar 15:20; Luk 23:34"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 1, 'Owua-wua''ö dödöu, ya''ugö si lö ono, si lö irai madono! A''iki ba lau liwaliwa, ya''ugö si lö irai afökhö hulu! Noa sa''ae oya nono matua khö zi lö awö-awö, moroi ba zi no muhalö donga, iŵa''ö Yehowa.[1]', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 2, 'Ebolo''ö naha noseu, alakha ebolo sibai zagö nahiau andrö, labe''e; böi tenaŵa! Anau''ö gasönia, aro''ö wanaru''ö![2]', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 3, 'Öfa''ese sa dania ndra''ugö, ba gambölö ba ba gabera: Labe''e dania barö mbawara soi [bö''ö] ma''uwumö andrö ba lafuli lafo''ösi mbanua si lö niha sa''ae.', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 4, 'Böi busi dödöu, tenga nibe''e ba zi lö boto ndra''ugö, ba böi aila''ö, tenga sa safusi bawa ndra''ugö dania. Olifu''ö sa''ae dania wa''ailau andrö, me ono alawe na ndra''ugö, ba lö''ö sa''ae itörö tödöu wa''ailamö andrö, me lakha mbanua ndra''ugö.[3]', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 5, 'Fo''omou sa''ae zomböi ya''ugö andrö: Yehowa ngahönö döinia; ba sangorifi ya''ugö Ni''amoni''ö Ndraono Gizeraeli andrö: Lowalangi zi sagörö uli danö döinia.[4]', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 6, 'Noa sa ikaoni ndra''ugö Yehowa, amaedola ndra alawe ni''erogö mege ba si no abu sibai tödö; ba si bohou muhalö —, ba hadia, ni''erogö da''ö? iŵa''ö Lowalangi.', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 7, 'Duhu, no u''erogö ndra''ugö, si lö arara, ba u''ebua''ö wa''ahakhö dödögu, wangahatö''ö ya''ugö khögu.', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 8, 'Me tesao wönugu, ba no ubini''ö mbawagu khöu, si lö arara, ba ufuli uhakhösi tödö ndra''ugö, fa''ebua dödö si lö aetu, iŵa''ö sangorifi ya''ugö andrö, Yehowa.', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 9, 'Timba wa''anönö danö idanö andrö, me luo Noakhi, khögu da''ö: si mane fahölusagu andrö, wa lö tola ifuli inönöi danö idanö andrö khö Noakhi, si manö wahölusagu, wa lö''ö sa''ae mofönudo khöu, awö wa lö''ö sa''ae utegu''ö.[5]', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 10, 'Alakha sa''ae aruru hili ba alakha mangiwa hili-hili, ba lö''ö sa tebulö khöu wa''ebua dödögu ba tebai mangiwa wawu''usa li andrö khögu, iŵa''ö sahakhö tödö khöu, Yehowa andrö.[6]', '["Faigi 49:20; Gal 4:27","Faigi 33:20","Hez 16:8","Faigi 62:5","MozI 9:11","Hez 37:26"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 11, 'He ya''ugö sabu tödö, nifaheu nangi, si lö fondrara tödö! Hiza, ube''e latalatamö weremata manika ba ufotoyo ndra''ugö feremata nila.[7]', '["Fam 21:19","Faigi 60:17; Yer 31:34; Yoh 6:45"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 12, 'Ba yasia ube''e mbumbu gölimö ba bawa gölimö, ba feremata ita, be fefu gowe nolamö andrö, ba batu indra''indra.', '["Fam 21:19","Faigi 60:17; Yer 31:34; Yoh 6:45"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 13, 'Ba onou fefu, ba nifahaö Yehowa; ebua wa''ohahau dödö nonou andrö.[8]', '["Fam 21:19","Faigi 60:17; Yer 31:34; Yoh 6:45"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 14, 'Fa''atulö dania latalatamö, fangaro; ya aröu khöu wamakao! alakha lö ata''u''ö ba ya aröu gameta''uö, lö''ö sa ihatö''ö ia khöu.', '["Fam 21:19","Faigi 60:17; Yer 31:34; Yoh 6:45"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 15, 'Ba na so zi fa''udu khöu, ba ma''ifu tenga nilau dödögu: gofu ha niha zi fasöndra khöu, ba si tekiko!', '["Fam 21:19","Faigi 60:17; Yer 31:34; Yoh 6:45"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 16, 'Hiza, ya''o zomböi siambu andrö, si duru-duru''ö si''öli ba galitö, samazökhi fangöna, nekhe-nekhe dangania; ya''o göi zomböi samakiko, ba wamufu ya''ia.', '["Fam 21:19","Faigi 60:17; Yer 31:34; Yoh 6:45"]', NULL),
  (3476309, 'OT', 'Yesaya', 54, 17, 'Fefu wangöna, nibago ba wamakiko ya''ugö, ba si lö boto ba dozi lela si fa''udu khöu, hadia ia huhuo, ba ö''ila ölaŵa. Da''ö dana khö genoni Yehowa andrö, awö wangatulö andrö, si falukha ira khögu, iŵa''ö Yehowa!', '["Fam 21:19","Faigi 60:17; Yer 31:34; Yoh 6:45"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 1, 'He ya''ami, sowökhi tödö, fefu, mi''ondrasi nidanö! Ba ya''ami si lö balazo, mi''aine mi''öli mböra ba mi''a! Mi''aine, mi''öli mböra, ba agu ba susu, saoha gölö![1]', '["Yoh 7:37; Fam 22:17","Fam 1:5","Mat 4:16; Rom 10:20","Mat 7:7","Sin 130:7; Hez 18:27; 33:19"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 2, 'Hana wa edöna mitulo gana''a, böli zi tenga ö, ba ölömi, ba zi tebai abuso ami? Ba mifondrondrongo khögu, ba misöndra ömi zi sökhi ba möi fangokafu dödömi zatabö.', '["Yoh 7:37; Fam 22:17","Fam 1:5","Mat 4:16; Rom 10:20","Mat 7:7","Sin 130:7; Hez 18:27; 33:19"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 3, 'Mibe''e mbörö dalingami ba mi''ondrasi ndra''odo! Mifondrondrongo, ena''ö tedou nosomi! Ba ulau fawu''u li khömi, si lö tebulö: — fa''ebua dödögu andrö khö duami Dawido, si tebai awu''a!', '["Yoh 7:37; Fam 22:17","Fam 1:5","Mat 4:16; Rom 10:20","Mat 7:7","Sin 130:7; Hez 18:27; 33:19"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 4, 'Hiza, no ube''e samaduhu''ö ia, ba niha baero salaŵa ba samatörö soi niha.[2]', '["Yoh 7:37; Fam 22:17","Fam 1:5","Mat 4:16; Rom 10:20","Mat 7:7","Sin 130:7; Hez 18:27; 33:19"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 5, 'Hiza, ökaoni dania soi si lö örai mila, ba la''ondrasi ndra''ugö niha si lö irai fa''ila li khöu. Börö Yehowa, Lowalangiu andrö, Ni''amoni''ö ndraono Gizeraeli andrö, me no ifolakhömi ndra''ugö.[3]', '["Yoh 7:37; Fam 22:17","Fam 1:5","Mat 4:16; Rom 10:20","Mat 7:7","Sin 130:7; Hez 18:27; 33:19"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 6, 'Mi''alui Yehowa, fatua i''oro''ö ia, mi''angaröfi li ia, fatua ahatö ia.[4]', '["Yoh 7:37; Fam 22:17","Fam 1:5","Mat 4:16; Rom 10:20","Mat 7:7","Sin 130:7; Hez 18:27; 33:19"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 7, 'Sebua horö, ba yamuröi lalania andrö, ba si lö atulö ba yamuböhöli nikhoi dödönia, yamufuli ia khö Yehowa, ba ihakhösi tödö; ba khö Lowalangida, sangöhöna dania fame''e aefa horönia.[5]', '["Yoh 7:37; Fam 22:17","Fam 1:5","Mat 4:16; Rom 10:20","Mat 7:7","Sin 130:7; Hez 18:27; 33:19"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 8, 'Me no imane Yehowa: Bö''ö gera-eragu ba bö''ö gera-erami, bö''ö lalami ba bö''ö lalagu.[6]', '["Rom 11:33","Nga''öt. 16:33; Sin 96:12; 98:8; Faigi 48:20"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 9, 'Fa''alaŵa mbanua si yaŵa yaŵa danö wa''alaŵa lalagu moroi ba lalami, ba si manö wa''alaŵa gera-eragu, moroi ba gera-erami.', '["Rom 11:33","Nga''öt. 16:33; Sin 96:12; 98:8; Faigi 48:20"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 10, 'Hulö deu andrö, si otarai mbanua si yaŵa ba si lö mangawuli ba da''ö, — na lö nibasöinia tanö, fangatabö zinanö, na lö nibe''enia auri zinanö wangasogö tanömö ba wanaru ba balazo, ni''a —', '["Rom 11:33","Nga''öt. 16:33; Sin 96:12; 98:8; Faigi 48:20"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 11, 'si manö daroma ligu andrö, si otarai mbawagu: lö mangawuli khögu lö boto, atö na no mofozu zomasido ibe''e ba na no ifalua ba nifa''ohe''ögu ya''ia!', '["Rom 11:33","Nga''öt. 16:33; Sin 96:12; 98:8; Faigi 48:20"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 12, 'Fa''omuso dödö sa khömi ba wofanö ba tefasao ami, lö hadia ia. Ma''iki hili ba hili-hili fönami, ebua li, ba molau tatawo fefu hogu geu ba mbenua.[7]', '["Rom 11:33","Nga''öt. 16:33; Sin 96:12; 98:8; Faigi 48:20"]', NULL),
  (3476310, 'OT', 'Yesaya', 55, 13, 'Auri sa''ae ndruria salahi manaze, ba salahi lato, ba malimbi. Ba tobali fangebua döi Yehowa, tandra si lö tebulö, si tebai mate.', '["Rom 11:33","Nga''öt. 16:33; Sin 96:12; 98:8; Faigi 48:20"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 1, 'Da''ö niŵa''ö Yehowa: Mitörö lala ba milau zatulö. Lö ara tö, ba so wangorifi andrö khögu ba tefa''ele''ö wa''atulö andrö khögu.[1]', '["Sin 82:3; Mat 3:2","MozII 20:8; Yer 17:21","Fam 1:5","Efes 2:11–22","Mat 21:13"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 2, 'Ya ahowu niha solo''ö da''e ba ono niha, si lö mamöhöli: samaigi fa böi telau zalakha ba luo sabato, ba sanaha tangania, fa böi ibabaya si lö sökhi![2]', '["Sin 82:3; Mat 3:2","MozII 20:8; Yer 17:21","Fam 1:5","Efes 2:11–22","Mat 21:13"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 3, 'Ba niha bö''ö andrö, si olembai Yehowa, ba böi yamuŵa''ö tödönia: Lö zi lö itibo''ö ndra''o banuania Yehowa! ba nikhai andrö, ba böi yamuŵa''ö: Hiza, töla geu si no mate ndra''odo!', '["Sin 82:3; Mat 3:2","MozII 20:8; Yer 17:21","Fam 1:5","Efes 2:11–22","Mat 21:13"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 4, 'Da''ö sa''ae niŵa''ö Yehowa: Nikhai andrö, si amoni''ö luo sabato andrö khögu ba sangalui somasi ndra''o ba si lö mamöhöi fawu''usa li andrö khögu,[3]', '["Sin 82:3; Mat 3:2","MozII 20:8; Yer 17:21","Fam 1:5","Efes 2:11–22","Mat 21:13"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 5, 'ba ufoharefa ba gosali khögu ba yomo ba mbanuagu, ba ufotöi, si sökhi moroi ba nono matua ba moroi ba nono alawe: töi si lö tebulö ba si tebai mate ube''e ba zamösana.', '["Sin 82:3; Mat 3:2","MozII 20:8; Yer 17:21","Fam 1:5","Efes 2:11–22","Mat 21:13"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 6, 'Ba niha bö''ö andrö, si olembai Yehowa, ba wangai halöŵönia ba ba wangomasi''ö töi Yehowa, ba we''amöi enoninia: dozi si lö mame''e tekiko luo sabato ba si lö mamöhöi fawu''usa li andrö khögu,[4]', '["Sin 82:3; Mat 3:2","MozII 20:8; Yer 17:21","Fam 1:5","Efes 2:11–22","Mat 21:13"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 7, 'ba u''ohe mangawuli ba hili ni''amoni''ö andrö khögu, ba omuso dödöra ba nomo wangandrö andrö khögu ube''e: somasido dania zumange nitunu ba sumange nitaba, khöra, ba naha wame''e sumange andrö khögu; omo wangandrö ba niha fefu sa döi nomogu andrö dania.[5]', '["Sin 82:3; Mat 3:2","MozII 20:8; Yer 17:21","Fam 1:5","Efes 2:11–22","Mat 21:13"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 8, 'Da''ö niŵa''ö Zo''aya, Yehowa, sangozaragö sizaewe Iraono Gizeraeli: Utohugö na wangozaragö, ni''orudugö ba ni''ozaragö andrö.[6]', '["Faigi 11:12; Yoh 10:16","Faigi 43:20","Yer 6:13; 8:10"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 9, 'Mi''owuloi ami, ya''ami saliŵa-liŵa ba mbenua, mi''aine, ba wemanga, ya''ami utu ndru''u barö gatua![7]', '["Faigi 11:12; Yoh 10:16","Faigi 43:20","Yer 6:13; 8:10"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 10, 'Sanaro andrö khöra, ba no au''a, dozi ira, ba lö fa''aboto ba dödö: no fadoro asu si lö lili, si tebai mukau; no lafadölö ira tou, mangifingifi, alau-lau hörö.', '["Faigi 11:12; Yoh 10:16","Faigi 43:20","Yer 6:13; 8:10"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 11, 'Ba asu andrö, ba sanani, tebai abuso, — ba ya''ira andrö, kubalo andrö, ba tebai labe''e mbörö dalingara. Itörö lalania zamösana, dozi lafaigi heza lasöndra harera, no fagölö-gölö.[8]', '["Faigi 11:12; Yoh 10:16","Faigi 43:20","Yer 6:13; 8:10"]', NULL),
  (3476311, 'OT', 'Yesaya', 56, 12, '[Lamane]: "Mitabu, da''uhalö nagu ba tabadu zi mabu ita. Ba si mane ma''ökhö göi mahemolu, niforege!"', '["Faigi 11:12; Yoh 10:16","Faigi 43:20","Yer 6:13; 8:10"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 1, 'Tekiko zatulö tödö, ba lö sabu tödö ba da''ö. Mate manö zadölö tödö, ba lö sanöngöni, wa no börö walösökhi andrö, ba niha, wa mate manö zatulö tödö.[1]', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 2, 'Ohahau dödönia we''amöi barö danö: mörö ira ba dufora, ya''ira si no manörö lala sadölö.[2]', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 3, 'Ba ya''ami, ba mi''ae ba da''e, ya''ami ono zebua elemu ira alawe, ya''ami nga''ötö zohorö; sabao ninami.[3]', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 4, 'Ha niha atö ni''ig-i''igi''ömi? Ha khö mifaboka mbawami, ha khö mi''oro''ö lela? Hadia, tenga ono si no fabali khö namara ami, nga''ötö walimosa andrö?[4]', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 5, 'Si no abao ba mbörö ndruria, barö geu sobulu fefu; sanaba bagi nonora ba ndraso, ba ba dögi narö gara misa.[5]', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 6, 'No öhalö khöu ösa gara salösö ba ndraso, ya''ia nituyumö tana khöu! No öfaduwa khönia zumange nibadu, no öbe''e zumange ni''a.', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 7, 'Hadia, utehe da''ö? Ba zuzu hili sebua ba salaŵa öbe''e wörömamö: ba da''ö göi möi''ö yaŵa, ba wanaba sumange.', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 8, 'Ba gero lagö mbawandruhö ba ba zi tambai gehomo öbe''e dandra andrö khöu, noa sa öheta gambalamö, wangerogö ya''odo, mörö''ö ba dufou, öbologö, mamagölö ndra''ugö khöra: omasi''ö na mörö ira ba ngaiu, öfaigi zogawi tanga ya''ugö.', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 9, 'No möi''ö khö razo andrö, no ö''ohe wanikha, oya öfake dalu-dalu nigule''ö, ba irugi ba zaröu öfatenge zinengeu, irugi zabakha si tou, ba mbanua tou.', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 10, 'Ba wa''asese wangörö-ngörö andrö erege dödöu, ba lö''ö sa öŵa''ö: Ubato! Tenga si mate na dangau, ö''ila, ba ikhamö na fa''abölöu.[6]', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 11, 'Ha niha atö zaila''ö, ha niha zata''u ndra''ugö, wa si falimo ndra''ugö, wa olifu''ö ndra''odo, wa lö ba dödöu sa''ae ya''o? Tenga si manö: me lö hede-hedegu, si no arara, — andrö wa lö''ö sa''ae ö''ata''ufi ndra''odo![7]', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 12, 'Da''ufarongogö wa''atulö andrö khöu, ba nilaumö andrö, — ba si lö guna khöu.', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 13, 'Na mangarö-ngarö''ö, ba ndramu''orifi''ö nihönamö andrö [adu andrö]: ba ahori humombo ba nangi, i''oloi''ö oho. Ba si saŵa ya''odo, ba khönia danö, khönia hili ni''amoni''ö andrö khögu![8]', '["Sin 12:2; Mikh 7:2","Faigi 26:20; Fam 14:13","Hez 16:12 b.t.","Yob 16:10; Sin 35:21","RazII 16:4","Fam 3:17","Faigi 42:14","Sin 37:9–11; Mat 5:5"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 14, 'Ba andrö imane Mifolala, mifolala! Mihaogö lala! Miheta zi fatimba ba lala mbanuagu andrö![9]', '["Faigi 62:10; Mat 3:3","Sin 51:19; 113:5; Faigi 6:3; 61:1; Fam 4:8","Sin 103:9","Hez 2:17","Faigi 48:22"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 15, 'Da''ö sa niŵa''ö zalaŵa andrö sebua lakhömi, si lö tebulö ba dadaoma zalaŵa, sotöi "Ni''amoni''ö," [imane]: Ba zalaŵa yaŵa so nahiagu ba ni''amoni''ö ndra''o, ba ba si no arasa tödö ba si lö fayaŵasa dödö, ba udou''ö wangorifi zi lö fayaŵasa dödö ba ufuli u''orifi dödö zi no arasa![10]', '["Faigi 62:10; Mat 3:3","Sin 51:19; 113:5; Faigi 6:3; 61:1; Fam 4:8","Sin 103:9","Hez 2:17","Faigi 48:22"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 16, 'Tenga si lö mamalö-malö watahisagu ba tenga si lö aetu wönugu, ariri sa ena''ö fönagu gehehara, awö noso andrö, niwöwöigu.[11]', '["Faigi 62:10; Mat 3:3","Sin 51:19; 113:5; Faigi 6:3; 61:1; Fam 4:8","Sin 103:9","Hez 2:17","Faigi 48:22"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 17, 'Börö lalönia andrö, fa''omasinia gana''a, wa no mofönu ndra''o, ba no u''otu''ö ia; no ubini''ö ndra''o ba sofönu ndra''o, ba no i''erogö [ndra''o], itörö lala somasi ia.', '["Faigi 62:10; Mat 3:3","Sin 51:19; 113:5; Faigi 6:3; 61:1; Fam 4:8","Sin 103:9","Hez 2:17","Faigi 48:22"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 18, 'No u''ila lalania andrö, ba edöna ndra''o u''orifi ia; u''ohe dangania ba urara dödönia, tödö zabu tödö andrö khönia.', '["Faigi 62:10; Mat 3:3","Sin 51:19; 113:5; Faigi 6:3; 61:1; Fam 4:8","Sin 103:9","Hez 2:17","Faigi 48:22"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 19, 'Ya''ia sangasogö bua-bua mbewe: "Fa''ohahau dödö, fa''ohahau dödö, he ba zahatö ba he ba zaröu," iŵa''ö Yehowa, "ba u''orifi ira."[12]', '["Faigi 62:10; Mat 3:3","Sin 51:19; 113:5; Faigi 6:3; 61:1; Fam 4:8","Sin 103:9","Hez 2:17","Faigi 48:22"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 20, 'Ba sebua horö andrö, ba no hulö nasi sebua dulu, tebai sa''ae ahono, ba iohe-ohe miyaŵa dai mba ba solotu dulunia andrö.', '["Faigi 62:10; Mat 3:3","Sin 51:19; 113:5; Faigi 6:3; 61:1; Fam 4:8","Sin 103:9","Hez 2:17","Faigi 48:22"]', NULL),
  (3476312, 'OT', 'Yesaya', 57, 21, 'Ba zebua horö, ba lö fa''ohahau dödö, iŵa''ö Lowalangigu.[13]', '["Faigi 62:10; Mat 3:3","Sin 51:19; 113:5; Faigi 6:3; 61:1; Fam 4:8","Sin 103:9","Hez 2:17","Faigi 48:22"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 1, 'Ao, forege; böi bato! Ebua''ö liu, amaedola li dorofe, si terongo ba zaröu; ombakha''ö ba mbanuagu laröra, ba ba ma''uwu Yakobo farongogö horöra?', '["Sakh 7:5; Mat 6:16"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 2, 'Ba lazofu-zofu zui ligu, bongi ma''ökhö, omasi ira la''ila lala andrö khögu! Si mane banua si no molau satulö ba si lö irai mondröi lala Lowalangira andrö: la''andrö khögu u''atulö''ö wangetu''ö huku, omasi ira na to''ele Lowalangi. [Lamane]:', '["Sakh 7:5; Mat 6:16"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 3, '"Hana wa mamoni ba gö ndra''aga, ba lö ö''ila, ba hana wa mafakao ndra''aga, ba lö sanehe ndra''ugö?" Ba na luo mamoni ami, ba mihalö-halö göi halöŵömi, ba mifakao zohalöŵö khömi, fefu!', '["Sakh 7:5; Mat 6:16"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 4, 'Ba wasosota ba ba wagua-guasa aekhu wamonimi andrö, ba ba wabagosa; famonimi ma''ökhö, ba tenga ena''ö tefondrondrongo si yaŵa wangandrömi andrö.', '["Sakh 7:5; Mat 6:16"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 5, 'Hadia, si manö maö wamoni somasi ndra''o: na ifakao ia niha ma''ökhö? na ikaöndrö ia, hulö kölöyömö ba na i''anufo goni ba awu — hadia da''ö öfotöi famoni, da''ö öfotöi luo somasi Yehowa?[1]', '["Sakh 7:5; Mat 6:16"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476313, 'OT', 'Yesaya', 58, 6, 'Hadia, tenga da''ö wamoni somasi ndra''o: na latoto''ö wesu zi lö horö ba na laburusi mböbö galo mbagi andrö, na la''efa''ö nifakao ba na larasa galo mbagi, fefu?', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 7, 'Ena''ö öfosasi göu ba zolofo ba ena''ö ö''ohe yomo khöu zi numana, si lö nahia; na ö''ila zi lö balu-balu, ba ena''ö na öfonukha, ba fa böi ö''erogö wöfö nösiu?[2]', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 8, 'Awena dania tumbu haga khöu si mane fa''atumbu zi moluo, ba mangaösö wa''adöhö wökhöu; mowaö-waö fönau wa''atulömö, ba lakhömi Yehowa moroi furiu ba lala.[3]', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 9, 'Ba mu''ao ndra''ugö ba itema liu Yehowa; ö''angaröfi li ia, ba imane: Ya''e ndra''odo! Na öbato wangöhöndrögö awöu, na lö''ö sa''ae ötuturu niha, ba na öbato wanandraŵaisi awöu.', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 10, 'Na öbe''e ba zolofo mbalazou [somasi''ö] ba na örara dödö zebua famakao, ba humaga haga andrö khöu ba zogömi-gömi, ba hulö haga ba zi laluo zogömi-gömi andrö khöu dania.', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 11, 'Ba lö ibato wamasao ya''ugö Yehowa; i''abusoi''ö ndra''ugö ba danö si no oköliköli, i''abe''e''ö dölau. Ba tobali hulö kabu nihaogö famatörö idanö ndra''ugö, hulö gumbu, si lö aetu idanö.', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 12, 'Ba awöu andrö, ba la''otomosi zui gadudula andrö, si no arara: dayadaya ba götö föna öfuli öfa''anö. Ba labe''e töimö "Zangazökhi sadudu" ba "Sangehao lala, ena''ö ta''ila ta''iagö da''ö."[4]', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 13, 'Na lö ölau zalakha ba zabato, fa böi öhalö halöŵöu, na luo ni''amoni''ö andrö khögu; na öbe''e töi zabato "omasiö" ba töi luo ni''amoni''ö andrö khö Yehowa "nifosumange" ba na öfosumange ia, fa böi öhalö halöŵöu ba fa böi ölau nilaumö, awö deatea mbewe andrö. —', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476313, 'OT', 'Yesaya', 58, 14, 'Ba tobali omasiö khöu Yehowa, ba ufatörö ndra''ugö ba zohili tanö, ba ube''e öu dana khö wurugömö Yakobo andrö. Hiza, no taroma li Yehowa![5]', '["Hez 18:7; Mat 25:35; Yak 1:27","Sin 37:6; 97:11; 112:4; Faigi 32:12","Faigi 61:4","MozV 32:13"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 1, 'Hiza, tenga sambö danga Lowalangi, ba wangorifi, ba tenga safiso ia, fa lö ifondrondrongo.[1]', '["Sin 94:9; Faigi 50:2","Yoh 9:31","Faigi 1:15","Yob 15:35; Sin 7:15","Yob 8:14","Yud a. 23","Amaed 1:16; Rom 3:15–17"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 2, 'Ha olalöŵami zamabali ya''ami khö Lowalangimi, ba horömi andrö mbörö, wa ibini''ö mbawania khömi, ba wa lö mamondrongo.[2]', '["Sin 94:9; Faigi 50:2","Yoh 9:31","Faigi 1:15","Yob 15:35; Sin 7:15","Yob 8:14","Yud a. 23","Amaed 1:16; Rom 3:15–17"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 3, 'Me no oi do dangami ba me no falemba ba durumi lalö; no faya wehede mbewemi, ba lelami andrö, ba no ilau zi lö sökhi.[3]', '["Sin 94:9; Faigi 50:2","Yoh 9:31","Faigi 1:15","Yob 15:35; Sin 7:15","Yob 8:14","Yud a. 23","Amaed 1:16; Rom 3:15–17"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 4, 'Lö satulö fangombakha hadia ia, ba lö sanörö lala, wangetu''ö huku: — ba zi lö boto abe''e dödöra, ba lalau waya; abeto ira famakao, ba la''adonogö wamakiko![4]', '["Sin 94:9; Faigi 50:2","Yoh 9:31","Faigi 1:15","Yob 15:35; Sin 7:15","Yob 8:14","Yud a. 23","Amaed 1:16; Rom 3:15–17"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 5, 'Lafaukhu gadulo gulö ba lasoso gu''ö galaŵa; si manga gadulo andrö khöra, ba mate, ba na laboto, ba alua nono gulö.[5]', '["Sin 94:9; Faigi 50:2","Yoh 9:31","Faigi 1:15","Yob 15:35; Sin 7:15","Yob 8:14","Yud a. 23","Amaed 1:16; Rom 3:15–17"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 6, 'Tenga baru dania mbeweŵö andrö khöra, tebai tahalö balu-baluda nilaura; folaura andrö, ba no folau famakiko, famalangögö halö-halöŵö dangara.[6]', '["Sin 94:9; Faigi 50:2","Yoh 9:31","Faigi 1:15","Yob 15:35; Sin 7:15","Yob 8:14","Yud a. 23","Amaed 1:16; Rom 3:15–17"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 7, 'Ba zi lö sökhi isaŵa ahera ba alio ira, ba wame''e aduwa ndro zi lö horö; era-era ba wamakiko gera-erara; fanudugö ba famufu ba lalara.[7]', '["Sin 94:9; Faigi 50:2","Yoh 9:31","Faigi 1:15","Yob 15:35; Sin 7:15","Yob 8:14","Yud a. 23","Amaed 1:16; Rom 3:15–17"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 8, 'Lala wa''atulö, ba lö la''ila; lö satulö ba döröŵara andrö; no labila''ö khöra lalara andrö, ba ba zanörö ya''ia, ba samösa lö sangila fa''atulö.', '["Sin 94:9; Faigi 50:2","Yoh 9:31","Faigi 1:15","Yob 15:35; Sin 7:15","Yob 8:14","Yud a. 23","Amaed 1:16; Rom 3:15–17"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 9, 'Andrö wa no aröu khöda zadölö lala, ba lö ikhamö ita fa''atulö. Tadöna-döna haga, ba hiza zogömi-gömi; tadöna-döna wa''amoluo — ba tadörö-dörö zi bongi.[8]', '["Faigi 5:30","Yob 10:21","Faigi 38:14","Yer 14:7"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 10, 'Tabaya-bayaisi, hulö niha sau''a, ba zinga göli, hulö zi lö hörö, wa tabaya-bayaisi misa; ba zi laluo manendre ita, hulö na ogömi-gömi na; hulö zi mate ita bakha ba hunö zi lö fökhöfökhö.[9]', '["Faigi 5:30","Yob 10:21","Faigi 38:14","Yer 14:7"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 11, 'Ba mundröndröndröndrö ita, hulö mberua, ba fakore hulö marafadi, lö mamalö-malö. Tadöna-döna zadölö lala, ba lö''ö; tadöna-döna wangorifi, ba no aröu khöda.[10]', '["Faigi 5:30","Yob 10:21","Faigi 38:14","Yer 14:7"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 12, 'Noa sa fahöna golalöŵama khöu, ba i''ombakha''ö ndra''aga horöma: aboto sa''ae ba dödöma lalöma andrö, ba no ma''ila zalama.[11]', '["Faigi 5:30","Yob 10:21","Faigi 38:14","Yer 14:7"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 13, 'No ta''erogö Yehowa, no falimo ita khönia; no tabato wolo''ö khö Lowalangida; famalangögö ba fa''erosa huhuoda; no abeto dödöda fehede faya, ba tafalua moroi bakha.', '["Faigi 5:30","Yob 10:21","Faigi 38:14","Yer 14:7"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 14, 'Tetimba mifuri zadölö lala, ba ba zaröu so wa''atulö; fa''aduhu andrö, ba manendre ba kade; ba fa''adölö, ba tebai isöndra mbawa lala.', '["Faigi 5:30","Yob 10:21","Faigi 38:14","Yer 14:7"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 15, 'Ba tobali lö falukha zi duhu, ba si lö mombambaya si lö sökhi, ba no aekhula zorabu. Me i''ila da''ö Yehowa, ba fatuwu khönia, wa lö satulö sa''ae.', '["Faigi 5:30","Yob 10:21","Faigi 38:14","Yer 14:7"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 16, 'Ba i''ila wa samösa lö niha, ba ahöli-höli dödönia, me lö sombelegö ya''ia mena''ö, awena ilau manö tangania, ba fa''atulönia zanolo ya''ia.[12]', '["Faigi 63:5","Efes 6:17; TesI 5:8","Rom 11:26"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 17, 'Ba i''angöröba wa''atulö ba i''okofia detenaulu fangorifi andrö; i''obaru mbaru ba wolau balö ba i''olohuni ia fönu baru sebua khönia.[13]', '["Faigi 63:5","Efes 6:17; TesI 5:8","Rom 11:26"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 18, 'Isulöni nilau andrö: fönu ba nudunia ba sulö ba nemalinia; isulöni ba hulo andrö nilaura.', '["Faigi 63:5","Efes 6:17; TesI 5:8","Rom 11:26"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 19, 'Ba la''ata''ufi dania döi Yehowa tanö ba gaekhula luo, ba lakhöminia tanö ba gatumbukha; itörö sa dania, hulö nidanö sise-ise ungo, nibözi nangi andrö khö Yehowa.', '["Faigi 63:5","Efes 6:17; TesI 5:8","Rom 11:26"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 20, 'Ba ba mbanua Ziona, ba möi ia sangorifi ba ba ma''uwu Yakobo andrö, samalalini era-erara, sondröi lalöra andrö, iŵa''ö Yehowa.[14]', '["Faigi 63:5","Efes 6:17; TesI 5:8","Rom 11:26"]', NULL),
  (3476314, 'OT', 'Yesaya', 59, 21, 'Ba ba khögu andre, ba da''ö wawu''usa li andrö khögu khöra: Ehehagu andrö, si no ahono khöu, ba taroma ligu, nibe''egu ba mbeweu, ba lö aefa dania ba mbawau, ba he ba mbawa nga''ötömö ba he ba mbawa ma''uwura zui, iŵa''ö Yehowa, i''otarai da''e, irugi zi lö aetu.', '["Faigi 63:5","Efes 6:17; TesI 5:8","Rom 11:26"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 1, 'Faoso, yamohaga ndra''ugö; noa sa so hagamö andrö, no humaga yaŵau lakhömi Yehowa!', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 2, 'Hiza sa: No tobalu sogömi-gömi danö ba si bongi zombalugö soi niha; ba yaŵamö, ba humaga Yehowa ba lakhöminia zi to''ele yaŵau.', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 3, 'Ba la''ondrasi dania haga andrö khöu niha baero, ba razo zangondrasi lakhömi andrö, si no humaga yaŵamö.[1]', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 4, 'Faöga höröu, fakhölö''ö ba faigi: No owulo ira fefu, la''ondrasi ndra''ugö! La''otarai zaröu ono matua khöu, ba nilu''i ba lembe nonou alawe.[2]', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 5, 'Ba na ö''ila dania, ba humaga mbawau [ba wa''omuso dödö], humufa dödöu ba ebolo; isaŵa sa''ae ndra''ugö ana''a si otarai nasi, möi khöu girö-girö niha baero.', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 6, 'Ihawui ndra''ugö fa''oya gondra andrö, ono gondra Midiano ba ono gondra Gefa; dozi so ira moroi ba Zaba: la''ohe gana''a ba kumöyö ba laturiaigö nilau Yehowa, fa''ebua döinia andrö.[3]', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 7, 'Fefu mbiri-biri Gedara andrö, ba khöu owulo, ba balazi ndra''ugö mbiri-biri si matua ba Ndraono Nabayoti. Ba naha wame''e sumange khögu yaŵa numalö, omasiö, ba ufolakhömi na nomo lakhömigu andrö.', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 8, 'Ha niha da''ö sihombo moroi sa, hulö lawuo, hulö marafadi, sanaŵa nahiara?', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 9, 'Ya''odo sa nidöna-döna hulo andrö, ba sowaö-waö nowo Darisi andrö, ba wolohe mangawuli onou, moroi ba zaröu, fabaya ana''a ba firö khöra [ana''a soi andrö] börö döi Yehowa Lowalangiu, börö Ni''amoni''ö Ndraono Gizeraeli andrö, me no ifolakhömi ndra''ugö.[4]', '["Fam 21:24","Faigi 49:18","Sin 72:10; Mat 2:11","Faigi 42:4"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 10, 'Niha bö''ö dania zangaro öli khöu ba möi enoniu razora; ba wönugu sa ubago ndra''ugö mege ba ba wa''ebua dödögu andrö uhakhösi tödö ndra''ugö.[5]', '["Faigi 12:1","Fam 21:25","Sakh 8:6; 14:16","Faigi 41:19","Faigi 49:23; Fam 3:9","Faigi 54:6","Faigi 43:3"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 11, 'Ba bawa gölimö andrö, ba ma''öma''ökhö teboka, ba he ba zi bongi, ba lö lakusi, ba wolohe miyomo khöu ana''a niha baero andrö, ba awö fao razo.[6]', '["Faigi 12:1","Fam 21:25","Sakh 8:6; 14:16","Faigi 41:19","Faigi 49:23; Fam 3:9","Faigi 54:6","Faigi 43:3"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 12, 'Na so soi ba ma öri, si lö edöna möi barö mbawau, ba tekiko, ba lö zi lö ahori dania soi andrö.[7]', '["Faigi 12:1","Fam 21:25","Sakh 8:6; 14:16","Faigi 41:19","Faigi 49:23; Fam 3:9","Faigi 54:6","Faigi 43:3"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 13, 'I''ondrasi dania ndra''ugö lakhömi hili Libano andrö: berua ba simalambuo ba afoa, fefu, ba wamolakhömi naha ni''amoni''ö andrö khögu ba ba wangebua töi nahia gahegu andrö.[8]', '["Faigi 12:1","Fam 21:25","Sakh 8:6; 14:16","Faigi 41:19","Faigi 49:23; Fam 3:9","Faigi 54:6","Faigi 43:3"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 14, 'Ba laköwö ira wanaŵa ya''ugö ono zamakao ya''ugö mege, ba lasömba ndra''ugö ba gaheu dozi sanandraŵaisi ya''ugö mege, ba labe''e töimö "Mbanua Yehowa", "Siona Ni''amoni''ö Ndraono Gizeraeli andrö".[9]', '["Faigi 12:1","Fam 21:25","Sakh 8:6; 14:16","Faigi 41:19","Faigi 49:23; Fam 3:9","Faigi 54:6","Faigi 43:3"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 15, 'Usalahini khöu wa no ni''erogö ndra''ugö, wa no ni''ogorofi, irege samösa lö itörö niha: ube''e nisuno ndra''ugö, si lö mamalö-malö, omasiö, götö-götö wa''ara.[10]', '["Faigi 12:1","Fam 21:25","Sakh 8:6; 14:16","Faigi 41:19","Faigi 49:23; Fam 3:9","Faigi 54:6","Faigi 43:3"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 16, 'Ba öbadu nösi zusu niha baero, ba ösisiö mbalö meme razo; ba ya aboto ba dödöu, wa sangefa''ö ya''ugö ndra''odo, ya''o Yehowa, awö wa sangorifi ya''ugö zabölö ma''uwu Yakobo andrö.[11]', '["Faigi 12:1","Fam 21:25","Sakh 8:6; 14:16","Faigi 41:19","Faigi 49:23; Fam 3:9","Faigi 54:6","Faigi 43:3"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 17, 'Salahi döla garamba ufabe''e''ö gana''a ba salahi zi''öli wirö, salahi geu döla garamba ba salahi gara zi''öli; ba ube''e salaŵamö wa''ohahau dödö, ba samatörö ya''ugö ube''e wa''atulö.', '["Fam 21:23; 22:5","Faigi 29:23"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 18, 'Lö''ö sa''ae terongo wamalangögö ba danömi, ba he famakiko ba fanudugö bakha barö nola khömi; "fangorifi" öbe''e töi gölimö ba "turia" öbe''e töi mbawa göli.', '["Fam 21:23; 22:5","Faigi 29:23"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 19, 'Lö''ö sa''ae moguna khöu luo, haga na ma''ökhö, ba lö''ö sa''ae humaga khöu mbaŵa, haga ba zi bongi; Yehowa sa''ae haga khöu, si lö tebulö, ba lakhömiu Lowalangimö.[12]', '["Fam 21:23; 22:5","Faigi 29:23"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 20, 'Lö''ö sa''ae aekhu luo andrö khöu, ba baŵa khöu, ba lö tesa''a; Yehowa sa''ae haga khöu, si lö tebulö, ba sahori sa''ae mbaŵa wa''abu dödö andrö khöu.', '["Fam 21:23; 22:5","Faigi 29:23"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 21, 'Ba banuami, ba ha sambalö satulö tödö; khöra danö, si lö mamalö-malö; le wiö zinanögu [ira], omböila dangagu, ena''ö tobali lakhömigu.[13]', '["Fam 21:23; 22:5","Faigi 29:23"]', NULL),
  (3476315, 'OT', 'Yesaya', 60, 22, 'Fondrege zide-ide, ba tobali hönö, ba fondrege tou, ba tobali soi sabölö: Ya''odo, Yehowa zamangaösö dania, na baŵania!', '["Fam 21:23; 22:5","Faigi 29:23"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 1, 'No ahono khögu Geheha Zo''aya andrö, Eheha Yehowa, me no ibayoini ndra''o Yehowa, ba wama''ema turia somuso dödö ba zebua famakao; no ifatenge ndra''odo, ba wodalu-daluni si no arasa tödö, ba ba wangombakha fangefa ba nikuru, ba famolala tödö ba nifobilagu;[1]', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 2, 'ba wanuriagö döfi wa''omasi khö Yehowa ba baŵa wolau balö khö Lowalangida, ba wondrara tödö zabu tödö fefu.[2]', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 3, 'Ba wama''ema ba zabu tödö andrö, banua Ziona, aya salahi nawu ba fanikha fa''owua-wua dödö, salahi wa''abu dödö, ba baru ba walöŵa, salahi wa''ata''u dödö bakha; ba labe''e dania töira "Döla geu wa''atulö", "Sinanö Yehowa", lakhöminia.', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 4, 'Ba lafuli la''otomosi gadudula, si no ara sibai, lafuli la''a''azökhi zadudu banua ndra tua, bohou labe''e mbanua niröi föna, adudula ba götö föna sa''ae.[3]', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 5, 'So niha bö''ö, ba wokubaloi urifömi; niha bö''ö göi zonowi khömi ba sohalöŵö ba kabu nagu khömi.', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 6, 'Ba töimi, ba "Ere Yehowa;" "Enoni Lowalangida" labe''e töimi. Ömi dania mbalazo niha baero ba mikhamö gana''ara.[4]', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 7, 'Dua winaeta dania zalahi wango''aya andrö mege, ba ma''iki dania ira, ndrohu-ndrohu, salahi wa''aila mege. Andrö wa dua winaeta dania khöra ba danöra: fa''omuso dödö si lö aetu lasöndra.[5]', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 8, 'Me no somasi satulö ndra''odo, ya''o Yehowa, ba sogoro nirabu manö, ba wa lö atulö; ube''e mböli gölöra, lö falimodo, ba utehe khöra wawu''usa li, si lö tebulö.', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 9, 'Ba anehe dania niha baero ma''uwura, ba la''ila madoura soi bö''ö: dozi sangila ya''ira, ba aboto ba dödö, wa no mado nifahowu''ö Yehowa ira.', '["Faigi 11:2; 57:15: 66:2; Luk 4:48","Faigi 49:8; Mat 5:4; Tit 3:4","Faigi 58:12","FetI 2:5; Fam 1:6","Faigi 35:10"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 10, 'Ba omuso dödögu ba khö Yehowa, owua-wua dödögu ba khö Lowalangigu, me no ifonukha ndra''odo nukha fangorifi, me no i''olohuni ndra''o baru sebua fa''atulö andrö, si mane sangowalu, sangehao aya ba högö, ba si mane ono nihalö si onukha nukha ni''owalu.[6]', '["Rom 13:14"]', NULL),
  (3476316, 'OT', 'Yesaya', 61, 11, 'Si mane tanö sa''ae, sauri sinanö, ba si mane kabu, ba zolöndru tanömö zinanö, si manö wa''amolöndru wa''atulö ba fa''ebua döi, ibe''e So''aya, Yehowa, ba zanehe niha baero fefu.', '["Rom 13:14"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 1, 'Börö Ziona andrö, wa lö ubato wehede, ba börö Yeruzalema, wa lö ahono ndra''odo, irege alua zatulö andrö khöra, hulö haga, ba irege alua wangorifira, hulö zulu sihola-hola.', '["Faigi 65:15","Faigi 54:6; Hos 1:10; FetI 2:10"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 2, 'Ba la''ila zatulö andrö khöu niha baero, ba oroma lakhömiu ba zalaŵa fefu. Ba töi si bohou labe''e töimö, soroi ba li Yehowa.[1]', '["Faigi 65:15","Faigi 54:6; Hos 1:10; FetI 2:10"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 3, 'Ba amaedola zaembu soadu ndra''ugö, ba danga Yehowa ba aya ba högö ba zalaŵa ba danga Lowalangiu.', '["Faigi 65:15","Faigi 54:6; Hos 1:10; FetI 2:10"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 4, 'Tenga töimö sa''ae "Niröi", ba tenga sa''ae "Tanö si mate" döi danöu andrö; "Fa''omasigu" labe''e töimö ba töi danöu, ba "Ni''owalu", me somasi Yehowa ndra''ugö ba me no amaedola ni''owalu danöu andrö.[2]', '["Faigi 65:15","Faigi 54:6; Hos 1:10; FetI 2:10"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 5, 'Si mane ono matua, na i''owalu nono alawe, si manö dania wangai nonou ya''ugö, ba si mane fa''owua-wua dödö zangowalu nono nihalö andrö khönia, si manö dania wa''owua-wua dödö Lowalangiu ndra''ugö.', '["Faigi 65:15","Faigi 54:6; Hos 1:10; FetI 2:10"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 6, 'Ba gölimö andrö, ya''ugö Yeruzalema, ba no ufataro zanaro: ma''öma''ökhö ba sara wongi, ba böi ndramubato we''ao; ya''ami samasugi ba dödö Yehowa [Siona], ba böi mibato!', '["MozV 12:17,18","Faigi 40:3","Faigi 40:10; Sakh 9:9; Mat 21:5"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 7, 'Ba böi mibe''e ahono ia, irege i''azökhi Yeruzalema, irege ibe''e börö wanuno ba guli danö ma''asagörö!', '["MozV 12:17,18","Faigi 40:3","Faigi 40:10; Sakh 9:9; Mat 21:5"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 8, 'No fahölu Yehowa ba dangania kambölö ba ba mbulökhania sabe''e andrö, [no imane]: Lö''ö sa''ae ululu ö nemaliu mbua nowi khöu, ba böi ndra mubadu niha bö''ö nösi mbua nagu khöu, si no erege dödöu.', '["MozV 12:17,18","Faigi 40:3","Faigi 40:10; Sakh 9:9; Mat 21:5"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 9, 'Samasi zi manga ba lasuno Yehowa, ba saneteu bua zamadu ösi ba golayama ni''amoni''ö andrö khögu.[3]', '["MozV 12:17,18","Faigi 40:3","Faigi 40:10; Sakh 9:9; Mat 21:5"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 10, 'Mitörö, mitörö mbawa göli andrö! Mihaogö lala mbanua [da]! Mifolala! Mifolala! Miheta gara ba lala! Mitaru''ö döla mandrera, ba niha baero andrö![4]', '["MozV 12:17,18","Faigi 40:3","Faigi 40:10; Sakh 9:9; Mat 21:5"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 11, 'Hiza, ifarongogö Yehowa, irugi ba wondrege guli danö, [imane]: Mimane khö nono Ziona alawe andrö: Hiza, so moroi sa wangorifiu! Hiza, fao khönia mböli gölö andrö, nibe''enia, ba mowaö-waö fönania zulö andrö khönia![5]', '["MozV 12:17,18","Faigi 40:3","Faigi 40:10; Sakh 9:9; Mat 21:5"]', NULL),
  (3476317, 'OT', 'Yesaya', 62, 12, '"Banua ni''amoni''ö" labe''e töira ba "Ni''orifi Yehowa"; ba töimö, ba "Ni''ondrasi", "Banua si tebai teröi."', '["MozV 12:17,18","Faigi 40:3","Faigi 40:10; Sakh 9:9; Mat 21:5"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 1, 'Ha niha da''ö, si otarai Gedomo, soyo baru andrö, si otarai mbosera? Si no moadu sibai ba mbarunia andrö, si no fahöna fa''abölö, wanörö lalania andrö? Ya''odo da''ö, samabu''u fa''atulö, si no abölö ba wangorifi.[1]', '["Faigi 34:6; Fam 19:11–13","Fam 14:18–20; 19:15","Faigi 34:8","Faigi 59:16","Faigi 51:17"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 2, 'Hana wa no oyo mbarumö andrö, ba hana wa no hulö ba zanguhundra folazi mbua nagu nukhau?', '["Faigi 34:6; Fam 19:11–13","Fam 14:18–20; 19:15","Faigi 34:8","Faigi 59:16","Faigi 51:17"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 3, 'Noa sa uhundragö wolazi, ha ya''oya''o, ba samösa lö awögu, niha baero. No uhundragö ba wönugu andrö, ba no uhösöini ba wa''abao dödögu, no tobali tokana ba nukhagu nösinia, oi ta''unö mbarugu ube''e.[2]', '["Faigi 34:6; Fam 19:11–13","Fam 14:18–20; 19:15","Faigi 34:8","Faigi 59:16","Faigi 51:17"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 4, 'Noa sa so ba dödögu mbaŵa wolau balö, ba no irugi döfi wangorifi andrö khögu.[3]', '["Faigi 34:6; Fam 19:11–13","Fam 14:18–20; 19:15","Faigi 34:8","Faigi 59:16","Faigi 51:17"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 5, 'Ba ufakhölö ndra''o, ba lö sanolo, ufaigi-faigi, no tobali dödögu, ba lö solului. Ba ulau manö bulökhagu, ba fa''abao dödögu andrö zanolo ya''odo.[4]', '["Faigi 34:6; Fam 19:11–13","Fam 14:18–20; 19:15","Faigi 34:8","Faigi 59:16","Faigi 51:17"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 6, 'Tobali uhundragö soi niha, ba wönugu andrö, ba umama, ba wa''abao dödögu; ahele ba danö nösira ube''e."[5]', '["Faigi 34:6; Fam 19:11–13","Fam 14:18–20; 19:15","Faigi 34:8","Faigi 59:16","Faigi 51:17"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 7, 'Da''usuno wa''ebua dödö Yehowa andrö, nilau Yehowa andrö soturia, dali nilau Yehowa khöda, ba fa''ebua dödönia andrö, soya finaeta, ba ma''uwu Gizeraeli, ni''amualagönia khöra, ba wa''ahakhö dödönia andrö, ba ba wa''afahöna wa''ebua dödönia.', '["Faigi 1:2","MozII 23:20; Faigi 46:3","MozIV 14:11; Sin 78:56; 95:9; Efes 4:30","MozII 14:29; MozIV 11:25; Sin 77:21"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 8, 'Noa sa imane: Si ndruhu, banuagu ira, ono, si lö falimo; ba tobali sangorifi ya''ira ia.[6]', '["Faigi 1:2","MozII 23:20; Faigi 46:3","MozIV 14:11; Sin 78:56; 95:9; Efes 4:30","MozII 14:29; MozIV 11:25; Sin 77:21"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 9, 'Si tosasa ira, fefu, ba tosasa ia göi; ba i''orifi ira mala''ika andrö, khala-khalania: ba wa''omasinia ba me no alimagö ira khönia, i''orifi ira, ifazaŵa ira ba i''ohe, ero ma''ökhö ba götö föna andrö.[7]', '["Faigi 1:2","MozII 23:20; Faigi 46:3","MozIV 14:11; Sin 78:56; 95:9; Efes 4:30","MozII 14:29; MozIV 11:25; Sin 77:21"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 10, 'Ba ya''ira: ba sabe''e tandro ba labusi dödö Gehehania ni''amoni''ö andrö, ba tobali si fa''udu khöra ia: ya''ia zi fasuwö khöra.[8]', '["Faigi 1:2","MozII 23:20; Faigi 46:3","MozIV 14:11; Sin 78:56; 95:9; Efes 4:30","MozII 14:29; MozIV 11:25; Sin 77:21"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 11, 'Awena itörö tödö mbanuania götö föna andrö, me luo Moze [ba lamane]: Heza so zolohe miyaŵa ya''ira moroi ba nasi, fabaya kubalo rorogöfönia andrö? Heza so zame''e Ehehania ni''amoni''ö andrö ba dödöra?[9]', '["Faigi 1:2","MozII 23:20; Faigi 46:3","MozIV 14:11; Sin 78:56; 95:9; Efes 4:30","MozII 14:29; MozIV 11:25; Sin 77:21"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 12, 'Ifao khö Moze ba gambölönia mbulökhania solakhömi andrö, ifabali nidanö fönara, ba wangai töi khönia, si lö tebulö.', '["Faigi 1:2","MozII 23:20; Faigi 46:3","MozIV 14:11; Sin 78:56; 95:9; Efes 4:30","MozII 14:29; MozIV 11:25; Sin 77:21"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 13, 'Ifatörö ira ba mbalö molö, si mane kudo ba mbenua salo''o, lö alau.', '["Faigi 1:2","MozII 23:20; Faigi 46:3","MozIV 14:11; Sin 78:56; 95:9; Efes 4:30","MozII 14:29; MozIV 11:25; Sin 77:21"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 14, 'Si mane öröbao, si möi mitou ba ndraso i''ohe ira ba zahono ira Eheha Yehowa. Si manö woloheu banuau, ba wangai töi si teturia khöu.', '["Faigi 1:2","MozII 23:20; Faigi 46:3","MozIV 14:11; Sin 78:56; 95:9; Efes 4:30","MozII 14:29; MozIV 11:25; Sin 77:21"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 15, 'Faigi moroi yaŵa ba zorugo, nehegö moroi ba nahiamö andrö ni''amoni''ö ba solakhömi! Heza so wa''aukhu dödöu andrö ba fa''abölöu? Ötaha khögu wa''ahakhö dödöu ba fa''ogolönia![10]', '["MozV 26:15","Sin 27:10"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 16, 'Amama sa atö ndra''ugö! [Tuama] Aberahamo andrö, ba lö''ö sa aboto ba dödönia ndra''aga, ba [Tuama] Izeraeli, ba lö i''ilaga; ya''ugö, Yehowa, namama, "Sangorifi ya''aga, götö-götö wa''ara sa''ae" döimö.[11]', '["MozV 26:15","Sin 27:10"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 17, 'Hana wa ötehe elungu ndra''aga, maröi lala andrö khöu, ya''ugö Yehowa? Hana wa ötehe abe''e dödöma, fa lö i''ata''ufi ndra''ugö? Fuli''ö, börö genoniu andrö, börö mado andrö, si no tana khöu!', '["MozV 26:15","Sin 27:10"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 18, 'Naha ni''amoni''ö andrö khöu, ba no si lö arara ba danga mbanua ni''amoni''ö andrö khöu, ba emalima zi hundra-hundra ya''ia.', '["MozV 26:15","Sin 27:10"]', NULL),
  (3476318, 'OT', 'Yesaya', 63, 19, 'Hulö zi no ara aefa banuau ndra''aga, hulö zi lö irai ba döi töimö andrö.', '["MozV 26:15","Sin 27:10"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 1, 'Ena''ö na öfabali mbanua si yaŵa, ba we''amöi mitou, ena''ö humisi hili,', '["Sanguhuk 5:5; Sin 68:9","Sin 31:20; KorI 2:9","Sin 90:5"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 2, 'fönau — si mane ba galitö, na ira''i duturu geu ba si mane na mo''otu nidanö ibe''e — ena''ö larongo döimö fa''udu khöu ba ena''ö manizi khöu niha baero andrö.', '["Sanguhuk 5:5; Sin 68:9","Sin 31:20; KorI 2:9","Sin 90:5"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 3, 'Na ölau zata''u niha, si lö mudöna-döna! No möi''ö mitou, ba no humisi hili fönau.[1]', '["Sanguhuk 5:5; Sin 68:9","Sin 31:20; KorI 2:9","Sin 90:5"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 4, 'I''otarai föna sa''ae, ba lö murongo, lö si möi ba dögi dalinga, lö irai i''ila hörö niha Lowalangi baerou, solau-lau hadia ia khö zanötöna khönia![2]', '["Sanguhuk 5:5; Sin 68:9","Sin 31:20; KorI 2:9","Sin 90:5"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 5, 'Öfaondragö zomasi molau satulö: ba lala andrö khöu itörö tödöra ndra''ugö. Hiza, no mofönu ndra''ugö ba ya''aga zolu''i — me no faröi ndra''aga, ba te''etu''ö hukuma.', '["Sanguhuk 5:5; Sin 68:9","Sin 31:20; KorI 2:9","Sin 90:5"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 6, 'Ba tobali amaedola zi ta''unö ndra''aga fefu, ba fefu mbua-buama si sökhi andrö, ba no hulö lembe si no göna do. Dozi ndra''aga, ba saleu, hulö mbulu zinanö; ba i''oloi''ö ndra''aga lalöma andrö, timba ni''oloi''ö nangi.[3]', '["Sanguhuk 5:5; Sin 68:9","Sin 31:20; KorI 2:9","Sin 90:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476319, 'OT', 'Yesaya', 64, 7, 'Samösa lö''ö sa''ae si angaröfi li töimö, si maoso, ba wangolembai ya''ugö; noa sa öbini''ö khöma mbawau, ba ölulu ndra''aga ba wa''abölö horöma andrö.', '["Sanguhuk 5:5; Sin 68:9","Sin 31:20; KorI 2:9","Sin 90:5"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 8, 'Ba iada''e, ya''ugö Yehowa, ba amama sa atö ndra''ugö: la''uri ndra''aga, ba ya''ugö zamöbözi; omböila dangau ndra''aga fefu![4]', '["Faigi 45:9; Rom 9:21","Sin 79:8"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 9, 'Böi abölögö wofönu, ya''ugö Yehowa, ba böi aragö ba dödöu lalö [ma] andrö! Faigi: Banuau ndra''aga fefu![5]', '["Faigi 45:9; Rom 9:21","Sin 79:8"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 10, 'Naha ni''amoni''ö andrö khöu, ba no adudu: No tobali tanö si mate Ziona, ba no si lö niha-niha Yeruzalema.', '["Faigi 45:9; Rom 9:21","Sin 79:8"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 11, 'Osali andrö khöda, ni''amoni''ö ba solakhömi, ba nisuno ndra tuama ya''ugö, ba no i''a alitö, ba fefu zomasi sibai ndra''aga, ba no adudula.', '["Faigi 45:9; Rom 9:21","Sin 79:8"]', NULL),
  (3476319, 'OT', 'Yesaya', 64, 12, 'Hadia, ö''ila zui ötaha dödöu ba da''ö, ya''ugö Yehowa; hadia, lö hede-hedeu ba öfalua öhöndrögö ndra''aga?', '["Faigi 45:9; Rom 9:21","Sin 79:8"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 1, 'Tola lasöndra ndra''o si lö manofu-nofu ya''odo ube''e, ba tola falukha khögu zi lö mangalui ya''o. No umane ba niha, si lö ba döi töigu: Ya''e ndra''o! ya''e ndra''o![1]', '["Faigi 52:15; Rom 10:20,21","MozV 12:2; Faigi 1:29","MozIII 11:7","Mat 25:46"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 2, 'No ma''öma''ökhö u''oro''ö dangagu ba niha sabe''e tandro, sanörö lala si lö sökhi,', '["Faigi 52:15; Rom 10:20,21","MozV 12:2; Faigi 1:29","MozIII 11:7","Mat 25:46"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 3, 'dali nikhoi dödöra: ba niha si lö mangetu''ö fangandrö fönugu, ba zanehe ndra''odo, wame''e adu ba kabu misa, awö wanunu kumöyö ba dete gara tembo.[2]', '["Faigi 52:15; Rom 10:20,21","MozV 12:2; Faigi 1:29","MozIII 11:7","Mat 25:46"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 4, 'Sidadao ba lewatö ba si mörö ba naha si tobini ira, si manga mbawi, ba dino sogoro ita nösi makora.[3]', '["Faigi 52:15; Rom 10:20,21","MozV 12:2; Faigi 1:29","MozIII 11:7","Mat 25:46"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 5, 'Sanguma''ö: "Aröu''ögö, böi hatö''ögö khögu; ni''amoni''ö sa ndra''o khöu!" — simbo ba nikhugu niha si manö, alitö si hola-hola, si lö mate-mate![4]', '["Faigi 52:15; Rom 10:20,21","MozV 12:2; Faigi 1:29","MozIII 11:7","Mat 25:46"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 6, 'Hiza, no so ba zura fönagu; tenga si lö hede-hede ndra''o, atö na no usulöni.', '["Faigi 52:15; Rom 10:20,21","MozV 12:2; Faigi 1:29","MozIII 11:7","Mat 25:46"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 7, 'Usulöni ba gahetara horömi, awö horö ndra tuami, ni''orudugö, iŵa''ö Yehowa, ba zi no manunu kumöyö ba hili misa, si no mango''aya ya''odo ba hili-hili — ba u''ofönai''ö usu''a ba gahetara luora.', '["Faigi 52:15; Rom 10:20,21","MozV 12:2; Faigi 1:29","MozIII 11:7","Mat 25:46"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 8, 'Imane Yehowa: Hulö na so''ösi mbua nagu ba na lamane: "Böi fakiko, so sa bakha howu-howu", si manö wolaugu, börö genonigu andrö, fa lö ahori ufakiko.', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 9, 'Ba moma''uwu Yakobo ube''e, ba so madou Ndraono Yuda, sokhö hili andrö khögu: ba tana ba nitutuyugu andrö [tanö], ba enonigu andrö zowanua ba da''ö.', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 10, 'Benua nahia mbiri-biri dania Zarona, ba daso Nakhori andrö, ba olombaseŵa zaŵi, ba mbanuagu andrö, ha wa''ato ira zanofu-nofu ya''odo.[5]', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 11, 'Ba ya''ami sangerogö Yehowa, ba solifu hili ni''amoni''ö andrö khögu, ya''ami samazökhi naha wame''e sumange ba "nadu salöfö" andrö ba samabadugö sumange nibadu, nifaruka,', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 12, 'ba "wamakhö," — ba khömi ufatörö zi''öli nihaogö, ba dozi ami, ba mifaöndrö ami ni''ö''ötö, me no lö mitema li, me mu''ao ndra''o; humede ndra''o, ba lö mifondrondrongo; ba milau zi fatuwu ba hörögu, ba si lö omasi ndra''o, ba omasi ami![6]', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 13, 'Andrö imane So''aya, Yehowa: Hiza, si manga-manga genonigu andrö, ba ya''ami, ba solofo! Hiza, samadu-madu hadia ia genonigu, ba ya''ami ba sowökhi tödö! Hiza, somuso tödö genonigu, ba ya''ami, ba saila!', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 14, 'Hiza, sa''iki-iki genonigu, ba wa''owua-wua dödö andrö, ba ya''ami, ba sangarö-ngarö, ba wa''afökhö dödömi bakha, ba sege-ege ba wa''arasa dödö!', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 15, 'Ba mifa''ema ba nitutuyugu andrö döimi, ba [wanötöi ba] wangelifi [na lamane]: Yamubunu''ö So''aya Yehowa! Ba ba genoninia andrö, ba ifatörö döi bö''ö.[7]', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 16, 'Tobali, na so ba danö zamahuwu''ö ya''ia, ba ba Lowalangi si ndruhu andrö ifahowu''ö ia, ba si fahölu ba danö, ba ba Lowalangi si ndruhu andrö fahölu ia, me no taya ba dödö wamakao andrö, si no numalö, ba me lö''ö sa''ae oroma khögu.', '["Faigi 35:2; Yos 7:24","Amaed 1:24; Faigi 60:4; Yer 7:13","MozIV 5:21"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 17, 'Hiza sa, uwöwöi mbanua si yaŵa si bohou ba tanö si bohou, ba lö''ö sa''ae itörö tödö zi föföna andrö, lö''ö sa''ae i''angeragö niha![8]', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 18, 'Ba owua-wua dödö ba ma''iki-iki ba niwöwöigu andrö si lö mamalö-malö; hiza sa, ma''iki-iki Yeruzalema ba wamazökhigu ya''ia ba owua-wua dödö nösi mbanua!', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 19, 'Ba sa''iki-iki bakha dödögu, börö Yeruzalema andrö, ba sowua-wua dödögu mbanuagu, ba lö''ö sa''ae terongo ba khöra li wege-ege ba he li wangarö-ngarö.[9]', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 20, 'Lö''ö sa''ae ba da''ö ono sawuyu, si ha ba ngaluo fa''anau noso, ba lö satua, si lö a''ozu noso; mate ono matua, na no otu fakhe ba si ha otu fakhe, ba si so horö, si no göna fangelifi.[10]', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 21, 'Ba lalau nomo, ba la''onahia göi; lafazökhi kabu nagu ba la''a mbua.', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 22, 'Tenga solau omo ira, ba tanö bö''ö zi onahia ba tenga sananö sinanö, ba tanö bö''ö zi manga mbua; fa''ara döla geu sa''ae wa''anau noso mbanuagu andrö, ba ölö dangara, ba nitutuyugu andrö zi oguna''ö.', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 23, 'Tenga serege tödö ira, ba zaya-zaya gölö, ba tenga so''ono, ena''ö itörö famakhö. Nga''ötö sebua howu-howu sa''ae ira khö Yehowa, ba so ba ngaira madoura.', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 24, 'Ba tobali, lö si''ao na ira, ba no utema li; fatua humede na ira, ba ufondrondrongo![11]', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476320, 'OT', 'Yesaya', 65, 25, 'Orudu ira nasu gatua nono mbiri-biri, wangalui göra; i''a ndru''u singo, si mane saŵi, ba tanö gö gulö; tenga sa''ae sangalani awöra ba tenga samakiko ira ba hili ni''amoni''ö andrö khögu fefu, iŵa''ö Yehowa.[12]', '["Faigi 66:22; FetII 3:13; Fam 21:1","Faigi 35:10; Fam 21:4; Sakh 14:21","MozI 5:5","Faigi 30:19; 58:9","MozI 3:14; Faigi 11:6–9"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 1, 'Da''ö niŵa''ö Yehowa: Dadaomagu mbanua si yaŵa ba dane-dane gahegu danö. Ba heza so ena''ö nomo andrö, nilaumi khögu, ba hezo naha solombase ndra''o?[1]', '["RazI 8:27; HalZin 7:48; 17:24","Sin 51:19; Faigi 57:15","Sin 50:7–13","Faigi 65:12"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 2, 'No tangagu sa atö zamazökhi da''ö fefu, wa so da''ö fefu, iŵa''ö Yehowa. Ba da''ö unehegö: sebua famakao ba si no arasa tödö ba sanizi-nizi ba daroma ligu andrö.[2]', '["RazI 8:27; HalZin 7:48; 17:24","Sin 51:19; Faigi 57:15","Sin 50:7–13","Faigi 65:12"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 3, 'Sanaba öröbao ba samunu niha göi; same''e sumange biri-biri ba samao famunu asu; same''e sumange ni''a ba samao do mbawi; sanunu kumöyö ba samao fanömba adu —: si mane ya''ira, me no nilau dödöra wanörö lalara andrö, ba me omasi ira zogoro ita andrö khöra,[3]', '["RazI 8:27; HalZin 7:48; 17:24","Sin 51:19; Faigi 57:15","Sin 50:7–13","Faigi 65:12"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 4, 'si manö göi ndra''o wa omasido mamakao ya''ira ba ufatörö khöra zihokha mbura, me no lö sanema li, me mu''ao ndra''o, ba me lö samondrongo, me humede ndra''odo; ba si fatuwu ba hörögu, da''ö lalau, ba si lö omasi ndra''o, ba omasi ira.[4]', '["RazI 8:27; HalZin 7:48; 17:24","Sin 51:19; Faigi 57:15","Sin 50:7–13","Faigi 65:12"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 5, 'Mifondrondrongo li "Yehowa, ya''ami sanizi-nizi ba daroma linia andrö! No lamane talifusömi andrö, si fatiu tödö khömi, sanibo ya''ami, börö döigu andrö: "Yamu''oroma''ö lakhöminia Yehowa, ena''ö anehe ndra''aga wa''omuso dödömi andrö".', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 6, 'Ba saila ira dania. Hiza ruru ba gamaudu mbanua; moroi ba gosali tarongo li Yehowa, sanulöni ba zi fa''udu khönia nilaura andrö.', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 7, 'Lö fakhamö afökhö hulu, ba no madono ia; lö fakhamö afökhö hulu, ba no i''adonogö nono matua.', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 8, 'Ha niha zirai mamondrongo si manö? ha niha zirai mangila? Hadia, böla zi sambua tanö, ha ma''öma''ökhö? Hadia, ha samuza wa''atumbu zi sambua soi? — wa no afökhö hulu Ziona, ba no fadoro i''adonogö nononia?', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 9, 'Hadia, irege hatö fa''aböla u''ohe maö [dabina], ba lö ube''e tumbu? iŵa''ö Yehowa. Ba ma same''e tumbu ba sanaha zui dania ndra''odo? iŵa''ö Lowalangiu.', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 10, 'Ya omuso dödömi, awö Yeruzalema ba mi''a''iki-iki ba khöra andrö, ya''ami fefu, somasi ya''ia! ya owua-wua dödömi awöra, ya''ami fefu, sabu tödö ba khöra.', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 11, 'Ena''ö abuso ami, wamadu ösi zusu fondrara tödö andrö khöra, ena''ö misowo ba ena''ö möi fangokafu dödömi wa''afahöna lakhömira andrö.', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 12, 'Imane sa Yehowa: Hiza, ufatörö khöra wa''ohahau dödö, hulö mboto nidanö, awö lakhömi niha baero andrö, hulö mbombo, si nönöi daso, ena''ö misisiö ba ena''ö nilu''i ba lembe ami ba ena''ö nihagi ba gaheta.[5]', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 13, 'Si mane na irara dödö nononia ina wondraragu tödömi, ba bakha ba Yeruzalema andrö dania terara dödömi.', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 14, 'Ba na mi''ila dania, ba owua-wua bakha dödömi, ba auri dania dölami, si mane du''u sawuyu-wuyu. Ba oroma danga Yehowa ba genoninia, ba mofönu ia ba zi fa''udu khönia.', '["Faigi 49:22; 60:4"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 15, 'Hiza sa, itörö dania Yehowa, fasui galitö, ba amaedola nangi sabölö guretania, ba wolau sulö fönunia andrö so''alitö ba fanegunia sihola-hola.[6]', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 16, 'Alitö sa ilau Yehowa, wame''e huku, ba si''ölinia andrö, ba niha fefu, ba ato dania ni''ö''ötö Yehowa andrö.', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 17, 'Ya''ira andrö, si amoni''ö ya''ira, sangehao ya''ira, ba we''amöi ba kabu andrö, wolo''ö khö zi so ba dalu andrö khöra, ba si manga mbawi ba hadia ia zogoro ita, ba te''u: ya''ira andrö, ba nihori fefu, iŵa''ö Yehowa.', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 18, 'Ba ya''odo, ba u''ila wolaura andrö, fabaya era-erara, no oroma: tobali u''owuloi fefu soi, ba hadia lira, ena''ö la''ondrasi, ba wamaigi lakhömigu.', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 19, 'Ba ulau dandra, ba zi so ira, ba ufatenge ösa ira, sauri, ba niha baero: ba Darisi ba ba Wuti ba ba Ludi, ba zamadölö sinali wana, ba ba Ndrawa Dubalo ba ba Ndrawa Yawano, ba ba hulo misa ba zaröu, ba zi lö irai larongo döigu ba ba zi lö irai la''ila lakhömigu; ba sangombakha lakhömigu andrö ira, ba niha baero.', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 20, 'Ena''ö la''ohe mangawuli dalifusömi fefu, sizaewe ba niha baero fefu; ena''ö la''ohe sumange Yehowa, si fakudo ba si fakureta ba nifabea ba si fakudo ba kudo kalide ba ba gondra, miyaŵa ba hili ni''amoni''ö andrö khögu, ba Yeruzalema, iŵa''ö Yehowa, amaedola na la''ohe ba gosali Yehowa zumange andrö Iraono Gizeraeli, bakha ba nahia ni''amoni''ö.', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 21, 'Ba uhalö göi ösa da''ö ere ba ono Lewi, iŵa''ö Yehowa.[7]', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 22, 'Si mane banua si yaŵa si bohou andrö sa''ae ba si mane tanö si bohou, niwöwöigu, wa si lö tebulö dania fönagu — iŵa''ö Yehowa —, si manö göi dania nga''ötömi andrö, fabaya töimi, wa si lö tebulö.[8]', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 23, 'Ba ero na tesa''a ba ero na luo sabato, ba oi so niha, ba wangalulu khögu, iŵa''ö Yehowa.', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476321, 'OT', 'Yesaya', 66, 24, 'Ba möi ira baero dania, mamaigi boto zi mate andrö, boto niha si no mangerogö ya''odo; lö''ö sa mate dania gukuö andrö khöra ba lö alele galitö khöra, ba sogoro niha fefu ira.[9]', '["MozV 4:24; Sin 50:3; TesII 1:8","MozII 19:6; Faigi 61:6","Faigi 65:17","Mar 9:44"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 1, 'Huhuo Yeremia andrö, ono Hilikia, oi ya''ira gere andrö ba Ganatoti, ba danö mado Mbeniyami,[1]', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 2, 'ba zihede Yehowa, me luo Yosia andrö, ono Gamoni, razo mado Yuda, me no alua mewelendrua fakhe razo ia. [628 föna Keriso].[2]', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 3, 'Ba me luo Yoyaki andrö, ono Yosia razo mado Yuda, irege alua mewelezara fakhe Zedekia, ono Yosia andrö, razo mado Yuda, irege te''oloi''ö Yeruzalema, me baŵa si lima. [586 föna Keriso].[3]', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 4, 'So niŵa''ö Yehowa khögu, imane:', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 5, 'Lö niwöwöigu ya''ugö na, ba dalu ninau, ba noa sa''ae u''ila''ö; ba lö si tumbu''ö na, ba no u''amoni''ö ndra''ugö; no uhonogöi, sama''ele''ö ndra''ugö ba ngawalö soi niha.[4]', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 6, 'Ba umane: He Soa''aya Yehowa, lö''ö sa u''ila fahuhuo, me iraono na ndra''odo.[5]', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 7, 'Ba imane khögu Yehowa: Böi ŵa''ö: Iraono na ndra''odo; ha khö sa''ae fefu ufatenge''ö, ba möi''ö, ba fefu hadia ia, ni''oroi''ögu khöu, ba öŵa''ö.', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 8, 'Böi ata''ufi ira, utolo sa ndra''ugö, ba wangorifi ya''ugö, iŵa''ö Yehowa.[6]', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 9, 'Ba i''oro''ö dangania Yehowa, itufa mbawagu. Ba imane khögu Yehowa: Hiza, ube''e ba mbeweu daroma ligu.[7]', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 10, 'Hiza, ufataro ndra''ugö ma''ökhö andre, utehe khöu soi andrö ba öri andrö, ba wangohori ba ba wamufu ba ba wamakiko ba ba wanudugö, ba ba wangotomosi ba ba wananö![8]', '["Yos 21:18; Nga''ötI 6:60","RazII 22:1","RazII 23:34; 24:17; 25:1; Faigi 39:1; 52:4","Gal 1:15","MozII 4:10","MozV 31:6; Hez 3:9","Yes 6:7","Faigi 18:7; KorII 10:5"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 11, 'Ba humede khögu Yehowa, imane: Hadia ni''ilau, Yeremia? Ba umane: Daha manalu (sahulö maoso) u''ila.', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 12, 'Ba imane khögu Yehowa: Si ndruhu, si lö mörö ndra''odo ba daroma ligu andrö, fa itörö ube''e.', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 13, 'Ba samuza tö humede khögu Yehowa, imane: Hadia ni''ilau? Ba umane: Bowoa so''otu ösi u''ila, ba moroi yöu i''otarai.', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 14, 'Ba imane khögu Yehowa: Moroi yöu dania falawu wamakao andrö, ihawui dania fefu niha ba danö.[9]', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 15, 'Ukaoni sa''ae dania fefu soi, öri miyöu andrö — iŵa''ö Yehowa — ena''ö möi ira, ena''ö ibe''e ba zinga mbawa göli Yeruzalema dadaomania zamösana, ba ba gero göli misa fefu, fasui, ba ba zinga mbanua mado Yuda fefu.[10]', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 16, 'Ba u''etu''ö hukura, ba zi lö sökhi andrö fefu, nilaura, me no la''erogö ndra''o, wamosumange Lowalangi bö''ö, ba me no mangalulu ira ba nifazökhi dangara.', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 17, 'Ba ya''ugö, ba amöbo talu, labu, ba ŵa''ö khöra fefu ni''oroi''ögu khöu! Böi tokea''ö khöra, ena''ö böi ya''odo zameta''u ya''ugö, fa ata''u''ö ira ube''e?', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 18, 'Ba ya''odo, ba hiza, ubali''ö banua saro ndra''ugö ma''ökhö, ba boha mbawa göli, si''öli, ba öli töla garamba, fametahö danö ma''afefu ba fametahö razo mado Yuda ba fametahö gumandrura sebua ba fametahö gere ba fametahö niha ba danö fefu.[11]', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476324, 'OT', 'Yeremia', 1, 19, 'Ba na fasöndra ira khöu, ba tebai sa atö lalaŵa ndra''ugö, utolo ndra''ugö — iŵa''ö Yehowa —, ba wangorifi ya''ugö.', '["Faigi 4:6","Faigi 5:15; 6:22; 10:22","Faigi 6:27; 15,20"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 1, 'Ba humede khögu Yehowa, imane:', '["Hez 16:8","MozII 19:6"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 2, 'Ae farongogö ba mbanua Yeruzalema andrö, ömane: Da''ö niŵa''ö Yehowa: Lö olifudo wa''atulö dödöu me ono alawe na ndra''ugö ba fa''omasiu [ndra''o], me nifohu na ndra''ugö, folo''ömö ya''odo ba danö si mate andrö, ba danö si lö sinasinanö.[1]', '["Hez 16:8","MozII 19:6"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 3, 'No ni''amoni''ö khö Yehowa mege Ndraono Gizeraeli, amaedola mbua zahulö khönia; dozi si manga ya''ira mena''ö, ba mosala; göna famakao ira, iŵa''ö Yehowa.[2]', '["Hez 16:8","MozII 19:6"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 4, 'Mifondrondrongo li Yehowa, ya''ami ma''uwu Yakobo, dozi mado ma''uwu Gizeraeli!', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 5, 'Da''ö niŵa''ö Yehowa: Hadia ni''ila ndra tuami khögu, si lö atulö, wa no la''erogö ndra''odo, wa no la''o''ö waya andrö, awö wa no tobali faya ira?', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 6, 'Ba lö lamane: Heza so Yehowa andrö, solohe miyaŵa ya''ita, moroi ba danö Miserayi, si no molohe tangada ba danö si mate, ba danö si no fahöna dekha ba sowahowaho; ba danö si no oköliköli ba sogömi-gömi sibai, ba danö si lö itörö niha bö''ö, ba si lö niha-niha, sonahia ba da''ö?[3]', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 7, 'Ba no u''ohe ami ba danö sabölö sibai sinanö, ena''ö mi''a mbua danö ba hadia ia zi sökhi, ba me no mirugi, ba mita''unöi danö andrö khögu, sogoro ita dana khögu mibe''e.', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 8, 'Lö lasofu ere: Hezo Yehowa? ba sanguhuku, ba lö la''ila ndra''odo; ba kubalo [zato], ba la''erogö ndra''o, ba sama''ele''ö andrö, ba ba döi Mba''ali andrö mama''ele''ö ba la''o''ö ba zi tebai mangorifi niha.[4]', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 9, 'Andrö utohugö wanegu ya''ami — iŵa''ö Yehowa — ba utegu na ma''uwumi dania.', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 10, 'Mi''ae sa''ae miyefo ba hulo Ndrawa Giti ba mifaigi, ba mifatenge ba Gedara ba mitöngöni ba mifaigi, na no mu''ila zi manö![5] —', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 11, 'na no lafalalini Lowalangira niha; ba si tenga Lowalangi na''i khöra. Ba banuagu andrö, ba no lahalö salahi zolakhömi andrö zi tebai mangorifi niha.[6]', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 12, 'Ya tobali dödömi, ya''ami banua si yaŵa, ba da''ö, ya humokha mbumi, ya tokea sibai ami! — iŵa''ö Yehowa.[7]', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 13, 'Dua winaeta sa horö, nifazökhi mbanuagu andrö: Ya''odo andre, umbu nidanö, ba no la''erogö, ba wogau ba''a khöra ba zabökha tanö, ba zi lö tosai idanö.[8]', '["MozV 8:15","Rom 2:20","Yes 23:1; Dan 11:30; MozIV 24:24","Sin 106:20; Rom 1:23","Yes 1:2","Faigi 17:13; Yoh 4:14"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 14, 'Hadia, sawuyu mado Gizeraeli, ma si tumbu ba nomo zo''omo? Hana wa tobali mirabu ira?', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 15, 'Mundröndröndröndrö khöra zingo, lafarongogö lira, ba labali''ö tanö si mate danöra, tetunu mbanua khöra, ba lö niha sa''e.[9]', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 16, 'Ba banua Nofi andrö göi ba banua Dakhifane, ba batule ndra''ugö labe''e.[10]', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 17, 'Hadia, tenga ba da''ö ösöndra da''ö, me no ö''erogö Lowalangiu Yehowa, me luo i''ohe dangau ba lala?[11]', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 18, 'Ba i''ya''e, ba ha döi wa möi''ö ba danö Miserayi, ba wamadu idanö Nilo andrö? Ba ha döi wa möi''ö ba danö Asiria, ba wamadu idanö Oifarati?', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 19, 'Falukha wotu ndra''ugö ibe''e si lö sökhi andrö khöu, ba itegu ndra''ugö fa''erosa andrö; ba ya aboto ba dödöu, ya ö''ila, wa si lö sökhi, wa afökhö, wa no ö''erogö Lowalangiu Yehowa, wa lö ö''ata''ufi ndra''o, iŵa''ö So''aya, Yehowa ngahönö andrö.[12]', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 20, 'I''otarai föna sa''ae, ba öfatö galo mbagi khöu ba ö''etu''ö wesumö ba ömane: Lö möido enoni; ba lö zuzu hili-hili ba lö börö geu, si lö ö''oro''ö ndra''ugö ba wohorö.[13]', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 21, 'Ba ya''odo, ba no utanö ndra''ugö ŵeŵe nagu si sökhi, ha sambalö si duhu; ba he moroi, wa no tobali ŵeŵe zotanga gari ndra''ugö?[14]', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 22, 'Ba he ödukhu ndra''ugö idanö nawu ba he ö''oya''ö zabu, ba da''i zui horöu andrö wamaigigu, iŵa''ö Soaya, Yehowa.[15]', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 23, 'He moroi, wa tola öŵa''ö. Lö nita''unöigu ya''odo, lö si möido ba Mba''ali andrö? Faigi nitöröu andrö ba ndraso, ya aboto ba dödöu nilaumö, ya''ugo sigelo gondra, saoha ahe, si riŵa lalania;', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 24, 'sigelo galide gatua, si no to''ölö ba danö si mate, sihasu-hasu ba nangi, ba wa''aukhunia andrö, — ha niha zamadöhö felowunia andrö? Dozi sangalui ya''ia, ba alakha lö erege dödö; na baŵania andrö, ba lasöndra manö.', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 25, 'Faigi-faigi gaheu, fa böi aheta mbadagahe, ba tölö-tölöu, fa böi mamorege wa''otufo! Ba ömane: Zaya-zaya gölö, lö u''o''ö, omasido mbö''ö, ba khöra u''o''ö.', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 26, 'Si mane sanagö, saila na lara''u ia, si manö dania wa''aila ma''uwu Gizeraeli, awö razora ba kumandru sebua khöra ba ere ba sama''ele''ö khöra,', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476325, 'OT', 'Yeremia', 2, 27, 'sanguma''ö ba mbalö geu: Amagu ndra''ugö! ba ba gara: Ya''ugö zadono ya''o! Noa sa la''erogö ndra''odo; lö ni''otahögöra ya''o. Ba na baŵa wamakao, ba mu''ao ira: Faoso ba orifiga!', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 28, 'Ba heza atö so Lowalangiu andrö, nifazökhiu khöu? Akha maoso ira, ma atö la''ila la''orifi''ö, na no göna famakao ndra''ugö. Fa''oya mbanua khömi sa''ae wa''oya Lowalangiu, ya''ugö mado Yuda![16]', '["Yes 1:7; 5:29; Faigi 4:7","Yes 19:13","Faigi 4:18","Hos 5:5","Yes 57:5; Faigi 3:6","MozII 15:17; Sin 44:3; 80:9; Yes 5:1; Mar 12:1; Luk 20:9","Yob 9:30","MozV 32:37; Sanguhuk 10:14; Yes 2:8; Faigi 11:13"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 29, 'Hana wa mukökö-kökö ami khögu? Noa sa''ae ahori mi''erogö ndra''odo, iŵa''ö Yehowa.', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 30, 'Zaya-zaya gölögu wangotu''ögu iraonomi; lö nibe''emi ba dödömi fotu; no i''a zama''ele''ö andrö khömi si''ölimi, timba zingo sange''enge''e.[17]', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 31, 'He si lö ngaroro! Mitöngöni daroma li Yehowa andrö! Hadia tanö si mate mege ndra''odo ba Ndraono Gizeraeli, ba ma tanö si no ogömi-gömi? Ba hana wa lamane banuagu: Aefaga! Lö''ö sa''ae möiga khöu!', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 32, 'Hadia, olifu maö nono alawe nayania, ba olifu nono nihalö mböbö dalunia? Ba noa zui olifu mbanuagu ndra''odo, ha mega sa''ae![18]', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 33, 'No maulu wamaigiu lala, ba wangalui somasi ya''ugö! Tobali lö''ö na''i ata''u''ö mamazökhi horö, ba nitörömö andrö.', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 34, 'Ba gahe mbarumö a''i so ndro zi numana, nibunu lö horö. Tenga sa ba wanöi yomo öra''u ira; börö da''ö no mege fefu.[19]', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 35, 'Ba ömane zui: Lö horögu: no atö döhö wönunia khögu! Hiza, usekhegö dania ndra''ugö, me öŵa''ö: Lö horögu!', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 36, 'Ba hana wa aösö moloi''ö, ba wanörö lala bö''ö zui? He ba Ndrawa Miserayi andrö, ba aekhu ba wa''aila dania, si mane fa''ailamö ba Ndrawa Asiria mege.[20]', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476325, 'OT', 'Yeremia', 2, 37, 'Sondra''u högöu dania ndra''ugö, na ö''otarai ira; itibo''ö sa''ae Yehowa nidöna-dönau fangorifi ba tobali faya khöu ba khöra.', '["Faigi 5:3; Mat 23:34","Faigi 13:1 b.t.","MozII 22:2","Nga''ötII 28:20; Yes 30:5"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 1, 'Imane Yehowa: Na itibo''ö ngambatönia niha ba na iröi ia, na möi donga niha bö''ö, hadia, tola ifuli ia khönia [ira matua andrö]? Hadia, lö ta''unö danö si manö? Ba no ato zi horöni ya''ugö, ba hadia, tola öfuli''ö khögu? — iŵa''ö Yehowa.[1]', '["MozV 24:1 b.t.","Hos 4:13","MozV 11:14; Hez 3:7","Sin 103:9"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 2, 'Faöga höröu ba hili-hili andrö si lö eu''eu ba faigi: Hezo zi lö tehoröni ndra''ugö? Ba zinga lala dumadao ndra''ugö, manarogö ya''ira, si mane Dawa Ara ba danö si mate ba ta''unö danö öbe''e ba wohorömö ba ba walösökhiu andrö.[2]', '["MozV 24:1 b.t.","Hos 4:13","MozV 11:14; Hez 3:7","Sin 103:9"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 3, 'Ba tetaha deu ba lö alua deu sara andrö, ba fa''abe''e mbawa ndra alawe sabao wa''abe''e mbawau, te khöu wa''aila.[3]', '["MozV 24:1 b.t.","Hos 4:13","MozV 11:14; Hez 3:7","Sin 103:9"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 4, 'Ba iya''e, ba mu''ao''ö khögu, ömane: He Ama, si no fahuwu khögu, me ono alawe ndra''odo, ndra''ugö!', '["MozV 24:1 b.t.","Hos 4:13","MozV 11:14; Hez 3:7","Sin 103:9"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 5, 'Hadia, si lö mamalö-malö wönunia, ba irugi zi lö aetu lö aefa ba dödönia? Si manö sa wehedeu, ba solau si lö sökhi ndra''ugö, lö öbato.[4]', '["MozV 24:1 b.t.","Hos 4:13","MozV 11:14; Hez 3:7","Sin 103:9"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 6, 'Ba humede khögu Yehowa, me luo razo Yosia andrö, imane: Hadia, no ö''ila nilau galawe si fa''ero andrö, Iraono Gizeraeli? No dozi hili salaŵa isaŵa ba dozi börö geu sauri, ba mohorö ba da''ö.[5]', '["Faigi 2:20","Hez 16:46"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 7, 'Ba umane dödögu: Na no ahori itörö da''ö, ba ifuli ia khögu, ba lö sangawuli ia! Ba i''ila da''ö si faröi andrö, talifusönia, mado Yuda.[6]', '["Faigi 2:20","Hez 16:46"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 8, 'Ba he ŵa''ae i''ila, da''ö mbörö wanibogu alawe si no fa''ero andrö, Iraono Gizeraeli, ba börö wame''egu sura wangefa khönia, me no mohorö ia, ba lö''ö zui ata''u zi faröi andrö, talifusönia, mado Yuda, möi zui ia ba mohorö göi.', '["Faigi 2:20","Hez 16:46"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 9, 'Ba ba duria wohorönia andrö, ba ta''unö danö; ba gara ba ba geu sa''ae orudu ia, wohorö.', '["Faigi 2:20","Hez 16:46"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 10, 'Ba he ŵa''ae da''ö fefu, ba tenga soroi ba dödö wangawuli zi faröi andrö, talifusönia, mado Yuda, no famini tödö wangawulinia khögu! — iŵa''ö Yehowa.', '["Faigi 2:20","Hez 16:46"]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 11, 'Ba imane khögu Yehowa: Hulö zi lö horö galawe si fa''ero andrö, Iraono Gizeraeli, wamaigida, ba ngai zi faröi andrö, mado Yuda![7]', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 12, 'Ae farongogö daroma li andre miyöu, ömane: Fuli''ö, ya''ugö alawe si no fa''ero, Iraono Gizeraeli — iŵa''ö Yehowa — lö''ö sa''ae mofönudo khömi, me no sebua tödö ndra''odo — iŵa''ö Yehowa — tenga si lö aetu wönugu![8]', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 13, 'Ba ya aboto ba dödöu horöu, wa no fa''ero ndra''ugö khö Lowalangiu, awö wa no ötörö lala saköi, we''amöi ba mbö''ö andrö, ba mbörö geu sauri fefu: ba lö nifondrondrongou ligu — iŵa''ö Yehowa.', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 14, 'Mifuli ami, ya''ami ono matua si no fa''ero — iŵa''ö Yehowa — me no ya''odo Zo''aya ya''ami — ba uhalö ami, samösa zamba banua ba darua zamba mado, ba u''ohe ami ba Ziona.[9]', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 15, 'Ba ufataro khömi gubalo, si faduhu dödögu, ena''ö lakubaloi ami si so fa''aboto ba dödö ba fa''atua-tua.[10]', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 16, 'Ba na ato dania ami, na mo''ono''ono ami ba danö, na luo da''ö — iŵa''ö Yehowa —, ba lö''ö sa''ae laŵa''ö: "Tawöla gamabu''ula li khö Yehowa"! ba lö''ö sa''ae itörö tödö niha, lö''ö sa''ae la''angeragö ba lö la''amalösi, ba lö''ö sa''ae lafuli lafazökhi.', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 17, '"Dadaoma Yehowa" labe''e töi Yeruzalema andrö, na luo da''ö, ba owulo dania ba da''ö fefu niha baero, börö döi Yehowa andrö ba Yeruzalema, ba lö''ö sa''ae abe''e dandrora, wolo ö nikhoi dödöra andrö, si lö sökhi.[11]', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 18, 'Na luo da''ö, ba fao ira ma''uwu Yuda ma''uwu Gizeraeli, la''otarai danö moroi yöu, orudu ira wanaŵa tanö andrö, nitehegu khö ndra tuami, tana khöra.', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 19, 'Noa sa umane dödögu: Si sökhi ube''e khöu, ba ndraonogu andrö, tanö omasiö utehe khöu, fondrege zi sökhi dana khöu ba niha fefu. Ba umane [na] dödögu: Si fa''ama ami khögu ba lö mibulö''ö wolo''ö khögu.[12]', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 20, 'Ba no mi''erogö ndra''o, ya''ami ma''uwu Gizeraeli, amaedola ndra alawe si fa''ero ba zomasi ya''ia — iŵa''ö Yehowa.', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 21, 'Hiza li, ba hili si lö eu''eu andrö: fege-ege Ndraono Gizeraeli andrö me no latörö lala sabila, me no olifu ira Lowalangira Yehowa![13]', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 22, 'Mifuli ami, ya''ami ono matua si no fa''ero, da''ufadöhö lua-lua wa''erosami andrö! — Ya''e ndra''aga, möiga khöu, me no Yehowa ndra''ugö, Lowalangima!', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 23, 'Si ndruhu, falimosa wagua-guasa si terongo moroi yaŵa, moroi ba hili; si ndruhu, khö Lowalangima Yehowa so wangorifi Ndraono Gizeraeli!', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 24, 'No i''a gölö ndra tuama "fa''aila" andrö, i''otarai iraono ndra''aga, biri-birira ba saŵira ba onora matua ba onora alawe!', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476326, 'OT', 'Yeremia', 3, 25, 'Damaföröni wa''afusi mbawama ba akha ambalama wa''ailama andrö; me no mafazökhi horö ba Lowalangima Yehowa, ya''aga, ba ira tuama, i''otarai iraono ndra''aga, irugi ma''ökhö andre, ba lö nifondrondrongoma li Lowalangima Yehowa.', '["Hez 16:51; 23:11","Sin 86:15","Faigi 31:32","Faigi 23:4","Mikh 4:2","MozV 7:6; 8:7","Sakh 12:10 b.t."]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 1, 'Na öfuli''ö, ya''ugö mado Gizeraeli — iŵa''ö Yehowa —, na öfuli''ö khögu ba na öheta ba duduma hörögu zogoro ita andrö ba na öbato wanörö-nörö andrö,', '["MozV 10:20"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 2, 'ba moroi ba dödöu sa''ae ba si ndruhu-ndruhu wahölusamö andrö ba wa''auri Yehowa, ba lafahowu''ö ira soi niha ba khönia andrö ba lasuno ira ba khönia.[1]', '["MozV 10:20"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 3, 'Da''ö sa niŵa''ö Yehowa ba mado Yuda ba ba mbanua Yeruzalema: "Milahoi zi bohou ba böi mi''anaru ba zi so börö za''a-sa''a mao.[2]', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 4, 'Miboto ami khö Yehowa, misaka guli dödömi andrö, ya''ami mado Yuda ba ya''ami banua Yeruzalema, fa böi muhola wönugu, si mane alitö, fa böi si tebai mate hola-holania, ba walösökhi wolaumi andrö!"[3]', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 5, 'Mi''ombakha''ö ba mado Yuda ba ba Yeruzalema, mi''ao khöra, mimane: Milau dorofe, ba danö! Mi''ao, mi''ebua''ö li, mimane: Mi''owuloi ami, ena''ö tasaŵa mbanua saro andrö!', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 6, 'Mitaru''ö mandrera ba lala ba Ziona: mi''oloi, böi mibadugö ami! Famakao sa''ae ufa''aso moroi yöu ba famufu sabölö-bölö.[4]', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 7, 'No möi miyaŵa zingo, moroi ba mbini-mbininia du''u, no maoso zamakiko soi niha, no iröi nahania, ba wamali''ö tanö si mate tanömi andrö, fa adudu mbanua, fa lö niha sa''ae.', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 8, 'Andrö mi''onukha gonigoni, mi''e''esi ba mi''abölögö wege-ege: lö''ö sa si döhö hola-hola wönu Yehowa khöda.[5]', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 9, 'Ba na luo da''ö — iŵa''ö Yehowa — ba si lö lala dödö razo ba he kumandru sebua, ba satöngö gere ba si tobali tödö zama''ele''ö.', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 10, 'Ba umane: He So''aya, Yehowa! Si ndruhu, no öhaogö wolimo soi andre ba banua Yeruzalema, me ömane: Falukha ami wangorifi! Si mate ba mbawa zi''öli ira, a ine.', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 11, 'Ba na luo da''ö, ba lamane ba mado andre ba ba mbanua Yeruzalema: Amaedola nangi saukhu ba hili si lö eu''eu andrö ba danö si mate wolau mbanuagu andrö, tebai ba wamöbörö ba tebai ba wangehao!', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 12, 'Angi sabölö zanörö ya''odo, moroi ba khöra; ba iya''e, ba ya''odo göi zangetu''ö huku!', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 13, 'Hiza, hulö lawuo wa''asora moroi sa, si mane angi sabölö guretara; salio moroi ba moyo kudora. Alai ita, si no afufu ita!', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 14, 'Sasai dödöu, heta zi lö sökhi andrö, ya''ugö banua Yeruzalema, ena''ö te''orifi ndra''ugö; ha wa''ara na lö tebulö ba dödöu gera-era si lö sökhi andrö?[6]', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 15, 'Hiza zangombakha, moroi ba mado Dano lafarongogö wamakao, moroi ba hili mado Geferayi.', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 16, 'Mifaŵa''ögö ba niha baero, mimane: Milabu! mikaoni zanuwö Yeruzalema! So zanuwö moroi ba danö saröu, mu''ao ira, wanuwö banua mado Yuda andrö.', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 17, 'Amaedola zanaro ba nowi lafasui, me no lalaŵa ndra''odo — iŵa''ö Yehowa.', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 18, 'Lua-lua lalamö andrö ba lua-lua wolaumö da''ö khöu: falösökhiu da''ö, wa no afökhö, wa ira''u dödöu.[7]', '["Hos 10:12","MozV 10:16; Rom 2:28; Kol 2:11","Faigi 1:14","Faigi 6:26","Sin 51:4; Yes 1:16","Faigi 2:29"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 19, 'Alai dödögu! Alai dödögu! Wa''afökhö! Tödögu bakha! Rumuru dödögu! Tebai ahono ndra''o! Örongo sa''ae li dorofe, ya''ugö tödögu, fe''ao ba wanuwö.[8]', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 20, 'Fatete manö wangombakha fa''adudu, no tekiko danö, ma''asagörö, adudu manö nosegu andrö, lö mudöna-döna, ha mamö''i hörö wa''ara, ba adudu nöugu andrö.', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 21, 'Ha wa''ara na u''ila-ila mandrera, ba ha wa''ara na urongo li dorofe?', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 22, 'Sowöhö mowa sa mbanuagu andrö; lö aboto ba dödöra ndra''odo; iraono si lö tödö ira, ba lö fa''aboto ba dödö. Satua-tua ira ba wolau si lö sökhi, ba folau si sökhi, ba lö la''ila.', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 23, 'Ufaigi danö, ba hiza, no tanö si mate ba si lö ösi! ba banua si yaŵa — ba lö hagania sa''ae!', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 24, 'Ufaigi hili, ba hiza, ba humeu; ba hili-hili fefu, ba mangiwa!', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 25, 'Ufakhölö ndra''o, ba hiza, samösa lö niha sa''ae, ba fofo ba dalu mbanua, ba no ahori moloi.', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 26, 'Ufakhölö ndra''o, ba hiza, no tobali tanö si mate hili Garemeli andrö, ba banua khönia, ba no ahori adudu — föna Yehowa, ba hola-hola wönunia andrö.', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 27, 'Da''ö sa niŵa''ö Yehowa: Tobali tanö si mate danö, ma''asagörö; ba lö''ö sa atö ufalua wangohori [ya''ira].[9]', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 28, 'Andrö abu dödö danö, ba banua si yaŵa ba alu, me no uŵa''ö da''ö ba me lö mangesa dödögu; me no uhonogöi ba me lö''ö sa''ae uwu''ai.', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 29, 'Ba wagua-guasa zi fakudo andrö ba ba wagua-guasa zolohe fana, ba moloi mbanua fefu, lasaŵa ndru''u, manöi ba gara ba hili: dozi banua, ba lö niha-niha, lö''ö sa''ae si iagö yomo.', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 30, 'Ba ya''ugö nidudugö, ba he öwisa? he ö''onukha mbaru luo si sökhi ba he ö''o''aya naya balaki ba he öfake wanikha samohua, fangalösö mbumö, ba zaya-zaya gölö sa atö wangehaomö andrö, lö edöna zomasi ya''ugö ena''ö; la''alui wamunu ya''ugö.', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476327, 'OT', 'Yeremia', 4, 31, 'Urongo sa''ae wege-ege, hulö ba zafökhö hulu, fangarö-ngarö, hulö ba zawena madono, fege-ege mbanua Ziona andrö, mangarö-ngarö ia, i''oro''ö dangania, imane: Alai ndra''o, aetu nosogu labe''e sange''e andrö!', '["Yes 16:11","Faigi 46:28"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 1, 'Mitöröi newali Yeruzalema ba mifaigi, ya aboto ba dödömi: mi''alui ba newalira, na misöndra zamösa, na so niha solau satulö sama''ua fa lö faröi, fa ube''e aefa horöra.[1]', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 2, 'Ba he laŵa''ö: "Ba wa''auri Yehowa" ba faya zui wahölusa andrö khöra.[2]', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 3, 'Ba ya''ugö Yehowa, hadia, tenga siduhu ötöngöni. No öbago ira, ba lö afökhö khöra; öhori ira, ba lö labe''e ba dödöra wotu andrö; no la''abe''e''ö mbawara, abe''e moroi ba gara; lö sedöna ira mamalalini era-erara.[3]', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 4, 'Ba no umane dödögu: Niha si lö töi ira, sowöhö mowa, me lö la''ila lala andrö khö Yehowa ba satulö andrö khö Lowalangira;', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 5, 'damöido ba zalaŵa, fahuhuodo khöra, me no ya''ira zangila lala andrö, khö Yehowa ba satulö andrö khö Lowalangira! Ba dozi no larasa galo mbagi andrö, ya''ira andrö, ba no la''etu''ö wesu.', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 6, 'Andrö ira''u ira singo, si oroi gatua, ba ifufu ira asu gatua ba danö si mate; manaro harimo ba gero mbanua khöra, ba dozi si möi baero mbanua ba tesasawi; me no mofinaeta lalöra, ba me no asese fa''ero ira.[4]', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 7, 'Hadia, wa ube''e aefa horöu? No la''erogö ndra''o iraonou ba fahölu ba zi tenga Lowalangi, ba he ŵa''ae no u''abusoi''ö ira, ba noa zui la''erogö zodonga ya''ira ba lahurufai nomo zohorö.', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 8, 'Si lö ahono ira, timba kudo satabö; dumele, i''alui ndronga nawönia zamösana.[5]', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 9, 'Hadia, lö u''otu''ö zi manö? iŵa''ö Yehowa — ba lö ulau mbalögu ba niha si manö amuata?', '["MozI 18:32; Hez 9; Fam 7","Faigi 4:2","Yes 9:13; Faigi 2:30","Hos 13:7","Hez 22:11"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 10, 'Mi''anöisi göli khöra ba midudugö, ba böi mihori [ira]; mi''etu''o ngenge, me no tenga khö Yehowa ira![6]', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 11, 'Noa sa faröi ira khögu, he ma''uwu Gizeraeli ba he ma''uwu Yuda — iŵa''ö Yehowa.[7]', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 12, 'No la''osilö''ögö Yehowa, no lamane: Tenga ya''ia! ba lö''ö sa göna ita famakao: he si''öli, ba he lofo, ba lö ta''ila.', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 13, 'Ba tobali angi dania zama''ele''ö andrö; lö''ö sa barö dotora sihede andrö. Ya itörö ira si manö![8]', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 14, 'Andrö wa imane Yehowa, Lowalangi ngahönö andrö: Me no mimanö wehede, ba ubali''ö alitö daroma ligu ba mbeweu, ba ubali''ö eu niha andrö, ena''ö i''a ira [alitö andrö]![9]', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 15, 'Hiza, ufatörö khömi soi, moroi ba zaröu, ya''ami ma''uwu Gizeraeli — iŵa''ö Yehowa — soi sabölö, soi si no arara, soi si lö mi''ila li ba si lö aboto ba dödömi hadia wehedera.[10]', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 16, 'Amaedola lewatö si no mukhau naha nono wana khöra, ha sambalö sabölö ira.', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 17, 'La''a dania mbua nowimi, ömi fakhe, numalö onomi matua ba onomi alawe, ba la''a, ba biri-biri khömi ba saŵi khömi, ba la''a, agu khömi ba bua ara, ba öra; banua saro andrö khömi, nidöna-dönami, ba larasa si''öli.[11]', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 18, 'Ba he na luo da''ö göi, ba lö ufalua wangohori ya''ami — iŵa''ö Yehowa.', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 19, 'Ba na miŵa''ö dania: Hadia mbörö, wa ilau khöda da''ö fefu Lowalangida Yehowa? ba ömane khöra: Si mane fangerogömi ya''odo, wamosumange Lowalangi bö''ö ba danömi, si manö we''amöimi sawuyu niha bö''ö, ba danö si tenga khömi.[12]', '["Faigi 4:27","Faigi 3:20","Yes 28:15","Faigi 1:9","MozV 28:49; Faigi 1:15; 6:22","MozIII 26:16; MozV 28:39","Faigi 16:10 b.t."]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 20, 'Mi''ombakha''ö da''ö ba ma''uwu Yakobo, mifarongogö ba mado Yuda,', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 21, 'mimane: Mifondrondrongo da''e, ya''ami niha sowöhö mowa si lö tödö, si so hörö, ba lö la''ila niha, si so tögi dalinga, ba lö larongo li niha![13]', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 22, 'Ya''odo, ba lö edöna mi''ata''ufi — iŵa''ö Yehowa — ba lö edöna manizi-nizi ami khögu, [khögu andre], si no mame''e tou ene, ola nasi, ba''a-ba''a si lö tobulö, si lö tola isawö — ba he ebua ndrulu, ba tebai, ba he mugoso-goso, ba tebai zui isawö.[14]', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 23, 'Ba soi andre, ba no motödö sabe''e tandro ba si lö edöna molo''ö: no fa''ero ira ba no latörö lalara.', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 24, 'Ba lö''ö sa lamane dödöra: Data''ata''ufi Lowalangida Yehowa, same''e teu andrö, teu sahulö ba teu sara, na baŵania, si lö mowu''ai baŵa wamasi khöda.[15]', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 25, 'Lalömi andrö mbörö, wa no fahole iada''e, ba horömi andrö mbörö, wa lö alua khömi howu-howu.', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 26, 'So sa zanao horö ba mbanuagu andrö: manaronaro, si mane sanaro fofo, na iköwö ia, labe''e tou ra''ura''u, ba wondra''u niha.', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 27, 'Si mane rökaröka so''ösi fofo, si manö wa''amo''ösi nomora ana''a falimosa: ba wolau si manö salaŵa ira ba so''ana''a.', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 28, 'No atabö ira, no ozönözönö. Ba falawu ba mbewera huhuo si lö sökhi; ba huhuo zi lö ama, si lö ina, ba lö lafatunö, ba wame''e möna ya''ira, ba huhuo zi numana, ba lö la''ohe ba lala.[16]', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 29, 'Hadia, lö uhuku zi mane da''ö? — iŵa''ö Yehowa — ba lö ulau mbalögu ba niha si manö amuata?[17]', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 30, 'Sihokha mbuda ba si tobali dödöda nilau ba danö.', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476328, 'OT', 'Yeremia', 5, 31, 'Sama''ele''ö andrö — ba falimosa wama''ele''öra, ba ere andrö — ba awö-awöra wolau, ba banuagu andrö — ba somasi si manö! Ba he miwisa ba gamozua da''ö?[18]', '["Yes 6:9","MozI 1:9; Yob 26:10","MozV 11:14","MozV 32:15; Yes 1:23","Faigi 9:9","Hez 13:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 1, 'Mi''oloi, ya''ami mado Mbeniyami, miröi Yeruzalema ba ba Dekoa, ba milau dorofe, ba Mbetikere mitaru ö mandrera: mangaha sa''ae wamakiko moroi yöu, famufu sabölö-bölö.[1]', '["Faigi 1:14"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 2, 'Da''ufufu nono Ziona alawe andrö, si sökhi andrö, nihaogö-haogö mege folau hadia ia.', '["Faigi 1:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476329, 'OT', 'Yeremia', 6, 3, 'Möi khönia gubalo, la''ohe guriföra, lafasui ia osera ba ikubaloi gurifönia zamösana, ba dana khönia.', '["Faigi 1:14"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 4, '[Lamane]: Mi''amoni''ö ami, ba wanuwö ya''ia! Talabu, tadegeni ita ba zi laluo! Alai ita! bongi sa''ae; adöni sa''ae lumö, lumö na tanö owi!', '["Faigi 1:14"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 5, 'Talabu, ena''ö takhamö ba zi bongi, ba wanudugö gödora!', '["Faigi 1:14"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 6, 'Imane sa''ae Yehowa ngahönö andrö: Mi''obö geu khöra, mifasui Yeruzalema fari! Banua ni''otu''ö ia. No fahöna wamalangögö awöra bakha ba mbanua.', '["Faigi 1:14"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 7, 'Si mane fangumbungumbu nidanö ba gumbu, wangumbungumbu zi lö sökhi khöra: fayaŵasa ba famalangögö zi terongo ba khöra; awai ni''ilagu, ha sambalö fangabu dödö ba famakao.', '["Faigi 1:14"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 8, 'Fondrondrongo wanegu, ya''ugö Yeruzalema, fa böi aefa dödögu khöu, fa böi ubali''ö tanö si mate ndra''ugö, tanö si lö niha-niha sa''ae!', '["Faigi 1:14"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 9, 'Da''ö niŵa''ö Yehowa ngahönö: Lahaogö dania wangozaragö wo''uwo''u, si tosai Iraono Gizeraeli, si mane ba mbua nagu; lafulifuli wanutuyu, si mane sangozaragö bua nagu, si lö aefa-aefa tanga ba ngenge.[2]', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 10, 'Ba ha khö muhededo, ha khö ufaduhu''ö, ena''ö lafondrondrongo? Hiza, si lö muboto dögi dalingara, ba tebai lafondrondrongo! Hiza, la''o''aya daroma li Yehowa, lö omasi ira.', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 11, 'Ba no fahöna khögu wönu Yehowa andrö, u''eregesi dödögu wanaha ya''ia: ba lau sa''ae ia ba ndraono baewali ba ba nono matua misa, fefu; he sa ira matua ba he ira alawe, ba göna dania, fabaya si no tohare huwa ba si no atua sibai.', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 12, 'Ba niha bö''ö dania zokhö omora ba benuara ba fo''omora, fefu; ututuru sa''ae niha ba danö — iŵa''ö Yehowa.[3]', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 13, 'I''otarai sa''ae ndraono, numalö ba zatua, ba oi sangalui hare; ba he sama''ele''ö, ba he ere, ba oi dozi solau faya ba falimosa.[4]', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 14, 'Ba lafayaigö wamadöhö fökhö mbanuagu andrö, wanguma''ö: Fangorifi! fangorifi! ba lö''ö sa fangorifi.[5]', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 15, 'Saila ira ena''ö, me no lalau zogoro ita, ba lö''ö sa aila ira, lö''ö sa''ae la''ila hadia wa''aila. Andrö tegaölö tou ira dania, awö zalau andrö; na baŵa wamatörö huku khöra, ba tetaru mbagi, iŵa''ö Yehowa.', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 16, 'Da''ö niŵa''ö Yehowa: Mi''ae ba lala ba mifaigi ba misofu lala ba götö föna, heza lala ba wa''ohahau dödö, ba mitörö ia, ena''ö misöndra zolombase dödömi! Ba lamane: Lö edönaga matörö![6]', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 17, 'Ba no ufataro zanaro ya''ami [umane]: Mifondrondrongo li dorofe! Ba lamane:', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 18, 'Lö edönaga mafondrondrongo! Ba mifondrondrongo, ya''ami niha baero, ba ya aboto ba dödömi, ya''ami banua, hadia nifatörö khöra.', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 19, 'Fondrondrongo, ya''ugö uli danö; ufatörö sa''ae wamakao ba niha andrö, lua-lua nikhoi dödöra andrö, lö''ö sa nitöngönira niŵa''ögu andrö, ba famobawagu lala, ba no la''ositengagö!', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 20, 'Ba hadia guna gumöyö andrö khögu, kumöyö Zaba andrö, ba kuli mani si sökhi andrö, moroi ba danö saröu? Tenga fa''omasigu zumange nitunu andrö khömi; ba sumange nitaba andrö khömi, ba lö ba dödögu![7]', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 21, 'Andrö wa imane Yehowa: Hiza, ube''e tou föna niha andre zanendre ira, ena''ö faoma tetaru mbagi, he ama ba he ono matua, ena''ö tekiko zamösana, fabaya awönia.', '["Yes 24:13","MozV 28:30","Yes 56:11","Faigi 8:11; Hez 13:10","Mat 11:29","Sin 40:7; Yes 1:11; Mikh 6:6"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 22, 'Imane Yehowa: So sa''ae niha moroi yöu, maoso soi sebua moroi ba wondrege danö.[8]', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 23, 'Fana ba toho wangönara, safaito ira, lö la''ila wa''ahakhö dödö. Amaedola wegoso-goso ndrulu nasi lira, fakudo ira, no mangaro, si mane niha sanuwö, ba wanuwö ya''ugö, ya''ugö ono Ziona alawe.', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 24, 'No tarongo duriania ba no adada dangada, no ihawui ita fa''ata''u, fanizi-nizi, si mane ba zadono!', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 25, 'Böi ae baero mbanua ba böi törö lala; noa sa mosi''öli nemali andrö — ameta''uö, fasui!', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 26, 'He ya''ami banuada! mi''olembe gonigoni ba mihawui ami awu, mi''e''esi nono matua andrö, si ha sambu-sambua, mi''ege-ege; i''ogomuzaö sa dania ihawui ita sanudugö andrö.[9]', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 27, 'No ufataro sanandraigö banuagu andrö ndra''ugö, hati saro, ena''ö aboto ba dödöu lalara andrö, ena''ö ötandraigö.', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 28, 'No dozi samorege folaŵa ira, somasi mamöbögö si lö duhu, no [ha] töla ba si''öli ira, no dozi samakiko ira.[10]', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 29, 'Fahambuhambu ndruru, ena''ö ahori zimo andrö, ba galitö: ba zaya-zaya gölö wolaogölaogö ba tebai toföfö zi lö sökhi.[11]', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476329, 'OT', 'Yeremia', 6, 30, '"Firö nitibo''ö" labe''e töira; noa sa''ae Yehowa zanibo ya''ira.', '["Yes 50:41","Faigi 4:8","Hez 22:18","Faigi 24"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 1, 'Da''ö daroma li andrö niŵa''ö Yehowa khö Yeremia, me imane:', '["Yes 1:16; Faigi 18:11"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 2, 'I''agö mbawandruhö gosali Yehowa, ba farongogö daroma li andre, ömane: Mifondrondrongo li Yehowa, ya''ami mado Yuda fefu, sanörö bawandruhö andre, we''amöi mangandrö khö Yehowa!', '["Yes 1:16; Faigi 18:11"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 3, 'Da''ö niŵa''ö Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Mihaogö döröŵami lala ba bua-buami, ba lö tebulö ami ba nahiami andre ube''e.[1]', '["Yes 1:16; Faigi 18:11"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 4, 'Böi mihalö fangabe''e dödömi huhuo falimosa andrö, na lamane: Osali Yehowa, osali Yehowa, osali Yehowa da''e!', '["Yes 1:16; Faigi 18:11"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 5, 'Na moroi ba dödömi sa''ae mihaogö döröŵami lala ba bua-buami: na si ndruhu lala mitörö, na so huhuomi ba nawömi;', '["Yes 1:16; Faigi 18:11"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 6, 'na lö mifalangögö zi fatewu gana ba si lö ama, si lö ina ba si no mate ira matua, ba na lö mibunu zi lö hörö, ba naha andre, ba na lö mi''o''ö khö Lowalangi bö''ö — famakikomi:', '["Yes 1:16; Faigi 18:11"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 7, 'ba lö tebulö ami ba nahia da''e ube''e, ba danö andre nitehegu khö ndra tuami, götö-götö wa''ara.', '["Yes 1:16; Faigi 18:11"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 8, 'Ba hiza, ba mihalö fangabe''e dödömi huhuo falimosa andrö, ba lö gunania.', '["MozII 20:13 b.t.","Mat 21:13; Mar 11:17; Luk 19:46","Yos 18:1; SamI 1:3; Sin 78:60","Amaed 1:24; Yes 65:12"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 9, 'He wisa? managö, mange''e ba mohorö ba latunu gumöyö khö Mba''ali ba la''o''ö khö Lowalangi bö''ö, si lö aboto ba dödömi?[2]', '["MozII 20:13 b.t.","Mat 21:13; Mar 11:17; Luk 19:46","Yos 18:1; SamI 1:3; Sin 78:60","Amaed 1:24; Yes 65:12"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 10, 'Ba dania, ba so ami, mi''ondrasi ndra''odo, ba nomo andre, nifao ba döi töigu, ba mimane: Auri ita! ba wolau dania zui sogoro ita andrö fefu?', '["MozII 20:13 b.t.","Mat 21:13; Mar 11:17; Luk 19:46","Yos 18:1; SamI 1:3; Sin 78:60","Amaed 1:24; Yes 65:12"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 11, 'Hadia, no tobali tögi narö hili, nahia zorabu nomo andre, nifao ba döi töigu, wamaigimi? Hiza, ya''odo göi, ba no u''ila — iŵa''ö Yehowa.[3]', '["MozII 20:13 b.t.","Mat 21:13; Mar 11:17; Luk 19:46","Yos 18:1; SamI 1:3; Sin 78:60","Amaed 1:24; Yes 65:12"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 12, 'Mi''ae atö ba nahiagu andrö ba Zilo, ba nifonahagu töigu, ba götö föna, ba mitöngöni, hadia nifatörögu khönia, börö walösökhi mbanuagu Iraono Gizeraeli![4]', '["MozII 20:13 b.t.","Mat 21:13; Mar 11:17; Luk 19:46","Yos 18:1; SamI 1:3; Sin 78:60","Amaed 1:24; Yes 65:12"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 13, 'Ba iya''e, me milau da''ö fefu — iŵa''ö Yehowa — ba me lö''ö zui nifondrondrongomi, he ŵa''ae no a''oi dödögu wehede khömi, ma''öma''ökhö; ba me lö nitemami ligu, he ŵa''ae no mu''aodo khömi,[5]', '["MozII 20:13 b.t.","Mat 21:13; Mar 11:17; Luk 19:46","Yos 18:1; SamI 1:3; Sin 78:60","Amaed 1:24; Yes 65:12"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 14, 'ba ufatörö ba nomo andre nifatörögu ba Zilo andrö, ba nomo andre, nifao ba döi töigu, sabe''e dödömi, ba ba nahia andre, nitehegu khömi ba khö ndra tuami.', '["MozII 20:13 b.t.","Mat 21:13; Mar 11:17; Luk 19:46","Yos 18:1; SamI 1:3; Sin 78:60","Amaed 1:24; Yes 65:12"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 15, 'Ba utimba ami ba duduma hörögu, si mane fanimbagu mege talifusömi andrö, ma''uwu Geferayi ma''afefu.', '["MozII 20:13 b.t.","Mat 21:13; Mar 11:17; Luk 19:46","Yos 18:1; SamI 1:3; Sin 78:60","Amaed 1:24; Yes 65:12"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 16, 'Ba ya''ugö, ba böi angandrö, salahi niha andrö, böi tarongo wakaosamö, ba khöra andrö; böi fakao ndra''odo, lö''ö sa atö ufondrondrongo khöu![6]', '["MozII 32:10; Faigi 11:14; 14:11","Faigi 44:19"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 17, 'Hadia, lö''ö sa ö''ila, hadia nilaura ba mbanua mado Yuda andrö misa ba baewali Yeruzalema!', '["MozII 32:10; Faigi 11:14; 14:11","Faigi 44:19"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 18, 'La''ozaragö geu iraono ba la''ebua''ö galitö ira amara, ba lafaruka hamo ira alawe, ba wamazökhi kue, ö zalaŵa mbanua si yaŵa andrö ira alawe, ba ba wame''e sumange nibadu ba Lowalangi bö''ö, ba wamusi tödögu.[7]', '["MozII 32:10; Faigi 11:14; 14:11","Faigi 44:19"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 19, 'Ba hadia, abu dödögu labe''e? — iŵa''ö Yehowa, — hadia, tenga ya''ira zabu tödö, ba wa''aila dania?', '["MozII 32:10; Faigi 11:14; 14:11","Faigi 44:19"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 20, 'Andrö imane So''aya, Yehowa: Hiza, göna fönugu ba fa''abao dödögu mbanua andrö, he niha ba he uriföra ba he eu ba he sinanö ba nowi, ba muhola [wönugu andrö], tebai mate hola-holania.', '["MozII 32:10; Faigi 11:14; 14:11","Faigi 44:19"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 21, 'Da''ö niŵa''ö Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Mibe''e nönö-nönö zumange nitaba andrö khömi zumange nitunu, ba mi''a nösi!', '["Sin 40:7; Yes 1:11","MozII 19:5; MozIII 26:12; MozV 6:3","Faigi 2:27; 32:33","Nga''ötII 36:15","Faigi 16:12","Faigi 5:3"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 22, 'Lö''ö sa ni''oroi''ögu khö ndra tuami, me luo uheta ira ba danö Miserayi, lö niŵa''ögu hadia ia, ba zumange nitunu ba ba zumange nitaba.[8]', '["Sin 40:7; Yes 1:11","MozII 19:5; MozIII 26:12; MozV 6:3","Faigi 2:27; 32:33","Nga''ötII 36:15","Faigi 16:12","Faigi 5:3"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 23, 'Da''ö sa niŵa''ögu khöra: Mi''o''ö goroisagu, ba Lowalangimi ndra''odo ba banuagu ami; mitörö si''aikö lala, nifakhoigu khömi, ena''ö ohahau dödömi![9]', '["Sin 40:7; Yes 1:11","MozII 19:5; MozIII 26:12; MozV 6:3","Faigi 2:27; 32:33","Nga''ötII 36:15","Faigi 16:12","Faigi 5:3"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 24, 'Ba lö lafondrondrongo, lö labe''e mbörö dalingara: lala nikhoi dödöra latörö, nikhoi dödöra ba wa''abe''enia ba gera-era si lö sökhi andrö, ba no la''erogö ndra''o, lö la''otahögö ndra''odo.[10]', '["Sin 40:7; Yes 1:11","MozII 19:5; MozIII 26:12; MozV 6:3","Faigi 2:27; 32:33","Nga''ötII 36:15","Faigi 16:12","Faigi 5:3"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 25, 'Ba i''otarai luo, me aheta ndra tuami ba danö Miserayi, irugi ma''ökhö andre, ba no ufatenge-tenge khömi genonigu andrö fefu, sama''ele''ö andrö, ero ma''ökhö ufatenge, i''otarai zi hulö wongi.[11]', '["Sin 40:7; Yes 1:11","MozII 19:5; MozIII 26:12; MozV 6:3","Faigi 2:27; 32:33","Nga''ötII 36:15","Faigi 16:12","Faigi 5:3"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 26, 'Ba lö lafondrondrongo khögu. Lö labe''e mbörö dalingara, sabe''e tandro ira, abölö-bölö walösökhi, moroi khö ndra tuara.[12]', '["Sin 40:7; Yes 1:11","MozII 19:5; MozIII 26:12; MozV 6:3","Faigi 2:27; 32:33","Nga''ötII 36:15","Faigi 16:12","Faigi 5:3"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 27, 'Ba na öŵa''ö khöra niŵa''ögu andre fefu, ba lö lafondrondrongo khöu, ba na muhede''ö khöra, ba lö latema liu.', '["Sin 40:7; Yes 1:11","MozII 19:5; MozIII 26:12; MozV 6:3","Faigi 2:27; 32:33","Nga''ötII 36:15","Faigi 16:12","Faigi 5:3"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 28, 'Ba ömane dania, ba khöra andrö: Da''ö niha andrö si lö mamondrongo oroisa Lowalangira, Yehowa, sangositengagö fotu; no taya wa lö faröi, no ahori ba mbewera.[13]', '["Sin 40:7; Yes 1:11","MozII 19:5; MozIII 26:12; MozV 6:3","Faigi 2:27; 32:33","Nga''ötII 36:15","Faigi 16:12","Faigi 5:3"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 29, 'Ba faguti''ö sa''ae naya andrö ba högöu [ya''ugö ono ziona alawe] ba tibo''ö, ba angarö-ngarö ba hili andrö, si lö eu''eu, me no itibo''ö niha andrö Yehowa, me no itimba![14]', '["Yob 1:20; Faigi 16:6","RazII 21:4; Hez 8:5","RazII 23:10; Faigi 19:5","MozV 28:26; Faigi 34:20","Yes 24:8"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 30, 'Noa sa lalau iraono Yuda andrö zi lö omasido famaigi — iŵa''ö Yehowa —; noa sa labe''e ba nomo andrö, nifao ba döi töigu, zogoro ita khöra, ba wana''unöi ya''ia.[15]', '["Yob 1:20; Faigi 16:6","RazII 21:4; Hez 8:5","RazII 23:10; Faigi 19:5","MozV 28:26; Faigi 34:20","Yes 24:8"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 31, 'Ba no lafa''anö naha wame''e sumange Tofeti andrö [sogoro niha] ba ndraso Mbeni-Hinomo, ba wanunu onora matua ba onora alawe, si tenga niŵa''ögu ba si lö irai itörö tödögu.[16]', '["Yob 1:20; Faigi 16:6","RazII 21:4; Hez 8:5","RazII 23:10; Faigi 19:5","MozV 28:26; Faigi 34:20","Yes 24:8"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 32, 'Andrö hiza, irugi baŵa dania — iŵa''ö Yehowa — ba tenga sa''ae Tofeti ba tenga sa''ae daso Mbeni-Hinomo laŵa''ö, "daso wange''enge''e" labe''e töinia, ba labe''e dania lewatö Dofeti andrö, me lö naha sa''ae.', '["Yob 1:20; Faigi 16:6","RazII 21:4; Hez 8:5","RazII 23:10; Faigi 19:5","MozV 28:26; Faigi 34:20","Yes 24:8"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 33, 'Ba tobali ö wofo ba dalu mbanua ba ö gutu ndru''u dania mboto niha andre, lö sanaboi ya''ira.[17]', '["Yob 1:20; Faigi 16:6","RazII 21:4; Hez 8:5","RazII 23:10; Faigi 19:5","MozV 28:26; Faigi 34:20","Yes 24:8"]', NULL),
  (3476330, 'OT', 'Yeremia', 7, 34, 'Ba tebato ba mbanua mado Yuda andrö ba baewali Yeruzalema wa''iki ba fa''omuso dödö, fa''omuso dödö zangowalu ba fa''omuso dödö nono nihalö, ube''e: tobali tanö si mate sa''ae danö.[18]', '["Yob 1:20; Faigi 16:6","RazII 21:4; Hez 8:5","RazII 23:10; Faigi 19:5","MozV 28:26; Faigi 34:20","Yes 24:8"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 1, 'Ba na luo da''ö — iŵa''ö Yehowa — ba lakhau döla razo mado Yuda andrö ba lewatö, ba töla zatuara ba töla gere ba töla zama''ele''ö ba töla nösi mbanua Yeruzalema andrö.[1]', '["RazII 23:16"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 2, 'Ba labologö ba zino ba ba haga mbaŵa ba ba haga ngahönö andrö ba mbanua si yaŵa, somasi ira mege, nifosumangera, nigo''ögo''öra, nisofura li ba sangalulu ira: lö lafuli la''ozaragö ba lö lafuli lako''o, tobali fangatabö zinanö ba danö.', '["RazII 23:16"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 3, 'Ba omasi dania ira wa''amate, moroi ba wa''auri, dozi si tosai andrö, si lö ahori niha si lö sökhi andre, ba danö andrö fefu misa, ba nitibo''ögu ya''ira, iŵa''ö Yehowa ngahönö andrö.', '["RazII 23:16"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 4, 'Ba ömane sa''ae khöra: Da''ö niŵa''ö Yehowa: Hadia, alau maö niha, lö maoso? hadia, ta''erogö hadia ia, ba lö tafuli ta''otahögö?', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 5, 'Ba hana wa la''erogö Yeruzalema niha andrö, si lö tebulö fa''erosa: Hana wa lö laböhöli waya, hana wa te khöra wamuli ya''ira?', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 6, 'No ufondrondrongo ba no terongo khögu: faya lalau, samösa lö sangesa todö ba walösökhinia andrö, fa iŵa''ö: Hadia nilaugu? Oi dozi la''erogö, la''osisi lalara, si mane kudo, sondrölö ya''ia ba zi fasöndra niha.', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 7, 'He sumbila ba dalu mbanua, ba i''ila mbaŵania, ba buru''u ba katawaena ba tumbao, ba lö latalu''i mbaŵa wangawulira, ba banuagu andrö, ba lö la''ila gamakhoita Yehowa andrö.[2]', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 8, 'Hadia wa tola miŵa''ö: Satua-tua ita ba so khöda goroisa Yehowa? Ya''ia! ba no ibali''ö faya fanura waya andrö ba danga zanura.', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 9, 'Saila zatua-tua andrö, si tobali tödö ba nira''u; hiza, taroma li Yehowa andrö, ba no la''ositengagö, ba hadia wa''atua-tua si so khöra?', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 10, 'Andrö ululu ba niha bö''ö ndrongara, ba niha bö''ö dania zokhö benuara; i''otarai sa''ae ndraono, numalö ba zatua, ba oi sangalui hare, ba he sama''ele''ö ba he ere, ba oi dozi solau faya ba falimosa.[3]', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 11, 'Ba lafayaigö wamadöhö fökhö mbanuagu andrö, wanguma''ö: Fangorifi! fangorifi! ba lö''ö sa fangorifi.[4]', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 12, 'Saila ira ena''ö, me no lalau zogoro ita, ba lö''ö sa aila ira, lö''ö sa''ae la''ila hadia wa''aila. Andrö tegaölö tou ira dania, awö zalau andrö; na baŵa wamatörö huku khöra, ba tetaru mbagi iŵa''ö Yehowa.', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 13, 'Ufarahugö, uhori ira — iŵa''ö Yehowa — Lö bua ba nagu ba ba marafala, no aleu mbulu; noa sa uhonogöi zi manga ya''ia.[5]', '["Yes 1:3; Faigi 5:4","Yes 56:11; Faigi 6:12 b.t.","Faigi 6:14","Yes 5:1 b.t.; Mat 21:19; Luk 13:6"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 14, 'Hadia wa dumao-dao manö ita? Mitabu fefu, datasaŵa mbanua saro andrö, ena''ö ba da''ö mate ita. Ibe''e sa''ae tekiko ita Lowalangida Yehowa, ifabadugö khöda langu, me no tafazökhi horö khö Yehowa![6]', '["Faigi 9:15; 23:15","Faigi 14:19","Faigi 4:15","Sin 58:5"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 15, 'Tadöna-döna wangorifi, ba lö hadia ia zi sökhi; tadöna-döna mbaŵa wamadöhö fökhö, ba hiza wa''atobali dödö![7]', '["Faigi 9:15; 23:15","Faigi 14:19","Faigi 4:15","Sin 58:5"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 16, 'Moroi ba Dano terongo wehöfu kudo, humeu danö ma''asambua, ba wa''abölö wedele kudo si matua, ba so ira ba la''a danö, fabaya ösinia ba banua, fabaya niha bakha.[8]', '["Faigi 9:15; 23:15","Faigi 14:19","Faigi 4:15","Sin 58:5"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 17, 'Hiza sa, ufa''aso khömi gulö, sita, si lö fanaka, ena''ö lara''u ami, iŵa''ö Yehowa.[9]', '["Faigi 9:15; 23:15","Faigi 14:19","Faigi 4:15","Sin 58:5"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 18, 'Heza usöndra wa''omuso dödö, ba wa''abu dödö andre! No mofökhö sibai bakha dödögu!', '["Faigi 46:11"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 19, 'Hiza, ebua li we''ao mbanuada andrö, moroi ba danö saröu, lamane: "Hadia, lö''ö sa Yehowa ba Ziona? Hadia, lö ba khöra razora? — Hana wa no la''andrö wönugu, ba geu nifobawa andrö khöra, ba nadu niha bö''ö!', '["Faigi 46:11"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 20, 'No awai wamasi, no ahori mu''ozaragö mbua geu, ba ya''ita, ba lö nisöndrada fangorifi!', '["Faigi 46:11"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 21, 'Me no arasa mbanuada andrö, ba no arasa göi dödögu: Sabu tödö ndra''odo, no tobali dödögu.', '["Faigi 46:11"]', NULL),
  (3476331, 'OT', 'Yeremia', 8, 22, 'Hadia, lö dalu-dalu sa''ae ba Gileadi ba lö''ö sa''ae sodalu-daluni fökhö? Hana sa, wa lö lafalemba dalu-dalu ba mbanuada andrö?[10]', '["Faigi 46:11"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 1, 'Ena''ö na idanö manö nösi högögu ba ena''ö na umbu daŵa hörö hörögu, ba bongi ma''ökhö u''e''esi nibunu andrö, banuada![1]', '["Yes 22:4; Faigi 4:19","Faigi 5:7","Faigi 6:7","MozI 27:36; Faigi 12:6; Mikh 7:5"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 2, 'Ena''ö na so nosegu ba danö si mate, ba uröi mbanuada andrö, uhetado khöra, me no ha sambalö sohorö manö ira, orudua zi faröi.[2]', '["Yes 22:4; Faigi 4:19","Faigi 5:7","Faigi 6:7","MozI 27:36; Faigi 12:6; Mikh 7:5"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 3, 'Lakhai lelara, hulö si mane fanara; ba waya ba tenga ba zi duhu samatörö ira ba danö, fatete manö lalau zi lö sökhi — ba lö aboto ba dödöra ndra''odo! — iŵa''ö Yehowa.[3]', '["Yes 22:4; Faigi 4:19","Faigi 5:7","Faigi 6:7","MozI 27:36; Faigi 12:6; Mikh 7:5"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 4, 'Faoma mi''angelama ba nawömi, ba he talifusö samuza, ba böi mi''amati khönia; dozi talifusö sa''ae, ba falimo, ba awömi fefu, ba möi mamöbögö si lö duhu;[4]', '["Yes 22:4; Faigi 4:19","Faigi 5:7","Faigi 6:7","MozI 27:36; Faigi 12:6; Mikh 7:5"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 5, 'faoma lalimo nawöra ba tenga si duhu wehedera: lafamaha lelara ba wolau faya, ba la''eregesi dödöra wo lau si tefuyu.', '["Yes 22:4; Faigi 4:19","Faigi 5:7","Faigi 6:7","MozI 27:36; Faigi 12:6; Mikh 7:5"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 6, 'No tefasui ndra''ugö falimosa, ba ba walimosa andrö, ba te khöra wa''aboto ba dödöra ndra''odo! — iŵa''ö Yehowa.', '["Yes 22:4; Faigi 4:19","Faigi 5:7","Faigi 6:7","MozI 27:36; Faigi 12:6; Mikh 7:5"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 7, 'Andrö imane Yehowa ngahönö andrö: Hiza, ulaugö ira, utandraigö, he uwisa na sa, ba walösökhi mbanuagu andrö?', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 8, 'Ono wana famunu lelara andrö, lalau waya; lahaogö mbewera khö nawöra, ba bakha ba dödö, ba falimosa.', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 9, 'Hadia lö u''otu''ö zi mane da''ö? — iŵa''ö Yehowa, — ba lö ulau mbalögu ba niha si manö amuata?[5]', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 10, 'Ulau me''e ba hili andrö ba mangarö-ngarödo ba u''e''esi mbenua andrö ba zalo''o, me no itörö alitö, ba tobali lö''ö sa''ae itörö niha ba lö''ö sa''ae irongo wedele gurifö nikubaloi; fofo ba dalu mbanua ba utu ndru''u, ba no moloi, no aheta.[6]', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 11, 'Ba ubali''ö adudula Yeruzalema, naha nasu ana''a, ba banua mado Yuda andrö, ba ubali''ö tanö si mate, si lö niha.[7]', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 12, 'Ha niha zi lö ambö fa''atua-tua, fa aboto ba dödönia da''ö? ba ha niha ba zihede Yehowa, ena''ö ifarongogö, hadia mbörö, wa no tekiko danö, wa no akhozi, hulö danö si mate, si lö itörö niha?', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 13, 'Ba imane Yehowa: Me no lö ba dödöra oroisagu andrö, nibe''egu khöra, ba me lö nifondrondrongora ligu, me lö ni''o''öra,', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 14, 'me no dali manö khöra dödöra sabe''e andrö, ba Mba''ali andrö, nifahaö ndra amara ya''ira,', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 15, 'andrö ube''e ö niha andrö zafeto ba ufabadugö khöra langu — iŵa''ö Yehowa ngahönö andrö, Lowalangi ndraono Gizeraeli.[8]', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 16, 'Ba ufazawili ira ba niha baero andrö, si lö larai mila, ba he ira amara mege, ba ufago''ögo''ö khöra zi''öli, irege no ahori ira ube''e.[9]', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476332, 'OT', 'Yeremia', 9, 17, 'Imane Yehowa ngahönö andrö: Mifaigi ba mihede ba ndra alawe sange''esi, ena''ö lafa''aso ira; mifatenge ba ndra alawe si no to''ölö, ena''ö möi ira, ena''ö la''aliogö ira,', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 18, 'ba wange''esi ya''ita, ena''ö mo''ala''ala höröda, ba ena''ö mowöi-wöi mbu höröda taŵa hörö?', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 19, 'Terongo sa''ae wege-ege sebua li moroi ba Ziona, lamane: "Ha lö afufu ita, no tehawu ita fa''aila, fa taröi danö, me no ladudugö nahiada!"', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 20, 'Ba mifondrondrongo li Yehowa, ya''ami ira alawe, ya möi ba dögi dalingami niŵa''önia, ba mifahaö nonomi alawe ba wange''esi; yamufahaö nawönia zamösana ba wa''ala-alaisa!', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 21, 'Noa sa i''anöisi zandrela khöda fa''amate, no möi yomo ba gödo khöda, ba wangohori iraono baewali, fabaya ono matua baolayama.', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 22, '"Ŵa''öda''ö", iŵa''ö Yehowa; ba no muzaewe tou mboto niha si mate, amaedola goboula fangatabö zinanö ba danö, amaedola ngamböbö wakhe ba döla, moroi furi zamasi, si lö sangozaragö?[10]', '["Sin 12:3; 28:3; 120:4","Faigi 5:29","Yes 34:13; Faigi 10:22","Faigi 8:14; 23:15","MozIII 26:33; MozV 28:64","Faigi 7:33"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 23, 'Imane Yehowa: Böi yamusuno ia ba wa''atua-tuania satua-tua ba böi yamusuno ia ba wa''abölönia sabölö ba böi yamusuno ia ba gana''ania sabua ana''a![11]', '["KorI 1:31; KorII 10:17"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 24, 'Ba da''ö yamusuno ia sedöna manuno ya''ia, me no so khönia wa''aboto ba dödö, me no aboto ba dödönia ndra''odo, wa ya''odo, Yehowa, zangoroma''ö fa''ahakhö dödö ba solau huku ba satulö ba guli danö; da''ö sa zomasido — iŵa''ö Yehowa.', '["KorI 1:31; KorII 10:17"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 25, 'Hiza, irugi baŵa dania — iŵa''ö Yehowa — baŵa wanguhukugu fefu niboto si so uli na.', '["KorI 1:31; KorII 10:17"]', NULL),
  (3476332, 'OT', 'Yeremia', 9, 26, 'Dawa Miserayi ba mado Yuda, Iraono Gedomo ba Iraono Gamoni ba Iraono Moabi ba dozi si no mufalo''o bu, sowanua ba danö si mate, — dozi niha baero sa, ba lö muboto, ba dozi ma''uwu Gizeraeli, ba si lö muboto tödö.', '["KorI 1:31; KorII 10:17"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 1, 'Mifondrondrongo li Yehowa andrö, fehedenia khömi, ya''ami ma''uwu Gizeraeli!', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 2, 'Imane Yehowa: Böi mifamaha ami ba huku niha baero andrö ba böi tokea ami ba dandra andrö ba mbanua si yaŵa, me si tokea niha baero ba khönia![1]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 3, 'Faya, sa nifakhoi niha baero andrö, eu, ni''eŵa ba gatua, nifazökhi danga duka, nifofoe.[2]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 4, 'Lafo''aya firö ba ana''a, labözi gosö-osö, fa böi mangiŵa.[3]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 5, 'Hulö si mane tabotabo wofo ba naha zinanö, ba si lö hede, ni''ohe-ohe, me tebai mowaö-waö: böi mi''ata''ufi ia, tebai sa ifakiko niha ba tebai göi ifa''ema wangorifi.[4]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 6, 'Lö''ö sa si fagölö-gölö khöu, ya''ugö Yehowa, salaŵa ndra''ugö ba no ebua döimö andrö ba wa''abölö andrö.[5]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 7, 'Ha niha zi lö mangata''ufi ya''ugö ena''ö, ya''ugö razo soi niha? Si nangea khöu da''ö, me lö ba zatua-tua fefu ba niha misa ba ba mbanuara fefu si fagölö-gölö khöu![6]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 8, 'Dozi ira sa, ba no sambö era-era ba sowöhö mowa: famahaö andrö ba nadu — ba no eu.[7]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 9, 'Firö niböbözi, nihalö ba Darisi ba ana''a moroi ba Gufa, nifazökhi duka ba tanga zamahele ya''ia; ungu sowu waru-waru ba ungu soyo mbaru, nifazökhi zonekhe, ma''afefu.', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 10, 'Ba no Lowalangi si ndruhu-ndruhu Yehowa, Lowalangi sauri ia ba razo si lö tebulö; ba wönunia humisi danö, ba fa''abao dödönia, ba si tebai lataha soi niha.', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 11, 'Ba mimane khöra: Lowalangi andrö, si no tenga samazökhi banua si yaŵa ba tanö tou, ba si taya dania ba guli danö ba barö mbanua si yaŵa.', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 12, 'Ya''ia, samazökhi tanö ba wa''atua-tuania andrö ba samologö banua si yaŵa ba wa''aboto ba dödönia.[8]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 13, 'Na terongo linia banua andrö, ba mogoso-goso deu, ba i''ohe miyaŵa lawuo moroi ba gahe mbanua, i''asogö gari mbanua, lala deu, ba ifolala nangi moroi ba zi fahöna ia.[9]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 14, 'Dozi atöngö, ba tebai aboto ba dödö; dozi tuka gana''a, ba saila, ba wamaedo andrö, me no falimosa nifahele andrö ba me si lö noso.[10]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 15, 'Faya ia, nifazökhi fango''aya; na baŵa wamatörö huku, ba tekiko.', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 16, 'Ba tenga si fagölö-gölö ba da''ö dana khö ma''uwu Yakobo andrö, no samazökhi tanö''a ia, ba soi tana khönia Ndraono Gizeraeli, Yehowa ngahönö döinia.[11]', '["MozIII 18:3","Yes 44:14 b.t.","Yes 41:7","Sin 115:5 b.t.; Yes 41:23; 46:7","Sin 86:8","Fam 15:4","Hab 2:18; Sakh 10:2","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 17, 'Tuyu gama-gamau ba danö, [ya''ugö ono Ziona] nifasui nemali!', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 18, 'Imane sa Yehowa: Hiza, ufazaumba niha ba danö si samuza andre, tosasa ube''e, ena''ö la''ila [ndra''odo].', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 19, 'Alai ndra''o ba zokhogu andre! Tebai döhö zi gönado andrö. Ba no umane dödögu: Na ha da''ö wamakaogu, ba utaha!', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 20, 'No adudu nosegu, no ahori aetu zinalinia, no aheta khögu nonogu matua, lö ya''ira sa''ae; lö sangazökhi osegu andrö, lö samologö mukonia.', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 21, 'Sambö tödö sa''ae gubalo andrö, ba lö nisofura Yehowa, andrö lö fozu khöra ba no muzaewe guriföra fefu.', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 22, 'Mifondrondrongo! muhöngö — so sa''ae moroi sa, ruru sebua moroi yöu, ba wamali''ö adudula banua mado Yuda andrö, ena''ö tobali naha nasu ana''a![12]', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 23, 'U''ila, ya''ugö Yehowa, wa tebai ihuku lalania niha, awö wa tebai ifanandrösa mbekania niha sanörö lala.[13]', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 24, 'Otu''ö ndra''odo, Yehowa, ba faigi ndrohu-ndrohu, böi be''e dali wönumö, ba böi afufu ndra''o öbe''e![14]', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476333, 'OT', 'Yeremia', 10, 25, 'Ba niha baero andrö lau wönumö, ba zi lö mangila ya''ugö, ba niha si lö mangaröfi li töimö, me no lahori ma''uwu Yakobo, me no lafufu ba me no labali''ö tanö si mate mbenuara.[15]', '["Faigi 5:15; 9:11","Amaed 16:1; 20:24","Sin 6:2; 38:2; Faigi 30:11","Sin 79:6"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 1, 'Niŵa''ö Yehowa khö Yeremia, imane:', '["MozV 27:26; Gal 3:10","MozIII 26:3 b.t.; RazI 8:51","MozI 12:2; MozV 7:12 b.t.","Nga''ötII 36:15; Faigi 7:13","Faigi 7:24"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 2, 'Mifondrondrongo daroma li fawu''usa li andre ba öfa''ema ba mado Yuda ba ba mbanua Yeruzalema andrö!', '["MozV 27:26; Gal 3:10","MozIII 26:3 b.t.; RazI 8:51","MozI 12:2; MozV 7:12 b.t.","Nga''ötII 36:15; Faigi 7:13","Faigi 7:24"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 3, 'Ömane khöra: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli andrö: Ni''elifi niha, si lö mamondrongo taroma li fawu''usa li andrö,[1]', '["MozV 27:26; Gal 3:10","MozIII 26:3 b.t.; RazI 8:51","MozI 12:2; MozV 7:12 b.t.","Nga''ötII 36:15; Faigi 7:13","Faigi 7:24"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 4, 'niŵa''ögu khö ndra tuami, me luo uheta ira ba danö Miserayi, ba mbalanga si''öli andrö folaugö, wanguma''ö: Mi''o''ö goroisagu, mibe''e dali khömi, mitörö sibai niŵa''ögu khömi, ba banuagu ami, ba Lowalangimi ndra''odo.[2]', '["MozV 27:26; Gal 3:10","MozIII 26:3 b.t.; RazI 8:51","MozI 12:2; MozV 7:12 b.t.","Nga''ötII 36:15; Faigi 7:13","Faigi 7:24"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 5, 'Ena''ö lö ubulö''ö zi no möido ba hölu andrö khö ndra tuami, wa edönado ube''e khöra danö si no falawu susu ba ŵe ŵani, si mane ni''ilada ma''ökhö andre! Ba utema li, umane: Ya''ia da''ö Yehowa![3]', '["MozV 27:26; Gal 3:10","MozIII 26:3 b.t.; RazI 8:51","MozI 12:2; MozV 7:12 b.t.","Nga''ötII 36:15; Faigi 7:13","Faigi 7:24"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 6, 'Ba imane khögu Yehowa: Farongogö daroma li andre fefu ba mbanua mado Yuda andrö ba baewali Yeruzalema, ömane: Mifondrondrongo daroma li fawu''usa li andrö, ba mi''o''ö!', '["MozV 27:26; Gal 3:10","MozIII 26:3 b.t.; RazI 8:51","MozI 12:2; MozV 7:12 b.t.","Nga''ötII 36:15; Faigi 7:13","Faigi 7:24"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 7, 'Noa sa ufarourou si''aikö ndra tuami, me luo uheta ira ba danö Miserayi ba irege ma''ökhö andre, u''ota''otarai zi hulö wongi, umane: Mifondrondrongo niŵa''ögu khömi![4]', '["MozV 27:26; Gal 3:10","MozIII 26:3 b.t.; RazI 8:51","MozI 12:2; MozV 7:12 b.t.","Nga''ötII 36:15; Faigi 7:13","Faigi 7:24"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 8, 'Ba lö lafondrondrongo; lö labe''e mbörö dalingara; itorö manö sa''ae nikhoi dödönia si lö sökhi andrö zamösana, ba no ufatörö khöra fefu [wangelifi andrö] ba daroma li fawu''usa li andrö, niŵa''ögu khöra, ni''o''ö ena''ö, ba si lö ni''o''öra.[5]', '["MozV 27:26; Gal 3:10","MozIII 26:3 b.t.; RazI 8:51","MozI 12:2; MozV 7:12 b.t.","Nga''ötII 36:15; Faigi 7:13","Faigi 7:24"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 9, 'Ba imane khögu Yehowa: No mamagölö mado Yuda ba banua Yeruzalema andrö.', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 10, 'No lafuli ira ba golalöŵa ndra tuara moroi yaŵa, si lö edöna mamondrongo ligu — ba la''o''ö ba Lowalangi bo''ö, ba wamosumange: no ladudugö wawu''usa li andrö khögu, he ma''uwu Gizeraeli ba he ma''uwu Yuda, fawu''usa li andrö khögu khö ndra tuara![6]', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 11, 'Andrö imane Yehowa: Ufatörö sa''ae khöra wamakao, si tebai aefa ira, ba na la''angaröfi li dania ndra''o, ba lö ufondrondrongo khöra.', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 12, 'Ba na möi dania mbanua mado Yuda andrö ba banua Yeruzalema, ba wangaröfi li Lowalangira andrö, nitunutunura kumöyö, ba tebai göi latolo ira da''ö, na baŵa wamakao andrö.', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 13, 'Fa''oya mbanua khömi sa''ae wa''oya Lowalangimi, ya''ami mado Yuda; ba fa''oya newali ba Yeruzalema wa''oya naha wame''e sumange andrö, nifa''anömi ba "wa''aila" andrö, naha wanunu kumöyö khö Mba''ali andrö.[7]', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 14, 'Ba ya''ugö, ba böi angandrö salahi niha andrö, böi tarongo wakaosamö ba khöra andrö; lö''ö manö sa ufondrondrongo, na la''angaröfi li ndra''o, na baŵa wamakao khöra![8]', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 15, 'Hadia ni''alui wa''omasigu andrö ba nomogu andrö? Hadia, ba wamalua nikhoi dödönia sonekhe andrö? Hadia, fangeheta zi lö sökhi khöu gamabu''ula li ba ösi zumange ni''amoni''ö, ena''ö tola owua-wua dödöu dania?', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 16, 'Falo satabö, si no fahöna bua si sökhi, ibe''e töimö Yehowa: ba nangi sabölö ibe''e galitö ba mbörö, ba afufu ndrahania.[9]', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 17, 'Yehowa ngahönö andrö, sananö ya''ugö mege, ba no ihonogöi khöu zi lö sökhi, börö walösökhi ma''uwu Gizeraeli ba ma''uwu Yuda, folaura andrö, ba wangandrö fönugu, wanunu kumöyö khö Mba''ali andrö.[10]', '["Sin 18:42; Yes 1:15; Hez 8:18","Faigi 2:28","Faigi 7:16; 14:11","Hos 14:16","Faigi 2:21"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 18, 'Ba no ifarongogö khögu Yehowa, ba no urongo: me luo da''ö ö''oroma''ö khögu wolaura andrö!', '["SamI 16:7; Sin 7:10; 26:2; Faigi 20:12; Rom 12:19"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 19, 'Ya''odo andre, ba no hulö nono mbiri-biri si möi-möi, ni''ohe ba wanaba ya''ia, ba lö u''ila, wa so nifakhaira nilau khögu: datafakiko döla, fabaya bua, tadeha ia ba danö zauri, fa böi sa''ae itörö tödö niha döinia!', '["SamI 16:7; Sin 7:10; 26:2; Faigi 20:12; Rom 12:19"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 20, 'Ba ya''ugö Yehowa ngahönö, samatörö huku satulö ba sanandraigö tödö, fabaya bua, ba fa''ila''ö khögu wolaumö balöu khöra; noa sa ube''e balaziu huhuogu andrö.[11]', '["SamI 16:7; Sin 7:10; 26:2; Faigi 20:12; Rom 12:19"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 21, 'Andrö wa no imane Yehowa, ba khö mbanua Ganatoti andrö, sangalui famunu ya''ugö, wanguma''ö: Böi ama''ele''ö ba döi Yehowa, fa böi mabunu''ö tangama andre!', '["SamI 16:7; Sin 7:10; 26:2; Faigi 20:12; Rom 12:19"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 22, 'Andrö wa no imane Yehowa ngahönö: Hiza ufatörö huku khöra: si mate ba mbawa zi''öli dania nono matua, ba si mate olofo nonora matua, fabaya onora alawe.', '["SamI 16:7; Sin 7:10; 26:2; Faigi 20:12; Rom 12:19"]', NULL),
  (3476334, 'OT', 'Yeremia', 11, 23, 'Lö si tosai dania, ya''ira andrö; famunu sa''ae ufatörö ba mbanua Ganatoti andrö, na döfi wanguhuku ya''ira.', '["SamI 16:7; Sin 7:10; 26:2; Faigi 20:12; Rom 12:19"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 1, 'Satulö ndra''ugö Yehowa na fasoso ndra''o khöu ena''ö; ba da''usekhegö zui ndra''ugö, hadia wa mofozu wolau zebua horö ba hana wa lö hadia ia ba zi falimo andrö fefu?[1]', '["Yob 12:6; 21:7","Yes 29:13","Sin 17:3; 139:1","Faigi 4:25"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 2, 'Ötanö ira ba moŵa''a, manöi ba mowua göi: na ba mbewera, ba ahatö ndra''ugö, ba na ba dödöra ba aröu''ö![2]', '["Yob 12:6; 21:7","Yes 29:13","Sin 17:3; 139:1","Faigi 4:25"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 3, 'Ba ya''ugö Yehowa ba no aboto ba dödöu ndra''odo, ö''ila ndra''o ba ötandraigö dödögu khöu: döni da''iora, si mane biri-biri ba wanaba ba amoni''ö ira, ba mbaŵa wamunu![3]', '["Yob 12:6; 21:7","Yes 29:13","Sin 17:3; 139:1","Faigi 4:25"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 4, 'Ha wa''ara na abu dödö danö ba ha wa''ara na aleu zinanö ba mbolo nowi? Ba walösökhi niha ba danö ahori gurifö niha, fabaya fofo ba dalu mbanua. — Me laŵa''ö: Lö dania i''ila wozuda![4]', '["Yob 12:6; 21:7","Yes 29:13","Sin 17:3; 139:1","Faigi 4:25"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 5, 'Na erege dödöu sa''ae labe''e sanörö tanö, na fao ndra''ugö khöra wagohisa, ba he öwisa wogamö ahe kudo? — ba na ha ba danö si lö hadia ia abe''e dödöu, ba he öwisa ba gatua ba mbewe Yoridano?[5]', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 6, 'Talifusöu na''i ba moroi yomo khömi, ba si falimo khöu; ya''ira göi zangebua li we''ao moroi furiu; böi fati lira, na lahaogö wehedera khöu.[6]', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 7, 'No uröi nomogu ba no u''erogö dana khögu; fondrege zomasido, ba no ululu ba danga zi fa''udu khönia.', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 8, 'Si so khögu andrö, ba no tobali hulö zingo barö gatua khögu; mundröndröndröndrö ia khögu: andrö anuzu dödögu ia.', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 9, 'Hadia, no amaedola wofo sola''a-la''a khögu zi so khögu andrö, wa lafasui ia moyo? Milabu! Mi''owuloi gutu ndru''u fefu, mifa''amöi ira, ba wemanga [ya''ia]!', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 10, 'No ato gubalo, samufu kabu nagu andrö khögu, no lahundra-hundra mbolo nowi khögu, no labali''ö tanö si mate nowi andrö, somasi dödögu.[7]', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 11, 'No tanö si mate labe''e, abu dödö fönagu, no afufu, no tanö si mate danö ma''asagöro, me lö si so ba dödö ya''ia.', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 12, 'Fefu hili andrö, si lö eu''eu ba danö si mate, ba no itörö samufu; so sa wöda khö Yehowa, si manga-manga hadia ia, i''otarai mbalö danö si föfö, numalö ba zi föfö, ba lö ösi guli danö si lö göna.', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 13, 'No lataru wakhe, ba sa''a-sa''a mao ba wamasi; no erege dödöra, ba lö fozu, ba saila sa''ae ami, ba lua-lua andrö khömi, ibe''e fönu Yehowa, saukhu andrö.[8]', '["Faigi 49:19","Amaed 26:25; Faigi 9:4","Faigi 6:3","MozIII 26:16"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 14, 'Imane Yehowa, ba khö zi faola tanö andrö khögu, si lö sökhi, sombambaya tana khö andrö, nibe''egu ba mbanuagu Iraono Gizeraeli: Hiza, uhori ira ba danöra, ba ma''uwu Yuda andrö göi, ba hunöra.', '["MozV 30:3; Faigi 32:37"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 15, 'Ba na no aefa uhori ira, ba ufuli uhakhösi tödö, ba u''ohe mangawuli ira, ufuli ufataro ba dana khönia ba ba danö khönia zamösana.[9]', '["MozV 30:3; Faigi 32:37"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 16, 'Ba tobali, na lafamaha dania ira ba huku mbanuagu andrö, ba wahölusa ba döigu, na lamane [göi]: Ba wa''auri Yehowa! Si mane famamahara banuagu, ba wahölusa ba Mba''ali andrö, ba te''a''azökhi ira, bakha ba hunö mbanuagu.', '["MozV 30:3; Faigi 32:37"]', NULL),
  (3476335, 'OT', 'Yeremia', 12, 17, 'Ba na lö lafondrondrongo, ba udeha niha si manö ba ufaulugö wangohori — iŵa''ö Yehowa.', '["MozV 30:3; Faigi 32:37"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 1, 'Imane khögu Yehowa: Ae öli khöu mböbö talu muko, ba amöbö talu, ba böi basöi idanö.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 2, 'Ba u''öli mböbö talu andrö, u''o''ö niŵa''ö Yehowa khögu; ba u''amöbö talu.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 3, 'Ba ifuli muhede khögu Yehowa imane:', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 4, 'Halö mböbö talu andrö ba löwi-löwiu, ni''öliu andrö, ba ae ba Oifarati ba bini''ö ia ba da''ö ba dögi gara.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 5, 'Ba möido mubini''ö ia ba mbewe Oifarati, si mane niŵa''ö Yehowa khögu.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 6, 'Ba ara ma''ifu, ba imane khögu Yehowa: Ae ba Oifarati ba halö ba da''ö mböbö talu andrö, niŵa''ögu khöu nibini''ö ba da''ö.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 7, 'Ba möido ba Oifarati, u''alui, ukharu ba uhalö mböbö talu andrö ba nahania andrö, ba nibini''ögu ya''ia, ba hiza, no obou mböbö talu andrö, lö gunania sa''ae.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 8, 'Ba humede khögu Yehowa, imane: Da''e niŵa''ö Yehowa:', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 9, 'Si manö dania wamakikogu fayaŵasa mado Yuda andrö ba fayaŵasa mbanua Yeruzalema, si no ebua sibai.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 10, 'Niha si lö sökhi andrö, si lö edöna mamondrongo ligu, si no abe''e tandro, wanörö nikhoi dödöra, wolo''ö ba Lowalangi bö''ö, ba wamosumange ba ba wangalulu khöra, — ba hulö si mane böbö talu andrö, si lö guna sa''ae dania ira.[1]', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 11, 'Hulö si mane böbö talu sa''ae, si fatöfa ba löwi-löwi niha, si manö wamatöfagu khögu ma''uwu Gizeraeli fefu ba ma''uwu Yuda fefu — iŵa''ö Yehowa — ena''ö banuagu ba fangebua duriagu ba fanuno ya''odo ba lakhömigu ira, ba lö lafondrondrongo khögu.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 12, 'Ba ömane sa''ae khöra: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Fefu migö, ba tefo''ösi agu! Ba na lamane dania khöu: Hadia, lö ma''ila wa tefo''ösi agu migö fefu?', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 13, 'Ba ömane khöra: Imane Yehowa: Hiza, ufo''ösi femabu fefu niha ba danö andre, awö razo andrö, ma''uwu Dawido, sidadao ba dadaomania andrö, ba ere andrö ba sama''ele''ö ba dozi banua Yeruzalema andrö.[2]', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 14, 'Ba faoma urasa ira ba nawöra, he ama ba he ono matua, nifarahugö, iŵa''ö Yehowa; lö alimagö ba lö afökhö khögu ba lö ahakhö dödögu, fa lö ufakiko ira ena''ö.', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 15, 'Mifondrondrongo ba mitöngöni! Böi fayaŵa ami, me no Yehowa zihede!', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 16, 'Mifosumange Lowalangimi Yehowa, fatua lö ogömi-gömi na, fatua lö manendre gahemi ba hili si no ogömi-gömi! Ba da''ö mibazebaze''ö sa dania haga, ba fa''ogömi-gömi sabölö ibe''e, si lö oroma turu.[3]', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 17, 'Ba na lö mifondrondrongo, ba me''e ndra''o ba zi lö oroma ndra''odo, ba wayaŵasa andrö, ya böi döhö wenguwengu, ya mangele daŵa hörögu, me ni''oloi''ö zanuwö rorogöfö Yehowa andrö.[4]', '["Faigi 7:24","Yes 51:21; 63:6; Faigi 25:27","Yes 59:9","Ngenu 1:2"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 18, 'Omane khö razo ba khö zamatörö andrö, ira alawe: Mi''ae tou, tanö tou sibai mi''iagö, me no ahele ba högömi naya ba högö, saembu si sökhi sibai andrö![5]', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 19, 'No laduhö mbawa göli mbanua raya ba lö samokai sa''ae; te''oloi''ö mado Yuda fefu, ahori te''oloi''ö!', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 20, 'Mifaöga hörömi ba mifaigi zi otarai moroi yöu andrö! Heza so nikubaloi andrö, nibe''e rorogöföu, rorogöfö si sökhi sibai andrö?', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 21, 'Hadia öŵa''ö, na ifataro salaŵamö zi fahuwu khöu andrö, nifamahau khöu? Hadia, lö ira''u ndra''ugö fa''afökhö hulu, si mane ba zadono?', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 22, 'Ba na ömane ena''ö dödöu: Hadia wa gönado si mane da''ö? — Ba wa''afahöna gölalöŵamö tefahoi gahe lembeu ba tefakao mbörö sisiu![6]', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 23, 'Hadia, i''ila i''afusiö nösinia Dawa saitö ba i''ila iheta la''a-la''ania harimo? awena dania mi''ila milau zi zökhi, ya''ami si no to''ölö wolau si lö sökhi.', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 24, 'Ba ufazawili sa''ae ira, si mane dami wakhe, ni''oloi''ö nangi moroi ba danö si mate!', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 25, 'Da''ö dania dana khöu, urakhau, nihukugu khöu — iŵa''ö Yehowa —, me no olifu''ö ndra''odo ba me no abe''e dödöu ba waya.', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476336, 'OT', 'Yeremia', 13, 26, 'Ba ufahoi göi gahe lembeu ba gangango mbisiu, ena''ö oroma zaila''ö![7]', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476336, 'OT', 'Yeremia', 13, 27, 'Fohorömö andrö ba fedeleu, fohorömö salakha andrö, — ba hili-hili andrö ba ba mbolo mbenua, ba no u''ila zalakha andrö khöu! Alai ndra''o ndra''ugö, Yeruzalema, tebai aheta khöu — ha wa''ara na dania![8]', '["RazII 24:10–16","Faigi 5:19; 16:10","Yes 47:3; Hez 16:37; Hos 2:10","Faigi 5:8"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 1, 'Niŵa''ö Yehowa khö Yeremia ba wa lö teu andrö:', '[]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 2, 'Abu dödö mado Yuda, hulö zariri mbanuara, dumao-dao tou ba danö, alangu sibai dödö; numalö miyaŵa wege-ege Yeruzalema.', '[]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 3, 'Salaŵara, ba lafatenge genonira, ba wana''u idanö, möi ba mba''a, ba lö falukha nidanö, ba mangawuli lö ösi nasoa, no tobali dödöra ba no aila, ba labalugö mbawara.', '[]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 4, 'Ba danö nowi andrö, si no tobali tödö, me lö saekhu ba danö teu tobali dödö zonowi, babalugö mbawara.', '[]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 5, 'Böhö na''i ba mbenua, mo''ono ba iröi, me lö du''u ba danö.', '[]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 6, 'Ba kalide gatua, ba no so ba hili si lö eu''eu, ambö mbadu, si mane ba nasu ana''a; ariri höröra, me lö du''u.', '[]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 7, 'Na i''ombakha''ö ndra''aga horöma andrö, ya''ugö Yehowa, ba be''e börö döimö andrö, wame''e ba lala; noa sa fahöna golalöŵama; khöu no mafazökhi horö!', '["MozII 32:10; Faigi 7:16; 11:14","Yes 1:15; Faigi 6:20; 7:21; 11:11"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 8, 'Ya''ugö tötönafö Ndraono Gizeraeli, sangorifi ya''ira, na baŵa wa''atosasa, hana wa no hulö niha bö''ö ba danö ndra''ugö, hana wa no hulö zikoli solau ose naha wemörö?', '["MozII 32:10; Faigi 7:16; 11:14","Yes 1:15; Faigi 6:20; 7:21; 11:11"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 9, 'Hana wa no hulö niha si no tobali tödö ndra''ugö, hulö zabölö, si tebai mangorifi awönia? Ba noa zui soso''ö ba khöma, ya''ugö Yehowa, ba no töimö mbörö wamotöi ya''aga: böi böhöli ndra''aga!', '["MozII 32:10; Faigi 7:16; 11:14","Yes 1:15; Faigi 6:20; 7:21; 11:11"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 10, 'Imane Yehowa, ba niha andre: Si manö wa''omasira wanörö-nörö, lö lataha gahera, — ba lö omasi Yehowa ira: itörö sa''ae tödönia lalöra ba i''otu''ö ira ba horöra andrö.', '["MozII 32:10; Faigi 7:16; 11:14","Yes 1:15; Faigi 6:20; 7:21; 11:11"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 11, 'Ba no imane khögu Yehowa: Böi andrö wangorifi niha andrö![1]', '["MozII 32:10; Faigi 7:16; 11:14","Yes 1:15; Faigi 6:20; 7:21; 11:11"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 12, 'Na mamoni ira, ba lö ufondrondrongo wakaosara andrö, ba na la''ohe [khögu] zumange nitunu ba sumanga ni''a, ba tenga somasido; uhori na''i ira bawa wöda ba lofo ba bö''a![2]', '["MozII 32:10; Faigi 7:16; 11:14","Yes 1:15; Faigi 6:20; 7:21; 11:11"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 13, 'Ba umane: He So''aya, Yehowa, ba laŵa''ö khöra sama''ele''ö andrö: Lö mi''ila zi''öli, ba he lofo, ba lö göna ami; fangorifi si lö mamalö-malö ufa''aso khömi ba naha andre![3]', '["Faigi 5:31","Faigi 23:21; 27:15; 29:8","Ngenu 1:16; 2:18"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 14, 'Ba imane khögu Yehowa: Falimosa nifa''ele''ö zama''ele''ö andrö ba döigu; tenga nifatengegu ira, lö niŵa''ögu khöra, lö sihededo khöra; angilata falimosa ba faetasa faya-faya ba faya nifakhai dödöra lafa''ele''ö khömi![4]', '["Faigi 5:31","Faigi 23:21; 27:15; 29:8","Ngenu 1:16; 2:18"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 15, 'Andrö imane Yehowa — ba khö zama''ele''ö, sanguma''ö zui: He si''öli ba he lofo, ba lö itörö danö da''e! he ŵa''ae tenga sinengegu ira — si''öli ba lofo dania wamunu zama''ele''ö da''ö!', '["Faigi 5:31","Faigi 23:21; 27:15; 29:8","Ngenu 1:16; 2:18"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 16, 'Ba niha andrö, ba nifa''ele''ö da''ö, ba sadölö tou dania baewali Yeruzalema ba lofo ba ba zi''öli, lö sogo''o ya''ira ba fo''omora ba onora matua ba onora alawe — ba uhawui ira sulö walösökhira andrö.', '["Faigi 5:31","Faigi 23:21; 27:15; 29:8","Ngenu 1:16; 2:18"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 17, 'Ba ömane khöra: Mowöi-wöi daŵa hörögu, bongi ma''ökhö, lö i''ila döhö, me no mu''ö''ötö sibai nono alawe andrö, banuada; safökhö sibai zokhonia.[5]', '["Faigi 5:31","Faigi 23:21; 27:15; 29:8","Ngenu 1:16; 2:18"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 18, 'Na möido baero ba mbenua, ba hiza tou ni''ö''ötö si''öli, ba na möido miyomo ba mbanua, ba hiza zi mate olofo! He sa sama''ele''ö ba he ere, ba möi ba danö si lö larai mila.', '["Faigi 5:31","Faigi 23:21; 27:15; 29:8","Ngenu 1:16; 2:18"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 19, 'Ba hadia, no öfaulugö wanibo mado Yuda? ba noa sa''ae anuzu dödöu Ziona? Hana wa no öfesokho ndra''aga, si lö famadöhö? Ladöna-döna wangorifi, ba lö hadia ia zi sökhi; ladöna-döna mbaŵa wamadöhö, ba hiza wa''atobali dödö![6]', '["Faigi 8:15","Sin 106:6; Dan 9:8","Sin 135:7; Faigi 5:24"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 20, 'He Yehowa! No aboto ba dödöma walösökhima, horö ndra tuama andrö, wa no molalö ndra''aga khöu![7]', '["Faigi 8:15","Sin 106:6; Dan 9:8","Sin 135:7; Faigi 5:24"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 21, 'Böi tibo''ö [mbanuau], börö döimö andrö; böi be''e fa''aila dadaoma lakhömi andrö khöu; törö tödöu, böi wu''ai wawu''usa li andrö khöda!', '["Faigi 8:15","Sin 106:6; Dan 9:8","Sin 135:7; Faigi 5:24"]', NULL),
  (3476337, 'OT', 'Yeremia', 14, 22, 'Hadia, so maö ba nadu niha baero andrö wangöndru deu? hadia moteu manö mbanua si yaŵa [ha ya''ia]? Hadia, tenga ya''ugö, Yehowa, Lowalangima? ba madöna-döna khöu, ya''ugö sa''ae zolau da''ö fefu.[8]', '["Faigi 8:15","Sin 106:6; Dan 9:8","Sin 135:7; Faigi 5:24"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 1, 'Ba imane khögu Yehowa: He ŵa''ae so ba da''e ena''ö Moze ba Samueli, ba lö''ö zui aolo dödögu ba niha andre, — fofanö ira ba duduma hörögu, ena''ö laheta ira![1]', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 2, 'Ba no lamane khöu: Heza masaŵa? ba ömane khöra: Da''ö niŵa''ö Yehowa: Nihonogöi ba wökhö famunu — ba ba wökhö famunu, ba nihonogöi ba mbawa zi''öli — ba ba mbawa zi''öli, ba nihonogöi ba lofo — ba ba lofo, ba nihonogöi ba wangoloi''ö — ba ba wangoloi''ö![2]', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 3, 'Öfa balö u''oroi''ö udura — iŵa''ö Yehowa: si''öli, ba wamunu ba asu, ba wanösöbi, ba fofo ba dalu mbanua ba utu ndru''u, ba wemanga, ba wangohori.[3]', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 4, 'Ba ube''e nifakao ira, fefu soi niha ba guli danö zamakao ya''ira, börö Manase andrö, ono Hisikia, razo mado Yuda, börö nilaunia andrö ba Yeruzalema.[4]', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 5, 'Ha niha sa''ae zi hakhösi tödö ya''ugö, Yeruzalema? ha niha zogolö tödö khöu? ha niha zi möi yomo khöu manofu na lö hadia khömö?', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 6, 'No ötibo''ö ndra''odo, iŵa''ö Yehowa, no fabali''ö khögu: andrö wa u''oro''ö dangagu khöu, ba wamakiko ya''ugö; no atagedo wangahakhösi tödö.', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 7, 'Ba ufazaumba ira ba mbawa göli danö, si lö ono sa''ae ira ube''e, ufakiko mbanuagu andrö; lö niröira lalara andrö.', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 8, 'Tobali oya lakha mbanua khöra, moroi ba ngawua nene ba mbewe nasi. Ba nina nono matua khöra ufatörö zamakiko, ba zi laluo, i''ogomuzaö; ihawui ira fa''ata''u ba fa''atobali dödö ube''e.[5]', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 9, 'Ariri zi fitu ono, aetu noso: aekhu luo khönia lö bongi na, tobali lö boto ia, ihawui ia fa''aila; ba si tosai na khöra, ba ululu ba mbawa zi''öli nemalira, — iŵa''ö Yehowa.[6]', '["MozII 32:11; SamI 7:9; Hez 14:14","Sakh 11:9","Faigi 7:33","MozV 28:25; RazII 21:1–18","Sin 91:6","Amos 8:9"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 10, 'Alai ndra''o, inagu! wa no ö''adonogö ndra''odo, niha nifakao ba nifasosoni niha ba guli danö fefu! Lö nibe''egu nifalali ba lö mube''e khögu nifalaligu, ba dozi la''elifi ndra''odo![7]', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 11, 'Imane Yehowa: Si ndruhu, u''abe''e''ö ndra''ugö, ba zi sökhi! Si ndruhu, mangalulu khöu zi fa''udu ube''e, na baŵa wamakao, na baŵa wa''atosasa khönia.', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 12, 'Hadia, afatö zi''öli warasi, si''öli moroi yöu ba töla?', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 13, 'Ana''au ba girö-giröu, ba ube''e nirabu lö böli, börö sa''ae horöu andrö fefu, nifazökhiu ba danömi misa ma''asagörö.[8]', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 14, 'Ba ube''e sangai halöŵö zi fa''udu khöu ndra''ugö, ba danö si lö örai mila; humola sa''ae galitö, fönugu andrö; khömi te''ebua''ö ia.[9]', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 15, 'Ö''ila sa''ae, ya''ugö Yehowa! Törö tödöu ndra''odo, tolodo ba lau mbalögu ba zolohi ya''odo; böi bunudo, ba wa''ebolo dödöu andrö [khöra]: törö tödöu, wa no börö ndra''ugö, wa ulu''i wa''aila!', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 16, 'Falukhado daroma li khöu, ba no amaedola gögu, ba tobali fa''omuso dödögu daroma liu andrö, ba fa''owua-wua dödögu, no töimö mbörö wamotöi ya''odo, ya''ugö Yehowa, Lowalangi ngahönö.[10]', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 17, 'Lö sorududo fedao-dao ba zomuso tödö, fa ma''ikido ena''ö: ba dangau andrö, ba no tonia ndra''o wedadao, me no fahöna wa lö sökhi-sökhi dödögu öbe''e.[11]', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 18, 'Hana wa lö''ö sa''ae mamalö-malö wa''afökhö andrö khögu, ba hana wa monana-nana zokhogu andrö, fa tebai nifadöhö? Hadia, amaedola mbombo si falimo ndra''ugö khögu, idanö saetu-aetu?[12]', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 19, 'Andrö imane Yehowa: Na öfuli''ö, ba ufuli utehe khöu wangondrasi ya''odo, ba na ö''oniagö ira zi nangea zi lö sökhi, ba amaedola mbawagu zui ndra''ugö? Ya''ira zi otahagö ya''ugö, ba ya''ugö, ba lö ö''otahogö ira.', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 20, 'Ba ube''e ba''a-ba''a töla saro ndra''ugö föna niha andrö, ba na fasöndra ira khöu, ba tebai lalaŵa ndra''ugö, so sa''ae ndra''odo ba ngaiu, ba wanolo ya''ugö ba ba wangorifi ya''ugo — iŵa''ö Yehowa.[13]', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476338, 'OT', 'Yeremia', 15, 21, 'Ba u''efa''ö ndra''ugö ba danga zi lö sökhi ba ba gokhö zamakao.', '["Yob 3:1; Faigi 20:14","Faigi 17:3","MozV 32:22","Hez 3:3; Yoh 4:34; Fam 10:9","Sin 1:1","Yob 6:15","Faigi 1:18"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 1, 'Ba humede khögu Yehowa, imane:', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 2, 'Böi mangai ira alawe ndra''ugö ba böi mo''ono ndra''ugö ba mbanua andre, he ono matua ba he ono alawe.', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 3, 'Imane sa Yehowa ba nono matua andrö ba ba nono alawe, si tumbu ba mbanua andre, ba ba khö ninara andrö, sadono ya''ira ba ba khö namara, so''ono ya''ira, ba danö andre:', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 4, 'Fa''amate safökhö sibai dania wa''amatera, lö sange''esi ya''ira ba lö sogo''o: tobali oboula fangatabö zinanö ba danö ira; bawa zi''öli ba lofo wangohori ba tobali ö wofo ba dalu mbanua ba ö gutu ndru''u mbotora andrö.[1]', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 5, 'Imane sa Yehowa: Böi ae yomo ba nomo, ba zi so zi mate, böi möi''ö mange''esi, böi oroma''ö wa''ahakhö dödö; noa sa uheta wa''ohahau dödö andrö khögu ba niha andrö, — iŵa''ö Yehowa — ba fa''ebua dödögu ba fa''ahakhö dödö.', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 6, 'Mate zatua ba mate ndraono, ba danö andre, lö sogo''o ba lö sange''esi, lö sogoi ösinia, ba khöra andrö, ba lö samatöŵö''ö bunia.[2]', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 7, 'Ba lö samoboto roti, ba khöra andrö, ba wondrara tödö niha ba zi mate, ba lö lafabadugö nösi mako fondrara dödö ba wa''amate nama ba ba wa''amate nina.[3]', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 8, 'Ba böi göi ae yomo ba wemanga, ba wedadao ena''ö, awöra, ba wemanga ba ba wamadu hadia ia.[4]', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 9, 'Imane sa Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Hiza, u''etu''ö ba mbanua andre, ba zanehe ami ba ba götömi andre, li wa''iki ba li wa''omuso dödö, li zangowalu ba li nono nihalö.[5]', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 10, 'Ba na ö''ombakha''ö dania khöra niŵa''ögu andre fefu, ba na lamane khöu: Hana wa idaö''ö-daö''ö khöma Yehowa wamakao sabölö-bölö andrö ba hadia lalöma ba hadia horöma nifazökhima khö Lowalangima Yehowa?[6]', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 11, 'ba ömane khöra: Me no la''erogö ndra''o ira tuami ba me no la''o''ö Lowalangi bö''ö, wamosumange ya''ira, awö wangalulu khöra, ba ya''odo, ba no laröi ba lö ba dödöra goroisagu andrö.', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 12, 'Ba ya''ami, ba no midou''ö na wolau si lö sökhi, moroi khö ndra tuami, me no sabe''e tandro zamösana, wolo''ö nikhoi dödönia si lö sökhi andrö, ba wa lö mamondrongo khögu.[7]', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 13, 'Ba uheta sa''ae ami ba danö andre, ufazaumba ami ba danö andrö, si lö mirai mila, he ira tuami, ena''ö mifosumange Lowalangi bö''ö ba da''ö, bongi ma''ökhö, me lö edönado uhakhösi tödö ami![8]', '["Sin 79:2; Faigi 9:22; 14:16; 15:2; 25:33","MozIII 19:28; MozV 14:1","Hez 24:17","Fangomb. 7:3","Yes 24:8; Faigi 25:10","Faigi 5:19","Faigi 3:17; 7:26","MozV 4:27; 28:64"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 14, 'Ba hiza, irugi baŵa dania — iŵa''ö Yehowa —, ba lö''ö sa''ae laŵa''ö: "Ba wa''auri Yehowa, solohe miyaŵa Iraono Gizeraeli moroi ba danö Miserayi!"[9]', '["Faigi 23:7","Hez 47:10; Mat 4:19","Nga''ötII 16:9; Yob 34:21","MozII 3:14"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 15, 'Lamane dania a''ine: "Ba wa''auri Yehowa, solohe mangawuli Iraono Gizeraeli, moroi yöu ba moroi ba danö andrö fefu, ba nitibo''önia ya''ira!" Ba u''ohe mangawuli ira ba danöra andre, nibe''egu khö ndra tuara.', '["Faigi 23:7","Hez 47:10; Mat 4:19","Nga''ötII 16:9; Yob 34:21","MozII 3:14"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 16, 'Hiza, ato u''oroi''ö si fakiri — iŵa''ö Yehowa — ena''ö lafa''u''u, amaedola gi''a; ba aefa da''ö, ba ato zui u''oroi''ö sialu, ba wolohi ya''ira ba hili ba ba hili-hili fefu ba ba dögi gara.[10]', '["Faigi 23:7","Hez 47:10; Mat 4:19","Nga''ötII 16:9; Yob 34:21","MozII 3:14"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 17, 'Uhörö-hörögö sa döröŵara fefu, tebai tobini ira khögu ba tebai tobalu golalöŵara, ba wamaigigu.[11]', '["Faigi 23:7","Hez 47:10; Mat 4:19","Nga''ötII 16:9; Yob 34:21","MozII 3:14"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 18, 'Ba uhönagö ufodua winaeta wanulöni olalöŵara andrö, awö horöra, me salakha sa''ae danö khögu, labe''e, ba gamatela zogoro ita andrö khöra, ba me no anönö dana khögu andrö sawai latoda andrö khöra.', '["Faigi 23:7","Hez 47:10; Mat 4:19","Nga''ötII 16:9; Yob 34:21","MozII 3:14"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 19, 'He Yehowa, fa''abölögu ba hatigu ba saŵatögu na baŵa wamakao! Khöu dania möi soi niha moroi ba wondrege danö ba lamane: Ha sambalö faya dana khö ndra tuama mege, [adu] faya, si lö soguna.', '["Faigi 23:7","Hez 47:10; Mat 4:19","Nga''ötII 16:9; Yob 34:21","MozII 3:14"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 20, 'Hadia, i''ila niha ifazökhi khönia Lowalangi? — tenga sa Lowalangi zi manö!', '["Faigi 23:7","Hez 47:10; Mat 4:19","Nga''ötII 16:9; Yob 34:21","MozII 3:14"]', NULL),
  (3476339, 'OT', 'Yeremia', 16, 21, 'Ba hiza, u''oroma''ö khöra zi samuza andre, ufa''ila''ö khöra dangagu ba fa''abölögu, ba ya aboto ba dödöra wa no Yehowa döigu![12]', '["Faigi 23:7","Hez 47:10; Mat 4:19","Nga''ötII 16:9; Yob 34:21","MozII 3:14"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 1, 'Fanura si''öli wanura horö mado Yuda andrö, fanura so''ikhu indra''indra. Ba ba naha zura ba dödöra tesura ba ba dandru naha wame''e sumange andrö khöra.[1]', '["Yob 19:24","Faigi 15:13"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 2, 'Itörö tödöra naha wame''e sumange andrö ba Asera andrö khöra, hulö na itörö tödöra nonora, ba mbörö geu sobulu andrö ba ba hili andrö.', '["Yob 19:24","Faigi 15:13"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 3, 'He ya''ugö hili ba danö khögu! Nibaya-bayau ba girö-giröu fefu, ba ube''e nirabu, hili-hili andrö khöu, börö horö andrö, nifazökhi ba danö misa fefu.[2]', '["Yob 19:24","Faigi 15:13"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 4, 'Ba aefa ba dangau dana khöu andrö, nibe''egu khöu, ba ube''e sangai halöŵö zi fa''udu khöu ndra''ugö, ba danö si lö örai mila; humola sa''ae wönugu mibe''e, si lö mamalö-malö hola-holania.', '["Yob 19:24","Faigi 15:13"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 5, 'Imane Yehowa: Ni''elifi niha sanötöna fangorifi ba nawönia niha, same''e fa''abölönia ösi niha, si fabali tödö khö Yehowa![3]', '["Nga''ötII 32:8","Sin 107:34","Yes 30:18","Sin 1:3","SamI 16:7; Yob 34:11; Amaed 31","SamI 25:25; Luk 12:20"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 6, 'Amaedola zi lö balu-balu ia, ba danö si mate, lö falukha zi sökhi, ba danö si no oköliköli so ia, ba danö si mate, ba zo''asio, ba zi tebai monahia niha.[4]', '["Nga''ötII 32:8","Sin 107:34","Yes 30:18","Sin 1:3","SamI 16:7; Yob 34:11; Amaed 31","SamI 25:25; Luk 12:20"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 7, 'Ba ya''ahowu niha, sanötöna khö Yehowa, same''e fa''abe''e dödönia Yehowa![5]', '["Nga''ötII 32:8","Sin 107:34","Yes 30:18","Sin 1:3","SamI 16:7; Yob 34:11; Amaed 31","SamI 25:25; Luk 12:20"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 8, 'Eu nitanö ba mbewe nidanö ia, sangoro''ö ŵa''ania ba mbombo ba si lö ata''u na aukhu zino; lö aleu mbulunia ba lö abu dödö, na döfi si lö teu, ba lö mo''otalua wowua.[6]', '["Nga''ötII 32:8","Sin 107:34","Yes 30:18","Sin 1:3","SamI 16:7; Yob 34:11; Amaed 31","SamI 25:25; Luk 12:20"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 9, 'Si no tefuyu dödö niha, moroi ba danö bö''ö fefu, ba si lö sokhi — ha niha zangila amuata?', '["Nga''ötII 32:8","Sin 107:34","Yes 30:18","Sin 1:3","SamI 16:7; Yob 34:11; Amaed 31","SamI 25:25; Luk 12:20"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 10, 'Ya''o, Yehowa, zanekhegö tödö ba sanandraigö bua, ba wanulöni ba zamösana bua-buania, lua-lua nilau-launia andrö.[7]', '["Nga''ötII 32:8","Sin 107:34","Yes 30:18","Sin 1:3","SamI 16:7; Yob 34:11; Amaed 31","SamI 25:25; Luk 12:20"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 11, 'Amaedola mbörökoa samaukhu adulo si tenga ni''angadulogönia zanöndra ana''a ba zi lö atulö: na talu niha ia, ba aefa ba dangania, ba ba gamozuania, ba amaedola zowöhö mowa ia.[8]', '["Nga''ötII 32:8","Sin 107:34","Yes 30:18","Sin 1:3","SamI 16:7; Yob 34:11; Amaed 31","SamI 25:25; Luk 12:20"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 12, 'He ya''ugö dadaoma lakhömi, si no alaŵa i''otarai mböröta, naha ni''amoni''ö khöma!', '["Yes 1:28; Faigi 2:13","Sin 6:3","Yes 5:19; FetII 3:4","Faigi 1:6","Sin 35:4; 40:15"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 13, 'Ya''ugö tötönafö Ndraono Gizeraeli — Yehowa! dozi sangerogö ya''ugö, ba tobali si lö boto: si fabali khöu, ba nisura ba gawu-gawu tou, me no laröi gumbu nidanö aurifa, Yehowa andrö.[9]', '["Yes 1:28; Faigi 2:13","Sin 6:3","Yes 5:19; FetII 3:4","Faigi 1:6","Sin 35:4; 40:15"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 14, 'Orifido Yehowa, ena''ö te''orifi ndra''odo, tolodo, ena''ö usöndra wanolo, me no nisunogu ndra''ugö![10]', '["Yes 1:28; Faigi 2:13","Sin 6:3","Yes 5:19; FetII 3:4","Faigi 1:6","Sin 35:4; 40:15"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 15, 'Hiza lamane sa khögu: "Hezo daroma li Yehowa? Ena''ö itörö!"[11]', '["Yes 1:28; Faigi 2:13","Sin 6:3","Yes 5:19; FetII 3:4","Faigi 1:6","Sin 35:4; 40:15"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 16, 'Ba lö''ö zui nibödagu ya''odo, we''amöi kubalo, wolo''ö khöu, ba lö''ö sa ni''arögu baŵa wamakao andrö — ya''ugö zangila! Hadia zalua ba mbewegu, ba no anehe ndra''ugö.[12]', '["Yes 1:28; Faigi 2:13","Sin 6:3","Yes 5:19; FetII 3:4","Faigi 1:6","Sin 35:4; 40:15"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 17, 'Böi bali''ö ameta''uö ndra''ugö khögu; saŵatögu ndra''ugö, na baŵa wamakao!', '["Yes 1:28; Faigi 2:13","Sin 6:3","Yes 5:19; FetII 3:4","Faigi 1:6","Sin 35:4; 40:15"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 18, 'Be''e aila zolohi ya''odo, ena''ö tobali dödöra ba böi be''e tobali dödögu: fatörö khöra mbaŵa wamakao andrö ba fodua winaeta worasa ya''ira![13]', '["Yes 1:28; Faigi 2:13","Sin 6:3","Yes 5:19; FetII 3:4","Faigi 1:6","Sin 35:4; 40:15"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 19, 'Imane na khögu Yehowa: Ae''e, ba iagö mbawa göli mbanuami, nitörö-törö razo mado Yuda, ba bawa göli Yeruzalema fefu, ba ömane khöra:', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 20, 'Mifondrondrongo li Yehowa, ya''ami razo mado Yuda ba ya''ami mado Yuda fefu ba ya''ami banua Yeruzalema dozi, sanörö bawa göli andre!', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 21, 'Imane Yehowa: Mi''angelama — nosomi mbalazi! Böi monoro ami na luo sabato, noro ni''ohe miyomo ba Yeruzalema.[14]', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 22, 'Ba böi göi mi''ohe tou noro, moroi ba nomomi, na luo sabato, ba böi mihalö hadia ia halöŵö, ena''ö mi''amoni''ö luo sabato, si mane niŵa''ögu khö ndra tuami.[15]', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 23, 'Ba lö lafondrondrongo, lö labe''e mbörö dalingara, sabe''e tandro ira; lö la''o''ö ba lö labe''e ba dödöra wotu.[16]', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 24, 'Ba na mifondrondrongo khögu, ya''ami andrö, iŵa''ö Yehowa, fa böi mi''ohe miyomo ba mbanua andre noro, na luo sabato; na mi''amoni''ö luo sabato, fa böi mihalö hadia ia halöŵö, na luo da''ö,', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 25, 'ba latörö mbawa göli mbanua andre razo ba satua, sidadao ba dadaoma Dawido andrö, fakureta ira ba fakudo, awö zatua andrö khöra, ira matua mado Yuda, awö mbanua Yeruzalema andrö, ba lö tebulö niha ba mbanua andre.[17]', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 26, 'Ba so dania zi otarai mbanua mado Yuda andrö ba si fasui Yeruzalema, tanö mado Mbeniyami ba moroi ba ndraso ba moroi ba hili ba moroi raya, solohe sumange nitunu ba sumange nitaba ba sumange ni''a ba kumöyö, ba solohe ba gosali Yehowa sumange fangandrö saoha gölö.', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476340, 'OT', 'Yeremia', 17, 27, 'Ba na lö mifondrondrongo khögu, ba we''amoni''ö luo sabato, ba wa lö molohe noro, nifatörö miyomo ba Yeruzalema, ba ugule''ö galitö ba mbawa göli Yeruzalema, ena''ö i''a gödo ba Yeruzalema ba ena''ö lö mate.', '["Neh 13:19","MozII 20:8–11","Faigi 11:8","Faigi 22:4"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 1, 'Fehede Yehowa khö Yeremia; imane:', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 2, 'Faoso, ae mitou ba nomo zamöbözi bowoa, ba da''ö dania so niŵa''ögu khöu.', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 3, 'Ba möido mitou ba nomo duka mbowoa, ba mohalö-halöŵö ia fönagu ba dandrösa.', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 4, 'Ba lö sökhi mbowoa andrö, niböbözinia, la''uri andrö ba danga zamöbözi. Ba ifuli ibali''ö bowoa si bohou, dali zi so ba dödö zamöbözi, wamazökhi ya''ia.', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 5, 'Ba humede khögu Yehowa,', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 6, 'imane: Hadia, lö u''ila ulau khömi nilau zamöbözi bowoa andrö, ya''ami mauwu Gizeraeli? — iŵa''ö Yehowa. Hiza, amaedola la''uri ba danga duka mbowoa ami ba dangagu, ya''ami ma''uwu Gizeraeli.[1]', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 7, 'So, ba ufeta''u soi niha, öri heza, uhori, ududugö ba ufakiko.[2]', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476341, 'OT', 'Yeremia', 18, 8, 'Ba na laröi zi lö sökhi niha andrö, nifeta''ugu, ba mangesa dödögu, ba wamakao andrö, niŵa''ögu, nifatörö khöra.[3]', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 9, 'Ba so, ba ufabu''u ba soi niha, ba ma ba nöri heza, u''azökhi ba utanö;', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 10, 'ba na latörö zi lö omasido, na lö la''o''ö goroisagu, ba mangesa göi dödögu, ba zi sökhi andrö, niŵa''ögu, nifatörö khöra.', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 11, 'Ba iya''e, ba ömane ba mado Yuda ba ba mbanua Yeruzalema andrö: Da''ö niŵa''ö Yehowa: Hiza, uwöwöi wamakao ya''ami, ikhoi tödögu nilau khömi! Mifuli ami, yamuröi lala si lö sökhi andrö khönia zamösana; mi''alui wanörö lala si sökhi ba bua-bua si sökhi![4]', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 12, 'Ba lamane dania: Zaya-zaya gölö! Era-erama sa''ae mafalua ba i''abe''e''ö dandronia zamösana, wolo''ö nikhoi dödönia si lö sökhi andrö.[5]', '["Yes 45:9; 64:8; Rom 9:21","Faigi 1:10","Hez 33:11","RazII 17:13; Yes 1:16; Faigi 7:3","Faigi 2:25"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 13, 'Andrö wa no imane Yehowa: Mitandraigö misofu ba niha baero, na so zirai mamondrongo si mane da''ö. Si hokha mbuda sa''ae nilau nono alawe andrö, Iraono Gizeraeli![6]', '["Faigi 2:10","Faigi 3:21; 6:16"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 14, 'Hadia, aheta maö ba dete gara ba hili deu si baku andrö, ba hili Libano? hadia, aetu mbombo si so umbu, sigoso-goso, sahele miyöu?', '["Faigi 2:10","Faigi 3:21; 6:16"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 15, 'Ba banuagu andrö, ba no olifu ira ndra''odo; ba waya latunu gumöyö, ba no alau ira ibe''e, ba lalara andrö, töröŵa ba götö föna andrö, ba wanörö lala si lö muhaogö.[7]', '["Faigi 2:10","Faigi 3:21; 6:16"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 16, 'Tobali labali''ö sihokha mbuda danöra, labali''ö ni''o''aya, si lö mamalö-malö; sanörö, ba humokha mbu ba ifalikhö ia.', '["Faigi 2:10","Faigi 3:21; 6:16"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 17, 'Amaedola nifazawili nangi moroi ba gatumbukha ufazaewe ira föna nemalira andrö: u''erogö ira, lö u''otahögö, na baŵa tekiko ira.', '["Faigi 2:10","Faigi 3:21; 6:16"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 18, 'Ba lamane: Talabu, te''alui wamagönaisi Yeremia andrö; lö''ö sa si taya huku, ba gere ba he famobawa lala, ba zatua-tua ba he huhuo, ba zama''ele''ö andrö. Talabu, tabunu ia lelada ba böi tafondrondrongo niŵa''önia, zambalö![8]', '["Mal 2:7","Sin 109:9"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 19, 'Faigi-faigido, ya''ugö Yehowa, ba fondrongondrongo huhuo zi fa''udu khögu andrö!', '["Mal 2:7","Sin 109:9"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 20, 'Hadia, sulö zi sökhi zi lö sökhi, wa no lakharu lösu-lösu khögu? Törö tödöu, wangondrasigu ya''ugö, ba wangandrö, salahira, ba wangalösi fönumö khöra!', '["Mal 2:7","Sin 109:9"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 21, 'Ba lulu sa''ae nonora ba wa''olofo, ba tou''ö ira ba mbawa zi''öli, ena''ö si lö ono ndra alawe khöra ba si lö ira matua sa''ae, ena''ö mate ba deu mbanua ndra matua khöra, ba ono matua, ba ena''ö ni''ö''ötö si''öli ba wasöndrata![9]', '["Mal 2:7","Sin 109:9"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 22, 'Ena''ö terongo we''ira-ira yomo khöra, na i''ogomuzaö öfatörö khöra nemali: noa sa lakharu lösu-lösu, ba wama''ala ya''odo ba no lalau wesu gahegu.', '["Mal 2:7","Sin 109:9"]', NULL),
  (3476341, 'OT', 'Yeremia', 18, 23, 'Ba ya''ugö Yehowa, ba no ahori ö''ila nifakhaira khögu, ba wamunu ya''odo: böi zi lö tesulöni lalöra andrö ba böi tebunu horöra fönau; ya tegaölö tou ira fönau; na baŵa tesao wönumö lau khöra!', '["Mal 2:7","Sin 109:9"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 1, 'Imane Yehowa: Ae öli khöu migö niböbözi duka mbowoa, ba ohe awöu zatua mbanua ösa ba satua gere.', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 2, 'Ba ae mitou ba ndraso Mbeni-Hinomo, ba gamaudu mbawa göli duga lawu, ba ombakha''ö ba da''ö niŵa''ögu khöu dania;', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 3, 'ömane: Mifondrondrongo li Yehowa, ya''ami razo mado Yuda ba ya''ami banua Yeruzalema! Imane Yehwoa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Hiza, ufatörö wamakao ba mbanua da''e, safökhö ba dögi dalinga zamondrongo![1]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 4, 'Börö wa no la''erogö ndra''o, awö wa no la''osilö''ögö naha andre, wa no labe''e naha wanunu kumoyö ba Lowalangi bö''ö, si lö aboto ba dödöra — ya''ira ba ira tuara ba razo mado Yuda — awö wa no lahöna ndro zi lö horö ba naha andre.[2]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 5, 'Ba no lafa''anö naha wame''e sumange khö Mba''ali, ba hili, ba wanunu onora sumange nitunu khö Mba''ali andrö, si tenga niŵa''ögu ba si tenga nifakhoigu, ba si lö irai itörö tödögu.[3]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 6, 'Ba hiza, ba irugi baŵa dania, iŵa''ö Yehowa, ba tenga sa''ae Tofeti ba daso Mbeni-Hinomo döi naha da''e; daso wange''enge''e döinia.[4]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 7, 'Ba ufaduwa tou sa''ae wa''onekhe mado Yuda ba fa''onekhe mbanua Yeruzalema ba naha andre ba mate ira ba mbawa zi''öli nemalira ube''e, ba ba danga zangalui famunu ya''ira; ba ube''e ö wofo ba dalu mbanua ba ö gutu ndru''u mbotora.[5]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 8, 'Ba ube''e fehokha mbu ba fango''aya mbanua andre: ha niha zanöro ba ya humokha mbu ba yamu''igi''igi''ö ira ba wotu andrö fefu, si no göna ira.[6]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 9, 'Ba ube''e öra nösi nonora matua ba ösi nonora alawe, ya faoma la''a nösi nawöra, ba wamakao andrö ba ba wa''atosasa, nifobörö nemalira andrö khöra, awö zangalui famunu ya''ira.[7]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 10, 'Ba örasa migö andrö, ba zanehe niha andrö si möi awöu.', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 11, 'Ba ömane khöra: Da''ö niŵa''ö Yehowa ngahönö andrö: Si manö dania worasagu niha andre ba banua andre, si mane na tarasa mbowoa niböbözi, si tebai tefa''anö zui, ba ba Dofeti lako''o ira, me lö naha lewatö.[8]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 12, 'Da''ö nifatörögu ba mbanua andre — iŵa''ö Yehowa —, ba ba nösinia, ba wamali''ö Tofeti banua andre.[9]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 13, 'Ba tobali salakha nomo ba Yeruzalema ba omo razo mado Yuda, si mane naha Dofeti andrö — fefu nomo ba nitunu kumöyö ba dete yaŵa, ba ngahönö andrö ba mbanua si yaŵa, fefu, ba ba nibe''e sumange nibadu ba Lowalangi bö''ö.[10]', '["SamI 3:11; RazII 21:12","Yes 65:11; Faigi 2:13","MozIII 18:21","Faigi 7:32","Faigi 15:3","Faigi 18:16","MozIII 26:29; MozV 28:53; RazII 6:28; Ngenu 4:10","Yes 30:14","Yes 30:32","RazII 23:12; Faigi 7:18"]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 14, 'Ba me mangawuli Yeremia moroi ba Dofeti, ba nifatenge Yehowa ya''ia, ba wama''ele''ö, ba i''iagö golayama gosali Yehowa ba imane ba zato fefu:', '[]', NULL),
  (3476342, 'OT', 'Yeremia', 19, 15, 'Da''ö niŵa''ö Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Hiza, ufatörö ba mbanua andre ba ba mbanua si faböbö khöra fefu wamakao andrö, nidaö''ö-daö''ögu khöra, me no sabe''e tandro ira ba me lö nifondrondrongora ligu.', '[]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 1, 'Ba me irongo Fasuri, ono Gimeri, satua zanaro ba gosali Yehowa, ifa''ema daroma li andrö Yeremia,', '["Faigi 29:26","RazII 25","Eser 2:38"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 2, 'ba itema ibözi Yeremia Fasuri ba ibe''e ba galo, ba mbawandruhö mado Mbeniyami tanö yaŵa, ba gosali Yehowa.[1]', '["Faigi 29:26","RazII 25","Eser 2:38"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 3, 'Ba mahemolu ö, ba zanguhulö wongi, me no i''efa''ö Yeremia ba galo Fasuri, ba imane khönia Yeremia: Tenga sa''ae Fasuri ibe''e töimö Yehowa, Magori-Misabibi (Ameta''uö fasui) ibe''e töimö.', '["Faigi 29:26","RazII 25","Eser 2:38"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 4, 'Imane sa Yehowa: Hiza, ubali''ö ameta''uö ndra''ugö, khöu ba ba nawöu fefu; mate dania ira ba mbawa zi''öli nemalira, ba zanehe ndra''ugö, ba mado Yuda ma''afefu, ba ube''e ba danga razo Mbabeli, ena''ö i''oloi''ö ba Mbabeli ba ena''ö ibunu si''öli.', '["Faigi 29:26","RazII 25","Eser 2:38"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 5, 'Ba fefu nihöna ba mbanua andre, awö nibaya-bayara fefu, awö gana''ara fefu, ba ululu; fabaya girö-girö razo mado Yuda, ba ube''e ba danga nemalira, akha larabu ba akha la''oloi''ö ba Mbabeli.[2]', '["Faigi 29:26","RazII 25","Eser 2:38"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 6, 'Ba ya''ugö fasuri ba si so yomo khöu fefu, ba ni''oloi''ö ami ba ba Mbabeli örugi, ba da''ö lako''o ndra''ugö, — ya''ugö ba awöu andrö fefu, ba ni''ombakha''öu faya.[3]', '["Faigi 29:26","RazII 25","Eser 2:38"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 7, 'No öfowöhö ndra''o, ya''ugö Yehowa, ba no ube''e nifowöhö ndra''odo; no öra''udo ba no ölaŵa ndra''o. No tobali fama''iki niha ndra''odo, si lö mamalö-malö, dozi la''o''aya ndra''o.[4]', '["Faigi 1:4–8","KorI 9:16,17","Faigi 17:18; 23:40","SamI 16:7"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 8, 'Ero muhededo, ba mangarongarödo ba mu''aodo: "Famakao ba famalangögö!" Noa sa tobali börö wama''iki khögu daroma li Yehowa ba börö wango''aya ya''odo, ma''öma''ökhö.', '["Faigi 1:4–8","KorI 9:16,17","Faigi 17:18; 23:40","SamI 16:7"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 9, 'Ba umane: Akha lö''ö sa''ae ufa''ema niŵa''önia, ba tobali hulö galitö sihola-hola ba dödögu bakha, si no te''u''u ba nösigu; u''eregesi dödögu wanaögö ya''ia, ba tebai.[5]', '["Faigi 1:4–8","KorI 9:16,17","Faigi 17:18; 23:40","SamI 16:7"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 10, 'No ato nirongogu fehede zafökhö tödö — ameta''uö fasui —, lamane: "Ni''ombakha''ö ia!" ba "Data''ombakha''ö ia!" Dozi sa ba zi fahuwu ndra''o, ba ladaro-darogö ndra''odo, ma atö molalö ndra''o, lamane: "Ma ibe''e nifowöhö ia, ena''ö talaŵa ia ba talau mbalöda khönia."', '["Faigi 1:4–8","KorI 9:16,17","Faigi 17:18; 23:40","SamI 16:7"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 11, 'Ba i''oawögö ndra''o Yehowa, amaedola zabölö sibai, ba salau dania zolohi ya''odo ba si tebai, tobali fondrege zi lö boto, me no tenga folau zatua-tua wolaura — tobali fa''aila si lö aetu, si lö taya ba dödö niha.[6]', '["Faigi 1:4–8","KorI 9:16,17","Faigi 17:18; 23:40","SamI 16:7"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 12, 'Ba ya''ugö Yehowa ngahönö, sanandraigö satulö tödö, sangila bua ba tödö: oroma''ö khögu wolau balöu khöra; noa sa ube''e noro dödöu huhuogu andrö.[7]', '["Faigi 1:4–8","KorI 9:16,17","Faigi 17:18; 23:40","SamI 16:7"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 13, 'Mi''anunö khö Yehowa, misuno Yehowa, me no sangefa''ö noso zi numana ba danga zolau si lö sökhi!', '["Faigi 1:4–8","KorI 9:16,17","Faigi 17:18; 23:40","SamI 16:7"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 14, 'Ni''elifi mbaŵa si tumbu ndra''o; baŵa andrö ba ni''adonogö ninagu ya''odo, ba böi tefahowu''ö![8]', '["Yob 3","MozI 19:24"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 15, 'Ni''elifi niha andrö sangombakha khö namagu turia somuso dödö andrö, wanguma''ö: No tumbu khöu nono matua! same''e omuso sibai dödönia!', '["Yob 3","MozI 19:24"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 16, 'Ya tefatörö ba niha andrö nifatörö ba mbanua andrö, nifaulugö Yehowa fanudugö, lö fa''ahakhö dödö, ba yamurongo wege-ege na mahemolu mbanua ba fe''ao-ao ba wanuwö na laluo![9]', '["Yob 3","MozI 19:24"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 17, 'Me lö nibununia ya''odo ba dalu ninagu, ena''ö tobali lewatögu ninagu ba ena''ö lö''ö manö tebulö dabinania!', '["Yob 3","MozI 19:24"]', NULL),
  (3476343, 'OT', 'Yeremia', 20, 18, 'Hana sa wa böla ndra''o moroi ba dalu ninagu, ba wangila famakao ba fa''abu dödö ba ba wa lö mamalö-malö wa''aila, sagötö ya''odo!', '["Yob 3","MozI 19:24"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 1, 'Niŵa''ö Yehowa khö Yeremia, me ifatenge khönia razo Sedekia Wasuri andrö, ono Malikia ba Sefania, ere andrö, ono Ma''aseya, wanguma''ö:', '["Sanguhuk 1:1; SamII 5:19; Faigi 37:3","Faigi 39:1"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 2, 'Tema sofu khö Yehowa khöma — isuwö sa''ae ndra''aga Nebukanesa, razo Mbabeli — ma itolo ita Yehowa, dali zahöli-höli dödö andrö fefu, nilaunia, ena''ö ifuli iheta ia khöda [Nebukanesa].[1]', '["Sanguhuk 1:1; SamII 5:19; Faigi 37:3","Faigi 39:1"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 3, 'Ba imane Yeremia khöra:', '["Sanguhuk 1:1; SamII 5:19; Faigi 37:3","Faigi 39:1"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 4, 'Mimane khö Zedekia: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Hiza, ubali''ö wangöna andrö ba dangami, nifakemi ba wasöndrata khö razo Mbabeli ba ba Ndrawa Galedaia andrö, sanasagö ya''ami, baero göli, ba u''owuloi bakha ba mbanua.', '["Sanguhuk 1:1; SamII 5:19; Faigi 37:3","Faigi 39:1"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 5, 'Ba ya''odo zanuwö ya''ami tanga ni''oro''ö ba ta''io sabölö ba wönu ba ba wa''abao dödö ba ba mbakhu-bakhu dödö andrö.', '["Sanguhuk 1:1; SamII 5:19; Faigi 37:3","Faigi 39:1"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 6, 'Ba ubözi tou nösi mbanua andre, he niha ba he urifö; fökhö waba sabölö-bölö wamunura.', '["Sanguhuk 1:1; SamII 5:19; Faigi 37:3","Faigi 39:1"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 7, 'Ba aefa da''ö — iŵa''ö Yehowa — ba ube''e ba danga Nebukanesa, razo Mbabeli ba ba danga nemalira, ba danga zangalui famunu ya''ira Zedekia andrö, razo mado Yuda, awö genoninia, awö zato, si tosai ba mbanua andre ba wökhö waba ba ba zi''öli ba ba lofo, ena''ö ibunu bawa zi''öli, lö fa''ahakhö dödö, lö alimagö ba lö fa''ogolö dödö.[2]', '["Sanguhuk 1:1; SamII 5:19; Faigi 37:3","Faigi 39:1"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 8, 'Ba ba niha andre, ba ömane: Da''ö niŵa''ö Yehowa: Hiza, ufaedo ia khömi lala ba wa''auri lala ba wa''amate![3]', '["MozV 11:26","Faigi 38:2","Faigi 22:3"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 9, 'Ha niha zi lö tebulö ba mbanua da''e, ba si mate, ma ba mbawa zi''öli, ba ma ba lofo, ba ma ba wökhö waba; ba si möi baero, same''e ya''ia ba danga Ndrawa Galedaia, ba sauri, harenia nosonia.[4]', '["MozV 11:26","Faigi 38:2","Faigi 22:3"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 10, 'Noa sa u''otahogö mbanua da''e, ba wamakiko ba tenga ba wangorifi — iŵa''ö Yehowa —; nibe''e ba danga razo Mbabeli ia, ena''ö itunu.', '["MozV 11:26","Faigi 38:2","Faigi 22:3"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 11, 'Ba ba zi samba omo razo mado Yuda, ba ömane: Mifondrondrongo li Yehowa,', '["MozV 11:26","Faigi 38:2","Faigi 22:3"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 12, 'ya''ami ma''uwu Dawido! Da''ö niŵa''ö Yehowa: Milau rafe, ero mahemolu mbanua, mi''efa''ö ni''anagöi ba danga zamakao ya''ia, fa böi muhola wönugu, si mane alitö, si lö famunu — ba walösökhi wolaumi andrö![5]', '["MozV 11:26","Faigi 38:2","Faigi 22:3"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 13, 'Hiza, ulau khöu, ya''ugö si so ba ndraso, ba gara ba zalo''o — iŵa''ö Yehowa —, khömi, sanguma''ö: Ha niha zi möi mitou khöma, ha niha zi möi yomo khöma?', '["MozV 11:26","Faigi 38:2","Faigi 22:3"]', NULL),
  (3476344, 'OT', 'Yeremia', 21, 14, 'Ba usulöni khömi lua-lua wolaumi andrö — iŵa''ö Yehowa — ba utunu gatua andrö khöra, ena''ö i''a [alitö andrö] fefu hadia ia zi tefasui ya''ira.', '["MozV 11:26","Faigi 38:2","Faigi 22:3"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 1, 'Imane Yehowa: Ae mitou ba gödo razo mado Yuda, ba öfa''ema khönia daroma li andre, ömane:', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 2, 'Fondrondrongo li Yehowa, ya''ugö razo mado Yuda, sidadao ba dadaoma Dawido andrö, ya''ugö ba enoniu ba banuau, sanörö bawa göli andre!', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 3, 'Da''ö niŵa''ö Yehowa: Lala mitörö ba satulö huku; mi''efa''ö ni''anagöi ba danga zamakao ya''ia! Ba böi mifakao niha bö''ö ba he lakha mbanua ba he si lö ama si lö ina, böi mifalangögö ba böi mibe''e aduwa ndro zi lö horö ba naha andre.[1]', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 4, 'Na mi''o''ö sibai da''ö, ba latörö mbawandruhö gödo andre razo, sidadao ba dadaoma Dawido, ma''uwunia, — fakureta ba fakudo, — ya''ia ba enoninia ba banuania.[2]', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 5, 'Ba na lö mifondrondrongo niŵa''ögu andre, ba fahölu ndra''o ba khögu — iŵa''ö Yehowa — wa adudula dania gödo andre.', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 6, 'Imane sa Yehowa ba gödo razo mado Yuda andre: Amaedola Gileadi ndra''ugö khögu, amaedola zuzu hili Libano! Si ndruhu, ubali''o tanö si mate ndra''ugö, banua si lö niha sa''ae.[3]', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 7, 'Ba ufahowu''ö zamakiko ya''ugö, udozigö, fabaya fangönara, ena''ö la''obö geresi nitutuyu andrö khöu ba ena''ö latibo''ö ba galitö.', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 8, 'Ba oya soi zanörö singa mbanua da''e, ba faoma lamane khö nawöra: Hana wa no ilau da''ö ba mbanua da''e Yehowa?[4]', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 9, 'Ba lamane dania: Me no laböhöli wawu''usa li andrö khö Lowalangira Yehowa ba me no mangalulu ira ba Lowalangi bö''ö, wamosumange da''ö.', '["Faigi 7:6; 21:12","Faigi 17:25","Faigi 21:14","MozV 29:24; RazI 9:8; Nga''ötII 7:21"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 10, 'Böi me''e ami ba zi mate andrö, böi mi''e''esi, da''ö mi''e''esi, zi no mofanö andrö, me lö falukha mangawuli lö falukha ifuli i''ila mbanuania![5]', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 11, 'Imane sa Yehowa ba khö Zalumi andrö, ono Yosia razo mado Yuda, si no tobali razo, fangali namania Yosia ba si no aheta ba naha andre: Lö''ö sa''ae mangawuli ia ba da''e;[6]', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 12, 'ba mbanua andrö, ba ni''oloi''ö ya''ia, mate ia, ba lö''ö sa''ae i''ila danö da''e.', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 13, 'Alai zame''e folau omonia si lö atulö ba same''e famazökhi bate''enia sabila, samohalöŵö awönia lö böli gölö ba si lö mame''e luonia,[7]', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 14, 'sanguma''ö: Da''ulau khögu nomo sebua ba bate''e sebolo! sangebolo''ö sandrela khönia, samagolöi eresi ba solau se soyo!', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 15, 'Hadia, razo ndra''ugö, na öforege wolau eresi? Amau andrö, ba manga-manga göi ba mamadu hadia ia, ba itörö lala, satulö ilau: ba sohahau tödö ia.', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 16, 'I''ohe ba lala huhuo nifakao ba huhuo zi numana: ba sohahau tödö ia. Hadia, tenga da''ö wa''aboto ba dödö ndra''odo? iŵa''ö Yehowa.', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 17, 'Ba ba höröu ba ba dödöu, ba awai ni''ila, ha sambalö hareu ba fanuwagö do zi lö horö, ba famalangögö ba famakao, ba wolau ya''ia.', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 18, 'Andrö imane Yehowa, ba khö Yoyaki andrö, ono Yosia, razo mado Yuda: Lö dania la''e''esi ia, wanguma''ö: "Alai ndra''o, ya''ugö ga''agu ira matua!" "Alai ndra''o, ya''ugö ga''agu ira alawe!" — lö la''e''esi ia, wanguma''ö: "Alai ndra''o, ya''ugö salaŵa!" ba "Alai ndra''o, ya''ugö helanö!"[8]', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 19, 'Fogo''o kalide wogo''o ya''ia, lafondröni hakhi, wanibo ya''ia, aröu baero mbawa göli Yeruzalema.[9]', '["RazII 23:33; Nga''ötII 35:25","Nga''öt. 3:15","MozV 24:14; Hab 2:9; Yak 5:4","RazII 24:1,2; Nga''ötII 36:5–8","Faigi 36:30"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 20, 'Ae yaŵa ba hili Libano ba ao khöra! Farongogö limö ba Mbazana ba ao moroi ba hili Gabari; noa sa arasa fefu zomasi ya''ugö.', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 21, 'No humededo khöu, me sahono-hono na ndra''ugö, me lö''ö na hadia ia khöu, ba ömane: Lö edönado mamondrongo! Da''ö gamuatau, i''otarai iraono ndra''ugö, wa lö ö''o''ö niŵa''ögu.', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 22, 'Fefu gubalo andrö khöu, ba angi zangoloi''ö dania ba dozi somasi ya''ugö, ba ni''oloi''ö sawuyu: ba tobali ni''igi''igi''ö ndra''ugö ba ihawui ndra''ugö fa''aila, börö walösökhimö andrö fefu!', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 23, 'Ya''ugö sonahia ba hili Libano, sangazuni ba hogu geresi — sangarö-ngarö ndra''ugö dania, na afökhö hulumö, na manizi-nizi ndra''ugö, timba zadono![10]', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 24, 'Faya wa no sauri ndra''o — iŵa''ö Yehowa —, he hulö laeduru ba dangagu kambölö mena''ö Yoyakhi andrö, ono Yoyaki, razo mado Yuda — na lö uheta ndra''ugö ba da''ö,[11]', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 25, 'ba na lö ube''e''ö ba danga zangalui famunu ya''ugö ba ba danga zihokha mbumö, ba ba danga Nebukanesa razo Mbabeli ba ba danga Ndrawa Galedaia.', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 26, 'Ba ufazaumba ndra''ugö ba danö bö''ö, fabaya inau sadono ya''ugö, tenga tanö si tumbu ami, ba ba da''ö mate ami.[12]', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 27, 'Ba lö tola mangawuli ira ba danö andrö, somasi ira mangawuli.', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 28, 'Hadia, amaedola mbowoa si lö ba dödö, bowoa nirasa, Yoyakhi andrö, amaedola wakake si lö omasi ita? Hana sa, wa tefazaumba ia, awö nononia, hana wa tetibo ira ba danö si lö larai mila?[13]', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 29, 'He ya''ami ba danö, he ya''ami ba danö, he ya''ami ba danö! Mifondrondrongo li Yehowa!', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476345, 'OT', 'Yeremia', 22, 30, 'Imane Yehowa: Mitanö ba zura döi niha da''ö, mibe''e niha si lö nga''ötö, niha si lö fozu ba götönia; lö''ö sa fakhai ba ma''uwunia ha niha, wedadao ba dadaoma Dawido andrö, razo mado Yuda na.', '["Faigi 21:14","RazII 24:6 b.t.; Faigi 24:1","RazII 24:12","Hos 8:8"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 1, 'Alai gubalo andrö, samakiko biri-biri nikubaloi andrö khögu, ba samazaewe! Iŵa''ö Yehowa.[1]', '["Faigi 10:21; Hez 34:2","Yes. 40:11; Faigi 3:15; Hez 34:11","Yes 4:2; Dan 9:24; Luk 1:33","MozV 33:28; Faigi 33:16","Faigi 16:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 2, 'Andrö wa imane Yehowa, Lowalangi Ndraono Gizeraeli, ba khö gubalo andrö sokubaloi banuagu: No mifazawili mbiri-biri andrö khögu, no muhafa mibe''e, lö nifaigi-faigimi — hiza, u''otu''ö ami ba zi lö sökhi andrö, nilaumi! iŵa''ö Yehowa.', '["Faigi 10:21; Hez 34:2","Yes. 40:11; Faigi 3:15; Hez 34:11","Yes 4:2; Dan 9:24; Luk 1:33","MozV 33:28; Faigi 33:16","Faigi 16:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 3, 'Ba ya''odo zangozaragö si tosai biri-birigu, ba danö andrö fefu, ba nifazaewegu ya''ira ba u''ohe mangawuli ba zi so du''u, öra, ba mo''ono''ono ira ba tobali oya.', '["Faigi 10:21; Hez 34:2","Yes. 40:11; Faigi 3:15; Hez 34:11","Yes 4:2; Dan 9:24; Luk 1:33","MozV 33:28; Faigi 33:16","Faigi 16:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 4, 'Ba ufataro khöra gubalo, sokubaloi ya''ira, ba alakha lö ata''u sa''ae ba akha lö tokea, ba sageu lö sisuna! iŵa''ö Yehowa.[2]', '["Faigi 10:21; Hez 34:2","Yes. 40:11; Faigi 3:15; Hez 34:11","Yes 4:2; Dan 9:24; Luk 1:33","MozV 33:28; Faigi 33:16","Faigi 16:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 5, 'Hiza, irugi baŵa dania — iŵa''ö Yehowa — ba ufatumbu''ö madou satulö khö Dawido, si möi razo ba si no atua-tua wolau hadia ia ba samatörö lala, awö huku satulö, ba danö.[3]', '["Faigi 10:21; Hez 34:2","Yes. 40:11; Faigi 3:15; Hez 34:11","Yes 4:2; Dan 9:24; Luk 1:33","MozV 33:28; Faigi 33:16","Faigi 16:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 6, 'Na luo da''ö, ba te''orifi mado Yuda ba lö hadia ia ba Ndraono Gizeraeli ba mbanuara, ba da''ö nibe''e töinia: "Yehowa fa''atulöda."[4]', '["Faigi 10:21; Hez 34:2","Yes. 40:11; Faigi 3:15; Hez 34:11","Yes 4:2; Dan 9:24; Luk 1:33","MozV 33:28; Faigi 33:16","Faigi 16:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 7, 'Andrö hiza, irugi baŵa dania — iŵa''ö Yehowa — ba lö''ö sa''ae laŵa''ö; "Ba wa''auri Yehowa, solohe miyaŵa Iraono Gizeraeli moroi ba danö Miserayi![5]', '["Faigi 10:21; Hez 34:2","Yes. 40:11; Faigi 3:15; Hez 34:11","Yes 4:2; Dan 9:24; Luk 1:33","MozV 33:28; Faigi 33:16","Faigi 16:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476346, 'OT', 'Yeremia', 23, 8, 'Lamane dania: "Ba wa''auri Yehowa, solohe mangawuli ma''uwu Gizeraeli moroi yöu ba moroi ba danö andrö fefu, ba nitibo''ögu ya''ira, ena''ö lafuli la''iagö danöra."', '["Faigi 10:21; Hez 34:2","Yes. 40:11; Faigi 3:15; Hez 34:11","Yes 4:2; Dan 9:24; Luk 1:33","MozV 33:28; Faigi 33:16","Faigi 16:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 9, 'Ba zama''ele''ö andrö: No arasa dödögu barö dotogu, humifahifa gahegu ba ta''iogu fefu; hulö zi mabu ndra''o, hulö niha nilaŵa nagu, — föna Yehowa ba ba daroma linia andrö, ni''amoni''ö.', '["Faigi 9:2","Hez 23:39","MozV 32:32; Yes 1:9","Yes 8:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 10, 'Noa sa anönö danö sohorö; ba wangelifi andrö sa''ae abu dödö danö, ba oköli ndru''u ba mbenua; fagohisara, ba no si lö sökhi, ba fa''abölöra, ba no si lö atulö.[6]', '["Faigi 9:2","Hez 23:39","MozV 32:32; Yes 1:9","Yes 8:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 11, 'He sama''ele''ö, ba he ere, ba no sanao horö, numalo ba gosali andrö khögu, ba falukhado walösökhi andrö khöra! — iŵa''ö Yehowa.[7]', '["Faigi 9:2","Hez 23:39","MozV 32:32; Yes 1:9","Yes 8:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 12, 'Andrö tobali hulö zaelo ba zogömi-gömi khöra lalara; tetimba ira ba alau ba lala andrö; famakiko sa''ae ufatörö khöra, döfi wangotu''ö, — iŵa''ö Yehowa.', '["Faigi 9:2","Hez 23:39","MozV 32:32; Yes 1:9","Yes 8:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 13, 'Ba he ba zama''ele''ö ba Zamaria, ba fa''owöhö mowa u''ila; ba [döi] Mba''ali andrö mama''ele''ö ira, wamowöhö banuagu.', '["Faigi 9:2","Hez 23:39","MozV 32:32; Yes 1:9","Yes 8:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 14, 'Iraono Gizeraeli. Ba ba zama''ele''ö ba Yeruzalema, ba sogoro ita u''ila: mohorö ba molau faya ba la''abe''e''ö dödö zamazökhi si lö sökhi, fa samösa lö samalalini era-erania, wondröi si lö sökhi andrö khönia. Dozi ira, ba no amaedola mbanua Zodoma ira khögu ba ösi mbanua, ba no amaedola mbanua Gomora.[8]', '["Faigi 9:2","Hez 23:39","MozV 32:32; Yes 1:9","Yes 8:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 15, 'Andrö imane Yehowa ngahönö andrö ba khö zama''ele''ö andrö: Hiza, ube''e öra zafeto sibai ba ufabadugö khöra nidanö langu; noa sa ba zama''ele''ö andrö ba Yeruzalema i''otarai si lö sökhi, wanörö tanö ma''asagörö![9]', '["Faigi 9:2","Hez 23:39","MozV 32:32; Yes 1:9","Yes 8:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 16, 'Imane Yehowa ngahönö andrö: Böi mifondrondrongo li zama''ele''ö andrö khömi — lafowöhö ami; angilata nifakhai dödöra la''ombakha''ö khömi, tenga niŵa''ö Yehowa.[10]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 17, 'Lö aetu lamane ba zi lö ba dödö ya''odo: "No muhede Yehowa: Fangorifi misöndra". Ba he no dozi abe''e dandro, wolo''ö nikhoi dödöra, ba lamane zui: "Lö''ö sa itörö ami famakiko."[11]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 18, 'Ha niha sa zi möi ba rafe andrö khö Yehowa, ba to''ele khönia daroma linia ba irongo! Same''e ba dödö taroma ligu, da''ö zangombakha.', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 19, 'Tesao sa''ae nangi sabölö khö Yehowa, fönunia, ba tawuyu nangi — itörö högö zebua horö andrö.[12]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 20, 'Lö alö wönu Yehowa andrö, irege no itörö nihonogöinia ibe''e, irege no ifalua, — moroi furi dania aboto sibai ba dödömi!', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 21, 'Lö nifatengegu sama''ele''ö da''ö, — ba fagohi zui ira; lö sihededo khöra, — ba mama''ele''ö zui ira![13]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 22, 'Na si ndruhu no möi ira ba rafe khögu mena''ö, ba la''ombakha''ö ena''ö ba mbanuagu daroma ligu, ba laröi lala si lö sökhi andrö khöra [banuagu] ba bua-buara si lö sökhi, labe''e ena''ö.', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 23, 'Hadia, [ha] Lowalangi ba zahatö ndra''odo — iŵa''ö Yehowa — ba tenga Lowalangi ba zaröu [göi]?[14]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 24, 'Hadia, i''ila ibini''ö ia ba mbini-mbini niha, fa lö u''ila ia? — iŵa''ö Yehowa. Hadia, tenga samo''ösi banua si yaŵa ba tanö si tou ndra''odo? — iŵa''ö Yehowa.[15]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 25, 'No urongo niŵa''ö zama''ele''ö andrö, sama''ele''ö faya ba döigu, me lamane: No mangifi ndra''o, fangifi khögu!', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 26, 'Ha wa''ara [zi manö]? Hadia, no so ba dödö zama''ele''ö andrö, sama''ele''ö faya, si no sama''ele''ö faya, nifakhai dödöra, — hadia,', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 27, 'da''ö zomasi ira lua-lua wangifira andrö, si faoma ladunö-dunö khö nawöra, ena''ö olifu mbanuagu döigu, si mane fa''olifu ndra tuara döigu, ba Mba''ali andrö?[16]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 28, 'Na so zama''ele''ö si no mangifi, ba yamu''tunö wangifi, ba si so taroma ligu, ba yamu''ombakha''ö ligu, si ndruhu-ndruhu! Hadia, tenga no faehu ira döla wakhe mbua? — iŵa''ö Yehowa.', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 29, 'Hadia, tenga atö amaedola galitö daroma ligu andrö — iŵa''ö Yehowa — ba amaedola warökha, famoto gara?[17]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 30, 'Andrö imane Yehowa: Hiza, ulau ba zama''ele''ö andrö, si faoma managö taroma ligu khö nawöra.[18]', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 31, 'Hiza, ulau ba zama''ele''ö andrö — iŵa''ö Yehowa — si oguna''ö lelara ba wanguma''ö: "Niŵa''ö Lowalangi."', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 32, 'Hiza, ulau ba zama''ele''ö andrö, sangombakha fangifi faya — iŵa''ö Yehowa — sanutunö, ba samaelungu banuagu falimosara ba hokhara andrö, ba tenga sa nifatengegu ira, lö niŵa''ögu khöra, ba lö gunara ba niha andre — iŵa''ö Yehowa.', '["Faigi 14:14","Faigi 6:14","Faigi 30:23","Faigi 27:15","Sin 139:8–10","Amos 9:2","Sanguhuk 3:7; 8:34","Heb 4:12","MozV 18:20; Faigi 14:14"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 33, 'Ba na lasofu khöu niha andre, ba ma sama''ele''ö, ma ere, na lamane: "Hadia noro khö Yehowa?" ba ömane khöra: Ya''ami noro, ba utibo''ö tou ami! — iŵa''ö Yehowa —.', '["Faigi 20:11"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 34, 'Ba sama''ele''ö ba ere ba sato, sanguma''ö! "Noro khö Yehowa", ba u''otu''ö zi manö, ufarahugö zi samba omo.', '["Faigi 20:11"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 35, 'Ba faoma mimane ba nawömi, ya imane zamösana ba dalifusönia: "Hadia niŵa''ö Yehowa wanema li?" ba ma: "He wisa wehede Yehowa?"', '["Faigi 20:11"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 36, 'Ba "noro khö Yehowa", ba böi itörö limi; "noro" ba zamösana sa linia, me no mifuyu''ö daroma li Lowalangi sauri, li Lowalangida, Yehowa ngahönö andrö.', '["Faigi 20:11"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 37, 'Ba ömane ba zama''ele''ö andrö: "Hadia niŵa''ö Yehowa, wanema liu?" ba ma: "He wisa wehede Yehowa?"', '["Faigi 20:11"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 38, 'Ba na miŵa''ö: "Noro khö Yehowa", ba imane Yehowa: Me miŵa''ö-ŵa''ö: "Noro khö Yehowa", — he ŵa''ae no ufaŵa''ögö khömi: Böi miŵa''ö-ŵa''ö: "Noro khö Yehowa!" — ba hiza,', '["Faigi 20:11"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 39, 'ufazaŵa ami [si mane noro] ba utibo''ö ami, fa böi sa''ae u''ila ami, ya''ami ba banua andrö, nibe''egu khömi ba khö ndra tuami.', '["Faigi 20:11"]', NULL),
  (3476346, 'OT', 'Yeremia', 23, 40, 'Ba uhawui ami fama''iki niha bö''ö si lö aetu ba fa''aila, si lö''ö manö taya ba dödö.[19]', '["Faigi 20:11"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 1, 'Ifamaigi ndra''o Yehowa, ba hiza dombua daga marafala föna gosali Yehowa (me no i''oloi''ö Nebukanesa razo Mbabeli razo mado Yuda andrö, Yoyakhi, ono Yoyaki, awö zatua mado Yuda awö duka, awö ziambu, banua Yeruzalema, me no i''ohe ba Mbabeli)[1]', '["RazII 24:15,16; Nga''öt. II, 36:10"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 2, 'Ba ndraga si sambua, ba marafala si sökhi sibai, timba marafala sahulö; ba ba zi sambua, ba fondrege zi lö sökhi, si tebai ni''a, ba walösökhi.', '["RazII 24:15,16; Nga''öt. II, 36:10"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 3, 'Ba imane khögu Yehowa: Hadia ni''ilau, Yeremia? Ba umane: Marafala. Marafala si sökhi andrö, ba no sökhi sibai, ba si lö sökhi, ba fondrege zi lö sökhi, tebai ni''a, — balazi walösökhi.', '["RazII 24:15,16; Nga''öt. II, 36:10"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 4, 'Ba humede khögu Yehowa, imane:', '["MozV 30:6; Faigi 31:33; Hez 11:10","Faigi 29:17","MozV 28:37; Faigi 15:4","Faigi 34:17"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 5, 'Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Si mane fa''asökhi marafala si sökhi andrö, si manö wamaigigu ni''oloi''ö andrö, mado Yuda, nifa''ohe''ögu ba danö Ndrawa Galedaia, nihetagu ba mbanua da''e: uhakhösi tödö ira.', '["MozV 30:6; Faigi 31:33; Hez 11:10","Faigi 29:17","MozV 28:37; Faigi 15:4","Faigi 34:17"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 6, 'U''ebua''ö dödögu, wamaigi ya''ira, ba u''ohe mangawuli ira ba danö da''e, ena''ö u''otomosi ba lö ufuli ududugö, ba ena''ö utanö ba lö ufuli udeha.', '["MozV 30:6; Faigi 31:33; Hez 11:10","Faigi 29:17","MozV 28:37; Faigi 15:4","Faigi 34:17"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 7, 'Ba ube''e khöra wa''oboto ba dödö, ena''ö aboto ba dödöra ndra''o, wa no Yehowa ndra''odo! Ba banuagu dania ira ba Lowalangira ndra''odo, na moroi si''aikö ba dödöra lafuli ira khögu.[2]', '["MozV 30:6; Faigi 31:33; Hez 11:10","Faigi 29:17","MozV 28:37; Faigi 15:4","Faigi 34:17"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 8, 'Ba si mane marafala si lö sökhi andrö si tebai ni''a, balazi walösökhi — iwa''ö Yehowa — si manö wolaugu khö Zedekia, razo mado Yuda andrö ba ba nawönia satua ba ba zi tosai banua Yeruzalema, he ba zi tosai ba danö andre ba he ba zi no möi fatewu ba danö Miserayi:[3]', '["MozV 30:6; Faigi 31:33; Hez 11:10","Faigi 29:17","MozV 28:37; Faigi 15:4","Faigi 34:17"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 9, 'Ba ube''e nifakao ira, dozi soi ba guli danö zamakiko; ube''e nihöwöhöwö ba ni''igi''igi''ö ba ni''o''aya ba ni''elifi, ba mbanua andrö fefu, ba nitibo''ögu ya''ira.[4]', '["MozV 30:6; Faigi 31:33; Hez 11:10","Faigi 29:17","MozV 28:37; Faigi 15:4","Faigi 34:17"]', NULL),
  (3476347, 'OT', 'Yeremia', 24, 10, 'Ba ufatörö khöra zi''öli ba lofo ba fökhö waba, irege no ahori ira ba danö andrö, nibe''egu khöra ba khö ndra tuara mege.[5]', '["MozV 30:6; Faigi 31:33; Hez 11:10","Faigi 29:17","MozV 28:37; Faigi 15:4","Faigi 34:17"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 1, 'Taroma li niŵa''ö khö Yeremia ba mado Yuda fefu, me no alua medölu fakhe razo Yoyaki andrö, ono Yosia, razo mado Yuda — döfi si föföna da''ö khö Nebukanesa andrö, razo Mbabeli.', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 2, 'Nifa''ema Yeremia ba mado Yuda fefu ba ba mbanua Yeruzalema fefu, imane:', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 3, 'I''otarai me alua mewelendrua fakhe razo Yosia, ono Gamoni, razo mado Yuda, ba irege ma''ökhö andre — no dua wulu a tölu fakhe sa''ae — wa no humede-hede khögu Yehowa, awö wa lö satagedo fangombakha khömi —, ba lö nifondrondrongomi.[1]', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 4, 'Ba lö sadage-dage Yehowa famatenge khömi enoninia fefu, sama''ele''ö andrö, ba lö nifondrondrongomi, lö nibe''emi börö dalingami, ba wamondrongo ena''ö.[2]', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 5, 'No mamane: "Mifuli ami! Yamuröi lalania si lö sökhi andrö zamösana, miböhöli mbua-buami andrö, si lö sökhi, ba si lö tebulö ba danö ami, ba danö nibe''e Yehowa khömi ba khö ndra tuami mege, si no götö-götö fa''ara.[3]', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 6, 'Ba böi mifahulö Lowalangi bö''ö, ba wamosumange ya''ira ba ba wangalulu khöra, böi mi''andrö wönugu nilau dangami andrö, fa böi ufatörö wamakiko khömi!"', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 7, 'Ba lö''ö zui mifondrondrongo khögu — iŵa''ö Yehowa — ba wangandrö fönugu nilau dangami andrö, famakikomi.', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 8, 'Andrö imane Yehowa ngahönö andrö: Me lö nifondrondrongomi taroma ligu,', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 9, 'ba ufakaoni''ö fefu soi moroi yöu — iŵa''ö Yehowa — ba enonigu andrö, Nebukanesa, razo Mbabeli, ba lahawui danö andre ube''e, awö niha ba danö, awö soi bö''ö andrö fefu si tefasui ya''ira, ba ube''e nifakiko, ube''e börö wehokha mbu ba börö wa''iki ba börö wango''aya si lö mamalö-malö.[4]', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 10, 'Ba ubunu ba khöra li wa''owua-wua dödö ba li wa''omuso dödö, li zangowawalu ba li nono nihalö ba koko halu ba haga wandru.[5]', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 11, 'Ba tanö da''e ma''afefu, ba nibali''ö sasai''ö, nibali''ö tanö si mate, ba soi andre, ba sawuyu razo Mbabeli, fitu ngafulu fakhe wa''ara.', '["Faigi 29:19; 35:14","Faigi 7:25","RazII 17:13; Faigi 18:11","Faigi 1:15","Yes 24:8; Fam 18:22"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 12, 'Ba na no alua zi fitu ngafulu fakhe, ba usulöni khö razo Mbabeli ba ba soi niha andrö golalöŵara andrö — iŵa''ö Yehowa — ba ba danö Ndrawa Galedaia andrö; ba ubali''ö tanö si mate, si lö mamalö-malö.[6]', '["Nga''ötII 36:21; Dan 9:2","Faigi 27:7"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 13, 'Ba itörö ba danö andrö ligu fefu, niŵa''ögu, ube''e — fefu nisura ba zura andre, nifa''ele''ö Yeremia, ba soi niha andrö fefu.', '["Nga''ötII 36:21; Dan 9:2","Faigi 27:7"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 14, 'Ya''ira sa''ae dania göi, ba ni''osawuyu soi sabölö ba ni''osawuyu razo sebua, ba usulöni khöra nifazökhira, nilau dangara andrö.[7]', '["Nga''ötII 36:21; Dan 9:2","Faigi 27:7"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 15, 'Noa sa imane khögu Yehowa Lowalangi Ndraono Gizeraeli: Tema zi samba mako agu andre ba dangagu, agu fönu, ba fabadugö ba soi niha andrö fefu, ba nifatengegu ya''ugö.[8]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 16, 'Ena''ö labadu ba ena''ö mabo, ena''ö owöhö ira, ba zi''öli andrö, nifatörögu khöra.[9]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 17, 'Ba uhalö mako andrö ba danga Yehowa, ba ufabadugö ba soi niha andrö fefu, ba nifatenge Yehowa ya''odo.', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 18, 'Ba Yeruzalema ba ba mbanua mado Yuda, ba razora ba ba zatuara, ba wamali''ö tanö si mate tanöra, ena''ö börö wehokha mbu ba börö wa''iki ba börö wangelifi, si mane ma''ökhö andre.', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 19, 'Fara''o andrö, razo Miserayi, fabaya enoninia ba kumandrunia ba banuania fefu,[10]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 20, 'ba Erebi andrö, ma''afefu, numalö fefu razo ba danö Usi ba fefu razo ba danö Wilisiti, ya''ia Gasikalo ba Gasa ba Ekerona ba si tosai Gasoto;[11]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 21, 'Iraono Gedomo ba Iraono Moabi ba Iraono Gamoni;[12]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 22, 'numalö fefu razo Diro ba fefu razo Zidona ba razo ba hulo ba nasi.[13]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 23, 'Ba Dedano ba Tema ba Busi ba nifalo''o bu andrö, fefu.[14]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 24, 'Ba dozi razo Ndrawa Ara ba dozi razo Gerebi andrö, ba danö si mate.', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 25, 'Numalö dozi razo Zimeri ba dozi razo Gelama ba dozi razo Ndrawa Media,[15]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 26, 'awö razo yöu, fefu, si fahatö ba si fandröundröu, — fefu gamatöröŵa razo ba guli danö; ba afuriata, ba mamadu razo Zezakhi (Babeli)![16]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 27, 'Ba ömane khöra: Da''ö niŵa''ö Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Mibadu, ena''ö mabu ami, ena''ö muta ba ena''ö tegaölö tou ami, si lö femaoso, ba zi''öli andrö, nifatörögu khömi!', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 28, 'Ba ma lö edöna ira, latema mako andrö ba dangau, ba wamadu, ba ömane khöra: Da''ö niŵa''ö Yehowa ngahönö andrö: Lö tola lö mamadu ami!', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 29, 'Hiza sa, ba mbanua andrö, si no fao ba döi töigu, ubörötaigö wamatörö famakiko, ba hadia, saefa ami? Tenga saefa ami, ukaoni sa''ae zi''öli, nifatörö ba niha ba guli danö fefu! — iŵa''ö Yehowa ngahönö —.[17]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 30, 'Ba öfa''ema khöra daroma li da''e fefu, ömane khöra: Mundröndröndröndrö dania Yehowa, moroi ba mbanua si yaŵa, ba moroi ba nahiania andrö, ni''amoni''ö ifarongogö linia! Ebua linia wendröndröndröndrö ba mbenua andrö khönia, ikaraini wa''iki, si mane si hundragö folazi, ba niha ba guli danö, fefu.[18]', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 31, 'Humöngö, irugi ba wondrege danö; fasoso sa''ae Yehowa ba soi niha; ifatörö huku ba nösi guli danö fefu; sebua horö andrö, ba ilulu ba mbawa zi''öli! — iŵa''ö Yehowa.', '["Yob 21:20","Yes 51:17; Sin 60:5; 75:9; Yob 21:20","Faigi 46:2","Faigi 47:1","Faigi 49:7; 48:1; 49:1","Yes 23:8; Faigi 47:4","Faigi 9:26","Faigi 49:34","Yer 51:41","Faigi 49:12; FetI 4:17","Yoel 3:16; Amos 1:2"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 32, 'Imane Yehowa ngahönö andrö: Hiza wamakiko, itöröi soi niha, tesao nangi sabölö, moroi ba wondrege danö.', '["Faigi 16:4","Faigi 4:8; 6:26"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 33, 'Ba so tou ba danö dania nibubunu Yehowa, na luo da''ö, i''otarai wondrege danö, numalö ba wondrege tanö sa; lö''ö sa la''e''esi ba lö la''ozaragö ba wogo''o: tobali fangatabö zinanö ba nowi.[19]', '["Faigi 16:4","Faigi 4:8; 6:26"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 34, 'Mi''ege-ege, ya''ami kubalo, milau mu''ira-ira, mifagaölö ami ba danö, ya''ami satua nikubaloi; noa sa irugi baŵa khömi, ba wanaba ya''ami, ba ba ŵa wamazawili ya''ami, ba tobali aekhu tou ami, si mane figa sebua böli![20]', '["Faigi 16:4","Faigi 4:8; 6:26"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 35, 'Lö''ö sa''ae saŵatö gubalo ba lö lala woloi ba zalaŵa nikubaloi,', '["Faigi 16:4","Faigi 4:8; 6:26"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 36, 'Mifondrondrongo! — fe''ira-ira gubalo ba fege-ege zalaŵa nikubaloi andrö, me ibali''ö tanö si mate naha göra Yehowa,', '["Faigi 16:4","Faigi 4:8; 6:26"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 37, 'ba benua si lö hadia ia mege, ba nifufu ba wa''aukhu wönu Yehowa andrö!', '["Faigi 16:4","Faigi 4:8; 6:26"]', NULL),
  (3476348, 'OT', 'Yeremia', 25, 38, 'No iröi ndru''u andrö khönia (mbini-mbini), si mane singo; tanö si mate sa''ae danöra, ba zi''öli andrö, sabölö sibai ba ba wa''aukhu wönunia andrö.', '["Faigi 16:4","Faigi 4:8; 6:26"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 1, 'Ba me awena razo Yoyaki andrö, ono Yosia, razo mado Yuda, ba iŵa''ö da''e khö Yeremia Yehowa.[1]', '["RazII 23:34","Faigi 18:8","Faigi 25:3","Sin 78:60; Faigi 7:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 2, 'Imane Yehowa: Iagö golayama gosali Yehowa ba hede ba mbanua mado Yuda andrö fefu, si no möi bakha, ba wangandrö ba gosali Yehowa; farongogö khöra daroma li andrö fefu, niŵa''ögu khöu nifa''ema khöra! Sambua li böi ambösi.', '["RazII 23:34","Faigi 18:8","Faigi 25:3","Sin 78:60; Faigi 7:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 3, 'Ma atö lafondrondrongo, ma lafuli ira, ma iröi lala si lö sökhi andrö khönia zamösana, ena''ö mangesa dödögu, ba wamakiko andrö, miŵa''ögu nifatörö khöra, ba mbua-buara andrö, si lö sökhi.[2]', '["RazII 23:34","Faigi 18:8","Faigi 25:3","Sin 78:60; Faigi 7:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 4, 'Ba ömane sa''ae khöra: Imane Yehowa: Na lö mifondrondrongo ligu, wolo''ö oroisagu andrö, nifakhoigu khömi,', '["RazII 23:34","Faigi 18:8","Faigi 25:3","Sin 78:60; Faigi 7:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 5, 'ba wamondrongo li genonigu sama''ele''ö andrö, si lö atagedo famatenge-tenge khömi, lö lai wa lö nifondrondrongomi,[3]', '["RazII 23:34","Faigi 18:8","Faigi 25:3","Sin 78:60; Faigi 7:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 6, 'ba faoma ira gosali ba da''e gosali andrö ba Zilo no, ube''e, ba banua andre, ba ube''e ni''elifi ba soi niha ba guli danö fefu.[4]', '["RazII 23:34","Faigi 18:8","Faigi 25:3","Sin 78:60; Faigi 7:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 7, 'Ba me larongo ere ba sama''ele''ö ba sato fefu i''ombakha''ö Yeremia daroma li da''ö, ba gosali Yehowa,', '[]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 8, 'ba me no i''o''ozui Yeremia wama''ema fefu ni''oroi''ö Yehowa, niŵa''ö ba zato, ba lara''u ia ere ba sama''ele''ö andrö ba sato, lamane: Si mate ndra''ugö!', '[]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 9, 'Hana wa ömanö wama''ele''ö ba döi Yehowa, wa ömane: Lala gosali ba Zilo no andrö lala gosali da''e dania ba banua andre, ba nidudugö, ba si lö niha dania! Ba aekhu niha sato fefu ba gosali Yehowa, udu Yeremia.', '[]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 10, 'Ba me terongo duria da''ö ba zatua mado Yuda, ba möi ira miyaŵa ba gosali Yehowa, la''otarai gödo razo, ba mudadao ba mbawa göli Yehowa andrö, si bohou.', '[]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 11, 'Ba lamane ere ba sama''ele''ö andrö ba zatua no mege ba ba zato: Huku famunu huku niha da''ö, me no ifa''ele''ö wa''atekiko mbanua da''e, nirongomi tögi dalingami!', '[]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 12, 'Ba humede Yeremia ba zatua fefu ba ba zato, imane: Yehowa zamatenge ya''o, ba wama''ele''ö taroma li andrö fefu ba gosali andre ba ba mbanua andre, nirongomi andrö.', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 13, 'Ba iya''e, ba mitörö lala si sökhi ba mihaogö mbua-buami ba mifondrondrongo niŵa''ö Lowalangimi, Yehowa, ena''ö mangesa dödö Yehowa ba wamakiko andrö, nidaö''ö-daö''önia khömi.[5]', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 14, 'Ba ya''odo andre — ba hiza, no sodo ba dangami. Mifatörö khögu zatulö dödömi!', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 15, 'Ba böi zi lö aboto ba dödömi: na mibunu ndra''odo, ba do zi lö horö mihare''ö khömi ba ba mbanua da''e, fabaya ösinia; noa sa si ndruhu, Yehowa zamatenge ya''odo ba khömi, ba wamarongogö khömi taromali andrö fefu!', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 16, 'Ba lamane satua andrö ba sato ba gere ba ba zama''ele''ö andrö: Tenga nibunu niha da''e, noa sa ba döi Lowalangida Yehowa humede ia khöda!', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 17, 'Ba maoso ösa zatua mbanua andrö, ba lamane ba niha sato fefu, si no owulo ba da''ö:', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 18, 'Maoso sama''ele''ö Mikha andrö, banua Moreseti, me luo razo mado Yuda Hisikia, ba imane ba zato mado Yuda: ''Da''ö niŵa''ö Yehowa ngahönö andrö: Nifaku nowi dania Ziona, ba adudula Yeruzalema, ba satua eu hili gosali andrö!''[6]', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 19, 'Ba hadia, no labunu ia Hisikia razo mado Yuda ba sato mado Yuda? Hadia, tenga no i''ata''ufi Yehowa Hisikia ba tenga no mangalulu ia khönia, irege mangesa dödö Yehowa, ba wamakiko andrö, nidaö''ö-daö''önia khöra? ba ya''ita ba hadia, ta''arö wamakiko sebua, famunuda?', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476349, 'OT', 'Yeremia', 26, 20, 'Ba so göi na danö bö''ö, sama''ele''ö ba döi Yehowa, Uria döi, ono Zemaya, banua Giriati Yeari; ifa''ele''ö zi göna dania mbanua da''e ba tanö da''e, ha sara wehedera Yeremia.', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 21, 'Ba me larongo niŵa''önia Yoyaki andrö, razo ba sabölö andrö khönia ba kumandru sebua khönia, fefu, ba i''alui razo wamabunu''ö ya''ia. Ba me terongo khö Guria, ba ata''u ia, ilau moloi, isaŵa danö Miserayi.', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 22, 'Ba ifatenge niha ba danö Miserayi Yoyaki, razo, Eli-Natano andrö, ono Nakhiboro ba awönia,', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 23, 'ba lahalö Guria, moroi ba danö Miserayi ba la''ohe khö razo Yoyaki; ba ifabunu''ö si''öli ba ifatibo''ögö ba lewatö nono mbanua mbotonia.', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476349, 'OT', 'Yeremia', 26, 24, 'Ba iba''agö ia khö Yeremia Ahika andrö, ono Zafano, fa böi labe''e ba danga zato, ba wamunu ya''ia.[7]', '["Faigi 7:3","Mikh 1:1; 3:12","RazII 22:12"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 1, 'Ba me awena razo Zedekia andrö, ono Yosia, razo mado Yuda, ba humede Yehowa khö Yeremia.', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 2, 'Imane [Yeremia]: Imane khögu Yehowa: Fazökhi khöu wesu ba kalo magi, ba be''e ba mbagiu,[1]', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 3, 'ba fa''ohe''ö khö razo Ndraono Gedomo ba khö razo Ndraono Moabi ba khö razo Ndraono Gamoni ba khö razo Diro ba khö razo Zidona, fa''ohe''ö ba zinenge andrö, si no möi khö Zedekia, razo mado Yuda, ba Yeruzalema.', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 4, 'Ba oroi''ö khöra, ndramane ba razora: Da''ö niŵa''ö Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Mimane ba razomi:', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 5, 'Ya''odo zomböi tanö, awö niha, awö gurifö niha, ba guli danö ba wa''abölögu andrö, si lö ambö ba tangagu ni''oro''ö, ba ube''e ba zomasido.[2]', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 6, 'Ba iya''e, ba ube''e barö mbawa genonigu Nebukanesa andrö, razo Mbabeli danö andrö fefu, numalö saliŵa-liŵa ba danö, ba ube''e khönia, ena''ö ngoni-ngoninia.[3]', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 7, 'Ba amaedola zawuyunia ba sawuyu nononia ba sawuyu ma''uwunia fefu soi, balazi irugi baŵa danönia andrö göi, irege labe''e amaedola zawuyura ia soi sabölö ba razo sabe''e.', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 8, 'Ba na so soi, na so nöri niha, si lö edöna möi enoninia, enoni Nebukanesa, razo Mbabeli andrö, si lö edöna mame''e bagira ba galo mbagi andrö khö razo Mbabeli, ba ufatörö zi''öli ba lofo ba fökhö waba ba niha da''ö, iŵa''ö Yehowa, irege no uhori ira tangania.', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 9, 'Ba ya''ami, ba böi mitöngöni niŵa''ö zama''ele''ö andrö khömi, ba he niŵa''ö zi faeta andrö, ba he fangifimi, ba he niŵa''ö zangombakha eluaha dandra hadia ia, ba he niŵa''ö zebua elemu, na lamane khömi: "Tenga si möi enoni razo Mbabeli ami".[4]', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 10, 'Faya nifa''ele''öra khömi, ba wameta ya''ami ba danömi; ena''ö utimba ami ba ena''ö tekiko ami.', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 11, 'Ba soi same''e baginia ba galo mbagi andrö khö razo Mbabeli, ba we''amöi enoninia, ba lö ubulö''ö ba danönia — iŵa''ö Yehowa —, ena''ö mangahalö ira ba ena''ö soso ira ba da''ö.', '["Faigi 28:10","MozI 1","Dan 4:22","MozV 18:10,11; Faigi 23:16"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 12, 'Ba khö Zedekia, razo mado Yuda andrö göi, ba uŵa''ö-ŵa''ö da''ö fefu, umane: Mi''oro''ö mbagimi andrö khö razo Mbabeli ba mi''ae enoninia ba enoni mbanuania, ba sauri ami.', '["Faigi 14:14"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 13, 'Hana sa, wa edöna mate ami ba mbawa zi''öli ba ba lofo ba ba wökhö waba, nidaö''ö-daö''ö Yehowa ba soi andrö, si lö edöna möi enoni razo Mbabeli, ya''ugö ba banuau andrö?', '["Faigi 14:14"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 14, 'Böi sa mifondrondrongo niŵa''ö zama''ele''ö andrö, na lamane khömi: "Tenga si möi enoni razo Mbabeli ami!" — faya sa nifa''ele''öra khömi.[5]', '["Faigi 14:14"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 15, 'Tenga sa ya''odo zamatenge ya''ira — iŵa''ö Yehowa — sofaya sa''ae ira, wama''ele''ö ba döigu, ena''ö utimba ami ba ena''ö tekiko ami, fabaya sama''ele''ö khömi.', '["Faigi 14:14"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 16, 'Ba umane göi ba gere ba niha da''e fefu: Da''ö niwa''ö Yehowa: Böi mifondrondrongo niŵa''ö zama''ele''ö andrö, na mama''ele''ö ira khömi, na lamane: "Hiza, alio sa''ae tefuli wakake ba gosali Yehowa andrö, moroi ba Mbabeli!" — faya sa''ae nifa''ele''öra khömi.', '["RazII 25:13","RazII 24:14","Raz. II, 36:18; Faigi 29:10"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 17, 'Böi mifondrondrongo khöra, mi''ae enoni razo Mbabeli, ba sauri ami! Hana wa tanö si mate dania naha mbanua da''e?', '["RazII 25:13","RazII 24:14","Raz. II, 36:18; Faigi 29:10"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 18, 'Ba na sama''ele''ö atö ira ba na so khöra daroma li Yehowa, ba ndramu''andrö khö Yehowa ngahönö andrö, ena''ö böi te''ohe ba Mbabeli wakake andrö si tosai ba gosali Yehowa ba ba gödo razo mado Yuda ba ba Yeruzalema.', '["RazII 25:13","RazII 24:14","Raz. II, 36:18; Faigi 29:10"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 19, 'Imane sa Yehowa ngahönö andrö, ba gehomo andrö ba ba mbaŵa nidanö andrö ba ba dadaoma andrö, ba ba zi tosai fakake, si tosai ba mbanua andre,[6]', '["RazII 25:13","RazII 24:14","Raz. II, 36:18; Faigi 29:10"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 20, 'niröi Nebukanesa, razo Mbabeli, me i''oloi''ö Yekhonia, ono Yoyaki, razo mado Yuda, moroi ha Yeruzalema, me i''ohe ba Mbabeli, fabeya salaŵa mado Yuda fefu ba salaŵa Yeruzalema:[7]', '["RazII 25:13","RazII 24:14","Raz. II, 36:18; Faigi 29:10"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 21, 'imane sa''ae Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli, ba wakake andrö, si tosai na ba gosali Yehowa ba ba gödo razo mado Yuda ba ba Yeruzalema:', '["RazII 25:13","RazII 24:14","Raz. II, 36:18; Faigi 29:10"]', NULL),
  (3476350, 'OT', 'Yeremia', 27, 22, 'Ba Mbabeli te''ohe dania, ba ba da''ö ahono, balazi irugi baŵa ufuli ufaigi — iŵa''ö Yehowa — ba wangai ya''ia, ba wamuli ba naha andre.[8]', '["RazII 25:13","RazII 24:14","Raz. II, 36:18; Faigi 29:10"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 1, 'Ba me döfi da''ö — me böröta, wa razo Zedekia, razo mado Yuda, ba ndröfi si öfa, baŵa si lima, ba humede khögu zama''ele''ö andrö, Hanania, ono Gasuri, banua Gibeona, ba gosali Yehowa, ba zi so ere ba sato fefu,', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 2, 'imane: Da''ö niŵa''ö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Urasa galo mbagi andrö khö razo Mbabeli!', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 3, 'Lö alua mendrua fakhe, ba u''ohe mangawuli ba naha andre fefu wakake andrö ba gosali Yehowa, nihalö Nebukanesa, ba mbanua, ni''ohenia ba Mbabeli.', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 4, 'Fabaya Yekhonia, ono Yoyaki, razo mado Yuda, awö fefu ni''oloi''ö andrö, mado Yuda, si no mondrugi Babeli, ba u''ohe mangawuli ba mbanua andre — iŵa''ö Yehowa — urasa sa''ae galo mbagi andrö khö razo Mbabeli.', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 5, 'Ba humede Yeremia khö Hanania andrö, sama''ele''ö, ba zi so ere ba sato fefu, si so ba gosali Yehowa.', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 6, 'Imane Yeremia, sama''ele''ö: Ya''ia da''ö! Yamufalua da''ö Yehowa! Yamube''e Yehowa itörö limö, nifa''ele''ömö, yamu''ohe mangawuli ba mbanua andre wakake andrö ba gosali Yehowa, awö fefu niha ni''oloi''ö, moroi ba Mbabeli.', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 7, 'Ba fondrondrongo na da''e, nifarongogögu khöu ba ba zato fefu:', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 8, 'Sama''ele''ö andrö fönagu ba fönau, i''otarai götö föna sa''ae, ba ba danö soya mama''ele''ö ba ba gamatöröŵa razo sebua; fanuwö ba famakiko ba fökhö waba la''ombakha''ö;', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 9, 'ba sama''ele''ö fangorifi — ba na itörö li zama''ele''ö andrö, ba oroma, ha niha zama''ele''ö andrö, ba oroma, ha niha zama''ele''ö nifatenge Lowalangi, si ndruhu-ndruhu.[1]', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 10, 'Ba ihalö galo mbagi andrö ba mbagi Yeremia sama''ele''ö Hanania sama''ele''ö andrö, ifatö.', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 11, 'Ba imane Hanania, ba zi so sato fefu: Da''ö niŵa''ö Yehowa: Lö alua mendrua fakhe, ba umanö worasa kalo mbagi andrö khö Nebukanesa, razo Mbabeli ba mbagi niha fefu, ha soi ira! Ba ilau mofanö Yeremia.', '["MozV 18:22"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 12, 'Ba me no ifatö Hanania sama''ele''ö andrö galo mbagi Yeremia sama''ele''ö, ba humede Yehowa khö Yeremia,', '["MozV 28:14","MozV 13:5; Faigi 29:32"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 13, 'imane: Ae ŵa''ö khö Hanania andrö: Da''ö niwa''ö: Kalo mbagi eu nifatöu, ba ufazökhi galo mbagi si''öli, fangalinia!', '["MozV 28:14","MozV 13:5; Faigi 29:32"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 14, 'Imane sa Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Kalo mbagi si''öli uhare''ö ba mbagi niha andrö fefu, ha soi ira, ena''ö enoni Nebukanesa, razo Mbabeli, ira, ena''ö ngoni-ngoninia, numalö saliŵa-liŵa ba danö, ba ube''e khönia.[2]', '["MozV 28:14","MozV 13:5; Faigi 29:32"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 15, 'Ba imane Yeremia sama''ele''ö khö Hanania sama''ele''ö andrö: Fondrondrongo, ya''ugö Hanania! Tenga Yehowa zamatenge ya''ugö, ba noa zui öfowöhö niha andre ba wa''abe''e dödö ba walimosa andrö.', '["MozV 28:14","MozV 13:5; Faigi 29:32"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 16, 'Andrö imane Yehowa: Hiza, uheta ndra''ugö ba guli danö; barö ndröfi andre mate ndra''ugö me no öfarou niha ba wolaŵa Yehowa![3]', '["MozV 28:14","MozV 13:5; Faigi 29:32"]', NULL),
  (3476351, 'OT', 'Yeremia', 28, 17, 'Ba mate Hanania, sama''ele''ö andrö ba ndröfi da''ö, me baŵa si fitu.', '["MozV 28:14","MozV 13:5; Faigi 29:32"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 1, 'Ba da''e zura andrö, nifa''ohe''ö Yeremia sama''ele''ö, moroi ba Yeruzalema, ba zi tosai satua ni''oloi''ö andrö ba ba gere ba ba zama''ele''ö andrö, ba ba zato fefu, ni''oloi''ö Nebukanesa ba Mbabeli, moroi ba Yeruzalema,', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 2, '(me no aheta ba Yeruzalema razo, Yekhonia, ba salaŵa ira alawe andrö ba enonira yomo ba kumandru sebua andrö, ba Ndraono Yuda, ba ba Yeruzalema ba tuka ba siambu)[1]', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 3, 'Ifa''ohe''ö khö Geleasa, ono Zafano, awö Gemaria, ono Hilikia, nifatenge Zedekia, razo mado Yuda, khö Nebukanesa, razo Mbabeli, imane ba zura andrö:', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 4, 'Da''ö niŵa''ö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli ba ni''oloi''ö andrö fefu, ni''oloi''ögu ba Mbabeli, moroi ba Yeruzalema:', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 5, 'Milau nomo ba ni''onahia, milau mokabu ba mi''a mbua zinanö bakha.', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 6, 'Mi''angowalu ba mi''o''ono, ono matua ba ono alawe, ba mifangowalu nonomi matua ba mibe''e nihalö nonomi alawe, ena''ö mo''ono ira, ono matua ba ono alawe, ena''ö ato ami ba da''ö, ena''ö böi awuwu wa''ato.', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 7, 'Mi''alui wangorifi mbanua andrö, ba ni''oloiögu ya''ami, mi''angandrö khö Yehowa, salahira; fangorifimi sa''ae wangorifira!', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 8, 'Imane sa Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Böi lafowöhö ami sama''ele''ö andrö khömi, si so andrö ba khömi, ba ma si faeta andrö khömi, ba böi mi''amati ba wangifimi,', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 9, 'falimosa sa nifa''ele''öra khömi ba döigu, tenga ya''odo zamatenge ya''ira! — iŵa''ö Yehowa.[2]', '["RazII 24:12","Faigi 14:14; Rom 10:15"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 10, 'Imane sa Yehowa: Na no alua zi fitu ngafulu fakhe ba Mbabeli, awena ufaigi ami ba awena ufalua niŵa''ögu si sökhi andrö, ba khömi, wa u''ohe mangawuli ami ba mbanua da''e.[3]', '["Nga''ötII 36:22; Faigi 25:12","MozV 30:2","Faigi 23:3"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 11, 'U''ila sa, he wisa dödögu khömi — iŵa''ö Yehowa — tödö ba wangorifi ba tenga ba wamakiko, ba wamaigi fa''ohahau dödö khömi, ba götö dania!', '["Nga''ötII 36:22; Faigi 25:12","MozV 30:2","Faigi 23:3"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 12, 'Awena dania mi''angaröfi li ndra''o, möi ami mangandrö khögu, ba ufondrondrongo khömi.', '["Nga''ötII 36:22; Faigi 25:12","MozV 30:2","Faigi 23:3"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 13, 'Ba mi''alui ndra''o ba misöndrado, na moroi si''aikö ba dödö mi''alui ndra''o,[4]', '["Nga''ötII 36:22; Faigi 25:12","MozV 30:2","Faigi 23:3"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 14, 'ba ube''e nisöndrami ndra''odo — iŵa''ö Yehowa — ba ufaigi wangefa khömi, u''ozaragö ami, moroi ba niha fefu ba moroi ba mbanua fefu, ba nitibo''ögu ya''ami — iŵa''ö Yehowa — ba u''ohe mangawuli ami ba mbanua andrö, ba nihetagu ya''ami.[5]', '["Nga''ötII 36:22; Faigi 25:12","MozV 30:2","Faigi 23:3"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 15, 'Ba na mimane: No i asogö khöma zama''ele''ö ba Mbabeli Yehowa —', '["Faigi 24:3 b.t.","MozV 28:37","Faigi 25:4"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 16, 'Imane sa''ae Yehowa, ba khö razo andrö, sidadao ba dadaoma andrö khö Dawido, ba ba niha sato fefu, banua da''e talifusömi, si lö fao khömi, ya''ami ni''oloi''ö andrö —', '["Faigi 24:3 b.t.","MozV 28:37","Faigi 25:4"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 17, 'imane Yehowa ngahönö: Hiza, ufatörö khöra zi''öli ba lofo ba fökhö waba, ube''e amaedola marafala saisö ira, si tebai ni''a, balazi walösökhi.[6]', '["Faigi 24:3 b.t.","MozV 28:37","Faigi 25:4"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 18, 'Ba ube''e solohi ya''ira zi''öli ba lofo ba fökhö waba ba ube''e sihokha mbu ira, ba niha ba guli danö fefu; ube''e börö wangelifi ba börö wa''atobali dödö ba börö wa''iki ba börö wango''aya, ba niha fefu, ba nitibo''ögu ya''ira,[7]', '["Faigi 24:3 b.t.","MozV 28:37","Faigi 25:4"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 19, 'börö wa lö nifondrondrongora ligu — iŵa''ö Yehowa — si lö atagedo fama''ohe-ohe''ö khöra ba genonigu sama''ele''ö andrö, ba lö nifondrondrongomi — iŵa''ö Yehowa.[8]', '["Faigi 24:3 b.t.","MozV 28:37","Faigi 25:4"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 20, 'Ba ya''ami, ba mifondrondrongo li Yehowa, ya''ami ni''oloi''ö andrö fefu, nifa''ohe''ögu ba Mbabeli, moroi ba Yeruzalema:', '["Dan 3:6"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 21, 'Imane Yehowa ngahönö, Lowalangi Ndraono Gizeraeli ba khö Gahabi andrö, ono Golaya, ba ba khö Zedekia andrö, ono Maseya, sama''ele''ö faya khömi, ba döigu: Hiza, ube''e ba danga Nebukanesa, razo Mbabeli, ira, ena''ö ifabunu''ö ira, ba zanehe ami!', '["Dan 3:6"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 22, 'Ba tobali börö wangelifi ira ba ni''oloi''ö andrö fefu, mado Yuda, ba Mbabeli, lamane dania: "Yamufatörö''ö Yehowa ba lala ndra Sedekia Ahabi, nitunu razo Mbabeli, ba galitö!"[9]', '["Dan 3:6"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 23, 'Me no manao horö ira ba Ndraono Gizeraeli, me no lahoröni ndronga nawöra ba me no la''ombakha''ö waya ba döigu, si tenga niŵa''ögu khöra: — ya''odo sa''ae zangila, si so ba mbörö ndra''o! — iŵa''ö Yehowa.', '["Dan 3:6"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 24, 'Ba khö Zemaya andrö, banua Nehalama,', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 25, 'ba ömane: Da''ö niŵa''ö Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Me no ba döimö öfa''ohe''ö zura ba mbanua Yeruzalema fefu ba khö Zefania ere andrö, ono Maseya ba ba gere fefu, me no ömane:', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 26, 'No ifataro ndra''ugö ere Yehowa, fangali Yoyada, ere andrö, ena''ö ödaro-darogö, na so zowöhö, na so zama''ele''ö, ena''ö öbe''e ba galo ba ba mbilagu mbagi.[10]', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 27, 'Ba hana sa wa lö ötenaŵa Yeremia andrö, banua Ganatoti, si no mama''ele''ö khömi?', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 28, 'Noa sa atö ifa''ohe''ö khöma [zura] ba Mbabeli, wanguma''ö: "Ara na sa! Milau nomo ba mi''onahia, milau mokabu ba mi''a mbua zinanö bakha! ..."', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 29, 'Ba ibaso zura andrö Sefania, ere andrö, ba zamondrongo Yeremia.', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 30, 'Ba humede Yehowa khö Yeremia, imane:', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 31, 'Farongogö ba ni''oloi''ö andrö fefu, ömane: Imane Yehowa, ba khö Zemaya andrö, banua Nehalama: Me no mama''ele''ö khömi Zemaya andrö, lö lai wa tenga nifatengegu ya''ia, ba me no ifowöhö ami, ena''ö abe''e dödömi ba waya,', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476352, 'OT', 'Yeremia', 29, 32, 'ba imane Yehowa: Hiza, usulöni da''ö khö Zemaya andrö, banua Nehalama ba ba ma''uwunia mitou! Böi falukha ia [ma''uwu], si lö tebulö ba mbanua niha da''e, ba lö ikhamö nosonia zi sökhi andrö, ni''asogögu dania ba mbanuagu andre — iŵa''ö Yehowa — me no ifarou niha ba wolaŵa Yehowa.[11]', '["RazII 9:11; 25:18","Faigi 28:16"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 1, 'Taroma li, niŵa''ö Yehowa khö Yeremia; imane:', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 2, 'Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Tanö khöu ba zura fefu daroma li andrö, niŵa''ögu khöu.[1]', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 3, 'Hiza sa, irugi baŵa dania, — iŵa''ö Yehowa, ba ufaigi wangefa ba mbanuagu Iraono Gizeraeli, awö mado Yuda, iŵa''ö Yehowa, ba u''ohe mangawuli ira ba danö andrö, nibe''egu khö ndra tuara, ena''ö la''okhögö.', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 4, 'Ba da''ö daroma li andrö, niŵa''ö Yehowa ba khö Ndraono Gizeraeli ba ba mado Yuda:', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 5, 'Imane sa''ae Yehowa: Fe''ao sata''u ita tarongo; fanizi-nizi, ba lö fangorifi.', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 6, 'Mizofu-zofu ba mifaigi, na madono maö ndra matua! Ba hana wa u''ila lagogohe zolara dozi ira matua, hulö zadono? ba hana wa fatutu afusi mbawa![2]', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 7, 'Alai ita! baŵa sebua sa''ae mbaŵa da''ö, si lö famaedo, ba baŵa wa''atosasa ba ma''uwu Yakobo, ba — ni''efa''ö dania ira ba da''ö![3]', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 8, 'Na baŵa da''ö sa — iŵa''ö Yehowa ngahönö — ba urasa galo mbagi andrö khöra, ba mbagimi, ba u''etu''ö wesu khömi, ba lö tola sa''ae la''osawuyu ira [ma''uwu Yakobo andrö] niha bö''ö.', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 9, 'Enoni Lowalangira Yehowa sa''ae ira ba enoni razora andrö. Dawido, ni''asogögu khora.[4]', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 10, 'Ba ya''ugö enonigu ma''uwu Yakobo, ba böi ata''u''ö — iŵa''ö Yehowa — ba böi tokea''ö, ya''ugö Iraono Gizeraeli, u''efa''ö sa''ae ndra''ugö ba danö saröu ba u''efa''ö ma''uwumö ba danö andrö, ba ni''oloi''ö ya''ira, ena''ö mangawuli ma''uwu Yakobo, ena''ö ahono ira ba danö, ena''ö lö hadia ia ba lö ikeani ira niha.[5]', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 11, 'Lö''ö sa aefado khöu — iŵa''ö Yehowa — ba wangorifi ya''ugö. Uhori sa''ae fefu soi niha, ba nifazaewegu ya''ami, ba ya''ami, ba lö uhori; u''otu''ö ami ndrohu-ndrohu, lö tola lö''ö manö fotu.[6]', '["Fam 1:11","Faigi 4:31; 6:24","Yoel 2:11; Sef 1:15","Hez 34:23; Hos 3:5","Yes 41:13; 43:5","SamII 7:14; Yes 27:8; Faigi 4:27; 10:24"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 12, 'Imane sa Yehowa: No abölö-bölö wökhöu andrö ba si lö dalu-dalu zokhou!', '["Faigi 5:6","Yes 41:11; Faigi 10:25","Sin 103:3"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 13, 'Lö samatunö huhuomö — ba zokhou sanana andrö, ba lö famadöhö, lö dalu-dalu nifalemba khöu!', '["Faigi 5:6","Yes 41:11; Faigi 10:25","Sin 103:3"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 14, 'Dozi somasi ya''ugö mege, ba no olifu ira ndra''ugö: lö''ö manö ba dödöra ya''ugö, me no ubago ndra''ugö nifamago emali, me no u''otu''ö ndra''ugö nilangotu''ö safaito, ba wa''oya golalöŵau andrö, ba ba wa''afahöna horöu.', '["Faigi 5:6","Yes 41:11; Faigi 10:25","Sin 103:3"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 15, 'Hana wa mangarö-ngarö ndra''ugö ba zesokho andrö khöu, me no abölö-bölö wa''afökhö khöu? Börö wa''oya golalöŵau andrö ba fa''afahöna horöu, wa ulau khöu da''ö![7]', '["Faigi 5:6","Yes 41:11; Faigi 10:25","Sin 103:3"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 16, 'Ba ni''a dania dozi si manga ya''ugö, ba dozi samakao ya''ugö, ba ni''oloi''ö dania, fefu, ba dozi sangosindra''ui si so khöu, ba ube''e ni''osindra''ui si so khöra dania, ba dozi sorabu gama-gamau, ba ube''e nirabu![8]', '["Faigi 5:6","Yes 41:11; Faigi 10:25","Sin 103:3"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 17, 'Ufatöfa sa dania khöu dalu-dalu nifalemba, ufadöhö zesokho andrö khöu — iŵa''ö Yehowa — me "Nitibo''ö" labe''e töimö — "Siona si lö ba dödö niha"[9]', '["Faigi 5:6","Yes 41:11; Faigi 10:25","Sin 103:3"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 18, 'Imane Yehowa: Hiza, ufaigi wangazökhi ma''uwu Yakobo ba uhakhösi tödö nomora; ifuli tetaru''ö mbanua ba hilinia ba ifuli te''onahia gödo, si mane föna.[10]', '["Sin 126:1","Yes 35:10","Mikh 5:2","Faigi 24:7; 31:33","Faigi 23:19"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 19, 'Ba terongo moroi ba da''ö wangandrö saoha gölö, awö li za''iki, ba ato ira ube''e, böi awuwu wa''ato; ba ebua döira ube''e, böi itohugö, wa lö ba dödö niha bö''ö ira.[11]', '["Sin 126:1","Yes 35:10","Mikh 5:2","Faigi 24:7; 31:33","Faigi 23:19"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 20, 'Ba iraononia (iraono Yakobo) ba si mane föna, ba banuara, ba si lö tebulö fönagu, ba dozi samakao ya''ira, ba u''otu''ö.', '["Sin 126:1","Yes 35:10","Mikh 5:2","Faigi 24:7; 31:33","Faigi 23:19"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 21, 'Ba samatörö ya''ira, ba oi ya''ira, ba salaŵara, ba banuara. Ba utehe khönia we''amöi khögu, ena''ö i''ondrasi ndra''o — ha niha na sa zi lö ata''u mate ba wangondrasi ya''odo? — iŵa''ö Yehowa.[12]', '["Sin 126:1","Yes 35:10","Mikh 5:2","Faigi 24:7; 31:33","Faigi 23:19"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 22, 'Ba tobali banuagu ami, ba Lowalangimi ndra''odo![13]', '["Sin 126:1","Yes 35:10","Mikh 5:2","Faigi 24:7; 31:33","Faigi 23:19"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 23, 'Tesao sa''ae nangi sabölö khö Yehowa fönunia, angi sabe''e sibai; itörö högö zebua horö andrö:[14]', '["Sin 126:1","Yes 35:10","Mikh 5:2","Faigi 24:7; 31:33","Faigi 23:19"]', NULL),
  (3476353, 'OT', 'Yeremia', 30, 24, 'Lö alö wönu Yehowa andrö, irege no itörö nihonogöinia ibe''e, irege no ifalua — moroi furi dania aboto ba dödömi!', '["Sin 126:1","Yes 35:10","Mikh 5:2","Faigi 24:7; 31:33","Faigi 23:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476354, 'OT', 'Yeremia', 31, 1, 'Ba na luo da''ö — iŵa''ö Yehowa —, ba Lowalangi mado Gizeraeli fefu ndra''odo, ba banuagu ira.', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 2, 'Imane Yehowa: No falukha wa''ebua dödö ba danö si mate niha andrö, si lö ahori ba mbawa zi''öli. Talabu! ba wolohe ba wa''ahono Iraono Gizeraeli![1]', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 3, 'No i''oroma''ö ia khögu Yehowa, moroi ba zaröu, no imane: No u''omasi''ö ndra''ugö fa''omasi si lö mamalö-malö, andrö wa lö tebulö khöu wa''ebua dödögu andrö.', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 4, 'Ufuli u''a''azökhi ndra''ugö, ena''ö te''azökhi''ö, ya''ugö ono alawe, Iraono Gizeraeli. Ayau zui dania waritia andrö khöu, ena''ö fao ndra''ugö ba zanari!', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 5, 'Öfuli ölau kabu nagu ba hili Zamaria — samazökhi ya''ia, ba la''oguna''ö göi.', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 6, 'Irugi sa baŵa dania, ba mu''ao zanaro, ba hili Geferayi, lamane: "Talabu, möi ita misi yaŵa ba hili Ziona, khö Lowalangida Yehowa!"[2]', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 7, 'Imane sa Yehowa: Mi''anunö ba wa''omuso dödö, ba khö ma''uwu Yakobo, mikaraini wa''iki, börö högö soi andrö! Mi''ebua''ö li wanunö, mimane: Orifi mbanuau andrö, si tosai Iraono Gizeraeli, ya''ugö Yehowa!', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 8, 'Hiza, u''ohe mangawuli ira moroi yöu, u''ozaragö ira moroi ba wondrege danö — fao zi lö hörö ba sogombuyu-mbuyu töla ba sanabina ba sawena madono fefu: ato sibai ira, wangawuli ba da''e!', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 9, 'Mege-ege ira wa''aso ba fakao: ufasao ira, u''ohe ba gumbu; lala si fadaya nitörö, si tebai manendre ira; noa sa tobali ama Ndraono Gizeraeli ndra''odo ba si a''a nonogu mado Geferayi!', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 10, 'Mifondrondrongo li Yehowa, ya''ami niha baero, mi''ombakha''ö ba hulo misa, ba zaröu, mimane: Samazaewe mege Iraono Gizeraeli, da''ö göi zangozaragö, ba irorogö, si mane fondrorogö gubalo rorogöfönia!', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 11, 'Yehowa sa zangorifi ma''uwu Yakobo, i''efa''ö ba danga zabölö moroi khöra.[3]', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 12, 'Ba so ira ba manunö ba hili Ziona, lahurufai wa''ebua dödö Yehowa andrö, bua nowi ba ösi nagu ba fanikha ba ono mbiri-biri ba ono zaŵi, ba amaedola kabu si lö ambö idanö nosora, ba lö''ö sa''ae ariri ira.', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 13, 'Ba awena dania omuso dödö nono alawe ba wanari, fabaya ono matua ba satua fefu, ba ubali''ö fa''owua-wua dödö wa''abu dödöra andrö ba urara dödöra, omuso dödöra ube''e, aefa wa''alangu dödö andrö.', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 14, 'Ba ube''e fangokafu dödö gere dawö ba abuso mbanuagu fa''ebua dödögu andrö — iŵa''ö Yehowa.', '["MozII 33:14; Heb 4:9","Yes 2:3; Mikh 4:2","Yes 49:24"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 15, 'Imane Yehowa: Terongo li wangarö-ngarö ba Rama, fege-ege sabölö-bölö! — i''e''esi nononia Rakhela, ba lö irongo wondrara tödö, ba nononia andrö, me lö ya''ira sa''ae![4]', '["MozI 35:19,20; Mat 2:18","Sin Faigi 5:21"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 16, 'Imane Yehowa: Bato wege-ege, böi sa''ae mowöi daŵa höröu, so na sa mböli gölö, ba wa''erege dödöu andrö — iŵa''ö Yehowa: mangawuli dania ira moroi ba danö nemali.', '["MozI 35:19,20; Mat 2:18","Sin Faigi 5:21"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 17, 'So na sa dötönafö, ba götö dania khöu — iŵa''ö Yehowa: mangawuli dania ndraono ba danöra.', '["MozI 35:19,20; Mat 2:18","Sin Faigi 5:21"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 18, 'Urongo sa''ae wangarö-ngarö mado Geferayi: No ö''otu''ö ndra''odo, ba tebai utimba, hulö nono zaŵi, si lö mufamaha na, — tehe khögu wangawuli, ba mangawulido, me no Yehowa ndra''ugö, Lowalangigu![5]', '["MozI 35:19,20; Mat 2:18","Sin Faigi 5:21"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 19, 'Me noa sa''ae u''erogö ndra''ugö, ba mangesa dödögu, ba me no usöndra wa''aboto ba dödö, ba ubözi zolagu: ailado, aila sibai ndra''odo, ulu''i sa''ae wa''aila andrö, si otarai me iraono na ndra''odo.', '["MozI 35:19,20; Mat 2:18","Sin Faigi 5:21"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 20, 'Hadia, ono omasiö sa''ae khögu mado Geferayi, ono börö wa''omuso dödö, fa ifulifuli zui itörö tödögu, ha me uga göi fategudo khönia? Andrö humuluhulu bakha dödögu khönia — tebai lö uhakhösi tödö ia! — iŵa''ö Yehowa.', '["MozI 35:19,20; Mat 2:18","Sin Faigi 5:21"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 21, 'Taru''ö khöu dandra lala, taru''ö geu, töngöni döröŵa andrö, lala andrö, nitöröu, — fuli''ö, ya''ugö ono alawe, Iraono Gizeraeli, fuli''ö ba mbanua andre khöu!', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 22, 'Ha wa''ara na ö''ero''erogö, ya''ugö ono alawe si fa''ero? Si bohou sa ilau Yehowa ba guli danö: Ifohu ndra matua ira alawe![6]', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 23, 'Imane Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Ifuli lamane dania ba danö mado Yuda ba ba mbanua khöra, na no ufaigi wangefa khöra: "Yamufahowu''ö ndra''ugö Yehowa, ya''ugö nahia wa''atulö, ya''ugö hili ni''amoni''ö!"[7]', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 24, 'Ba monahia dania ba da''ö mado Yuda, fabaya banuara fefu, sonowi ba sakubaloi urifö.', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 25, 'U''okafui sa''ae dödö si no odufodufo, ba dozi sariri, ba abuso ube''e.', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 26, 'Ba tokeado ba da''ö ba ufakhölödo, ba no fangokafu dödögu wemörögu andrö![8]', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 27, 'Imane Yehowa: Hiza, irugi baŵa dania, ba ufazaewe danomö niha ba tanömö gurifö ba danö Ndraono Gizeraeli ba ba danö mado Yuda,', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 28, 'ba si mane me lö atage ndra''o, ba wangohori ba ba wamufu ba ba wanudugö, ba ba wamakiko ba ba wangalani [ya''ira], si manö göi dania wa lö atagedo ba wangazökhi ba ba wananö! — iŵa''ö Yehowa.[9]', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 29, 'Na luo da''ö, ba lö''ö sa''ae laŵa''ö: "Ira ama zi manga bua nagu si lakiritö, ba iraono zafuru boha."[10]', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 30, 'Ba horönia sa''ae mate zamösana; ha niha zi manga mbua nagu si lakiritö, da''ö zafuru boha.', '["Yoh 1:14; 17:23; Fam 21:2,3","Yes 11:9; Sakh 8:3","Sin 78:65","Faigi 1:10","Hez 18:2"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 31, 'Hiza, irugi baŵa dania — Iŵa''ö Yehowa — ba ulau fawu''u li ba ma''uwu Gizeraeli ba ba ma''uwu Yuda, fawu''usa li si bohou.[11]', '["Faigi 32:40; Heb 8:8–12","Faigi 24:7; 30:22; 32:38; Hez 11:19","Yes 54:13; Faigi 33:8; Mikh 7:18; Yoh 6:45; HalZin 10:43"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 32, 'Tenga si mane me fawu''u li ndra''o khö ndra tuara, me u''ohe dangara, ba wangeheta ya''ira ba danö Miserayi, fawu''usa li si no laböhöli, he ŵa''ae amaedola no u''owalu ira! — iŵa''ö Yehowa.', '["Faigi 32:40; Heb 8:8–12","Faigi 24:7; 30:22; 32:38; Hez 11:19","Yes 54:13; Faigi 33:8; Mikh 7:18; Yoh 6:45; HalZin 10:43"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 33, 'Da''ö sa wawu''usa li, na ulau fawu''u li ba ma''uwu Gizeraeli, na no aefa götö da''e — iŵa''ö Yehowa: Ube''e barö dotora goroisagu andrö, usura ba dödöra, ba Lowalangira ndra''odo ba banuagu ira.[12]', '["Faigi 32:40; Heb 8:8–12","Faigi 24:7; 30:22; 32:38; Hez 11:19","Yes 54:13; Faigi 33:8; Mikh 7:18; Yoh 6:45; HalZin 10:43"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 34, 'Ba lö''ö sa''ae ifahaö nawönia zamösana ba lö''ö sa''ae ifahaö dalifusönia sotalifusö, wanguma''ö: Ya aboto ba dödömi Yehowa! Noa sa''ae dozi ira zaboto ba dödö ya''odo, i''otarai wondrege ndraono, numalö ba wondrege zatua — iŵa''ö Yehowa —, ube''e aefa sa''ae khöra lalöra ba lö''ö sa''ae itörö tödögu horöra![13]', '["Faigi 32:40; Heb 8:8–12","Faigi 24:7; 30:22; 32:38; Hez 11:19","Yes 54:13; Faigi 33:8; Mikh 7:18; Yoh 6:45; HalZin 10:43"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 35, 'Imane Yehowa, sangohonogöi luo, ena''ö humaga ba zi ma''okho, awö lala mbaŵa ba lala ndröfi, ba wehaga ba zi bongi, samahufa asi, fa mu''ugu-ugu ndrulunia, — Yehowa ngahönö döinia, [imane]:[14]', '["MozI 1:16; Yes 51:15","Sin 72:5; Yes 6:13; Rom 11:25–27","Neh 3:1; Sakh 14:10"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 36, 'Si mane wa tebai awu''a fönagu nifakhoi andrö — iŵa''ö Yehowa —, si manö göi wa tebai tenga sa''ae soi fönagu ma''uwu Gizeraeli, götö-götö wa''ara.[15]', '["MozI 1:16; Yes 51:15","Sin 72:5; Yes 6:13; Rom 11:25–27","Neh 3:1; Sakh 14:10"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 37, 'Imane Yehowa: Si mane wa tebai tesu''a mbanua si yaŵa, awö wa tebai te''alui latalata danö andrö, tou, si manö göi wa tebai utibo''ö madou Gizeraeli ma''afefu, ba nilaura andrö fefu — iŵa''ö Yehowa!', '["MozI 1:16; Yes 51:15","Sin 72:5; Yes 6:13; Rom 11:25–27","Neh 3:1; Sakh 14:10"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 38, 'Hiza, irugi baŵa dania — iŵa''ö Yehowa — ba tetaru''ö zui mbanua khö Yehowa, i''otarai malige Hananeli andrö, irugi mbawa göli ba watalinga.[16]', '["MozI 1:16; Yes 51:15","Sin 72:5; Yes 6:13; Rom 11:25–27","Neh 3:1; Sakh 14:10"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 39, 'Ba latohugö, ladölö misa wanu''a, ba hili-hili Garebi andrö, ba laköi''ö, latuturu Goa.', '["MozI 1:16; Yes 51:15","Sin 72:5; Yes 6:13; Rom 11:25–27","Neh 3:1; Sakh 14:10"]', NULL),
  (3476354, 'OT', 'Yeremia', 31, 40, 'Ba daso gamatela andrö, ma''afefu, daso nawu andrö, benua andrö ma''asagörö, irugi mbombo Kendrona; ba tanö ba gatumbukha, irugi zinga mbawa göli kudo, ba ni''amoni''ö khö Yehowa: ba lö''ö sa''ae tefufu, lö''ö sa''ae tedudugö, irugi zi lö aetu.', '["MozI 1:16; Yes 51:15","Sin 72:5; Yes 6:13; Rom 11:25–27","Neh 3:1; Sakh 14:10"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 1, 'Taroma li Yehowa khö Yeremia, me no alua meziŵa fakhe Zedekia andrö, razo mado Yuda, döfi si feleŵalu khö Nebukanesa.', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 2, 'Me luo da''ö isuwö Yeruzalema razo Mbabeli; ba no mukuru Yeremia, sama''ele''ö, ba naha zago ba gödo razo mado Yuda.[1]', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 3, 'Noa sa ifakuru''ö ia Sedekia, razo mado Yuda, wanguma''ö: Hana wa ömane wama''ele''ö: Da''ö niŵa''ö Yehowa: Hiza, ube''e ba danga razo Mbabeli mbanua da''e, ena''ö atu''a ira.[2]', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 4, 'Ba Sedekia andrö, razo mado Yuda, ba lö zi lö lara''u Dawa Galedaia, lö zi lö tebe''e ba danga razo Mbabeli, ba fahuhuo ira ba fa''ila bawa.', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 5, 'Ba Mbabeli i''ohe Zedekia, ba ba da''ö ahono ia, irege ufuli utolo ia! — iŵa''ö Yehowa. Na fasöndra ami ba Ndrawa Geledaia, ba lö fozu.', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 6, 'Ba imane Yeremia: No humede khögu Yehowa, imane:', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 7, 'Lö ara tö, ba möi khöu Hanameli, ono namau Salumi, ba imane: Öli mbenuagu andrö ba Ganatoti, ya''ugö sa zi töla mananu, wowöli ya''ia.[3]', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 8, 'Ba so dana nonogu andrö, Hanameli, itörö niŵa''ö Yehowa, möi khögu ba naha zago andrö, imane khögu: Tema öli mbenuagu andrö, ba Ganatoti, ba danö niwada mado Mbeniyami, tola sa ya''ugö mokho, tola ösanu — öli ia khöu! Ba aboto ba dödögu, wa no li Yehowa;', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 9, 'ba u''öli mbenua andrö, ba Ganatoti, khö Hanameli, tana nonogu, ba utulo khönia mböli, felewitu ba rufia.', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 10, 'Ba ufazökhi zura ba ufotandrö ba u''asogö zi so ba mbörö ba utulo mböli, ba waliera.', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 11, 'Ba uhalö zura wowöli andrö, nifotandrö,', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 12, 'ba ube''e khö Mbarukhi, ono Neriya ono Mahaseya zura andrö, ba zi so Hanameli andrö, tana nonogu ba si so ba mbörö andrö, si no mame''e tandro tanga ba zura wowöli andrö, ba zi so mado Yuda fefu, si soso ba naha zago andrö.', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 13, 'Ba umane khö Mbarukhi andrö ba zi so ira:', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 14, 'Da''ö niŵa''ö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Halö zura wowöli andrö, nifotandro, ba si sagörö, si lö muduhö, ba öbe''e ba migö tanö, ena''ö ara manaha.', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 15, 'Imane sa Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Ifuli te''öli dania nomo ba benua ba kabu nagu ba danö andre!', '["RazII 25:1","Faigi 34:2","MozIII 25:25"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 16, 'Ba me no ube''e ba danga Mbarukhi andrö, ono Neriya, zura wowöli andrö, ba mangandrö ndra''o khö Yehowa, umane:', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 17, 'He So''aya, Yehowa, hiza, no ya''ugö zamazökhi banua si yaŵa ba tanö, ba wa''abölomö andrö si lö ambö, tangamö andrö, ni''oro''ö, zamazökhi — lö hadia ia zi tebai, khöu.[4]', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 18, 'Ba ngahönö ö''ebua''ö dödöu ba ösulöni lalö ndra ama ba gaheta ndraonora furira, ya''ugö Lowalangi sebua, si lö ambö fa''abölö, sotöi Yehowa ngahönö,[5]', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 19, 'sebua lala dödö ba sabölö ba wolau hadia ia, sanehe lala nono niha fefu, ba wanulöni ba zamösana, dali nitörönia andrö, awö lua-lua wolaunia.[6]', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 20, 'Si no mamazökhi tandra ba sahöli-höli dödö ba danö Miserayi, ba irugi ma''ökhö andre, he ba Ndraono Gizeraeli ba he ba niha baero, ba wangebua turiamö, si mane turiau ma''ökhö.', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 21, 'No öheta ba danö Miserayi mbanuamö Iraono Gizeraeli, wamazökhi tandra ba sahöli-höli dödö, tangau sabölö ba ta''iomö nifadölö, ba fao wameta''u, sabölö-bölö.[7]', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 22, 'Ba no öbe''e khöra danö andre, nifabu''umö fame''e, si möi''ö ba hölu, khö ndra tuara, tanö ba zi falawu susu ba ŵe ŵani.', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 23, 'Ba me no larugi, me no la''okhögö, ba lö la''o''ö goroisamö ba lö latörö nifakhoimö, ma''ifu lö la''o''ö niŵa''öu khöra ni''o''ö, andrö wa öfatörö khöra wamakao andrö fefu.', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 24, 'No irugi zinga mbanua fari andrö, ena''ö atu''a nemali, ba noa sa''ae mube''e ba danga Ndrawa Galedaia andrö, samasui ya''ia, mbanua, ba zi''öli ba ba lofo ba ba wökhö waba andrö; nidaö''ö-daö''ömö, ba no itörö, ba hiza, anehe ndra''ugö.', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 25, 'Ba noa zui öŵa''ö khögu, ya''ugö So''aya, Yehowa: Öli khöu mbenua andrö, be''e mböli ba asogö zi so ba mbörö! faudu wa tebe''e ba danga Ndrawa Geledaia mbanua.', '["MozI 18:14","MozII 34:7; Sin 79:12","Nga''ötII 16:9; Yes 28:29; Rom 2:6","SamII 7:23; Nga''ötI 17:21"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 26, 'Ba humede Yehowa khö Yeremia, imane:', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 27, 'Hiza, Yehowa ndra''odo, Lowalangi nösi guli danö fefu, — hadia, so maö hadia ia zi tebai, khögu?[8]', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 28, 'Andrö imane Yehowa: Hiza, ube''e ba danga Ndrawa Galedaia mbanua andre, ba danga Nebukanesa, razo Mbabeli, ena''ö atu''a ira.[9]', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 29, 'Ba Dawa Galedaia andrö, samasui banua andre, ba möi bakha dania ba latunu mbanua andre, akhozi labe''e, fabaya omo andrö, ba nitunura kumöyö khö Mba''ali, ba dete yaŵa, ba ba nibe''era sumange nibadu ba Lowalangi bö''ö, ba wangandrö fönugu.[10]', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 30, 'Iraono Gizeraeli ba mado Yuda, ba i''otarai iraono ira sa''ae, ba awai nilaura, ha si lö omasi ndra''o; lö aetu sa la''andrö wönugu Iraono Gizeraeli, ba nifazökhi dangara andrö — iŵa''ö Yehowa;', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 31, 'fangandrö wönugu ba fangandrö wa''abao dödögu sa''ae mbanua andre, i''otarai luo, me lataru''ö ia, irugi ma''ökhö andre, ena''ö uheta ia ba duduma hörögu,', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 32, 'börö walösökhi Ndraono Gizeraeli, fefu ba falösökhi mado Yuda, nilaura andrö, ba wangandrö fönugu, ya''ira ba razora ba satuara ba ere andrö ba sama''ele''ö khöra ba ira matua mado Yuda ba banua Yeruzalema.', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 33, 'No la''erogö ndra''o, lö ni''onahögöra ya''odo, ba he ŵa''ae lö sadage-dage ita, wamahaö ya''ira, ba lö''ö zui nifondrondrongora, ba wanöngöni fotu mena''ö.[11]', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 34, 'Sogoro ita andrö khöra sa''ae lafedadao ba gosali andrö, nifotöi khögu, ba wana''unöi ya''ia.[12]', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 35, 'Lafa''anö naha wame''e sumange khö Mba''ali ba ndraso Mbeni-Hinomo, ba wanunu onora matua ba onora alawe khö Molokho andrö, — si tenga niŵa''ögu khöra ba si lö irai itörö tödögu, folau sogoro ita andrö, ba wamowöhö mado Yuda, ba wamazökhi horö.', '["MozIV 16:22","Faigi 21:10","Faigi 19:13","Faigi 2:27; 7:13","Faigi 7:30; 23:11"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 36, 'Ba iya''e — ba andrö wa imane Yehowa, Lowalangi Ndraono Gizeraeli, ba mbanua andre, niŵa''ömi no mube''e ba danga razo Mbabeli ba zi''öli ba ba lofo ba ba wökhö waba andrö:', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 37, 'Hiza, u''ozaragö zui ira ba danö andrö fefu, ba nitibo''ögu ya''ira ba wönugu andrö ba ba mbakhu-bakhu dödögu ba ba wa''abao dödögu, si no abölö-bölö, ba u''ohe mangawuli ba naha da''e ba ahono ira ba da''e, lö hadia ia, ube''e.[13]', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 38, 'Ba banuagu dania ira ba Lowalangira ndra''odo.[14]', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 39, 'Ba ha sara dödöra ba ha sara lala nitörö, ube''e khöra, fa böi mamalö-malö wangata''ufira ya''odo, fangorifira ba fangorifi ndraonora, furira.', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 40, 'Ba ulau fawu''u li khöra, fawu''usa li si lö tebulö, fa lö ubödado khöra, ba wolau si sökhi khöra. Ba ube''e ba dödöra wangata''ufi ya''odo, fa böi fabali ira khögu.[15]', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 41, 'Börö wa''owua-wua dödögu sa''ae ira dania, ba wolau si sökhi khöra. Ba utanö ira ba danö andre, si ndruhu-ndruhu, moroi si''aikö ba dödögu ba moroi si''aikö ba gera-eragu.[16]', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 42, 'Imane sa Yehowa: Si mane famatörögu ba mbanua andre famakiko andrö fefu, si no abölö-bölö, si manö dania ufatörö khöra zi sökhi andrö fefu, nifabu''ugu khöra.', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 43, 'Ba lafuli la''öli mbenua ba danö andre, niŵa''ömi: "Tanö si mate, lö niha ba lö urifö! no mube''e ba danga Ndrawa Galedaia!"', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476355, 'OT', 'Yeremia', 32, 44, 'La''öli dania mbenua, labe''e mböli, lafazökhi zura wowöli ba lafotandro ba la''asogö zi so ba mbörö, ba danö mado Mbeniyami ba ba zi fasui Yeruzalema ba ba mbanua mado Yuda ba ba mbanua ba hili ba ba mbanua ba ndraso ba ba mbanua raya: u''ohe sa mangawuli ni''oloi''ö andrö khöra! — iŵa''ö Yehowa.', '["Faigi 29:14","Faigi 34:7; 30:22","Faigi 31:31 b.t.","Amos 9:15"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 1, 'Ba humede Yehowa khö Yeremia, samuza tö, me ba gurunga na so ia, ba naha zago, imane:[1]', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 2, 'Da''ö niŵa''ö Yehowa, solau, Yehowa sogoi tödönia, ba wamalua — Yehowa döinia —, imane:', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 3, 'Angaröfi li ndra''o, ba utema liu, ba u''ombakha''ö khöu zebua, si tebai aboto ba dödö niha, si lö örai örongo.', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 4, 'Imane sa Yehowa, Lowalangi Ndraono Gizeraeli, ba nomo ba mbanua andre ba ba gödo razo mado Yuda, nidudugö, lua-lua fari andrö ba lua-lua zi''öli.', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 5, 'So zi möi fasöndra ba Ndrawa Galedaia ba lafo''ösi [nomo andrö] boto niha si mate, nibunugu ba wönugu andrö ba ba mbakhu-bakhu dödögu; börö walösökhira fefu, wa no ubini''ö mbawagu ba mbanua andre.', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 6, 'Hiza, ufatöfa khönia dalu-dalu nifalemba, famadöhö; ufadöhö zokhora ba uböla''ö khöra wangorifi, si fahöna, ba si lö mamalö-malö.', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 7, 'Ba u''ohe mangawuli ni''oloi''ö andrö, mado Yuda ba Iraono Gizeraeli, ufuli u''a''azökhi ira, si mane föna.[2]', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 8, 'Ba uhaogö ira, uheta golalöŵara fefu, lalöra khögu; ube''e aefa khöra zalara fefu, salara khögu, me lalaŵa ndra''odo.[3]', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 9, 'Ena''ö turiagu omasiö ba fanuno ya''odo ba lakhömigu ia (mbanua andrö) ba niha ba guli danö fefu, sogikhi tödö dania ba sanizi-nizi ba zi sökhi andrö ba ba wangorifi andrö fefu — na larongo — nibe''egu khöra.', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 10, 'Imane Yehowa: Ba naha andre niŵa''ömi: "Tanö si mate, lö niha, ba lö urifö!" ba ba mbanua mado Yuda misa ba baewali Yeruzalema, si no asai''ö, si lö niha-niha: lö niha ba lö urifö,[4]', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 11, 'ba terongo zui wa''iki ba wa''owua-wua dödö ba ba wa''omuso dödö ba li zangowalu ba li nono nihalö ba fanunö zangumaö: "Nisuno Yehowa ngahönö; si sökhi tödö sa Yehowa, si lö aetu sa wa''ebua dödönia andrö," solohe ba gosali Yehowa sumange fangandrö saoha gölö: me ube''e mangawuli ni''oloi''ö andrö, si otarai danö da''e, ena''ö si mane föna — iŵa''ö Yehowa.[5]', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 12, 'Imane Yehowa ngahönö: Ba naha da''e, si no tanö si mate, si lö niha ba si lö urifö, ba ba mbanua khönia fefu, ba ifuli dania monaha gubalo, sokubaloi urifö.', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 13, 'Ba ba mbanua ba hili ba ba mbanua ba ndraso ba ba mbanua raya ba ba danö mado Mbeniyami, ba ba zi fasui Yeruzalema ba ba mbanua mado Yuda misa, ba ifuli latörö dania zangofaya ya''ira biri-biri, iŵa''ö Yehowa.', '["Faigi 32:2","Faigi 24:6","Faigi 31:34","Faigi 32:43","Faigi 7:34; Sin 136:1"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 14, 'Hiza, irugi baŵa dania — iŵa''ö Yehowa — ba alua ube''e zi sökhi andrö, niŵa''ögu, ba khö ma''uwu Gizeraeli ba ba khö ma''uwu Yuda:[6]', '["Faigi 23:5,6; 29:10","Yes 4:2; KorI 1:30","Sin 89:30"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 15, 'Na luo da''ö ba na götö da''ö, ba tumbu madou khö Dawido, ube''e, madou satulö, ena''ö ifaigi lala ba satulö, ba danö![7]', '["Faigi 23:5,6; 29:10","Yes 4:2; KorI 1:30","Sin 89:30"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 16, 'Na luo da''o, ba te''orifi mado Yuda, ba ahono Yeruzalema, lö hadia ia, ba töinia dania [töi Yeruzalema], ba: "Fa''atulöda Yehowa".', '["Faigi 23:5,6; 29:10","Yes 4:2; KorI 1:30","Sin 89:30"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476356, 'OT', 'Yeremia', 33, 17, 'Imane sa Yehowa: Lö tola ambö khö Dawido [ma''uwu], sidadao ba dadaoma razo ba ma''uwu Gizeraeli,[8]', '["Faigi 23:5,6; 29:10","Yes 4:2; KorI 1:30","Sin 89:30"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 18, 'ba ba gere, mado Lewi andrö, ba lö tola ambö [ma''uwu], si so fönagu, same''e sumange nitunu ba sanunu sumange ni''a ba sangasiwai sumange nitaba, si lö mamalö-malö.', '["Faigi 23:5,6; 29:10","Yes 4:2; KorI 1:30","Sin 89:30"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 19, 'Ba humede Yehowa khö Yeremia, imane:', '["Faigi 31:36"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 20, 'Da''ö niŵa''ö Yehowa: Na mi''ila miwu''ai nifakhoigu lala zi ma''ökhö ba nifakhoigu lala zi bongi, fa böi sa''ae moluo ba fa böi sa''ae bongi, ba ginötönia,[9]', '["Faigi 31:36"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 21, 'ba uwu''ai göi wawu''usa li andrö khögu, khö genonigu Dawido, fa böi sa''ae so khönia ma''uwu, sidadao ba dadaomania, samatörö, ba fawu''usa li andrö khögu ba mado lewi ere andrö, enonigu.', '["Faigi 31:36"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 22, 'Si mane ngahönö andrö, ba mbanua si yaŵa, si tebai te''erai, awö nene ba mbewe nasi, si tebai tesu''a, si manö göi wa tebai te''erai ma''uwu genonigu Dawido, ube''e, ba si manö nono Lewi andrö, si möi enonigu.', '["Faigi 31:36"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 23, 'Ba humede Yehowa khö Yeremia, imane:', '["Faigi 31:36"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 24, 'Hadia, lö aboto ba dödöu niŵa''ö-ŵa''ö niha andrö, wanguma''ö: Mado andre, si dombua, nitutuyu Yehowa, ba no itibo''ö! ba no lö ba dödöra mbanuagu andrö, irege tenga sa''ae banua wamaigira?', '["Faigi 31:36"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 25, 'Imane Yehowa: Na lö nifakhoigu lala ba zi ma''ökhö ba ba zi bongi, ba na lö nihonogöigu sinörö ba mbanua si yaŵa ba ba danö si tou,', '["Faigi 31:36"]', NULL),
  (3476356, 'OT', 'Yeremia', 33, 26, 'ba utibo''ö göi ma''uwu Yakobo ba ma''uwu genonigu Dawido andrö, fa lö''ö sa''ae uhalö ma''uwunia samatörö ma''uwu ndra Aberahamo, Iza''aki, Yakobo; ufaigi sa wangefa khöra ba uhakhösi tödö ira.', '["Faigi 31:36"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 1, 'Niŵa''ö Yehowa khö Yeremia, me isuwö Yeruzalema ba banua ba ngaira Nebukanesa, me no i''ohe zabölö khönia fefu, awö fefu nöri ba guli danö, si so barö mbawania, awö fefu soi niha, imane Yehowa:[1]', '["RazII 25:1 b.t.; Faigi 52:4","Faigi 21:10; 32:29","Nga''ot. II. 16:14"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 2, 'Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Ae ŵa''ö khö Zedekia andrö, razo mado Yuda, ömane khönia: Da''ö niŵa''ö Yehowa: Hiza, ube''e ba danga razo Mbabeli mbanua da''e, ena''ö itunu.[2]', '["RazII 25:1 b.t.; Faigi 52:4","Faigi 21:10; 32:29","Nga''ot. II. 16:14"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 3, 'Ba ya''ugö, ba si tebai aefa ba dangania; lö zi lö lara''u ndra''ugö ba lö zi lö labe''e''ö ba dangania, ba fa''ila bawa ndra''ugö khö razo Mbabeli andrö, ba fahuhuo ami ba te''ohe ba Mbabeli ndra''ugö!', '["RazII 25:1 b.t.; Faigi 52:4","Faigi 21:10; 32:29","Nga''ot. II. 16:14"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 4, 'Ba fondrondrongo li Yehowa, ya''ugö Sedekia, razo mado Yuda: Imane Yehowa, ba khöu andre: Lö tola labunu ndra''ugö;', '["RazII 25:1 b.t.; Faigi 52:4","Faigi 21:10; 32:29","Nga''ot. II. 16:14"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 5, 'ba wa''ahono-hono mate ndra''ugö, ba si mane fanunura samohua khö ndra amau, razo mege, fönau, si manö göi latunu khöu dania ba la''e''esi ndra''ugö, lamane: "Alai ndra''o ndra''ugö, salaŵa!" me no umanö wanguma''ö — iŵa''ö Yehowa.[3]', '["RazII 25:1 b.t.; Faigi 52:4","Faigi 21:10; 32:29","Nga''ot. II. 16:14"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 6, 'Ba ifa''ema khö Zedekia, razo mado Yuda, Yeremia sama''ele''ö daroma li da''ö, ba Yeruzalema,', '["RazII 25:1 b.t.; Faigi 52:4","Faigi 21:10; 32:29","Nga''ot. II. 16:14"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 7, 'me luo lasuwö Yeruzalema sabölö khö razo Mbabeli, ba bö''önia fefu, si tosai banua mado Yuda, Lakhisi andrö ba Aseka; hatö sa da''ö zi tosai banua saro, ba mado Yuda.', '["RazII 25:1 b.t.; Faigi 52:4","Faigi 21:10; 32:29","Nga''ot. II. 16:14"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 8, 'Niŵa''ö Yehowa khö Yeremia, me no mamagölö razo, Sedekia, ba zato mbanua Yeruzalema fefu, ba wamarongogö fangefa khöra,[4]', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 9, 'ena''ö i''efa''ö zawuyunia ira matua ba sawuyunia ira alawe, Heberaio, zamösana, fa lö tola i''osawuyu niwara, ma''uwu Yuda, zamösana.', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 10, 'Ba la''o''ö satua fefu ba sato fefu, sanehe mege famagölö andrö, dozi la''efa''ö zawuyura ira matua, ba sawuyura ira alawe, lö''ö sa''ae la''osawuyu; la''o''ö, la''efa''ö.', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 11, 'Ba aefa da''ö, ba lahalö mangawuli zawuyu ira matua ba sawuyu ira alawe, ni''efa''öra, la''anösö''ö wangosawuyu.', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 12, 'Ba humede Yehowa khö Yeremia, imane:', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 13, 'Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: No fawu''u li ndra''o khö ndra tuami, me uheta ira ba danö Miserayi ba danö ni''osawuyu ya''ira, wanguma''ö;', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 14, '"Na irugi mewitu fakhe, ba yamu''efa''ö dalifusönia Heberaio zamösana, na so zi no mamawa ya''ia khönia; meönö fakhe sawuyumö ia ba na aefa ö, ba ö''efa''ö ia!" Ba lö lafondrondrongo ligu ira tuami, lö labe''e mbörö dalingara.[5]', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 15, 'Ba no mifalalini gera-erami ma''ökhö, no mi''o''ö zatulö khögu, me no mifarongogö wangefa, ba nawömi, ba me no mamagölö ami fönagu, ba gosali andrö, si no fao ba döi töigu.', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 16, 'Ba iya''e, ba no mifuli mibe''e ra''iö döigu, me ihalö mangawuli zawuyunia ira matua ba sawuyunia ira alawe zamösana, sawuyumi, si no mifalua fangefa''ö; me no mifuli mi''anösö''ö wangosawuyu ya''ira.', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 17, 'Andrö imane Yehowa: Lö nifondrondrongomi ligu, ba wamarongogö fangefa ba dalifusömi, ba nawömi andrö, dozi ami — ba hiza, ya''odo zamarongogö khömi fangefa, ululu ami ba mbawa zi''öli ba ba wökhö waba ba ba lofo, ba ube''e nifakao ami, dozi soi niha ba guli danö zamakao ya''ami.', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 18, 'Ululu zi no manawö nifakhoigu andrö ba si lö molo''ö famagölö andrö, famagölöra fönagu, me lafabali nono zaŵi andrö, ba wanörö atalua,[6]', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 19, 'satua mado Yuda ba satua mbanua Yeruzalema ba enoni razo yomo ba ere ba sato ba danö fefu, si no manörö otalua nono zaŵi nifabali andrö: —', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 20, 'ube''e ba danga nemalira ira, ba danga zangalui famunura, ba ö wofo ba dalu mbanua ba ö gutu ndru''u dania mbotora.[7]', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 21, 'Manö Zedekia andrö, razo mado Yuda ba kumandru sebua andrö khönia: ube''e ba danga nemalira, ba danga zangalui famunura, ba danga zabölö andrö khö razo Mbabeli, si no aheta ba khömi [iada''e].', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476357, 'OT', 'Yeremia', 34, 22, 'Hiza, muhededo khöra — iŵa''ö Yehowa — u''ohe mangawuli ira ba mbanua da''e, ena''ö lasuwö ba ena''ö atu''a ira, ba ena''ö latunu, ba ubali''ö tanö si mate mbanua mado Yuda, fa böi sa''ae monahia bakha niha.', '["MozII 21:2; MozV 15:12","MozIII 25:39 b.t.","MozI 15:10,17","Faigi 7:33"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 1, 'Niŵa''ö Yehowa khö Yeremia, me luo razo mado Yuda Yoyaki andrö, ono Yosia,', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 2, 'imane: Ae ba ma''uwu Rekhabi andrö ba hede khöra, ba ohe ira ba gosali Yehowa, ba mbate''e andrö zambua ba be''e öra nagu.[1]', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 3, 'Ba humededo khö Yasania andrö, ono Yeremia ono Habasinia, ba ba dalifusönia ba ba ndraononia fefu ba ba watalifusöta ma''uwu Rekhabi andrö fefu.', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 4, 'Ba u''ohe ba gosali Yehowa ba mbate''e ndraono Hanani andrö, ono Yigidalia, enoni Lowalangi, ba ngai mbate''e zatua andrö, yaŵa mbate''e Maseya, ono Zalumi, sanaro ba mbawandruhö.', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 5, 'Ba ufa''oli migö ba mako, si so agu yaŵa ba ma''uwu Rekhabi andrö, ba umane khöra: Mibadu nagu!', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 6, 'Ba lamane: Lö mabadu nagu! noa sa i''oroi''ö khöma tuama Yonadabi, ono duama Rekhabi, furugöma, imane: "Böi manö mibadu nagu ba he iraonomi,[2]', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 7, 'ba böi milau nomo ba böi manaru [fakhe] ami ba böi mifazökhi kabu nagu, böi so khömi zi manö; ba nose soso ami, sagötö ya''ami, ena''ö anau nosomi ba danö, ba zi so ami si fatewu!"[3]', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 8, 'Ba no ma''o''ö goroisa wurugöma Yonadabi andrö, ono duama Rekhabi, fefu hadia ia ni''oroi''önia khöma, wa lö mabadu nagu, sagötö ya''aga, he yaga''a ba he ira alawema ba he onoma matua ba he onoma alawe,', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 9, 'awö wa lö malau nomo khöma, nahiama, wa lö mafazökhi kabu nagu, wa lö mangahalöga, wa lö bolo nowi khöma.', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 10, 'Ba tobali ba nose sosoga, molo''ö ndra''aga, matörö ni''oroi''ö wurugöma Yonadabi khöma, fefu.', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 11, 'Ba me irugi danöda Nebukanesa razo Mbabeli, ba mamane: "Talabu, talau moloi ba zabölö Ndrawa Galedaia andrö ba ba zabölö Garamo, tasaŵa Yeruzalema!" andrö soga ba Yeruzalema.[4]', '["Nga''ötI 2:55","RazII 10:15","MozII 20:12","RazII 24:1"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 12, 'Ba humede Yehowa khö Yeremia,', '["Faigi 7:25; 11:7; 25:3","Faigi 33:17"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 13, 'imane: Da''ö niŵa''ö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Ae hede ba mado Yuda ba ba mbanua Yeruzalema, ömane: Hadia, lö mitöngöni wotu, ba wamondrongo ligu ena''ö? iŵa''ö Yehowa.', '["Faigi 7:25; 11:7; 25:3","Faigi 33:17"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 14, 'Oroisa Yonadabi andrö, ono Rekhabi, ni''oroi''önia ba ma''uwunia, fa böi labadu nagu, ba no mu''o''ö; irugi ma''ökhö andre lö nibadura, wolo''ö oroisa wurugöra andrö: ba no lö sadage-dagedo fehede khömi, ba lö nifondrondrongomi khögu.[5]', '["Faigi 7:25; 11:7; 25:3","Faigi 33:17"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 15, 'Ba lö sadage-dagedo famatenge khömi enonigu andrö fefu, sama''ele''ö, ba wanguma''ö khömi: Mifuli ami, yamuröi lalania si lö sökhi andrö zamösana ba mihaogö mbua-buami ba böi mi''o''ö ba Lowalangi bö''ö, ba wamosumange ya''ira, ba lö tebulö ami ba danö, nibe''egu khömi ba khö ndra tuami! — ba lö nibe''emi börö dalingami, lö nifondrondrongomi khögu.', '["Faigi 7:25; 11:7; 25:3","Faigi 33:17"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 16, 'Ma''uwu Yonadabi andrö, ono Rekhabi ba no la''o''ö goroisa wurugöra, ni''oroi''önia khöra; ba niha da''e, ba lö nifondrondrongora khögu.', '["Faigi 7:25; 11:7; 25:3","Faigi 33:17"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 17, 'Andrö imane Yehowa, Lowalangi ngahönö, Lowalangi Ndraono Gizeraeli: Hiza, ufatörö sa''ae ba ma''uwu Yuda ba ba mbanua Yeruzalema wamakiko andrö fefu, nidaö''ö-daö''ögu khöra, me no humededo khöra, si lö famondrongo, ba me no mu''aodo khöra, si lö fanema li.', '["Faigi 7:25; 11:7; 25:3","Faigi 33:17"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 18, 'Ba ba watalifusöta ma''uwu Rekhabi, ba imane Yeremia: Da''ö niŵa''ö Yehowa ngahönö. Lowalangi Ndraono Gizeraeli: Me no mi''o''ö goroisa wurugömi Yonadabi, me no mitöngöni ni''oroi''önia andrö fefu ba me no ahori mitörö niŵa''önia khömi, ba imane Yehowa ngahönö,', '["Faigi 7:25; 11:7; 25:3","Faigi 33:17"]', NULL),
  (3476358, 'OT', 'Yeremia', 35, 19, 'Lowalangi Ndraono Gizeraeli: Lö tola ambö khö Yonadabi andrö, ono Rekhabi, [ma''uwu] si so fönagu [enonigu].[6]', '["Faigi 7:25; 11:7; 25:3","Faigi 33:17"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 1, 'Dofi si öfa khö Yoyaki ono Yosia, razo mado Yuda, ba humede Yehowa khö Yeremia,', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 2, 'imane: Halö garate, ba sura daroma li andrö fefu, niŵa''ögu khöu, nitandrösaigö ba Ndraono Gizeraeli ba ba mado Yuda, ba ba soi bö''ö fefu, i''otarai luo andrö, me awena humededo khöu, me luo Yosia, irugi ma''ökhö andre.[1]', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 3, 'Ma atö labe''e ba dödöra ma''uwu Yuda wamakiko andrö fefu, si so ba dödögu nifatörö khöra, ma atö iröi lalania si lö sökhi andrö zamösana, ma lafuli ira, ba ube''e aefa khöra lalöra, awö horöra.', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 4, 'Ba humede Yeremia khö Mbarukhi andrö, ono Neriya, ba i''anura''ö Barukhi, igo''ögo''ö niŵa''ö-ŵa''ö Yeremia khönia, fefu daroma li Yehowa, niŵa''önia khönia, itanö ba zura.', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 5, 'Ba noa da''ö, ba iŵa''ö li khö Mbarukhi Yeremia, imane: So rörögu, tebai möido ba gosali Yehowa;', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 6, 'ba ae''e, ya''ugö andre, ba baso zura andrö, nisuramö, wolo''ölo''ö niŵa''ö-ŵa''ögu khöu, taroma li Yehowa andrö; farongogö ba zato ba gosali Yehowa, na baŵa wamoni; ba ba mado Yuda fefu, si no möi ba da''ö, moroi ba mbanuara misa,', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 7, 'farongogö wombaso, ma atö lakao khö Yehowa, wangide-ide''ö ya''ira, ma iröi lalania andrö si lö sökhi zamösana, ma lafuli ira: noa sa ebua wönu Yehowa ba bakhu-bakhu dödönia, fameta''u Yehowa niha andre.', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 8, 'Ba i''o''ö Barukhi, ono Neriya, fefu niŵa''ö Yeremia, sama''ele''ö, khönia, ibaso daroma li Yehowa, si so ba zura andrö, ba gosali Yehowa.', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 9, 'Ba me döfi si lima khö Yoyaki, ono Yosia, razo mado Yuda, me baŵa si siŵa, ba te''oroi''ö wamoni föna Yehowa ba mbanua Yeruzalema fefu ba ba mbanua bö''ö fefu, si möi ba Yeruzalema, moroi ba mbanua mado Yuda misa.', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 10, 'Ba ibaso huhuo Yeremia andrö Barukhi, ba gosali Yehowa, ba golayama khö Gemaria, ono Zafano, durutuli, ba golayama föna, si yaŵa, ba zinga mbawa göli si bohou, ba gosali Yehowa, ifarongogö wombaso sura andrö, ba niha sato fefu.[2]', '["Yes 8:1; Faigi 1:2; 35:3; 30:2","RazII 22:3; Faigi 26:10"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 11, 'Ba me no irongo Mikhaya, ono Gemaria ono Zafano, daramo li Yehowa fefu, ba zura andrö,', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 12, 'ba möi ia mitou ba gödo razo ba kato durutuli, ba no falukha ba da''ö zalaŵa fefu, ira Elisama, durutuli, Delaya, ono Zemaya ba Elinatano, ono Nakhiboro, ba Gemaria, ono Zafano, ba Sedekia, ono Hanania, ba satua bö''ö, fefu.[3]', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 13, 'Ba i''ombakha''ö khöra Micbaya fefu nirongonia, me ifarongogö ba niha sato Barukhi wombaso sura andrö.', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 14, 'Ba lafatenge Yudi salaŵa andrö fefu, Yudi ono Natania ono Zelemia ono Khusi, lafatenge khö Mbarukhi, wanguma''ö: Ohe zura andrö, nifarongogöu ba zato ba ae khöma! Ba i''ohe zura andrö Barukhi, ono Neriya, möi ia khöra.', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 15, 'Ba lamane khönia: Dadao, ba farongogö khöma! Ba ifarongogö khöra Barukhi.', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 16, 'Ba me no larongo daroma li andrö fefu, ba faoma lafaigi mbawa nawöra, no tobali dödöra, ba lamane khö Mbarukhi andrö: Nifarongogö khö razo da''ö fefu!', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 17, 'Ba lasofu khö Mbarukhi, lamane: Tunö khöma, he öwisa wanura taroma li andrö, ni''ombakha''önia khöu.', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 18, 'Imane khöra Barukhi: Iŵa''ö-ŵa''ö khögu daroma li andre fefu, ba utanö ba zura, taŵa.', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 19, 'Ba lamane satua, khö Mbarukhi: Ae bini''ö ndra''ugö, awö Yeremia, ena''ö lö sangila heza so ami.', '["Faigi 26:22"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 20, 'Ba möi ira khö razo, ba golayama me no la''irö''ö zura andrö ba kato durutuli Elisama, ba la''ombakha''ö khö razo da''ö no mege fefu.', '[]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 21, 'Ba ifatenge Yudi razo, ba wangai sura andrö, ba ihalö ba kato durutuli Elisama. Ba ibaso Yudi, ifarongogö khö razo ba ba zatua andrö, fefu, si so ba ngainia.', '[]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 22, 'Ba ba nahania na baŵa deu so razo — baŵa si siŵa —, no so galitö fönania.', '[]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 23, 'Ba ero na no tölu irege öfa ngaroro ibaso Yudi, ba itaba razo ladawa ba itibo''ö ba galitö, irege no ahori akhozi zura andrö.', '[]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 24, 'Ba lö tokea razo, ba he enoninia andrö fefu, samondrongo taroma li andrö fefu, lö lasika nukhara.', '[]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 25, 'Ba he ŵa''ae la''andrö khö razo ira Elinatano, Delaya ba Gemaria, böi yamutunu zura andrö, ba lö''ö zui ifondrondrongo khöra.', '[]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 26, 'Iŵa''ö na''i khö Yeramieli, ono razo ba khö ndra Seraya, ono Gaserieli, Selemia, ono Gabideli, lakaoni durutuli Barukhi ba Yeremia sama''ele''ö — ba no ibini''ö ira Yehowa.', '[]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 27, 'Ba humede Yehowa khö Yeremia, me no aefa itunu razo zura andrö, ifabaya taroma li andrö, nisura Mbarukhi, ni''ombakha''ö Yeremia khönia, imane Yehowa:', '["Faigi 22:19"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 28, 'Halö garate bö''ö, ba sura yaŵa daroma li andrö, si mane mege, si so ba zura si föföna andrö, nitunu Yoyaki, razo mado Yuda.', '["Faigi 22:19"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 29, 'Ba ba khö Yoyaki andrö, razo mado Yuda, ba ömane: Da''ö niŵa''ö Yehowa: No ötunu zura andrö, wanguma''ö: Hana wa ötanö bakha: "Lö zi lö möi razo Mbabeli, ba wamufu tanö da''e ba ba wangohori ba danö niha, fabaya uriföra?"', '["Faigi 22:19"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 30, 'Andrö imane Yehowa ba khö Yoyaki andrö, razo mado Yuda: Lö nga''ötönia dania, sidadao ba dadaoma Dawido andrö, ba so tou dania mbotonia, ba zino, na ma''ökhö, ba ba wa''oafu, ba zi bongi.[4]', '["Faigi 22:19"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 31, 'Ba usulöni ba khönia ba ba ma''uwunia ba ba genoninia andrö lalöra, ba ba mbanua Yeruzalema ba ba mado Yuda, ba ufatörö wamakiko andrö fefu, nidaö''ö-daö''ögu khöra, lö lai wa lö nifondrondrongora.', '["Faigi 22:19"]', NULL),
  (3476359, 'OT', 'Yeremia', 36, 32, 'Ba ihalö garate bö''ö, ibe''e khö durutulinia Barukhi, ono Neriya, ba itanö bakha da''ö fefu nösi zura andrö, nitunu Yoyaki razo mado Yuda, igo''ögo''ö niŵa''ö-ŵa''ö Yeremia khönia — ba oya lanönö na huhuo bö''ö, huhuo si manö göi.', '["Faigi 22:19"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 1, 'Ba razo fangali Yoyakhi andrö, ono Yoyaki, Zedekia, ono Yosia, nifataro Nebukanesa, razo Mbabeli, razo ba danö mado Yuda.[1]', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 2, 'Ba lö lafondrondrongo li Yehowa andrö, nifaŵa''ögönia khö Yeremia sama''ele''ö, he ya''ia ba he enoninia ba he niha ba danö.', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 3, 'Ba ifatenge khö Yeremia sama''ele''ö razo Sedekia, — Yukhala, ono Zelemia, ba Sefania ere andrö, ono Maseya zinenge —, wanguma''ö: "Angandrö khö Yehowa, Lowalangida, salahima!"', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 4, 'Me luo da''ö, ba idörö-döröi na mbanua Yeremia, lö mukuru na.', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 5, 'Ba barö ö, ba so moroi sa zanuwö khö Wara''o, moroi ba danö Miserayi, ba me terongo da''ö ba Ndrawa Galedaia, ba laheta ira, labato wanuwö Yereozalema.', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 6, 'Ba humede Yehowa khö Yeremia, sama''ele''ö imane:', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 7, 'Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli: Mimane khö razo mado Yuda, samatenge ya''ami, ba wanofu khögu: Sanuwö andrö khö Wara''o, si so moroi sa, ba wanolo ya''ami, ba mangawuli ba danöra, tanö Miserayi,', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 8, 'ba sangawuli göi Ndrawa Galedaia andrö, ba wanuwö banua da''e, ena''ö atu''a ira ba ena''ö latunu.[2]', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 9, 'Da''ö niŵa''ö Yehowa: Böi milimo ami, wanguma''ö tödömi: "Alua laheta ira khöda Dawa Galedaia andrö!" lö''ö sa laheta ira.', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 10, 'He ŵa''ae milaŵa ena''ö zabölö Ndrawa Galedaia andrö fefu, sanuwö ya''ami, ba he ha mato ma''ifu zi tosai, si no mesokho sibai na''i, ba ifazaŵa zui ia zamösana ba nosenia ba latunu mbanua da''e.', '["RazII 24:17","Faigi 34:22"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 11, 'Ba me no laheta ira ba Yeruzalema sabölö Ndrawa Galedaia andrö, ba zanuwö andrö khö Wara''o,', '[]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 12, 'ba iröi Yeruzalema Yeremia ba we''amöi ba danö mado Mbeniyami, ba wangai urakhania ba da''ö, fao ia ba niha [bö''ö].', '[]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 13, 'Ba me irugi mbawa göli mado Mbeniyami andrö, khö zanaro sotöi Yeria, ono Zelemia ono Hanania, ba itaha Yeremia sama''ele''ö da''ö, imane: "Ba Ndrawa Galedaia möi ndra''ugö!"', '[]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 14, 'Ba imane Yeremia: Faya! Tenga si möi ba Ndrawa Galedaia ndra''odo; ba i''ositengagö. Ba itema ira''u Yeremia Yeria andrö, i''ohe ba zatua.', '[]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 15, 'Ba mofönu zatua khö Yeremia, labago ia ba labe''e ba gurunga ba nomo Yonata durutuli; noa sa labali''ö kurunga da''ö.', '[]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 16, 'Ba tobali labe''e ba gurunga barö danö Yeremia, ba nibale kara moroi yaŵa; ba ara ia ba da''ö.', '[]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 17, 'Ba ifatenge khönia razo, Sedekia, ifahalö''ö ia. Ba isofu khönia razo ba gödonia, nibini''ö, imane: Hadia, so khöu daroma li Yehowa? Ba imane Yeremia: So! ba imane: Ba danga razo Mbabeli tebe''e ndra''ugö!', '["Faigi 22:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476360, 'OT', 'Yeremia', 37, 18, 'Ba imane na Yeremia khö Zedekia, razo: Hadia horögu khöu ba ba genoniu andre, wa no mibe''edo ba gurunga?', '["Faigi 22:2"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 19, 'Ba heza so iada''e zama''ele''ö andrö, sangombakha khömi, wanguma''ö: "Lö irugi ami razo Mbabeli ba lö irugi danö andre!" —?', '["Faigi 22:2"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 20, 'Ba iada''e, ba fondrondrongo ya''ugö sokhö ya''o, razogu! Fondrondrongo wangandrögu! Böi be''e mangawuli ndra''o ba nomo Yonata durutuli andrö, fa böi matedo ba da''ö!', '["Faigi 22:2"]', NULL),
  (3476360, 'OT', 'Yeremia', 37, 21, 'Ba iŵa''ö razo Sedekia, ba naha zago la''ohe Yeremia, wanaha ya''ia, ba sambua ma''ökhö labe''e roti khönia, nihalö ba nomo duka roti, irege ahori roti ba mbanua bakha. Ba ba naha zago ahono Yeremia.[3]', '["Faigi 22:2"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 1, 'Ba larongo ira Safatia, ono Matano, Gedalia, ono Wasuri, ba Yukhala, ono Zelemia, ba Fasuri, ono Malikia, larongo li Yeremia, me fahuhuo ia ba zato, wanguma''ö:', '["Faigi 21:9"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 2, 'Da''ö niŵa''ö Yehowa: Ha niha zi lö tebulö ba mbanua da''e, ba si mate ba mbawa zi''öli ba ba lofo ba ba wökhö waba, ba ha niha zolulu ya''ia ba danga Ndrawa Galedaia, ba sauri; amaedola gondra''uania nosonia, ba auri[1]', '["Faigi 21:9"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 3, 'Imane Yehowa: Banua da''e, ba lö zi lö tebe''e ba danga zanuwö andrö, khö razo Mbabeli, atu''a ira dania!', '["Faigi 21:9"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 4, 'Ba lamane kumandru sebua khö razo: Ena''ö na öfabunu''ö niha da''ö! Awai halöŵönia: atalö dödö zabölö, si tosai ba mbanua da''a bakha, ibe''e, ba huhuo si manö khöra; tenga fangorifi mbanuada zi so ba dödö niha da''ö, ha famakiko!', '["Faigi 21:9"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 5, 'Ba imane razo, Sedekia: Ba mihalö ia! tebai sa ifadaö limi razo.', '["Faigi 21:9"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 6, 'Ba lahalö Yeremia ba latibo''ö ia ba dögi andrö khö nono razo andrö, Malakia, ba golayama naha zago, ladada mitou Yeremia sinali — ba lö bakha idanö ba dögi andrö, ha tambu, — ba ahöndrö ba dambu Yeremia.', '["Faigi 21:9"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 7, 'Ba me irongo Ebedi-Melekhi, Dawa Gaitiofia, nikhai, si so ba gödo razo, no latibo''ö ba dögi andrö Yeremia — ba ba mbawa göli mado Mbeniyami so razo —,[2]', '["Yer 39:16"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 8, 'ba iröi gödo razo Ebedi-Melekhi, möi ia khö razo, imane:', '["Yer 39:16"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 9, 'He sokhö ya''odo, razo, tenga si sökhi fefu nilaura khö Yeremia sama''ele''ö andrö, wa no latibo''ö ia ba dögi andrö, fa mate olofo ia ba da''ö, me lö balazo sa''ae ba mbanua.', '["Yer 39:16"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 10, 'Ba iŵa''ö razo khö Ndrawa Gaitiofia andrö, Ebedi-Melekhi: Ohe awöu niha moroi ba da''e, datölu, ba döni yaŵa Yeremia, moroi ba dögi andrö, fatua lö mate ia.', '["Yer 39:16"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 11, 'Ba i''ohe awönia niha andrö Ebedi-Melekhi, möi ia ba gödo razo, ba mbate''e tou kato hua, ihalö ba da''ö nukhanukha, atuala nukha, ba idada sinali khö Yeremia ba dögi.', '["Yer 39:16"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 12, 'Ba imane Dawa Gaitiofia andrö, Ebedi-Melekhi, khö Yeremia: Be''e ba galogou gatuala nukha andrö, tufo zinali! ba i''o''ö da''ö Yeremia.', '["Yer 39:16"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 13, 'Ba ladöni yaŵa Yeremia moroi ba dögi, sinali. Ba ba naha zago ahono Yeremia.', '["Yer 39:16"]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 14, 'Ba ifahalö''ö Yeremia sama''ele''ö razo, Sedekia, khönia ba mbawandruhö andrö, fanete zi dombua, ba gosali Yehowa, ba imane razo khö Yeremia: So nisofugu khöu, — böi bini''ö khögu hadia ia.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 15, 'Ba imane Yeremia khö Zedekia: Na u''ombakha''ö khöu, ba hadia, ba lö öbunudo? ba na ufolala dödöu, ba lö''ö zui öfondrondrongo khögu.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 16, 'Ba fahölu razo Sedekia khö Yeremia — lö ifarongogö ba niha — imane: Ba wa''auri Yehowa, somböi khöda nosoda andre, — lö ubunu ndra''ugö, ba lö ube''e''ö ba danga niha andrö, sangalui famunu ya''ugö!', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 17, 'Ba imane Yeremia khö Zedekia; Da''ö niŵa''ö Yehowa, Lowalangi ngahönö, Lowalangi Ndraono Gizeraeli: Na ölulu ndra''ugö ba danga gumandra khö razo Mbabeli, ba auri ndra''ugö ba lö tetunu mbanua andre, ba sauri ndra''ugö awö zoroiyomou fefu.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 18, 'Ba na lö ölulu''ö ba danga gumandra khö razo Mbabeli, ba tebe''e ba danga Ndrawa Galedaia mbanua da''e, ba latunu, ba tebai aefa ndra''ugö ba dangara!', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 19, 'Ba imane razo Sedekia khö Yeremia: Ata''udo niwada, mado Yuda, si ne möi ba Ndrawa Galedaia, — ma labe''edo ba dangara, ba wango''aya ya''o.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 20, 'Ba imane Yeremia: Lö labe''e''ö ba dangara! Ba fondrondrongo goroisa Yehowa, o''ö niŵa''ögu khöu, ba ohahau dödöu ba sauri ndra''ugö.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 21, 'Ba na te khöu ölulu ndra''ugö, ba ya''ia da''e, nifa''ila''ö Yehowa khögu:', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 22, 'Hiza, ira alawe andrö fefu, si tosai ba gödo razo mado Yuda, ba te''ohe baero khö gumandra khö razo Mbabeli, ba lamane [ira alawe andrö]: "No lafowöhö''ö sabe''e dödöu ba no lalaŵa''ö! — me no alösu gaheu ba dambu, ba no la''erogö ndra''ugö!"', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 23, 'Ba ira alaweu fefu, fabaya onou, ba la''ohe baero ba Ndrawa Galedia, ba ya''ugö göi, ba tebai aefa''ö ba dangara, tera''u ndra''ugö ba tebe''e''ö ba danga razo Mbabeli, ba banua da''e, ba nitunu alitö.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 24, 'Ba imane Sedekia khö Yeremia: Lö tola irongo niha bö''ö huhuoda andre, fa böi mate ndra''ugö.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 25, 'Ba na larongo kumandru sebua, no fahuhuo ndra''o khöu, ba na möi ira khöu, na lamane khöu: "Ombakha''ö khöma, hadia niŵa''öu khö razo, — böi bini''ö khöma hadia ia, fa böi mabunu''ö — ba hadia niŵa''ö razo khöu,"', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 26, 'ba ömane khora: No u''idei''ide''ö ndra''odo, wangandrö khö razo böi yamube''e mangawuli ndra''o ba nomo Yonata, ba wa''amate ba da''ö.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 27, 'Ba möi gumandru sebua fefu khö Yeremia, lasofu khönia, ba i''o''ö sibai niŵa''ö razo khönia, wangombakha khöra. Ba laböhöli ia, ma''ifu lö murongo huhuo no mege.', '[]', NULL),
  (3476361, 'OT', 'Yeremia', 38, 28, 'Ba ba naha zago ahono Yeremia, irege luo atu''a ba Yeruzalema zanuwö.', '[]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 1, 'Ba me no atu''a ira ba Yeruzalema (me döfi si siŵa khö Zedekia, baŵa si fulu, ba so Nebukanesa, razo Mbabeli, awö zabölö khönia fefu, ba wanuwö Yeruzalema, ba lafasui;[1][2]', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 2, 'ba me döfi si felezara khö Zedekia ba zi meziŵa ba mbaŵa si öfa, ba atu''a ira ba mbanua)', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 3, 'ba so gumandra andrö khö razo Mbabeli, ba dumadao ba zinga mbawa göli ba dalu: Ira Neregala-Zarese, Samigaro-Nebo ba Saresekhi, sa''asa sebua, ba Neregala-Zarese, satua gere, si faeta, awö gumandra bö''ö andrö fefu, khö razo Mbabeli.', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 4, 'Ba me la''ila ira ira Sedekia, razo mado Yuda, ba sabölö andrö khönia fefu, ba latema moloi, ba zi bongi laröi mbanua, latörö lala ba kabu razo, mbawa göli ba gotalua göli si dua, ba lasaŵa Garaba.', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 5, 'Ba lagohi ira sabölö Ndrawa Galedaia ba lakhamö Zedekia ba ndraso, ba Yerikho; la''ohe ia, lafasao khö Nebukanesa, razo Mbabeli, ba Ribela ba danö Hamata, ba i''etu''ö hukunia.', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 6, 'Ba ifataba''ö mbagi ndraono Zedekia razo Mbabeli, ba da''ö, ba Ribela, ba zanehe Zedekia; ba fefu zalaŵa mado Yuda, ba ifataba''ö mbagi razo Mbabeli.', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 7, 'Ba ifakoe''ö hörö Zedekia, ba larate iŵa''ö ba la''ohe ba Mbabeli.', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 8, 'Ba gödo razo andrö, awö nomo zato, ba latunu Dawa Galedaia ba ladudugö göli Yeruzalema.', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 9, 'Ba si tosai niha, si lö ahori, ba mbanua, he si no möi khöra mege, ba he si tosai, si lö ahori, ba i''ohe ba Mbabeli Nebusa-Adano, sarasa wazuri.', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 10, 'Ba niha si numana, si lö ba danga hadia ia, ba isaigö ösa ba danö mado Yuda Nebusa-Adano, sarasa wazuri, ba ibe''e khöra kabu nagu, awö nowi, me luo da''ö.', '["Ayati 1–10: Faz. 52:4–16; RazII 25:1–12","RazII 25:1 b.t."]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 11, 'Ba ba khö Yeremia, ba ibe''e goroisa Nebukanesa, razo Mbabeli, khö Nebusa-Adano,', '[]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 12, 'imane: Halö ia ba rorogö, böi fakao ia; o''ö khönia zomasi ia, nibokainia khöu!', '[]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 13, 'Ba lafatenge zinenge ira Nebusa-Adano, sarasa wazuri, Nebusasiba, sa''asa sebua ba Neregala-Zarese, satua gere, si faeta, awö fefu gumandra andrö khö razo Mbabeli, lafatenge,', '[]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 14, 'lafahalö''ö Yeremia ba naha zago ba labe''e rorogöfö Gedalia, ono Gahika ono Zafano, ena''ö i''ohe yomo. Ba tobali toröi ia, awö zato.', '[]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 15, 'Ba no muhede Yehowa khö Yeremia, me tetaha ia ba naha zago, no imane:', '["Faigi 38:7"]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 16, 'Ae ŵa''ö khö Ndrawa Gaitiofia andrö, Ebedi-Melekhi: Da''ö niŵa''ö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Itörö sa''ae ligu ba mbanua da''e ube''e, ba wamakiko andrö, ba tenga ba wangorifi, itörö ba zanehe ndra''ugö, na luo da''ö.[3]', '["Faigi 38:7"]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 17, 'Ba ya''ugö andre, ba u''orifi, na luo da''ö — iŵa''ö Yehowa — ba lö tebe''e ndra''ugö ba danga niha andrö, sata''u ndra''ugö.', '["Faigi 38:7"]', NULL),
  (3476362, 'OT', 'Yeremia', 39, 18, 'Aefa ndra''ugö ube''e, tenga si mate ba mbawa zi''öli ndra''ugö, amaedola gondra''uamö nosou, me no abe''e dödöu khögu — iŵa''ö Yehowa.', '["Faigi 38:7"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 1, 'Niŵa''ö Yehowa khö Yeremia, me no i''efa''o ia Nebusa-Adano, sarasa wazuri, ba Rama, wamahalö''ö ya''ia — no murate ia, awö nira''u andrö fefu, banua Yeruzalema ba mado Yuda, ni''oloi''ö ba Mbabeli —.', '["Faigi 26:24; 39:14"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 2, 'Ba ifahalö''ö Yeremia sarasa wazuri andrö ba imane khönia: No idaö''ö-daö''ö ba mbanua da''e wamakiko andrö Yehowa andrö,', '["Faigi 26:24; 39:14"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 3, 'Lowalangimö, ba no ifatörö; no ifalua Yehowa nidaö''ö-daö''önia, me no molalö ami khö Yehowa ba me lö nifondrondrongomi oroisania, ba andrö itörö ami da''ö.', '["Faigi 26:24; 39:14"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 4, 'Ba iya''e, ba hiza! uheta khöu rate andrö ba dangau: na omasi''ö möi awögu ba Mbabeli, ba tabu, ba urorogö ndra''ugö! Ba na anuzu dodöu möi awögu ba Mbabeli, ba akha lö''ö! Hiza, no ebolo danö fönau: heza zomasi''ö möi, ba da''ö ae''e!', '["Faigi 26:24; 39:14"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 5, 'Ba me lö mofanö Yeremia na, ba imane: Ba fuli''ö khö Gedalia, ono Gahika ono Zafano, nifataro razo Mbabeli ba mbanua mado Yuda, ba iagö khönia, awö zato andrö, ma heza zomasi''ö, bö''önia, möi''ö, ba da''ö ae''e! Ba ibe''e khönia mbalazo ba lala ba buala sarasa wazuri andrö, ba ifofanö ia.[1]', '["Faigi 26:24; 39:14"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 6, 'Ba isaŵa Gedalia, ono Gahika andrö, Yeremia, ba Misefa, ba i''iagö khönia, awö zato, si tosai ba danö.', '["Faigi 26:24; 39:14"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 7, 'Ba me larongo kumandra andrö fefu, baero mbanua ba si fao khöra, me larongo, no ifataro [kumandru] ba danö Gedalia, ono Gahika andrö, razo Mbabeli ba no ibe''e barö mbawania ndra matua, awö ndra alawe, awö ndraono, fabaya niha si numana, ba danö, ba niha si lö mu''ohe ba Mbabeli,[2]', '["RazII 25:22–24","Faigi 42:1"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 8, 'ba möi ira khö Gedalia, ba Misefa, ira sima''eli, ono Netania, Yokhana ira, ba Yonata andrö, ono Garea ba Seraya, ono Danumeti, ba iraono Gefa''i andrö, banua Netofa, ba Yesania, ono mbanua Ma''akha andrö, awö zi fao khöra andrö.[3]', '["RazII 25:22–24","Faigi 42:1"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 9, 'Ba möi ba hölu khöra ba ba nawöra andrö Gedalia, ono Gahika ono Zafano, imane: Böi mi''ata''ufi we''amöi barö mbawa Ndrawa Galedaia; mi''iagö danö ba mi''o''ö khö razo Mbabeli, ba sohahau tödö ami!', '["RazII 25:22–24","Faigi 42:1"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 10, 'Hiza, ba Misefa so ndra''odo, fönami ba Ndrawa Galedaia, na so zi möi khöda; ba ya''ami, ba mi''ozaragö mbua nagu ba bua geu bö''ö, fabaya fanikha, ba mibe''e ba nahia, ba mi''iagö mbanua andrö, ni''okhögömi!', '["RazII 25:22–24","Faigi 42:1"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 11, 'Ba larongo göi fefu niha Yehuda andrö, si no fatewu ba Ndraono Moabi ba ba Ndraono Gamoni ba ba Ndraono Gedomo ba ba danö bö''ö fefu, larongo, wa no isaigö ösa mado Yuda razo Mbabeli, awö wa no ifataro kumandrura Gedalia andrö, ono Gahika ono Zafano.', '["RazII 25:22–24","Faigi 42:1"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 12, 'Ba mangawuli fefu niha Yehuda moroi ba danö misa fefu, sizaewe ira, lasaŵa danö mado Yuda, khö Gedalia ba Misefa; ba lasöndra mbua nagu ba bua geu bö''ö, fahöna.', '["RazII 25:22–24","Faigi 42:1"]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 13, 'Ba möi khö Gedalia, ba Misefa, Yokhana andrö, awö gumandra andrö fefu, si so baero mbanua,', '[]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 14, 'ba lamane khönia: Hadia, no örongo göi, wa no ifatenge Zima''eli andrö, ono Netania, Ba''alisi, razo ndraono Gamoni, ba wamunu ya''ugö? Ba lö ifati lira Gedalia, ono Gahika.', '[]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 15, 'Ba imane Yokhana, ono Garea, khö Gedalia, ba Misefa — lö ifarongogö ba niha bö''ö —: Damöido mamunu Sima''eli andrö, ono Netania; alakha lö irongo niha bö''ö! Hana wa ibunu ndra''ugö, ba wame''e zumaewe zui fefu niha Yehuda, si no orudu khöu ba tekiko zi tosai mado Yuda?', '[]', NULL),
  (3476363, 'OT', 'Yeremia', 40, 16, 'Ba imane Gedalia, ono Gahika, khö Yokhana, ono Garea: Böi! faya niböbögöu andrö khö Zima''eli!', '[]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 1, 'Ba me baŵa si fitu, ba so Zima''eli andrö, ono Netania ono Gelisama, nga''ötö razo ba salaŵa ba ngai razo; dafulu niha nawönia, lasaŵa Gedalia, ono Gahika, ba Misefa, ba manga ira, tomenia, ba Misefa.[1]', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 2, 'Ba maoso Zima''eli andrö ba awönia fao, si dafulu andrö, latema labunu Gedalia, ono Gahika ono Zafano, labunu si''öli nifataro razo Mbabeli ba danö,', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 3, 'fabaya niha Yehuda fefu, si so ba da''ö, ba Misefa, khö Gedalia ba Dawa Galedaia ba da''ö, sabölö, ibunu Sima''eli.', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 4, 'Ba sara wongi, aefa no labunu Gedalia, me lö samondrongo na,', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 5, 'ba so niha si otarai Zikhema ba Silo ba Samaria, ŵalu ngafulu ira, no mutöwö gambi ba no lasika nukhara ba no lakhoi ira, so khöra zumange ni''a ba kumöyö, ni''ohe ba gosali Yehowa ena''ö.[2]', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 6, 'Ba ifaondragö ira Sima''eli, ono Netania, moroi ba Misefa, mege-ege ia ba lala, ba me faondra ira, ba imane khöra: Mitabu miyomo khö Gedalia, ono Gahika!', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 7, 'Ba ha si''aikö larugi yomo mbanua, ba i''ö''ötö ira Sima''eli, ono Netania, ba itibo''ö ba mba''a, ya''ia ba awönia fao.', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 8, 'Ba dafulu khöra zanguma''ö khö Zima''eli: Böi bunuga: so khöma mbalazo, nibini''ö ba danö, fakhe ba rigi ba fanikha ba ŵe ŵani! Ba iböhöli ira, lö ibunu, awö mbanuara andrö.', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 9, 'Ba ba''a andrö, nitibo''ö Zima''eli boto niha andrö, nibununia, fefu —, ba ya''ia mba''a sebua andrö, nifakhao''ö Asa, razo, öra idanö, me isuwö ira Ba''esa, razo Ndraono Gizeraeli: da''ö nifo''ösi Zima''eli, ono Netania, boto nibunu.[3]', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 10, 'Ba dozi si tosai niha ba Misefa, ba i''oloi''ö Sima''eli, ono razo alawe, awö zato fefu, si tosai ba Misefa, nibe''e Nebusa-Adano, sarasa wazuri barö mbawa Gedalia ono Gahika — da''ö ni''oloi''ö Zima''eli, ono Netania, ba mofanö, ba we''amöi misi yefo ba Ndraono Gamoni.', '["Faigi 40:14","Yer 16:6","RazI 15:22"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 11, 'Ba me larongo Yokhana, ono Garea, ba kumandra andrö fefu, awönia, wamakiko andrö, nilau Zima''eli andrö, ono Netania,', '["SamII 2:13"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 12, 'ba la''ozaragö niha fefu, maoso ira, ba wanuwö Sima''eli, ono Netania, ba lakhamö ia ba zinga mbaŵa idanö sebua andrö, ba ngai Gibeona.[4]', '["SamII 2:13"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 13, 'Ba ha si''aikö la''ila Yokhana, ono Garea, awö gumandra andrö, fefu, si fao khönia, ni''oloi''ö Zima''eli andrö, ba omuso dödöra.', '["SamII 2:13"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 14, 'Ba labali''ö ira furi dozi ni''oloi''ö Zima''eli, moroi ba Misefa, lasaŵa Yokhana, ono Garea.', '["SamII 2:13"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 15, 'Ba moloi Zima''eli, ono Netania, khö Yokhana, ikhamö Ndraono Gamoni, ba daŵalu nawönia.', '["SamII 2:13"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 16, 'Ba dozi niha si tosai, ba i''ohe Yokhana, awö gumandra zabölö andrö fefu, si fao khönia, dozi ni''oloi''ö Zima''eli, ono Netania, moroi ba Misefa, me no ibunu Gedalia, ono Gahika, ira matua, sabölö andrö ba ira alawe ba iraono ba nikhai andrö, ni''ohenia mangawuli, moroi ba Gibeona.', '["SamII 19:38"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 17, 'Ba maoso ira, ba molombase dania ua ba Geruti Kimami, ba ngai Mbetilekhema, ba we''amöi misi tou danö Miserayi,[5]', '["SamII 19:38"]', NULL),
  (3476364, 'OT', 'Yeremia', 41, 18, 'ba Ndrawa Galedaia andrö; ata''u sa''ae ira da''ö, me no ibunu Gedalia, ono Gahika, nifataro razo Mbabeli ba danö Sima''eli andrö, ono Netania.', '["SamII 19:38"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 1, 'Ba so gumandra andrö fefu, awö Yokhana, ono Garea ba Asaria ono Hosaya, ba sato fefu, he iraono ba he satua,', '["SamI 7:8; 12:19; Faigi 37:3","Faigi 7:23"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 2, 'ba lamane khö Yeremia sama''ele''ö: Fondrondrongo wangandröma khöu ba angandrö khö Yehowa, Lowalangiu, salahima, salahi zi tosai andre fefu — lö''ö sa atoto ndra''aga, si tosai sato no, i''ila höröu, na öfaigi ndra''aga —;[1]', '["SamI 7:8; 12:19; Faigi 37:3","Faigi 7:23"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 3, 'yamu''ombakha''ö khöma Yehowa, Lowalangiu, lala, nitöröma, yamuŵa''ö li, ni''o''öma.', '["SamI 7:8; 12:19; Faigi 37:3","Faigi 7:23"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 4, 'Ba imane khöra Yeremia sama''ele''ö: Lau! Ba da mangandrödo khö Lowalangimi Yehowa, u''o''ö zomasi ami, ba fefu niŵa''ö Yehowa khömi, ba u''ombakha''ö khömi; sambua li lö ubini''ö khömi.', '["SamI 7:8; 12:19; Faigi 37:3","Faigi 7:23"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 5, 'Ba lamane khö Yeremia: Ya si so ba mbörö khöma Yehowa, si ndruhu-ndruhu, ba sabe''e dödöda, na lö mabe''e sibai dali wolauma niŵa''ö Yehowa, Lowalangiu, khöu, nifa''ema khöma;', '["SamI 7:8; 12:19; Faigi 37:3","Faigi 7:23"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 6, 'he si sökhi ba he si lö sökhi, — oroisa Lowalangima Yehowa, ba nifatengema ya''ugö iada''e, da''ö ma''o''ö, ena''ö ohahau dödöma, na mafondrondrongo goroisa Lowalangima Yehowa.[2]', '["SamI 7:8; 12:19; Faigi 37:3","Faigi 7:23"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 7, 'Ba fulu bongi, ba iŵa''ö li Yehowa khö Yeremia.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 8, 'Ba ifakaoni''ö Yokhana andrö, ono Garea, ba kumandra andrö fefu, awönia, awö zato fefu, he iraono ba he satua,', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 9, 'ba imane khöra: Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli, ba nifatengemi ya''odo, ba wama''ema wangandrömi, imane:', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 10, 'Na mi''iagö danö da''e, ba u''a''azökhi ami, ba lö ududugö ami, utanö ami, ba lö ufuli udeha ami; noa sa''ae khögu wamakiko andrö, nifatörögu khömi.[3]', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 11, 'Alakha lö mi''ata''ufi razo Mbabeli, sata''u ami iada''e, — akha lö mi''ata''ufi ia, iŵa''ö Yehowa; fao-fao sa ndra''o khömi, ba wanolo ya''ami ba ba wangefa''ö ya''ami ba dangania.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 12, 'Falukha wa''ahakhö dödö ami ube''e, ena''ö i''ogolöi tödö ami ba ena''ö itehe khömi wangawuli ba danömi.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 13, 'Ba na mimane dödömi: Lö ma''iagö danö da''e! na lö mifondrondrongo goroisa Lowalangimi Yehowa, wanguma''ö:', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 14, 'Lö''ö! Ba danö Miserayi möiga, ena''ö lö ma''ila wanuwö ba ena''ö lö marongo li dorofe ba ena''ö lö olofoga, ba wa lö balazo, ba ba da''ö ma''iagö! 15— ba hiza, ba mifondrondrongo daroma li Yehowa, ya''ami si tosai mado Yuda: Imane Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Na mi''onahögö we''amöi ba danö Miserayi, na möi ami si fatewu ba da''ö,', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 16, 'ba ikhamö ami, ba da''ö ba danö Miserayi, si''öli andrö, ni''ata''ufimi ma''ökhö, ba igo''ögo''ö ami ba danö Miserayi lofo andrö, sata''u ami iada''e, ba tekiko ami ba da''ö.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 17, 'Ba dozi niha, si onahögö fe''amöi ba danö Miserayi, si möi fatewu ba da''ö, ba si tekiko ba mbawa zi''öli ba ba lofo ba ba wökhö waba, ba samösa lö si tosai dania, ya''ira andrö, si falukha moloi ba wamakiko andrö, nifatörögu khöra.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476365, 'OT', 'Yeremia', 42, 18, 'Imane sa Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Si mane fönugu andrö ba bakhu-bakhu dödögu, me ihawui mbanua Yeruzalema, si manö dania, na ihawui ami bakhu-bakhu dödögu andrö, na misaŵa danö Miserayi, ba börö wondrakö ami ba famahokha mbu ba fangelifi ba fango''aya, ba lö''ö sa''ae mi''ila danö da''e![4]', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 19, 'Ba noa sa iŵa''ö li khömi Yehowa, ya''ami si tosai mado Yuda, no imane: Böi misaŵa danö Miserayi! Böi zi lö aboto ba dödömi, wa no ufangelama ami ma''ökhö.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 20, 'Noa sa milimo ami, me no mifatenge ndra''o khö Lowalangimi Yehowa, wanguma''ö: Angandrö khö Lowalangima Yehowa, salahima, ba o''ö sibai niŵa''ö Lowalangima Yehowa, wangombakha khöma, ena''ö matörö da''ö.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 21, 'Ba no u''ombakha''ö khömi ma''ökhö, ba lö nifondrondrongomi oroisa Lowalangimi Yehowa, ba da''ö fefu, ba nifatengenia ya''odo, khömi.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476365, 'OT', 'Yeremia', 42, 22, 'Ba iya''e, ba böi zi lö aboto ba dödömi: ba mbawa zi''öli ba ba lofo ba ba wökhö waba tekiko ami dania ba danö andrö, somasi ami möi ami fatewu.', '["Faigi 24:6; Yon 3:10","Yes 65:15; Faigi 25:9"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 1, 'Ba me no ahori i''ombakha''ö Yeremia ba zato fefu daroma li Lowalangira Yehowa, ba nifatenge Lowalangira Yehowa ya''ia khöra, 2— taroma li andrö fefu, ba lamane ira Asaria, ono Hosaya, Yokhana, ono Garea, awö dozi, si no abe''e bawa khö Yeremia: Fayau, lö nifatenge Lowalangima Yehowa ya''ugö, ba wanguma''ö khöma: "Böi mi''ae ba danö Miserayi, ba we''amöi si fatewu ba da''ö!"', '["Faigi 41:10","Faigi 2:16"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 3, 'Barukhi andrö, ono Neriya, zama''udu ya''ugö khöma, ba wame''e ba danga Ndrawa Galedaia ya''aga, ena''ö labunuga, ba ena''ö la''oloi''ö ndra''aga ba Mbabeli!', '["Faigi 41:10","Faigi 2:16"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 4, 'Ba lö la''o''ö goroisa Yehowa ira Yokhana ba kumandra andrö fefu, awö niha sato fefu, ba wangiagö tanö mado Yuda ena''ö;', '["Faigi 41:10","Faigi 2:16"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 5, 'la''ohe zi tosai mado Yuda fefu ira Yokhana, ono Garea, ba kumandra andrö fefu, zi tosai andrö, sangawuli moroi ba niha misa, sizaewe ira mege, ba we''aso ba danö mado Yuda,', '["Faigi 41:10","Faigi 2:16"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 6, 'ira matua ba ira alawe ba iraono ba ono razo andrö, alawe, awö fefu niha, nisaigö Nebusa-Adano, sarasa wazuri, khö Gedalia, ono Gahika ono Zafano, fabaya Yeremia sama''ele''ö ba Barukhi, ono Neriya,[1]', '["Faigi 41:10","Faigi 2:16"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 7, 'ba lasaŵa danö Miserayi; lö''ö sa la''o''ö goroisa Yehowa. Ba larugi Dakhifane.[2]', '["Faigi 41:10","Faigi 2:16"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 8, 'Ba humede Yehowa khö Yeremia, ba Dakhifane, imane:', '["Faigi 15:2"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 9, 'Halö gara sebua ba ko''o ba la''uri ba nibale kara andrö, ba ngai lala yomo, ba gödo Wara''o, ba Dakhifane, fa''aso niha Yehuda ösa,', '["Faigi 15:2"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 10, 'ba ömane khöra: Da''ö niŵa''ö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Hiza, ufahalö''ö genonigu Nebukanesa, razo Mbabeli, ba yaŵa gara andre, niko''ogu, ufedadao dadaomania ba da''ö dania ibologö darafa zalo khönia.', '["Faigi 15:2"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 11, 'Ba so ia ba ifufu danö Miserayi: ha niha nibunu, ba labunu, ba ni''oloi''ö, ba la''oloi''ö ba ni''ö''ötö s''öli, ba la''ö''ötö si''öli![3]', '["Faigi 15:2"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 12, 'Ba ugule''ö galitö ba gosali Lowalangi Ndrawa Miserayi, ba itunu [gosali andrö] ba i''oloi''ö [Lowalangira] ba i''okaero danö Miserayi, si mane na i''okaero mbarunia sebua kubalo, ba mangawuli ia, lö hadia ia.', '["Faigi 15:2"]', NULL),
  (3476366, 'OT', 'Yeremia', 43, 13, 'Ba irasa gowe andrö ba Mbeti Zemesi, ba danö Miserayi, ba osali Lowalangi Ndrawa Miserayi, ba itunu.', '["Faigi 15:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 1, 'Taroma li niŵa''ö khö Yeremia, ba niha Yehuda andrö fefu, si so ba danö Miserayi, ba Migidola ba ba Dakhifane ba ba Nofi ba ba danö Wataro, imane:[1]', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 2, 'Da''ö niŵa''ö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: No anehe ami wamakiko andrö fefu, nifatörögu ba Yeruzalema ba ba mbanua mado Yuda andrö, — tanö si mate da''ö ma''ökhö ba lö niha —,', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 3, 'börö zi lö sökhi andrö, nifazökhira, wangandrö fönugu, me möi ira manunu kumöyö ba Lowalangi bö''ö, wamosumange si lö la''ila, he ya''ira ba he ya''ami ba he ira tuami.', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 4, 'Ba lö''ö sa sadage-dagedo famatenge khömi enonigu andrö fefu, sama''ele''ö andrö, ba wanguma''ö khömi: Böi milau da''ö, sogoro ita, si fatuwu khögu![2]', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 5, 'Ba lö lafondrondrongo, lö labe''e mbörö dalingara, ba wondröi mena''ö si lö sökhi andrö, fa böi sa''ae latunu gumöyö ba Lowalangi bö''ö.', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 6, 'Ba falawu mbakhu-bakhu dödögu ba fönugu, humola ba mbanua mado Yuda andrö ba baewali Yeruzalema, fa tobali adudula ba tanö si mate, si mane ma''ökhö.[3]', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 7, 'Ba iya''e, ba imane Yehowa, Lowalangi ngahönö, Lowalangi Ndraono Gizeraeli: Hana wa miwöwöi khömi wamakiko sebua, wangohori ira matua ba ira alawe ba ono matua ba ono sawuyu khömi, ba danö mado Yuda, wa lö misai gö wöfömi,', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 8, 'wangandrö fönugu, ba nilau dangami andrö, wanunu kumöyö ba Lowalangi bö''ö, ba danö Miserayi, si möi ami si fatewu, fa ahori ami, fa tobali börö wangelifi ba börö wango''aya ami, ba niha ba guli danö fefu?', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 9, 'Hadia, no olifu ami golalöŵa ndra tuami ba olalöŵa razo mado Yuda ba olalöŵa zalaŵami ba olalöŵami ba olalöŵa ndra alawemi, nilaura ba danö Yuda ba baewali Yeruzalema?', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 10, 'Irege ma''ökhö andre lö si tehandro dödöra, ba lö sata''u ira ba lö ni''o''öra oroisagu ba amakhoitagu, nifakhoigu khömi ba khö ndra tuami.', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 11, 'Andrö wa imane Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Hiza, unehegö ami ba wamakiko, ba wangohori mado Yuda, ma''afefu![4]', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 12, 'Use''egö zi tosai mado Yuda andrö, si so ba dödö fe''amöi ba danö Miserayi, si fatewu ba da''ö; nihori ira, ma''afefu; ba danö Miserayi mate ira; ba mbawa zi''öli ba ba lofo ahori ira, he iraono ba he satua: bawa zi''öli ba lofo wamunu. Ba tobali fondrakö ba famahokha mbu ba börö wangelifi ba börö wango''aya ira andrö.[5]', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 13, 'Ba u''otu''ö zi so ba danö Miserayi, si mane fangotu''ögu banua Yeruzalema, si''öli ba lofo ba fökhö waba.', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 14, 'Ba samösa lö si falukha fangorifi ba foloi, si tosai mado Yuda andrö, si no mondrugi tanö Miserayi, ba we''amöi si fatewu ba da''ö, ba wangawuli ba danö mado Yuda ena''ö, somasi ira mangawuli, ba we''aso [zui] ba da''ö: lö''ö sa falukha mangawuli, baero zoloi andrö [si lö atoto].', '["MozII 14:2; Hez 29:10; 30:6; Faigi 43:7","Faigi 25:3,4","Faigi 7:20","Faigi 21:10; Amos 9:4","Faigi 42:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 15, 'Ba latema li Yeremia dozi ira matua, sangila wa latunu gumöyö ba Lowalangi bö''ö ira alawera ba dozi ira alawe, si no ato ba da''ö ba sato fefu, si no fatewu ba danö Miserayi ba Wataro, lamane:', '["Faigi 7:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 16, 'Ba niŵa''öu andrö khöma, ba döi Yehowa, ba lö mafondrondrongo khöu;', '["Faigi 7:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 17, 'ahori sa mafalua gamabu''ula lima andrö, nifabu''uma, ba wanunu kumöyö khö razo mbanua si yaŵa ira alawe andrö ba ba wame''e sumange nibadu khönia, si mane folauma mege, awö ndra ama, awö razoma, awö zatuama, ba mbanua mado Yuda ba baewali Yeruzalema: me luo da''ö, ba lö ambö balazoma ba ohahau dödöma, ba lö itöröga famakao.[6]', '["Faigi 7:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 18, 'Ba götö me no mabato wanunu kumöyö khö razo mbanua si yaŵa, ira alawe andrö ba fame''e sumange nibadu khönia, ba ambö ndra''aga fefu hadia ia, ba ahori ndra''aga ba mbawa zi''öli ba ba lofo.', '["Faigi 7:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 19, 'Ba na matunu iada''e gumöyö khö razo mbanua si yaŵa, ira alawe andrö ba na mabe''e khönia zumange nibadu — ba tenga si lö larongo ira matuama, wa mafazökhi kue khönia, wolau duma-dumania, awö wa mabe''e zumange nibadu khönia.', '["Faigi 7:18"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 20, 'Ba humede Yeremia ba niha sato, ba ndra matua ba ba ndra alawe ba zato fefu, sanguma''ö da''ö no mege, imane:', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 21, 'Ya''ia, fanunu kumöyö andrö, nilaumi, ba mbanua mado Yuda ba baewali Yeruzalema, ya''ami ba ira amami ba razomi ba satuami ba sato ba danö, — da''ö nitörö dödö Yehowa, da''ö ni''angeragönia.', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 22, 'Ba tebai sa''ae itaha Yehowa ba walösökhi wolaumi andrö, ba zogoro ita andrö nifazökhimi; ba andrö wa tobali tanö si mate danömi ba börö wangelifi ba si lö niha, si mane ma''ökhö.', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 23, 'Me no manunu kumöyö ami ba me no molalö ami, khö Yehowa, ba me lö nifondrondrongomi niŵa''ö Yehowa ba me lö ni''o''ömi oroisania ba amakhoitania ba famaduhu''önia: andrö wa no itörö ami famakiko andrö, si mane, maökho.[7]', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 24, 'Ba imane na Yeremia ba zato ba ba ba ndra alawe fefu: Mifondrondrongo li Yehowa, ya''ami niha Yehuda fefu, ba danö Miserayi!', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 25, 'Imane Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Ya''ami ira alawe, — niŵa''ömi bewemi, da''ö nilaumi tangami! — me miŵa''ö: "Mafalua gamabu''ula lima andrö, nifabu''uma, wanunu kumoyö khö razo mbanua si yaŵa andrö, ira alawe, awö wame''e sumange nibadu khönia!" ba mitörö ae nifabu''umi mifalua gamabu''ula limi andrö!', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 26, 'Andrö mifondrondrongo li Yehowa, ya''ami niha Yehuda fefu, si so ba danö Miserayi: Hiza, fahölu ndra''o ba döigu andrö, sebua, iŵa''ö Yehowa: Samösa lö''ö sa''ae niha Yehuda, ba danö Miserayi, ma''asagörö, sanötöi töigu ba wanguma''ö ena''ö: "Ba wa''auri Yehowa!"[8]', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 27, 'Hiza, uhörö-hörögö ira ba wamakiko ba tenga ba wangorifi, ba dozi niha Yehuda, si so ba danö Miserayi ba nihori bawa zi''öli ba lofo, irege no ase''e![9]', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 28, 'Ba saefa ba mbawa zi''öli, ba sangawuli ba danö mado Yuda; laröi danö Miserayi, ba lö atoto. Ba si tosai mado Yuda fefu, si no manaŵa tanö Miserayi, si fatewu, ba saboto ba dödö dania, ha li zi duhu, na ligu, ba na lira! —', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 29, 'Ba da''ö dania dandra khömi, iŵa''ö Yehowa, wa u''otu''ö ami ba danö da''e, ena''ö aboto ba dödömi, wa lö zi lö alua wamakiko andrö, nida''ö''daö''ögu khömi:', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476367, 'OT', 'Yeremia', 44, 30, 'Imane Yehowa: Hiza, ube''e ba danga nemalinia Wara''o Hofera andrö, ba danga zangalui famunu ya''ia, si mane fame''egu Sedekia andrö, razo mado Yuda, ba danga Nebukanesa, razo Mbabeli, si no emalinia ba sangalui famunu ya''ia.[10]', '["Hos 9:1 b.t.","Yes 45:23; Faigi 49:13; Heb 6:13","Faigi 1:12","Hez 29:2"]', NULL),
  (3476368, 'OT', 'Yeremia', 45, 1, 'Taroma li niŵa''ö Yeremia khö Mbarukhi andrö, ono Neriya, me itanö ba zura huhuo andre niŵa''ö-ŵa''ö Yeremia khönia, me döfi si öfa khö Yoyaki andrö, ono Yosia, razo mado Yuda; imane Yeremia:[1]', '["Faigi 36:4","Faigi 39:18"]', NULL),
  (3476368, 'OT', 'Yeremia', 45, 2, 'Da''ö niŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli, ba khöu andre, ya''ugö Barukhi:', '["Faigi 36:4","Faigi 39:18"]', NULL),
  (3476368, 'OT', 'Yeremia', 45, 3, 'No ömane: "Alai ndra''o, inönö na sa fa''abu dödö wa''afökhö andrö khögu Yehowa! Erege dödögu wangarö-ngarö, lö falukhado wolombase!"', '["Faigi 36:4","Faigi 39:18"]', NULL),
  (3476368, 'OT', 'Yeremia', 45, 4, 'Ba ömane khönia [ya''ugö Yeremia]: Da''ö niŵa''ö Yehowa: Hiza, ni''otomosigu andrö, ba ududugö, ba nitanögu, ba udeha, ba guli danö,', '["Faigi 36:4","Faigi 39:18"]', NULL),
  (3476368, 'OT', 'Yeremia', 45, 5, 'ma''asagörö, ba hadia, ö''andrö khöu zebua? Böi andrö da''ö! Hiza sa, dozi niha sa''ae, ba ufatörö wamakiko, iŵa''ö Yehowa, ba ya''ugö ba u''orifi, fefu gofu heza ösaŵa.[2]', '["Faigi 36:4","Faigi 39:18"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 1, 'Taroma li Yehowa khö Yeremia sama''ele''ö, ba niha baero andrö:', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 2, 'Ba Ndrawa Miserayi: Ba zanuwö andrö khö Wara''o Nekho, razo Miserayi, si no mondrugi boto Oifarati, Karikemi andrö, ni''alani Nebukanesa, me döfi si öfa khö Yoyaki andrö, ono Yosia, razo mado Yuda [imane]:[1]', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 3, 'Mihalö mbaluse, awö ndrange, ba milabu ba wasöndrata![2]', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 4, 'Mifa''anö kudo ba mi''ae yaŵa ba hulu! Mifa''aso ami, mi''otetenaulu! Mihaogö doho! Mi''amaru mbaru sabe''e!', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 5, 'Hana wa tokea ira, ba hana wa lawuwu tete u''ila? Hana wa humufa zabölöra ba hana wa moloi manö, lö fanaha, lö labali''ö ira furi; tehawu fa''atau — iŵa''ö Yehowa?', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 6, 'Lö falukha moloi zalio ahe, tebai aefa zabölö: yöu andrö, si yaŵa, ba mbewe Oifarati andrö, manendre ira, alau!', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 7, 'Ha niha atö zanöi, si mane Nilo, sohohou, si mane idanö sebua?', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 8, 'Dawa Miserayi andrö zanöi, si mane Nilo, mohohou, si mane idanö sebua, ba lamane: Möi ita miyaŵa, tanönöi danö, tafufu mbanua, fabaya niha bakha!', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 9, 'Mi''andruo, ya''ami kudo! Mi''abölögö, ya''ami kureta! ba ndramulabu sabölö: Dawa Gaitiofia andrö ba Dawa Libia, samaluse andrö, fangönara, ba Dawa Ludi, si so fana, nikhai![3]', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 10, 'Ba khö Zo''aya mbaŵa da''ö, khö Yehowa ngahöno andrö, baŵa wolau balö, ena''ö ilau mbalönia ba zi fa''udu khönia! Manga zi''öli ba abuso, mabu ia dora andrö: sanaba sumange sa''ae Zo''aya, Yehowa ngahönö, ba danö yöu, ba mbewe Oifarati![4]', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 11, 'Ae misi yaŵa ba Gileadi ba halö dalu-dalu, ya''ugö ono alawe, ono Ndrawa Miserayi! Öfalalalala dalu-dalu nifalemba khöu![5]', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 12, 'Larongo wa''ailamö andrö niha baero, ba no anönö danö fege-egeu andrö, itendre nawönia sabölö sabölö ba faoma alau ira, darua ira.', '["RazII 23:29; 24:7; Nga''ötII 35:20; Hez 29:2","RazI 10:17","MozI 10:6","Yes 34:8","Faigi 8:22"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 13, 'Taroma li niŵa''ö Yehowa khö Yeremia sama''ele''ö, ba we''aso Nebukanesa, razo Mbabeli, ba wanuwö Dawa Miserayi, imane:', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 14, 'Mi''ombakha''ö ba danö Miserayi, mifarongogö ba Migidola, mitunö ba Nofi ba ba Dakhifane, mimane: Faoso ba fa''anö''ö, noa sa''ae manga-manga zi''öli ba zi tefasui ya''ugö![6]', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 15, 'Hana wa no tegaölö tou zabölömö? Tebai manaha, me no Yehowa zanimba.', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 16, 'No ato zalau ibe''e, ilangö nawönia zamösana, ba lamane: Talabu, fafuli ita ba niwada, ba danö khöda, ba zi''öli andrö, sabölö sibai!', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 17, 'Lamane ba da''ö: "Si tekiko Wara''o, razo Miserayi; lö ni''oguna''önia wamonoso andrö!"', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 18, 'Faya wa no sauri ndra''o, iŵa''ö razo andrö, sotöi Yehowa ngahönö — na tenga amaedola Dabora hili andrö, ba na tenga amaedola Garemeli andrö, yaŵa nasi, wa''asonia! (Nebukanesa andrö)', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 19, 'Fa''anö gama-gamamö ba wofanö, ya''ugö niha ba danö, ono Ndrawa Miserayi alawe; tanö si mate sa dania Nofi, tetunu, ba ahori niha.', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 20, 'Amaedola nono zaŵi si sökhi sibai Miserayi andrö; ba so gulo moroi yöu, itörö.', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 21, 'Enoni andrö göi khöra [ni''oni ba wanuwö], ba no amaedola nono zaŵi nibula, ba da''ö göi zamali''ö ya''ira furi, moloi, dozi, tebai manaha. Noa sa ikhamö ira baŵa wa''atekikora, baŵa wotu.', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 22, 'Lira, ba no hulö ruru gulö, na moloi ia. Ato sa ira, sabölö, na so ira; lalau wato, amaedola zolobö eu.', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 23, 'La''obö gatua andrö khöra, iŵa''ö Yehowa; lö''ö sa mutaha mu''erai ira, oya sa''ae ira, moroi ba damo, tebai zangerai.', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 24, 'Tobali si lö boto nono Miserayi andrö, alawe, tebe''e ba danga niha moroi yöu!', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 25, 'Imane Yehowa ngahönö andrö, Lowalangi Ndraono Gizeraeli: Hiza, u''otu''ö Gamoni andrö ba No, fabaya Fara''o ba tanö Miserayi ba Lowalangira ba razora, Fara''o andrö, fabaya sabe''e tödö khönia.', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 26, 'Ba ube''e ba danga zangalui famunura ira, ba danga Nebukanesa, razo Mbabeli ba ba danga genoninia; ba aefa da''ö ba ifuli so zowanua ba da''o, niha, si mane me götö föna — iŵa''ö Yehowa.', '["Faigi 44:1"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 27, 'Ba ya''ugö enonigu, ma''uwu Yakobo, ba böi ata''ufi, böi tokea''ö, ya''ugö ma''uwu Gizeraeli; hiza sa u''efa''ö ndra''ugö ba danö saröu, ba u''efa''ö madou ba danö andrö, ba ni''oloi''ö ya''ira, ena''ö mangawuli ma''uwu Yakobo, ena''ö ahono ira ba danö ba ena''ö lö hadia ia, fa böi si keani ya''ira.[7]', '["Yes 41:13; 43:5; 44:2","Faigi 30:11"]', NULL),
  (3476369, 'OT', 'Yeremia', 46, 28, 'Böi ata''ufi, ya''ugö enonigu ma''uwu Yakobo, iŵa''ö Yehowa, fao-fao sa ndra''odo khöu. Use''e sa niha andrö fefu, ba nitibo''ögu ya''ugö, ba ya''ugo, ba lö use''egö, ha u''otu''ö ndra''ugö, ndrohu-ndrohu; lö''ö sa tola lö''ö manö u''otu''ö ndra''ugö.[8]', '["Yes 41:13; 43:5; 44:2","Faigi 30:11"]', NULL),
  (3476370, 'OT', 'Yeremia', 47, 1, 'Taroma li niŵa''ö Yehowa khö Yeremia ba Ndrawa Wilisiti andrö, me lö nisuwö Wara''o Gasa na.[1]', '["Faigi 25:30; Hez 25:15; Amos 1:6","MozI 10:14; MozV 2:23; Amos 9:7","Faigi 16:6"]', NULL),
  (3476370, 'OT', 'Yeremia', 47, 2, 'Imane Yehowa: Mohohou sa''ae nidanö moroi yöu, tobali mbombo si nönöi daso, anönö danö, fabaya ösinia, ibe''e, alömö mbanua, fabaya niha bakha: mu''ira-ira niha, mege-ege fefu zi so ba danö.', '["Faigi 25:30; Hez 25:15; Amos 1:6","MozI 10:14; MozV 2:23; Amos 9:7","Faigi 16:6"]', NULL),
  (3476370, 'OT', 'Yeremia', 47, 3, 'Ba wedözödözö danö, ba wanguhundra za''a kudo khöra ya''ia ba ba ruru guretara ba ba werara gaolo, — ba lö labali''ö ira furi ba ndraonora ira ama, me no atata dangara,', '["Faigi 25:30; Hez 25:15; Amos 1:6","MozI 10:14; MozV 2:23; Amos 9:7","Faigi 16:6"]', NULL),
  (3476370, 'OT', 'Yeremia', 47, 4, 'börö mbaŵa andrö, si no alua, ba wamufu tanö Ndrawa Wilisiti ma''asagorö, ba ba wangohori Tiro ba Sidona, dozi si tosai na, sanolo; ifufu sa''ae Yehowa Ndrawa Wilisiti, si tosai si hene asi ba Gafatora,[2]', '["Faigi 25:30; Hez 25:15; Amos 1:6","MozI 10:14; MozV 2:23; Amos 9:7","Faigi 16:6"]', NULL),
  (3476370, 'OT', 'Yeremia', 47, 5, 'No irugi Gasa fa''asele, no adudu Gasikalo. Ya''ami si tosai ma''uwu Genaki, ha wa''ara na mikhoikhoi nösimi?[3]', '["Faigi 25:30; Hez 25:15; Amos 1:6","MozI 10:14; MozV 2:23; Amos 9:7","Faigi 16:6"]', NULL),
  (3476370, 'OT', 'Yeremia', 47, 6, 'He ya''ugö, si''öli Yehowa! ha wa''ara na, wa lö molombase ndra''ugö? Angawuli ba zaembumö, honogö''ö ba böi aliŵa-liŵa!', '["Faigi 25:30; Hez 25:15; Amos 1:6","MozI 10:14; MozV 2:23; Amos 9:7","Faigi 16:6"]', NULL),
  (3476370, 'OT', 'Yeremia', 47, 7, 'He iwisa wolombase, me no i''oroi''ö Yehowa? Ba Gasikalo ba ba zi hene asi andrö, — ba da''ö i''oro''ö!', '["Faigi 25:30; Hez 25:15; Amos 1:6","MozI 10:14; MozV 2:23; Amos 9:7","Faigi 16:6"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 1, 'Ba khö Ndraono Moabi: Imane Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Alai Nebo andrö, noa sa adudu! No tobali si lö boto Giriata''i, no atu''a zanuwö; no si lö boto mbanua saro andrö!', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 2, 'No taya duria Ndraono Moabi. Ba Hesibona lafagölösi wamakiko ya''ira [lamane]: "Talabu! Tahori ira, ena''ö tenga soi sa''ae". Ba ya''ugö göi, ya''ugö Madimena, ba nifufu; igo''ögo''ö ndra''ugö si''öli!', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 3, 'Hiza we''ira-ira moroi ba Horona''i, lamane: "Fa''adudu ba famufu sabölö-bölö!"', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 4, 'Noa sa afufu Ndraono Moabi: Fege-ege nirongoda, irugi Zoara.', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 5, 'Sege-ege ba lala miyaŵa, ba Luhiti, ba mitou ba ngai Horona''i, ba fangarongarö ba wa''afufu andrö tarongo.', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 6, 'Mi''oloi, mi''orifi ami, ya si lö balu-balu ami ba danö si mate!', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 7, 'Me no abe''e dödömi ba nilau dangami andrö ba ba gana''ami, ba atu''a göi ba mbanua khömi zanuwö, ba ni''oloi''ö Gamosi (adu) andrö, ba ere andrö ba salaŵa andrö khönia, fefu.[2]', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 8, 'Ba dozi banua, ba itörö sanudugö; sambua lö banua, saefa: Tekiko ndraso ba afufu zalo''o, itörö niŵa''ö Yehowa.', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 9, 'Mifo''afi Ndraono Moabi, ena''ö muhombo ba ena''ö moloi: adudula sa dania mbanua khöra, salösu lö niha sa''ae!', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 10, 'Ni''elifi zongae tödö wangai halöŵö andrö khö Yehowa, ba ni''elifi göi zanaha si''ölinia ba wamaduwa do andrö.', '["MozIV 21:29; Faigi 49:3"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 11, 'I''otarai mböröta, ba lö hadia ia ba Ndraono Moabi andrö, no ahono-hono manö ba wöröwörö andrö, lö mufohani ira ba nahia bö''ö, lö murai mu''oloi''ö ira; andrö wa lö si tebulö wa''amira ba lö si tobali huara.', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 12, 'Ba hiza sa, irugi baŵa dania, iŵa''ö Yehowa, ba ufatörö khöra zamohani, samaduwa ösi nahia andrö khöra ba sorasa rumbira!', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 13, 'Ba tobali si lö boto Ndraono Moabi ba Gamosi andrö, si mane falöboto Ndraono Gizeraeli no, ba Mbetieli andrö, ba zabe''e dödöra.[3]', '["RazI 11:29","Faigi 25:27"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476371, 'OT', 'Yeremia', 48, 14, 'He moroi, wa mimane: Niha sabölö ndra''aga si no to''ölö ba wanuwö?', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 15, 'So moroi sa zamufu Iraono Moabi, sanudugö banua khöra ba tegaölö tou wondrege nitutuyu andrö, ono matua sabölö, ni''ö''ötö, — iŵa''ö razo andrö, sotöi Yehowa ngahönö.', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 16, 'No ahatö wa''atekiko Ndraono Moabi andrö, aösö sibai wamunura.', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 17, 'Mi''e''esi, dozi ami si faola tanö khöra, ya''ami si no mamondrongo töira, fefu! Mimane: Ha lö afufu zi''o zalaŵa andrö, si''o ba wa''abölö, si''o lakhömi andrö!', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 18, 'Ae tou, röi lakhömi andrö, dadao tou, ba zi lö basöbasö dödö, ya''ugö banua Dibona, ono alawe; so sa''ae khöu zamufu Iraono Moabi moroi sa, idudugö hati andrö khöu!', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 19, 'Ae ba zinga lala, ba fakhölö''ö, ya''ugö banua Garoeri; sofu ba zoloi andrö, ba zaefa andrö, ömane:', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 20, 'He wisa mege? No tobali si lö boto Ndraono Moabi, noa sa tobali dödö: mi''ege-ege ba mi''angarö-ngarö! Mi''ombakha''ö ba mbewe Garono, wa no afufu danö Moabi!', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 21, 'Noa sa itörö huku danö andrö, ba zalo''o tanö, Holono andrö ba Yasa ba Mefa''ata,', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 22, 'ba Dibona ba Nebo ba Beti Dibelata''i,', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 23, 'ba Kiriata''i ba Beti Gamula ba Beti Meona,', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 24, 'ba Keriota ba Bosera, banua Ndraono Moabi fefu, he ba zahatö ba he ba zaröu.', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 25, 'No mu''eŵa dandru Ndraono Moabi ba no murasa da''io! — iŵa''ö Yehowa.', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 26, 'Mibusi ira tuo, noa sa lalaŵa Yehowa; ena''ö tetaru mbagi Ndraono Moabi ba gutara ba ena''ö fama''iki niha bö''ö göi ira.[4]', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 27, 'Hadia, lö ni''igi''igi''ömi Iraono Gizeraeli? Hadia no mura''u ira si fabaya ba zanagö, wa öfalikhölikhö ndra''ugö, ero na itörö liu ira?', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 28, 'Miheta ami yomo ba mbanua, ya''ami si so ba danö Ndraono Moabi, ba dögi narö gara mifaigi nahiami, ena''ö amaedola mburu''u ami, sangazuni ba zinga mbaho!', '["RazI 11:29","Faigi 25:27"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 29, '"No tarongo wayaŵasa Ndraono Moabi andrö, si no fondrege, hokhara andrö ba fayaŵasa andrö khöra, hokhara ba fayaŵasa dödöra!"[5]', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 30, 'U''ila sa''ae wayaŵasara andrö, iŵa''ö Yehowa: faya wehedera ba faya wolaura, hadia ia.', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 31, 'Andrö wa sege-ege ndra''o ba Ndraono Moabi, sange''esi Iraono Moabi fefu; sangarö-ngarö ita ba mbanua Giri Heresi andrö!', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 32, 'Abölö wange''esigu ya''ugö, ya''ugö töla nagu ba Zibema, moroi ba we''e ba Ya''ezeri andrö; tefa''ötö ba zilua asi ndrahamö, ba irugi mbaŵa nidanö andrö ba Ya''ezeri: ba mbaŵa wamasi khöu, ba wangozaragö bua nagu, so zamufu.', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 33, 'Aheta wa''omuso dödö ba fa''iki ba kabu ba danö Ndraono Moabi; taya nösi mbua nagu ba rumbi ube''e, tebato wolazi; fa''iki si tenga fa''iki!', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 34, 'I''otarai Hesibona, sangarö-ngarö andrö ba irugi Eleale, irugi Yahasa, ba mege-ege niha; i''otarai Zoara, numalö ba Horona''i ba ba zi tölu nga''ötö Negelati; ogo''ö sa''ae göi nidanö ba Nimeri, tobali tanö si mate.[6]', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 35, 'Ba uhori ba Ndraono Moabi — iŵa''ö Yehowa — zi möi miyaŵa ba hili-hili, ba wanunu kumöyö khö Lowalangira.', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 36, 'Andrö wa moli bakha dödögu ba Ndraono Moabi andrö, amaedola li zurune! moli bakha dödögu, amaedola li zurune, ba mbanua Giri-Heresi andrö: noa sa taya ni''irö''öra, nibe''era yaŵa.', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 37, 'Dozi högö, ba no batule, ba no mutöwö gambi, fefu; dozi ta''io, ba no mukhoi ba no la''olembe gonigoni.', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 38, 'Ba dete nomo Ndraono Moabi fefu ba ba newali khöra, ba no ha sambalö fangarö-ngarö, — me no urasa Ndraono Moabi, timba worasa bowoa, si lö somasi, iŵa''ö Yehowa.', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 39, 'Ha lö arasa! Mege-ege. La''erogö manö [ita] Iraono Moabi, aila; Tobali fama''iki niha ba fa''atobali dödö Ndraono Moabi ba zi faola tanö khöra fefu.', '["Yes 16:9","Yes 15:5"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 40, 'Imane sa''ae Yehowa: Hiza, amaedola moyo we''asonia (sanuwö andrö) moroi sa, ibologö gafinia yaŵa Ndraono Moabi andrö;[7]', '["Faigi 49:22","Yes 24:17","MozIV 21:18; 24:17"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 41, 'te''ala mbanua ba atu''a ba hati andrö zanuwö, ba tödö zabölö Ndraono Moabi, na luo da''ö, ba no timba dödö ndra alawe, si so ba daugedauge.', '["Faigi 49:22","Yes 24:17","MozIV 21:18; 24:17"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 42, 'Ba nifufu Ndraono Moabi fa tenga soi sa''ae, me no lalaŵa Yehowa.', '["Faigi 49:22","Yes 24:17","MozIV 21:18; 24:17"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 43, 'Fehokha mbu ba lösu-lösu ba tandraŵa khöu, ya''ugö si so ba danö Ndraono Moabi, — iŵa''ö Yehowa —:[8]', '["Faigi 49:22","Yes 24:17","MozIV 21:18; 24:17"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 44, 'Si no moloi ba wehokha mbu andrö, ba aekhu ba lösu-lösu, ba si möi yaŵa moroi ba lösu-lösu, ba alau ba dandraŵa. Da''ö sa nifatörögu ba Ndraono Moabi, na döfi wangotu''ö ya''ira — iŵa''ö Yehowa.', '["Faigi 49:22","Yes 24:17","MozIV 21:18; 24:17"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 45, 'Ba lumö andrö ba Hesibona labadugö ira soloi, tebai sa''ae, ba alua galitö ba Hesibona ba hola-hola galitö ba gödo Zihona; ba i''a dangi-dangi Ndraono Moabi ba amu''u zebua gua-gua.[9]', '["Faigi 49:22","Yes 24:17","MozIV 21:18; 24:17"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 46, 'Alai ami, ya''ami Iraono Moabi, no tekiko mbanua Gamosi andrö! ono matua ba ono alawe khömi, ba ni''oloi''ö sawuyu.', '["Faigi 49:22","Yes 24:17","MozIV 21:18; 24:17"]', NULL),
  (3476371, 'OT', 'Yeremia', 48, 47, 'Ba ufuli sa u''efa''ö Ndraono Moabi ba götö furi, iŵa''ö Yehowa. — Ba da''e irugi fotu Ndraono Moabi andrö.', '["Faigi 49:22","Yes 24:17","MozIV 21:18; 24:17"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 1, 'Ba Ndraono Gamoni andrö: Da''ö niŵa''ö Yehowa: Hadia, lö nga''ötö Ndraono Gizeraeli, lö sanema ondröita? Ba hana wa no itema gondröita Gado Milikomo andrö, hana wa so ba mbanuara mbanuania?[1]', '["RazI 11:5; RazII 23:13; Hez 21:28 b.t.; 25:2 b.t.; Amos 1:13 b.t."]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 2, 'Ba hiza, irugi baŵa dania — iŵa''ö Yehowa — ba so wangahahagö ba wanuwö ba Raba Ndraono Gamoni ube''e, ba tobali adudula ia, ba tetunu halama soya khöra ba latema sa''ae Iraono Gizeraeli gondröita zanema ondröita duara mege, — iŵa''ö Yehowa.', '["RazI 11:5; RazII 23:13; Hez 21:28 b.t.; 25:2 b.t.; Amos 1:13 b.t."]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 3, 'Mi''ege-ege, ya''ami banua Hesibona, me no atu''a ba mbanua zanuwö! Mi''angarö-ngarö, ya''ami halama soya ba Raba! Mi''olembe gonigoni, milau mange''esi, ya si lö ahono ami, barö göli misa; ni''oloi''ö sa''ae Milikomo andrö, fabaya ere andrö ba salaŵa andrö khönia!', '["RazI 11:5; RazII 23:13; Hez 21:28 b.t.; 25:2 b.t.; Amos 1:13 b.t."]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 4, 'Hadia wa ösuno ndra''ugö ba ndraso andrö, ba zi no fahöna ba zalo''o andrö, ya''ugö ono alawe si no fa''ero, si no abe''e tödö ba gana''a, wanguma''ö: "Ha niha zolau khögu?"', '["RazI 11:5; RazII 23:13; Hez 21:28 b.t.; 25:2 b.t.; Amos 1:13 b.t."]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 5, 'Hiza, fehokha mbu ufatörö khöu, moroi ba zi tefasui ya''ugö — iŵa''ö Yehowa ngahönö andrö; ba nifazaewe ami, itörö lalania zamösana, ba lö sangozaragö soloi andrö!', '["RazI 11:5; RazII 23:13; Hez 21:28 b.t.; 25:2 b.t.; Amos 1:13 b.t."]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 6, 'Ba na furi, ba u''ohe mangawuli ni''oloi''ö andrö, Iraono Gamoni, — iŵa''ö Yehowa.', '["RazI 11:5; RazII 23:13; Hez 21:28 b.t.; 25:2 b.t.; Amos 1:13 b.t."]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 7, 'Ba Ndraono Gedomo: Imane Yehowa ngahönö: Hadia, lö fa''atua-tua sa''ae ba Demana? Hadia, no taya gera-era zi so tödö andrö, hadia, no tobalu wa''atua-tuara?[2]', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 8, 'Mi''oloi, milabu ami! Mibini''ö ami ba dögi, ya''ami banua Dedano! Famakiko sa''ae ufatörö ba ma''uwu Gezau na luo u''otu''ö ira.', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 9, 'Na so zangozaragö bua nagu, ba hadia, lö lasaigö wo''uwo''u? na sanagö, ba zi bongi — ba lafufu, irege ahono dödöra.', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 10, 'Ba me no ya''odo zamahoi balu-balu Gezau, me u''oroma''ö zi tobini khönia, fa tebai ibini''ö ia, ba afufu ma''uwunia ba talifusöra ba si faola tanö khöra, ba si lö boto sa''ae!', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 11, 'Röi manö zi lö ama, si lö ina khöu, — ya''odo zangorifi, ba si no mate ira matua khöu, ba hana na khögu abe''e dödöra!', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 12, 'Imane sa Yehowa: Hiza, si tenga si nangea mamadu ösi mako andrö, ba lö tola lö labadu, ba ya''ugö andrö, ba hadia, si lö fotu ndra''ugö? Tenga si lö fotu ndra''ugö, lö tola lö öbadu![3]', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 13, 'Fahölu sa''ae ndra''o ba khögu — iŵa''ö Yehowa: Börö wehokha mbu ba börö wango''aya ba tanö si mate ba börö wangelifi Mbosera andrö dania, ba halama soya andrö khöra, ba si lö mamalö-malö adudula![4]', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 14, 'No urongo duria khö Yehowa, no tefatenge zinenge ba niha baero, ba wanguma''ö: "Mi''owuloi ami, misaŵa ira, milabu, ba wanuwö!"', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 15, 'Hiza sa, uhöndrögö ndra''ugö ba ngai soi bö''ö si lö ba dödö niha bö''ö ndra''ugö ube''e.', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 16, 'Fa''ata''u niha ndra''ugö! samowöhö ya''ugö, ba fayaŵasa dödömö andrö, ya''ugö si so banua saro ba dete gara, sanalagui zuzu hili. He ŵa''ae ö''alaŵa''ö yaŵa gazunimö, si mane moyo, ba utimba tou ndra''ugö, moroi ba da''ö — iŵa''ö Yehowa.[5]', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 17, 'Ba börö wehokha mbu dania Ndraono Gedomo: dozi sanörö, ba tobali dödö, ba fasi ba zokhora andrö fefu[6]', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 18, 'Si mane Sodoma andrö ba Gomora ba si faola khöra, si no tobali arö — iŵa''ö Yehowa, — si manö göi ba da''ö, wa samösa lö niha ba da''o, lö niha-niha si iagö da''ö.[7]', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 19, 'Hiza, timba zingo si möi miyaŵa moroi ba zukhu ba bewe Yoridano, sanaŵa tanö sokara: si manö na utimba ira ha mamö''i hörö wa''ara, ba ufataro salaŵara nituyu andrö. Ha niha sa zi fagölö-gölö khögu? ba ha niha zanofu li khögu? ba heza so gubalo, sanaha fönagu?[8]', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 20, 'Andrö mifondrondrongo dödö Yehowa andrö, tödönia ba Ndraono Gedomo andrö, ba era-erania ba mbanua Demana: Si ndruhu, ni''oloi''ö ira — side-ide mbiri-biri andrö! Si ndruhu, si tobali tödö nahara, ba khöra andrö.', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 21, 'Ba weruru wa''alaura andrö, ba muheu danö; fe''ira-ira — ba mbewe nasi zukhu telobi li!', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 22, 'Hiza, timba moyo wa''asonia moroi sa, muhombo, ba ibologö gafinia yaŵa Mbosera andrö, ba tödö zabölö Ndraono Gedomo, na luo da''ö, ba no timba dödö ndra alawe si so ba daugedauge.[9]', '["Obad a. 1 b.t.; Yob 15","Faigi 25:28; FetI 4:17","Yes 34:6; 63:1","Mat 11:23","Faigi 18:16; 19:8; 50:13","MozI 19:24","Faigi 12:15","Faigi 48:40"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 23, 'Ba Ndramaseko andrö: No aila Hamata ba Arafadi, me no turia si lö sökhi nirongora; no aragu-ragu dödöra, siduludulu ira, si mane asi, si tebai ahono.[10]', '["Yes 17:1 b.t.","Faigi 4:31; 6:24","Amos 1:4"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 24, 'Lö lala dödö Ndramaseko, latema moloi, no ihawui ira fa''ata''u, no ira''u ira fa''afökhö hulu, si mane ba zadono.[11]', '["Yes 17:1 b.t.","Faigi 4:31; 6:24","Amos 1:4"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 25, 'Ha lö ateröi mbanua andrö, sebua turia, banua omasiö khögu!', '["Yes 17:1 b.t.","Faigi 4:31; 6:24","Amos 1:4"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 26, 'Andrö tegaölö tou ba newalira nono matua khöra, ba ahori zabölöra, fefu, na luo da''ö, — iŵa''ö Yehowa ngahönö.', '["Yes 17:1 b.t.","Faigi 4:31; 6:24","Amos 1:4"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 27, 'Ba u''ebua''ö galitö barö göli ba Ndramaseko, ena''ö i''a gödo Mbenihada andrö.[12]', '["Yes 17:1 b.t.","Faigi 4:31; 6:24","Amos 1:4"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 28, 'Ba Gedara ba ba gamatöröwa Hasora andrö, nisuwö Nebukanesa andrö, razo Mbabeli: Imane Yehowa: Milabu, misuwö Gedara, midudugö mbanua andrö, tanö ba gatumbukha luo![13]', '["Yob 1:3","Faigi 9:26"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 29, 'Osera ba biri-birira, ba nihalö, ba tufora ba gama-gamara ba ondra khöra, ba ni''oloi''ö, ba lamane dania niha, we''ao: "Fehokha mbu, fasui!"', '["Yob 1:3","Faigi 9:26"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 30, 'Mi''oloi, mi''aliogö woloi, mibini''ö ami ba dögi, ya''ami banua Hasora! — iŵa''ö Yehowa; so sa gera-era Nebukanesa, razo Mbabeli, khömi, no ikhoi tödönia wolau khömi.', '["Yob 1:3","Faigi 9:26"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 31, 'Milabu! misuwö niha si no ahono-hono, si lö hadia ia — iŵa''ö Yehowa — si lö lagö mbawandruhö ba si lö lazi, ba si lö awö-awö.', '["Yob 1:3","Faigi 9:26"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 32, 'Ondra''ua dania gondrara ba ni''oloi''ö guriföra, soya sibai, ba ufazawili ira, fefu gofu heza misa nifalo''o bu andrö — ba ufatörö khöra wamakiko, moroi ba zi tefasui ya''ira — iŵa''ö Yehowa.[14]', '["Yob 1:3","Faigi 9:26"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 33, 'Ba tobali naha nasu ana''a Hasora andrö, adudula si lö mamalö-malö: lö''ö sa''ae niha ba da''ö, lö si iagö ya''ia.', '["Yob 1:3","Faigi 9:26"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 34, 'Taroma li, niŵa''ö Yehowa khö Yeremia sama''ele''ö, ba Gelama andrö, me awena razo Zedekia, razo mado Yuda, imane:', '["Faigi 48:47"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 35, 'Da''ö niŵa''ö Yehowa ngahönö: Hiza, urasa wana Ndrawa Gelama andrö, sebua wangönara andrö.', '["Faigi 48:47"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 36, 'Ba öfa ufatörö ba Ndrawa Gelama andrö angi, si oroi wondrege danö, si öfa andrö, ba ufazaewe ira ba zi oroi angi andrö, fefu; lö niha dania, si lö larugi sizaewe Dawa Gelama andrö.', '["Faigi 48:47"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 37, 'Aragu-ragu dania dödö Ndrawa Gelama, ube''e, ba nemalira andrö ba ba zangalui famunu ya''ira, ba ufatörö khöra wamakiko, fehola-hola wönugu andrö, iŵa''ö Yehowa — ba ufago''ö khöra zi''öli, irege no ahori ira ube''e.', '["Faigi 48:47"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 38, 'Dadaomagu ufedadao ba danö Ndrawa Gelama andrö ba uhori ba da''ö razo, fabaya satua — iŵa''ö Yehowa.', '["Faigi 48:47"]', NULL),
  (3476372, 'OT', 'Yeremia', 49, 39, 'Ba na luo safuria dania, ba u''ohe mangawuli ni''oloi''ö andrö. Dawa Gelama — iŵa''ö Yehowa.[15]', '["Faigi 48:47"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 1, 'Taroma li Yehowa andrö, nifa''ema Yeremia sama''ele''ö, ba Mbabeli, ba danö Ndrawa Galedaia andrö, imane:[1]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 2, 'Mi''ombakha''ö ba niha baero, mifarongogö, mitaŵi mandrera! Mituriagö, böi mibini''ö! Mimane: No atu''a zanuwö ba Mbabeli, no aila Mbeli andrö, no arasa Merodaki; no si lö boto wamaedo andrö khöra, no arasa nadura.[2]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 3, 'So sa''ae moroi yöu niha, si möi manuwö ya''ira, — samali''ö tanö si mate tanöra, fa lö niha sa''ae ba danö; he niha, ba he urifö, ba moloi, aheta.', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 4, 'Ba na luo da''ö, na götö da''ö — iŵa''ö Yehowa — ba mangawuli Ndraono Gizeraeli, awö mado Yuda, mege-ege manö ba lala, we''amöi mangalui Lowalangira Yehowa.[3]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 5, 'Hili Ziona lazofu-zofu, la''otahögö da''e. So ira ba la''olembai Yehowa, famaböbö si lö mamalö-malö, si lö taya sa''ae ba dödö.[4]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 6, 'Biri-biri sisuna mege mbanuagu andrö: la''ohe ira ba lala elungua kubalora andrö, lafaelungu ira, ba hili misa, latöröi hili ba hili-hili misa, olifu ira golombaseŵara.[5]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 7, 'Si manga ya''ira dozi si fakhamö khöra, ba lamane emalira andrö: Lö horöda! — borö me no molalö ira khö Yehowa andrö, Yehowa nahia wa''atulö, tötönafö ndra tuara.[6]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 8, 'Mi''oloi, miröi Mbabeli andrö, miheta ami ba danö Ndrawa Galedaia, ya hulö mbiri-biri si matua ami, sondrönia''ö biri-biri soya.[7]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 9, 'Hiza sa, ufaoso gahe gorudua soi sabölö moroi yöu, ba Mbabeli andrö; so ira moroi sa ube''e, sama''anö ya''ira, sanuwö ya''ira, ba da''ö moroi wa atu''a dania ira ba [Mbabeli]. Ono wana niha da''ö ba no timba zabölö, sahu lu, si lö mangawuli lö hadia ia.[8]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 10, 'Ba tobali ondra''ua danö Ndrawa Galedaia, ba dozi si farabu ba da''ö, ba abuso — iŵa''ö Yehowa.', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 11, 'Ya omuso dödömi, ya ma''iki ami, ya''ami sorabu nibaya-bayagu, — ya mamaröga ami, si mane ono zaŵi ba wamöbörö fakhe, milau mudele, si mane si matua kudo.[9]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 12, 'Saila sibai dania ninami, afusi mbawa zadono ya''ami, — ya''ira, soi safuria andrö ba tanö si mate ba adudula ba benua awuyu!', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 13, 'Ba wönu Yehowa andrö, ba lö niha sa''ae, tanö si mate manö: dozi sanörö Babeli andrö, ba tobali dödö ba fasi, ba zokhora andrö fefu.[10]', '["Yes 13:14; Faigi 25:26","Yes 46:1","MozV 4:29; Faigi 31:9","Yes 55:3","Faigi 23:1 b.t.","Faigi 31:23; 40:2,3","Yes 48:20","SamII 1:22","MozV 25:4","Faigi 18:16"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 14, 'Mifa''anö ami, mifasui Mbabeli andrö, ya''ami solohe fana! Mi''efasi wana khöra, böi mi''ambösi nono wana, me no khö Yehowa molalö ira!', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 15, 'Mihehegö, fasui: No ilulu ia [Babeli], no adudu wangabe''e, no mududugö göli! — Me no folau balö, khö Yehowa, ba milau mbalömi khöra! Folaura mege misulöni khöra![11]', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 16, 'Mihori ba Mbabeli andrö, he sanaru, ba he samasi! Ba zi''öli sabölö andrö, ba isaŵa niwara zamösana, oi zara moloi, lasaŵa khöra.', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 17, 'Ono mbiri-biri nikeani Ndraono Gizeraeli, nikeani zingo; börötania, ba i''a ira razo Asiria, ba iya''e, ba gafuriata, ba i''ö''ökhi dölara razo Mbabeli.', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 18, 'Andrö wa imane Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Hiza, u''otu''ö razo Mbabeli andrö, fabaya banuania si mane fangotu''ögu mege razo Asiria.[12]', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 19, 'Ba u''ohe mangawuli ba mbenuara Ndraono Gizeraeli, ena''ö ba hili Garemeli ladudu guriföra, ba ba Mbazana, ba ena''ö ba hili mado Geferayi andrö ba ba danö Gileadi lafadöhö wa''olofora!', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 20, 'Ba na luo da''ö, na götö da''ö — iŵa''ö Yehowa — ba la''alu-alui lalö Ndraono Gizeraeli, ba lö''ö sa''ae, ba la''alu-alui lalö mado Yuda, ba lö lasöndra; u''efa''ö sa''ae ba nisaigögu andrö.', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 21, 'Ae lau ba danö "si dua götö fanandro" ba mbanua "wotu" andrö; se''egö, fakiko, gohi ira — iwa''ö Yehowa — o''ö sibai niŵa''ögu khöu!', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 22, 'Hiza wanuwö ba danö ba famufu sabölö-bölö!', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 23, 'Ha lö afufu warökha andrö, famözi uli danö ma''asagörö, ha lö arasa! Ha lö atobali dödö niha bö''ö Mbabeli andrö!', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 24, 'No ulau wesu khöu, ba no alau ndra''ugö, ya''ugö Babeli, lö nidöna-dönau! No lakhamö ndra''ugö ba no lara''u''ö, me no lö ata''u''ö wolaŵa Yehowa.', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 25, 'No ibokai naha wangöna andrö khönia Yehowa ba no isao''ö baero wangöna andrö, na mofönu ia; so sa''ae halöŵö Zo''aya, Yehowa ngahönö, ba danö Ndrawa Galedaia, [fanuwö].', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 26, 'Milabu khöra, gofu heza moroi sa; mibokai halasa khöra mifahisi ira, amaedola wakhe niböbörö, ba mifakiko; ya lö si tosai khöra!', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 27, 'Mihahandro nono zaŵi si matua khöra, fefu, — ni''ö''ötö tou! Alai ira! noa sa irugi baŵa khöra, baŵa wotu![13]', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476373, 'OT', 'Yeremia', 50, 28, 'Hiza! Soloi ba saefa ba danö Mbabeli, sangombakha ba hili Ziona folau balö andrö, nilau Lowalangida Yehowa, balö gosalinia andrö.', '["MozII 21:24; Sin 137:8","RazII 19:35","Faigi 48:15"]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 29, 'Mifaoso gahe zolohe fana, ba Mbabeli andrö, dozi zogai fana! Mifasui mbanua! Böi falukha moloi ira! Misulöni khöra wolaura andrö! Mibe''e dali wolaumi khöra wolaura mege; noa sa lalaŵa Yehowa, Ni''amoni''ö Ndraono Gizeraeli!', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 30, 'Andrö ni''ö''ötö tou ba newali nono matua khöra, ba dozi sabölö khöra, ba nihori, na luo da''ö — iŵa''ö Yehowa. 31— Hiza, ulau khöu, ya''ugö "fayaŵasa", iŵa''ö So''aya, Yehowa ngahönö, noa sa irugi baŵa khöu, inötö wangotu''ögu ya''ugö![14]', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 32, 'Ba salau sa''ae "wayaŵasa", tegaölö tou, ba lö samaoso. Ba ugule''ö galitö ba mbanuara, ena''ö i''a fefu zi tefasui ya''ira!', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 33, 'Imane Yehowa ngahönö: Nifakao Ndraono Gizeraeli, awö mado Yuda fefu, ba dozi sangoloi''ö ya''ira mege, ba lataha, te khöra la''efa''ö.', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 34, 'Ba sangefa''ö ya''ira, ba no sabölö, — Yehowa ngahönö döinia; ya''ia dania zamatunö huhuora, ena''ö ahono guli danö ibe''e, ba ena''ö manizi-nizi mbanua Mbabeli.', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 35, 'Föda nifatörö ba Ndrawa Galedaia andrö — iŵa''ö Yehowa, ba mbanua Mbabeli ba ba zalaŵara ba ba zatua-tua andrö khöra!', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 36, 'Föda nifatörö ba zoya bewe andrö, ena''ö sowöhö mowa ira! Föda ba zabölö andrö khöra, ena''ö atalö dödöra!', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 37, 'Föda ba kudora ba ba guretara ba ba niha bö''ö andrö, si no fatewu, ena''ö tobali ira alawe! Föda ba girö-giröra andrö, ena''ö terabu!', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 38, 'Föda ba nidanö khöra, ena''ö aetu! Tanö naha nadu sa danö, ba ba zihokha mbuda andrö owöhö ira.', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 39, 'Andrö monaha dania ba da''ö garawi ba asu ana''a, kanöwö zonahia ba danö; ba irugi zi lö aetu, ba lö niha sa''ae; götö-götö wa''ara, ba lö sowanua:[15]', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 40, 'Si mane famali''ö Lowalangi arö Zodoma, awö Gomora, awö mbanua ba ngaira, — iŵa''ö Yehowa — si manö dania ba da''ö, wa lö niha, wa lö si iagö.[16]', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 41, 'Hiza niha moroi yöu, soi sebua ba razo si no ato zi maoso moroi ba wondrege danö!', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 42, 'Mofana ba manoho, safaito ira, lö la''ila wa''ahakhö dödö. Fagua-guasara, ba hulö we''ugu-ugu nasi, fakudo, no mangaro ira, fangaro zabölö, ba wanuwö ya''ugö, ya''ugö ono Mbabeli alawe![17]', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 43, 'Irongo duriara razo Mbabeli, ba atata danga, no ihawui ia fa''ata''u, fanizi-nizi, si mane ba zadono.', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 44, 'Hiza, timba zingo si möi miyaŵa, moroi ba ndru''u ba mbewe Yoridano, sanaŵa tanö sokara: si manö na utimba ira, ha mamö''i hörö wa''ara, ba ufataro salaŵara nituyu andrö. Ha niha sa zi fagölö-gölö khögu? ba ha niha zanofu li khögu? ba heza so gubalo, sanaha fönagu?[18]', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 45, 'Andrö mifondrondrongo dödö Yehowa andrö, tödönia ba Mbabeli andrö, ba era-erania ba danö Ndrawa Galedaia: Si ndruhu, ni''oloi''ö ira — side-ide mbiri-biri andrö! Si ndruhu, si tobali tödö nahara, ba khöra andrö!', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476373, 'OT', 'Yeremia', 50, 46, 'Ba we''ao andrö: "No atu''azanuwö!" ba humeu danö, ba fe''ira-irara, ba terongo ba niha baero misa!', '["Yes 47:7","Yes 34:14","MozI 19:24","Faigi 6:23","Yob 41:1; Faigi 49:19 b.t."]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 1, 'Imane Yehowa: Hiza, ufarou dödö zamakiko, samufu Babeli, banua ba hunö nudugu andrö,[1]', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 2, 'ba ufatenge ba Mbabeli zamöbörö, si möi mamöbörö ya''ira, ena''ö lö niha sa''ae ba danöra labe''e. Na lafa''u''u ira, na baŵa wamakao andrö,[2]', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 3, 'ba lö [ba Mbabeli] sogai fana, ba lö sangöröba, sanimba! Ba böi mihakhösi tödö nono matua khöra [ya''ami sanuwö], mifakiko zabölö andrö khöra, fefu,', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 4, 'ena''ö tegaölö tou nibunu ba danö Ndrawa Geledaia, awö nihahandro, ba newali khöra.[3]', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 5, 'Iraono Gizeraeli ba mado Yuda, ba tenga sa amaedola lakha mbanua, tenga ni''erogö Lowalangira, Yehowa ngahönö andrö, he ŵa''ae no fahöna ba danöra golalöŵa khö Ni''amoni''ö Ndraono Gizeraeli.', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 6, 'Mi''oloi, miheta ami ba Mbabeli, yamufaigi wangorifinia zamösana! Böi göna ami famakiko, ba golalöŵara andrö! Inötö wolau balö sa''ae, khö Yehowa: isulöni khöra wolaura mege.[4]', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 7, 'Mako ana''a mege Mbabeli andrö, ba danga Yehowa, ba zi mabu ösi guli danö ma''afefu: labadu-badu nagu andrö yaŵa niha baero, andrö wa no timba zowöhö soi niha misa.[5]', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 8, 'Ba no i''ogomuzaö te''ala Mbabeli ba no afufu: mi''e''esi ira! Mihalö dalu-dalu ba zafökhö andrö khöra, ma atö döhö![6]', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 9, '"Mafadöhö mena''ö wökhö Mbabeli andrö, ba tebai döhö"; miböhöli, talabu ita, yamusaŵa mbanua khöra zamösana. Noa sa irugi mbanua si yaŵa huku andrö, si göna ira, ikhamö lawuo yaŵa!', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 10, 'No ibokai huhuoda satulö andrö Yehowa: Talabu, tadunö-dunö ba Ziona wolau Lowalangida Yehowa!', '["Faigi 4:11; 25:12","Faigi 15:7","Faigi 49:26","Faigi 48:20","Faigi 25:15; Fam 17:4","Yes 21:9; Faigi 8:22; 46:11"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 11, 'Mihaogö nono wana, mituyu mbaluse. No ifarou dödö razo Ndrawa Media andrö Yehowa, si fa''udu ba Mbabeli dödönia, ba wamakiko ya''ira. Folau balö sa''ae da''ö, khö Yehowa, balö gosalinia andrö.[7]', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 12, 'Mitaŵi mandrera, mi''otahögö göli Mbabeli! Mihaögö wama''u''u! Mifataro zanaro! Mifa''aso ba mbini-mbini ösa! Ifalua sa''ae Yehowa nihonogöinia, nidaö''ö-daö''önia ba mbanua Mbabeli andrö.', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 13, 'Ya''ugö andrö, si so ba mbewe nidanö sebua, sebua ana''a, — no irugi wozu khöu, inötö wamalo''o ya''ugö sa''ae.[8]', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 14, 'Fahölu Yehowa ngahönö ba khönia, imane: He ŵa''ae no ufo''ösi ndra''ugö niha, timba wali [wa''ato, ya''ugö Babeli], — ba lalau zui dania wanunö zi möna, ba khöu andrö![9]', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 15, 'Ya''ia, samazökhi tanö ba wa''atua-tuania andrö ba samologö banua si yaŵa ba wa''aboto ba dödönia.[10]', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 16, 'Na terongo linia banua andrö, ba mugoso-goso deu, ba i''ohe miyaŵa lawuo moroi ba gahe mbanua, i''asogö gari mbanua, lala deu, ba ifolala nangi moroi ba zi fahöna ia.[11]', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 17, 'Dozi atöngö, ba tebai aboto ba dödö; dozi tuka gana''a, ba saila, ba wamaedo andrö, me no falimosa nifahele andrö ba me si lö noso.[12]', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 18, 'Faya ia, nifazökhi fango''aya; na baŵa wamatörö huku, ba tekiko.', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 19, 'Ba tenga si fagölö-gölö ba da''ö dana khö ma''uwu Yakobo andrö, no samazökhi tanö''a ia, ba soi tana khönia Ndraono Gizeraeli, Yehowa ngahönö döinia.[13]', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 20, 'Farökha mege ndra''ugö khögu, fangöna, no ube''e forasa soi niha ndra''ugö ba famufu gamatöröŵa razo misa.', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 21, 'Ube''e forasa kudo, fabaya si fakudo yaŵa ndra''ugö ba forasa gureta, fabaya samatörö, ba forasa ndra matua,', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 22, 'awö ndra alawe, awö zatua, awö ndraono, awö nono matua, awö nono alawe, ba forasa gubalo,', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 23, 'fabaya nikubaloi, awö zonowi, awö göröbao khöra, awö gumandru, fabaya mandru.', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 24, 'Ba usulöni ba Mbabeli ba ba mbanua Galedaia fefu zi lö sökhi andrö, fefu, nilaura ba Ziona, ba zanehe ami — iŵa''ö Yehowa.', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 25, 'Hiza, ulau khöu, ya''ugö hili wamakiko — iŵa''ö Yehowa — si no mamakiko ösi guli danö, ma''afefu; to''ila khöu wa''abölögu ube''e; ufagaölö tou ndra''ugö, moroi ba gara andrö, ba ubali''ö hili sakhozi ndra''ugö.', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 26, 'Sambua dania lö lahalö ba khöu gowe ba sambua lö lahalö toyo gehomo; tanö si mate ndra''ugö, si lö mamalö-malö, — iŵa''ö Yehowa.', '["Faigi 50:28; Sakh 9:13","Fam 17:15","Faigi 25:30","MozI 1; Yob 9:8; Sin 104:2","Sin 135:7","Yes 44:11; 45:10; Faigi 51:17","Sin 74:2"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 27, 'Mitaŵi mandrera ba guli danö! Milau dorofe ba niha misa! Mi''amoni''ö soi bö''ö, sanuwö ya''ira! Mikaoni udura gamatöröŵa razo Ararata ba amatöröŵa razo Mini ba amatöröŵa razo Asekena! Mi''oroi''ö zondrönia''ö! Mi''asogö kudo, si hulö damo sosöri![14]', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 28, 'Mi''amoni''ö soi bö''ö udura, razo Ndrawa Media andrö, awö gumandru khöra, awö mandru, amatöröŵara ma''afefu!', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 29, 'Ba humisi dania danö ba humeu itörö sa''ae niŵa''ö dödö Yehowa, ba Mbabeli andrö: tanö si mate danö Mbabeli, ibe''e, ba ahori niha.', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 30, 'Labato wasöndrata sabölö Mbabeli, dumao-dao ba hati andrö khöra, no ariri wa''abölöra, no tobali ira alawe ira: no mutunu nomora, no afatö lazi mbawa göli.', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 31, 'Faondra zi fagohi ba sinenge, ba wangombakha khö razo Mbabeli, wa no atu''a zanuwö ba mbanuania, fasui,', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 32, 'awö wa no ba danga nemali so götöna, wa no la''ogo''öisi mbandra nidanö, awö wa no tobali dödö zabölö.', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 33, 'Imane sa Yehowa ngahönö, Lowalangi Ndraono Gizeraeli: Ono Mbabeli andrö alawe, ba amaedola golayama mbasitö, na baŵa latutu danönia; lö ara tö, ba baŵa wamasi![15]', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 34, '"No i''a ita Nebukanesa, razo Mbabeli, no itimba ita; no ibali''ö nahia si lö ösi ita, no itölö ita, nifanölö hieo, famo''ösi dalunia, no itimba ita ba danöda omasiö".[16]', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 35, 'Ya möi ba hulu Mbabeli wamalangögö ya''odo ba ösigu andrö [ni''a] — ya imanö banua Ziona — ba dogu andrö, ba ya möi ba hulu mbanua Galedaia! — ya imanö Yeruzalema.', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 36, 'Andrö imane Yehowa: Hiza, ufatunö huhuomö, ba ulau mbalöu; u''ogo''öisi nidanö andrö khöra ba u''etu''ö gumbu!', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 37, 'Ba adudula dania Mbabeli, nahia nasu ana''a, tobali börö wehokha mbu, ba fama''iki niha, ba si lö niha sa''ae!', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 38, 'Mundröndröndröndrö na ira, si mane singo, ba fangöngö-ngöngö, si mane ono zingo:', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 39, 'Ba ba wangisöra andrö ufa''oli khöra mbinalu ba ufabadugö khöra zi mabu ira, ena''ö owua-wua dödöra; ba alau dania höröra, ba wemörö si lö mamalö-malö, si lö tokea ira sa''ae! — iŵa''ö Yehowa.[17]', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 40, 'Hulö nono mbiri-biri nitaba tegaölö tou ira ube''e hulö zi matua mbiri-biri ba si matua nambi.', '["MozI 10:3; RazII 19:37","Yes 21:10","Faigi 30:14,19:11","Dan 5"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 41, 'Alai "Zezakhi" andrö, no atu''a zanuwö, no möi ba danga zanuwö wondrege nisuno andrö ba guli danö, ma''asagörö! Alai Mbabeli, no tobali börö wehokha mbu ba niha baero![18]', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 42, 'No inönöi asi Mbabeli andrö, no ihawui dulunia sigoso-goso.', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 43, 'No tobali adudula mbanuara, tanö si mate, tanö si lö niha sa''ae, si lö itörö niha.', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 44, 'U''otu''ö Mbeli andrö ba Mbabeli; hadia nitölönia andrö, ba usöbi ba mbawania, ba böi sa''ae lahurufai ia niha baero! Ba sadudu göi göli Mbabeli!', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 45, 'Miheta ami ba khöra, ya''ami banuagu, yamufaigi wangorifinia zamösana, ba hola-hola wönu Yehowa andrö!', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 46, 'Böi sa atalö dödömi, fa mi''ata''ufi duria andrö, si terongo ba danö, na sambalö duria zi döfi andre ba sambalö ba ndröfia, ba na famakao ba danö, na faoma lalaŵa nawöra salaŵa.', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 47, 'Andrö hiza, irugi baŵa dania, ba ufatörö wotu ba nadu Mbabeli andrö, ba aila danöra ma''asagörö, ba hiza tou ba danö fefu nibunu andrö khöra.', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 48, 'Ba sowua-wua tödö dania mbanua si yaŵa ba tanö tou ba ösinia fefu, ba Mbabeli andrö; moroi yöu sa lahawui ira sanudugö andrö — iŵa''ö Yehowa.[19]', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 49, 'Si te''ala göi Mbabeli, ya''ami Iraono Gizeraeli nibubunu, me no börö Mbabeli, wa sagörö uli danö mate-mate niha.', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 50, 'Ya''ami si no aefa ba mbawa zi''öli, miheta ami, böi mibato! Mitörö-törö tödömi Yehowa, ba zaröu andrö; böi aefa-aefa ba dödömi Yeruzalema![20]', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 51, 'Saila sibai ita, me no tarongo wango''aya: no ihawui mbawada fa''aila, me no larugi niha bö''ö ni''amoni''ö andrö ba gosali Yehowa!', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 52, 'Andrö hiza, irugi baŵa dania — iŵa''ö Yehowa — ba ufatörö wotu ba nadura andrö, ba sagörö tanöra ba so zangarö-ngarö, nibunu!', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 53, 'He no ba mbanua si yaŵa irugi Babeli, ba he si lö lala miyaŵa hatira andrö, labe''e, ba ba khögu la''otarai khöra sanudugö — iŵa''ö Yehowa.[21]', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 54, 'Hiza we''ira-ira moroi ba Mbabeli ba fa''afufu sabölö-bölö tarongo, moroi ba danö Galedaia!', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 55, 'Idudugö sa''ae Mbabeli andrö Yehowa, tebato wagua-guasa andrö, ba khöra ibe''e; mugoso-goso ndrulura, [dulu zanudugö] timba nasi; humöngö we''aora andrö!', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 56, 'Larugi sa''ae Mbabeli sanudugö ba nira''u zabölöra, nirasa wanara; Lowalangi solau balö sa Yehowa, ihaogö wamasulöni.', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 57, 'Ba ba zalaŵara ba ba zatua-tua ba ba gumandru ba ba mandru ba ba zabölö khöra, ba ufabadugö zi mabu ira, ba alau höröra, ba mörö si lö mamalö-malö; lö''ö sa''ae tokea ira! — iŵa''ö razo andrö, sotöi Yehowa ngahönö.', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 58, 'Imane Yehowa ngahönö andrö: Öli Mbabeli andrö, si no awe''e-we''e sibai, ba nidudugö, irege doyo tou, ba bawa göli salaŵa andrö, ba nitunu alitö, ba itörö niwa''ö andrö: Aekhu ba waya wohalö-halöŵö niha, ba ba galitö aekhu wa''erege dödö soi niha.', '["Faigi 25:26","Fam 18:20","Sin 137:5,6","Yes 14:13"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 59, 'Taroma li niŵa''ö Yeremia sama''ele''ö khö Zeraya andrö, ono Neria ono Mahaseya, me möi ba Mbabeli da''ö, awö Zedekia, razo mado Yuda, me no mendröfa fakhe razo ia, — mandru ba wofanö Zeraya andrö.[22]', '["Faigi 32:12"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 60, 'Ba itanö ba zura Yeremia wamakiko andrö fefu, si göna Mbabeli dania — huhuo andrö fefu, nisura, ba Mbabeli andrö.', '["Faigi 32:12"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 61, 'Ba imane Yeremia khö Zeraya: Na örugi Mbabeli, ba faigi, fa öbaso daroma li andre fefu, ba ömane:', '["Faigi 32:12"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 62, 'He Yehowa, ya''ugö zi daö''ö-daö''ö ba mbanua da''e fanudugö ya''ia, fa böi si iagö ya''ia sa''ae, he niha ba he urifö; noa sa ömane: Tanö si mate dania ndra''ugö, si lö mamalö-malö.', '["Faigi 32:12"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 63, 'Ba na no ahori öbaso zura andrö, ba fotambua kara ba tibo''ö ba Oifarati, ba ömane:', '["Faigi 32:12"]', NULL),
  (3476374, 'OT', 'Yeremia', 51, 64, 'Si manö dania wa''alömö Mbabeli, ba lö''ö sa''ae ifuli möi yaŵa, ba wamakiko andrö, nifatörögu khöra; erege dödöra.', '["Faigi 32:12"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 1, 'Dua wulu a sara fakhe Zedekia, me tumaro razo ia, ba felezara fakhe razo ia ba Yeruzalema. Hamutala döi ninania, ono Yeremia, banua Libena.[1]', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 2, 'Ba si lö omasi Yehowa ilau, si mane si''aikö folau Yoyaki andrö.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 3, 'Itörö sa''ae mbanua Yeruzalema, awö mado Yuda [si lö sökhi andrö], börö wönu Yehowa, irege no itimba ira ba duduma hörönia. Ba fabali Zedekia khö razo Mbabeli.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 4, 'Ba me no ahatö irugi meziŵa fakhe razo ia, ba zi mewulu ba mbaŵa si fulu, ba so Nebukanesa, razo Mbabeli, awö zabölö khönia fefu, ba wanuwö Yeruzalema, lafa''u''u, lafazökhi mba''a-ba''ara, fasui.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 5, 'Ba tobali te''u''u mbanua, irugi ndröfi si felezara khö Zedekia.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 6, 'Ba ba zi meziŵa ba mbaŵa si öfa, me no abölö lofo ba mbanua, me lö''ö sa''ae ö niha ba danö,', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 7, 'ba atöla göli labe''e sanuwö ba moloi razo, awö zabölö fefu, ba zi bongi, laröi mbanua, latörö mbawa göli ba gotalua göli si dua, tanö ba kabu razo (ba samasui banua na Ndrawa Galedaia) ba latörö lala ba Garaba.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 8, 'Ba lagohi razo sabölö Ndrawa Galedaia ba lakhamö Zedekia ba ndraso ba Yerikho, me no laröi ia sabölö khönia fefu, me no muzaewe.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 9, 'Ba lara''u razo, la''ohe khö razo Mbabeli ba Ribela ba danö Hamata; ba i''etu''ö hukunia da''ö.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 10, 'Ba ifataba''ö mbagi ndraono Zedekia razo Mbabeli, ba zanehe Zedekia, ba fefu zalaŵa mado Yuda, ba ifataba''ö mbagi, ba Ribela.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 11, 'Ba ifakoe''ö hörö Zedekia, ba larate iŵa''ö. Ba ifa''ohe''ö ba Mbabeli razo Mbabeli ba ifakuru''ö, irugi wa''amatenia.', '["Faigi göi Faz 39:1–10; RazII 24:18–20; Nga''ötII 36:11–16"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 12, 'Ba ba zi mewulu ba mbaŵa si lima, — me no sara ambö dua wulu fakhe dania razo Nebukanesa, razo Mbabeli andrö — ba so Nebusa-Adano andrö, sarasa wazuri, si lö aefa-aefa khö razo Mbabeli, möi ia ba Yeruzalema,', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 13, 'ba itunu gosali Yehowa, awö gödo razo ba omo ba Yeruzalema fefu; omo zalaŵa fefu, ba itunu.', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 14, 'Ba sara öli Yeruzalema, fasui, ba ladudugö sabölö Ndrawa Galedaia, dozi ira, si fao khö zarasa wazuri andrö.', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 15, 'Ba si tosai niha, si lö ahori ba mbanua ba si no möi khöra mege, sanaŵa razo Mbabeli andrö, ba si tosai tuka, ba i''ohe ba Mbabeli Nebusa-Adano, sarasa wazuri.', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 16, 'Ba niha si numana ba danö, ba isaigö ösa Nebusa-Adano, sarasa wazuri, iröi sohalöŵö ba kabu nagu ba sonowi.', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 17, 'Ba taru nahe töla andrö ba gosali Yehowa ba dayadaya andrö ba gala nidanö andrö, töla, ba gosali Yehowa, ba larasa Dawa Galedaia; ba tölania fefu, ba la''ohe ba Mbabeli.[2]', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 18, 'Ba bowoa andrö ba sundrusundru ba si''öli ba figa ba wanefe ba figa bö''ö ba fefu wakake töla, ba wame''e sumange, ba lahalö,', '["Faigi 27:19","RazI 7:15"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476375, 'OT', 'Yeremia', 52, 19, 'ba mako sebua andrö ba gali ba figa ba wanefe ba bowoa ba naha wandru ba mako ba wamadu, fefu wakake ana''a ba fefu wakake firö, ba ihalö sarasa wazuri andrö.', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 20, 'Dua rozi taru nahe andrö ba sambua gala nidanö ba saŵi töla andrö, si felendrua, dayadayania, dayadaya andrö, nifazökhi razo Selomo, ba gosali Yehowa, — tebai tetulo döla wakake andrö fefu.[3]', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 21, 'Ba taru nahe andrö, ba felendrua hela wa''alaŵa zara ba mato daöfa manalagu; öfa turu wa''awe''e-we''e, ni''okoro, lö ösi bakha.', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 22, 'Ba mohögö töla; sambua högö, ba lima hela wa''alaŵa, ba no tefasui ni''obua dalimo högö andrö, töla manö; ba si manö göi ba daru nahe si sara.', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 23, 'Siŵa wulu a önö ni''obua dalimo, soroma, ba otu fefu ni''obua dalimo, fasui ba ni''otarali andrö.', '["Faigi 27:19","RazI 7:15"]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 24, 'Ba ihalö sarasa wazuri zatua gere andrö, Seraya, ba tambalinania ere, Sefania, ba sanaro ba mbawandruhö, datölu.', '[]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 25, 'Ba ihalö ba mbanua genoni yomo, zamösa, si no kumandra zabölö göi, ba dafitu zi lö aefa-aefa mege khö razo, nisöndra ba mbanua, ba durutuli gumandra sebua, sanutuyu saradadu niha danö ba önö ngafulu na niha ba danö, nisöndra ba mbanua.', '[]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 26, 'Da''ö nihalö Nebusa-Adano, sarasa wazuri, ba i''ohe khö razo Mbabeli ba Ribela.', '[]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 27, 'Ba ifabunu''ö ira razo Mbabeli, ba da''ö ba Ribela, ba danö Hamata. Si manö wa''aheta mado Yuda ba danöra, fangoloi''ö ya''ira.', '[]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 28, 'Da''e wa''ato niha, ni''oloi''ö Nebukanesa: Me döfi si fitu khönia, ba tölu ngahönö a dua wulu a tölu mado Yuda i''oloi''ö;', '[]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 29, 'ba me döfi si feleŵalu, ba ŵalu ngaotu a tölu ngafulu a rua, banua Yeruzalema.', '[]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 30, 'Ba me döfi si dua wulu a tölu khö Nebukanesa, ba fitu ngaotu a öfa wulua lima mado Yuda i''oloi''ö Nebusa Adano, sarasa wazuri; tobali öfa ngahönö a önö ngaotu niha, fefu.', '[]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 31, 'Ba me döfi zi tölu ngafulu a fitu, i''otarai me te''oloi''ö Yoyakhi andrö, razo mado Yuda, ba zi dua wulu a lima, ba mbaŵa si felendrua, ba ihakhösi tödö Yoyakhi andrö, razo mado Yuda, Ewili-Merodaki, razo Mbabeli — ba ndröfi me tumaro ia razo, i''efa''ö ba gurunga.[4]', '["RazII 25:27 b.t."]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 32, 'Ihaogö wehedenia khönia ba yaŵa naha dadaoma zalaŵa bö''ö, awönia ba Mbabeli, ibe''e dadaoma Yoyakhi.', '["RazII 25:27 b.t."]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 33, 'Ifaheta''ö nukhania ba gurunga ba awönia ia ba wemanga, götö wa''anau nosonia na.', '["RazII 25:27 b.t."]', NULL),
  (3476375, 'OT', 'Yeremia', 52, 34, 'Ba razo Mbabeli zanaha balazonia — balazonia si lö mamalö-malö, hadia zahori ma''ökhö, irugi wa''amatenia, götö wa''anau nosonia na.', '["RazII 25:27 b.t."]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 1, 'Alai mbanua andrö, no aomö-aomö, sato niha no; no tobali lakha, sebua no ba ngai niha bö''ö; samatörö banua bö''ö no, ba no göna rodi!', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 2, 'Sara wongi manö mege-ege, mowöi daŵa hörönia. Lö sondrara tödönia, dozi somasi ya''ia mege. Dozi si fahuwu khönia mege, ba no faröi khönia, no si fa''udu.[1]', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 3, 'No awu''a mado Yuda, ba wangabu dödö andrö ba ba rodi andrö, si no abe''e. Ba niha baero so ira, lö falukha zahono ira. No lakhamö ira solohi ya''ira, ba zambö fa''ebolo lala.', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 4, 'Sabu tödö lala ba Ziona, me lö si möi ba gowasa. Bawa gölinia fefu, ba no adudula; mangarö-ngarö gere khöra; sabu tödö nono alawe khöra; ba ya''ia, ba no salangu tödö.', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 5, 'No möi yaŵa zamakao ya''ira, ba ba zi fa''udu khöra, ba lö fa''abu dödö. Yehowa sa''ae zamusi tödöra, ba wa''oya horöra andrö; noa sa mu''oloi''ö ndraonora, nirabu zamakao ya''ira.', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 6, 'Ba no aheta ba nono Ziona alawe lakhöminia fefu. Salaŵara, ba no timba mböhö, si lö ö du''u, mowaö-waö lö döladöla, föna zolohi.', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 7, 'Itörö tödö Yeruzalema — na baŵa wamakao ba na baŵa wolohi — zi sökhi andrö fefu, si otarai götö föna sa''ae, me möi ba danga zamakao mbanuara, me lö sangorifi; lafaigi-faigi samakao andrö, la''igi''igi''ö ira, ba wa''ate''alara andrö.', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 8, 'Sebua horö Yeruzalema, andrö wa tobali ni''ogorofi ira. Dozi samosumange ya''ira mege, ba no si lö ba dödö ya''ira sa''ae, me no la''ila zaila ira; ba ya''ira, ba sangarö-ngarö, ba labali''ö ira furi.[2]', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 9, 'No ta''unö gahe mbarura, lö itörö tödöra lua-lua. Ba sahöli-höli dödöda wa''ahöndröra andrö, lö sondrara tödöra. "Faigi wa''anumanagu, ya''ugö Yohowa", noa sa fayaŵa zi fa''udu!', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 10, 'No i''oro''ö dangania samakao andrö, ba wangai ana''ara fefu. Ba no la''ila me möi ba ni''amoni''ö andrö khöra niha baero, niŵa''öu: lö töla orudu ira ba mbanuami.[3]', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 11, 'No ara wangarö-ngarö mbanuara fefu, wangalui balazo; labe''e-be''e gana''ara böli göra, fangorifira. Faigi, ya''ugö Yehowa, nehegö, wa no lö ba dödö niha ya''odo![4]', '["Sin 6:7","Sin 44:15; Yes 47:3; Yer 13:26","MozV 23:3; Yer 52:17","Yer 52:6; Faigi 4:10"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 12, 'Ya''ami fefu, sanörö, mifaigi ba minehegö, na so na wa''afökhö si mane fa''afökhö andrö khögu, nilau khögu, khögu andre, nibusi Yehowa tödö, me baŵa wönunia andrö, si no abölö-bölö sibai.[5]', '["Yer 14:17","Yes 63:3","Yer 23:17","Yer 30:14"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 13, 'No ilau galitö, moroi yaŵa, ifatöröi''ö ba dölagu, ba no ilau wesu gahegu ba no itimba furi ndra''odo. No ifufu ndra''o, fadoro wökhögu ibe''e.', '["Yer 14:17","Yes 63:3","Yer 23:17","Yer 30:14"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 14, 'No ifa''anö kalo mbagigu horögu andrö, tangania; no tefaböbö, ba no muhare''ö ba mbagigu — erege dödögu ibe''e. No ibe''e ba danga zi tebai ulaŵa ndra''odo So''aya.', '["Yer 14:17","Yes 63:3","Yer 23:17","Yer 30:14"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 15, 'No itibo''ö So''aya fefu zabölö, si so ba khögu mege. No ikaoni ba gowasa zi fa''udu khögu, ba womama ono matua khögu. So''aya zanguhundragö folazi khö nono Yuda andrö alawe.[6]', '["Yer 14:17","Yes 63:3","Yer 23:17","Yer 30:14"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 16, 'Da''ö mbörö wege-egegu; mangele manö daŵa hörögu. Noa sa aröu khögu zondrara tödö, si okafui tödögu ena''ö. No abu dödö ndraonogu, me no abölö nemali andrö.[7]', '["Yer 14:17","Yes 63:3","Yer 23:17","Yer 30:14"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 17, 'I''oro''ö dangania Siona, lö falukha zondrara tödö. No ifaoso gahe zamakao ma''uwu Yakobo Yehowa, fasui. No tobali ni''ogorofi Yeruzalema, ba khöra andrö.', '["Yer 14:17","Yes 63:3","Yer 23:17","Yer 30:14"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 18, 'Satulö Yehowa; noa sa ufadaö linia. Mifondrondrongo, ya''ami niha baero fefu, ba mifaigi wa''afökhö andre khögu! Ono alawe khögu ba ono matua, ba no mu''oloi''ö.', '["Yer 14:17","Yes 63:3","Yer 23:17","Yer 30:14"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 19, 'No ukaoni zomasi ya''odo mege, ba lalimodo. Ere khögu ba satua, ba no mate olofo, ba mbanua, me la''alui göra, fangorifira.[8]', '["Yer 14:17","Yes 63:3","Yer 23:17","Yer 30:14"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 20, 'Faigi, ya''ugö Yehowa, wa''atosagu andre; hulö galitö bakha dödögu. Ibali''ö ia tödögu barö dotogu, me no sabe''e tandro ndra''odo mege. Baero, ba si''öli, famunu ndraono, ba yomo ba mbanua, ba teu mbanua.[9]', '["Yes 16:11; Yer 14:18","Yer 8:18"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 21, 'Larongo niha wangarö-ngarögu — ba sondrara tödö, ba lö''ö. Dozi si fa''udu khögu, ba larongo wamakao andrö khögu, ba omuso dödöra, me no ölau [khögu]. Alua dania mbaŵa andrö, nifarongogömö, öbe''e, ba fagölö-gölö ira khögu.', '["Yes 16:11; Yer 14:18","Yer 8:18"]', NULL),
  (3476376, 'OT', 'Ngenu-Ngenu Yeremia', 1, 22, 'Ya möi ba duduma höröu walösökhira andrö, fefu, ba lau khöra, si mane folaumö khögu, ba horöra andrö fefu! Noa sa fahöna wangarö-ngarögu, ba sofökhö bakha dödögu.[10]', '["Yes 16:11; Yer 14:18","Yer 8:18"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 1, 'Ha lö atelumö nono Ziona andrö alawe, ibe''e So''aya ba wönunia andrö! Moroi ba mbanua si yaŵa itibo''ö tou ba danö lakhömi Ndraono Gizeraeli, ba lö itörö tödönia mbaku-baku gahe andrö khönia, me baŵa wönu andrö khönia.[1]', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 2, 'Lö fa''ahakhö dödö Zo''aya wamufu tanö ma''uwu Yakobo; no idudugö hati nono Yuda alawe, ba wönunia andrö; no itimba tou gamatöröŵa, fabaya salaŵa, salakha ibe''e.', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 3, 'No i''eŵa dandru Ndraono Gizeraeli fefu, ba wehola-hola wönunia andrö; no iböda gambölönia, ba nemali andrö, ba no i''ebua''ö galitö sihola-hola, si manga-manga hadia ia, fasui, ba ma''uwu Yakobo.', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 4, 'No ikhai wanania, si mane emali, abe''e gambölönia si mane ba zi fa''udu, ba no ahori ibunu zomasi ira famaigi, ba nose nono Ziona alawe; no ilau mbakhu-bakhu dödönia, hulö galitö.', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 5, 'Amaedola nemali sa''ae Zo''aya, no ise''egö Ndraono Gizeraeli; no ifufu gödo khöra fefu; hati khöra, ba no idudugö; ba no falawulaete wangarö-ngarö nono Yuda alawe ibe''e.[2]', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 6, 'No ideha gölira, si mane ba kabu; no ifufu naha gowuloa khöra; olifu mbanua Ziona gowasa ba sabato, ibe''e Yehowa, ba no itibo''ö razo, fabaya ere, ba mbakhu-bakhu dödönia andrö.[3]', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 7, 'No lö ba dödö Zo''aya naha wame''e sumange andrö khönia, no itibo''ö ba dödönia ni''amoni''ö andrö khönia; no ilulu ba danga nemali gödora andrö; no mu''ao-ao ira ba gosali Yehowa, si mane na baŵa gowasa.', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 8, 'No ihonogöi Yehowa wanudugö öli nono ziona alawe; no ifatörö wanu''a, lö iböda dangania wanudugö, sabu tödö mba''a-ba''a, fabaya öli, ibe''e, no faoma salangu tödö.[4]', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 9, 'No ahöndrö ba danö mbawa gölinia; no ifufu lazinia, no ifatö; razora ba satua khöra, ba no so ba niha baero — no taya goroisa; ba he sama''ele''ö khöra, ba lö''ö sa''ae falukha wama''ele''ö khö Yehowa.[5]', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 10, 'No dumao-dao tou ba danö, lö hede-hede, zalaŵa nono Ziona alawe; no lalau gawu-gawu ba högöra ba no la''onukha gonigoni; lafatugu ira ono Yeruzalema alawe.', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 11, 'Ariri hörögu, ba daŵa hörö andrö, no aukhu bakha narö dotogu; hulö zi fabali bakha dödögu, ba wa''atekiko nono mbanuada andrö alawe, me si mate olofo ndraono, fabaya ono sawuyu, ba newali ba mbanua.[6]', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 12, 'Lamane khö ninara: Heza so wakhe ba agu? Me mate olofo, si mane sesokho famunu, ba newali, ba mbanua, me aetu nosora ba gaheta ninara.', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 13, 'Hadia nibe''egu famaduhu''ö khöu, hadia wamaedou ube''e, ya''ugö ono alawe, Yeruzalema? Hadia ube''e si falaŵalaŵa khöu, ono Ziona? Fa''ebua nasi sa''ae wa''ebua zokhou; ha niha zamadöhö?', '["Sin 78:61; 99:5","Sin 89:41","Yes 5:5","RazII 21:13","Sin 74:9","Yob 16:13; Amaed 7:23"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 14, 'Sama''ele''ö andrö khöu, ba faya, ba si lö asio wangi''ilara khöu; lö nibokaira horöu ba wangefa''ö ya''ugö, taroma li faya ba fanibo ni''i''ilara khöu.[7]', '["Yer 2:8; 5:31; 14:14; 23:16; Hez 13:2","Sin 48:3; 50:2","Faigi 3:46","MozV 28:15"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 15, 'Solau tatawo khöu dozi sanörö, fasi ira ba lafalikhö ira, ba nono alawe andrö, Yeruzalema [lamane]: "Hadia, da''ö mbanua andrö, nibe''era töi, fondrege zi sökhi'' ba, ''omasiö nösi guli danö, ma''afefu''?"[8]', '["Yer 2:8; 5:31; 14:14; 23:16; Hez 13:2","Sin 48:3; 50:2","Faigi 3:46","MozV 28:15"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 16, 'Lafaboka mbawara khöu dozi si fa''udu khöu; fasi ira ba lafatangi mbohara, lamane: "No mafufu! Ya''ia sa''ae mbaŵa nidöna-dönama; no makhamö, no ma''ila!"[9]', '["Yer 2:8; 5:31; 14:14; 23:16; Hez 13:2","Sin 48:3; 50:2","Faigi 3:46","MozV 28:15"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 17, 'No ifalua Yehowa nikhoi dödönia, no ifatörö ba niŵa''önia, ni''oroi''önia, i''otarai götö föna sa''ae — no idudugö lö fa''ahakhö dödö, ba no ibe''e omuso khöu dödö zi fa''udu, khöu — no i''alaŵa''ö dandru zamakao ya''ugö![10]', '["Yer 2:8; 5:31; 14:14; 23:16; Hez 13:2","Sin 48:3; 50:2","Faigi 3:46","MozV 28:15"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 18, 'Angaröfi li Zo''aya, ya''ugö ono alawe, ono Ziona; alakha mowöi daŵa hörö, hulö gelea, bongi ma''ökhö; böi olombase, böi ibadugö ia ono hörö khöu.[11]', '["Yer 14:17","Sin 62:9","RazII 6:29"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 19, 'Labu, angarö-ngarö ba zi bongi, na mörö niha; faduwa dödöu, timba nidanö, ba duduma hörö Zo''aya; oro''ö khönia dangau, ba wangorifi iraonou, si mate olofo, ba watalinga newali, fefu.[12]', '["Yer 14:17","Sin 62:9","RazII 6:29"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 20, 'Nehegö, ya''ugö Yehowa, faigi: ha khö ölau zi manö! Hadia, la''a nonora ira alawe, iraono andrö, rorogöföra? Hadia, tebubunu gere, fabaya sama''ele''ö, ba ni''amoni''ö andrö khö Zo''aya?[13]', '["Yer 14:17","Sin 62:9","RazII 6:29"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 21, 'No so tou ba danö, ba newali, ndraono, awö zatua: ono alawe khögu ba ono matua khögu, ba no mate ni''ö''ötö; no mange''e ndra''ugö, me baŵa wönu andrö, khöu — no mamunu niha ndra''ugö, lö fa''ahakhö dödö.', '["Yer 14:17","Sin 62:9","RazII 6:29"]', NULL),
  (3476377, 'OT', 'Ngenu-Ngenu Yeremia', 2, 22, 'No ökaoni — nifogaoni ba gowasa — gameta''uö khögu, fasui, ba samösa lö''ö, me baŵa wönu Yehowa andrö, soloi ba saefa; nirorogögu andrö, ni''e''ebuagu, ba no ihori emaligu andrö.', '["Yer 14:17","Sin 62:9","RazII 6:29"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 1, 'Ya''odo niha andrö, sangila famakao, ba mbözi-bözi andrö khönia ba wönunia.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 2, 'Ya''odo nifasaonia, nifatörönia ba zogömi-gömi ba ba zi lö haga.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 3, 'Khögu ifonumanumalö dangania, ma''öma''ökhö.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 4, 'Sariri nösigu ba uligu, ibe''e; tölagu, ba no irasa.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 5, 'No ifasui ndra''odo, wama''anö langu ba famakao.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 6, 'No ibe''e ba zogömi-gömi ndra''odo, amaedola zi mate, lö fangorifi sa''ae.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 7, 'No ikölini ndra''o kara, lö lala, no abua rate khögu, ibe''e.[1]', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 8, 'Ba he mu''ao ndra''o, he ŵa''ae ebua ligu, ba iba''a wangandrögu.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 9, 'Iba''a lalagu kara sebua; ifufu nitörögu ena''ö.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 10, 'Amaedola mberua sanaronaro ia khögu, amaedola zingo ba mbini-mbini.[2]', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 11, 'Selungu lalagu ibe''e; no isasawi ndra''odo; adudula ndra''odo ibe''e.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 12, 'No ikhai wanania, ba no ibe''e tandra wana ndra''odo.[3]', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 13, 'No ifatörö ba mbuagu nono wana khönia.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 14, 'No tobali fama''iki ndra''o ba mbanuama fefu, ayara ma''öma''ökhö.[4]', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 15, 'No i''abusoi''ö ndra''o safeto, no ifabadugö khögu nidanö mbulu mbala.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 16, 'Ubohagö nene ibe''e, ba ufagaölö ndra''o bawu.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 17, 'No ötayaigö wa''ohahau dödögu, olifu ndra''o zi sökhi.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 18, 'Ba umane: No taya wa''abe''egu, ba fanötönagu khö Yehowa.', '["Yob 3:23","Yob 10:16","Yob 16:12; Sin 7:13","Yob 30:9"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 19, 'Törö tödöu wa''anumanagu ba folohi ya''odo andrö, ba idanö mbulu mbala andrö, awö langu andrö!', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 20, 'U''angera-ngeragö, ba iköwö ia bakha tödögu.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 21, 'Da''ö utanö ba dödögu, ba andrö udöna-döna:', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 22, 'Lö''ö sa atö saetu na wa''ebua dödö Yehowa, lö sahori na wa''ahakhö dödönia;', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 23, 'ero mahemolu, ba ifuli bohou, abölö wa lö faröi ndra''ugö![5]', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 24, 'Tana khögu Yehowa, iŵa''ö tödögu, andrö wa khönia udöna-döna.[6]', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 25, 'Sebua tödö Yehowa ba zanötöna khönia, ba niha sangalui ya''ia.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 26, 'Si sökhinia, tadöna-döna wangorifi andrö khö Yehowa, lö hede-hede.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 27, 'Sökhi ba niha, na ilu''i galo mbagi andrö, fatua ono matua na ia.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 28, 'Ya dumao-dao lö awö ba lö hede-hede, na ihare''ö ba mbaginia.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 29, 'Ya fa''ago bawa ia ba gawu-gawu tou — ma atö so na dötönafö;', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 30, 'Yamu''oro''ö mbo''önia ba zamalisi ya''ia, ya abuso fango''aya.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 31, 'Tenga si lö mamalö-malö wanibo Zo''aya.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 32, 'Na no ifatörö wa''abu dödö, ba [ifuli] ahakhö dödö, ba wa''afahöna wa''ebua dödönia andrö.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 33, 'Tenga sa fa''omasinia wamakao ba famusi tödö nono niha.', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 34, 'Wa lahundragö fefu nira''u andrö, ba danö, wa lawu''ai huku,', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 35, 'ba zanehe Wondrege Zalaŵa,', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 36, 'wa lafuyu''ö huhuo niha, ba hadia, lö i''ila So''aya?', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 37, 'Ha niha zanguma''ö, ba no itörö, na tenga moroi ba li Zo''aya?[7]', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 38, 'Hadia, tenga umbu zi lö sökhi ba umbu zi sökhi göi mbawa Wondrege Zalaŵa?[8]', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 39, 'Hadia wa mangarö-ngarö manö niha, sagötö ya''ia? Ba horönia ya mangarö-ngarö zamösana!', '["Sin 30:6","Sin 16:5; 73:26; Yer 10:16","Sin 33:9","Yes 45:7"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 40, 'Datafaigi döröŵada, ta''alu-alui, ba tafuli ita khö Yehowa!', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 41, 'Datafazaŵa dödöda ba tangada khö Lowalangi ba zorugo!', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 42, 'No elungu ita, ba no tandro-tandrofö ita — ba lö nibe''eu aefa [da''ö].', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 43, 'No öfobalu-balu ndra''ugö fönu ba no ögohi ndra''aga, no öbubunu ndra''aga, lö fa''ahakhö dödö.', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 44, 'No öbalugö ndra''ugö lawuo, fa tebai isösö fangandrö.', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 45, 'No öbali''ö sasao ba sogoro niha ndra''aga, ba hunö niha baero.[9]', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 46, 'No lafaboka mbawara khöma dozi si fa''udu khöma.[10]', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 47, 'Fehokha mbu ba kohokoho gurakhama, ba fa''adudu ba fa''afufu.', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 48, 'Mangele daŵa hörögu, ba wa''afufu nono alawe andrö, ono niwada.[11]', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 49, 'Mo''ala''ala manö hörögu, lö mamalö-malö,[12]', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 50, 'balazi ifaigi moroi yaŵa, balazi ifaigi lala Yehowa, moroi ba zorugo.', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 51, 'Afökhö bakha dödögu ibe''e [taŵa] hörögu andrö, ba nono alawe andrö, banuada, fefu.', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 52, 'No lagohi ndra''o, nifolohi fofo, si fa''udu khögu, lö börö-börö,', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 53, 'no la''etu''ö nosogu ba gohokoho danö ba no lahawui ndra''o kara.[13]', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 54, 'No ilawui högögu idanö, ba umane: si mate ndra''o.', '["KorI 4:12","Faigi 2:16","Faigi 3:11","Faigi 2:18","Yer 38:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 55, 'Ba no u''angaröfi li döimö, ya''ugö Yehowa, moroi ba wondrege gohokoho.[14]', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 56, 'Ba no öfondrondrongo we''aogu andrö: "Böi duhö dögi dalingau; okafui dödögu, tolodo!"', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 57, 'No ahatö ndra''ugö, me mu''aodo khöu, ömane: "Böi busi dödöu!"', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 58, 'No öfatunö huhuogu, ya''ugö Yehowa, no ö''orifi ndra''odo.', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 59, 'No ö''ila wamakao ya''odo andrö, ya''ugö Yehowa: ohe ba lala huhuogu andrö!', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 60, 'No anehe''ö dödöra ba wolau khögu, fefu nifakhaira khögu.', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 61, 'No örongo wango''ayara andrö, ya''ugö Yehowa, fefu nifakhaira khögu,', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 62, 'huhuo zi fa''udu khögu ba tödöra fa''udusa khögu, ma''öma''ökhö.', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 63, 'Faigi, ba wedadaora ba ba wemaosora, ba ayara ndra''odo.', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 64, 'Ya''ugö Yehowa zanulöni khöra, dali nilau dangara;[15]', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 65, 'ö''abösi''ö dödöra — ba ya tohare khöra wangelifiu!', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476378, 'OT', 'Ngenu-Ngenu Yeremia', 3, 66, 'Ögohi ira ba wönumö ba öhori ira, barö mbanua khö Yehowa!', '["Sin 130:1","Rom 2:6"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 1, 'Ha lö aitö gana''a andrö, ha lö atobali mbalaki, ba tetibo mani-mani ni''amoni''ö, ba watalinga newali fefu!', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 2, 'Ono matua omasiö andrö, ba Ziona, nifatimba balaki, ba no timba mbowoa tanö, nilau danga zamöbözi bowoa![1]', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 3, 'He asu ana''a, ba i''oro''ö mbagi zusu, ifaenu nononia; ba ono mbanuada andrö, alawe, ba no si lö fa''ahakhö dödö, no timba ganöwö ba danö si mate.', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 4, 'No falemba ba gararo lela nono sawuyu, ba wa''owökhi dödö andrö; mangandrö gö ndraono, ba lö same''e khöra.', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 5, 'Si manga gö sami mege, ba no mate olofo baewali; nifokaso baru luo mege ba wangahagi, ba no latalagui golawua.', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 6, 'Noa sa ebua horö mbanuada andrö, moroi ba horö Zodoma no, nibali''ö arö, ha mamö''i hörö wa''ara, ba tenga nibabaya tanga.', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 7, 'Safusi moroi ba mbötua zalaŵara, safusi moroi ba nösi zusu; soyo moroi ba duturu gara soyo nösira, no timba weremata nila nga''eura.', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 8, 'Ba noa sa''ae aitö moroi ba ndra''i mbowoa wamaigida, lö oroma döi niha, ba newali; falemba ba dölara gulira, no oköliköli, timba geu.', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 9, 'Ohahau dödö zi mate ba mbawa zi''öli mege, moroi ba zi mate olofo andrö; sariri manö, no timba nifahö tödö, me lö bua nowi.', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 10, 'Ira alawe sahakhö tödö, ba labe''e bawu nonora tangara; labali''ö öra, ba wa''adudu nono alawe andrö, ono mbanuada.[2]', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 11, 'No i''oigö mbakhu-bakhu dödönia Yehowa, no ilau hola-hola wönunia andrö ba no i''ebua''ö galitö ba Ziona, si manga latalata.', '["Yer 19:11","Yer 19:9; Faigi 2:20"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 12, 'Lö''ö sa faduhu mena''ö dödö razo ba guli danö, ba he tödö nösi guli danö ma''afefu, wa atu''a ba mbawa göli Yeruzalema zanuwö ya''ira, emalira andrö.', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 13, 'Börö horö zama''ele''ö andrö khöra ba horö gere khöra, si no mame''e aduwa ba mbanua ndro zatulö, wa alau-lau ira, timba zau''a,', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 14, 'ba newali; si no ta''unö do ira, tobali tebai tababaya nukhara.', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 15, '"Mihole''ö ami! Si ra''iö!" — lamanö fönara —, "mihole''ö ami! mihole''ö ami! böi fatöfa ami!" Na moloi ira ba na alau-lau, ba lamane niha baero: Lö tola sa''ae la''iagö da''e![3]', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 16, 'Ba Yehowa zamazawili ya''ira, lö''ö sa''ae ifaigi-faigi ira. Lö ba dödönia gere, lö sahakhö dödönia si no tohare huwa.', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 17, 'Ha wa''ara ariri manö höröda, wamaigi fangorifi khöda zaya-zaya gölö! Ba naha wanaro andrö khöda tadöna-döna niha, si lö manolo [ya''ita].', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 18, 'Ladaro-darogö nihundragöda tanö, tobali tebai tatörö newali khöda; no ahatö wozu khöda, no irugi baŵada, fozu sa''ae.', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 19, 'Alio gahe zolohi ya''ita, moroi ba moyo ba dalu mbanua, lagohi ita ba hili, latarogö ita ba danö si mate.', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 20, 'Nosoda andrö [razo], nibayoini Yehowa, ba no alau ba lösu-lösu andrö khöra — ya''ia andrö, niŵa''öda tödöda: Ba lumönia auri ita, ba niha baero.', '["MozIII 13:45"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 21, 'Ya omuso dödöu, ya owua-wua, ya''ugö ono Ndraono Gedomo alawe sowanua ba danö Usi; irugi dania ndra''ugö göi mako andrö; mabu dania ndra''ugö ba öheta mbalu-balumö![4]', '["Yer 25:15; 49:12","Yes 40:2"]', NULL),
  (3476379, 'OT', 'Ngenu-Ngenu Yeremia', 4, 22, 'No abu''a gömöu, ya''ugö ono Ziona alawe, lö''ö sa''ae itibo''ö ndra''ugö; ba ömöu, ya''ugö ono Ndraono Gedomo, ono alawe, ba i''alui, ibokai horöu.[5]', '["Yer 25:15; 49:12","Yes 40:2"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 1, 'He Yehowa, törö tödöu zi no göna ndra''aga; faigi, ba nehegö wa''ailama andre!', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 2, 'Si so khöma mege, ba no möi ba danga niha bö''ö, ba omoma ba no la''okhögö Dawa baero.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 3, 'Si lö ama ndra''aga sa''ae, no lakha mbanua ninama.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 4, 'Öma idanö, ba ni''öli, ba awena falukhaga geuma, na mabe''e mböli.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 5, 'Falu''i khöma zolohi ya''aga; no erege dödöma, lö labe''e molombase ndra''aga.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 6, 'No ma''oro''ö dangama ba Ndrawa Miserayi, ba ba Ndrawa Asiria, ena''ö masöndra zabönö öma.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 7, 'No molalö ndra tuama; lö ya''ira sa''ae, ba ya''aga zolu''i olalöŵara.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 8, 'Sawuyu zamatörö ya''aga; lö sangefa''ö ya''aga ba dangara.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 9, 'Sata''u mate ndra''aga wangai göma; ba zi''öli nemali andrö, ba danö si mate.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 10, 'No aitö gulima, hulö mbowoa, ba wa''afökhö wa''olofo andrö.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 11, 'Ira alawe ba Ziona, ba no lahoröni, fabaya ono alawe, ba mbanua mado Yuda misa.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 12, 'No lataŵi zalaŵa tangara, ba bawa zatua, ba lö ba dödöra.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 13, 'Ono matua, ba no labe''e sanutu fakhe, ba salau-lau ndraono ba norora eu.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 14, 'Lö''ö sa''ae möi ba mbawa göli zatua; ba no labato wolau biola ono matua.[1]', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 15, 'No taya wa''omuso dödöma; no tobali fangarö-ngarö wanunöma.', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 16, 'No aekhu tou zaembu ana''a andrö moroi ba högöma: alai ndra''aga, me no mafazökhi horö!', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 17, 'Ba da''ö, wa tobali sofökhö dödöma; ba da''ö, wa no balunö höröma;', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 18, 'ba hili Ziona andrö, me no afufu, me ladörö-dörö asu gatua.[2]', '["MozI 34:20","Neh 4:3"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 19, 'Ba ya''ugö Yehowa, ba si lö aetu fa''asalaŵa; dadaomamö andrö, ba götö-götö wa''ara.[3]', '["Sin 9:8; 90:2; 102:13","Yer 31:18"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 20, 'Hana wa lö mamalö-malö ö''olifugö''ö ndra''aga, hana wa ö''erogö ndra''aga, sagötö ya''aga?', '["Sin 9:8; 90:2; 102:13","Yer 31:18"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 21, 'He Yehowa, halö mangawuli ndra''aga khöu, ba mafuliga; bohouni mbaŵama, si mane ba götö föna![4]', '["Sin 9:8; 90:2; 102:13","Yer 31:18"]', NULL),
  (3476380, 'OT', 'Ngenu-Ngenu Yeremia', 5, 22, 'Ma no alua ötibo''ö ndra''aga; hadia, no falawu wönumö khöma?', '["Sin 9:8; 90:2; 102:13","Yer 31:18"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 1, 'Me no arakha 30 fakhe ndra''o, me sodo ba ni''oloi''ö andrö ba mbewe Khebara, ba zi melima ba mbawa si öfa, ba teboka mbanua ba u''ila gangilata khö Lowalangi.', '["RazII 24:15","Fam 1:15"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 2, 'Ba zi melima ba mbawa da''ö (no töra mendröfa fakhe, me te''oloi''ö razo Yoyaki)[1]', '["RazII 24:15","Fam 1:15"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 3, 'ba humede Yehowa khö Hezekieli, ono Mbusi, ere, ba danö Galedaia, ba mbewe Khebara, ba ira''u ia tanga Yehowa, ba da''ö.', '["RazII 24:15","Fam 1:15"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 4, 'Ba u''ila, ilabu angi sabölö-bölö, moroi yöu, ba fao lawuo sebua, ba alitö si no amaedola nimbayaini, ba si no moragi lawuo andrö, fasui, ba moroi bakha ba galitö andrö, ba so zihaga, timba dola garamba, si takile.[2]', '["RazII 24:15","Fam 1:15"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 5, 'Ba öfa nga''eu zi oroi bakha ba galitö andrö saliŵa-liŵa ba danö. Ba famaigida ya''ira, ba no monga''eu niha.[3]', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 6, 'Ba dozi ira, ba öfa''öfa mbawa ba öfa''öfa gafi.[4]', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 7, 'Ba ahera, ba no adölö, ba lalua kahera, ba no si mane lalu''a kahe nono zaŵi ba si takili, timba wa''atakile döla garamba si no mudukhu.', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 8, 'Ba barö gafira, ba tanga niha, föna ba furi ba faoma fatambai, öfa''öfa.', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 9, 'Ba bawa zi öfa andrö ba afira — oi si fatöfa ba nawöra gafi andrö — ba lö labali''ö ira, na mofanö ira, idölö manö ia zamösana.', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 10, 'Ba famaigida bawara, ba tanö föna, ba no bawa niha, ba ba gambölö, ba bawa zingo, ba zi öfa andrö, ba ba gabera, ba bawa zaŵi si matua, ba zi öfa andrö, ba bawa moyo, ba zi öfa, mibakha.[5]', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 11, 'Ba afira, ba si no mubologö miyaŵa: dua-dua zi no fatöfa, ba dua-dua mbalu-balu mbotora.[6]', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 12, 'Ba dozi, ba ladölö manö ira; heza i''o''ou ira Eheha, ba da''ö möi ira; ba lö laholehole''ö ira, na mofanö ira.', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 13, 'Ba ba gotalua zaliŵa-liŵa andrö, ba hulö mbo galitö, wamaigigu, hulö zulu sangörö-ngörö ba ba gotalua zaliŵa-liŵa andrö, ba sihaga galitö andrö, ba i''otarai galitö andrö gari mbanua.', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 14, 'Ba mangörö-ngörö zaliŵa-liŵa andrö, si mane haga gari mbanua.', '["Fam 4:6","Faigi 10:14","Fam 4:7","Yes 6:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 15, 'Ba me ufaigi na zaliŵaliwa andrö, ba hiza, ba sambuasambua gaolo ba danö, ba ngai zaliŵa-liŵa andrö si öfa nga''eu.', '["Fam 4:8"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 16, 'Ba gaolo andrö ba famazökhi ya''ia, ba famaigida, ba no timba wa''atakile weremata wirusi. Ba ha sambua wonga''eu zi öfa andrö; ba famaigida ba famazökhi ya''ia, ba hulö na bakha ba nawönia so zi sambua.', '["Fam 4:8"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 17, 'Miföna ba mifuri, ba faoma fatambai lasaŵa na mofanö; lö tobali, na mofanö.', '["Fam 4:8"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 18, 'Ba gama gaolo, ba no alaŵa ba sata''u ita; ba no si falawu hörö gama andrö, fasui, ba zi öfa andrö fefu.[7]', '["Fam 4:8"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 19, 'Ba na mofanö zaliŵa-liŵa andrö, ba mofanö gaolo andrö, ba ngaira, ba na lafazaŵa ira moroi ba danö saliŵa-liŵa andrö, ba muzaŵa göi gaolo.', '["Fam 4:8"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 20, 'Heza ifatörö ira Eheha, ba da''ö lasaŵa, ba ero na lafazaŵa ira, ba fao göi gaolo, me no ba gaolo so Geheha zaliŵa-liŵa andrö.', '["Fam 4:8"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 21, 'Na mofanö da''ö, ba mofanö göi gaolo, ba na labadugö ira, ba ahono göi gaolo, ba na lafazaŵa ira, moroi ba danö, ba fao göi wezaŵa gaolo, me no ba gaolo so Geheha zaliŵa-liŵa andrö.', '["Fam 4:8"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 22, 'Ba yaŵa zaliŵa-liŵa andrö, ba so zi hulö mbanua si yaŵa, si takile, timba mbaluri, sata''u ita, no tebolosö yaŵara.', '["Sin 29:3","Fam 4:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 23, 'Ba barö zi hulö mbanua andrö, ba no tebolosö gafira, no faondra; ba no dua zageu gafi, balu-balu mbotora.', '["Sin 29:3","Fam 4:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 24, 'Ba urongo ruru gafira, no timba wegoso-goso nidanö sebua, timba mbanua khö Zi lö ambö fa''abölö; na mowaö-waö ira, ba timba werararara ba golombaseŵa zanuwö li weruru andrö; ba na labadugö ira, ba sadada manö gafira.', '["Sin 29:3","Fam 4:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 25, 'Ba terongo ruru yaŵa zi hulö mbanua andrö, yaŵara; ba na labadugö ira, ba sadada manö gafira.[8]', '["Sin 29:3","Fam 4:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 26, 'Ba yaŵa zi hulö mbanua andrö, yaŵara, ba no hulö weremata nila wamaigida, amuata dadaoma, ba so zidadao ba dadaoma andrö, hulö niha wamaigida, yaŵa.[9]', '["Sin 29:3","Fam 4:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 27, 'Ba u''ila haga, timba wa''atakile döla garamba, si takile, timba haga galitö, bakha ba nahia, i''otarai zi hulö zolania wamaigida, miyaŵa; ba i''otarai zi hulö zolania ba mitou, ba no hulö galitö, wamaigigu. Ba si tefasui ya''ia,', '["Sin 29:3","Fam 4:2"]', NULL),
  (3476381, 'OT', 'Hezekieli', 1, 28, 'ba no haga: si mane dumi, ni''ilada ba lawuo na luo moteu, si manö wamaigida haga andrö, fasui. Si manö wa''oroma lakhömi Yehowa andrö wamaigigu. Ba me u''ila, ba ufalögu tou ndra''o. Ba urongo li zihede.', '["Sin 29:3","Fam 4:2"]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 1, 'Ba imane khögu: He ono niha, zizio, ena''ö fahuhuodo khöu!', '["Faigi 1:8; FetI 3:14."]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 2, 'Ba möi ba dödögu, Geheha, me imanö khögu, da''ö zamazizio ya''odo, ba urongo li zi fahuhuo khögu.', '["Faigi 1:8; FetI 3:14."]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476382, 'OT', 'Hezekieli', 2, 3, 'Ba imane khögu: "He ono niha! Da''ufatenge ndra''ugö ba ma''uwu Gizeraeli andrö, ba niha andrö si no fa''ero, si no mangerogö ya''odo, ya''ira ba ira tuara mege, ba no la''erogö ndra''o, irugi ma''ökhö andre.', '["Faigi 1:8; FetI 3:14."]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 4, 'Ba niha sabe''e bawa ba sabe''e tandro ufatenge ndra''ugö, ba ömane khöra: Da''ö niŵa''ö Zo''aya Yehowa!', '["Faigi 1:8; FetI 3:14."]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 5, 'Ba he lafondrondrongo, ba he lö ba dödöra — me no niha sabe''e tandro ira —, ba ya aboto zui ba dödöra, wa no tefataro khöra zama''ele''ö.', '["Faigi 1:8; FetI 3:14."]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 6, 'Ba ya''ugö, ono niha, ba böi ata''ufi ira, ba he fehedera, ba böi ata''ufi, na amaedola lato ira khöu ba na amaedola za''a-sa''a mao, ba na tongo zi fatewu ndra''ugö yomo; böi ata''ufi wehedera, böi tokea''ö ibe''e bawara, me no niha sabe''e tandro ira.[1]', '["Faigi 1:8; FetI 3:14."]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 7, 'Taroma ligu öfa''ema khöra, he lafondrondrongo, ba he lö''ö; no ha sambalö fa''abe''e dandro khöra.', '["Faigi 1:8; FetI 3:14."]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 8, 'Ba ya''ugö, ono niha, ba fondrondrongo niŵa''ögu khöu; ya''ugö, ba böi sabe e tandro ndra''ugö, si mane niha sabe''e tandro andrö. Faboka mbawau ba a nibe''egu khöu."', '[]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 9, 'Ba ufaigi, ba hiza danga ni''oro''ö khögu; ba sura ba danga andrö.', '[]', NULL),
  (3476382, 'OT', 'Hezekieli', 2, 10, 'Ba ibologö fönagu, ba no musura ba dete ba barö, ngenu-ngenu ba fangarö-ngarö ba fa''a-la''alaisa nitanö bakha.', '[]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 1, 'Ba imane khögu: He ono niha, a zi so fönau; a nga''ölu zura andre, ba ae''e ba hede ba ma''uwu Gizeraeli.', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 2, 'Ba ufaboka mbawagu, ba ibe''e ögu nga''ölu zura andrö, ba imane khögu:', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 3, 'He ono niha, be''e ö dalumö ba ösi mbetu''amö nga''ölu zura andre, nibe''egu khöu. Ba u''a, ba ami ba mbawagu, timba ŵe ŵani,[1]', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 4, 'Ba imane khögu: He ono niha, labu! ae ba ma''uwu Gizeraeli ba fa''ema khöra daroma ligu.', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 5, 'Tenga sa ba niha si lö aboto ba dödöda li ba tenga ba zabe''e lela, no ba ma''uwu Gizeraeli tefatenge ndra''ugö;', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 6, 'tenga ba ngawalö niha baero, si lö aboto ba dödöda li ba si no abe''e lela, si lö ö''ila li, no ba khöra ufatenge ndra''ugö. Ya''ira ba tenga si tebai aboto ba dödö niŵa''öu!', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 7, 'Ba ma''uwu Gizeraeli andrö, ba si lö edöna mamondrongo khöu, me no te khöra wamondrongo khögu; noa sa sabe''e angango ba sabe''e tödö ma''uwu Gizeraeli ma''afefu.', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 8, 'Ba hiza, ba u''abe''e''ö mbawau, si mane bawara, ba u''abe''e''ö gangangomö, si mane angangora: timba indra''indra,', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 9, 'sabe''e moroi ba gowe, gangangomö dania, ube''e. Böi ata''ufi ira, ba böi tokea''ö khöra, me no niha sabe''e tandro ira![2]', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 10, 'Ba imane khögu: He ono niha, taroma ligu andre fefu, niŵa''ögu khöu, ba ötanö ba dödöu ba öbe''e mbörö dalingau, ba wamondrongo!', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 11, 'Ba labu sa''ae, ba ae ba ni''oloi''ö andrö, iwami, ba hede khöra, ömane khöra. Da''ö niŵa''ö Zo''aya, Yehowa…! he lafondrondrongo, ba he lö''ö.[3]', '["Sin 19:11; Faigi 15:16; Fam 10:9,11","Yes 50:7; Faigi 1:18","Faigi 2:7"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 12, 'Ba ifazaŵa ndra''o Eheha ba urongo moroi furigu ruru ziheu sabölö-bölö, me ifazaŵa ia lakhömi Yehowa andrö, moroi ba nahania,[4]', '["Mikh 1:3; Sakh 2:13"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 13, 'awö ruru gafi zaliŵa-liŵa ba danö andrö, si fabaya ba nawöra, awö ruru gaolo, si fao, awö ruru ziheu, sabölö-bölö.', '["Mikh 1:3; Sakh 2:13"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 14, 'Ba ifazaŵa ndra''o Eheha, i''ohedo misa, ba mowaö-waö ndra''o, sabu tödö ndra''odo, ba wehufa dödögu andrö, no tohare khögu danga Yehowa.', '["Mikh 1:3; Sakh 2:13"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 15, 'Ba urugi ni''oloi''ö andrö, ba Deli Abibi, ba mbewe Khebara, ba u''iagö da''ö khöra, fitu bongi ndra''o khöra, lö tödötödögu.', '["Mikh 1:3; Sakh 2:13"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 16, 'Ba me no irugi fitu bongi, ba so niŵa''ö Yehowa khögu, imane:', '["Yer 62:6; Faigi 33:7","Faigi 18:24"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 17, 'He ono niha, no ufataro ndra''ugö sanaro ma''uwu Gizeraeli, ba na örongo daroma ligu, ba öfangelama ira khögu, ö''o''ö niŵa''ögu.[5]', '["Yer 62:6; Faigi 33:7","Faigi 18:24"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 18, 'Na uŵa''ö ba zi no mangerogö Lowalangi: Si mate ndra''ugö! ba na lö öfangelama ia, na lö hede-hedeu, ba wamangelama si no mangerogö Lowalangi, ba lalania elungua andrö, ba wangorifi ya''ia, ba si mate ia, ya''ia, si no mangerogö Lowalangi, börö horönia andrö, ba donia, ba ba dangau so, khöu usugi.', '["Yer 62:6; Faigi 33:7","Faigi 18:24"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 19, 'Ba na öfangelama zi no mangerogö Lowalangi, ba na lö iböhöli horönia, ba he lala elungua andrö khönia, ba si mate sa ia, börö horönia andrö, ba ya''ugö, ba sauri.', '["Yer 62:6; Faigi 33:7","Faigi 18:24"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 20, 'Ba na iböhöli wa''atulö dödönia satulö tödö, na ilau zi lö atulö, ba na ufatörö khönia zi te''ala ia, si mate ia, ba na lö nifangelamau ya''ia, ba si mate ia, ba horönia andrö, ba bua-buania si sökhi andrö, ba lö tebe''e harenia; ba donia andrö, ba ba dangau so, khöu usugi.[6]', '["Yer 62:6; Faigi 33:7","Faigi 18:24"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 21, 'Ba na öfangelama zatulö tödö andrö, fa böi molalö ia, ba na lö mosala ia, ya''ia, satulö tödö andrö, ba sauri ia, me no öfangelama ia, ba ya''ugö, ba sauri [göi].', '["Yer 62:6; Faigi 33:7","Faigi 18:24"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 22, 'Ba tohare khögu danga Yehowa ba da''ö, ba imane khögu Yehowa: Faoso, ae misa, ba ndraso andrö, ba ba da''ö muhededo khöu dania.', '["Faigi 1:3","Faigi 2:2"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 23, 'Ba maoso ndra''o, möido mitou ba ndraso, ba hiza, no so ba da''ö lakhömi Yehowa, si mane lakhömi andrö, ni''ilagu ba mbewe Khebara no; ba ufalögu tou ndra''o.[7]', '["Faigi 1:3","Faigi 2:2"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 24, 'Ba möi ba dödögu Geheha, samazizio ya''o; ba humede ia khögu, imane khögu: Ae yomo ba nomou, ba kusi mbawandruhö furiu.[8]', '["Faigi 1:3","Faigi 2:2"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 25, 'Ba hiza, ya''ugö ono niha, laböbö dania ndra''ugö, fa böi mangörö-ngörö ndra''ugö khöra.', '["Faigi 1:3","Faigi 2:2"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 26, 'Ba falemba lelamö ba gararou ube''e, ena''ö si lö hede ndra''ugö, fa böi möi''ö sanegu ya''ira, me no niha sabe''e tandro ira.', '["Faigi 1:3","Faigi 2:2"]', NULL),
  (3476383, 'OT', 'Hezekieli', 3, 27, 'Ba na muhededo khöu, ba ubokai mbawau, ba ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa…! Sedöna mamondrongo, ba yamufondrondrongo, ba si lö edöna, ba yamubato! me no niha sabe''e tandro ira.', '["Faigi 1:3","Faigi 2:2"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 1, 'Ba ya''ugö ono niha, halö gara tembo ba be''e fönau ba sura ba dete yaŵa wamaedo mbanua Yeruzalema.', '["MozIV 14:34","Faigi 3:25"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 2, 'Ba fazökhi mba''a-ba''a ba lau malige zanuwö khönia; lau fari khönia, fa''aso zanuwö ya''ia ba fasui ia famoto göli kara.', '["MozIV 14:34","Faigi 3:25"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 3, 'Ba khöu halö gali si''öli ba be''e ba''a-ba''a si''öli ba gotaluami mbanua, ba otahögö mbanua, ena''ö tobali nisuwö ia; ya''ugö zanuwö. Ya tobali famaedo da''ö ba ma''uwu Gizeraeli.', '["MozIV 14:34","Faigi 3:25"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 4, 'Ba ya''ugö, ba be''e ngaimö ba halö norou horö ma''uwu Gizeraeli andrö: götö wa si manö wemöröu tou, ba öbe''e langölangömö horöra.', '["MozIV 14:34","Faigi 3:25"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 5, 'Ba ha me uga fakhe horöra mege, ba ubali''ö ngaluo khöu — 390 ngaluo — ba langölangömö horö ma''uwu Gizeraeli andrö.[1]', '["MozIV 14:34","Faigi 3:25"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 6, 'Ba na no ahöwö mbongi andrö khöu, ba fuli be''e ngaimö kambölö, ba be''e langölagömö horö ma''uwu Yuda, 40 wongi, döfidöfi, ba sara-sara ngaluo u''erai khöu.', '["MozIV 14:34","Faigi 3:25"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 7, 'Ba otahögö wanuwö Yeruzalema andrö, ba oro''ö khönia da''iomö, nifahoi baru, ba mama''ele''ö ndra''ugö khöra.', '["MozIV 14:34","Faigi 3:25"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 8, 'Ba hiza, ba uböbö ndra''ugö, fa tebai öbali-bali''ö ndra''ugö, irege no ahöwö khöu mbongi wanuwö andrö.[2]', '["MozIV 14:34","Faigi 3:25"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 9, 'Ba halö khöu gandru ba se''iri ba harita niha ba harita side-ide ba rigi ba rigi ö manu, lau ba nahia ba bali''ö roti khöu; götö wa''ara andrö, wa öbe''e ngaimö tou, si 390 wongi, ö''a ia.', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 10, 'Ba ötulo göu, ba wemanga ya''ia, 20 rufia fanimba ma''ökhö; ba öfo''otalua wemanga.', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 11, 'Ba öu idanö, ba ösu''a göi, samba botoboto ma''ökhö, ba öfo''otalua göi wamadu.', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 12, 'Öbali''ö kue ze''iri, ba wemanga ya''ia, ba tai niha, soköli öbe''e eu, ba wogore ya''ia, ba zanehe ira.', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 13, 'Ba imane Yehowa: Si manö göi dania Ndraono Gizeraeli: Ö si ta''unö la''a ba mbanua niha baero, ba nitibo''ögu ya''ira.[3]', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 14, 'Ba umane: He Yehowa, So''aya! Hiza, lö urai göna si ta''unö ba lö urai u''a zi mate, ba he nisasawi gutu ndru''u, i''otarai iraono ndra''o, irugi ma''ökhö andre, ba lö irai itörö mbawagu sobou.[4]', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 15, 'Ba imane khögu: Ba hiza, ba utehe khöu dai zaŵi, salahi dai niha, eu göu andrö.', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 16, 'Ba imane na khögu: He ono niha, hiza, ufatö dania ba Yeruzalema zi''o öra andrö, ba ni tulo göra ba fao wa''abu dödö, na la''a ia, ba nisu''a nidanö, ba fao wa''atobali dödö, na labadu,[5]', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476384, 'OT', 'Hezekieli', 4, 17, 'ena''ö sambö ö ba sambö idanö ira ba ena''ö faoma tobali dödöra, fa ariri ira, ba horöra andrö.', '["Hos 9:3","Yes 65:4; HalZin 10:14","MozIII 26:26"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 1, 'Ba ya''ugö ono niha, halö khöu wöda satarö, be''e fanöwö; halö ia, ba fatörö ba högöu ba ba gambiu. Ba aefa da''ö, ba halö waliera, ba otölu mbu andrö.', '["MozIV 15:38"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 2, 'Si saraö, ba ötunu ba galitö, ba dalu newali ba mbanua, na no numalö mbongi wanuwö andrö, ba si saraö, ba öhalö, ba fazawili ba zi fasui, ötimba si''öli, ba si saraö, ba öfazawili ba nangi, ba usöbi zi''öli moroi furi!', '["MozIV 15:38"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 3, 'Ba ha ma''ifu öhalö, ba öfabu''u ba watalinga mbarumö.[1]', '["MozIV 15:38"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 4, 'Ba öhalö zui da''ö ma''ifu, ba ötibo''ö ba galitö, ötunu. Ba da''ö i''otarai alitö sanörö ma''uwu Gizeraeli ma''afefu. Ba ömane ba ma''uwu Gizeraeli fefu:', '["MozIV 15:38"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 5, 'Da''ö niŵa''ö Yehowa, So''aya: Da''ö Yeruzalema andrö, nitaru''ögu ba hunö niha baero, si no tefasui tanö bö''ö.[2]', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 6, 'Ba ya''ira, ba no sabe''e tandro, lö la''o''ö huku andrö khögu, no sebua horö ira, moroi ba niha baero, ba no lafadaö nifakhoigu, moroi ba niha ba danö bö''ö misa, si tefasui ya''ira. No lö ba dödöra huku andrö khögu, ba nifakhoigu andrö, ba lö la''o''ö.', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 7, 'Andrö wa imane So''aya, Yehowa: Me no sabe''e tandro ami, moroi ba niha baero, si tefasui ya''ami, me no lö ni''o''ömi nifakhoigu ba me lö nitöngönimi huku andrö khögu, me lö''ö na''i ni''o''ömi huku ba niha baero andrö ba ngaimi,', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 8, 'andrö wa imane So''aya, Yehowa: Hiza, ulau sa''ae khömi, ufatörö huku khömi, ba zanehe niha baero.', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 9, 'Ba ulau khömi zi lö urai ulau ba si lö''ö sa''ae ulau göi dania, börö zogoro ita andrö khömi, fefu.', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 10, 'Tobali la''a dania nonora ira ama, ba khömi, ba la''a namara iraono, ba ufatörö khömi huku, ba si tosai ya''ami, ba ufazawili misa ba zi fasui fefu.[3]', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 11, 'Andrö: "ba wa''aduhu wa''aurigu" iŵa''ö Yehowa, u''erogö göi ami, börö me no mita''unöi ni''amoni''ö andrö khögu sihokha mbuda andrö khömi ba sogoro ita, fefu, ba lö ahakhö dödögu wamaigi ya''ami ba si lö alimagö ami khögu, ube''e.[4]', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 12, 'Si saraö ya''ami, ba si mate ba wökhö waba ba sahori ba lofo, ba khömi, ba si saraö, ba si mate ba mbaŵa zi''öli, ba zi tefasui ya''ami, ba si saraö [si tosai], ba ufazawili ba nangi misa, ba usöbi zi''öli moroi furira.', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 13, 'Ba akha ahori wönugu ba uhonogöi wa''abao dödögu ba khöra andrö, ba u''okafui dödögu, ena''ö aboto ba dödöra, wa no ya''o, Yehowa, zihede ba wa''aukhu dödögu ba khöra.', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 14, 'Ba ubali''ö tanö si mate nahami, ube''e börö wangehera ya''ami, ba niha baero, si tefasui ya''ami, ba zanehe zanörö fefu.[5]', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 15, 'Ba tobali börö wangehera ami ba börö wanandraŵa, fanenaŵa, ba börö wa''atobali dödö, ba niha baero, si tefasui ya''ami, na ufatörö khömi huku ba wönu ba ba wa''abao dödö, ba fotu ba wönu. Ya''o, Yehowa, zanguma''ö.', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 16, 'Na u''efa''ö khöra nono wana lofo andrö, safökhö, famakiko andrö, ni''efa''ögu dania, ba wamakiko ya''ami, ba na lö aetu ufatörö khömi lofo, ba ufatö khömi zi''o andrö, si''o ömi,[6]', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476385, 'OT', 'Hezekieli', 5, 17, 'ba ufatörö khömi lofo ba utu ndru''u, ena''ö si lö ono ami labe''e, ba itörö ami fökhö waba ba fa''aduwa ndro, ba si''öli ufatörö khömi. Ya''odo, Yehowa, zanguma''ö![7]', '["Ngenu 1:1","Yer 49:36; Ngenu 4:10","Faigi 7:4,8,18","MozV 28:37","Faigi 4:16","MozIII 26:22"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 2, 'He ono niha, otahögö hili Ndraono Gizeraeli andrö ba ama''ele''ö nitandrösaigö ba da''ö,[1]', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 3, 'ömane: He ya''ami hili Ndraono Gizeraeli, mifondrondrongo niŵa''ö Zo''aya, Yehowa! Imane So''aya, Yehowa ba hili andrö ba ba hili-hili, ba ba mbombo ba ba ndraso andrö: Hiza, ufatörö khömi zi''öli ba ufufu hili-hili andrö khömi.', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 4, 'Ba nidudugö naha wame''e sumange andrö khömi ba nirasa nadu luo andrö, ba föna nadumi utibo''ö tou nibunu andrö khömi.[2]', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 5, 'Boto zi mate ba Ndraono Gizeraeli, ba utou''ö tou föna nadura, ba tölami, ba ufazawili, ufasui naha wame''e sumange andrö khömi.', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 6, 'Ba danömi misa fefu, ba banua sadudu dania ba hili-hili si no afufu, ena''ö si lö mu''oguna''ö sa''ae naha wame''e sumange khömi, ba si no adudu, si no murasa nadumi ba si no muheta, si no mutuli''ö tou nadu luo andrö ba si no muhori nifazökhi dangami andrö.', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 7, 'Ba so zi mate nibunu ba khömi, ena''ö aboto ba dödömi, wa ya''odo Yehowa.', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 8, 'Ba na so ösa, banuami, saefa ba mbawa zi''öli, ba niha baero misa, na nifazawili ami ba danö zotanö,', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 9, 'ba itörö todö zoloi andrö khömi, ba niha baero, ba ni''oloi''ö ya''ira, nibotogu tödö andrö, si no fa''ero, si no mangerogö ya''o, awö hörö, si lö aefa-aefa ba nadu, timba ba zohorö, ba ogoro ira ira, börö zi lö sökhi andrö, nilaura sogoro ita andrö.', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 10, 'Ba aboto ba dödöra, wa tenga faya me udaö''ö-daö''ö wamatörö famunu andrö khöra, ya''o, Yehowa.', '["Faigi 36:1","MozIII 26:30; Yes 17:8"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 11, 'No imane So''aya, Yehowa: Lau dataŵo ba börö-börö danö ba lau wa''ala-alaisa ba zogoro ita andrö fefu, ba ma''uwu Gizeraeli, me si''öli ba lofo ba fökhö waba wamunura dania.', '["Yer 48:22"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 12, 'Saröu, ba ba wökhö waba tekiko, ba sahatö, ba ba mbawa zi''öli mate, ba si tosai, si lö göna da''ö, ba ba lofo mate, ba tobali u''oigö wönugu ba khöra andrö.', '["Yer 48:22"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 13, 'Ba ya aboto ba dödömi wa ya''o Yehowa, na no so tou ba ngai nadura nibunu andrö khömi ba zi tefasui naha wame''e sumange andrö khöra, ba hili-hili salaŵa fefu ba ba zuzu hili fefu, dozi börö geu ba dozi börö manawa sabölö bulu, ba nitunura samohua ba nadura fefu.', '["Yer 48:22"]', NULL),
  (3476386, 'OT', 'Hezekieli', 6, 14, 'Ba u''oro''ö dangagu, ba khöra andrö, ubali''ö tanö si mate ba si lö niha-niha danöra, i''otarai danö si mate andrö, irugi Ribela, ba naha mbanuara fefu; ba ya aboto ba dödöra, wa no ya''o Yehowa.[3]', '["Yer 48:22"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 2, 'Ba ya''ugö ono niha, ba ömane: Da''ö niŵa''ö Zo''aya, Yehowa, ba danö Ndraono Gizeraeli andrö: So moroi sa gamozua; ba mbalö danö ma''a''öfa, ba amozua sa''ae.', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 3, 'Itörö''ö sa''ae amozua ba ufatörö khöu wönugu ba uhuku ndra''ugö, dali mbua-buau andrö, ba u''otu''ö ndra''ugö ba zogoro ita andrö khöu, fefu.', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 4, 'Ba lö ahakhö dödögu wamaigi ya''ugö, lö alimagö ndra''ugö khögu, ufatörö sa''ae khöu wotu ba mbua-buau andrö, ba bakha ba hunömi dania so zogoro ita andrö khömi; ba ya aboto ba dödömi, wa no ya''o Yehowa.', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 5, 'Da''ö niŵa''ö Zo''aya, Yehowa: Famakiko, hiza, so moroi sa wamakiko!', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 6, 'Amozua sa''ae so moroi sa gamozua, isaŵa ndra''ugö, hiza ia moroi sa!', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 7, 'Itörö''ö famakhö, ya''ugö niha ba danö; irugi inötö, no ahatö mbaŵa, baŵa wa''atobali dödö ba tenga baŵa wa''iki, ba hili.[1]', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 8, 'Ba lö ara tö, ba uhawui ndra''ugö fa''abao dödögu andrö ba u''oigö wönugu ba khöu andrö, ba uhuku ndra''ugö, dali mbua-buau andrö, ba ufatörö khöu wotu, ba zogoro ita andrö khöu, fefu.', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 9, 'Ba lö ahakhö dödögu wamaigi ya''ugö, ba lö alimagö ndra''ugö khögu. Ufatörö khöu nifatörö, dali mbua-buau andrö, ba ba hunömi dania so zogoro ita andrö khömi; ba ya aboto ba dödömi, wa no ya''o, Yehowa, zamago ya''ami.', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 10, 'Hiza mbaŵa andrö; hiza ia! alua dakula, mobowo zi''o, mobulu hokha andrö![2]', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 11, 'Maoso wamakao andrö, fotu ba zi lö atulö; ma''ifu lö ya''ira sa''ae, lö si tosai sato andrö, lö si tosai si no fahöna, ba lö sange''esi ya''ira.', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 12, 'Irugi baŵa, no ahatö luo andrö: böi omuso dödö zowöli ba böi abu dödö zaniaga; tesao sa''ae wönu ba zi no ato andrö.', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 13, 'Lö''ö sa ifuli möi ba danga zamawa ni''amawa andrö, he ŵa''ae lö mate ia na; lö mamöhöi wönu andrö, ba zi no ato andrö fefu. Ba dozi ira, ba lö falukha wa''abe''e, börö horöra andrö.', '["Yes 16:10","Yes 10:5"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 14, 'Milau dorofe, mifa''anö fefu hadia ia, ba samösa lö salua möi ba wasuwöta, me no tesao wönugu ba zato andrö fefu.', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 15, 'Baero, ba si''öli, ba yomo ba mbanua, ba fökhö waba, ba lofo. Si so baero ba mbenua, ba si mate ba mbawa zi''öli, ba si so yomo ba mbanua, ba ni''a lofo ba fökhö waba.', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 16, 'Ba na so zoloi ösa, ya''ira andrö, ba timba mburu''u ba mbawa danö dania ira, sangarö-ngarö fefu — ba horönia mangarö-ngarö zamösana.', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 17, 'Adada danga fefu ba sangulu mbalöduhi.[3]', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476387, 'OT', 'Hezekieli', 7, 18, 'Ba sonukha nukha ba wa''abu dödö ira ba si tehawu fa''ata''u; fa''aila ba mbawara fefu, ba dozi högö, ba si batule.[4]', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 19, 'Firöra, ba latibo''ö tou ba newali, ba ana''ara, ba sasao laŵa''ö. Tenga sa sangorifi ya''ira wiröra ba ana''ara, na baŵa wönu Yehowa andrö; no tenga fangabuso ba wa''atebakhara andrö, ba tenga ösi dalura noa sa tobali tandraŵa horö ia khöra.[5]', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 20, 'Ba no labe''e börö wayaŵasa gana''ara lakhömira andrö, ba no labali''ö adura andrö, sogoro ita, sihokha mbuda andrö khöra; andrö wa ubali''ö sasao ia khöra.', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 21, 'Ba ululu nirabu niha bö''ö ia, ahulua wondrege zebua horö ba guli danö, ena''ö lafatörö ba zalakha.', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 22, 'Ba u''erogö ira, ba ndramufatörö ba zalakha girö-girögu andrö, hana na möi zorabu ba hana na lalau zalakha khönia.', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 23, 'Fazökhi rate; me no anönö danö fange''e ba me no anönö mbanua horö.', '["SamII 4:1; Yes 13:7","Yes 15:3; Yer 48:37","Amaed 11:4; TimI 6:9,10"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 24, 'Ba ufatörö sa''ae wondrege zafaito niha baero, hana na da''ö zangokhögö omora, ba u''ezosi sa''ae wayaŵasa zabölö andrö, ba akha telau zalakha ba ni''amoni''ö andrö khöra.', '["Mal 2:7"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 25, 'So wa''ata''u, ba la''alui wangorifi, ba lö falukha:', '["Mal 2:7"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 26, 'Si fatete manö wamakao ba si lö aetu duria [sata''u ita]; ba lazofu-zofu gangilata khö zama''ele''ö, ba ba gere, ba taya lala, ba ba zatua, ba taya wamolala tödö.[6]', '["Mal 2:7"]', NULL),
  (3476387, 'OT', 'Hezekieli', 7, 27, 'Sabu tödö razo, ba salaŵa, ba i''onukha wa''atobali dödö, ba sadada danga niha ba danö, lö döladöla. Bua-buara ube''e dali wolau khöra, ba huku ba khöra ube''e dali wanguhuku ya''ira, ba ya aboto ba dödöra, wa no ya''o Yehowa.', '["Mal 2:7"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 1, 'Ba ba ndröfi si önö, ba zi melima ba mbaŵa si önö, me dumadaodo ba nomogu, ba me dumadao fönagu zatua mado Yuda, ba ira''udo tanga Yehowa.[1]', '["Faigi 1:2","Faigi 1:4","Faigi 3:23"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 2, 'Ba ufakhölödo, ba u''ila wamaedo, hulö niha wamaigigu; i''otarai löwi-löwinia mitou, ba alitö, ba miyaŵa, ba hulö haga, timba wa''atakile döla garamba si takile.[2]', '["Faigi 1:2","Faigi 1:4","Faigi 3:23"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 3, 'Ba i''oro''ö zi hulö danga, ituyu mbugu ba ifazaŵado ba dalu mbanua Eheha ba i''ohedo ba Yeruzalema, ba gangilata khö Lowalangi, ba zinga mbawandruhö ibe''e ndra''o, bawandruhö tanö bakha, miyöu, ba zi so adu andrö, börö wa''olohu Yehowa.', '["Faigi 1:2","Faigi 1:4","Faigi 3:23"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 4, 'Ba hiza, ba so ba da''ö lakhömi Lowalangi Ndraono Gizeraeli, si mane fangilagu ya''ia no, ba ndraso.[3]', '["Faigi 1:2","Faigi 1:4","Faigi 3:23"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 5, 'Ba imane khögu: He ono niha, fakhölö''ö miyöu! Ba me ufakhölödo miyöu, ba hiza, ba so ba zinga mbawandruhö ba naha wame''e sumange, tanö yöu, nadu börö wa''olohu andrö.', '["Faigi 1:2","Faigi 1:4","Faigi 3:23"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 6, 'Ba imane khögu: He ono niha, hadia, ö''ila nilaura ba da''ö? No sogoro ita sabölö-bölö nilau ma''uwu Gizeraeli ba da''e, tobali lö tola lö u''erogö ni''amoni''ö andrö khögu; ba so na dania ni''ilau sabölö ogoro ita, baero da''ö!', '["Faigi 1:2","Faigi 1:4","Faigi 3:23"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 7, 'Ba i''ohedo ba zinga mbawa göli ba golayama. Ba me ufakhölödo, ba hiza zatöla göli kara.', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 8, 'Ba imane khögu: He ono niha, törö göli andrö! Ba me utörö göli, ba hiza mbawandruhö.', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 9, 'Ba imane khögu: Ae bakha ba faigi zogoro ita, sabölö-bölö andrö, nilaura ba da''ö!', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 10, 'Ba me möido bakha, ba me ufaigi, ba hiza ngawalö wamaedo guökuö sihokha mbuda, ba famaedo gurifö niha, ba adu ma''uwu Gizeraeli fefu nisua ba mbagolö, fasui.', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 11, 'Ba so niha, 70 satua ma''uwu Gizeraeli, ba Ya''asania, ono Zafano, ba hunöra bakha, solohe ya''ira, ba no dozi ira naha wanunu kumöyo ba danga, numalö miyaŵa hua zimbo gumöyö andrö.', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 12, 'Ba imane khögu: Hadia, no ö''ila, ya''ugö ono niha, hadia nilau zatua Ndraono Gizeraeli, ba zogömi-gömi, ba mbate''e nadu khönia ilau zamösana. Lamane sa dödöra: Lö i''ila ita Yehowa, no iheta ia ba danöda Yehowa.[4]', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 13, 'Ba imane na khögu: So na dania ni''ilau, baero da''ö, sogoro ita sabölö-bölö, nilaura!', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 14, 'Ba i''ohedo ba zinga mbawandruhö ba gosali Yehowa, tanö yöu, ba hiza ndra alawe sidadao ba da''ö, sange''esi Tamusi andrö.', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 15, 'Ba imane khögu: Hadia, no ö''ila, ya''ugö ono niha? So na dania ni''ilau sogoro ita, sabölö-bölö moroi ba da''ö.', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 16, 'Ba i''ohedo ba golayama gosali Yehowa, tanö bakha; ba mato 25 niha ba da''ö, ba zinga mbawandruhö ba gosali Yehowa, ba gotaluara gewe''ewe andrö naha wame''e sumange, sangerogö osali Yehowa ira ba si otahögö atumbukha luo ba sangalulu ba luo, ba gatumbukha.[5]', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 17, 'Ba imane khögu: Hadia, no ö''ila, ya''ugö ono niha? Hadia, ambö na ba ma''uwu Yuda wolau sogoro ita andrö, nilaura ba da''e, wa lanönöi [na göi] danö famakao awöra, awö wa lö aetu la''andrö wönugu? ba hiza, ba la''ago''ago duturu geu sauri.', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476388, 'OT', 'Hezekieli', 8, 18, 'Ba ya''odo göi, ba fönugu ufatörö khöra: lö ahakhö dödögu, wamaigi ya''ira ba lö alimagö ira khögu. Ba he ebua dania lira wangarö-ngarö khögu, ba lö ufondrondrongo.[6]', '["Yob 22:13; Sin 94:7; Yes 29:15","MozV 17:3; Yob 31:26; RazII 23:5","Faigi 5:11"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 1, 'Ba mu''ao ia khögu, ebua linia, imane: So moroi sa wotu mbanua andrö, ba no so ba danga zamösana wanudugö.', '["Nga''ötII 27:3; MozIII 16:4","MozIII 12:22; Fam 7:3","MozII 32:27; Yer 25:29; FetI 4:17"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 2, 'Ba hiza moroi sa niha, daönö, la''otarai mbawa göli tanö si yaŵa, tanö miyöu, sara wanudugö ba danga zamösana, ba baru tarafali mbaru zi samösa ba fanura ba löwi-löwinia. So ira ba la''iagö ba ngai naha wame''e sumange töla garamba andrö.[1]', '["Nga''ötII 27:3; MozIII 16:4","MozIII 12:22; Fam 7:3","MozII 32:27; Yer 25:29; FetI 4:17"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 3, 'Ba no iheta ia lakhömi Yehowa andrö, no iröi Kerubi andrö, si so ia yaŵa mege, isaŵa doyo mbawandruhö ba gosali; ba mu''ao ia khö zamaru tarafali andrö, si so fanura andrö ba löwi-löwi.', '["Nga''ötII 27:3; MozIII 16:4","MozIII 12:22; Fam 7:3","MozII 32:27; Yer 25:29; FetI 4:17"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 4, 'Ba imane khönia Yehowa: Törö mbanua, talu Yeruzalema andrö, ba fotandra gangango niha andrö sangarö-ngarö, sabu tödö ba zogoro ita andrö fefu, nilau ba mbanua andrö![2]', '["Nga''ötII 27:3; MozIII 16:4","MozIII 12:22; Fam 7:3","MozII 32:27; Yer 25:29; FetI 4:17"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 5, 'Ba ba nawönia, ba imane — irongo tögi dalingagu —: Mi''o''ö ia, mitörö mbanua ba milau khöra, böi ahakhö dödömi, wamaigi ya''ira, ba böi alimagö ira khömi!', '["Nga''ötII 27:3; MozIII 16:4","MozIII 12:22; Fam 7:3","MozII 32:27; Yer 25:29; FetI 4:17"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 6, 'Si no tohare huwa ba ono matua ba ono alawe ba iraono ba ira alawe, ba mi''ö''ötö tou; ba dozi zi so tandra, andrö, ba böi mibabaya. Ba ni''amoni''ö andrö khögu mibörötaigö! Ba labörögö ba zatua andrö, si so ba golayama gosali.[3]', '["Nga''ötII 27:3; MozIII 16:4","MozIII 12:22; Fam 7:3","MozII 32:27; Yer 25:29; FetI 4:17"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 7, 'Ba imane khöra: Mita''unöi gosali ba mibe''e anönö newali boto nibunu! Milabu! Ba möi ira ba lalau ba mbanua andrö.', '["Nga''ötII 27:3; MozIII 16:4","MozIII 12:22; Fam 7:3","MozII 32:27; Yer 25:29; FetI 4:17"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 8, 'Ba me la''ö''ötö tou niha, me no toröido furi, ba ufalögu tou ndra''o, mu''aodo, umane: He So''aya, Yehowa, hadia, öfalua wangohori si tosai Iraono Gizeraeli, wangahawui Yeruzalema fönumö andrö?', '["Faigi 8:12","Faigi 5:11"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 9, 'Ba imane khögu: No ebua sibai horö ma''uwu Gizeraeli ba he horö ma''uwu Yuda, ba no anönö danö fange''e, ba banua, ba no anönö famuyu''ö huku, lamane sa dödöra: "No iheta ia ba danö Yehowa", ba: "Lö i''ila Yehowa."[4]', '["Faigi 8:12","Faigi 5:11"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 10, 'Ba lö''ö sa''ae göi ahakhö dödögu, wamaigi, ba lö alimagö ira khögu: usulöni khöra mbua-buara andrö![5]', '["Faigi 8:12","Faigi 5:11"]', NULL),
  (3476389, 'OT', 'Hezekieli', 9, 11, 'Ba i''ombakha''ö sobaru tarafali andrö, si so fanura ba löwi-löwi, imane: No u''o''ö niŵa''öu khögu.', '["Faigi 8:12","Faigi 5:11"]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 1, 'Ba ufakhölödo, ba hiza, ba yaŵa zi hulö mbanua andrö, yaŵa högö Kerubi andrö, ba so zi hulö weremata nila; oroma yaŵara zi hulö wamaedo dadaoma zalaŵa.[1]', '["Faigi 1:26","Faigi 1:13; 9:3","Faigi 1:25"]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 2, 'Ba imane khö zobaru tarafali andrö: Ae bakha ba gotalua gaolo andrö, tou Kerubi, gokhöi mbo galitö ba gotalua Kerubi andrö, ba fazaewe yaŵa mbanua Yeruzalema! Ba möi ia bakha, anehe ndra''o.', '["Faigi 1:26","Faigi 1:13; 9:3","Faigi 1:25"]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 3, 'Ba ba gambölö gosali so Kerubi andrö, me möi ia bakha, ba inönöi golayama tanö bakha lawuo andrö.', '["Faigi 1:26","Faigi 1:13; 9:3","Faigi 1:25"]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 4, 'Ba ifazaŵa ia lakhömi, iröi Kerubi andrö, isaŵa doyo mbawandruhö gosali, ba anönö gosali lawuo andrö, ba olayama, ba anönö haga lakhömi Yehowa.[2]', '["Faigi 1:26","Faigi 1:13; 9:3","Faigi 1:25"]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 5, 'Ba terongo ruru gafi Kerubi, irugi golayama tanö baero sibai, no timba li Lowalangi Si lö ambö fa''abölö, na muhede ia.[3]', '["Faigi 1:26","Faigi 1:13; 9:3","Faigi 1:25"]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 6, 'Ba me iŵa''ö khö zobaru tarafali andrö: Halö galitö ba gotalua gaolo andrö, ba gotalua Kerubi, ba möi ia bakha, i''iagö ba ngai gaolo.', '["Faigi 1:26","Faigi 1:13; 9:3","Faigi 1:25"]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 7, 'Ba i''oro''ö dangania Kerubi andrö ba galitö ba gotalua Kerubi, ituyu [ösa] ba ibe''e ba danga zobaru tarafali andrö, ba ihalö ba mofanö.', '["Faigi 1:26","Faigi 1:13; 9:3","Faigi 1:25"]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 8, 'Ba oroma ba Kerubi andrö zi hulö danga niha, barö gafira.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 9, 'Ba ufaigi, ba hiza gaolo ba ngai Kerubi andrö, öfa, sambua Kerubi, ba sambua gaolo ba ngainia, ba gaolo andrö, ba no timba wa''atakile weremata wirusi, wamaigigu.[4]', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 10, 'Ba famaigida ya''ia, ba no fagölö-gölö, ma''a''öfa, hulö na bakha ba gaolo zi zambua so zi sambua.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 11, 'Ba na mofanö, ba öfa rozi lala; lö labali''ö ira, na mofanö; ba ni''otahögö zi sambua la''o''ö; lö labali''ö ira, na mofanö.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 12, 'Ba ösira ma''asambua ba hulura ba tangara ba afira ba he gaolo andrö, ba no anönö hörö, fasui, ba zi öfa andrö.[5]', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 13, 'Ba urongo, me tebe''e töi gaolo andrö "dawuyu nangi."', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 14, 'Ba öfa bawa zambua. Bawa zi zambua, ba bawa zaŵi si matua, ba si sambua, ba sobawa niha, ba fanete da''ö, ba sobaŵa zingo, ba fanete da''ö, ba sobawa moyo.[6]', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 15, 'Ba lafazaŵa ira Kerubi andrö. Ya''ia manö ni''ilagu no, ba mbewe Khebara.[7]', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 16, 'Ba na mofanö Kerubi andrö, ba fao gaolo andrö, ba ngaira, ba na labologö gafira Kerubi, ba wamazaŵa ya''ira moroi ba danö, ba lö tebulö ba ngaira gaolo.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 17, 'Ba na labadugö ira Kerubi, ba tebato göi gaolo, ba na lafazaŵa ira Kerubi, ba fao göi gaolo, me no so bakha geheha zaliŵa-liŵa andrö.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 18, 'Ba iheta ia ba doyo mbawandruhö gosali lakhömi Yehowa ba i''iagö yaŵa Kerubi.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 19, 'Ba labologö gafira Kerubi, lafazaŵa ira moroi ba danö — anehe ndra''o, me aefa ira ba fao gaolo andrö. Ba la''iagö zinga mbawandruhö gosali, tanö ba gatumbukha luo, ba yaŵara so lakhömi Lowalangi Ndraono Gizeraeli.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 20, 'Ya''ia zaliŵa-liŵa andrö, ni''ilagu no, dayadaya Lowalangi Ndraono Gizeraeli. Ba u''ila, wa Kerubi.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 21, 'No öfa''öfa mbawara ba öfa''öfa gafira, ba barö gafira, ba no si hulö danga niha.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476390, 'OT', 'Hezekieli', 10, 22, 'Ba bawara andrö, ba no si mane bawa ni''ilagu no ba mbewe Khebara; famaigida ya''ia ba si ndruhu göi; ba idölö manö ia zambuana.', '["Faigi 1:16","Fam 4:6,8","Faigi 1:10","Faigi 1:3 b.t."]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 1, 'Ba ifazaŵado Eheha ba i''ohedo ba zinga mbawandruhö gosali Yehowa tanö ba gatumbukha luo, si otahögö atumbukha; ba 25 niha ba da''ö, ba zinga mbawandruhö, ba u''ila ba khöra zalaŵa, Ya''asania, ono Asuri ba Felatia, ono Mbenaya.[1]', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 2, 'Ba imane khögu: He ono niha, da''ö niha andrö sangalui famakiko, samakhai tödö si lö sökhi ba mbanua andre,', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 3, 'sanguma''ö: "Lö alio sibai ginötö wolau omo: bowoa mbanua, ba diwo nirino ita!"', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 4, 'Ba ama''ele''ö ba khöra, ama''ele''ö, ya''ugö ono niha!', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 5, 'Ba ihawuido Eheha Yehowa, ba imane khögu: Ömane: Da''ö niŵa''ö Yehowa: Si manö wehedemi, ya''ami ma''uwu Gizeraeli, ba hadia zi tesao ba dödömi, ba noa sa''ae aboto ba dödögu.', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 6, 'Ato nibunumi yomo ba mbanua andre, no mibe''e anönö newali nibunu tou.', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 7, 'Andrö wa imane So''aya Yehowa: Nibunumi andrö, ni''ö''ötömi tou, da''ö ndriwo andrö ba banua mbowoa! Ba ya''ami, ba niheta ba mbanua.', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 8, 'Si''öli mi''ata''ufi, ba si''öli ufatörö khömi, iŵa''ö So''aya, Yehowa.', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 9, 'Ba uheta ami ba mbanua, ube''e ba danga niha bö''ö ami ba ufatörö khömi huku.', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 10, 'Si''öli wamunumi dania, ba nola danö Ndraono Gizeraeli uhuku ami, ba ya aboto ba dödömi wa no ya''o Yehowa.', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 11, 'Böi tobali bowoa khömi mbanua ba tenga diwo ami bakha; ba nola danö Ndraono Gizeraeli uhuku ami.', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 12, 'Ba ya aboto ba dödömi ba da''ö, wa no ya''o Yehowa, si lö ni''o''ömi nifakhoinia ba si lö nitöngönimi huku; no huku niha baero, si tefasui ya''ami, mi''o''ö.', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 13, 'Ba fatua mama''ele''ö ndra''o, ba no mate Welatia, ono Mbenaya. Ba ufalögu tou ndra''o, mu''aodo, ebua ligu, umane: Alai ndra''o, ya''ugö So''aya, Yehowa, hadia, öfalua sa''ae wangohori si tosai Iraono Gizeraeli?', '["Faigi 8:16"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 14, 'Ba humede khögu Yehowa, imane:', '["Yer 24:7; 32:37 b.t; Faigi 36:27 b.t.","Yer 30:22"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 15, 'He ono niha, talifusömi, iwami, si tengabö''ömi ba ma''uwu Gizeraeli fefu, orudu, niŵa''ö mbanua Yeruzalema: "No aröu gotaluara Yehowa; khöma no mutehe danö, okhötama!"', '["Yer 24:7; 32:37 b.t; Faigi 36:27 b.t.","Yer 30:22"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 16, 'Andrö wa ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Ya''ia, no ube''e ba zaröu ira, ba niha baero, no ufazawili ira ba danö zotanö, ba no ha ma''ifu ni''amoni''ö ndra''o khöra, ba danö andrö misa, si no larugi.', '["Yer 24:7; 32:37 b.t; Faigi 36:27 b.t.","Yer 30:22"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 17, 'Andrö wa ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Ba u''ozaragö ami ba niha baero andrö ba u''owuloi ami moroi ba danö andrö misa, ba nifazaewe ya''ami, ba ube''e khömi danö Ndraono Gizeraeli.', '["Yer 24:7; 32:37 b.t; Faigi 36:27 b.t.","Yer 30:22"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 18, 'Ba larugi dania da''ö, ba lahori ba danö zihokha mbuda andrö khöra, fefu, awö zogoro ita andrö, fefu.', '["Yer 24:7; 32:37 b.t; Faigi 36:27 b.t.","Yer 30:22"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 19, 'Ba ube''e khöra dödö si bohou, ba Eheha si bohou ube''e ba dödöra bakha; tödö kara andrö, ba uheta barö doto, ba ube''e khöra dödö nagole,[2]', '["Yer 24:7; 32:37 b.t; Faigi 36:27 b.t.","Yer 30:22"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 20, 'ena''ö la''o''ö nifakhoigu ba ena''ö latöngöni huku andrö khögu ba ena''ö latörö; ba banuagu dania ira ba Lowalangira ndra''odo.[3]', '["Yer 24:7; 32:37 b.t; Faigi 36:27 b.t.","Yer 30:22"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 21, 'Ba na so zadöni tödö ba zogoro ita andrö khöra ba ba zihokha mbuda andrö, khöra usulöni wolaura! — iŵa''ö So''aya, Yehowa.', '["Yer 24:7; 32:37 b.t; Faigi 36:27 b.t.","Yer 30:22"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 22, 'Ba labologö gafira Kerubi andrö, ba fao khöra gaolo andrö, ba yaŵara so lakhömi Lowalangi Ndraono Gizeraeli.', '["Faigi 10:18; 43:2"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 23, 'Ba ifazaŵa ia lakhömi Yehowa, moroi ba dalu newali mbanua, ba i''iagö zuzu hili, tanö ba gatumbukha luo, na ta''otarai mbanua.[4]', '["Faigi 10:18; 43:2"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 24, 'Ba ifazaŵa ndra''o Eheha, i''ohedo ba danö Ndrawa Galedaia, ba ni''oloi''ö andrö, ba gangilata. Eheha Lowalangi zolohe ya''o. Ba iheta ia khögu angilata andrö, ni''ilagu mege.', '["Faigi 10:18; 43:2"]', NULL),
  (3476391, 'OT', 'Hezekieli', 11, 25, 'Ba u''ombakha''ö ba ni''oloi''ö andrö daroma li Yehowa fefu, nifa''ele''önia khögu.', '["Faigi 10:18; 43:2"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 1, 'Ba humede khögu Yehowa imane:', '["Yes 6:9; 42:18; Yer 5:21"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 2, 'He ono niha, bakha ba hunö niha sabe''e tandro soso ndra''ugö, ba hunö niha si so hörö, ba wangila niha, ba lö sa la''ila niha, ba si so tögi dalinga, ba wamondrongo ba lö''ö sa larongo li niŵa''ö khöra, me no niha sabe''e tandro ira.[1]', '["Yes 6:9; 42:18; Yer 5:21"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 3, 'Ba ya''ugö ono niha, ba faigi khöu zoguna ba wa''awu''a, ba aheta''ö, ba zi ma''ökhö, ba zanehe ira; öheta''ö ba nahiamö, ba ösaŵa mbanua bö''ö, ba zanehe ira, — ma atö latöngöni, noa sa niha sabe''e tandro ira!', '["Yes 6:9; 42:18; Yer 5:21"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 4, 'Ba zi ma''ökhö, ba zanehe ira, öbe''e tou gama-gamamö, gama-gama ba wa''awu''a; ba ya''ugö, ba na owi mofanö''ö, ba zanehe ira, amaedola wa''aheta nifofanö.', '["Yes 6:9; 42:18; Yer 5:21"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 5, 'Otöla''ö göli, ba zanehe ira, ba ötörö da''ö, we''amöi baero.', '["Yes 6:9; 42:18; Yer 5:21"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 6, 'Öfa''ele''ö khöra, na ö''angalisigö gama-gamamö; ba zi bongi mofanö''ö ba öbalugö mbawau, fa lö ö''ila danö. Ube''e famaedo ndra''ugö ba Ndraono Gizeraeli.', '["Yes 6:9; 42:18; Yer 5:21"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 7, 'Ba u''o''ö niŵa''ö khögu: gama-gamagu, ba ba zi ma''ökhö u''ohe tou, amaedola gama-gama ba wa''aheta, ba tanötanö owi, ba utola''ö göli tangagu; ba me bongi, ba u''angalisigö gama-gamagu ba u''ohe baero, ba zanehe ira.', '["Yes 6:9; 42:18; Yer 5:21"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 8, 'Ba ba zanguhulö wongi, ba humede khögu Yehowa, imane:', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 9, 'He ono niha, hadia, lö niŵa''ö ma''uwu Gizeraeli, niha sabe''e tandro andrö: "Hadia nilaumö andrö?"', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 10, 'Ömane khöra: Da''ö niŵa''ö Zo''aya Yehowa: Ba zalaŵa tetandrösaigö niŵa''ö andre, ba Yeruzalema, ba ba ma''uwu Gizeraeli fefu banuara.[2]', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 11, 'Ömane: Famaedo ndra''o khömi; Nilaugu andrö, ba itörö ira dania: ba danö niha bö''ö te''oloi''ö ira dania.', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 12, 'Ba salaŵa andrö, ba khöra, ba i''angalisigö gama-gamania ba ba zi bongi aheta ia. Latöla''ö dania göli, lalania; ba bawania, ba ibalugö, ena''ö lö i''ila ia niha, ba ya''ia, ba ena''ö lö i''ila danö.[3]', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 13, 'Ba uhawui ia u''ö andrö khögu, ba alau dania ia ba gu''ögu, ba u''ohe ba Mbabeli ia, ba danö Ndrawa Galedaia; ba lö''ö sa i''ila hörönia, ba ba da''ö mate ia dania.[4]', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 14, 'Ba awönia andrö, tohu-tohu dangania, ba sabölö andrö khönia fefu, ba ufazawili misa, ba zi fasui, ba usöbi zi''öli, moroi furira.', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476392, 'OT', 'Hezekieli', 12, 15, 'Ba ya aboto ba dödöra, wa no ya''o Yehowa, na ufazaewe ira ba niha baero ba ba danö misa.', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 16, 'Ba usaigö ösa, si lö atoto, banuara, si lö mate ba mbawa zi''öli ba ba lofo, ba ba wökhö waba, ena''ö ladunö-dunö ba niha baero misa zogoro ita andrö khöra, fefu, ba niha nirugira dania, ena''ö aboto ba dödöra, wa no ya''o Yehowa.', '["Yes 13:1","RazII 25:4","Yer 39:7; 52:11; Faigi 17:20"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 17, 'Ba so na niŵa''ö Yehowa khögu, imane:', '[]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 18, 'He ono niha, sanizi-nizi ndra''ugö dania ba wemanga göu, ba sogikhi tödö ba sabu tödö, ba wamadu idanö,', '[]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 19, 'ba ömane ba niha ba danö: Da''ö niŵa''ö Zo''aya, Yehowa, nitandrösaigö ba mbanua Yeruzalema, ba danö Ndraono Gizeraeli: sabu tödö ira dania, ba wemanga göra ba sihokha bu, na labadu nidanö; ena''ö tanö si mate dania danöra, si no aheta si fahöna mege, börö horö niha ba danö andrö, fefu.', '[]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 20, 'Ba banua andrö, si so niha iada''e, ba tobali si lö niha dania, ba tanö si mate danö, ena''ö aboto ba dödömi, wa no Yehowa ndra''odo.', '[]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 21, 'Ba so zui niŵa''ö Yehowa, khögu, imane:', '["Hab 2:3; FetII 3:4"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 22, 'He ono niha, hadia khömi niŵa''ö andrö ba danö Ndraono Gizeraeli, na lamane: Lö''ö manö i''ila irugi baŵa ba tobali manö si lö boto gangilata fefu?[5]', '["Hab 2:3; FetII 3:4"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 23, 'Andrö wa ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Da''u''etu''ö niŵa''ö andrö, fa böi sa''ae laŵa''ö-ŵa''ö Iraono Gizeraeli! Ömane sa''ae khöra: Itugu ahatö mbaŵa andrö ba eluaha gangilata andrö, fefu.', '["Hab 2:3; FetII 3:4"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 24, 'Böi sa''ae ta''ila ba ma''uwu Gizeraeli gangilata si lö boto, ba he fama''ele''ö faya.', '["Hab 2:3; FetII 3:4"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 25, 'Ya''odo a''i, Yehowa, zihede, uŵa''ö niŵa''ögu, ba itörö dania. Lö mogasa sa''ae, ba götömi andre, ya''ami niha sabe''e tandro; so niŵa''ögu, ba itörö göi ube''e! — iŵa''ö So''aya, Yehowa.', '["Hab 2:3; FetII 3:4"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 26, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Hab 2:3; FetII 3:4"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 27, 'He ono niha, hiza, lamane dödöra ma''uwu Gizeraeli: Angilata andrö, ni''ilania, ba ba wa''ara dania, ba götö furi nifa''ele''önia andrö.', '["Hab 2:3; FetII 3:4"]', NULL),
  (3476392, 'OT', 'Hezekieli', 12, 28, 'Andrö wa ömane khöra: Niŵa''ögu andrö fefu, ba lö mogasa sa''ae: taroma ligu andrö niŵa''ögu, ba itörö dania! — iŵa''ö So''aya, Yehowa.', '["Hab 2:3; FetII 3:4"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 2, 'He ono niha, ama''ele''ö, nitandrösaigö ba zama''ele''ö andrö ba Ndraono Gizeraeli, ömane ba zama''ele''ö nikhoi dödöra andrö: Mifondrondrongo li Yehowa![1]', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 3, 'Da''ö niŵa''ö Zo''aya, Yehowa: Alai zama''ele''ö andrö, si lö tödö, solo''ö manö nikhoi dödöra, si no tenga ni''ila höröra.', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 4, 'No timba nasu gatua ba gadudula mbanua zama''ele''ö andrö khömi, ya''ami Iraono Gizeraeli.[2]', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 5, 'Lö si möi ami miyaŵa ba zatöla göli, ba lö nikölinimi ma''uwu Gizeraeli, ba wangabe''e''ö ya''ami ba wasuwöta na baŵa Yehowa.[3]', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 6, 'Si lö boto mege la''ila ba faetasa faya, ya''ira andrö, si''ao mege: "Niŵa''ö Yehowa", ba lö nifatenge Yehowa ya''ira ba no sombalo-mbaloi, ena''ö itörö niŵa''ö andrö.', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 7, 'Hadia, tenga angilata si lö boto ni''i''ilami ba tenga faetasa faya wehedemi, ba no mimane: "Niŵa''ö Yehowa", ba lö sihede ndra''odo.', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 8, 'Andrö wa imane So''aya, Yehowa: Me no si lö boto wehedemi ba me no faya ni''ila hörömi, ba ulau sa''ae khömi! — iŵa''ö So''aya Yehowa.', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 9, 'Ilau ba zama''ele''ö andrö tangagu, ba zama''ele''ö si no mangi''ila si lö boto, ba si no mama''ele''ö faya; tebai monaha ira ba mbanuagu andrö, ba ba zura nga''ötö ma''uwu Gizeraeli, ba lö latanö döira, ba lö tola larugi danö Ndraono Gizeraeli; ba ya aboto sa''ae ba dödömi, wa no So''aya, Yehowa, ndra''odo.', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 10, 'Börö me no lafaelungu mbanuagu wanguma''ö: "Fa''atulö", ba zi lö fa''atulö sa atö, ba na lalau göli kara banuagu, ba ya''ira zolau betua fangafusi.[4]', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 11, 'Ba ömane sa''ae ba zolau betua andrö: Ya adudu! Si ndruhu, ufatörö deu sabölö-bölö, fangahanigö ya''ia; aekhu ba danö deu kara ba ilau angi sabölö-bölö.', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 12, 'Ba adudu sa''ae göli kara andrö. Hadia, lö lasofu dania khömi: Heza so mbetua andrö, nilaumi?', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 13, 'Andrö wa imane So''aya, Yehowa: Ya''ia, ilau angi sabölö-bölö ube''e, ba wa''abao dödögu andrö ba teu sabölö-bölö fangahanigö, lua-lua wönugu ba teu kara, bakhu-bakhu dödögu, ba wangohori.', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 14, 'Ba ududugö sa''ae göli andrö, nilaumi betua, ulau tou ba danö, ena''ö oroma dayadayania; sadudu ia ba ya''ami, ba si tekiko ba da''ö, ba ya aboto ba dödömi, wa no ya''odo Yehowa![5]', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 15, 'Ba u''oigö wa''abao dödögu ba göli kara andrö, ba ba zolau betua khönia, ba imane dania khömi: Lö''ö sa''ae öli kara andrö ba lö''ö sa''ae solau betua,', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 16, 'sama''ele''ö andrö ba Ndraono Gizeraeli, sama''ele''ö nitandrösaigö ba Yeruzalema ba sangi''ila angilata fangorifi khöra, me lö''ö sa atö fangorifi! iŵa''ö So''aya Yehowa.', '["FetII 1:21","SinSeb 2:15","Sin 106:23; Faigi 22:30","Yer 6:14","Mat 7:27"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 17, 'Ba ya''ugö ono niha, otahögö nono mbanuami alawe, sama''ele''ö nikhoi dödöra, ba ama''ele''ö nifaudugö khöra, ömane:', '["MozV 18:20"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 18, 'Da''ö niŵa''ö Zo''aya, Yehowa: Alai ndra alawe andrö, sanagu luniluni mbulökha fefu ba samazökhi balu-balu högö, sondrozigö niha, he iraono ba he zatua, ba wogaigö niha. Hadia, edöna mifa''u''u ösa khömi?', '["MozV 18:20"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 19, 'Ba no mibe''e ba zalakha ndra''o, ba mbanuagu, ha mato matonga kata fakhe mböli gölömi ba mato dua mbawa kue, ba wamunu niha, salakha lö mate ena''ö, ba ba wangorifi niha, si lö tola auri ena''ö, me milau waya ba mbanuagu, si no samondromondrongo faya.[6]', '["MozV 18:20"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 20, 'Andrö wa imane So''aya, Yehowa: Hiza, ulau ba luniluni andrö khömi fondra''umi niha, timba wondra''u wofo, ba usöbi ba dangami, ba u''efa''ö niha andrö nira''umi, nifamoloi fofo.', '["MozV 18:20"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 21, 'Ba ure''a mbalu-balu andrö khömi, ba u''efa''ö ba dangami mbanuagu andrö, fa böi sa''ae ahulua ira ba dangami, ba ya aboto ba dödömi, wa no ya''odo Yehowa.', '["MozV 18:20"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 22, 'Me no mibusi dödö niha satulö tödö, falimosa, me lö omasi ndra''o lafakao ira, ba me no mi''abe''e''ö danga zi no mangerogö Lowalangi, ena''ö lö iböhöli mbua-buania si lö sökhi andrö, fa lö mate ia.', '["MozV 18:20"]', NULL),
  (3476393, 'OT', 'Hezekieli', 13, 23, 'Ba böi sa''ae mi''ila zi lö boto ba böi sa''ae milau waetasa, u''efa''ö sa''ae ba dangami mbanuagu andrö, ba ya aboto ba dödömi, wa no ya''o Yehowa.', '["MozV 18:20"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 1, 'Ba möi khögu niha, satua Ndraono Gizeraeli, ba mudadao ira fönagu.', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 2, 'Ba so niŵa''ö Yehowa khögu, imane.', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 3, 'He ono niha, no la''aro''ö ba dödöra nadura niha andrö ba no labe''e fönara, tandraŵa horöra; ba hadia, utehe khöra lasofu khögu hadia ia?', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 4, 'Ba hede khöra, ömane: Da''ö niwa''ö Zo''aya, Yehowa: Dozi Iraono Gizeraeli, sangaro''ö ba dödöra adura ba same''e fönara tandraŵa horöra, ba si möi khö zama''ele''ö dania, ba ya''odo, Yehowa, zanguma''ö li khöra, ba wa''afahöna nadura andrö,', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 5, 'ba wombaya tödö ma''uwu Gizeraeli, me no la''erogö ndra''o, ba nadura andrö fefu.', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 6, 'Andrö wa ömane ba ma''uwu Gizeraeli: Da''ö niŵa''ö Zo''aya Yehowa: Mifalalini gera-erami, ba miböhöli nadumi andrö ba mi''erogö zogoro ita andrö khömi fefu.', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 7, 'Dozi ma''uwu Gizeraeli sa, ba niha bö''ö, si no fatewu ba Ndraono Gizeraeli, si fabali khögu, ba sangaro''ö ba dödöra adura, ba same''e fönara, tandraŵa horöra andrö ba si möi khö zama''ele''ö dania, ba wanofu khögu ba huhuo hadia ia khöra, ba ya''odo, Yehowa, zanguma''ö li khöra.', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 8, 'Utöngö niha si manö ba ube''e tandra ira ba amaedola ba uhori ira ba mbanuagu andrö, ena''ö aboto ba dödömi, wa no ya''o Yehowa.[1]', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 9, 'Ba na ibe''e nifowöhö ia sama''ele''ö, ba wanguma''ö li, ba no ya''o, Yehowa zamowöhö sama''ele''ö andrö, ba u''oro''ö dangagu khönia ba ubunu ia ba hunö mbanuagu Iraono Gizeraeli.', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 10, 'Ba lalu''i horöra, fagölö-gölö ira zala zanofu zala zama''ele''ö andrö,', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 11, 'ena''ö lö''ö sa''ae elungu ma''uwu Gizeraeli wangerogö ya''o, ba böi sa''ae lata''unöi ira, ba horöra andrö fefu; ya banuagu ira ba Lowalangira ndra''odo, iŵa''ö So''aya, Yehowa.[2]', '["MozV 28:37","RazI 22:22; TesII 2:11"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 12, 'Ba so na niŵa''ö Yehowa khögu, imane:', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 13, 'He ono niha, na mosala khögu niha ba danö, heza, na faröi ira khögu, ba na ubabaya ira, na ufufu wangabe''era andrö, öra, na ufatörö khöra lofo ba na uhori ba danö niha, fabaya uriföra,[3]', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 14, 'ba na so ba danö andrö niha andrö si datölu: Noakhi ba Danieli ba Yobi, ba ha ya''ira zauri, ba wa''atulö dödöra andrö, — iŵa''ö So''aya, Yehowa.[4]', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 15, 'Na u''ohe ba danö gutu ndru''u ena''ö lahori ndraono, ena''ö lö niha-niha sa''ae, ena''ö tanö si mate sa''ae, si lö sanörö, börö gutu ndru''u andrö,', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 16, 'ba na so ba danö niha andrö, si datölu, ba faya wa no sauri ndra''o, iŵa''ö So''aya, Yehowa, na so zauri labe''e, he ono matua, ba he ono alawe: ha ya''ira zauri, ba tanö, ba tobali tanö si mate.', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 17, 'Ba ma na si''öli ufatörö ba danö andrö, na umane: "Yatumörö danö andrö si''öli!" ba na uhori ba danö niha,', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 18, 'fabaya uriföra, ba na so ba danö niha andrö, si datölu, ba faya, wa no sauri ndra''o, iŵa''ö So''aya, Yehowa, na so zauri labe''e, he ono matua, ba he ono alawe; ha ya''ira zauri.', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 19, 'Ba ma na fökhö waba ufatörö ba danö andrö, ba na ulau khöra wönugu andrö, irugi ndro, ba wangohori ba danö niha, fabaya uriföra,', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 20, 'ba na so ba danö ndra Noakhi, Danieli, Yobi, ba faya, wa no sauri ndra''o, iŵa''ö So''aya, Yehowa, na so zauri labe''e, he ono matua, ba he ono alawe; ha ya''ira zauri, ba wa''atulö dödöra andrö.', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 21, 'Ba imane sa''ae So''aya, Yehowa: Ba na ufatörö ba Yeruzalema wotu andrö khögu, si öfa balö, si lö sökhi: Si''öli ba lofo ba utu ndru''u ba fökhö waba, ba wangohori ba danö niha, fabaya uriföra.[5]', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 22, 'ba hiza, ba so zi tosai ba danö, ni''orifi, sangoloi''ö ono matua ba ono alawe. Da''ö dania zi möi khömi, ba mi''ila mbua-buara, awö nilaura, ba arara dödömi, ba wamakao andrö nifatörögu ba Yeruzalema, ba ngawalö hadia ia, fefu, nifatörögu khöra.[6]', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476394, 'OT', 'Hezekieli', 14, 23, 'Ba tobali arara dödömi labe''e, na anehe ami mbua-buara, awö nilaura, ba aboto ba dödömi, wa no tenga si lö börö, me ulau khöra nilaugu andrö fefu, iŵa''ö So''aya, Yehowa.', '["Faigi 4:16","MozI 6:8; Dan 9:23; Faigi 28:3; Yob 42:10","Yer 15:3; Fam 6:8","Faigi 24:26"]', NULL),
  (3476395, 'OT', 'Hezekieli', 15, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Sin 80:9; Yer 2:21; Yoh 15:6"]', NULL),
  (3476395, 'OT', 'Hezekieli', 15, 2, 'He ono niha, hadia zi tohude ŵeŵe nagu, moroi ba duturu geu satoru moroi ba hogu geu ba gatua?[1]', '["Sin 80:9; Yer 2:21; Yoh 15:6"]', NULL),
  (3476395, 'OT', 'Hezekieli', 15, 3, 'Hadia, so zangai ya''ia, samali''ö fakake, hadia ia, hadia so zamali''ö saita ya''ia, ba wanaitagö ngawalö hadia ia wakake?', '["Sin 80:9; Yer 2:21; Yoh 15:6"]', NULL),
  (3476395, 'OT', 'Hezekieli', 15, 4, 'Hiza, ö galitö labe''e ia; ba na no akhozi mbalönia faföfö, ba na no ifelai alitö dalunia göi, ba hadia, so na gunania dania ba ngawalö hadia ia?', '["Sin 80:9; Yer 2:21; Yoh 15:6"]', NULL),
  (3476395, 'OT', 'Hezekieli', 15, 5, 'Hiza, me lö sakhozi na ia, ba lö gunania, ba wolau hadia ia; ba mendrua manö tebai la''oguna''ö ia ba da''ö, na no i''a alitö ba na no akhozi ösa.', '["Sin 80:9; Yer 2:21; Yoh 15:6"]', NULL),
  (3476395, 'OT', 'Hezekieli', 15, 6, 'Andrö wa imane So''aya Yehowa: Timba döla nagu ba ngai geu ba gatua, nihonogöigu ö galitö, ube''e dania mbanua Yeruzalema andrö.', '["Sin 80:9; Yer 2:21; Yoh 15:6"]', NULL),
  (3476395, 'OT', 'Hezekieli', 15, 7, 'Ba utöngö ira: No aefa ira ba galitö, ba alitö zui zi manga ya''ira dania, ba ya aboto ba dödömi, wa no ya''o Yehowa, na utöngö ira.', '["Sin 80:9; Yer 2:21; Yoh 15:6"]', NULL),
  (3476395, 'OT', 'Hezekieli', 15, 8, 'Ba ubali''ö tanö si mate danö, me no faröi ira, iŵa''ö So''aya Yehowa.', '["Sin 80:9; Yer 2:21; Yoh 15:6"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 2, 'He ono niha, tegu Yeruzalema ba zogoro ita andrö khöra, ömane:', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 3, 'Da''ö niŵa''ö Zo''aya, Yehowa, ba mbanua Yeruzalema: Si otarai ya''ugö ba börötamö, ba no ba danö Ndrawa Gana''ana: Tuau, ba Iraono Gamori, ba aweu, ba Iraono Kheti.', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 4, 'Ba ba wa''atumbumö andrö, me luo tumbu ndra''ugö, ba lö mutaba wusömö ba lö mufemondri ndra''ugö, ba wangehao ösiu, ba lö mudukhu asio ndra''ugö ba lö mulölö.', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 5, 'Lö sahakhö tödö ya''ugö, ba wolau khöu hadia ia, da''ö, ba wangahakhösi tödö ya''ugö. No nitibo''ö baero ba mbenua ndra''ugö, — awai zi so ba dödöra nosou, me luo tumbu ndra''ugö.', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 6, 'Ba utörö ndra''ugö, ba anehedo, me manaranara ndra''ugö, oi do, ba umane khöu: Ya''ugö andrö ba ndro andrö khöu, tou, ba ni''orifi ndra''ugö! umane khöu: sauri ndra''ugö, ba ndro andrö khöu!', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 7, 'Ba no u''oya''öndra''ugö, timba wa''oya rozi ngawalö ndru''u ba danö, ba no manöi''ö, ebua ndra''ugö, ba no tobali fondrege omasiö ndra''ugö: no afosu ndra''ugö, ba no itugu abölö mbumö, ba si lö nukha na ndra''ugö, si lö balu-balu.', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 8, 'Ba utörö ndra''ugö, ba u''ila''ö, ba hiza, ba no irugi baŵa wa''omasi khöu. Ba ubologö gambalagu balu-balumö, ubalugö ndra''ugö, me no lö nukhau, ba fawu''u li ndra''o khöu, möido ba hölu, iŵa''ö So''aya, Yehowa, ba no khögu sa''ae ndra''ugö.[2]', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 9, 'Ba ufemondri''ö ba nidanö, usasai ndro andrö khöu ba ubayoini fanikha ndra''ugö.', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 10, 'Ba ufonukha ndra''ugö nukha nifola''a-la''a, ba wanoso, ba ufobadagahe uli zaŵi nasi ndra''ugö; ba ufolembe ndra''ugö lembe tarafali ba salendra suto ube''e khöu.[3]', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 11, 'Ba u fo''aya ndra''ugö ba ube''e göla ba mbulökhamö ba aya ba mbagiu.', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 12, 'Ba aya ba nikhumö ba saeru dalinga ba dalingau ba takula si sökhi sibai ba högöu.[4]', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 13, 'Ba no nifo''aya ndra''ugö, aya ana''a ba aya firö, ba nukhamö, ba no tarafali, awö nukha sola''a-la''a. Ba fakhe samohua ba ŵe ŵani ba fanikha göu ba tobali si maulu wa''asökhiu ba ökhamö wa''asalaŵa.', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 14, 'Ba ebua duriamö ba niha baero misa, börö wa''asökhiu andrö, me no a''oi so, ba wangehao andrö, nibe''egu khöu, iŵa''ö So''aya, Yehowa.', '["Rut 3:9; MozII 19:5; MozV 7:6","Sin 45","MozI 24:47"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 15, 'Ba no öbe''e fa''abe''e dödöu wa''asökhimö andrö, ba mohorö ndra''ugö, börö duriamö andrö, öhöna wohorömö andrö ba zanörö fefu, ölulu ndra''ugö.[5]', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 16, 'Ba öhalö nukhamö andrö ösa, ba öbe''e tufo ba hili-hili andrö khöu, sola''a-la''a ba da''ö, ba mohorö-horö''ö ba da''ö — si lö irai ba si lö''ö sa''ae göi dania.[6]', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 17, 'Ba öhalö nayamö andrö, ana''agu ba firögu, nibe''egu khöu, ba öbali''ö famaedo ndra matua, ba mohorö''ö khöra.[7]', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 18, 'Ba öhalö nukhamö, sola''a-la''a andrö, ba öbe''e nukhara; ba fanikha andrö khögu ba kumöyö khögu, ba öbe''e sumangera.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 19, 'Ba kue andrö khögu, nibe''egu khöu, hamo si sökhi andrö khögu, ba no öbe''e-be''e sumangera, samohua; si manö mege, iŵa''ö So''aya, Yehowa.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 20, 'Ba öhalö nonou matua ba onou alawe, ni''adonogömö khögu, ba ötaba, öra; hadia, sambö na wohorömö andrö,[8]', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 21, 'wa ötaba na göi nonogu matua ba wame''e khöra, wa no ötutunu öra.[9]', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 22, 'Ba ba zogoro ita andrö khöu fefu ba ba wohorö-horömö, ba lö''ö sa itörö tödöu götö me ono sawuyu ndra''ugö, me lö nukhau, me lö balu-balumö, ba me manaranara''ö tou ba me oi do ndra''ugö!', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 23, 'Ba nönö-nönö zi lö sökhi andrö khöu fefu, — Alai ndra''ugö, alai ndra''ugö! — iŵa''ö So''aya, Yehowa,', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 24, 'ba ölau khöu nose ba öfazökhi khöu hili-hili ba golayama misa fefu.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 25, 'Ba ngai waerua lala fefu öfazökhi khöu hili-hili ba öbe''e ba zalakha wa''asökhimö andrö, dozi sanörö, ba öfolala khöu; no öhöna wohorömö.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 26, 'Mohorö''ö ba nono matua Ndrawa Miserayi, si faola tanö khöu, sebua ösi; ba ötohugö na wohorömö, ba wangandrö fönugu.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 27, 'Ba hiza, ba no u''oro''ö dangagu yaŵau ba no u''ambösi nihonogöi khöu, ba no ululu ndra''ugö ba wa''atebakha zi fa''udu khöu andrö, ono Ndrawa Wilisiti alawe, si no aila ba mbua-buamö fohorö andrö.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 28, 'Ba no mohorö''ö ba Ndrawa Asiria, ba tebai abuso ndra''ugö; no mohorö''ö khöra ba tebai aföli''ö.[10]', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 29, 'Ba no ötohu-tohugö na wohorömö ba danö zaniaga andrö, ba danö Galedaia, ba he ba da''ö göi, ba lö saföli ndra''ugö.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 30, 'No si tebakha sibai dödöu! iŵa''ö So''aya, Yehowa — wa no ölau da''ö fefu, nifolou zohorö, si no maulumaulu,', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 31, 'wa no ödozigö waerua lala, wolau ose khöu, ba he ewali fefu, wamazökhi hili-hili khöu; ba no tenga zui si mane sohorö, sanguma''ö no ambö luo, ndra''ugö.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 32, 'He alawe sohorö-horö, solulu ya''ia ba mbö''ö, lö lai wa no modonga ndra''ugö!', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476396, 'OT', 'Hezekieli', 16, 33, 'Dozi ira alawe sohorö, ba manema buala, ba ya''ugö, ba mamuala ba zomasi ya''ugö fefu, no öbe''e gana''a, ena''ö möi ira khöu, moroi ba zi fasui fefu, ba wohorö khöu.[11]', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 34, 'Ba no tobali ba khömö andrö, no tenga si mane huku ba ndra alawe bö''ö, ba wohorö-horömö andrö, no tenga nigohi ndra''ugö, no ya''ugö zame''e luo, ba lö''ö sa mufoluo ndra''ugö. No tobali ba khömö andrö.', '["Yer 2:20; Faigi 23:3","Faigi 7:20","Hos 2:8","MozIII 18:21","RazII 16:3","RazII 16:7; Nga''ötII 28:23; Faigi 23:12","Hos 8:9"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 35, 'Ba me no si manö, ya''ugö sohorö-horö, ba fondrondrongo li Yehowa!', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 36, 'Da''ö niŵa''ö Zo''aya, Yehowa: Me no mulau zaila''ö, ba me no mufa''ele''ö zi lö balu-balu khöu, ba wohorö-horömö andrö ba zomasi ya''ugö, ba ba nadumö andrö fefu, sihokha mbuda, ba börö na göi ndro ndraonou andrö, nibe''eu sumangera,', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 37, 'ba hiza ba u''ozaragö fefu zomasi ya''ugö, ba zi no omasiö ndra''ugö, ba somasi ndra''ugö, fabaya si lö edöna''ö ba si no te khöu öwa''ö. U''ozaragö ira khöu ba ufahoi mbalu-balu zaila''ö, ba zanehe ira, ena''ö la''ila zaila''ö andrö fefu.[12]', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 38, 'Ba uhuku ndra''ugö, huku zohorö ufatörö khöu, huku ndra alawe sange''e, ba ube''e aduwa ndromö, ba wönugu andrö ba ba wa''olohugu.[13]', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 39, 'Ba ube''e ba dangara ndra''ugö, ba ladudugö noseu andrö ba lafufu hili-hili andrö khöu ba laheta khöu nukhamö ba lahalö nayau ba si lö nukha sa''ae ndra''ugö, si lö balu-balu labe''e.', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 40, 'Ba falukha dania ira, udumö, ba latebu kara ndra''ugö ba la''ö''ötö ndra''ugö si''öli.', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 41, 'Ba latunu nomou ba lafatörö khöu huku, ba ato ndra alawe bö''ö samaigi-maigi, ba lö''ö sa''ae utehe sohorö-horö ndra''ugö, ba lö tola sa''ae öbe''e luora ba wohorö andrö.[14]', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 42, 'Ba u''okafui wönugu ba khöu andrö, dohö wa''olohugu khöu, ba lö hede-hedegu sa''ae, ba lö''ö sa''ae mofönudo.[15]', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 43, 'Me lö itörö tödöu mege, he wisa me ono sawuyu ndra''ugö, ba me no ö''andrö wönugu ba ngawalö andrö fefu, ba hiza, ba usulöni sa''ae khöu mbua-buau andrö! iŵa''ö So''aya, Yehowa, ba hadia, lö nifazökhiu fondrege horö, nönö-nönö zogoro ita andrö khöu fefu?[16]', '["Yes 47:3; Yer 13:26; Hos 2:10 b.t.","MozIII 20:10","RazII 25:9","Faigi 5:13","Faigi 9:10; 11:21"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 44, 'Hiza, dozi solau amaedola, ba laböbögö khöu, lamane: "No famaedo nina nono alawe".', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 45, 'Ono ninau ndra''ugö, ono ninau andrö, sanuzu tödö mege fo''omonia, fabaya ononia. Ba no talifusö dalifusöu ndra''ugö, sanuzu tödö fo''omora ba onora: Iraono Kheti gawemi ba Iraono Gamori duami.', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 46, 'Samaria ga''au ira alawe, ya''ia ba ononia alawe, si so ba ngaimö, ba gabera, ba akhiu andrö, si so ba gambölöu, ba ya''ia Zodoma ba ononia alawe.[17]', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 47, 'Ba no tenga lalara nitörömö ba tenga sogoro ita khöra nilaumö; lö arara, ba tedou walösökhi mbua-buamö fefu, moroi ba mbua-buara.', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 48, 'Faya wa no sauri ndra''o, iŵa''ö So''aya, Yehowa, na no irai ilau akhiu Sodoma ba ononia alawe nilaumi onou alawe![18]', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 49, 'Hiza, da''ö horö nakhiu Sodoma: Hokha, ba fa''afahöna mbalazo ba fa lö fa''abu dödö zi falukha ia, ba ononia alawe, ba si numana ba sambö balazo, ba lö latolo.[19]', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 50, 'Fayaŵa ira ba lalau zogoro ita fönagu; ba uheta ira, me u''ila da''ö.[20]', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 51, 'Ba lö''ö na''i matonga horömö nifazökhi Zamaria; no abölö-bölö wolaumö sogoro ita andrö, moroi khöra, ba tobali no öbu''a ba hulu ndra talifusöu, ba zogoro ita andrö fefu, nilaumö.[21]', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 52, 'Ba ötaha sa''ae göi wa''ailamö, ya''ugö andrö, me no möi''ö samu''a ba hulu ndra talifusöu, ba horömö andrö, ba zi no ölau sogoro ita, sabölö-bölö, moroi ba nilaura, ba tobali satulö moroi khöu ira. Ba yagö aila sa''ae, ba ötaha wa''ailamö, me no hulö zatulö dalifusömö öbe''e.', '["MozV 32:32; Yes 1:10; Yer 3:8","Mat 10:15","Luk 17:28","MozI 19:24","Yer 3:11"]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 53, 'Ufuli sa''ae uhakhösi tödö ira, Sodoma ba ononia alawe ba Samaria ba ononia alawe, ba uhakhözi tödö göi ndra''ugö, ba khöra u''ohe ndra''ugö,[22]', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 54, 'ena''ö ötaha wa''ailamö, ena''ö aila ndra''ugö ba nilaumö andrö fefu, na arara dödöra öbe''e.', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 55, 'Ba talifusoöe andrö, Sodoma ba ononia alawe, ba lakhamö si mane föna, ba Samaria ba ononia alawe, ba lakhamö, ba ya''ugö ba onou alawe, ba mikhamö si mane föna.', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 56, 'Ba lö nitörö liu Sodoma, talifusöu andrö, götö wayaŵasamö andrö,', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 57, 'me lö oroma na walösökhimö, si mane me luo la''o''aya ndra''ugö ono Ndraono Gedomo alawe, awö zi tefasui ya''ira fefu, ono Ndrawa Wilisiti alawe, sango''aya ya''ugö, fasui.[23]', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 58, 'Fohorömö andrö ba sogoro ita andrö khöu, ba no ölu''i, iŵa''ö So''aya, Yehowa.', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 59, 'Da''ö sa niŵa''ö Zo''aya, Yehowa: Usulöni khöu nilaumö, me ö''ositengagö wahölusa andrö ba me ödudugö wawu''usa li andrö.', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 60, 'Ba ya''o, ba lö olifudo wawu''usa li andrö, me fawu''u li ndra''o khöu, me iraono ndra''ugö, ba [ufuli] fawu''u li khöu, sirugi si lö aetu.[24]', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 61, 'Awena dania itörö tödöu mbua-buamö andrö ba aila ndra''ugö, na öhalö khöu ndra ga''au andrö, fabaya akhiu, na ube''e onou ira, ba tenga ba wawu''usa li andrö khöu.', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 62, 'Ba ulau fawu''u li khöu, ba ya aboto ba dödöu, wa no ya''o Yehowa.', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476396, 'OT', 'Hezekieli', 16, 63, 'Ena''ö itörö tödöu, ba ena''ö aila''ö, fa lö hede-hedeu sa''ae, ba wa''aila andrö, na ube''e aefa khöu nilaumö andrö fefu, iŵa''ö So''aya, Yehowa.', '["FetI 3:19,20","Yes 7:1","Yer 31:31 b.t."]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 2, 'He ono niha, lau dahö-dahö ba amaedola ba ma''uwu Gizeraeli, ömane:', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 3, 'Da''ö niŵa''ö Zo''aya, Yehowa: No so moroi sa moyo sebua, sebua sibai afi, sanau sibai bu, no a''oi so mbu si sökhi la''a-la''a; isaŵa hili Libano ba ifatö hogu geresi.[1]', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 4, 'Ikhete mbadöbadö ba i''oloi''ö ba danö zaniaga; ba mbanua soya lafo ibe''e.[2]', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 5, 'Ba ihalö zinanö ba danö, sara, ba itanö ba kabu, ba zabölö idanö ibe''e, timba mbou.', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 6, 'Ba auri ba tobali ŵeŵe nagu sanana tou ba danö, ba tobali aköi mangawuli khönia gasinia ba barönia so ŵa''ania. Ba me no tobali ŵeŵe nagu, ba fadahadaha ia, i''oro''ö ndrahania.', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 7, 'Ba so moyo bö''ö, sebua ba sebua afi ba sabölö bu, ba hiza, ba ifaudugö ia ŵa''ania ŵeŵe nagu andrö ba i''oro''ö khönia ndrahania, ena''ö khönia isöndra nidanö, ba tenga ba gowoto andrö nitanö ya''ia,', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 8, 'he ŵa''ae no ba danö si sökhi ba sabölö idanö tetanö ia mege, ena''ö modaha ia ba ena''ö mowua, ena''ö tobali ŵeŵe nagu si no maulu fa''asökhi.', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 9, 'Ba ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Hadia, si sökhi maö lua-lua dania? Hadia, lö ideha dania ŵa''ania [sananö ya''ia mege], ba lö iteu mbuania, fa aleu lehelehenia fefu? Ba tenga ba wa''abölö danga, ba tenga ba wa''ato niha, na ideha ŵa''ania.', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 10, 'Ba hiza, ba no sinanö ia; ba hadia, si sökhi maö lua-lua dania? Hadia, lö alua manö aleu, na göna ia angi moroi ba gatumbukha luo, lö aleu ia ba gowoto andrö, ba nitanö ya''ia?[3]', '["Yer 48:40; 49:22","Faigi 16:29","MozI 41:6"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 11, 'Ba so niŵa''ö Yehowa khögu, imane:', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 12, 'Ömane ba niha sabe''e tandro andrö: Hadia, lö aboto ba dödömi geluaha da''ö? Ömane: Hiza, no möi ba Yeruzalema razo Mbabeli ba no ifara''u''ö razora, awö gumandru sebua khönia, ba no i''ohe khönia ba Mbabeli.[4]', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 13, 'Ba no ihalö göi nga''ötö razo, ba no fawu''u li ia khönia, no ibe''e ba hölu, ba salaŵa ba danö, ba no i''ohe,[5]', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 14, 'ena''ö böi ebua wa''asalaŵa, ena''ö böi fayaŵa [razo] ba fa böi iwu''ai wawu''usa li andrö khönia, ena''ö aro.', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 15, 'Ba no fabali ia khönia, ba no ifatenge zinenge ba danö Miserayi, ena''ö lafa''ohe''ö khönia kudo ba ena''ö lafatenge niha. Hadia, si sökhi maö lua-lua da''ö? Hadia, sauri maö zolau si mane da''ö? Hadia, auri ia, na no idudugö wawu''usa li andrö?[6]', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 16, 'Faya wa no sauri ndra''o, iŵa''ö So''aya, Yehowa, na tenga ba mbanua razo andrö mate, ba mbanua razo andrö, samali''ö razo ya''ia mege, si no isawö si möi ia ba hölu mege, awö wawu''usa li andrö, khönia ba Mbabeli bakha mate ia.', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 17, 'Ba Fara''o andrö, ba lö''ö sa itolo ia sabölö khönia, ba he ba wa''ato niha khönia, ba wasuwöta, na lako''o fari dania ba na lalau malige, ba wangohori niha, sato sibai.[7]', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 18, 'Noa sa isawö zi no möi ia ba hölu mege, me no iwu''ai wawu''usa li andrö: he ŵa''ae no fara''u tanga ira, ba no ilau zui da''ö fefu; ba lö auri ia ba da''ö.', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 19, 'Andrö wa imane So''aya, Yehowa: Faya wa no sauri ndra''o, na lö usulöni khönia wahölusania andrö, ba khögu mege, si no i''ositengagö, ba he fawu''usa li andrö, me fawu''u li ia fönagu, niwu''ainia.', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 20, 'Ba uhawui ia u''ö andrö khögu, ena''ö alau ia ba gu''ögu; ba u''ohe ia ba Mbabeli, ba ba da''ö uhuku ia, ba walimosania andrö khögu.[8]', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 21, 'Ba fondrege zabölö andrö khönia, ba zabölö andrö khönia fefu, ba si mate ba mbawa zi''öli dania, ba si tosai, ba nifazawili misa ba zi fasui fefu, ena''ö aboto ba dödömi, wa no ya''o, Yehowa, zanguma''ö.[9]', '["RazII 24:10 b.t.","RazII 24:17 b.t.","Nga''ötII 36:13","Faigi 4:2","Faigi 12:13","Faigi 5:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 22, 'Da''ö niŵa''ö Zo''aya, Yehowa: Uhalö göi zara duturu ba hogu geresi salaŵa andrö ba utanö. Ba duturunia ba wondrege hogu ufatö zara sise-ise, ba utanö yaŵa ba hili salaŵa.[10]', '["Yes 4:2; 11:1; Yer 23:5; 33:15; Sakh 3:8; 6:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 23, 'Ba hili salaŵa andrö ba Ndraono Gizeraeli utanö, ena''ö modaha ia, ba ena''ö mowua ba ba ena''ö tobali eresi salaŵa sibai, nahia ngawalö wofo; ba lumö ndrahania la''iagö.', '["Yes 4:2; 11:1; Yer 23:5; 33:15; Sakh 3:8; 6:12"]', NULL),
  (3476397, 'OT', 'Hezekieli', 17, 24, 'Ba ya la''ila töla geu ba mbenua fefu, wa no ya''o Yehowa zangide-ide''ö eu sebua, awö wa no u''ebua''ö geu side-ide, wa no mangadolu geu sauri ube''e, awö wa no mobowo geu si no mate mege: ya''odo, Yehowa zanguma''ö ba no ya''odo zolau.', '["Yes 4:2; 11:1; Yer 23:5; 33:15; Sakh 3:8; 6:12"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 2, 'Hana ami, wa milau-lau gamaedola andrö ba danö Ndraono Gizeraeli, wa mimane: "Ira ama mege zi manga mbua nagu saisö, ba iraonora zafuru boha?"[1]', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 3, 'Faya wa no sauri ndra''o, iŵa''ö So''aya, Yehowa, na milau na dania gamaedola andrö, ba Ndraono Gizeraeli!', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 4, 'Hiza, no khögu noso niha fefu, he noso nama, ba he noso nono, ba no khögu; sosala zaetu noso![2]', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 5, 'Na so zatulö tödö, na ilau zadölö ba satulö,', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 6, 'na lö i''a gö nadu, ba hili, ba na lö ifaöga hörönia ba nadu ma''uwu Gizeraeli andrö, ba na lö i''aohafi ndronga nawönia, ba na lö orudu ia ba ndra alawe, götö wa''afökhö dalunia,[3]', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 7, 'na lö ifakao nawönia, ba na ifulifuli gade zugilönia, ba na lö falau horö ia ba na ibe''e ö zolofo gönia ösa, ba na ifobalu-balu zi lö nukha,[4]', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 8, 'ba na lö i''ebua''ö hare gana''ania, na lö ifo''ono gana''ania, ba na lö ibabaya zi lö sökhi, ba na lö ifuyu''ö huku ba niha bö''ö,[5]', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 9, 'ba na i''o''ö nifakhoigu, ba na itöngöni huku andrö khögu, wolau sadölö, — da''ö niha satulö, ba lö zi lö auri zi manö, iŵa''ö So''aya, Yehowa.', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 10, 'Ba na mo''ono ia ono samakao awönia, sange''enge''e ba solau si lö sökhi,', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 11, 'ba si lö manörö lala namania andrö, satulö tödö; si manga gö nadu, ba hili, ba si angaohafi donga nawönia,', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 12, 'ba samakao side-ide ba si numana, ba si falau horö, ba si lö mamuli gade, ba samaöga hörönia ba nadu andrö,', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 13, 'ba solau sogoro ita, ba sangebua hare zugilönia, samo''ono ana''ania, hadia, sauri zi manö? Lö auri zi mane da''ö! Me no ilau zogoro ita andrö, fefu, ba huku famunu hukunia; ya''ia zolu''i donia.', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 14, 'Ba na mo''ono zui zi manö, ba na i''ila zala namania fefu ono andrö, ba na ata''u ia ba na lö i''ohia''ö da''ö,', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 15, 'na lö i''a gö nadu, ba hili, ba na lö ifaöga hörönia ba nadu ma''uwu Gizeraeli andrö, ba na lö i''aohafi ndronga nawönia, ba na lö ifakao nawönia,', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 16, 'ba na lö itagö gade ba na lö falau horö ia, ba na ibe''e ö zolofo gönia ösa ba na ifobalu-balu zi lö nukha, ba na lö ibabaya zi lö sökhi,', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 17, 'ba na lö i''ebua''ö hare zugilönia, na lö ifo''ono gana''ania, ba na i''o''ö huku andrö khögu, na itörö nifakhoigu, — ba lö mate ba horö namania zi manö, sauri ia.', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 18, 'Amania andrö, me no ifakao nawönia ba me no falau horö ia, ba me no ilau zi lö sökhi, bakha ba hunö niwara, — da''ö zi mate, börö horönia andrö.', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 19, 'Ba mimane: Hana wa lö ilu''i göi horö namania ono? Na no i''o''ö huku ono, ba na no ilau zatulö, ba na no itöngöni nifakhoigu, ba na no i''o''ö, ba sauri ia.', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 20, 'Niha solalö, da''ö zi mate. Lö ilu''i horö namania ono, ba lö ilu''i horö nononia ama. Lö tebulö khö zatulö tödö wa''atulö dödönia andrö, ba lö tebulö khö zebua horö golalöŵania andrö![6]', '["Yer 31:29","Rom 5:12; Yak 1:15","Yes 57:7; Faigi 22:9; MozIII 18:20; 20:18","MozII 22:26; MozIII 19:13; MozV 15:7; Yes 58:7","MozII 22:25","MozV 24:16; Hab 2:4"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 21, 'Ba na ifalalini gera-erania sebua horö, na iböhöli horö andrö nifazökhizökhinia mege, ba na itöngöni nifakhoigu ba na ilau zadölö ba satulö, ba auri ia, lö mate.', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 22, 'Fangerogönia andrö, bua-buania mege, ba lö''ö sa''ae tebe''e horönia; auri ia, börö zatulö andrö, nilaunia.', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 23, 'Hadia, somasi fa''amate zebua horö ndra''odo, iŵa''ö So''aya, Yehowa, hadia, lö omasido, na iböhöli mbua-buania si lö sökhi andrö, ba na auri ia?[7]', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 24, 'Ba na iböhöli wa''atulö dödönia satulö tödö, ba na ilau zi lö sökhi, si mane sogoro ita andrö, nilau zebua horö, ba lö''ö sa''ae guna mbua-buania si sökhi andrö, mege; si mate ia, börö walimosania andrö, nilaunia, awö horönia andrö, nifazökhinia.[8]', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 25, 'Ba na miŵa''ö: Tenga satulö wolau Yehowa! ba mifondrondrongo, ya''ami ma''uwu Gizeraeli: hadia, folaugu zi lö atulö? Hadia, tenga folaumi zi lö atulö?[9]', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 26, 'Na iböhöli wa''atulö dödönia satulö tödö, ba na ilau zi lö sökhi, ba si mate ia, börö da''ö; börö wa''amatenia zi lö sökhi andrö, nilaunia.', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 27, 'Ba na iböhöli mbua-buania mege sebua horö ba na ilau zadölö ba satulö, ba lö mate ia.', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 28, 'Me no iböhöli wangerogönia andrö, mege, fefu, ba sauri ia, lö mate.', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 29, 'Ba na lamane ma''uwu Gizeraeli: Tenga satulö wolau Yehowa! ba hadia, si ndruhu, folaugu zi lö atulö, ya''ami ma''uwu Gizeraeli? Hadia, tenga folaumi andrö zi lö atulö?', '["Faigi 33:11; TimI 2:4; FetII 3:9","Faigi 3:20","Faigi 33:17"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 30, 'Andrö wa bua-bua zamösana ube''e dali wanguhuku ya''ami, ya''ami ma''uwu Gizeraeli! iŵa''ö So''aya, Yehowa. Mifalalini gera-erami, miböhöli walimosami andrö fefu, fa böi tobali tandraŵa horö, khömi.', '["Faigi 11:19; 36:26","Faigi 33:11"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 31, 'Miböhöli walimosami andrö fefu, nilaumi khögu, ba mifaigi khömi dödö si bohou ba era-era si bohou; hana sa wa edöna mate ami, ya''ami ma''uwu Gizeraeli![10]', '["Faigi 11:19; 36:26","Faigi 33:11"]', NULL),
  (3476398, 'OT', 'Hezekieli', 18, 32, 'Lö''ö sa omasido wa''amate zi mate andrö, iŵa''ö So''aya, Yehowa. Ba miböhöli, ena''ö auri ami.[11]', '["Faigi 11:19; 36:26","Faigi 33:11"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 1, 'Ba ya''ugö, ba e''esi razo Ndraono Gizeraeli, ömane:', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 2, 'Ha niha ninau? Singo si alawe; ba ngai zingo mörö-mörö ia, ba ngai nono zingo i''e''ebua nononia.', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 3, 'Sara zebua ononia; ba tobali ono zingo da''ö ba ifamaha ia ba wondra''undra''u, i''a niha.', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 4, 'Ba la''ekhugö niha khönia niha baero, ba lösu-lösu khöra lafa''ala ia, lafesu nikhu ba la''ohe ba danö Miserayi ia.[1]', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 5, 'Ba me i''ila [inania] ara manö ba lö tötönafö sa''ae, ba ihalö nononia si sara, ba ibali''ö ono zingo.', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 6, 'Ba fao-fao ia ba zingo, tobali ono zingo, ifamaha ia ba wondra''undra''u, i''a niha.', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 7, 'Ba i''aohafi lakha mbanua khöra ba idudugö mbanua, ba tobali tanö si mate danö, fabaya ösinia, ba wendröndröndröndrönia.', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 8, 'Ba lafasui ia niha baero, udunia, moroi ba danö si tefasui ya''ira, ba lahawui ia u''öra, ba ba lösu-lösu khöra lafa''ala ia.', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 9, 'Ba lafesu nikhu ba ladöni ba haya, ba la''ohe ia khö razo Mbabeli, si yaŵa ba hati labe''e, ena''ö lö''ö sa''ae terongo linia ba hili Ndraono Gizeraeli.[2]', '["RazII 23:31 b.t. Yer 22:11; Yes 37:29","RazII 24:1 b.t.; Nga''ötII 36:5 b.t.; Yer 22:19"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 10, 'No timba ŵeŵe nagu ninau, si mane ya''ugö, ŵeŵe nagu nitanö ba mbewe nidanö; no abölö mbua ba no abölö ndraha, börö wa''abölö nidanö.[3]', '["Faigi 17:6","Faigi 17:10"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 11, 'Ba sara zesolo dahania, tola si''o zalaŵa; manöi ia, bakha ba zarege daha, ba to''ele ia, ba wa''alaŵania ba ba wa''oya zi fadahadaha.', '["Faigi 17:6","Faigi 17:10"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 12, 'Ba tedeha ia ba wönu, tetibo''ö tou ba danö, ba oköli mbuania ibe''e angi timu; nilöwa ndrahania sesolo ba mangadolu, ö galitö.[4]', '["Faigi 17:6","Faigi 17:10"]', NULL),
  (3476399, 'OT', 'Hezekieli', 19, 13, 'Ba iya''e, ba no mutanö ba danö si mate, ba danö soköliköli, si no timba zowökhi tödö.', '["Faigi 17:6","Faigi 17:10"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476399, 'OT', 'Hezekieli', 19, 14, 'Ba no i''a duturunia alitö, si otarai ndraha no mege, ba lö si tosai khönia daha sesolo, lö''ö sa''ae si''o zalaŵa. Fangarö-ngarö da''e ba no tobali fange''esi.', '["Faigi 17:6","Faigi 17:10"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 1, 'Ba ba ndröfi si fitu, ba zi mewulu ba mbaŵa si lima, ba sozatua Ndraono Gizeraeli, ösa ba wanofu khö Yehowa, ba mudadao ira fönagu.', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 2, 'Ba humede khögu Yehowa, imane khögu:', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 3, 'He ono niha, hede ba zatua Ndraono Gizeraeli andrö, ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Hadia, ba wanofu khögu möi ami, Faya wa no sauri ndra''o, na utehe khömi wanofu khögu, iŵa''ö So''aya, Yehowa.', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 4, 'Ba na öfatörö khöra huku, na ö''otu''ö ira, ya''ugö ono niha, ba ombakha''ö khöra zogoro ita andrö khö ndra tuara mege,[1]', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 5, 'ba ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Me luo utuyu Ndraono Gizeraeli, ba no ufazaŵa dangagu [we''amöi ba hölu] ba nga''ötö ma''uwu Gezeraeli, ba no ufa''ele''ö ndra''o khöra, ba danö Miserayi; no ufazaŵa dangagu khöra, ba no umane: Yehowa ndra''odo, Lowalangimi![2]', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 6, 'Me luo da''ö ufazaŵa dangagu khöra [we''amöi ba hölu] wa uheta ira ba danö Miserayi, awö wa u''ohe ira ba danö ni''aluigu khöra, tanö si falawu susu ba ŵe ŵani, — fondrege zi sökhi danö fefu![3]', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 7, 'Ba no umane khöra: Dozi ami, ba mitibo''ö zihokha mbuda andrö, ba duduma hörömi, ba böi mihalö zalakha khömi nadu Ndrawa Miserayi andrö! No ya''odo Yehowa, Lowalangimi!', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 8, 'Ba no sabe''e tandro ira, ba lö edöna lafondrondrongo ligu; sihokha mbuda andrö fönara, ba lö latibo''ö, ba adu Ndrawa Miserayi andrö, ba lö laböhöli. Ba uhawui ena''ö ira bakhu-bakhu dödögu andrö, ba uhorigö ena''ö wönugu ba khöra, ba dalu danö Ndrawa Miserayi.', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 9, 'Ba lö olifudo döigu andrö, fa böi te''o''aya da''ö ba zanehe niha baero, ba zi so ira, sanehe, me ufa''ele''ö ndra''o khöra, me uheta ira ba danö Miserayi.', '["Faigi 22:2; 23:36","MozII 6:2 b.t.","MozII 3:8"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 10, 'Uheta ira ba danö Miserayi ba u''ohe ira ba danö si mate; ba ufakhoi khöra nifakhoigu,', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 11, 'ba u''ombakha''ö khöra huku khögu, ni''o''ö niha, ena''ö auri ia ba da''ö.[4]', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 12, 'Ba luo sabato andrö khögu göi ube''e khöra, ena''ö tandra ia khöma, ena''ö aboto ba dödöra, wa no ya''o, Yehowa, zi amoni''ö ya''ira.[5]', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 13, 'Ba no lö la''o''ö khögu ma''uwu Gizeraeli, ba danö si mate, lö latörö nifakhoigu ba lö ba dödöra huku andrö khögu, ni''o''ö niha, ena''ö auri ia ba da''ö; ba luo sabato andrö khögu, ba no laforege wango''aya. Ba uhawui ena''ö ira bakhu-bakhu dödögu andrö, ba danö si mate, ba wangohori ya''ira.[6]', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 14, 'Ba lö''ö zui olifudo döigu andrö, fa böi te''o''aya da''ö ba zanehe niha baero, si no anehe, me uheta ira.', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 15, 'Ba no ufazaŵa göi dangagu khöra, ba danö si mate [möido ba hölu khöra], wa lö u''ohe ira ba danö andrö nitehegu khöra tanö si falawu susu ba ŵe ŵani — , fondrege zi sökhi danö fefu![7]', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 16, 'me no lö ba dödöra huku andrö khögu, ba me lö latörö nifakhoigu ba me la''o''aya luo sabato andrö khögu; me no ba nadu khöra molemba dödöra.[8]', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 17, 'Ba no abölö ahakhö dödögu ira, ba tebai ufakiko ira, ba lö ufalua wangohori ya''ira, ba danö si mate.', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 18, 'Ba no umane ba ndraonora, ba danö si mate: Böi mi''o''ö gamuata ndra amami ba böi mitöngöni huku andrö khöra ba böi mita''unöi ami ba nadura!', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 19, 'Ya''odo Yehowa, Lowalangi: nifakhoigu mitörö ba huku khögu mitöngöni ba mi''o''ö!', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 20, 'Ba he luo sabato andrö khögu, ba mi''amoni''ö, ena''ö tandra ia khöda, ena''ö aboto ba dödö, wa no ya''odo Yehowa, Lowalangimi.', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 21, 'Ba iraonora andrö göi, ba lö lafondrondrongo ligu: lö latörö nifakhoigu ba lö latöngöni huku andrö khögu, ba wolo''ö ena''ö ni''o''ö niha, ena''ö auri ia ba da''ö; ba he luo sabato andrö khögu, ba no la''o''aya. Ba uhawui ena''ö ira bakhu-bakhu dödögu andrö, ba uhorigö ena''ö wönugu khöra, ba danö si mate.', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 22, 'Ba ufuli zui uböda dangagu, ba lö olifudo döigu andrö, fa böi te''o''aya da''ö, ba zanehe niha baero andrö, si no anehe mege, me uheta ira.', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 23, 'Ba no ufazaŵa dangagu khöra ba danö si mate [möido ba hölu] wa utibo''ö ira ba niha baero, wa ufazawili ira ba danö zotanö misa,[9]', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 24, 'me no lö la''o''ö huku andrö khögu, ba me lö ba dödöra nifakhoigu, ba me la''o''aya luo sabato andrö khögu, ba me lö aefa höröra ba nadu ndra amara andrö.', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 25, 'Ba no ufakhoi khöra zambö fa''asökhi ba no uhonogöi huku si tenga fangorifira.[10]', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 26, 'Ta''unö ira ube''e, ba gö nadu andrö khöra — me no ahori manö lafatörö ba galitö zi a''a nonora — ena''ö muhokha mbura ube''e, fa aboto ba dödöra, wa no ya''odo Yehowa.[11]', '["MozIII 18:5; Luk 10:28","MozII 20:8; 31:13; 35:2","MozII 16:28; 32:10","MozIV 14:30","Amos 5:25,26","MozIII 26:33","Rom 1:28","MozIII 18:21; MozV 12:31; Faigi 16:20"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 27, 'Andrö wa muhede''ö ba ma''uwu Gizeraeli, ya''ugö ono niha, ömane khöra: Da''ö niŵa''ö Zo''aya Yehowa: Sambalö na wango''aya ndra tuami ya''odo, me no la''erogö ndra''o.', '["Yes 57:5","Yer 44:17"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 28, 'Me no u''ohe ira ba danö andrö, nifabu''ugu khöra, we''amöi ba hölu, ba na la''ila hili-hili salaŵa, heza, ba ma eu sabölö bulu, ba latataba ba da''ö zumange nadu khöra ba ba da''ö labe''e game''elara andrö, sanuzu dödöda, ba he sumange samohua andrö khöra ba he sumange nibadu.[12]', '["Yes 57:5","Yer 44:17"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 29, 'Ba umane khöra: Hadia hili-hili andrö, si möi-möi ami? Andrö wa labe''e töinia "hili-hili", irugi ma''ökhö andre.', '["Yes 57:5","Yer 44:17"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 30, 'Ba ömane sa''ae ba ma''uwu Gizeraeli: Da''ö niŵa''ö Zo''aya, Yehowa: Hadia, huku khö ndra tuami mi''o''ö, wana''unöi ya''ami, ba mohorö-horö ami ba zihokha mbuda andrö khöra.', '["Yes 57:5","Yer 44:17"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 31, 'Ba wame''e sumange andrö khömi ba ba wamatörö ba galitö onomi matua, mita''unöi ami ba nadu andrö khömi, fefu, irugi ma''ökhö andre, ba hadia, ba utehe khömi wanofu khögu, ya''ami, ma''uwu Gizeraeli? Faya wa no sauri ndra''o, iŵa''ö So''aya, Yehowa, na utehe khömi wanofu khögu!', '["Yes 57:5","Yer 44:17"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 32, 'Ba hadia niŵa''ömi tödömi, ba lö''ö manö itörö, me no mimane dödömi: Tafaomagö ita ba niha baero, ba niha ba danö niha baero, wamosumange eu ba kara.[13]', '["Yes 57:5","Yer 44:17"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 33, 'Faya, wa no sauri ndra''o, iŵa''ö So''aya, Yehowa, na lö möido samatörö ya''ami ba na lö u''abe''e''ö dangagu ba na lö u''oro''ö ba na lö ulau mbakhu-bakhu dödögu.[14]', '["MozV 5:15","Yes 31:2; Hos 2:14","MozIII 27:32; Mikh 7:14"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 34, 'Ba uheta ami ba niha baero, u''ozaragö ami moroi ba danö misa, ba zi no tefazawili ami, u''abe''e''ö dangagu ba u''oro''ö ba ulau mbakhu-bakhu dödödögu.', '["MozV 5:15","Yes 31:2; Hos 2:14","MozIII 27:32; Mikh 7:14"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 35, 'Ba u''ohe ami ba danö si mate ba niha baero, ba ba da''ö fahuhuo ita, si faudu wawa ita.[15]', '["MozV 5:15","Yes 31:2; Hos 2:14","MozIII 27:32; Mikh 7:14"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 36, 'Si mane me fahuhuo ndra''o khö ndra tuami ba danö si mate, ba danö Miserayi, si manö göi na fahuhuodo khömi, iŵa''ö So''aya, Yehowa.', '["MozV 5:15","Yes 31:2; Hos 2:14","MozIII 27:32; Mikh 7:14"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 37, 'Ba ufatörö ami barö zi''o ba ube''e ba wesu wawu''usa li andrö ami.[16]', '["MozV 5:15","Yes 31:2; Hos 2:14","MozIII 27:32; Mikh 7:14"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 38, 'Ba uheta ba khömi zi no molaŵa ya''odo ba si no fabali khögu. Uheta ira ba danö andrö, ba zi no niha bö''ö ira, ba lö''ö sa larugi danö Ndraono Gizeraeli, ena''ö aboto ba dödömi, wa no ya''odo Yehowa.', '["MozV 5:15","Yes 31:2; Hos 2:14","MozIII 27:32; Mikh 7:14"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 39, 'Ba ya''ami, ma''uwu Gizeraeli, ba da''ö niŵa''ö Zo''aya, Yehowa: Mi''ae mitunu nadumi andrö, dozi ami; ba aefa da''ö — hadia, si ndruhu lö mifondrondrongo ligu? — ba lö''ö sa''ae mi''o''aya döigu andrö, ni''amoni''ö ba gö nadu andrö khömi ba ba nadumi andrö.', '["MozV 5:15","Yes 31:2; Hos 2:14","MozIII 27:32; Mikh 7:14"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 40, 'Ba hili ni''amoni''ö andrö khögu, ba hili salaŵa andrö ba Ndraono Gizeraeli, iŵa''ö So''aya, Yehowa, ba da''ö lafosumange dania ndra''odo ma''uwu Gizeraeli ba danö, dozi; ba u''ebua''ö sa''ae dödögu, wangai ya''ami khögu ba ebua dödögu ba zumange nihalö fegero ba ba zi a''a game''ela andrö khömi, ba game''elami ni''amoni''ö andrö, fefu.', '["Faigi 6:9"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 41, 'Ba wa''amohua andrö u''ebua''ö dödögu wangai ya''ami khögu, na uheta ami ba niha baero ba na u''ozaragö ami ba danö misa, ba nifazawili ya''ami, ba ufa''ele''ö wa no ni''amoni''ö ndra''odo, ba zanehe niha baero.', '["Faigi 6:9"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 42, 'Ba aboto dania ba dödömi, wa no ya''o Yehowa, na u''ohe ami ba danö Ndraono Gizeraeli, ba danö si no möido ba hölu khö ndra tuami, ba wame''e khöra.', '["Faigi 6:9"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 43, 'Ba itörö dania tödömi mbua-buami, awö zi lö sökhi andrö, fefu, nilaumi, wana''unöi ya''ami, ba ogoro dania ami wolaumi andrö, börö zi lö sokhi andrö, fefu, nifazökhimi.[17]', '["Faigi 6:9"]', NULL),
  (3476400, 'OT', 'Hezekieli', 20, 44, 'Ba ya aboto ba dödömi, wa no ya''o Yehowa, na lö olifudo döigu andrö, ba nilaugu khömi, na lö ube''e dali mbua-buami andrö, si lö sökhi, ba he folaumi andrö, si lö sökhi, ya''ami ma''uwu Gizeraeli, iŵa''ö So''aya, Yehowa.', '["Faigi 6:9"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Faigi 21:2","Luk 23:31","Faigi 17:2"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 2, 'He ono niha, otahögö danö miraya, ba miraya lau huhuomö ba ama''ele''ö, nitandrösaigö ba gatua andrö ba mbenua, ba danö tanö raya,[1]', '["Faigi 21:2","Luk 23:31","Faigi 17:2"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 3, 'ba ömane ba gatua andrö, ba danö tanö raya: Fondrondrongo li Yehowa! Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, u''ebua''ö galitö khöu, si manga geu sauri fefu, fabaya adolu fefu. Si lö mate hola-hola galitö andrö, ba bawa niha fefu, i''otarai moroi raya, numalö miyöu, ba ariri ibe''e.[2]', '["Faigi 21:2","Luk 23:31","Faigi 17:2"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 4, 'Ba dozi niha dania zangila, wa no ya''o, Yehowa, zangebua; si lö mate ia.', '["Faigi 21:2","Luk 23:31","Faigi 17:2"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 5, 'Ba umane: Alai ndra''o, ya''ugö So''aya, Yehowa! Lamane dania ba khögu andre: Hadia, tenga solau amaedola?[3]', '["Faigi 21:2","Luk 23:31","Faigi 17:2"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 6, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Faigi 7:17"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 7, 'He ono niha, otahögö Yeruzalema, ba angombakha, nitandrösaigö ba ni''amoni''ö andrö ba ama''ele''ö, nitandrösaigö ba danö Ndraono Gizeraeli.', '["Faigi 7:17"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 8, 'Ömane ba danö Ndraono Gizeraeli: Da''ö niŵa''ö Yehowa: Hiza, ulau khöu, usöbi zi''öligu ba uhori ba danö he satulö tödö, ba he sebua horö.', '["Faigi 7:17"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 9, 'Me edönado uhori ba danö zatulö tödö, fabaya sebua horö andrö, wa aheta ba zaembu zi''öligu, famunu niha fefu, i''otarai moroi raya, numalö miyöu.', '["Faigi 7:17"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 10, 'Ba ya aboto ba dödö niha fefu, wa no ya''odo, Yehowa, zanöbi si''öli; lö''ö sa''ae mangawuli ba zaembu.', '["Faigi 7:17"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 11, 'Ba ya''ugö ono niha, ba angarö-ngarö! Ya timba safatö sola ndra''ugö ba sabu sibai tödö wangarö-ngarö, ba zanehe ira!', '["Faigi 7:17"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 12, 'Ba na lamane khöu: Hadia wa mangarö-ngarö''ö? ba ömane: Me no murongo duria ba zangulu dödö fefu ba ba zadada danga fefu, ba zi taya gera-era fefu ba ba zi tobali idanö mbalöduhi fefu. Hiza, alua, itörö, iŵa''ö So''aya, Yehowa.[4]', '["Faigi 7:17"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 13, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 14, 'He ono niha, ama''ele''ö, ömane: Da''ö niŵa''ö Yehowa: Ömane: Si''öli, no mudali zi''öli, no muhaogö!', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 15, 'Ba wangö''ötö niha, wa no ladali ia, ba wa''atakile, wa no lahaogö. Tenga si lö abölö mbözi-bözi nonogu andrö, no si lö ba dödö ngawalö geu fefu.', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 16, 'Ba no ibe''e nihaogö, ena''ö ituyu tangania. No mudali zi''öli andrö ba no muhaogö, ba wame''e ba danga zamunumunu niha ya''ia.', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 17, 'Ege''ege ba angarö-ngarö, ya''ugö ono niha, telau sa''ae ba mbanuagu ba ba zalaŵa Ndraono Gizeraeli, fefu! Ö zi''öli sa''ae ira, fabaya banuagu andrö; ba bözi zolamö!', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 18, 'Noa sa mutandraigö — "ba he wisa, na te khö mbözi-bözi andrö?" Tebai da''ö, iŵa''ö So''aya, Yehowa.', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 19, 'Ba ya''ugö, ono niha, ba ama''ele''ö ba lau datawo, ba tölu dania zi''öli, si''öli famunu, si''öli famunu sebua zamasui ya''ira,[5]', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 20, 'ena''ö mangulu dödö, ba ena''ö ato ni''ö''ötö tou, ba mbawa göli khöra fefu. Takile zi''öli ube''e, na amaedola gari mbanua tebe''e ia, no ba wamunu ladali.', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 21, 'Bali''ögö furi, saŵa gambölö, dölö''ö, saŵa gabera, he zi no muwa''ö mbawau!', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 22, 'Ba ya''odo göi, ba ulau dataŵo, ba ufadöhö wönugu; ya''odo, Yehowa zanguma''ö.[6]', '["Faigi 6:11","Faigi 16:42"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 23, 'Ba so niŵa''ö Yehowa khögu, imane:', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 24, 'He ono niha, honogöi, dua rozi lala zi''öli andrö khö razo Mbabeli, ha sambua danö, si otarai lala andrö, si dua rozi. Ba dozi bawa lala ba mbanua heza, ba öbe''e dandra,', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 25, 'ena''ö itörö Raba Ndraono Gamoni ba tanö mado Yuda, ba Yeruzalema ba dalu, si''öli andrö.', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 26, 'Noa sa so ba wabaliŵa lala razo Mbabeli, ba mbawa lala andrö si dua rozi, ba wolau faetasa; ifahisi nono wana, isofu ba ziraha ba ifaigi gate.[7]', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 27, 'Ba dangania kambölö, ba dahö-dahö "Yeruzalema", ba wame''e famoto göli ba ba we''ao ba ba wangahahagö ba ba wamataro forasa mbawa göli, ba wogo''o fari ba ba wolau malige zanuwö.[8]', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 28, 'Ba ba dödöra, ba no hulö waetasa faya; famaigira, ba ara na, ha uga migu na, ba tefasugi ba dödö horöra, ena''ö te''oloi''ö ira.', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 29, 'Andrö wa imane So''aya, Yehowa: Me no mifasugi ba dödö horömi, me no oroma wangerogömi [ya''odo], me no tobali to''ele horömi ba nilau-laumi andrö, fefu, — me itörö tödö ami, ba nira''u ami, börö da''ö.', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 30, 'Ba ya''ugö nibunu sebua horö, salaŵa Ndraono Gizeraeli, si no irugi baŵa ba ginötö wangasiwai horö:', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 31, 'Da''ö niŵa''ö Zo''aya Yehowa: Niheta zaembu, niheta dakula! Tenga si lö tebulö da''ö. Nibe''e yaŵa zi no ide-ide tou ba nihöndrögö tou zi no alaŵa yaŵa.', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 32, 'Tölu winaeta ubali''ö adudula; da''ö göi, ba si lö''ö sa''ae dania, irege so zokhö andrö, ba khönia ube''e.[9]', '["MozI 31:19","Faigi 4:2","MozI 49:10"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 33, 'Ba ya''ugö ono niha, ba ama''ele''ö, ömane: Da''ö niŵa''ö Zo''aya Yehowa, ba khö Ndraono Gamoni ba ba wango''ayara andrö, ba ömane: Si''öli, no mudöni zi''öli, no muhaogö ba wango''ö''ötö niha ba wa''atakile ba ba wehaga,', '["Yer 47:6"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 34, 'fatua lafaigi khöu walimosa ba fatua lalau khöu waetasa faya, ba wamaudugö ya''ia ba mbagi zi mate sebua horö, sirugi baŵa ba ginötö wangasiwai horö.', '["Yer 47:6"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 35, 'Fuli saembugö! Ba mbanua ba niwöwöi ya''ugö, ba danö mbörötamö uhuku ndra''ugö.[10]', '["Yer 47:6"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 36, 'ba uhawui ndra''ugö fönugu; alitö bakhu-bakhu dödögu u''ebua''ö khöu, ba ube''e ba danga niha si no timba gutu ndru''u ndra''ugö, niha sama''ua famakikomö.', '["Yer 47:6"]', NULL),
  (3476401, 'OT', 'Hezekieli', 21, 37, 'Ö galitö dania ndra''ugö, ba ba dalu danö aduwa ndromö; lö''ö sa''ae itörö tödö ndra''ugö; noa sa ya''odo, Yehowa, zanguma''ö!', '["Yer 47:6"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 2, 'Ba ya''ugö, ono niha, hadia same''e fotu ndra''ugö, same''e fotu ba mbanua zange''enge''e andrö? Ba fasugi ba dödöra zogoro ita andrö khöra, fefu,[1]', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 3, 'ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Alai mbanua andrö, same''e aduwa ndro niha ba khöra, ena''ö irugi baŵa andrö khöra, ba samazökhi khöra adu, ba wana''unöi ya''ira!', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 4, 'Ba ndro andrö khöu, niduwagömö, tohare khöu horö, ba ba nadu andrö khöu, nifazökhimö, ba no ta''unö ndra''ugö. Ba no ara ndra''ugö, no numalö ndröfiu. Andrö wa ube''e ni''o''aya niha baero ndra''ugö ba fama''iki ba danö misa, fefu.[2]', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 5, 'He sahatö, ba he saröu, ba la''igi''igi''ö ndra''ugö, ya''ugö si no ebua turia wa''ata''unö, si no fahöna fa''afakuyu.', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 6, 'Hiza, salaŵa Ndraono Gizeraeli andrö ba khöu, ba fatandro, ba dangania abe''e dödö zamösana, ba wamunumunu niha.', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 7, 'Ama ba ina, ba la''ositengagö ba khömi, ba si fatewu, ba lafalangögö, ba si lö ama, si lö ina, ba he lakha mbanua, ba lafakao, ba khömi andrö.', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 8, 'No lö ba dödömi ni''amoni''ö andrö khögu, ba he luo sabato andrö khögu, ba mi''o''aya.', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 9, 'So ba khömi niha samöbögö si lö sökhi, ba wamunu niha dania, ba ba hili ba khömi, ba la''aga''aga gö nadu, ba mohörö-hörö mbanuami.[3]', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 10, 'Sangeheta balu-balu zaila nama ami, ba sorudu ba ndra alawe si no ra''i-ra''iö ba wa''afökhö dalu.[4]', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 11, 'Si samösa, ba ihoröni ndronga nawönia, ba si samösa, ba ra''i-ra''iö numönönia ibe''e, wohoröni ya''ia, ba si samösa ba khömi, ba ihoröni dalifusönia, ono namania.[5]', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 12, 'Manga gana''a ami, ba wamunu niha; no mi''ebua''ö hare zugilömi ba no mifo''ono gana''ami, no mibe''e te''ala nawömi, no mifakao, ba no olifu ami ndra''odo, iŵa''ö So''aya, Yehowa.', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 13, 'Ba hiza, ba no ahöli-höli dödögu ba haremö andrö, nisöndramö, ba ba wamunumunu niha andrö ba khömi.[6]', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 14, 'Ba hadia, lö tebulö wa''abe''e dödömi andrö ba lö mamalö-malö wa''abe''e dangami, na luo usekhegö ami? No ya''odo, Yehowa, zanguma''ö, ba ufalua göi.[7]', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 15, 'Ba ufazawili ami ba niha baero, ba danö zotanö misa zumaewe ami ube''e, ba uheta khömi zi ra''ira''i''ö andrö,[8]', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 16, 'ba u''okhögö ami, ba zanehe niha baero, ena''ö aboto ba dödömi, wa no ya''o Yehowa.', '["Faigi 20:4; 24:9","RazII 21:16; MozV 28:37; Faigi 5:14","Faigi 18:6","MozIII 18:8,19","MozIII 18:9,15,20","Faigi 21:17","Faigi 17:24","Faigi 12:14"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 17, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Yes 1:22; Yer 6:28"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 18, 'He ono niha, no tobali akhozila khögu ma''uwu Gizeraeli andrö. Ya''ira fefu, ba no timba döla garamba ba simo mbanua ba si''öli ba simo itö, ba galitö famahele; no tobali tai wirö.[9]', '["Yes 1:22; Yer 6:28"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476402, 'OT', 'Hezekieli', 22, 19, 'Andrö wa imane So''aya, Yehowa: Me no ahori tobali akhozila ami, ba hiza, ba u''owuloi ami ba Yeruzalema bakha.', '["Yes 1:22; Yer 6:28"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 20, 'Si mane na la''orudugö bakha ba galitö wirö ba töla garamba ba si''öli ba simo itö ba simo mbanua, ba wangebua alitö khönia ba ba wolaugö ya''ia, si manö na u''orudugö ami dania ba wönugu andrö ba ba wa''abao dödögu, ba utuli''ö tou ami, ba alau ami ube''e.', '["Yes 1:22; Yer 6:28"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 21, 'Ba u''owuloi ami, ba u''ebua''ö khömi galitö bakhu-bakhu dödögu, ena''ö alau ami bakha ba da''ö.', '["Yes 1:22; Yer 6:28"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 22, 'Si mane na latunu wirö ba galitö, si manö dania wolaugö ya''ami bakha ba da''ö, ena''ö aboto ba dödömi, wa no uhawui ami fönugu, ya''odo andre, Yehowa.', '["Yes 1:22; Yer 6:28"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 23, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 24, 'He ono niha, ömane khönia: Tanö si lö teu ndra''ugö si lö basöbasö, me luo wönugu andrö.', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 25, 'Sama''ele''ö andrö ba khöra, ba no mamagölö; la''a niha, si mane singo sindröndröndröndrö, sondra''undra''u; gama-gama ba ana''a, ba larabu, ba fahöna ba danö lakha mbanua labe''e.[10]', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 26, 'Ere ba khöra, ba mo''olalöŵa ba nifakhoigu andrö ba la''o''aya ni''amoni''ö andrö khögu; ni''amoni''ö ba si lö mu''amoni''ö, ba lö lafaehusi, ba lö lafahaö zato, he wisa ba ni''amoni''ö ba he wisa ba zi lö mu''amoni''ö; ba luo sabato andrö khögu, ba lafakifu horöra, ba tobali ni''o''aya ndra''o ba khöra.[11]', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 27, 'Salaŵara andrö, ba no hulö nasu gatua sondra''undra''u niha, ba wame''e aduwa ndro ba ba wamunu niha, wangalui harera.[12]', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 28, 'Ba sama''ele''ö andrö khöra, ba labalugö da''ö, wangi''ila faya, ba lafa''ele''ö khöra walimosa, lamane: "Niŵa''ö Yehowa!" ba lö''ö sa hede-hede Yehowa.[13]', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 29, 'Niha ba danö, ba lafakao nawöra ba faraburabu; lafakao zide-ide ba si numana ba lafalangögö zi fatewu, lö börö.', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 30, 'Ba no u''alu''alui zamösa, same''e ba''a-ba''a ba ma samelegö nosonia ba danö andrö, khögu, fa böi ufakiko, ba lö nisöndragu.[14]', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476402, 'OT', 'Hezekieli', 22, 31, 'Ba no ulau khöra wönugu, no uhori ira alitö bakhu-bakhu dödögu andrö, no usulöni khöra mbua-buara andrö, iŵa''ö So''aya, Yehowa.[15]', '["Hos 6:9; Mat 23:14","Faigi 44:23","Mikh 3:11; Sef 3:3","Faigi 13:10","Sin 106:23","Faigi 9:10; 11:21; 16:43"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 1, 'Ba so niŵa''ö Yehowa khögu, imane: He ono niha!', '["Faigi 16:26; 20:8"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 2, 'So ndra alawe, dombua, ha sambua nina, sohorö-horö ba danö Miserayi,', '["Faigi 16:26; 20:8"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 3, 'me ono alawe ira na mohorö-horö ira. Lababaya zusura [ira matua] ba la''omösimösi wosura.[1]', '["Faigi 16:26; 20:8"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 4, 'Ohola döi zi a''a, ba Oholiba döi nakhinia. Ba no uhalö ira, ba mo''ono ira, ono matua ba ono alawe, ba Ohola döi Zamaria ba Oholiba döi Yeruzalema.', '["Faigi 16:26; 20:8"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 5, 'Ba orudu ba ndra matua bö''ö, salahigu, Gohola, ba aukhu ia ba zomasi ya''ia andrö, ba ndrawa Asiria, si möi khönia,[2]', '["RazII 15:19; 17:3; Faigi 16:28","Faigi 16:37"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 6, 'sobaru ungu sowu waru-waru, reside ba kumandru, oi ono matua omasiö, si fakudo.', '["RazII 15:19; 17:3; Faigi 16:28","Faigi 16:37"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 7, 'Ba ilulu ia khöra, ba wohorö andrö; oi ono matua Ndrawa Asiria, nitutuyu; ba ba khöra fefu, ba zi no aukhu ia, ba ra''i-ra''iö ia ibe''e, ba nadura andrö fefu.', '["RazII 15:19; 17:3; Faigi 16:28","Faigi 16:37"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 8, 'Ba fohorö-horönia andrö, si oroi ba danö Miserayi sa''ae, ba lö iböhöli; noa sa mohorö da''ö khönia, me ono alawe ia na, no lababaya wosunia ba no lalau khönia wohoröra andrö.', '["RazII 15:19; 17:3; Faigi 16:28","Faigi 16:37"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 9, 'Andrö wa no ube''e ia ba danga zomasi ya''ia, ba danga nono matua Ndrawa Asiria andrö, ba zi no aukhu ia.', '["RazII 15:19; 17:3; Faigi 16:28","Faigi 16:37"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 10, 'Ba laheta mbalu-balu zaila ia, ba la''oloi''ö nononia matua, fabaya ononia alawe, ba labunu ia si''öli, ba tobali amaedola ia ba ndra alawe bö''ö, ba lafatörö khönia huku.[3]', '["RazII 15:19; 17:3; Faigi 16:28","Faigi 16:37"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 11, 'Ba he ŵa''ae no i''ila da''ö akhinia Oholiba, ba abölö-bölö zui na wa''aukhunia, moroi khö ga''ania, ba tedou na wohorönia, moroi ba wohorö ga''ania mege.[4]', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 12, 'Aukhu ia ba nono matua Ndrawa Asiria andrö, ba reside ba ba gumandru, si möi khönia, si sökhi sibai nukha, ba si fakudo; oi ono matua omasiö.', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 13, 'Ba no u''ila wa ya''ia göi zana''unöi ya''ia; no fagölö-gölö mbua-bua zi darua andrö.', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 14, 'Ba ya''ia, ba itohugö wohorö-horönia andrö. Ba me i''ila wamaedo ndra matua, nisua ba mbagolö, famaedo Ndrawa Galedaia,', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 15, 'nilau se soyo, ba soböbö löwi-löwi, ba sanaembu, oi kumandra wamaigida, famaedo nono matua Mbabeli, banua Ndrawa Galedaia, 16— ba aukhu ia ba da''ö, me i''ila ira, ba ifatenge zinenge khöra ba danö Ndrawa Galedaia:', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 17, 'Ba möi si bakha khönia nono matua Mbabeli, ba wohorö khönia ba ra''i-ra''iö ia labe''e, ba wohoröra andrö, tobali si ra''i-ra''iö ia ba khöra andrö, ba aefa da''ö, ba fa''ero dödönia khöra.', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 18, 'Ba me no ba zoroma ba niha ilau wohorönia andrö, ba me iheta mbalu-balu zaila ia, ba fa''ero dödögu khönia, si mane mege, me u''erogö ga''ania.', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 19, 'Ba ya''ia, ba itohugö na wohorö-horönia andrö, itörö tödönia götö me ono alawe ia, me mohorö-horö ia ba danö Miserayi.', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 20, 'Ba aukhu ia ba zohorö khönia, si no famatua si mane ba galide ba fa''aduwa gula, si mane ba kudo.', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 21, 'Ba no öfuli ö''alu-alui wohorömö ba götö me ono alawe na ndra''ugö, me la''omösimösi wosumö Dawa Miserayi, ba me lababaya zusumö andrö, si bohou ebua.', '["Yer 3:11"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 22, 'Andrö wa imane So''aya, Yehowa, ya''ugö Oholiba: Hiza, ufarou udumö zomasi ya''ugö andrö mege, ya''ira andrö, ba zi no fa''ero dödöu, so ira moroi ba zi fasui fefu, ba wolau khöu, ube''e.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 23, 'Ono matua Mbabeli andrö ba Dawa Galedaia fefu, Fekodi ba Soa ba Koa, ono matua Ndrawa Asiria fefu, awöra, oi ono matua omasiö, reside ba kumandru, oi kumandra ba salaŵa, si fakudo.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 24, 'Ba so ira, ba wolau khöu, oya sibai gureta ba gaolo, ba ato sibai niha; mamaluse ba modange ba motetenaulu, wolau khöu, lafasui ndra''ugö, ba u''ombakha''ö khöra huhuo andrö, ena''ö lahuku ndra''ugö, dali huku ba khöra.[5]', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 25, 'Ba ulau khöu wönugu, ba lö ahakhö dödöra ndra''ugö, ikhumö ba talingamö, ba latataba, ba si tosai khöu, ba si mate ba mbawa zi''öli. Onou matua ba onou alawe, ba la''oloi''ö, ba si tosai khöu ba ö galitö dania.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 26, 'Ba laheta khöu nukhamö ba lahalö nayau.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 27, 'Ba u''etu''ö hokhamö ba fohorömö andrö, si oroi danö Miserayi, fa böi sa''ae öfaöga höröu khöra ba fa böi sa''ae itörö tödöu danö Miserayi.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 28, 'Imane sa So''aya, Yehowa: Hiza, ube''e ba danga zi fatiu dödöu ndra''ugö, ba danga zi no fa''ero dödöu andrö.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 29, 'Ba lafakao ndra''ugö ba ahori lahalö zi so khöu ba laröi tou ndra''ugö lö nukha, lö balu-balu, aheta mbalu-balu zaila ndra''ugö, saila zohorö-horö, ba oroma wohorö-horömö andrö, awö hokhamö.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 30, 'Börö wa lalau khöu da''ö, ba me no mohorö-horö ndra''ugö ba niha baero, me no ra''irai''ö ndra''ugö ba nadura andrö.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 31, 'No ötörö lala ga''au andrö; ba ufabadugö sa''ae khöu göi nösi mako andrö, nibadunia.[6]', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 32, 'Da''ö niŵa''ö Zo''aya, Yehowa: Ösi mako andrö, nibe''e khö ga''au mege, ba öbadu göi, ösi mako sabakha ba sebua, sebua sibai ösi, ba tobali fama''iki niha ndra''ugö ba borö wango''aya,[7]', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 33, 'ba mabu sibai ndra''ugö ba abu sibai dödöu, no mako ba wehokha mbu ba ba wa''atobali dödö, mako nibe''e khö ga''au Samaria mege.', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 34, 'Ba öbadu nösi, öhori wangohofo ya''ia, ba öfelafelai gamotola ba ökha''akha''ai zusumö, me no ya''o zanguma''ö, iŵa''ö So''aya, Yehowa:', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 35, 'Andrö wa imane So''aya, Yehowa: Me no olifu''ö ndra''o ba me no ö''erogödo, ba ölu''i göi hokhamö, awö wohorö-horömö andrö.[8]', '["RazI 10:17","Sin 75:9","Yes 51:17; Yer 25:15; 49:12; Obad a. 16","RazI 14:9; Yez. 2:32; 13:23; Faigi 22:12"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 36, 'Ba imane khögu Yehowa: He ono niha, na ö''otu''ö ndra Ohola Oholiba, ba fasugi ba dödöra zogoro ita andrö khöra.[9]', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 37, 'Noa sa mohorö ira ba no togule ba dangara ndro, ba no ba nadu andrö khöra mohorö-horö ira, no lafatörö ba galitö nono matua andrö, si no tumbu khöra khögu, no labe''e ö nadu.[10]', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 38, 'Ba da''ö na göi nilaura khögu: No lata''unöi ni''amoni''ö andrö khögu, me luo da''ö, ba no la''o''aya luo sabato andrö khögu.[11]', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 39, 'Ba na labunu ö nadu nonora matua, ba möi ira ba ni''amoni''ö andrö khögu, na luo da''ö, ba wango''aya ya''ia, ba hiza, ba si manö göi wolaura bakha ba gosali khögu!', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 40, 'Ba lafakaoni''ö na''i göi niha moroi ba zaröu, ba ha si''aikö tohare khöra zinenge, ba so ira, ba mondri ndra''ugö ba öhaogö röngöröngöu ba öfake nayamö.', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 41, 'Ba mudadao ndra''ugö ba gaso si sökhi sibai, ba meza fönau, si no muhaogö, ba öbe''e yaŵa gumöyö andrö khögu ba fanikha khögu.[12]', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 42, 'Ba yomo ba mbanua, ba fagua-gua niha, fagua-guasa si lö fa''aila. Ba awö niha si lö töi, ba lafakaoni''ö zamadu-madu tuo ba danö si mate, da''ö zame''e aya ba dangara ba saembu si sökhi sibai ba högö.', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 43, 'Ba umane: Mohorö-horö na zi no aleu, lö iböhöli wohorönia, ilau manö.', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 44, 'Ba möi ira si bakha khönia, si mane na möi ba zohorö; möi ira si bakha khö Gohola ba khö Goholiba, ira alawe sebua hokha.', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 45, 'Ba niha satulö zamatörö fotu khönia dania, fotu ba zohorö ba fotu ba zange''e, noa sa sohorö-horö ira ba no togule ba dangara ndro.[13]', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 46, 'Imane sa So''aya, Yehowa: Nilau falukhata khöra, nibe''e nifakao ba nirabu si so khöra ira.[14]', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 47, 'Ba ndramutebu kara ira sato ba ndra mu''ö''ötö ira si''ölira. Nibunu tou nonora matua, fabaya onora alawe, ba omora, ba nitunu.', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 48, 'Ba ufadöhö wohorö andrö ba zi manö, ena''ö labe''e nitegu ira ira alawe [bö''ö] fefu, fa böi mohorö-horö ira, si mane ya''ira andrö.', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476403, 'OT', 'Hezekieli', 23, 49, 'Ba labe''e ba hulumi wohorömi andrö, ba olalöŵami ba nadumi andrö, ba milu''i, ena''ö aboto ba dödömi, wa no ya''odo Zo''aya, Yehowa.', '["Faigi 20:4","Faigi 16:20","RazII 21:4","Amaed 7:17","Faigi 16:38","Faigi 16:40"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 1, 'Ba ndröfi si siŵa, ba zi mewulu ba mbaŵa si fulu, ba humede khögu Yehowa, imane:[1]', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 2, 'He ono niha, tanö ba zura döi mbaŵa da''e, töi mbaŵa da''e sibai, ma''ökhö! Ma''ökho andre ilau ba Yeruzalema razo Mbabeli.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 3, 'Andrö wa ölau gamaedola ba niha sabe''e tandro andrö, ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Fedadao bawu mbowoa, fedadao ba lau göi nidanö bakha.[2]', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 4, 'Be''e bakha ndriwo andrö, ösinia, hadia ia zi sökhi, osu ba ta''io, fo''ösi si so töla, ni tutuyu.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 5, 'Biri-biri nitutuyu halö, ba fa''anö göi geu barönia; rino ndriwo andrö bakha: mo''otu sa''ae bakha zi so töla andrö.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 6, 'Andrö wa imane So''aya, Yehowa: Alai ndra''o ndra''ugö, ya''ugö banua zange''e, bowoa andrö, si no molemba howu, ba si tebai aheta sa''ae howu andrö! no lazara-zara wangai ösi, ba lö mulau dahö-dahö.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 7, 'Me no so na bakha ba mbanua ndro andrö niduwagöra. No ba dete gara si lö tanö lalau, tenga ba danö laduwagö, ena''ö ibadu tanö.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 8, 'Ba wamatörö fönu khöra, ba ena''ö u''ila ulau mbalö, andrö wa ba dete gara si lö tanö tohare ndro andrö niduwagöra, ube''e, fa böi ibadu tanö.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 9, 'Andrö wa imane So''aya, Yehowa: Alai ndra''o ndra''ugö, ya''ugö banua zange''enge''e! Hiza, u''ebua''ö mbaho geu andrö![3]', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 10, 'Mihöna geu, mi''ebua''ö galitö, mi''asosoi ndriwo andrö, yamo''otu nidanönia, ena''ö akhozi döla andrö.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 11, 'Ba aefa da''ö, ba be''e bawu mbowoa, lö ösi, ena''ö aukhu ia ba ena''ö oyo dölania, fa adudu bakha zi ta''unönia ba ena''ö ahori howu.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 12, 'Ba no zaya-zaya gölö ibe''e, ba lö aheta khönia howu sawe''e-we''e andrö, howu saböu andrö,', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 13, 'ba wa''ata''unömö, ba wohorö-horö andrö. Me no utandraigö wangehao ya''ugö ba me no tebai aheta zi ta''unö andrö khöu, ba alakha lö''ö sa''ae aheta, irege no ufadöhö wönugu, ba khömö andrö.', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 14, 'No ya''o, Yehowa, zanguma''ö; itörö dania ba ufalua: ma''ifu lö uwuwu, lö uhakhösi tödö ami, ba lö mangesa dödögu. Bua-buamö ba folaumö andrö labe''e dali wamatörö huku khöu, iŵa''ö So''aya, Yehowa.[4]', '["Yer 52:4","Yer 1:13; Faigi 11:3","Faigi 22:2; Nakh 3:1; Hab 2:12","Faigi 5:11"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 15, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 16, 'He ono niha, uheta khöu gomasiö höröu andrö, ba wökhö uheta khöu. Ba böi angarö-ngarö ba böi e''e; böi mowöi daŵa höröu.', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 17, 'Angarö-ngarö lö li, böi e''esi: anaembu ba amadagahe: böi balugö mbu mbawamö ba böi a kue ba wa''abu dödö![5]', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 18, 'Ba fahuhuo ndra''o ba niha, si hulö wongi; ba tanö owi, ba mate wo''omogu, ba mahemolu ö, si hulö wongi, ba u''o''ö niŵa''ö khögu.', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 19, 'Ba lamane khögu niha: Hadia, lö öbotokhi ba dödöma, hadia geluahania, wa ömanö?', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 20, 'Ba umane khöra: No muhede khögu Yehowa,', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 21, 'no imane: Ömane ba ma''uwu Gizeraeli: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ube''e ba zalakha ni''amoni''ö andrö khögu, nibe''emi börö wayaŵasami, omasiö hörömi andrö, fa''omasi dödömi; ba onomi matua ba onomi alawe, niröimi, ba si mate ba mbawa zi''öli dania.', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 22, 'Ba ba da''ö dania mi''o''ö nilaugu andre: lö mibalugö mbu mbawami ba lö mi''a kue ba wa''abu dödö.', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 23, 'Lö mibulö''ö zaembu ba högömi, ba he badagahe ba gahemi, lö mangarö-ngarö ami ba lö sege-ege, sariri manö ami, ba horömi andrö, ba faoma khö naŵomi mangarö-ngarö ami.[6]', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 24, 'Ba tobali amaedola khömi Hezekieli andre; mi''o''ö sibai dania nilaunia andre, na itörö dania, ena''ö aboto ba dödömi, wa no ya''odo Yehowa.[7]', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 25, 'Ba ya''ugö, ono niha, ba hiza, na luo uheta khöra nidöna-dönara andrö, omasiöra andrö si sökhi sibai, awö zomasi dödöra, onora matua ba onora alawe,', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 26, 'na luo da''ö, ba so zoloi, si möi khöu, ba wanuriagö ya''ia.[8]', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476404, 'OT', 'Hezekieli', 24, 27, 'Na luo da''ö, ba teboka mbawau, endronga ami soloi andrö, ba humede ndra''ugö, tenga sa''ae si lö hede ndra''ugö, ba amaedola ndra''ugö khöra, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '["Yer 16:7","MozIII 26:39; Faigi 4:17","Faigi 12:6","Faigi 33:21"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 1, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Yer 49:1 b.t.","Faigi 35:15"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 2, 'He ono niha, otahögö Ndraono Gamoni ba ama''ele''ö nitandrösaigö khöra.[1]', '["Yer 49:1 b.t.","Faigi 35:15"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 3, 'ömane ba Ndraono Gamoni andrö: Mifondrondrongo li Zo''aya, Yehowa! Da''ö niŵa''ö Zo''aya Yehowa: Me no faha! ami ba ni''amoni''ö andrö khögu, me no mu''o''aya ia, ba ba danö Ndraono Gizeraeli, me no mubali''ö tanö si mate ia, ba ba ma''uwu Yuda, me no mu''oloi''ö ira,', '["Yer 49:1 b.t.","Faigi 35:15"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 4, 'ba hiza, ba ube''e okhöta niha tanö ba gatumbukha luo ami, ena''ö lalau hatira ba khömi ba ena''ö lataru''ö nahiara. Ya''ira zi manga bua danö khömi ba ya''ira zamadu susu zaŵi khömi.', '["Yer 49:1 b.t.","Faigi 35:15"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 5, 'Ba ubali''ö nikubaloi gondra Raba andrö, ba tanö Ndraono Gamoni, ba ubali''ö föröma mbiri-biri, ena''ö aboto ba dödömi, wa no ya''odo Yehowa.', '["Yer 49:1 b.t.","Faigi 35:15"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 6, 'Imane sa So''aya, Yehowa: Me no molau tatawo ami ba me no mibörö danö ba me no mi''ositengagö Ndraono Gizeraeli ba me no a''oi so wa''omuso dödömi ba zi göna ira,[2]', '["Yer 49:1 b.t.","Faigi 35:15"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 7, 'ba hiza, ba u''oro''ö dangagu yaŵami ba ube''e ondra''ua niha baero ami ba uhori ami bakha ba hunö niha bö''ö, taya ami ba danö ube''e; ufakiko ami, ena''ö aboto ba dödömi, wa no ya''odo Yehowa.', '["Yer 49:1 b.t.","Faigi 35:15"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 8, 'Da''ö niŵa''ö Zo''aya, Yehowa: Me no lamane Iraono Moabi ba banua Ze''ira: No tobali si mane niha bö''ö fefu ma''uwu Yuda![3]', '["Yer 48:1 b.t."]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 9, 'ba hiza, ba ulahoi zanaere tanö andrö, ba Ndraono Moabi, fa lö banua sa''ae, banua andrö mege, ba zi fasui: fa''amoadu danö andrö, Beti Yesimoto ba Ba''ali Meono ba Kiriata''i.', '["Yer 48:1 b.t."]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 10, 'Ube''e okhöta niha tanö ba gatumbukha luo, awö danö Ndraono Gamoni, ena''ö lö''ö sa''ae itörö tödö niha bö''ö Ndraono Gamoni andrö.', '["Yer 48:1 b.t."]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 11, 'Ba ba Ndraono Moabi, ba ufatörö huku, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '["Yer 48:1 b.t."]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 12, 'Da''ö niŵa''ö Zo''aya, Yehowa: Me no molau balö ba ma''uwu Yuda Ndraono Gedomo, ba me no ebua horö, me no lalau mbalöra khöra,[4]', '["Sin 137:7; Amos 1:11","Yes 11:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476405, 'OT', 'Hezekieli', 25, 13, 'andrö wa imane So''aya, Yehowa: U''oro''ö sa''ae dangagu yaŵa Ndraono Gedomo, ba uhori ba danö niha, fabaya urifö, ba ubali''ö tanö si mate danö; i''otarai Demana, numalö ba Dedano, ba mate-mate ira ba mbawa zi''öli.', '["Sin 137:7; Amos 1:11","Yes 11:14"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 14, 'Ba folaugu balögu ba Ndraono Gedomo, ba ube''e ba danga mbanuagu Iraono Gizeraeli, ena''ö fönugu ba fa''abao dödögu labe''e dali wolau ba Ndraono Gedomo, ba ena''ö la''ila wolaugu balögu andrö, iŵa''ö So''aya, Yehowa.[5]', '["Sin 137:7; Amos 1:11","Yes 11:14"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 15, 'Da''ö niŵa''ö Zo''aya, Yehowa: Me no molau balö Ndrawa Wilisiti, me no la''ositengagö ami ba me no moroi si''aikö ba dödöra lalau mbalöra khömi, me no famakiko lafa''ua, ba watiusa andrö si lö aetu,[6]', '["Yer 47:1 b.t. Sef 2:5"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 16, 'andrö wa imane So''aya, Yehowa: Hiza, u''oro''ö dangagu yaŵa Ndrawa Wilisiti, ba uhori Ndrawa Gereta andrö, ba ufakiko zi tosai sihene asi.', '["Yer 47:1 b.t. Sef 2:5"]', NULL),
  (3476405, 'OT', 'Hezekieli', 25, 17, 'Folau balö sabölö-bölö ufatörö khöra, fotu ba wönu, ena''ö aboto ba dödöra, wa no ya''odo Yehowa, na ulau mbalögu khöra.', '["Yer 47:1 b.t. Sef 2:5"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 1, 'Ba ba ndröfi si felezara, me tesa''a, ba so niŵa''ö Yehowa khögu,[1]', '["Faigi göi Yes 23; Amos 1:9; Yoel 3:4 b.t."]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 2, 'imane:', '["Faigi göi Yes 23; Amos 1:9; Yoel 3:4 b.t."]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 3, 'ba imane So''aya, Yehowa: Hiza, ulau khöu, ya''ugö Tiro, oya soi u''ohe udumö niha, timba ndrulu ba nasi, saboto baene.', '[]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 4, 'Ba ladudugö dania göli Diro, öli kara, ba laso''agö malige andrö khöra. Ba ubözini khönia guli danö, ubali''ö kara si lö tanö yaŵa.', '[]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 5, 'Naha wolokhoi kiri dania ia, ba dalu nasi bakha, me no ya''o zanguma''ö, iŵa''ö So''aya, Yehowa, ba ahulua soi bö''ö dania ia.', '[]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 6, 'Ba banua halama soya khöra, sihene asi, ba si mate ba mbawa zi''öli dania, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '[]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 7, 'Imane sa So''aya, Yehowa: Hiza ufatenge sanuwö Tiro Nebukanesa, razo Mbabeli, moroi yöu, fondrege razo andrö, solohe kudo ba hureta ba si fakudo, awö niha sato sibai.', '["Yes 24:8"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 8, 'Da''ö zamunu tou si''öli mbanua halama soya khömi, sihene asi, ba ilau malige zanuwö khömi ba ifako''o''ö fari khömi ba ifafazökhi''ö mba''a-ba''a khöra.', '["Yes 24:8"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 9, 'Ba la''olobigö ba göli kara khömi wamoto andrö ba larasa maligemi si''öli andrö khöra.', '["Yes 24:8"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 10, 'Ba tehawu ami gawu-gawu ba wa''oya kudo khöra moroi sa; ba ba werara zi fakudo ba gaolo ba kureta, ba humisi göli mbanua khömi, na latörö mbawa göli khömi, si mane na atu''a ba mbanua zanuwö.', '["Yes 24:8"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 11, 'Afufu newalimö fefu [ya''ugö Tiro] labe''e ahe kudo khöra, ba ösimö, ba labunu tou si''öli, ba adudu tou gehomo sesolo andrö khöu.', '["Yes 24:8"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 12, 'Ba larabu gana''amö, ba faniaga andrö ba khöu, ba lahalö, ba ladudugö gölimö, öli kara andrö, ba omo, sebua balazo mege ba wolau, ba lafufu, ba karania ba eunia, adudula, ba latibo''ö ba nasi.', '["Yes 24:8"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 13, 'U''etu''ö li wanunö ba khöu, ba he li mbiola khöu, ba lö terongo sa''ae.[2]', '["Yes 24:8"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 14, 'Ba ubali''ö kara si lö tanö yaŵa ndra''ugö: tobali naha wolokhoi kiri ndra''ugö; lö''ö sa''ae lafuli lataru''ö ndra''ugö, me no ya''o, Yehowa, zanguma''ö, iŵa''ö So''aya, Yehowa.', '["Yes 24:8"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 15, 'Da''ö niŵa''ö Zo''aya, Yehowa, nitandrösaigö ba Diro andrö: Hadia, lö muheu hulo ba nasi ba werara wa''adudumö ba ba wangarö-ngarö nitaru''ö si''öli, na möi famunu ba khömö zi''öli andrö?', '["Fam 18:9"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 16, 'Ba möi tou zalaŵa ba mbewe nasi fefu, laröi dadaomara, laheta mbarura, baru zalaŵa, awö nukhara nigili sola''a-la''a. Ba la''onukha wanizi-nizi, ba tou ba danö mudadao ira; lö mamalö-malö wanizi ba no tobali dödöra ba khömö andrö.', '["Fam 18:9"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 17, 'Ba la''e''esi ndra''ugö ba lamane khöu: "Ha lö afufu ndra''ugö, ha lö ataya ndra''ugö ba nasi, ya''ugö banua nisuno sibai mege, si no abölö ba nasi, ya''ia ba ösinia, same''e manizi-nizi khönia dozi si so ba ngai![3]', '["Fam 18:9"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 18, 'Ba iada''e, ba humeu hulo, me luo wa''adudumö, ba si tobali tödö hulo ba nasi, ba wozumö andrö.', '["Fam 18:9"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 19, 'Imane sa So''aya, Yehowa: Na ubali''ö banua si no adudu ndra''ugö, si mane banua bö''ö andrö, si lö niha sa''ae, na ufatörö khöu goloro,', '["Fam 18:9"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 20, 'ena''ö anönö''ö asi, ba utuli''ö si tou ndra''ugö, awö zi no möi si tou ba goho-koho, ba niha ba götö föna, ba ba mbanua tou u''asiwai nahiamö, timba gadudula si no ara sibai, ba zi no möi ba goho-koho, fa böi sa''ae la''iagö ndra''ugö niha, ba fa böi sa''ae monaha ndra''ugö ba danö niha sauri.', '["Fam 18:9"]', NULL),
  (3476406, 'OT', 'Hezekieli', 26, 21, 'I''ogomuzaö adudu ndra''ugö ube''e, ba lö''ö sa''ae ya''ugö. La''alui dania ndra''ugö, ba irugi zi lö aetu, ba lö lasöndra''ö, iŵa''ö So''aya, Yehowa.', '["Fam 18:9"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 1, 'Ba so niŵa''ö Yehowa khögu,', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 2, 'imane: Ba ya''ugö ono niha, ö''e''esi Diro andrö,', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 3, 'ömane khönia: Si so ba mbewe nasi, ba mbewe labua, saniaga ba niha baero, ba zihene asi misa: Da''ö niŵa''ö Zo''aya, Yehowa: Ya''ugö Tiro, ba no ömane dödöu: "No fondrege zi sökhi ndra''o!"[1]', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 4, 'No ba dalu nasi so nahiamö; no maulu wa''asökhimö labe''e sanaru''ö ya''ugö.', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 5, 'No senobari moroi ba Zeniri labe''e fafamö fefu, ba eresi moroi ba hili Libano lahalö, ba wamotöla loyo ya''ugö.', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 6, 'Ba tali gae moroi ba Mbazana labe''e sola, ba bagolömö ba tetemö ba simalambuo, moroi ba hulo Ndrawa Giti, nifosinga ifö guaza.[2]', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 7, 'Ba tarafali nigili sola''a-la''a, moroi ba danö Miserayi, öbologö mandreramö, ba ungu sowu waru-waru ba soyo, moroi ba mbewe nasi ba Gelisa mba''a-ba''a zino khöu.', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 8, 'Banua Zidona ba banua Garawada öhalö sanola; ba sabölö onekhe si so ba khöu, ya''ugö Tiro, ba no möi sangamuri.', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 9, 'Satua mbanua Gebala ba tuka khöra zi möi sanga''azökhi si böla ba khöu; owo ba nasi fefu, awö nono nowo, ba no so ba khöu.[3]', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 10, 'Dawa Weresia ba Dawa Ludi ba Dawa Wuti, ba no möi saradadu khöu ba wasuwöta; baluse ba tetenaulu, ba no lasaitagö ba khömö andrö, nönö-nönö lakhömiu.', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 11, 'Banua Garawada andrö ba sabölö andrö khöu [fefu], ba no so ba gölimö, fasui, ba sabölö zi so yaŵa ba maligemö. Balusera, ba no lasaitagö ba gölimö fasui; lafo''ahonoa wa''asökhimö.', '["Faigi 28:12","Yes 23:1","RazI 5:18"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 12, 'Tarisi zaniagö khöu, ba wa''oya ngawalö waniaga. Firö ba si''öli ba simo mbanua ba simo itö la''ohe ba kade khöu.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 13, 'Yawano ba Tubalo ba Mesekhi zaniaga khöu; sawuyu ba fakake töla garamba la''ohe khöu, faniaga.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 14, 'Ma''uwu Dogarima zolohe ba kade khöu kudo gureta ba kudo ba wakudosa ba kalide kudo.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 15, 'Dawa Dedano zaniaga khöu. No möi barö mbawau ba waniaga zihene asi misa; ifö guaza ba eu zati labe''e beo khöu.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 16, 'Dawa Garamo zaniaga khöu, ba wa''oya ngawalö nekhe-nekhe danga khöra; feremata zumurudi ba ungu ba nukha nigili sola''a-la''a ba tarafali ba meredia ba yasia la''ohe ba kade khöu,', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 17, 'Mado Yuda ba iraono Gizeraeli zaniaga khöu. Gandru moroi ba Miniti ba kue sami ba ŵe ŵani ba fanikha ba fanikha samohua la''ohe khöu faniaga.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 18, 'Damaseko zowöliwöli khöu, ba wa''oya ngawalö nekhe-nekhe danga khöu, ba wa''afahöna waniaga, agu moroi ba Helebono ba bu mbiri-biri, moroi ba Zakhara, si takile fa''afusi, la''ohe.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 19, 'Wedano ba Yawano ba Usala zolohe faniaga ba kade khöu; fakake si''öli ba kuli mani ba deringu la''ohe khöu faniaga.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 20, 'Dedano zaniaga khöu, dane-dane zela kudo, ba wakudosa.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 21, 'Dawa Ara ba salaŵa Gedara fefu, ba no so barö mbawau saniaga: ono mbiri-biri ba biri-biri si matua ba nambi si matua la''ohe: da''ö waniagara khöu.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 22, 'Sikoli Zaba ba sikoli Raema zaniaga khöu. Fondrege zi sökhi rembaremba, awö ngawalö weremata ba ana''a la''ohe ba kade khöu.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 23, 'Harana ba Kane ba Edena, sikoli Zeba ba sikoli Dawa Asiria ba sikoli Gilimada zaniaga khöu.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 24, 'Faniagara ba kade khöu, ba baru luo ba baru sebua ungu sowu waru-waru ba nukha nigili sola''a-la''a ba ambala sokhoikhoi ba sinali ni''otaŵi gatölu ba sinali nitali.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 25, 'Owo Darisi zolohe faniaga khöu, ba tobali sebua ana''a ndra''ugö ba sebua lakhömi, ba dalu nasi.', '[]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 26, 'Misi tou ba nasi la''ohe ndra''ugö sanola owou; — ba irasa ndra''ugö angi timu, ba dalu nasi.', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 27, 'Ana''amö ba faniagamö ba ösi lafo ba ono nowo khöu ba sangamuri, sanga''azökhi si böla khöu, ba samawamawa faniaga andrö khöu ba saradadumö, fefu, si so yomo ba mbanua khöu, fabaya niha sato fefu khöu, ba sahöndrö ba dalu nasi dania, na luo wa''adudumö.', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 28, 'Ba ba we''ira-ira zangamuri andrö khöu, ba humisi nowo soya.', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 29, 'Ba dozi sangamuri, ba laröi nowora; ono nowo ba dozi sangamuri, ba nasi, ba möi yaŵa ba danö.', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 30, 'Ba la''e''esi ndra''ugö ba mu''ira-ira ba lalau gawu-gawu ba högöra, ba lahawui ira awu.[4]', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 31, 'Latöwö mbura, börö ndra''ugö, ba la''onukha nukha ba wa''abu dödö ba mege-ege ira ba khömö andrö, abu sibai dödöra, afökhö sibai khöra.', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 32, 'Ba ba wa''abu dödöra andrö, ba mangarö-ngarö ira ba khömö andrö, ba la''e''esi ndra''ugö lamane. Ha niha zi no si mane Tiro andrö, si lö nini-nini sa''ae bakha ba dalu nasi!', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 33, 'Me möi yaŵa moroi ba nasi waniagamö andrö, ba no oya soi zabuso öbe''e; ba wa''ebua gana''amö ba ba wa''oya waniagamö, ba no öfo''ana''a razo ba guli danö.', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 34, 'Ba iya''e, ba no aboto ndra''ugö, no aheta''ö ba nasi yaŵa; no ahöndrö si tou waniagamö andrö, fabaya niha sato fefu, ösiu.', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 35, 'Dozi si hene asi, ba tobali dödö ba khömö andrö, ba humokha mbu zalaŵara, mangerau mbawa.', '["Fam 18:11"]', NULL),
  (3476407, 'OT', 'Hezekieli', 27, 36, 'Saniaga andrö ba niha bö''ö, ba la''o''aya ndra''ugö; no i''ogomuzaö adudu ndra''ugö, ba lö''ö manö ya''ugö sa''ae.', '["Fam 18:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 1, 'Ba so niŵa''ö Yehowa khögu,', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 2, 'imane: He ono niha, ömane khö razo Diro andrö: Da''ö niŵa''ö Zo''aya, Yehowa: Me no fayaŵa dödöu, me no ömane: "Lowalangi ndra''odo, nahia Lowalangi nahiagu ba dalu nasi bakha!" ba no niha ndra''ugö, ba tenga Lowalangi, ba me öŵa''ö zui tödöu, Lowalangi ndra''ugö, —[1]', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 3, 'hiza, no atua-tua ndra''ugö, moroi khö Danieli, lö hadia ia si tobini, si lö ösöndra.[2]', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 4, 'Ba wa''atua-tuamö andrö ba ba wa''aboto ba dödöu, ba ösöndra gana''a ba öhöna gana''a ba firö, barö dawöla.', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 5, 'Ba wa''afahöna wa''atua-tuamö andrö ba ba waniagamö, ba ödou''ö wa''ebua gana''au, ba fayaŵa dödöu, börö wa''ebua gana''amö andrö.', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 6, 'Andrö wa imane So''aya, Yehowa: Me öŵa''ö tödöu, Lowalangi ndra''ugö, ba hiza,', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 7, 'ba ufatörö khöu niha bö''ö, niha si lö fa''ahakhö dödö, ba lasöbi zi''ölira ba wa''atua-tuamö andrö, ba la''o''aya lakhömiu andrö.[3]', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 8, 'Ba gohokoho si tou latuli''ö ndra''ugö, ba fa''amate nibunu wa''amateu, ba dalu nasi bakha.', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 9, 'Ba hadia, öŵa''ö na göi dania: "Lowalangi ndra''o!" föna zamunu ya''ugö, me no niha ndra''ugö, ba tenga Lowalangi, ba danga zi ange''eli ya''ugö?', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 10, 'Fa''amate zi lö muboto wa''amateu dania, ba danga niha bö''ö, me no ya''o zanguma''ö, iŵa''ö So''aya, Yehowa.', '["Yes 14:13; 31:3","Dan 1:20","Faigi 30:11"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 11, 'Ba so niŵa''ö Yehowa khögu,', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 12, 'imane: He ono niha e''esi razo Diro andrö, ömane khönia: Da''ö niŵa''ö Zo''aya, Yehowa: No tandro ba wa''amo''ahonoa ndra''ugö, mege, no fahöna wa''atua-tua ba no mo''ahonoa wa''asökhi.', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 13, 'No ba Gedena, ba kabu Lowalangi andrö, so ndra''ugö; balu-balumö ngawalö weremata, aki ba sabaradi ba ita ba firusa ba una ba yasia ba nila ba sumurudi ba yakudi; ba ana''a waritia ba surune khöu; me luo tewöwöi ndra''ugö tefazökhi.[4]', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 14, 'No Kerubi ba''a-ba''a ufataro ndra''ugö; ba hili Lowalangi andrö ni''amoni''ö so''ö; ba gotalua gara, si no timba galitö, mowaö-waö ndra''ugö.[5]', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 15, 'Si lö sinegu ndra''ugö ba mbua-buamö andrö, i''otarai luo me tewöwöi ndra''ugö, irege tesöndra dania golalöŵa ba khöu.', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 16, 'Ba waniagamö andrö, si no abölö sibai, ba mo''ösi ndra''ugö si lö sökhi, mosala ndra''ugö; ba no ube''e ba zalakha ndra''ugö, no uheta''ö ba hili Lowalangi andrö, no ufakiko''ö, ya''ugö Kerubi ba''a-ba''a, ba ba gotalua gara andrö, si no timba galitö, ba no uheta''ö.', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 17, 'No fayaŵa dödöu, börö wa''asökhimö andrö, ba taya wa''atua-tuamö andrö öbe''e, ba lakhömimö andrö. Ba danö tou no utibo''ö ndra''ugö, no ube''e ba danga razo bö''ö ndra''ugö, ena''ö wa''omasira wamaigi-maigi ya''ugö.', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 18, 'Ba wa''afahöna golalöŵamö andrö ba ba walimosa andrö ba waniagamö, ba öbe''e ba zalakha ni''amoni''ö andrö khöu. Ba alua galitö ba khömö ube''e, ba no i''a''ö, ba no ubali''ö awu ndra''ugö ba danö tou, ba zanehe zamaigi ya''ugö, fefu.', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 19, 'Dozi si no fa''ila li khöu, ba niha baero, ba no tobali dödö, ba khömö andrö; no i''ogomuzaö tekiko ndra''ugö, ba lö''ö manö ya''ugö sa''ae.[6]', '["MozI 2:8; MozII 28:17–20","MozII 25:20; Yes 6:6","Faigi 26:16"]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 20, 'Ba so niŵa''ö Yehowa khögu,', '[]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 21, 'imane: He ono niha, otahögö Zidona, ba ama''ele''ö nitandrösaigö khöra,', '[]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 22, 'ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ulau khöu, ya''ugö Sidona, ba molakhömi ndra''o ba khömö andrö, ube''e, ena''ö aboto ba dödöra, wa no ya''odo Yehowa, na ufatörö khöra huku ba na u''oroma''ö khöra, wa no ni''amoni''ö ndra''odo.', '[]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 23, 'Ba ufatörö khöra wökhö waba, ba fange''e ba newali khöra, ba mate tou nibunu si''öli, ba mbanua bakha, tefasui si''öli ira, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '[]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 24, 'Ba ba ma''uwu Gizeraeli, ba lö''ö sa''ae doi famakao ba lö''ö sa''ae zuzumö safökhö, ba niha si tefasui ya''ira, fefu, si lö ba dödö ya''ira, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '[]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 25, 'Da''ö niŵa''ö Zo''aya, Yehowa: Na u''ozaragö dania ma''uwu Gizeraeli, ba niha baero andrö, ba nifazaewe ya''ira, ba u''oroma''ö ba khöra, wa no ni''amoni''ö ndra''odo, ba zanehe niha baero, ba ba danöra dania so ira, ba danö nibe''egu khö genonigu Yakobo.[7]', '["Yes 65:21 b.t."]', NULL),
  (3476408, 'OT', 'Hezekieli', 28, 26, 'Ba mowanua ira ba da''ö, lö hadia ia khöra, molau omo ira ba lafazökhi kabu nagu, ba lö hadia ia khöra, na ufatörö huku ba niha fefu, si lö ba dödö ya''ira mege, ba zi tefasui ya''ira mege, ena''ö aboto ba dödöra, wa no ya''odo Yehowa, Lowalangira.', '["Yes 65:21 b.t."]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 1, 'Ba ba ndröfi si fulu, ba zi mewelendrua ba mbaŵa si fulu, ba so niŵa''ö Yehowa khögu,[1] imane:', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 2, 'He ono niha, otahögu Wara''o andrö, razo Miserayi, ba ama''ele''ö nitandrösaigö khönia ba ba danö Miserayi, ma''asagörö.', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 3, 'Hede, ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ulau khöu, ya''ugö Fara''o, razo Miserayi bu''aya sebua, si so ba dalu nidanö andrö khönia, sanguma''ö: Khögu Nilo, no ya''o zamazökhi![2]', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 4, 'Ulau sa''ae gai ba zimbimö, ba falemba ba huna-hunamö gi''a, ba nidanö andrö khöu, ube''e, ba udöni''ö yaŵa, moroi ba dalu nidanö andrö khöu, fabaya i''a fefu, ba nidanö khöu, si no falemba ba huna-hunamö.', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 5, 'Ba utibo''ö ndra''ugö ba danö si mate, ya''ugö ba i''a andrö fefu, ba nidanö andrö khöu; ba mbenua aekhu tou ndra''ugö, ba lö''ö sa''ae lahalö''ö ba lö lako''o ba danö ndra''ugö: ö gutu ndru''u ba ö wofo ba dalu mbanua ube''e ndra''ugö.', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 6, 'Ba ya aboto ba dödö Ndrawa Miserayi fefu, wa no ya''odo Yehowa. Me no si''o sukhu ndra''ugö ba ma''uwu Gizeraeli —[3]', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 7, 'na latuyu ndra''ugö, ba afatö''ö, ba oi mesokho dangara öbe''e, ba na labe''e tendrotendrora ndra''ugö, ba tefatö''ö, ba oi mangiwa zolara öbe''e! —', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 8, 'Andrö wa imane So''aya, Yehowa: Hiza, ufatörö khöu zi''öli: ba uhori ba khömö niha, fabaya urifö.', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 9, 'Ba tanö si mate ba si lö niha-niha dania danö Miserayi, ena''ö aboto ba dödöra, wa no ya''odo Yehowa. Me no öŵa''ö: "Khögu Nilo, no ya''o zamazökhi!"', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 10, 'Ba andrö, ba hiza, ulau khöu ba ba nidanö andrö khöu, ba ubali''ö si lö niha-niha ba tanö si mate danö Miserayi, i''otarai Migidola, numalö ba Ziene, ba ba nola Khusi.[4]', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 11, 'Lö''ö sa''ae itörö ahe niha, ba he ahe zaliŵa-liŵa ba danö: si lö niha ia, 40 fakhe wa''ara.', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 12, 'Ubali''ö tanö si mate danö Miserayi, bakha ba dalu danö bö''ö, si no mufufu, ba banuara, ba adudula, bakha ba hunö mbanua bö''ö, si no adudu göi, 40 fakhe wa''ara; ba Dawa Miserayi, ba ufazaewe ba niha baero, ba danö bö''ö misa ufazawili ira.', '["Faigi göi Yes 19","Yes 27:1; 51:9; Faigi 32:2","RazII 18:21; Yes 36:6","Yer 44:1; 46:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476409, 'OT', 'Hezekieli', 29, 13, 'Imane sa So''aya, Yehowa: Na no irugi 40 wulu fakhe dania, ba ufuli u''ozaragö Ndrawa Miserayi, ba niha baero misa, ba nifazaewe ya''ira.', '["Faigi 21:24"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 14, 'Ba u''ohe mangawuli Ndrawa Miserayi, ni''oloi''ö mege, ba danö Wataro, ba danö mbörötara u''ohe ira; ba soi side-ide dania ira ba da''ö.', '["Faigi 21:24"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 15, 'Ide-ide ira, moroi ba soi niha bö''ö, ba lö''ö sa''ae fayaŵa ira, ba niha baero, ba lö ato ira ube''e, fa tebai sa''ae ya''ira zamatörö niha bö''ö.', '["Faigi 21:24"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 16, 'Ba tenga sa''ae tötönafö ma''uwu Gizeraeli zangadugö ya''ira, ba lalöra andrö, na la''olembai ira; ba aboto ba dödöra, wa no ya''odo Yehowa, So''aya.[5]', '["Faigi 21:24"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 17, 'Ba ndrofi si 27, ba zi sambua desa''a ba mbaŵa si föföna, ba humede khögu Yehowa, imane: He ono niha!', '["Sin 132:17"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 18, 'No halöŵö safökhö lahalö sabölö andrö khö Nebukanesa ba Diro andrö, ibe''e Nebukanesa, razo Mbabeli: no ahori adeha mbu högö, ba alisi fefu, ba no azaza; ba lö nitemara böli gölöra, ba Diro andrö, ba halöŵöra, nihalöra ba khöra, he ya''ia ba he sabölö andrö khönia.', '["Sin 132:17"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 19, 'Andrö wa imane So''aya, Yehowa: Hiza, ube''e bualagu khö Nebukanesa, razo Mbabeli, danö Miserayi andrö, ena''ö i''oloi''ö gana''ara, ba ena''ö irabu ba ibo''ai zi so: da''ö mböli gölö zabölö andrö khönia dania.', '["Sin 132:17"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 20, 'Luora ba halöŵö andrö nihalöra ube''e danö Miserayi, me no mohalöŵö ira khögu, iŵa''ö So''aya, Yehowa.', '["Sin 132:17"]', NULL),
  (3476409, 'OT', 'Hezekieli', 29, 21, 'Ba na luo da''ö, ba ufatumbu''ö dandru ba ma''uwu Gizeraeli, ba ya''ugö, ba utolo, fa lö ata''u''ö muhede ba khöra, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.[6]', '["Sin 132:17"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 1, 'Ba so niŵa''ö Yehowa khögu,', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 2, 'imane: He ono niha, ama''ele''ö, ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Mi''ege-ege, alai mbaŵa andrö!', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 3, 'Noa sa ahatö mbaŵa andrö; baŵa andrö khö Yehowa, ba no ahatö! Baŵa salu mbanua, inötö ba niha baero ia,[1]', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 4, 'Ba irugi Ndrawa Miserayi si''öli, ba humeu danö Khusi, na tegaölö tou nibunu ba Ndrawa Miserayi, ba na la''oloi''ö gana''ara ba na ladudugö mbanua.', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 5, 'Khusi ba Futi ba Ludi, fabaya niha si fakhöyö andrö fefu, ba Kubi ba Dawa Gereta, ba mate ba mbawa zi''öli, awöra.[2]', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 6, 'Da''ö niŵa''ö Yehowa: Aso''a dania tuwutuwu Miserayi andrö, ba awuwu tou lakhömira andrö, si no ebua; i''otarai Migidola, numalö ba Ziene, ba mate ira ba mbawa zi''öli iŵa''ö So''aya, Yehowa.[3]', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 7, 'Ba tanö si mate dania danöra, bakha ba dalu danö bö''ö, si no mubali''ö tanö si mate göi; ba banua khöra ba bakha ba hunö mbanua si no adudu so.[4]', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 8, 'Ba aboto dania ba dödöra, wa no ya''odo Yehowa, na ugule''ö galitö ba danö Miserayi, ba na te''ö''ötö tou fefu zi fa''awö khöra.', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 9, 'Ba na luo da''ö, ba so zinenge, sowaö-waö fönagu, ba nowo, ba wokeani Khusi andrö, si lö fa''abu dödö na, ba humeu dania danöra, ba mbaŵa Miserayi andrö; hiza sa, irugi dania!', '["Sef 1:14, b.t.","Yer 46:9","Faigi 29:10","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 10, 'Da''ö niŵa''ö Zo''aya, Yehowa: U''etu''ö sa''ae gua-gua andrö ba danö Miserayi tanga Nebukanesa, razo Mbabeli.', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 11, 'Ya''ia ba banuania, awönia, ni''ohe moroi sa, soi safaito, ba wamufu tanö, ba lasöbi zi''ölira ba danö Miserayi ba anönö danö nibunu labe''e.[5]', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 12, 'Ba u''ogo''öisi nidanö, ba tanö, ba u''amawa ba niha si lö sökhi, ba ubali''ö tanö si mate danö ba ufufu nösinia tanga niha bö''ö. No ya''o Yehowa zanguma''ö![6]', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 13, 'Da''ö niŵa''ö Zo''aya, Yehowa: Ufufu nadu andrö ba uhori wamaedo andrö ba Nofi, awö zalaŵa ba danö Miserayi, fa lö ya''ira sa''ae dania; ba uhawui fa''ata''u Ndrawa Miserayi.', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 14, 'Ba ududugö Wataro ba ugule''ö galitö ba Zoana ba ufatörö huku ba No.[7]', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 15, 'Ba uhawui bakhu-bakhu dödögu Zini, banua saro andrö ba danö Miserayi, ba uhori zato andrö ba No.', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 16, 'Ugule''ö galitö ba danö Miserayi, ba sanizi-nizi ba sogikhi dania Zini; ba ba No, ba atu''a nemali, ba ba Nofi, ba emali ba zi ma''ökhö.', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 17, 'Ono matua ba Oni ba ono matua ba Wibese, ba si mate ba mbawa zi''öli, ba banua bö''ö, ba ni''oloi''ö.[8]', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 18, 'Ba Dakhifane, ba ogömi-gömi ba zi ma''ökhö, na ufatö ba da''ö zi''o zalaŵa ba Ndrawa Miserayi, ba na a''ozu ba da''ö lakhömira andrö, si no ebua. Banua andrö, ba ibalugö salu, ba halama soya khöra, ba ni''oloi''ö.[9]', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 19, 'Huku ufatörö ba Ndrawa Miserayi, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '["Faigi 28:7","Yes 19:5","Yes 19:13; Yer 46:25; Nakh 3:8","MozI 41:45","Yes 43:8"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 20, 'Ba ba ndröfi si felezara, ba zi mewitu ba mbaŵa si föföna, ba so niŵa''ö Yehowa khögu, imane:', '["Yer 37:7","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 21, 'He ono niha, ta''io Wara''o andrö, razo Miserayi, ba no ufatö, ba hiza, ba lö labe''e dalu-dalu; ena''ö ifuli abe''e, na labe''e dalu-dalu, na la''olohuni, ena''ö ifuli abe''e, ba wanuyu si''öli.[10]', '["Yer 37:7","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 22, 'Andrö wa imane So''aya, Yehowa: Hiza, ulau khö Wara''o andrö, razo Miserayi, ufatö da''ionia, he ta''ionia sabe''e na, ba he si no afatö andrö; ba utimba ba dangania zi''öli.', '["Yer 37:7","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 23, 'Ba ufazaewe ba niha baero Ndrawa Miserayi, ba danö zotanö misa ufazawili ira.[11]', '["Yer 37:7","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 24, 'Ba u''abe''e''ö danga razo Mbabeli, ba ube''e ba dangania zi''öli andrö khögu; ba ta''io Wara''o, ba ufatö, ena''ö mangarö-ngarö ia föna razo Mbabeli, timba wangarö-ngarö nihandro toho.', '["Yer 37:7","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 25, 'Ba tanga razo Mbabeli, ba u''abe''e''ö, ba sadada danga Wara''o, ba ya aboto ba dödöra, wa no ya''odo Yehowa, na ube''e ba danga razo Mbabeli zi''öli andrö khögu, ena''ö ilau ba Ndrawa Miserayi.', '["Yer 37:7","Faigi 29:12"]', NULL),
  (3476410, 'OT', 'Hezekieli', 30, 26, 'Ba ufazaewe ba niha baero Ndrawa Miserayi, ba danö zotanö misa ufazawili ira, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '["Yer 37:7","Faigi 29:12"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 1, 'Ba ba ndröfi si felezara andrö, ba zi sambua desa''a ba mbaŵa si tölu, ba so niŵa''ö Yehowa khögu, imane:', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 2, 'He ono niha, ömane khö Wara''ö andrö, razo Miserayi: Ha niha zi falaŵalaŵa khöu, ba wa''ebuamö andrö?', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 3, 'Hiza geresi ba hili Libano, si sökhi daha ba si sökhi hogu ba si no alaŵa sibai, ba lawuo si yaŵa irugi hogunia.[1]', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 4, 'No idanö wangebuania mege, no molö wamanöi; no ifasui hohounia naha andrö ba nitanö ya''ia, ba irugi mbörö geu ba mbenua fefu eleania.', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 5, 'Andrö wa no ebua ia moroi ba geu bö''ö fefu, ba mbenua; itugu tedou wa''ebua hogunia, itugu anau ndrahania ba wa''abölö nidanö, na i''oro''ö ndraha.', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 6, 'Ba ndrahania andrö mangazuni ngawalö wofo ba dalu mbanua, ba ba mbörönia mo''ono gutu ndru''u fefu, ba ba lumönia mowanua soi niha andrö, ha wa''oya.', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 7, 'Ba no si sökhi ia, ba wa''ebuania andrö, ba wa''anau ndrahania, me no irugi zabölö idanö ŵa''ania.', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 8, 'Lö italu''i ia eresi bö''ö, ba kabu Lowalangi, ba lö si falaŵalaŵa khönia daha zenobari, ba daha mbaranga, ba lö si fagölö-gölö khönia; sara lö eu ba kabu Lowalangi andrö, si falaŵalaŵa khönia, ba wa''asökhi.[2]', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 9, 'No si sökhi ia ba wa''afahöna ndrahania ube''e, ba fefu döla geu ba Gedena, ba kabu Lowalangi andrö, ba no safökhö tödö khönia.', '["Dan 4:7","MozI 2:8"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 10, 'Andrö wa imane So''aya, Yehowa: Me no alaŵa sibai ia ba me no irugi lawuo si yaŵa hogunia, ba me no fayaŵa dödönia, ba wa''amanöinia andrö,', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 11, 'andrö wa no ube''e ia ba danga zabölö ba niha baero, da''ö dania zolau khönia; no ba walösökhinia, wa uheta ia ba danö.', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 12, 'Ba no la''obö ia niha bö''ö, fondrege zafaito ba niha baero, no laso''agö tou. Ba hili ba ba ndraso misa fefu muzawili duturunia, ba dahania, ba no safatö tou ba ndraso mbombo misa ba danö, ba mofanö soi niha ba danö fefu, laheta ira ba lumönia, ba laröi tou ia.[3]', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 13, 'Ba ba mbotonia tou manuge wofo ba dalu mbanua, ba barö ndrahania soso gutu ndru''u ba mbenua fefu,', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 14, 'ena''ö böi sa''ae ebua hadia ia geu ba mbewe nidanö, böi sa''ae irugi lawuo si yaŵa hogu, böi sa''ae fayaŵa zabölönia ba da''ö, fefu zanisiö idanö andrö. Noa sa mululu ba wa''amate fefu, ba mbanua tou, ba hunö nono niha bakha, ba zi no möi mitou ba gohokoho.', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 15, 'Imane So''aya, Yehowa: Me luo möi mitou ia ba mbanua tou, ba abu dödö nidanö ube''e ba utaha hohounia, ba toba''a nidanö andrö, si no abölö. No ubalugö salu hili Libano, börö ia, ba no ba khönia, wa no ariri geu ba mbenua, fefu.', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 16, 'Ba werara wa''aso''ania andrö, ba humisi niha baero ube''e, me utuli''ö ia si tou ba mbanua tou, ba zi no numalö mitou ba gohokoho, ba arara dödö geu Gedena fefu, ba mbanua tou, eu nitutuyu andrö, fondrege zi sökhi ba hili Libano, fefu zanisiö idanö.[4]', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 17, 'Si fao khönia göi da''ö mitou ba mbanua tou, ba nibunu si''öli andrö, fabaya nga''ötöra, sonahia ba lumönia mege, bakha ba hunö niha baero.', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476411, 'OT', 'Hezekieli', 31, 18, 'Hezo zi falaŵalaŵa ndra''ugö ba wa''asökhi ba ba wa''alaŵa, ba geu Gedena andrö? Ba awö geu Gedena andrö tetuli''ö si tou ndra''ugö, ba mbanua tou; tou, bakha ba hunö zi lö muboto so''ö dania, ba nibunu si''öli andrö: da''ö Wara''o andrö, fabaya lakhöminia fefu, iŵa''ö So''aya, Yehowa.[5]', '["Faigi 28:7","Yes 14:8","Faigi 28:10"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 1, 'Ba ba ndröfi si felendrua, ba zi sambua desa''a ba mbaŵa si felendrua, ba so niŵa''ö Yehowa khögu,', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 2, 'imane: He ono niha, e''esi Wara''o andrö, razo Miserayi, ömane khönia: Ya''ugö ono zingo ba niha baero, lö ya''ugö sa''ae! no timba mbuaya ba molö ndra''ugö, no izö''izö nikhumö, no ö''olotui nidanö ahemö, no manambunambu ndra''ugö ba hohou.[1]', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 3, 'Da''ö niŵa''ö Zo''aya, Yehowa: Uhawui sa''ae ndra''ugö dialagu ba zoya aekhu soi niha, ba ladöni yaŵa ndra''ugö, ba ndrialagu andrö.[2]', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 4, 'Ba ufazaumba yaŵa ba danö ndra''ugö, ba mbenua utibo''ö tou ndra''ugö, ba manuge ba mbotomö wofo ba dalu mbanua fefu ube''e; ba utu ndru''u ba guli danö ma''asagörö, ba u''abusoi''ö ösiu.[3]', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 5, 'Ba u''ohe yaŵa ba hili nösiu, ba ufo''ösi ndraso amatelamö.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 6, 'Ba ba danö ninönöimö mege, ba ufabadugö ndromö, irugi ba gahe hili, ba afönu ngöfi mbombo öbe''e.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 7, 'Ba ba wa''amatemö, ba alu mbanua ube''e ba ubalugö saitö ndröfinia; luo, ba ubalugö lawuo, ba baŵa, ba si lö haga.[4]', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 8, 'Sihaga andrö ba mbanua si yaŵa, ba ubalugö saitö, börö ndra''ugö, ba uhawui sogömi-gömi danömo, iŵa''ö So''aya, Yehowa.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 9, 'Ba oya soi niha, ba abu dödö ube''e, na u''ohe ba niha baero gadudulamö, ba danö zotanö, si lö örai ö''ila.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 10, 'Ba oya soi niha zi tobali tödö ube''e, ba khömö andrö, ba razora, ba sihokha mbu, börö ndra''ugö, na ufaligoi zi''öli fönara, ba sanizi-nizi ira, si lö mamalö-malö; ba nosonia manizi-nizi zamösana, na luo wa''ate''alamö andrö.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 11, 'Imane sa So''aya, Yehowa: Irugi dania ndra''ugö si''öli razo Mbabeli.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 12, 'Si''öli zabölö andrö ube''e famufu lakhömimö andrö; fondrege zafaito niha fefu. Da''ö dania zamufu hokha Miserayi andrö; ba lakhömira fefu, ba nihori.[5]', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 13, 'Ba uriföra fefu ba zabölö idanö andrö, ba uhori, ba sara lö ahe niha sa''ae dania si olotui idanö andrö, ba he sa''a zaliŵa-liŵa ba danö.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 14, 'Ba ohahau dania nidanö andrö khöra, ube''e, ba hulö wanikha wa''ahele hohounia, iŵa''ö So''aya, Yehowa,', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 15, 'na ubali''ö tanö si mate danö Miserayi, na no afufu danö ba na si lö ösi sa''ae, na ubunu fefu zowanua ba danö, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 16, 'Fange''esi da''e, nilau, ono niha baero alawe zolau ya''ia: ba danö Miserayi ba ba lakhömira andrö fefu latandrösaigö, iŵa''ö So''aya, Yehowa.', '["Faigi 29:3","Faigi 12:13","Faigi 29:5","Yes 13:10","Faigi 28:7"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 17, 'Ba ba ndröfi si felendrua, ba duli, ba so niŵa''ö Yehowa khögu,', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 18, 'imane: He ono niha, e''esi lakhömi Miserayi andrö, ba dada tou ia ba mbanua tou, ba zi no numalö mitou ba gohokoho, ya''ugö ba ono soi sebua alawe.[6]', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 19, 'Hadia, tenga no omasiö ndra''ugö moroi ba niha bö''ö fefu? Ae si tou ba be''e nifaförö ba ngai zi lö muboto ndra''ugö![7]', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 20, 'Bakha ba hunö nibunu si''öli tegaölö tou ira. No mube''e zi''öli; ba tefaförö tou ia, fabaya lakhöminia fefu!', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 21, 'Ba lamane dania khönia sabölö andrö moroi ba dalu mbanua tou, khönia ba ba zi no fa''awö khönia: No ahöndrö si tou, no so tou ba da''ö zi lö muboto, nibunu si''öli andrö.', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 22, 'Hiza Asiria ba sato khöra fefu, si no tefasui lewatönia, — oi nibunu tou, si mate ba mbawa zi''öli mege —', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 23, 'ba wondrege ba watalinga tebe''e mege lewatöra, ba no tefasui satonia lewatönia, oi nibunu tou mege, si mate ba mbawa zi''öli, sameta''u niha mege ba danö niha sauri.', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 24, 'Hiza Gelama ba satonia fefu, si tefasui lewatönia, oi nibunu tou mege, si mate ba mbawa zi''öli, si no numalö mitou ba mbanua tou lö muboto, sameta''u niha mege, ba danö niha sauri, ba solu''i iya''e wa''ailara, awö zi no numalö mitou ba gohokoho.[8]', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 25, 'Bakha ba hunö nibunu lafazökhi khönia naha wemörö, awö naha zatonia andrö, tefasui ia lewatöra, oi si lö muboto, si mate ba mbawa zi''öli mege — noa sa sameta''u niha mege ira ba danö niha sauri —; ba lalu''i iya''e wa''ailara, ba ngai zi no numalö mitou ba gohokoho, bakha ba hunö nibunu tebe''e nahara.', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 26, 'Hiza Mesekhi ba Tubala ba satora fefu, no tefasui ia lewatö da''ö, oi si lö muboto, si mate ba mbawa zi''öli mege, sameta''u niha mege, ba danö niha sauri.[9]', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 27, 'Tenga ba ngai zabölö andrö so ira, tenga ba ngai zabölö si mate nibunu ba götö föna sibai, si lö aheta fangaro, ba welalö mitou, ba mbanua tou, nibe''e tandraya si''ölira, ba ambala gamatelara mbalusera; noa sa sata''u niha zabölö andrö, ba danö niha sauri mege.', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 28, 'Ba bakha ba hunö zi lö muboto arasa ndra''ugö, ba ba ngai nibunu si''öli mörö tou ndra''ugö!', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 29, 'Hiza Gedomo andrö, awö razora, awö zalaŵara fefu, si no mube''e ba ngai nibunu si''öli, ba wa''abölöra andrö; ba ngai zi lö muboto tou so ira, ba ngai zi no numalö mitou ba gohokoho.', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 30, 'Hiza razo moroi yöu ba banua Zidona fefu, si no numalö mitou nibunu, lö lai wa no sata''u ita mege, lua-lua wa''abölöra, si no aila ira. No tou ba da''ö so ira, lö muboto, ba ngai nibunu si''öli; ba lalu''i wa''ailara, awö zi no numalö mitou ba gohokoho.', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 31, 'Da''ö [fefu] ni''ila Wara''o andrö dania, ba arara dödönia, ba lakhöminia andrö fefu; nibunu si''öli Wara''o andrö, awö zabölö andrö khönia fefu, iŵa''ö So''aya, Yehowa.', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476412, 'OT', 'Hezekieli', 32, 32, 'Noa sa sata''u niha ia mege ba danö niha sa''uri; andrö wa labe''e tou ia bakha ba hunö zi lö muboto, ba ngai nibunu si''öli: Fara''o andrö, fabaya lakhöminia fefu, iŵa''ö So''aya, Yehowa.', '["Faigi 31:14","Faigi 28:10","Yer 49:36","Faigi 27:13; 38:2"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 1, 'Ba so niŵa''ö Yehowa khögu,', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 2, 'imane: He ono niha, hede ba ndraono mbanuami, ömane khöra: Na ufatörö zi''öli ba danö, heza, ba na latuyu zamösa, ba khöra fefu,', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 3, 'nibe''e sanaro khöra, ba na i''ila, itörö danö si''öli, ba na ilau dorofe, na ifangelama niha, —', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 4, 'ba na lö ibe''e nifangelama ia samondrongo li dorofe andrö, ba na möi famununia, ba ya ba hulunia so ndronia![1]', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 5, 'No irongo li dorofe, ba lö nibe''enia nifangelama ya''ia: ya ba hulunia so ndronia! Ba sanaro no mege, ba no ifangelama ia, ba no i''orifi nosonia.', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 6, 'Ba na i''ila moroi sa zi''öli sanaro andrö, ba na lö ilau dorofe, na lö tefangelama zato, ba na itörö si''öli, na möi famunu niha ba khöra, ha niha ia; ba si mate ba lalönia da''ö, ba donia, ba ba danga zanaro andrö u''alui.', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 7, 'Ba ya''ugö ono niha, ba no ube''e sanaro ba ma''uwu Gizeraeli, ena''ö öfangelama ira, ena''ö öfa''ema niŵa''ögu, na no örongo daroma ligu.[2]', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 8, 'Na uŵa''ö khö zi no mangerogö Lowalangi: "Si mate ndra''ugö, sebua horö!" ba na lö hede-hedeu, ba wamangelama si no mangerogö Lowalangi, ba mbua-buania andrö, ba si mate zebua horö andrö ba lalönia, ba donia, ba ba dangau u''alui.', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 9, 'Ba tenga ba khöu so, na no öfangelama zi no mangerogö Lowalangi, ba mbua-buania andrö, ena''ö ifalalini gera-erania, ba na lö iböhöli mbua-buania, ba si mate sa ia, börö lalönia andrö, ba ya''ugö, ba no ö''orifi nosou.', '["Faigi 18:13","Faigi 3:17"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 10, 'Ba ya''ugö ono niha, ba ömane ba ma''uwu Gizeraeli: No mimane: Si ndruhu, no tohare khöma lalöma, awö horöma, ba moroi ba da''ö, wa ariri ndra''aga, ba heza masöndra fa lö mate ndra''aga?[3]', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 11, 'Ömane khöra: Faya wa no sauri ndra''o, na omasido mate zebua horö; somasi ndra''o na iröi lalania andrö sebua horö, na ifalalini gera-erania, ba na auri ia. Mifalalini gera-erami, miröi lalami andrö, si lö sökhi! Hana sa wa edöna mate ami, ya''ami ma''uwu Gizeraeli?[4]', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 12, 'Ba ya''ugö ono niha, ba ömane ba niwami: Ba zatulö tödö andrö, ba tenga fangorifi wa''atulö dödönia andrö, na luo molalö ia; ba ba zi so horö, ba tenga famunu horönia, na luo ifalalini gera-erania, na iböhöli horönia andrö; ba satulö tödö, ba lö auri ba da''ö, na luo molalö ia.', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 13, 'Na umane khö zatulö tödö: Lö zi lö auri ndra''ugö, ba na abe''e dödönia ba wa''atulö dödönia andrö, ba na ifazökhi zi lö sökhi, ba lö''ö sa''ae itörö tödö mbua-buania si sökhi andrö; ba zi lö sökhi andrö, nilaunia, mate ia.', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 14, 'Ba na umane khö zi so horö: Si mate ndra''ugö! ba na ifalalini gera-erania, na iböhöli horönia andrö ba na ilau zadölö ba satulö,', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 15, 'na ifuli gade ba na i''ali zinagö, ba na i''o''ö nifakhoigu, ba wangorifi, na lö''ö sa''ae ifazökhi zi lö sökhi, ba sauri ia, lö mate![5]', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476413, 'OT', 'Hezekieli', 33, 16, 'Horönia andrö fefu, nifazökhinia mege, ba lö''ö sa''ae tebe''e horönia: no sadölö ba satulö nilaunia, ba sauri ia.', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 17, 'Ba lamane na iwami: "Tenga satulö wolau Yehowa," ba no folaura zi lö atulö.[6]', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 18, 'Na iböhöli wa''atulö dödönia satulö tödö ba na ifazökhi zi lö sökhi, ba si mate ia ba da''ö.', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 19, 'Ba na ifalalini gera-erania si so horö, na iböhöli horönia andrö, ba na ilau zadölö ba satulö, ba möi börö wangorifinia da''ö.', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 20, 'Ba no mimane: "Tenga satulö wolau Yehowa!" Bua-buami ube''e dali wanguhuku zamösana ba khömi, ya''ami ma''uwu Gizeraeli!', '["Faigi 24:23","SamII 14:14; Faigi 18:23","MozII 22:4,26; MozIII 6:2 b.t.","Faigi 18:25"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 21, 'Ba me no arakha mewelendrua fakhe aefa wangoloi''ö ya''aga, ba möi khögu zoloi ba Yeruzalema, solohe turia, imane: "No atu''a zanuwö ba mbanua!"[7]', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 22, 'Ba sara wongi lö''ö na soloi andrö, ba no ira''u ndra''o tanga Yehowa, ba no ibokai mbawagu, föna we''amöi da''ö khögu, si hulö wongi, ba lö''ö sa''ae ubato wehede, tenga sa''ae si lö hede ndra''o.', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 23, 'Ba so niŵa''ö Yehowa khögu,', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 24, 'imane: He ono niha, lamane si so ba gadudula andrö ba danö Ndraono Gizeraeli: Ha samösa Gaberahamo, ba tebe''e zui okhötania danö andre, ba ya''aga, ba no ato, khöma tebe''e okhöta danö.', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 25, 'Andrö wa ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Ba hili manga-manga ami [ö nadu] ba ba nadu andrö khömi mifaöga hörömi, ba manuwagö do ami — ba midöna-döna möi okhötami danö?[8]', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 26, 'Abe''e dödömi ba zi''ölimi, molau si lö sökhi ami, faoma mibe''e ta''unö ndronga nawömi — ba midöna-döna okhötami danö?', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 27, 'Ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Faya wa no sauri ndra''odo, na fayagu: si so ba gadudula andrö, ba si mate ba mbawa zi''öli dania, ba si so ba mbenua, ba ube''e ö gutu ndru''u, ba si so ba dete gara yaŵa ba ba dögi narö hili, ba si mate ba wökhö waba.', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 28, 'Ba ubali''ö tanö si lö niha-niha danö ba tanö si mate, ba awai sa''ae dania hokhania andrö, ba tanö si mate hili Ndraono Gizeraeli, fa lö sanörö sa''ae.', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 29, 'Ba aboto dania ba dödöra, wa no ya''odo Yehowa, na no ubali''ö tanö si lö niha-niha danö ba tanö si mate, börö zogoro ita andrö khöra, fefu, nilaura.', '["RazII 25:4,5; Faigi 24:26","MozI 9:4; MozIII 19:26"]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 30, 'He ono niha, fahuhuo niwami ba zalogotö ba ba mbagi nora; faoma lamane khö nawöra ba da''ö: Mitabu ba mifondrondrongo hadia daroma li Lowalangi andrö!', '[]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 31, 'Ba lahurufai ndra''ugö, ba dumao-dao ira fönau, banuagu, ba na no larongo niŵa''öu, ba lö''ö zui la''o''ö. Fa''omasi lafa''ua bawara, ba tödöra, ba no solohi hare.', '[]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 32, 'Ba hiza, ba amaedola wanunö omasiö ndra''ugö khöra, si sökhi li ba si no onekhe folau biola, ba larongo limö, ba lö la''o''ö.', '[]', NULL),
  (3476413, 'OT', 'Hezekieli', 33, 33, 'Ba na itörö dania — ba hiza, itörö — ba awena aboto ba dödöra, wa no so zama''ele''ö ba khöra.', '[]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 1, 'Ba so niŵa''ö Yehowa khögu,', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 2, 'imane: He ono niha, ama''ele''ö nitandrösaigö ba gubalo Ndraono Gizeraeli andrö; ama''ele''ö, ömane ba gubalo andrö: Da''ö niŵa''ö Zo''aya, Yehowa: Alai gubalo Ndraono Gizeraeli andrö, sokubaloi botora! Hadia, tenga biri-biri ikubaloi kubalo?[1]', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 3, 'Susu, ba no mibadu, ba bu, ba no mihalö nukhami, ba si no atabö, ba no mitaba, ba fokubaloimi biri-biri, ba no lö''ö![2]', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 4, 'Samomo, ba lö ni''abe''e''ömi, ba ba zafökhö, ba lö nifadöhömi fökhö, ba ba zesokho, ba lö nibe''emi dalu-dalu, ba si no muzaewe, ba lö nihalömi mangawuli, ba sisuna, ba lö ni''aluimi, no sabe''e ami wamatörö ya''ira, no safaito.[3]', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 5, 'Ba no tobali muzaewe ira, me no lö kubalo, ba no tobali ö gutu ndru''u ba danö fefu ira, ba muzawili.', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 6, 'Ba hili misa fefu ba ba hili-hili salaŵa fefu elungu-lungu mbiri-biri; ba ba danö ma''asagörö misa zumawili mbiri-birigu andrö, ba lö samaigi-maigi ya''ira, lö sangalui.', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 7, 'Andrö, ya''ami kubalo, mifondrondrongo li Yehowa!', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 8, 'Faya, wa no sauri ndra''o, na fayagu, iŵa''ö So''aya, Yehowa; si ndruhu, me no tobali ahulua mbiri-birigu andrö, me no ö gutu ndru''u ba danö mbiri-birigu, lö kubalo, ba me no lö ba dödö gubalo andrö khögu mbiri-birigu — noa sa botora lakubaloi kubalo, ba biri-birigu, ba lö nikubaloira —: andrö,', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 9, 'ya''ami kubalo, mifondrondrongo li Yehowa!', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 10, 'Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ulau ba gubalo andrö; ba dangara usugi mbiri-biri ba u''etu''ö wokubaloira biri-biri; ba böi sa''ae lakubaloi mbotora kubalo andrö, ufadöni sa''ae ba mbawara mbiri-biri andrö, fa böi sa''ae möi öra.', '["Yer 23:1 b.t.","Sakh 11:16","FetI 5:3"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 11, 'Imane sa So''aya, Yehowa: Hiza ndra''odo, ba wangalui biri-birigu andrö ba ba wamaigi-maigi ya''ira.[4]', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 12, 'Si mane famaigi-maigi gubalo biri-biri, na luo so ia ba hunö mbiri-birinia, si no muzaewe, si manö dania wangaluigu biri-birigu, ba u''orifi ira, moroi ba danö andrö misa fefu, ba nifazaewe ya''ira, me luo abölö lawuo ba me alu.[5]', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 13, 'Ba u''ohe ira miyaŵa, moroi ba niha baero ba u''ozaragö ira ba danö zotanö misa, ba u''ohe ira ba danöra, ba ukubaloi ira ba hili Ndraono Gizeraeli ba ba mbewe mbombo, ba ba danö misa fefu, ba zi so banua niha.[6]', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 14, 'Ba zabölö du''u ukubaloi ira, ba ba hili salaŵa ba Ndraono Gizeraeli so nahara, naha göra; ba da''ö mörö-mörö ira ba mbenua si sökhi ba satabö göra du''u ba hili Ndraono Gizeraeli.', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 15, 'Ya''odo dania zokubaloi biri-birigu ba ya''odo zame''e mörö ya''ira, iŵa''ö So''aya, Yehowa.', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 16, 'Sisuna, ba u''alui, ba si no muzaewe, ba uhalö mangawuli, ba ba zesokho, ba ulau dalu-dalu, ba sofökhö, ba u''abe''e''ö, ba satabö ba sabölö, ba urorogö; u''onangegö wokubaloi.', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 17, 'Ba ya''ami biri-birigu, da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ufatunö huhuo mbiri-biri andrö ba nawöra, ba he huhuo nikhai ba zi matua.[7]', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 18, 'Hadia, ambö na khömi, na ba wondrege zatabö du''u misöndra gömi, wa mihundra-hundra na tou zi lö ahori mi''a; ba na idanö sohahau mibadu, wa mi''olotui ahemi zi tosai?', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 19, 'Ba tobali ö mbiri-birigu zi no mihundra-hundra tou, ba öra idanö zi no mi''olotui ahemi.', '["Yoh 10:11 b.t.","Faigi 30:3; Yoel 2:2","Faigi 28:25","Mat 25:32"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 20, 'Andrö wa imane khömi So''aya, Yehowa: Hiza ndra''odo, ba wamatunö huhuo mbiri-biri satabö andrö ba zafuo.', '["Yes 40:11; Yer 23:5; Faigi 37:24; Heb 13:20; FetI 2:25; 5:4","Yes 42:1"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 21, 'He no mibe''e fanimba biri-biri sambö fa''abölö fefu ngaimi ba alisimi, ba me no mitatandru, irege no mituli''ö baero ira.', '["Yes 40:11; Yer 23:5; Faigi 37:24; Heb 13:20; FetI 2:25; 5:4","Yes 42:1"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 22, 'Ba utolo sa''ae mbiri-birigu andrö, fa böi sa''ae ahulua ira, ba ufatunö huhuo mbiri-biri ba nawöra.', '["Yes 40:11; Yer 23:5; Faigi 37:24; Heb 13:20; FetI 2:25; 5:4","Yes 42:1"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 23, 'Ba ufataro gubalo khöra, si ha samösa, da''ö dania zokubaloi ya''ira, enonigu Dawido andrö. Da''ö zokubaloi ya''ira, da''ö gubalora.[8]', '["Yes 40:11; Yer 23:5; Faigi 37:24; Heb 13:20; FetI 2:25; 5:4","Yes 42:1"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 24, 'Ba ya''odo Yehowa, ba Lowalangira, ba enonigu Dawido andrö, ba salaŵa ba khöra; no ya''odo, Yehowa, zanguma''ö![9]', '["Yes 40:11; Yer 23:5; Faigi 37:24; Heb 13:20; FetI 2:25; 5:4","Yes 42:1"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 25, 'Ba fawu''u li ndra''o khöra, fawu''usa li ba wa''atulö, utu ndru''u safaito fefu, ba utaboi, uheta ba danö, ba tobali tola la''iagö danö si mate, lö hadia ia, ba tola mörö ba dalu gatua.[10]', '["Faigi 37:26; Hos 2:18","MozIII 26:3–6","Sin 85:13","Yer 30:10; 46:27","Faigi 36:37"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 26, 'Ba ya''ira ba hadia zi tefasui hili-hili andrö khögu, ba ubali''ö howu-howu, ba ube''e aekhu ba danö deu na inötö; teu howu-howu deu andrö![11]', '["Faigi 37:26; Hos 2:18","MozIII 26:3–6","Sin 85:13","Yer 30:10; 46:27","Faigi 36:37"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 27, 'Ba mowua geu ba kabu, ba tanö, ba mowua, ba la''iagö danöra lö hadia ia, ba aboto ba dödöra, wa no ya''odo Yehowa, na ufatö döla galo mbagi andrö khöra, ba na u''efa''ö ira ba danga zangosawuyu ya''ira mege.[12]', '["Faigi 37:26; Hos 2:18","MozIII 26:3–6","Sin 85:13","Yer 30:10; 46:27","Faigi 36:37"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 28, 'Ba böi sa''ae ahulua niha baero ira ba böi sa''ae möi ö gutu ndru''u ba danö; sahono ira, lö hadia ia, ba nahiara, lö si keani ya''ira.[13]', '["Faigi 37:26; Hos 2:18","MozIII 26:3–6","Sin 85:13","Yer 30:10; 46:27","Faigi 36:37"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 29, 'Ba si no maulu zinanöra ube''e, ba samösa lö''ö sa''ae ba danö si mate olofo, ba alakha lö''ö sa''ae lataögö wango''aya niha baero.', '["Faigi 37:26; Hos 2:18","MozIII 26:3–6","Sin 85:13","Yer 30:10; 46:27","Faigi 36:37"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 30, 'Ba ya aboto ba dödöra, wa utolo ira, ya''odo andre, Yehowa, Lowalangira, awö wa no banuagu ira, ya''ira, ma''uwu Gizeraeli, iŵa''ö So''aya, Yehowa.', '["Faigi 37:26; Hos 2:18","MozIII 26:3–6","Sin 85:13","Yer 30:10; 46:27","Faigi 36:37"]', NULL),
  (3476414, 'OT', 'Hezekieli', 34, 31, 'Ba ya''ami, ba no biri-birigu ami, biri-biri nikubaloigu [niha] ami; ya''odo Lowalangimi! iŵa''ö So''aya, Yehowa.[14]', '["Faigi 37:26; Hos 2:18","MozIII 26:3–6","Sin 85:13","Yer 30:10; 46:27","Faigi 36:37"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 1, 'Ba so niŵa''ö Yehowa khögu,', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 2, 'imane: He ono niha, otahögö hili Ze''ira ba ama''ele''ö, ömane khönia.[1]', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 3, 'Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ulau khöu, ya''ugö hili Ze''ira, u''oro''ö dangagu yaŵau ba ubali''ö tanö si lö niha-niha ba tanö si mate ndra''ugö.', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 4, 'Banua khöu, ba ubali''ö adudula, ba ya''ugö, ba si tobali tanö si mate, ena''ö aboto ba dödöu, wa no ya''odo Yehowa!', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 5, 'Me no si lö mamalö-malö watiusamö andrö, ba me no öbe''e ba mbaŵa zi''öli Ndraono Gizeraeli, me luo wa''ate''alara andrö, me luo wangasiwai horö,[2]', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 6, 'andrö faya, wa no sauri ndra''o, na fayagu: Hiza, ubali''ö do ndra''ugö ba do zolohi ya''ugö; si ndruhu, ba ndro horömö andrö, ba do dania zolohi ya''ugö!', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 7, 'Ba ubali''ö tanö si lö niha-niha hili Ze''ira andrö ba tanö si mate, ba uhori ba danö zangörö-ngörö.', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 8, 'Fahöna ba hilira misa nibunu tou ube''e; ba hili-hili misa khöu ba ba ndraso ba ba mbewe mbombo khöu tegaölö tou nibunu si''öli.', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 9, 'Ubali''ö tanö si lö niha-niha ndra''ugö, si lö mamalö-malö, ba si lö niha mbanua khöu, ena''ö aboto ba dödömi, wa no ya''o Yehowa.[3]', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 10, 'Me no ömane: Khögu dania soi si dombua andrö ba tanö andrö si dua görö, ya''aga zi okhögö! — he ŵa''ae no Yehowa zi so ba da''ö —.', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 11, 'Andrö: faya, wa no sauri ndra''o, na lö ube''e dali ba wolaugu khöu wönumö andrö ba fa''aukhu dödöu ba wolau khöra, me no fatiu dödöu, ba to''ila ndra''o khöu ube''e, na uhuku ndra''ugö,', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 12, 'ena''ö aboto ba dödöu, wa no ya''o Yehowa. Noa sa urongo wanandraŵaisimö andrö fefu, nilaumö ba hili Ndraono Gizeraeli andrö, me ömane: No tanö si mate ia, öda sa''ae!', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 13, 'Ba no abe''e mbawami khögu, no mihöna wehedemi khögu.', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 14, 'No urongo. Da''ö niŵa''ö Zo''aya Yehowa: Me no omuso dödöu ba danö andrö khögu, me no tanö si mate, ba umanö göi wamatörö khöu.', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476415, 'OT', 'Hezekieli', 35, 15, 'Me no omuso dödöu ba danö ma''uwu Gizeraeli, ondröita ndra tuara khöra, me no tanö si mate, ba umanö göi wamatörö khöu. Tanö si mate dania ndra''ugö, ya''ugö hili Ze''ira, ba tanö Ndraono Gedomo ma''asagörö, ena''ö aboto ba dödöra, wa na ya''odo Yehowa.[4]', '["Yer 49:7 b.t; Faigi 25:8","Yer 18:21","Faigi 34:30","Faigi 25:6"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 1, 'Ba ya''ugö ono niha, ba ama''ele''ö nitandrösaigö ba hili Ndraono Gizeraeli, ömane: Mifondrondrongo li Yehowa, ya''ami hili Ndraono Gizeraeli!', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 2, 'Da''ö niŵa''ö Zo''aya, Yehowa: Me no lamane ba khömi andrö emali: "Ha! no tanö si mate, si lö mamalö-malö! no möi okhötama!"[1]', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 3, 'Andrö wa mama''ele''ö ndra''ugö, ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, me no labali''ö tanö si mate [danömi], ba me no lafasui ami, wangisö ya''ami, ena''ö niha bö''ö zokhö ya''ami, ba me no lafatunö ami, me no lafatou ami niha,', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 4, 'andrö ya''ami hili Ndraono Gizeraeli, mifondrondrongo li Zo''aya, Yehowa! Da''ö niŵa''ö Zo''aya, Yehowa, ba hili andrö ba ba hili-hili ba ba mbombo ba ba ndraso, ba gadudula andrö, si lö niha-niha sa''ae ba ba mbanua si no aheta niha, si no tobali ahulua ba fama''iki niha bö''ö, si tefasui ya''ira, 5— andrö wa imane So''aya, Yehowa: Hiza, ba wa''aukhu dödögu andrö muhede ndra''o ba niha bö''ö andrö ba ba Ndraono Gedomo fefu, si no mamaigi khöra tanö khögu, no omuso sibai dödöra, ba me no ma''iki ira, ba wanimba niha ba danö ba ba worabu si so khöra.', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 6, 'Andrö wa mama''ele''ö ndra''ugö, nitandrösaigö ba danö Ndraono Gizeraeli, ba ömane ba hili andrö ba ba hili-hili ba ba mbombo ba ba ndraso: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ba wönugu andrö ba ba wa''abao dödögu mege muhede ndra''odo, me no sanaögö fango''aya niha baero ami.', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 7, 'Andrö wa imane So''aya, Yehowa: Ufazaŵa dangagu, [möido ba hölu], umane: Si ndruhu, niha baero andrö, si tefasui ya''ami, zanaögö dania wango''ayami!', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 8, 'Ba ya''ami hili Ndraono Gizeraeli, ba akha mobulu geumi ba akha mowua, ö mbanuagu Iraono Gizeraeli; lö''ö sa ara tö mangawuli ira!', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 9, 'Hiza sa, möido khömi, u''otahögö ami ba lahalö ami, labali''ö nowi ami.[2]', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 10, 'Ba ato niha khömi ube''e, — ma''uwu Gizeraeli ma''afefu, — ba ba mbanua misa, ba so niha, ba adudula andrö, ba lafuli lataru''ö.', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 11, 'Ba he niha, ba he uriföra, ba u''oya''ö ba khömi, itugu oya ira ba mo''ono''ono. So niha ba khömi ube''e, si mane ba götö föna, ba ube''e zi sökhi, udou''ö moroi ba nibe''egu ba götömi föna, ena''ö aboto ba dödömi, wa no ya''odo Yehowa!', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 12, 'Ba mowaö-waö ba detemi niha ube''e, banuagu Iraono Gizeraeli; da''ö zi okhögö ya''ugö, ena''ö khöra ndra''ugö, amaedola gondröita, ba lö''ö sa''ae öhori ndraonora.', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 13, 'Imane So''aya, Yehowa: Me no lamane khömi: No ira alawe si manga niha ndra''ugö, no öhorihori ndraono mbanuau —', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 14, 'andrö wa böi sa''ae si manga niha ndra''ugö ba böi sa''ae öhorihori ndraono mbanuamö, iŵa''ö So''aya, Yehowa.', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 15, 'Ba lö''ö sa''ae ufarongogö khöu wa''iki niha baero andrö, ba fango''aya soi niha, ba lö''ö sa''ae ötaögö, ba lö''ö sa''ae öhori ndraono mbanuamö, iŵa''ö So''aya, Yehowa.', '["Faigi 6:2; 25:3; 26:2","Faigi 34:30"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 16, 'Ba so niŵa''ö Yehowa khögu,', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 17, 'imane: He ono niha, me so na ba danöra ma''uwu Gizeraeli, ba no lata''unöi ia ba mbua-buara andrö ba ba zi lö sökhi andrö nifazökhira. No timba wa''ata''unö ndra alawe, na afökhö dalunia, mbua-buara andrö fönagu.[3]', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 18, 'Ba no uhawui ira fönugu, börö ndro andrö, niduwagöra ba danö, ba me no lata''unöi ia ba nadu andrö khöra.', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 19, 'Ba no ufazaewe ira ba niha baero, tefazaewe ira ba danö zotanö; bua-buara ba si lö sökhi andrö nifazökhira ube''e dali wanguhuku ya''ira.', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 20, 'Ba no larugi niha baero; ba heza larugi, ba te''o''aya döigu andrö, ni''amoni''ö, labe''e, me no lamane [niha bö''ö], ba khöra andrö: "da''ö mbanua Yehowa andrö, ba noa zui aheta ira ba danö andrö khönia!"[4]', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 21, 'Ba aröuröu ba dödögu döigu andrö, ni''amoni''ö, ni''o''ayara ba niha baero, ya''ira ma''uwu Gizeraeli, fefu gofu heza larugi.', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 22, 'Andrö wa ömane ba ma''uwu Gizeraeli: Da''ö niŵa''ö Zo''aya, Yehowa: Tenga ya''ami mbörö, wa ufaigi lala, ya''ami ma''uwu Gizeraeli, börö döigu andrö, ni''amoni''ö, ni''o''ayami ba niha baero, heza mirugi.', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 23, 'Ba u''amoni''ö döigu andrö, sebua, si no mu''o''aya ba niha baero, si no mi''o''aya ba khöra, ena''ö aboto ba dödö niha baero, wa no ya''odo Yehowa, iŵa''ö So''aya, Yehowa; na u''oroma''ö ba khömi andrö, wa no ni''amoni''ö ndra''odo, ba zanehe ira.', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 24, 'Ba uhalö ami ba niha baero andrö ba u''ozaragö ami ba danö zotanö misa fefu, ba u''ohe ami ba danömi.[5]', '["MozIII 15:19","Yes 52:5","Faigi 11:17, b.t."]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 25, 'Ba utefe ami idanö sohahau, ba aheta ndra''imi, fefu zi ra''i-ra''iömi ba adumi andrö fefu, ba uheta khömi.[6]', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 26, 'Ba ube''e khömi dödö si bohou ba Eheha si bohou ube''e ba dödömi bakha; tödö kara andrö, ba uheta barö dotomi ba ube''e khömi dödö nagole.[7]', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 27, 'Ba Ehehagu ube''e ba dödömi ba mi''o''ö nifakhoigu ube''e, ba mitöngöni lala nibe''egu ba mitörö.', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 28, 'Ba lö''ö sa''ae tebulö ami ba danö andrö, nibe''egu khö ndra tuami; ba banuagu ami, ba Lowalangimi ndra''odo.', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 29, 'Ba uheta khömi zi ra''i-ra''iö andrö fefu ba humede ndra''o ba mbua nowi ba u''oya''ö, ba lö''ö sa''ae ufatörö khömi lofo.', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 30, 'Ba bua geu ba bua danö, ba u''oya''ö, fa böi sa''ae zamuza tö milu''i wa''aila ba lofo, ba niha baero.', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 31, 'Ba itörö dania tödömi mbua-buami si lö sökhi andrö, awö nilaumi andrö si lö göna, ba ogoro dania dödömi ami, börö lalömi andrö ba sogoro ita khömi.[8]', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 32, 'Tenga ya''ami mbörö, wa u''alui lala, iŵa''ö So''aya, Yehowa; böi zi lö mirongo! Akha aila ami ba akha afusi mbawami ba mbua-buami andrö, ya''ami ma''uwu Gizeraeli.', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 33, 'Imane So''aya, Yehowa: Na luo uheta khömi lalömi andrö fefu, ba so zui niha ba mbanua misa ube''e, tetaru''ö zui gadudula andrö.', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 34, 'Ba tanö andrö, si no modu''u, ba lafuli lahalö, fa böi sa''ae si mane föna, me no tanö si mate, sanehe niha fefu, sanörö.', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 35, 'Ba lamane dania: "Tanö andre, si no tanö si mate mege, ba no tobali timba kabu Edena, ba banua andrö, si no adudula mege, si lö niha-niha sa''ae ba si no afufu, ba no mu''aro''ö iyae, ba so niha!"', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 36, 'Ba aboto dania ba dödö niha andrö si tosai, si tefasui ya''ami, wa no ya''o, Yehowa, zanaru''ö si no adudu mege ba samali''ö kabu si no tanö si mate. No ya''o, Yehowa, zanguma''ö ba ufalua göi![9]', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476416, 'OT', 'Hezekieli', 36, 37, 'Imane So''aya, Yehowa: Ba da''ö göi na ufondrondrongo wangandrö ma''uwu Gizeraeli, fa u''o''ö khöra: Ato ira ube''e, timba mbiri-biri nikubaloi.[10]', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476416, 'OT', 'Hezekieli', 36, 38, 'Timba mbiri-biri nibe''e sumange. Si mane fa''afahöna mbiri-biri ba Yeruzalema, na luo gowasa, si manö dania wa''afahöna ngawawa niha ba mbanua andrö, si lö niha-niha sa''ae mege, ena''ö aboto ba dödöra, wa no ya''odo Yehowa!', '["Yes 44:3; Sakh 13:1","MozV 30:6; Yer 31:33; 32:39","Faigi 6:9; 20:43","Faigi 17:24","Faigi 34:31"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 1, 'Ira''u ndra''o tanga Yehowa, ba i''ohe baero ndra''o Eheha Yehowa ba ba dalu ndraso ibe''e tebato ndra''odo, ba ndraso si no fahöna töla zi mate.', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 2, 'Ba ifatörö ndra''o, ufasui ibe''e. No fahöna tou ba ndraso, ba no oköli sibai.', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 3, 'Ba imane khögu: He ono niha, hadia, ifuli maö auri döla zi mate andrö! Ba utema linia, umane: He So''aya, Yehowa, ya''ugö zangila!', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 4, 'Ba imane khögu: Ama''ele''ö nitandrösaigö ba döla zi mate andrö, ömane: He ya''ami töla zi mate andrö, si no oköli, mifondrondrongo li Yehowa!', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 5, 'Da''ö niŵa''ö Zo''aya, Yehowa, ba döla zi mate andrö: Hiza, ufonoso dania ami, ena''ö ifuli auri ami.', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 6, 'Ufo''uo ami ba ufonagole ami, ba ufo''uli ami ba ufonoso ami, ena''ö auri ami, fa aboto ba dödömi, wa no ya''odo Yehowa.', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 7, 'Ba mama''ele''ö ndra''o, u''o''ö niŵa''ö khögu. Ba mururu, me mama''ele''ö ndra''o, ba murara ba te''anö''anö döla zi mate andrö.', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 8, 'Ba u''ila wa itugu mo''uo ba monagole ba tobalu uli. Ba lö''ö na bakha noso.', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 9, 'Ba imane khögu: Hede ba nangi, ama''ele''ö, ono niha, ömane ba nangi: Aine noso, moroi yöu ba moroi raya, moroi ba gatumbukha ba moroi ba gaekhula, hehaini nibunu andre, fangorifi!', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 10, 'Ba me mama''ele''ö ndra''o, me u''o''ö niŵa''ö khögu, ba monoso ira, auri ba maoso, muzizio ato sibai ira!', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 11, 'Ba imane khögu: He ono niha, ma''uwu Gizeraeli ma''afefu döla zi mate andre. So ösa zanguma''ö: No oköliköli dölama, lö tötönaföma sa''ae: si lö boto sa''ae ndra''aga!', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 12, 'Ba ama''ele''ö, ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ubokai lewatömi ba uhalö yaŵa ami, moroi ba lewatömi, ya''ami banuagu, ba u''ohe ba danö Ndraono Gizeraeli ami, ena''ö aboto ba dödömi,', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 13, 'wa no ya''odo Yehowa, na ubokai lewatömi, ba na uhalö yaŵa ami moroi ba lewatömi, ya''ami banuagu.', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 14, 'Ba ube''e barö dotomi noso andrö khögu, ena''ö ifuli auri ami; ba ba danömi u''ohe ami, ba aboto dania ba dödömi, wa no ya''odo Yehowa; no ya''odo zanguma''ö, ba ufalua göi, iŵa''ö Yehowa.', '[]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 15, 'Ba so niŵa''ö Yehowa khögu,', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 16, 'imane: He ono niha, halö zio, ba sura ba detenia: "Mado Yuda ba awöra Iraono Gizeraeli;" ba noa da''ö ba sara tö öhalö si''o ba ösura ba detenia: "Mado Yosefo, si''o Geferayi, ba awönia ma''uwu Gizeraeli ma''afefu".', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 17, 'Ba aefa da''ö, ba faböbö ira, ha sara si''o öbe''e, ena''ö ha sara ba dangau.[1]', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 18, 'Ba na lamane khöu iwami: Hadia, lö öbotokhi ba dödöma, hadia daniu wolau da''ö?', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 19, 'ba ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, uhalö zi''o mado Yosefo andrö, si so ba danga mado Geferayi ba ba danga nawönia, mado Ndraono Gizeraeli, ba u''orudugö ba zi''o mado Yuda, ena''ö ha sara si''o ba danga mado Yuda.', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 20, 'Ni''orudugö ba dangau zi''o andrö, nisuramö, ba zanehe ira.', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 21, 'Ba ömane khöra: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, uhalö Ndraono Gizeraeli, ba hunö niha baero, ba zi no larugi, u''ozaragö ira ba zi fasui misa ba u''ohe ira ba danöra.', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 22, 'Ba ha sambua soi dania ira ube''e, ba danö, ba hili Ndraono Gizeraeli, ba ha samösa razora, ya''ira fefu, böi sa''ae dombua soi ira ba böi sa''ae dua öri, böi si no fabali.[2]', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 23, 'Ba böi sa''ae lata''unöi ira ba nadu andrö khöra ba ba zogoro ita andrö khöra ba ba walimosara fefu; ba u''efa''ö ira ba wa''erosara andrö fefu, olalöŵara andrö, ba uhaogö ira, ena''ö ifuli banuagu ira, ba Lowalangira ndra''odo![3]', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 24, 'Ba razora genonigu Dawido, ba ya''ira fefu, ba ha samösa gubalora ba la''o''ö goroisagu, latöngöni nifakhoigu ba latörö.[4]', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 25, 'Ba la''iagö danö andrö, nibe''egu khö genonigu Yakobo, tanö ba zi so ira tuami mege; ba da''ö göi so ira, ba iraonora ba ma''uwura, irugi zi lö aetu, ba enonigu Dawido zalaŵara, si lö mamalö-malö.', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 26, 'Ba fawu''u li ndra''o khöra, fawu''usa li ba wa''atulö, fawu''usa li khöra, si lö tebulö, irugi zi lö aetu. Ba ufataro ira ba ato ira ube''e, ba ube''e ba hunöra bakha ni''amoni''ö andrö khögu, ba lö ubulö''ö.[5]', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 27, 'Ba yaŵara dania nahiagu, ba Lowalangira ndra''odo ba banuagu ira.', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476417, 'OT', 'Hezekieli', 37, 28, 'Ba aboto dania ba dödö niha baero, wa no ya''odo Yehowa, si amoni''ö Iraono Gizeraeli, na lö tebulö ba hunöra bakha ni''amoni''ö andrö khögu.', '["Yes 11:13; Yer 31:9","Hos 1:11; Yoh 10:16","Faigi 36:25 b.t. KorII 6:16","Yer 30:9; Faigi 11:20; 34:23 b. t","Sin 89:4; Yes 55:3"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 1, 'Ba so niŵa''ö Yehowa khögu,', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 2, 'imane: He ono niha, otahögö Gogi andrö ba danö Magogi, razo ba Rosi ba ba Mesekhi ba ba Dubala, ba ama''ele''ö nitandrösaigö khönia,[1]', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 3, 'ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ulau khöu, ya''ugö Gogi, razo ba Rosi ba ba Mesekhi ba ba Dubala, ba udönisi ndra''ugö,', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 4, 'ugaini zimbimö, u''ohe baero ndra''ugö, awö zabölö andrö khöu fefu, fabaya si fakudo, oi si no mangehao, fondrege zi sökhi nukha, ato sibai ira, samaluse ba sodange, sara wöda ba danga zamösana.[2]', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 5, 'Awöra Warasa ba Khusi ba Futi, oi samaluse ba sotetenaulu.[3]', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 6, 'Gomeri ba sabölö andrö khöra fefu ba ma''uwu Dogarima, fondrege yöu ba sabölö andrö khöra fefu — oya soi nawöu![4]', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 7, 'Angaro ba fa''anö fefu hadia ia khöu, ya''ugö ba sabölö andrö khöu, fefu, si no owulo khöu, ba iagö nitöngönira.', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 8, 'Na ara dania, ba teŵa''ö li khöu, ba götö na furi, ba örugi danö, si no mufadöni ba mbaŵa zi''öli [ba niha] si no mu''ozaragö ba niha baero misa, soya soi, si no mufataro ba hili Ndraono Gizeraeli, si no lö mamalö-malö, wa lö niha-niha mege; moroi ba niha baero te''ohe miyaŵa ira mege; ba dozi la''iagö danö, lö hadia ia.', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 9, 'Ba so ndra''ugö moroi sa, timba deu sabölö-bölö fabaya angi, timba lawuo ndra''ugö moroi sa, ba wangahawui tanö, na so''ö, ya''ugö ba sabölö andrö khöu fefu, ba soi soya, awöu.', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 10, 'Da''ö niŵa''ö Zo''aya, Yehowa: Na luo da''ö, ba so zi tesao ba dödöu ba si lö sökhi nikhoi dödöu,', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 11, 'ba ömane: "Da''usuwö zi fahalama, niha sahono-hono uhawui, niha si lö hadia ia; lö mu''öli nahiara, lö bawa göli ba lö lazi!"[5]', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 12, 'Ba wamaigi sahulu ndra''ugö, ba ba worabu, ba wolau ba gadudula andrö, si so niha zui, ba ba niha ni''ozaragö ba niha baero, niha sangalui ana''a, sowanua ba wusö danö.[6]', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 13, 'Seba ba Dedano ba saniaga andrö, banua Darisi ba ono zingo andrö khöra fefu, ba lamane khöu: Hadia, ba wamaigi sahulu ndra''ugö so''ö? Hadia ba worabu ö''owuloi zabölö khöu, ba wangoloi''ö firö ba ana''a, ba wolohe misa nibaya-baya, ahulua sebua?', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 14, 'Ba ama''ele''ö, ya''ugö ono niha, ömane khö Gogi andrö: Da''ö niŵa''ö Zo''aya, Yehowa: He wisa? Na luo ahono-hono ba danö mbanuagu Iraono Gizeraeli, na lö hadia ia khöra,', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 15, 'maoso ndra''ugö, ba so''ö moroi sa ba nahiamö ba wondrege yöu, ya''ugö ba soi soya andrö, awöu, oi si fakudo, ato sibai, ato zabölö,', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 16, 'ba moi''ö musuwö mbanuagu Iraono Gizeraeli, hulö lawuo, ba wangahawui tanö? Ba götö safuria andrö u''ohe miyaŵa ndra''ugö, ba wanuwö ba danögu, ena''ö aboto ba dödö niha baero ndra''odo, na u''oroma''ö ba khömö andrö, ya''ugö Gogi, wa ni''amoni''ö ndra''odo, ba zanehe ira.', '["MozI 10:2; Fam 20:8","RazII 19:28; Faigi 29:4","Faigi 27:10","Faigi 27:14","Sakh 2:4,5","Faigi 5:5"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 17, 'Da''ö niŵa''ö Zo''aya, Yehowa: Hadia, ya''ugö nitörö ligu me föna, nifa''ema genonigu sama''ele''ö andrö, ba Ndraono Gizeraeli, si no mama''ele''ö me luo da''ö, ha me uga fakhe wa''ara, wa u''ohe khöra ndra''ugö sanuwö ya''ira?[7]', '["Yes 24:21; Yer 30:23; Yoel 3:2","Sin 11:6"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 18, 'Ba na luo da''ö, na luo so Gogi, ba wanuwö Iraono Gizeraeli, iŵa''ö So''aya, Yehowa, ba humola wönugu ba nikhugu.', '["Yes 24:21; Yer 30:23; Yoel 3:2","Sin 11:6"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 19, 'Ba wa''aukhu dödögu ba ba galitö wa''abao dödögu andrö uŵa''ö ia: Si ndruhu, na luo da''ö, ba itörö danö Ndraono Gizeraeli siheu sabölö-bölö.', '["Yes 24:21; Yer 30:23; Yoel 3:2","Sin 11:6"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 20, 'Humisi dania fönagu gi''a ba nasi ba fofo ba dalu mbanua ba utu ndru''u ba danö ba kuö-kuö fefu, sanana ba danö, awö niha fefu ba guli danö; ba hili, ba adudu, ba kara sisindro, ba aso''a, ba öli kara fefu, ba adudu tou ba danö.', '["Yes 24:21; Yer 30:23; Yoel 3:2","Sin 11:6"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 21, 'Ba ba hili andrö khögu fefu, ba muhededo ba zi''öli famununia, iŵa''ö So''aya, Yehowa; dozi ira, ba faoma lalau khö nawöra zi''öli.', '["Yes 24:21; Yer 30:23; Yoel 3:2","Sin 11:6"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 22, 'Ba fahuhuodo khönia ba wökhö waba ba ba wa''aduwa ndro, ba deu sabölö-bölö ba ba deu kara; moteu alitö ba talö balera ia ba sabölö andrö khönia, awö soi soya andrö, awönia, ube''e.[8]', '["Yes 24:21; Yer 30:23; Yoel 3:2","Sin 11:6"]', NULL),
  (3476418, 'OT', 'Hezekieli', 38, 23, 'Ba u''oroma''ö, wa no sebua ndra''o, awö wa ni''amoni''ö ndra''o ba ufa''ele''ö ndra''o ba zanehe soi soya, ena''ö aboto ba dödöra, wa no ya''odo Yehowa.', '["Yes 24:21; Yer 30:23; Yoel 3:2","Sin 11:6"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 1, 'Ba ama''ele''ö, ya''ugö ono niha, nitandrösaigö khö Gogi andrö, ömane: Da''ö niŵa''ö Zo''aya, Yehowa: Hiza, ulau khöu, ya''ugö Gogi, Razo ba Rosi ba ba Mesekhi ba ba Dubala,', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 2, 'ba udönisi ndra''ugö ba ufasao''ö ba u''ohe miyaŵa ndra''ugö, moroi ba wondrege yöu, u''ohe ba hili Ndraono Gizeraeli ndra''ugö.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 3, 'Ba utimba ba dangau kabera wana ba ahele ba dangau kambölö nono wana ube''e.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 4, 'Ba hili Ndraono Gizeraeli mate ndra''ugö, ya''ugö ba sabölö andrö khöu fefu, awö soi bö''ö andrö awöu. Ba wofo sandra''undra''u andrö, ba zo''afi fefu ba ba gutu ndru''u ba danö utehe ndra''ugö, öra.[1]', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 5, 'Baero ba mbenua tegaölö tou ndra''ugö, me no ya''o zanguma''ö, iŵa''ö So''aya, Yehowa.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 6, 'Ba ugule''ö galitö ba Magogi ba ba zihene asi andrö, si lö fa''abu dödö, ena''ö aboto ba dödöra, wa no ya''odo Yehowa!', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 7, 'Ba terongo döigu ni''amoni''ö bakha ba hunö mbanuagu Iraono Gizeraeli ube''e, ba lö''ö sa''ae ube''e ni''o''aya döigu andrö, ni''amoni''ö, ena''ö aboto ba dödö niha baero, wa no ya''odo Yehowa, ni''amoni''ö ba Ndraono Gizeraeli.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 8, 'Hiza, itörö, alua, iŵa''ö So''aya, Yehowa: da''ö mbaŵa andrö niŵa''ögu.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 9, 'Ba möi baero dania zi so ba mbanua Ndraono Gizeraeli ba labe''e fangebua galitö ba fangasoso gö wangöna andrö, dange ba baluse ba fana ba ono wana ba bago gama ba toho, mewitu fakhe wa''ara labe''e fangebua galitö da''ö.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 10, 'Lö lahalö geu ba mbenua, lö la''obö ba gatua; fangöna andrö labe''e fangebua galitö ba larabu gama-gama zorabu, gama-gamara mege, ba lahalö gana''a zangai ana''ara mege, iŵa''ö So''aya, Yehowa.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 11, 'Ba na luo da''ö ba uhonogöi naha Gogi, naha lewatönia ba Ndraono Gizeraeli, ba ndraso zikoli andrö, tanö ba gatumbukha, na ta''otarai nasi; ba tobali ba''a-ba''a lala zikoli. Ba da''ö lako''o dania Gogi, fabaya sabölö andrö khönia fefu, ba labe''e töi ndraso andrö ndraso zato andrö khö Gogi.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 12, 'Ba fitu waŵa, wa''ara la''oko''o''ö ira Iraono Gizeraeli, ba wangehao tanö.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 13, 'Niha sato ba danö fefu zogo''o ya''ira, ba tobali fangebua döira, na luo ufa''ele''ö lakhömigu, iŵa''ö So''aya, Yehowa.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 14, 'Ba latutuyu dania niha, lafataro ba wanöröi tanö, ba wogo''o si tosai na tou ba danö, sikoli, ba wangehao tanö, na no aefa zi fitu wawa, ba la''aalu-alui.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 15, 'Ba na latöröi danö ba na so zangila töla niha, ba yamube''e dandra ba ngai, irege lako''o ba ndraso zato andrö khö Gogi sogo''o si mate andrö.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 16, 'Ba labe''e töi mbanua Hamona ("sato") Ba lahaogö danö ba zi manö.', '["Faigi 29:5; 32:4"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 17, 'Ba ya''ugö ono niha, da''ö niŵa''ö Zo''aya, Yehowa: Ömane ba wofo andrö so''afi, fefu ba ba gutu ndru''u ba mbenua, fefu: Mi''owuloi ami ba mi''aine, mifa''aso ami, moroi ba zi fasui fefu, ba wemanga zumange andrö ni''asogögu khömi, — sumange sebua ba hili Ndraono Gizeraeli, ba niami ösi ba ba nibadumi do.[2]', '["Yes 34:6; Fam 19:17"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 18, 'Ösi zabölö mi''a ba do zalaŵa ba guli danö mibadu: biri-biri si matua ba ono mbiri-biri ba nambi si matua ba ono zaŵi, awö nibula mbanua Mbazana fefu!', '["Yes 34:6; Fam 19:17"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 19, 'Ba tawö mi''a, irege abuso ami ba do mibadu, irege mabu ami, sumange andrö khögu, ni''asogögu khömi.', '["Yes 34:6; Fam 19:17"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 20, 'Ba wemanga khögu abuso ami kudo ba koreta ba sabölö ba sanuwö, ha niha ira, iŵa''ö So''aya, Yehowa.', '["Yes 34:6; Fam 19:17"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 21, 'Ba ufa''ele''ö ba niha baero lakhömigu andrö, ba dozi niha, ba la''ila huku andrö, nifatörögu, ba tangagu, fombambaya ya''ira.', '["Yes 34:6; Fam 19:17"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 22, 'Ba ba ma''uwu Gizeraeli, ba ya aboto ba dödö, wa no ya''odo Yehowa, Lowalangira, i''otarai luo da''ö, ba mitou dania.', '["Yes 34:6; Fam 19:17"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 23, 'Ba ba niha baero, ba ya aboto ba dödö, wa no lalö Ndraono Gizeraeli mbörö, wa no tetibo ira, — börö me no la''erogö ndra''odo; tobali ubini''ö mbawagu khöra, ba ube''e ira ba danga nemalira, ba tobali ahori mate ira ba mbawa zi''öli.', '["Yes 34:6; Fam 19:17"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 24, 'Dali ba wolaugu khöra wa''ara''iöra ba fangerogöra ya''odo, ba no ubini''ö mbawagu khöra.', '["Yes 34:6; Fam 19:17"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 25, 'Andrö wa imane So''aya, Yehowa: Iya''e, ba u''ohe mangawuli ni''oloi''ö andrö, ma''uwu Yakobo, ba uhakhösi tödö Ndraono Gizeraeli fefu, ba amaedola zolohu ndra''o, ba döigu andrö ni''amoni''ö.[3]', '["Faigi 16:61; 20:43; 36:31","Faigi 36:25; Yoel 2:28"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 26, 'Ba akha olifu ira wa''ailara andrö ba fangerogöra ya''odo fefu, na ahono zui ira ba danö, lö hadia ia, lö si keani ya''ira.', '["Faigi 16:61; 20:43; 36:31","Faigi 36:25; Yoel 2:28"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 27, 'Na u''ohe mangawuli ira, moroi ba niha baero, ba na u''ozaragö ira ba danö nemalira; ba ufa''ele''ö ba khöra andrö, wa no ni''amoni''ö ndra''o, ba zanehe niha baero, soya soi,', '["Faigi 16:61; 20:43; 36:31","Faigi 36:25; Yoel 2:28"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 28, 'ena''ö aboto ba dödöra, wa no ya''odo Yehowa Lowalangira, me noa sa utibo''ö ira ba niha baero misa, ba me no ufuli u''ozaragö ira ba danöra; samösa lö uröi furi ba da''ö.', '["Faigi 16:61; 20:43; 36:31","Faigi 36:25; Yoel 2:28"]', NULL),
  (3476419, 'OT', 'Hezekieli', 39, 29, 'Ba lö''ö sa''ae ubini''ö mbawagu khöra, me no ulau Gehehagu ba ma''uwu Gizeraeli, iŵa''ö So''aya, Yehowa.[4]', '["Faigi 16:61; 20:43; 36:31","Faigi 36:25; Yoel 2:28"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 1, 'Ba ndröfi si dua wulu a lima, aefa te''oloi''ö ndra''aga, me böröta ndröfi, ba zi mewulu ba mbawa si föföna, meweleöfa fakhe aefa atu''a zanuwö ba Yeruzalema, — me luo da''ö ituyu ndra''o tanga Yehowa, ba i''ohedo ba da''ö.[1]', '["MozII 12:2,3; Faigi 33:21","Faigi 8:3","Faigi 1:4; Dan 10:6; Fam 11:1; 21:15"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 2, 'Ba gangilata soroi ba Lowalangi i''ohedo ba danö Ndraono Gizeraeli ba itou''ö tou ndra''o ba hili salaŵa; ba ba da''ö, ba no so ba gametahögu zi hulö mbanua nitaru''ö.[2]', '["MozII 12:2,3; Faigi 33:21","Faigi 8:3","Faigi 1:4; Dan 10:6; Fam 11:1; 21:15"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 3, 'Ba me no i''ohedo ba da''ö, ba oroma niha, hulö döla garamba wamaigigu, sinali tarafali ba helo ba dangania; ba singa mbawa göli so ia.[3]', '["MozII 12:2,3; Faigi 33:21","Faigi 8:3","Faigi 1:4; Dan 10:6; Fam 11:1; 21:15"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 4, 'Ba humede khögu niha andrö, imane: He ono niha, nehegö ba fondrondrongo ba töngöni fefu ni''oroma''ögu khöu. Ba da''ö te''ohe ndra''ugö ba da''e, ena''ö la''oroma''ö khöu; ba ahori ö''ombakha''ö ba ma''uwu Gizeraeli ni''ilau!', '["MozII 12:2,3; Faigi 33:21","Faigi 8:3","Faigi 1:4; Dan 10:6; Fam 11:1; 21:15"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 5, 'Ba hiza göli kara baero gosali, fasui, ba so helo ba danga niha andrö, ono hela wa''anau, sahe-sahela a lalu''a hela andrö. Ba isu''a wa''ebolo nomo andrö: sahelo, ba fa''alaŵa, ba sahelo göi.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 6, 'Ba möi ia bakha ba mbawa göli, si otahögö atumbukha luo; möi ia miyaŵa ba mbosinia ba isu''a doyo mbawa göli: sahelo wa''ebolo, sara toyo ba sahelo wa''ebolo,', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 7, 'ba si hulö mbate''e side-ide andrö, ba sahelo wa''anau ba sahelo wa''ebolo, ba otalua zi hulö mbate''e side-ide andrö, ba lima hela, ba toyo mbawa göli ba ngai gewe''ewe ba mbawa göli andrö, tanö bakha, ba no sahelo.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 8, 'Ba isu''a gewe''ewe andrö, ba mbawa göli, tanö bakha, ba sahelo.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 9, 'Ba isu''a gewe''ewe andrö ba mbawa göli, ba no ŵalu hela, ba ehomonia, ba dua hela; ba ewe''ewe andrö ba mbawa göli, ba no mibakha.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 10, 'Ba si hulö mbate''e side-ide andrö ba mbawa göli, si otahögö atumbukha luo, ba tölutölu, fatambai. No fagölö-gölö wa''ebua zi tölu andrö; ba si manö göi gehomo andrö fatambai: no fagölö-gölö wa''ebua.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 11, 'Ba isu''a wa''ebolo mbawa göli, ba no fulu hela; fa''anau mbawa göli, ba feledölu hela.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 12, 'Ba föna zi hulö mbate''e side-ide andrö, ba so darali, sahe-sahela darali andrö, fatambai; ba si hulö mbate''e andrö, ba önö''önö hela, fatambai.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 13, 'Ba isu''a mbawa göli, i''otarai zagö mbate''e si sambua, numalö ba zagö zi sambua: dua wulu a lima hela wa''ebolo, no fatahö mbawandruhö.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 14, 'Ba ewe''ewe andrö, ba dua wulu, ba bate''e andrö ba mbawa göli, ba no mibaero ba golayama, fasui.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 15, 'Ba i''otarai föna mbawa göli, lala mibakha, irugi föna gewe''ewe ba mbawa göli tanö bakha, ba no lima wulu hela.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 16, 'Ba bawa göli, ba no fasui zandrela, si no ahole ba wangotahögö si hu''ö mbate''e andrö ba ehomonia andrö, tanö bakha, ba si manö göi gewe''ewe andrö, no fasui zandrela, mibakha, ba ba gehomo andrö, ba famaedo nohi.[4]', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 17, 'Ba i''ohedo bakha, ba golayama tanö baero. Ba so mbate''e ba da''ö, ba no mulau mbale ba golayama, fasui; tölu ngafulu mbate''e side-ide ba zinga mbale andrö.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 18, 'Ba ngai mbawa göli so mbale andrö, dali wa''anau mbawa göli, bale tanö tou andrö.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 19, 'Ba isu''a wa''ebolo golayama, i''otarai föna mbawa göli tanö tou, irugi wondrege golayama tanö bakha: otu hela tanö ba gatumbukha luo ba tanö miyöu.', '["RazI 6:4"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476420, 'OT', 'Hezekieli', 40, 20, 'Ba bawa göli ba golayama tanö baero, si otahögö tanö miyöu, ba isu''a, fa''anau ba fa''ebolo.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 21, 'Ba si hulö mbate''e side-ide ba da''ö, ba tölutölu, no fatambai, ba ehomonia ba ewe''ewenia, ba no falaŵalaŵa ba mbawa göli no mege; lima wulu hela wa''anau ba dua wulu a lima hela wa''ebolo.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 22, 'Ba sandrelania ba ewe''ewenia ba famaedo nohi andrö, ba no falaŵa ba mbawa göli andrö, si otahögö tanö ba gatumbukha luo; fitu bosi lala miyaŵa khönia, ba fönania gewe''ewenia andrö.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 23, 'Ba bawa göli ba golayama tanö bakha, ba no faudu ba mbawa göli tanö miyöu ba ba mbawa göli tanö ba gatumbukha luo. Ba isu''a, i''otarai mbawa göli si sambua, numalö ba zi sambua: otu hela.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 24, 'Ba i''ohedo miraya; ba so ba da''ö mbawa göli si otahögö tanö miraya. Ba isu''a gehomonia ba ewe''ewenia, ba no falaŵalaŵa ba zu''a-su''a no mege.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 25, 'Ba no mosandrela, si mane ewe''ewenia göi, fasui, si mane sandrela no mege; lima wulu hela wa''anau ba dua wulu a lima hela wa''ebolo.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 26, 'Ba fitu bosi lala miyaŵa khönia, ba fönania gewe''ewenia. Ba so wamaedo nohi, sagesageu, fatambai, ba gehomonia.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 27, 'Ba sambua mbawa göli ba golayama tanö bakha, si otahögö tanö miraya, ba isu''a, i''otarai mbawa göli si sambua, numalö ba zi sambua, miraya: otu hela.', '["RazI 6:4"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 28, 'Ba i''ohedo ba golayama tanö bakha, ifatörödo, ba mbawa göli tanö miraya ba isu''a mbawa göli tanö miraya ba zu''a-su''a no mege,', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 29, 'ba si hulö mbate''e side-ide andrö ba ehomonia ba ewe''ewenia, ba zu''a-su''a da''ö göi. Ba no mosandrela, si mane ewe''ewenia göi, fasui; lima wulu hela wa''anau ba dua wulu a lima hela wa''ebolo.', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 30, 'Ba no mo''ewe''ewe, fasui, dua wulu a lima hela wa''anau ba lima hela wa''ebolo.', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 31, 'Ba ewe''ewenia, ba no tanö ba golayama tanö baero, ba ba gehomonia, ba famaedo nohi, ba ŵalu bosi lala miyaŵa.', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 32, 'Ba i''ohedo ba mbawa göli, tanö ba gatumbukha luo, ba isu''a mbawa göli andrö, ba zu''a-su''a no mege.', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 33, 'Ba bate''e side-ide andrö ba ehomonia, ba ewe''ewe andrö khönia, ba no falaŵalaŵa göi, ba no mosandrela, si mane ewe''ewe andrö khönia, fasui; lima wulu hela wa''anau ba dua wulu a lima hela wa''ebolo.', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 34, 'Ba ewe''ewenia, ba i''otahögö golayama tanö baero, ba famaedo nohi ba gehomonia, faoma fatambai; ŵalu bosi lala miyaŵa khönia.', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 35, 'Ba i''ohedo ba mbawa göli tanö yöu ba isu''a,', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 36, 'ba zu''a-su''a no mege, bate''e side-ide andrö khönia ba ehomonia ba ewe''ewenia, ba no mosandrela, fasui; lima wulu hela wa''anau ba dua wulu a lima hela wa''ebolo.', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 37, 'Ba ewe''ewenia, ba i''otahögö golayama tanö baero, ba famaedo nohi ba gehomonia, fatambai; ŵalu bosi lala miyaŵa khönia.', '[]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 38, 'Ba so mbate''e; ba gewe''ewe mbawa göli andrö so mbawandruhönia, naha ba wanasai sumange nitunu.', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 39, 'Ba barö gewe''ewe mbawa göli andrö, ba no dombudombua meza, no fatambai, naha ba wanaba sumange nitunu ba sumange fameta horö ba sumange ogauta.', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 40, 'Ba ba zinga mbagolö tanö baero, tanö miyöu, na so zanörö bawa göli miyaŵa, ba no dombua meza, ba ba zinga mbagolö ba zi tambai, ba gewe''ewe mbawa göli, ba dombua göi meza; öfa''öfa meza,', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 41, 'no fatambai, ba zinga mbagolö mbawa göli andrö; ŵalu meza naha ba wanabanaba sumange.', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 42, 'Öfa meza ba zumange nitunu, kara, si öfa sagi, sahela a matonga wa''anau ba sahela a matonga wa''ebolo ba sahela wa''alaŵa, ba wanou''ö ba da''ö fakake andrö, nifake ba wanaba sumange nitunu ba sumange nitaba.', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 43, 'Ba no mufosinga mibakha, lalu''a wa''ebolo, fasui, ba ba meza andrö labe''e-be''e nösi zumange andrö.', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 44, 'Ba föna mbawa göli tanö bakha, ba so mbate''e, nahia zanunö ba golayama tanö bakha, sambua ba zinga mbagolö mbawa göli tanö yöu, ba i''otahögö danö miraya, ba sambua ba zinga mbagolö mbawa göli tanö ba gatumbukha luo, si otahögö tanö miyöu.', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 45, 'Ba imane khögu: Bate''e andre, si otahögö tanö miraya, ba moguna nahia gere, sangai-ngai halöŵö bakha ba gosali.', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 46, 'Ba bate''e andrö, si otahögö tanö miyöu, ba moguna nahia gere, sangai-ngai halöŵö ba naha wame''e sumange. Ma''uwu Zadoki da''ö; ha da''ö ma''uwu Lewi si tola mangahatö''ö ya''ira khö Yehowa, ngoni-ngoninia.[5]', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 47, 'Ba isu''a golayama andrö: otu hela wa''anau ba otu hela wa''ebolo, si öfa sagi. Ba föna gosali so naha wame''e sumange.[6]', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 48, 'Ba i''ohedo ba gewe''ewe gosali, ba isu''a gewe''ewe gosali andrö, lima hela dambai, ba fa''ebolo mbawa göli, ba feleöfa hela, ba bagolö mbawa göli, ba no tölu hela dambai.[7]', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476420, 'OT', 'Hezekieli', 40, 49, 'Fa''anau gewe''ewe andrö, ba dua wulu hela, ba fa''ebolo, ba felendrua hela, ba fulu bosi lala miyaŵa khönia. Ba ba ngai gehomo andrö, ba so zi hulö daru nahe, faoma fatambai.[8]', '["Faigi 43:19; 44:15; RazI 1:8,39; Nga''ötI 5:34","Faigi 43:13","RazI 6:3","RazI 7:21"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 1, 'Ba i''ohedo bakha ba nösi gosali ba isu''a gehomo: önö''önö hela wa''ebolo, faoma fatambai.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 2, 'Ba fa''ebolo mbawandruhö, ba no fulu hela, ba bagölö kara andrö ba mbawandruhö, ba lima hela dambai. Ba isu''a wa''anau: öfa wulu hela, ba fa''ebolo: dua wulu hela.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 3, 'Ba möi ia bakha ba isu''a gehomo ba mbawandruhö: dua hela, ba fa''ebolo mbawandruhö, önö hela, ba bagolö fatambai mbawandruhö: fitu hela dambai.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 4, 'Ba isu''a wa''anau: dua wulu hela, ba fa''ebolo: dua wulu hela, föna gosali. Ba imane khögu: Da''ö wondrege ni''amoni''ö andrö![2]', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 5, 'Ba isu''a mbagolö gosali: önö hela, ba fa''ebolo zahe-sahe andrö: öfa hela si fasui osali.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 6, 'Ba bate''e ba ngai, ba no te''oli, medölu wa tölu ngafulu, no monga''ötö, ba tehandro ba mbagolö, bagolö gosali tanö ba mbate''e andrö, fasui, ba wangabe''e, ba lö''ö sa mufakhai ba mbagolö.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 7, 'Ba ebolo, tedou miyaŵa; tedou nösi ba nga''ötö miyaŵa, fasui, ba gosali, tobali ebolo nösi mbate''e andrö, tanö miyaŵa. Ba so lala, i''otarai zi sagötö tanö tou, numalö ba zi sagötö ba dalu ba ba zi sagöto tanö yaŵa.[3]', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 8, 'Ba u''ila mbosi ba gahe gosali, fasui: toyo mbate''e ba ngai andrö: sahelo; önö hela irugi nindrotoi andrö.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 9, 'Ba fa''awe''e-we''e mbagolö kara andrö ba mbate''e andrö, tanö baero, ba no lima hela; ba otalua mbate''e ba ngai andrö, ba gosali.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 10, 'Ba bate''e andrö, ba no mo''otalua, dua wulu hela, si fasui ba gosali.[4]', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 11, 'Ba bawandruhö ba mbate''e andrö, ba i''otahögö zi lö bate''e; sambua mbawandruhö miyöu ba sambua miraya, ba fa''ebolo zi lö bate''e, ba no lima hela, fasui.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 12, 'Ba ösi nomo, föna newali ni''oniagö andrö, ba watalinga, tanö ba gaekhula luo, ba fitu ngafulu hela wa''anau, ba fa''ebolo mbagolö kara, ba nomo andrö, ba no lima hela, fasui, ba fa''anau, ba siŵa wulu hela.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 13, 'Ba isu''a nomo andrö: otu hela wa''anau ba olayama ni''oniagö andrö ba omo andrö, awö mbagolö kara ba no otu hela wa''anau.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 14, 'Ba fa''ebolo nomo, tanö föna, fabaya olayama ni''oniagö andrö, tanö ba gatumbukha luo, ba no otu hela göi.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 15, 'Ba isu''a wa''anau nomo andrö, tanö ba golayama ni''oniagö andrö ba geronia, ba hareharenia fatambai: otu hela. Ba ba nösi gosali andrö, awö nifosagö andrö, ba golayama,', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 16, 'ba no eu nihaogö fokata zilötö ba sandrela nifotarali andrö, awö lesi, ba zi tölu nahia, föna zilötö andrö, fasui manö. I''otarai danö, irugi zandrela — ba sandrela, ba no muduhö, —', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 17, 'irugi yaŵa mbawandruhö ba irugi gosali tanö bakha, ba baero ba ba mbagolö fefu, fasui, bakha ba baero, ba so zu''a-su''a.', '["Faigi 43:12","RazI 6:6,8","Faigi 42:1–3"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 18, 'Ba no mulau wamaedo Kerubi ba famaedo nohi, sagesageu nohi ba gotalua zi dombudombua Kerubi. Ba si dombudombua bawa Kerubi andrö: Si sambua,', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 19, 'ba bawa niha, si otahögö ohi ba zi tambai, ba si sambua, ba bawa zingo, si otahögö ohi ba zi tambai, ba nomo andrö ma''asambua, fasui.', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 20, 'I''otarai danö, irugi yaŵa mbawandruhö so wamaedo Kerubi andrö ba famaedo nohi; ba mbagölö.', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 21, 'Ba ehomo gosali, ba si öfa sagi. Ba föna ni''amoni''ö, ba so zi hulö naha wame''e sumange, wamaigida, naha wame''e sumange eu,', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 22, 'tölu hela wa''alaŵa; fa''anaunia, ba dua hela, ba fa''ebolonia, ba dua hela göi; ba no motalinga, ba ahenia, awö ngainia, ba eu. Ba imane khögu: Da''ö meza andrö, si so föna Yehowa.[5]', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 23, 'Ba dombua mbawandruhö ba nomo osali andrö ba ba ni''amoni''ö.', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 24, 'Ba dua-dua görö lagö mbawandruhö, lagö nifuyu''ö; dua görö ba zi sambua ba dua görö göi ba zi sambua.[6]', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 25, 'Ba ba mbawandruhö gosali andrö, ba no mulau wamaedo Kerubi ba famaedo nohi, si mane nilau ba mbagolö misa, ba so lesi eu, baero,', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476421, 'OT', 'Hezekieli', 41, 26, 'föna gewe''ewe andrö, ba sandrela nifotarali ba famaedo nohi, faoma fatambai ba mbagolö gewe''ewe.', '["MozII 30:1–10","RazI 6:34"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 1, 'Ba i''ohedo baero ba golayama baero, tanö miyöu. Ifasaodo ba mbate''e andrö, ba gamaudu ni''oniagö andrö ba ba gamaudu nomo no mege,', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 2, 'tanö miyöu; ba mbawa duasania, otu hela wa''anaunia, tanö miyöu; ba fabolo, ba lima wulu hela.[1]', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 3, 'Ba ba gamaudu zi dua wulu hela andrö, ba golayama tanö bakha, ba föna mbale andrö, ba golayama baero, ba no fatahö harehare, tölu nga''ötö.[2]', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 4, 'Ba föna mbate''e andrö, ba so lala, fulu hela wa''ebolo, tanö ba golayama bakha, otu hela wa''anau, ba tanö miyöu mbawandruhö.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 5, 'Ba bate''e tanö yaŵa, ba no oböda, noa sa naha harehare da''ö, moroi tanö tou ba ba dalu.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 6, 'Noa sa tölu nga''ötö, ba lö ehomo, si mane ehomo ba golayama andrö; andrö wa no aböda [tanö yaŵa], ebolo tanö tou ba ba dalu, moroi tou ba danö.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 7, 'Ba öli kara andrö, ba dali mbate''e andrö, tanö ba golayama baero, föna mbate''e andrö, ba no lima wulu hela wa''anau.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 8, 'Me no lima wulu hela göi wa''anau mbate''e andrö, tanö ba golayama baero; ba hiza ba gamaudu gosali, ba otu hela.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 9, 'Ba tou mbate''e andrö sa lala mibakha, tanö ba gatumbukha luo, ba ta''otarai golayama baero, we''amöi bakha,', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 10, 'ba mbolo göli kara andrö, ba golayama. Ba tanö ba gatumbukha luo, föna ni''oniagö andrö ba föna nomo andrö, ba so [göi] mbate''e.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 11, 'Ba föna da''ö, ba so lala, si mane bate''e andrö, wamaigida, bate''e tanö miyöu; fa''anau ba fa''ebolo, ba no si mane ba da''ö, ba bawandruhö fefu ba wamazökhi, ba no fagölö-gölö ba da''ö.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 12, 'Ba no si mane bawandruhö mbate''e andrö, tanö miraya, sambua mbawandruhö ba mbawa lala, lala föna göli kara andrö, si ohia''ö ya''ia, tanö ba gatumbukha luo, na möi bakha.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 13, 'Ba imane khögu: bate''e andrö tanö yöu ba bate''e tanö raya, föna ni''oniagö andrö, ba no bate''e ni''amoni''ö andrö, nahia gere si tola mangahatö''ö ya''ira khö Yehowa, ba wemanga wondrege ni''amoni''ö andrö. Ba da''ö labe''e wondrege ni''amoni''ö andrö ba he sumange ni''a ba sumange fameta horö ba sumange ogauta; me no ni''amoni''ö naha andrö.[3]', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 14, 'Ba na möi bakha gere — ba lö tola möi ira ba golayama baero, la''otarai ni''amoni''ö andrö — ba labe''e ba da''ö nukhara, nukhara ba halöŵöra andrö, me no ni''amoni''ö da''ö, ba la''onukha nukha bö''ö, ba awena lasaŵa nahia zato.', '["Faigi 41:13","Faigi 41:10; 40:17","MozIII 21:22"]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 15, 'Ba me no awai isu''a nomo andrö tanö bakha, ba i''ohedo baero, masaŵa mbawa göli, si otahögö tanö ba gatumbukha luo, ba isu''a baero, ifasui.', '[]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 16, 'Isu''a tanö ba gatumbukha luo, helo andrö: 500 helo, ba helo andrö, fasui.', '[]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 17, 'Ba isu''a tanö yöu: 500 helo, ba helo andrö,', '[]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 18, 'fasui; ba isu''a tanö raya: 500 helo, ba helo andrö.', '[]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 19, 'Ba ifasui, isaŵa danö ba gaekhula luo, 500 helo,', '[]', NULL),
  (3476422, 'OT', 'Hezekieli', 42, 20, 'ba helo andrö: saginia si öfa [fefu] isu''a. No tefasui öli kara: 500 wa''anau ba 500 wa''ebolo, ba wangoniagö ni''amoni''ö ba zi tenga ni''amoni''ö.', '[]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 1, 'Ba i''ohedo ba mbawa göli andrö tanö ba gatumbakha luo.', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 2, 'Ba hiza, ba to''ele lakhömi Lowalangi Ndraono Gizeraeli, moroi ba gatumbukha luo, no timba wegoso-goso nidanö sebua we''ugu-ugunia, ba humaga danö ba lakhöminia andrö.[1]', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 3, 'Ba famaigigu andrö, ba no timba wamaigigu me föna, me to''ele ia ba wamakiko banua; ba famaigigu kureta andrö, ba no si mane famaigi ba mbewe Gebara no; ba ufalögu tou ndra''odo.[2]', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 4, 'Ba isaŵa gosali lakhömi Yehowa, itörö mbawa göli andrö, si otahögö atumbukha luo.[3]', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 5, 'Ba ifazaŵa ndra''o Eheha ba i''ohedo ba golayama bakha, ba hiza, ba no anönö gosali lakhömi Yehowa.[4]', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 6, 'Ba urongo li zihede khögu, si otarai gosali; ba no so na ba ngaigu niha andrö,', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 7, 'imane khögu: He ono niha! Hadia, no ö''ila naha dadaomagu andrö, awö naha lalu''a kahegu, nahiagu ba hunö Ndraono Gizeraeli, si lö tebulö? Ba böi sa''ae labe''e ma''uwu Gizeraeli ra''i-ra''iö döigu andrö ni''amoni''ö, — ya''ira andrö ba razora, ba wame''e-me''era adu ba ba hili-hili andrö khöra ba ba mboto razora si no mate,[5]', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 8, 'me lafaedo zilötöra ba zilötö khögu ba ehomo khöra ba gehomo khögu, tobali ha bagolö gotaluama; ba lö mamalö-malö wa ra''ira''ö döigu andrö, ni''amoni''ö, labe''e, ba zogoro ita andrö khöra, nilaura, ba no tobali uhori ira ba wönugu andrö.[6]', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 9, 'Ba iya''e, ba lö''ö sa''ae lahatö''ö khögu wame''e-me''era adu andrö ba he boto zi mate andrö, boto razora, ena''ö lö mamalö-malö u''iagö ba khöra.', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 10, 'Ba ya''ugö ono niha, ba ötanö ba zura nibe''e ba ma''uwu Gizeraeli, he wisa gosali andrö, ena''ö aila ira golalöŵara andrö, ba akha lasu''a göi nomo andrö?[7]', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 11, 'Ba na aila ira nilaura andrö fefu, ba botokhi ba dödöra he wisa gosali andrö, he wisa wolau ya''ia ba he lala ba we''amöi baero, awö lala ba we''amöi bakha ba amuatania fefu, ba he wisa wame''e ya''ia fefu ba hadia nifakhoi ba khönia ba oroisa fefu, ba tanö ba zura, ba zanehe ira, ena''ö latöngöni he wisa wolau ya''ia, ba hadia gamakhoita, ba ena''ö la''o''ö.', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 12, 'Si mane wame''e osali andrö: ba zuzu hili andrö, ba ni''amoni''ö sibai nahania andrö fefu, fasui. Hiza, da''ö nifakhoi ba gosali andrö.', '["Faigi 1:24; 11:23","Faigi 8–11; Faigi 1:4","Faigi 11:22,23; 10:19","MozII 40:34; RazI 8,10,11","Sin 132:7,13,14; 99:5; Nga''ötI 28:2; Yes 66:1","Faigi 8:7–18","Faigi 16:61,63; 36:32"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 13, 'Ba da''ö wa''ebua naha wame''e sumange andrö ba hela, ba sahela, ba no sahela a lalu''a: Toyonia, ba no sahela, ba sahela wa''ebolo; ba lesinia ba zinga, ba lito, fasui. Ba da''ö wa''alaŵa naha wame''e sumange andrö:[8]', '["Faigi 40:47; MozII 27:1–8","MozII 27:2; Yes 29:1"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 14, 'I''otarai doyo andrö tou, irugi lesi andrö, tanö tou, ba dua hela, ba fa''ebolo, ba sahela; ba i''otarai lesi side-ide andrö, irugi lesi sebua, ba öfa hela, ba sahela wa''ebolo.', '["Faigi 40:47; MozII 27:1–8","MozII 27:2; Yes 29:1"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 15, 'Ba farikhi andrö ba zumange, ba öfa hela, ba farikhi andrö, ba sotandru miyaŵa, öfa dandru.', '["Faigi 40:47; MozII 27:1–8","MozII 27:2; Yes 29:1"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 16, 'Ba farikhi, ba felendrua hela wa''anau ba felendrua hela wa''ebolo, no si öfa sagi, si fagölö-gölö.[9]', '["Faigi 40:47; MozII 27:1–8","MozII 27:2; Yes 29:1"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 17, 'Ba lesi andrö, ba feleöfa hela wa''anau ba feleöfa wa''ebolo, saginia andrö si no fagölö-gölö, ba tarali, fasui, ba matonga hela. Ba toyo andrö, fasui, ba sahela. Ba nibosi andrö, ba no tanö ba gatumbukha luo.', '["Faigi 40:47; MozII 27:1–8","MozII 27:2; Yes 29:1"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 18, 'Ba imane khögu: He ono niha! Da''ö niŵa''ö Zo''aya, Yehowa: Da''ö nihonogöi ba naha wame''e sumange andrö, na luo wama''anö ya''ia, ba wame''e sumange nitunu ba detenia, ba ba wanefe ya''ia do.', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 19, 'Ba öbe''e ba danga gere andrö, ma''uwu Lewi, nga''ötö Zadoki, si tola mangahatö''ö ya''ira khögu, iŵa''ö So''aya, Yehowa, ba wamosumange ya''o öbe''e ba dangara nono zaŵi, sumange fameta horö.[10]', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 20, 'Ba öhalö ndronia ösa, ba ögule''ö ba dandru wame''e sumange andrö, si öfa, ba watalinga lesi andrö, si öfa ba ba darali, fasui, fameta sala ba khönia ba ogauta.', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 21, 'Ba aefa da''ö, ba öhalö nono zaŵi andrö, sumange fameta horö, ena''ö latunu ia ba naha nihonogöi andrö, baero ni''amoni''ö.[11]', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 22, 'Ba mahemolu ö ba öbe''e sumange fameta horö nambi si matua, si lö si sala, fameta zala ba naha wame''e sumange, si mane me labe''e fameta zala ba hönia nono zaŵi andrö.', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 23, 'Ba na no o''o''ozui wameta sala andrö, ba öbe''e sumange nono zaŵi si matua, si lö si sala, sara, ba sageu göi zi matua mbiri-biri si lö si sala.', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 24, 'Ö''ohe föna Yehowa, ba lalau yaŵa nasio ere ba labe''e sumange Yehowa, sumange nitunu.[12]', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476423, 'OT', 'Hezekieli', 43, 25, 'Fitu bongi wa''ara, ba sageu ma''ökhö öbe''e si matua nambi, sumange fameta horö, ba sara göi nono zaŵi, si matua, labe''e, ba sageu mbiri-biri si matua, si lö si sala.', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 26, 'Fitu bongi wa''ara lahetaheta zala ba naha wame''e sumange ba lahaogö ia ba la''amoni''ö.[13]', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476423, 'OT', 'Hezekieli', 43, 27, 'Ba si manö wa''ahöwö mbongi andrö khöra; ba na luo si ŵalu ba na aefa da''ö, ba labe''e zumange nitunu andrö khömi, ba sumange nitaba, ere, ba naha wame''e sumange andrö, ba uhakhösi tödö ami, iŵa''ö So''aya, Yehowa.', '["MozII 29; Faigi 40:46","MozIII 16:27","MozIII 2:13","MozII 28:41"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 1, 'Ba i''ohe mangawuli ndra''o, masaŵa mbawa göli ba ni''amoni''ö, bawa göli baero si otahögö atumbukha luo; ba si no mukusi da''ö.', '["Faigi 43:4","Faigi 45:7, MozII 29:32","Faigi 43:5","MozIII 3:17"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 2, 'Ba imane khögu Yehowa: Böi tebulö nikusi mbawa göli andre, böi labokai. Lö tola itörö niha; me no itörö ia Yehowa, Lowalangi Ndraono Gizeraeli, we''amöi bakha, andrö wa lö labokai ia.[1]', '["Faigi 43:4","Faigi 45:7, MozII 29:32","Faigi 43:5","MozIII 3:17"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 3, 'Ba razo zidadao ba da''ö, ba wemanga andrö, föna Yehowa. Ba gewe''ewe mbawa göli andrö itörö we''amöi bakha, ba da''ö göi lalania ba wangawuli.[2]', '["Faigi 43:4","Faigi 45:7, MozII 29:32","Faigi 43:5","MozIII 3:17"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 4, 'Ba i''ohedo tanö ba mbawa göli yöu, föna gosali; ba u''ila wa''anönö gosali Yehowa lakhömi Yehowa, ba ufalögu tou ndra''odo.[3]', '["Faigi 43:4","Faigi 45:7, MozII 29:32","Faigi 43:5","MozIII 3:17"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 5, 'Ba imane khögu Yehowa: He ono niha, töngöni ba faigi höröu ba fondrondrongo tögi dalingamö fefu niŵa''ögu khöu iya''e, ba nihonogöi andrö fefu, ba gosali Yehowa, awö nifakhoi ba khönia, fefu; töngöni lala ba we''amöi bakha ba gosali, awö lala we''amöi baero, na la''otarai ni''amoni''ö andrö.', '["Faigi 43:4","Faigi 45:7, MozII 29:32","Faigi 43:5","MozIII 3:17"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 6, 'Ba ömane ba zabe''e tandro andrö, ba ma''uwu Gizeraeli: Da''ö niŵa''ö Zo''aya, Yehowa: No abönö wa''ara wolau-laumi sogoro ita andrö khömi,', '["Faigi 43:4","Faigi 45:7, MozII 29:32","Faigi 43:5","MozIII 3:17"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 7, 'ya''ami ma''uwu Gizeraeli, me no mi''ohe bakha niha bö''ö, si lö muboto tödö, ba he ösi, me no mitehe so ira ba ni''amoni''ö andrö khögu, ba wango''aya osali khögu, na mibe''e gögu, tawö ba do, ba tobali midudugö wawu''usa li andrö khögu, nönö-nönö zogoro ita andrö khömi, fefu.[4]', '["Faigi 43:4","Faigi 45:7, MozII 29:32","Faigi 43:5","MozIII 3:17"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 8, 'Ba no lö mi''o''ö nifakhoi ba ni''amoni''ö andrö khögu; nikhoi dödömi zi no mibe''e dali a''ine, ba wamataro sanaro ba ni''amoni''ö andrö khögu.', '["Faigi 43:4","Faigi 45:7, MozII 29:32","Faigi 43:5","MozIII 3:17"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 9, 'Da''ö niŵa''ö Zo''aya, Yehowa: Lö tola möi bakha ba ni''amoni''ö andrö khögu niha bö''ö si lö muboto tödö ba si lö muboto ösi, — niha bö''ö andrö fefu, si no fatewu ba Ndraono Gizeraeli.', '["Nga''ötI 23:28"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 10, 'Ono Lewi a''ine, si no mangerogö ya''odo, me elungu Ndraono Gizeraeli, me no laröi ndra''odo, wame''e-me''e adu andrö khöra, fa''elungu, da''ö zolui lalöra andrö.', '["Nga''ötI 23:28"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 11, 'Ba sangai-ngai halöŵö ba ni''amoni''ö andrö khögu ira, sanaro ba mbawandruhö gosali ba ngoni-ngoni ba gosali; sanabanaba sumange nitunu ba sumange nitaba ira, sumange nibe''e zato; la''iagö sanolo ya''ira, ngoni-ngonira.[5]', '["Nga''ötI 23:28"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 12, 'Me no möi ira ngoni-ngonira ba nadura andrö [föna], ba me no tobali tandraŵa golalöŵa ira ba ma''uwu Gizeraeli, andrö wa no ufazaŵa dangagu khöra, iŵa''ö So''aya, Yehowa; ba lalu''i lalöra andrö.', '["Nga''ötI 23:28"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 13, 'Lö tola lahatö''ö ira khögu, ba wangai-ngai halöŵö gere andrö khögu, we''amöi ba ni''amoni''ö andrö khögu fefu, ba ni''amoni''ö sibai andrö. Lalu''i wa''ailara a''ine, awö wotu ba zogoro ita andrö khöra, nilaura.', '["Nga''ötI 23:28"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 14, 'Ba wangai-ngai halöŵö ba gosali ufataro ira — halöŵö ngoni-ngoni andrö ba hadia ia, fefu, nihalö-halö ba da''ö, ba ya''ira zangai-ngai.', '["Nga''ötI 23:28"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 15, 'Ba ere Ono Lewi andrö — nga''ötö Zadoki —, sangai-ngai halöŵö ba ni''amoni''ö andrö khögu, mege, me la''erogö ndra''odo Iraono Gizeraeli, da''ö zangahatö''ö ya''ira khögu, ngoni-ngonigu, ba la''ondrasi ndra''odo, ba wame''e khögu tawö ba do, iŵa''ö So''aya, Yehowa.[6]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 16, 'Möi ira bakha ba ni''amoni''ö andrö khögu ba lahatö''ö ira ba meza khögu, ngoni-ngonigu, sangai-ngai halöŵö khögu.', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 17, 'Ba na latörö mbawa göli, we''amöi ba golayama tanö bakha, ba baru tarafali la''obaru; lö tola labe''e ba nösira mbu mbiri-biri, na lahalö-halö halöŵöra barö mbawa göli golayama tanö bakha ba ba gosali.[7]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 18, 'Saembu tarafali ba högöra ba saraeŵa tarafali ba wahara; böi la''onukha zaböböi ira.[8]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 19, 'Ba na möi ira baero, ba golayama baero, ba niha sato, ba laheta nukhara, nukhara ba halöŵöra mege, ba latou''ö tou ba mbate''e andrö, ba nukha bö''ö la''onukha, fa böi la''amoni''ö zato, ba nukhara andrö.[9]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 20, 'Böi lafatöwö''ö ira, ba böi göi ladudu mbu, nifalo''o a''i mbura.[10]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 21, 'Ba agu, ba böi ibadu ere, na möi ira ba golayama bakha.[11]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 22, 'Ba lö tola lahalö lakha ba he ira alawe nitibo''ö; ono alawe a''i lahalö, ono ma''uwu Gizeraeli; ba lakha gere sa, ba hana na lahalö.[12]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 23, 'Ba banuagu ba lafahaö he wisa wa''afaehu ni''amoni''ö ba zi tenga ni''amoni''ö, ba fa''afaehu zi ra''iö ba zi sökhi, ba labotokhi ba dödöra.[13]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 24, 'Ba samatunö huhuo ira; huku khögu la''o''ö ba wanguhuku, ba oroisagu, awö nifakhoigu, ba latöngöni ba luo ni''amoni''ö andrö khögu fefu, ba la''amoni''ö zabato andrö khögu.[14]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 25, 'Ba mboto zi mate, ba böi lahatö''ö ira, fa böi ra''iö ira; ha na amara ba ma inara ba ma onora matua ba ma onora alawe ba ma talifusöra matua ba ma talifusöra alawe, si lö murai muhalö, ba hana na ra''iö ira.[15]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 26, 'Ba na no mufuli muhaogö, ba fitu bongi na la''erai khönia.[16]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 27, 'Ba na luo ifuli möi ba ni''amoni''ö, ba golayama bakha, ba wangai halöŵö ba ni''amoni''ö, ba ibe''e zumange fameta horö andrö khönia, iŵa''ö So''aya, Yehowa.', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 28, 'Tana khöra benua, ba lö labe''e khöra — no ya''odo dana khöra — ba böi mibe''e khöra zotöi khöra dania: no ya''odo gokhötara![17]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 29, 'Sumange ni''a andrö ba sumange fameta horö ba sumange ogauta, da''ö göra, ba hadia fefu nilakha''ö, ba Ndraono Gizeraeli, ba khöra.', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 30, 'Ba si sökhi zi a''a, hadia ia ngawalö fefu ba hadia ia ngawalö zumange, nihalö fegero, fegero andrö fefu, ba zumange nihalö fegero, ba ere zanema. Ba si a''a hamo khömi, ba khö gere mibe''e, ena''ö möi howu-howu ba nomomi mibe''e.[18]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476424, 'OT', 'Hezekieli', 44, 31, 'Ba hadia zi mate ba he nira''u wofo ba he nisasawi gutu ndru''u, ba lö tola la''a ere.[19]', '["Faigi 40:46; 48:11","MozIII 16:4","MozII 28:42","Faigi 42:14; MozIII 16:4,23","MozIII 19:27; 21:5","MozIII 10:9","MozIII 21:7,13,14","MozIII 10:10; Faigi 22:26","MozV 17:8; Nga''ötII 19:10","MozIII 21:1–4","MozIV 19:11","MozIV 18:20; MozV 10:9","MozII 13:2","MozIII 22:8; MozII 22:31"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 1, 'Na mifaosa danö, na milau dahö-dahö, ba wame''e tana khö, ba mifakhoi khö Yehowa ösa, ame''ela tanö ni''amoni''ö, 25.000 hela wa''anau ba 20.000 hela wa''ebolo; ni''amoni''ö da''ö, ma''asagörö, fasui.', '["Faigi 44:3; 48,21:22"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 2, 'Ba ba nisu''a andrö ba ösu''a na, ba 25.000 hela wa''anau ba 10.000 hela wa''ebolo, naha ni''amoni''ö, ni''amoni''ö sibai andrö.', '["Faigi 44:3; 48,21:22"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 3, 'Ame''ela tanö ni''amoni''ö da''ö; tana ba gere, sangai-ngai halöŵö ba ni''amoni''ö andrö, si tola mangahatö''ö ya''ira, ngonigoni Yehowa, naha nomora. Ba si no tonia ni''amoni''ö andrö.', '["Faigi 44:3; 48,21:22"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 4, 'Naha ni''amoni''ö andrö ba da''ö, ba si 500 hela sagi, fasui, si öfa sagi, ba 50 hela golayamania, fasui.', '["Faigi 44:3; 48,21:22"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 5, 'Ba 25.000 hela wa''anau ba 10.000 wa''ebolo, ba nibe''e tanö Nono Lewi andrö, sangai-ngai halöŵö ba gosali, dua wulu banua naha nomo.', '["Faigi 44:3; 48,21:22"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 6, 'Ba mihonogöi ba mbanua andrö, ba 5.000 hela wa''ebolo ba 25.000 wa''anau, dali nifakhoi no mege, ni''amoni''ö. Ba ba ma''uwu Gizeraeli fefu da''ö.', '["Faigi 44:3; 48,21:22"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 7, 'Ba khö razo, ba faoma fatambai ni''amoni''ö andrö, irugi faoma fatambai mbenua andrö, he tanö ba gaekhula luo, ba he tanö ba gatumbukha. Si fanaunau ba nifakhoi ba zi sambu-sambua mado, i''otarai nola danö tanö ba gaekhula luo, numalö ba nola tanö ba gatumbukha.[1]', '["Faigi 44:3; 48,21:22"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 8, 'Da''ö mbenuania ba Ndraono Gizeraeli, ena''ö böi sa''ae lafakao mbanuagu razo andrö khögu, ena''ö latehe a''ine ba ma''uwu Gizeraeli — dali madora — danö [si tosai].', '["Faigi 44:3; 48,21:22"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 9, 'Da''ö niŵa''ö Zo''aya, Yehowa: Mibato sa''ae, ya''ami razo Ndraono Gizeraeli: Famakao ba famalangögö, ba miböhöli, ba milau zadölö ba satulö. Mibato wamakao banuagu andrö! i''wa''ö So''aya, Yehowa.', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 10, 'Saga satulö ba tumba satulö ba lauru satulö mifake.[2]', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 11, 'Tumba ba lauru, ba ni''osara''ö; felelima lauru zi sa so''e labe''e ba ŵalu hinaoya zi samba lauru. Ba zi sazo''e la''otarai wangerai.', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 12, 'Ba tölu ngafulu saga zi samba fondruyu; na lima saga, ba lima saga göi labe''e, ba na fulu saga, ba fulu saga, ba dua wulu rufia zi samba fondruyu.[3]', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 13, 'Da''ö gamaedola wegero, nibe''emi: Sadumba ba zi sazo''e gandru ba sadumba göi ba zi sazo''e ze''iri.', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 14, 'Ba nihonogöi ba wanikha, ba samba hinaoya ba zi sazo''e, ba zi felelima lauru, si sazo''e.', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 15, 'Ba sara-sara nono mbiri-biri ba zi 200 biri-biri, amaedola fegero, nibe''e mado Ndraono Gizeraeli fefu, nibe''e sumange ni''a ba sumange nitunu ba sumange fangorifi, ba wameta salara, iŵa''ö So''aya, Yehowa.', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 16, 'Niha sato fefu nifo''ömö si hulö wegero andrö khö razo Ndraono Gizeraeli.', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 17, 'Ba ömö razo zumange nitunu ba sumange ni''a ba sumange nibadu ba gowasa ba ba wasulöna ba ba zabato, ba gowuloa ma''uwu Gizeraeli fefu. Ya''ia zame''e sumange fameta horö ba sumange ni''a ba sumange nitunu ba sumange fangorifi, ba wameta sala ma''uwu Gizeraeli.', '["MozIII 19:35","MozII 30:13"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 18, 'Da''ö niŵa''ö Zo''aya, Yehowa: Ba zi sambua desa''a ba mbawa si föföna, ba öhalö nono zaŵi, si matua, si lö sala, ba wameta sala ba ni''amoni''ö andrö.', '["MozIII 23:5","MozIII 23:34"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 19, 'Ba ihalö ndro zumange fameta horö andrö ösa ere, ba igule''ö ba gehomo gosali ba ba watalinga lesi naha wame''e sumange andrö, si öfa, ba ba mboha mbawa göli ba golayama bakha.', '["MozIII 23:5","MozIII 23:34"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 20, 'Ba si manö göi ölau ba zi sambua desa''a ba mbaŵa si fitu, börö zi no mosala, selungu, ba ma sambö fa''aboto ba dödö, ba miheta zala ba gosali ba zi manö.', '["MozIII 23:5","MozIII 23:34"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 21, 'Ba ba zi meweleöfa, ba mbaŵa si föföna, ba milau gowasa fasa andrö; fitu bongi wa''ara la''a roti si lö mu''aisöni.[4]', '["MozIII 23:5","MozIII 23:34"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 22, 'Ba razo, ba ibe''e nono zaŵi sumange fameta horö, na luo da''ö, khönia ba ba niha sato ba danö fefu.', '["MozIII 23:5","MozIII 23:34"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 23, 'Ba si fitu ngaluo gowasa andrö, ba fadoro fitu rozi ma''ökhö ibe''e ono zaŵi sumange nitunu khö Yehowa ba fitu nga''eu göi mbiri-biri si matua si lö si sala, ba sageu ma''ökhö nambi si matua, sumange fameta horö.', '["MozIII 23:5","MozIII 23:34"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 24, 'Ba sumange ni''a, ba tölu lauru ibe''e, awö nono zaŵi andrö, ba tölu lauru göi awö mbiri-biri, ba fanikha, tölutölu hinaoya ba zi tölutölu lauru andrö.', '["MozIII 23:5","MozIII 23:34"]', NULL),
  (3476425, 'OT', 'Hezekieli', 45, 25, 'Ba duli ba mbaŵa si fitu, ba gowasa, ba si manö göi ibe''e, fitu bongi wa''ara, he sumange fameta horö ba he sumange nitunu, ba he sumange ni''a ba fanikha.[5]', '["MozIII 23:5","MozIII 23:34"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 1, 'Da''ö niŵa''ö Zo''aya, Yehowa: Bawa göli andrö ba golayama bakha, tanö ba gatumbukha luo, ba si önö ngaluo barö zabato, ba lö labokai, ba na luo sabato, ba labokai, ba si manö göi ba wasulöna.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 2, 'Ba itörö gewe''ewe, mbawa göli andrö razo, moroi baero, we''amöi bakha, ba i''iagö ba ngai mboha mbawa göli. Ba labe''e zumange nitunu andrö khönia ba sumange fangorifi ere; ba ya''ia, ba sangalulu, ba zilötö mbawa göli andrö, ba aefa da''ö, ba ifuli möi baero, ba bawa göli ba lö lakusi, irege bongi.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 3, 'Ba niha ba danö, ba sangalulu khö Yehowa, föna mbawa göli na luo sabato ba ba wasulöna.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 4, 'Ba da''ö zumange nitunu andrö, nibe''e razo khö Yehowa: na luo sabato, ba önö rozi nono mbiri-biri, si lö si sala, ba sageu mbiri-biri si matua,', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 5, 'si lö si sala, ba nifo''awö sumange ni''a, tölutölu lauru ba mbiri-biri si matua andrö; balazi ira ha wa''ebua zumange ni''a andrö awö nono mbiri-biri andrö, ba tölu hinaoya wanikha ba zi tölu lauru.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 6, 'Ba ba wasulöna, ba ono zaŵi si matua, si lö si sala, ba önö rozi nono mbiri-biri ba sageu mbiri-biri si matua, oi si lö si sala [nibe''e].[1]', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 7, 'Ba sumange ni''a, ba tölu lauru i''asiwai, awö nono zaŵi andrö, ba tölu lauru, awö mbiri-biri si matua; ba awö nono mbiri-biri andrö, ba dali ia ha wa''ebua, ba tölu hinaoya wanikha ba zi tölu lauru.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 8, 'Ba na möi bakha razo, ba ewe''ewe mbawa göli andrö itörö, ba da''ö göi lalania we''amöi baero.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 9, 'Ba na la''ondrasi Yehowa niha ba danö, na baŵa gowasa, ba sanörö bawa göli tanö yöu we''amöi bakha, ba bawa göli tanö raya itörö we''amöi baero, ba sanörö bawa göli tanö raya we''amöi bakha, ba bawa göi tanö yöu itörö we''amöi baero; böi latörö ba wangawuli mbawa göli nitöröra ba we''amöi bakha; ba zi fatahö a''i latörö ba we''amöi baero.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 10, 'Ba razo, ba bakha ba hunöra so, na möi ira bakha, ba fao ia khöra, na möi ira baero.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 11, 'Ba ba gowasa ba na luo ni''amoni''ö, ba tölutölu lauru zumange ni''a, awö nono zaŵi andrö ba awö mbiri-biri si matua; ba balazi ira ha wa''ebua ba nono mbiri-biri andrö; ba tölutölu hinaoya wanikha ba zi tölutölu lauru.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 12, 'Ba na ibe''e game''ela saoha gölö razo, sumange nitunu ba ma sumange fangorifi, saoha gölönia khö Yehowa, ba labokai khönia mbawa göli, tanö ba gatumbukha luo; ba ibe''e sumange fangorifi, nibe''e-be''enia, na luo sabato, ba ifuli möi baero; ba no möi ia baero, ba nikusi mbawandruhö.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 13, 'Ba ero ma''ökhö, ba sara ibe''e ono mbiri-biri si döfi fa''ebua ba si lö si sala, sumange Yehowa, sumange nitunu; ero na mahemolu mbanua ibe''e.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 14, 'Ba ifo''awö sumange ni''a — ero mahemolu — dua dumba, ba samba hinaoya wanikha, ba wanefe hamo si sökhi andrö, sumange Yehowa, sumange ni''a, amakhoita si lö tebulö.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 15, 'Ba si manö wame''era ono mbiri-biri andrö ba sumange ni''a andrö, awö wanikha, ero mahemolu, sumange nitunu, si lö mamalö-malö.', '["MozIV 28:11"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 16, 'Da''ö niŵa''ö Zo''aya, Yehowa: Na ibe''e khö nononia mbenua razo, bualania, ba iraononia zokhö, ondröita.', '["MozIII 25:10; MozIV 36:4"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 17, 'Ba na khö genoninia ibe''e buala mbenua, ba ha irugi ndröfi wangefa andrö, wa khönia. Ba ba da''ö, ba mangawuli khö razo; ba benua ba ndraononia andrö, ba lö tebulö wa khöra.[2]', '["MozIII 25:10; MozIV 36:4"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 18, 'Ba lö tola ihalö hadia ia mbenua zato razo, wamakao ya''ira, na i''ambösi dana khöra; benua khönia, ba hana na ibe''e ba ndraononia, ondröita, fa böi tetimba mbanuagu, ha niha ia, ba dana khönia.', '["MozIII 25:10; MozIV 36:4"]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 19, 'Ba ifatörödo ba mbawandruhö andrö, ba mbagolö ba zinga mbawa göli andrö ba mbate''e ni''amoni''ö andrö, nihonogöi nahia gere, tanö miyöu. Ba ba da''ö, ba so nahia ba watalinga ba wondrege tanö ba gaekhula luo.', '[]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 20, 'Ba imane khögu: Da''ö naha andrö ba nirino gere sumange ogauta andrö ba sumange fameta horö ba ba nigore sumange ni''a andrö, fa böi la''ohe baero ba golayama, ba golayama baero, ba we''amoni''ö niha sato.', '[]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 21, 'Ba i''ohedo baero, ba golayama baero, ifa''amöido ba watalinga golayama andrö, si öfa, ba hiza, dozi fatalinga golayama, ba so golayama [side-ide].', '[]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 22, 'Ba watalinga golayama andrö, si öfa, ba so golayama ni''oniagö, 40 hela wa''anau ba 30 hela wa''ebolo; no fagölö-gölö wa''ebua zi öfa andrö, nahia andrö, ba watalinga.', '[]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 23, 'Ba no mubale kara, fasui, ma''a''öfa, ba ba gahe mbale andrö, ba so nawu, fasui.', '[]', NULL),
  (3476426, 'OT', 'Hezekieli', 46, 24, 'Ba imane khögu: Da''ö nahia koki andrö; ba nirino zangai-ngai halöŵö ba gosali sumange nitaba andrö, nibe''e niha sato.', '[]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 1, 'Ba i''ohedo mangawuli, ba mbawandruhö gosali, ba hiza nidanö, si otarai doyo nomo andrö, tanö ba gatumbukha luo; atumbukha luo sa i''otahögö osali. Ba ahele mitou nidanö andrö ba gahe mbagolö gosali tanö raya, raya naha wame''e sumange.[1]', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 2, 'Ba i''ohedo baero, ifatörödo be mbawa göli tanö you ba matörö lala, ba wamasui ba mbawa göli baero, si otahögö atumbukha luo; ba hiza nidanö, si otarai narö mbagolö tanö raya.', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 3, 'Ba möi baero niha andrö, si so helo ba danga, me isaŵa tanö ba gatumbukha luo, ba isu''a, ba 1.000 hela. Ba ifatörödo ba nidanö andrö; irugi mbu''u gawono.', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 4, 'Ba ifuli isu''a, ba 1.000 hela, ba ifatörödo ba nidanö, ba irugi mbalöduhi. Ba ifuli isu''a, ba 1.000 hela, ba ifatörödo ba nidanö, ba no falaŵa sola.', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 5, 'Ba ifuli isu''a, ba 1.000 hela, ba no idanö sebua si tebai u''ötö. Me no abölö abakha nidanö andrö — no idanö solangi ita — no idanö sebua, si tebai ta''ötö.', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 6, 'Ba imane khögu: Hadia, no anehe''ö da''ö, ono niha? Ba i''ohedo mangawuli ba mbewe nidanö andrö.', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 7, 'Ba me ufulido, ba hiza, no fahöna geu ba mbewe nidanö andrö, faoma fatambai.', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 8, 'Ba imane khögu: Idanö andre, ba isaŵa baero ba danö tanö ba gatumbukha luo, ba Garaba misi tou moluaha; ba na irugi zilua asi andrö [silua asi si mate] ba nidanö sasi-asi, ba idanö si sökhi nasi andrö.[2]', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 9, 'Ba hadia ia fefu saliŵa-liŵa, solihaliha ba da''ö, heza irugi hohounia, ba auri, ba si fahöna dania gi''a; na no irugi sa''ae idanö andrö, ba tobali idanö si sökhi [nasi andrö], ba hadia ia fefu ba zirugi idanö andre, ba auri.[3]', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 10, 'Ba so dania zangai i''a ba mbewe, i''otarai Enigedi, numalö ba Enegela''i; naha ba nilau kiri dania ia; oi so ngawalö gi''a, si mane i''a ba nasi sebua, fahöna.', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 11, 'Ba laza andrö khönia, awö zi faonö andrö, ba lö tobali, dörö-dörö asi-asi a''ine, ba wangasio.', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 12, 'Ba ba mbewe nidanö andrö, ba ngöfinia fatambai, ba so ngawalö geu sowua, ö niha; bulunia, ba lö aleu, ba bua, ba si lö aetu. Sarasara waŵa, ba so mbua si bohou; me no ba ni''amoni''ö andrö i''otarai idanö andrö khönia. Bua, ba ö niha, ba bulu, ba dalu-dalu.[4]', '["Yoel 3:18; Fam 22:1","MozV 3:17","Sakh 14:8","Fam 22:2"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 13, 'Da''ö niŵa''ö Zo''aya, Yehowa: Da''ö nola danö andrö, nifaosami khömi, dali mado Ndraono Gizeraeli andrö, si felendrua; ba ba mado Yosefo, ba dombua waosatö.[5]', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 14, 'Mifagölö-gölö waosatö khömi, ondröita dania, me no fahölu ndra''o me föna, ube''e khö ndra tuami, ba tobali ya''ami zokhö tanö andre, ondröita.[6]', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 15, 'Ba da''ö nola danö, tanö yöu: I''otarai nasi sebua ba ituturu Hetelono, irugi lala ba Zedada,', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 16, 'Hamata ba Berota ba Sibera''i, ba nolara danö Ndramaseko danö Hamata, irugi Hasara-Enono, ba nola Haurana.[7]', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 17, 'Tobali i''otarai nasi ola andrö, ba irugi Hasara-Enono, tobali italu''i miyöu tanö Ndramaseko ba tanö Hamata; da''ö danö miyöu.', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476427, 'OT', 'Hezekieli', 47, 18, 'Ba tanö ba gatumbukha luo: I''otarai Hasara-Enono ba gotaluara Ndramaseko Haurana, ba no Yoridano nolara Gileadi danö Ndraono Gizeraeli, irugi zilua asi tanö ba gatumbukha luo, irugi danö ba Damara; da''ö danö ba gatumbukha luo.', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 19, 'Ba tanö miraya: I''otarai Damara, irugi Me-Meriboto ba ngai Gadesi ba ituturu mbombo andrö mitou ba nasi sebua; da''ö danö miraya.[8]', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 20, 'Ba tanö ba gaekhula luo: Asi sebua nola, irugi ba gamaudu sibai lala ba Hamata; da''ö danö ba gaekhula luo.', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 21, 'Da''ö danö andrö nifaosami khömi, dali mado Ndraono Gizeraeli andrö.[9]', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 22, 'Milau dahö-dahö, ba wamaosa ya''ia ondröita khömi ba ba niha bö''ö andrö, si no fatewu khömi, si no mo''ono ono matua ba khömi. Si falaŵalaŵa ba Ndraono Gezeraeli, ono ba danö, ira, mibe''e. Sanema ondröita göi ira, awömi, bakha ba hunö mado Ndraono Gizeraeli.', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476427, 'OT', 'Hezekieli', 47, 23, 'Ba mado andrö, ba zi so niha bö''ö andrö, mituturu khönia gondröita khönia, iŵa''ö So''aya, Yehowa.', '["MozI 48:5","MozI 12:7; 17:8","Yos 13:5; Sanguhuk 3:3","MozI 14:7; MozIV 20:1; 27:14; 34:5","MozIV 33:54"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 1, 'Ba da''e döi mado andrö: Ba wondrege yöu, ba ngai lala ba Hetelono, irugi lala ba Hamata ba ba Hasara-Enana ba nola Ndramaseko tanö raya, ba ngai Hamata, tobali khöra i''otarai danö ba ba gatumbukha luo, numalö ba danö ba gaekhula, ba mado Dano, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 2, 'Ba ba ngai mado Dano, i''otarai danö ba gatumbukha luo, numalö ba danö ba gaekhula, ba mado Gaseri, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 3, 'Ba ba ngai mado Gaseri, moroi ba gatumbukha, numalö ba gaekhula, ba mado Nafetali, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 4, 'Ba ba ngai mado Nafetali, moroi ba gatumbukha, numalö ba gaekhula, ba mado Manase sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 5, 'Ba ba ngai mado Manase, moroi ba gatumbukha, irugi ba gaekhula, ba mado Geferayi, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 6, 'Ba ba ngai mado Geferayi, moroi ba gatumbukha, irugi ba gaekhula, ba mado Rubeno, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 7, 'Ba ba ngai mado Rubeno, moroi ba gatumbukha, irugi ba gaekhula, ba mado Yuda, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 8, 'Ba ba ngai mado Yuda, moroi ba gatumbukha, irugi ba gaekhula, ba buala andrö, nibe''emi, labe''e, 25.000 hela wa''ebolo ba fa''anau, ba i''ohia''ö dana ba zi sambu-sambua mado, moroi ba gatumbukha, irugi ba gaekhula; ba ba dalunia labe''e ni''amoni''ö andrö.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 9, 'Ba buala andrö nibe''emi khö Yehowa, ba 25.000 hela wa''anau, ba 20.000 hela wa''ebolo.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 10, 'Ba da''ö zokhö buala ni''amoni''ö andrö: Ere, miyöu, ba 25.000 hela, ba tanö ba gaekhula luo, ba 10.000 hela wa''ebolo, ba tanö ba gatumbukha, ba 10.000 hela göi wa''ebolo, ba tanö miraya, ba 25.000 hela wa''anau. Ba ba dalunia bakha labe''e ni''amoni''ö andrö khö Yehowa.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 11, 'Ba gere ni''amoni''ö andrö, nga''ötö Zadoki, si iagö ngoni-ngonigu, si lö elungu, me elungu Ndraono Gizeraeli, si mane fa''elungu Nono Lewi andrö.[1]', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 12, 'Khöra ia si faböbö ba mbuala andrö, föfö mbuala tanö andrö, ni''amoni''ö sibai, si faola ba mbenua Nono Lewi.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 13, 'Ba ba Nono Lewi, ba dali nibe''e ba gere: 25.000 hela wa''anau ba 10.000 hela wa''ebolo, tobali 25.000 hela wa''anau, fefu, ba 20.000 hela wa''ebolo.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 14, 'Ba lö tola la''amawa hadia ia ba lö tola lafalalini, lö tola möi ba danga mbö''ö wondrege zi sökhi danö andrö, me no ni''amoni''ö khö Yehowa.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 15, 'Ba si 5.000 hela andrö, si tosai na, bolo andrö, ba zinga zi 25.000 hela andrö, ba ba mbanua, ba zato, möi, naha nomo ba benua zato; ba banua, ba ba dalu bakha so.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 16, 'Ba da''ö wa''ebua: Tanö yöu, ba 4.500 hela, ba tanö raya, ba 4.500 hela, ba tanö ba gatumbukha ba 4.500 ba tanö ba gaekhula, ba 4.500.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 17, 'Ba benua mbanua andrö ba 250 hela tanö yöu ba, 250 tanö raya ba 250 tanö ba gatumbukha ba 250 tanö ba gaekhula.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 18, 'Ba si tosai naunau, ba zinga mbuala ni''amoni''ö andrö, 10.000 hela tanö ba gatumbukha ba 10.000 hela tanö ba gaekhula, da''ö nibe''e si faola ba mbuala ni''amoni''ö andrö, ba buania, ba ö mbanua.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 19, 'Ba banua andrö, ba si fakhöyö, dozi mado Ndraono Gizeraeli.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 20, 'Ba ahonoa nibe''emi buala tanö, ba si öfa sagi, 25.000 hela: buala ni''amoni''ö andrö, fabaya benua mbanua.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 21, 'Ba si tosai, ba khö razo, faoma fatambai mbuala ni''amoni''ö andrö, ba zi fabaya benua mbanua tanö ba gatumbukha luo, ba ngai zi 25.000 hela, irugi nola tanö ba gatumbukha, ba tanö ba gaekhula, ba ngai zi 25.000 hela, irugi nola tanö ba gaekhula, dali dana ba zi sambu-sambua mado; khö razo da''ö, ba buala ni''amoni''ö andrö, ba osali andrö, ni''amoni''ö, ba ba dalu bakha so.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 22, 'Ba i''otarai mbenua Nono Lewi ba benua mbanua, ba gotalua dana khö razo, ba khö razo gotaluara dana ba mado Yuda dana ba mado Mbeniyami.', '["Faigi 44:15"]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 23, 'Ba mado si tosai, ba i''otarai danö ba gatumbukha luo, numalö ba danö ba gaekhula, ba mado Mbeniyami, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 24, 'Ba ba ngai mado Mbeniyami, moroi ba gatumbukha, irugi ba gaekhula, ba mado Zimeoni, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 25, 'Ba i''otarai mado Zimeoni, moroi ba gatumbukha, irugi ba gaekhula, ba mado Isasari, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 26, 'Ba ba ngai mado Isasari, moroi ba gatumbukha, irugi ba gaekhula, ba mado Zebuloni, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 27, 'Ba ba ngai mado Zebuloni, moroi ba gatumbukha, irugi ba gaekhula, ba mado Gado, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 28, 'Ba ba ngai mado Gado, tanö miraya, ba ola, i''otarai Damara, itörö Me-Meriba, ba zinga Gadesi, irugi mbombo andrö (ola danö Miserayi) ba i''osisi, irugi nasi sebua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 29, 'Da''ö danö andrö, nifaosami ondröita dania ba mado Ndraono Gizeraeli, si fadahö-dahö ami, ba da''ö dana khöra andrö, iŵa''ö So''aya, Yehowa.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 30, 'Ba da''ö mbawa göli mbanua — töi mbawa göli mbanua, ba si ohia''ö töi mado Ndraono Gizeraeli —: Tanö yöu, 314.500 hela ba zu''a-su''a andrö, ba tölu mbawa göli, tanö miyöu: bawa göli mado Rubeno, sambua, ba bawa göli mado Yuda, sambua, ba bawa göli mado Lewi, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 32, 'Ba tanö ba gatumbukha luo, 4.500 hela, ba tölu mbawa göli: bawa göli mado Yosefo, sambua, ba bawa göli mado Mbeniyami, sambua, ba bawa göli mado Dano, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 33, 'Ba tanö raya, 4.500 hela, ba tölu mbawa göli: bawa göli mado Zimeoni, sambua, ba bawa göli mado Isasari, sambua, ba bawa göli mado Zebuloni, sambua.', '[]', NULL),
  (3476428, 'OT', 'Hezekieli', 48, 34, 'Ba tanö ba gaekhula luo, 4.500 hela, ba tölu mbawa göli: bawa göli mado Gado, sambua, ba bawa göli mado Gaseri, sambua, ba bawa göli mado Nafetali, sambua. 3.518.000 hela, fasui, ba töi mbanua, na luo da''ö dania, ba "Yehowa ba da''ö."', '[]', NULL),
  (3476429, 'OT', 'Danieli', 1, 1, 'Me no alua mendrua fakhe razo Yoyaki andrö, razo mado Yuda, ba so Nebukanesa, razo Mbabeli, möi ia ba Yeruzalema, ba wanuwö ya''ira.[1]', '["RazII 24:1","MozI 10:10"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 2, 'Ba ibe''e ba dangania Yoyaki razo mado Yuda So''aya, awö gama-gama ba nomo Lowalangi ösa, ba i''ohe ba danö Zineara, ba gosali Lowalanginia, ba gama-gama andrö, ba ibe''e ba mbate''e girö-girö andrö khö Lowalanginia.[2]', '["RazII 24:1","MozI 10:10"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 3, 'Ba ibe''e li razo khö Asifena, mandru genoni yomo, ena''ö ifaigi ba Ndraono Gizeraeli nga''ötö razo, awö nga''ötö zalaŵa,', '["RazII 24:1","MozI 10:10"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 4, 'ono matua si lö si sala [ba mbotora] ba si no mufahaö ba sangila watahögö ba si so fa''aboto ba dödö, si nangea möi ngoni-ngoni razo, ba gödo, ba ena''ö na ifahaö ira ba wanura ba ba li Ndrawa Galedaia.', '["RazII 24:1","MozI 10:10"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 5, 'Ba iŵa''ö razo göra ma''ökhö, föfö gö razo ba föfö nagu nibadu-badunia, ba ibe''e li, medölu fakhe wa''ara la''e''ebua ira, ba na aefa da''ö, ba möi ira ngoni-ngoni razo.', '["RazII 24:1","MozI 10:10"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 6, 'Ba ya''ira göi mado Yuda andrö, ira Danieli, Hanania, Mizaeli ba Asaria.', '["RazII 24:1","MozI 10:10"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 7, 'Ba ifalalini döira mandru genoni yomo: Töi Danieli, ba Belizasari, ba töi Hanania ba Saderakhi, ba töi Mizaeli, ba Mezakhi ba töi Asaria ba Abedo-Nego ibe''e.', '["RazII 24:1","MozI 10:10"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 8, 'Ba iŵa''ö sibai tödönia Danieli, lö ihalö salakha khönia wemanga gö razo, ba he famadu agu andrö, föfö nibadu-badu razo. Ba i''andrö khö mandru genoni yomo, ena''ö alakha lö ihalö salakha khönia.[3]', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 9, 'Ba falukha wa''ebua dödö ba fa''ahakhö dödö Danieli, khö mandru genoni yomo, ibe''e Lowalangi;', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 10, 'ba imane zui mandru andrö khö Danieli: Soso dödögu, ma dania safuofuo ami, moroi ba nono matua bö''ö, si faziazia''a khömi, wamaigi zokhö ya''o, razo, sanguma''ö gömi, andrö, ba ma ifabunu''ö dania ndra''ö razo, börö ami!', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 11, 'Ba imane Danieli khö mandru zame''e-me''e gö, nibe''e mandru genoni yomo barö mbawa ira Danieli, Hanania, Mizaeli ba Asaria:', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 12, 'Tema tandraigö ba genoniu andre, fulu bongi, ena''ö ha sambalö sinanö labe''e öma, ba idanö, nibadu.', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 13, 'Ba hana na öfaigi dania, he wisa nösima ba he wisa nösi nono matua si manga-manga wöfö gö razo; ba heza zi faduhu dödöu dania, ba da''ö ölau ba genoniu.', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 14, 'Ba i''o''ö ni''andröra, ba itandraigö fulu bongi.', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 15, 'Ba me no aefa zi fulu bongi, ba no sökhi nösira ba no esolo ira, moroi ba nono matua andrö fefu, si manga-manga wöfö gö razo.', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 16, 'Ba i''otarai da''ö, ba ifaheta''ö mandru same''e-me''e gö göra andrö ba agu andrö, ba sinanö ibe''e öra.', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 17, 'Ba ibe''e ba nono matua andrö si daöfa Lowalangi wangila watahögö ba fa''aboto ba dödö ngawalö zura fefu, awö ngawalö wa''atua-tua; ba Danieli, ba i''ila göi geluaha gangilata ba eluaha wangifi fefu.', '["MozIII 11"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 18, 'Ba me no irugi inötö niŵa''ö razo, ba wama''ele''ö ya''ira khönia, ba ifa''ele''ö ira khö Nebukanesa mandru genoni yomo.', '["Eser 1:1; Faigi 6:28"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 19, 'Ba me fahuhuo khöra razo, ba lö ba khöra fefu si mane ira Danieli, Hanania, Mizaeli ba Asaria; ba möi ngoni-ngoni razo ira.', '["Eser 1:1; Faigi 6:28"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 20, 'Ba ero na balazi wa''atua-tua ba fa''aboto ba dödö, ba isöndra razo — ero na izofu-zofu khöra — mewulu latalu''i zebua elemu ba si faeta fefu, ba mbanuani, fefu.', '["Eser 1:1; Faigi 6:28"]', NULL),
  (3476429, 'OT', 'Danieli', 1, 21, 'Ba Danieli, ba lö si mate na, me awena tobali razo Kiro.[4]', '["Eser 1:1; Faigi 6:28"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 1, 'Ba me no töra döfi razö Nebukanesa, ba mangifi ia, ba humufa dödönia, ba lö''ö sa''ae i''ila mörö.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 2, 'Ba ibe''e li razo, lakaoni zebua elemu ba si faeta ba sanoto ba Dawa Galedaia, ba wangombakha khö razo hadia wangifinia. Ba me so ira, me la''ondrasi razo,', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 3, 'ba imane khöra razo: No mangifi ndra''o, ba no humufa dödögu, ena''ö u''ila geluaha wangifi andrö.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 4, 'Ba latema li razo Dawa Galedaia andrö, ba li Ndrawa Garamo, lamane: He razo, ya si lö aetu nosou! Tunö wangifi andrö ba genoniu, ena''ö ma''ombakha''ö geluahania!', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 5, 'Ba imane razo ba Ndrawa Galedaia anrdö: No u''etu''ö tödögu: Na tebai mitunö khögu wangifi andrö, fabaya eluahania, ba la''ö''ötö ami, ba labali''ö oboula nomomi.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 6, 'Ba na mi''ila mitunö khögu wangifi, fabaya eluahania, ba oya ngawalö mbuala ba sumange sebua mitema khögu. Andrö mi''ombakha''ö khögu wangifi andrö, awö geluahania!', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 7, 'Ba lafuli latema linia, lamane: Yamutunö manö wangifi andrö razo, ba genoninia, ba ya''aga dania zanguma''ö hadia geluahania.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 8, 'Ba imane khöra razo: Aboto sibai sa''ae ba dödögu, wa edöna mirörö ndra''odo, me no mirongo, no u''etu''ö tödögu:', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 9, 'Na lö''ö sa mi''ila mitunö khögu wangifigu andrö, ba lö tebulö huku, ni''etu''ögu khömi, me no mamagölö ami, ba wolau faya khögu, ba wolimo ya''o, irege no olifu ndra''ö. Andrö mitunö khögu wangifi andrö, ena''ö aboto ba dödögu, mi''ila göi miŵa''ö khögu, hadia geluahania.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 10, 'Ba latema li razo Dawa Galedaia andrö, lamane: Samösa lö niha ba guli danö, sangila manguma''ö ni''andrö razo, ba lö''ö göi irai iŵa''ö ba zebua elemu ba ba zi faeta ba ba Ndrawa Galedaia zi mane da''ö razo sebua ba sabölö, fefu gofu heza.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 11, 'No abölö afökhö ni''andrö razo, me samösa lö sangila mangombakha''ö da''ö khö razo, baero zi no motöi Lowalangi, ba tenga ba ngai niha si mate-mate so da''ö.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 12, 'Ba mofönu sibai razo, abao dödönia, ba ibe''e li, ahori labunu zonekhe-nekhe ba Mbabeli.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 13, 'Ba me no mube''e goroisa andrö, ba wamunu sonekhe-nekhe andrö, ba la''alui göi Danieli ba awönia andrö, ba wamunu ya''ira.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 14, 'Ba humede Danieli, si so era-era ba si so tödö, khö Gariokhi, kumandra wazuri, si möi mamunu sonekhe-nekhe ba Mbabali.', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 15, 'Humede ia, imane khö Gariokhi andrö, kumandra khö razo: Hadia mbörö goroisa sabe''e andrö, nibe''e razo? Ba me no i''ombakha''ö khö Danieli mbörö Ariokhi,', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 16, 'ba möi Danieli mangandrö famonoso khö razo, ba i''ombakha''ö khö razo geluaha [wangifi andrö] iŵa''ö.', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 17, 'Aefa da''ö, ba ifuli ia ba nahiania Danieli ba idunö-dunö ba nawönia andrö, khö ndra Hanania, Mizaeli, Asaria huhuo andrö,', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 18, 'ba iŵa''ö khöra la''agaröfi li Lowalangi ba zorugo, ba zi no tobini andrö, ena''ö ihakhösi tödö ira, fa böi lafao dania ba zonekhe-nekhe bö''ö ba Mbabeli Danieli ba awönia, wamunu ya''ira.', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 19, 'Ba tebokai khö Danieli zi no tobini andrö ba gangilata, ba zi bongi. Ba isuno Lowalangi ba zorugo Danieli.', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 20, 'Humede ia, imane: Nisuno döi Lowalangi, götö-götö wa''ara dania; me no khönia wa''atua-tua ba fa''abölö.[1]', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 21, 'Ya''ia zamalalini nga''ötö ba inötö, itimba razo ba ifuli ifataro razo bö''ö; ba ya''ia zame''e fa''atua-tua ba zatuatu''a ba fa''aboto ba dödö ba zaboto ba dödö.[2]', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 22, 'Ya''ia zamokai si no tobini sibai, ba i''ila nilau ba zogömi-gömi; ba haga andrö, ba ba khönia so.', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 23, 'U''andrö saoha gölö khöu, ya''ugö Lowalangi ndra tuagu, usuno ndra''ugö, me no öbe''e khögu wa''tua-tua ba fa''abölö, ba me no öbokai göi khögu iada''e ni''andröma khöu; noa sa öbokai khöma niŵa''ö razo andrö.', '["Sin 113:2","RazI 3:7 b.t.; Yob 12:13 b.t."]', NULL),
  (3476430, 'OT', 'Danieli', 2, 24, 'Ba möi sa''ae Danieli khö Gariokhi, ba niŵa''ö razo famunu sonekhe-nekhe ba Mbabeli; möi ia khönia, imane khönia: Böi bunu zonekhe-nekhe ba Mbabeli! Ohe ndra''o yomo khö razo, ba u''ombakha''ö geluaha [wangifi andrö] khö razo.', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 25, 'Ba i''aliogö i''ohe khö razo Danieli Ariokhi, imane khönia: No usöndra niha, ba Niha Yehuda, ni''oloi''ö moroi ba mbanuara, sedöna mangombakha eluaha [wangifi andrö] khö razo.', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 26, 'Ba humede razo, imane khö Danieli, si no mufotöi Belizasari: Hadia, ö''ila ö''ombakha''ö khögu hadia wangifigu andrö ba hadia geluahania?', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 27, 'Ba humede Danieli, imane khö razo: Ba zi no tobini andrö, ni''andrö razo, ba lö sonekhe-nekhe ba lö si faeta ba lö sebua elemu ba lö sangila eluaha ndröfi, sangila mangombakha khö razo;', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 28, 'ba so Lowalangi, ba zorugo, samokai si no tobini, ba no da''ö zama''ele''ö khö razo Nebukanesa, he wisa dania, furida. Ba da''ö wangifiu andrö ba angilata höröu ba wemöröu:[3]', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 29, 'Ya''ugö razo, ba no mangera-ngera tödö ndra''ugö ba gasou, he wisa maö furida; ba samokai si no tobini, ba no ifa''ele''ö khöu he wisa.', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 30, 'Ba no tenga börö wa''atua-tua, si no so khögu taŵa''ö, ba si lö ba niha bö''ö fefu, wa no mu''oroma''ö khögu; börönia: ena''ö irongo geluaha razo, ba ena''ö te''ombakha''ö khöu hadia gera-era dödöu andrö.', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 31, 'Ya''ugö razo, ba no ö''ila, no so ba duduma höröu wamaedo niha, sebua sibai. No ebua wamaedo andrö, ba si no ebua sibai lakhömi göi; no musindro fönau ba sata''u ita wamaigi ya''ia.', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 32, 'Högö wamaedo andrö, ba no si ndruhu mbalaki, ba totonia, awö da''io, ba firö, ba talu ba lafoyo, ba töla garamba, ba fahania, ba si''öli, ba ahenia,', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 33, 'ba no matonga zi''öli, ba si matonga, ba la''uri.', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 34, 'Ba öfaigi, ba i''ogomuzaö abo''a gowe — tenga moroi ba danga niha — ba göna ba wamaedo niha andrö, ba gahenia si''öli ba la''uri, ba arasa ibe''e.', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 35, 'Ba i''ozumagö muzawili, he si''öli ba he la''uri, ba he töla garamba, ba he firö, ba he balaki, timba ndrami ba golayama mbasitö ba wamasi, ba i''oloi''ö angi, tobali ezai mutö lö musöndra sa''ae. Ba gowe andrö, same''e arasa wamaedo niha andrö, ba manöi ba tobali hili sebua, anönö guli danö ma''asagörö ibe''e.[4]', '["Amos 4:13","Yes 2:2; 28:16"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 36, 'Da''ö wangifi andrö, ba data''ombakha''ö khö razo hadia geluahania;', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 37, 'Ya''ugö razo, ba no razo yaŵa razo bö''ö ndra''ugö, nibe''e Lowalangi ba zorugo fa''asalaŵa ba fa''abölö ba fa''abe''e ba fa''ebua döi,[5]', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 38, 'ba nibe''enia barö mbawa niha, fefu gofu heza so ira, awö zaliŵa-liŵa ba danö, awö wofo ba dalu mbanua, nibe''enia samatörö ya''ira fefu: ya''ugö högö balaki andrö.[6]', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 39, 'Ba furiu dania, ba so gamatöröŵa bö''ö, sambö moroi ba khömö; ba aefa da''ö, ba so zui, si no töla garamba, ba irugi guli danö ma''asagörö famatörö.', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 40, 'Ba aefa da''ö, ba amatöröŵa fanete zi tölu, sabe''e timba zi''öli, si mane si''öli, sorasa fefu hadia ia, samoto, si manö wa ifufu dania da''ö no mege fefu ba irasa, si mane si''öli, forasa hadia ia.', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476430, 'OT', 'Danieli', 2, 41, 'Ba ahe andrö ba tuturu kahe ni''ilau, wa no matonga la''uri ba si matonga, ba si''öli, ba falöaro gamatöröŵa andrö [geluahania]. Ba so sa atö khönia göi wa''abe''e zi''öli; ya''ia wa no ö''ila, no fakhöyö ira zi''öli la''uri.', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 42, 'Ba fangilau, wa no faruka ira zi''öli la''uri, ba duturu kahe, ba ya''ia wa matonga aro, matoga lö aro gamatöröŵa andrö;', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 43, 'awö wa no faruka ira zi''oli la''uri, ö''ila: ba he lafakhöyö ira, na fahalö ira, ba lö''ö sa atö faböbö, si mane si''öli ba la''uri, si tebai göi tafaruka.', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 44, 'Ba na luo razo andrö, ba i''asogö gamatöröŵa Lowalangi ba zorugo, amatöröŵa si tebai adudu, götö-götö wa''ara, ba fa''asalaŵa da''ö, ba lö möi ba niha bö''ö; irasa dania gamatöröŵa no mege fefu, ba ihori, ba ya''ia, ba lö tebulö, irugi zi lö aetu.[7]', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 45, 'Si mane fangilau, wa abo''a gowe ba hili — tenga moroi ba danga niha — sorasa si''öli ba töla garamba ba la''uri ba firö ba balaki. No Lowalangi sebua zama''ele''ö khö razo, he wisa dania. Ba fangifi andrö, ba no si ndruhu, ba eluahania, ba no si faduhu dödöda.', '["Hez 26:7","Yer 27:6; 28:14","Faigi 4:31; 6:26,44; Mikh 4:7; Luk 1:33"]', NULL),
  (3476430, 'OT', 'Danieli', 2, 46, 'Ba ifalögu tou ia razo Nebukanesa, ba mangalulu ia khö Danieli, ba ibe''e li, labe''e zumange khönia ba samohua.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 47, 'Ba humede razo, imane khö Danieli: Si ndruhu: no Lowalangi yaŵa Lowalangi bö''ö Lowalangimi andrö, ba no So''aya razo fefu, ba no sangila mamokai si no tobini ia, me no ö''ila öfa''ele''ö zi no tobini andrö.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 48, 'Ba ifosumange sibai Danieli razo; oya sibai ibe''e khönia buala sebua, ba ifataro salaŵa ia ba nöri Mbabeli ma''asara, ba ibe''e fondrege zatua zonekhe-nekhe ba Mbabeli fefu ia.', '[]', NULL),
  (3476430, 'OT', 'Danieli', 2, 49, 'Ba me mangandrö Danieli khö razo, ba ibe''e ba danga ndra Saderakhi, Mezakhi Abedo-Nego wamatörö öri Mbabeli. Ba Danieli, ba lö aefa-aefa ba gödo razo.', '[]', NULL),
  (3476431, 'OT', 'Danieli', 3, 1, 'Ifafazökhi''ö wamaedo niha Nebukanesa, famaedo ana''a, 60 hela wa''alaŵa ba 6 hela wa''ebolo, ba ndraso, ba Dura, ba danö Mbabeli.', '["Yer 29:22"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 2, 'Ba ifatenge zinenge razo Nebukanesa ba zalaŵa ba khö ndra tua sebua ba ba gumandru ba ba högö zanguhuku ba ba zangirö ana''a ba ba zangila amakhoita ba ba zanguhuku sato ba ba nifatarö ba danö misa, ba halöŵö khö razo, fefu, ifakaoni''ö ira, ba wangaruwusi famaedo niha andrö, nifafazökhi''ö razo Nebukanesa.', '["Yer 29:22"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 3, 'Ba owulo zalaŵa ba ira tua sebua ba kumandru, awö högö zanguhuku ba sangirö ana''a ba sangila amakhoita ba sanguhuku sato, awö nifataro ba danö misa, ba halöŵö khö razo, fefu, ba wangaruwusi famaedo niha andrö, nifafazökhi''ö Nebukanesa, ba la''iagö föna wamaedo andrö.', '["Yer 29:22"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 4, 'Ba mu''ao zi''ao andrö, ebua linia, imane: Da''ö niŵa''ö khömi, ya''ami, ha niha ami, ha soi ami ba hadia limi.', '["Yer 29:22"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 5, 'Ha si''aikö mirongo li dorofe ba li zurune ba li mbiola nitika side-ide ba li mbiola nitika sebua ba li mbiola nifosinali, ba li laigi niwuwusi, ba hadia ia na fefu nifoli, ba mifalögu tou ami, ba wangalulu ba waemaedo niha andrö, nifafazökhi''ö razo Nebukanesa.', '["Yer 29:22"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 6, 'Ba si lö mamalögu tou ya''ia, ba si lö mangalulu, ba ladölö latibo''ö ba mbaho galitö sihola-hola![1]', '["Yer 29:22"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 7, 'Andrö wa la''anema''ö lafalögu tou ira dozi ha niha ira ba ha soi ira ba hadia ngawalö lira, me larongo li dorofe ba li zurune ba li mbiola nitika, side-ide ba sebua ba li mbiola nifosinali, ba hadia ia na, fefu, nifoli, ba wangalulu ba wamaedo niha andrö ana''a, nifafazökhi''ö razo Nebukanesa.', '["Yer 29:22"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 8, 'Ba i''anema''ö so Ndrawa Galedaia, sangadugö Niha Yehuda.', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 9, 'Humede ira, lamane khö razo Nebukanesa: He razo, ya si lö aetu nosou![2]', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 10, 'No öbe''e goroisa, ya''ugö razo, ena''ö lafalögu tou ira niha, fefu, na larongo li dorofe ba li zurune ba li mbiola nitika, side-ide ba sebua ba li mbiola nifosinali ba li laigi niwuwusi, ba hadia ia na, fefu nifoli, ba wangalulu ba wamaedo niha andrö ana''a,', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 11, 'awö wa nitibo''ö ba mbaho galitö sihola-hola zi lö mamalögu tou ya''ia ba si lö mangalulu.', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 12, 'Ba no so ba da''ö Niha Yehuda, nifataromö samatörö öri Mbabeli, ira Saderakhi, Mezakhi, Abedo-Nego. No la''ositengagö goroisamö niha andrö, ya''ugö razo; Lowalangimö, ba lö lafosumange, ba ba wamaedo niha andrö ana''a, nifafazökhi''ömö, ba lö mangalulu ira.', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 13, 'Ba mofönu sibai Nebukanesa, abao dödönia, ba ibe''e li, la''ohe khönia ndra Saderakhi, Mezakhi, Abedo-Nego. Ba me la''ohe ira khö razo, ba humede Nebukanesa,', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 14, 'imane khöra: Hadia, ni''odödögö, ya''ami, ira Saderakhi, Mezakhi, Abedo-Nego, wa lö mifosumange Lowalangigu, awö wa lö mangalulu ami ba wamaedo niha andrö ana''a, nifalau''ögu?', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 15, 'Hiza, na edöna ami mifalögu tou ami, ba wangalulu ba wamaedo niha andrö, nifalau''ögu, na ha si''aikö mirongo li dorofe ba li zurune ba li mbiola nitika, side-ide ba sebua, ba li mbiola si 10 sinali, ba he li laigi niwuwusi, ba hadia ia na, fefu, nifoli, ba lau; ba na lö mangalulu ami, ba ladölö latibo''ö ami ba mbaho galitö sihola-hola, ba ha niha maö Lowalangi, sangila mangefa''ö ya''ami ba dangagu![3]', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 16, 'Ba latema li ira Saderakhi, Mezakhi, Abedo-Nego, lamane khö razo Nebukanesa: Alakha lö matema limö.', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 17, 'Na i''ila i''orifi ndra''aga Lowalangima andrö, nifosumangema, ba i''efa''öga ba mbaho galitö sihola-hola ba ba dangau, ya''ugö razo;[4]', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 18, 'ba na lö''ö, ba ya aboto ba dödöu, ya''ugö razo, wa lö''ö zui mafosumange Lowalangimö, ba lö''ö göi mangalulu ndra''aga ba wamaedo niha andrö ana''a, nifalau''ömö.', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 19, 'Ba mofönu sibai Nebukanesa khö ndra Saderakhi, Mezakhi, Abedo-Nego, oyo mbawania, ba i''oroi''ö ladou''ö galitö, mewitu fa''abölönia mege, si nangea fa''aukhunia föna.', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 20, 'Ba ibe''e göi li ba zabölö zaradadunia, laböbö ndra Saderakhi, Mezakhi, Abedo-Nego, ba wanibo''ö ya''ira ba mbaho galitö andrö.', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 21, 'Ba laböbö niha andrö — lö muheta zaraeŵara ba lembera ba barura, ba hadia ia nukha bö''ö — ba latibo''ö ba mbaho galitö sihola-hola.', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 22, 'Ba me no abe''e sibai goroisa razo ba me no töra wa''abölö galitö, ba mate niha andrö solohe miyaŵa ira Saderakhi, Mezakhi, Abedo-Nego, ibe''e hola-hola galitö andrö;', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 23, 'ba si datölu andrö, Saderakhi ba Mezakhi ba Abedo-Nego, ba aekhu si tou ba mbaho galitö andrö, niböbö.[5]', '["Faigi 2:4","SamI 17:45, Yes 36:20; 37:20","HalZin 4:19","Yes 43:2"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 24, 'Ba tobali dödö razo Nebukanesa, ba i''aliogö maoso; humede ia, imane khö ndra anofulania: Hadia, tenga ha datölu niböböda niha, nitibo''ö ba galitö? Ba latema li razo, lamane khönia: Si ndruhu, razo!', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 25, 'Ba imane khöra: Ba daöfa u''ila iada''e niha, sowaö-waö ba galitö, lö böbö, ba lö hadia zakhozi ira, ba si samösa, ba no hulö nono Lowalangi wamaigida.[6]', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 26, 'Ba möi ba mbawa mbaho galitö andrö sihola-hola Nebukanesa, humede ia, imane: He ya''ami, ira Saderakhi, Mezakhi, Abedo-Nego, ya''ami enoni Lowalangi Fondrege zalaŵa, mi''ae yaŵa, mi''ae ba da''e! Ba laröi galitö ira Saderakhi, Mezakhi, Abedo-Nego,', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 27, 'ba owulo zalaŵa ba ira tua sebua ba kumandru ba anofula razo, ba la''ila, wa no tebai i''a nösi niha andrö alitö, wa lö sakhozi mbura, awö wa lö sadudu nukhara ba he saböu alitö, ba lö''ö, ba khöra andrö.', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 28, 'Ba humede Nebukanesa, imane: Nisuno Lowalangi ndra Saderakhi, Mezakhi, Abedo-Nego, si no mamatenge mala''ikania ba si no mangorifi enoninia andrö, si no abe''e tödö khönia, ba si no manawö oroisa razo, wolulu botora, fa böi lafosumange Lowalangi bö''ö, ba fa böi mangalulu ba Lowalangi bö''ö, ha ba Lowalangira.', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 29, 'Andrö wa no ube''e goroisa: Dozi, ha niha ira, ba ha soi ira, ba hadia ngawalö lira, ha niha zango''aya Lowalangi ndra Saderakhi, Mezakhi, Abedo-Nego, ba ni''ö''ötö, ba omonia, ba nibali''ö oboula, me no lö Lowalangi bö''ö, sangila mangorifi niha, si mane Lowalangira.[7]', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 30, 'Ba ifataro kumandru sebua ba danö Mbabeli ndra Saderakhi, Mezakhi, Abedo-Nego, razo.', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 31, 'Oroisa razo Nebukanesa ba niha fefu, ha soi ira ba hadia ngawalö lira, ba guli danö: Ya ahowu ami!', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 32, 'Omasi ndra''o, ufarongogö dandra andrö ba sahöli-höli dödöda, nilau Lowalangi Fondrege zalaŵa khögu.', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476431, 'OT', 'Danieli', 3, 33, 'Si no ebua sibai dandra andrö khönia, ba si no abölö-bölö sibai zahöli-höli dödöda andrö! Amatöröŵania andrö, ba no amatöröŵa si lö tebulö, irugi zi lö aetu, ba fa''asalaŵania andrö, ba götö-götö wa''ara dania![8]', '["Yob 1:6","Faigi 2:5","Sin 93:1; Faigi 2:44"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 1, '"Ya''odo Nebukanesa ba no sosodo ba nomogu lö fangabu dödö, ha sambalö fa''ohahau dödö khögu ba gödogu.', '["Faigi 2:2"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 2, 'Ba mangifi ndra''o ba tobali dödögu ba tokeado ibe''e era-eragu ba gasogu ba angilata hörögu andrö.', '["Faigi 2:2"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 3, 'Ba ube''e li, la''ohe khögu zonekhe-nekhe ba Mbabeli, fefu, ena''ö la''ombakha''ö khögu geluaha wangifigu andrö.', '["Faigi 2:2"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 4, 'Ba so zebua elemu ba si faeta ba Dawa Galedaia andrö ba sangila eluaha ndröfi, ba utunö khöra wangifigu andrö; ba lö la''ila la''ombakha''ö khögu geluahania.[1]', '["Faigi 2:2"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 5, 'Ba ba gafuriata, ba so Danieli andrö, sotöi Belizasari, wangohia''ö töi Lowalangigu andrö, ba si so Eheha Lowalangi, ni''amoni''ö, ba utunö khönia wangifigu, umane:', '["Faigi 2:2"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 6, 'He Belizasari högö zebua elemu, si so Eheha Lowalangi ni''amoni''ö, u''ila, ba sangila mamokai si no tobini, fefu, fondrondrongo ni''ilagu ba wangifi, ba ombakha''ö khögu geluahania!', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 7, 'Angilata hörögu, ba gasogu, ba ufaigi, ba hiza geu sebua sibai, ba dalu danö.[2]', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 8, 'Ba tedou-dou wa''ebua geu andrö ba fa''esolonia; irugi mbanua si yaŵa hogunia, ba irugi ba wondrege danö oroma ia.', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 9, 'Bulunia, ba no si sökhi ba buania, ba no fahöna, dozi niha zanöndra göra khönia; mörö-mörö ba mbörönia zaliŵa-liŵa ba danö, ba lumö, ba ba ba ndrahania, ba mangazuni wofo ba dalu mbanua, ba ba khönia lasöndra göra fefu zonoso.', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 10, 'Ba u''ila ba gangilata hörögu andrö, ba gasogu, ba hiza moroi yaŵa ba mbanua si yaŵa zanaro ni''amoni''ö; mu''ao ia,', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 11, 'ibe''e li, imane: Mi''obö ge''u andrö ba mitunga ndrahania; miburusi mbulu ba mifazawili mbua! Ena''ö moloi zaliŵa-liŵa ba danö ba mbörönia, ba he fofo ba ndrahania.', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 12, 'Ba börönia, ba niröi ba danö, ba nirate, rate si''öli ba töla, ba mbenua, ena''ö hambunö ia ia namo mbanua, ba ena''ö i''aga''aga ndru''u ba danö, awö zaliŵa-liŵa ba danö.', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 13, 'Tödö niha andrö khönia, ba niheta khönia, ba tödö zaliŵa-liŵa ba danö nibe''e khönia, ba mewitu fakhe wa''ara da''ö khönia.', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 14, 'Nihonogöi zanaro andrö da''ö, ba no oroisa ni''amoni''ö andrö ba da''ö, ena''ö aboto ba dödö niha sauri, wa no ba danga Wondrege zalaŵa so wa''asalaŵa niha ba ibe''e khö zomasi ia, awö wa i''ila göi ifataro salaŵa wondrege zide-ide.[3]', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 15, 'Da''ö wangifi andrö, me mangifi ndra''odo, ya''odo, razo Nebukanesa; ba ya''ugö, Belizasari, ba hadia geluahania? Fefu zonekhe-nekhe ba danögu, ba lö''ö sa la''ila la''ombakha''ö khögu geluaha; ba ya''ugö zangila, me no so khöu Geheha Lowalangi andrö, ni''amoni''ö."', '["Hez 31:3 b.t.","RazI 22:19"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 16, 'Ba tobali dödö Danieli, sotöi Belizasari, ara ma''ifu, abu dödönia, me mangera-era ia. Ba humede razo, imane: He Belizasari, böi tobali dödöu ba wangifi andrö, ba ba geluahania! Ba itema linia Belizasari, imane: He Tua! Ena''ö na si fatiu tödö khöu dandrösa wangifi andrö, ba ena''ö na ba nemaliu tetandrösaigö geluahania!', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 17, 'Eu andrö, ni''ilau, salaŵa ba sesolo, sirugi ba mbanua si yaŵa hogu ba soroma irugi ba wondrege danö fasui,', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 18, 'si sökhi bulu ba si no fahöna bua, irege lasöndra göra dozi si möi khönia, ba zonahia zaliŵa-liŵa ba danö, ba lumö, ba ba zangazuni fofo, ba ndraha, ba ya''ugö da''ö, ya''ugö razo,', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 19, 'sebua ba sabölö, si no tedou-dou fa''ebua, irugi ba mbanua si yaŵa ba sirugi ba wondrege danö fa''abölö.', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 20, 'Ba fangila razo, wa so moroi yaŵa zanaro ni''amoni''ö, sanguma''ö: Mi''obö geu andrö ba mikhökhö, ba börönia, ba miröi ba danö ba mirate, rate si''öli ba töla, ba mbenua, ena''ö hambunö ia namo mbanua, ba ena''ö i''a wöfö gö zaliŵa-liŵa ba danö, irugi mewitu fakhe,', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 21, 'ba da''ö geluahania, ya''ugö razo, — no nihonogöi Wondrege zalaŵa, nifatörö khö zokhö ya''o razo —', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 22, 'latibo''ö dania ndra''ugö niha, ba ba zaliŵa-liŵa ba danö nahiau dania: bulu ndru''u labe''e öu, föfö gö zaŵi, ba si hambunö namo mbanua ndra''ugö, mewitu fakhe wa''ara khöu da''ö, irege aboto ba dödöu, wa no ba danga Wondrege zalaŵa so wa''asalaŵa niha, ba i''ila ibe''e ba zomasi ia.[4]', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 23, 'Ba oroisa andrö, wa lö labulö''ö ba danö mbörö geu andrö, ba eluahania, ba si lö tebulö khöu wa''arazomö; ha si''aikö aboto ba dödöu, wa no abölö zorugo.', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 24, 'Ba andrö, ya''ugö razo, fondrondrongo niŵa''ögu khöu: salahini horöu andrö fa''atulö dödö, ba olalöŵamö, ba salahini fa''ahakhö dödöu zi numana, ma atö ara dania wa''ohahau dödöu.', '["Yer 27:5"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 25, 'Ba itörö razo Nebukanesa da''ö fefu.', '[]', NULL),
  (3476432, 'OT', 'Danieli', 4, 26, 'Döfi aefa da''ö no mege, ba samuza ma''ökhö, ba manörö-nörö razo ba dete gödonia.', '[]', NULL),
  (3476432, 'OT', 'Danieli', 4, 27, 'Ba humede ia, imane: Hadia, tenga Babeli sebua andrö da''e, nitaru''ögu banua razo, ba wa''abölögu, si no maulu, ba ba wangebua lakhömigu!', '[]', NULL),
  (3476432, 'OT', 'Danieli', 4, 28, 'Ba lö saetu na ba mbewe razo niŵa''önia andrö, ba so li si oroi mbanua si yaŵa, imane: Da''ö niŵa''ö khöu, ya''ugö razo Nebukanesa: no aheta khöu wa''asalaŵamö,', '[]', NULL),
  (3476432, 'OT', 'Danieli', 4, 29, 'latibo''ö sa''ae ndra''ugö awöra niha, ba ba zaliŵa-liŵa ba danö nahiamö dania. Bulu ndru''u, föfö gö zaŵi, labe''e öu, ba mewitu fakhe wa''ara da''ö khöu, irege aboto ba dödöu, wa no ba danga Wondrege zalaŵa so wa''asalaŵa niha, ba i''ila ibe''e ba zomasi ia.', '[]', NULL),
  (3476432, 'OT', 'Danieli', 4, 30, 'Ba i''anema''ö itörö Nebukanesa niŵa''ö andrö: latibo''ö ia banuania ba tobali i''aga''aga mbulu ndru''u, föfö gö zaŵi, ba hambunö ia namo mbanua, irege anau mbunia, timba mbu moyo, ba sa''ania, ba tobali timba za''a wofo.', '[]', NULL),
  (3476432, 'OT', 'Danieli', 4, 31, 'Ba me no irugi inötö andrö, ba maoso ndra''o, ya''odo Nebukanesa, ufaöga hörögu ba ifuli motödö ndra''o; ba u''andrö saoha gölö khö Wondrege zalaŵa ba usuno zauri irugi zi aetu ba u''ebua''ö döinia, töi zi so fa''abölö si lö aetu, ba fa''asalaŵania, ba götö-götö wa''ara.', '["Yob 9:12; Yes 40:17; 14:27"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 32, 'Faya manö fefu niha ba guli danö; somasi ia ba ilau, he ba ngahönö andrö ba mbanua si yaŵa, ba he ba niha ba guli danö; ba samösa lö sangila manenaŵa ya''ia, si tola manguma''ö khönia: Hadia nilaumö?[5]', '["Yob 9:12; Yes 40:17; 14:27"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 33, 'Ba i''anema''ö ifuli motödö ndra''odo ba usöndra mangawuli wa''ebuagu föna, awö lakhömigu, fangebua döi wa''asalaŵagu. La''alui ndra''o ira anofulagu ba awögu salaŵa, ba ifuli tefataro razo ndra''odo, ba tebe''e khögu wa''abölö, si tedou moroi me föna.', '["Yob 9:12; Yes 40:17; 14:27"]', NULL),
  (3476432, 'OT', 'Danieli', 4, 34, 'Ba iya''e, ba manunö ndra''o ba u''andrö saoha gölö, ba usuno razo ba zorugo. No si ndruhu wolaunia fefu, ba he lala andrö khönia, ba no satulö, ba sanörö lala hokha, ba i''ila ihöndrögö.', '["Yob 9:12; Yes 40:17; 14:27"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 1, 'Ilau fatome razo Belisasa, fatomesa sebua, hönö nikaoni awönia salaŵa, ba ibadu-badu nagu ba zi so zi hönö andrö.[1]', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 2, 'Ba me no ibörötaigö mabu Mbelisasa, ba iŵa''ö lahalö mako ana''a andrö ba mako firö, nihalö duania Nebukanesa ba gosali ba Yeruzalema, ena''ö la''amadugö ira razo awönia salaŵa ba fo''omonia ba dongania ba döi andrö.[2]', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 3, 'Ba la''ohe khönia mako ana''a andrö, nihalö ba nomo Lowalangi ba Yeruzalema, ba ni''amoni''ö andrö, ba la''amadugö ira razo awönia salaŵa, ba fo''omonia ba dongania ba döi andrö.', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 4, 'Labadu-badu nagu ba lasuno nadu ana''a, awö nadu firö, awö nadu töla, awö nadu si''öli, awö nadu eu, awö nadu kara.', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 5, 'Ba ba da''ö si''aikö oroma duturu danga niha, sanura ba mbagolö nilau betua, ba gamaudu naha wandru, ba mbate''e sebua nihaogö; ba i''ila razo danga andrö, sanura.', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 6, 'Ba ufusi mbawa razo ba tobali dödönia, ba hulö zadeha zolania ba manizi-nizi mbalöduhinia.', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 7, 'Ba mu''ao razo, ebua linia, ena''ö lafakaoni''ö zi faeta ba Dawa Galedaia ba sangila eluaha ndröfi. Ba humede razo, imane ba zonekhe-nekhe andrö, ba Mbabeli: Ha niha zangila mombaso sura ba sangila mangombakha khögu eluahania, ba lafobaru baru luo ba labe''e ba mbaginia naya ana''a, ba labe''e fahandrona ba gamatöröŵa razo ia.', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 8, 'Ba möi yomo zonekhe-nekhe andrö khö razo, fefu, ba lö sangila mombaso sura ba he fangombakha khö razo hadia geluaha.', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 9, 'Ba tobali sibai dödö razo Belisasa, afusi mbawania, ba awönia salaŵa göi, ba fawuka manö dödö.', '["Yer 27:7; 51:39,57","Faigi 1:2"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 10, 'Ba me irongo ina razo huhuora awönia salaŵa, ba möi ia ba mbate''e wemanga andrö. Humede ia, imane khö razo: He razo, ya si lö aetu nosou! Böi busi dödöu ba böi afusi mbawau![3]', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 11, 'So niha ba mbanuau, si so Eheha Lowalangi andrö, ni''amoni''ö; me luo razo duau, ba no lasöndra, wa no so khönia haga ba tödö satua-tua ba fa''atua-tua Lowalangi; ba tuau, razo Nebukanesa, ba no ifataro ia högö ba zebua elemu ba ba zi faeta, ba ba Ndrawa Galedaia ba ba zangila eluaha ndröfi — tuau andrö, ya''ugö razo! —[4]', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 12, 'Me no la''ila, wa Eheha si sökhi zi so khö Danieli andrö, ba fa''aboto ba dödö ba fangila eluaha wangifi ba eluaha dahö-dahö ba famokai si no tobini, khö Danieli andrö, nifotöi razo "Belizasari." Andrö öfakaoni''ö Danieli andrö, ba i''ombakha''ö khöu geluaha zura andrö.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 13, 'Ba la''ohe khö razo ba gödo Danieli. Ba humede razo, imane khö Danieli: Hadia, ya''ugö Danieli andrö, awö ni''oloi''ö andrö, Niha Yehuda, banua mado Yuda, ni''oloi''ö duagu razo [Nebukanesa]?', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 14, 'No urongo ndra''ugö, wa no so khöu Geheha Lowalangi, awö wa no mu''ila khöu haga ba fa''atarö dödö ba fa''atua-tua, si no maulu.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 15, 'No faefa mege la''ohe khögu zonekhe-nekhe ba si faeta, ba wombaso sura andrö, ba ba wangombakha khögu eluahania; ba lö la''ila geluaha, tebai la''ombakha''ö khögu.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 16, 'Ba no urongo ndra''ugö, wa ö''ila ö''ombakha''ö geluaha hadia ia ba ö''ila öbokai zi no tobini. Ba iya''e, ba na ö''ila öbaso zura andrö, ba na ö''ila ö''ombakha''ö khögu geluahania, ba lafobaru baru luo ndra''ugö, ba labe''e ba mbagiu naya ana''a, ba labe''e fahandrona ndra''ugö, ba gamatöröŵagu!', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 17, 'Ba imane Danieli khö razo: Buala andrö, ba alakha lö öbe''e khögu, ba ame''elamö andrö, ba hana na ba mbö''ö öbe''e; ba ubaso sa khö razo zura andrö, ba u''ombakha''ö khönia hadia geluaha.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 18, 'He razo! Fondrege Lowalangi andrö, ba no ibe''e khö duau Nebukanesa wa''asalaŵa ba fa''abölö ba sumange ba fa''ebua döi.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 19, 'Ba ba wa''abölö andrö, nibe''enia khönia, ba manizi-nizi niha fefu, ha soi ira ba hadia ngawalö lira, ba la''ata''ufi ia. Tola ibunu zomasi ia ba tola i''orifi zomasi a; tola ibe''e salaŵa zomasi ia, ba tola ihöndrögö zomasi ia.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 20, 'Ba me fayaŵa dödönia, me tesao hokhania, irege zi tenga inötö, ba tetimba ia ba dadaoma razo, ba aheta khönia wa''arazonia.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 21, 'Latibo''ö ia awönia niha, ba tödönia, ba tobali timba dödö zaliŵa-liŵa ba danö, ba ngai galide gatua nahiania, ba labe''e önia mbulu ndru''u, föfö gö zaŵi; hambunö nösinia namo mbanua, irege aboto ba dödönia, ba danga wondrege Lowalangi so wa''asalaŵa niha ba somasi ia ifataro salaŵa.[5]', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 22, 'Ba ya''ugö, Belisasa, ma''uwunia, ba no lö ni''ide-ide''ömö ya''ugö, he ŵa''ae no örongo da''ö fefu,', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 23, 'no ölaŵa Zo''aya ba zorugo; mako andrö, ba gosalinia, ba no ö''oroi''ö khöu, ena''ö mi''amadugö, ya''ugö ba awöu salaŵa ba fo''omou ba dongau ba döi andrö, wamadu agu; ba no ösuno nadu firö, awö nadu ana''a, awö nadu töla, awö nadu si''öli, awö nadu eu, awö nadu kara, si lö mangila niha, ba si lö mamondrongo li niha ba si lö tödö; ba Lowalangi andrö, si so ba danga nosou, ba si no balazi ba zanörö ya''ugö fefu, ba no lö nifosumangeu.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 24, 'Da''ö mbörö, wa no ifatenge duturu danga andrö, ba wanura sura andrö ba da''ö.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476433, 'OT', 'Danieli', 5, 25, 'Ba nisura andrö ba da''ö, ba: Mene, mene, tekel, upharsin.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 26, 'Ba eluaha li andrö, ba: "mene", ba: No i''erai wa''arazomö Lowalangi, ba no i''etu''ö.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 27, 'Ba "tekei", ba: No latulo ndra''ugö ba waliera, ba no lasöndra, wa no abölö aoha ndra''öegö,', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 28, '"peres", (upharsin) ba: No lafaosa gamatöröŵamö ba no labe''e ba Ndrawa Media ba ba Ndrawa Weresia.', '["Faigi 2:4","Faigi 2:48; 4:6","Faigi 4:22"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 29, 'Ba ibe''e li Belisasa, lafobaru baru luo Danieli ba labe''e ba mbaginia naya ana''a andrö, ba lafarongogö ba niha, wa nibe''e salaŵa ia ba gamatöröŵa razo, fahandrona.', '["Yes 21:1 b.t.; 47:11; Yer 51:53"]', NULL),
  (3476433, 'OT', 'Danieli', 5, 30, 'Ba ba zi bongi andrö, ba labunu Mbelisasa andrö, razo Ndrawa Galedaia.[6]', '["Yes 21:1 b.t.; 47:11; Yer 51:53"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 1, 'Ba Dario, Dawa Media, zi tobali razo, me no 52 fakhe, wa''atuania.', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 2, 'Ba omasi Dario andrö, 120 ifataro kumandru, ba gamatöröŵania ma''asagörö, ifosasi.', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 3, 'Ba datölu ibe''e högöra tua sebua, samösa Danieli, ena''ö la''ombakha''ö ba da''ö kumandru andrö, he wisa, fa böi manö te''ala razo.', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 4, 'Ba högö zui Danieli, högö dua sebua andrö, ba högö gumandru fefu, me no so khönia Geheha sebua; ba tödö razo sa''ae: ibe''e barö mbawa Danieli gamatöröŵania ma''asagörö.', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 5, 'Ba la''alui sibai ira tua sebua andrö, awö gumandru, nibe''e esuanö Danieli ba halöŵönia famatörö andrö. Ba lö lasöndra hadia ia gesuanö, ba he hadia ia zi lö sökhi, me no lö falimosa khö Danieli, ba he fa''areu ba he bö''önia si lö sökhi, ba lö lasöndra khönia.', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 6, 'Ba lamane niha andrö: Lö tasöndra mbörö khö Danieli andrö, na tenga ba wolo''önia oroisa Lowalangira.', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 7, 'Ba mangandrö sibai ira khö razo, ira tua sebua andrö, awö gumandru, lamane khönia: He razo Dario! Ya si lö aetu nosou![1]', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 8, 'No mamagölö ndra tua sebua fefu ba gamatöröŵamö, ba satua ba kumandru ba ira anofulamö ba kumandra, ena''ö ibe''e goroisa razo ba ena''ö ifeta''u niha: dozi ira, na so zangandrö hadia ia, he khö Lowalangi, ba he ba niha, na tenga khöu, ya''ugö razo, 30 wongi wa''ara, ba nitibo''ö ba lösu-lösu, nahia zingo.', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 9, 'Ba iya''e, ya''ugö razo, ba be''e goroisa andrö, ba fa''ohe''ö zura, sura goroisa, si tebai awu''a, dali lala goroisa andrö ba Ndrawa Media ba ba Ndrawa Weresia, si tebai lawu''ai.[2]', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 10, 'Ba ifasura''ö goroisa andrö, awö wameta''u no mege razo Dario.', '["Faigi 2:4","Esit 1:10; 8:8"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 11, 'Ba me irongo Danieli, wa no mube''e goroisa andrö, ba möi ia ba nomonia, ba no teboka zandrela ba mbate''e ba zi sagötö khönia, si otahögö Yeruzalema; ba medölu ma''ökhö ibalöduhini tou zalo, mangandrö ia khö Lowalanginia ba isuno Lowalangi, lö ibulö''ö zi no to''ölö ia.[3]', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 12, 'Ba fagohi moroi tou niha no mege ba la''ila, me mangandrö Danieli ba fakaosania khö Lowalangi.', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 13, 'Ba möi ira khö razo ba lasofu khönia, ba goroisania andrö, lamane: Hadia, tenga no öbe''e goroisa nitanö ba zura, wa nitibo''ö ba lösu-lösu nahia zingo dozi sangandrö hadia ia, he khö Lowalangi, ba he ba niha, na tenga khöu, ya''ugö razo, 30 wongi wa''ara? Ba itema lira razo, imane: Ya''ia, no muhonogöi da''ö, dali goroisa ba Ndrawa Media ba ba Ndrawa Weresia, si tebai awu''a.', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 14, 'Ba lamane khö razo: Ba Danieli andrö, awö ni''oloi''ö andrö, Niha Yehuda, ba no i''ositengagö ndra''ugö, ya''ugö razo, ba he oroisa andrö, nibe''eu; medölu ma''ökhö mangandröngandrö ia.', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 15, 'Ba me irongo da''ö razo, ba abu sibai dödönia, ba i''alu-alui tödönia, he iwisa wangorifi Danieli; irugi aekhu, luo i''alui lala, ba wangefa''ö ya''ia.', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 16, 'Ba laforege khö razo niha no mege, lamane khönia: Böi zi lö aboto ba dödöu, ya''ugö razo, wa no huku ba Ndrawa Media ba ba Ndrawa Weresia, wa tebai awu''a na so nitenaŵa razo, ba he ni''oroi''önia, fefu gofu hadia ia!', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 17, 'Awena ibe''e li razo, lahalö Danieli, ba wanibo ba lösu-lösu nahia zingo. Ba humede razo, imane khö Danieli: Yamu''orifi''ö Lowalangimö andrö, nifosumangeu, si lö mamalö-malö!', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 18, 'Ba la''ohe gowe, duhöduhö mbawa lösu-lösu andrö, ba ifotandro razo, tandronia ba tandro nawönia salaŵa, ena''ö böi awu''a nihuku andrö ba khö Danieli.[4]', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 19, 'Ba möi ba gödonia razo, ba mamoni ia ba zi bongi andrö; lö ifa''amöi si bakha ndra alawe; ba lö alau hörönia.', '["RazI 8:48; Sin 55:18","Mat 27:66"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 20, 'Ba me moluo, me afusi wali, ba maoso razo, ba i''aliogö isaŵa lösu-lösu nahia zingo.', '["Faigi 3:25; Heb 11:33"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 21, 'Ba me lö aröu tö irugi lösu-lösu, ba mu''ao ia khö Danieli, timba ze''e. Humede razo, imane khö Danieli: He Danieli, enoni Lowalangi sauri andrö, hadia, no i''ila itimba khöu zingo andrö Lowalangiu andrö, nifosumangeu, si lö mamalö-malö?', '["Faigi 3:25; Heb 11:33"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 22, 'Ba humede Danieli, imane khö razo: He razo! Ya si lö aetu nosou!', '["Faigi 3:25; Heb 11:33"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 23, 'No ifatenge mala''ika khönia Lowalangigu, ba no ikusi mbawa zingo, fa böi labunu ndra''o, me no lö horögu i''ila, ba he khöu göi, ya''ugö razo, ba lö lalögu.[5]', '["Faigi 3:25; Heb 11:33"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 24, 'Ba omuso sibai dödö razo, ba iŵa''ö lahalö yaŵa Danieli, moroi ba lösu-lösu. Ba me lahalö yaŵa ia, ba ma''ifu lö lasöndra sesokho ia, me no abe''e dödönia khö Lowalanginia.', '["Faigi 3:25; Heb 11:33"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 25, 'Ba iŵa''ö razo, latibo''ö ba lösu-lösu nahia zingo niha andrö, sangadugö Danieli mege. Ba la''ohe ba latibo''ö si tou, fabaya fo''omora ba iraonora; ba lö sikoko ira ba doyo lösu-lösu, ba lara''u sa''ae ira singo, ba larasa dölara fefu.', '["Faigi 3:25; Heb 11:33"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 26, 'Ba ifa''ohe''ö zura razo Dario, ba niha fefu, ha soi ira ba hadia ngawalö lira, ba guli danö misa, ma''asagörö, imane: "Ya ahowu ami![6]', '["Faigi 3:31","Faigi 2:44","Faigi 1:21"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 27, 'Da''ö niŵa''ögu khömi: ba gamatöröŵagu ma''asagörö, ba khö Lowalangi Danieli manizi-nizi ami ba ya''ia mi''ata''ufi. Me no ya''ia Lowalangi sauri, si lö tebulö, irugi zi lö aetu; amatöröŵania, ba no si tebai adudu, ba fa''asalaŵania, ba si lö aetu.[7]', '["Faigi 3:31","Faigi 2:44","Faigi 1:21"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 28, 'I''ila i''orifi niha ba i''ila i''efa''ö, ifazökhi dandra ba ilau zahöli-höli dödö, ba mbanua si yaŵa ba ba guli danö tou, ya''ia andrö, si no mangefa''ö Danieli ba wa''abölö zingo andrö".', '["Faigi 3:31","Faigi 2:44","Faigi 1:21"]', NULL),
  (3476434, 'OT', 'Danieli', 6, 29, 'Ba Danieli andrö, ba sohahau tödö, barö mbawa Dario andrö, ba he barö mbawa Giro, Dawa Weresia andrö, dania.[8]', '["Faigi 3:31","Faigi 2:44","Faigi 1:21"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 1, 'Ba me lö döfi na razo Mbabeli Belisasa, ba mangifi Danieli, so gangilata hörönia, ba gasonia. Ba itanö ba zura wangifi andrö, tuhonia.[1]', '["Faigi 2:29","Yes 17:12","Yer 4:7; Faigi 2:13","Faigi 5:28; 8:3","Faigi 8:5,21,22","Faigi 2:40,41"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 2, 'Humede Danieli, imane: Ni''ilagu ba zi bongi ba wangifigu, ba ilabu angi, isaŵa nasi sebua, öfa nangi mbanua si yaŵa.[2]', '["Faigi 2:29","Yes 17:12","Yer 4:7; Faigi 2:13","Faigi 5:28; 8:3","Faigi 8:5,21,22","Faigi 2:40,41"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 3, 'Ba so moroi tou ba nasi zaliŵa-liŵa ba danö sebua sibai, öfa nga''eu ba no fazambuzambua.', '["Faigi 2:29","Yes 17:12","Yer 4:7; Faigi 2:13","Faigi 5:28; 8:3","Faigi 8:5,21,22","Faigi 2:40,41"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 4, 'Si föföna, ba no hulö zingo, ba no mo''afi moyo. Ba ufaigi-faigi manö ia: ba tedeha gafinia ba tefasindro ia, moroi ba danö, tefazizio ba gahenia si dua, hulö niha ba tebe''e khönia dödö niha.[3]', '["Faigi 2:29","Yes 17:12","Yer 4:7; Faigi 2:13","Faigi 5:28; 8:3","Faigi 8:5,21,22","Faigi 2:40,41"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 5, 'Ba aefa da''ö, ba so zageu tö, dua geu, möi da''ö, ba si hulö mberua da''ö; ba si tambainia, ba no sisindro, ba ba mbawania, ba tölu rozi döla nosu, ba nifönia, ba so zanguma''ö khönia: Labu, oya''ö wemanga nagole hadia ia![4]', '["Faigi 2:29","Yes 17:12","Yer 4:7; Faigi 2:13","Faigi 5:28; 8:3","Faigi 8:5,21,22","Faigi 2:40,41"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 6, 'Ba ufaigi, ba oroma zageu tö, si hulö harimo, ba öfa gafi wofo ba hulunia; ba öfa göi högönia, ba no mube''e khönia wa''abölö.[5]', '["Faigi 2:29","Yes 17:12","Yer 4:7; Faigi 2:13","Faigi 5:28; 8:3","Faigi 8:5,21,22","Faigi 2:40,41"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 7, 'Ba aefa da''ö, ba u''ila ba gangilatagu ba zi bongi, ba sageu tö zi so moroi tou sata''u ita ba sihokha mbuda, ba sabölö sibai. Si''öli nifönia, sebua sibai; i''aga''aga gönia ba ibohagö; ba si tosai, ba ihundra-hundra tou. Ba no faehu ia ba da''ö no mege fefu, ba fulu rozi dandrunia.[6]', '["Faigi 2:29","Yes 17:12","Yer 4:7; Faigi 2:13","Faigi 5:28; 8:3","Faigi 8:5,21,22","Faigi 2:40,41"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 8, 'Ba utöngö sibai dandru andrö, ba hiza dandru bö''ö side-ide si tumbu ba gotalua, ba tölu rozi nideha tandru no mege, si föföna, börö zide-ide andrö; ba hiza, ba si so hörö dandru andrö, hulö hörö niha; ba noa göi mobawa solau fayaŵasa.', '["Faigi 2:29","Yes 17:12","Yer 4:7; Faigi 2:13","Faigi 5:28; 8:3","Faigi 8:5,21,22","Faigi 2:40,41"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 9, 'Ba ufaigi-faigi, irugi tefedadao ba da''ö dadaoma zalaŵa ba irege dumadao "zatua andrö," si no arara: barunia, ba no si takile, afusi, fa''afusi mbetua, ba bunia, ba no timba zi ndruhu mbu mbiri-biri, ba dadaomania, ba hola-hola galitö, ba no moroda alitö sihola-hola.[7]', '["Hez 1:16; Mat 19:28; Fam 20:4","Sin 68:18; Fam 4:5; Fam 20:12","Fam 19:20","Hez 1:26; Mark. 13:26; HalZin 1:11; Fam 1:13; 14:14","Sin 2:6; 110:2; Faigi 2:44; Fil 2:9"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 10, 'Ba hulö zahele misa galitö, sebua, si otarai ia; mehönö wa hönö ngoni-ngoninia, ba mewulu ngahönö wa fulu ngahönö zi so ba ngainia. Ba dumadao zanguhuku ba labokai zura.[8]', '["Hez 1:16; Mat 19:28; Fam 20:4","Sin 68:18; Fam 4:5; Fam 20:12","Fam 19:20","Hez 1:26; Mark. 13:26; HalZin 1:11; Fam 1:13; 14:14","Sin 2:6; 110:2; Faigi 2:44; Fil 2:9"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 11, 'Ba ufaigi-faigi manö — börö wayaŵasa andrö, huhuo dandru andrö, sebua li — ufaigi-faigi manö, irege labunu zaliŵa-liŵa ba danö andrö, ba irege lafakiko mbotonia, ba irege latibo''ö ba galitö si hola-hola.[9]', '["Hez 1:16; Mat 19:28; Fam 20:4","Sin 68:18; Fam 4:5; Fam 20:12","Fam 19:20","Hez 1:26; Mark. 13:26; HalZin 1:11; Fam 1:13; 14:14","Sin 2:6; 110:2; Faigi 2:44; Fil 2:9"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 12, 'Ba he ba nawönia saliŵa-liŵa ba danö andrö, ba teheta wa''abölö, ba te''ötö khöra mbongi ba inötö, ha wa''anau nosora.', '["Hez 1:16; Mat 19:28; Fam 20:4","Sin 68:18; Fam 4:5; Fam 20:12","Fam 19:20","Hez 1:26; Mark. 13:26; HalZin 1:11; Fam 1:13; 14:14","Sin 2:6; 110:2; Faigi 2:44; Fil 2:9"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 13, 'Ba ni''ilagu na ba gangilata andrö, ba zi bongi, ba so moroi sa, ba lawuo ba mbanua si yaŵa, zi hulö niha, ba irugi zatua no mege, te''ohe khönia.[10]', '["Hez 1:16; Mat 19:28; Fam 20:4","Sin 68:18; Fam 4:5; Fam 20:12","Fam 19:20","Hez 1:26; Mark. 13:26; HalZin 1:11; Fam 1:13; 14:14","Sin 2:6; 110:2; Faigi 2:44; Fil 2:9"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 14, 'Ba ba da''ö tebe''e sa''ae wa''abolo ba fa''ebua döi ba fa''asalaŵa: enoninia niha fefu, ha soi ira ba hadia ngawalö lira; ba fa''abölönia andrö, ba sirugi si lö aetu ba si lö tebulö, ba amatöröŵania andrö, ba lö''ö manö adudu.[11]', '["Hez 1:16; Mat 19:28; Fam 20:4","Sin 68:18; Fam 4:5; Fam 20:12","Fam 19:20","Hez 1:26; Mark. 13:26; HalZin 1:11; Fam 1:13; 14:14","Sin 2:6; 110:2; Faigi 2:44; Fil 2:9"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 15, 'Ba ya''o, Danieli, ba sabu sibai bakha tödö; tobali dödögu ibe''e angilata hörögu andrö.', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 16, 'Ba u''ondrasi zamösa, si so ba da''ö, ba u''andrö khönia, ena''ö i''ombakha''ö khögu zi ndruhu geluaha da''ö fefu. Ba itema ligu, i''ombakha''ö khögu geluaha ni''ilagu andrö, imane:', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 17, 'Saliŵa-liŵa ba danö andrö, sebua sibai, si öfa nga''eu, ba daöfa dania razo ba guli danö;', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 18, 'ba ni''amoni''ö andrö khö Wondrege zalaŵa dania zanema fa''asalaŵa, ba khöra manö dania lö tebulö, götö-götö wa''ara.', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 19, 'Ba omasido, na urongo geluaha zaliŵa-liŵa ba danö andrö, fanete zi tölu, si no faehu ba nawönia andrö, fefu, ba sata''u sibai ita, si so ifö si''öli ba sa''a töla garamba, si manga-manga gönia ba samohagö, ba si hundra-hundra tou si tosai,', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 20, 'ba eluaha dandru andrö si fulu, ba högönia, ba eluaha dandru si sara andrö, si tumbu [ba gotalua], ba zabo''a si tölu rozi, tandru andrö, si so hörö ba si so bawa, si so huhuo fayaŵasa, ba si no aröu ebua moroi ba nawönia, wamaigida.', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 21, 'Ba noa göi u''ila: Isuwö ni''amoni''ö andrö tandru andrö, ba ya''ia zabölö,[12]', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 22, 'ba ba gafuriata ba so "zatua" no mege, ba te''ohe ba lala huhuo niha ni''amoni''ö andrö khö Wondrege zalaŵa, ba inötö sa''ae, wa möi ba ni''amoni''ö andrö wa''asalaŵa.', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 23, 'Ba imane khögu: Saliŵa-liŵa ba danö andrö, fanete si tölu, ba no amatöröŵa fanete zi tölu, si no faehu ba gamatöröŵa bö''ö fefu, si tumbu ba guli danö dania, ba i''a danö ma''afefu ba ihundra-hundra ba ifufu.', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 24, 'Ba tandru andrö si fulu rozi, ba dafulu dania razo ba gamatöröŵa andrö, ba aefa da''ö, ba so zamösa tö, si faehu ba zi so mege, fönania, ba datölu itimba razo.[13]', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 25, 'Ba ilau huhuo fayaŵasa khö Wondrege zalaŵa, ba ifakao ni''amoni''ö andrö khö Wondrege zalaŵa; iwai dania tola iwu''ai ginötö ba oroisa; ba döfi ba mendrua fakhe ba matonga ndröfi tebe''e dangania ira.[14]', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 26, 'Ba dumadao sa dania zanguhuku; ba teheta khönia wa''abölönia, adudu ba afufu, si maulu.', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 27, 'Ba tebe''e sa''ae dania ba niha ni''amoni''ö khö Wondrege zalaŵa wa''asalaŵa ba fa''abe''e ba fa''abölö, ba gamatöröŵa andrö, ba guli danö ma''asagörö; amatöröŵania, ba amatöröŵa si lö tebulö, götö-götö wa''ara, ba tobali ngoni-ngoninia zalaŵa fefu, barö mbawania ira.', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476435, 'OT', 'Danieli', 7, 28, 'Awai ni''ombakha''önia khögu. Ba ya''odo, Danieli, ba si tobali tödö, afusi mbawagu; ba utanö ba dödögu da''ö no mege.', '["Fam 11:7; 13:7","Fam 17:12","Faigi 12:7; Fam 12:14; 13:5"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 1, 'Ba me no töra mendrua fakhe razo Belisasa, ba so gangilatagu bö''ö, ya''odo Danieli andre, me no aefa gangilata si sambua no.[1]', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 2, 'U''ila ba gangilata andrö, ba hulö ba gödo ba Zusa, ba danö Gelama, sodo, me u''ila; ba u''ila ba gangilata andrö, wa no ba mbewe Gula''i sodo.[2]', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 3, 'Ba me ufaöga hörögu, ba hiza mbiri-biri si matua, si dua rozi tandru, ba mbewe nidanö, ba si sara tandrunia sanau andrö, ba no anau na moroi ba zi sara; ba sanau andrö, ba safuria manöi.[3]', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 4, 'Ba u''ila, me fatandru mbiri-biri si matua andrö, tanö ba gaekhula luo ba miyöu ba miraya; ba lö saliŵa-liŵa ba danö sangila molaŵa ya''ia. Lö sangefa''ö ba wa''abölönia; ilau zomasi ia, ba itugu abölö sibai.', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 5, 'Ba me ufaigi sibai na, ba hiza nambi si matua, moroi ba gaekhula luo, itörö guli danö ma''asagörö, ba lö manandrösa ba danö gahenia; ba ba nambi andrö, ba sara dandru si tenga inötö fa''anau, ba mbörö nikhunia.[4]', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 6, 'Ba i''ondrasi mbiri-biri si matua andrö, si dua rozi tandru, niilagu mege, ba mbewe nidanö ba itandru, sofönu ia, ba a''oi dölania.', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 7, 'U''ila, wa no ngai mbiri-biri itandru; abao sibai dödönia ba i''olobigö ia ba mbiri-biri andrö, afatö dandru, ma''adua rozi, ibe''e; ba me no ambö wa''abölö mbiri-biri, ba wolaŵa ya''ia, ba ituli''ö tou ba ihundra-hundra, ba lö sangefa''ö biri-biri ba wa''abölönia andrö.', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 8, 'Ba itugu abölö sibai nambi andrö, ba me no irugi wondrege wa''abölönia, ba afatö dandru sanau andrö, ba öfa zi tumbu tandru bö''ö ba nahania, miraya ba miyöce ba tanö ba gatumbukha luo, ba tanö ba gaekhula.', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 9, 'Ba ba zi sara, ba tumbu dandru side-ide, sanöínöi sibai miraya ba tanö ba gatumbukha luo ba tanö ba wondrege zi sökhi tanö andrö.[5]', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 10, 'Ba ilaŵa ngahönö ba mbanua si yaŵa, ba atoru ösa ibe''e, ba döfi ösa atoru ba danö ba ihundra-hundra.', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 11, 'Ba he salaŵa ngahönö andrö, ba ilaŵa; tobali lö''ö sa''ae labe''e ba da''ö zumange, nibe''e-be''e khönia mege, ba ladudugö naha ni''amoni''ö khönia.[6]', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 12, 'Ba börö golalöŵa andrö, wa no ngahönö nilulu, fabaya sumange andrö, sero ma''ökhö; ba ituli''ö tou zi duhu, ba mofozu wolaunia.', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 13, 'Ba urongo zihede, ni''amoni''ö, ba ni''amoni''ö bö''ö zanofu khö zihede andrö, imane: Ha wa''ara gangilata andrö, fa''atebato zumange andrö, nibe''e-be''e mege ba fanao horö andrö, götö wa no ilulu nihundra-hundra naha ni''amoni''ö andrö, awö ngahönö andrö?', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 14, 'Ba itema linia, imane: Dua ngahönö a tölu ngaotu wongi, ba te''azökhi zui naha ni''amoni''ö andrö.', '["Faigi 7:1","Neh 1:1; Esit 1:2","Faigi 5:28; 7:5","Faigi 7:6","Faigi 7:8; Sin 106:24; Hez 20:6","Yos 5:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 15, 'Ba me no u''ila gangilata andrö, ya''odo Danieli, ba me u''alu-alui hadia geluahania, ba hiza niha, ba gametahögu, ira matua wamaigigu.', '["Faigi 9:21; Luk 1:26","Hez 1:28"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 16, 'Ba urongo li niha, si otarai nungo Gula''i, mu''ao ia, imane: He Gaberieli! ombakha''ö khönia andrö geluaha gangilata andrö![7]', '["Faigi 9:21; Luk 1:26","Hez 1:28"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 17, 'Ba so ia, i''iagö ba ngaigu, ba tokea ndra''o, me so ia, ba ufalögu tou ndra''o. Ba imane khögu: Fondrondrongo, ono niha, me ba götö safuria dania itörö gangilata andrö.[8]', '["Faigi 9:21; Luk 1:26","Hez 1:28"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 18, 'Ba me fahuhuo ia khögu, ba tobali hulö zi ono matelö ndra''o, si no telögu tou ba danö; ba ituyu ndra''o, ifazizio ndra''odo, ba zi sodo mege.', '["Faigi 9:21; Luk 1:26","Hez 1:28"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 19, 'Ba imane khögu: Da''u''ombakha''ö khöu, he wisa dania, na alö sa''ae wönu Lowalangi, me no ba götö safuria tetandrösaigö ia.', '["Faigi 9:21; Luk 1:26","Hez 1:28"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 20, 'Biri-biri si matua andrö, ni''ilau, si dua rozi tandru, ba no razo Ndrawa Media, fabaya Dawa Weresia.', '["Faigi 9:21; Luk 1:26","Hez 1:28"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 21, 'Ba nambi si matua andrö, sanau bu, ba no razo Ndrawa Heleni. Ba tandrunia andrö, sanau, ba mbörö nikhu, ba ya''ia zi a''a razora.', '["Faigi 9:21; Luk 1:26","Hez 1:28"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 22, 'Ba fa''afatönia, awö wa no öfa rozi zi tumbu ba nahania, ba öfa gamatöröŵa dania zi so barö mbawania mege, lö lai wa sambö fa''abölö dania ira, moroi khönia mege.', '["Faigi 9:21; Luk 1:26","Hez 1:28"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 23, 'Ba ba gamozua wa''asalaŵara dania, na no lafönui zu''a-su''a sanao horö andrö, ba so zalaŵa safaito, sangila köiköi fefu.', '["Faigi 11:24","Hez 12:27; Faigi 10:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 24, 'Sabölö sibai ia dania, ba tenga sa fa''abölö si to''ua khönia; famakiko si tenga inötö ilau, ba sofozu wolaunia; sabölö ifakiko, ba tödönia dania, ena''ö i''ila ihori ni''amoni''ö andrö.', '["Faigi 11:24","Hez 12:27; Faigi 10:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 25, 'Ba falimosa andrö, nifakhainia, ba mofozu, si fayaŵa ia ba ato ifakiko, si lö mudöna-döna, ba ilaŵa Wondrege zalaŵa, ba nirasa dania ia, ba tenga moroi ba danga [niha].[9]', '["Faigi 11:24","Hez 12:27; Faigi 10:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 26, 'Ba angilata andrö, nifa''ele''ö — ha uga bongi ia — ba no si ndruhu; ba ya''ugö, ba böi ombakha''ö gangilata andrö, me no ba götö saröu mitou dania tetandrösaigö.[10]', '["Faigi 11:24","Hez 12:27; Faigi 10:14"]', NULL),
  (3476436, 'OT', 'Danieli', 8, 27, 'Ba ya''odo, Danieli, ba mofökhö, ha uga bongi. Ba aefa da''ö, ba ifuli abe''e ndra''o, ba u''ila uhalö halöŵögu khö razo; ba no sahöli-höli sibai tödö ndra''o ba gangilata andrö, lö lai wa lö aboto ba dödögu ia.', '["Faigi 11:24","Hez 12:27; Faigi 10:14"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 1, 'Ba me lö döfi na Dario andrö, Dawa Media, ono Gahasiwero, si no tobali razo Ndrawa Galedaia, me lö''ö na döfi razo ia,', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 2, 'ba ufaigi, ya''odo Danieli, ba zura, ha me uga fakhe, niŵa''ö Yehowa khö Yeremia sama''ele''ö, si lö tebulö, wa adudula Yeruzalema, 70 fakhe.[1]', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 3, 'Ba u''otahögö Lowalangi So''aya, mamoni ndra''o, u''obaru gonigoni ba mudadaodo bawu, ena''ö usöndra wangandrö ba fakaosa khönia.[2]', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 4, 'Mangandrö ndra''o khö Lowalangigu Yehowa, u''ombakha''ö lalöda, umane: "He So''aya, Lowalangi sebua ba sata''u ita, si lö mowu''ai fawu''usa li andrö ba fa''ahakhö dödö ba zomasi ya''ugö, ba zolo''ö oroisamö![3]', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 5, 'No mamazökhi horö ndra''aga ba no malau zi lö atulö; no sebua horö ndra''aga ba no malaŵa ndra''ugö, no masawö goroisamö ba amakhöitamö.[4]', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 6, 'Noa göi lö nifondrondrongoma li genonimö, sama''ele''ö andrö, sama''ema niŵa''öu ba razoma ba ba zalaŵama ba khö ndra tuama ba ba niha ba danö, fefu.', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 7, 'Ba ya''ugö So''aya, ba si no a''oi so fa''atulö, ba no safusi bawa fa''aila mado Yuda ba banua Yeruzalema ba Iraono Gizeraeli fefu, he ba zahatö, ba he ba zaröu, ba danö andrö fefu misa, ba nifazaeweu ya''ira, börö wa no la''erogö ndra''ugö.', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 8, 'He So''aya, saila ndra''aga, ya''aga ba razoma ba salaŵama ba ira tuama, me no molalöga khöu.', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 9, 'Ba no khö Zo''aya, Lowalangima, so wa''ahakhö dödö ba fangefa horö. Noa sa molaŵa ndra''aga khönia,', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 10, 'ba lö nifondrondrongoma li Lowalangima Yehowa, ba wanörö ena''ö lala nifakhoinia nifarongogönia khöma ba genoninia sama''ele''ö andrö.', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476437, 'OT', 'Danieli', 9, 11, 'Iraono Gizeraeli fefu, ba no lasaŵö goroisamö, no lö ni''o''öra khöu, no la''erogö ndra''ugö. Ba no göna ndra''aga fangelifi andrö ba fahölusa, si so ba zura goroisa andrö khö Moze, enoni Lowalangi, me no molalö ndra''aga khönia.[5]', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 12, 'No ifatörö ba niŵa''önia, fameta''u ya''aga ba salaŵama, samatörö ya''aga, wa ifatörö dania khöma wamakao sebua, si lö murai mulau ba guli danö, ha ba Yeruzalema.[6]', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 13, 'Itörö manö zi so ba zura goroisa andrö khö Moze, no gönaga famakao andrö, fefu. Ba lö ni''alösima tödö Lowalangima Yehowa, lö nifalalinima era-erama, lö nibatoma wanao horö ba lö nitöngönima si duhu andrö khöu.', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 14, 'Andrö wa no itörö tödö Yehowa wamakao andrö, ba no ifatörö khöma, me no satulö Lowalangima Yehowa, ba nilaunia fefu; ba ya''aga, ba no si lö molo''ö linia.[7]', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 15, 'Ba iya''e, ya''ugö So''aya, Lowalangima, me no öfawu''a mbanuau, me no öheta ira ba danö Miserayi tangau sabölö ba me no ebua döimö öbe''e, irugi ma''ökhö andre; no molalö ndra''aga, no molauga si lö atulö.', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 16, 'He So''aya, alösi wönumö ba mbanuau Yeruzalema, ba hili ni''amoni''ö andrö khöu, dali wa''ahakhö dödöu andrö, ni''oromaroma''ömö, götö-götö wa''ara sa''ae! Börö sa horöma andrö ba olalöŵa ndra tuama, wa no tobali fama''iki niha si tefasui ya''aga fefu Yeruzalema ba banuamö andre.', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 17, 'Ba iya''e, ya''ugö Lowalangima, ba fondrondrongo wangandrö genoniu ba fakaosania, ba fehaga mbawau yaŵa ni''amoni''ö andrö khöu, si no adudu, börö ndra enonimö andrö, ya''ugö So''aya![8]', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 18, 'Be''e mbörö dalingau, ya''ugö Lowalangigu, ba fondrondrongo! Fehaga''ö ba faigi wa''adudu andrö khöma ba banua andrö, sotöi töimö. Tenga sa börö wanötönama ba wa''atulöma, ni''oroma''öma, wa ma''ohe khöu wakaosama andrö, börö wanötönama fa''ahakhö dödöu andrö, si no ebua sibai.', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 19, 'He So''aya, fondrondrongo! be''e aefa khöma horöma, Soaya! be''e mbörö dalingau, So''aya, ba ta''i-ta''i, börö ndra''ugö, ya''ugö Lowalangigu; me no sotöi töimö mbanua andrö khöu ba banuau [niha]!"', '["Yer 25:11,12; 27:7; 29:10","Sanguhuk 20:26","MozV 7:9; Neh 1:5","Sin 106:6; Yes 64:5","MozIII 26:14 b.t.; MozV 27:15 b.t.; 28:15 b.t.; 29:20 b.t.; 30:18; 32:19 b.t.","Ngenu 1:12; 2:13","Yer 1:12; 31:28; 24:27","MozIV 6:25"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 20, 'Ba me lö saetu na wehedegu ba fangandrögu, me u''ombakha''ö horögu, awö horö mbanuama Iraono Gizeraeli ba me u''ohe khö Lowalangigu Yehowa wangandrögu fanolo ba hili ni''amoni''ö andrö khö Lowalangigu,', '["Faigi 8:16; Luk 1:19","Faigi 10:12","Faigi 8:23; Heb 9:12, Mat 5:17","Eser 7:11 b.t.; 9:9; Neh 9:36","Yes 53:8; Mat 26:66","Faigi 11:31; 12:11; Mat 24:15; Mar 13:14; Luk 24:20"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 21, 'me mangandröngandrö na ndra''odo, ba i''ondrasido Gaberieli andrö — ni''ilagu ba gangilata andrö no — me inötö wame''e sumange na tanö owi so ia, me no erege sibai dödögu.[9]', '["Faigi 8:16; Luk 1:19","Faigi 10:12","Faigi 8:23; Heb 9:12, Mat 5:17","Eser 7:11 b.t.; 9:9; Neh 9:36","Yes 53:8; Mat 26:66","Faigi 11:31; 12:11; Mat 24:15; Mar 13:14; Luk 24:20"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 22, 'Möi ia fahuhuo khögu, ba imane: He Danieli, ba wamotokhi sibai ba dödöu so ndra''odo iada''e.', '["Faigi 8:16; Luk 1:19","Faigi 10:12","Faigi 8:23; Heb 9:12, Mat 5:17","Eser 7:11 b.t.; 9:9; Neh 9:36","Yes 53:8; Mat 26:66","Faigi 11:31; 12:11; Mat 24:15; Mar 13:14; Luk 24:20"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 23, 'Me öbörötaigö mangandrö mege, ba tebe''e li, ba no sodo, ba wangombakha khöu, wa no omasiö ndra''ugö. Ba fondrondrongo, ba aboto ba dödöu dania gangilata andrö![10]', '["Faigi 8:16; Luk 1:19","Faigi 10:12","Faigi 8:23; Heb 9:12, Mat 5:17","Eser 7:11 b.t.; 9:9; Neh 9:36","Yes 53:8; Mat 26:66","Faigi 11:31; 12:11; Mat 24:15; Mar 13:14; Luk 24:20"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 24, 'Fitu ngafulu migu (mewitu fakhe zi samigu) nihonogöi ba niwami ba ba mbanua ni''amoni''ö andrö khöu, ba wango''ozui fanao horö andrö ba ba wamönui su''a-su''a horö ba ba wangeheta olalöŵa ba ba wangasogö fa''atulö dödö si lö aetu, ba ba wamotandro angilata zama''ele''ö andrö ba ba we''amoni''ö fondrege ni''amoni''ö andrö.[11]', '["Faigi 8:16; Luk 1:19","Faigi 10:12","Faigi 8:23; Heb 9:12, Mat 5:17","Eser 7:11 b.t.; 9:9; Neh 9:36","Yes 53:8; Mat 26:66","Faigi 11:31; 12:11; Mat 24:15; Mar 13:14; Luk 24:20"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 25, 'Ba böi zi lö örongo, ba ya aboto ba dödöu: I''otarai mbaŵa me tefabu''u, lafuli lataru''ö Yeruzalema, irege so Mesia, salaŵa, ba fitu migu, ba 62 migu wa''ara la''angazökhi''ö ewali ba bandra [ba Yeruzalema], ba lö aefa wamakao ba götö da''ö.[12]', '["Faigi 8:16; Luk 1:19","Faigi 10:12","Faigi 8:23; Heb 9:12, Mat 5:17","Eser 7:11 b.t.; 9:9; Neh 9:36","Yes 53:8; Mat 26:66","Faigi 11:31; 12:11; Mat 24:15; Mar 13:14; Luk 24:20"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 26, 'Ba na no aefa zi 62 migu andrö, ba tetimba Mesia lö horönia, ba banua, fabaya ni''amoni''ö andrö, ba sabölö khö razo si so moroi sa zanudugu, ba timba na itörö oloro gamozuania; irugi gamozua, ba fanuwö ba famakao ba fanudugu.[13]', '["Faigi 8:16; Luk 1:19","Faigi 10:12","Faigi 8:23; Heb 9:12, Mat 5:17","Eser 7:11 b.t.; 9:9; Neh 9:36","Yes 53:8; Mat 26:66","Faigi 11:31; 12:11; Mat 24:15; Mar 13:14; Luk 24:20"]', NULL),
  (3476437, 'OT', 'Danieli', 9, 27, 'Ba ato nibe''enia oroisa sabe''e dania, samigu wa''ara, ba ba dalu zi samigu andrö dania, ba itenaŵa wame''e sumange nitaba ba sumange ni''a, ba börö wondrege zogoro ita andrö, ba so zanudugö ba irugi wangohori, si no muhonogöi sibai, si hawui dania sanudugö.[14]', '["Faigi 8:16; Luk 1:19","Faigi 10:12","Faigi 8:23; Heb 9:12, Mat 5:17","Eser 7:11 b.t.; 9:9; Neh 9:36","Yes 53:8; Mat 26:66","Faigi 11:31; 12:11; Mat 24:15; Mar 13:14; Luk 24:20"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 1, 'Ba me no töra mendrua fakhe razo Ndrawa Weresia andrö, Kiro, ba so nifa''ele''ö khö Danieli andrö, nifotöi Belizasari. Si ndruhu nifa''ele''ö andrö, ha no famakao sebua nifa''ele''ö. Ba itanö ba dödönia nifa''ele''ö andrö ba itöngöni gangilatania.', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 2, 'Ba ya''odo Danieli, ba sabu tödö, me luo da''ö, tölu migu wa''ara:', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 3, 'Lö u''a gö sami, ba he diwo, ba lö ubadu nagu, ba samuza lö ubayoini ndra''o, irugi alua zi tölu migu.', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 4, 'Ba ba zi dua wulu a öfa ba mbaŵa si föföna, ba ba mbewu nidanö sebua andrö, Tigeri, sodo.[1]', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 5, 'Ba ufaöga hörögu, ufakhölödo, ba hiza niha, nukha tarafali nukhania, ba böbö löwi-löwinia, ba balaki sa''usö, balaki Ufasa.[2]', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 6, 'Ba botonia, ba no timba weremata wirusa, ba sihaga mbawania, hulö gari mbanua, ba hörönia, ba hulö zulu, ba ta''ionia ba ahenia, ba nö töla garamba si no mudukhu, si takile, wamaigida, ba linia, ba no hulö goso-goso sabölö-bölö.[3]', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 7, 'Ha ya''odo, Danieli, zangila angilata andrö, ba awögu, ba ma''ifu lö la''ila; ba noa sa ihawui ira fa''ata''u sabölö-bölö, ba moloi ira, ba wamini''ö ya''ira.[4]', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 8, 'Ha ya''o zi toröi, ba me u''ila gangilata sebua andrö, ba atata manö dölagu, ba afusi mbawagu, tobali, ba lö döladölagu sa''ae.[5]', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 9, 'Urongo linia, ba me urongo da''ö, ba alau tou ndra''o, hulö zi ono matelö, telögudo tou ba danö.', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 10, 'Ba i''ogomuzaö itufa ndra''o tanga ba ifahisi ndra''odo; ba ubalöduhini danö, ba utundreheni ndra''o tangagu.', '["MozI 2:14","Faigi 12:6; Fam 1:13","Hez 1:7,26–28","RazII 6:17; HalZin 9:7","Faigi 7:28; 8:18"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 11, 'Ba imane khögu: He Danieli omasiö! Fondrondrongo ligu, niŵa''ögu khöu ba zizio, me no iya''e sibai tefatenge ndra''o khöu. Ba me iŵa''ö khögu da''ö, ba muzizio ndra''o, manizi-nizido.[6]', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 12, 'Ba imane khögu: Böi busi dödöu, Danieli, i''otarai luo, me ibörötaigö omasi''ö ösöndra wa''aboto ba dödö ba me ö''ide-ide''ö ndra''ugö föna Lowalangiu, ba no tefondrondrongo wangandröu, ba no fangandröu andrö mbörö wa''asogu.', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 13, 'Dua wulu a sara wongi wa''ara iba''a ndra''o mala''ika samaigi-maigi amatöröŵa Ndrawa Weresia andrö; ba hiza, ba so Mikhaeli, salaŵa mala''ika, sebua, itolodo, me no ha ya''odo ba wasöndrata ba razo Ndrawa Weresia.', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 14, 'Ba no sodo, ba wangombakha khöu, he wisa ba madomi, ba götö furi; noa sa zui angilata, nitandrösaigö ba götö mitou dania.[7]', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 15, 'Ba me imanö khögu, ba ufatugu ndra''o, ba lö hede-hedegu.', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 16, 'Ba hiza zi hulö niha, wamaigigu, sanufa bewegu tuturunia; ba ubokai mbawagu, humede ndra''o, umane ba zi so fönagu andrö: He Tuha! No göna ndra''o faniri, börö ni''ilagu andrö, ba lö döladölagu sa''ae.', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 17, 'Ba he uwisa göi, ya''odo enoni zokhö ya''o, he uwisa fahuhuo khö Duha, si mane ya''ugö? Lö döladölagu sa''ae ba ambö manö nosogu!', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 18, 'Ba ifuli itufa ndra''odo tangania, si hulö niha, wamaigigu, i''abe''e''ö ndra''o.', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 19, 'Ba imane: Böi busi dödöu, ya''ugö omasiö, ya ohahau dödöu! Abe''e''ö ndra''ugö, ya''ia, ö''abe''e''ö ndra''ugö! Ba me iŵa''ö khögu da''ö, ba abe''e ndra''odo, ba u''ila uŵa''ö: Hede Tuha, me no ö''abe''e''ö ndra''odo!', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 20, 'Ba imane: Hadia, ö''ila, hana wa möido khöu? Mangawuli ndra''o iada''e, möido fasöndra ba mala''ika samaigi-maigi Dawa Weresia, ba na aefado ba da''ö, ba no so sa''ae mala''ika Ndrawa Heleni.', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476438, 'OT', 'Danieli', 10, 21, 'Ba u''ombakha''ö atö khöu zi so ba zura zi duhu andrö, he ŵa''ae lö awögu, ba wolau ba khöra andrö, baero mala''ikami andrö, Mikhaeli.', '["Faigi 9:23","Faigi 8:26"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 1, 'Ba ya''odo, me ambö döfi na razo Dario andrö, Dawa Media, si iagö awögu, ba wanolo ya''o ba ba womba''a khögu hadia ia.', '["Faigi 8:5","Faigi 8:8"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 2, 'Ba iya''e, ba si duhu u''ombakha''ö khöu: Datölu tö na dania razo Ndrawa Weresia; ba fanete da''ö, ba ana''a sebua moroi ba gana''ara fefu isöndra, ba na sabölö sibai sa''ae ia dania, ba i''owuloi zabölö fefu, ba wanuwö amatöröŵa Ndrawa Heleni.', '["Faigi 8:5","Faigi 8:8"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 3, 'Ba so dania razo sabölö, samatörö amatöröŵa sebua, ba ifalua zomasi ia.[1]', '["Faigi 8:5","Faigi 8:8"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 4, 'Ba si mane fa''asonia, si manö göi wa''adudu gamatöröŵania [wa''alio], ni''o''öfa, mangohia''ö mata angi si öfa. Ba sambua lö möi ba nga''ötönia, ba sambua göi lö sogamö fa''abölö khönia mege. Fa''asalaŵania ba ni''osi sa''ae, ba ba mbö''ö möi, tenga ba nga''ötönia.[2]', '["Faigi 8:5","Faigi 8:8"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 5, 'Ba abölö dania razo raya, ba sabölö na moroi khönia gumandra khönia, samösa, ba salaŵa da''ö, salaŵa gamatöröŵa, tanö sebolo ibe''e barö mbawania.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 6, 'Ba mato mendrua fakhe, ba fahuwu ira, ba möi fo''omo razo yöu nono razo raya, ba wahuwusa, ba lö anau gölö dolo-tolo da''ö; ba he tolo-tolo bö''ö khönia, ba si lö boto, tebe''e nifakiko dania ia [ira alawe andrö], awö zolohe ya''ia mege, awö namania, awö zanolo ya''ia mege.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 7, 'Ba so dania wangalinia, lewiö ba lali andrö, si otarai ira alawe andrö, mege; da''ö dania zi möi fasuwö ba zabölö andrö, ba atu''a ia ba mbanua saro andrö, khö razo yöu, ba ilau khöra zomasi ia ba sabölö ia.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 8, 'Numalö adura ba famaedo nifahele khöra, awö gama-gamara sebua böli, firö ba ana''a, ba i''ohe ahulua, ba danö Miserayi; ba irege mato mendrua fakhe dania, ba lö''ö sa''ae isuwö razo yöu;', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 9, 'ba da''ö dania zi möi ba danö razo raya, ba wanuŵo ya''ira, ba ifuli sa atö ia ba khöra.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 10, 'Ba iraononia dania zanohugö fanuwö-nuwö andrö, ba ato sibai la''owuloi sabölö. Da''ö dania zi so, timba molö sebua, ba lanönöi danö; ba lafuli lalau, larugi mbanua saro andrö khönia.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 11, 'Ba abao sibai dania dödö razo raya, ba so ia moroi si tou, ba wasuwöta khö razo yöu. Ato sibai sa ba da''ö sabölö, ba möna zui razo raya.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 12, 'Ba ahori zanuwö andrö; ba fayaŵa razo raya, ba ngafulu ngahönö ibunu niha, ba tenga sa atö sabölö ia dania.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 13, 'Ifuli i''owuloi zabölö razo yöu, sato moroi ba zi föföna mege; ba na no mato mendrua fakhe zui, ba ifuli so ia, ato sibai zabölö khönia, ba fangöna, ba si no fahöna.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 14, 'Ba ba da''ö dania, ba ato zi maoso udu razo raya, ba molaŵa göi zabölö andrö, soimi, ena''ö itörö wama''ele''ö andrö, ba si te''ala ira.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 15, 'So razo yöu, ifako''o''ö mba''a-ba''a ba atu''a ia ba mbanua saro; lö''ö sa manaha zaradadu moroi raya, ba fondrege zabölö khönia, ba no sambö fa''abölö, ba wanimba ya''ira ena''ö.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 16, 'Ba solau khönia andrö, ba ilau manö zomasi ia, me lö sabe''e. Ba i''aro''ö naha ba wondrege zi sökhi tanö andrö; famakiko nilau dangania.[3]', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 17, 'Ba da''ö nifaiginia dania, ena''ö khönia manö gamatöröŵa razo raya, ma''asagörö, ba i''atulö''ö ia khönia ba ibe''e khönia nononia alawe, ba ba wamakiko; ba lö itörö [nifakhainia], lö fozu.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 18, 'Ba ifaigi wangai tanö ba mbewe nasi ba ebolo ihalö khönia; ba so dania gumandra sebua, samadöhö fango''ayania andrö, isulöni sa''ae khönia wango''ayania andrö.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 19, 'Ba awena dania ifaigi mbanua saro ba danönia, ba amaedola zanendre ia ba da''ö, ba alau ia, ba lö ya''ia sa''ae.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 20, 'Ba fanalinia, ba ifatenge ba wondrege zi sökhi tanö andrö zanugi beo; ba lö ara, ba mate nibunu ia, ba tenga ba wönu ba tenga ba wanuwö.', '["Faigi 8:9"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 21, 'Ba fangalinia, ba si lö ngaroro, si tenga ni''odödögö famataro razo; ba so manö ia, lö mudöna-döna ba ba walimolimosa i''okhögö wa''asalaŵa.[4]', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 22, 'Ba sanuwö sato sibai, ba amaedola ihanigö manö, ba ihori, ba ibunu göi zatua ba wawu''usa li andrö, samösa.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 23, 'Ba he na so zi no fahuwu khönia, ba ilimo; lö ato sibai khönia zabölö, na möi ia manuwö, ba ya''ia zui zi möna.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 24, 'Ihawui manö danö fondrege zatabö sinanö, lö mudöna-döna, ba ilau zi tenga nilau ndra amania, ba he ira tuania föna; nirabunia ba ahuluania, ba ifaosa ba nawönia, tenga ha ma''ifu, ba ifakhai wolau ba mbanua saro misa; ba lö ara sibai.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 25, 'Ba ilau khö razo raya wa''abölönia andrö ba fa''abe''e dödönia, ato sibai i''ohe niha, ba no maulu göi wa''ato khö razo raya, ba no sabölö sibai, ba ifaondragö, ba wasuwöta, ba tebai ilaŵa, börö me so zi manga mböli.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 26, 'Sorudu manga khönia zamufu ya''ia; timba nihanigö zabölö andrö khönia fefu, ba ato nibunu si''öli.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 27, 'Falimosa dödö razo andrö si darua; ha sambua naha wemanga ba faoma lalimo nawöra; ba lö fozu, me awena amozua, na no irugi inötö.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 28, 'Ba tobali ifuli ia ba danönia, ba no ebua sibai gahulua, ba awena dania ifaigi ba wolau ba zi no fawu''u li andrö, ni''amoni''ö, ba ifalua ba ifuli ia ba danönia.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 29, 'Ba na no irugi inötö, ba isaŵa zui danö si raya, ba bö''ö lua-lua ba zi samuza andrö, bö''ö me föna.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 30, 'Lalau khönia si so ba nowo Giti, ba ata''u ia labe''e, ba tobali mangawuli, ba ba zi no fawu''u li andrö, ni''amoni''ö, itandrösaigö wönunia. Ba ifuli ia ba khöra, ba i''otarai da''ö, ba itandrösaigö ba zi no mangawuli furi, si no mondröi fawu''usa li ni''amoni''ö andrö.[5]', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 31, 'Ifatenge zabölö, si iagö da''ö, ba solau salakha ba ni''amoni''ö andrö, ba hati andrö, ba sanenaŵa sumange andrö, nibe''e-be''e ba samedadao sogoro ita andrö, fanudugö [huku Lowalangi].[6]', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 32, 'Ba zi no manawö fawu''usa li andrö, ba ilimo, ena''ö la''erogö [huku Lowalangi]; ba si no aboto ba dödö Lowalangira, balö mangiwa, latandro.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 33, 'Satua-tua ba khöra, ba labotokhi ba dödö zato, ba mato mendröfa fakhe wa''ara tefakiko ira bawa zi''öli ba alitö ba fokuru ba foraburabu si so khöra.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 34, 'Ba na luo wa''ate''alara andrö, ba falukha ira wanolo side-ide, fangorifira; ba ato dania zi fao khöra, samini tödö.', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 35, 'Ba so zi mate, ösa, satua-tua khöra, ba wameta si fabaya, si lö göna, ba si no amaedola gadaya, ba wangehao, gasa-gasa gamozua; ba ginötö sa dania da''ö.[7]', '["Faigi 8:25","MozIV 24:24; Yes 23:1","Faigi 9:27","Faigi 12:10"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 36, 'Ba razo andrö, ba ilau zomasi ia; sohokha ia ba si fayaŵa ia ba zi no motöi Lowalangi, fefu, ba khö Lowalangi Fondrege zalaŵa, ba ilau huhuo sihokha mbuda, ba mofozu wolaunia, irege no alö wönu Lowalangi [ba Ndraono Gizeraeli], me no mufalua nihonogöi.[8]', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 37, 'Ba he Lowalangi ndra tuania mege, ba lö ba dödönia, ba he "fa''omasi ndra alawe" andrö, ba he hadia ia Lowalangi bö''ö, ba lö ba dödönia, fayaŵa manö ia khöra fefu.', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 38, 'Ba nifosumangenia, salahi, ba Lowalangi hati andrö, Lowalangi si lö murongo khö ndra tuania, ifosumange firö ba ana''a ba mani-mani ba barasi.[9]', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 39, 'Ba ba mbanua saro misa, ba ifaigi khönia zolo''ö huku Lowalangi bö''ö; ba ba nitutuyunia andrö, ba i''ebua''ö zumange ba ifataro salaŵa ira, ato ibe''e barö mbawara, ba ifakhoi khöra danö, böli gölöra.', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 40, 'Ba ba götö safuria andrö, ba fatandra fa''abölö khönia razo raya, ba ilau khönia razo yöu, i''ohe gureta ba si fakudo, ba oya göi nowo, lasaŵa danönia ba lahawui, lanönöi.[10]', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 41, 'Ba möi ia göi ba wondrege zi sökhi tanö andrö, ba ba ngafulu ngahönö zi mate ibe''e. Ba si lö ibabaya, ba Iraono Gedomo ba Iraono Moabi ba tuho Ndraono Gamoni.', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 42, 'I''oro''ö dangania yaŵa danö andrö misa, ba he tanö Miserayi göi, ba lö aefa khönia;', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 43, 'ana''a ba firö ba hadia gama-gama sebua böli ba danö Miserayi, ba ihalö khönia, ba solo''ö khönia göi Ndrawa Libia ba Dawa Khusi.', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 44, 'Ba so dania duria moroi ba gatumbukha luo ba moroi yöu, si tokea ia; ba maoso ia, isaŵa, ena''ö atö ifakiko ba ihori.', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476439, 'OT', 'Danieli', 11, 45, 'Ba ba gotaluara nasi hili andrö, si so famoadu andrö, ni''amoni''ö, ibe''e nosenia, amaedola gödonia; ba ba da''ö ikhamö ia fa''amate, ba lö sangorifi ya''ia.[11]', '["Faigi 7:25; TesII 2:4; Hez 28:2; Fam 13:5","Hab 1:11","Hez 38:15; Fam 9:16","Faigi 7:26; Fam 19"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 1, 'Ba na luo da''ö dania, ba maoso Mikhaeli andrö, salaŵa mala''ika, sebua, samaigi-maigi soimi andrö, ba götö wamakao ba da''ö, si lö irai, irugi da''ö, i''otarai mböröta soi niha. Ba ba götö da''ö, ba da''ö fefu ni''orifi, soimi, si no mutanö ba zura.[1]', '["Faigi 10:21; Mat 24:21; Faigi 12:7","Yes 66:24; Mat 25:46; Yoh 5:29; HalZin 24:15","Amaed 4:18; Mat 13:43; Yak 5:20","Yes 29:11"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 2, 'Ba ato zi maoso dania, si no mörö barö danö, ba wa''auri si lö aetu ösa, ba tanö bö''ö, ba ba wa''aila ba ba wa''ogoro si lö aetu.[2]', '["Faigi 10:21; Mat 24:21; Faigi 12:7","Yes 66:24; Mat 25:46; Yoh 5:29; HalZin 24:15","Amaed 4:18; Mat 13:43; Yak 5:20","Yes 29:11"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 3, 'Ba satua-tua, ba sihaga, timba haga mbanua si yaŵa, ba si no ato molohe ba wa''atulö, ba timba dröfi dania, götö-götö wa''ara, si lö aetu.[3]', '["Faigi 10:21; Mat 24:21; Faigi 12:7","Yes 66:24; Mat 25:46; Yoh 5:29; HalZin 24:15","Amaed 4:18; Mat 13:43; Yak 5:20","Yes 29:11"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 4, 'Ba ya''ugö Danieli, ba böi ombakha''ö huhuoda andre ba fotandro zura, irugi ba götö safuria. Ato dania zangalu-ngalui eluaha ba tedou-dou dania wa''aboto ba dödö.[4]', '["Faigi 10:21; Mat 24:21; Faigi 12:7","Yes 66:24; Mat 25:46; Yoh 5:29; HalZin 24:15","Amaed 4:18; Mat 13:43; Yak 5:20","Yes 29:11"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 5, 'Ba ya''odo, Danieli, ba u''ila, ba hiza mala''ika, darua, si so ba da''ö, si samösa, ba ba mbewe nidanö tanö andre, ba si samösa, ba ba mbewe tanö si yefo.', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 6, 'Ba imane si samösa ba niha andrö, sonukha tarafali, si so yaŵa nidanö: Ha wa''ara dania wa''a''ozu zahöli-höli dödö andrö?[5]', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 7, 'Ba urongo me humede zonukha tarafali andrö, si so yaŵa nidanö — i''oro''ö miyaŵa dangania ma''adua, miyaŵa ba zorugo, fahölu ia ba khö zauri andrö, irugi zi lö aetu — imane: Fa''arania, ba döfi ba mendrua fakhe, ba matonga ndröfi; na no a''ozu wa''abölö zamakiko soi ni''amoni''ö, ba itörö da''ö no mege fefu![6]', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 8, 'Urongo sa, ba lö aboto ba dödögu, ba umane: He Tuha! He wisa lua-lua da''ö no mege fefu dania?', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 9, 'Ba imane khögu: Fuli''ö, ya''ugö Danieli! irege götö safuria andrö, ba tenga sa ni''ombakha''ö huhuo andre; nifotandro.', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 10, 'Ato dania zi hulö nitafi, nihaogö, ba niheta si lö sökhi, ba sebua horö, ba si dörö-dörö manao horö; dozi sebua horö, ba dörödöro lö fa''aboto ba dödö; ba ba zatua-tua, ba so wa''aboto ba dödö.[7]', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 11, 'Ba i''otarai luo andrö, na tetenaŵa zumange andrö, nibe''e-be''e mege, ba wamedadao sogoro ita andrö, fanudugö huku Lowalangi, ba 1.290 wongi tö.[8]', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 12, 'Ya ahowu zanau ölö ba sanau noso, irugi no numalö zi 1.335 wongi!', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476440, 'OT', 'Danieli', 12, 13, 'Ba ya''ugö, ba ae''e, amaedola öfaondragö gamozua; solombase ndra''ugö ua, ba maoso''ö dania, ba wanema tana khöu andrö, ba gamozua götö danö andre.[9]', '["Faigi 10:5","Faigi 7:25; Fam 10:5,6","Faigi 11:35; Hos 14:9; Fam 22:11","Faigi 8:11; 9:27; 11:31","Kol 1:12"]', NULL),
  (3476441, 'OT', 'Hosea', 1, 1, 'Da''e daroma li Yehowa khö Hosea andrö, ono Mbe''eri, me luo Usia ba Yotamo ba Ahasi ba Hisikia, razo mado Yuda, ba me luo Yerobeamo andrö, ono Yo''asi, razo Ndraono Gizeraeli.[1]', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL),
  (3476441, 'OT', 'Hosea', 1, 2, 'Me böröta wehede Yehowa khö Hosea, ba imane Yehowa khö Hosea: Ae halö ndra alawe sohorö-horö, fabaya nono horö, me no sohorö-horö niha ba danö, wangerogö Yehowa.[2]', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL),
  (3476441, 'OT', 'Hosea', 1, 3, 'Ba möi ia mangai Gomeri andrö, ono Dibila''i, ba manabina da''ö ba mo''ono khönia, ono matua.', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL),
  (3476441, 'OT', 'Hosea', 1, 4, 'Ba imane khönia Yehowa: Yezere''eli be''e töinia; hatö sa ma''ifu tö, ba ulau mbalö ndro Yezere''eli andrö, ba nga''ötö Yehu andrö ba use''e nöri Ndraono Gizeraeli andrö.[3]', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476441, 'OT', 'Hosea', 1, 5, 'Ba na luo da''ö, ba ufatö wana Ndraono Gizeraeli ba ndraso andrö, ba Yezere''eli.', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL),
  (3476441, 'OT', 'Hosea', 1, 6, 'Ba ifuli manabina ba mo''ono, ono alawe. Ba imane khönia Yehowa: Lo-Ruhama (si lö muhakhösi tödö) be''e töinia, me lö''ö sa''ae uhakhösi tödö ma''uwu Gizeraeli, wame''e aefa khöra horöra ena''ö.', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL),
  (3476441, 'OT', 'Hosea', 1, 7, 'Ba ma''uwu Yuda andrö, ba uhakhösi tödö, ba u''orifi ira tanga Lowalangira, Yehowa, ba lö ube''e fangorifira wana ba si''öli ba fanuwö, ba he kudo ba he si fakudo.[4]', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL),
  (3476441, 'OT', 'Hosea', 1, 8, 'Ba i''efa''ö ba mbagi zusu Lo-Ruhama andrö, ba ifuli manabina ba mo''ono, ono matua.', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL),
  (3476441, 'OT', 'Hosea', 1, 9, 'Ba imane Yehowa: Lo-Ami (tenga banuagu) be''e töinia, me no tenga banuagu ami, ba me lö edönado, khömi ndra''odo.', '["Yes 1:1","Yer 3:1; Hez 23:3","RazI 21:1; RazII 10:1 b.t.; 15:12","RazII 19:34"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 1, 'Ba fa''ato Ndraono Gizeraeli dania, ba timba wa''oya ngawua nene ba mbewe nasi, si tebai nisu''a ba si tebai ni''erai; ba tobali: ba mbanua, ba niŵa''ö khöra: "Tenga banuagu ami", ba lamane khöra: "Ya''ami, ono Lowalangi sauri."[1]', '["MozI 32:12; Rom 9:26; FetI 2:10","Yer 3:18; 30:9; Hez 37:22"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 2, 'Ba lafuli la''orudugö ira Iraono Yuda ba Iraono Gizeraeli fefu, ba si ha samösa lafataro högöra ba möi ira miyaŵa, moroi ba danö andrö; baŵa sebua sa mbaŵa Yezere''eli andrö.[2]', '["MozI 32:12; Rom 9:26; FetI 2:10","Yer 3:18; 30:9; Hez 37:22"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 3, 'Mimane ba dalifusömi matua andrö: "Banuagu [ami]!" ba ba dalifusömi alawe: "Nihakhösi tödö [ami]!"', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 4, 'Mihuku ninami andrö, mihuku! me no tenga fo''omogu ia ba me no tenga ngambatönia ndra''odo, ena''ö iheta ba mbawania hokhania, ba fohorönia ba gotalua zusunia.[3]', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 5, 'Fa böi uheta mbalu-balunia, fa böi ube''e si mane me luo wa''atumbunia ia, ba fa böi ufaomagö ia ba danö si mate, ba danö si lö ida''idanö, ba fa lö ube''e mate owökhi dödö ia.', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 6, 'Ba ononia andrö, ba lö uhakhösi tödö, me no ono horö.', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 7, 'Noa sa mohorö ninara, no ilau zaila ita sadono ya''ira; noa sa imane: Da''ugo''ögo''ö zomasi ya''odo, same''e ögu fakhe ba ögu idanö ba bu mbiri-biri ba afasi ba fanikha khögu ba hadia ia nibadugu.', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 8, 'Andrö hiza, uba''a lalania doi ba ufa''anö göli kara khönia, ba alakha lö isöndra lalania.', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 9, 'Ba igohi zomasi ya''ia, ba lö ikhamö: i''alui, ba lö isöndra, ba imane dania: Da''ufulido khö ngambatögu si föföna andrö; noa sa ohahau dödögu, me luo da''ö, moroi iada''e.', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 10, 'Ba lö saboto ba dödönia, wa ya''odo zame''e khönia fakhe ba agu ba fanikha andrö, ba si no mangöhöna khönia firö ba ana''a; ba ba khö Mba''ali la''oguna''ö.[4]', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 11, 'Ba ya''odo göi, ba uhalö sa''ae göi wakhe andrö khögu, na asotö, ba agu andrö khögu, na baŵania; ba bu mbiri-biri ba afasi andrö khögu, nibe''enia balu-balunia ena''ö, ba usöbi khönia.', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 12, 'Ba uheta mbalu-balu zaila ia, ba zanehe zohoröni ya''ia; ba lö sangefa''ö ya''ia ba dangagu![5]', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 13, 'Ba u''etu''ö fefu wa''omuso dödönia, awö walöŵa andrö, awö wasulöna andrö, awö luo sabato ba awö gowasa andrö khönia, fefu.[6]', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 14, 'Ba töla nagu andrö khönia ba töla marafala khönia, ba ufufu, niŵa''önia tödönia: buala khögu da''ö, nibe''e zomasi ndra''o andrö, ba ubali''ö sasai''ö, ena''ö ö gutu ndru''u.[7]', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 15, 'Uhuku ba khönia götö nadu andrö, götö wamosumangenia ya''ia, wango''aya laeduru ba aya bö''ö, me olifu ia ndra''odo, iŵa''ö Yehowa.', '["Yer 3:1; Hez 23:3; 16:16","Hez 16:16 b.t.","Faigi 5:14","Amos 8:10","Sin 80:13; Yes 5:5"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 16, 'Andrö hiza, udönisi ia, ba u''ohe ba danö si mate, ba uhaogö wehede khönia.[8]', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 17, 'Ba ba da''ö ufuli khönia kabu nagu andrö khönia ba ubali''ö bawa göli ba wanötöna mbawa danö wa''abu dödö andrö; ena''ö manunö ia ba da''ö, si mane me ono alawe ia, si mane me i''otarai moroi si tou danö Miserayi.[9]', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 18, 'Na luo da''ö — iŵa''ö Yehowa — ba "fo''omogu" öbe''e töigu, ba tenga sa''ae "Ba''aligu."', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 19, 'Ba ube''e taya sa''ae ba mbewenia döi Mba''ali andrö, ena''ö lö''ö sa''ae tetötöi döira andrö.', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 20, 'Ba na luo da''ö, ba ube''e gamakhoita ba gutu ndru''u ba ba wofo ba dalu mbanua, ba ba guökuö ba danö, fangorifira, ba fana ba si''öli ba fanuwö, ba uhori ba danö, ba lö hadia ia khöra ba danö ube''e.[10]', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 21, 'Ba u''oniha ndra''ugö, si lö mamalö-malö; u''oniha ndra''ugö ba wa''atulö ba ba wa''adölö ba ba wa''ebua dödö ba ba wa''ahakhö dödö;[11]', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 22, 'ba wa lö faröi u''oniha ndra''ugö, ena''ö aboto ba dödöu Yehowa![12]', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 23, 'Na luo da''ö, ba ufondrondrongo li, iŵa''ö Yehowa; ufondrondrongo li mbanua si yaŵa, ba ya''ia zamondrongo li danö.[13]', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 24, 'Ba tanö, ba ifondrondrongo li wakhe ba li nagu ba li wanikha ba ya''ira zamondrongo li Yezere''eli andrö.[14]', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476442, 'OT', 'Hosea', 2, 25, 'Ba utaru''ö ia khögu ba danö, ba uhakhösi tödö Lo-Ruhama (si lö muhakhösi tödö) andrö, ba umane khö Lo-Ami (tenga banuagu) andrö: "Banuagu ndra''ugö"! na ya''ia, ba imane: "He Lowalangigu."[15]', '["Yes 40:2; Hez 20:35","MozII 15:1; Yos 7:26","Yob 5:23; Yes 11:6; Hez 34:25","Hez 16:8","Yer 31:34","Sakh 8:12","Faigi 1:11","Faigi 1:6,9:10"]', NULL),
  (3476443, 'OT', 'Hosea', 3, 1, 'Ba imane khögu Yehowa: Ae fuli omasi''ö ndra alawe, sangomasi''ö niha bö''ö ba si no mohorö, si mane fa''omasi Yehowa Ndraono Gizeraeli, he ŵa''ae no adöni dödöra ba Lowalangi bö''ö ba he ŵa''ae no omasi ira kue nifaruka bua nagu.', '["MozI 31:19; Nga''ötII 15:3; Faigi 10:3","Yes 2:2 b.t.; Yer 30:9"]', NULL),
  (3476443, 'OT', 'Hosea', 3, 2, 'Ba no uhöli ia khögu felelima rufia ba sazo''e gandru;', '["MozI 31:19; Nga''ötII 15:3; Faigi 10:3","Yes 2:2 b.t.; Yer 30:9"]', NULL),
  (3476443, 'OT', 'Hosea', 3, 3, 'ba umane khönia: Ara dania dumao-dao ndra''ugö khögu; böi mohoro''ö ba böi möi''ö donga ndra matua bö''ö, ba si manö ndra''o khöu.', '["MozI 31:19; Nga''ötII 15:3; Faigi 10:3","Yes 2:2 b.t.; Yer 30:9"]', NULL),
  (3476443, 'OT', 'Hosea', 3, 4, 'Iraono Gizeraeli andrö sa, ba ara dania, ba dumao-dao manö, lö salaŵa, lö högö, ba lö fame''e sumange ba lö harefa ba lö ono mbaru ba doto ba lö sihara.[1]', '["MozI 31:19; Nga''ötII 15:3; Faigi 10:3","Yes 2:2 b.t.; Yer 30:9"]', NULL),
  (3476443, 'OT', 'Hosea', 3, 5, 'Ba na aefa da''ö, ba lafalalini gera-erara Iraono Gizeraeli ba la''alui Yehowa, Lowalangira, ba Dawido andrö, salaŵara, la''ondrasi Yehowa ba fa''ebua dödö andrö khönia, oi so wa''ata''u, na aefa da''ö dania.[2]', '["MozI 31:19; Nga''ötII 15:3; Faigi 10:3","Yes 2:2 b.t.; Yer 30:9"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 1, 'Mifondrondrongo li Yehowa, ya''ami Iraono Gizeraeli! So huhuo Yehowa ba niha ba danö, me lö falöfaröi, ba me lö fa''omasi, ba me lö fa''aboto ba dödöra Lowalangi, ba danö:', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 2, 'mangelingelifi ira ba molau-lau faya ba mange''enge''e ba managönagö ba mohorö-horö; manöinöi yomo ira ba te''oli manö wamunu niha.', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 3, 'Da''ö mbörö, wa oköliköli danö [lö teu], awö wa ariri niha ba danö, fabaya utu ndru''u ba fofo ba dalu mbanua; ba numalö i''a ba nasi, ba mate-mate.', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 4, 'Ba böi fasoso niha ba böi fatahi khö nawönia. Ba khömi, ya''ami ere, so huhuogu![1]', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 5, 'Ba zi ma''ökhö alau ami ube''e, ba he sama''ele''ö andrö, ba salau, awömi, ba zi bongi, ba ufakiko ninami!', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 6, 'Ba wa''atekiko lasaŵa banuagu, me no lö fa''aboto ba dödö. Ba me no lö ba dödömi wa''aboto ba dödö andrö [ya''ami ere], ba utibo''ö ami, fa böi sa''ae ere ami. Ba me no olifu ami nifakhoi Lowalangimi, ba da''u''olifugö göi ndra''o ndraonomi.[2]', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 7, 'Me itugu abölö ira mege, ba no itugu oya lalöra khögu; ba ube''e salahi lakhömira wa''aila.', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 8, 'Ba horö mbanuagu andrö lasöndra göra, ba no omasi ira golalöŵa mbanuagu.[3]', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 9, 'Ba dalafaomagö wolau khöra, ba gere ba ba niha sato: U''otu''ö mbua-buara, ba mangandrauli khöra nilau-laura ube''e.[4]', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 10, 'Na manga ira, ba böi ya abuso ira; ba na orudu ira ba ndra alawe, ba böi mo''ono''ono ira, me no laböhöli wame''e ba dödöra Yehowa.[5]', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 11, 'Ba wohorö-horö ba ba wemabu-mabu agu taya gera-era:', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 12, 'Ba mbalö geu faeta mbanuagu ba si''ora zangombakha khöra lala. Noa sa bekhu ba wohoröhörö zamowöhö ya''ira, fa lafosumange nadu, salahi Lowalangi.', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 13, 'Ba zuzu hili misa latataba zumange, ba ba hili-hili labe''e ba mbörö manawa ba ba mbörö ma''usö ba ba mbörö zimalambuo — no omasiö lumö geu andrö. Ba tobali mohorö-horö nonomi alawe ba lalulu ira ba zohoröni donga zodona umönömi.[6]', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 14, 'Ba onomi alawe, ba lö u''otu''ö ba wohorö-horöra andrö, ba he umönömi, me lalulu ira ba zohoröni donga zodonga, ba lö u''otu''ö. Ya''ira [ere] ba noa sa fao ira ba ndra alawe sabao, ba zi tobini, ba no fao-fao ira ba ndra alawe nifataro ba wohorö-horö, wame''e sumange nitaba, ba tobali tekiko niha sato, si lö fa''aboto ba dödö.', '["MozV 17:12","Yes 5:13","MozIII 6:26","Yes 24:2","MozIII 26:26; Hag 1:6","RazII 17:20; Yes 37:7; Hez 6:13; 20:28"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 15, 'Ba na mamosumange adu ami, ya''ami Iraono Gizeraeli, ba böi atö molalö mado Yuda! Böi mi''ae ba Giligala, ba böi mi''ae miyaŵa ba Mbeti Awene, ba böi mifao ba da''ö wahölusa andrö: "Ba wa''aduhu wa''auri Yehowa![7]', '["RazI 12:29; Faigi 9:15; Amos 8:14","Mikh 7:3"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 16, 'Na no sabe''e tandro Ndraono Gizeraeli, timba zaŵi samu''i, ba hadia, ba ikubaloi ira Yehowa, ba mbenua sebolo, amaedola nono mbiri-biri?', '["RazI 12:29; Faigi 9:15; Amos 8:14","Mikh 7:3"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 17, 'No la''olembai nadu mado Geferayi; ba niböhöli sa''ae ira!', '["RazI 12:29; Faigi 9:15; Amos 8:14","Mikh 7:3"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 18, 'No tenga inötö wemabu-mabura, ba sohorö-horö ira! Fangebua döira andrö, ba lö ba dödöra; fa''aila zomasi ira.[8]', '["RazI 12:29; Faigi 9:15; Amos 8:14","Mikh 7:3"]', NULL),
  (3476444, 'OT', 'Hosea', 4, 19, 'Ifuyu''ö ira tawuyu nangi sabölö ba tobali si lö boto wanötönara ba naha wame''e sumange andrö khöra.', '["RazI 12:29; Faigi 9:15; Amos 8:14","Mikh 7:3"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 1, 'Mifondrondrongo da''e, ya''ami ere! Mibe''e mbörö dalingami, ya''ami Iraono Gizeraeli, ba mitöngöni, ya''ami ba gödo razo! Me no khömi manandrösa huhuo andrö, me no tobali tandraŵa ami ba Misefa ba u''ö nifadölö ba hili Dabora.', '["Faigi 4:12","Faigi 7:10","Yer 11:11; Yoh 7:34"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 2, 'No la''erogö Lowalangi ba no abakha wanao horö. Andrö u''otu''ö ira fefu dania!', '["Faigi 4:12","Faigi 7:10","Yer 11:11; Yoh 7:34"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 3, 'Noa sa aboto ba dödögu mado Geferayi, ba tebai labini''ö ira khögu Iraono Gizeraeli; noa sa faefa mege mame''e adu ami, ya''ami mado Geferayi ba no lata''unöi ria Iraono Gizeraeli, wanörö salakha.', '["Faigi 4:12","Faigi 7:10","Yer 11:11; Yoh 7:34"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 4, 'Bua-buara wamatimba, na lafuli ira khö Lowalangira ena''ö; no mobekhu ira bekhu wohorö, ba fa''aboto ba dödöra Yehowa, ba lö khöra.[1]', '["Faigi 4:12","Faigi 7:10","Yer 11:11; Yoh 7:34"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 5, 'Ba fangebua döi Ndraono Gizeraeli andrö zamaduhu''ö dania, udura, wa lasaŵa wa''atekiko Iraono Gizeraeli, fabaya mado Geferayi, börö golalöŵara andrö — ba si tekiko göi mado Yuda, awöra.[2]', '["Faigi 4:12","Faigi 7:10","Yer 11:11; Yoh 7:34"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 6, 'Ba na maoso dania ira, na la''ohe mbiri-birira, awö zaŵira, ba wangalui Yehowa, ba lö lasöndra ia: noa sa i''erogö ira.[3]', '["Faigi 4:12","Faigi 7:10","Yer 11:11; Yoh 7:34"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 7, 'Na faröi ira khö Yehowa, noa sa mo''ono''ono ono horö ira. Andrö i''a dania ira owasa ba wasulöna andrö, fabaya tanöra.', '["Faigi 4:12","Faigi 7:10","Yer 11:11; Yoh 7:34"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 8, 'Milau dorofe ba Gibea, milau dorofe ba Rama! Mihahagö ba Mbeti Awene! Mi''angelama, ya''ami mado Mbeniyami!', '["MozV 19:14","RazI 12:28"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 9, 'Si tobali tanö si mate danö mado Geferayi dania, na baŵa wangotu''ö. Si duhu ni''ombakha''ögu, si göna Ndraono Gizeraeli dania!', '["MozV 19:14","RazI 12:28"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 10, 'Satua mado Yuda andrö, ba no timba zama''ese gowe nola; ya''ira dania uhawui fönugu, nifamaduwa idanö.[4]', '["MozV 19:14","RazI 12:28"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 11, 'Ba mado Geferayi, ba latehe wamuyu''ö huku, latehe na lahundra-hundra; noa sa lö ata''u ira, la''o''ö waya-faya andrö.[5]', '["MozV 19:14","RazI 12:28"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 12, 'Ba no tobali timba hama ndra''o ba mado Geferayi ba timba go ba mado Yuda.', '["MozV 19:14","RazI 12:28"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 13, 'Ba me la''ila wökhöra mado Geferayi ba me la''ila waosara mado Yuda, ba mangandrö tolo mado Geferayi ba Ndrawa Asiria, lafatenge zinenge khö razo Yarebi, ba tebai i''abe''e''ö ami da''ö, ba lö i''ila ifadöhö waosami andrö,', '["MozV 19:14","RazI 12:28"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 14, 'me timba zingo dania ndra''odo ba mado Geferayi, ba timba nono zingo ba ma''uwu Yuda. Ya''odo andre, usasawi ira ba ulau mofanö; u''oloi''ö ira, ba lö sangefa''ö ya''ira ba mofanö ndra''o,', '["MozV 19:14","RazI 12:28"]', NULL),
  (3476445, 'OT', 'Hosea', 5, 15, 'ufulido ba nahiagu. Ba fozu dania, ba aboto ba dödöra ba la''alui wamaigigu ya''ira; na tosasa ira, ba humulu dödöra khögu.', '["MozV 19:14","RazI 12:28"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 1, 'Talabu, tafuli ita khö Yehowa; ifuli sa ifadöhö zokhoda, me no amaedola isasawi ita, idalu-daluni zokhoda andrö, me no ifesokho ita![1]', '["MozV 32:39; Yob 5:18; Yes 30:26","Yes 26:19; KorI 15:4","SamII 23:4; Sin 72:6"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 2, 'Ha mato dua wongi, ba i''orifi ita, ba mahemolu ö, ba ifuli i''abe''e''ö ita, ena''ö auri ita rorogöfönia.[2]', '["MozV 32:39; Yob 5:18; Yes 30:26","Yes 26:19; KorI 15:4","SamII 23:4; Sin 72:6"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 3, 'Akha aboto ba dödöda, ba ena''ö na taforege wangalui fa''aboto ba dödöda Yehowa, — möi ia khöda, si ndruhu-ndruhu timba wa''aduhu wa''amoluo, ena''ö itörö ita, timba deu, timba deu sara, si basöi tanö."[3]', '["MozV 32:39; Yob 5:18; Yes 30:26","Yes 26:19; KorI 15:4","SamII 23:4; Sin 72:6"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 4, 'He uwisa khömi ya''ami mado Geferayi? Hadia nilaugu khömi, ya''ami mado Yuda? Me no hulö lawuo ba zanguhulö wongi wa''omasimi andrö, me no hulö namo mbanua, salio sibai taya.[4]', '["Faigi 13:3","SamI 15:22; Amaed 21:3; Mat 9:13","Faigi 8:1"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 5, 'Ba me no si manö, ba lö tola lö ufabago''ö ira ba zama''ele''ö andrö, ba lö tola lö ububunu ira taroma ligu andrö, ba nifa''ele''ö wanguhukugu, si mane fa''atumbu luo.', '["Faigi 13:3","SamI 15:22; Amaed 21:3; Mat 9:13","Faigi 8:1"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 6, 'Fa''omasi sa zomasido, ba tenga sumange nitaba; fa''aboto ba dödöra Lowalangi zomasido ba tenga sumange nitunu![5]', '["Faigi 13:3","SamI 15:22; Amaed 21:3; Mat 9:13","Faigi 8:1"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 7, 'Ba ya''ira andrö, ba no lasawö nifakhoigu, nifolau niha baero. No falimo ira khögu ba da''ö.[6]', '["Faigi 13:3","SamI 15:22; Amaed 21:3; Mat 9:13","Faigi 8:1"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 8, 'Gileadi andrö, ba no banua zanao horö, si no ta''unö do.', '["Faigi 13:3","SamI 15:22; Amaed 21:3; Mat 9:13","Faigi 8:1"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 9, 'No timba zi farabu, sanarogö sanörö, gere andrö; mange''enge''e ira ba ngai lala ba Zikhema.', '["Faigi 13:3","SamI 15:22; Amaed 21:3; Mat 9:13","Faigi 8:1"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 10, 'Horö sa nilaura! Sihokha mbuda ni''ilagu ba mbanua Ndraono Gizeraeli: No mame''e-me''e adu ba da''ö mado Geferayi, no lata''unöi dangara Iraono Gizeraeli.', '["Faigi 13:3","SamI 15:22; Amaed 21:3; Mat 9:13","Faigi 8:1"]', NULL),
  (3476446, 'OT', 'Hosea', 6, 11, 'Ba ba khömi göi, ya''ami mado Yuda, ba famasi dania labe''e, na ufuli dania u''azökhi mbanuagu andrö.', '["Faigi 13:3","SamI 15:22; Amaed 21:3; Mat 9:13","Faigi 8:1"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 1, 'Ero na omasido u''orifi Ndraono Gizeraeli, ba oroma horö mado Geferayi ba si lö sökhi ba mbanua Zamaria, me no si falimo ira ba me manöinöi yomo zanagö, ba me no ato zi farabu-rabu, baero, ba lala.', '["RazII 15:10,14"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 2, 'Ba lö''ö sa lafatou-tou tödöra, wa lö olifulifu ndra''o mbua-buara andrö, si lö sökhi, fefu. Ba no te''u''u ira nilau-laura andrö; lö aefa-aefa ba duduma hörögu da''ö.', '["RazII 15:10,14"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 3, 'Labe''e fondrara dödö razora zi lö sökhi andrö khöra ba fondrara dödö zalaŵa labe''e wamini tödö andrö khöra.', '["RazII 15:10,14"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 4, 'Dozi ira, ba sohorö, timba nawu famogö roti, niböda duka roti alitö, irege no manöi gomböila roti andrö, si no mufaruka.', '["RazII 15:10,14"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 5, 'Na owasa khö razo, ba mabu agu zalaŵa andrö, irege akhömö-khömö ira. Ba i''oro''ö dangania ba zango''aya.', '["RazII 15:10,14"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 6, 'No timba nawu si''öli dödöra, ba walimosara andrö. Sara wongi manö mörö-mörö duka roti, ba ba zanguhulö wongi, ba ebua galitö, alitö sihola-hola.', '["RazII 15:10,14"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 7, 'Dozi ira, ba no hulö nawu si''öli, sebua alitö, ba tobali la''a zanguhuku ya''ira. Salaŵara fefu, ba no mubunu, ba samösa lö''ö ba khöra sangombakha khögu.[1]', '["RazII 15:10,14"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 8, 'No fao ba niha baero mado Geferayi; no tobali hulö kue si lö mubali''ö ira.[2]', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 9, 'Niha bö''ö zi manga wa''abölöra, ba lö la''ila; no tohare huwa, ba lö la''ila.', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 10, 'Ba si lö lai wa no ifaduhu''ö wolaura lakhömi Ndraono Gizeraeli andrö: lö nifulira ya''ira khö Lowalangira Yehowa, lö ni''aluira ya''ia, lö lai da''ö fefu.[3]', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 11, 'Folau mado Geferayi, ba no nifolau marafadi, sowöhö-wöhö ba si lö tödö; no lakaoni Ndrawa Miserayi, ba no la''angaröfi li Ndrawa Asiria.[4]', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 12, 'Ba me ba da''ö lasaŵa, ba utaŵi wuka, uhalö ira ba dalu mbanua ba u''otu''ö, dali zi no mufarongogö ba mbanuara;', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 13, 'Alai ira, me no la''erogö ndra''o! Ya itörö ira fa''adudu, me no lalaŵa ndra''odo! He na edöna ndra''o u''orifi ira, ba lalau waya, wamatunö wolaugu.', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 14, 'Ba tenga soroi ba dödöra wangaröfi li ya''odo, ha fege-ege tou ba zalo. Ba lakhoi nösira, wolaŵa ya''odo, ena''ö abölö mbua nowi, awö nagu.', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 15, 'Ba noa sa atö ya''o zamobawa lala khöra ba sangabe''e''ö tangara. Ba no si lö sökhi dödöra khögu.', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476447, 'OT', 'Hosea', 7, 16, 'Labali''ö sa furi ira, ba no tenga miyaŵa. Hulö wana si lö aefa ira! Ba salaŵara, ba nibunu si''öli, börö mbewera andrö, fönura andrö — andrö wa la''igi''igi''ö dania ira ba danö Miserayi.[5]', '["Sin 106:35","Faigi 5:5","RazII 17:4; Faigi 5:13","Sin 78:57; Yes 30:3"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 1, 'Lau dorofe! Lau''ö ba nomo Yehowa, hulö si mane moyo! Me no lasaŵo nifakhoigu ba me no molaŵa ira, ba niŵa''ögu khöra.[1]', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 2, 'Ba mu''ao ira khögu, lamane: He Lowalangigu! Aboto sa ba dödöma ndra''ugö, ya''aga Iraono Gizeraeli!', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 3, 'Ba no lö ba dödö Ndraono Gizeraeli fangorifi andrö — ba alakha lagohi ira emali!', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 4, 'No lafataro razo, ha ya''ira, si tenga balazi ndra''odo; no latuyu högöra, si lö nirongogu. No lafahele adu wiröra ba ana''ara; ba hadia gunania? Ha sambalö famakikora.[2]', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476448, 'OT', 'Hosea', 8, 5, 'Ono zaŵi andrö khömi, ya''ami banua Zamaria, ba no aböu; no tesao wönugu khöra. Ha wa''ara na dania, wa tebai si lö horö ira![3]', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 6, 'No ba Ndraono Gizeraeli mbörötania [böröta zaŵi andrö] no tuka zolau ya''ia, ba tenga Lowalangi ia. Nifufu sa dania zaŵi Zamaria andrö!', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 7, 'Angi sa nitarura, ba angi sabölö dania labasi; lö töla, sauri andrö, ba si lö ösi, ba na so ena''ö, ba niha bö''ö zi manga.', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 8, 'Ni''a Ndraono Gizeraeli! Amaedola wakake si lö guna sa''ae ira, ba niha baero![4]', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 9, 'Me no möi ba Ndrawa Asiria mado Geferayi, timba galide ndru''u, somasi si lö awö-awönia, ba no lafakhai zi fahuwu khöra, nifoluo.[5]', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 10, 'Ba famakhaira si fahuwu khöra andrö, ba niha baero, mbörö, wa usasagö sa''ae ira, ena''ö lö ara tö mangarö-ngarö ira, ba mbeo andrö, nibe''e khö razo sebua andrö.', '["MozV 28:49; Faigi 5:8; 6:7","RazI 12:20; Faigi 2:8","RazI 12:28","Yes 30:14; Yer 22:28","Hez 16:33"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 11, 'Noa sa''ae oya lafa''anö naha wame''e sumange mado Geferayi, ba lua-luania khöra, ba no ba horö ba Lowalangi.', '["Faigi 6:6; Yes 66:3"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 12, 'Ba he uhöna wamakhoi khöra lala, ba hulö nifakhoi niha bö''ö wamaigira.', '["Faigi 6:6; Yes 66:3"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 13, 'Lataba zumange nitaba ba la''a nösi, ba lö omasi Yehowa ira. Ba lö olifulifu ia wa''atefuyura, ba i''otu''ö dania horöra Ya''ira andrö dania zangawuli ba danö Miserayi ba si manga gö salakha ba danö Ndrawa Asiria.[6]', '["Faigi 6:6; Yes 66:3"]', NULL),
  (3476448, 'OT', 'Hosea', 8, 14, 'Me no olifu Ndraono Gizeraeli zomböi ya''ira mege, ba me no lalau gödo khöra, ba me no la''oya''ö khöra mbanua saro mado Yuda, ba ufa''ohe''ö galitö ba mbanuara andrö, alitö si manga hati andrö khöra.', '["Faigi 6:6; Yes 66:3"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 1, 'Böi mi''abölögö wangomusoi''ö tödömi, ya''ami Iraono Gizeraeli, böi si mane niha baero! Noa sa mierogö Lowalangimi, no faröi ami; no omasi ami luo wohorö ba golayama mbasitö misa fefu.', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 2, 'Ba i''ositengö sa ira olayama mbasitö ba he folazi mbua nagu; ba lö khöra dania.', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 3, 'Aheta dania ira ba danö Yehowa andrö. Sangawuli ba danö Miserayi mado Geferayi, ba si manga gö salakha ba danö Asiria.[1]', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 4, 'Lö''ö sa''ae lafaduwa nagu khö Yehowa, ba lö''ö sa''ae la''asiwai khönia zumange nitaba andrö khöra. Timba gö ba wa''abu dödö göra dania; dozi si manga ya''ia, ba ra''i-ra''iö. Ha sa famadöhö wa''olofora göra, ba lö''ö sa irugi gosali Yehowa.[2]', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 5, 'Ba he miwisa na baŵa gowuloa ba na owasa khö Yehowa?', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 6, 'Hiza no lö ikhamö ira famunu, ba wa''adudu andrö, ba ba danö Miserayi gahonoa, ba Membisi lewatöra dania; ahonoa nayara firö, ba ba lato, ba sa''a-sa''a mao zi tumbu ba nosera.[3]', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 7, 'Irugi dania baŵa wangotu''ö, irugi baŵa wamasulöni, ba nisöndra Ndraono Gizeraeli fa''aboto ba dödö, me no lamane: Sowöhö mowa zama''ele''ö andrö ba sowöhö zi so Eheha! Ba lazi wa''abölö wa''atefuyumi ba fatiusami andrö.', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 8, 'Sanaronaro mado Geferayi ba gametahö Lowalangigu. Khö zama''ele''ö andrö, ba no lalau wesu, nifolau zama''ala fofo, ba bölödi, ba gosali Lowalanginia.', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 9, 'No manao horö sebua ira, si mane ba Gibea no: lö olifu ia golalöŵara, i''otu''ö dania horöra!', '["Hez 4:13","MozV 26:14","Yes 32:13; 34:13"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 10, 'Nisöndragu Ndraono Gizeraeli, timba mbua nagu ba danö si mate, ba fangilagu ira tuami, ba no timba wangilada si a''a mbua ara ba hogu zawena mowua. Ba me larugi Mba''ali Weoro andrö, ba lalau mamosumange adu, ba tobali sogoro ita ira, si mane ni''olembaira andrö.[4]', '["MozIV 25:3; Yer 24:1 b.t.","Faigi 4:15; Yes 1:23"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 11, 'Hulö wofo soloi dania [wa''ataya] mado Geferayi sato andrö; tebato wo''ono, lö''ö sa''ae manabina, lö''ö sa''ae mutuge nono.', '["MozIV 25:3; Yer 24:1 b.t.","Faigi 4:15; Yes 1:23"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 12, 'Ba he la''e''ebua nonora matua, ba uheta dania khöra, ena''ö lö ira matua sa''ae dania. Ba he ya''ira göi, ba alai ira, na lö''ö sa''ae ufaigi ira!', '["MozIV 25:3; Yer 24:1 b.t.","Faigi 4:15; Yes 1:23"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 13, 'No timba Diro nitaru''ö ba ndraso mado Geferayi wamaigigu, ba lalulu dania ba danga zange''e nonora matua mado Geferayi andrö.', '["MozIV 25:3; Yer 24:1 b.t.","Faigi 4:15; Yes 1:23"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 14, 'Be''e khöra zomasi''ö öbe''e khöra, ya''ugö Yehowa! Böda khöra nösi dalu ba ösi zusu!', '["MozIV 25:3; Yer 24:1 b.t.","Faigi 4:15; Yes 1:23"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 15, 'Ba Giligala lafazökhi horöra andrö fefu. Ba da''ö sa tesao wa''udusagu khöra. Uheta ira ba nomogu andrö, ufofanö ira, börö zi lö sökhi andrö nilaura. Lö''ö sa''ae u''omasi''ö ira! Salaŵara fefu, ba no si fa''ero [khögu].[5]', '["MozIV 25:3; Yer 24:1 b.t.","Faigi 4:15; Yes 1:23"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 16, 'No göna famunu mado Geferayi, obou ŵa''a, tebai sa''ae mowua! Ba he na mo''ono ira, ono matua, ba ubunu nonora omasiö andrö.', '["MozIV 25:3; Yer 24:1 b.t.","Faigi 4:15; Yes 1:23"]', NULL),
  (3476449, 'OT', 'Hosea', 9, 17, 'Itibo''ö ira Lowalangigu; me no lö nifondrondrongora linia: alakha si lö hinaoma ira ba niha baero misa!', '["MozIV 25:3; Yer 24:1 b.t.","Faigi 4:15; Yes 1:23"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 1, 'Töla nagu sabölö manöi Ndraono Gizeraeli mege, ba si sökhi fowua. Ba itugu abölö mbua, ba oya lafa''anö khöra naha wame''e sumange [ba nadu]; itugu abölö mbua danö, ba itugu lafazökhi khöra nadu nihaogö.[1]', '["Yes 5:3; Faigi 8:11","Faigi 3:4","RazII 23:5; Sef 1:4","Faigi 5:13","Yes 2:19; Luk 23:30"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 2, 'No tödö si falimo dödöra; andrö wa ni''otu''ö ira. Ya''ia zanudugö naha wame''e sumange andrö khöra, ba irasa nadura.', '["Yes 5:3; Faigi 8:11","Faigi 3:4","RazII 23:5; Sef 1:4","Faigi 5:13","Yes 2:19; Luk 23:30"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 3, 'Lamane sa dania: Lö khöma razo sa''ae, me no lö ni''ata''ufima Yehowa. Ba hadia guna razo khöma?[2] —', '["Yes 5:3; Faigi 8:11","Faigi 3:4","RazII 23:5; Sef 1:4","Faigi 5:13","Yes 2:19; Luk 23:30"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 4, 'Hadia, samagölö [ba nawönia] ia, si möi ia ba hölu si lö itörö, ba ma si fawu''uwu''u li wamatumbu''ö huku si bohou, timba ndru''u langu ba nowi, na no lafaku?', '["Yes 5:3; Faigi 8:11","Faigi 3:4","RazII 23:5; Sef 1:4","Faigi 5:13","Yes 2:19; Luk 23:30"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 5, 'Saŵi si matua andrö ba Mbeti Awene ni''abusi mbanua Zamaria tödö dania; abu dödö zi olembai ya''ia, mege, ba manizi-nizi gerenia ba khönia, dania, — ba girö-girö andrö khönia, me saheta khönia.[3]', '["Yes 5:3; Faigi 8:11","Faigi 3:4","RazII 23:5; Sef 1:4","Faigi 5:13","Yes 2:19; Luk 23:30"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 6, 'Ba ya''ia na''i, ba ni''oloi''ö ba danö Asiria, buala khö razo Yarebi; fa''aila mado Geferayi andrö ihalö khönia, ba tobali faya wanötöna Ndraono Gizeraeli ba nikhoi dödöra andrö.[4]', '["Yes 5:3; Faigi 8:11","Faigi 3:4","RazII 23:5; Sef 1:4","Faigi 5:13","Yes 2:19; Luk 23:30"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 7, 'Safufu Zamaria andrö, ba razora, ba si hulö wahawaha geu solangi ba dete nidanö.', '["Yes 5:3; Faigi 8:11","Faigi 3:4","RazII 23:5; Sef 1:4","Faigi 5:13","Yes 2:19; Luk 23:30"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 8, 'Sadudu dania hili-hili famakiko andrö, horö Ndraono Gizeraeli andrö, ba lato ba sa''a-sa''a mao zi tumbu dania ba naha wame''e sumange andrö khöra. Ba ba da''ö dania lamane ba hili: Mihawui ndra''aga! Ba ba hili-hili: Milangögöga![5]', '["Yes 5:3; Faigi 8:11","Faigi 3:4","RazII 23:5; Sef 1:4","Faigi 5:13","Yes 2:19; Luk 23:30"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 9, 'I''otarai götö ba Gibea andrö, ba no molalö ami, ya''ami Iraono Gizeraeli. Lö si tebulö ira ba da''ö, ba ikhamö ira fanuwö sanao horö andrö ba Gibea andrö.[6]', '["Faigi 9:9","Amaed 11:18","RazII 17:3"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 10, 'Na edöna ndra''o, ba u''ila u''otu''ö ira, ni''owuloi dania soi niha baero, solau khöra, wangotu''ö ya''ira ba lalöra andrö si no dua winaeta.', '["Faigi 9:9","Amaed 11:18","RazII 17:3"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 11, 'Mado Geferayi andrö, ba no hulö nono zaŵi si no muhaogö famamaha, somasi mamöbörö fakhe. Noa sa lö nibe''egu kalo mbagi ba mbaginia si sökhi andrö, mege, ba iya''e, ba ufokalo mbagi sa''ae mado Geferayi; ba sondröni famali''ö danö mado Yuda ba sondröni kori-kori ma''uwu Yakobo.', '["Faigi 9:9","Amaed 11:18","RazII 17:3"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 12, 'Fa''ahakhö dödö mitaru, ba so fönami wamasi dania, ibe''e fa''ebua dödö Lowalangi andrö! Mitua''ö zi bohou, me no irugi inötö, ba wangalui Yehowa, ena''ö i''ondrasi ami, ba ena''ö ifatörö khömi deu fangorifi.[7]', '["Faigi 9:9","Amaed 11:18","RazII 17:3"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 13, 'Ba me no mitaru horö, ba no famakiko nibasimi, ba no bua walimosami gömi! Noa sa tötönaföu gureta ba wanuwö andrö ba fa''ato zabölö andrö khöu!', '["Faigi 9:9","Amaed 11:18","RazII 17:3"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 14, 'Ba rumuru dania moroi sa zanuwö sato andrö khöu; ba banua saro andrö khöu fefu, ba ladudugö, si mane me idudugö Mbeti Arebeli Salama, me luo manuwö no, me la''ö''ötö nina ndraono, fabaya iraonora.[8]', '["Faigi 9:9","Amaed 11:18","RazII 17:3"]', NULL),
  (3476450, 'OT', 'Hosea', 10, 15, 'Si manö sibai dania wolaura khömi, ya''ami Iraono Gizeraeli me no hatö falösökhi khömi. Ba zanguhulö wongi dania mate nibunu razo Ndraono Gizeraeli!', '["Faigi 9:9","Amaed 11:18","RazII 17:3"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 1, 'Me ono''ono na Ndraono Gizeraeli, ba no omasido ira ba ukaoni zato andrö, uheta ba danö Miserayi.[1]', '["MozII 4:22; Mat 2:15","MozII 32:4; RazI 11:8","MozII 15:26"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 2, 'Ba na humededo khöra ba la''erogö ndra''o. Latataba zumange nadu ba lafosumange wamaedo andrö,[2]', '["MozII 4:22; Mat 2:15","MozII 32:4; RazI 11:8","MozII 15:26"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 3, 'ba ya''odo ba utuyu galogo mado Geferayi [nifolau ba Ndraono], ba uhagi ira. Ba lö la''ila, wa ufadöhö wökhöra.[3]', '["MozII 4:22; Mat 2:15","MozII 32:4; RazI 11:8","MozII 15:26"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 4, 'No udöni ira sinali, si mane ni''oguna''ö niha, fesu fa''omasi, ba no amaedola zolulu kalo mbagi andrö, ba mbagira, ndra''odo, ba u''oro''ö göra.', '["MozII 4:22; Mat 2:15","MozII 32:4; RazI 11:8","MozII 15:26"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 5, 'Sangawuli ba danö Miserayi ira, ba razo Ndrawa Asiria razora dania, me no te khöra wamuli ya''ira khögu.', '["MozII 4:22; Mat 2:15","MozII 32:4; RazI 11:8","MozII 15:26"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 6, 'Ba nidöni sa''ae zi''öli, ba wolau ba mbanuara andrö, famufu lazi mbawa göli ba si manga hati andrö khöra.', '["MozII 4:22; Mat 2:15","MozII 32:4; RazI 11:8","MozII 15:26"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 7, 'Noa sa aso''ala dödö mbanuagu andrö, wangerogö ya''odo; ba he na mu''ao ita khöra: miyaŵa! ba samösa lö sedöna.', '["MozII 4:22; Mat 2:15","MozII 32:4; RazI 11:8","MozII 15:26"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 8, 'Ba hadia, tola uböhöli ami, ya''ami mado Geferayi, tola ululu ami, ya''ami Iraono Gizeraeli? Tola uböhöli ami si mane Adama no, tola ubali''ö Sebo''i ami? Tobali bakha dödögu, ba no a''oi tesao wa''ahakhö dödögu.[4]', '["MozI 14:2; 19:24","MozIV 23:19","Yes 60:8"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 9, 'Böi molua-lua wönugu saukhu andrö; lö ufalua wamakiko mado Geferayi. Me no Lowalangi ndra''odo, ba me tenga niha, u''iagö ba khömi, Lowalangi ni''amoni''ö, ba lö tesao wönugu.[5]', '["MozI 14:2; 19:24","MozIV 23:19","Yes 60:8"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 10, 'La''o''ö dania khö Yehowa; sindröndröndröndrö ia, hulö zingo; sindröndröndröndrö ia, ba so moroi sa ba mbewe nasi nono matua, manizi-nizi.', '["MozI 14:2; 19:24","MozIV 23:19","Yes 60:8"]', NULL),
  (3476451, 'OT', 'Hosea', 11, 11, 'So ira moroi sa, ba danö Miserayi, hulö wofo, manizi-nizi, hulö marafadi si oroi danö Asiria. Ba sahono baomora dania ira ube''e, iŵa''ö Yehowa.[6]', '["MozI 14:2; 19:24","MozIV 23:19","Yes 60:8"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 1, 'No tefasui manö mado Geferayi faya nilau khögu labe''e, ba si tefasui falimosa Ndraono Gizeraeli, ba mado Yuda, ba sanufa tödö manö na, ba khö Lowalangi ba ba khö Ni''amoni''ö andrö, si lö falimosa.', '["Faigi 5:13; 7:11"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 2, 'Mado Geferayi, ba no somasi angi sabölö ba lagohi nangi timu, ero ma''ökhö manö lahöna waya ba famakao awöra; fawu''u li ira ba Ndrawa Asiria; ba ba Ndrawa Miserayi, ba la''ohe wanikha.[1]', '["Faigi 5:13; 7:11"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 3, 'Ba ifatörö dania huku ba mado Yuda Yehowa, ba i''otu''ö ma''uwu Yakobo, dali mbua-buara, ba isulöni khöra nilau-laura andrö.', '["Faigi 5:13; 7:11"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 4, 'Ba dalu ninara ilimo ga''ania [Yakobo], ba me no ira matua ia, ba si fasöndra khö Lowalangi ia.[2]', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 5, 'No fasöndra ira mala''ika andrö, ba Yakobo zabölö: mege-ege ia ba i''andrö wa''ahakhö dödö khö mala''ika andrö. Ba Mbetieli falukha khönia mala''ika andrö, ba ba da''ö fahuhuo ia khönia[3] —', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 6, 'Yehowa andrö, Lowalangi ngahönö, ya''ia andrö, sotöi Yehowa.', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 7, 'Ba si manö göi ndra''ugö ena''ö, wamuli ya''ugö khö Lowalangiu. Fa''omasi ba fa''atulö fa''ua, ba böi aetu wanötönamö khö Lowalangiu!', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 8, 'Ba danga Ndrawa Gana''ana so waliera faya, ya''ia zomasi mangalani awönia.[4]', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 9, 'Ba imane [göi] mado Geferayi: Ha fangebua ana''a ni''aluigu; ena''ö na ebua gana''agu dödögu. Ba ba wangaluigu andrö fefu, ba tebai lafo''esuanö ndra''o, tebai labe''e horögu hadia ia.[5]', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 10, 'Ba ya''odo Yehowa, ba no Lowalangimö ndra''odo, i''otarai ba danö Miserayi no — ba u''ila ufuli ufa''aso ba nose ndra''ugö, si mane me luo walukhata andrö [ba gahe hili Horebi] —[6]', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 11, 'ba no tenga ha samuza humede ndra''o ba zama''ele''ö andrö; ya''odo zangoya''ö fame''e angilata ba same''e molau amaedola zama''ele''ö andrö.', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 12, 'Na si lö ngaroro mbanua Gileadi andrö, ba nihori ira; na labe''e sumange zaŵi si matua, ba Giligala, ba nibali''ö baho kara ba nihölu nowi naha wame''e sumange andrö khöra.[7]', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 13, 'Me moloi Yakobo, me isaŵa danö Mezofotami, ba tobali sawuyu Gizeraeli, böli ndra alawe; böli ndra alawe wa kubalo mbiri-biri ia.[8]', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 14, 'Sama''ele''ö ifataro Yehowa, ba wangeheta Iraono Gizeraeli ba danö Miserayi, ba sama''ele''ö zamaigi-maigi ya''ira.', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476452, 'OT', 'Hosea', 12, 15, 'Ba no sangandrö fönu mado Geferayi. Andrö wa ibe''e ba hulura wange''enge''era andrö sokhö ya''ira, ba mangandrauli khöra horöra andrö ibe''e.', '["MozI 25:26; 32:25–29","MozI 28:19; 35:10","MozI 14:2; 19:24","Fam 3:17","Yes 43:11","Faigi 4:15; 6:8","MozI 28:2; 29:20"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 1, 'Ero na lafeta''u niha bö''ö mado Geferayi, föna, ba salaŵa ira wamaigi Ndraono Gizeraeli. Ba no mosala ira, me no mame''e-me''e adu ira, ba mate-mate ira.[1]', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 2, 'Ba he ma''ökhö andre, ba latohu-tohugö wamazökhi horö: no labali''ö adu nifahele wiröra, adu bö''ö nibe''e famaedo — ba ha sambalö halöŵö duka da''ö fefu. Da''ö ni''angaröfira li! Niha same''e sumange, ba fa''ago bawa ba zaŵi si matua![2]', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 3, 'Andrö wa tobali timba lawuo ba zanguhulö wongi ira ba timba namo mbanua, salio sibai taya, ba timba ndrami wakhe, ni''oloi''ö nangi, moroi ba golayama mbasitö, ba timba zimbo, sanörö bawa duwutuwu.[3]', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 4, 'Ba ya''odo, Yehowa, ba noa sa atö Lowalangimö ndra''odo, i''otarai ba danö Miserayi sa''ae — tanö bö''ö, si no Lowalangi göi, ba lö ni''ilau; ba tanö bö''ö, si no sangorifi göi, ba lö''ö.[4]', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 5, 'Ya''odo mege zame''e gömi ba danö si mate, ba danö si no oköliköli tou.[5]', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 6, 'Ba itugu oya göra, ba itugu abölö lafo''ösi dalura, ba me no abölö lafo''ösi dalura, ba me no abölö sibai la''abusoi''ö ira, ba tesao hokha, ba tobali olifu ira ndra''odo.[6]', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 7, 'Andrö wa no timba zingo ndra''o khöra; udaro-darogö ira ba zinga lala, hulö si mane harimo;', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 8, 'ura''u ira nifondra''u mberua si alawe, niheta ono, ba ure''a göröba dödöra (totora) Ba da''ö la''a ira ono zingo, ba lasasawi ira utu ndru''u.[7]', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 9, 'Na ufakiko ami, ya''ami Iraono Gizeraeli, ba ha niha zangorifi ya''ami?', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 10, 'Ba heza so iada''e razomi, ena''ö i''orifi ami, ba he högömi andrö fefu, ba wolohe ba lala huhuomi andrö? niŵa''ömi: Fataro khöma razo ba satua![8]', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 11, 'Ufa''aso khömi razo, ba wönugu andrö, ba ufuli uheta ia ba wa''abao dödögu!', '["Sanguhuk 8:1; 12:1","RazI 19:18; Faigi 2:8","Sin 1:4; Dan 2:35","MozII 20:2; Faigi 12:10; Sin 18:32; Yes 45:22","MozV 8:15; 32:10","MozV 32:15","SamII 17:8; Amaed 17:12","SamI 8:5; 16:1"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 12, 'Lalö mado Geferayi andrö, ba no mube''e yaŵa, ba horöra, ba no mu''irö''ö.', '["Yes 25:8; KorI 15:55; Rom 11:29","MozI 41:32"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 13, 'Tesao khöra wa''afökhö hulu; ba no timba ndraono, si lö mamondrongo li, ira. Na inötö sa''ae, ba lö tumbu ira.', '["Yes 25:8; KorI 15:55; Rom 11:29","MozI 41:32"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 14, 'Hadia, ufaigi khöra wa''aefa ba wa''abölö mbanua tou, u''efa''ö ira ba wa''amate? Hezo wökhö andrö khöu, ya''ugö fa''amate? Hezo wamakao andrö khöu, ya''ugö banua tou? Lö''ö sa''ae u''ila wa''ahakhö dödö![9]', '["Yes 25:8; KorI 15:55; Rom 11:29","MozI 41:32"]', NULL),
  (3476453, 'OT', 'Hosea', 13, 15, 'He ŵa''ae no timba geu sowua mado Geferayi, ba ngai mado bö''ö andrö, fabaliŵara, ba ilabu zui angi timu, angi sabölö khö Yehowa, ba danö si mate tesao ia, ba tobali ogo''ö nidanö ba mba''a ba aetu nulu mbombo. Ba ya''ia [razo Ndraono Gizeraeli] zangohori gama-gama andrö fefu ba naha girö-girö khönia.[10]', '["Yes 25:8; KorI 15:55; Rom 11:29","MozI 41:32"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 1, 'Tohare wotu ba Zamaria, me no lö ba dödöra li Lowalangira. Ba mbawa zi''öli mate ira; ono sawuyu, ba nirasa dania; ba sanabina, ba nisiköi talu.[1]', '["RazII 15:16","Hez 18:32","Sin 116:14; Yes 57:19; Heb 13:15"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 2, 'Mifuli ami khö Lowalangimi Yehowa, ya''ami Iraono Gizeraeli! Olalöŵami andrö wamakikomi.[2]', '["RazII 15:16","Hez 18:32","Sin 116:14; Yes 57:19; Heb 13:15"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 3, 'Mi''ohe daroma li (fangesa dödö) wamuli ya''ami khö Yehowa, ba mimane khönia: Be''e aefa khöma horöma, fefu, ba hakhösi tödö ndra''aga, ba mabe''e salahi zumange ono zaŵi mbewema andre:[3]', '["RazII 15:16","Hez 18:32","Sin 116:14; Yes 57:19; Heb 13:15"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 4, '"Lö''ö sa''ae ma''andrö tolo ba Ndrawa Asiria, lö''ö sa''ae fakudo ndra''aga, ba lö''ö sa''ae mabe''e töi nekhe-nekhe dangama "Lowalangima", khöu sa lasöndra wa''ahakhö dödö si lö ama si lö ina."', '["RazII 15:16","Hez 18:32","Sin 116:14; Yes 57:19; Heb 13:15"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 5, 'Ufuli dania ufadöhö lua-lua wangerogöra ya''o andrö, ba aoha gölögu wangomasi''ö ya''ira, noa sa alö wönugu khöra.', '["Sin 52:10; SinSeb 4:11","Sin 107:43; Amaed 10:29; Dan 12:10; KorII 2:16"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 6, 'Timba namo mbanua dania ndra''odo ba Ndraono Gizeraeli: mobowo dania ira, si mane ladari mböhö, ba moŵa''a, si mane eu gatua ba hili Libano.', '["Sin 52:10; SinSeb 4:11","Sin 107:43; Amaed 10:29; Dan 12:10; KorII 2:16"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 7, 'Ba atabö lewiöra, ba hogu, ba timba hogu zai, ba fa''amohuania, ba timba wa''amohua ba hili Libano.[4]', '["Sin 52:10; SinSeb 4:11","Sin 107:43; Amaed 10:29; Dan 12:10; KorII 2:16"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 8, 'Ba si so nahia ba lumöra, ba ifuli lasöndra mbua nowi ba mobowo, si mane agu; ebua dania duriara, timba duria nagu ba hili Libano.', '["Sin 52:10; SinSeb 4:11","Sin 107:43; Amaed 10:29; Dan 12:10; KorII 2:16"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 9, 'He ya''ami mado Geferayi! Hadia guna nadu andrö khögu sa''ae dania? Ya''odo andre zamondrongo khöra dania ba uhörö-hörögö ira; no timba zenobari si sökhi lehelehe ndra''odo! Buami andrö dania, ba ya''odo zangasogö.', '["Sin 52:10; SinSeb 4:11","Sin 107:43; Amaed 10:29; Dan 12:10; KorII 2:16"]', NULL),
  (3476454, 'OT', 'Hosea', 14, 10, 'Ha niha zatua-tua, ba wanöndra da''ö, ba ha niha zi so tödö, saboto ba dödö ya''ia? Sadölö sa lala andrö khö Yehowa. Latörö satulö tödö, ba sangerogö Yehowa, ba alau ba lala andrö.[5]', '["Sin 52:10; SinSeb 4:11","Sin 107:43; Amaed 10:29; Dan 12:10; KorII 2:16"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 1, 'Taroma li Yehowa, niŵa''önia khö Yoeli, ono Wetueli.', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 2, 'Mifondrondrongo da''e, ya''ami satua, mibe''e mbörö dalingami, ya''ami niha ba danö, fefu! Hadia, no irai si manö ba götömi. Ba ma ba götö ndra tuami?', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 3, 'Midunö-dunö ba ndraonomi, ba iraonomi zanutunö ba ndraonora, ba iraono da''ö, ba sama''ema mitou!', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 4, 'Si lö ahori i''a tamo lea, ba i''a era, ba si lö ahori i''a era, ba ifakiko föla, ba si tosai ba wöla, ba i''a siliŵi.[1]', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 5, 'Mifaoso, ya''ami si mabu andrö, ba mi''ege-ege! Mi''angarö-ngarö, ya ami samadu-madu agu, fefu, me no muböda ba mbawami nidanö nagu!', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 6, 'Noa sa ihawui danögu soi baero, soi sabölö, si lö mutaha mu''erai ha wa''ato niha; ifö zingo niföra ba boha zingo si alawe mbohara.', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 7, 'Tola nagu khögu, ba no lafufu, ba töla ara khögu, ba no lafatö; no ahori labo''a guli ba no laso''agö, tobali afusi manö ndraha;', '["MozII 10:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476455, 'OT', 'Yoeli', 1, 8, 'Mi''ege-ege, timba nono alawe, si no mamaru baru ba wa''abu dödö, wamato-matou tödönia soniha ya''ia, me ono alawe ia!', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 9, 'Lö''ö sa''ae sumange ni''a ba lö''ö sa''ae sumange nibadu ba gosali Yehowa; abu dödö gere, enoni Yehowa.', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 10, 'No mubali''ö tanö si mate mbenua ba no sabu tödö danö salo''o; noa sa mufufu zinanö ba nowi, otufo nösi nagu, ariri wanikha.', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 11, 'Ya afusi mbawami wa''aila, ya''ami sangahalö, ba mi''ege-ege, ya''ami sokabu nagu, ba gandru andrö ba ba ze''iri; me si lö boto sa''ae mbasitö ba nowi.', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 12, 'Töla nagu ba no mate, ba ara, ba aleu, ba he dalimo ba ohi ba ma''ufa, ba eu ba mbenua fefu, ba oi mate-mate; ba noa sa ogo''ö wa''omuso dödö nono niha.', '["MozII 10:14"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 13, 'Mi''obaru [mbaru ba wa''abu dödö] ba mi''ege-ege, ya''ami sangai halöŵö ba naha wame''e sumange! Mi''ae bakha [ba gosali], ba sara wongi böi miheta nukha ba wa''abu dödö, ya''ami enoni Lowalangigu! Me lö''ö sa''ae falukha zumange ni''a ba he sumange nibadu, ba gosali Lowalangimi.', '["Faigi 2:15","Yes 13:6; Faigi 2:1","Sin 104:20; 147:9"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 14, 'Miŵa''ö wamoni ni''amoni''ö, mikaoni zato ba gowuloa! Mifa''aso zatua, awö niha ba danö fefu, ba gosali Lowalangimi Yehowa, ba mikao khö Yehowa.[2]', '["Faigi 2:15","Yes 13:6; Faigi 2:1","Sin 104:20; 147:9"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 15, 'Alai mbaŵa da''ö! Noa sa ahatö mbaŵa andrö khö Yehowa, so moroi sa wanudugö, nifatörö Zi lö ambö fa''abölö.[3]', '["Faigi 2:15","Yes 13:6; Faigi 2:1","Sin 104:20; 147:9"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 16, 'Hadia, tenga no muböda fönada göda, ba he fa''omuso dödö ba fa''iki ba gosali Lowalangida?', '["Faigi 2:15","Yes 13:6; Faigi 2:1","Sin 104:20; 147:9"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 17, 'No ariri ba danö wakhe si no mutaru, si lö ösi lou, awö halasa, ba si no adudu naha mbalazo, me no mate zinanö ba nowi.', '["Faigi 2:15","Yes 13:6; Faigi 2:1","Sin 104:20; 147:9"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 18, 'Mu''ö''ö''ö''ö sibai gurifö, ba sihufa ngawawa zaŵi, me lö öra, fefu gofu heza! Ba famakao sa''ae göi ba ngawawa mbiri-biri.', '["Faigi 2:15","Yes 13:6; Faigi 2:1","Sin 104:20; 147:9"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 19, 'He Yehowa, ya''ugö u''angaröfi li! Me no akhozi mbenua si so du''u mege, ba me no ariri ba hola-hola galitö geu ba danö, fefu.', '["Faigi 2:15","Yes 13:6; Faigi 2:1","Sin 104:20; 147:9"]', NULL),
  (3476455, 'OT', 'Yoeli', 1, 20, 'Ba he utu ndru''u, ba mangarö-ngarö khöu, me no ogo''ö mbombo ba me no i''a alitö mbenua, si so du''u mege.[4]', '["Faigi 2:15","Yes 13:6; Faigi 2:1","Sin 104:20; 147:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 1, 'Milau dorofe ba Ziona, ba mibözi garamba, ba hili ni''amoni''ö andrö khögu, ena''ö manizi-nizi niha ba danö, fefu! Irugi sa dania baŵa andrö khö Yehowa, no ahatö ia.[1]', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 2, 'Baŵa wa''ogömi-gömi, ba baŵa wa''abongi, ba baŵa wa''alu, ba fe''ugu-ugu mbanua ba zi bongi, timba na ibörögö fa''amoluo ba hili misa. Sato sibai ba sabölö [zi so moroi sa], si lö murai mu''ila; i''otarai götö föna sibai, ba si lö''ö sa''ae göi dania, irugi götö wondrege mitou.[2]', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 3, 'Sowaö-waö fönara, ba no alitö si manga-manga hadia ia ba hola-hola galitö göi moroi furira. Ba na no timba kabu no, ba Gedena danö fönara mege, ba no tanö si mate mbenua furira, ba lö fangorifi ba khöra andrö!', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 4, 'Kudo ira, wamaigida, ba fa''alio zi fakudo wa''aliora.[3]', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 5, 'Si mane feruru gureta, na lafanoka ira, na lasawö zuzu hili ba si mane feriri hola-hola galitö, na akhozi go''o, timba zanuwö si no ato, ba si no mangaro ba wasöndrata.', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 6, 'Manizi-nizi fönara soi niha; dozi niha, ba no safusi bawa.[4]', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 7, 'Fagohisa zabölö wagohisara, lasawö göli kara, si mane sanuwö si no to''ölö; lalania itörö zamösana, ba samösa lö sanaŵa lala nawönia.', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 8, 'Lö sanimba awönia, idölö manö zamösana; latörö manö doho ni''oludu, fagohi manö, lö labadugö ira.', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 9, 'Ladörö-döröi newali, ba si fulö-fulöi ira ba dete göli kara, manöi yomo ira, latörö zandrela, si mane sanagö.', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 10, 'Moduru danö fönara, ba humisi mbanua si yaŵa; ndrundrumö luo, fabaya baŵa, ba taya haga ndröfi.[5]', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 11, 'Ba ife''ugu-ugu mbanua Yehowa, föna zabölö andrö khönia; me no ato sibai zanuwö andrö khönia, ba me no sabölö zamatörö niŵa''önia andrö! Baŵa sebua sa mbaŵa andrö, khö Yehowa, ba sata''u sibai ita: ha niha zanaha![6]', '["Sef 1:14; Yes 13:6","Amos 5:18","Fam 9:9","Nakh 2:11","Yes 13:10","Yes 30:7"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 12, 'Ba iya''e na göi, ba da''ö niŵa''ö Yehowa: Mifalalini gera-erami, soroi si''aikö ba dödömi, ya fao wamoni ba fege-ege ba fangarö-ngarö![7]', '["Yer 4:1","Sin 51:19; MozII 34:6","SamII 12:22; Yon 3:9","Faigi 1:14","Sin 42:11; 70:10; 115:2; Mikh 7:10"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 13, 'Tödömi mire''a, ba tenga nukhami, ba mifuli ami khö Lowalangimi Yehowa! Me no sebeoa tödö ia ba me no sahakhö tödö; lö aösö mofönu ia, ba no fahöna wa''asökhi dödönia, ba mangesa dödönia ba wamakao andrö.[8]', '["Yer 4:1","Sin 51:19; MozII 34:6","SamII 12:22; Yon 3:9","Faigi 1:14","Sin 42:11; 70:10; 115:2; Mikh 7:10"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 14, 'Ha zangila, na lö ifuli mangesa dödönia dania, ba ma iröi khömi howu-howu: sumange ni''a ba sumange nibadu, khö Lowalangimi Yehowa.[9]', '["Yer 4:1","Sin 51:19; MozII 34:6","SamII 12:22; Yon 3:9","Faigi 1:14","Sin 42:11; 70:10; 115:2; Mikh 7:10"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 15, 'Milau dorofe ba hili Ziona! Miŵa''ö wamoni ni''amoni''ö mikaoni niha sato fefu ba gowuloa![10]', '["Yer 4:1","Sin 51:19; MozII 34:6","SamII 12:22; Yon 3:9","Faigi 1:14","Sin 42:11; 70:10; 115:2; Mikh 7:10"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 16, 'Mi''owuloi niha sato, mi''amoni''ö mbanua, mifa''aso zi no tohare huwa, mi''owuloi ndraono, — numalö si lö aefa na ba mbagi zusu; yamuröi mbate''enia sangowalu, ba ono nihalö, ba yamuröi wörömania!', '["Yer 4:1","Sin 51:19; MozII 34:6","SamII 12:22; Yon 3:9","Faigi 1:14","Sin 42:11; 70:10; 115:2; Mikh 7:10"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 17, 'Ndramege-ege gere andrö, enoni Yehowa, ba gotaluara gewe''ewe andrö naha wame''e sumange, ya lamane: Hakhösi tödö mbanuamö, Yehowa, ba böi be''e aila dana khöu, böi möi salaŵara niha baero! Hana wa öbe''e lamane niha baero: Heza so Lowalangira?[11]', '["Yer 4:1","Sin 51:19; MozII 34:6","SamII 12:22; Yon 3:9","Faigi 1:14","Sin 42:11; 70:10; 115:2; Mikh 7:10"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 18, 'Ba afökhö bakha dödö Yehowa ba danönia andrö, ba ihakhösi tödö mbanuania.', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 19, 'Humede Yehowa, imane ba mbanuania: Hiza, ube''e khömi mbua nowi ba agu ba fanikha, ena''ö abuso ami; ba lö''ö sa''ae ube''e la''o''aya ami niha baero.', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 20, 'Ba soroi yöu andrö, ba ba zaröu utimba ira khömi, ba danö si no oköliköli, ba danö si mate utibo''ö ira; si so föna, ba utimba ba zilua asi tanö ba gatumbukha, ba si so moroi furi, ba ba nasi tanö ba gaekhula, ba tobali möi yaŵa wa''aböu, hua zi no mate, me no si tenga inötö nilaura!', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 21, 'Böi busi dödöu, ya''ugö tanö, a''iki ba omusoi''ö dödöu, me no sebua nilau Yehowa!', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 22, 'Böi mibusi dödömi, ya''ami utu ndru''u; tumbu sa''ae ndru''u ba mbenua ba ndraso, mowua geu sowua: ara ba agu, ba no abölö mbua.', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 23, 'Ba ya''ami göi, ba gahe hili Ziona, mi''a''iki ba mi''omusoi''ö dödömi, ba khö Lowalangimi Yehowa, me ibe''e khömi deu, ba ginötö, ifa''ohe''ö mitou khömi deu, teu sahulö ba teu sara, si mane föna.[12]', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 24, 'Fahöna mbua nowi ba golayama mbasitö, ba si falawu agu ba fanikha wolazi.', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 25, 'Usalahini khömi zi lö''ö ba ndröfi andrö, me no la''a tamo lea ba era ba föla ba siliŵi, — soya andrö khögu, nidudugu khömi.[13]', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 26, 'Si fahöna dania gömi, ba abuso ami ba misuno döi Lowalangimi, Yehowa, si no mamatörö khömi sahöli-höli dödö, ba lö''ö manö sa''ae itörö mbanuagu famakiko.', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476456, 'OT', 'Yoeli', 2, 27, 'Ba ya aboto ba dödömi dania, wa no ya''odo zi so ba hunö Ndraono Gizeraeli; Yehowa sa atö ndra''odo, Lowalangimi, ba Lowalangi bö''ö, ba lö''ö; ba lö''ö manö sa''ae itörö mbanuagu famakiko.[14]', '["MozV 11:14","Faigi 1:4","Sakh 12:9"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 1, 'Ba na aefa da''ö, ba ulau Gehehagu ba niha fefu; ba mama''ele''ö dania nonomi matua ba onomi alawe, ba mangifi zatua khömi ba la''ila gangilata ono matua khömi.', '["Yes 44:3; Hez 39:29; HalZin 2:17 b.t.","Ayati 20; Mat 24:29","Obad a. 17; Rom 10:13"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 2, 'Numalö ba zawuyu ira matua ba ba zawuyu ira alawe, ba ulau Gehehagu, na luo da''ö.[1]', '["Yes 44:3; Hez 39:29; HalZin 2:17 b.t.","Ayati 20; Mat 24:29","Obad a. 17; Rom 10:13"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 3, 'Ba ufa''ele''ö dandra sahöli-höli dödö ba mbanua si yaŵa ba ba danö tou: dö ba alitö ba boto zimbo.', '["Yes 44:3; Hez 39:29; HalZin 2:17 b.t.","Ayati 20; Mat 24:29","Obad a. 17; Rom 10:13"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 4, 'Tobali ogömi-gömi luo ba do mbaŵa, gasa-gasa wa irugi baŵa sebua andrö, sata''u ita, khö Yehowa.[2]', '["Yes 44:3; Hez 39:29; HalZin 2:17 b.t.","Ayati 20; Mat 24:29","Obad a. 17; Rom 10:13"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 5, 'Ba dozi si angaröfi li töi Yehowa, ba ni''orifi; so sa wangorifi ba hili Ziona ba ba Yeruzalema, itörö niŵa''ö Yehowa, fangorifi zi tosai andrö, nikaoni Yehowa,[3]', '["Yes 44:3; Hez 39:29; HalZin 2:17 b.t.","Ayati 20; Mat 24:29","Obad a. 17; Rom 10:13"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 6, 'Hiza sa, na luo da''ö dania, na ufuli utolo mado Yuda, ba banua Yeruzalema,', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 7, 'ba u''owuloi soi niha baero, fefu, ba u''ohe mitou ira ba ndraso andrö khö Yozafati, ba wamatörö huku khöra ba da''ö, börö mbanuagu, tana khögu andrö, Iraono Gizeraeli, me no lafazaewe ba niha baero misa, ba me no lafaosa danögu;[4]', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 8, 'ba me no fadahö-dahö ira ba mbanuagu andrö; ono matua ba no labe''e böli ndra alawe sohorö-horö, ba ono alawe, ba no böli nagu khöra, ba no laforege wamadu-madu agu.', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 9, 'Hadia atö ni''aluimi khögu, ya''ami banua Diro ba banua Zidona, ba ya''ami fefu, ba danö Ndrawa Wilisiti? Hadia, khögu misulöni nilau khömi, ba ma milau khögu hadia ia? Da''u''aliogö sibai ube''e mangandrauli ba hulumi nilaumi andrö.[5]', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 10, 'Noa sa mirabu wirögu ba ana''agu, ba fondrege zi sökhi nayagu, ba no mibe''e ba gosali khömi.', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 11, 'Ba mado Yuda ba banua Yeruzalema, ba no mi''amawa ba Ndrawa Heleni, ba wangaröu''ö ya''ira, aefa ba mbanuara.[6]', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 12, 'Ba hiza, ba ususugi ira, ba mbanua andrö ba ni''amawami ya''ira, ba mangandrauli ba hulumi nilaumi ube''e.', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 13, 'U''amawa dania ba mado Yuda nonomi matua, fabaya onomi alawe, ba ya''ira ba la''amawa ba Ndrawa Zaba, soi ba zaröu sibai, me no Yehowa zanguma''ö!', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 14, 'Mifatenge zi''ao ba niha baero, mimane: Mifa''anö ami ba wanuwö ni''amoni''ö! Mifarou zabölö! Ndramufa''aso ira sanuwö fefu, ndramöi manuwö![7]', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 15, 'Mibali''ö föda wakumi ba rosömi, ba mibali''ö toho. Samomo, ba yamuŵa''ö: "Sabölö ndra''odo!"[8]', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 16, 'Mita''i-ta''i, mitabu, mi''owuloi ami, ya''ami soi si tefasui ya''aga! — Ba da''ö dania dada zabölö andrö khöu, ya''ugö Yehowa!', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 17, 'Faoma ndramufarou nawöra soi niha ba ndramusaŵa ndraso andrö khö Yozafati; ba da''ö sa dania dumadao ndra''o, ba wanguhuku soi niha andrö fefu, misa.', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 18, 'Milau zabi, me no basitö sa''ae; mi''aine ba mihundragö wolazi, me no mufo''ösi, si falawu to andrö, me no ebua sibai horöra![9]', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 19, 'Mongawawa ira wa''aso; me no ahatö mbaŵa andrö khö Yehowa, ba ndraso andrö, ba wangetu''ö huku.', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 20, 'Noa sa ndrundrumö luo, fabaya baŵa, ba no taya haga ndröfi.[10]', '["Nga''ötII 20","Hez 22:31","Hez 27:13","Yer 6:4","Yes 2:2; Mikh 4:3","Fam 14:15","Faigi 2:10"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 21, 'Ba si ndröndröndröndrö Yehowa, moroi ba Ziona, ba moroi ba Yeruzalema ifarongogö linia, ba tobali moduru mbanua si yaŵa, fabaya tanö; ba no saŵatö mbanuania Yehowa, ba no hati Ndraono Gizeraeli ia.[11]', '["Yes 31:4; Yer 25:30; Faigi 11:10; Hag 2:6; Heb 12:26","Sakh 14:21; Fam 21:27","Amos 9:13; Hez 47:1","Amos 1:11"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 22, 'Ba ya''aboto ba dödömi, wa no Yehowa ndra''odo, Lowalangimi; hili Ziona u''iagö, hili ni''amoni''ö andrö khögu! Ba Yeruzalema andrö, ba ni''amoni''ö; lö''ö sa''ae latörö ia niha bö''ö.[12]', '["Yes 31:4; Yer 25:30; Faigi 11:10; Hag 2:6; Heb 12:26","Sakh 14:21; Fam 21:27","Amos 9:13; Hez 47:1","Amos 1:11"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 23, 'Ba na luo da''ö, ba mowöi-wöi nösi nagu, ba hili misa; mangele nösi zusu moroi ba hili-hili, ba falawu idanö mbombo fefu, ba mado Yeda. Sambua dania gumbu ba gosali Yehowa, samo''idanö daso Zitimi andrö.[13]', '["Yes 31:4; Yer 25:30; Faigi 11:10; Hag 2:6; Heb 12:26","Sakh 14:21; Fam 21:27","Amos 9:13; Hez 47:1","Amos 1:11"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 24, 'Ba tanö Miserayi, ba si tobali tanö si mate, ba tanö Ndraono Gedomo, ba tobali benua si lö du''udu''u, börö horöra andrö ba Ndraono Gizeraeli, me no labe''e aduwa ndro zi lö horö, ba danöra.[14]', '["Yes 31:4; Yer 25:30; Faigi 11:10; Hag 2:6; Heb 12:26","Sakh 14:21; Fam 21:27","Amos 9:13; Hez 47:1","Amos 1:11"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 25, 'Ba tanö mado Yuda, ba si lö tebulöbulö niha, ba he Yeruzalema, irugi nga''ötö mitou sibai.', '["Yes 31:4; Yer 25:30; Faigi 11:10; Hag 2:6; Heb 12:26","Sakh 14:21; Fam 21:27","Amos 9:13; Hez 47:1","Amos 1:11"]', NULL),
  (3476457, 'OT', 'Yoeli', 3, 26, 'Ba ulau mbalö ndrora, si lö nilaugu na, ba i''iagö manö hili Ziona Yehowa!', '["Yes 31:4; Yer 25:30; Faigi 11:10; Hag 2:6; Heb 12:26","Sakh 14:21; Fam 21:27","Amos 9:13; Hez 47:1","Amos 1:11"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 1, 'Huhuo Gamosi da''e, Amosi kubalo andrö, banua Dekoa, huhuo ba Ndraono Gizeraeli, nifa''ele''ö khönia, me luo razo mado Yuda Usia andrö, ba me razo Ndraono Gizeraeli Yerobeamo, ono Yoasi, mendrua fakhe lö duru andrö.[1]', '["Faigi 7:14; Hos 1:1; Sakh 14:5","Yoel 3:21"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 2, 'Ba imane: Mundröndröndröndrö Yehowa, moroi ba Ziona, moroi ba Yeruzalema ifarongogö linia. Ba aleu dania mbenua gubalo andrö, ba mate ndru''u ba zuzu hili Garemeli.[2]', '["Faigi 7:14; Hos 1:1; Sakh 14:5","Yoel 3:21"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 3, 'Da''ö niŵa''ö Yehowa: Börö horö Ndramaseko andrö, si tölu balö, si öfa balö na, wa lö ufuli ligu — me no lafatörö ba mbanua Gileadi wamöbörö wakhe nifosi''öli.[3]', '["RazII 13:7","RazII 13:3","Yes 17:1; RazII 16:9"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 4, 'Andrö wa ocfatörö galitö ba mbanua Hazaeli, si manga gödo Mbenihada andrö.[4]', '["RazII 13:7","RazII 13:3","Yes 17:1; RazII 16:9"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 5, 'Lazi ba mbawa göli Ndramaseko, ba ufatö, ba ösi mbanua, ba uhori, ba ndraso horö andrö, ba solohe si''o zalaŵa, ba ubunu ba nomo wa''omasi andrö, ba soi Ndrawa Garamo andrö, ba ni''oloi''ö ba Giri, iŵa''ö Yehowa.[5]', '["RazII 13:7","RazII 13:3","Yes 17:1; RazII 16:9"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 6, 'Da''ö niŵa''ö Yehowa: Börö horö [Ndrawa Wilisiti] ba Gasa, si tölu balö andrö, si öfa balö na, wa lö ufuli ligu — me no samba-samba banua manö sa''ae la''oloi''ö, ba wame''e ba danga Ndraono Gedomo.[6]', '["Nga''ötII 21:16,17; 28:18; Yer 47:5"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 7, 'Andrö wa ufatörö galitö ba göli Gasa, alitö si manga gödo andrö khöra.', '["Nga''ötII 21:16,17; 28:18; Yer 47:5"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 8, 'Banua Gasoto, ba uhori, ba solohe si''o zalaŵa ba Gasikalo, ba ubunu, ba ufulido furi, ba Nekerona, ba tobali tekiko si tosai Dawa Wilisiti, iŵa''ö So''aya Yehowa.', '["Nga''ötII 21:16,17; 28:18; Yer 47:5"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 9, 'Da''ö niŵa''ö Yehowa: Börö horö [Ndrawa Wönikia] ba Diro, si tölu balö, si öfa balö na, wa lö ufuli ligu — me no samba-samba banua manö sa''ae la''oloi''ö, nibe''e ba danga Ndraono Gedomo, ba me no olifu ira wawu''usa li andrö ba zi fatalifusö.[7]', '["RazI 5:1"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 10, 'Andrö wa ufatörö galitö ba göli Diro andrö, alitö si manga gödo andrö khöra.', '["RazI 5:1"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 11, 'Da''ö niŵa''ö Yehowa: Börö horö Ndraono Gedomo andrö, si tölu balö, si öfa balö na, wa lö ufuli ligu — me no lagohi si''öli dalifusöra ba me no fadoro manö labunu wa''ahakhö dödöra, me no lö lafamalö-malö wönura, ba me lö latayaigö wa''abao dödöra.[8]', '["MozI 27:40","Yes 34:6; Obad a. 9"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 12, 'Andrö wa ufatörö galitö ba Demana, alitö si manga gödo ba Mbosera.[9]', '["MozI 27:40","Yes 34:6; Obad a. 9"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 13, 'Da''ö niŵa''ö Yehowa: Börö horö Ndraono Gamoni andrö, si tölu balö, si öfa balö na, wa lö ufuli ligu — me no lasiköi dalu zanabina, ba Gileadi, ba wangebolo tanöra.[10]', '["SamI 11:2; RazII 8:12"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 14, 'Andrö wa ufatörö galitö ba göli Raba andrö, alitö si manga gödora, ba fao we''ao-ao, na baŵa wasöndrata, ba angi sabölö, na baŵa we''ugu-ugu mbanua.', '["SamI 11:2; RazII 8:12"]', NULL),
  (3476458, 'OT', 'Amosi', 1, 15, 'Ba ni''oloi''ö Milikomo andrö, fabaya ere ba satua andrö khönia, iŵa''ö Yehowa.', '["SamI 11:2; RazII 8:12"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 1, 'Da''ö niŵa''ö Yehowa: Börö horö Ndraono Moabi andrö, si tolu balö, si öfa balö na, wa lö ufuli ligu — me no latunu döla razo Ndraono Gedomo, nifanunu betua.[1]', '["Yes 15:1","Yer 48:24"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 2, 'Andrö wa ufatörö galitö ba Ndraono Moabi, alitö si manga gödo ba Gerioto. Ba mate nisuwö Ndraono Moabi, ba fao we''ao-ao ba wanuwö, ba telau-lau dorofe.[2]', '["Yes 15:1","Yer 48:24"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 3, 'Ubunu zalaŵa, bakha ba hunöra, ba satuara fefu, ba ububunu awönia iŵa''ö Yehowa.', '["Yes 15:1","Yer 48:24"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 4, 'Da''ö niŵa''ö Yehowa: Börö horö mado Yuda andrö, si tölu balö, si öfa balö na, wa lö ufuli ligu — me no la''ositengagö goroisa Yehowa, ba me lö ni''o''öra amakhoitania; noa sa labe''e nifowöhö ira, wolo''ö faya andrö, ni''o''ö ndra tuara mege.', '[]', NULL),
  (3476459, 'OT', 'Amosi', 2, 5, 'Andrö wa ufatörö galitö ba mado Yuda, alitö si manga gödo ba Yeruzalema.', '[]', NULL),
  (3476459, 'OT', 'Amosi', 2, 6, 'Da''ö niŵa''ö Yehowa: Börö horö Ndraono Gizeraeli andrö, si tölu balö, si öfa balö na, wa lö ufuli ligu — me la''amawa ba gana''a zatulö tödö, ba si numana, ba ba zi safasa badagahe,', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 7, 'ya''ira andrö, sangisö tanö andrö ba högö zi numana, ba samila''ö lala ba zi no göna famakao; ha sambua ndra alawe sohoröhörö, ba faoma möi ira khönia, he ama, ba he ono, ba wango''aya töigu andrö, ni''amoni''ö.', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 8, 'Labe''e-be''e tufora nukha nihalö gade, ba zinga naha wame''e sumange fefu, ba labadu-badu nagu ogauta, ba gosali Lowalangira.[3]', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 9, 'Ba noa sa ya''odo zangohori mege Iraono Gamori, fönara, si no timba döla geresi fa''ebua ba si no timba döla manawa fa''abe''e. Ba no uhori mbua ba hogu ba he ŵa''a tou.[4]', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 10, 'No ya''odo zolohe ya''ami miyaŵa, moroi ba danö Miserayi ba samatörö ya''ami ba danö si mate andrö, öfa wulu fakhe wa''ara, ena''ö mi''okhogö danö Ndraono Gamori andrö![5]', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 11, 'Ba iraonomi, ba sama''ele''ö ösa, ba ono matua khömi, ba naziri ösa, ube''e. Hadia, tenga si manö, ya''ami, Iraono Gizeraeli? iŵa''ö Yehowa.[6]', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 12, 'Ba no mibe''e ö naziri andrö nagu, ba ba zama''ele''ö andrö, ba no mimane: Lö tola mama''ele''ö ami![7]', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 13, 'Ba hiza, ba ufera''ö ami, ba zi so sibai ami, si mane kureta famöbörö wakhe, famera döla wakhe si no fahöna ba golayama,', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 14, 'ena''ö tobali faya woloi zalio ahe, ba ena''ö tobali si lö boto wa''abe''e zabölö; ena''ö lö falukha wangorifi zabölö; ena''ö lö falukha wangorifi zabölö,', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 15, 'ba ena''ö lö manaha zi fafana, ena''ö lö möi fangorifi zalio ahe gahenia andrö, ba ena''ö lö auri göi zi fakudo.', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476459, 'OT', 'Amosi', 2, 16, 'Ba na so ba zabölö andrö zabe''e tödö, — ba moloi lö balu-balu, na luo da''ö dania, iŵa''ö Yehowa.', '["MozII 22:26","MozIV 21:24; Yos 24:8","MozII 12:51","MozIV 6:2","Yes 30:10; Yer 11:21; Faigi 7:13"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 1, 'Mifondrondrongo daroma li andre, taroma li Yehowa, fanegu ya''ami, Iraono Gizeraeli, fanegu sato fefu, ni''ohegu miyaŵa moroi ba danö Miserayi; imane:', '["Yes 45:7"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 2, 'Ba niha fefu ba guli danö, ba no ha ya''ami nituyugu; andrö wa u''otu''ö ami ba lalömi andrö fefu.', '["Yes 45:7"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 3, 'Hadia, so zi darua, si fao ba lala, na lö samagölö ira?', '["Yes 45:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476460, 'OT', 'Amosi', 3, 4, 'Hadia, mundröndrö-ndröndrö zingo ba gatua, na lö ahuluania? Hadia, ifarongogö linia ono zingo, ba naha wemörö khönia, na lö hadia ia nira''unia?', '["Yes 45:7"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 5, 'Hadia, alau wofo ba dandraŵa tou ba danö, na tenga khönia mege lalau dandraŵa andrö? Hadia, aefa dandraŵa ba danö tou, na lö hadia zalau?', '["Yes 45:7"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 6, 'Hadia, lalau göi dorofe yomo ba mbanua, si lö tokea niha sato? Hadia, itörö mbanua famakao hadia ia, na tenga khö Yehowa mbörö?[1]', '["Yes 45:7"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 7, 'Lö''ö! Lö ilau hadia ia Yehowa, na lö nibokainia ua tödönia, ba genoninia andrö, sama''ele''ö.', '["Yes 45:7"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 8, 'Na no mundröndröndröndrö zingo, ba ha niha zi lö ata''u? Ba na no muhede Zo''aya, Yehowa, ba ha niha zi lö mama''ele''ö?', '["Yes 45:7"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 9, 'Mifarongogö ba gödo ba Gasoto ba ba gödo ba danö Miserayi, ba mimane: Mi''owuloi ami ba hili andrö, si tefasui Samaria, ba mifaigi wagua-guasa sabölö-bölö andrö ba famalangögöra awöra!', '["Hos 5:14","MozII 27:2; RazI 12:32; RazII 23:15","Yer 36:22; RazI 22:39"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 10, 'Lö''ö sa la''ila wolau satulö, iŵa''ö Yehowa, ya''ira andrö, sangöhöna horö ba famakao awöra, ba gödora andrö.', '["Hos 5:14","MozII 27:2; RazI 12:32; RazII 23:15","Yer 36:22; RazI 22:39"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 11, 'Andrö wa imane So''aya, Yehowa: Lasasagö dania danö emali, fasui manö, ba ladudugö mba''a-ba''a andrö khömi, ba nirabu dania gama-gama ba gödomi.', '["Hos 5:14","MozII 27:2; RazI 12:32; RazII 23:15","Yer 36:22; RazI 22:39"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 12, 'Da''ö niŵa''ö Yehowa: Si mane na ifadöni ba mbawa zingo kabalo zi dua rozi faha mbiri-biri, ba ma si sambua mburumburu, si manö dania wangorifi Iraono Gizeraeli andrö, sidadao ba Zamaria ba watalinga warate ba ba gaso Ndramaseko.[2]', '["Hos 5:14","MozII 27:2; RazI 12:32; RazII 23:15","Yer 36:22; RazI 22:39"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 13, 'Mifondrondrongo ba mifaduhu''ö ba ma''uwu, iŵa''ö So''aya Yehowa,', '["Hos 5:14","MozII 27:2; RazI 12:32; RazII 23:15","Yer 36:22; RazI 22:39"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 14, 'Lowalangi ngahönö: Si ndruhu, na u''otu''ö Ndraono Gizeraeli ba horöra, ba ulau ba naha wame''e sumange andrö, ba Mbetieli, ena''ö ni''eŵa dandru ba naha wame''e sumange, ena''ö atoru tou ba danö.[3]', '["Hos 5:14","MozII 27:2; RazI 12:32; RazII 23:15","Yer 36:22; RazI 22:39"]', NULL),
  (3476460, 'OT', 'Amosi', 3, 15, 'Ba he omo, na baŵa deu, ba he omo, na baŵa lökhö, ba ududugö. Ba nifufu göi nomo ifö guaza; oya manö zi taya dania omo, iŵa''ö Yehowa.[4]', '["Hos 5:14","MozII 27:2; RazI 12:32; RazII 23:15","Yer 36:22; RazI 22:39"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 1, 'Mifondrondrongo ligu andre, ya''ami saŵi Mbazana ba hili Zamaria, ya''ami samakao side-ide ba samufu si numana ba sanguma''ö khö zokhö ya''ira: Faigi khönia nibaduma![1]', '["RazI 16:24; Yes 56:11,12"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 2, 'No fahölu Zo''aya, Yehowa, ba wa''asalaŵania andrö, no imane: Hiza, irugi baŵa dania khömi, nidöni yaŵa ami ba khai-khai, ba nga''ötömi, ba ba gai gi''a.', '["RazI 16:24; Yes 56:11,12"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 3, 'Ba mitörö zatöla göli, we''amöi baero mbanua, idölö ia zamösana, ba tetibo ami ba Haramono.', '["RazI 16:24; Yes 56:11,12"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 4, 'Mi''ae ba Mbetieli ba misao''ö horö, ba ba Giligala, ba mi''oya''ö wanao horö. Mibe''e zumange nitaba andrö khömi, na mahemolu mbanua, ba ba zi dua wongi, ba mibe''e zi sambua ni''ofulu andrö khömi.[2]', '["Hos 4:15; 12:12","MozV 28:22; RazI 8:37; Yoel 1:4; 2:25; Hag 2:17","MozI 19:24; Sakh 3:2; Yud 23"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 5, 'Mitunu manö roti ni''aisöni, sumange fangandrö saoha gölö, ba mi''ao ba niha sato, ena''ö labe''e game''ela saoha gölö! Da''ö sa atö zomasi ami, ya''ami Iraono Gizeraeli! iŵa''ö Soaya, Yehowa.', '["Hos 4:15; 12:12","MozV 28:22; RazI 8:37; Yoel 1:4; 2:25; Hag 2:17","MozI 19:24; Sakh 3:2; Yud 23"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 6, 'Ba he ŵa''ae lö halöŵö mbohami ube''e ba mbanuami fefu, ba he ŵa''ae ambö balazo ba nahiami fefu, ube''e, ba lö''ö zui nifalalinimi era-erami, wamuli ya''ami khögu, iŵa''ö Yehowa.', '["Hos 4:15; 12:12","MozV 28:22; RazI 8:37; Yoel 1:4; 2:25; Hag 2:17","MozI 19:24; Sakh 3:2; Yud 23"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 7, 'Ba he ŵa''ae lö ube''e khömi deu mege, me tölu waŵa lö famasi na; tenga ha samuza, ba ba mbanua si sambua aekhu ba danö deu, ba ba zi sambua, ba lö''ö — nowi si sagörö, ba no si göna teu, ba ba zi sagörö, ba mate zinanö, me lö si göna ia —', '["Hos 4:15; 12:12","MozV 28:22; RazI 8:37; Yoel 1:4; 2:25; Hag 2:17","MozI 19:24; Sakh 3:2; Yud 23"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 8, 'ba he ŵa''ae tenga ha samuza, ba dombua banua, tölu banua na, zondröni ya''ira ba mbanua si sambua, ba wamadu idanö, si lö''ö sa atö döhö fa''owökhi dödö, ba lö''ö zui nifalalinimi era-erami, wamuli ya''ami khögu, iŵa''ö Yehowa.', '["Hos 4:15; 12:12","MozV 28:22; RazI 8:37; Yoel 1:4; 2:25; Hag 2:17","MozI 19:24; Sakh 3:2; Yud 23"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 9, 'No u''otu''ö ami fa''akhozi ngalai wakhe ba fa''ongaö; ba tamo zi manga zinanö ba kabumi soya andrö ba ba kabu nagu, ba he ara khömi ba he zai, ba la''a. Ba lö''ö zui nifalalinimi era-erami, wamuli ya''ami khögu, iŵa''ö Yehowa.[3]', '["Hos 4:15; 12:12","MozV 28:22; RazI 8:37; Yoel 1:4; 2:25; Hag 2:17","MozI 19:24; Sakh 3:2; Yud 23"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 10, 'Ba no ufatörö khömi wökhö waba, si mane ba Ndrawa Miserayi no; no ubunu si''öli zabölömi, lö lai wa no lahalö göi kudomi, ba no ufa''amöi miyaŵa ba nikhumi wa''aböu golombaseŵami andrö. Ba lö''ö zui nifalalinimi era-erami, ba wamuli ya''ami khögu mena''ö.', '["Hos 4:15; 12:12","MozV 28:22; RazI 8:37; Yoel 1:4; 2:25; Hag 2:17","MozI 19:24; Sakh 3:2; Yud 23"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 11, 'Ba no ubali''ö ami, si mane me ibali''ö Zodoma ba Gomora Lowalangi, ba tobali timba ndrundrunga nisöbi ba galitö ami. Ba lö''ö zui nifalalinimi era-erami, ba wamuli ya''ami khögu mena''ö.[4]', '["Hos 4:15; 12:12","MozV 28:22; RazI 8:37; Yoel 1:4; 2:25; Hag 2:17","MozI 19:24; Sakh 3:2; Yud 23"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 12, 'Andrö wa ulau khömi da''ö, ya''ami Iraono Gizeraeli: — ba me umanö dania khömi, ba mifa''anö ami, ya''ami Iraono Gizeraeli, ba wangondrasi Lowalangimi!', '["Faigi 5:8"]', NULL),
  (3476461, 'OT', 'Amosi', 4, 13, 'Hiza sa, so zamösa, samazökhi hili mege ba somböi angi, sama''ele''ö ba niha hadia ba dödönia, samali''ö sogömi-gömi fa''amoluo, ba sanawö hili ba guli danö, — Yehowa, Lowalangi ngahönö döinia.[5]', '["Faigi 5:8"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 1, 'Mifondrondrongo ligu andre, fange''esigu ya''ami, ya''ami Iraono Gizeraeli!', '["MozV 28:62; Yes 6:13"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 2, 'No alau nono alawe andrö soi Ndraono Gizeraeli, ba tebai maoso sa''ae. No mutuli''ö tou ia ba danöra tou, ba lö samazaŵa ya''ia!', '["MozV 28:62; Yes 6:13"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 3, 'Da''ö sa niŵa''ö Zo''aya, Yehowa: Ba mbanua andrö, si hönö sabölö, ba hato otu zi tosai dania, ba ba zi otu sabölö mege, ba hato fulu zi tosai dania, ba mbanua Ndraono Gizeraeli.[1]', '["MozV 28:62; Yes 6:13"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 4, 'Da''ö sa niŵa''ö Yehowa ba mbanua Ndraono Gizeraeli andrö: Misofu ndra''odo, ena''ö auri ami!', '["Faigi 4:4","Yob 9:9; MozI 7:10"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 5, 'Ba böi mi''alui Mbetieli andrö! Böi mi''ae ba Giligala ba böi misaŵa Mbereseba! Giligala andrö sa, ba ni''oloi''ö dania, ba Betieli, ba nifufu.[2]', '["Faigi 4:4","Yob 9:9; MozI 7:10"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 6, 'Mi''alui Yehowa, ena''ö auri ami! Fa böi ihawui mado Yosefo, timba galitö, si manga-manga hadia ia, si lö samunu, ba Mbetieli; ya''ia andrö,', '["Faigi 4:4","Yob 9:9; MozI 7:10"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 7, 'somböi "zara" andrö ba "si tölu" (döfi) samali''ö fa''amoluo si bongi, sogömi-gömi sibai, ba samali''ö si bongi si moluo; si no humede ba nasi mege, ena''ö inönöi guli danö: Yehowa döinia!', '["Faigi 4:4","Yob 9:9; MozI 7:10"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 8, 'Sangasogö famakiko zabölö, si lö mudöna-döna, ba he fa''adudu mbanua saro.', '["Faigi 4:4","Yob 9:9; MozI 7:10"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 9, 'Ya''ira andrö, samali''ö safeto sibai huku satulö, ba samila''ö lala.[3]', '["Faigi 4:4","Yob 9:9; MozI 7:10"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 10, 'Si fatiu tödö ira ba zolohe ba lala huhuo, ba kato, ba la''ogorofi zolau si duhu.', '["Sef 1:13; Hag 1:6","Efes 5:16"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 11, 'Me no sanguhundragö si numana ami, ba me mitema khöra mbuala, bua nowi, ba alakha milau nomo kara nitoto, ba lö tola mi''onahia; ba alakha mifazökhi kabu nagu omasiö, ba lö tola mibadu nösi mbua.[4]', '["Sef 1:13; Hag 1:6","Efes 5:16"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 12, 'Noa sa aboto ba dödögu: no fahöna golalöŵami ba no oya sibai horömi! Mifakao zi lö horö ba manga gana''a ami ba mifalangögö zi numana, ba kato.', '["Sef 1:13; Hag 1:6","Efes 5:16"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 13, 'Andrö wa lö hede-hede zatua-tua, ba götö da''e, me no götö si lö sökhi.[5]', '["Sef 1:13; Hag 1:6","Efes 5:16"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 14, 'Mi''alui zi sokhi, ba böi si lö sökhi, ena''ö auri ami! Awena dania itolo ami Yehowa Lowalangi ngahönö, si mane niŵa''ömi.', '["Sin 34:15; Yes 1:16"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 15, 'Mi''ogorofi zi lö sökhi ba mi''omasi''ö zi sökhi; böi mifuyu''ö huku, ba kato! Ma atö ihakhösi tödö zi tosai mado Yosefo Yehowa, Lowalangi ngahönö![6]', '["Sin 34:15; Yes 1:16"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 16, 'Andrö wa imane Yehowa, Lowalangi ngahönö, So''aya: Dozi olayama dania, ba fege-ege, lamane ba newali fefu: Alai ndra''o! alai ndra''o! Sangahalö ba danö, ba humede dania ba zi no to''ölö ba wege-ege ba wa''abu dödö ba ba wange''esi,', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 17, 'ba dozi kabu nagu misa, ba fege-ege dania, na utörö ami, iŵa''ö Yehowa.', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 18, 'Alai zomasi na alio irugi baŵa andrö khö Yehowa! Hadia guna mbaŵa andrö khö Yehowa khömi? Fa''ogömi-gömi dania ia, ba tenga haga![7]', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 19, 'Hulö zi falukha berua, na no moloi ia ba zingo, ba nidou ulö, na no irugi yomo, ba na itufa tangania dowa.[8]', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 20, 'Hiza, fa''ogömi-gömi dania mbaŵa andrö, khö Yehowa, ba tenga haga; sogömi-gömi, ba tenga sihaga!', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 21, 'Anuzu dödögu gowasami andrö, lö ba dödögu, tebai u''ago gowuloami.[9]', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 22, 'Na mibe''e khögu zumange nitunu ba ame''elami andrö, ba no tenga somasido; ba sumange fangandrö saoha gölö, ono zaŵi nibula andrö khömi, ba lö''ö na''i ufaigi.', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 23, 'Aröu''ö khögu wakoresa andrö, fanunömö; li mbiola andrö khöu, ba lö omasido urongo!', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 24, 'Ba ena''ö na mangumbu-ngumbu zatulö lala, timba nidanö; ba huku satulö, ba ena''ö na timba mbombo, si tebai ogo''ö!', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 25, 'Hadia, no mibe''e khögu zumange nitaba ba ame''ela, ba danö si mate no, si öfa wulu fakhe wa''ara; ya''ami Iraono Gizeraeli?[10]', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 26, 'Ba mi''osa''ö Zikuti andrö, razomi, ba Kewana andrö, Lowalangimi, famaedo andrö khömi, nifazökhimi![11]', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476462, 'OT', 'Amosi', 5, 27, 'Ba ube''e ni''oloi''ö ami, amaedola nitibo''ö, irugi ba zi tambai Ndramaseko, iŵa''ö Yehowa — Lowalangi ngahönö döinia.[12]', '["Yer 17:15; 30:7; Yes 13:6","Yes 24:18","Yes 1:11","HalZin 7:42,43; Hez 20:16 b.t.","RazI 11:7; Sef 1:5","RazII 17:6"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 1, 'Alai zi lö mangabusi tödö hadia ia ba hili Ziona, ba si no ahono-hono manö ba hili Zamaria, si no sebua töi ba zi a''a soi andrö, ba ni''ondra''ondrasi ma''uwu Gizeraeli![1]', '["Luk 6:24","Yes 10:9; Nga''ötII 26:6","Hez 12:27; Faigi 9:10","Yes 5:12; Nga''ötI 23:5"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 2, 'Mi''ae ba Galene, ba mifakhölö ami ba mi''otarai da''ö, ba mirugi Hamata sebua, ba mi''ae mitou ba Gata, ba danö Ndrawa Wilisiti: Hadia, si sökhi ami, moroi ba mbanua da''ö, ba hadia, ebua danömi, moroi ba danöra?[2]', '["Luk 6:24","Yes 10:9; Nga''ötII 26:6","Hez 12:27; Faigi 9:10","Yes 5:12; Nga''ötI 23:5"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 3, 'Ya''ami, sanguma''ö tödöra, aröu na sa mbaŵa si lö sökhi, ba sangahatö''ö dadaoma horö.[3]', '["Luk 6:24","Yes 10:9; Nga''ötII 26:6","Hez 12:27; Faigi 9:10","Yes 5:12; Nga''ötI 23:5"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 4, 'No farate ifö guaza waratera, ba lafadölö ira ba gasora; ono mbiri-biri satabö göra, ono mbiri-biri nikubaloi, ba ono zaŵi moroi ba kandra.', '["Luk 6:24","Yes 10:9; Nga''ötII 26:6","Hez 12:27; Faigi 9:10","Yes 5:12; Nga''ötI 23:5"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 5, 'Si fakore ira, na telau mbiola nitika, ba lawai nifolau Dawido wolaura biola.[4]', '["Luk 6:24","Yes 10:9; Nga''ötII 26:6","Hez 12:27; Faigi 9:10","Yes 5:12; Nga''ötI 23:5"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 6, 'Mako zumange la''amadugö wamadu agu, ba labayoini ira fondrege zi sökhi wanikha, ba fökhö ma''uwu Yosefo andrö, ba lö la''abusi tödö!', '["Luk 6:24","Yes 10:9; Nga''ötII 26:6","Hez 12:27; Faigi 9:10","Yes 5:12; Nga''ötI 23:5"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 7, 'Andrö wa si a''a ni''oloi''ö sa''ae ira, ba tebato wa''iki zi no mamadölö ya''ira ba zalo.', '["Luk 6:24","Yes 10:9; Nga''ötII 26:6","Hez 12:27; Faigi 9:10","Yes 5:12; Nga''ötI 23:5"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 8, 'No fahölu Zo''aya, Yehowa, iŵa''ö Yehowa, Lowalangi ngahönö, [imane]: Ogoro ndra''odo wayaŵasa ma''uwu Yakobo, anuzu, dödögu hatira andrö, ba ululu mbanua andrö, fabaya ösinia.', '["Hez 24:15 b.t.","Faigi 5:7","RazI 22:11","Yes 7:17; Nga''ötII 7:8"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 9, 'Ba na dafulu dania zi tosai niha ba nomo heza, ba ahori mate ira.', '["Hez 24:15 b.t.","Faigi 5:7","RazI 22:11","Yes 7:17; Nga''ötII 7:8"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 10, 'Ba na ihalö dania ira sahatö khöra, sogo''ö ya''ira, ba wangeheta yomo, ba na imane khö zi so si bakha ba mbate''e side-ide: Hadia, so na nawöu? ba na imane da''ö: Lö''ö, ba imane: Böi hede-hede! Lö töla sa latötöi döi Yehowa.', '["Hez 24:15 b.t.","Faigi 5:7","RazI 22:11","Yes 7:17; Nga''ötII 7:8"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 11, 'Hiza sa, ibe''e goroisa Yehowa, ba idudugö nomo sebua ba irasa zide-ide.[5]', '["Hez 24:15 b.t.","Faigi 5:7","RazI 22:11","Yes 7:17; Nga''ötII 7:8"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 12, 'Hadia, latörö dete gara kudo, ba hadia, ta''ila tabe''e sanguhundra asi zaŵi? Me no mibali''ö langu huku, ba me no mibali''ö safeto sibai mbua-bua wa''atulö.[6]', '["Hez 24:15 b.t.","Faigi 5:7","RazI 22:11","Yes 7:17; Nga''ötII 7:8"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 13, 'Omuso dödömi zi lö boto, mimane dödömi: Moroi ba wa''abe''eda, wa no sabölö ita![7]', '["Hez 24:15 b.t.","Faigi 5:7","RazI 22:11","Yes 7:17; Nga''ötII 7:8"]', NULL),
  (3476463, 'OT', 'Amosi', 6, 14, 'Ba hiza, ya''ami Iraono Gizeraeli — iŵa''ö Yehowa, Lowalangi ngahönö — u''asogö sa''ae khömi soi samakao ya''ami, i''otarai ba lala ba Hamata, irugi mbombo andrö ba danö si mate.[8]', '["Hez 24:15 b.t.","Faigi 5:7","RazI 22:11","Yes 7:17; Nga''ötII 7:8"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 1, 'Da''e nifa''ele''ö Zo''aya Yehowa khögu: So nono damo, me ibörötaigö auri zinanö ba nowi sebolo, ba so zarakha mo''ahonoa fa''ebua, me no aefa ifaguti''ö mbua mbiri-biri khönia razo.[1]', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 2, 'Ba me no ahori la''a mbulu ndru''u ba danö, ba mangandrö ndra''o, umane: He So''aya, Yehowa, be''e aefa horö! Heza lasöndra wangorifi ma''uwu Yakobo? No si numana sibai ira!', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 3, 'Ba mangesa dödö Yehowa. Böi! iŵa''ö Yehowa.[2]', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 4, 'Ba da''e [zui] nifa''ele''ö Zo''aya Yehowa khögu: Iŵa''ö wanuwö galitö So''aya, Yehowa. Ba i''a nasi sebua alitö; ba me i''a ena''ö dana khö Yehowa,', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 5, 'ba mangandrö ndra''o, umane: He So''aya, Yehowa, böda! Heza lasöndra wangorifi ma''uwu Yakobo? No si numana sibai ira!', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 6, 'Ba mangesa dödö Yehowa. Böi! iŵa''ö Yehowa.', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 7, 'Ba da''e [zui] nifa''ele''ö Zo''aya, Yehowa, khögu: No so ba dete göli kara, sadölö fesindro, Zo''aya, ba no so ba dangania zimo (fanimba, na adölö)[3]', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 8, 'Ba imane khögu Yehowa: Hadia ni''ilamö, Amosi? Ba umane: Simo. Ba imane So''aya: Hiza, ulau zimo ba hunö mbanuagu Iraono Gizeraeli; lö''ö sa''ae ufuli ube''e aefa horöra![4]', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 9, 'Nidudugö ine hili-hili andrö ba ma''uwu Giza''aki, ba nifufu ni''amoni''ö andrö ba ma''uwu Gizeraeli; ba ba zi samba omo ndra Yerobeamo, ba utema ulau zi''öli![5]', '["RazII 15:17","Yer 18:8","Yes 34:11","RazII 21:13","Yer 17:2"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 10, 'Ba ifatenge zinenge Amasia, ere ba Mbetieli, khö Yerobeamo, razo Ndraono Gizeraeli, imane: Amosi andrö, ba ifawe''e ma''uwu Gizeraeli, ba wolaŵa ya''ugö; tebai itaha tanö huhuonia andrö fefu![6]', '["RazII 14:23","Yes 30:10; Faigi 2:12"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 11, 'Da''ö sa niŵa''ö Gamosi: Ba mbawa zi''öli mate Yerobeamo, ba Iraono Gizeraeli, ba lö zi lö mu''oloi''ö dania, aheta ira ba danöra.', '["RazII 14:23","Yes 30:10; Faigi 2:12"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 12, 'Ba imane Amasia khö Gamosi: He sangi''ila, faoso! oloi, saŵa danö mado Yuda! Ba da''ö alui göu, ba ba da''ö möi''ö sama''ele''ö!', '["RazII 14:23","Yes 30:10; Faigi 2:12"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 13, 'Ba ba Mbetieli, ba lö tola sa''ae möi''ö sama''ele''ö! me no ni''amöni''ö khö razo da''e, osali zato fefu khö razo.[7]', '["RazII 14:23","Yes 30:10; Faigi 2:12"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 14, 'Ba itema li Gamasia Amosi, imane: Tenga sama''ele''ö ndra''odo ba tenga göi ono zekola zama''ele''ö, kubalo zaŵi ndra''odo a''ine, ba si so kabu ara.[8]', '["Faigi 1:1","Hez 21:2","Hos 4:13"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 15, 'Ba no ihalö ndra''odo Yehowa, no ihetado kubalo, ba no imane khögu Yehowa: Ae''e, ba iagö sama''ele''ö ba mbanuagu Iraono Gizeraeli.[9]', '["Faigi 1:1","Hez 21:2","Hos 4:13"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 16, 'Ba fondrondrongo sa''ae li Yehowa: Ya''ugö, ba ömane: Lö tola ö''iagö sama''ele''ö ba Ndraono Gizeraeli, ba lö tola ölau huhuo ba ma''uwu Giza''aki!', '["Faigi 1:1","Hez 21:2","Hos 4:13"]', NULL),
  (3476464, 'OT', 'Amosi', 7, 17, 'Andrö wa imane Yehowa: Fo''omou, ba si tobali sohorö, ba mbanua, ba onou matua ba onou alawe, ba si mate ba mbawa zi''öli. Tanöu, ba lasu''a sinali, wamaosa ya''ia, ba ya''ugö, ba ba danö si ra''i-ra''iö mate''ö. Ba Iraono Gizeraeli, ba lö zi lö mu''oloi''ö dania, aheta ira ba danöra.[10]', '["Faigi 1:1","Hez 21:2","Hos 4:13"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 1, 'Da''e nifa''ele''ö Zo''aya Yehowa khögu: Hiza ndraga so''ösi bua geu sasoso.', '["Faigi 7:8","Hos 12:8"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 2, 'Ba isofu khögu, imane: Hadia ni''ilau Amosi? Ba umane: Daga so''ösi bua geu sasoso! Ba imane khögu Yehowa: Irugi dania baŵa wangozaragö bua geu ba mbanuagu Iraono Gizeraeli andrö; ba lö''ö sa''ae ufuli ube''e aefa horöra![1]', '["Faigi 7:8","Hos 12:8"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 3, 'Ba sege-ege dania zanunö, ira alawe andrö, ba gödo misa, na luo da''ö, iŵa''ö So''aya, Yehowa. Fahöna mboto zi mate! Lafazawili manölö hede-hede!', '["Faigi 7:8","Hos 12:8"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 4, 'Mifondrondrongo da''e, ya''ami solohi si numana ba samakiko sebua famakao ba danö, wanguma''ö tödömi:', '["Faigi 7:8","Hos 12:8"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 5, 'Ha wa''ara aefa wasulöna, ena''ö tola ta''amawa mbua nowi, ba ha wa''ara aefa luo sabato, ena''ö tola tabokai naha wakhe, ba ena''ö ta''ide-ide''ö lauru, ba ena''ö ta''ebua''ö zaga ba tafaigi waliera falimosa, ba wolimo niha,[2]', '["Faigi 7:8","Hos 12:8"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 6, 'ba ena''ö ta''öli niha side-ide; tabe''e gana''a, ba si safasa badagahe tabe''e böli zi numana, ba ena''ö ta''amawa göi damböni.', '["Faigi 7:8","Hos 12:8"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 7, 'No fahölu Yehowa, ba wangebua döi ma''uwu Yakobo andrö, no imane: Si ndruhu, lö''ö manö olifudo zambalö, nilaura andrö![3]', '["Faigi 6:8","Yer 15:9","Yer 6:26; 48:37; Hez 7:18; Sakh 12:10","Hos 2:3","RazI 12:29"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 8, 'Hadia, lö muheu danö ba zi mane da''ö, ba hadia, lö abu dödö dozi sonahia ba detenia? hadia, lö manöi ena''ö danö ma''asagörö, si mane Nilo, ba ifuli alö, si mane Nilo ba danö Miserayi?', '["Faigi 6:8","Yer 15:9","Yer 6:26; 48:37; Hez 7:18; Sakh 12:10","Hos 2:3","RazI 12:29"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 9, 'Ba na luo da''ö — iŵa''ö So''aya, Yehowa — ba na laluo aekhu luo ube''e, ba ba zi ma''ökhö ufatörö wa''ogömi-gömi, ba guli danö.[4]', '["Faigi 6:8","Yer 15:9","Yer 6:26; 48:37; Hez 7:18; Sakh 12:10","Hos 2:3","RazI 12:29"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 10, 'Owasami, ba ubali''ö fa''abu dödö, ba fanunömi fefu, ba ubali''ö fange''esi; dozi löwi-löwi, ba molembe lembe ba wa''abu dödö, ba dozi högö, ba nitöwö ube''e. Tobali amaedola wange''esi ono matua si ha sambu-sambua, ube''e, ba amozuania, ba si mane baŵa safökhö sibai.[5]', '["Faigi 6:8","Yer 15:9","Yer 6:26; 48:37; Hez 7:18; Sakh 12:10","Hos 2:3","RazI 12:29"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 11, 'Hiza, irugi baŵa dania — iŵa''ö So''aya Yehowa — ba ufatörö ba danö lofo mbanua, tenga fa''olofo ba gö, ba tenga fa''owökhi dödö ba nidanö, fa''olofo ba wamondrongo li Yehowa a''ine, ba tobali lafangörö ira,', '["Faigi 6:8","Yer 15:9","Yer 6:26; 48:37; Hez 7:18; Sakh 12:10","Hos 2:3","RazI 12:29"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 12, 'i''otarai nasi si sambua, numalö ba zi sambua, ba latöröi danö, i''otarai moroi yöu, numalö ba gatumbukha luo, ba wangalui taroma li Yehowa; ba lö lasöndra!', '["Faigi 6:8","Yer 15:9","Yer 6:26; 48:37; Hez 7:18; Sakh 12:10","Hos 2:3","RazI 12:29"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 13, 'Ba na luo da''ö, ba ono matelö nono alawe si sökhi bawa ba ira matua sabölö, ba wa''owökhi dödö![6]', '["Faigi 6:8","Yer 15:9","Yer 6:26; 48:37; Hez 7:18; Sakh 12:10","Hos 2:3","RazI 12:29"]', NULL),
  (3476465, 'OT', 'Amosi', 8, 14, 'Ya''ira andrö, same''e hölu olalöŵa Zamaria andrö, wanguma''ö: "Ba wa''aduhu wa''auri Lowalangimi andrö, ya''ami — banua Dano!" ba: "Ba wa''aduhu wa''auri Lowalangimi andrö, ya''ami — banua Mbereseba!" — tegaölö tou ira, ba lö lafuli maoso.[7]', '["Faigi 6:8","Yer 15:9","Yer 6:26; 48:37; Hez 7:18; Sakh 12:10","Hos 2:3","RazI 12:29"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 1, 'Ba u''ila Zo''aya, si iagö ngai naha wame''e sumange, ba imane: Bözi högö [daru nahe] andrö, ena''ö muhisi mbuatö, rasa, [ekhugö] ba högöra, fefu! Nga''ötöra, ba ububunu si''öli, samösa böi moloi, samösa böi i''orifi ia.[1]', '["Yes 6:4; Faigi 2:14","Sin 139:8; Yer 23:24; Heb 4:13","Yer 44:11","Sin 97:5; Faigi 8:8","Sin 104:3; Faigi 5:8"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 2, 'Ba he banua tou lasaŵa, ba ihalö ira ba da''ö tangagu, ba he miyaŵa ba mbanua si yaŵa möi ira, ba utuli''ö si tou ira moroi ba da''ö.[2]', '["Yes 6:4; Faigi 2:14","Sin 139:8; Yer 23:24; Heb 4:13","Yer 44:11","Sin 97:5; Faigi 8:8","Sin 104:3; Faigi 5:8"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 3, 'Ba na labini''ö ira ba zuzu hili Garemeli, ba u''alui ira ba da''ö, ba uhalö ira. Ba he si tou ba doyo nasi labini''ö ira, fa böi u''ila ira, ba ufatörö gulö ba da''ö, sondrou ya''ira.', '["Yes 6:4; Faigi 2:14","Sin 139:8; Yer 23:24; Heb 4:13","Yer 44:11","Sin 97:5; Faigi 8:8","Sin 104:3; Faigi 5:8"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476466, 'OT', 'Amosi', 9, 4, 'Ba na möi ni''oloi''ö ira, emalira moroi furi, ba uŵa''ö zi''öli ba da''ö, famunura; ba unehegö ira ba zi lö sökhi, ba tenga ba zi sökhi![3]', '["Yes 6:4; Faigi 2:14","Sin 139:8; Yer 23:24; Heb 4:13","Yer 44:11","Sin 97:5; Faigi 8:8","Sin 104:3; Faigi 5:8"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 5, 'Ba ya''ia So''aya, Yehowa ngahönö, na ibaya danö, ba alau, ba abu dödö dozi sonahia ba detenia, ba manöi danö ma''asagörö, si mane Nilo, ba ifuli alö, si mane Nilo ba danö Miserayi.[4]', '["Yes 6:4; Faigi 2:14","Sin 139:8; Yer 23:24; Heb 4:13","Yer 44:11","Sin 97:5; Faigi 8:8","Sin 104:3; Faigi 5:8"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 6, 'Ba mbanua si yaŵa ilau mbate''e khönia, ba ba guli danö itaru''ö nöu khönia, no humede ia ba nasi ba no ifaduwa ba guli danö misa — Yehowa döinia.[5]', '["Yes 6:4; Faigi 2:14","Sin 139:8; Yer 23:24; Heb 4:13","Yer 44:11","Sin 97:5; Faigi 8:8","Sin 104:3; Faigi 5:8"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 7, 'Hadia, tenga si mane Dawa Gaitiofia ami khögu, ya''ami Iraono Gizeraeli? iŵa''ö Yehowa. Hadia, lö ni''ohegu miyaŵa Iraono Gizeraeli moroi ba danö Miserayi, ba Dawa Wilisiti moroi ba Gafora, ba Dawa Garamo moroi ba Giri?[6]', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 8, 'Ba hiza, ba inehegö mbanua sebua horö andrö So''aya, Yehowa; ba uhori ba guli danö. Ba lö''ö sa ufalua sibai wangohori ma''uwu Yakobo andrö, iŵa''ö Yehowa.[7]', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 9, 'Hiza sa, ube''e li dania, ena''ö lasikhi ma''uwu Yakobo, ba niha baero fefu, timba na lasikhi damböni ba data, ba sambua ngawua lö aekhu ba danö.', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 10, 'Ba mbaŵa zi''öli mate dozi si so horö ba mbanuagu, sanguma''ö tödöra: "Lö ikhamö ita famakiko, lö ihawui ita!"[8]', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 11, 'Ba na luo da''ö, ba ufuli utaru''ö nose Dawido andrö, si no adudu, ba ufuli u''a''azökhi zadudunia; adudulania, ba ufuli ufasindro, ba ufuli u''otomosi, si mane ba götö föna.[9]', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 12, 'Ena''ö labe''e barö mbawara zi tosai Iraono Gedomo, ba soi bö''ö fefu, ba nitötöi töigu mege — iŵa''ö Yehowa, solau da''ö dania.', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 13, 'Ba irugi baŵa dania, iŵa''ö Yehowa, ba ikhamö zamasi samaku, ba ikhamö zolazi bua nagu sanaru; ba mowöi ösi nagu hili misa, ba mangulu hili-hili fefu.[10]', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 14, 'Ba ufuli u''azökhi mbanuagu Iraono Gizeraeli, ba tobali na lafuli lataru''ö mbanua si no adudu, ba la''onahia göi, ba na lafazökhi kabu nagu, ba labadu göi nösi mbua, ba na latanö geu sowua, ba la''a göi mbuania.', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476466, 'OT', 'Amosi', 9, 15, 'Ba amaedola utanö ira ba danöra, fa böi sa''ae adeha ira ba danöra andrö, nibe''egu khöra, iŵa''ö Yehowa, Lowalangiu.[11]', '["Yer 47:4; Faigi 1:5","Yer 5:18; 30:11","Faigi 6:3","HalZin 15:16","Yoel 3:18","Yer 32:41"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 1, 'Fama''ele''ö khö Gobadia. Da''ö niŵa''ö Zo''aya, Yehowa, ba khö Ndraono Gedomo andrö: No marongo duria khö Yehowa, ba no mufatenge zinenge ba niha baero, [no imane]: Talabu, möi ita manuwö ya''ira![1]', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 2, 'Hiza, uhöndrögö tou ndra''ugö, ba ngai soi bö''ö, ni''ositengagö manö ndra''ugö dania.', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 3, 'No ifowöhö ndra''ugö tödöu si fayaŵa andrö, no amaedola zi so omo ba dete gara ba hili ndra''ugö, ba dadaoma si no alaŵa yaŵa, no ömane dödöu: "Ha niha zanuli''ö tou ya''odo!"', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 4, 'Ba he no ba zalaŵa yaŵa öbe''e gazunimö, si mane moyo, he ba ngai ndröfi si yaŵa öbe''e, ba utuli''ö tou ndra''ugö moroi ba da''ö, iŵa''ö Yehowa.', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 5, 'Na möi yomo khöu zanagö, si farabu ba zi bongi — ba no nifakao sibai ndra''ugö — ba ha ndrohu-ndrohu zomasi ira sa atö la''oloi''ö. Ba na möi ba kabumö zaneteu bua nagu, ba hadia, lö lasaigö wo''uwo''u?', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 6, 'Ba no mubu''ai sibai nomo ma''uwu Gezau, irugi wondrege mbini-mbini!', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 7, 'Latimba ami dozi si fa''awö khömi mege, lö lafa''amöi ba danöra ami; lalimo ami si no fahuwu khömi mege, lahöndrögö ami; si no manga gömi mege, ba lalau dandraŵa khömi, si lö oroma.', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 8, 'Hiza, na luo da''ö — iŵa''ö Yehowa — ba uhori zatua-tua ba Ndraono Gedomo, awö wa''aboto ba dödö ba hili ma''uwu Gezau.[2]', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 9, 'Satalö tödö dania zabölö andrö khömi, ya''ami, banua Dema, ena''ö samösa lö tosai dania niha ba hili ma''uwu Gezau, ena''ö ahori, ba wasöndrata andrö.[3]', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 10, 'Si tehawu fa''aila dania ndra''ugö, börö horöu andrö khö nakhiu Yakobo, ba nihori ndra''ugö, si lö fulitö.[4]', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 11, 'Me luo möi''ö udunia, me luo la''oloi''ö gana''ania niha bö''ö, me atu''a ba mbanuania Ndrawa, ba me fadahö-dahö ira ba Yeruzalema, ba no so göi ndra''ugö, hulö na awöra ndra''ugö.[5]', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 12, 'Böi omusoi''ö dödöu, ba mbaŵa wamakao andrö, khö nakhiu, ba mbaŵa wa''ate''ala andrö khönia. Böi owua-wua dödöu ba mado Yuda andrö, na baŵa wa''atekikora; böi ömanö wamaboka bawau, na baŵa wa''atosasa khöra.', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 13, 'Böi törö mbawa göli mbanuagu, na baŵa wamakao khöra; böi omuso dödöu göi ba wamakaora, na baŵa wamakao khöra, ba böi babaya zi so khöra, na baŵa wamakao khöra.', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 14, 'Böi iagö wabaliŵa lala, ba wamunu soloi, banuara, ba böi ra''u zoloi andrö, na baŵa wa''atosasa![6]', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 15, 'Noa sa ahatö mbaŵa andrö khö Yehowa, ba niha baero fefu [baŵa wanguhuku]. Tesulöni khöu nilaumö andrö, mangandrauli ba högöu wolaumö![7]', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 16, 'Si mane famadumi mege ba hili ni''amoni''ö andrö khögu, si manö dania wamadu niha baero fefu, si lö aetu; mamadu ira ba mangohofo, ba tobali si mane si lö mangila haga zi moluo!', '["Yer 49:7 b.t.","Yes 29:14","Hes. 25:13","MozIV 27:41; Sin 137:7; Hez 35:5; Amos 1:11","Nga''ötII 21:16 b.t.","Hez 35:15","Yoel 2:1"]', NULL),
  (3476323, 'OT', 'Obadia', 1, 17, 'Ba ba hili Ziona, ba so wangorifi, ba "ni''amoni''ö" döinia, ba la''okhögö dana khöra ma''uwu Yakobo.', '[]', NULL),
  (3476323, 'OT', 'Obadia', 1, 18, 'Tobali alitö nga''ötö Yakobo, ba hola-hola galitö nga''ötö Yosefo. Ba ma''uwu Gezau, ba tobali töla wakhe soköli, ba ira''i alitö no mege, ba i''a, ba tobali lö hadia ia zi tosai nga''ötö Gezau; me no moroi ba li Yehowa.', '[]', NULL),
  (3476323, 'OT', 'Obadia', 1, 19, 'Banua tanö raya andrö zangokhögö hili Ndraono Gedomo, ba banua ba zalo''o zangokhögö tanö Ndrawa Wilisiti; ba he benua mado Gerefayi, ba he benua Zamaria, ba la''otanö, ba mado Mbeniyami zangai tanö Gileadi.', '[]', NULL),
  (3476323, 'OT', 'Obadia', 1, 20, 'Ba Iraono Gizeraeli ni''oloi''ö mege, banua saro andre, ba la''okhögö danö Ndrawa Gana''ana, irugi tanö ba Zarefa, ba ni''oloi''ö, banua Yeruzalema, si so ba Zefarada, ba la''okhögö mbanua tanö raya.', '[]', NULL),
  (3476323, 'OT', 'Obadia', 1, 21, 'Sangorifi zanaŵa hili Ziona, ba wamatörö huku ba hili ma''uwu Gezau, ba khö Yehowa wa''arazo.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 1, 'Ba humede Yehowa khö Yona, ono Gamita''i, imane:[1]', '["RazII 14:25","MozI 10:11; 18:21; Faigi 18:5","HalZin 9:36"]', NULL),
  (3476467, 'OT', 'Yona', 1, 2, 'Faoso, ae ba Niniwe, banua sebua andrö, ba angombakha khöra; noa sa irugi ndra''o, ba da''e si yaŵa horöra andrö![2]', '["RazII 14:25","MozI 10:11; 18:21; Faigi 18:5","HalZin 9:36"]', NULL),
  (3476467, 'OT', 'Yona', 1, 3, 'Ba maoso Yona, ba woloi khö Yehowa, isaŵa Darisi ena''ö. Ba irugi si tou Yafo, ba isöndra nowo, sanaŵa Tarisi. Ba ibe''e wanofa, ba möi ia yaŵa, ba wefao khöra ba Darisi, ba woloi khö Yehowa.[3]', '["RazII 14:25","MozI 10:11; 18:21; Faigi 18:5","HalZin 9:36"]', NULL),
  (3476467, 'OT', 'Yona', 1, 4, 'Ba ifatörö nangi sabe''e ba nasi Yehowa, tobali bade sabölö-bölö, ba nasi, hato ma''ifu tö, ba aboto nowo.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 5, 'Ba ata''u sibai zolohe owo, ba i''angaröfi li Lowalanginia zamösana. Ba latibo''ö ba nasi gama-gama ba nowo, ena''ö aoha. Ba no möi si tou Yona, ba wondrege si tou ba nowo, no ifadölö ia, ba mörö sibai.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 6, 'Ba möi khönia Nakoda, imane khönia: Hadia khöu da''ö, wa mörö''ö? Faoso, angaröfi li Lowalangimö! Ma atö itörö tödö Lowalangi da''ö ita, fa böi ahöndrö ita!', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 7, 'Ba faoma lamane khö nawöra: Talabu, talau fadahö-dahö, ena''ö tasöndra, ha niha mbörö, wa göna ita famakao andre! Ba me fadahö-dahö ira, ba Yona zi göna.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 8, 'Ba lamane khönia: Ombakha''ö khöma, ha niha mbörö, wa göna ita famakao andre: Hadia halö-halöŵöu, ba heza ö''otarai? Ha banua ba ha soi ndra''ugö?', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 9, 'Ba imane khöra: Niha Heberaio ndra''odo, samosumange Yehowa, Lowalangi zorugo, somböi asi ba tanö sabe''e.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 10, 'Ba ata''u sibai niha andrö, ba lamane khönia: Hadia nilaumö andrö? Noa sa larongo niha andrö, wa no soloi khö Yehowa ia, me no i''ombakha''ö khöra.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 11, 'Ba lasofu khönia, lamane: He mawisa khöu, ena''ö tebato mbade andre khöda? Itugu manö ebua ndrulu.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 12, 'Ba imane khöra: Mituyu ndra''o ba mitibo''ödo ba nasi, ba ahono khömi nasi. Noa sa aboto ba dödögu, wa no ya''odo mbörö, wa göna ami bade sabölö-bölö andre!', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 13, 'Ba laforege niha andrö, ba wolohe ba labua owo, ba tebai; me itugu manö abölö-bölö mbade andrö khöra.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 14, 'Ba la''angaröfi li Yehowa, lamane: He Yehowa! Böi be''e tekiko ndra''aga, börö noso niha andre, ba böi be''e ba huluma ndro zi lö horö! Noa sa ölau zomasi ndra''ugö, ya''ugö Yehowa!', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 15, 'Ba latuyu Yona, ba latibo''ö ba nasi; ba döhö mbade.', '[]', NULL),
  (3476467, 'OT', 'Yona', 1, 16, 'Ba ata''u sibai niha andrö Yehowa, labe''e khönia zumange nitaba ba lafabu''u na khönia.', '[]', NULL),
  (3476468, 'OT', 'Yona', 2, 1, 'Ba ifatörö gi''a sebua Yehowa, ba wanölö Yona. Ba tölu ngaluo ba tölu mbongi Yona ba dalu gi''a.[1]', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 2, 'Ba mangandrö Yona ba dalu gi''a andrö khö Lowalanginia Yehowa, imane:', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 3, '"Ba wa''atosasagu andre u''angaröfi li Yehowa, ba no itema ligu; moroi ba dalu mbanua tou mu''ao ndra''o, ba no öfondrondrongo ligu.[2]', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 4, 'No ötibo''ö ba namö ndra''odo, ba dalu nasi, ba no te''u''u ndra''o hou, no ihawui ndra''o hou ba dulu andrö khöu, fefu.', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 5, 'No umane sa''ae dödögu: No tetibo ndra''odo, lö''ö sa''ae öfaigido! Hadia, ifuli maö u''ila gosali andrö khöu, ni''amoni''ö?', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 6, 'No te''u''u ndra''o asi, irugi nosogu, no ifasui ndra''o hou, no iböbö högögu du''u ba nasi.', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 7, 'No numalö si tou ndra''o ba wondrege dayadaya hili; ilazi ndra''o tanö, si lö mamalö-malö. Ba no ösöbi yaŵa nosogu, moroi ba gohokoho, ya''ugö Lowalangigu Yehowa!', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 8, 'Me no aragu-ragu bakha dödögu, ba itörö tödögu Yehowa, ba irugi ndra''ugö fangandrögu, ba gosali andrö khöu, ni''amoni''ö.', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 9, 'Si olembai adu faya andrö, ba la''ositengagö wa''ebua dödö andrö, si falukha ira ena''ö.[3]', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 10, 'Ba ya''odo, ba u''ebua''ö ligu wangandrö saoha gölö khöu, ufosumange ndra''ugö; hadia nifabu''ugu, ba ubu''a: khö Yehowa i''otarai fangorifi!"[4]', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476468, 'OT', 'Yona', 2, 11, 'Ba ibe''e li khö gi''a andrö, Yehowa, ba i''uta''ö baene Yona.', '["Mat 12:40; 16:4; Luk 11:29 b.t.","Sin 120:1","Sin 144:2","Sin 3:9; 50:14"]', NULL),
  (3476469, 'OT', 'Yona', 3, 1, 'Ba ifuli humede Yehowa khö Yona, imane:', '[]', NULL),
  (3476469, 'OT', 'Yona', 3, 2, 'Faoso, ae ba Niniwe, banua sebua andrö, ba turiagö khöra niŵa''ögu khöu.', '[]', NULL),
  (3476469, 'OT', 'Yona', 3, 3, 'Ba maoso Yona, möi ia ba Niniwe, i''o''ö niŵa''ö Yehowa khönia. Ba no banua sebua sibai Niniwe andrö, tölu ngaluo fofanö wa''anau.', '[]', NULL),
  (3476469, 'OT', 'Yona', 3, 4, 'Ba ibörötaigö Yona itörö newali mbanua, ma''ökhö fofanö, mangombakha ia, imane: Hato öfa wulu wongi, ba adudu Niniwe!', '[]', NULL),
  (3476469, 'OT', 'Yona', 3, 5, 'Ba faduhu dödö mbanua Niniwe khö Lowalangi, laŵa''ö wamoni ba la''obaru mbaru ba wa''abu dödö, he satua ba he iraono.[1]', '["Dan 9:3; Mat 12:41; Luk 11:30","Yes 59:6","Yoel 2:14","Yer 18:8"]', NULL),
  (3476469, 'OT', 'Yona', 3, 6, 'Ba me irongo duria andrö razo Niniwe, ba maoso ia, iröi dadaoma razo, iheta mbarunia baru sebua, ihalö balu-balunia mbaru ba wa''abu dödö; ba mudadao ia bawu.', '["Dan 9:3; Mat 12:41; Luk 11:30","Yes 59:6","Yoel 2:14","Yer 18:8"]', NULL),
  (3476469, 'OT', 'Yona', 3, 7, 'Ba ifatenge zihede ba mbanua Niniwe, imane; Da''ö goroisa razo ba oroisa nawönia salaŵa: Böi manga niha ba he urifö, he saŵi, ba he biri-biri; lö tola möi ba ndru''u, ba lö tola labadu nidanö.', '["Dan 9:3; Mat 12:41; Luk 11:30","Yes 59:6","Yoel 2:14","Yer 18:8"]', NULL),
  (3476469, 'OT', 'Yona', 3, 8, 'La''obaru mbaru ba wa''abu dödö — he niha, ba he urifö — ba laforege wangaröfi li Lowalangi, ba iböhöli mbua-buania si lö sökhi andrö zamösana awö horö andrö, si no falemba ba dangara.[2]', '["Dan 9:3; Mat 12:41; Luk 11:30","Yes 59:6","Yoel 2:14","Yer 18:8"]', NULL),
  (3476469, 'OT', 'Yona', 3, 9, 'Ma atö alulu dödö Lowalangi, ma aröuröu ba dödönia, ma alö wönunia, fa böi tekiko ita![3]', '["Dan 9:3; Mat 12:41; Luk 11:30","Yes 59:6","Yoel 2:14","Yer 18:8"]', NULL),
  (3476469, 'OT', 'Yona', 3, 10, 'Ba me i''ila wolaura Lowalangi, wa laböhöli mbua-buara si lö sökhi andrö, ba aröuröu ba dödö Lowalangi wamakiko andrö niŵa''önia, fameta''u ya''ira, ba lö ifalua.[4]', '["Dan 9:3; Mat 12:41; Luk 11:30","Yes 59:6","Yoel 2:14","Yer 18:8"]', NULL),
  (3476470, 'OT', 'Yona', 4, 1, 'Ba abao sibai dödö Yona, mofönu ia.[1]', '["Luk 15:20","MozII 34:6; Sin 86:5; Yoel 2:13"]', NULL),
  (3476470, 'OT', 'Yona', 4, 2, 'Ba mangandrö ia khö Yehowa, imane: He Yehowa, ya''ia da''ö niŵa''ögu, me sodo ba khöma na, ba da''ö mbörö woloigu, me usaŵa Darisi ena''ö, fa böi si manö! Noa sa aboto ba dödögu, wa no Lowalangi sebua tödö ba sahakhö tödö ndra''ugö, si lö alio-lio mofönu ba si no fahöna fa''asökhi dödö, awö wa aröuröu ba dödöu dania wamakiko andrö [niŵa''öu]![2]', '["Luk 15:20","MozII 34:6; Sin 86:5; Yoel 2:13"]', NULL),
  (3476470, 'OT', 'Yona', 4, 3, 'Ba etu''ö manö sa''ae nosogu, ya''ugö Yehowa, sökhi sa na matedo, moroi na aurido!', '["Luk 15:20","MozII 34:6; Sin 86:5; Yoel 2:13"]', NULL),
  (3476470, 'OT', 'Yona', 4, 4, 'Ba imane Yehowa: Hadia, si ndruhu, so mbörö wönumö andrö?', '["Sin 145:9"]', NULL),
  (3476470, 'OT', 'Yona', 4, 5, 'Ba iheta ia yomo ba mbanua Yona, tou mbanua i''iagö, tanö ba gatumbukha luo. Ilau nose khönia ba da''ö, ba mudadao ia baose andrö, ba lumö, ba wamaigi hadia nifatörö Yehowa ba mbanua andrö.', '["Sin 145:9"]', NULL),
  (3476470, 'OT', 'Yona', 4, 6, 'Ba ifatumbu''ö lafandru Yehowa, Lowalangi; manöi, yaŵa Yona, ena''ö telumö högönia, ba ena''ö döhö walösökhi-sökhi dödönia; ba omuso sibai dödö Yona lafandru andrö.', '["Sin 145:9"]', NULL),
  (3476470, 'OT', 'Yona', 4, 7, 'Ba me moluo, me mahemolu ö, ba i''asogö gukuö Lowalangi, sanögi töla lafandru, ba aleu.', '["Sin 145:9"]', NULL),
  (3476470, 'OT', 'Yona', 4, 8, 'Ba me tumbu luo, ba ifatörö nangi timu, angi lökhö, Lowalangi, ba ihandro högö Yona sino, ba atata sibai dölania. Ba omasi ia mate, imane: Sökhi na matedo, moroi na aurido!', '["Sin 145:9"]', NULL),
  (3476470, 'OT', 'Yona', 4, 9, 'Ba imane Lowalangi khö Yona: Hadia, si ndruhu, so mbörö wönumö, ba lafandru andrö? Ba imane: Tenga si lö börö, na mofönu ndra''odo, irugi wa''amategu!', '["Sin 145:9"]', NULL),
  (3476470, 'OT', 'Yona', 4, 10, 'Ba imane Yehowa: Ya''ugö, ba no sahakhö tödö lafandru andrö, si lö erege dödöu ba si tenga ni''e''ebuamö; ha sara wongi wanöinia ba ha sara wongi göi wa''amatenia.', '["Sin 145:9"]', NULL),
  (3476470, 'OT', 'Yona', 4, 11, 'Ba ya''odo, ba hadia, ba lö uhakhösi tödö Niniwe andrö, banua sebua, si no töra 120.000 nono niha, si lö mangila hezo gambölö, ba hezo gabera, awö gurifö niha, soya sibai?[3]', '["Sin 145:9"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 1, 'Da''e daroma li Yehowa andrö, niŵa''önia khö Mikha andrö, banua Moreseti, me luo razo mado Yuda Yotamo ba Ahasi ba Hisikia: niŵa''ö khönia, nitandrösaigö ba Zamaria ba ba Yeruzalema.[1]', '["Nga''ötII 27:1; RazII 16:1; 18:1; 15:32; Yes 1:1; Yes 26:18"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 2, 'Mifondrondrongo, ya''ami niha baero, fefu! Be''e mbörö dalingau, ya''ugö tanö, fabaya ösiu! Ba akha möi si so ba mbörö Zo''aya, Yehowa, ba khömi andrö, So''aya andrö, moroi ba gosalinia andrö, ni''amoni''ö.[2]', '["MozV 32:1; Yes 1:2","MozV 32:13; 33:29; Sin 115:3; Yes 26:31","Sin 97:5; Amos 9:5","RazII 23:13"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 3, 'Hiza sa, mangefa ba nahiania Yehowa, möi ia mitou ba itörö misa hili ba guli danö.[3]', '["MozV 32:1; Yes 1:2","MozV 32:13; 33:29; Sin 115:3; Yes 26:31","Sin 97:5; Amos 9:5","RazII 23:13"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 4, 'Ba alau hili, barö gahenia ba asila zalo''o, timba zigu-sigu ba galitö ba timba nidanö, moroi yaŵa ba hili.[4]', '["MozV 32:1; Yes 1:2","MozV 32:13; 33:29; Sin 115:3; Yes 26:31","Sin 97:5; Amos 9:5","RazII 23:13"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 5, 'Börö da''ö fefu, ba olalöŵa ma''uwu Yakobo, awö horö Ndraono Gizeraeli andrö. Hadia golalöŵa ma''uwu Yakobo andrö? Hadia, tenga Samaria andrö? Ba hadia horö mado Yuda? Hadia, tenga Yeruzalema andrö?[5]', '["MozV 32:1; Yes 1:2","MozV 32:13; 33:29; Sin 115:3; Yes 26:31","Sin 97:5; Amos 9:5","RazII 23:13"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 6, 'Ba ubali''ö sa''ae baho gara ba mbenua Zamaria, ubali''ö naha kabu nagu. Ba karania, ba ufagaölö mitou ba zalo''ö tanö, ba u''oroma''ö dayadayania.', '["MozV 32:1; Yes 1:2","MozV 32:13; 33:29; Sin 115:3; Yes 26:31","Sin 97:5; Amos 9:5","RazII 23:13"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 7, 'Adu nifofoe andrö khöra, fefu, ba nirasa, ba buala andrö khöra, fefu, ba nitunu ba galitö, ba he naha nadu andrö khöra, fefu, ba ubali''ö tanö si mate; me no luo zohorö mege wangöhöna ya''ia, ba si tobali luo zohorö zui dania.', '["MozV 32:1; Yes 1:2","MozV 32:13; 33:29; Sin 115:3; Yes 26:31","Sin 97:5; Amos 9:5","RazII 23:13"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 8, 'Andrö wa mangarö-ngarö ndra''o, ba mege-egedo, mowaö-waö manö ndra''o, lö badagahe ba lö baru sebua; ulau mege-ege, si mane asu ana''a, ba mangarö-ngarödo, si mane fofo ondra.[6]', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 9, 'Me no tebai nidalu-daluni zokhora andrö; irugi sa''ae mado Yuda, ikhamö mbawa göli mbanuagu andrö, irugi Yeruzalema!', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 10, 'Böi sa mifarongogö ba Gata, böi mi''ege-ege ba Ako! Ba Mbeti Afera milau gawu-gawu ba nösimi.[7]', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 11, 'Mitörö, ya''ami banua Zafiri, si lö balu-balu, akha aila ami! Ata''u möi tou mbanua Za''ana; fege-ege Mbeti Eseli andrö zi fatimba khömi, na mi''iagö da''ö ena''ö.[8]', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 12, 'Manizi-nizi sa''ae mbanua Maroto andrö, wangalui fangorifi; so sa wamakiko mbawa göli Yeruzalema, si otarai moroi yaŵa khö Yehowa.[9]', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 13, 'Mifa''anö kudo, ba gureta, ya''ami banua Lakhisi! Da''ö zamobörö horö ba mbanua Ziona, me no ba khöu tesöndra lalö Ndraono Gizeraeli andrö.', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 14, 'Andrö wa öbe''e zura wangefa ba Moreseti Gata; tobali falimosa ba razo Ndraono Gizeraeli nomo ba Nakhisibi andrö.', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 15, 'Samuza tö ufatörö khömi zanuwö ya''ami, ya''ami banua Maresa; larugi dania Gadula salaŵa Ndraono Gizeraeli.', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476471, 'OT', 'Mikha', 1, 16, 'Fatöwö''ö mbumö, awö gambiu, börö ndraono omasiö andrö khöu, ebolo''ö zi lö bu, si mane ba wofo nazari! aheta sa ira khöu, ni''oloi''ö.', '["Yob 30:29; Yes 21:3; Yer 4:19","SamII 1:20; Yer 6:26","Yes 47:3","Amos 3:6"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 1, 'Alai zamakhai si lö atulö, ba sama''ua si lö sökhi, ba gasora [ba zi bongi], ba wamalua ya''ia, na moluo, na ha si''aikö lasöndra lala.[1]', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 2, 'Na omasi ira mbenua, ba la''okhögö; ba na omo zomasi ira, ba lafadöni ba nawöra. Lafakao nawöra, ba lahalö manö zi so khöra; lafalangögö manö zokhö, fabaya si so khönia.[2]', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 3, 'Andrö wa imane Yehowa: Hiza, no so ba dödögu zi lö sökhi, nilau ba mbanuagu andrö, si tebai mifadöni mbagimi, ba si tebai mifaöga mbawami ba wowaö-waö, me baŵa si lö sökhi dania da''ö![3]', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476472, 'OT', 'Mikha', 2, 4, 'Na luo da''ö dania, ba manunö niha, fango''aya ya''ami, ba latema la''e''esi ami, lamane: "Noa sa''ae! No sadudu manö mbanuada. Nisu''a sinali mbenua mbanuada, ba wamaosa! Ifadöni manö khöma! Ba niha baero ifaosa mbenuama!"', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 5, 'Andrö wa lö khöu, samatörö sinali fanu''a ba dana ba mbanua Yehowa.', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 6, 'Lamane bewera: "Böi milau deatea mbewe." "Böi lahalö teatea mbewera da''ö! Lö aetu wango''aya andrö!"[4]', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 7, 'Hadia manö huo-huo andrö, ya''ami ma''uwu Yakobo? Hadia, si ono wönutö Yehowa, ba no si manö wolaunia? Hadia, tenga fangorifi daroma linia, tenga fangorifi zadölö tödö wanörö lalania?', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 8, 'Ba no ara sa''ae, ba molaŵa mbanuagu andrö, si fa''udu ira. Ba zanörö si lö famaudu dödö, ba sanuzu tödö fagua-guasa, ba misöbi mbaru sebua, balu-balu gameza.', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 9, 'Ira alawe mbanuagu, ba mitimba yomo ba nomora, sohahau dödöra, ba ba ndraonora, ba mifadöni naya andrö nibe''egu, ba lö mifuli.', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 10, 'Mifaoso, milabu ami! lö''ö sa tola mi''iagö da''e, börö wa''ara''i-ra''iö andrö, famakiko ba famunu.[5]', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 11, 'Na ilimo ena''ö ndra''ugö sama ua angi ba faya, na imane ena''ö: Da mama''ele''ö ndra''o khöu: agu ba hadia ia nibadu, si mabu ita! — da''ö zama''ele''ö zi göna ba mbanua andre![6]', '["Yob 12:6","Yes 5:8; Amos 2:7,8","Amos 5:13; 2:14–16","Yes 30:10; Amos 7:16","MozIII 18:25","Yes 30:10"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 12, 'Ahori u''ozaragö ami, ya''ami ma''uwu Yakobo! Ahori ufuli u''owuloi zi tosai Iraono Gizeraeli! U''orudugö ira, si mane biri-biri ba kandra, si mane nikubaloi ba mbenua, ba tobali ato sibai, siruru-ruru![7]', '["Yer 31:10","Yes 52:12"]', NULL),
  (3476472, 'OT', 'Mikha', 2, 13, 'Ba mowaö-waö fönara zamolala ya''ira; latimba zi fatimba ba latörö manö, lasaŵa baero mbawa göli. Ba mowaö-waö fönara razora, ba Yehowa zolohe ya''ira.[8]', '["Yer 31:10","Yes 52:12"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 1, 'Ba no umane: Mifondrondrongo ae, ya''ami högö ma''uwu Yakobo ba ya''ami samatörö nga''ötö Gizeraeli. Hadia, tenga sangila huku ami ena''ö?[1]', '["Yer 5:5; Faigi 6:8","Yes 5:20","Sin 14:4","Yob 27:9; Amaed 1:29; Hez 8:18"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 2, 'Laböhöli zi sökhi, ba ebua dödöra ba zi lö sökhi, labo''ai guli nawöra, ba lafaefa nagole ba döla.[2]', '["Yer 5:5; Faigi 6:8","Yes 5:20","Sin 14:4","Yob 27:9; Amaed 1:29; Hez 8:18"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 3, 'Öra nösi mbanuagu andrö, labo''ai guli ba nösi ba lafatö döla; latatawi, si mane nibe''e bawu, si mane nagole ba mbalanga.[3]', '["Yer 5:5; Faigi 6:8","Yes 5:20","Sin 14:4","Yob 27:9; Amaed 1:29; Hez 8:18"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 4, 'Awena dania mangarö-ngarö ira khö Yehowa, ba lö''ö sa ifondrondrongo lira, ba ibini''ö mbawania khöra, na luo da''ö, börö me no lalau zi lö sökhi.[4]', '["Yer 5:5; Faigi 6:8","Yes 5:20","Sin 14:4","Yob 27:9; Amaed 1:29; Hez 8:18"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 5, 'Da''ö niŵa''ö Yehowa ba zama''ele''ö andrö, si no molohe ba lala elungua banuagu, sanguma''ö: "Ya ahowu!" na so göra; ba si lö mame''e göra, ba lasuwö.[5]', '["Faigi 2:11; Mat 7:15","Yes 8:22; Amos 8:9","Sakh 8:4 b.t.","Yes 50:4; 58:1"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 6, 'Andrö wa itörö ami si bongi, lö angilata, ba fa''ogömi-gömi, lö fangombakha lala; aekhu luo ba zama''ele''ö andrö ba ogömi-gömi khöra ba zi ma''ökhö.[6]', '["Faigi 2:11; Mat 7:15","Yes 8:22; Amos 8:9","Sakh 8:4 b.t.","Yes 50:4; 58:1"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 7, 'Ba tobali si lö boto zangi''ila andrö, ba saila zama''ele''ö; dozi dania labalugö gambira, me lö itema lira Lowalangi![7]', '["Faigi 2:11; Mat 7:15","Yes 8:22; Amos 8:9","Sakh 8:4 b.t.","Yes 50:4; 58:1"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 8, 'Ba ya''odo, ba si no fahöna fa''abölö, Eheha Yehowa ba huku satulö ba fa''abe''e, ba wangombakha ba ma''uwu Yakobo fangerogöra Lowalangi, ba ba Ndraono Gizeraeli horöra.[8]', '["Faigi 2:11; Mat 7:15","Yes 8:22; Amos 8:9","Sakh 8:4 b.t.","Yes 50:4; 58:1"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 9, 'Mifondrondrongo, ya''ami högö ma''uwu Yakobo, ba ya''ami samatörö nga''ötö Gizeraeli, sanuzu tödö ba huku satulö ba samila''ö sadölö fefu:[9]', '["Amos 5:7","Hez 22:27; Nga''ötII 28:3","SamI 8:3; Yes 1:23; Hos 4:18","Sin 79:1; Yer 26:18; Luk 19:43"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 10, 'Fange''enge''e wanaru''ö Ziona khöra ba horö wanaru''ö Yeruzalema.[10]', '["Amos 5:7","Hez 22:27; Nga''ötII 28:3","SamI 8:3; Yes 1:23; Hos 4:18","Sin 79:1; Yer 26:18; Luk 19:43"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 11, 'Manga gana''a zalaŵa, ba wolohe ba lala hadia ia, ba ere khöra, ba latema luo ba wamahaöra; sama''ele''ö khöra, ba no sama''ele''ö nifoluo, ba ladöna-döna khö Yehowa lamane dödöra: So sa atö ba khöda Yehowa, tebai göna famakao ita![11]', '["Amos 5:7","Hez 22:27; Nga''ötII 28:3","SamI 8:3; Yes 1:23; Hos 4:18","Sin 79:1; Yer 26:18; Luk 19:43"]', NULL),
  (3476473, 'OT', 'Mikha', 3, 12, 'Andrö wa lafaku nowi dania Ziona, börö ami, ba Yeruzalema, ba si tobali adudula, ba hili satua eu dania hili gosali andrö![12]', '["Amos 5:7","Hez 22:27; Nga''ötII 28:3","SamI 8:3; Yes 1:23; Hos 4:18","Sin 79:1; Yer 26:18; Luk 19:43"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 1, 'Ba ba götö safuria dania, ba si no modayadaya saro hili gosali Yehowa andrö, salaŵa hili ba sanalu''i hili-hili misa; ba lahurufai ia niha baero.[1][2]', '["Faigi göi Yes 2","Sakh 8:21–23","Sin 25:4; 122:1; Sakh 8:18; 14:16 b.t.","Yoel 3:15","RazI 4:25; Yes 11:6 b.t.; Yer 30:10","MozV 30:4","Hez 34:16; Sef 3:19; Dan 2:44","MozI 35:21"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 2, 'Oya soi dania zi maoso, ba lamane: "Talabu, tasaŵa miyaŵa hili Yehowa andrö, ba osali Lowalangi, ena''ö ifahaö ita ba lala andrö khönia, ba ena''ö lalania andrö tatörö!" Me ba Ziona i''otarai amakhoita andrö, ba ba Yeruzalema i''otarai taroma li Yehowa.[3]', '["Faigi göi Yes 2","Sakh 8:21–23","Sin 25:4; 122:1; Sakh 8:18; 14:16 b.t.","Yoel 3:15","RazI 4:25; Yes 11:6 b.t.; Yer 30:10","MozV 30:4","Hez 34:16; Sef 3:19; Dan 2:44","MozI 35:21"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 3, 'Ba oya soi dania nifatunönia huhuo, ba he ba niha baero sabölö, irugi ba zaröu, ba ya''ia zangetu''ö huku; ba labali''ö faku zi''ölira si''öli nihaogö, ba tohora, ba labali''ö fondra''a. Sambua lö soi sa''ae solohe si''öli, ba wanuwö soi bö''ö; lö''ö sa''ae lafamaha ira ba wanuwö.[4]', '["Faigi göi Yes 2","Sakh 8:21–23","Sin 25:4; 122:1; Sakh 8:18; 14:16 b.t.","Yoel 3:15","RazI 4:25; Yes 11:6 b.t.; Yer 30:10","MozV 30:4","Hez 34:16; Sef 3:19; Dan 2:44","MozI 35:21"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 4, 'Sahono manö dania zamösana ba lumö nagu khönia ba ba lumö marafalania, lö si keani ya''ia, me no Yehowa ngahönö zanguma''ö.[5]', '["Faigi göi Yes 2","Sakh 8:21–23","Sin 25:4; 122:1; Sakh 8:18; 14:16 b.t.","Yoel 3:15","RazI 4:25; Yes 11:6 b.t.; Yer 30:10","MozV 30:4","Hez 34:16; Sef 3:19; Dan 2:44","MozI 35:21"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 5, 'Ba niha bö''ö fefu, ba no töi Lowalangira khöra, ba wanörö lalara, ba khöda, ba no töi Lowalangida Yehowa, ba wanöröda lalada, götö-götö wa''ara!', '["Faigi göi Yes 2","Sakh 8:21–23","Sin 25:4; 122:1; Sakh 8:18; 14:16 b.t.","Yoel 3:15","RazI 4:25; Yes 11:6 b.t.; Yer 30:10","MozV 30:4","Hez 34:16; Sef 3:19; Dan 2:44","MozI 35:21"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 6, 'Ba na luo da''ö, iŵa''ö Yehowa, ba u''ozaragö zi no mangahole''ö ya''ira, ba u''owuloi zi no muzaewe, fabaya si no ube''e te''ala mege.[6]', '["Faigi göi Yes 2","Sakh 8:21–23","Sin 25:4; 122:1; Sakh 8:18; 14:16 b.t.","Yoel 3:15","RazI 4:25; Yes 11:6 b.t.; Yer 30:10","MozV 30:4","Hez 34:16; Sef 3:19; Dan 2:44","MozI 35:21"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 7, 'Ba edöna u''orifi zi no mangahole''ö ya''ira, ba ubali''ö soi sato niha zi no muzaewe misa. Ba razora Yehowa, ba hili Ziona andrö, i''otarai da''ö, ba irugi zi lö aetu.[7]', '["Faigi göi Yes 2","Sakh 8:21–23","Sin 25:4; 122:1; Sakh 8:18; 14:16 b.t.","Yoel 3:15","RazI 4:25; Yes 11:6 b.t.; Yer 30:10","MozV 30:4","Hez 34:16; Sef 3:19; Dan 2:44","MozI 35:21"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 8, 'Ba ba khömö andrö, ya''ugö malige Ederi, hili-hili mbanua Ziona, ba möi khöu wa''asalaŵa föna, mangawuli khöu, fa''arazo ba mbanua Yeruzalema![8]', '["Faigi göi Yes 2","Sakh 8:21–23","Sin 25:4; 122:1; Sakh 8:18; 14:16 b.t.","Yoel 3:15","RazI 4:25; Yes 11:6 b.t.; Yer 30:10","MozV 30:4","Hez 34:16; Sef 3:19; Dan 2:44","MozI 35:21"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 9, 'Hana wa si manö wangarö-ngarömö? Hadia, lö razo khömi, ba ma no mate zamobawa lala khömi, wa no göna faniri ndra''ugö, timba zadono?', '["Sin 54:9","Sakh 4:14; 6:5","Yoh 18:22"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 10, 'Miköröbui ami, ya''ami Siona, ya afökhö hulumi, si mane ba zadono! Saheta yomo ba mbanua sa''ae ami, ba baero ba mbenua mörö-mörö ami, ba mirugi Mbabeli. Ba da''ö falukha ami wangorifi, ba da''ö i''efa''ö ami Yehowa, ba danga nemalimi!', '["Sin 54:9","Sakh 4:14; 6:5","Yoh 18:22"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 11, 'Ba iya''e, ba no oya soi sowulo udumi, sanguma''ö: Yatumörö ira salakha khöra, ena''ö fa''omasida wamaigi-maigi Siona andrö.[9]', '["Sin 54:9","Sakh 4:14; 6:5","Yoh 18:22"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 12, 'Ba ma''ifu lö saboto ba dödöra gera-era Yehowa andrö, ba lö la''ila watahögö dödönia andrö, wa no i''owuloi ira, timba nganu''i wakhe ba golayama mbasitö.', '["Sin 54:9","Sakh 4:14; 6:5","Yoh 18:22"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 13, 'Mifaoso, ya''ami banua Ziona, ba miböbörö! Ubali''ö si''öli sa''ae dandrumi, ba sa''ami, ba ubali''ö töla garamba, ena''ö oya soi mifufu. Ba ö''amoni''ö khö Yehowa nirabura andrö [mege], ba ana''ara, ba ö''amoni''ö khö Zo''aya tanö ma''asagörö.[10]', '["Sin 54:9","Sakh 4:14; 6:5","Yoh 18:22"]', NULL),
  (3476474, 'OT', 'Mikha', 4, 14, 'Ba mi''owuloi ami, ya''ami banua nidegeni mege! No lafasui ita fari [sanuwö]. Lafalisi ue dania mbo''ö zanguhuku Iraono Gizeraeli.[11]', '["Sin 54:9","Sakh 4:14; 6:5","Yoh 18:22"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 1, 'Ba ya''ugö Betilekhema Eferata, noa sa abölö ide-ide ndra''ugö, ba wamadoro ya''ugö ba mbanua zalaŵa ba mado Yuda ena''ö. Ba ba khöu sa i''otarai khögu samösa, si möi samatörö Iraono Gizeraeli; me föna sa''ae mbörötania, ba götö föna sibai sa''ae.[1]', '["Mat 2:6; Yoh 7:42; Amaed 8:23","Yes 7:14; Fam 12:5","Sin 72:4; Yes 9:7; Hez 34:11","Efes 2:14","Sakh 8:13; Sin 110:3"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 2, 'Andrö wa ilulu ira, irugi luo no madono zo''ono andrö, ba irugi mangawuli niwania si tosai andrö, awö Ndraono Gizeraeli.[2]', '["Mat 2:6; Yoh 7:42; Amaed 8:23","Yes 7:14; Fam 12:5","Sin 72:4; Yes 9:7; Hez 34:11","Efes 2:14","Sakh 8:13; Sin 110:3"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 3, 'Ba da''ö dania so ia, ba ikubaloi dania ira, fa''abölö Yehowa wa''abölönia, ba ba döi Lowalanginia Yehowa, si no ebua sibai; ba tobali sahono ira; sebua sa dania ia, irugi ba wondrege danö [wa''asalaŵania].[3]', '["Mat 2:6; Yoh 7:42; Amaed 8:23","Yes 7:14; Fam 12:5","Sin 72:4; Yes 9:7; Hez 34:11","Efes 2:14","Sakh 8:13; Sin 110:3"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 4, 'Ba ya''ia dania wa''atulö! Na lasaŵa danöda Dawa Asiria, na möi ba khöda, ba dafitu tabe''e sanimba ya''ira kubalo mbiri-biri, ba daŵalu zalaŵa.[4]', '["Mat 2:6; Yoh 7:42; Amaed 8:23","Yes 7:14; Fam 12:5","Sin 72:4; Yes 9:7; Hez 34:11","Efes 2:14","Sakh 8:13; Sin 110:3"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 5, 'Da''ö dania zamatörö si''öli ba zi so ba danö Ndrawa Asiria, ba föda si no musobi lafatörö ba danö Nimerodi, ba tobali i''orifi ita, lö ibe''e ba danga Ndrawa Asiria ita, na lasaŵa danöda, na möi ba khöda.[5]', '["Mat 2:6; Yoh 7:42; Amaed 8:23","Yes 7:14; Fam 12:5","Sin 72:4; Yes 9:7; Hez 34:11","Efes 2:14","Sakh 8:13; Sin 110:3"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 6, 'Ba si tosai ma''uwu Yakobo, ba niha baero, sizaewe ba niha bö''ö, soya misa, ba tobali timba namo mbanua, timba daŵa deu, satoru ba mbulu zinanö, si lö manötöna ba niha, si lö mombaloi fa''aso niha.', '["Mat 2:6; Yoh 7:42; Amaed 8:23","Yes 7:14; Fam 12:5","Sin 72:4; Yes 9:7; Hez 34:11","Efes 2:14","Sakh 8:13; Sin 110:3"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 7, 'Si tosai ma''uwu Yakobo andrö, ba niha baero, sizaewe ba niha bö''ö soya misa, ba tobali timba zingo ba gutu ndru''u, ba timba nono zingo ba ngawawa mbiri-biri, si hundra-hundra ba sanasawi na itörö, lö sangorifi.', '["Mat 2:6; Yoh 7:42; Amaed 8:23","Yes 7:14; Fam 12:5","Sin 72:4; Yes 9:7; Hez 34:11","Efes 2:14","Sakh 8:13; Sin 110:3"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 8, 'Sabölö dania ndra''ugö, ba ölaŵa zamakao ya''ugö, ba ahori dania nemaliu fefu!', '["Mat 2:6; Yoh 7:42; Amaed 8:23","Yes 7:14; Fam 12:5","Sin 72:4; Yes 9:7; Hez 34:11","Efes 2:14","Sakh 8:13; Sin 110:3"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 9, 'Ba na luo da''ö, iŵa''ö Yehowa, ba uhori kudo khöu, ba uheta gureta,[6]', '["Sakh 9:10","Nakh 1:14"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 10, 'banua andrö ba danöu, ba uhori, ba hati andrö khöu, ba ahori ududugö.', '["Sakh 9:10","Nakh 1:14"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 11, 'Ba elemu andrö, ba uhori ba dangau, ba sanoto, ba lö''ö sa''ae ba khömi.', '["Sakh 9:10","Nakh 1:14"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 12, 'Adu nifofoe andrö khöu ba famaedo hadia ia, ba uhori ba khömi, ba lö''ö sa''ae mangalulu ndra''ugö ba nifazökhi dangau.[7]', '["Sakh 9:10","Nakh 1:14"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 13, 'Aseramö andrö, ba udeha khöu, ba adumö, ba ufufu.', '["Sakh 9:10","Nakh 1:14"]', NULL),
  (3476475, 'OT', 'Mikha', 5, 14, 'Ba ulau mbalö ba niha baero andrö, si lö mamondrongo ligu, mofönudo khöra ba abao dödögu.', '["Sakh 9:10","Nakh 1:14"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 1, 'Mifondrondrongo hadia niŵa''ö Yehowa: Faoso, fatunö huhuo ba zanehe hili, ena''ö irongo limö bawö andrö!', '["Hos 4:1; Amos 3:9","Yer 2:5","MozII 15:20","MozIV 22:18; 25:1; Yos 4:20"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 2, 'Mifondrondrongo, ya''ami hili, huhuo Yehowa andrö, ba ya''ami si lö tebulö, ya''ami dayadaya danö! So sa huhuo Yehowa ba mbanuania, ba ifatörö huku ba Ndraono Gizeraeli.[1]', '["Hos 4:1; Amos 3:9","Yer 2:5","MozII 15:20","MozIV 22:18; 25:1; Yos 4:20"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 3, '"Hadia horögu khömi, ya''ami banuagu, ba heza so nifakaogu ya''ami? Mitunö khögu![2]', '["Hos 4:1; Amos 3:9","Yer 2:5","MozII 15:20","MozIV 22:18; 25:1; Yos 4:20"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 4, 'Noa sa atö u''ohe miyaŵa ami moroi ba danö Miserayi, no u''efa''ö ami ba danö, ba zi no möi sawuyu ami, ba no ube''e solohe ya''ami ndra Moze, A''aroni, Miriya.[3]', '["Hos 4:1; Amos 3:9","Yer 2:5","MozII 15:20","MozIV 22:18; 25:1; Yos 4:20"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 5, 'Mitörö-törö tödömi, ya''ami banuagu, hadia dödö Mbalaki andrö, razo Ndraono Moabi, ba hadia niŵa''ö Mbileamo andrö, ono Mbeoro, wanema linia, ba he wisa, i''otarai Ziti, numalö ba Giligala, ena''ö aboto ba dödömi wa''ebua dödö Yehowa andrö."[4]', '["Hos 4:1; Amos 3:9","Yer 2:5","MozII 15:20","MozIV 22:18; 25:1; Yos 4:20"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 6, '"Hadia ni''ohegu khö Yehowa, wangondrasi ya''ia, wangalulu khö Lowalangi ba zalaŵa yaŵa? Hadia, u''ohe khönia zumange nitunu, ono zaŵi si döfi fa''ebua?[5]', '["Sin 50:8; 51:18; Yes 1:11","MozV 10:12"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 7, 'Hadia, omasi Yehowa ngahönö mbiri-biri si matua, ba omasi ia hele fanikha si lö mutaha mu''erai? Hadia, ube''e khönia zi a''a nonogu, ba wameta horögu andrö; nga''ötögu ube''e khönia, höli nosogu?', '["Sin 50:8; 51:18; Yes 1:11","MozV 10:12"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 8, 'No iŵa''ö khöu, ya''ugö niha, hadia zi sökhi! Ba hadia goroisa Yehowa khöu, baero ba wolau satulö ba ba wangomasi''ö awöu ba fa böi fayaŵa ndra''ugö ba wanörö lalamö, föna Lowalangiu?[6]', '["Sin 50:8; 51:18; Yes 1:11","MozV 10:12"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 9, 'Fondrondrongo! Lö aefa-aefa we''ao Yehowa ba mbanua, ba fangorifi larongo sangata''ufi töinia. Mifondrondrongo wotu andrö ba ha niha zanguma''ö ya''ia.', '["Amos 8:5","MozIII 19:35; Hos 12:8","Yer 9:8","MozIII 26:26","MozV 28:38; Amos 5:11; Sef 1:13; Hag 1:6","RazI 16:25–30"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 10, 'Hadia, so yomo khö zebua horö gana''a si lö atulö, ba wangalui ya''ia mege, awö lauru sabölö ide-ide, ni''elifi ena''ö?[7]', '["Amos 8:5","MozIII 19:35; Hos 12:8","Yer 9:8","MozIII 26:26","MozV 28:38; Amos 5:11; Sef 1:13; Hag 1:6","RazI 16:25–30"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 11, 'Hadia, si lö sala zi so faliera falimosa ba tokosa naha zaga si lö atulö?[8]', '["Amos 8:5","MozIII 19:35; Hos 12:8","Yer 9:8","MozIII 26:26","MozV 28:38; Amos 5:11; Sef 1:13; Hag 1:6","RazI 16:25–30"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 12, 'Na famakao awöra lafa''ua sebua ana''a ba khöra, ba na faya lalau banuara ba na si falimo lela ba mbawara?[9]', '["Amos 8:5","MozIII 19:35; Hos 12:8","Yer 9:8","MozIII 26:26","MozV 28:38; Amos 5:11; Sef 1:13; Hag 1:6","RazI 16:25–30"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 13, 'Ba ya''odo göi, ba ubörötaigö uböbözi''ö, u''asogö wanudugö, börö horöu andrö.', '["Amos 8:5","MozIII 19:35; Hos 12:8","Yer 9:8","MozIII 26:26","MozV 28:38; Amos 5:11; Sef 1:13; Hag 1:6","RazI 16:25–30"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 14, 'Na manga''ö, ba lö abuso''ö ube''e, dörödöro manö wa''olofo dalumö a''ine. Ba na mangirö ndra''ugö, ba lö''ö sa atö zi töra balazou; si töra, ba ululu ba mbawa zi''öli a''i.[10]', '["Amos 8:5","MozIII 19:35; Hos 12:8","Yer 9:8","MozIII 26:26","MozV 28:38; Amos 5:11; Sef 1:13; Hag 1:6","RazI 16:25–30"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 15, 'Na manaru fakhe ndra''ugö, ba lö mamasi''ö ube''e! Na ölazi mbua zai, ba lö öbayoini fanikha ndra''ugö; ba na bua nagu ölazi, ba lö öbadu nösi.[11]', '["Amos 8:5","MozIII 19:35; Hos 12:8","Yer 9:8","MozIII 26:26","MozV 28:38; Amos 5:11; Sef 1:13; Hag 1:6","RazI 16:25–30"]', NULL),
  (3476476, 'OT', 'Mikha', 6, 16, 'Ba no ötöngöni gamakhoita Omeri, awö nilau zi samba omo ndra Ahabi, fefu, tödöra zi no mi''ohia''ö, ena''ö ubali''ö tanö si mate ndra''ugö ba fama''iki niha bö''ö zowanua ba danö; tohare sa dania khömi wango''aya niha baero.[12]', '["Amos 8:5","MozIII 19:35; Hos 12:8","Yer 9:8","MozIII 26:26","MozV 28:38; Amos 5:11; Sef 1:13; Hag 1:6","RazI 16:25–30"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 1, 'Alai ndra''o, no timba zangozaragö bua geu ndra''odo, hulö zangezökhöi wo''uwo''u ba waneteu bua nagu: Lö''ö sa''ae bua nagu, ögu, ba lö''ö sa''ae bua ara sahulö, somasido ena''ö.[1]', '["Yer 24","Sin 12:2; Yes 57:1","Faigi 3:11","Yer 9:4","Hez 22:7; Mat 10:21"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 2, 'Niha satulö tödö, ba no taya ba danö; sadölö tödö, ba lö''ö sa''ae ba niha; no dozi sanaro ira, ba wange enge''e; ilau gu''ö nawönia zamösana.[2]', '["Yer 24","Sin 12:2; Yes 57:1","Faigi 3:11","Yer 9:4","Hez 22:7; Mat 10:21"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 3, 'Si lö sökhi nifa''ua dangara ba wamalua ya''ia ba wa''alio. Salaŵa, ba mangandrö ana''a, ba sanguhuku, ba itema luo, ba sebuara, ba iŵa''ö manö zomasi dödönia; si manö wamakhaira ya''ia.[3]', '["Yer 24","Sin 12:2; Yes 57:1","Faigi 3:11","Yer 9:4","Hez 22:7; Mat 10:21"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 4, 'Si sökhira, ba no timba manaze, ba satulö, ba no atarö moroi ba göli hao mbitaha. Baŵa zanaro andrö khöu, fangotu''ö ya''ugö, ba no ahatö!', '["Yer 24","Sin 12:2; Yes 57:1","Faigi 3:11","Yer 9:4","Hez 22:7; Mat 10:21"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 5, 'Ba si tokea dania ira! Böi sa''ae abe''e dödömi khö zi fahuwu khömi! Böi manötöna ami ba zi no ha sara tödö khömi mege! Faigi-faigi mbawandruhö mbawau, he ba khö nitalaguimö andrö.[4]', '["Yer 24","Sin 12:2; Yes 57:1","Faigi 3:11","Yer 9:4","Hez 22:7; Mat 10:21"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 6, 'I''o''aya sa''ae namania ono matua, ba ilaŵa ninania ono alawe, ba böli gana''a, ba ilaŵa ninania sowöli ya''ia: Si fa''udu ba niha, ba ya''ia zoroiyomonia fefu![5]', '["Yer 24","Sin 12:2; Yes 57:1","Faigi 3:11","Yer 9:4","Hez 22:7; Mat 10:21"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 7, 'Ba ya''odo, ba utöngötöngöni khö Yehowa, manötöna ndra''o khö Lowalangi andrö, sangorifi ya''odo. Ifondrondrongo sa ligu Lowalangigu.', '["Yer 50:34","Yoel 2:17"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 8, 'Böi omuso dödöu ba khögu andrö ya''ugö si fa''udu khögu! Na no alau ndra''o, ba ufuli maoso; na ba zogömi-gömi so ndra''o, ba haga khögu Yehowa.', '["Yer 50:34","Yoel 2:17"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 9, 'Fönu Yehowa andrö, ba ulu''i, me no molalö ndra''o khönia, irege ifondrondrongo huhuogu andrö, ba irege i''ohe ba lala. I''ohe ba haga dania ndra''odo, ba fangokafu dödögu dania wa''atulönia andrö.[6]', '["Yer 50:34","Yoel 2:17"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 10, 'Ba akha ifaigi-faigi dania udugu andrö, ba ya tehawu fa''aila! Ya''ia andrö, sanofu khögu: Heza so Yehowa, Lowalangimö andrö? Wa''omasi hörögu dania wamaigi-maigi ya''ia. Ba tehundra-hundra dania ia, timba dambu baewali.[7]', '["Yer 50:34","Yoel 2:17"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 11, 'Irugi baŵa dania, ba la''a''azökhi gölimö; na luo da''ö, ba aröu to''ese misa nolamö andrö.[8]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 12, 'Na luo da''ö, ba la''ondrasi''ö si oroi danö Ndrawa Asiria, irugi danö Miserayi, ba i''otarai zui danö Asiria, numalö ba mboto Oifarati, ba i''otarai nasi si sambua, numalö ba zi sambua, ba hili si sambua, numalö ba zi sambua, la''otarai sangondra.[9]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 13, 'Ba tobali tanö si mate guli danö, börö zowanua yaŵa, bua-buara andrö.[10]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 14, 'Kubaloi mbanuamö andrö si''ou, timba mbiri-biri, okhötamö, ena''ö ba zi lö niha-niha monahia ira, ba gatua, yaŵa ba hili Garemeli. Akha ba Mbazana ba ba danö Gileadi la''alui göra, si mane ba götö föna.[11]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 15, 'Fa''ila''ö khöra zahöli-höli dödö, si mane me luo la''otarai danö Miserayi.', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 16, 'Akha la''ila niha baero, ba akha aboto ba dödöra, wa no si lö boto wa''abölöra andrö; hana na la''okhö dania mbawara ba hana na afiso ira.[12]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 17, 'Lafelai gawu-gawu dania, si mane ulö; si mane sanana ba danö tou; laheta ira ba mbini-mbini andrö khöra, manizi-nizi, ata''u ira, ba lanehegö Lowalangida Yehowa ba la''ata''ufi ia![13]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 18, 'Heza so Lowalangi si mane ya''ugö, same''e aefa horö ba zi tosai tana khönia, ba sangosilömilagö olalöŵa; si tenga si fadoro mofönu, somasi a''i wamatörö fa''ahakhö dödö.[14]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 19, 'Ifuli dania ihakhösi tödö ita, ba ihöndrögö tou golalöŵada andrö. Horöma andrö, ba ötibo''ö ba namö ba nasi![15]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476477, 'OT', 'Mikha', 7, 20, 'Si lö faröi ndra''ugö khö Yakobo ba öhakhösi tödö Gaberahamo, nifabu''umö khö ndra tuama, ba götö föna sa''ae, we''amöi ba hölu khöra.[16]', '["Sin 72:8; Amos 9:11; Sakh 9:10","Yes 19:23","Yer 21:14","MozIV 23:9; Sin 23; Yer 50:19","Yob 21:5","Sin 18:46; 72:9; Yes 49:23","MozII 34:6; Yes 57:16; Yer 3:5","MozI 3:15","Luk 1:73"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 1, 'Nitandrösaigö ba mbanua Niniwe. Sura wama''ele''ö andrö khö Nakhumi andrö, banua Gelikosi.[1]', '["Yes 10:3; Hez 31:3 b.t."]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 2, 'Lowalangi solohu ba solau balö Yehowa; solau balö Yehowa ba si no fahöna fönu. Solau balö ba zi fa''udu khönia Yehowa, lö aefa wönunia khöra.[2]', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 3, 'Lö alio-lio mofönu Yehowa, ba no sabölö sibai ia, ba lö zi lö ibe''e wotu. Si fao ba nangi sabölö ba ba mbanua Yehowa, ba no gawu-gawu barö gahenia lawuo.[3]', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 4, 'Itenaŵa nasi, i''ogo''öisi, ba otufo nungo nidanö fefu, ibe''e. Aleu zinanö ba Mbazana ba ba hili Garemeli; ba ba hili Libano, ba aleu mbowo.', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 5, 'Humeu hili, fönania, ba hili-hili, ba alau; maöga danö fönania, uli danö, fabaya sowanua yaŵa.[4]', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 6, 'Ha niha zanaha fa''abao dödönia andrö ba ha niha zabe''e ba wönunia andrö, sihola-hola? Timba galitö na itörö fönunia andrö, ba fabali fönania gara ba hili.', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 7, 'Sebua tödö Yehowa, ba''a-ba''a ia, na baŵa wa''abu dödö; aboto ba dödönia zanaŵa ya''ia.[5]', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 8, 'Ba timba nitörö molö, na ifakiko zolaŵa ya''ia, ba sogömi-gömi zolohi si fa''udu khönia.', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 9, 'He wisa dödömi ba khö Yehowa, Ifakiko [ami] — lö ifomendrua famakao!', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 10, 'Timba za''a-sa''a mao, si no fakhai, ba si no mabu nibadura andrö, i''a ira alitö, si mane töla wakhe, si no oköli sibai.', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 11, 'Khömi mege i''otarai si so era-era si lö sökhi ba khö Yehowa, samakhai famakiko.[6]', '["MozII 20:5; Sin 94:1","MozII 34:6","MozII 19:18; Sin 18:8; 97:5","Sin 1:6","Yes 36"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 12, 'Da''ö niŵa''ö Yehowa: He na laŵa''ö tödöra, sabölö ira ba ato ira, ba nihori zui ira, saheta ira. Na no uhöndrögö ndra''ugö, ba lö ufuli uhöndrögö''ö zamuza tö.', '["Yes 37:38; Dan 5:27"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 13, 'Ba urasa sa''ae galo mbagi andrö khönia, ba mbagiu, ba u''etu''ö wesumö andrö.', '["Yes 37:38; Dan 5:27"]', NULL),
  (3476491, 'OT', 'Nakhumi', 1, 14, 'Ba ba khömö andrö, ba ibe''e li Yehowa: si taya sa''ae döimö, lö nga''ötö. Ba ba gosali Lowalangimö andrö, ba uhori nadu nifofoe ba adu nifahele, ba u''asiwai sa''ae lewatömö, me nitibo''ö ndra''ugö.[7]', '["Yes 37:38; Dan 5:27"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476492, 'OT', 'Nakhumi', 2, 1, 'Hiza moroi sa ba hili zangombakha turia somuso dödö, wa lö fanuwö sa''ae. Milau gowasa khömi, ya''ami mado Yuda, mitörö nifabu''umi andrö, lö''ö sa''ae latörö ami samakiko andrö, no mu hori ira, lö si tosai.[1]', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 2, 'So moroi sa khömi zanudugö! Midaro-darogö hatimi andrö! Böi aefa-aefa ba lala hörömi! Mi''abe''e''ö dödömi, mihaogö wama''anö ya''ami!', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 3, 'Ifuli i''a''azökhi wa''asalaŵa ma''uwu Yakobo Yehowa, ba he fa''asalaŵa Ndraono Gizeraeli; noa sa larabu si faraburabu andrö, no lafufu lewiö.[2]', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 4, 'No oyo mbaluse zabölö andrö khönia, baru luo mbaru zi möi fasuwö andrö; hulö galitö wa''atakile zi''öli andrö ba gureta, na ifa''anö, ba lafangaha doho.', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 5, 'Murara gureta ba newali, ladörö-döröi golayama; hulö zulu, wamaigida, timba gari mbanua, na latörö.', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 6, 'Itörö tödönia zalaŵa andrö khönia: alau-lau ira ba lala, si fulöi ira, lasaŵa göli mbanua — ba lafazökhi sa''ae mba''a-ba''a.', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 7, 'Ba labokai sa''ae mbawa göli ba nidanö, ba si taya gödo.', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 8, 'Ba no muhonogöi: ni''oloi''ö ia, ni''ohe misi yaŵa, ba mangarö-ngarö genoninia ono alawe, hulö li marafadi lira, ba labözi dötö''ara.', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 9, 'No timba mbaŵa nidanö Niniwe, i''otarai föna, sa''ae, ba moloi zui ira. "Mibadugö ami! Mibadugö ami!" — ba samösa lö samali''ö ya''ia furi.[3]', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 10, 'Mihalö wirö, mihalö gana''a! Me no si fahöna girö-girö; no oya sibai ngawalö gama-gama sebua böli.', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 11, 'Tobali si lö''ö sa''ae, si lö ösi sa''ae, no adudula, ba tödö si no atalö ba balöduhi sanizi-nizi, ba dozi sola, ba akandro, ba dozi bawa, ba afusi![4]', '["Yes 52:7; Rom 10:15; RazI 22:19 b.t.","Yes 10:12","Yon 4:11","Yes 13:7; Yoel 2:6"]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 12, 'Heza so nahia zingo andrö, naha andrö ba ni''e''ebua ono zingo, nidörö-dörö zingo si matua ba singo si alawe ba ono zingo, lö si keani ya''ira?[5]', '["Hez 19:2 b.t."]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 13, 'Mondra''undra''u mege zingo, irege abönö ö nononia, ba mange''enge''e, ö zi alawenia; ihöna gahuluania ba nahiania tögi narö gara, ba ondra''uania ba wörömania.', '["Hez 19:2 b.t."]', NULL),
  (3476492, 'OT', 'Nakhumi', 2, 14, 'Hiza, ulau khöu! iŵa''ö Yehowa ngahönö, ba utunu ba galitö gureta khöu, ba ö mbawa zi''öli nono zingo andrö khöu. Ba uhori ba danö gondra''uamö andrö, ba lö''ö sa''ae terongo li zinengemö!', '["Hez 19:2 b.t."]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 1, 'Alai mbanua sange''enge''e andrö, si no fahöna falimosa ba famakaora awöra, si lö mamöhöli famara''u.[1]', '["Hez 24:9","Fam 17:1 b.t.; 18:1 b.t.","Yer 13:26"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 2, 'Tarongo sa''ae li mbözi-bözi kudo! Tarongo werara gaolo gureta, awö kudo si mandruo, awö weruru gureta, ba si fakudo, si so moroi sa,', '["Hez 24:9","Fam 17:1 b.t.; 18:1 b.t.","Yer 13:26"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 3, 'ba si''öli ba toho, oi takile! No ato tou nibunu, no fahöna manö mboto zi mate, no fadoro manö tou, tobali alau ita, tatendre mboto zi mate andrö.', '["Hez 24:9","Fam 17:1 b.t.; 18:1 b.t.","Yer 13:26"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 4, 'Ba wa''asese horö ndra alawe sohorö andrö, ira alawe omasiö andrö, si no to''ölö ba wakelemusa, si no mamowöhö soi niha ba wohorönia andrö, ba samaelungu niha — ha soi ira — ba wakelemusania.[2]', '["Hez 24:9","Fam 17:1 b.t.; 18:1 b.t.","Yer 13:26"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 5, 'Ba hiza, ba ulau khöu! iŵa''ö Yehowa ngahönö, ba ufahoi gu''imö, föna, ba u''oroma''ö ba niha zi lö balu-balu khöu, ufa''ele''ö ba gamatöröŵa niha zaila''ö.[3]', '["Hez 24:9","Fam 17:1 b.t.; 18:1 b.t.","Yer 13:26"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 6, 'Ba uhawui ndra''ugö sogoro ita, ba aila''ö ube''e, ubali''ö fama''iki niha ndra''ugö,', '["Hez 24:9","Fam 17:1 b.t.; 18:1 b.t.","Yer 13:26"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 7, 'ena''ö moloi dozi sangila ya''ugö, ba ena''ö lamane: No mududugö Niniwe! Ha niha zahakhö tödö ya''ira? Heza usöndra zondrara tödömi?', '["Hez 24:9","Fam 17:1 b.t.; 18:1 b.t.","Yer 13:26"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 8, 'Hadia, sökhi ami, moroi ba No Amoni andrö, ba mbewe Nilo, si no tefasui idanö, si so ba''a-ba''a asi ba öli idanö?', '["Yer 25:15","Yes 19:16","Yer 51:14"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 9, 'Fangabölöra Ndrawa Gaitiofia ba Dawa Miserayi, si lö mutaha mu''erai, ba awöra na Ndrawa Wuti ba Dawa Libia.', '["Yer 25:15","Yes 19:16","Yer 51:14"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 10, 'Ba no ni''oloi''ö göi ira, ni''osawuyu; ba ono sawuyu khöra ba no murasa ba watalinga newali fefu. Salaŵara, ba nilau dahö-dahö, ba sebuara fefu, ba niböbö.', '["Yer 25:15","Yes 19:16","Yer 51:14"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 11, 'Ba ya''ami göi, ba si mabu dania, si so ba zogömi-gömi, sangalui saŵatö föna nemali ami göi![4]', '["Yer 25:15","Yes 19:16","Yer 51:14"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 12, 'Hati andrö khömi fefu, ba no timba döla ara, si so bua sahulö; na lafadögö, ba atoru mbua, göna ba mbawa zi manga ya''ia.', '["Yer 25:15","Yes 19:16","Yer 51:14"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 13, 'Hiza, sabölö andrö ba khömi, ba no tobali ira alawe — teboka manö mbawa göli ba danömi, alitö zi manga lazi khömi![5]', '["Yer 25:15","Yes 19:16","Yer 51:14"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 14, 'Mita''u khömi nidanö, soguna na lasuwö ami! Mi''a''aro''ö hatimi! Mihundra-hundra lömbu za''ua, mitutu la''uri, mituyu golabuta gara tembo!', '["Yer 25:15","Yes 19:16","Yer 51:14"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 15, 'Ba da''ö i''a ami alitö, ahori ami ba mbawa zi''öli, timba wemanga larewe, he oya sibai ami ua, si mane fali.[6]', '["Yer 25:15","Yes 19:16","Yer 51:14"]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 16, 'No oya moroi ba ndröfi ba mbanua si yaŵa zaniaga andrö khöu, ba latörö föla andrö, ba humombo misa.', '[]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 17, 'No timba larewe zalaŵami, ba kumandra andrö khömi, ba no timba damo, si mörö-mörö ba zinga göli kara, na oafu ira, ba na tumbu luo, ba moloi ira, ba lö sangila, heza lasaŵa.', '[]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 18, 'Kubalo andrö khöu, ya''ugö razo Asiria, ba manuköu, ba salaŵa andrö khöu, ba no mörö-mörö tou; banuau, ba no muzaewe ba hili misa, lö sangowuloi ya''ira!', '[]', NULL),
  (3476494, 'OT', 'Nakhumi', 3, 19, 'Lö fangokafu wökhöu andrö, ba lö famadöho zokhou. Dozi samondrongo turiamö, ba lalau datawo, ba khömö andrö; ha niha na sa, zi lö öfakao mege, si lö mamalö-malö?', '[]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 1, 'Taroma li, nitema Habakuki sama''ele''ö andrö.[1]', '["Yes 13:1"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 2, 'Ha wa''ara sa''ae u''andrö tolo khöu, ya''ugö Yehowa, ba lö öfondrondrongo; ha wa''ara sa''ae mu''aodo khöu: "Famakao!" ba lö''ö sa ötolo!', '[]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 3, 'Hana wa öfa''ila''ö khögu zi lö sökhi, ba öfaigi-faigi manö göi wamakao niha awöra? Famalangögö ba famakao zi so ba duduma hörögu; andrö wa no tumbu wasosota, ba soso manö zui wagua-guasa.', '[]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 4, 'Andrö wa alulu wolohe ba lala hadia ia, ba satulö ba lö''ö manö oroma sa''ae. Lafa''u''u sa''ae zatulö sebua horö andrö, andrö wa fafuyu huku, na alua.', '[]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 5, 'Mifaöga mbawami, ya''ami si no faröi, mifakhölö ami! Ya atöngö ami ba ya tobali dödömi! Nilaunia ba götömi andrö, ba lö faduhu dödömi, na nitunö khömi ena''ö![2]', '["Yes 28:21; HalZin 13:41","Yer 5:15","Yer 4:13; 5:6; MozI 28:49; Mat 24:28","Hez 28:2"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 6, 'Hiza sa, u''asogö Ndrawa Galedaia andrö, soi safaito ba salio ahe, sanöröi bolo guli danö, ba wangokhögö nahia niha bö''ö.[3]', '["Yes 28:21; HalZin 13:41","Yer 5:15","Yer 4:13; 5:6; MozI 28:49; Mat 24:28","Hez 28:2"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 7, 'Sihokha mbuda ba sata''u ita ira. Ba khöra manö tumbu huku andrö khöra ba fa''asalaŵara.', '["Yes 28:21; HalZin 13:41","Yer 5:15","Yer 4:13; 5:6; MozI 28:49; Mat 24:28","Hez 28:2"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 8, 'Kudo khöra, ba no alio moroi ba harimo ba afaito moroi ba nasu gatua, na bongi; si fakudo andrö khöra, ba lafandruo kudora, sebua hokha ira, ba zaröu la''otarai, sihombo ira, timba moyo sondra''u gönia.[4]', '["Yes 28:21; HalZin 13:41","Yer 5:15","Yer 4:13; 5:6; MozI 28:49; Mat 24:28","Hez 28:2"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 9, 'Dozi ira, ba famakao awöra lafa''ua, atumbukha luo la''otahögö; lahöna niha ni''oloi''ö, timba ngawua nene wa''oya.', '["Yes 28:21; HalZin 13:41","Yer 5:15","Yer 4:13; 5:6; MozI 28:49; Mat 24:28","Hez 28:2"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 10, 'Ba ya''ia — ba i''igi''igi''ö razo, ba tandrösa wango''ayania zalaŵa. Ma''iki ia ba hati andrö, fefu, ilau fari tanö, ba atu''a ia dania.', '["Yes 28:21; HalZin 13:41","Yer 5:15","Yer 4:13; 5:6; MozI 28:49; Mat 24:28","Hez 28:2"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 11, 'Ba ilau angi sabölö, itörö, ba mosala ia, ya''ia andrö, same''e Lowalangi fa''abölönia.[5]', '["Yes 28:21; HalZin 13:41","Yer 5:15","Yer 4:13; 5:6; MozI 28:49; Mat 24:28","Hez 28:2"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 12, 'Hadia, tenga Lowalangigu ndra''ugö, i''otarai götö föna sibai sa''ae, hadia, tenga ni''amoni''ö khögu ndra''ugö, ya''ugö, si lö''ö manö mate? He Yehowa, ba wamatörö huku öhonogöi ia, ba no öfataro same''e fotu ia —[6]', '["Yes 10:5","Sin 5:5"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 13, 'ya''ugö andrö, si so hörö satulö, fa tebai öfaigi-faigi zi lö sökhi, ba tebai anehe ndra''ugö wamakao niha awöra — ba hana wa öfaigi-faigi zi faröi andrö, ba hana wa lö hede-hedeu, na ifakiko sebua horö zi lö horö khönia?[7]', '["Yes 10:5","Sin 5:5"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 14, 'Noa sa tobali timba gi''a ba nasi niha öbe''e, timba guökuö si lö sokhö.', '["Yes 10:5","Sin 5:5"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 15, 'Ya''ira fefu, ba no igaini, idöni misa ba waurunia, ba ifa''u''u ba giri. Andrö wa omuso dödönia ba owua-wua dödö:', '["Yes 10:5","Sin 5:5"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 16, 'andrö wa itaba zumange waurunia ba ifosumange göi girinia. Me ba da''ö isöndra gondra''ua sebua ba ö satabö.', '["Yes 10:5","Sin 5:5"]', NULL),
  (3476495, 'OT', 'Habakuki', 1, 17, 'Andrö wa lö aetu idöni zi''öli ba ibunubunu soi bö''ö lö fa''ahakhö dödö.', '["Yes 10:5","Sin 5:5"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 1, 'Damöido ba naha wanaro khögu, möido ba hati andrö, ba wamaigi-maigi, ena''ö urongo hadia huhuonia khögu, ba hadia niŵa''önia khögu, ba wangadugu andrö.[1]', '["Yes 21:8; Hez 33:7","Yes 30:8; Fam 1:19","Heb 10:37; FetII 3:9","Yob 3:36; Rom 1:17; Gal 3:11; Heb 10:38"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 2, 'Ba itema ligu Yehowa, imane khögu: Tanö ba zura gangilata andrö, haogö wanua ba gara wanura, ena''ö lö afökhö wombaso ya''ia.[2]', '["Yes 21:8; Hez 33:7","Yes 30:8; Fam 1:19","Heb 10:37; FetII 3:9","Yob 3:36; Rom 1:17; Gal 3:11; Heb 10:38"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 3, 'Mogasa na sa wa''alua gangilata andrö, ba aösö ia ba wa''alua, ba no tenga faya. Na mogasa ia, ba döna-döna manö; lö''ö sa zi lö itörö, lö zi lö alua![3]', '["Yes 21:8; Hez 33:7","Yes 30:8; Fam 1:19","Heb 10:37; FetII 3:9","Yob 3:36; Rom 1:17; Gal 3:11; Heb 10:38"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 4, 'Hiza, no si so hokha dödönia, lö bakha tödö sadölö; ba satulö tödö, ba ba wamatinia auri ia.[4]', '["Yes 21:8; Hez 33:7","Yes 30:8; Fam 1:19","Heb 10:37; FetII 3:9","Yob 3:36; Rom 1:17; Gal 3:11; Heb 10:38"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 5, 'Ba baero ö na, ba no famowöhö nagu andrö; ba si lö boto niha si fayaŵa, samokai bawania, timba narako, ba si no timba wa''amate, ba wa''atebai abuso, si no mondrönisi khönia niha baero, fefu, ba sangowuloi khönia dozi soi.[5]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 6, 'Ba hadia, lö la''o''aya dania ia da''ö fefu, lö lafatou ia, ba lö labe''e amaedola? Lamane dania: Alai zangöhöna ana''a mbö''ö — ha wa''ara maö? — ba sangai noronia nihalö gade.', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 7, 'Hadia, lö i''ogomuzaö maoso dania zosugilö khöu, ba lö i''ozumagö tokea zamakao ya''ugö? Ba ahuluara ndra''ugö!', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 8, 'Si mane ya''ugö sa, me no oya soi niraburabumö si so khöra, si manö göi laraburabu dania zi so khöu soi si tosai andrö, börö ndro niha andrö, si no aduwa, ba famakaomö tanö ba banua ba ösi mbanua.[6]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 9, 'Alai zangalui ana''a si lö atulö, ni''okhögö, ba wame''e, ba zalaŵa yaŵa azuninia, ba wangefa''ö ya''ia ba wa''abölö wamakiko![7]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 10, 'Fangailami, ya''ami si samba omo, dödöu andrö, ba wangohori soi soya; famakiko nosou ö''alui.', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 11, 'Mu''ao sa''ae dania gara toyo gehomo ba itema linia buatö yaŵa ba mbulu.[8]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 12, 'Alai zame''e fanaru''ö banua sebua fange''e, ba fanaru''ö banua side-ide horö![9]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 13, 'Hadia, tenga soroi khö Yehowa ngahönö zi manö? Mohalö-halöŵö soi niha, ba ba galitö lua-lua, ba erege dödö niha, ba si lö boto![10]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 14, 'Anönö sa dania danö fa''aboto ba dödö lakhömi Yehowa, timba nasi, balu-balu doyonia tanö.[11]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 15, 'Alai zamabadugö ba nawönia nifaruka si mabu niha, ena''ö mabu ira, ba ena''ö oroma zaila ira![12]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 16, 'Fangabusou mege, ba fa''aila, ba tenga fangebua döi: ba badu iya''e, ya''ugö göi, ba oroma''ö mbotolö khöu! Irugi sa''ae ndra''ugö mako andrö ba danga Yehowa kambölö, ba ikhamö''ö fa''aila sebua, salahi lakhömi.[13]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 17, 'Ilaugö sa dania ndra''ugö famarukhumö mege, ba hili Libano, ba humokha mbumö ibe''e famunumunumö utu ndru''u andrö, börö ndro niha andrö, si no aduwa ba famakaomö tanö ba banua ba ösi mbanua.[14]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 18, 'Hadia guna nadu nifofoe andrö, wa ifofoe mege tukania? Ba hadia guna nadu nifahele ba si faeta sofaya, wa no abe''e dödö dukania khönia, fa ifazökhi Lowalangi si lö hede?[15]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 19, 'Alai zanguma''ö ba geu: Faoso! Ba sanguma''ö ba gara sabe''e: Aliŵa-liŵa! Hadia, ifahaö niha? Hiza, no lafosinga ia ana''a ba firö, ba lö bakha noso.', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476496, 'OT', 'Habakuki', 2, 20, 'Ba Yehowa, ba no so ba gosali andrö khönia; ba yamuhonogö ia fönania uli danö ma''asagörö![16]', '["Amaed 30:16; Yes 5:14; Dan 5:1","Yes 33:8","Yes 22:13","Luk 19:40","Hez 24:9","Yer 51:58","Yes 11:9","Yer 25:15 b.t.","Yer 25:26","Yes 14:8; 37:24","Yer 10:8","Sin 11:4; Sef 1:7"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 1, 'Fangandrö Habakuki sama''ele''ö, dali wa''ala-alaisa andrö.[1]', '["Sin 7:1"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 2, 'He Yehowa, no urongo duria andrö khöu, ba ata''u sibai ndra''odo! He Yehowa, falua nilaumö andrö, barö ndröfi andrö, barö ndröfi andrö fa''ele''ö ia! Na mofönu ndra''ugö, ba böi olifugö''ö wa''ahakhö dödö.[2]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 3, 'So moroi sa Lowalangi, i''otarai Demana, ba hili Warana i''otarai Ni''amoni''ö andrö. Tobalu mbanua si yaŵa lakhöminia andrö, ba anönö danö turiania.[3]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 4, 'Mohaga, timba haga luo, moragi faoma fatambai, ba ba da''ö so mbalu-balu wa''abölönia.[4]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 5, 'Mowaö-waö fönania deu mbanua, ba itara lahenia fa''aukhu, fökhö waba.[5]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 6, 'Humeu danö, na ihundragö; ba na ifaöga mbawania, ba humufa soi niha. Ba fabali hili si lö tebulö andrö, ba ahöndrö hili si no arara. Lala ba götö föna sibai itörö![6]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 7, 'Tohare wamakiko ba nose Guzana u''ila; humeuheu goloso nose ba danö Ndrawa Midiano.', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 8, 'Hadia, ba mboto nidanö mofönu Yehowa, boto nidanö dandrösa wönunia? Hadia, asi ötahigö, wa fakudo ndra''ugö, na ötörö, wa ba gureta zabölö so''ö?[7]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 9, 'Lö''ö manö luniluni wanamö, no ödaö''ö-daö''ö wotu, no fahölu ndra''ugö. Mangumbu nidanö sebua moroi barö danö.[8]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 10, 'Na la''ila ndra''ugö hili, ba manizi-nizi ira; inönoi danö molö, ifarongogö we''ugu-ugunia asi: ifazaŵa dangania.[9]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 11, 'La''iagö manö nahiara luo ba baŵa, ba haga nono wana andrö khöu, sanörö, ba wa''atakile dohomö andrö.[10]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 12, 'Ba wa''abao dödö andrö ötöröi danö ba öfufu soi niha ba wönu.[11]', '["Rom 11:22","MozV 33:2; Sanguhuk 5:4","RazI 8:12","MozII 9:3; SamII 24:15","Sin 68:9","Sin 68:18; 114:3,5; Yes 66:15","MozI 7:11","Sin 114:4","Yos 10:13; Yes 13:10; Hez 32:7","Yes 25:10; 41:15"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 13, 'Ba wangorifi banuamö so ndra''ugö, ba wangorifi nibayoinimö andrö; öfazaumba tou mbumbu nomo zebua horö, öheta nöu dayadaya, irugi mbagi zilalöyaŵa.[12]', '["Sin 110:6","Sin 77:20","Yer 5:17; 18:13","SamII 22:34; Sin 18:34"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 14, 'Ötöla''ö toho högö zangoloi''ö ya''ira, na so ira, na fagohi ira, ba wamazaewe ya''aga; lahehegö, timba na la''a ena''ö zi numana ba mbini-mbini.', '["Sin 110:6","Sin 77:20","Yer 5:17; 18:13","SamII 22:34; Sin 18:34"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 15, 'Öfatörö ba nasi kudomö, ba ndrulu nasi andrö, sebua sibai.[13]', '["Sin 110:6","Sin 77:20","Yer 5:17; 18:13","SamII 22:34; Sin 18:34"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 16, 'Me urongo, ba humisi nösigu; ba duria andrö manizi-nizi mbewegu. No timba wa''obou döla ba nösigu, manizi-nizi ndra''o ba zi sodo, si lö hede-hede ndra''o, irugi mbaŵa wamakao, na so moroi sa zamakao banua [Ndraono Gizeraeli].', '["Sin 110:6","Sin 77:20","Yer 5:17; 18:13","SamII 22:34; Sin 18:34"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 17, 'Na lö mobowo ara ba na lö bua nagu, na si lö fakhai mbua zai ba na lö falukha gö ba danö na ambö biri-biri ba kandra ba na lö saŵi ba kandrara[14] —', '["Sin 110:6","Sin 77:20","Yer 5:17; 18:13","SamII 22:34; Sin 18:34"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 18, 'ba ya''odo, ba somuso tödö zui ndra''odo ba khö Yehowa, owua-wua dödögu khö Lowalangi sangorifi ya''o![15]', '["Sin 110:6","Sin 77:20","Yer 5:17; 18:13","SamII 22:34; Sin 18:34"]', NULL),
  (3476497, 'OT', 'Habakuki', 3, 19, 'Fa''abölögu Yehowa, So''aya! Timba gahe mböhö gahegu ibe''e, ba ba zalaŵa yaŵa ifatörödo. — Khö duka wanunö; nilau biola nitika.', '["Sin 110:6","Sin 77:20","Yer 5:17; 18:13","SamII 22:34; Sin 18:34"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 1, 'Taroma li Yehowa, khö Zefania andrö, ono Gedalia ono Gamaria ono Hisikia, me luo razo mado Yuda Yosia, ono Gamoni.[1]', '["RazII 22:1"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 2, 'Ufarahugö wanibo fefu hadia ia ba guli danö! iŵa''ö Yehowa.', '["Hos 4:3; Mat 13:41","RazII 23:5; Yer 19:13; Hez 14:4","Amos 5:26","Yes 1:4; Yer 15:6"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 3, 'Uhori niha, fabaya urifö niha, uhori wofo ba dalu mbanua ba i''a ba nasi, ba fangala andrö, fabaya sebua horö, uhori niha ba guli danö! iŵa''ö Yehowa.[2]', '["Hos 4:3; Mat 13:41","RazII 23:5; Yer 19:13; Hez 14:4","Amos 5:26","Yes 1:4; Yer 15:6"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 4, 'U''oro''ö dania dangagu yaŵa mado Yuda ba yaŵa mbanua Yeruzalema, ba uhori ba da''ö döi Mba''ali andrö ba töi gere nadu andrö, fabaya ere,[3]', '["Hos 4:3; Mat 13:41","RazII 23:5; Yer 19:13; Hez 14:4","Amos 5:26","Yes 1:4; Yer 15:6"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 5, 'awö fefu zangalulu ba ngahönö ba mbanua si yaŵa, ba dete nomora yaŵa, awö zangalulu andrö, si möi ba hölu ba khö Yehowa ba same''e hölu göi Milikomo andrö,[4]', '["Hos 4:3; Mat 13:41","RazII 23:5; Yer 19:13; Hez 14:4","Amos 5:26","Yes 1:4; Yer 15:6"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 6, 'awö zi no mangerogö Yehowa, si lö mangalui ya''ia, si lö manofu ya''ia![5]', '["Hos 4:3; Mat 13:41","RazII 23:5; Yer 19:13; Hez 14:4","Amos 5:26","Yes 1:4; Yer 15:6"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 7, 'Böi mihede-hede föna Yehowa, So''aya! Me no ahatö mbaŵa andrö khö Yehowa; no i''asiwai zumange Yehowa, no i''amoni''ö nikaoninia andrö.[6]', '["Yes 34:6; Yer 46:10; Hab 2:20","RazII 25:7","SamI 5:5","RazII 22:14","Sin 94:7","MozV 28:30,39; Amos 5:11"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 8, 'Ba na baŵa wame''e sumange andrö khö Yehowa, ba u''otu''ö zalaŵa, awö nono razo, awö dozi sonukha nukha Ndrawa.[7]', '["Yes 34:6; Yer 46:10; Hab 2:20","RazII 25:7","SamI 5:5","RazII 22:14","Sin 94:7","MozV 28:30,39; Amos 5:11"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 9, 'Na luo da''ö, ba udozigö u''otu''ö sanawö toyo mbawandruhö, sangöhöna famakao awöra ba falimosa, ba nomo Zo''aya ya''ira.[8]', '["Yes 34:6; Yer 46:10; Hab 2:20","RazII 25:7","SamI 5:5","RazII 22:14","Sin 94:7","MozV 28:30,39; Amos 5:11"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 10, 'Na luo da''ö dania — iŵa''ö Yehowa — ba so we''ira-ira, i''otarai mbawa göli gi''a, ba fege-ege si otarai zi mamatonga mbanua, ba fangarö-ngarö sabölö-bölö si otarai hili-hili.[9]', '["Yes 34:6; Yer 46:10; Hab 2:20","RazII 25:7","SamI 5:5","RazII 22:14","Sin 94:7","MozV 28:30,39; Amos 5:11"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 11, 'Mi''ege-ege, ya''ami si so omo ba "lösu", me no ahori tekiko zaniaga andrö, ba me no muhori zolu''i-lu''i ana''a.', '["Yes 34:6; Yer 46:10; Hab 2:20","RazII 25:7","SamI 5:5","RazII 22:14","Sin 94:7","MozV 28:30,39; Amos 5:11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476498, 'OT', 'Sefania', 1, 12, 'Ba na luo da''ö, ba u''ohe zulu, wamaigi-maigi ba Yeruzalema, ba u''otu''ö ira, si no abe''e manö ba wöröwörö andrö khöra, ba sanguma''ö tödöra: "Yehowa andrö, ba tebai ibe''e zalöfö, ba tebai göi ibe''e te''ala ita!"[10]', '["Yes 34:6; Yer 46:10; Hab 2:20","RazII 25:7","SamI 5:5","RazII 22:14","Sin 94:7","MozV 28:30,39; Amos 5:11"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 13, 'Ba nirabu dania zi so khöra, ba omora, ba sadudu: ba na molau omo ira, ba lö la''onahia, ba na lafazökhi kabu nagu, ba lö''ö zui labadu nösi mbua![11]', '["Yes 34:6; Yer 46:10; Hab 2:20","RazII 25:7","SamI 5:5","RazII 22:14","Sin 94:7","MozV 28:30,39; Amos 5:11"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 14, 'No ahatö mbaŵa sebua andrö khö Yehowa; no ahatö ia, ba alio sibai irugi. Mifondrondrongo? no baŵa andrö khö Yehowa! Mu''ao mege-ege zabölö andrö.', '["Yer 30:7; Amos 5:18","Hez 7:19; Sef 3:8"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 15, 'Baŵa wönu mbaŵa andrö ba baŵa wa''ata''u ba baŵa wa''atosasa, baŵa wa''adudu ba baŵa wa''afufu, baŵa zi bongi ba baŵa wa''ogömi-gömi, baŵa lawuo ba baŵa wa''alu;[12]', '["Yer 30:7; Amos 5:18","Hez 7:19; Sef 3:8"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 16, 'baŵa wolau torofe ba baŵa wangekhugö niha, ba wanuwö banua saro, awö watalinga göli andrö si no alaŵa.', '["Yer 30:7; Amos 5:18","Hez 7:19; Sef 3:8"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 17, 'Ba ufeta''u niha, ena''ö timba zi lö hörö ira wowaö-waö, me no molalö ira khö Yehowa. Ba aduwa dania ndrora, timba gawu-gawu, ba betu''ara, timba zöi.', '["Yer 30:7; Amos 5:18","Hez 7:19; Sef 3:8"]', NULL),
  (3476498, 'OT', 'Sefania', 1, 18, 'Tebai möi fangorifira wiröra, ba he ana''ara, na baŵa wönu Yehowa andrö, ahori dania i''a danö alitö wönunia andrö. Ihori manö sa dania zowanua ba guli danö fefu, lö mudöna-döna.[13]', '["Yer 30:7; Amos 5:18","Hez 7:19; Sef 3:8"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 1, 'Mi''ide-ide''ö ami, ba tou manö mi''iagö, ya''ami, banua si lö fa''aila,', '["Sin 1:4; 35:5; Yob 21:18","Yoel 2:14; Amos 5:15; Yon 3:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 2, 'fatua tenga na amaedola ndrami wakhe ami, sihombo ba nangi, fatua lö''ö na itörö ami alitö wönu Yehowa andrö; fatua lö ikhamö ami baŵa wönu Yehowa?[1]', '["Sin 1:4; 35:5; Yob 21:18","Yoel 2:14; Amos 5:15; Yon 3:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 3, 'Mi''alui Yehowa, ya''ami fefu, si lö fayaŵasa, ba danö, ya''ami solau satulö andrö khönia! Fa''atulö dödö mifa''ua, ba fa lö fayaŵa mi''alui: ma atö te''orifi ami, na baŵa wönu Yehowa andrö![2]', '["Sin 1:4; 35:5; Yob 21:18","Yoel 2:14; Amos 5:15; Yon 3:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 4, 'Si lö niha sa dania Gasa ba tanö si mate Gasikalo. Ba banua Gasoto, ba soloi ba zi laluo, nifeta''u, ba Ekerona, ba nidudugö, nifaulugö.[3]', '["Yer 47:4","SamI 30:14","Yer 48:29; Hez 25:8","Sin 107:34; Yer 17:6","Yes 60:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 5, 'Alai ami, ya''ami sihene asi, ya''ami Dawa Gereta! Khömi tetandrösaigö li Yehowa, ya''ugö tanö Gana''ana, tanö Ndrawa Wilisiti! Ufakiko ndra''ugö, uhori niha![4]', '["Yer 47:4","SamI 30:14","Yer 48:29; Hez 25:8","Sin 107:34; Yer 17:6","Yes 60:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 6, 'Ba tobali benua awuyu ndraso nasi andrö, tobali nahia gubalo ba nahia kandra mbiri-biri.', '["Yer 47:4","SamI 30:14","Yer 48:29; Hez 25:8","Sin 107:34; Yer 17:6","Yes 60:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 7, 'Ba ba zi tosai ma''uwu Yuda möi dania ndraso nasi andrö: ya''ira zokubaloi guriföra ba da''ö; ba nomo ba Gasikalo mörö ira na bongi; möi sa dania mamaigi ya''ira Lowalangira Yehowa, ba ifolala dödöra.', '["Yer 47:4","SamI 30:14","Yer 48:29; Hez 25:8","Sin 107:34; Yer 17:6","Yes 60:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 8, 'No urongo wango''aya Ndraono Moabi ba fanandraŵa Ndraono Gamoni, me la''o''aya mbanuagu ba me lafadöni khöra danöra.[5]', '["Yer 47:4","SamI 30:14","Yer 48:29; Hez 25:8","Sin 107:34; Yer 17:6","Yes 60:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 9, 'Andrö, faya wa no sauri ndra''odo — iŵa''ö Yehowa ngahönö, Lowalangi Ndraono Gizeraeli, — na lö itörö dania Ndraono Moabi si göna Zodoma no ba na lö itörö Ndraono Gamoni si göna Gomora; benua sabölö lato dania ba da''ö, ba ladu ba tanö si mate, si lö mamalö-malö: si tosai mbanuagu dania zangai si so khöra, si tosai mbanuagu zanema ondröitara.[6]', '["Yer 47:4","SamI 30:14","Yer 48:29; Hez 25:8","Sin 107:34; Yer 17:6","Yes 60:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 10, 'Börö wayaŵasara andrö, wa itörö ira da''ö, me no mango''aya ira ba me no lafakao mbanua Yehowa ngahönö.', '["Yer 47:4","SamI 30:14","Yer 48:29; Hez 25:8","Sin 107:34; Yer 17:6","Yes 60:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 11, 'Ifeta''u dania ira Yehowa, ariri sa dania Lowalangi ba guli danö fefu, ibe''e, ena''ö mangalulu khönia hulo niha baero fefu, i''otarai nahiania zamösana.[7]', '["Yer 47:4","SamI 30:14","Yer 48:29; Hez 25:8","Sin 107:34; Yer 17:6","Yes 60:9"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 12, 'Ba ya''ami göi, ya''ami Dawa Gaitiofia, ba ba mbawa zi''öli khögu mate ami!', '["Nakh 1:4","Yes 13:21; 34:11","Yes 47:3"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 13, 'Ba i''oro''ö dania dangania miyöu ba ifakiko Ndrawa Asiria ba ibali''ö adudula Niniwe, soköliköli, si mane tanö si mate,[8]', '["Nakh 1:4","Yes 13:21; 34:11","Yes 47:3"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 14, 'ena''ö ba dalu naha mbanua mörö-mörö mbiri-biri nikubaloi ba utu ndru''u ba danö: tumbao ba borokoa zi mörö ba gadudula nomo, li wofo tarongo ba mbawa zandrela, adudula ba mbawandruhö; bagolö eresi andrö, ba sabo''a.[9]', '["Nakh 1:4","Yes 13:21; 34:11","Yes 47:3"]', NULL),
  (3476499, 'OT', 'Sefania', 2, 15, 'Hadia, da''ö mbanua sa''iki-iki andrö, somuso tödö, sidao-dao manö, lö hadia ia, sanguma''ö tödönia: Ya''odo, ba no tenga si manö mbanua bö''ö? Ha lö atobali börö wehokha mbu; no tobali nahia gutu ndru''u. Ha niha zanörö, ba fasi, ba ifangewe dangania.[10]', '["Nakh 1:4","Yes 13:21; 34:11","Yes 47:3"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 1, 'Alai mbanua andrö sabe''e tandro, si no ra''i-ra''iö, banua samakao awöra!', '["Hez 22:27; Hab 1:8","Yer 23:11; Hez 22:26; Hos 9:7","MozV 32:4; Yer 8:12","Faigi 1:16","Yer 6:8","Faigi 1:18"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 2, 'Lö lafondrondrongo goroisa ba lö ba dödöra wotu, lö manötöna khö Yehowa, ba lö la''ondrasi Lowalangira.', '["Hez 22:27; Hab 1:8","Yer 23:11; Hez 22:26; Hos 9:7","MozV 32:4; Yer 8:12","Faigi 1:16","Yer 6:8","Faigi 1:18"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 3, 'No timba zingo si ndröndröndröndrö zalaŵara, ba sanguhuku ba khöra, ba no timba nasu gatua, na bongi, lö lasaigö hadia ia irugi mahemolu mbanua.[1]', '["Hez 22:27; Hab 1:8","Yer 23:11; Hez 22:26; Hos 9:7","MozV 32:4; Yer 8:12","Faigi 1:16","Yer 6:8","Faigi 1:18"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 4, 'Sama''ele''ö andrö khöra, ba no si lö ngaroro, no niha si falimolimo; ere khöra, ba ra''i-ra''iö ni''amoni''ö labe''e, mosala ba goroisa ira.[2]', '["Hez 22:27; Hab 1:8","Yer 23:11; Hez 22:26; Hos 9:7","MozV 32:4; Yer 8:12","Faigi 1:16","Yer 6:8","Faigi 1:18"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 5, 'Ba no satulö Yehowa, ba khöra, lö ilau zi lö atulö; ero mahemolu ifa''ele''ö lala andrö khönia, lö italu''i, — ba ma''ifu lö i''ila aila niha si lö atulö![3]', '["Hez 22:27; Hab 1:8","Yer 23:11; Hez 22:26; Hos 9:7","MozV 32:4; Yer 8:12","Faigi 1:16","Yer 6:8","Faigi 1:18"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 6, 'No uhori niha baero; malige andrö khöra, ba no adudu; ba lala ba khöra, ba no lö niha ube''e, samösa lö sanörö: banuara, ba no adudu, si lö niha sa''ae, no ahori niha![4]', '["Hez 22:27; Hab 1:8","Yer 23:11; Hez 22:26; Hos 9:7","MozV 32:4; Yer 8:12","Faigi 1:16","Yer 6:8","Faigi 1:18"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 7, 'Ba no umane: "Ata''ufi manö ndra''o, o''ö wanegugu ya''ugö!" ba lö tehori nahiara, lö itörö niŵa''ögu nifatörö khöra, fefu. Ba si ndruhu, ba no lö atage ira ba wamahole fefu hadia ia nilaura![5]', '["Hez 22:27; Hab 1:8","Yer 23:11; Hez 22:26; Hos 9:7","MozV 32:4; Yer 8:12","Faigi 1:16","Yer 6:8","Faigi 1:18"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 8, 'Andrö midöna-döna manö khögu, iŵa''ö Yehowa, irugi luo maoso ndra''o sasi [udumi]. Me no huku khögu wangorudugö soi niha, fangowuloi amatöröŵa razo, ba wangahawui ya''ira fa''abao dödögu, alitö wönugu andrö fefu; i''a sa dania guli danö ma''asagörö alitö wönugu andrö.[6]', '["Hez 22:27; Hab 1:8","Yer 23:11; Hez 22:26; Hos 9:7","MozV 32:4; Yer 8:12","Faigi 1:16","Yer 6:8","Faigi 1:18"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 9, 'Ba ba da''ö dania u''asogö ba niha mbewe si sökhi, ena''ö dozi la''angaröfi li döi Yehowa, ba ena''ö te''anö manö ira we''amöi enoninia.', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 10, 'Yefo nidanö Gaitiofia lafosumange ndra''o sumange nitaba, ba sumange ni''a labe''e khögu.[7]', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 11, 'Ba na luo da''ö, ba lö''ö sa''ae aila ndra''ugö golalöŵau andrö fefu, si no molalö ndra''ugö khögu. Na luo da''ö, ba uheta ba khömi zi fayaŵa, sa''iki ba khömi, ba lö''ö sa''ae fayaŵa ndra''ugö ba hili andrö khögu ni''amoni''ö.[8]', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 12, 'Ba usaigö khömi niha si numana, si lö fayaŵasa; da''ö dania zame''e saŵatöra töi Yehowa.', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 13, 'Ba si tosai Iraono Gizeraeli andrö, ba lö''ö sa''ae molalö; lö''ö sa''ae molau faya ira, ba lö''ö sa''ae falukha lela si falimo, ba mbawara; mangalui göra ira ba mörö dania lö sikeani ya''ira[9]', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 14, 'A''iki, ya''ugö ono Ziona alawe, mi''owua-wua''ö dödömi, ya''ami Iraono Gizeraeli! Omusoi''ö dödöu, ba a''iki, moroi si''aikö ba dödöu, ya''ugö ono Yeruzalema alawe![10]', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 15, 'No iböda wangotu''ö ya''ugö Yehowa, no itimba nemalimö andrö! No so ba khömi razo Ndraono Gizeraeli andrö, Yehowa: lö''ö sa''ae itörö ndra''ugö si lö sökhi.', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 16, 'Ba na luo da''ö, ba lamane ba mbanua Yeruzalema: Böi mibusi dödömi! Böi adada dangami, ya''ami Siona!', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 17, 'No so ba khömi Lowalangimi Yehowa, sabölö; möna ami ibe''e. Omuso dödönia ndra''ugö, owua-wua dödö; lö hede-hedenia, ba wa''omasinia andrö; ma''iki ia, owua-wua dödönia ndra''ugö.', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 18, 'Sabu tödö andrö, me lö lakhamö gowasa, ba u''ozaragö, no iwami ira, ba no tohare wa''aila.', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 19, 'Ba na luo da''ö, ba ulau ba zamakao ya''ugö, fefu; ba u''orifi zi no mangohole''ö ya''ira ba u''ozaragö zi no muzaewe, ba ubali''ö fanuno ya''ira ba fangebua döira wa''ailara andrö, ba guli danö ma''asagörö.[11]', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476500, 'OT', 'Sefania', 3, 20, 'Na luo da''ö, ba u''ohe mangawuli ami, na luo u''ozaragö ami. Ubali''ö nisuno sa''ae ami ba sebua töi, ba niha ba guli danö fefu, na ufuli utolo ami, ba zanehe ami, iŵa''ö Yehowa.', '["Sin 68:32; Yes 18:1; 66:20","Hez 39:26","Mikh 7:14","Yes 12:6; 54:1; Sakh 9:9","Mikh 4:6"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 1, 'Me no töra döfi razo Dario, me fasulöna ba mbaŵa si önö, ba so niŵa''ö Yehowa, nifa''ema Haga''i, sama''ele''ö, khö Zerubabeli, ono Zelatieli, kumandru ba mado Yuda ba khö Yosua, ono Yosadaki, ere sebua, imane:[1]', '["Nga''ötI 3:17; Eser 4:24; 5:1,2"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 2, 'Da''ö niŵa''ö Yehowa ngahönö: Lamane niha andrö: Tenga na inötö wolau osali Yehowa andrö?', '[]', NULL),
  (3476501, 'OT', 'Hagai', 1, 3, 'Ba so niwa''ö Yehowa, nifa''ema Haga''i sama''ele''ö, imane.', '[]', NULL),
  (3476501, 'OT', 'Hagai', 1, 4, 'Ba hadia, ba no inötö khömi wangonahia omo, nihaogö bagolö, me no adudula nomo da''e?', '[]', NULL),
  (3476501, 'OT', 'Hagai', 1, 5, 'Ba iya''e, ba imane Yehowa ngahönö: Mifaigi ba, he wisa ba khömi!', '["MozIII 26:26; MozV 28:38; Mikh 6:14"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 6, 'No ebolo nowimi, ba lö ebua ni''ohe yomo: manga-manga ami, ba lö irugi ba wa''abuso, mibadu-badu hadia ia, ba tebai abuso ami, monukha ami, ba ambö ba wa lö o''afu, ba si manga gazi, ba ba mbola satöla ibe''e gazinia.[2]', '["MozIII 26:26; MozV 28:38; Mikh 6:14"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 7, 'Da''ö niŵa''ö Yehowa ngahönö: Mifaigi-faigi, he wisa ba khömi andrö!', '["MozIII 26:19; MozV 28:23","RazII 8:1"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 8, 'Mi''ae yaŵa ba hili, mihalö geu, ba milau gosali, ena''ö omasi ndra''o ba ena''ö ebua döigu! iŵa''ö Yehowa.', '["MozIII 26:19; MozV 28:23","RazII 8:1"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 9, 'No ebua midöna-döna ba no ide-ide lua-lua; no mi''ohe yomo, ba no uwuwusi. Hana wa si manö? iŵa''ö Yehowa ngahönö; börö nomogu andrö, me no adudula, ba me ba nomonia idölö ia zamösana, ba khömi andrö.', '["MozIII 26:19; MozV 28:23","RazII 8:1"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 10, 'Andrö wa lö ifalua khömi namo banua yaŵa, ba lö ifalua mbuania tanö.[3]', '["MozIII 26:19; MozV 28:23","RazII 8:1"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 11, 'Ba no muhededo ba wa lö teu, no ufatörö ba danö ba ba hili, ba zinanö ba nowi ba ba nagu ba ba wanikha, ba ba mbua danö hadia ia, ba niha ba ba zaliŵa-liwa ba danö ba ba wangalui niha, fefu hadia ia.[4]', '["MozIII 26:19; MozV 28:23","RazII 8:1"]', NULL),
  (3476501, 'OT', 'Hagai', 1, 12, 'Ba lafondrondrongo li Lowalangira Yehowa ira Serubabeli, ono Zelatieli, Yosua, ono Yosadaki, ere sebua, awö niha sato fefu, ba labe''e ba dödöra niŵa''ö Haga''i, sama''ele''ö, me no Lowalangira Yehowa zamatenge ya''ia, ba la''ata''ufi Yehowa niha sato.', '[]', NULL),
  (3476501, 'OT', 'Hagai', 1, 13, 'Ba imane Haga''i, sinenge Yehowa andrö, ba niha sato — dali niŵa''ö Yehowa: "Utolo ami!" iŵa''ö Yehowa.', '[]', NULL),
  (3476501, 'OT', 'Hagai', 1, 14, 'Ba ifarou Yehowa dödö Zerubabeli, ono Zelatieli, kumandru ba mado Yuda, ba tödö Yosua, ono Yosadaki, ere sebua, ba tödö niha sato fefu, ba so ira, ba labörötaigö halöŵö folau osali Lowalangira Yehowa ngahönö,', '[]', NULL),
  (3476501, 'OT', 'Hagai', 1, 15, 'ba zi dua wulu a öfa, ba mbaŵa si önö, si no töra döfi razo Dario.', '[]', NULL),
  (3476502, 'OT', 'Hagai', 2, 1, 'Ba ba zi dua wulu a sara, ba mbaŵa si fitu, ba so niŵa''ö Yehowa, nifa''ema Haga''i sama''ele''ö, imane:', '[]', NULL),
  (3476502, 'OT', 'Hagai', 2, 2, 'Hede khö Zerubabeli, ono Zelatieli, kumandru ba mado Yuda, ba khö Yosua, ono Yosadaki, ere sebua, ba ba niha sato, ömane:', '["Eser 3:12"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 3, 'Ha niha na zi tosai ba khömi, si no mangila osali andre, lakhöminia föna? Ba he wisa wamaigimi ya''ia iada''e? Hadia, tenga hulö zi lö boto, wamaigimi?[1]', '["Eser 3:12"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 4, 'Ba iyae, ba böi busi dödöu, ya''ugö Serubabeli! iŵa''ö Yehowa; böi busi dödöu, ya''ugö Yosua, ono Yosadaki ere sebua! Böi mibusi dödömi, ya''ami niha ba danö fefu, iŵa''ö Yehowa, ba mibabaya halöŵö; utolo sa''ae ami,', '["Moz. 19:5; Sakh 4:6"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 5, 'iŵa''ö Yehowa ngahönö, nifagölösigu khömi, me aheta ami ba danö Miserayi, ba abölö Gehehagu ba khömi. Böi mibusi dödömi![2]', '["Moz. 19:5; Sakh 4:6"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 6, 'Imane sa Yehowa ngahönö: Hatö ma''ifu tö, ba ufaheu mbanua si yaŵa, awö danö, ba asi ba tanö sabe''e.[3]', '["Heb 12:26","Sin 72:10; Yes 60:5","Yes 56:7"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 7, 'Ufahufa niha baero, fefu, ba tobali owulo gama-gama niha baero fefu, ana''a, ba anönö nomo andre lakhömi ube''e, iŵa''ö Yehowa ngahönö.[4]', '["Heb 12:26","Sin 72:10; Yes 60:5","Yes 56:7"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 8, 'Khögu wirö ba khögu gana''a, iŵa''ö Yehowa ngahönö.', '["Heb 12:26","Sin 72:10; Yes 60:5","Yes 56:7"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 9, 'Lakhömi gosali andre dania, ba ebua moroi ba lakhöminia föna, iŵa''ö Yehowa ngahönö, ba fangorifi ube''e ba naha andre, iŵa''ö Yehowa ngahönö.[5]', '["Heb 12:26","Sin 72:10; Yes 60:5","Yes 56:7"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 10, 'Ba ba zi dua wulu a öfa ba mbaŵa si siŵa, si no töra döfi razo Dario, ba so niŵa''ö Yehowa, nifa''ema Haga''i, sama''ele''ö imane:', '[]', NULL),
  (3476502, 'OT', 'Hagai', 2, 11, 'Da''ö niŵa''ö Yehowa ngahönö: Sofu ba gere he wisa lala ba da''ö:', '[]', NULL),
  (3476502, 'OT', 'Hagai', 2, 12, 'Na so zi so saŵi ni''amoni''ö ba nono mbarunia, ba na tobaya nono mbarunia ba roti, ba ma ba gule-gule, ba ma ba nagu, ba ma ba wanikha, ba ma hadia ia ni''a, ba he wisa, ni''amoni''ö dania göi da''ö?', '[]', NULL),
  (3476502, 'OT', 'Hagai', 2, 13, 'Ba lamane ere: Lö''ö!', '[]', NULL),
  (3476502, 'OT', 'Hagai', 2, 14, 'Ba humede Haga''i, imane: Si manö göi ba niha andre, si manö ba soi andre, wamaigigu, iŵa''ö Yehowa, si manö göi ba nilau dangara fefu: nibe''era sumange khögu, ba da''ö, ba no si ra''i-ra''iö.', '["Amos 4:9; Hag 1:11","Eser 3:10"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 15, 'Ba iada''e, ba mifaigi he wisa ma''ökhö ba he wisa mege, me lö nifa''anömi kara na, omo Yehowa!', '["Amos 4:9; Hag 1:11","Eser 3:10"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 16, 'He wisa khömi mege? Larugi mbasitö: 20 nganu''i ladöna-döna, ba no ha 10; Ba larugi, wolazi nagu: 50 lauru laŵa''ö, ba no ha 20.', '["Amos 4:9; Hag 1:11","Eser 3:10"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 17, 'No u''otu''ö ami fa''akhozi ngalai wakhe ba fa''ahohomö ba teu kara, ba halöŵö dangami andrö, fefu; ba no lö fangawuli khögu ba khömi! iŵa''ö Yehowa.[7]', '["Amos 4:9; Hag 1:11","Eser 3:10"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 18, 'Ba mifaigi, i''otarai ma''ökhö andre ba ba götö dania, i''otarai zi dua wulu a öfa, ba mbaŵa si siŵa, baŵa me tebe''e tou doyo gosali Yehowa![8]', '["Amos 4:9; Hag 1:11","Eser 3:10"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 19, 'Mitöngöni, na so na ba halasa mbua danö ba na lö''ö na mowua nagu ba ara ba dalimo ba falo! I''otarai luo da''ö, ba ufahowu''ö ami.', '["Amos 4:9; Hag 1:11","Eser 3:10"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 20, 'Ba ifuli humede Yehowa khö Haga''i, ba zi dua wulu a öfa, ba mbaŵa da''ö, imane:', '[]', NULL),
  (3476502, 'OT', 'Hagai', 2, 21, 'Ömane khö Zerubabeli, kumandru ba mado Yuda: Ufaheu mbanua si yaŵa, awö danö,', '["Hez 38:21","SinSeb 8:6; Yer 22:24"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 22, 'utuli''ö dadaomo razo ba uhori wa''abölö gamatöröŵa niha baero. Utuliö gureta, fabaya si fakureta yaŵa, ba alau kudo, fabaya si fakudo ba hulu, faoma ba mbawa zi''öli nawöra.[9]', '["Hez 38:21","SinSeb 8:6; Yer 22:24"]', NULL),
  (3476502, 'OT', 'Hagai', 2, 23, 'Ba na luo da''ö — iŵa''ö Yehowa ngahönö — ba uhalö ndra''ugö, ya''ugö Serubabeli, ono Zelatieli, enonigu, iŵa''ö Yehowa, ba ufataro ndra''ugö, timba laeduru tandro; me no utuyu ndra''ugö, iŵa''ö Yehowa ngahönö.[10]', '["Hez 38:21","SinSeb 8:6; Yer 22:24"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 1, 'Ba mbaŵa si ŵalu, si no töra döfi Dario, ba so niŵa''ö Yehowa khö Zakharia andrö, sama''ele''ö, ono Mberekhia ono Ido, imane:[1]', '["Eser 5:1; Neh 12:16; Hag 1:1"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 2, 'No mofönu sibai Yehowa khö ndra tuami.', '["Yes 31:6; Yer 3:12; 18:11; Hez 18:30; Hos 14:1"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 3, 'Andrö ömane khöra: Da''ö niŵa''ö Yehowa ngahönö: Mifuli ami khögu — iŵa''ö Yehowa ngahönö — ba ufulido göi khömi, iŵa''ö Yehowa ngahönö.[2]', '["Yes 31:6; Yer 3:12; 18:11; Hez 18:30; Hos 14:1"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 4, 'Böi si mane ira tuami ami, tuami andrö ba niŵa''ö zama''ele''ö föna: Da''ö niŵa''ö Yehowa ngahönö: Mifalalini gera-erami, miböhöli lala si lö sökhi andrö khömi ba bua-buami andrö si lö sökhi! — ba lö lafondrondrongo ba lö latöngöni niŵa''ögu, iŵa''ö Yehowa.', '["Yes 31:6; Yer 3:12; 18:11; Hez 18:30; Hos 14:1"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 5, 'Ira tuami andrö, ba heza so? Ba sama''ele''ö andrö, ba hadia, si lö aetu noso?', '["Yes 31:6; Yer 3:12; 18:11; Hez 18:30; Hos 14:1"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 6, 'Ba taroma ligu andrö, awö nifakhoigu andrö, niŵa''ögu ba genonigu, ba tenga no manga ba dödö ndra tuami, ba no lafalalini gera-erara, ba no lamane: Nihonogöi Yehowa ngahönö nifatörö khöda — dali lala andrö nitöröda ba bua-buada andrö — ba no ifatörö khöda.', '["Yes 31:6; Yer 3:12; 18:11; Hez 18:30; Hos 14:1"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 7, 'Ba ba zi dua wulu a öfa, ba mbaŵa si felezara, baŵa Sebati, si no töra döfi Dario, ba so niŵa''ö Yehowa khö Zakharia sama''ele''ö, ono Mberekhia ono Ido, imane:', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 8, 'So gangilatagu, ba zi bongi: niha ba hulu kudo soyoramö, ba gotalua malimbi ba ndraso so ia, ba moroi furinia, ba kudo soyoramö ba soyo ba safusi.[3]', '["Faigi 6:2; Fam 6:4"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 9, 'Be me usofu: Hadia geluaha da''ö, Tuha? ba imane khögu mala''ika andrö, sihede khögu: Da''u''ombakha''ö khöu, hadia geluaha da''ö.', '["Faigi 6:2; Fam 6:4"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 10, 'Ba humede niha andrö, ba gotalua malimbi, imane: Nifatenge Yehowa da''ö, ba wanöröi uli danö!', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 11, 'Ba humede ira khö mala''ika Yehowa andrö, ba gotalua malimbi, lamane: No matöröi guli danö, ba hiza, ba no sahono manö guli danö ma''asagörö, lö hadia ia.', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 12, 'Ba humede mala''ika Yehowa andrö, imane: He Yehowa ngahönö, ha wa''ara tö na lö ahakhö dödöu Yeruzalema ba banua mado Yuda, si no mofönu ndra''ugö, no 70 fakhe ae?', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 13, 'Ba itema li mala''ika andrö, sihede khögu, Yehowa, ihaogö wehedenia khönia, fondrara dödö.', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 14, 'Ba imane khögu mala''ika andrö, sihede khögu: Ebua''ö liu, ömane: Da''ö niŵa''ö Yehowa ngahönö: Humulu sibai dödögu ba Yeruzalema ba ba Ziona,[4]', '["Sakh 8:2","Yes 47:6"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 15, 'ba mofönu sibai ndra''o ba niha baero andrö, si no ahono-hono, si no molului mege ba wamakiko, me mofönu ndra''o, si lö abölö-bölö.[5]', '["Sakh 8:2","Yes 47:6"]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 16, 'Andrö wa imane Yehowa: Ufuli ufaigi Yeruzalema, ahakhö dödögu: telau zui gosali khögu, ba khöra, iŵa''ö Yehowa ngahönö, ba tefadölö ba Yeruzalema wanu''a danö.', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 17, 'Ba farongogö na, ömane: Da''ö niŵa''ö Yehowa ngahönö: Ebua sa''ae dania mbanua andrö khögu, balazi wa''ohahau dödöra, ba ifuli irara dödö Ziona Yehowa, ba ifuli ituyu khönia Yeruzalema.', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 18, 'Ba ufaöga hörögu, ufakhölödo, ba hiza dandru, öfa rozi.', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 19, 'Ba umane khö mala''ika andrö, sihede khögu: Hadia geluaha da''ö?', '[]', NULL),
  (3476504, 'OT', 'Sakharia', 1, 20, 'Ba ifa''ele''ö khögu ziambu Yehowa, daöfa,', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476504, 'OT', 'Sakharia', 1, 21, 'ba umane: Hadia halöŵö da''ö?', '[]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 1, 'Ba ufaöga hörögu, ufakhölödo. Ba hiza niha si so fanu''a danö ba danga.[1]', '["Hez 40:3","Hez 38:11","Yes 60:19"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 2, 'Ba umane: Heza möi ndra''ugö? Ba imane khögu: Ba wanu''a Yeruzalema, ba wamaigi ha wa''ebolo, ba ha wa''anau.', '["Hez 40:3","Hez 38:11","Yes 60:19"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 3, 'Ba hiza, ba so mala''ika andrö, si fahuhuo khögu, ba so na mala''ika bö''ö, ba gametahönia;', '["Hez 40:3","Hez 38:11","Yes 60:19"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 4, 'ba imane ba da''ö: Fulöi, ba hede khö nono matua andrö ba da''ö, ömane: Si lö öli dania Yeruzalema, ba wa''ato niha ba ba wa''oya gurifö, si so yomo ba mbanua,[2]', '["Hez 40:3","Hez 38:11","Yes 60:19"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 5, 'ba ya''odo — iŵa''ö Yehowa — ba öli alitö ndra''odo, fasui, ba lakhömi ndra''o yomo ba mbanua.[3]', '["Hez 40:3","Hez 38:11","Yes 60:19"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 6, 'Hai, hai! Mi''oloi, miheta ami ba danö yöu andrö, iŵa''ö Yehowa; noa sa amaedola ba zi öfa balö mata angi ufazawili ami, iŵa''ö Yehowa.[4]', '["Yes 48:20; 52:11","MozV 32:10; Sin 17:8","MozIII 26:12; Yes 12:6; Hez 37:27; Sef 3:14","Yes 60:3","Hab 2:20"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 7, 'Hai, ya''ugö Siona, orifi''ö, ya''ugö sonahia ba ngai nono Mbabeli alawe!', '["Yes 48:20; 52:11","MozV 32:10; Sin 17:8","MozIII 26:12; Yes 12:6; Hez 37:27; Sef 3:14","Yes 60:3","Hab 2:20"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 8, 'Noa sa imanö wame''e li Yehowa ngahönö, no ifatenge ndra''o ba niha baero andrö, si no morabu si so khömi, ba wangalui fa''ebua döi ifatenge ndra''o; me no sombambaya ono hörönia zombambaya ya''ami![5]', '["Yes 48:20; 52:11","MozV 32:10; Sin 17:8","MozIII 26:12; Yes 12:6; Hez 37:27; Sef 3:14","Yes 60:3","Hab 2:20"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 9, 'Ba hiza, ba u''oro''ö dangagu, yaŵara, ena''ö ondra''ua zi so barö mbaŵara ira, ba ena''ö aboto ba dödömi, wa no Yehowa ngahönö zamatenge ya''o!', '["Yes 48:20; 52:11","MozV 32:10; Sin 17:8","MozIII 26:12; Yes 12:6; Hez 37:27; Sef 3:14","Yes 60:3","Hab 2:20"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 10, 'A''iki, ba omusoi''ö dödöu, ya''ugö ono Ziona alawe! hiza sa, so ndra''o, ba wame''e nahiagu ba khömi, iŵa''ö Yehowa.[6]', '["Yes 48:20; 52:11","MozV 32:10; Sin 17:8","MozIII 26:12; Yes 12:6; Hez 37:27; Sef 3:14","Yes 60:3","Hab 2:20"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 11, 'Ba na luo da''ö, ba oya soi zi olembai Yehowa, ena''ö faböbö banuania ira, ba ena''ö ba khömi la''iagö; ba aboto dania ba dödömi, wa no Yehowa ngahönö zamatenge ya''o ba khömi.[7]', '["Yes 48:20; 52:11","MozV 32:10; Sin 17:8","MozIII 26:12; Yes 12:6; Hez 37:27; Sef 3:14","Yes 60:3","Hab 2:20"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 12, 'I''okhögö dania mado Yuda Yehowa, ihalö tana khönia, ba danö ni''amoni''ö andrö ba ifuli ituyu khönia Yeruzalema.', '["Yes 48:20; 52:11","MozV 32:10; Sin 17:8","MozIII 26:12; Yes 12:6; Hez 37:27; Sef 3:14","Yes 60:3","Hab 2:20"]', NULL),
  (3476505, 'OT', 'Sakharia', 2, 13, 'Dozi niha, ba ndramuhonogö ira föna Yehowa! Noa sa maoso ia, no iröi nahiania andrö ni''amoni''ö.[8]', '["Yes 48:20; 52:11","MozV 32:10; Sin 17:8","MozIII 26:12; Yes 12:6; Hez 37:27; Sef 3:14","Yes 60:3","Hab 2:20"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 1, 'Ba i''oroma''ö khögu Yosua andrö Yehowa, Yosua ere sebua; föna mala''ika Yehowa so ia, ba no so ba ngainia Zatana, ba wangadugu ya''ia.[1]', '["Eser 2:2; Hag 1:1; Yob 1:6; Sin 109:6; Fam 12:10","Yud a. 9; Amos 4:11","Fam 3:18","Sin 51:9; Yes 61:10; Luk 15:22","MozII 28:39; Faigi 6:11","MozV 11:1; Hez 44:15; Sin 91:11"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 2, 'Ba imane Yehowa khö Zatana: Yehowa zanguma''ö khöu: böi hede-hede, ya''ugö Satana! Yehowa, si no manuyu khönia Yeruzalema, zanguma''ö khöu: böi hede-hede! Hadia, tenga dudunga nisöbi ba galitö da''e?[2]', '["Eser 2:2; Hag 1:1; Yob 1:6; Sin 109:6; Fam 12:10","Yud a. 9; Amos 4:11","Fam 3:18","Sin 51:9; Yes 61:10; Luk 15:22","MozII 28:39; Faigi 6:11","MozV 11:1; Hez 44:15; Sin 91:11"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 3, 'Ba no nukha soda''i nukha Yosua, me so ia ba da''ö, föna mala''ika.[3]', '["Eser 2:2; Hag 1:1; Yob 1:6; Sin 109:6; Fam 12:10","Yud a. 9; Amos 4:11","Fam 3:18","Sin 51:9; Yes 61:10; Luk 15:22","MozII 28:39; Faigi 6:11","MozV 11:1; Hez 44:15; Sin 91:11"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 4, 'Ba humede da''ö, imane ba zi so ba da''ö: Miheta khönia nukha soda''i andrö! Ba noa da''ö, ba imane khönia: Hiza, no ube''e aefa khöu horöu, ba ufafonukha''ö sa''ae ndra''ugö nukha ba walöŵa.[4]', '["Eser 2:2; Hag 1:1; Yob 1:6; Sin 109:6; Fam 12:10","Yud a. 9; Amos 4:11","Fam 3:18","Sin 51:9; Yes 61:10; Luk 15:22","MozII 28:39; Faigi 6:11","MozV 11:1; Hez 44:15; Sin 91:11"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 5, 'Ba imane na: Mifanaembu ia saembu si lö da''i! Ba lafanaembu ia saembu si sökhi ba lafonukha ia; ba soso na ba ngaira mala''ika Yehowa andrö.[5]', '["Eser 2:2; Hag 1:1; Yob 1:6; Sin 109:6; Fam 12:10","Yud a. 9; Amos 4:11","Fam 3:18","Sin 51:9; Yes 61:10; Luk 15:22","MozII 28:39; Faigi 6:11","MozV 11:1; Hez 44:15; Sin 91:11"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 6, 'Ba ifaduhu''ö khö Yosua mala''ika Yehowa, imane:', '["Eser 2:2; Hag 1:1; Yob 1:6; Sin 109:6; Fam 12:10","Yud a. 9; Amos 4:11","Fam 3:18","Sin 51:9; Yes 61:10; Luk 15:22","MozII 28:39; Faigi 6:11","MozV 11:1; Hez 44:15; Sin 91:11"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 7, 'Da''ö niŵa''ö Yehowa ngahönö: Na ötörö lala andrö khögu, ba na ö''o''ö nifakhoigu; na öhaogö halöŵöu ba nomogu, ba na öhaogö göi wamaigi he wisa ba golayama, ba ufolala ndra''ugö, awö genonigu andre.[6]', '["Eser 2:2; Hag 1:1; Yob 1:6; Sin 109:6; Fam 12:10","Yud a. 9; Amos 4:11","Fam 3:18","Sin 51:9; Yes 61:10; Luk 15:22","MozII 28:39; Faigi 6:11","MozV 11:1; Hez 44:15; Sin 91:11"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 8, 'Ba fondrondrongo, ya''ugö Yosua, ere sebua, ya''ugö ba awöu andrö, sidadao fönau — noa sa tandra ira he wisa dania, sahöli-höli dödöda —: Hiza sa, ufa''aso genonigu "Lewiö" andrö![7]', '["Yes 4:2; Hez 12:6; Faigi 6:12","Sin 118:22; Yes 11:1,2; 28:16; Faigi 4:10","RazI 4:25; Mikh 4:4"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 9, 'Ba kara andrö, nibe''egu föna Yosua — fitu hörö zamaigi kara, si ha sambu-sambua —, ba usua dania, iŵa''ö Yehowa ngahönö, ba olalöŵa andrö, ba danö andre, ba ha ma''öma''ökhö u''angohori''ö.[8]', '["Yes 4:2; Hez 12:6; Faigi 6:12","Sin 118:22; Yes 11:1,2; 28:16; Faigi 4:10","RazI 4:25; Mikh 4:4"]', NULL),
  (3476506, 'OT', 'Sakharia', 3, 10, 'Ba na luo da''ö — iŵa''ö Yehowa — ba tola faoma mikaoni nawömi ba lumö nagu ba ba lumö marafala![9]', '["Yes 4:2; Hez 12:6; Faigi 6:12","Sin 118:22; Yes 11:1,2; 28:16; Faigi 4:10","RazI 4:25; Mikh 4:4"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 1, 'Ba isusugido mala''ika andrö, si fahuhuo khögu, timba na lasusugi zi mörö,', '["Hag 1:1; 2:5"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 2, 'ba imane khögu: Hadia ni''ilau? Ba umane: Naha wandru u''ila, ana''a manö, naha wanikha tanö yaŵa ba fitu wandrunia ba fitu goro wanikha, ba wolau ba wandru andrö, tanö yaŵa.', '["Hag 1:1; 2:5"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 3, 'Ba ba ngainia, ba dua geu döla zai, sageu ba gambölö naha wanikha andrö ba sageu ba gabera.', '["Hag 1:1; 2:5"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 4, 'Ba humede ndra''o, umane khö mala''ika andrö, si fahuhuo khögu: Hadia geluaha da''ö. Tuha?', '["Hag 1:1; 2:5"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 5, 'Ba itema ligu mala''ika andrö, si fahuhuo khögu, imane khögu: Hadia, lö ö''ila, hadia geluaha da''ö? Ba umane: Lö''ö, Tuha!', '["Hag 1:1; 2:5"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 6, 'Ba humede ia, imane khögu: Taroma li Yehowa khö Zerubabeli da''ö, imane: Tenga ba wa''abölöu ba tenga ba wa''abe''eu, ha ba Gehehagu a''i, iŵa''ö Yehowa ngahönö.[1]', '["Hag 1:1; 2:5"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 7, 'Hadia atö, ndra''ugö, ya''ugö hili sebua, föna Zerubabeli? Salo''o dania ndra''ugö! Ena''ö alaŵa yaŵa ibe''e gara andrö, ba ena''ö lahehegö: Ya ahowu! Ya ahowu!', '["Hag 1:1; 2:5"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 8, 'Ba humede khögu Yehowa, imane:', '["Eser 3:8 b.t.","Nga''ötII 16:9; Fam 5:6","Fam 11:4"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 9, 'Tanga Zerubabeli mege zame''e tou toyo ba watalinga nomo andre, ba tangania göi zangasiwai, ena''ö aboto ba dödöu, wa no Yehowa ngahönö zamatenge ya''o khömi.[2]', '["Eser 3:8 b.t.","Nga''ötII 16:9; Fam 5:6","Fam 11:4"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 10, 'Ha niha sa zangositengagö baŵa mböröta andre! oi no ide-ide na! Somuso tödö ira, na la''ila zimo ba danga Zerubabeli; si fitu andrö — hörö Yehowa andrö — zondrugi uli danö ma''asagörö.[3]', '["Eser 3:8 b.t.","Nga''ötII 16:9; Fam 5:6","Fam 11:4"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 11, 'Ba humede ndra''o, umane khönia: Ba töla zai andrö, fatambai naha wandru, ba hadia geluaha?', '["Eser 3:8 b.t.","Nga''ötII 16:9; Fam 5:6","Fam 11:4"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 12, 'Ba usofu na khönia, umane: Ba hadia geluaha duturu zai andrö, ba ngai goro andrö ana''a, si dua andrö, lala wanikha ana''a andrö moroi yaŵa?', '["Eser 3:8 b.t.","Nga''ötII 16:9; Fam 5:6","Fam 11:4"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 13, 'Ba imane khögu; Hadia, lö ö''ila hadia geluaha da''ö? Ba umane: Lö''ö, Tuha!', '["Eser 3:8 b.t.","Nga''ötII 16:9; Fam 5:6","Fam 11:4"]', NULL),
  (3476507, 'OT', 'Sakharia', 4, 14, 'Ba imane: Da''ö nibayoini andrö, si darua, si iagö ngoni-ngoni föna zamatörö ösi guli danö ma''asagörö.[4]', '["Eser 3:8 b.t.","Nga''ötII 16:9; Fam 5:6","Fam 11:4"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 1, 'Ba ufuli ufaöga hörögu, ufakhölödo, ba hiza zura sihombo.[1]', '["Hez 2:9"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 2, 'Ba umane khögu: Hadia ni''ilau? Ba umane: Sura sihombo u''ila, dua wulu hela wa''anau, ba fulu hela wa''ebolo.', '["Hez 2:9"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 3, 'Ba imane khögu: Da''ö wangelifi andrö, sanöröi tanö ma''asagörö; dozi sanagö, ba nihori ba da''e, dali nisura ba zura andrö; ba dozi si möi ba höleo [na faya], ba nihori ba da''e, dali nisura ba zura andrö.', '["Hez 2:9"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 4, 'No ufa''ohe''ö ia, iŵa''ö Yehowa ngahönö, ena''ö irugi yomo ba nomo zanagö ba ba nomo zi möi ba hölu ba döigu [na faya], ena''ö yomo khöra i''iagö, ba ena''ö ifufu, he eu, ba he kara.', '["Hez 2:9"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 5, 'Ba so mala''ika andrö, si fahuhuo khögu, ba imane khögu: Faöga höröu ba faigi hadia zoroma andrö!', '["MozI 10:10"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 6, 'Ba umane: Hadia ia? Ba imane: Lou zoroma; ba imane na: Olalöŵara da''ö, ba danö, ma''asagörö.', '["MozI 10:10"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 7, 'Ba hiza, ba teboka lagö lou, simo sowulo, ba hiza ndra alawe sidao-dao, bakha ba lou.', '["MozI 10:10"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 8, 'Ba imane mala''ika: Da''ö horö andrö. Ba ituli''ö tou ba lou [ndra alawe andrö], ba ilagö''ö simo no mege.', '["MozI 10:10"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 9, 'Ba me ufaöga horögu, ba hiza, darua ndra alawe soroma, ba ibözi angi gafira — no hulö gafi dumbao gafira —, ba lafazaŵa lou no mege, la''ohe ba dalu mbanua.', '["MozI 10:10"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 10, 'Ba umane khö mala''ika andrö, si fahuhuo khögu: Heza la''ohe lou andrö?', '["MozI 10:10"]', NULL),
  (3476508, 'OT', 'Sakharia', 5, 11, 'Ba imane khögu: Ba wamaigi nahiania ba danö Zineara, ba na no awai, ba lafedadao ba da''ö, ba nahania.[2]', '["MozI 10:10"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 1, 'Ba ufuli ufaöga hörögu, ufakhölödo, ba hiza gureta, öfa endronga, si otarai gotalua hili; ba hili andrö, ba töla garamba.', '["Faigi 1:8; Fam 6:4","Yer 49:36","Hez 5:13"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 2, 'Ba sondröni kureta si so föna, ba kudo soyoramö, ba ba gureta fanete da''ö, ba kudo saitö,', '["Faigi 1:8; Fam 6:4","Yer 49:36","Hez 5:13"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 3, 'ba ba wanete da''ö, ba safusi, ba ba wanete da''ö, ba sombaŵambaŵa.[1]', '["Faigi 1:8; Fam 6:4","Yer 49:36","Hez 5:13"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 4, 'Ba humede ndra''o, umane khö mala''ika andrö, si fahuhuo khögu: Hadia geluaha da''ö, Tuha?', '["Faigi 1:8; Fam 6:4","Yer 49:36","Hez 5:13"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 5, 'Ba imane khögu mala''ika: Da''ö mata angi andrö, si öfa; latörö, me no faefa la''ondrasi zamatörö ösi guli danö ma''afefu.[2]', '["Faigi 1:8; Fam 6:4","Yer 49:36","Hez 5:13"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 6, 'Kureta andrö, nidöni kudo saitö andrö, ba ba danö miyöu isaŵa, ba la''o''ö safusi andrö; ba sombaŵa-mbaŵa, ba ba danö miraya lasaŵa.', '["Faigi 1:8; Fam 6:4","Yer 49:36","Hez 5:13"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 7, 'Ba mofanö göi soyoramö andrö; ba me mangefa ira ena''ö, ba imane Yehowa: Milabu! Mitöröi guli danö! ba latöröi guli danö.', '["Faigi 1:8; Fam 6:4","Yer 49:36","Hez 5:13"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 8, 'Ba humede ia khögu, ba imane khögu: Faigi, sanaŵa tanö miyöu andrö, ba ahono Gehehagu ba danö yöu andrö misa labe''e.[3]', '["Faigi 1:8; Fam 6:4","Yer 49:36","Hez 5:13"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 9, 'Ba so niŵa''ö Yehowa khögu, imane:', '["Sakh 3:1","Yes 4:2; Yer 23:5; Faigi 3:8","Hez 37:16; Efes 2:14 b.t.","Yes 46:6; 10:10"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 10, 'Halö ösa game''ela mbanua si no mu''oloi''ö, Helida''i zama''ema khöu, nibe''e ndra Tobia Yedaya; ba ae yomo khö Yosia, ono Zefania, na luo da''ö, ya''ugö andrö, ba nomo ba zi möi ira, me la''otarai Mbabeli.', '["Sakh 3:1","Yes 4:2; Yer 23:5; Faigi 3:8","Hez 37:16; Efes 2:14 b.t.","Yes 46:6; 10:10"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 11, 'Ba halö wirö ba ana''a, ba bali''ö takula, ba fotakula Zerubabeli ba Yosua, ono Yosadaki, ere sebua,[4]', '["Sakh 3:1","Yes 4:2; Yer 23:5; Faigi 3:8","Hez 37:16; Efes 2:14 b.t.","Yes 46:6; 10:10"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 12, 'ba ömane khöra: Da''ö niŵa''ö Yehowa ngahönö: Hiza niha sotöi "Lewiö" — na so ia, ba tumbu-tumbu [zi sökhi], ba ya''ia zolau osali Yehowa.[5]', '["Sakh 3:1","Yes 4:2; Yer 23:5; Faigi 3:8","Hez 37:16; Efes 2:14 b.t.","Yes 46:6; 10:10"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 13, 'Ya''ia zolau osali Yehowa, ba si falukha fa''asalaŵa ia, ba tobali dumadao ia ba dadaoma zalaŵa khönia, ba salaŵa ia, ba so ba ngainia gere, ba ha sara dödö zi darua andrö.[6]', '["Sakh 3:1","Yes 4:2; Yer 23:5; Faigi 3:8","Hez 37:16; Efes 2:14 b.t.","Yes 46:6; 10:10"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 14, 'Ba takula no mege, ba nibe''e ba gosali Yehowa, fa böi aefa-aefa itörö tödöra ndra Helida''i Tobia Yedaya, ba fa''oböwö nono Zefania andrö.', '["Sakh 3:1","Yes 4:2; Yer 23:5; Faigi 3:8","Hez 37:16; Efes 2:14 b.t.","Yes 46:6; 10:10"]', NULL),
  (3476509, 'OT', 'Sakharia', 6, 15, 'Ba banua saröu, ba möi manolo ba wolau osali Yehowa, ena''ö aboto ba dödömi, wa no Yehowa ngahönö zamatenge ya''o khömi, ba na moroi ba dödömi mi''o''ö goroisa Lowalangimi Yehowa, ba itörö.[7]', '["Sakh 3:1","Yes 4:2; Yer 23:5; Faigi 3:8","Hez 37:16; Efes 2:14 b.t.","Yes 46:6; 10:10"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 1, 'Ba me no töra medölu fakhe razo Dario, ba so niŵa''ö Yehowa khö Zakharia.', '["Yer 52:12"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 2, 'Ba zi mendröfa, ba mbaŵa si siŵa, baŵa Kisilewi ba lafatenge zinenge si samba omo ndra Elizarese ba Regemi-Melekhi ba banuara,', '["Yer 52:12"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 3, 'ba wangalulu khö Yehowa, ba wanofu ba gere, ba gosali Yehowa ngahönö, ba ba zama''ele''ö, lamane: Hadia, utohugö na ba mbaŵa si lima we''e ba famoni, hadia, utohugö na wolaugu no, ha me uga fakhe sa''ae.[1]', '["Yer 52:12"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 4, 'Ba humede khögu Yehowa ngahönö, imane:', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 5, 'Hede ba niha ba danö fefu ba ba gere, ömane: Na no fitu ngafulu fakhe mamoni ami ba mege-ege, na baŵa si lima ba na baŵa si fitu, ba hadia, no khögu tetandrösaigö wamonimi andrö?[2]', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 6, 'Ba na manga ami ba na mibadu hadia ia, ba hadia, tenga ya''ami zi manga, ba tenga ya''ami zamadu nibadu andrö?', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 7, 'Hadia, tenga da''e daroma li andrö, nifa''ombakha''ögö Yehowa ba zama''ele''ö no andrö, föna, me so na niha ba Yeruzalema, me lö''ö na hadia ia khöra, ba ba mbanua si tefasui ya''ira, ba me lö saheta niha raya, ba ba zalo''o?[3]', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 8, 'Ba so niŵa''ö Yehowa khö Zakharia, imane:', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 9, 'Da''ö niŵa''ö Yehowa ngahönö: "Satulö mifaigi, ba wamatunö huhuo, ba faoma mi''omasi''ö nawömi, ba faoma mihakhösi tödö![4]', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 10, 'Böi mifakao lakha mbanua ba si lö ama, si lö ina, ba he niha bö''ö, ba he si numana, ba böi mifakhoi tödömi zi lö sökhi ba nawömi!"[5]', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 11, 'Ba no te khöra wamondrongo, no abe''e mbörö du''i; la''afiso''ö dögi dalingara, ba tobali lö larongo.', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 12, 'Ba la''abe''e''ö dödöra, timba naoma, ba tobali lö larongo goroisa ba taroma li andrö nifafa''ema''ö Yehowa ngahönö khö Gehehania, ba zama''ele''ö andrö, föna. Ba tesao wönu Yehowa ngahönö, fönu sabölö-bölö,[6]', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 13, 'ba si mane ba we''aonia mege, si lö lafondrondrongo, si manö dania na mu''ao-ao ira, iŵa''ö Yehowa ngahönö, lö urongo;[7]', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476510, 'OT', 'Sakharia', 7, 14, 'ufazawili dania ira a''i, ba danö niha baero fefu, si lö larai la''ila, ba tanöra, ba si tobali tanö si mate, na no aheta ira, ba tobali lö sanörö sa''ae; ba tobali tanö si mate danö si sökhi sibai labe''e.', '["RazII 25:25; Yer 41:1","Yes 58:3","Yer 7:5; 21:12","Yes 1:23","Yes 48:4; Mikh 3:8","Yes 1:15; Yer 11:11"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 1, 'Ba ifuli so niŵa''ö Yehowa khögu, imane:', '["Faigi 1:14","Sef 3:13"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 2, 'Da''ö niŵa''ö Yehowa ngahönö: Omasido sibai Ziona andrö, solohu ndra''odo, ba no tesao wönugu khöra, fönu sabölö-bölö.[1]', '["Faigi 1:14","Sef 3:13"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 3, 'Da''ö niŵa''ö Yehowa: Sangawuli ba Ziona ndra''odo, ba ba dalu Yeruzalema ube''e nahiagu; "banua si lö faröi" dania döi Yeruzalema, ba "hili ni''amoni''ö" döi hili Yehowa ngahönö.[2]', '["Faigi 1:14","Sef 3:13"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 4, 'Da''ö niŵa''ö Yehowa ngahönö: So na dania zidao-dao ba golayama ba Yeruzalema ira matua satua ba ira alawe satua, dozi so zi''o ba dangara, me no atua sibai ira.', '["Faigi 1:14","Sef 3:13"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 5, 'Ba ewali yomo ba mbanua, ba anönö iraono, ono matua ba ono alawe, si famaimai baewali khöra.', '["Faigi 1:14","Sef 3:13"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 6, 'Da''ö niŵa''ö Yehowa ngahönö: Na sahöli-höli dödö dania da''ö, na luo da''ö, wamaigi zi tosai so da''e, ba khögu göi, ba sahöli-höli dödö ia, iŵa''ö Yehowa ngahönö.', '["Faigi 1:14","Sef 3:13"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 7, 'Da''ö niŵa''ö Yehowa ngahönö: Hiza, u''orifi mbanuagu, u''efa''ö ba danö tanö ba gatumbukha luo misa ba ba danö tanö ba gaekhula luo,', '["Faigi 1:14","Sef 3:13"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 8, 'ba u''ohe mangawuli ira, ena''ö yomo ba Yeruzalema labe''e nahiara, ba banuagu ira, si lö tebulö ba si ndruhu, ba Lowalangira ndra''odo!', '["Faigi 1:14","Sef 3:13"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 9, 'Da''ö niŵa''ö Yehowa ngahönö: Mi''abe''e''ö dangami ya''ami samondrongo taroma li andre, ba götö da''e, taroma li nifa''ema zama''ele''ö andrö, sama''ele''ö me luo tebe''e tou doyo ba wolau omo Yehowa ngahönö, osali andrö.[3]', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 10, 'Föna da''ö sa, ba lö böli gölö niha ba halöŵöra, ba he halöŵö gurifö, ba no zaya-zaya gölö; ba zofanö ba ba zangawuli, ba so gameta''uö emali, ba no ufadou manö niha fefu.[4]', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 11, 'Ba iya''e, ba bö''ö dödögu ba zi tosai soi da''e, bö''ö me föna, iŵa''ö Yehowa ngahönö;', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 12, 'lö''ö sa''ae hadia ia ba zinanö khöra. Mowua nagu ba mowua danö, ba soso namo mbanua ba utehe manö da''ö fefu ba zi tosai soi andre.', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 13, 'Ba si mane mege, me no tobali fangelifi döimi ba niha baero, ya''ami ma''uwu Yuda ba ma''uwu Gizeraeli, si manö wanologu ya''ami, ena''ö tobali famahowu''ö döimi! Böi mibusi dödömi!', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 14, 'Mi''abe''e''ö dangami! Imane sa Yehowa ngahönö: Si mane mege, me uhonogöi wamakao ya''ami, me labaosi dödögu ira tuami, iŵa''ö Yehowa ngahönö, ba me lö aröuröu ba dödögu,', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 15, 'si manö göi wangohonogöigu ma''ökhö famatörö si sökhi ba Yeruzalema ba ba ma''uwu Yuda.', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 16, 'Böi mibusi dödömi! Ba da''ö nilaumi: Faoma si duhu milau khö nawömi ba böi mibila''ö wamatunö huhuo ba kato khömi, huku satulö mifatörö![5]', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 17, 'Böi mifakhai tödömi zi lö sökhi khö nawömi, ba böi omasi ami we''amöi ba hölu ba zi lö duhu, me no si fatuwu khögu da''ö fefu, iŵa''ö Yehowa.[6]', '["Eser 3:10","Hag 1:6","MozI 34:20; Efes 4:25","Faigi 5:3; 7:10"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 18, 'Ba so niŵa''ö Yehowa ngahönö khögu, imane:', '["Yer 52:6,12; 41:1; 52:4","Yes 2:3; Mikh 4:2","KorI 14:25"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 19, 'Da''ö niŵa''ö Yehowa ngahönö: Famoni andrö, na baŵa si öfa ba si lima ba si fitu ba si fulu, ba tobali fa''omuso dödö ba fa''iki ba si no amaedola walöŵa, ba ma''uwu Yuda: ba mi''omasi''ö zi duhu ba fa''atulömi khö nawömi![7]', '["Yer 52:6,12; 41:1; 52:4","Yes 2:3; Mikh 4:2","KorI 14:25"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 20, 'Da''ö niŵa''ö Yehowa ngahönö: Falukha na dania, ba la''ondrasi ami soi bö''ö, sambu-sambua soi manö, ba oya banua zangondrasi ya''ami.', '["Yer 52:6,12; 41:1; 52:4","Yes 2:3; Mikh 4:2","KorI 14:25"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 21, 'Faoma möi khö nawöra mbanuara ba lamane: Talabu, möi ita fakao khö Yehowa ngahönö! Ya''odo göi, ba si möi![8]', '["Yer 52:6,12; 41:1; 52:4","Yes 2:3; Mikh 4:2","KorI 14:25"]', NULL),
  (3476511, 'OT', 'Sakharia', 8, 22, 'Ba oya soi, ato niha baero zangondrasi, ba wangalui Yehowa ngahönö, ba Yeruzalema, ba ba wakaosa, khö Yehowa.', '["Yer 52:6,12; 41:1; 52:4","Yes 2:3; Mikh 4:2","KorI 14:25"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3476511, 'OT', 'Sakharia', 8, 23, 'Da''ö niŵa''ö Yehowa ngahönö: Na luo da''ö dania, ba hiza, ba dafitu niha, hadia lira fefu, li niha baero, zondra''u ahe mbaru niha Yehuda si ha samösa, ba sanguma''ö: Faoga khömi, me no marongo, wa lö aefa-aefa khömi Lowalangi![9]', '["Yer 52:6,12; 41:1; 52:4","Yes 2:3; Mikh 4:2","KorI 14:25"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 1, 'Niŵa''ö [zama''ele''ö]. Taroma li Yehowa, nitandrösaigö ba danö Haderakhi, si tohare ba Ndramaseko dania. Ifaigi-faigi sa niha Yehowa, ba he mado Ndraono Gizeraeli fefu.[1]', '["Yes 13:1","Yes 10:9","SamII 24:18"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 2, 'Ba ba Hamata, si faola ba da''ö, ba ba Diro ba ba Zidona; noa sa onekhe sibai ira![2]', '["Yes 13:1","Yes 10:9","SamII 24:18"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 3, 'No la''aro''ö mbanua khöra banua Diro andrö. No lahöna wirö, timba gawu-gawu, ba balaki, timba dambu baewali wa''oya.', '["Yes 13:1","Yes 10:9","SamII 24:18"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 4, 'Ba hiza, ba Yehowa zatu''a dania, ba itimba ba nasi wangabe''era andrö, ba banua, ba ö galitö.', '["Yes 13:1","Yes 10:9","SamII 24:18"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 5, 'Lafaigi-faigi dania Asikalo, ba humokha mbura: ba banua Gasa, ba laköröbui ira [ba wa''afökhö], ba si manö göi Nekerona — me no tobali faya dötönaföra andrö. Ba ba Gasa, ba lö razo sa''ae; ba Asikalo, ba si lö niha sa''ae dania,', '["Yes 13:1","Yes 10:9","SamII 24:18"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 6, 'ba ba Gasoto, ba niha si no fakhöyö zowanua. Uhöndrögö wayaŵasa Ndrawa Wilisiti andrö,', '["Yes 13:1","Yes 10:9","SamII 24:18"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 7, 'ba ufadöni ba mbawara si fao do andrö; ba sogoro ita andrö khöra, ba usöbi ba niföra. Ba si tosai dania ira göi, khö Lowalangida. Si falaŵalaŵa ba zalaŵa mado Yuda dania ira, ba banua Nekerona, ba si falaŵalaŵa ba Ndraono Yebusi.[3]', '["Yes 13:1","Yes 10:9","SamII 24:18"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 8, 'Ba u''iagö ba''a-ba''a ba gosali andrö khögu, ba''a-ba''a zanörö fefu. Böi sa''ae irugi ira samakao; ufaigi-faigi sa''ae.', '["Yes 13:1","Yes 10:9","SamII 24:18"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 9, 'Abölögö a''iki, ya''ugö ono Ziona alawe! Owua-wua''ö dödö, ya''ugö ono Yeruzalema alawe! Hiza, möi yomo ba mbanua khömi razomi, razo satulö ba sabölö! si lö fayaŵasa ia, ba hulu galide so ia, ba hulu nono galide si alawe.[4]', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 10, 'Ba ihori gureta ba wanuwö, ba mado Geferayi, ba he kudo ba Yeruzalema: ba he fana ba wanuwö, ba nihori dania; ba fa böi fasuwö iŵa''ö ba soi niha misa. Ba oi barö mbawania so, i''otarai nasi ba zi tambai, numalö ba nasi ba zi tambai, tanö sa, ba i''otarai mboto Oifarati, numalö ba wondrege danö.[5]', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 11, 'Ba me no do ube''e tandro tanga ba zura wawu''usa li andrö khöda, ba u''efa''ö göi ni''oloi''ö andrö khöu, ba mba''a andrö, si lö idanö.[6]', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 12, 'Mifuli ami ba mbanua saro andrö, ya''ami si no timba nikuru, sanötöna na fangefa. Ma''ökhö na göi, ba tefarongogö: Ufodua winaeta wanulöni khöu.', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 13, 'No ukhai khögu mado Yuda, nifogai fana, no ufo''ösi [ono wana] mado Geferayi, ba ufarou nonou matua, ya''ugö Siona, ba wolau ba ndraono Yawano, ubali''ö si''öli zabölö ami.[7]', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 14, 'To''ele dania Yehowa, yaŵara, ba itörö ono wana khönia, timba gari mbanua; ilau dania dorofe Yehowa ba fao ia ba nangi sabölö moroi raya wanörö.[8]', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 15, 'Ifoba''a-ba''a ira Yehowa ngahönö, manga-manga ira, ba lahundra-hundra tou nono gara riboribo. Labadu ndro [zanuwö] nifamadu agu, ba oi do ira, timba wiga andrö, ba wame''e sumange, ba timba watalinga naha wame''e sumange.', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 16, 'Lowalangira Yehowa zame''e abölö ira, na luo da''ö, ya''ira andrö, nikubaloi, banuania, me no mani-mani ba dakula ira, si takile ba danönia.', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476512, 'OT', 'Sakharia', 9, 17, 'Ha lö ebua lakhöminia! ba ha lö abölö wa''asökhinia! So mbua danö, fangabölö nono matua, ba so nösi mbua nagu fangabölö nono alawe.[9]', '["Yes 62:11; Mat 21:5; Yoh 12:15","Sin 72:8","Yes 61:1; Mat 26:28","Yoel 3:6","Sin 18:15; Yes 27:13","MozV 33:28"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 1, 'Mi''andrö deu khö Yehowa! Ibe''e deu sara ba teu sahulö, na inötö; ifatörö gari mbanua ba teu laöhö ba ndru''u ba ba zinanö ba danö fefu.[1]', '["Sin 72:16","Yer 10:8","Hez 34:2","Yes 19:13; 22:23; SamII 1:22","Mikh 7:10","Faigi 9:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 2, 'Fayafafa sa niŵa''ö ziraha, ba no angilata faya gangilata zi faeta; nifakhai dödö, si lö boto, wehedera, ba no angi wondrara dödö andrö khöra. Andrö wa mowaö-waö manö ira, timba ngawawa mbiri-biri, ba no irugi ira famakao, me no lö sokubaloi ya''ira.[2]', '["Sin 72:16","Yer 10:8","Hez 34:2","Yes 19:13; 22:23; SamII 1:22","Mikh 7:10","Faigi 9:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 3, 'Ba no tesao wönugu, ba gubalo andrö, ba u''otu''ö dania zi matua andrö [sondrönia''ö ya''ira]. Noa sa ifaigi Yehowa ngahönö nikubaloi andrö khönia, ma''uwu Yuda, ba no ibali''ö kudo khönia, kudo soadu ba wanuwö.[3]', '["Sin 72:16","Yer 10:8","Hez 34:2","Yes 19:13; 22:23; SamII 1:22","Mikh 7:10","Faigi 9:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 4, 'Khönia i''otarai toyo ba watalinga ba moroi khönia göi daru-taru nose, moroi khönia wana ba wanuwö, ba ba khönia la''otarai sondrönia''ö fefu.[4]', '["Sin 72:16","Yer 10:8","Hez 34:2","Yes 19:13; 22:23; SamII 1:22","Mikh 7:10","Faigi 9:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 5, 'Hulö sabölö ira ba wasöndrata, samöbörö tou tambu ba ewali, ba lalau fasöndra, me no Yehowa zanolo ya''ira, ba tobali si lö boto zi fakudo (emali)[5]', '["Sin 72:16","Yer 10:8","Hez 34:2","Yes 19:13; 22:23; SamII 1:22","Mikh 7:10","Faigi 9:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 6, 'Ba u''abe''e''ö ma''uwu Yuda, ba utolo ma''uwu Yosefo; ba u''ohe mangawuli ira, me no ahakhö dödögu ira, ba tobali hulö na lö urai utibo''ö ira. Me no Yehowa ndra''odo, Lowalangira, ba ufondrondrongo khöra.', '["Sin 72:16","Yer 10:8","Hez 34:2","Yes 19:13; 22:23; SamII 1:22","Mikh 7:10","Faigi 9:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 7, 'Ba tobali sabölö mado Geferayi, ba abe''e dödöra, timba zi no mamadu agu. Ba la''ila iraonora; ba omuso dödö, owua-wua dödöra ba khö Yehowa![6]', '["Sin 72:16","Yer 10:8","Hez 34:2","Yes 19:13; 22:23; SamII 1:22","Mikh 7:10","Faigi 9:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 8, 'Udönisi ira ba u''owuloi ira, me no sangorifi ya''ira ndra''odo; ba ato dania ira, si mane me föna.', '["Yer 51:50","Yes 11:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 9, 'Ufazawili ira ba danö niha baero, ba he ba wondrege zaröu tanö, ba itörö tödöra ndra''odo; ba la''e''ebua ndraonora, ba lafuli ira.[7]', '["Yer 51:50","Yes 11:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 10, 'U''ohe mangawuli ira, moroi ba danö Miserayi ba u''owuloi ira moroi ba danö Asiria; ufa''amöi ba danö Gileadi ira ba ba hili Libano, ba ambö nahara.', '["Yer 51:50","Yes 11:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 11, 'La''ötö nasi, lasaŵa Diro, ba ituli''ö ba nasi hati andrö khöra, ba ogo''ö namö Nilo, fefu. Ba tetuli''ö tou Asiria, si no fayaŵa andrö, ba aheta zi''o zalaŵa ba Ndrawa Miserayi.[8]', '["Yer 51:50","Yes 11:15"]', NULL),
  (3476513, 'OT', 'Sakharia', 10, 12, 'Abe''e dania ira ba khö Yehowa ube''e, ba lasuno dania ira ba döinia andrö, iŵa''ö Yehowa.', '["Yer 51:50","Yes 11:15"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 1, 'Bokai mbawa gölimö, ya''ugö hili Libano, ena''ö i''a alitö döla geresi andrö khöu![1]', '["RazI 7:2; Yer 22:23","Yes 2:13","Sin 44:23; Rom 8:36"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 2, 'Ege''ege, ya''ugö senobari, me no tekiko geresi, me no afufu zoadu andrö! Mi''ege-ege, ya''ami manawa ba danö Mbazana, me no tou ba danö so gatua andrö, si tebai itörö niha mege![2]', '["RazI 7:2; Yer 22:23","Yes 2:13","Sin 44:23; Rom 8:36"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 3, 'Tarongo wege-ege gubalo andrö, me no afufu wa''asökhi andrö. Tarongo wendröndröndröndrö nono zingo, me no tobali tanö si mate zatua eu andrö ba ndraso Yoridano.', '["RazI 7:2; Yer 22:23","Yes 2:13","Sin 44:23; Rom 8:36"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 4, 'Da''ö niŵa''ö Lowalangigu Yehowa: Kubaloi mbiri-biri andrö nitaba dania;[3]', '["RazI 7:2; Yer 22:23","Yes 2:13","Sin 44:23; Rom 8:36"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 5, 'nitaba zowöli lö fotu; ba niŵa''ö zamawa: Nisuno Yehowa, so''ana''a sa''ae ndra''odo! ba kubalora, ba lö lahakhösi tödö ira.', '["RazI 7:2; Yer 22:23","Yes 2:13","Sin 44:23; Rom 8:36"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 6, 'I''otarai da''e sa, ba lö''ö sa''ae uhakhösi tödö niha ba danö, iŵa''ö Yehowa; ya''odo sa''ae zolulu niha, ululu ba danga gubalonia zamösana, ba ba danga razonia; da''ö sa''ae zamakiko tanö, ba samösa lö u''efa''ö ba dangara.', '["RazI 7:2; Yer 22:23","Yes 2:13","Sin 44:23; Rom 8:36"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 7, 'Ba no ukubaloi mbiri-biri sinuturu andrö, biri-biri sabölö ahakhö dödöda, me no si manö, ba dua rozi uhalö khögu si''o gubalo; "fa''ebua dödö" ube''e töi zi sara, ba "famaböbö" döi zi sara khögu.', '["Yer 2:8; 23:1","Yer 15:2; 43:11"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 8, 'Ba me ukubalo-baloi mbiri-biri andrö, ba me no utimba gubalo si datölu andrö, barö zi ba sara waŵa, ba anuzu dödögu ira, ba ya''ira göi, ba no sanuzu tödö ya''odo.[4]', '["Yer 2:8; 23:1","Yer 15:2; 43:11"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 9, 'Ba umane: Lö omasido wokubaloi ya''ami: si mate, ba alakha mate ia, ba si tekiko, ba alakha tekiko, ba si tosai na dania, ba hana na faoma la''a nawöra![5]', '["Yer 2:8; 23:1","Yer 15:2; 43:11"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 10, 'Ba utuyu zi''ogu "fa''ebua dödö" andrö, ba ufatö, ba wanudugö fawu''usa li andrö khögu, ba niha baero fefu.', '["Mat 26:15; 27:9","Hez 37:16","Hez 34:2"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 11, 'Ba me tedudugö, me luo da''ö, ba aboto ba dödö mbiri-biri andrö, fondrege zahakhö dödöda, sanöngöni nilaugu, wa no taroma li Yehowa.', '["Mat 26:15; 27:9","Hez 37:16","Hez 34:2"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 12, 'Ba umane khöra: Na lö abua khömi, ba mibe''e luogu, ba na lö mibe''e, ba böi. Ba latulo luogu, 30 rufia.[6]', '["Mat 26:15; 27:9","Hez 37:16","Hez 34:2"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 13, 'Ba imane khögu Yehowa: Fazaumba ba mbate''e girö-girö, mböli soadu andrö, niŵa''öra böligu! Ba uhalö rufia andrö, si 30, ba ufazaumba ba mbate''e girö-girö, ba gosali Yehowa.', '["Mat 26:15; 27:9","Hez 37:16","Hez 34:2"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 14, 'Ba ufatö göi zi''ogu si sara, "famaböbö" andrö, ba wanudugö fa''afatalifusöra mado Yuda Ndraono Gizeraeli.[7]', '["Mat 26:15; 27:9","Hez 37:16","Hez 34:2"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 15, 'Ba imane khögu Yehowa: Halö khöu wakake gubalo sambö tödö;', '["Mat 26:15; 27:9","Hez 37:16","Hez 34:2"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 16, 'Hiza sa, ya''odo zangasogö dania kubalo ba danö, si lö ba dödö si tekiko sa''ae, ba si lö mangalui sisuna ba si lö mamadöhö sokho zesokho, ba si lö mondrorogö si lö fökhö [na], si aga''aga nösi zatabö, ba samabali sa''ara.[8]', '["Mat 26:15; 27:9","Hez 37:16","Hez 34:2"]', NULL),
  (3476514, 'OT', 'Sakharia', 11, 17, 'Alai gubalo andrö, si lö ngaroro, si faröi ba nikubaloi andrö. Ya oköli da''ionia, ba ya aboto hörönia kambölö! Ya oköli sibai da''ionia, ba akha alua mate hörönia kambölö!', '["Mat 26:15; 27:9","Hez 37:16","Hez 34:2"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 1, 'Taroma li. Taroma li Yehowa, nitandrösaigö ba Ndraono Gizeraeli, niŵa''ö Yehowa andrö, samologö banua si yaŵa mege ba solata tanö, ba somböi eheha niha, barö dotonia.[1]', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 2, 'Hiza, ubali''ö mako zalimbuanö niha Yeruzalema, salimbuanö niha baero fefu, si tefasui ya''ira, ba tefarahu göi mado Yuda, na lasuwö Yeruzalema.[2]', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 3, 'Na luo da''ö dania, ba ubali''ö gowe nifazaŵa Yeruzalema, ba niha baero fefu, dozi ha niha ira samazaŵa, ba mesokho; ba dozi soi ba guli danö, ba owulo, udunia.[3]', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 4, 'Ba na luo da''ö, iŵa''ö Yehowa, ba ubözi fa''atokea kudo fefu; ba si fakudo ba hulu, ba ubözi fa''owöhö. Ba ma''uwu Yuda andrö, ba uhörö-hörögö, fatua uhawui bösi kudo niha baero fefu.[4]', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 5, 'Ba lamane dania dödöra salaŵa mado Yuda: We''e-we''e dödö mbanua Yeruzalema Yehowa ngahönö, Lowalangira, we''e-we''e dödö sabe''e!', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 6, 'Na luo da''ö dania, ba timba ndrundrunga ba mbaho ge''u zalaŵa mado Yuda ube''e, ba timba zulu sihola-hola ba mbaho ngamböbö wakhe, ba tobali la''a niha baero fefu, si tefasui ya''ira, he ba gambölö, ba he ba gabera; ba Yeruzalema, ba si lö tebulö ba nahania, lö hadia ia khöra.', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 7, 'I''ofönai''ö wanolo ba nose mado Yuda Yehowa, fa böi fayaŵa ba mado Yuda ma''uwu Dawido ba banua Yeruzalema, ba wa''ebua döira andrö.', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 8, 'Na luo da''ö, ba amaedola ibalugö balusenia Yehowa mbanua Yeruzalema, ba samome khöra, ba no timba Dawido, na luo da''ö, ba ma''uwu Dawido, ba no timba Lowalangi, si mane mala''ika Yehowa andrö, si iagö fönara.', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 9, 'Ba na luo da''ö, ba u''alui wangohori fefu niha baero, si no möi manuwö Yeruzalema.[5]', '["Yes 13:1; 42:5","Yes 51:17,22","Mat 21:44","RazII 6:18","Hez 38:32; Fam 20:9"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 10, 'Ba ba ma''uwu Dawido, ba ba mbanua Yeruzalema, ba ulau Geheha fa''ahakhö dödö, Eheha ba wakaosa, ba latöngöni nifahöra mege, ba la''e''esi ia, nifange''esi ono matua si ha sambu-sambua; mege-ege sibai ira ba khönia, timba wa''abu dödö ba khö nono si a''a.[6]', '["Yer 6:26; Yoel 2:28; Amos 8:10; Yoh 19:34; Fam 1:7","Nga''ötII 35:20","SamII 5:14","MozIV 3:18"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 11, 'Na luo da''ö, ba tesao wange''esi sabölö-bölö, ba Yeruzalema, timba wange''esi no ba Hadandrimo ba danö salo''o, ba Megido.[7]', '["Yer 6:26; Yoel 2:28; Amos 8:10; Yoh 19:34; Fam 1:7","Nga''ötII 35:20","SamII 5:14","MozIV 3:18"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 12, 'Mege-ege niha ba danö fefu, sambu-sambua mado: Si tonia ma''uwu Dawido ba si tonia ndra alawe khöra; ba si tonia ma''uwu Natano ba si manö göi ndra alawe khöra;[8]', '["Yer 6:26; Yoel 2:28; Amos 8:10; Yoh 19:34; Fam 1:7","Nga''ötII 35:20","SamII 5:14","MozIV 3:18"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 13, 'ba si tonia mado Lewi ba si manö göi ndra alawe khöra; ba si tonia ma''uwu Zime''i ba si manö göi ndra alawe khöra;[9]', '["Yer 6:26; Yoel 2:28; Amos 8:10; Yoh 19:34; Fam 1:7","Nga''ötII 35:20","SamII 5:14","MozIV 3:18"]', NULL),
  (3476515, 'OT', 'Sakharia', 12, 14, 'ba si manö madora fefu; sambu-sambua mado, ba si tonia, ba si manö göi ndra alawe khöra.', '["Yer 6:26; Yoel 2:28; Amos 8:10; Yoh 19:34; Fam 1:7","Nga''ötII 35:20","SamII 5:14","MozIV 3:18"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 1, 'Ba na luo da''ö, ba no atöla gumbu ba ma''uwu Dawido ba ba mbanua Yeruzalema, umbu ba wanasai horö ba si ra''i-ra''iö.[1]', '["Hez 47:1; Faigi 14:8","Yer 14:15; Hos 2:17","MozV 13:9","RazII 1:8","Amos 7:14","Sin 22:17"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 2, 'Ba na luo da''ö — iŵa''ö Yehowa ngahönö, ba uhori irege döi nadu, ba danö, ba tobali lö itörö lira sa''ae, ba umanö göi wangohori ba danö sama''ele''ö andrö, fabaya eheha andrö si ra''i-ra''iö.[2]', '["Hez 47:1; Faigi 14:8","Yer 14:15; Hos 2:17","MozV 13:9","RazII 1:8","Amos 7:14","Sin 22:17"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 3, 'Ba na so zui na zabe''e tödö, ba we''amöi sama''ele''ö, ba lamane dania khönia amania ba inania, so''ono ya''ia: Yagö mate, me no ölau waya ba döi Yehowa! Ba satuania, amania ba inania zanaru''ö khönia si''öli, na möi ia sama''ele''ö.[3]', '["Hez 47:1; Faigi 14:8","Yer 14:15; Hos 2:17","MozV 13:9","RazII 1:8","Amos 7:14","Sin 22:17"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 4, 'Ba na luo da''ö, ba dozi sama''ele''ö, ba saila ba gangilatara, na möi ira sama''ele''ö, ba lö''ö sa''ae la''obaru mbaru bu andrö, ba wolimo niha;[4]', '["Hez 47:1; Faigi 14:8","Yer 14:15; Hos 2:17","MozV 13:9","RazII 1:8","Amos 7:14","Sin 22:17"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 5, 'dozi lamane a''ine: Tenga sama''ele''ö ndra''odo, no sangahalö ndra''o; me iraono sibai na ndra''o, ba no lahöli sawuyu ndra''odo.[5]', '["Hez 47:1; Faigi 14:8","Yer 14:15; Hos 2:17","MozV 13:9","RazII 1:8","Amos 7:14","Sin 22:17"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 6, 'Ba na tamanö dania: Ba hadia laheto andrö, ba dötö''amö? ba imane: Me no laböbözido yomo ba nomo zomasi ya''odo![6]', '["Hez 47:1; Faigi 14:8","Yer 14:15; Hos 2:17","MozV 13:9","RazII 1:8","Amos 7:14","Sin 22:17"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 7, 'Faoso, ya''ugö si''öli, khö gubalo andrö khögu, ba niha andrö, sahatö khögu! iŵa''ö Yehowa ngahönö. Lau khö gubalo andrö, ena''ö muzaewe mbiri-biri, ba ena''ö ulau ba niha side-ide.[7]', '["Mat 26:31","Sin 50:15; 91:15; Hos 2:23; FetI 1:7"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 8, 'Ba ba danö ma''asagörö — iŵa''ö Yehowa — ba tobali duata zahori, si mate, ba ha saraö zi tosai ba danö.', '["Mat 26:31","Sin 50:15; 91:15; Hos 2:23; FetI 1:7"]', NULL),
  (3476516, 'OT', 'Sakharia', 13, 9, 'Ba he si saraö andrö, ba ufatörö ba galitö, utunu, nifanunu firö, uhaogö ira, nifangehao ana''a. Da''ö dania zi angaröfi li töigu, ba ufondrondrongo khöra, ba umane dania: Da''ö mbanuagu! ba lamane: He Yehowa, Lowalangigu![8]', '["Mat 26:31","Sin 50:15; 91:15; Hos 2:23; FetI 1:7"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 1, 'Hiza, irugi dania baŵa khö Yehowa, ba yomo ba mbanua khömi lafosasi gondra''ua nirabu ba khömi.', '["Hez 38:14 b.t.","Yes 42:13; Hez 39:4","Amos 1:1","Yes 60:19; Fam 21:23; 22:5"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 2, 'U''owuloi sa''ae dania niha baero fefu, ba wanuwö Yeruzalema, ba atu''a dania ira ba mbanua, ba laraburabu gama-gama ba nomo, ba lahoröni ndra alawe; ba si matonga nösi mbanua, ba ni''oloi''ö, ba si tosai niha, ba tenga nihori ba mbanua.[1]', '["Hez 38:14 b.t.","Yes 42:13; Hez 39:4","Amos 1:1","Yes 60:19; Fam 21:23; 22:5"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 3, 'To''ele dania Yehowa a''i, möi fasuwö ba soi niha andrö, si mane no, me fasuwö ia, me luo wasöndrata andrö.[2]', '["Hez 38:14 b.t.","Yes 42:13; Hez 39:4","Amos 1:1","Yes 60:19; Fam 21:23; 22:5"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 4, 'Ba hili wanikha i''iagö, na luo da''ö, ba hili wanikha andrö ba gamaudu Yeruzalema, tanö ba gatumbukha luo. Ba fabali hili wanikha, i''otarai zuzunia, numalö ba gatumbukha ba ba gaekhula, tobali bawa danö sebolo, miyöu to''ese zi tambai hili ba miraya to''ese zi tambai.', '["Hez 38:14 b.t.","Yes 42:13; Hez 39:4","Amos 1:1","Yes 60:19; Fam 21:23; 22:5"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 5, 'Ba moloi ami, misaŵa mbawa danö andrö, otalua hili andrö khögu — me no ba Gaseli irugi bawa danö andrö, otalua hili — ba soloi ami, si mane me moloi ami ba ziheu no andrö, me luo razo mado Yuda Usia. Ba si to''ele Yehowa, Lowalangigu, ba awönia ni''amoni''ö fefu.[3]', '["Hez 38:14 b.t.","Yes 42:13; Hez 39:4","Amos 1:1","Yes 60:19; Fam 21:23; 22:5"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 6, 'Ba na luo da''ö, ba lö''ö manö moluo, tobali ogömi-gömi zihaga andrö.', '["Hez 38:14 b.t.","Yes 42:13; Hez 39:4","Amos 1:1","Yes 60:19; Fam 21:23; 22:5"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 7, 'Ba ma''ökhö dania — nihonogöi Yehowa — ba tenga si moluo ba tenga si bongi; ba na tanö owi, ba awena moluo.[4]', '["Hez 38:14 b.t.","Yes 42:13; Hez 39:4","Amos 1:1","Yes 60:19; Fam 21:23; 22:5"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 8, 'Na luo da''ö, ba so nidanö gumbu, si oroi moroi yomo ba Yeruzalema, sangele misa: sara zoluaha ba zilua asi tanö ba gatumbukha luo, ba si sara, ba ba nasi tanö ba gaekhula moluaha; faoma, he ba mbaŵa lökhö, ba he ba mbaŵa deu.[5]', '["Yoel 3:18; Faigi 13:1; Fam 22:1","Fam 19:16","Yes 2:2; Yer 38:7; RazII 14:13; Neh 3:1","Fam 22:3"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 9, 'Ba Yehowa razo ba danö, ma''asagörö. Na luo da''ö, ba ha samösa Yehowa, ba töinia, ba ha sambua.[6]', '["Yoel 3:18; Faigi 13:1; Fam 22:1","Fam 19:16","Yes 2:2; Yer 38:7; RazII 14:13; Neh 3:1","Fam 22:3"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 10, 'Tobali salo''o dania danö ma''asagörö, i''otarai Geba, numalö ba Rimono, raya Yeruzalema. Ba Yeruzalema, ba si lö tebulö ba dadaomania andrö, si no alaŵa, i''otarai mbawa göli mado Mbeniyami, irugi naha mbawa göli me föna ba irugi mbawa göli ba watalinga andrö; ba i''otarai malige Hananeli, ba irugi wolazi andrö khö razo.[7]', '["Yoel 3:18; Faigi 13:1; Fam 22:1","Fam 19:16","Yes 2:2; Yer 38:7; RazII 14:13; Neh 3:1","Fam 22:3"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 11, 'Ba soso ira ba da''ö, ba lö fangelifi sa''ae, ba sahono mbanua Yeruzalema, lö hadia ia.[8]', '["Yoel 3:18; Faigi 13:1; Fam 22:1","Fam 19:16","Yes 2:2; Yer 38:7; RazII 14:13; Neh 3:1","Fam 22:3"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 12, 'Ba da''ö wamakao, famözi Yehowa niha baero andrö fefu, si no manuwö Yeruzalema: Mangobou nösira fatua muzizio na ira; höröra, ba obou ba nahania bakha, ba lelara, ba obou ba mbawa.', '[]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 13, 'Na luo da''ö, ba ihawui ira fa''afakuyu sabölö-bölö Yehowa, ba tobali fara''ura''u tanga ira, ba ilau khö nawönia zamösana.', '[]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 14, 'Ba mado Yuda göi zi fasöndra khöra, yomo ba Yeruzalema. Ba te''owuloi dania gana''a niha baero fefu, si fasui, ana''a ba firö ba nukha, si fahöna.', '[]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 15, 'Ba famunu da''ö göi zi göna kudo ba kudo kalide ba ondra ba kalide, urifö niha fefu, si so ba naha zanuwö andrö.', '[]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 16, 'Ba dozi si tosai niha baero andrö fefu, si no möi manuwö Yeruzalema, ba ero röfi möi ira misi yaŵa, ba wangalulu khö Yehowa ngahönö ba ba wolau owasa nose daha geu andrö.[9]', '["Yes 66:23","MozII 39:30","Yes 35:8; Yoel 3:17; Fam 21:7"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 17, 'Ba si lö möi misi yaŵa ba Yeruzalema, soi niha ba guli danö, ba wangalulu khö razo Yehowa ngahönö, ba lö aekhu ba danöra deu.', '["Yes 66:23","MozII 39:30","Yes 35:8; Yoel 3:17; Fam 21:7"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 18, 'Ba na lö möi misi yaŵa Ndrawa Miserayi, na lö ya''ira, ba göna ira famakao andrö, nifatörö Yehowa ba niha baero andrö, si lö möi misi yaŵa, ba wolau owasa nose daha geu.', '["Yes 66:23","MozII 39:30","Yes 35:8; Yoel 3:17; Fam 21:7"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 19, 'Da''ö dania horö Ndrawa Miserayi ba horö niha baero fefu, me lö möi ira misi yaŵa ba wolau owasa nose daha geu.', '["Yes 66:23","MozII 39:30","Yes 35:8; Yoel 3:17; Fam 21:7"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 20, 'Ba na luo da''ö, ba sura ba dete ritiriti andrö ba kudo, ba: "Ni''amoni''ö khö Yehowa!" ba bowoa fondrino andrö ba gosali Yehowa, ba no si mane figa andrö, ba wame''e sumange.[10]', '["Yes 66:23","MozII 39:30","Yes 35:8; Yoel 3:17; Fam 21:7"]', NULL),
  (3476517, 'OT', 'Sakharia', 14, 21, 'Dozi bowoa dania, ba Yeruzalema ba ba mado Yuda, ba no mu''amoni''ö khö Yehowa ngahönö, ba dozi same''e sumange, ba so ira, ba lahalö ösa, ba labe''e fondrino [zumange], ba na luo da''ö ba lö''ö sa''ae saniaga, ba gosali Yehowa ngahönö.[11]', '["Yes 66:23","MozII 39:30","Yes 35:8; Yoel 3:17; Fam 21:7"]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 1, 'Taroma li. Niŵa''ö Yehowa ba Ndraono Gizeraeli, nifa''ema Male''akhi andrö.[1]', '["Yes 13:1"]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 2, 'Imane Yehowa: No u''omasi''ö ami, ba mimane: Heza zi no ö''omasi''ö ndra''aga? Ba imane Yehowa: Hadia, tenga ga''a Yakobo Gezau? ba noa zui u''omasi''ö Yakobo,[2]', '["MozI 25:24 b.t.; Rom 9:13","MozI 36:8; Yer 49:17; Obad a. 18"]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 3, 'ba fa''udu ndra''o khö Gezau, ba no ubali''ö sasai''ö hili andrö khönia; ba tana khönia tanö, ba no ubali''ö tanö si mate, nahia nasu ana''a.[3]', '["MozI 25:24 b.t.; Rom 9:13","MozI 36:8; Yer 49:17; Obad a. 18"]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 4, 'Na lamane Iraono Gedomo: Si no murasa ndra''aga, ba mafuli ma''a''azökhi gadudula andrö, ba imane Yehowa ngahönö andrö: Sotomo ira, ba sanudugö ndra''odo, ba labe''e töira "tanö horö" ba "soi sofönu Yehowa, si lö mamalö-malö".', '[]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 5, 'Ba i''ila hörömi, ba mimane dania: Sebua Yehowa, italu''i nola Ndraono Gizeraeli!', '[]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 6, 'Ono, ba ifosumange namania, ba sangai halöŵö, ba ifosumange zokhö ya''ia. Ba na Ama ndra''o, ba hezo zumangegu? Ba na sokhö ndra''o, ba hezo wangata''ufi ya''odo? iŵa''ö khömi Yehowa ngahönö andrö, ya''ami ere andrö, si lö ba dödö töigu. Ba mimane zui: Hezo zi lö ba dödöma töimö?', '[]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 7, 'Ya''ami, same''e ba naha wame''e sumange andrö khögu roti nita''unöi, ba mimane zui: Hezo zi ta''unö andrö, ni''ohema khöu? Me no miŵa''ö: Meza khö Yehowa andrö, ba no si lö ba dödöda.[4]', '["MozIII 21:8","MozIII 22:22"]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 8, 'Ba na mibe''e sumange zi lö hörö, ba tenga si lö sökhi [miŵa''ö]. Ba na mibe''e zombuyu-mbuyu töla ba sofökhö, ba tenga si lö sökhi göi [miŵa''ö]. Tema be''e buala khö gumandru khöu, hadia, ebua maö dödönia khöu, ba hadia, inehegö ndra''ugö? iŵa''ö Yehowa ngahönö.[5]', '["MozIII 21:8","MozIII 22:22"]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 9, 'Ba iada''e, ba mi''angaröfi li Lowalangi, ena''ö ihakhösi tödö ita — tangami zolau si manö — hadia, so ba khömi zebua dödönia? iŵa''ö Yehowa ngahönö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3399611, 'OT', 'Maleakhi', 1, 10, 'Ena''ö na so zamösa ba khömi sondruhö bawandruhö; fa böi sa''ae mi''ebua''ö galitö ba naha wame''e sumange andrö, si lö boto! Lö omasido ami, iŵa''ö Yehowa ngahönö, ba sumange nibe''e dangami, ba lö ba dödögu.[6]', '["Amos 5:21","Sin 113:3; Sakh 14:16 b.t."]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 11, 'I''otarai sa ba gatumbukha luo, numalö ba gaekhula, wa''ebua döigu, ba niha baero, ba dozi banua, ba tetunu zamohua, sumange döigu, sumange si sökhi; sebua sa döigu ba niha baero, iŵa''ö Yehowa ngahönö.[7]', '["Amos 5:21","Sin 113:3; Sakh 14:16 b.t."]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 12, 'Ba ya''ami, ba salakha milau khönia, wanguma''ö: Meza Yehowa andrö, ba no muta''unöi, ba tana khöda andrö ba da''ö, öda, ba no sanuzu dödöda.', '[]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 13, 'Ba mimane: Wa''ebua wa''akao! ba te khömi, iŵa''ö Yehowa ngahönö, ba mi''ohe gondra''ua ba sombuyu-mbuyu töla ba sofökhö; mibe''e sumange; hadia, somasido da''ö, nibe''e dangami! iŵa''ö Yehowa.', '[]', NULL),
  (3399611, 'OT', 'Maleakhi', 1, 14, 'Ba ni''elifi zi falimo, si so si matua ba gurifönia ba samabu''u hadia ia, ba same''e sumange Zo''aya dania si alawe, si so sala; razo sebua sa ndra''odo, iŵa''ö Yehowa ngahönö, ba sata''u niha döigu, ba niha baero.', '[]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 1, 'Ba iada''e, ba ba khömi tetandrösaigö goroisa andre, ya''ami ere.', '["MozIII 26:16; MozV 28:15"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 2, 'Na lö mifondrondrongo ba na lö mibe''e ba dödömi, ba wamosumange döigu, iŵa''ö Yehowa ngahönö, ba ufatörö khömi wangelifi ba u''elifi wamahuwumi andrö; ba noa sa''ae u''elifi, me lö edöna mibe''e ba dödömi.[1]', '["MozIII 26:16; MozV 28:15"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 3, 'Hiza, utegu dangami, ba ulau ba mbawami golawua, olawua zumange andrö khömi, ba ba da''ö lafao ami.', '["MozIV 25:12","Yer 32:40"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 4, 'Ba aboto dania ba dödömi, wa no ufafa''ema''ö khömi goroisa andrö, ena''ö fawu''usa li khögu ba Ndraono Lewi, iŵa''ö Yehowa ngahönö.[2]', '["MozIV 25:12","Yer 32:40"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 5, 'Fawu''usa ligu andrö khöra, ba no fangorifi ba fa''ohahau dödö, ba ba wangata''ufi ya''odo ube''e khöra, ba no la''ata''ufi ndra''odo, ba no manizi-nizi ira ba döigu andrö.[3]', '["MozIV 25:12","Yer 32:40"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 6, 'Oroisa si ndruhu nifa''emara, ba si lö atulö, ba lö falukha ba mbewera. Ba wa lö sinegu ba ba wa''atulö latörö lalara somasi ndra''o, ba no ato ladönisi mangawuli, ba wondröi lala si lö atulö.[4]', '["Yak 1:25","Yer 18:18"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 7, 'Ba mbewe gere sa, ba böi aefa wamahaö si ndruhu; famobawa lala ta''alui ba mbewenia, me no sinenge Yehowa ngahönö ia.[5]', '["Yak 1:25","Yer 18:18"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 8, 'Ba ya''ami, ba no miröi lala, no ato zi te''ala mibe''e famahaömi andrö, no mifufu wawu''usa li andrö, ba Ndraono Lewi, iŵa''ö Yehowa ngahönö.', '[]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 9, 'Ba ya''odo göi, ba si lö ba dödö ami, ube''e, ba si lö töi, ba zato fefu, me no olifu ami lala andrö khögu, ba me no ebua dödömi zambuana, ba wamahaö andrö.', '[]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 10, 'Hadia, tenga ha samösa namada, ya''ita fefu? Tenga ha samösa Lowalangi somböi ya''ita? Ba hana wa faoma falimo-limo ita khö nawöda, wolau salakha ba wawu''usa li andrö khö ndra tuada?[6]', '["Efes 4:6","Eser 9:1 b.t.; Neh 13:23"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 11, 'Si falimo mado Yuda, ba ba Ndraono Gizeraeli ba ba Yeruzalema, ba no telau zogoro ita; mado Yuda, ba noa sa lalau zalakha ba ni''amoni''ö andrö, khö Yehowa, somasi ia; ba no omasi ira nono Lowalangi bö''ö, ba no la''owalu.[7]', '["Efes 4:6","Eser 9:1 b.t.; Neh 13:23"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 12, 'Yamuhori Yehowa zi lö mörö ba sanedema li, ba nose ma''uwu Yakobo, ba niha andrö, same''e sumange khö Yehowa ngahönö!', '[]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 13, 'Ba da''ö na nilaumi: mihawu taŵa hörö naha wame''e sumange andrö khö Yehowa, ba fege-ege ba fangarö-ngarö, tobali lö''ö sa''ae i''otahögö zumange nibe''emi, ba lö''ö sa''ae ihalö ba dangami zomasi ia.', '["Mat 5:32"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 14, 'Ba mimane: Hana? Me no anehe Lowalangi wolaumö khö ngambatömö me ono matua ndra''ugö ba zi no falimo ndra''ugö, lö lai wa no awöu ia ba fo''omo ba wawu''usa li andrö khöu.[8]', '["Mat 5:32"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 15, 'Ba samösa lö solau si manö, si so tödö na ma''ifu. Ba he wisa dödö zi samösa andrö? Khö Lowalangi i''alui nga''ötö. Ba mi''angelama, tödömi andrö, ba böi manö falimo ndra''ugö khö ngambatöu me ono matua ndra''ugö.[9]', '["MozI 15:3; 16:3","MozV 24:1; Mat 19:8"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 16, 'Me no si fatuwu khögu wanibo andrö, iŵa''ö Yehowa, Lowalangi Ndraono Gizeraeli; ihawui horö mbarunia [solau da''ö], iŵa''ö Yehowa ngahönö. Ba mi''angelama sa''ae, tödömi andrö, ba böi manö falimo ami![10]', '["MozI 15:3; 16:3","MozV 24:1; Mat 19:8"]', NULL),
  (3399612, 'OT', 'Maleakhi', 2, 17, 'Atage Yehowa mibe''e, ba wehedemi andrö, ba mimane: Heza mabe''e atage ndra''ugö? Me miwa''ö: Dozi solau si lö atulö, ba no si sökhi, wamaigi Yehowa, ba no ya''ira zomasi ia: ma hezo na Lowalangi andrö, samatörö huku satulö?', '["MozI 15:3; 16:3","MozV 24:1; Mat 19:8"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 1, 'Hiza ufatenge zinenge andrö khögu, ena''ö ihaogö lala fönagu; ba lö mudöna-döna, ba möi ba gosalinia Zo''aya andrö, ni''aluimi, mala''ika wawu''usa li andrö, somasi ami, zi so; hiza so ia dania, iŵa''ö Yehowa ngahönö.[1]', '["Mat 11:10; Mar 1:2; Luk 1:76; 7:27"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 2, 'Ba ha niha zanaha baŵa wa''asonia andrö, ba ha niha zi tola, na to''ele ia? Me hulö si mane alitö ba zolaugö ana''a ia, ba me hulö si mane idanö nawu ba zamabago nukha.[2]', '["Yer 2:22; Sakh 13:9"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 3, 'Ba dumadao dania ia wolaugö firö andrö ba fangehao ya''ia, ba ihaogö Nono Lewi andrö, iheta zi tenga, nifolau ba gana''a ba ba wirö, ena''ö tobali solohe sumange Yehowa ira, si nangea.[3]', '["Hes 44:15; Sin 5:21"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 4, 'Ba ena''ö omasi dania Yehowa zumange nibe''e mado Yuda, awö nibe''e Yeruzalema, si mane me luo föna sibai, si mane ba götö si no numalö.', '["Hes 44:15; Sin 5:21"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 5, 'Ba möido khömi, ba wanguhuku, ba sasi salio ndra''o, udu zi fakelemu andrö ba udu zohorö, fabaya si möi ba hölu na faya ba sangambösi luo genoni ba samakao lakha mbanua ba si lö ama, si lö ina, ba samuyu''ö huku, ba niha bö''ö, lö fangata''ufi ya''odo, iŵa''ö Yehowa ngohönö.[4]', '["MozII 22:22; MozIII 19:13; Yak 5:4"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 6, 'Ya''odo, sa Yehowa, ba lö si tobali ndra''odo; ba ya''ami, Iraono Gizeraeli, ba lö sahori na ami.[5]', '["MozIV 23:19; Sin 33:1; Amaed 19:21","Sakh 1:3","Neh 13:10"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 7, 'I''otarai götö ndra tuami, ba no mi''erogö gamakhoitagu ba lö ni''o''ömi. Mifuli ami khögu, ba ufulido khömi, iŵa''ö Yehowa ngahönö, ba mimane: Hezo atö nifalalinima era-erama?[6]', '["MozIV 23:19; Sin 33:1; Amaed 19:21","Sakh 1:3","Neh 13:10"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 8, 'Hadia, tola maö ilimo Lowalangi niha, wa milimo ndra''odo? ba mimane: Hezo nilimoma ya''ugö? Ba zi sambua ni''ofulu andrö ba ba zumange nihalö fegero andrö.[7]', '["MozIV 23:19; Sin 33:1; Amaed 19:21","Sakh 1:3","Neh 13:10"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 9, 'Andrö wa no mu''elifi ami, me milimolimo ndra''odo, sambua soi manö ya''ami.', '["MozI 7:11; RazII 7:19"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 10, 'Mi''ohe ba nomo girö-girö zi sambua ni''ofulu, ma''asambua, ena''ö so mbalazo ba nomo andrö khögu, ba mitandraigö ndra''o ba da''ö, iŵa''ö Yehowa ngahönö, na lö ubokai dania khömi mba''a-ba''a andrö ba mbanua si yaŵa, wamaduwa howu-howu khömi, irege zi no fahöna.[8]', '["MozI 7:11; RazII 7:19"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 11, 'Ba utenaŵa khömi damo andrö, fa böi lafakiko mbua danö, ba lö''ö sa''ae khömi si zizimö ba ŵeŵe nagu ba kabu, iŵa''ö Yehowa ngahönö.', '["Yes 62:4; Dan 11:16; Sakh 7:14"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 12, 'Ba lasuno dania ami soi baero, fefu, sohahau tödö ami laŵa''ö; me tanö omasiö sa''ae ami, dania, iŵa''ö Yehowa ngahönö.[9]', '["Yes 62:4; Dan 11:16; Sakh 7:14"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 13, 'Milaŵa ndra''o fehedemi, iŵa''ö Yehowa, ba misofu na: Hadia nifagölösima khöu?', '["Gen 26:5"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 14, 'Mimane: Zaya-zaya gölö wamosumange Lowalangi, ba hadia hare, me tatörö nifakhoinia, ba me ta''onukha nukha ba wange''esi, börö Yehowa ngahönö?[10]', '["Gen 26:5"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 15, 'Ba tasuno sa''ae zi fayaŵa; tenga ha fa no mofozu zolau si lö atulö, noa na göi latandraigö Lowalangi, ba lö fotu.', '["Gen 26:5"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 16, 'Ba fahuhuo zangata''ufi Yehowa, ba ihenegö Lowalangi ba irongo, ba tefazökhi zura fönania, sura famasugi ba dödö, börö zangata''ufi Yehowa andrö, samosumange töinia.[11]', '["Fam 20:12","MozV 7:6; 8:5; Sin 118:24; Sakh 14:7"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 17, 'Ba khögu ira, iŵa''ö Yehowa ngahönö, na no irugi baŵa andrö, ni''asogögu, ba u''orifi ira, si mane fangorifi niha ononia matua samosumange ya''ia.[12]', '["Fam 20:12","MozV 7:6; 8:5; Sin 118:24; Sakh 14:7"]', NULL),
  (3399613, 'OT', 'Maleakhi', 3, 18, 'Ba ifuli dania mi''ila wa''afaehura zatulö zi lö atulö, ba fa''afaehura zamosumange Lowalangi zi lö mamosumange ya''ia.', '[]', NULL),
  (3399614, 'OT', 'Maleakhi', 4, 1, 'Hiza sa, irugi dania baŵa andrö sihola-hola, timba galitö ba wanunu bötua, ba timba mbörö wakhe dania dozi si fayaŵa, awö dozi solau si lö atulö, ba akhozi ibe''e baŵa andrö dania, iŵa''ö Yehowa ngahönö, tobali lö tosai khöra ibe''e, he ŵa''a ba he daha.[1]', '["Faigi 3:2"]', NULL),
  (3399614, 'OT', 'Maleakhi', 4, 2, 'Ba khömi sangata''ufi töigu, ba tumbu luo andrö, fa''atulö, ba fangorifi barö gafinia, ba maoso ami ba manaoka ami, si mane ono zawi nibula.[2]', '["Yer 23:6; Luk 1:78"]', NULL),
  (3399614, 'OT', 'Maleakhi', 4, 3, 'Ba mihundra-hundra zebua horö, awu sa''ae ira barö gahemi, na baŵa da''ö, ni''asogögu dania, iŵa''ö Yehowa ngahönö.', '["Yer 23:6; Luk 1:78"]', NULL),
  (3399614, 'OT', 'Maleakhi', 4, 4, 'Mitöro-törö tödömi goroisa andrö nifa''ema Moze, enonigu andrö, ba ni''oroi''ögu amakhoita ba huku, ba Ndraono Gizeraeli fefu, ba hili Horebi.[3]', '["MozV 4:10"]', NULL),
  (3399614, 'OT', 'Maleakhi', 4, 5, 'Hiza, ufatenge khömi Geliya andrö, sama''ele''ö, gasa-gasa wa irugi baŵa andrö khö Yehowa, sebua ba sata''u ita.[4]', '["Fam 11:1","Mat 11:14; Mar 9:11; Luk 1:17"]', NULL),
  (3399614, 'OT', 'Maleakhi', 4, 6, 'Ba ifuli ba ndraono dödö ndra ama, ba tödö ndraono khö ndra ama, fa böi möi ndra''o, ba wangohori niha ba danö.[5]', '["Fam 11:1","Mat 11:14; Mar 9:11; Luk 1:17"]', NULL),
  (3394460, 'NT', 'Mataio', 1, 1, 'Sura mböröta Yesu Keriso, ma''uwu Dawido andrö, ma''uwu Gaberahamo.', '["Sura mböröta eluahania sura nga''ötö. Ngawalö döi niha bakha ba zura nga''ötö andre no lafaudugö wanurania ba lela Nono Niha. Börö da''ö abua khöda wangalui ba Google ngawalö döi andrö. Ba zi so föna, ena''ö aoha khö ndraono zekola mamahaö ba wangosili Zura Ni''amoni''ö, abölö sökhi na tesura döi andrö molo''ö töi si no fagölö la''ila niha. Fangali ba li Niha böi tobali taha-taha ba wangi''ila."]', NULL),
  (3394460, 'NT', 'Mataio', 1, 2, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394462, 'NT', 'Mataio', 3, 7, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394465, 'NT', 'Mataio', 6, 17, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394468, 'NT', 'Mataio', 9, 20, 'Ba hiza ndra alawe, sendro talu, no mewelendrua fakhe sa''ae; i''ondrasi Yesu moroi furi, ibabaya gahe mbarunia;', '["Faigi 14:36"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 21, 'imane sa dödönia: He ha barunia ubabaya, ba döhö wökhögu.[10]', '["Faigi 14:36"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 22, 'Ba ibali''ö ia Yesu, i''ila ba imane: Böi ata''ufi, onogu; no i''orifi ndra''ugö famatimö andrö. Ba abe''e ndra alawe andrö, i''otarai da''ö sibai.', '[]', NULL),
  (3394468, 'NT', 'Mataio', 9, 23, 'Ba me irugi nomo zalaŵa no mege Yesu, me i''ila zolau sigu, awö niha sato, si fagua-gua, ba imane:[11]', '["Yer 9:17","Yoh 11:11"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 24, 'Miheta ami, tenga sa si mate nono alawe andrö, si mörö. Ba la''igi-igi''ö ia.[12]', '["Yer 9:17","Yoh 11:11"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 25, 'Ba me no tefofanö baero niha sato, ba möi ia si bakha, ira''u danga, ba maoso nono alawe andrö.', '[]', NULL),
  (3394468, 'NT', 'Mataio', 9, 26, 'Ba humöngö duria da''ö ba danö andrö, ma''asagörö.[13]', '["Luk 7:17"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 27, 'Ba me mofanö Yesu ba da''ö, ba la''o''ö ia niha sau''a, darua, mu''ao ira, lamane: Hakhösi tödö ndra''aga, ma''uwu Dawido![14]', '["Faigi 20:30"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 28, 'Ba me möi ia yomo, ba la''ondrasi ia sau''a andrö, ba imane khöra Yesu: Hadia, faduhu dödömi, u''ila ulau da''ö? Lamane khönia: Faduhu dödöma, Tua.', '[]', NULL),
  (3394468, 'NT', 'Mataio', 9, 29, 'Awena ibabaya höröra, imane: Ya''itörö zi faduhu dödömi.[15]', '["Faigi 8:13"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 30, 'Ba teboka höröra. Ba itenaŵa sibai ira Yesu, imane: Mifaigi, böi irongo da''ö niha, gofu ha niha.[16]', '["Faigi 12:16; Mar 1:44"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 31, 'Ba möi ira baero, ba la''ombakha''ö ia ba danö andrö ma''asagörö.', '["Faigi 12:16; Mar 1:44"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 32, 'Ba me no möi ira baero, ba hiza, la''ohe khönia niha si lö hede, sobekhu.[17]', '["Faigi 12:22"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 33, 'Ba me no tefofanö mbekhu andrö, ba humede zi lö hede no mege, ba ahöli-höli dödö niha sato, lamane: Lö irai oroma zi manö ba Ndraono Gizeraeli.', '[]', NULL),
  (3394468, 'NT', 'Mataio', 9, 34, 'Ba lamane farizaio: Moroi ba zalaŵa mbekhu andrö, wa ifofanö mbekhu.[18] [19]', '["Faigi 12:24; Mar 3:22","Moroi ba zalaŵa mbekhu eluahania tola ifofanö mbekhu andrö börö wamataro zalaŵa mbekhu."]', NULL),
  (3394468, 'NT', 'Mataio', 9, 35, 'Ba itöröi mbanua sebua awö mbanua side-ide Yesu, mamahaö ia ba zekola khöra, manuriagö turia mbanua Lowalangi andrö, turia somuso dödö, ba ifadöhö fefu ngawalö wökhö ba fefu ngawalö wa''atebai.[20]', '["Faigi 4:23"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 36, 'Ba me i''ila niha sato, ba ahakhö dödönia ira, me no nifakao ira, nifazaewe, hulö mbiri-biri, si lö kubalo.[21]', '["Hes 34:4,5; Mar 6:34"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 37, 'Ba imane khö ndra nifahaönia: Ebolo sa mbasitö, ba lö ato zohalöŵö.[22]', '["Luk 10:2"]', NULL),
  (3394468, 'NT', 'Mataio', 9, 38, 'Andrö mi''andrö khö zokhö basitö andrö, ena''ö ifatenge zohalöŵö ba mbasitönia.', '["Luk 10:2"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 1, 'Ba humede ia ba nifahaönia andrö,[1] si felendrua, itehe khöra, wolaŵa bekhu si ra''iö, ena''ö lafofanö ba ena''ö lafadöhö fefu ngawalö wökhö ba fefu ngaŵalö wa''atebai.', '["Ayati 1–15: Mar 3:13–19; 6:7–13: Luk 6:14–16; 9:1–6"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 2, 'Da''e döi zinenge andrö, si felendrua: Si föföna Zimoni, nifotöi Fetero ba Andrea, talifusönia; ba Yakobo, ono Zebedaio ba talifusönia Yohane,[2]', '["HalZin 1:13"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 3, 'ba Filifo ba Batolomaio, ba Toma ba Mataio, sanema beo andrö, ba Yakobo, ono Galifaio ba Lebaio,', '["HalZin 1:13"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 4, 'ba Simoni selote, ba Yuda, banua Kariota, si manga mbölinia dania.', '["HalZin 1:13"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 5, 'Si felendrua andrö nifatenge Yesu ba iŵa''ö li khöra, imane: Böi misaŵa lala niha baero ba böi mi''ae ba mbanua Ndrawa Zamaria andrö.', '["Faigi 15:24; HalZin 13:46"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 6, 'Ba mbiri-biri sisuna andrö, ma''uwu Gizeraeli mi''ae''e.[3]', '["Faigi 15:24; HalZin 13:46"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 7, 'Mi''ae''e ba mi''angombakha, mimane: No ahatö mbanua zorugo andrö.[4]', '["Faigi 4:17; Luk 10:9","Mar 16:17 b.t.; HalZin 8:20"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 8, 'Mifadöhö wökhö zofökhö, ba misusugi zi mate, ba mifadöhö mbou auri ba mifofanö mbekhu. Lö nibe''emi böli, ba böi göi mihalö mböli.[5]', '["Faigi 4:17; Luk 10:9","Mar 16:17 b.t.; HalZin 8:20"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 9, 'Böi mi''ohe gana''a ba böi göi firö ba böi göi kefe, ba mböbö talumi.[6]', '["Luk 22:35"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 10, 'Böi mamola ami ba lala, böi dombua mbarumi, böi mobadagahe ami ba böi mani''o, noa sa si nangea labe''e gö ba zohalöŵö.[7]', '["Luk 10:7; KorI 9:7,14; TimI 5:18"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 11, 'Ba ba zi möi ami ba mbanua sebua, ba ma ba mbanua side-ide, ba mizofu-zofu ha niha zi nangea ba da''ö, ba ba da''ö mi''iagö, irege mofanö ami.', '[]', NULL),
  (3394469, 'NT', 'Mataio', 10, 12, 'Ba na möi ami yomo ba nomo, ba mi''owai ira.[8]', '["Luk 10:5,6"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 13, 'Ba na si nangea nomo andrö, ba yafalukha ia wa''ohahau dödö andrö khömi. Ba na tenga si nangea ia, ba yamangawuli khömi wa''ohahau dödö andrö khömi.', '["Luk 10:5,6"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 14, 'Ba na so zi lö mama''amöi yomo ya''ami ba si lö mamondrongo limi, ba miheta ami ba nomo andrö ba ba mbanua andrö, mi''anotogö gawu-gawu ba gahemi.[9]', '["HalZin 13:51; 18:6","Faigi 11:24"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 15, 'Si ndruhu niŵa''ögu khömi, öna-öna na zi göna mbanua Zodoma ba banua Gomora andrö, na luo wanguhuku, moroi ba zi göna mbanua andrö.[10]', '["HalZin 13:51; 18:6","Faigi 11:24"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 16, 'Hiza, ufatenge ami, hulö mbiri-biri, ba hunö nasu gatua. Andrö ya''onekhe ami, si mane ulö ba ya''atulö ami, si mane marafadi.[11]', '["Luk 10:2; HalZin 23:6"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 17, 'Ba mi''angelamaisi niha;[12] la''ohe sa dania ami ba rafe, ba ba zekola khöra, labözi-bözi dania ami.[13]', '["Ayati 17–22: Mar 13:9–13","Faigi 24:9; Luk 21:12; HalZin 5:40","HalZin 25, 23"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 18, 'Ba ba gumandru ba ba razo te''ohe ami, börö ndra''o, ba wamaduhu''ö khöra ba ba niha baero.[14]', '["Ayati 17–22: Mar 13:9–13","Faigi 24:9; Luk 21:12; HalZin 5:40","HalZin 25, 23"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 19, 'Ba na labe''e ba dangara ami, ba böi mi''abusi tödö he miwisa ba hadia niŵa''ömi; tebe''e sa khömi dania, ba da''ö sibai, hadia niŵa''ömi.[15]', '["Luk 12:11,12"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 20, 'Tenga sa ya''ami zihede, Eheha Namami andrö zihede, na humede ami.', '["Luk 12:11,12"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 21, 'Ibe''e dania nibunu dalifusönia niha, ba ibe''e nibunu nononia ama, ba maoso ndraono, udu ndra amara, labunu.', '["Luk 21, 16. 17. Yoh 15, 18–21. F. 24, 13"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 22, 'Ba dozi ira dania fa''udu khömi, börö döigu. Ba sanau ölö, irugi gamozua, da''ö ni''orifi.[16]', '["Luk 21, 16. 17. Yoh 15, 18–21. F. 24, 13"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 23, 'Ba na lagohi ami ba mbanua si sambua, ba mi''oloi, misa ŵa mbanua bö''ö. Si ndruhu niŵa''ögu khömi: Lö fakhamö mi dozigö mbanua Ndraono Gizeraeli irege so Nono Niha.', '["Yoh 13:16; 15:20"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 24, 'Tenga sebua moroi khö zamahaö nifahaö, ba tenga sebua moroi khö zokhö ya''ia zawuyu.[17]', '["Yoh 13:16; 15:20"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 25, 'Abönö sa''ae khö nifahaö, na tobali faoma ira zamahaö ya''ia, ba na faoma ira zokhö zawuyu. Na no labe''e töi zokhö omo Mbelesebu, ba tenga mendrua manö lamanö göi ba zoroiyomonia?[18]', '["Faigi 12, 24"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 26, 'Andrö böi mi''ata''ufi ira.[19] Lö''ö sa hadia ia nibalugö, si lö tefa''ele''ö dania, ba lö nibini''ö, si lö aboto ba dödö dania.[20]', '["Ayati 26–33: Luk 12:2–9","Mar 4:22; Luk 8:17"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 27, 'Hadia niŵa''ögu khömi ba zogömi-gömi, ba niŵa''ö ba zohaga; ba hadia nirongomi tögi dalingami, ba mituriagö ba mbawa duwu-tuwu.', '[]', NULL),
  (3394469, 'NT', 'Mataio', 10, 28, 'Ba böi mi''ata''ufi zamunu boto, si tebai mamunu noso. Ba mendrua manö mi''ata''ufi zangila mamakiko noso, fabaya boto, ba narako.', '[]', NULL),
  (3394469, 'NT', 'Mataio', 10, 29, 'Tenga dombua zakefe, na la''amawa ziliŵi nali? ba sambua lö aekhu tou ba danö da''ö, na tenga moroi khö Namami andrö;', '[]', NULL),
  (3394469, 'NT', 'Mataio', 10, 30, 'ba ba khömi, ba no te''erai göi rozi mbu fefu, ba högö yaŵa.', '[]', NULL),
  (3394469, 'NT', 'Mataio', 10, 31, 'Andrö böi ata''u ami; no tohude ami moroi ba ziliŵi nali, he ŵa''ae oya ira.', '[]', NULL),
  (3394469, 'NT', 'Mataio', 10, 32, 'Ba dozi ha niha zamaduhu''ö ya''o ba niha, da''ö göi nifaduhu''ögu khö Namagu, si so ba zorugo.[21]', '["Rom 10:9,10","Luk 9:26; TimII 2:12"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 33, 'Ba sangosilö''ögö ya''o ba niha, ba u''osilö''ögö göi khö Namagu, si so ba zorugo.[22]', '["Rom 10:9,10","Luk 9:26; TimII 2:12"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 34, 'Böi miŵa''ö tödömi, ba wolohe fa''atulö ba guli danö so ndra''o; tenga ba wolohe fa''atulö möi ndra''o, ba wolohe fasöndrata möido.', '[]', NULL),
  (3394469, 'NT', 'Mataio', 10, 35, 'Ba wama''udu niha khö namania möi ndra''o, ba ba wama''udu ono alawe khö ninania ba ba wama''udu umönö ira alawe khö ninania matuania,[23]', '["Mikh 7:6"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 36, 'ba si fa''udu ba niha dania zoroiyomonia.', '["Mikh 7:6"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 37, 'Ha niha zomasi amania, ba ma inania, moroi ba wa''omasinia ndra''o, ba tenga si nangea khögu da''ö; ba ha niha zomasi ononia matua, ba ma ononia alawe, moroi ba wa''omasinia ndra''o, ba tenga si nangea khögu.[24]', '["MozV 13:6 b.t.; Luk 14:26"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 38, 'Ba ha niha zi lö manuyu röfania, ba wolo''ö ya''o, ba tenga si nangea khögu.[25]', '["Faigi 16:24 b.t.; Luk 14:26"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 39, 'Khö zanöndra nosonia aetu ia, ba ha niha zaetu noso, na börö ndra''o, da''ö zanöndra ya''ia.[26]', '["Luk 17:33; Yoh 12:25"]', NULL),
  (3394469, 'NT', 'Mataio', 10, 40, 'Sama''amöi yomo ya''ami, ba ifa''amöi yomo ndra''o, ba sama''amöi yomo ya''o, ba ifa''amöi yomo zamatenge ya''o andrö.[27]', '["Faigi 18:5; Yoh 13:20","SalI 17:10 b.t.; SalII 4:8 b.t."]', NULL),
  (3394469, 'NT', 'Mataio', 10, 41, 'Sama''amöi yomo sama''ele''ö, me no sama''ele''ö döinia, ba itema luo zama''ele''ö, ba sama''amöi yomo satulö, me no satulö döinia, ba itema luo zatulö.[28]', '["Faigi 18:5; Yoh 13:20","SalI 17:10 b.t.; SalII 4:8 b.t."]', NULL),
  (3394469, 'NT', 'Mataio', 10, 42, 'Ba ha niha zamabadugö si samba mako idanö kafu, he ha da''ö, ba zi samösa, side-ide andre, me no nifahaö döinia, ba si ndruhu niŵa''ögu khömi, tebai aekhu luonia.[29]', '["Faigi 25:40; Mar 9:41"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 1, 'Ba me no i''o''ozui Yesu wamobawa lala andrö ba nifahaönia si felendrua andrö, ba mofanö ia ba da''ö, möi ia mamahaö ba mangombakha ba mbanua khöra misa.', '[]', NULL),
  (3394470, 'NT', 'Mataio', 11, 2, 'Ba me irongo nifazökhi Yesu Yohane andrö,[1] ba gurunga, ba ifatenge nifahaönia,[2]', '["Ayati 2–6: Luk 7:18–23","Faigi 14:3","MozV 18:15"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 3, 'ifasofu''ö khönia, imane: Hadia, ya''ugö zi möi andrö, ma mabalo-baloi danö bö''ö?[3]', '["Ayati 2–6: Luk 7:18–23","Faigi 14:3","MozV 18:15"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 4, 'Ba itema lira Yesu, imane khöra: Mi''ae mi''ombakha''ö khö Yohane nirongomi, awö ni''ila hörömi andrö.', '["Faigi 15:30,31; Yes 35:5; 61:1)"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 5, 'Ifuli la''ila niha sau''a, ba mowaö-waö zombuyu-mbuyu töla, döhö mbou auri ba larongo li niha safiso, ba maoso zi mate, ba ba zi numana te''ombakha''ö duria somuso dödö,[4]', '["Faigi 15:30,31; Yes 35:5; 61:1)"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 6, 'ba ya''ahowu ba zi lö fatuwu ndra''o.', '["Faigi 15:30,31; Yes 35:5; 61:1)"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 7, 'Ba me no mofanö da''ö,[5] ba ibörötaigö Yesu, imane ba niha sato, ba khö Yohane andrö: Hadia nifaigimi, wa möi baero ami ba danö si mate? Hadia, sukhu, nifaheu-heu nangi?', '["Ayati 7–19: Luk 7:24–35"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 8, 'Ma hadia, wa möi baero ami? Hadia, ba wamaigi niha sonukha sombuyu-mbuyu? Hiza, ba nomo razo so zonukha sombuyu-mbuyu.', '[]', NULL),
  (3394470, 'NT', 'Mataio', 11, 9, 'Ma hadia, wa möi baero ami? Hadia, ba wamaigi sama''ele''ö? Si ndruhu niŵa''ögu khömi, si töra sama''ele''ö.[6]', '["Luk 1:76","Mal 3:1; Mar 1:2"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 10, 'Ya''ia zi so ba zura: "Hiza, ufowaö-waö fönau zinengegu, sangehao lalamö fönau."[7]', '["Luk 1:76","Mal 3:1; Mar 1:2"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 11, 'Si ndruhu niŵa''ögu khömi, lö irai so zebua moroi khö Yohane andrö, samayagö idanö, ba ni''adonogö ndra alawe, ba fondrege zide-ide ba mbanua zorugo andrö ba no ebua moroi khönia.', '[]', NULL),
  (3394470, 'NT', 'Mataio', 11, 12, 'Ba i''otarai luo Yohane andrö, samayagö idanö, irugi da''e, ba teforege wangalui banua zorugo andrö, ba samorege andrö, da''ö zondra''u ya''ia khöra.[8]', '["Luk 16:16"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 13, 'Noa sa mama''ele''ö zama''ele''ö andrö fefu, awö goroisa, irugi Yohane,', '["Luk 16:16"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 14, 'ba na edöna ami, ba ya''ia Geliya andrö, niŵa''ö si so.', '["Luk 16:16"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 15, 'Si so tögi dalinga, ba yamufondrondrongo![9]', '["Faigi 13:9"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 16, 'Ba ha khö ufaudugö niha andre? Amaedola ndraono ira, sidadao ba kade,', '[]', NULL),
  (3394470, 'NT', 'Mataio', 11, 17, 'si''ao ba nawöra, lamane: No malau zigu khömi, ba lö solaya ami, no me''e ndra''aga, ba lö sabu dödömi.', '[]', NULL),
  (3394470, 'NT', 'Mataio', 11, 18, 'Noa sa so Yohane andrö, lö manga ba lö mamadu-madu hadia ia, ba lamane: Sobekhu.[10]', '["Faigi 3:4"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 19, 'Ba no so Nono Niha, manga-manga ba mamadu-madu hadia ia, ba lamane: Hiza niha solu''a-lu''a, samadu-madu agu, si fahuwu ba zanema beo andrö ba ba zebua horö; ba tobali sa famu''a ba hulu wa''atua-tua andrö nifazökhi dangania.[11]', '["Faigi 9:10; Yoh 2:2"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 20, 'Ba da''ö ibörötaigö ihede-hede''ö mbanua andrö, ba zoya tefazökhi tandra andrö khönia, me lö nifalalinira era-erara, imane:', '[]', NULL),
  (3394470, 'NT', 'Mataio', 11, 21, 'Alai ndra''ugö, khorasi! alai ndra''ugö, Betisa''ida! Na ba Diro ba na ba Zidona mena''ö tefazökhi dandra andrö, nifazökhi ba khömi andrö, ba na föna sa''ae lafalalini gera-era mena''ö, no la''onukha goni, ba no lalau nawu ba högöra mena''ö.[12]', '["Hes 26 ba 27; Yob 42:6"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 22, 'Ba uŵa''ö na khömi: Öna-öna na zi göna Diro ba Sidona, na luo wanguhuku andrö, moroi ba zi göna ami.', '["Hes 26 ba 27; Yob 42:6"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 23, 'Ba ya''ugö, Kafanauma, tenga no mu''alaŵa''ö ndra''ugö, irugi mbanua si yaŵa? Irugi mbanua tou tetibo''ö ndra''ugö dania. Na ba Zodoma mena''ö tefazökhi dandra andrö, nifazökhi ba khömö andrö, ba lö si tebulö ia mena''ö, irugi ma''ökhö andre.', '["Faigi 10:15; Luk 12:47"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 24, 'Ba uŵa''ö na khömi: Öna-öna na zi göna mbanua Zodoma andrö, na luo wanguhuku andrö, moroi ba zi göna ndra''ugö.[13]', '["Faigi 10:15; Luk 12:47"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 25, 'Me luo da''ö humede Yesu, imane: usuno ndra''ugö, Ama, Sokhö sorugo, awö danö, me no öbini''ö da''ö ba zatua-tua, awö ba zonekhe, ba me no öfa''ele''ö ia ba ndraono.[14]', '["Faigi 5:3; KorI 1:19–29"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 26, 'Ya''ia, Ama, me no wa''omasiu zi manö.', '["Yoh 1:18; 3:35; 14:6; Faigi 28:18"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 27, 'Fefu hadia ia, ba no ibe''e ba dangagu Amagu. Ba lö saboto ba dödö Ono, baero Nama, ba lö saboto ba dödö Ama, baero Nono, awö ba zedöna ifa''ele''ö Ono.[15]', '["Yoh 1:18; 3:35; 14:6; Faigi 28:18"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 28, 'Mi''aine khögu, dozi serege tödö, awö zonoro, ba ufolombase ami.[16]', '["Yer 31:25","Sakh 9:9; Fil 2:5 b.t.","YohI 5:3"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 29, 'Mihare''ö khömi kalo mbagi andrö khögu ba mitöngöni khögu, me no sebolo tödö ndra''o ba si lö fayaŵa tödö, ba falukha ami wolombase dödömi.[17]', '["Yer 31:25","Sakh 9:9; Fil 2:5 b.t.","YohI 5:3"]', NULL),
  (3394470, 'NT', 'Mataio', 11, 30, 'Moguna sa kalo mbagi andrö, khögu, ba no aoha noro andrö khögu.[18]', '["Yer 31:25","Sakh 9:9; Fil 2:5 b.t.","YohI 5:3"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 1, 'Me luo da''ö itörö nowi Yesu,[1] me luo sabato, ba no olofo nifahaönia ba labörötaigö ladödöni lai wakhe ba la''a nösi.[2]', '["Ayati 1–8: Mar 2:23–28; Luk 6:1–5","MozV 23:25"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 2, 'Ba me la''ila da''ö farizaio, ba lamane khönia: Hiza, lalau zi lö tola ba luo sabato ira nifahaömö.', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 3, 'Ba imane khöra: Hadia, lö ni''ilami ba zura, he iwisa Dawido, me olofo ia, ba awönia fao?[3]', '["SamI 21:6","MozIII 24:5–9; MozII 29:32–33"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 4, 'Me möi ia ba nomo Lowalangi, ba me la''a roti nifaigi-faigi andrö, si lö tola i''a ba si lö tola la''a awönia fao? ha ere zi tola manga da''ö.[4]', '["SamI 21:6","MozIII 24:5–9; MozII 29:32–33"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 5, 'Ba lö ni''ilami ba zura goroisa andrö, wa lö la''amoni''ö luo sabato ere ba gosali, ba lö salara?[5]', '["MozIV 28:9 b.t."]', NULL),
  (3394471, 'NT', 'Mataio', 12, 6, 'Ba uŵa''ö khömi, no so ba da''e zebua moroi ba gosali.', '["MozIV 28:9 b.t."]', NULL),
  (3394471, 'NT', 'Mataio', 12, 7, 'Ba na aboto ba dödömi ena''ö, hadia geluaha niŵa''ö andrö: "Fa''ahakhö dödö zomasido, ba tenga sumange", ba lö mihuku ena''ö zi lö sala.[6]', '["Faigi 9:13; Hos 6:6"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 8, 'So''aya luo sabato sa Nono Niha.', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 9, 'Ba mofanö ia ba da''ö,[7] möi ia ba zekola khöra.', '["Ayati 9–14: Mar 3:1–6; Luk 6:6–11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394471, 'NT', 'Mataio', 12, 10, 'Ba hiza niha si no ariri tanga, si sara. Ba lasofu khönia, lamane: Hadia, tola mamadöhö fökhö na luo sabato? ba wangadugö ya''ia.[8]', '["Luk 13:14; 14:3 b.t."]', NULL),
  (3394471, 'NT', 'Mataio', 12, 11, 'Ba imane khöra: Ha niha ba khömi, si so biri-biri, sageu, si lö mondra''u da''ö, ba wanöbi yaŵa, na aekhu ba dögi, na luo sabato?', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 12, 'Ba he zi sökhi ira niha mbiri-biri? Tobali tola tafazökhi zi sökhi na luo sabato.', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 13, 'Awena iŵa''ö ba niha andrö: Oro''ö dangau andrö! Ba i''oro''ö. Ba ifuli sökhi si mane si sara.', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 14, 'Ba möi baero warizaio, mamagölö, ba khönia andrö, ba wamunu ya''ia.[9]', '["Yoh 5:16–18"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 15, 'Ba me aboto da''ö ba dödö Yesu, ba iheta ia ba da''ö. Ba ato zolo''ö ya''ia ba ifadöhö wökhöra fefu.', '["Faigi 9:30"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 16, 'Ba itenaŵa ira, fa lö la''ombakha''ö ia.[10]', '["Faigi 9:30"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 17, 'Ena''ö itörö niŵa''ö Yesaya andrö, sama''ele''ö, me imane:', '["Yes 42:1–4; 11:2","Rom 15:12"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 18, '"Hiza genonigu andrö, nituyugu, ni''omasi''ögu, somasi dödögu andrö, ube''e khönia Gehehagu, ba i''ombakha''ö huku ba niha baero.[11]', '["Yes 42:1–4; 11:2","Rom 15:12"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 19, 'Lö fasoso ia ba lö mu''ao-ao ba lö larongo linia ba newali misa.', '["Yes 42:1–4; 11:2","Rom 15:12"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 20, 'Ono geu si no tefatö, ba lö ifalua ifatö ba fandru si lö hola-hola sa''ae, ba lö ibunu, irege möna huku ibe''e.', '["Yes 42:1–4; 11:2","Rom 15:12"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 21, 'Ba ba döinia dania manötöna niha baero."[12]', '["Yes 42:1–4; 11:2","Rom 15:12"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 22, 'Aefa da''ö,[13] ba la''ohe khönia zobekhu, sau''a ba si lö hede, ba ifadöhö, tobali muhede zi lö hede andrö ba i''ila niha.[14]', '["Ayati 22–32: Mar 3:22–30; Luk 11:14–23","Faigi 9:32"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 23, 'Ba tobali dödö niha sato fefu ba lamane: Hadia, tenga ma''uwu Dawido andrö da''ö?', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 24, 'Ba lamane farizaio, me larongo da''ö: Lö ifofanö mbekhu da''ö, na tenga moroi khö Mbelesebu, salaŵa mbekhu andrö.[15]', '["Faigi 9:34"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 25, 'Ba me no i''ila gera-erara, ba imane khöra: Dozi öri adudu, na no fabali dödö; ba dozi banua ba dozi omo, ba lö fakhai, na no fabali dödö.', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 26, 'Ba na ifofanö Zatana Satana, ba noa sa''ae fabali dödönia, ba he wisa wa''aro mbanuania?', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 27, 'Ba na moroi khö Mbelesebu, wa ufofanö mbekhu ba ha khö moroi, wa lafofanö iraonomi? Andrö ya''ira dania zanguhuku ya''ami.', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 28, 'Ba na moroi khö Geheha Lowalangi, wa ufofanö mbekhu, ba noa sa''ae i''ondrasi ami banua Lowalangi andrö.[16]', '["YohI 3:8"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 29, 'Ba he wisa niha we''amöi yomo ba nomo zabölö, ba worabu gama-gamania, na lö ihönagö iböbö zabölö andrö? ba awena i''osindra''ui hadia ia ba nomonia.[17]', '["Yes 49:24"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 30, 'Si lö fao khögu, ba no si fa''udu khögu, ba si lö mangozara, awögu, ba samazaewe.[18]', '["Mar 9:40"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 31, 'Andrö uŵa''ö khömi: Fefu hadia ia horö ba fefu hadia ia wanandraŵa, ba te''efa''ö ba niha; ba fanandraŵaisi Eheha andrö, ba lö te''efa''ö.[19]', '["Heb 6:4–6; 10:26"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 32, 'Ba na so zamöbögö hadia ia khö Nono Niha ba te''efa''ö khönia; ba na so zamöbögö hadia ia khö Geheha ni''amoni''ö, ba lö te''efa''ö khönia, he ba götö da''e, ba he ba götö dania.[20]', '["Luk 12:10"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 33, 'Sökhi döla geu mibe''e, ba si sökhi mbuania, ba na lö''ö, ba sobou döla geu mibe''e, ba sobou mbuania. Ba mbua sa aboto ba dödöda döla geu.[21]', '["Faigi 7:17; Luk 6:44"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 34, 'He ya''ami, ono gulö! he moroi mi''ila miŵa''ö zi sökhi, me no si lö sökhi ami? Hadia sa zi no fahöna ba dödö, da''ö zalua ba mbewe.[22]', '["Faigi 3:7","Luk 6:45"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 35, 'Isao''ö baero zi sökhi niha si sökhi, moroi ba girö-girö si sökhi andrö; ba niha si lö sökhi, ba isao''ö baero zi lö sökhi andrö.[23]', '["Faigi 3:7","Luk 6:45"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 36, 'Ba uŵa''ö khömi, tezofu-zofu dania, na luo wanguhuku, fefu ngawalö wehede si lö guna, nilau niha.[24]', '["Efes 4:29"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 37, 'Moroi ba wehedemö sa satulö ndra''ugö dania, ba moroi ba wehedemö te''etu''ö hukumö.', '["Efes 4:29"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 38, 'Ba so ösa zanema linia,[25] sangila amakhoita ba farizaio, lamane: He samahaö, omasiga ma''ila dandra khömö.[26]', '["Ayati 38–42: Luk 11:16,29–32","Faigi 16:1 b.t.; Yoh 6:30"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 39, 'Ba itema lira, imane khöra: La''andrö dandra niha andre, si lö sökhi, sohorö-horö, ba lö tebe''e khöra dandra, ha tandra khö Yona sama''ele''ö andrö.[27]', '["Faigi 16:4"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 40, 'Hulö si mane Yona sa, me tölu ngaluo tölu mbongi ia ba dalu gi''a sebua andrö, si manö göi Nono Niha dania, tölu ngaluo tölu mbongi dania ia ba hunö danö.[28]', '["Yon 2:1"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 41, 'Maoso dania mbanua Niniwe andrö, na luo wanguhuku, udu niha da''e ba la''etu''ö huku niha da''e; me no lafalalini gera-erara ba wangombakha Yona andrö, ba hiza, so ba da''e zebua moroi khö Yona.[29]', '["Yon 3:5 b.t."]', NULL),
  (3394471, 'NT', 'Mataio', 12, 42, 'Maoso dania razo ira alawe andrö, moroi raya, na luo wanguhuku, udu niha da''e, ba i''etu''ö huku niha da''e, me no möi ia moroi ba wondrege danö, ba wamondrongo fa''atua-tua Zelomo andrö; ba hiza, so ba da''e zebua moroi khö Zelomo.[30]', '["SalI 10:1 b.t."]', NULL),
  (3394471, 'NT', 'Mataio', 12, 43, 'Ba na aheta mbekhu si ra''iö ba niha,[31] ba itöröi danö si lö idanö, mangalui nahia wolombase, ba lö isöndra.', '["Ayati 43–45: Luk 11:24–26"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 44, 'Awena dania imane: Da''ufulido ba nomogu, ba zi otarai ndra''o. Ba na so ia, ba lö mu''onahia i''ila, ba no labözini ba no lahaogö.', '["Ayati 43–45: Luk 11:24–26"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 45, 'Ba möi ia, ihalö awönia mbekhu bö''ö, dafitu, safaito moroi khönia, ba möi ira bakha, labe''e nahiara da''ö, ba tobali tedou walösökhi zafuria ba niha andrö, moroi ba zi föföna mege. Si manö göi dania ba niha si lö sökhi andre.[32]', '["FetII 2:20"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 46, 'Ba lö nibatonia na huhuonia andrö ba niha sato,[33] ba hiza ninania, awö ndra talifusönia, so ira baero, la''alui lala, so niŵa''öra khönia.[34]', '["Ayati 46–50: Mar 3:31–35; Luk 8:19–21","Yoh 7:5"]', NULL),
  (3394471, 'NT', 'Mataio', 12, 47, 'Ba so zanguma''ö khönia: Hiza baero ninau, awö ndra talifusöu, la''alui lala, so niŵa''öra khöu.[35]', '["Faigi 13:57)."]', NULL),
  (3394471, 'NT', 'Mataio', 12, 48, 'Ba itema li, imane ba zanguma''ö khönia: Ha niha ninagu, ba ha niha dalifusögu?', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 49, 'Ba i''oro''ö dangania, yaŵa ndra nifahaönia, imane: Ya''e ninagu ba talifusögu!', '[]', NULL),
  (3394471, 'NT', 'Mataio', 12, 50, 'Ha niha sa zolo''ö somasi Namagu andrö, si so ba zorugo, da''ö dalifusögu matua ba talifusögu alawe ba inagu.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 1, 'Me luo da''ö möi baero Yesu,[1] mudadao ia ba zinga mbaŵa andrö.', '["Ayati 1–23: Mar 4:1–20; Luk 8:4–15"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 2, 'Ba ato zowulo khönia niha, ba möi ia baowo ba mudadao, ba baene so niha sato fefu.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 3, 'Ba oya huhuonia khöra, amaedola, imane:', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 4, 'Ba ba wamazaewenia, ba so zi göna ba lala, ba so wofo, ba la''a.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 5, 'Ba so zi göna ba zokara, ba zi lö awe''e-we''e tanö khönia, ba i''anema''ö motalinga, me lö awe''e-we''e danö khönia.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 6, 'Ba me tumbu luo, ba angongo ba mate, me no ambö ŵa''ania.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 7, 'Ba so zi göna barö ndroi, ba ebua ndroi ba mate zinanö ibe''e.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 8, 'Ba so zi göna ba danö si sökhi, ba mowua, so zowua si dua wulu, so zi felendrua ba so zi önö, zamba yöu.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 9, 'Si so tögi dalinga, ba yamufondrondrongo! [2]', '["Faigi 11:15"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 10, 'Ba la''ondrasi ia nifahaönia, lamane khönia: Hana wa amaedola niŵa''öu khöra?', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 11, 'Ba itema li, imane: khömi no mube''e wa''aboto ba dödö zi no tobini andrö, ba mbanua zorugo andrö, ba khöra, ba lö mube''e.[3]', '["Faigi 11:25; 16:17; KorI 2:7–10","Faigi 25:29; Mar 4:25; Luk 8:18; 19:26"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 12, 'Ba zi no so sa, ba tebe''e na, lahöna khönia, ba ba zi lö''ö, ba laheta göi zi no so khönia.[4]', '["Faigi 11:25; 16:17; KorI 2:7–10","Faigi 25:29; Mar 4:25; Luk 8:18; 19:26"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 13, 'Da''ö mbörö wa amaedola huhuogu khöra, me lö mangila ira, he ŵa''ae no teboka höröra, ba me lö mamondrongo, he ŵa''ae larongo, ba me lö aboto ba dödöra.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 14, 'Ba itörö ba khöra nifa''ele''ö Yesaya, me imane: "Mirongo dania ia tögi dalingami, ba lö''ö manö aboto ba dödömi; anehe hörömi, ba lö mi''ila.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 15, 'Noa sa mu''abe''e''ö dödö niha andre ba no afiso-fiso ira, ba no lafakifu hörö, ena''ö lö la''ila höröra ba ena''ö lö larongo tögi dalingara ba ena''ö lö aboto ba dödöra, fa lö lafuli ira, ena''ö u''orifi ira."', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 16, 'Ba ya''ahowu hörömi, me la''ila, ba tögi dalingami, me larongo.[5]', '["Luk 10:23 b.t.","FetI 1:10; Heb 11:13"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 17, 'Si ndruhu niŵa''ögu khömi: No ato zama''ele''ö ba no ato zatulö somasi mangila ni''ilami andrö, ba lö ni''ilara, ba somasi mamondrongo nirongomi andrö, ba lö nirongora.[6]', '["Luk 10:23 b.t.","FetI 1:10; Heb 11:13"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 18, 'Ba mifondrondrongo geluaha gamaedola andrö, samazaewe tanömö zinanö:', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 19, 'Na so zamondrongo turia mbanua andrö, ha niha ia, ba na lö aboto ba dödönia, ba so Gafökha, i''oloi''ö nifazaewe ba dödönia; da''ö nifazaewe tanömö si göna ba lala andrö.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 20, 'Ba nifazaewe ba zokara, ba da''ö ia: Irongo daroma li andrö, ba i''anema''ö itema, omuso dödönia.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 21, 'Ba lö moŵa''a ba dödönia, lö''ö sa anau-nau gölö; ba na tesao wamakao, ba ma folohi, na börö daroma li andrö, ba i''anema''ö mangawuli furi.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 22, 'Ba nifazaewe barö ndroi, ba da''ö ia: Irongo daroma li andrö, ba so wa''abu dödö ba guli danö andre, awö wamaelungu andrö, ba gana''a, ba ibunu daroma li, ba tobali lö mowua.[7]', '["Faigi 19:23; TimI 6:9"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 23, 'Ba nifazaewe ba danö si sökhi, ba da''ö ia: Irongo daroma li, ba aboto ba dödönia, ba ya''ia zowua, so zowua si dua wulu, so zi felendrua ba so zi önö, zamba yöu.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 24, 'Amaedola tanö bö''ö iŵa''ö khöra, imane: No fakhili-khili ira mbanua zorugo andrö niha samazaewe tanömö si sökhi ba nowinia.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 25, 'Ba me no mörö niha, ba so zi fatiu tödö khönia, möi mufazaewe, danömö ndru''u barö zinanö ba ilau mofanö.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 26, 'Ba me no ebua zinanö, me molai, awena göi oroma ndru''u andrö.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 27, 'Ba so genoni zokhö, lamane khönia: He Tua! hadia, tenga tanömö zinanö si sökhi nifazaeweu ba nowiu? Ba he moroi khönia ndru''u andrö?', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 28, 'Ba imane khöra: Niha si fatiu tödö zolau da''ö.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 29, 'Ba imane: Böi, ma dania mifao wondröni sinanö, na mi''ozaragö ndru''u.[8]', '["Yes 65:8","Faigi 3:12; SamII 23:6"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 30, 'Akha faoma ebua ia, irege wamasi, ba na baŵa wamasi, ba uŵa''ö ba zamasi, umane: Mi''ofönai''ö wangozaragö du''u ba milau ba ngamböbö, ba wanunu ya''ia, ba bua zinanö, ba mi''owuloi ba halasa khögu.[9]', '["Yes 65:8","Faigi 3:12; SamII 23:6"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 31, 'Amaedola tanö bö''ö iŵa''ö khöra,[10] imane: No fakhili-khili ira mbanua zorugo andrö hunö lada, nihalö niha, nifazaewenia ba nowinia.', '["Ayati 31–34: Mar 4:30–34; Luk 13:18–21"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 32, 'Fondrege zide-ide mbua zinanö sa ia, ba na no manöi, ba ebua ia moroi ba gule-gule bö''ö ba tobali motöla, tobali möi wofo ba dalu mbanua, mangazuni ba ndrahania.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 33, 'Amaedola tanö bö''ö iŵa''ö khöra, imane: No fakhili-khili ira mbanua zorugo andrö danömö roti, nihalö ndra alawe, nifarukania ba zi tölu yöu hamo, irege aisö ma''afefu.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 34, 'Da''ö fefu niŵa''ö Yesu ba niha sato, amaedola, lö bö''önia, huhuonia khöra, ha sambalö amaedola.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 35, 'Ena''ö itörö niŵa''ö zama''ele''ö andrö, me imane: "Damuhededo, ulau gamaedola, ubokai zi no tobini, i''otarai mböröta danö."[11]', '["Sin 78:2; KorI 2:7"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 36, 'Aefa da''ö, ba ifofanö niha sato ba möi ia yomo. Ba möi khönia nifahaönia, lamane: Ombakha''ö khöma geluaha gamaedola andrö, du''u ba nowi.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 37, 'Ba itema lira, imane: Samazaewe tanömö zinanö si sökhi andrö, ba ya''ia Nono Niha,', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 38, 'ba nowi andrö, ba ya''ia niha ba guli danö; ba tanömö si sökhi andrö, ba ono mbanua andrö; ba du''u, ba ono Gafökha.[12]', '["Yoh 8:44; YohI 3:8"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 39, 'Ba si fatiu tödö andrö, samazaewe ya''ia, ba ya''ia Gafökha andrö. Ba famasi, ba amozua götö danö andre; ba samasi, ba mala''ika andrö.[13]', '["Fam 14:15"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 40, 'Ba hulö si mane na la''ozaragö ndru''u, nitunu ba galitö, si manö göi dania ba gamozua götö danö andre.', '["Faigi 24:31","Sin 50; Fam 19:20"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 41, 'Ifatenge dania mala''ikania Ono Niha, ba la''ozaragö fefu wangala ba mbanuania andrö, awö zamazökhi si lö atulö,[14]', '["Faigi 24:31","Sin 50; Fam 19:20"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 42, 'ba latibo''ö ba mbaho galitö andrö, ba fege-ege dania ba da''ö ba fatangisa mboha.[15]', '["Faigi 24:31","Sin 50; Fam 19:20"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 43, 'Ba humaga dania zatulö andrö, hulö luo, ba mbanua Namara andrö. Ha niha zi so tögi dalinga, ba yamufondrondrongo![16]', '["Dan 12:3; KorI 15:40 b.t."]', NULL),
  (3394472, 'NT', 'Mataio', 13, 44, 'No fakhili-khili ira mbanua zorugo andrö girö-girö nibini''ö ba mbenua, nisöndra niha, ba ibini''ö; ba ba wa''omuso dödönia andrö, ba möi ia, i''amawa fefu hadia ia zi so khönia, ba i''öli mbenua andrö.[17]', '["Fil 3:7"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 45, 'Fakhili-khili zui ira mbanua zorugo andrö niha saniaga, sangalui mani-mani si sökhi.', '["Amaed 8:10,11"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 46, 'Ba me isöndra zambua mani-mani sebua böli, ba möi ia, i''amawa fefu hadia ia zi so khönia ba i''öli da''ö.[18]', '["Amaed 8:10,11"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 47, 'Fakhili-khili zui ira mbanua zorugo andrö giri, nilau ba nasi, fama''u''u fefu hadia ia ngawalö gi''a.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 48, 'Ba na no afönu ia, ba ladöni yaŵa baene ba mudadao ira, la''ozaragö zi sökhi, lalau ba nahia ba si lö sökhi, ba latibo''ö.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 49, 'Si manö göi dania ba gamozua götö danö andre. Möi dania mala''ika andrö ba lafabali zi lö sökhi andrö ba zatulö;', '["Faigi 22:13; 24:51"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 50, 'ba latibo''ö ba mbaho galitö andrö, ba fege-ege dania ba da''ö ba fatangisa mboha.[19]', '["Faigi 22:13; 24:51"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 51, 'Hadia, no aboto ba dödömi da''ö fefu?', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 52, 'Ba imane khöra: Me si manö, ba dozi sangila amakhoita, nifahaö ba ngawalö mbanua Lowalangi andrö, ba no fakhili-khili ba niha, satua baomo, sanao''ö baero, moroi ba girö-girönia andrö, si bohou, awö zi no ara.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 53, 'Ba me no i''o''ozui Yesu gamaedola andrö,[20] ba iheta ia ba da''ö.', '["Ayati 53–58: Mar 6:1–6; Luk 4:16,22–24"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 54, 'Ba me irugi mbanuara, ba ifahaö ira ba zekola khöra, irege tobali dödöra, ba lamane: Heza moroi khönia wa''atua-tua andrö, awö wa''abölö andrö?', '["Ayati 53–58: Mar 6:1–6; Luk 4:16,22–24"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 55, 'Tenga ono duka andrö ia? Tenga Maria döi ninania andrö, ba tenga Yakobo ba Yosefo ba Simoni ba Yuda döi dalifusönia matua andrö?[21]', '["Faigi 12:46; Yoh 6:42"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 56, 'Ba talifusönia alawe andrö, ba tenga khöda so ira, fefu? Ba heza moroi khönia da''ö fefu?', '["Faigi 12:46; Yoh 6:42"]', NULL),
  (3394472, 'NT', 'Mataio', 13, 57, 'Ba fatuwu ia khöra.', '[]', NULL),
  (3394472, 'NT', 'Mataio', 13, 58, 'Ba lö oya ifazökhi ba da''ö tandra, börö wa lö mamati ira.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 1, 'Me luo da''ö irongo duria Yesu andrö Herode,[1] razo ba zi sagörö ni''o''öfa tanö andrö.', '["Ayati 1–12: Mar 6:14–31; Luk 9:7–9","Faigi 16:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394473, 'NT', 'Mataio', 14, 2, 'Ba imane ba genoninia: Yohane da''ö, samayagö idanö; no maoso da''ö moroi ba ngai zi mate, andrö so khönia wa''abölö andrö.[2]', '["Ayati 1–12: Mar 6:14–31; Luk 9:7–9","Faigi 16:14"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 3, 'Noa sa ifara''u''ö Yohane andrö Herode, no ifaböbö''ö ba no ifabe''e''ö ba gurunga, börö Herodia andrö, fo''omo dalifusönia [Filifo].[3]', '["Luk 3:19,20","MozIII 18:16"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 4, 'Noa sa iŵa''ö khönia Yohane; Lö tola so ia khöu.[4]', '["Luk 3:19,20","MozIII 18:16"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 5, 'Ba ibunu ena''ö Yohane Herode, ba ata''u ia niha sato, me ba dödöra sama''ele''ö Yohane andrö.[5]', '["Faigi 21:26"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 6, 'Ba me baŵa wa''atumbu khö Herode, ba manari nono Herodia andrö khöra ba da''ö, ba omasi Herode.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 7, 'Andrö ifabu''u khönia, fahölu ia, ibe''e khönia hadia ia ni''andrönia.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 8, 'Ba me no isofu khö ninania ua; ba imane: Be''e khögu ba da''e, ba wiga yaŵa, högö Yohane andrö, samayagö idanö.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 9, 'Ba abu dödö razo, ba ba wahölusa no mege ba ba domenia andrö, ba i''oroi''ö labe''e.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 10, 'Ba ifatenge, ifa''eŵa''ö mbagi Yohane ba gurunga.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 11, 'Ba la''ohe högönia, ba wiga, ba labe''e khö nono alawe andrö, ba i''ohe khö ninania.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 12, 'Ba so ndra nifahaönia, lahalö mbotonia ba lako''o; ba möi ira mangombakha da''ö khö Yesu.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 13, 'Ba me irongo Yesu,[6] ba iheta ia ba da''ö, moloyo ia, isaŵa danö si mate, ba zi ha ya''ia; ba me larongo niha sato, ba la''o''ö ia, latörö tanö, moroi ba mbanua misa.', '["Ayati 13–21: Mar 6:31–44; Luk 9:11–17; Yoh 6:1–14)"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 14, 'Ba me irugi Yesu, ba i''ila niha sato sibai andrö, ba ahakhö dödönia ira ba ifadöhö wökhö ba zofökhö khöra.[7]', '["Faigi 9:36"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 15, 'Ba me tanö owi, ba möi khönia nifahaö, lamane: Tanö si mate da''e, ba bongi; fofanö sa''ae niha sato, ena''ö möi ira ba mbanua misa, mowöli göra.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 16, 'Ba imane khöra: Alakha lö mofanö ira, mibe''e göra, ya''ami.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 17, 'Ba lamane khönia: Lö khöma ba da''e, ha lima roti ba ha dua rozi gi''a.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 18, 'Ba imane: Mi''ohe ia khögu ba da''e.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 19, 'Ba iŵa''ö mudadao niha sato ba ndru''u, ba ihalö roti andrö, si lima, awö gi''a andrö, si dua rozi, ifaöga hörönia miyaŵa ba zorugo, i''aohasi gölö Lowalangi ba iboboto ba ibe''e khö ndra nifahaö roti no mege, ba ira nifahaö zame''e ba niha sato.[8]', '["Faigi 15:32 b.t."]', NULL),
  (3394473, 'NT', 'Mataio', 14, 20, 'Ba manga ira fefu ba abuso, ba la''ozaragö zi töra, akhökhöla, felendrua kude.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 21, 'Ba si manga andrö, ba mato lima ngahönö ndra matua, baero ndra alawe, baero ndraono.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 22, 'Ba ifarou nifahaö,[9] ena''ö mowaö-waö ira baowo, moloyo miyefo, gasa-gasa wamofanönia niha sato.', '["Ayati 22–35: Mar 6:45–56; Yoh 6:15–21"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 23, 'Ba me no ifofanö niha sato, ba möi ia ba hili, ha ya''ia, mangandrö. Ba me no bongi, ba ha ya''ia ba da''ö.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 24, 'Ba no so ba dalu mbaŵa nowo no mege, no tosasa ba ndrulu, noa sa zuzumö nangi.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 25, 'Ba me miwo manu, ba möi khöra Yesu, mowaö-waö ba dete nidanö.[10]', '["Yoh 9:8"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 26, 'Ba me la''ila ia, sowaö-waö ba dete nidanö, ba tokea ira, lamane: Bekhu! ba mu''ira-ira ba wa''ata''u.[11]', '["Luk 24:37"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 27, 'Ba i''anema''ö muhede khöra Yesu, imane: Mihonogö ami, ya''odo; böi mi''ata''ufi!', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 28, 'Ba itema linia Fetero, imane: Na ya''ugö, Tua, ba ŵa''ö khögu, möido khöu ba dete nidanö.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 29, 'Ba imane: Aine! Ba möi tou Wetero, moroi ba nowo, mowaö-waö ia ba dete nidanö, i''ondrasi Yesu.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 30, 'Ba me i''ila nangi, ba ata''u ia ba ibörötaigö ahöndrö, ba imane: He Tua, orifido!', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 31, 'Ba i''anema''ö i''oro''ö dangania Yesu, ira''u, imane khönia: He sambö famati, hana wa manufa dödöu?[12]', '["Faigi 8:26"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 32, 'Ba me möi ira baowo, ba tebato nangi.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 33, 'Ba mangalulu khönia zi so baowo, lamane: Duhu, Ono Lowalangi ndra''ugö.[13]', '["Faigi 16:16"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 34, 'Ba la''ötö mbaŵa, lasaŵa danö Genezare.', '[]', NULL),
  (3394473, 'NT', 'Mataio', 14, 35, 'Ba me la''ila ia banua da''ö, ba lafatenge zinenge ba zi fasui andrö fefu ba la''ohe khönia fefu zi so fökhö.', '["Faigi 9:21; Luk 6:19"]', NULL),
  (3394473, 'NT', 'Mataio', 14, 36, 'Ba la''andrö khönia, ena''ö ha ahe mbarunia lababaya, ba dozi sombambaya, ba döhö wökhö.[14]', '["Faigi 9:21; Luk 6:19"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 1, 'Me luo da''ö möi khö Yesu Farizaio ba sangila amakhoita,[1] banua Yeruzalema, lamane:', '["Ayati 1–20: Mar 7:1–23","Luk 11, 38"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 2, 'Hana wa lasawö niŵa''ö ndra tua ira nifahaömö? Lö''ö sa mombanö ira, na la''a göra.[2]', '["Ayati 1–20: Mar 7:1–23","Luk 11, 38"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 3, 'Ba itema li, imane khöra: Ba hana ami göi, wa misawö goroisa Lowalangi, ba nifakhoimi andrö?', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 4, 'Noa sa i''oroi''ö Lowalangi, imane: "Fosumange namau, awö ninau" ba: "si mate zangelifi amania ba ma inania."[3]', '["MozII 20:12; 21:17; Amaed 23:22"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 5, 'Ba ya''ami, ba mimane: Na so zanguma''ö khö namania, ba ma khö ninania: Tebe''e sumange [Lowalangi] zinemau khögu ena''ö, ba alakha lö ifusumange namania, awö ninania.', '["MozII 20:12; 21:17; Amaed 23:22"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 6, 'Ba no miwu''ai goroisa Lowalangi andrö, ba nifakhoimi andrö.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 7, 'He ya''ami, samini tödö! Si ndruhu wama''ele''ö Yesaya ba khömi andrö, me imane:', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 8, '"Lafosumange ndra''o bewera niha andrö, ba tödöra, ba no aröu khögu.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 9, 'Zaya-zaya gölöra wamosumangera ya''o, me no nifakhoi niha wamahaöra andrö."', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 10, 'Ba ikaoni khönia niha sato, ba imane khöra: Mifondrondrongo ba ya''aboto ba dödömi!', '["HalZin 10:15; Rom 14:14"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 11, 'Tenga da''ö zana''unöi niha si möi bakha ba mbawania, ha si möi baero, si oroi mbawania da''ö zana''unöi niha.[4]', '["HalZin 10:15; Rom 14:14"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 12, 'Ba so ndra nifahaö, lamane khönia: Hadia, ö''ila wa no fatuwu ba warizaio, me larongo niŵa''öu andrö?', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 13, 'Ba itema li, imane: Fefu zinanö, si tenga nitanö Namagu andrö ba zorugo, ba ladeha dania.[5]', '["HalZin 5:38","Faigi 23:16; Luk 6:39; Rom 2:19"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 14, 'Miböhöi ira; niha sau''a ira, samasao sau''a, ba na ifasao nawönia sau''a sau''a, ba faoma aekhu ira ba goho-koho.[6]', '["HalZin 5:38","Faigi 23:16; Luk 6:39; Rom 2:19"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 15, 'Ba itema linia Fetero, imane khönia: Ombakha''ö khöma geluaha gamaedola andrö.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 16, 'Ba imane: Hadia, lö''ö na saboto ba dödömi göi?', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 17, 'Hadia, lö mi''ila, wa isaŵa mbetu''a fefu zi möi bakha ba mbawa, awö wa ifuli möi baero ba dögi-tögi?', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 18, 'Ba hadia ia zi otarai mbawa, ba ba dödö i''otarai, ba da''ö zana''unöi niha.[7]', '["Yak 3:6","MozI 6:5; Rom 7:18"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 19, 'Moroi ba dödö sa i''otarai era-era si lö sökhi, ba fange''e, ba fohoröni donga zodonga ba fohorö bö''ö ba fanagö ba famöbögö si lö duhu ba fanandraŵa.[8]', '["Yak 3:6","MozI 6:5; Rom 7:18"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 20, 'Ya''ia wana''unöi niha. Ba lö ita''unöi niha, na manga lö mombanö.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 21, 'Ba iheta ia ba da''ö Yesu,[9] isaŵa danö Diro ba tanö Zidona.', '["Ayati 21–31: Mar 7:24–31"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 22, 'Ba hiza ndra alawe Gana''ana, si otarai danö da''ö; mu''ao ia, imane: Hakhösi tödö ndra''o Tua, ma''uwu Dawido! ifakao sibai nonogu alawe bekhu.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 23, 'Ba lö itema linia, sambua li lö''ö. Ba möi khönia ndra nifahaönia, mangandrö ira khönia, lamane: Fofanö ia, me si ao-ao moroi furida.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 24, 'Ba itema lira, imane: Ha ba mbiri-biri sisuna andrö, ma''uwu Gizeraeli, tefatenge ndra''o.[10]', '["Faigi 10, 6"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 25, 'Ba möi ndra alawe no mege, ituhi danö fönania, imane: He Tua, tolodo!', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 26, 'Ba itema linia, imane: Lö tola lahalö gö ndraono, ba wame''e ö nasu.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 27, 'Ba imane: Si ndruhu Tua, ba la''a sa atö asu gakhökhöla, saekhu tou, na manga zokhö ya''ira.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 28, 'Ba itema linia Yesu, imane khönia: He alawe, no ebua wamatimö andrö, yafalukha''ö zomasi ndra''ugö! Ba döhö wökhö nononia alawe, ba da''ö sibai.[11]', '["Faigi 8:10,13"]', NULL),
  (3394474, 'NT', 'Mataio', 15, 29, 'Ba iheta ia ba da''ö Yesu, isaŵa mbaŵa Galilaia andrö, ba möi ia ba hili, mudadao ia ba da''ö.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 30, 'Ba ato zangondrasi ya''ia niha, si so sogombuyu-mbuyu ba sagau''a ba si lö hede ba sagaböda ba bö''önia, ato, ba latou''ö tou fönania; ba ifadöhö wökhöra,[12]', '["Faigi 11:5; Yes 35:5 b.t."]', NULL),
  (3394474, 'NT', 'Mataio', 15, 31, 'tobali ahöli-höli dödö niha sato, me la''ila humede zi lö hede andrö ba döhö wökhö zagaböda ba mowaö-waö zogombuyu-mbuyu ba la''ila niha sagau''a; ba lasuno Lowalangi Ndraono Gizeraeli.', '["Faigi 11:5; Yes 35:5 b.t."]', NULL),
  (3394474, 'NT', 'Mataio', 15, 32, 'Ba humede Yesu ba nifahaönia,[13] imane: Ahakhö dödögu niha sato andrö, me no tölu bongi wa''ara lö niröira ya''o, ba lö öra, ba lö omasido ufofanö ira lö manga, fa lö mate olofo ba lala.[14]', '["Ayati 32–39: Mar 8:1–10","Faigi 14:15 b.t."]', NULL),
  (3394474, 'NT', 'Mataio', 15, 33, 'Ba lamane khönia nifahaö: Heza tahalö gö si manö fa''oya, ba danö si mate, fangabuso niha si manö fa''ato?', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 34, 'Ba imane khöra Yesu: Ha uga roti, si so khömi? Ba lamane: Fitu, ba so ma''ifu gi''a.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 35, 'Ba iŵa''ö ba niha sato, ena''ö mudadao ira ba danö;', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 36, 'ba ihalö roti andrö si fitu, awö gi''a andrö, ba i''aohasi gölö Lowalangi, ba iboboto ba ibe''e khö ndra nifahaö, ba ira nifahaö zame''e ba niha sato.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 37, 'Ba manga ira fefu, ba abuso; ba la''ozaragö zi töra, akhökhöla, fitu kude.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 38, 'Ba si manga andrö, ba no öfa ngahönö ndra matua, baero ndraono, baero ndra alawe.', '[]', NULL),
  (3394474, 'NT', 'Mataio', 15, 39, 'Ba ifofanö niha sato, ba möi ia baowo, isaŵa danö Magada.', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 1, 'Ba möi khönia Farizaio ba sadukaio,[1] latandraigö ia, la''andrö khönia, ena''ö na i''oroma''ö khöra dandra, moroi si yaŵa ba mbanua.[2]', '["Ayati 1–12: Mar 8:11–21","Faigi 12:38"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 2, 'Ba itema li, imane khöra: Na tanö owi, ba mimane: Lökhö dania, me no oyo mbanua;[3]', '["Luk 12:54 b.t.","Faigi 12:39. Yon 2:1"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 3, 'ba na mahemolu mbanua, ba mimane; Moteu sabölö-bölö ma''ökhö, me no oyo mbanua ba me no alu. Amuata mbanua andrö, ba mi''ila mihuku, ba tandra ginötö andrö, ba tebai mihuku.', '["Luk 12:54 b.t.","Faigi 12:39. Yon 2:1"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 4, 'La''alui dandra niha si lö sökhi, sohorö-horö, ba lö tebe''e khöra dandra, ha tandra khö yona andrö. Ba iröi ira, mofanö ia.[4]', '["Luk 12:54 b.t.","Faigi 12:39. Yon 2:1"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 5, 'Ba me no larugi si yefo ira nifahaö, ba no olifu ira wolohe roti.', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 6, 'Ba imane khöra Yesu: Mifaigi, mi''angelama ba danömö roti Farizaio andrö ba ba danömö roti zadukaio.[5]', '["Luk 12:1; Gal 5:9; KorI 5:6"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 7, 'Ba lafatou-tou tödöra, lamane: Me lö ni''oheda roti.', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 8, 'Ba me i''ila da''ö Yesu, ba imane: Hadia nifatou-toumi tödömi, sambö famati, wa lö ni''ohemi roti?', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 9, 'Hadia, lö''ö na saboto ba dödömi, ba hadia, lö itörö tödömi roti no, si lima ba zi lima ngahönö niha ba ha uga kude ni''ozaragömi?[6]', '["Faigi 14:17 b.t.","Faigi 15, 34 b.t."]', NULL),
  (3394475, 'NT', 'Mataio', 16, 10, 'Ba he roti si fitu ba zi öfa ngahönö niha, ba ha uga kude ni''ozaragömi?[7]', '["Faigi 14:17 b.t.","Faigi 15, 34 b.t."]', NULL),
  (3394475, 'NT', 'Mataio', 16, 11, 'Hana wa lö aboto ba dödömi, wa tenga roti niŵa''ögu khömi, me umane: Mi''angelama ba danömö roti Farizaio andrö ba ba danömö roti zadukaio?', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 12, 'Awena aboto ba dödöra, wa tenga da''ö niŵa''önia: Mi''angelama ba danömö roti Farizaio andrö ba ba danömö roti zadukaio, wa famahaö Farizaio ba famahaö zadukaio niŵa''önia.', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 13, 'Ba me irugi Yesu danö Kaisaria Wilifo,[8] ba isofu khö ndra nifahaönia, imane: Hadia laŵa''ö niha, ha niha Nono Niha?', '["Ayati 13–20: Mar 8:27–30; Luk 9:18–21"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 14, 'Ba lamane: So zanguma''ö Yohane andrö, samayagö idanö ba so zanguma''ö Eliya, ba so, ba Yeremia lawa''ö, ba ma fasamösa zama''ele''ö andrö.[9]', '["Faigi 14:2; 17:10"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 15, 'Ba imane khöra: Ba ya''ami, ba ha miŵa''ö, ha niha ndra''odo?', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 16, 'Ba itema li Simoni Fetero, imane: Keriso ndra''ugö, Ono Lowalangi sauri andrö.[10]', '["Faigi 14:33; Yoh 6:69; 11:27"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 17, 'Ba itema linia Yesu, imane khönia: Ya''ahowu ndra''ugö Simoni, ono Yona, me no tenga niha zama''ele''ö khöu da''ö, me Amagu andrö, si so ba zorugo, zama''ele''ö.[11]', '["Gal 1:16; KorI 2:14","Yoh 1:43; HalZin 15:7","Faigi 18:18; Yoh 20:23"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 18, 'Ba ya''odo göi, uŵa''ö khöu: Fetero ndra''ugö, ba ba dete gowe andrö utaru''ö mbanuagu andrö dania, ba lö lalaŵa ia bawa göli mbanua tou.[12]', '["Gal 1:16; KorI 2:14","Yoh 1:43; HalZin 15:7","Faigi 18:18; Yoh 20:23"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 19, 'Ube''e dania khöu wogoe mbanua zorugo andrö, ba na so niböbömö ba guli danö, ba niböbö göi ba zorugo, ba hadia ni''efa''öu ba guli danö, ba ni''efa''ö göi ba zorugo.[13]', '["Gal 1:16; KorI 2:14","Yoh 1:43; HalZin 15:7","Faigi 18:18; Yoh 20:23"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 20, 'Aefa da''ö iŵa''ö khö ndra nifahaö, böi laŵa''ö ba niha, wa Keriso ia.', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 21, 'I''otarai da''ö,[14] ba ibörötaigö Yesu ibokai khö ndra nifahaönia, wa lö tola lö möi ia ba Yeruzalema, awö wa la''oya''ö dania wamakao ya''ia satua andrö ba ere sebua ba sangila amakhoita, awö wa labunu dania ia, awö wa tesusugi dania ia, na no irugi tölu ngaluo.[15]', '["Ayati 21–28: Mar 8:31–38; 9:1; Luk 9:22–27","Faigi 17:22,23; 20:18,19"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 22, 'Ba isöbi ia khönia Fetero, ibörötaigö itenaŵa, imane: Yamutimba khöu Lowalangi, Tua! Böi göna ndra''ugö si manö.', '[]', NULL),
  (3394475, 'NT', 'Mataio', 16, 23, 'Ba ibali''ö ia, imane khö Wetero: Ae furigu, Satana! fangalagu ndra''ugö; me lö öfatou-tou zomasi Lowalangi, ha somasi niha öfatou-tou.[16]', '["SamII 19:22"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 24, 'Aefa da''ö, ba imane Yesu khö ndra nifahaönia: Na so zedöna molo''ö ya''o, ba yamu''ositengagö ia ba yamulu''i röfania ba yamu''o''ö ndra''o.[17]', '["Faigi 10:38"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 25, 'Ba zangalui fa''anau nosonia, aetu ia, ba saetu noso, na börö ndra''o, da''ö zanöndra ya''ia.[18]', '["Luk 17:33; Yoh 12:25"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 26, 'Hadia sa guna ba niha, na isöndra harenia fefu hadia ia zi so ba guli danö, ba na te''ala ia nosonia? Ba hadia ena''ö nibe''e niha höli nosonia?[19]', '["Sin 49:8,9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394475, 'NT', 'Mataio', 16, 27, 'So sa dania Nono Niha, so khönia lakhömi Namania, awönia mala''ika khönia, ba ba da''ö ibe''e zulö ba zamösana, dali mbua-buania.[20]', '["Faigi 24:30; 25:31; KorII 5:10"]', NULL),
  (3394475, 'NT', 'Mataio', 16, 28, 'Si ndruhu niŵa''ögu khömi, so ösa, zi so ba da''e, si lö mate, irege no la''ila so Nono Niha ba mbanuania andrö.[21]', '["Faigi 10:23"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 1, 'Ba önö bongi aefa da''ö,[1] ba iŵa''ö awönia Yesu Wetero ba Yakobo ba Yohane, talifusö Yakobo, ba i''ohe ira ba hili salaŵa, ba zi ha ya''ira.[2]', '["Ayati 1–13: Mar 9:2–13; Luk 9:28–36","Faigi 26:37 b.t."]', NULL),
  (3394476, 'NT', 'Mataio', 17, 2, 'Ba tobali ia fönara, humaga mbawania, hulö luo, ba nukhania, ba afusi, hulö haga.[3]', '["FetII 1:16–18"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 3, 'Ba hiza, oroma khöra Moze ba Eliya, si fahuhuo khönia.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 4, 'Ba humede Wetero, imane khö Yesu: He Tua, ba da''e zi sökhi nahada, na omasi ndra''ugö, ba da''ulau nose ba da''e,[4] tölu, sambua khöu ba sambua khö Moze ba sambua khö Geliya.', '["da''ulau nose ba teks asli Yunani: da''ufazökhi tölu nose."]', NULL),
  (3394476, 'NT', 'Mataio', 17, 5, 'Ba me muhede ia na, ba hiza lawuo sihaga, si lumö''ö ya''ira, ba hiza li, si otarai lawuo andrö, imane: Onogu da''ö, ono omasiö, wa''omasigu; mifondrondrongo linia.[5]', '["Faigi 3:17; MozV 18:15"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 6, 'Ba me larongo da''ö ira nifahaö, ba lafalögu tou ira, ata''u sibai.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 7, 'Ba möi khöra Yesu, itufa ira tangania, imane: Mifaoso, ba böi mi''ata''ufi.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 8, 'Ba me lafaöga höröra, ba lö ni''ilara niha, ha Yesu.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 9, 'Ba me latueli hili, ba iŵa''ö khöra Yesu, böi la''ombakha''ö gangilata andrö, gofu ha ökhö, irege no maoso Nono Niha moroi ba ngai zi mate.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 10, 'Ba lasofu khönia nifahaö andrö, lamane: Ba hana wa laŵa''ö sangila amakhoita, lö tola lö möi Geliya ua?[6]', '["Mal 3:1; 4:5"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 11, 'Ba itema li, imane: Möi sa Geliya ba ifuli i''a''azökhi fefu hadia ia.[7]', '["Fam 11:3 b.t.","Faigi 11:14; 14:8; Luk 1:17"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 12, 'Ba uŵa''ö khömi: Noa sa''ae möi Geliya, ba lö saboto ia ba dödöra, ba no lalau khönia hadia zomasi ira. Si manö göi ba Nono Niha; lafakao dania.[8]', '["Fam 11:3 b.t.","Faigi 11:14; 14:8; Luk 1:17"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 13, 'Awena aboto ba dödö ndra nifahaö, wa khö Yohane, samayagö idanö andrö, tetandrösaigö niŵa''önia khöra.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 14, 'Ba me larugi niha sato,[9] ba i''ondrasi ia niha, ituhi danö fönania, imane:', '["Ayati 14–21: Mar 9:14–29; Luk 9:37–43"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 15, 'He Tua, hakhösi tödö nonogu andrö, maniri,[10] mofökhö sibai; asese sa''ae alau ia ba galitö ba asese göi ba nidanö.', '["maniri: ba teks asli Yunani tesura σεληνιάζεται (selēniazetai) eluahania fökhö faniri si itaria fawuka baero gilo (li Indonesia epilepsi)"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 16, 'Ba no u''ohe ia khö ndra nifahaömö, ba tebai lafadöhö.', '["maniri: ba teks asli Yunani tesura σεληνιάζεται (selēniazetai) eluahania fökhö faniri si itaria fawuka baero gilo (li Indonesia epilepsi)"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 17, 'Ba itema linia Yesu, imane: He ya''ami, niha si lö famati, si no tefuyu tödö! ha wa''aragu na khömi ena''ö? ha wa''ara utaha wolaumi andrö? Mi''ohe ia khögu ba da''e.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 18, 'Ba itenaŵa ia Yesu,[11] ba aheta khönia mbekhu andrö, ba döhö wökhö nono andrö, i''otarai da''ö sibai.', '["Ba itenaŵa ia Yesu: nitenaŵa Yesu bekhu tenga ono andrö. Sabölö faudunia: Ba itenaŵa mbekhu andrö Yesu."]', NULL),
  (3394476, 'NT', 'Mataio', 17, 19, 'Aefa da''ö, ba möi ndra nifahaö khö Yesu, ba zi ha ya''ira, lamane: Hana ndra''aga, wa tebai mafofanö ia?', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 20, 'Ba imane khöra: Ba wa''ambö wamatimi andrö. Si ndruhu sa niŵa''ögu khömi, na so khömi wamati, sezai bua lada, ba miŵa''ö ba hili andrö: Fawu''a''ö ba da''e, fa''ese''ö ba da''ö! ba ifawu''a ia; ba lö hadia ia zi tebai khömi.[12]', '["Faigi 21:21; Mar 11:23; Luk 17:6"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 21, 'Ba lö aheta zi sambalö andrö, na tenga ba wangandrö ba ba wamoni.', '["Faigi 21:21; Mar 11:23; Luk 17:6"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 22, 'Ba me orudu ira ba Galilaia, ba imane khöra Yesu; Tebe''e dania Nono Niha ba danga niha,', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 23, 'ba labunu ia, ba na no irugi tölu ngaluo, ba maoso ia, ifuli auri. Ba abu sibai dödöra.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 24, 'Ba me larugi Gafanauma, ba möi khö Wetero zanema bobotolö andrö,[13] lamane: Hadia, lö ibe''e mbobotolö andrö samahaö ya''ami?[14]', '["Bobotolö ba teks asli Yunani tesura δίδραχμα (didrachma), ya''ia da''ö hua gefe ni''oguna''ö ba wamu''a gömö nifotöi beo gosali (li Indonesia pajak). Kefe andre te''oguna''ö ba ngawalö zoguna ba gosali.","Faigi 22:17"]', NULL),
  (3394476, 'NT', 'Mataio', 17, 25, 'Imane: Ibe''e.', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 26, 'Ba me imane: Ba niha bö''ö,', '[]', NULL),
  (3394476, 'NT', 'Mataio', 17, 27, 'Ba fa böi fatuwu ita khöra, ba ae ba mbaŵa, ba lau gai, ba halö gi''a andrö, si föföna möi yaŵa, ba na öbokai mbawania, ba ösöndra bakha zambua rufia; da''ö halö ba be''e ömöda darua ita.[15]', '["Faigi 3:15; Rom 13:7; KorI 10:32"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 1, 'Ba da''ö möi khö Yesu ndra nifahaönia,[1] lamane: Ha niha atö zebua ba mbanua zorugo andrö?', '["Ayati 1–5: Mar 9:33–37; Luk 9:46–48"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 2, 'Ba humede ia ba ndraono, ifa''aso fönara, ba imane:', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 3, 'Si ndruhu niŵa''ögu khömi, na lö mifuli ami, ba na lö tobali hulö ndraono ami, ba lö''ö manö lalami ba mbanua zorugo andrö.[2]', '["Faigi 19:14 b.t.; Mar 10:15; KorI 14:20","Faigi 23:12","Faigi 30:40"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 4, 'Ba ha niha zangide-ide''ö ya''ia, si mane iraono andre, da''ö zebua ba mbanua zorugo andrö.[3]', '["Faigi 19:14 b.t.; Mar 10:15; KorI 14:20","Faigi 23:12","Faigi 30:40"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 5, 'Ba na so zama''amöi yomo khönia iraono si manö, sambua, ba döigu, ba ya''o nifa''amöinia yomo.[4]', '["Faigi 19:14 b.t.; Mar 10:15; KorI 14:20","Faigi 23:12","Faigi 30:40"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 6, 'Ba na so zangalani side-ide andrö,[5] samösa, samati khögu, ba sökhi khönia ena''ö, na lataŵi ba mbaginia gara sebua ba na latibo''ö ia ba dalu nasi.[6]', '["Ayati 6–9: Mar 9:42–48","Luk 17:2"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 7, 'Alai niha ba guli danö, ba wangala andrö! Lö''ö sa tola lö fangala, ba alai niha samobörö fangala.[7]', '["Luk 17:1; KorI 11:19"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 8, 'Ba na i''alani ndra''ugö tangau, ba ma aheu, ba tema eŵa ia ba tibo''ö; mohare''ö na saböda ndra''ugö, ba ma sakela-kela, ba ökhamö wa''auri, moroi dua dangau ba dua gaheu, ba tetibo ndra''ugö ba galitö andrö, si lö mate-mate.[8]', '["Faigi 5:30"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 9, 'Ba na i''alani ndra''ugö höröu, ba tema koe ia ba tibo''ö; mohare''ö na si bakole ndra''ugö ba ökhamö wa''auri, moroi dombua höröu, ba tetibo ndra''ugö ba narako alitö andrö.[9]', '["Faigi 5:29"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 10, 'Mifaigi, fa böi mi''ositengagö zide-ide andrö, samösa. Uŵa''ö sa khömi, mala''ikara andrö ba zorugo, ba lö mamalö-malö wa la''ila mbawa Namagu andrö, si so ba zorugo.[10]', '["Sin 34:8; Heb 1:14","Faigi 9:13; Luk 19:10; TimI 1:15"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 11, 'Ba wangorifi si no elungu sa möi Nono Niha.[11]', '["Sin 34:8; Heb 1:14","Faigi 9:13; Luk 19:10; TimI 1:15"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 12, 'Hadia ba dödömi?[12] Na so niha, si so biri-biri, otu nga''eu, ba na no elungu zi sageu; hadia, lö iröi zi siŵa wulu a siŵa ba hili misa ba möi mangalui selungu andrö?', '["Ayati 12–14: Luk 15:4–7"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 13, 'Ba na tobali isöndra, ba si ndruhu niŵa''ögu khömi, abölö wa''omuso dödönia ba da''ö, moroi ba wa''omuso dödönia ba zi siŵa wulu a siŵa, si lö elungu.', '["Ayati 12–14: Luk 15:4–7"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 14, 'Si manö göi khö Namami andrö, si so ba zorugo; tenga nilau dödönia taya zamösa, side-ide andrö.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 15, 'Ba na mosala khöu dalifusöu, ba ae tegu ia, ba zi ha ya''ami, daruami; na ifondrondrongo khöu, ba no ösöndra dalifusöu.[13]', '["MozIII 19:15; Gal 6:1"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 16, 'Ba na lö ifondrondrongo, ba halö awöu zamösa tö ba ma darua, ena''ö aro huhuo fefu ba niŵa''ö zi darua, ba ma si datölu, si so ba mbörö.[14]', '["Yoh 8:17"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 17, 'Ba na lö ifondrondrongo khöra andrö, ba ombakha''ö ba mbanua. Ba na lö''ö göi ifondrondrongo niŵa''ö mbanua, ba ya hulö niha baero ia khöu, ya hulö zanema beo.[15]', '["KorI 5:11,13; TesII 3:6,14,15"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 18, 'Si ndruhu niŵa''ögu khömi, hadia niböbömi ba guli danö, ba niböbö göi ba zorugo; ba hadia ni''efa''ömi ba guli danö, ba ni''efa''ö göi ba zorugo.[16]', '["Faigi 16:19; Yoh 20:23"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 19, 'Ba uŵa''ö göi khömi, na darua ba khömi zangosara''ö tödöra, ba guli danö, ba ngawalö hadia ia, ni''andröra, ba ibe''e khöra Amagu andrö, si so ba zorugo.[17]', '["Mar 11, 24","Faigi 28:20; Luk 24:36"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 20, 'Ba zorudu zi darua, ba ma si datölu, ba döigu, ba da''ö sodo khöra ba gotaluara.[18]', '["Mar 11, 24","Faigi 28:20; Luk 24:36"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 21, 'Ba möi khönia Wetero, imane khönia: He Tua, ha me uga u''efa''ö zala dalifusögu, na mosala in khögu? Hadia irugi mewitu?[19]', '["Luk 17:3,4"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 22, 'Imane khönia Yesu: uŵa''ö khöu: tenga ha irugi zi mewitu, irugi zi mewitu ngafulu wa fitu.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 23, 'Andrö fakhili-khili ira mbanua zorugo andrö razo, sedöna mangerai ömö khö zawuyunia.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 24, 'Ba me ibörötaigö mangerai, ba te''ohe khönia zamösa, so''ömö si fulu ngahönö balaki.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 25, 'Ba me lö khönia famu''a, ba iŵa''ö sokhö, la''amawa ia, awö wo''omonia, awö nononia, awö fefu hadia ia zi so khönia, famu''a gömö.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 26, 'Ba ituhi danö sawuyu andrö, mangalulu ia khönia, imane: Bologö dödöu khögu, ba ahori ubu''a ia khöu.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 27, 'Ba ahakhö dödö zokhö zawuyu andrö, i''efa''ö ba ibe''e bualania khönia zugilö andrö.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 28, 'Ba me möi baero zawuyu andrö, ba falukha ia nawönia sawuyu, so''ömö khönia si lima wulu rufia. Ba ira''u, itögi mbagi, imane: Bu''a gömöu khögu.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 29, 'Ba ituhi danö awönia sawuyu andrö, mangandrö khönia, imane: Bologö dödöu khögu, ba ubu''a khöu.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 30, 'Ba lö edöna ia; möi ia, ifakuru''ö, irege ibu''a gömö.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 31, 'Ba me la''ila da''ö awönia sawuyu bö''ö, ba abu sibai dödöra ba möi ira, la''ombakha''ö khö zokhö ya''ira da''ö no mege fefu.', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 32, 'Ba ifakaoni''ö ia sokhö ya''ia, imane khönia: He sawuyu si lö sökhi! Ömö no andrö fefu, ba no ube''e bualagu khöu, me no mangandrö ndra''ugö khögu;', '[]', NULL),
  (3394477, 'NT', 'Mataio', 18, 33, 'ba hadia, lö öhakhösi tödö göi mena''ö nawöu sawuyu, si mane ya''o, me no uhakhösi tödö ndra''ugö?[20]', '["Yak 2:13","Faigi 3:25,26"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 34, 'Ba mofönu zokhö ya''ia, ibe''e ba danga zamakao, irege ibu''a gömönia khönia fefu.[21]', '["Yak 2:13","Faigi 3:25,26"]', NULL),
  (3394477, 'NT', 'Mataio', 18, 35, 'Si manö göi ilau khömi dania Amagu andrö ba zorugo, na tenga moroi ba dödömi mi''efa''ö zala, dozi ami, ba dalifusömi.[22]', '["Faigi 6:15; Mar 11:25 b.t."]', NULL),
  (3394479, 'NT', 'Mataio', 19, 1, 'Ba me no i''o''ozui Yesu huhuo andrö,[1] ba iheta ia ba Galilaia, isaŵa danö Yudaia, yefo Yoridano.', '["Ayati 1–9: Mar 10:1–12"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 2, 'Ba ato zolo''ö ya''ia niha, ba ifadöhö wökhöra ba da''ö.', '[]', NULL),
  (3394479, 'NT', 'Mataio', 19, 3, 'Ba möi khönia warizaio, latandraigö ia, lamane: Hadia, tola itibo''ö ngambatönia niha, gofu hadia mbörö?[2]', '["Mar 10:8"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 4, 'Ba itema li, imane: Hadia, lö ni''ilami ba zura, wa ira matua ba ira alawe nifazökhi zomböi ba mböröta?[3]', '["MozI 2:27; 5:2)","MozI 2:24; Efes 5:31","KorI 7:10"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 5, 'ba no imane: "Andrö iröi dania namania, awö ninania, niha, ba i''olembai ngambatönia, ba tobali ha sambua boto zi darua andrö"?[4]', '["MozI 2:27; 5:2)","MozI 2:24; Efes 5:31","KorI 7:10"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 6, 'Ba tenga sa''ae darua ira, ha sambua boto. Ba böi yamufabali niha nifaböbö Lowalangi.[5]', '["MozI 2:27; 5:2)","MozI 2:24; Efes 5:31","KorI 7:10"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 7, 'Lamane khönia: Ba hana wa no i''oroi''ö Moze labe''e zura wangefa, ba latibo''ö ia?[6]', '["Faigi 5:31"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 8, 'Imane khöra: Börö wa''abe''e dödömi, wa itehe khömi Moze wanibo''ö ira alawemi; ba moroi ba mböröta, ba tenga si manö.', '["Faigi 5:32; Luk 16:18"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 9, 'Ba uŵa''ö khömi: Na so zanibo''ö ira alawenia, na tenga horö mbörö, ba na ihalö danö bö''ö, ba sohorö da''ö.[7]', '["Faigi 5:32; Luk 16:18"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 10, 'Lamane khönia nifahaönia: Na si manö huku niha ba ndra alawe, ba lö sökhi wangowalu.[8]', '["KorI 7:1"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 11, 'Ba imane khöra: Lö dozi aboto ba dödö huhuo andre, ha ba nibe''e fa''aboto ba dödö.[9]', '["KorI 7:2; 7:17","KorI 7:26,32 b.t.; TimI 4:3; TimII 3:6"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 12, 'So sa nikhai, si no tohöna si manö, moroi ba dalu nina; ba so nikhai, nikhai niha, ba so nikhai, si no mogai ya''ira tangara, börö mbanua zorugo andrö. Sangila mamotokhi ba dödönia, ba yamubotokhi.[10]', '["KorI 7:2; 7:17","KorI 7:26,32 b.t.; TimI 4:3; TimII 3:6"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 13, 'Ba la''ohe khönia ndraono sawuyu,[11] ena''ö itufa ira tanga ba mangandrö. Ba latenaŵa ira nifahaö.', '["Ayati 13–15: Mar 10:13–16; Luk 18:15–17"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 14, 'Ba imane khöra Yesu: Mifa''amöi ndraono, böi mitaha ira we''amöi khögu, ba zi manö sa mbanua zorugo andrö.[12]', '["Faigi 18:3"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 15, 'Ba itufa ira tanga, ba iheta ia ba da''ö.', '["Faigi 18:3"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 16, 'Ba hiza niha si möi khönia,[13] imane: He samahaö! hadia zi sökhi nilaugu, ena''ö usöndra wa''auri si lö aetu andrö? [14]', '["Ayati 16–22: Mar 10:17–22; Luk 18:18–23","Luk 10:25"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 17, 'Ba imane khönia: Hadia wa ösofu khögu zi sökhi? Ha samösa zi sökhi. Ba na omasi''ö ökhamö wa''auri, ba o''ö goroisa andrö.[15]', '["Luk 10:26–28; Gal 3:12,21"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 18, 'Imane: Hadia goroisa?', '[]', NULL),
  (3394479, 'NT', 'Mataio', 19, 19, 'Fosumange namau, awö ninau! ba: Omasi''ö zahatö khöu, si mane fa''omasiu ndra''ugö![17]', '["MozII 20:12 b.t.","Faigi 22:39; MozIII 19:18"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 20, 'Imane khönia ono matua andrö: No ahori u''o''ö da''ö, hadia zambö ndra''o?', '[]', NULL),
  (3394479, 'NT', 'Mataio', 19, 21, 'Imane khönia Yesu: Na omasi''ö mo''ahonoa, ba ae amawa zi so khöu ba be''e ba zi numana, ba so khöu girö-girö ba zorugo ba tabu, o''ö ndra''o.[18]', '["Faigi 5:48; 6:20; Luk 12:33,34"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 22, 'Ba me irongo da''ö ono matua andrö, ba mofanö ia, abu dödö; me no sebua ana''a ia.', '[]', NULL),
  (3394479, 'NT', 'Mataio', 19, 23, 'Ba imane Yesu ba nifahaönia: Si ndruhu niŵa''ögu khömi, afökhö sibai ba zo''ana''a wogamö banua zorugo andrö.[19]', '["TimI 6:9","Faigi 13:22"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 24, 'Ba uŵa''ö göi khömi, aoha na i itörö dögi walölöŵa kudo, moroi ikhamö mbanua zorugo so''ana''a.[20]', '["TimI 6:9","Faigi 13:22"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 25, 'Ba me larongo da''ö nifahaönia, ba tobali sibai dödöra, ba lamane: Ba ha niha zogamö fa''auri?', '[]', NULL),
  (3394479, 'NT', 'Mataio', 19, 26, 'Ba ifaigi ira Yesu ba imane khöra: Na ba niha, ba tebai; ba ba Lowalangi, ba molala fefu hadia ia.[21]', '["Luk 1:37"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 27, 'Ba humede Wetero, imane khönia: Faigi ndra''aga, no maröi fefu hadia ia ba no ma''o''ö ndra''ugö, ba hadia khöma dania?[22]', '["Faigi 4:20"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 28, 'Ba imane khöra Yesu: Si ndruhu niŵa''ögu khömi, ya''ami solo''ö ya''o, ba ba wangazökhi dania, na mudadao Nono Niha ba dadaoma lakhöminia andrö, ba dumadao göi ami, felendrua dadaoma ba sanguhuku mado Gizeraeli andrö, si felendrua, ami.[23]', '["Faigi 25:31; Luk 22:28 b.t.; Fam 3:21; KorI 6:2"]', NULL),
  (3394479, 'NT', 'Mataio', 19, 29, 'Ba dozi si no mondröi talifusö matua, ba ma talifusö alawe, ba ma ama, ba ma ina, ba ma ono, ba ma benua, na börö döigu, ba oya winaeta lasöndra mangawuli, ba latema wa''auri si lö aetu andrö, amaedola gondröita.', '[]', NULL),
  (3394479, 'NT', 'Mataio', 19, 30, 'Ba ato zi möi furi dania si so föna iada''e, ba si möi föna, si so furi iada''e.[24]', '["Faigi 20:8,16; Luk 13:30"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 1, 'Noa sa fakhili-khili ira mbanua zorugo andrö niha, satua baomo, si möi, si hulö wongi, mangoni sohalöŵö ba kabu nagu khönia.[1]', '["Faigi 21:33"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 2, 'Ba me no mamagölö ira zohalöŵö, sasuku ma''ökhö luora, ba ifatenge ira ba kabu nagu andrö khönia.', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 3, 'Ba me ifuli möi, me labözi siŵa, ba i''ila danö bö''ö, si so ba kade, si lö halöŵö,', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 4, 'ba imane khöra: Mi''ae''e, ya''ami göi, ba kabu nagu, ba si nangea luomi, ba ube''e khömi.', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 5, 'Ba möi ira. Ba ifuli möi me laluo ba me labözi tölu, ba imanö zui.', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 6, 'Ba me möi ia me labözi lima, ba falukha ia danö bö''ö, si so ba da''ö, ba imane khöra: Hadia wa mi''oma''ökhöi manö ba da''e, lö halöŵö?', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394481, 'NT', 'Mataio', 20, 7, 'Lamane khönia: Me lö sangoni ya''aga.', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 8, 'Ba me bongi sa''ae, ba imane sokhö kabu nagu andrö khö durutulinia: Hede ba zohalöŵö andrö ba be''e luora; börögö ba zafuria möi, numalö ba zi föföna andrö.[2]', '["Faigi 19:30"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 9, 'Ba la''ondrasi ni''oni me labözi lima, ba sasuku zamösa luora.', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 10, 'Ba me so zi föföna andrö, ba lawai ebua zinemara. Ba tebe''e sasuku zamösa khöra göi.', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 11, 'Ba me no latema da''ö, ba kumökö-kökö ira khö zatua baomo andrö,[3]', '["Luk 15:29 b.t.","Faigi 19:29"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 12, 'lamane: Ha saza wohalöŵö zafuria andrö, ba no fagölö-gölö ndra''aga öbe''e, ya''aga si no manaha fa''afökhö andrö, ma''ö-ma''ökhö, awö wa''aukhu zino.[4]', '["Luk 15:29 b.t.","Faigi 19:29"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 13, 'Ba itema li zi samösa andrö, imane: He le, lö ulimo ndra''ugö. Tenga no mamagölö ita ba zi sasuku?', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 14, 'Halö dana khöu ba ofanö. Somasido, ufagölö-gölö wame''e khömi safuria andre.', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 15, 'Ma lö tola u''o''ö manö nilau dödögu ba zi so khögu? Ma afökhö dödöu, me no sebua tödö ndra''o?[5]', '["Rom 9:21 b.t."]', NULL),
  (3394481, 'NT', 'Mataio', 20, 16, 'Si manö wa tobali si so föna zi so furi, awö wa tobali si so furi zi so föna.[6]', '["Faigi 19:30; 22:14"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 17, 'Ba me möi misi yaŵa Yesu ba Yeruzalema,[7] ba i''ohe awönia zi felendrua, ba zi ha ya''ira ba imane khöra ba lala:', '["Ayati 17–19: Mar 10:32–34; Luk 18:31–34","Faigi 16:21","Faigi 27:2 b.t."]', NULL),
  (3394481, 'NT', 'Mataio', 20, 18, 'Hiza, möi ita misi yaŵa ba Yeruzalema; ba tebe''e dania ba danga gere sebua ba ba danga zangila amakhoita andrö Nono Niha, ba la''etu''ö hukunia, huku famunu,[8]', '["Ayati 17–19: Mar 10:32–34; Luk 18:31–34","Faigi 16:21","Faigi 27:2 b.t."]', NULL),
  (3394481, 'NT', 'Mataio', 20, 19, 'ba labe''e ia ba danga niha baero, ba wango''aya ya''ia ba ba wamöbözi ba ba wamoröfa; ba na no irugi tölu ngaluo, ba maoso ia, ifuli auri.[9]', '["Ayati 17–19: Mar 10:32–34; Luk 18:31–34","Faigi 16:21","Faigi 27:2 b.t."]', NULL),
  (3394481, 'NT', 'Mataio', 20, 20, 'Ba möi khönia nina nono Zebedaio andrö,[10] awö nononia, ituhi danö fönania, so ni''andrönia khönia.[11]', '["Ayati 20–28: Mar 10:35–45","Faigi 10:2"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 21, 'Ba imane khönia: Hadia niŵa''öu?', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 22, 'Ba itema linia Yesu, imane: Lö mi''ila watahögö hadia ni''andrömi. Hadia mi''ila mibadu nösi mako andrö, nibadugu dania?', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 23, 'Imane khöra: Mibadu sa nösi mako andrö khögu dania, ba fedadao andrö ba gambölögu ba ba gaberagu, ba tenga ya''o zanguma''ö; ha da''ö zidadao ba da''ö, nihonogöi Namagu fedadao.[13]', '["Faigi 25:34"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 24, 'Ba me larongo da''ö si dafulu, ba lö sökhi-sökhi dödöra ba zi darua andrö, si fatalifusö.', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 25, 'Ba humede khöra Yesu, imane: Mi''ila, lafatörö mbanuara salaŵa niha ba labe''e barö mbawara niha sebuara.[14]', '["Luk 22:25 b.t."]', NULL),
  (3394481, 'NT', 'Mataio', 20, 26, 'Ba ba khömi, ba böi si manö; ha niha zomasi ebua ba khömi, ba yamöi enonimi;[15]', '["Faigi 23:11; Mar 9:35; Efes 5:21"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 27, 'ba na so ba khömi zomasi möi fönami, ba yamöi sawuyumi.', '["Faigi 23:11; Mar 9:35; Efes 5:21"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 28, 'Si mane Ono Niha, tenga si möi mangoni, no si möi enoni, si möi mame''e nosonia höli zato.[16]', '["Luk 22:27; Yes 53:10,12; TimI 2:6; FetI 1:18,19"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 29, 'Ba me mofanö ira, me aefa ira ba Yerikho,[17] ba ato zolo''ö ya''ia niha.', '["Ayati 29–34: Mar 10:46–52; Luk 18:35–43"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 30, 'Ba hiza niha sau''a, darua, sidadao ba zinga lala; me larongo itörö Yesu, ba mu''ao ira, lamane: Hakhösi tödö ndra''aga, ma''uwu Dawido![18]', '["Faigi 9:27"]', NULL),
  (3394481, 'NT', 'Mataio', 20, 31, 'Ba latenaŵa ira sato, ena''ö labato. Ba lahötöi fe''ao, lamane: He Tua, ma''uwu Dawido, hakhösi tödö ndra''aga!', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 32, 'Ba ibadugö ia Yesu, muhede ia khöra, imane: Hadia zomasi ami, he uwisa khömi?', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 33, 'Lamane khönia: He Tua, ena''ö teboka höröma!', '[]', NULL),
  (3394481, 'NT', 'Mataio', 20, 34, 'Ba ahakhö dödö Yesu ba ibabaya höröra, ba i''anema''ö ifuli la''ila niha ba la''o''ö ia.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 1, 'Ba me no ahatö ira ba Yeruzalema,[1] me larugi Mbetifage, ba gahe hili wanikha, ba ifatenge nifahaönia Yesu, darua,', '["Ayati 1–11: Mar 11:1–10; Luk 19:29–38; Yoh 12:12–18"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 2, 'imane khöra:', '["Ayati 1–11: Mar 11:1–10; Luk 19:29–38; Yoh 12:12–18"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 3, 'Ba na so zanguma''ö khömi hadia ia, ba mimane: Moguna khö Dua, ba i''anema''ö ifa''ohe''ö.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 4, 'Andrö si manö, ena''ö itörö niŵa''ö zama''ele''ö andrö, me imane: "Miŵa''ö khö nono Ziona alawe andrö:', '["Sakh 9:9"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 5, '"Hiza, i''ondrasi''ö razomö, sebolo tödö, fakudo ia ba hulu galide, ba ba hulu nono zonoro"[2]', '["Sakh 9:9"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 6, 'Ba möi nifahaö andrö, la''o''ö niŵa''ö Yesu, khöra, la''ohe galide andrö,', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 7, 'awö nono, ba labologö nukha ba hulu ba fakudo ia yaŵa.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 8, 'Ba ato niha samologö ba lala nukhara; ba so zoleŵa tuturu geu ba lafazawili ba lala.[3]', '["SalII 9:13"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 9, 'Ba mu''ao niha sato, si so föna, awö zolo''ö moroi furi, lamane: Hozana khö ma''uwu Dawido andrö, ya''ahowu zi so andrö, ba döi Zo''aya; hozana ba zalaŵa yawa![4]', '["Sin 118:25,26"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 10, 'Ba me irugi yomo ba Yeruzalema, ba humufa mbanua ma''afefu, lamane: Ha niha da''ö?', '["Faigi 2:23; Yoh 1:46"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 11, 'Ba lamane niha sato: Da''ö zama''eleö andrö, Yesu, banua Nazareta, ba Galilaia.[5]', '["Faigi 2:23; Yoh 1:46"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 12, 'Ba möi ba gosali Lowalangi andrö Yesu,[6] ba ifofanö baero fefu zamawa-mawa hadia ia, awö zowöli-wöli ba gosali, ba iso''agö meza zanuka ana''a, awö dadaoma zamawa marafadi.[7]', '["Ayati 12–17: Mar 11:15–19; Luk 19:45,46","Yoh 2:14 b.t."]', NULL),
  (3394483, 'NT', 'Mataio', 21, 13, 'Ba imane khöra: No so ba zura: "Omo wangandrö döi nomogu." Ba ya''ami, ba no mibali''ö tögi narö hili naha zorabu.[8]', '["Yes 56:7; Yer 7:11"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 14, 'Ba la''ondrasi ia sau''a, awö zombuyu-mbuyu töla, ba gosali, ba ifadöhö wökhöra.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 15, 'Ba me la''ila ere sebua ba sangila amakhoita zahöli-höli dödö andrö, nilaunia, ba me larongo li ndraono, si''ao ba gosali, sanguma''ö: "Hozana khö ma''uwu Dawido andrö!" ba lö sökhi-sökhi dödöra.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 16, 'Ba lamane khönia: örongo, hadia niŵa''ö da''ö?', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 17, 'Ba iröi ira, möi ia baero mbanua, isaŵa Mbetania, ba mörö ia ba da''ö.[10]', '["Mar 11:11,19"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 18, 'Ba me mangawuli ia miyomo ba Yeruzalema,[11] si hulö wongi, ba olofo ia.', '["Ayati 18–22: Mar 11:12–14, 20–24"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 19, 'Ba me i''ila marafala, sageu, ba ngai lala, ba möi ia ba da''ö, ba lö yaŵa bua ni''ilania, ha bulu. Ba imane khönia: Böi yamowua ndra''ugö sa''ae, irugi zi lö aetu. Ba i''anema''ö mate marafala andrö.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 20, 'Ba me la''ila da''ö nifahaö, ba ahöli-höli dödöra ba lamane: Ha lö alio mate marafala andrö!', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 21, 'Ba humede Yesu, imane khöra: Si ndruhu niŵa''ögu khömi: Na so khömi wamati, na lö manufa dödömi, ba tenga ha da''ö milau, ba marafala andrö; na miŵa''ö göi ba hili andrö: Fazaŵa''ö ba tibo''ögö ba nasi, ba itörö niŵa''ömi.[12]', '["Faigi 17:20","Faigi 7:7; 18:19"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 22, 'Ba hadia ia, fefu, ni''andrömi ba wangandrö, na mamati ami ba lö zi lö mitema.[13]', '["Faigi 17:20","Faigi 7:7; 18:19"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 23, 'Ba me möi ia ba gosali,[14] ba la''ondrasi ia ere sebua ba satua mbanua, me mamahaö ia, lamane: Hadia, wa tola ölau da''ö ba ha niha zanehe khöu?[15]', '["Ayati 23–27: Mar 11:27–33; Luk 20:1–8","Yoh 2:18"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 24, 'Ba itema lira Yesu, imane khöra: So göi nisofugu khömi zambalö; na miŵa''ö khögu da''ö, ba uŵa''ö göi khömi, hadia, wa tola ulau da''ö.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 25, 'Famayagö idanö andrö khö Yohane, he moroi ia, hadia, moroi ba zorugo, hadia moroi ba niha?', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 26, 'Na taŵa''ö: Moroi ba zorugo, ba imane khöda dania: Ba hana wa lö mamati ami no khönia? Ba na taŵa''ö: Moroi ba niha, ba ata''u ita niha sato, me ba dödöra fefu, sama''ele''ö Yohane andrö.[17]', '["Luk 3:3; 7:30","Faigi 14:5"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 27, 'Ba latema li Yesu, lamane: Lö ma''ila.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 28, 'Ba hadia ba dödömi? So niha, si so ono matua, darua. Ba möi ia ba zi samösa, imane: He onogu, ae ohalöŵö ba kabu nagu ma''ökhö.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 29, 'Ba itema linia, imane: Lö edönado. Ba aefa da''ö, ba mangesa dödönia, ba möi ia.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 30, 'Ba möi ia ba zi samösa, ba imanö göi. Ba itema linia da''ö, imane: Möi ndra''o, ama, ba lö möi ia.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 31, 'Ha niha ba zi darua andrö zolo''ö somasi nama? Lamane: Si föföna andrö.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 32, 'Noa sa möi Yohane khömi, wangombakha lala satulö, ba lö samati ami khönia, ba no mamati khönia zanema beo ba sohorö. Ba me mi''ila da''ö, ba lö sangesa dödömi, furi ö, ba wamati khönia ena''ö.[19]', '["Luk 3:12; 18:14","Faigi 3:17"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 33, 'Mifondrondrongo gamaedola bö''ö:[20] So niha, satua baomo, samazökhi kabu nagu, ifasui öli, iko''o ba danö wolazi, ba i''otomosi malige, ba ibe''e niseŵa kabu andrö ba zohalöŵö, ba ilau mofanö.[21]', '["Ayati 33–46: Mar 12:1–12; Luk 20:9–19","Yes 5:1 b.t.; Yer 2:21"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 34, 'Ba me no ahatö mbaŵa wangai bua, ba ifatenge zawuyunia ba zohalöŵö andrö, ba wanema bua nagu khönia.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 35, 'Ba lara''u zawuyunia andrö sohalöŵö: so niböbözi, so nibunu manö, ba so nibunu nitebu kara.[22]', '["Faigi 22:6"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 36, 'Ba ifuli ifatenge zawuyu bö''ö, ato moroi ba zi föföna andrö, ba lamanö göi ba da''ö.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 37, 'Ba ba gafuriata, ba ifatenge khöra nononia, imane: Ata''u ira nonogu.[23]', '["Heb 1:1,2"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 38, 'Ba me la''ila nononia andrö sohalöŵö, ba lamane dödöra: Sanema ondröita da''ö, talabu, tabunu ia ba tahalö khöda gondröita andrö khönia.[24]', '["Faigi 26:3,4,66; 27:23"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 39, 'Ba lara''u ia, latuli''ö baero kabu nagu, ba labunu.[25]', '["Faigi 23:37; Heb 13:12"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 40, 'Ba na möi zokhö kabu nagu andrö, ba he iwisa ba zohalöŵö andrö?', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 41, 'Lamane khönia: Ihaogö wamakiko sebua horö andrö, ba kabu nagu andrö, ba ibe''e niseŵa ba zohalöŵö bö''ö, same''e bua khönia na baŵania.', '[]', NULL),
  (3394483, 'NT', 'Mataio', 21, 42, 'Imane khöra Yesu: Hadia, lö mirai mi''ila ba zura: "Gowe andrö, nitibo''ö zotomo andrö, ba no tobali toyo ba watalinga; khö Zo''aya moroi da''ö, ba sahöli-höli dödöda."[26]', '["Sin 118:22, 23; HalZin 4:11; Yes 28:16"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 43, 'Andrö uŵa''ö khömi: Laheta dania khömi mbanua Lowalangi andrö, ba labe''e ba niha sowua buania.[27]', '["HalZin 13:46","Yes 8:14,15; Dan 2:34 b.t."]', NULL),
  (3394483, 'NT', 'Mataio', 21, 44, 'Ba sarasa zalau ba gowe andrö, ba nilangönia, ba imama.[28]', '["HalZin 13:46","Yes 8:14,15; Dan 2:34 b.t."]', NULL),
  (3394483, 'NT', 'Mataio', 21, 45, 'Ba me larongo gamaedola andrö khönia ere sebua ba farizaio, ba aboto ba dödöra, wa khöra itandrösaigö da''ö.', '["Luk 7:16; Luk 19:48; Mar 12:12"]', NULL),
  (3394483, 'NT', 'Mataio', 21, 46, 'Ba la''alui wondra''u ya''ia, ba no ata''u ira niha sato, me ba dödöra sama''ele''ö ia.[29]', '["Luk 7:16; Luk 19:48; Mar 12:12"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 1, 'Ba humede Yesu, amaedola zui ilau khöra, imane:', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 2, 'No fakhili-khili ira mbanua zorugo andrö razo niha,[1] samangowalu ononia.', '["Ayati 2–14: Luk 14:16–24"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 3, 'Ba ifatenge zawuyunia, ba wehede ba zi ho kumaoni, ba we''amöi ba walöŵa, ba lö edöna möi ira.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 4, 'Ba ifuli ifatenge zawuyu bö''ö, imane: Mimane ba zi no kumaoni andrö: Hiza, no u''asiwai gö andrö khögu, öröbao khögu ba hadia ia gurifö ni''a''atabö, ba no tumaba ba no awai fefu hadia ia, mitabu ba walöŵa.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 5, 'Ba lö ba dödöra; mofanö ira, so zi möi ba nowi khönia, ba so zi möi maniaga.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 6, 'Ba tanö bö''ö, ba lara''u zawuyunia andrö, la''o''aya ba labunu.[2]', '["Faigi 21:35,36"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 7, 'Ba mofönu razo no mege, ba ifatenge zaradadunia, ifafakiko''ö zange''e andrö ba banuara, ba ifatunu''ö.[3]', '["Dan 9:26"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 8, 'Aefa da''ö, ba imane ba zawuyunia: Noa sa mulau walöŵa, ba tenga si nangea möi nikaoni andrö.[4]', '["HalZin 13:46"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 9, 'Ba mi''ae ba wabaliŵa lala misa, ba ha wa''ato zi falukha ami, ba mikaoni ba walöŵa.', '["HalZin 13:46"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 10, 'Ba möi ba lala zawuyu no mege, ba la''ozaragö fefu zi falukha ira, si sökhi, awö zi lö sökhi, ba afönu niha si manga naha walöŵa.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 11, 'Ba me möi baulu razo, ba wamaigi si manga andrö, ba i''ila zamösa ba da''ö, si lö baru ba walöŵa.[5]', '["Yes 61:10; Efes 4:22–24"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 12, 'Ba imane khönia: He le, hadia wa möi''ö yomo ba da''e, ba lö baru ba walöŵa? Ba lö hede-hedenia.', '["Yes 61:10; Efes 4:22–24"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 13, 'Ba imane razo ba genoni: Miböbö gahenia ba tangania, ba mitibo''ö ia ba zogömi-gömi, baero sibai; ba fege-ege dania ba da''ö ba fatangisa mboha.[6]', '["Faigi 8:12"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 14, 'Ato sa nikaoni, ba lö ato nitutuyu.[7]', '["Faigi 20:16"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 15, 'Ba möi mamagölö warizaio,[8] ena''ö la''alani ia ba huhuonia.', '["Ayati 15–22: Mar 12:13–17; Luk 20:20–26"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 16, 'Ba lafatenge khönia nono zekola andrö khöra, awö zi fao-fao khö Herode, lamane: He samahaö! ma''ila, satulö ndra''ugö ba si ndruhu wangombakha''öu lala Lowalangi, ba lö ba dödöu niha, lö''ö sa öfaigi mbawa niha.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 17, 'Ba ŵa''ö khöma, hadia ba dödöu, tola labe''e mbeo khö kaizaro, ma lö''ö?', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 18, 'Ba me no aboto ba dödö Yesu walösökhira, ba imane: Hana wa mitandraigö ndra''o, samini tödö?', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 19, 'Mi''oroma''ö khögu hua mbeo andrö. Ba la''oro''ö khönia zambua hua suku.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 20, 'Ba imane khöra Yesu: Ha famaedo da''e, ba ha ökhö zura andre?', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 21, 'Ba imane khöra: Ba mibe''e khö kaizaro hadia khö kaizaro, ba khö Lowalangi hadia khö Lowalangi.[9]', '["Luk 23:2; Rom 13:7"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 22, 'Ba me larongo da''ö, ba ahöli-höli dödöra ba laröi ia, lalau mofanö.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 23, 'Me luo da''ö möi khönia zadukaio andrö,[10] sanguma''ö lö femaoso zi mate, ba lasofu khönia,[11]', '["Ayati 23–33: Mar 12:18–27; Luk 20:27–39","HalZin 23:6,8","MozV 25:5"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 24, 'lamane: He samahaö, no iŵa''ö Moze, na so zi mate niha, si lö ono, ba yamu''owalu wo''omonia talifusönia, yamufonga''ötö dalifusönia andrö.[12]', '["Ayati 23–33: Mar 12:18–27; Luk 20:27–39","HalZin 23:6,8","MozV 25:5"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 25, 'Ba no so ba khöma, dafitu si fatalifusö, ba mangowalu zi a''a ba mate; ba me lö ononia, ba khö nakhinia wo''omonia.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 26, 'Si manö göi wanete da''ö ba fanete zi darua, irugi dafitu ira.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394484, 'NT', 'Mataio', 22, 27, 'Ba ba gafuriata, furira fefu, ba mate göi galawe andrö.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 28, 'Ba ba wemaoso zi mate andrö, ba ha fo''omo ia ba zi dafitu andrö? noa sa''ae dozi zangai ya''ia.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 29, 'Ba itema lira Yesu, imane khöra: Selungu ami, lö saboto ba dödömi zura ba lö saboto ba dödömi wa''abölö Lowalangi andrö.', '["Luk 20:35"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 30, 'Ba wemaoso zi mate andrö sa, ba lö mangowalu ira, ba lö möi nihalö, hulö mala''ika Lowalangi andrö ba zorugo sa''ae ira.[13]', '["Luk 20:35"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 31, 'Ba ba wemaoso zi mate andrö, ba hadia, lö nibasomi niŵa''ö Lowalangi khömi, me imane:[14]', '["MozII 3:6"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 32, '"Lowalangi Gaberahamo ndra''o ba Lowalangi Giza''aki ba Lowalangi Yakobo?" Ba tenga Lowalangi zi mate ia, no Lowalangi zauri.', '["MozII 3:6"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 33, 'Ba me larongo da''ö niha sato, ba tobali dödöra ba wamahaönia andrö.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 34, 'Ba me larongo farizaio,[15] no ifa''afu mbawa zadukaio, ba falukha ira.', '["Ayati 34–40: Mar 12:28–34"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 35, 'Ba so zamösa khöra, sonekhe ba goroisa, sanofu khönia, ba wanandraigö ya''ia, imane:', '["Ayati 34–40: Mar 12:28–34"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 36, 'He samahaö, hezo zebua goroisa ba zura goroisa andrö?', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 37, 'Ba imane khönia: "Omasi''ö Zo''aya ya''ugö, Lowalangiu andrö, moroi si''aikö ba dödöu, nosou ma''asambua zangomasi''ö ya''ia, ba öhorigö gera-erau, wangomasi''ö ya''ia."[16]', '["MozV 6:5; 10:12"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 38, 'Da''ö zebua goroisa, da''ö zi föföna.', '["MozV 6:5; 10:12"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 39, 'Ba sambua tö, si fakhili-khili khönia: "Omasi''ö zahatö khöu, si mane fa''omasiu ndra''ugö."[17]', '["YohI 4:20,21; MozIII 19:18; Rom 13:9"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 40, 'Ba goroisa si dombua andrö manandrösa goroisa fefu, awö niŵa''ö zama''ele''ö andrö.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 41, 'Ba me falukha warizaio,[18] ba isofu khöra Yesu, imane:', '["Ayati 41–45: Mar 12:35–37; Luk 20:41–44"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 42, 'Hadia ba dödömi ba khö Keriso andrö? ha ma''uwu ia? Lamane khönia: Ma''uwu Dawido.', '[]', NULL),
  (3394484, 'NT', 'Mataio', 22, 43, 'Ba imane khöra: Ba hadia wa ibe''e töinia Zo''aya Dawido, nifarou Geheha, me imane:', '["Sin 110:1; HalZin 2:34,35; Heb 1–13"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 44, '"No iŵa''ö So''aya khö Zo''aya ya''o: Dadao ba gambölögu, irege ube''e tou barö gaheu zi fatiu tödö khöu."[19]', '["Sin 110:1; HalZin 2:34,35; Heb 1–13"]', NULL),
  (3394484, 'NT', 'Mataio', 22, 45, 'Ba na ibe''e töinia Zo''aya Dawido, ba he wisa wa ma''uwunia? Ba lö sangila manema linia, hadia ia, ba lö si lö ata''u manofu khönia sa''ae, i''otarai luo da''ö.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 1, 'Ba humede Yesu ba niha sato ba khö ndra nifahaönia,[1] imane:', '["Ayati 1–14: Mar 12:38–40; Luk 20:45–47"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 2, 'Ba dadaoma Moze dumadao zangila amakhoita andrö ba farizaio.', '["Rom 2:21"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 3, 'Ba fefu hadia ia, niŵa''öra khömi, ba mi''o''ö, böi misawö, ba böi mi''o''ö ba mbua-buara; laŵa''ö-ŵa''ö sa, ba lö latörö.[2]', '["Rom 2:21"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 4, 'Ba laböbö noro sabua ba lahare''ö ba galisi niha, ba ya''ira, ba sara turura lö labe''e, ba wamaliŵa ya''ia.[3]', '["Luk 11:46"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 5, 'Afu-afura la''ila ira niha, andrö lalau fefu nilaura andrö. La''ebolo''ö sa zura wangera-ngera andrö khöra,[4] ba la''ebua''ö mbowo-bowo mbarura andrö.[5] [6]', '["Sura wangera-ngera: ba teks asli Yunani tesura φυλακτήρια (phylaktēria) eluahania balö garate nisura bakha ayati Zura Ni''amoni''ö. Balö garate andre labe''e bakha ba sambua nahia si hulö kade side-ide. Laböbö kade andre ba gangangora ya''ira niha Yahudi faoma böbö sanau.","Bowo mbaru: ba teks asli Yunani tesura κράσπεδα (kraspeda) eluahania bu''u-bu''u dali ma bana (faigi gambara ba nga''örö andre). Te abölö faudu na laŵaö ia bowo mbana.","Faigi 6:1,2; MozIV 15:38; MozV 6:8"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 6, 'Ba no omasi ira naha tanö si yaŵa ba gowuloa ba dadaoma tanö si yaŵa ba zekola;[7]', '["Luk 11:43"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 7, 'ba omasi ira na la''owai ira ba kade, ba na labe''e töira zamahaö niha tanö bö''ö.', '["Luk 11:43"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 8, 'Ba böi ndramube''e töimi zamahaö, ha sa samösa zamahaö ya''ami, ba si fatalifusö ami fefu.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 9, 'Ba böi fa''ama ami ba niha ba guli danö, ha sa samösa Namami, si so ba zorugo.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 10, 'Ba böi ndramaube''e töimi zolohe, me ha samösa zolohe ya''ami, Keriso.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 11, 'Enonimi zebuami.[8]', '["Faigi 20:26,27"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 12, 'Ba samali''ö salaŵa ya''ia, ba ni''ide-ide''ö dania, ba sangide-ide''ö ya''ia, ba nibali''ö salaŵa.[9]', '["Faigi 18:4; Luk 14:11; 18:14; Amaed 29:23; FetI 5:5"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 13, 'Ba alai ami, sangila amakhoita, ba farizaio, samini tödö! me mikusi mbanua zorugo andrö föna niha; lö''ö sa möi ami bakha, ba lö mifa''amöi bakha zi möi ena''ö.[10]', '["Luk 11:52"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 14, 'Alai ami, sangila amakhoita ba farizaio, samini tödö! me no si manga nomo lakha mbanua ami, ba me mi''oroma''ö wangandrö sara; andrö tedou huku, nifatörö khömi.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 15, 'Alai ami, sangila amakhoita ba farizaio, samini tödö! me no sanöröi asi, awö danö, ami, ba wamali''ö solo''ö huku khömi samösa niha, ba na no i''o''ö, ba mibali''ö ono narako, mendrua manö na sa moroi khömi.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 16, 'Alai ami, solohe tanga niha bö''ö, ba no au''a ami, sanguma''ö: Na so zame''e hölu osali, ba si lö''ö da''ö, ba na so zame''e hölu ana''a gosali, ba nitörö.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 17, 'He sambö tödö, si no au''a! he zebua ira sa, ana''a, ba ma osali, same''e amonita ana''a andrö?', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 18, 'Ba mimane: Na so zame''e hölu naha wame''e sumange andrö, ba si lö''ö da''ö, ba na so zame''e hölu sumange andrö, si so yaŵa, ba nitörö.', '["MozII 29:37"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 19, 'He sau''a! he zebua ira sa, sumange andrö, ba ma naha wame''e, same''e amonita sumange andrö?[11]', '["MozII 29:37"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 20, 'Andrö, same''e hölu naha wame''e sumange, ba ibe''e hölu da''ö, fabaya si so yaŵa fefu.', '["SalI 8:13","Faigi 5:34"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 21, 'Ba same''e hölu osali, ba ibe''e hölu da''ö, fabaya si onahia osali.[12]', '["SalI 8:13","Faigi 5:34"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 22, 'Ba same''e hölu sorugo, ba ibe''e hölu dadaoma Lowalangi fabaya sidadao yaŵa.[13]', '["SalI 8:13","Faigi 5:34"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 23, 'Alai ami, sangila amakhoita ba farizaio, samini tödö! me mibe''e zambua ni''ofulu lönga ba höwa ba lada, ba no olifu ami zebua goroisa, fanguhuku ba fa''ahakhö dödö ba fa lö faröi; ni''o''ö zi sambalö, ba tenga göi ni''ositengagö zi sambalö.[14]', '["Luk 11:42"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 24, 'He solohe tanga niha, si no au''a, mitafi''ö nibadu, ba wameta di, ba mitölö kudo.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 25, 'Alai ami, sangila amakhoita ba farizaio, samini tödö! me mihaogö gero mako ba ero wiga, ba yaŵa, ba no fahöna warabu ba folu''a-lu''a.[15]', '["Luk 11:39 b.t."]', NULL),
  (3394486, 'NT', 'Mataio', 23, 26, 'He farizaio sau''a! ofönai''ö wangehao yaŵa, mako, ena''ö sökhi göi geronia.[16]', '["Tit 1:15"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 27, 'Alai ami, sangila amakhoita ba farizaio, samini tödö, me no hulö lewatö nilau betua ami, si sökhi sa moroi baero, wamaigida, ba bakha, ba no fahöna döla zi mate, awö fefu hadia ia zi ta''unö.[17]', '["Luk 11:44"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 28, 'Si manö göi ami, niha satulö ami, wamaigida, moroi baero, ba bakha, ba no fahöna wamini tödö ba fa lö atulö.', '["Luk 11:44"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 29, 'Alai ami, sangila amakhoita ba farizaio, samini tödö! me mi''a''azökhi lewatö zama''ele''ö andrö, ba me mihaogö dandra lewatö zatulö,[18]', '["Luk 11:47,48"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 30, 'ba me mimane: Na ya''aga mena''ö ba götö ndra tuada, ba lö fao ndra''aga khöra, ba wamunu sama''ele''ö andrö.', '["Luk 11:47,48"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 31, 'Tobali mifaduhu''ö dödö niha bö''ö khömi, wa no ma''uwu zamunu sama''ele''ö andrö ami.[19]', '["HalZin 7:52","TesI 2:16"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 32, 'Ba mifönui zu''a-su''a andrö khö ndra tuami.[20]', '["HalZin 7:52","TesI 2:16"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 33, 'He ulö, ono gulö! he miwisa wangefa''ö ya''ami ba wanguhuku andrö, ba narako?[21]', '["Mat 3:7"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 34, 'Andrö, hiza,[22] ufatenge khömi zama''ele''ö ba satua-tua ba sangila amakhoita, ba so dania ba mibunu, miforöfa, ba so, ba mibözi-bözi ba zekola khömi ba migohi, i''otarai mbanua si sambua, numalö ba zi sambua,[23]', '["Ayati 34–36: Luk 11:49–51","Faigi 10:17","MozI 4:8; Nga''ötII 24:20 b.t."]', NULL),
  (3394486, 'NT', 'Mataio', 23, 35, 'ena''ö möi ba hulumi fefu ndro zatulö andrö, niduwagö ba guli danö, i''otarai ndro Habeli satulö andrö, irugi ndro Zakharia, ono Mbarakhia andrö, nibunumi ba gotaluara gosali naha wame''e sumange.[24]', '["Ayati 34–36: Luk 11:49–51","Faigi 10:17","MozI 4:8; Nga''ötII 24:20 b.t."]', NULL),
  (3394486, 'NT', 'Mataio', 23, 36, 'Si ndruhu niŵa''ögu khömi, tohare dania da''ö fefu ba niha si sagötö andre.', '[]', NULL),
  (3394486, 'NT', 'Mataio', 23, 37, '[25] He Yeruzalema! he Yeruzalema! samunu sama''ele''ö andrö, sanebu kara nifatenge khönia, ha me uga no utandraigö mangowuloi onou, si mane sifagelo, na i''owuloi nononia barö gafinia, ba lö sedöna ami.', '["Ayati 37–39: Luk 13:34,35","Faigi 24:2; SalI 9:7","Faigi 21:9; Yoh 12:13"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 38, 'Hiza, teröi khömi nomomi, adudu.[26]', '["Ayati 37–39: Luk 13:34,35","Faigi 24:2; SalI 9:7","Faigi 21:9; Yoh 12:13"]', NULL),
  (3394486, 'NT', 'Mataio', 23, 39, 'Uŵa''ö sa khömi, lö''ö sa''ae mi''ila ndra''o, i''otarai da''e, irege miŵa''ö dania: Ya''ahowu zi so ba döi Zo''aya![27]', '["Ayati 37–39: Luk 13:34,35","Faigi 24:2; SalI 9:7","Faigi 21:9; Yoh 12:13"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 1, 'Ba möi baero Yesu,[1] iröi gosali, mofanö ia, ba möi khönia nifahaönia, ba wanuturu osali andrö khönia.', '["Ayati 1–28: Mar 13:1–23; Luk 21:5–24"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 2, 'Ba itema lira, imane khöra: Hadia, lö mi''ila da''ö fefu? Si ndruhu niŵa''ögu khömi, sambua lö toröi ba da''ö ba dete nawönia yaŵa, kara, si lö ladudugö.[2]', '["Luk 19:44"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 3, 'Ba me mudadao ia ba hili wanikha, ba möi khönia nifahaönia, ba zi ha ya''ira, lamane: Ombakha''ö khöma, ha wa''ara da''ö, ba hadia dandra wa''asomö ba tandra wa''atua danö.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 4, 'Ba itema lira Yesu, imane khöra: Mifaigi, fa böi ifaelungu ami niha, ha niha ia.[3]', '["Faigi 7:15; TesII 2:3"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 5, 'Ato sa dania zi möi, sanagö töigu, sanguma''ö: Ya''odo Keriso, ba ato lafaelungu.[4]', '["Yoh 5:43; HalZin 5:36 b.t."]', NULL),
  (3394487, 'NT', 'Mataio', 24, 6, 'Ba mirongo dania wanuwö ba fe''ira-ira ba wanuwö; mifaigi, böi tokea ami; lö''ö sa tola lö si manö, ba tenga fa''atua danö na sa.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 7, 'Maoso dania zi sambua soi, udu zi sambua; ba si sara öri, udu zi sara; ba soso lofo mbanua awö ndruru danö misa.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 8, 'Ba böröta wa''afökhö da''ö fefu.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 9, 'Ba da''ö dania la''ohe ami ba wamakao ba labunu ami; ba dozi soi dania zi fatiu tödö khömi, börö döigu andrö.[5]', '["Faigi 10:17 b.t.; Yoh 16:2; Fam 2:10"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 10, 'Ba ato dania ba da''ö zi te''ala, ba faoma dania la''a mböli nawöra, ba faoma fatiu dödöra khö nawöra.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 11, 'Ba ato zi maoso sama''ele''ö sofaya, ba ato lafaelungu.[6]', '["YohI 4:1"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 12, 'Ba me monönö wa lö atulö, ba ato zi taya fa''omasi.[7]', '["TimII 3:1 b.t."]', NULL),
  (3394487, 'NT', 'Mataio', 24, 13, 'Ba sanau ölö irugi gamozua, da''ö ni''orifi.[8]', '["Faigi 10:22; Yak 1:12"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 14, 'Ba teturiagö dania mbanua Lowalangi andrö, turia somuso dödö, ba guli danö misa, ma''asagörö, ba wamaduhu''ö ba niha fefu, ba awena dania fa''atua danö.[9]', '["Rom 10:18"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 15, 'Ba na mi''ila dania wa''adudu andrö, sihokha mbuda, niŵa''ö Danieli, ba naha ni''amoni''ö — yatumörö tödönia sombaso da''e[10] —', '["Dan 9:27; 12:13"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 16, 'ba ndramoloi zi so ba Yudaia, ndramusaŵa hili.', '["Dan 9:27; 12:13"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 17, 'Böi yamöi tou zi so ba dete nomonia yaŵa, ba wangai hadia ia ba nomonia,[11]', '["Luk 17:31)"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 18, 'ba böi yamufuli ia furi si so ba nowi, ba wangai barunia.', '["Luk 17:31)"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 19, 'Ba alai zanabina ba si so ono ba mbagi zusu, na luo da''ö![12]', '["Luk 23:29"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 20, 'Ba mi''angandrö, fa böi baŵa deu, ba fa böi luo sabato, na luo woloimi andrö.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 21, 'So sa wamakao sabölö-bölö ba da''ö dania, si lö irai si manö, i''otarai mböröta danö, irege da''e, ba lö''ö göi si manö dania.[13]', '["Dan 12:1"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 22, 'Ba na tenga ni''önaigö luo da''ö ena''ö, ba samösa lö auri niha. Ba börö nitutuyu andrö, wa te''önaigö luo andrö.', '["Dan 12:1"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 23, 'Ba na so ba da''ö zanguma''ö khömi: Faigi, so ba da''e Keriso, ba ma: ba da''ö so ia, ba böi mifati.[14]', '["Luk 17:21,23 b.t."]', NULL),
  (3394487, 'NT', 'Mataio', 24, 24, 'Maoso sa dania Keriso faya ba sama''ele''ö sofaya, ba lafazökhi dandra sebua, awö gila-ila, ba wamaelungu nitutuyu andrö, na böla.[15]', '["TesII 2:9"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 25, 'Hiza, no uhönagö uŵa''ö khömi.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 26, 'Ba na lamane khömi: Hiza, ba danö si mate so ia, ba böi mi''ae''e; ba ma: Hiza, ba mbate''e, ba böi mifati.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 27, 'Hulö gari mbanua sa si otarai gatumbukha luo, sihaga, irege gaekhula, si manö dania wa''aso Nono Niha andrö.[16]', '["Luk 17:24"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 28, 'Ba zi so amatela, ba da''ö owulu moyo.[17]', '["Yob 39:30; Luk 17:37"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 29, 'Ba aefa si''aikö wamakao andrö,[18] na luo da''ö, ba taya haga luo, ba lö''ö sa''ae humaga mbaŵa, ba atoru ndröfi moroi ba mbanua si yaŵa, ba humeu-heu wangaro mbanua si yaŵa.[19]', '["Ayati 29–36: Mar 13:24–32; Luk 21:25–33","Yes 13:10; Fam 6:12 b.t."]', NULL),
  (3394487, 'NT', 'Mataio', 24, 30, 'Ba aefa da''ö, ba oroma dandra Nono Niha andrö ba mbanua si yaŵa, ba mege-ege fefu soi ba guli danö, ba la''ila dania Nono Niha, si so moroi si yaŵa, ba dete lawuo ba mbanua, fao wa''abölö ba lakhömi sebua.[20]', '["Faigi 25:31; Dan 7:13; Fam 1:7; Mar 14:62"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 31, 'Ba ifatenge mala''ikania, telau dorofe sebua li, ba la''owuloi khönia nitutuyunia andrö, moroi ba zi fasui, i''otarai wondrege danö, numalö ba wondregenia tanö sa.[21]', '["Faigi 13:41; TesI 4:16"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 32, 'Ba ba marafala mitöngöni wamaedo andrö: Na mo''idanö ndrahania, na tumbu lehe-lehe, ba mi''ila, no ahatö mbaŵa wa''aukhu zino.[22]', '["Luk 21:37"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 33, 'Si manö göi ami, na mi''ila da''ö fefu, ba oroma khömi, no ahatö ia.', '["Faigi 16:28"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 34, 'Si ndruhu niŵa''ögu khömi, lö fakhamö atua niha si sagötö andre, ba no alua da''ö fefu.[23]', '["Faigi 16:28"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 35, 'Atua mbanua ba atua danö, ba lö awu''a niŵa''ögu.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 36, 'Ba baŵa andrö ba inötö, ba lö sangila, he mala''ika ba zorugo, he Ono; ha Ama zangila.[24]', '["TesI 5:1 b.t."]', NULL),
  (3394487, 'NT', 'Mataio', 24, 37, 'Ba hulö si mane me luo Noakhi,[25] si manö göi wa''aso Nono Niha andrö dania.[26]', '["Ayati 37–41: Luk 17:26–36","MozI 6:5,11 b.t."]', NULL),
  (3394487, 'NT', 'Mataio', 24, 38, 'Hulö si mane ya''ira sa, me luo föna wa''anönö danö andrö, manga-manga ira ba mamadu-madu hadia ia, mangowalu ba mame''e nihalö, irugi luo möi baowo Noakhi,', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 39, 'ba lö aboto ba dödöra, irege so wa''anönö andrö ba irege ahori ira fefu, si manö göi dania wa''aso Nono Niha andrö.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 40, 'Darua dania zi so ba nowi; samösa nihalö ba si samösa, ba niröi.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 41, 'Darua ndra alawe sanutu fakhe ba lösu; samösa nihalö ba si samösa, ba niröi.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 42, 'Andrö, böi miförö, me lö mi''ila mbaŵa wa''aso Zo''aya ya''ami.[27]', '["Faigi 25:13; Mar 13:33"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394487, 'NT', 'Mataio', 24, 43, 'Ba da''ö mibe''e ba dödömi: Na i''ila ena''ö sokhö omo, ha wa''alaŵa mbongi so zanagö, ba lö mörö ia ena''ö, ba itimba ena''ö zanagö, fa lö möi yomo khönia.[28]', '["Luk 12:39 b.t.; FetII 3:10; Fam 3:3"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 44, 'Andrö ya''ami göi, mihönagö mifa''anö ami, me si lö midöna-döna dania Nono Niha, na so ia.', '[]', NULL),
  (3394487, 'NT', 'Mataio', 24, 45, 'Ba ha niha zawuyu andrö,[29] si lö faröi, satua-tua, nibe''e zokhö ya''ia barö mbawa si so yomo khönia, ba wame''e göra, na inötö wemanga?', '["Ayati 45–51: Luk 12:42–46"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 46, 'ya''ahowu zawuyu andrö, na i''ila sokhö ya''ia, na so ia, no i''o''ö da''ö.', '["Ayati 45–51: Luk 12:42–46"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 47, 'Si ndruhu niŵa''ögu khömi, ibe''e barö mbawania fefu hadia ia, zi so khönia.', '["Ayati 45–51: Luk 12:42–46"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 48, 'Ba na iŵa''ö tödönia sawuyu si lö sökhi: Mogasa wa''aso zokhö ya''o,', '["Faigi 22:13; 25:30"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 49, 'ba na ibörötaigö ibözi-bözi nawönia sawuyu, ba na manga-manga ia, ba na ibadu-badu hadia ia, awö zi mabu-mabu andrö;', '["Faigi 22:13; 25:30"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 50, 'ba so dania zokhö sawuyu andrö, na luo lö idöna-döna ba gamaudu wa''alaŵa luo, na iwai lö ya''ia na;', '["Faigi 22:13; 25:30"]', NULL),
  (3394487, 'NT', 'Mataio', 24, 51, 'ba i''ötö dalu zawuyu andrö, ba ibe''e gurakhania awö zamini tödö andrö; ba fege-ege dania ba da''ö ba fatangisa mboha.[30]', '["Faigi 22:13; 25:30"]', NULL),
  (3394489, 'NT', 'Mataio', 25, 1, 'Ba da''ö dania fakhili-khili ira mbanua zorugo andrö nono alawe, dafulu, sangai fandrura, ba we''amöi mamaondragö sangowalu.', '["Fam 19:7 b.t.; KorII 11:2"]', NULL),
  (3394489, 'NT', 'Mataio', 25, 2, 'Ba dalima ira zambö tödö, ba dalima zatua-tua.', '["Fam 19:7 b.t.; KorII 11:2"]', NULL),
  (3394489, 'NT', 'Mataio', 25, 3, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394491, 'NT', 'Mataio', 26, 46, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394495, 'NT', 'Mataio', 28, 5, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394502, 'NT', 'Mareko', 3, 12, 'Ba itenaŵa sibai ira, fa böi la''ombakha''ö ia.[8]', '["1:24,34; Luk 4:41","Mat 12:16"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 13, 'Ba möi ia ba hili, humede ia ba zomasi ia, ba la''ondrasi.[9]', '["Ayati 13–19: Mat 10:1–4; Luk 6:12–16"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 14, 'Ba i''oniagö zi felendrua, ena''ö awönia ira ba ena''ö ifatenge ira ba wangombakha,[10]', '["Mat 10:5","Luk 9:54"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 15, 'ena''ö tetehe khöra wamofanö bekhu andrö.', '["Mat 10:5","Luk 9:54"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 16, 'I''oniagö zi felendrua andrö, ibe''e töi Zimoni andrö Wetero,', '["Mat 10:5","Luk 9:54"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 17, 'awö Yakobo, ono Zebedaio, ba Yohane, talifusö Yakobo, ba ibe''e töi zi darua andrö Mboaneregesi, — ono we''ugu-ugu mbanua geluahania;[11]', '["Mat 10:5","Luk 9:54"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 18, 'ba Andrea ba Filifo ba Batolomaio ba Mataio ba Toma ba Yakobo, ono Galifaio andrö, ba Tadaio, ba Simoni Kananaio,', '["Mat 10:5","Luk 9:54"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 19, 'ba Yuda, banua Kariota, si manga mbölinia andrö.', '["Mat 10:5","Luk 9:54"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 20, 'Ba möi ia yomo. Ba owulo zui niha sato, tobali tebai na i manga ira.[12]', '["Faigi faza 6:31"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 21, 'Ba me larongo da''ö talifusönia, ba möi ira mondra''u ya''ia, noa sa owöhö ia, laŵa''ö.[13]', '["Mat 12:24–32; Luk 11:14–23"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 22, 'Ba lamane sangila amakhoita andrö,[14] si no möi mitou moroi ba Yeruzalema: No so khönia Mbelesebu, ba moroi ba zalaŵa mbekhu andrö, wa ifofanö mbekhu.[15]', '["Ayati 22–30: Mat 12:24–32; Luk 11:14–23","Yoh 8:48"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 23, 'Ba ifalukha''ö ira, iŵa''ö khöra gamaedola, imane: He wisa ifofanö Zatana Satana?', '["Mat 12:27","Luk 11:21","Luk 12:10","Yoh 10:20"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 24, 'Ba na fabali dödö nöri, ba tebai aro nöri andrö.', '["Mat 12:27","Luk 11:21","Luk 12:10","Yoh 10:20"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 25, 'Ba na fabali dödö zi sangambatö, ba lö fakhai zi samba omo andrö.[16]', '["Mat 12:27","Luk 11:21","Luk 12:10","Yoh 10:20"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 26, 'Ba na no ilaŵa ia Satana ba na dua dödönia, ba lö fakhai, awai sa''ae.', '["Mat 12:27","Luk 11:21","Luk 12:10","Yoh 10:20"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 27, 'Lö''ö sa sangila möi baomo ba nomo zabölö, ba worabu gama-gamania, na lö ihönagö iböbö zabölö andrö, ba awena irabu hadia ia ba nomonia.[17]', '["Mat 12:27","Luk 11:21","Luk 12:10","Yoh 10:20"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 28, 'Si ndruhu niŵa''ögu khömi, fefu ngawalö horö andrö, ba tebe''e aefa ba nono niha; he fanandraŵa andrö, ha wa''oya wanandraŵara,[18]', '["Mat 12:27","Luk 11:21","Luk 12:10","Yoh 10:20"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 29, 'ha na so zanandraŵaisi Eheha ni''amoni''ö andrö, ba lö fangefa khönia, götö wa''ara dania; ilu''i horö andrö, götö-götö wa''ara. —', '["Mat 12:27","Luk 11:21","Luk 12:10","Yoh 10:20"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 30, 'Me laŵa''ö: "Sobekhu ia, bekhu si ra''iö."[19]', '["Mat 12:27","Luk 11:21","Luk 12:10","Yoh 10:20"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 31, 'Ba so ninania ba ira talifusönia,[20] no so baewali ba lafatenge khönia, lafahede''ö khönia', '["Ayati 31–35: Mat 12:46–50; Luk 8:19–21"]', NULL),
  (3394502, 'NT', 'Mareko', 3, 32, 'Ba no lafasui ia wedadao niha sato. Ba lamane khönia: Hiza, no so baero ninau ba ira talifusöu matua ba ira talifusöu alawe, la''alui ndra''ugö.', '[]', NULL),
  (3394502, 'NT', 'Mareko', 3, 33, 'Ba itema lira, imane: Ha niha ninagu, ba ha niha dalifusögu?', '[]', NULL),
  (3394502, 'NT', 'Mareko', 3, 34, 'Ba ifakhölö ia, ifaigi zi tefasui ya''ia si dadao, ba imane: Hiza ninagu ba taliftusögu.', '[]', NULL),
  (3394502, 'NT', 'Mareko', 3, 35, 'Solo''ö somasi Lowalangi, da''ö dalifusögu matua ba talifusögu alawe ba inagu.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 1, 'Ba ifuli ibörötaigö mamahaö,[1] ba zinga mbaŵa. Ba ato sibai zowulo khönia niha, tobali möi ia ba nowo, mudadao ia, ba nidanö yaŵa, ba ba mbewe nidanö so niha sato fefu, baene.', '["Ayati 1–25: Mat 13:1–23; Luk 8:4–18"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 2, 'Ba ifahaö ira, oya ilau amaedola, ba imane khöra ba wamahaönia andrö:', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 3, 'Mifondrondrongo! Hiza, möi baero zamazaewe tanömö zinanö, ba wamazaewe tanömö andrö;', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 4, 'ba tobali, ba wamazaewe andrö, ba so ösa zi göna ba lala; ba so wofo, ba la''a.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 5, 'Ba so ösa zi göna ba zokara, ba zi lö abölö tanö khönia, ba i''anema''ö motalinga, me lö awe''e-we''e danö khönia.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 6, 'Ba me no tumbu luo, ba asoso ia ba aleu, börö wa lö ŵa''ania.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 7, 'Ba so ösa zi göna ba gotalua ndroi, ba manöi ndroi ba ibunu, ba lö bua.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 8, 'Ba so ösa zi göna ba danö si sökhi andrö, ba mowua, motalinga ba manöi, so zowua si önö, zamba yöu, so zi felendrua ba so zi dua wulu.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 9, 'Ba imane: Si so tögi dalinga ba wamondrongo, ba yamufondrondrongo!', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 10, 'Ba me no mofanö niha, ba lasofu khönia si fao khönia, awö zi felendrua, ba gamaedola andrö.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 11, 'Ba imane khöra: Khömi no mube''e zi tobini andrö, he wisa mbanua Lowalangi, ba ba khöra si so baero andrö, ba oi ba gamaeldola larongo, ena''ö anehe höröra,', '["Yes 6:9.10"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 12, 'ba lö''ö zui la''ila, ba larongo tögi dalingara, ba lö''ö zui aboto ba dödöra, fa lö lafuli ira ba fa lö tebe''e aefa khöra horöra.[2]', '["Yes 6:9.10"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 13, 'Ba imane khöra: Lö mi''ila geluaha gamaedola andrö, ba he moroi aboto ba dödömi gamaedola soya?', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 14, 'Taroma li nifazaewe zamazaewe tanömö andrö.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 15, 'Ba da''ö zi so ba lala andrö: tefazaewe daroma li, ba na larongo, ba i''anema''ö so Zatana andrö, ba iheta daroma li andrö, nifazaewe ba dödöra.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 16, 'Ba si manö nifazaewe ba danö sokara andrö, da''ö ira: i''anema''ö lafonaha daroma li, na larongo, omuso dödöra,', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 17, 'ba lö wa''ania ba dödöra, niha samangörö li ira, dania, na so wamakao, ba ma folohi, ba daroma li andrö, ba i''anema''ö lafuli furi.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 18, 'Ba bö''ö nifazaewe ba gotalua ndroi: da''ö ira, si no mamondrongo taroma li,', '["Faigi 10:23"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 19, 'ba fatewu wa''abu dödö andrö ba gulidanö ba famaelungu andrö, ba gana''a, ba hadia ia gisö-isö bö''ö, ba ibunu daroma li andrö, ba tobali lö bua.[3]', '["Faigi 10:23"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 20, 'Ba da''ö nifazaewe ba danö si sökhi andrö: samondrongo taroma li ba samonahia ya''ia ba sowua; so zi önö, zamba yöu, so zi felendrua ba so zi dua wulu.[4]', '["Yoh 18:57"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 21, 'Ba imane khöra: Hadia, andrö so wandru, ena''ö tabe''e barö dumba yöu, ba ma barö warate? Tenga andrö so ia, ena''ö tabe''e ba naha wandru yaŵa?[5]', '["Mat 5:15; Luk 11:33","Mat 1:6"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 22, 'Lö''ö sa hadia ia zi tobini, na tenga ba wama''ele''ö ya''ia dania, ba lö hadia ia zi lö oroma, ha ba wangoroma''ö ya''ia dania.[6]', '["Mat 5:15; Luk 11:33","Mat 1:6"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 23, 'Na so zi so tögi dalinga ba wamondrongo, ba yamufondrondrongo!', '["Mat 5:15; Luk 11:33","Mat 1:6"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 24, 'Ba imane khöra: Mitöngöni nirongomi! Su''a-su''a ni''anu''a''ömi, la''anu''a''ö khömi, ba ladou''ö na khömi.[7]', '["Mat 7:2; Luk 6:38","Mat 13:12"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 25, 'Ba zi so, ba tebe''e na, ba ba zi lö''ö, ba teheta göi hadia zi so khönia.[8]', '["Mat 7:2; Luk 6:38","Mat 13:12"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 26, 'Ba imane: Si mane mbanua Lowalangi andrö, hulö na itibo''ö ba danö danömö zinanö niha.', '["Sin 127:2"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 27, 'Ba mörö ia ba maoso, bongi ma''ökhö, ba motalinga danömö andrö ba manöi, lö''ö sa i''ila,[9]', '["Sin 127:2"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 28, 'mowua manö danö, ha ya''ia, öföna döla, awena ngalai, awena zi ndruhu nösi ba ngalai.', '["Sin 127:2"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 29, 'Ba na basitö, ba i''anema''ö ifatenge zamasi, me no irugi famasi.', '["Sin 127:2"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 30, 'Ba imane:[10] Hadia tabe''e famaedo mbanua Lowalangi andrö? Ba heza tahalö gamaedolania?', '["Ayati 30–34: Mat 13:31,32,34; Luk 13:18,19","\"Lada\": sinanö andre tumbu ba danö Timur Tengah ba lö ba Danö Niha andrö wa ifo''eluaha manö ia Sundermann \"lada\". Ba li Indonesia latötöi ia sesawi hitam (töi ilmiahnia Brassica nigra). Fa''alaŵania tola irugi 1,2 m."]', NULL),
  (3394503, 'NT', 'Mareko', 4, 31, 'Hulö mbua lada,[11] si no fondrege zide-ide mbua zinanö, na tefazaewe ba danö.', '["Ayati 30–34: Mat 13:31,32,34; Luk 13:18,19","\"Lada\": sinanö andre tumbu ba danö Timur Tengah ba lö ba Danö Niha andrö wa ifo''eluaha manö ia Sundermann \"lada\". Ba li Indonesia latötöi ia sesawi hitam (töi ilmiahnia Brassica nigra). Fa''alaŵania tola irugi 1,2 m."]', NULL),
  (3394503, 'NT', 'Mareko', 4, 32, 'Ba na no mufazaewe ia, ba manöi ba tobali ebua moroi ba ngawalö gule-gule fefu ba modaha sebua ia, tobali la''ila mangazuni ba lumönia fofo, si so ba dalu mbanua.', '["Ayati 30–34: Mat 13:31,32,34; Luk 13:18,19","\"Lada\": sinanö andre tumbu ba danö Timur Tengah ba lö ba Danö Niha andrö wa ifo''eluaha manö ia Sundermann \"lada\". Ba li Indonesia latötöi ia sesawi hitam (töi ilmiahnia Brassica nigra). Fa''alaŵania tola irugi 1,2 m."]', NULL),
  (3394503, 'NT', 'Mareko', 4, 33, 'Ba oya ngawalö gamaedola si manö ilau khöra, wamahaö ya''ira; ifaigi zi tola lafondrondrongo.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 34, 'Lö''ö sa huhuonia khöra, si tenga amaedola. Ba khö nifahaönia i''ombakha''ö geluaha fefu, ba zi ha ya''ira.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 35, 'Ba me luo da''ö, me tanö owi, ba imane khöra:[12] Möi ita miyefo.', '["Ayati 35–41: Mat 8:18,23–27; Luk 8:22–25"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 36, 'Ba me no lafofanö niha sato, ba la''ohe manö ia baowo; ba so zi fao khönia owo bö''ö.', '["Ayati 35–41: Mat 8:18,23–27; Luk 8:22–25"]', NULL),
  (3394503, 'NT', 'Mareko', 4, 37, 'Ba ilabu bade sabe''e ba ihawui nowo dulu, tobali abuso sa''ae idanö.', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 38, 'Ba no so ia ba gi''o, mörö, no manandraya ia. Ba lasusugi ia, lamane khönia: He samahaö! hadia, lö ba dödöu, na tekiko ita?', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 39, 'Ba maoso ia ba itenaŵa nangi ba imane ba ndrulu: Böi hede-hede sa''ae, honogö''ö!', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 40, 'Ba imane khöra: Hadia wa ada''u-da''u ami si manö? Hana wa lö famati khömi?', '[]', NULL),
  (3394503, 'NT', 'Mareko', 4, 41, 'Ba ata''u sibai ira, ba faoma lamane khö nawöra: Ha niha da''ö, wa lafondrondrongo göi linia angi ba dulu?', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 1, 'Ba larugi zi tambai mbaŵa,[1] danö Gerasa.', '["Ayati 1–20: Mat 8:28–34; Luk 8:26–39"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 2, 'Ba ha ihundragö danö, moroi ba nowo, ba i''anema''ö i''ondrasi ia niha, soroi lewatö, si so bekhu si ra''iö.', '["Ayati 1–20: Mat 8:28–34; Luk 8:26–39"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 3, 'Ba lewatö soso ia, ba lö sangila mamöbö ya''ia, he rate wamöbö.', '["Ayati 1–20: Mat 8:28–34; Luk 8:26–39"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 4, 'Noa sa asese teböbö ia böbö gahe ba rate danga, ba i''etu''ö rate danga ba irekha mböbö gahe andrö, ba lö sangila molaŵa ya''ia.', '["Ayati 1–20: Mat 8:28–34; Luk 8:26–39"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 5, 'Ba ba lewatö soso ia ba ba hili, lö mamalö-malö, bongi ma''ökhö, mu''ao-ao ia ba i''olobigö khönia gara.', '["Ayati 1–20: Mat 8:28–34; Luk 8:26–39"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 6, 'Ba me i''ila Yesu, moroi ba zaröu, ba fagohi ia, ituhi danö fönania,', '["Faigi 1:24"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 7, 'mu''ao ia, ebua sibai li, imane: Hadia niŵa''öu khögu, Yesu, Ono Lowalangi Fondrege Zalaŵa? Ube''e ba hölu ndra''ugö, khö Lowalangi, fa böi öfakao ndra''o![2]', '["Faigi 1:24"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 8, 'Imane sa khönia: Beta''ögö bekhu si ra''iö, röi niha andrö!', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 9, 'Ba isofu khönia: Hadia döiu? Ba imane khönia: Liwu döigu; me no ato sibai ndra''aga.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 10, 'Ba iforege wangandrö khönia, ena''ö lö ifofanö ira, lö iheta ira ba danö andrö.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 11, 'Ba so ba da''ö ba gahe hili mbawi, sambawa, nikubaloi, oya sibai.', '["Luk 8:31"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 12, 'Ba la''andrö khönia, lamane: Fatenge ndra''aga ba mbawi andrö, ena''ö mabe''e nahiama ira.[3]', '["Luk 8:31"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 13, 'Ba itehe khöra. Ba laheta ira bekhu si ra''iö andrö, lasaŵa mbawi andrö. Ba latibo''ö ira ba mbaŵa bawi si sambawa andrö, moroi ba zanaere, mato dua ngahönö, ba alömö ba da''ö.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 14, 'Ba moloi gubalora, la''ombakha''ö yaomo ba mbanua ba ba halama misa; ba möi ira mufaigi, he wisa.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 15, 'Ba larugi Yesu ba la''ila zi so bekhu andrö, no dumadao, no monukha, no taya wa''owöhö, si so liwu andrö no mege, ba ata''u ira.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 16, 'Ba sangila mege, ba la''ombakha''ö khöra, he wisa mege ba zobekhu andrö, ba hadia ia ba mbawi andrö.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 17, 'Ba labörötaigö la''andrö khönia, ena''ö iheta ia ba danöra.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 18, 'Ba me möi ia baowo, ba i''andrö khönia sobekhu andrö mege, ena''ö fao ia khönia.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 19, 'Ba lö i''ohe, imane sa khönia: Fuli''ö yomo khömi, ba ombakha''ö khöra, ha wa''ebua wanolo Zo''aya ya''ugö ba fa''ahakhö dödönia ndra''ugö.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 20, 'Ba möi ia, ibörötaigö i''ombakha''ö ba zi fulu banua, ha wa''ebua wanolo Yesu ya''ia ba oi ahöli-höli dödöra.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 21, 'Ba me no irugi si yefo Yesu,[4] ba nowo, ba owulo khönia niha, ato sibai; ba no so ia ba mbewe mbaŵa.', '["Ayati 21–43: Mat 9:1,18–26; Luk 8:40–56"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 22, 'Ba so zamösa, satua zekola, Ya''iro döi, ba me i''ila ia, ba ituhi danö fönania,', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 23, 'iforege wangandrö khönia, imane: Torege khö nonogu alawe, ena''ö möi''ö ba ötufa ia tangau, ena''ö abe''e ba ena''ö auri.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 24, 'Ba möi ia, fao ia khönia. Ba la''o''ö niha, ato sibai; fadege ira khönia.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 25, 'Ba so ndra alawe, sendro talu,[5] no mewelendrua fakhe wa''ara,', '["Sendro talu no sambua wökhö si göna ndra''alawe na aduwa ndro moroi ba wa''alawe tenga ha ba ginötö alua mbaŵa khöra (li Indonesia menstruasi). Oya mbörö aduwa ndro andre, ba gotaluania fökhö nifotöi fibroids ma ba li Indonesia tumor rahim. So fibroids sabölö sikho nifotöi kanker rahim, bahiza fökhö nifadöhö Yesu andre te tumor rahim börö me no ara sibai lö ebua zikhonia (felendrua fakhe). Moguna tetöngöni niŵa''ö Yesu ba ayati 34, wa samadöhö fökhö ndra''alawe andrö famati ndra''alawe andrö samösa.","Faigi 6:56"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 26, 'no erege sibai dödönia ba zodalu-daluni, no ato, ba no ahori ibe''e gana''ania, ba lö si to''ila, no itugu abölö-bölö na i.', '["Sendro talu no sambua wökhö si göna ndra''alawe na aduwa ndro moroi ba wa''alawe tenga ha ba ginötö alua mbaŵa khöra (li Indonesia menstruasi). Oya mbörö aduwa ndro andre, ba gotaluania fökhö nifotöi fibroids ma ba li Indonesia tumor rahim. So fibroids sabölö sikho nifotöi kanker rahim, bahiza fökhö nifadöhö Yesu andre te tumor rahim börö me no ara sibai lö ebua zikhonia (felendrua fakhe). Moguna tetöngöni niŵa''ö Yesu ba ayati 34, wa samadöhö fökhö ndra''alawe andrö famati ndra''alawe andrö samösa.","Faigi 6:56"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 27, 'Ba me irongo da''ö khö Yesu, ba möi ia, ba hunö niha, moroi furi, ibabaya mbarunia.', '["Sendro talu no sambua wökhö si göna ndra''alawe na aduwa ndro moroi ba wa''alawe tenga ha ba ginötö alua mbaŵa khöra (li Indonesia menstruasi). Oya mbörö aduwa ndro andre, ba gotaluania fökhö nifotöi fibroids ma ba li Indonesia tumor rahim. So fibroids sabölö sikho nifotöi kanker rahim, bahiza fökhö nifadöhö Yesu andre te tumor rahim börö me no ara sibai lö ebua zikhonia (felendrua fakhe). Moguna tetöngöni niŵa''ö Yesu ba ayati 34, wa samadöhö fökhö ndra''alawe andrö famati ndra''alawe andrö samösa.","Faigi 6:56"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 28, 'Imane: He ha barunia ubabaya, ba aurido.[6]', '["Sendro talu no sambua wökhö si göna ndra''alawe na aduwa ndro moroi ba wa''alawe tenga ha ba ginötö alua mbaŵa khöra (li Indonesia menstruasi). Oya mbörö aduwa ndro andre, ba gotaluania fökhö nifotöi fibroids ma ba li Indonesia tumor rahim. So fibroids sabölö sikho nifotöi kanker rahim, bahiza fökhö nifadöhö Yesu andre te tumor rahim börö me no ara sibai lö ebua zikhonia (felendrua fakhe). Moguna tetöngöni niŵa''ö Yesu ba ayati 34, wa samadöhö fökhö ndra''alawe andrö famati ndra''alawe andrö samösa.","Faigi 6:56"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 29, 'Ba i''anema''ö otufo ndro andrö khönia, ba to''ila ba nösinia, wa no döhö wamakao andrö khönia.', '["Sendro talu no sambua wökhö si göna ndra''alawe na aduwa ndro moroi ba wa''alawe tenga ha ba ginötö alua mbaŵa khöra (li Indonesia menstruasi). Oya mbörö aduwa ndro andre, ba gotaluania fökhö nifotöi fibroids ma ba li Indonesia tumor rahim. So fibroids sabölö sikho nifotöi kanker rahim, bahiza fökhö nifadöhö Yesu andre te tumor rahim börö me no ara sibai lö ebua zikhonia (felendrua fakhe). Moguna tetöngöni niŵa''ö Yesu ba ayati 34, wa samadöhö fökhö ndra''alawe andrö famati ndra''alawe andrö samösa.","Faigi 6:56"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 30, 'Ba i''anema''ö i''ila Yesu, ba khönia, wa no aheta khönia wangabölö andrö, ba ibali''ö ia ba hunö niha, imane : Ha niha zombambaya barugu.[7]', '["Luk 6:19"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 31, 'Ba lamane khönia nifahaönia: Ö''ila wa fadege khöu niha, ba ömane: Ha niha zombambaya ya''o?', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 32, 'Ba ifakhölö ia, wamaigi solau da''ö.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 33, 'Ba ata''u ndra alawe no mege, manizi-nizi, me no i''ila, hewisa khönia, ba möi ia, ituhi danö fönania, i''ombakha''ö he wisa zi ndruhunia fefu.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 34, 'Ba imane khönia: He onogu, no i''orifi ndra''ugö famatimö andrö; fuli''ö, ya''ohahau dödöu ba yadöhö wamakao andrö khöu![8]', '["Faigi 10:52"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 35, 'Ba me muhede ia na, ba so, zinenge zatua zekola no mege, lamane: No mate nonou; hadia wa öfakao na zamahaö andrö?', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394504, 'NT', 'Mareko', 5, 36, 'Ba i''osilömurongogö Yesu niwa''öra andrö, imane khö zatua zekola andrö: Böi ata''ufi, amati manö.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 37, 'Ba lö itehe fao khönia niha, ha Fetero ba Yakobo ba Yohane, talifusö Yakobo.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 38, 'Ba larugi yomo ba nomo zatua zekola andrö, ba i''ila wagua-guasa andrö, awö ze''e, awö zange''esi, wa''abölö-bölö.', '["Yoh 11:11"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 39, 'Ba möi ia yomo, imane khöra: Hadia wa fagua-gua ami ba hadia wa mege-ege? Tenga si mate nono andrö, si mörö.[9]', '["Yoh 11:11"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 40, 'Ba la''igi-igi''ö ia.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 41, 'Ba ira''u danga nono, imane khönia: Talita kumi! Faoso ono alawe, uŵa''ö khöu! geluahania.[10]', '["Luk 7:14"]', NULL),
  (3394504, 'NT', 'Mareko', 5, 42, 'Ba i''anema''ö maoso nono alawe andrö ba mowaö-waö; so sa mewelendrua fakhe wa''ebuania. Ba i''anema''ö tobali sibai dödöra.', '[]', NULL),
  (3394504, 'NT', 'Mareko', 5, 43, 'Ba i''abe''e''ö linia wanguma''ö khöra, ena''ö lö irongo da''ö niha, ha niha ia; ba iŵa''ö, ena''ö labe''e gö nono andrö.[11]', '["Faigi 1:44; 7:36"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 1, 'Ba mofanö ia ba da''ö.[1] Ba irugi mbanuara ba la''o''ö ia nifahaönia.', '["Ayati 1–6: Mat 13:54–58; Luk 4:16, 22–24"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 2, 'Ba me luo sabato, ba ibörögö mamahaö ya''ira ba zekola.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 3, 'Tenga tuka andrö, ono Maria andrö, tenga talifusö ndra Yakobo, Yose, Yuda, Simoni? Ba talifusönia alawe andrö, ba tenga ba da''e khöda so?', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 4, 'Ba imane khöra Yesu: Lö te''ositengagö zama''ele''ö, na tenga ba mbanuara ba na tenga ba zahatö khönia ba moroi yomo khöra.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 5, 'Ba tebai ifazökhi dandra ba da''ö, hadia ia, ha ma''ifu zofökhö itufa tanga, ifadöhö wökhö.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 6, 'Ba ahöli-höli dödönia ba wa lö mamati ira. Ba itörö misa mbanua si fasui, mamahaö ia.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 7, 'Ba humede ia ba zi felendrua,[2] ibörötaigö ifatenge ira, daru-darua, itehe khöra wamofanö bekhu si ra''iö.', '["Ayati 7–13: Mat 10:1,9–15; Luk 9:1–6; 10:4–12","Mat 10:10"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 8, 'Ba i''oroi''ö khöra, böi la''ohe hadia ia ba lala, ha si''o. Böi la''ohe roti, böi la''ohe mbola ba böi kefe ba mböbö talu[3]', '["Ayati 7–13: Mat 10:1,9–15; Luk 9:1–6; 10:4–12","Mat 10:10"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 9, '(ba mobadagahe sa) ba böi dua görö mbarura.', '["Ayati 7–13: Mat 10:1,9–15; Luk 9:1–6; 10:4–12","Mat 10:10"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 10, 'Ba imane khöra: Ba zi möi ami yomo, ba da''ö mi''iagö, irege mofanö ami ba da''ö.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 11, 'Ba na so mbanua, si lö mama''amöi yomo ya''ami ba si lö mamondrongo limi, ba miheta ami ba da''ö, mi''anotogö gawu-gawu ba gahemi, ba wamaduhu''ö khöra.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 12, 'Ba mofanö ira mangombakha, lamane: Mifalalini gera-era!', '["Yak 5:14"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 13, 'Ba oya lafofanö mbekhu ba ato zofökhö labayoini fanikha, lafadöhö wökhö.[4]', '["Yak 5:14"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 14, 'Ba irongo razo Herode;[5] noa sa teturia döinia. Baimane: Nomaoso Yohane andrö, samayagö idanö, moroi ba ngai zi mate, andrö so khönia wa''abölö andrö.', '["Ayati 14–29: Mat 14:1–12; Luk 9:79","Faigi 8:28"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 15, 'Ba so zanguma''ö, Eliya; ba so, ba sama''ele''ö laŵa''ö; hulö zama''ele''ö andrö föna, samösa.[6]', '["Ayati 14–29: Mat 14:1–12; Luk 9:79","Faigi 8:28"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 16, 'Ba me irongo Herode, ba imane: Yohane andrö, nifa''eŵa''ögu bagi, da''ö zi no maoso.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 17, 'Noa sa ifatenge Herode, no ifara''u''ö Yohane, no laböbö ba gurunga, börö Herodia andrö, fo''omo dalifusö Herode, Filifo, me no ihalö Herode.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 18, 'Noa sa iŵa''ö Yohane khö Herode: Lö tola so khöu wo''omo dalifusöu.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 19, 'Ba no afökhö dödö Herodia andrö khönia, ibunu ena''ö, ba tebai.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 20, 'Noa sa ata''u Herode Yohane, me no i''ila wa no niha satulö, ni''amoni''ö, ba ifatarogö''ö, ba auli abu dödönia, na irongo linia, ba omasi ia, ifondrondrongo.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 21, 'Ba baŵa senahöi: fatome Herode, awönia salaŵa ba kumandra andrö ba salaŵa andrö ba Galilaia, me baŵa wa''atumbunia.', '["Est 5:8,6"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 22, 'Ba möi yomo nono Herodia andrö, alawe, manari, ba omasi Herode ba tomenia. Ba imane razo khö nono alawe andrö: Andrö khögu hadia zomasi''ö, ba ube''e khöu; fahölu ia khönia:', '["Est 5:8,6"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 23, 'Hadia ia ni''andröu khögu, ube''e khöu, irugi zi matonga mbanuagu.[7]', '["Est 5:8,6"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 24, 'Ba möi ia baero, imane khö ninania: Hadia zi sökhi ni''andrögu?', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 25, 'Ba i''anema''ö ifuli ia khö razo no mege, i''aliogö, i''andrö, imane: Omasido, iada''e sibai öbe''e khögu, ba wiga yaŵa, högö Yohane andrö, samayagö idanö.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 26, 'Ba abu sibai dödö razo, ba ba wahölusa no mege ba ba dome andrö, ba lö edöna ia lö ibe''e.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 27, 'Ba i''anemaö ifatenge razo wazuri, i''oroi''ö la''ohe högö Yohane.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 28, 'Ba möi da''ö, i''eŵa mbagi ba gurunga ba i''ohe högö ba wiga yaŵa, ibe''e khö nono alawe no mege, ba ibe''e khö ninania ono alawe andrö.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 29, 'Ba me larongo nifahaö Yohane, ba möi ira, lahalö mbotonia ba lako''o.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 30, 'Ba owulo khö Yesu zinenge no, ba la''ombakha''ö khönia fefu nilaura ba famahaöra andrö.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 31, 'Ba imane khöra: Mitabu, ya''ami andrö, ba zi ha ya''ita, ba zi lö niha-niha, ba mi''olombase maifu. Ato sa zangörö-ngörö, lö falukha manga ira.[8]', '["Mar 3:20"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 32, 'Ba moloyo ira,[9] lasaŵa naha si lö niha-niha, ba zi ha ya''ira.', '["Ayati 32–44: Mat 14:13–21; Luk 9:10–17; Yoh 6:1–14"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 33, 'Ba ato zanehe me mofanö ira ba la''ila, wa ya''ira, ba lahurufai, moroi ba mbanua misa fefu, latörö tanö, lahulö ira.', '["Ayati 32–44: Mat 14:13–21; Luk 9:10–17; Yoh 6:1–14"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 34, 'Ba me irugi. Yesu, ba i''ila, ato sibai niha, ba ahakhö dödönia ira, me no hulö mbiri-biri si lö kubalo, ba ibörötaigö ifahaö ira, oya ngawalö.[10]', '["Mat 9:36"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 35, 'Ba me arakha, bongi sa''ae, ba möi khönia nifahaönia, lamane: Tanö si mate naha andre, ba no arakha bongi.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 36, 'Fofanö ira, ena''ö lasaŵa halama ba banua side-ide, si fasui misa, ba wowöli göra.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 37, 'Ba itema lira, imane khöra: Mibe''e göra, ya''ami.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 38, 'Ba imane khöra: Ha wa''oya zi so khömi roti; mi''ae mifaigi.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 39, 'Ba iŵa''ö khöra, mudadao ira, lafa''oli ira, bandru''u.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 40, 'Ba mudadao ira, la''angenoligö ira, otu-otu ba lima-lima wulu.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 41, 'Ba ihalö roti andrö, si lima ba i''a andrö, si dua rozi, ifaöga hörönia ba zorugo, ifahowu''ö roti andrö, ba iboboto, ibe''e khö ndra nifahaö, ena''ö labe''e khöra, ba ba gi''a andrö, si dua rozi göi, idozigö ira.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 42, 'Ba manga ira fefu ba abuso.[11]', '["Faigi 8:8"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 43, 'Ba la''ozaragö gakhökhöla, felendrua kude; akhökhöla gi''a ösa.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 44, 'Ba si manga roti andrö, ba lima ngahönö ndra matua.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 45, 'Ba i''anema''ö iforege wanguma''ö khö ndra nifahaönia we''amöi baowo,[12] ba wowaö-waö miyefo ba Mbetisa''ida, gasa-gasa wamofanönia niha sato.', '["Ayati 45–52: Mat 14:22–33; Yoh 6:15–21"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 46, 'Ba me no i''efa''ö ira, ba möi ia ba hili, mangandrö.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 47, 'Ba me bongi, ba no irugi dalu mbawa owo no mege ba ha ya''ia ba danö.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 48, 'Ba me i''ila erege dödöra woloyo — noa sa zuzumö nangi — ba i''ondrasi ira, me miwo manu, mowaö-waö ia ba guli mbaŵa ba italu''i ira ena''ö.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 49, 'Ba me la''ila, mowaö-waö ia ba guli mbaŵa, ba lawai bekhu, ba mu''ira-ira. Dozi sa la''ila ia ba tokea ira.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 50, 'Ba i''anema''ö muhede khöra, imane khöra : Böi mi''abusi tödö, ya''odo, böi mi''ata''ufi.', '[]', NULL),
  (3394505, 'NT', 'Mareko', 6, 51, 'Ba möi ia baowo khöra, ba tebato nangi: ba oi so wa''atobali dödöra.[13]', '["Faigi 4:39","Faigi 8:17; Mat 16:9"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 52, 'Lö''ö sa aboto ba dödöra ba roti andrö mege; noa sa abe''e dödöra.[14]', '["Faigi 4:39","Faigi 8:17; Mat 16:9"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 53, 'Ba la''ötö,[15] lasaŵa danö, larugi Genezare, manao ira.', '["Ayati 53–56: Mat 14:34–36","Faigi 5:27,28"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 54, 'Ba me no möi ira ba danö, ba i''anema''ö la''ila niha, wa ya''ia.', '["Ayati 53–56: Mat 14:34–36","Faigi 5:27,28"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 55, 'Ba latöröi misa danö ma''asagörö, labörötaigö lafabea khönia zofökhö, ba gasora, ba nirongora so ia.', '["Ayati 53–56: Mat 14:34–36","Faigi 5:27,28"]', NULL),
  (3394505, 'NT', 'Mareko', 6, 56, 'Ba ba zi möi ia yomo ba mbanua side-ide, ba ma ba mbanua sebua, ba ma ba halama, ba latou''ö tou baewali zofökhö andrö ba la''andrö khönia, ena''ö ha bowo-bowo mbarunia tola lababaya; ba ha wa''ato zombambaya, ba döhö wökhö.[16]', '["Ayati 53–56: Mat 14:34–36","Faigi 5:27,28"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 1, 'Ba owulo khönia Farizaio ba sangila amakhoita ösa,[1] si otarai Yeruzalema.', '["Ayati 1–23: Mat 15:1–20","Luk 11:38","Mat 23:25"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 2, 'Ba me la''ila nifahaönia ösa, si manga manö lö mombanö.[2]', '["Ayati 1–23: Mat 15:1–20","Luk 11:38","Mat 23:25"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 3, 'Lö''ö sa manga warizaio, awö niha Yehuda fefu, na lö muforege wanasai tanga, wolo''ö oroisa zatua andrö,', '["Ayati 1–23: Mat 15:1–20","Luk 11:38","Mat 23:25"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 4, 'ba na la''otarai kade, ba lö manga ira, na lö si mondri, ba oya ngawalö tanö bö''ö, nifaema khöra, ni''o''ö, fanaisai mako ba fanasai migö ba fanasai bowoa.[3]', '["Ayati 1–23: Mat 15:1–20","Luk 11:38","Mat 23:25"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 5, 'Ba lasofu khönia farizaio andrö, awö zangila amakhoita andrö, lamane: Hana wa lö latörö lala goroisa zatua andrö ira nifahaömö, hana wa manga manö ira lö mombanö?', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 6, 'Ba imane khöra: Si duhu nifa''ele''ö Yesaya andrö ba khömi, samini tödö andrö, si mane ba zura: "Lafosumange ndra''o bewera niha andre, ba tödöra, ba no aröu khögu.[4]', '["Yes 29:13"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 7, 'Si lö guna wamosumangera ya''o, me nifakhoi dödö niha wamahaöra.', '["Yes 29:13"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 8, 'Oroisa Lowalangi mi''erogö, ba mi''o''ö goroisa niha.', '["Yes 29:13"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 9, 'Ba imane khöra: Si ndruhu wangositengagömi oroisa, ba wolo''ö nifakhoi dödömi.', '["MozII 29:12; 21:17"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 10, 'Noa sa iwa''ö Moze: "Fosumange namau, awö ninau," ba: "Na so zangelifi amania, ba ma inania, ba simate."[5]', '["MozII 29:12; 21:17"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 11, 'Ba ya''ami miŵa''ö: Na so niha sanguma''ö khö namania, ba ma khö ninania: "Korban", ame''ela, sumange, geluahania, zinemau khögu ena''ö,', '["MozII 29:12; 21:17"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 12, 'ba lö''ö sa''ae ömönia khö namania, ba ma khö ninania, miŵa''ö.', '["MozII 29:12; 21:17"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 13, 'Ba tobali lö guna daroma li Lowalangi sa''ae, mibe''e, ba nifakhoimi andrö, nikhoi dödömi; ba oya ngawalö na zi manö milau.', '["MozII 29:12; 21:17"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 14, 'Ba ifuli humede ba niha sato, imane khöra: Mifondrondrongo khögu, dozi ami, ba ya''aboto ba dödömi!', '["HalZin 10:15, 28"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 15, 'Tebai ita''unöi niha hadia ia moroi baero, si möi ba dalunia; da''ö sa zana''unöi niha, si otarai moroi bakha dödö niha.[6]', '["HalZin 10:15, 28"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 16, 'Si so tögi dalinga, ba wamondrongo, ba yamufondrondrongo!', '["HalZin 10:15, 28"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 17, 'Ba me no möi ia yomo, me no iröi niha sato andrö, ba lasofu khönia nifahaönia ba gamaedola andrö no mege.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 18, 'Ba imane khöra: Hadia, lö''ö na göi saboto ba dödömi? Lö mi''ila, wa tebai ita''unöi niha si otarai moroi baero, si möi ba dalunia, me tenga tödönia isaŵa,', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 19, 'me ba dalu möi, ba me aheta ba dögi-tögi, ba nihaögö fefu, hadia ia, ngawalö gö?', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 20, 'Ba imane: Si otarai niha, moroi bakha, da''ö wana''unöi niha.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 21, 'Moroi bakha sa, moroi ba dödö niha, i''otarai era-era si lö sökhi, ba fohorö ba fanagö ba fange''e,', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 22, 'ba fohoröni donga zodonga ba fa''omasi gana''a ba fa''afaito ba falimosa ba femabu-mabu ba fa''afökhö dödö ba fanandraŵaisi niha bö''ö ba fayaŵasa ba fa lö tödö.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 23, 'Fefu zi lö sökhi andrö, ba moroi bakha i''otarai ba ita''unöi niha.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 24, 'Ba maoso ia, iheta ia ba da''ö,[7] isaŵa danö Diro. Ba möi ia yomo ba nomo, ena''ö lö la''ila niha bö''ö, dödönia; ba tebai tobini ia.', '["Ayati 24–30: Mat 15:21–28"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 25, 'I''anema''ö no irongo ia ira alawe, si so ono alawe sobekhu si ra''iö, ba möi yomo da''ö, ituhi danö fönania.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 26, 'Ba Dawa Heleni ndra alawe andrö, ba Ziria Wönikia mbanuara. Ba i''andrö khönia, ena''ö ifofanö mbekhu andrö khö nononia.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 27, 'Ba imane khönia: Akha abuso ndraono ua; lö''ö sa sökhi, na lahalö gö ndraono ba na labe''e ö nasu.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 28, 'Ba itema linia, imane khönia: E, Tua; ba la''a göi asu barö meza gakhökhöla ba ndraono.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 29, 'Ba imane khönia: Ba limö andrö, fuli''ö, no aheta mbekhu andrö khö nonou.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 30, 'Ba mofanö ia khöra, ba no mörö-mörö ba gaso nono, i''ila, ba no aheta mbekhu andrö.', '[]', NULL),
  (3394506, 'NT', 'Mareko', 7, 31, 'Ba mofanö zui Yesu, iröi danö Diro, itörö Zidona, isaŵa, mbaŵa Galilaia, itörö danö zi fulu banua.[8]', '["Mat 15:29 bt."]', NULL),
  (3394506, 'NT', 'Mareko', 7, 32, 'Ba la''ohe khönia zafiso, si no abe''e lela, la''andrö khönia, ena''ö itufa tanga.', '["Mat 15:29 bt."]', NULL),
  (3394506, 'NT', 'Mareko', 7, 33, 'Ba i''ohe ba zi lö niha ba ibe''e duturunia ba dalinga, mangendrilo ia ba ibabaya lela.[9]', '["Faigi 8:23","Faigi 6:41; Yoh 17:1"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 34, 'Ifaöga hörönia miyaŵa ba zorugo, ihasugö ia ba imane khönia: Efata! yateboka''ö geluhania.[10]', '["Faigi 8:23","Faigi 6:41; Yoh 17:1"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 35, 'Ba teboka dögi dalingania, ba i''anema''ö aefa wesu lelania andrö, ba atulö wehedenia.', '["MozI 1:31"]', NULL),
  (3394506, 'NT', 'Mareko', 7, 36, 'Ba iwa''ö khöra, böi la''ombakha''ö, gofu ha ökhö; ba ihötöi fanenaŵa ya''ira, ba lahötöi fangombakha.', '["MozI 1:31"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394506, 'NT', 'Mareko', 7, 37, 'Ba tobali sibai dödöra ba lamane: Oi nihaogö manö wolaunia, safiso ibali''ö samondrongo li niha, ba si lö hede, ba ibali''ö sihede.[11]', '["MozI 1:31"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 1, 'Me luo da''ö,[1] ba ato sibai zui niha, ba ma''ifu lö öra, ba humede Yesu ba nifahaönia, imane khöra:', '["Ayati 1–10: Mat 15:32–39"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 2, 'Ahakhö dödögu niha andrö; noa sa''ae tölu bongi lö si tebulö ira khögu, ba ma''ifu lö öra.', '["Ayati 1–10: Mat 15:32–39"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 3, 'Ba na ufofanö ira ba khöra, lö manga, ba mate ira olofo ba lala; banua saröu na i ösa.', '["Ayati 1–10: Mat 15:32–39"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 4, 'Ba latema linia nifahaönia, lamane: He moroi tahalö gö, ba wangabusoi''ö niha andrö, ba da''e, ba danö si mate?', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 5, 'Ba isofu khöra: Hauga khömi roti ? Ba lamane: Fitu.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 6, 'Ba iŵa''ö ba niha, mudadao ira ba danö.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 7, 'Ba so khöra gi''a ma''ifu, ba ifahowu''ö ba ifaosa göi.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 8, 'Ba manga ira, ba abuso, ba la''ozaragö zi töra, akhökhöla, fitu kude.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 9, 'Ba so öfa ngahönö ira; ba ifofanö ira.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 10, 'Ba idölö ia baowo, awö nifahaönia ba irugi danö Dalamanuta.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 11, 'Ba so moroi yomo warizaio,[2] labörötaigö fahuhuo khönia, la''andrö khönia dandra, moroi yaŵa ba mbanua, ba wanandraigö ya''ia.[3]', '["Ayati 11–21: Mat 16:1–12","Luk 11:16,29"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 12, 'Ba ihasugö ia, tödönia, ba imane: Hana wa la''andrö dandra niha andrö? Si ndruhu niŵa''ögu khömi, lö''ö manö labe''e dandra ba niha andrö.[4]', '["Yoh 11:33"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 13, 'Ba iröi ira, ifuli ia baowo, isaŵa si yefo.', '["Yoh 11:33"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 14, 'Ba no olifu ira wolohe roti; lö baowo khöra, ha sambua roti.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 15, 'Ba ifangelama ira, imane: Mifaigi, böi mibabaya danömö roti andrö ba warizaio, awö danömö roti khö Herode andrö.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 16, 'Ba fahuhuo ira, lamane: Me lö khöda roti.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 17, 'Ba i''ila ba imane khöra: Hadia wa fahuhuo ami, wa lö roti khömi? Hadia, lö''ö na mi''ila hadia ia, ba lö''ö na saboto ba dödömi? Lö mamalö-malö wa''abe''e dödömi? [5]', '["Faigi 6:52","Faigi 6:41","Faigi 8:5"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 18, 'Mohörö ami, ba lö mi''ila hadia ia, ba no so dögi dalingami, ba lö mirongo hadia ia, ba lö mi''era-era tödömi.', '["Faigi 6:52","Faigi 6:41","Faigi 8:5"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 19, 'Me uboboto roti no si lima, ba zi lima ngahönö niha, ba ha uga kude ni''ozaragömi akhökhöla? Lamane khönia: Felendrua.[6]', '["Faigi 6:52","Faigi 6:41","Faigi 8:5"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 20, 'Ba ba zi fitu no, ba zi öfa ngahönö niha, ba ha uga kude ni''ozaragömi akhökhöla? Ba lamane: Fitu.[7]', '["Faigi 6:52","Faigi 6:41","Faigi 8:5"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 21, 'Ba imane khöra: Hadia, lö''ö na aboto ba dödömi?', '["Faigi 6:52","Faigi 6:41","Faigi 8:5"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 22, 'Ba larugi Mbetisa''ida. Ba la''ohe khönia zau''a, la''andrö khönia, ena''ö ibabaya.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 23, 'Ba i''ohe danga zau''a andrö, ifasao baero mbanua, idiloi hörönia, itufa ia tanga, isofu khönia, na so ni''ilania.[8]', '["Faigi 7:33; Yoh 9:6"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 24, 'Ba ifaöga hörönia, ba imane: U''ila niha; möwaö-waö ira, u''ila sa, hulö döla geu.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 25, 'Ba ifuli itufa hörönia tanga ba itöngö ba te''azökhi ia, ba atöla wamaiginia fefu hadia ia.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 26, 'Ba ifofanö ia ba khöra, imane: Böi ae miyomo ba mbanua andre.[9]', '["Mat 9:30"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 27, 'Ba mofanö Yesu,[10] awö nifahaönia, lasaŵa mbanua misa, sahatö ba Kaizaria Wilifo.', '["Ayati 27–30 : Mat 16, 13–20. Luk 9. 18–21"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 28, 'Ba lamane khönia: Laŵa''ö Yohane, samayagö idanö, ndra''ugö, ba so zanguma''ö Eliya ba so zanguma''ö fasamösa zama''ele''ö andrö.[11]', '["Faigi 6:15"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 29, 'Ba isofu khöra: Ba ya''ami, ha miŵa''ö, ha niha ndra''o?', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 30, 'Ba itenaŵa ira, fa böi la''ombakha''ö ia ba niha bö''ö.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 31, 'Ba ibörötaigö ibokai khöra,[13] wa lö tola lö oya dania itaha famakao Ono Niha, latibo''ö dania ia satua andrö ba sangila amakhoita; labunu ia ba na no irugi tölu ngaluo, ba ifuli auri.[14]', '["Ayati 31–38: Mat 16:21–27; Luk 9:22–26","Faigi 10:32 btn"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 32, 'Lö''ö sa aiŵö ia wangombakha.', '["Ayati 31–38: Mat 16:21–27; Luk 9:22–26","Faigi 10:32 btn"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 33, 'Ba ibali''ö ia, ba me i''ila nifahaönia, ba itenaŵa Wetero andrö, imane: Ae furigu, Satana! Lö''ö sa ö''era-era hadia khö Lowalangi, ha hadia ba niha.', '[]', NULL),
  (3394507, 'NT', 'Mareko', 8, 34, 'Ba humede ia ba niha sato,[15] awö ba nifahaönia, imane khöra: Na so zedöna molo''ö ya''o, ba yamu''ositengagö ia, yamulu''i röfania ba yamu''o''ö ndra''o.[16]', '["Ayati 31–38: Mat 16:21–27; Luk 9:22–26","Mat 10:38 btn","Mat 10:33; Luk 9:26"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 35, 'Na so sa zedöna manganau''ö nosonia, da''ö zaetu noso, ba na so zaetu noso, na börö ndra''o ba turia somuso dödö andrö, ba da''ö zanganau''ö.', '["Ayati 31–38: Mat 16:21–27; Luk 9:22–26","Mat 10:38 btn","Mat 10:33; Luk 9:26"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 36, 'Hadia sa guna ba niha, na isöndra ena''ö harenia fefu hadia ia zi so ba guli danö, ba na te''ala ia nosonia?', '["Ayati 31–38: Mat 16:21–27; Luk 9:22–26","Mat 10:38 btn","Mat 10:33; Luk 9:26"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 37, 'Hadia sa ena''ö, nibe''e niha höli nosonia ?', '["Ayati 31–38: Mat 16:21–27; Luk 9:22–26","Mat 10:38 btn","Mat 10:33; Luk 9:26"]', NULL),
  (3394507, 'NT', 'Mareko', 8, 38, 'Na so sa zaila ba khögu andre, ba ba daroma ligu, ba niha sohorö-horö andre, solalö, da''ö göi zaila dania Nono Niha, na so ia, na so khönia lakhömi Nama andrö, ba na awönia mala''ika ni''amoni''ö andrö.[17]', '["Ayati 31–38: Mat 16:21–27; Luk 9:22–26","Mat 10:38 btn","Mat 10:33; Luk 9:26"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 1, 'Ba imane khöra: Si ndruhu niŵa''ögu khömi, so ösa ba zi so ba da''e, si lö manandra fa''amate dania, irege no la''ila abölö mbanua Lowalangi andrö.[1]', '["Mat 16:28; Luk 9:27"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 2, 'Ba önö bongi aefa da''ö,[2] ba i''ohe awönia Yesu Wetero ba Yakobo ba Yohane, i''ohe misa ira ba hili salaŵa, ba zi ha ya''ira manö; ba tobali ia fönara;', '["Ayati 2–11: Mat 17:1–13; Luk 9:28–36","Fam 1:14,17"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 3, 'ba nukhania, ba tobali humaga, afusi sibai, tebai si manö wa''afusi nukha ba zamabago ba guli danö.[3]', '["Ayati 2–11: Mat 17:1–13; Luk 9:28–36","Fam 1:14,17"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 4, 'Ba oroma khöra Geliya ba Moze fahuhuo ira khö Yesu.', '["Ayati 2–11: Mat 17:1–13; Luk 9:28–36","Fam 1:14,17"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 5, 'Ba humede Wetero, imane khö Yesu: He samahaö, ba da''e zi sökhi nahada; ba damafazökhi nose, tölu, sambua khöu, ba sambua khö Moze ba sambua khö Geliya.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 6, 'Lö''ö sa i''ila watahögö niŵa''önia; noa sa a''oi so wa''atobali dödöra.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 7, 'Ba so moroi sa lawuo si lumö''ö ya''ira. Ba so zihede moroi ba lawuo andrö, imane: Onogu omasiö da''ö, mifondrondrongo linia![4]', '["FetII 1:16,17; Yoh 12:28"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 8, 'Ba me lafakhölö ira, ba i''ozumagö lö''ö sa''ae oroma khöra niha, ha Yesu manö nawöra.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 9, 'Ba me latueli hili, ba iŵa''ö khöra, böi la''ombakha''ö, gofu ha khö, ni''ilara, ha dania, na no maoso Nono Niha moroi ba ngai zi mate.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 10, 'Ba lö olifu ira niŵa''önia andrö, ba fahuhuo ira, hadia ia wemaoso andrö, moroi ba ngai zi mate.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 11, 'Ba lasofu khönia, lamane: Hadia wa laŵa''ö farizaio ba sangila amakhoita, lö tola lö möi Geliya ua?', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 12, 'Ba imane khöra: Ya''ia, so Geliya ua ba i''a''azökhi fefu hadia ia; ba he wisa ba zura ba khö Nono Niha andrö? Oya dania itaha famakao ba latibo''ö.', '["Fam 11:13 b.t."]', NULL),
  (3394508, 'NT', 'Mareko', 9, 13, 'Ba uŵa''ö khömi, noa göi: möi Geliya, ba no lalau khönia hadia zomasi ira, no itörö zi so ba zura ba khönia andrö.[5]', '["Fam 11:13 b.t."]', NULL),
  (3394508, 'NT', 'Mareko', 9, 14, 'Ba me larugi nifahaö,[6] ba ato niha samasui ya''ira, la''ila, awö zangila amakhoita, si fahuhuo khöra.', '["Ayati 14–29: Mat 17:14–21; Luk 9:37–43"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 15, 'Ba i''anema''ö tobali dödö niha sato andrö fefu, me la''ila ia ba lahurufai ia, wangowai ya''ia.', '["Ayati 14–29: Mat 17:14–21; Luk 9:37–43"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 16, 'Ba isofu khöra: Hadia huhuomi khöra?', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 17, 'Ba itema linia si samösa ba zato andrö, imane: He samahaö, no u''ohe khöu nonogu, si so bekhu si lö hede.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 18, 'Ba na ira''u ia, ba idödöni ba fawukhö gilo ba ifatangi mboha ba ariri manö ia. Ba no uŵa''ö ba nifahaömö, ena''ö lafofanö, ba tebai.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 19, 'Ba itema lira, imane: Alai ndra''o ami, niha si lö mamati! Ha wa''ara tö na sodo khömi? Ha wa''ara utaha ba khömi? Mi''ohe ia khögu.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 20, 'Ba la''ohe khönia.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 21, 'Ba isofu khö namania Yesu: Ha wa''ara sa''ae göna-göna ia si manö?', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 22, 'Ba imane: I''otarai iraono ia. No asese itibo''ö ba galitö göi ba ba nidanö, ba wamunu ya''ia; ba na ö''ila hadia ia, ba hakhösi tödö ndra''aga, tologa.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 23, 'Ba imane khönia Yesu: Ba niŵa''öu andrö: "Na ö''ila", — fefu hadia ia i''ila ilau samati.[7]', '["KorI 12:10"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 24, 'Ba i''anema''ö mu''ao nama nono andrö, imane: Mamati ndra''o, tolodo ba wa ambö famati andrö![8]', '["Luk 17:5,6"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 25, 'Ba me i''ila Yesu lahurufai niha sato andrö, ba itenaŵa mbekhu si ra''iö andrö, imane khönia: Uŵa''ö khöu, bekhu si lö hede, safiso, heta''ögö khönia ba böi sa''ae fuli''ö khönia.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 26, 'Ba iheta ia, mu''ao-ao ia ba idödöni sibai nösinia. Ba tobali hulö zi mate, ba ato zanguma''ö: No mate ia.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 27, 'Ba ira''u danga Yesu, ifazizio, ba maoso ia.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 28, 'Ba me möi ia yomo, ba lasofu khönia nifahaönia, ba zi ha ya''ira: Hana wa tebai ndra''aga, ba wamofanö ya''ia?', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 29, 'Ba imane khöra: Lö famofanö zi sambalö andrö, na tenga fangandrö.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 30, 'Ba laheta ira ba da''ö,[9] latörö Galilaia, ba lö omasi ia, i''ila ira niha bö''ö.', '["Ayati 30–32: Mat 17:22,23; Luk 9:43–45","Faigi 8:31; 10:32 b.t.","Luk 18:34"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 31, 'Ifahaö sa nifahaönia, imane khöra: Tetou''ö dania Nono Niha ba danga niha, ba labunu, ba na no labunu, ba tölu ngaluo, ba ifuli auri.[10]', '["Ayati 30–32: Mat 17:22,23; Luk 9:43–45","Faigi 8:31; 10:32 b.t.","Luk 18:34"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 32, 'Ba lö aboto ba dödöra niŵa''önia andrö, ba ata''u ira, wanofu khönia.[11]', '["Ayati 30–32: Mat 17:22,23; Luk 9:43–45","Faigi 8:31; 10:32 b.t.","Luk 18:34"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 33, 'Ba larugi Gafanauma,[12] ba me no möi ia yomo, ba isofu khöra: Hadia mege huhuomi ba lala?', '["Ayati 33–37: Mat 18:1–5; Luk 9:46–48"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 34, 'Ba lö hede-hedera; noa sa mege fahuhuo ira ba lala, ha niha zebuara maö.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 35, 'Ba mudadao ia ba humede ia ba zi felendrua ba imane khöra: Na so zomasi föna ia, ba yamöi furi sibai, yamöi enoni nawönia fefu.[13]', '["Faigi 10:43; Mat 20:26 b.t.","Faigi 10:16","Yoh 13:20"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 36, 'Ba ifa''aso tanö fönara ndraono, sambua, italagui, ba imane khöra:[14]', '["Faigi 10:43; Mat 20:26 b.t.","Faigi 10:16","Yoh 13:20"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 37, 'Na so zama''amöi yomo khönia ono si mane da''e, sambua, na börö döigu, ba ya''o nifa''amöinia yomo. Ba na so zama''amöi yomo ya''o, ba tenga ya''o nifa''amöinia yomo, samatenge ya''o andrö nifa''amöinia.[15]', '["Faigi 10:43; Mat 20:26 b.t.","Faigi 10:16","Yoh 13:20"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 38, 'Imane khönia Yohane:[16] He samahaö, no ma''ila zamösa, sanötöi töimö, wamofanö bekhu, si lö molo''ö ya''ita, ba no matenaŵa ia, me lö i''o''ö ita.', '["Ayati 38–40: Luk 9:49,50"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 39, 'Ba imane Yesu: Böi mitenaŵa ia; tebai sa ilau hadia ia dandra, niha, ba döigu, ba i''anema''ö zui i''o''aya ndra''o.', '["Mat 12:30"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 40, 'Ha niha sa zi lö fa''udu khöda, ba no awöda.[17]', '["Mat 12:30"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 41, 'Ha niha sa zame''e nibadu khömi zamba mako idanö, ba döigu andrö, me khö Keriso ami, ba si ndruhu niŵa''ögu khömi, lö aekhu luonia.[18]', '["Mat 10:42"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 42, 'Ba na so zangalani side-ide andrö samati,[19] samösa, ba ebua mohare ia mena''ö, na labe''e ba mbaginia gara sebua ba na latibo''ö ia ba nasi.[20]', '["Ayati 42–48; Mat 18:6–9","Luk 17:1,2"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 43, 'Ba na i''alani ndra''ugö tangau, ba tema eŵa ia; mohare ndra''ugö, na ha tambai dangau, ba ökhamö wa''auri, moroi dua dangau, ba möi''ö ba narako, ba galitö andrö, si lö mate-mate', '["Yes 66:24"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 44, 'ba zi lö mate-mate gukuö andrö khöra, awö galitö andrö.[21]', '["Yes 66:24"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 45, 'Ba na i''alani ndra''ugö aheu, ba tema eŵa ia, mohare ndra''ugö, na sakela-kela ndra''ugö, ba ökhamö wa''auri, moroi dua gaheu, ba tetibo''ö ba narako,', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 46, 'ba zi lö mate-mate gukuö andrö khöra, awö galitö andrö.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 47, 'Ba na i''alani ndra''ugö höröu, ba tema koe ia, mohare ndra''ugö, na bakole ndra''ugö, ba ökhamö mbanua Lowalangi, moroi dombua höröu, ba tetibo''ö ba narako,', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 48, 'ba zi lö mate-mate gukuö andrö khöra, awö galitö andrö.', '[]', NULL),
  (3394508, 'NT', 'Mareko', 9, 49, 'Ni''asioni alitö sa dania ira fefu.', '["Mat 5:13; Luk 14:34; Kol 4:6; Rom 12:18; Yob 12:14"]', NULL),
  (3394508, 'NT', 'Mareko', 9, 50, 'Si sökhi nasio andrö; ba na taya wa''asi-asi nasio andrö, ba ha mibe''e fangasi-ngasinia? Böi zi lö asio khömi ba dödömi, ba böi fa''udu-udu ami.[22]', '["Mat 5:13; Luk 14:34; Kol 4:6; Rom 12:18; Yob 12:14"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 1, 'Ba iheta ia ba da''ö,[1] isaŵa danö Yudaia ba tanö yefo Yoridano, ba ato zui zowulo khönia niha, ba ifuli ifahaö ira, no to''ölö ia ba zi manö.[2]', '["Ayati 1–12: Mat 19:1–9","Yoh 10, 40","Mat 19:3"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 2, 'Ba la''ondrasi ia farizaio, lasofu khönia, na tola itibo''ö ngambatönia niha, latandraigö ia.[3]', '["Ayati 1–12: Mat 19:1–9","Yoh 10, 40","Mat 19:3"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 3, 'Ba itema lira, imane khöra: Hadia goroisa Moze khömi?', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 4, 'Lamane khönia: No itehe Moze, lafazökhi zura, wangefa''ö, ba latibo''ö ia.[4]', '["MozV 24:1"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 5, 'Ba imane khöra Yesu: Börö wa''abe''e dödömi, wa isura khömi goroisa andrö,', '["Efes 5:30–33"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 6, 'ba moroi ba mböröta nifazökhi Lowalangi, ba ira matua ba ira alawe wamazökhinia ya''ira.', '["Efes 5:30–33"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 7, '"Andrö iröi namania, awö ninania, niha,[5]', '["Efes 5:30–33"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 8, 'ba ha sambua boto dania zi darua andrö"; tobali tenga sa''ae dombua, ha sambua boto.', '["Efes 5:30–33"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 9, 'Ba hadia ni''orudugö Lowalangi sa''ae, ba böi yamufabali niha.', '["Efes 5:30–33"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 10, 'Ba me no möi ia yomo, ba lafuli lasofu khönia da''ö nifahaönia.', '["Efes 5:30–33"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 11, 'Ba imane khöra: Na so zanibo ngambatönia, ba na ihalö danö bö''ö, ba sohorö da''ö, ba khönia andrö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394509, 'NT', 'Mareko', 10, 12, 'Ba na ya''ia zanibo ira matua, ba na möi ia donga danö bö''ö, ba sohorö, ia.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 13, 'Ba la''ohe khönia ndraono,[6] ena''ö ibabaya; ba lategu zolohe andrö nifahaönia.', '["Ayati 13–16: Mat 19:13–15; Luk 18:15–17"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 14, 'Ba me i''ila Yesu, ba mofönu ia, ba imane khöra: Mifa''amöi khögu ndraono andrö, böi mitenaŵa ira, ba zi manö sa mbanua Lowalangi andrö.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 15, 'Sindruhu niŵa''ögu khömi, si lö manema banua Lowalangi andrö si mane iraono, ba lö''ö manö lalania ba da''ö.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 16, 'Ba italagui ira, ifahowu''ö, itufa högöra tanga.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 17, 'Ba me möi ia tou baewali,[7] ba i''ondrasi ia niha, ituhi danö fönania, isofu khönia, imane: He samahaö si sökhi, he uwisa, ena''ö utema wa''auri si lö aetu andrö?', '["Ayati 17–22: Mat 19:16–23; Luk 18:18–23"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 18, 'Ba imane khönia Yesu: Hana wa öŵa''ö si sökhi ndra''o? Lö si sökhi, baero zi ha samösa andrö, Lowalangi.', '["Rom 13:9"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 19, 'Oroisa andrö, ba no ö''ila: "Böi ohorö! böi ange''e! böi anagö! böi böbögö khö nawöu zi lö duhu, fosumange namau, awö ninau!"[8]', '["Rom 13:9"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 20, 'Ba imane khönia: No ahori u''o''ö da''ö samahaö, i''otarai iraono ndra''o.[9]', '["Mat 20:38; Luk 16:9"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 21, 'Ba inehegö ia Yesu, i''omasi''ö, ba imane: Sambalö zi lö''ö khöu. Ae amawa hadia zi so khöu ba be''e ba zinumana, ba so khöu girö-girö ba zorugo, ba tabu, o''ö ndra''o.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 22, 'Ba lö sökhi-sökhi dödönia ba niŵa''ö Yesu andrö, ba mofanö ia abu dödönia; me no sebua ana''a ia.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 23, 'Ba ifakhölö ia Yesu[10] ba imane ba nifahaönia: Ha lö afökhö lala zo''ana''a ba mbanua Lowalangi!', '["Ayati 23–31: Mat 19:23–30; Luk 18:24–30"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 24, 'Ba tobali dödö nifahaö ba niŵa''önia andrö.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 25, 'Aoha na i, itörö dögi walölöŵa kudo, moroi ikhamö mbanua Lowalangi andrö so''ana''a.', '["Amaed 11:28"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 26, 'Ba tedou wa''atobali dödöra, ba faoma lamane khö nawöra: Ba ha niha zanöndra fa''auri?', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 27, 'Ba inehegö ira Yesu, ba imane: Ba niha, ba tebai, ba ba Lowalangi, ba tola; fefu hadia ia sa, ba molala ba Lowalangi.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 28, 'Ba ibörötaigö Fetero, imane khönia: Faigi, ya''aga andre, no maröi manö fefu hadia ia, ba no ma''o''ö ndra''ugö.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 29, 'Imane Yesu: Si ndruhu niwa''ögu khömi, lö sondröi omo ba ma talifusö matua, ba ma talifusö alawe, ba ma ina, ba ma ama, ba ma ono, ba ma benua na börö ndra''o ba turia somuso dödö andrö,', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 30, 'si lö manema mangawuli, otu winaeta, iada''e ba götö andre, omo ba talifusö matua ba talifusö alawe ba ina ba ono ba benua, awö wolohi andrö, ba ba mbanua furi, ba fa''auri si lö aetu.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 31, 'Ba ato zi so furi dania zi so föna iada''e, ba si manö zi so furi iada''e, tobali si so föna dania.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 32, 'Ba ba lala so ira,[12] we''amöi misi yaŵa ba Yeruzalema, ba itari-tari Yesu, ba no tobali dödöra ba ata''u dödö zolo''ö moroi furi. Ba ifuli i''ohe khönia zi felendrua, ibörötaigö i''ombakha''ö khöra hadia zi göna ia dania,[13] imane:', '["Ayati 32–34: Mat 20:17–19; Luk 18:31–34","Faigi 9:31; Yoh 11:7–8"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 33, 'Hiza, möi ita misi yaŵa ba Yeruzalema, ba tebe''e ba danga gere sebua ba ba danga zangila amakhoita andrö Nono Niha, ba la''etu''ö hukunia, huku famunu, ba latou''ö ba danga niha baero ia,', '["Ayati 32–34: Mat 20:17–19; Luk 18:31–34","Faigi 9:31; Yoh 11:7–8"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 34, 'ba la''o''aya dania ia ba ladidiloi ba laböbözi ba labunu, ba tölu ngaluo, ba ifuli auri.', '["Ayati 32–34: Mat 20:17–19; Luk 18:31–34","Faigi 9:31; Yoh 11:7–8"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 35, 'Ba la''ondrasi ia ira Yakobo Yohane,[14] ono Zebedaio andrö, lamane khönia: He samahaö, omasi ndra''aga, na ö''o''ö khöma ni''andröma khöu.', '["Ayati 35–45: Mat 20:20–28"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 36, 'Ba imane khöra: Hadia ni''andrömi khögu?', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 37, 'Ba lamane khönia: Tehe khöma, ena''ö samösa ba gambölöu ba samösa ba gaberau nahama ba lakhömiu dania.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 38, 'Ba imane khöra Yesu: Lö mi''ila hadia ni''andrömi. Hadia, tola mibadu nösi mako andrö, nibadugu, ba tola labayagö khömi nibayagö khögu?[15]', '["Luk 12:50"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 39, 'Ba lamane khönia: Tola.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 40, 'ba fanehe fedadao andrö, ba tenga khögu; da''ö zidadao ba da''ö, ba zi no muhonogöi fedadao andrö.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 41, 'Ba me larongo da''ö si dafulu, ba labörötaigö mukökö-kökö ba khö ndra Yakobo Yohane.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 42, 'Ba humede khöra Yesu, imane: Mi''ila, lafatörö mbanuara si no salaŵa ba niha, wanguma''ö niha, ba labe''e barö mbawara niha sebuara.', '["Faigi 9:35"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 43, 'Ba böi si manö ba khömi; ha niha zomasi ebua ia ba khömi, ba yamöi enonimi.[16]', '["Faigi 9:35"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 44, 'Ba ha niha ba khömi zomasi föna ia, ba yamöi sawuyu zato.', '["Faigi 9:35"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 45, 'Ono Niha sa göi, tenga si möi mangoni, si möi enoni, si möi mame''e nosonia höli zato.', '["Faigi 9:35"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 46, 'Ba larugi Yerikho.[17] Ba me mofanö ia ba Yerikho, awö nifahaönia ba awö zato, ba no dumadao ba ngai lala nono Dimaio, Batimaio, niha sau''a, sangandrö-ngandrö balazo.', '["Ayati 46–52: Mat 20:29–34; Luk 18:35–43"]', NULL),
  (3394509, 'NT', 'Mareko', 10, 47, 'Ba me irongo so Yesu, banua Nazareta, ba ibörötaigö mu''ao, imane: He ma''uwu Dawido, Yesu, hakhösi tödö ndra''o!', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 48, 'Ba ato zanegu ya''ia, ena''ö lö muhede ia. Ba iforege we''ao: He ma''uwu Dawido, hakhösi tödö ndra''o!', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 49, 'Ba ibadugö ia Yesu, imane: Mihede khönia.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 50, 'Ba itibo''ö tou mbarunia, ifaröga ia, i''ondrasi Yesu.', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 51, 'Ba muhede khönia Yesu, imane: Hadia zomasi''ö, he uwisa khöu?', '[]', NULL),
  (3394509, 'NT', 'Mareko', 10, 52, 'Ba imane khönia Yesu: Fuli''ö, no i''orifi''ö famatimö andrö.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 1, 'Ba me no ahatö ira ba Yeruzalema[1] ba ba Mbetania ba gahe hili wanikha andrö, ba ifatenge nifahaönia, darua, imane khöra:', '["Ayati 1–10: Mat 21:1–11; Luk 19:28–38; Yoh 12:12–18"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 2, 'Mi''ae ba ba mbanua side-ide andrö, fönami, ba na mirugi, ba i''anema''ö mi''ila nono galide nifesu, si lö irai la''okudo niha; mitoto''ö wesunia ba mi''ohe ia.', '["Ayati 1–10: Mat 21:1–11; Luk 19:28–38; Yoh 12:12–18"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 3, 'Ba na so zanguma''ö khömi: Hana wa mimanö? ba mimane: Moguna khö Dua, ba i''anema''ö ifa''ohe''ö mangawuli ba da''e.', '["Ayati 1–10: Mat 21:1–11; Luk 19:28–38; Yoh 12:12–18"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 4, 'Ba möi ira, ba hiza nono galide no mege, nifesu, ba zinga mbawandruhö, tou baewali, ba latoto''ö wesu.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 5, 'Ba lamane khöra ösa, si so ba da''ö: Hadia khömi da''ö, wa mitoto''ö wesu nono galide andrö?', '["SamII 7:12–16"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 6, 'Ba la''ombakha''ö khöra hadia niŵa''ö Yesu; awena latehe.', '["SamII 7:12–16"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 7, 'Ba la''ohe khö Yesu nono galide andrö, labe''e ba hulunia nukhara, ba i''okudo.', '["SamII 7:12–16"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 8, 'Ba ato zamologö ba lala nukhara, ba so, ba bulu ndru''u, ni''eŵara ba mbenua.', '["SamII 7:12–16"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 9, 'Ba sowaö-waö ba solo''ö moroi furi, ba mu''ao, lamane: Hozana, nifahowu''ö zi so andrö ba döi Zo''aya,', '["SamII 7:12–16"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 10, 'nifahowu''ö wa''asalaŵa Duada Dawido andrö, sangondrasi ya''ita; hozana ha zalaŵa yaŵa![2]', '["SamII 7:12–16"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 11, 'Ba möi ia miyomo ba Yeruzalema,[3] ba gosali. Ba me no ifaigi fefu hadia ia, ba me arakha bongi, ba möi ia baero, isaŵa Mbetania, awö zi felendrua.', '["Ayati 11–14: Mat 21:17–19"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 12, 'Ba mahemolu ö, me la''oroi Mbetania, ba olofo ia.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 13, 'Ba i''ila marafala tanö sa, si so bulu, ba möi ia, ma isöndra hadia ia mbua, ba me irugi, ba lö isöndra hadia ia, ha sambalö bulu, tenga sa baŵa marafala.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 14, 'Ba humede ia, imane khönia: Böi sa''ae yamu''a mbuau niha, irugi zi lö aetu. Ba larongo nifahaönia.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 15, 'Ba larugi Yeruzalema.[4]', '["Ayati 15–19: Mat 21: 12–13,17; Luk 19:45–48"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 16, 'ba lö itehe lafatörö ba gosali nahia hadia ia.', '["Yes 56:6 btn.; Yer 7:11"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 17, 'Ba ifahaö ira, imane khöra: Tenga no so ba zura: "Omo wangandrö döi nomogu ba niha fefu?" Ba ya''ami, ba no mibali''ö tögi narö hili naha zorabu.[5]', '["Yes 56:6 btn.; Yer 7:11"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 18, 'Ba larongo ere sebua, awö zangila amakhoita andrö, ba la''alui wamunu ya''ia; ata''u sa ira ia; a''oisa no tobali dödö niha sato ba wamahaönia.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 19, 'Ba na bongi, ba möi ia baero mbanua.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 20, 'Ba me latörö,[6] si hulö wongi, ba la''ila, no mate marafala no mege, i''otarai ŵa''a tou.', '["Ayati 20–24: Mat 21:19–22"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 21, 'Ba itörö tödö Wetero ba imane khönia: He samahaö! faigi marafala andrö, ni''elifiu, no mate.[7]', '["Mat 24:32"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 22, 'Ba itema lira Yesu, imane khöra: Mi''amati ba Lowalangi.[8]', '["Yoh 14:21","Fam 11:3 btn; KorI 15:2","Yoh 15:7,16,23; YohI 5:14","Mat 5:23 btn; Mat 6:14","Mat 18:35"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 23, 'Si ndruhu niŵa''ögu khömi, na so zanguma''ö ba hili andrö: Beta''ögö ba tibo''ögö ba nasi, ba na lö mangiwa bakha dödönia, na faduhu dödönia itörö niŵa''önia, ba itörö khönia.[9]', '["Yoh 14:21","Fam 11:3 btn; KorI 15:2","Yoh 15:7,16,23; YohI 5:14","Mat 5:23 btn; Mat 6:14","Mat 18:35"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 24, 'Andrö uŵa''ö khömi: Fefu hadia ia ni''andrömi, na mangandrö, mifati wa mitema, ba so ia khömi.[10]', '["Yoh 14:21","Fam 11:3 btn; KorI 15:2","Yoh 15:7,16,23; YohI 5:14","Mat 5:23 btn; Mat 6:14","Mat 18:35"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 25, 'Ba na awena mangandrö ami, ba mi''efa''ö, na so hadia ia zala niha, ha niha ia, khömi, ena''ö Amami andrö ba zorugo göi, ibe''e aefa khömi lalömi.[11]', '["Yoh 14:21","Fam 11:3 btn; KorI 15:2","Yoh 15:7,16,23; YohI 5:14","Mat 5:23 btn; Mat 6:14","Mat 18:35"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 26, 'Ba na lö mi''efa''ö zala, ba lö''ö göi i''efa''ö lalömi Amami andrö, si so ba zorugo.[12]', '["Yoh 14:21","Fam 11:3 btn; KorI 15:2","Yoh 15:7,16,23; YohI 5:14","Mat 5:23 btn; Mat 6:14","Mat 18:35"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 27, 'Ba larugi zui Yeruzalema.[13] Ba me mowaö-waö ia ba gosali, ba la''ondrasi ia ere sebua ba sangila amakhoita andrö ba satua mbanua andrö.', '["Ayati 27–38; Mat 21:23–27; Luk 20:1–8"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 28, 'Ba lamane khönia: Hadia wa tola ölau da''ö? Ba ha niha zanehe khöu, wolau ya''ia?[14]', '["Yoh 2:18; 11:57"]', NULL),
  (3394510, 'NT', 'Mareko', 11, 29, 'Ba imane khöra Yesu: So nisofugu khömi zambalö, ba mi''ombakha''ö khögu, awena dania u''ombakha''ö khömi, hadia, wa tola ulau da''ö.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 30, 'Famayagö idanö andrö, khö Yohane, hadia, moroi ba zorugo ia, ma moroi ba niha? Mi''ombakha''ö khögu.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 31, 'Ba la''era-era tödöra, lamane: Na taŵa''ö: Moroi ba zorugo, ba imane dania khöda: Ba hana wa lö mamati ami no khönia?', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 32, 'Ba na taŵa''ö: Moroi ba niha ba ata''u ita niha sato, me ba dödöra fefu si ndruhu zama''ele''ö Yohane andrö.', '[]', NULL),
  (3394510, 'NT', 'Mareko', 11, 33, 'Ba latema li Yesu lamane: Lö ma''ila.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 1, 'Ba ibörötaigö molau amaedola khöra,[1] imane:', '["Ayati 1–12: Mat 21:35–40; Luk 20, 9–10"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 2, 'Ba ifatenge zawuyu ba zohalöŵö andrö, me no inötö, ena''ö ihalö mbua nagu, ba kabu andrö, ba zohalöŵö andrö.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 3, 'Ba lahalö da''ö, laböbözi ba lafatenge manö mangawuli, lö labe''e.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 4, 'Ba ifuli ifatenge khöra zawuyu bö''ö; ba lafesokho högö da''ö ba la''o''aya ia.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 5, 'Ba ifatenge danö bö''ö, ba latema labunu da''ö. Ba ato na danö bö''ö, ba so labözi-bözi, ba so, ba labunu.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 6, 'Ba so na khönia nono, ha samösa, ono omasiö, da''ö nifatengenia khöra sa furia, imane: Ata''u ira nonogu.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 7, 'Ba sohalöŵö no mege, ba faoma lamane khö nawöra: Sanema ondröita da''ö; talabu, tabunu ia, ba khöda gondröita andrö.[3]', '["Luk 13:34; Mat 23:37"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 8, 'Ba lahalö ia, labunu, ba latibo''ö baero kabu nagu andrö.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 9, 'He iwisa dania sokhö kabu nagu andrö? Möi ia dania mamakiko sohalöŵö andrö, ba ibe''e ba danga danö bö''ö kabu no mege.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 10, 'Hadia, lö''ö göi ni''ilami zi so ba zura andrö: "Gowe andrö, nitibo''ö zotomo andrö, ba notobali toyo ba watalinga;[4]', '["Sin 118:22"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 11, '10 Hadia, lö''ö göi ni''ilami zi so ba zura andrö: "Gowe andrö, nitibo''ö zotomo andrö, ba notobali toyo ba watalinga; 1', '["Sin 118:22"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 12, 'Ba la''alui lala wondra''u ya''ia. ba ata''u ira niha sato; aboto sa''ae ba dödöra, wa khöra iböbögö gamaedola andrö. Ba laröi ia, mofanö ira.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 13, 'Ba lafatenge khönia warizaio[6] ösa awö zi fao-fao khö Herode, ena''ö la''alani ia ba huhuo.', '["Ayati 13–17: Mat 22:15–22; Luk 20:20–26"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 14, 'Ba möi ira, ba lamane khönia: He samahaö, ma''ila satulö ndra''ugö ba lö ba dödöu niha, lö''ö sa öfaigi mbawa niha ba si ndruhu wangombakha''öu lala andrö khö Lowalangi. Hadia, tola labe''e mbeo khö kaizaro, ma lö''ö? Hadia labe''e, hadia lö''ö?', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 15, 'Ba ya''ia, me no i''ila wamini tödö andrö khöra, ba imane khöra: Hadia wa mitandraigö ndra''o? Mi''oroma''ö khögu hua suku zambua.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 16, 'Ba imane khöra: Ha famaedo da''e ba ha ökhö zura andre?', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 17, 'Ba imane khöra Yesu: Hadia khö kaizaro, ba mibe''e khö kaizaro, ba hadia khö Lowalangi, ba mibe''e khö Lowalangi. Ba ahöli-höli dödöra khönia.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 18, 'Ba möi khönia zadukaio,[7] sanguma''ö, lö femaoso zi mate, lasofu khönia, lamane:[8]', '["Ayati 18–27: Mat 22:23–33","Yoh 11:57"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 19, 'He samahaö, no ifakhoi khöma Moze: na mate zi so talifusö, ba na toröi wo''omonia, lö ono, ba yamuhalö wo''omonia talifusönia, yamufonga''ötö dalifusönia.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 20, 'Ba no so zi fatalifusö, dafitu; ba mangowalu zi samösa, ba me mate ia, ba lö nga''ötö.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 21, 'Ba ihalö ndra alawe andrö si samösa, ba mate, lö nga''ötö; ba si manö göi wanete da''ö.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 22, 'Ba lö nga''ötö zi dafitu andrö.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 23, 'He wisa ba wemaoso zi mate andrö, na maoso ira, ha fo''omo ia, ba khöra andrö? noa sa dafitu ira, zangai ya''ia.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 24, 'Imane khöra Yesu: Tenga andrö elungu ami, me lö aboto ba dödömi zi so ba zura, ba me lö aboto ba dödömi wa''abölö Lowalangi andrö?', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 25, 'Na maoso zi mate andrö, ba lö mangowalu ira, ba lö möi nihalö, hulö mala''ika ba zorugo ira dania.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 26, 'Ba ba zi mate andrö, wa maoso ira, ba hadia, lö ni''ilami ba zura Moze, ba ngafu ndroi andrö, me humede khönia Lowalangi, me imane: "Lowalangi Gaberahamo ndrao, ba Lowalangi Giza''aki ba Lowalangi Yakobo?"', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394511, 'NT', 'Mareko', 12, 27, 'Tenga Lowalangi zi mate ia, no Lowalangi zauri; no abölö-bölö wa''elungumi andrö.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 28, 'Ba i''ondrasi ia sangila amakhoita,[9] samösa; no irongo, me fahuhuo ira ba no i''ila, enahöi wamu''ania; isofu khönia, imane: Hadia goroisa si föföna sibai?', '["Ayati 28–34: Mat 22:34–40"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 29, 'Imane Yesu: Da''ö zi föföna:', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 30, 'ba omasi''ö Zoaya, Lowalangiu andrö, moroi si''aikö ba dödöu, nosou ma''asambua zangomasi''ö ya''ia, ba horigö gera-erau, awö wa''abölöu, wangomasi''ö ya''ia.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 31, '"Omasi''ö zahatö khöu, si mane fa''omasiu ndra''ugö."', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 32, 'Ba imane khönia sangila amakhoita andrö: Ya''ia, samahaö, si ndruhu. niwa''öu, ha samösa, ba lö tanö bö''ö baeronia.[10]', '["MozV 4:32"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 33, 'Ba fangomasi''ö ya''ia andrö, moroi si''aikö ba dödö, awö wa lahorigö gera-era, awö wa''abölö, wangomasi''ö ya''ia ba fangomasi''öda sahatö khöda, si mane fa''omasida ita, ba no tohude wa''asökhi da''ö, moroi ba wa''asökhi zumange nitunu, awö zumange nitaba, fefu.[11]', '["SamI 15:22"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 34, 'Ba me i''ila Yesu, tenga sambö era-era ia, wanema li, ba imane khönia: Lö aröu tö, ba banua Lowalangi ndra''ugö.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 35, 'Ba humede Yesu,[13] imane, wamahaö ba gosali: Hana wa laŵa''ö sangila amakhoita, ma''uwu Dawido Keriso andrö?', '["Ayati 35–37: Mat 22:41–46; Luk 20:41–44"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 36, 'No ya''ia, Dawido, zanguma''ö moroi ba Geheha ni''amoniö: "No iŵa''ö So''aya khö Zo''aya ya''o andrö: Dadao ba gambölögu, irege ube''e tou barö gaheu zi fatiu tödö khöu."[14]', '["Sin 110:1 b.t."]', NULL),
  (3394511, 'NT', 'Mareko', 12, 37, 'Ya''ia, Dawido, zi faso''aya khönia, ba he moroi, wa ma''uwunia? Ba no wa''omasi niha sato wamondrongo khönia.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 38, 'Ba imane wamahaö ya''ira:[15] Mi''angelamaisi zangila amakhoita andrö, somasi mamaru baru sanau, somasi na la''owai ira ba kade,[16]', '["Ayati 38–40: Luk 20:45–47","Mat 23:5,6"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 39, 'somasi dadaoma tanö yaŵa ba zekola ba he naha tanö yaŵa ba walöŵa;', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 40, 'si manga gölö lakha mbanua, sangaragö fangandrö, ena''ö la''ila niha; tedou wa''abe''e huku, si göna ira dania, labe''e si manö.[17]', '["Mat 23:14"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 41, 'Ba mudadao ia ba gamaudu naha game''ela,[18] ifaigi he wisa wame''e zato kefe ba naha game''ela andrö.', '["Ayati 41–44: Luk 21:1–4"]', NULL),
  (3394511, 'NT', 'Mareko', 12, 42, 'Ba so lakha mbanua, si numana, ibe''e bakha dombua rimi, tobali sambua se.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 43, 'Ba humede Yesu ba nifahaönia, imane khöra: Si ndruhu niŵa''ögu khömi, ebua nibe''e lakha mbanua si numana andrö, moroi ba khöra fefu, same''e kefe ba naha game''ela.', '[]', NULL),
  (3394511, 'NT', 'Mareko', 12, 44, 'A''oi sa moroi ba zi töra khöra labe''e, ba ya''ia, ba moroi ba zambö khönia ibe''e, fefu hadia ia zi so khönia, balazonia ma''afefu.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 1, 'Ba mofanö ia, iröi gosali,', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 2, 'Ba imane khönia Yesu: Ö''ila gosali sebua andrö? Sambua manö lö''ö dania si toröi ba dete nawönia yaŵa kara, si lö ladudugö.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 3, 'Ba me dumadao ia ba hili wanikha, ba gamaudu gosali, ba lasofu khönia ira Fetero, Yakobo, Yohane ba Andrea, ba zi ha ya''ira, lamane:', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 4, 'Ombakha''ö khöma, ha wa''ara dania da''ö? ba hadia dandra, na inötö da''ö fefu dania?', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 5, 'Ba ibörötaigö Yesu, imane khöra: Mifaigi, fa lö ifaelungu ami niha.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 6, 'Ato zi so dania, sanagö töigu, ba lamane dania: Ya''odo, ba ato lafaelungu.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 7, 'Ba na mirongo wanuwö-nuwö ba turia wanuwö-nuwö, ba böi tokea dödömi; lö tola lö si manö, ba tenga fa''atua danö na sa.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 8, 'Maoso sa dania zi sambua soi, udu zi sambua, ba si sara öri, udu zi sara; sosò ndruru danö misa ba sosò lofo mbanua. Böröta wa''afökhö da''ö.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 9, 'Ba mifaigi-faigi, he miwisa ami. Latou''ö dania ami ba danga zalaŵa rafe ba la''ohe ami ba walukhata, labözi-bözi ami, la''ohe ami barö gumandru ba barö razo, börö ndra''o, ba wamaduhu''ö khöra.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 10, 'Ba lö tola lö te''ombakha''ö duria somuso dödö andrö ua ba niha fefu, ha soi ira.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 11, 'Ba na la''ohe ami, ba wame''e ba dangara ya''ami, ba böi mihönagö mi''abusi tödö, hadia niŵa''ömi dania, hadia nibe''e ba dödömi, na inötö wehede andrö, da''ö miŵa''ö; tenga sa ya''ami zihede, Eheha ni''amoni''ö andrö zihede.[2]', '["Mat 10:19 b.t."]', NULL),
  (3394512, 'NT', 'Mareko', 13, 12, 'Ba itou''ö ba danga zamunu ya''ia dalifusönia sotalifusö ba si manö zo''ono ba nononia, ba maoso ndraono, udu ndra amara, ba wamunu la''ohe.[3]', '["Mikh 7:6","Mat 10:22"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 13, 'Ba dozi niha fatiu dödö khömi, börö döigu. Ba sanau ölö, irugi gamozua, da''ö ni''orifi.[4]', '["Mikh 7:6","Mat 10:22"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 14, 'Ba na mi''ila so ba zi tenga nahania zogoro ita andrö, böröta wa''adudu — yamube''e ba dödönia sombaso da''e — ba yamoloi ba hili zi so ba Yudaia.[5]', '["Dan 9:27"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 15, 'Ba si so ba dete nomo yaŵa, ba böi yamöi tou, böi yamöi yomo, ba wangai hadia ia ba nomonia.', '["Dan 9:27"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 16, 'Ba si no möi ba nowi, ba böi yamufuli ia furi, ba wangai barunia.', '["Dan 9:27"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 17, 'Ba alai zanabina ba si so ono, ba mbagi zusu, na luo da''ö.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 18, 'Ba mi''angandrö, fa böi na baŵa deu.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 19, 'Famakao sa dania luo da''ö, lö irai si manö, i''otarai mböröta hadia ia fefu nifazökhi Lowalangi, irugi da''e, ba lö''ö manö göi simanö dania.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 20, 'Ba na lö i''önaigö ena''ö mbaŵa da''ö So''aya, ba samösa lö auri niha ena''ö; ba börö nitutuyu andrö, si no itutuyu, wa no i''önaigö mbaŵa da''ö.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 21, 'Ba ba da''ö dania, na so zanguma''ö khömi: Ya''e Keriso andrö, hiza! ba böi mifati.', '["Yoh 16:4"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 22, 'Ba maoso dania Keriso faya ba sama''ele''ö sofaya, ba lafazökhi dandra, awö gila-ila, ba wamaelungu nitutuyu andrö göi, na böla.', '["Yoh 16:4"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 23, 'Ba ya''ami, mifaigi, no uhönagö uŵa''ö khömi da''ö fefu.[6]', '["Yoh 16:4"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 24, 'Bana luo da''ö,[7] na no aefa wamakao no mege, ba taya haga luo, ba lö''ö sa''ae dania muhaga mbaŵa,', '["Ayati 24–32: Mat 24:29–36; Luk 21:25–33"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 25, 'ba atoru ndröfi moroi ba mbanua si yaŵa, ba humeu-heu wangarö andrö, ba mbanua si yaŵa.', '["Ayati 24–32: Mat 24:29–36; Luk 21:25–33"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 26, 'Ba la''ila dania Nono Niha, si so moroi sa ba lawuo, a''oi so wa''abölö, awö lakhömi.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 27, 'Ba ifatenge dania mala''ikania andrö, ba i''owuloi nitutuyu andrö, moroi ba zi fasui, i''otarai wondrege danö, irugi gahe mbanua ba wondrege tanö sa.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 28, 'Ba ba marafala mitöngöni wamaedo andrö. Na mo''idanö ndrahania, na tumbu lehe-lehe, ba mi''ila, wa no ahatö mbaŵa wa''aukhu zino.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 29, 'Si manö göi ami, na mi''ila itörö da''ö no mege, ba oroma khömi, no ahatö ia.', '[]', NULL),
  (3394512, 'NT', 'Mareko', 13, 30, 'Si ndruhu niŵa''ögu khömi, lö fakhamö atua niha si sagötö andre, irugi itörö da''ö fefu.', '["Yes 51:6","HalZin 1:7"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 31, 'Atua mbanua si yaŵa dania ba atua danö, ba lö awu''a ligu.[8]', '["Yes 51:6","HalZin 1:7"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 32, 'Ba baŵa andrö ba inötö, ba lö sangila, mala''ika ba zorugo göi lö''ö, Ono göi lö''ö, ha Ama zangila.[9]', '["Yes 51:6","HalZin 1:7"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 33, 'Mifaigi, böi miförö; lö''ö sa mi''ila ginötö.[10]', '["Mat 24:42; Luk 12:40; 21:36","Mat 25:13"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 34, 'Hulö niha sofanö, sondröi omonia, same''e ba danga zawuyunia hadia ia khönia, sanguma''ö halöŵö zamösana ba sanguma''ö khö zanaro ba mbawandruhö, böi mörö ia.[11]', '["Mat 24:42; Luk 12:40; 21:36","Mat 25:13"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 35, 'Ba böi miförö, lö''ö sa mi''ila ginötö wa''aso zatua baomo andrö, na tanö owi, ba ma na talu mbongi, ba ma na miwo manu, ba ma na moluo,', '["Mat 24:42; Luk 12:40; 21:36","Mat 25:13"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 36, 'fa böi mörö ami, i''ila, na so ia lö mudöna-döna.', '["Mat 24:42; Luk 12:40; 21:36","Mat 25:13"]', NULL),
  (3394512, 'NT', 'Mareko', 13, 37, 'Ba hadia niŵa''ögu khömi, ba khömi fefu uŵa''ö: böi miförö!', '["Mat 24:42; Luk 12:40; 21:36","Mat 25:13"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 1, 'Ba hatö dua wongi, ba fasa andrö ba baŵa roti si lö mu''aisöni.[1] Ba la''alui ere sebua ba sangila amakhoita he lawisa wangonekhesi fondra''u ya''ia, ba famunu ya''ia.', '["Ayati 1–2: Mat 26:2–5; Luk 22:1,2"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 2, 'Lamane sa: Böi ba gowasa, fa böi aekhu niha.', '["Ayati 1–2: Mat 26:2–5; Luk 22:1,2"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 3, 'Ba me so ia ba Mbetania,[2] ba nomo Zimoni andrö, sobou auri, me manga ia, ba so ndra alawe, so khönia zamba buli-buli kara zi ndruhu wanikha naridu, sebua böli, ba iboto mbuli-buli, ba ifaduwa ba högö Yesu wanikha andrö.', '["Ayati 3–9: Mat 26:6–13; Yoh 12:1–8"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 4, 'Ba so ösa zikökö-kökö tödöra, lamane: Hadia wa la''alimagösi wanikha andrö.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 5, 'Tola sa la''amawa mena''ö wanikha andrö, töra otu a lima wulu rufia, ba tola tebe''e ba zinumana. Ba kumökö-kökö ira khönia.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 6, 'Ba imane Yesu: Böi mitegu ia; hadia wa mibusi dödönia? Si sökhi nilaunia khögu.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 7, 'Lö tebulö awömi zi numana, ba tola mitolo ira, na edöna ami, ba ya''o, ba tenga si lö tebulö khömi.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 8, 'No ilau ndrege zi tola ilau; no ihönagö ibayoini mbotogu, ba wogo''o ya''o.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 9, 'Ba sindruhu niŵa''ögu khömi, heza misa teturiagö duria somuso dödö andrö, ba guli danö ma''asagörö, ba da''ö göi te''ombakha''ö nilau da''e, ba wanörö tödö ya''ia.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 10, 'Ba möi khö gere sebua Yuda andrö, banua Kariota, awö zi felendrua, ba wemanga mbölinia khöra.[3]', '["Ayati 10–11: Mat 26:14–16; Luk 22:3–6"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 11, 'Ba omuso dödöra, me larongo, ba lafabu''u khönia labe''e gana''a. Ba i''alui he wisa zenahöi, wangombakha ya''ia.', '["Ayati 10–11: Mat 26:14–16; Luk 22:3–6"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 12, 'Ba me baŵa roti si lö mu''aisöni,[4] si föföna, ba nitaba fasa andrö, ha lamane khönia nifahaönia: Heza zomasi''ö, heza möiga mangasiwai, ena''ö ö''a wasa andrö?', '["Ayati 12–16: Mat 26:17–19; Luk 22:7–18"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 13, 'Ba ifatenge nifahaönia, darua, imane khöra: Mi''ae miyomo ba mbanua, ba falukha ami niha, solohe migö nidanö, mi''o''ö ia.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 14, 'Ba ba zi möi ia yomo ba nomo, ba da''ö mimane khö zokhö omo: Da''ö niŵa''ö zamahaö khöu: Hezo nahagu andrö, heza u''a wasa andrö, awö nifahaögu?', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 15, 'Ba i''oroma''ö khömi dania mbate''e sebua, ba si sagötö, si no labe''e tufo, si no muhaogö; ba da''ö mi''asiwai khöda.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 16, 'Ba möi nifahaö andrö, larugi yomo ba mhanua, ba itörö niŵa''önia khöra. Ba la''asiwai wasa no mege.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 17, 'Ba me tanö owi, ba so ia, awö zi felendrua.[5]', '["Ayati 17–21: Mat 26:20–25; Luk 22:21–33"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 18, 'Ba me no mudadao ira, me manga, ba imane Yesu: Si ndruhu niŵa''ögu khömi, samösa ba khömi sorudu manga khögu zi manga mböligu dania.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 19, 'Ba ibörötaigö abu dödöra, ba oi zara lamane khönia: Hadia ya''odo?', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 20, 'Ba imane khöra: Samösa ba zi felendrua, si falulu manga khögu.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 21, 'Itörö sa lalania Ono Niha, itörö zi so ba zura ba khönia, ba alai niha andrö, si manga mböli Nono Niha; sökhi ba niha andrö, lö tumbu ia mege.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 22, 'Ba me manga ira,[6] ba ihalö roti, ifahowu''ö ba iboboto, ibe''e khöra, imane: Mitema, mi''a, botogu da''e.', '["Ayati 22–25: Mat 26:26–29; Luk 22:14–20"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 23, 'Ba ihalö mako, i''aohasi gölö Lowalangi, ibe''e khöra, ba labadu, dozi ira.', '["Ayati 22–25: Mat 26:26–29; Luk 22:14–20"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 24, 'Ba imane khöra: Dogu da''e, do gamabu''ula li, saduwa salahi zato.', '["Ayati 22–25: Mat 26:26–29; Luk 22:14–20"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 25, 'Si ndruhu niŵa''ögu khömi, lö''ö manö sa''ae ubadu nösi mbua nagu andrö, irugi luo wamadugu si bohounia, ba mbanua Lowalangi andrö.', '["Ayati 22–25: Mat 26:26–29; Luk 22:14–20"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 26, 'Ba me no aefa manunö ira, ba möi ira baero, ba gahe hili wanikha andrö.[7]', '["Ayati 26–31: Mat 26:30–35"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 27, 'Ba imane khöra Yesu: Dozi dania ami te''ala, si mane sa ba zura: "Ubago dania gubalo andrö, ba sumawili mbiri-biri andrö nikubaloi."', '["Faigi 16:7"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 28, 'Ba na aefa maoso ndra''o, ba mowaö-waödo ba Galilaia, fönami.[8]', '["Faigi 16:7"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 29, 'Ba imane khönia Fetero: He dozi te''ala ira, ba ya''o, ba lö te''ala.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 30, 'Ba imane khönia Yesu: Si ndruhu niŵa''ögu khöu, iada''e bongi andre, lö fakhamö mendrua miwo zilatao, ba no medölu ö''osilö''ögö ndra''o.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 31, 'Ba ihötöi fanguma''ö: Ba he matedo awöu, ba tebai u''osilö''ögö ndra''ugö. Ba si manö wanguma''ö ndra nifahaö fefu.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 32, 'Ba larugi halama, Gezemane döinia, ba imane ba nifahaönia:[9] Midadao ba da''e, irege no mangandrö ndra''o.', '["Ayati 32–42: Mat 26:36–46; Luk 22:29–46; Yoh 18:1"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 33, 'Ba i''ohe awönia ndra Fetero, Yakobo, Yohane, ibörötaigö manizi-nizi ba abu dödö.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 34, 'Ba imane khöra: Abu sibai dödögu, irugi wa''amate; mi''iagö da''e ba böi miförö.[10]', '["Heb 5:7"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 35, 'Ba mofanö ia, lö aröu, ifalögu tou ia ba danö ba mangandrö, ena''ö italu''i ia inötö andrö, na böla.[11]', '["Yoh 12:27"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 36, 'Imane: He Aba, Ama, lö hadia ia zi tebai ndra''ugö; heta khögu mako andrö; ba böi somasi ndra''o, somasi ndra''ugö sa.', '["Yoh 12:27"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 37, 'Ba ifuli ia, ba no mörö ira, me irugi,', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 38, 'Böi miförö ba mi''angandrö, fa böi itörö ami fanandraigö. Aoha sa gölö dödö, ba si no ambö fa''ahölö nösi.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 39, 'Ba ifuli möi mangandrö, si mane mege no linia.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 40, 'Ba me ifuli ia, ba no mörö zui ira, me irugi, me no abua guli höröra, ba lö la''ila hadia niŵa''öra, wanema linia.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 41, 'Ba so zui ia, me no medölu, ba imane khöra: Miförö sa''ae ba mi''olombase! No abönö. No inötö, hiza, tetou''ö ba danga niha si so horö Nono Niha.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 42, 'Mifaoso! talabu; hiza, no ahatö zi manga mböligu andrö.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 43, 'Ba i''anema''ö, me muhede ia na,[12] ba so Yuda, banua Kariota andrö, awö zi felendrua, ba ato zi fao khönia soföda ba sobago gama, nifatenge gere sebua ba sangila amakhoita ba satua mbanua andrö.', '["Ayati 43–50: Mat 26:47–56; Luk 22:47–53; Yoh 18:2,3; 10:11"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 44, 'Ba no iŵa''ö khöra dandra si manga mböli andrö, no imane: Si fa''ago bawa ndra''o, da''ö ia, da''ö mira''u ba mi''ohe, mi''aro''ö.', '["Ayati 43–50: Mat 26:47–56; Luk 22:47–53; Yoh 18:2,3; 10:11"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 45, 'Ba me so ia, ba i''anema''ö i''ondrasi Yesu, imane khönia: He samahaö! ba fa''ago bawa ia khönia.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394513, 'NT', 'Mareko', 14, 46, 'Ba lababaya, lara''u.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 47, 'Ba isöbi wöda si samösa, awö zi so ba ngai andrö, itema igukhui zawuyu gere sebua, i''eŵa dalinga.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 48, 'Ba humede Yesu, imane khöra: Hulö na ba zorabu möi ami, moföda ami ba mobago gama, wondra''u ya''o.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 49, 'Ero ma''ökhö so ndra''o khömi ba gosali, mamahaö ndra''o, ba lö nira''umi ya''o; ba ena''ö itörö zi so ba zura.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 50, 'Ba laröi ia [awönia], oi zara moloi.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 51, 'Ba so nono matua samösa, solo''ö ya''ia, ha sambua mbaru, baru muko si sökhi; ba lara''u ia.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 52, 'Ba iröi furi mbaru muko andrö ba moloi lö baru.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 53, 'Ba la''ohe khö gere sebua Yesu;[13] ba falukha gere sebua fefu ba satua mbanua ba sangila amakhoita andrö.', '["Ayati 53–65: Mat 26:57–68; Luk 22:54. 63–65"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 54, 'Ba i''o''ö Fetero, aröu moroi furi, irugi baolayama gere sebua, ba mudadao ia, awö genoni andrö, moleu ia, ba zinga galitö.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 55, 'Ba la''alui wamöbögö horö khö Yesu ere sebua, awö zalaŵa rafe sebua fefu, ba wamunu ya''ia, ba lö lasöndra.', '["MozV 17:6","Faigi 15:29"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 56, 'Ato sa zamöbögö horö khönia, ba lö faoma wanguma''öra.[14]', '["MozV 17:6","Faigi 15:29"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 57, 'Ba so ösa zamöbögö khönia, lamane:', '["MozV 17:6","Faigi 15:29"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 58, 'No marongo me iŵa''ö: Ududugö dania gosali andre, nifazökhi danga niha, ba ha tölu ngaluo u''angotomosi''ö danö bö''ö, si tenga nifazökhi danga niha.[15]', '["MozV 17:6","Faigi 15:29"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 59, 'Ba ba da''ö göi lö faoma wanguma''öra.', '["MozV 17:6","Faigi 15:29"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 60, 'Ba maoso gere sebua, i''agö gotaluara, isofu khö Yesu, imane: Hadia, ma''ifu lö ötema li ba niböbögö da''ö khöu?', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 61, 'Ba lö hede-hedenia, ma''ifu lö itema li.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 62, 'Ba imane Yesu: Ya''ia, ba mi''ila dania dumadao Nono Niha ba gambölö wa''abölö andrö, ba so ia, ba lawuo ba mbanua si yaŵa.[17]', '["Faigi 13:26"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 63, 'Ba isika nukhania ere sebua, ba imane: Hadia sa''ae guna zi so ba mbörö?', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 64, 'No mirongo wangaoha-ngaoha andrö. He wisa ba dödömi? Ba oi zara la''etu''ö hukunia, huku famunu.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 65, 'Ba labörötaigö ösa ladidiloi ia, labalugö mbawania ba lagukhui ia ba lamane khönia: Ama''ele''ö; ba latema lafalisi ia si''o enoni andrö.[18]', '["Faigi 10:34; Mar 15:19"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 66, 'Ba me so tou Wetero baolayama,[19] ba so zawuyu gere sebua, ono alawe, samösa,', '["Ayati 66–72: Mat 26:69–75; Luk 22:55–62; Yoh 18:16–18,25–27"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 67, 'ba me i''ila Wetero, me moleu, ba inehegö, ba imane: Ya''ugö göi nawö mbanua Nazareta andrö, Yesu andrö.', '["Ayati 66–72: Mat 26:69–75; Luk 22:55–62; Yoh 18:16–18,25–27"]', NULL),
  (3394513, 'NT', 'Mareko', 14, 68, 'Ba i''osilö''ögö, imane: Lö u''ila, hadia niŵa''öu, lö aboto ba dödögu. Ba möi ia baero, baolayama föna, ba miwo zilatao.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 69, 'Ba i''ila ia sawuyu ono alawe no mege, ba ifuli ibörötaigö, imane ba zi so ba da''ö: Samösa da''e, awöra.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 70, 'Ba ifuli i''osilö''ögö.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 71, 'Ba ibörötaigö i''elifi ia ba fahölu, imane: Lö u''ila ha niha da''ö, niŵa''ömi.', '[]', NULL),
  (3394513, 'NT', 'Mareko', 14, 72, 'Ba i''anema''ö ifuli miwo zilatao, no mendrua. Ba itörö tödö Wetero li Yesu, me imane khönia: Lö fakhamö mendrua miwo zilatao, ba medölu ö''osilö''ögö ndra''o. Ba me itörö tödönia, ba mege-ege ia.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 1, 'Ba me moluo sibai, me no aetu huhuora, ere sebua ba satua mbanua ba sangila amakhoita ba salaŵa rafe sebua andrö, fefu, ba laböbö Yesu, la''ohe ia, labe''e ba danga Wilato.[1]', '["Ayati 1: Mat 27:1,2; Luk 22:66–71"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 2, 'Ba isofu khönia Filato, imane:[2] Hadia, razo niha Yehuda ndra''ugö?', '["Ayati 2–15: Mat 27:11–26; Luk 23:2–4,17–25; Yoh 18:33–40"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 3, 'Ba laforege wangadugö ya''ia ere sebua andrö.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 4, 'Ba ifuli isofu khönia Filato, imane: Hadia, ma''ifu lö ötema li? Hiza, fahöna manö khöra, wangadugö ya''ugö.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 5, 'Ba ma''ifu lö''ö sa''ae itema li Yesu; tobali ahöli-höli dödö Wilato.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 6, 'Ba ero na owasa, ba ibe''e aefa khöra nikuru, samösa, ha niha ni''andröra.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 7, 'Ba so nikuru, awö zolaŵa andrö, Baraba döinia, awö zi no mange''e, me molaŵa niha.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 8, 'Ba möi miyaŵa niha sato, labörögö mangandrö, itörö khöra si mane föna.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 9, 'Ba itema lira Filato, imane: Hadia omasi ami, u''efa''ö khömi razo niha Yehuda andrö?', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 10, 'Noa sa i''ila, wa börö wa''afökhö dödö, wa labe''e ia ba dangania ere sebua.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 11, 'Ba lafawe''e niha sato ere sebua andrö, ena''ö i''efa''ö khöra Mbaraba andrö.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 12, 'Ba itema zui lira Filato, imane khöra: Ba hadia zomasi ami, he uwisa ba niŵa''ömi razo niha Yehuda ia?', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 13, 'Ba mu''ao zui ira: Foröfa ia!', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 14, 'Ba imane khöra Filato: Ba hadia horönia i?', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 15, 'Ba edöna Wilato itörö zomasi niha sato, ba i''efa''ö khöra Mbaraba andrö, ifabözi''ö Yesu ba ibe''e niforöfa.[3]', '["Yoh 19:1"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 16, 'Ba la''ohe ia baolayama, ba gödo gumandru, saradadu ba lafa''aso zi sabari andrö fefu.[4]', '["Ayati 16–19: Mat 27:27–30; Yoh 19:2,3","Mar 14:65"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 17, 'Ba lafobaru ia baru luo soyo ba lalalau dakula doi, lafotakula ia.', '["Ayati 16–19: Mat 27:27–30; Yoh 19:2,3","Mar 14:65"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 18, 'Ba labörögö la''owai ia, lamane: Ya''ugö razo niha Yehuda?', '["Ayati 16–19: Mat 27:27–30; Yoh 19:2,3","Mar 14:65"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 19, 'Ba lafalisi högönia sukhu ba ladidiloi ia, latuhi danö, mangalulu khönia.[5]', '["Ayati 16–19: Mat 27:27–30; Yoh 19:2,3","Mar 14:65"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 20, 'Ba me no aefa la''o''aya ia,[6] ba laheta khönia mbaru luo soyo no mege ba lafonukha ia nukhania, ba la''ohe ia baero, ba wamoröfa ya''ia.', '["Ayati 20–32: Mat 27:31–44; Luk 23:26,33–39; Yoh 19:16–24"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 21, 'Ba laforege wanguma''ö ba zanörö lala, Simoni döi, banua Girene, si otarai nowi, ama ndra Alesandro Rufo, ena''ö i''ohe röfania.[7]', '["Rom 16:13"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 22, 'Ba la''ohe ia ba naha andrö, sotöi Gologata, — sokamu''u geluahania. —', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 23, 'Ba labe''e önia nagu si faruka emuri; ba lö ibadu.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 24, 'Ba laforöfa ia ba lafaosa nukhania, fadahö-dahö ira ba da''ö, ba wamaosa.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 25, 'Ba labözi siŵa, me laforöfa ia.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 26, 'Ba so zura horönia, nisura yaŵania: "Bazo niha Yehuda".', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 27, 'Ba darua laforöfa awönia, sorabu, samösa ba gambölö, ba samösa ba gaberania; ba itörö zi so ba zura andrö:', '["Yes 53:12"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 28, '"No tebe''e awö zebua horö ia".[8]', '["Yes 53:12"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 29, 'Ba latandraŵaisi ia sanörö, lafalikhö ira, lamane: Aha, sanudugö osali andrö, sangotomosi ya''ia, si ha tölu ngaluo.[9]', '["Faigi 14:58"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 30, 'Orifi ndra''ugö, ae tou moroi ba röfa andrö!', '["Faigi 14:58"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 31, 'Simanö göi gere sebua andrö, mango''aya, faoma muhede ira khö nawöra, awö zangila amakhoita, lamane: Tanö bö''ö no i''orifi, ba lö i''ila i''orifi ia.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 32, 'Keriso andrö, razo Ndraono Gizeraeli, yamöi tou iada''e, moroi ba röfa andrö, ena''ö ta''ila ba ena''ö mamati ita; latandraŵaisi göi ia niforöfa awönia.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 33, 'Ba me laluo, ba ogömi-gömi danö ma''afefu, irege labözi tölu.[10]', '["Ayati 33–41: Mat 27:45–56; Luk 23:44–49; Yoh 19:28–30"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 34, 'Ba me labözi tölu, ba mu''ao Yesu, ebua li, imane: Eloi! Eloi! lama sabakhtani? He Lowalangigu! He Lowalangigu! hana wa no ö''erogö ndra''o? geluahania.', '["Ayati 33–41: Mat 27:45–56; Luk 23:44–49; Yoh 19:28–30"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 35, 'Ba lamane ösa, si so ba da''ö, me larongo: Hiza, mu''ao khö Geliya.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 36, 'Ba fagohi zamösa, ihalö rabo, ifo''ösi niro aisö, ibe''e ba mbalö zukhu, ifabadugö, khönia, imane: Böi ua, datafaigi, na möi Geliya, ba wangefa''ö ya''ia.[11]', '["Sin 69:22"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 37, 'Ba mu''ao Yesu, ebua li, ba aetu noso.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 38, 'Ba asika mba''a-ba''a andrö ba gosali, fabali manö, i''otarai si yaŵa, numalö mitou.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 39, 'Ba me i''ila kumandra andrö, si so ba da''ö ba gamaudunia, wa si manö wa''amatenia, ba imane: Si ndruhu, Ono Lowalangi niha andrö.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 40, 'Ba so göi ndra alawe, samaigi-maigi moroi ba zaröu, ira Maria, banua Magadala andrö, ba Maria, ina ndra Yakobo side-ide Yose andrö, ba Salome andrö;[12]', '["Yoh 19:25"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 41, 'si no fago''ö-go''ö khönia, me so ia ba Galilaia, si no möi-möi ngoni-ngoninia, ba ato na danö bö''ö, si no fao khönia, we''amöi misi yaŵa ba Yeruzalema.', '["Yoh 19:25"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 42, 'Ba me no arakha bongi (baŵa wangehao, sara wongi lö sabato)[13]', '["Ayati 42–47: Mat 27:57–61; Luk 23:50–55; Yoh 19:14,38–42"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 43, 'ba so Yosefo, banua Garimatia, salaŵa rafe, si sökhi amuata, sanötöna göi banua Lowalangi andrö; lö ata''u ia we''amöi khö Wilato, wangandrö boto Yesu.', '["Ayati 42–47: Mat 27:57–61; Luk 23:50–55; Yoh 19:14,38–42"]', NULL),
  (3394514, 'NT', 'Mareko', 15, 44, 'Ba ahöli-höli dödö Wilato, wa noa sa''ae mate ia, ba ifakaoni''ö gumandra andrö, isofu khönia na no ara, me mate ia.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 45, 'Ba meno irongo khö gumandra andrö, ba i''amualagö mboto no mege khö Yosefo andrö.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 46, 'Ba i''öli muko, ihalö tou mboto, i''olohuni muko ba ibe''e ba lewatö nikhao ba gara, ba ifagaölö gowe ba mbawa lewatö andrö.', '[]', NULL),
  (3394514, 'NT', 'Mareko', 15, 47, 'Ba lafaigi, heza lako''o ia ira Maria, banua Magadala andrö ba Maria ina Yose andrö.', '[]', NULL),
  (3394515, 'NT', 'Mareko', 16, 1, 'Ba me no aefa luo sabato, ba la''öli dalu-dalu ira Maria, banua Magadala ba Maria, ina Yakobo andrö, ba Salome andrö, ena''ö möi ira mombayoini ya''ia.[1]', '["Faigi 15:40; Luk 23:56"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 2, 'Ba ahulö sibai, me luo migu, möi ira ba lewatö, me tumbu luo.[2]', '["Mat 28:1; Luk 24:1; Yoh 20:1","Mat 28:2; Luk 24:2"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 3, 'Ba faoma lamane khö nawöra: Ha niha zamagaölö khöda gowe andrö, wangeheta ya''ia ba mbawa lewatö?', '["Mat 28:1; Luk 24:1; Yoh 20:1","Mat 28:2; Luk 24:2"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 4, 'Ba me lafaigi, ba laila, no mufagaölö gowe andrö; ebua sibai sa.[3]', '["Mat 28:1; Luk 24:1; Yoh 20:1","Mat 28:2; Luk 24:2"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 5, 'Ba möi ira ba lewatö,[4] ba la''ila nono matua, samösa, si dadao ba gambölö, sobaru sanau, safusi; ba tokea ira.[5]', '["Ayati 5–8: Mat 28:5–8; Luk 24:3–9","Luk 24:4"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 6, 'Ba imane khöra: Böi tokea ami. Yesu, banua Nazareta andrö ni''aluimi, niforöfa andrö, no maoso ia, lö ya''ia ba da''e; hiza naha, ba nibe''era ya''ia.', '["Faigi 14:28"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 7, 'Ba mi''ae''e, miŵa''ö ba nifahaönia ba khö Wetero andrö, mowaö-waö ia fönami, we''amöi ba Galilaia; ba da''ö mi''ila ia dania, itörö dania niŵa''önia khömi.[6]', '["Faigi 14:28"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 8, 'Ba möi ira yaŵa, fulöi ira, wondröi lewatö; noa sa manizi-nizi ira ba no tobali dödöra; ba lö hede-hedera, me ata''u ira.', '[]', NULL),
  (3394515, 'NT', 'Mareko', 16, 9, 'Ba me no maoso ia, si hulö wongi, me luo migu, ba oföna i''oroma''ö ia khö Maria andrö, banua Magadala, ba nifofanönia bekhu andrö, si dafitu.[7]', '["Yoh 20:11–18; Luk 8:2"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 10, 'Möi da''ö, i''ombakha''ö ba zi no fao-fao khönia, si no abu tödö, sege-ege.', '["Luk 24:10,11"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 11, 'Ba ya''ira, me larongo, no auri ia ba no i''ila ia Maria, ba lö faduhu dödöra.[8]', '["Luk 24:10,11"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 12, 'Ba aefa da''ö, ba i''oroma''ö ia ba nawöra, darua, ba lala me möi ira ba mbanua bö''ö, bö''ö nga''eunia ha da''ö.[9]', '["Luk 24:13–25","Luk 24:37,41"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 13, 'Ba möi da''ö, la''ombakha''ö ba danö bö''ö andrö, ba ba khöra göi, ba lö faduhu dödöra.[10]', '["Luk 24:13–25","Luk 24:37,41"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 14, 'Furi ö i''oroma''ö ia ba zi felezara, me manga ira, ba itegu wa lö mamati ira ba fa''abe''e dödöra, wa lö si faduhu dödöra ba zangila ya''ia, me no maoso ia.[11]', '["Luk 24:36 b.t.; Yoh 20:19,20,27 b.t."]', NULL),
  (3394515, 'NT', 'Mareko', 16, 15, 'Ba imane khöra: Mi''ae mitöröi guli danö ma''afefu, mituriagö duria somuso dödo andrö, midozigö niha.[12]', '["Mar 13:10; Mat 28:19 b.t.; Kol 1:23","Yoh 3:18; 5:24; HalZin 2:38","HalZin 16:18; 8:7; 2:4; 19:6","Luk 10:19; HalZin 28:58; 9:17"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 16, 'Ha niha zamati, nibayagö idanö, da''ö zi falukha fa''auri, ba mbanua furi, ba nitibo''ö zi lö mamati.[13]', '["Mar 13:10; Mat 28:19 b.t.; Kol 1:23","Yoh 3:18; 5:24; HalZin 2:38","HalZin 16:18; 8:7; 2:4; 19:6","Luk 10:19; HalZin 28:58; 9:17"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 17, 'Ba da''ö dandra, si fao ba zamati andrö: Ba döigu lafofanö mbekhu; molau li si bohou ira,[14] latuyu gulö,', '["Mar 13:10; Mat 28:19 b.t.; Kol 1:23","Yoh 3:18; 5:24; HalZin 2:38","HalZin 16:18; 8:7; 2:4; 19:6","Luk 10:19; HalZin 28:58; 9:17"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 18, 'ba na labadu langu, famunu, ba lö te''ala ira; latufa tangara zofökhö, ba döhö wökhö.[15]', '["Mar 13:10; Mat 28:19 b.t.; Kol 1:23","Yoh 3:18; 5:24; HalZin 2:38","HalZin 16:18; 8:7; 2:4; 19:6","Luk 10:19; HalZin 28:58; 9:17"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 19, 'Ba me aefa fahuhuo khöra Zo''aya, ba tefazaŵa ia miyaŵa ba zorugo, ba mudadao ia ba gambölö Lowalangi.[16]', '["Luk 24:50 b.t.; Yoh 6:62; HalZin 1:9; Sin 110:1; Heb 1:3,13"]', NULL),
  (3394515, 'NT', 'Mareko', 16, 20, 'Ba ya''ira, ba mofanö mangombakha, fefu gofu heza, ba itolo So''aya, ifaduhu''ö daroma li tandra andrö, si fao khönia.[17]', '["HalZin 3:16; 5:15; 14:3; Heb 2:4"]', NULL),
  (3393924, 'NT', 'Luka', 1, 1, 'Me no ato zanandraigö manura nidunö-dunö andrö, si no itörö ba khöda,', '["Yoh 15:27; YohI 1:1","HalZin 1:1"]', NULL),
  (3393924, 'NT', 'Luka', 1, 2, 'nifa''ema zi so ba mbörö andrö, sangombakha taroma li andrö, khöda,', '["Yoh 15:27; YohI 1:1","HalZin 1:1"]', NULL),
  (3393924, 'NT', 'Luka', 1, 3, 'ba no uŵa''ö göi tödögu, usura göi khöu, ya''ugö Teofilo si sökhi, uhaogö wamöfö''ö, me no uzofu-zofu sibai fefu, i''otarai mböröta', '["Yoh 15:27; YohI 1:1","HalZin 1:1"]', NULL),
  (3393924, 'NT', 'Luka', 1, 4, 'ena''ö faduhu dödöu, duhu nirongou andrö, ni''ombakha''ö khöu, wamahaö ya''ugö.', '["Yoh 15:27; YohI 1:1","HalZin 1:1"]', NULL),
  (3393924, 'NT', 'Luka', 1, 5, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393924, 'NT', 'Luka', 1, 7, 'Ba lö ono khöra, me si lö mo''ono Gelizabe, ba faoma no numalö ndröfira.', '["Mat 2:1; Nga''ötI 24:10; Luk 22:52; Neh 12:14,17","MozV 10:12; Yob 1:1,8"]', NULL),
  (3393924, 'NT', 'Luka', 1, 8, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393925, 'NT', 'Luka', 2, 28, 'ba ihahae göi, isuno Lowalangi, imane:', '[]', NULL),
  (3393925, 'NT', 'Luka', 2, 29, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393928, 'NT', 'Luka', 4, 38, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393931, 'NT', 'Luka', 7, 6, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393933, 'NT', 'Luka', 8, 56, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393935, 'NT', 'Luka', 10, 38, '
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393937, 'NT', 'Luka', 12, 42, 'Ba imane So''aya: Ha niha zatua zangai halöŵö, si lö faröi si no atua-tua, nibe''e zokhö barö mbawa sangai halöŵö khönia, ba wame''e göra, na inötö?', '[]', NULL),
  (3393937, 'NT', 'Luka', 12, 43, 'Ya''ahowu zawuyu andrö, na i''ila sokhö ya''ia, na so ia, no i''o''ö zi manö.', '[]', NULL),
  (3393937, 'NT', 'Luka', 12, 44, 'Si ndruhu niŵa''ögu khömi, ibe''e barö mbawania fefu hadia ia zi so khönia.', '[]', NULL),
  (3393937, 'NT', 'Luka', 12, 45, 'Ba na iŵa''ö ena''ö tödönia sawuyu no mege: "Mogasa so zokhö ya''o", ba na ibörötaigö ibago-bago zawuyu ira matua ba sawuyu ira alawe, ba na manga-manga ia ba mamadu-madu tou ba mabu-mabu,', '["Yak 4:17"]', NULL),
  (3393937, 'NT', 'Luka', 12, 46, 'ba so dania zokhö sawuyu andrö, na luo lö idöna-döna, ba ha wa''alaŵa luo, ba lö i''ila, ba i''ötö dalu ba ibe''e gurakhania, awö zi lö mamati.', '["Yak 4:17"]', NULL),
  (3393937, 'NT', 'Luka', 12, 47, 'Ba sawuyu andrö, si no mangila somasi zokhö ya''ia, ba si lö mangasiwai hadia ia ba si lö molo''ö somasi zokhö, ba la''abölögö wamözi.[20]', '["Yak 4:17"]', NULL),
  (3393937, 'NT', 'Luka', 12, 48, 'Ba ha niha zi lö mangila, ba ilau hadia ia zi göna ia bözi-bözi, ba la''önaigö wamözi ya''ia. Ba dozi, ha khö zoya labe''e, ba oya lasugi khönia, ba ha khö zoya labe''e ba danga, ba oya göi la''andrö khönia.', '[]', NULL),
  (3393937, 'NT', 'Luka', 12, 49, 'Ba wolohe alitö ba guli danö so ndra''o, ba omasido sibai, na no muhola ia ena''ö;[21]', '["Yes 4:4"]', NULL),
  (3393937, 'NT', 'Luka', 12, 50, 'ba so nibayagö khögu dania, ba lö ahono dödögu ibe''e, irege no awai.', '["Yes 4:4"]', NULL),
  (3393937, 'NT', 'Luka', 12, 51, 'Hadia, miwai ba wolohe fa''atulö ba guli danö so ndra''o! Tenga da''ö, uŵa''ö khömi, ba wolohe fa''udusa möi ndra''o.[22]', '["Mat 10:34 b.t."]', NULL),
  (3393937, 'NT', 'Luka', 12, 52, 'I''otarai da''e sa, ba fa''udu zi dalima, si ha samba omo; fa''udu zi datölu ba zi darua, ba fa''udu zi darua ba zi datölu.', '[]', NULL),
  (3393937, 'NT', 'Luka', 12, 53, 'Fa''udu nama khö nono ba fa''udu nono khö nama, ba ina khö nono alawe ba ono alawe khö nina, inania khö numönö ba umönö khö ninania matuania.', '[]', NULL),
  (3393937, 'NT', 'Luka', 12, 54, 'Ba imane göi ba niha sato: Na mi''ila so lawuo moroi ba gahe mbanua, ba gaekhula luo, ba i''anema''ö mimane: So deu dania, ba itörö zi manö.[23]', '["Mat 16:2 b.t."]', NULL),
  (3393937, 'NT', 'Luka', 12, 55, 'Ba na angi moroi raya, ba mimane: Aukhu zino dania, ba itörö.', '["Mat 16:2 b.t."]', NULL),
  (3393937, 'NT', 'Luka', 12, 56, 'He ya''ami, samini tödö! amuata danö ba amuata mbanua, ba no mi''ila mihuku, ba inötö andre, ba he wisa wa lö mi''ila mihuku?', '[]', NULL),
  (3393937, 'NT', 'Luka', 12, 57, 'Ba hana wa tenga moroi ba dödömi manö göi mihuku, hadia zatulö?', '[]', NULL),
  (3393937, 'NT', 'Luka', 12, 58, 'Na fao ami zi fa''udu khöu, we''amöi ba gumandru, ba forege ba lala, ena''ö aefa ndra''ugö khönia, fa böi isöbi ndra''ugö khö zanguhuku, ba ibe''e ba danga wazuri ndra''ugö sanguhuku, ba ikuru''ö fazuri.[24]', '["Mat 5:25 b.t."]', NULL),
  (3393937, 'NT', 'Luka', 12, 59, 'Uŵa''ö khöu, lö''ö manö aefa''ö ba da''ö, na so zi tosai si sakefe, ömöu, si lö mubu''a.', '["Mat 5:25 b.t."]', NULL),
  (3393938, 'NT', 'Luka', 13, 1, 'Ba so niha ösa, me luo da''ö, la''ombakha''ö khönia mbanua Galilaia andrö, nifaruka Wilato do ba zumange andrö khöra.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 2, 'Ba itema lira, imane khöra: Hadia, miwai ebua horö mbanua Galilaia andrö, moroi ba horö mbanua Galilaia bö''ö fefu, me no göna ira da''ö?', '["Faigi 19:42 b.t.","Neh 3:15"]', NULL),
  (3393938, 'NT', 'Luka', 13, 3, 'Tenga da''ö, uŵa''ö khömi; na lö mifalalini gera-erami sa, ba oi si manö wa''atekikomi dania.[1]', '["Faigi 19:42 b.t.","Neh 3:15"]', NULL),
  (3393938, 'NT', 'Luka', 13, 4, 'Ma si feleŵalu andrö, nilangö malige andrö ba Ziloa, si mate ba da''ö, hadia, miwai ebua zalara, moroi ba zala niha bö''ö fefu, banua Yeruzalema?[2]', '["Faigi 19:42 b.t.","Neh 3:15"]', NULL),
  (3393938, 'NT', 'Luka', 13, 5, 'Tenga da''ö, uŵa''ö khömi; na lö mifalalini gera-erami sa, ba oi si manö wa''atekikomi dania.', '["Faigi 19:42 b.t.","Neh 3:15"]', NULL),
  (3393938, 'NT', 'Luka', 13, 6, 'Ba iŵa''ö gamaedola andre: So niha föna, si so töla marafala, nitanö ba kabu nagu khönia; ba möi ia mamaigi bua khönia, ba lö ni''ilania.[3]', '["Yes 5:2; Yer 8:13; Mat 21:19"]', NULL),
  (3393938, 'NT', 'Luka', 13, 7, 'Ba imane ba zohalöŵö ba kabu nagu: Hiza, no medölu fakhe ae möido, mamaigi bua ba marafala andrö, ba lö ni''ilagu. Obö ia: hana wa lö guna danö, ibe''e!', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 8, 'Ba itema linia da''ö, imane khönia: He Tua, akha so ia na zi döfi andre göi, irege uko''o danö ba mbörönia ba irege ulau goboula,', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 9, 'ma atö mowua ia dania, ba na lö''ö dania, ba obö ia.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 10, 'Ba mamahaö ia ba zekola, me luo sabato.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 11, 'Ba hiza ndra alawe si so bekhoe wökhö, meweleŵalu fakhe ae. Ba no aköi ia, tebai manö ifaöga ia.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 12, 'Ba me i''ila ia Yesu, ba humede ia khönia, imane: He alawe, yadöhö wökhöu,', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 13, 'ba itufa tanga ba i''anema''ö adölö, ba isuno Lowalangi.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 14, 'Ba humede zatua zekola andrö, mofönu ia, me mamadöhö fökhö Yesu ba zabato, imane ba niha sato: önö ngaluo zi tola mohalöŵö ita, ba ba da''ö mi''ae mifafadöhö''ö wökhömi, ba böi na luo sabato.[4]', '["MozII 20:9"]', NULL),
  (3393938, 'NT', 'Luka', 13, 15, 'Ba itema linia So''aya, imane: He samini tödö! Tenga dozi ami midudu zaŵimi, ba ma kalidemi, ba zinga naha gö, ba mi''ohe ba wamabadugö idanö khönia, na luo sabato?[5]', '["Faigi 14:5"]', NULL),
  (3393938, 'NT', 'Luka', 13, 16, 'Ba ma uwu Gaberahamo andre, nifesu Zatana, hiza, no meweleŵalu fakhe, hadia lö latoto''ö khönia wesu andrö ba luo sabato?', '["Faigi 14:5"]', NULL),
  (3393938, 'NT', 'Luka', 13, 17, 'Ba me iŵa''ö da''ö, ba oi aila zi fa''udu khönia andrö, ba oi omuso dödö niha sato, ba nilaunia andrö fefu, si no teturia.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 18, 'Ba imane:[6] Ha khö fakhili-khili mbanua Lowalangi andrö? Ha famaedo ube''e ia?', '["Ayati 18-21: Mat 12:31-34; Mar 4:30-33"]', NULL),
  (3393938, 'NT', 'Luka', 13, 19, 'Ba mbua lada fakhili-khili ia, nihalö niha, nitibo''önia ba kabu khönia, ba manöi ba tobali motöla, ba mangazuni wofo ba dalu mbanua ba ndrahania.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 20, 'Ba imane zui: Ha famaedo ube''e mbanua Lowalangi andrö?', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 21, 'Ba danömö roti fakhili-khili ia, nihalö ndra alawe, nifarukania ba zi tölu yöu hamo, irege aisö ma''afefu.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 22, 'Ba itöröi mbanua sebua, awö mbanua side-ide, mamahaö, isaŵa Yeruzalema. [7]', '["Mat 9:35"]', NULL),
  (3393938, 'NT', 'Luka', 13, 23, 'Ba so zanguma''ö khönia: He Tua, hadia, lö ato zauri dania ba mbanua furi?', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 24, 'Ba imane khöra: Miforege wangalui lala wanörö bawa göli sise-ise andrö. Ato sa, uŵa''ö khömi, zangalui dania fanörö, ba tebai.[8]', '["Mat 7:13,14; Fil 3:12"]', NULL),
  (3393938, 'NT', 'Luka', 13, 25, 'Na no maoso sa''ae zokhö omo andrö, na no ikusi mbawandruhö, ba na ibörötaigö baero so ami mamökö bawandruhö, na mimane: He So''aya, bokai khöma! ba itema limi, imane khömi: Lö u''ila ha niha ami, he moroi ami.[9]', '["Mat 25, 10-12"]', NULL),
  (3393938, 'NT', 'Luka', 13, 26, 'Awena dania mibörögö, mimane: No manga-manga ndra''aga, no mamadu idanö ndra''aga, ba zanehe ndra''ugö, ba no mamahaö ndra''ugö ba newali khöma.[10]', '["Mat 7, 22 b.t.","Mat 25:41"]', NULL),
  (3393938, 'NT', 'Luka', 13, 27, 'Ba imane dania: Uŵa''ö khömi, lö u''ila ha niha ami, he moroi ami. Miheta ami khögu, fefu zolau si lö atulö.[11]', '["Mat 7, 22 b.t.","Mat 25:41"]', NULL),
  (3393938, 'NT', 'Luka', 13, 28, 'Ba fege-ege dania ba da''ö ba fatangisa mboha, na mi''ila ndra Aberahamo, Iza''aki, Yakobo ba dozi sama''ele''ö andrö, ba mbanua Lowalangi andrö, ba na mi''ila nitibo''ö baero ami.[12]', '["Mat 8:11 b.t."]', NULL),
  (3393938, 'NT', 'Luka', 13, 29, 'Ba so dania moroi ba gatumbukha ba moroi ba gaekhula, moroi yöu ba moroi raya, ba manga ira ba mbanua Lowalangi andrö.', '["Mat 19:30"]', NULL),
  (3393938, 'NT', 'Luka', 13, 30, 'Ba hiza, so zi so furi, si möi föna dania, ba so zi so föna, si möi furi dania.[13]', '["Mat 19:30"]', NULL),
  (3393938, 'NT', 'Luka', 13, 31, 'Ba ba da''ö sibai, ba so warizaio ösa, lamane khönia: Heta''ö, ofanö ba da''e, ibunu''ö sa Herode.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 32, 'Ba imane khöra: Mi''ae miŵa''ö khö nasu gatua andrö: Hiza, ufofanö mbekhu ba ulau mamadöhö fökhö ma''ökhö ba mahemolu, ba ba zi dua wongi, ba urugi wondrege.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 33, 'Ba lö tola lö mukolido ma''ökhö ba mahemolu ba ba zi dua wongi, me no lö tola mate zama''ele''ö, na tenga ba Yeruzalema.', '[]', NULL),
  (3393938, 'NT', 'Luka', 13, 34, 'He Yeruzalema! He Yeruzalema! samunu sama''ele''ö, sanebu kara nifatenge khönia! ha me uga sa''ae u''owuloi mena''ö nonou, si mane sifagelo, na i''owuloi nononia barö gafi, ba lö sedöna ami.[14]', '["Mat 23:37 b.t."]', NULL),
  (3393938, 'NT', 'Luka', 13, 35, 'Hiza, lö''ö sa''ae nahami dania. Uŵa''ö khömi, lö''ö manö sa''ae mi''ila ndra''o, irege miŵa''ö dania: Ya''ahowu zi so andrö, ba döi Zo''aya![15]', '["Faigi 19, 37. 38. Mat 21, 9"]', NULL),
  (3393939, 'NT', 'Luka', 14, 1, 'Ba me möi ia ba nomo zalaŵa warizaio manga, ba luo sabato, ba so ira göi ba latarogö ia.[1]', '["Faigi 11:37,54"]', NULL),
  (3393939, 'NT', 'Luka', 14, 2, 'Ba hiza niha, samösa, sabao talu, fönania.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 3, 'Ba humede Yesu, imane ba zangila amakhoita andrö ba ba warizaio: Hadia, tola lafadöhö wökhö ba luo sabato, ma lö''ö? Ba lö hede-hedera.[2]', '["Faigi 6:9; Mat 12:10 b.t."]', NULL),
  (3393939, 'NT', 'Luka', 14, 4, 'Ba ibabaya zofökhö andrö, ifadöhö wökhönia, ba ifofanö.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 5, 'Ba humede ia khöra, imane: Ha niha ba khömi, na aekhu ba mba''a nononia, ba ma saŵinia, si lö i''anema''ö manöbi yaŵa ya''ia, na luo sabato?[3]', '["Faigi 13, 15"]', NULL),
  (3393939, 'NT', 'Luka', 14, 6, 'Ba tebai labu''a da''ö.[4]', '["Faigi 13, 17"]', NULL),
  (3393939, 'NT', 'Luka', 14, 7, 'Ba ilau gamaedola ba nikaoni andrö, me no ifaigi-faigi, wa lafahulö naha tanö si yaŵa, imane khöra:[5]', '["Mat 23, 6"]', NULL),
  (3393939, 'NT', 'Luka', 14, 8, 'Na so zogaoni ya''ugö ba walöŵa, ba böi dadao ba naha tanö si yaŵa, ma ta''ila so nikaoninia salaŵa moroi khöu,[6]', '["Amaed 25:6,7"]', NULL),
  (3393939, 'NT', 'Luka', 14, 9, 'ba na so zogaoni ya''ami, ba imane khöu: Fonaha da''e, ba ibörötaigö aila ndra''ugö wedadao tanö si tou sibai.', '["Amaed 25:6,7"]', NULL),
  (3393939, 'NT', 'Luka', 14, 10, 'Na lakaoni ndra''ugö, ba ae dadao ba naha tanö si tou sibai, ena''ö, na so zogaoni ya''ugö, ba imane khöu: Fa''ese''ö miyaŵa le! ba awena tefosumange ndra''ugö föna nawöu ba wemanga fefu.[7]', '["Faigi 18:14; Mat 23:12"]', NULL),
  (3393939, 'NT', 'Luka', 14, 11, 'Dozi sa, ha niha zamali''ö salaŵa ya''ia, da''ö ni''ide''i-de''ö, ba ha niha zangide-ide''ö ya''ia, da''ö nibe''e salaŵa.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 12, 'Ba imane göi ba zogaoni ya''ia andrö: Na ökaoni manga niha si hulö wongi, ba ma na owi, ba böi kaoni zi fahuwu khöu, ba ma talifusöu, ba ma si tenga bö''ömi, ba ma banuami so''ana''a, fa böi lakaoni göi ndra''ugö mangawuli, ba ötema zulö.[8]', '["Mat 5:46 b.t."]', NULL),
  (3393939, 'NT', 'Luka', 14, 13, 'Na fatome ndra''ugö, ba kaoni zi numana ba sagaböda ba sogombuyu-mbuyu ba sagau''a,[9]', '["Amaed 3:27; Yes 58:7","Mat 6:4; 25:35 b.t.)"]', NULL),
  (3393939, 'NT', 'Luka', 14, 14, 'ba ya''ahowu ndra''ugö, lö''ö sa khöra sulö khöu, ba tesulöni khöu ba wemaoso niha satulö andrö dania.[10]', '["Amaed 3:27; Yes 58:7","Mat 6:4; 25:35 b.t.)"]', NULL),
  (3393939, 'NT', 'Luka', 14, 15, 'Ba me irongo da''ö si samösa, awöra ba wemanga, ba imane khönia: Ya''ahowu zi manga ba mbanua Lowalangi andrö.[11]', '["Faigi 13:29; Fam 19:9"]', NULL),
  (3393939, 'NT', 'Luka', 14, 16, 'Ba imane khönia: So niha si fatome, owuloa sebua khönia, ato nikaoni.[12]', '["Mat 22:2 b.t."]', NULL),
  (3393939, 'NT', 'Luka', 14, 17, 'Ba ifatenge zawuyunia, me inötö gowuloa, ba wanguma''ö ba nikaoni andrö: Mi''aine, no awai.', '["Mat 22:2 b.t."]', NULL),
  (3393939, 'NT', 'Luka', 14, 18, 'Ba labörötaigö la''andrö aefa ira, ha sara dödö manö fefu. Imane khönia si föföna: So ni''öligu benua, ba lö tola lö möido mufaigi, u''andrö khöu, efa''ö ndra''o.', '["MozV 24:5; KorI 7:29-35"]', NULL),
  (3393939, 'NT', 'Luka', 14, 19, 'Ba imane si samösa: So ni''öligu öröbao, fulu nga''eu, ba möido mutandraigö; u''andrö khöu, efa''ö ndra''o.', '["MozV 24:5; KorI 7:29-35"]', NULL),
  (3393939, 'NT', 'Luka', 14, 20, 'Ba si samösa, ba imane: No mangowaludo, ba andrö tebai möi ndra''o.[13]', '["MozV 24:5; KorI 7:29-35"]', NULL),
  (3393939, 'NT', 'Luka', 14, 21, 'Ba ifuli ia sawuyu no mege, i''ombakha''ö da''ö khö zokhö ya''ia. Ba mofönu zatua baomo andrö ba imane khö zawuyunia andrö: Ta''i-ta''i ae ba newali misa, ba mbanua, ba fasao yomo ba da''e zi numana ba sagaböda ba sagau''a ba sogombuyu-mbuyu.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 22, 'Ba imane sawuyu andrö: He Tua, no u''o''ö niŵa''u ba so na naha.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 23, 'Ba imane tua andrö khö zawuyu: Ae ba lala ba ba zinga göli misa, ba farou dödöra ba we''amöi yomo, ena''ö afönu nomogu.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 24, 'Uŵa''ö sa khömi, samösa lö''ö dania si manga ba watomesa andrö khögu, niha si tohöna mukaoni andrö.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 25, 'Ba ato zi fao khönia ba lala niha, ba ibali''ö ia, imane khöra:', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 26, 'Na so zangondrasi ya''o, ba na tenga si fa''udu khö namania ba khö ninania ba khö wo''omonia ba ba ndraononia ba ba dalifusönia matua ba ba dalifusönia alawe ba ba nosonia na i, ba tebai nifahaögu ia.[14]', '["Faigi 18:29 b.t.; Mat 10:37 b.t.","Faigi 9, 23"]', NULL),
  (3393939, 'NT', 'Luka', 14, 27, 'Ha niha zi lö molu''i röfania, ba wolo''ö ya''o, ba tebai nifahaögu.[15]', '["Faigi 18:29 b.t.; Mat 10:37 b.t.","Faigi 9, 23"]', NULL),
  (3393939, 'NT', 'Luka', 14, 28, 'Ha niha sa ba khömi, sedöna mangotomosi malige, si lö dumadao ua mangerai balazo, na irugi, ba wamalua ya''ia?', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 29, 'Fa böi labörötaigö wango''aya ya''ia dozi samaigi, na no ifobörö, ba na tebai i''asiwai dania, fa böi lamane:', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 30, 'No ibörötaigö wotomo niha da''ö, ba tebai i''o''ozui.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 31, 'Ma ha niha razo sedöna manuwö razo bö''ö, si lö dumadao ua manguhuhuo''ö, na tola ifaondragö zamaondragö ya''ia, si dua wulu ngahönö niha, na ha fulu ngahönö khönia?', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 32, 'Ba na tebai, ba ifatenge zinenge, fatua aröu na zi samösa, i''andrö wangatulö.', '[]', NULL),
  (3393939, 'NT', 'Luka', 14, 33, 'Ba si manö göi ami fefu, ha niha zi lö mangositengagö fefu hadia ia zi so khönia, ba tebai nifahaögu ia.[16]', '["Mat 13:44"]', NULL),
  (3393939, 'NT', 'Luka', 14, 34, 'Si sökhi sa nasio, ba na taya wa''asi-asi nasio göi, ba hadia labe''e fangazökhi.[17]', '["Mat 9:50; Mat 5:13"]', NULL),
  (3393939, 'NT', 'Luka', 14, 35, 'Lö gunania ba danö ba lö''ö goi gunania fangatabö zinanö; tetibo''ö manö ia. Si so tögi dalinga ba wamondrongo, ba yamufondrondrongo!', '["Mat 9:50; Mat 5:13"]', NULL),
  (3393940, 'NT', 'Luka', 15, 1, 'Ba oi la''ondrasi ia sanema beo ba sebua horö, ba wamondrondrongo huhuonia.[1]', '["Faigi 5:29 b.t."]', NULL),
  (3393940, 'NT', 'Luka', 15, 2, 'Ba kumökö-kökö warizaio ba sangila amakhoita, lamane: Ifa''amöi khönia zebua horö da''ö ba orudu manga ia khöra. [2]', '["Faigi 7:34,39"]', NULL),
  (3393940, 'NT', 'Luka', 15, 3, 'Ba ilau khöra gamaedola andre, imane:', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 4, 'Ha niha ba khömi zi so biri-biri, otu nga''eu, ba na elungu zageu, hadia lö iröi ba danö si mate zi siŵa wulu a siŵa, ba i''o''ö zi sageu andrö, irege isöndra?[3]', '["Mat 18:12,13; Sin 119:176"]', NULL),
  (3393940, 'NT', 'Luka', 15, 5, 'Ba na no isöndra, ba i''angalisigö, omuso dödönia,[4]', '["Yes 40:11","Faigi 5:32"]', NULL),
  (3393940, 'NT', 'Luka', 15, 6, 'ba na irugi yomo, ba ikaoni zi fahuwu khönia, awö zi fahatö omo khönia, imane khöra: Akha omuso dödömi, awögu, me no usöndra mbiri-birigu andrö, si no elungu andrö?', '["Yes 40:11","Faigi 5:32"]', NULL),
  (3393940, 'NT', 'Luka', 15, 7, 'Uŵa''ö khömi, si manö göi wa''omuso dödö ba zorugo, ba niha, samalalini era-era, he ha samösa, moroi ba wa''omuso dödö ba zi siŵa wulu a siŵa, si lö moguna famalalini era-era.[5]', '["Yes 40:11","Faigi 5:32"]', NULL),
  (3393940, 'NT', 'Luka', 15, 8, 'Ba heza so ndra alawe, si so hua suku, fulu nga''örö, ba na aekhu zagörö khönia, hadia, lö itunu wandru, ba lö ibözini nomo, ba lö iforege wangalui, irege isöndra?', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 9, 'Ba na no isöndra, ba ikaoni ndra alawe si fahuwu khönia, awö zi fahatö omo khönia ba imane: Akha omuso dödömi, awögu, me no usöndra hua suku andrö, si no aekhu.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 10, 'Uŵa''ö khömi, si manö wa''omuso dödö ba zanehe mala''ika andrö, ba zorugo, ba niha, samalalini era-era, he ha samösa.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 11, 'Ba imane: So niha föna, si so ono matua, darua.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 12, 'Ba imane si akhi khö nama: He ama, be''e khögu dana khögu gana''a andrö. Ba ifaosa khöra zi so andrö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393940, 'NT', 'Luka', 15, 13, 'Ba lö ara furi ö, ba i''ozaragö fefu hadia ia siakhi nono andrö no mege, ilau mofanö, isaŵa danö saröu ba ba da''ö ihori gana''ania, manibo manö ia.[6]', '["Amaed 23:21"]', NULL),
  (3393940, 'NT', 'Luka', 15, 14, 'Ba me no ihori fefu hadia ia, ba itörö lofo sabölö-bölö danö andrö ma''asagörö, ba ibörötaigö lö balazo khönia.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 15, 'Ba möi ia mu''olembai niha ba danö andrö, samösa, manga gazi; ba ifatenge ia da''ö ba mbenuania, ba wokubaloi bawi.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 16, 'Ba omasi ia ifo''ösi dalunia lölö mbanio, ö mbawi, ba lö same''e khönia.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 17, 'Ba i''era-era tödönia ba imane: Ha wa''ato zangai halöŵö khö namagu, si lö ambö ö, ba ya''o, ba tekiko wa''olofo ba da''e.[7]', '["MozV 30:1 b.t.","Eser 9:6; Sin 51:6"]', NULL),
  (3393940, 'NT', 'Luka', 15, 18, 'Damaoso ndra''o, möido khö namagu ba umane khönia: He ama! no ufazökhi horö ba zorugo ba fönau, [8]', '["MozV 30:1 b.t.","Eser 9:6; Sin 51:6"]', NULL),
  (3393940, 'NT', 'Luka', 15, 19, 'tenga sa''ae si nangea laŵa''ö onou ndra''o, akha hulö zi manga gazi ndra''o khöu, samösa.', '["MozV 30:1 b.t.","Eser 9:6; Sin 51:6"]', NULL),
  (3393940, 'NT', 'Luka', 15, 20, 'Ba maoso ia, möi ia khö namania. Ba me aröu ia na, ba i''ila sa''ae ia amania, ba ahakhö dödö, fagohi ia, italagui mbagi, fa''ago bawa ia khönia.[9]', '["Yer 3:12"]', NULL),
  (3393940, 'NT', 'Luka', 15, 21, 'Ba imane khönia ono: He ama, no ufazökhi horö ba zorugo ba fönau, tenga sa''ae si nangea laŵa''ö onou ndra''o.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 22, 'Ba imane ama ba zawuyunia: Mihalö mbaru luo si sökhi andrö ba mibe''e barunia, mibe''e laeduru ba durunia ba badagahe ba gahenia,[10]', '["Yes 61:10; Fam 3:18","Efes 2:1-5"]', NULL),
  (3393940, 'NT', 'Luka', 15, 23, 'ba mihalö nono zaŵi nibula andrö, mitaba ba ta''a, akha omuso dödöda,', '["Yes 61:10; Fam 3:18","Efes 2:1-5"]', NULL),
  (3393940, 'NT', 'Luka', 15, 24, 'me no ifuli auri nonogu andre, si no mate, no elungu ia, ba no musöndra. Ba i börötaigö omuso dödöra.[11]', '["Yes 61:10; Fam 3:18","Efes 2:1-5"]', NULL),
  (3393940, 'NT', 'Luka', 15, 25, 'Ba no so ba nowi nononia si a''a. Ba me ifuli ia me ahatö ia ba nomo, ba irongo wanuno ba folaya.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 26, 'Ba humede ia khö zawuyu, isofu khönia hadia da''ö.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 27, 'Ba imane khönia da''ö: No so nakhiu andrö, ba no ifataba''ö nono zaŵi nibula andrö amau, me no mangawuli ia khönia, me lö si göna ia hadia ia.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 28, 'Ba mofönu ia ba lö edöna möi ia yomo. Ba möi tou namania, ifarou dödönia.', '["Amaed 29:3"]', NULL),
  (3393940, 'NT', 'Luka', 15, 29, 'Ba itema li namania, imane: Hiza, ha me uga fakhe enoniu ndra''o, ba lö urai usawö goroisamö, ba khögu lö örai öbe''e nono mbiri-biri, ena''ö omuso dödögu, awö zi fahuwu khögu.', '["Amaed 29:3"]', NULL),
  (3393940, 'NT', 'Luka', 15, 30, 'Ba me no so nonou andrö, si no mangohori ana''ania, awö zohorö-horö, ba no öfataba''ö khönia nono zaŵi nibula andrö.[12]', '["Amaed 29:3"]', NULL),
  (3393940, 'NT', 'Luka', 15, 31, 'Ba imane khönia: He onogu, si lö tebulö khögu ndra''ugö, ba hadia ia fefu zi so khögu ba khöu.', '[]', NULL),
  (3393940, 'NT', 'Luka', 15, 32, 'Ba somuso tödö sa ita ena''ö, sowua-wua tödö, me no ifuli auri nakhiu andrö, si no mate; no elungu ia, ba no musöndra.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 1, 'Ba imane göi ba nifahaönia: So niha so''ana''a föna, si so satua zangai halöŵö; ba te''adugö da''ö khönia, ihori gana''ania.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 2, 'Ba humede ia khönia, imane khönia: Hana wa si manö nirongogu khöu? Ombakha''ö he wisa wangaimö halöŵöu andrö, tebai sa''ae satua zangai halöŵö ndra''ugö.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 3, 'Ba imane dödönia satua zangai halöŵö andrö: He uwisa? ihetado sa satua zangai halöŵö sokhö ya''o; tebai mogo''o tanö ndra''o ba ailado mangandrö-ngandrö böli gögu.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 4, 'U''ila he uwisa, ena''ö lafa''amöido yomo khöra, na ahetado satua zangai halöŵö.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 5, 'Ba idozigö zo''ömö khö zokhö ya''ia, wehede khöra, ba imane ba zi föföna andrö: Ha wa''ebua gömöu khö zokhö ya''o?', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 6, 'Ba imane: Otu lauru fanikha. Ba imane khönia: Halö zuramö, dadao, ba ta''i-ta''i sura lima wulu.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 7, 'Ba imane ba zi samösa: Ba ya''ugö, ha wa''ebua gömöu? Ba imane: Otu ngaso''e fakhe. Imane khönia: Halö zuramö ba sura ŵalu ngafulu.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 8, 'Ba isuno sokhö zatua zangai halöŵö andrö, si lö atulö tödö, me no i''onekhesi. Me no onekhe nono niha guli danö andre, moroi ba nono haga andrö, ba khö nawöra andrö.[1]', '["Efes 5:8"]', NULL),
  (3393941, 'NT', 'Luka', 16, 9, 'Ba uŵa''ö khömi, mihuwu khömi niha, ana''a si lö atulö andrö, ena''ö lafa''amöi ami ba nose andrö ba mbanua furi, na no ahori ia. [2]', '["Faigi 12:33; Mat 25:35 b.t.","Faigi 19:17"]', NULL),
  (3393941, 'NT', 'Luka', 16, 10, 'Ha niha zi lö faröi ba wondrege zide-ide andrö, ba lö''ö göi faröi ba zebua, ba ha niha zofaya ba wondrege zide-ide andrö, ba mofaya göi ba zebua. [3]', '["Faigi 12:33; Mat 25:35 b.t.","Faigi 19:17"]', NULL),
  (3393941, 'NT', 'Luka', 16, 11, 'Ba na mofaya ami ba gana''a si lö atulö andrö, ba ha niha zame''e ba dangami si ndruhu andrö?', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 12, 'Ba na no mofaya mege ami ba zi tenga khömi, ba ha niha zame''e khömi si ndruhu khöda?', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 13, 'Na sangai halöŵö, ba samösa lö sangila faoma i''o''ö, na darua zangoni ya''ia; ma fa''udu ia ba zi samösa, ba i''omasi''ö zi samösa, ba ma i''o''ö li zi samösa, ba i''ositengagö zi samösa; tebai enoni Lowalangi ami, ba enoni gana''a göi.[4]', '["Mat 6:24"]', NULL),
  (3393941, 'NT', 'Luka', 16, 14, 'Ba larongo göi da''ö fefu farizaio andrö somasi ana''a, ba la''o''aya ia.[5]', '["Mat 23:14"]', NULL),
  (3393941, 'NT', 'Luka', 16, 15, 'Ba imane khöra: Ya''ami mibu''a-bu''a ba hulumi zi lö sökhi ba zanehe niha, ba Lowalangi zangila tödömi; hadia zebua ba niha, ba ni''ogorofi sa ba Lowalangi.[6]', '["Faigi 18:9 b.t."]', NULL),
  (3393941, 'NT', 'Luka', 16, 16, 'Irugi Yohane andrö, ba oroisa ba sama''ele''ö, ba i''otarai da''ö, ba teturiagö mbanua Lowalangi andrö, ba dozi lasöndragö ira bakha.[7]', '["Mat 11, 12. 13"]', NULL),
  (3393941, 'NT', 'Luka', 16, 17, 'Ba oföna adudu mbanua si yaŵa, awö danö, atö awu''a zambua tandra wamabali andrö, ba goroisa andrö.[8]', '["Faigi 21, 33. Mat 5, 18"]', NULL),
  (3393941, 'NT', 'Luka', 16, 18, 'Na so zanibo ngambatönia ba na ihalö danö bö''ö, ba sohorö da''ö. Ba ha niha zangai nitibo''ö ndra matua, ba sohorö.[9]', '["Mat 5, 32; 19, 8. 9"]', NULL),
  (3393941, 'NT', 'Luka', 16, 19, 'Ba so me föna niha so''ana''a, sobaru baru luo manö ba muko si sökhi sibai, ero ma''ökhö i''omusoi''ö manö dödönia, lö ambö-ambö hadia ia.[10]', '["Yoh 5:5; YohI 2:16"]', NULL),
  (3393941, 'NT', 'Luka', 16, 20, 'Ba so göi zi numana, Lazaro döi, nitou''ö barö mbatönia, oi gigimö.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 21, 'Ba omasi da''ö ihalö önia zi lö a''oi ba wemanga zo''ana''a andrö. Ba so göi nasu, lafela-felai gigimönia andrö.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 22, 'Ba ha samuza ma''ökhö, ba mate zi numana andrö, ha la''ohe ia ba gaheta Gaberahamo mala''ika.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 23, 'Ba ba mbanua tou, ba ifaöga hörönia, me no i''ila wa''afökhö, ba i''ila Gaberahamo, ba zaröu, awö Lazaro no mege, ba gahetania.', '["Heb 1:14; Mat 8:11; Yoh 21:23 b.t.; Sin 73"]', NULL),
  (3393941, 'NT', 'Luka', 16, 24, 'Ba mu''ao ia, imane: He Tuagu, Aberahamo! hakhösi tödö ndra''o, ba fatenge Lazaro andrö, ena''ö i''ungugö zara nuwu durunia ba nidanö, ba i''okafui lelagu, me no afökhö khögu ba hola-hola galitö andre. [12]', '["Mar 3:43 b.t."]', NULL),
  (3393941, 'NT', 'Luka', 16, 25, 'Ba imane Aberahamo: He onogu, törö-törö tödöu, wa no ötema zi sökhi andrö, tana khöu, götö we''asomö ba guli danö, ba si manö göi wa no itema zi lö sökhi andrö Lazaro; ba iada''e, ba terara dödönia ba da''e, ba khöu, ba fa''afökhö.[13]', '["Sin 17:14,15"]', NULL),
  (3393941, 'NT', 'Luka', 16, 26, 'Ba baero ö fefu, ba no mu''a''aro''ö goho-koho sebua ba gotaluada, ena''ö tebai latörö sedöna möi ba khömi, soroi da''e, ba tebai göi zi otarai moroi sa khömi, si möi ba da''e ena''ö.', '["Sin 17:14,15"]', NULL),
  (3393941, 'NT', 'Luka', 16, 27, 'Ba imane: Ba u''andrö khöu Tua, ena''ö öfatenge ia ba nomo namagu, so na sa dalifusögu, dalima,', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 28, 'ena''ö ifaduhu''ö khöra, fa böi möi ira göi ba naha wa''afökhö andre.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 29, 'Ba imane Aberahamo: So khöra zura Moze ba sura zama''ele''ö andrö; ndramufondrondrongo da''ö. [14]', '["Yes 8:20; Yoh 5:39"]', NULL),
  (3393941, 'NT', 'Luka', 16, 30, 'Ba imane: Ai lö''ö Tuagu Aberahamo, ha na möi khöra zi otarai zi no mate, awena lafalalini gera-erara.', '[]', NULL),
  (3393941, 'NT', 'Luka', 16, 31, 'Ba imane khönia: Na lö lafondrondrongo li Moze, awö li zama''ele''ö, ba lö''ö göi mamati ira, na so zi maoso moroi ba ngai zi mate.[15]', '["Yoh 11:44,53; 12:9,10"]', NULL),
  (3393942, 'NT', 'Luka', 17, 1, 'Ba imane ba nifahaönia: Tebai sa lö fangala andrö, ba alai zamobörö ya''ia![1]', '["Mat 18:6,7"]', NULL),
  (3393942, 'NT', 'Luka', 17, 2, 'Mohare ia, na labe''e gowe zalaŵa ba mbaginia ena''ö, ba na lahanigö ia ba nasi, moroi i''alani zamösa zide-ide andrö.', '["Mat 18:6,7"]', NULL),
  (3393942, 'NT', 'Luka', 17, 3, 'Mifaigi-faigi dödömi! Na mosala dalifusöu, ba tegu ia, ba na mangesa dödönia, ba efa''ö khönia.[2]', '["Mat 18:15 b.t.","Mat 18:21,22"]', NULL),
  (3393942, 'NT', 'Luka', 17, 4, 'Ba he mewitu ma''ökhö mosala ia khöu, ba na mewitu ifuli ia khöu, ba imane: Mangesa dödögu; ba efa''ö khönia.[3]', '["Mat 18:15 b.t.","Mat 18:21,22"]', NULL),
  (3393942, 'NT', 'Luka', 17, 5, 'Ba lamane sinenge andrö khö Zo''aya: Dou''ö wamatima![4]', '["Mar 9:24"]', NULL),
  (3393942, 'NT', 'Luka', 17, 6, 'Ba imane So''aya: Na so khömi wamati, ezai si samba ngawua bua lada, ena''ö, ba miŵa''ö ena''ö ba marafala andrö: Deha''ö ba fawu''a''ö, tanö''ö ba nasi, ba ifondrondrongo limi.[5]', '["Mat 17:20"]', NULL),
  (3393942, 'NT', 'Luka', 17, 7, 'Ba ha niha ba khömi zi so sawuyu, samaku-maku ba laza, ba ma sokubaloi urifönia, hadia, na i''otarai nowi, hadia, imane khönia; Dölö''ö ba da''e, lau manga!', '["Faigi 12:35,37"]', NULL),
  (3393942, 'NT', 'Luka', 17, 8, 'Hadia, lö imane; Asiwai gögu, ba olembe ba halö-halö khögu hadia ia, irege aefa manga ndra''o, ba awena dania manga ndra''ugö?[6]', '["Faigi 12:35,37"]', NULL),
  (3393942, 'NT', 'Luka', 17, 9, 'Hadia, i''andrö saoha gölö khö zawuyu andrö dania, me no i''o''ö hadia niŵa''ö khönia?', '["Faigi 12:35,37"]', NULL),
  (3393942, 'NT', 'Luka', 17, 10, 'Si manö göi ami, na no ahori mi''o''ö hadia ia niŵa''ö khömi, ba mimane: Sawuyu si lö guna ndra''aga, hadia gömöma halöŵö, da''ö nihalöma.[7]', '["Yoh 22:2,3; 41:2"]', NULL),
  (3393942, 'NT', 'Luka', 17, 11, 'Ba me isaŵa Yeruzalema, ba itörö dalu danö Zamaria ba talu danö Galilaia.', '[]', NULL),
  (3393942, 'NT', 'Luka', 17, 12, 'Ba irugi mbanua side-ide, ba lala, ba falukha ia zobou auri, ira matua, dafulu; lö lahatö''ö ira.[8]', '["MozIII 13:45,46"]', NULL),
  (3393942, 'NT', 'Luka', 17, 13, 'Ba mu''ao ira, lamane: He Yesu, samahaö, hakhösi tödö ndra''aga!', '[]', NULL),
  (3393942, 'NT', 'Luka', 17, 14, 'Ba me i''ila ira, ba imane khöra: Mi''ae mi''oroma''ö ami ba gere. Ba tobali barö we''amöi andrö, ba döhö wökhöra.[9]', '["Faigi 5:13,14; MozIII 14:2 b.t."]', NULL),
  (3393942, 'NT', 'Luka', 17, 15, 'Ba si samösa, me i''ila, no döhö, ba ifuli ia, i''ebua''ö linia wanuno Lowalangi,', '["Luk 10:33"]', NULL),
  (3393942, 'NT', 'Luka', 17, 16, 'ituhi danö fönania, wangandrö saoha gölö khönia; ba Dawa Zamaria da''ö.[10]', '["Luk 10:33"]', NULL),
  (3393942, 'NT', 'Luka', 17, 17, 'Ba humede Yesu, imane: Hadia, tenga dafulu ira zi döhö fökhö? heza so zi dasiŵa?', '[]', NULL),
  (3393942, 'NT', 'Luka', 17, 18, 'Hadia, lö ni''ilada zangawuli, ba wamosumange Lowalangi, baero niha bö''ö andrö?', '[]', NULL),
  (3393942, 'NT', 'Luka', 17, 19, 'Ba imane khönia: Faoso, fuli''ö, no i''orifi''ö famatimö andrö.[11]', '["Faigi 8:48"]', NULL),
  (3393942, 'NT', 'Luka', 17, 20, 'Ba me lasofu khönia farizaio, ha wa''ara alua mbanua Lowalangi andrö, ba itema lira, imane: Na alua mbanua Lowalangi andrö, ba lö ebua nini-nini;[12]', '["Faigi 19:11; HalZin 1:6; Yoh 18:36","Rom 14:17"]', NULL),
  (3393942, 'NT', 'Luka', 17, 21, 'Lö''ö sa laŵa''ö dania: Ya''e ia, ba ma: hiza, ba da''ö. Hiza sa, banua Lowalangi andrö, ba no so ba khömi.[13]', '["Faigi 19:11; HalZin 1:6; Yoh 18:36","Rom 14:17"]', NULL),
  (3393942, 'NT', 'Luka', 17, 22, 'Ba imane khö ndra nifahaö: Irugi luo dania, ba omasi ami mi''ila mbaŵa Nono Niha andrö, mato ma''ökhö, ba lö falukha mi''ila.', '["Faigi 21:8; Mat 24:23-27"]', NULL),
  (3393942, 'NT', 'Luka', 17, 23, 'Ba lamane khömi dania: Hiza! Ya''e! Ba böi mi''ae''e, böi mi''o''ö. [14]', '["Faigi 21:8; Mat 24:23-27"]', NULL),
  (3393942, 'NT', 'Luka', 17, 24, 'Hulö si mane gari mbanua andrö sa, si otarai wondrege mbanua, sihaga irugi wondrege tanö sa, si manö göi Nono Niha dania, na baŵania andrö.', '["Mat 16:21"]', NULL),
  (3393942, 'NT', 'Luka', 17, 25, 'Ba lö tola lö oya itaha ua famakao ba latibo''ö ia niha andre.[15]', '["Mat 16:21"]', NULL),
  (3393942, 'NT', 'Luka', 17, 26, 'Ba hulö si mane me luo Noakhi, si manö göi dania na baŵa Nono Niha andrö.[16]', '["Mat 24, 36"]', NULL),
  (3393942, 'NT', 'Luka', 17, 27, 'Manga-manga ira, labadu-badu hadia ia, mangowalu ira ba möi nihalö, irugi luo andrö, me möi yaŵa Noakhi ba nowo andrö; ba so wa''anönö danö andrö ba tekiko ira fefu ibe''e.', '["Mat 24, 36"]', NULL),
  (3393942, 'NT', 'Luka', 17, 28, 'Hulö si mane me luo Loti: manga-manga ira, mamadu-madu hadia ia, mamawa-mawa hadia ia ba mowöli-wöli, mananö-nanö sinanö ira ba mangotomo-tomosi omo.[17]', '["MozI 18:20; 19:24 b.t."]', NULL),
  (3393942, 'NT', 'Luka', 17, 29, 'Ba me luo iheta ia Loti ba Zodoma andrö, ba moteu alitö ba talö balera moroi ba mbanua si yaŵa ba ifakiko ira fefu.', '["MozI 18:20; 19:24 b.t."]', NULL),
  (3393942, 'NT', 'Luka', 17, 30, 'Si manö göi dania, na luo to''ele Nono Niha.', '["Mat 24:17,18","MozI 19:26)"]', NULL),
  (3393942, 'NT', 'Luka', 17, 31, 'Ba na luo da''ö dania, ba na so zi so yaŵa ba dete nomo, ba yomo so gama-gamania, ba böi yamöi tou, ba wangai ya''ia, ba si so ba nowi, ba si manö göi, böi yamufuli ia furi.[18]', '["Mat 24:17,18","MozI 19:26)"]', NULL),
  (3393942, 'NT', 'Luka', 17, 32, 'Mitörö-törö tödömi wo''omo Loti andrö![19]', '["Mat 24:17,18","MozI 19:26)"]', NULL),
  (3393942, 'NT', 'Luka', 17, 33, 'Ha niha zangalui nosonia, khönia aetu ia, ba ha niha zaetu noso, da''ö zangorifi ya''ia.[20]', '["Faigi 9:24"]', NULL),
  (3393942, 'NT', 'Luka', 17, 34, 'Uŵa''ö khömi, darua zi faedo mörö, na bongi da''ö, samösa ni''ohe, ba si samösa, ba niröi.[21]', '["Mat 24:40 b.t."]', NULL),
  (3393942, 'NT', 'Luka', 17, 35, 'Darua zorudu wanutu fakhe, samösa ni''ohe, ba si samösa, ba niröi.', '["Mat 24:40 b.t."]', NULL),
  (3393942, 'NT', 'Luka', 17, 36, 'Darua zi so ba nowi, samösa ni''ohe, ba si samösa, ba niröi.', '["Mat 24:40 b.t."]', NULL),
  (3393942, 'NT', 'Luka', 17, 37, 'Ba latema linia, lamane khönia: Heza, Tua? Ba imane khöra: Ba zi so amatela, ba da''ö göi owulo moyo.[22]', '["Mat 24:28"]', NULL),
  (3393943, 'NT', 'Luka', 18, 1, 'Ba ilau khöra gamaedola, ba wangoroma''ö wa lö tola lö fadoro wangandrö, wa böi atage, [1]', '["Rom 12:12; Efes 6:18; Kol 4:2; TesI 1:5,17"]', NULL),
  (3393943, 'NT', 'Luka', 18, 2, 'imane:', '["Rom 12:12; Efes 6:18; Kol 4:2; TesI 1:5,17"]', NULL),
  (3393943, 'NT', 'Luka', 18, 3, 'Ba so lakha mbanua ba mbanua andrö, ba möi da''ö khönia, imane: Tolodo ba zi fa''udu khögu andrö.[2]', '["MozII 22:22 b.t.; Yes 1:17"]', NULL),
  (3393943, 'NT', 'Luka', 18, 4, 'Ba ara lö edöna ia. Ba dania, ba imane dödönia: He lö u''ata''ufi Lowalangi ba he lö ba dödögu hadia niŵa''ö niha,', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 5, 'ba edönado zui utolo lakha mbanua andrö, me ifakao ndra''o, fa böi afökhö högögu ibe''e, na lö ibato-bato we''amöi.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 6, 'Ba imane So''aya: Mifondrondrongo, hadia niŵa''ö zanguhuku andrö, si lö atulö tödö.', '["Sin 55:17,18","Sin 145:18,19"]', NULL),
  (3393943, 'NT', 'Luka', 18, 7, 'Ba hadia, lö itolo Lowalangi nitutuyunia andrö, si''angaröfi li ya''ia bongi ma''ökhö; ba hadia arörö ia ba khöra?[3]', '["Sin 55:17,18","Sin 145:18,19"]', NULL),
  (3393943, 'NT', 'Luka', 18, 8, 'Uŵa''ö khömi, itolo ira, lö ara sibai. Ba na so Nono Niha, hadia falukha ia maö wamati ba guli danö?[4]', '["Sin 55:17,18","Sin 145:18,19"]', NULL),
  (3393943, 'NT', 'Luka', 18, 9, 'Ba so ösa zanguma''ö tödöra satulö ira, abe''e dödöra ba khöra, ba la''ositengagö danö bö''ö, ba ilau göi gamaedola ba da''ö, imane:[5]', '["Faigi 16:15"]', NULL),
  (3393943, 'NT', 'Luka', 18, 10, 'Darua zi möi miyaŵa ba gosali, niha, farizaio zi samösa ba sanema beo zi samösa.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 11, 'So warizaio andrö, imane wangandrö: He Lowalangi, u''andrö saoha gölö khöu, me tenga si mane niha bö''ö ndra''odo, tenga si mane sorabu, ba tenga si mane sohorö, ba tenga göi si mane sanema beo andrö.[6]', '["Yes 58:2 b.t.","Faigi 11:42; Mat 9:14"]', NULL),
  (3393943, 'NT', 'Luka', 18, 12, 'Mendrua zi samigu mamoni ba gö ndra''o, ba ube''e zambua ni''ofulu zi so khögu fefu.[7]', '["Yes 58:2 b.t.","Faigi 11:42; Mat 9:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393943, 'NT', 'Luka', 18, 13, 'Ba sanema beo andrö, ba no so ba zaröu, lö''ö göi edöna ia ifaöga hörönia miyaŵa ba zorugo, ibözi manö dötö''ania, imane: He Lowalangi, hakhösi tödö ndra''o, si no ebua horö.[8]', '["Eser 9:6"]', NULL),
  (3393943, 'NT', 'Luka', 18, 14, 'Uŵa''ö khömi, satulö da''ö, me mangawuli ia mitou ba nomonia, moroi ba zi samösa. Dozi sa, ha niha zangebua ya''ia, da''ö ni''ide-ide''ö, ba ha niha zangide-ide''ö ya''ia, da''ö nibe''e sebua.[9]', '["Faigi 14:11"]', NULL),
  (3393943, 'NT', 'Luka', 18, 15, 'Ba la''ohe göi khönia ndraono sawuyu,[10] ena''ö itufa ira tanga. Ba me la''ila da''ö nifahaö, ba lategu ira.', '["Ayati 15-17: Mat 19:13-15; Mar 10:13-16"]', NULL),
  (3393943, 'NT', 'Luka', 18, 16, 'Ba humede khöra Yesu, imane: Mifa''amöi khögu ndraono, böi mitenaŵa; ba zi manö sa mbanua Lowalangi andrö.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 17, 'Si ndruhu niŵa''ögu khömi, si tenga hulö ndraono, wanema banua Lowalangi andrö, ba tebai manö möi ia bakha.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 18, 'Ba isofu khönia salaŵa, imane:[11] He samahaö si sökhi, he uwisa, ena''ö usöndra wa''auri andrö, si lö aetu?', '["Ayati 18-23: Mat 19:16-22; Mar 10:17-22"]', NULL),
  (3393943, 'NT', 'Luka', 18, 19, 'Ba imane khönia Yesu: Hana wa öŵa''ö, si sökhi ndra''o? Lö si sökhi, baero Lowalangi, si ha samösa.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 20, 'Oroisa andrö, ba no ö''ila: böi ohorö, böi ange''e, böi anagö, böi böbögö zi lö duhu, fosumange namau, awö ninau.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 21, 'Ba imane: No ahori u''o''ö da''ö, i''otarai iraono ndra''o.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 22, 'Ba me irongo da''ö Yesu, ba imane khönia: Sambalö na zi lö''ö khöu. Tema amawa fefu hadia ia zi so khöu, ba faosa ba zi numana mbölinia, ba so khöu girö-girö ba zorugo, ba tabu o''ö ndra''o.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 23, 'Ba me irongo da''ö, ba abu sibai dödönia; no sebua sibai ana''a ia.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 24, 'Ba me inehegö ia Yesu,[12] ba imane: Afökhö sibai ba zo''ana''a, wogamö banua Lowalangi andrö.', '["Ayati 24-30: Mat 19:23-29; Mar 10:23-30"]', NULL),
  (3393943, 'NT', 'Luka', 18, 25, 'Aoha na na i itörö dögi walölöŵa kudo, moroi möi ba mbanua Lowalangi andrö zo''ana''a.', '["Ayati 24-30: Mat 19:23-29; Mar 10:23-30"]', NULL),
  (3393943, 'NT', 'Luka', 18, 26, 'Ba lamane samondrongo da''ö: Ba ha niha zanöndra fa''auri?', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 27, 'Ba imane: Si tebai ba niha, ba tola ba Lowalangi.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 28, 'Ba imane Fetero: Hiza, ya''aga, ba no maröi manö zi so khöma, ba no ma''o''ö ndra''ugö.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 29, 'Ba imane khöra: Si ndruhu niŵa''ögu khömi, samösa lö''ö, si no mondröi omo, ba ma soroiyomo, ba ma talifusö, ba ma ira amania, ba ma ono, na börö mbanua Lowalangi andrö,', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 30, 'si lö manema ya''ia mangawuli, oya winaeta ba götö da''e, ba fa''auri si lö aetu ba götö dania.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 31, 'Ba i''ohe awönia zi felendrua,[13] ba imane khöra: Hiza, möi ita misi yaŵa ba Yeruzalema, ba itörö dania fefu nisura zama''ele''ö andrö, ba khö Nono Niha.', '["Ayati 31-34: Mat 20:17-19; Mar 10:32-34"]', NULL),
  (3393943, 'NT', 'Luka', 18, 32, 'Labe''e sa ia ba danga niha baero dania, ba la''o''aya ba la''osiwawöi ba ladidiloi,', '["Ayati 31-34: Mat 20:17-19; Mar 10:32-34"]', NULL),
  (3393943, 'NT', 'Luka', 18, 33, 'ba na no labözi-bözi dania, ba labunu, ba tölu ngaluo, ba maoso ia, ifuli auri.', '["Ayati 31-34: Mat 20:17-19; Mar 10:32-34"]', NULL),
  (3393943, 'NT', 'Luka', 18, 34, 'Ba ma''ifu lö aboto ba dödöra da''ö, si tobini khöra daroma li andrö ba lö la''ila hadia niŵa''ö. [14]', '["Faigi 9:45; Mar 9:32"]', NULL),
  (3393943, 'NT', 'Luka', 18, 35, 'Ba me no ahatö ia ba Yerikho,[15] ba so zidadao ba zinga lala, niha sau''a, mangandrö-ngandrö böli gönia.', '["Ayati 35-43: Mat 20:29-34; Mar 10:40-52"]', NULL),
  (3393943, 'NT', 'Luka', 18, 36, 'Ba irongo niha sanörö, ba izofu-zofu hadia da''ö.', '["Ayati 35-43: Mat 20:29-34; Mar 10:40-52"]', NULL),
  (3393943, 'NT', 'Luka', 18, 37, 'Ba la''ombakha''ö khönia, itörö Yesu, banua Nazareta andrö.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 38, 'Ba mu''ao ia imane: He Yesu, ma''uwu Dawido, hakhösi tödö ndra''o!', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 39, 'Ba latenaŵa ia si so föna, ena''ö ibato.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 40, 'Ba ibadugö ia Yesu, iŵa''ö, la''ohe khönia. Ba me no ahatö ia, ba isofu khönia:', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 41, 'Hadia zomasi''ö, he uwisa khöu?', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 42, 'Ba imane khönia Yesu; Yagö mu''ila zui niha! Noa i''orifi ndra''ugö famatimö andrö.', '[]', NULL),
  (3393943, 'NT', 'Luka', 18, 43, 'Ba i''anema''ö ifuli i''ila niha, ba i''o''ö, isuno Lowalangi. Ba lasuno Lowalangi niha fefu, sangila da''ö.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 1, 'Be möi ia miyomo ba Yerikho, itörö mbanua.[1]', '["Faigi 18:35"]', NULL),
  (3393944, 'NT', 'Luka', 19, 2, 'Ba hiza niha, Sakaio döi, satua zanema beo, so''ana''a.', '["Yoh 12:21"]', NULL),
  (3393944, 'NT', 'Luka', 19, 3, 'I''alui wamaigi Yesu, ha niha ia, ba tebai, ba wa''ato niha, me no side-ide niha ia.[2]', '["Yoh 12:21"]', NULL),
  (3393944, 'NT', 'Luka', 19, 4, 'Ba itari-tari, fagohi, i''anöisi döla marafala, ena''ö i''ila, me lalania dania da''ö.', '["Yoh 12:21"]', NULL),
  (3393944, 'NT', 'Luka', 19, 5, 'Ba me irugi da''ö Yesu, ba ifaöga hörönia, imane khönia: He Sakaio, ta''i-ta''i, ae tou, lö''ö sa tola lö möido yomo khöu, tomeu, ma''ökhö.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 6, 'Ba i''alio''ö mitou, i''ohe yomo Yesu, omuso dödönia.[3]', '["Yoh 1:12"]', NULL),
  (3393944, 'NT', 'Luka', 19, 7, 'Ba me la''ila da''ö, ba kumökö-kökö ira fefu, lamane: No möi ia tome niha sebua horö,[4]', '["Faigi 15:2; Mat 9:11"]', NULL),
  (3393944, 'NT', 'Luka', 19, 8, 'Ba so Zakaio andrö, imane khö Zo''aya: Hiza, ube''e ba zi numana zi matonga zi so khögu, Tua, ba na so nilimogu niha, hadia ia, ba mendrua ufabali wamuli.[5]', '["MozII 22:1,9; Hes 33:14,15"]', NULL),
  (3393944, 'NT', 'Luka', 19, 9, 'Ba imane khönia Yesu: No falukha wangorifi zi samba omo andre ma''ökhö; ma''uwu Gaberahamo sa atö ia göi.[6]', '["Gal 3:7","Faigi 15:4; Mat 18:11"]', NULL),
  (3393944, 'NT', 'Luka', 19, 10, 'Ba da''ö sa möi Nono Niha, ba wangalui si no elungu ba ba wangorifi ya''ia.[7]', '["Gal 3:7","Faigi 15:4; Mat 18:11"]', NULL),
  (3393944, 'NT', 'Luka', 19, 11, 'Ba me no larongo da''ö,[8] ba ilau na gamaedola, me no ahatö ia ba Yeruzalema, ba me lawai i''anema''ö to''ele mbanua Lowalangi andrö.[9]', '["Ayati 11-28: Mat 25:14-30","Faigi 17:20"]', NULL),
  (3393944, 'NT', 'Luka', 19, 12, 'Imane sa''ae: So zofanö, salaŵa, isaŵa danö saröu, ena''ö tobali tuhe nöri ia ba da''ö, ba mangawuli.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 13, 'Ba humede ia ba zawuyunia, dafulu, ibe''e khöra zi fulu balaki, ba imane khöra: Milau ba waniaga, irege mangawulido.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 14, 'Ba no fatiu dödö mbanuania khönia, ba lafatenge zinenge, solo''ö ya''ia, lamane: Lö edönaga salaŵama da''ö.[10]', '["Yoh 1:11"]', NULL),
  (3393944, 'NT', 'Luka', 19, 15, 'Ba me mangawuli ia, me no tobali tuhe nöri ia si yefo, ba ifakaoni''ö zawuyunia andrö, nibe''enia ana''a andrö, ena''ö irongo, he lawisa wolau.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 16, 'Ba so zi föföna, imane: He Tua, fulu balaki hare zi samba fondruyu andrö khöu.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 17, 'Ba imane khönia: Lau, sawuyu si sökhi! Me lö si faröi ndra''ugö ba zi lö oya-oya, ba yaso barö mbawau zi fulu banua.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 18, 'Ba so wanete da''ö, imane: Si sambua fondruyu andrö khöu, Tua, ba no mohare, lima balaki.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 19, 'Ba imane göi ba da''ö: Ba ya''ugö göi, yaso barö mbawau zi lima banua.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 20, 'Ba so zi samösa, imane: Ya''e zi sambua fondruyu khöu, Tua, no u''irö''ö ba zaefu tanga.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 21, 'Noa sa ata''udo ndra''ugö, me no sabe''e huku ndra''ugö, me öhalö zi tenga nibe''eu, ba me öbasi zi tenga nitarumö.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 22, 'Imane khönia: Moroi ba mbeweu uhuku ndra''ugö, sawuyu si lö sökhi. Hadia, no ö''ila sabe''e huku ndra''odo, mangaido si tenga nibe''egu, ba mamasido si tenga nitarugu?[11]', '["Mat 12:37"]', NULL),
  (3393944, 'NT', 'Luka', 19, 23, 'Ba hana wa lö öbe''e ba zamalali gana''agu andrö? Ba ya''o, na sodo, ba uhalö fabaya hare, ena''ö.', '["Mat 12:37"]', NULL),
  (3393944, 'NT', 'Luka', 19, 24, 'Ba imane ba zi so ba da''ö: Mihalö khönia zi samba fondruyu andrö, ba mibe''e ba zi so si fulu balaki.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 25, 'Ba lamane khönia: He Tua, ba no fulu balaki khönia.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 26, 'Uŵa''ö khömi, dozi ba zi no so, ba tebe''e, ba khö zi lö''ö, ba lahalö göi zi no so khönia.[12]', '["Faigi 8:18"]', NULL),
  (3393944, 'NT', 'Luka', 19, 27, 'Ba si fatiu tödö andrö khögu, si lö edöna salaŵara ndra''odo, ba mi''ohe ba da''e, ba mibunu ira fönagu.', '["Faigi 8:18"]', NULL),
  (3393944, 'NT', 'Luka', 19, 28, 'Ba me no iŵa''ö da''ö, ba mofanö ia, isaŵa misi yaŵa Yeruzalema.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 29, 'Ba me no ahatö ia ba Mbetifage[13] ba ba Mbetania ba gahe hili andrö, sotöi hili wanikha, ba ifatenge nifahaönia, darua,', '["Ayati 29-40: Mat 21:1-11; Mar 11:1-10; Yoh 12:1,12-19","Faigi 22:11 b.t."]', NULL),
  (3393944, 'NT', 'Luka', 19, 30, 'imane: Mi''ae ba mbanua side-ide andrö, fönami, ba na mirugi yomo ba da''ö, ba mi''ila nono galide ni''amöhögö, si lö irai la''okudo niha; ba mitoto''ö wesu, ba mi''ohe ia.', '["Ayati 29-40: Mat 21:1-11; Mar 11:1-10; Yoh 12:1,12-19","Faigi 22:11 b.t."]', NULL),
  (3393944, 'NT', 'Luka', 19, 31, 'Ba na so zanofu khömi: Hana wa mitoto''ö? ba mimane: Moguna khö Dua.[14]', '["Ayati 29-40: Mat 21:1-11; Mar 11:1-10; Yoh 12:1,12-19","Faigi 22:11 b.t."]', NULL),
  (3393944, 'NT', 'Luka', 19, 32, 'Ba möi zinenge andrö, ba itörö niŵa''önia khöra.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 33, 'Ba me latoto''ö wesu nono galide andrö, ba lamane khöra sokhö ya''ia: Hadia wa mitoto''ö wesu nono galide andrö?', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 34, 'Ba lamane: Moguna khö Dua.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 35, 'Ba la''ohe khö Yesu, labe''e ba hulu nono galide andrö nukhara, ba lafakudo Yesu yaŵa.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 36, 'Ba me mofanö ia, ba labologö nukhara ba lala.', '["Faigi 2:14"]', NULL),
  (3393944, 'NT', 'Luka', 19, 37, 'Ba me arakha irugi zanue hili wanikha andrö, ba labörötaigö nifahaö fefu lasuno Lowalangi, omuso dödöra, la''ebua''ö lira, börö wa''abölö andrö fefu, ni''ilara lamane:', '["Faigi 2:14"]', NULL),
  (3393944, 'NT', 'Luka', 19, 38, 'Ya''ahowu razo andrö, ba döi Zo''aya, fa''ohahau dödö ba zorugo ba sumange ba mbanua si yaŵa![15]', '["Faigi 2:14"]', NULL),
  (3393944, 'NT', 'Luka', 19, 39, 'Ba so warizaio ösa, awö niha sato, ba lamane khönia: He samahaö, tenaŵa nifahaömö andrö.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 40, 'Ba itema lira, imane: Uŵa''ö khömi, na lö''ö sa''ae hede-hede da''ö, ba mu''ao gara.', '[]', NULL),
  (3393944, 'NT', 'Luka', 19, 41, 'Ba me ahatö ia, me i''ila mbanua, ba me''e ia ba khönia, imane:[16]', '["Yoh 11:35","Faigi 23:28 b.t.; MozV 28:52 b.t.; Yes 22:2,3; Yer 6:6; Sakh 14:2","Faigi 21:6; Mat 24:2"]', NULL),
  (3393944, 'NT', 'Luka', 19, 42, 'Ena''ö na aboto ba dödöu göi, ba mbaŵamö andre, hadia wangohahau dödöu, ba iya''e, ba no tobini ia khöu!', '["Yoh 11:35","Faigi 23:28 b.t.; MozV 28:52 b.t.; Yes 22:2,3; Yer 6:6; Sakh 14:2","Faigi 21:6; Mat 24:2"]', NULL),
  (3393944, 'NT', 'Luka', 19, 43, 'Irugi sa dania baŵa khöu, ba lakölini ndra''ugö emaliu ba lafasui ndra''ugö, ba laforege, fasui manö.[17]', '["Yoh 11:35","Faigi 23:28 b.t.; MozV 28:52 b.t.; Yes 22:2,3; Yer 6:6; Sakh 14:2","Faigi 21:6; Mat 24:2"]', NULL),
  (3393944, 'NT', 'Luka', 19, 44, 'Ba larasa ndra''ugö, fabaya onou, awöu, ba lö tosai khöu zi dombua kara, si falaete, labe''e, börö wa lö saboto ba dödöu mbaŵa wamaigi ya''ugö andrö.[18]', '["Yoh 11:35","Faigi 23:28 b.t.; MozV 28:52 b.t.; Yes 22:2,3; Yer 6:6; Sakh 14:2","Faigi 21:6; Mat 24:2"]', NULL),
  (3393944, 'NT', 'Luka', 19, 45, 'Ba möi ia ba gosali,[19] ibörötaigö ifofanö baero zaniaga andrö,', '["Ayati 45-46: Mat 21:12,13; Mar 11:15-18"]', NULL),
  (3393944, 'NT', 'Luka', 19, 46, 'imane khöra: No so ba zura: "Ba omo wangandrö dania nomogu andrö"; ba ya''ami, ba no mibali''ö tögi narö hili, naha zorabu.', '["Ayati 45-46: Mat 21:12,13; Mar 11:15-18"]', NULL),
  (3393944, 'NT', 'Luka', 19, 47, 'Ba mamahaö ia ba gosali, ero ma''ökhö. Ba la''alui wamunu ya''ia ere sebua ba sangila amakhoita, ba si manö göi zalaŵa.[20]', '["Mat 21:45,46"]', NULL),
  (3393944, 'NT', 'Luka', 19, 48, 'Ba lö lasöndra lala. A''oi sa la''omasi''ö ia niha sato, wamondrongo linia.', '["Mat 21:45,46"]', NULL),
  (3393945, 'NT', 'Luka', 20, 1, 'Ba ha samuza ma''ökhö, me ifahaö niha ba gosali, me i''ombakha''ö duria somuso dödö andrö, ba so gere sebua ba sangila amakhoita ba satua mbanua andrö,', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 2, 'muhede ira khönia, lamane: Ŵa''ö khöma: Hadia, wa tola ölau da''ö, ba ha niha ia, zanehe khöu?', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 3, 'Ba itema lira, imane khöra: So göi zambalö nisofugu khömi, ba mi''ombakha''ö khögu:', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 4, 'Famayagö idanö andrö khö Yohane no, hadia, moroi ba zorugo ma moroi ba niha?', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 5, 'Ba la''era-era tödöra, lamane: Na taŵa''ö: Moroi ba zorugo, ba imane dania khöda: Ba hana wa lö samati ami khönia!', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 6, 'Ba na taŵa''ö: Moroi ba niha, ba latebu kara ita niha sato fefu; a''oi sa faduhu dödöra, wa no sama''ele''ö Yohane andrö.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 7, 'Ba laŵa''ö khönia, lö la''ila, he moroi.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 8, 'Ba imane khöra Yesu: Ba lö''ö göi uŵa''ö khömi, hadia wa tola ulau da''ö.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 9, 'Ba ibörötaigö iŵa''ö ba niha gamaedola andre:[1] So niha, samazökhi kabu nagu, ba ibe''e niwawalö ba zohalöŵö, ba isaŵa danö bö''ö, ara ia.', '["Ayati 9-19: Mat 21:33-46; Mar 12:1-12"]', NULL),
  (3393945, 'NT', 'Luka', 20, 10, 'Ba me baŵa mbua, ba ifatenge zawuyu ba zohalöŵö andrö, ena''ö labe''e khönia mbua kabu nagu andrö ösa. Ba latema laböbözi da''ö sohalöŵö ba kabu nagu andrö, ba lafatenge mangawuli, lö labe''e.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 11, 'Ba itohugö, ifatenge zawuyu tanö bö''ö. Ba ya''ira, ba laböbözi da''ö göi, la''o''aya, ba lafatenge mangawuli, lö labe''e.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 12, 'Ba itohugö ifatenge, datölu sa''ae. Ba lafesokho da''ö, ba latibo''ö baero.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 13, 'Ba imane sokhö kabu nagu andrö: He uwisa? Da''ufatenge nonogu omasiö andrö, te ata''u ira da''ö.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 14, 'Ba me la''ila da''ö sohalöŵö ba kabu andrö, ba fahuhuo ira, lamane: Sanema ondröita da''ö, databunu ia, ena''ö khöda möi gondröita andrö.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 15, 'Ba latibo''ö ia baero kabu nagu andrö ba labunu.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 16, 'Möi ia dania, ba ifakiko zohalöŵö andrö, ba ibe''e ba danga danö bö''ö kabu nagu no mege.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 17, 'Ba inehegö ira ba imane: Ba hadia ia zi so ba zura andrö: "Gowe andrö, nitibo''ö zotomo andrö, ba no tobali toyo ba watalinga?"', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 18, 'Ba sarasa fefu zalau ba gowe andrö, ba nilangönia, ba imama.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 19, 'Ba la''alui lala wondra''u ya''ia sangila amakhoita ba ere sebua, ba da''ö sibai, ba ata''u ira niha sato. Noa sa aboto ba dödöra, wa khöra iböbögö gamaedola andrö.[2]', '["Faigi 19:47"]', NULL),
  (3393945, 'NT', 'Luka', 20, 20, 'Ba latarogö ia,[3] ba lafatenge zamauze, samini''ö tödöra, hulö na satulö tödö ira, ena''ö la''alani ia ba huhuonia, ba wame''e ba danga zalaŵa ya''ia, ba ba danga gumandru.', '["Ayati 20-46: Mat 22:15-22; Mar 12:13,14"]', NULL),
  (3393945, 'NT', 'Luka', 20, 21, 'Ba lasofu khönia, lamane: He samahaö, ma''ila wa no satulö niŵa''öu, awö wamahaömö, ba lö öfaigi mbawa niha, ha si ndruhu manö khöu, wangombakha lala Lowalangi andrö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393945, 'NT', 'Luka', 20, 22, 'Hadia, tola tabe''e mbeo khö kaizaro, hadia lö''ö?', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 23, 'Ba me no i''ila wa''onekhera andrö, ba imane khöra: Mi''oroma''ö khögu hua suku. Ha famaedo da''e khönia ba ha khö zurania?', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 24, 'Ba lamane khönia: Khö kaizaro.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 25, 'Ba imane khöra: Na si manö, ba mibe''e khö kaizaro, hadia khö kaizaro, ba hadia khö Lowalangi, ba mibe''e khö Lowalangi.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 26, 'Ba tebai la''alani ia ba niŵa''önia, ba niha sato, ba ahöli-höli dödöra ba wanemania li andrö, ba lö hede-hedera sa''ae.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 27, 'Ba so zadukaio andrö,[4] ösa, sanguma''ö lö femaoso zi mate, lasofu khönia, lamane:', '["Ayati 27-40: Mat 22:23-33; Mar 12:18-27"]', NULL),
  (3393945, 'NT', 'Luka', 20, 28, 'He samahaö, no ibe''e ba zura khöma Moze, na mate zi so talifusö, si so donga, ba na lö ono, ba yamuhalö ndronga andrö talifusönia, ba yamufonga''ötö dalifusönia si mate andrö.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 29, 'Ba no so zi fatalifusö, dafitu, ba mangowalu zi samösa, ba mate, lö ono,', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 30, 'ba ihalö ndra alawe andrö fanete da''ö ba fanete da''ö zui,', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 31, 'ba si manö-manö, dafitu, oi mate, lö ono.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 32, 'Ba ba gafuriata, ba mate göi ndra alawe andrö.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 33, 'Ba ira alawe andrö, ha donga ia, ba khöra andrö, ba wemaoso zi mate andrö dania? No dozi lahalö ia, dafitu.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 34, 'Ba imane khöra Yesu: Niha zi sagötö tanö andre zangowalu ba tebe''e nihalö.', '["YohI 3:1,2"]', NULL),
  (3393945, 'NT', 'Luka', 20, 35, 'Ba si tola ba mbanua furi andrö, si tola maoso moroi ba ngai zi mate, ba lö mangowalu ba lö labe''e nihalö.', '["YohI 3:1,2"]', NULL),
  (3393945, 'NT', 'Luka', 20, 36, 'Tebai sa mate ira sa''ae göi, hulö mala''ika sa''ae, ba ono Lowalangi ira, me ono wemaoso andrö. [5]', '["YohI 3:1,2"]', NULL),
  (3393945, 'NT', 'Luka', 20, 37, 'Ba femaoso zi mate andrö, ba no itörö göi li Moze, ba ngafu ndroi andrö, me ibe''e töi Zo''aya Lowalangi Gaberahamo ba Lowalangi Giza''aki ba Lowalangi Yakobo.', '["YohI 3:1,2"]', NULL),
  (3393945, 'NT', 'Luka', 20, 38, 'Ba tenga Lowalangi zi mate Lowalangi, no Lowalangi zauri; a''oi sa auri ira khönia.', '["YohI 3:1,2"]', NULL),
  (3393945, 'NT', 'Luka', 20, 39, 'Ba latema linia sangila amakhoita ösa, lamane: Duhu niŵa''öu, samahaö.', '[]', NULL),
  (3393945, 'NT', 'Luka', 20, 40, 'Ba ata''u sa''ae ira manofu khönia hadia ia.[6]', '["Mat 22:46"]', NULL),
  (3393945, 'NT', 'Luka', 20, 41, 'Ba imane khöra:[7] He wisa wa laŵa''ö ma''uwu Dawido Keriso andrö?', '["Ayati 41-44: Mat 22:41-45; Mar 12:35-37"]', NULL),
  (3393945, 'NT', 'Luka', 20, 42, 'Ba Dawido sa zanguma''ö ba zura zinunö andrö: "No iŵa''ö So''aya khö Zo''aya ya''o: Dadao ba gambölögu,', '["Ayati 41-44: Mat 22:41-45; Mar 12:35-37"]', NULL),
  (3393945, 'NT', 'Luka', 20, 43, 'irege no ube''e tou barö gaheu zi fa''udu khöu."', '["Ayati 41-44: Mat 22:41-45; Mar 12:35-37"]', NULL),
  (3393945, 'NT', 'Luka', 20, 44, 'Tobali faso''aya khönia Dawido; ba he wisa, wa ma''uwunia ia?', '["Ayati 41-44: Mat 22:41-45; Mar 12:35-37"]', NULL),
  (3393945, 'NT', 'Luka', 20, 45, 'Ba me lafondrondrongo niha sato fefu,[8] ba imane ba nifahaönia:', '["Ayati 45-47: Mat 23:1,6,14; Mar 12:38-40"]', NULL),
  (3393945, 'NT', 'Luka', 20, 46, 'Mi''angelamaisi zangila amakhoita andrö; somasi mamaru baru sanau, somasi na la''owai ira ba kade, awö wedadao ba dadaoma tanö si yaŵa, ba zekola ba ba walöŵa,[9]', '["Faigi 11:43"]', NULL),
  (3393945, 'NT', 'Luka', 20, 47, 'sangohori balazo lakha mbanua, sangaragö fangandrö-ngandrö, fa la''ila niha; tedou manö huku, nifatörö khöra dania.', '["Faigi 11:43"]', NULL),
  (3393946, 'NT', 'Luka', 21, 1, 'Ba ifakhölö ia ba i''ila zoana''a, same''e ame''elara ba naha game''ela andrö.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 2, 'Ba i''ila göi lakha mbanua, samösa, si numana, same''e si dombua rimi ba da''ö.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 3, 'Ba imane: Sindruhu niŵa''ögu khömi, ebua nibe''e lakha mbanua si numana andrö, moroi ba khöra fefu.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 4, 'Dozi ira da''ö, ba oi sa si töra khöra nibe''era, ame''ela, ba ya''ia ba föfö zambö khönia ibe''e, awai mbalazo, si so khönia.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 5, 'Ba me so zamatunö osali andrö,[1] wa no muhaogö ia kara si sökhi ba buala andrö, ba imane:', '["Ayati 5-24: Mat 24:1-22; Mar 13:1-20","Faigi 19:43 b.t."]', NULL),
  (3393946, 'NT', 'Luka', 21, 6, 'Ni''ilami andrö, ba irugi baŵa dania, ba sambua lö tosai ba dete naŵönia yaŵa kara, si lö mududugö.[2]', '["Ayati 5-24: Mat 24:1-22; Mar 13:1-20","Faigi 19:43 b.t."]', NULL),
  (3393946, 'NT', 'Luka', 21, 7, 'Ba lasofu khönia, lamane: He samahaö, ba ha wa''ara da''ö? Ba hadia dandra, wa itörö dania da''ö?', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 8, 'Ba imane: Mifaigi, böi lafaelungu ami; ato sa dania zi möi, sanagö töigu, lamane dania: Ya''odo, ba: no irugi baŵa; böi mi''o''ö khöra.[3]', '["Faigi 17:23 b.t."]', NULL),
  (3393946, 'NT', 'Luka', 21, 9, 'Ba na mirongo wanuwö ba folaŵa, ba böi tokea ami; lö''ö sa tola lö so da''ö ua; ba lö''ö na i''anema''ö fa''atua danö.', '["Faigi 17:23 b.t."]', NULL),
  (3393946, 'NT', 'Luka', 21, 10, 'Ba imane khöra: Maoso dania zi sambua soi, udu zi sambua, ba si sara öri, udu zi sara.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 11, 'Ba so ndruru danö sabölö-bölö ba lofo mbanua ba fökhö sebua misa, ba ameta''uö ba tandra sebua, moroi ba mbanua si yaŵa.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 12, 'Ba föna da''ö fefu, ba lababaya ami ba lagohi ami, la''ohe ami ba zekola ba ba gurunga, ba wolohe ya''ami ba zalaŵa ba ba gumandru, börö döigu andrö.[4]', '["Yoh 15:20; HalZin 12:1","Yer 1:9; HalZin 6:10"]', NULL),
  (3393946, 'NT', 'Luka', 21, 13, 'Tobali famaduhu''ö tödöra da''ö khömi.', '["Yoh 15:20; HalZin 12:1","Yer 1:9; HalZin 6:10"]', NULL),
  (3393946, 'NT', 'Luka', 21, 14, 'Andrö mitanö ba dödömi, fa böi mihönagö mi''alui he miwisa wamu''a.', '["Yoh 15:20; HalZin 12:1","Yer 1:9; HalZin 6:10"]', NULL),
  (3393946, 'NT', 'Luka', 21, 15, 'Ya''o sa zame''e dania khömi fehede ba fa''atua-tua, si tebai lalaŵa ba si tebai lafadaö dozi si fa''udu khömi.[5]', '["Yoh 15:20; HalZin 12:1","Yer 1:9; HalZin 6:10"]', NULL),
  (3393946, 'NT', 'Luka', 21, 16, 'Ba so göi dania, ba la''a mbölimi ira amami ba talifusö ba si tenga bö''ö ba si fahuwu khömi, ba labunu ösa ami.', '["Faigi 12:7; Mat 10:30; Dan 3:27","Nga''ötII 15:7; Mat 24:13"]', NULL),
  (3393946, 'NT', 'Luka', 21, 17, 'Ba dozi dania fatiu dödöra khömi, börö döigu andrö.', '["Faigi 12:7; Mat 10:30; Dan 3:27","Nga''ötII 15:7; Mat 24:13"]', NULL),
  (3393946, 'NT', 'Luka', 21, 18, 'Ba sara lö tekiko bu ba högömi.[6]', '["Faigi 12:7; Mat 10:30; Dan 3:27","Nga''ötII 15:7; Mat 24:13"]', NULL),
  (3393946, 'NT', 'Luka', 21, 19, 'Ba wa''anau gölömi dania misöndra haremi nosomi.[7]', '["Faigi 12:7; Mat 10:30; Dan 3:27","Nga''ötII 15:7; Mat 24:13"]', NULL),
  (3393946, 'NT', 'Luka', 21, 20, 'Ba na mi''ila no lafasui Yeruzalema sanuwö, ba ya''aboto ba dödömi, no ahatö mbaŵa wanudugö ya''ia.', '["Faigi 17:31"]', NULL),
  (3393946, 'NT', 'Luka', 21, 21, 'Ba ndramoloi ba hili zi so ba Yudaia ba ndrahumeta ira si so yomo ba mbanua; ba si so ba halama, ba böi ndramöi miyomo.[8]', '["Faigi 17:31"]', NULL),
  (3393946, 'NT', 'Luka', 21, 22, 'Me baŵa wolau balö da''ö, ena''ö itörö fefefu zi so ba zura.', '["Faigi 17:31"]', NULL),
  (3393946, 'NT', 'Luka', 21, 23, 'Alai zanabina ba si so ono, ba mbagi zusu, na luo da''ö dania. Abölö-bölö sibai sa wamakao dania ba guli danö, ba fönu ba niha andre.', '["MozV 28:64; Rom 11:25; Fam 11:2"]', NULL),
  (3393946, 'NT', 'Luka', 21, 24, 'Ba mate ira ba mbawa wöda, ba ni''ohe sawuyu ira ba niha baero fefu misa; ba nihundra-hundra niha baero dania Yeruzalema, irege no mo''ahonoa götö niha baero andrö.[9]', '["MozV 28:64; Rom 11:25; Fam 11:2"]', NULL),
  (3393946, 'NT', 'Luka', 21, 25, 'Ba so dania dandra ba luo ba ba mbaŵa ba ba ndröfi,[10] ba fa''atosasa niha ba guli danö, ba wa''abu dödö ba we''ugu-ugu nasi ba ba ndrulu. [11]', '["Ayati 25-36: Mat 24:29-36; Mar 13:24-33","Hes 38:19,20; Hos 10:8"]', NULL),
  (3393946, 'NT', 'Luka', 21, 26, 'Tekiko niha ba wa''ata''u börö wangiwa dödö ba zalua si göna uli danö andre dania, humeu-heu sa wa''abölö ba mbanua si yaŵa dania.', '["Mat 26:64"]', NULL),
  (3393946, 'NT', 'Luka', 21, 27, 'Ba la''ila dania Nono Niha, si so moroi sa ba lawuo, si no a''oi so fa''abölö, awö lakhömi.[12]', '["Mat 26:64"]', NULL),
  (3393946, 'NT', 'Luka', 21, 28, 'Ba na iborögö da''ö, ba mifaoso, ba mifaöga mbawami, me no ahatö wangefa''ö ya''ami andrö.[13]', '["TesII 1:7 b.t.; Yak 5:8"]', NULL),
  (3393946, 'NT', 'Luka', 21, 29, 'Ba iŵa''ö khöra gamaedola, imane: Mifaigi marafala andrö, awö ngawalö geu fefu;', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 30, 'na no mokio-kio ia, ba mi''ila manö tödömi, na mifaigi, wa no ahatö mbaŵa wa''aukhu zino.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 31, 'Si manö göi ami, na mi''ila itörö da''ö, ba ya''aboto ba dödömi, no ahatö mbanua Lowalangi andrö.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 32, 'Si ndruhu niŵa''ögu khömi, lö fakhamö atua niha si sagötö andre, ba no ahori itörö.', '[]', NULL),
  (3393946, 'NT', 'Luka', 21, 33, 'Atua mbanua si yaŵa ba atua danö, ba lö''ö manö awu''a daroma ligu andre.[14]', '["Faigi 16:17"]', NULL),
  (3393946, 'NT', 'Luka', 21, 34, 'Ba mi''angelama, fa böi arörö dödömi ba wemanga-manga ba ba wemabu-mabu ba ba wa''abu dödö ba mbalazo, ba i''ozumagö ikhamö ami baŵa da''ö;[15]', '["Rom 13:13"]', NULL),
  (3393946, 'NT', 'Luka', 21, 35, 'hulö dandraŵa sa''ae ihawui fefu zi so ba guli danö, ma''asagörö, misa.', '["Rom 13:13"]', NULL),
  (3393946, 'NT', 'Luka', 21, 36, 'Ba böi miförö, ero ma''ökhö, mi''angandrö-ngandrö, ena''ö tola moloi ami ba da''ö fefu, si törö dania, ba ena''ö tola föna Nono Niha nahami.[16]', '["Mat 24:4,2; YohI 2:28; FetII 3:11 b.t."]', NULL),
  (3393946, 'NT', 'Luka', 21, 37, 'Ba ba gosali so ia, na ma''ökhö, mamahaö; ba na owi, ba möi ia baero, möi ia mörö ba gahe hili andrö, sotöi hili wanikha.[17]', '["Mat 21:17; Yoh 8:2"]', NULL),
  (3393946, 'NT', 'Luka', 21, 38, 'Ba lahulö wongi niha sato fefu, wangondrasi ya''ia ba gosali, ba wamondrondrongo huhuonia.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 1, 'Ba lö ara tö,[1] ba owasa roti si lö mu''aisöni andrö, nifotöi fasa.', '["Ayati 1-2: Mat 26:1-5; Mar 14:1,2","Mat 21:46"]', NULL),
  (3393947, 'NT', 'Luka', 22, 2, 'Ba la''alui lala wamunu ya''ia ere sebua ba sangila amakhoita; ata''u sa ira niha sato.[2]', '["Ayati 1-2: Mat 26:1-5; Mar 14:1,2","Mat 21:46"]', NULL),
  (3393947, 'NT', 'Luka', 22, 3, 'Ba möi Zatana ba dödö Yuda andrö,[3] sotöi banua Kariota, awö zi felendrua andrö.[4]', '["Ayati 3-6: Mat 26:14-16; Mar 14:10-11","Yoh 13:27"]', NULL),
  (3393947, 'NT', 'Luka', 22, 4, 'Ba möi ia fahuhuo khö ndra ere sebua ba khö ndra kumandra, he wisa lala wangombakhania ya''ia khöra.', '["Ayati 3-6: Mat 26:14-16; Mar 14:10-11","Yoh 13:27"]', NULL),
  (3393947, 'NT', 'Luka', 22, 5, 'Ba omuso dödöra, ba la''osara''ö li, ba wame''e ana''a khönia.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 6, 'Ba itehe, ba i''alui zi sökhi lala, wangombakha ya''ia, ba zi lö niha.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 7, 'Ba irugi baŵa roti si lö mu''aisöni no mege,[5] ba nitaba fasa andrö.', '["Ayati 7-13: Mat 26:17-20; Mar 14:12-16"]', NULL),
  (3393947, 'NT', 'Luka', 22, 8, 'Ba ifatenge ndra Fetero Yohane Yesu, imane: Mi''ae mi''asiwai khöda wasa andrö, ena''ö ta''a.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 9, 'Ba lamane khönia: Heza zomasi ndra''ugö, ma''asiwai?', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 10, 'Ba imane khöra: Hiza, na mirugi yomo ba mbanua, ba falukha ami niha, solohe migö nidanö, da''ö mi''o''ö, ba nomo, ba zi möi ia,', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 11, 'ba mimane ba zokhö omo andrö: Da''ö niŵa''ö zamahaö ya''aga khöu: Heza so naha andrö khögu, ba wemanga wasa, awö nifahaögu?', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 12, 'Ba i''oroma''ö dania khömi mbate''e sebua, yaŵa ba zi sagötö, si no mubologö tufo; ba da''ö mi''asiwai.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 13, 'Ba möi ira, ba itörö niŵa''önia khöra; ba la''asiwai wasa andrö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 14, 'Ba me no inötö,[6] ba mudadao ia manga, ba awönia zinenge andrö si felendrua.', '["Ayati 14-18: Mat 26:26-29; Mar 14:22-25"]', NULL),
  (3393947, 'NT', 'Luka', 22, 15, 'Ba imane khöra: No humulu sibai dödögu, ba wemanga wasa andre, awömi, föna wamakao ya''o andrö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 16, 'Uŵa''ö sa khömi, lö''ö sa''ae u''a, irege no itörö ba mbanua Lowalangi andrö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 17, 'Ba ihalö mako, i''aohasi gölö Lowalangi, ba imane: Mitema da''e ba mifosasi khömi.', '["Mat 26:29"]', NULL),
  (3393947, 'NT', 'Luka', 22, 18, 'Uŵa''ö sa khömi, lö''ö sa''ae ubadu nösi mbua nagu, i''otarai da''e, irege alua mbanua Lowalangi andrö.[7]', '["Mat 26:29"]', NULL),
  (3393947, 'NT', 'Luka', 22, 19, 'Ba ihalö roti,[8] i''aohasi gölö Lowalangi, iboboto roti ba ibe''e khöra, imane: Botogu da''e, nibe''e salahimi; mitörö-törö tödömi ndra''o, ba zi mane.[9]', '["Ayati 19-20: Mat 26:27-29; Mar 14:22-25; KorII 11:23 b.t.","Yoh 6:51"]', NULL),
  (3393947, 'NT', 'Luka', 22, 20, 'Ba si manö göi mako andrö, me no aefa manga ira, ba imane: Amabu''ula li si bohou mako andre, ba ndrogu, saduwa dania salahimi.', '["Ayati 19-20: Mat 26:27-29; Mar 14:22-25; KorII 11:23 b.t.","Yoh 6:51"]', NULL),
  (3393947, 'NT', 'Luka', 22, 21, 'Ba hiza,[10] no orudu ba wemanga andre danga zi manga mböligu.', '["Ayati 21-22: Mat 26:21-25; Mar 14:18-21"]', NULL),
  (3393947, 'NT', 'Luka', 22, 22, 'Möi sa Nono Niha, itörö nihonogöi; ba alai niha andrö, si manga mbölinia.', '["Ayati 21-22: Mat 26:21-25; Mar 14:18-21"]', NULL),
  (3393947, 'NT', 'Luka', 22, 23, 'Ba ibörötaigö faoma lasofu khö nawöra, ha niha maö ia, ba khöra andrö, solau da''ö dania.', '["Ayati 21-22: Mat 26:21-25; Mar 14:18-21"]', NULL),
  (3393947, 'NT', 'Luka', 22, 24, 'Ba tesao göi wamadöni ba khöra, ha niha zebuara maö.[11]', '["Faigi 9:46"]', NULL),
  (3393947, 'NT', 'Luka', 22, 25, 'Ba imane khöra: Mamatörö banuara zalaŵa ba niha baero, ba si so niha barö mbawa, ba lafotöi sebua tödö.[12]', '["Mat 20, 25 b.t.","Rom 12:10; Fil 2:3","Yoh 13:4-14; Mat 20:28"]', NULL),
  (3393947, 'NT', 'Luka', 22, 26, 'Ba ya''ami, ba tenga si manö; sebuami, ba yahulö si mane si akhi, ba solohe, ba yahulö si mane enoni.[13]', '["Mat 20, 25 b.t.","Rom 12:10; Fil 2:3","Yoh 13:4-14; Mat 20:28"]', NULL),
  (3393947, 'NT', 'Luka', 22, 27, 'Ha niha sa zebua? sidadao manga, ba ma sangai halöŵö? Hadia, tenga sidadao manga? Ba ya''o, ba khömi, ba no hulö zangai halöŵö.[14]', '["Mat 20, 25 b.t.","Rom 12:10; Fil 2:3","Yoh 13:4-14; Mat 20:28"]', NULL),
  (3393947, 'NT', 'Luka', 22, 28, 'Ba ya''ami zi lö faröi-röi khögu, ba wanandraigö ya''o andrö.', '["Faigi 12:32; Fam 3:21","Mat 19:28"]', NULL),
  (3393947, 'NT', 'Luka', 22, 29, 'Ba ya''o ba uhonogöi khömi, si mane fangohonogöi Nama khögu banua andrö,[15]', '["Faigi 12:32; Fam 3:21","Mat 19:28"]', NULL),
  (3393947, 'NT', 'Luka', 22, 30, 'ena''ö orudu manga ami khögu ba mamadu-madu hadia ia, ba mbanuagu andrö, ba ena''ö dumadao dania ami ba dadaoma, manguhuku Iraono Gizeraeli, si felendrua tua andrö.[16]', '["Faigi 12:32; Fam 3:21","Mat 19:28"]', NULL),
  (3393947, 'NT', 'Luka', 22, 31, 'He Simoni! He Simoni! hiza no i''andrö khönia Satana, ena''ö itafi''ö ami, hulö wakhe,[17]', '["FetI 5:8","Yoh 21:15"]', NULL),
  (3393947, 'NT', 'Luka', 22, 32, 'ba no mangandrö ndra''o, salahiu, ena''ö lö aetu wamatimö, ba ya''ugö, na no öfalalini gera-erau dania, ba abe''e''ö dalifusöu.[18]', '["FetI 5:8","Yoh 21:15"]', NULL),
  (3393947, 'NT', 'Luka', 22, 33, 'Ba imane khönia: He Tua, tola manö sa''ae möido awöu, he ba gurunga, ba he ba wa''amate.[19]', '["Mat 26:33 b.t.; Yoh 13:37 b.t."]', NULL),
  (3393947, 'NT', 'Luka', 22, 34, 'Ba imane: Uŵa''ö khöu, Fetero, lö fakhamö miwo zilatao bongi dania, ba no medölu ö''osilö''ögö wangila ya''o.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 35, 'Ba imane khöra: Me ufatenge ami no, si lö kabe-kabe, si lö bola, si lö badagahe, hadia no irai ambö khömi hadia ia? Ba lamane: Lö irai.[20]', '["Faigi 9:3","Faigi 24:32; Yes 53:12"]', NULL),
  (3393947, 'NT', 'Luka', 22, 36, 'Ba imane khöra: Ba iya''e, ba ha niha zi so kabe-kabe ba yamuhalö, si manö göi mbola, ba si lö''ö, ba yamu''amawa mbarunia sebua, ba yamu''öli wöda.', '["Faigi 9:3","Faigi 24:32; Yes 53:12"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393947, 'NT', 'Luka', 22, 37, 'Uŵa''ö sa khömi, lö tola lö itörö ba khögu da''ö, si so ba zura: "Ba no tebe''e awö zebua horö ia"; itörö sa nitandrösaigö khögu andrö.[21]', '["Faigi 9:3","Faigi 24:32; Yes 53:12"]', NULL),
  (3393947, 'NT', 'Luka', 22, 38, 'Ba lamane: He Tua, hiza wöda, dua rozi. Ba imane khöra: Abönö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 39, 'Ba möi ia baero,[22] isaŵa gahe hili wanikha, no to''ölö ia ba zi manö.', '["Ayati 39-46: Mat 26:30,36-46; Mar 14:32-42"]', NULL),
  (3393947, 'NT', 'Luka', 22, 40, 'Ba la''o''ö ia nifahaönia. Ba me no irugi, ba imane khöra: Mi''angandrö, fa böi itörö ami fanandraigö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 41, 'Ba iheta ia khöra, ikhamö tebu-tebu kara wa''aröu, ba ibalöduhini tou danö, mangandrö, imane:', '["Yoh 6:38"]', NULL),
  (3393947, 'NT', 'Luka', 22, 42, 'He Ama, ena''ö na öfatalu''i''ö khögu mako andrö, ba böi ya''itörö zomasi ndra''o, ha somasi ndra''ugö.[23]', '["Yoh 6:38"]', NULL),
  (3393947, 'NT', 'Luka', 22, 43, 'Ba to''ele khönia mala''ika, moroi ba zorugo, sangabölö''ö ya''ia. [24]', '["Dan 10:18,19; Heb 2:7","Heb 5:7"]', NULL),
  (3393947, 'NT', 'Luka', 22, 44, 'Ba tobali fasöndra ia ba iforege wangandrö. Ba tobali hulö mböi-böi ndro mböböinia, atoru ba danö.[25]', '["Dan 10:18,19; Heb 2:7","Heb 5:7"]', NULL),
  (3393947, 'NT', 'Luka', 22, 45, 'Ba maoso ia, ibato wangandrö andrö i''ondrasi ndra nifahaönia, ba hiza, no mörö ira, ba wa''abu dödö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 46, 'Ba imane khöra: Hadia wa mörö ami? Mifaoso! mi''angandrö, fa böi itörö ami fanandraigö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 47, 'Ba me humede ia na,[26] ba hiza niha, ba sotöi Yuda andrö, awö zi felendrua, zangoloi''ö ya''ira, ba i''ondrasi Yesu, ba wangago bawania.', '["Ayati 47-53: Mat 26:47-56; Mar 14:43-50; Yoh 18:2,3,10,11"]', NULL),
  (3393947, 'NT', 'Luka', 22, 48, 'Ba imane khönia Yesu: He Yuda, hadia fa''ago bawa ndra''ugö khö Nono Niha, wemanga mbölinia?', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 49, 'Ba me la''ila si fao khönia he wisa, ba lamane: he Tua! Hadia, ma''ö''ötö ira föda?', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 50, 'Ba i''ö''ötö zawuyu gere sebua si samösa, awöra, i''eŵa dalingania, kambölö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 51, 'Ba humede Yesu, imane: Noa, böi mitohugö. Ba ibabaya dalinga andrö, ifadöhö zesokho.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 52, 'Ba imane Yesu ba gere sebua andrö, ba gumandra ba gosali ba ba zatua andrö, si möi mondra''u ya''ia: Hulö ba zorabu möi ami, moföda ami, ba mobago gama.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 53, 'Me ero ma''ökhö ndra''o khömi ba gosali, ba lö nibabayami ya''o. Ba da''e ginötö, ba da''e wa''abölö zogömi-gömi andrö.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 54, 'Ba me no lara''u ia,[27] ba la''ohe, ladölö ba nomo gere sebua andrö. Ba i''o''ö Fetero, aröu ia, moroi furi.', '["Ayati 54-62: Mat 26:57,69-75; Mar 14:54,66-72; Yoh 18:13-18,25-27"]', NULL),
  (3393947, 'NT', 'Luka', 22, 55, 'Ba me no la''ebua''ö galitö ba dalu golayama, me dumadao ira, ba dumadao göi Wetero ba ngaira.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 56, 'Ba i''ila ia sawuyu ono alawe, me dumadao ia ba haga galitö, ifaigi ia, imane: Da''ö göi nawönia.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 57, 'Ba i''osilö''ögö, imane: Lö u''ila ha niha da''ö, alawe.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 58, 'Ba lö ara, ba i''ila ia tanö bö''ö ba imane: Awöra göi ndra''ugö. Ba imane Fetero: Tenga le.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 59, 'Ba so saza gotalua, ba ifaduhu''ö tanö bö''ö, imane: Si ndruhu, da''e göi nawönia, banua Galilaia sa göi ia.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 60, 'Ba imane Fetero: Lö u''ila hadia niŵa''öu, le.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 61, 'Ba ibali''ö ia So''aya, ifaigi Wetero; ba itörö tödö Wetero niŵa''ö Zo''aya andrö, me imane khönia: Lö fakhamö miwo zilatao bongi, ba no medölu ö''osilö''ögö ndra''o.[28]', '["Faigi 22:34"]', NULL),
  (3393947, 'NT', 'Luka', 22, 62, 'Ba möi ia baero, mege-ege sibai.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 63, 'Ba la''o''aya Yesu niha andrö,[29] solohe ya''ia, laböbözi ia,', '["Ayati 63-65: Mat 26:67,68; Mar 14:65"]', NULL),
  (3393947, 'NT', 'Luka', 22, 64, 'labalugö ia, ba lasofu khönia, lamane: Fa''ele''ö, ha niha zamözi ya''ugö?', '["Ayati 63-65: Mat 26:67,68; Mar 14:65"]', NULL),
  (3393947, 'NT', 'Luka', 22, 65, 'Ba oya na ngawalö tanö bö''ö laŵa''ö khönia, wanandraŵaisi ya''ia.', '["Ayati 63-65: Mat 26:67,68; Mar 14:65"]', NULL),
  (3393947, 'NT', 'Luka', 22, 66, 'Ba me no moluo, ba falukha zatua mbanuara ba ere sebua ba sangila amakhoita, ba la''ohe ia ba rafe khöra, lamane: Na Keriso andrö ndra''ugö, ba ombakha''ö khöma.[30]', '["Mat 27:1; Mar 15:1; Yoh 18:28"]', NULL),
  (3393947, 'NT', 'Luka', 22, 67, 'Ba imane khöra: Na uŵa''ö khömi, ba lö faduhu dödömi.[31]', '["Mat 26:63-66; Mar 14:60-64"]', NULL),
  (3393947, 'NT', 'Luka', 22, 68, 'Ba na manofu ndra''o, ba lö mitema ligu.', '["Mat 26:63-66; Mar 14:60-64"]', NULL),
  (3393947, 'NT', 'Luka', 22, 69, 'Ba i''otarai da''e, ba dumadao Nono Niha ba gambölö wa''abölö Lowalangi andrö.', '["Mat 26:63-66; Mar 14:60-64"]', NULL),
  (3393947, 'NT', 'Luka', 22, 70, 'Ba lamane fefu: Ba Ono Lowalangi ndra''ugö? Ba imane khöra: Ya''ia niŵa''ömi.', '[]', NULL),
  (3393947, 'NT', 'Luka', 22, 71, 'Ba lamane: Hadia guna wamaduhu''ö sa''ae khöda? Tögi dalingada sa''ae zamondrongo, me iŵa''ö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 1, 'Ba maoso ira fefu, ba la''ohe ia khö Wilato.[1]', '["Ayati 1-4: Mat 27:2,11-14; Mar 15:1-5; Yoh 18:29-38","Faigi 20:22 b.t.; Mat 17:27"]', NULL),
  (3393948, 'NT', 'Luka', 23, 2, 'Ba labörötaigö la''adugö ia, lamane: Samakuyu niha khöda da''e ma''ila, ba sanenaŵa fame''e beo khö kaizaro, ba sanguma''ö Keriso ia, razo.[2]', '["Ayati 1-4: Mat 27:2,11-14; Mar 15:1-5; Yoh 18:29-38","Faigi 20:22 b.t.; Mat 17:27"]', NULL),
  (3393948, 'NT', 'Luka', 23, 3, 'Ba isofu khönia Filato, imane: Hadia, razo niha Yehuda ndra''ugö? Ba itema linia, imane: ya''ia niŵa''öu.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 4, 'Ba imane Filato ba gere sebua, ba ba niha sato andrö: Lö usöndra zala niha da''ö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 5, 'Ba ya''ira, ba laforege, lamane: Ifahufa niha, wamahaö ya''ira, ba danö Yudaia ma''asagörö, i''otarai ba Galilaia ba irugi da''e.[3]', '["HalZin 10:36 b.t."]', NULL),
  (3393948, 'NT', 'Luka', 23, 6, 'Ba me irongo da''ö Filato, ba isofu, na banua Galilaia niha da''ö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 7, 'Ba me irongo wa banua Herode, ba ifatenge khö Herode, si so ba Yeruzalema göi, me luo da''ö.[4]', '["Faigi 3:1"]', NULL),
  (3393948, 'NT', 'Luka', 23, 8, 'Ba me i''ila Yesu Herode, ba omuso sibai dödönia, no ara sa''ae omasi ia i''ila, me no irongo duriania, ba idöna-döna ifazökhi zambalö dandra, ba zi so ia. [5]', '["Faigi 9:9; Mat 14:1"]', NULL),
  (3393948, 'NT', 'Luka', 23, 9, 'Ba oya ngawalö isofu khönia, ba lö''ö manö itema linia Yesu.', '["Faigi 9:9; Mat 14:1"]', NULL),
  (3393948, 'NT', 'Luka', 23, 10, 'Ba so gere sebua andrö, awö zangila amakhoita, laforege wangadugö ya''ia.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 11, 'Ba i''ositengagö göi ia Herode, awö zaradadunia, i''o''aya, ifobaru baru safusi ba ifatenge mangawuli khö Wilato.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 12, 'Ba tobali fahuwu ira, Herode Wilato, i''otarai luo da''ö, föna ö sa, ba no si fa''udu ira.[6]', '["HalZin 4:27"]', NULL),
  (3393948, 'NT', 'Luka', 23, 13, 'Ba ifalukha''ö Filato gere sebua, awö zalaŵa, awö niha sato,', '["Yoh 19:1"]', NULL),
  (3393948, 'NT', 'Luka', 23, 14, 'imane khöra: No mi''ohe khögu niha andrö, samabali khöda niha miŵa''ö, ba hiza, no usekhegö ia, ba zi so ami, ba lö nisöndragu ba niha andrö börö wangadugömi ya''ia.', '["Yoh 19:1"]', NULL),
  (3393948, 'NT', 'Luka', 23, 15, 'Ba si manö göi Herode; noa sa ifatenge mangawuli khöda, ba hiza, ba lö nifazökhinia börö wamunu ya''ia.', '["Yoh 19:1"]', NULL),
  (3393948, 'NT', 'Luka', 23, 16, 'Ba da''u''otu''ö manö ia, ba u''efa''ö.[7]', '["Yoh 19:1"]', NULL),
  (3393948, 'NT', 'Luka', 23, 18, 'Ba mu''ao ira fefu, lamane: Tibo''ö da''ö, ba efa''ö khöma Mbaraba andrö.', '["Ayati 17-25: Mat 27:15-26; Mar 15:6-15"]', NULL),
  (3393948, 'NT', 'Luka', 23, 19, 'Si no mukuru, börö me molaŵa niha, si no tesao ba mbanua, ba fange''e.', '["Ayati 17-25: Mat 27:15-26; Mar 15:6-15"]', NULL),
  (3393948, 'NT', 'Luka', 23, 20, 'Ba ifuli muhede khöra Wilato, somasi ia, ba Yesu i''efa''ö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 21, 'Ba latema linia, lamane: Foröfa ia! foröfa ia!', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 22, 'Ba imane zui khöra, no medölu: Ba hadia horö, nifazökhi da''ö? Lö nisöndragu khönia hadia ia, börö wamunu ya''ia. Ba da''u''otu''ö ia, ba u''efa''ö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 23, 'Ba lö laböhöi ia, ebua lira, la''andrö, ena''ö laforöfa, ba möna ira, ba we''aora andrö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 24, 'Ba i''etu''ö Filato, ena''ö itörö ni''andröra.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 25, 'Ba i''efa''ö nikuru andrö ba wolaŵa niha ba ba wange''e, ni''andröra, ba Yesu, ba ibe''e ba zomasi ira.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 26, 'Ba me la''ohe ia misa, ba lara''u niha, samösa, Simoni döi, banua Girene, si otarai nowi, lahare''ö khönia röfa, ena''ö i''ohe, moroi furi Yesu.[9]', '["Mat 27:31-32; Mat 15:20,21; Yoh 19:16 b.t."]', NULL),
  (3393948, 'NT', 'Luka', 23, 27, 'Ba ato zolo''ö ya''ia niha, awö ndra alawe, sange''esi ya''ia, mege-ege.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 28, 'Ba ibali''ö ia khöra Yesu, imane: He ya''ami, ono alawe, banua Yeruzalema! böi mi''e''e ba khögu, ba ba khömi mi''e''e, ba ba ndraonomi.', '["Mat 24:19","Yes 2:19; Hos 10:8; Fam 6:16","FetI 4:17,18"]', NULL),
  (3393948, 'NT', 'Luka', 23, 29, 'Hiza sa, irugi baŵa dania, ba lamane: Ya''ahowu zi lö ono, talu si lö irai mo''ono, awö meme, si lö irai mamaenu ono.[10]', '["Mat 24:19","Yes 2:19; Hos 10:8; Fam 6:16","FetI 4:17,18"]', NULL),
  (3393948, 'NT', 'Luka', 23, 30, 'Ba da''ö dania labörötaigö laŵa''ö ba hili: Milangögö ndra''aga! ba ba hili-hili: Mibalugö ndra''aga![11]', '["Mat 24:19","Yes 2:19; Hos 10:8; Fam 6:16","FetI 4:17,18"]', NULL),
  (3393948, 'NT', 'Luka', 23, 31, 'Na lamanö sa ba geu sauri, ba hadia nilau ba gadolu?[12]', '["Mat 24:19","Yes 2:19; Hos 10:8; Fam 6:16","FetI 4:17,18"]', NULL),
  (3393948, 'NT', 'Luka', 23, 32, 'Ba darua tö na la''ohe sebua horö, ba wamunu ya''ira awönia.[13]', '["Faigi 22:37"]', NULL),
  (3393948, 'NT', 'Luka', 23, 33, 'Ba me no larugi naha andrö,[14] sotöi sokamu''u, ba laforöfa ia ba da''ö, awö zebua horö no mege, samösa ba gambölö ba samösa ba gabera.', '["Ayati 33-43: Mat 27:33-44; Mar 15:22-32; Yoh 19:17-24"]', NULL),
  (3393948, 'NT', 'Luka', 23, 34, 'Ba imane Yesu: He Ama, be''e aefa khöra, lö''ö sa la''ila hadia nilaura.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 35, 'Ba so ba da''ö niha sato, lafaigi-faigi. Ba la''o''aya ia salaŵa, lamane: Niha bö''ö no i''orifi, yamu''orifi göi ia, na Keriso Lowalangi andrö ia, nituyu andrö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 36, 'Ba la''o''aya ia göi saradadu, möi ira khönia,', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 37, 'la''ohe önia nirö aisö, ba lamane: Na razo niha Yehuda ndra''ugö, ba orifi ndra''ugö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 38, 'Ba so göi zura yaŵania: "Razo niha Yehuda da''e".', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 39, 'Ba si samösa niforöfa andrö, sebua horö, ba itandraŵaisi, imane: Tenga Keriso andrö ndra''ugö? orifi ndra''ugö, ba ya''aga.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 40, 'Ba itema linia si samösa, itegu, imane: Ba ya''ugö göi zi lö mangata''ufi Lowalangi, he no faoma hukumi?', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 41, 'Ba satulö sa khöda, sanema luo nifazökhida sa''ae ita, ba da''e, ba lö nifazökhinia si lö göna.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 42, 'Ba imane: He Yesu! törö tödöu ndra''odo, na möi''ö ba mbanuau andrö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 43, 'Ba imane khönia: Si ndruhu niŵa''ögu khöu, ma''ökhö andre awögu ndra''ugö ba waradaiso andrö.[16]', '["Yoh 5:24; KorII 12:4; Fam 14:13"]', NULL),
  (3393948, 'NT', 'Luka', 23, 44, 'Ba mato laluo sa''ae,[17] ba tobali ogömi-gömi ba danö, ma''asagörö,', '["Ayati 44-49: Mat 27:45-56; Mar 15:33-41; Yoh 19:28-30"]', NULL),
  (3393948, 'NT', 'Luka', 23, 45, 'irugi labözi tölu, taya haga luo, ba asika mba''a-ba''a andrö, ba gosali, fabali.', '["Ayati 44-49: Mat 27:45-56; Mar 15:33-41; Yoh 19:28-30"]', NULL),
  (3393948, 'NT', 'Luka', 23, 46, 'Ba mu''ao Yesu, ebua linia, imane: He Ama, ba dangau utou''ö nosogu. Ba me aefa iŵa''ö da''ö, ba aetu nosonia.[18]', '["Sin 31:6"]', NULL),
  (3393948, 'NT', 'Luka', 23, 47, 'Ba me i''ila da''ö fefu kumandra andrö, ba isuno Lowalangi, imane: Si ndruhu, niha satulö niha da''ö.', '["Faigi 18:13"]', NULL),
  (3393948, 'NT', 'Luka', 23, 48, 'Ba dozi niha satö, si no möi mamaigi da''ö, me la''ila da''ö fefu, ba labözi dötö''ara ba lafuli ira.[19]', '["Faigi 18:13"]', NULL),
  (3393948, 'NT', 'Luka', 23, 49, 'Ba so göi ba zaröu ma''ifu fefu zi no fa''ila li khönia, awö ndra alawe andrö, si no molo''ö ya''ia moroi ba Galilaia, ba la''ila da''ö.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 50, 'Ba hiza niha,[20] Yosefo döi, salaŵa rafe, niha si sökhi, satulö tödö,', '["Ayati 50-56: Mat 27:57-61; Mar 15:42-47; Yoh 19:38-42","Faigi 2:25,38"]', NULL),
  (3393948, 'NT', 'Luka', 23, 51, '- lö nitehenia huhuora andrö, awö nilaura - banua Garimatia, banua niha Yehuda andrö, sombalo-mbaloi banua Lowalangi andrö.[21]', '["Ayati 50-56: Mat 27:57-61; Mar 15:42-47; Yoh 19:38-42","Faigi 2:25,38"]', NULL),
  (3393948, 'NT', 'Luka', 23, 52, 'Da''ö zi möi khö Wilato, mangandrö boto Yesu.', '["Ayati 50-56: Mat 27:57-61; Mar 15:42-47; Yoh 19:38-42","Faigi 2:25,38"]', NULL),
  (3393948, 'NT', 'Luka', 23, 53, 'Ba ihalö tou, i''olohuni muko, ba ibe''e ba lewatö nikhao ba gara, ba zi lö larai lako''o niha.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 54, 'Ba baŵa wangehao, ibörötaigö luo sabato.', '[]', NULL),
  (3393948, 'NT', 'Luka', 23, 55, 'Ba ira alawe andrö, solo''ö, si no molo''ö ya''ia moroi ba Galilaia, ba lafaigi lewatö andrö ba he lawisa wogo''o botonia.', '["Mar 16:1; MozII 20:10"]', NULL),
  (3393948, 'NT', 'Luka', 23, 56, 'Ba lafuli ira, la''asiwai zamohua, awö wanikha, ba ba luo sabato, ba ahono ira, la''o''ö goroisa.[22]', '["Mar 16:1; MozII 20:10"]', NULL),
  (3393949, 'NT', 'Luka', 24, 1, 'Ba me luo migu,[1] ba möi ira ba lewatö, ahulö sibai, la''ohe zamohua andrö, ni''asiwaira.', '["Ayati 1-11: Mat 28:1-8; Mar 16:1-11; Yoh 20:1-18"]', NULL),
  (3393949, 'NT', 'Luka', 24, 2, 'Ba la''ila, no mufagaölö gowe andrö, no aheta ba lewatö.', '["HalZin 1:10"]', NULL),
  (3393949, 'NT', 'Luka', 24, 3, 'Ba me möi ira bakha, ba lö lasöndra mboto Yesu, So''aya.', '["HalZin 1:10"]', NULL),
  (3393949, 'NT', 'Luka', 24, 4, 'Ba me la''abusi tödö da''ö, ba hiza niha, darua, no so ba ngaira, no mobaru safusi, sihaga.[2]', '["HalZin 1:10"]', NULL),
  (3393949, 'NT', 'Luka', 24, 5, 'Ba me ata''u ira, ba me lafatugu ira, ba lamane khöra: Hadia wa mi''alui zauri ba zi mate?', '["Faigi 18:31 b.t.; Mat 17:22 b.t."]', NULL),
  (3393949, 'NT', 'Luka', 24, 6, 'Lö ya''ia ba da''e, noa sa maoso ia; mitörö-törö tödömi niŵa''önia khömi, me so ia ba Galilaia na,', '["Faigi 18:31 b.t.; Mat 17:22 b.t."]', NULL),
  (3393949, 'NT', 'Luka', 24, 7, 'me itörö linia Nono Niha andrö, wa lö tola lö tebe''e ia ba danga niha si so horö, awö wa niforöfa, ia, awö wemaosonia, na no irugi tölu ngaluo.[3]', '["Faigi 18:31 b.t.; Mat 17:22 b.t."]', NULL),
  (3393949, 'NT', 'Luka', 24, 8, 'Ba itörö tödöra niŵa''önia andrö.[4]', '["Yoh 2:22"]', NULL),
  (3393949, 'NT', 'Luka', 24, 9, 'Ba lafuli ira, laröi lewatö, la''ombakha''ö da''ö fefu ba zi felezara andrö ba ba danö bö''ö fefu.', '["Faigi 8:2,3"]', NULL),
  (3393949, 'NT', 'Luka', 24, 10, 'Ira Maria, banua Magadala andrö, ira, ba Yohane ba Maria, ina Yakobo ba awöra andrö, la''ombakha''ö da''ö ba zinenge andrö.[5]', '["Faigi 8:2,3"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393949, 'NT', 'Luka', 24, 11, 'Ba ba dödöra, ba hulö waya niŵa''öra andrö, ba lö faduhu dödöra khöra.', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 12, 'Ba maoso Wetero, isaŵa lewatö, fagohi, ba ifaöndrö ia, ba i''ila lembe muko andrö, no so tou, ha da''ö, ba ifuli ia khöra, ahöli-höli dödönia da''ö.[6]', '["Yoh 20:3,6"]', NULL),
  (3393949, 'NT', 'Luka', 24, 13, 'Ba hiza, darua khöra me luo da''ö zi möi ba mbanua side-ide, mato dua za a matonga fofanö, i''otarai Yeruzalema, Ema''usa döi.[7]', '["Mar 16:12,13"]', NULL),
  (3393949, 'NT', 'Luka', 24, 14, 'Ba itörö lira da''ö no mege fefu.', '["Mar 16:12,13"]', NULL),
  (3393949, 'NT', 'Luka', 24, 15, 'Ba me fahuo-huo ira, me lafatunö, ba so Yesu, fao ia khöra ba lala.[8]', '["Mat 18:20"]', NULL),
  (3393949, 'NT', 'Luka', 24, 16, 'Ba tetaha höröra, fa lö la''ila wa ya''ia.', '["Mat 18:20"]', NULL),
  (3393949, 'NT', 'Luka', 24, 17, 'Ba imane khöra: Hadia huo-huo andrö khömi ba lala?', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 18, 'Ba lafatugu ira. Ba itema li si samösa, Kelofasi döinia, imane khönia: Hadia, ha ya''ugö ba dome andrö ba Yeruzalema, si lö mamondrongo da''ö, si bohou na.', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 19, 'Ba imane khöra: Hadia?', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 20, 'Awö wa no lafa''etu''ögö hukunia ere sebua khöma, awö zalaŵa, huku famunu, awö wa no laforöfa.', '["Faigi 7:16,22; HalZin 2:22"]', NULL),
  (3393949, 'NT', 'Luka', 24, 21, 'Ba ya''aga, ba mawai ya''ia zi möi mangorifi Iraono Gizeraeli.', '["Faigi 7:16,22; HalZin 2:22"]', NULL),
  (3393949, 'NT', 'Luka', 24, 22, 'Ba no göi tobali dödöma labe''e ira alawe khöma ösa, si no möi ba lewatö, si hulö wongi.', '["HalZin 1:6"]', NULL),
  (3393949, 'NT', 'Luka', 24, 23, 'Lö nisöndrara botonia, ba so ira, ba laŵa''ö, no la''ila gangilata, mala''ika, sanguma''ö no auri ia.', '["HalZin 1:6"]', NULL),
  (3393949, 'NT', 'Luka', 24, 24, 'Ba no möi nawöma ösa, ba no la''ila, duhu niŵa''ö ndra alawe andrö, ba ya''ia ba lö ni''ilara.', '["HalZin 1:6"]', NULL),
  (3393949, 'NT', 'Luka', 24, 25, 'Ba imane khöra: He ya''ami, sambö era-era, ba sareu tödö wamati fefu hadia ia niŵa''ö zama''ele''ö andrö!', '["FetI 1:11; Heb 2:8 b.t.; Yes 50:5,6; 53:3 b.t."]', NULL),
  (3393949, 'NT', 'Luka', 24, 26, 'Tenga lö tola lö itaögö da''ö Keriso andrö, ba möi ba lakhöminia? [11]', '["FetI 1:11; Heb 2:8 b.t.; Yes 50:5,6; 53:3 b.t."]', NULL),
  (3393949, 'NT', 'Luka', 24, 27, 'Ba i''otarai khö Moze ba ba zama''ele''ö andrö fefu, ibotokhi khöra ba zura andrö fefu hadia ia, ba khönia andrö.[12]', '["MozI 3:15; 22:18; 49:10; MozV 18:15; Sin 22; Yes 9:6; Dan 9:24"]', NULL),
  (3393949, 'NT', 'Luka', 24, 28, 'Ba ahatö sa''ae ira ba mbanua andrö, ba zi möi ira, ba hulö edöna italu''i laŵa''ö.', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 29, 'Ba la''andrö khönia, lamane: Iagö khöma, bongi, lö''ö sa''ae alaŵa yaŵa luo. Ba möi ia yomo, aŵora.', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 30, 'Ba me manga ira, ba ihalö göra roti, ifahowu''ö ba iboboto, ibe''e khöra.[13]', '["Faigi 22:19"]', NULL),
  (3393949, 'NT', 'Luka', 24, 31, 'Ba teboka höröra, ba la''ila wa ya''ia; ba taya manö ia fönara.', '["Faigi 22:19"]', NULL),
  (3393949, 'NT', 'Luka', 24, 32, 'Ba faoma lamane khö naŵora: Tenga no aukhu-aukhu bakha dödöda, me fahuhuo ia khöda ba lala, me ibotokhi khöda zi so ba zura?', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 33, 'Ba maoso ira, ba da''ö sibai, lafuli ira ba Yeruzalema, ba no owulo fönara zi felezara, awö zi fao-fao khöra andrö, ba lamane da''ö:', '["KorI 15:5"]', NULL),
  (3393949, 'NT', 'Luka', 24, 34, 'Si ndruhu, no maoso Zo''aya, ba no i''oroma''ö ia khö Zimoni.[14]', '["KorI 15:5"]', NULL),
  (3393949, 'NT', 'Luka', 24, 35, 'Ba ya''ira, ba ladunö-dunö, he wisa ba lala no mege, ba he wisa wangilara, wa ya''ia, ba wamoboto roti andrö.', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 36, 'Ba me lafatunö da''ö, ba so manö Yesu, ba hunöra bakha.[15]', '["Mar 16:14; Yoh 20:19","Mat 14:26"]', NULL),
  (3393949, 'NT', 'Luka', 24, 37, 'Ba tobali dödöra ba ata''u ira, lawai bekhu ni''ilara [16]', '["Mar 16:14; Yoh 20:19","Mat 14:26"]', NULL),
  (3393949, 'NT', 'Luka', 24, 38, 'Ba imane khöra: Hadia wa tokea ami, ba hana wa manufa dödömi?', '["YohI 1:1"]', NULL),
  (3393949, 'NT', 'Luka', 24, 39, 'Mifaigi dangagu ba ahegu, wa ya''odo; mibabaya ndra''o, ba mifaigi, ba mbekhu sa, ba lö nagole, ba lö töla, si mane ni''ilami khögu.[17]', '["YohI 1:1"]', NULL),
  (3393949, 'NT', 'Luka', 24, 40, 'Ba me iŵa''ö da''ö, ba i''oroma''ö khöra gahe ba tanga.[18]', '["Yoh 20:20,25,27; Sin 22:17"]', NULL),
  (3393949, 'NT', 'Luka', 24, 41, 'Ba me lö faduhu dödöra na, ba wa''omuso dödö, ba me ahöli-höli dödöra, ba imane khöra: Hadia, so göda ma''ifu khömi ba da''e?', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 42, 'Ba labe''e khönia gi''a nisala ösa.', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 43, 'Ba ihalö, i''a fönara.', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 44, 'Ba imane khöra: Da''ö niŵa''ögu khömi, me sodo khömi na, wa lö tola lö itörö fefu zi so ba zura goroisa andrö khö Moze ba ba zura zama''ele''ö ba ba zura zinunö, ba khögu andre.[19]', '["Mat 16:21; HalZin 2:25 b.t.","HalZin 17:3"]', NULL),
  (3393949, 'NT', 'Luka', 24, 45, 'Awena ibokai dödöra, fa aboto ba dödöra zi so ba zura.[20]', '["Mat 16:21; HalZin 2:25 b.t.","HalZin 17:3"]', NULL),
  (3393949, 'NT', 'Luka', 24, 46, 'Ba imane khöra: Si manö ba zura, sanaögö famakao Keriso ba si maoso moroi ba ngai zi mate, na no irugi tölu ngaluo,', '["Mat 24:14; HalZin 2:38; 13:38","Yoh 14:26; 16:7; HalZin 1:4,8"]', NULL),
  (3393949, 'NT', 'Luka', 24, 47, 'ba ni''o''mbakha''ö wamalalini era-era ba fangefa horö, ba döinia, ba niha fefu misa, nibörötaigö ba Yeruzalema.[21]', '["Mat 24:14; HalZin 2:38; 13:38","Yoh 14:26; 16:7; HalZin 1:4,8"]', NULL),
  (3393949, 'NT', 'Luka', 24, 48, 'Ya''ami zi so ba mbörö ba da''ö.', '["Mat 24:14; HalZin 2:38; 13:38","Yoh 14:26; 16:7; HalZin 1:4,8"]', NULL),
  (3393949, 'NT', 'Luka', 24, 49, 'Ba ufatenge ba khömi nifabu''u Namagu andrö; ba ya''ami, ba sahono ba mbanua, irege no te''abölö''ö ami fa''abölö andrö moroi si yaŵa.[22]', '["Mat 24:14; HalZin 2:38; 13:38","Yoh 14:26; 16:7; HalZin 1:4,8"]', NULL),
  (3393949, 'NT', 'Luka', 24, 50, 'Ba i''ohe ira baero, irugi tanö ba Mbetania andrö, ba ifazaŵa dangania, ifahowu''ö ira.', '[]', NULL),
  (3393949, 'NT', 'Luka', 24, 51, 'Ba barö wamahowu''önia ya''ira, ba aheta ia khöra.[23]', '["Mar 16:19; HalZin 1:9 b.t.; Yoh 20:17"]', NULL),
  (3393949, 'NT', 'Luka', 24, 52, 'Ba lafuli ira ba Yeruzalema, omuso sibai dödöra.[24]', '["Yoh 5:23; 16:22","HalZin 1:14"]', NULL),
  (3393949, 'NT', 'Luka', 24, 53, 'Ba lö tebulö ba gosali so ira, manuno Lowalangi.[25]', '["Yoh 5:23; 16:22","HalZin 1:14"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 1, 'Ba mböröta so daroma li andrö, ba khö Lowalangi daroma li andrö, ba taroma li andrö, ba no Lowalangi.[1]', '["Faigi 17:5; 8:58; YohI 1:1 b.t.; 5:20; Fam 19:19"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 2, 'Khö Lowalangi so ia ba mböröta.[2]', '["Amaed 8:22 b.t.","KorI 8:6; Kol 1:16; Heb 1:2; 11:3; Sin 33:6"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 3, 'Khönia mböröta hadia ia fefu. Sambalö lö''ö, si so, si tenga khönia mböröta.[3]', '["Amaed 8:22 b.t.","KorI 8:6; Kol 1:16; Heb 1:2; 11:3; Sin 33:6"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 4, 'Khönia so wa''auri, ba haga ba niha wa''auri andrö.[4]', '["Faigi 5:26; 14:6; 8:22; YohI 5:11–12","KorII 4:6; Luk 1:78 b.t.; Faigi 3:19; 9:5"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 5, 'Ba humaga haga andrö, ba zogömi-gömi, ba lö ihalö ia sogömi-gömi.[5]', '["Faigi 5:26; 14:6; 8:22; YohI 5:11–12","KorII 4:6; Luk 1:78 b.t.; Faigi 3:19; 9:5"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 6, 'So niha, nifatenge Lowalangi, Yohane döinia.[6]', '["Luk 3:2 b.t.","Faigi 5:33 b.t."]', NULL),
  (3391599, 'NT', 'Yohane', 1, 7, 'Da''ö zi möi mamaduhu''ö, ena''ö ifaduhu''ö haga andrö, ena''ö dozi mamati khönia.[7]', '["Luk 3:2 b.t.","Faigi 5:33 b.t."]', NULL),
  (3391599, 'NT', 'Yohane', 1, 8, 'Tenga ya''ia haga andrö, ha ba wamaduhu''ö haga andrö.[8]', '["Faigi 3:28"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 9, 'Möi sa''ae ba guli danö haga si ndruhu andrö, sohagaini niha fefu.[9]', '["Faigi 12:46","Ayati 3–5","Faigi 19:15; Mat 13: 57; Sin 69:9"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 10, 'No so Ia ba guli danö, ba khö-Nia mböröta hadia ia, fefu, ba lö aboto Ia ba dödö niha ba guli danö.[10]', '["Faigi 12:46","Ayati 3–5","Faigi 19:15; Mat 13: 57; Sin 69:9"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 11, 'No khö-Nia ba zi möi Ia, ba lö lafonaha ia khöra banua-Nia.[11]', '["Faigi 12:46","Ayati 3–5","Faigi 19:15; Mat 13: 57; Sin 69:9"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 12, 'Ba ha wa''ato zamonaha Ya''ia, khöra itehe, tobali ono Lowalangi ira, khö zamati ba döi-Nia andrö.[12]', '["Hos 1:10; YohI 3:1; Gal 3:26"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 13, 'Tenga moroi ba ndro tumbu ira, ba tenga moroi ba wa''edöna nösi niha ba tenga moroi ba wa''edöna ndra matua, moroi ba Lowalangi tumbu ia.[13]', '["Faigi 3:3 b.t.; Zak 1:18; FetI 1:23; YohI 5:1–4"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 14, 'Ba no tobali ösi niha daroma li andrö, ba no so ia khöda, ba no anehega lakhömi-Nia, hulö lakhömi Nono, si ha sambua khö Nama, si no a''oi so fa''ebua dödö, awö wa''aduhu.[14]', '["Ayati 1; Faigi 11:40; YohI 4:2–9; Mat 17:2; TimI 3:16; FetII 1:16 b.t."]', NULL),
  (3391599, 'NT', 'Yohane', 1, 15, 'Ifaduhu''ö Ia Yohane, mu''ao ia, imane: Ya''ia da''ö, niŵa''ögu: Fönagu zi so furigu dania, me no oföna Ia moroi khögu.[15]', '["Mat 3:11"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 16, 'Me no manema ita fefu fa''ebua dödö si lö aetu-aetu moroi ba zi no a''oi so khö-Nia.[16]', '["Kol 1:19; 2:9"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 17, 'Sama''ema oroisa Moze, ba khö Yesu Keriso mböröta wa''ebua dödö ba böröta wa''aduhu.[17]', '["HalZin 7:38; Sin 89:3-15"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 18, 'Lö irai i''ila Lowalangi niha, da''ö zanutunö khöda, Ono andrö, si ha sambua, si so ba gaheta Nama.[18]', '["Faigi 6:46; MozII 33:20; Mat 11:27"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 19, 'Ba da''ö wamaduhu''ö Yohane, me lafatenge khönia gere, awö nono Lewi, niha Yehuda, banua Yeruzalema, ba wanofu khönia: Ha niha ndra''ugö?[19]', '["Faigi 5:33"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 20, 'Ba i''ombakha''ö: tenga Keriso andrö ndra''o.[20]', '["Faigi 3:28; HalZin 13:25"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 21, 'Ba lasofu khönia: Ba hadia? Eliya ndra''ugö? Imane: Tenga. Lamane: Ya''ugö zama''ele''ö andrö? Imane: Tenga.[21]', '["Mat 11:14"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 22, 'Ba lamane khönia: Ba ha niha ndra''ugö? Ena''ö maŵa''ö khö zamatenge ya''aga. Hadia niŵa''öu ba khöu andrö?', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 23, 'Imane: "Li zi''ao ba danö si mate ndra''o: Mifadaya lala Zo''aya, si mane niŵa''ö Yesaya andrö, sama''ele''ö".[22]', '["Yes 40:3"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 24, 'Ba sinenge warizaio zinenge andrö.', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 25, 'Ba lasofu khönia, lamane khönia: Ba hana wa mamayagö idanö ndra''ugö na tenga Keriso andrö ndra''ugö, ba tenga Eliya, ba na tenga sama''ele''ö andrö?', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 26, 'Itema lira Yohane, imane: Samayagö idanö ndra''o; no so khömi zi lö mi''ila,[23]', '["Mat 3:11","Ayati 15; Mal 3:1"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 27, 'si so furigu; no ambö ndra''o khönia, utoto''ö mböbö mbadagahenia.[24]', '["Mat 3:11","Ayati 15; Mal 3:1"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 28, 'Ba Mbetania da''ö, yefo Yoridano, ba da''ö mamayagö idanö Yohane.[25]', '["Faigi 10:40"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 29, 'Ba sara wongi aefa da''ö, ba i''ila Yesu, si möi khönia, ba imane: Hiza nono mbiri-biri andrö khö Lowalangi, sangeheta horö nösi guli danö.[26]', '["Yes 53:5–7 b.t."]', NULL),
  (3391599, 'NT', 'Yohane', 1, 30, 'Da''ö niŵa''ögu: Furigu so dania niha, si no fönagu, me no oföna ia moroi khögu.', '["Yes 53:5–7 b.t."]', NULL),
  (3391599, 'NT', 'Yohane', 1, 31, 'Ba lö aboto ba dödögu ia, ba ena''ö oroma ia ba Ndraono Gizeraeli, andrö möi ndra''o, mamayagö idanö.', '["Yes 53:5–7 b.t."]', NULL),
  (3391599, 'NT', 'Yohane', 1, 32, 'Ba mamaduhu''ö Yohane, imane: No u''ila Geheha, si möi tou, moroi ba zorugo, hulö marafadi ia ba ahono ia khönia.[27]', '["Mat 3:16 b.t.","HalZin 1:5","Faigi 3:34–36"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 33, 'Ba lö aboto ba dödögu ia, ba samatenge ya''o, ba wamayagö idanö, da''ö zanguma''ö khögu: ni''ilau si möi tou Eheha, ba ahono khönia, da''ö zamayagö Eheha ni''amoni''ö niha.[28]', '["Mat 3:16 b.t.","HalZin 1:5","Faigi 3:34–36"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 34, 'Ba no u''ila ia ba no ufaduhu''ö, wa Ono Lowalangi da''ö.[29]', '["Mat 3:16 b.t.","HalZin 1:5","Faigi 3:34–36"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 35, 'Ba sara wongi aefa da''ö, ba so zui Yohane, awö nifahaönia, darua.', '["FetI 1:18"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 36, 'Ba inehegö Yesu, sanörö, ba imane: Hiza nono Mbiri-biri andrö, khö Lowalangi.[30]', '["FetI 1:18"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 37, 'Larongo niŵa''önia nifahaönia, si darua andrö, ba la''o''ö Yesu.', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 38, 'Ba ibali''ö ia furi Yesu, ifaigi ira, solo''ö ba imane khöra: Hadia ni''aluimi?', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 39, 'Ba lamane khönia: Hezo nahiau omo, Rabi? samahaö geluahania.', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 40, 'Imane khöra: Mi''ae mifaigi.', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 41, 'Samösa Gandrea, talifusö Zimoni Fetero, samondrongo khö Yohane, solo''ö Yesu.', '["Dan 9:25; Sin 2:2"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 42, 'Ba oföna falukha da''ö khö dalifusönia Simoni andrö, ba imane khönia: No masöndra Mesia andrö; nibayoini (Keriso) geluahania.[32]', '["Dan 9:25; Sin 2:2"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 43, 'Ba i''ohe khö Yesu.', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 44, 'Ba mahemolu ö, ba mofanö Yesu, ena''ö isaŵa Galilaia, ba falukha ia Wilifo. Ba imane khönia Yesu: O''ö ndra''o.', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 45, 'Ba banua Mbetisa''ida Wilifo andrö, banua ndra Andrea Fetero.', '["Faigi 21:2; Luk 24:27; 3:33; Yes 7:14; Yer 23:5 b.t"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 46, 'Falukha khö Natana''eli Wilifo andrö, ba imane khönia: No masöndra nisura Moze ba zura goroisa, nisura zama''ele''ö, Yesu andrö, ono Yosefo, banua Nazareta.[34]', '["Faigi 21:2; Luk 24:27; 3:33; Yes 7:14; Yer 23:5 b.t"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 47, 'Imane khönia Natana''eli: So zi sökhi, si otarai Nazareta? Imane khönia Filifo: Ae faigi.[35]', '["Faigi 7:41–52"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 48, 'I''ila Natana''eli andrö, si möi khönia, Yesu, ba imane khönia: Hiza zi ndruhu Ndraono Gizeraeli, si lö falimosa ba dödö.', '[]', NULL),
  (3391599, 'NT', 'Yohane', 1, 49, 'Imane khönia Natana''eli: He moroi ö''ila ndra''o? Itema linia Yesu, imane khönia: Me lö nikaoni Wilifo ya''ugö na, me so''ö ba mbörö marafala andrö, ba no u''ila''ö.[36].', '["Sin 139:1 b.t."]', NULL),
  (3391599, 'NT', 'Yohane', 1, 50, 'Imane khönia Natana''eli: He Rabi, ono Lowalangi ndra''ugö, razo Ndraono Gizeraeli![37]', '["Faigi 12:13; Mat 16:16"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 51, 'Itema linia Yesu, imane khönia: Me no uŵa''ö khöu, no u''ila''ö, ba mbörö marafala andrö, andrö mamati ndra''ugö! So dania ni''ilau, sebua moroi andrö.', '["Faigi 3:13; MozI 28:12"]', NULL),
  (3391599, 'NT', 'Yohane', 1, 52, 'Ba imane na khönia: Si ndruhu-ndruhu niŵa''ögu khömi, mi''ila dania, teboka mbanua si yaŵa, ba mangörö-ngörö miyaŵa ba mitou mala''ika Lowalangi, khö Nono Niha.[38]', '["Faigi 3:13; MozI 28:12"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 1, 'Dua wongi aefa da''ö, ba so walöŵa ba Kana ba Galilaia, ba so nina Yesu ba da''ö.[1]', '["Faigi 1:44"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 2, 'Ba lakaoni göi Yesu, awö nifahaönia, ba walöŵa andrö.', '[]', NULL),
  (3391600, 'NT', 'Yohane', 2, 3, 'Ba lö agu khöra, me no ahori nagu walöŵa. Ba imane ina Yesu khönia: Lö agu.', '[]', NULL),
  (3391600, 'NT', 'Yohane', 2, 4, 'Imane khönia Yesu: Hana ndra''ugö khögu, alawe? Tenga na inötö khögu.', '[]', NULL),
  (3391600, 'NT', 'Yohane', 2, 5, 'Imane inania ba genoni andrö: Na so niŵa''önia khömi, ba mi''o''ö.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391600, 'NT', 'Yohane', 2, 6, 'Ba so ba da''ö rumbi, önö, naha nidanö, ba wanasa khöra, huku khöra ba niha Yehuda, fa tölu yöu zambua.[2]', '["Mar 7:3 b.t."]', NULL),
  (3391600, 'NT', 'Yohane', 2, 7, 'Imane khöra Yesu: Mifönui idanö rumbi andrö. Ba lafönui irugi mbewe.', '[]', NULL),
  (3391600, 'NT', 'Yohane', 2, 8, 'Ba imane khöra: Misou sa''ae, ba mi''ohe khö zatua zangai halöŵö. Ba la''ohe.', '[]', NULL),
  (3391600, 'NT', 'Yohane', 2, 9, 'Ba me no itandra satua zangai halöŵö nidanö andrö, si no tobali agu, ba me lö i''ila, he moroi — ba la''ila sa enoni andrö sana''u idanö andrö — ba humede zatua zangai halöŵö khö zangowalu,[3]', '["Faigi 4:46"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 10, 'imane khönia: Oföna labe''e nagu si sökhi dozi niha, ba dania, na no abuso ira, ba labe''e zambö fa''asökhi; ba ya''ugö, ba no ötenagö nagu si sökhi, irugi da''e.', '["Faigi 4:46"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 11, 'Ba Kana ba Galilaia ilau da''ö Yesu, böröta dandra andrö, i''oroma''ö lakhöminia, ba mamati khönia nifahaönia andrö.[4]', '["Faigi 1:14"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 12, 'Aefa da''ö möi ia misi tou, ba Gafanauma, ya''ia ba inania ba talifusönia ba nifahaönia. Ba lö ara ira ba da''ö.[5]', '["Mat 4:13, 13:55"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 13, 'Ba no ahatö gowasa fasa ba niha Yehuda, ba möi misi yaŵa Yesu ba Yeruzalema.[6]', '["Faigi 6:4"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 14, 'Ba i''ila ba gosali zamawa saŵi ba biri-biri ba marafadi, awö zanuka ana''a, si dadao ba da''ö.[7]', '["Mat 21:12 b.t."]', NULL),
  (3391600, 'NT', 'Yohane', 2, 15, 'Ba ifazökhi mbözi-bözi sinali, ba ifofanö ira fefu ba gosali, ba biri-biri ba saŵi andrö; ba iduwagö gana''a zanuka andrö, iso''agö meza khöra.', '["Mat 21:12 b.t."]', NULL),
  (3391600, 'NT', 'Yohane', 2, 16, 'Ba imane ba zamawa marafadi: Mi''ohe misa da''ö, böi mibali''ö kade nomo Namagu.', '["Mat 21:12 b.t."]', NULL),
  (3391600, 'NT', 'Yohane', 2, 17, 'Ba itörö tödö nifahaönia niŵa''ö ba zura: "No i''ado fönu andrö ba nomomö."[8]', '["Sin 69:10"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 18, 'Ba latema linia niha Yehuda, lamane khönia: Hadia dandra, ni''oroma''öu khöma, wa tola ölau da''ö?[9]', '["Faigi 6:30"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 19, 'Itema lira Yesu, imane khöra: Midudugö gosali andre, ba ha tölu ngaluo, ba u''azökhi.[10]', '["Mat 26:61"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 20, 'Ba lamane khönia niha Yehuda; Öfa wulu a önö fakhe wangotomosi osali andre, ba ha tölu ngaluo ö''azökhi.', '[]', NULL),
  (3391600, 'NT', 'Yohane', 2, 21, 'Ba osali botonia niŵa''önia.[11]', '["KorII 5:1"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 22, 'Ba dania, me no maoso ia moroi ba ngai zi mate, ba itörö tödö nifahaönia niŵa''önia andrö, ba faduhu dödöra ba zi so ba zura, ba ba niŵa''ö Yesu.[12]', '["Luk 24:8-44,45"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 23, 'Ba me so ia ba Yeruzalema, ba gowasa fasa, ba ato zamati ba döinia, me la''ila dandra andrö khönia, nifazökhinia.[13]', '["Faigi 4:48","Faigi 6:64; Mar 2:8"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 24, 'Ba lö faduhu dödö Yesu khöra, börö wa''aboto ba dödönia ira,[14]', '["Faigi 4:48","Faigi 6:64; Mar 2:8"]', NULL),
  (3391600, 'NT', 'Yohane', 2, 25, 'awö wa lö moguna khönia, la''ombakha''ö khönia niha; noa sa i''ila manö, ha ya''ia, hadia zi so ba dödö niha.', '["Faigi 4:48","Faigi 6:64; Mar 2:8"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 1, 'Ba so niha, farizaio, Nikodemo döinia, salaŵa ba niha Yehuda. [1]', '["Faigi 7:50. 19:39"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 2, 'Da''ö zi möi khö Yesu ba zi bongi, imane khönia: He samahaö? ma''ila, samahaö si otarai Lowalangi ndra''ugö, me samösa lö sangila mamazökhi tandra andrö, nifazökhiu, na lö itolo ia Lowalangi. [2]', '["Faigi 9:24-33; HalZin 10:38; Luk 20:21"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 3, 'Itema linia Yesu, imane khönia: Si ndruhu-ndruhu niŵa''ögu khöu, na lö tumbu moroi si yaŵa niha, ba tebai i''ila mbanua Lowalangi andrö. [3]', '["Faigi 1:13; YohI 3:9"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 4, 'Imane khönia Nikodemo: He iwisa tumbu niha, na no atua ia? Hadia, i''ila ifuli ia ba dalu ninania, ba ifuli tumbu? [4]', '["KorII 5:17"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 5, 'Itema linia Yesu: Si ndruhu-ndruhu niŵa''ögu khöu, na lö tumbu moroi ba nidanö ba moroi ba Geheha niha, ba tebai möi la ba mbanua zorugo andrö. [5]', '["Hes 36:25 b. t; Tit 3:5"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 6, 'Ösi niha zi tumbu ba nösi niha, ba eheha zi tumbu khö Geheha. [6]', '["MozI 5:3; 6:3; Sin 51:7"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 7, 'Böi ahöli-höli dödöu, me no uŵa''ö khöu, lö tola lö tumbu moroi si yaŵa ami.', '[]', NULL),
  (3391601, 'NT', 'Yohane', 3, 8, 'Angi andrö, ba isaŵa zomasi ia, ba örongo höngö-höngönia, ba lö ö''ila, heza i''otarai, ba heza isaŵa. Si manö göi dozi si tumbu khö Geheha. [7]', '["Sangomb 11:5"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 9, 'Itema linia Nikodemo, imane khönia: He wisa lala da''ö? [8]', '["Luk 1:34-35"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 10, 'Itema linia Yesu, imane khönia: Samahaö Iraono Gizeraeli ndra''ugö, ba lö aboto ba dödöu da''ö? [9]', '["MozV 30:6; Sin 51:12; Hes 11:19."]', NULL),
  (3391601, 'NT', 'Yohane', 3, 11, 'Si ndruhu-ndruhu niŵa''ögu khöu, saboto ba dödöma maŵa''ö, ba ni''ila höröma mafaduhu''ö, ba lö mirema wamaduhu''öma.', '[]', NULL),
  (3391601, 'NT', 'Yohane', 3, 12, 'Na lö mamati ami, na uŵa''ö khömi zi so ba guli danö, ba he miwisa wamati, na uŵa''ö khömi zi so ba zorugo?', '[]', NULL),
  (3391601, 'NT', 'Yohane', 3, 13, 'Ba lö si möi yaŵa ba zorugo, baero zi no möi tou, si otarai zorugo, Ono Niha andrö, si so ba zorugo. [10]', '["Faigi 6:38; 62; Efes 4:9 b.t."]', NULL),
  (3391601, 'NT', 'Yohane', 3, 14, 'Ba hulö gulö andrö, nituwu Moze yaŵa, ba danö si mate, si manö göi te''alaŵa''ö yaŵa dania Nono Niha, lö tola lö''ö, [11]', '["MozIV 21:8-9; Faigi 12:32-33","Mar 16:16; Rom 3:25"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 15, 'ena''ö so wa''auri si lö aetu ba zamati khönia fefu. [12]', '["MozIV 21:8-9; Faigi 12:32-33","Mar 16:16; Rom 3:25"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 16, 'Si manö sa wa''omasi Lowalangi nösi guli danö, no ibe''e Nononia andrö, si ha sambua, ena''ö lö tekikö dozi samati khönia, ena''ö so khöra wa''auri si lö aetu. [13]', '["YohI 4:9; Rom 8:32"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 17, 'Tenga sa ba wanguhuku ösi guli danö ifatenge ba guli danö Nononia Lowalangi, afu-afunia te''orifi khönia nösi guli danö. [14]', '["Faigi 12:47; Luk 9:56; Mat 18:11"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 18, 'Samati khönia ba lö lahuku, ba si no muhuku zi lö mamati, me lö mamati ia ba döi Nono Lowalangi andrö, si ha sambua. [15]', '["Faigi 5:24; TesII 2:12"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 19, 'Da''ö wanguhuku; no möi ba guli danö haga andrö, ba no omasi niha da''ogömi-gömi, moroi ba haga, me si lö sökhi mbua-buara. [16]', '["Faigi 1:4 b.t."]', NULL),
  (3391601, 'NT', 'Yohane', 3, 20, 'Dozi lö omasi haga zamazökhi si lö sökhi, ba lö la''ondrasi haga, fa lö te''otu''ö ira ba nifazökhira andrö. [17]', '["Efes 5:13; Yob 24:13—16"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 21, 'Ba i''ondrasi haga samazökhi si duhu, ena''ö oroma mbua-buania, me nilau ba khö Lowalangi. [18]', '["Mat 5:16"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 22, 'Aefa da''ö, ba möi ba danö Yudaia Yesu, awö nifahaönia, ba da''ö so ia, ba soso ira khönia, ba mamayagö idanö ia. [19]', '["Faigi 4:1-2"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 23, 'Ba Yohane göi, mamayagö idanö göi, ba Gaino, ba zi tambai Zalima, me ebua nidanö ba da''ö, ba möi ba da''ö niha lafabayagö''ö idanö ira.', '[]', NULL),
  (3391601, 'NT', 'Yohane', 3, 24, 'Lö''ö na sa mube''e ba gurunga Yohane. [20]', '["Mat 14:3"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 25, 'Ba fagua-gua ira, nifahaö Yohane niha Yehuda, ba wangehao andrö.', '[]', NULL),
  (3391601, 'NT', 'Yohane', 3, 26, 'Ba möi ira khö Yohane, ba lamane khönia: He samahaö! faigi da''ö, mamayagö idanö da''ö no, si no möi khöu, yefo Yoridano, nifaduhu''ömö, ba dozi niha zangondrasi ya''ia. [21]', '["Faigi 1:25—34; Mat 3:11-13 b.t."]', NULL),
  (3391601, 'NT', 'Yohane', 3, 27, 'Itema lira Yohane, imane: Tebai ihalö khönia hadia ia niha, na tenga nibe''e khönia moroi ba zorugo. [22]', '["KorI 4:7"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 28, 'Ya''ami zi so ba mbörö khögu, wa no uŵa''ö: Tenga Keriso andrö ndra''o, nifatenge ndra''o fönania. [23]', '["Faigi 1: 20-30"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 29, 'Ha ökhö so nono nihalö, da''ö zangowalu, ba omuso sibai dödö zi fahuwu khö zangowalu andrö, si so ba da''ö ba wamondrondrongo khönia, na irongo li zangowalu; ba na a''oi so wa''omuso dödö andrö khögu. [24]', '["Mat 9:15"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 30, 'Lö tola lö manöi ia, ba lö töla lö awuwu ndra''o.', '[]', NULL),
  (3391601, 'NT', 'Yohane', 3, 31, 'No föna danö bö''ö fefu zi otarai si yaŵa. Moroi ba guli danö, zi otarai guli danö, ba moroi ba guli danö hedehe-denia. Ba si otarai zorugo, [25]', '["Faigi 3:23; KorI 15:47"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 32, 'ba ni''ila hörönia, awö nirongonia, ifaduhu''ö, ba lö samati famaduhu''önia. [26]', '["Faigi 3:11; 1:11"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 33, 'Samati famaduhu''önia, ba i''a''aro''ö, wa no si ndruhu Lowalangi. [27]', '["YohI 5:10"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 34, 'Li Lowalangi wedehe nifatenge Lowalangi, me no tenga nisu''a Geheha, nibe''e Lowalangi. [28]', '["Sin 45:8; Kol 1: 19"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 35, 'I''omasi''ö Nono Ama, ba no ahori ibe''e ba dangania fefu hadia ia. [29]', '["Faigi 5:22; 13:3; Mat 11:27"]', NULL),
  (3391601, 'NT', 'Yohane', 3, 36, 'Khö zamati khö Nono andrö so wa''auri si lö aetu; lö i''ila dania wa''auri si lö mamati khö Nono andrö, lö tebulö wönu Lowalangi khönia. [30]', '["YohI 5:12"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 1, 'Me no irongo Yesu, na larongo farizaio, ato nifahaö Yesu ba ato nibayagönia idanö, moroi khö Yohane[1] —', '["Faigi 3:22-26","Ayati 45"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 2, 'ba tenga sa Yesu zamayagö idanö, ha nifahaönia —', '["Faigi 3:22-26","Ayati 45"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 3, 'ba iröi Yudaia, ifuli isaŵa Galilaia. [2].', '["Faigi 3:22-26","Ayati 45"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 4, 'Ba ba Zamaria lalania.', '["MozI 33:19; 48:22"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 5, 'Ba irugi mbanua Zamaria andrö, sotöi Sikhara, ba zi tambai mbenua andrö, nibe''e Yakobo khö nononia Yosefo. [3]', '["MozI 33:19; 48:22"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 6, 'Ba so ba da''ö gumbu Yakobo. Ba me no erege dödö Yesu wekoli, ba mudadao ia ba zinga gumbu andrö Solaluo.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 7, 'So moroi sa ndra alawe Zamaria ba wana''u idanö. Imane khönia Yesu: Be''e ögu ubadu.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 8, 'Noa sa mofanö nifahaönia miyomo ba mbanua, ba wowöli gö.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 9, 'Imane khönia ira alawe Zamaria andrö; Hadia wa ö''andrö khögu nidanö? niha Yehuda sa ndra''ugö, ba ira alawe Zamaria ndra''odo. [4]', '["Luk 9:53; Eser 4:1 b.t."]', NULL),
  (3391602, 'NT', 'Yohane', 4, 10, 'Itema linia Yesu, imane khönia: Na ö''ila ena''ö mbuala Lowalangi andrö, ba na ö''ila, ha niha zanguma''ö khöu: Be''e ögu, ubadu; ba no mangandrö ndra''ugö khönia mena''ö, ba no ibe''e khöu nidanö gumbu. [5]', '["Sin 36:10; Fam 21:6"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 11, 'Imane khönia ira alawe andrö: Ba lö khöu fana''u Tua, ba no abakha mba''a, ba he moroi khöu nidanö gumbu andrö?', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 12, 'Hadia, ebua ndra''ugö moroi khö duada Yakobo, same''e ba''a andre khöda, samadu idanönia, awö nononia, awö gurifönia?', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 13, 'Itema linia Yesu, imane khönia: Ifuli awökhi dödö dozi samadu idanö andre,', '["Faigi 7:38-39; Yes 12"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 14, 'ba irugi zi lo aetu, ba lö''ö manö owökhi dödö zamadu idanö nibe''egu khönia, tobali umbu ba dödönia nidanö andrö, nibe''egu khönia, sangumbungumbu, sanaŵa fa''auri si lö aetu. [6]', '["Faigi 7:38-39; Yes 12"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 15, 'Imane khönia ira alawe andrö: He Tua! be''e ögu nidanö andrö, fa böi sa''ae owökhi dödögu, fa lö möido ba da''e, mana''u idanö. [7]', '["Yes 55:1"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 16, 'Imane khönia: Ae kaoni wo''omou, ba fuli''ö ba da''e.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 17, 'Itema linia ira alawe andrö, imane: Lö fo''omogu. Imane khönia Yesu: Si ndruhu niŵa''öu andrö: Lö fo''omogu.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 18, 'Dalima sa''ae zangai ya''ugö, ba tenga fo''omou zorudu khöu iada''e. Si ndruhu niŵa''öu andrö:', '["Faigi 1:49-50; 2:25"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 19, 'Imane: khönia ira alawe andrö: He Tua! oroma khögu, wa sama''ele''ö ndra''ugö. [8]', '["Faigi 1:49-50; 2:25"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 20, 'Ba hili andrö mangalulu ndra tuama föna, ba ya''ami miŵa''ö, ba Yeruzalema so naha wangalulu [9]', '["MozV 12:5 b.t."]', NULL),
  (3391602, 'NT', 'Yohane', 4, 21, 'Imane khönia Yesu: Fati ligu, alawe, irugi baŵa dania, ba tenga ba hili andrö, ba tenga göi ba Yeruzalema mangalulu ami khö Nama. [10]', '["Mal 1:11"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 22, 'Ba zi lö mi''ila mangalulu ami; ya''aga, ma''ila, ha ökhö mangalulu ndra''aga, me moroi ba niha Yehuda i''otarai fangorifi andrö. [11]', '["SalII 17:27 b.t.; Yes 2:3; Luk 1:69"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 23, 'Ba irugi baŵa dania ba no irugi iya''e, ba si ndruhu zangalulu, ba moroi ba Geheha ba moroi ba wa''aduhu mangalulu ira khö Nama. I''alui sa göi Ama zangalulu khönia si manö. [12]', '["Rom 12:1-2"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 24, 'Eheha Lowalangi, ba da''ö zi nangea fangalulu, ba zangalulu khönia, fangalulu moroi ba geheha ba fangalulu moroi ba wa''aduhu. [13]', '["KorII 3:17"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 25, 'Imane khönia ira alawe andrö! U''ila, so dania Mesia andrö, sotöi Keriso, na so da''ö, ba ya''ia zangombakha khöda fefu hadia ia.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 26, 'Imane khönia Yesu: Ya''odo da''ö, si fahuhuo khöu. [14]', '["Faigi 9:37"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 27, 'Ba ba da''ö so ndra nifahaönia, ba ahöli-höli dödöra, me fahuo-huo ia ba ndra alawe, ba lö''ö zui sanofu: Hadia ni''aluimö, ba ma: hadia huhuomö khönia?', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 28, 'Ba iröi sa''ae nasoa khönia ira alawe andrö, möi ia miyomo ba imane ba mbanuara:', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 29, 'Mi''ae mifaigi niha, si no mangombakha khögu fefu hadia ia nilaugu! Hadia, tenga Keriso andrö da''ö?', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 30, 'Ba möi ira moroi yomo, la''ondrasi.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 31, 'Ba barö ö muhede khönia nifahaönia, lamane: A göu, samahaö.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 32, 'Ba imane khöra: So gögu, ni''a, si lö mi''ila.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 33, 'Ba faoma lamane nifahaönia khö nawöra: Hadia, so zi no molohe gö khönia?', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 34, 'Imane khöra Yesu: Ogu da''ö, na u''o''ö zomasi zamatenge ya''o, ba na u''asiwai halöŵö andrö khönia. [15]', '["Faigi 6:38; Sin 40:9"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 35, 'Hadia, lö miŵa''ö: Hatö öfa waŵa, ba famasi sa''ae? Hiza, uŵa''ö khömi: Mifaöga hörömi, ba mifaigi nowi, noa sa''ae a''usö, tandra wa basitö. [16]', '["Mat 9:37"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 36, 'Itema sa''ae luo samasi, ba i''ozaragö mbua ba wa''auri si lö aetu, ena''ö faoma omuso dödöra, he sanaru, ba he samasi. [17]', '["KorI 3:6 b.t."]', NULL),
  (3391602, 'NT', 'Yohane', 4, 37, 'Ba da''ö sa duhu niŵa''ö andrö: Samösa zanaru ba samösa zamasi.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 38, 'No ufatenge ami ba wamasi, ba zi lö erege dödömi. No mohalöŵö niha bö''ö, ba ya''ami zanohugö holöŵöra andrö. [18]', '["HalZin 8:5 b.t."]', NULL),
  (3391602, 'NT', 'Yohane', 4, 39, 'Ba ato zamati khönia banua Zamaria, banua da''ö no mege, ba niŵa''ö ndr alawe andrö, samaduhu''ö: No i''ömbakha''ö khögu fefu hadia ia nilaugu.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 40, 'Ba me no la''ondrasi ia banua Zamaria andrö, ba la''andrö khönia, i''iagö khöra da''ö; ba dua wonginia ba da''ö.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 41, 'Ba ato zamati ba wangombakhania,', '["Faigi 17:8"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 42, 'ba lamane ba ndra alawe no mege: Tenga sa''ae ba ni''ombakha''ömö mamati ndra''aga, noa sa''ae marongo ba no ma''ila, wa si ndruhu sangorifi ösi guli danö da''ö. [19]', '["Faigi 17:8"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 43, 'Ba aefa zi dua wongi, ba iheta ia ba da''ö, isaŵa Galilaia.', '["Mat 13:57"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 44, 'Ifaduhu''ö sa Yesu, te''ositengagö zama''ele''ö ba mbanuara. [20].', '["Mat 13:57"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391602, 'NT', 'Yohane', 4, 45, 'Ba me no irugi Galilaia, ba latema ia banua Galilaia, me no la''ila nilaunia ba Yeruzalema, ba gowasa fefu. Noa sa möi ira göi ba gowasa. [21]', '["Faigi 2:23"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 46, 'Ba irugi zui Kana ba Galilaia ba nibali''önia agu idanö. Ba so genoni razo, sofökhö ono, ba Gafanauma. [22]', '["Faigi 2: 19"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 47, 'Me irongo da''ö, so Yesu, si otarai Yudaia, si möi ba Galilaia, ba möi ia khönia, ena''ö möi ia misi tou, ba wamadöhö fökhö nononia, si onali mate.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 48, 'Ba imane khönia Yesu: Na lö ni''ilami tandra ba ila-ila, ba lö mamati ami. [23]', '["Faigi 2:18; 20:29"]', NULL),
  (3391602, 'NT', 'Yohane', 4, 49, 'Imane khönia enoni razo andrö: He Tua! ae mitou, fatua lö mate nonogu andrö.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 50, 'Imane khönia Yesu: Ae''e, auri nonou. Faduhu dödö niha andrö ba li andrö, niŵa''ö Yesu khönia, ba möi.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 51, 'Ba me no irugi si tou, ba falukha ia zawuyunia ba la''ombakha''ö khönia: Auri nonou.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 52, 'Ba isofu khöra, ha wa''alaŵa luo, me abe''e ia. Ba lamane khönia: Menewi, manaere wa''alaŵa luo, ba tebato wa''aukhu.', '[]', NULL),
  (3391602, 'NT', 'Yohane', 4, 53, 'Ba aboto sa''ae ba dödö nama nono andrö, da''ö wa''alaŵa luo, me iŵa''ö khönia Yesu: Auri nonou. Ba mamati ia, awö zoroiyomonia fefu. [24]', '["HalZin 16:15-31 b.t."]', NULL),
  (3391602, 'NT', 'Yohane', 4, 54, 'Me i''otarai Yudaia, me numalö ia ba Galilaia, ilau da''ö Yesu, dombua sa''ae ba da''ö dandra andrö. [25]', '["Faigi 2:11"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 1, 'Aefa da''ö, ba so gowasa niha Yehuda, ba möi misi yaŵa ba Yeruzalema Yesu.', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 2, 'Ba so ba Yeruzalema mbaŵa, ba zinga mbawa göli mbiri-biri, Betesa döinia ba li Heberaio, ba lima nose.[1]', '["Neh 3:1"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 3, 'Ba ato niha sofökhö ba nose andrö, awö zau''a, awö zombuyu-mbuyu, awö zofökhö baösi, (labalo-baloi wa''atekiba nidanö.[2]', '["Fam 16:5"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 4, 'Itaria möi tou mala''ika, ba mbaŵa andrö, ba ifakiba nidanö, ba döhö wökhö zi föföna möi si tou ba mbaŵa, na aefa tekiba nidanö, gofu hadia göi wökhönia).', '["Fam 16:5"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 5, 'Ba so ba da''ö niha, si no tölu ngafulu a ŵalu fakhe wa''ara fökhö.', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 6, 'Me i''ila da''ö Yesu, ba me oroma khönia, no ara sibai ia, ba imane khönia: Omasi''ö na döhö wökhöu?', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 7, 'Itema linia sofökhö andrö, imane: Lö khögu niha, Tua, solohe ya''o si tou ba mbaŵa na tekiba nidanö, ba na so ndra''o, ba no möi si tou danö bö''ö, fönagu.', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 8, 'Imane khönia Yesu: Faoso, fazaŵa gasomö ba owaö-waö![3]', '["Mat 9:6; HalZin 9:34"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 9, 'Ba döhö wökhö niha andrö ifazaŵa gasonia ba mowaö-waö.', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 10, 'Ba lamane niha Yehuda khö nifadöhö fökhö andrö: Luo sabato, ba lö tola ö''ohe gaso.', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 11, 'Itema lira, imane: Samadöhö fökhögu andrö zanguma''ö khögu: Fazaŵa gasomö ba owaö-waö.', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 12, 'Ba lasofu khönia: Ha niha da''ö, zanguma''ö khöu: Fazaŵa ba owaö-waö?', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 13, 'Ba lö i''ila sofökhö andrö ha niha, noa sa iheta ia Yesu, me no ato niha ba da''ö.', '[]', NULL),
  (3391603, 'NT', 'Yohane', 5, 14, 'Aefa da''ö, ba falukha khönia Yesu, ba gosali, ba imane khönia: Faigi, no döhö wökhöu, böi sa''ae fazökhi horö, fa lö göna ndra''ugö sabölö-bölö moroi andrö.[4]', '["Faigi 8:11; Mat 12:45"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 15, 'Möi niha andrö, iŵa''ö ba niha Yehuda, Yesu zamadöhö fökhönia.[5]', '["Ayati 10"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 16, 'Ba andrö lagohi Yesu niha Yehuda, me no ilau da''ö ba luo sabato.[6]', '["Faigi 7:22 b.t.; 9:16"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 17, 'Ba humede ia khöra, imane: Mohalö-halöŵö Namagu, irugi da''e, ba ya''o göi, mohalöŵö.[7]', '["Faigi 9:4"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 18, 'Andrö mendrua manö la''alui wamunu ya''ia niha Yehuda, me tenga ha fanaŵönia oroisa sabato, me iŵa''ö göi, Lowalangi Namania, ba me ifaomagö ia khö Lowalangi.[8]', '["Faigi 10:30–33"]', NULL),
  (3391603, 'NT', 'Yohane', 5, 19, 'Ba humede khöra Yesu, imane khöra: Si ndruhu-ndruhu niŵa''ögu khömi, lö i''ila ilau hadia ia Ono, na moroi khönia, na lö ni''ilania, ilau Ama; nilau da''ö sa ilau göi Ono, si manö göi.[9]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 20, 'Noa sa i''omasi''ö Nono Ama, ba fefu nilaunia, ba i''oroma''ö khönia, ba i''oroma''ö khönia dania halöŵö, sebua moroi andrö, ena''ö ahöli-höli dödömi.[10]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 21, 'Hulö si mane fanusugi Nama si mate, si mane fangorifinia ya''ira, si manö göi Nono, i''orifi zomasi ia.', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 22, 'Lö''ö sa göi ihuku niha Ama, noa sa ibe''e khö Nono wanguhuku andrö fefu,[11]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 23, 'fa dozi lafosumange Nono, si mane famosumangera Ama. Si lö mamosumange Ono, ba lö''ö göi ifosumange Nama, samatenge Ono.[12]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 24, 'Si ndruhu-ndruhu niŵa''ögu khömi, so wa''auri si lö aetu khö zamondrongo ligu, na mamati ia khö zamatenge ya''o, ba lö lahuku ia; noa sa isaŵa wa''auri, i''otarai wa''amate.[13]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 25, 'Si ndruhu-ndruhu niŵa''ögu khömi, irugi baŵa dania, ba no irugi iya''e, ba larongo li Nono Lowalangi si mate, ba sauri zamondrongo andrö.[14]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 26, 'Hulö si mane khö Nama sa, si so fa''auri ba dödönia si manö göi mbe''enia khö Nono, ena''ö so wa''auri ba dödönia.[15]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 27, 'Ba no itehe khönia wanguhuku, börö me no Ono Niha ia.[16]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 28, 'Böi ahöli-höli dödömi ba da''ö! Irugi baŵa dania, ba larongo linia dozi si so ba lewatö,[17]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 29, 'ba möi ira yaŵa: samazökhi si sökhi, ba ba wemaoso ba wa''auri, ba solo''ö si lö sökhi, ba ba wemaoso ba huku.[18]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 30, 'Lö u''ila ulau hadia ia, na moroi khögu, u''o''ö nirongogu, wanguhuku, ba no atulö wanguhuku andrö khögu. Lö u''alui zomasi ndra''o, somasi zamatenge ya''o u''alui.[19]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 31, 'Na ya''o zamaduhu''ö ya''o, ba tenga si duhu wamaduhu''ögu.[20]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 32, 'Tanö bö''ö zamaduhu''ö ya''o, ba mi''ila, wa no si duhu wamaduhu''önia, famaduhu''önia ya''o.[21]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 33, 'No mifatenge khö Yohane, ba no ifaduhu''ö zi duhu.[22]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 34, 'Ba ya''o, ba tenga ba niha utema wamaduhu''ö andrö, ba andrö uŵa''ö da''ö, ena''ö te''orifi ami.', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 35, 'Fandru sihola-hola da''ö no mege, sihaga, ba no omasi ami, mi''omusoi''ö, dödömi, si lö arara, ba haga andrö khönia.', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 36, 'Ba no so khögu wamaduhu''ö ba da''ö, sebua moroi khö Yohane. Halöŵö andrö sa, nibe''e Nama khögu, ba wangasiwai ya''ia, halöŵö andrö, nihalögu, da''ö zamaduhu''ö ya''o, wa no Ama zamatenge ya''o.[23]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 37, 'Ba samatenge ya''o andrö, Ama da''ö zamaduhu''ö ya''o. Ba lö mirai mirongo linia, ba nga''eunia, ba lö ni''ilami.[24]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 38, 'Ba lö ahono ba dödömi daroma linia, me lö mamati ami khö nifatengenia andrö.[25]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 39, 'Mi''alu-alui ba zura, me miŵa''ö so khömi ba da''ö wa''auri si lö aetu; ba ya''ia zamaduhu''ö ya''o;[26]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 40, 'ba lö edöna möi ami khögu, ena''ö so khömi wa''auri.', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 41, 'Lö utema zumange nibe''e niha.', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 42, 'Ba no u''ila ami, wa lö khömi fa''omasi Lowalangi ba dödömi.', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 43, 'Ba döi Namagu so ndra''o, ba lö mifonaha ndra''o. Na so dania danö bö''ö, ba döina manö, ba mifonaha.[27]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 44, 'He miwisa mamati, me faoma mitema zumange khö nawömi, ba sumange andrö khö Lowalangi, si ha sambua, ba lö mi''alui?[28]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 45, 'Böi miŵa''ö tödömi, ya''o zangadugö ya''ami khö Nama; so zangadugö ya''ami, Moze, ba zanötöna ami.[29]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 46, 'Na mamati ami khö Moze, ba mamati ami khögu göi ena''ö, noa sa ibe''e ba zura da''ö hadia ia khögu.[30]', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391603, 'NT', 'Yohane', 5, 47, 'Ba na lö mamati ami ba zura da''ö, ba he miwisa mamati ba niŵa''ögu?', '["Faigi 5:30","Faigi 1:51","Faigi 3:35; Sin 72:1; HalZin 17:31; Mat 25:32","Faigi 14:13; Fil 2:10,11; YohI 2:23","Faigi 3:18,37; 8:51","Faigi 11:43; Mat 11:5; Efes 5:14","Faigi 1:4; 11:25; YohI 5:20","Dan 7:13.14; Mat 25:31","TesI 4:16","Faigi 9:40; Dan 12:2","Faigi 5:19; 6:38","Faigi 8:13; 14:54","Mat 3:17","Faigi 1:19 b.t.","Faigi 10:25; 14:10,11","Faigi 8:18; 1:18","Faigi 10:26; KorII 3:15","Yes 34:16; Sin 40:8; Luk 24:27","Faigi 7:28","Faigi 12:42,43","MozV 31:26 b.t.","MozI 3:15, 49:10; MozV 31:15 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 1, 'Aefa da''ö, ba mofanö Yesu, i''ötö mbaŵa Galilaia andrö, baŵa Diberia.', '["MozIII 23:5 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 2, 'Ba ato zolo''ö ya''ia niha, me no la''ila dandra andrö, nifazökhinia ba zofökhö.', '["MozIII 23:5 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 3, 'Ba möi ba hili Yesu, mudadao ia ba da''ö, awö ndra nifahaönia.', '["MozIII 23:5 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 4, 'Ba no ahatö wasa, owasa niha Yehuda andrö.[1]', '["MozIII 23:5 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 5, 'Ba ifaöga hörönia Yesu, ba i''ila, ato zi möi khönia niha, ba imane khö Wilifo: Heza ta''öli gö, ena''ö manga da''ö?[2]', '["Faigi 1:44"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 6, 'Ba wanandraigö ya''ia iŵa''ö da''ö, noa sa i''ila, he iwisa dania.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 7, 'Itema linia Filifo, imane: Lö irugi öra si otu rufia fowöli roti, he ha ma''ifu zamösa tebe''e.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 8, 'Imane khönia nifahaönia samösa, Andrea, talifusö Zimoni Fetero andrö:', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 9, 'So ba da''e ndraono, si so roti gandru, lima, ba dua rozi gi''a. Ba ha wa''aröu da''ö ba zi manö fa ato?', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 10, 'Imane Yesu: Mifedadao niha.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 11, 'Ba ihalö roti no mege Yesu, i''aohasi gölö Lowalangi, ba ibe''e ba zidadao andrö, si manö göi ba gi''a andrö, ha wa''oya zomasi ira.[3]', '["Sin 145:16"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 12, 'Ba me no abuso ira, ba imane ba nifahaönia; Mi''ozaragö gakhökhöla, si tosai, fa böi tefara''u hadia ia.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 13, 'Ba la''ozaragö ba felendrua lafo''ösi kude, akhökhöla roti gandru andrö, si lima, si tosai ba zi no manga andrö.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 14, 'Ba me la''ila niha dandra andrö, nifazökhinia, ba lamane: Si ndruhu, da''ö zama''ele''ö andrö, si möi ba guli danö.[4]', '["Faigi 7:40; MozV 18:15 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 15, 'Ba me i''ila Yesu,[5] möi ira dania, lara''u ia, ba wamali''ö razo ya''ia ba ifuli iheta ia, isaŵa hili, ha ya''ia.[6]', '["Ayati 15-21: Mat 14:22-36; Mar 6:45-56","Faigi 18:36"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 16, 'Ba me tanö owi, ba möi mitou ndra nifahaönia ba mbaŵa möi ira baowo,', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 17, 'la''ötö mbaŵa, lasaŵa Gafanauma; ba ikhamö ira fa''abongi, ba lö''ö na si möi khöra Yesu.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 18, 'Modulu sibai mbaŵa, me angi sabe''e.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 19, 'Ba me no töra saza woloyora, ba la''ila Yesu, sowaö-waö ba dete nidanö, no ahatö ia ba nowo, ba ata''u ira.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 20, 'Ba imane khöra: Ya''odo, böi mi''ata''ufi!', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 21, 'Ba lafa''amöi ia baowo mena''ö, ba irugi si''aikö owo danö si möi ira.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 22, 'Ba mahemolu ö, ba la''ila niha si so yefo mbaŵa lö owo bö''ö ba da''ö, baero zi sambua andrö, ba no la''ila, lö fao Yesu khö ndra nifahaönia, we''amöi baowo, ha nifahaönia zoloyo.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 23, '— So sa nowo bö''ö, si otarai Diberia, si möi ba zahatö ba naha andrö, ba ni''ara roti andrö me no mangandrö saoha gölö Zo''aya. —', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 24, 'Ba me la''ila niha, lö Yesu ba da''ö ba lö''ö göi ira nifahaönia, ba möi ira göi ba nowo andrö, lasaŵa Gafanauma, mangalui Yesu.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 25, 'Ba me lasöndra ia, yefo mbaŵa, ba lamane khönia: He samahaö, ha mega örugi da''e?', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 26, 'Itema lira Yesu, imane: Si ndruhu-ndruhu niŵa''ögu khömi, tenga ba da''ö mi''alui ndra''o, me no mi''ila dandra; me no mi''a roti andrö, me no abuso ami, andrö mi''alui ndra''o.', '["Faigi 4:14; 10:36"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 27, 'Böi mi''a''asogö gö andrö sobou dania, ö si lö tebulö-bulö andrö, ba wa''auri si lö aetu, mi''asogö, nibe''e Nono Niha khömi; da''ö sa nifaduhu''ö Nama, Lowalangi.[7]', '["Faigi 4:14; 10:36"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 28, 'Ba lamane khönia: He mawisa ena''ö, ba wangai halöŵö andrö khö Lowalangi?', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 29, 'Itema lira Yesu, imane khöra: Da''ö halöŵö khö Lowalangi, na mamati ami khö nifatengenia andrö.[8]', '["YohI 3:23"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 30, 'Ba lamane khönia: Ba hadia dandra, nifazökhiu, ena''ö ma''ila, ba ena''ö mamati ndra''aga khöu? Hadia ni''asogömö?[9]', '["Faigi 4:18; Mat 12:38","MozII 16:4,15; Sin 78:24"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 31, 'No la''a "mana" ira tuada, ba danö si mate; si mane ba zura: "No ibe''e öra roti moroi ba mbanua si yaŵa".[10]', '["Faigi 4:18; Mat 12:38","MozII 16:4,15; Sin 78:24"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 32, 'Ba imane khöra Yesu: Si ndruhu-ndruhu niŵa''ögu khömi, tenga Moze zame''e khömi gö andrö, moroi ba mbanua si yaŵa, Amagu zame''e khömi gö si ndruhu andrö, moroi ba mbanua si yaŵa.[11]', '["Faigi 6:49 b.t.; MozV 8:3"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 33, 'Da''ö sa gö andrö, nibe''e Lowalangi, si möi mitou moroi ba mbanua si yaŵa, fangorifi nösi guli danö.', '["Faigi 6:49 b.t.; MozV 8:3"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 34, 'Ba lamane khönia: He Tua, böi bulö''ö wame''e khöma gö andrö.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 35, 'Ba imane khöra Yesu: Ya''odo gö fangorifi, lö''ö sa''ae olofo zi möi khögu, ba lö''ö manö sa''ae owökhi dödö zamati khögu.', '["Faigi 17:6,9,11","Faigi 4:34; Luk 22:42","Faigi 10:28,29","Faigi 3:14 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 36, 'Ba uŵa''ö khömi, noa göi mi''ila ndra''odo, ba lö mamati ami.', '["Faigi 17:6,9,11","Faigi 4:34; Luk 22:42","Faigi 10:28,29","Faigi 3:14 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 37, 'Si möi khögu fefu nibe''e Namagu khögu, ba lö''ö manö utibo''ö zi möi khögu.[12]', '["Faigi 17:6,9,11","Faigi 4:34; Luk 22:42","Faigi 10:28,29","Faigi 3:14 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 38, 'Tenga ba wolau somasi ndra''o möido tou moroi ba zorugo, ba wolau somasi samatenge ya''o möido tou.[13]', '["Faigi 17:6,9,11","Faigi 4:34; Luk 22:42","Faigi 10:28,29","Faigi 3:14 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 39, 'Da''ö zomasi zamatenge ya''o, ena''ö lö si taya khögu ba nibe''enia khögu fefu, ena''ö na ususugi ia, na luo safuria andrö.[14]', '["Faigi 17:6,9,11","Faigi 4:34; Luk 22:42","Faigi 10:28,29","Faigi 3:14 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 40, 'Da''ö sa zomasi Namagu, ena''ö so wa''auri si lö aetu khö zangila Ono fefu, samati khönia, ba ya''o zanusugi ya''ira, na luo safuria andrö.[15]', '["Faigi 17:6,9,11","Faigi 4:34; Luk 22:42","Faigi 10:28,29","Faigi 3:14 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 41, 'Ba kumökö-kökö niha Yehuda khönia, me no iŵa''ö: ya''odo gö andrö, si no möi mitou moroi ba mbanua si yaŵa, ba lamane:', '["Mat 13:55 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 42, 'Tenga Yesu da''ö, ono Yosefo, ni''ilada ama ba ina? Ba hana wa iŵa''ö da''ö: Moroi ba mbanua si yaŵa u''otarai?[16]', '["Mat 13:55 b.t."]', NULL),
  (3391604, 'NT', 'Yohane', 6, 43, 'Itema lira Yesu, imane khöra: Böi mikökö-kökö khö nawömi.', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391604, 'NT', 'Yohane', 6, 44, 'Lö sangila möi khögu, na tenga Amagu, samatenge ya''o, zondrönisi ya''ia; ba ya''o zanusugi ya''ia na luo safuria andrö.[17]', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 45, 'No so ba zura zama''ele''ö: "Nifahaö Lowalangi ira dania, fefu". Dozi möi khögu samondrongo khö Nama, sanöngöni.[18]', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 46, 'Tenga fa no i''ila Nama niha, baero zi otarai Lowalangi andrö, da''ö zi no mangila Lowalangi.[19]', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 47, 'Si ndruhu-ndruhu niŵa''ögu khömi, khö zamati so wa''auri si lö aetu.[20]', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 48, 'Ya''o roti fangorifi andrö.', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 49, 'No la''a "mana" ira tuami, ba danö si mate, ba no mate ira.[21]', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 50, 'Da''ö roti fangorifi, si otarai mbanua si yaŵa, ena''ö na i''a ia niha, ba lö mate ia.', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 51, 'Ya''o roti andrö, sauri, si otarai mbanua si yaŵa, na so zi manga roti andrö, ba auri ia, irugi zi lö aetu; ba roti andrö göi, nibe''egu dania, ösigu andre, ba no fangorifi nösi guli danö.[22]', '["Faigi 6:37,39,65; Mat 16:17","Yes 54:13; Yer 31:33-34","Faigi 1:18; TimI 6:16","Faigi 3:36","KorI 10:3,5","Luk 22:19"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 52, 'Ba mowasoso niha Yehuda, lamane: He iwisa da''ö fa tola ibe''e ni''ada nösinia?', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 53, 'Ba imane khöra Yesu: Si ndruhu-ndruhu niŵa''ögu khömi, na lö mi''a nösi Nono Niha, na lö mibadu ndronia, ba lö fa''auri khömi, ba dödömi.[23]', '["Mat 26:26 b.t.; KorI 11:27","Faigi 15:5","Faigi 5:26"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 54, 'Si manga nösigu, samadu dogu, da''ö zi so fa''auri si lö aetu, ba ya''o zanusugi ya''ia, na luo safuria andrö.', '["Mat 26:26 b.t.; KorI 11:27","Faigi 15:5","Faigi 5:26"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 55, 'Ösigu sa zi ndruhu gö ba dogu zi ndruhu nibadu.', '["Mat 26:26 b.t.; KorI 11:27","Faigi 15:5","Faigi 5:26"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 56, 'Lö aheta khögu zi manga nösigu, samadu dogu, ba lö aheta ndra''o khönia.[24]', '["Mat 26:26 b.t.; KorI 11:27","Faigi 15:5","Faigi 5:26"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 57, 'Si mane famatenge Nama sauri andrö ya''o, awö wa no börö Nama, wa no sauri ndra''o, si manö göi zi manga ya''o, börö ndra''o, wa sauri ia.[25]', '["Mat 26:26 b.t.; KorI 11:27","Faigi 15:5","Faigi 5:26"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 58, 'Da''ö roti andrö, si otarai mbanua si yaŵa; tenga si mane ira tuami, si manga ba mate: Si manga roti andrö, ba auri, irugi zi lö aetu.', '["Mat 26:26 b.t.; KorI 11:27","Faigi 15:5","Faigi 5:26"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 59, 'Ba zekola iŵa''ö da''ö, me mamahaö ia, ba Gafanauma.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 60, 'Ba ato nifahaönia, ba lamane, me larongo da''ö; Huhuo sabe''e da''ö, ha niha zanaha mamondrongo da''ö?', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 61, 'Ba me i''ila tödönia Yesu, kumökö-kökö nifahaönia ba da''ö, ba imane khöra: Hadia, fatuwu khömi da''ö?', '["Yoh 3:13; 20:17; Mar 16:19","KorII 3:6"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 62, 'Ba he wisa, na mi''ila dania, möi yaŵa Nono Niha, ba zi so ia föna?[26]', '["Yoh 3:13; 20:17; Mar 16:19","KorII 3:6"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 63, 'Eheha zangorifi, lö''ö manö guna nösi niha. Eheha ba fa''auri daroma ligu andrö, niŵa''ögu khömi.[27]', '["Yoh 3:13; 20:17; Mar 16:19","KorII 3:6"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 64, 'Ba so ösa ba khömi, zi lö mamati.', '["Yoh 3:13; 20:17; Mar 16:19","KorII 3:6"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 65, 'Ba imane: Andrö uŵa''ö khömi: Lö sangila möi khögu, na tenga nibe''e Nama khönia.[29]', '["Faigi 6:44"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 66, 'I''otarai da''ö, ba ato zamuli ya''ira, nifahaönia, ba lö''ö sa''ae fao-fao ira khönia.', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 67, 'Ba imane Yesu ba zi felendrua: Hadia, sofanö göi ami?', '[]', NULL),
  (3391604, 'NT', 'Yohane', 6, 68, 'Itema linia Simoni Fetero, imane: He Tua, ba ökhö möiga? So khöu daroma li fangorifi, ba wa''auri si lö aetu.', '["Faigi 1:50; 11:27"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 69, 'Ba no mamati ndra''aga ba no aboto ba dödöma, ya''ugö ni''amoni''ö andrö khö Lowalangi.[30]', '["Faigi 1:50; 11:27"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 70, 'Itema lira Yesu: Tenga felendrua ami, nitutuyugu? Ba afökha zi samösa.[31]', '["Luk 6:13"]', NULL),
  (3391604, 'NT', 'Yohane', 6, 71, 'Yuda andrö, ono Zimoni, banua Kariota, niŵa''önia; da''ö sa zi manga mbölinia dania; samösa ia ba zi felendrua.[32]', '["Faigi 12:4; 18:3"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 1, 'Aefa da''ö, ba itöröi Galilaia Yesu, lö''ö sa edöna ia itöröi Yudaia, me la''alui wamunu ya''ia niha Yehuda.[1]', '["Faigi 5:16,18","MozIII 23:34 b.t."]', NULL),
  (3391605, 'NT', 'Yohane', 7, 2, 'Ba no ahatö gowasa niha Yehuda, owasa nose daha geu.[2]', '["Faigi 5:16,18","MozIII 23:34 b.t."]', NULL),
  (3391605, 'NT', 'Yohane', 7, 3, 'Ba lamane khönia ira talifusönia: Heta''ö ba da''e, ae misi yaŵa ba Yudaia, ena''ö la''ila göi ira nifahaömö halöŵöu andrö, nihalöu.[3]', '["Mat 12:46"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 4, 'Lö solau hadia ia ba zi tobini, si lö edöna aiwö göi. Na ölau zi manö, ba oroma''ö ndra''ugö ba niha.', '["Mat 12:46"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 5, 'Talifusönia andrö göi, ba si lö mamati khönia.[4]', '["Sin 69:9; Mat 3:21"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 6, 'Imane khöra Yesu: Tenga na inötö khögu, ba inötö khömi andrö, ba gofu ha wa''ara.[5]', '["Faigi 2:4"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 7, 'Khömi, ba tebai fatiu dödö niha guli danö, ba khögu, ba fatiu dödöra, me ufaduhu''ö khöra, wa lö sökhi mbua-buara.', '["Faigi 2:4"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 8, 'Mi''ae misi yaŵa ba gowasa, ya''odo, lö möi misi yaŵa ba gowasa, me lö irugi na inötö andrö khögu.', '["Faigi 2:4"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 9, 'Aefa iŵa''ö da''ö, ba i''iagö Galilaia.', '[]', NULL),
  (3391605, 'NT', 'Yohane', 7, 10, 'Ba me no möi misi yaŵa ba gowasa ndra talifusönia, ba awena möi ia göi misi yaŵa; lö i''oroma''ö, ibini''ö.', '[]', NULL),
  (3391605, 'NT', 'Yohane', 7, 11, 'Ba la''alui ia niha Yehuda, ba gowasa, lamane: Heza so ia?', '["Faigi 9:16","Faigi 9:22"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 12, 'Ba tobali fasosota sabölö-bölö, ba khönia andrö, ba niha sato. So zanguma''ö: Si sökhi ia. Ba so zanguma''ö: Lö''ö ifaelungu niha.[6]', '["Faigi 9:16","Faigi 9:22"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 13, 'Ba lö''ö zui si lö aiwö manguma''ö hadia ia ba khönia, ba wa''ata''ura niha Yehuda.[7]', '["Faigi 9:16","Faigi 9:22"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 14, 'Ba me no talu gowasa, ba möi miyaŵa Yesu ba gosali ba mamahaö.', '[]', NULL),
  (3391605, 'NT', 'Yohane', 7, 15, 'Ba ahöli-höli dödö niha Yehuda, lamane: He moroi i''ila zura da''ö, me lö mufahaö?[8]', '["Mar 6:2"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 16, 'Ba itema lira Yesu, imane: Tenga khögu wamahaögu andrö, khö zamatenge ya''o.[9]', '["Faigi 8:26,28; 14:24","Faigi 3:33","Faigi 5:41,44","HalZin 7:52,53; Mat 12:14"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 17, 'Na so zedöna molo''ö somasi ia, ba dödönia aboto hadia ia ba wamahaö andrö, na moroi ba Lowalangi ia, ba na moroi ba khögu muhede ndra''o.[10]', '["Faigi 8:26,28; 14:24","Faigi 3:33","Faigi 5:41,44","HalZin 7:52,53; Mat 12:14"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 18, 'Sihede moroi ba khönia, ba mangalui lakhömi khönia. Ba sangalui lakhömi zamatenge ya''ia, da''ö zi ndruhu, ba lö si lö atulö ba dödönia.[11]', '["Faigi 8:26,28; 14:24","Faigi 3:33","Faigi 5:41,44","HalZin 7:52,53; Mat 12:14"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 19, 'Tenga Moze zame''e oroisa khömi? Ba samösa lö''ö ba khömi solo''ö oroisa andrö. Hana wa mi''alui wamunu ya''o?[12]', '["Faigi 8:26,28; 14:24","Faigi 3:33","Faigi 5:41,44","HalZin 7:52,53; Mat 12:14"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 20, 'Latema linia niha sato, lamane! Sobekhu ndra''ugö! Ha niha zangalui famunu ya''ugö?[13]', '["Faigi 8:48; 10:20"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 21, 'Itema lira Yesu, imane khöra: Ha sambalö halöŵö nihalögu, ba oi sahöli-höli tödö ami.[14]', '["Faigi 5:16","MozIII 12:3; MozI 17:10,12","Faigi 5:9","MozV 1:16-17; 16:19"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 22, 'No ibe''e khömi wamoto andrö Moze, tenga me moroi khö Moze ia, me moroi khö ndra tua, ba ba luo sabato miboto niha.[15]', '["Faigi 5:16","MozIII 12:3; MozI 17:10,12","Faigi 5:9","MozV 1:16-17; 16:19"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 23, 'Na laboto niha ba luo sabato, fa lö tesawö goroisa Moze andrö, ba hadia, mofönu ami khögu, me no abe''e niha, ma''asambua, ube''e ba luo sabato?[16]', '["Faigi 5:16","MozIII 12:3; MozI 17:10,12","Faigi 5:9","MozV 1:16-17; 16:19"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 24, 'Böi mibe''e balazi ni''ila hörö, ba wanguhuku hadia ia, mi''atulö''ö wanguhuku[17]', '["Faigi 5:16","MozIII 12:3; MozI 17:10,12","Faigi 5:9","MozV 1:16-17; 16:19"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 25, 'Ba laŵa''ö banua Yeruzalema ösa: Hadia, tenga da''ö ni''aluira famunu?', '["Faigi 6:42"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 26, 'Ba hiza, lö ata''u ia muhede, ba lö hede-hedera khönia. Ma duhu no aboto ba dödö zalaŵa, wa Keriso da''ö?', '["Faigi 6:42"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 27, 'Ba no ta''ila, he moroi da''ö, ba na so Keriso andrö, ba lö sangila he moroi ia.[18]', '["Faigi 6:42"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 28, 'Ba mu''ao Yesu, me mamahaö ia ba gosali, imane: Mi''ila sa ndra''o, ba mi''ila, he moroi ndra''o. Ba tenga moroi khögu möi ndra''o, so sa zi duhu, samatenge ya''o, si lö mi''ila.[19]', '["Faigi 5:43; 8:19,42 b.t.","Mat 11:27"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 29, 'Ya''o zangila ya''ia, me moroi khönia ndra''o, ba me no ya''ia zamatenge ya''o.[20]', '["Faigi 5:43; 8:19,42 b.t.","Mat 11:27"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 30, 'Ba la''alui wondra''u ya''ia, ba lö''ö sa sombambaya ya''ia, me lö''ö na irugi inötö andrö khönia.[21]', '["Faigi 8:20; 13:1"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 31, 'Ba ato zamati khönia ba niha sato, ba lamane: Na so Keriso andrö, ba hadia, oya ifazökhi dandra, moroi ba nifazökhi da''ö?[22]', '["Faigi 8:30"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 32, 'Larongo farizaio, wa si manö wangöngö-ngöngösa niha sato ba khönia; ba lafatenge genonira ere sebua ba farizaio, ena''ö lara''u ia.', '[]', NULL),
  (3391605, 'NT', 'Yohane', 7, 33, 'Ba imane Yesu: Lö ara tö ndra''o khömi, ba mofanödo khö zamatenge ya''o andrö.[23]', '["Faigi 12:25; 13:33; 14:12; 16:28","Faigi 8:21; 12:26; Amos 8:12"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 34, 'Mi''alui ndra''o dania, ba lö misöndra ndra''o, ba tebai möi ami ba zi so ya''o.[24]', '["Faigi 12:25; 13:33; 14:12; 16:28","Faigi 8:21; 12:26; Amos 8:12"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 35, 'Ba faoma lamane khö nawöra niha Yehuda: Heza möi ia dania, wa lö tasöndra ia? Ma möi ia ba zizaewe andrö, ba Ndrawa Heleni, mamahaö Dawa Heleni?[25]', '["FetI 1:1"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 36, 'Hadia wehede andrö, niŵa''önia: Mi''alui ndra''o dania, ba lö misöndra ndra''o; ba tebai möi ami ba zi so ya''o?', '["FetI 1:1"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 37, 'Ba me luo gowasa safuria, sebua, ba so Yesu, mu''ao ia, imane: Na so zowökhi tödö, ba yamöi khögu, mamadu?[26]', '["MozIII 23:36; Faigi 4:10,14; Fam 22:17","Hes 47:1; Yes 44:3"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 38, 'Moroi ba nösi zamati khögu mangele dania hohou nidanö gumbu, si mane niŵa''ö ba zura.[27]', '["MozIII 23:36; Faigi 4:10,14; Fam 22:17","Hes 47:1; Yes 44:3"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 39, 'Ba Geheha sa iŵa''ö da''ö, nitema zamati khönia dania; lö si so Geheha na, me lö mufolakhömi Yesu na.[28]', '["Faigi 16:7; 20:22"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 40, 'Ba so ba niha sato ösa, lamane me no larongo wehede andrö: Si ndruhu zama''ele''ö andrö ia.[29]', '["Faigi 6:14","Faigi 1:47","Sin 132:11; Mikh 5:2; Mat 2:5,6"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 41, 'Ba so danö bö''ö ba lamane: Keriso ba tanö bö''ö, ba lamane: Hadia sa, ba Galilaia i''otarai Keriso?[30]', '["Faigi 6:14","Faigi 1:47","Sin 132:11; Mikh 5:2; Mat 2:5,6"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 42, 'Tenga no muŵa''ö ba zura, moroi ba ma''uwu Dawido, moroi ba mbanua side-ide andrö, Betilekhema, ba zi so Dawido föna, i''otarai Keriso?[31]', '["Faigi 6:14","Faigi 1:47","Sin 132:11; Mikh 5:2; Mat 2:5,6"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 43, 'Ba tobali lö fagölö-gölö dödö niha sato ba khönia andrö.[32]', '["Faigi 10:19"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 44, 'So ba khöra zondra''u ya''ia ena''ö, ba lö''ö zui sombambaya ya''ia.', '["Faigi 10:19"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 45, 'Ba lafuli ira ba gere sebua ba ba warizaio enoni no mege, ba lamane khöra da''ö: Hana wa lö mi''ohe ia?', '[]', NULL),
  (3391605, 'NT', 'Yohane', 7, 46, 'Latema lira enoni andrö, lamane: Lö irai si manö niha wehede, si mane fehede niha da''ö.[33]', '["Mat 7:28-29"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 47, 'Latema lira farizaio, lamane: Hadia, no tefaelungu ami göi?', '["Faigi 12:42; KorI 1:26-27"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 48, 'Hadia, so zamösa salaŵa, ba ma farizaio, si no mamati khönia?[34]', '["Faigi 12:42; KorI 1:26-27"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 49, 'Ha sa niha sato andrö, si lö aboto ba dödö oroisa, ba ni''elifi da''ö.', '["Faigi 12:42; KorI 1:26-27"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 50, 'Imane khöra Nikodemo, awöra:[35]', '["Faigi 3:1-2","MozII 23:1; HalZin 25:16"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 51, 'Hadia, ihuku göi niha oroisa khöda, na lö murongo ua hadia ia, khönia, na lö aboto ba dödö nilaunia?[36]', '["Faigi 3:1-2","MozII 23:1; HalZin 25:16"]', NULL),
  (3391605, 'NT', 'Yohane', 7, 52, 'Latema linia, lamane khönia: Hadia, moroi ba Galilaia göi ndra''ugö? Alui ba faigi, lö sama''ele''ö, si otarai Galilaia.[37]', '["Mar 14:70; Yes 9:1-2"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 1, 'Ba möi ba gahe hili wanikha Yesu. [1]', '["Luk 21:37-38"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 2, 'Ba me no moluo, ba ifuli ia ba gosali, ba oi la''ondrasi ia niha, ba mudadao ia mamahaö ya''ira.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 3, 'Ba la''ohe khönia sangila amakhoita ba farizaio ndra alawe, nira''u baewawö, lafa''aso ba gotaluara, lamane khönia:', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 4, 'He samahaö, nira''u baewawö ndra alawe andre.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 5, 'Ba ba goroisa iŵa''ö khöda Moze, nibunu zi manö, nitebu kara, ha ya''ugö, ha öŵa''ö? [2]', '["MozIII 20:10"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 6, 'Fanandraigö ya''ia, wa laŵa''ö da''ö, ena''ö la''ila mu''adugö ia. Ba ifaöndrö ia tou Yesu, isura danö turunia. [3]', '["Luk 11:53-54; 10:25 b.t."]', NULL),
  (3391606, 'NT', 'Yohane', 8, 7, 'Ba me lö labato wanofu khönia, ba ifuli ifaöga ia, ba imane khöra: Na so ba khömi zi lö horö, ba yamubörötaigö wanebu kara ya''ia. [4]', '["MozV 17:7; Rom 2:1"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 8, 'Ba ifuli ifaöndrö ia manura tanö.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 9, 'Ba ya''ira, me larongo da''ö, ba me itegu ira tödöra, ba monizanizara wofanö, i''otarai zatua, numalö ba zafuria, ba toröi Yesu, ha ya''ia, awö ndra alawe andrö, ba gotaluara no mege. [5]', '["Rom 2:15-22"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 10, 'Ba me no ifaöga ia Yesu ba me lö ni''ilania niha, baero ndra alawe, andrö, ba imane khönia: He alawe, heza so da''ö, sangadugö ya''ugö? Lö sanguhuku ya''ugö?', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 11, 'Ba imane: Lö''ö, Tua. Imane khönia Yesu: Ba ya''odo göi, lö uhuku ndra''ugö. Ofanö, ba böi sa''ae fazökhi horö. [6]', '["Faigi 3:17; 5:14"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 12, 'Ba ifuli muhede khöra Yesu imane: ya''odo haga nösi guli danö andrö. Solo''ö ya''o, ba lö mowaö-waö ba zogömi-gömi, so sa''ae khönia haga ba wa''auri andrö. [7]', '["Faigi 1:4-9; Yes 49:6"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 13, 'Ba lamane khönia farizaio: ya''ugö nifaduhu''ö mö, lö duhu wamaduhu''ömö andrö.[8]', '["Faigi 5:31"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 14, 'Itema lira Yesu, imane khöra: He ya''o samaduhu''ö ya''odo, ba duhu zui wamaduhu''ögu, me no u''ila, he moroi ndra''o, ba heza möido, ba ya''ami, ba lö mi''ila, he moroi ndra''o ba heza möido. [9]', '["Faigi 7:28-33"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 15, 'ösi niha dali wanguhuku khömi, ya''o ba lö uhuku niha. [10]', '["Faigi 7:24; 8:11","Faigi 8:29; 5:30 b.t."]', NULL),
  (3391606, 'NT', 'Yohane', 8, 16, 'Ba he manguhuku ndra''o, ba si ndruhu wanguhukugu, me no tenga ha ya''o, daruaga sa''ae samatenge ya''o. [11]', '["Faigi 7:24; 8:11","Faigi 8:29; 5:30 b.t."]', NULL),
  (3391606, 'NT', 'Yohane', 8, 17, 'Ba noa göi so ba goroisa khömi, si duhu wamaduhu''ö zi darua. [12]', '["MozV 17:6; 19:15"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 18, 'ya''odo zamaduhu''ö ya''o, ba ifaduhu''ö ndra''o samatenge ya''o, Amagu. [13]', '["Faigi 5:37"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 19, 'Ba lamane khönia: Heza so Namau andrö? Itema lira Yesu, imane: Lö mi''ila ha niha ndra''o, ba lö''ö göi mi''ila ha niha Namagu andrö. Na mi''ila ena''ö ha niha ndra''o, ba mi''ila göi ha niha Namagu andrö. [14]', '["Faigi 16:3; 14:7"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 20, 'Ba zinga naha game''ela iŵa''ö da''ö, me mamahaö ia ba gosali. Ba lö sondra''u ya''ia, me lö''ö na irugi inötö andrö khönia. [15]', '["Mar 12:41; Faigi 7:30; Luk 22:33"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391606, 'NT', 'Yohane', 8, 21, 'Ba imane zui Yesu khöra: Mofanö ndra''o, ba mi''alui ndra''o dania, ba mate ami ba horömi. Tebai möi ami ba zi möi ndra''o. [16]', '["Faigi 7:33,34"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 22, 'Ba lamane niha Yehuda: Ta''ila na ibunu ia dania, wa iŵa''ö: Tebai möi ami ba zi möi ndra''o? [17]', '["Faigi 7:35"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 23, 'Ba imane khöra: Moroi si tou ami, moroi si yaŵa ndra''odo; moroi ba guli danö andre ami, tenga moroi ba guli danö andre ndra''odo. [18]', '["Faigi 3:31"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 24, 'Andrö no uŵa''ö khömi, si mate ami ba horömi. Na lö''ö sa mamati ami, wa ya''odo, ba si mate ami ba horömi. [19]', '["Faigi 4:26"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 25, 'Ba lamane khönia: Ha niha ndra''ugö? Imane khöra Yesu: Niŵa''ögu khömi göi, i''otarai mböröta. [20]', '["Hes 12:25; Yes 52:6"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 26, 'Oya niŵa''ögu ba khömi andrö, ba oya nihukugu, ba samatenge ya''o, ba no si ndruhu, ba nirongogu khönia, da''ö niŵa''ögu ba niha ba guli danö. [21]', '["Faigi 3:33"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 27, 'Ba lö aboto ba dödöra, wa Amania niŵa''önia khöra.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 28, 'Ba imane Yesu: Na no mi''alaŵa''ö yaŵa dania Nono Niha, awena dania aboto ba dödömi, wa ya''odo, awö wa lö hadia ia zoroi ba khögu, nilaugu. u''o''ö wamahaö Namagu ya''o, da''ö huhuogu. [22]', '["Faigi 12:32; 5:19; 7:16"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 29, 'Ba fao-fao khögu zamatenge ya''o. Lö iröi ndra''o, ha ya''o, me lö mamalö-malö ulau zomasi ia.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 30, 'Me iŵa''ö da''ö, ba ato zamati khönia.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 31, 'Ba imane Yesu ba niha Yehuda, si no mamati khönia: Na lö tebulö ami ba daroma ligu andrö, ba si ndruhu nifahaögu ami; [23]', '["Faigi 7:17"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 32, 'ba aboto ba dödömi zi duhu, ba i''efa''ö ami si duhu andrö. [24]', '["Gal 5:1; Yak 1:25"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 33, 'Latema linia, lamane: Ma''uwu Gaberahamo ndra''aga, ba lö marai möi sawuyu niha bö''ö, hadia wa öŵa''ö: Ni''efa''ö ami? [25]', '["Mat 3:9; Neh 9:36"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 34, 'Itema lira Yesu, imane: Si ndruhu-ndruhu niŵa''ögu khömi, sawuyu horö zamazökhi horö. [26]', '["Rom 6:16,20"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 35, 'Ba tenga sa si lö mamalö-malö yomo zawuyu, si lö mamalö-malö nono. [27]', '["MozI 29:10; MozII 21:2; Sin 23:6"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 36, 'Ba na i''efa''ö ami Ono andrö, awena aefa sibai ami. [28]', '["Rom 6:18; 8:2"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 37, 'u''ila, wa no ma''uwu Gaberahamo ami; ba mi''alui wamunu ya''o, me lö fakhai daroma ligu ba dödömi. [29]', '["Faigi 5:18"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 38, 'uŵa''ö hadia ni''ilagu khö Namagu; ba ya''ami sa göi, mi''o''ö nirongomi khö namami andrö.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 39, 'Latema linia, lamane khönia: Aberahamo duama. Imane khöra Yesu: Na ma''uwu Gaberahamo ami, ba mi''o''ö ena''ö mbua-bua Gaberahamo. [30]', '["Gal 3:7"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 40, 'Ba mi''alui sa wamunu ya''o, niha sanguma''ö khömi si duhu, nirongogu khö Lowalangi; tenga si manö Gaberahamo.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 41, 'Bua-bua namami andrö mi''o''ö. Lamane khönia: Tenga ono horö ndra''aga, ha samosa namama, Lowalangi.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 42, 'Imane khöra Yesu: Na amami Lowalangi mena''ö, ba mi''omasi''ö ndra''o. Moroi ba Lowalangi sa mbörötagu, ba da''ö u''otarai; tenga sa moroi ba khögu, wa no so ndra''o, Ya''ia sa zamatenge ya''o. [31]', '["Faigi 5:43; 16:27"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 43, 'Hana wa lö aboto ba dödömi wehedegu, wa tebai mifondro-ndrongo ligu? [32]', '["Faigi 6:60; KorI 2:14"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 44, 'Moroi ba Gafökha ami, ba no edöna ami mi''o''ö wa''omasi namami andrö. No samunu niha da''ö, i''otarai mböröta, ba lö ni''agönia si duhu, lö''ö sa si duhu ba dödönia. Na iŵa''ö waya, ba moroi ba zi so khönia muhede ia, sofaya sa ia ba ama zofaya. [33]', '["YohI 3:8-10; MozI 3; FetII 2:4"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 45, 'Ba me no si duhu niŵa''ögu, andrö lö mamati ami.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 46, 'Ha niha ba khömi zanegu horö ba khögu zambalö? Na uŵa''ö zi duhu, ba hana wa lö mamati ami khögu? [34]', '["FetI 2:22; KorII 5:21"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 47, 'Si otarai Lowalangi, ba ifondrondrongo li Lowalangi, andrö lö mamondrongo ami, me tenga moroi ba Lowalangi ami. [35]', '["Faigi 18:37; YohI 4:6"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 48, 'Latema linia niha Yehuda, lamane khönia: Tenga si duhu niŵa''öma, wa Dawa Zamaria ndra''ugö, sobekhu? [36]', '["Faigi 7:20"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 49, 'Itema lira Yesu, imane: Tenga sobekhu ndra''odo, ufosumange sa Namagu, ba ya''ami, ba mi''o''aya ndra''o.', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 50, 'Ba lö u''alui zumangegu, so zangalui ya''ia, sanguhuku. [37]', '["Faigi 5:41"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 51, 'Si ndruhu-ndruhu niŵa''ögu khömi, na so zolo''ö ligu, ba lö''ö manö i''ila wa''amate, irugi zi lö aetu. [38]', '["Faigi 5:24; 11:25 b.t."]', NULL),
  (3391606, 'NT', 'Yohane', 8, 52, 'Lamane khönia niha Yehuda; Awena aboto ba dödöma, wa sobekhu ndra''ugö. No mate Gaberahamo, awö zama''ele''ö andrö, ba öŵa''ö: Na so zolo''ö ligu, ba lö''ö manö itandra wa''amate, irugi zi lö aetu. [39]', '["Sakh 1:5"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 53, 'Hadia, ebua ndra''ugö, moroi khö duada Aberahamo, si no mate? Ba sama''ele''ö andrö, ba no mate. Hadia öbali''ö ndra''ugö?', '[]', NULL),
  (3391606, 'NT', 'Yohane', 8, 54, 'Itema lira Yesu imane: Na ufolakhömi ndra''o, ba faya lakhömigu andrö. Amagu zamolakhömi ya''ö, niŵa''ömi: Lowalangima ia. [40]', '["Faigi 5:31-32"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 55, 'Ba lö aboto ba dödömi ia, ba ya''o, ba sangila ya''ia. Ba na uŵa''ö ena''ö, lö u''ila ia, ba sofaya ndra''o, si mane ya''ami. Ba no u''ila ia, ba u''o''ö linia. [41]', '["Faigi 7:28"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 56, 'Owua-wua dödö duami Aberahamo, ena''ö i''ila mbaŵagu andrö, ba i''ila, ba omuso dödönia. [42]', '["Heb 11:13"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 57, 'Lamane khönia niha Yehuda: Ambö na lima wulu fakhe ndra''ugö, ba no ö''ila Gaberahamo? [43]', '["Luk 3:23"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 58, 'Imane khöra Yesu: Si ndruhu-ndruhu niŵa''ögu khömi lö Aberahamo na, ba so ndra''o, [44]', '["Faigi 1:1-2; Yes 43:13; MozII 3:14"]', NULL),
  (3391606, 'NT', 'Yohane', 8, 59, 'Ba latuyu gara, ba wanebu ya''ia. Ba ibini''ö ia Yesu, ba iheta ia ba gosali. [45]', '["Faigi 10:31; MozIII 24:16; Luk 4:30"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 1, 'Me itörö Yesu, ba i''ila niha, sau''a moroi ba dalu ninania.', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 2, 'Ba lasofu khönia nifahaönia, lamane: He samahaö, ha niha zamazökhi horö, da''e, ma ira amania, wa no au''a ia moroi ba dalu ninania?[1]', '["Luk 13:2"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 3, 'Itema lira Yesu, imane: Tenga da''e zamazökhi horö, ba tenga göi ira amania; ba ena''ö te''oroma''ö ba khönia wolau Lowalangi, andrö si manö.[2]', '["Faigi 11:4","Faigi 5:17-19","Faigi 8:12"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 4, 'Lö tola lö tahalö halöŵö zamatenge ya''ita, fatua moluo. Bongi dania, ba lö sangila mohalöŵö.[3]', '["Faigi 11:4","Faigi 5:17-19","Faigi 8:12"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 5, 'Fatua sodo ba guli danö, ba haga ba guli danö ndra''odo.[4]', '["Faigi 11:4","Faigi 5:17-19","Faigi 8:12"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 6, 'Aefa iŵa''ö da''ö, ba idiloi danö ba ibali''ö tambu gilo andrö, ba igule''ö dambu andrö ba hörö andrö,[5]', '["Mar 8:23"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 7, 'ba imane khönia: Ae sasai mbawau ba mbaŵa Ziloa andrö, "nifatenge" geluahania.', '["Mar 8:23"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 8, 'Me itörö Yesu, ba i''ila niha, sau''a moroi ba dalu ninania. Ba lamane banuara, awö zi no mangila ya''ia föna, me mangandrö-ngandrö böli gö ia: Tenga ya''ia da''ö, si dadao, mangandrö-ngandrö böli gö?[6]', '["HalZin 3:10"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 9, 'Ba so zanguma''ö: ya''ia. Ba so göi zanguma''ö: Tenga, ba no fakhili-khili ia khönia. Ba ya''ia iŵa''ö: ya''odo da''ö.', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 10, 'Ba lamane khönia: He wisa, wa tebokai hörömö?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 11, 'Itema lira, imane: Niha andrö, sotöi Yesu, ifazökhi dambu ba igule''ö ba hörögu, ba imane khögu: Ae ba Ziloa, sasai mbawau. Ba möido, ba me no usasaido, ba u''ila niha.', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 12, 'Lamane khönia: Heza so ia?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 13, 'Ba la''ohe ia ba warizaio, zau''a föna andrö.[7]', '["Faigi 7:32; 11:46"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 14, 'Ba luo sabato, me luo ifazökhi dambu andrö Yesu, me ibokai hörönia.[8]', '["Faigi 5:9 b.t."]', NULL),
  (3391607, 'NT', 'Yohane', 9, 15, 'Ba lafuli lasofu khönia farizaio göi, hewisa, wa i''ila niha. Ba imane khöra: Tambu ibe''e ba hörögu, ba no usasai mbawagu, ba u''ila niha.', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 16, 'Ba lamane farizaio ösa: Tenga si otarai Lowalangi niha andrö, me lö i''amoni''ö luo sabato. Ba lamane tanö bö''ö: He moroi i''ila ifazökhi dandra si manö niha si so horö? Ba lö faoma dödöra.[9]', '["Faigi 7:43"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 17, 'Ba lafuli lamane khö zau''a andrö: Ba ya''ugö, hadia öŵa''ö ba khönia andrö, me no ibokai höröu?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 18, 'Ba lö faduhu dödö niha Yehuda khönia, wa no au''a ia föna, awö wa i''ila niha iada''e, irege muhede ira khö ndra ama zi no teboka hörö andrö.', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 19, 'Ba lasofu khöra, lamane: Hadia, onomi da''ö, niŵa''ömi no au''a ia moroi ba dalu ninania?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 20, 'Ba he wisa wa i''ila niha iada''e?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 21, 'ba he moroi wa i''ila niha iada''e, ba lö ma''ila, ba ha niha zamokai hörönia, ba lö ma''ila. Misofu khönia, noa sa''ae wa''ebuania, ba iŵa''ö dania hadia ia khönia.', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 22, 'Me ata''u ndra amania niha Yeduda, andrö laŵa''ö da''ö. Noa sa mamagölö niha Yehuda, na so ena''ö zanguma''ö Keriso Yesu andrö, ba latibo''ö ia banua.[11]', '["Faigi 7:13; 12:2"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 23, 'Andrö laŵa''ö ira amania: Noa sa''ae wa''ebuania, misofu khönia.', '["Faigi 7:13; 12:2"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 24, 'Awena muhede ira zamuza tö ba niha andrö, sau''a föna, ba lamane khönia: Fosumange Lowalangi, ya''aga, ba ma''ila, wa no si so horö niha andrö.[12]', '["Faigi 8:46"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 25, 'Itema lira, imane: Lö u''ila, na si so horö ia, sambalö u''ila, sau''a ndra''o föna, ba u''ila niha iada''e.', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 26, 'Ba lamane khönia: He iwisa khöu? He iwisa wamokai höröu?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 27, 'Itema lira, imane: Noa sa''ae uŵa''ö khömi, ba lö nifondrondrongomi. Hana wa omasi ami, mirongo zamuza tö? Ma edöna ami göi möi nifahaönia?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 28, 'Mofönu ira khönia, lamane: ya''ugö nifahaönia, nifahaö Moze ndra''aga.', '["Faigi 7:27; 8:14"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 29, 'Ma''ila, wa no muhede Lowalangi khö Moze, ba da''ö, ba lö ma''ila, he moroi ia.[13]', '["Faigi 7:27; 8:14"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 30, 'Itema lira niha andrö, imane khöra: Ba da''ö so zahöli-höli dödöda, wa lö mi''ila, he moroi ia, ba no ibokai hörögu.', '["Yob 35:13; Sin 145:19; Amaed 15:8"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 31, 'No ta''ila, lö ifondrondrongo li zi so horö Lowalangi ba na so zangata''ufi ya''ia, solo''ö somasi ia, khönia ifondrondrongo.[14]', '["Yob 35:13; Sin 145:19; Amaed 15:8"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 32, 'I''otarai mböröta ba lö murongo, so niha samokai hörö zau''a moroi ba dalu ninania.', '["Yob 35:13; Sin 145:19; Amaed 15:8"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 33, 'Na tenga si otarai Lowalangi da''ö, ba tebai ilau hadia ia mena''ö.', '["Yob 35:13; Sin 145:19; Amaed 15:8"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 34, 'Latema linia, lamane khönia: Me tumbu ndra''ugö, ba no si so horö manö ndra''ugö, ba öfahaö ndra''aga? Ba latuli''ö ia baero.[15]', '["Faigi 9:2-3"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 35, 'Irongo Yesu, wa no latuli''ö ia baero, ba me falukha ia khönia, ba imane khönia: Hadia, mamati ndra''ugö khö Nono Niha andrö?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 36, 'Itema linia, imane: Ha niha ia, Tua, ena''ö mamati ndra''o khönia?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 37, 'Imane khönia Yesu: Noa sa ö''ila ia, ba sihede khöu, da''ö ia.[16]', '["Faigi 4:26"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 38, 'Ba imane: Mamati ndra''o, Tua! ba mangalulu ia khönia.', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 39, 'Ba imane Yesu: Börö huku, wa möi ndra''o ba guli danö andre, ena''ö la''ila niha sau''a, ba ena''ö au''a zangila niha.[17]', '["Mat 13:14-15"]', NULL),
  (3391607, 'NT', 'Yohane', 9, 40, 'Larongo farizaio ösa, si fao khönia ba da''ö, ba lamane khönia: Ba hadia, sau''a göi ndra''aga?', '[]', NULL),
  (3391607, 'NT', 'Yohane', 9, 41, 'Imane khöra Yesu: Na sau''a ami, ba lö horömi ena''ö, ba iya''e, ba miŵa''ö: Ma''ila niha: ba lö tebulö horömi.[18]', '["Faigi 15:22; Hes 13:10-16"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 1, 'Si ndruhu-ndruhu niŵa''ögu khömi, si lö manörö bawandruhö andrö, we''amöi ba kandra mbiri-biri andrö, sanawö ba''a-ba''a, ba sanagö da''ö ba samara''u.[1]', '["Yer 23:2 b.t.; Sin 23","Ayati 7","Yes 43:1"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 2, 'Sanörö bawandruhö da''ö gubalo mbiri-biri. [2]', '["Yer 23:2 b.t.; Sin 23","Ayati 7","Yes 43:1"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 3, 'Khönia ibokai sanaro ba mbawadruhö andrö, ba lafondrondrongo linia biri-biri, ba humede ia ba mbiri-biri tana khönia itötöi döi, ba i''ohe baero.[3]', '["Yer 23:2 b.t.; Sin 23","Ayati 7","Yes 43:1"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 4, 'Ba na no ibe''e baero dana khönia fefu, ba mowaö-waö ia, ba la''o''ö ia mbiri-biri, noa sa la''ila linia.', '["Yer 23:2 b.t.; Sin 23","Ayati 7","Yes 43:1"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 5, 'Ba lö la''o''ö niha bö''ö, moloi sa ira khönia, me lö la''ila li niha bö''ö.', '["Yer 23:2 b.t.; Sin 23","Ayati 7","Yes 43:1"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 6, 'Amaedola andrö iŵa''ö khöra Yesu, ba lö aboto ba dödöra hadia ia, niŵa''önia khöra.', '[]', NULL),
  (3391608, 'NT', 'Yohane', 10, 7, 'Ba imane Yesu: Si ndruhu-ndruhu niŵa''ögu khömi, ya''odo mbawandruhö ba mbiri-biri.', '["Mat 7:15–23,13","Faigi 14:6; MozIV 27:17,21","Sin 23:1; FetI 2:25"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 8, 'Dozi ira, ha wa''ato zi no möi, ba no sanagö ba no samara''u, ba lö lafondrondrongo khöra biri-biri.[4]', '["Mat 7:15–23,13","Faigi 14:6; MozIV 27:17,21","Sin 23:1; FetI 2:25"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 9, 'Ya''o mbawandruhö. Na so zanörö ya''o, we''amöi bakha, da''ö ni''orifi, ba möi ia bakha ba möi baero, ba isöndra gö.[5]', '["Mat 7:15–23,13","Faigi 14:6; MozIV 27:17,21","Sin 23:1; FetI 2:25"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 10, 'Lö möi zanagö, na tenga ba wanagö ba ba wamunu ba ba wamakiko. Ba da''ö möi ndra''o, ena''ö so khöra wa''auri ba ena''ö fahöna khöra wa''auri ba ena''ö fahöna khöra hadia ia andrö.[6]', '["Mat 7:15–23,13","Faigi 14:6; MozIV 27:17,21","Sin 23:1; FetI 2:25"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 11, 'Ya''odo gubalo si sökhi andrö. Kubalo si sökhi ibelegö nosonia föna mbiri-biri.[7]', '["Yes 40:11; Hes 34:11 b.t.; YohI 3:16","Sakh 11:16 b.t."]', NULL),
  (3391608, 'NT', 'Yohane', 10, 12, 'Moloi genoni, si tenga kubalo, si tenga sokhö mbiri-biri, na i''ila nasu gatua moroi sa, iröi mbiri-biri, ba ira''u asu gatua ba ifazawili.[8]', '["Yes 40:11; Hes 34:11 b.t.; YohI 3:16","Sakh 11:16 b.t."]', NULL),
  (3391608, 'NT', 'Yohane', 10, 13, 'Me enoni ia, ba me lö ba dödönia mbiri-biri.', '["Yes 40:11; Hes 34:11 b.t.; YohI 3:16","Sakh 11:16 b.t."]', NULL),
  (3391608, 'NT', 'Yohane', 10, 14, 'Ya''odo gubalo si sökhi andrö, ba no aboto ba dödögu dana khögu, ba no aboto ba dödö dana khögu ndra''odo.[9]', '["TimII:2–19","Mat 11:27; Mar 10:45"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 15, 'Si mane fa''aboto ba dödö Namagu ndra''o, ba si mane fa''aboto ba dödögu Namagu. Ba ubelegö nosogu föna mbiri-biri.[10]', '["TimII:2–19","Mat 11:27; Mar 10:45"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 16, 'Ba so khögu na mbiri-biri bö''ö, si tenga moroi ba kandra andre, ba lö tola lö uhalö ira, ba lafondrondrongo ligu dania ba tobali ha sambawa nikubaloi ba ha samösa gubalo.[11]', '["Faigi 11:52; Mat 8:11; Yes 49:6; Sakh 14:9; Efes 2:14 b.t."]', NULL),
  (3391608, 'NT', 'Yohane', 10, 17, 'Andrö i''omasi''ö ndra''o Amagu, me ube''e nosogu, ba wanema ya''ia mangawuli.[12]', '["Faigi 2:19; Yes 53:10","Faigi 18:6; 14:31"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 18, 'Lö sangai ya''ia khögu, ube''e sa''ae ia, nilau dödögu. Tola ube''e ia, ba tola ufuli uhalö. Oroisa andrö no utema khö Namagu.[13]', '["Faigi 2:19; Yes 53:10","Faigi 18:6; 14:31"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 19, 'Ba fabö''ö zui dödö niha Yehuda, ba niŵa''önia andrö.[14]', '["Faigi 7:43","Faigi 7:20"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 20, 'Ba ato khöra zaguma''ö: Sobekhu, sowöhö, hana wa mifondrondrongo khönia?[15]', '["Faigi 7:43","Faigi 7:20"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391608, 'NT', 'Yohane', 10, 21, 'Ba lamane tanö bö''ö: Tenga fehede zobekhu wehede andrö. Hadia, i''ila ibokai hörö zau''a bekhu?[16]', '["Faigi 9:30 b.t.; MozII 4:11"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 22, 'Ba luo we''amoni''ö osali ba Yeruzalema, baŵa deu.', '["HalZin 3:11; 5:12"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 23, 'Ba manörö-nörö Yesu ba zinga gosali, baolayama Zelomo andrö.[17]', '["HalZin 3:11; 5:12"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 24, 'Ba lafasui ia niha Yehuda ba lamane khönia: Heza irugi lö ahono dödöma öbe''e? Na Keriso ndra''ugö, ba ŵa''ö khöma, böi aiŵö ndra''ugö.[18]', '["Faigi 8:25"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 25, 'Itema lira Yesu, imane: No uŵa''ö khömi, ba lö faduhu dödömi; halöŵö andrö, nihalö-halögu ba döi Namagu, da''ö zamaduhu''ö ya''o.[19]', '["Faigi 5:36","Faigi 8:45,47"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 26, 'Ba lö faduhu dödömi, me tenga biri-birigu ami.[20]', '["Faigi 5:36","Faigi 8:45,47"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 27, 'Lafondrondrongo ligu biri-birigu, ba no aboto ba dödögu ira, ba la''o''ö ndra''o. 28 Ba ube''e khöra wa''auri si lö aetu, ba lö tekiko ira, götö-götö wa''ara ba lö sanöbi ya''ira ba dangagu. 29 Ebua moroi ba danö bö''ö fefu Namagu, same''e ya''ira khögu, ba lö sangila manöbi ya''ira ba danga Namagu. 30 Ha sambua ndra''aga Amagu.', '["Faigi 8:51; 5:24; Rom 8:38 b.t.; FetI 1:5","Faigi 14:28","Faigi 10:37–38; 5:23; 17:10; 11:21"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 28, 'Ba ube''e khöra wa''auri si lö aetu, ba lö tekiko ira, götö-götö wa''ara ba lö sanöbi ya''ira ba dangagu.', '[]', NULL),
  (3391608, 'NT', 'Yohane', 10, 29, 'Ebua moroi ba danö bö''ö fefu Namagu, same''e ya''ira khögu, ba lö sangila manöbi ya''ira ba danga Namagu.[22]', '["Faigi 8:51; 5:24; Rom 8:38 b.t.; FetI 1:5","Faigi 14:28","Faigi 10:37–38; 5:23; 17:10; 11:21"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 30, 'Ha sambua ndra''aga Amagu.[23]', '["Faigi 8:51; 5:24; Rom 8:38 b.t.; FetI 1:5","Faigi 14:28","Faigi 10:37–38; 5:23; 17:10; 11:21"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 31, 'Ba latuyu zui gara niha Yehuda, ba wanebu ya''ia.[24]', '["Faigi 8:59"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 32, 'Humede khöra Yesu, imane: No oya halöŵö si sökhi, ni''oroma''ögu khömi, dali Namagu. Hezo mbörö ba halöŵö andrö, wa mitebu kara ndra''o?[25]', '["Mar 7:37"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 33, 'Latema linia niha Yehuda, lamane: Tenga ba halöŵö si sökhi andrö matebu kara ndra''ugö, ba wangaoha-ngaoha andrö, ba me öbali''ö Lowalangi ndra''ugö, ba no niha ndra''ugö.[26]', '["Faigi 5:18; Mat 26:65"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 34, 'Itema lira Yesu, imane: Tenga no so ba zura goroisa khömi: "No uŵa''ö, Lowalangi ami?" [27]', '["Sin 82:6","Mat 5:18 b.t.","Faigi 7:17–23","Faigi 15:24; 14:9–11"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 35, 'Na ibe''e töi da''ö Lowalangi, ba nitandrösaigö li Lowalangi andrö — ba tebai tewu''ai zura [28] —', '["Sin 82:6","Mat 5:18 b.t.","Faigi 7:17–23","Faigi 15:24; 14:9–11"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 36, 'ba hadia, ba miŵa''ö ba ni''amoni''ö Nama andrö, ba nifatengenia ba guli danö: Mangaoha-ngaoha ndra''ugö, me no uŵa''ö: Ono Lowalangi ndra''o? [29]', '["Sin 82:6","Mat 5:18 b.t.","Faigi 7:17–23","Faigi 15:24; 14:9–11"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 37, 'Na lö uhalö halöŵö Namagu, ba böi mi''amati khögu.', '["Sin 82:6","Mat 5:18 b.t.","Faigi 7:17–23","Faigi 15:24; 14:9–11"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 38, 'Ba na uhalö ia, ba mi''amati ba halöŵögu, na lö mamati ami khögu, ena''ö mi''ila, ba ena''ö aboto ba dödömi, ba dödögu so Namagu ba ba dödö Namagu so ndra''o.[30]', '["Sin 82:6","Mat 5:18 b.t.","Faigi 7:17–23","Faigi 15:24; 14:9–11"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 39, 'Ba latandraigö zui, wondra''u ya''ia, ba iheta ia ba dangara.', '[]', NULL),
  (3391608, 'NT', 'Yohane', 10, 40, 'Ba mofanö zui ia miyefo Yoridano, ba zi so Yohane, me awena mamayagö idanö ia. [31]', '["Faigi 1:28"]', NULL),
  (3391608, 'NT', 'Yohane', 10, 41, 'Ba ato zangondrasi ya''ia ba lamane: Lö''ö sa nifazökhi Yohane tandra: ba fefu niŵa''ö Yohane ba khö da''e, ba no si duhu.[32]', '["Faigi 1:26 b.t.; 3:27 b.t."]', NULL),
  (3391608, 'NT', 'Yohane', 10, 42, 'Ba ato zamati khönia ba da''ö.', '["Faigi 1:26 b.t.; 3:27 b.t."]', NULL),
  (3391609, 'NT', 'Yohane', 11, 1, 'Ba so zofökhö, Lazaro, banua Mbetania, banua ndra Maria Marata, talifusönia.[1]', '["Luk 10:38–39","Faigi 12:3; Mat 26:7 b.t."]', NULL),
  (3391609, 'NT', 'Yohane', 11, 2, 'Ba Maria zamayoini So''aya fanikha samohua, solosi ahe Zo''aya bunia; talifusö da''ö, Lazaro, zofökhö.[2]', '["Luk 10:38–39","Faigi 12:3; Mat 26:7 b.t."]', NULL),
  (3391609, 'NT', 'Yohane', 11, 3, 'Ba lafatenge khö Yesu ira talifusönia alawe, lamane: He Tua, faigi, somasi ndra''ugö andrö, ba no mofökhö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 4, 'Ba me no irongo da''ö Yesu, ba imane: Tenga fökhö ba wa''amate wökhö andrö, fökhö famolakhömi Lowalangi, ena''ö tefolakhömi Nono Lowalangi ba da''ö[3]', '["Faigi 9:3"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 5, 'Ba no omasi Yesu Marata andrö ba talifusönia ba Lazaro andrö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 6, 'Ba me no irongo mofökhö ia, ba dua wongi na ia ba zi so ia.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 7, 'Aefa da''ö, ba imane khö ndra nifahaö: Datafuli ita ba Yudaia.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 8, 'Lamane khönia ira nifahaö: He samahaö, ha mega no, ba labunu ndra''ugö mena''ö niha Yehuda, latebu kara ndra''ugö mena''ö, ba öfuli möi ba da''ö?[4]', '["Faigi 10:31"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 9, 'Itema lira Yesu: Tenga felendrua za zi ma''ö-ma''ökhö? Na so zofanö ba zi ma''ökhö, ba lö manendre ia, me i''ila haga andrö ba guli danö.[5]', '["Faigi 9:4–5","Faigi 12:35"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 10, 'Ba na so sofanö bongi, ba manendre, me lö khönia haga andrö.[6]', '["Faigi 9:4–5","Faigi 12:35"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 11, 'Da''ö niŵa''önia; ba me aefa da''ö, ba imane khöra: No mörö Lazaro andrö, si fahuwu khöda, ba möido mususugi ia.[7]', '["Mat 9:24; KorI:15–20"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 12, 'Ba lamane khönia ira nifahaö: He Tua, na mörö ia, ba abe''e.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 13, 'Ba fa''amatenia niŵa''ö Yesu, ba lawai si ndruhu femörö niŵa''önia.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 14, 'Awena iŵa''ö khöra Yesu, lö ibini''ö: No mate Lazaro.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 15, 'Ba omuso dödögu, börö ami, me lö ya''o ba da''ö, ena''ö faduhu dödömi. Ba mitabu khönia.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 16, 'Ba imane Toma andrö, nifotöi si faero, ba nawönia nifahaö: Damöi ita göi, ena''ö mate ita awönia.[8]', '["Faigi 20:24 b.t."]', NULL),
  (3391609, 'NT', 'Yohane', 11, 17, 'Ba me irugi Yesu, ba irongo, no öfa bonginia ba lewatö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 18, 'Ba ahatö ba Yeruzalema Mbetania andrö, so dua mbadu fofanö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 19, 'Ba no ato niha Yehuda, si möi khö ndra Marata Maria, ba wondrara tödöra, ba khö dalifusöra andrö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 20, 'Ba me irongo Marata so Yesu, ba ifaondragö, ba dumadao yomo Maria.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 21, 'Ba imane Marata khö Yesu: He Tua, ena''ö na no so ndra''ugö ba da''e, ba lö mate mena''ö dalifusögu andrö.[9]', '["Ayati 32","Faigi 9:31–33"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 22, 'Ba iada''e göi, ba u''ila, hadia ni''andröu khö Lowalangi, ba ibe''e khöu Lowalangi.[10]', '["Ayati 32","Faigi 9:31–33"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 23, 'Imane khönia Yesu: Maoso dania dalifusöu andrö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 24, 'Imane khönia Marata: U''ila sa, maoso ia dania, ba wemaoso andrö na luo sa furia[11]', '["Luk 14:14; Faigi 5:25; HalZin 24:15"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 25, 'Imane khönia Yesu: Ya''odo wemaoso ba fa''auri, samati khögu, ba auri, he ŵa''ae mate ia.[12]', '["Faigi 3:36–5; 26:6; 40:54","Yoh 8:51"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 26, 'Ba dozi sauri, samati khögu, ba lö mate, irugi zi lö aetu. Hadia, faduhu dödöu ba da''ö?[13]', '["Faigi 3:36–5; 26:6; 40:54","Yoh 8:51"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 27, 'Imane khönia: E, Tua, mamati sa''ae ndra''o, wa Keriso andrö ndra''ugö, Ono Lowalangi, si möi ba guli danö.[14]', '["Faigi 6:69"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 28, 'Ba aefa iŵa''ö da''ö, ba möi ia muhede khö dalifusönia, Maria, nibini''ö, imane: No so zamahaö, ba muhede ia khöu.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 29, 'Ba ya''ia, me irongo da''ö, ba i''alio''ö ifazaŵa ia, ifaondragö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 30, 'Ba lö''ö na nirugi Yesu banua, ba zi fakhamö Marata khönia mege so ia na.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 31, 'Ba me la''ila niha Yehuda, si so khönia yomo ba da''ö, sondrara tödönia, i''alio''ö wamazaŵa ya''ia Maria ba möi, ba la''o''ö ia, lawai sa möi ia ba lewatö, ba wege-ege ba da''ö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 32, 'Ba me irugi Maria ba zi so Yesu, me i''ila ia, ba ituhi danö fönania, imane khönia: He Tua, ena''ö na no so ndra''ugö ba da''e, ba lö mate mena''ö dalifusögu andrö.[15]', '["Ayati 21"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 33, 'Ba me i''ila Yesu, mege-ege ia, ba mege-ege niha Yehuda andrö si fao khönia, ba mofönu ia ba dödönia, ba ifatalikhö ia.[16]', '["Mar 8:12"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 34, 'Ba imane: Heza labe''e ia?', '["Mar 8:12"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 35, 'Me''e Yesu.[17]', '["Luk 19:41"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 36, 'Ba lamane niha Yehuda: Hiza wa''omasinia ia.', '["Faigi 9:6–32"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 37, 'Ba so ba khöra zanguma''ö: Hadia, lö i''ila i''orifi da''ö göi mena''ö samokai hörö zau''a andrö?[18]', '["Faigi 9:6–32"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 38, 'Ba mofönu zui Yesu ba dödönia, ba irugi lewatö. Ba tögi narö gara lewatö andrö, nifolagö gowe.[19]', '["Mat 27:60"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 39, 'Ba imane Yesu: Mifazaŵa gowe andrö.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 40, 'Imane khönia Yesu: Tenga no uŵa''ö khöu, na faduhu dödöu, ba oroma khöu lakhömi Lowalangi?[20]', '["Faigi 11:4–23"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 41, 'Awena lafazaŵa gowe andrö. Ba ifaöga hörönia Yesu, ba imane: He Ama, saoha gölöu, me no öfondrondrongo ligu![21]', '["Faigi 17:1","Yoh 12:30"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 42, 'Ba u''ila, lö mamalö-malö, wa öfondrondrongo ligu, ba börö niha sato andre, samasui ya''o, wa uŵa''ö, ena''ö faduhu dödöra, wa no ya''ugö zamatenge ya''o.[22]', '["Faigi 17:1","Yoh 12:30"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 43, 'Ba me aefa iŵa''ö da''ö, ba i''ebua''ö linia we''ao, imane: He Lazaro, ae baero!', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 44, 'Möi baero zi mate, no mu''olohuni gahenia ba tangania lembe ba lewatö, ba bawania, ba nibalugö lembe folosi mböböi. Ba imane khöra Yesu: Mitoto''ö khönia ba mifofanö ia.[23]', '["Luk 8:49 b.t.; 7:11 b.t."]', NULL),
  (3391609, 'NT', 'Yohane', 11, 45, 'Ba ato zamati khönia niha Yehuda, si no möi khö Maria, me la''ila nilau Yesu.[24]', '["Faigi 7:31"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 46, 'Ba so ösa khöra, zi möi ba warizaio, la''ombakha''ö khöra hadia nilau Yesu.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 47, 'Ba lafalukha''ö zalaŵa rafe sebua sangila amakhoita ba farizaio ba lamane: He tawisa? Oya sa ifazökhi tandra niha andrö.[25]', '["Mat 26:3 b.t.; Luk 16:31","Faigi 12:19"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 48, 'Na tatehe manö khönia zi manö, ba ahori mamati ira khönia, ba möi dania Ndrawa Roma ba la''okhögö danöda, fabaya niha.[26]', '["Mat 26:3 b.t.; Luk 16:31","Faigi 12:19"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 49, 'Ba imane khöra awöra si samösa, Kayafa, ere sebua zi döfi andrö: Lö mi''ila watahögö hadia ia, ba lö mifatou-tou,', '["Faigi 18:14"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 50, 'wa mohare ita, na mate zamösa niha, salahi mbanuada andre, fa böi tekiko mbanuada andre ma''afefu.[27]', '["Faigi 18:14"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 51, 'Ba tenga moroi khönia, wa iŵa''ö da''ö, me no ere sebua ia zi döfi andrö, ba mama''ele''ö ia; mate sa dania Yesu salahi mbanuara andrö.[28]', '["Amaed 16:1–10; SamI 1:17","Faigi 10:16"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 52, 'Ba tenga ha salahi mbanuara, ena''ö i''owuloi göi nono Lowalangi andrö, sizaewe, ena''ö orudu[29]', '["Amaed 16:1–10; SamI 1:17","Faigi 10:16"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 53, 'I''otarai luo da''ö, ba mamagölö ira sa''ae, ba wamunu ya''ia.[30]', '["Mat 21:38"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 54, 'Ba lö''ö sa''ae i''oroma''ö ia Yesu ba niha Yehuda, mofanö ia ba da''ö, isaŵa danö ba zinga danö si mate, banua andrö, sotoi Eferayi, ba da''ö soso ia, awö nifahaönia.', '[]', NULL),
  (3391609, 'NT', 'Yohane', 11, 55, 'Ba no ahatö wasa andrö, ba niha Yehuda. Ba ato zi möi misi yaŵa ba Yeruzalema, moroi ba da''ö, föna wasa andrö, ba wangehao ya''ira.[31]', '["Faigi 6:4; Nga''ötII 30:17","Faigi 7:11"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 56, 'Ba la''alui Yesu, ba faoma lamane khö nawöra, me so ira ba gosali: Hadia ba dödömi, wa lö möi ia ba gowasa?[32]', '["Faigi 6:4; Nga''ötII 30:17","Faigi 7:11"]', NULL),
  (3391609, 'NT', 'Yohane', 11, 57, 'Ba no labe''e goroisa ira ere sebua ba farizaio, na so zangila, heza so ia, ba i''ombakha''ö, ena''ö lara''u ia.[33]', '["Faigi 9:22"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 1, 'Önö bongi lö fasa, ba möi ba Mbetania Yesu, ba zi so Lazaro andrö, nisusuginia moroi ba ngai zi mate.[1]', '["Faigi 11:1–43 b.t.","Luk 10:39–40"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 2, 'Ba labe''e gönia ba da''ö, ba sangai halöŵö Marata. Ba samösa Lazaro, awönia ba wemanga.[2]', '["Faigi 11:1–43 b.t.","Luk 10:39–40"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 3, 'Ba ihalö Maria zakati zi ndruhu wanikha narawasu, samohua, sebua böli, ibayoini gahe Yesu ba i''osi bunia; ba afönu nomo hua wanikha andrö.', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 4, 'Ba imane Yuda andrö, banua Kariota, nifahaönia si samösa, si manga mbölinia dania:[3]', '["Faigi 13:26 b.t.; 18:2"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 5, 'Hana wa lö la''amawa wanikha andrö, otu a lima wulu rufia mbölinia mena''ö, ba labe''e ba zi numana?', '["Faigi 13:26 b.t.; 18:2"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 6, 'Ba tenga me so ba dödönia zi numana iŵa''ö da''ö, me no sanagö-nagö ia, me khönia so naha gefe, me ihalö-halö game''ela andrö.[4]', '["Luk 8:3; Faigi 13:29"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 7, 'Ba imane Yesu: Böi tegu ia; no i''irö''ö da''ö, irege luo wogo''o ya''o.', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 8, 'Si lö mamalö-malö awömi zi numana, ba ya''o, ba tenga si lö mamalö-malö khömi.', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 9, 'Ba ato zamondrongo niha Yehuda, no so ia ba da''ö, ba möi ira, tenga ha Yesu mbörö, ba wamaigi Lazaro göi, nisusuginia moroi ba ngai zi mate.', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 10, 'Ba mamagölö gere sebua, ena''ö labunu göi Lazaro andrö;', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 11, 'börö sa ia, wa ato zi so niha Yehuda, samati khö Yesu.', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 12, 'Sara wongi aefa da''ö,[5] me larongo, niha sato, si no möi ba gowasa, no möi ba Yeruzalema Yesu,', '["Ayati 12–18; Mat 21:1–11; Mar 11:1–10; Luk 19:29–38","MozIII 23:40"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 13, 'ba lahalö mbulu nohi, möi ira mamaondragö ya''ia, mu''ao ira: Hosana, ya''ahowu zi so andrö, ba döi Zo''aya, razo Ndraono Gizeraeli andrö![6]', '["Ayati 12–18; Mat 21:1–11; Mar 11:1–10; Luk 19:29–38","MozIII 23:40"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 14, 'Ba me isöndra nono galide Yesu, ba i''okudo, itörö zi so ba zura andrö:', '["Sakh 9:9"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 15, '"Böi ata''ufi, ono Ziona alawe, hiza, so razomö, i''okudo nono galide".[7]', '["Sakh 9:9"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 16, 'Lö''ö sa i''anema''ö aboto ba dödö ndra nifahaö da''ö ba me no tefolakhömi Yesu, awena itörö tödöra, wa ba khönia tesura da''ö, awö wa no lamanö khönia.', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 17, 'Ba lafaduhu''ö niha sato, si fao khönia, wa no humede ia khö Lazaro andrö ba lewatö, wa no isusugi ba ngai zi mate.[8]', '["Luk 19:37"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 18, 'Andrö göi la''ondrasi ia niha sato, me no larongo, no ifazökhi dandra andrö.', '["Luk 19:37"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 19, 'Ba faoma lamane farizaio khö nawöra: Mi''ila, lö''ö manö fakhai wolaumi. Hiza, ahori manö la''o''ö niha ba guli danö.[9]', '["Faigi 3:26; 11:48"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 20, 'Ba so Ndrawa Heleni ösa, awö zi no möi miyaŵa, mangalulu ba gowasa.[10]', '["Faigi 7:35","Luk 19:3"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 21, 'Da''ö zi möi khö Wilifo andrö, banua Mbetisa''ida, ba Galilaia, la''andrö khönia, lamane: He Tua, omasiga ma''ila Yesu.[11]', '["Faigi 7:35","Luk 19:3"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391610, 'NT', 'Yohane', 12, 22, 'Möi Wilifo, iŵa''ö khö Gandrea, ba möi ira, darua ira, Andrea Filifo, laŵa''ö khö Yesu.', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 23, 'Ba itema lira Yesu, imane: No irugi inötö andrö ba wamolakhömi Ono Niha.[12]', '["Faigi 17:1; 13:32","KorI 15:36 b.t.","Luk 17:33","Luk 9:23; Faigi 14:3","Mat 26:38,39"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 24, 'Si ndruhu-ndruhu niŵa''ögu khömi, na lö tetaru ba danö zi samba ngawua ulitö, ba na lö obou, ba ha ya''ia manö; ba na obou ia ua, ba oya mbuania.[13]', '["Faigi 17:1; 13:32","KorI 15:36 b.t.","Luk 17:33","Luk 9:23; Faigi 14:3","Mat 26:38,39"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 25, 'Khö zomasi nosonia aetu ia, ba si fa''udu ba nosonia ba guli danö andre, ba irorogö ba wa''auri si lö aetu.[14]', '["Faigi 17:1; 13:32","KorI 15:36 b.t.","Luk 17:33","Luk 9:23; Faigi 14:3","Mat 26:38,39"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 26, 'Na so zi möi enonigu, ba yamu''o''ö ndra''o, ba ba zi so ya''o, ba da''ö göi so genonigu dania. Na so zi möi enonigu, ba ifosumange Amagu [15]', '["Faigi 17:1; 13:32","KorI 15:36 b.t.","Luk 17:33","Luk 9:23; Faigi 14:3","Mat 26:38,39"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 27, 'Iada''e, ba abu dödögu, ba hadia niŵa''ögu? He Ama, efa''ö ndra''o ba ginötö andre! Ba andrö urugi ginötö andre.[16]', '["Faigi 17:1; 13:32","KorI 15:36 b.t.","Luk 17:33","Luk 9:23; Faigi 14:3","Mat 26:38,39"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 28, 'He Ama, folakhömi döimö!', '["Faigi 17:1; 13:32","KorI 15:36 b.t.","Luk 17:33","Luk 9:23; Faigi 14:3","Mat 26:38,39"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 29, 'Ba lamane niha sato, si so ba da''ö, me larongo da''ö: Mu''ugu mbanua! Ba so göi zanguma''ö: No muhede khönia mala''ika.[18]', '["HalZin 23:9"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 30, 'Itema lira Yesu, imane: Tenga ya''o mbörö, wa so li andrö, ya''ami mbörö.[19]', '["Faigi 11:42","Faigi 16:11; 14:30","Faigi 3:14; 8:28"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 31, 'Fanguhuku ösi guli danö andre iada''e, iada''e tetibo baero zalaŵa guli danö andre.[20]', '["Faigi 11:42","Faigi 16:11; 14:30","Faigi 3:14; 8:28"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 32, 'Ba ya''o, na no te''alaŵa''ö yaŵa ndra''o, moroi ba danö, ba ahori udönisi ira khögu.[21]', '["Faigi 11:42","Faigi 16:11; 14:30","Faigi 3:14; 8:28"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 33, 'Ba wangombakha he wisa wa''amatenia dania iŵa''ö da''ö.', '[]', NULL),
  (3391610, 'NT', 'Yohane', 12, 34, 'Ba latema linia niha sato, lamane: No marongo ba zura goroisa, lö tebulö Keriso andrö irugi zi lö aetu; ba hana wa öŵa''ö ni''alaŵa''ö yaŵa Nono Niha? Ha niha Nono Niha andrö? [22]', '["Sin 45:7; 72:7,17; 110:4; Yes 9:7; Hes 37:35; Dan 7:13,14"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 35, 'Ba imane khöra Yesu: Ma''ifu tö na so ba khömi haga andrö. Mi''oguna''ö haga andrö, ba lalami, fa lö ikhamö ami fa''ogömi-gömi. Sowaö-waö ba zogömi-gömi, ba lö i''ila, heza isaŵa.[23]', '["Faigi 7:33; 11:9,10"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 36, 'Mi''oguna''ö haga andrö, wamati ba haga andrö, ena''ö tobali ono haga ami.', '["Faigi 7:33; 11:9,10"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 37, 'Ba he no si manö wa''oya dandra nifazökhinia ba zanehe ira, ba lö''ö zui mamati ira khönia.[24]', '["HalZin 2:22; Mat 26:1–5","Yes 53:1"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 38, 'Ena''ö itörö niŵa''ö Yesaya andrö, sama''ele''ö, me imane: He So''aya, ha niha zi faduhu tödö ba wangombakha''öma andrö, ba tanga Zo''aya andrö, ba ha khö tefa''ele''ö?[25]', '["HalZin 2:22; Mat 26:1–5","Yes 53:1"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 39, 'Andrö tebai mamati ira, iŵa''ö göi Yesaya:[26]', '["Yes 6:9–10; Mat 13:14 b.t."]', NULL),
  (3391610, 'NT', 'Yohane', 12, 40, '"No ifobalunö höröra ba no i''abe''e''ö dödöra, ena''ö lö la''ila höröra, ba ena''ö lö aboto ba dödöra, ba fa böi lafalalini gera-erara, ba fa böi u''orifi ira."', '["Yes 6:9–10; Mat 13:14 b.t."]', NULL),
  (3391610, 'NT', 'Yohane', 12, 41, 'Da''ö niŵa''ö Yesaya, me no i''ila lakhöminia, ba me itörö linia ia.[27]', '["Yes 6:1"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 42, 'Ba ato sa zui zamati göi khönia salaŵa, ba börö warizaio, wa lö la''ombakha''ö, fa böi latibo''ö banua ira.[28]', '["Faigi 7:48; 9:22","Faigi 5:44"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 43, 'Omasi sa ira zumange ba niha, moroi ba zumange ba Lowalangi.[29]', '["Faigi 7:48; 9:22","Faigi 5:44"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 44, 'Ba mu''ao Yesu, imane: Samati khögu, ba tenga khögu mamati ia, khö samatenge ya''o mamati ia.[30]', '["Faigi 7:16","Faigi 10:30–14;9","Faigi 8:12","Faigi 3:17"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 45, 'Ba sangila ya''o, ba i''ila zamatenge ya''o andrö.[31]', '["Faigi 7:16","Faigi 10:30–14;9","Faigi 8:12","Faigi 3:17"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 46, 'Haga ndra''o, si no möi ba guli danö, ena''ö böi sa''ae so ba zogömi-gömi dozi samati khögu. [32]', '["Faigi 7:16","Faigi 10:30–14;9","Faigi 8:12","Faigi 3:17"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 47, 'Ba na so zamondrondrongo ligu, ba na lö i''o''ö, ba tenga ya''o zanguhuku ya''ia. Tenga sa ba da''ö möi ndra''o, ba wanguhuku ösi guli danö, ena''ö u''orifi nösi guli danö.[33]', '["Faigi 7:16","Faigi 10:30–14;9","Faigi 8:12","Faigi 3:17"]', NULL),
  (3391610, 'NT', 'Yohane', 12, 48, 'Khö zangositengagö ya''o, si lö mamonaha taroma ligu, khönia so sa''ae zanguhuku ya''ia; taroma ligu andrö, niŵa''ögu, da''ö zanguhuku ya''ia, na luo safuria andrö.[34]', '["Faigi 3:18; Mar 16:16","Faigi 5:19 b.t."]', NULL),
  (3391610, 'NT', 'Yohane', 12, 49, 'Tenga sa moroi khögu manö niŵa''ögu; samatenge ya''o, Amagu, ba no ibe''e goroisa khögu, hadia niŵa''ögu, hadia wehedegu.[35]', '["Faigi 3:18; Mar 16:16","Faigi 5:19 b.t."]', NULL),
  (3391610, 'NT', 'Yohane', 12, 50, 'Ba u''ila, fa''auri si lö aetu goroisania andrö. Andrö u''o''ö niŵa''ö Namagu khögu, ba wehedegu andrö.', '["Faigi 3:18; Mar 16:16","Faigi 5:19 b.t."]', NULL),
  (3391612, 'NT', 'Yohane', 13, 1, 'Ba föna gowasa fasa andrö, me no i''ila Yesu, no irugi inötö, aheta ia ba guli danö andre, möi ia khö Nama, si mane fa''omasinia dana khönia ba guli danö, föna, si manö ŵa''omasinia ira irugi gamozua.[1]', '["Mat 26:2; Faigi 16:28"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 2, 'Ba me manga ira ena''ö, me no ibe''e ba dödö Yuda andrö, ono Zimoni, banua Kariota wemanga mböli Yesu Afökha[2] —', '["Luk 22:3","Faigi 3:35"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 3, 'he ŵa''ae no i''ila Yesu, no ibe''e ba dangania fefu hadia ia Ama, ba he ŵa''ae i''ila, khö Lowalangi i''otarai, ba ba Lowalangi möi ia,[3] —', '["Luk 22:3","Faigi 3:35"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 4, 'ba maoso ia ba ngai gö, iheta mbarunia, ihalö lembe, ba i''olembe.', '["Luk 22:3","Faigi 3:35"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 5, 'Aefa da''ö, ba ilau nidanö ba naha wanasa, ba ibörötaigö isasai gahe ndra nifahaö, ba i''osi lembe andrö, ni''olembenia.', '["Luk 22:3","Faigi 3:35"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 6, 'Ba irugi Zimoni Fetero, ba imane khönia da''ö: Ya''ugö zanasai ahegu, Tua?', '[]', NULL),
  (3391612, 'NT', 'Yohane', 13, 7, 'Itema linia Yesu, imane khönia: Iada''e ba lö ö''ila hadia nilaugu, ba aboto ba dödöu dania.', '[]', NULL),
  (3391612, 'NT', 'Yohane', 13, 8, 'Imane khönia Fetero: Irugi zi lö aetu, ba lö tola ösasai gahegu.', '[]', NULL),
  (3391612, 'NT', 'Yohane', 13, 9, 'Imane khönia Simoni Fetero: He Tua, böi ha sambalö ahegu, tanga göi ba högö.', '[]', NULL),
  (3391612, 'NT', 'Yohane', 13, 10, 'Imane khönia Yesu: Akha lö isasai ia si no mondri, noa sa muhaogö nösinia ma''afefu, ba no muhaogö ami, ba lö dozi.[5]', '["Faigi 15:3; Tit 3:5"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 11, 'Noa sa i''ila zi manga mbölinia, andrö iŵa''ö: Lö dozi muhaogö ami.[6]', '["Faigi 6:64–70"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 12, 'Ba me aefa isasai gahera ba i''obaru mbarunia ba ifuli mudadao, imane khöra: Hadia, no aboto ba dödömi nilaugu khömi?', '["Mat 23:8–10","Luk 22:26–27","FetI 2:21","Faigi 15:20; Mat 10:24","Mat 7:21–24; Yak 1:25","Sin 41:10; Mat 26:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 13, 'Mibe''e töigu zamahaö ba So''aya ba si sökhi, na miŵa''ö da''ö, si ndruhu da''ö.[7]', '["Mat 23:8–10","Luk 22:26–27","FetI 2:21","Faigi 15:20; Mat 10:24","Mat 7:21–24; Yak 1:25","Sin 41:10; Mat 26:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 14, 'Ba na no usasai gahemi, ya''odo andre, So''aya ya''ami, samahaö ya''ami, ba mo''ömö göi ami, wanasai ahe nawömi.[8]', '["Mat 23:8–10","Luk 22:26–27","FetI 2:21","Faigi 15:20; Mat 10:24","Mat 7:21–24; Yak 1:25","Sin 41:10; Mat 26:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 15, 'Famaedo nibe''egu khömi, ena''ö mi''o''ö nilaugu khömi.[9]', '["Mat 23:8–10","Luk 22:26–27","FetI 2:21","Faigi 15:20; Mat 10:24","Mat 7:21–24; Yak 1:25","Sin 41:10; Mat 26:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 16, 'Si ndruhu-ndruhu niŵa''ögu khömi, tenga sebua, moroi khö zokhö ya''ia, zawuyu, ba tenga sebua, moroi khö zamatenge ya''ia zinenge.[10]', '["Mat 23:8–10","Luk 22:26–27","FetI 2:21","Faigi 15:20; Mat 10:24","Mat 7:21–24; Yak 1:25","Sin 41:10; Mat 26:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 17, 'Na no mi''ila da''ö, ba ya''ahowu ami, na mi''o''ö, wolau ya''ia.[11]', '["Mat 23:8–10","Luk 22:26–27","FetI 2:21","Faigi 15:20; Mat 10:24","Mat 7:21–24; Yak 1:25","Sin 41:10; Mat 26:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 18, 'Lö dozi ami da''ö, niŵa''ögu; u''ila, ha niha nitutuyugu. Ba ena''ö itörö zi so ba zura andrö: "Awögu ba wemanga andrö, ba no ifazaŵa mbörö sisinia khögu".[12]', '["Mat 23:8–10","Luk 22:26–27","FetI 2:21","Faigi 15:20; Mat 10:24","Mat 7:21–24; Yak 1:25","Sin 41:10; Mat 26:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 19, 'I''otarai da''e, uŵa''ö khömi, fatua lö alua, ena''ö faduhu dödömi, wa ya''odo, na no alua dania.[13]', '["Faigi 14:29–16;4","Mat 10:40 b.t."]', NULL),
  (3391612, 'NT', 'Yohane', 13, 20, 'Si ndruhu-ndruhu niŵa''ögu khömi, samonaha, na so nifatengegu, ba ifonaha ndra''o; ba samonaha ya''o, ba ifonaha zamatenge ya''o andrö.[14]', '["Faigi 14:29–16;4","Mat 10:40 b.t."]', NULL),
  (3391612, 'NT', 'Yohane', 13, 21, 'Aefa iŵa''ö da''ö Yesu, ba abu dödönia, ba ifaduhu''ö, imane: Si ndruhu-ndruhu niŵa''ögu khömi, samösa ba khömi zi manga mböligu dania.[15]', '["Mat 26:21 b.t."]', NULL),
  (3391612, 'NT', 'Yohane', 13, 22, 'Ba faoma lafaigi nawöra ira nifahaö, lö la''ila, ha niha niŵa''önia.[16]', '["Faigi 19:26"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 23, 'Ba so zamösa nifahaö, sidadao ba ngai Yesu, ni''omasi''ö Yesu.', '["Faigi 19:26"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 24, 'Da''ö nikhawi Zimoni Fetero tanga, imane khönia: Ombakha''ö khögu, ha niha niŵa''önia.', '["Faigi 19:26"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 25, 'Ba ihole''ö ia ba dötö''a Yesu, imane khönia: He Tua, ha niha?', '[]', NULL),
  (3391612, 'NT', 'Yohane', 13, 26, 'Itema linia Yesu: Da''ö ia, ni''ungugögu ö, sambawa, nibe''egu khönia.', '[]', NULL),
  (3391612, 'NT', 'Yohane', 13, 27, 'Ba me aefa itema gö andrö, ba möi ba dödönia Zatana.', '[]', NULL),
  (3391612, 'NT', 'Yohane', 13, 28, 'Ba lö ba nawönia ba wemanga andrö saboto ba dödö da''ö, hana wa iŵa''ö khönia da''ö.', '["Faigi 12:6"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 29, 'So zanguma''ö tödöra, me so khönia naha gefe, iŵa''ö khönia Yesu: Öli hadia zoguna khöda ba gowasa, ba ma ena''ö na ibe''e ba zi numana ma''ifu.[18]', '["Faigi 12:6"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 30, 'Ba me no itema gö andrö, ba i''anema''ö möi ia baero. Ba no bongi.[19]', '["Faigi 18:3"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 31, 'Ba me no möi ia baero, ba imane Yesu: Awena tefolakhömi Nono Niha, ba no tefolakhömi Lowalangi ba khönia.[20]', '["Faigi 12:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 32, 'Na no tefolakhömi Lowalangi ba khönia, ba ifolakhömi göi ia Lowalangi, ba khönia, ba i''anema''ö ifolakhömi.', '["Faigi 12:23"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 33, 'He iraono, ha ma''ifu tö na sodo khömi. Mi''alui ndra''o dania, ba hulö si mane niŵa''ögu no ba niha Yehuda: Tebai möi ami ba zi möi ndra''o, si manö göi niŵa''ögu khömi iada''e.[21]', '["Faigi 7:34","Yoh 15:12–13; Efes 5:2; YohI 3:11,14,23","YohI 2:5"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 34, 'Oroisa si bohou ube''e khömi, ena''ö mi''omasi''ö nawömi; si mane fa''omasigu ami, ena''ö ya''ami göi, faoma mi''omasi''ö nawömi.[22]', '["Faigi 7:34","Yoh 15:12–13; Efes 5:2; YohI 3:11,14,23","YohI 2:5"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 35, 'Ba da''ö aboto ba dödö niha fefu, wa no nifahaögu ami, na so khömi wa''omasimi nawömi.[23]', '["Faigi 7:34","Yoh 15:12–13; Efes 5:2; YohI 3:11,14,23","YohI 2:5"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 36, 'Imane khönia Simoni Fetero: He Tua, heza möi''ö? Itema linia Yesu, imane: Tebai ö''o''ö ndra''o iada''e ba zi möi ndra''o, ba ö''o''ö sa ndra''o na furi.[24]', '["Faigi 21:18–19"]', NULL),
  (3391612, 'NT', 'Yohane', 13, 37, 'Imane khönia Fetero: He Tua, hana wa lö u''ila u''o''ö ndra''ugö iada''e? Ubelegö nosogu fönau.[25]', '["Luk 22:33 b.t."]', NULL),
  (3391613, 'NT', 'Yohane', 14, 1, 'Böi abu dödömi. Mi''amati ba Lowalangi ba mi''amati khögu.[1]', '["Mar 11:22; Faigi 12:44"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 2, 'Oya nahia ba nomo Namagu, ba na tenga si manö mena''ö, ba no uŵa''ö khömi. Möido sa muhaogö naha khömi.[2]', '["KorII 5:1","Faigi 17:24"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 3, 'Ba na no möido, na no uhaogö naha khömi, ba mangawulido, ba uhalö ami khögu, ena''ö so ami göi ba zi so ya''o.[3]', '["KorII 5:1","Faigi 17:24"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 4, 'Ba no mi''ila lala ba zi möi ndra''o.', '[]', NULL),
  (3391613, 'NT', 'Yohane', 14, 5, 'Imane khönia Toma: He Tua, lö ma''ila, heza möi ndra''ugö, ba he moroi ma''ila lala?', '[]', NULL),
  (3391613, 'NT', 'Yohane', 14, 6, 'Imane khönia Yesu: Ya''odo lala, ya''odo wa''aduhu, ya''odo wa''auri. Lö sondrugi Ama, na lö itörö ndra''o.[4]', '["Heb 10:19","Faigi 8:19"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 7, 'Na no aboto ba dödömi ndra''o, ba aboto göi ba dödömi Namagu dania. Ba i''otarai da''e, ba aboto ba dödömi ia, ba no mi''ila ia.[5]', '["Heb 10:19","Faigi 8:19"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 8, 'Imane khönia Filifo: He Tua, oroma''ö khöma Nama, ba ahono dödöma.', '[]', NULL),
  (3391613, 'NT', 'Yohane', 14, 9, 'Imane khönia Yesu: Si manö wa''ara awömi ndra''o, Filifo, ba lö aboto ba dödömi ndra''o? Si no mangila ya''o, ba no i''ila Nama; ba hana wa öŵa''ö: Oroma''ö khöma Nama?[6]', '["Faigi 12:45; Kol 1:15; Heb 1:3; KorII 4:4-6"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 10, 'Hadia lö faduhu dödöu, wa ba dödö Nama so ndra''o, awö wa ba dödögu so Nama? Taroma li andrö, niŵa''ögu khömi, ba tenga moroi ba khögu uŵa''ö ia. Ba ihalö halöŵönia Ama, si lö tebulö ba dödögu.', '["Faigi 12:45; Kol 1:15; Heb 1:3; KorII 4:4-6"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 11, 'Mifati khögu, wa ba dödö Nama so ndra''o, awö wa ba dödögu so Nama; ba na lö''ö, ba mi''amati ba halöŵö andrö.[7]', '["Faigi 10:38","Mat 17:20; HalZin 2:41; 5:15","Faigi 15:7; 16:23","YohI 5:14-15"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 12, 'Si ndruhu-ndruhu niŵa''ögu khömi, ihalö dania halöŵö andrö, nihalögu, samati khögu, ba sebua moroi andrö ihalö, me khö Nama möi ndra''o,[8]', '["Faigi 10:38","Mat 17:20; HalZin 2:41; 5:15","Faigi 15:7; 16:23","YohI 5:14-15"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 13, 'ba hadia ni''andrömi, ba döigu, ba u''o''ö, ena''ö tefolakhömi Nama ba khö Nono.[9]', '["Faigi 10:38","Mat 17:20; HalZin 2:41; 5:15","Faigi 15:7; 16:23","YohI 5:14-15"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 14, 'Na so ni''andrömi khögu ba döigu, ba u''o''ö.[10]', '["Faigi 10:38","Mat 17:20; HalZin 2:41; 5:15","Faigi 15:7; 16:23","YohI 5:14-15"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 15, 'Na mi''omasi''ö ndra''o, ba mi''o''ö goroisagu.[11]', '["Faigi 15:10; YohI 5:3"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 16, 'Ba ya''o, ba u''andrö dania khö Nama, ba ibe''e khömi zanolo tanö bö''ö, ena''ö lö aefa ia khömi, irugi zi lö aetu;[12]', '["Faigi 14:26","YohI 5:6"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 17, 'Eheha si duhu andrö, si tebai latema niha guli danö, me lö la''ila, me lö aboto ba dödöra. Ba dödömi no aboto ia, me lö aefa ia khömi, ba ba dödömi so ia dania.[13]', '["Faigi 14:26","YohI 5:6"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 18, 'Lö uröi ami, hulö zi lö ama, si lö ina, möido khömi.[14]', '["Mat 28:20"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 19, 'Ma''ifu tö na, ba lö''ö sa''ae la''ilado niha guli danö, ba ya''ami zangila ya''o, auri sa ndra''o, ba sauri göi ami dania.[15]', '["Faigi 16:16; Hos 6:2","Faigi 17:23 b.t."]', NULL),
  (3391613, 'NT', 'Yohane', 14, 20, 'Na luo da''ö, ba aboto ba dödömi, wa ba dödö Nama so ndra''o, awö wa ba dödögu so ami ba ba dödömi so ndra''o.[16]', '["Faigi 16:16; Hos 6:2","Faigi 17:23 b.t."]', NULL),
  (3391613, 'NT', 'Yohane', 14, 21, 'Si so oroisa andrö khögu, solo''ö ya''ia, da''ö zomasi ya''o. Ba ni''omasi''ö Namagu zomasi ya''o; ba ya''o göi u''omasi''ö ia ba u''oroma''ö ndra''o khönia.[17]', '["Ayati 15"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 22, 'Imane khönia Yuda, tenga banua Kariota andrö: He Tua, hadia ia wa ö''oroma''ö ndra''ugö khöma, ba lö ö''oroma''ö ndra''ugö ba niha guli danö?', '[]', NULL),
  (3391613, 'NT', 'Yohane', 14, 23, 'Itema linia Yesu, imane khönia: Na so zomasi ya''o, ba i''o''ö ligu, ba i''omasi''ö Amagu, ba möiga khönia, ba ba khönia ma''iagö.[18]', '["Efes 3:17 b.t.","Faigi 7:16 b.t."]', NULL),
  (3391613, 'NT', 'Yohane', 14, 24, 'Si lö mangomasi''ö ya''o, ba lö i''o''ö ligu. Ba taroma li andrö, nirongomi, ba tenga khögu, no khö zamatenge ya''o, khö Nama.[19]', '["Efes 3:17 b.t.","Faigi 7:16 b.t."]', NULL),
  (3391613, 'NT', 'Yohane', 14, 25, 'Da''ö niŵa''ögu khömi, fatua lö ahetado khömi.', '["Faigi 15:26; 16:14; Fil 1:9-11"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 26, 'Ba sanolo andrö, Eheha ni''amoni''ö, nifatenge Namagu dania ba döigu, da''ö zamahaö ya''ami, ba da''ö fefu, ba ahori ifasugi ba dödömi niŵa''ögu khömi.[20]', '["Faigi 15:26; 16:14; Fil 1:9-11"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 27, 'Uröi khömi wa''ohahau dödö, fa''ohahau dödö khögu ube''e khömi. Bö''ö nibe''e niha guli danö, bö''ö nibe''egu. Böi abu dödömi ba böi ata''u ami.[21]', '["Faigi 16:33; Rom 5:1; Fil 4:7"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 28, 'No mirongo, me uŵa''ö khömi: Mofanö ndra''o ba ufulido khömi. Na mi''omasi''ö ndra''o, ba omuso dödömi ena''ö, me khö Nama möido, me no sebua moroi khögu Nama.[22]', '["Faigi 10:29; Fil 2:6 b.t.","Faigi 13:19"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 29, 'Ba noa sa uŵa''ö khömi, fatua lö alua, ena''ö faduhu dödömi, na alua dania.[23]', '["Faigi 10:29; Fil 2:6 b.t.","Faigi 13:19"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 30, 'Lö''ö sa''ae oya huhuogu khömi, so sa''ae zalaŵa guli danö andrö, ba lö isöndra hadia ia khögu;[24]', '["Faigi 12:31; Luk 22:53","Faigi 10:18"]', NULL),
  (3391613, 'NT', 'Yohane', 14, 31, 'ba ena''ö aboto ba dödö niha guli danö, omasido Nama ba u''o''ö hadia niŵa''ö Nama khögu, ba mifaoso, taheta ita ba da''e![25]', '["Faigi 12:31; Luk 22:53","Faigi 10:18"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 1, 'Ya''odo döla nagu si ndruhu andrö, ba si so kabu nagu Namagu.', '["Mat 15:13; Fil 1:9-11"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 2, 'Fefu ndraha ba khögu, si lö mowua, ba iheta, ba fefu zowua, ba ihaogö, ena''ö tedou wa''oya mbuania.[1]', '["Mat 15:13; Fil 1:9-11"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 3, 'Si no muhaogö ami, börö daroma li andrö, niŵa''ögu khömi.[2]', '["Faigi 13:10; Efes 5:26"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391614, 'NT', 'Yohane', 15, 4, 'Mi''iagö ndra''o, ba u''iagö ami. Hulö ndraha, si tebai mowua, ha ya''ia, na tenga sa''ae ba döla nagu so ia, si manö göi ami, na tenga sa''ae ba khögu so ami.', '[]', NULL),
  (3391614, 'NT', 'Yohane', 15, 5, 'Ya''odo döla nagu andrö, daha ami. Sangiagö ya''o, na u''iagö ia göi, daö zoya bua, me tebai milau hadia ia, na lö ya''o.[3]', '["KorII 3:5"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 6, 'Nitibo''ö na so zi lö mangiagö ya''o, hulö ndraha, ba mate, ba la''ozaragö ba latibo''ö ba galitö ba akhozi.[4]', '["Mat 3:10","Faigi 14:13; Mar 11:24"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 7, 'Na mi''iagö ndra''o, ba na lö aefa ba dödömi daroma ligu, ba mi''andrö hadia zomasi ami, ba tebe''e khömi.[5]', '["Mat 3:10","Faigi 14:13; Mar 11:24"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 8, 'Ba da''ö tefosumange Namagu, ena''ö oya mbuami, ba ena''ö tobali nifahaögu ami.', '["Faigi 14:15"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 9, 'Si mane fa''omasi Nama ndra''o, si manö göi wa''omasigu ami. Mi''iagö wa''omasigu andrö.', '["Faigi 14:15"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 10, 'Na mi''o''ö goroisagu, ba da''ö mi''iagö wa''omasigu, si mane folo''ögu oroisa Namagu, be u''iagö wa''omasinia.[6]', '["Faigi 14:15"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 11, 'Da''ö niŵa''ögu khömi, ena''ö so ba dödömi wa''omuso dödö andrö khögu, ba ena''ö a''oi so wa''omuso dödömi.[7]', '["Faigi 16:24"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 12, 'Da''ö goroisagu, ena''ö faoma mi''omasi''ö nawömi, si mane fa''omasigu ami.[8]', '["Faigi 13:34","Rom 5:6 b.t."]', NULL),
  (3391614, 'NT', 'Yohane', 15, 13, 'Fondrege wa''ebua wangomasi''ö awö, na ibelegö nosonia niha föna zi fahuwu khönia.[9]', '["Faigi 13:34","Rom 5:6 b.t."]', NULL),
  (3391614, 'NT', 'Yohane', 15, 14, 'Si no fahuwu khögu ami, na mi''o''ö hadia niŵa''ögu khömi.[10]', '["Luk 8:21","Yak 2:23"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 15, 'Lö''ö sa''ae ube''e töimi genoni, enoni, ba lö i''ila, hadia nifazökhi zokhö ya''ia; ba no ube''e töimi zi fahuwu, noa sa u''ombakha''ö khömi fefu nirongogu khö Namagu.[11]', '["Luk 8:21","Yak 2:23"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 16, 'Tenga ya''ami zanuyu ya''o, ya''o sa zanutuyu ya''ami, ba no ufataro ami, ena''ö möi ami mowua, ba ena''ö lö tebulö mbuami, ena''ö ibe''e khömi Ama hadia ni''andrömi khönia ba döigu.[12]', '["Faigi 16:23"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 17, 'Da''ö goroisagu khömi, ena''ö faoma mi''omasi''ö nawömi.', '[]', NULL),
  (3391614, 'NT', 'Yohane', 15, 18, 'Na fatiu dödö niha guli danö khömi, ba ya''aboto ba dödömi, no oföna fatiu dödöra khögu.[13]', '["YohI 3:13","Faigi 17:14"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 19, 'Na awö niha guli danö ami ena''ö, ba no omasi ena''ö niha guli danö dana khöra andrö; ba me no tenga awö niha guli danö ami, me no ututuyu ami ba niha guli danö, andrö wa fatiu dödö niha guli danö khömi.[14]', '["YohI 3:13","Faigi 17:14"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 20, 'Mitörö-törö tödömi li andrö, niŵa''ögu khömi: Tenga sebua moroi khö zokhö ya''ia zawuyu. Na no lagohi ndra''o, ba lagohi göi ami; na no la''o''ö ligu, ba la''o''ö göi limi.[15]', '["Faigi 13:16; Mat 24:9"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 21, 'Ba börö döigu, wa lalau khömi da''ö fefu, me lö saboto ba dödöra zamatenge ya''o.[16]', '["Faigi 16:3","Faigi 9:41","Faigi 5:23"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 22, 'Na lö si möido mena''ö, muhede khöra, ba lö horöra. Ba iada''e, ba lö tahi khöra ba horöra andrö.[17]', '["Faigi 16:3","Faigi 9:41","Faigi 5:23"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 23, 'Si fatiu tödö khögu, ba fatiu göi khö Namagu.[18]', '["Faigi 16:3","Faigi 9:41","Faigi 5:23"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 24, 'Na lö nihalögu mena''ö ba khöra halöŵö andrö, si lö irai ihalö niha bö''ö, ba lö horöra ena''ö, ba iada''e, ba no la''ila, ba noa zui fatiu dödöra khögu ba khö Namagu.[19]', '["Faigi 10:37-38","Sin 35:19; 69:5"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 25, 'Ba ena''ö itörö li andrö, nisura ba zura goroisa khöra: "No fatiu dödöra khögu, ba lö börö-börö".[20]', '["Faigi 10:37-38","Sin 35:19; 69:5"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 26, 'Na so zanolo andrö, nifatengegu khömi dania, si oroi khö Nama, Eheha si duhu andrö, si otarai Nama, da''ö zamaduhu''ö ya''o.[21]', '["Faigi 14:16,26","HalZin 1:8-21 b.t.; 5:32"]', NULL),
  (3391614, 'NT', 'Yohane', 15, 27, 'Ba ya''ami göi, ba samaduhu''ö, me no i''otarai mböröta fao-fao ami khögu.[22]', '["Faigi 14:16,26","HalZin 1:8-21 b.t.; 5:32"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 1, 'Da''ö niŵa''ögu khömi, fa böi fatuwu khömi.[1]', '["Mat 13:21","Mat 24:9; HalZin 8:1; 9:1 b.t.; 23:12","Faigi 15:21 KorI 2:8"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 2, 'Latibo''ö banua ami dania. Ba irugi baŵa dania, ba dozi samunu ya''ami, ba lawai famosumange Lowalangi.[2]', '["Mat 13:21","Mat 24:9; HalZin 8:1; 9:1 b.t.; 23:12","Faigi 15:21 KorI 2:8"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 3, 'Ba me lö aboto ba dödöra Nama ba ya''o, andrö lalau khömi da''ö.[3]', '["Mat 13:21","Mat 24:9; HalZin 8:1; 9:1 b.t.; 23:12","Faigi 15:21 KorI 2:8"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 4, 'Ba andrö uŵa''ö khömi da''ö, ena''ö, na no irugi baŵa da''ö, ba mitörö-törö tödömi, wa no uŵa''ö khömi. Ba tenga si otarai mböröta uŵa''ö khömi da''ö, me no fao-fao ndra''o khömi.[4]', '["Faigi 13:19"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 5, 'Ba iada''e, ba mofanö ndra''o khö zamatenge ya''o, ba samösa lö ba khömi sanofu khögu: Heza möi''ö?[5]', '["Faigi 7:33; 13:36"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 6, 'Ba me no uŵa''ö khömi da''ö ba no a''oi so wa''abu dödömi.', '["Faigi 7:33; 13:36"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 7, 'Ba si ndruhu niŵa''ögu khömi, moguna khömi, na mofanö ndra''o. Na lö mofanö ndra''o, ba lö möi khömi zanolo andrö; ba na möido, ba ufatenge ia khömi.', '["Faigi 7:33; 13:36"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 8, 'Ba na so da''ö, ba i''otu''ö niha guli danö, ba horö ba ba wa''atulö dödö ba ba huku.', '["Faigi 3:18","Rom 4:25; 8:34","Faigi 12:31"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 9, 'Ba horö, me lö mamati ira khögu.[6]', '["Faigi 3:18","Rom 4:25; 8:34","Faigi 12:31"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 10, 'Ba wa''atulö dödö, me sofanö khö Nama ndra''o, ba me lö mi''ilado sa''ae.[7]', '["Faigi 3:18","Rom 4:25; 8:34","Faigi 12:31"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 11, 'Ba huku, me no tehuku zalaŵa guli danö andre.[8]', '["Faigi 3:18","Rom 4:25; 8:34","Faigi 12:31"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 12, 'Wa''oya na niŵa''ögu khömi, ba tebai mitaha iada''e.', '["Faigi 14:17; YohI 2:27"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 13, 'Ba na so da''ö, Eheha si duhu andrö, ba i''oroma''ö khömi lala ba zi duhu fefu. Tenga sa soroi khönia wehedenia, fefu hadia ia nirongonia, iŵa''ö, ba hadia zi so dania, ba i''ombakha''ö khömi.[9]', '["Faigi 14:17; YohI 2:27"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 14, 'Ya''ia zamolakhömi ya''o, me moroi ba zi so khögu itema ba i''ombakha''ö khömi.[10]', '["Yoh 14:26","Faigi 17:10"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 15, 'Fefu hadia ia zi so khö Nama, ba khögu da''ö. Andrö uŵa''ö, itema ba zi so khögu, ba i''ombakha''ö khömi.[11]', '["Yoh 14:26","Faigi 17:10"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 16, 'Ma''ifu tö na, ba lö mi''ilado sa''ae, ba ma''ifu tö zui, ba mi''ilado.[12]', '["Faigi 14:19-28"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 17, 'Ba faoma lamane khö naŵora nifahaönia ösa: Hadia da''ö, niŵa''önia khöda: Ma''ifu tö, ba lö mi''ilado, ba ma''ifu tö zui, ba mi''ilado, ba: mofanö ndra''o khö Nama?', '["Faigi 7:33-36"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 18, 'Ba lamane: Hadia da''ö, niŵa''önia: Ma''ifu tö? Lö ma''ila hadia niŵa''önia.[13]', '["Faigi 7:33-36"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 19, 'Aboto ba dödö Yesu, lasofu khönia dania, ba imane khöra: Da''ö nizofu-zofumi khö nawömi, me no uŵa''ö: Ma''ifu tö, ba lö mi''ilado ba ma''ifu tö zui, ba mi''ilado?', '[]', NULL),
  (3391615, 'NT', 'Yohane', 16, 20, 'Si ndruhu-ndruhu niŵa''ögu khömi, mege-ege dania ami ba mange''esi, ba omuso dödö niha guli danö; sabu tödö ami, ba tobali sa fa''omuso dödö wa''abu dödömi andrö.', '[]', NULL),
  (3391615, 'NT', 'Yohane', 16, 21, 'Abu dödö ndra alawe, na madono ia, me no irugi baŵania, ba na no i''adonogö nono andrö, ba lö''ö sa''ae itörö tödönia wa''afökhö andrö, ba wa''omuso dödö, me no tumbu niha andrö, ba guli danö.[14]', '["Yes 26:17 b.t.","Luk 24:41-52; Yes 16:10-14; 35:10"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 22, 'Ba ya''ami göi, abu sa dödömi iada''e, ba ufuli ufaigi ami, ba omuso dödömi, ba lö sangeheta khömi fa''omuso dödömi andrö.[15]', '["Yes 26:17 b.t.","Luk 24:41-52; Yes 16:10-14; 35:10"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 23, 'Ba na luo da''ö, ba ma''ifu lö misofu khögu. Si ndruhu-ndruhu niŵa''ögu khömi, na so ni''andrömi khö Nama, ba ibe''e khömi, ba döigu.[16]', '["Faigi 15:7-16","Faigi 15:11"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 24, 'Irege da''e, ba lö ni''andrömi ba döigu. Mi''andrö, ba mitema, ena''ö a''oi so wa''omuso dödömi.[17]', '["Faigi 15:7-16","Faigi 15:11"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 25, 'Amaedola khögu, wanguma''ö khömi da''ö. Irugi baŵa dania, ba lö''ö sa''ae uŵa''ö gamaedola khömi, ba lö aiŵödo wangombakha khömi hadia ia khö Nama.', '["Faigi 14:16; Heb 7:25","Faigi 14:21; 17:8,25","Faigi 13:3"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 26, 'Na luo da''ö ba mangandrö ami ba döigu, ba lö uŵa''ö khömi, mangandrö ndra''o khö Nama salahimi.[18]', '["Faigi 14:16; Heb 7:25","Faigi 14:21; 17:8,25","Faigi 13:3"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 27, 'Ya''ia, Ama, zangomasi''ö ya''ami, me no mi''omasi''ö ndra''odo, ba me no faduhu dödömi, khö Lowalangi u''otarai.[19]', '["Faigi 14:16; Heb 7:25","Faigi 14:21; 17:8,25","Faigi 13:3"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 28, 'Khö Nama u''otarai, ba no möido ba guli danö; ba uröi zui guli danö ba möido khö Nama.[20]', '["Faigi 14:16; Heb 7:25","Faigi 14:21; 17:8,25","Faigi 13:3"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 29, 'Lamane ira nifahaö: Hiza, iada''e lö aiŵö ndra''ugö muhede, ba lö öŵa''ö gamaedola.', '["Faigi 21:17"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 30, 'Aboto sa''ae ba dödöma, wa no ö''ila fefu hadia ia, ba lö moguna khöu, isofu khöu niha. Ba da''ö faduhu dödöma, wa khö Lowalangi ö''otarai.[21]', '["Faigi 21:17"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 31, 'Itema lira Yesu, imane: Iada''e faduhu dödömi?', '["Mat 26:56; Faigi 8:29","Faigi 14:27; YohI 5:4"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 32, 'Hiza, irugi baŵa dania ba no irugi iya''e, ba oi zara tefazawili ami, isaŵa dana khönia zamösana, ba miröi ndra''o, ba ya''o, ba tenga ha ya''odo, me fao-fao khögu Nama.[22]', '["Mat 26:56; Faigi 8:29","Faigi 14:27; YohI 5:4"]', NULL),
  (3391615, 'NT', 'Yohane', 16, 33, 'Da''ö niŵa''ögu khömi, ena''ö so khömi wa''ohahau dödö ba khögu. Ba guli danö so wa''afökhö khömi, ba böi mibusi dödömi, no ulawa niha gulidanö.[23]', '["Mat 26:56; Faigi 8:29","Faigi 14:27; YohI 5:4"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 1, 'Da''ö niŵa''ö Yesu, ba ifaöga hörönia miyaŵa ba zorugo, ba imane: He Ama, no irugi inötö; folakhömi Nonou, ena''ö ifolakhömi ndra''ugö Ono.[1]', '["Faigi 12:23-28","Mat 28:18; Faigi 3:35; 6:37"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 2, 'Si mane fame''eu barö mbawania fefu niha, ena''ö idozigö fa''auri si lö aetu nibe''eu khönia andrö.[2]', '["Faigi 12:23-28","Mat 28:18; Faigi 3:35; 6:37"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 3, 'Da''ö wa''auri si lö aetu, ena''ö aboto ba dödöra ndra''ugö, Lowalangi si ndruhu andrö, si ha sambua, ba ena''ö, aboto ba dödöra zinengeu andrö, Yesu Keriso.[3]', '["KorI 8:6","Faigi 4:34","Tanö''a: I''oguna''ö wehede tanö''a Sundermann ba wangali fehede dunia ma zui planet bumi ba li Indonesia.","Faigi 1:1 b.t.; Fil 2:6"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 4, 'No ufolakhömi ndra''ugö ba guli danö, no u''asiwaligö halöŵö andrö, nibe''eu khögu, ba wangai ya''ia.[4]', '["KorI 8:6","Faigi 4:34","Tanö''a: I''oguna''ö wehede tanö''a Sundermann ba wangali fehede dunia ma zui planet bumi ba li Indonesia.","Faigi 1:1 b.t.; Fil 2:6"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 5, 'Ba iada''e, ba folakhömi ndra''o, awöu, ya''ugö, Ama, lakhömi si no so khögu ba khöu, föna wa''aso danö''a[5] andrö.[6]', '["KorI 8:6","Faigi 4:34","Tanö''a: I''oguna''ö wehede tanö''a Sundermann ba wangali fehede dunia ma zui planet bumi ba li Indonesia.","Faigi 1:1 b.t.; Fil 2:6"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 6, 'No ufa''ele''ö döimö ba niha andrö, nibe''eu khögu, moroi ba niha guli danö. Khöu ira, ba no öbe''e khögu, ba no la''o''ö liu.', '["Faigi 16:27,30"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 7, 'Aboto sa''ae ba dödöra, wa moroi khöu fefu hadia ia nibe''eu khögu.', '["Faigi 16:27,30"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 8, 'Me no ufa''ema khöra daroma li andrö, nibe''eu khögu, ba no latema, ba si ndruhu no aboto ba dödöra, wa moroi khöu u''otarai, ba no faduhu dödöra, wa no ya''ugö zamatenge ya''o.[7]', '["Faigi 16:27,30"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 9, 'Mangandrö ndra''o, salahira, tenga salahi niha guli danö mangandrödo, khöra sa, nibe''eu khögu, me no khöu ira.[8]', '["Heb 7:25","Faigi 16:15"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 10, 'Ba khöu fefu zi so khögu, ba khögu fefu zi so khöu, ba no tefolakhömi ndra''o ba khöra[9]', '["Heb 7:25","Faigi 16:15"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 11, 'Ba lö''ö sa''ae sodo ba guli danö, ba so sa ira ba guli danö, khöu möi ndra''odo. He Ama ni''amoni''ö! Taha ira, ba döimö, nibe''eu khögu andrö, ena''ö ha sambua dödöra, si mane tödöda andrö.[10]', '["Faigi 10:30","Faigi 13:18; 6:70; Sin 109:8"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 12, 'Me sodo khöra, ba ya''o zanaha ya''ira, ba döimö, nibe''eu khögu andrö ba no urorogö ira, ba lö si tekiko ba khöra, baero nono wa''atekiko andrö, ena''ö itörö zi so ba zura andrö[11]', '["Faigi 10:30","Faigi 13:18; 6:70; Sin 109:8"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 13, 'Ba möido khöu iada''e, ba uŵa''ö da''ö ba guli danö, ena''ö a''oi so khöra wa''omuso dödö andrö khögu, ba dödöra[12]', '["Faigi 15:11","Faigi 15:18-19","YohI 5:18; TesII 3:3"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 14, 'No ufa''ema khöra daroma limö, ba no fatiu dödö niha guli danö khöra, me tenga moroi ba niha guli danö ira, si mane ya''o, si tenga moroi ba niha guli danö[13]', '["Faigi 15:11","Faigi 15:18-19","YohI 5:18; TesII 3:3"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 15, 'Lö u''andrö, öheta ira ba guli danö, ba ena''ö örorogö ira, ba ö''efa''ö ba Gafökha.[14]', '["Faigi 15:11","Faigi 15:18-19","YohI 5:18; TesII 3:3"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 16, 'Tenga moroi ba niha guli danö ira, si mane ya''o, si tenga moroi ba niha guli danö.', '["Faigi 15:11","Faigi 15:18-19","YohI 5:18; TesII 3:3"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 17, 'Amoni''ö ira ba zi duhu; taroma limö zi duhu.[15]', '["SamII 7:28; Sin 119:160","Faigi 20:21","Heb 7:27; 10:9,10; Tit 2:14"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 18, 'Si mane famatengeu ya''o ba guli danö, si manö göi wamatengegu ya''ira ba guli danö.[16]', '["SamII 7:28; Sin 119:160","Faigi 20:21","Heb 7:27; 10:9,10; Tit 2:14"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 19, 'Ba u''amoni''ö ndra''o salahira, ena''ö ni''amoni''ö ira göi ba zi duhu.[17]', '["SamII 7:28; Sin 119:160","Faigi 20:21","Heb 7:27; 10:9,10; Tit 2:14"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 20, 'Ba tenga ha khöra ni''andrögu, ba zamati khögu ba lira no göi,[18]', '["Rom 10:17","HalZin 4:32"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 21, 'ena''ö ha sambua dödöra, dozi ira, si mane ya''ugö, Ama, ba khögu, ba si mane ya''o ba khöu, ena''ö ya''ira göi, ba khöda so ira; ena''ö faduhu dödö niha guli danö, ya''ugö zamatenge ya''o.[19]', '["Rom 10:17","HalZin 4:32"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 22, 'Ba no ube''e khöra lakhömi andrö, nibe''eu khögu, ena''ö ha sambua dödöra, si mane tödöda andrö, si ha sambua.[20]', '["Rom 8:15 b.t.; 29 b.t."]', NULL),
  (3391616, 'NT', 'Yohane', 17, 23, 'Ya''o ba khöra ba ya''ugö ba khögu, ena''ö mo''ahonoa wa ha sambua dödöra, ena''ö aboto ba dödö niha guli danö, ya''ugö zamatenge ya''o, ba no ö''omasi''ö ira, si mane fa''omasiu ndra''o.[21]', '["Efes 4:3,13-16; KorI 6:17"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 24, 'He Ama, omasido na awögu ba zi so ya''o nibe''eu khögu andrö, ena''ö anehe ira lakhömigu, nibe''eu khögu, me no ö''omasi''ö ndra''o, föna wamazökhi danö''a.[22]', '["Faigi 12:26; YohI 3:2; Mat 25:34","Faigi 8:19 Mat 11:25","Sin 22:23; Faigi 15:9"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 25, 'He Ama satulö! lö''ö sa aboto ba dödö niha guli danö ndra''ugö, ba ba dödögu aboto ndra''ugö, ba na aboto ba dödö da''e, wa no ya''ugö zamatenge ya''o.[23]', '["Faigi 12:26; YohI 3:2; Mat 25:34","Faigi 8:19 Mat 11:25","Sin 22:23; Faigi 15:9"]', NULL),
  (3391616, 'NT', 'Yohane', 17, 26, 'Ba no u''ombakha''ö khöra doimö, ba u''ombakha''ö na dania, ena''ö so ba dödöra wa''omasi andrö, fa''omasiu ndra''o, ba ena''ö so ba dödöra ndra''odo.[24]', '["Faigi 12:26; YohI 3:2; Mat 25:34","Faigi 8:19 Mat 11:25","Sin 22:23; Faigi 15:9"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 1, 'Aefa iŵa''ö da''ö Yesu, ba möi ia baero, awö ndra nifahaönia, i''ötö mbombo andrö, Kendrona, ba so kabu ba da''ö, ba da''ö bakha möi Yesu, awö nifahaönia.[1]', '["Mat 26:36 b.t.; SamII 15:23"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 2, 'Ba no i''ila göi naha andrö Yuda andrö, si manga mbölinia, me asese möi ba da''ö Yesu, awö nifahaönia.[2]', '["Mat 26:47 b.t."]', NULL),
  (3391618, 'NT', 'Yohane', 18, 3, 'Ba me no ihalö Yuda zaradadu ba enoni gere sebua ba enoni warizaio, ba möi ia ba da''ö, la''ohe wandru ba sulu ba fangöna.', '["Mat 26:47 b.t."]', NULL),
  (3391618, 'NT', 'Yohane', 18, 4, 'Ba no i''ila Yesu fefu zi göna ia dania, ba möi ia baero, imane khöra: Ha niha ni''aluimi?[3]', '["Faigi 13:1"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 5, 'Latema linia, lamane: Yesu, banua Nazareta andrö. Imane khöra Yesu: Ya''odo da''ö. Ba so göi ba da''ö Yuda, si manga mbölinia, awöra.', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 6, 'Ba me iŵa''ö khöra: Ya''odo da''o! ba lawuwu furi, alau tou ira ba danö.', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 7, 'Ba ifuli isofu khöra: Ha niha ni''aluimi?', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 8, 'Itema lira Yesu, imane: No uŵa''ö khömi, ya''odo da''ö. Ba na mi''alui ndra''o, ba mifofanö da''e.[4]', '["Faigi 10:18","Faigi 17:12"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 9, 'Ena''ö itörö niŵa''önia no: Samösa lö si taya khögu nibe''eu khögu andrö.[5]', '["Faigi 10:18","Faigi 17:12"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 10, 'Ba me so wöda khö Zimoni Fetero, ba isöbi, ba igukhui zawuyu gere sebua, i''eŵa dalingania, kambölö. Malikho döi zawuyu andrö.[6]', '["Mat 26:51 b.t."]', NULL),
  (3391618, 'NT', 'Yohane', 18, 11, 'Ba imane Yesu khö Wetero: Saembugö wöda. Hadia, lö ubadu nösi mako andrö, nibe''e Namagu khögu?[7]', '["Mat 26:39"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 12, 'Ba lara''u Yesu saradadu ba kumandra ba enoni niha Yehuda andrö ba laböbö ia.[8]', '["Mat 26:57 b.t."]', NULL),
  (3391618, 'NT', 'Yohane', 18, 13, 'Ba la''ofönai''ö wolohe ya''ia khö Hanasi, matua Kayafa da''ö, ba ere sebua Kayafa zi döfi andrö.[9]', '["Luk 3:2","Faigi 11:50"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 14, 'Ba Kayafa zanguma''ö ba niha Yehuda no, sökhi na mate zamösa, salahi mbanuara andrö.[10]', '["Luk 3:2","Faigi 11:50"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 15, 'Ba i''o''ö Yesu Simoni Fetero ba samösa nifahaö bö''ö. Ba no fa''ila li nifahaö andrö khö gere sebua, ba fao ia khö Yesu, we''amöi ba golayama gere sebua.[11]', '["Faigi 20:2"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 16, 'Ba baero so Wetero, ba zinga mbawandruhö. Ba möi baero nifahaö si samösa andrö, si no fa''ila li khö gere sebua, fahuhuo ia ba zanaro ba mbawandruhö, ono alawe, ba i''ohe bakha Wetero.', '["Faigi 20:2"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 17, 'Ba imane khö Wetero sawuyu ono alawe andrö, sanaro ba mbawandruhö: Tenga ya''ugö göi nifahaö niha andrö?', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391618, 'NT', 'Yohane', 18, 18, 'Ba so ba da''ö zawuyu ba enoni, no la''ebua''ö galitö, o''afu ira, moleu. Ba so göi Wetero ba da''ö, ba ngaira, moleu göi ia.', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 19, 'Ba isofu khö Yesu ere sebua ba nifahaönia ba ba wamahaönia andrö.', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 20, 'Itema linia Yesu, imane: Lö urai aiŵö fahuhuo ba niha, lö aetu mamahaö ndra''o ba zekola ba ba gosali, ba zi möi niha Yehuda fefu, lö huhuogu ba zi tobini.[13]', '["Faigi 7:14 Mat 26:50"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 21, 'Hana wa ösofu khögu? Sofu, ba zi no mamondrongo hadia niŵa''ögu khöra. Hiza, ya''ira zangila, hadia niŵa''ögu.', '["Faigi 7:14 Mat 26:50"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 22, 'Ba me iŵa''ö da''ö, ba itema ifalisi mbawa Yesu enoni, samösa, si so ba da''ö, imane: Hadia, ömanö wanema li gere sebua?', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 23, 'Itema linia Yesu, imane: Na sala wehedegu, ba ombakha''ö, hadia zi lö sökhi, ba na lö sala, ba hana wa öbözido?[14]', '["Mat 5:39"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 24, 'Ba ifa''ohe''ö ia Hanasi khö gere sebua andrö, Kayafa, lö mutoto''ö mböbö.', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 25, 'Ba so Zimoni Fetero, moleu. Ba lamane khönia: Hadia, tenga ya''ugö göi nifahaönia?', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 26, 'Imane sawuyu gere sebua, samösa, talifusö ni''eŵa Wetero talinga: Tenga no u''ila ndra''ugö, awönia ba kabu?', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 27, 'Ba ifuli i''osilö''ögö Fetero.', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 28, 'Ba la''ohe ba gödo gumandru Yesu, la''otarai Kayafa; si hulö wongi. Ba lö möi ira ba gödo, fa lö latörö zalakha, ena''ö la''ila manga wasa andrö.[16]', '["Mat 27:1 b.t.; Mar 15:1 b.t.; Luk 23:1 b.t."]', NULL),
  (3391618, 'NT', 'Yohane', 18, 29, 'Ba möi baero khöra Wilato, imane: Hadia, wangadu khömi ba niha andre?', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 30, 'Latema linia, lamane khönia: Na tenga samazökhi si lö sökhi da''ö, ba lö mabe''e ba dangau ia mena''ö.', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 31, 'Ba imane khöra Filato: Mihalö ia, ya''ami, ba mi''o''ö goroisa andrö khömi, wanguhuku ya''ia.', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 32, 'Ena''ö itörö li Yesu, niŵa''önia ba wangombakha he wisa wa''amatenia dania.[18]', '["Faigi 19:6–7","Faigi 12:32–33; Mat 20:19"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 33, 'Ba ifuli ia yomo ba gödo Filato, humede ia khö Yesu, imane khönia: Hadia, razo niha Yehuda ndra''ugö?[19]', '["Mar 15:2; Luk 23:2"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 34, 'Itema linia Yesu, imane: Hadia, moroi khöu öwa''ö da''ö, ma tanö bö''ö zangombakha ya''ia khöu, ba khögu andre?', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 35, 'Itema linia Filato, imane: Hadia, niha Yehuda ndra''odo? Iwau ba ere sebua andrö zame''e ba dangagu ya''ugö; hadia horöu?', '[]', NULL),
  (3391618, 'NT', 'Yohane', 18, 36, 'Itema linia Yesu, imane: Tenga moroi ba guli danö andre mbanuagu andrö, na moroi ba guli danö andre mbanuagu, ba molaŵa mena''ö genonigu andrö, fa böi tebe''e ba danga niha Yehuda ndra''o; ba no tenga sa moroi ba da''ö mbanuagu.[20]', '["Faigi 6:15 Mat 26:5–53"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 37, 'Ba imane khönia Filato: Ba razo sa atö ndra''ugö? Itema linia Yesu: Ya''ia niŵa''öu, razo ndra''odo. Andrö tumbu ndra''o, ba andrö möido ba guli danö, ba wamaduhu''ö si duhu. Dozi si otarai zi duhu, ba lafondrondrongo ligu.[21]', '["Luk 23:3; Tim 6:13; Faigi 8:47"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 38, 'Imane khönia Filato: Hadia zi duhu? Ba me aefa iŵa''ö da''ö, ba möi ia baero zui, ba niha Yehuda, ba imane khöra: Lö usöndra khönia horö.[22]', '["Faigi 14:6; Luk 23:4","Mar 15:6–9"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 39, 'Ba no huku ba khömi, ube''e aefa khömi zamösa, ba gowasa fasa andrö. Hadia, omasi ami, ube''e aefa khömi razo niha Yehuda andrö?[23]', '["Faigi 14:6; Luk 23:4","Mar 15:6–9"]', NULL),
  (3391618, 'NT', 'Yohane', 18, 40, 'Ba mu''ao zui ira, lamane: Böi da''ö, Baraba andrö efa''ö.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 1, 'Aefa da''ö, ba ihalö Yesu Filato, ifabözi''ö.[1]', '["Ayati 1-3: Mat 27:27-30; Mar 15:16-19"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 2, 'Ba lalalau dakula doi saradadu, lafotakula ia, ba lafobaru ia baru luo soyo,', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 3, 'ba la''ondrasi ia, ba lamane: Ya''ugö, razo niha Yehuda? Ba lafalisi mbawania.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 4, 'Ba möi baero zui Wilato, imane khöra: Hiza, u''ohe ia baero khömi, ena''ö aboto ba dödömi, lö usöndra horö.[2]', '["Faigi 18:29–38"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 5, 'Ba möi baero Yesu, mokofia ia takula doi andrö, ba mobaru baru luo soyo no mege.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 6, 'Ba me la''ila ia ere sebua ba enoni andrö, ba mu''ao ira: Foröfa! foröfa!', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 7, 'Latema linia niha Yehuda, lamane: So goroisa khöma, ba ba goroisa andrö, ba si mate ia, me no ibali''ö Ono Lowalangi ia.[5]', '["Mat 26:63–66; MozV 18:20; Faigi 10:33"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 8, 'Me irongo niŵa''öra andrö Filato, ba tedou wa''ata''unia,', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 9, 'ba ifuli ia yomo ba gödo, ba imane khö Yesu: Heza moroi ndra''ugö?', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 10, 'Imane khönia Filato: Hadia, lö muhede''ö khögu? Lö ö''ila, wa tola u''efa''ö ndra''ugö ba tola uforöfa ndra''ugö?', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 11, 'Itema linia Yesu, imane: Lö tola ölau hadia ia khögu ena''ö, na tenga nitehe khöu moroi si yaŵa. Andrö ebua horö zame''e ba dangau ya''o.[7]', '["Rom 13:1"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 12, 'I''otarai da''ö, ba i''alui Filato wangefa''ö ya''ia.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 13, 'Ba me no irongo niŵa''öra andrö Filato, ba i''ohe baero Yesu, ba mudadao ia ba dadaoma zanguhuku, ba naha andrö sotöi "nibale kara", ba li Heberaio, ba "Gabata".[9]', '["Mat 27:19"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 14, 'Ba baŵa wangehao ba gowasa fasa, so labözi önö. Ba imane ba niha Yehuda: Hiza razomi![10]', '["Mar 15:42>"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 15, 'Ba mu''ao ira: Heta! heta! foröfa ia!', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 16, 'Awena ibe''e niforöfa.[12] Ba la''ohe Yesu.', '["Aayati 16–24: Mat 27:31–44; Mar 15:20–32; Luk 23:26, 33–39"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 17, 'Ba i''osa''ö röfania, ba möi ira baero, lasaŵa naha andrö, sotöi "sokamu''u", "Gologata" ba li Heberaio.[13]', '["MozI 22:6"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 18, 'Ba da''ö laforöfa ia ba darua nawönia, samösa dambai, ba gotaluara labe''e Yesu.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 19, 'Ba ifazökhi göi zura Filato, ibe''e ba högö röfa "Yesu, banua Nazareta, razo niha Yehuda" nisurania.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 20, 'Ba ato zombaso sura andrö niha Yehuda, me no ahatö ba mbanua naha andrö, ba niforöfa Yesu, ba no mube''e li Heberaio ba li Ndrawa Roma ba li Ndrawa Heleni.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 21, 'Ba lamane ere sebua ba niha Yehuda khö Wilato: Böi sura: razo niha Yehuda, sura wa no iŵa''ö: Razo niha Yehuda ndra''o.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 22, 'Itema lira Filato, imane: Lö tebulö nisuragu andrö.', '[]', NULL),
  (3391621, 'NT', 'Yohane', 19, 23, 'Ba me no aefa laforöfa Yesu saradadu, ba lahalö nukhania, la''o''öfa, sambua ni''o''öfa zamösa, awö gamezania. Ba si lö tagu-tagu gameza andrö, nisoso, i''otarai si yaŵa, ma''asagörö.', '["Sin 22:19"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 24, 'Ba faoma lamane khö nawöra; Böi tataba ia, datalau fadahö-dahö khönia, ha khö möi ia. Ena''ö itörö zi so ba zura: "No lafaosa khöra nukhagu, ba no fadahö-dahö ira ba gamezagu." Da''ö nilau zaradadu andrö.[14]', '["Sin 22:19"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 25, 'Ba so ba ngai röfa Yesu ninania ba talifusö ninania, Maria, fo''omo Kelofasi andrö ba Maria, banua Magadala andrö.[15]', '["Mar 15:40; Mat 27:56"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 26, 'Ba me i''ila ninania Yesu, awö nifahaönia andrö, somasi ia, ba ngainia, ba imane khö ninania: Hiza nonou, alawe![16]', '["Faigi 20:2; 2:4"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 27, 'Aefa da''ö, ba imane khö nifahaö andrö: Hiza ninau!', '["Faigi 20:2; 2:4"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 28, 'Me aefa da''ö, me no i''ila Yesu, no awai, fefu hadia ia, ena''ö itörö zi so ba zura; ba imane: Owökhi dödögu![17]', '["Faigi 17:4; Sin 69:22"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 29, 'Ba so ba da''ö zamba nahia niro aisö. Ba lafönui rabo, labe''e ba mbalö zukhu ba la''oro''ö khönia, ba mbawania.[18]', '["Mat 27:48"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 30, 'Ba me no ibadu niro aisö andrö, ba imane: No awai! Ba ileagö högönia, ba aetu noso.[19]', '["Mat 27:50"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 31, 'Ba la''andrö khö Wilato niha Yehuda, ena''ö na lafafatö waha niforöfa ba laheta ira, me baŵa wangehao, fa böi toröi ba röfa mbotora, ba luo sabato; ebua sa luo sabato andrö.[20]', '["MozV 21:23"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 32, 'Ba möi zaradadu, lafafatö waha zi darua, niforöfa awönia.', '["MozV 21:23"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 33, 'Ba me larugi Yesu, me la''ila, no mate ia, ba lö lafafatö wahania,', '["YohI 5:6; Heb 9:11; 12:18 b.t."]', NULL),
  (3391621, 'NT', 'Yohane', 19, 34, 'ba ifahö ngainia ikhu doho saradadu si samösa, ba i''anema''ö alua ndro, si faruka idanö.[21]', '["YohI 5:6; Heb 9:11; 12:18 b.t."]', NULL),
  (3391621, 'NT', 'Yohane', 19, 35, 'Ba si no mangila da''ö zamaduhu''ö da''ö, ba duhu wamaduhu''önia; i''ila wa si duhu niŵa''önia, ena''ö mamati ami göi.', '["MozII 12:46; Sin 34:21","Sakh 12:10; Fam 1:7"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 36, 'Andrö si manö, ena''ö itörö zi so ba zura: "Sara böi lafatö tölania".[22]', '["MozII 12:46; Sin 34:21","Sakh 12:10; Fam 1:7"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 37, 'Ba si mane zui ba zura bö''ö: "Anehe dania ira nifahöra andrö."[23]', '["MozII 12:46; Sin 34:21","Sakh 12:10; Fam 1:7"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 38, 'Ba me no aefa da''ö,[24] ba i''andrö khö Wilato Yosefo, banua Garimatia, ena''ö tola iheta mboto Yesu; nifahaö Yesu ia göi, ba ibini''ö, fa''ata''unia niha Yehuda. Ba itehe Filato. Ba möi ira, laheta.[25]', '["Ayati 38–42; Mat 27:57–61; Mar 15:42–47; Luk 23:50–55","Luk 23: 50"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 39, 'Ba so göi Nikodemo andrö, si möi khönia no, si föföna, ba zi bongi, i''ohe emuri ba aloe, nifaruka, mato safiku.[26]', '["Faigi 3:1 b.t.; 7:50"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 40, 'Ba lahalö sa''ae mboto Yesu, la''olohuni muko, ba lalau zamohua andrö; si manö huku ba niha Yehuda, wogo''o si mate.', '["Faigi 3:1 b.t.; 7:50"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 41, 'Ba so ba zahatö ba niforöfa Yesu kabu, ba so lewatö si bohou ba kabu andrö, ba zi lö larai lako''o niha.', '["Yer 53:9"]', NULL),
  (3391621, 'NT', 'Yohane', 19, 42, 'Ba ba da''ö labe''e Yesu, ba mbaŵa wangehao andrö, ba niha Yehuda, me sahatö lewatö andrö.[27]', '["Yer 53:9"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 1, 'Sara wongi aefa zabato, ba möi ba lewatö Maria andrö, banua Magadala, ihulö wongi, me ogömi-gömi na, ba i''ila, no laheta gowe andrö ba lewatö.[1]', '["Mat 28:1","Faigi 13:23"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 2, 'Ba fagohi ia khö Zimoni Fetero ba khö nifahaö si samösa andrö, ni''omasi''ö Yesu, ba imane khöra: No lahalö Duada, ba lewatö, ba lö ta''ila heza labe''e ia.[2]', '["Mat 28:1","Faigi 13:23"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 3, 'Ba möi Wetero, awö nifahaö si samösa andrö, lasaŵa lewatö.', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 4, 'Ba faoma fagohi ira, darua ira. Ba alio nifahaö si samösa andrö wagohisa, moroi khö Wetero, ya''ia zi föföna mondrugi lewatö,', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 5, 'ba me ifaigi bakha, ba i''ila muko andrö, nitou''ö tou; ba lö''ö sa möi ia bakha.', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 6, 'Ba so Zimoni Fetero, i''o''ö, möi ia tou ba lewatö, ba i''ila muko andrö, nitou''ö tou.', '["Faigi 11:44"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 7, 'Ba lö mu''orudugö ba muko andrö zaembu, si so ba högö Yesu mege; no lagölugö, sambua nahania.[3]', '["Faigi 11:44"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 8, 'Ba awena möi tou göi nifahaö si samösa andrö, si föföna mondrugi lewatö, ba i''ila, ba faduhu dödönia.', '["KorI 15:4; Sin 16:10; HalZin 2:25 b.t."]', NULL),
  (3391622, 'NT', 'Yohane', 20, 9, 'Lö''ö na sa aboto ba dödöra zi so ba zura, wa lö tola lö maoso Yesu moroi ba ngai zi mate.[4]', '["KorI 15:4; Sin 16:10; HalZin 2:25 b.t."]', NULL),
  (3391622, 'NT', 'Yohane', 20, 10, 'Ba lafuli ira khöra nifahaö andrö.', '["KorI 15:4; Sin 16:10; HalZin 2:25 b.t."]', NULL),
  (3391622, 'NT', 'Yohane', 20, 11, 'Ba no so ba zinga lewatö Maria andrö, mege-ege. Ba me mege-ege ia, ba ifaigi bakha ba lewatö,', '["Mat 28:5 b.t; Mar 16:5"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 12, 'ba i''ila mala''ika, darua, sobaru safusi, sidadao, samösa tanö ba högö, samösa tanö ba gahe, ba nibe''e boto Yesu mege.[5]', '["Mat 28:5 b.t; Mar 16:5"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 13, 'Lamane khönia: Hana wa mege-ege ndra''ugö, alawe? Imane khöra: No lahalö Zo''aya ya''o, ba lö u''ila, heza labe''e ia.', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 14, 'Me aefa iŵa''ö da''ö, ba ibali''ö ia furi ba i''ila Yesu; no so ba da''ö, ba lö i''ila, wa Yesu da''ö.[6]', '["Mar 16:9"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 15, 'Imane khönia Yesu: Hana wa mege-ege ndra''ugö, alawe? ha niha ni''aluimö?', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 16, 'Imane khönia Yesu: He Maria!', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 17, 'Imane khönia Yesu: Böi babaya ndra''o, lö''ö na si möi ndra''o yaŵa khö Namagu. Ba ae ba dalifusögu andrö, ba ŵa''ö khöra: Möido yaŵa khö Namagu, ba khö Namami, khö Lowalangigu, ba khö Lowalangimi.[8]', '["Mat 28:9–10; Faigi 6:62; Heb 2:11–12; KorI 11:3"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 18, 'Ba möi Maria andrö, banua Magadala, i''ombakha''ö ba nifahaö: No u''ila Duada, ba da''ö niŵa''önia khögu.[9]', '["Mat 16:10"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 19, 'Ba me tanö owi, me luo Migu, me no mulazi mbawandruhö, ba zi so ndra nifahaö, ba wa''ata''ura niha Yehuda, ba möi Yesu, so ia ba gotaluara, ba imane khöra: Ya''ohahau dödömi![10]', '["Luk 24:36"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 20, 'Ba me aefa iŵa''ö da''ö, ba i''oroma''ö khöra danga, awö ngai.', '["Luk 24:36"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 21, 'Ba ifuli imane khöra: Ya''ohahau dödömi! Hulö si mane famatenge Nama ya''o si manö göi wamatengegu ya''ami.[12]', '["Faigi 14:27; 17:18"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 22, 'Ba me no iŵa''ö da''ö ba ihehaini ira, ba imane khöra: Mitema Geheha ni''amoni''ö.[13]', '["Luk 24:49","Mat 16:19; 18:18"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 23, 'Na so ni''efa''ömi horö, ba aefa khöra, ba ba zi lö mi''efa''ö ia, ba lö aefa.[14]', '["Luk 24:49","Mat 16:19; 18:18"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 24, 'Ba lö Toma, awö zi felendrua andrö, nifotöi si faero, me so Yesu.[15]', '["Faigi 11:16"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 25, 'Ba la''ombakha''ö khönia nifahaö bö''ö andrö: No ma''ila Duada.', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 26, 'Ba fitu bongi aefa da''ö, ba so zui si bakha ndra nifahaönia, ba so göi Doma. So Yesu, me no mulazi mbawandruhö, so ia ba gotaluara, ba imane: Ya''ohahau dödömi!', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 27, 'Awena iŵa''ö khö Doma: Oro''ö durumö, ba da''e, ba faigi dangagu, ba oro''ö dangau, ba tufa ngaigu, ba böi zi lö faduhu dödöu, yafaduhu sa''ae.', '[]', NULL),
  (3391622, 'NT', 'Yohane', 20, 28, 'Itema linia Toma, imane khönia: So''aya ya''o ba Lowalangigu![17]', '["Faigi 1:1; Rom 9:5"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 29, 'Imane khönia Yesu: Me no ö''ilado, andrö wa no faduhu dödöu. Ya''ahowu zi faduhu tödö, he lö mangila höröra![18]', '["Faigi 4:48; FetI 1:8; Heb 11:1–27"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 30, 'Ba oya na sa dandra bö''ö, nifazökhi Yesu, ba zanahe ndra nifahaö, si lö musura ba zura andre.[19]', '["Faigi 21:25; HalZin 1:3","Faigi 3:16; YohI 5:13"]', NULL),
  (3391622, 'NT', 'Yohane', 20, 31, 'Ba no musura da''e, ena''ö faduhu dödömi, Keriso Yesu, Ono Lowalangi, ba ena''ö so khömi wa''auri si lö aetu, ba döinia andrö, na faduhu dödömi.[20]', '["Faigi 21:25; HalZin 1:3","Faigi 3:16; YohI 5:13"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 1, 'Aefa da''ö, ba ifuli i''oroma''ö ia Yesu ba nifahaönia, ba zinga mbaŵa Diberia andrö. Imane wangoroma''ö ya''ia:', '["Faigi 1:46"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 2, 'Faoma so ira, Simoni Fetero ba Toma, nifotöi si faero, ba Natana''eli, banua Kana, ba Galilaia, ba ono Zebedaio andrö ba darua na nifahaönia bö''ö.[1]', '["Faigi 1:46"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 3, 'Imane khöra Simoni Fetero: Möido mangai i''a.', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 4, 'Ba me moluo sa''ae, ba so Yesu, ba mbewe nidanö. Ba lö''ö sa la''ila nifahaö andrö, wa Yesu da''ö.[3]', '["Faigi 20:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391624, 'NT', 'Yohane', 21, 5, 'Ba imane khöra Yesu: Hadia, so göda ma''ifu, ya''ami, iraonogu?', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 6, 'Lamane khönia: Lö''ö.', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 7, 'Ba imane nifahaö andrö, ni''omasi''ö Yesu, khö Wetero: Tuada!', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 8, 'Ba ba dundraha la''o''ö nifahaö bö''ö andrö; lö''ö sa aröu danö, ha mato dua ngaotu hela: lasöbi gi''a no mege, ba giri.', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 9, 'Ba me möi ira baene, ba la''ila mbo galitö, tou ba danö, ba no so bawu gi''a, awö roti.', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 10, 'Imane khöra Yesu: Mi''ohe gi''a andrö, sawena mihalö, ösa.', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 11, 'Ba möi yaŵa Zimoni Fetero, isöbi baene giri, no afönu i''a sebua, otu a lima wulu a tölu rozi. Ba he si manö wa''oya, ba lö''ö zui atika giri.[6]', '["Mat 13:47–41"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 12, 'Imane khöra Yesu: Mi''aine, milau manga.', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 13, 'So Yesu, ihalö roti no mege, ibe''e khöra, ba si manö göi gi''a andrö.[7]', '["HalZin 10:41"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 14, 'Medölu sa''ae, möi da''ö, i''oroma''ö ia Yesu ba nifahaönia, me no aefa maoso ia, moroi ba ngai zi mate.[8]', '["Faigi 20:19–26"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 15, 'Ba me aefa manga ira, ba imane Yesu khö Zimoni Fetero: He Simoni, ono Yohane, hadia, abölö omasi''ö ndra''o, moroi ba wa''omasi da''e ndra''o?', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 16, 'Ba ifuli imane khönia: He Simoni, ono Yohane, hadia, omasi''ö ndra''o?', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 17, 'Ifuli imane khönia, no medölu: He Simoni, ono Yohane, hadia, omasi''ö ndra''o?', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 18, 'Si ndruhu-ndruhu niŵa''ögu khöu, me ono matua ndra''ugö, ba no ya''ugö zamakhai böbö talumö, ba möi''ö heza zomasi''ö; ba na atua ndra''ugö, ba ö''oro''ö dangau, ba niha bö''ö zamakhai böbö talumö, ba i''ohe''ö ba zi lö omasi''ö.[12]', '["Faigi 16:30; 2:25; HalZin 20; 28","FetI 5:1; HalZin 21:11; FetII 1:14"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 19, 'Ba wangombakha he wisa wa''amatenia dania ba wamolakhömi Lowalangi, iŵa''ö da''ö.', '["Faigi 16:30; 2:25; HalZin 20; 28","FetI 5:1; HalZin 21:11; FetII 1:14"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 20, 'Ba me ibali''ö ia furi Fetero, ba i''ila, molo''ö nifahaö andrö, ni''omasi''ö Yesu, sidadao göi ba ngai Yesu, ba wemanga no, sanofu no: He Tua, ha niha zi manga mböliu?[14]', '["Faigi 13:25"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 21, 'Ba me i''ila da''ö Fetero, ba imane khö Yesu: Ba hana da''e, Tua?', '["Faigi 13:25"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 22, 'Imane khönia Yesu: Na omasido, lö tebulö ia, irege sodo, ba hana wa öhalö khöu? Ya''ugö, o''ö ndra''o.[15]', '["Fam 1:7–9 b.t."]', NULL),
  (3391624, 'NT', 'Yohane', 21, 23, 'Da''ö mböröta, wa laŵa''ö-ŵa''ö ba dalifusö andrö: Lö mate nifahaö andrö. Ba lö niŵa''ö Yesu khönia, lö mate, imane: Na omasido, lö tebulö ia, irege sodo.', '[]', NULL),
  (3391624, 'NT', 'Yohane', 21, 24, 'Da''ö nifahaö andrö, samaduhu''ö da''e, sanura göi da''e, ba no ta''ila, wa no si duhu wamaduhu''önia.[16]', '["Faigi 16:35; Fam 1:2","Faigi 20:30"]', NULL),
  (3391624, 'NT', 'Yohane', 21, 25, 'Ba oya na sa mbö''önia, nilau Yesu, ba na lazara-zara wananö ba zura ena''ö, ba ba dödögu, ba lö itaha uli danö ma''asagörö zura andrö, nitanö ya''ia.[17]', '["Faigi 16:35; Fam 1:2","Faigi 20:30"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 1, 'No awai khögu zura si föföna andrö, ya''ugö Teofilo, no usura fefu nibörötaigö Yesu, folau ba famahaö,[1]', '["Luk 1:1–3","Mat 28:19; Luk 24:44 b.t.","Mar 16:14; Yoh 20:19–30"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 2, 'irugi luo tefazaŵa ia, me no ibe''e goroisa ba zinenge andrö, ni''anutuyu''önia Eheha ni''amoni''ö,[2]', '["Luk 1:1–3","Mat 28:19; Luk 24:44 b.t.","Mar 16:14; Yoh 20:19–30"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 3, 'ba ni''oya''önia tandra, wangoroma''ö wa no auri ia, me no aefa itaögö wamakao andrö; öfa wulu wongi wa''ara i''oroma-roma''ö ia khöra, i''ombakha''ö khöra ngawalö mbanua Lowalangi andrö.[3]', '["Luk 1:1–3","Mat 28:19; Luk 24:44 b.t.","Mar 16:14; Yoh 20:19–30"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 4, 'Ba me orudu ira, me manga ira, ba iŵa''ö khöra, böi laröi Yeruzalema, labaloi gamabu''ula li Nama andrö, nirongomi khögu (iŵa''ö).[4]', '["Luk 24:49; Yoh 14:16","Mat 3:11; Faigi 2:4; 11:15 b.t."]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 5, 'Idanö sa nibayagö Yohane, ba nibayagö Eheha ni''amoni''ö ami, lö ara tö.[5]', '["Luk 24:49; Yoh 14:16","Mat 3:11; Faigi 2:4; 11:15 b.t."]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 6, 'Ba lasofu khönia si so ba da''ö, lamane: He Tua, hadia öfuli ö''a''azökhi iya''e dania nöri Ndraono Gizeraeli?[6]', '["Luk 19:11 b.t.; 24:21"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 7, 'Ba imane khöra: Tenga si nangea ya''ami zangila baŵa ba bu''u li, nihonogöi Nama ba wa''abölönia,[7]', '["Mat 24:36","Yoh 15:27; Faigi 5:32; Luk 24:47"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 8, 'ba mitema dania wa''abölö Geheha ni''amoni''ö, si möi khömi, ba samaduhu''ö ami khögu ba Yeruzalema, ba ba danö Yudaia, ma''asagörö, ba ba Zamaria, ba irugi wondrege danö.[8]', '["Mat 24:36","Yoh 15:27; Faigi 5:32; Luk 24:47"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 9, 'Ba me aefa iŵa''ö da''ö, ba tefazaŵa ia, anehe ira, ihalö ia lawuo, ba lö''ö sa''ae oroma ia khöra.[9].', '["Mar 16:19"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 10, 'Ba me latöngö mbanua si yaŵa, me mofanö ia, ba hiza, darua zi so ba da''ö khöra niha, sobaru safusi,[10]', '["Yoh 20:12","Luk 21:27; Fam 1:7"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 11, 'sanguma''ö göi: Hana wa so ami ba da''e, wa mitöngö mbanua, ya''ami banua Galilaia? Mangawuli dania Yesu andrö, nihalö ba zorugo moroi ba khömi, si mane me mi''ila ia, me mofanö ia ba zorugo.[11]', '["Yoh 20:12","Luk 21:27; Fam 1:7"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 12, 'Aefa da''ö, ba mangawuli ira ba Yeruzalema, moroi ba hili andrö, sotöi hili wanikha, ba ngai Yeruzalema, mato sambadu fofanö.', '[]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 13, 'Ba me no larugi yomo, ba möi ira yaŵa ba mbate''e ba zi sagötö, ba da''ö soso ira, Fetero ba Yohane ba Yakobo ba Andrea ba Filifo ba Toma ba Batolomaio ba Mataio ba Yakobo, ono Galifaio, ba Simoni Selote ba Yuda, ono Yakobo.[12]', '["Mat 10:2 b.t.","Luk 24:53; Yoh 7:5; Faigi 2:46"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 14, 'Da''ö fefu zi lö aefa-aefa mangandrö, ha sara dödö, awö ndra alawe andrö, ba awö Maria, ina Yesu, ba ira talifusönia.[13]', '["Mat 10:2 b.t.","Luk 24:53; Yoh 7:5; Faigi 2:46"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 15, 'Ba me luo da''ö, ba maoso Wetero, me falukha dalifusö (ba so mato otu a dua wulu wa''ato niha, sowulo ba da''ö) imane:', '[]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 16, 'He ya''ami, ira talifusö, lö tola lö itörö zi so ba zura andrö, si no ihönagö ifaŵa''ögö Eheha ni''amoni''ö, ni''ombakha''ö Dawido, ba khö Yuda andrö, si no tobali samasao sondra''u Yesu.[14]', '["Sin 41:10; Mat 26:47","Luk 6:16","Mat 27:3–10; Nga''ötII 25:12","Sin 69:26; 109:8"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 17, 'Noa sa te''erai ia, awöda, ba no itema dana khönia, halöŵö andrö.[15]', '["Sin 41:10; Mat 26:47","Luk 6:16","Mat 27:3–10; Nga''ötII 25:12","Sin 69:26; 109:8"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 18, 'Ba noa sa isöndra mbenua nibe''e böli luo walö''atulö andrö, ba no aekhu tou ia, ba no aboto dalu, ba no aduwa mbetu''ania ma''afefu.[16]', '["Sin 41:10; Mat 26:47","Luk 6:16","Mat 27:3–10; Nga''ötII 25:12","Sin 69:26; 109:8"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 19, 'Ba no larongo fefu, banua Yeruzalema, andrö labe''e töi mbenua andrö Akhelidama, ba lira, benua ndro geluahania.', '["Sin 41:10; Mat 26:47","Luk 6:16","Mat 27:3–10; Nga''ötII 25:12","Sin 69:26; 109:8"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 20, 'Noa sa musura ba zura zinunö: Sadudu nahania, ba böi i''onaha niha ba: Yamutema niha bö''ö halöŵönia andrö.[17]', '["Sin 41:10; Mat 26:47","Luk 6:16","Mat 27:3–10; Nga''ötII 25:12","Sin 69:26; 109:8"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 21, 'Ba lö''ö sa tola lö tahalö niha, samösa, ba zi no fao-fao khöda, götö wa''ara wangörö-ngörö Zo''aya ya''ita, Yesu, khöda,[18]', '["Yoh 15:27"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 22, 'ibörötaigö ba wamayagö idanö andrö khö Yohane, irugi luo tefazaŵa ia moroi ba khöda; samösa da''ö zamaduhu''ö femaosonia, awöda.', '["Yoh 15:27"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 23, 'Ba lafa''aso zi darua, Yosefo, nifotöi Barasaba, si so töi Yuso na göi, ba Matia.', '["Faigi 2:32; 10:37–41"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 24, 'Ba mangandrö ira, lamane: He So''aya, sangila tödö niha fefu, oroma''ö nituyumö, samösa, ba zi darua andre,[20]', '["Faigi 15:8; Yoh 21:17"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 25, 'sanema naha andrö, ba halöŵö andrö, awö wamaigi-maigi, niröi Yuda, ba we''amöi ba nahania.', '["Faigi 15:8; Yoh 21:17"]', NULL),
  (3394249, 'NT', 'Halöŵö Zinenge', 1, 26, 'Ba lalau fadahö-dahö ba khöra andrö, ba göna Matia, ba tobali famönökhi zinenge andrö, si felendrua ia.[21]', '["Amaed 16:33"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 1, 'Ba me luo wendrakose (si 50) ba no owulo ira fefu, ha sambua naha.[1]', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 2, 'Ba i''ozumagö so zihöngö, si otarai mbanua si yaŵa, hulö na itörö angi sabölö-bölö, ba ifönui nomo andrö, ma''asambua, ba zi dadao ira.[2]', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 3, 'Ba oroma khöra dalinga wandru, si fabali-bali, alitö wamaigira, ba idozigö ira, ahono ba högöra.[3]', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 4, 'Ba fahöna khöra Geheha ni''amoni''ö, ba labörötaigö lalau li bö''ö, si mane nibe''e Geheha khöra fanötöi.[4]', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 5, 'Ba so zi fatewu gana ba Yeruzalema, niha Yehuda, niha sangata''ufi Lowalangi, soroi fefu soi ba guli danö.', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 6, 'Ba me so zihöngö andrö, ba aekhu niha sato ba tobali dödöra, me larongo wehedera ba li khöra, dozi ira.', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 7, 'Ba tobali dödöra, dozi ira, ahöli-höli dödöra ba lamane: Hiza, tenga banua Galilaia ira, dozi sihede andrö?[5]', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 8, 'Ba he wisa wa tarongo lida, dozi ita, li ba danöda, ba zi tumbu ita?', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 9, 'Ya''ita Dawa Waretia ba Dawa Media ba Dawa Gelama, awö zi so ba Mezofotamia, ba ba Yudaia ba ba Gafadokia, ba Wondro ba ba Azia,[6]', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 10, 'ba Werigia ba ba Wambilia, ba danö Miserayi ba ba danö Libia, tanö ba Girene, awö zi fatewu gana ba Roma, niha Yehuda, awö zi no möi banuara,', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 11, 'Dawa Gereta ba Dawa Ara, ba tarongo, lalau lida, wangombakha segebua andrö, nilau Lowalangi.', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 12, 'Ba tobali dödöra, dozi ira, lö la''ila watahögö, faoma lamane khö nawöra: He wisa da''ö dania?', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 13, 'Ba so zangaohangaoha ösa, lamane: Si mabu agu sami.[7]', '["MozIII 23:15","Yoh 3:8; Faigi 3:1,11; 5:12","Mat 3:11","Mar 16:17; Faigi 4:31; 11:15; 10:46","Yoh 7:52","FetI 1:1)","KorI 14:21 b.t."]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 14, 'Ba maoso Wetero, awö zi felezara, muhede ia, imane khöra: He ya''ami, niha Yehuda, awö zi so ba Yeruzalema fefu, ya''aboto ba dödömi da''e, ba mifondrondrongo niŵa''ögu!', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 15, 'Tenga sa si mane niŵa''ömi, wa si no mabu da''e, awena sa göi labözi siŵa.', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 16, 'Da''ö sa ia, niŵa''ö Yoeli, sama''ele''ö andrö:[8]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 17, '"Ba so dania, na luo safuria, iŵa''ö Lowalangi, ba ulau ba niha fefu wöfö Gehehagu, ba mama''ele''ö nonomi matua, awö nonomi alawe, ba la''ila gangilata ono matua khömi ba mangifi zatua khömi.', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 18, 'Ba genonigu ira matua ba ba genonigu ira alawe ulau ösa Gehehagu, na luo da''ö, ba mama''ele''ö ira.', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 19, 'Ba ufazökhi gila-ila ba mbanua si yaŵa ba tandra ba guli danö si tou, do ba alitö ba simbo.[9]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 20, 'Ba tobali sogömi-gömi luo ba do mbaŵa, fatua lö irugi luo Zo''aya andrö, sebua.', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 21, 'Ba tobali auri dozi si angaröfi li töi Zo''aya."[10]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 22, 'He ya''ami, Iraono Gizeraeli, mifondrondrongo da''e! Yesu andrö, banua Nazareta, niha nifaduhu''ö, Lowalangi ba khömi, ba wa''abölö ba ba gila-ila ba ba dandra, nifafazökhi''ö Lowalangi khönia, ba khömi, ni''ilami andrö.[11]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 23, 'Da''ö mege mihalö, me no mube''e ba dangami ia, me no ihonogöi ihuku Lowalangi, me no tohöna mege i''ila, ba no mi''osö ia ba röfa tanga niha baero, wamunu ya''ia.[12]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 24, 'Da''ö nisusugi Lowalangi, me no i''efa''ö khönia wa''afökhö wa''amate, me tebai sa ato itaha ia fa''amate.[13]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 25, 'Imane sa Dawido ba khönia andrö: "Lö aefa-aefa ba duduma hörögu Zo''aya ya''o, noa sa so ia ba gambölögu, fa lö mangiwa ndra''o.[14]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 26, 'Andrö waomuso dödögu ba manunö lelagu, ba ösigu göi, ba molombase dania, ba wanötöna,', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 27, 'lö''ö sa öröi ba mbanua tou nosogu, ba lö ötehe, i''ila wa''obou ni''amoni''ö andrö khöu.[15]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 28, 'No ö''ombakha''ö khögu lala ba wa''auri, öhöna khögu wa''omuso dödö tanö fönau."', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 29, 'He ya''ami, ira talifusö, akha lö aiŵö ndra''o muhede khömi, ba khö duada Dawido, wa no mate ia, awö wa no lako''o, ba so ba khöda lewatönia, irugi ma''ökhö andre.[16]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 30, 'Ba me no sama''ele''ö ia, me no i''ila, no ifabu''u khönia Lowalangi fahölusa, ifedadao ba dadaomania ma''uwunia,[17]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 31, 'me no i''ila zi so na furi dania, ba itörö linia wemaoso Keriso, wa lö''ö sa teröi ia ba mbanua tou, awö wa lö''ö göi i''ila ösinia wa''obou.', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 32, 'Yesu andrö nisusugi Lowalangi, si so na mbörö ba da''ö ndra''aga fefu.[18]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 33, 'Ba me no te''alaŵa''ö ia iada''e kambölö Lowalangi, ba me no itema gamabu''ula li andrö, Eheha ni''amoni''ö andrö, khö Nama, ba no ilau da''e, ni''ilami, nirongomi andre.[19]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 34, 'Tenga sa Dawido zi möi yaŵa ba zorugo, ba ya''ia zanguma''ö: "No iŵa''ö So''aya khö Zo''aya ya''o: Dadao ba gambölögu,[20]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 35, 'irege ube''e tou barö gaheu zi fa''udu khöu."', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 36, 'Ya''aboto sibai iada''e ba dödö ma''uwu Gizeraeli fefu, wa no ibali''ö So''aya ba Keriso da''ö Lowalangi, Yesu andrö, niforöfami.[21]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 37, 'Ba me larongo da''ö, ba manga ia ba dödöra ba lamane khö Wetero ba ba zinenge bö''ö andrö: He mawisa ena''ö, ya''ami, ira talifusö?[22]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 38, 'Ba imane khöra Fetero: Mifalalini gera-erami ba mifabayagö''ö idanö ami, dozi ami, ba döi Yesu Keriso, ba wangefa''ö horömi andrö, ba mitema dania mbuala andrö, Eheha ni''amoni''ö.[23]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 39, 'Khömi sa gamabu''ula li andrö ba ba ndraonomi ba ba zi so ba zaröu fefu, gofu ha wa''ato nikaoni Zo''aya, Lowalangida.[24]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 40, 'Ba so na niŵa''önia, tanö bö''ö, famaduhu''ö, ba ifarou dödöra, imane: Ya''aefa ami ba niha si tefuyu tödö andre.[25]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 41, 'Ba lafabayagö''ö idanö ira samonaha taroma linia ba dödöra, ba mato tölu ngahönö niha, si te''anö, ha si ma''ö-ma''ökhö andrö.[26]', '["Yoel 2:28—32","Luk 21:25","Rom 10:13","Faigi 10:38; Rom 1:4","Faigi 4:28; 3:15 b.t.","Luk 11:22","Sin 16:8 b.t.","Faigi 13:35 b.t.","SalI 2:10","Sin 132:11 b.t.; Luk 1:32; Rom 1:3","Faigi 1:8; 3:15","Faigi 5:31; Yoh 12:32; 14:26; Sin 68:19","Sin 110:1","Fil 2:11","Heb 4:12; Faigi 16:30","Faigi 3:19; 10:45","Yoel 2:28; Yoh 10:16","Fil 2:15","Yes 53:11,12"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 42, 'Ba lö tebulö ira nifahaö zinenge, ba he ba wefao, ba he ba wamoboto roti ba ba wangandrö.[27]', '["Faigi 20:7","Faigi 5:11,12","Faigi 4:32","Faigi 2:42","Faigi 4:4"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 43, 'Ba dozi ata''u niha, ba oya gila-ila ba oya dandra, nifazökhi zinenge.[28]', '["Faigi 20:7","Faigi 5:11,12","Faigi 4:32","Faigi 2:42","Faigi 4:4"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 44, 'Ba no orudu zamati, fefu, faoma khöra zi so khöra, fefu.[29]', '["Faigi 20:7","Faigi 5:11,12","Faigi 4:32","Faigi 2:42","Faigi 4:4"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 45, 'Ba la''amawa mbenuara, awö gama-gamara, ba ladozigö wamaosa, lafaigi zabölö moguna.', '["Faigi 20:7","Faigi 5:11,12","Faigi 4:32","Faigi 2:42","Faigi 4:4"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 46, 'Ba ero ma''ökhö so ira ba gosali, lö aefa-aefa, ha sambua dödöra, laboboto roti ba nomo misa, latema göra ba da''ö, omuso dödöra ba atulö.[30]', '["Faigi 20:7","Faigi 5:11,12","Faigi 4:32","Faigi 2:42","Faigi 4:4"]', NULL),
  (3394251, 'NT', 'Halöŵö Zinenge', 2, 47, 'Lasuno Lowalangi, ba ebua khöra dödö niha sato fefu, ba ero ma''ökhö ifa''anö khöra So''aya zanöndra fangorifi andrö.[31]', '["Faigi 20:7","Faigi 5:11,12","Faigi 4:32","Faigi 2:42","Faigi 4:4"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 1, 'Möi miyaŵa ndra Fetero Yohane ba gosali, me inötö wangandrö, me labözi tölu.[1]', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 2, 'Ba hiza niha, sombuyu-mbuyu moroi ba dalu ninania, nilu''i. Ero ma''ökhö lafedadao ia ba zinga mbawandruhö gosali, nifotöi si sökhi, ba wangandrö böli gö ba zi möi ba gosali.[2]', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 3, 'Ba me i''ila ndra Fetero Yohane, si möi ba gosali, ba mangandrö böli gö ia khöra.', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 4, 'Ba inehegö ia Fetero, awö Yohane imane: Faigi ndra''aga.', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 5, 'Ba ifaigi ira, iwai so zinemania khöra.', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 6, 'Ba imane Fetero: Lö khögu firö ba lö ana''a, ba hadia zi so khögu, ba ba ube''e khöu: Ba döi Yesu Keriso, banua Nazareta, owaö-waö,[3]', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 7, 'Ba ira''u dangania kambölö, ifazizio. Ba i''anema''ö abe''e gahenia, awö mbu''u gawononia,', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 8, 'ifaröga ia ba muzizio ba mowaö-waö; ba möi ia ba gosali, fao ia khöra, mowaö-waö ia ba mamaröga ba isuno Lowalangi.[4]', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 9, 'Ba la''ila niha sato fefu, mowaö-waö ia ba manuno Lowalangi ia,', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 10, 'Ba la''ila ia, wa ya''ia da''ö, sidao-dao ba mbawandruhö gosali si sökhi ba wangandrö böli gö; ba a''oi so wa''ahöli-höli dödöra ba fa''atobali dödöra, ba zi no falukha ia.[5]', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 11, 'Ba me lö iröi ndra Fetero Yohane, ba owulo khöra niha sato fefu ba newali, nifotöi ewali Zelomo, (ewali nifolose) no tobali dödöra.[6]', '["Faigi 10:3; Luk 1:10","Faigi 14:8","Mat 10:9; Mar 16:17 b.t.","Yes 35:6; Luk 5:25; 17:15","Luk 5:26","Yoh 10:23"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 12, 'Ba me i''ila da''ö Fetero, ba itema li niha sato, imane: He ya''ami, Iraono Gizeraeli hadia wa ahöli-höli dödömi ba da''ö, ba hadia wa mifaigi-faigi ndra''aga, hulö na ya''aga zamowaö-waö niha andre ba wa''abölöma, ba ma ba wa''atulö dödöma?', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 13, 'Lowalangi ndra Aberahamo, Iza''aki, Yakobo, Lowalangi ndra tuada, no ifolakhömi nononia Yesu, nibe''emi ba danga Wilato, ni''osilö''ögömi fönania, he no iŵa''ö da''ö, la''efa''ö.[7]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 14, 'Ba ya''ami, ba no mi''osilö''ögö ni''amoni''ö andrö, satulö, ba no mi''andrö, latehe khömi zange''e.[8]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 15, 'Ba no mibunu zalaŵa sangorifi andrö, nisusugi Lowalangi, moroi ba ngai zi mate, ba zi so ba mbörö ndra''aga.[9]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 16, 'Ba famati ba döinia mbörö, wa no i''abölö''ö töinia da''e, ni''ilami, nirongomi andre; ba famati andrö, ni''asogönia zame''e khönia fangabe''e andre, ba zanehe ami fefu.[10]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 17, 'Ba iada''e, ya''ami, ira talifusö, u''ila, me lö mi''ila watahögö, andrö mimanö, ba si manö göi zalaŵami.[11]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 18, 'Ba no ifatörö ba zi manö Lowalangi nihönagönia fama''ombakha''ögö ba zama''ele''ö andrö fefu, wa itaögö wamakao Keriso andrö khönia.[12]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 19, 'Andrö mifalalini gera erami, ba mifuli ami, ba wamabeta''ö horömi, ena''ö alua götö wa''ohahau dödö, na inehegö ita Lowalangi,[13]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 20, 'ba ena''ö ifatenge nihonogöi khömi andrö, Keriso Yesu andrö.[14]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 21, 'Lö''ö sa tola lö ifonaha ia sorugo, irege götö wanga''azökhi fefu, hadia ia, niŵa''ö Lowalangi, ni''ombakha''ö zama''ele''ö andrö khönia, ni''amoni''ö, i''otarai mböröta danö''a.[15]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 22, 'Noa sa iŵa''ö Moze: "I''asogö khömi So''aya Lowalangida zama''ele''ö, talifusömi, si mane ya''o; da''ö nifondrondrongomi li, fefu hadia ia niŵa''önia khömi."[16]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 23, 'Ba tobali, fefu gofu ha niha zi lö mamondrongo li zama''ele''ö andrö, ba nihori ba mbanua andre."', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 24, 'Ba dozi göi sama''ele''ö, i''otarai Zamu''eli, awö moroi furinia, ha wa''ato zi no muhede, ba noa göi la''ombakha''ö luo da''e.[17]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 25, 'ya''ami ma''uwu zama''ele''ö andrö, ono wawu''usa li andrö ami, ni''asogö Lowalangi khö ndra tuada, me iŵa''ö khö Gaberahamo: "Ba khö ma''uwumö dania tefahowu''ö fefu soi ba guli danö."[18]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394253, 'NT', 'Halöŵö Zinenge', 3, 26, 'khömi i''ofönai''ö Lowalangi, wamatenge ononia, me no isusugi, ba wamahowu''ö ya''ami, na mifuli ami fefu, na miröi zi lö sökhi andrö khömi.[19]', '["Luk 23:22,23","Mat 27:20,21","Faigi 5:31; 4:33; Luk 24:48","Faigi 4:10–12","Faigi 13:27; Luk 23:34; KorI 2:8","Yes 53:5; Luk 24:25 b.t.","Faigi 2:38","Yes 57:15,16","Faigi 1:11; KorI 15:25. 28","MozV 18:15 b.t.; Heb 3:2 b.t.","Luk 1:70 b.t.","MozI 22:18; Rom 9:4 b.t.","Faigi 13:46; Mat 10:6"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 1, 'Ba me laŵa''ö da''ö ba niha sato, ba maoso khöra gere andrö, awö gumandra ba gosali, awö zadukaio,', '["Faigi 23:8"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 2, 'afökhö khöra, me lafahaö niha, me la''ombakha''ö, khö Yesu so wemaoso zi mate.[1]', '["Faigi 23:8"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 3, 'Ba lara''u ira ba lakuru, irugi mahemolu ö; noa sa arakha bongi.', '[]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 4, 'Ba ato zamati, samondrongo li andrö, ba tobali lima ngahönö wa''ato ndra matua.[2]', '["Faigi 2:41,47; 5:14"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 5, 'Ba mahemolu ö, ba falukha zalaŵara ba satuara ba sangila amakhöita khöra,', '["Yoh 18:13"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 6, 'ba Yeruzalema, ba Hanasi, ere sebua andrö, ba Kayafa ba Yohane ba Alesandro ba si fatalifusö khö ndra ere sebua, fefu.[3]', '["Yoh 18:13"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 7, 'Ba lafa''aso ira ba gotaluara ba lasofu: Ha niha zanehe khömi ba ha töi khömi, wolau da''ö?[4]', '["Mat 21:23"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 8, 'Ba imane khöra Fetero, si no fahöna Eheha ni''amoni''ö: He ya''ami, salaŵa mbanua andre ba ya''ami, satua![5]', '["Luk 12:11,12","Faigi 3:6,16; 5:30","Mat 21:42; Sin 118:22","Faigi 2:21; 10:43"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 9, 'Na tesekhegö ndra''aga ma''ökhö andre, ba wanoloma andrö, ba niha sofökhö andrö, hadia wangabe''enia,', '["Luk 12:11,12","Faigi 3:6,16; 5:30","Mat 21:42; Sin 118:22","Faigi 2:21; 10:43"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 10, 'ba ya''aboto ba dödömi fefu ba ba dödö Ndraono Gizeraeli fefu: ba döi Yesu, banua Nazareta, niforöfami, nisusugi Lowalangi, moroi ba ngai zi mate, ba döi da''ö abe''e da''e, fönami,[6]', '["Luk 12:11,12","Faigi 3:6,16; 5:30","Mat 21:42; Sin 118:22","Faigi 2:21; 10:43"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 11, 'Da''ö gowe andrö, ni''ositengagömi, ya''ami sotomo, gowe si no tobali toyo ba watalinga.[7]', '["Luk 12:11,12","Faigi 3:6,16; 5:30","Mat 21:42; Sin 118:22","Faigi 2:21; 10:43"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 12, 'Ba lö fangorifi ba danö bö''ö, ba lö''ö sa göi töi bö''ö nibe''e ba niha, ba guli danö, ba wangorifi ya''ita.[8]', '["Luk 12:11,12","Faigi 3:6,16; 5:30","Mat 21:42; Sin 118:22","Faigi 2:21; 10:43"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 13, 'Ba me la''ila wa lö aiŵö ndra Fetero Yohane, ba me no larongo, niha si lö mufahaö ira, ono mbanua, ba ahöli-höli dödöra, ba la''ila ira, wa no awö Yesu ira föna.', '["Faigi 3:8–10; Yoh 11:47"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 14, 'Ba me la''ila, awöra niha andrö nifadöhö fökhö, ba tebai labu''a.', '["Faigi 3:8–10; Yoh 11:47"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 15, 'Ba laŵa''ö khöra, mofanö ira, laheta ira ba rafe sebua: mamagölö ira, lamane:', '["Faigi 3:8–10; Yoh 11:47"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 16, 'He tawisa ba niha andrö, noa sa oroma ba zi so ba Yeruzalema fefu, wa no lafazökhi dandra sanehe niha, ba tebai ta''osilö''ögö,[9]', '["Faigi 3:8–10; Yoh 11:47"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 17, 'ba fa böi tedou terongo ba niha, ba tafeta''u ira, böi sa''ae itörö lira döi andrö, gofu ha khö.', '["Faigi 3:8–10; Yoh 11:47"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 18, 'Ba humede ira khöra, laŵa''ö khöra, böi manö sa''ae muhede ira ba böi namahaö, wangombakha töi Yesu.[10]', '["Faigi 5:28,40"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 19, 'Ba latema lira ira Fetero Yohane, lamane khöra: Mi''era-era tödömi, na atulö khö Lowalangi, na la''o''ö khömi, moroi ba wolo''ö khö Lowalangi;[11]', '["Faigi 5:29","YohI 1:1 b.t."]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 20, 'tebai sa khöma, lö maŵa''ö ni''ilama, nirongo dögi dalingama.[12]', '["Faigi 5:29","YohI 1:1 b.t."]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 21, 'Ba me no lafeta''u ira na, ba la''efa''ö, me lö lasöndra, he lawisa, wangotu''ö ya''ira, ba niha sato, me no oi dozi lasuno Lowalangi ba da''ö no mege;[13]', '["Faigi 5:26"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 22, 'noa sa töra öfa wulu fakhe niha andrö nifazökhi tandra andrö, famadöhö fökhö.', '["Faigi 5:26"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 23, 'Ba me no aefa ira, ba möi ira ba nawöra, ba la''ombakha''ö fefu niŵa''ö ndra ere sebua, ba satua, khöra.', '[]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 24, 'Ba me no larongo, ba mangandrö ira khö Lowalangi, ha sara dödö, lamane: He So''aya, ya''ugö zamazökhi sorugo, awö danö, awö nasi, awö nösinia fefu,[14]', '["Faigi 14:15; MozI 1:1; Neh 9:6","Sin 2:1–2","Luk 23:12","Faigi 2:23"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 25, 'ya''ugö zanguma''ö ni''ombakha''ö duama Dawido enonimö andrö, moroi ba Geheha ni''amoni''ö: Hana wa mofönu niha baero, ba hana wa la''alu-alui soi zi lö boto?[15]', '["Faigi 14:15; MozI 1:1; Neh 9:6","Sin 2:1–2","Luk 23:12","Faigi 2:23"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 26, 'Molaŵa zalaŵa ba guli danö ba samatörö andrö, ba mamagölö, ba khö Zo''aya ba ba khö Keriso andrö khönia."', '["Faigi 14:15; MozI 1:1; Neh 9:6","Sin 2:1–2","Luk 23:12","Faigi 2:23"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 27, 'Ba si ndruhu, noa sa falukha ira ba mbanua andre ba khö nonou andrö, ni''amoni''ö, nibayoiniu, Herode ba Fondrio Filato, awö niha baero, awö soi Ndraono Gizeraeli,[16]', '["Faigi 14:15; MozI 1:1; Neh 9:6","Sin 2:1–2","Luk 23:12","Faigi 2:23"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 28, 'ba wolau hadia nihönagö dangau, awö gera-erau, wangohonogöi, salua dania.[17]', '["Faigi 14:15; MozI 1:1; Neh 9:6","Sin 2:1–2","Luk 23:12","Faigi 2:23"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 29, 'Ba iada''e, ya''ugö So''aya, ba nehegö wameta''ura andrö, ba tolo genonimö, ena''ö lö''ö manö aiŵö ira, wangombakha limö,', '["Faigi 14:15; MozI 1:1; Neh 9:6","Sin 2:1–2","Luk 23:12","Faigi 2:23"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 30, 'ba oro''ö dangau, ba wamadöhö fökhö, ena''ö so dandra, awö gila-ila, börö döi nonou andrö, ni''amoni''ö, Yesu.', '["Faigi 14:15; MozI 1:1; Neh 9:6","Sin 2:1–2","Luk 23:12","Faigi 2:23"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 31, 'Ba me no mangandrö ira, ba humeu-heu nomo andrö, sowulo ira, ba tehöna khöra fefu Geheha ni''amoni''ö, ba lö aiŵö ira, wangombakha li Lowalangi.[18]', '["Faigi 2:2; 13:52"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 32, 'Ba ha sambua dödö, ha wa''ato zamati, ha sambua gera-era, ba samösa lö sanguma''ö khönia hadia ia nibaya-bayania, faoma sa khöra manö fefu.[19]', '["Faigi 2:44 b.t.; Yoh 17:21,22"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 33, 'Ba abölö sibai zinenge, wamaduhu''ö femaoso Yesu Keriso, So''aya, ba abölö wa''ebua dödö ba khöra fefu.[20]', '["Faigi 2:24","Luk 12:33","KorII 8:14"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 34, 'Ba lö''ö sa göi sambö balazo ba khöra, dozi sa sokhö benua, ba ma omo, ba la''amawa, ba la''ohe mböli ni''amawara andrö.[21]', '["Faigi 2:24","Luk 12:33","KorII 8:14"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 35, 'labe''e ba danga zinenge, ba lafosasi ba zamösana, lafaigi zabölö moguna.[22]', '["Faigi 2:24","Luk 12:33","KorII 8:14"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 36, 'Ba Yosefo, nibe''e zinenge töi Baranaba, "ono wondrara dödö" geluahania, ono Lewi, moroi ba hulo Gifero mböröta,[23]', '["Faigi 11:22"]', NULL),
  (3394255, 'NT', 'Halöŵö Zinenge', 4, 37, 'me so khönia mbenua, ba i''amawa, ba i''ohe mböli, ibe''e ba danga zinenge.', '["Faigi 11:22"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 1, 'Ba i''amawa mbenua khönia si samösa, Anania döinia, ba awönia wo''omonia,', '["Faigi 4:35"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 2, 'Safira, ba ihalö khönia ösa, mbölinia, fo''omonia göi zangila, ba i''ohe ösa, ibe''e ba danga zinenge.[1]', '["Faigi 4:35"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 3, 'Ba imane Fetero: He Anania, hana wa no fahöna ba dödöu Zatana, fa ölimo Geheha ni''amoni''ö ba öhalö khöu ösa, mböli mbenua andrö?[2]', '["Luk 22:3; Yoh 8:44"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 4, 'Tenga khöu, na lö mu''amawa ia mena''ö, ba me no mu''amawa, ba tenga ba dangau manö so? Ba hana wa öfa''amöi ba dödöu wolau si manö? Tenga niha nilimou, no Lowalangi ölimo.', '["Luk 22:3; Yoh 8:44"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 5, 'Ba me irongo niŵa''önia andrö, ba alau tou ia, ba aetu noso.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 6, 'Ba maoso nono matua, laheta ia, la''ohe baero ba lako''o.[3]', '["MozIII 10:5"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 7, 'Ba so mato tölu za gotalua, ba so wo''omonia, lö nirongonia da''ö no mege.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 8, 'Ba imane khönia Fetero: Ombakha''ö khögu, na si manö wa''ebua mböli mbenua andrö khömi?', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 9, 'Ba imane khönia Fetero: Hana wa mamagölö ami, ba wanandraigö Eheha Zo''aya? Hiza, so sa''ae moroi tou zogo''o fo''omou mege, ba la''ohe baero ndra''ugö göi.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 10, 'Ba i''anema''ö alau tou ia, fönania, ba aetu noso.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 11, 'Ba ihawui fa''ata''u sebua mbanua fefu, awö dozi samondrongo da''ö.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 12, 'Ba oya nifazökhi ndra sinenge tandra ba ila-ila, ba niha. Ba no orudu ira, ba newali Zelomo andrö, (ewali nifolose) ha sambua dödö.[5]', '["Faigi 2:43; 4:30; 3:11","Faigi 4:4","Faigi 19:11,12; Yoh 14:12","Faigi 8:7; Mar 16:17"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 13, 'Ba ata''u danö bö''ö fefu, orudu khöra, ba lasuno zui ira niha sato.', '["Faigi 2:43; 4:30; 3:11","Faigi 4:4","Faigi 19:11,12; Yoh 14:12","Faigi 8:7; Mar 16:17"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 14, 'Ba ato sa nifa''anö, samati khö Zo''aya, ato ndra matua ba ato ndra alawe,[6]', '["Faigi 2:43; 4:30; 3:11","Faigi 4:4","Faigi 19:11,12; Yoh 14:12","Faigi 8:7; Mar 16:17"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 15, 'irege la''ohe baero baolayama zofökhö, ba gaso ba ba hea-hea, ena''ö na mato samösa na atö zi göna lumö Wetero, na so ia.[7]', '["Faigi 2:43; 4:30; 3:11","Faigi 4:4","Faigi 19:11,12; Yoh 14:12","Faigi 8:7; Mar 16:17"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 16, 'Ba la''ondrasi göi niha sato, moroi ba mbanua si fasui Yeruzalema, la''ohe zofökhö, awö nifakao mbekhu si ra''iö, ba ahori tefadöhö.[8]', '["Faigi 2:43; 4:30; 3:11","Faigi 4:4","Faigi 19:11,12; Yoh 14:12","Faigi 8:7; Mar 16:17"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 17, 'Ba maoso gere sebua ba awönia fefu, si faehu huku andrö, sadukaio, mofönu dödöra.[9]', '["Faigi 4:1; 3:6"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 18, 'Lara''u zinenge, ba lakuru, ba gurunga gumandru.', '["Faigi 4:1; 3:6"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 19, 'Ba ba zi bongi, ba ibokai mbawandruhö gurunga mala''ika Lowalangi, i''ohe baero ira ba imane:[10]', '["Faigi 12:7 b.t."]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 20, 'Mi''ae mi''oroma''ö ami ba mi''ombakha''ö ba gosali ba niha sato daroma li fangorifi andrö fefu.[11]', '["Yoh 6:68; 17:3"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 21, 'Ba me no larongo da''ö, ba möi ira ba gosali, me moluo sibai, mamahaö ira.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 22, 'Ba me möi genoni, ba lö lasöndra ba gurunga. Ba lafuli ira, la''ombakha''ö,', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 23, 'lamane: Noa sa muhaogö wokusi kurunga, me soga, no so ba zinga mbawandruhö zanaro, ba me no mabokai, ba lö niha bakha.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 24, 'Ba me larongo niŵa''öra andrö kumandra ba gosali ba ira ere sebua, ba abu dödöra, ba khöra andrö, he wisa da''ö dania.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 25, 'Ba so zangombakha khöra: Hiza, niha andrö, nibe''emi ba gurunga, no so ba gosali, mamahaö niha.', '[]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 26, 'Ba möi gumandra, awö genoni andrö, lahalö ira. Tenga ni''anösö''ö, ata''u sa ira niha sato, fa lö latebu kara ira.[12]', '["Faigi 4:21"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 27, 'Ba la''ohe ira ba rafe sebua.', '["Faigi 4:21"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 28, 'Ba isofu, khöra ere sebua, imane: No mahaogö wanguma''ö khömi, böi mamahaö ami, wangombakha töi andrö, ba hiza, anönö Yeruzalema famahaömi mibe''e, ba edöna ami mi''ohe ba huluma ndro niha andrö.[13]', '["Faigi 4:18; Mat 27:25"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 29, 'Ba latema linia Fetero ba ira sinenge, lamane: Ni''o''ö khö Lowalangi, moroi ba wolo''öda ba niha.[14]', '["Faigi 4:19 b.t.","Faigi 3, 13 b.t.; 10:39","Faigi 2:33,36"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 30, 'No isusugi Lowalangi ndra tuada Yesu andrö, nibunumi, nifanaŵa ba döla geu.[15]', '["Faigi 4:19 b.t.","Faigi 3, 13 b.t.; 10:39","Faigi 2:33,36"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 31, 'Da''ö ni''alaŵa''ö Lowalangi yaŵa, tangania kambölö, solohe ba sangorifi, ba wame''e famalalini era-era ba Ndraono Gizeraeli, ba fangefa horö.[16]', '["Faigi 4:19 b.t.","Faigi 3, 13 b.t.; 10:39","Faigi 2:33,36"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 32, 'Ba ya''aga zi so ba mbörö, ba niŵa''ö andre, awö Geheha ni''amoni''ö, nibe''e Lowalangi ba zolo''ö khönia.', '["Faigi 4:19 b.t.","Faigi 3, 13 b.t.; 10:39","Faigi 2:33,36"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 33, 'Ba me larongo da''ö, ba afökhö sibai ba dödöra, ba mamagölö ira, ba wamunu ya''ira.[17]', '["Faigi 7:54"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 34, 'Ba maoso zamösa ba rafe sebua, farizaio, Gamalieli döinia, samahaö ba goroisa, ni''omasi''ö niha sato, iŵa''ö lafofanö baero ma''ifu niha andrö.[18]', '["Faigi 22:3"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 35, 'Ba imane khöra:', '["Faigi 22:3"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 36, 'Lö ara na sa, ba maoso Doida andrö, sanguma''ö sebua ia, ba möi awönia niha, mato öfa ngaotu; ba no labunu ia ba tefazawili fefu, ha wa''ato zi fao khönia, ba tobali faya.[19]', '["Faigi 21:38","Luk 2:2","Mat 15:13","Amaed 21:30; Yes 8:10; Faigi 23:9"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 37, 'Aefa da''ö, ba maoso Yuda andrö, banua Galilaia, me luo latanö ba zura döi niha, ba idönisi niha, ba wolo''ö khönia; ba nibunu göi da''ö, ba nifazawili fefu, ha wa''ato zolo''ö khönia.[20]', '["Faigi 21:38","Luk 2:2","Mat 15:13","Amaed 21:30; Yes 8:10; Faigi 23:9"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 38, 'Ba iada''e ba uŵa''ö khömi: Miböhöli niha andrö, ba böi mitegu ira. Na moroi ba niha lala andrö, awö nilau andrö, ba si lö fozu dania.[21]', '["Faigi 21:38","Luk 2:2","Mat 15:13","Amaed 21:30; Yes 8:10; Faigi 23:9"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 39, 'Ba na moroi ba Lowalangi, ba tebai mitenaŵa, fa böi göi samadaö khö Lowalangi ami.[22]', '["Faigi 21:38","Luk 2:2","Mat 15:13","Amaed 21:30; Yes 8:10; Faigi 23:9"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 40, 'Ba la''o''ö khönia; ba humede ira ba zinenge no mege, lafabözi''ö, ba laŵa''ö khöra, böi latötöi döi Yesu andrö; ba la''efa''ö ira.[23]', '["Faigi 4:17,18"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 41, 'Ba laröi sa''ae rafe sebua, omuso dödöra, me no tetehe khöra, la''o''aya ira, börö döi andrö.[24]', '["Mat 5:10—12; Luk 21:17; FetI 4:13","Mar 16:15"]', NULL),
  (3394257, 'NT', 'Halöŵö Zinenge', 5, 42, 'Ba lö labato wamahaö ba fangombakha Yesu Keriso ba gosali ba ba nomo misa, ero ma''ökhö.[25]', '["Mat 5:10—12; Luk 21:17; FetI 4:13","Mar 16:15"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 1, 'Ba me luo da''ö, me tobali ato nifahaö, ba tesao wekökö-kökö Ndrawa Heleni ba niha Heberaio, me te''ositengagö lakha mbanua khöra, ba dolo-tolo andrö, sero ma''ökhö.[1]', '["Faigi 4:35"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 2, 'Ba lafalukha''ö nifahaö sato si felendrua, lamane: Lö omasiga, maröi daroma li Lowalangi, ba we''amöi ngoni-ngoni ba wemanga.[2]', '["Faigi 4:33","TimI 3:8 b.t.","Faigi 1:14; TimI 5:17"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 3, 'Ba mifaigi niha, ba khömi, ya''ami, ira talifusö, dafitu, si sökhi turia, si no fahöna Eheha ba fa''atua-tua, nifataroda ba halöŵö andrö.[3]', '["Faigi 4:33","TimI 3:8 b.t.","Faigi 1:14; TimI 5:17"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 4, 'Ba lö tebulö ndra''aga ba wangandrö ba ba halöŵö fangombakha taroma li.[4]', '["Faigi 4:33","TimI 3:8 b.t.","Faigi 1:14; TimI 5:17"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 5, 'Ba omasi zato fefu niŵa''ö andrö, ba latutuyu Zitefano andrö, niha si no fahöna famati ba Eheha ni''amoni''ö, ba Filifo ba Ferokhoro ba Nikanoro ba Timo ba Faremena ba Nikola''o, si no möi banuara, banua Gandriokhia,[5]', '["Faigi 8:5; 21:8","Faigi 1:23; 8:15,17; TimI 4:14; 5:22"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 6, 'la''ohe ira ba zinenge, ba mangandrö da''ö ba latufa högöra tanga.[6]', '["Faigi 8:5; 21:8","Faigi 1:23; 8:15,17; TimI 4:14; 5:22"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 7, 'Ba monönö-nönö li Lowalangi, ba tobali ato sibai nifahaö ba Yeruzalema, ato göi gere, si faduhu tödö, solö''ö.[7]', '["Faigi 12:24; Rom 1:5"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 8, 'Ba ifazökhi gila-ila, awö dandra sebua ba niha, Sitefano, si no fahöna fa''ebua dödö ba fa''abölö.', '[]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 9, 'Ba maoso ösa ono zekola andrö, sotöi sekola Liberitini ba banua Girene ba banua Alesandria ba ono zekola zi otarai Gilikia ba Azia, fahuhuo ira khö Zitefano.[8]', '["Faigi 11, 20; 18, 24","Luk 21:15"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 10, 'Ba tebai lalaŵa wa''atua-tua andrö awö Geheha khönia, ba wahuhuosa.[9]', '["Faigi 11, 20; 18, 24","Luk 21:15"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 11, 'Awena lafawe''e niha, sanguma''ö: No marongo, me itandraŵaisi Moze, awö Lowalangi, da''e.', '[]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 12, 'Ba la''o''ou niha sato, awö zatua, awö zangila amakhoita. Ba maoso ira, lasöbi da''ionia, la''ohe ba rafe sebua,', '["Mat 26:59; Faigi 21:28; 7:48 b.t.; Yer 26:11","Mat 24:2; 5:17"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 13, 'ba la''asogö zi so ba mbörö, sofaya, sanguma''ö: Lö ibato-bato niha andre, wangosiwawöi naha ni''amoni''ö andrö, awö goroisa.[10]', '["Mat 26:59; Faigi 21:28; 7:48 b.t.; Yer 26:11","Mat 24:2; 5:17"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 14, 'No marongo, me iŵa''ö: Idudugö dania naha andrö Yesu andrö, banua Nazareta, ba iwu''ai dania huku andrö, nibe''e Moze khöda.[11]', '["Mat 26:59; Faigi 21:28; 7:48 b.t.; Yer 26:11","Mat 24:2; 5:17"]', NULL),
  (3394258, 'NT', 'Halöŵö Zinenge', 6, 15, 'Ba lanehegö ia dozi sidadao ba rafe sebua, ba hulö mbawa mala''ika mbawania, wamaigira.', '[]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 1, 'Ba imane ere sebua: Hadia, duhu, si manö da''ö?', '[]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 2, 'Ba imane Sitefano: He ya''ami, ira talifusö, ba ya''ami, ira ama, mifondrondrongo! No i''roma''ö ia Lowalangi lakhömi andrö khö duada Aberahamo, me so ia ba Mezofotamia, me lö''ö na si möi ia ba Harana,[1]', '["Faigi 22:1","MozI 11:31; 12:1 b.t.","Yes 24:2,3"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 3, 'imane khönia: "Heta''ö ba danömi ba ba dalifusöu ba ae ba danö ni''oroma''ögu khöu dania."[2]', '["Faigi 22:1","MozI 11:31; 12:1 b.t.","Yes 24:2,3"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 4, 'Ba iheta ia ba danö Galedaia, ba Harana so ia. Ba me no mate namania, ba iheta ia ba da''ö Lowalangi, i''ohe ba danö andre, ba zi so ami iada''e.[3]', '["Faigi 22:1","MozI 11:31; 12:1 b.t.","Yes 24:2,3"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 5, 'Ba lö ibe''e khönia ba da''e tanö ondröita, mitou dania, sambalahe lö''ö.', '["Faigi 22:1","MozI 11:31; 12:1 b.t.","Yes 24:2,3"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 6, 'Imane sa Lowalangi: "Si fatewu gana dania ma''uwumö, ba danö bö''ö, ba la''osawuyu ira, ba lafakao, öfa ngaotu fakhe.[5]', '["MozI 12:7","MozI 15:13 b.t.; MozII 12:40; Gal 3:17","MozII 3:12","MozI 17:10 b.t.; 21:2 b.t.; 25:26; 35:22 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 7, 'Ba uhuku dania soi andrö, ba zi möi sawuyu ira, iŵa''ö Lowalangi; ba aefa da''ö ba aheta ira, ba lafosumange ndra''o ba danö andre."[6]', '["MozI 12:7","MozI 15:13 b.t.; MozII 12:40; Gal 3:17","MozII 3:12","MozI 17:10 b.t.; 21:2 b.t.; 25:26; 35:22 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 8, 'Ba no ibe''e khönia wawu''usa li famoto andrö, ba mo''ono ia, Iza''aki andrö, ba iboto, me no alua zi fitu bongi; ba si manö Giza''aki khö Yakobo ba Yakobo ba wurugö andrö, sifelendrua.[7]', '["MozI 12:7","MozI 15:13 b.t.; MozII 12:40; Gal 3:17","MozII 3:12","MozI 17:10 b.t.; 21:2 b.t.; 25:26; 35:22 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 9, 'Ba afökhö dödö wurugö andrö khö Yosefo, ba la''amawa ba danö Miserayi, ba itolo ia Lowalangi,[8]', '["MozI 37","MozI 39; 41:37 b.t.; Sin 105:21"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 10, 'ba i''efa''ö ba zamakao ya''ia fefu, ba ibe''e khönia wa''ebua dödö ba fa''atua-tua, föna Wara''o, razo Miserayi, ba ifataro kumandru ba danö Miserayi ia Fara''o, ba barö mbawania so zi samba omo ndra Fara''o.[9]', '["MozI 37","MozI 39; 41:37 b.t.; Sin 105:21"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 11, 'Ba so lofo ba danö Miserayi ma''asagörö, ba ba danö Gana''ana ma''asagörö, famakao sebua, ba lö lasöndra gö ira tuada.[10]', '["MozI 41:54 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 12, 'Ba me no irongo Yakobo, ba danö Miserayi so wakhe, ba ifatenge ndra tuada, si föföna andrö.[11]', '["MozI 42:1 b.t.","MozI 45:1; 4:16","MozI 45:9 b.t.; 46:27"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 13, 'Ba me lafuli möi dania, ba i''ombakha''ö ia Yosefo khö ndra talifusönia, ba terongo khö Wara''o dalifusö Yosefo andrö.[12]', '["MozI 42:1 b.t.","MozI 45:1; 4:16","MozI 45:9 b.t.; 46:27"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 14, 'Ba ifatenge Yosefo, ifakaoni''ö namania Yakobo, awö zoroiyomonia fefu fitu ngafulu a lima niha.[13]', '["MozI 42:1 b.t.","MozI 45:1; 4:16","MozI 45:9 b.t.; 46:27"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 15, 'Ba möi misi tou Yakobo, ba danö Miserayi, ba mate, ya''ia ba ira tuada.[14]', '["MozI 46:1; 49:33","MozI 50:13; 23:16,17"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 16, 'Ba la''ohe ira misi yaŵa, ba Zikhema, labe''e ba lewatö andrö, ni''öli Gaberahamo khö nono Hemori, ba Zikhema firö mböli.[15]', '["MozI 46:1; 49:33","MozI 50:13; 23:16,17"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 17, 'Ba itugu ahatö mbu''u li andrö, nifabu''u Lowalangi khö Gaberahamo, ba itugu tedou ira, tobali ato, ba danö Miserayi,[16]', '["MozII 1:7 b.t.","MozII 1:10,22; MozV 26:6"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 18, 'irege so razo bö''ö ba danö Miserayi, si lö mangila Yosefo.', '["MozII 1:7 b.t.","MozII 1:10,22; MozV 26:6"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 19, 'Da''ö zangonekhesi ba niwada, ifakao ndra tuada, ena''ö latibo''ö nonora, ena''ö böi la''orifi.[17]', '["MozII 1:7 b.t.","MozII 1:10,22; MozV 26:6"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 20, 'Me luo da''ö tumbu Mose, ba ono si sökhi ia wamaigi Lowalangi, ba tölu waŵa la''orifi ia ba nomo namania.[18]', '["MozII 2:2; Heb 11:23","MozII 2:5–10"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 21, 'Ba me no latibo''ö ia, ba ihalö ia ono Wara''o alawe, ba i''e''ebua, ononia.[19]', '["MozII 2:2; Heb 11:23","MozII 2:5–10"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 22, 'Ba tefahaö Moze ba ngawalö wa''atua-tua Ndrawa Miserayi fefu, ba abölö ia ba huhuo ba ba nifazökhi dangania.', '["MozII 2:2; Heb 11:23","MozII 2:5–10"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 23, 'Ba me no öfa wulu fakhe ia, ba itörö tödönia wamaigi iwara, Iraono Gizeraeli.[20]', '["MozII 2:11 b.t.","MozII 2:13"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 24, 'Ba me i''ila nifakao, ba zi lö börö, ba itolo, ilau mbalö nifalangögö andrö, ibunu Ndrawa Miserayi andrö.', '["MozII 2:11 b.t.","MozII 2:13"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 25, 'Ba iwai aboto ba dödö niwara, i''efa''ö ira tangania Lowalangi, ba lö aboto ba dödöra.', '["MozII 2:11 b.t.","MozII 2:13"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 26, 'Ba mahemolu ö, ba so ia, me fasoso ira, ba i''a''atulö ira ena''ö, afu labato, imane: Si fatalifusö ami, hana wa mifakao nawömi, ba zi lö börö?[21]', '["MozII 2:11 b.t.","MozII 2:13"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 27, 'Ba ituli''ö ia samalangögö awönia no mege, imane: Ha niha zamataro ya''ugö salaŵa ba sanguhuku, ba khöma?', '["MozII 2:11 b.t.","MozII 2:13"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 28, 'Hadia, öbunu göi ndra''o ena''ö, si mane famunumö Dawa Miserayi andrö, no menewi?', '["MozII 2:11 b.t.","MozII 2:13"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 29, 'Ba moloi Moze, ba niŵa''önia andrö, ba tobali si fatewu ia ba danö Midiano, mo''ono ia ba da''ö, ono matua, dombua.[22]', '["MozII 2:15 b.t.; 18:3,4"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 30, 'Ba me no irugi öfa wulu fakhe, ba i''oroma''ö ia khönia mala''ika, ba danö si mate ba gahe hili Zina''i, ba hola-hola galitö, ba ngafu ndroi.[23]', '["MozII 3:2 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 31, 'Ba me i''ila da''ö Moze ba ahöli-höli dödönia gangilata andrö. Ba me i''ondrasi, ba wamaigi, ba humede Zo''aya, imane:', '["Mat 22:32"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 32, '"Lowalangi ndra tuau ndra''odo, Lowalangi ndra Aberahamo, Iza''aki, Yakobo." Ba manizi-nizi Moze, ata''u ia ifaigi.[24]', '["Mat 22:32"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 33, 'Ba imane khönia So''aya: "Heta mbadagahe ba gaheu: tanö ni''amoni''ö sa danö andrö, ba zi so ndra''ugö.[25]', '["MozII 3:5; Yos 5:15","MozII 3:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 34, 'No ufaigi sibai wamakao banuagu andrö, si so ba danö Miserayi, ba fangarö-ngaröra ba no urongo, ba no möido tou mangefa''ö ya''ira, ba aine sa, da''ufatenge ndra''ugö ba danö Miserayi."[26]', '["MozII 3:5; Yos 5:15","MozII 3:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 35, 'Moze andrö, ni''ositengagöra, me lamane: Ha niha zamataro ya''ugö salaŵa ba sanguhuku? Da''ö nifatenge Lowalangi salaŵa ba sangefa''ö, nitolo tanga mala''ika, sangoroma''ö ya''ia khönia, ba ngafu ndroi andrö.[27]', '["MozII 3:19,20; Yes 63:9–12","MozII 7:10 b.t.; 14:21 b.t.; Sin 106:21 b.t.","MozV 18:15","MozII 19:3,20; MozV 32:47","MozII 16:3","MozII 32:1 b.t.","Hes 20:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 36, 'Da''ö zamawu''a ya''ira, wamazökhi ila-ila ba tandra, ba danö Miserayi ba ba nasi soyo ba ba danö si mate, öfa wulu fakhe wa''ara.[28]', '["MozII 3:19,20; Yes 63:9–12","MozII 7:10 b.t.; 14:21 b.t.; Sin 106:21 b.t.","MozV 18:15","MozII 19:3,20; MozV 32:47","MozII 16:3","MozII 32:1 b.t.","Hes 20:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 37, 'Da''ö Moze andrö, sanguma''ö ba Ndraono Gizeraeli: "I''asogö khömi Lowalangi zama''ele''ö, si mane ya''o, talifusömi."[29]', '["MozII 3:19,20; Yes 63:9–12","MozII 7:10 b.t.; 14:21 b.t.; Sin 106:21 b.t.","MozV 18:15","MozII 19:3,20; MozV 32:47","MozII 16:3","MozII 32:1 b.t.","Hes 20:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 38, 'Da''ö zi so ba walukhata andrö, ba danö si mate, awö mala''ika andrö, sihede khönia, ba hili Zina''i, ba awö ndra tuada, ya''ia zanema taroma li sauri, ba wama''ema khöda;[30]', '["MozII 3:19,20; Yes 63:9–12","MozII 7:10 b.t.; 14:21 b.t.; Sin 106:21 b.t.","MozV 18:15","MozII 19:3,20; MozV 32:47","MozII 16:3","MozII 32:1 b.t.","Hes 20:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 39, 'ya''ia zi lö edöna lafondrondrongo li ira tuada; latimba ia, ba lö aefa dödöra ba danö Miserayi,[31]', '["MozII 3:19,20; Yes 63:9–12","MozII 7:10 b.t.; 14:21 b.t.; Sin 106:21 b.t.","MozV 18:15","MozII 19:3,20; MozV 32:47","MozII 16:3","MozII 32:1 b.t.","Hes 20:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 40, 'wanguma''ö khö Ga''aroni: Fazökhi khöda Lowalangi, sowaö-waö fönada. Lö''ö sa ma''ila, hadia zi göna Moze andrö, sangeheta ya''aga ba danö Miserayi.[32]', '["MozII 3:19,20; Yes 63:9–12","MozII 7:10 b.t.; 14:21 b.t.; Sin 106:21 b.t.","MozV 18:15","MozII 19:3,20; MozV 32:47","MozII 16:3","MozII 32:1 b.t.","Hes 20:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 41, 'Ba lafazökhi nono zaŵi, me luo da''ö, ba labe''e zumange ba nadu andrö, ba omuso dödöra ba nifazökhi dangara andrö.[33]', '["MozII 3:19,20; Yes 63:9–12","MozII 7:10 b.t.; 14:21 b.t.; Sin 106:21 b.t.","MozV 18:15","MozII 19:3,20; MozV 32:47","MozII 16:3","MozII 32:1 b.t.","Hes 20:7 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 42, 'Ba i''erogö ira Lowalangi, ilulu ira, ena''ö lafosumange zabölö mbanua si yaŵa; si mane nisura ba zura zama''ele''ö: "Hadia, no mibe''e khögu zumange nitaba ba sumange bö''ö, si öfa wulu fakhe no, ba danö si mate, ya''ami Iraono Gizeraeli?[34]', '["Rom 1:24 b.t.; MozV 17:2 b.t.; Yer 7:23 b.t.; Amos 5:25 b.t.","SalI 11:7; SalII 17:6 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 43, 'Ba no mi''osa''ö nose Molokho andrö, awö ndröfi Lowalangi andrö, Refano, famaedo andrö, nifazökhimi, ba wangalulu khönia. Ba ufawu''a ami, ba zi tambai Mbabilona u''ohe ami."[35]', '["Rom 1:24 b.t.; MozV 17:2 b.t.; Yer 7:23 b.t.; Amos 5:25 b.t.","SalI 11:7; SalII 17:6 b.t."]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 44, 'No so khö ndra tuada nose wamaduhu''ö andrö, ba danö si mate; no la''o''ö niŵa''ö zihede khö Moze, wamazökhi ya''ia, la''o''ö wamaedo andrö ni''ilania.[36]', '["MozII 25:9,40; 26:30","Yos 3:14 b.t.; MozII 23:29 b.t.; 34:11","Faigi 13:22; SamI 16:12; Sin 132:5","SalI 6"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 45, 'La''ohe göi ba danö da''ö ira tuada, me no latema, awö Yosua, me lalaŵa niha baero andrö, nitimba Lowalangi föna ndra tuada, irugi luo so Dawido,[37]', '["MozII 25:9,40; 26:30","Yos 3:14 b.t.; MozII 23:29 b.t.; 34:11","Faigi 13:22; SamI 16:12; Sin 132:5","SalI 6"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 46, 'si falukha fa''ebua dödö Lowalangi. Ba i''andrö, ena''ö na isöndra naha khö Lowalangi Yakobo.[38]', '["MozII 25:9,40; 26:30","Yos 3:14 b.t.; MozII 23:29 b.t.; 34:11","Faigi 13:22; SamI 16:12; Sin 132:5","SalI 6"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 47, 'Ba Selomo zolau omo khönia.[39]', '["MozII 25:9,40; 26:30","Yos 3:14 b.t.; MozII 23:29 b.t.; 34:11","Faigi 13:22; SamI 16:12; Sin 132:5","SalI 6"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 48, 'Ba lö i''onahia Fondrege Zalaŵa nifazökhi tanga niha; imane sama''ele''ö:[40]', '["SalI 8:27 b.t.","Yes 66:1,2; Yer 23:24; Mat 5:34","MozV 9:24; 10:16; Yer 6:10; 9:26","Nga''ötII 36:16; Mat 23:31,37","MozII 20; Yoh 7:19; Heb 2:2; Gal 3:19"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 49, '"Dadaomagu zorugo ba dane-dane gahegu danö. Hadia nomo nilaumi khögu? iŵa''ö So''aya, ba hadia naha wolombase khögu.[41]', '["SalI 8:27 b.t.","Yes 66:1,2; Yer 23:24; Mat 5:34","MozV 9:24; 10:16; Yer 6:10; 9:26","Nga''ötII 36:16; Mat 23:31,37","MozII 20; Yoh 7:19; Heb 2:2; Gal 3:19"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 50, 'Tenga no tangagu zamazökhi da''e fefu?"', '["SalI 8:27 b.t.","Yes 66:1,2; Yer 23:24; Mat 5:34","MozV 9:24; 10:16; Yer 6:10; 9:26","Nga''ötII 36:16; Mat 23:31,37","MozII 20; Yoh 7:19; Heb 2:2; Gal 3:19"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 51, 'He ya''ami, sabe''e börö du''i, si lö muboto tödö ba tögi dalinga! Lö aetu mamadaö ami khö Geheha ni''amoni''ö, hulö si mane ira tuami, si manö göi ami.[42]', '["SalI 8:27 b.t.","Yes 66:1,2; Yer 23:24; Mat 5:34","MozV 9:24; 10:16; Yer 6:10; 9:26","Nga''ötII 36:16; Mat 23:31,37","MozII 20; Yoh 7:19; Heb 2:2; Gal 3:19"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 52, 'Hezo zama''ele''ö, si lö lagohi ira tuami? Ba no labunu zangöhönagö mangombakha fa''aso zatulö andrö, ni''ami böli iada''e, nibunumi,[43]', '["SalI 8:27 b.t.","Yes 66:1,2; Yer 23:24; Mat 5:34","MozV 9:24; 10:16; Yer 6:10; 9:26","Nga''ötII 36:16; Mat 23:31,37","MozII 20; Yoh 7:19; Heb 2:2; Gal 3:19"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 53, 'ya''ami, si no manema oroisa, nifa''ema mala''ika, ba si lö molo''ö ya''ia.[44]', '["SalI 8:27 b.t.","Yes 66:1,2; Yer 23:24; Mat 5:34","MozV 9:24; 10:16; Yer 6:10; 9:26","Nga''ötII 36:16; Mat 23:31,37","MozII 20; Yoh 7:19; Heb 2:2; Gal 3:19"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 54, 'Ba me larongo da''ö, ba afökhö sibai ba dödöra, ba lafatangi mbohara khönia.[45]', '["Faigi 5:33"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 55, 'Ba no fahöna khönia Geheha ni''amoni''ö, ba ifaöga hörönia ba zorugo, ba i''ila lakhömi Lowalangi, awö Yesu, si so ba gambölö Lowalangi,[46]', '["Faigi 6:5; Mat 26:64","FetI 3:22"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 56, 'ba imane: Hiza, teboka zorugo, u''ila ba so ba gambölö Lowalangi Nono Niha.[47]', '["Faigi 6:5; Mat 26:64","FetI 3:22"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 57, 'Ba mu''ao ira, ebua lira, laduhö dögi dalingara, lahurufai ia, ha sara dödö,', '[]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 58, 'ba latuli''ö baero mbanua, ba latebu kara.', '[]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 59, 'Ba latebu kara Zitefano, ba mangandrö ia, imane: He Yesu, So''aya, tema nosogu![49]', '["Sin 31:6; Luk 23:46"]', NULL),
  (3394261, 'NT', 'Halöŵö Zinenge', 7, 60, 'Ba ibalöduhini tou danö, mu''ao ia, ebua linia: He So''aya, be''e aefa khöra horö andre!', '["Sin 31:6; Luk 23:46"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 1, 'Ba tobali lagohi sibai mbanua Yesu ba Yeruzalema, me luo da''ö, ba oi lafazawili ira ba danö Yudaia ba ba danö Zamaria, ba lö fao zinenge.[1]', '["Faigi 7:58; 13:9; Mat 10:23","MozI 50:10","Faigi 9:1; 13:31; KorI 15:9"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 2, 'Ba lako''o Zitefano niha sangata''ufi Lowalangi, ba la''e''esi sibai ia.[2]', '["Faigi 7:58; 13:9; Mat 10:23","MozI 50:10","Faigi 9:1; 13:31; KorI 15:9"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 3, 'Ba ifufu mbanua Yesu Saulo andrö, itöröi nomo misa, isöbi ndra matua, awö ndra alawe, ifabe''e''ö ba gurunga.[3]', '["Faigi 7:58; 13:9; Mat 10:23","MozI 50:10","Faigi 9:1; 13:31; KorI 15:9"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 4, 'Ba ya''ira, si no muzaewe, ba latöröi danö, la''ombakha''ö daroma li somuso dödö.[4]', '["Faigi 11:19"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 5, 'Ba me irugi si tou mbanua Zamaria Filifo, ba i''ombakha''ö khöra Keriso.[5]', '["Faigi 6:5","Faigi 5:16"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 6, 'Ba ha sara dödö niha sato, wamondrongo niŵa''ö Wilifo, me larongo ba me la''ila dandra andrö, nifazökhinia.', '["Faigi 6:5","Faigi 5:16"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 7, 'Ato zaheta bekhu, si so bekhu si ra''iö, mu''ao ira, ebua li; ba ato zabe''e, si mate dambai, awö zombuyu-mbuyu töla.[6]', '["Faigi 6:5","Faigi 5:16"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 8, 'Ba tobali fa''omuso dödö sabölö-bölö ba mbanua andrö.', '["Faigi 6:5","Faigi 5:16"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 9, 'Ba no tohöna ba mbanua andrö niha, sebua elemu, Simoni döinia, ba tobali dödö Ndrawa Zamaria ibe''e, sebua ia iŵa''ö.[7]', '["Faigi 13:6,8"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 10, 'Khönia lafaigi fefu, he iraono, ba he satua, lamane: Da''ö wa''abölö Lowalangi, niŵa''ö sebua ia.', '["Faigi 13:6,8"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 11, 'Ba lafaigi-faigi khönia, me no ara ahöli-höli dödöra ibe''e, ba wakelemusania andrö.', '["Faigi 13:6,8"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 12, 'Ba me mamati ira khö Wilifo, sangombakha turia mbanua Lowalangi ba turia döi Yesu Keriso, somuso dödö, ba lafabayagö''ö idanö ira, ira matua ba ira alawe.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 13, 'Ba Simoni andrö göi, ba mamati, ba me no tebayagö idanö ia, ba lö iröi-röi Wilifo, ba i''ila dandra andrö, awö wa''abölö andrö, ba tobali dödönia.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 14, 'Ba me larongo sinenge ba Yeruzalema, la''o''ö li Lowalangi, ba Zamaria, ba lafatenge khöra Wetero ba Yohane.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 15, 'Ba me larugi si tou, ba mangandrö ira, ba khöra andrö, ena''ö tebe''e khöra Geheha ni''amoni''ö.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 16, 'Lö''ö manö na si möi ia khöra, samösa lö sanema, ha fa no tebayagö idanö ira, ba döi Yesu So''aya.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 17, 'Awena latufa högöra tanga, ba latema Geheha ni''amoni''ö.[8]', '["Faigi 6:6"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 18, 'Ba me i''ila Simoni, tebe''e Geheha, na latufa ira tanga sinenge, ba i''ohe khöra gana''a,', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 19, 'imane: Mibe''e khögu göi wa''abölö andrö, ena''ö na itema Geheha ni''amoni''ö nitufagu tanga.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 20, 'Imane khönia Fetero: Yamöi ba wa''atekiko gana''au, awö ndra''ugö! me öwai ana''a mböli mbuala Lowalangi andrö![9]', '["Mat 10:8","Neh 2:20","MozV 29:18"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 21, 'Lö urakhau ba lö sinemau ba daroma li andrö; lö''ö sa atulö dödöu föna Lowalangi.[10]', '["Mat 10:8","Neh 2:20","MozV 29:18"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 22, 'Andrö falalini gera-erau, erogö golalöŵau andrö, ba andrö khö Zo''aya, ma atö i''efa''ö khöu gera-era dödöu, si lö sökhi andrö.', '["Mat 10:8","Neh 2:20","MozV 29:18"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 23, 'Oroma sa khögu, wa no fahöna ba dödöu gawökhu safeto, ba no iböbö ndra''ugö si lö atulö.[11]', '["Mat 10:8","Neh 2:20","MozV 29:18"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 24, 'Ba itema linia Simoni, imane: Mi''andrö khö Zo''aya, salahigu, ena''ö lö itörö ndra''o niŵa''ömi andrö fefu.[12]', '["MozII 10:17; FamI 12:19"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 25, 'Ba ya''ira, me no lafaduhu''ö li Zo''aya, me no la''ombakha''ö, ba lafuli ira ba Yeruzalema, ba la''oya''ö banua Ndrawa Zamaria, wanuriagö turia somuso dödö.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 26, 'Ba muhede mala''ika Zo''aya khö Wilifo, imane: Faoso, ae miraya, ba lala andrö, si otarai Yeruzalema, saekhu ba Gasa, sanörö tanö si mate.', '[]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 27, 'Ba maoso ia, möi ia.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 28, 'Ba mangawuli ia, dumadao ia ba guretania, mamaso sura Yesaya, sama''ele''ö andrö.', '["SalI 8:41; Sef 3:10; Yoh 12:20"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 29, 'Ba imane Eheha khö Wilifo: Ondrasi gureta andrö, ba böi röi-röi ia.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 30, 'Ba fagohi Wilifo, i''ondrasi ba irongo, mamaso sura Yesaya, sama''ele''ö, niha andrö, ba imane: Hadia, aboto göi ba dödöu nibasomö?', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 31, 'Ba imane: He uwisa sa, na lö samobawa lala khögu? Ba i''andrö khö Wilifo, möi ia yaŵa mudadao ba ngainia.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 32, 'Ba si mane ba zura andrö, nibasonia: "Hulö mibiri-biri te''ohe ia ba wanaba ya''ia, ba hulö nono mbiri-biri, si lö hede-hede ba danga zoguti bunia, si manö göi wa lö hede-hedenia.[14]', '["Yes 53:7,8"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 33, 'Ba wa''ide-idenia te''etu''ö wanguhuku ya''ia; ha niha zanutunö nga''ötönia? teheta sa ba guli danö nosonia."', '["Yes 53:7,8"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 34, 'Ba itema li mandru andrö, imane khö Wilifo: u''andrö khöu, ha niha nitörö li zama''ele''ö andrö, wanguma''ö da''ö? hadia, ya''ia, hadia niha bö''ö?', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 35, 'Ba muhede Wilifo, i''otarai zura da''ö, ituriagö khönia duria somuso dödö andrö, khö Yesu.[15]', '["KorI 15:3 b.t."]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 36, 'Ba me latörö lala, ba larugi nidanö, ba imane mandru andrö: Hiza nidanö! Hadia wanenaŵa, na tebayagö idanö ndra''o?[16]', '["Faigi 10:47"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 37, 'Ba imane Filifo: Na ahori dödöu wamati, ba tola.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 38, 'Ba iŵa''ö labadugö gureta, ba möi ira tou, ba nidanö, darua ira, Filifo mandru andrö, ba ibayagö idanö ia Filifo.', '[]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 39, 'Ba me no möi ira miyaŵa moroi ba nidanö, ba iheta Wilifo Eheha Zo''aya, ba lö''ö sa''ae i''ila ia mandru andrö; omuso sa dödönia, ba wanörö lalania.[18]', '["SalI 18:12"]', NULL),
  (3394262, 'NT', 'Halöŵö Zinenge', 8, 40, 'Ba ba Gasoto tesöndra Wilifo, ba itöröi danö wanuriagö turia somuso dödö andrö, idozigö banua, irugi Kaizaria.[19]', '["Faigi 21:8,9"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 1, 'Ba lö''ö na tebato wa''omasi Zaulo, ifeta''u nifahaö Zo''aya ba ibunu; möi ia khö ndra ere sebua,[1]', '["Faigi 8:3","Ayati 2—9: Faigi 22:4—10; 26:9—18"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 2, 'i''andrö khönia zura,[2] nibe''e ba Ndramaseko ba zekola, ena''ö iböbö na falukha ia zolo''ö huku da''ö, ira matua ba ira alawe, ba i''ohe ba Yeruzalema.', '["Faigi 8:3","Ayati 2—9: Faigi 22:4—10; 26:9—18"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 3, 'Ba ba wofanö, me ahatö ia ba Ndramaseko, ba i''ozumagö ifasui ia haga, moroi si yaŵa ba mbanua.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 4, 'Ba alau tou ia ba danö, ba irongo li, imane khönia:', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 5, 'Ba imane: He So''aya, ha niha ndra''ugö?', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 6, 'Ba faoso ba ae ba mbanua andrö, ba laŵa''ö khöu he öwisa.[5]', '["KorI 15:8","Faigi 2:37"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 7, 'Ba labadugö ira niha andrö, awönia ba lala, lö hede-hede; larongo sa li andrö, ba lö oroma khöra niha.[6]', '["Faigi 22:9"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 8, 'Ba maoso Zaulo moroi ba danö, ba me ifehaga ia, ba lö i''ila hadia ia; ba la''ohe dangania, lafasao ia ba Ndramaseko.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 9, 'Ba tölu bongi lö i''ila niha, lö manga ia ba lö ibadu nidanö.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 10, 'Ba so ba Ndramaseko nifahaö,[7] Anania döinia, ba imane ba da''ö So''aya, ba gangilata: He Anania! Ba imane: ya''e ndra''o, Tua!', '["Ayati 10—19: Faigi 22:12—16)"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 11, 'Ba imane khönia So''aya: Faoso, ae ba newali andrö, nifotöi "sadölö" ba sofu zotöi Saulo andrö, banua Dareso, ba nomo Yuda. Hiza sa, mangandrö ia,[8]', '["Faigi 21:39"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 12, 'ba no i''ila niha, sotöi Anania, si möi khönia yomo, sanufa högönia tanga, ena''ö ifuli i''ila niha.', '["Faigi 21:39"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 13, 'Ba itema linia Anania, imane: He Tua, no ato zangombakha niha andrö, nirongogu, i''abölögö wamakao ni''amoni''ö andrö khöu, ba Yeruzalema, laŵa''ö.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 14, 'Ba ba da''e, ba no latehe khönia ere sebua, tola iböbö dozi si angaröfi li töimö.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 15, 'Ba imane khönia So''aya: Ae''e, me no fakake nituyu da''ö khögu, ba wolohe ba niha baero töigu ba ba zalaŵa ba ba Ndraono Gizeraeli.[9]', '["Faigi 3:2; 22:21; 26:2; 27:24; Rom 1:1,5; TimI 2:7","Faigi 20:23; KorII 11:23 b.t.; TimII 3:11"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 16, 'u''oroma''ö sa khönia, ha wa''oya zi lö tola lö göna ia famakao, börö döigu andrö.[10]', '["Faigi 3:2; 22:21; 26:2; 27:24; Rom 1:1,5; TimI 2:7","Faigi 20:23; KorII 11:23 b.t.; TimII 3:11"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 17, 'Ba möi Ganania, möi ia yomo ba nomo andrö, itufa högö Zaulo tangania, imane: He talifusögu Saulo, So''aya zamatenge ya''o, Yesu, sangoroma''ö ya''ia khöu, ba lala nitöröu, ena''ö ifuli ö''ila niha, ba ena''ö tehöna khöu Geheha ni''amoni''ö.[11]', '["Faigi 8:17"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 18, 'Ba i''anema''ö abo''a ba hörönia zi hulö huna-huna, ba ifuli i''ila niha; ba maoso ia, ifabayagö''ö idanö ia, ba i''a gönia, fangabe''enia.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 19, 'Ba so ia ma''ifu ba da''ö ba Ndramaseko, awö ndra nifahaö.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 20, 'Ba i''anema''ö i''ombakha''ö Keriso, ba zekola, wa ono Lowalangi da''ö.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 21, 'Ba tobali dödö dozi samondrongo da''ö, ba lamane: Tenga da''ö zamakiko no, ba Yeruzalema si angaröfi li töi andrö, ba si möi ba da''e, ba wamöbö ya''ira ba ba wolohe ya''ira khö ndra ere sebua?[12]', '["Gal 1:13"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 22, 'Ba itugu abölö na Zaulo, fawuka dödö niha Yehuda, si fatewu ba Ndramaseko, ibe''e, wama''ele''ö, wa Keriso Yesu.[13]', '["Faigi 18:28; Yoh 4:42"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 23, 'Ba me no ara ma''ifu, ba mamagölö niha Yehuda, ba wamunu ya''ia.[14]', '["Faigi 23:12"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 24, 'Ba irongo Saulo dödöra andrö.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 25, 'Ba latolo ia nifahaönia ba zi bongi, ladada baero göli, ba raga-raga.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 26, 'Ba me no irugi Yeruzalema, ba itandraigö ifaogö ia khö ndra nifahaö, ba a''oi ata''u ira, lö faduhu dödöra, wa no nifahaö ia.[16]', '["Gal 1:18 b.t."]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 27, 'Ba itolo ia Baranaba, i''ohe khö ndra sinenge, idunö-dunö khöra, he wisa wangilania So''aya ba lala, awö wa no muhede khönia, ba he wisa wamahaönia, wangombakha töi Yesu, ba Ndramaseko, wa lö aiŵö ia.[17]', '["Faigi 4:36"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 28, 'Ba fao-fao ia khöra, ba Yeruzalema, heza möi ira, ba lö aiŵö ia, wamahaö, wangombakha töi Zo''aya.[18]', '["Faigi 22:17 b.t."]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 29, 'Ba muhede ia göi ba Ndrawa Heleni, fahuhuo ira, ba ya''ira, ba la''alui wamunu ya''ia.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 30, 'Ba me larongo da''ö talifusö, ba la''ohe ia misi tou ba Kaizaria, ba lafatenge ba Dareso.[19]', '["Faigi 11:25"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 31, 'Ba ohahau dödö mbanua Yesu, ba danö Yudaia ma''asagörö, awö ba Zamaria, itugu aro ira, ba latörö lala Zo''aya, la''ata''ufi ia, ba fahöna khöra wondrara dödö khö Geheha ni''amoni''ö.[20]', '["Yud 20; Yoh 14:16"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 32, 'Ba me itöröi ira Fetero, ba tobali irugi göi si tou, ni''amoni''ö, banua Lida.[21]', '["Faigi 8:14"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 33, 'Ba falukha ia ba da''ö niha, Ainea döinia, si no meŵalu fakhe fa''ara tou ba zalo manö, si mate dambai.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 34, 'Ba imane khönia Fetero: He Ainea! Ifadöhö wökhöu Yesu Keriso; faoso, ba ya''ugö mamazökhi naha wemörö khöu.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 35, 'Ba oi la''ila ia banua Lida fefu ba banua Zarona, ba la''o''ö khö Zo''aya.[23]', '["Yes 35:2"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 36, 'Ba so ba Yofe nifahaö, ira alawe, Tabita döinia, Doreka (nago), na la''ali, si no fahöna bua-bua si sökhi, ba oya ibe''e ame''ela ba zi numana.[24]', '["Faigi 10:2"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 37, 'Ba tobali, me luo da''ö, ba mofökhö ia ba mate. Ba lafemondri ia, ba labe''e ba mbate''e ba zi sagötö.', '["Faigi 10:2"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 38, 'Ba me no ahatö ba Yofe Lida andrö, ba me no larongo ira nifahaö, so ba da''ö Wetero, ba lafatenge khönia niha, darua, sangandrö khönia: Böi aragö we''amöi khöma.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 39, 'Ba maoso Wetero, möi ia awöra.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 40, 'Ba ifofanö ira baero fefu Fetero, ibalöduhini tou zalo, mangandrö; ba ibali''ö ia ba mboto zi mate andrö, imane: Faoso, Tabita!', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 41, 'Ba i''oro''ö khönia danga, ifazizio.', '[]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 42, 'Ba terongo ba mbanua Yofe, fefu, ba ato zamati khö Zo''aya.[26]', '["Yoh 10:42"]', NULL),
  (3394264, 'NT', 'Halöŵö Zinenge', 9, 43, 'Ba ara Wetero ba Yofe, tome Zimoni tuka guli zaŵi.', '["Yoh 10:42"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 1, 'Ba so ba Kaizaria niha, Konelio döinia, kumandra zaradadu Gitalia andrö;[1]', '["Mat 8:5","Sin 112:9; Luk 7:5"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 2, 'niha satulö tödö, sangata''ufi Lowalangi, awö zoroiyomonia fefu; oya ibe''e ba zi numana ame''ela, ba si lö mamalö-malö wangandrönia khö Lowalangi.[2]', '["Mat 8:5","Sin 112:9; Luk 7:5"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 3, 'Ba i''ila ba gangilata, oroma sibai, mala''ika Lowalangi, si möi yomo khönia, so labözi tölu, imane khönia:', '["Mat 8:5","Sin 112:9; Luk 7:5"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 4, 'Ba itöngö, ata''u ia, imane: Hadia da''ö, Tua?', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 5, 'Ba iada''e, ba fatenge niha ba Yofe, ba fakaoni''ö Zimoni andrö,', '["Luk 1:12,29; Sin 141:2","Faigi 9:43; 11:14"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 6, 'nifotöi Fetero; no möi ia tome khö Zimoni andrö, tuka guli zaŵi, ba mbewe nasi so nomonia.[5]', '["Luk 1:12,29; Sin 141:2","Faigi 9:43; 11:14"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 7, 'Ba me no mofanö mala''ika andrö, sihede khönia, ba humede ia ba zawuyunia, darua, ba ba zaradadu samösa, sangata''ufi Lowalangi,', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 8, 'ngoni-ngoninia, ba me no idunö-dunö khöra fefu hadia ia, ba ifatenge ira ba Yofe.', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 9, 'Ba sara wongi, me so ira ba lala, me ahatö sa''ae ira ba mbanua, ba möi yaŵa Wetero ba zi sagötö, mangandrö, so laluo.[6]', '["Dan 6:10"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 10, 'Ba olofo ia, omasi ia manga.', '["Dan 6:10"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 11, 'Ba i''ila, teboka mbanua si yaŵa, ba numalö mitou nahia, hulö lembe sebolo, nifotaŵi-taŵi fatalinga si öfa, wanada ya''ia ba guli danö.', '["Faigi 11:5 b.t.; 22:17"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 12, 'So bakha fefu ngawalö zaliŵa-liŵa ba danö, si öfa ahe, ba fefu ngawalö guö-kuö ba danö, ba fefu ngawalö wofo ba dalu mbanua.', '["Faigi 11:5 b.t.; 22:17"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 13, 'Ba so zihede khönia, imane: Faoso, Fetero, taba ba a!', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 14, 'Ba imane Fetero: Ai, tebai Tua, me lö urai u''a zi lö sökhi, awö zi ra''iö.[8]', '["MozIII 11:4 b.t."]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 15, 'Ba imane zui khönia sihede andrö: Böi bali si lö sökhi nihaogö Lowalangi.[9]', '["Mat 15:11; TimI 4:5"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 16, 'Ba medölu zi manö, ba i''anema''ö tedöni miyaŵa ba mbanua si yaŵa nahia andrö.', '["Mat 15:11; TimI 4:5"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 17, 'Ba me ibusi tödö Fetero, hadia gangilata andrö, ni''ilania, ba hiza, ba no so tou niha andrö, nifatenge Konelio, no lasofu nomo Zimoni.', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 18, 'Ba mu''ao ira, lasofu, na so ba da''ö tome Zimoni, nifotöi Fetero.', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 19, 'Ba me ifatou-tou na tödönia Fetero gangilata andrö, ba imane Eheha khönia: Hiza niha, sangalui ya''ugö,[10]', '["Faigi 8:29","Faigi 15:7"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 20, 'ba faoso, ae tou, ba ae awöra, böi manufa dödöu, me no ya''o zamatenge ya''ira.[11]', '["Faigi 8:29","Faigi 15:7"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 21, 'Ba möi tou Wetero, i''ondrasi niha andrö, imane: Hiza, ya''odo ni''aluimi. Hadia mbörö, wa so ami?', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 22, 'Ba lamane: Konelio andrö, kumandra, niha satulö tödö, sangata''ufi Lowalangi, si sökhi turia göi ba niha Yehuda fefu; no ifaŵa''ögö khönia Lowalangi ba mala''ika ni''amoni''ö, ifakaoni''ö ndra''ugö ba nomonia, ba wamondrondrongo niŵa''öu.', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 23, 'Ba i''ohe ira yomo, ibe''e göra. Ba sara wongi, ba möi ia, fao ia khöra: ba möi awönia dalifusö ösa, banua Yofe.[12]', '["Faigi 11:12"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 24, 'Ba mahemolu ö, ba larugi Kaizaria. Ba no ibalo-baloi ira Konelio, no ikaoni zahatö khönia, awö zabölö fahuwu khönia.', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 25, 'Ba me möi yomo Wetero, ba ifaondragö ia Konelio, ituhi danö fönania, mangalulu.', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 26, 'Ba ifaoso Fetero, imane: Faoso! niha göi ndra''odo.[13]', '["Faigi 14:15; Fam 19:10; 22:8,9"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 27, 'Ba fahuhuo ira, möi ira yomo, ba i''ila zato, si no so ba da''ö, Fetero.', '[]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 28, 'Ba imane khöra: Mi''ila, lö tola ba niha Yehuda, orudu ia ba niha bö''ö, ba lö tola möi ia khöra; ba khögu, ba no i''oroma''ö Lowalangi, böi uŵa''ö, si lö sökhi, ba ma si ra''iö niha, gofu ha niha ia.[14]', '["Faigi 11:3; Yoh 18:28"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 29, 'Andrö göi lö ufadaö we''amöi, me lafakaoni''ö ndra''odo. Usofu iada''e, hadia mbörö, wa no mifakaoni''ö ndra''o?', '["Faigi 11:3; Yoh 18:28"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 30, 'Ba imane Konelio: öfa bongi ma''ökhö, me mangandrö ndra''o, yomo ba da''e khögu, me labözi tölu, ba hiza niha, si so fönagu, sobaru sihaga,[15]', '["Faigi 1:10"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 31, 'ba imane: He Konelio! No tefondrondrongo wangandröu ba no itörö tödö Lowalangi game''elamö andrö.', '["Faigi 1:10"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 32, 'Andrö fatenge ba Yofe, ba fakaoni''ö Zimoni andrö, nifotöi Fetero; no möi ia tome ba nomo Zimoni, tuka guli zaŵi, ba mbewe nasi.', '["Faigi 1:10"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 33, 'Ba u''anema''ö ufatenge khöu, ba sökhi me no so ndra''ugö. Ba no soga fefu iada''e, föna Lowalangi, ba wamondrondrongo fefu niŵa''ö Zo''aya khöu.', '["Faigi 1:10"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 34, 'Ba humede Wetero, imane: Awena si ndruhu aboto ba dödögu, lö ifaigi mbawa niha Lowalangi,[16]', '["MozV 10:17; SamI 16:7","Faigi 2:39; 15:9; Yes 56:6,7","Faigi 13:26,46; Yes 52:7; Efes 2:14 b.t.; Fil 1:11"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 35, 'dozi sa, ha soi ira, sangata''ufi ya''ia, solau satulö, da''ö zomasi ia.[17]', '["MozV 10:17; SamI 16:7","Faigi 2:39; 15:9; Yes 56:6,7","Faigi 13:26,46; Yes 52:7; Efes 2:14 b.t.; Fil 1:11"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 36, 'Da''ö daroma li andrö, nifa''ohe''önia ba Ndraono Gizeraeli, wamaturiagö''ö fa''ohahau dödö khö Yesu Keriso, no da''ö Zo''aya niha fefu.[18]', '["MozV 10:17; SamI 16:7","Faigi 2:39; 15:9; Yes 56:6,7","Faigi 13:26,46; Yes 52:7; Efes 2:14 b.t.; Fil 1:11"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 37, 'No mirongo duria andrö, ba danö Yudaia ma''asagörö, si börögö ba Galilaia, me no aefa wamayagö idanö andrö, ni''ombakha''ö Yohane;[19]', '["Mat 4:12 b.t.; Mar 1:1 b.t.","Faigi 2:22; Luk 4:14,18; Mat 9:35; Yoh 3:2"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 38, 'Yesu andrö, banua Nazareta, fombayoini Lowalangi ya''ia, Eheha ni''amoni''ö ba fa''abölö, sanöröi tanö, wanolo niha ba famadöhö fökhö nifakao Gafökha fefu, me no itolo ia Lowalangi.[20]', '["Mat 4:12 b.t.; Mar 1:1 b.t.","Faigi 2:22; Luk 4:14,18; Mat 9:35; Yoh 3:2"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 39, 'Ba ya''aga zi so ba mbörö ba nilaunia fefu, he ba danö niha Yehuda, ba he ba Yeruzalema, ba no lataŵi ia ba döla geu, no labunu.[21]', '["Faigi 1:8; 2:23; 3:15; Luk 23:33; FetI 2:24","Mat 28:6","Faigi 13:31; Yoh 15:27; Luk 24:43; Mat 26:29"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 40, 'Da''ö nisusugi Lowalangi, me no aefa zi dua wongi, ba no ibe''e oroma ia,[22]', '["Faigi 1:8; 2:23; 3:15; Luk 23:33; FetI 2:24","Mat 28:6","Faigi 13:31; Yoh 15:27; Luk 24:43; Mat 26:29"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 41, 'tenga ba niha sato, ha ba zamaduhu''ö andrö, nihönagö Lowalangi wanutuyu ya''ira, khöma, si no orudu manga khönia, zi no mamadu idanö awönia, me no aefa maoso ia moroi ba ngai zi mate.[23]', '["Faigi 1:8; 2:23; 3:15; Luk 23:33; FetI 2:24","Mat 28:6","Faigi 13:31; Yoh 15:27; Luk 24:43; Mat 26:29"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 42, 'Ba no iŵa''ö khöma wangombakha ba niha andre ba famaduhu''ö, wa da''ö nihonogöi Lowalangi sanguhuku niha sauri awö zi no mate.[24]', '["Faigi 17:31; Yoh 5:22","Faigi 4:12; Yes 53:11; Yer 31:34; Dan 9:24; Rom 3:21 b.t."]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 43, 'Ya''ia nifaduhu''ö zama''ele''ö, fefu, wa ba döinia lasöndra wameta horö dozi si faduhu tödö khönia.[25]', '["Faigi 17:31; Yoh 5:22","Faigi 4:12; Yes 53:11; Yer 31:34; Dan 9:24; Rom 3:21 b.t."]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 44, 'Ba lö''ö na saetu wehede andrö, ba aekhu Geheha ni''amoni''ö ba zamondrongo taroma li andrö fefu,[26]', '["Faigi 11:15"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 45, 'Ba tobali dödö zamati niboto, fefu, ha wa''ato ira, zi no fao khö Wetero, we''amöi, me telau göi ba niha baero game''ela andrö, Eheha ni''amoni''ö.[27]', '["Faigi 2:17,38"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 46, 'Larongo sa''ae, molau li bö''ö ira ba lasuno Lowalangi.', '["Faigi 2:17,38"]', NULL),
  (3394266, 'NT', 'Halöŵö Zinenge', 10, 47, 'Ba iŵa''ö khöra lafabayagö''ö idanö ira, ba döi Yesu Keriso. Ba la''andrö khönia, ena''ö i''aragö ia ma''ifu khöra.', '["Faigi 2:4; 19:6"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 1, 'Ba larongo sinenge ba talifusö, ba Yudaia misa, la''o''ö göi li Lowalangi niha baero.[1]', '["Faigi 10:44 b.t.; Efes 3:1 b.t."]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 2, 'Ba me so moroi si tou Wetero, me möi ba Yeruzalema,', '["Faigi 10:28"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 3, 'ba lategu ia niboto, lamane: No möi''ö ba niha si lö muboto, no orudu manga ndra''ugö khöra.[2]', '["Faigi 10:28"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 4, 'Ba ibörötaigö Fetero, izara-zara wanutunö khöra, imane:', '["Faigi 10:9 b.t."]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 5, 'Sodo ba Yofe, mangandrö ndra''o; ba u''ila, me abeta nosogu, gangilata, nahia silalö mitou, hulö lembe sebolo, nifotaŵi-taŵi fatalinga si öfa, wanada ya''ia moroi ba mbanua si yaŵa, ba irugi ndra''odo.[3]', '["Faigi 10:9 b.t."]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 6, 'Ba utöngö, ufaigi-faigi, ba u''ila bakha zaliŵa-liŵa ba danö, si öfa ahe, awö gutu ndru''u si fara''u ba kuö-kuö ba fofo ba dalu mbanua.', '["Faigi 10:9 b.t."]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 7, 'Ba urongo göi li, imane khögu: Faoso Fetero, taba ba a!', '["Faigi 10:9 b.t."]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 8, 'Ba umane: Ai tebai, Tua, me lö irai itörö mbawagu si lö sökhi ba si ra''iö.', '["Faigi 10:9 b.t."]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 9, 'Ba itema zui ligu sihede andrö, moroi ba mbanua si yaŵa, imane: Böi bali si lö sökhi nihaogö Lowalangi.', '["Faigi 10:9 b.t."]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 10, 'Ba medölu zi manö, ba tedöni zui miyaŵa, ba mbanua si yaŵa, fefu.', '["Faigi 10:9 b.t."]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 11, 'Ba hiza, ba da''ö sibai so baolayama nomo andrö, ba zi soga, niha andrö, nifatenge khögu, moroi ba Kaizaria.', '["Faigi 10:23"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 12, 'Ba iŵa''ö khögu Eheha, möido awöra, böi manufa dödögu. Ba möi göi awögu dalifusö, si daönö andre, ba möiga yomo ba nomo niha andrö.[4]', '["Faigi 10:23"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 13, 'Ba i''ombakha''ö khöma, he wisa wangilania mala''ika andrö, yomo khönia, sanguma''ö: Fatenge ba Yofe, ba fakaoni''ö Zimoni andrö, nifotöi Fetero,', '["Faigi 10:6; 16:30,31"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 14, 'da''ö zanguma''ö khöu taroma li, fangorifiu, ba fangorifi zoroiyomou fefu.[5]', '["Faigi 10:6; 16:30,31"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 15, 'Ba me ubörötaigö fahuhuo, ba aekhu Geheha ni''amoni''ö ba khöra, si mane ba khöda göi, ba mböröta.[6]', '["Faigi 10:44","Faigi 1:5","Faigi 17:47"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 16, 'Ba itörö tödögu niŵa''ö Zo''aya, me imane: "Idanö nibayagö Yohane, ba ya''ami, ba nibayagö Eheha ni''amoni''ö."[7]', '["Faigi 10:44","Faigi 1:5","Faigi 17:47"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 17, 'Ba na faoma game''ela, nibe''e Lowalangi khöra nibe''enia khöda, samati khö Zo''aya ya''ita, Yesu Keriso, ba ha niha ndra''o? Hadia tola utenaŵa Lowalangi?[8]', '["Faigi 10:44","Faigi 1:5","Faigi 17:47"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 18, 'Ba me larongo da''ö, ba lö hede-hedera, ba lasuno Lowalangi, lamane: Ba noa sa ibe''e ba niha baero göi Lowalangi wamalalini era-era ba wangorifi.[9]', '["Faigi 5:31"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 19, 'Ba latöröi danö si no musaewe andrö, moroi ba wamakao andrö, si no tesao ba khö Zitefano, irugi danö Wönikia ba Kifero ba Andriokhia, ba lö la''ombakha''ö daroma li Loŵalangi, gofu ha khö, ha ba niha Yehuda.[10]', '["Faigi 8:1,4","Faigi 8:35","Faigi 2:47"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 20, 'Ba so ösa ba khöra, Dawa Gifero ba banua Girene, da''ö zangombakha ba Ndrawa Heleni göi, me larugi Gandriokhia, laturiagö khöra Yesu, So''aya.[11]', '["Faigi 8:1,4","Faigi 8:35","Faigi 2:47"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 21, 'Ba itolo ira tanga Zo''aya, ba ato zi faduhu tödö, la''o''ö khö Zo''aya.[12]', '["Faigi 8:1,4","Faigi 8:35","Faigi 2:47"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 22, 'Ba terongo duria andrö khöra, ba dögi dalinga mbanua Yesu ba Yeruzalema, ba lafatenge Mbaranaba, ba Gandriokhia.[13]', '["Faigi 9:27","Faigi 13:43","Faigi 6:5"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 23, 'Ba me irugi, me i''ila wa''ebua dödö Lowalangi andrö, ba omuso dödönia, ba ifarou dödöra fefu, ena''ö na la''aro''ö dödö wangiagö khö Zo''aya,[14]', '["Faigi 9:27","Faigi 13:43","Faigi 6:5"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 24, 'me no niha si sökhi ia ba me no fahöna khönia Geheha ni''amoni''ö, awö wamati. Ba ato niha si tefaböbö khö Zo''aya.[15]', '["Faigi 9:27","Faigi 13:43","Faigi 6:5"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 25, 'Ba möi ia ba Dareso, ba wangalui Saulo andrö, ba me no isöndra, ba i''ohe ba Gandriokhia.[16]', '["Gal 2:11 b.t.","Faigi 26:28; FetI 4:16"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 26, 'Ba tobali döfi wa''ara falukha-lukha ira ba mbanua andrö, ba ato nifahaöra niha, ba ba Gandriokhia mböröta, wa labe''e töi nifahaö niha Keriso.[17]', '["Gal 2:11 b.t.","Faigi 26:28; FetI 4:16"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 27, 'Ba me luo da''ö, ba möi misi tou ba Gandriokhia zama''ele''ö moroi ba Yeruzalema.[18]', '["Faigi 13:1; Efes 4:11","Faigi 21:10","Rom 15:25,26","Faigi 12:25"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 28, 'Ba maoso zi samösa da''ö, Agabo döinia, ifa''ele''ö moroi ba Geheha lofo sebua, si so dania ba guli danö ma''asagörö; salua me luo Kaizaro Kalaudio.[19]', '["Faigi 13:1; Efes 4:11","Faigi 21:10","Rom 15:25,26","Faigi 12:25"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 29, 'Ba lahonogöi ira nifahaö fefu, lafa''ohe''ö dolo-tolo ba dalifusö ba Yudaia, ebua labe''e sebua ana''a.[20]', '["Faigi 13:1; Efes 4:11","Faigi 21:10","Rom 15:25,26","Faigi 12:25"]', NULL),
  (3394268, 'NT', 'Halöŵö Zinenge', 11, 30, 'Ba alua göi lafa''ohe''ö khö zatua, Baranaba ba Saulo zolohe.[21]', '["Faigi 13:1; Efes 4:11","Faigi 21:10","Rom 15:25,26","Faigi 12:25"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 1, 'Me luo da''ö ibabaya ösa, mbanua Yesu, razo, Herode, ba wamakao ya''ira.[1]', '["Faigi 4:3; Luk 21:12","Mat 4:21"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 2, 'Ba ibunu si''öli Yakobo, talifusö Yakobo.[2]', '["Faigi 4:3; Luk 21:12","Mat 4:21"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 3, 'Ba me i''ila omasi niha Yehuda, ba itohugö, ifara''u''ö Wetero göi (Ba baŵa roti si lö mu''aisöni).[3]', '["Mar 14:1"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 4, 'Ba me no ifara''u''ö, ba ifabe''e''ö ba gurunga, ibe''e ba danga zaradadu si mendröfa wa daöfa, ba wanaro ya''ia, edöna ifa''ele''ö ba niha sato, na aefa wasa.', '["Mar 14:1"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 5, 'Ba latarogö sa''ae Wetero ba gurunga.', '["Mar 14:1"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 6, 'Ba me ifa''ele''ö ena''ö Herode, ba ba gotalua zaradadu si darua mörö Wetero, ba zi bongi andrö, dua rozi rate mbilagunia, ba so zanaro ba ngai mbawandruhö gurunga.', '[]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 7, 'Ba hiza, so mala''ika Zo''aya, ba so haga, sihaga ba mbate''e andrö. Ba ibözi ngai Wetero, isusugi, imane: Faoso, aliogö! Ba atoru mbilagu ba dangania.[5]', '["Faigi 5:19; 27:23"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 8, 'Ba imane khönia mala''ika andrö: Amöbö talu ba amadagahe mbadagahemö! Ba i''o''ö da''ö. Ba imane khönia: Amaru mbarumö sebua, ba o''ö ndra''o!', '["Faigi 5:19; 27:23"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 9, 'Ba möi ia baero, i''o''ö, lö i''ila wa si duhu nilau mala''ika andrö, iwai sa angilata ni''ilania.', '[]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 10, 'Ba me no latörö naha zanaro, si föföna larugi, awö naha wanete da''ö, ba larugi mbawandruhö si''öli andrö, lala ba newali, ba teboka manö da''ö fönara; ba möi ira baero, latörö newali si sara, ba i''anema''ö iheta ia khönia mala''ika andrö.', '[]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 11, 'Ba imane Fetero, me i''era-era tödönia: Awena u''ila, si ndruhu-ndruhu, no ifatenge mala''ikania So''aya, ba no i''efa''ö ndra''o ba danga Herode ba ba nibalo-baloi niha Yehuda fefu.[6]', '["Sin 34:8; 91:11; Dan 6:22; Heb 1:14"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 12, 'Ba me no aboto ba dödönia da''ö, ba irugi nomo Maria andrö, ina Yohane, nifotöi Mareko; ba no ato zowulo ba da''ö, mangandrö.[7]', '["Faigi 15:37; TimII 4:11"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 13, 'Ba me ibökö mbawandruhö föna, ba so nono alawe, Rode döinia, ba wamondrongo,', '["Luk 24:37"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 14, 'ba me irongo li Wetero, ba lö ibokai mbawandruhö, ba wa''omuso dödö, fagohi ia, isaŵa yomo, i''ombakha''ö, so baero Wetero.', '["Luk 24:37"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 15, 'Ba lamane khönia: Owöhö''ö! Ba lö iböhöli, si duhu iŵa''ö. Ba lamane: Mala''ikania.[8]', '["Luk 24:37"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 16, 'Ba itohugö wamökö Fetero; ba me labokai, ba la''ila ia, ba tobali dödöra.', '["Faigi 15:13; Gal 1:19"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 17, 'Ba ifazaŵa dangania khöra, böi humede ira, ba idunö-dunö, heiwisa So''aya, wangefa''ö ya''ia ba gurunga, ba imane: Mi''ombakha''ö khö Yakobo ba ba dalifusö. Ba mofanö ia, isaŵa naha bö''ö.[9]', '["Faigi 15:13; Gal 1:19"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 18, 'Ba me moluo, ba tenga ha ma''ifu ŵa''abu dödö zaradadu andrö, hadia khö Wetero andrö.', '[]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 19, 'Ba me isofu ia Herode ba me lö isöndra, ba isekhegö zanaro, ba iŵa''ö labunu.', '[]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 20, 'Ba so wönunia sabölö-bölö ba mbanua Diro ba ba mbanua Zidona. Ba möi ira khönia, ha sara dödö, lafawe''e Mbalaso andrö, mandru yomo khö razo ba la''andrö wangatulö, me ba danö razo andrö lasöndra mbalazora.[10]', '["Hes 27:17; SalI 5:9,11"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 21, 'Ba ha samuza mo''ökhö, ba i''obaru mbaru razo Herode mudadao ia ba dadaomania andrö, ba muhede ia khöra.', '["SalII 19:35; Hes 28:2; Dan 5:20"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 22, 'Ba mu''ao niha sato khönia: Li Lowalangi da''ö, ba tenga li niha.', '["SalII 19:35; Hes 28:2; Dan 5:20"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 23, 'Ba i''anema''ö ibözi ia mala''ika Zo''aya, me tenga Lowalangi ifosumange; ba mate ia, ni''a gukuö.[11]', '["SalII 19:35; Hes 28:2; Dan 5:20"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 24, 'Ba monönö-nönö li Lowalangi, tobali ato ira.[12]', '["Faigi 19:20; Yes 55:11","Faigi 11:29,30; 13:5"]', NULL),
  (3394269, 'NT', 'Halöŵö Zinenge', 12, 25, 'Ba mangawuli Mbaranaba, awö Zaulo, moroi ba Yeruzalema, me no la''asiwai wame''e tolo-tolo andrö, ba la''ohe awöra Yohane andrö, nifotöi Mareko.[13]', '["Faigi 19:20; Yes 55:11","Faigi 11:29,30; 13:5"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 1, 'Ba so ba Gandriokhia, ba mbanua Yesu ba da''ö, zama''ele''ö ba samahaö, Baranaba andrö ba Simeoni, nifotöi Nigero, ba Lukio, banua Girene, ba Mena''e, awö Herode, salaŵa andrö ba zi sagörö ni''o''öfa tanö, me iraono ira, ba Saulo.[1]', '["Faigi 11:25 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 2, 'Ba me lafosumange Zo''aya ba me mamoni ira, ba imane Eheha ni''amoni''ö: Mi''oniagö khögu Mbaranaba andrö, awö Zaulo ba halöŵö andrö, ba nikaonigu ya''ira.[2]', '["Faigi 14:26","Faigi 6:6"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 3, 'Ba mamoni ira, ba mangandrö, ba latufa högöra tanga, ba lafofanö.[3]', '["Faigi 14:26","Faigi 6:6"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 4, 'Ba ya''ira, nifatenge Geheha ni''amoni''ö, ba möi misi tou ba Zeloikia, ba moroi ba da''ö moloyo ira, lasaŵa Gifero.', '["Faigi 12:25"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 5, 'Ba me no larugi Zalami, ba mangombakha li Lowalangi ira, ba zekola niha Yehuda. Ba fao göi khöra Yohane, ngoni-ngonira.[4]', '["Faigi 12:25"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 6, 'Ba me latöröi hulo andrö, ma''asagörö, irugi Wafo, ba falukha ira niha sebua elemu, sama''ele''ö sofaya, niha Yehuda, Bariyesu döinia,[5]', '["Faigi 8:9","Faigi 9:17","MozV 13:13","Sin 32:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 7, 'si so khö gumandru, Seregio Faulo; ba no niha satua-tua gumandru andrö. Ba ifakaoni''ö khönia ndra Baranaba Saulo kumandru andrö, omasi ia ifondrondrongo li Lowalangi.', '["Faigi 8:9","Faigi 9:17","MozV 13:13","Sin 32:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 8, 'Ba itenaŵa ira Elima, (si manö döinia, na la''ali) sebua elemu andrö, i''alui wamaelungu kumandru, fa böi faduhu dödönia.', '["Faigi 8:9","Faigi 9:17","MozV 13:13","Sin 32:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 9, 'Ba inehegö ia Saulo, sotöi Faulu göi, si no fahöna Eheha ni''amoni''ö,[6],', '["Faigi 8:9","Faigi 9:17","MozV 13:13","Sin 32:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 10, 'imane: He ono Gafökha, si no fahöna fa''onekhe ba falimosa fefu, sanuzu tödö satulö fefu, hadia ia, lö öbato wamila''ö lala sadölö andrö khö Zo''aya?[7]', '["Faigi 8:9","Faigi 9:17","MozV 13:13","Sin 32:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 11, 'Ba iada''e ba hiza, ba ikhamö ndra''ugö tanga Zo''aya ba au''a ndra''ugö, ba lö ö''ila luo, irege no irugi baŵa khöu. Ba i''anema''ö ihawui ia fa''andrundrumö ba fa''ogömi-gömi, ba mowaö-waö ia misa, mangalui solohe tangania.[8]', '["Faigi 8:9","Faigi 9:17","MozV 13:13","Sin 32:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 12, 'Ba me i''ila da''ö kumandru, ba faduhu dödönia, tobali dödönia ba huku Zo''aya.', '["Faigi 8:9","Faigi 9:17","MozV 13:13","Sin 32:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 13, 'Ba moloyo ndra Faulo, la''otarai Wafo, lasaŵa Werege ba Wambilia; ba iröi ira Yohane, mangawuli ba Yeruzalema.[9]', '["Faigi 15:37 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 14, 'Ba ya''ira, ba latörö danö, ba larugi Gandriokhia ba Wizidia, ba möi ira ba zekola, me luo sabato, mudadao ira.', '["Faigi 15:37 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 15, 'Ba me no aefa wombaso sura goroisa, awö zura zama''ele''ö, ba lafahede''ö khöra satua zekola, lamane: Na so hadia ia khömi, ya''ami, ira talifusö, niŵa''ö ba zato, famarou dödö, ba miŵa''ö.[10]', '["Faigi 15:21"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 16, 'Ba maoso Waulo, ifazaŵa dangania, ba imane: He ya''ami, Iraono Gizeraeli ba ya''ami, sangata''ufi Lowalangi, mifondrondrongo!', '["Faigi 7:2; MozV 26:18,19; MozII 12:37 b.t.; Yes 63:12; Hes 20:5 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 17, 'No ituyu ndra tuada Lowalangi Ndraono Gizeraeli andrö, ba no i''ebua''ö soi andrö, me si fatewu ira ba danö Miserayi, ba no iheta ira ba da''ö tangania sabölö andrö.[11]', '["Faigi 7:2; MozV 26:18,19; MozII 12:37 b.t.; Yes 63:12; Hes 20:5 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 18, 'Ba mato öfa wulu fakhe wa''ara irorogö ira ba danö si mate andrö,[12],', '["MozIV 14:34; MozV 1:31; 8:15,16; Sin 78; Heb 3:9","MozV 7:1; Yos 24:11; 14:2"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 19, 'ba fitu soi ihori ba danö Gana''ana ba ibe''e khöra danöra andrö, ondröita mitou.[13]', '["MozIV 14:34; MozV 1:31; 8:15,16; Sin 78; Heb 3:9","MozV 7:1; Yos 24:11; 14:2"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 20, 'Ba aefa da''ö, ba i''asogö khöra zanguhuku, mato öfa ngaotu a lima wulu fakhe wa''ara, irugi Zamu''eli, sama''ele''ö andrö.[14]', '["Sanguh 2:16 b.t.; SamI 3:20","SamI 8:5; 9:1,2,16","SamI 16:1; 13:13,14; Sin 89:21"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 21, 'Ba i''otarai da''ö, ba la''andrö razo, ba ibe''e khöra Lowalangi Zaulo andrö, ono Gisi, mado Mbeniyami, öfa wulu fakhe.[15]', '["Sanguh 2:16 b.t.; SamI 3:20","SamI 8:5; 9:1,2,16","SamI 16:1; 13:13,14; Sin 89:21"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 22, 'Ba me no itibo''ö da''ö, ba ibe''e razo Dawido andrö, nifaduhu''önia, me imane: "No usöndra Dawido, ono Giza''i andrö, niha somasi dödögu, solo''ö fefu zomasido."[16]', '["Sanguh 2:16 b.t.; SamI 3:20","SamI 8:5; 9:1,2,16","SamI 16:1; 13:13,14; Sin 89:21"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 23, 'Ba ma''uwu da''ö no i''asogö Lowalangi sangorifi Iraono Gizeraeli Yesu, dali gamabu''ula li andrö,[17]', '["Rom 1:3; Yes 11:1; Luk 1:27","Faigi 19:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 24, 'me no aefa i''ombakha''ö Yohane föna wa''asonia andrö, wamayagö idanö andrö, ba wamalalini era-era, ba Ndraono Gizeraeli fefu.[18]', '["Rom 1:3; Yes 11:1; Luk 1:27","Faigi 19:4"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 25, 'Ba me awai halöŵö Yohane andrö, ba imane: Hadia ba dödömi, ha niha ndra''odo? Tenga ya''odo; hiza sa, so furigu dania zambö ndra''o utoto''ö mbadagahe ba gahenia.[19]', '["Luk 3:15 b.t.; Yoh 1:20 b.t.","Faigi 3:26; 10:36","Faigi 3:17; Yoh 16:3; Yes 29:11","Mat 27:20,22,23","Luk 18:13; Mat 27:59 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 26, 'He ya''ami, ira talifusö, madou Gaberahamo, ba ha niha ba khömi, sangata''ufi Lowalangi, khömi tefa''ohe''ö daroma li fangorifi andrö.[20]', '["Luk 3:15 b.t.; Yoh 1:20 b.t.","Faigi 3:26; 10:36","Faigi 3:17; Yoh 16:3; Yes 29:11","Mat 27:20,22,23","Luk 18:13; Mat 27:59 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 27, 'Lö''ö sa aboto da''ö ba dödö mbanua Yeruzalema, ba he ba dödö zalaŵara, ba itörö göi li zama''ele''ö andrö, nibaso-baso, ero na luo sabato, labe''e, me la''etu''ö huku.[21]', '["Luk 3:15 b.t.; Yoh 1:20 b.t.","Faigi 3:26; 10:36","Faigi 3:17; Yoh 16:3; Yes 29:11","Mat 27:20,22,23","Luk 18:13; Mat 27:59 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 28, 'Ba he lö nisöndrara börö wamunu, ba la''andrö zui khö Wilato, labunu ia.[22]', '["Luk 3:15 b.t.; Yoh 1:20 b.t.","Faigi 3:26; 10:36","Faigi 3:17; Yoh 16:3; Yes 29:11","Mat 27:20,22,23","Luk 18:13; Mat 27:59 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 29, 'Ba me no latörö fefu zi so ba zura ba khönia, ba laheta ia ba döla geu, labe''e ba lewatö.[23]', '["Luk 3:15 b.t.; Yoh 1:20 b.t.","Faigi 3:26; 10:36","Faigi 3:17; Yoh 16:3; Yes 29:11","Mat 27:20,22,23","Luk 18:13; Mat 27:59 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 30, 'Ba no isusugi Lowalangi, moroi ba ngai zi mate.[24]', '["Faigi 3:15","Faigi 1:3; 10:40,41"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 31, 'Ara ma''ifu i''oroma-roma''ö ia khöra, si fao khönia moroi ba Galilaia, we''amöi misi yaŵa ba Yeruzalema, samaduhu''ö ya''ia iada''e ba niha sato.[25]', '["Faigi 3:15","Faigi 1:3; 10:40,41"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 32, 'Ba ya''aga mangombakha khömi amabu''ula li andrö khö ndra tua, wa no itörö sibai da''ö Lowalangi ba ma''uwu, khöda, me isusugi Yesu.[26]', '["Luk 24:27","Sin 2:7","Faigi 2:27; Yes 55:3","Sin 16:10; Sakh 13:7","Faigi 2:29 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 33, 'Si mane si so ba zinunö fanete zi föföna andrö: "Onogu ndra''ugö, ma''ökhö andre no mo''onodo ya''ugö."[27]', '["Luk 24:27","Sin 2:7","Faigi 2:27; Yes 55:3","Sin 16:10; Sakh 13:7","Faigi 2:29 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 34, 'Ba imane wangombakha fanusuginia ya''ia moroi ba ngai zi mate, fa lö''ö sa''ae mangawuli ia ba wa''obou: "ube''e khömi ni''amoni''ö andrö khö Dawido, si ndruhu andrö."[28]', '["Luk 24:27","Sin 2:7","Faigi 2:27; Yes 55:3","Sin 16:10; Sakh 13:7","Faigi 2:29 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 35, 'Me imane göi ba zi sambua: "Lö öfa''ila''ö wa''obou ba ni''amoni''ö andrö khöu.[29]', '["Luk 24:27","Sin 2:7","Faigi 2:27; Yes 55:3","Sin 16:10; Sakh 13:7","Faigi 2:29 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 36, 'Noa sa mate Dawido, me no i''o''ö dödö Lowalangi, ba niha si sagötö andrö, si faendronga khönia, ba no te''orudugö ia khö ndra tuania, ba no i''ila wa''obou.[30]', '["Luk 24:27","Sin 2:7","Faigi 2:27; Yes 55:3","Sin 16:10; Sakh 13:7","Faigi 2:29 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 37, 'Ba lö ni''ila nisusugi Lowalangi andrö fa''obou.', '["Luk 24:27","Sin 2:7","Faigi 2:27; Yes 55:3","Sin 16:10; Sakh 13:7","Faigi 2:29 b.t."]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 38, 'Andrö ya''aboto ba dödömi, ya''ami, ira talifusö, te''ombakha''ö khömi wangefa horö, soroi ba da''ö;[31]', '["Faigi 10:43; Luk 24:47","Rom 3:28","Yes 28:14; Hab 1:5"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 39, 'fefu zi tebai aefa khömi ba goroisa Moze, ba aefa ba da''ö, ba zamati fefu.[32]', '["Faigi 10:43; Luk 24:47","Rom 3:28","Yes 28:14; Hab 1:5"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 40, 'Andrö mifaigi, fa lö itörö ami niŵa''ö ba zura zama''ele''ö andrö:[33]', '["Faigi 10:43; Luk 24:47","Rom 3:28","Yes 28:14; Hab 1:5"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 41, '"Mifaigi, ya''ami, si lö ba dödö, ba ya''ahöli-höli dödömi, yalö oroma ami sa''ae; me uhalö halöŵö ba götömi, halöŵö ba zi lö faduhu dödömi, na so zanutunö ya''ia khömi."', '["Faigi 10:43; Luk 24:47","Rom 3:28","Yes 28:14; Hab 1:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 42, 'Ba me laröi zekola, ba la''andrö khöra lafuli, la''ombakha''ö khöra daroma li andrö, na luo sabato dania.', '["Faigi 11:23"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 43, 'Ba me no aefa zekola, ba ato niha Yehuda, awö zi no möi banuara, samosumange Lowalangi, solo''ö ira Faulo Baranaba. Ba fahuhuo ira khöra, lafarou dödöra, fa böi labulö''ö ira ba wa''ebua dödö Lowalangi andrö.[34]', '["Faigi 11:23"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 44, 'Ba me luo sabato fanete da''ö, ba arakha samba banua manö andrö zangondrasi, ba wamondrongo taroma li Zo''aya.', '[]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 45, 'Ba me la''ila niha sato andrö niha Yehuda andrö, ba tesao wa''afökhö dödöra ba lafadaö niŵa''ö Waulo, mamadaö ba manandraŵa.[35]', '["TesI 2:14–16"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 46, 'Ba lamane ira Faulo Baranaba, lö aiŵö ira: Lö tola lö te''ofönai''ö khömi wangombakha taroma li Lowalangi, ba me mitimba ia, me tenga si nangea mitema wa''auri si lö aetu andrö, miŵa''ö, ba hiza, ba masaŵa niha baero.[36]', '["Faigi 3:26; 28:28; Mat 10:6; 21:43; 22:3–8","Faigi 1:8; Yes 49:6"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 47, 'Si manö sa ni''oroi''ö Zo''aya khöma: "No ube''e haga niha baero ndra''ugö, ena''ö fangorifi ndra''ugö, irugi ba wondrege danö".[37]', '["Faigi 3:26; 28:28; Mat 10:6; 21:43; 22:3–8","Faigi 1:8; Yes 49:6"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 48, 'Ba me larongo da''ö niha baero, ba omuso dödöra ba lasuno daroma li Zo''aya, ba mamati, ha wa''ato nihonogöi ba wanema fa''auri si lö aetu.[38]', '["Rom 8:29,30"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 49, 'Ba te''ombakha''ö daroma li Zo''aya, ba danö andrö ma''asagörö.', '["Rom 8:29,30"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 50, 'Ba lafarou niha Yehuda ndra alawe zalaŵa, sangata''ufi Lowalangi, awö zalaŵa mbanua, ba tobali lagohi ndra Faulo Baranaba, lafofanö ira ba danöra.[39]', '["Faigi 14:2; 17:5"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 51, 'Ba ya''ira, ba la''anotogö khöra gawu-gawu andrö ba gahera, möi ira ba Nikonia.[40]', '["Faigi 18:6; Mat 10:14"]', NULL),
  (3394270, 'NT', 'Halöŵö Zinenge', 13, 52, 'Ba fahöna ba nifahaö wa''omuso dödö ba Eheha ni''amoni''ö.', '["Faigi 18:6; Mat 10:14"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 1, 'Ba ba Nikonia, ba fao ira we''amöi ba zekola niha Yehuda, ba ba wangombakha''öra, ba faoma mamati, he niha Yehuda, ba he Dawa Heleni, ato ira.[1]', '["Faigi 11:20,21","Faigi 13:45,50","Mar 16:20; Heb 2:4"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 2, 'Ba lafarou dödö niha baero niha Yehuda si lö molo''ö, lafabörö ba dalifusö.[2]', '["Faigi 11:20,21","Faigi 13:45,50","Mar 16:20; Heb 2:4"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 3, 'Ba ara zui ma''ifu ira ba da''ö, lö aiŵö ira wangombakha, börö Zo''aya, samaduhu''ö taroma li fa''ebua dödönia; ibe''e khöra, lafazökhi tangara dandra, awö gila-ila.[3]', '["Faigi 11:20,21","Faigi 13:45,50","Mar 16:20; Heb 2:4"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 4, 'Ba fabali dödö mbanua andrö, so zi fa''awö ba niha Yehuda, ba so zi fa''awö ba zinenge.', '["TimII 3:10,11"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 5, 'Ba me maoso dödö niha baero, awö dödö niha Yehuda, fabaya salaŵara, ba wamakao ya''ira ba ba wanebu kara,[4]', '["TimII 3:10,11"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 6, 'ba me terongo khöra, ba moloi ira, lasaŵa mbanua Lika''onia, Lisitera ba Dareba, ba ba zi fasui andrö.[5]', '["Mat 10:23"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 7, 'Ba da''ö la''ombakha''ö duria somuso dödö.', '["Mat 10:23"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 8, 'Ba so ba Lisitera niha, sidao-dao, si tebai mofanö, sombuyu-mbuyu töla, moroi ba dalu ninania, alukhö mowaö-waö ia.[6]', '["Faigi 3:2 b.t."]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 9, 'Ba irongo, me fahuhuo Waulo.', '["Faigi 3:2 b.t."]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 10, 'ba imane, ebua linia: Atulö''ö wezizio ba gaheu!', '["Mat 9:28"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 11, 'Ba me la''ila niha sato nilau Waulo, ba lamane ba li Lika''onia: No tobali fakhili-khili ndra Lowalangi ba niha, ba no möi mitou khöda.[9]', '["Faigi 28:6"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 12, 'Ba labe''e töi Mbaranaba Yufitero ba töi Waulo, ba Merekuri, me ya''ia zi fahuhuo.', '["Faigi 28:6"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 13, 'Ba i''ohe ba mbawa göli göröbao ba bunga ere Yufitero andrö, si so ba ngai mbanuara, ba möi awönia niha sato, lafosumange ira ena''ö.', '[]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 14, 'Ba me larongo da''ö sinenge Baranaba ba Faulo, ba lasika nukhara, fagohi ira lasaŵa zato, mu''ao ira, lamane:', '["Faigi 10:26; 17:23,24; TesI 1:9","Faigi 17:30; Rom 1:24","Rom 1:19 b.t.; Yer 5:24; Mat 5:45"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 15, 'He ya''ami, hana wa mimanö? Niha göi ndra''aga, si mane ya''ami, sangombakha khömi turia somuso dödö, ena''ö miröi waya andrö, ba ena''ö mifuli ami khö Lowalangi sauri, samazökhi banua si yaŵa, awö danö, awö nasi, awö nösi fefu;[10]', '["Faigi 10:26; 17:23,24; TesI 1:9","Faigi 17:30; Rom 1:24","Rom 1:19 b.t.; Yer 5:24; Mat 5:45"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 16, 'si no manehe ba götö si no numalö, latörö larara niha baero fefu;[11]', '["Faigi 10:26; 17:23,24; TesI 1:9","Faigi 17:30; Rom 1:24","Rom 1:19 b.t.; Yer 5:24; Mat 5:45"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 17, 'he ŵa''ae lö ibini''ö ia, wanolo, wame''e khömi teu moroi yaŵa ba baŵa sowua zinanö, ba wangabuso tödömi ö ba fa''omuso dödö.[12]', '["Faigi 10:26; 17:23,24; TesI 1:9","Faigi 17:30; Rom 1:24","Rom 1:19 b.t.; Yer 5:24; Mat 5:45"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 18, 'Ba me laŵa''ö da''ö, ba ha si''aikö fanenaŵa sato, fa lö lafosumange ira.', '[]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 19, 'Ba so niha Yehuda, si otarai Gandriokhia ba Ikonia, ba lafarou niha sato, ba latebu kara Waulo, ba lafondröni hakhi baero mbanua, lawai no mate ia.[13]', '["Faigi 13:14,50; KorII 11:25"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 20, 'Ba me lafasui ia nifahaö, ba maoso ia, möi ia miyomo. Ba sara wongi aefa da''ö, ba mofanö ia, awö Mbaranaba, lasaŵa Ndrarebe.', '[]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 21, 'Ba la''ombakha''ö duria somuso dödö ba mbanua andrö, ba me no ato nibali''öra nifahaö, ba lafuli ira ba Lisitera ba ba Nikonia ba ba Gandriokhia.', '["Faigi 13:43; TimII 3:12; Rom 8:17; Sin 34:20","Faigi 20:28; 13:3"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 22, 'La''a''aro''ö dödö nifahaö, lafarou dödöra, fa böi labulö''ö ira ba wamati; laŵa''ö khöra, lö tola lö oya zi göna ita famakao ba lala ba mbanua Lowalangi andrö.[14]', '["Faigi 13:43; TimII 3:12; Rom 8:17; Sin 34:20","Faigi 20:28; 13:3"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 23, 'Ba me no ladozigö banua, wanutuyu satua khöra, ba mangandrö ira ba mamoni, wanou''ö ya''ira ba danga Zo''aya, ba zamati ira.[15]', '["Faigi 13:43; TimII 3:12; Rom 8:17; Sin 34:20","Faigi 20:28; 13:3"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 24, 'Ba latörö Wizidia, lasaŵa Wambilia.', '["Faigi 13:1–3; 15:40"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 25, 'Ba me no la''ombakha''ö daroma li ba Werege, ba möi ira misi tou ba Gatalia.', '["Faigi 13:1–3; 15:40"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 26, 'Moroi ba da''ö moloyo ira, lasaŵa Gandriokhia, ba nitou''ö ya''ira ba wa''ebua dödö Lowalangi, ba halöŵö andrö, nihalöra.[16]', '["Faigi 13:1–3; 15:40"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 27, 'Ba me larugi, ba lafalukha''ö mbanua, la''ombakha''ö he iwisa Lowalangi khöra, awö wa no ifolala ba wamati niha baero.[17]', '["Faigi 21:19"]', NULL),
  (3394271, 'NT', 'Halöŵö Zinenge', 14, 28, 'Ba ara ma''ifu ira ba da''ö, awö ndra nifahaö.', '["Faigi 21:19"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 1, 'Ba so zi möi misi tou ösa moroi ba Yudaia, lafahaö dalifusö, lamane: Na lö laboto ami, na lö mi''o''ö huku Moze, ba tebai misöndra wa''auri andrö.[1]', '["Gal 5:1 b.t.","Faigi 11:30","Faigi 14, 27"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 2, 'Ba me tobali fabali dödö, ba me tenga side-ide huhuo ndra Faulo Baranaba khöra, ba lahonogöi, möi misi yaŵa ndra Faulo Baranaba ba awöra bö''ö ösa, ba zinenge ba ba zatua, ba Yeruzalema, ba huhuo andrö.[2]', '["Gal 5:1 b.t.","Faigi 11:30","Faigi 14, 27"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 3, 'Ba ya''ira, me no lafasao ira banua, ba latörö Wönikia ba Samaria, ladunö-dunö wolo''ö niha baero andrö, omuso sibai dödö dalifusö fefu labe''e.[3]', '["Gal 5:1 b.t.","Faigi 11:30","Faigi 14, 27"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 4, 'Ba me larugi Yeruzalema, ba latema ira banua ba sinenge ba satua; ba la''ombakha''ö he wisa Lowalangi khöra.', '[]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 5, 'Ba maoso ösa zi faehu huku andrö, farizaio, si no mamati, lamane: Lö tola lö laboto ira, ba lö tola lö laŵa''ö khöra, la''o''ö goroisa Moze.[4]', '["Faigi 26:5"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 6, 'Ba falukha ndra sinenge, awö zatua, ba wame''e ba huhuo niŵa''öra andrö.', '[]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 7, 'Ba me oya huhuo, ba maoso Wetero, ba imane khöra: He ya''ami, ira talifusö, mi''ila, wa no ara sa''ae, me ihonogöi Lowalangi ba khöda, ena''ö khögu larongo niha baero daroma li turia somuso dödö andrö ba wamati.[5]', '["Faigi 10:20,34 b.t.","Faigi 10:15,17; Rom 10:12","Gal 3:10,20; Mat 23:4","Rom 3:20 b.t.; Efes 2:4—10"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 8, 'Ba no ifaduhu''ö ira Lowalangi, sangila tödö niha, me ibe''e khöra Geheha ni''amoni''ö, si mane khöda göi,', '["Faigi 10:20,34 b.t.","Faigi 10:15,17; Rom 10:12","Gal 3:10,20; Mat 23:4","Rom 3:20 b.t.; Efes 2:4—10"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 9, 'ba ma''ifu lö ifaehusi ira khöda, wangehao tödöra famati andrö.[6]', '["Faigi 10:20,34 b.t.","Faigi 10:15,17; Rom 10:12","Gal 3:10,20; Mat 23:4","Rom 3:20 b.t.; Efes 2:4—10"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 10, 'Ba iada''e, ba hana wa mitandraigö Lowalangi, wangahare''ö kalo ba mbagi ndra nifahaö, si tebai ta''ohe, he ira tuada mege, ba he ya''ita.[7]', '["Faigi 10:20,34 b.t.","Faigi 10:15,17; Rom 10:12","Gal 3:10,20; Mat 23:4","Rom 3:20 b.t.; Efes 2:4—10"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 11, 'Ba no faduhu dödöda, wa moroi ba wa''ebua dödö Zo''aya, Yesu, wa te''orifi ita, ha sara lala, khöra göi.[8]', '["Faigi 10:20,34 b.t.","Faigi 10:15,17; Rom 10:12","Gal 3:10,20; Mat 23:4","Rom 3:20 b.t.; Efes 2:4—10"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 12, 'Ba lö hede-hede zato fefu, lafondrondrongo khö Mbaranaba ba khö Waulo, sanutunö ha wa''oya nifazökhi Lowalangi tandra ba ila-ila tangara, ba niha baero.', '[]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 13, 'Ba me no labato wehede, ba itema lira Yakobo, imane: He ya''ami, ira talifusö, mifondrondrongo khögu![9]', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 14, 'No idunö-dunö Simoni, wa no i''ofönai''ö Lowalangi wamaigi soi andre, si ha sambua, nituyu ba niha baero, ba döinia andrö.', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 15, 'Ba si faudu da''ö niŵa''ö zama''ele''ö, si mane si so ba zura:[10]', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 16, '"Aefa da''ö, ba ufulido, ba ufuli u''otomosi nose Dawido andrö, si no aso''a, ufuli u''otomosi zadudunia, ufuli u''a''azökhi ia,', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 17, 'ena''ö la''alui Zo''aya si tosai niha, fefu soi, ba zi no mutötöi töigu, iŵa''ö So''aya,', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 18, 'samarongogö da''ö i''otarai götö föna sa''ae."', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 19, 'Andrö, ni''ŵa''ögu, tenga nifakao zolo''ö andrö khö Lowalangi, niha baero, ba tafazökhi zura khöra,', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 20, 'ena''ö böi lababaya wana''unöi ya''ira ba nadu andrö, ba fohorö, ba nitögi bagi, ba do.[11]', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 21, 'I''otarai mböröta, ba dozi banua, ba so sa khö Moze zangombakha ya''ia, me labasobaso ba zekola, ero na luo sabato.[12]', '["Faigi 21:18","Amos 9:11,12","Faigi 21:25; KorI 10:7,8; TesI 4:3 b.t.; MozIII 17:10—16; MozI 9:4","Faigi 13:15"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 22, 'Ba omasi ndra sinenge, awö zatua, awö mbanua fefu, latutuyu niha ba khöra, nifatenge ba Gandriokhia, awö ndra Faulo Baranaba, Yuda andrö, sotöi Barasaba, ba Sila satua dalifusö.', '["Faigi 15:1; Gal 1:7; 2:4","Faigi 14:19"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 23, 'Lafa''ohe''ö khöra zura, lamane: "Lafahowu''ö sinenge ba talifusö satua dalifusö andrö ba Gandriokhia ba ba Ziria ba ba Gilikia, si no niha baero mböröta.', '["Faigi 15:1; Gal 1:7; 2:4","Faigi 14:19"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 24, 'Me no marongo, no lafawukaisi dödömi huhuora ösa, si otarai ba khöma, lö sökhi-sökhi dödömi labe''e, si lö oroisama;[13]', '["Faigi 15:1; Gal 1:7; 2:4","Faigi 14:19"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 25, 'andrö maŵa''ö, me no ha sara dödö, matutuyu niha nifatenge khömi, awö zomasiga andrö, Baranaba, ba Faulo andrö,', '["Faigi 15:1; Gal 1:7; 2:4","Faigi 14:19"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 26, 'niha si no mangositengagö nosora, börö döi Zo''aya ya''ita andrö, Yesu Keriso.[14]', '["Faigi 15:1; Gal 1:7; 2:4","Faigi 14:19"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 27, 'Ba no mafatenge ndra Yuda Sila, sangombakha göi khömi, si manö göi.', '["KorI 8; MozII 34:15 b.t.; Fam 2:14,29"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 28, 'Noa sa omasi Geheha ni''amoni''ö ba ya''aga göi, böi sa''ae lafonoro ami, baero zi lö tola lö''ö andrö:', '["KorI 8; MozII 34:15 b.t.; Fam 2:14,29"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 29, 'Fa böi mibabaya gö nadu, ba do, ba nitögi bagi, ba fohorö; na lö mibabaya da''ö, ba ohahau dödömi, ya''ahowu ami!"[15]', '["KorI 8; MozII 34:15 b.t.; Fam 2:14,29"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 30, 'Ba me no lafofanö ira, ba möi ira misi tou ba Gandriokhia, lafalukha''ö zato ba labe''e ba dangara zura andrö.', '["Faigi 14, 22"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 31, 'Ba me no labaso, ba omuso dödöra, ba wondrara dödö andrö.', '["Faigi 14, 22"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 32, 'Ba oya huhuo ndra Yuda Sila fondrara dödö ba fangarö dödö dalifusö, me no sama''ele''ö ira göi.[16]', '["Faigi 14, 22"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 33, 'Ba me no ara ma''ifu ira, ba lafofanö ira talifusö ba zamatenge ya''ira, lafahowu''ö ira.', '[]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 34, 'Ba omasi Zila, toröi ia.', '[]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 35, 'Ba la''iagö Gandriokhia ira Faulo Baranaba, mamahaö ira ba mangombakha taroma li Zo''aya, ba ato na nawöra bö''ö.', '[]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 36, 'Ba lö ara, ba imane Faulo khö Mbaranaba: Tafuli ita, tafaigi dalifusö tadozigö banua misa, ba ni''ombakha''öda taroma li Zo''aya; he wisa ira.', '[]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 37, 'Ba omasi Mbaranaba la''ohe awöra göi Yohane andrö, sotöi Mareko.[17]', '["Faigi 12:25; Kol 4:13","Faigi 13:13"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 38, 'Ba niŵa''ö Waulo, tenga si nangea, na la''ohe awöra zi no fabali khöra no, ba Wambilia, si lö möi awöra ba halöŵö no.[18]', '["Faigi 12:25; Kol 4:13","Faigi 13:13"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 39, 'Ba tobali faoma möfonu ira khö nawöra, irege fabali ira, ba i''ohe awönia Mareko andrö Baranaba, moloyo ira, lasaŵa Gifero.[19]', '["TimII 4:11"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 40, 'Ba i''ohe Zila Faulo, ba mofanö, me no latou''ö ia ba wa''ebua dödö Lowalangi talifusö.[20]', '["Faigi 14:26; 15:22","Faigi 12:22"]', NULL),
  (3394274, 'NT', 'Halöŵö Zinenge', 15, 41, 'Ba itörö Ziria ba Kilikia, i''a''aro''ö dödö mbanua Yesu.[21]', '["Faigi 14:26; 15:22","Faigi 12:22"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 1, 'Ba irugi si tou Ndrarebe ba Lisitera, ba hiza, so ba da''ö nifahaö, Timoteo döi, niha Yehuda ninania, samati, ba Dawa Heleni namania.[1]', '["Faigi 19:22; Rom 16:21; TimI 1:2; TimII 1:5; 3:14","TesI 3:2","KorI 9:19 b.t.; Gal 2:3"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 2, 'Sökhi duriania ba dalifusö, ba Lisitera ba ba Nikonia.[2]', '["Faigi 19:22; Rom 16:21; TimI 1:2; TimII 1:5; 3:14","TesI 3:2","KorI 9:19 b.t.; Gal 2:3"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 3, 'Ba omasi Waulo, na möi awönia da''ö. Ba ihalö, iboto, börö niha Yehuda, si so ba mbanua andrö, oi dozi sa la''ila, wa Dawa Heleni namania.[3]', '["Faigi 19:22; Rom 16:21; TimI 1:2; TimII 1:5; 3:14","TesI 3:2","KorI 9:19 b.t.; Gal 2:3"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 4, 'Ba me latöröi mbanua, ba lafa''ema khöra goroisa andrö, ni''o''ö, nihonogöi zinenge ba satua, ba Yeruzalema.[4]', '["Faigi 15:23–30","Faigi 14:22; 4:4"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 5, 'Ba itugu sa aro dödö mbanua, wamati, ba ero ma''ökhö tedou wa''atora.[5]', '["Faigi 15:23–30","Faigi 14:22; 4:4"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 6, 'Ba latörö Wirigia, awö danö Galatia, me no itenaŵa ira Eheha ni''amoni''ö, fa böi ba Azia la''ombakha''ö daroma li.[6]', '["Faigi 18:23"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 7, 'Ba me larugi tanö ba Mizia, ba latandraigö we''amöi ba Mbitinia, ba lö ifa''amöi ira Eheha Yesu.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 8, 'Ba lahene Mizia, larugi si tou Deroa.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 9, 'Ba oroma khö Waulo gangilata, ba zi bongi, Dawa Makedonia. So ia, mangandrö ia khönia, imane: Ae si yefo, ba Makedonia, orifiga.[7]', '["Faigi 18:9; 9:12; TimI 2:4","Faigi 17:4,12"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 10, 'Ba me aefa i''ila gangilata andrö, ba i''anema''ö ma''alui we''amöi ba Makedonia, me masöndra tödöma, Lowalangi zogaoni ya''aga, ba wangombakha turia somuso dödö khöra.', '["Faigi 18:9; 9:12; TimI 2:4","Faigi 17:4,12"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 11, 'Moloyo ndra''aga, maröi Deroa, madölöga ba Zamoterake, ba mahemolu ö, ba marugi Neafoli.', '["Faigi 18:9; 9:12; TimI 2:4","Faigi 17:4,12"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 12, 'Moroi ba da''ö masaŵa Wilifi, sebua mbanua ba Makedonia tanö andrö, banua nifataro. Ba ara ma''ifu ndra''aga ba mbanua andrö.', '["Faigi 18:9; 9:12; TimI 2:4","Faigi 17:4,12"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 13, 'Ba me luo sabato, ba möiga baero mbanua, ba zinga nidanö, ba da''ö möi ira mangandrö maŵa''ö, ba dumadaoga, fahuhuoga ba ndra alawe, si no möi ba da''ö.[8]', '["Faigi 18:9; 9:12; TimI 2:4","Faigi 17:4,12"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 14, 'Ba ifondrondrongo ira alawe, Lidia döi, saniaga baru luo, banua Diatira, sangata''ufi Lowalangi; ba ibokai dödönia So''aya, fa lö olifu ia, niŵa''ö Waulo.[9]', '["Faigi 13:16; TesI 2:13; Luk 8:15","Faigi 16:31,34"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 15, 'Ba me no tebayagö idanö ia awö zoroiyomonia, ba mangandrö ia khöma, imane: Na ba dödömi, samati khö Zo''aya ndra''odo, ba mi''ae yomo ba nomogu, mi''iagö da''ö, ba iforege wanguma''ö khöma.[10]', '["Faigi 13:16; TesI 2:13; Luk 8:15","Faigi 16:31,34"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 16, 'Ba me möiga mangandrö ba falukhaga zawuyu ono alawe, si so bekhu waetasa, ebua lasöndra sokhö ya''ia ibe''e, ba waetasania andrö.[11]', '["SamI 28:7"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 17, 'Ba i''o''öga, ira Faulo ndra''aga, mu''ao ia, imane: Enoni Lowalangi Fondrege zalaŵa niha andrö, sangombakha khömi lala wangorifi.', '["SamI 28:7"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 18, 'Ba ara si manö-manö ia.', '["SamI 28:7"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 19, 'Ba me la''ila sokhö ya''ia, no aheta mbörö wangaluira andrö, ba lara''u ndra Faulo Sila, ladöni ba kade ba zalaŵa.[13]', '["Faigi 15:40"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 20, 'Ba la''ohe khö gumandru, lamane: Lafakuyu khöda mbanua niha andre, ba no niha Yehuda ira;[14]', '["Faigi 17:6 b.t.; Amos 7:10"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 21, 'la''ombakha''ö huku si lö tola tatema, si lö tola ta''o''ö, me Dawa Roma ita.', '["Faigi 17:6 b.t.; Amos 7:10"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 22, 'Ba maoso göi niha sato khöra; ba laheta khöra nukhara ira kumandru ba laŵa''ö, labözi.[15]', '["KorII 11:25; TesI 2:2","Faigi 12:4"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 23, 'Ba me no laforege wamözi ya''ira, ba lakuru, laŵa''ö khö zanaro ba gurunga, ihaogö wanaro ya''ira.', '["KorII 11:25; TesI 2:2","Faigi 12:4"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 24, 'Ba me no irongo goroisa andrö, ba ibe''e ira ba gurunga tanö bakha, ikalo gahera.[16]', '["KorII 11:25; TesI 2:2","Faigi 12:4"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 25, 'Ba mato talu mbongi, ba mangandrö Waulo, awö Zila, lasuno Lowalangi, ba lafondrondrongo khöra nikuru.[17]', '["Faigi 5:41"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 26, 'Ba i''ozumagö so ndruru sabölö-bölö, irege dumögö-dögö lata-lata gurunga. Ba i''anema''ö teboka mbawandruhö fefu, ba oi dozi aefa rate khöra.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 27, 'Ba me tokea zanaro ba gurunga, me i''ila, no teboka mbawandruhö gurunga, ba isöbi wöda, ibunu ia ena''ö, iwai no moloi nikuru.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 28, 'Ba mu''ao Waulo, ebua linia, imane: Böi fakiko''ö, dozi sa so ndra''aga ba da''e!', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 29, 'Ba iŵa''ö wandru, isaŵa si bakha, fagohi, ituhi danö, föna ndra Faulo Sila, manizi-nizi,', '["Faigi 2:37"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 30, 'ba ifasao ira baero, imane: He uwisa, Tua, fa usöndra wangorifi?[18]', '["Faigi 2:37"]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 31, 'Ba lamane: Amati khö Zo''aya, Yesu, ba te''orifi ndra''ugö, awö zoroiyomou fefu.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 32, 'Ba la''ombakha''ö khönia daroma li Zo''aya ba ba si so ba nomonia fefu.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 33, 'Ba ihalö ira, ba da''ö sibai, ba zi bongi, isasai khöra zesokho ba wamözi andrö, ba i''anema''ö tebayagö idanö ia, awö zoroiyomonia fefu.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 34, 'Ba i''ohe ira yomo, ibe''e göra, ba owua-wua dödönia, me no samba omo manö ira mamati ba Lowalangi.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 35, 'Ba me no moluo, ba lafatenge wazuri ira kumandru, lamane: Efa''ö niha andrö!', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 36, 'Ba i''ombakha''ö sanaro ba gurunga lira andrö khö Waulo, imane: No lafatenge ira kumandru, ena''ö la''efa''ö ami. Ba iada''e, ba mi''ae baero, mi''ofanö, ya''ohahau dödömi!', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 37, 'Ba imane khöra Faulo: No labözi ndra''aga, ba zanehe niha, lö musekhegö, he ŵa''ae banua Roma ndra''aga, ba no lakuru ndra''aga, ba hadia, labini''ö iada''e wamofanö ya''aga? Böi sa! Ndramöi sa''ae, ya''ira andrö, ba wangefa''ö ya''aga.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 38, 'Awena la''ombakha''ö fazuri khö ndra kumandru niŵa''öra andrö. Ba ata''u ira, me larongo, wa banua Roma ira; ba möi ira, la''o''ou,', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 39, 'la''ohe baero, la''andrö khöra, laheta ira ba mbanuara.', '[]', NULL),
  (3394275, 'NT', 'Halöŵö Zinenge', 16, 40, 'Ba me no laröi gurunga, ba möi ira khö Lidia andrö; ba me la''ila dalifusö, ba lafarou dödöra, ba mofanö ira.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 1, 'Ba me no latörö Gambifoli, awö Gafolonia, ba larugi Desalonika, ba zi so sekola niha Yehuda.[1]', '["TesI 2:2"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 2, 'Ba me no huku Waulo zi manö, ba möi ia bakha khöra, ba tölu sabato lahuhuo''ö zi so ba zura.', '["Luk 24:27,45"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 3, 'Ibokai khöra, i''oroma''ö khöra, wa lö tola lö tefakao Keriso ba maoso moroi ba ngai zi mate, awö wa da''ö Keriso, Yesu andrö, ni''ombakha''ögu khömi, iŵa''ö.[2]', '["Luk 24:27,45"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 4, 'Ba so ösa ba khöra zi faduhu tödö, ba fao-fao ira khö ndra Faulo Sila, ba ato göi Ndraŵa Heleni, sangata''ufi Lowalangi, ba ira alawe zalaŵa, ato.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 5, 'Ba mofönu niha Yehuda, lahalö awöra niha si lö halöŵö, ösa, niha si lö sökhi, la''ekhugö niha, lafawukaisi dödö mbanua, lasaŵa nomo Yaso andrö, la''alui ira, la''ohe ba niha sato ena''ö.', '["Faigi 16:20","Luk 23:2"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 6, 'Ba me lö lasöndra ira, ba lasöbi ba zalaŵa mbanua Yaso andrö, awö dalifusö ösa, mu''ao ira, lamane: "No möi ba da''e göi niha andrö, samawukaisi ösi guli danö ma''afefu![3]', '["Faigi 16:20","Luk 23:2"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 7, 'Ba no ifa''amöi ira baomo khönia Yaso, tomenia, ba dozi ira, ba lasaŵö goroisa kaizaro, wanguma''ö, tanö bö''ö razo, Yesu andrö."[4]', '["Faigi 16:20","Luk 23:2"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 8, 'Ba tobali dödö zato, labe''e, awö dödö zalaŵa, samondrongo da''ö.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 9, 'Ba me no lafali''ö ira khöra Yaso ba awönia, ba la''efa''ö da''ö.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 10, 'Ba la''anema''ö talifusö, lafofanö ba Mberoia ndra Faulo Sila, ba zi bongi; ba me larugi, ba möi ira ba zekola niha Yehuda.', '["Yoh 5:39"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 11, 'Ba si sökhi tödö da''ö, moroi ba zi so ba Desalonika, omasi ira lafondrondrongo daroma li, ero ma''ökhö la''alu-alui ba zura, na si ndruhu.[5]', '["Yoh 5:39"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 12, 'Ba ato ba khöra zamati, ato göi ma''ifu zalaŵa Ndrawa Heleni, ira alawe ba ira matua.', '["Yoh 5:39"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 13, 'Ba me larongo niha Yehuda, ba Desalonika, wa ba Mberoia göi i''ombakha''ö li Lowalangi Faulo, ba möi ira, lafawukaisi dödö zato ba da''ö göi, lafakuyu.[6]', '["TesI 2:15"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 14, 'Ba la''anema''ö lafofanö Waulo talifusö, ena''ö isaŵa mbewe nasi; ba toröi furi ba da''ö Zila ba Timoteo.[7]', '["Faigi 16:1"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 15, 'Ba lafasao Waulo awönia, irugi Natena, ba i''oroi''ö khöra, laŵa''ö khö ndra Sila Timoteo, ena''ö lata''i-ta''i, we''amöi khönia, ba mofanö ira.', '["Faigi 16:1"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 16, 'Ba me ibalo-baloi ira ba Natena Faulo, ba mofönu bakha dödönia, me i''ila, no fahöna nadu ba mbanua.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 17, 'Andrö fahuhuo ia ba zekola ba niha Yehuda, ba ba zangata''ufi Lowalangi, ba ba kade, ero ma''ökhö, ba zi so ba da''ö.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 18, 'Ba falukha khönia göi ösa wilosofo, efikuraio ba sito''iko, ba lamane ösa: Hadia niŵa''ö zi fawea-wea andrö? Ba so zanguma''ö: Hulö na sangombakha Lowalangi bö''ö ia; me i''ombakha''ö khöra Yesu ba femaoso zi mate andrö.[8]', '["KorI 4:12"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 19, 'Ba lasöbi ia, la''ohe ba hili-hili Garesi, lamane: Hadia, tola marongo, hadia huku si bohou andrö, ni''ombakha''öu?', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 20, 'Si bohou sa öfarongogö khöma, andrö omasiga, marongo, hadia ia.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 21, 'Awai sa zomasi mbanua Natena andrö fefu, awö niha bö''ö, si no fatewu khöra, ha fangombakha ba famondrongo si bohou so.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 22, 'Ba ba dalu hili-hili Garesi so Waulo, ba imane: He ya''ami, banua Natena! oroma manö khögu, wa no sabölö mangata''ufi Lowalangi ami.', '["Faigi 7:48","Sin 50:8,9","MozV 32:8"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 23, 'Me utöröi wamaigi sibai nifosumangemi, ba noa sa usöndra göi naha wame''e sumange, nisura yaŵa: "khö Lowalangi si lö ta''ila." Ba ni''ata''ufimi andrö, he lö mi''ila ia, da''ö ni''ombakha''ögu khömi.', '["Faigi 7:48","Sin 50:8,9","MozV 32:8"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 24, 'Lowalangi andrö, samazökhi danö''a ba ösinia, fefu, ba lö i''onahia gosali nifazökhi tanga niha, me no So''aya sorugo ia, ba So''aya tanö;[9]', '["Faigi 7:48","Sin 50:8,9","MozV 32:8"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 25, 'tebai göi tefosumange ia tanga niha, hulö na moguna khönia hadia ia, me no ya''ia zame''e ba niha fefu noso ba hanu-hanu, awö fefu hadia ia.[10]', '["Faigi 7:48","Sin 50:8,9","MozV 32:8"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 26, 'Ba moroi khönia wa no dumadao fefu soi niha ba guli danö ma''asagörö, si ha sambua böröta; ba no i''ötö khöra mbongi, no ihönagö ihonogöi, awö nola nahara andrö.[11]', '["Faigi 7:48","Sin 50:8,9","MozV 32:8"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 27, 'Ena''ö la''alui Lowalangi, ma atö la''ila lababaya ia ba lasöndra, me lö''ö sa atö aröu ia khöda fefu; ba khönia sa auri ita,', '["MozI 1:27; Luk 24:47","Rom 10:14"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 28, 'ba khönia maliŵa-liŵa ita, ba khönia so ita, si mane niŵa''ö zanunö ösa khömi göi: "Nga''ötönia sa ita."', '["MozI 1:27; Luk 24:47","Rom 10:14"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 29, 'Ba me no nga''ötö Lowalangi ita, ba lö tola taŵa''ö tötöda, no fakhili-khili Lowalangi ba gana''a, ba ma ba wirö, ba ma ba gara, ba wamaedo nifazökhi niha, ba wa''atukania ba ba nisöndra dödönia.[12]', '["MozI 1:27; Luk 24:47","Rom 10:14"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 30, 'Ba noa sa i''osilömilagö Lowalangi götö me lö la''ila watahögö niha, ba iada''e, ba iŵa''ö ba niha fefu wamalalini era-era,', '["MozI 1:27; Luk 24:47","Rom 10:14"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 31, 'gofu heza so ira, me no i''ötö mbongi, ba nihukunia dania ösi guli danö, i''atulö''ö wanguhuku, so zanguhuku, si no ihonogöi, wangoro''ö famati ba niha fefu, wanusugi ya''ia moroi ba ngai zi mate.[13]', '["MozI 1:27; Luk 24:47","Rom 10:14"]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 32, 'Ba me larongo wemaoso zi mate andrö, ba so za''iki ösa, ba so göi zanguma''ö: Mafuli mafondrondrongo na khöu da''ö.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 33, 'Ba iheta ia khöra Faulo.', '[]', NULL),
  (3394278, 'NT', 'Halöŵö Zinenge', 17, 34, 'Ba lö laröi ia ira matua ösa ba mamati, samösa göi Dionizio, salaŵa rafe ba hili-hili Garesi andrö, ba samösa ndra alawe, Damari döi, ba so danö bö''ö na, awöra.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 1, 'Aefa da''ö iröi Natena Faulo, möi ia ba Gorindro.', '["Rom 16:3","Faigi 20:34; KorI 4:12"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 2, 'Ba falukha ia niha Yehuda, Akila döi, banua Wondro mböröta; bohou na me i''otarai Gitalia, awö wo''omonia, Ferikila döi, me no ibe''e goroisa kaizaro Kalaudio, laheta ira ba Roma niha Yehuda fefu; ba möi ia khöra.[1]', '["Rom 16:3","Faigi 20:34; KorI 4:12"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 3, 'Ba me no faoma halöŵöra, ba i''iagö khöra, ba mohalö-halöŵö ira; sanoso oloso nose ira.[2]', '["Rom 16:3","Faigi 20:34; KorI 4:12"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 4, 'Ba fahuhuo ia ba zekola, ero na luo sabato, ifaduhu''ö dödö niha Yehuda, awö dödö Ndrawa Heleni.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 5, 'Ba me so Zila ba Timoteo, si otarai Makedonia, ba lö aefa Waulo ba wamahaö, wamaduhu''ö ba niha Yehuda, wa Keriso Yesu.[3]', '["Faigi 17:14,15","Faigi 13:15; 20:26"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 6, 'Ba me mamadaö ira ba me manandraŵa, ba i''anotogö nukhania, imane khöra: Yamöi ba hulumi ndromi! Aefado; i''otarai da''e, ba möido ba niha baero.[4]', '["Faigi 17:14,15","Faigi 13:15; 20:26"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 7, 'Ba mofanö ia ba da''ö, isaŵa nomo niha, sotöi Titio Yuso, sangata''ufi Lowalangi, si no fasinga ba nomo zekola nomonia.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 8, 'Ba mamati khö Zo''aya Gerifo, satua zekola, awö zoroiyomonia fefu; ba ato mbanua Gorindro, samondrongo, mamati ba lafabayagö''ö idanö ira.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 9, 'Ba imane So''aya ba zi bongi, ba gangilata, khö Waulo: Böi ata''ufi! hede manö ba böi bato,', '["Yer 1:18; Hos 2:23; Yoh 10:16"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 10, 'me fao-fao ndra''o khöu, ba lö sombambaya ya''ugö, ba wamakao ya''ugö, me no ato khögu niha ba mbanua da''e.[5]', '["Yer 1:18; Hos 2:23; Yoh 10:16"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 11, 'Ba döfi a matonga i''iagö da''ö, wamahaö ya''ira ba daroma li Lowalangi.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 12, 'Ba me kumandru ba Nakhaya Galio, ba maoso niha Yehuda, ba khö Waulo, ha sara dödö, la''ohe ia ba gödo,', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 13, 'lamane: Lö i''o''ö goroisa da''e wondrönisi niha ba wangata''ufi Lowalangi.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 14, 'Ba me muhede ena''ö Waulo, ba imane Galio ba niha Yehuda: Na so hadia ia zi lö atulö, ba ma hadia ia horö, ya''ami, niha Yehuda, ba lö zi lö ufondrondrongo khömi.[6]', '["Faigi 25, 18. 19","Yoh 18:31"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 15, 'Ba na fasosota ba wamahaö ba ba döi niha ba ba goroisa andrö khömi, ba ya''ami zamaigi; lö edönado uhuhuo''ö zi manö.[7]', '["Faigi 25, 18. 19","Yoh 18:31"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 16, 'Ba ifofanö ira ba gödo.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 17, 'Ba dozi lara''u Zotene, satua zekola, ba labago ia ba gödo; ba lö''ö manö ihalö khönia Galio.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 18, 'Ba me no ara na ma''ifu Waulo, ba i''angonasi dalifusö ba moloyo, isaŵa danö Ziria ba awönia Werikila andrö ba Akila, me no itöwö mbunia ba Gengerea; so gamabu''ula linia.[8]', '["Faigi 21:24; MozIV 6:9,18"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 19, 'Ba irugi Nefeso, ba iröi ira ba da''ö, ba ya''ia, ba möi ba zekola ba fahuhuo ba niha Yehuda.', '["KorI 4:19; Yak 4:15"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 20, 'Ba me la''andrö i''aragö ia ba da''ö,', '["KorI 4:19; Yak 4:15"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 21, 'ba lö i''o''ö; i''angonasi sa ira ba imane: ufulido zui khömi, na omasi Lowalangi; ba moloyo ia, iröi Nefeso.[9]', '["KorI 4:19; Yak 4:15"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 22, 'Ba me no irugi si tou Kaizaria, ba möi ia misi yaŵa, i''owai mbanua, ba möi ia misi tou ba Gandriokhia.[10]', '["Faigi 21:15"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 23, 'Ba me no ara ia ma''ifu ba da''ö, ba mofanö ia, ifadoro wanörö tanö Galatia ba Ferigia, wanga''aro''ö tödö nifahaö fefu.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 24, 'Ba möi ba Nefeso niha Yehuda, banua Alesandria mböröta, Afolo döinia, niha satutua, sabölö ba zura.[11]', '["KorI 3:6"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 25, 'No tefahaö ia ba lala Zo''aya; ba me no satarö tödö ia, ba fahuhuo ia, i''ombakha''ö sibai hadia ia khö Zo''aya, Yesu, ba ha famayagö idanö andrö khö Yohane nirongonia.', '["KorI 3:6"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 26, 'Ba ibörötaigö mangombakha ba zekola, lö aiŵö.', '[]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 27, 'Ba me edöna isaŵa Nakhaya, ba lafarou dödö nifahaö talifusö, lafa''ohe''ö zura, ena''ö lafa''amöi ia khöra. Ba me no irugi, ba itolo sibai zi no mamati, ba wa''ebua dödö andrö;', '["Faigi 9:22; 17:3"]', NULL),
  (3394279, 'NT', 'Halöŵö Zinenge', 18, 28, 'noa sa abölö ia wamu''a niŵa''ö niha Yehuda, ba zanehe niha sato, ba i''oroma''ö moroi ba zura, wa Keriso Yesu.[12]', '["Faigi 9:22; 17:3"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 1, 'Ba tobali me so ba Gorindro Afolo, ba irugi si tou Nefeso Faulo, no itörö yaŵa danö andrö, ba isöndra nifahaö ösa,', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 2, 'ba imane khöra: Hadia, no mitema Geheha ni''amoni''ö, me awena mamati ami?', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 3, 'Ba imane khöra: Ba hadia sa dandrösa, ba nibayagö idanö ya''ami? Ba lamane: Famayagö idanö khö Yohane andrö.', '["Mat 3:11"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 4, 'Ba imane Faulo: Famayagö idanö ba wamalalini era-era wamayagö idanö andrö khö Yohane, ba no iŵa''ö ba niha wamati khö zi so furinia dania, famati khö Yesu.[2]', '["Mat 3:11"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 5, 'Ba me larongo da''ö, ba lafabayagö''ö idanö ira ba döi Yesu, So''aya.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 6, 'Ba me no itufa högöra Faulo, tangania, ba möi khöra Geheha ni''amoni''ö, molau li bö''ö ira ba mama''ele''ö.[3]', '["Faigi 8:17; 10:44,46"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 7, 'So mato felendrua fefu, ndra matua.', '["Faigi 8:17; 10:44,46"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 8, 'Ba möi ia ba zekola, lö aiŵö ia muhede, mato tölu waŵa wa''ara fahuo-huo ia ba ifaduhu''ö dödöra ba ngawalö mbanua Lowalangi andrö.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 9, 'Ba me so ösa zangabe''e''ö tödöra, si lö mamati, sango''aya lala andrö, ba niha sato, ba iheta ia khöra, i''oniagö ndra nifahaö, ba ero ma''ökhö fahuhuo ia ba zekola Dirano.[4]', '["TimII 1:15; Faigi 9:2"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 10, 'Ba mendrua fakhe zi manö, tobali ahori larongo li Zo''aya banua Azia andrö, niha Yehuda ba Dawa Heleni.', '["TimII 1:15; Faigi 9:2"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 11, 'Ba tenga side-ide dandra nifazökhi Lowalangi tanga Waulo;[5]', '["Faigi 14:3","Faigi 5:15"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 12, 'irege labalugö göi zofökhö saefu tanga ba lembe moroi ba nösinia, ba döhö wökhö ba aheta mbekhu si lö sökhi.[6]', '["Faigi 14:3","Faigi 5:15"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 13, 'Ba latandraigö göi samofanö bekhu, niha Yehuda, sanörö-nöröi tanö, ösa, wanötöi töi Yesu, So''aya, ba zi so bekhu si lö sökhi, lamane: ufofanö ami, ba döi Yesu, ni''ombakha''ö Waulo andrö.[7]', '["Luk 9:49"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 14, 'Dafitu ira, ono gere sebua ba niha Yehuda sotöi Sikoia, zolau da''ö.', '["Luk 9:49"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 15, 'Ba itema lira bekhu si lö sökhi andrö, imane khöra: Aboto sa ba dödögu Yesu, ba u''ila Waulo andrö, ba ya''ami, ba ha niha ami?', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 16, 'Ba isaŵa ira niha andrö, si so bekhu si lö sökhi andrö, ilaŵa ira, darua, ibago, irege moloi ira, laröi nomo andrö; no aheta nukha ba no mesokho ira.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 17, 'Ba terongo da''ö ba niha Yehuda sato ba ba Ndrawa Heleni, banua Nefeso, ba ihawui ira fefu fa''ata''u, ba tesuno sibai döi Yesu, So''aya.[8]', '["Faigi 5:5,11","Faigi 6:7"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 18, 'Ba ato zi möi, si no mamati, ba wamokai bua-buara; la''ombakha''ö.', '["Faigi 5:5,11","Faigi 6:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 19, 'Ba ato zi no molau faya-faya mangowuloi sura andrö ba latunu, ba zanehe zato, ba la''ofaya mbölinia, ba lasöndra, dua wulu a lima ngahönö ba rufia.', '["Faigi 5:5,11","Faigi 6:7"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 20, 'Ba ba wa''abölö Zo''aya andrö, ba monönö-nönö daroma li, ba abölö.[9]', '["Faigi 5:5,11","Faigi 6:7"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 21, 'Ba me awai da''ö, ba iŵa''ö tödönia Faulo, itörö Makedonia ba Akhaya, we''amöi ba Yeruzalema, imane: Na aefado ba da''ö, ba lö tola lö u''ila Roma göi.[10]', '["Faigi 23:11","Faigi 17:14; Rom 16:23"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 22, 'Ba ifowaö-waö ba Makedonia dohu-tohu dangania andrö, darua, Timoteo ba Eraso, ba tebato ia na ma''ifu ba Azia.[11]', '["Faigi 23:11","Faigi 17:14; Rom 16:23"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 23, 'Ba tesao wagua-guasa sabölö-bölö ma''ifu, me luo da''ö, ba huku andrö.[12]', '["Ayati 9; KorII 1:8"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 24, 'So niha, tuka wirö, Demeterio döinia, samazökhi famaedo gosali Garitemi andrö, firö, tenga side-ide wangalui nawönia tuka ibe''e.[13]', '["Faigi 16:1"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 25, 'Ba ifalukha''ö ira, awö zi so halöŵö ba da''ö, ba imane: Mi''ila, ya''ami andre, ba halöŵö andrö moroi mbalazoda,', '["Faigi 16:1"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 26, 'ba anehe ami ba mirongo, tenga ha ba Nefeso, arakha ba danö Azia ma''asagörö sa''ae, ba ato nidönisi Waulo andrö niha, nifa''eronia khöda, wanguma''ö tenga Lowalangi nifazökhi danga niha.', '["Faigi 16:1"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 27, 'Ba tenga ha si sambalö andrö zata''u ita, wa lö laku nifazökhida andrö, lö''ö göi ba dödöra gosali Lowalangi ira alawe sebua andrö, Aritemi, ba dania, ba tetayaigö göi wa''asalaŵania ösa, ni''ata''ufi mbanua Azia fefu, awö niha fefu, ba guli danö ma''asagörö.', '["Faigi 16:1"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 28, 'Ba me larongo da''ö, ba mofönu sibai ira, mu''ao ira, lamane: Ebua Garitemi mbanua Nefeso andrö!', '["Faigi 20:4; KorII 1:8,9"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 29, 'Ba samba banua manö fawuka dödö, ba ha sara dödö wanaŵa omo mai-mai, fagohi ira ba lasöbi khöra ndra Gayo Arisaro, banua Makedonia, awö Waulo.[14]', '["Faigi 20:4; KorII 1:8,9"]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 30, 'Ba möi ena''ö Waulo ba niha sato, ba lö lafofanö ia nifahaö.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 31, 'Ba lafatenge göi khönia salaŵa Azia, si no fahuwu khönia, la''andrö khönia, böi yamu''oroma''ö ia ba nomo mai-mai.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 32, 'Ba bö''ö sa niŵa''ö zi samösa, bö''ö niŵa''ö zi samösa, we''ao-ao; noa sa fawuka manö dödö zowulo andrö, ba sato, ba lö la''ila, hana wa owulo ira.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 33, 'Awena laŵa''ö Alesandro, ba hunö niha sato, nilulugö niha Yehuda ia. Ba ifazaŵa dangania Alesandro, muhede ena''ö ia ba niha sato, ibu''a ena''ö.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 34, 'Ba me larongo wa niha Yehuda ia, ba ha sara li zato, mato dua za wa''ara, mu''ao ira: Ebua Garitemi mbanua Nefeso andrö!', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 35, 'Ba ihonogö ira durutuli, ba imane: He ya''ami, banua Nefeso! Ha niha sa zi lö mangila, wa banua Nefeso zondrorogö osali Garitemi sebua andrö, awö zatoru andrö moroi ba mbanua si yaŵa?', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 36, 'Ba me tebai niwu''ai da''ö, ba sahono ami ena''ö, ba böi mida''i-da''i wolau hadia ia.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 37, 'Noa sa mi''ohe ba da''e niha andrö, ba tenga sorabu gama-gama ba gosali ira, ba tenga göi sango''aya Lowalangimi.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 38, 'Ba na so sa, ha niha ia, ni''adugö Demeterio ba awönia tuka andrö, ba lalau rafe ba so gumandru, faoma ndramu''adugö nawöra.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 39, 'Ba na so hadia ia, ba mbö''önia, niŵa''ömi, ba la''asiwai ia ba walukhata satulö.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 40, 'Ata''u sa ita, laböbögö khöda wolaŵa salaŵa, la''adugö ita, börö ma''ökhö andre, me lö khöda börö wamu''a salada ba wa''aekhu niha andre.', '[]', NULL),
  (3394280, 'NT', 'Halöŵö Zinenge', 19, 41, 'Ba me aefa iŵa''ö da''ö, ba ifofanö zowulo andrö.', '[]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 1, 'Ba me no muhonogö wagua-guasa andrö, ba ifakaoni''ö khönia nifahaö Faulo ba ifarou dödöra, ba me no i''angonasi ira, ba mofanö ia, ba we''amöi ba Makedonia.', '["Faigi 17:10; 19:29","Faigi 16:8"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 2, 'Ba itörö danö tanö ba da''ö, ba oya niŵa''önia khöra famarou dödö, ba irugi danö Hela.', '["Faigi 17:10; 19:29","Faigi 16:8"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 3, 'Ba tölu waŵania ba da''ö. Ba me lafagönaisi ia niha Yehuda, me moloyo ia ba Ziria mena''ö, ba iŵa''ö tödönia, sökhi na itörö Makedonia wangawuli.', '["Faigi 17:10; 19:29","Faigi 16:8"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 4, 'Ba awönia Zofatera, ono Wiro, banua Mberoia ba Arisaro ba Sekundro, banua Desalonika, ba Gayo, banua Ndrarebe, ba Timoteo, ba moroi ba Azia, ba Tikhiko ba Terofimo.[1]', '["Faigi 17:10; 19:29","Faigi 16:8"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 5, 'Ba mowaö-waö da''ö ba labaloi ndra''aga ba Deroa.[2]', '["Faigi 17:10; 19:29","Faigi 16:8"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 6, 'Ba me aefa mbaŵa roti si lö mu''aisöni andrö, ba moloyo ndra''aga, maröi Wilifi, ba lima bongi ndra''aga, ba makhamö ira ba Deroa, ba fitu bongima ba da''ö.', '["Faigi 17:10; 19:29","Faigi 16:8"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 7, 'Ba me luo migu, me owulo ndra''aga, ba wamoboto roti, ba fahuhuo Waulo khöra, sara wongi aefa ö edöna mofanö ia; ba i''aragö huhuonia, irege talu mbongi.[3]', '["KorI 16:2; Faigi 2:42,46"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 8, 'Ba oya wandru ba mbate''e andrö, ba zi sagötö yaŵa, ba zowulo ira.', '["KorI 16:2; Faigi 2:42,46"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 9, 'Ba dumadao ba zandrela nono matua, Oitikho döi, ba mörö sibai, me i''aragö huhuonia Faulo, ba me no abölö mörö ia, ba aekhu tou ia, dua götö wa''alaŵa; ba lafazaŵa ia, no mate.', '[]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 10, 'Ba möi tou Waulo, ifalögu ia ba dotonia, italagui, imane: Böi mifagua-gua, so sa nosonia.[4]', '["SalI 17:21"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 11, 'Ba ifuli ia yaŵa, iboboto roti, ba manga, ba ara na fahuhuo ia, irege moluo, ba mofanö ia.', '[]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 12, 'Ba la''ohe nono matua no mege, auri, ba tenga ha ma''ifu terara dödö.', '[]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 13, 'Ba ya''aga, ba mowaö-waö baowo, moloyo ndra''aga ba Gaso, ba wangai khöma Faulo, ba da''ö, me no imanö wangohonogöi, me edöna itörö tanö.', '["Faigi 18:21; 21:4,12"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 14, 'Ba me ikhamö ndra''aga ba Gaso, ba matema ia, ba marugi Mitilene.', '["Faigi 18:21; 21:4,12"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 15, 'Ba moloyoga moroi ba da''ö, ba mahemolu ö, ba marugi gamaudu Khio; ba sara wongi aefa da''ö, ba masaŵa Zamo, ba mahemolu ö, ba marugi Mileti.', '["Faigi 18:21; 21:4,12"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 16, 'Noa sa ihonogöi Faulo, italu''i Nefeso, fa lö arörö ia ba Azia; aösö ia; omasi ia ba Yeruzalema so ia na luo wendrakose, na tola ikhamö.[5]', '["Faigi 18:21; 21:4,12"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 17, 'Ba moroi ba Mileti, ba ifatenge ba Nefeso, ifakaoni''ö zatua mbanua.', '[]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 18, 'Ba me no möi ira khönia ba imane khöra: Mi''ila, he uwisa ba khömi, ero ma''ökhö, iotarai luo me uhundragö danö Azia.[6]', '["Faigi 18:19; 19:10","Ayati 3"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 19, 'Enoni Zo''aya ndra''o, ma''ifu lö si fayaŵa ndra''o, mowöi daŵa hörögu, ba so wanandraigö, si göna ndra''o, ba wamagönaisi niha Yehuda ya''o.[7]', '["Faigi 18:19; 19:10","Ayati 3"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 20, 'Mi''ila he uwisa, wa lö nitahagu soguna khömi, si lö u''ombakha''ö khömi, si lö ufobawa lala khömi, ba zi so niha sato ba yomo göi,', '["Faigi 18:19; 19:10","Ayati 3"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 21, 'wamaduhu''ö ba niha Yehuda ba ba Ndrawa Heleni famalalini era-era khö Lowalangi, awö wamati khö Zo''aya ya''ita, Yesu Keriso.', '["Faigi 18:19; 19:10","Ayati 3"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 22, 'Ba hiza iada''e, usaŵa Yeruzalema, amaedola zi so ba wesu dödögu; hadia zi göna ndra''o ba da''ö, ba lö u''ila,[8]', '["Faigi 18:21; 19:21","Faigi 9:16; 21:4,11","Faigi 21:13"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 23, 'baero nifaduhu''ö Geheha ni''amoni''ö khögu, ba mbanua misa, iŵa''ö, ibalo-baloi ndra''o böbö ba famakao.[9]', '["Faigi 18:21; 19:21","Faigi 9:16; 21:4,11","Faigi 21:13"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 24, 'Ba lö ba dödögu nosogu, lö itörö ligu na i, ba wango''ozui lalagu, awö halöŵögu andrö, nitemagu khö Zo''aya, Yesu, famaduhu''ö turia somuso dödö, turia wa''ebua dödö Lowalangi andrö.[10]', '["Faigi 18:21; 19:21","Faigi 9:16; 21:4,11","Faigi 21:13"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 25, 'Ba hiza sa, u''ila, lö''ö sa''ae fa''ila bawa ita, dozi ami nitörögu, wangombakha banua Lowalangi andrö.', '["TimI 4:16; FetI 5:2","Mat 7:16"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 26, 'Andrö ufaduhu''ö khömi ma''ökhö andre, lö horögu ba ndrora fefu.', '["TimI 4:16; FetI 5:2","Mat 7:16"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 27, 'Lö''ö sa nitahagu, fa lö u''ombakha''ö khömi gera-era Lowalangi fefu.', '["TimI 4:16; FetI 5:2","Mat 7:16"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 28, 'Andrö mifaigi-faigi dödömi, ba mifaigi-faigi nikubaloi andrö fefu, ba nifataro Geheha ni''amoni''ö ya''ami samaigi-maigi, ba wokubaloi banua Zo''aya andrö, nihölinia khönia donia.[11]', '["TimI 4:16; FetI 5:2","Mat 7:16"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 29, 'u''ila, na no mofanö ndra''o, ba so moroi baero nasu gatua samara''u, si möi khömi, ba lö alimagö khöra nikubaloi andrö.[12]', '["TimI 4:16; FetI 5:2","Mat 7:16"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 30, 'Ba so göi niha si otarai khömi, solau huhuo si tefuyu, ba wondrönisi khöra nifahaö.', '["Heb 13:7"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 31, 'Andrö, böi miförö, mitörö-törö tödömi: medölu fakhe wa''ara, bongi ma''ökhö, ba lö nibatogu wamarou tödömi dozi ami, mowöi daŵa hörögu ba da''ö.[13]', '["Heb 13:7"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 32, 'Ba iada''e, ba utou''ö ami ba danga Lowalangi ba ba daroma li fa''ebua dödönia andrö, khönia, sangila manga''aro''ö tödömi, sangila mame''e khömi ondröita andrö, awö ni''amoni''ö andrö fefu.[14]', '["Faigi 14:3","KorI 9:12; MozIV 16:15; SamI 12:3","Faigi 18:3; KorI 4:12; TesI 2:9"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 33, 'Samösa lö ni''aluigu firö, ba ma ana''a, ba ma nukha.[15]', '["Faigi 14:3","KorI 9:12; MozIV 16:15; SamI 12:3","Faigi 18:3; KorI 4:12; TesI 2:9"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 34, 'Mi''ila ae, tangagu andre zangalui soguna khögu, awö zoguna ba nawögu.[16]', '["Faigi 14:3","KorI 9:12; MozIV 16:15; SamI 12:3","Faigi 18:3; KorI 4:12; TesI 2:9"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 35, 'Fefu gofu heza, ba no u''oroma''ö khömi, si manö wohalöŵö, ba nitolo zambö fa''abölö, ba böi olifu ita niŵa''ö Zo''aya, Yesu, me imane: "Ohahau dödö ba wame''e, moroi ba wanema."', '["Faigi 14:3","KorI 9:12; MozIV 16:15; SamI 12:3","Faigi 18:3; KorI 4:12; TesI 2:9"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 36, 'Ba me aefa iŵa''ö da''ö, ba ibalö duhini tou danö, mangandrö ia, ba fao ira fefu.[17]', '["Faigi 21:5","Ayati 25"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 37, 'Ba tobali abölö-bölö wege-egera fefu, ba latalagui mbagi Waulo, fa''ago bawa ira khönia.', '["Faigi 21:5","Ayati 25"]', NULL),
  (3394282, 'NT', 'Halöŵö Zinenge', 20, 38, 'Abölö abu dödöra ba niŵa''önia andrö, wa lö''ö sa''ae fa''ila bawa ira. Ba lafasao ia baowo.[18]', '["Faigi 21:5","Ayati 25"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 1, 'Ba me no ma''efa''ö ndra''aga khöra, ba moloyo ndra''aga, madölöga ba Go, ba mahemolu ö, ba marugi Rodo, ba moroi ba da''ö, ba masaŵa Watara.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 2, 'Ba me masöndra nowo, si möi ba Wönikia, ba möiga yaŵa ba moloyoga.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 3, 'Ba me oroma khöma Gifero, ba maröi ba gabera ba masaŵa Ziria, marugi si tou Diro; ba da''ö sa labokai nösi nowo.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 4, 'Ba me falukhaga nifahaö, ba tebatoga ba da''ö, fitu bongi. Ba laŵa''ö khö Waulo, moroi ba Geheha ni''amoni''ö, böi möi ia misi yaŵa, ba Yeruzalema.[1]', '["Faigi 11:12; 20:23"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 5, 'Ba me no fitu bongima, ba mahetaga, mofanöga, lafasaoga, dozi ira, awö ndra alawe, awö ndraono, irugi baero mbanua; ba mabalöduhini tou danö, baene, mangandröga.[2]', '["Faigi 20:36"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 6, 'Ba fabaliga, ba möiga baowo, ba ya''ira, ba lafuli ira miyomo.', '["Faigi 20:36"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 7, 'Ba ma''asiwai woloyo, ma''otarai ba Diro, masaŵa Wetolema''i, ma''owai dalifusö, ba ma''iagö khöra, sara wongi.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 8, 'Ba mahemolu ö, ba mofanöga, ba marugi Kaizaria. Ba möiga yomo khö Wilifo, sangombakha andrö, awö zi dafitu no, ba tebatoga khönia.', '["Faigi 2:17"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 9, 'Ba so nononia, öfa, ono alawe, sama''ele''ö.[3]', '["Faigi 2:17"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 10, 'Ba me ara ma''ifu ndra''aga, ba da''ö, ba so moroi si yaŵa ba Yudaia zama''ele''ö, Agabo döi.[4]', '["Faigi 11:28","Faigi 20:23"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 11, 'Ba möi ia khöma, ihalö mböbö talu Waulo, iböbö gahenia, awö dangania, ba imane: Da''ö niŵa''ö Geheha ni''amoni''ö: Lamanö dania wamöbö niha sokhö böbö talu andre niha Yehuda, ba Yeruzalema, ba latou''ö ba danga niha baero.[5]', '["Faigi 11:28","Faigi 20:23"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 12, 'Ba me marongo da''ö, ba mangandrö ndra''aga khö Waulo, awö mbanua da''ö, böi möi ia misi yaŵa, ba Yeruzalema.[6]', '["Mat 16:22"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 13, 'Ba itema lima Faulo, imane: Hadia khömi da''ö, wa mege-ege ami, wa mibusi dödögu? No aoha manö sa gölögu, tenga ha ba wame''e niböbö ya''o, ba wa''amate göi, ba Yeruzalema, na börö döi Zo''aya, Yesu.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 14, 'Ba me lö i''o''ö khöma, ba lö''ö sa''ae muhedega, mamane: Ya''itörö zomasi Zo''aya.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 15, 'Ba me aefa da''ö, ba mafa''anö ndra''aga, ba möiga misi yaŵa ba Yeruzalema.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 16, 'Ba möi awöma nifahaö, banua Kaizaria, ösa, solohe ya''aga ba zi möiga tome, khö Menaso, banua Gifero, nifahaö si no ara.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 17, 'Ba me no marugi Yeruzalema, ba omuso dödö dalifusö, me no soga.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 18, 'Ba mahemolu ö, ba i''ohega Faulo, we''amöi khö Yakobo, ba ahori so zatua.[7]', '["Faigi 15:13; Gal 1:19"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 19, 'Ba me no i''owai ira, ba izara-zara wangombakha, he iwisa Lowalangi ba niha baero, ba halöŵönia andrö.', '["Faigi 15:13; Gal 1:19"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 20, 'Ba ya''ira, me larongo, ba lasuno Lowalangi, ba lamane khönia: ö''ila ga''a, ha wa''oya ngahönö zi no mamati, ba oi la''o''ö sibai goroisa.[8]', '["Faigi 15:1","Faigi 16:3; Rom 10:4"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 21, 'Ba no te''ombakha''ö khöra, ba khömö andrö, öŵa''ö ba niha Yehuda fefu, si fatewu ba niha baero, la''erogö Moze; öŵa''ö khöra, böi laboto nonora, ba böi la''o''ö gamakhoita andrö.[9]', '["Faigi 15:1","Faigi 16:3; Rom 10:4"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 22, 'Ba he wisa ia? Lö fulitö, ato zowulo dania; larongo sa, wa no so''ö.', '["Faigi 15:1","Faigi 16:3; Rom 10:4"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 23, 'Ba o''ö da''e, niŵa''öma khöu: Daöfa khöma niha si so amabu''ula li,', '["Faigi 18:18","Faigi 15:20,29"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 24, 'khöra ha ya''ira, mifao da''ö, fahaogö''ö ndra''ugö, awöra, ba taha gahakhöŵa khöra, ena''ö lafatöwö''ö ira, ba la''ila mötö dozi, wa no faya ni''ombakha''ö khöra, ba khömö andrö, ba ötörö sa, ba khömö göi, lala wolo''ö oroisa.[10]', '["Faigi 18:18","Faigi 15:20,29"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 25, 'Ba ba zamati niha baero andrö, ba no mafa''ohe''ö zura, no mahonogöi, böi lababaya gö nadu ba do ba nitögi bagi ba fohorö.[11]', '["Faigi 18:18","Faigi 15:20,29"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 26, 'Ba ihalö awönia niha andrö Faulo, ba mahemolu ö, ba möi ia ba gosali, me no ifahaogö''ö ia, awöra, i''ombakha''ö wa''awai mbongi wangehao andrö, irugi tedozigö ira wame''e sumange andrö.[12]', '["MozIV 6:13,14"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 27, 'Ba me arakha irugi zi fitu bongi andrö, ba la''ila ia ba gosali niha Yehuda, banua Azia, ba la''ekhugö niha sato fefu, ba lara''u ia,', '["Faigi 6:13,14; Hez 44:7"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 28, 'mu''ao ira, lamane: He ya''ami, Iraono Gizeraeli, milului! da''e niha andrö, sondrozigö niha, gofu heza so ira, wamahaö ya''ira; bö''ö wamahaönia, bö''ö ba khöda, ba oroisa, ba ba naha andre. Ba no i''ohe na göi Ndrawa Heleni ba gosali, ra''iö naha ni''amoni''ö andre ibe''e.[13]', '["Faigi 6:13,14; Hez 44:7"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 29, 'So zangila mege Terofimo, banua Nefeso, awönia ba mbanua, ba lawai ni''ohe Waulo ba gosali.[14]', '["Faigi 20:4; TimII 4:20"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 30, 'Ba maoso dödö niha, samba banua manö, aekhu niha, ba lara''u Waulo, lasöbi ia baero gosali, ba la''okusi''ö bawandruhö.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 31, 'Ba labunu ia ena''ö, ba terongo si yaŵa khö gumandra zi hönö, ba zaradadu andrö, no fawuka Yeruzalema, samba banua manö.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 32, 'Ba i''anema''ö ihalö khönia zaradadu ba kumandra zi otu, isaŵa si tou khöra, fagohi.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 33, 'Ba irugi kumandra, ihalö ia, iŵa''ö, larate ia, dua rozi rate, ba isofu, ha niha ia ba hadia nilaunia.[15]', '["Faigi 20:23"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 34, 'Ba bö''ö niŵa''ö zi samösa, bö''ö niŵa''ö zi samösa, ba niha sato andrö. Ba me tebai irongo zi ndruhunia, ba wagua-guasa andrö, ba iŵa''ö, la''ohe ba hati.', '["Faigi 20:23"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 35, 'Ba me irugi nora, ba tobali la''osa''ö ia saradadu ba wa''abölö niha.', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 36, 'La''o''ö sa niha sato, mu''ao ira: Nitibo''ö ia![16]', '["Faigi 22:22; Luk 23:18"]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 37, 'Ba me la''ohe ba hati ena''ö Waulo, ba imane khö gumandra: Tola uŵa''ö khöu da''e?', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 38, 'Tenga sa Dawa Miserayi andrö ndra''ugö, sangekhugö niha, bohou na no andrö, solohe misa ba danö si mate si öfa ngahönö niha, sange''e andrö?', '[]', NULL),
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 39, 'Ba imane Faulo: Niha Yehuda ndra''odo, banua Dareso, banua si teturia, ma''ifu, ba Gilikia. Ba u''andrö khöu, tehe khögu wehede ba niha.[17]', '["Faigi 9:11"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3394283, 'NT', 'Halöŵö Zinenge', 21, 40, 'Ba me no itehe, ba i''agö mbosi nora Faulo, ifazaŵa dangania ba niha. Ba me no ahono sibai, ba muhede ia khöra, ba li Heberaio, imane:[18]', '["Faigi 12:17; 13:16; 19:33"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 1, '"He ya''ami, ira talifusö ba ira amagu, mifondrondrongo wamu''agu ba hulugu khömi iada''e.[1]', '["Faigi 7:2; 13:20"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 2, 'Ba me larongo,[2] ilau khöra li Heberaio, ba tedou na wa''ahonora, ba imane:[3]', '["Ayati 3–21: Faza 9:1–29; 26:9–18","Faigi 21:40"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 3, 'Niha Yehuda ndra''o, banua Dareso, ba Gilikia, ba ba mbanua da''e ebua ndra''o, ono zekola Gamalieli, no la''o''ö wa''abe''e goroisa khö ndra tua, wamahaö ya''o, hulö zolohu ndra''o ba ngawalö hadia ia khö Lowalangi, si mane ya''ami fefu na, ma''ökhö andre.[4]', '["Faigi 5:34","Faigi 8:3"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 4, 'No u''osisi lala andrö, irugi wamunu, no uböbö ndra matua, awö ndra alawe, ba no u''ohe ba gurunga.[5]', '["Faigi 5:34","Faigi 8:3"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 5, 'No si so ba mbörö khögu gere sebua, awö zatua mbanua fefu, ba nitemagu sura ba dalifusö, we''amöi ba Ndramaseko, ba wolohe ba Yeruzalema göi si so ba da''ö, niböbö, ena''ö te''otu''ö ira.', '["Faigi 5:34","Faigi 8:3"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 6, 'Ba ba wofanö andrö, me no ahatö ndra''o ba Ndramaseko, ba i''ozumagö göna ndra''o haga sabölö-bölö, moroi ba mbanua si yaŵa, so laluo.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 7, 'Ba alau tou ndra''o, ba danö, ba urongo li, imane khögu: He Saulo! He Saulo! hana wa ögohido?', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 8, 'Ba umane: Ha niha ndra''ugö, Tua? Ba imane khögu: Yesu ndra''o, banua Nazareta andrö, nigohiu.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 9, 'Ba la''ila sa haga andrö, awögu fao, ba lö larongo li zihede khögu andrö.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 10, 'Ba umane: He uwisa, Tua? Ba imane So''aya khögu: Faoso, ae ba Ndramaseko, ba da''ö dania laŵa''ö khöu fefu nihonogöi khöu, nilaumö.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 11, 'Ba lö u''ila niha, ba wa''abölö haga no mege, la''ohe dangagu awögu ba lala, ba urugi Ndramaseko.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 12, 'Ba so niha, Anania döi, sangata''ufi Lowalangi, solo''ö oroisa, si sökhi turia ba niha Yehuda fefu, si no fatewu ba Ndramaseko.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 13, 'Ba möi khögu da''ö, i''ondrasi ndra''o, ba imane khögu: He Saulo, talifusö, yagö mu''ila zui niha! Ba i''otarai da''ö, ba u''ila ia.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 14, 'Ba imane: Föna sa''ae ihonogöi Lowalangi ndra tuada, ena''ö aboto ba dödöu zomasi ia, ba ena''ö ö''ila zatulö andrö, ba ena''ö örongo linia, na muhede ia.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 15, 'Me samaduhu''ö ndra''ugö khönia dania ba niha fefu, öfaduhu''ö ni''ila höröu ba nirongo dögi dalingau.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 16, 'Ba iada''e, ba hana wa ara''ö? Faoso, fabayagö''ö idanö ndra''ugö ba fasasai''ö horöu, we''angaröfi li töi Zo''aya andrö.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 17, 'Ba me no ufulido ba Yeruzalema, me mangandrö ndra''o ba gosali, ba abeta nosogu,[6]', '["Faigi 9:26","Ayati 4","Faigi 7:57; 8:1","Faigi 9:15; 13:2"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 18, 'ba u''ila ia, ba imane khögu: Ta''i-ta''i, aliogö, heta''ö ba Yeruzalema, me lö''ö sa atö latema wamaduhu''ömö ya''o.', '["Faigi 9:26","Ayati 4","Faigi 7:57; 8:1","Faigi 9:15; 13:2"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 19, 'Ba umane: He Tua, no la''ila, sokuru samati khöu ndra''odo, samöbözi ya''ira, ba zekola misa,[7]', '["Faigi 9:26","Ayati 4","Faigi 7:57; 8:1","Faigi 9:15; 13:2"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 20, 'ba no la''ila, sodo ba ngai, me labunu Zitefano andrö, samaduhu''ö ya''ugö, ba omasido da''ö, ba u''irö''ö nukha zamunu ya''ia andrö.[8]', '["Faigi 9:26","Ayati 4","Faigi 7:57; 8:1","Faigi 9:15; 13:2"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 21, 'Ba imane khögu: Ae''e, ba niha baero ufatenge ndra''ugö, ba zaröu."[9]', '["Faigi 9:26","Ayati 4","Faigi 7:57; 8:1","Faigi 9:15; 13:2"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 22, 'Ba lafondrondrongo khönia irege da''ö, ba mu''ao ira, lamane: Nitibo''ö, niheta ba guli danö niha si manö! tenga sa si nangea auri ia.[10]', '["Faigi 21:36"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 23, 'Ba mu''ao-ao ira, latibo''ö tou nukhara ba lafazaumba gawu-gawu ba dalu mbanua.', '["Faigi 21:36"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 24, 'Ba iŵa''ö kumandra, la''ohe ba hati ia, i''oroi''ö, labözi, ba wanekhegö ya''ia, ena''ö irongo, hadia mbörö, wa lamanö we''ao-ao ba khönia andrö.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 25, 'Ba me no laböbö ia ba geu, ba wamözi ya''ia, ba imane Faulo khö gumandra zi otu, si so ba da''ö: Hadia, tola mibözi manö mbanua Roma, he lö muhuku?[11]', '["Faigi 16:37; 23:27"]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 26, 'Ba me irongo da''ö kumandra zi otu andrö, ba möi ia mu''ombakha''ö khö gumandra zi hönö, imane: Hadia nilaumö?', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 27, 'Banua Roma sa niha da''ö.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 28, 'Ba imane kumandra: Ya''odo andre, ba no ebua ube''e ana''a, fa banua andrö ndra''o.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 29, 'Ba i''anema''ö laböhöi ia sanekhegö ya''ia ena''ö. Ba ata''u göi gumandra, me no irongo, wa banua Roma ba me no irate.', '[]', NULL),
  (3393654, 'NT', 'Halöŵö Zinenge', 22, 30, 'Ba mahemolu ö, me edöna irongo zi ndruhu, hadia nibe''e niha Yehuda horönia, wangadugö ya''ia, ba ifa''efa''ögö rate, ba i''oroi''ö falukha gere sebua, awö zalaŵa rafe sebua fefu, ba i''ohe mitou Waulo, ifasao khöra.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 1, 'Ba inehegö zalaŵa rafe sebua Faulo, ba imane: He ya''ami, ira talifusö! Lö sinegu dödögu khögu, ba wolo''ö khö Lowalangi, irugi ma''ökhö andre.[1]', '["Faigi 22:1; 24:16"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 2, 'Ba iŵa''ö ere sebua, Anania, ba zi so ba da''ö, lafalisi mbawania.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 3, 'Ba imane khönia Faulo: Ifalisi dania ndra''ugö Lowalangi, bagolö nilau betua! Dumadao ndra''ugö wanguhuku ya''o, dali goroisa, ba ösawö goroisa, wanguma''ö, labözi ndra''o.[2]', '["Mat 23:27"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 4, 'Ba lamane si so ba da''ö: Hadia, ötandraŵaisi gere sebua andrö khö Lowalangi?', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 5, 'Ba imane Faulo: Lö u''ila, wa ere sebua ia, ga''a. Si manö sa ba zura: "Böi tandraŵaisi zatua mbanuami."[3]', '["MozII 22:28","Faigi 22:3; 26:5"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 6, 'Ba me i''ila Faulo, sadukaio ösa ba farizaio ösa, ba mu''ao ia ba zalaŵa rafe sebua, imane: He ya''ami, ira talifusö! Farizaio ndra''odo, ono warizaio; fanötöna femaoso zi mate andrö mbörö, wa tehuku ndra''odo.[4]', '["MozII 22:28","Faigi 22:3; 26:5"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 7, 'Ba me no iŵa''ö da''ö, ba tobali fagua-gua ira, warizaio zadukaio, ba fabali dödö zato.', '["Mat 22:23","Faigi 25:25; 5:39"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 8, 'Niŵa''ö zadukaio, ba lö femaoso ba lö mala''ika ba lö bekhu zi mate; ba faoma sa faduhu dödö warizaio ba da''ö.[5]', '["Mat 22:23","Faigi 25:25; 5:39"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 9, 'Ba tobali fagua-guasa sabölö-bölö, ba maoso zangila amakhoita ösa, farizaio, fasoso ira, lamane: Ma''ifu lö masöndra horö niha da''ö; ba he wisa, na no humede khönia mbekhu zi mate, ba ma mala''ika?[6]', '["Mat 22:23","Faigi 25:25; 5:39"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 10, 'Ba me no abölö-bölö wagua-guasa, ba ata''u gumandra, lasila Waulo, ba iŵa''ö möi mitou zaradadu, ba wamadöni ya''ia khöra, wolohe ba hati.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 11, 'Ba ba zi bongi andrö, ba möi khönia Zo''aya, imane: Böi ata''ufi! Hulö si mane famaduhu''öu hadia ia khögu ba Yeruzalema, si manö göi wamaduhu''öu dania ba Roma, lö tola lö''ö.[7]', '["Faigi 18:9; 19:21"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 12, 'Ba me no moluo, ba lafagölö-gölö ira börö niha Yehuda, la''elifi ira, lö manga ira ba lö labadu nidanö, irege no labunu Waulo.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 13, 'Töra öfa wulu ira, sangelifi ya''ira ba da''ö.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 14, 'Möi ira khö ndra ere sebua ba ba zatua mbanua, lamane: No ma''elifi sibai ndra''aga, lö mababaya hadia ia gö, irege no mabunu Waulo andrö.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 15, 'Andrö mifaŵa''ögö khö gumandra, ya''ami, awö zalaŵa rafe, yamufa''ohe''ö ia mitou khömi, hulö na edöna mirongo sibai na, hadia ia khönia; ba matarogö sa''ae, ba wamunu ya''ia, ba lala.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 16, 'Ba me irongo wamagönaisi andrö ono mbene''ö Waulo, ba möi ia ba hati, i''ombakha''ö khö Waulo.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 17, 'Ba humede Waulo khö gumandra zi otu, imane khönia: Ohe khö gumandra zi hönö nono matua andre, so niŵa''önia khönia.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 18, 'Ba i''ohe khö gumandra zi hönö, imane: No muhede khögu, Waulo andrö, nikuru, i''andrö khögu, u''ohe khöu nono matua andre, so niŵa''önia khöu.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 19, 'Ba idöni dangania kumandra, i''ohe ba zi ha ya''ira, ba isofu khönia: Hadia niŵa''öu khögu?', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 20, 'Ba imane: No mamagölö niha Yehuda, ba wangandrö khöu, ena''ö öfa''ohe''ö mitou khöra ba rafe mahemolu Waulo andrö, hulö na edöna lazofu-zofu na ena''ö, hadia ia khönia.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 21, 'Andrö böi fati lira; latarogö sa''ae ia, töra öfa wulu niha, banuara, no la''elifi ira, lö manga ira ba lö labadu nidanö, irege no labunu ia. Ba noa sa''ae lafa''anö ira, ba labaloi niŵa''öu.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 22, 'Ba ifofanö nono matua andrö kumandra, iŵa''ö khönia, böi i''ombakha''ö gofu ha ökhö, wa no ibokai khönia da''ö.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 23, 'Ba darua ifakaoni''ö kumandra zi otu, ba imane: Mifa''anö zaradadu, dua ngaotu, ba we''amöi ba Kaizaria, awö zi fakudo, fitu ngafulu, ba dua ngaotu zanoho,', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 24, 'na mörö niha; ba ndra mu''asogö kudo, ba wamakudo Faulo andrö, ba lahaogö wolohe ya''ia khö gumandru Felisi.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 25, 'Ba ifazökhi zura,', '["Faigi 21:33; 22:25","Faigi 22:30","Faigi 18:14,15","Faigi 24:8"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 26, 'imane: "Kalaudio Lisia khö gumandru Felisi si sökhi sibai tödö, ya''ahowu!', '["Faigi 21:33; 22:25","Faigi 22:30","Faigi 18:14,15","Faigi 24:8"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 27, 'Niha andrö, nira''u niha Yehuda, nibunura mena''ö, no u''efa''ö, me sodo awö zaradadu, me no urongo, wa banua Roma ia.[8]', '["Faigi 21:33; 22:25","Faigi 22:30","Faigi 18:14,15","Faigi 24:8"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 28, 'Ba usofu mena''ö mbörö wangadugöra ya''ia, ba u''ohe ba rafe khöra.[9]', '["Faigi 21:33; 22:25","Faigi 22:30","Faigi 18:14,15","Faigi 24:8"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 29, 'Ba usöndra, fagua-guasa ba goroisa khöra mbörö, wa la''adugö ia, ba lö fangadu börö wamunu, ba he börö worate ya''ia.[10]', '["Faigi 21:33; 22:25","Faigi 22:30","Faigi 18:14,15","Faigi 24:8"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 30, 'Ba me no mu''ombakha''ö khögu, so ba khöra zamagönaisi niha andrö, ba no ufa''ohe''ö ia khöu, ba no uŵa''ö göi ba zangadu andrö, ndramu''ombakha''ö khöu."[11]', '["Faigi 21:33; 22:25","Faigi 22:30","Faigi 18:14,15","Faigi 24:8"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 31, 'Ba lahalö sa''ae Waulo saradadu no mege, la''o''ö niŵa''ö khöra, la''ohe ia ba Gandrifati, ba zi bongi.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 32, 'Ba mahemolu ö, ba lafatenge awönia zi fakudo andrö, ba lafuli ira ba hati.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 33, 'Ba me no larugi Kaizaria da''ö, ba labe''e ba danga gumandru zura no mege, ba la''ohe göi khönia Waulo.', '[]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 34, 'Ba me no ibaso zura, ba isofu, ha banua ia, ba me irongo, wa banua Gilikia,[12]', '["Faigi 22:3"]', NULL),
  (3393655, 'NT', 'Halöŵö Zinenge', 23, 35, 'ba imane: usekhegö dania ndra''ugö, na no so göi zangadugö ya''ugö andrö. Ba i''oroi''ö, ba gödo Herode lataha Waulo.', '["Faigi 22:3"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 1, 'Ba lima bongi aefa da''ö, ba möi misi tou gere sebua andrö, Anania, awö zatua mbanua ösa, awö zi fahuhuo andrö, Teretulo; ya''ira zi möi khö gumandru, ba wangadugö Faulo.', '[]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 2, 'Ba lafakaoni''ö ia, ba ibörögö wangadugö ya''ia Teretulo,', '["Faigi 17:6","Faigi 23:30"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 3, 'imane: Ohahau sibai dödöma barö mbawau, ba wa''oya manö zi sökhi ba mbanua andre, me no sökhi dödöu khöra, ya''ugö Felisi, si sökhi sibai tödö, lö mabini''ö, gofu heza soga, lö mamalö-malö; ma''andrö saoha gölöu.', '["Faigi 17:6","Faigi 23:30"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 4, 'Ba fa lö urörö ndra''ugö, ba u''andrö khöu, öfondrondrongo khöma ma''ifu, ba wa''ebolo dödöu andrö.', '["Faigi 17:6","Faigi 23:30"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 5, 'Noa sa masöndra, wa no fökhö sebua niha andrö, samagua manö niha Yehuda andrö fefu, ba guli danö misa, ma''asagörö; satua zi faehu huku andrö, banua Nazareta, ia.[1]', '["Faigi 17:6","Faigi 23:30"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 6, 'Noa sa göi itandraigö i''ohe ba gosali zalakha, ba no mara''u ia,', '["Faigi 17:6","Faigi 23:30"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 7, 'ba so moroi si yaŵa Lisia andrö, kumandra, abölö ira, ba lafadöni ba dangama.', '["Faigi 17:6","Faigi 23:30"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 8, 'khönia tola örongo fefu mbörö wangadugöma ya''ia, na ösofu.[2]', '["Faigi 17:6","Faigi 23:30"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 9, 'Ba lanönö niha Yehuda, lafaduhu''ö niŵa''önia.', '[]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 10, 'Ba itema lira Faulo, me ifazaŵa dangania khönia kumandru, tandra wa tola muhede ia, imane: Me u''ila, no ara, ha me uga fakhe sa''ae, sanguhuku ndra''ugö ba mbanua andre, ba lö aiŵö ndra''o wamu''a ba hulugu esuanö andrö khögu,', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 11, 'me tola ösofu, wa lö töra felendrua wongi, me sodo moroi si tou, me möido ba Yeruzalema, ba wangandrö.', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 12, 'Ba lö ni''ilara ya''o ba gosali, wa fahuhuo ndra''o ba niha bö''ö, ba ma mangekhugö niha, ba lö''ö göi ba zekola ba lö''ö göi ba mbanua misa.[3]', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 13, 'Ba tebai göi la''ombakha''ö khöu niböbögöra khögu iada''e.', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 14, 'Ba lö ubini''ö khöu da''ö, wa utörö lala da''ö, niŵa''öra si faehu huku, wamosumange Lowalangi ndra tuama, wamati fefu nisura ba zura goroisa ba ba zura zama''ele''ö.[4]', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 15, 'Ba so khögu wanötöna khö Lowalangi, si so khöra göi, wa so wemaoso zi mate, he satulö, ba he si lö atulö.[5]', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 16, 'Andrö uforege göi, lö mamalö-malö, fa lö itegudo tödögu, he ba khö Lowalangi, ba he ba niha.[6]', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 17, 'Ba noa sa möido, me no ara, ba wolohe ame''ela ba mbanuama, ba ba wame''e sumange;[7]', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 18, 'ba da''ö la''ila sa ndra''o niha Yehuda ösa, banua Azia, me utörö wangehao andrö, ba gosali, tenga ba zi no ato niha, ba tenga ba wagua-guasa;[8]', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 19, 'ya''ira zi lö tola lö so ba da''e khöu ena''ö, ba wangadu, na so hadia ia gesuanögu khöra.', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 20, 'Ma ndramuŵa''ö da''e, hadia nisöndrara si lö atulö, me sodo ba rafe sebua;', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 21, 'atö na ba zi sambua li andrö, niŵa''ögu, me sodo khöra ba da''ö no, me umane: Femaoso zi mate mbörö, wa tehuku ndra''o khömi ma''ökhö![9]', '["Faigi 25:8","Faigi 26:22 b.t.","Faigi 26:6–8; Dan 12:2","Faigi 23:1; KorII 1:12","Faigi 21:24; Rom 15:25 b.t.","Faigi 21:27","Faigi 23:6"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 22, 'Ba ifazaŵa khöra mbongi Felisi, me no aboto ba dödönia he wisa lala da''ö, ba imane: Na möi mitou Lisia, kumandra andrö, ba usofu da''ö khömi.[10]', '["Faigi 23:26"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 23, 'Ba iŵa''ö khö gumandra, latarogö Waulo, lahaogö khönia, ba böi latenaŵa, na so zi möi ngoni-ngoninia, sahatö khönia.[11]', '["Faigi 27:3; 28:16"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 24, 'Ba lö ara tö, ba möi Welisi, awö Derusila, fo''omonia, niha Yehuda, ifakaoni''ö Waulo, ifondrondrongo khönia wamati andrö khö Keriso Yesu.', '[]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 25, 'Ba me itörö linia wa''atulö dödö ba fa böi mohorö ba fanguhuku andrö dania, ba tokea Welisi, ba imane: Ofanö iada''e, igamöi lö aröröŵagu dania, ba ufakaoni''ö ndra''ugö.[12]', '["Faigi 10:42"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 26, 'Ba idöna-döna göi ba ba''ö, ibe''e khönia gana''a Faulo; andrö asese ifahalö''ö, ba wahuhuosa khönia.', '["Faigi 25:9,14"]', NULL),
  (3393657, 'NT', 'Halöŵö Zinenge', 24, 27, 'Ba me no irugi mendrua fakhe, ba te''ali Welisi, Forokio Feso wangalinia. Ba omasi Welisi, ebua dödö niha Yehuda khönia, ba iröi furi Waulo, nirate.[13]', '["Faigi 25:9,14"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 1, '. Tölu bongi Weso ba danö, ba möi ia misi yaŵa ba Yeruzalema, moroi ba Kaizaria.[1]', '["Faigi 24:27; 23:23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 2, 'Ba la''ondrasi ia ere sebua ba salaŵa niha Yehuda, ba khö Waulo andrö, la''andrö khönia,[2]', '["Faigi 24:1","Faigi 23:15"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 3, 'fa''ebua dödönia khöra laŵa''ö, ena''ö ifahalö''ö miyaŵa ba Yeruzalema; labunu ia ba lala, dödöra.[3]', '["Faigi 24:1","Faigi 23:15"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 4, 'Ba iŵa''ö khöra Feso, tetaha-taha Waulo ba Kaizaria ba ya''ia göi, ba alio ifuli ia ba da''ö.', '["KorI 4:13; Faigi 17:6"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 5, 'Ba ha niha sa zalaŵa ba khömi, iŵa''ö, ba ndrafao we''amöi misi tou, ba wangadugö niha da''ö, na so hadia ia zalania.[4]', '["KorI 4:13; Faigi 17:6"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 6, 'Ba mato ŵalu bonginia khöra, fulu bongi zara sibai, ba möi ia misi tou ba Kaizaria, ba sara wongi aefa da''ö, ba dumadao ia ba dadaoma zanguhuku, ba i''oroi''ö Waulo.[5]', '["Faigi 21:28 b.t."]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 7, 'Ba me so ia, ba lafasui ia niha Yehuda, si no möi mitou, si otarai Yeruzalema, oya ngawalö laböbögö khönia sala sebua, si tebai la''oroma''ö ngamohi,[6]', '["Faigi 24:13","Faigi 24:12; 28:17"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 8, 'me ibu''a ba hulunia Faulo; lö nisaŵönia oroisa ba niha Yehuda, iŵa''ö, ba lö horönia ba gosali ba lö''ö göi khö kaizaro.[7]', '["Faigi 24:13","Faigi 24:12; 28:17"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 9, 'Ba omasi Weso, na ebua dödö niha Yehuda khönia, ba itema li Waulo, imane: Hadia, omasi''ö möi misi yaŵa ba Yeruzalema, na ba da''ö tehuku ndra''ugö, ba zi so ya''o, ba zala andrö?', '[]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 10, 'Ba imane Faulo: Föna dadaoma zanguhuku khö kaizaro so ndra''o, lö tola tenga ba da''e tehuku ndra''o. Lö horögu ba niha Yehuda, noa sa aboto sibai ba dödöu göi.[8]', '["Faigi 22:28","Faigi 26:32"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 11, 'Ba so atö horögu, ba na no ulau hadia ia, börö wamunu ya''o, ba lö uwösi-wösido, na nibunu ndra''o. Ba na faya niböbögö da''e khögu, ba tebai labe''e buala ndra''o khöra. Ufuli khö kaizaro.[9]', '["Faigi 22:28","Faigi 26:32"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 12, 'Awena fahuhuo Weso ba nawönia ba rafe, ba imane: khö kaizaro no öfuli, ba khö kaizaro möi''ö.[10]', '["Faigi 27, 24"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 13, '. Ba lö ara furi ö, ba möi ba Kaizaria razo, Agerifa ba Berenike (ngambatönia), ba wangondrasi Feso.', '[]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 14, 'Ba me ara ma''ifu ira ba da''ö, ba i''ombakha''ö Feso huhuo andrö ba khö Waulo, khö razo andrö, imane: So niha niröi Welisi furi, nikuru.', '["Faigi 23:29; 26:8,23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 15, 'La''ondrasido ere sebua ba satua mbanua ba niha Yehuda, me sodo ba Yeruzalema, ba khönia, la''andrö wame''e huku khönia.', '["Faigi 23:29; 26:8,23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 16, 'Ba u''ombakha''ö khöra, tenga huku ba Ndrawa Roma, la''etu''ö manö huku niha, na lö lafatutu wawa ira ua zangadu ni''adugö, na lö mufolala khönia wamu''a ba hulunia niböbögö khönia.', '["Faigi 23:29; 26:8,23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 17, 'Ba me no falukha ira ba da''e, ba ma''ifu lö u''aragö, ha sara wongi, ba mudadaodo ba dadaoma zanguhuku, ba u''oroi''ö niha andrö.', '["Faigi 23:29; 26:8,23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 18, 'Ba me so zangadugö ya''ia, ba ma''ifu lö la''ila la''ombakha''ö sala,', '["Faigi 23:29; 26:8,23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 19, 'nidöna-dönagu, ha fagua-guasa ba wamosumangera Lowalangi la''ombakha''ö, salania, ba ba khö Yesu andrö, si no mate, niŵa''ö Waulo no ifuli auri.[11]', '["Faigi 23:29; 26:8,23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 20, 'Ba me lö u''ila he uwisa ba huhuo andrö ba da''ö, ba usofu khönia, na edöna möi ia ba Yeruzalema, na andrö lahuku ia ba da''ö.', '["Faigi 23:29; 26:8,23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 21, 'Ba me i''andrö Faulo lataha ia, irege i''etu''ö huku kaizaro, ba u''oroi''ö, lataha ia, irege ufa''ohe''ö ia khö kaizaro.', '["Faigi 23:29; 26:8,23"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 22, 'Ba imane Agerifa khö Weso: Omasido urongo göi niŵa''ö niha andrö.', '[]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 23, 'Ba sara wongi aefa da''ö, ba so Agerifa ba Berenike, ebua sibai lakhömi, möi ira ba kato, awö gumandra, awö zalaŵa mbanua, ba i''oroi''ö Feso, la''ohe Waulo.', '[]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 24, 'Ba imane Feso: He razo, Agerifa, ba ya''ami fefu, si so ba da''e, awöma! Mi''ila da''e; no mangandrö khögu niha Yehuda sato ba khönia, ba Yeruzalema ba ba da''e göi, mu''ao ira, tenga ni''orifi sa''ae.[13]', '["Faigi 22:22","Faigi 23:9","Faigi 26:3,27","Faigi 25:9,14"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 25, 'Ba me no aboto ba dödögu, lö horönia, börö wamunu ya''ia, ba me no ifuli göi khö kaizaro, ba no uhonogöi, lafa''ohe''ö ia.[14]', '["Faigi 22:22","Faigi 23:9","Faigi 26:3,27","Faigi 25:9,14"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 26, 'Ba lö nirongogu si ndruhu, ba khönia, nisuragu khö zokhö ya''ita, ena''ö. Andrö no ufasao ia khömi, ba oföna khöu, ya''ugö razo Agerifa, ena''ö falukhado nisura, na no musekhegö.[15]', '["Faigi 22:22","Faigi 23:9","Faigi 26:3,27","Faigi 25:9,14"]', NULL),
  (3393659, 'NT', 'Halöŵö Zinenge', 25, 27, 'Ba dödögu sa, tenga lala, na tafa''ohe''ö nikuru ba lö ta''ombakha''ö mbörö wangadugö ya''ia.[16]', '["Faigi 22:22","Faigi 23:9","Faigi 26:3,27","Faigi 25:9,14"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 1, 'Ba imane Agerifa khö Waulo: Latehe khöu, öbu''a ba hulumö.', '[]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 2, 'He razo, Agerifa, omuso dödögu, me tola ubu''a ba hulugu ma''ökhö andre, fönau, fefu niböbögö niha Yehuda khögu.', '["Mat 10:18","Faigi 22:3 b.t.; Gal 1:13 b.t.","Faigi 23, 6"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 3, 'Me no ö''ila sibai fefu huku ba niha Yehuda, awö nifadöni andrö, ba u''andrö khöu, bologö dödöu, wamondrongo khögu.', '["Mat 10:18","Faigi 22:3 b.t.; Gal 1:13 b.t.","Faigi 23, 6"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 4, 'Bua-buagu i''otarai iraono ndra''o, nilaugu i''otarai mböröta, ba khöma ba Yeruzalema, ba no la''ila niha Yehuda fefu;[2]', '["Mat 10:18","Faigi 22:3 b.t.; Gal 1:13 b.t.","Faigi 23, 6"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 5, 'me no la''ila ndra''o, i''otarai föna sa''ae (na edöna ira lafaduhu''ö), wa no u''o''ö wondrege wa''abe''e huku, ba wamosumange Lowalangi ba khöda, wa farizaio ndra''odo.[3]', '["Mat 10:18","Faigi 22:3 b.t.; Gal 1:13 b.t.","Faigi 23, 6"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 6, 'Ba iada''e, ba lahuku ndra''o, börö wanötöna amabu''ula li andrö, nifabu''u Lowalangi khö ndra tuada,[4]', '["Faigi 13:32; 28:20","Faigi 24:14,15","Faigi 4:2","Faigi 22, 20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 7, 'ni''alui zi felendrua tua khöma, fogamö ya''ia, bongi ma''ökhö la''owölö-ölögö wamasumange Lowalangi ba da''ö. Fanötöna da''ö mbörö, ya''ugö razo, wa la''adugö ndra''odo niha Yehuda.[5]', '["Faigi 13:32; 28:20","Faigi 24:14,15","Faigi 4:2","Faigi 22, 20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 8, 'Hadia wa laŵa''ö ba khömi, tebai faduhu dödö niha, na isusugi zi mate Lowalangi?[6]', '["Faigi 13:32; 28:20","Faigi 24:14,15","Faigi 4:2","Faigi 22, 20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 9, 'Noa sa uŵa''ö tödögu, ni''abölögö wangöhöndrögö töi Yesu, banua Nazareta andrö.', '["Faigi 13:32; 28:20","Faigi 24:14,15","Faigi 4:2","Faigi 22, 20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 10, 'Ba ulau sa göi ba Yeruzalema; ba ato ni''amoni''ö nibe''egu ba gurunga, nitehe ndra ere sebua khögu: ba na labunu ira, ba manehe ndra''odo.[7]', '["Faigi 13:32; 28:20","Faigi 24:14,15","Faigi 4:2","Faigi 22, 20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 11, 'Ba ba zekola misa fefu, ba asese ulau mbalögu khöra, uforege khöra, irege manandraŵa ira, si lö awawö wönugu khöra, ba ugohi ira, urugi göi mbanua baero.', '["Faigi 13:32; 28:20","Faigi 24:14,15","Faigi 4:2","Faigi 22, 20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 12, 'Ba möido ba Ndramaseko, ba zi manö, no latehe khögu ira ere sebua, no labe''e zura.', '["Faigi 9, 3 b.t.","Faigi 22:15; Gal 1:12","Faigi 22:21; Yer 1:8,18,19","Yes 42:7; Kol 1:12—14; Faigi 20:32"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 13, 'Ba laluo, ya''ugö razo, ba u''ila ba lala, moroi ba mbanua si yaŵa haga, abölö moroi ba haga luo, ifasui ndra''odo, awö zi fao khögu ba lala.', '["Faigi 9, 3 b.t.","Faigi 22:15; Gal 1:12","Faigi 22:21; Yer 1:8,18,19","Yes 42:7; Kol 1:12—14; Faigi 20:32"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 14, 'Ba alauga tou ba danö; ba urongo li, sihede, imane khögu ba li Heberaio: He Saulo! He Saulo! hana wa ögohido? Afökhö khö khöu, na fabörö''ö ba dukotuko andrö.[8]', '["Faigi 9, 3 b.t.","Faigi 22:15; Gal 1:12","Faigi 22:21; Yer 1:8,18,19","Yes 42:7; Kol 1:12—14; Faigi 20:32"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 15, 'Ba umane: Ha niha ndra''ugö, Tua? Ba imane So''aya; Yesu ndra''o, nigohiu.', '["Faigi 9, 3 b.t.","Faigi 22:15; Gal 1:12","Faigi 22:21; Yer 1:8,18,19","Yes 42:7; Kol 1:12—14; Faigi 20:32"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 16, 'Ba faoso, zizio. Andrö u''oroma''ö ndra''o khöu, ba wangohonogöi ya''ugö enoni ba samaduhu''ö ni''ila höröu, awö ni''oroma''ögu khöu dania.[9]', '["Faigi 9, 3 b.t.","Faigi 22:15; Gal 1:12","Faigi 22:21; Yer 1:8,18,19","Yes 42:7; Kol 1:12—14; Faigi 20:32"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 17, 'Ba u''efa''ö ndra''ugö ba danga mbanuami ba ba danga niha baero, ba nifatengegu ya''ugö,[10]', '["Faigi 9, 3 b.t.","Faigi 22:15; Gal 1:12","Faigi 22:21; Yer 1:8,18,19","Yes 42:7; Kol 1:12—14; Faigi 20:32"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 18, 'ba wamokai höröra ena''ö laröi zögömi-gömi, ba ena''ö lafuli ira ba haga, ena''ö laröi wa''abölö Gafökha, ba lafuli ira khö Lowalangi, ena''ö latema wangefa horö ba ondröita andrö, awö ni''amoni''ö andrö, wamati khögu.[11]', '["Faigi 9, 3 b.t.","Faigi 22:15; Gal 1:12","Faigi 22:21; Yer 1:8,18,19","Yes 42:7; Kol 1:12—14; Faigi 20:32"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 19, 'Andrö lö u''ositengagö gangilata andrö, soroi sorugo ya''ugö razo Agerifa,[12]', '["Gal 1:16","Faigi 9:20; 28:29; 20:21"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 20, 'mangombakha ndra''o, si oföna ba mbanua Ndramaseko ba ba Yeruzalema ba ba danö Yudaia ma''asagörö ba ba niha baero, ena''ö lafalalini gera-erara ba ena''ö lafuli ira khö Lowalangi, wanga''asogö bua-bua si nangea bua-bua wamalalini era-era.[13]', '["Gal 1:16","Faigi 9:20; 28:29; 20:21"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 21, 'Da''ö mbörö, wa lara''u ndra''o niha Yehuda, me sodo ba gosali, wa latandraigö wamunu ya''o.[14]', '["Faigi 21:30,31","Luk 24:44 b.t.","Luk 24:26 b.t.; 2:32; KorI 15:4,20; Faigi 13:47"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 22, 'Ba me no itolodo Lowalangi, andrö sodo irege ma''ökhö andre, ba mamaduhu''ö ndra''o ba ndraono ba ba zatua; lö ni''ombakha''ögu hadia ia baero niŵa''ö zama''ele''ö andrö, salua dania, ba he baero niŵa''ö Moze,[15]', '["Faigi 21:30,31","Luk 24:44 b.t.","Luk 24:26 b.t.; 2:32; KorI 15:4,20; Faigi 13:47"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 23, 'wa nifakao Keriso, awö wa no ya''ia zi föföna ba wemaoso zi mate andrö, sangombakha dania haga ba mbanua da''e, ba ba niha baero.[16]', '["Faigi 21:30,31","Luk 24:44 b.t.","Luk 24:26 b.t.; 2:32; KorI 15:4,20; Faigi 13:47"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 24, 'Ba me imanö wamu''a ba hulunia, ba imane Feso, ebua linia: Owöhö''ö Faulo! ifowöhö ndra''ugö sura, soya sibai andrö.', '[]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 25, 'Ba imane Faulo: Tenga sowöhö ndra''o, ya''ugö, Feso si sökhi! si ndruhu niŵa''ögu, soroi ba dödö.', '["Yoh 18:20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 26, 'I''ila sa da''ö razo, ba zi lö aiŵödo muhede; tebai manö faduhu dödögu, so ba da''ö zi lö irongo mege; tenga sa ba zi tobini telau da''ö no.[17]', '["Yoh 18:20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 27, 'Hadia, ya''ugö razo, Agerifa, faduhu dödöu ba niŵa''ö zama''ele''ö andrö?', '["Yoh 18:20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 28, 'u''ila, faduhu.', '["Yoh 18:20"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 29, 'Ba imane Faulo: Mangandrö ndra''o khö Lowalangi ena''ö; he aröu, ba he lö aröu, ba ena''ö tenga ha ya''ugö, ena''ö dozi samondrongo khögu ma''ökhö andre tobali si mane ya''odo andre, baero rate andre.[18]', '["Faigi 28:29"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 30, 'Ba maoso razo, awö gumandru, awö Mberenike andrö, awö zidadao ba da''ö ba ngaira.[19]', '["Faigi 25:23","Faigi 25:11"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 31, 'Laheta ira, fahuhuo, ba lamane: Lö nifazökhi niha andrö börö wamunu, ba he börö worate ya''ia.[20]', '["Faigi 25:23","Faigi 25:11"]', NULL),
  (3393660, 'NT', 'Halöŵö Zinenge', 26, 32, 'Ba imane Agerifa khö Weso: Tola ni''efa''ö niha andrö, na lö nifulinia khö kaizaro mena''ö.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 1, 'Ba me no muhonogöi, moloyo ndra''aga ba Gitalia,[1] ba labe''e Waulo, awö nikuru tanö bö''ö ösa, ba danga gumandra zi otu, Yulio döinia, kumandra zaradadu andrö khö kaizaro.[2]', '["Italia no sambua danö si so negara Italia ma''ökhö, heŵa''ae lö faudu fagölö wa''ebolora.","Faigi 25:12,21"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 2, 'Ba möiga ba nowo Gaderamiti, sedöna moloyo ba mbanua Azia[3] misa, ba moloyoga; awöma Garisaro, banua Makedonia, banua Desalonika.[4]', '["Azia eluahania tanöa Asia","Faigi 19:29"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 3, 'Ba mahemolu ö, ba marugi Zidona. Ba ebua dödö Yulio khö Waulo, fahuo-huo ia khönia, itehe khönia möi ia khö zi fahuwu khönia ba latolo-tolo ia.[5]', '["Faigi 24:23"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 4, 'Ba aefaga ba da''ö, ba matörö tou Gifero, me angi moroi föna.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 5, 'Ba me no matörö nasi tanö ba Gilikia ba tanö ba Wambilia, ba marugi si tou Mira, ba Likia.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 6, 'Ba da''ö isöndra kumandra andrö nowo Alesandria, sanaŵa Italia, ba i''ohega ba da''ö.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 7, 'Ba me ara lö sökhi-sökhi woloyo, me afökhö wondrugi Kenido, me lö ibe''ega angi, ba matörö tou Gereta, tanö ba Zalomone.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 8, 'Ba afökhö wanörö singa hulo, ba marugi naha sotöi "labua si sökhi", ba zahatö banua Lasaia.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 9, 'Ba no ara, ba no ata''u niha woloyo, me no aefa göi mbaŵa wamoni, ba ifangelama ira Faulo,[6]', '["KorII 11:26; MozIII 23:27 b.t."]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 10, 'imane khöra: He ya''ami, u''ila, göna ita famakao ba fa''ate''ala sebua ba woloyo andre, tenga ha ba nowo ba ba nösinia, ba nosoda göi.', '["KorII 11:26; MozIII 23:27 b.t."]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 11, 'Ba ifondrondrongo kumandra niŵa''ö durumudi,[7] awö niŵa''ö nakoda,[7] moroi ba niŵa''ö Waulo.', '["7.0 7.1 Itaria lafagölösi durumudi ba nakoda niha, bahiza no fabö''ö ira. Lafotöi durumudi (li Indonesia \"juru mudi\") zamofanö köfa, si sindro ba solohe amuri (li Indonesia \"kemudi\"). Ba li Inggris lakaoni ia \"pilot\". Lafotöi nakoda (li Indonesia \"kapten kapal\") niha si tobali högö zi sambua göfa. Ya''ia zangai angetula ba göfa ba khönia lafondrondrongo ya''ira sohalöŵö ba göfa, fao ba da''ö durumudi."]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 12, 'Ba lö sökhi labua andrö, ba wombaloi fa''aefa mbaŵa deu, ba ato zomasi ahetaga ba da''ö, ma tola marugi Wönika, ba wombaloi fa''aefa mbaŵa deu; labua ba Gereta da''ö, tanö ba gaekhula.', '["7.0 7.1 Itaria lafagölösi durumudi ba nakoda niha, bahiza no fabö''ö ira. Lafotöi durumudi (li Indonesia \"juru mudi\") zamofanö köfa, si sindro ba solohe amuri (li Indonesia \"kemudi\"). Ba li Inggris lakaoni ia \"pilot\". Lafotöi nakoda (li Indonesia \"kapten kapal\") niha si tobali högö zi sambua göfa. Ya''ia zangai angetula ba göfa ba khönia lafondrondrongo ya''ira sohalöŵö ba göfa, fao ba da''ö durumudi."]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 13, 'Ba me angi moroi raya, si lö abölö-bölö, ba lawai tola niŵa''öra andrö, ba ladöni zao ba lahatö''ö ira, wanörö singa Gereta.', '["7.0 7.1 Itaria lafagölösi durumudi ba nakoda niha, bahiza no fabö''ö ira. Lafotöi durumudi (li Indonesia \"juru mudi\") zamofanö köfa, si sindro ba solohe amuri (li Indonesia \"kemudi\"). Ba li Inggris lakaoni ia \"pilot\". Lafotöi nakoda (li Indonesia \"kapten kapal\") niha si tobali högö zi sambua göfa. Ya''ia zangai angetula ba göfa ba khönia lafondrondrongo ya''ira sohalöŵö ba göfa, fao ba da''ö durumudi."]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 14, '. Ba lö ara, ba ilabu tawuyu nangi, sotöi timu kaduo.', '["Sin 107:25 b.t."]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 15, 'Ba göna ba nowo ba tebai ilaŵa nangi, ba maböhöli, ba te''oloi''ö manö ndra''aga.[8]', '["Sin 107:25 b.t."]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 16, 'Ba me matörö hulo side-ide, sotöi Kalauda, ba ma''ifu tö, ba tebai masöbi dundraha.', '["Yon 1:5"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 17, 'Ba lasöbi yaŵa da''ö, ba lafake wangaro andrö, laböbö nowo. Ba ata''u ira tosake ba goso ene andrö, ba labunu loyo, ba te''oloi''ö manö nowo.', '["Yon 1:5"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 18, 'Ba me iforege khöma angi, ba mahemolu ö, ba latibo''ö nösi nowo.', '["Yon 1:5"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 19, 'Ba dua wongi aefa da''ö ba latibo''ö gama-gama ba nowo tangara.[9]', '["Yon 1:5"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 20, 'Ba me ara lö oroma luo ba lö oroma ndröfi, ba me iforege bade sabölö-bölö, ba ma''ifu lö''ö sa''ae madöna-döna auri ndra''aga.', '["Yon 1:5"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 21, 'Ba me no ara lö si manga, ba möi khöra Waulo, imane: He ya''ami fefu, ni''o''ö sa mena''ö niŵa''ögu no, fa böi aheta ita ba Gereta, fa lö göna ita famakao andre, awö wa''ate''ala andre.', '["Faigi 5:19","Faigi 23:11; 9:15","Faigi 28:1"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 22, 'Ba iada''e, ba u''andrö khömi, böi mibusi dödömi, lö''ö sa tekiko ami, ha niha ami, ha owo zafufu dania.', '["Faigi 5:19","Faigi 23:11; 9:15","Faigi 28:1"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 23, 'Noa sa möi khögu me owi mala''ika Lowalangi andrö, sokhö ya''o, ba si no möido enoni göi,[10]', '["Faigi 5:19","Faigi 23:11; 9:15","Faigi 28:1"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 24, 'ba no imane khögu: Böi ata''ufi, Faulo, lö tola lö örugi kaizaro, ba hiza, no ibe''e bualania khöu Lowalangi fefu nawöu soloyo.[11]', '["Faigi 5:19","Faigi 23:11; 9:15","Faigi 28:1"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 25, 'Andrö, böi mibusi dödömi, ya''ami fefu! Faduhu sa dödögu khö Lowalangi, itörö, si mane niŵa''ö khögu.', '["Faigi 5:19","Faigi 23:11; 9:15","Faigi 28:1"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 26, 'Ba lö''ö sa tola lö tosake ita ba hulo.[12]', '["Faigi 5:19","Faigi 23:11; 9:15","Faigi 28:1"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 27, 'Ba me no fele''öfa bongi sa''ae te''oloi''ö manö misa ndra''aga ba nasi Aderia, ba talu mbongi, ba laŵa''ö ono nowo, te ahatö danö.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 28, 'Ba lalau wanu''a wa''abakha, ba dua wulu ngaröfa. Ba me no moloyo ma''ifu tö, ba lafuli lalau, ba felelima ngaröfa.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 29, 'Ba ata''u ira, ma tosake ba gara, ba latibo''ö zao moroi ba gi''o nowo, öfa, ba omasi ira, na moluo.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 30, 'Ba la''alui ono nowo woloi moroi ba nowo, ladada ba nasi dundraha, fanguma''öra latibo''ö zao, moroi ba mbagi nowo;', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 31, 'ba imane Faulo khö gumandra andrö ba ba zaradadu andrö: Na aheta da''ö ba nowo, ba tebai auri ami.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 32, 'Awena la''eŵa daŵi-taŵi dundraha saradadu, la''ekhugö si tou.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 33, 'Ba gasa-gasa wa''amoluo, ba ifarou dödöra fefu Faulo, ba wemanga göra, imane: No fele''öfa bongi ma''ökhö mombalo-mbaloi ami, ba lö si manga, ma''ifu lö ni''ami.[13]', '["Sin 102:5","Luk 21:18"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 34, 'Andrö u''andrö khömi, mi''a gömi, fangorifimi sa da''ö; sara mbu sa lö''ö ba högömi fefu saekhu.[14]', '["Sin 102:5","Luk 21:18"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 35, 'Ba me aefa iŵa''ö da''ö, ba ihalö roti, i''aohasi gölö Lowalangi, fönara fefu, iboboto ba ibörötaigö manga.[15]', '["Mat 14:19"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 36, 'Awena terara dödöra fefu ba la''a göi göra.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 37, 'Ba dua ngaotu a fitu ngafulu a önö ndra''aga fefu ba nowo andrö.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 38, 'Ba me no abuso ira öra, ba lakaohasi nowo, latibo''ö si tou mbalazo, ba nasi.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 39, 'Ba me moluo, ba lö la''ila watahögö danö andrö. Ba la''ila zadöni asi, si so ene, ba mamagölö ira, ba da''ö ladölö nowo, na tola.', '[]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 40, 'Ba la''eŵa zinali zao, laröi ba nasi, ba fao ba da''ö göi latoto''ö mböbö gamuri andrö, lataŵi loyo sabu, tanö ba nangi ba la''angamurisi baene nowo.', '["KorII 11:25"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 41, 'Ba me göna ba dure, ba lasakeni, ba tetaru sa mbagi, lö maliŵa-liŵa, ba aboto gi''o ba wa''abölö ndrulu.[16]', '["KorII 11:25"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 42, 'Ba mamagölö zaradadu, ba wamunu nikuru andrö, fa böi moloi, na so zolangi, sanaŵa ene ena''ö.[17]', '["Faigi 16:27"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 43, 'Ba edöna i''orifi Waulo kumandra andrö, ba itenaŵa ira, ba iŵa''ö, oföna latibo''ö ira ba nasi sangila molangi,', '["Faigi 16:27"]', NULL),
  (3393661, 'NT', 'Halöŵö Zinenge', 27, 44, 'ba wogamö tanö, ba tanö bö''ö, ba ba wafa ösa ba ba gamotola nowo ösa. Ba tobali ahori auri ira ba zi manö, lakhamö danö.', '["Faigi 16:27"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 1, 'Ba me no aefaga ba wamakiko andrö, ba marongo, Melite döi hulo andrö.[1]', '["Faigi 27:26,39","KorII 11:27"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 2, 'Ba ebua sibai dödö niha bö''ö andrö khöma, la''ebua''ö galitö, ba lafonaha ndra''aga fefu, me no ilabu teu ba me o''afuga.[2]', '["Faigi 27:26,39","KorII 11:27"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 3, 'Ba me ira''ui zandra''u nono geu Faulo, ba wame''e ba galitö, ba hiza gulö, soloi ba wa''aukhu galitö, ira''u danga Waulo.', '[]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 4, 'Ba me la''ila niha andrö gulö andrö, sanaŵa-naŵa ba dangania, ba faoma lamane khö nawöra: Oroma, wa sange''e niha andrö, ibunu ia "solau balö", he ŵa''ae no aefa ia ba nasi.[3]', '["Luk 13:2; MozV 32:24; Amos 9:3"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 5, 'Ba ifazaumba ba galitö gulö andrö, ba lö göna ia hadia ia, safökhö.[4]', '["Mar 16:18"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 6, 'Ba labalo-baloi, ma abao, ba ma i''ozumagö manö alau tou ia ba mate. Ba ara labalo-baloi, ba la''ila, lö hadia zafökhö, si göna ia, ba tobali, Lowalangi ia laŵa''ö.[5]', '["Faigi 14:11"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 7, 'Ba ba zahatö ba mbanua andrö motanö gumandru hulo andrö, Fubelio döinia. Ba ifa''amöiga khönia, tölu bongi wa''ara ibe''e-be''e göma, wa''oböwö.', '[]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 8, 'Ba mofökhö nama Wubelio andrö, akhömö ba mendro dalu.', '[]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 9, 'Ba me aefa da''ö, ba mangondra göi zofökhö bö''ö ba hulo andrö, ba tefadöhö wökhöra.[7]', '["Mat 8:14; Yak 5:14 b.t.","Mat 4:24"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 10, 'Ba lafosumange sibai ndra''aga, ba me mofanöga, ba labe''e zoguna khöma.', '[]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 11, 'Ba tölu waŵa, ba moloyoga, ba nowo si no mombaloi fa''aefa mbaŵa deu ba hulo andrö, moroi ba Alesandria, sotandra sifaero andrö.', '["Faigi 21:4"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 12, 'Ba manaoga ba Zirakuso, tölu bongima ba da''ö.', '["Faigi 21:4"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 13, 'Ba me no mafasui, ba marugi Regio. Ba sara wongi aefa da''ö, ba ilau angi moroi raya, ba mahemolu ö, ba marugi Wuteoli.', '["Faigi 21:4"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 14, 'Falukhaga dalifusö ba da''ö, ba la''andrö khöma, ma''iagö khöra, fitu bongi; ba marugi sa''ae Roma.[8]', '["Faigi 21:4"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 15, 'Ba so moroi ba da''ö dalifusö, me no larongo ndra''aga, lafaondragö ndra''aga ba Gafiforo ba ba Daretabene. Ba me i''ila da''ö Faulo, ba isuno Lowalangi ba terara dödönia.[9]', '["Rom 1:10 b.t."]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 16, 'Ba me no marugi Roma, ba latehe khö Waulo, sambua nahania, awönia zaradadu samösa, sanaro ya''ia.[10]', '["Faigi 23:11; 27:3"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 17, 'Ba tölu bongi, ba ifalukha''ö Faulo zatua niha Yehuda, si so ba da''ö.', '[]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 18, 'Ba la''efa''ö ndra''o mena''ö da''ö, me no lasekhegö, me lö hadia ia mbörö wamunu ya''o khögu.[12]', '["Faigi 25:8","Faigi 26:32","Faigi 25:11,12","Faigi 26:6 b.t.; TimII 1:16"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 19, 'Ba me mamadaö niha Yehuda, ba lö lala bö''ö khögu, baero wamuli khö kaizaro, tenga sa taŵa''ö so ni''adugögu talifusögu.[13]', '["Faigi 25:8","Faigi 26:32","Faigi 25:11,12","Faigi 26:6 b.t.; TimII 1:16"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 20, 'Da''ö sa mbörö, wa ufakaoni''ö ami, ena''ö u''ila ami, ba fahuhuodo khömi: fanötöna Ndraono Gizeraeli andrö sa mbörö, wa terate ndra''o rate andre.[14]', '["Faigi 25:8","Faigi 26:32","Faigi 25:11,12","Faigi 26:6 b.t.; TimII 1:16"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 21, 'Ba lamane khönia: Lö''ö sa nitemama sura, ba khömö, moroi ba Yudaia, ba lö''ö göi si möi dalifusö, sangombakha hadia ia zi lö sökhi ba khöu.', '["Faigi 24:5,14; Luk 2:34"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 22, 'Ba niŵa''öma, sökhi marongo khöu, he wisa gera-erau; ba zi faehu huku andrö sa, ba no marongo, tefadaö manö niŵa''öra, fefu gofu heza so ira.[15]', '["Faigi 24:5,14; Luk 2:34"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 23, 'Ba la''ötö khönia mbongi, ba ato zi möi khönia ba zi mörö ia.', '[]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 24, 'Ba so ösa zi faduhu tödö ba niŵa''önia, ba so göi zi lö mamati.[17]', '["Faigi 17:4; 14:4","FetII 1:21","Yes 6:9 b.t.; Mat 13:14 b.t.","Faigi 13:46 b.t."]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 25, 'Ba me lö ha sara dödö, ba mofanö ira, me iŵa''ö zambua li Faulo, me imane: Duhu niŵa''ö Geheha ni''amoni''ö, ni''ombakha''ö Yesaya, sama''ele''ö andrö, khö ndra tuami,[18]', '["Faigi 17:4; 14:4","FetII 1:21","Yes 6:9 b.t.; Mat 13:14 b.t.","Faigi 13:46 b.t."]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 26, 'me imane: "Ae ba niha andrö, ba ömane: Mirongo tögi dalingami, ba lö''ö manö aboto ba dödömi, ba anehe hörömi, ba lö''ö manö mi''ila geluaha.[19]', '["Faigi 17:4; 14:4","FetII 1:21","Yes 6:9 b.t.; Mat 13:14 b.t.","Faigi 13:46 b.t."]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 27, 'Noa sa abe''e dödö niha andrö ba no afiso-fiso dögi dalingara, ba höröra, ba no lafakifu, fa lö la''ila höröra, fa lö larongo tögi dalingara, fa lö aboto ba dödöra, fa lö lafuli ira, fa lö u''orifi ira."', '["Faigi 17:4; 14:4","FetII 1:21","Yes 6:9 b.t.; Mat 13:14 b.t.","Faigi 13:46 b.t."]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 28, 'Ba ya''aboto ba dödömi, no tefa''ohe''ö ba niha baero wangorifi andrö, khö Lowalangi, ba mamondrongo göi da''ö.[20]', '["Faigi 17:4; 14:4","FetII 1:21","Yes 6:9 b.t.; Mat 13:14 b.t.","Faigi 13:46 b.t."]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 29, 'Ba me aefa iŵa''ö, ba mofanö niha Yehuda, wa''abölö wasosotara khö nawöra.', '[]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 30, 'Ba alo''o mendrua fakhe Waulo ba nomo andrö niwawalönia, ba ifa''amöi fefu zi möi yomo khönia.', '["Efes 6:18—20"]', NULL),
  (3393662, 'NT', 'Halöŵö Zinenge', 28, 31, 'Ituriagö mbanua Lowalangi ba ifahaö niha ba duria Zo''aya, Yesu, ma''ifu lö aiŵö ia ba lö mutenaŵa.[21]', '["Efes 6:18—20"]', NULL),
  (3414708, 'NT', 'Roma', 1, 1, 'Faulo zanura da''e, enoni Keriso Yesu, nikaoni sinenge, nituyu, ba wangombakha turia somuso dödö andrö khö Lowalangi,[1]', '["Gal 1:10,15 b.t.; HalZin 9:15","Tit 1:2,3; Luk 24:44","HalZin 2:30; 13:23","HalZin 13:33,34; Yoh 10:36; FetI 3:18","Faigi 15:15–19; Efes 3:8 b.t.","Faigi 9:24","KorI 1:2,3"]', NULL),
  (3414708, 'NT', 'Roma', 1, 2, 'nifafabu''u''önia föna ba zama''ele''ö andrö khönia, ba zura ni''amoni''ö,[2]', '["Gal 1:10,15 b.t.; HalZin 9:15","Tit 1:2,3; Luk 24:44","HalZin 2:30; 13:23","HalZin 13:33,34; Yoh 10:36; FetI 3:18","Faigi 15:15–19; Efes 3:8 b.t.","Faigi 9:24","KorI 1:2,3"]', NULL),
  (3414708, 'NT', 'Roma', 1, 3, 'turia Nononia andrö. Ma''uwu Dawido ba nga''ötö niha,[3]', '["Gal 1:10,15 b.t.; HalZin 9:15","Tit 1:2,3; Luk 24:44","HalZin 2:30; 13:23","HalZin 13:33,34; Yoh 10:36; FetI 3:18","Faigi 15:15–19; Efes 3:8 b.t.","Faigi 9:24","KorI 1:2,3"]', NULL),
  (3414708, 'NT', 'Roma', 1, 4, 'nifataro Ono Lowalangi, nibe''e fa''abölö, dali Geheha ni''amoni''ö, moroi ba wemaoso moroi ba ngai zi mate: Yesu Keriso, So''aya ya''ita.[4]', '["Gal 1:10,15 b.t.; HalZin 9:15","Tit 1:2,3; Luk 24:44","HalZin 2:30; 13:23","HalZin 13:33,34; Yoh 10:36; FetI 3:18","Faigi 15:15–19; Efes 3:8 b.t.","Faigi 9:24","KorI 1:2,3"]', NULL),
  (3414708, 'NT', 'Roma', 1, 5, 'Khönia no tatema wa''ebua dödö, awö halöŵö zinenge, ba wanga''asogö folo''ö famati andrö, ba niha fefu, ba wangebua töinia andrö.[5]', '["Gal 1:10,15 b.t.; HalZin 9:15","Tit 1:2,3; Luk 24:44","HalZin 2:30; 13:23","HalZin 13:33,34; Yoh 10:36; FetI 3:18","Faigi 15:15–19; Efes 3:8 b.t.","Faigi 9:24","KorI 1:2,3"]', NULL),
  (3414708, 'NT', 'Roma', 1, 6, 'Ba zi te''u''u göi ami, nikaoni Yesu Keriso;[6]', '["Gal 1:10,15 b.t.; HalZin 9:15","Tit 1:2,3; Luk 24:44","HalZin 2:30; 13:23","HalZin 13:33,34; Yoh 10:36; FetI 3:18","Faigi 15:15–19; Efes 3:8 b.t.","Faigi 9:24","KorI 1:2,3"]', NULL),
  (3414708, 'NT', 'Roma', 1, 7, 'ba ni''omasi''ö Lowalangi andrö fefu, nikaoni andrö, ni''amoni''ö, si so ba Roma. Yafalukha ami wa''ebua dödö ba fa''ohahau dödö khö Namada Lowalangi ba khö Zo''aya ya''ita, Yesu Keriso![7]', '["Gal 1:10,15 b.t.; HalZin 9:15","Tit 1:2,3; Luk 24:44","HalZin 2:30; 13:23","HalZin 13:33,34; Yoh 10:36; FetI 3:18","Faigi 15:15–19; Efes 3:8 b.t.","Faigi 9:24","KorI 1:2,3"]', NULL),
  (3414708, 'NT', 'Roma', 1, 8, 'Si föföna, ba usuno Lowalangigu andrö, dali Yesu Keriso, ba khömi fefu, me no teturiagö wamatimi andrö ba guli danö ma''asagörö.[8]', '["Faigi 16:19; KorI 1:4 b.t.; TesI 1:2,8","Fil 1:8","Faigi 15:23,32; HalZin 19:21","TesI 3:10","Amaed 11:25","Faigi 15:22","KorI 1:22–24","HalZin 28:31"]', NULL),
  (3414708, 'NT', 'Roma', 1, 9, 'Irongo sa ligu Lowalangi, si möido enoni tödögu, ba wangombakha turia somuso dödö andrö khö Nononia andrö, wa lö tebulö itörö, tödögu ami.[9]', '["Faigi 16:19; KorI 1:4 b.t.; TesI 1:2,8","Fil 1:8","Faigi 15:23,32; HalZin 19:21","TesI 3:10","Amaed 11:25","Faigi 15:22","KorI 1:22–24","HalZin 28:31"]', NULL),
  (3414708, 'NT', 'Roma', 1, 10, 'Lö aetu u''andrö, na mangandrö ndra''o, ma atö salöfögu samuza, ma aoha gölö Lowalangi, möi ndra''o khömi.[10]', '["Faigi 16:19; KorI 1:4 b.t.; TesI 1:2,8","Fil 1:8","Faigi 15:23,32; HalZin 19:21","TesI 3:10","Amaed 11:25","Faigi 15:22","KorI 1:22–24","HalZin 28:31"]', NULL),
  (3414708, 'NT', 'Roma', 1, 11, 'Humulu sa dödögu wamaigi ya''ami, ena''ö ufa''ema khömi ma''ifu, ame''ela Geheha, ba wangabe''e ya''ami,[11]', '["Faigi 16:19; KorI 1:4 b.t.; TesI 1:2,8","Fil 1:8","Faigi 15:23,32; HalZin 19:21","TesI 3:10","Amaed 11:25","Faigi 15:22","KorI 1:22–24","HalZin 28:31"]', NULL),
  (3414708, 'NT', 'Roma', 1, 12, 'ya''ia na terara dödögu göi awömi, ba khömi andrö, börö wa no faoma samati ita, he ya''ami, ba he ya''o.[12]', '["Faigi 16:19; KorI 1:4 b.t.; TesI 1:2,8","Fil 1:8","Faigi 15:23,32; HalZin 19:21","TesI 3:10","Amaed 11:25","Faigi 15:22","KorI 1:22–24","HalZin 28:31"]', NULL),
  (3414708, 'NT', 'Roma', 1, 13, 'Ba tebai ubini''ö khömi, ya''ami ira talifusö, wa no asese uŵa''ö tödögu, möido khömi — ba no tetabi ndra''o irugi da''e — ena''ö usöndra ba khömi göi mbua ma''ifu, si mane ba niha bö''ö göi.[13]', '["Faigi 16:19; KorI 1:4 b.t.; TesI 1:2,8","Fil 1:8","Faigi 15:23,32; HalZin 19:21","TesI 3:10","Amaed 11:25","Faigi 15:22","KorI 1:22–24","HalZin 28:31"]', NULL),
  (3414708, 'NT', 'Roma', 1, 14, 'So''ömö ndra''odo, he ba Ndrawa Heleni, ba he ba zi tenga Dawa Heleni, he ba zatua-tua, ba he ba zi lö atua-tua.[14]', '["Faigi 16:19; KorI 1:4 b.t.; TesI 1:2,8","Fil 1:8","Faigi 15:23,32; HalZin 19:21","TesI 3:10","Amaed 11:25","Faigi 15:22","KorI 1:22–24","HalZin 28:31"]', NULL),
  (3414708, 'NT', 'Roma', 1, 15, 'Andrö si manö wa''edöna dödögu, na balazi ndra''o, wangombakha turia somuso dödö andrö, ba khömi göi, ba Roma.[15]', '["Faigi 16:19; KorI 1:4 b.t.; TesI 1:2,8","Fil 1:8","Faigi 15:23,32; HalZin 19:21","TesI 3:10","Amaed 11:25","Faigi 15:22","KorI 1:22–24","HalZin 28:31"]', NULL),
  (3414708, 'NT', 'Roma', 1, 16, 'Lö''ö sa ailado ba duria somuso dödö andrö; noa sa fa''abölö Lowalangi ia, ba wangorifi samati andrö fefu, ba niha Yehuda ua ba ba Ndrawa Heleni göi.[16]', '["TimII 1:8–12; Sin 119:46; KorI 1:18; HalZin 13:46","Faigi 3:21 b.t.; Hab 2:4"]', NULL),
  (3414708, 'NT', 'Roma', 1, 17, 'Tefa''ele''ö sa ba khönia wa''atulö dödö khö Lowalangi, moroi ba wamati ba ba wamati zui lua-lua, si mane si so ba zura: "Ba wamati isöndra wa''auri satulö tödö."[17]', '["TimII 1:8–12; Sin 119:46; KorI 1:18; HalZin 13:46","Faigi 3:21 b.t.; Hab 2:4"]', NULL),
  (3414708, 'NT', 'Roma', 1, 18, 'Tefa''ele''ö sa moroi ba zorugo wönu Lowalangi ba golalöŵa andrö ba ba zi lö atulö andrö fefu, ba niha, sanaisi si duhu ba wa lö atulö andrö,[18]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 19, 'me no oroma ba khöra zi tola ta''ila khö Lowalangi; noa sa ifa''ele''ö khöra Lowalangi.[19]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 20, 'La''ila sa tödöra, ba nifazökhinia, zi lö oroma andrö, amuatania, i''otarai wamazökhi danö''a, fa''abölönia andrö, si lö aetu ba fa''alowalanginia fa lö famu''a khöra.[20]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 21, 'Me no aboto ba dödöra Lowalangi ba me lö ni''olowalangira ya''ia, wanuno ya''ia, ba me lö ni''andröra saoha gölö khönia me no arörö dödöra ba waya ba me no tobali ogömi-gömi dödöra, sambö era-era andrö.[21]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 22, 'Me no satua-tua ira, laŵa''ö, ba no tobali, sambö tödö ira.[22]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 23, 'Ba no lafalalini, no laböhöli lakhömi Lowalangi, andrö, si lö tebulö, ba no labe''e salahinia khala-khala wamaedo niha si mate-mate ba khala-khala wamaedo wofo ba khala-khala wamaedo zaliŵa-liŵa ba danö si öfa ahe, awö zanana andrö.[23]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 24, 'Andrö no iböhöli ira Lowalangi, fa la''o''ö wangisö dödöra andrö, si ta''unö andrö, ena''ö te''o''aya nösira andrö.[24]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 25, 'ya''ira andrö, si no mamalalini si duhu andrö khö Lowalangi, ba waya, si no mamosumange nifazökhi andrö, si no mangaröfi li ya''ia, moroi ba wamosumangera samazökhi, moroi ba we''angaröfi li da''ö, nisuno irugi zi lö aetu. Yaduhu.', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 26, 'Andrö no iböhöli ira Lowalangi, fa la''o''ö wangisö si lö sökhi: he ira alawe khöra, no laböhöli lala, ba no lasalahini si tenga lala.[25]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 27, 'Ba si manö göi ndra matua, no laböhöli lala wa''orudu ba ndra alawe, ba no tesao wa faoma la''isö nawöra, tobali no lahoröni ndra matua ira matua, ba no latema zi nangea luora ba wa''elungura andrö, ba nösira.[26]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 28, 'Ba me no lö ba dödöra wa''aboto ba dödöra Lowalangi, ba no ilulu ira Lowalangi, ena''ö la''o''ö gera-era si lö göna ba wolau si lö tola;', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 29, 'no a''oi so zi lö atulö fefu, awö walösökhi, awö wa''afaito, awö wa''omasi gana''a, no fahöna wa''afökhö dödö, awö wange''e, awö wagua-guasa, awö wa''onekhe, awö walimosa,[27]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 30, 'samato-matou awöra ira ba sanandraŵaisi ba si lö omasi Lowalangi ba sangosiwawöi awöra ba si fayaŵa ba samahokha ba samakhai si lö sökhi ba si lö molo''ö li zatua,[28]', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 31, 'ba sambö era-era ba si faröi ba sabe''e tödö ba si lö ahakhö tödö.', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414708, 'NT', 'Roma', 1, 32, 'La''ila sa huku Lowalangi andrö, wa no huku famunu huku zolau si manö, ba tenga ha fa lalau da''ö, omasi na göi ira, na so zolau si manö, niha bö''ö.', '["Faigi 2:5–8; Heb 10:26 b.t.","HalZin 14:17; 17:25 b.t.","Sin 8:2 b.t.; 19:2 b.t.; Yes 40:26","Efes 4:17; Sin 50:23","Yer 10:14; KorI 1:19 b.t.","MozV 4:16 b.t.; Sin 106:20","HalZin 14:16; Sin 81:13; TesI 4:4,5","MozIII 18:22 b.t.","KorI 6:9","Efes 5:3 b.t.; Gal 5:19 b.t.","TimII 3:2 b.t."]', NULL),
  (3414709, 'NT', 'Roma', 2, 1, 'Andrö tebai öbu''a ba hulumö, ya''ugö ono niha, ha niha ndra''ugö sanguhuku awönia; hukumö ö''etu''ö, na öhuku danö bö''ö; faoma sa nilaumi, ya''ugö sanguhuku.[1]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 2, 'Noa sa ta''ila, wa satulö wanguhuku Lowalangi solau si manö.', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 3, 'Ma öwai, aefa ndra''ugö ba huku andrö, nifatörö Lowalangi, ya''ugö niha, sanguhuku solau si manö, na no faoma nilaumi?[2]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 4, 'Ma ö''ositengagö wa''abölö wa''ebua dödönia ba fanahania tödönia ba fa''ebolo dödönia, ba lö ö''ila, wa ifarou''ö ba wamalalini era-era fa''ebua dödö Lowalangi andrö?[3]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 5, 'Ba ba wa''abe''e dödöu andrö ba ba wa lö edona''ö öfalalini gera-era dödöu, ba öhöna khöu wönu ba mbaŵa wönu andrö, ba mbaŵa wama''ele''ö fanguhuku satulö andrö, khö Lowalangi:[4]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 6, 'idozigö dania niha wamasulöni bua-buara;[5]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 7, 'ibe''e wa''auri si lö aetu ba zanau ölö ba mbua-bua si sökhi, wangalui lakhömi ba sumange ba fa lö tekiko,', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 8, 'ba ba zi lö atulö tödö, si lö molo''ö si duhu, solo''ö si lö atulö, ba fönu ba bakhu-bakhu dödö.[6]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 9, 'Famakao ba fa''abu dödö ba niha fefu, samazökhi si lö sökhi, oföna ba niha Yehuda, ba ba Ndrawa Heleni göi.[7]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 10, 'Ba lakhömi ba sumange ba fa''ohahau dödö ba zolau si sökhi, fefu, oföna ba niha Yehuda ba ba Ndrawa Heleni göi.[8]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 11, 'Ba Lowalangi, ba lö''ö sa famaigi bawa niha.[9]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 12, 'Ha wa''ato sa ita samazökhi horö, lö oroisa, ba tetibo göi, lö oroisa, ba ha wa''ato zamazökhi horö, si so oroisa, ba dali goroisa wanguhuku ya''ira.[10]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 13, 'Tenga sa samondrongo oroisa zatulö föna Lowalangi, ha solo''ö oroisa niŵa''ö satulö.[11]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 14, 'Ba na lalau niŵa''ö ba goroisa, to''ua ya''ira, niha baero, si lö oroisa, ba tobali oroisa ira khöra, ya''ira, si lö oroisa,[12]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 15, 'tobali la''oroma''ö, wa no musura ba dödöra niŵa''ö ba goroisa andrö, ba fao wamaduhu''ö dödöra, awö wa faoma la''adu-adugö nawöra era-erara, ba he wa faoma labu''a-bu''a ba hulu nawöra.[13]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 16, 'Oroma dania na luo ifahuku''ö dania Lowalangi khö Keriso Yesu zi tobini ba dödö niha, si mane niŵa''ögu, wangombakha turia somuso dödö andrö.[14]', '["Faigi 3:9–19; 14:10; SamII 12:5; Yoh 8:7","Sin 50:16–22","Luk 13:2 b.t.; FetII 3:9,15; Yud 4","Yob 36, 13),","Fam 22; Mat 16:27; KorII 5:10; Yer 17:10","TesII 1:8 b.t.","Luk 12:47,48; Mat 11:22","Faigi 1:16","MozV 10:17; HalZin 10:34","Faigi 1:32; Yoh 5:45","Yoh 1:22,25; Luk 10:25 b.t.; YohI 3:7","Sin 147:20","Faigi 1:19; Heb 8:10","Mat 25:31; KorI 4:5; Sin 90:8"]', NULL),
  (3414709, 'NT', 'Roma', 2, 17, 'Ba niha Yehuda ndra''ugö öŵa''ö, ba ödöna-döna ba goroisa, ba ösuno ndra''ugö ba khö Lowalangi.[15]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 18, 'No aboto ba dödöu zomasi ia, no ötimba tödöu hezo zi sökhi, me no nifahaö ba goroisa ndra''ugö.[16]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 19, 'öŵa''ö tödöu solohe tanga zau''a ndra''ugö, sohagaini si so ba zogömi-gömi,[17]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 20, 'samamaha sambö era-era, samahaö iraono, si so dali wangila ba dali zi duhu, ba goroisa;', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 21, 'ba ya''ugö samahaö niha tanö bö''ö, ba hadia, lö öfahaö ndra''ugö? ya''ugö, sanguma''ö ba niha, böi managö, ba managö''ö?[18]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 22, 'Sanguma''ö, böi mohorö, ba mohorö''ö? Sangogorofi adu, ba ö''anagöi ira ba gosali?[19]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 23, 'ya''ugö, sanuno ya''ugö ba goroisa, ba ö''o''aya Lowalangi wanawö oroisa?', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 24, '"Börö sa ami, wa tetandraŵaisi döi Lowalangi ba niha baero", itörö zi so ba zura.[20]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 25, 'Moguna sa wamoto andrö, na ö''o''ö goroisa, ba na sanawö oroisa ndra''ugö, ba tobali botolö zi no muboto andrö khömö.[21]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 26, 'Ba na itörö lala goroisa si lö muboto andrö, ba tenga no tobali amaedola zi no muboto mbotolö andrö khönia?[22]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 27, 'Ba ihuku ndra''ugö dania si to''ua lö muboto, solo''ö oroisa andrö, ya''ugö andrö, sanawö oroisa, he no so zura, ba he no muboto ndra''ugö.', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 28, 'Tenga sa da''ö niha Yehuda, si no niha Yehuda wamaigi niha, ba tenga göi da''ö wamoto, ni''ila hörö, ba nösi niha.[23]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3414709, 'NT', 'Roma', 2, 29, 'Ha si no niha Yehuda ba zi tobini ba famoto tödö, na dali Geheha; si tenga dali niŵa''ö ba zura. Na so zi manö, ba tenga nisuno niha, no nisuno Lowalangi.[24]', '["Yes 58:2; Mikh 3:11","Fil 1:10","Mat 15:14","Mat 5:23; 3:4; Sin 50:16 b.t.","Yoh 8:9","Yes 52:5; Hes 36:20–23","Yer 4:4; KorI 7:19; MozV 10:16","Kol 2:11; Gal 5:6","Faigi 9:6 b.t.; Yoh 8:39","MozV 30:6; Fil 3:3"]', NULL),
  (3415469, 'NT', 'Roma', 3, 1, 'Ba hadia zi tohude ba niha Yehuda, ba hadia guna wamoto andrö?[1]', '["Faigi 2:25","Faigi 9:4 b.t.; HalZin 7:38; MozV 4:7 b.t.; Sin 147:19","Faigi 11:1,2,29; TimII 2:13","Sin 116:11; 51:6; MozIV 23:19","Faigi 9:14","MozI 18:25","Faigi 6:1,2"]', NULL),
  (3415469, 'NT', 'Roma', 3, 2, 'Ebua sa, gofu he wisa wamaigida. Si föföna ua, wa no mube''e ba dangara daroma li Lowalangi andrö.[2]', '["Faigi 2:25","Faigi 9:4 b.t.; HalZin 7:38; MozV 4:7 b.t.; Sin 147:19","Faigi 11:1,2,29; TimII 2:13","Sin 116:11; 51:6; MozIV 23:19","Faigi 9:14","MozI 18:25","Faigi 6:1,2"]', NULL),
  (3415469, 'NT', 'Roma', 3, 3, 'Ma he wisa? na so ösa zi lö mamati, hadia, iwu''ai wa lö faröi Lowalangi wa lö mamati ira?[3]', '["Faigi 2:25","Faigi 9:4 b.t.; HalZin 7:38; MozV 4:7 b.t.; Sin 147:19","Faigi 11:1,2,29; TimII 2:13","Sin 116:11; 51:6; MozIV 23:19","Faigi 9:14","MozI 18:25","Faigi 6:1,2"]', NULL),
  (3415469, 'NT', 'Roma', 3, 4, 'Tenga si manö. Fozunia, ba si ndruhu Lowalangi ba sofaya niha fefu, itörö zi so ba zura: "Ena''ö satulö ndra''ugö, laŵa''ö, ba niŵa''öu andrö, ba ena''ö möna ndra''ugö, na lahuku''ö."[4]', '["Faigi 2:25","Faigi 9:4 b.t.; HalZin 7:38; MozV 4:7 b.t.; Sin 147:19","Faigi 11:1,2,29; TimII 2:13","Sin 116:11; 51:6; MozIV 23:19","Faigi 9:14","MozI 18:25","Faigi 6:1,2"]', NULL),
  (3415469, 'NT', 'Roma', 3, 5, 'Ba na i''aro''ö wa''atulö Lowalangi wa lö atulö ita, ba hadia niŵa''öda? Hadia, si lö atulö Lowalangi, na ifatörö wönu? (tödö niha niŵa''ögu).[5]', '["Faigi 2:25","Faigi 9:4 b.t.; HalZin 7:38; MozV 4:7 b.t.; Sin 147:19","Faigi 11:1,2,29; TimII 2:13","Sin 116:11; 51:6; MozIV 23:19","Faigi 9:14","MozI 18:25","Faigi 6:1,2"]', NULL),
  (3415469, 'NT', 'Roma', 3, 6, 'Tenga si manö. Na si manö ena''ö, ba he iwisa Lowalangi wanguhuku ösi guli danö?[6]', '["Faigi 2:25","Faigi 9:4 b.t.; HalZin 7:38; MozV 4:7 b.t.; Sin 147:19","Faigi 11:1,2,29; TimII 2:13","Sin 116:11; 51:6; MozIV 23:19","Faigi 9:14","MozI 18:25","Faigi 6:1,2"]', NULL),
  (3415469, 'NT', 'Roma', 3, 7, 'Ba na tedou wa''aduhu Lowalangi andrö, ba wayagu andrö, fangebua lakhöminia, ba hadia wa lafatörö na khögu huku zamazökhi horö?', '["Faigi 2:25","Faigi 9:4 b.t.; HalZin 7:38; MozV 4:7 b.t.; Sin 147:19","Faigi 11:1,2,29; TimII 2:13","Sin 116:11; 51:6; MozIV 23:19","Faigi 9:14","MozI 18:25","Faigi 6:1,2"]', NULL),
  (3415469, 'NT', 'Roma', 3, 8, 'Ba tenga itörö, na latandraŵaisi ita, na so ösa zanguma''ö, no maŵa''ö: "Datalau zi lö sökhi, ena''ö si sökhi lua-luania." Si nangea nihuku zi manö.[7]', '["Faigi 2:25","Faigi 9:4 b.t.; HalZin 7:38; MozV 4:7 b.t.; Sin 147:19","Faigi 11:1,2,29; TimII 2:13","Sin 116:11; 51:6; MozIV 23:19","Faigi 9:14","MozI 18:25","Faigi 6:1,2"]', NULL),
  (3415469, 'NT', 'Roma', 3, 9, 'Ba he wisa? No tohude ita? Tenga sa ya''ia manö. Noa sa mege ta''adugö ira, he niha Yehuda, ba he Dawa Heleni, wa no a''oi sawuyu horö ira,[8]', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 10, 'itörö zi so ba zura: "Lö satulö tödö, samösa lö''ö,[9]', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 11, 'lö satua-tua, lö sangalui sibai Lowalangi.', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 12, 'No ahori fabali ira, no fatutu manö, lö gunara, lö solau si sökhi, samösa lö''ö,', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3415469, 'NT', 'Roma', 3, 13, 'Lewatö sobawa dölö-tölöra, lalau falimo lelara, söfu gulö no so ba mbewera.[10]', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 14, 'Ba mbawara ba no fahöna wangelifi ba fatiusa,[11]', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 15, 'ahera, ba no alio-lio ba wange''e,[12]', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 16, 'ba lalara, ba no so wamakiko, awö wa''abu dödö;', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 17, 'lala wa''ohahau dödö andrö, ba lö saboto ba dödöra,', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 18, 'Fangata''ufi Lowalangi ba lö''ö, fametahöra."[13]', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 19, 'Ba no ta''ila, fefu hadia ia niŵa''ö ba goroisa, ba ba khöra teŵa''ö si so barö mbawa goroisa, ena''ö nifa''afu mbawara fefu ba ena''ö mo''ömö khö Lowalangi dozi niha ba guli danö.', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 20, 'Börö wa samösa lö niha niŵa''ö satulö, fönania, ba wolo''ö oroisa andrö. Soroi ba goroisa sa, ba fa''aboto ba dödö horö.[14]', '["Faigi 1:2; Gal 3:22","Sin 14:1–3","Sin 5:10, 140:4","Sin 10:7","Yes 59:7,8","Sin 36:2","Gal 2:16; Sin 143:2; Faigi 7:7 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 21, 'Ba noa sa''ae to''ele wa''atulö dödö khö Lowalangi, baero goroisa, nifaduhu''ö goroisa ba nifaduhu''ö zama''ele''ö andrö,[15]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 22, 'fa''atulö dödö khö Lowalangi soroi ba wamati khö Yesu Keriso, ba zamati andrö fefu; lö''ö sa fa''afaehu.[16]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 23, 'Noa sa ahori mamazökhi horö ira, ba lö''ö sa si sökhi turiara khö Lowalangi.[17]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 24, 'Ba saoha gölö wa iŵa''ö Lowalangi satulö ira, fa''ebua dödönia, börö wangöhöli andrö, ba khö Keriso Yesu,[18]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 25, 'nifataro Lowalangi höli, ba ndrönia andrö, balazi wamati, ba wangoroma''ö fa''atulö dödönia, börö wa no i''osilömilagö horö föna,[19]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 26, 'götö wa''ebolo dödö Lowalangi, ba wangoroma''ö fa''atulö dödönia ba götö da''e, ena''ö satulö ia ba ena''ö satulö göi, iŵa''ö, zamati khö Yesu.[20]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 27, 'Ba heza so khöda wanuno ya''ita? Lö''ö sa ya''ia. Hadia lala? Hadia, balazi mbua-bua? Tenga. No lala wamati andrö.[21]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 28, 'Ba da''ö niŵa''öda, börö wamati, wa satulö niha iŵa''ö Lowalangi, baero wolo''ö oroisa.[22]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 29, 'Ma ha Lowalangi niha Yehuda Lowalangi? Tenga Lowalangi niha baero göi? Ya''ia, Lowalangi niha baero göi.[23]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 30, 'Na duhu ha samösa Lowalangi, sanguma''ö dania satulö zi no muboto, moroi ba wamati, awö zi lö muboto, ba wamati andrö.[24]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3415469, 'NT', 'Roma', 3, 31, 'Ba hadia, tawu''ai goroisa, ba wamati andrö? Tenga da''ö. Ta''aro''ö goroisa.[25]', '["Faigi 1:17; HalZin 10:43","Fil 3:9; KorII 5:21; Faigi 10:10,12","RazI 8:46","HalZin 13:38 b.t.; Efes 2:8 b.t.","MozII 25:17; Heb 4:16; HalZin 17:30","Faigi 8:3,4","Faigi 4:2; 8:2","Gal 2:16; HalZin 13:38,39","Faigi 9:24 b.t.; 10:12 b.t.","Faigi 4:11,12; HalZin 15:11; Gal 3:8","Faigi 6:15; Mat 5:17; Yak 2:14 b.t."]', NULL),
  (3421993, 'NT', 'Roma', 4, 1, 'Ba ha taŵa''ö, hadia nisöndra Gaberahamo, furugöda, ba lala niha ba guli danö?[1]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 2, 'Na moroi ba wolo''ö oroisa sa''ae, wa iŵa''ö Lowalangi satulö Gaberahamo, ba nisuno ia, ba tenga nisuno Lowalangi.[2]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 3, 'Ba hadia sa niŵa''ö ba zura? "Ba mamati Gaberahamo khö Lowalangi, ba tebe''e fa''atulö dödönia da''ö."[3]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 4, 'Ba ba zohalöŵö, ba tenga fa''ebua dödö, wa tebe''e luonia, no ömö.[4]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 5, 'Ba ba zi tenga balazi mbua-bua, samati khö zanguma''ö satulö zi no mangerogö Lowalangi mege, khönia tebe''e fa''atulö dödönia wamatinia andrö.[5]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 6, 'Si manö göi wamahowu''ö Dawido niha niŵa''ö Lowalangi satulö ia, he lö folo''ö oroisa, imane:[6]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 7, '"Ya''ahowu zi no mube''e aefa lalö andrö, si no mubalugö horö!', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 9, 'Ba famahowu''ö andrö, hadia, ha famahowu''ö si no muboto, ba ma famahowu''ö si lö muboto göi? Noa sa taŵa''ö: No tebe''e fa''atulö dödö Gaberahamo wamatinia andrö.', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 10, 'Ba ha mege tebe''e fa''atulö dödönia, hadia, me no muboto ia, ba ma me lö muboto na? Tenga me no muboto, no me lö muboto na.', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 11, 'Ba itema dandra, famoto andrö, famaduhu''ö fa''atulö dödö andrö, ba wamati andrö, si so khönia, me lö muboto ia na, ena''ö tobali tua zamati lö muboto fefu ia, ena''ö tebe''e fa''atulö dödöra wa''atulö dödö andrö,[7]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 12, 'ba ena''ö tua zi no muboto göi ia, ba zi tenga ha famoto, sanara göi lahe wamati andrö, si so khö duada Aberahamo, me lö muboto ia na.[8]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 13, 'Tenga sa ba goroisa tefa''ema gamabu''ula li andrö khö Gaberahamo, ba he ba ma''uwunia, wa ya''ia zokhö uli danö dania, no ba wa''atulö dödö ba wamati tefa''ema.[9]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 14, 'Na solo''ö oroisa sa zanema ondröita, ba no tobali faya wamati andrö, ba si lö boto gamabu''ula li andrö.', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 15, 'Samobörö fönu sa goroisa, ba ba zi lö oroisa, ba lö''ö göi fanawö.[10]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 16, 'Andrö moroi ba wamati, ena''ö fa''ebua dödö, ena''ö aro gamabu''ula li andrö, ba ma''uwunia fefu, tenga ha ba ma''uwunia moroi ba goroisa, no ba ma''uwunia moroi ba wamati göi, moroi ba wamati Gaberahamo, si no tuada fefu,[11]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 17, 'si mane si so ba zura: "No ube''e furugö ndra''ugö, oya soi ma''uwumö dania"; ba khö Lowalangi andrö, ba zamati ia, sangorifi si no mate, sanötöi si lö''ö na, hulö na no so[12]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 18, 'samati manö, wanötöna, he lö tötönafö, ena''ö oya soi ma''uwunia, na itörö niŵa''ö andrö: "Si manö ma''uwumö dania."[13]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 19, 'Ba lö sangiwa dödönia wamati, wamaigi botonia, wa no atua — no mato otu fakhe — ba ma talu Zara andrö, si no amaedola zi mate;[14]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 20, 'lö sangiwa dödönia ba gamabu''ula li Lowalangi andrö, fa lö mamati ia, abe''e dödönia wamati, ifosumange Lowalangi,[15]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 21, 'no faduhu sibai dödönia, i''ila ifalua göi Lowalangi hadia nifabu''unia.[16]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 22, 'Andrö göi tebe''e fa''atulö dödönia,', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 23, 'ba tenga ha ba khönia, wa tesura, wa no mube''e fa''atulö dödönia,', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 24, 'ba khöda göi, ba nibe''e dania, khöda samati khö zanusugi Yesu, So''aya ya''ita, moroi ba ngai zi mate,[17]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421993, 'NT', 'Roma', 4, 25, 'nibe''e nibunu ba lalöda andrö, nisusugi ba wangatulö''ö ya''ita.[18]', '["Yes 51:2","Yak 2:21; KorI 1:29,31","MozI 15:6; Gal 3:6; Yak 2:23","Faigi 11:6","Faigi 3:26,28","Sin 32:1,2","Faigi 2:28 b.t.; MozI 17:10,11; Gal 3:7 b.t.","Yoh 8:39; Mat 3:9","Gal 3:16—18; MozI 22:16 b.t.","Faigi 3:20; 7:8,10; 5:13","Gal 3:7,9,14","MozI 17:5; Heb 11:19","Heb 11:1; MozI 15:5","Heb 11:11,12; MozI 17:1,17; 18:11","Yak 1:6","Sin 115:3; Luk 1:37","Faigi 15:3; 10:9; FetI 1:21","Faigi 3:25; 8:32,34; FetI 1:3"]', NULL),
  (3421994, 'NT', 'Roma', 5, 1, 'Ba me no satulö tödö ita, iŵa''ö Lowalangi, balazi ba wamati, ba no atulö ita Lowalangi, börö Zo''aya ya''ita, Yesu Keriso.[1]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 2, 'Moroi khönia göi, wa tola ta''ondrasi mege wa''ebua dödö andrö, si lö tebulö, khöda, ba tasuno ita, me tadöna-döna lakhömi Lowalangi andrö.[2]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 3, 'Ba tenga ha da''ö, tasuno göi ita ba wamakao andrö, me no ta''ila, i''a''asogö wanaha tödö famakao andrö;[3]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 4, 'ba fanaha tödö andrö, ba i''a''asogö wa''abe''e, ba fa''abe''e andrö, ba i''a''asogö wanötöna.[4]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 5, 'ba fanötöna andrö, ba tebai te''ala ita, ibe''e, me no mulau ba dödöda wa''omasi Lowalangi andrö, ba khö Geheha ni''amoni''ö andrö, nibe''e khöda.[5]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 6, 'Noa sa mate Keriso, me luo lö abe''e ita na, salahi zi no mangerogö Lowalangi.[6]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 7, 'Ba si lö lokha lö mate niha salahi zatulö, ba zi sökhi sa, ba ma ta''ila tola mate ia.[7]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 8, 'Ba i''oroma''ö wa''omasinia ita Lowalangi, me no mate salahida Keriso, me samazökhi horö ita na.[8]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 9, 'Ba mendrua manö aefa ita ba wönu andrö iada''e, ba khönia, me no satulö ita, iŵa''ö Lowalangi, ba ndronia andrö.[9]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 10, 'Na noa sa mu''a''atulö ita Lowalangi, ba wa''amate Nononia, me si fa''udu ita, ba mendrua manö te''orifi ita ba wa''aurinia andrö, me no atulö ita.[10]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 11, 'Ba tenga ha da''ö; me tasuno göi ita ba khö Lowalangi, börö Zo''aya ya''ita, Yesu Keriso, nitemada fa''atulö iada''e.[11]', '["Yes 32:17,18; Efes 2:14 b.t.","Efes 3:12; Heb 10:19","FetI 4:13; Yak 1:2 b.t.);","FetI 1:6—9","Sin 34:6; Fil 1:20; YohI 4:12,13,16","Heb 4:15; FetI 3:18","Yoh 15:13","Faigi 8:32; Yoh 3:16","Efes 1:7; Kol 1:14","Faigi 4:25; KorII 5:19; Kol 1:21 b.t.","KorI 30:31"]', NULL),
  (3421994, 'NT', 'Roma', 5, 12, 'Andrö, si mane böröta horö andrö ba guli danö, wa no ha samösa niha zamobörö, awö lua-lua horö andrö, fa''amate, awö wa no ikhamö niha fefu fa''amate andrö, börö wa no dozi samazökhi horö ira[12]', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 13, '— noa sa so horö ba guli danö, me lö oroisa na, ba lö tebe''e horö horö andrö, na lö oroisa,[13]', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 14, 'ba no salaŵa zui wa''amate andrö, i''otarai Gadamo, irugi Moze, he ba zi lö lalö si mane lalö Gadamo, si no tobali famaedo zi so dania[14] —', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 15, 'Ba buala fa''ebua dödö andrö, ba tenga si mane lalö andrö. Na sato sa zi mate ba lalö zi ha samösa, ba mendrua manö, wa a''oi irugi zato fa''ebua dödö Lowalangi ba buala andrö, moroi ba wa''ebua dödö niha si ha samösa andrö, Yesu Keriso.[15]', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 16, 'Ba bö''ö wa''ebua dödö andrö, bö''ö zoroi ba zi ha samösa, samazökhi horö andrö. Moroi ba zi ha samösa huku andrö, ba wanibo, ba buala fa''ebua dödö andrö, ba moroi ba lalö soya, ba wanga''atulö.', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 17, 'Na ha samösa sa mbörö, wa no salaŵa wa''amate, moroi ba lalö zi ha samösa andrö, ba mendrua manö abölö ba wa''auri zanema fa''ebua dödö andrö, awö mbuala andrö, fa''atulö dödö, si no a''oi so, börö zi ha samösa andrö, Yesu Keriso.', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 18, 'Tobali si mane ba lalö zi ha samösa andrö, me no möi börö wanibo niha fefu, si manö göi ba wanga''atulö zi ha samösa andrö, noa göi möi fanga''atulö niha fefu, ba wangorifi.', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 19, 'Hulö si mane ba wa lö molo''ö niha andrö, si ha samösa sa, me no möi börö, wa no a''oi sokhö horö zato, si manö göi ba wolo''ö zi ha samösa andrö, noa göi möi börö wanga''atulö ba zato.[16]', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 20, 'Ba no fatewu goroisa, ena''ö a''oi so lalö andrö. Ba ba zi no a''oi so horö, ba mendrua manö wa no a''oi so wa''ahakhö dödö göi,[17]', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421994, 'NT', 'Roma', 5, 21, 'ena''ö si mane fa''abölö horö andrö, ba wamunu, si manö göi wa''abölö wa''ahakhö dödö andrö, moroi ba wanga''atulö andrö, ba wa''auri si lö aetu, börö Yesu Keriso, So''aya ya''ita.[18]', '["Faigi 6:23; MozI 3:6; 2:17; TimI 2:14","Faigi 4:15","KorI 15:45","KorI 15:21,22; Yoh 1:16,17","Yes 53:11; Faigi 3:24 b.t.; Heb 5:8","Faigi 7:13; Gal 3:19","Faigi 6:23"]', NULL),
  (3421999, 'NT', 'Roma', 6, 1, 'Ba hadia niŵa''öda? Hadia, lö tabulö''ö ita ba horö, ena''ö a''oi so dania wa''ahakhö dödö andrö?[1]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 2, 'Böi si manö. Ya''ita, si no mate ba horö, ba hana wa edöna ita auri ba khönia.[2]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 3, 'Ma lö mi''ila, wa ba wa''amate Keriso Yesu tebayagö idanö ita fefu, ya''ita, si no mubayagö idanö ba khönia?[3]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 4, 'Ba noa sa teko''o ita, awönia, famayagö idanö andrö, ba wa''amate, ena''ö hulö si mane Keriso, si no mususugi lakhömi Nama, moroi ba ngai zi mate, si manö göi ita, tatörö lala si bohou.[4]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 5, 'Na noa sa''ae faböbö ita khönia, me no fakhili-khili ira wa''amateda wa''amatenia, ba si manö sa göi ba wemaoso dania;[5]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 6, 'me aboto ba dödöda, wa no mufarahugö niha si töhöna khöda, wamoröfa ya''ia, ena''ö tehöndrögö mboto andrö, samazökhi horö, fa böi sa''ae sawuyu horö ita.[6]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 7, 'Si no mate sa, ba no mu''atulö''ö, no aefa ba horö.[7]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 8, 'Ba na no mate ita, awö Keriso, ba no faduhu dödöda, auri göi ita dania, awönia.[8]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 9, 'Me no ta''ila, lö''ö sa''ae mate Keriso, me no aefa tesusugi ia moroi ba ngai zi mate; lö''ö sa''ae ilaŵa ia fa''amate.[9]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 10, 'Fa''amatenia andrö, ba ba horö andrö mate ia, samuza; ba fa''aurinia, ba khö Lowalangi auri ia.[10]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 11, 'Si manö göi ami, si no mate sa, ba horö, ami, miŵa''ö tödömi, ba sauri ba khö Lowalangi, börö Keriso Yesu.[11]', '["Faigi 5:20; 3:5,8","Gal 2:17; FetI 2:24","Gal 3:27","Faigi 8:10; 7:6; Kol 2:12 b.t.; KorII 5:15,17","TimII 2:11; Fil 3:10,11","Gal 5:24; 6:14; Efes 4:22 b.t.","Gal 2:19","Gal 2:20; Kol 3:3,4","Yes 53:8,10; Heb 7:24; Fam 1:18","Heb 9:26,28","Faigi 6:4,8"]', NULL),
  (3421999, 'NT', 'Roma', 6, 12, 'Ba böi abölö horö ba mbotomi andrö, si mate, ba wolo''ö fangisönia.[12]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 13, 'Ba böi ba horö mitehe ndroto-ndrotomi, fangöna ba zi lö atulö, mi''oro''ö ami khö Lowalangi, si mane si no auri, si otarai wa''amate, ba Lowalangi mitehe ndroto-ndrotomi, fangöna ba zatulö.[13]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 14, 'Tebai sa ilaŵa ami horö; tenga sa barö mbawa goroisa so ami, no barö mbawa wa''ahakhö dödö so ami.[14]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 15, 'Ba he wisa? Hadia tafazökhi horö, me tenga barö mbawa goroisa, me no barö mbawa wa''ahakhö dödö so ita? Böi si manö.[15]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 16, 'Hadia, lö mi''ila, ha khö mitehe ami, sawuyu, ba wolo''ö linia, khönia ami, sawuyu, ba wolo''ö linia, he ba horö, ba wa''amate, ba he ba wolo''ö, ba wanga''atulö.[16]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 17, 'Ba nisuno Lowalangi, me no aefa wa sawuyu horö ami, ba me no moroi ba dödömi mi''o''ö wamaedo andrö, famahaö andrö, ba ni''ohe ya''ami.[17]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 18, 'Ba me no mu''efa''ö ami ba horö, ba no tobali enoni zatulö ami.[18]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 19, 'Fehede niha wehedegu, börö wa no sambö fa''abölö nösimi. Si mane fanehemi sa föna ndroto-ndrotomi sawuyu zi ra''iö ba sawuyu wanawö oroisa, ba wanawö-nawö oroisa, si manö mitehe iada''e ndroto-ndrotomi enoni zatulö, ba wangohau-hau.[19]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 20, 'Me sawuyu horö ami sa, ba no aefa ami ba wa''atulö dödö andrö.', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 21, 'Ba hadia haremi, me luo da''ö? saila ami iada''e; fa''amate sa wozunia.[20]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 22, 'Ba iya''e, me no aefa ami ba horö, me no tobali enoni Lowalangi ami, ba no so haremi ba wangohau-hau, ba fozunia, ba fa''auri si lö aetu.[21]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3421999, 'NT', 'Roma', 6, 23, 'Luo horö sa, ba fa''amate, ba buala fa''ebua dödö Lowalangi andrö, ba no fa''auri si lö aetu ba khö Keriso Yesu, So''aya ya''ita.[22]', '["MozI 4:7","Faigi 6:19; 12:1; Efes 2:4,5","Faigi 7:4 b.t.; 8:2; TimI 1:9; Gal 5:16,18","Faigi 6:1 b.t.","Yoh 8:34; FetII 2:19","Yoh 8:32–36","FetI 2:16","Faigi 1:24,29; 6:13","Faigi 7:5; 8:6","Gal 6:8; FetI 1:9","Faigi 5:12; Yak 1:15; YohI 5:11"]', NULL),
  (3422001, 'NT', 'Roma', 7, 1, 'Ma lö mi''ila, ya''ami, ira talifusö, — ba zi no aboto ba dödö oroisa muhehedo — wa no barö mbawa goroisa andrö so niha, irugi mate ia.[1]', '["Faigi 2:17 b.t.","KorI 7:39","Mat 5:32","Faigi 6:5,7; KorII 11:2; Gal 2:19","Faigi 6:21","Faigi 6:4"]', NULL),
  (3422001, 'NT', 'Roma', 7, 2, 'Ira alawe si no muhalö, ba noa sa tefaböbö ba ndra matua, ba goroisa andrö, götö wa''anau noso ndra matua; ba na mate ndra matua, ba lö''ö sa''ae oroisa, famaböbö ya''ia khönia.[2]', '["Faigi 2:17 b.t.","KorI 7:39","Mat 5:32","Faigi 6:5,7; KorII 11:2; Gal 2:19","Faigi 6:21","Faigi 6:4"]', NULL),
  (3422001, 'NT', 'Roma', 7, 3, 'Tobali labe''e töinia sohorö, na orudu ia ba ndra matua bö''ö, fatua auri ndra matuania. Ba na mate ndra matua, ba aefa ia ba goroisa, fa tenga sa''ae sohorö ia, na möi ia donga ndra matua bö''ö.[3]', '["Faigi 2:17 b.t.","KorI 7:39","Mat 5:32","Faigi 6:5,7; KorII 11:2; Gal 2:19","Faigi 6:21","Faigi 6:4"]', NULL),
  (3422001, 'NT', 'Roma', 7, 4, 'Andrö ya''ami göi, ya''ami ira talifusögu, si no mubunu ami, ba goroisa, ba mboto Keriso andrö, ena''ö tanö bö''ö zokhö ya''ami, ya''ia andrö, si no mususugi moroi ba ngai zi mate, ena''ö so mbua-buada khö Lowalangi.[4]', '["Faigi 2:17 b.t.","KorI 7:39","Mat 5:32","Faigi 6:5,7; KorII 11:2; Gal 2:19","Faigi 6:21","Faigi 6:4"]', NULL),
  (3422001, 'NT', 'Roma', 7, 5, 'Me no ba nösi so ita, ba no abölö wangisö horö andrö, nifasugi goroisa andrö, ba ndroto-ndrotoda, ena''ö so mbua-buania ba wa''amate.[5]', '["Faigi 2:17 b.t.","KorI 7:39","Mat 5:32","Faigi 6:5,7; KorII 11:2; Gal 2:19","Faigi 6:21","Faigi 6:4"]', NULL),
  (3422001, 'NT', 'Roma', 7, 6, 'Ba iya''e, ba no aefa ita ba goroisa, me no mate ita ba zanaha ya''ita föna, tobali enoni ita ba lala si bohou andrö, khö Geheha, ba tenga ba lala föna, si so ba zura.[6]', '["Faigi 2:17 b.t.","KorI 7:39","Mat 5:32","Faigi 6:5,7; KorII 11:2; Gal 2:19","Faigi 6:21","Faigi 6:4"]', NULL),
  (3422001, 'NT', 'Roma', 7, 7, 'Ba hadia niŵa''öda? Hadia, horö goroisa andrö? Tenga si manö. Ba lö''ö sa aboto ba dödögu horö andrö mena''ö, na tenga moroi ba goroisa. Lö''ö sa göi u''ila mena''ö, hadia wangisö andrö, na lö muŵa''ö ba goroisa andrö: Böi mangisö.[7]', '["Faigi 3:20; MozII 20:17","Faigi 5:13; Yoh 15:22","MozV 5:32,33; Gal 3:12","TimI 1:8"]', NULL),
  (3422001, 'NT', 'Roma', 7, 8, 'Ba no i''oguna''ö nifakhoi andrö horö andrö, ba no ifasugi ba dödögu fefu ngawalö wangisö; na lö oroisa sa, ba no si mate horö,[8]', '["Faigi 3:20; MozII 20:17","Faigi 5:13; Yoh 15:22","MozV 5:32,33; Gal 3:12","TimI 1:8"]', NULL),
  (3422001, 'NT', 'Roma', 7, 9, 'ba ya''o, ba sauri lö oroisa, föna. Ba me so nifakhoi andrö, ba auri horö, ba ya''o, ba mate,', '["Faigi 3:20; MozII 20:17","Faigi 5:13; Yoh 15:22","MozV 5:32,33; Gal 3:12","TimI 1:8"]', NULL),
  (3422001, 'NT', 'Roma', 7, 10, 'ba no tobali famunugu goroisa andrö, nibe''e fangorifi.[9]', '["Faigi 3:20; MozII 20:17","Faigi 5:13; Yoh 15:22","MozV 5:32,33; Gal 3:12","TimI 1:8"]', NULL),
  (3422001, 'NT', 'Roma', 7, 11, 'Noa sa i''oguna''ö nifakhoi andrö horö andrö, no ibe''e famaelungu ya''o, ba famunu ya''o.', '["Faigi 3:20; MozII 20:17","Faigi 5:13; Yoh 15:22","MozV 5:32,33; Gal 3:12","TimI 1:8"]', NULL),
  (3422001, 'NT', 'Roma', 7, 12, 'Tobali ni''amoni''ö goroisa andrö, ba nifakhoi andrö, ba ni''amoni''ö ba satulö ba si sökhi.[10]', '["Faigi 3:20; MozII 20:17","Faigi 5:13; Yoh 15:22","MozV 5:32,33; Gal 3:12","TimI 1:8"]', NULL),
  (3422001, 'NT', 'Roma', 7, 13, 'Ba hadia no tobali famunugu zi sökhi andrö? Tenga si manö. Horö andrö a''ine; ba ena''ö oroma, wa horö ia, na ibe''e famunugu zi sökhi andrö, ena''ö a''oi so wa horö ia, moroi ba nifakhoi andrö.[11]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3422001, 'NT', 'Roma', 7, 14, 'Ta''ila sa, wa no moroi ba Geheha goroisa andrö, ba ösi niha ndra''odo, ni''amawa ba horö andrö.[12]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 15, 'Hadia nilaugu sa, ba no si lö aboto ba dödögu. Tenga sa somasi ndra''o nilaugu, si fa''udu ndra''o, da''ö ulau.[13]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 16, 'Ba na ulau zi lö omasido ba no utehe goroisa andrö, wa no si sökhi.', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 17, 'Ba tenga sa''ae ya''o zolau ya''ia, horö andrö a''ine, si no so ba nösigu, zolau.', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 18, 'Noa sa u''ila, wa lö si sökhi ba khögu, ba nösigu andrö. So sa khögu wa''edöna, ba famalua si sökhi andrö, ba lö''ö.[14]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 19, 'Tenga si sökhi, somasi ndra''o, ulau, si lö sökhi, si lö edöna ndra''o, da''ö nilaugu.', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 20, 'Ba na ulau zi lö omasido, ba tenga sa''ae ya''o zolau ya''ia, horö andrö a''ine, si so ba nösigu, zolau.', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 21, 'Ba tobali oroma khögu, na to''ua ya''o, ba omasido ulau zi sökhi ba no ahatö zi lö sökhi.[15]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 22, 'Omasido sa goroisa Lowalangi, na balazi dödögu bakha,[16]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 23, 'ba u''ila goroisa bö''ö ba ndroto-ndrotogu, si fasöndra ba goroisa andrö, si so ba dödögu, ba samöbö ya''o, sawuyu goroisa horö andrö, si so ba ndroto-ndrotogu[17]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 24, 'Alai ndra''o, niha nifakao! Ha niha zangefa''ö ya''o ba mboto ba wa''amate andrö?[18]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422001, 'NT', 'Roma', 7, 25, 'Nisuno Lowalangi, börö Yesu Keriso, So''aya ya''ita. Tobali solo''ö oroisa Lowalangi ndra''o tödögu, ba solo''ö oroisa horö andrö ösigu.[19]', '["Faigi 6:23; KorI 15:56","Faigi 8:3; Mat 5:22,28","Gal 5:17","MozI 8:21; Fil 2:13","Heb 12:1","Faigi 2:14,15","Faigi 7:15","Faigi 8:10 b.t.","Faigi 8:2,37; KorI 15:57"]', NULL),
  (3422002, 'NT', 'Roma', 8, 1, 'Ba lö''ö sa''ae fanibo zi so ba khö Keriso Yesu.[1]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 2, 'Noa sa i''efa''ö ndra''ugö ba goroisa horö ba ba goroisa ba wa''amate andrö oroisa Geheha sangorifi andrö, ba khö Keriso Yesu.[2]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 3, 'Si tebai goroisa andrö sa, me no lö abölö ia ibe''e ösi niha andrö, da''ö nilau Lowalangi, wamatenge Ononia, famaedo nösi niha andrö, si no so barö mbawa horö, börö horö andrö, ba no i''etu''ö huku horö andrö, ba nösi niha,[3]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 4, 'ena''ö itörö niŵa''ö ba goroisa andrö, ba khöda, si lö manörö lala nösi niha, sanörö lala Geheha.[4]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 5, 'Si so ba lala nösi niha sa, ba hadia ia ba nösi niha lagohi tödöra, ba si so ba lala Geheha, ba hadia ia ba Geheha lagohi.[5]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 6, 'Era-era nösi niha sa, ba no fa''amate, ba era-era Geheha, ba no fa''auri ba fa''ohahau dödö.[6]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 7, 'Me no fa''udusa khö Lowalangi gera-era nösi niha; lö''ö sa i''o''ö goroisa Lowalangi, me tebai göi.[7]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 8, 'Tebai omasi Lowalangi zi so ba lala nösi niha.', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 9, 'Ba ya''ami, ba tenga si so ba lala nösi niha, si so ba lala Geheha ami, na so atö ba dödömi Geheha Lowalangi. Ba na so zi lö Eheha Keriso, ba tenga khö Keriso da''ö.[8]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 10, 'Ba na so Keriso ba dödömi, ba boto zi mate sa mboto, börö horö andrö, ba tödö si bohou andrö, ba sauri, börö wa''atulö dödö andrö.[9]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 11, 'Ba na so ba dödömi Geheha zanusugi Yesu moroi ba ngai zi mate, ba i''orifi dania göi mbotomi, si mate andrö, Ehehania andrö, si no so ba dödömi si no manusugi Keriso Yesu moroi ba ngai zi mate.[10]', '["Faigi 10:4; Yoh 5:24; Gal 5:16,25","Yoh 8:36; KorII 3:17","Heb 7:18,19; 2:14; Gal 3:21; 4:4; Fil 2:7; KorII 5:21","Faigi 8:1","KorI 2:14","Faigi 6:21,22; Gal 6:8","Yak 4:4","KorI 3:16; Efes 3:17; Yoh 14:23","Faigi 5:12; 7:24; Kol 2:12,13","Faigi 6:4; KorII 4:14"]', NULL),
  (3422002, 'NT', 'Roma', 8, 12, 'Ba tobali so''ömö ita, ya''ami ira talifusö, tenga so''ömö ba nösi niha, fa tatörö lala nösi niha.[11]', '["Faigi 6:18","Faigi 8:6","Gal 5:18","Gal 4:1–6; TimI 1:7","Gal 4:7; Fam 21:7; TimII 2:11,12; Yoh 17:22","KorII 4:17"]', NULL),
  (3422002, 'NT', 'Roma', 8, 13, 'Na mitörö lala nösi niha sa, ba si mate ami dania. Ba na mibunu mbua-bua mboto andrö Eheha, ba sauri ami.[12]', '["Faigi 6:18","Faigi 8:6","Gal 5:18","Gal 4:1–6; TimI 1:7","Gal 4:7; Fam 21:7; TimII 2:11,12; Yoh 17:22","KorII 4:17"]', NULL),
  (3422002, 'NT', 'Roma', 8, 14, 'Ha niha sa ira fefu nifarou Geheha Lowalangi, da''ö nono Lowalangi.[13]', '["Faigi 6:18","Faigi 8:6","Gal 5:18","Gal 4:1–6; TimI 1:7","Gal 4:7; Fam 21:7; TimII 2:11,12; Yoh 17:22","KorII 4:17"]', NULL),
  (3422002, 'NT', 'Roma', 8, 15, 'Tenga sa Eheha zawuyu nitemami, ena''ö ata''u zui ami; Eheha ndraono nitemami; moroi khönia wa mu''ao ita: He Aba, Ama![14]', '["Faigi 6:18","Faigi 8:6","Gal 5:18","Gal 4:1–6; TimI 1:7","Gal 4:7; Fam 21:7; TimII 2:11,12; Yoh 17:22","KorII 4:17"]', NULL),
  (3422002, 'NT', 'Roma', 8, 16, 'Ya''ia, Eheha andrö göi, zamaduhu''ö tödöda, wa ono Lowalangi ita.', '["Faigi 6:18","Faigi 8:6","Gal 5:18","Gal 4:1–6; TimI 1:7","Gal 4:7; Fam 21:7; TimII 2:11,12; Yoh 17:22","KorII 4:17"]', NULL),
  (3422002, 'NT', 'Roma', 8, 17, 'Ba na ono ita, ba sanema ondröita göi, sanema ondröita khö Lowalangi, awö Keriso, na nifakao göi ita awönia, ena''ö tefolakhömi göi ita awönia.[15]', '["Faigi 6:18","Faigi 8:6","Gal 5:18","Gal 4:1–6; TimI 1:7","Gal 4:7; Fam 21:7; TimII 2:11,12; Yoh 17:22","KorII 4:17"]', NULL),
  (3422002, 'NT', 'Roma', 8, 18, 'Tödögu sa, ba lö oroma wamakao ba götö da''e, ba ngai lakhömi andrö, nifa''ele''ö dania ba khöda andre.[16]', '["Faigi 6:18","Faigi 8:6","Gal 5:18","Gal 4:1–6; TimI 1:7","Gal 4:7; Fam 21:7; TimII 2:11,12; Yoh 17:22","KorII 4:17"]', NULL),
  (3422002, 'NT', 'Roma', 8, 19, 'Ibalo-baloi sa nifazökhi Lowalangi andrö, idöna-döna wama''ele''ö Ono Lowalangi andrö.[17]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 20, 'Noa sa mube''e barö mbawa zi lö boto andrö nifazökhi Lowalangi andrö, lö aoha gölö; no moroi ba zame''e ya''ia, ba wanötöna,[18]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 21, 'me ya''ia göi, nifazökhi Lowalangi andrö, ni''efa''ö ba wangosawuyu wa''atekiko andrö, ba wolohe ya''ia ba wa''aefa nono Lowalangi andrö, si so lakhömi.[19]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 22, 'Noa sa ta''ila, mangarö-ngarö fefu nifazökhi Lowalangi, awöda, afökhö khönia, irugi da''e.', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 23, 'Ba tenga ha da''ö, ya''ita göi, si no so famobörö Geheha andrö, mangarö-ngarö ita tödöda, wanötöna fa ono ita, fangefa''ö botoda andrö.[20]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 24, 'Noa sa te''orifi ita, ba wanötöna da''ö. Ba tötönafö ni''ila höröda, ba tenga tötönafö; hana wa idöna-döna na sa niha zi no i''ila hörönia?[21]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 25, 'Ba na tadöna-döna zi lö i''ila höröda, ba tabalo-baloi, tataha dödöda.[22]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 26, 'Ba si manö göi Geheha, itolo ita, me no ambö wa''abölöda. Hadia ni''andröda ena''ö, he wisa zi sökhi, ba lö''ö sa ta''ila; ba ya''ia, Eheha andrö, i''iagö salahida, ba wangarö-ngarö si lö alua baeha.', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 27, 'Ba sanekhegö tödö andrö, ba i''ila hadia niŵa''ö Geheha, me no i''o''ö zomasi Lowalangi we''amöi salahi niha ni''amoni''ö.[23]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 28, 'Ba no ta''ila, ba zangomasi''ö Lowalangi, ba oi ba zi sökhi manö lua-lua hadia ia, fefu, ba khöra si no mukaoni, nihonogöi ba da''ö.[24]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 29, 'Si no i''ila föna sa, da''ö göi nihonogöinia, ena''ö famaedo Nononia ira dania, ena''ö si a''a ia, ba no ato dalifusö.[25]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 30, 'Ba ha niha zi no ihonogöi, da''ö göi nikaoninia, ba ha niha nikaoninia, da''ö göi zatulö, iŵa''ö, ba ha niha zatulö, iŵa''ö, da''ö göi nifolakhöminia.[26]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 31, 'Ba hadia niŵa''öda ba da''ö?', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 32, 'Ya''ia, si lö alimagö Ononia, si no mame''e da''ö salahida fefu, hadia lö ifabaya manö ba da''ö wame''e buala khöda da''ö fefu?[28]', '["Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11"]', NULL),
  (3422002, 'NT', 'Roma', 8, 33, 'Ha niha zangadugö nitutuyu Lowalangi? No Lowalangi zanguma''ö satulö ira.[29]', '["Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11"]', NULL),
  (3422002, 'NT', 'Roma', 8, 34, 'Ha niha zangetu''ö huku? No so Keriso Yesu, si no mate, ba mendrua manö, me no ifuli auri, si so ba gambölö Lowalangi, ba si lului manguma''ö, salahida.', '["Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11"]', NULL),
  (3422002, 'NT', 'Roma', 8, 35, 'Ha niha zamabali ya''ita ba wa''omasi Keriso ita? Hadia, famakao! ba ma fa''afökhö, ba ma folohi, ba ma fa''olofo, ba ma fa''o''afu, ba ma ameta''uö, ba ma famunu?', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 36, 'Si mane si so ba zura: "Börö ndra''ugö, wa nibunu ndra''aga ma''ö-ma''ökhö, hulö mbiri-biri nitaba ndra''aga, ba dödö niha bö''ö."[31]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 37, 'Ba ba da''ö fefu, ba möna sibai ita, ibe''e si no mangomasi''ö ya''ita.[32]', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 38, 'III. 19 Ibalo-baloi sa nifazökhi Lowalangi andrö, idöna-döna wama''ele''ö Ono Lowalangi andrö. 20 Noa sa mube''e barö mbawa zi lö boto andrö nifazökhi Lowalangi andrö, lö aoha gölö; no moroi ba zame''e ya''ia, ba wanötöna, 21 me ya''ia göi, nifazökhi Lowalangi andrö, ni''efa''ö ba wangosawuyu wa''atekiko andrö, ba wolohe ya''ia ba wa''aefa nono Lowalangi andrö, si so lakhömi. 22 Noa sa ta''ila, mangarö-ngarö fefu nifazökhi Lowalangi, awöda, afökhö khönia, irugi da''e. 23 Ba tenga ha da''ö, ya''ita göi, si no so famobörö Geheha andrö, mangarö-ngarö ita tödöda, wanötöna fa ono ita, fangefa''ö botoda andrö. 24 Noa sa te''orifi ita, ba wanötöna da''ö. Ba tötönafö ni''ila höröda, ba tenga tötönafö; hana wa idöna-döna na sa niha zi no i''ila hörönia? 25Ba na tadöna-döna zi lö i''ila höröda, ba tabalo-baloi, tataha dödöda. 26 Ba si manö göi Geheha, itolo ita, me no ambö wa''abölöda. Hadia ni''andröda ena''ö, he wisa zi sökhi, ba lö''ö sa ta''ila; ba ya''ia, Eheha andrö, i''iagö salahida, ba wangarö-ngarö si lö alua baeha. 27 Ba sanekhegö tödö andrö, ba i''ila hadia niŵa''ö Geheha, me no i''o''ö zomasi Lowalangi we''amöi salahi niha ni''amoni''ö. 28 Ba no ta''ila, ba zangomasi''ö Lowalangi, ba oi ba zi sökhi manö lua-lua hadia ia, fefu, ba khöra si no mukaoni, nihonogöi ba da''ö. 29 Si no i''ila föna sa, da''ö göi nihonogöinia, ena''ö famaedo Nononia ira dania, ena''ö si a''a ia, ba no ato dalifusö. 30 Ba ha niha zi no ihonogöi, da''ö göi nikaoninia, ba ha niha nikaoninia, da''ö göi zatulö, iŵa''ö, ba ha niha zatulö, iŵa''ö, da''ö göi nifolakhöminia. 31 Ba hadia niŵa''öda ba da''ö? Na i''o''awögö ita Lowalangi, ba ha niha zi fa''udu khöda? 32 Ya''ia, si lö alimagö Ononia, si no mame''e da''ö salahida fefu, hadia lö ifabaya manö ba da''ö wame''e buala khöda da''ö fefu? 33 Ha niha zangadugö nitutuyu Lowalangi? No Lowalangi zanguma''ö satulö ira. 34 Ha niha zangetu''ö huku? No so Keriso Yesu, si no mate, ba mendrua manö, me no ifuli auri, si so ba gambölö Lowalangi, ba si lului manguma''ö, salahida. 35 Ha niha zamabali ya''ita ba wa''omasi Keriso ita? Hadia, famakao! ba ma fa''afökhö, ba ma folohi, ba ma fa''olofo, ba ma fa''o''afu, ba ma ameta''uö, ba ma famunu? 36 Si mane si so ba zura: "Börö ndra''ugö, wa nibunu ndra''aga ma''ö-ma''ökhö, hulö mbiri-biri nitaba ndra''aga, ba dödö niha bö''ö." 37 Ba ba da''ö fefu, ba möna sibai ita, ibe''e si no mangomasi''ö ya''ita. 38 Noa sa faduhu dödögu, he fa''amate, ba he fa''auri, he mala''ika, ba he samatörö, he si so iada''e, ba he si so dania, he sabölö, 39 ba he fa''alaŵa ba he fa''abakha, ba he hadia ia mbö''önia nifazökhi Lowalangi, ba lö i''ila ifabali ita ba wa''omasi Lowalangi andrö ita, ba khö Keriso Yesu, So''aya ya''ita.', '["Kol 3:4","Fangomb 1:2 b.t.; MozI 3:17","FetII 3:13","KorII 5:2; Luk 21:28","KorII 5:7; Heb 11:1","KorII 4:18; Heb 10:36","KorI 2:10","Efes 1:11","Faigi 11:2; Fil 3:21; Kol 1:15","TesII 2:13,14; TimII 1:2","Sin 118:6","Yoh 3:16; KorI 3:22","Yes 50:1,9; Fam 12:10,11","Faigi 4:25; Heb 7:25","Sin 44:23","YohI 5:4 b.t.; Fam 12:11","Mat 10:28","Yoh 10:28"]', NULL),
  (3422002, 'NT', 'Roma', 8, 39, 'ba he fa''alaŵa ba he fa''abakha, ba he hadia ia mbö''önia nifazökhi Lowalangi, ba lö i''ila ifabali ita ba wa''omasi Lowalangi andrö ita, ba khö Keriso Yesu, So''aya ya''ita.', '["Mat 10:28"]', NULL),
  (3422003, 'NT', 'Roma', 9, 1, 'Si ndruhu niŵa''ögu ba khö Keriso, tenga fayagu, ifaduhu''ö khögu tödögu, ba khö Geheha ni''amoni''ö,[1]', '["TimI 2:7; HalZin 5:32","MozII 32:32; KorII 12:15","MozII 4:22; 40:34; MozV 14:1; MozIII 26:42; Efes 2:12; Heb 9:1; Faigi 3:2","Faigi 1:3; Heb 1:9; TimI 3:16; YohI 5:20"]', NULL),
  (3422003, 'NT', 'Roma', 9, 3, 'Omasido sa, na si tetibo ndra''o khö Keriso, salahi dalifusögu andrö, si oi ya''aga, si ha sambua tua.[2]', '["TimI 2:7; HalZin 5:32","MozII 32:32; KorII 12:15","MozII 4:22; 40:34; MozV 14:1; MozIII 26:42; Efes 2:12; Heb 9:1; Faigi 3:2","Faigi 1:3; Heb 1:9; TimI 3:16; YohI 5:20"]', NULL),
  (3422003, 'NT', 'Roma', 9, 4, 'Iraono Gizeraeli andrö, si so fa''a''ono, awö lakhömi, awö wawu''usa li andrö, awö goroisa andrö, nibe''e khöra, awö wamosumange Lowalangi, awö gamabu''ula li andrö,[3]', '["TimI 2:7; HalZin 5:32","MozII 32:32; KorII 12:15","MozII 4:22; 40:34; MozV 14:1; MozIII 26:42; Efes 2:12; Heb 9:1; Faigi 3:2","Faigi 1:3; Heb 1:9; TimI 3:16; YohI 5:20"]', NULL),
  (3422003, 'NT', 'Roma', 9, 5, 'awö ndra tua andrö, ba ba zi otarai Keriso, me tobali niha ia, si no Lowalangi, si so barö mbawa fefu hadia ia, nisuno irugi zi lö aetu! Yaduhu.[4]', '["TimI 2:7; HalZin 5:32","MozII 32:32; KorII 12:15","MozII 4:22; 40:34; MozV 14:1; MozIII 26:42; Efes 2:12; Heb 9:1; Faigi 3:2","Faigi 1:3; Heb 1:9; TimI 3:16; YohI 5:20"]', NULL),
  (3422003, 'NT', 'Roma', 9, 6, 'Ba tenga fa uŵa''ö, no awu''a daroma li Lowalangi. Ma''uwu Gizeraeli andrö, ba tenga si no a''oi Iraono Gizeraeli.[5]', '["Faigi 3:3,4; 2:28","Yoh 9:39; MozI 21:12","Gal 3:7; 4:28","MozI 18:10","MozI 25:21","Faigi 8:28,29; 11:5,6","MozI 25:23","Mal 1:2,3"]', NULL),
  (3422003, 'NT', 'Roma', 9, 7, 'Ba no lö dozi iraono Gaberahamo ira, me no madounia, da''ö niŵa''ö: "khö Giza''aki andrö dania so nifotöi ma''uwumö."[6]', '["Faigi 3:3,4; 2:28","Yoh 9:39; MozI 21:12","Gal 3:7; 4:28","MozI 18:10","MozI 25:21","Faigi 8:28,29; 11:5,6","MozI 25:23","Mal 1:2,3"]', NULL),
  (3422003, 'NT', 'Roma', 9, 8, 'Da''e geluahania: Tenga ono Lowalangi ndraono si otarai mboto, iraono ba gamabu''ula li andrö, da''ö niŵa''ö: ma''uwu.[7]', '["Faigi 3:3,4; 2:28","Yoh 9:39; MozI 21:12","Gal 3:7; 4:28","MozI 18:10","MozI 25:21","Faigi 8:28,29; 11:5,6","MozI 25:23","Mal 1:2,3"]', NULL),
  (3422003, 'NT', 'Roma', 9, 9, 'Taroma li amabu''ula li daroma li andrö: "Na mane furi sodo, ba no so nono khö Zara."[8]', '["Faigi 3:3,4; 2:28","Yoh 9:39; MozI 21:12","Gal 3:7; 4:28","MozI 18:10","MozI 25:21","Faigi 8:28,29; 11:5,6","MozI 25:23","Mal 1:2,3"]', NULL),
  (3422003, 'NT', 'Roma', 9, 10, 'Ba tenga ha da''ö, Rebeka göi, me manabina ia khö zi ha samösa andrö, khö duada Iza''aki,[9]', '["Faigi 3:3,4; 2:28","Yoh 9:39; MozI 21:12","Gal 3:7; 4:28","MozI 18:10","MozI 25:21","Faigi 8:28,29; 11:5,6","MozI 25:23","Mal 1:2,3"]', NULL),
  (3422003, 'NT', 'Roma', 9, 11, 'me lö si tumbu ira na i, me lö nifazökhira, he si sökhi, ba he si lö sökhi — ena''ö lö tebulö, wa balazi Lowalangi wanutuyu, wa tenga balazi mbua-bua, wa moroi ba zogaoni[10] —', '["Faigi 3:3,4; 2:28","Yoh 9:39; MozI 21:12","Gal 3:7; 4:28","MozI 18:10","MozI 25:21","Faigi 8:28,29; 11:5,6","MozI 25:23","Mal 1:2,3"]', NULL),
  (3422003, 'NT', 'Roma', 9, 12, 'ba da''ö teŵa''ö khönia: "Sawuyu zi akhi dania zi a''a."[11]', '["Faigi 3:3,4; 2:28","Yoh 9:39; MozI 21:12","Gal 3:7; 4:28","MozI 18:10","MozI 25:21","Faigi 8:28,29; 11:5,6","MozI 25:23","Mal 1:2,3"]', NULL),
  (3422003, 'NT', 'Roma', 9, 13, 'Si mane si so ba zura: "Yokobo andrö, ba no u''omasi''ö, ba khö Gezau, ba no fa''udu ndra''o."[12]', '["Faigi 3:3,4; 2:28","Yoh 9:39; MozI 21:12","Gal 3:7; 4:28","MozI 18:10","MozI 25:21","Faigi 8:28,29; 11:5,6","MozI 25:23","Mal 1:2,3"]', NULL),
  (3422003, 'NT', 'Roma', 9, 14, 'Ba hadia niŵa''öda? Hadia, so zi lö atulö nilau Lowalangi? Tenga si manö.[13]', '["MozV 32:4; Yob 34:10 b.t.","MozII 33:19","Fangomb 9:11; Efes 2:8 b.t.","MozII 9:15,16","Faigi 11:30–32; MozII 7:3; 8:15","Yes 45:9 b.t.","Yer 18, 6. TimII 2, 20","Faigi 2:4 b.t.; FetI 2:8","Faigi 8:29,30; Efes 1:4–12; HalZin 13:48","Faigi 3, 29","Hos 2:23; FetI 2:10","Hos 1:10","Yes 10:22,23","Yes 1:9"]', NULL),
  (3422003, 'NT', 'Roma', 9, 15, 'Imane sa khö Moze: Na so zebua dödögu, ba ebua dödögu khönia; ba na so zahakhö dödögu, ba ahakhö dödögu khönia?[14]', '["MozV 32:4; Yob 34:10 b.t.","MozII 33:19","Fangomb 9:11; Efes 2:8 b.t.","MozII 9:15,16","Faigi 11:30–32; MozII 7:3; 8:15","Yes 45:9 b.t.","Yer 18, 6. TimII 2, 20","Faigi 2:4 b.t.; FetI 2:8","Faigi 8:29,30; Efes 1:4–12; HalZin 13:48","Faigi 3, 29","Hos 2:23; FetI 2:10","Hos 1:10","Yes 10:22,23","Yes 1:9"]', NULL),
  (3422003, 'NT', 'Roma', 9, 16, 'Tobali tenga sa fa''edöna niha ba tenga famoregenia, ha fa''ahakhö dödö Lowalangi andrö.[15]', '["MozV 32:4; Yob 34:10 b.t.","MozII 33:19","Fangomb 9:11; Efes 2:8 b.t.","MozII 9:15,16","Faigi 11:30–32; MozII 7:3; 8:15","Yes 45:9 b.t.","Yer 18, 6. TimII 2, 20","Faigi 2:4 b.t.; FetI 2:8","Faigi 8:29,30; Efes 1:4–12; HalZin 13:48","Faigi 3, 29","Hos 2:23; FetI 2:10","Hos 1:10","Yes 10:22,23","Yes 1:9"]', NULL),
  (3422003, 'NT', 'Roma', 9, 17, 'Si mane sa niŵa''ö khö Wara''o, si so ba zura: "Da''ö sibai mbörö, wa u''asogö ndra''ugö, ena''ö ufa''ele''ö wa''abölögu, ba khömö andrö, ba ena''ö te''ombakha''ö döigu ba guli danö ma''asagörö."[16]', '["MozV 32:4; Yob 34:10 b.t.","MozII 33:19","Fangomb 9:11; Efes 2:8 b.t.","MozII 9:15,16","Faigi 11:30–32; MozII 7:3; 8:15","Yes 45:9 b.t.","Yer 18, 6. TimII 2, 20","Faigi 2:4 b.t.; FetI 2:8","Faigi 8:29,30; Efes 1:4–12; HalZin 13:48","Faigi 3, 29","Hos 2:23; FetI 2:10","Hos 1:10","Yes 10:22,23","Yes 1:9"]', NULL),
  (3422003, 'NT', 'Roma', 9, 18, 'Tobali na so zedöna ia, ba ahakhö dödönia, ba na so zedöna ia zui, ba i''abe''e''ö dödö da''ö.[17]', '["MozV 32:4; Yob 34:10 b.t.","MozII 33:19","Fangomb 9:11; Efes 2:8 b.t.","MozII 9:15,16","Faigi 11:30–32; MozII 7:3; 8:15","Yes 45:9 b.t.","Yer 18, 6. TimII 2, 20","Faigi 2:4 b.t.; FetI 2:8","Faigi 8:29,30; Efes 1:4–12; HalZin 13:48","Faigi 3, 29","Hos 2:23; FetI 2:10","Hos 1:10","Yes 10:22,23","Yes 1:9"]', NULL),
  (3422003, 'NT', 'Roma', 9, 19, 'Ba ömane khögu: Ba hana wa ibe''e horöda? Ha niha sa zangila molaŵa zomasi ia?', '["MozV 32:4; Yob 34:10 b.t.","MozII 33:19","Fangomb 9:11; Efes 2:8 b.t.","MozII 9:15,16","Faigi 11:30–32; MozII 7:3; 8:15","Yes 45:9 b.t.","Yer 18, 6. TimII 2, 20","Faigi 2:4 b.t.; FetI 2:8","Faigi 8:29,30; Efes 1:4–12; HalZin 13:48","Faigi 3, 29","Hos 2:23; FetI 2:10","Hos 1:10","Yes 10:22,23","Yes 1:9"]', NULL),
  (3422003, 'NT', 'Roma', 9, 20, 'Böi ua, ya''ugö niha, ha niha ndra''ugö, wa ötahigö Lowalangi? Hadia, tola iŵa''ö omböila khö zomböi ya''ya: Hana wa ömanö wamazökhi ya''o?[18]', '["MozV 32:4; Yob 34:10 b.t.","MozII 33:19","Fangomb 9:11; Efes 2:8 b.t.","MozII 9:15,16","Faigi 11:30–32; MozII 7:3; 8:15","Yes 45:9 b.t.","Yer 18, 6. TimII 2, 20","Faigi 2:4 b.t.; FetI 2:8","Faigi 8:29,30; Efes 1:4–12; HalZin 13:48","Faigi 3, 29","Hos 2:23; FetI 2:10","Hos 1:10","Yes 10:22,23","Yes 1:9"]', NULL),
  (3422003, 'NT', 'Roma', 9, 21, 'Ma tenga ba danga zamösi bowoa so la''uri, fa tola ibali''ö nahia zi sökhi ösa ba nahia zi lö sökhi ösa, zi ha sambua böröta?[19]', '["MozV 32:4; Yob 34:10 b.t.","MozII 33:19","Fangomb 9:11; Efes 2:8 b.t.","MozII 9:15,16","Faigi 11:30–32; MozII 7:3; 8:15","Yes 45:9 b.t.","Yer 18, 6. TimII 2, 20","Faigi 2:4 b.t.; FetI 2:8","Faigi 8:29,30; Efes 1:4–12; HalZin 13:48","Faigi 3, 29","Hos 2:23; FetI 2:10","Hos 1:10","Yes 10:22,23","Yes 1:9"]', NULL),
  (3422003, 'NT', 'Roma', 9, 30, 'Ba hadia niŵa''öda? Niha baero, si lö mangalui fa''atulö dödö, ba no falukha wa''atulö dödö, fa''atulö dödö moroi ba wamati.[27]', '["Faigi 10:20; 3:23","Faigi 11:7 b.t.","Yes 58:2; KorI 1:23","Yes 8:14; 28:16"]', NULL),
  (3422004, 'NT', 'Roma', 10, 1, 'He ya''ami ira talifusö! Da''ö wa''omasigu ba da''ö wangandrögu khö Lowalangi, ba khöra andrö, ena''ö lasöndra wangorifi.[1]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 2, 'Si ndruhu sa, tebai ubini''ö, laforege sa ba khö Lowalangi, ba no ambö gera-era.[2]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 3, 'Me lö''ö sa aboto ba dödöra wa''atulö dödö andrö khö Lowalangi, ba me la''alui wamoguna''ö fa''atulö dödö khöra, ba lö la''o''ö wa''atulö dödö andrö khö Lowalangi.[3]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 4, 'Lua-lua goroisa sa, ba Keriso, ba wama''ema fa''atulö dödö ba zamati fefu.[4]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 5, 'mane sa Moze ba wa''atulö dödö andrö, soroi ba goroisa: "Na so zamalua ya''ia, ba tobali fangorifinia."[5]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 6, 'Ba imane fa''atulö dödö andrö, soroi ba wamati: "Böi ŵa''ö tödöu: Ha niha zi möi yaŵa ba zorugo?" ba wangai Keriso, ba wolohe mitou;[6]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 7, 'ba ma: "Ha niha zi möi mitou, ba mbanua tou?" ba wangai Keriso, moroi ba ngai zi no mate.', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 8, 'Hadia sa niŵa''önia? "No ahatö khöu daroma li andrö, ba mbeweu ba ba dödöu", taroma li ba wamati andrö, ni''ombakha''öma.[7]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 9, 'Na itehe sa beweu So''aya Yesu ba na faduhu dödöu, no isusugi ia Lowalangi moroi ba ngai zi mate, ba ni''orifi ndra''ugö.[8]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 10, 'Ba dödöda sa so wamati, ba wogamö fa''atulö dödö, ba beweda zanehe, ba wogamö fangorifi.', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 11, 'Si mane sa ba zura: "Dozi samati khönia ba tenga saila dania."[9]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 12, 'Lö''ö sa faehu ira niha Yehuda Ndrawa Heleni. Ha sa samösa Zo''aya ya''ira, ba zi no fahöna fefu hadia ia, ba ziangaröfi li ya''ia, fefu.[10]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 13, '"Dozi sa, ha niha ziangaröfi li töi Zo''aya, ba ni''orifi."[11]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 14, 'Ba he lawisa wa''angaröfi li, ba zi lö mamati ira? Ba he lawisa wamati ba zi lö nirongora, ba he lawisa wamondrongo, na lö sangombakha?', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 15, 'Ba he lawisa wangombakha, na lö mufatenge ira? Si mane si so ba zura: "Wa''asökhi lahe zangombakha turia somuso dödö, si sökhi andrö."[12]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 16, 'Ba lö dozi la''o''ö turia somuso dödö andrö. Imane sa Yesaya: "He So''aya, ha niha zi faduhu tödö ba duria andrö khöma?"[13]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 17, 'Tobali moroi ba duria wamati andrö, ba turia andrö, ba moroi ba daroma li Keriso.[14]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 18, 'Ba da''ö niŵa''ögu: Hadia, lö nirongora? Noa sa: "No itörö danö ma''afefu lira, ba no irugi wondrege guli danö niŵa''öra andrö."[15]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 19, 'Ba da''ö niŵa''ögu: Hadia lö saboto ba dödö Ndraono Gizeraeli? Moze zi oföna manguma''ö: "Afökhö dania dödömi, ube''e, ba mbanua si tenga banuagu, ba mofönu ami ba mbanua sambö ere-era, ube''e."[16]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 20, 'Ba lö alaŵö Yesaya ba imane: "No lasöndra ndra''o si lö mangalui ya''o, no to''ele ndra''o ba zi lö manofu ya''o."[17]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422004, 'NT', 'Roma', 10, 21, 'Ba ba Ndraono Gizeraeli, ba imane: "Ma''ö-ma''ökhö manö no u''oro''ö dangagu ba mbanua si lö mamondrongo li, si lö edöna molo''ö."[18]', '["Faigi 9:1 b.t.","HalZin 22:3; Gal 4:17","Faigi 9:31,32; Yoh 16:2 b.t.","Mat 5:17,18; HalZin 13:39; Gal 3:24","MozIII 18:5; Luk 10:28","MozV 30:12,13","MozV 30:14","Mat 10:32; KorII 4:13; Faigi 4:24,25","Faigi 9:33; Yes 28:16","Faigi 3:22; HalZin 15:9","Yoel 2:32","Yes 52:7","Yes 53:1; Yoh 12:38; 4:24","Yoh 17:20; TesI 2:13","Sin 19:5; Kol 1:23","Faigi 11:11; MozV 32:21","Yes 65:1","Yes 65:2"]', NULL),
  (3422005, 'NT', 'Roma', 11, 1, 'Ba da''ö niŵa''ögu: Hadia, no itibo''ö mbanuania Lowalangi? Tenga si manö! Ya''odo sa göi, ba Iraono Gizeraeli, ma''uwu Gaberahamo, mado Mbeniyami.[1]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 2, 'Lö nitibo''ö Lowalangi banuania, si no i''ila föna. Ma lö nirongomi, hadia niŵa''ö ba zura, ba khö Geliya andrö? Me humede ia khö Lowalangi, ba khö Ndraono Gizeraeli andrö, me imane:[2]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 3, '"He So''aya, no labunu zama''ele''ö andrö khöu, no ladudugö naha wame''e sumange khöu, ba hatö ya''o zi tosai, ba la''alui wamunu ya''o."[3]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 4, 'Ba hadia niŵa''ö Lowalangi, wanema linia? Imane: "No usaigö khögu, 7000 niha, si lö irai manuhi tanö föna Mba''ali andrö."[4]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 5, 'Ba si manö göi ba götö da''e: so zi tosai, dali wanutuyu andrö, ba wa''ebua dödö andrö.[5]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 6, 'Ba na moroi ba wa''ebua dödö, ba tenga sa''ae moroi ba mbua-bua; na si manö ena''ö, ba tenga sa''ae fa''ebua dödö wa''ebua dödö andrö.[6]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 7, 'Ba he wisa? ni''alui Ndraono Gizeraeli andrö, ba lö nisöndrara; ba no lasöndra nitutuyu andrö; ba si tosai, ba ni''abe''e''ö tödö.[7]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3422005, 'NT', 'Roma', 11, 8, 'Si mane si so ba zura: "No ibe''e khöra Lowalangi geheha wanukö-nuköu, no ibe''e khöra hörö ba wa lö mangila ba tögi dalinga ba wa lö mamondrongo, irugi ma''ökhö andre."[8]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 9, 'Ba imane Dawido: "Yatobali tandraŵa khöra naha wemanga andrö khöra ba fondra''u ba fa''ate''ala ba sulö.[9]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 10, 'Nifobalunö höröra, ena''ö lö la''ila; ba hulura, ba faöndrö, böi mamalö-malö."', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 11, 'Ba da''ö niŵa''ögu: Hadia, andrö manendre ira, ena''ö alau? Tenga si manö. Lalöra mbörö wö sa, wa irugi niha baero fangorifi andrö, ena''ö tefarou dödöra.[10]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 12, 'Ba na möi hare niha guli danö lalöra, ba na hare niha baero de''alara, ba tenga mendrua manö na ahori molo''ö ira?[11]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 13, 'Ba da''ö ligu khömi, ya''ami niha baero: Ndrohu-ndrohu zi no sinenge ba niha baero ndra''o, ba usuno halöŵö andrö, niŵa''ö khögu,[12]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 14, 'ma atö u''ila ufarou dödö dalifusögu andrö, ma atö u''ila u''orifi ösa ira.', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 15, 'Na tobali fangatulö''ö niha guli danö wanibo ya''ira andrö, ba hadia wanema ya''ira, na tenga fa''auri moroi ba zi mate?[13]', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 16, 'Ba na ni''amoni''ö wamobörö andrö, ba ni''amoni''ö göi zoya, ba na ni''amoni''ö ŵa''a, ba ni''amoni''ö göi ndraha.', '["Yer 31:37; Fil 3:5","Faigi 8:29 b.t.; Sin 94:14","RazI 19:10,14","RazI 19:18","Faigi 9:27","Faigi 4:4; Gal 2:16","Faigi 9:16,31; KorII 3:14","Yes 29:10; 6:9,10; HalZin 28:26 b.t.","Sin 69:23,24","HalZin 13:46; Faigi 10:19","Yer 4:1,2","Faigi 1:5","Hes 37"]', NULL),
  (3422005, 'NT', 'Roma', 11, 17, 'Ba na no mufafatö ndraha ösa, ba na no mufatöfa ndra''ugö, awöra, ya''ugö andrö, si no falo ndru''u, ba na no mo''urakha ndra''ugö ba ŵa''a falo andrö ba ba wa''amofanikhania,[14]', '["Yer 11:16 b.t.; Efes 2:11 b.t.","Heb 3:19; 4:2; KorI 10:12","FetII 2:4,5","Yoh 15:2,6","Faigi 14:4"]', NULL),
  (3422005, 'NT', 'Roma', 11, 18, 'ba böi suno ndra''ugö, ba ndraha andrö. Ba na ösuno ndra''ugö, ba tenga sa atö ya''ugö zanaya ŵa''a andrö, ŵa''a andrö zanaya ya''ugö.', '["Yer 11:16 b.t.; Efes 2:11 b.t.","Heb 3:19; 4:2; KorI 10:12","FetII 2:4,5","Yoh 15:2,6","Faigi 14:4"]', NULL),
  (3422005, 'NT', 'Roma', 11, 19, 'Ba ömane: No mufafatö ndraha andrö, ena''ö tefatöfa ndra''odo. Duhu!', '["Yer 11:16 b.t.; Efes 2:11 b.t.","Heb 3:19; 4:2; KorI 10:12","FetII 2:4,5","Yoh 15:2,6","Faigi 14:4"]', NULL),
  (3422005, 'NT', 'Roma', 11, 20, 'Me lö mamati ira, andrö tefafatö ira, ba ya''ugö, ba moroi ba wamati, wa monaha ndra''ugö. Böi fayaŵa dödöu, sata''u ndra''ugö.[15]', '["Yer 11:16 b.t.; Efes 2:11 b.t.","Heb 3:19; 4:2; KorI 10:12","FetII 2:4,5","Yoh 15:2,6","Faigi 14:4"]', NULL),
  (3422005, 'NT', 'Roma', 11, 21, 'Na noa sa itibo''ö Lowalangi zi no to''ua daha; ba itibo''ö göi ndra''ugö.[16]', '["Yer 11:16 b.t.; Efes 2:11 b.t.","Heb 3:19; 4:2; KorI 10:12","FetII 2:4,5","Yoh 15:2,6","Faigi 14:4"]', NULL),
  (3422005, 'NT', 'Roma', 11, 22, 'Andrö töngöni wa''ebua dödö Lowalangi andrö ba fa''abe''enia göi; ba zi no molalö faigi wa''abe''enia, ba fa''ebua dödö Lowalangi, ba ba khömö andrö, na lö tebulö ndra''ugö ba wa''ebua dödö andrö ba na tenga si manö, ba ni''eŵa göi ndra''ugö dania.[17]', '["Yer 11:16 b.t.; Efes 2:11 b.t.","Heb 3:19; 4:2; KorI 10:12","FetII 2:4,5","Yoh 15:2,6","Faigi 14:4"]', NULL),
  (3422005, 'NT', 'Roma', 11, 23, 'Ba ya''ira göi, na tenga si lö mamalö-malö khöra wa lö mamati andrö, ba nifatöfa ira dania; lö''ö sa ambö wa''abölö Lowalangi; i''ila ifuli ifatöfa ira.[18]', '["Yer 11:16 b.t.; Efes 2:11 b.t.","Heb 3:19; 4:2; KorI 10:12","FetII 2:4,5","Yoh 15:2,6","Faigi 14:4"]', NULL),
  (3422005, 'NT', 'Roma', 11, 24, 'Na ni''eŵa sa ndra''ugö ba zi to''ua falo ndru''u ba na nifatöfa ba falo si sökhi, si tenga lala mena''ö, ba tenga mendru''a manö ira, si no to''ua ya''ia, nifatöfa ba falo khöra andrö.', '["Yer 11:16 b.t.; Efes 2:11 b.t.","Heb 3:19; 4:2; KorI 10:12","FetII 2:4,5","Yoh 15:2,6","Faigi 14:4"]', NULL),
  (3422005, 'NT', 'Roma', 11, 25, 'Tebai sa ubini''ö khömi, ya''ami ira talifusö, zi no tobini andrö, fa böi miŵa''ö tödömi satua-tua ami: wa no göna fangabe''e dödö Ndraono Gizeraeli ösa, irugi no molo''ö gahonoa niha baero andrö,[19]', '["Luk 21:24; Yoh 10:9,16","MozV 4:30,31; Yes 59:20,21","Yer 31:31–34","TesI 2:15 b.t.; Faigi 15:8","MozIV 23:19","Tit 3:3 b.t.","Gal 3:22; Sin 145:9"]', NULL),
  (3422005, 'NT', 'Roma', 11, 26, 'ba awena dania te''orifi Ndraono Gizeraeli ma''afefu, si mane si so ba zura: "Moroi ba Ziona i''otarai dania sangorifi andrö, iheta dania ba ndraono Yakobo wa lö ba dödöra Lowalangi;[20]', '["Luk 21:24; Yoh 10:9,16","MozV 4:30,31; Yes 59:20,21","Yer 31:31–34","TesI 2:15 b.t.; Faigi 15:8","MozIV 23:19","Tit 3:3 b.t.","Gal 3:22; Sin 145:9"]', NULL),
  (3422005, 'NT', 'Roma', 11, 27, 'ba da''ö wawu''usa li andrö khögu khöra, na uheta horöra andrö".[21]', '["Luk 21:24; Yoh 10:9,16","MozV 4:30,31; Yes 59:20,21","Yer 31:31–34","TesI 2:15 b.t.; Faigi 15:8","MozIV 23:19","Tit 3:3 b.t.","Gal 3:22; Sin 145:9"]', NULL),
  (3422005, 'NT', 'Roma', 11, 28, 'Tobali si fa''udu ira na dali lala duria somuso dödö andrö, börö ami; ba na dali wanutuyu ya''ira andrö, ba ni''omasi''ö ira, börö ndra tua.[22]', '["Luk 21:24; Yoh 10:9,16","MozV 4:30,31; Yes 59:20,21","Yer 31:31–34","TesI 2:15 b.t.; Faigi 15:8","MozIV 23:19","Tit 3:3 b.t.","Gal 3:22; Sin 145:9"]', NULL),
  (3422005, 'NT', 'Roma', 11, 29, 'Lö''ö sa mangesa dödö Lowalangi ba game''elania ba ba wogaoninia andrö[23]', '["Luk 21:24; Yoh 10:9,16","MozV 4:30,31; Yes 59:20,21","Yer 31:31–34","TesI 2:15 b.t.; Faigi 15:8","MozIV 23:19","Tit 3:3 b.t.","Gal 3:22; Sin 145:9"]', NULL),
  (3422005, 'NT', 'Roma', 11, 30, 'Hulö si mane ya''ami sa, si lö molo''ö li Lowalangi föna, ba si no falukha wa''ahakhö dödö iada''e, börö wa lö molo''ö ira;[24]', '["Luk 21:24; Yoh 10:9,16","MozV 4:30,31; Yes 59:20,21","Yer 31:31–34","TesI 2:15 b.t.; Faigi 15:8","MozIV 23:19","Tit 3:3 b.t.","Gal 3:22; Sin 145:9"]', NULL),
  (3422005, 'NT', 'Roma', 11, 31, 'si manö göi ira, lö la''o''ö iada''e, ena''ö falukha ira göi wa''ahakhö dödö, moroi ba wa''ahakhö dödö andrö, si no falukha ami.', '["Luk 21:24; Yoh 10:9,16","MozV 4:30,31; Yes 59:20,21","Yer 31:31–34","TesI 2:15 b.t.; Faigi 15:8","MozIV 23:19","Tit 3:3 b.t.","Gal 3:22; Sin 145:9"]', NULL),
  (3422005, 'NT', 'Roma', 11, 32, 'Noa sa ifa''u''u manö ira fefu Lowalangi, ba wa lö molo''ö, ena''ö ihakhösi tödö ira fefu.[25]', '["Luk 21:24; Yoh 10:9,16","MozV 4:30,31; Yes 59:20,21","Yer 31:31–34","TesI 2:15 b.t.; Faigi 15:8","MozIV 23:19","Tit 3:3 b.t.","Gal 3:22; Sin 145:9"]', NULL),
  (3422005, 'NT', 'Roma', 11, 33, 'Ha lö abakha wa no a''oi so manö khö Lowalangi ba fa''atua-tuania ba fangilania andrö! Si lö aboto ba dötö niha wanguhukunia, ba si lö isöndra niha lala andrö khönia![26]', '["Yob 11:6,7","Yes 40:13,14; KorI 2:16","Yob 41:2","KorI 8:6; Rom 16:27; FetII 3:11"]', NULL),
  (3422005, 'NT', 'Roma', 11, 34, 'Ha niha sa zi no aboto ba dödö dödö Zo''aya andrö? ba ha niha zi no mamolala tödönia?[27]', '["Yob 11:6,7","Yes 40:13,14; KorI 2:16","Yob 41:2","KorI 8:6; Rom 16:27; FetII 3:11"]', NULL),
  (3422005, 'NT', 'Roma', 11, 35, 'Ma ha niha zi no mangöhönagö fame''e khönia hadia ia, nisulöni khönia dania?[28]', '["Yob 11:6,7","Yes 40:13,14; KorI 2:16","Yob 41:2","KorI 8:6; Rom 16:27; FetII 3:11"]', NULL),
  (3422005, 'NT', 'Roma', 11, 36, 'Moroi khönia sa fefu hadia ia ba ya''ia zamatörö ba ba khönia lua-lua hadia ia fefu. Ya''ia nifosumange, irugi zi lö aetu! Yaduhu.[29]', '["Yob 11:6,7","Yes 40:13,14; KorI 2:16","Yob 41:2","KorI 8:6; Rom 16:27; FetII 3:11"]', NULL),
  (3422006, 'NT', 'Roma', 12, 1, 'Andrö ufarou dödömi, ya''ami ira talifusö, moroi ba wa''ahakhö dödö Lowalangi andrö, ena''ö mibe''e sumange mbotomi, sumange sauri, ni''amoni''ö, somasi Lowalangi; da''ö wamosumange Lowalangi khömi, si so tödö.[1]', '["Faigi 6:13","Efes 4:17,22 b.t.; 5:10,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 2, 'Ba böi mifaomagö ami ba niha zi sagötö tanö andre, mibali''ö ami, wamohouni era-era dödömi, ena''ö mi''ila mitimba tödömi hadia nilau dödö Lowalangi, hadia zi sökhi, hadia wa''omasinia ba hadia zo''ahonoa.[2]', '["Faigi 6:13","Efes 4:17,22 b.t.; 5:10,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 3, 'Uŵa''ö sa khömi, dozi ami, moroi ba wa''ebua dödö andrö, si no falukha ndra''o, böi fayaŵa zamösana, ha ndrohu-ndrohu, era-era zatua-tua yamu''alui, dali zu''a-su''a wamati andrö, nindrohugö Lowalangi ba zamösana.[3]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 4, 'Hulö mbotoda sa, me no oya ndroto-ndroto khöda, ba me tenga ha sambalö halöŵö ndroto-ndroto andrö,[4]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 5, 'si manö ita ba khö Keriso, ya''ita si no ato, ha sambua boto ita, ba no ndroto-ndroto ita, zamösana ba khö nawönia;[5]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 6, 'Ba no faehu game''ela andrö khöda, balazi wa''ebua dödö andrö, si no falukha ita: Na fama''ele''ö, ba yafaudu ba wamati andrö;[6]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 7, 'ba na so zi so halöŵö, ba yamuhaogö halöŵönia, ba na famahaö, ba yamamahaö;[7]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 8, 'ba na famarou tödö, ba yamufarou dödö niha; na so zame''e ame''ela, ba ya''adölö dödönia wame''e; na samatörö, ba yamu''oigö dödönia; ba na sahakhö tödö si numana, ba ya moroi ba dödönia.[8]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 9, 'Ba wangomasi''ö awö andrö, ba böi faruka wamini tödö. Mi''ogorofi zi lö sökhi andrö, mi''olembai zi sökhi.[9]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 10, 'Fangomasi''ö talifusö andrö, ba ya moroi ba dödömi, faoma mihulö naŵomi, wamosumange ya''ia.[10]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 11, 'Ba wa''owölö-ölö andrö, ba böi atage ami; ya''atarö dödömi, ya enoni Zo''aya ami.', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 12, 'Mi''omusoi''ö dödömi ba wanötöna andrö, mitaha dödömi, na göna ami famakao; böi mifamalö-malö wangandrö.[11]', '["Faigi 11:20; Gal 6:3; KorII 10:13","KorI 12:12 b.t.","KorI 12:27","KorI 12:4; 14:1","FetI 4:10,11","Mat 6:2 b.t.; KorII 9:7","TimI 1:5; Sin 34:15; Amos 5:15","Heb 13:1; FetI 1:22; 2:17","Faigi 5:2 b.t.; 8:24 b.t.; TesI 5:16,17"]', NULL),
  (3422006, 'NT', 'Roma', 12, 13, 'Na so ni''amoni''ö, sambö-ambö hadia ia, ba mitolo; mifamaha ami ba wame''e gö dome.[12]', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422006, 'NT', 'Roma', 12, 14, 'Mifahowu''ö zolohi ya''ami; mifahowu''ö ba böi mi''angelifi.[13]', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422006, 'NT', 'Roma', 12, 15, 'Mi''omusoi''ö dödömi awö zomuso tödö, ba mi''ege-ege awö zege-ege.[14]', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422006, 'NT', 'Roma', 12, 16, 'ya ha sara dödömi khö nawömi, böi mifayaŵa, tou mi''iagö, awö zide-ide, böi miŵa''ö tödömi satua-tua ami.[15]', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422006, 'NT', 'Roma', 12, 17, 'Böi misulöni zi lö sökhi awönia si lö sökhi, ba niha; si sökhi mifatou-tou, ba niha fefu.[16]', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422006, 'NT', 'Roma', 12, 18, 'Na dali ami, ba ya''atulö ami ba niha fefu.[17]', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422006, 'NT', 'Roma', 12, 19, 'Böi milau mbalömi, ya''ami ni''omasi''ögu! mifonaha wönu andrö; noa sa so ba zura: "khögu wolau balö, ya''o zanulöni, iŵa''ö So''aya."[18]', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422006, 'NT', 'Roma', 12, 20, 'Ba na olofo zi fa''udu khöu, ba be''e gönia, ba na owökhi dödönia, ba fabadugö khönia nidanö. Na ölau da''ö sa, ba ö''owuloi mbo galitö ba högönia.[19]', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422006, 'NT', 'Roma', 12, 21, 'Böi ilaŵa ndra''ugö si lö sökhi, be''e folaŵa zi lö sökhi zi sökhi.', '["FetI 4:9; Heb 6:10; 13:2","Mat 5:44; FetI 3:9","Luk 15:32","Faigi 15:5; KorI 1:10; Fil 2:2,3; Yes 5:21","Faigi 12:14; Amaed 20:22; KorII 8:21","Faigi 14:19; Heb 12:14","MozIII 19:18; Mat 5:39 b.t.; MozV 32:35","Amaed 25:21,22"]', NULL),
  (3422007, 'NT', 'Roma', 13, 1, 'Dozi niha ndramu''o''ö li zalaŵa, si so ira barö mbawa: lö''ö sa fa''asalaŵa, na tenga moroi ba Lowalangi, ba nifataro Lowalangi zalaŵa si so andrö.[1]', '["Tit 3:1; FetI 2:13,14; Yoh 19:11","Nga''ötII 19:6 b.t.","Mat 22:21"]', NULL),
  (3422007, 'NT', 'Roma', 13, 2, 'Tobali, ha niha zolaŵa salaŵa, ba ilaŵa nihonogöi Lowalangi; ba solaŵa andrö, ba la''a''asogö khöra huku.', '["Tit 3:1; FetI 2:13,14; Yoh 19:11","Nga''ötII 19:6 b.t.","Mat 22:21"]', NULL),
  (3422007, 'NT', 'Roma', 13, 3, 'Samatörö andrö sa, ba tenga fameta''u ba mbua-bua si sökhi, no fameta''u ba mbua-bua si lö sökhi. Ba na omasi''ö lö ata''u''ö zalaŵa, ba si sökhi lau, ba isuno ndra''ugö.', '["Tit 3:1; FetI 2:13,14; Yoh 19:11","Nga''ötII 19:6 b.t.","Mat 22:21"]', NULL),
  (3422007, 'NT', 'Roma', 13, 4, 'Enoni Lowalangi sa ia, soguna khöu. Ba na ölau zi lö sökhi, ba ata''ufi ia; tenga sa mai-mai, wa so khönia wöda; enoni Lowalangi sa ia, solau balö, samatörö huku ba zolau si lö sökhi.[2]', '["Tit 3:1; FetI 2:13,14; Yoh 19:11","Nga''ötII 19:6 b.t.","Mat 22:21"]', NULL),
  (3422007, 'NT', 'Roma', 13, 5, 'Andrö lö tola lö ta''o''ö lira tenga ha ba wotu andrö, fa lö itegu ita tödöda göi.', '["Tit 3:1; FetI 2:13,14; Yoh 19:11","Nga''ötII 19:6 b.t.","Mat 22:21"]', NULL),
  (3422007, 'NT', 'Roma', 13, 6, 'Andrö mibe''e mbeo göi, sangai halöŵö Lowalangi sa ira, lö tola lö laŵa''ö-ŵa''ö.', '["Tit 3:1; FetI 2:13,14; Yoh 19:11","Nga''ötII 19:6 b.t.","Mat 22:21"]', NULL),
  (3422007, 'NT', 'Roma', 13, 7, 'Midozigö ira, wame''e ömömi, böli döla högö ba zanema böli döla högö, ba beo ba zanema beo, ba fa''ata''u ba ni''ata''ufi, ba sumange ba nifosumange.[3]', '["Tit 3:1; FetI 2:13,14; Yoh 19:11","Nga''ötII 19:6 b.t.","Mat 22:21"]', NULL),
  (3422007, 'NT', 'Roma', 13, 8, 'Boi mo''ömö ami hadia ia, gofu ha ökhö, ha fa faoma mi''omasi''ö nawömi; sangomasi''ö awönia sa, ba no i''o''ö goroisa.[4]', '["Yoh 13:34; TimI 1:5","Gal 5:14; MozII 20:13 b.t.; MozIII 19:18; Mat 22:39,40","KorI 13:4 b.t."]', NULL),
  (3422007, 'NT', 'Roma', 13, 9, 'Oroisa andrö sa: "Böi ohorö!" "böi ange''e!" "böi anagö!" "böi angisö!" ba hadia ia goroisa bö''ö, ba no tefarahugö ba niŵa''ö andrö: "Omasi''ö zahatö khöu, si mane fa''omasiu ndra''ugö".[5]', '["Yoh 13:34; TimI 1:5","Gal 5:14; MozII 20:13 b.t.; MozIII 19:18; Mat 22:39,40","KorI 13:4 b.t."]', NULL),
  (3422007, 'NT', 'Roma', 13, 10, 'Fa''omasi andrö, ba lö ilau zi lö sökhi khö nawönia, andrö wa folo''ö oroisa wa''omasi andrö.[6]', '["Yoh 13:34; TimI 1:5","Gal 5:14; MozII 20:13 b.t.; MozIII 19:18; Mat 22:39,40","KorI 13:4 b.t."]', NULL),
  (3422007, 'NT', 'Roma', 13, 11, 'Andrö mi''o''ö da''ö, me no mi''ila ginötö andrö, wa no irugi baŵa khömi, ba wemaoso moroi ba wemörö; noa sa ahatö khöda wangorifi andrö iada''e moroi me awena mamati ita.[7]', '["Efes 5:14,16","TesI 5:6,8; Efes 5:11; 6:13","Luk 21:34; TesI 4:3 b.t.; Yak 3:14","Gal 3:27; 5:16; KorI 9:27; FetI 2:11"]', NULL),
  (3422007, 'NT', 'Roma', 13, 12, 'No numalö zi bongi, moluo sa''ae. Ba databöhöi sa''ae mbua-bua ba zogömi-gömi andrö, ba ta''aro''ö ita fangöna ba zi moluo.[8]', '["Efes 5:14,16","TesI 5:6,8; Efes 5:11; 6:13","Luk 21:34; TesI 4:3 b.t.; Yak 3:14","Gal 3:27; 5:16; KorI 9:27; FetI 2:11"]', NULL),
  (3422007, 'NT', 'Roma', 13, 13, 'Data''onangegö wanörö lalada, si mane na moluo, böi femanga-manga ba famadu-madu tuo, böi fohorö-horö ba hokha, böi fagua-guasa ba fa''afökhö dödö;[9]', '["Efes 5:14,16","TesI 5:6,8; Efes 5:11; 6:13","Luk 21:34; TesI 4:3 b.t.; Yak 3:14","Gal 3:27; 5:16; KorI 9:27; FetI 2:11"]', NULL),
  (3422007, 'NT', 'Roma', 13, 14, 'mihalö balu-balumi Zo''aya ya''ita, Yesu Keriso, ba fangehaomi ösimi andrö, ba böi ba wolo''ö fangisönia.[10]', '["Efes 5:14,16","TesI 5:6,8; Efes 5:11; 6:13","Luk 21:34; TesI 4:3 b.t.; Yak 3:14","Gal 3:27; 5:16; KorI 9:27; FetI 2:11"]', NULL),
  (3422008, 'NT', 'Roma', 14, 1, 'Si lö abölö famati na,ba mitehe göi, ba böi ba wanguhuku tödönia.[1]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 2, 'So zanguma''ö tola manö i''a fefu, hadia ia, ba sambö fa''abe''e, ba i''a gule-gule.[2]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 3, 'Böi yamu''ambösi zi lö manga si manga, ba si lö manga, ba böi yamuhuku zi manga; noa sa itema ia Lowalangi.[3]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 4, 'Ya''ugö andrö, ha niha ndra''ugö, wa öhuku genoni mbö''ö? Khö zokhö ya''ia, na abe''e ia, ba khö zokhö ya''ia göi, na alau. Ba sabe''e sa''ae ia; so sa wa''abölö Zo''aya, ba wangabe''e ya''ia.[4]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 5, 'So sa zamaehusi luo, ba so zanguma''ö faoma manö; böi zi lö faduhu dödö zamösana.[5]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 6, 'Ha niha zamaehusi luo, ba khö Zo''aya, wa ifaehusi, ba ha niha zi manga, ba khö Zo''aya wemangania, i''andrö sa saoha gölö khö Lowalangi; ba ha niha zi lö manga, ba khö Zo''aya, wa lö manga ia, ba i''andrö göi saoha gölö khö Lowalangi.[6]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 7, 'Lö''ö sa ba khöda sauri, ba khönia manö, ba lö si mate, ba khönia manö.[7]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 8, 'Na auri ita sa, ba khö Zo''aya wa''aurida, ba na mate ita, ba khö Zo''aya wa''amateda; tobali, he sauri ita, ba he si mate ita, ba khö Zo''aya ita.[8]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 9, 'Da''ö sa mbörö, wa mate Keriso, awö wa no ifuli auri, ena''ö ifatörö zi no mate, awö zauri.[9]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 10, 'Ba ya''ugö, hadia wa öhuku dalifusöu? Ma ya''ugö göi, hadia wa ö''ositengagö dalifusöu? Dozi ita sa, ba föna dadaoma wanguhuku andrö khö Lowalangi so ita dania.[10]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 11, 'Noa sa so ba zura: "Faya wa no sauri ndra''o, iŵa''ö So''aya, na lö dozi dania latuhi danö fönagu, ba na lö dözi bewe dania zanuno Lowalangi."[11]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 12, 'Tobali dozi ita tesekhegö dania khö Lowalangi, i''ombakha''ö hadia ia khönia zamösana.[12]', '["Faigi 15:1 b.t.","MozI 1:21; 9:3; KorI 10:25","KorI 8:8 b.t.; 10:23 b.t.; Kol 2:16","Yak 4:11,12","Faigi 14:3; Gal 4:10","Kol 3:17; TimI 4:4; MozV 1:10","KorII 5:15; Gal 2:20","Faigi 6:10,11; TesI 5:10","HalZin 10:42; Tit 2:14","Faigi 2:16; Mat 7:1 b.t.; KorII 5:10","Yes 45:23; Fil 2:10","Mat 12:36"]', NULL),
  (3422008, 'NT', 'Roma', 14, 13, 'Ba böi sa''ae tahuku nawöda; da''ö sa''ae mifaigi, fa lö te''a''asogö zi fatuwu, ba ma fangala, ba dalifusö.[13]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 14, 'u''ila ba no faduhu dödögu, ba khö Zo''aya, Yesu, ba lö hadia ia zi to''ua alakha, ha ba zanguma''ö tödönia, no alakha, hadia ia, khönia no alakha.[14]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 15, 'Ba na börö gö, wa abu dödö dalifusöu, ba tenga sa''ae fangomasi''ö awö dali khöu; böi be''e famakiko zi no mate Keriso salahi göu andrö.[15]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 16, 'Böi tetandraŵasi zi sökhi andrö khömi.', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 17, 'Banua Lowalangi andrö sa, ba tenga femanga-manga ba famadu-madu hadia ia, ha fa''atulö dödö, ba fa''ohahau dödö ba fa''omuso dödö, ba khö Geheha ni''amoni''ö.[16]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 18, 'Ha niha sa zi möi enoni Keriso ba da''ö, da''ö zomasi Lowalangi, da''ö zi faduhu dödö niha.', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 19, 'Ba datagohi zoguna, ena''ö atulö ita, ba ena''ö tedou-dou ba zi sökhi nawöda, tabe''e.[17]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 20, 'Böi be''e börö gö, wamakiko halöŵö Lowalangi. Oi si sökhi sa, ba tobali si lö sökhi, na i''a niha ba na fatuwu khönia.[18]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 21, 'Sökhi lö ta''a ndriwo ba lö tabadu nagu, ba ma hadia ia, na fatuwu khö dalifusöda.[19]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 22, 'Famati andrö, si so khöu, ba khöu da''ö, dali ndra''ugö, föna Lowalangi. Ya''ahowu zi lö manufa tödö, na si tola ba na si lö tola, hadia ia.[20]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422008, 'NT', 'Roma', 14, 23, 'Ba sanufa tödö, ba no muhuku, na i''a, me no tenga moroi ba wamati. Ba fefu hadia ia zi tenga moroi ba wamati, ba no olalöŵa.[21]', '["Mat 18:7; KorI 8:9; 10:32","Mat 15:11; Tit 1:15","Faigi 13:10; KorI 8:11–13","KorI 4:20; 8:8; Mat 6:33","Faigi 12:18; 15:2","HalZin 10:15; KorI 8:7","KorI 8:13","Yoh 1:3,21","Faigi 14:14"]', NULL),
  (3422009, 'NT', 'Roma', 15, 1, 'Ba no mo''ömö ita, ya''ita si no abe''e, wamologö tödöda ba wa lö abölö zambö fa''abölö na; ba böi ta''omasi''ö ita.[1]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 2, 'Dozi ita, ta''o''ö khö nawöda, ena''ö moguna khönia, ena''ö tedou-dou ba zi sökhi nawöda.[2]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 3, 'Si manö sa göi Keriso, lö i''omasi''ö ia, itörö sa zi so ba zura: "No göna ndra''o tahi andrö khö zanahigö ya''ugö."[3]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 4, 'Hadia ia sa nisura föna, ba ba wamahaö ya''ita tesura ia, ena''ö so khöda wanötöna andrö, moroi ba wa''ebolo dödö andrö ba moroi ba wondrara dödö andrö, nirongoda ba zura.[4]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 5, 'Ba Lowalangi wa''ebolo dödö, Lowalangi wondrara dödö, ba yamutolo ami, ena''ö ha sara dödömi, ba khö nawömi, dali Keriso Yesu;[5]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 6, 'ena''ö ha sara dödömi ba ha sara limi, wanuno Lowalangi, Ama Zo''aya ya''ita Yesu Keriso.[6]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 7, 'Andrö faoma mifonaha nawömi, si mane famonaha Keriso ya''ami, ba wamolakhömi Lowalangi.[7]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 8, 'Da''ö sa niŵa''ögu: no tobali enoni niboto Keriso, börö wa''aduhu Lowalangi, ba wanga''aro''ö amabu''ula li andrö khö ndra tua.[8]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 9, 'Ba fa''ahakhö dödö andrö mbörö, wa lafolakhömi Lowalangi niha baero, si mane si so ba zura: "Andrö usuno ndra''ugö ba niha baero, ba ube''e börö wanuno döimö."[9]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 10, 'Ba so zui, ba imane: "Mi''omusoi''ö dödömi, ya''ami, niha baero, awö mbanuania."[10]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 11, 'Ba so zui: "Misuno Zo''aya, dozi ami, motöi niha baero, ndramusuno ia fefu soi."[11]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 12, 'Ba so zui, ba imane Yesaya: So dania lewiö ba mbörö Iza''i andrö, ba si maoso dania, ba wamatörö niha baero; khönia manötöna dania niha baero.[12]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL),
  (3422009, 'NT', 'Roma', 15, 13, 'Ba Lowalangi wanötöna andrö, ba yamuhöna khömi fefu wa''omuso dödö ba fa''ohahau dödö ba wamati andrö, ena''ö a''oi so khömi wanötöna andrö, soroi ba wa''abölö Geheha ni''amoni''ö.[13]', '["Faigi 14:1 b.t.; KorI 9:22","Faigi 14:19; TesI 5:11","Yoh 8:50; Sin 69:10","Faigi 4:23,24","Faigi 12:16","HalZin 4:24","Faigi 14:1","Mat 15:24; 20:28","Sin 18:50","MozV 32:43","Sin 117:1","Yes 11:1,10; Mat 12:21","Faigi 5:1,2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3422009, 'NT', 'Roma', 15, 14, 'Ba noa göi faduhu dödögu, ya''ami ira talifusögu, ba khömi andrö, wa no fahöna khömi göi gera-era si sökhi, wa no a''oi so wa''aboto ba dödömi, awö wa tola faoma mifarou dödö nawömi.[14]', '["FetII 1:12","Faigi 11:13; 12:1; Yes 66:20","KorII 1:12–14","KorII 3:5; 4:5; Faigi 1:5","KorII 12:12; HalZin 14:3","KorII 10:15,16","Yes 52:15"]', NULL),
  (3422009, 'NT', 'Roma', 15, 15, 'Ba no lö alaŵödo ma''ifu, wanura khömi, hulö ba wamasugi ba dödömi, moroi ba wa''ebua dödö andrö, si no falukha ndra''o khö Lowalangi,', '["FetII 1:12","Faigi 11:13; 12:1; Yes 66:20","KorII 1:12–14","KorII 3:5; 4:5; Faigi 1:5","KorII 12:12; HalZin 14:3","KorII 10:15,16","Yes 52:15"]', NULL),
  (3422009, 'NT', 'Roma', 15, 16, 'ena''ö enoni Yesu Keriso ndra''o, ba niha baero, ere, ba halöŵö ni''amoni''ö andrö, fangombakha turia somuso dödö andrö, khö Lowalangi, ena''ö ni''omasi''ö zumange andrö, niha baero, ni''omasi''ö ba khö Geheha ni''amoni''ö.[15]', '["FetII 1:12","Faigi 11:13; 12:1; Yes 66:20","KorII 1:12–14","KorII 3:5; 4:5; Faigi 1:5","KorII 12:12; HalZin 14:3","KorII 10:15,16","Yes 52:15"]', NULL),
  (3422009, 'NT', 'Roma', 15, 17, 'Ba so khögu wanuno ya''o, ba khö Keriso Yesu, ba halöŵögu andrö khö Lowalangi.[16]', '["FetII 1:12","Faigi 11:13; 12:1; Yes 66:20","KorII 1:12–14","KorII 3:5; 4:5; Faigi 1:5","KorII 12:12; HalZin 14:3","KorII 10:15,16","Yes 52:15"]', NULL),
  (3422009, 'NT', 'Roma', 15, 18, 'Lö''ö sa zi lö ata''udo utunö, hadia ia, zi lö itolodo Keriso, wolau ya''ia, ba wondrönisi niha baero ba wolo''ö, he taroma li, ba he nihalö danga.[17]', '["FetII 1:12","Faigi 11:13; 12:1; Yes 66:20","KorII 1:12–14","KorII 3:5; 4:5; Faigi 1:5","KorII 12:12; HalZin 14:3","KorII 10:15,16","Yes 52:15"]', NULL),
  (3422009, 'NT', 'Roma', 15, 19, 'Ba wa''abölö dandra ba ba wa''abölö gila-ila, ba wa''abölö Geheha Lowalangi, tobali no ufalua wangombakha turia somuso dödö andrö khö Keriso, i''otarai Yeruzalema, numalö ba zi fasui, irugi Iliria,[18]', '["FetII 1:12","Faigi 11:13; 12:1; Yes 66:20","KorII 1:12–14","KorII 3:5; 4:5; Faigi 1:5","KorII 12:12; HalZin 14:3","KorII 10:15,16","Yes 52:15"]', NULL),
  (3422009, 'NT', 'Roma', 15, 20, 'Ba u''alui, ena''ö lö uturiagö ba zi no murongo döi Keriso, fa böi uhalö halöŵögu halöŵö niha bö''ö,[19]', '["FetII 1:12","Faigi 11:13; 12:1; Yes 66:20","KorII 1:12–14","KorII 3:5; 4:5; Faigi 1:5","KorII 12:12; HalZin 14:3","KorII 10:15,16","Yes 52:15"]', NULL),
  (3422009, 'NT', 'Roma', 15, 21, 'ena''ö itörö zi so ba zura: "Ba zi lö mu''ombakha''ö na hadia ia, ba khönia, da''ö zangila dania, ba ba zi lö murongo na ia, da''ö zaboto ba dödö dania."[20]', '["FetII 1:12","Faigi 11:13; 12:1; Yes 66:20","KorII 1:12–14","KorII 3:5; 4:5; Faigi 1:5","KorII 12:12; HalZin 14:3","KorII 10:15,16","Yes 52:15"]', NULL),
  (3422009, 'NT', 'Roma', 15, 22, 'Da''ö göi zasese möi börö, wa tetabi ndra''o we''amöi khömi mena''ö.[21]', '["Faigi 1:13","Faigi 1:10 b.t.","HalZin 19:21; 24:17","HalZin 11:29 b.t.","KorI 9:11","Faigi 1:11"]', NULL),
  (3422009, 'NT', 'Roma', 15, 23, 'Ba iada''e, me lö nahagu sa''ae ba danö da''e misa, ba me no humulu dödögu we''amöi khömi, ha me uga fakhe sa''ae,[22]', '["Faigi 1:13","Faigi 1:10 b.t.","HalZin 19:21; 24:17","HalZin 11:29 b.t.","KorI 9:11","Faigi 1:11"]', NULL),
  (3422009, 'NT', 'Roma', 15, 24, 'ba möido khömi, na möido ba Zifania; udöna-döna sa, u''ila ami, na utörö, ba fao ami khögu ba da''ö, na no usöndra ua wangabe''e ma''ifu, ba khömi andrö.', '["Faigi 1:13","Faigi 1:10 b.t.","HalZin 19:21; 24:17","HalZin 11:29 b.t.","KorI 9:11","Faigi 1:11"]', NULL),
  (3422009, 'NT', 'Roma', 15, 25, 'Ba iada''e, ba usaŵa Yeruzalema, möido enoni ni''amoni''ö andrö.[23]', '["Faigi 1:13","Faigi 1:10 b.t.","HalZin 19:21; 24:17","HalZin 11:29 b.t.","KorI 9:11","Faigi 1:11"]', NULL),
  (3422009, 'NT', 'Roma', 15, 26, 'Noa sa nilau dödö mbanua Makedonia ba banua Nakhaya, wanolo si numana ba ni''amoni''ö andrö ba Yeruzalema.[24]', '["Faigi 1:13","Faigi 1:10 b.t.","HalZin 19:21; 24:17","HalZin 11:29 b.t.","KorI 9:11","Faigi 1:11"]', NULL),
  (3422009, 'NT', 'Roma', 15, 27, 'Nilau dödöra sa ba ömöra khöra göi. Na no mo''urakha sa''ae niha baero ba mbalazo dödö khöra, ba ömöra göi latolo ira ba mbalazo mboto.[25]', '["Faigi 1:13","Faigi 1:10 b.t.","HalZin 19:21; 24:17","HalZin 11:29 b.t.","KorI 9:11","Faigi 1:11"]', NULL),
  (3422009, 'NT', 'Roma', 15, 28, 'Ba na no awai khögu da''ö, na no ube''e ba dangara mbuala andrö, ba utörö ami, we''amöi ba Zifania.', '["Faigi 1:13","Faigi 1:10 b.t.","HalZin 19:21; 24:17","HalZin 11:29 b.t.","KorI 9:11","Faigi 1:11"]', NULL),
  (3422009, 'NT', 'Roma', 15, 29, 'Ba no u''ila, na möido khömi, ba a''oi u''ohe howu-howu andrö, khö Keriso.[26]', '["Faigi 1:13","Faigi 1:10 b.t.","HalZin 19:21; 24:17","HalZin 11:29 b.t.","KorI 9:11","Faigi 1:11"]', NULL),
  (3422009, 'NT', 'Roma', 15, 30, 'Ba u''andrö khömi, ya''ami ira talifusö, moroi khö Zo''aya ya''ita, Yesu Keriso ba moroi ba wa''omasi Geheha andrö, mitolo ndra''o wangandrö-ngandrö khö Lowalangi, ba khögu andre,[27]', '["KorII 1:11; Efes 6:18,19","TesII 3:1,2; HalZin 21:11,27 b.t.","Faigi 1:10","Faigi 16:20; TesI 5:23; TesII 3:16"]', NULL),
  (3422009, 'NT', 'Roma', 15, 31, 'ena''ö te''efa''ö ndra''o ba danga zi lö mamati andrö, ba Yudaia, ba ena''ö omasi ni''amoni''ö wanologu Yeruzalema andrö,[28]', '["KorII 1:11; Efes 6:18,19","TesII 3:1,2; HalZin 21:11,27 b.t.","Faigi 1:10","Faigi 16:20; TesI 5:23; TesII 3:16"]', NULL),
  (3422009, 'NT', 'Roma', 15, 32, 'ena''ö omuso dödögu we''amöi khömi, na omasi Lowalangi, ba ena''ö faoma ta''okafui dödö nawöda.[29]', '["KorII 1:11; Efes 6:18,19","TesII 3:1,2; HalZin 21:11,27 b.t.","Faigi 1:10","Faigi 16:20; TesI 5:23; TesII 3:16"]', NULL),
  (3422009, 'NT', 'Roma', 15, 33, 'Ba yamutolo ami fefu Lowalangi wa''ohahau dödö andrö! Yaduhu.[30]', '["KorII 1:11; Efes 6:18,19","TesII 3:1,2; HalZin 21:11,27 b.t.","Faigi 1:10","Faigi 16:20; TesI 5:23; TesII 3:16"]', NULL),
  (3422010, 'NT', 'Roma', 16, 1, 'U''andrö khömi, ba khö Woibe andrö, talifusöda alawe, enoni ba mbanua ba Gengerea,[1]', '["TimI 5:9 b.t.; HalZin 18:18","Fil 2:29"]', NULL),
  (3422010, 'NT', 'Roma', 16, 2, 'ena''ö mitema ia, ba khö Zo''aya, si nangea ba ni''amoni''ö, ba ena''ö mitolo ia ba halöŵö fefu, ba zoguna ami khönia; ya''ia göi, ba no ato nitolonia, ba ya''odo göi, ba no itolo.[2]', '["TimI 5:9 b.t.; HalZin 18:18","Fil 2:29"]', NULL),
  (3422010, 'NT', 'Roma', 16, 3, 'Mi''owai Werikila ba Akila, awögu ba halöŵö, ba khö Keriso Yesu,[3]', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 4, 'si no mamelegö bagira ba nosogu; tenga ha ya''o zangandrö saoha gölöra, no dozi banua niha Keriso ba niha baero göi;', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 5, 'ba mi''owai mbanua niha Keriso andrö yomo khöra. Mi''owai Gefaineto andrö, somasi ndra''o, böröta mbanua Keriso ba Azia.[4]', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 6, 'Mi''owai Maria andrö, si no erege tödö khömi.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 7, 'Mi''owai Gandroniko andrö ba Yunio andrö, iwama, awögu nikuru, si no teturia, ba zinenge andrö, ba noa göi fönagu tobali niha Keriso ira.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 8, 'Mi''owai Gambeliato andrö, somasi ndra''o, ba khö Zo''aya.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 9, 'Mi''owai Guribano andrö, awöma ba halöŵö, ba khö Keriso, ba Sitakhi andrö, somasi ndra''o.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 10, 'Mi''owai Gafele andrö, si no faduhu dödöda, ba khö Keriso. Mi''owai zi so yomo khö Garisobulo andrö.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 11, 'Mi''owai Herodiano andrö, iwama. Mi''owai niha Keriso andrö, yomo khö Narikiso andrö.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 12, 'Mi''owai Derifena andrö ba Terifosa, serege tödö ba khö Zo''aya. Mi''owai Weresi andrö, ni''omasi''ö andrö, si no abölö halöŵö ba khö Zo''aya.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 13, 'Mi''owai Rufo andrö, ba khö Zo''aya, ba inania, si no tobali inagu göi.[5]', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 14, 'Mi''owai Gasikerito andrö ba Felego ba Hereme ba Fateroba ba Herema ba talifusö andrö, awöra.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 15, 'Mi''owai Wilologo andrö ba Yulia andrö ba Nereo ba talifusönia alawe andrö ba Olifa, awö ni''amoni''ö andrö fefu, awöra.', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 16, 'Faoma mi''owai nawömi fa''agosa bawa ni''amoni''ö andrö. La''owai ami banua Keriso fefu.[6]', '["HalZin 18:2","KorI 16:19","Mar 15:21","KorI 16:20; FetI 5:14"]', NULL),
  (3422010, 'NT', 'Roma', 16, 17, 'Ba u''andrö khömi, ya''ami ira talifusö, mifaigi zamobörö famabali ba fangala, si lö faudu ba wamahaö andrö, me lafahaö ami; mi''erogö ira.[7]', '["Mat 7:15 b.t.; Fil 3:2; TimI 6:3–5; Tit 3:10 b.t.","Fil 3:18,19; FetII 2:1,14 b.t.; Kol 2:4","Faigi 1:8; Mat 10:16; KorI 14:20","Faigi 15:33; MozI 3:15"]', NULL),
  (3422010, 'NT', 'Roma', 16, 18, 'Tenga sa enoni Zo''aya ya''ita, Yesu Keriso niha si manö, enoni dalura ira. Ba me no si sökhi lira, ba me lahaogö-haogö, ba lafaelungu dödö zadölö tödö.[8]', '["Mat 7:15 b.t.; Fil 3:2; TimI 6:3–5; Tit 3:10 b.t.","Fil 3:18,19; FetII 2:1,14 b.t.; Kol 2:4","Faigi 1:8; Mat 10:16; KorI 14:20","Faigi 15:33; MozI 3:15"]', NULL),
  (3422010, 'NT', 'Roma', 16, 19, 'Noa sa terongo wolo''ömi ba niha fefu, ba omuso dödögu khömi andrö, ba omasido na atua-tua ami ba zi sökhi, ba na owöhö-wöhö ami ba zi lö sökhi.[9]', '["Mat 7:15 b.t.; Fil 3:2; TimI 6:3–5; Tit 3:10 b.t.","Fil 3:18,19; FetII 2:1,14 b.t.; Kol 2:4","Faigi 1:8; Mat 10:16; KorI 14:20","Faigi 15:33; MozI 3:15"]', NULL),
  (3422010, 'NT', 'Roma', 16, 20, 'Lö ara tö, ba imama barö gahemi Zatana Lowalangi wa''ohahau dödö andrö. Yafalukha ami wa''ebua dödö Zo''aya ya''ita, Yesu Keriso![10]', '["Mat 7:15 b.t.; Fil 3:2; TimI 6:3–5; Tit 3:10 b.t.","Fil 3:18,19; FetII 2:1,14 b.t.; Kol 2:4","Faigi 1:8; Mat 10:16; KorI 14:20","Faigi 15:33; MozI 3:15"]', NULL),
  (3422010, 'NT', 'Roma', 16, 21, 'I''owai ami Timoteo andrö, awögu ba holöŵö, ba Lukio andrö ba Yaso ba Sosifatero, iwama.[11]', '["HalZin 16:1; 13:1; 17:5; 20:4","Yer 36:4","Tola tokea niha wombaso fehede andre, börö me iŵa''ö Teresio döinia, sanura zura Waulo. Eluahania tenga Faulo samösa zanura ngawalö zura nifa''ohe''önia, bahiza niha bö''ö simane Teresio andre.","KorI 1:14; TimII 4:20","KorI 16:23"]', NULL),
  (3422010, 'NT', 'Roma', 16, 22, 'U''owai ami, ya''o Teresio, sanura sura andre, ba khö Zo''aya.[12][13]', '["HalZin 16:1; 13:1; 17:5; 20:4","Yer 36:4","Tola tokea niha wombaso fehede andre, börö me iŵa''ö Teresio döinia, sanura zura Waulo. Eluahania tenga Faulo samösa zanura ngawalö zura nifa''ohe''önia, bahiza niha bö''ö simane Teresio andre.","KorI 1:14; TimII 4:20","KorI 16:23"]', NULL),
  (3422010, 'NT', 'Roma', 16, 23, 'I''owai ami Gayo, si no möi tome ndra''o; ba hulö zi no möi tome khönia mbanua ma''afefu. I''owai ami Eraso andrö, durutuli mbanua ba Kurato, talifusö andrö.[14]', '["HalZin 16:1; 13:1; 17:5; 20:4","Yer 36:4","Tola tokea niha wombaso fehede andre, börö me iŵa''ö Teresio döinia, sanura zura Waulo. Eluahania tenga Faulo samösa zanura ngawalö zura nifa''ohe''önia, bahiza niha bö''ö simane Teresio andre.","KorI 1:14; TimII 4:20","KorI 16:23"]', NULL),
  (3422010, 'NT', 'Roma', 16, 24, 'Yafalukha ami fefu wa''ebua dödö Zo''aya ya''ita, Yesu Keriso.[15]', '["HalZin 16:1; 13:1; 17:5; 20:4","Yer 36:4","Tola tokea niha wombaso fehede andre, börö me iŵa''ö Teresio döinia, sanura zura Waulo. Eluahania tenga Faulo samösa zanura ngawalö zura nifa''ohe''önia, bahiza niha bö''ö simane Teresio andre.","KorI 1:14; TimII 4:20","KorI 16:23"]', NULL),
  (3422010, 'NT', 'Roma', 16, 25, 'Ba khönia, sangila manga''aro''ö tödömi ba duria somuso dödö andrö, khögu, ba ba duria Yesu Keriso andrö, fama''ele''ö zi no tobini andrö, si lö mu''ombakha''ö, götö-götö wa''ara mege,[16]', '["TesII 3:3; Kol 1:26; FetI 1:20","Efes 3:4,5","Faigi 11:36; TimI 1:17"]', NULL),
  (3422010, 'NT', 'Roma', 16, 26, 'nifa''ele''ö iada''e, nifarongogö ba niha baero fefu, moroi ba zura wama''ele''ö andrö, me no i''oroi''ö Lowalangi si lö aetu, ba wolo''ö andrö, ba wamati,[17]', '["TesII 3:3; Kol 1:26; FetI 1:20","Efes 3:4,5","Faigi 11:36; TimI 1:17"]', NULL),
  (3422010, 'NT', 'Roma', 16, 27, 'khö Lowalangi satua-tua andrö, ha ya''ia, moroi khö Yesu Keriso, ya khönia zumange, irugi zi lö aetu! Yaduhu.[18]', '["TesII 3:3; Kol 1:26; FetI 1:20","Efes 3:4,5","Faigi 11:36; TimI 1:17"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 1, 'Faulo zanura da''e, nikaoni sinenge Keriso Yesu, moroi ba nilau dödö Lowalangi, ba Sotene, talifusö andrö,[1]', '["Kol 1:1; HalZin 18:17","HalZin 18:1 b.t.; Yoh 17:19; Rom 1:7","Efes 1:2"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 2, 'ba mbanua Lowalangi andrö ba Gorindro, nihaogö ba khö Keriso Yesu, ni''amoni''ö, nikaoni, fabaya fefu zangaröfi li töi Zo''aya ya''ita, Yesu Keriso, fefu gofu heza, he ba khöra, ba he ba khöma.[2]', '["Kol 1:1; HalZin 18:17","HalZin 18:1 b.t.; Yoh 17:19; Rom 1:7","Efes 1:2"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 3, 'Yafalukha ami wa''ebua dödö ba fa''ohahau dödö khö Namada Lowalangi, ba khö Zo''aya, Yesu Keriso.[3]', '["Kol 1:1; HalZin 18:17","HalZin 18:1 b.t.; Yoh 17:19; Rom 1:7","Efes 1:2"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 4, 'Lö mamalö-malö u''andrö saoha gölö khö Lowalangigu, ba khömi andrö, ba wa''ebua dödö Lowalangi andrö, si no falukha ami, ba khö Keriso Yesu,[4]', '["Rom 1:8-9","Kol 1:9–10"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 5, 'me no fahöna khömi fefu hadia ia, ba khönia andrö, he ba ngawalö huhuo, ba he ba ngawalö wa''aboto ba dödö fefu,[5]', '["Rom 1:8-9","Kol 1:9–10"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 6, 'wa no mu''a''aro''ö ba dödömi wamaduhu''ö Keriso andrö.', '["Rom 1:8-9","Kol 1:9–10"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 7, 'Tobali lö ambö ami buala fa''ebua dödö andrö fefu, hadia ia, ba sombalo-mbaloi fa''ato''ele Zo''aya ya''ita, Yesu Keriso, ami,[6]', '["Tit 2:13","Fil 1:6, 10:1; TesI 5:23–24"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 8, 'sangabe''e''ö göi ya''ami, irugi gamozua, fa lö sinegu, na baŵa Zo''aya ya''ita, Yesu Keriso.[7]', '["Tit 2:13","Fil 1:6, 10:1; TesI 5:23–24"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 9, 'Lö faröi Lowalangi, si no mamakaoni''ö ya''ami ba wefao khö Nononia Yesu Keriso, So''aya ya''ita,[8]', '["Faigi I 10:13; TimII 1:9; Yoh 6:44"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 10, 'Ba u''andrö khömi, ya''ami ira talifusö, moroi ba döi Zo''aya ya''ita andrö, Yesu Keriso, ena''ö ha sara limi fefu, ba ena''ö lö falukha ba khömi fabali dödö; mi''atulö''ö, mi''osara''ö gera-erami ba tödömi.[9]', '["Faigi 11:18; Rom 15:5; Fil 2:1–2"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 11, 'Noa sa mu''ombakha''ö khögu, ba khömi andrö, ya''ami ira talifusögu, si so yomo khö Kheloe andrö zangombakha, no so wagua-gusa ba khömi.[10]', '["Faigi 3:3 b.t."]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 12, 'Da''ö niŵa''ögu, me iŵa''ö si samösa ba khömi: Khö Waulo ndra''o, ba si samösa, ba: Khö Afolo ndra''o, ba si samösa, ba: Khö Gefa ndra''o, ba si samösa, ba: Khö Keriso ndra''o.[11]', '["HalZin 18:24; Yoh 1:43"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 13, 'Hadia, no fabali Keriso? Hadia, Faulo niforöfa salahimi? ba ma ba döi Waulo tebayagö idanö ami mege?', '["HalZin 18:24; Yoh 1:43"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 14, 'Usuno Lowalangi, me samösa lö nibayagögu idanö ba khömi, baero Gerifo ba Gayo andrö,[12]', '["HalZin 18:8; Rom 16:23"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 15, 'fa böi laŵa''ö, no ba döigu ubayagö idanö niha.', '["HalZin 18:8; Rom 16:23"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 16, 'Ba noa sa göi ubayagö idanö zi samba omo ndra Sefana, baero ö, ba lö u''ila, na so niha bö''ö nibayagögu idanö.[13]', '["Faigi 16:15–17"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 17, 'Tenga sa ba wamayagö idanö ifatenge ndra''o Keriso, no ba wangombakha turia somuso dödö ifatenge ndra''o, tenga fa''onekhe ba huhuo, fa böi tobali faya röfa Keriso andrö.[14]', '["Faigi 2:1 b.t.","Faigi 1:23–24; Rom 1–16"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 19, 'Noa sa so ba zura: "Ufakiko dania wa''atua-tua zatua-tua andrö ba fa''aboto ba dödö ba zaboto ba dödö andrö, ba utayaigö."[16]', '["Yes 29:14; Yob 5:12","Faigi 3:19; Yes 19:12"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 20, 'Hezo zatua-tua? hezo zonekhe ba wasosota andrö, ba götö danö andre. Hadia, tenga no ibali''ö faya wa''atua-tua ba guli danö andre Lowalangi?[17]', '["Yes 29:14; Yob 5:12","Faigi 3:19; Yes 19:12"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 21, 'Me no lö''ö sa aboto ba dödö niha guli danö Lowalangi, ba wa''atua-tuania andrö, ba wa''atua-tuara, ba no omasi Lowalangi i''orifi zamati andrö, faya andrö, fangombakha.[18]', '["Mat 11:25"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 22, 'La''andrö sa dandra niha Yehuda ba la''alui wa''atua-tua Dawa Heleni,[19]', '["Mat 12:38; HalZin 17:18–32","Faigi 2:2–14; Rom 9:32 b.t.","Faigi 1:18; 2:5; Kol 2:3"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 23, 'ba ya''aga, ba maturiagö Keriso, niforöfa andrö, si fatuwu ba niha Yehuda, ba si no faya ba dödö niha baero,[20]', '["Mat 12:38; HalZin 17:18–32","Faigi 2:2–14; Rom 9:32 b.t.","Faigi 1:18; 2:5; Kol 2:3"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 24, 'ba ba nikaoni andrö, he niha Yehuda, ba he Dawa Heleni, ba no Keriso, fa''abölö Lowalangi ba fa''atua-tua Lowalangi ia.[21]', '["Mat 12:38; HalZin 17:18–32","Faigi 2:2–14; Rom 9:32 b.t.","Faigi 1:18; 2:5; Kol 2:3"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 25, 'Faya-faya andrö sa, soroi Lowalangi, ba no atua-tua moroi ba niha, ba si lö abölö andrö, soroi Lowalangi, ba no abölö moroi ba niha.', '["Mat 12:38; HalZin 17:18–32","Faigi 2:2–14; Rom 9:32 b.t.","Faigi 1:18; 2:5; Kol 2:3"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 26, 'Mifaigi sa''ae wogaoni ya''ami andrö, ya''ami ira talifusö, lö ato zatua-tua, na dali wa''atua-tua niha, lö ato zabölö, lö ato zalaŵa.[22]', '["Yoh 7:48–49"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 27, 'Hadia ia zi no faya-faya, wamaigi niha guli danö, da''ö nitutuyu Lowalangi, ena''ö i''ailasi zatua-tua andrö, ba hadia zi lö abölö, wamaigi niha guli danö, da''ö nitutuyu Lowalangi, ena''ö i''ailasi zabölö andrö.[23]', '["Yak 2:1–5","Gal 6:3","Efes 2:6; Yes 40:6"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 28, 'Ba ha niha zi tenga salaŵa, wamaigi niha guli danö, ba hadia ni''ositengagö, da''ö nitutuyu Lowalangi, hadia zi lö''ö andrö, ena''ö lö moguna zi so, ibe''e,[24]', '["Yak 2:1–5","Gal 6:3","Efes 2:6; Yes 40:6"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 29, 'ena''ö lö isuno ia niha, ha niha ia, föna Lowalangi.[25]', '["Yak 2:1–5","Gal 6:3","Efes 2:6; Yes 40:6"]', NULL),
  (3391748, 'NT', 'Korindro I', 1, 31, 'ena''ö itörö zi so ba zura: "Na so zanuno ya''ia, ba ba khö Zo''aya yamusuno ia".[27]', '["Faigi 1:24; Yer 23:6; KorII 5:21; Heb 2:11; Rom 3:24; Efes 1:7","Yer 9:23–24; KorII 10:17"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 1, 'Ba ya''odo göi, me möido khömi, ya''ami ira talifusö, ba tenga fa''abölö ba huhuo ni''ohegu, ba tenga fa''abölö wa''atua-tua, wanuriagö khömi famaduhu''ö Lowalangi andrö.[1]', '["Faigi 1:17; YohI 5:9","Faigi 15:3; Gal 6:14"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 2, 'Lö''ö sa niŵa''ögu tödögu, so hadia ia ni''ilagu ba khömi andrö, baero Yesu Keriso, niforöfa andrö,[2]', '["Faigi 1:17; YohI 5:9","Faigi 15:3; Gal 6:14"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 3, 'Ba ya''o, ba si lö abölö ba sata''u ba salaŵö-laŵö sibai, ba khömi andrö.[3]', '["HalZin 18:9; KorII 10:10; 11:30","TesI 1:5","Faigi 1:18–24"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 4, 'Ba fehedegu ba fangombakha''ögu, ba tenga huhuo zatua-tua, si faduhu dödö niha, ha fangoroma''ö Eheha ba fa''abölö,[4],', '["HalZin 18:9; KorII 10:10; 11:30","TesI 1:5","Faigi 1:18–24"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 5, 'fa böi fa''atua-tua niha dandrösa wamatimi, ena''ö fa''abölö Lowalangi dandrösania.[5]', '["HalZin 18:9; KorII 10:10; 11:30","TesI 1:5","Faigi 1:18–24"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 6, 'Fa''atua-tua sa wehedema ba zi no mo''ahonoa, ba tenga fa''atua-tua niha guli danö andre, tenga göi fa''atua-tua zalaŵa ba guli danö andre, si tetibo dania.', '["HalZin 18:9; KorII 10:10; 11:30","TesI 1:5","Faigi 1:18–24"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 7, 'Fa''atua-tua Lowalangi wehedema, si no tobini, si no tobalu, nihonogöi Lowalangi, götö-götö wa''ara sa''ae, ba wamolakhömi ya''ita.[6]', '["Sin 51:8; Efes 3:8–9","HalZin 13:27; 3:17"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 8, 'Si lö irai aboto ba dödö zalaŵa ba guli danö andre, ha niha ia göi: na no aboto ba dödöra sa, ba lö laforöfa mena''ö zalaŵa lakhömi andrö;[7]', '["Sin 51:8; Efes 3:8–9","HalZin 13:27; 3:17"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 9, 'Si mane si so ba zura sa: Si lö irai i''ila hörö niha, si lö irai irongo tögi dalinga niha, si lö irai möi ba dödö niha, ni''asiwai Lowalangi ba zangomasi''ö ya''ia.[8]', '["Yes 64:4","Yoh 16:13; Dan 2:23"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 10, 'Ba khöda no ifa''ele''ö Lowalangi, balazi Gehehania; fefu hadia ia sa, ba i''alu-alui Eheha, irege wa''abakha Lowalangi andrö.[9]', '["Yes 64:4","Yoh 16:13; Dan 2:23"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 11, 'Ha niha sa zangila hadia ba dödö niha, baero geheha niha andrö, si so ba dödönia? Si manö göi wa lö saboto ba dödö hadia zi so ba dödö Lowalangi, baero Geheha Lowalangi andrö.', '[]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 12, 'Ba ya''ita, ba tenga eheha ba guli danö andre nitemada, no Eheha si otarai Lowalangi nitemada, ena''ö ta''ila, hadia nibe''e Lowalangi bualania khöda.[10]', '["Rom 8:15; FetII 1:3"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 13, 'Ba da''ö göi wehedema, tenga taroma li nisöndra ba niha, fa''atua-tua niha; no taroma li nisöndra khö Geheha, soroi ba Geheha tefaedogö ba zoroi ba Geheha.[11]', '["Faigi 2:1–4; FetII 1:21","Faigi 1:23; Mat 16:17; Yud 19; Yoh 14:17"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 14, 'Na to''ua tödö niha, ba lö i''o''ö hadia zi otarai khö Geheha Lowalangi, noa sa faya-faya khönia, ba tebai aboto ba dödö, me moroi ba Geheha ena''ö wangalui eluahania.[12]', '["Faigi 2:1–4; FetII 1:21","Faigi 1:23; Mat 16:17; Yud 19; Yoh 14:17"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 15, 'Ba si so Eheha, ba isöndra geluaha hadia ia fefu, ba ya''ia, ba si lö aboto ba dödö niha bö''ö.[13]', '["YohI 2:20","Yes 40:13; Yer 23:18"]', NULL),
  (3391749, 'NT', 'Korindro I', 2, 16, 'Ha niha sa, zi no aboto ba dödö era-era Zo''aya, ha niha zamahaö ya''ia? Ba ya''ita, ba no era-era Keriso gera-erada.[14]', '["YohI 2:20","Yes 40:13; Yer 23:18"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 1, 'Ba ya''o, ba tebai fahuhuodo khömi si mane ba zi so Eheha, ya''ami ira talifusö, si mane ba zi ha zambalö ösi niha huhuogu khömi, si mane ba ndraono sawuyu, ba khö Keriso.[1]', '["Faigi 2:15; Yoh 16:12","Heb 5:12 b.t.; FetI 2:2","Faigi 1:10,11; Gal 5:19–20; Yak 3:14–16;","Faigi 1:12"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 2, 'Susu nifabadugögu khömi, tenga ö sabe''e; me tebai mitaha na, ba iada''e göi, ba tebai zui mitaha;[2]', '["Faigi 2:15; Yoh 16:12","Heb 5:12 b.t.; FetI 2:2","Faigi 1:10,11; Gal 5:19–20; Yak 3:14–16;","Faigi 1:12"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 3, 'solo''ö ösi niha na sa ami. Na so na wa''afökhö dödö ba fagua-guasa ba khömi, ba tenga solo''ö ösi niha ami, ba tenga huku ba niha dali mbua-buami?[3]', '["Faigi 2:15; Yoh 16:12","Heb 5:12 b.t.; FetI 2:2","Faigi 1:10,11; Gal 5:19–20; Yak 3:14–16;","Faigi 1:12"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 4, 'Na iŵa''ö si samösa: Khö Waulo ndra''odo, ba si samösa, ba: Khö Afolo ndra''odo, ba tenga huku ba niha mi''o''ö?[4]', '["Faigi 2:15; Yoh 16:12","Heb 5:12 b.t.; FetI 2:2","Faigi 1:10,11; Gal 5:19–20; Yak 3:14–16;","Faigi 1:12"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 5, 'Hadia sa Afolo andrö? Ba hadia Waulo andrö? Enoni ira, si no mama''ema famati andrö khömi, balazi nitema zamösana khö Zo''aya.[5]', '["Faigi 4:1","Faigi 12:11; HalZin 18:27; 19:1","Faigi 4:5; Sin 62:13"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 6, 'Ya''o zananö, Afolo zombuwui, ba Lowalangi zamanöi.[6]', '["Faigi 4:1","Faigi 12:11; HalZin 18:27; 19:1","Faigi 4:5; Sin 62:13"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 7, 'Tobali faya zananö, ba faya zombuwui, ha Lowalangi, samanöi, zi ndruhu.', '["Faigi 4:1","Faigi 12:11; HalZin 18:27; 19:1","Faigi 4:5; Sin 62:13"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 8, 'Ba sananö ba sombuwui, ba ha sambua, ba itema sa luonia zamösana, balazi halöŵönia.[7]', '["Faigi 4:1","Faigi 12:11; HalZin 18:27; 19:1","Faigi 4:5; Sin 62:13"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391750, 'NT', 'Korindro I', 3, 9, 'Sanolo sa ndra''aga, ba halöŵö, khö Lowalangi; nowi Lowalangi ami, tomosa khö Lowalangi.[8]', '["KorII 6:1–16; Mat 25:14","Faigi 15:10; Rom 15:20","Faigi 16:22; FetI 2:4–6"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 10, 'No ufotoyo, si mane sotomo, si no atua-tua, dali wa''ebua dödö Lowalangi andrö, si no falukha ndra''o; tanö bö''ö zamedadao. Ba yamufaigi zamösana, he wisa wotomonia.[9]', '["KorII 6:1–16; Mat 25:14","Faigi 15:10; Rom 15:20","Faigi 16:22; FetI 2:4–6"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 11, 'Toyo bö''ö ba lö''ö sa i''ila ibe''e tou niha, ha niha ia göi, baero zi no mube''e, Yesu Keriso andrö.[10]', '["KorII 6:1–16; Mat 25:14","Faigi 15:10; Rom 15:20","Faigi 16:22; FetI 2:4–6"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 12, 'Ba na so zangotomosi ba dete doyo andrö, ma balaki, ba ma firö, ba ma mani-mani, ba ma eu, ba ma du''u soköli, ba ma töla wakhe,', '["Yud 23"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 13, 'ba oroma dania halöŵö zamösana, i''oroma''ö sa dania baŵa andrö, me ba galitö tefa''ele''ö dania, ba he wisa halöŵö zamösana, ba alitö wanandraigö.', '["Yud 23"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 14, 'Na manaha nifazökhinia, ni''otomosinia, ba itema luo.', '["Yud 23"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 15, 'Ba na akhozi nifazökhinia, ba te''ala ia, ba ya''ia, ba ni''orifi, ba hulö nifatörö ba galitö.[11]', '["Yud 23"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 16, 'Hadia, lö mi''ila, wa no osali Lowalangi ami, awö wa no nahia Geheha Lowalangi dödömi?[12]', '["Faigi 6:19; Rom 8:9"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 17, 'Na so zamakiko osali Lowalangi andrö, ba nifakiko Lowalangi dania da''ö: ni''amoni''ö sa gosali Lowalangi andrö, ba ya''ami da''ö.', '["Faigi 6:19; Rom 8:9"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 18, 'Böi yamufaelungu ia niha. Na so ba khömi, ba guli danö andre, zanguma''ö tödönia, satua-tua ia, ba yatobali sambö era-era, ena''ö tobali satua-tua ia.[13]', '["Amaed 3:5–7; Rom 12:16; Faigi 4:10","Faigi 1:20; Rom 1:22; Yob 5:13","Sin 94:11"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 19, 'Fa''atua-tua niha guli danö andre sa, ba no fa''ambö era-era ba khö Lowalangi. Si mane sa ba zura: "Sondra''u satua-tua andrö, ba wa''onekhera."[14]', '["Amaed 3:5–7; Rom 12:16; Faigi 4:10","Faigi 1:20; Rom 1:22; Yob 5:13","Sin 94:11"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 20, 'Ba so zui, ba: "I''ila So''aya gera-era zatua-tua andrö, wa faya."[15]', '["Amaed 3:5–7; Rom 12:16; Faigi 4:10","Faigi 1:20; Rom 1:22; Yob 5:13","Sin 94:11"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 21, 'Andrö böi yamusuno ia niha, ha niha ia; a''oi sa khömi manö,[16]', '["Faigi 1:31; Yer 17:5","Faigi 3:4; Rom 8:28; 38:39"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 22, 'he Faulo ba he Afolo ba he Kefa ba he uli danö ba he fa''auri ba he fa''amate ba he götö da''e ba he götö dania, oi khömi manö,[17]', '["Faigi 1:31; Yer 17:5","Faigi 3:4; Rom 8:28; 38:39"]', NULL),
  (3391750, 'NT', 'Korindro I', 3, 23, 'ba ya''ami, ba khö Keriso, ba Keriso, ba khö Lowalangi.', '["Faigi 1:31; Yer 17:5","Faigi 3:4; Rom 8:28; 38:39"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 1, 'Da''ö ndramuŵa''ö tödöra, dozi, ba khöma andre, enoni Keriso ndra''aga, samatörö si tobini andrö, khö Lowalangi.[1]', '["Faigi 3:5; KorII 4:5; Kol 1:25–26","Luk 12:42; FetI 4:10","KorII 1:12; 5:10–11; Sin 19:13; 143:2"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 2, 'Ba ba zamatörö andrö, ba da''ö sa nifaigi ba khöra, ena''ö lö falimo zamösana.[2]', '["Faigi 3:5; KorII 4:5; Kol 1:25–26","Luk 12:42; FetI 4:10","KorII 1:12; 5:10–11; Sin 19:13; 143:2"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 3, 'Lö''ö sa ba dödögu, na tehuku ndra''o khömi, ba ma ba rafe niha bö''ö, lö''ö sa göi uhuku ndra''odo.', '["Faigi 3:5; KorII 4:5; Kol 1:25–26","Luk 12:42; FetI 4:10","KorII 1:12; 5:10–11; Sin 19:13; 143:2"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 4, 'Ba he sa lö ni''ilagu hadia ia, ba tenga na sa börö da''ö, wa laŵa''ö ena''ö satulö ndra''o. Ba So''aya zanguhuku ya''o.[3]', '["Faigi 3:5; KorII 4:5; Kol 1:25–26","Luk 12:42; FetI 4:10","KorII 1:12; 5:10–11; Sin 19:13; 143:2"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 5, 'Andrö böi mi''etu''ö huku, hadia ia, na tenga inötö na, irege so Zo''aya, sohagaini göi si no tobini ba zogömi-gömi, sama''ele''ö söndra dödö andrö, ba awena dania tesuno zamösana khö Lowalangi.[4]', '["Rom 2:16; Sangomb 12:14; KorII 10:18"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 6, 'Khögu ba khö Afolo no uböbögö da''ö, ya''ami ira talifusö, börö ami, ena''ö mitöngöni khöma, fa böi fayaŵa ami, fa böi italu''i zi so ba zura, fa lö ifahokha zamösana, ba wangebua''ö ba zi samösa ba ba wangambözi zi samösa.[5]', '["Rom 12:3"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 7, 'Ha niha sa zamaehusi ya''ugö? Hadia khöu, si lö mube''e khöu? Ba na nibe''e khöu, ba hadia wa ösuno ndra''ugö, hulö tenga nibe''e khöu?[6]', '["Yak 1:17","Fam 3:17"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 8, 'No abuso ami, no fahöna khömi, no samatörö ami, ba zi lö ya''aga! Ena''ö na duhu wa no samatörö ami, fa samatörö göi ndra''aga, awömi![7]', '["Yak 1:17","Fam 3:17"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 9, 'Ba dödögu sa, ba no oroma wa no fondrege zide-ide ndra''aga, ya''aga sinenge, ibe''e Lowalangi, hulö zi no mu''etu''ö huku famunu, me no tobali mai-mai ndra''aga ba nösi guli danö, ba mala''ika ba ba niha.[8]', '["KorII 4:11; Heb 10:32–33","Faigi 1:18 b.t.; 3:18"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 10, 'Sambö tödö ndra''aga, börö Keriso, ba ya''ami, ba no satua-tua, ba khö Keriso; si lö abölö ndra''aga, ba ya''ami, ba sabölö; nifosumange ami, ba ni''ositengagö ndra''aga.[9]', '["KorII 4:11; Heb 10:32–33","Faigi 1:18 b.t.; 3:18"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 11, 'Irugi ma''ökhö andre, ba solofo ndra''aga ba sowökhi tödö, no sambö nukha, ba no nibözi-bözi ndra''aga, ba lö nahama, sahono ndra''aga,[10]', '["KorII 11:23–27","Faigi 9:15; HalZin 18:3; Rom 12:14; Mat 5:44","HalZin 22:22"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 12, 'ba ma''eregeisi dödöma, mohalö-halöŵö dangama; latandraŵaisi ndra''aga, ba mafahowu''ö ira, lagohi ndra''aga, ba mataha dödöma;[11]', '["KorII 11:23–27","Faigi 9:15; HalZin 18:3; Rom 12:14; Mat 5:44","HalZin 22:22"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 13, 'laböbögö khöma zi lö sökhi, ba mangandrö ndra''aga; no tobali hulö zasao ba guli danö ndra''aga, hulö ndra''i, ba niha fefu, irugi da''e.[12]', '["KorII 11:23–27","Faigi 9:15; HalZin 18:3; Rom 12:14; Mat 5:44","HalZin 22:22"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 14, 'Tenga ba wangailasi ya''ami usura da''ö, ha ba wamarou tödömi, si mane iraonogu, somasi ndra''o.[13]', '["TesI 2:11 b.t.","Gal 4:19; Filem 10","Faigi 11:1"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 15, 'He sa fulu ngahönö khömi mandru, ba khö Keriso, ba lö ato nama khömi. Ba khö Keriso Yesu sa no mo''onodo ya''ami, moroi ba duria somuso dödö andrö.[14]', '["TesI 2:11 b.t.","Gal 4:19; Filem 10","Faigi 11:1"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 16, 'Andrö u''andrö khömi, mihalö famaedo khömi ndra''odo.[15]', '["TesI 2:11 b.t.","Gal 4:19; Filem 10","Faigi 11:1"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 17, 'Da''ö mbörö, wa no ufatenge khömi Dimoteo andrö, onogu andrö, ba khö Zo''aya, somasi ndra''o, si lö faröi, da''ö dania zamasugi ba dödömi lala andrö khögu, ba khö Keriso Yesu, si mane famahaögu fefu gofu heza, ba mbanua fefu.[16]', '["Faigi 16:10; TimI 1:2; TimII 1:5"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 18, 'Ba no mohokha ösa, hulö na lö möido khömi.', '["Faigi 16:5–6; Yak 4:15","Faigi 2:4; Luk 17:21","KorII 13:10"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 19, 'Ba lö ara tö, ba möido khömi, na itolo Lowalangi, ba tenga li zohokha andrö dania usofu, ha fa''abölöra.[17]', '["Faigi 16:5–6; Yak 4:15","Faigi 2:4; Luk 17:21","KorII 13:10"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 20, 'Tenga sa li daya-daya mbanua Lowalangi andrö, no fa''abölö daya-dayania.[18]', '["Faigi 16:5–6; Yak 4:15","Faigi 2:4; Luk 17:21","KorII 13:10"]', NULL),
  (3391751, 'NT', 'Korindro I', 4, 21, 'Hadia zomasi ami, hadia, ue u''ohe, na möido khömi, ba ma fa''omasi ba Eheha wa''ebolo dödö andrö?[19]', '["Faigi 16:5–6; Yak 4:15","Faigi 2:4; Luk 17:21","KorII 13:10"]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 1, 'Fohorö ba khömi zabölö teturia, ba fohorö si lö''ö na i murongo ba niha baero, wa ihalö ndronga namania niha.[1]', '["Faigi 6:15 b.t.; TesI 4:3–5; MozIII 18:7–8","Faigi 4:6 b.t."]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 2, 'Ba sohokha ami, ba lö''ö sa abu dödömi, fa tetibo ena''ö banuami zolau da''ö.[2]', '["Faigi 6:15 b.t.; TesI 4:3–5; MozIII 18:7–8","Faigi 4:6 b.t."]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 3, 'Ba ya''odo andre, ba si ndruhu sa, lö ya''o, botogu andre, ba sodo sa tödögu, noa sa uhuku, hulö na no so ndra''o, ba zamazökhi da''ö, si manö,[3]', '["Kol 2:5","Mat 16:19; 18:18–20","TimI 1:20; KorII 2:6 b.t."]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 4, 'na no falukha ita ba döi Zo''aya ya''ita, Yesu, ya''ami ba tödögu andre, ba na fao wa''abölö Zo''aya yaita, Yesu;[4]', '["Kol 2:5","Mat 16:19; 18:18–20","TimI 1:20; KorII 2:6 b.t."]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 5, 'ba nibe''e ba danga Zatana zi manö, ba wamakiko ösinia, ena''ö auri mbekhu, na baŵa Zo''aya ya''ita Yesu.[5]', '["Kol 2:5","Mat 16:19; 18:18–20","TimI 1:20; KorII 2:6 b.t."]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 6, 'Tenga si sökhi duriami andrö. Hadia, lö mi''ila, wa aisö nifaruka ma''afefu ibe''e tanömö roti si ha ma''ifu?[6]', '["Gal 5:9","MozII 12:15–19; FetI 1:18–19"]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 7, 'Mitibo''ö danömö si no ara andrö, ena''ö si bohou mufaruka ami; noa sa si lö mu''aisöni ami, noa sa mutaba wasa khöda göi, Keriso.[7]', '["Gal 5:9","MozII 12:15–19; FetI 1:18–19"]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 8, 'Ba datalau gowasa fasa, böi fao danömö roti si no ara, ba böi göi fao danömö roti andrö, falösökhi ba fa''asilöyaŵa, ha si lö mu''aisöni andrö, fa''adölö dödö ba fa''aduhu, nifao.', '[]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 9, 'No usura khömi ba zura no andrö, böi fabaya ami ba zohorö.', '["YohI 5:19"]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 10, 'Tenga sohorö manö, ba niha guli danö, niŵa''ögu, ba somasi ana''a ba sorabu ba samosumange adu, na si manö ena''ö, ba lö tola lö miheta manö sa''ae ami ba guli danö andre ena''ö.[8]', '["YohI 5:19"]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 11, 'Ba no usura khömi, böi fabaya ami, na so zanguma''ö, talifusö ia, ba na sohorö ia, ba ma somasi ana''a, ba ma samosumange adu, ba ma sanandraŵaisi awönia, ba ma si mabu-mabu, ba ma sorabu; na so zi manö, ba böi na i orudu manga ami khönia.[9]', '["Faigi 6:9–10; Mat 18:17"]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 12, 'Hadia sa wa uhalö khögu wanguhuku si so baero andrö? Hadia, tenga ya''ami zanguhuku si te''u''u khömi?[10]', '["Kol 4:5","TesII 3:6"]', NULL),
  (3391752, 'NT', 'Korindro I', 5, 13, 'Lowalangi dania zanguhuku si so baero andrö. Mibe''e baero zi lö sökhi, miheta ba khömi.[11]', '["Kol 4:5","TesII 3:6"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 1, 'Hadia, so ba khömi zi lö ata''u, na so hadia ia nifadöninia khö naŵönia, ifahuku''ö ba niha si lö atulö, ba tenga ba ni''amoni''ö?[1]', '["Mat 5:40","Dan 7:22; Mat 19:28","FetII 2:4"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 2, 'Ma lö mi''ila, wa sangohuku niha guli danö dania ni''amoni''ö andrö? Ba na sanguhuku niha guli danö ami, ba hadia, lö tola mihuku ngawalö hadia ia, zide-ide sibai?[2]', '["Mat 5:40","Dan 7:22; Mat 19:28","FetII 2:4"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 3, 'Hadia, lö mi''ila, wa sanguhuku mala''ika dania ita? ba tenga mendrua manö tola ba mbalazo?[3]', '["Mat 5:40","Dan 7:22; Mat 19:28","FetII 2:4"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 4, 'Ba na so nifadöni balazo, ba hadia, mifataro sanguhuku ni''ositengagö mbanua niha Keriso?', '["Mat 5:40","Dan 7:22; Mat 19:28","FetII 2:4"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 5, 'Ba wangailasi ya''ami uŵa''ö da''ö; Hadia: tobali samösa lö satua-tua ba khömi, sangila manguhuku hadia ia ba zi fatalifusö?', '[]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 6, 'Hadia, i''adugö dalifusönia sotalifusö, ba ba zi tenga samati na i?', '[]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 7, 'Noa sa''ae sala sibai ami, me so wamadönimi khö nawömi. Hana wa lö mitaha manö dödömi, na lafatörö khömi zi lö atulö? Hana wa lö mitaha, na la''alani ami?[4]', '["Mat 5:39 b.t.","TesI 4:6"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 8, 'Ba ya''ami zamatörö si lö atulö, ba mi''alani nawömi, ba talifusö na i.[5]', '["Mat 5:39 b.t.","TesI 4:6"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 9, 'Ma lö mi''ila, wa tebai tefa''amöi ba mbanua Lowalangi zi lö atulö? Böi elungu ami, he sohorö, ba he samosumange adu, ba he sohoröni donga zodonga, ba he sombuyutö, ba he sohoröni ira matua,[6]', '["Ga 5:19 b.t.; Efes 5:5; Fam 21:8; 22:15"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 10, 'ba he sanagö, ba he somasi ana''a, ba he si mabu-mabu, ba he sanandraŵaisi awönia, ba he sorabu, ba tebai tefa''amöi ba mbanua Lowalangi andrö.', '["Ga 5:19 b.t.; Efes 5:5; Fam 21:8; 22:15"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 11, 'Ba no si manö ösa ami föna. Ba no musasai ami, no mu''ohau-hau''ö, no atulö ami, iŵa''ö Lowalangi, moroi ba döi Yesu Keriso, So''aya, ba moroi ba Geheha Lowalangida andrö.[7]', '["Tit 3:3 b.t.; FetI 4:3 b.t.; HalZin 22:16; Fam 1:5; 7:14"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 12, 'Fefu hadia ia, ba tola ulau, ba so zi lö guna. Fefu hadia ia, ba tola ulau, ba lö utehe i''osawuyu ndra''o hadia ia.[8]', '["Faigi 10:23","Mat 15:17; TesI 4:3–5"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 13, 'Ö andrö, ba ba mbetu''a nahania, ba betu''a andrö, ba no naha gö. Ba faoma iheta dania Lowalangi. Ba boto, ba böi ba wohorö, no khö Zo''aya, ba So''aya, ba ba mboto.[9]', '["Faigi 10:23","Mat 15:17; TesI 4:3–5"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 14, 'Ba no isusugi Zo''aya Lowalangi, ba isusugi göi ita dania fa''abölönia andrö.[10]', '["Faigi 15:15–20 b.t.; TesI 4:14; Rom 8:11"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 15, 'Hadia, lö mi''ila, wa no ndroto-ndroto Keriso mbotomi andrö? Ba hadia, uhalö ndroto-ndroto Keriso, ba ube''e ndroto-ndroto zohorö? Böi si manö.[11]', '["Faigi 12:27","MozI 2:24"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 16, 'Ma lö mi''ila, wa ha sambua boto ira, na so zorudu ba zohorö ira alawe? noa sa muŵa''ö, "ha sambua ösi zi darua andrö."[12]', '["Faigi 12:27","MozI 2:24"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 17, 'Ba na so zi olembai So''aya, ba ha sambua Eheha ira.[13]', '["Yoh 17:21–22"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 19, 'Ma lö mi''ila, wa no osali Geheha ni''amoni''ö andrö, si so ba dödömi, nibe''e Lowalangi khömi, mbotomi andrö, awö wa tenga khömi ami?[15]', '["Faigi 10:8; KorII 7:1","Faigi 3:16 b.t.","Faigi 7:23; FetI 1:18–19"]', NULL),
  (3391753, 'NT', 'Korindro I', 6, 20, 'Noa sa ebua mege hölimi; ba mifosumange Lowalangi ba mbotomi andrö.[16]', '["Faigi 10:8; KorII 7:1","Faigi 3:16 b.t.","Faigi 7:23; FetI 1:18–19"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 1, 'Ba ba nisurami andrö khögu, ba sökhi ba niha, na lö ibabaya ndra alawe.[1]', '["Faigi 7:25–26; Mat 19:10 b.t."]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 2, 'Ba ba wohorö andrö, ba yamodonga zamösana, ndra matua, ba si manö göi ndra alawe.', '["Faigi 7:25–26; Mat 19:10 b.t."]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 3, 'Yamutörö gömönia ba ndra alawe ira matua, ba ya si manö göi ndra alawe ba ndra matua.', '["Faigi 7:25–26; Mat 19:10 b.t."]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 4, 'Tenga samatörö botonia ndra alawe, ira matua zamatörö, ba si manö göi ndra matua, tenga ya''ia zamatörö botonia, ira alawe zamatörö.', '["Faigi 7:25–26; Mat 19:10 b.t."]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 5, 'Böi mifabali ami khö nawömi, ato na lö ara, na ha sara limi, fa lö mangoloi dödömi, ba wangandrö, ba mifuli zui orudu, fa lö itandraigö ami Satana, na tebai mitaha dödömi.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 6, 'Fa utehe khömi, uŵa''ö da''ö, tenga oroisa.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 7, 'Omasido sa ena''ö, na si mane ya''o fefu niha; ba no faehu nitema zamösana, khö Lowalangi, bö''ö ba zi samösa, ba bö''ö ba zi samösa.[2]', '["Mat 19:11–12","Faigi 9:5","TimI 5:14"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 8, 'Ba da''ö niŵa''ögu ba zi lö donga ba ba lakha mbanua: sökhi khöra, na lö tebulö si mane ya''o ira göi.[3]', '["Mat 19:11–12","Faigi 9:5","TimI 5:14"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 9, 'Ba na tebai lataha, ba ndramangowalu ba ndramöi nihalö; sökhi sa mangowalu, moroi aukhu ira.[4]', '["Mat 19:11–12","Faigi 9:5","TimI 5:14"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 10, 'Ba da''ö goroisagu ba zi so donga; tenga na i ya''o zangoroi''ö, So''aya zangoroi''ö: böi fabali ndra alawe ba ndra matua.[5]', '["Mar 10:9–12; Mal 2:14 b.t.","Mal 5:32"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 11, 'Ba na so zi no fabali, ba böi yamöi nihalö sa''ae, ato na ifuli i''atulö''ö ia ba ndra matua; ba ira matua göi, ba böi yamutibo''ö ndra alawe.[6]', '["Mar 10:9–12; Mal 2:14 b.t.","Mal 5:32"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 12, 'Ba da''ö niŵa''ögu ba danö bö''ö, tenga niŵa''ö Zo''aya: Na so dalifusö, si so ira alawe si tenga samati, ba na edöna ndra alawe soso khönia, ba böi yamutibo''ö.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 13, 'Ba na so ndra alawe, si so ira matua si tenga samati, ba na edöna ndra matua soso khönia, ba böi yamuröi.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 14, 'Noa sa mu''amoni''ö ndra matua si tenga samati, ba ndra alawe andrö, ba ira alawe si tenga samati, ba no mu''amoni''ö, ba ndra matua andrö. Na tenga si manö mena''ö, ba no si ra''iö ndraonomi, ba iya''e, ba no ni''amoni''ö.[7]', '["HalZin 16:1; Rom 11:16"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 15, 'Ba na edöna fabali zi tenga samati, ba yafabali ia; lö muböbö dangara ba zi manö, he talifusö matua, ba he talifusö alawe. Ba wa''atulö sa ikaoni ita Lowalangi.[8]', '["Kol 3:15"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 16, 'Hana wa ö''ila ya''ö, ya''ugö ira alawe, ö''orifi dania ndra matua? ba ma ya''ugö, ira matua, hana wa ö''ila, ö''orifi dania ndra alawe?[9]', '["FetI 3:1–2","Faigi 7:7; 20:24; Efes 4:1"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 17, 'Awai nifaigi: He wisa nibe''e Zo''aya ba zamösana, he wisa wogaoni Lowalangi zamösana, da''ö yamutörö. Ba si manö nihonogöigu ba mbanua misa fefu.[10]', '["FetI 3:1–2","Faigi 7:7; 20:24; Efes 4:1"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 18, 'Na so nikaoni si no muboto, ba böi yamubalugö. Ba na so nikaoni si lö muboto, ba böi yamufaboto''ö ia.[11]', '["Gal 5:2","Gal 5:6"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 19, 'Faya wamoto, ba faya na lö muboto, ha folo''ö oroisa Lowalangi zoguna.[12]', '["Gal 5:2","Gal 5:6"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 20, 'He wisa mege zamösana, me tekaoni ia, ba böi yamubulö''ö.', '["Gal 5:2","Gal 5:6"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 21, 'Na sawuyu ndra''ugö, me tekaoni ndra''ugö, ba böi abusi tödö; ba he göi ösöndra lala wangefa''ö ya''ugö, ba iagö manö da''ö.[13]', '["TimI 6:1–2; Kol 3:22","Yoh 8:36; Efes 6:6"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 22, 'Na so nikaoni ba khö Zo''aya, sawuyu, ba si no aefa sawuyu ia, khö Zo''aya. Si manö göi na so nikaoni si tenga sawuyu, ba no sawuyu Keriso ia.[14]', '["TimI 6:1–2; Kol 3:22","Yoh 8:36; Efes 6:6"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 23, 'No ebua mege hölimi, böi mi''ae sawuyu niha.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 24, 'He wisa zamösana, me tekaoni ia, ya''ami ira talifusö, ba böi yamubulö''ö ia ba da''ö, khö Lowalangi.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 25, 'Ba ba nono alawe andrö, ba lö khögu oroisa Zo''aya, ba era-eragu manö u''ombakha''ö, me no falukhado wa''ebua dödö Zo''aya, fa lö mofaya ndra''o.[15]', '["KorII 8:10; TimI 1:13–16"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 26, 'Ba da''ö dödögu: da''ö zi sökhi, me no ahatö wamakao, sohahau dödö niha, na si manö ia.', '["KorII 8:10; TimI 1:13–16"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 27, 'Na no faböbö ndra''ugö ba ndra alawe, ba böi alui wangefa''ö ya''ugö, ba na si lö donga ndra''ugö, ba böi alui ndra alawe.', '["TimI 4:1–3"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 28, 'Ba he mangowalu ndra''ugö, ba tenga samazökhi horö ndra''ugö. Ba na möi nihalö nono alawe, ba tenga samazökhi horö ia; ba falukha sa wamakao ba guli danö zi manö. Ba ya''o, ba omasido, na si lö famakao ami.[16]', '["TimI 4:1–3"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 29, 'Ba da''ö niŵa''ögu, ya''ami ira talifusö, no fadege, ba iada''e sa''ae, ba ena''ö hulö zi lö donga zi so donga;[17]', '["Luk 14:26","YohI 2:15–17; Mat 24:35"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 30, 'ba sege-ege andrö, ba ena''ö hulö zi lö mege-ege; ba somuso tödö andrö, ba ena''ö hulö zi lö omuso tödö; ba sowöli andrö, ba ena''ö hulö tenga khöra;', '["Luk 14:26","YohI 2:15–17; Mat 24:35"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 31, 'ba sangoguna''ö götö danö andre, ba ena''ö hulö zi lö mangoguna''ö ya''ia; ibörötaigö sa tobali danö''a andre.[18]', '["Luk 14:26","YohI 2:15–17; Mat 24:35"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 32, 'Ba omasido, na lö fangabu dödö khömi. Si lö donga, ba i''abusi tödö hadia ia khö Zo''aya, ena''ö i''omasi''ö ia So''aya.', '["Efes 5:29","TimI 5:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391754, 'NT', 'Korindro I', 7, 33, 'Ba sangowalu, ba i''abusi tödö hadia ia ba guli danö, ena''ö i''omasi''ö ia ira alawe.[19]', '["Efes 5:29","TimI 5:5"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 34, 'Noa göi faehu ira ndra alawe si no muhalö nono alawe. Si lö muhalö, ba i''abusi tödö hadia ia khö Zo''aya, ena''ö ohau-hau ia, he botonia, ba he tödönia. Ba si no muhalö, ba i''abusi tödö hadia ia ba guli danö, ena''ö i''omasi''ö ia ira matua.[20]', '["Efes 5:29","TimI 5:5"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 35, 'Ba wamobawa lala khömi, sohare ami, uŵa''ö da''ö, tenga ba wamöbö tangami, ena''ö moadu ba ena''ö lö tebulö ami khö Zo''aya, ena''ö lö mangoloi dödö.[21]', '["Faigi 7:28"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 36, 'Ba na so zanguma''ö tödönia, lö moadu khö nononia alawe, na italu''i ginötö wame''e ya''ia; no tobali lö tola lö''ö, ba yamutörö zomasi ia, tenga samozökhi horö ia; ndramöi nihalö.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 37, 'Ba na so zabe''e tödö, si tenga nilulugö, si tola molau somasi ia, ba na no ihuku tödönia, lö ibe''e nononia alawe, ba si sökhi nilau da''ö.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 38, 'Ba tobali, si sökhi göi nilau zame''e nihalö ononia alawe, ba mendrua manö ilau zi sökhi si lö mame''e ya''ia.', '[]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 39, 'Ira alawe, ba no muböbö danga, götö wa''anau noso ndra matua; ba na no mate ndra matua, ba aefa ia, gofu ha niha zangai ya''ia, ba tola möi ia, ba ha ba khö Zo''aya.[22]', '["Rom 7:2"]', NULL),
  (3391754, 'NT', 'Korindro I', 7, 40, 'Ba abölö ohahau dödönia, niŵa''ögu, na lö''ö sa''ae möi ia nihalö; ba ba dödögu, so khögu göi Geheha Lowalangi.', '["Rom 7:2"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 1, 'Ba ba gö nadu andrö, ba no ta''ila, si so fa''aboto ba dödö ita fefu. Famahokha wa''aboto ba dödö andrö ba fa''omasi andrö, ba fanga''azökhi.[1]', '["HalZin 15:29; Rom 14:19; 15:1–3","Gal 6:3","Faigi 13:12; Gal 4:9","Faigi 10:19 b.t."]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 2, 'Na so zanguma''ö tödönia, so hadia ia zaboto ba dödönia, ba tenga si nangea fa''aboto ba dödö wa''aboto ba dödönia andrö.[2]', '["HalZin 15:29; Rom 14:19; 15:1–3","Gal 6:3","Faigi 13:12; Gal 4:9","Faigi 10:19 b.t."]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 3, 'Ba na so zangomasi''ö Lowalangi, da''ö zaboto ba dödö Lowalangi.[3]', '["HalZin 15:29; Rom 14:19; 15:1–3","Gal 6:3","Faigi 13:12; Gal 4:9","Faigi 10:19 b.t."]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 4, 'Ba ba wemanga gö nadu andrö, ba no ta''ila, wa faya nadu ba guli danö, awö wa lö Lowalangi, baero zi sambua andrö.[4]', '["HalZin 15:29; Rom 14:19; 15:1–3","Gal 6:3","Faigi 13:12; Gal 4:9","Faigi 10:19 b.t."]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 5, 'Ba he ŵa''ae so nifotöi Lowalangi, he ba zorugo, ba he ba guli danö — oya sa Lowalangi ba ato zo''aya —[5]', '["Yoh 10:34 b.t.; Sin 136:2–3","Mal 2:10; Rom 11:36"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 6, 'ba khöda sa, ba ha sambua Lowalangi, Ama andrö, ba zi otarai fefu hadia ia, ba ya''ita, ba ba khönia ita ba ha samösa Zo''aya, Yesu Keriso, sama''ema fefu hadia ia, ba ya''ita, ba moroi khönia.[6]', '["Yoh 10:34 b.t.; Sin 136:2–3","Mal 2:10; Rom 11:36"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 7, 'Ba lö dozi so wa''aboto ba dödö; so ösa, ba irugi da''e itegu ira tödöra ba nadu andrö, ba femanga gö nadu khöra, na la''a, ba tödöra andrö, ba tetutu, me no sambö fa''abe''e.[7]', '["Faigi 10:27–28; Rom 14:23","Rom 14:6–17"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 8, 'Tenga femangada mbalazi, ba khö Lowalangi; lö tedou wa''asökhida, na manga ita, ba lö i''ambösi ita, na lö manga ita.[8]', '["Faigi 10:27–28; Rom 14:23","Rom 14:6–17"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 9, 'Ba mifaigi, fa böi tobali fangalani sambö fa''abe''e wa no tola khömi da''ö.[9]', '["Faigi 6:12; Rom 14:13 Gal 6:13","Rom 14:15"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 10, 'Na so zangila ya''ugö, na manga''ö ba nomo nadu, ya''ugö andrö, si no so fa''aboto ba dödö, ba hadia, ba lö tefarou dödönia, sambö fa''abe''e na ba wemange gö nadu andrö?', '["Faigi 6:12; Rom 14:13 Gal 6:13","Rom 14:15"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 11, 'Ba tobali famakiko zambö fa''abe''e wa''aboto ba dödö andrö khöu, famakiko dalifusö andrö, si no börö wa''amate Keriso andrö.[10]', '["Faigi 6:12; Rom 14:13 Gal 6:13","Rom 14:15"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 12, 'Ba na mosala ami, si manö, ba dalifusö, ba no tetutu dödöra, sambö fa''abe''e mibe''e, ba khö Keriso mosala ami.', '["Rom 14:21"]', NULL),
  (3391756, 'NT', 'Korindro I', 8, 13, 'Andrö, na te''ala dalifusögu, ba gö andrö, ba lö''ö manö u''a ndriwo, götö-götö wa''ara, fa lö ufobörö wangala ba dalifusögu.[11]', '["Rom 14:21"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 1, 'Hadia, tenga tola manö ulau zomasi ndra''o? Hadia, tenga sinenge ndra''o? Hadia, lö ni''ilagu Yesu, So''aya ya''ita? Hadia, tenga lua-lua halöŵögu ami, ba khö Zo''aya?[1]', '["Faigi 15:8 b.t.; 4:15; HalZin 9:4","KorII 3:2–3; 12:12","Faigi 4:3"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 2, 'Na tenga sinenge ndra''o ba danö bö''ö, ba ba khömi sa atö; famaduhu''ö halöŵögu, halöŵö zinenge andrö, ami, ba khö Zo''aya.[2]', '["Faigi 15:8 b.t.; 4:15; HalZin 9:4","KorII 3:2–3; 12:12","Faigi 4:3"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 3, 'Famu''agu da''ö, ba zanguhuku ya''o andrö.[3]', '["Faigi 15:8 b.t.; 4:15; HalZin 9:4","KorII 3:2–3; 12:12","Faigi 4:3"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 4, 'Hadia, lö tola manga ndra''aga, lö tola mabadu hadia ia?[4]', '["Luk 10:7","HalZin 1:14; Mat 8:14","HalZin 13:2; TesII 3:8–9","MozV 25:4; TimI 5:18"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 5, 'Hadia, lö tola ma''ohe-ohe awöma dalifusö alawe, fo''omoma, si mane sinenge bö''ö andrö göi ba talifusö Zo''aya ba Kefa?[5]', '["Luk 10:7","HalZin 1:14; Mat 8:14","HalZin 13:2; TesII 3:8–9","MozV 25:4; TimI 5:18"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 6, 'Ma ha daruaga Baranaba zi lö tola lö mohalöŵö?[6]', '["Luk 10:7","HalZin 1:14; Mat 8:14","HalZin 13:2; TesII 3:8–9","MozV 25:4; TimI 5:18"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 7, 'Ha niha zi möi sanuwö, sanaha göi balazonia? Ha niha zamazökhi kabu nagu, si lö manga mbua? Ba ha niha zokubaloi urifö, si lö mamadu susu gurifö andrö?', '["Luk 10:7","HalZin 1:14; Mat 8:14","HalZin 13:2; TesII 3:8–9","MozV 25:4; TimI 5:18"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 8, 'Hadia, tödö niha dali wehedegu andrö? Ma tenga si manö göi niŵa''ö ba goroisa?', '["Luk 10:7","HalZin 1:14; Mat 8:14","HalZin 13:2; TesII 3:8–9","MozV 25:4; TimI 5:18"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 9, 'Noa sa musura ba goroisa Moze: "Böi fosare''a mbawa göröbao samöbörö fakhe". Hadia, so ba dödö Lowalangi göröbao?[7]', '["Luk 10:7","HalZin 1:14; Mat 8:14","HalZin 13:2; TesII 3:8–9","MozV 25:4; TimI 5:18"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 10, 'Ma tenga ya''ita ato mbörö wanguma''önia da''ö? Ya''ita sa mbörö, wa tesura da''ö, wa lö tola lö idöna-döna lua-lua samaku tanö; ba si manö zamöbörö fakhe, idöna-döna wemanga.[8]', '["Yak 5:7","Rom 15:27","KorII 12:13; HalZin 20:33 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 11, 'Na no mataru khömi zoroi ba Geheha, ba hadia, nikata''ö sibai, na mabasi ba khömi zoguna balazo mboto?[9]', '["Yak 5:7","Rom 15:27","KorII 12:13; HalZin 20:33 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 12, 'Na so danö bö''ö sangokhögö göi hadia ia khömi, ba hadia, tenga mendrua manö ndra''aga? Ba lö ni''oguna''öma, wa tola da''ö mena''ö mataha manö sa''ae fefu hadia ia, fa lö mafobörö daha-taha ba duria somuso dödö andrö, khö Keriso.[10]', '["Yak 5:7","Rom 15:27","KorII 12:13; HalZin 20:33 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 13, 'Hadia lö mi''ila, wa ba gosali lasöndra göra si so halöŵö ba gosali? awö wa ba naha wame''e sumange mo''urakha zi so halöŵö ba naha wame''e sumange?[11]', '["MozV 18:1 b.t.","Faigi 9:4; Luk 10:7 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 14, 'Si manö göi, no i''oroi''ö So''aya ba zangombakha turia somuso dödö andrö, ba duria somuso dödö andrö lasöndra göra.[12]', '["MozV 18:1 b.t.","Faigi 9:4; Luk 10:7 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 15, 'Ba ya''o, ba lö ni''oguna''ögu da''ö, ma''ifu lö''ö. Ba tenga andrö usura da''ö, ena''ö lafatörö khögu zi manö; sökhi na i matedo, moroi faya khögu mbörö wanuno ya''o, ibe''e niha, ha niha ia.[13]', '["KorII 11:7 b.t.","Faigi 1:17","Faigi 4:1 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 16, 'Na u''ombakha''ö duria somuso dödö andrö, ba tenga börö wanuno khögu; lö''ö sa tola lö umanö, alai sa ndra''o, na lö u''ombakha''ö duria somuso dödö andrö![14]', '["KorII 11:7 b.t.","Faigi 1:17","Faigi 4:1 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 17, 'Na nilau dödögu sa, ba so luogu; ba na sabua ölö ndra''o, ba no nibe''e ba dangagu halöŵö andrö.[15]', '["KorII 11:7 b.t.","Faigi 1:17","Faigi 4:1 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 18, 'Ba hadia luogu ya''ö? Da''ö luogu, ube''e buala duria somuso dödö andrö, na u''ombakha''ö, fa lö u''oguna''ö zi tola ena''ö, ba halöŵö andrö, ba duria somuso dödö andrö.', '["KorII 11:7 b.t.","Faigi 1:17","Faigi 4:1 b.t."]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 19, 'He ŵa''ae tenga sawuyu niha ndra''odo, ba no ubali''ö sawuyu zato ndra''odo, ena''ö ato udönisi.[16]', '["Faigi 10:33; Mat 20:27,28","HalZin 16:3; 21:20 b.t.","Gal 2:3; 6:2; Yak 2:12","Faigi 9:19; KorII 11:29; HalZin 10:35; 10:32"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 20, 'Ba niha Yehuda, ba no tobali hulö niha Yehuda ndra''o, ena''ö udönisi niha Yehuda. Ba zi so barö mbawa goroisa, ba hulö zi so barö mbawa goroisa ndra''o, — ba tenga sa si so barö mbawa goroisa — ena''ö udönisi zi so barö mbawa goroisa.[17]', '["Faigi 10:33; Mat 20:27,28","HalZin 16:3; 21:20 b.t.","Gal 2:3; 6:2; Yak 2:12","Faigi 9:19; KorII 11:29; HalZin 10:35; 10:32"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 21, 'Ba zi lö oroisa, ba hulö zi lö oroisa ndra''o, — ba tenga sa si lö oroisa ba khö Lowalangi, solo''ö oroisa Keriso ndra''odo — ena''ö udönisi zi lö oroisa.[18]', '["Faigi 10:33; Mat 20:27,28","HalZin 16:3; 21:20 b.t.","Gal 2:3; 6:2; Yak 2:12","Faigi 9:19; KorII 11:29; HalZin 10:35; 10:32"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 22, 'Ba zambö fa''abe''e, ba no tobali sambö fa''abe''e ndra''o, ena''ö udönisi zambö fa''abe''e; fefu hadia ia, ba niha fefu ba no ugo''ö-go''ö, ena''ö fefu gofu heza, ba fasamösa na ato u''orifi.[19]', '["Faigi 10:33; Mat 20:27,28","HalZin 16:3; 21:20 b.t.","Gal 2:3; 6:2; Yak 2:12","Faigi 9:19; KorII 11:29; HalZin 10:35; 10:32"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 23, 'Ba börö duria somuso dödö andrö, wa ulau da''ö fefu, ena''ö mo''urakha göi ndra''o ba da''ö.', '[]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 24, 'Hadia, lö mi''ila ba zi fagohi andrö, ba lala wagohisa andrö, wa dozi sa fagohi ira, ba ha samösa zanema luo andrö? Ba mimanö wagohisa, ena''ö mitema![20]', '["Fil 3:12 b.t.","TimII 2:4; 4:8; FetI 5:4","Faigi 15:58","Rom 8:13 b.t.; 13:14"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 25, 'Ba dozi si fatandra töla andrö, ba laböhöli fefu hadia ia; ba ya''ira andrö, ena''ö latema dakula si tekiko dania, ba ya''ita, ena''ö tatema zi lö tebulö.[21]', '["Fil 3:12 b.t.","TimII 2:4; 4:8; FetI 5:4","Faigi 15:58","Rom 8:13 b.t.; 13:14"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 26, 'Ba ya''o, ba si fagohi, tenga si mane ba zi lö ta''ila; si fasöndra ndra''o, ba tenga ba dalu mbanua manö.[22]', '["Fil 3:12 b.t.","TimII 2:4; 4:8; FetI 5:4","Faigi 15:58","Rom 8:13 b.t.; 13:14"]', NULL),
  (3391757, 'NT', 'Korindro I', 9, 27, 'Ufakao mbotogu andre, ba u''osawuyu, fa böi si lö guna ndra''o, he no sangombakha lala ba danö bö''ö ndra''odo.[23]', '["Fil 3:12 b.t.","TimII 2:4; 4:8; FetI 5:4","Faigi 15:58","Rom 8:13 b.t.; 13:14"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 1, 'Lö''ö sa ubini''ö khömi, ya''ami ira talifusö; no a''oi barö lawuo andrö so ndra tuada, no a''oi latörö nasi,[1]', '["MozII 13:21; 14:29; Sin 78:13–14","MozII 16:4; Sin 78:24 b.t.; Yoh 6:49","MozII 17:6; MozV 32:4–18","MozIV 14:22; 23:30–32; Heb 3:16 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 2, 'no ahori tebayagö idanö ira, ba khö Moze, ba lawuo andrö ba ba nasi andrö,', '["MozII 13:21; 14:29; Sin 78:13–14","MozII 16:4; Sin 78:24 b.t.; Yoh 6:49","MozII 17:6; MozV 32:4–18","MozIV 14:22; 23:30–32; Heb 3:16 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 3, 'ba no ha sambalö gö moroi yaŵa la''a.[2]', '["MozII 13:21; 14:29; Sin 78:13–14","MozII 16:4; Sin 78:24 b.t.; Yoh 6:49","MozII 17:6; MozV 32:4–18","MozIV 14:22; 23:30–32; Heb 3:16 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 4, 'Ba no ha sambalö moroi yaŵa labadu; moroi ba gara andrö, moroi yaŵa, si fao khöra, labadu-badu, ba kara andrö, ba ya''ia Keriso.[3]', '["MozII 13:21; 14:29; Sin 78:13–14","MozII 16:4; Sin 78:24 b.t.; Yoh 6:49","MozII 17:6; MozV 32:4–18","MozIV 14:22; 23:30–32; Heb 3:16 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 5, 'Ba sato andrö, ba lö omasi Lowalangi, noa sa tefakiko ira ba danö si mate.[4]', '["MozII 13:21; 14:29; Sin 78:13–14","MozII 16:4; Sin 78:24 b.t.; Yoh 6:49","MozII 17:6; MozV 32:4–18","MozIV 14:22; 23:30–32; Heb 3:16 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 6, 'Ba duma-duma khöda da''ö, wa si manö, fa böi ta''isö zi lö sökhi, si mane fangisöra andrö.[5]', '["MozIV 11:4; Sin 78:18 b.t.","MozII 32:6","Faigi 6:13 b.t.; MozIV 25:1–9","MozIV 21:5–6; Sin 106:14 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 7, 'Ba böi göi mi''ame''e adu, si mane ya''ira ösa, niŵa''ö ba zura: "Mudadao niha manga ba mamadu hadia ia, ba maoso ira molaya."[6]', '["MozIV 11:4; Sin 78:18 b.t.","MozII 32:6","Faigi 6:13 b.t.; MozIV 25:1–9","MozIV 21:5–6; Sin 106:14 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 8, 'Ba böi göi mohorö ita, si mane ya''ira ösa, me mohorö, ba mate zi dua wulu a tölu ngahönö niha, ha ma''ö-ma''ökhö.[7]', '["MozIV 11:4; Sin 78:18 b.t.","MozII 32:6","Faigi 6:13 b.t.; MozIV 25:1–9","MozIV 21:5–6; Sin 106:14 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 9, 'Ba böi göi tatandraigö Zo''aya, si mane ya''ira ösa, me latandraigö, ba ibunu ira ulö.[8]', '["MozIV 11:4; Sin 78:18 b.t.","MozII 32:6","Faigi 6:13 b.t.; MozIV 25:1–9","MozIV 21:5–6; Sin 106:14 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 10, 'Böi göi mikökö-kökö, si mane ya''ira ösa, me kumökö-kökö, ba ibunu ira samakiko andrö.[9]', '["MozIV 14:2–37","Rom 15:4; Heb 4:11; 9:26","Rom 11:20"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 11, 'Ba duma-duma da''ö, wa göna ira zi manö, ba famangelama ya''ita, wa tebe''e ia ba zura, ya''ita si fakhamö amozua götö danö andre.[10]', '["MozIV 14:2–37","Rom 15:4; Heb 4:11; 9:26","Rom 11:20"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 12, 'Andrö, na so zanguma''ö tödönia sizizio ia, ba yamufaigi, fa böi alau ia.[11]', '["MozIV 14:2–37","Rom 15:4; Heb 4:11; 9:26","Rom 11:20"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 13, 'Lö''ö na si göna ami fanandraigö, ha fanandraigö ba niha; ba lö faröi Lowalangi, lö ibe''e tetandraigö ami, si tebai mitaha, awö wanandraigö ifaigi göi wa''awai, ena''ö tola mitaha.[12]', '["Faigi 1:9; TesII 3:3; FetII 2:9"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 14, 'Andrö, ya''ami somasi ndra''o, mi''angelamaisi wame''e adu andrö.[13]', '["YohI 5:21","Faigi 14:37"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 15, 'Fehede ba zatua-tua wehedegu; mitimba tödömi niŵa''ögu.[14]', '["YohI 5:21","Faigi 14:37"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 16, 'Mako famahowu''ö andrö, nifahowu''öda, hadia, tenga famo''urakha ba ndro Keriso? Roti andrö, nibobotoda, hadia, tenga famo''urakha ba mboto Keriso?[15]', '["Faigi 11:24 b.t.; Mat 26:27; HalZin 2:42","Faigi 12:27"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 17, 'Me ha sambua roti, ba ha sambua boto ita, ya''ita sato; a''oi sa mo''urakha ita ba roti andrö, si ha sambua.[16]', '["Faigi 11:24 b.t.; Mat 26:27; HalZin 2:42","Faigi 12:27"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 18, 'Mifaigi Ndraono Gizeraeli andrö, si ndruhu madou Yakobo. Hadia, tenga no faböbö ba naha wame''e sumange zi manga zumange andrö?[17]', '["MozIII 7:6; 15:16","Faigi 8:4 b.t.","MozIII 17:7; Fam 9:20","KorII 6:15; Mal 1:7","MozV 32:21"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 19, 'Ba hadia niŵa''ögu? Hadia, soboto zumange nadu andrö, ba ma adu andrö, hadia, soboto?[18]', '["MozIII 7:6; 15:16","Faigi 8:4 b.t.","MozIII 17:7; Fam 9:20","KorII 6:15; Mal 1:7","MozV 32:21"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 20, 'Tenga si manö. Hadia zumange, nibe''era, ba ba mbekhu labe''e, tenga khö Lowalangi. Ba lö omasido, na ba mbekhu faböbö ami.[19]', '["MozIII 7:6; 15:16","Faigi 8:4 b.t.","MozIII 17:7; Fam 9:20","KorII 6:15; Mal 1:7","MozV 32:21"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 21, 'Tebai faoma mibadu, he ösi mako andrö khö Zo''aya, ba he ösi mako mbekhu. Tebai faoma mo''urakha ami, he ba wemanga andrö khö Zo''aya, ba he ba wemanga ba mbekhu.[20]', '["MozIII 7:6; 15:16","Faigi 8:4 b.t.","MozIII 17:7; Fam 9:20","KorII 6:15; Mal 1:7","MozV 32:21"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 22, 'Ma edöna ita ta''andrö wönu Zo''aya? Hadia, sabölö moroi khönia ita?[21]', '["MozIII 7:6; 15:16","Faigi 8:4 b.t.","MozIII 17:7; Fam 9:20","KorII 6:15; Mal 1:7","MozV 32:21"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 23, 'Fefu hadia ia, ba tola, ba so zi lö guna. Fefu hadia ia, ba tola, ba so zi lö möi fanga''azökhi.[22]', '["Faigi 6:12; 8:1 b.t.","Faigi 13:5; Rom 15:2","Rom 14:2 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 24, 'Böi yamu''alui zoguna khönia zamösana, soguna khö nawönia yamu''alui.[23]', '["Faigi 6:12; 8:1 b.t.","Faigi 13:5; Rom 15:2","Rom 14:2 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 25, 'Fefu hadia ia ni''amawa ba onga, ba mi''a, böi mizofu-zofu, ba dödömi andrö.[24]', '["Faigi 6:12; 8:1 b.t.","Faigi 13:5; Rom 15:2","Rom 14:2 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 26, 'Khö Zo''aya sa danö, awö nösi guli danö.[25]', '["Sin 50:12","Faigi 8:7","Faigi 8:8 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 27, 'Ba na so zogaoni ya''ami tome, si tenga samati, ba na edöna möi ami, ba fefu hadia ia nibe''e ömi, ba mi''a, böi mizofu-zofu, ba dödömi andrö.[26]', '["Sin 50:12","Faigi 8:7","Faigi 8:8 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 28, 'Ba na so zanguma''ö khömi; Sumange nadu da''e, ba böi mi''a, börö zangombakha andrö ba tödö andrö.', '["Sin 50:12","Faigi 8:7","Faigi 8:8 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 29, 'Tenga tödö nifangelama andrö niŵa''ögu, tödö danö bö''ö; hana sa wa ihuku zi tola khögu tödö danö bö''ö?[27]', '["Sin 50:12","Faigi 8:7","Faigi 8:8 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 30, 'Na u''andrö saoha gölö, na mangado, ba hana wa latandraŵaisi ndra''o ba ni''andrögu saoha gölö?[28]', '["MozV 8:10; TimI 4:4","Kol 3:17"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 31, 'Ba he si manga ami, ba he samadu hadia ia, ba ma hadia nilaumi, ba ba wamosumange Lowalangi milau ia fefu.[29]', '["MozV 8:10; TimI 4:4","Kol 3:17"]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 32, 'Böi mifobörö wangala, he ba niha Yehuda, ba he ba Ndrawa Heleni, ba he ba mbanua Lowalangi;[30]', '["Rom 14:13; Faigi 9:22","Faigi 8:13; 9:19 b.t."]', NULL),
  (3391758, 'NT', 'Korindro I', 10, 33, 'hulö si mane ya''o, me no ugo''ö-go''ö khöra fefu, ha niha ira, me lö u''alui zoguna khögu, me ha soguna ba zato u''alui, ena''ö te''orifi ira.[31]', '["Rom 14:13; Faigi 9:22","Faigi 8:13; 9:19 b.t."]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 1, 'Mibe''e tulada khömi ndra''odo, si mane ya''o, me no ube''e tulada khögu Keriso.[1]', '["Faigi 4:16; Fil 3:17"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 2, 'Ba usuno ami, me itörö-törö tödömi ndra''o, gofu hadia nilaumi, ba me mi''o''ö gamakhoita andrö, si mane nifa''emagu khömi.', '["Faigi 4:16; Fil 3:17"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 3, 'Ba omasido na mi''ila; högö ndra matua fefu, ba ya''ia Keriso, ba högö ndra alawe ndra matua, ba högö Keriso Lowalangi.[2]', '["Faigi 3:23; Efes 5:23"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 4, 'Na so ndra matua sangandrö, ba ma sama''ele''ö, si so balu-balu högö, ba i''o''aya högönia.[3]', '["Faigi 14:1","Faigi 14:34","MozI 1:27; 2:22 b.t."]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 5, 'Ba ira alawe, ba i''o''aya högönia, na lö balu-balu högö, na mangandrö ia, ba ma na mama''ele''ö ia, faoma sa ira zi no mutöwö.[4]', '["Faigi 14:1","Faigi 14:34","MozI 1:27; 2:22 b.t."]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 6, 'Na lö''ö sa ibalugö ia ira alawe, ba yamufatöwö''ö göi ia. Ba na aila ndra alawe, ifaguti''ö mbunia, ba ma ifatöwö''ö, ba yamubalugö ia.', '["Faigi 14:1","Faigi 14:34","MozI 1:27; 2:22 b.t."]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 7, 'Akha sa lö ifobalu-balu högönia ira matua, me no duma-duma Lowalangi ia ba me no lakhömi Lowalangi; ba ira alawe, ba no lakhömi ndra matua.[5]', '["Faigi 14:1","Faigi 14:34","MozI 1:27; 2:22 b.t."]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 8, 'Tenga sa soroi ba ndra alawe ndra matua, no moroi ba ndra matua ndra alawe.[6]', '["TimI 2:13","MozI 2:18"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 9, 'Tenga sa göi ira alawe mbörö, wa tefazökhi ndra matua, no ira matua mbörö, wa tefazökhi ndra alawe.[7]', '["TimI 2:13","MozI 2:18"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 10, 'Andrö lö tola lö so ba högö ndra alawe dandra, wa no barö mbawa ia, börö mala''ika andrö.[8]', '["MozI 24:65","Yoh 15:1"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 11, 'Ba tenga ha ira alawe, lö ira matua, ba tenga ha ira matua, lö ira alawe, ba khö Zo''aya.', '["MozI 24:65","Yoh 15:1"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 12, 'Hulö da''ö sa, wa no moroi ba ndra matua ndra alawe, si manö göi, wa no moroi ba ndra alawe ndra matua, ba fefu hadia ia, ba no moroi ba Lowalangi.[9]', '["MozI 24:65","Yoh 15:1"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 13, 'Mitimba tödömi, ha ya''ami. Hadia, moadu ba ndra alawe, na mangandrö ia khö Lowalangi, lö balu-balu högö?', '["SamII 14:26"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 14, 'Hadia, tenga no to''ua manö göi oroma khömi, wa lö moadu ba ndra matua, na anau mbunia,[10]', '["SamII 14:26"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 15, 'awö wa no lakhömi ndra alawe mbu sanau? me no salahi mbalu-balu khönia, wa no mube''e khönia mbu andrö.', '["SamII 14:26"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 16, 'Ba na so zomasi fagua-gua ba da''ö, ba tenga huku ba khöma zi manö, ba tenga göi huku mbanua Lowalangi misa.[11]', '["TimI 6:3–5"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 17, 'Ba me itörö ligu da''ö, ba tebai usuno gowuloami, me tenga ba wanga''azökhi, me no ba wa''awuwu.', '["Faigi 3:3 b.t.","Mat 18:7; YohI 2:19"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 18, 'Si föföna ua, ba urongo, lö ha sara dödömi, na owulo mbanua, ba no faduhu dödögu, si duhu ösa.[12]', '["Faigi 3:3 b.t.","Mat 18:7; YohI 2:19"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 19, 'Lö''ö sa tola lö so zi faehu era-era ba khömi, ena''ö oroma zi faduhu dödöda, ba khömi.[13]', '["Faigi 3:3 b.t.","Mat 18:7; YohI 2:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391759, 'NT', 'Korindro I', 11, 20, 'Ba na owulo ami, ba tobali tenga ba wolau femanga andrö, khö Zo''aya.', '["Faigi 3:3 b.t.","Mat 18:7; YohI 2:19"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 21, 'Ihönagö i''a gönia zamösana, ba wemanga andrö, ba no olofo zi samösa, ba ibusi ia agu si samösa.', '["Faigi 3:3 b.t.","Mat 18:7; YohI 2:19"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 22, 'Hadia, lö khömi omo, ba wemanga ba ba wamadu hadia ia? Ma lö ba dödömi mbanua Lowalangi andrö, ba mi''ailasi zi lö ba danga? Ha uŵa''ö khömi? Hadia, usuno ami? Ba da''ö lö usuno ami.[14]', '["Yak 2:5–6","Gal 1:12; Mat 26:26 b.t.","Luk 22:20","MozII 12:26–27; Mat 26:29"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 23, 'Ya''odo sa, ba no khö Zo''aya utema, nifa''emagu khömi göi: So''aya ya''ita, Yesu, me bongi andrö, me te''a mbölinia, ihalö roti,[15]', '["Yak 2:5–6","Gal 1:12; Mat 26:26 b.t.","Luk 22:20","MozII 12:26–27; Mat 26:29"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 24, 'ba i''aohasi gölö Lowalangi, ba iboboto roti ba imane: Botogu da''e, salahimi, mitörö-törö tödömi ndra''o ba zi mane.', '["Yak 2:5–6","Gal 1:12; Mat 26:26 b.t.","Luk 22:20","MozII 12:26–27; Mat 26:29"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 25, 'Si manö göi mako, me no aefa manga ira, ba imane: Amabu''ula li si bohou mako andre, ba ndrogu. Gofu ha me uga mibadu da''e, ba mitörö-törö tödömi ndra''odo.[16]', '["Yak 2:5–6","Gal 1:12; Mat 26:26 b.t.","Luk 22:20","MozII 12:26–27; Mat 26:29"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 26, 'Ha me uga mi''a roti andrö sa, ba ha me uga mibadu nösi mako andrö, ba mi''ombakha''ö wa''amate Zo''aya, irugi so ia.[17]', '["Yak 2:5–6","Gal 1:12; Mat 26:26 b.t.","Luk 22:20","MozII 12:26–27; Mat 26:29"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 27, 'Tobali, na so zi manga roti andrö, ba ma samadu ösi mako andrö, khö Zo''aya, si tenga si nangea, ba mosala ia ba mboto Zo''aya andrö ba ba ndronia.[18]', '["Faigi 10:21","KorII 13:5","Faigi 10:16–17"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 28, 'Ba yamusekhegö dödönia zamösana, ba awena yamu''a wöfö roti andrö ba yamubadu wöfö nösi mako andrö.[19]', '["Faigi 10:21","KorII 13:5","Faigi 10:16–17"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 29, 'Si manga sa ba samadu, ba i''a khönia huku ba ibadu khönia, na lö ifaehusi mboto andrö.[20]', '["Faigi 10:21","KorII 13:5","Faigi 10:16–17"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 30, 'Andrö ato ba khömi zambö fa''abölö ba sofökhö, ba tenga si lö ato zi no mate.', '["Sin 32:5","Heb 12:5–6"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 31, 'Ba na ya''ita zanguhuku ya''ita, ba lö tehuku ita ena''ö.[21]', '["Sin 32:5","Heb 12:5–6"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 32, 'Ba na tehuku ita, ba ni''otu''ö ita, khö Zo''aya, ena''ö lö tetibo ita, awö niha guli danö.[22]', '["Sin 32:5","Heb 12:5–6"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 33, 'Andrö, ya''ami ira talifusögu, na owulo ami ba wemanga, ba yamubase''ö nawönia zamösana.', '["Faigi 16:5"]', NULL),
  (3391759, 'NT', 'Korindro I', 11, 34, 'Na so zolofo, ba yomo yamanga, fa böi mifobörö khömi huku, na owulo ami. Ba hadia ia danö bö''ö, ba uŵa''ö li, na sodo.[23]', '["Faigi 16:5"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 1, 'Ba lö omasido, lö mi''ila watahögö, ya''ami ira talifusö, ba mbuala Geheha andrö.[1]', '["Faigi 14:2","Faigi 6:11"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 2, 'Lö solifu ami: me luo niha baero ami, ba ba nadu si lö hede andrö misaŵa, nidöni ta''io.[2]', '["Faigi 14:2","Faigi 6:11"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 3, 'Andrö u''ombakha''ö khömi: lö i''elifi Yesu sihede moroi ba Geheha Lowalangi, ba tebai faso''aya khö Yesu niha, na tenga moroi ba Geheha ni''amoni''ö.[3]', '["Mar 9:39 b.t.; Yoh 13:13; YohI 4:2–3","Rom 12:6","Faigi 12:28; 8:6","Efes 4:6"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 4, 'Ba no faehu mbuala fa''ebua dödö andrö, ba ha sambua Geheha,[4]', '["Mar 9:39 b.t.; Yoh 13:13; YohI 4:2–3","Rom 12:6","Faigi 12:28; 8:6","Efes 4:6"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 5, 'ba no faehu halöŵö, ba ha samösa Zo''aya,[5]', '["Mar 9:39 b.t.; Yoh 13:13; YohI 4:2–3","Rom 12:6","Faigi 12:28; 8:6","Efes 4:6"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 6, 'no faehu wa''abölö, ba ha sambua Lowalangi, sanga''asogö fefu hadia ia, ba dödö zi no ato andrö fefu.[6]', '["Mar 9:39 b.t.; Yoh 13:13; YohI 4:2–3","Rom 12:6","Faigi 12:28; 8:6","Efes 4:6"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 7, 'Ba ena''ö ba zato moguna, andrö tebe''e wama''ele''ö Geheha andrö ba zamösana.[7]', '["Faigi 14:26","Faigi 13:2","Faigi 14:1; 5:24–29; YohI 4:1","Faigi 14:1–5; 24:29; YohI 4:1"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 8, 'Ba zi samösa, ba tebe''e moroi ba Geheha daroma li fa''atua-tua, ba ba zi samösa, ba taroma li fangaboto ba dödö, moroi ba Geheha da''ö göi;[8]', '["Faigi 14:26","Faigi 13:2","Faigi 14:1; 5:24–29; YohI 4:1","Faigi 14:1–5; 24:29; YohI 4:1"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 9, 'ba ba zi samösa, ba buala ba wamadöhö fökhö, moroi ba Geheha si ha sambua andrö;[9]', '["Faigi 14:26","Faigi 13:2","Faigi 14:1; 5:24–29; YohI 4:1","Faigi 14:1–5; 24:29; YohI 4:1"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 10, 'ba ba zi samösa, ba famazökhi sahöli-höli dödö; ba ba zi samösa, ba fama''ele''ö; ba ba zi samösa, ba fangila amuata Geheha; ba ba zi samösa, ba oya ngawalö li; ba ba zi samösa, ba famotokhi li andrö.[10]', '["Faigi 14:26","Faigi 13:2","Faigi 14:1; 5:24–29; YohI 4:1","Faigi 14:1–5; 24:29; YohI 4:1"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 11, 'Ba fefu hadia ia zi manö, ba oi Eheha da''ö, si ha sambua, zanga''asogö; ifosasi, ibe''e ba zamösana zomasi ia.[11]', '["Rom 12:3"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 12, 'Hulö mbotoda andrö, si ha sambua, ba no oya ndroto-ndroto, ba tobali ha sambua boto ndroto-ndroto mboto andrö, ha wa''oya ira, si manö göi khö Keriso.[12]', '["Rom 12:4 b.t."]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 13, 'Ha sa sambua Geheha, me tebayagö idanö ita fefu, ena''ö ha sambua boto ita, he niha Yehuda, ba he Dawa Heleni, he sawuyu, ba he si tenga sawuyu; ba ha sambua Geheha nifabadugö khöda.[13]', '["Faigi 10:2–4"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 14, 'Botoda andrö sa göi, ba tenga ha sambua ndroto-ndroto, no oya.', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 15, 'Na iŵa''ö ena''ö ahe: Me tenga tanga ndra''odo, ba tenga si faböbö ba mboto ndra''o, ba no tenga börö da''ö, wa tenga si faböbö ba mboto ia.', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 16, 'Ba na iŵa''ö ena''ö talinga: Me tenga hörö ndra''odo, ba tenga si faböbö ba mboto ndra''o, ba no tenga börö da''ö, wa tenga si faböbö ba mboto ia.', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 17, 'Hadia na ha sambalö hörö mboto, ba heza dögi dalinga? Ba na ha sambalö tögi dalinga, ba hezo dögi nikhu?', '["Faigi 15:38"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 18, 'Ba noa sa ifonaha ndroto-ndroto andrö Lowalangi, no ifasambua ba mboto, balazi zomasi ia.[14]', '["Faigi 15:38"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 19, 'Ba na ha sambua ndroto-ndroto ena''ö, ba heza so mboto?', '["Faigi 15:38"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 20, 'Ba iya''e ba noa sa oya ndroto-ndroto, ba ha sambua boto.', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 21, 'Ba tebai iŵa''ö hörö ba danga: Lö gunau khögu. Ba tebai göi iŵa''ö högö ba gahe: Lö gunami khögu.', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 22, 'Tobali sa moguna khöda ndroto-ndroto mboto andrö, niŵa''öda sambö fa''abölö.', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 23, 'Ba niŵa''öda ni''ositengagö ba mboto andrö, ba no abölö tafosumange, ba si lö moadu khöda, ba abölö tafoadu;', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 24, 'ba zoadu khöda, ba lö moguna. Noa sa ifa''anö mboto andrö Lowalangi, no abölö ifoadu zide-idenia,', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 25, 'ena''ö lö fa''afabali ba mboto andrö, ena''ö faoma larorogö nawöra ndroto-ndroto andrö.', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 26, 'Ba na so zafökhö ba zi sambua ndroto-ndroto, ba oi afökhö ba ndroto-ndroto fefu, ba na so nifosumange, ndroto-ndroto, ba oi zara, omuso dödö ndroto-ndroto bö''ö andrö göi.[15]', '["Rom 12:15","Rom 12:5"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 27, 'Ba ya''ami, ba boto Keriso, ba no ndroto-ndroto zamösana.[16]', '["Rom 12:15","Rom 12:5"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 28, 'Ba so nifataro Lowalangi, ba mbanua: si föföna, ba sinenge, ba fanete, ba sama''ele''ö, ba fanete, ba samahaö, awena zahöli-höli dödö andrö, awena mbuala ba wamadöhö fökhö, ba fanolo ba famatörö, ba soya ngawalö li.[17]', '["Faigi 12:8–10; Efes 4:11–12"]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 29, 'Hadia, a''oi sinenge ira? Hadia, a''oi sama''ele''ö? Hadia, a''oi samahaö? Hadia, oi dozi so khöra zahöli-höli dödö andrö?', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 30, 'Hadia, oi dozi so khöra mbuala andrö, ba wamadöhö fökhö? oi dozi so ngawalö li? oi dozi ira zamotokhi?', '[]', NULL),
  (3391760, 'NT', 'Korindro I', 12, 31, 'Miforege wangalui buala si sökhi andrö. Ba u''oroma''ö na khömi lala si sökhi moroi ba da''ö.[18]', '["Faigi 14:1 b.t."]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 1, 'He fehede niha ba fehede mala''ika wehedegu, ba na lö khögu fa''omasi andrö, ba hulö garamba soli ba hulö riti-riti ndra''odo.[1]', '["Faigi 14:6–9","Faigi 12:8–9; Mat 7:22; 17:20","Mat 6:1 b.t.; Dan 3:28; SinSeb 8:7"]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 2, 'Ba he no so khögu wama''ele''ö, ba he no u''ila fefu zi no tobini andrö, awö wa''aboto ba dödö andrö fefu, ba he no a''oi so khögu wamati andrö, ba wamawu''a hili, ba na lö khögu fa''omasi andrö, ba faya ndra''odo.[2]', '["Faigi 14:6–9","Faigi 12:8–9; Mat 7:22; 17:20","Mat 6:1 b.t.; Dan 3:28; SinSeb 8:7"]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 3, 'Ba he ahori ube''e balazo zi numana zi so khögu, ba he ululu mbotogu, ena''ö latunu auri, ba na lö khögu fa''omasi andrö, ba lö gunania.[3]', '["Faigi 14:6–9","Faigi 12:8–9; Mat 7:22; 17:20","Mat 6:1 b.t.; Dan 3:28; SinSeb 8:7"]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 4, 'Fa''omasi andrö, ba no sebolo tödö, no sebua tödö; fa''omasi andrö, ba lö i''afökhöi tödö nawönia, lö isuno ia, lö mohokha.[4]', '["Yak 3:17","Faigi 10:24; Fil 2:4","Rom 15:1; Amaed 10:12"]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 5, 'Lö ilau zi lö moadu, lö i''alui dana khönia; lö mofönu ia; lö itanö ba dödönia zi lö sökhi;[5]', '["Yak 3:17","Faigi 10:24; Fil 2:4","Rom 15:1; Amaed 10:12"]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 6, 'lö omuso dödönia ba zi lö atulö, ba omuso dödönia awö zi duhu.', '["Yak 3:17","Faigi 10:24; Fil 2:4","Rom 15:1; Amaed 10:12"]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 7, 'Fefu hadia ia zi falukha ia, ba itaha dödönia; fefu hadia ia, ba faduhu dödönia; fefu hadia ia, ba idöna-döna, fefu hadia ia, ba itaögö.[6]', '["Yak 3:17","Faigi 10:24; Fil 2:4","Rom 15:1; Amaed 10:12"]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 8, 'Si lö mamalö-malö wa''omasi andrö; he fama''ele''ö sa, ba tebato dania, ba he ngawalö li, ba tebato, ba he fa''aboto ba dödö andrö, ba tebato dania.', '[]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 9, 'Sambö-ambö sa wa''aboto ba dödöda andrö, ba sambö-ambö wama''ele''öda andrö.', '[]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 10, 'Ba na so zo''ahonoa andrö, ba tebato zambö-ambö andrö.', '[]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 11, 'Me iraono ndra''odo, ba no fehede ndraono wehedegu ba tödö ndraono dödögu ba era-era ndraono gera-eragu, ba me no tobali ira matua ndra''odo, ba uböhöli nifolau ndraono.', '[]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 12, 'Ha sa dahö-dahö ni''ilada iada''e, ba zörömi, ba ba da''ö dania, ba fa''ila bawa. Iada''e ambö-ambö wa''aboto ba dödögu, ba ba da''ö dania, ba u''ila, si mane fangila ya''odo andrö.[7]', '["MozIV 12:8; KorII 3:18; 5:7; Faigi 8:3; YohI 3:2"]', NULL),
  (3391761, 'NT', 'Korindro I', 13, 13, 'Ba me si manö, ba si lö tebulö wamati ba fanötöna ba fa''omasi, si tölu andrö, ba sebuara, ba fa''omasi andrö.[8]', '["TesI 1:3; Heb 10:22–24; Kol 3:14"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 1, 'Migohi wa''omasi andrö, ba mi''alu-alui mbuala Geheha andrö, ba si oföna, ba ena''ö mi''ila mama''ele''ö.[1]', '["Faigi 12:1 b.t. 31","HalZin 10:46"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 2, 'Solau ngawalö li andrö, ba tenga ba niha muhede, no khö Lowalangi muhede ia, lö''ö sa samondrongo, niha, ba moroi ba Geheha iŵa''ö zi no tobini.[2]', '["Faigi 12:1 b.t. 31","HalZin 10:46"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 3, 'Ba sama''ele''ö, ba ba niha muhede, fanga''azökhi ba famarou dödö, ba fondrara dödö.', '["Faigi 12:1 b.t. 31","HalZin 10:46"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 4, 'Solau ngawalö li andrö, ba ya''ia ni''a''asökhinia, ba sama''ele''ö, ba banua i''a''asökhi.', '["Faigi 12:1 b.t. 31","HalZin 10:46"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 5, 'Ba omasido, na dozi ami milau ngawalö li, ba mendrua manö, na mama''ele''ö ami. Ba ebua zama''ele''ö, moroi ba zolau ngawalö li andrö, ato na ibotokhi, ena''ö möi fanga''azökhi mbanua.[3]', '["MozIV 11:29"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 6, 'Ba me no si manö, ya''ami ira talifusö, ba na möido khömi ena''ö, molau ngawalö li, ba hadia gunagu khömi, na lö muhededo khömi, ma famokai hadia ia, ba ma famotokhi, ba ma fama''ele''ö, ba ma famahaö?', '["MozIV 11:29"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 7, 'Si manö göi ba mai-mai si lö noso andrö, soli, he sigu, ba he biola, na lö faehu li, salua, ba he lawisa wamondrongo hadia li zigu ba hadia li mbiola?', '[]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 8, 'Ba torofe göi, na li si lö mila manö linia, ba ha niha zama''anö ya''ia ba wanuwö?', '[]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 9, 'Si manö göi ami, na si lö mila wehedemi, na milau ngawalö li, ba he moroi aboto ba dödö niŵa''ö andrö? ba dalu mbanua sa''ae muhede ami.', '[]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 10, 'Ta''ila ha wa''oya ngawalö li ba guli danö, ba lö si lö eluaha.[4]', '["Sin 19:4 b.t."]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 11, 'Ba na lö u''ila geluaha li andrö, ba niha bö''ö ndra''o, khö zihede andrö, ba sihede andrö, ba niha bö''ö ia khögu.', '["Sin 19:4 b.t."]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 12, 'Si manö göi ami, me no solohi Eheha ami, ba mi''alui, ena''ö fahöna khömi, ba wanga''azökhi banua.', '["Sin 19:4 b.t."]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 13, 'Andrö, na so zolau ngawalö li andrö, ba yamu''andrö, ena''ö i''ila ibotokhi.', '["Yak 5:13"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 15, 'Ba he wisa? Da''u''angandrö''ö dödö ba u''angandrö''ö göi gera-era; u''anunö''ö dödö ba u''anunö''ö göi gera-era.[5]', '["Yak 5:13"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 16, 'Na tenga si manö, ba he iwisa si lö to''ölö ba da''ö, wamaduhu''ö fanunömö, na ö''anunö''ö dödö, me lö i''ila, hadia niŵa''öu.[6]', '["Nga''ötI 16:36; Neh 8:6"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 17, 'Te sökhi sa wanunöu, ba lö möi fanga''azökhi danö bö''ö.', '["Nga''ötI 16:36; Neh 8:6"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 18, 'Usuno Lowalangi, me asese ulau ngawalö li andrö, moroi khömi fefu.', '["Nga''ötI 16:36; Neh 8:6"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 19, 'Ba na ba mbanua, ba omasido, ha lima ngawua li uŵa''ö, soroi ha gera-eragu, ena''ö ufahaö danö bö''ö göi, moroi fulu ngahönö ngawua li uŵa''ö, wolau ngawalö li andrö.', '["Nga''ötI 16:36; Neh 8:6"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 20, 'He ya''ami ira talifusö! böi mibali''ö iraono ami, ba gera-era andrö; ba zi lö sökhi mibali''ö iraono ami, ba ba gera-era andrö, ba ena''ö mo''ahonoa ami.[7]', '["Mat 10:16; Rom 16:17","Yes 28:11–12"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 21, 'Noa sa so ba zura goroisa: "Li niha bö''ö ulau dania ba niha andrö, ba bewe niha bö''ö ufake, wehede khöra, ba he si manö, ba lö''ö zui lafondrondrongo ligu, iŵa''ö So''aya."[8]', '["Mat 10:16; Rom 16:17","Yes 28:11–12"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 22, 'Tobali tandra ngawalö li andrö, tenga ba zamati, no ba zi lö mamati, ba fama''ele''ö andrö, ba tenga ba zi lö mamati, no ba zamati.', '["HalZin 2:12–13","Heb 4:12","Yes 60:14"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 23, 'Ba na owulo ena''ö mbanua fefu, ba na oi zara lalau ngawalö li ena''ö, ba na so zi möi bakha si lö to''ölö ba da''ö, ba ma si tenga samati, hadia, lö laŵa''ö sowöhö ami?[9]', '["HalZin 2:12–13","Heb 4:12","Yes 60:14"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 24, 'Ba na a''oi mama''ele''ö, ba na so zi möi bakha si tenga samati, ba ma si lö to''ölö ba da''ö, ba tefaduhu dödönia khöra fefu, ba tehuku ia khöra fefu,[10]', '["HalZin 2:12–13","Heb 4:12","Yes 60:14"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 25, 'ba oroma zi tobini andrö ba dödönia, ba tobali ifalögu tou ia, mangalulu ia khö Lowalangi, ba i''ombakha''ö, si ndruhu so Lowalangi ba dödömi.[11]', '["HalZin 2:12–13","Heb 4:12","Yes 60:14"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 26, 'Ba he wisa, ya''ami ira talifusö? Na owulo ami, ba oi dozi so hadia ia, ma sinunö, ba ma famahaö, ba ma famokai hadia ia, ba ma ngawalö li, ba ma famotokhi; ba fefu hadia ia, ba ba wanga''azökhi yamoguna.', '[]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 27, 'Ba na so zolau ngawalö li, ba darua, datölu zato sibai, ba nizara-zara, ba samösa zamotokhi.', '["Faigi 14:2–4"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 28, 'Ba na lö samotokhi, ba böi yamuhede ba gowuloa, ba khönia yamuhede, ba khö Lowalangi.[12]', '["Faigi 14:2–4"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 29, 'Ba sama''ele''ö, ba darua, ba ma datölu ndramuhede, ba ndramuhuku tanö bö''ö.[13]', '["Faigi 12:10; HalZin 17:11","Faigi 11:16"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 30, 'Ba na falukha danö bö''ö sidadao, wama''ele''ö, ba yamubato wehede si föföna andrö.', '["Faigi 12:10; HalZin 17:11","Faigi 11:16"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 31, 'Tola sa mizara-zara wama''ele''ö, dozi ami, ena''ö oi dozi tefahaö ira, ba ena''ö oi dozi tefarou dödö.', '["Faigi 12:10; HalZin 17:11","Faigi 11:16"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 32, 'Ba eheha zama''ele''ö andrö, ba la''o''ö ba zama''ele''ö.', '["Faigi 12:10; HalZin 17:11","Faigi 11:16"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 33, 'Tenga sa Lowalangi wamakuyu Lowalangi, no Lowalangi wa''atulö ia.[14]', '["Faigi 12:10; HalZin 17:11","Faigi 11:16"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 34, 'Ira alawe, ba böi ndrahumede ba gowuloa, si mane ba gowuloa ni''amoni''ö fefu; lö''ö sa tola fahuhuo ira, ha folo''ö khöra, si mane niŵa''ö ba goroisa göi.[15]', '["TimI 2:12; MozI 3:16"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 35, 'Ba na omasi ira, lasöndra hadia ia, ba yomo ndramusofu ba ndra matuara; lö''ö sa moadu ba ndra alawe, na fahuhuo ia ba gowuloa.', '["TimI 2:12; MozI 3:16"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 36, 'Ma ba khömi i''otarai taroma li Lowalangi andrö? ba ma ha ba khömi irugi?', '["Faigi 10:15"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 37, 'Na so zanguma''ö tödönia, sama''ele''ö ia, ba ma si so Eheha ia, ba ya''aboto ba dödönia nisuragu andre, wa moroi khö Zo''aya.[16]', '["Faigi 10:15"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 38, 'Ba na so zi lö mangila watahögö, ba yalö i''ila watahögö.', '["Faigi 10:15"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 39, 'Andrö, ya''ami ira talifusögu, mi''alui wama''ele''ö, ba böi mitenaŵa wolau ngawalö li andrö; ba fefu hadia ia,', '["Kol 2:5"]', NULL),
  (3391762, 'NT', 'Korindro I', 14, 40, 'ba oi ni''angenanöi ba oi niföfögö.[17]', '["Kol 2:5"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 1, 'Ba lö ubini''ö khömi, ya''ami ira talifusö, duria somuso dödö andrö, ni''ombakha''ögu khömi, nihalömi khömi göi, ba zaro ami göi,[1]', '["Gal 1:11–12"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 2, 'ba nisöndrami fangorifi göi, na mi''o''ö zi mane ni''ombakha''ögu khömi, na lö miböhöli; ato na zaya-zaya gölömi, wa no mamati ami.', '["Gal 1:11–12"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391763, 'NT', 'Korindro I', 15, 3, 'Da''ö sa zi a''a nifa''emagu khömi, nitemagu göi, wa no mate Keriso, börö horöda andrö; wa no itörö zi so ba zura andrö;[2]', '["Faigi 11:23; Yes 53:8 b.t.; Dan 9:26; HalZin 17:2 b.t.","Sin 16:10; Hos 6:2; Mat 12:40","Luk 24:34–36","Mat 28:10","Luk 24:50"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 4, 'awö wa no muko''o ia, awö wa no mususugi ia, me no irugi tölu ngaluo, wa no itörö zi so ba zura;[3]', '["Faigi 11:23; Yes 53:8 b.t.; Dan 9:26; HalZin 17:2 b.t.","Sin 16:10; Hos 6:2; Mat 12:40","Luk 24:34–36","Mat 28:10","Luk 24:50"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 5, 'awö wa no i''oroma''ö ia khö Gefa andrö, ba aefa da''ö, ba ba zi felendrua.[4]', '["Faigi 11:23; Yes 53:8 b.t.; Dan 9:26; HalZin 17:2 b.t.","Sin 16:10; Hos 6:2; Mat 12:40","Luk 24:34–36","Mat 28:10","Luk 24:50"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 6, 'Aefa da''ö, ba i''oroma''ö ia ba dalifusö andrö, si töra lima ngaotu, i''osamuzaigö; so sa zi no mate ösa, da''ö, ba ato zauri.[5]', '["Faigi 11:23; Yes 53:8 b.t.; Dan 9:26; HalZin 17:2 b.t.","Sin 16:10; Hos 6:2; Mat 12:40","Luk 24:34–36","Mat 28:10","Luk 24:50"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 7, 'Aefa da''ö, ba i''oroma''ö ia khö Yakobo andrö, ba aefa da''ö, ba ba zinenge andrö fefu.[6]', '["Faigi 11:23; Yes 53:8 b.t.; Dan 9:26; HalZin 17:2 b.t.","Sin 16:10; Hos 6:2; Mat 12:40","Luk 24:34–36","Mat 28:10","Luk 24:50"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 8, 'Ba ba gafuriata sibai, ba no i''oroma''ö ia göi khögu, si hulö zi lö irugi baŵa ba wa''atumbu.[7]', '["Faigi 9:1; HalZin 9:3 b.t.","Efes 3:8; TimI 1:13","TimI 1:14; KorII 5:23"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 9, 'Fondrege zide-ide sa ndra''odo, ba zinenge andrö, tenga sa si nangea labe''e töigu zinenge, me no ugohi mbanua Lowalangi andrö.[8]', '["Faigi 9:1; HalZin 9:3 b.t.","Efes 3:8; TimI 1:13","TimI 1:14; KorII 5:23"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 10, 'Ba börö wa''ebua dödö Lowalangi, wa si manö ndra''odo iada''e, ba tenga sa zaya-zaya gölö wa''ebua dödönia ba khögu andre, tobali sa ebua halöŵö nihalögu, moroi ba nihalöra fefu, ba tenga sa ya''odo, no fa''ebua dödö Lowalangi andrö, fanolo ya''odo.[9]', '["Faigi 9:1; HalZin 9:3 b.t.","Efes 3:8; TimI 1:13","TimI 1:14; KorII 5:23"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 11, 'Ba he ya''odo, ba he ya''ira andrö, ba si manö wangombakha''öma, ba si manö wamatimi.[10]', '["Faigi 3:7"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 12, 'Ba na teturiagö Keriso, wa no mususugi ia moroi ba ngai zi mate, ba hana wa so ösa ba khömi sanguma''ö, lö femaoso zi mate?[11]', '["TimII 2:17–18; Mat 22:23","TesI 4:14"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 13, 'Na lö femaoso zi mate sa, ba lö''ö göi mususugi Keriso.', '["TimII 2:17–18; Mat 22:23","TesI 4:14"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 14, 'Ba na lö mususugi Keriso, ba no zaya-zaya gölö göi wangombakha''öma, ba zaya-zaya gölö göi wamatimi.', '["TimII 2:17–18; Mat 22:23","TesI 4:14"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 15, 'Ba no tobali sasi sofaya ndra''aga ba khö Lowalangi, me no maböbögö khö Lowalangi, no isusugi Keriso si tenga nisusuginia; na duhu, lö tesusugi zi mate.', '["TimII 2:17–18; Mat 22:23","TesI 4:14"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 16, 'Na lö''ö sa tesusugi zi mate, ba lö mususugi Keriso.', '["TimII 2:17–18; Mat 22:23","TesI 4:14"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 17, 'Ba na lö mususugi Keriso, ba si lö boto wamatimi andrö, ba lö si tebulö ami ba horömi;', '["TimII 2:17–18; Mat 22:23","TesI 4:14"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 18, 'tobali si no tetiko göi zi no mate andrö, ba khö Keriso.[12]', '["TimII 2:17–18; Mat 22:23","TesI 4:14"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 19, 'Na ha ba götöda andre manötöna ita, khö Keriso, ba no numana ita, moroi ba niha bö''ö fefu.[13]', '["Faigi 15:32; 4:9","HalZin 26:23; Kol 1:18","Rom 5:12; 18:21"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 20, 'Ba iada''e, ba no mususugi Keriso, moroi ba ngai zi mate, no si a''a ia ba zi no mate andrö.[14]', '["Faigi 15:32; 4:9","HalZin 26:23; Kol 1:18","Rom 5:12; 18:21"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 21, 'Me no moroi ba niha sa wa''amate andrö, ba moroi ba niha göi wemaoso zi mate andrö.[15]', '["Faigi 15:32; 4:9","HalZin 26:23; Kol 1:18","Rom 5:12; 18:21"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 22, 'Hulö si mane ba khö Gadamo sa, wa ahori mate ira ba da''ö, si manö göi ba khö Keriso, ahori te''orifi ira dania.', '["TesI 4:15–16"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 23, 'Ba oi niföfö''ö: Si a''a, ba Keriso, ba fanetenia, ba tana khö Keriso andrö, na so ia.[16]', '["TesI 4:15–16"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 24, 'Ba awena dania gamozua andrö, na ibe''e ba danga Lowalangi Ama wamatörö andrö, na no iheta wamatörö fefu ba fa''asalaŵa fefu ba fa''abölö fefu.', '["Sin 110:1; Heb 10:12–13"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 25, 'Lö''ö sa tola lö''ö, salaŵa ia, irege no ibe''e barö gahenia zi fa''udu, fefu,[17]', '["Sin 110:1; Heb 10:12–13"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 26, 'Safuria zi fa''udu, niheta, ba ya''ia wa''amate andrö.[18]', '["Fam 20:14","Sin 8:7; Mat 28:18; Heb 2:8","Faigi 3:23; 11:3"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 27, '"Fefu hadia ia, ba no ibe''e barö gahenia." Ba na laŵa''ö, no mube''e barö mbawa fefu hadia ia, ba no ta''ila, baero zame''e barö mbawania fefu hadia ia.[19]', '["Fam 20:14","Sin 8:7; Mat 28:18; Heb 2:8","Faigi 3:23; 11:3"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 28, 'Ba na no mube''e barö mbawania fefu hadia ia, ba awena möi göi Nono barö mbawa zi no mame''e barö mbawania fefu hadia ia, ena''ö ha sambalö Lowalangi ba khöra fefu.[20]', '["Fam 20:14","Sin 8:7; Mat 28:18; Heb 2:8","Faigi 3:23; 11:3"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 29, 'Na tenga si manö, ba hadia nilau zamabayagö''ö idanö ya''ira salahi zi no mate? Na lö''ö manö tesusugi zi mate, ba hana wa lafabayagö''ö ira idanö, salahira?', '[]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 30, 'Ba ya''aga göi, ba hana wa lö mamalö-malö, wa lö ma''ila nosoma.[21]', '["Rom 8:36","KorII 1:8–9; 4:10 b.t."]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 31, 'Ero ma''ökhö matedo; ya lö usuno ndra''o ba khömi andrö, ya''ami ira talifusö, ba khö Keriso Yesu, So''aya ya''ita, na fayagu.[22]', '["Rom 8:36","KorII 1:8–9; 4:10 b.t."]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 32, 'Na dali niha, wa no fasöndra ndra''o ba gutu ndru''u andrö ba Nefeso, ba hadia gunania khögu? Na lö tesusugi zi mate, ba "datalau manga-manga ba datalau mamadu-madu hadia ia, mahemolu mate sa atö ita."[23]', '["HalZin 19:29 b.t.; Yes 22:13","TesI 5:6–8"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 33, 'Böi mibe''e nifaelungu ami. Ifakiko mböwö si sökhi huhuo si lö sökhi.', '["HalZin 19:29 b.t.; Yes 22:13","TesI 5:6–8"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 34, 'Miböhöli sibai wemabu andrö ba böi mifazökhi horö; so sa ösa zi lö aboto ba dödö Lowalangi; ba wangailasi ya''ami uŵa''ö da''ö.[24]', '["HalZin 19:29 b.t.; Yes 22:13","TesI 5:6–8"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 35, 'Ba te so zanguma''ö: ba he wisa wanusugi si mate andrö? He wisa mbotora, na so ira?[25]', '["Hes 37:3; Yes 26:19","Yoh 12:24","Faigi 12:8; MozI 1:11"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 36, 'He si lö mangila watahögö! tanömö nitarumö andrö, ba lö auri, na lö mate ua.[26]', '["Hes 37:3; Yes 26:19","Yoh 12:24","Faigi 12:8; MozI 1:11"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 37, 'Ba nitarumö andrö, ba tenga boto andrö si so dania ötaru, he sambalö ulitö, ta''ila na gandru, ba ma hadia ia mbö''önia.', '["Hes 37:3; Yes 26:19","Yoh 12:24","Faigi 12:8; MozI 1:11"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 38, 'Ba Lowalangi zame''e khönia boto, somasi ia; ba sambalö danömö, ba sambalö mboto dania.[27]', '["Hes 37:3; Yes 26:19","Yoh 12:24","Faigi 12:8; MozI 1:11"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 39, 'Lö''ö sa oi fagölö-gölö nösi hadia ia; sambua sa nösi niha, ba sambua nösi gurifö niha, ba sambua nösi wofo, ba sambua nösi gi''a.', '["Mat 22:30; HalZin 12:7"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 40, 'Ba so mboto yaŵa, ba so mboto ba guli danö, ba sambua lakhömi zi so yaŵa, ba sambua lakhömi zi so ba guli danö.[28]', '["Mat 22:30; HalZin 12:7"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 41, 'Sambua haga luo, ba sambua haga mbaŵa, ba sambua haga ndröfi; a''oi sa faehu na i wa''abölö haga ndröfi.', '["Mat 22:30; HalZin 12:7"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 42, 'Si manö göi wemaoso zi mate andrö. Sobou nitanö, ba si lö obou nisusugi.', '["Fil 3:21; Kol 3:4","MozI 2:7; Yob 19:25"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 43, 'Si lö töi nitanö, ba si so lakhömi nisusugi; si lö abölö nitanö, ba sabölö nisusugi.[29]', '["Fil 3:21; Kol 3:4","MozI 2:7; Yob 19:25"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 44, 'Boto si so noso nitanö, ba boto si so Eheha nisusugi. Na so mboto si so noso, ba so göi mboto si so Eheha.', '["Fil 3:21; Kol 3:4","MozI 2:7; Yob 19:25"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 45, 'Si manö göi ba zura: "No tobali sonoso niha si föföna andrö, Adamo", ba Adamo safuria andrö, ba no tobali Eheha sangorifi,[30]', '["Fil 3:21; Kol 3:4","MozI 2:7; Yob 19:25"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 46, 'Ba tenga si föföna zi so Eheha, si so noso zi föföna, awena zi so Eheha.', '["MozI 3:19; Yoh 3:13–31","Rom 8:29"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 47, 'Moroi ba guli danö niha si föföna andrö, tanö, ba moroi ba zorugo niha si sambua.[31]', '["MozI 3:19; Yoh 3:13–31","Rom 8:29"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 48, 'Si mane si otarai ba danö andrö, si manö fefu zi otarai ba danö, ba si mane si otarai zorugo andrö, si manö fefu mbanua zorugo;', '["MozI 3:19; Yoh 3:13–31","Rom 8:29"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 49, 'ba si mane foloheda famaedo zi otarai ba danö andrö, si manö göi dania woloheda famaedo zi otarai zorugo andrö.[32]', '["MozI 3:19; Yoh 3:13–31","Rom 8:29"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 50, 'Ba da''ö niŵa''ögu, ya''ami, ira talifusö, tebai isöndra mbanua Lowalangi ösi niha andrö, ba tebai isöndra wa lö obou sobou andrö.[33]', '["Yoh 1:13","TesI 4:15 b.t.","Mat 24:31"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 51, 'Hiza, si no tobini u''ombakha''ö khömi: Lö ahori mate ita, ba ahori tobali,[34]', '["Yoh 1:13","TesI 4:15 b.t.","Mat 24:31"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 52, 'i''ogomuzaö, ha mamö''i hörö wa''ara, na telau dorofe safuria andrö; telau sa ia dania, ba maoso zi no mate andrö, tebai sa''ae obou, ba ya''ita, ba si tobali.[35]', '["Yoh 1:13","TesI 4:15 b.t.","Mat 24:31"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 53, 'Lö''ö sa tola lö i''onukha wa tebai obou sobou andre, ba lö tola lö i''onukha wa tebai mate si mate andre.[36]', '["KorII 5:4","Yes 25:8","Hos 13:14","Rom 5:12; 13:20; 7:9 b.t.","Rom 7:25; 8:37; YohI 5:4–5"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 54, 'Ba na no i''onukha wa tebai obou sobou andre, ba na no i''onukha wa tebai mate si mate andre, ba awena itörö daroma li andrö, si so ba zura: No alömö wa''amate andrö ba wemöna.[37]', '["KorII 5:4","Yes 25:8","Hos 13:14","Rom 5:12; 13:20; 7:9 b.t.","Rom 7:25; 8:37; YohI 5:4–5"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 55, 'Hezo wemönau, fa''amate? Hezo duomö, fa''amate?[38]', '["KorII 5:4","Yes 25:8","Hos 13:14","Rom 5:12; 13:20; 7:9 b.t.","Rom 7:25; 8:37; YohI 5:4–5"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 56, 'Ba tuo wa''amate andrö, ba ya''ia horö andrö, ba fa''abölö horö andrö, ba ya''ia goroisa.[39]', '["KorII 5:4","Yes 25:8","Hos 13:14","Rom 5:12; 13:20; 7:9 b.t.","Rom 7:25; 8:37; YohI 5:4–5"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 57, 'Ba nisuno Lowalangi same''e khöda femöna andrö, moroi khö Zo''aya ya''ita andrö, Yesu Keriso.[40]', '["KorII 5:4","Yes 25:8","Hos 13:14","Rom 5:12; 13:20; 7:9 b.t.","Rom 7:25; 8:37; YohI 5:4–5"]', NULL),
  (3391763, 'NT', 'Korindro I', 15, 58, 'Andrö, ya''ami ira talifusögu, somasi ndra''o, ya''abe''e ami, si lö humeu-heu, ya''a''oi so khömi wangai halöŵö Zo''aya andrö, böi yamamalö-malö, me no mi''ila, tenga zaya-zaya gölö wa''erege dödömi andrö, ba khö Zo''aya.[41]', '["Nga''ötII 15:7; Mat 25:13; Kol 2:6–7"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 1, 'Ba ba dolo-tolo andrö, ba ni''amoni''ö andrö, ba mi''o''ö hadia nifakhoigu ba mbanua misa ba Galatia.[1]', '["KorII 8:1 b.t.; Rom 12:13; HalZin 11:29","HalZin 20:7; Fam 1:10"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 2, 'Ero migu mibe''e yaŵa ma''ifu ba da''ö, dozi ami, balazi wa''ebua nisöndra zamösana; fa böi awena la''ozaragö, na so ndra''o.[2]', '["KorII 8:1 b.t.; Rom 12:13; HalZin 11:29","HalZin 20:7; Fam 1:10"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 3, 'Ba na sodo, ba ufatenge zi tola niŵa''ömi, ufa''ohe''ö zura, ba wolohe tolo-tolomi andrö ba Yeruzalema.[3]', '["KorII 8:16-19"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 4, 'Ba na si nangea möi ndra''odo göi, ba ndramöi awögu.', '["KorII 8:16-19"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 5, 'Ba awena möido khömi, na no utörö Makedonia. Utörö sa Makedonia;[4]', '["KorII 1:16; HalZin 19:21","HalZin 20:2 b.t.","Faigi 4:19"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 6, 'ba ba khömi, ba ta''ila na arado, ma ubase''ö göi wa''aefa mbaŵa deu, ena''ö fao ami khögu, heza möido.[5]', '["KorII 1:16; HalZin 19:21","HalZin 20:2 b.t.","Faigi 4:19"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 7, 'Lö''ö sa edönado iada''e ha ba wanörö u''ila ami, udöna-döna sa, arado ma''ifu ba khömi, na itehe So''aya.[6]', '["KorII 1:16; HalZin 19:21","HalZin 20:2 b.t.","Faigi 4:19"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 8, 'Ba ba Nefeso sodo irugi luo wendrakose.', '["HalZin 14:27"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 9, 'Noa sa ebua mbawandruhö si teboka khögu ba halöŵö, ba no ato zi fa''udu.[7]', '["HalZin 14:27"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 10, 'Ba na so Dimoteo, ba mifaigi, ena''ö lö ada''u-da''u ia ba khömi; halöŵö Lowalangi sa ihalö, si mane ya''o göi.[8]', '["Faigi 4:17; Fil 2:19-20","TimI 4:12"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 11, 'Andrö, böi yamu''ositengagö ia niha, ha niha ia; ba mifasao ia, böi mibusi dödönia, ena''ö möi ia khögu; udöna-döna sa ia, awö dalifusö andrö.[9]', '["Faigi 4:17; Fil 2:19-20","TimI 4:12"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 12, 'Ba ba khö Afolo andrö, talifusö andrö, ba no uforege wangandrö khönia, ena''ö möi ia khömi, awö dalifusö andrö; ba lö''ö manö edöna ia möi iada''e, ba möi sa dania, na isöndra lala.[10]', '["Faigi 3:5-6"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 13, 'Böi miförö, mi''abe''e''ö ami wamati, si mane ira matua, ya''abölö ami![11]', '["Faigi 15:34,58; HalZin 20:31; Mat 25:13; Efes 6:10","Kol 3:14"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 14, 'Fefu hadia ia khömi, ba moroi ba wa''omasi milau.[12]', '["Faigi 15:34,58; HalZin 20:31; Mat 25:13; Efes 6:10","Kol 3:14"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 15, 'Ba u andrö khömi, ya''ami ira talifusö: no mi''ila ndra Sefana andrö, samba omo ira, wa no böröta ira ba Nakhaya, awö wa no möi ira enoni ni''amoni''ö andrö;[13]', '["Faigi 1:16"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 16, 'ena''ö mifondrondrongo li zi manö, awö li zi no manolo ba halöŵö, fefu, si no erege tödö göi.', '["Faigi 1:16"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 17, 'Ba omuso dödögu, me no so Zefana ba Fotunato ba Akha''iko, me no salahi ira ba zi lö ya''ami.[14]', '["KorII 11:9","KorII 7:13; TesI 5:12-13"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 18, 'Noa sa la''okafui dödögu ba tödömi. Andrö, böi zi lö aboto ba dödömi zi manö.[15]', '["KorII 11:9","KorII 7:13; TesI 5:12-13"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 19, 'La''owai ami banua andrö ba Azia misa. I''owai sibai ami Akila ba Ferikila, ba khö Zo''aya, awö zowulo andrö yomo khöra.[16]', '["Fam 1:4-11; HalZin 18:2 b.t."]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 20, 'La''owai ami talifusö andrö fefu. Faoma mi''owai nawömi fa''agosa bawa andrö ni''amoni''ö.[17]', '["Rom 16:16"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 21, 'Fangowaigu da''e, tangagu zanura, tanga Waulo andre.[18]', '["Kol 4:18","Gal 1:8","Rom 16:24"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 22, 'Na so zi lö mangomasi''ö So''aya andrö, ba ya anatema (ni''elifi); maranata (so dania Zo''aya).[19]', '["Kol 4:18","Gal 1:8","Rom 16:24"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 23, 'Yafalukha ami wa''ebua dödö Zo''aya ya''ita, Yesu![20]', '["Kol 4:18","Gal 1:8","Rom 16:24"]', NULL),
  (3391764, 'NT', 'Korindro I', 16, 24, 'No falukha ami fefu wa''omasigu, ba khö Keriso Yesu.', '["Kol 4:18","Gal 1:8","Rom 16:24"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 1, 'Faulo zanura da''e, sinenge Keriso Yesu andrö, moroi ba wa''omasi Lowalangi, ba Timoteo, talifusö andrö, ba mbanua Lowalangi andrö, si so ba Gorindro, awö ni''amoni''ö andrö fefu, si so ba danö Nakhaya ma''asagörö.[1]', '["KorI 1:1; 16:10,11; Fil 1:1","Gal 1:3"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 2, 'Yafalukha ami wa''ebua dödö ba fa''ohahau dödö, khö Namada, Lowalangi ba khö Zo''aya ya''ita, Yesu Keriso![2]', '["KorI 1:1; 16:10,11; Fil 1:1","Gal 1:3"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 3, 'Nisuno Lowalangi Zo''aya ya''ita, Yesu Keriso, Amania, Ama wa''ahakhö dödö andrö, Lowalangi wondrara dödö, fefu,[3]', '["FetI 1:3","Faigi 7:6; Sin 94:19","Kol 1:24"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 4, 'sondrara tödöma, ba wa''afökhö andrö fefu, khöma, ena''ö ma''ila marara dödö zi göna fa''afökhö hadia ia ngawalö, moroi ba wondrara dödö andrö, si falukha ndra''aga khö Lowalangi.[4]', '["FetI 1:3","Faigi 7:6; Sin 94:19","Kol 1:24"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 5, 'Hulö si mane famakao andrö khö Keriso, si no fahöna khöma, si manö göi wondrara dödö andrö, fahöna zi falukha ndra''aga khö Keriso.[5]', '["FetI 1:3","Faigi 7:6; Sin 94:19","Kol 1:24"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 6, 'Ba he si göna fa''afökhö ndra''aga, ba ba wondrara tödömi ba ba wangorifi ya''ami, ba he nirara tödö ndra''aga, ba ba wondrara tödömi, si möi fangabölö ba wanaha tödö, na göna ami famakao andrö, si göna ndra''aga göi. Ba no abe''e dödöma, wanötöna, ba khömi andrö,', '["FetI 1:3","Faigi 7:6; Sin 94:19","Kol 1:24"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 7, 'me no ma''ila, faoma mo''urakha ami, hulö si mane ba wamakao andrö, si manö göi ba wondrara dödö andrö.', '["FetI 1:3","Faigi 7:6; Sin 94:19","Kol 1:24"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 8, 'Ba lö edöna mabini''ö khömi, ya''ami ira talifusö, ba wa''afökhö andrö khöma, si no göna ndra''aga ba Azia, irege no abölö-bölö sibai, irege tebai mataha sa''ae, tobali lö''ö sa''ae madöna-döna auriga.[6]', '["KorI 15:32; HalZin 19:23 b.t.","TimII 3:11; 4:18"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 9, 'Na ba dödöma sa, ba no maŵa''ö si mate ndra''aga, ena''ö lö madöna-döna ba khöma, ena''ö ha ba Lowalangi andrö, sanusugi si mate, madöna-döna.', '["KorI 15:32; HalZin 19:23 b.t.","TimII 3:11; 4:18"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 10, 'No i''efa''ö ndra''aga ba wa''amate si manö, ba i''efa''ö na dania; ba khönia madöna-döna, wa itohugö na wangefa''ö ya''aga.[7]', '["KorI 15:32; HalZin 19:23 b.t.","TimII 3:11; 4:18"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 11, 'Me no sanolo ya''aga göi ami, fangandrö, ena''ö ato göi zangandrö saoha gölö ba wa''ebua dödö andrö, ni''andrö zato khöma, börö ndra''aga.[8]', '["Faigi 4:15; Rom 15:30","Heb 13:18; KorI 2:4,13; TesI 2:10","Faigi 3:2 b.t.; Fil 2:16; 4:1"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 12, 'Da''ö sa khöma, na masuno ndra''aga, wa ifaduhu''ö khöma tödöma, no ohau-hau ndra''aga, wanörö lalama ba guli danö andre, ba mendrua manö ba khömi andrö, lö si fabaya hadia ia, ibe''e Lowalangi, tenga dali wa''atua-tua nösi niha, dali wa''ebua dödö Lowalangi.[9]', '["Faigi 4:15; Rom 15:30","Heb 13:18; KorI 2:4,13; TesI 2:10","Faigi 3:2 b.t.; Fil 2:16; 4:1"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 13, 'Lö''ö sa masura khömi mbö''önia, ha nibasomi andrö ba si no aboto ba dödömi; ba udöna-döna aboto ba dödömi irugi gamozua;', '["Faigi 4:15; Rom 15:30","Heb 13:18; KorI 2:4,13; TesI 2:10","Faigi 3:2 b.t.; Fil 2:16; 4:1"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 14, 'si mane fa''aboto ba dödömi ösa ndra''aga, wa no börö wanunomi ya''ami ndra''aga, si mane ya''ami khöma, na baŵa Zo''aya ya''ita, Yesu.[10]', '["Faigi 4:15; Rom 15:30","Heb 13:18; KorI 2:4,13; TesI 2:10","Faigi 3:2 b.t.; Fil 2:16; 4:1"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 15, 'Ba me no so khögu wanötöna da''ö, ba möido mena''ö khömi föna, ena''ö samuza tö falukha ami wa''ebua dödö.[11]', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 16, 'Ba utörö ena''ö ami, we''amöi ba Makedonia, ba na u''otarai Makedonia, ba möido zui khömi, ba ena''ö mifasao ndra''odo ba Yudaia.', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 17, 'Ba hadia, me edönado da''ö hadia, no nifolau zambö era-era nilaugu? Ma na uhonogöi hadia ia, hadia tödö niha dali wangohonogöigu ya''ia, ena''ö itaria "ya''ia" ba itaria "tenga", ba khögu.[12]', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 18, 'Ba lö faröi Lowalangi, fa böi faoma lima khömi, he si no "ya''ia" ba he si "tenga".[13]', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 19, 'Ono Lowalangi andrö sa, Yesu Keriso, ni''ombakha''öma ba khömi, ya''odo ba Siliwano ba Timoteo, ba no tenga faoma, he si no "ya''ia" ba he si "tenga", no ba khönia so wa "ya''ia".[14]', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 20, 'Ha wa''oya sa gamabu''ula li Lowalangi, ba no ba khönia so wa "ya''ia", andrö wa moroi ba khönia göi wamaduhu''ö andrö, sumange Lowalangi khöma.', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391768, 'NT', 'Korindro II', 1, 21, 'Ba sangabe''e ya''aga ba ya''ami, ba khö Keriso, ba ya''ia Lowalangi, si no mamayoini ya''ita göi;[15]', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 22, 'si no manga''aro''ö göi ya''ita, si no mame''e we''e-we''e dödö andrö, Eheha andrö, ba dödöda.[16]', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 23, 'Ba u''angaröfi Lowalangi, ba nosogu andre, wa no börö wa alimagö ami khögu, wa lö si möido sa''ae khömi ba Gorindro.[17]', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391768, 'NT', 'Korindro II', 1, 24, 'Tenga sa laŵa''ö amatöröŵama wamatimi andrö, ba no sanolo ndra''aga ena''ö falukha ami wa''omuso dödö; noa sa abe''e ami wamati.[18]', '["KorI 16:5 b.t.","Yak 5:12","KorI 1:9","TesI 1:1; Fam 3:14","YohI 2:27","Faigi 5:5; Efes 1:13,14","Faigi 12:20,21","Faigi 4:5; FetI 5:3; Fil 1:25"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 1, 'Ba no uhonogöi tödögu da''ö, böi ifuli abu dödögu, na möido khömi.[1]', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 2, 'Na ubusi dödömi, ba ha niha zangomosoi''ö tödögu, na tenga nibusigu tödö andrö?', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 3, 'Ba no usura da''ö khömi, fa lö abu dödögu, na möido, labe''e somuso dödögu ena''ö; me no udöna-döna ba khömi fefu, wa fa''omuso dödömi fefu wa''omuso dödögu andrö.[2]', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 4, 'Noa sa a''oi so wa''afökhö khögu, awö wa''atosasa dödögu, me ufa''ohe''ö zura andrö khömi, tenga ha ma''ifu mowöi daŵa hörögu; tenga sa ena''ö abu dödömi, ena''ö aboto ba dödömi wa''omasi andrö, si so khögu; wa no abölö omasido ami, moroi ba niha bö''ö.[3]', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 5, 'Ba na so zi no mamusi tödö nawönia, ba tenga ya''o nibusinia tödö, ya''ami fefu — fa böi abölö-bölö wanguma''ögu — ba ya''ami ösa.[4]', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 6, 'Ba no abönö ba zi manö wotu andrö, me no ato zangotu''ö ya''ia.[5]', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 7, 'Tola mibalia''ö sa''ae, mibe''e aefa khönia ba mirara dödönia, fa böi tehawu zi manö fa''abu dödö, na no abölö-bölö sibai.', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 8, 'Andrö u''andrö khömi, mifatörö khönia wa''omasi.', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 9, 'Andrö sa göi ufa''ohe''ö zura khömi, ena''ö u''ila, na tola ami, na mi''o''ö fefu hadia ia.', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 10, 'Ba na so niha ni''efa''ömi hadia ia, ba ya''odo göi, u''efa''ö göi. Ya''o sa göi, hadia ni''efa''ögu, na so ni''efa''ögu, ba börö ami, ba zanehe Keriso,[6]', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 11, 'ena''ö lö i''alani ita Satana; tenga sa fa lö aboto ba dödöda gera-erania.', '["Faigi 12, 21","KorI 5","Faigi 7:8 b.t.","KorI 5:1,2","Faigi 7:11; KorI 5:5","Yoh 20:23"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 12, 'Ba me no urugi Deroa, ba wangombakha turia somuso dödö andrö khö Keriso, ba me no teboka khögu mbawandruhö ba khö Zo''aya,[7]', '["HalZin 20:6; KorI 16:9","Faigi 7:5,6","KorI 15:57; Efes 3:8 b.t.","KorI 1:18","Luk 2:34; Rom 1:16; Yoh 3:17,18","Faigi 4:2"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 13, 'ba lö''ö sa ahono bakha dödögu, me lö usöndra Dito andrö, talifusögu; ba u''angonasi ira ba usaŵa Makedonia.[8]', '["HalZin 20:6; KorI 16:9","Faigi 7:5,6","KorI 15:57; Efes 3:8 b.t.","KorI 1:18","Luk 2:34; Rom 1:16; Yoh 3:17,18","Faigi 4:2"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 14, 'Ba u''andrö saoha gölö khö Lowalangi, same''e möna ya''aga, si lö mamalö-malö, ba khö Keriso, sama''oroma''ögö hua wa''aboto ba dödö ia andrö, khöma, fefu gofu heza.[9]', '["HalZin 20:6; KorI 16:9","Faigi 7:5,6","KorI 15:57; Efes 3:8 b.t.","KorI 1:18","Luk 2:34; Rom 1:16; Yoh 3:17,18","Faigi 4:2"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 15, 'Fa''amohua khö Keriso sa ndra''aga, khö Lowalangi, ba ni''orifi andrö ba ba zi tetibo andrö.[10]', '["HalZin 20:6; KorI 16:9","Faigi 7:5,6","KorI 15:57; Efes 3:8 b.t.","KorI 1:18","Luk 2:34; Rom 1:16; Yoh 3:17,18","Faigi 4:2"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 16, 'Ba nitibo''ö andrö, ba hua soroi ba wa''auri si saŵa fa''amate, ba ba ni''orifi andrö, ba hua soroi ba wa''auri si saŵa fa''auri. Ba ha niha zogamö da''ö?[11]', '["HalZin 20:6; KorI 16:9","Faigi 7:5,6","KorI 15:57; Efes 3:8 b.t.","KorI 1:18","Luk 2:34; Rom 1:16; Yoh 3:17,18","Faigi 4:2"]', NULL),
  (3391769, 'NT', 'Korindro II', 2, 17, 'Tenga sa si mane sato andrö, samali''ö faniaga taroma li Lowalangi andrö, ndra''aga; fehedema, ba moroi ba zi lö fabaya hadia ia, moroi ba Lowalangi, föna Lowalangi, ba khö Keriso.[12]', '["HalZin 20:6; KorI 16:9","Faigi 7:5,6","KorI 15:57; Efes 3:8 b.t.","KorI 1:18","Luk 2:34; Rom 1:16; Yoh 3:17,18","Faigi 4:2"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 1, 'Hadia, mabörötaigö zui wamaduhu''ö ya''aga? Moguna khöma zura wamaduhu''ö, nifa''ohe''ö khömi, ba ma nifa''ohe''ömi, si mane ba danö bö''ö ösa?[1]', '["Faigi 5:12; 11:13 b.t.","Faigi 7:3","Yer 31:33; Hes 11:19; Heb 8:10","Fil 2:13","Faigi 5:18; Yoh 6:63; Rom 7:10"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 2, 'Surama ami, nisura ba dödöma bakha, si no aboto ba dödö niha fefu, nibaso-basora.[2]', '["Faigi 5:12; 11:13 b.t.","Faigi 7:3","Yer 31:33; Hes 11:19; Heb 8:10","Fil 2:13","Faigi 5:18; Yoh 6:63; Rom 7:10"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 3, 'No oroma, wa sura Keriso ami, nisurama, halöŵöma; tenga taŵa wanura ya''ia, Eheha Lowalangi sauri andrö wanura ya''ia, tenga ba gara wanura andrö, no ba kara nagole, ba dödö.[3]', '["Faigi 5:12; 11:13 b.t.","Faigi 7:3","Yer 31:33; Hes 11:19; Heb 8:10","Fil 2:13","Faigi 5:18; Yoh 6:63; Rom 7:10"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 4, 'Ba no so khöma wanötöna si manö, moroi khö Keriso, ba khö Lowalangi;', '["Faigi 5:12; 11:13 b.t.","Faigi 7:3","Yer 31:33; Hes 11:19; Heb 8:10","Fil 2:13","Faigi 5:18; Yoh 6:63; Rom 7:10"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 5, 'tenga sa taŵa''ö tola manö ndra''aga, na moroi khöma, ba wamaböbö tödöma hadia ia, hulö na tödöma manö; hadia zi tola ndra''aga, ba no moroi ba Lowalangi,[4]', '["Faigi 5:12; 11:13 b.t.","Faigi 7:3","Yer 31:33; Hes 11:19; Heb 8:10","Fil 2:13","Faigi 5:18; Yoh 6:63; Rom 7:10"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 6, 'si no manolo göi ya''aga, ena''ö tola enoni ndra''aga ba gamabu''ula li si bohou andrö, tenga ba dandra zura andrö, no ba khö Geheha; famunu sa dandra zura andrö, ba Eheha andrö, ba sangorifi.[5]', '["Faigi 5:12; 11:13 b.t.","Faigi 7:3","Yer 31:33; Hes 11:19; Heb 8:10","Fil 2:13","Faigi 5:18; Yoh 6:63; Rom 7:10"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 7, 'Ba na no molakhömi halöŵö ba wamunu andrö, ba dandra zura andrö, nisura ba gara, na no tobali tebai latöngö mbawa Moze Iraono Gizeraeli andrö, ba wa''amohaga mbawania, si taya sa atö;[6]', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 8, 'ba tenga mendrua manö molakhömi halöŵö ba khö Geheha andrö?', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 9, 'Na molakhömi sa''ae halöŵö ba wanibo andrö, ba mendrua manö, wa no a''oi so lakhömi halöŵö ba wangatulö andrö?[7]', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 10, 'Tobali si lö mufolakhömi sa "nifolakhömi" andrö, ba da''ö, börö lakhömi andrö, si no a''oi so.', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 11, 'Na molakhömi sa''ae zi taya andrö, ba mendrua manö molakhömi zi lö tebulö andrö.[8]', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 12, 'Ba me no so khöma wanötöna si manö, ba no a''oi so wa lö aiŵö ndra''aga.', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 13, 'Ba tenga si mane Moze, sombalugö bawania, fa böi lafaigi Iraono Gizeraeli andrö gamozua zi taya andrö.[9]', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 14, 'Ba no mu''abe''e''ö dödöra; irugi ma''ökhö andre, ba lö saheta mbalu-balu andrö, ba wombaso sura gamabu''ula li si föföna andrö, lö muheta, me ba khö Keriso aheta ia.[10]', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 15, 'Ba irege ma''ökhö andre, na labaso zura Moze andrö, ba no so mbalu-balu ba dödöra.', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 16, 'Ba na lafuli ira khö Zo''aya, ba aheta mbalu-balu andrö.[11]', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 17, 'Ba So''aya Geheha andrö; ba ba zi so Eheha Zo''aya andrö, ba da''ö so wangefa.[12]', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391770, 'NT', 'Korindro II', 3, 18, 'Ba ya''ita fefu, ba ta''ila-ila lakhömi Zo''aya andrö, lö balu-balu mbawada; hulö na ba zörömi, ba tobali ita, i''ohia''ö wamaedo da''ö, tedou lakhömi safuria moroi ba lakhömi si föföna, moroi khö Geheha Zo''aya andrö.[13]', '["MozII 34:1; 29:30","Faigi 5:19–21; Gal 3:10","Heb 7:21 b.t.","MozII 34:33 b.t.","Rom 11:25; Yes 6:10; 29:11,12","Rom 11:23","KorI 15:45; Yoh 4:24; 8:36","KorI 13:12; Rom 8:29"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 1, 'Andrö: me no mufataro ndra''aga ba halöŵö andrö, dali wa''ahakhö dödö andrö, si no falukha ndra''aga, ba lö ma''ila wa''ata''u;[1]', '["Faigi 3:6; TimI 13:16","Faigi 2:17; 5:11","Faigi 2:15,16","Efes 2:2; Yoh 12:31; 14:9; Heb 1:3","Faigi 1:24; 5:20","MozI 1:3; FetII 1:19; Efes 1:18 b.t."]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 2, 'noa sa matimba wamini andrö, ba wa''aila andrö, me lö matörö walimosa, ba me lö mafuyu''ö daroma li Lowalangi; mafaduhu''ö ndra''aga ba dödö niha fefu, föna Lowalangi, wama''ele''ö si duhu andrö.[2]', '["Faigi 3:6; TimI 13:16","Faigi 2:17; 5:11","Faigi 2:15,16","Efes 2:2; Yoh 12:31; 14:9; Heb 1:3","Faigi 1:24; 5:20","MozI 1:3; FetII 1:19; Efes 1:18 b.t."]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 3, 'Ba na no tobalu göi duria somuso dödö andrö, khöma ba ba zi tetibo andrö tobalu ia,[3]', '["Faigi 3:6; TimI 13:16","Faigi 2:17; 5:11","Faigi 2:15,16","Efes 2:2; Yoh 12:31; 14:9; Heb 1:3","Faigi 1:24; 5:20","MozI 1:3; FetII 1:19; Efes 1:18 b.t."]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 4, 'ba nimbaŵainö Lowalangi zi sagötö tanö andre era-era, era-era zi lö mamati, fa lö ihagaini ira haga duria somuso dödö andrö, turia lakhömi Keriso andrö, si no famaedo Lowalangi.[4]', '["Faigi 3:6; TimI 13:16","Faigi 2:17; 5:11","Faigi 2:15,16","Efes 2:2; Yoh 12:31; 14:9; Heb 1:3","Faigi 1:24; 5:20","MozI 1:3; FetII 1:19; Efes 1:18 b.t."]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 5, 'Tenga sa ya''aga ni''ombakha''öma, no Keriso Yesu, So''aya, ma''ombakha''ö, ba ya''aga, ba enonimi, maŵa''ö, börö Yesu.[5]', '["Faigi 3:6; TimI 13:16","Faigi 2:17; 5:11","Faigi 2:15,16","Efes 2:2; Yoh 12:31; 14:9; Heb 1:3","Faigi 1:24; 5:20","MozI 1:3; FetII 1:19; Efes 1:18 b.t."]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 6, 'Lowalangi andrö sa, sanguma''ö; yatumbu haga andrö ba zogömi-gömi, da''ö zamatumbu''ö ba dödöma haga andrö, ena''ö humaga wa''aboto ba dödö lakhömi Lowalangi andrö, ba mbawa Keriso.[6]', '["Faigi 3:6; TimI 13:16","Faigi 2:17; 5:11","Faigi 2:15,16","Efes 2:2; Yoh 12:31; 14:9; Heb 1:3","Faigi 1:24; 5:20","MozI 1:3; FetII 1:19; Efes 1:18 b.t."]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 7, 'Ba ba nahia tanö so khöma girö-girö andrö, ena''ö khö Lowalangi, wa no fahöna wa''abölö, ba böi moroi ba khöma.[7]', '["Faigi 5:1","Faigi 1:8; 6:4,5","Mat 5:10","KorI 15:31; Gal 6:17; Rom 6:8","Rom 8:36; KorI 4:9"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 8, 'Fefu gofu heza, ba no mufalangögö ndra''aga, ba tenga sa nimama; nibusi tödö ndra''aga, ba so zui lala dödö;[8]', '["Faigi 5:1","Faigi 1:8; 6:4,5","Mat 5:10","KorI 15:31; Gal 6:17; Rom 6:8","Rom 8:36; KorI 4:9"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 9, 'nigohi, ba tenga niröi; nitibo''ö tou, ba tenga nifakiko;[9]', '["Faigi 5:1","Faigi 1:8; 6:4,5","Mat 5:10","KorI 15:31; Gal 6:17; Rom 6:8","Rom 8:36; KorI 4:9"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 10, 'lö aefa ba mbotoma wamunu Yesu andrö, ma''ohe-ohe, ena''ö te''oroma''ö göi wa''auri Yesu andrö, ba mbotoma andre.[10]', '["Faigi 5:1","Faigi 1:8; 6:4,5","Mat 5:10","KorI 15:31; Gal 6:17; Rom 6:8","Rom 8:36; KorI 4:9"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 11, 'Lö aetu sa tefatörö ndra''aga ba wamunu, ya''aga sauri andre, börö Yesu, ena''ö tefa''ele''ö göi wa''auri Yesu andrö, ba nösima andre, si mate.[11]', '["Faigi 5:1","Faigi 1:8; 6:4,5","Mat 5:10","KorI 15:31; Gal 6:17; Rom 6:8","Rom 8:36; KorI 4:9"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 12, 'Tobali ba khöma abölö wa''amate, ba ba khömi, ba fa''auri zabölö.[12]', '["Faigi 13:9","Sin 116:10","KorI 6:14; Rom 8:11","Faigi 1:6,11; Sin 50:23; Kol 1:24","Efes 3:16","Rom 8:17,18; FetI 1:6 b.t.","Rom 8:24; Heb 10:34; 11:1,26"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 13, 'Ba me no so khöma Geheha wamati andrö, si mane si so ba zura: No mamati ndra''o, andrö humede ndra''o, ba mamati ndra''aga göi, ba andrö muhedega göi.[13]', '["Faigi 13:9","Sin 116:10","KorI 6:14; Rom 8:11","Faigi 1:6,11; Sin 50:23; Kol 1:24","Efes 3:16","Rom 8:17,18; FetI 1:6 b.t.","Rom 8:24; Heb 10:34; 11:1,26"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 14, 'Me no ma''ila, si no manusugi Yesu, So''aya ya''ita, ba isusugi göi ndra''aga dania, awö Yesu, ba ifa''aso ndra''aga, awömi.[14]', '["Faigi 13:9","Sin 116:10","KorI 6:14; Rom 8:11","Faigi 1:6,11; Sin 50:23; Kol 1:24","Efes 3:16","Rom 8:17,18; FetI 1:6 b.t.","Rom 8:24; Heb 10:34; 11:1,26"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 15, 'Börö sa ami, ba da''ö fefu, ena''ö amaedola zi tedou-dou na wa''ebua dödö (Lowalangi) andrö, ba ena''ö fahöna; wangandrö saoha gölö, ena''ö ato zangandrö, ba wamolakhömi Lowalangi.[15]', '["Faigi 13:9","Sin 116:10","KorI 6:14; Rom 8:11","Faigi 1:6,11; Sin 50:23; Kol 1:24","Efes 3:16","Rom 8:17,18; FetI 1:6 b.t.","Rom 8:24; Heb 10:34; 11:1,26"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 16, 'Andrö lö ma''ila wa''ata''u, he ŵa''ae tekiko mbotoma andre, ba tebohouni niha bakha, ero ma''ökhö.[16]', '["Faigi 13:9","Sin 116:10","KorI 6:14; Rom 8:11","Faigi 1:6,11; Sin 50:23; Kol 1:24","Efes 3:16","Rom 8:17,18; FetI 1:6 b.t.","Rom 8:24; Heb 10:34; 11:1,26"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 17, 'Famakaoda andrö sa, si lö arara, si lö abölö-bölö, ba i''a''asogö khöda lakhömi sebua, si lö aetu, irege fahöna;[17]', '["Faigi 13:9","Sin 116:10","KorI 6:14; Rom 8:11","Faigi 1:6,11; Sin 50:23; Kol 1:24","Efes 3:16","Rom 8:17,18; FetI 1:6 b.t.","Rom 8:24; Heb 10:34; 11:1,26"]', NULL),
  (3391771, 'NT', 'Korindro II', 4, 18, 'me lö tefaigi zoroma andrö, ha si lö oroma. Soroma sa, ba lö arara, ba si lö oroma, ba irugi zi lö aetu.[18]', '["Faigi 13:9","Sin 116:10","KorI 6:14; Rom 8:11","Faigi 1:6,11; Sin 50:23; Kol 1:24","Efes 3:16","Rom 8:17,18; FetI 1:6 b.t.","Rom 8:24; Heb 10:34; 11:1,26"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 1, 'Noa sa ma''ila, na tedudugö nahama andre, ba guli danö, ose andre, ba so khöma ni''otomosi Lowalangi, omo, si tenga nifazökhi tanga, si lö tebulö, ba zorugo.[1]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 2, 'Ba da''ö sa göi mangarö-ngaröga, humulu dödöma, ena''ö tefonukha ndra''aga nahama andrö, soroi ba zorugo;[2]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 3, 'me tenga sa si lö nukha ndra''aga, wamaigi ya''aga, na no ma''onukha ia.[3]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 4, 'Andrö mangarö-ngaröga, ya''aga si so ba nose andrö, sonoro ndra''aga, me lö omasiga, na aheta nukhama, me omasiga na tefalaete, ena''ö i''a fa''auri andrö zi mate andrö.[4]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 5, 'Ba sangehao ya''aga ba da''ö, ba ya''ia Lowalangi, si no mame''e khöma we''e-we''e dödö andrö, Eheha andrö.[5]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 6, 'Andrö wa lö mamalö-malö wa''arara dödöma, ba no mi''ila, na ba mboto soga, ba no aröu ndra''aga khö Zo''aya, no sikoli ndra''aga.[6]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 7, 'Lala wamati sa lalama, ba tenga famaigi.[7]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 8, 'Ba no arara dödöma, ba abölö omasiga awu''a ndra''aga, maröi mboto, ba ahono ndra''aga khö Zo''aya.[8]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 9, 'Andrö göi maforege, he sahono ndra''aga yomo, ba he sikoli, ena''ö omasi ia ndra''aga.[9]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 10, 'Lö''ö sa tola lö oroma dania ita fefu föna dadaoma ba wanguhuku andrö khö Keriso, ena''ö itema zamösana zulö nilaunia, me ba mboto, so ia, he si sökhi, ba he si lö sökhi.[10]', '["FetII 1:13,14; Heb 9:11; 11:10","Rom 8:23","Mat 22:11; Efes 4:24; Fam 3:18","Rom 8:19,22; KorI 15:51–53","Faigi 1:22; Rom 8:14","Heb 13:14","KorI 13:12,13; FetI 1:8","Fil 1:23","Kol 1:10 b.t.","Rom 14:10; KorI 4:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 11, 'Ba me no aboto ba dödöda wangata''ufi So''aya, ba tadönisi niha; ba noa sa oroma ita khö Lowalangi, ba udöna-döna, ba dödömi göi oroma ndra''o.[11]', '["KorI 9:20; KorII 4:2","Faigi 3:1; 10:12","Rom 6:3 b.t.","Rom 14:7 b.t.","Rom 8:1; Gal 6:15; Fam 21:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 12, 'Lö''ö sa mafuli mafaduhu''ö ndra''aga khömi, ba mafobörö khömi wanuno ya''ami ba khöma andre, ena''ö so khömi wanuno, ba zanuno ya''ira ba zoroma ba niha, ba tenga ba zi so ba dödö.[12]', '["KorI 9:20; KorII 4:2","Faigi 3:1; 10:12","Rom 6:3 b.t.","Rom 14:7 b.t.","Rom 8:1; Gal 6:15; Fam 21:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 13, 'Na sowöhö ndra''aga, ba no khö Lowalangi owöhöga, ba na si so era-era ndra''aga, ba ba khömi.', '["KorI 9:20; KorII 4:2","Faigi 3:1; 10:12","Rom 6:3 b.t.","Rom 14:7 b.t.","Rom 8:1; Gal 6:15; Fam 21:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 14, 'Fa''omasi Keriso andrö sa zango''ou ya''aga.[13]', '["KorI 9:20; KorII 4:2","Faigi 3:1; 10:12","Rom 6:3 b.t.","Rom 14:7 b.t.","Rom 8:1; Gal 6:15; Fam 21:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 15, 'Da''ö niŵa''öma: Na no mate zamösa, salahi zato fefu, ba no ahori mate ira fefu. Ba no mate ia salahi zato fefu, ena''ö tenga sa''ae khöra auri zauri, ena''ö khö zi mate salahira, khö nisusugi andrö, salahira, auri ira.[14]', '["KorI 9:20; KorII 4:2","Faigi 3:1; 10:12","Rom 6:3 b.t.","Rom 14:7 b.t.","Rom 8:1; Gal 6:15; Fam 21:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 16, 'Tobali, i''otarai da''e, ba lö''ö sa''ae ma''ila niha, na dali mboto. Ba he no ma''ila Keriso, dali mboto, ba lö''ö sa''ae ma''ila ia iada''e.', '["KorI 9:20; KorII 4:2","Faigi 3:1; 10:12","Rom 6:3 b.t.","Rom 14:7 b.t.","Rom 8:1; Gal 6:15; Fam 21:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 17, 'Tobali na ba khö Keriso so niha, ba no si bohou mufazökhi ia, no numalö zi tohöna andrö, ba hiza, ba no tobali bohou.[15]', '["KorI 9:20; KorII 4:2","Faigi 3:1; 10:12","Rom 6:3 b.t.","Rom 14:7 b.t.","Rom 8:1; Gal 6:15; Fam 21:5"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 18, 'Ba fefu da''ö, ba moroi ba Lowalangi, si no mangatulö''ö ya''ita khönia, ba khö Yesu Keriso, si no mame''e göi khöda halöŵö fangatulö andrö.[16]', '["Rom 5:10","Yoh 14:10; Rom 3:24 b.t.; Kol 1:19,20; YohI 2:2","Yes 52:7; Yoh 20:21","FetI 2:22 b.t.; 3:18; Gal 3:13; Rom 8:3,4"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 19, 'Lowalangi sa zi no mangatulö''ö khönia ösi guli danö, ba khö Keriso, lö ibe''e ömöra lalöra andrö, ba no ibe''e ba dödöma daroma li andrö, ba wangatulö andrö.[17]', '["Rom 5:10","Yoh 14:10; Rom 3:24 b.t.; Kol 1:19,20; YohI 2:2","Yes 52:7; Yoh 20:21","FetI 2:22 b.t.; 3:18; Gal 3:13; Rom 8:3,4"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 20, 'Ba no sinenge ndra''aga, salahi Keriso, hulö na Lowalangi zamarou tödö niha, ba lima andrö, mangandrö ndra''aga, salahi Keriso, mamane: Mifa''atulö''ögö ami khö Lowalangi![18]', '["Rom 5:10","Yoh 14:10; Rom 3:24 b.t.; Kol 1:19,20; YohI 2:2","Yes 52:7; Yoh 20:21","FetI 2:22 b.t.; 3:18; Gal 3:13; Rom 8:3,4"]', NULL),
  (3391772, 'NT', 'Korindro II', 5, 21, 'Noa sa ibali''ö horö zi lö irai mangila horö, salahida, ena''ö tobali fa''atulö khö Lowalangi ita, ba khönia andrö.[19]', '["Rom 5:10","Yoh 14:10; Rom 3:24 b.t.; Kol 1:19,20; YohI 2:2","Yes 52:7; Yoh 20:21","FetI 2:22 b.t.; 3:18; Gal 3:13; Rom 8:3,4"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 1, 'Ba ma''andrö khömi, ya''aga sanolo ba halöŵö andrö, böi saekhu ba danö, me no falukha ami wa''ebua dödö Lowalangi andrö.[1] —', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 2, 'Noa sa imane: "No ufondrondrongo khöu, me baŵa si sökhi, ba no utolo''ö, me luo wangorifi. "Hiza, iya''e mbaŵa si sökhi, hiza, iya''e luo wangorifi andrö.[2] —', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 3, 'Lö''ö sa mafobörö wangala hadia ia, gofu ha ökhö, fa böi te''o''aya halöŵö andrö.', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 4, 'Fefu hadia ia nilauma sa, ba no amuata genoni Lowalangi gamuatama, ba wanaha tödö, si no a''oi so, ba ba wa''afökhö, ba ba wa''atosasa, ba ba wa''ata''u dödö,[3]', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 5, 'ba na labözi ndra''aga, ba na lakuruga, ba na molaŵa niha, ba ba wa''erege dödö, ba ba wa lö mörö, ba ba wa lö si manga,[4]', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 6, 'ba ba wa''ohau-hau, ba ba wa''aboto ba dödö, ba ba wa''ebolo dödö, ba wa''asökhi dödö, ba ba khö Geheha ni''amoni''ö, ba ba wa''omasi andrö, si lö famini tödö,', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 7, 'ba daroma li fa''aduhu andrö, ba ba wa''abölö Lowalangi andrö, moroi ba wangöna fa''atulö dödö andrö, he ba gambölö, ba he ba gabera;[5]', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 8, 'He falukha zumange, ba he fango''aya, he laböbögö zi lö sökhi, ba he lasuno ndra''aga; hulö zamaelungu, ba no si duhu;', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 9, 'hulö zi lö aboto ba dödö niha, ba noa sa aboto ba dödö niha bö''ö; hulö zi mate, ba hiza, ba sauri ndra''aga; hulö ni''otu''ö ba lö''ö sa mubunu;[6]', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 10, 'hulö zabu tödö, ba lö''ö sa mamalö-malö wa''omuso dödö; hulö zi numana, ba ato nifo''ana''ama; hulö niha si lö''ö, ba no a''oi so khöma.[7]', '["Faigi 1:24; Heb 12:15","Yes 49:8; Heb 3:7,13","Faigi 4:8 b.t.","Faigi 11:23–27; HalZin 19:29; 21:30","TimII 2:15; Rom 15:19","Faigi 4:10,11; Sin 118:17,18","Faigi 12:10; 8:9; Kor 3:21"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 11, 'No alua baeha lima khömi, ya''ami banua Gorindro, no ibologö ia tödöma.', '["Efes 5:11","RazI 18:21","KorI 3:16; MozIII 26:11,12","Yes 52:11; Fam 18:4; MozIV 16:29","Yer 31:33; 32:38; Yoh 1:12"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 12, 'Lö ambö nahami ba dödöma ba no ide-ide dödömi.', '["Efes 5:11","RazI 18:21","KorI 3:16; MozIII 26:11,12","Yes 52:11; Fam 18:4; MozIV 16:29","Yer 31:33; 32:38; Yoh 1:12"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 13, 'Ba misulöni — hulö wehede ba ndraono wehedegu khömi — mi''ebolo''ö dödömi göi.', '["Efes 5:11","RazI 18:21","KorI 3:16; MozIII 26:11,12","Yes 52:11; Fam 18:4; MozIV 16:29","Yer 31:33; 32:38; Yoh 1:12"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 14, 'Böi mitolo ba nilau zi lö mamati andrö. Hadia, faböbö ira wa''atulö wa lö atulö? Ba hadia, awö haga zogömi-gömi?[8]', '["Efes 5:11","RazI 18:21","KorI 3:16; MozIII 26:11,12","Yes 52:11; Fam 18:4; MozIV 16:29","Yer 31:33; 32:38; Yoh 1:12"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 15, 'Hadia, no faudu ira Keriso Mbeliali? Ba hezo zi faoma mo''urakha ira, zamati zi lö mamati?[9]', '["Efes 5:11","RazI 18:21","KorI 3:16; MozIII 26:11,12","Yes 52:11; Fam 18:4; MozIV 16:29","Yer 31:33; 32:38; Yoh 1:12"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 16, 'Hadia faböbö ira gosali Lowalangi nadu? Osali Lowalangi sauri sa ami, si mane niŵa''ö Lowalangi: "Ba khöra ube''e nahagu, ba udörö-döröi ira, ba Lowalangira ndra''o, ba banuagu ira.[10]', '["Efes 5:11","RazI 18:21","KorI 3:16; MozIII 26:11,12","Yes 52:11; Fam 18:4; MozIV 16:29","Yer 31:33; 32:38; Yoh 1:12"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 17, 'Andrö miheta ami khöra, mifabali ami, iŵa''ö So''aya, ba böi mibabaya zi ra''i-ra''iö; ba utema ami,[11]', '["Efes 5:11","RazI 18:21","KorI 3:16; MozIII 26:11,12","Yes 52:11; Fam 18:4; MozIV 16:29","Yer 31:33; 32:38; Yoh 1:12"]', NULL),
  (3391773, 'NT', 'Korindro II', 6, 18, 'ba amami ndra''o, ba onogu matua ami ba onogu alawe, iŵa''ö So''aya andrö, si lö ambö fa''abölö."[12]', '["Efes 5:11","RazI 18:21","KorI 3:16; MozIII 26:11,12","Yes 52:11; Fam 18:4; MozIV 16:29","Yer 31:33; 32:38; Yoh 1:12"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 1, 'Ba me no so khöda gamabu''ula li si manö, ya''ami ni''omasi''ö! ba datahaogö ita, taheta fefu zi no tokana andrö, he ba nösi, ba he ba dödö, ba wamalua fangohau-hau andrö; ta''ata''ufi Lowalangi.[1]', '["Faigi 6:17; YohI 3:3"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 2, 'Mifondrondrongo khöma; lö nilauma si lö sökhi ba niha, lö nifakikoma niha, lö ni''alanima.[2]', '["Faigi 12:17","Faigi 6:11–13","Fil 2:17","Faigi 4:8","Faigi 1:4; 2:13","TesI 3:6–8"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 3, 'Tenga fangetu''ö huku, wa uŵa''ö da''ö. Noa sa uŵa''ö mege, ba dödöma so ami, he ba wa''amate, ba he ba wa''auri, awöma.[3]', '["Faigi 12:17","Faigi 6:11–13","Fil 2:17","Faigi 4:8","Faigi 1:4; 2:13","TesI 3:6–8"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 4, 'No abe''e sibai dödögu ami, oi so wanunogu ya''o, ba khömi andrö; no fahöna wondrara dödö khögu, oi so wa''omuso dödögu, ba wa''afökhö andrö fefu khöma.[4]', '["Faigi 12:17","Faigi 6:11–13","Fil 2:17","Faigi 4:8","Faigi 1:4; 2:13","TesI 3:6–8"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391774, 'NT', 'Korindro II', 7, 5, 'Me no marugi Makedonia sa, ba ma''ifu lö folombase mbotoma, no fahöna manö zafökhö, fasosota baero, ba bakha ba dödö, ba fa''ata''u.[5]', '["Faigi 12:17","Faigi 6:11–13","Fil 2:17","Faigi 4:8","Faigi 1:4; 2:13","TesI 3:6–8"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 6, 'Ba sondrara tödö zi numana, Lowalangi, da''ö zondrara tödöma, ba wa''aso Dito andrö.[6]', '["Faigi 12:17","Faigi 6:11–13","Fil 2:17","Faigi 4:8","Faigi 1:4; 2:13","TesI 3:6–8"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 7, 'Ba tenga ha ba wa''asonia, ba wondrara tödö andrö göi, si no falukha ia khömi, me i''ombakha''ö khöma wehulu dödömi andrö ba fangarö-ngarömi ba fa''owölö-ölömi, ba khögu andre; tobali no tedou na wa''omuso dödögu.[7]', '["Faigi 12:17","Faigi 6:11–13","Fil 2:17","Faigi 4:8","Faigi 1:4; 2:13","TesI 3:6–8"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 8, 'Ba he sa no ubusi dödömi ba zura andrö, ba lö''ö sa mangesa dödögu. Ba he no mangesa dödögu — u''ila sa, wa no abu dödömi, ba zura andrö, he lö arara[8] —', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 9, 'ba iada''e, ba no omuso dödögu, tenga sa me no abu dödömi, me no abu dödömi ba wamalalini era-era a''ine, dali sa Lowalangi, wa abu dödömi, ena''ö lö hadia ia zi te''ala ami khöma.', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 10, '''Lua-lua wa''abu dödö andrö sa, na dali Lowalangi, ba famalalini era-era, ba wangorifi ba mbanua furi, si lö mangesa dödö sa''ae, ba lua-lua wa''abu dödö niha guli danö andrö, ba fa''amate.[9]', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 11, 'Hiza sa da''ö, wa no abu dödömi, dali Lowalangi, he wisa wamarounia tödömi, ba wamu''a sa''ae, ba ba wofönu, ba ba wa''ata''u, ba ba wehulu dödö, ba ba wamorege, ba ba wangotu''ö! Gofu hadia ia, niŵa''öda, ba no mi''oroma''ö, wa lö esuanö khömi ba da''ö.', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 12, 'Ba he no ufa''ohe''ö zura khömi, ba no tenga börö zi so sala andrö, ba tenga börö ba zosala ia, da''ö mbörö, ena''ö oroma ba khömi, föna Lowalangi, wa no soso dödömi ndra''aga.[10]', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 13, 'Andrö no falukha ndra''aga wondrara dödö. Ba noa na möi fonönö wondrara dödöma wa''omuso dödöma andrö, si no fahöna, moroi ba wa''omuso dödö Dito andrö, me no falukha ia wangokafu dödö, ba khömi fefu.', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 14, 'Ba na no usuno ndra''o ma''ifu khönia, ba khömi andrö, ba lö saila ndra''o, si mane niŵa''öma khömi fefu, me no si duhu, si manö göi wanunoma ya''aga khö Dito, no si duhu.', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 15, 'Ba noa na tedou wa''omasima ami, me itörö tödönia wolo''ömi andrö, dozi ami, me mitema ia, me ata''u ami, ba me manizi-nizi ami.', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391774, 'NT', 'Korindro II', 7, 16, 'Omuso sa dödögu, me no abe''e dödögu ami, fefu gofu hadia ia.', '["Faigi 2:2–4","Mat 5:4; 26:75","Faigi 2:5,9"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 1, 'Ba lö''ö sa mabini''ö khömi, ya''ami ira talifusö, wa''ebua dödö Lowalangi andrö, ni''oroma''önia ba mbanua (niha Keriso), ba Makedonia misa.[1]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 2, 'No oya wanandraigö, fa''afökhö, ba no fahöna göi wa''omuso dödö, no numana sibai ira, ba no abölö wa''ahakhö dödöra, lua-lua.', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 3, 'Ndrege zi tola ira, lö ubini''ö, italu''i na i zi tola, fa''aoha gölöra.', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 4, 'No laforege wangandrö khöma, ena''ö matehe khöra, awö göi ira ba wanolo ni''amoni''ö andrö.[2]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 5, 'Ba tenga ha nidöna-dönama andrö, botora lalulu, khö Zo''aya ua, ba khöma dania, me no omasi Lowalangi.', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 6, 'Tobali mafarou dödö Dito andrö, ena''ö ifalua göi nifobörönia, ba dolo-tolo andrö, ba khömi göi.[3]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 7, 'Ba me no fahöna khömi fefu hadia ia, he famati, ba he famahaö andrö, ba he fa''aboto ba dödö, ba he ngawalö wa''owölö-ölö fefu, ba he fa''omasimi ndra''aga, ba ena''ö a''oi göi so khömi dolo-tolo andrö.[4]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 8, 'Tenga oroisa, na uŵa''ö khömi, ba ena''ö utandraigö, na si ndruhu wa''omasimi andrö, ena''ö ube''e fanandraigö wa''owölö-ölö danö bö''ö.[5]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 9, 'Noa sa aboto ba dödömi wa''ahakhö dödö Zo''aya ya''ita, Yesu Keriso, wa no ifa''anumana ia, börö ami, he ŵa''ae no fahöna khönia, ena''ö fahöna dania khömi ba wa''anumanania andrö.[6]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 10, 'Ba da''ö dödögu ba da''ö — da''ö sa zöguna khömi, me no mifobörö me ndröfia, tenga ha famalua, no fa''edöna göi[7] —', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 11, 'ba mi''asiwai göi wolau iada''e, ena''ö hulö si mane fa''aoha gölö andrö ba wa''edöna, si manö göi wamalua andrö, dali zi so khömi.[8]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 12, 'Na so wa''aoha gölö sa, ba no ni''omasi''ö; dali zi so khönia, tenga dali zi lö''ö.[9]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 13, 'Tenga sa ena''ö ohahau dödö danö bö''ö, ba ena''ö afökhö khömi; ena''ö fagölö-gölö a''ine: hadia zi töra khömi, götö iada''e, ba yamöi fonönö ba zambö khöra,', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 14, 'ena''ö göi möi fonönö ba zambö khömi zi töra khöra, ena''ö fagölö-gölö.[10]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 15, 'Si mane si so ba zura: "Ba zi no oya, ba lö si töra, ba ba zi lö oya-oya, ba lö sambö."[11]', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 16, 'Ba nisuno Lowalangi, si no mame''e ba dödö Dito fa''owölö-ölö andrö, ba khömi andrö.', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 17, 'Lö''ö sa abua khönia me lafarou ia, ba noa sa fahöna khönia wa''aterou dödö, ba möi manö ia khömi, no aoha gölönia.', '["Faigi 9:1,2; Rom 15:26","HalZin 11:29","Faigi 7:13–15; 12:18","KorI 1:5","YohI 3:17,18","Luk 9:58; Fil 2:6 b.t.","Faigi 9:2","Amaed 3:9","Faigi 9:7; Amaed 3:27,28; Luk 21:3,4","Faigi 9:12","MozII 16:18"]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 18, 'Ba no mafatenge awönia dalifusö andrö, si sökhi turia ba mbanua misa fefu, ba duria somuso dödö andrö.[12]', '["Faigi 12:18","Rom 12:17","Faigi 7:14 b.t."]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 19, 'Ba tenga ha da''ö, noa göi nituyu mbanua andrö ia, awöma, ba dolo-tolo andrö, si so ba dangama, ba wamosumange So''aya, ba ba wamarou tödöma.', '["Faigi 12:18","Rom 12:17","Faigi 7:14 b.t."]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 20, 'Andrö malau da''ö, fa lö laböbögö khöma zi lö sökhi, ba dolo-tolo sebua andrö, nifa''emama.', '["Faigi 12:18","Rom 12:17","Faigi 7:14 b.t."]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 21, 'Si sökhi sa ni''aluima, tenga ha ba zanehe Zo''aya, ba zanehe niha göi.[13]', '["Faigi 12:18","Rom 12:17","Faigi 7:14 b.t."]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 22, 'Ba no mafatenge awöra dalifusöda andrö, si no faduhu dödöma, wa sowölö-ölö ia; no asese ma''ila, no oya ngawalö; ba mendrua manö owölö-ölö ia iada''e, me no faduhu sibai dödönia khömi.', '["Faigi 12:18","Rom 12:17","Faigi 7:14 b.t."]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 23, 'Ba he ba khö Dito andrö, ba awögu ia, ba khömi andrö, ba sanolo ya''o ba halöŵö andrö, ba he talifusöda andrö, ba no sinenge mbanua andrö ira, lakhömi Keriso.', '["Faigi 12:18","Rom 12:17","Faigi 7:14 b.t."]', NULL),
  (3391775, 'NT', 'Korindro II', 8, 24, 'Ba na mi''oroma''ö khöra wa''omasimi, awö mbörö wanunoma ya''ami, ba no amaedola zi no so mbanua fefu.[14]', '["Faigi 12:18","Rom 12:17","Faigi 7:14 b.t."]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 1, 'Ba dolo-tolo andrö sa ba ni''amoni''ö andrö, ba alakha lö''ö sa''ae usura khömi hadia ia.[1]', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 2, 'Noa sa u''ila wa''aoha gölömi, ba nisunogu ya''ami, ba mbanua Makedonia, wa no aoha gölö mbanua Nakhaya, me ndröfia sa''ae; ba no möi famarou dödö zato wa''owölö-ölömi.', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 3, 'Ba no ufatenge dalifusö andrö, fa böi tobali faya wanunoma ya''ami, ba da''ö; ena''ö itörö niŵa''ögu, ena''ö aoha gölömi.[2]', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 4, 'Ena''ö lö aila ndra''aga — me no madöna-döna da''ö, na möi awögu mbanua Makedonia, ba na lö aoha gölömi la''ila.', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 5, 'Andrö wa no uŵa''ö tödögu, moguna u''andrö ba dalifusö andrö, ena''ö mowaö-waö ira ba khömi, ba wangasiwai howu-howu andrö khömi, si no awai tefabu''u, ena''ö awai, ba ena''ö howu-howu, ba böi si hulö wa''atali.', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 6, 'Ba da''ö niŵa''ögu: Na so zangatalisi tanömö, ba lö oya-oya ibasi, ba na so zi lö alimagö tanömö, ba oya göi ibasi dania.[3]', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 7, 'Ba balazi dödö zamösana; böi abu dödö, ba tenga niforege; si no aoha gölö fame''e, da''ö sa zomasi Lowalangi.[4]', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 8, 'Ba no abölö Lowalangi, ba wangöhöna khömi fefu ngawalö wa''ebua dödö, ena''ö lö mamalö-malö wa a''oi so khömi fefu hadia ia, ba ena''ö so zi töra, ba wolau si sökhi, hadia ia fefu.[5]', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 9, 'Si mane si so ba zura: "No ifazaewe, no ibe''e ba zi numana, lö mamalö-malö wa''atulö dödö andrö, khönia, irugi zi lö aetu."[6]', '["Faigi 8, 4. 20","Faigi 8:22,24","Amaed 11:24,25; 28:27","Faigi 8:12; MozV 15:7,10; Rom 12:8","Fil 4:19","Sin 112:9"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 10, 'Ba same''e tanömö ba zanaru ba ibe''e göi gö ni''a ba i''oya''ö mbua zinanömi, ba idou''ö lua-lua wa''atulö dödömi andrö.[7]', '["Yes 55:10; Hos 10:12","Faigi 8:7","Faigi 8:14","Rom 6:23"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 11, 'Ena''ö fahöna khömi fefu, hadia ia, ba wanolo andrö fefu, famasugi wangandrö saoha gölö khö Lowalangi; sama''ema ndra''aga.[8]', '["Yes 55:10; Hos 10:12","Faigi 8:7","Faigi 8:14","Rom 6:23"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 12, 'Tolo-tolo andrö, ame''ela andrö, ba tenga ha famönökhi sambö ba ni''amoni''ö andrö, mohare sibai göi, me ifasugi wangandrö saoha gölö khö Lowalangi, ba zato andrö,[9]', '["Yes 55:10; Hos 10:12","Faigi 8:7","Faigi 8:14","Rom 6:23"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 13, 'na lasuno Lowalangi, me no si ndruhu wanolo andrö, ba wolo''ömi andrö, wa lö mi''osilö''ögö duria somuso dödö andrö khö Keriso, ba ba wa''ebua dödö andrö, me no mihalö noro dödömi göi zabu dödöra ba sabu dödö zato fefu.', '["Yes 55:10; Hos 10:12","Faigi 8:7","Faigi 8:14","Rom 6:23"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 14, 'Ba ba wangandröra, salahimi, me no humulu dödöra khömi, börö wa''ebua dödö Lowalangi andrö khömi, si no fahöna.', '["Yes 55:10; Hos 10:12","Faigi 8:7","Faigi 8:14","Rom 6:23"]', NULL),
  (3391776, 'NT', 'Korindro II', 9, 15, 'Ba nisuno Lowalangi, ba mbualania andrö, si tebai taŵa''ö fa''ebua.[10]', '["Yes 55:10; Hos 10:12","Faigi 8:7","Faigi 8:14","Rom 6:23"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 1, 'Ba ya''o, Faulo, ufarou dödömi ba wa''ebolo dödö Keriso andrö, ba ba wa''asökhi dödönia; ya''o, si no ide-ide na fa''ila bawa ita, na sodo khömi, ba si no abe''e wanguma''ö khömi hadia ia, na ba zaröu sodo.', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 2, 'Ba u''andrö khömi: ena''ö alakha lö abe''e ndra''o na sodo, ena''ö alakha lö ufake wa lö aiŵö andrö, si tola ufake niŵa''ögu, ba niha ösa, sanguma''ö tödöra, dali khöma nösi niha ba lalama.[1]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 3, 'Ösi niha sa khöma ba lalama, ba ba wasöndrata andrö, ba tenga dali nösi niha khöma.', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 4, 'Ba wangönama andrö, ba wasöndrata andrö, ba tenga dali nösi niha, noa sa abe''e, ba khö Lowalangi, ba wanudugö hati.[2]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 5, 'Madudugö nifakhai dödö, awö ngawalö wayaŵasa fefu, solaŵa ena''ö fa''aboto ba dödö niha Lowalangi, ba maböbö fefu ngawalö gera-era, ba wolo''ö khö Keriso.[3]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 6, 'Ba matarogö, ba wangotu''ö fefu ngawalö wa lö molo''ö, na no a''oi so wolo''ömi.', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 7, 'Mitöngöni duduma hörö andrö. Na so zabe''e tödö ba khönia, wa no khö Keriso ia, ba yamu''ofanöi tödönia, wa si mane ya''ia göi ndra''aga, khö Keriso.', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 8, 'Ba he na udou''ö na ma''ifu tö wanuno ya''o, me no itehe khöma So''aya, wanga''azökhi ya''ami, ba tenga famakiko, ba lö''ö sa atö falukha aila ndra''odo,[4]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 9, 'fa böi hulö na ufeta''u ami ba zura andrö.', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 10, 'Me laŵa''ö: sura andrö, ba no abe''e, no abölö, ba na so ia, ba no ambö fa''abe''e, ba huhuo andrö, ba lö göna ba dödö.[5]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 11, 'Ba yamube''e ba dödönia sanguma''ö da''ö: si mane fehedema ba zura, na lö ya''aga, si manö göi wolauma, na soga.[6]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 12, 'Ata''u sa ndra''aga mafaomagö ndra''aga ba mafakhili-khili ndra''aga ba niha andrö, samaduhu''ö ya''ira; ba ya''ira, ba no sambö era-era, na labe''e dali ira ba wamaigi su''ara ba he wisa ira.', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 13, 'Ba ya''aga, ba lö mafalawu wanuno ya''aga, mabe''e dali nifakhoi andrö, nifakhoi Lowalangi khöma, fondrege wa no marugi göi ami.[7]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 14, 'Lö taŵa''ö, lö nirugima ya''ami, ba mafaigi sa''ae zi töra fa''aröu; noa sa marugi ami göi, wangombakha turia somuso dödö andrö khö Keriso.[8]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 15, 'Lö mafalawu wanuno ya''aga, ba halöŵö niha bö''ö; ba madöna-döna, na tedou wamatimi andrö, ba ebua ndra''aga, ba khömi andrö, dali nifakhoi andrö khöma, irege a''oi makhamö,', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 16, 'ba wangombakha turia somuso dödö andrö, ba zi tambaimi, ba böi ba nifakhoi ba danö bö''ö, ba zi no awai halöŵö, ba wanuno ya''aga ba da''ö.[9]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 17, 'Na so zanuno ya''ia, ba ba khö Zo''aya yamusuno ia.[10]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391777, 'NT', 'Korindro II', 10, 18, 'Tenga sa ba zamaduhu''ö ya''ia faduhu dödöda, ba nifaduhu''ö Zo''aya faduhu dödöda.[11]', '["Faigi 13:1–10; 1:12,17","Efes 6:10,13 b.t.","Rom 15:18","Faigi 12:6; 13:10","Faigi 11:6","Faigi 13:2 b.t.","Rom 12:3","KorI 9:2","Rom 15:20","KorI 1:31","KorI 4:5; Amaed 27:2"]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 1, 'Ena''ö mibologö dödömi ma''ifu, ba wa''ambö tödö andrö khögu! Ba mibologö sa göi dödömi khögu.[1]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 2, 'Solohu sa ndra''o, ba khömi andrö, fa''olohu Lowalangi. No ufohu ami ba niha, si ha samösa, ena''ö u''ohe ami khö Keriso, ono alawe si sökhi.[2]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 3, 'Ba ata''u ndra''o, tefakiko gera-erami, aheta ba zadölö andrö, ba khö Keriso, hulö si mane famaelungu gulö andrö Khawa, ba wa''onekhenia.[3]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 4, 'Na so sa zi möi khömi, mangombakha Yesu tanö bö''ö, si tenga ni''ombakha''öma, ba ma na mitema Geheha tanö bö''ö, si tenga nitemami, ba ma turia somuso dödö tanö bö''ö, si tenga nihalömi khömi, ba faduhu dödöda, na lö mitimba.[4]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 5, 'Ba dödögu sa, ba ma''ifu lö ide-ide ndra''o, moroi ba zinenge salua yaŵa andrö.[5]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 6, 'Ba he no sambö tödö ndra''odo ba huhuo, ba tenga sa ba wa''aboto ba dödö; gofu hadia ia, ba no u''oroma''ö manö ia, ba khömi andrö.[6]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 7, 'Ma horögu, me no u''ide-ide''ö ndra''o, ena''ö möi yaŵa ami, ube''e, me no saoha gölögu wangombakha khömi turia somuso dödö andrö khö Lowalangi?[7]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 8, 'Banua bö''ö, ba no ufo''ömö, me no uhalö mböli gölögu, ba we''amöi enonimi; ba me sodo khömi, me ambö khögu, ba lö nibusigu tödö niha, ha niha ia.[8]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 9, 'Sambö khögu andrö, ba noa sa labönökhi talifusö andrö, si otarai Makedonia; ba fefu hadia ia, ba lö nibusigu tödömi, ba lö''ö göi ubusi dödömi dania.[9]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 10, 'Faya zi duhu andrö khö Keriso ba dödögu, na ube''e toba''a khögu wanuno ya''o andrö, ba mbanua Nakhaya misa.[10]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 11, 'Hana wa si manö? Hadia me lö omasido ami? I''ila Lowalangi.', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 12, 'Ba nilaugu iada''e, ba utohugö, ena''ö utimba mbörö andrö, ba zangalui börö, ba wangai tulada khöra ya''aga, ba nisunora ya''ira.', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 13, 'Sinenge faya sa niha si manö, sohalöŵö si falimo, sanagö amuata zinenge Keriso.[11]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 14, 'Ba lö''ö sa ahöli-höli dödöda; Satana sa göi, itagö gamuata mala''ika haga.[12]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 15, 'Ba hana wa takata''ö sibai, na latagö enoninia göi gamuata genoni ba zatulö? Ba i''ohia''ö mbua-buara amozuara dania.[13]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 16, 'Samuza tö uŵa''ö: Böi yamuŵa''ö tödönia niha, sambö tödö ndra''odo; ba na so zui, ba lau, ba yasambö tödö ndra''o khömi, ena''ö töla usuno göi ndra''o ma''ifu.[14]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 17, 'Hadia niŵa''ögu iada''e, ba tenga dali Zo''aya, wa uŵa''ö ia; hulö ba wa''ambö tödö sa, me no abe''e dödögu wanuno ya''o.[15]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 18, 'Me ato zanuno ya''ira, dali nösi niha, ba usunodo göi.[16]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 19, 'No edöna ami, mibologö dödömi ba zambö tödö, me no satua-tua ami.[17]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 20, 'Mitaha sa, na so zangosawuyu ya''ami, na so zi manga ya''ami, na so zondra''u ya''ami, na so zi fayaŵa, na so zamalisi baŵami.[18]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 21, 'Fangaila, wa uŵa''ö: noa sa ambö wa''abe''ema. Ba na so zabe''e dödö niha bö''ö (fehede zambö tödö wehedegu) ba abe''e göi dödögu.', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 22, 'Niha Heberaio ira? ya''odo göi. Iraono Gizeraeli ira? ya''odo göi. Ma''uwu Gaberahamo ira? ya''odo göi.[19]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 23, 'Enoni Keriso ira? (fehede zambö tödö wehedegu) no töra ndra''o; no abölö wa''erege dödögu, no asese laböbözi ndra''o, no asese lakurudo, no asese ahatö wa''amate.[20]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 24, 'No melima lahare''ö khögu niha Yehuda zi sara ambö öfa wulu.[21]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 25, 'No medölu tebözi ue ndra''o, samuza no latebudo kara; no medölu falukhado wa''aboto nowo; sara luo sara mbongi si no alömö ba nasi ndra''odo.[22]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 26, 'No asese mukoli ndra''o, falukha ndra''o gameta''uö ba nidanö ba ameta''uö sange''e, ba ameta''uö ba niwama, ba ameta''uö ba niha baero, ba ameta''uö ba mbanua misa, ba ameta''uö ba danö si mate, ba ameta''uö ba nasi, ba ameta''uö ba dalifusö sofaya;', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 27, 'ba halöŵö ba ba wa''erege dödö; ba wa''asese lö mörö ba zi bongi; ba wa''olofo ba ba wa''owökhi dödö, ba wa''asese lö manga, ba wa''o''afu ba ba wa lö nukha;[23]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 28, 'lö lai baero ö, wa ero ma''ökhö lahurufai ndra''o, wa u''abusi tödö mbanua misa, fefu.', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 29, 'Ha niha zamomo, zi lö amomo ndra''o göi? Ha niha zi falukha fangala, si lö afökhö bakha dödögu?[24]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 30, 'Na lö tola lö usuno ndra''o, ba ba wa''ambö wa''abölögu usunodo.[25]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 31, 'Lowalangi Zo''aya ya''ita Yesu, Amania, nisuno-suno irugi zi lö aetu, da''ö zangila, wa tenga faya niŵa''ögu.', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391778, 'NT', 'Korindro II', 11, 32, 'Ba Ndramaseko ifatarogö''ö mbanua Ndramaseko kumandru razo Areta andrö, ba wondra''u ya''o;[26]', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391778, 'NT', 'Korindro II', 11, 33, 'ba ba zandrela lafatörö ndra''o, wanada ya''o, ba gero göli kara, ba raga-raga, ba aefa ndra''o ba dangania.', '["Faigi 11:16–19; 12:6","Efes 5:25 b.t.","MozI 3:1–13","Gal 1:6 b.t.","Faigi 12:11; 10:12; KorI 15:9,10","Faigi 10:10; KorI 2:1,13","Faigi 12:13; KorI 9:12","Fil 4:10,55; HalZin 18:3","KorI 16:17; TesI 2:9","KorI 9:15","Faigi 2:17; Fil 3:2","Mat 4:5,6; HalZin 16:16,17","Fil 3:19","Faigi 11:1","Faigi 12:19","Fil 3:3 b.t.","KorI 4:10","KorI 7:23","HalZin 22:3","KorI 4:1","MozV 25:3","HalZin 16:22; 14:19; 27:41 b.t.","Faigi 6:4,5; KorI 4:11","KorI 9:22","Faigi 12:5,9,10","HalZin 9:24 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 1, 'Lö tola lö usuno ndra''o, ba lö''ö sa gunania; ba alakha sa itörö ligu gangilata andrö, ba fama''ele''ö andrö, khö Zo''aya.[1]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 2, 'So ni''ilagu niha, ba khö Keriso, si no mu''ohe yaŵa, irugi tölu nga''ötö zorugo, me mewele''öfa fakhe (na ba mboto so ia, ba lö u''ila, ba na baero mboto, ba lö''ö zui u''ila; Lowalangi zangila).[2]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 3, 'Ba no u''ila niha andrö (na ba mboto, ba na baero mboto, ba lö u''ila; Lowalangi zangila)', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 4, 'wa no mu''ohe ia ba waradaiso, awö wa no irongo daroma li si tebai laŵa''ö niha, si lö tola iŵa''ö niha, ha niha ia göi.[3]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 5, 'Da''ö mbörö wa usuno ndra''o, ba na ba khögu, ba lö edönado usunodo, ha ba wa''ambö wa''abölögu andrö.[4]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 6, 'Na edönado sa usuno ndra''o, ba tenga nifolau zambö tödö wolaugu, me si duhu niŵa''ögu; ba utaha dödögu, fa lö iwai niha, ha niha ia, ebua ndra''o, moroi ba ni''ilania khögu, ba moroi ba nirongonia.[5]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 7, 'Ba ena''ö böi fayaŵa ndra''o, ba nifa''ele''ö andrö khögu, me no ebua, ba no mutaru''ö khögu zuzumö ba nösi, mala''ika Zatana, ena''ö igukhu-gukhui ndra''o, fa böi fayaŵa ndra''odo.[6]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 8, 'Ba no medölu mangandrödo khö Zo''aya, ena''ö aheta ia khögu.[7]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 9, 'Ba no iŵa''ö khögu: Ya''abönö khöu wa''ebua dödögu khöu, a''oi sa so wa''abölö andrö khögu ba wa lö abölö. Andrö wa abölö omasido, ba wa lö abölödo andrö usuno ndra''o, ena''ö abönö khögu wa''abölö Keriso andrö.[8]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 10, 'Andrö omasi ndra''o wa lö abölö ba famakao ba fa''afökhö ba folohi ba fa''atosasa, na börö Keriso. Na sambö fa''abölö ndra''o, awena abölödo.[9]', '["HalZin 26:16; Gal 2:2","Hes 11:24; HalZin 22:17","Luk 23:43","Faigi 11:30","Faigi 10:8","Yob 2:7; Gal 4:14","Mat 26:44","Fil 4:13; Yes 40:29 b.t.","Faigi 6:10"]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 11, 'Noa sa tobali sambö era-era ndra''o; noa sa miforege khögu. Ya''ami sa zanuno ya''o ena''ö, ma''ifu sa lö ide-ide ndra''o, moroi ba zinenge andrö, si no alua yaŵa, he ŵa''ae no si lö boto ndra''odo.[10]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 12, 'Tandra, si nangea tandra khö zinenge, ba no mufalua ba khömi, no a''oi so wa''anau gölö ba dandra ba ba gila-ila ba ba wa''abölö.[11]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 13, 'Hadia sa ni''ambösi ami, moroi ha mbanua bö''ö andrö, baero wa lö nifonorogu tödömi? Mibologö dödömi khögu, ba zalagu andrö.[12]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 14, 'Hiza, no ufuli ufa''anödo, ba we''amöi khömi, no medölu, möi da''e, ba lö dania ufonoro dödömi. Tenga sa nibaya-bayami ni''aluigu, ha ya''ami u''alui. Tenga sa iraono zangalui ana''a khö ndra amara, ama zangalui ana''a ba ndraono.[13]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 15, 'Ba omasido mangahakhö, ba he ya''odo na i nibe''e salahi nosomi; na no fahöna wa''omasigu ami, ba hadia, ba la''ambösi wangomasi''ö ya''o?[14]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 16, 'Ba ya''ia ya''ö; lö nifonorogu tödömi, ba me no onekhe ndra''o, ba no ufa''u''u ami fa''onekhe andrö.', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 17, 'Hadia, no u''alani ami, ba nifatengegu khömi andrö, ha niha ia?', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 18, 'No u''andrö khö Dito andrö, ba no ufatenge awönia dalifusö andrö; hadia, no i''alani ami Tito andrö? Hadia, lö ha sara dödöma, wanörö lala khöma? Hadia, lö faoma matara lahe nawöma?[15]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 19, 'I''otarai föna sa''ae, miŵa''ö tödömi, mabu''a ba huluma, ba khömi andrö; föna Lowalangi muhede ndra''aga, ba khö Keriso. Ba fefu hadia ia da''ö, ya''ami ni''omasi''ö, ba ba wanga''azökhi ya''ami.[16]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 20, 'Ata''udo sa, na sodo, ba ma tenga somasi ndra''o u''ila ba khömi, ba ya''ami göi, ba ma tenga somasi ami, mi''ila khögu; ma so wagua-guasa, ba ma fa''afökhö dödö, ba ma fönu, ba ma fasosota, ba ma famöbögö si lö duhu, ba ma fangöngö-ngöngösa, ba ma fayaŵasa, ba ma famakuyu;[17]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391779, 'NT', 'Korindro II', 12, 21, 'ba ma ihöndrögö ndra''o Lowalangigu, ba khömi andrö, na ufuli möi khömi, ba abu dödögu ba zato andrö, si no mamazökhi horö, föna, ba si lö abu tödö ba zi lö sökhi andrö ba ba wohorö ba ba hokha andrö, nitöröra.[18]', '["Faigi 11:1,5,16","Faigi 6:4–6; Rom 15:19","Faigi 11:7–11","Faigi 13:1; HalZin 20:33","TesI 2:8","Faigi 8:16–18; KorI 16:10","Faigi 3:1; 11:16 b.t.","KorI 1:11; Gal 5:19 b.t.","KorI 6:15 b.t."]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 1, 'Ufuli möi khömi, medölu, möi da''e. Ba niŵa''ö zi darua, ba ma si datölu, si so ba mbörö, ahono dania fefu hadia ia.[1]', '["Faigi 12:14; Mat 18:16; MozV 19:15; TimI 5:19","KorI 5:3; KorII 1:23; 12:21","Rom 15:18; Mat 10:20","Rom 6:9,10; Heb 2:9"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 2, 'No uhönagö uŵa''ö ba ufuli uhönagö uŵa''ö, hulö no so ndra''o, zamuza tö, he ŵa''ae lö ya''o iada''e, ba zi no mamazökhi horö, föna, ba ba danö bö''ö fefu, wa lö u''ila wa''ahakhö dödö, na möido zamusa tö.[2]', '["Faigi 12:14; Mat 18:16; MozV 19:15; TimI 5:19","KorI 5:3; KorII 1:23; 12:21","Rom 15:18; Mat 10:20","Rom 6:9,10; Heb 2:9"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 3, 'Me mi''alu-alui dandra, wa Keriso zihede ba wehedegu andrö; Keriso si lö ambö fa''abölö, ba khömi andrö, si no abölö ba khömi.[3]', '["Faigi 12:14; Mat 18:16; MozV 19:15; TimI 5:19","KorI 5:3; KorII 1:23; 12:21","Rom 15:18; Mat 10:20","Rom 6:9,10; Heb 2:9"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 4, 'Noa sa muforöfa ia, ba wa lö abölö, ba no auri ia, ba wa''abölö Lowalangi. Ya''aga sa göi, ba no sambö fa''abölö, ba khönia andrö, ba auri ndra''aga dania, awönia, ba wa''abölö Lowalangi, ba khömi andrö.[4]', '["Faigi 12:14; Mat 18:16; MozV 19:15; TimI 5:19","KorI 5:3; KorII 1:23; 12:21","Rom 15:18; Mat 10:20","Rom 6:9,10; Heb 2:9"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 5, 'Misekhegö dödömi, na samati ami, mitandraigö ami; ma lö aboto ba dödömi ami, wa no so ba dödömi Keriso Yesu? Atö no si lö faduhu dödöda ami.[5]', '["KorI 11:28; Rom 8:9,10; Gal 2:20","Heb 13:21","Faigi 2:3; 10:8"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 6, 'Ba udöna-döna, aboto ba dödömi dania, wa tenga si lö faduhu dödöda ndra''aga.', '["KorI 11:28; Rom 8:9,10; Gal 2:20","Heb 13:21","Faigi 2:3; 10:8"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 7, 'Ba mangandrö ndra''aga ba Lowalangi, ena''ö lö milau hadia ia zi lö atulö; tenga sa ena''ö laŵa''ö, niha si faduhu dödö niha bö''ö ndra''aga, ena''ö si sökhi milau, ba ena''ö hulö zi lö faduhu dödö niha ndra''aga.', '["KorI 11:28; Rom 8:9,10; Gal 2:20","Heb 13:21","Faigi 2:3; 10:8"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 8, 'Tebai sa masawö zi duhu, ha ba zi duhu ma''ila matolo.', '["KorI 11:28; Rom 8:9,10; Gal 2:20","Heb 13:21","Faigi 2:3; 10:8"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 9, 'Ebua sa dödöma, na sambö fa''abölö ndra''aga, ba na sabölö ami; ba da''ö ni''andröma, ena''ö mo''ahonoa ami.[6]', '["KorI 11:28; Rom 8:9,10; Gal 2:20","Heb 13:21","Faigi 2:3; 10:8"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 10, 'Andrö usura khömi da''ö, me lö ya''o, ena''ö alakha lö u''abe''e''ö, na sodo, ena''ö alakha lö ube''e dali wa''abe''e andrö, nitehe Zo''aya khögu, ba wanga''azökhi, ba tenga ba wanudugö.[7]', '["KorI 11:28; Rom 8:9,10; Gal 2:20","Heb 13:21","Faigi 2:3; 10:8"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 11, 'Ba baero ö, ya''ami ira talifusö, ba mi''omusoi''ö dödömi, mibe''e nihaogö ami, mifondrondrongo wamarou tödömi, ya ha sara dödömi, ya''atulö ami ba nawömi ba itolo ami Lowalangi wa''omasi andrö, Lowalangi wa''atulö.[8]', '["Fil 4:4; KorI 14:20; Rom 12:16,18; 15:33","KorI 16:20; TesI 5:26","Gal 6:18; Rom 5:5"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 12, 'Faoma mi''owai nawömi fa''agosa bawa ni''amoni''ö andrö. La''owai ami ni''amoni''ö andrö fefu.[9]', '["Fil 4:4; KorI 14:20; Rom 12:16,18; 15:33","KorI 16:20; TesI 5:26","Gal 6:18; Rom 5:5"]', NULL),
  (3391780, 'NT', 'Korindro II', 13, 13, 'Yafalukha ami fefu wa''ebua dödö Zo''aya ya''ita, Yesu Keriso ba fa''omasi Lowalangi ba fa''awösa Geheha ni''amoni''ö![10]', '["Fil 4:4; KorI 14:20; Rom 12:16,18; 15:33","KorI 16:20; TesI 5:26","Gal 6:18; Rom 5:5"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 1, 'Faulo zanura da''e, sinenge, tenga moroi ba niha ba tenga göi nifa''ema niha khönia, moroi khö Yesu Keriso ba moroi khö Lowalangi Ama, si no manusugi ya''ia moroi ba ngai zi mate,[1]', '["Tit 1:3","KorI 16:1","Efes 1:2; YohII 3","Faigi 2:20; Mat 20:28; Efes 5:2; YohI 5:19","TimII 4:18"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 2, 'ba talifusö andrö, awögu, fefu: ba mbanua andrö misa, ba Galatia mafa''ohe''ö.[2]', '["Tit 1:3","KorI 16:1","Efes 1:2; YohII 3","Faigi 2:20; Mat 20:28; Efes 5:2; YohI 5:19","TimII 4:18"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 3, 'Yafalukha ami wa''ebua dödö ba fa''ohahau dödö, khö Lowalangi Ama, ba khö Zo''aya ya''ita, Yesu Keriso,[3]', '["Tit 1:3","KorI 16:1","Efes 1:2; YohII 3","Faigi 2:20; Mat 20:28; Efes 5:2; YohI 5:19","TimII 4:18"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 4, 'si no mame''e ya''ia, ba horöda andrö, ena''ö i''efa''ö ita ba nösi guli danö andre, si lö sökhi, dali zomasi Lowalangi, Amada,[4]', '["Tit 1:3","KorI 16:1","Efes 1:2; YohII 3","Faigi 2:20; Mat 20:28; Efes 5:2; YohI 5:19","TimII 4:18"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 5, 'nifosumange irugi zi lö aetu. Yaduhu.[5]', '["Tit 1:3","KorI 16:1","Efes 1:2; YohII 3","Faigi 2:20; Mat 20:28; Efes 5:2; YohI 5:19","TimII 4:18"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 6, 'Ahöli-höli dödögu, me no alio sibai mifaheta''ö ami ba zogaoni ya''ami ba wa''ebua dödö Keriso andrö, me no alio mi''otahögö duria somuso dödö bö''ö.[6]', '["Faigi 5:8; KorII 11:4","Faigi 5:10; HalZin 15:1,24","KorI 16:22","TesI 2:4"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 7, 'Ba lö''ö sa tanö bö''ö, ha ba niha andrö ösa, samakuyu ya''ami, sedöna mamalia''ö turia somuso dödö andrö khö Keriso.[7]', '["Faigi 5:8; KorII 11:4","Faigi 5:10; HalZin 15:1,24","KorI 16:22","TesI 2:4"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 8, 'Ba he na ya''aga, ba ma mala''ika moroi ba zorugo, zangombakha khömi turia somuso dödö bö''ö si tenga ni''ombakha''öma khömi, ba yagöna ia fangelifi![8]', '["Faigi 5:8; KorII 11:4","Faigi 5:10; HalZin 15:1,24","KorI 16:22","TesI 2:4"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 9, 'Si mane fanguma''öma föna, si manö göi ufuli uŵa''ö iada''e: na zo zangombakha khömi turia somuso dödö, si lö faudu ba nitemami andrö, ba yagöna ia fangelifi!', '["Faigi 5:8; KorII 11:4","Faigi 5:10; HalZin 15:1,24","KorI 16:22","TesI 2:4"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 10, 'Hadia sa iada''e, hadia, ena''ö faduhu dödö niha khögu u''alui, ba ma ena''ö faduhu dödö Lowalangi khögu? Hadia, ena''ö la''omasi''ö ndra''o niha u''alui? Na u''alui na, ena''ö la''omasi''ö ndra''o niha, ba tenga enoni Keriso ndra''odo ena''ö.[9]', '["Faigi 5:8; KorII 11:4","Faigi 5:10; HalZin 15:1,24","KorI 16:22","TesI 2:4"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 11, 'Ba lö ubini''ö khömi, ya''ami ira talifusö: ba duria somuso dödö andrö, ni''ombakha''ögu, ba tenga dali niha.[10]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 12, 'Ba tenga sa göi nitemagu ba niha, ba tenga nifahaö ndra''odo, no moroi ba wama''ele''ö Yesu Keriso ia. [11]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 13, 'Noa sa mirongo gamuatagu föna, ba huku ba niha Yehuda, wa no uforege wolohi banua Lowalangi, wa no ufakiko [12]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 14, 'ba no'' ato utalu''i si fazia-zia''a khögu, iwama, ba huku ba niha Yehuda andrö, ba no uforege, ba wolo''ö nifa''ema ndra tuama.[13]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 15, 'Ba me no omasi zi no mangoniagö ya''o, moroi ba dalu ninagu, si no mogaoni ya''o, ba wa''ebua dödönia,[14]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 16, 'ifa''ele''ö Nononia andrö ba dödögu, ena''ö uturiagö ia ba niha baero, ba i''anema''ö lö ube''e dali niha,[15]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 17, 'lö''ö göi si möido misi yaŵa ba Yeruzalema, ba khöra si no sinenge fönagu; möido ba danö Ndrawa Ara, ba ufulido zui ba Ndramaseko.', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 18, 'Awena dania, medölu fakhe furi ö, ba möido misi yaŵa ba Yeruzalema, ena''ö falukhado khö Gefa, ba felelima wongigu khönia;[16]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 19, 'ba sinenge bö''ö, ba lö ni''ilagu, ha Yakobo, talifusö Zo''aya andrö.[17]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 20, 'Ba hadia nisuragu, ba hiza, anehe Lowalangi, wa tenga sofaya ndra''odo.[18]', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 21, 'Ba awena möido ba mbanua Ziria misa ba ba mbanua Gilikia andrö.', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 22, 'Ba lö''ö sa marai fa''ila bawa mbanua Keriso ba Yudaia.', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406110, 'NT', 'Galatia', 1, 23, 'Ha da''ö nirongora: Solohi ya''ita föna, ba ituriagö iada''e wamati andrö, nifakikonia föna, 24 ba lasuno Lowalangi ba khögu andre.', '["KorI 15, b.t.","HalZin 26:16","HalZin 26:4 b.t.; TimI 1:13","HalZin 22:3","HalZin 9:15; Efes 3:7","Mat 11:27; HalZin 26:16 b.t.; Efes 3:8 b.t.","HalZin 9:26","Faigi 2:9; HalZin 12:17; Mat 13:55","Rom 9:1"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 1, 'Ba aefa da''ö, meweleöfa fakhe furi ö, ba ufuli möi misi yaŵa ba Yeruzalema, awö Mbaranaba, ba u''ohe göi awögu Dito andrö. [1]', '["HalZin 15:2; KorII 8:23","HalZin 13:2","HalZin 15:24; Gal 5:1"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 2, 'Ba fama''ele''ö mbörö, wa möido misi yaŵa, ba u''ombakha''ö khöra duria somuso dödö andrö, nituriagögu ba niha baero, oföna ba zi no motöi andrö, ba wamaigi na zaya-zaya gölögu halöŵögu, ba ma halöŵögu föna.[2]', '["HalZin 15:2; KorII 8:23","HalZin 13:2","HalZin 15:24; Gal 5:1"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 3, 'Ba he Tito andrö, awögu, Dawa Heleni, ba lö mu''o''ou, ena''ö ifaboto''ö ia.', '["HalZin 15:2; KorII 8:23","HalZin 13:2","HalZin 15:24; Gal 5:1"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 4, 'Ba ba dalifusö faya andrö, si no tetewu, si no manöndragö ya''ira bakha, ba wamaigi hadia zi tola khöma, ba khö Keriso Yesu, ena''ö labali''ö sawuyu ndra''aga.[3]', '["HalZin 15:2; KorII 8:23","HalZin 13:2","HalZin 15:24; Gal 5:1"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 5, 'Ba saza lö alulu dödöma, ba wolo''ö khöra mena''ö, ena''ö lö tebulö khömi wa''aduhu duria somuso dödö andrö.', '["HalZin 15:2; KorII 8:23","HalZin 13:2","HalZin 15:24; Gal 5:1"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 6, 'Ba ba zi so töi andrö — ha niha ira föna, ba ma''ifu lö ba dödögu da''ö; lö''ö sa ifaigi mbawa niha Lowalangi, — ba lö''ö sa ninönö zi so töi andrö khögu.[4]', '["Rom 2:11","HalZin 15:12; Rom 1:5","Rom 15:15 b.t.","Efes 3:8 b.t.","KorI 16:1; HalZin 11:29,30"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 7, 'Ba tenga ha da''ö; me larongo, wa no mube''e ba dangagu duria somuso dödö andrö, ba niha si lö muboto, si mane khö Wetero ba niboto[5] —', '["Rom 2:11","HalZin 15:12; Rom 1:5","Rom 15:15 b.t.","Efes 3:8 b.t.","KorI 16:1; HalZin 11:29,30"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 8, 'sanolo khö Wetero sa, ba halöŵö zinenge andrö, ba niboto, da''ö göi zanolo ya''o, ba niha baero,[6] —', '["Rom 2:11","HalZin 15:12; Rom 1:5","Rom 15:15 b.t.","Efes 3:8 b.t.","KorI 16:1; HalZin 11:29,30"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 9, 'ba me no aboto ba dödöra wa''ebua dödö andrö, si no falukha ndra''o, Yakobo andrö ba Kefa ba Yohane, si no amaedola gehomo, laŵa''ö niha sato, ba fara''u tanga ira khögu ba khö Mbaranaba, tandra wa fa''awö, ena''ö ba niha baero mangombakha ndra''aga, ba ya''ira, ba ba niboto;[7]', '["Rom 2:11","HalZin 15:12; Rom 1:5","Rom 15:15 b.t.","Efes 3:8 b.t.","KorI 16:1; HalZin 11:29,30"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 10, 'ha fa böi olifu ndra''aga zi numana, ba noa göi uforege wolo''ö da''ö.[8]', '["Rom 2:11","HalZin 15:12; Rom 1:5","Rom 15:15 b.t.","Efes 3:8 b.t.","KorI 16:1; HalZin 11:29,30"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 11, 'Ba me möi ba Gandriokhia Gefa, ba no utegu ia, muhededo khönia, me no mosinegu ia.', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 12, 'Me lö si so niha andrö sa, si otarai khö Yakobo, ba orudu manga ia ba zi no niha baero föna, ba me no so ira, ba iheta ia, ba i''oniagö ia, fa''ata''unia niboto.[9]', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 13, 'Ba mamini tödö göi, awönia, niha Yehuda bö''ö andrö, ba tobali adöni göi Mbaranaba, ba wamini tödö andrö khöra.', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 14, 'Ba me u''ila, lö sökhi nilaura, lö latörö zi duhu andrö, turia somuso dödö, ba muhededo khö Gefa, ba zi so ira fefu, umane: Na ö''o''ö huku ba niha baero, ya''ugö niha Yehuda, ba na tenga huku ba niha Yehuda ö''o''ö, ba hadia wa ö''o''ou niha baero, ba wolo''ö huku ba niha Yehuda![10]', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 15, 'Ya''ita, ba no to''ua niha Yehuda, ba tenga si so horö, nga''ötö niha baero.[11]', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 16, 'Ba me no ta''ila, wa tenga moroi ba wolo''ö oroisa atulö niha, iŵa''ö Lowalangi, ha moroi ba wamati andrö, khö Keriso Yesu, ba no mamati ita, khö Keriso Yesu, ena''ö atulö ita, iŵa''ö Lowalangi, moroi ba wamati andrö, khö Keriso, ba tenga moroi ba wolo''ö oroisa, me samösa lö''ö, satulö, iŵa''ö Lowalangi, moroi ba wolo''ö oroisa.[12]', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 17, 'Ba na no oroma, wa no niha si so horö göi ita, ya''ita sangalui ena''ö atulö ita, iŵa''ö Lowalangi, ba khö Keriso, ba ma no sanolo ba horö Keriso? Böi si manö!', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 18, 'Na ufuli sa ufazökhi zi no ududugö, ba tobali solalö ndra''o ube''e.', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 19, 'Ya''o sa, ba si no mate ba goroisa andrö, moroi ba goroisa, ena''ö khö Lowalangi auri ndra''o.[13]', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 20, 'No muforöfa ndra''o, awö Keriso; auri ndra''o, ba tenga sa''ae ya''o, Keriso zauri ba dödögu. Ba fa''aurigu iada''e, ba mboto andre, ba no fa''auri ba wamati khö Nono Lowalangi, si no mangomasi''ö ya''o, si no mame''e salahigu ya''ia.[14]', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406112, 'NT', 'Galatia', 2, 21, 'Lö u''ositengagö wa''ebua dödö Lowalangi andrö; na moroi ba goroisa wa''atulö dödö andrö mena''ö, ba no zaya-zaya gölö, wa no mate Keriso.[15]', '["HalZin 21:18; 11:3","TimI 5:20","Efes 2:3 b.t.","Faigi 3:11; HalZin 15:10-11; Rom 3:20,28; 4:5","Faigi 6:14; Rom 7:4; 6:4-6","KorII 13:5; 5:15,17; Gal 1:4","Heb 7:11"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 1, 'He ya''ami, banua Galatia, si lö tödö-tödö! Ha niha zolau elemunia khömi, khömi, si no mube''e famaedo Yesu Keriso, ba duduma hörö, famaedo Yesu Keriso niforöfa? [1]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 2, 'Ha da''ö nisofugu khömi: Hadia, moroi ba wolo''ö oroisa, wa no mitema mege Geheha, ba ma moroi ba duria wamati andrö? [2]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 3, 'Hadia, si manö wa''ambö tödö andrö khömi? Ba Geheha mibörötaigö no, ba hadia, ba nösi niha wozu khömi dania?', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 4, 'Hadia, ha wa''oya-oya zi no itörö ami, hadia, zaya-zaya gölö? Si ndruhu zaya-zaya gölö taŵa''ö?', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 5, 'Ba sama''ema khömi Eheha andrö, sanga''asogö khömi fa''abölö, hadia, moroi ba wolo''ö oroisa, wa ilau da''ö, ba ma moroi ba duria wamati andrö?', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 6, 'Si mane Aberahamo, "mamati ia khö Lowalangi, ba tebe''e fa''atulö dödönia."[3]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 7, 'Ba aboto sa''ae ba dödömi: ha niha zi otarai wamati, da''ö ma''uwu Gaberahamo.[4]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 8, 'Ba me no tohöna oroma ba zura, wa moroi ba wamati andrö atulö niha baero, iŵa''ö Lowalangi, andrö tehönagö te''ombakha''ö khö Gaberahamo duria somuso dödö, imane Lowalangi: "Moroi ba khöu tefahowu''ö dania fefu soi ba gulidanö."[5]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 9, 'Tobali awö Gaberahamo, samati andrö, tefahowu''ö zi otarai wamati andrö.[6]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 10, 'Ha wa''ato sa zi otarai wolo''ö oroisa, ba no tohare khöra wangelifi. Noa sa so ba zura: "Ni''elifi dozi si lö manörö fefu, hadia ia, zi so ba zura goroisa andrö, ba wolo''ö ya''ia."[7]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 11, 'Ba no oroma, wa samösa lö satulö, iŵa''ö Lowalangi, ba goroisa andrö, imane: "Moroi ba wamati auri dania zatulö andrö." [8]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 12, 'Ba tenga moroi ba wamati goroisa andrö, imane: "Ha niha zi no molo''ö, da''ö zauri ba da''ö." [9]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 13, 'No ihöli ita Keriso, ba wangelifi andrö, ba goroisa andrö, me no tobali ni''elifi ia, salahida, me no so ba zura: Ni''elifi dozi nitaŵi ba döla geu,[10]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 14, 'ena''ö falukha niha baero howu-howu andrö khö Gaberahamo, ba khö Keriso Yesu, ena''ö tatema gamabu''ula li andrö, Eheha andrö, moroi ba wamati.[11]', '["Faigi 5:7","HalZin 2:38","MozI 15:6; Rom 4:3","Rom 4:11-12; Yoh 8:39","MozI 12:3","Rom 4:16","MozV 27:26","Faigi 2:16; Hab 2:4; Rom 1:17","MozIII 18:5; Rom 10:5","Rom 8:3; MozV 21:23","MozI 12:3; Yes 44:3"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 15, 'He ya''ami, ira talifusö! Fehede niha wehedegu. Oroisa niha göi, na no mu''aro''ö, ba lö la''osilö''ögö, ba lö lasahe.[12]', '["Heb 9:15 b.t","MozI 13:15; 17:8 b.t.","MozII 12:40","Rom 4:13 b.t.","Rom 3:20; 5:20","MozV 4:35","Rom 8:2-4","Rom 3:9; 11:32; Gal 3:14"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 16, 'Ba no muŵa''ö gamabu''ula li andrö, khö Gaberahamo ba khö ma''uwunia; lö iŵa''ö: "ba khö ma''uwu sato"; ha samösa, no imane: "ba khö ma''uwumö", ya''ia Keriso. [13]', '["Heb 9:15 b.t","MozI 13:15; 17:8 b.t.","MozII 12:40","Rom 4:13 b.t.","Rom 3:20; 5:20","MozV 4:35","Rom 8:2-4","Rom 3:9; 11:32; Gal 3:14"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 17, 'Ba da''ö niŵa''ögu: Oroisa andrö, ni''a''aro''ö Lowalangi föna, ba tebai tewu''ai ba goroisa amakhoita andrö, si no öfa ngaotu a tölu ngafulu fakhe si akhi moroi khönia, fa lö''ö sa''ae moguna gamabu''ula li andrö mena''ö.[14]', '["Heb 9:15 b.t","MozI 13:15; 17:8 b.t.","MozII 12:40","Rom 4:13 b.t.","Rom 3:20; 5:20","MozV 4:35","Rom 8:2-4","Rom 3:9; 11:32; Gal 3:14"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 18, 'Na moroi ba goroisa sa wanema ondröita andrö ena''ö, ba tenga sa''ae moroi ba gamabu''ula li; ba khö Gaberahamo, ba no moroi ba gamabu''ula li, wa i''amualagö Lowalangi.[15]', '["Heb 9:15 b.t","MozI 13:15; 17:8 b.t.","MozII 12:40","Rom 4:13 b.t.","Rom 3:20; 5:20","MozV 4:35","Rom 8:2-4","Rom 3:9; 11:32; Gal 3:14"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 19, 'Bahe wisa goroisa andrö? Börö golalöwa andrö, wa tefatewu ia, irege so ma''uwu andrö, ba nitandrösaigö amabu''ula li andrö; ni''oroi''ö ba mala''ika goroisa andrö, nifa''ema zama''ema andrö.[16]', '["Heb 9:15 b.t","MozI 13:15; 17:8 b.t.","MozII 12:40","Rom 4:13 b.t.","Rom 3:20; 5:20","MozV 4:35","Rom 8:2-4","Rom 3:9; 11:32; Gal 3:14"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 20, 'Ba sama''ema, ba tenga ba zi ha samösa, ba Lowalangi, ba no ha samösa.[17]', '["Heb 9:15 b.t","MozI 13:15; 17:8 b.t.","MozII 12:40","Rom 4:13 b.t.","Rom 3:20; 5:20","MozV 4:35","Rom 8:2-4","Rom 3:9; 11:32; Gal 3:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3406114, 'NT', 'Galatia', 3, 21, 'Ba hadia, fa''udu goroisa ba gamabu''ula li Lowalangi andrö? Tenga si manö. Na no mube''e mena''ö goroisa, sangila mangorifi niha, ba si ndruhu moroi ba goroisa i''otarai fa''atulö andrö. [18]', '["Heb 9:15 b.t","MozI 13:15; 17:8 b.t.","MozII 12:40","Rom 4:13 b.t.","Rom 3:20; 5:20","MozV 4:35","Rom 8:2-4","Rom 3:9; 11:32; Gal 3:14"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 22, 'Ba ba zura, ba no tefa''u''u manö fefu hadia ia, barö mbawa horö, ena''ö moroi ba wamati khö Yesu Keriso tebe''e gamabu''ula li andrö, ba zamati andrö.[19]', '["Heb 9:15 b.t","MozI 13:15; 17:8 b.t.","MozII 12:40","Rom 4:13 b.t.","Rom 3:20; 5:20","MozV 4:35","Rom 8:2-4","Rom 3:9; 11:32; Gal 3:14"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 23, 'Ba me lö famati andrö na sa, ba no tetarogö ita, nifa''u''u barö mbawa goroisa, famati andrö nituturu, nifa''ele''ö dania,[20]', '["Faigi 4:2-3","Rom 10:4","Rom 7:4,6","Faigi 4:5,7; Yoh 1:12","Rom 6:3 b.t.; 13:14","Kol 3:11; Efes 2:14,15","Faigi 9:3,16"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 24, 'Ba no tobali samamaha ya''ita goroisa andrö, ba khö Keriso, ena''ö moroi ba wamati andrö atulö ita, iwa''ö Lowalangi.[21]', '["Faigi 4:2-3","Rom 10:4","Rom 7:4,6","Faigi 4:5,7; Yoh 1:12","Rom 6:3 b.t.; 13:14","Kol 3:11; Efes 2:14,15","Faigi 9:3,16"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 25, 'Ba me no so wamati andrö, ba tenga sa''ae barö mbawa zamamaha so ita. [22]', '["Faigi 4:2-3","Rom 10:4","Rom 7:4,6","Faigi 4:5,7; Yoh 1:12","Rom 6:3 b.t.; 13:14","Kol 3:11; Efes 2:14,15","Faigi 9:3,16"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 26, 'Dozi ami sa, ba no ono Lowalangi, moroi ba wamati andrö khö Keriso Yesu.[23]', '["Faigi 4:2-3","Rom 10:4","Rom 7:4,6","Faigi 4:5,7; Yoh 1:12","Rom 6:3 b.t.; 13:14","Kol 3:11; Efes 2:14,15","Faigi 9:3,16"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 27, 'Ha wa''ato ami sa, si no mubayagö idanö, ba khö Keriso, ba no mi''onukha Keriso.[24]', '["Faigi 4:2-3","Rom 10:4","Rom 7:4,6","Faigi 4:5,7; Yoh 1:12","Rom 6:3 b.t.; 13:14","Kol 3:11; Efes 2:14,15","Faigi 9:3,16"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 28, 'Ba da''ö lö niha Yehuda, ba lö Dawa Heleni, lö sawuyu ba lö si tenga sawuyu, lö ira matua, ba lö ira alawe; dozi ami sa, ba ha samösa, ba khö Keriso Yesu.[25]', '["Faigi 4:2-3","Rom 10:4","Rom 7:4,6","Faigi 4:5,7; Yoh 1:12","Rom 6:3 b.t.; 13:14","Kol 3:11; Efes 2:14,15","Faigi 9:3,16"]', NULL),
  (3406114, 'NT', 'Galatia', 3, 29, 'Ba na khö Keriso ami, ba no ma''uwu Gaberahamo ami, sanema ondröita, dali gamabu''ula li andrö.[26]', '["Faigi 4:2-3","Rom 10:4","Rom 7:4,6","Faigi 4:5,7; Yoh 1:12","Rom 6:3 b.t.; 13:14","Kol 3:11; Efes 2:14,15","Faigi 9:3,16"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 1, 'Ba da''ö niŵa''ögu: götö wa iraono zanema ondröita, ba lö faehu ira zawuyu, he wa''ae khönia fefu, hadia ia,', '[]', NULL),
  (3406117, 'NT', 'Galatia', 4, 2, 'barö mbawa zondrorogö so ia ba barö mbawa zamaigi-maigi yomo, gasa-gasa wa irugi baŵa nihuku namania.', '[]', NULL),
  (3406117, 'NT', 'Galatia', 4, 3, 'Si manö göi ita; götö wa iraono ita, ba no i''osawuyu ita famobörö andrö, ba guli danö.[1]', '["Kol 2:8,20"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 4, 'Ba me no irugi inöto andrö, ba ifatenge Nononia Lowalangi, ni''adonogö ndra alawe, ba nibe''e barö mbawa goroisa,[2]', '["MozI 49:10; Dan 9:25; Mat 5:17","Faigi 3:13,26"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 5, 'ena''ö ihöli zi so barö mbawa goroisa, ena''ö falukha ita, fa ono ita.[3]', '["MozI 49:10; Dan 9:25; Mat 5:17","Faigi 3:13,26"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 6, 'Ba me no ono ami, ba no ifatenge Lowalangi Geheha Nononia andrö, ba dödöda, si''ao andrö: He Aba, Ama![4]', '["Rom 8:15"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 7, 'Tobali tenga sa''ae sawuyu ndra''ugö, ono ndra''ugö; ba na ono, ba no sanema ondröita göi, ibe''e Lowalangi.[5]', '["Rom 8:16,17"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 8, 'Ba me luo da''ö sa, me lö saboto ba dödömi Lowalangi, ba no sawuyu Lowalangi bö''ö ami, si tenga to''ua Lowalangi.[6]', '["KorI 8:4, 12:2; Sin 115:4"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 9, 'Ba iada''e, me no aboto ba dödömi Lowalangi, me noa sa''ae aboto ba dödö Lowalangi göi ami, ba hana wa mifuli ami ba wamobörö andrö, sambö fa''abölö, ba si numana, si möi enoni zui ami ena''ö, samuza tö?[7]', '["Kol 2:20 b.t.","Rom 14:5"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 10, 'Hadia mifaigi ngaluo, ba baŵa, ba inötö, ba döfi?[8]', '["Kol 2:20 b.t.","Rom 14:5"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 11, 'Ata''u ndra''o ba khömi, ma dania zaya-zaya gölögu wohalöŵögu ba khömi andrö.', '[]', NULL),
  (3406117, 'NT', 'Galatia', 4, 12, 'Mibe''e tuladami ndra''odo, me no si mane ya''ami ndra''odo göi; he ya''ami ira talifusö, mangandrö ndra''o khömi. Lö hadia ia horömi khögu.', '[]', NULL),
  (3406117, 'NT', 'Galatia', 4, 13, 'Ba no mi''ila, wa no ambö wa''abe''e nösigu, me u''ombakha''ö khömi duria somuso dödö andrö, si föföna andrö. [9]', '["KorI 2:3","Mal 2:7; Yoh 13:20"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 14, 'Ba lö ni''ositengagömi fanandraigö ya''ami andrö, ba nösigu, ba lö sanuzu dödömi; hulö na mala''ika Lowalangi ndra''o, wanemami ya''o no, hulö na Keriso Yesu ndra''odo.[10]', '["KorI 2:3","Mal 2:7; Yoh 13:20"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 15, 'Ba heza so iada''e wa''odöŵa-döŵa dödömi no, niŵa''ömi? Ufaduhu''ö sa khömi, na tola mena''ö, ba no mikoe hörömi, ba no mibe''e khögu.', '[]', NULL),
  (3406117, 'NT', 'Galatia', 4, 16, 'Hadia, no tobali si fa''udu khömi ndra''odo, me no uŵa''ö khömi zi duhu?', '[]', NULL),
  (3406117, 'NT', 'Galatia', 4, 17, 'Tenga sa si sökhi wangaluira tödömi, edöna lafabali ami khögu, ena''ö mi''alui ira.[11]', '["Faigi 6:12; HalZin 20:30"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 18, 'Ba si sökhi sa, na te''alui zi zökhi, si lö mamalö-malö; ba tenga ha na sodo khömi.', '["Faigi 6:12; HalZin 20:30"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 19, 'He ya''ami, ira onogu, ni''adonogögu zamuza tö, safökhö khögu, irege tobali famaedo Keriso ami.[12]', '["KorI 4:15"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 20, 'Ena''ö na sodo khömi iada''e, ba ena''ö na u''ila ufalalini ligu; no abu dödögu ami.', '["KorI 4:15"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 21, 'Mi''ombakha''ö khögu, ya''ami, sedöna möi barö mbawa goroisa, hadia lö mifondrondrongo goroisa?', '[]', NULL),
  (3406117, 'NT', 'Galatia', 4, 22, 'Noa sa so ba zura: dombua nono Gaberahamo, sambua ba zawuyu andrö, ba sambua ba zi tenga sawuyu.[13]', '["MozI 16:15; 21:2 b.t.","Rom 9:7-9"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 23, 'Ba ba lala wo''ono ba niha tesöndra zi sambua, ba zawuyu andrö, ba si sambua, ba zi tenga sawuyu, ba moroi ba gamabu''ula li.[14]', '["MozI 16:15; 21:2 b.t.","Rom 9:7-9"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 24, 'Amaedola da''ö : ya''ia sa zi dua balö wawu''usa li andrö, si sambua, ba moroi ba hili Zina''i, so''ono ba wa''asawuyu, ya''ia Hagara andrö,[15]', '["MozII 19:18; MozI 16:1; Heb 12:18 b.t.","Heb 12:22; Fam 3:12","Yes 54:1","MozI 21:9","MozI 21:10,12"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 25, 'Hagara sa hili Zina''i andrö, ba li Ndrawa Ara, ba no falaŵa ia ba Yeruzalema ma''ökhö; noa sa sawuyu da''ö, awö ndraononia.', '["MozII 19:18; MozI 16:1; Heb 12:18 b.t.","Heb 12:22; Fam 3:12","Yes 54:1","MozI 21:9","MozI 21:10,12"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 26, 'Ba Yeruzalema yaŵa andrö, ba tenga sawuyu, ya''ia ninada, ya''ita fefu.[16]', '["MozII 19:18; MozI 16:1; Heb 12:18 b.t.","Heb 12:22; Fam 3:12","Yes 54:1","MozI 21:9","MozI 21:10,12"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 27, 'Noa sa so ba zura: "Omusoiö dödöu, ya''ugö, si lö ono, si lö irai madono; kara-karaini waiki ba owua-wua''ö dödöu, ya''ugö si lö fa''afökhö hulu, noa sa oya ndraono ba zi ha samösa andrö, no tohude ia, moroi ba zi so iramatua." [17]', '["MozII 19:18; MozI 16:1; Heb 12:18 b.t.","Heb 12:22; Fam 3:12","Yes 54:1","MozI 21:9","MozI 21:10,12"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 28, 'Ba ya''ami ira talifusö, ba no ono gamabu''ula li ami, dali Giza''aki.', '["MozII 19:18; MozI 16:1; Heb 12:18 b.t.","Heb 12:22; Fam 3:12","Yes 54:1","MozI 21:9","MozI 21:10,12"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 29, 'Ba hulö si mane ba da''ö, me igohi nisöndra ba lala Geheha nisöndra ba lala wo''ono ba niha, si manö göi iada''e.[18]', '["MozII 19:18; MozI 16:1; Heb 12:18 b.t.","Heb 12:22; Fam 3:12","Yes 54:1","MozI 21:9","MozI 21:10,12"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 30, 'Ba hadia niŵa''ö ba zura? Imane: "Tibo''ö zawuyu andrö awö nononia, lö''ö sa tola manema ondröita nono zawuyu andrö, awö nono zitenga sawuyu."[19]', '["MozII 19:18; MozI 16:1; Heb 12:18 b.t.","Heb 12:22; Fam 3:12","Yes 54:1","MozI 21:9","MozI 21:10,12"]', NULL),
  (3406117, 'NT', 'Galatia', 4, 31, 'Andrö, ya''ami ira talifusö, tenga ono zawuyu ita, no ono zi tenga sawuyu.', '["MozII 19:18; MozI 16:1; Heb 12:18 b.t.","Heb 12:22; Fam 3:12","Yes 54:1","MozI 21:9","MozI 21:10,12"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 1, 'Ba fa böi sawuyu ita, ba no i''efa''ö ita Keriso. Ba mi''abe''e''ö, böi mibe''e nifokalo mbagimi, ba wa''asawuyu.[1]', '["Faigi 2:4; 4:9; Yoh 8:32,36; HalZin 15:1"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 2, 'Hiza, ya''o, Faulo, uŵa''ö khömi, na mifaboto''ö ami, ba lö guna Keriso khömi.[2]', '["Faigi 2:21; HalZin 16:1"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 3, 'Ba ufaduhu''ö zui ba niha fefu, ha niha zamaboto''ö ya''ia, wa mo''ömö ia folo''ö oroisa ma''afefu.[3]', '["Faigi 6:13"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 4, 'No mifabali ami khö Keriso, na ba goroisa mi''alui wangatulömi, no aefa ami ba wa''ahakhö dödö andrö.', '[]', NULL),
  (3406119, 'NT', 'Galatia', 5, 5, 'Ya''ita sa, ba ba Geheha, moroi ba wamati andrö, tadöna-döna dötönafö andrö, fangatulö.[4]', '["Rom 5:1 b.t.; TimII 4:8"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 6, 'Ba khö Keriso Yesu sa, ba tebai wamoto, ba tebai wa lö muboto, ha famati andrö, si no abölö, ba wa''omasi andrö.[5]', '["Faigi 6:15; 3:28; KorI 7:19; 13:2"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 7, 'No sökhi wolo''ömi föna; ha niha zanenaŵa ya''ami, fa lö mifondrondrongo zi duhu?[6]', '["Faigi 1:1-3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 8, 'Fondrönisi andrö, ba tenga moroi ba zogaoni ya''ami. [7]', '["Faigi 1:6"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 9, 'Ha ma''ifu danömö roti, ba ahori i''aisöni gomböila roti fefu.[8]', '["KorI 5:6"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 10, 'No faduhu dödögu khömi, ba khö Zo''aya, wa ha da''ö dödömi, ba samakuyu ya''ami andrö, ba ilu''i dania hukunia, gofu ha niha ia.[9]', '["Faigi 1:7"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 11, 'Ba ya''odo andre, ya''ami ira talifusö, na u''ombakha''ö na ena''ö wamoto andrö, ba hana wa lagohi na ndra''odo? Noa sa döhö mena''ö, wa fatuwu röfa andrö.[10]', '["Faigi 6:12,14; KorI 1:23"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 12, 'Ena''ö na lafakhai''ö ira, samawukaisi tödömi andrö![11]', '["Sin 12:4"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 13, 'Ya''ami sa, ba ba wa böi sawuyu tekaoni ami, ya''ami ira talifusö, ha fa böi tobali lala nösi niha, wa tenga sawuyu ami, faoma mitolo nawömi, moroi ba wa''omasi andrö.[12]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 14, 'Oroisa andrö sa ma''afefu, ba ba zi ha sambua li andrö tetörö ia fefu, na imane: "Omasi''ö zahatö khöu, simane fa''omasiu ndra''ugö."[13]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 15, 'Ba na fara''u-ra''u ami, na faoma mi''a nawömi, ba mifaigi, fa böi faoma mibe''e ahori nawömi.', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 16, 'Ba da''ö niŵa''ögu: mitörö lala Geheha, ba lö mifalua wangisö nösi andrö.[14]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 17, 'Mangisö sa nösi si no fa''udu ba Geheha, ba omasi Geheha zi fa''udu ba nösi; faoma sa fa''udu ira khö nawöra, ena''ö lö milau zomasi ami ena''ö.[15]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 18, 'Ba na nifarou Geheha ami, ba tenga barö bawa goroisa so ami. [16]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 19, 'Ba no oroma mbua-bua nösi andrö, ya''ia wohorö, ba fa''ara''i-ra''iö, ba fa''atebakha[17]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 20, 'ba fame''e adu, ba fakelemusa, ba fatiusa, ba fasosota, ba fatötöisa, ba fönu, ba fanandraŵa, ba fa''udusa, ba fa''erosa,[18]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 21, 'ba fa''afökhö dödö, ba fomabu-mabu, ba femanga-manga, ba hadia ia na, nawönia, ba uhönagö uŵa''ö khömi, si mane niŵa''ögu no sa''ae khömi, solau si manö, ka tebai isöndra mbanua Lowalangi.[19]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 22, 'Ba bua-bua Geheha andrö, ba ya''ia wa''omasi, ba fa''omuso dödö, ba fa''ohahau dödö, ba fa''ebolo dödö, ba fa''asökhi dödö, ba fa''ebua dödö, ba fa lö faröi.[20]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 23, 'ba fa lö mofönu, ba famoni; na so zimanö, ba lö ihuku oroisa.[21]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 24, 'Ba tana khö Keriso Yesu andrö, ba no laforöfa nösira, awö wangisö andrö, ba awö wa''omasi si lö sökhi. [22]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 25, 'Na ba Geheha auri ita, ba datatörö göi lala Geheha.', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406119, 'NT', 'Galatia', 5, 26, 'Böi fayaŵa ita ba waya, böi ta''arö-arö nawöda, böi afökhö dödöda khö nawöda.[23]', '["KorI 8:9; FetI 2:16","Rom 13:9,10","Rom 7:6; 8:4,5; FetI 2:11","Rom 7:23; 8:6","Rom 8:14; 6:14","KorI 6:9 b.t.; Kol 3:5","Fam 21:8; KorII 12:20; KorI 11:19","Rom 13:13; Efes 5:5","Efes 5:9; Rom 14:7","TimI 1:9","Faigi 2:19; Rom 6:6","Fil 2:3"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 1, 'He ya''ami ira talifusö, na so niha sosala, si lö mudöna-döna, ba mifuli mi''ohe ba zi sökhi zi manö Eheha wa''ebolo dödö andrö, ya''ami, si so Eheha, ba ya''ugö faigi, fa böi tetandraigö ndra''ugö göi.[1]', '["TesI 5:14; Mat 18:15 b.t.; Sin 141:5","Rom 15:1-3; Kol 3:13; Yoh 15:12","KorI 8:2","KorI 4:5,6","Rom 14:12; Amaed 9:12"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 2, 'Faoma mi''onoro noro dödö nawömi, ba no mi''o''ö goroisa Keriso andrö. [2]', '["TesI 5:14; Mat 18:15 b.t.; Sin 141:5","Rom 15:1-3; Kol 3:13; Yoh 15:12","KorI 8:2","KorI 4:5,6","Rom 14:12; Amaed 9:12"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 3, 'Na so zanguma''ö tödönia, sebua ia, he ŵa''ae si lö boto sa atö, ba no ilimo ia.[3]', '["TesI 5:14; Mat 18:15 b.t.; Sin 141:5","Rom 15:1-3; Kol 3:13; Yoh 15:12","KorI 8:2","KorI 4:5,6","Rom 14:12; Amaed 9:12"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 4, 'Yamufaigi wolaunia zamösana, ba ha khönia wanunonia ya''ia, ba lö ifarongogö ba niha bö''ö.[4]', '["TesI 5:14; Mat 18:15 b.t.; Sin 141:5","Rom 15:1-3; Kol 3:13; Yoh 15:12","KorI 8:2","KorI 4:5,6","Rom 14:12; Amaed 9:12"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 5, 'Ilu''i-lu''i sa noronia zamösana.[5]', '["TesI 5:14; Mat 18:15 b.t.; Sin 141:5","Rom 15:1-3; Kol 3:13; Yoh 15:12","KorI 8:2","KorI 4:5,6","Rom 14:12; Amaed 9:12"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 6, 'Ba ha niha nifahaö, ba daroma li andrö, ba ya ha sara dödö khö zamahaö ya''ia, ba zi sökhi, fefu. [6]', '["KorI 9:11,14","Yob 13:9; Luk 16:25","Amaed 22:8; Yes 8:10; Rom 8:13","TesII 3:13; Sin 126:5","FetII 1:7"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 7, 'Böi elungu ami; lö ibe''e ni''o''aya ia Lowalangi. Hadia nitaru niha sa, da''ö göi nibasinia dania.[7]', '["KorI 9:11,14","Yob 13:9; Luk 16:25","Amaed 22:8; Yes 8:10; Rom 8:13","TesII 3:13; Sin 126:5","FetII 1:7"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 8, 'Ha niha zanaru ba nösinia, ba moroi ba nösi ibasi dania wa''atekiko, ba sanaru ba Geheha, ba moroi ba Geheha ibasi dania wa''auri si lö aetu andrö.[8]', '["KorI 9:11,14","Yob 13:9; Luk 16:25","Amaed 22:8; Yes 8:10; Rom 8:13","TesII 3:13; Sin 126:5","FetII 1:7"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 9, 'Ba böi atage ita, wolau si sökhi andrö; na inötönia dania, ba mamasi ita, na lö atage ita.[9]', '["KorI 9:11,14","Yob 13:9; Luk 16:25","Amaed 22:8; Yes 8:10; Rom 8:13","TesII 3:13; Sin 126:5","FetII 1:7"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 10, 'Ba talau sa''ae zi sökhi, me no baŵania khöda, ba niha fefu, ba oföna ba zi ha sara lala wamati, wöda.[10]', '["KorI 9:11,14","Yob 13:9; Luk 16:25","Amaed 22:8; Yes 8:10; Rom 8:13","TesII 3:13; Sin 126:5","FetII 1:7"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 11, 'Mifaigi ha wa''ebua dandra zura khögu, wanuragu khömi, tangagu andre.', '["Faigi 5:2,11; Fil 3:18","Faigi 5:3; HalZin 15:10; Mat 23:3,4","Faigi 2:19; KorI 2:2","Faigi 5:6; KorII 5:17","Fil 3:16; Sin 125:4-5","KorII 4:10","Fil 4:23; TimII 4:22"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 12, 'Ha niha ira, sangalui, ena''ö la''omasi''ö ira, dali nösi niha, da''ö zango''ou ya''ami, ena''ö mifaboto''ö ami, ha fa böi tefakao ira, moroi ba röfa Keriso andrö. [11]', '["Faigi 5:2,11; Fil 3:18","Faigi 5:3; HalZin 15:10; Mat 23:3,4","Faigi 2:19; KorI 2:2","Faigi 5:6; KorII 5:17","Fil 3:16; Sin 125:4-5","KorII 4:10","Fil 4:23; TimII 4:22"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 13, 'Ya''ira sa göi, samaboto''ö ya''ira andrö, ba lö la''o''ö goroisa, ba omasi ira, na mifaboto''ö ami, ena''ö lasuno ira, ba nösimi andrö.[12]', '["Faigi 5:2,11; Fil 3:18","Faigi 5:3; HalZin 15:10; Mat 23:3,4","Faigi 2:19; KorI 2:2","Faigi 5:6; KorII 5:17","Fil 3:16; Sin 125:4-5","KorII 4:10","Fil 4:23; TimII 4:22"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 14, 'Ba ya''o, ba lö ufa''amöi ba dödögu wanuno ya''o, na tenga ba röfa Zo''aya ya''ita andrö, Yesu Keriso, ba niforöfa ösi guli danö khögu, ba ba niforöfa ya''o, ba nösi guli danö.[13]', '["Faigi 5:2,11; Fil 3:18","Faigi 5:3; HalZin 15:10; Mat 23:3,4","Faigi 2:19; KorI 2:2","Faigi 5:6; KorII 5:17","Fil 3:16; Sin 125:4-5","KorII 4:10","Fil 4:23; TimII 4:22"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 15, 'Lö guna wamoto, ba lö guna wa lö muboto, ha niha si bohou zoguna.[14]', '["Faigi 5:2,11; Fil 3:18","Faigi 5:3; HalZin 15:10; Mat 23:3,4","Faigi 2:19; KorI 2:2","Faigi 5:6; KorII 5:17","Fil 3:16; Sin 125:4-5","KorII 4:10","Fil 4:23; TimII 4:22"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 16, 'Ba ha wa''ato zanörö lala da''ö, ba ndrafalukha wa''ohahau dödö, ba fa''ahakhö dödö, ba yasi manö göi Ndraono Gizeraeli andrö, khö Lowalangi.[15]', '["Faigi 5:2,11; Fil 3:18","Faigi 5:3; HalZin 15:10; Mat 23:3,4","Faigi 2:19; KorI 2:2","Faigi 5:6; KorII 5:17","Fil 3:16; Sin 125:4-5","KorII 4:10","Fil 4:23; TimII 4:22"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 17, 'Böi yamubusi sa''ae dödögu niha, ha niha ia. Ugohe-gohe ba nösigu andre lade andrö, khö Yesu.[16]', '["Faigi 5:2,11; Fil 3:18","Faigi 5:3; HalZin 15:10; Mat 23:3,4","Faigi 2:19; KorI 2:2","Faigi 5:6; KorII 5:17","Fil 3:16; Sin 125:4-5","KorII 4:10","Fil 4:23; TimII 4:22"]', NULL),
  (3406121, 'NT', 'Galatia', 6, 18, 'Yafalukha dödömi wa''ebua dödö Zo''aya ya''ita, Yesu Keriso, ya''ami ira talifusö! Yaduhu.[17]', '["Faigi 5:2,11; Fil 3:18","Faigi 5:3; HalZin 15:10; Mat 23:3,4","Faigi 2:19; KorI 2:2","Faigi 5:6; KorII 5:17","Fil 3:16; Sin 125:4-5","KorII 4:10","Fil 4:23; TimII 4:22"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 1, 'Faulo zanura da''e, sinenge Keriso Yesu, moroi ba nilau dödö Lowalangi, ba ni''amoni''ö andrö, si so ba Nefeso, ba zamati khö Keriso Yesu.[1]', '["KorI 1:2; HalZin 19","Rom 1:7"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 2, 'Yafalukha ami wa''ebua dödö, ba fa''ohahau dödö, khö Namada Lowalangi ba khö Zo''aya ya''ita, Yesu Keriso[2]', '["KorI 1:2; HalZin 19","Rom 1:7"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 3, 'Nisuno Lowalangi Zo''aya ya''ita, Yesu Keriso, Amania, si no mamahowu''ö ya''ita, fefu ngawalö wamahowu''ö Geheha andrö, ba zorugo, ba khö Keriso.[3]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 4, 'Itörö wanutuyunia ya''ita, ba khönia andrö, föna wolata danö, ena''ö sohau-hau ita, si lö sinegu, fönania.[4]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 5, 'Moroi ba wa''omasinia ita, wa no ihönagö ihonogöi, ena''ö ono ita khönia, moroi khö Yesu Keriso, dali zomasi ia, nilau dödönia; [5]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 6, 'ba wanuno lakhömi wa''ebua dödönia, ni''amualagönia khöda, ba zomasi ia andrö.[6]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 7, 'Ba da''ö so khöda wangöhöli andrö, ba ndronia, fangefa lalö andrö, dali wa no a''oi so wa''ebua dödönia,[7]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 8, 'nihönania fangoroma''ö khöda, ba ngawalö wa''atua-tua fefu, ba ba ngawalö wa''aboto ba dödö,', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 9, 'noa sa ibokai khöda si no tobini andrö, nilau dödönia, dali zomasi ia, nihonogöinia tödönia,[8]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 10, 'nifatörönia ba ginötö ndröfi andrö, ba wamarahugö fefu, hadia ia, ba khö Keriso, he si so ba zorugo, ba he si so ba guli danö, ba khönia.[9]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 11, 'Ba da''ö tasöndra göi dana khöda andrö, ya''ita nihonogöi föna sa''ae, dali nihuku zamalua fefu, hadia ia, ba gera-era nilau dödönia andrö, [10]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 12, 'ena''ö fanuno lakhöminia ita, ya''ita, si no tohöna manötöna khö Keriso.[11]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 13, 'Ba da''ö göi so ami, me no mirongo daroma li si duhu andrö, turia somuso dödö andrö, fangorifimi, ba ba da''ö te''a''aro''ö göi ami, Eheha ba gamabu''ula li andrö, ni''amoni''ö, me no mamati ami.[12]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 14, 'Eheha andrö we''e-we''e dödö, ba gondröita andrö khöda, ba wangorifi tana khönia andrö, ba wanuno lakhöminia andrö.[13]', '["KorII 1:3","Faigi 3:11; TimII 1:9; Kol 1:22","Faigi 2, 4. Rom 8, 29","Rom 3:24; Mat 3:17","Kol 1:14; FetI 1:18; Efes 2:7; Rom 9:23","Faigi 3:9 b.t.","Kol 1:20","Faigi 1:4; Rom 8:28 b.t.","HalZin 26:6,7","Kol 1:5,6; KorII 1:22","Faigi 4:30; KorII 5:5"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 15, 'Andrö ya''odo göi, me no urongo wamati andrö, ba khömi, khö Zo''aya ya''ita, Yesu, ba fa''omasimi ni''amoni''ö andrö fefu,[14]', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 16, 'ba lö ubato wangandrö saoha gölö, ba khömi andrö, itörö ligu, ba wangandrögu,[15]', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3406024, 'NT', 'Efeso', 1, 17, 'ena''ö ibe''e khömi Geheha ba wa''atua-tua andrö Lowalangi Zo''aya ya''ita andrö, Yesu Keriso, Ama lakhömi andrö, Eheha ba wama''ele''ö, ba wa''aboto ba dödömi ia.', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 18, 'Ena''ö tefehaga hörö dödömi, fa mi''ila hadia dötönafö, ba wogaoninia andrö,', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 19, 'ba he wisa, wa no a''oi so lakhömi gondröitania andrö, ba ni''amoni''ö andrö, ba he wisa ginötö wa''abölönia andrö, si no fahöna, ba khöda, samati, dali wolaunia ha wa''abe''e wa''abölönia andrö.[16]', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 20, 'Da''ö zi no i''oroma''ö ba khö Keriso, me isusugi moroi ba ngai zi mate, ba me ifedadao ba gambölönia, ba zorugo,[17]', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 21, 'alaŵa yaŵa zamatörö andrö fefu, ba yaŵa zalaŵa andrö, ha yaŵa zabölö, ba yaŵa zo''aya andrö, ba yaŵa zi so töi, fefu, nitötöi, tenga ha ba götö danö da''e, ba götö dania göi.[18]', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 22, 'Ba no ibe''e barö gahenia fefu, hadia ia, ba no ibe''e högö hadia ia fefu ia, ba mbanua andrö,[19]', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL),
  (3406024, 'NT', 'Efeso', 1, 23, 'si no tobali botonia, ahonoa zamo''ahonoa fefu hadia ia, ba khöra fefu.[20]', '["Kol 1:3, 4","Fil 1:3","Faigi 3:7,20; Kol 2:12","FetI 3:22; Sin 110:1","Fil 2:9 b.t.","KorI 15:27; Efes 4:15; 5:23","Faigi 3:19; KorI 12:27; Kol 2:9"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 1, 'Khömi göi, si no mate föna, ba golalöŵami andrö, ba ba horömi andrö,[1]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 2, 'nitörömi föna, dali huku ba guli danö andre, dali zalaŵa andrö, sokhö fa''abölö andrö, ba dalu mbanua, bekhu andrö, sabölö iada''e na, ba ndraono wa lö molo''ö andrö,[2]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 3, 'nitöröda göi föna, dozi ita, ba wangisö nösida andrö, me talau zomasi nösi, awö gaso''ala dödöda andrö, ba me to''ua iraono si göna fönu ita, si mane tanö bö''ö göi.[3]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 4, 'Ba Lowalangi andrö, si no a''oi so fa''ahakhö dödö, ba wa''omasinia andrö, si no fahöna, fa''omasinia ita,[4]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 5, 'he me no si mate ita, ba golalöŵa andrö, ba no i''orifi ita, awö Keriso — fa''ahakhö dödö, wa no auri ami — [5]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 6, 'ba no ifao wanusugi ya''ita ba famawu''a ya''ita, fama''aso ya''ita ba mbanua zorugo, ba khö Keriso Yesu,[6]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 7, 'ena''ö i''oroma''ö ba götö dania wa''ahakhö dödönia andrö, si no a''oi so, si no fahöna, ba wa''ebua dödönia khöda, ba khö Keriso Yesu.[7]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 8, 'Fa''ahakhö dödö sa, wa no auri ami, moroi ba wamati, ba tenga moroi khömi da''ö, no buala Lowalangi,[8]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 9, 'tenga moroi ba mbua-bua, fa böi isuno ia niha.[9]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 10, 'Nifazökhinia sa ita, nifazökhi ba khö Keriso Yesu, ba mbua-bua si sökhi, ba nihonogöi Lowalangi ya''ita, föna sa''ae, ena''ö tatörö.[10]', '["Kol 2:13","Faigi 6:12; Tit 3:3 b.t.; KorII 4:4","Kol 3:7; Rom 8:7,8","Faigi 1:5-7; YohI 3:1","Faigi 5:14; Kol 2:12 b.t.; HalZin 15:11","Fil 3:20","Faigi 1:7","Rom 3:24; Gal 2:16","Rom 3:27","Tit 2:14; KorII 5:17"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 11, 'Andrö böi mi''olifugö ami, ya''ami si no niha baero föna, to''ua ya''ami, niwa''ö si lö muboto, ba zi so töi niboto, niboto tanga, ba nösi,[11]', '["Rom 2:26,29; Kol 2:13","Rom 9:4"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 12, 'wa no lö Keriso khömi, me luo da''ö, wa no tenga so''urakha ami ba mbanua Ndraono Gizeraeli, wa no niha bö''ö ami, ba wawu''usa li andrö, ba gamabu''ula li andrö, wa no si lö Lowalangi, ba guli danö andre.[12]', '["Rom 2:26,29; Kol 2:13","Rom 9:4"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 13, 'Ba iada''e, ba khö Keriso Yesu, ba no tobali ahatö ami, ya''ami, si no aröu föna, börö ndro Keriso andrö.[13]', '["Yes 57:19; Efes 1:7","Yes 9:6; Kol 1:20","Kol 2:14","Kol 1:21"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 14, 'Fangatulöda sa ia, ya''ia, si no mangorudugö si dua ngasi andrö, si no manudugö oto''oto, öli andrö,[14]', '["Yes 57:19; Efes 1:7","Yes 9:6; Kol 1:20","Kol 2:14","Kol 1:21"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 15, 'fa''udusa andrö, me no iheta goroisa amakhoita, nifakhoi andrö, ba nösinia, ena''ö ibali''ö niha si bohou, si ha samösa, zi darua andrö, ba khönia, wangatulö''ö ya''ira,[15]', '["Yes 57:19; Efes 1:7","Yes 9:6; Kol 1:20","Kol 2:14","Kol 1:21"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 16, 'ba ena''ö i''atulö''ö khö Lowalangi zi dua ngasi andrö, ba mboto andrö, si ha sambua, moroi ba röfa andrö, na no ibunu wa''udusa andrö, ba da''ö yaŵa.[16]', '["Yes 57:19; Efes 1:7","Yes 9:6; Kol 1:20","Kol 2:14","Kol 1:21"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 17, 'Ba me so ia, ba ituriagö wangatulö, turia somuso dödö, khömi, saröu, ba fangatulö göi ba zahatö. [17]', '["Faigi 2:13; HalZin 10:36","Faigi 3:12; Rom 5:2","Faigi 2:12; 3:6","KorI 3:9 b.t.; Yes 28:16","Faigi 4:16","KorI 3:16; FetI 2:5"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 18, 'Me moroi khönia, wa no faoma so khöda lala khö Nama, ha sambua Geheha.[18]', '["Faigi 2:13; HalZin 10:36","Faigi 3:12; Rom 5:2","Faigi 2:12; 3:6","KorI 3:9 b.t.; Yes 28:16","Faigi 4:16","KorI 3:16; FetI 2:5"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 19, 'Ba tobali tenga sa''ae niha bö''ö ami, ba tenga sa''ae si fatewu, no banua ni''amoni''ö ami, ba soroiyomo Lowalangi,[19]', '["Faigi 2:13; HalZin 10:36","Faigi 3:12; Rom 5:2","Faigi 2:12; 3:6","KorI 3:9 b.t.; Yes 28:16","Faigi 4:16","KorI 3:16; FetI 2:5"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 20, 'nifa''anö ba dete dane-dane andrö, sinenge andrö ba sama''ele''ö, ba zi no tobali toyo ba watalinga Keriso Yesu,[20]', '["Faigi 2:13; HalZin 10:36","Faigi 3:12; Rom 5:2","Faigi 2:12; 3:6","KorI 3:9 b.t.; Yes 28:16","Faigi 4:16","KorI 3:16; FetI 2:5"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 21, 'ba zanöi tomosa andro, ma''asambua, nifa''anö, tobali osali ni''amoni''ö, ba khö Zo''aya, [21]', '["Faigi 2:13; HalZin 10:36","Faigi 3:12; Rom 5:2","Faigi 2:12; 3:6","KorI 3:9 b.t.; Yes 28:16","Faigi 4:16","KorI 3:16; FetI 2:5"]', NULL),
  (3406025, 'NT', 'Efeso', 2, 22, 'ba nifa''anö göi ya''ami, awö, omo Lowalangi, ba Geheha.[22]', '["Faigi 2:13; HalZin 10:36","Faigi 3:12; Rom 5:2","Faigi 2:12; 3:6","KorI 3:9 b.t.; Yes 28:16","Faigi 4:16","KorI 3:16; FetI 2:5"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 1, 'Andrö ya''o, Faulo, nikuru andrö khö Keriso, börö ami, ya''ami niha baero föna[1]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 2, 'na no mirongo nihonogöi Lowalangi, ba wa''ebua dödönia andrö, nibe''e ba dangagu, ba khömi andrö,[2]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 3, 'wa no mu''oroma''ö khögu zi no tobini andrö, ba wama''ele''ö, nitörö ligu mege ma''ifu. [3]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 4, 'Ba da''ö tola mi''ila wa''aboto ba dödögu zi no tobini andrö, khö Keriso, na mibaso,[4]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 5, 'si lö mu''oroma''ö ba nono niha, ba götö föna, si mane fangoroma''ö ya''ia iada''e, ba zinengenia ba ba zama''ele''ö andrö khönia, ni''amoni''ö, ba Geheha,[5]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 6, 'wa nifanema göi niha baero, ba gondröita andrö, wa no ndroto-ndroto göi ira ba sanema, ba gamabu''ula li andrö, ba khö Keriso Yesu, moroi ba duria somuso dödö andrö.', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 7, 'Ba da''ö no tobali enoni ndra''o, dali mbuala andrö fa''ebua dödö Lowalangi, nibe''e khögu, balazi wolaunia, ba wa''abölönia,[6]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 8, 'ya''o, fondrege zide-ide ni''amoni''ö, si no falukha fa''ebua dödö andrö, ba wangombakha ba niha baero, wa no a''oi so khö Keriso, wa no lö famaedo,[7]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 9, 'ba ba wamotokhi ba dödöra, he wisa nihonogöi, ba zi no tobini andrö, si no mubini''ö, götö-götö wa''ara, ba dödö Lowalangi, somböi fefu hadia ia.[8]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 10, 'Ena''ö te''oroma''ö iada''e ba zamatörö andrö ba ba zalaŵa andrö, ba zorugo, ba mbanua Keriso andrö, zi siŵa mbalö wa''atua-tua Lowalangi andrö,[9]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 11, 'dali gera-era andrö, si no götö-götö wa''ara, nifaluania ba khö Keriso Yesu, So''aya ya''ita,[10]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 12, 'ba zi so khöda wa lö aiŵö, awö lala, ba wanötöna, moroi ba wamati andrö khönia. [11]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 13, 'Andrö u''andrö, ena''ö lö atage ndra''o, ba wamakao andrö khögu, salahimi; si tobali lakhömimi.[12]', '["Faigi 4:1; HalZin 21:33; TimII 1:8","Gal 2:7 b.t.","Faigi 1:9 b.t.; Gal 1:12","Rom 16:25 b.t.","KorI 2:10","Rom 1:5","KorI 15:9,10","Kol 1:15 b.t.; Rom 16:25","FetI 1:12","Faigi 1:4,9","Faigi 2:18; Heb 4:16","TesI 3:3; Kol 1:24"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 14, 'Andrö ubalöduhini tou danö, föna Nama,[13]', '["Faigi 1:3","Faigi 6:10; Kol 1:11 b.t.","Yoh 14:23","Kol 2:2 b.t.","Rom 16:25 b.t.","Fil 4:20"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 15, 'ba zoroi töi soi fefu, he ba zorugo, ba he ba guli danö,', '["Faigi 1:3","Faigi 6:10; Kol 1:11 b.t.","Yoh 14:23","Kol 2:2 b.t.","Rom 16:25 b.t.","Fil 4:20"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 16, 'ena''ö ibe''e khömi, moroi ba lakhöminia andrö, si no a''oi so, fa tedou wa''abölömi, moroi ba Gehehania, ba niha bakha andrö; [14]', '["Faigi 1:3","Faigi 6:10; Kol 1:11 b.t.","Yoh 14:23","Kol 2:2 b.t.","Rom 16:25 b.t.","Fil 4:20"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 17, 'ena''ö monahia Keriso ba dödömi, ba wamati andrö,[15]', '["Faigi 1:3","Faigi 6:10; Kol 1:11 b.t.","Yoh 14:23","Kol 2:2 b.t.","Rom 16:25 b.t.","Fil 4:20"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 18, 'ena''ö soŵa''a ami, ba wa''omasi, ba nifodane-dane, ena''ö tola aboto ba dödömi, awö ni''amoni''ö andrö fefu, he wisa wa''ebolo, ba he wisa wa''anau, ba he wisa wa''abakha, ba he wisa wa''alaŵa,', '["Faigi 1:3","Faigi 6:10; Kol 1:11 b.t.","Yoh 14:23","Kol 2:2 b.t.","Rom 16:25 b.t.","Fil 4:20"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 19, 'ba ena''ö aboto ba dödömi wa''omasi Keriso andrö ita, si tebai aboto ba dödö niha mena''ö, ena''ö tehöna khömi zi no fahöna andrö khö Lowalangi, fefu.[16]', '["Faigi 1:3","Faigi 6:10; Kol 1:11 b.t.","Yoh 14:23","Kol 2:2 b.t.","Rom 16:25 b.t.","Fil 4:20"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 20, 'Ba ya''ia, sangila manalu''i na fefu hadia ia, wolau, fa aröu italu''i ni''andröda, awö zi faböbö ba gera-erada, dali wa''abölö andrö, si no abölö ba dödöda,[17]', '["Faigi 1:3","Faigi 6:10; Kol 1:11 b.t.","Yoh 14:23","Kol 2:2 b.t.","Rom 16:25 b.t.","Fil 4:20"]', NULL),
  (3406029, 'NT', 'Efeso', 3, 21, 'ya''ia nifosumange ba mbanua andrö, ba ba khö Keriso Yesu, götö-götö wa''ara, irugi zi lö aetu! Yaduhu.[18]', '["Faigi 1:3","Faigi 6:10; Kol 1:11 b.t.","Yoh 14:23","Kol 2:2 b.t.","Rom 16:25 b.t.","Fil 4:20"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 1, 'Ba u''andrö khömi, ya''o nikuru andre, ba khö Zo''aya, ena''ö mitörö zi nangea lala nikaoni andrö, meno mukaoni ami. [1]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 2, 'Ya a''oi so wa lö fayaŵa ami, awö wa''asökhi dödö, awö wa''ebolo dödö, mibologö dödömi khö nawömi, mi''omasi''ö ia;[2]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 3, 'mi''oigö dödömi, ena''ö lö tebulö wa ha sara dödö, ena''ö faböbö ami, famaböbö fa''atulö andrö:[3]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 4, 'Ha sambua mboto, ba ha sambua dödö, si mane fogaoni ya''ami göi, ba zi ha sara fanötöna, ba nikaoni ya''ami.[4]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 5, 'Ha samösa Zo''aya, ha sambua wamati, ha sambua wamayagö idanö;[5]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 6, 'ha sambua Lowalangi ba Amara fefu, yaŵara fefu, ba sanörö ya''ira fefu, ba ba dödöra fefu. [6]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 7, 'Ba dozi ita, ba no mube''e wa''ebua dödö andrö, dali ndrohu-ndrohu mbuala Keriso andrö;[7]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 8, 'andrö imane sama''ele''ö: "No numalö ia miyaŵa, ba no i''ohe nikuru, ba no mamuala ia ba niha."[8]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 9, 'Ba hadia geluaha, wa "no numalö ia miyaŵa", na tenga wa "no numalö ia mitou göi ua, ba mbanua tou?[9]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 10, 'Si no numalö mitou andrö, da''ö göi zi no numalö miyaŵa, yaŵa zorugo fefu, ena''ö ifo''ahonoa fefu, hadia ia.[10]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 11, 'Ba ya''ia göi zangohonogöi: sinenge ösa, ba sama''ele''ö ösa, ba sangombakha turia somuso dödö ösa, ba kubalo ösa, ba samahaö,[11]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 12, 'ba wangehao ni''amoni''ö andrö, ba halöŵö andrö, nihalö, ba wama''anö boto Keriso andrö,[12]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 13, 'ena''ö oi takhamö, fa ha sara dödö wamati, ba fa''aboto ba dödöda Nono Lowalangi, fa ira matua, si no mo''ahonoa, ita, dali ndrohu-ndrohu wa''ebua Keriso andrö, si no mo''ahonoa.[13]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 14, 'Böi sa''ae iraono ita, nifaheu-heu ba nifangörö-ngörö ba nangi wamahaö andrö, fefu, hadia ia ngawalö, moroi ba walimosa niha, moroi ba wa''onekhe, ba wolohe ba gowöhöna;[14]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 15, 'ena''ö na atulö ita, ba wa''omasi andrö, ba ena''ö na manöi fefu hadia ia, ba khönia, si no tobali högö, Keriso.[15]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 16, 'Ba khönia mobörö, wa tefa''anö mboto andrö, ma''asambua, awö wa tefaböbö, ba wamakhai andrö fefu, ba dolo-tolo andrö, dali wa''abölö andrö, ba zi no motana zambuana, ena''ö tobali boto, ba wa''atedounia, ba wa''omasi.[16]', '["Faigi 3:1; 6:20; Kol 1:10; TesI 2:12","Kol 3:12; Rom 12:10","Kol 3:13,14; Rom 12:16","Rom 12:5; KorI 12:13,27","Mat 23:8","Faigi 3:14,15; KorI 8:6; Mal 2:10","Rom 12:3,6; FetI 4:10","Sin 68:19","FetI 3:19; Mat 12:40","Yoh 3:13","KorI 12:28; HalZin 21:8; FetI 5:2","Faigi 2:22","Faigi 3:18,19; Luk 6:40","KorI 3:1; Kol 2:8","Faigi 3:17; 3:23; Kol 2:19","Faigi 2:21; Rom 12:4 b.t.; KorI 12:12 b.t."]', NULL),
  (3406041, 'NT', 'Efeso', 4, 17, 'Ba da''ö niwa''ögu, ba ufaduhu''ö, ba khö Zo''aya, ena''ö amuatami andrö, ba böi sa''ae si mane amuata niha baero göi, ba waya-faya dödöra andrö,[17]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 18, 'si no mu''ogömi-gömisi tödö, si no olifu wa''auri andrö, khö Lowalangi, ba wa lö aboto ba dödöra, ba wa''abe''e dödöra andrö,', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 19, 'sanörö lala hokha, me no mate bakha dödöra, ba wamalua si lö sökhi andrö, fefu, ba wa tebai abuso.[18]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 20, 'Ba ya''ami, ba tenga si manö wanöngönimi Keriso,[19]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 21, 'na no mirongo atö ia, ba na no mufahaö ami, ba khönia, wa khö Yesu so zi duhu,[20]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 22, 'wa niheta niha si tohöna andrö khömi, ba lala föna andrö, samakiko ya''ia, ba wangisö andrö, ba wa''elungu.[21]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 23, 'Ba nibohouni ami, ba gera-era dödömi andrö,[22]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 24, 'ba mi''onukha niha si bohou andrö, nibe''e famaedo Lowalangi, wamazökhi ya''ia, ba wa''atulö dödö ba ba wa''ohau-hau, ba zi duhu.[23]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 25, 'Andrö miböhöli waya, faoma si duhu milau khö nawömi, me no faoma ndroto-ndroto ita.[24]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 26, 'Na mofönu, ba böi mifazökhi horö; böi mi''ekhugö luo ba wönumi.[25]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 27, 'Ba böi mifonaha Gafökha.[26]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 28, 'Si no managö-nagö, ba böi yamanagö-nagö sa''ae, ba yamohalöŵö, yamufazökhi zi sökhi, tangania, ena''ö so khönia, ba wame''e ba zi numana.[27]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 29, 'Böi alua ba mhewemi wehede si lö sökhi, he ha sambua li; hadia zonahia, ba wanga''azökhi, na moguna, ena''ö omasi zamondrongo.[28]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 30, 'Ba köi mibusi dödö Geheha ni''amoni''ö andrö, fangaromi, ba luo wangorifi andrö.[29]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 31, 'Fefu ngawaiö wotötöisa, ba fa''abao dödö, ba fönu ba fagua-guasa, ba fanandraŵa, ba yatebato khömi, awö fefu, hadia ia zi lö sökhi.[30]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406041, 'NT', 'Efeso', 4, 32, 'Ba faoma mihaogö-haogö khö nawömi, faoma mihakhösi tödö, faoma mibe''e aefa zala nawömi, si mane fangefa''ö Lowalangi khömi göi, ba khö Keriso.[31]', '["Rom 1:21; FetI 4:3","Rom 1:24 b.t.","Tit 2:11,12","Yoh 1:17","Kol 3:8 b.t.","Rom 12:2","Kol 3:10; Rom 13:14","Sakh 8:16; Kol 3:9","Sin 4:5; 37:8; Yak 1:19,20","Yak 4:7","TesI 4:11","Faigi 5:4; Mat 12:36; Kol 4:6; 3:16","Faigi 1:13,14","FetI 2:1","Kol 3:12,13; Mat 18:35"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 1, 'Ba mi''o''ö khö Lowalangi, si mane iraono omasiö.[1]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 2, 'Ba mitörö lala wa''omasi andrö, si mane fangomasi''ö Keriso ya''ita, awö wa no ibe''e ia salahida, ame''ela ba sumange, samohua khö Lowalangi.[2]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 3, 'Ba fohorö, ba hadia ia ngawalö wa''ara''i-ra''iö fefu, ba fa''omasi gana''a, ba böi na i terongo ba khömi, si manö zoadu ba ni''amoni''ö.[3]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 4, 'Ba fehede si lö sökhi, ba faya-faya, ba fawudesa si lö boto, si lö moadu; si sökhinia, na fangandrö saoha gölö.[4]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 5, 'Da''ö sa ya''aboto ba dödömi: lö mo''urakha ba mbanua Keriso, ba mbanua Lowalangi andrö, zohorö, ba sira''i-ra''iö, ba somasi ana''a, ha niha ia, si no same''e adu.[5]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 6, 'Böi yamufaelungu ami niha, fehede si lö boto; da''ö sa mbörö wa mofönu Lowalangi ba ndraono si lö mamondrongo li.[6]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 7, 'Andrö böi awöra ami.', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 8, 'Noa sa sogömi-gömi ami föna, ba iada''e, ba no haga ami ba khö Zo''aya; lala ndraono haga mitörö, [7]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 9, 'Bua-bua haga sa, ba ya''ia ngawalö wa''asökhi dödöda, khö nawöda, awö wa''atulö dödö, awö wa''aduhu.[8]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 10, 'Ba mitimba tödömi, hadia zomasi Zo''aya,[9]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 11, 'ba böi fao ami ba wama''ua bua-bua wa''ogömi-gömi andrö, si lö boto, mi''otu''ö na i göi.[10]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 12, 'Hadia nilaura sa, ba zi tobini, ba aila ita na i tatötöi.', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 13, 'Ba fefu da''ö, hadia ia, ba ni''otu''ö ba haga, ba ni''oroma''ö; fefu, hadia ia sa, zoroma, ba haga da''ö.[11]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 14, 'Andrö so ba zura: "Faoso, ya''ugö, si no mörö, fazaŵa''ö moroi ba ngai zi mate, ba ihagaini ndra''ugö Keriso."[12]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 15, 'Ba mifaigi sibai, he wisa wanörömi lalami; böi si mane sambö era-era, si mane satua-tua a''ine.[13]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 16, 'Mi''oguna''ö ginötö andrö, me no si lö sökhi-sökhi mbaŵa da''e.[14]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 17, 'Andrö böi sambö era-era ami, ya''aboto ba dödömi hadia zomasi Zo''aya.[15]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 18, 'Ba böi mibusi ami agu, tobali famakuyu da''ö; yafahöna khömi Geheha;[16]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3406045, 'NT', 'Efeso', 5, 19, 'milau-lau khö nawömi zinunö, ba lailö, ba manö-manö nibe''e Geheha, mifalailö tödömi, ba mi''anunö, khö Zo''aya.[17]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 20, 'Böi mifamalö-malö wangandrö saoha gölö, khö Lowalangi Ama, nitemada khönia fefu, ba döi Zo''aya ya''ita, Yesu Keriso.[18]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 21, 'Faoma mi''o''ö li nawömi, ba wa''ata''uda Keriso.[19]', '["Mat 5:48; Luk 6:36","Faigi 4:1,2; Yoh 13:34; Gal 2:20; Heb 9:14","Kol 3:5,6; KorI 6:18 b.t.","Faigi 4:29","KorI 6:9,10; Mat 6:24","Faigi 4:14; KorI 15:33; Mat 7:15","FetI 2:9; Fil 2:15; Yoh 12:35,36","Gal 5:22","Rom 12:2","KorII 6:14","Yoh 3:20; Kor 1:4,5","Yes 60:1,2; Rom 13:11","Mat 10:16; Yak 3:13","Kol 4:5","Faigi 5:10","Amaed 20:1; 23:20,29","Kol 3:16; Sin 96:1","Kol 3:17; TesI 5:18","Mat 20:26; FetI 5:5"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 22, 'Ira alawe, ba ndramu''o''ö li ndra matuara, hulö na li Zo''aya,[20]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 23, 'me no högö ndra alawe ndra matua, si mane Keriso göi, me no högö mbanua ia, ba sangorifi boto ia.[21]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 24, 'Ba si mane banua, me no la''o''ö li Keriso, ya si manö ndra alawe, ba ndra matua, ba ngawalö hadia ia, fefu.[22]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 25, 'Ya''ami, ira matua, mi''omasiö ndra alawemi, si mane Keriso, me no i''omasi''ö mbanua, ba me no ibe''e salahira ia.[23]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 26, 'ena''ö i''amoni''ö ira, me no ihaogö ira, femondri andrö, ba daroma li,[24]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 27, 'ena''ö molakhömi mbanua andrö khönia, ibe''e, si lö hadia ia da''i, ba ma si tekuru, ba ma hadia ia, ena''ö ohau-hau, si lö sinegu.[25]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 28, 'Ya si manö wa''omasi ndra matua ndra alawe khöra, si mane fa''omasira mbotora. Somasi ngambatönia, ba i''omasi''ö mbotonia.', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 29, 'Lö irai fa''udu niha ba nösinia, irorogö, ba ihaogö-haogö, si mane Keriso göi ba mbanua,', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 30, 'me no ndroto-ndroto mbotonia ita.[26]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 31, '"Andrö iröi namania, awö ninania niha, ba molemba ia ba ngambatönia, ba tobali ha sambua ösi zi darua andrö."[27]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 32, 'No ebua zi no tobini andrö; ba fehedegu, ba ba khö Keriso ba ba mbanuania faekhu.[28]', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406045, 'NT', 'Efeso', 5, 33, 'Ba ba khömi, ba yamu''omasi''ö ngambatönia zamösana, si mane fa''omasinia ia; ba ira alawe, ba ena''ö na i''ata''ufi ndra matua.', '["MozI 3:16; Kol 3:18","Faigi 1:22,23; KorI 11:3","FetI 1:3","Kol 3:19; Efes 5:2","Yoh 17:17,19; 15:3; Tit 3:5","Faigi 1:4; Kol 1:21,22","Rom 12:5","MozI 2:24","KorII 11:2"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 1, 'Ya''ami iraono, mi''o''ö li ndra amami inami, ba khö Zo''aya; da''ö sa zatulö.[1]', '["Kol 3:20","MozII 20:12","Kol 3:21; MozI 18:19"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 2, '"Fosumange namau, awö ninau" da''ö mböröta goroisa si so amabu''ula li:', '["Kol 3:20","MozII 20:12","Kol 3:21; MozI 18:19"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 3, '"ena''ö ohahau dödöu, ba ena''ö anau nosou ba guli danö."[2]', '["Kol 3:20","MozII 20:12","Kol 3:21; MozI 18:19"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 4, 'Ba ya''ami, ira ama, böi mi''andrö wönu ndraonomi, mifamaha-maha ira, mibe''e wotu, ba mifarou dödöra, khö Zo''aya.[3]', '["Kol 3:20","MozII 20:12","Kol 3:21; MozI 18:19"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 5, 'Ya''ami sawuyu, mi''o''ö li zokhö botomi; sata''u ami, ba sanizi-nizi, ya''adölö dödömi, hulö na khö Keriso.[4]', '["Kol 3:22 b.t.; FetI 2:18","KorII 5:10","MozIII 25:43; Kol 4:1; Rom 2:11"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 6, 'Böi ha na anehe ira, si mane sangalui fa''omasi niha ira; ena''ö na si mane enoni Keriso, solo''ö somasi Lowalangi,', '["Kol 3:22 b.t.; FetI 2:18","KorII 5:10","MozIII 25:43; Kol 4:1; Rom 2:11"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 7, 'soroi ba dödö, si no aoha gölö, we''amöi enoni, hulö na khö Zo''aya, ba na tenga ba niha; si no mangila:', '["Kol 3:22 b.t.; FetI 2:18","KorII 5:10","MozIII 25:43; Kol 4:1; Rom 2:11"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 8, 'hadia zi sökhi, nilau zamösana ba tesulöni khönia, khö Zo''aya, he sawuyu ia, ba he si tenga sawuyu.[5]', '["Kol 3:22 b.t.; FetI 2:18","KorII 5:10","MozIII 25:43; Kol 4:1; Rom 2:11"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 9, 'Ba ya''ami, sokhö niha bö''ö, ba mimanö göi khöra, ba mibato wameta''u ya''ira, me no mirongo, so ba zorugo Zo''aya ya''ami, So''aya ya''ira göi, ba lö ba khönia famaigi bawa niha.[6]', '["Kol 3:22 b.t.; FetI 2:18","KorII 5:10","MozIII 25:43; Kol 4:1; Rom 2:11"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 10, 'Ba hadia baero ö, ba mi''abölö''ö ami, ba khö Zo''aya, ba ba wa''abölö wa''abe''enia andrö.[7]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 11, 'Mi''a''aro''ö ami, fangaro andrö, khö Lowalangi, ena''ö abe''e ami, ba wa''onekhe Gafökha andrö.', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 12, 'Tenga sa fasöndrata ba niha wasöndratada, no fasöndrata ba zamatörö andrö, ba zalaŵa andrö, ba zokhö uli danö andre, ba zogömi-gömi andre, fasöndrata ba mbekhu si lösökhi andrö, ba mbanua si yaŵa.[8]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 13, 'Andrö mihalö wangaro andrö khö Lowalangi, ena''ö tola milaŵa, na baŵa si lö sökhi, ba ena''ö tola mi''asiwai fefu hadia ia, ba ena''ö möna ami.[9]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 14, 'Ba mi''abe''e''ö ami, böbö löwi-löwimi zi duhu, ba öröbami wa''atulö dödö,[10]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 15, 'badagahe ba gahemi wa no mifa''anö ami, ba wangombakha turia somuso dödö andrö, ba wa''atulö.', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 16, 'Ba awö da''ö fefu, ba mihalö mbaluse famati andrö, si tola mibe''e fangokafu nono wana Gafökha andrö, so''alitö;[11]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 17, 'ba mihalö detenaulu fangorifi andrö, awö wöda Geheha andrö, taroma li Lowalangi.[12]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 18, 'Fefu hadia ia ngawalö wangandrö, awö ngawalö wakaosa, milau, böi mifamalö-malö, soroi ba Geheha ba böi miförö-förö ba da''ö, ya''a''oi so wa''anau gölö, awö wangandrö, salahi ni''amoni''ö andrö fefu,[13]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 19, 'ba salahigu, ena''ö tebe''e khögu hadia niŵa''ö, na fahuhuo ndra''odo, ena''ö lö aiwö ndra''o, wangombakha si no tobini andrö, turia somuso dödö andrö,[14]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 20, 'ba nibe''e sinenge ya''odo, ba rate andre, ena''ö lö alaŵö-laŵödo ba da''ö, ena''ö si nangea huhuo huhuogu andrö.[15]', '["KorI 16:13","Faigi 2:2; Luk 22:31","KorII 10:4","Luk 12:35; Yes 11:5","Amaed 30:5; Sin 7:11","TesI 5:8; Yes 59:17; Heb 4:12","Luk 18:1; Kol 4:2,3","TesII 3:1","Kol 4:4; KorII 5:20"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 21, 'Ba ena''ö mi''ila göi, he wisa khögu, hadia nilaugu, ba i''ombakha''ö khömi dania fefu, hadia ia, Tikhiko andrö, talifusö ni''omasi''ö andrö, enoni si lö faröi ba khö Zo''aya;[16]', '["Kol 4:7 b.t.","FetI 5:14","Fil 4:23"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 22, 'nifatengegu khömi, ba da''ö, ena''ö mirongo, he wisa khöma, ba ena''ö irara dödömi.', '["Kol 4:7 b.t.","FetI 5:14","Fil 4:23"]', NULL),
  (3406049, 'NT', 'Efeso', 6, 23, 'Ndrafalukha dalifusö wa''ohahau dödö ba fa''omasi ba famati, khö Lowalangi Ama, ba khö Zo''aya ya''ita, Yesu Keriso,[17] Ndrafalukha wa''ebua dödö dozi sangomasi''ö So''aya ya''ita, Yesu Keriso, si lö tebulö.[18]', '["Kol 4:7 b.t.","FetI 5:14","Fil 4:23"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 1, 'Faulo zanura da''e ba Timoteo, enoni Keriso Yesu, ba ni''amoni''ö andrö, khö Keriso Yesu, fefu, si so ba Wilifi, awö zatua ba awö genoni.[1]', '["KorII 1:1 b.t.; HalZin 16:12","Kol 1:2"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 2, 'Yafalukha ami wa''ebua dödö ba fa''ohahau dödö, khö Namada Lowalangi, ba khö Zo''aya ya''ita, Yesu Keriso.[2]', '["KorII 1:1 b.t.; HalZin 16:12","Kol 1:2"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 3, 'U''andrö saoha gölö khö Lowalangigu, ero na itörö tödögu ami,[3]', '["Rom 1:8 b.t.","KorI 1:6-8"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 4, 'lö mamalö-malö, ero mangandrö ndra''o; omuso dödögu, ba wangandrö andrö, salahimi fefu;', '["Rom 1:8 b.t.","KorI 1:6-8"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 5, 'börö me no mitolo ba wangombakha turia somuso dödö andrö, i''otarai mböröta, irugi da''e.', '["Rom 1:8 b.t.","KorI 1:6-8"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 6, 'Ba da''ö moroi, wa faduhu dödögu, samörögö mege halöŵö si sökhi andrö, ba dödömi, ba ifalua göi, irugi luo Keriso Yesu andrö.[4]', '["Rom 1:8 b.t.","KorI 1:6-8"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 7, 'Si manö zi nangea dödögu khömi, me no so ami ba dödögu; ba faoma, he ba rategu andre, ba he ba wamaduhu''ö turia somuso dödö, ba ba wanga''aro''ö ya''ia, ba mo''urakha ami fefu, ba wa''ebua dödö andrö khögu.', '["Rom 1:9 b.t."]', NULL),
  (3351020, 'NT', 'Filifi', 1, 8, 'Lowalangi sa zamaduhu''ö khögu, ha wa''aböldö omasido falukha khömi fefu, moroi ba dödö Keriso Yesu.[5]', '["Rom 1:9 b.t."]', NULL),
  (3351020, 'NT', 'Filifi', 1, 9, 'Ba da''ö ni''andrögu, ena''ö itugu tedou na ba wa''omasimi andrö wa''aboto ba dödö, awö ngawalö wangila fefu;[6]', '["Kol 1:9","Rom 12:1,2; TesI 3:13","FetI 1:7"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 10, 'ena''ö mi''ila mitimba tödömi, hadia zi sökhi, ena''ö ohau-hau ami, ba ena''ö lö manendre ami, irugi luo Keriso andrö,[7]', '["Kol 1:9","Rom 12:1,2; TesI 3:13","FetI 1:7"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 11, 'ba ena''ö fahöna khömi mbua-bua wa''atulö dödö, si oroi Yesu Keriso, ba wamolakhömi Lowalangi, ba ba wanuno ya''ia.[8]', '["Kol 1:9","Rom 12:1,2; TesI 3:13","FetI 1:7"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 12, 'Ba omasi ndra''o, na mirongo, ya''ami ira talifusö, wa no tobali abölö terongo duria somuso dödö, ba zi göna ndra''o andrö,', '["Faigi 4:22"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 13, 'irege oroma rategu andre, khö Keriso, ba zaradadu andrö, ma''afefu, ba ba danö bö''ö fefu.[9]', '["Faigi 4:22"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 14, 'Ba no ato dalifusö, si faduhu tödö, ba rategu andre, börö Zo''aya, ba no tedou wa lö aiwö ira, wangombakha taroma li Lowalangi, lö ata''u ira.', '["Faigi 4:22"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 15, 'So sa göi ösa, zangombakha Keriso, soroi ba wa''afökhö dödö, ba me no omasi ira wasosota, ba so ösa, ba moroi ba wa''asökhi dödö.', '["KorII 3:17"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 16, 'Soroi ba wa''omasi, ba me no la''ila, famaduhu''ö turia somuso dödö halöŵögu andrö.[10]', '["KorII 3:17"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 17, 'Ba soroi ba wasosota, ba lö sökhi wangombakha''öra Keriso, me lawai lanönö rategu andre fa''afökhö.[11]', '["TimII 1:8","KorII 1:11"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 18, 'Ba hadia sa? Te''ombakha''ö sa atö Keriso, gofu he wisa, he ba waya-faya, ba he ba zi duhu ; ba da''ö omuso dödögu, ba lö zi lö omuso dödögu na dania.', '["TimII 1:8","KorII 1:11"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 19, 'U''ila sa, tobali fangorifigu da''ö dania, börö wangandrömi, ba fanolo Geheha Yesu Keriso andrö.[12]', '["TimII 1:8","KorII 1:11"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 20, 'Itörö wehulu dödögu andrö ba fanötönagu, wa sambalö lö''ö, saila ndra''o, wa lö''ö manö fa''aiŵö; si mane föna fefu, si manö göi iada''e, te''ebua''ö döi Keriso, ba mbotogu andre, he ba wa''auri, ba he ba wa''amate.', '[]', NULL),
  (3351020, 'NT', 'Filifi', 1, 21, 'Fa''auri sa khögu Keriso, ba hare khögu wa''amate.', '[]', NULL),
  (3351020, 'NT', 'Filifi', 1, 22, 'Ba na so nisöndragu, ba wa''auri ba mboto andre, ba lö u''ila, hezo nihalögu.', '["KorII 5:8"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 23, 'Ba no manufa manö dödögu, ba zi dua balö andrö: omasido mofanödo ba sodo khö Keriso; si sökhi sibai sa da''ö;[13]', '["KorII 5:8"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 24, 'ba abölö moguna, lö ahetado, ba mboto andre, börö ami.', '["KorII 5:8"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 25, 'Ba me faduhu dödögu ba da''ö, ba u''ila, lö ahetado, ba lö aefado khömi fefu, ba wamanöi ya''ami ba ba wangomusoi''ö tödömi, ba wamati.[14]', '["Faigi 2:24","KorII 1:14"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 26, 'Ena''ö fahöna khömi mbörö wanuno ya''ami, ba khö Keriso, börö ndra''o, fangawuligu, na mangawulido zui khömi.[15]', '["Faigi 2:24","KorII 1:14"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 27, 'Ba ha da''ö: mihaogö mbua-buami, si faudu ba duria somuso dödö andrö, khö Keriso, ena''ö abe''e ami, ha sambua gera-era, ha sara dödö, wanolo ba wanimba si fatuwu ba wamati ba duria somuso dödö andrö, he möido mufaigi ami, ba he lö ya''o, ba urongo he wisa khömi.[16]', '["Efes 4:1; Faigi 2:2; Yud 3"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 28, 'Ba ena''ö lö''ö manö lakeani ami samadaö andrö; tandra wa''atekiko da''ö khöra, ba tandra wangorifi sa khömi, ba moroi ba Lowalangi da''ö.[17]', '["TesII 1:4,5"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 29, 'Noa sa tetehe khömi — fa''ebua dödö — mitaha wamakao, börö Keriso, tenga ha famati khönia,[18]', '["HalZin 5:41","HalZin 16:22 b.t.; TesI 2:2"]', NULL),
  (3351020, 'NT', 'Filifi', 1, 30, 'ba faoma wasöndratada, si no mi''ila khögu, ba nirongomi khögu iada''e.[19]', '["HalZin 5:41","HalZin 16:22 b.t.; TesI 2:2"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 1, 'Ba na moguna na hadia ia wamarou tödö, ba khö Keriso, na moguna na hadia ia wondrara dödö, soroi ba wa''omasi, na so hadia ia wefao ba khö Geheha, na so hadia ia wa''ogolö dödö ba fa''ahakhö dödö,[1]', '["Efes 4:1-3; Kol 3:12 b.t.","Faigi 3:16; KorI 1:10","Gal 5:26; Rom 12:10","KorI 10:24"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 2, 'ba mifo''ahonoa wa''omuso dödögu andrö, ena''ö ha sara dödömi, ena''ö faoma wa''omasimi nawömi, ena''ö ha sambua dödö ba ha sambua gera-era.[2]', '["Efes 4:1-3; Kol 3:12 b.t.","Faigi 3:16; KorI 1:10","Gal 5:26; Rom 12:10","KorI 10:24"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 3, 'Böi mifonaha wasosota, ba he fayawasa; mi''ide-ide''ö ami, ba ya''ebua ba dödö zamösana nawönia, moroikhönia.[3]', '["Efes 4:1-3; Kol 3:12 b.t.","Faigi 3:16; KorI 1:10","Gal 5:26; Rom 12:10","KorI 10:24"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 4, 'Böi ha soguna khönia ibe''e ba dödönia zamösana, soguna khö nawönia göi yamube''e ba dödönia.[4]', '["Efes 4:1-3; Kol 3:12 b.t.","Faigi 3:16; KorI 1:10","Gal 5:26; Rom 12:10","KorI 10:24"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 5, 'Si mane tödö Yesu Keriso, ya si manö göi dödömi.[5]', '["Yoh 13:15","Kol 1:15","KorII 8:9; Yes 52:13 b.t.; Heb 2:14,17","Yoh 14:31; Heb 5:8","Efes 1:20 b.t.; Heb 1:4 b.t.","Mat 28:18; Rom 14:11; Fam 5:13,14","HalZin 2:36; 10:36; Rom 14:9"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 6, 'Ya''ia, he ŵa''ae no nga''eu Lowalangi nga''eunia, ba ba dödönia, ba tenga sa nirabu, wa no fagölö-gölö ia khö Lowalangi;[6]', '["Yoh 13:15","Kol 1:15","KorII 8:9; Yes 52:13 b.t.; Heb 2:14,17","Yoh 14:31; Heb 5:8","Efes 1:20 b.t.; Heb 1:4 b.t.","Mat 28:18; Rom 14:11; Fam 5:13,14","HalZin 2:36; 10:36; Rom 14:9"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 7, 'iheta khönia da''ö, ihalö nga''eu zawuyu, ba tobali fakhili-khili ia ba niha, ba amuatania, ba si mane amuata niha, wamaigi niha.[7]', '["Yoh 13:15","Kol 1:15","KorII 8:9; Yes 52:13 b.t.; Heb 2:14,17","Yoh 14:31; Heb 5:8","Efes 1:20 b.t.; Heb 1:4 b.t.","Mat 28:18; Rom 14:11; Fam 5:13,14","HalZin 2:36; 10:36; Rom 14:9"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 8, 'I''ide-ide''ö ia, molo''ö ia, irugi wa''amate, fa''amate ba röfa.[8]', '["Yoh 13:15","Kol 1:15","KorII 8:9; Yes 52:13 b.t.; Heb 2:14,17","Yoh 14:31; Heb 5:8","Efes 1:20 b.t.; Heb 1:4 b.t.","Mat 28:18; Rom 14:11; Fam 5:13,14","HalZin 2:36; 10:36; Rom 14:9"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 9, 'Andrö göi no ibali''ö salaŵa sebua ia Lowalangi, ba no ibe''e bualania khönia döi andrö, sebua moroi ba döi bö''ö fefu.[9]', '["Yoh 13:15","Kol 1:15","KorII 8:9; Yes 52:13 b.t.; Heb 2:14,17","Yoh 14:31; Heb 5:8","Efes 1:20 b.t.; Heb 1:4 b.t.","Mat 28:18; Rom 14:11; Fam 5:13,14","HalZin 2:36; 10:36; Rom 14:9"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 10, 'Ena''ö ba döi Yesu andrö latuhi danö dozi si so ba zorugo, awö zi so ba guli danö, awö zi so barö danö;[10]', '["Yoh 13:15","Kol 1:15","KorII 8:9; Yes 52:13 b.t.; Heb 2:14,17","Yoh 14:31; Heb 5:8","Efes 1:20 b.t.; Heb 1:4 b.t.","Mat 28:18; Rom 14:11; Fam 5:13,14","HalZin 2:36; 10:36; Rom 14:9"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 11, 'ba ena''ö dozi bewe manehe, wa no So''aya Yesu Keriso, ba wamolakhömi Lowalangi Ama.[11]', '["Yoh 13:15","Kol 1:15","KorII 8:9; Yes 52:13 b.t.; Heb 2:14,17","Yoh 14:31; Heb 5:8","Efes 1:20 b.t.; Heb 1:4 b.t.","Mat 28:18; Rom 14:11; Fam 5:13,14","HalZin 2:36; 10:36; Rom 14:9"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 12, 'Andrö, ya''ami ni''omasi''ögu, si mane folo''ömi li, götö wa''ara, si manö göi mi''alui wangorifimi andrö ba mbanua furi, sata''u ami ba sanizi-nizi, böi ha si mane me sodo, mendrua manö na iada''e, me lö ya''odo.[12]', '["FetI 1:17; Sin 2:11","KorII 3:5","Yak 1:6 b.t.","FetI 2:12; Mat 5:14 b.t.","KorII 1:14","TimII 4:6; KorII 7:4","Faigi 4:4"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 13, 'Faoma sa Lowalangi zanga''asogö ba dödömi, he fa''edöna, ba he famalua, börö wa''ebua dödönia andrö.[13]', '["FetI 1:17; Sin 2:11","KorII 3:5","Yak 1:6 b.t.","FetI 2:12; Mat 5:14 b.t.","KorII 1:14","TimII 4:6; KorII 7:4","Faigi 4:4"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 14, 'Fefu, hadia ia, nilaumi, ba böi mikökö-kökö, ba böi manufa dödömi,[14]', '["FetI 1:17; Sin 2:11","KorII 3:5","Yak 1:6 b.t.","FetI 2:12; Mat 5:14 b.t.","KorII 1:14","TimII 4:6; KorII 7:4","Faigi 4:4"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 15, 'ena''ö tobali si lö sinegu ami, ba sohau-hau, ono Lowalangi, si lö si sala, bakha ba hunö niha andre, sabila tödö, si no tefuyu; oroma ami, ba gotaluara, sohagaini ulidanö.[15]', '["FetI 1:17; Sin 2:11","KorII 3:5","Yak 1:6 b.t.","FetI 2:12; Mat 5:14 b.t.","KorII 1:14","TimII 4:6; KorII 7:4","Faigi 4:4"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 16, 'Ena''ö böi miböhöli daroma li fangorifi andrö, ba wanunogu ya''o, na luo Keriso, wa no tenga faya nitörögu, awö wa no tenga zaya-zaya golö wa''erege dödögu andrö.[16]', '["FetI 1:17; Sin 2:11","KorII 3:5","Yak 1:6 b.t.","FetI 2:12; Mat 5:14 b.t.","KorII 1:14","TimII 4:6; KorII 7:4","Faigi 4:4"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 17, 'Ba he tebe''e sumange ndra''o, ba wame''e sumange famatimi andrö, ba wo''ere ba da''ö, ba omuso dödögu, owua-wua dödögu, awömi fefu.[17]', '["FetI 1:17; Sin 2:11","KorII 3:5","Yak 1:6 b.t.","FetI 2:12; Mat 5:14 b.t.","KorII 1:14","TimII 4:6; KorII 7:4","Faigi 4:4"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 18, 'Ba mi''omusoi''ö dödömi ba da''ö, mi''owua-wua''ö dödömi, awögu.[18]', '["FetI 1:17; Sin 2:11","KorII 3:5","Yak 1:6 b.t.","FetI 2:12; Mat 5:14 b.t.","KorII 1:14","TimII 4:6; KorII 7:4","Faigi 4:4"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 19, 'Ba udöna-döna sa khö Zo''aya, Yesu, alio ufatenge khömi Dimoteo andrö, ena''ö terara dödögu göi, na urongo he wisa khömi.[19]', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 20, 'Samösa lö khögu, si fagölö-gölö tödö khögu, si manö, si onorogöi tödö ya''ami, sindruhu-ndruhu.[20]', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 21, 'A''oi sa la''alui dana khöra, ba lö la''alui hadia ia khö Keriso Yesu.', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 22, 'Ba fa lö faröi ia, si no mutandra, ba no mi''ila, wa awögu ia, hulö nono, awö namania, ba halöŵö ba duria somuso dödö andrö.[21]', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 23, 'Da''ö sa nidöna-dönagu, nifatenge; u''anema''ö, na no u''ila, he wisa khögu.', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 24, 'Faduhu sa dödögu khö Zo''aya, alio so ndra''odo göi.[22]', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 25, 'Ba no uŵa''ö tödögu, lö tola lö ufatenge khömi Gefaforito, talifusö andrö, awögu ba halöŵö ba awögu ba wasöndrata, sinengemi andrö, enonimi ba zoguna khögu,[23]', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 26, 'me no humulu dödönia khömi fefu, ba me no abu dödönia, me no mirongo, wa no mofökhö ia.', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 27, 'Ba duhu sa, no mofökhö ia, ahatö wa''amate, ba no ihakhösi tödö ia Lowalangi, ba tenga ha ya''ia, ya''odo sa göi, fa böi fatete khögu wa''abu dödö.', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 28, 'Andrö aösö sibai dödögu, wamatenge ya''ia, ena''ö ifuli omuso dödömi, na mi''ila ia, ba ena''ö anono göi wa''abu dödögu.', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 29, 'Andrö mifonaha ia khömi, khö Zo''aya, ya''omuso manö dödömi, ba mifosumange zi manö.[24]', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351021, 'NT', 'Filifi', 2, 30, 'Halöŵö Keriso sa mbörö, wa no irugi zahatö ba wa''amate, no i''ositengagö nosonia, ba we''amöi salahimi, enonigu, me lö ya''ami.', '["TesI 3:2","TimII 4:10,16","TimI 1:2","Faigi 1:25","Faigi 4:18","KorI 16:18; TimI 5:17"]', NULL),
  (3351024, 'NT', 'Filifi', 3, 1, 'Ba baero da''ö, ya''ami ira talifusögu, ba mi''omusoi''ö dödömi, ba khö Zo''aya! Lö''ö sa abua gölögu, na da''ö zui usura khömi, ba faduhu dödömi.[1]', '["Faigi 2:18; Sin 32:11; 33:1","Mat 7:6; Fam 22:15; Yes 56:10 b.t.; KorII 11:13; Gal 6:12","Rom 2:29; Gal 6:14-16","KorII 11:21 b.t.","Rom 11:1; HalZin 26:5","Gal 1:13; HalZin 22:3 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 2, 'Mifaigi nasu andrö, mifaigi zohalöŵö andrö, si lö sökhi, mifaigi wanataba andrö.[2]', '["Faigi 2:18; Sin 32:11; 33:1","Mat 7:6; Fam 22:15; Yes 56:10 b.t.; KorII 11:13; Gal 6:12","Rom 2:29; Gal 6:14-16","KorII 11:21 b.t.","Rom 11:1; HalZin 26:5","Gal 1:13; HalZin 22:3 b.t."]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3351024, 'NT', 'Filifi', 3, 3, 'Ya''ita sa niboto andrö, samosumange Lowalangi, moroi ba Geheha Lowalangi andrö, ba ba khö Keriso Yesu tasuno ita, ba lö faduhu dödöda ba nösi niha.[3]', '["Faigi 2:18; Sin 32:11; 33:1","Mat 7:6; Fam 22:15; Yes 56:10 b.t.; KorII 11:13; Gal 6:12","Rom 2:29; Gal 6:14-16","KorII 11:21 b.t.","Rom 11:1; HalZin 26:5","Gal 1:13; HalZin 22:3 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 4, 'He ŵa''ae no so khögu, wa tola faduhu dödögu göi ba nösi niha ena''ö. Na so danö bö''ö, sanguma''ö tödönia, faduhu dödönia ba nösi niha, ba mendrua manö ndra''odo.[4]', '["Faigi 2:18; Sin 32:11; 33:1","Mat 7:6; Fam 22:15; Yes 56:10 b.t.; KorII 11:13; Gal 6:12","Rom 2:29; Gal 6:14-16","KorII 11:21 b.t.","Rom 11:1; HalZin 26:5","Gal 1:13; HalZin 22:3 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 5, 'No laboto ndra''o, me no ŵalu bongi ndra''odo, Iraono Gizeraeli ndra''odo, mado Mbeniyami, niha Heberaio ndra''odo, ba niha Heberaio ndra amagu, farizaio ndra''o, wolo''ö oroisa,[5]', '["Faigi 2:18; Sin 32:11; 33:1","Mat 7:6; Fam 22:15; Yes 56:10 b.t.; KorII 11:13; Gal 6:12","Rom 2:29; Gal 6:14-16","KorII 11:21 b.t.","Rom 11:1; HalZin 26:5","Gal 1:13; HalZin 22:3 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 6, 'samorege folohi banua Yesu andrö, ba ba wa''atulö dödö andrö, soroi ba goroisa, ba lö sinegu khögu.[6]', '["Faigi 2:18; Sin 32:11; 33:1","Mat 7:6; Fam 22:15; Yes 56:10 b.t.; KorII 11:13; Gal 6:12","Rom 2:29; Gal 6:14-16","KorII 11:21 b.t.","Rom 11:1; HalZin 26:5","Gal 1:13; HalZin 22:3 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 7, 'Ba hadia haregu, föna, ba no ube''e te''alagu, ba dödögu, börö Keriso.[7]', '["Luk 14:33","Gal 2:16,21","Rom 6:4,5; KorII 4:10","TimI 6:12; Sin 73:23 b.t.","KorI 9:24 b.t.; TimII 4:7 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 8, 'Ba fefu, hadia ia manö sa''ae, ba te''ala manö, uŵa''ö tödögu, börö wa''aboto ba dödögu Keriso Yesu, So''aya ya''o, sebua moroi ba danö bö''ö fefu; da''ö mbörö, wa no utayaigö fefu hadia ia, ba sasao ia, uŵa''ö tödögu, ena''ö usöndra haregu Keriso,', '["Luk 14:33","Gal 2:16,21","Rom 6:4,5; KorII 4:10","TimI 6:12; Sin 73:23 b.t.","KorI 9:24 b.t.; TimII 4:7 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 9, 'ba ena''ö oroma, ba khönia sodo, ba lö khögu fa''atulö dödö, khögu, si otarai goroisa; ha fa''atulö dödö andrö, soroi ba wamati khö Keriso, fa''atulö dödö soroi ba Lowalangi, ba wamati andrö;[8]', '["Luk 14:33","Gal 2:16,21","Rom 6:4,5; KorII 4:10","TimI 6:12; Sin 73:23 b.t.","KorI 9:24 b.t.; TimII 4:7 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 10, 'fa aboto ba dödögu ia, awö wa''abölö wemaosonia andrö, awö wefao ba wamakao andrö, khönia, na fagölö-gölö ndra''o ba wa''amatenia;[9]', '["Luk 14:33","Gal 2:16,21","Rom 6:4,5; KorII 4:10","TimI 6:12; Sin 73:23 b.t.","KorI 9:24 b.t.; TimII 4:7 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 11, 'ma atö ukhamö wemaoso zi mate andrö.', '["Luk 14:33","Gal 2:16,21","Rom 6:4,5; KorII 4:10","TimI 6:12; Sin 73:23 b.t.","KorI 9:24 b.t.; TimII 4:7 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 12, 'Tenga fa no aro ia khögu, ba ma fa no mo''ahonoa ndra''odo, ba ugohi, ma u''ila ura''u, börö wa no ira''udo göi Keriso Yesu.[10]', '["Luk 14:33","Gal 2:16,21","Rom 6:4,5; KorII 4:10","TimI 6:12; Sin 73:23 b.t.","KorI 9:24 b.t.; TimII 4:7 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 13, 'He ya''ami ira talifusö! lö''ö na uŵa''ö tödögu, ya''odo andre, no ura''u ia.', '["Luk 14:33","Gal 2:16,21","Rom 6:4,5; KorII 4:10","TimI 6:12; Sin 73:23 b.t.","KorI 9:24 b.t.; TimII 4:7 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 14, 'Sambalö sa, olifu ndra''odo zi no numalö, ba ugohi zi so fönagu, fagohi ndra''o, usaŵa dandra andrö, luo zi möna andrö, ba nikaoni Lowalangi niha, moroi si yaŵa, ba khö Keriso Yesu.[11]', '["Luk 14:33","Gal 2:16,21","Rom 6:4,5; KorII 4:10","TimI 6:12; Sin 73:23 b.t.","KorI 9:24 b.t.; TimII 4:7 b.t."]', NULL),
  (3351024, 'NT', 'Filifi', 3, 15, 'Ba ha wa''ato ita, si no mo''ahonoa, ba tamanö dödöda; ba na bö''ö ena''ö dödömi, ba i''oroma''ö göi khömi da''ö Lowalangi.', '["Faigi 1:27; 2:9; Rom 12:16","Faigi 4:92; KorI 11:1","KorII 11:15; Rom 16:18","Yoh 14:3; Heb 11:13-16; 13:14; Tit 2:13","KorI 15:43,49; YohI 3:2"]', NULL),
  (3351024, 'NT', 'Filifi', 3, 16, 'Ba heza zi no tarugi, ba böi tabulö''ö ita ba da''ö, wanörö![12]', '["Faigi 1:27; 2:9; Rom 12:16","Faigi 4:92; KorI 11:1","KorII 11:15; Rom 16:18","Yoh 14:3; Heb 11:13-16; 13:14; Tit 2:13","KorI 15:43,49; YohI 3:2"]', NULL),
  (3351024, 'NT', 'Filifi', 3, 17, 'Mibe''e dalimi ndra''odo, wolo''ö, ya''ami ira talifusö! Mitöngöni zi no si manö wanörö lalara, me no famaedo ndra''aga khömi.[13]', '["Faigi 1:27; 2:9; Rom 12:16","Faigi 4:92; KorI 11:1","KorII 11:15; Rom 16:18","Yoh 14:3; Heb 11:13-16; 13:14; Tit 2:13","KorI 15:43,49; YohI 3:2"]', NULL),
  (3351024, 'NT', 'Filifi', 3, 18, 'Ato sa zanörö lalara, si no asese u''ombakha''ö khömi, ba mowöi göi daŵa hörögu iada''e, ba wangombakha ya''ira, wa no fatiu ira ba röfa Keriso andrö.', '["Faigi 1:27; 2:9; Rom 12:16","Faigi 4:92; KorI 11:1","KorII 11:15; Rom 16:18","Yoh 14:3; Heb 11:13-16; 13:14; Tit 2:13","KorI 15:43,49; YohI 3:2"]', NULL),
  (3351024, 'NT', 'Filifi', 3, 19, 'Amozuara wa''atekiko, Lowalangira dalura, ba ba zaila ita ebua duriara, ba ngawalö hadia ia, ba guli danö, so dödöra.[14]', '["Faigi 1:27; 2:9; Rom 12:16","Faigi 4:92; KorI 11:1","KorII 11:15; Rom 16:18","Yoh 14:3; Heb 11:13-16; 13:14; Tit 2:13","KorI 15:43,49; YohI 3:2"]', NULL),
  (3351024, 'NT', 'Filifi', 3, 20, 'Ba si no banua ita, ba ba zorugo so; moroi ba da''ö göi tadöna-döna sangorifi Zo''aya ya''ita, Yesu Keriso,[15]', '["Faigi 1:27; 2:9; Rom 12:16","Faigi 4:92; KorI 11:1","KorII 11:15; Rom 16:18","Yoh 14:3; Heb 11:13-16; 13:14; Tit 2:13","KorI 15:43,49; YohI 3:2"]', NULL),
  (3351024, 'NT', 'Filifi', 3, 21, 'samali''ö dania botoda, boto ba wa''ide-ide andre, ena''ö faoma ira mbotonia andrö, solakhömi, ba wa''abölö andrö, ba ni''ilania göi ibe''e barö mbawania fefu hadia ia.[16]', '["Faigi 1:27; 2:9; Rom 12:16","Faigi 4:92; KorI 11:1","KorII 11:15; Rom 16:18","Yoh 14:3; Heb 11:13-16; 13:14; Tit 2:13","KorI 15:43,49; YohI 3:2"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 1, 'Ba me no si manö, ya''ami ira talifusögu, somasi ndra''o, ba zihulu dödögu, fa''omuso dödögu, ba si no amaedola dakulagu, ba mimanö wangabe''e''ö ya''ami, ba khö Zo''aya, ya''ami, somasi ndra''o.[1]', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 2, 'U''andrö khö Gewodia, ba u''andrö khö Zitikhe, ena''ö ha sambua dödö, ba khö Zo''aya.', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 3, 'U''andrö sa göi khöu, ya''ugö awögu si lö faröi andrö, tolo ira, si no fa''awö khögu, ba wangombakha turia somuso dödö, awö Gelemeno ba awögu tanö bö''ö ba halöŵö, nitanö töi ba zura wa''auri andrö.[2]', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 4, 'Böi yamamalö-malö wa''omuso dödömi, ba khö Zo''aya! ufuli uŵa''ö: Mi''omusoi''ö dödömi![3]', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 5, 'Ya''aboto ba dödö niha fefu wa''ebolo dödömi andrö! No ahatö Zo''aya.[4]', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 6, 'Böi mibusi tödö hadia ia, ba gofu: hadia ia mbörö, na so zabu dödömi, ba mibokai khö Lowalangi, ba wangandrö ba ba wangalulu, yafao wangandrö saoha gölö.[5]', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 7, 'Ba irorogö dödömi, awö gera-erami fa''ohahau dödö andrö, khö Lowalangi, sabölö moroi ba gera-era niha fefu, ba khö Keriso Yesu.[6]', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 8, 'Ba hadia baero ö, ya''ami ira talifusö, hadia zi duhu, hadia zi so töi, hadia zatulö, hadia zohau-hau, hadia zomasi ita, hadia zatulö dödöda famondrongo, na so hadia ia mbua-bua si sökhi, na so hadia ia nisuno, da''ö mifatou-tou tödömi.[7]', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 9, 'Nitöngönimi göi, nitemami andrö, nirongomi, ni''ilami khögu, da''ö milau, ba itolo ami Lowalangi wa''ohahau dödö andrö.[8]', '["TesI 2:19; Fil 1:27","Filem 2; Fam 13:8","Faigi 3:1","Yak 5:8,9","FetI 5:7; Efes 6:18","Kol 3:15; Rom 5:1","Tit 8:8,14","Faigi 3:17; TesI 5:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 10, 'Ba no omuso sibai dödögu, ba khö Zo''aya, me no ifuli tokea ami, ba wamatou-tou tödömi soguna khögu; noa sa mifatou-tou föna göi, ba lö lala khömi.', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 11, 'Tenga andrö uŵa''ö da''ö, me ambö khögu; noa sa to''ölö ndra''o, ahono dödögu, gofu he wisa khögu.[9]', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 12, 'Tola numana ndra''odo, ba tola fahöna khögu; no tefamaha ndra''o, gofu he wisa, ba gofu hadia ia, he sabuso ndra''odo, ba he solofo, he fahöna khögu, ba he ambö.[10]', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 13, 'Ulaŵa manö fefu, börö zanga''abölö ya''o andrö.[11]', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 14, 'Ba sökhi zui nilaumi, me no mitolo ndra''odo, ba wamakao andrö khögu.', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 15, 'Ba mi''ila sa göi, ya''ami banua Wilifi, wa ba mböröta wangombakha turia somuso dödö andrö, me uröi Makedonia, ba sambua lö banua, si lö aefa-aefa khögu, ba wanolo, baero ami, ha ya''ami.[12]', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 16, 'Me sodo ba Desalonika göi, ba no mifa''ohe''ö khögu zoguna khögu, mato mendrua.[13]', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 17, 'Tenga sangalui buala andrö ndra''odo, ha lua-luania andrö u''alui, si fahöna, ba wangofaya khömi.', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 18, 'Ba noa sa ahori utema, ba töra na i khögu; no fahöna khögu, me no utema khö Gefaforito nifa''ohe''ömi andrö, si sökhi sibai hua, sumange omasiö, somasi Lowalangi.[14]', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 19, 'Ba a''oi ibe''e khömi dania Lowalangigu fefu zoguna khömi, ba lakhömi, ba khö Keriso Yesu, me no fahöna khönia.[15]', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 20, 'Ba nifosumange Lowalangi, Amada, götö-götö wa''ara! Yaduhu.[16]', '["TimI 6:6-8","Heb 13:5","KorII 12:10","KorII 11:9","HalZin 17:1","Faigi 2:25; Heb 13:16","KorII 9:8","Gal 1:4,5"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 21, 'Mi''owai ni''amoni''ö fefu ba khö Keriso Yesu. La''owai ami awögu andre, talifusö.', '["KorII 13:12","KorI 16:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 22, 'La''owai ami fefu ni''amoni''ö, ba oföna sa zi so yomo khö kaizaro andrö.[17]', '["KorII 13:12","KorI 16:23"]', NULL),
  (3351025, 'NT', 'Filifi', 4, 23, 'Ya''ebua dödö Zo''aya ya''ita, Yesu Keriso, ba dödömi andrö![18]', '["KorII 13:12","KorI 16:23"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 1, 'Faulo, sinenge Yesu Keriso andrö, moroi ba wa''omasi Lowalangi, ba talifusö andrö, Timoteo, zanura da''e,[1]', '["Fil 1:1","TesI 1:1"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 2, 'ba ni''amoni''ö andrö, ba Golose, talifusö samati andrö, ba khö Keriso Yesu. Yafalukha ami wa''ebua dödö ba fa''ohahau dödö, khö Namada Lowalangi.[2]', '["Fil 1:1","TesI 1:1"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 3, 'Ma''andrö saoha gölö khö Lowalangi Zo''aya ya''ita, Yesu Keriso, khö Namania, lö mamalö-malö, na mangandröga, salahimi,[3]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 4, 'me no marongo wamatimi andrö khö Keriso Yesu, ba fa''omasi andrö, si so khömi, fa''omasimi ni''amoni''ö fefu.[4]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 5, 'Börö dötönafö andrö, ni''irö''ö khömi, ba zorugo, si no mirongo sa''ae, ba daroma li si duhu andrö, ba duria somuso dödö,[5]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 6, 'si no möi khömi, si mane ba guli danö ma''asagörö göi, ba mowua ba monöi, simane ba khömi göi, i''otarai luo andrö, me mirongo ia, ba me aboto ba dödömi wa''ebua dödö Lowalangi andrö, ba zi duhu.[6]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 7, 'Si mane nirongomi khö Gefafera, awöma ba halöŵö, ni''omasi''ö andrö, enoni Keriso, si lö faröi, ba khömi.[7]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 8, 'Ya''ia göi zangombakha khöma wa''omasimi andrö, soroi ba Geheha.', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 9, 'Ba andrö ya''aga göi, lö mabato, i''otarai luo andrö, me marongo, mangandröga, salahimi, ma''andrö, ena''ö tehöna khömi wa''aboto ba dödömi zomasi ia, na tebe''e khömi ngawalö wa''atua-tua fefu, awö ngawalö wangila fefu, soroi ba Geheha;[8]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 10, 'ena''ö amuata dana khö Zo''aya gamuatami, fa böi si lö omasi ia khömi, ena''ö mowua ami, fefu ngawalö mbua-bua si sökhi, ba ena''ö tedou wa''aboto ba dödömi Lowalangi;[9]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 11, 'ena''ö abölö ami, ena''ö tedou khömi fefu ngawalö wa''abölö, dali wa''abölö lakhöminia andrö, ena''ö a''oi so khömi wanaha tödö, awö wa''ebolo dödö, ba ena''ö omuso dödömi,[10]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 12, 'wangandrö saoha gölö khö Nama, si no mangehao ya''ita, ba wanema tana ba niha ni''amoni''ö andrö, ba haga andrö;', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 13, 'si no mangefa''ö ya''ita ba wa''abölö zogömi-gömi andrö, si no mamawu''a ya''ita, si no molohe ya''ita ba mbanua Nono wa''omasinia andrö.[11]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 14, 'Ba zi so khöda fangöhöli, fangefa''ö horö andrö.[12]', '["Efes 1:15,16","Filem 5","FetI 1:3,4; Efes 1:13","Yes 55:11; Mar 4:8","Faigi 4:12","Efes 1:15 b.t.","Efes 4:1; Hebr 13:21","Efes 3:16","HalZin 26:18","Efes 1:7"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 15, 'Famaedo Lowalangi si lö oroma andrö ia, si a''a moroi ba nifazökhi andrö, fefu, hadia ia.[13]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 16, 'Ba khönia sa mbörö wamazökhi hadia ia, fefu, he si so ba zorugo, ba he si so ba guli danö, soroma ba si lö oroma, he si dadao, ba he so''aya, ba he samatörö, ba he salaŵa andrö. Fefu, hadia ia, ba oi ya''ia zamazökhi, ba oi ba khönia, wa tefazökhi,[14]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 17, 'ba ya''ia, ba no föna danö bö''ö fefu, ba ba khönia aro fefu, hadia ia.[15]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 18, 'Ba ya''ia högö mboto andrö, högö mbanua, ya''ia mböröta, si a''a zi otarai zi mate andrö, ena''ö föna ia, fefu gofu heza.[16]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 19, 'Me no si manö wa''omasi Lowalangi, wa ba khönia monahia zi fahöna andrö, fefu,[17]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 20, 'awö wa ya''ia zangatulö fefu hadia ia, khönia, na i''atulö''ö donia andrö, ba röfania, ya''ia mbörö, he ba zi so ba guli danö, ba he ba zi so ba zorugo.[18]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 21, 'Ya''ami göi, me no fabali ami föna, me no fa''udu ami, ba gera-erami, ba mbua-buami andrö, si lö sökhi, ba no i''atulö''ö ami iada''e,[19]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 22, 'fa''amate andrö, ba mboto nösinia andrö, ba wamali''ö ni''amoni''ö ya''ami, si lö sala, si lö sinegu, fönania;[20]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 23, 'na lö''ö sa atö mamalö-malö wamatimi, na no modane-dane ami, na aro, na lö tebulö ami ba wanötöna andrö, niŵa''ö ba duria somuso dödö andrö, nirongomi, ni''ombakha''ö ba nifazökhi Lowalangi andrö, si so ba guli danö, fefu, si no tobali enoni ndra''o, ya''odo, Faulo andre.[21]', '["Heb 1:3; Fam 3:14","Yoh 1:3,10; Kol 2:10","Fam 22:13; Yoh 17:5","Efes 1:22 b.t.; Fam 1:5; KorI 15:20","Faigi 2:9; Yoh 1:16","KorII 5:18; Efes 2:14,16","Rom 5:6,10; Efes 2:15 b.t.","Tit 2:14","KorI 15:58; Kol 2:7; 1:6"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 24, 'Iada''e omuso dödögu, ba wamakao andre, salahimi, ba ubönökhi ba nösigu andre zambö na ba wamakao Keriso andrö, salahi mbotonia, banua andrö,[22]', '["Efes 3:1,13; HalZin 9:16","Efes 3:7","Rom 16:25 b.t.","KorII 13:5; Efes 3:17","Faigi 4:12"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 25, 'ba zi no tobali enoni ndra''odo, dali nihonogöi Lowalangi andrö, nibe''e ba dangagu, ba khömi andrö, ba wamo''ahonoa fangombakha taroma li Lowalangi andrö,[23]', '["Efes 3:1,13; HalZin 9:16","Efes 3:7","Rom 16:25 b.t.","KorII 13:5; Efes 3:17","Faigi 4:12"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 26, 'si no tobini andrö, si lö oroma, götö-götö wa''ara, ba ba nga''ötö ndra tua andrö, ba iada''e, ba no tefa''ele''ö ia, ba ni''amoni''ö andrö khönia.[24]', '["Efes 3:1,13; HalZin 9:16","Efes 3:7","Rom 16:25 b.t.","KorII 13:5; Efes 3:17","Faigi 4:12"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 27, 'Khöra edöna Lowalangi i''oroma''ö he wisa wa''ebua lakhömi zi no tobini andrö, ba niha baero, ya''ia Keriso ba khömi, tötönafö lakhömi andrö.[25]', '["Efes 3:1,13; HalZin 9:16","Efes 3:7","Rom 16:25 b.t.","KorII 13:5; Efes 3:17","Faigi 4:12"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 28, 'Ya''ia ni''ombakha''öma ba madozigö niha, wamarou tödöra, madozigö niha, wamahaö ya''ira ba ngawalö wa''atua-tua, fefu, ena''ö dozi niha mo''ahonoa fa''atulö, ba khö Keriso, mabe''e.', '["Efes 3:1,13; HalZin 9:16","Efes 3:7","Rom 16:25 b.t.","KorII 13:5; Efes 3:17","Faigi 4:12"]', NULL),
  (3386490, 'NT', 'Kolose', 1, 29, 'Ba khö da''ö sa göi mohalöŵödo, fasöndrado, balazi wa''abölönia, sangabölö''ö sibai ya''odo.[26]', '["Efes 3:1,13; HalZin 9:16","Efes 3:7","Rom 16:25 b.t.","KorII 13:5; Efes 3:17","Faigi 4:12"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 1, 'Omasi sa ndra''o, na mirongo he wisa wa''abu dödögu andrö, börö ami ba ya''ira ba La''odikia, ba dozi si lö irai fa''ila khögu, [1]', '["Faigi 4:13","KorI 1:24","Efes 5:6","KorI 14:40","Faigi 1:23; Efes 2:20; 4:15"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 2, 'ena''ö terara dödöra, na no faböbö ira, ba wa''omasi andrö, ba ena''ö lakhamö a''oi so wangila andrö, lö manufa dödö, ena''ö aboto ba dödö zi no tobini andrö, khö Lowalangi, Keriso andrö,', '["Faigi 4:13","KorI 1:24","Efes 5:6","KorI 14:40","Faigi 1:23; Efes 2:20; 4:15"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 3, 'ba zi no tobini fefu ngawalö girö-girö fa''atua-tua, awö girö-girö fa''aboto ba dödö.[2]', '["Faigi 4:13","KorI 1:24","Efes 5:6","KorI 14:40","Faigi 1:23; Efes 2:20; 4:15"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 4, 'Andrö uŵa''ö da''ö, fa böi ilimo ami niha, ha niha ia, ba huhuo famowöhö.[3]', '["Faigi 4:13","KorI 1:24","Efes 5:6","KorI 14:40","Faigi 1:23; Efes 2:20; 4:15"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 5, 'He sa lö botogu andre, ba sodo sa ba khömi tödögu; omuso dödögu, wangila fa''ehao andrö khömi, awö wa''aro dödömi, wamati khö Keriso.[4]', '["Faigi 4:13","KorI 1:24","Efes 5:6","KorI 14:40","Faigi 1:23; Efes 2:20; 4:15"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 6, 'Ba si mane fanemami Yesu Keriso, So''aya, si manö göi mitörö lalania,', '["Faigi 4:13","KorI 1:24","Efes 5:6","KorI 14:40","Faigi 1:23; Efes 2:20; 4:15"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 7, 'ba khönia yamoŵa''a ami, si tedou-dou, ni''abe''e''ö, ba wamati andrö, dali wamahaö ya''ami andrö; yafahöna khömi wangandrö saoha gölö, [5]', '["Faigi 4:13","KorI 1:24","Efes 5:6","KorI 14:40","Faigi 1:23; Efes 2:20; 4:15"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 8, 'Mifaigi, fa böi ilimo ami niha, ha niha ia, ba wa''atua-tua niha guli danö andrö, ba ba waya-faya andrö, wolo''ö nifa''ema niha, huku ba niha guli danö; si tenga folo''ö khö Keriso.[6]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 9, 'Ba khönia sa monahia gahonoa wa''alowalangi andrö, ma''afefu, moboto.[7]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 10, 'Ba khönia, wa no fahöna khömi; ba ba zamatörö andrö, fefu, ba ba zalaŵa andrö, fefu, ba no ya''ia högö.[8]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 11, 'Ba khönia göi no muboto ami, tenga ni''amoto''ö tanga, famoto fangeheta boto nösi andrö, famoto khö Keriso andrö,[9]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 12, 'me no teko''o ami, awönia, ba wamayagö idanö andrö; ba khönia göi no mususugi ami, awönia, börö wamati ba wa''abölö Lowalangi andrö, si no manusugi ya''ia moroi ba ngai zi mate.[10]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 13, 'Ya''ami, göi, si no mate föna, ba wanawö-nawö oroisa andrö, ba ba nösimi andrö, si lö muboto, ba no i''orifi, awönia, me no ibe''e bualania khöda lalö andrö fefu,[11]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 14, 'me no ibunu zura gömöda andrö, fangadugö ya''ita andrö, amakhoita andrö, ududa; no iheta, me no i''osö ba röfa;[12]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 15, 'me iheta wangöna zamatörö andrö, ba fangöna zalaŵa andrö, me ibali''ö aya ira, ba zanehe zato, me i''oroma''ö, wa no abölö ia moroi khöra, ba röfa andrö.[13]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 16, 'Ba böi sa''ae yamuhuku ami niha ba ni''a, ba ma ba nibadu, ba ma ba luo ni''amoni''ö, ba ma ba wasulöna, ba ma ba zabato.[14]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 17, 'Lumö zi so dania da''ö, ba khö Keriso mboto.[15]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 18, 'Böi ilimo ami niha, ha niha ia, ba luo zabölö andrö, niha somasi fa''adugu-dugu, ba famosumange mala''ika, niha solo''ö angilatania, si so hokha si lö börö, ba gera-era dödö nösinia,[16]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 19, 'ba si lö molemba ba högö andrö; ba moroi ba da''ö sa tetolo mboto ma''afefu, ba wamaböbö andrö, ba ba nuo, moroi ba da''ö tefaböbö ia, ba manöi, ba wa''ebua andrö nibe''e Lowalangi.[17]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 20, 'Ba na no mate ami, awö Keriso, ba huku niha guli danö andrö, ba hana wa labe''e goroisa khömi, hulö ba zi lö mate na, ba niha guli danö, wanguma''ö:[18]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 21, 'Böi halö! böi a! böi babaya![19]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 22, '— ba oi sa atö ba wa''atekiko tebe''e ia, ba wangoguna''ö ya''ia — wolo''ö amakhoita ba famahaö ba niha:[20]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3387640, 'NT', 'Kolose', 2, 23, 'fa''atua-tua sa laŵa''ö, ba wame''e sumange si lö mu''oroi''ö, ba ba wa''adugu-dugu, ba ba wamakao boto, ba tenga ba wangöhöndrögö fa''abölö nösi andrö.[21]', '["Efes 4:14; Rom 16:18","Faigi 1:19; Yoh 1:14","Faigi 1:16; Efes 1:21,23","Fil 3:3; Kol 3:5-9","Rom 6:4,5; Efes 2:5 b.t.; Kol 3:1","Efes 2:1; 5:11; KorII 5:19","Efes 2:15","Luk 11:22","Heb 9:10; Rom 14:2 b.t.; MozIII 23","Heb 8:5; 10:1","TimI 6:3 b.t.","Efes 4:15,16","Gal 4:9","MozIII 5:2; TimI 4:3","Mat 15:9,17,18","TimI 4:8"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 1, 'Ba na no maoso ami, awö Keriso, ba mi''alui zi so si yaŵa, ba zi so Keriso, sidadao ba gambölö Lowalangi.[1]', '["Faigi 2:12,13; Heb 12:2","Mat 6:33","Rom 6:2,11","Fil 1:21; TesII 1:7,10; FetI 4:13"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 2, 'Si so si yaŵa mifatou-tou tödömi, böi si so ba guli danö.[2]', '["Faigi 2:12,13; Heb 12:2","Mat 6:33","Rom 6:2,11","Fil 1:21; TesII 1:7,10; FetI 4:13"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 3, 'Noa sa mate ami, ba no tobini wa''aurimi andrö, awö Keriso, ba khö Lowalangi.[3]', '["Faigi 2:12,13; Heb 12:2","Mat 6:33","Rom 6:2,11","Fil 1:21; TesII 1:7,10; FetI 4:13"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 4, 'Ba na to''ele dania Keriso, fa''aurimi andrö, awena dania to''ele göi ami, awönia, ba lakhömi.[4]', '["Faigi 2:12,13; Heb 12:2","Mat 6:33","Rom 6:2,11","Fil 1:21; TesII 1:7,10; FetI 4:13"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 5, 'Ba mibunu sa''ae ndroto-ndroto andrö, si so ba guli danö: fohorö, ba fa''ara''i-ra''iö, ba hokha, ba fangisö si lö sökhi, ba fa''omasi gana''a; no famosumange adu da''ö;[5]', '["Efes 5:3,5","Efes 5:6","Efes 2:1-3","Yak 1:21; Efes 4:29; 5:4","Efes 4:22,25","Efes 4:24; MozI 1:27","Gal 3:28; 5:6"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 6, 'da''ö fefu mbörö, wa tesao wönu Lowalangi.[6]', '["Efes 5:3,5","Efes 5:6","Efes 2:1-3","Yak 1:21; Efes 4:29; 5:4","Efes 4:22,25","Efes 4:24; MozI 1:27","Gal 3:28; 5:6"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3388052, 'NT', 'Kolose', 3, 7, 'Ya''ami göi, ba no mitörö da''ö föna, me ba da''ö nahami.[7]', '["Efes 5:3,5","Efes 5:6","Efes 2:1-3","Yak 1:21; Efes 4:29; 5:4","Efes 4:22,25","Efes 4:24; MozI 1:27","Gal 3:28; 5:6"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 8, 'Ba iada''e, ba miböhöli göi da''ö fefu: Fönu, ba fa''abao dödö, ba fa''afaito, ba fanandraŵa, ba fehede si lö sökhi, si oroi mbewemi.[8]', '["Efes 5:3,5","Efes 5:6","Efes 2:1-3","Yak 1:21; Efes 4:29; 5:4","Efes 4:22,25","Efes 4:24; MozI 1:27","Gal 3:28; 5:6"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 9, 'Böi milimo nawömi, me no miheta niha si tohöna andrö, fabaya nilau-launia andrö,[9]', '["Efes 5:3,5","Efes 5:6","Efes 2:1-3","Yak 1:21; Efes 4:29; 5:4","Efes 4:22,25","Efes 4:24; MozI 1:27","Gal 3:28; 5:6"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 10, 'ba me no mi''onukha zi bohou andrö, nibohouni, ba wa''aboto ba dödö andrö, dali wamaedo zamazökhi ya''ia andrö,[10]', '["Efes 5:3,5","Efes 5:6","Efes 2:1-3","Yak 1:21; Efes 4:29; 5:4","Efes 4:22,25","Efes 4:24; MozI 1:27","Gal 3:28; 5:6"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 11, 'ba zi lö Dawa Heleni ba lö niha Yehuda, ba lö niboto ba lö si lö muboto, lö niha bö''ö, ba lö Sikito, lö sawuyu, ba lö si tenga sawuyu, ha sambalö Keriso manö, ba dödöra fefu.[11]', '["Efes 5:3,5","Efes 5:6","Efes 2:1-3","Yak 1:21; Efes 4:29; 5:4","Efes 4:22,25","Efes 4:24; MozI 1:27","Gal 3:28; 5:6"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 12, 'Ba me no nitutuyu Lowalangi ami, ni''amoni''ö ba ni''omasi''ö, ba mi''onukha wa''ahakhö dödö, ba fa''ebua dödö, ba fa lö fayaŵa, ba fa''ebolo dödö, ba fanaha tödö.[12]', '["Efes 4:2,32","Efes 5:2; Mat 6:14 b.t.","Yoh 13:34; 15:12; FetI 4:8","Fil 4:7","Efes 5:19; KorI 14:26","KorI 10:31; Efes 5:20"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 13, 'Faoma mibologö dödömi khö nawömi, ba faoma mi''efa''ö zala nawömi khömi, na so zinegu zamösana khö nawönia; si mane fangefa''ö Keriso khömi, si manö göi ami.[13]', '["Efes 4:2,32","Efes 5:2; Mat 6:14 b.t.","Yoh 13:34; 15:12; FetI 4:8","Fil 4:7","Efes 5:19; KorI 14:26","KorI 10:31; Efes 5:20"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 14, 'Ba baero da''ö fefu, ba fa''omasi; da''ö wamaböbö fa''amo''ahonoa.[14]', '["Efes 4:2,32","Efes 5:2; Mat 6:14 b.t.","Yoh 13:34; 15:12; FetI 4:8","Fil 4:7","Efes 5:19; KorI 14:26","KorI 10:31; Efes 5:20"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 15, 'Ba yamufatörö dödömi fa''ohahau dödö andrö, khö Keriso, ba nikaoni ya''ami; ha sambua boto; ba mi''andrö saoha gölö.[15]', '["Efes 4:2,32","Efes 5:2; Mat 6:14 b.t.","Yoh 13:34; 15:12; FetI 4:8","Fil 4:7","Efes 5:19; KorI 14:26","KorI 10:31; Efes 5:20"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 16, 'Yamonaha ba khömi daroma li Keriso andrö, yafahöna; ya''a''oi so wa''atua-tuami, ba wamahaö awömi ba ba wamarou tödöra, sinunö ba umanö ba lailö dödö, yafao wangandrö saoha gölö; misuno Lowalangi ba dödömi.[16]', '["Efes 4:2,32","Efes 5:2; Mat 6:14 b.t.","Yoh 13:34; 15:12; FetI 4:8","Fil 4:7","Efes 5:19; KorI 14:26","KorI 10:31; Efes 5:20"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 17, 'Ba fefu hadia ia nilaumi, he taroma li, ba he halöŵö, ba ba döi Yesu, So''aya, milau ia, fefu, wangandrö saoha gölö khö Lowalangi Ama; Yesu zama''ema.[17]', '["Efes 4:2,32","Efes 5:2; Mat 6:14 b.t.","Yoh 13:34; 15:12; FetI 4:8","Fil 4:7","Efes 5:19; KorI 14:26","KorI 10:31; Efes 5:20"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 18, 'Ya''ami ira alawe, mi''o''ö li ndra matua; si manö zi nangea, ba khö Zo''aya.[18]', '["Efes 5:22 b.t.","Efes 6:1 b.t.","Efes 6:5 b.t.","KorI 1:5,10; Rom 2:11"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 19, 'Ya''ami ira matua, mi''omasi''ö ndra alawe, ba böi abao dödömi khöra.', '["Efes 5:22 b.t.","Efes 6:1 b.t.","Efes 6:5 b.t.","KorI 1:5,10; Rom 2:11"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 20, 'Ya''ami iraono, mifondrondrongo li ndra amami, gofu hadia ia niŵa''ö khömi, da''ö sa ni''omasi''ö, ba khö Zo''aya.[19]', '["Efes 5:22 b.t.","Efes 6:1 b.t.","Efes 6:5 b.t.","KorI 1:5,10; Rom 2:11"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 21, 'Ya''ami ira ama, böi mi''andrö wönu ndraonomi, fa böi ada''u-da''u ira.', '["Efes 5:22 b.t.","Efes 6:1 b.t.","Efes 6:5 b.t.","KorI 1:5,10; Rom 2:11"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 22, 'Ya''ami sawuyu, mifondrondrongo li zokhö botomi, gofu hadia ia niŵa''ö khömi, böi ha ba zanehe ira, si mane niha sangalui fa''omasi niha ira; moroi si''aikö ba dödömi, me no sangata''ufi So''aya ami.[20]', '["Efes 5:22 b.t.","Efes 6:1 b.t.","Efes 6:5 b.t.","KorI 1:5,10; Rom 2:11"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 23, 'Hadia ia nifazökhimi, ba moroi ba dödö milau ia, hulö na khö Zo''aya, ba na tenga ba niha,', '["Efes 5:22 b.t.","Efes 6:1 b.t.","Efes 6:5 b.t.","KorI 1:5,10; Rom 2:11"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 24, 'me no mi''ila, wa khö Zo''aya mitema dania luo, ondröita andrö; enoni Zo''aya, Keriso, ami.', '["Efes 5:22 b.t.","Efes 6:1 b.t.","Efes 6:5 b.t.","KorI 1:5,10; Rom 2:11"]', NULL),
  (3388052, 'NT', 'Kolose', 3, 25, 'Itema sa zulö zi lö atulö andrö, nilaunia, solau si lö atulö, ba lö ebua dödö zambuana.[21]', '["Efes 5:22 b.t.","Efes 6:1 b.t.","Efes 6:5 b.t.","KorI 1:5,10; Rom 2:11"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 1, 'Ya''ami sokhö niha bö''ö, hadia zatulö, hadia zi nangea, da''ö milau ba zawuyu andrö, me no mi''ila, so Zo''aya ya''ami göi ba zorugo.[1]', '["Efes 6:9","Efes 6:18; TesI 5:17","Efes 6:19,20","Efes 5:15,16","Mar 9:50; Amaed 10:32"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 2, 'Böi miböhöli wangandrö; böi mörö ami ba da''ö, yafao wangandrö saoha gölö.[2]', '["Efes 6:9","Efes 6:18; TesI 5:17","Efes 6:19,20","Efes 5:15,16","Mar 9:50; Amaed 10:32"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 3, 'Ba ya''itörö göi limi ndra''aga, ba da''ö, ena''ö ifolala khöma Lowalangi daroma li andrö, ba wangombakha si no tobini andrö, khö Keriso, da''ö göi mbörö, wa no murate ndra''o.[3]', '["Efes 6:9","Efes 6:18; TesI 5:17","Efes 6:19,20","Efes 5:15,16","Mar 9:50; Amaed 10:32"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 4, 'Ena''ö u''ila ubokai ia, ba ena''ö u''ila u''o''ö niŵa''ö khögu, wangombakha.', '["Efes 6:9","Efes 6:18; TesI 5:17","Efes 6:19,20","Efes 5:15,16","Mar 9:50; Amaed 10:32"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 5, 'Böi zi lö atua-tua ami, ba wolau nilaumi, ba zi so baero andrö, ba mifaigi ginötö, si göna.[4]', '["Efes 6:9","Efes 6:18; TesI 5:17","Efes 6:19,20","Efes 5:15,16","Mar 9:50; Amaed 10:32"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 6, 'Böi tebulö khömi wangehao fehedemi, nilau asio, fa mi''ila, he miwisa wanema li zamösana.[5]', '["Efes 6:9","Efes 6:18; TesI 5:17","Efes 6:19,20","Efes 5:15,16","Mar 9:50; Amaed 10:32"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 7, 'Fefu hadia ia, ba khögu andre, ba i''ombakha''ö khömi dania Tikhiko,[6] talifusö ni''omasi''ö andrö, enoni si lö faröi andrö, awögu sangai halöŵö, ba khö Zo''aya.[7]', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 8, 'Da''ö mbörö, wa ufatenge ia khömi, ena''ö mirongo he wisa ba khöma andre, ba ena''ö irara dödömi.', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 9, 'Awönia Gonesimo, talifusö andrö, si lö faröi, ni''omasi''ö, banuami. La''ombakha''ö dania khömi fefu, he wisa ba da''e.[8]', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 10, 'I''owai ami Arisaro, awögu nikuru andrö, ba Mareko, talifusö Mbaranaba andrö, ba nitemami oroisa — na irugi ami, ba mifa''amöi ia khömi —[9]', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 11, 'ba Yesu andrö, sotoi Yuso. Ha da''ö nawögu niha niboto, sohalöŵö ba mbanua Lowalangi; no tobali fondrara dödögu ira.', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 12, 'I''owai ami Efafera, banuami andrö, enoni Keriso Yesu; lö tebulö wa iforege wangandrö, salahimi, ena''ö abe''e ami, ena''ö mo''ahonoa, ba ena''ö faduhu sibai dödömi, ba zomasi Lowalangi andrö, fefu.[10]', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 13, 'Ufaduhu''ö khömi, ba khönia andrö, wa no erege dödönia, börö ami ba banua La''odikia andrö ba banua Hierafoli.', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 14, 'I''owai ami Luka, doto andrö, ni''omasi''ö, ba Dema.[11]', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 15, 'Mi''owai dalifusö andrö, ba La''odikia, ba Nimefa, ba banua andrö, baomo khönia.', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 16, 'Ba na no mubaso zura andre, ba khömi, ba mibe''e nibaso ba mbanua ba La''odikia göi, ba ena''ö tebaso göi ba khömi zura ba mbanua La''odikia andrö.', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 17, 'Ba mimane khö Arikhifo andrö: "Faigi halöŵö andrö nitemau ba khö Zo''aya, fa ö''asiwai."[12]', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388154, 'NT', 'Kolose', 4, 18, 'Fangowaigu da''e, tangagu zanura, tanga Waulo andre. Mitörö-törö tödömi rategu andre. Yafalukha ami wa''ebua dödö.[13]', '["Tychikos (Τυχικὸς) no samösa niha Keriso si fao awö Waulo ba wanuriaigö Injil. I''o''awögö Waulo moroi ba Makedonia irugi Yerusalema, heŵa''ae so göi zanguma''ö wa no fao ia khö Waulo ba Roma. Moroi ba Roma ifatenge ia Faulo ba Efeso ba ba Kolose ba wondrou''ö Gereja ba da''ö.","Efes 6:21,22","Filem 10 b.t.","HalZin 27:2; TimII 4:11","Faigi 2:1; Fam 3:14","Filem 24","Filem 2","KorI 16:21; Heb 13:3; TesI 5:28"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 1, 'Faulo zanura da''e ba Siliwano ba Timoteo, ba mbanua andrö, ba Desalonika, ba khö Lowalangi Ama, ba ba khö Zo''aya, Yesu Keriso. Yafalukha ami wa''ebua dödö ba fa''ohahau dödö.[1]', '["TesII 1:1,2; HalZin 17:1,10"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 2, 'Lö mamalö-malö wangandröma saoha gölö khö Lowalangi.[2]', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 3, 'ba khömi andrö, fefu, itörö lima ami, na mangandröga; lö aetu wa itörö tödöma mbua-bua wamatimi andrö, ba fa''owölö-ölö wa''omasimi, ba fa''anau gölö wanötönami andrö, khö Zo''aya ya''ita, Yesu Keriso, föna Namada Lowalangi,[3]', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 4, 'me no aboto ba dödöma, wa no nitutuyu ami, ya''ami ira talifusö, ni''omasi''ö Lowalangi,[4]', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 5, 'me no irugi ami turia somuso dödö andrö, khöma, tenga ha ba li, no fao göi wa''abölö ba Eheha ni''amoni''ö, ba no abölö wa lö aiŴö; mi''ila sa he wisa ndra''aga, ba khömi andrö, börö ami.[5]', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 6, 'Ba no tobali solo''ö khöma ami ba solo''ö khö Zo''aya, me no mifonaha daroma li andrö; no oya zi fao famakao, ba no omuso dödömi, moroi khö Geheha ni''amoni''ö;[6]', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 7, 'ba no'' tobali famaedo ami ba zamati fefu, ba Makedonia ba ba Nakhaya.', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 8, 'Moroi ba khömi sa terongo daroma li Zo''aya andrö, tenga ha ba Makedonia ba ba Nakhaya, no ba mbanua bö''ö fefu teturia wamatimi ba Lowalangi, tobali alakha lö''ö sa''ae itörö lima.[7]', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 9, 'Ya''ira sa zanutunö, he wisa we''amöima ba khömi, ba he wisa wamulimi ya''ami ba Lowalangi, wondröi adu andrö, ba wolo''ö khö Lowalangi sauri andrö, si ndruhu,[8]', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388910, 'NT', 'Tesalonika I', 1, 10, 'ba ba wombalo-mbaloi Ononia andrö, moroi ba zorugo, nisusuginia moroi ba ngai zimate, Yesu, sangefa''ö ya''ita ba wönu dania andrö.[9]', '["TesII 1:3; Kol 1:3","Faigi 5:8; KorI 13:13","TesII 2:13 b.t.","Faigi 2:13 b.t.; KorI 2:4,5","KorI 11:1; HalZin 17:5 b.t.","KorII 12:15","HalZin 18:3; 29:18 b.t.","Faigi 4:16; Fil 3:20; Rom 5:9"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 1, 'Mi''ila sa, ya''ami ira talifusö, wa no tenga zaya-zaya gölö we''amöima ba khömi.[1]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 2, 'Noa sa ma''abe''e''ö ndra''aga, ba khö Lowalangida, me no mataögö ua wamakao ba me no la''osiwawöi ndra''aga, ba Wilifi, nirongomi, ba wangombakha khömi turia somuso dödö andrö khö Lowalangi; no oya zi fao famakao.[2]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 3, 'Tenga sa moroi ba wa''elungu wangombakha''öma, ba tenga moroi ba walösökhi, ba tenga ba wa''onekhe;[3]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 4, 'me no iŵa''ö Lowalangi tola ndra''aga, tola ibe''e ba dangama duria somuso dödö andrö, ba muhede ndra''aga, tenga afuma la''omasi''ö ndra''aga niha, afuma i''omasi''öga Lowalangi andrö, sanandraigö tödöma.[4]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 5, 'Lö''ö sa marai masuno niha, wondrönisi ya''ira, mi''ila, ba lö nibini''öma tödöma, wangalui harema; Lowalangi zangila.[5]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 6, 'Lö''ö göi ni''aluima sumange ba niha, he ba khömi, ba he ba niha bö''ö; tola sa ma''ebua''ö ndra''aga mena''ö, me no sinenge Keriso ndra''aga;[6]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 7, 'ba no mahaogö-haogö, ba khömi, hulö zamaenu ono, ba wondrorogö ononia.', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 8, 'Si manö wehulu dödöma khömi, ba no aoha gölöma, tenga ha turia somuso dödö andrö khö Lowalangi mafa''ema khömi, nosoma göi, ba no khömi, me no omasiga ami.[7]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 9, 'Dörö itörö tödömi, ya''ami, ira talifusö, wa''erege dödöma ba famakaoma andrö; bongi ma''ökhö mohalö-halöŵö ndra''aga, ena''ö samösa lö''ö, ba khömi, sabu tödö ba khöma andre, me maturiagö khömi duria somuso dödö andrö, khö Lowalangi.[8]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 10, 'No anehe ami ba no anehe Lowalangi wa''ohau-hauma ba fa''atulö dödöma andrö, awö wa no lö sinegu khöma, ba khömi samati andrö.', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 11, 'Mi''ila he wisa wango''ouma ya''ami, dozi ami, ba he wisa wamarouma tödömi, hulö nama khö nononia,[9]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 12, 'ba he wisa wamaduhu''öma khömi, ena''ö mihaogö mbua-buami, ena''ö si nangea khö Lowalangi andrö, sogaoni ya''ami banuania, ba ba lakhömi andrö khönia.[10]', '["Faigi 1:5,9","HalZin 16:22 b.t.; 17:6","KorII 2:17","TimI 1:11; Gal 1:10; Nga''ötI 29:17","KorII 4:2; 12:14","Yoh 5:41,44","KorII 12:15","HalZin 18:3; 20:18 b.t.","KorI 4:14,15","Efes 4:1"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 13, 'Andrö lö mabato, göi wangandrö saoha gölö khö Lowalangi, me no mifonaha daroma li Lowalangi andrö, nirongomi khöma, tenga si mane taroma li niha, no si mane si ndruhunia, simane taroma li Lowalangi, si no abölö göi ba dödömi, ba dödö zi no mamati andrö.[11]', '["Faigi 1:2-6","HalZin 17:5,13; 8:1","HalZin 3:15; 7:52","HalZin 13:45; 14:2; Dan 9:26,27"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 14, 'Noa sa solo''ö ami, ya''ami ira talifusö, no mi''o''ö ba mbanua Lowalangi andrö, si so ba Yudaia, ba khö Keriso Yesu, me no mitaögö göi wamakao si manö, ba dalifusömi, si mane ya''ira ba niha Yehuda,[12]', '["Faigi 1:2-6","HalZin 17:5,13; 8:1","HalZin 3:15; 7:52","HalZin 13:45; 14:2; Dan 9:26,27"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 15, 'si no mamunu göi So''aya, Yesu, awö zama''ele''ö andrö, si no molohi ya''aga göi; lö omasi Lowalangi ira, ba no fa''udu ira ba niha fefu;[13]', '["Faigi 1:2-6","HalZin 17:5,13; 8:1","HalZin 3:15; 7:52","HalZin 13:45; 14:2; Dan 9:26,27"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 16, 'sanenaŵa ya''aga ba wangombakha ba niha baero, ena''ö te''orifi ira, ba wamönökhi horöra; lö mamalö-malö. Ba no göna ira fönu Lowalangi, fondrege.[14]', '["Faigi 1:2-6","HalZin 17:5,13; 8:1","HalZin 3:15; 7:52","HalZin 13:45; 14:2; Dan 9:26,27"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 17, 'Ba ya''aga andre, ya''ami ira talifusö, me lö ya''ami khöma, si lö arara — fa lö i''ila ami höröma, tenga fa lö ba dödöma ami — ba no humulu sibai dödöma, ena''ö fa''ila bawa ita,omasi sibai ndra''aga.', '["KorII 1:14","Faigi 3:9"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 18, 'Andrö möiga khömi mena''ö, ya''odo andre, Faulo, samuza ba samuza tö zui, ba no itimbaga Satana.', '["KorII 1:14","Faigi 3:9"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 19, 'Ha niha sa dötönaföma ba fa''omuso dödöma ba takulama, fanuno ya''aga? Tenga ya''ami göi, föna Zo''aya ya''ita andrö, Yesu, ba wa''asonia andrö dania? [15]', '["KorII 1:14","Faigi 3:9"]', NULL),
  (3388911, 'NT', 'Tesalonika I', 2, 20, 'Ya''ami sa lakhömima ba fa''omuso dödöma.[16]', '["KorII 1:14","Faigi 3:9"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 1, 'Andrö edönaga, ha ya''aga zi toröi furi ba Natena, me no tebai mataha sa''ae,[1]', '["HalZin 17:15,16","Faigi 1:1","Efes 3:13; TimII 3:12","HalZin 14:22","Mat 4:3"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 2, 'ba no mafatenge Dimoteo andrö, talifusöma, enoni Lowalangi andrö, ba duria somuso dödö andrö khö Keriso, ba wangabe''e''ö ya''ami, ba ba wamarou tödömi, ba wamatimi andrö,[2]', '["HalZin 17:15,16","Faigi 1:1","Efes 3:13; TimII 3:12","HalZin 14:22","Mat 4:3"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 3, 'ena''ö lö sangiwa tödö, ba wamakao andrö, noa sa mi''ila wa no nihonogöi khöda da''ö.[3]', '["HalZin 17:15,16","Faigi 1:1","Efes 3:13; TimII 3:12","HalZin 14:22","Mat 4:3"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 4, 'Me soga khömi göi sa''ae, ba no mahönagö maŵa''ö khömi, göna dania ita famakao, ba no itörö ba no mi''ila.[4]', '["HalZin 17:15,16","Faigi 1:1","Efes 3:13; TimII 3:12","HalZin 14:22","Mat 4:3"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 5, 'Andrö göi wa no ufatenge, me tebai utaha sa''ae, ba wamaigi famatimi andrö, ma no itandraigö ami sanandraigö andrö, ba ma no tobali zaya-zaya gölö halöŵöma andrö.[5]', '["HalZin 17:15,16","Faigi 1:1","Efes 3:13; TimII 3:12","HalZin 14:22","Mat 4:3"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 6, 'Ba iada''e, me no mangawuli khöma Dimoteo, moroi ba khömi, me no ituriagö khöma wa''asökhi wamatimi ba fa''asökhi wa''omasimi, awö wa lö''ö manö olifu ami ndra''aga, awö wehulu dödömi, ba wangila ya''aga, si mane fehulu dödöma, ba wangila ya''ami;', '[]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 7, 'andrö wa no terara dödöma, ba khömi andrö, ya''ami ira talifusö, ba wa''afökhö andrö fefu, ba ba wamakao andrö khöma, börö wamatimi andrö;', '[]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 8, 'noa sa auri ndra''aga iada''e, na abe''e ami ba khö Zo''aya.', '[]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 9, 'Hadia sa zulö, zi tola mabe''e khö Lowalangi, fangandrö saoha gölönia, ba khömi andrö, ba wa''omuso dödöma andrö fefu, ba khömi, föna Lowalangida?[6]', '["Faigi 2:19,20; YohIII 4","Rom 1:10,11","Faigi 4:9,10","Faigi 5:23; TesII 1:7,10"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 10, 'Bongi ma''ökhö ma''abölögö sibai wangandrö, ena''ö fa''ila bawa ita, ba ena''ö ma''asiwai hadia ia zambö na, ba wamatimi andrö.[7]', '["Faigi 2:19,20; YohIII 4","Rom 1:10,11","Faigi 4:9,10","Faigi 5:23; TesII 1:7,10"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 11, 'Ba ya''ia, Lowalangi, Amada, ba yamufolala ndra''aga khömi ba So''aya ya''ita andrö, Yesu.', '["Faigi 2:19,20; YohIII 4","Rom 1:10,11","Faigi 4:9,10","Faigi 5:23; TesII 1:7,10"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 12, 'Ba khömi, ba yamudou''ö So''aya wa''omasimi nawömi ba fa''omasimi niha fefu, si mane fa''omasima ami göi, ena''ö fahöna,[8]', '["Faigi 2:19,20; YohIII 4","Rom 1:10,11","Faigi 4:9,10","Faigi 5:23; TesII 1:7,10"]', NULL),
  (3389088, 'NT', 'Tesalonika I', 3, 13, 'ba wanga''aro''ö tödömi, ena''ö lö sinegu, ba wa''ohau-hau, föna Namada Lowalangi, ba wa''aso Zo''aya ya''ita, Yesu, na fao ni''amoni''ö andrö khönia, fefu. Yaduhu.[9]', '["Faigi 2:19,20; YohIII 4","Rom 1:10,11","Faigi 4:9,10","Faigi 5:23; TesII 1:7,10"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 1, 'Ba hadia na baero ö, ya''ami ira talifusö, ba ma''andrö khömi, ba mafarou dödömi, ba khö Zo''aya ya''ita andrö, Yesu; ena''ö tedou manö na wanörömi lala andrö, nirongomi khöma, he wisa ia, he wisa zomasi Lowalangi, si mane fanörömi sa''ae.[1]', '["KorI 15:58","TesII 3:6","KorI 6:18","KorI 6:13 b.t.","Rom 1:24","KorI 6:7-8","FetI 1:14-16","Luk 10:16; KorII 5:5"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 2, 'Noa sa mi''ila hadia goroisa, nibe''ema khömi, moroi khö Zo''aya ya''ita andrö, Yesu.[2]', '["KorI 15:58","TesII 3:6","KorI 6:18","KorI 6:13 b.t.","Rom 1:24","KorI 6:7-8","FetI 1:14-16","Luk 10:16; KorII 5:5"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 3, 'Da''ö sa wa''omasi Lowalangi fangohau-hau''ö ya''ami, ena''ö lö mibabaya wohorö,[3]', '["KorI 15:58","TesII 3:6","KorI 6:18","KorI 6:13 b.t.","Rom 1:24","KorI 6:7-8","FetI 1:14-16","Luk 10:16; KorII 5:5"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 4, 'ena''ö ila i''alui ndrongania zamösana, ena''ö ohau-hau, ba ena''ö lö hadia ia zaila ita.[4]', '["KorI 15:58","TesII 3:6","KorI 6:18","KorI 6:13 b.t.","Rom 1:24","KorI 6:7-8","FetI 1:14-16","Luk 10:16; KorII 5:5"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 5, 'Böi omasi ami mohorö-horö, si mane niha baero andrö, si lö mangila Lowalangi.[5]', '["KorI 15:58","TesII 3:6","KorI 6:18","KorI 6:13 b.t.","Rom 1:24","KorI 6:7-8","FetI 1:14-16","Luk 10:16; KorII 5:5"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 6, 'Ba fa böi ilimo dalifusönia zamösana, ba waniaga, ba böi i''alani: oi sa nihuku Zo''aya dania da''ö, si mane ni''ombakha''öma khömi sa''ae göi, si mane nifaduhu''öma khömi.[6]', '["KorI 15:58","TesII 3:6","KorI 6:18","KorI 6:13 b.t.","Rom 1:24","KorI 6:7-8","FetI 1:14-16","Luk 10:16; KorII 5:5"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 7, 'Tenga sa ba walösökhi, me ikaoni ita Lowalangi, ba wangohau-hau''ö ya''ita ikaoni ita.[7]', '["KorI 15:58","TesII 3:6","KorI 6:18","KorI 6:13 b.t.","Rom 1:24","KorI 6:7-8","FetI 1:14-16","Luk 10:16; KorII 5:5"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 8, 'Andrö sa, na so zangositengagö da''ö, ba tenga niha i''ositengagö, Lowalangi i''ositengagö, same''e göi Eheha ni''amoni''ö andrö khömi.[8]', '["KorI 15:58","TesII 3:6","KorI 6:18","KorI 6:13 b.t.","Rom 1:24","KorI 6:7-8","FetI 1:14-16","Luk 10:16; KorII 5:5"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 9, 'Ba ba wangomasi''ö talifusö andrö, ba alakha lö masura khömi hadia ia; ya''ami andrö, ba noa sa ifahaö Lowalangi, ena''ö faoma mi''omasi''ö nawömi.[9]', '["Faigi 3:12; Rom 12:10; YohI 2:27","Faigi 1:7; 3:12","TesII 3:6-12; Efes 4:28","FetI 2:12"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 10, 'Ba milau sa''ae da''ö, ba dalifusö andrö, fefu, ba danö Makedonia ma''asagörö. Ba mafarou dödömi, ya''ami ira talifusö, ena''ö tedou-dou manö na khömi,[10]', '["Faigi 3:12; Rom 12:10; YohI 2:27","Faigi 1:7; 3:12","TesII 3:6-12; Efes 4:28","FetI 2:12"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 11, 'ba ena''ö mi''alui, fa ahono ami, fa ifaigi zamösana hadia ia khönia, ba ihalö halöŵönia, simane niŵa''öma khömi;[11]', '["Faigi 3:12; Rom 12:10; YohI 2:27","Faigi 1:7; 3:12","TesII 3:6-12; Efes 4:28","FetI 2:12"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 12, 'ena''ö lö sinegu zi so baero andrö, khömi, ba ena''ö lö moguna khömi niha bö''ö.[12]', '["Faigi 3:12; Rom 12:10; YohI 2:27","Faigi 1:7; 3:12","TesII 3:6-12; Efes 4:28","FetI 2:12"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 13, 'Balö edöna mabini''ö khömi, ya''ami ira talifusö, he wisa ba zi no mate andrö, fa böi abu dödömi, si mane tanö bö''ö andrö, si lö fanötöna.[13]', '["KorI 16:16 b.t.","KorI 6:14","KorI 15:23,51 b.t.","TesII 1:7 b.t.; Mat 24:31","Yoh 12:26; 14:3"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 14, 'Na mamati ita sa, no mate Yesu ba no ifuli auri, ba ba zi manö göi ifafatörö''ö khö Yesu Lowalangi zi no mate andrö, awönia.[14]', '["KorI 16:16 b.t.","KorI 6:14","KorI 15:23,51 b.t.","TesII 1:7 b.t.; Mat 24:31","Yoh 12:26; 14:3"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 15, 'Taroma li Lowalangi sa niŵa''öma andre khömi: ya''ita andre, sauri, si tosai, irugi wa''aso Zo''aya andrö, ba tenga föna zi no mate ita dania.[15]', '["KorI 16:16 b.t.","KorI 6:14","KorI 15:23,51 b.t.","TesII 1:7 b.t.; Mat 24:31","Yoh 12:26; 14:3"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 16, 'Ya''ia dania, So''aya, zi möi mitou, moroi ba zorugo, na so we''ao andrö, na mu''ao zatua mala''ika andrö, na tefoli dorofe Lowalangi andrö, ba oföna maoso zi no mate andrö, ba khö Keriso.[16]', '["KorI 16:16 b.t.","KorI 6:14","KorI 15:23,51 b.t.","TesII 1:7 b.t.; Mat 24:31","Yoh 12:26; 14:3"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 17, 'Awena dania tefazaŵa ita, ya''ita sauri, si tosai, ba lawuo. fao ita khöra, ba wamaondragö So''aya, ba dalu mbanua; ba tobali awö Zo''aya ita, silö mamalö-malö.[17]', '["KorI 16:16 b.t.","KorI 6:14","KorI 15:23,51 b.t.","TesII 1:7 b.t.; Mat 24:31","Yoh 12:26; 14:3"]', NULL),
  (3391156, 'NT', 'Tesalonika I', 4, 18, 'Andrö faoma mibe''e fondrara dödö nawömi daroma li andre.', '["KorI 16:16 b.t.","KorI 6:14","KorI 15:23,51 b.t.","TesII 1:7 b.t.; Mat 24:31","Yoh 12:26; 14:3"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 1, 'Ba ba mbaŵania, ba ba ginötönia andrö, ba lö moguna khömi lasura khömi hadia ia, ya''ami ira talifusö.', '["FetII 3:10; Mat 24:3,36,43 b.t.","Yer 6:14; Luk 21:35"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 2, 'Ya''ami sa''ae zangila sibai hulö wa''aso zanagö, ba zi bongi, si manö wa''aso mbawa Zo''aya andrö dania.[1]', '["FetII 3:10; Mat 24:3,36,43 b.t.","Yer 6:14; Luk 21:35"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391157, 'NT', 'Tesalonika I', 5, 3, 'Na laŵa''ö''sa''ae dania: No atulö, no ahono; awena dania i''ozumagö ikhamö ira fa''atekiko, hulö si mane fa''afökhö hulu ba zanabina, ba tebai moloi ira.[2]', '["FetII 3:10; Mat 24:3,36,43 b.t.","Yer 6:14; Luk 21:35"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 4, 'Ba ya''ami, ira talifusö, ba tenga si so ba zogömi-gömi, fa ikhamö ami baŵa andrö hulö zanagö.', '["Efes 5:8","Rom 13:11 b.t.; FetI 5:8; 4:7","Faigi 1:3; Efes 6:14-17","TimI 2:4; TesII 2:14","Rom 14:7-9","Heb 10:24 b.t."]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 5, 'Ono haga sa ami fefu, ono zi ma''ökhö; tenga ba zi bongi so ita, ba tenga ba zogömi-gömi.[3]', '["Efes 5:8","Rom 13:11 b.t.; FetI 5:8; 4:7","Faigi 1:3; Efes 6:14-17","TimI 2:4; TesII 2:14","Rom 14:7-9","Heb 10:24 b.t."]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 6, 'Ba böi mörö-mörö ita, si mane tanö bö''ö andrö, ena''ö si no maoso ita, si lö mabu-mabu.[4]', '["Efes 5:8","Rom 13:11 b.t.; FetI 5:8; 4:7","Faigi 1:3; Efes 6:14-17","TimI 2:4; TesII 2:14","Rom 14:7-9","Heb 10:24 b.t."]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 7, 'Si mörö sa, ba ba zi bongi mörö, ba si mabu andrö, ba ba zi bongi mabu.', '["Efes 5:8","Rom 13:11 b.t.; FetI 5:8; 4:7","Faigi 1:3; Efes 6:14-17","TimI 2:4; TesII 2:14","Rom 14:7-9","Heb 10:24 b.t."]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 8, 'Ba ya''ita, me no ba zi ma''ökhö ita, ba böi mabu-mabu ita, ta''obaru göröba famati andrö, ba öröba fa''omasi, ba ta''otakula dakula andrö, fanötöna fangorifi.[5]', '["Efes 5:8","Rom 13:11 b.t.; FetI 5:8; 4:7","Faigi 1:3; Efes 6:14-17","TimI 2:4; TesII 2:14","Rom 14:7-9","Heb 10:24 b.t."]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 9, 'Tenga sa ba wamatörö fönu khöda ihonogöi ita Lowalangi, ha ba wanöndra fangorifi, ba khö Zo''aya ya''ita, Yesu Keriso, [6]', '["Efes 5:8","Rom 13:11 b.t.; FetI 5:8; 4:7","Faigi 1:3; Efes 6:14-17","TimI 2:4; TesII 2:14","Rom 14:7-9","Heb 10:24 b.t."]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 10, 'si no mate salahida, ena''ö auri ita, fao khönia, awönia, he si no maoso, ba he si mörö ita.[7]', '["Efes 5:8","Rom 13:11 b.t.; FetI 5:8; 4:7","Faigi 1:3; Efes 6:14-17","TimI 2:4; TesII 2:14","Rom 14:7-9","Heb 10:24 b.t."]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 11, 'Andrö faoma mifarou dödö nawömi, ba faoma mitolo nawömi, si mane folaumi sa''ae göi.[8]', '["Efes 5:8","Rom 13:11 b.t.; FetI 5:8; 4:7","Faigi 1:3; Efes 6:14-17","TimI 2:4; TesII 2:14","Rom 14:7-9","Heb 10:24 b.t."]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 12, 'Ba ma''andrö khömi, ya''ami ira talifusö, böi zi lö aboto ba dödömi zino erege tödö wohalöŵö ba khömi, ba fönami andrö, ba khö Zo''aya, samobawa lala khömi.[9]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 13, 'ba böi zi lö mifosumange ira, ba mi''omasi''ö sibai ira, börö halöŵöra andrö. Böi mifagua-gua khö nawömi![10]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 14, 'Ba mafarou dödömi, ya''ami ira talifusö, mitegu zi lö atulö folo''ö huku, mirara dödö zabu tödö; mitolo zambö fa''abölö, mibologö dödömi khöra fefu.[11]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 15, 'Mifaigi, fa böi falukha zanulöni si lö sökhi awönia si lö sökhi; ba böi mifamalö-malö wangalui folau si sökhi, he khö nawömi, ba he ba niha bö''ö fefu.[12]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 16, 'Böi mamalö-malö wa''omuso dödömi.[13]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 17, 'Böi aetu-aetu wangandrömi.[14]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 18, 'Fefu hadia ia, ba mi''andrö saoha gölö; da''ö sa zomasi Lowalangi, ba khö Keriso Yesu, ba khömi.[15]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 19, 'Böi mibunu Geheha andrö.[16]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 20, 'Böi mi''ositengagö wama''ele''ö andrö.[17]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 21, 'Mitandra fefu, hadia ia, ba si sökhi, ba mihalö khömi.[18]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 22, 'Si lö sökhi, fefu, hadia ia ngawalö, ba böi mibabaya.[19]', '["TimI 5:17","Heb 13:17","TesII 3:6,11 b.t.; Gal 6:1,2","Rom 12:9,17; FetI 3:9-11","Fil 4:4","Luk 18:1","Efes 5:20","KorI 14:39; TimI 4:14","KorI 14:1 b.t.","KorI 14:29; YohI 4:1","Faigi 4:12"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 23, 'Ba ya''ia, Lowalangi wa''ohahau dödö andrö, ba yamufaulugö wangehao ya''ami, ena''ö terorogö gehehami, awö nosomi, awö mbotomi, fa lö hadia ia, fa lö sinegu, irugi wa''aso Zo''aya ya''ita andrö, Yesu Keriso![20]', '["Faigi 3:13; Heb 13:20 b.t.; KorI 1:8","TesII 3:3; KorI 1:9","TesII 3:1","Rom 16:16","Rom 16:20,24"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 24, 'Lö faröi zogaoni ya''ami andrö, ya''ia göi zamalua dania.[21]', '["Faigi 3:13; Heb 13:20 b.t.; KorI 1:8","TesII 3:3; KorI 1:9","TesII 3:1","Rom 16:16","Rom 16:20,24"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 25, 'Mi''angandrö, salahima, ya''ami ira talifusö.[22]', '["Faigi 3:13; Heb 13:20 b.t.; KorI 1:8","TesII 3:3; KorI 1:9","TesII 3:1","Rom 16:16","Rom 16:20,24"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 26, 'Mi''owai dalifusö fefu fa''agosa bawa ni''amoni''ö andrö.[23]', '["Faigi 3:13; Heb 13:20 b.t.; KorI 1:8","TesII 3:3; KorI 1:9","TesII 3:1","Rom 16:16","Rom 16:20,24"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 27, 'Ube''e ba hölu ami, khö Zo''aya, fa mifabaso''ö zura andre, ba dalifusö fefu.', '["Faigi 3:13; Heb 13:20 b.t.; KorI 1:8","TesII 3:3; KorI 1:9","TesII 3:1","Rom 16:16","Rom 16:20,24"]', NULL),
  (3391157, 'NT', 'Tesalonika I', 5, 28, 'Yafalukha ami wa''ebua dödö Zo''aya ya''ita, Yesu Keriso.[24]', '["Faigi 3:13; Heb 13:20 b.t.; KorI 1:8","TesII 3:3; KorI 1:9","TesII 3:1","Rom 16:16","Rom 16:20,24"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 1, 'Faulo zanura da''e ba Siliwano ba Timoteo, ba mbanua andrö ba Desalonika, ba khö Namada, Lowalangi, ba ba khö Zo''aya, Yesu Keriso.[1]', '["TesI 1:1","KorI 1:3"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 2, 'Yafalukha ami wa''ebua dödö, khö Namada Lowalangi ba khö Zo''aya, Yesu Keriso. [2]', '["TesI 1:1","KorI 1:3"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 3, 'Mo''ömö ndra''aga khö Lowalangi, lö mafamalö-malö wangandrö saoha gölö khönia, börö ami, ya''ami ira talifusö; si manö zi nangea, me manöi sibai wamatimi, ba dozi ami, ba tedou-dou wa''omasimi nawömi.[3]', '["TesI 1:2,3; 3:6","TesI 2:14,19","Fil 1:28; FetI 4:17","Rom 12:19","FetI 4: 13; TesI 4:16","Mat 25: 41,46","HalZin 1:11; Kol 3:4"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 4, 'Tobali masuno ndra''aga, ba mbanua Lowalangi misa, ba khömi andrö, börö wa''anau gölömi ba famatimi andrö, ba wolohi andrö fefu, khömi, ba ba wamakao andrö, nitahami.[4]', '["TesI 1:2,3; 3:6","TesI 2:14,19","Fil 1:28; FetI 4:17","Rom 12:19","FetI 4: 13; TesI 4:16","Mat 25: 41,46","HalZin 1:11; Kol 3:4"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 5, 'Tandra wanguhuku Lowalangi andrö da''ö, fanguhuku si no atulö, wa tola khömi dania mbanua Lowalangi andrö, da''ö sa göi mbörö, wa mitaha wamakao.[5]', '["TesI 1:2,3; 3:6","TesI 2:14,19","Fil 1:28; FetI 4:17","Rom 12:19","FetI 4: 13; TesI 4:16","Mat 25: 41,46","HalZin 1:11; Kol 3:4"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 6, 'Me atulö sa atö ba Lowalangi, tesulöni wamakao ba zamakao ya''ami;[6]', '["TesI 1:2,3; 3:6","TesI 2:14,19","Fil 1:28; FetI 4:17","Rom 12:19","FetI 4: 13; TesI 4:16","Mat 25: 41,46","HalZin 1:11; Kol 3:4"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 7, 'ba khömi, nifakao andrö, ba fangokafu dödö, awöma, na to''ele dania Zo''aya, Yesu, moroi ba zorugo, awö mala''ika wa''abölönia andrö,[7]', '["TesI 1:2,3; 3:6","TesI 2:14,19","Fil 1:28; FetI 4:17","Rom 12:19","FetI 4: 13; TesI 4:16","Mat 25: 41,46","HalZin 1:11; Kol 3:4"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 8, 'ba hola-hola galitö, na ilau mbalö ba zi lö aboto ba dödö Lowalangi, ba ba zi lö molo''ö turia somuso dödö andrö, khö Zo''aya ya''ita, Yesu.', '["TesI 1:2,3; 3:6","TesI 2:14,19","Fil 1:28; FetI 4:17","Rom 12:19","FetI 4: 13; TesI 4:16","Mat 25: 41,46","HalZin 1:11; Kol 3:4"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 9, 'Göna fotu dania ira, fa''atekiko si lö aetu, moroi ba mbawa Zo''aya, ba moroi ba lakhömi wa''abölönia andrö,[8]', '["TesI 1:2,3; 3:6","TesI 2:14,19","Fil 1:28; FetI 4:17","Rom 12:19","FetI 4: 13; TesI 4:16","Mat 25: 41,46","HalZin 1:11; Kol 3:4"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 10, 'na so ia, ba wamolakhömi ya''ia, ba niha ni''amoni''ö andrö khönia, ba ba wame''e sahöli-höli dödö ya''ia, ba zamati andrö, fefu — me no faduhu dödömi, ba wamaduhu''öma andrö — na luo da''ö.[9]', '["TesI 1:2,3; 3:6","TesI 2:14,19","Fil 1:28; FetI 4:17","Rom 12:19","FetI 4: 13; TesI 4:16","Mat 25: 41,46","HalZin 1:11; Kol 3:4"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 11, 'Andrö göi lö mafamalö-malö wangandrö, salahimi, ena''ö ibe''e Lowalangida, si nangea nikaoni ami; ba ena''ö iforege wamo''ahonoa fa''omasimi zi sökhi, awö halöŵö wamati andrö,[10]', '["TesI 2:3; 2:12"]', NULL),
  (3391158, 'NT', 'Tesalonika II', 1, 12, 'ena''ö tefolakhömi döi Zo''aya ya''ita andrö, Yesu, ba khömi, ba ena''ö tefolakhömi ami, ba khönia, dali wa''ebua dödö Lowalangida andrö ba fa''ebua dödö Zo''aya, Yesu Keriso.', '["TesI 2:3; 2:12"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 1, 'Ba ma''andrö khömi, ya''ami ira talifusö, ba wa''aso Zo''aya ya''ita, Yesu Keriso andrö, ba ba wangowulo ya''ita khönia,[1]', '["TesI 4:15-17","TesI 5:2; Mat 24:4 b.t."]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 2, 'fa böi alio mangiwa dödömi, ba böi alio tokea, he ba geheha, ba he ba daroma li, ba he ba zura, hulö na ya''aga zama''ohe''ö, hulö na no irugi luo Zo''aya andrö.[2]', '["TesI 4:15-17","TesI 5:2; Mat 24:4 b.t."]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 3, 'Böi ifaelungu ami niha, gofu he wisa; lö''ö sa tola lö itörö ua fa''aheta andrö, ba lö tola lö oroma ua niha golalöŵa andrö, ono wa''atekiko andrö[3]', '["Mat 24:10-12; TimI 4:1 b.t.; FetII 3:3 b.t.; Dan 7:25; YohI 2:18","Dan 11:36; Yes 14:13-14; Rom 13:5 b.t."]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 4, 'si fa''udu andrö, sangebua''ö ya''ia, moroi ba zotöi Lowalangi ba moroi ba zotöi ni''amoni''ö fefu, tobali dumadao ia ba gosali Lowalangi andrö, ba ibali''ö Lowalangi ia.[4]', '["Mat 24:10-12; TimI 4:1 b.t.; FetII 3:3 b.t.; Dan 7:25; YohI 2:18","Dan 11:36; Yes 14:13-14; Rom 13:5 b.t."]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 5, 'Hadia, lö itörö tödömi, wa no uŵa''ö khömi da''ö, me sodo khömi na?', '["YohI 4:3"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 6, 'Ba iada''e, ba no mi''ila hadia zanaha na inötö wa''oromania andrö.', '["YohI 4:3"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 7, 'Noa sa abölö zi tobini andrö, olalöŵa andrö, hatö sanaha andrö, irege da''e, niheta.[5]', '["YohI 4:3"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 8, 'Ba awena dania oroma zo''olalöŵa andrö, nifakiko Zo''aya, Yesu, dania, Eheha mbawania andrö, nifufunia dania lakhömi wa''asonia andrö.[6]', '["Yes 11:4; Dan 7:11","Yoh 8:44; Mat 24:24; Fam 13:13 b.t.","KorII 4:3,4"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 9, 'Fa''abölö Zatana wama''aso ya''ia, oi so wa''abölö ba tandra ba ila-ila faya,[7]', '["Yes 11:4; Dan 7:11","Yoh 8:44; Mat 24:24; Fam 13:13 b.t.","KorII 4:3,4"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 10, 'ba oi so wamaelungu horö andrö, ba zi tetibo andrö, sulö wa lö nifonahara fa''omasi zi duhu andrö, fangorifira mena''ö.[8]', '["Yes 11:4; Dan 7:11","Yoh 8:44; Mat 24:24; Fam 13:13 b.t.","KorII 4:3,4"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 11, 'Ba andrö ifa''ohe''ö khöra Lowalangi zabölö wamaelungu, ena''ö faduhu dödöra ba waya andrö.[9]', '["Faigi 2:3,9; Mat 24:5,11; RazI 22:22","Yoh 3:18"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 12, 'ena''ö tehuku fefu zi lö faduhu tödö ba zi duhu andrö, si no omasi si lö atulö.[10]', '["Faigi 2:3,9; Mat 24:5,11; RazI 22:22","Yoh 3:18"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 13, 'Ba ya''aga, ba mo''ömö khö Lowalangi, böi mamalö-malö wangandröma saoha gölö khönia, börö ami, ya''ami ira talifusö, ni''omasi''ö, me no itutuyu ami Lowalangi, i''otarai mböröta, ba wangorifi andrö, ba wangohau-hau Geheha andrö, ba ba wamati ba zi duhu,[11]', '["Efes 1:4","TesI 5:9"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 14, 'ba nikaoninia ya''ami, turia somuso dödö andrö khöma ba wangalui lakhömi andrö, khö Zo''aya ya''ita, Yesu Keriso.[12]', '["Efes 1:4","TesI 5:9"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 15, 'Ba mi''abe''e''ö ami, ya''ami ira talifusö, ba böi miböhöli gamakhoita andrö, ni''ombakha''ö khömi, he ba daroma li, ba he ba zura andrö khöma.', '[]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 16, 'Ba ya''ia, So''aya ya''ita, Yesu Keriso ba Lowalangi, Amada, si no mangomasi''ö ya''ita, ba si no mame''e fondrara dödö khöda, si lö aetu, awö wanötöna, si sökhi, ba wa''ebua dödö,[13]', '["FetI 5:10","TesI 3:13"]', NULL),
  (3391159, 'NT', 'Tesalonika II', 2, 17, 'ba yamurara dödömi ba yamu''a''aro''ö ba ngawalö mbua-bua fefu, ba ba ngawalö daroma li, si sökhi.[14]', '["FetI 5:10","TesI 3:13"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 1, 'Ba hadia na mbö''önia, ya''ami ira talifusö, ba mi''angandrö, salahima ena''ö alio terongo misa daroma li Zo''aya andrö, ba ena''ö tefolakhömi, si mane ba khömi,[1]', '["TesI 5:25; Kol 4:3","Yoh 6:44; HalZin 18:1-17","TesI 5:24","Gal 5:10"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 2, 'ba ena''ö te''efa''ö ndra''aga ba niha andrö, si lö tödö, ba si lö sökhi; lö''ö sa dozi mamati.[2]', '["TesI 5:25; Kol 4:3","Yoh 6:44; HalZin 18:1-17","TesI 5:24","Gal 5:10"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 3, 'Ba lö''ö sa faröi Zo''aya, ba ya''ia zangabe''e ya''ami, ba irorogö ami, itimba khömi zi lö sökhi andrö.[3]', '["TesI 5:25; Kol 4:3","Yoh 6:44; HalZin 18:1-17","TesI 5:24","Gal 5:10"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 4, 'Ba madöna-döna khömi, ba khö Zo''aya, mi''o''ö niŵa''öma khömi, he iada''e, ba he dania.[4]', '["TesI 5:25; Kol 4:3","Yoh 6:44; HalZin 18:1-17","TesI 5:24","Gal 5:10"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 5, 'Ba ya So''aya zamatörö tödömi ba wa''omasi Lowalangi andrö, ba ba wanaha tödö andrö, khö Keriso.', '["TesI 5:25; Kol 4:3","Yoh 6:44; HalZin 18:1-17","TesI 5:24","Gal 5:10"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 6, 'Ba maŵa''ö khömi, ya''ami ira talifusö, ba döi Zo''aya ya''ita andrö, Yesu Keriso, mifabali ami ba dalifusö si lö sökhi bua-bua, gofu ha niha ia, si lö manörö lala nirongora khöma.[5]', '["Rom 16:17; KorI 5:11"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 7, 'Noa sa mi''ila he wisa wolo''ö khöma; lö''ö sa nitöröma si lö göna, ba khömi andrö;[6]', '["TesI 2:10","TesI 2:9","HalZin 23:35; KorI 9:6; 4:16","MozI 3:19"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 8, 'ba lö''ö göi nihalöma balazo, si lö nibe''ema böli, noa sa erege dödöma, ba no akao ndra''aga, wohalöŵö, bongi ma''ökhö, fa böi abu dödömi khöma, ha niha ami.[7]', '["TesI 2:10","TesI 2:9","HalZin 23:35; KorI 9:6; 4:16","MozI 3:19"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 9, 'Tenga fa lö tola mena''ö, ba ena''ö mabe''e famaedo ndra''aga khömi, ena''ö mi''o''ö khöma.[8]', '["TesI 2:10","TesI 2:9","HalZin 23:35; KorI 9:6; 4:16","MozI 3:19"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 10, 'Da''ö sa göi niŵa''öma khömi, me soga khömi; si lö edöna mohalöŵö, ba böi yamanga göi.[9]', '["TesI 2:10","TesI 2:9","HalZin 23:35; KorI 9:6; 4:16","MozI 3:19"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 11, 'Noa sa marongo, so ösa ba khömi zi lö sökhi bua-bua, ma''ifu lö mohalöŵö, molau faya-faya.', '["TesI 2:10","TesI 2:9","HalZin 23:35; KorI 9:6; 4:16","MozI 3:19"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 12, 'Ba da''ö niŵa''öma ba zi manö, ba mafarou dödöra, ba khö Zo''aya, Yesu Keriso: ena''ö lahonogö ira ba halöŵöra, ba ena''ö la''a gölöra, balazora.[10]', '["TesI 4:11","Gal 6:9","Faigi 3:6; Tit 3:10","Mat 18:15 b.t.; TesI 5:14"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 13, 'Ba ya''ami ira talifusö, ba böi atage ami wolau si sökhi.[11]', '["TesI 4:11","Gal 6:9","Faigi 3:6; Tit 3:10","Mat 18:15 b.t.; TesI 5:14"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 14, 'Ba na so zi lö molo''ö niŵa''öma andrö, ba zura, ba böi olifu ami, böi fahuwu ami khönia, ena''ö aila ia.[12]', '["TesI 4:11","Gal 6:9","Faigi 3:6; Tit 3:10","Mat 18:15 b.t.; TesI 5:14"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 15, 'Ba böi hulö zi fa''udu ami khönia, ba mitegu ia, si mane si fatalifusö.[13]', '["TesI 4:11","Gal 6:9","Faigi 3:6; Tit 3:10","Mat 18:15 b.t.; TesI 5:14"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 16, 'Ba ya''ia, So''aya fa''ohahau dödö andrö, ba yamube''e khömi wa''ohahau dödö andrö, böi yamamalö-malö, gofu he wisa lala. Yamutolo ami fefu So''aya.[14]', '["Rom 15:33","Faigi 2:2; KorI 16:21","TesI 5:28"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 17, 'Fangowaigu da''e, tangagu zanura, tanga Waulo andre; da''ö dandra ba zuragu fefu, si manö wanuragu.[15]', '["Rom 15:33","Faigi 2:2; KorI 16:21","TesI 5:28"]', NULL),
  (3391160, 'NT', 'Tesalonika II', 3, 18, 'Yafalukha ami fefu wa''ebua dödö khö Zo''aya ya''ita, Yesu Keriso.[16]', '["Rom 15:33","Faigi 2:2; KorI 16:21","TesI 5:28"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 1, 'Faulo zanura da''e, sinenge Keriso Yesu andrö, dali goroisa Lowalangi, sangorifi ya''ita, ba oroisa Keriso Yesu andrö, tötönaföda,[1]', '["KorI 1:1; Kol 1:27","TimII 1:2; KorI 4:17; Tit 1:4"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 2, 'khö Dimoteo andrö, si ndruhu nononia andrö, ba wamati. Yafalukha''ö wa''ebua dödö ba fa''ahakhö dödö ba fa''ohahau dödö, khö Namada Lowalangi, ba khö Keriso Yesu, So''aya ya''ita.[2]', '["KorI 1:1; Kol 1:27","TimII 1:2; KorI 4:17; Tit 1:4"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 3, 'Si mane famarougu tödöu, fa ö''iagö Nefeso, me möido ba Makedonia, ena''ö öŵa''ö khöra ösa, böi lafaehusi wamahaö,[3]', '["HalZin 20:1–4","Faigi 4:7; Tit 1:14"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 4, 'ba böi la''o''ö gamaedola andrö, ba fanutunö nga''ötö andrö, si lö aetu, famobörö wagua-guasa, moroi ba wogunania ba wamatörö Lowalangi banuania andrö, ba wamati.[4]', '["HalZin 20:1–4","Faigi 4:7; Tit 1:14"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 5, 'Ba ba da''ö moguna goroisa, ba wanga''asogö fa''omasi, soroi ba dödö si no ohau-hau, ba ba dödö si lö fategu, ba ba wamati si lö famini;[5]', '["Kol 3:14; Rom 12:9","Faigi 6:4 b.t. 20"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 6, 'noa sa so ösa zi no mondröi da''ö, solau huhuo si lö boto.[6]', '["Kol 3:14; Rom 12:9","Faigi 6:4 b.t. 20"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 7, 'No labali''ö samahaö ba goroisa ira, ba lö saboto ba dödöra, he niŵa''öra, ba he nifaduhu''öra.', '["Rom 7:12","Gal 5:23","KorI 6:9 b.t.; MozII 21:16","TesI 2:4"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 8, 'Ba no ta''ila, si sökhi goroisa andrö, na atulö wamoguna''ö niha ya''ia,[7]', '["Rom 7:12","Gal 5:23","KorI 6:9 b.t.; MozII 21:16","TesI 2:4"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 9, 'na no i''ila, tenga ba zatulö goroisa andrö, ha ba zolalö, ba ba zi lö mamondrongo li, ba ba zi no mangerogö Lowalangi, ba ba zamazökhi horö, ba ba zi lö ohau-hau, ba ba zi lö sökhi, ba zamunu ama, ba ba zamunu ina, ba ba zange''e,[8]', '["Rom 7:12","Gal 5:23","KorI 6:9 b.t.; MozII 21:16","TesI 2:4"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 10, 'ba ba zohorö, ba ba zohoröni ono matua, ba zanagö niha, ba ba zofaya-faya, ba ba zi möi ba hölu ba zi lö duhu, ba ma hadia ia mbö''önia, si lö faudu ba wamahaö si ndruhu andrö,[9]', '["Rom 7:12","Gal 5:23","KorI 6:9 b.t.; MozII 21:16","TesI 2:4"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 11, 'dali duria somuso dödö andrö, turia lakhömi Lowalangi sohahau tödö andrö nibe''e ba dangagu.[10]', '["Rom 7:12","Gal 5:23","KorI 6:9 b.t.; MozII 21:16","TesI 2:4"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 12, 'U''andrö saoha gölö khö Keriso Yesu, So''aya ya''ita, sangabölö''ö ya''o, me no iŵa''ö tödönia, lö faröi ndra''ö, me ifataro ndra''o ba halöŵö andrö,', '["Gal 1:13 b.t.; HalZin 8:3; 3:17"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 13, 'ya''odo andre, sanandraŵa föna ba solohi ba sangosiwawöi; ba no falukhado wa''ahakhö dödö, me lö''ö na u''ila watahögö, me ulau da''ö, me lö faduhu dödögu na.[11]', '["Gal 1:13 b.t.; HalZin 8:3; 3:17"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 14, 'Bo no fahöna wa''ebua dödö Zo''aya ya''ita andrö, awö wamati ba awö wa''omasi andrö, ba khö Keriso Yesu.[12]', '["KorI 15:10","Mat 1:21; 9:13","Rom 16:27; Yud 25"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 15, '14 Bo no fahöna wa''ebua dödö Zo''aya ya''ita andrö, awö wamati ba awö wa''omasi andrö, ba khö Keriso Yesu. 15 Si ndruhu daroma li andrö ba si nangea tafonaha manö, wa no möi ba guli danö Keriso Yesu, ba wangorifi si so horö; sebuara ndra''odo. 16 Ba andrö tehakhösi tödö ndra''o, ena''ö ba khögu, ba zebua honö andrö, i''oigö wangoroma''ö fa''ebolo dödönia Yesu Keriso, duma-duma ba zamati khönia dania ba wanema fa''auri si lö aetu. 17 Ba razo zi lö aetu andrö, si lö tebulö, si lö oroma, Lowalangi si ha samösa andrö, ba nifosumange ba nisuno, irugi zi lö aetu. Yaduhu.', '["KorI 15:10","Mat 1:21; 9:13","Rom 16:27; Yud 25"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 16, 'Ba andrö tehakhösi tödö ndra''o, ena''ö ba khögu, ba zebua honö andrö, i''oigö wangoroma''ö fa''ebolo dödönia Yesu Keriso, duma-duma ba zamati khönia dania ba wanema fa''auri si lö aetu.', '["Mat 1:21; 9:13"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 17, 'Ba razo zi lö aetu andrö, si lö tebulö, si lö oroma, Lowalangi si ha samösa andrö, ba nifosumange ba nisuno, irugi zi lö aetu. Yaduhu.[14]', '["KorI 15:10","Mat 1:21; 9:13","Rom 16:27; Yud 25"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 18, 'Da''ö goroisagu khöu, ya''ugö onogu Timoteo, dali li wama''ele''ö andrö föna, nitandrösaigö khöu, ena''ö ö''o''ö da''ö, wolau fasöndrata andrö, si sökhi,[15]', '["Faigi 6:12","Faigi 6:10–21; HalZin 24:16","TimII 2:17; 18:4–14; KorI 5:5"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 19, 'ba ena''ö lö öböhöli wamati, ba ena''ö lö tebulö wa lö sinegu dödöu khöu; noa sa so ösa zi no manibo da''ö, ba no taya wamatira, hulö zaboto owo.[16]', '["Faigi 6:12","Faigi 6:10–21; HalZin 24:16","TimII 2:17; 18:4–14; KorI 5:5"]', NULL),
  (3391783, 'NT', 'Timoteo I', 1, 20, 'Ya''ia khö ndra Himenaio Alesandro, nitou''ögu ba danga Zatana, ena''ö te''otu''ö ira, fa böi sa''ae manandraŵa.[17]', '["Faigi 6:12","Faigi 6:10–21; HalZin 24:16","TimII 2:17; 18:4–14; KorI 5:5"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 1, 'Ba si föföna sibai, ba ufarou dödömi ba wangalulu ba ba wangandrö, ba ba wangandrö salahi nawö, ba ba wangandrö saoha gölö; mifarahugö niha fefu.[1]', '["Fil 4:6"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 2, 'Mifarahugö razo ba salaŵa, fefu, ena''ö ahono ita, ba ena''ö lö hadia ia, ena''ö a''oi so wolo''ö khö Lowalangi, awö wa''amoadu.', '["Fil 4:6"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 3, 'Da''ö zi sökhi, da''ö zomasi Lowalangi, sangorifi ya''ita,', '["Hes 18:23; FetII 3:9","Yoh 17:3; Heb 9:15","Tit 2:14; Mat 20:28"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 4, 'somasi na ahori te''orifi niha, na dozi lasöndra wa''aboto ba dödöra zi duhu.[2]', '["Hes 18:23; FetII 3:9","Yoh 17:3; Heb 9:15","Tit 2:14; Mat 20:28"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 5, 'Ha sa samösa Lowalangi, ba ha samösa zama''ema ba gotaluara Lowalangi niha, ya''ia niha andrö, Keriso Yesu,[3]', '["Hes 18:23; FetII 3:9","Yoh 17:3; Heb 9:15","Tit 2:14; Mat 20:28"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 6, 'si no mame''e ya''ia, höli niha fefu, nifaduhu''ö ba ginötönia,[4]', '["Hes 18:23; FetII 3:9","Yoh 17:3; Heb 9:15","Tit 2:14; Mat 20:28"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 7, 'Ba nifataro ya''o sangombakha ba sinenge — si duhu niŵa''ögu, tenga faya — samahaö niha baero, ba wamati ba ba zi duhu.[5]', '["TimII 1:11; Rom 9:1; 1:5"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391784, 'NT', 'Timoteo I', 2, 8, 'Ba da''ö zomasido: mangandrö ndra matua, gofu heza so ira, lafazaŵa danga ni''amoni''ö, si lö fönu ba si lö fagua-guasa.[6]', '["KorI 14:34; Mar 11:25; Yak 1:6","FetI 3:3–5","Tit 2:3 b.t.","KorI 14:34–35","Efes 5:22; Kol 3:18; FetII 3:1 b.t.","MozI 2:18 b.t.","KorII 11:3; MozI 3:6","Tit 2:4–5; KorI 7:25,26"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 9, 'Si manö göi ndra alawe, ndramangehao baru soadu, ba yafao wa''aila ba fa''amoadu; böi fondrandra bu ba mani-mani ba nukha sebua böli,[7]', '["KorI 14:34; Mar 11:25; Yak 1:6","FetI 3:3–5","Tit 2:3 b.t.","KorI 14:34–35","Efes 5:22; Kol 3:18; FetII 3:1 b.t.","MozI 2:18 b.t.","KorII 11:3; MozI 3:6","Tit 2:4–5; KorI 7:25,26"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 10, 'hadia zi nangea ba ndra alawe sanguma''ö sangata''ufi Lowalangi ira; bua-bua si sökhi wangehaora.[8]', '["KorI 14:34; Mar 11:25; Yak 1:6","FetI 3:3–5","Tit 2:3 b.t.","KorI 14:34–35","Efes 5:22; Kol 3:18; FetII 3:1 b.t.","MozI 2:18 b.t.","KorII 11:3; MozI 3:6","Tit 2:4–5; KorI 7:25,26"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 11, 'Ya''ahono-hono ndra alawe, wamahaö ya''ia, ya''a''oi so wolo''önia li.[9]', '["KorI 14:34; Mar 11:25; Yak 1:6","FetI 3:3–5","Tit 2:3 b.t.","KorI 14:34–35","Efes 5:22; Kol 3:18; FetII 3:1 b.t.","MozI 2:18 b.t.","KorII 11:3; MozI 3:6","Tit 2:4–5; KorI 7:25,26"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 12, 'Lö utehe ba ndra alawe wamahaö niha bö''ö, ba he famatörö ira matua, yamuhonogö ia.[10]', '["KorI 14:34; Mar 11:25; Yak 1:6","FetI 3:3–5","Tit 2:3 b.t.","KorI 14:34–35","Efes 5:22; Kol 3:18; FetII 3:1 b.t.","MozI 2:18 b.t.","KorII 11:3; MozI 3:6","Tit 2:4–5; KorI 7:25,26"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 13, 'Oföna sa tefazökhi Gadamo, awena Khawa.[11]', '["KorI 14:34; Mar 11:25; Yak 1:6","FetI 3:3–5","Tit 2:3 b.t.","KorI 14:34–35","Efes 5:22; Kol 3:18; FetII 3:1 b.t.","MozI 2:18 b.t.","KorII 11:3; MozI 3:6","Tit 2:4–5; KorI 7:25,26"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 14, 'Ba tenga Adamo nifaelungu, ba ira alawe nifaelungu, isawö goroisa.[12]', '["KorI 14:34; Mar 11:25; Yak 1:6","FetI 3:3–5","Tit 2:3 b.t.","KorI 14:34–35","Efes 5:22; Kol 3:18; FetII 3:1 b.t.","MozI 2:18 b.t.","KorII 11:3; MozI 3:6","Tit 2:4–5; KorI 7:25,26"]', NULL),
  (3391784, 'NT', 'Timoteo I', 2, 15, 'Ba ni''orifi sa ia, ba wadono, na lö aefa khöra wamati ba fa''omasi ba fangohau-hau, awö wa''amoadu.[13]', '["KorI 14:34; Mar 11:25; Yak 1:6","FetI 3:3–5","Tit 2:3 b.t.","KorI 14:34–35","Efes 5:22; Kol 3:18; FetII 3:1 b.t.","MozI 2:18 b.t.","KorII 11:3; MozI 3:6","Tit 2:4–5; KorI 7:25,26"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 1, 'Si ndruhu daroma li andre: Na so zangalui halöŵö zatua niha Keriso andrö, ba halöŵö si sökhi i''alui.[1]', '["HalZin 20:28","Tit 1:6 b.t.; TimII 2:24","MozIII 10:9 b.t.","Kol 4:5"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 2, 'Ba satua andrö, ba böi mosinegu, böi samodombua donga, böi sambö era-era, ha satua-tua, si sökhi böwö, same''e-me''e gö dome, sangila mamahaö.[2]', '["HalZin 20:28","Tit 1:6 b.t.; TimII 2:24","MozIII 10:9 b.t.","Kol 4:5"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 3, 'Böi samadu-madu tuo, ba böi si fabago-bago, ha sebolo tödö, si lö fagua-gua, si lö omasi ana''a;[3]', '["HalZin 20:28","Tit 1:6 b.t.; TimII 2:24","MozIII 10:9 b.t.","Kol 4:5"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 4, 'sangila mangehao, wamatörö soroiyomonia, si so ono solo''ö linia, si no a''oi so fa''amoadu. — Na so zi lö mangila mamatörö soroiyomonia, ba he iwisa wondrorogö banua Lowalangi andrö? —', '["HalZin 20:28","Tit 1:6 b.t.; TimII 2:24","MozIII 10:9 b.t.","Kol 4:5"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 6, 'Böi si bohou mubayagö idanö, fa böi fayaŵa ia, ba fa lö göna ia huku andrö, khö Gafökha.', '["HalZin 20:28","Tit 1:6 b.t.; TimII 2:24","MozIII 10:9 b.t.","Kol 4:5"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 7, 'Ba lö tola göi lö sökhi duriania ba si so baero andrö, fa böi tetandraŵaisi ia, ba fa böi alau ia ba dandraŵa Gafökha.[4]', '["HalZin 20:28","Tit 1:6 b.t.; TimII 2:24","MozIII 10:9 b.t.","Kol 4:5"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 8, 'Ba si manö göi genoni andrö: si sökhi amuata, böi dua lela, böi samadu-madu tuo, böi sangalui ana''a si lö atulö,[5]', '["HalZin 6:3 b.t.","HalZin 24:16","Faigi 5:9; 2:9","Mat 25:21; 19:28; Luk 19:17–19"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 9, 'si lö mamöhöi si no tobini andrö, famati andrö, ba dödö si lö sinegu.[6]', '["HalZin 6:3 b.t.","HalZin 24:16","Faigi 5:9; 2:9","Mat 25:21; 19:28; Luk 19:17–19"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 10, 'Ba nitandraigö göi ira ua, ba awena tola möi ira enoni, na lö sinegu.', '["HalZin 6:3 b.t.","HalZin 24:16","Faigi 5:9; 2:9","Mat 25:21; 19:28; Luk 19:17–19"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 11, 'Ya si manö göi ndra alawe: si sökhi amuata, böi samöbögö si lö duhu, böi sambö era-era; si lö faröi, gofu hadia ia.[7]', '["HalZin 6:3 b.t.","HalZin 24:16","Faigi 5:9; 2:9","Mat 25:21; 19:28; Luk 19:17–19"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 12, 'Ba enoni andrö, ba si ha sambua donga, sangehaogö famatörö onora ba soroiyomora, fefu.', '["HalZin 6:3 b.t.","HalZin 24:16","Faigi 5:9; 2:9","Mat 25:21; 19:28; Luk 19:17–19"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 13, 'Lasöndra sa khöra naha si sökhi sangehaogö fangai halöŵöra andrö, ba fahöna dania khöra wa lö aiŵö, ba wamati andrö, ba khö Keriso Yesu, labe''e.[8]', '["HalZin 6:3 b.t.","HalZin 24:16","Faigi 5:9; 2:9","Mat 25:21; 19:28; Luk 19:17–19"]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 14, 'Da''ö nisuragu khöu, ba udöna-döna, alio usöndra we''amöi khöu; ba na ara ndra''o,', '["Efes 2:19 b.t.; Heb 3:6","Yoh 1:14; Kol 2:9; Rom 1:3–4; KorI 15:5–9; Efes 1:20 b.t."]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 15, 'ba ena''ö na ö''ila, he lawisa ba nomo Lowalangi andrö, ya''ia mbanua Lowalangi sauri andrö, ehomo zi duhu andrö ba dane-danenia.[9]', '["Efes 2:19 b.t.; Heb 3:6","Yoh 1:14; Kol 2:9; Rom 1:3–4; KorI 15:5–9; Efes 1:20 b.t."]', NULL),
  (3391787, 'NT', 'Timoteo I', 3, 16, 'Ba tenga faya, wa no ebua zi no tobini andrö, ba wolo''ö andrö khö Lowalangi: si no tefa''ele''ö ba nösi niha, nifa duhu''ö ba khö Geheha, si no mangoroma''ö ya''ia ba mala''ika, nituriagö ba niha baero, ba zi no faduhu dödö niha ba guli danö, da''ö ni''ohe yaŵa ba lakhömi.[10]', '["Efes 2:19 b.t.; Heb 3:6","Yoh 1:14; Kol 2:9; Rom 1:3–4; KorI 15:5–9; Efes 1:20 b.t."]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 1, 'Noa sa iŵa''ö sibai Eheha, so ba götö dania ösa zondröi famati andrö, solo''ö ba geheha samaelungu, ba solo''ö famahaö mbekhu,[1]', '["TimII 3:1 b.t.; FetII 3:3; YohI:2–18; TesII 2:9 b.t.","TimII 3:5","KorI 7:28; 36:38; Kol 2:16; 20:23","KorI 10:30–31"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 2, 'börö wamini tödö zolau faya andrö, si no falemba tandra ba dödöra,[2]', '["TimII 3:1 b.t.; FetII 3:3; YohI:2–18; TesII 2:9 b.t.","TimII 3:5","KorI 7:28; 36:38; Kol 2:16; 20:23","KorI 10:30–31"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 3, 'sanenaŵa fangowalu ba femanga gö, nifazökhi Lowalangi, ba wemanga ya''ia, na fao wangandrö saoha gölö, ba zamati andrö, si no aboto ba dödö si duhu.[3]', '["TimII 3:1 b.t.; FetII 3:3; YohI:2–18; TesII 2:9 b.t.","TimII 3:5","KorI 7:28; 36:38; Kol 2:16; 20:23","KorI 10:30–31"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 4, 'Si sökhi sa fefu nifazökhi Lowalangi, ba lö hadia ia nitimba, na fao wangandrö saoha gölö, ba wangoguna''ö ya''ia;[4]', '["TimII 3:1 b.t.; FetII 3:3; YohI:2–18; TesII 2:9 b.t.","TimII 3:5","KorI 7:28; 36:38; Kol 2:16; 20:23","KorI 10:30–31"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 5, 'ba daroma li Lowalangi ba ba wangandrö te''amoni''ö sa''ae ia.', '["TimII 3:1 b.t.; FetII 3:3; YohI:2–18; TesII 2:9 b.t.","TimII 3:5","KorI 7:28; 36:38; Kol 2:16; 20:23","KorI 10:30–31"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 6, 'Na öŵa''ö da''ö ba dalifusö, ba enoni Keriso ndra''ugö, si sökhi, ba fangabölöu daroma li ba wamati andrö ba famahaö si ndruhu, ni''o''ömö andrö.[5]', '["TimII 3:15","Faigi 1:4; Tit 1:10 b.t.","Faigi 6:6 b.t.; Sin 34:10; 37:4; Mat 6:33","Faigi 2:3–4"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 7, 'Ba böi tehe gamaedola si lö boto andrö, faya-faya andrö; ba famaha ndra''ugö ba wolo''ö khö Lowalangi.[6]', '["TimII 3:15","Faigi 1:4; Tit 1:10 b.t.","Faigi 6:6 b.t.; Sin 34:10; 37:4; Mat 6:33","Faigi 2:3–4"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 8, 'Lö''ö sa börö moguna wamamaha boto andrö; ba folo''ö khö Lowalangi andrö, ba moguna manö, gofu heza ia, ba no tefabu''u khönia wa''auri iya''e ba fa''auri dania.[7]', '["TimII 3:15","Faigi 1:4; Tit 1:10 b.t.","Faigi 6:6 b.t.; Sin 34:10; 37:4; Mat 6:33","Faigi 2:3–4"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 9, 'Si ndruhu daroma li andrö, ba no si nangea tafonaha manö.', '["TimII 3:15","Faigi 1:4; Tit 1:10 b.t.","Faigi 6:6 b.t.; Sin 34:10; 37:4; Mat 6:33","Faigi 2:3–4"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 10, 'Ba da''ö sa ma''eregeisi dödöma, ba fasöndraga, me no madöna-döna khö Lowalangi sauri andrö, sangorifi niha fefu, ba oföna zamati andrö.[8]', '["TimII 3:15","Faigi 1:4; Tit 1:10 b.t.","Faigi 6:6 b.t.; Sin 34:10; 37:4; Mat 6:33","Faigi 2:3–4"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 11, 'Da''ö ŵa''ö khöra, ba ba da''ö fahaö ira.', '["TimII 3:15","Faigi 1:4; Tit 1:10 b.t.","Faigi 6:6 b.t.; Sin 34:10; 37:4; Mat 6:33","Faigi 2:3–4"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 12, 'Böi yamu''ositengagö ndra''ugö niha, me ono matua na ndra''ugö; ya duma-duma ndra''ugö ba zamati, ba huhuo, ba ba mbua-bua, ba ba wa''omasi, ba ba wamati, ba ba wa''ohau-hau.[9]', '["Tit 2:7–15; KorI 16:11","TimII 1:6","HalZin 20:28"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 13, 'Irege so ndra''o, ba böi bato wombaso sura, ba böi bato wamarou tödö ba famahaö.', '["Tit 2:7–15; KorI 16:11","TimII 1:6","HalZin 20:28"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 14, 'Böi ositengagö game''ela andrö, si so ba dödöu, nibe''e khöu, ba wama''ele''ö andrö, me latufa högöu tanga satua andrö.[10]', '["Tit 2:7–15; KorI 16:11","TimII 1:6","HalZin 20:28"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 15, 'Da''ö törö-törö tödöu, da''ö fatou-tou, ena''ö oroma wa''atedoumö, ba khöra fefu.', '["Tit 2:7–15; KorI 16:11","TimII 1:6","HalZin 20:28"]', NULL),
  (3391788, 'NT', 'Timoteo I', 4, 16, 'Faigi-faigi he wisa ndra''ugö, ba he öwisa wamahaö andrö; böi böhöli da''ö. Na ö''o''ö da''ö, ba ö''orifi ndra''ugö, awö zamondrongo andrö khöu.[11]', '["Tit 2:7–15; KorI 16:11","TimII 1:6","HalZin 20:28"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 1, 'Niha satua, ba böi feta''u, ba farou dödönia, hulö na amau, ba ono matua, ba hulö na talifusöu;[1]', '["MozIII 19:32","Mark 7:10 b.t.","Luk 2:37"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 2, 'ira alawe satua, ba hulö na inau, ba ono alawe, ba hulö na talifusöu alawe, ni''onangegö sibai.', '["MozIII 19:32","Mark 7:10 b.t.","Luk 2:37"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 3, 'Lakha mbanua andrö, ba fosumange, na si ndruhu lakha mbanua.', '["MozIII 19:32","Mark 7:10 b.t.","Luk 2:37"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 4, 'Ba na so lakha mbanua si so ono, ba ma ma''uwu, ba ndramufamaha ira ua, wolo''ö huku Lowalangi, ba wondrorogö soroiyomora, ba ba wamasulöni khö ndra inara nitemara; da''ö sa zomasi Lowalangi.[2]', '["MozIII 19:32","Mark 7:10 b.t.","Luk 2:37"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 5, 'Ba si ndruhu lakha, si lö olembata, ba no manötöna khö Lowalangi, ba lö iböhöi wangandrö ba fangalulu bongi ma''ökhö.[3]', '["MozIII 19:32","Mark 7:10 b.t.","Luk 2:37"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 6, 'Ba samorege femanga-manga, ba ma hadia ia, ba no mate auri.[4]', '["Fam 3:1"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 7, 'Ba da''ö goroisa, ni''ombakha''öu, ena''ö lö sinegu khöra.', '["Fam 3:1"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 8, 'Ba na so zangositengagö sahatö khönia, ba mendrua manö na soroiyomonia, ba no i''osilö''ögö wamati, ba abölö walösökhinia, moroi ba walösökhi zi lö mamati.[5]', '["Faigi 3:5"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 9, 'Na latanö ba zura döi lakha mbanua, ba böi ambö önö ngafulu fakhe wa''atua, si ha sambua donga föna, ba si sökhi turia, ba mbua-bua,[6]', '["Rom 16:1","Heb 13:2; Yoh 13:14"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 10, 'na no i''e''ebua ndraono, na no ibe''e-be''e gö dome, na no isasai gahe ni''amoni''ö andrö, na no itolo-tolo zi tosasa, na no i''alui mbua-bua si sökhi, fefu, hadia ia ngawalö.[7]', '["Rom 16:1","Heb 13:2; Yoh 13:14"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 11, 'Na lakha mbanua sambö fa''atua, ba böi tehe; na no mohokha ira sa, si fa''udu khö Keriso, ba edöna ira möi nihalö,', '["Amaed 10:19; TesII 3:11"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 12, 'ba lalu''i dahi andrö, wa no faröi ira, ba nifabu''u andrö, si föföna.', '["Amaed 10:19; TesII 3:11"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 13, 'Ba faböbö ba da''ö, wa lafamaha ira wangero-ngero lö mohalöŵö, ba tenga ha fa lö mohalöŵö, wa''oya göi mbewe, lahalö khöra zi tenga khöra, lalau huo-huo si lö göna.[8]', '["Amaed 10:19; TesII 3:11"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 14, 'Andrö omasido, na möi nihalö lakha mbanua sambö fa''atua, na mo''ono, na tobali samatörö soroiyomora ira, ba na lö lafobörö wanandraŵaisi ba zi fa''udu andrö;[9]', '["KorI 7:9; 39:40"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 15, 'noa sa aheta ösa, la''o''ö Zatana.', '["KorI 7:9; 39:40"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 16, 'Na so zamati, ira alawe, si so lakha mbanua, ba yamurorogö, ba böi möi noro dödö mbanua, fa la''ila latolo zi ndruhu lakha mbanua.', '[]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 17, 'Satua andrö, sangehaogö fangai halöŵöra, ba nifodua winaeta zumangera, ba mendrua manö ba zi so halöŵö fahuhuosa ba famahaö.[10]', '["TesI 5:12–13","MozV 25:4; Mat 10:10"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 18, 'Noa sa so ba zura: "Böi fosare''a mbawa göröbao samöbörö fakhe" ba: "No sinangea labe''e luo ba zohalöŵö."[11]', '["TesI 5:12–13","MozV 25:4; Mat 10:10"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 19, 'Böi tema na la''adugö zatua, na tenga darua, ba ma datölu zi so ba mbörö.[12]', '["MozV 19:15","Mat 18:17; Gal 2:14","Faigi 6:13-14"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 21, 'Uŵa''ö sibai khöu, föna Lowalangi, ba föna Keriso Yesu, ba föna mala''ika nitutuyu andrö, ena''ö lö olifu''ö da''ö, ena''ö lö aösö ö''etu''ö huku, ba ena''ö lö ebua dödöu zambuana, wolau hadia ia, fefu.[14]', '["MozV 19:15","Mat 18:17; Gal 2:14","Faigi 6:13-14"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 22, 'Böi aösö tufa tanga högö niha, gofu ha niha ia, ba böi fabaya ndra''ugö ba horö niha bö''ö; böi tobaya khöu hadia ia zi lö sökhi.[15]', '["Faigi 3:10; KorII 6:14"]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 23, 'Böi sa''ae ha sambalö idanö öbadu, öfake sa nagu ma''ifu, ba dalumö andrö, ba me asese mofökhö''ö.', '[]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 24, 'So ösa niha soroma horö, ihulö huku, ba so göi, ba moroi furi.[16]', '["Gal 5:19 b.t.","Gal 5:22 b.t."]', NULL),
  (3391789, 'NT', 'Timoteo I', 5, 25, 'Si manö göi mbua-bua si sökhi andrö, oroma, ba ba zi tenga si manö, ba tebai sa ato tobini dania.[17]', '["Gal 5:19 b.t.","Gal 5:22 b.t."]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 1, 'Ha wa''ato zawuyu andrö, solu''i kalo mbagi andrö, ba ndramu''oigö dödöra wamosumange sokhö ya''ira, fa böi tetandraŵaisi döi Lowalangi, awö wamahaö andrö.[1]', '["Efes 6:5; b.t.; Tit 2:9–10","Filem 16"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 2, 'Ba si so sokhö samati, ba böi ndramu''ositengagö, me no talifusö; mendrua manö sa lahaogö wangai halöŵöra, me no samati ba ni''omasi''ö zoguna halöŵö si sökhi andrö. Ba da''ö fahaö ira, ba da''ö farou dödöra.[2]', '["Efes 6:5; b.t.; Tit 2:9–10","Filem 16"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 3, 'Na so zi tenga si manö famahaö, si lö molo''ö si ndruhu andrö, niŵa''ö Zo''aya ya''ita, Yesu Keriso, ba famahaö si faudu ba wolo''ö andrö, khö Lowalangi,[3]', '["Gal 1:6 b.t.; TimII 1:13","Faigi 1:4–7; TimII 2:14","TimII 3:5; 7:8"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 4, 'ba si fayaŵa da''ö, lö saboto ba dödönia hadia ia, no mofökhö ia, ni''alu-alui dödö andrö ba fagua-guasa wökhönia, ba ba da''ö tumbu dania wa''afökhö dödö, ba fasosota, ba famaudu dödö, si lö sökhi,[4]', '["Gal 1:6 b.t.; TimII 1:13","Faigi 1:4–7; TimII 2:14","TimII 3:5; 7:8"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 5, 'ba fagua-guasa, si lö aetu, ba niha si no tekiko era-era, si no taya si duhu, sanguma''ö tödöra fangalui ana''a wolo''ö andrö, khö Lowalangi.[5]', '["Gal 1:6 b.t.; TimII 1:13","Faigi 1:4–7; TimII 2:14","TimII 3:5; 7:8"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 6, 'Ba si ndruhu, fangalui sebua wolo''ö andrö, na fao wa''ahono dödö ba zi no so,[6]', '["Faigi 4:8; Sin 37:16; Heb 13:5","Yob 1:21; Sin 49:18","Amaed 30:8 b.t."]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 7, 'Lö''ö sa hadia ia ni''oheda ba guli danö andre, me awena so ita, me tebai göi ta''ohe hadia ia, na taröi guli danö.[7]', '["Faigi 4:8; Sin 37:16; Heb 13:5","Yob 1:21; Sin 49:18","Amaed 30:8 b.t."]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 8, 'Ba na so khöda mbalazo, awö nukha, ba noa khöda da''ö.[8]', '["Faigi 4:8; Sin 37:16; Heb 13:5","Yob 1:21; Sin 49:18","Amaed 30:8 b.t."]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 9, 'Ba sedöna mangebua ana''a, ba göna fanandraigö, ba tandraŵa, ba oya wangisö faya-faya ba fangisö fama''ala, sangahanigö niha ba wa''atekiko, ba ba wa''amate.[9]', '["Amaed 23:4 b.t.; 28:20; Mat 13:22","Luk 12:15 b.t."]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 10, 'Noa sa baya ngawalö hadia ia zi lö sökhi fefu wa''omasi gana''a andrö, ba no elungu ösa, no laröi wamati, wangalui da''ö, ba no oya nifoböröra khöra fa''afökhö.[10]', '["Amaed 23:4 b.t.; 28:20; Mat 13:22","Luk 12:15 b.t."]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 11, 'Ba ya''ugö, niha Lowalangi, ba timba zi mane da''ö; ba alui wa''atulö dödö, ba folo''ö andrö, khö Lowalangi, ba famati, ba fa''omasi, ba fanaha tödö, ba fa''ebolo dödö.[11]', '["TimII 2:22","Faigi 1:18; TimII 4:7 b.t.; Fil 3:12 b.t.","Faigi 5:21; Mat 27:11; Yoh 18:37","TesI 3:13","Fam 19:16","Yoh 5:26; MozII 33:20"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 12, 'Lau fasöndra, fasöndrata si sökhi andrö, fasöndrata wamati; ra''u wa''auri si lö aetu andrö, ba nikaoni ya''ugö, ba ba nilaumö famaduhu''ö si sökhi andrö, ba zi no ato ba mbörö.[12]', '["TimII 2:22","Faigi 1:18; TimII 4:7 b.t.; Fil 3:12 b.t.","Faigi 5:21; Mat 27:11; Yoh 18:37","TesI 3:13","Fam 19:16","Yoh 5:26; MozII 33:20"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 13, 'Uŵa''ö khöu föna Lowalangi, sangorifi fefu hadia ia, ba föna Keriso Yesu, si no molau famaduhu''ö si sökhi andrö, föna Wondrio Filato andrö:[13]', '["TimII 2:22","Faigi 1:18; TimII 4:7 b.t.; Fil 3:12 b.t.","Faigi 5:21; Mat 27:11; Yoh 18:37","TesI 3:13","Fam 19:16","Yoh 5:26; MozII 33:20"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 14, 'O''ö goroisa andrö, böi göna hadia ia, böi falukha zinegu, irugi wa''ato''ele Zo''aya ya''ita andrö, Yesu Keriso,[14]', '["TimII 2:22","Faigi 1:18; TimII 4:7 b.t.; Fil 3:12 b.t.","Faigi 5:21; Mat 27:11; Yoh 18:37","TesI 3:13","Fam 19:16","Yoh 5:26; MozII 33:20"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 15, 'ni''oroma''ö Zamatörö andrö dania, na inötönia, Samatörö andrö, sohahau tödö, si ha samösa, razo razo andrö, ba So''aya sokhö,[15]', '["TimII 2:22","Faigi 1:18; TimII 4:7 b.t.; Fil 3:12 b.t.","Faigi 5:21; Mat 27:11; Yoh 18:37","TesI 3:13","Fam 19:16","Yoh 5:26; MozII 33:20"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 16, 'si so fa lö mate, si ha khönia, si so ba haga andrö, ba zi tebai möi niha, si lö irai i''ila niha, ba si tebai göi i''ila. Ya khönia zumange ba fa''abölö si lö aetu. Yaduhu.[16]', '["TimII 2:22","Faigi 1:18; TimII 4:7 b.t.; Fil 3:12 b.t.","Faigi 5:21; Mat 27:11; Yoh 18:37","TesI 3:13","Fam 19:16","Yoh 5:26; MozII 33:20"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 17, 'Ba zi so ana''a, ba guli danö andre, ŵa''ö, böi fayaŵa ira, böi ndramudöna-döna ba gana''a, si lö aro andrö, khö Lowalangi ndramudöna-döna, si lö mangambösi khöda, wame''e hadia ia, ba wangoguna''ö ya''ia;[17]', '["Yob 31:24; Mat 10:24; Luk 12:20","Heb 13:16; Yoh 3:21","Mat 6:20; Luk 16:9"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 18, 'ndramutolo nawöra, yafahöna khöra mbua-bua si sökhi, böi atali ira, ya''ahakhö dödöra nawöra;[18]', '["Yob 31:24; Mat 10:24; Luk 12:20","Heb 13:16; Yoh 3:21","Mat 6:20; Luk 16:9"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 19, 'ba wangöhöna khöra girö-girö dane-dane si sökhi, ba götö dania, ena''ö lakhamö zi ndruhu fa''auri andrö.[19]', '["Yob 31:24; Mat 10:24; Luk 12:20","Heb 13:16; Yoh 3:21","Mat 6:20; Luk 16:9"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 20, 'He Timoteo! irö-irö''ö nibe''e khöu andrö, böi babaya huo-huo andrö si lö boto, si lö guna andrö, ba amadöniŵa wa''atua-tua faya andrö;[20]', '["TimII 1:14; 2:14–16","Faigi 1:6–19; TimII 4:22"]', NULL),
  (3391790, 'NT', 'Timoteo I', 6, 21, 'so ösa zi no molo''ö da''ö, ba no elungu, no laröi wamati. — Yafalukha''ö wa''ebua dödö![21]', '["TimII 1:14; 2:14–16","Faigi 1:6–19; TimII 4:22"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 1, 'Faulo zanura da''e, sinenge Keriso Yesu andrö, moroi ba nilau dödö Lowalangi, dali wamabu''u fa''auri andrö, ba khö Keriso Yesu,[1]', '["TimI 1:1; YohI 2:25","TimI 1:2"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 2, 'khö Dimoteo andrö, ono omasiö khönia. Yafalukha''ö wa''ebua dödö, ba fa''ahakhö dödö, ba fa''ohahau dödö, khö Lowalangi Ama, ba khö Keriso Yesu, So''aya ya''ita![2]', '["TimI 1:1; YohI 2:25","TimI 1:2"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 3, 'U''andrö saoha gölö khö Lowalangi, nifosumangegu, i''otarai ndra tuagu, lö sinegu dödögu khögu, lö aetu göi itörö ligu ndra''ugö, na mangandrö ndra''o, bongi ma''ökhö,[3]', '["HalZin 23:1","Faigi 4:9–21","HalZin 16:1"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 4, 'oi so wehulu dödögu, ena''ö falukhado khöu, itörö tödögu daŵa höröu andrö, ena''ö fahöna khögu wa''omuso dödö.[4]', '["HalZin 23:1","Faigi 4:9–21","HalZin 16:1"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 5, 'Me no tefasugi ba dödögu wamatimö andrö, si lö famini tödö, si no oföna monahia ba dödö gaweu Loise ba ba dödö ninau, Oinike, ba udöna-döna, ba dödöu göi.[5]', '["HalZin 23:1","Faigi 4:9–21","HalZin 16:1"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 6, 'Da''ö mbörö, wa ufasugi ba dödöu, ena''ö öfado''ö game''ela Lowalangi andrö, si so ba dödöu, moroi ba wanufa högöu tangagu.[6]', '["TimI 4:14","Rom 8:15"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 7, 'Tenga sa Eheha sada''u-da''u nibe''e Lowalangi khöda, no Eheha sabölö, Eheha ba wa''omasi, Eheha ba wangonangegö nibe''enia khöda.[7]', '["TimI 4:14","Rom 8:15"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 8, 'Ba böi aila ndra''ugö, wamaduhu''ö turia Zo''aya ya''ita, ba böi aila''ö ba khögu andre, nitaha andrö khönia, yafao ndra''ugö wanaha famakao andrö, ba duria somuso dödö andrö, dali wa''abölö Lowalangi andrö,[8]', '["Faigi 2:3; 4:5","Tit 3:5; Efes 1:4–11","Heb 2:14; KorI 15:55–57","TimI 2:7"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 9, 'si no mangorifi ya''ita, si no mogaoni ya''ita, fogaoni ni''amoni''ö; tenga dali mbua-buada, dali nihonogöi dödönia, ba fa''ebua dödö andrö, si no falukha ita, ba khö Keriso Yesu, föna nga''ötö danö andrö,[9]', '["Faigi 2:3; 4:5","Tit 3:5; Efes 1:4–11","Heb 2:14; KorI 15:55–57","TimI 2:7"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 10, 'nifa''ele''ö iada''e, ba wa''ato''ele zangorifi ya''ita andrö, Keriso Yesu, si no mamakiko fa''amate andrö, ba si no mangasogö fa''auri ba fa lö tekiko, moroi ba duria somuso dödö andrö,[10]', '["Faigi 2:3; 4:5","Tit 3:5; Efes 1:4–11","Heb 2:14; KorI 15:55–57","TimI 2:7"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 11, 'ba nifataro ya''o sangombakha ba sinenge ba samahaö.[11]', '["Faigi 2:3; 4:5","Tit 3:5; Efes 1:4–11","Heb 2:14; KorI 15:55–57","TimI 2:7"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 12, 'Da''ö göi mbörö, wa utaögö zi mane da''ö, ba lö''ö sa aila ndra''o ba khönia; noa sa u''ila ha khö mamati ndra''o, ba no faduhu dödögu, abölö ia, tola i''irö''ö khögu nibe''e ba dangagu andrö, irugi luo safuria andrö dania.[12]', '["Faigi 2:9; Kol 1:5","Rom 6:17; TimI 6:3; Tit 2:1","TimI 6:20"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 13, 'O''ö dulada wamahaö si ndruhu andrö, nirongou khögu, ba wamati, ba ba wa''omasi ba khö Keriso Yesu.[13]', '["Faigi 2:9; Kol 1:5","Rom 6:17; TimI 6:3; Tit 2:1","TimI 6:20"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 14, 'Irö-irö''ö nibe''e khöu andrö, si sökhi andrö, yamutolo''ö Eheha ni''amoni''ö andrö, sonahia ba dödöda.[14]', '["Faigi 2:9; Kol 1:5","Rom 6:17; TimI 6:3; Tit 2:1","TimI 6:20"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 15, 'Noa sa örongo, wa no ahori la''erogö ndra''o si so ba Azia andrö, ira Figelo ba Hemogene.[15]', '["Faigi 4:10–16"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 16, 'Yamuhakhösi tödö So''aya zoroiyomo Gonesiforo andrö, fefu, me no asese i''okafui dödögu, ba lö saila ia ba rategu andre.[16]', '["Faigi 4:19","Mat 5:7"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391793, 'NT', 'Timoteo II', 1, 17, 'Me möi ia ba Roma, ba no iforege wangalui ya''o, ba no isöndra ndra''o.', '["Faigi 4:19","Mat 5:7"]', NULL),
  (3391793, 'NT', 'Timoteo II', 1, 18, 'Yamutolo ia So''aya, ena''ö falukha ia wa''ahakhö dödö khö Zo''aya, na luo safuria andrö dania; ba ha wa''ebua wanolonia ba Nefeso, ba no ya''ugö zabölö mangila.[17]', '["Faigi 4:19","Mat 5:7"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 1, 'Ba ya''ugö onogu, ba ya''abe''e ndra''ugö, ba wa''ebua dödö andrö, ba khö Keriso Yesu.[1]', '["Efes 6:10","Faigi 1:13"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 2, 'Ba hadia nirongou khögu, ba zi no ato ba mbörö, da''ö fa''ema ba niha si lö faröi, si tola mamahaö dania niha bö''ö göi.[2]', '["Efes 6:10","Faigi 1:13"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 3, 'Yafao ndra''ugö wanaha famakao, amaedola zi möi manuwö, awö Keriso Yesu, si sökhi.[3]', '["Faigi 1:8","KorI 9:25 b.t.","KorI 9:10"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 4, 'Fefu, ha niha zi möi manuwö, ba lö ihalö rörönia wangalui balazo, afunia i''omasi''ö ia solohe ya''ia andrö.[4]', '["Faigi 1:8","KorI 9:25 b.t.","KorI 9:10"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 5, 'Ba he no si fasöndra niha, ba lö''ö sa lafotakula ia, na si lö göna wasöndratania andrö.', '["Faigi 1:8","KorI 9:25 b.t.","KorI 9:10"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 6, 'Da''ö zi föföna mangoguna''ö bua nowi, sonowi andrö, sohalöŵö.[5]', '["Faigi 1:8","KorI 9:25 b.t.","KorI 9:10"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 7, 'Tanö ba dödöu hadia niŵa''ögu; ibotokhi sa dania ba dödöu So''aya, fefu hadia ia.[6]', '["Amaed 2:6","Rom 1:3; KorI 15:4–20","Faigi 1:8–12; HalZin 28:30–31","Kol 1:24"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 8, 'Törö-törö tödöu Yesu Keriso, nisusugi moroi ba ngai zi mate, ma''uwu Dawido andrö, dali duria somuso dödö andrö khögu;[7]', '["Amaed 2:6","Rom 1:3; KorI 15:4–20","Faigi 1:8–12; HalZin 28:30–31","Kol 1:24"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 9, 'da''ö mbörö, wa utaha wamakao, irege rate andrö, hulö zamarukhu; ba lö''ö sa mufesu daroma li Lowalangi andrö.[8]', '["Amaed 2:6","Rom 1:3; KorI 15:4–20","Faigi 1:8–12; HalZin 28:30–31","Kol 1:24"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 10, 'Andrö utaha fefu, hadia ia, börö nitutuyu andrö, ena''ö lakhamö göi wangorifi andrö, ba khö Keriso Yesu, awö lakhömi andrö, si lö aetu.[9]', '["Amaed 2:6","Rom 1:3; KorI 15:4–20","Faigi 1:8–12; HalZin 28:30–31","Kol 1:24"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 11, 'Si ndruhu daroma li andrö: na no fao ita ba wa''amate, ba fao göi ita ba wa''auri;[10]', '["Rom 6:5–8","Rom 8:17; Mat 10:33","Rom 3:3"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 12, 'na tataha wamakao, ba awö göi ita dania, ba wa''asalaŵa; na ya''ita mangosilö''ögö, ba ya''ia göi mangosilö''ögö ya''ita dania;[11]', '["Rom 6:5–8","Rom 8:17; Mat 10:33","Rom 3:3"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 13, 'na faröi ita, ba lö''ö sa faröi ia; tebai sa i''osilö''ögö ia.[12]', '["Rom 6:5–8","Rom 8:17; Mat 10:33","Rom 3:3"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 14, 'Da''ö fasugi ba dödöra; öŵa''ö sibai khöra, föna Lowalangi, fa böi fagua-gua ira, si lö guna, si ha sambalö famakuyu samondrongo.[13]', '["TimI 6:4–5","TimI 4:6"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 15, 'Forege wangalui, ena''ö si nangea khö Lowalangi ndra''ugö, sohalöŵö si lö aiŵö, sangehaogö fangoguna''ö taroma li si duhu andrö.[14]', '["TimI 6:4–5","TimI 4:6"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 16, 'Timba wamakhai mbewe andrö, si lö boto; tedou-dou manö sa khöra, wa lö la''o''ö khö Lowalangi[15]', '["TimI 6:20"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 17, 'ba manana-nana dania lira andrö, hulö mbou auri. Ya''ia ndra Himenaio Fileto,[16]', '["Faigi 3:13; TimI 1:20","TimI 6:21; KorI 15:19","Yoh 19:14–27; Mat 7:22; Fam 2:13"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 18, 'si no elungu, si no mondröi si duhu, wanguma''ö no aefa wemaoso zi mate andrö, ba so ösa nifawukara famati.[17]', '["Faigi 3:13; TimI 1:20","TimI 6:21; KorI 15:19","Yoh 19:14–27; Mat 7:22; Fam 2:13"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 19, 'Ba lö''ö sa atö tebulö dane-dane saro andrö khö Lowalangi, ba da''ö dandronia: "No aboto ba dödö Zo''aya dana khönia andrö" ba: "ndramuröi zi lö atulö dozi sanötöi töi Zo''aya andrö." [18]', '["Faigi 3:13; TimI 1:20","TimI 6:21; KorI 15:19","Yoh 19:14–27; Mat 7:22; Fam 2:13"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 20, 'Ba ba nomo sebua ba tenga ha gama-gama balaki ba gama-gama firö, so sa göi gama-gama eu ba gama-gama tanö, ba nifake ba zoadu ösa, ba ba zi lö moadu ösa.[19]', '["Rom 9:21","KorII 6:17 b.t."]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 21, 'Ba na so zi no mangeheta ya''ia ba zi manö, ba fakake ba zoadu ia dania, ni''amoni''ö, ba soguna ba zokhö omo, nihaogö, ba ngawalö mbua-bua si sökhi, fefu.[20]', '["Rom 9:21","KorII 6:17 b.t."]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 22, 'Erogö wangisö nono matua andrö, ba gohi wa''atulö dödö ba famati ba fa''omasi ba fefao dödö ba zangaröfi li So''aya andrö, soroi ba dödö si no ohau-hau.[21]', '["TimI 6:11"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 23, 'Ba amadöniŵa faya andrö, si lö göna, ba timba, me no ö''ila, ha fasosota zi tumbu ba da''ö.[22]', '["Faigi 2:14–16","Tit 1:7–9","TesI 5:14","Efes 5:14"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 24, 'Ba enoni Zo''aya, ba böi yafasoso, yamuhaogö linia, ba niha fefu, ya''enahöi wamahaönia, ya''ebolo dödönia ba niha si lö sökhi,[23]', '["Faigi 2:14–16","Tit 1:7–9","TesI 5:14","Efes 5:14"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 25, 'yamuhaogö-haogö wanegu samadaö andrö, ma atö ibe''e khöra Lowalangi wamalalini era-era, fa aboto ba dödöra zi duhu.[24]', '["Faigi 2:14–16","Tit 1:7–9","TesI 5:14","Efes 5:14"]', NULL),
  (3391794, 'NT', 'Timoteo II', 2, 26, 'fa tokea ira, ba wangefa''ö ya''ira ba dandraŵa Gafökha andrö, si no mama''ala ya''ira, ba wolo''ö nilau dödönia andrö.[25]', '["Faigi 2:14–16","Tit 1:7–9","TesI 5:14","Efes 5:14"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 1, 'Ba böi zi lö aboto ba dödöu: so dania mbaŵa si lö sökhi, ba götö safuria andrö.[1]', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 2, 'Amuata niha ba da''ö, ba ha tana khöra la''alui, somasi ana''a ira, ba sanuno ya''ira, ba si fayaŵa, ba sanandraŵa, ba si lö mamondrongo li ndra amara, ba si tebai mangandrö saoha gölö, ba sango''aya Lowalangi,[2]', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 3, 'ba si lö mangomasi''ö awöra, ba si faröi, ba samöbögö si lö duhu, ba solau-lau manö hadia ia, ba si tebai ahono, ba si lö omasi si sökhi,', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 4, 'ba si manga mböli, ba si lö tödö, ba sebua hokha, ba somasi isö-isö dödöra, moroi ba wa''omasira Lowalangi;[3]', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 5, 'hulö solo''ö khö Lowalangi ira, wamaigida, ba no sangosilö''ögö fa''abölö wolo''ö andrö. Ba ya''ugö erogö niha si manö.[4]', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 6, 'Oi ya''ira sa zanöröi omo, ba wondrönisi ira alawe, si no fahöna horö, solo''ö manö fangisö dödöra, ha wa''oya ngawalö,[5]', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 7, 'si lö mamalö-malö wamahaö ya''ira, ba si tebai mogamö fa''aboto ba dödöra zi duhu.', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 8, 'Ba hulö si mane famadaö ndra Yane Yambere andrö khö Moze, si manö göi wamadaö da''ö no mege si duhu. Niha si no fakuyu tödö, si lö aro famati andrö.[6]', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 9, 'Ba lö''ö sa atö ara wolaura andrö, oroma sa dania ba niha fefu, wa si lö tödö ira, si mane ba khöra andrö föna göi.[7]', '["TimI 4:1 b.t.","Rom 1:29 b.t.","Fil 3:19","Tit 1:16; Mat 7:15","FetII 2:14","MozII 7:11–22; HalZin 13:8–10; TimI 6:5","MozII 7:12; 8:18; 9:11"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 10, 'Ba ya''ugö, ba no ö''o''ö khögu, ba wamahaö andrö, ba ba gamuata, ba ba nilau dödö, ba ba wamati, ba ba wa''ebolo dödö andrö, ba ba wa''omasi, ba ba wanaha tödö,', '["KorII 1:8–10; HalZin 13:50; 14:5–19","FetI 4:12 b.t.; Yoh 15:18 b.t."]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 11, 'ba wolohi andrö, ba ba wamakao andrö, si no göna ndra''o, ba Gandriokhia ba ba Nikonia ba ba Lisitera; no utaögö wolohi si manö, ba no i''efa''ö ndra''o So''aya, ba da''ö fefu.[8]', '["KorII 1:8–10; HalZin 13:50; 14:5–19","FetI 4:12 b.t.; Yoh 15:18 b.t."]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 12, 'Ba dozi sedöna molo''ö li Lowalangi, ba khö Keriso Yesu, ba göna folohi dania.[9]', '["KorII 1:8–10; HalZin 13:50; 14:5–19","FetI 4:12 b.t.; Yoh 15:18 b.t."]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 13, 'Ba ba niha si lö sökhi, samowöhö niha bö''ö, ba tedou-dou manö walösökhi, lafaelungu niha bö''ö, ba nifaelungu göi ira.', '["KorII 1:8–10; HalZin 13:50; 14:5–19","FetI 4:12 b.t.; Yoh 15:18 b.t."]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 14, 'Ba ya''ugö andrö, ba böi böhöli zi no örongo, awö zi no faduhu dödöu; me no ö''ila, ha khö örongo ia,[10]', '["Faigi 1:12–13","Faigi 1:5; Yoh 5:39","FetII 1:19–21"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 15, 'awö wa no ö''ila zura ni''amoni''ö andrö, i''otarai iraono ndra''ugö, sangila mangatua-tua''ö ya''ugö, ba wangalui fangorifi ba mbanua furi andrö, soroi ba wamati andrö, khö Keriso Yesu.[11]', '["Faigi 1:12–13","Faigi 1:5; Yoh 5:39","FetII 1:19–21"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 16, 'Fefu nösi zura andrö, ba Eheha Lowalangi zame''e ba dödö niha, ba moguna ia, ba wamahaö, ba ba wangotu''ö ba ba wanga''azökhi, ba ba wamamaha ba wa''atulö dödö,[12]', '["Faigi 1:12–13","Faigi 1:5; Yoh 5:39","FetII 1:19–21"]', NULL),
  (3391795, 'NT', 'Timoteo II', 3, 17, 'ena''ö mo''ahonoa genoni Lowalangi andrö, si no to''ölö ba ngawalö mbua-bua si sökhi andrö fefu.', '["Faigi 1:12–13","Faigi 1:5; Yoh 5:39","FetII 1:19–21"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 1, 'Uŵa''ö sibai khöu, föna Lowalangi, ba föna Keriso Yesu, sanguhuku dania niha sauri, awö zi no mate, ba wa''ato''elenia, ba ba mbanuania andrö:[1]', '["TimI 6:13; HalZin 10:42","TimI 4:13; 5:20","Yer 5:31; Mikh 2:11","Tit 1:14"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 2, 'Ombakha''ö daroma li, böi bulö''ögö, he baŵa, ba he tenga baŵa, otu''ö ira, farou dödöra, ba feta''u ira, ba ya''a''oi so wa''ebolo dödöu, awö wamahaö.[2]', '["TimI 6:13; HalZin 10:42","TimI 4:13; 5:20","Yer 5:31; Mikh 2:11","Tit 1:14"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 3, 'Irugi sa dania baŵa, si tebai lataha wamahaö si ndruhu andrö, ba lahöna dania khöra zamahaö somasi ira, si maoso mbörö dalingara,[3]', '["TimI 6:13; HalZin 10:42","TimI 4:13; 5:20","Yer 5:31; Mikh 2:11","Tit 1:14"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 4, 'ba la''erogö zi duhu, lö lafondrondrongo, ba la''otahögö waya-faya andrö.[4]', '["TimI 6:13; HalZin 10:42","TimI 4:13; 5:20","Yer 5:31; Mikh 2:11","Tit 1:14"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 5, 'Ba ya''ugö andrö, ba böi fawuka dödöu, gofu hadia ia ngawalö, taha wamakao, halö halöŵöu, halöŵö zangombakha turia somuso dödö andrö; fo''ahonoa nibaya-bayau andrö,[5]', '["Faigi 2:3 Kol 4:17"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 6, 'Ya''odo sa, ba nibe''e sumange sa''ae, ba lö ara tö, ba irugi baŵa wangefagu andrö.[6]', '["Fil 2:17","TimI 6:12; HalZin 20:24","KorI 9:25; Yak 1:12; Fam 2:10"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 7, 'Fasöndrata si sökhi andrö, ba no ulau, ba töröŵa andrö, ba no u''o''ozui, lö niböhöligu famati andrö.[7]', '["Fil 2:17","TimI 6:12; HalZin 20:24","KorI 9:25; Yak 1:12; Fam 2:10"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 8, 'Ba iada''e sa''ae, ba no muföfö''ö khögu dakula ba wa''atulö dödö andrö, nibe''e Zo''aya andrö, sangatulö''ö fanguhuku, khögu dania, na luo safuria andrö, ba tenga ha khögu, idozigö göi zangomasi''ö fa''ato''elenia andrö. [8]', '["Fil 2:17","TimI 6:12; HalZin 20:24","KorI 9:25; Yak 1:12; Fam 2:10"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 9, 'Ta''i-ta''i, ena''ö alio möi''ö khögu.', '["Kol 4:14","Kol 4:10","Kol 4:7"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 10, 'Noa sa iröido Dema andrö, me no omasi ia götö da''e, ba no möi ia ba Desalonika; Kereke andrö, ba no möi ba Galatia, ba Tito, ba no isaŵa Dalamatia;[9]', '["Kol 4:14","Kol 4:10","Kol 4:7"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 11, 'ha Luka nawögu; ohe awöu Mareko andrö, moguna sa ia khögu, ngoni-ngonigu.[10]', '["Kol 4:14","Kol 4:10","Kol 4:7"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 12, 'Tikhiko andrö, ba no ufatenge ba Nefeso.[11]', '["Kol 4:14","Kol 4:10","Kol 4:7"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 13, 'Baru sebua andrö, niröigu ba Deroa, khö Garafo, ohe, na möi''ö ba da''e, ba sura andrö, oföna guli geu andrö.', '[]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 14, 'No oya ilau khögu zi lö sökhi Alesandro, siambu andrö; isulöni dania khönia So''aya mbua-buania andrö;[12]', '["TimI 1:20; Sin 28:4; KorII 11:15"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 15, 'ba ya''ugö göi, angelama khönia; noa sa iforege wamadaö niŵa''öma andrö.', '["TimI 1:20; Sin 28:4; KorII 11:15"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 16, 'Me tesekhegö ndra''o, si föföna andrö, ba samösa lö sango''awögö ya''o, noa sa ahori laröi ndra''o; böi yatebe''e ömöra!', '["HalZin 27:24; 9:15"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 17, 'Ba no fa''awö khögu Zo''aya, ba no i''abölö''ö ndra''odo, ena''ö u''asiwai wangombakha andrö, ba ena''ö larongo fefu soi; ba no te''efa''ö ndra''o ba mbawa zingo.[13]', '["HalZin 27:24; 9:15"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 18, 'Ba i''efa''ö dania ndra''o So''aya, ba nifakhai dödö andrö, si lö sökhi, fefu, ba i''orifi ndra''o, i''ohedo ba mbanuania andrö, ba zorugo. Ya khönia lakhömi, götö-götö wa''ara! Yaduhu.[14]', '["Faigi 3:11; Mat 6:13"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 19, 'Owai Werisa andrö ba Akila, ba si samba omo ndra Onesiforo andrö.[15]', '["Faigi 1:16; HalZin 18:2","HalZin 19:22; 20:4–15"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 20, 'No toröi ba Gorindro Geraso; Terofimo andrö, ba no uröi ba Mileti, mofökhö.[16]', '["Faigi 1:16; HalZin 18:2","HalZin 19:22; 20:4–15"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 21, 'Ta''i-ta''i we''amöi, fatua lö baŵa deu. La''owai ndra''ugö ira Oibulo Fudeo ba Lino ba Kalaudia ba talifusö andrö, fefu.', '["Gal 6:18"]', NULL),
  (3391796, 'NT', 'Timoteo II', 4, 22, 'Ya awö dödöu Zo''aya! Yafalukha ami wa''ebua dödö![17]', '["Gal 6:18"]', NULL),
  (3391825, 'NT', 'Tito', 1, 1, 'Faulo zanura da''e, enoni Lowalangi andrö, sinenge Yesu Keriso, ba wamati nitutuyu Lowalangi andrö, ba ba wa''aboto ba dödöra zi duhu, ba wolo''ö li Lowalangi andrö,[1]', '["Rom 1:1","Rom 16:25","TimI 2:6–7","Gal 2:3; KorII 8:23; TimI 1:2"]', NULL),
  (3391825, 'NT', 'Tito', 1, 2, 'börö wanötöna andrö, fanötöna fa''auri si lö aetu andrö, nifabu''u Lowalangi, si lö mofaya, föna götö danö andre.[2]', '["Rom 1:1","Rom 16:25","TimI 2:6–7","Gal 2:3; KorII 8:23; TimI 1:2"]', NULL),
  (3391825, 'NT', 'Tito', 1, 3, 'Ba noa sa ifa''ele''ö daroma linia, me inötönia, ba wangombakha andrö, nibe''e ba dangagu, dali goroisa Lowalangi andrö, sangorifi ya''ita.[3]', '["Rom 1:1","Rom 16:25","TimI 2:6–7","Gal 2:3; KorII 8:23; TimI 1:2"]', NULL),
  (3391825, 'NT', 'Tito', 1, 4, 'Khö Dito andrö, si ndruhu nonogu, dali wa no faoma wamati. Yafalukha''ö wa''ebua dödö ba fa''ohahau dödö, khö Lowalangi Ama, ba khö Keriso Yesu, sangorifi ya''ita andrö.[4]', '["Rom 1:1","Rom 16:25","TimI 2:6–7","Gal 2:3; KorII 8:23; TimI 1:2"]', NULL),
  (3391825, 'NT', 'Tito', 1, 5, 'Da''ö mbörö, wa no uröi ndra''ugö ba Gereta, ena''ö ö''a''atulö zi tosai andrö, ba ena''ö ödozigö banua, wamataro satua; ö''o''ö niŵa''ögu khöu;[5]', '["HalZin 14:23; TimII 2:2","TimI 3:2 b.t.","KorI 4:1; TimII 2:24","TimII 4:2; 1:13"]', NULL),
  (3391825, 'NT', 'Tito', 1, 6, 'na so zi lö sinegu, si ha sambua donga, si so ono samati, si lö turia wa''asilöyaŵa, ba he turia wa lö molo''ö li.[6]', '["HalZin 14:23; TimII 2:2","TimI 3:2 b.t.","KorI 4:1; TimII 2:24","TimII 4:2; 1:13"]', NULL),
  (3391825, 'NT', 'Tito', 1, 7, 'Sanaro andrö sa, ba lö tola mosinegu, ya si mane satua zangai halöŵö, khö Lowalangi, böi same''e manö ba nikhoi dödönia hadia ia, ba böi si ono wönutö, ba böi samadu-madu tuo, ba böi si fabago-bago, ba böi sangalui ana''a si lö atulö;[7]', '["HalZin 14:23; TimII 2:2","TimI 3:2 b.t.","KorI 4:1; TimII 2:24","TimII 4:2; 1:13"]', NULL),
  (3391825, 'NT', 'Tito', 1, 8, 'ha same''e-me''e gö dome, somasi si sökhi, satua-tua, satulö tödö, sohau-hau, si höndrögö si lö sökhi;', '["HalZin 14:23; TimII 2:2","TimI 3:2 b.t.","KorI 4:1; TimII 2:24","TimII 4:2; 1:13"]', NULL),
  (3391825, 'NT', 'Tito', 1, 9, 'si lö mamöhöi taroma li si ndruhu andrö, si faudu ba wamahaö andrö, ena''ö faoma i''ila, he famarou tödö, ba wamahaö si ndruhu andrö, ba he famaduhu''ö tödö zamadaö andrö.[8]', '["HalZin 14:23; TimII 2:2","TimI 3:2 b.t.","KorI 4:1; TimII 2:24","TimII 4:2; 1:13"]', NULL),
  (3391825, 'NT', 'Tito', 1, 10, 'Ato sa zi lö mamondrongo li, solau huhuo si lö boto, ba samowöhö niha bö''ö, abölö-bölö ba niboto.[9]', '["HalZin 15:1","TimII 3:6; FetI 5:2","HalZin 17:28","Faigi 3:9; TimI 1:4 b.t."]', NULL),
  (3391825, 'NT', 'Tito', 1, 11, 'Nifa''afu bawa da''ö; ya''ira zamakuyu niha, so, ba samba omo manö, ba wamahaö si lö tola andrö, khöra, wangalui ana''a si lö sökhi.[10]', '["HalZin 15:1","TimII 3:6; FetI 5:2","HalZin 17:28","Faigi 3:9; TimI 1:4 b.t."]', NULL),
  (3391825, 'NT', 'Tito', 1, 12, 'No iŵa''ö sama''ele''ö khöra, oi ya''ira, imane: "Sofaya manö Ndrawa Gereta andrö, utu ndru''u safaito, sedöna manö manga-manga lö halöŵö."[11]', '["HalZin 15:1","TimII 3:6; FetI 5:2","HalZin 17:28","Faigi 3:9; TimI 1:4 b.t."]', NULL),
  (3391825, 'NT', 'Tito', 1, 13, 'Ba si ndruhu niŵa''önia andrö, ba andrö abe''e''ö wangotu''ö ya''ira, ena''ö atulö wamatira;', '["HalZin 15:1","TimII 3:6; FetI 5:2","HalZin 17:28","Faigi 3:9; TimI 1:4 b.t."]', NULL),
  (3391825, 'NT', 'Tito', 1, 14, 'ba böi ndramu''o''ö waya-faya niha Yehuda andrö, ba amakhoita niha sangerogö si duhu.[12]', '["HalZin 15:1","TimII 3:6; FetI 5:2","HalZin 17:28","Faigi 3:9; TimI 1:4 b.t."]', NULL),
  (3391825, 'NT', 'Tito', 1, 15, 'Ba zohau-hau tödö, ba lö hadia ia zalakha, ba ba zi ra''i-ra''iö, ba ba zi lö mamati, ba oi salakha manö, fefu, hadia ia; noa sa moda''i gera-erara, ba he tödöra.[13]', '["Rom 14:14–20; Luk 11:39 b.t.","TimII 3:5"]', NULL),
  (3391825, 'NT', 'Tito', 1, 16, 'Laŵa''ö sa, no aboto ba dödöra Lowalangi, ba ba mbua-buara, ba la''osilö''ögö ia; ni''ogorofi ira, si lö mamondrongo li, ba si tebai ba mbua-bua si sökhi andrö fefu.[14]', '["Rom 14:14–20; Luk 11:39 b.t.","TimII 3:5"]', NULL),
  (3391826, 'NT', 'Tito', 2, 1, 'Ba ya''ugö, ba hadia zi faudu ba wamahaö si ndruhu andrö, da''ö ombakha''ö;[1]', '["Faigi 1:9"]', NULL),
  (3391826, 'NT', 'Tito', 2, 2, 'ena''ö, böi sambö era-era ndra matua satua andrö, ena''ö si sökhi amuata ira, satua-tua, ena''ö atulö wamati, awö wa''omasi, awö wanaha tödö andrö.', '["Faigi 1:9"]', NULL),
  (3391826, 'NT', 'Tito', 2, 3, 'Ba si manö ndra alawe satua, ba gamuatara, ena''ö soadu ba ni''amoni''ö andrö, böi samöbögö si lö duhu, böi samorege famadu tuo, ena''ö samahaö ba zi sökhi,[2]', '["TimI 3:11; 5:10","Efes 5:22 b.t."]', NULL),
  (3391826, 'NT', 'Tito', 2, 4, 'ena''ö lafamaha zawena muhalö, ba wangomasi''ö ira matuara ba onora;', '["TimI 3:11; 5:10","Efes 5:22 b.t."]', NULL),
  (3391826, 'NT', 'Tito', 2, 5, 'lafamaha, ena''ö atua-tua ba ohau-hau, ena''ö lahaogö halöŵöra baomora, ba ena''ö la''o''ö li ndra matuara, fa böi tetandraŵaisi daroma li Lowalangi andrö.[3]', '["TimI 3:11; 5:10","Efes 5:22 b.t."]', NULL),
  (3391826, 'NT', 'Tito', 2, 6, 'Si manö göi ba nono matua: öfarou dödöra, ena''ö atua-tua.', '[]', NULL),
  (3391826, 'NT', 'Tito', 2, 7, 'Fefu hadia ia, ba be''e duma-duma ndra''ugö, ba mbua-bua si sökhi, ba ba wamahaö, ba böi fabaya zi lö göna, yamoadu,[4]', '["TimI 4:12; FetI 5:3","FetI 2:12; 3:16"]', NULL),
  (3391826, 'NT', 'Tito', 2, 8, 'fehede satulö wehedeu, si lö sinegu, ena''ö aila zi fa''udu andrö, na tebai iböbögö khöda zi lö sökhi.[5]', '["TimI 4:12; FetI 5:3","FetI 2:12; 3:16"]', NULL),
  (3391826, 'NT', 'Tito', 2, 9, 'Sawuyu andrö, ba farou dödö, ena''ö la''o''ö li zokhö ya''ira: ena''ö lafaigi zomasi zokhö, fefu, hadia ia, böi ndramamadaö,[6]', '["Efes 6:5 b.t.; TimI 6:1 b.t."]', NULL),
  (3391826, 'NT', 'Tito', 2, 10, 'böi managö, ena''ö a''oi so wa lö faröi ira, si sökhi, ena''ö moturia lala Lowalangi, sangorifi ya''ita ba khöra andrö, fefu, labe''e.', '["Efes 6:5 b.t.; TimI 6:1 b.t."]', NULL),
  (3391826, 'NT', 'Tito', 2, 11, 'Noa sa to''ele wa''ebua dödö Lowalangi andrö, sangorifi niha fefu;[7]', '["Faigi 3:4; YohI 4:9","FetI 2:11; YohI 2:15 b.t.","KorI 1:7; Fet 1:7","Gal 1:4; TimI 2:6; Efes 5:27; 2:10"]', NULL),
  (3391826, 'NT', 'Tito', 2, 12, 'ifahaö ita, ena''ö taböhöli wa lö ba dödöda Lowalangi, awö wangisö andrö, ba guli danö, ba ena''ö satua-tua ita, ba satulö tödö, ba solo''ö li Lowalangi, ba götö da''e ba guli danö,[8]', '["Faigi 3:4; YohI 4:9","FetI 2:11; YohI 2:15 b.t.","KorI 1:7; Fet 1:7","Gal 1:4; TimI 2:6; Efes 5:27; 2:10"]', NULL),
  (3391826, 'NT', 'Tito', 2, 13, 'sombalo-mbaloi tötönafö andrö, sohahau dödö, ba fa''ato''ele lakhömi Lowalangi sebua andrö, sangorifi ya''ita, Keriso Yesu,[9]', '["Faigi 3:4; YohI 4:9","FetI 2:11; YohI 2:15 b.t.","KorI 1:7; Fet 1:7","Gal 1:4; TimI 2:6; Efes 5:27; 2:10"]', NULL),
  (3391826, 'NT', 'Tito', 2, 14, 'si no mame''e ya''ia, salahida, ba wangefa''ö ya''ita, ba zi lö atulö fefu, ba ba wangehao ya''ita, banua khönia, sowölö-ölö ba mbua-bua si sökhi.[10]', '["Faigi 3:4; YohI 4:9","FetI 2:11; YohI 2:15 b.t.","KorI 1:7; Fet 1:7","Gal 1:4; TimI 2:6; Efes 5:27; 2:10"]', NULL),
  (3391826, 'NT', 'Tito', 2, 15, 'Da''ö ombakha''ö, ba farou dödöra, ba oigö dödöu wangotu''ö. Böi yamu''ositengagö ndra''ugö niha, ha niha ia.[11]', '["TimI 4:11-12"]', NULL),
  (3391827, 'NT', 'Tito', 3, 1, 'Fasugi ba dödöra, fa la''o''ö li zalaŵa, ba li zokhö ya''ira, fa lafondrondrongo, fa böi abua gölöra, ba wolau si sökhi, fefu, hadia ia.[1]', '["Rom 13:1 b.t.; FetI 2:13 b.t.","TimII 2:24; Kol 3:12","Efes 2:2 b.t."]', NULL),
  (3391827, 'NT', 'Tito', 3, 2, 'Böi latandraŵaisi niha, ha niha ia, böi fasoso-soso, ena''ö lahaogö-haogö, ena''ö oroma, wa no a''oi so wa''ebolo dödöra, ba niha fefu.[2]', '["Rom 13:1 b.t.; FetI 2:13 b.t.","TimII 2:24; Kol 3:12","Efes 2:2 b.t."]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391827, 'NT', 'Tito', 3, 3, 'Ya''ita göi föna, ba noa sa si lö tödö, ba si lö molo''ö li, ba si no elungu, ba sawuyu wangisö andrö, ba sawuyu zomasi dödö andrö, si no oya ngawalö; no tatörö lala si lö sökhi, awö lala wa''afökhö dödö; no ni''ogorofi ita, ba no faoma fatiu dödöda khö nawöda.[3]', '["Rom 13:1 b.t.; FetI 2:13 b.t.","TimII 2:24; Kol 3:12","Efes 2:2 b.t."]', NULL),
  (3391827, 'NT', 'Tito', 3, 4, 'Ba me no to''ele wa''asökhi dödö Lowalangi, sangorifi ya''ita, awö wa''omasinia niha,[4]', '["Faigi 2:11","TimII 1:9; FetI 1:3; Yoh 3:5; Efes 5:26 b.t.; 4:23; Rom 6","Hes 36:25 b.t.","Rom 8:24 b.t."]', NULL),
  (3391827, 'NT', 'Tito', 3, 5, 'ba no i''orifi ita, tenga moroi ba mbua-buada, ba wa''atulö dödö, balazi wa''ahakhö dödönia andrö, ba wemondri andrö, ba wa''atumbu si bohou, ba ba wamohouni andrö, khö Geheha ni''amoni''ö,[5]', '["Faigi 2:11","TimII 1:9; FetI 1:3; Yoh 3:5; Efes 5:26 b.t.; 4:23; Rom 6","Hes 36:25 b.t.","Rom 8:24 b.t."]', NULL),
  (3391827, 'NT', 'Tito', 3, 6, 'nihönania khöda, wolau ya''ia, nifa''ema Yesu Keriso, sangorifi ya''ita;[6]', '["Faigi 2:11","TimII 1:9; FetI 1:3; Yoh 3:5; Efes 5:26 b.t.; 4:23; Rom 6","Hes 36:25 b.t.","Rom 8:24 b.t."]', NULL),
  (3391827, 'NT', 'Tito', 3, 7, 'ena''ö satulö ita, iŵa''ö Lowalangi, moroi ba wa''ebua dödönia, ba tötönaföda gondröita andrö, fa''auri si lö aetu.[7]', '["Faigi 2:11","TimII 1:9; FetI 1:3; Yoh 3:5; Efes 5:26 b.t.; 4:23; Rom 6","Hes 36:25 b.t.","Rom 8:24 b.t."]', NULL),
  (3391827, 'NT', 'Tito', 3, 8, 'Si ndruhu daroma li andrö, ba omasi ndra''o, na öfaduhu''ö sibai da''ö, ena''ö owölö-ölö zi no mamati ba Lowalangi, wamalua bua-bua si sökhi. Da''ö zi sökhi, ba da''ö zoguna ba niha.[8]', '["Faigi 3:14"]', NULL),
  (3391827, 'NT', 'Tito', 3, 9, 'Ba amadöniŵa andrö, si lö boto, ba fanutunö nga''ötö, ba fasosota, ba fagua-guasa andrö, ba goroisa, ba böi babaya; lö''ö sa gunania, no si lö boto.[9]', '["Faigi 1:14","Rom 16:17; Mat 18:15 b.t.","TimI 6:4–5"]', NULL),
  (3391827, 'NT', 'Tito', 3, 10, 'Na so zi fasambua famahaö, ba böhöli, na no ötenaŵa ia, irege mendrua,[10]', '["Faigi 1:14","Rom 16:17; Mat 18:15 b.t.","TimI 6:4–5"]', NULL),
  (3391827, 'NT', 'Tito', 3, 11, 'ya''aboto ba dödöu, wa no tefuyu dödö zi manö, awö wa samazökhi horö ia, awö wa ya''ia zanguhuku ya''ia.[11]', '["Faigi 1:14","Rom 16:17; Mat 18:15 b.t.","TimI 6:4–5"]', NULL),
  (3391827, 'NT', 'Tito', 3, 12, 'Na ufatenge khöu Gatema andrö, ba ma Tikhiko andrö, ba ta''i-ta''i ae khögu, ba Nikofoli; ba da''ö sa sodo na baŵa deu, uŵa''ö.', '["HalZin 18:24"]', NULL),
  (3391827, 'NT', 'Tito', 3, 13, 'Tolo Zena andrö, sangila amakhoita, ba Afolo andrö, wama''anö ya''ira, ba wofanö, haogö, fa böi ambö khöra hadia ia.[12]', '["HalZin 18:24"]', NULL),
  (3391827, 'NT', 'Tito', 3, 14, 'Ba ndramufamaha göi ira banuada, wanolo niha bö''ö ba zoguna, ndramuhaogö, fa böi si lö bua-bua si sökhi ira.', '["HalZin 18:24"]', NULL),
  (3391827, 'NT', 'Tito', 3, 15, 'La''owai ndra''ugö awögu andre fefu. Owai fefu zomasi ya''ita, ba wamati. Yafalukha ami fefu wa''ebua dödö![13]', '["Fil 4:23"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 1, 'Faulo, nikuru andrö khö Keriso Yesu, zanura da''e, ba Timoteo, talifusö andrö, khö Wilemo andrö, ni''omasi''ö, awöma, ba halöŵö andrö,[1]', '["Efes 3:1; 4:1; KorII 1:1","Kol 4:15–17","Kol 1:2"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 2, 'ba khö Gafia, talifusö alawe andrö, ba khö Garikhifo, awöma andrö, ba wasöndrata, ba ba mbanua andrö, yomo khöu.[2]', '["Efes 3:1; 4:1; KorII 1:1","Kol 4:15–17","Kol 1:2"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 3, 'Yafalukha ami wa''ebua dödö ba fa''ohahau dödö, khö Namada Lowalangi, ba khö Yesu Keriso, So''aya ya''ita![3]', '["Efes 3:1; 4:1; KorII 1:1","Kol 4:15–17","Kol 1:2"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 4, 'Lö mamalö-malö wangandrögu saoha gölö khö Lowalangigu, na itörö tödögu ndra''ugö, na mangandrö ndra''o,[4]', '["Rom 1:8","Kol 1:4","Gal 5:6"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 5, 'börö me urongo wa''omasiu andrö, ba famati andrö khöu, khö Zo''aya, Yesu, ba ba ni''amoni''ö andrö, fefu;[5]', '["Rom 1:8","Kol 1:4","Gal 5:6"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 6, 'ena''ö abölö wa''awösa andrö ba wamatimö, ba wamotokhi ba dödöu fefu hadia ia zi sökhi, ba khöda, khö Keriso.[6]', '["Rom 1:8","Kol 1:4","Gal 5:6"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 7, 'Noa sa abölö wa''omuso dödögu, ba fondrara dödögu, ba wa''omasiu andrö, me no te''okafui dödö ni''amoni''ö andrö, ba khömö, ya''ugö talifusö.', '["Rom 1:8","Kol 1:4","Gal 5:6"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 8, 'Andrö, he ŵa''ae tola manö, ba khö Keriso, ube''e goroisa khöu, ba zi nangea andrö, ba edönado zui mangandrö khöu, börö wa''omasi andrö: Ya''odo andre,', '["TimII 1:8","KorI 4:15; Kol 4:9"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 9, 'Faulo satua andre, ba nikuru göi iada''e, khö Keriso Yesu,[7]', '["TimII 1:8","KorI 4:15; Kol 4:9"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 10, 'u''andrö khöu, ba khö nonogu andrö, nisöndragu onogu, ba gurunga andre, Onesimo "soguna" andrö,[8]', '["TimII 1:8","KorI 4:15; Kol 4:9"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 11, 'si no si lö guna khöu föna, ba soguna iada''e, he khöu, ba he khögu.', '["TimII 1:8","KorI 4:15; Kol 4:9"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 12, 'Ufatenge ia mangawuli; tödögu nifatengegu.', '[]', NULL),
  (3391831, 'NT', 'Filemo', 1, 13, 'Utaha ia mena''ö khögu, ena''ö ngoni-ngonigu ia, salahiu, ba gurunga andre, ba duria somuso dödö andrö.', '[]', NULL),
  (3391831, 'NT', 'Filemo', 1, 14, 'Ba lö''ö sa edönado ulau hadia ia, na lö niteheu, fa böi hulö zabua ölö ndra''ugö, ba dolo-tolomö andrö, ena''ö saoha gölö.', '[]', NULL),
  (3391831, 'NT', 'Filemo', 1, 15, 'Ma andrö aefa ia khöu ma''ifu, ena''ö lö''ö sa''ae tebulö ia khöu,', '["TimI 6:1–2; Efes 6:5"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 16, 'tenga sa''ae sawuyu, si töra moroi ba zawuyu, no talifusö ni''omasi''ö, oföna khögu, ba mendrua manö na i khöu, he botonia, ba he ba khö Zo''aya.[9]', '["TimI 6:1–2; Efes 6:5"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 17, 'Ba na belau ndra''odo, öŵa''ö, ba tema ia, hulö na ya''o mena''ö.', '["TimI 6:1–2; Efes 6:5"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 18, 'Ba na no te''ala ndra''ugö, ibe''e mege, ba ma na so gömönia khöu, ba be''e ömögu.', '["TimI 6:1–2; Efes 6:5"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 19, 'Ya''o, Faulo, zanura da''e, tangagu: Ya''o zamu''a; fa lö uŵa''ö khöu, ömöu khögu ndra''ugö andrö göi.[10]', '["TesII 3:17","Ayati 10:11"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 20, 'Si ndruhu, ya''ugö ga''a, ena''ö mohare ndra''o khöu, ba khö Zo''aya! Okafui dödögu andre, ba khö Keriso![11]', '["TesII 3:17","Ayati 10:11"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 21, 'Me no udöna-döna wolo''ömö, andrö usura khöu da''ö, me no u''ila, tenga ha niŵa''ögu andrö ö''o''ö, otöraigö na i.', '["Heb 13:19"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 22, 'Ba endrongagö göi wamaigi naha khögu; udöna-döna sa, tebe''e buala ndra''o khömi, börö wangandrömi andrö.[12]', '["Heb 13:19"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 23, 'I''owai ndra''ugö Efafera, awögu nikuru andrö, ba khö Keriso Yesu,[13]', '["Kol 1:7","Kol 4:10–14"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 24, 'ba Mareko ba Arisaro ba Dema ba Luka, awögu ba halöŵö andrö.[14]', '["Kol 1:7","Kol 4:10–14"]', NULL),
  (3391831, 'NT', 'Filemo', 1, 25, 'Yafalukha dödömi wa''ebua dödö Zo''aya, Yesu Keriso.[15]', '["TimII 4:22"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 1, 'Me no aefa wehede Lowalangi föna, khö ndra tuada, si no asese, ba si no oya ngawalö, nifa''ema zama''ele''ö andrö, ba no muhede ia, me luo safuria andre, khöda, nifa''ema Nononia.[1]', '["MozIV 12:6 b.t.; HalZin 3:22–24; FetI 1:20; Yoh 15:15"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 2, 'Nifataronia sanema ondröita, fefu, hadia ia, nibe''enia göi samazökhi danö''a,[2]', '["Faigi 2:7–8; Efes 1:20 b.t.; Yoh 1:3–10","KorII 4:4; Kol 1:15; Faigi 9:14–26; 12:2","Fil 2:9"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 3, 'si no haga lakhöminia andrö ba duma-duma mbotonia, sanaya fefu hadia ia, taroma li fa''abölönia andrö, ba no isöndra wangehao andrö, fameta horö, ba no mudadao ia ba gambölö wa''asalaŵa andrö, ba zalaŵa yaŵa;[3]', '["Faigi 2:7–8; Efes 1:20 b.t.; Yoh 1:3–10","KorII 4:4; Kol 1:15; Faigi 9:14–26; 12:2","Fil 2:9"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 4, 'ba no tohude ia moroi ba mala''ika, ndrohu-ndrohu wa''atohude döi andrö, nitemania, moroi ba döira.[4]', '["Faigi 2:7–8; Efes 1:20 b.t.; Yoh 1:3–10","KorII 4:4; Kol 1:15; Faigi 9:14–26; 12:2","Fil 2:9"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 5, 'Ha niha sa mala''ika, ba zi no irai iŵaö: "Onogu ndra''ugö, ma''ökhö andre no mo''ono ndra''o ya''ugö?" Ba imane zui: "Amania ndra''odo ba Onogu ia."[5]', '["Faigi 5:5; Sin 2:7; SamII 7:14","Kol 1:15; Rom 8:29; Sin 97:7; Efes 1:21","Sin 104:4"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 6, 'Ba so zui, me ifataro ba guli danö zi a''a ba wa''atumbu andrö, ba imane: "Ba yamangalulu khönia mala''ika Lowalangi, fefu."[6]', '["Faigi 5:5; Sin 2:7; SamII 7:14","Kol 1:15; Rom 8:29; Sin 97:7; Efes 1:21","Sin 104:4"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 7, 'Ba imane sa ba mala''ika andrö: "Samali''ö angi mala''ikania, ba samali''ö hola-hola galitö enoninia".[7]', '["Faigi 5:5; Sin 2:7; SamII 7:14","Kol 1:15; Rom 8:29; Sin 97:7; Efes 1:21","Sin 104:4"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 8, 'Ba ba Nono andrö, ba imane: "Dadaomamö, ya''ugö Lowalangi, ba no si lö tebulö, götö-götö wa''ara, ba si''o ba wa''atulö zi''o zalaŵa andrö khöu.[8]', '["Sin 45:7–8","Yes 61:1","Sin 102:26–28","Yes 51:6; FetII 3:10"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 9, 'No omasi ndra''ugö wa''atulö, ba no fa''udu ndra''ugö ba zi lö atulö; andrö no ibayoini ndra''ugö Lowalangiu, ya''ugö Lowalangi, fanikha fa''owua-wua dödö, no ihude''ö ndra''ugö, moroi ba nawöu."[9]', '["Sin 45:7–8","Yes 61:1","Sin 102:26–28","Yes 51:6; FetII 3:10"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 10, 'Ba: "Ya''ugö So''aya zolata tanö, ba mböröta, ba nifazökhi dangau mbanua si yaŵa;[10]', '["Sin 45:7–8","Yes 61:1","Sin 102:26–28","Yes 51:6; FetII 3:10"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 11, 'ya''ia, ba sadudu dania, ba ya''ugö, ba si lö tebulö; ba atua dania da''ö fefu, timba mbaru,[11]', '["Sin 45:7–8","Yes 61:1","Sin 102:26–28","Yes 51:6; FetII 3:10"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 12, 'ba ögölugö dania, hulö lembe, ba tobali dania, ba ya''ugö, ba ya''u-ya''ugö manö, ba si lö aetu ndröfiu."', '["Sin 45:7–8","Yes 61:1","Sin 102:26–28","Yes 51:6; FetII 3:10"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 13, 'Ba ha niha ba mala''ika, ba zi no irai iŵa''ö: "Dadao ba gambölögu, irege no ube''e dane-dane gaheu zi fatiu tödö khöu?"[12]', '["Sin 110:1","Sin 34:8; 92:11 b.t.; Mat 18:10"]', NULL),
  (3391834, 'NT', 'Heberaio', 1, 14, 'Tenga no a''oi bekhu enoni ira, nifatenge sanolo ba zanema fangorifi andrö dania?[13]', '["Sin 110:1","Sin 34:8; 92:11 b.t.; Mat 18:10"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 1, 'Andrö mendrua manö ta''olembai ena''ö nirongoda andrö, fa böi ahani ita.', '["HalZin 7:53; Gal 3:19","Faigi 10:2; Mar 1:14","HalZin 14:3; KorI 12:4–11"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 2, 'Na no aro sa''ae daroma li andrö, ni''ombakha''ö mala''ika, ba na no tesulöni si nangea khönia fefu ngawalö wanawö, awö ngawalö wa lö molo''ö fefu,[1]', '["HalZin 7:53; Gal 3:19","Faigi 10:2; Mar 1:14","HalZin 14:3; KorI 12:4–11"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 3, 'ba he tawisa wangefa''ö ya''ita, na ta''ositengagö wangorifi si manö fa''ebua? nifobörö ba wangombakha Zo''aya andrö, nifaduhu''ö zamondrongo khönia andrö, khöda,[2]', '["HalZin 7:53; Gal 3:19","Faigi 10:2; Mar 1:14","HalZin 14:3; KorI 12:4–11"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 4, 'nifo''awö famaduhu''ö andrö khö Lowalangi, ba dandra andrö, ba ba gila-ila, ba ba ngawalö hadia ia wa''abölö, ba ba wame''e-me''e Eheha ni''amoni''ö andrö, dali zomasi ia.[3]', '["HalZin 7:53; Gal 3:19","Faigi 10:2; Mar 1:14","HalZin 14:3; KorI 12:4–11"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 5, 'Tenga sa barö mbawa mala''ika ibe''e zi sagötö tanö dania, niŵa''ö-ŵa''öma.[4]', '["FetII 3:13","Sin 8:5 b.t.","Luk 22:43","Faigi 1:2; Mat 28:18; Yoh 3:35"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 6, 'Ba noa sa so zamaduhu''ö, samuza, no imane: "Hadia niha, wa itörö tödöu? ba ono niha, wa öfaigi ia?[5]', '["FetII 3:13","Sin 8:5 b.t.","Luk 22:43","Faigi 1:2; Mat 28:18; Yoh 3:35"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 7, 'No ö''ide-ide''ö ia, si lö arara, tou mala''ika; no öfotakula ia, lakhömi ba sumange,[6]', '["FetII 3:13","Sin 8:5 b.t.","Luk 22:43","Faigi 1:2; Mat 28:18; Yoh 3:35"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 8, 'no öbe''e barö gahenia fefu, hadia ia." Ba wame''e barö mbawa andrö sa fefu, hadia ia, ba lö nisaigönia, si lö mube''e barö mbawania. Ba iada''e, ba lö''ö na ta''ila, no mube''e barö mbawania fefu, hadia ia.[7]', '["FetII 3:13","Sin 8:5 b.t.","Luk 22:43","Faigi 1:2; Mat 28:18; Yoh 3:35"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 9, 'Ba ni''ide-ide''ö andrö, tou mala''ika, si lö arara, Yesu, ba ta''ila, nifo''aya lakhömi ba sumange, börö wamakao andrö, nitahania, fa''amate andrö, ena''ö itandra wa''amate, salahi niha fefu, balazi wa''ebua dödö Lowalangi.[8]', '["Fil 2:8–9 b.t.; KorII 5:14–15"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 10, 'Da''ö sa zi nangea khönia, si no börö hadia ia, fefu, ba zoroi fefu, hadia ia, me ato ndraono i''ohe ba lakhömi: ba wamakao ifo''ahonoa solohe ya''ira ba wangorifi andrö.[9]', '["Rom 11:36; Faigi 5:8–9 HalZin 5:31"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 11, 'Ba he si amoni''ö sa, ba he ni''amoni''ö andrö, ba ha samösa duara fefu; da''ö göi mbörö, wa lö aila ia fatalifusö khöra,[10]', '["Yoh 17:19; Mar 3:34 b.t.","Sin 22:23; Rom 8:29","Yes 8:17–18"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 12, 'imane: "U''ombakha''ö döimö ba dalifusögu andrö, ba zowulo banua usuno ndra''ugö."[11]', '["Yoh 17:19; Mar 3:34 b.t.","Sin 22:23; Rom 8:29","Yes 8:17–18"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 13, 'Ba imane zui: "Sanötöna khönia dania ndra''odo." Ba so zui, ba imane: "Hiza, ya''o ba iraono andrö, nibe''e Lowalangi khögu."[12]', '["Yoh 17:19; Mar 3:34 b.t.","Sin 22:23; Rom 8:29","Yes 8:17–18"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 14, 'Ba me no ösi niha göi nösi ndraono, ba no itema göi dana khönia da''ö, no fakhili-khili, ena''ö ifakiko ba wa''amate andrö zi so fa''abölö wa''amate. Afökha andrö;[13]', '["Rom 8:3; TimII 1:10; YohI 3:8","Rom 6:17 b.t."]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 15, 'ba ena''ö i''efa''ö zi no sawuyu, sagötö ya''ira, ba wa''ata''ura wa''amate andrö.[14]', '["Rom 8:3; TimII 1:10; YohI 3:8","Rom 6:17 b.t."]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 16, 'Tenga sa ato mala''ika nitolonia, no ma''uwu Gaberahamo andrö itolo.', '["Rom 8:3; TimII 1:10; YohI 3:8","Rom 6:17 b.t."]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 17, 'Andrö lö tola lö fagölö-gölö ia ba dalifusönia, gofu he wisa wamaigida, ena''ö sahakhö tödö ia, ba ere sebua, si lö faröi, khö Lowalangi, ba wame''e höli ba horö mbanua andrö.[15]', '["Faigi 4:15–5;1 b.t.","Faigi 4:16"]', NULL),
  (3391835, 'NT', 'Heberaio', 2, 18, 'Ndrohu-ndrohu zi no itaha famakao sa, si no tetandraigö ia, ba i''ila itolo nitandraigö andrö.[16]', '["Faigi 4:15–5;1 b.t.","Faigi 4:16"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 1, 'Andrö, ya''ami, ira talifusö, ni''amoni''ö, si no mo''urakha ba wogaoni andrö, moroi ba zorugo, mitöngöni zinenge andrö, ere sebua, ba wamaduhu''öda andrö, Yesu,[1]', '["Fil 3:14; Faigi 4:14","MozIV 12:7","Faigi 8:6"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 2, 'si lö faröi andrö, khö zamataro ya''ia, si mane Moze göi, yomo khönia fefu.[2]', '["Fil 3:14; Faigi 4:14","MozIV 12:7","Faigi 8:6"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 3, 'Ebua sa dana khönia lakhömi, moroi khö Moze, ndrohu-ndrohu wa''atohude wa''ebua zotomo, moroi ba wa''ebua nomo.[3]', '["Fil 3:14; Faigi 4:14","MozIV 12:7","Faigi 8:6"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 4, 'Fefu nomo sa, ba so zotomo, ba samazökhi fefu, hadia ia, ba ya''ia Lowalangi.', '["Yoh 5:46"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 5, 'Ba Moze, ba si lö faröi sa, yomo khönia fefu, enoni ia, ba wamaduhu''ö ni''ombakha''ö dania.[4]', '["Yoh 5:46"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 6, 'Ba Keriso, ba no Ono, ba nomonia; ba omonia ita, na lö taböhöli wa lö mangiwa, awö duriada andrö, ba wanötöna irugi gamozua; na ta''aro''ö khöda.[5]', '["Yoh 8:35; FetI 2:5; Faigi 6:11"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 7, 'Andrö, si mane niŵa''ö Geheha: "Ma''ökhö andre, na mirongo linia,[6]', '["Faigi 4:7; Sin 95:8 b.t.","MozII 17:7; MozV 6:16","MozIV 14:22","MozIV 14:23,28–35"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 8, 'ba böi mi''abe''e''ö dödömi, si mane ba wa''abao dödö andrö, me luo wanandraigö andrö, ba danö si mate,[7]', '["Faigi 4:7; Sin 95:8 b.t.","MozII 17:7; MozV 6:16","MozIV 14:22","MozIV 14:23,28–35"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 9, 'me latandraigö ndra''o ira tuami, wombaya ya''o, ba noa sa''ae la''ila nilaugu, öfa wulu fakhe wa''ara;[8]', '["Faigi 4:7; Sin 95:8 b.t.","MozII 17:7; MozV 6:16","MozIV 14:22","MozIV 14:23,28–35"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 10, 'andrö mofönu ndra''o, ba niha andrö, ba umane: Lö mamalö-malö wa''elungu dödöra; ba lö aboto ba dödöra lalagu andrö,', '["Faigi 4:7; Sin 95:8 b.t.","MozII 17:7; MozV 6:16","MozIV 14:22","MozIV 14:23,28–35"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 11, 'tobali fahölu ndra''o, ba wönugu andrö, umane: Böi yalakhamö wolombase andrö, khögu."[9]', '["Faigi 4:7; Sin 95:8 b.t.","MozII 17:7; MozV 6:16","MozIV 14:22","MozIV 14:23,28–35"]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 12, 'Mifaigi, ya''ami ira talifusö, böi yatesöndra ba khömi, ha niha ia, si so tödö si lö sökhi, tödö ba wa lö mamati, ba wangerogö Lowalangi sauri;', '["Faigi 3:7","MozIV 14:1 b.t."]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 13, 'faoma mifarou dödö nawömi, ero ma''ökhö, götö wa laŵa''ö "ma''ökhö andre" fa böi tesöndra ba khömi, ha niha ia, ni''abe''e''ö tödö, ba walimosa horö andrö.', '["Faigi 3:7","MozIV 14:1 b.t."]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 14, 'Noa sa tobali awö Keriso ita, na lö''ö sa ato taböhöli mböröta wa faduhu dödö andrö, irugi gamozua, na ta''aro''ö khöda.', '["Faigi 3:7","MozIV 14:1 b.t."]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 15, 'Na no muŵa''ö: "Ma''ökhö andre, na mirongo linia, ba böi mi''abe''e''ö dödömi, si mane ba wa''abao dödö andrö,"[10]', '["Faigi 3:7","MozIV 14:1 b.t."]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 16, 'ba ha niha ira, samondrongo, sabao tödö andrö? Tenga dozi ira, si otarai danö Miserayi, ni''oloi''ö Moze?[11]', '["Faigi 3:7","MozIV 14:1 b.t."]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 17, 'Ba ha khö mofönu ia, si öfa wulu fakhe andrö? Hadia, tenga ba zanao horö andrö? botora, ba no adudu ba danö si mate.[12]', '["MozIV 14:29; KorI 10:5","MozV 1:32 b.t."]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 18, 'Ba ha khö tetandrösaigö, me fahölu ia, böi yalakhamö wolombase andrö khönia, na tenga ba zi lö molo''ö andrö?', '["MozIV 14:29; KorI 10:5","MozV 1:32 b.t."]', NULL),
  (3391836, 'NT', 'Heberaio', 3, 19, 'Ba no ta''ila, wa tebai lakhamö, börö wa lö mamati.[13]', '["MozIV 14:29; KorI 10:5","MozV 1:32 b.t."]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 1, 'Ba data''ata''ufi, fa böi tesöndra ba khömi, ha niha ia, si hulö zi no toröi furi, me no so na gamabu''ula li, ba wogamö folombase andrö khönia.[1]', '["Faigi 12:15"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 2, 'Noa sa mu''ombakha''ö khöda göi, si mane khöra, ba ba khöra, ba lö sonahia daroma li wangombakha andrö, me lö si tefaböbö ba zamondrongo andrö, ba wamati.', '["Faigi 12:15"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 3, 'Sogamö folombase andrö sa ita, ya''ita samati, si mane niŵa''önia: "Tobali fahölu ndra''o, ba wönugu andrö, umane: Böi yalakhamö wolombase andrö khögu" he ŵa''ae no awai nilau andrö, i''otarai wamazökhi danö''a andrö.[2]', '["Faigi 3:11; Sin 95:11"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 4, 'Noa sa itörö linia, samuza, luo si fitu andrö, no imane: "Ba molombase Lowalangi, ba luo si fitu andrö, me no awai nilaunia fefu."[3]', '["MozI:2–2"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 5, 'Ba imane zui ba da''e: "Böi yalakhamö wolombase andrö khögu!"', '["MozI:2–2"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 6, 'Ba me so sa na dania, lakhamö ia ösa, ba me lö nikhamö nituriagö yaia, si föföna, ba wa lö molo''ö,[4]', '["Faigi 3:19","Faigi 3:7","MozV 31:7; Yos 22:4"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 7, 'ba ifuli i''ötö mbongi: "ma''ökhö" Dawido zama''ema linia, me no si manö wa''ara gotalua, si mane niŵa''ö mege: "Ma''ökhö andre, na mirongo linia, ba böi mi''abe''e''ö dödömi."[5]', '["Faigi 3:19","Faigi 3:7","MozV 31:7; Yos 22:4"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 8, 'Na Yosua sa mena''ö zolohe ya''ira ba wolombase, ba lö itörö ena''ö linia luo bö''ö, furi da''ö no mege.[6]', '["Faigi 3:19","Faigi 3:7","MozV 31:7; Yos 22:4"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 9, 'Tobali so na sa dania wolombase mbanua Lowalangi andrö, folombase ba luo sabato.', '["Fam 14:13"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 10, 'Si no mogamö folombase khönia sa, ba molombase göi, na awai halöŵönia, si mane Lowalangi, me no awai halöŵönia.[7]', '["Fam 14:13"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 11, 'Ba dataforege, ba wogamö folombase andrö, ena''ö lö falukha so zalau, ha niha ia, wolo''ö famaedo andrö, ba wa lö molo''ö.[8]', '["FetII 1:10; KorI 10:11–12"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391837, 'NT', 'Heberaio', 4, 12, 'Sauri sa daroma li Lowalangi andrö, ba sabölö, ba no atarö, moroi ba gari si faoma bawa, ba isösö, irugi ifabali ira noso geheha, ba bu''u ba uto, ba ihuku gera-era dödö, ba söndra dödö,[9]', '["FetI 1:23; Rom 1:16; Efes 6:17; Fam 1:16","Yob 28:24"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 13, 'ba lö hadia ia, nifazökhi Lowalangi, si tobini fönania, fefu, hadia ia, ba lö balu-balu, no mubokai, ba wamaigi zanofu-nofu khöda andrö.[10]', '["FetI 1:23; Rom 1:16; Efes 6:17; Fam 1:16","Yob 28:24"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 14, 'Ba me no so khöda gere sebua, salaŵa, si no manöröi sorugo andrö, Yesu, Ono Lowalangi andrö, ba böi taböhöli wamaduhu''ö andrö.[11]', '["Faigi 8:1; 9:11–24; 10:23","Faigi 5:2; 2:17–18; 7:26","Faigi 10:22; Rom 3:25"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 15, 'Tenga sa ere sebua si tebai ahakhö tödö, ba wa''ambö wa''abölöda, zi so khöda, no ere sebua si no mutandraigö, ba ngawalö hadia ia, fefu, hulö si mane ya''ita; ba lö horö.[12]', '["Faigi 8:1; 9:11–24; 10:23","Faigi 5:2; 2:17–18; 7:26","Faigi 10:22; Rom 3:25"]', NULL),
  (3391837, 'NT', 'Heberaio', 4, 16, 'Ba data''ondrasi daroma wa''ahakhö dödö andrö, böi aiŵö ita, ena''ö tatema wa''ahakhö dödö, ba ena''ö falukha ita wa''ebua dödö, fanolo, na baŵa moguna.[13]', '["Faigi 8:1; 9:11–24; 10:23","Faigi 5:2; 2:17–18; 7:26","Faigi 10:22; Rom 3:25"]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 1, 'Dozi ere sebua sa, nihalö ba niha, ba ba niha tefataro ia, ba halöŵö, khö Lowalangi, ba wame''e ame''ela ba sumange, fameta horö;[1]', '["Faigi 2:17; 8:3","Faigi 4:15","Faigi 7:27; MozIII 9:7; 16:6; 11:17","Nga''ötII 26:18 MozII 28:1"]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 2, 'si no mangila ndrohu-ndrohu wamologö tödönia, ba zi lö mangila watahögö, ba ba zelungu, me ya''ia göi zi no falukha-lukha fa''ambö fa''abölö.[2]', '["Faigi 2:17; 8:3","Faigi 4:15","Faigi 7:27; MozIII 9:7; 16:6; 11:17","Nga''ötII 26:18 MozII 28:1"]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 3, 'Ba me börö da''ö, wa lö tola lö ibe''e zumange, ba khönia göi, si mane ba zato, fameta horö.[3]', '["Faigi 2:17; 8:3","Faigi 4:15","Faigi 7:27; MozIII 9:7; 16:6; 11:17","Nga''ötII 26:18 MozII 28:1"]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 4, 'Ba lö ira''u khönia wa''ebua andrö niha, ha nikaoni Lowalangi, si mane A''aroni andrö göi.[4]', '["Faigi 2:17; 8:3","Faigi 4:15","Faigi 7:27; MozIII 9:7; 16:6; 11:17","Nga''ötII 26:18 MozII 28:1"]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 5, 'Si manö göi Keriso, lö ni''ebua''önia ya''ia, ba we''amöi ere sebua, ha sanguma''ö khönia: "Onogu ndra''ugö, ma''ökhö andre no mo''ono ndra''o ya''ugö."[5]', '["Yoh 8:54; Faigi 1:5","Sin 110:4; Sakh 6:13"]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 6, 'Si mane niŵa''önia, si samuza göi: "Ere ndra''ugö, irugi zi lö aetu, dali gamuata Melekhisede andrö."[6]', '["Yoh 8:54; Faigi 1:5","Sin 110:4; Sakh 6:13"]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 7, 'Me luo niha ia, ba no i''ohe wangandrö, awö wakaosa, khö zangila mangefa''ö ya''ia ba wa''amate, no fao we''ao-ao sabölö-bölö, ba taŵa hörö, ba no mufondrondrongo linia, ba no mu''efa''ö ia ba wa''ata''u andrö.[7]', '["Mar 14:34; Mat 26:37 b.t.; Luk 22:44 b.t."]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 8, 'Ba he ŵa''ae Ono ia, ba no ifamaha ia ba wolo''ö, ba wamakao andrö, nitaögönia;[8]', '["Fil 2:8","Faigi 2:10; 7:25","Faigi 6:1 b.t."]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 9, 'no mufo''ahonoa ia, ba no tobali börö wangorifi ba mbanua furi ia, ba zamondrongo linia, fefu,[9]', '["Fil 2:8","Faigi 2:10; 7:25","Faigi 6:1 b.t."]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 10, 'nifotöi Lowalangi ere sebua, dali gamuata Melekhisede andrö.[10]', '["Fil 2:8","Faigi 2:10; 7:25","Faigi 6:1 b.t."]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 11, 'Ba da''ö oya huhuoda, ba afökhö wamotokhi, me no awe''e-we''e dögi dalingami andrö.[11]', '["Faigi 6:1 b.t.","KorI 3:1 b.t."]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 12, 'Samahaö sa''ae ami ena''ö, me no ara, ba tobali moguna khömi lafahaö zui ami, ba wamobörö daroma li Lowalangi andrö, ba tobali moguna khömi zusu, ba tenga ö sabe''e;[12]', '["Faigi 6:1 b.t.","KorI 3:1 b.t."]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 13, 'ba ha niha zamadu susu, ba lö i''ila watahögö huhuo satulö andrö, me no iraono ia.', '["Faigi 6:1 b.t.","KorI 3:1 b.t."]', NULL),
  (3391838, 'NT', 'Heberaio', 5, 14, 'Ba ba zi no mo''ahonoa, ba ö sabe''e nibe''e, ba zi no mamamaha ya''ira, si no to''ölö tödö, ba wamaehusi hadia zatulö, hadia zi lö atulö.[13]', '["KorI 2:6"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 1, 'Andrö taböhöli sa''ae wamobörö fangombakha Keriso andrö, ba tafa''ese ba wamo''ahonoa; böi sa''ae tafuli wamodane-dane, famalalini era-era ba mbua-bua si mate, ba famati ba Lowalangi,[1]', '["Faigi 5:12; HalZin 20:21","HalZin 2:38; 8:17; 24:25,15"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 2, 'ba famahaö ba wamayagö idanö andrö, ba ba wanufa tanga, ba ba wemaoso zi mate, ba ba wanguhuku si lö tebulö andrö.[2]', '["Faigi 5:12; HalZin 20:21","HalZin 2:38; 8:17; 24:25,15"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 3, 'Ba da''ö nilauda, na itehe Lowalangi.', '["Faigi 5:12; HalZin 20:21","HalZin 2:38; 8:17; 24:25,15"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 4, 'Tebai sa, na so zi no muhagaini tödö zamuza, si no manandra ame''ela andrö moroi ba zorugo, ba si no mo''urakha Eheha ni''amoni''ö andrö,[3]', '["Faigi 10:26 b.t.","FetII 2:20-21"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 5, 'ba si no manandra taroma li Lowalangi andrö, si sökhi, awö wa''abölö andrö,', '["Faigi 10:26 b.t.","FetII 2:20-21"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 6, 'ba götö dania, ba na lafuli furi, ba tebai te''a''azökhi zui ira, ba wamalalini era-era, ya''ira, si no mamoröfa khöra zamuza tö Ono Lowalangi, si no mame''e ni''o''aya ya''ia.[4]', '["Faigi 10:26 b.t.","FetII 2:20-21"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 7, 'Tanö andrö sa, samadu teu andrö, sasese aekhu ba khönia, si so sinanö, soguna ba zamahaogö''ö ya''ia, ba no itema dana khönia howu-howu khö Lowalangi.[5]', '["Yes 55:11","Yes 5:4 b.t."]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 8, 'Ba na sa''a-sa''a mao ba lato zi tumbu khönia, ba lö faduhu dödöda khönia, ba no ahatö khönia wangelifi; ba fozunia, ba fanunu ya''ia.[6]', '["Yes 55:11","Yes 5:4 b.t."]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 9, 'Ba ba khömi, ya''ami ni''omasi''ö, ba no faduhu dödöma, ba zi sökhi, ba zoguna ba wangorifi andrö, he ŵa''ae no si manö lima.', '["Fam 2:2,19; Faigi 10:33 b.t."]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 10, 'Tenga sa si lö atulö Lowalangi, fa olifu ia ena''ö mbua-buami, awö wa''omasi andrö, nifa''ele''ömi, fa''omasimi döinia, me möi ami enoni ni''amoni''ö andrö, awö wa enonira na ami iada''e.[7]', '["Fam 2:2,19; Faigi 10:33 b.t."]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 11, 'Ba omasi ndra''aga, ena''ö dozi ami mi''oroma''ö wa''owölö-ölö andrö, ena''ö a''oi so wa''aro wanötöna andrö, irugi gamozua,', '["Faigi 11:13,7; Yak 5:7"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 12, 'ena''ö böi abe''e dödömi, ena''ö mibe''e famaedo khömi zanema amabu''ula li andrö, ba wamati, ba ba wa''ebolo dödö.[8]', '["Faigi 11:13,7; Yak 5:7"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 13, 'Me ibe''e gamabu''ula li khö Gaberahamo Lowalangi, ba fahölu ia, ba khönia, me lö khönia sebua, nibe''e hölu ena''ö,', '["MozI 22:16,17","Faigi 10:36"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 14, 'imane: "Si ndruhu-ndruhu, ufahowu''ö sibai ndra''ugö, ba a''oi so dania wangoya''ögu ya''ugö."[9]', '["MozI 22:16,17","Faigi 10:36"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 15, 'Ba me no imanö wamologö tödönia, wombaloi, ba no itema gamabu''ula li andrö.[10]', '["MozI 22:16,17","Faigi 10:36"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 16, 'Na niha sa, ba labe''e hölu zebua, ba tebato wamadaö fefu, ba wahölusa andrö, ba wangaro''ö niŵa''ö.[11]', '["MozII 22:11"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 17, 'Andrö ifake wahölusa Lowalangi, me i''oroma''ö sibai na mena''ö, ba zanema amabu''ula li andrö, wa tebai awu''a gera-erania,[12]', '["Luk 1:73","Tit 1:2 TimI 6:12","Faigi 9:3-24","Faigi 4:14; 5:6"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 18, 'ena''ö tobali dombua balö zi lö awu''a, ba zi tebai mofaya Lowalangi, nibe''e famarou dödöda, sabölö-bölö, ya''ita, si no manaŵa da''ö, wa lö taböhöli dötönafö andrö, si so fönada,[13]', '["Luk 1:73","Tit 1:2 TimI 6:12","Faigi 9:3-24","Faigi 4:14; 5:6"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 19, 'si no möi sao nosoda, si no aro, si no abe''e, si rugi göi bakha barö mba''a-ba''a andrö,[14]', '["Luk 1:73","Tit 1:2 TimI 6:12","Faigi 9:3-24","Faigi 4:14; 5:6"]', NULL),
  (3391839, 'NT', 'Heberaio', 6, 20, 'ba zi no möi bakha sowaö-waö salahida, Yesu andrö, me tobali ere sebua ia, dali gamuata Melekhisede andrö, irugi zi lö aetu.[15]', '["Luk 1:73","Tit 1:2 TimI 6:12","Faigi 9:3-24","Faigi 4:14; 5:6"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 1, 'Melekhisede andrö sa, razo Zalema, ere Lowalangi Fondrege Zalaŵa, samaondragö Aberahamo, ba samahowu''ö ya''ia me mangawuli ia, me i''otarai mangalani razo andrö,[1]', '["MozI 14:18 b.t.","Sin 72:1 b.t.; Yes 9:6-7"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 2, 'nibe''e Gaberahamo göi sambua ni''ofulu, fefu, hadia ia, ba no razo ba wa''atulö ua, geluaha döinia, ba aefa da''ö, ba razo Zalema göi, razo wa''ohahau dödö geluaha da''ö,[2]', '["MozI 14:18 b.t.","Sin 72:1 b.t.; Yes 9:6-7"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 3, 'lö ama, lö ina, ba lö tua moroi yaŵa, lö böröta mbaŵania, ba lö fa''aetu nosonia, ba si no mufakhili-khili khö Nono Lowalangi, ba lö tebulö ere ia, lö mamalö-malö.', '["MozI 14:18 b.t.","Sin 72:1 b.t.; Yes 9:6-7"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 4, 'Ba mifaigi, ha wa''ebua da''ö, nibe''e Gaberahamo göi sambua ni''ofulu gahuluania nitutuyu andrö, Aberahamo, furugö andrö.[3]', '["MozI 14:20","MozIV 18:21-32"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 5, 'Ba nono Lewi andrö sa, si tobali ere, ba no mu''oroi''ö, latema zambua ni''ofulu, ba niha sato, ba dalifusöra, dali goroisa andrö, he ŵa''ae ba löwi-löwi Gaberahamo mbörötara.[4]', '["MozI 14:20","MozIV 18:21-32"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 6, 'Ba si tenga ya''ira andrö, ba no ihalö zambua ni''ofulu, khö Gaberahamo, ba no ifahowu''ö zi so amabu''ula li andrö.[5]', '["MozI 12:3; Gal 3:16"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 7, 'Ba lö fulitö, side-ide zi tefahowu''ö khö zebua.', '["MozI 12:3; Gal 3:16"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 8, 'Ba ba da''e, ba niha si mate dania zanema si sambua ni''ofulu, ba ba da''ö, ba no nifaduhu''ö, wa sauri ia.', '["MozI 12:3; Gal 3:16"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 9, 'Ba no hulö ba khö Gaberahamo tefo''ömö göi Lewi, si sambua ni''ofulu, Lewi andrö, sanema si sambua ni''ofulu dania.', '[]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 10, 'No ba löwi-löwi duania so ia na, me ifaondragö ia Melekhisede andrö.', '[]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 11, 'Ba na no so mena''ö wamo''ahonoa ba wa''a''ere nono Lewi andrö (ba da''ö sa tetandrösaigö goroisa andrö, nibe''e khöra) ba hadia guna na, tefataro gere bö''ö dali gamuata Melekhisede, awö wa lö laŵa''ö, dali gamuata Ga''aroni andrö?[6]', '["Faigi 8:7; Gal 2:21"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 12, 'Na tobali wa''a''ere sa, ba lö fulitö tobali göi goroisa.', '[]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 13, 'Ba nitandrösaigö da''ö sa, ba no soi bö''ö, si lö irai möi ere niha, ha niha ia.', '[]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 14, 'Noa sa murongo, wa no mado Yuda Zo''aya ya''ita, mado ba zi lö niŵa''ö Moze, ba gere andrö.[7]', '["MozI 49:10; Mikh 5:2; Yes 11:1; Fam 5:5"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 15, 'Ba no mendrua manö na oroma, na tefataro gere bö''ö, dali wa fakhili-khili ia khö Melekhisede andrö,', '["MozI 49:10; Mikh 5:2; Yes 11:1; Fam 5:5"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 16, 'si tenga balazi oroisa, amakhoita dali nösi niha, si no balazi wa''abölö wa''auri andrö, si lö tebulö.', '["MozI 49:10; Mikh 5:2; Yes 11:1; Fam 5:5"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 17, 'Noa sa tefaduhu''ö ia: "Ere ndra''ugö, irugi zi lö aetu, dali gamuata Melekhisede andrö."[8]', '["Fagi 5:6","Faigi 10:1-4; Rom 8:3","HalZin 13:39"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 18, 'Tewu''ai sa goroisa föna andrö, börö wa no sambö fa''abölö, awö wa lö gunania sa''ae,[9]', '["Fagi 5:6","Faigi 10:1-4; Rom 8:3","HalZin 13:39"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 19, '(lö''ö sa hadia ia nifo''ahonoa goroisa); ba tefatewu wanötöna si sökhi moroi andrö, ba nihatö''öda ya''ita, khö Lowalangi.[10]', '["Fagi 5:6","Faigi 10:1-4; Rom 8:3","HalZin 13:39"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 20, 'Ba ndrohu-ndrohu zi so fahölusa — ba khöra sa, ba lö fahölusa, na tobali ere ira,[11]', '["Faigi 6:17","Sin 110:4","Faigi 8:6; 9:15; 12:24"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 21, 'ba ba khönia, ba so wahölusa, fahölusa zanguma''ö khönia: "No fahölu Zo''aya, ba lö ifuli mangesa dödönia: ere ndra''ugö, irugi zi lö aetu"[12] —', '["Faigi 6:17","Sin 110:4","Faigi 8:6; 9:15; 12:24"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 22, 'ndrohu-ndrohu da''ö göi no tobali we''e-we''e dödö, ba wawu''usa li si sökhi moroi andrö, Yesu.[13]', '["Faigi 6:17","Sin 110:4","Faigi 8:6; 9:15; 12:24"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 23, 'Ba ba khöra, ba ato zi möi ere, börö wa tebai si lö tebulö ira, me mate-mate.', '[]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 24, 'Ba khönia, me si lö tebulö, irugi zi lö aetu, ba so wa''a''ere si lö mamalö-malö.', '[]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 25, 'Andrö göi i''ila ifo''ahonoa wangorifi sangondrasi Lowalangi, nifa''emania, me no si lö mamalö-malö fa''auri, ba wolului khöra fanguma''ö.[14]', '["Faigi 10:14; 9:24; Yoh 14:7; Rom 8:34; YohI 2:1"]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 26, 'Si manö sa zi nangea ere sebua khöda, si no ohau-hau, si lö sala, si lö hadia ia zi lö göna, si no tonia ba niha si so horö, si no yaŵa zorugo,[15]', '["Faigi 4:15","MozIII 16:17; Heb 9:12-26 b.t."]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 27, 'salakha lö ero ma''ökhö mame''e sumange ba horönia ua, ba aefa ö, ba ba horö zato, si mane ere sebua andrö föna; noa sa i''osamuzaigö wolau da''ö, me ibe''e sumange ia.[16]', '["Faigi 4:15","MozIII 16:17; Heb 9:12-26 b.t."]', NULL),
  (3391843, 'NT', 'Heberaio', 7, 28, 'Oroisa sa, ba ifataro ere sebua niha, sambö fa''abölö, ba taroma li wahölusa andrö, me no aefa goroisa, ba ifataro Nono andrö, si no mo''ahonoa, irugi zi lö aetu.[17]', '["Faigi 5:1; 2:9"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 1, 'Da''ö duho ba niŵa''ö andrö: No so khöda gere sebua si manö, si no dumadao ba gambölö daroma wa''asalaŵa andrö, ba zorugo,[1]', '["Faigi 4:14; 1:3","Faigi 9:11"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 2, 'barö mbawania ni''amoni''ö andrö, awö nose si ndruhu andrö, nifazökhi Zo''aya, tenga niha.[2]', '["Faigi 4:14; 1:3","Faigi 9:11"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 3, 'Dozi ere sebua sa, ba ba wame''e ame''ela ba sumange tefataro ira; andrö lö tola lö so khönia göi nibe''e.[3]', '["Faigi 5:1; Efes 5:2","Faigi 10:1; Kol 2:17; MozII 25:40"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 4, 'Ba na ba guli danö so ia ena''ö, ba tenga na i ere ia, me no so zame''e ame''ela andrö, dali goroisa, nibe''e enoni,', '["Faigi 5:1; Efes 5:2","Faigi 10:1; Kol 2:17; MozII 25:40"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 5, 'ba wamaedo zi so ba zorugo andrö, ba lumö-lumönia, si mane niŵa''ö khö Moze, me ifobörö wamazökhi ose andrö, imane: "Faigi, ö''ohia''ö wamaedo andrö, ni''oroma''ö khöu ba hili, wamazökhi fefu, hadia ia."[4]', '["Faigi 5:1; Efes 5:2","Faigi 10:1; Kol 2:17; MozII 25:40"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 6, 'Ba iada''e, ba no si sökhi wamatörö nibe''e ba dangania, ndrohu-ndrohu zi tedou wa''asökhi wawu''usa li andrö, ba zi no sama''ema ia, nitandrösaigö ba gamabu''ula li si sökhi moroi ba zi föföna andrö, wangohonogöi ya''ia.[5]', '["Faigi 7:22"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 7, 'Na lö sinegu sa mena''ö, ba zi föföna andrö, ba lö mena''ö te''alui naha zi sambua.[6]', '["Faigi 7:18-19","Yer 31:31-34","MozII 19:3 b.t.; Yer 15:1 b t.","Hes 36:26 b.t.; Sakh 8:8"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 8, 'Ba itegu, imane khöra: "Hiza, irugi baŵa dania, iŵa''ö So''aya, ba ulau fawu''u li ba ma''uwu Gizeraeli ba ba ma''uwu Yuda, fawu''usa li si bohou;[7]', '["Faigi 7:18-19","Yer 31:31-34","MozII 19:3 b.t.; Yer 15:1 b t.","Hes 36:26 b.t.; Sakh 8:8"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 9, 'tenga dali wawu''usa li andrö, me fawu''u li ndra''o, khö ndra tuara, me luo u''ohe dangara, ba wangeheta ya''ira ba danö Miserayi; noa sa laböhöli wawu''usa li andrö khögu, ba no u''ositengagö göi ira, iŵa''ö So''aya.[8]', '["Faigi 7:18-19","Yer 31:31-34","MozII 19:3 b.t.; Yer 15:1 b t.","Hes 36:26 b.t.; Sakh 8:8"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 10, 'Ba da''ö sa wawu''usa li andrö, na ulau fawu''u li ba ma''uwu Gizeraeli, na no aefa götö da''e, iŵa''ö So''aya: ube''e ba gera-erara goroisa andrö, khögu, ba usura ba dödöra, ba Lowalangira dania ndra''odo, ba banuagu ira.[9]', '["Faigi 7:18-19","Yer 31:31-34","MozII 19:3 b.t.; Yer 15:1 b t.","Hes 36:26 b.t.; Sakh 8:8"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 11, 'Ba lö''ö manö sa''ae ifahaö nawönia banua zamösana, ba lö''ö sa''ae ifahaö dalifusönia, wanguma''ö: Ya''aboto ba dödöu Zo''aya, me no a''oi la''ila ndra''o, he iraono, ba he satua.[10]', '["YohI 2:27","Yes 43:25"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 12, 'Ebolo sa dania dödögu, ba zi lö atulö andrö, khöra, ba lö''ö manö sa''ae itörö tödögu horöra andrö.[11]', '["YohI 2:27","Yes 43:25"]', NULL),
  (3391844, 'NT', 'Heberaio', 8, 13, 'Ba wanguma''ö "si bohou", ba no atua zi föföna, ibe''e; ba hadia zatua, ba hadia zi no numalö döfi, ba no ahatö wa''ataya.', '[]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 1, 'Ba ba zi föföna sa göi, ba so gamakhoita, nitörö, awö ni''amoni''ö andrö, dali ba guli danö.', '["MozII 25","MozII 26:33"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 2, 'Tefazökhi sa nose tanö föna andrö, ba da''ö so naha wandru andrö, awö meza andrö, awö roti nifaigi-faigi andrö, ba töinia, ba ni''amoni''ö;[1]', '["MozII 25","MozII 26:33"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 3, 'ba ba gero mba''a-ba''a si sagörö andrö, ba ose andrö, nifötöi fondrege ni''amoni''ö.[2]', '["MozII 25","MozII 26:33"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 4, 'Ba da''ö so naha wanunu kumöyö andrö, balaki, ba tawöla gamabu''ula li, nifo''uli balaki, ma''afefu, ba bakha ba da''ö, ba migö balaki, nifo''ösi "mana" andrö, ba si''o Ga''aroni andrö, solewiö, ba kara wanura andrö, sura wawu''usa li.[3]', '["MozII 30:34 b.t.; 25:10; 16:33; MozIV 17:10; RazI 8:9"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 5, 'Ba yaŵa da''ö, ba kerubi lakhömi, si lumö''ö lagö-lagö andrö, fameta horö andrö, ba tenga nizara-zara iada''e, wamatunö da''ö.[4]', '["MozII 25:17 b.t."]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 6, 'Da''ö wakakenia; ba ba nose tanö föna andrö, ba möi-möi gere, si lö mamalö-malö, na lahalö-halö halöŵöra,[5]', '["MozIV 18:7","MozII 30:10; MozIII 16"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 7, 'ba ba zi sambua, ba ha samuza zi döfi möi gere sebua, ha ya''ia, ba lö''ö sa, na lö do, ni''ohenia, ba khönia, ba ba lalö zato andrö, ba wa lö mangila watahögö.[6]', '["MozIV 18:7","MozII 30:10; MozIII 16"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 8, 'Da''ö nifa''ele''ö Geheha ni''amoni''ö ba da''ö: lö''ö na mu''oroma''ö lala ba ni''amoni''ö andrö, fatua lö tebulö nose tanö föna andrö,[7]', '["Faigi 9:24,25; 10:19","Faigi 10:1-2","MozIII 11; MozIV 8:7; 19:7"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 9, 'si no mube''e amaedola ba götö da''e, dali wame''e ame''ela ba sumange, si tebai mamo''ahonoa sangai halöŵö andrö, ba dödö andrö;[8]', '["Faigi 9:24,25; 10:19","Faigi 10:1-2","MozIII 11; MozIV 8:7; 19:7"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 10, 'ha ba gö, ba ba nibadu, ba ba ngawalö wanasa aekhu, amakhoita ba nösi niha, nifakhoi, irugi ginötö wangatulö andrö.[9]', '["Faigi 9:24,25; 10:19","Faigi 10:1-2","MozIII 11; MozIV 8:7; 19:7"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 11, 'Ba me so Keriso, ere sebua ba zi sökhi andrö, si so dania, ba no itörö nose si sökhi ba so''ahonoa moroi andrö, si tenga nifazökhi tanga, ya''ia wa tenga moroi ba guli danö andre,[10]', '["Faigi 4:14; Yes 33:20","Faigi 10:10; Yes 45:17; Fam 1:5"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 12, 'ba tenga göi balazi ndro mbiri-biri si matua, ba tenga balazi ndro nono zaŵi, no balazi ndronia, me möi ia ba ni''amoni''ö andrö, no i''osamuzaigö, ba no isöndra wangöhöli si lö aetu.[11]', '["Faigi 4:14; Yes 33:20","Faigi 10:10; Yes 45:17; Fam 1:5"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 13, 'No ihaogö sa''ae nösi do mbiri-biri si matua andrö, ba do zaŵi si matua, ba awu zigelo zaŵi andrö, fanefe zi ra''i-ra''iö andrö,[12]', '["MozIII 16:14-15; MozIV 19","Faigi 10:22; Kol 1:14; YohI 1:7"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 14, 'ba tenga mendrua manö ndro Keriso andrö, si no mame''e sumange, si lö sinegu, ya''ia, khö Lowalangi, balazi Geheha si lö aetu andrö, iheta ba dödömi mbua-bua si mate, ena''ö möi ami enoni Lowalangi sauri![13]', '["MozIII 16:14-15; MozIV 19","Faigi 10:22; Kol 1:14; YohI 1:7"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 15, 'Ba andrö sama''ema ba wawu''usa li si bohou ia, ena''ö latema nikaoni andrö gamabu''ula li andrö, ondröita si lö aetu, na no mutörö wa''amate, ba wangöhöli ba lalö andrö, ba wawu''usa li si föföna.[14]', '["Faigi 7:22; 8:8; TimI 2:5; Rom 3:25"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 16, 'Ba zi so oroisa zi mate sa, ba lö tola lö alua ua wa''amate zangoroi''ö andrö.', '[]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 17, 'Oroisa si manö sa, ba ba wa''amate aro, me no lö gunania fatua auri zangoroi''ö.', '[]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 18, 'Andrö tenga göi si lö do föna, me te''amoni''ö zi föföna andrö.', '[]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 19, 'Me no i''ombakha''ö Moze fefu ngawalö gamakhoita, ba niha sato, fefu, dali goroisa, ba ihalö ndro nono zaŵi andrö, awö ndro mbiri-biri si matua, awö nidanö, ba bu mbiri-biri soyo, ba sufo, ba itefe zura andrö, awö niha sato fefu,[15]', '["MozII 24:3-8","Mat 26:28"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 20, 'ba imane: "Do andre, ba no do ba wawu''usa li andrö, ni''oroi''ö Lowalangi khömi".[16]', '["MozII 24:3-8","Mat 26:28"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391845, 'NT', 'Heberaio', 9, 21, 'Ba ose göi, ba fakake ba halöŵö, fefu, ba itefe göi do andrö, si manö göi.[17]', '["MozIII 8:15,19","MozIII 17:11"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 22, 'Ba arakha fefu, hadia ia, ba do wangehao ya''ia, dali goroisa, ba lö fangefa, na lö aduwa ndro.[18]', '["MozIII 8:15,19","MozIII 17:11"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 23, 'Ba tobali lö tola na tenga da''ö wangehao wamaedo zi so ba zorugo andrö, ba ba khönia, si so ba zorugo, ba lö tola lö falukha zumange si sökhi moroi andrö, wangehao ya''ia.', '["Faigi 9:11; 7:25"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 24, 'Tenga sa ba ni''amoni''ö nifazökhi tanga möi Keriso, tenga ba wamaedo zi duhu, no ba zorugo möi ia, ba wama''ele''ö ya''ia iada''e khö Lowalangi, salahida.[19]', '["Faigi 9:11; 7:25"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 25, 'Ba tenga sa göi ena''ö i''asese''ö wame''e sumange ya''ia, si mane ere sebua andrö, si no ero röfi möi ba ni''amoni''ö andrö molohe do tanö bö''ö.', '["Faigi 9:12"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 26, 'Na si manö ena''ö, ba lö tola lö asese itaögö wamakao andrö, i''otarai mböröta danö andre; ba iada''e, ba no ha samuza to''ele ia, ba gamozua götö danö andre, ba wameta horö, wame''e sumange ya''ia.[20]', '["Faigi 9:12"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 27, 'Ba si mane ba niha, me no muhonogöi khönia, wa samuza mate ia, ba aefa da''ö, ba fanguhuku,[21]', '["Yob 30:23; KorII 5:10","Faigi 10:12 b.t.; Rom 6:10; Mat 26:28"]', NULL),
  (3391845, 'NT', 'Heberaio', 9, 28, 'si manö göi Keriso, me no samuza tebe''e sumange ia, ba wameta horö zato, ba ba zi samuza dania, ba lö horö, na to''ele ia, ba zombalo-mbaloi ya''ia, ba wangorifi.[22]', '["Yob 30:23; KorII 5:10","Faigi 10:12 b.t.; Rom 6:10; Mat 26:28"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 1, 'Me ha lumö-lumö zi sökhi andrö, si so dania, ba goroisa andrö, me tenga si ndruhu famaedo ngawalö andrö, ba lö''ö manö i''ila ifo''ahonoa zangondrasi andrö, ba zumange andrö, si no ero röfi labe''e, si lö aetu-aetu.[1]', '["Faigi 8:5; 9:9; Kol 2:16,17"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 2, 'Tenga labato ena''ö, wame''e sumange, me lö itörö ena''ö tödö zame''e sumange andrö horö, na no muhaogö zamuza?', '["Faigi 8:5; 9:9; Kol 2:16,17"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 3, 'Ba no ero röfi tefasugi ba dödöra horö, ba da''ö.', '["Sin 50:13","Sin 40:7-9","Mikh 6:7","Yoh 4:34","Faigi 7:18","Faigi 9:12,28; 13:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 4, 'Tebai sa iheta horö do zaŵi si matua, ba do mbiri-biri si matua.[2]', '["Sin 50:13","Sin 40:7-9","Mikh 6:7","Yoh 4:34","Faigi 7:18","Faigi 9:12,28; 13:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 5, 'Andrö imane, me möi ia ba guli danö: "Sumange ba ame''ela, ba no lö somasi''ö, ba no öfazökhi khögu mboto;[3]', '["Sin 50:13","Sin 40:7-9","Mikh 6:7","Yoh 4:34","Faigi 7:18","Faigi 9:12,28; 13:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 6, 'sumange nitunu ba sumange fameta horö, ba lö somasi''ö;[4]', '["Sin 50:13","Sin 40:7-9","Mikh 6:7","Yoh 4:34","Faigi 7:18","Faigi 9:12,28; 13:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 7, 'ba umane: "Hiza, sodo dania, ba nga''ölu zura no musura hadia ia, ba khögu: ba wolo''ö somasi''ö, ya''ugö, Lowalangi."[5]', '["Sin 50:13","Sin 40:7-9","Mikh 6:7","Yoh 4:34","Faigi 7:18","Faigi 9:12,28; 13:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 8, 'Me no iŵa''ö mege: "Sumange ba ame''ela, ba sumange nitunu, ba sumange fameta horö, ba lö ba dödöu, lö somasi''ö",', '["Sin 50:13","Sin 40:7-9","Mikh 6:7","Yoh 4:34","Faigi 7:18","Faigi 9:12,28; 13:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 9, 'nibe''e, dali goroisa, ba awena imane: "Hiza, sodo dania, ba wolo''ö somasi''ö." Si sambalö iwu''ai, ena''ö ifataro zi sambalö.[6]', '["Sin 50:13","Sin 40:7-9","Mikh 6:7","Yoh 4:34","Faigi 7:18","Faigi 9:12,28; 13:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 10, 'Ba zomasi ia andrö, ba da''ö te''amoni''ö ita, ba wame''e sumange boto Yesu Keriso andrö, ni''osamuzaigö.[7]', '["Sin 50:13","Sin 40:7-9","Mikh 6:7","Yoh 4:34","Faigi 7:18","Faigi 9:12,28; 13:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 11, 'Ere andrö sa fefu, ba ero ma''ökhö so ira, ba wangai-ngai halöŵöra, ba ba wangasese''ö fame''e sumange andrö, ha da''öda''ö, si tebai manö mameta horö[8]', '["Faigi 10:1","Faigi 1:3","KorI 15:25"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 12, 'Ba ya''ia, ba ha sambalö nibe''enia sumange, ba horö andrö, ba no mudadao ia ba gambölö Lowalangi, si lö mamalö-malö,[9]', '["Faigi 10:1","Faigi 1:3","KorI 15:25"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 13, 'ba wombalo-mbaloi sa''ae, "irege tebe''e tou barö gahenia zi fa''udu khönia".[10]', '["Faigi 10:1","Faigi 1:3","KorI 15:25"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 14, 'Ba wame''e sumange si samuza andrö sa, ba no ifo''ahonoa ni''amoni''ö andrö, irugi zi lö aetu.[11]', '["Faigi 9:26 b.t.","Yer 31:31 b.t."]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 15, 'Ba ifaduhu''ö göi khöda Eheha ni''amoni''ö.', '["Faigi 9:26 b.t.","Yer 31:31 b.t."]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 16, 'Me no aefa iŵa''ö: "Da''ö wawu''usa li andrö, na ulau fawu''u li khöra, na no aefa götö da''e!" iŵa''ö So''aya: "Oroisagu ube''e ba dödöra, ba ba gera-erara usura ia,[12]', '["Faigi 9:26 b.t.","Yer 31:31 b.t."]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 17, 'ba lö''ö sa''ae dania itörö tödögu horöra ba olalöŵara andrö."', '["Faigi 9:26 b.t.","Yer 31:31 b.t."]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 18, 'Ba ba zi so fangefa da''ö, ba lö''ö sa''ae göi ame''ela, ba horö andrö.', '["Faigi 9:26 b.t.","Yer 31:31 b.t."]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 19, 'Ba me no so khöda wa lö aiŵö, ya''ami ira talifusö, ba we''amöi bakha ba ni''amoni''ö andrö, börö ndro Yesu andrö,[13]', '["Rom 5:2","Faigi 6:19-20; Yoh 14:6","Faigi 3:6","Faigi 4:16; 9:13,14; YohI 1:7","Hes 36:25"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 20, 'ni''amoni''önia khöda, lala si bohou, lala ba wa''auri, sanörö ba''a-ba''a andrö, ya''ia nösinia andrö,[14]', '["Rom 5:2","Faigi 6:19-20; Yoh 14:6","Faigi 3:6","Faigi 4:16; 9:13,14; YohI 1:7","Hes 36:25"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 21, 'ba me no so khöda gere sebua, ba nomo Lowalangi andrö,[15]', '["Rom 5:2","Faigi 6:19-20; Yoh 14:6","Faigi 3:6","Faigi 4:16; 9:13,14; YohI 1:7","Hes 36:25"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 22, 'ba data''ondrasi, ya si ndruhu dödöda, ya''alösu lö mangiwa wamatida, ya''aefa dödö sanegu ya''ita, me no mutefe dödöda,[16]', '["Rom 5:2","Faigi 6:19-20; Yoh 14:6","Faigi 3:6","Faigi 4:16; 9:13,14; YohI 1:7","Hes 36:25"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 23, 'ba ena''ö nisasai nösida idanö sohahau; böi taböhöli wamaduhu''ö tötönafö andrö, böi mangiwa; lö''ö sa faröi zamabu''u andrö.[17]', '["Rom 5:2","Faigi 6:19-20; Yoh 14:6","Faigi 3:6","Faigi 4:16; 9:13,14; YohI 1:7","Hes 36:25"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 24, 'Ba datafaoma tafaigi nawöda, ba wamarou tödö ba wa''omasi andrö, ba ba mbua-bua si sökhi.[18]', '["Faigi 13:1,21","Kol 3:16; Yak 5:8-9","Faigi 6:4 b.t.","MozV 32:22; Sef 1:18"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 25, 'Ba böi taböhöli we''amöi ba migu khöda, si mane nifolau-lau danö bö''ö ösa, tafarou dödö nawöda, ba mendrua manö, me itugu mi''ila, ahatö mbaŵa andrö.[19]', '["Faigi 13:1,21","Kol 3:16; Yak 5:8-9","Faigi 6:4 b.t.","MozV 32:22; Sef 1:18"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 26, 'Na ta''odödögö wamazökhi horö sa, na no tasöndra wa''aboto ba dödö zi duhu andrö, ba lö''ö sa''ae si tosai sumange, fameta horö,[20]', '["Faigi 13:1,21","Kol 3:16; Yak 5:8-9","Faigi 6:4 b.t.","MozV 32:22; Sef 1:18"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 27, 'ha fombalo-mbaloi huku, sata''u ita, awö hola-hola galitö andrö, si manga dania zi fa''udu andrö.[21]', '["Faigi 13:1,21","Kol 3:16; Yak 5:8-9","Faigi 6:4 b.t.","MozV 32:22; Sef 1:18"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 28, 'Na so zangositengagö oroisa andrö khö Moze, ba lö fa''ahakhö dödö, mate ia, ba zi darua, ba ma si datölu, si so ba mbörö;[22]', '["MozIV 15:30 b.t.; MozV 17:7","Faigi 12:25; KorI 11:25,29; Mat 12:31"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 29, 'ba he wisa ba dödömi, tenga mendrua manö wotu, si göna zi hundragö Ono Lowalangi andrö, ba na ba dödönia si lö guna ndro andrö, ba wawu''usa li andrö, ba ni''amoni''ö ya''ami, ba na no i''osiwawöi Geheha fa''ebua dödö andrö?[23]', '["MozIV 15:30 b.t.; MozV 17:7","Faigi 12:25; KorI 11:25,29; Mat 12:31"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 30, 'Noa sa ta''ila zi no manguma''ö: "Khögu wolau balö, ya''o zanulöni", ba so zui, ba: "Ihuku dania mbanuania So''aya."[24]', '["MozV 32:35,36","Faigi 12:29"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 31, 'Sata''u ita na ba danga Lowalangi sauri aekhu ita.[25]', '["MozV 32:35,36","Faigi 12:29"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 32, 'Ba mitörö-törö tödömi mbaŵa föna andrö, me oya mitaögö fasöndrata famakao andrö, me no muhagaini ami;[26]', '["TesI 2:14","KorI 4:9","Faigi 13:2; Mat 5:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 33, 'so, ba tebe''e mai-mai mifaigi ami, wango''aya ya''ami, ba famakao ya''ami, ba so, ba tobali awö zi göna si manö ami,[27]', '["TesI 2:14","KorI 4:9","Faigi 13:2; Mat 5:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 34, 'Noa sa göi mihakhösi tödö nikuru, ba no mitaha, na terabu zi so khömi, lö sabu dödömi, me no aboto ba dödömi, so khömi zi sökhi moroi andrö, si lö tebulö.[28]', '["TesI 2:14","KorI 4:9","Faigi 13:2; Mat 5:12"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 35, 'Ba böi miböhöli wa''abe''e dödö andrö khömi, nifoluo sebua dania.[29]', '["Faigi 12:2-3","Faigi 12:1; Luk 21:19","Hab 2:3-4; Fam 22:12","Rom 1:17","TesI 3:3; FetI 1:9"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 36, 'Fa''ebolo dödö sa zoguna khömi, ena''ö mi''o''ö zomasi Lowalangi, ba ena''ö misöndra gamabu''ula li andrö.[30]', '["Faigi 12:2-3","Faigi 12:1; Luk 21:19","Hab 2:3-4; Fam 22:12","Rom 1:17","TesI 3:3; FetI 1:9"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 37, '"Hatö sa ma''ifu sibai tö, ba so zi möi andrö, lö i''aragö ia.[31]', '["Faigi 12:2-3","Faigi 12:1; Luk 21:19","Hab 2:3-4; Fam 22:12","Rom 1:17","TesI 3:3; FetI 1:9"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 38, 'Ba satulö tödö andrö khögu, ba moroi ba wamati auri ia dania, ba na awuwu ia, ba lö omasi dödögu ia."[32]', '["Faigi 12:2-3","Faigi 12:1; Luk 21:19","Hab 2:3-4; Fam 22:12","Rom 1:17","TesI 3:3; FetI 1:9"]', NULL),
  (3391846, 'NT', 'Heberaio', 10, 39, 'Ba ya''ita, ba tenga sawuwu, ba wa''atekiko, no samati ita, ba wangorifi noso.[33]', '["Faigi 12:2-3","Faigi 12:1; Luk 21:19","Hab 2:3-4; Fam 22:12","Rom 1:17","TesI 3:3; FetI 1:9"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 1, 'Ba famati andrö, ba no fa''a''ro dödö ba nidöna-döna andrö, fa''afaduhu dödö ba ngawalö, hadia ia, si lö oroma.[1]', '["Rom 8:24-25; KorII 4:18","Rom 1:20; Sin 33:6; Yoh 1:3"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 2, 'Ba khönia sa lasöndra satua föna, wa tefaduhu''ö ira.', '["Rom 8:24-25; KorII 4:18","Rom 1:20; Sin 33:6; Yoh 1:3"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 3, 'Moroi ba wamati aboto ba dödöda, wa no taroma li Lowalangi wamazökhi danö''a, wa no tobali tenga moroi ba zoroma tumbu zoroma andrö,[2]', '["Rom 8:24-25; KorII 4:18","Rom 1:20; Sin 33:6; Yoh 1:3"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 4, 'Moroi ba wamati, wa no sökhi zumange andrö, nibe''e Habeli khö Lowalangi, moroi ba nibe''e Ka''ino, ba moroi ba da''ö tefaduhu''ö ia, wa satulö ia, me ifaduhu''ö game''elania Lowalangi, ba moroi ba da''ö göi, wa muhede ia na, he ŵa''ae no mate ia.[3]', '["MozI 4:4 b.t.; Mat 23:35"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 5, 'Moroi ba wamati, wa teheta Khenoki, fa lö i''ila wa''amate, ba lö lasöndra ia, me no iheta ia Lowalangi; föna wangeheta ya''ia sa''ae tefaduhu''ö ia, wa no somasi Lowalangi ia.[4]', '["MozI 5:24"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 6, 'Ba na lö famati, ba tebai i''omasi''ö niha Lowalangi: Sangondrasi Lowalangi ena''ö ba lö''ö sa tola lö mamati ia, so Lowalangi, ba ifoluo zangalui ya''ia andrö.', '["MozI 5:24"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 7, 'Moroi ba wamati, wa ilau nowo andrö Noakhi, ba wangorifi si samba omo ya''ira, me no ibokai khönia Lowalangi zi lö oroma na; i''ata''ufi; ba da''ö i''etu''ö huku niha guli danö, ba tobali sanema fa''atulö dödö ba wamati ia.[5]', '["MozI 6:9-22; FetII 2:5; Rom 3:22"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 8, 'Moroi ba wamati, wa molo''ö Gaberahamo, me tekaoni ia, wa awu''a ia, wa isaŵa danö, nibe''e ondröita mitou dania khönia, ba mofanö ia, he lö''ö na i''ila, heza isaŵa.[6]', '["MozI 12:1-4; Rom 4:1 b.t."]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 9, 'Moroi ba wamati, wa si fatewu ia, ba danö amabu''ula li andrö, ba danö niha bö''ö ua, ose nahiania, ba si manö göi khö Giza''aki ba khö Yakobo, awönia sanema amabu''ula li andrö göi.[7]', '["MozI 12:7 b.t.; 15:13","Faigi 12:22; 13:14"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 10, 'Ibaze-baze''ö sa mbanua andrö, saro dane-dane, ba zi no möi tuka ba sotomo Lowalangi.[8]', '["MozI 12:7 b.t.; 15:13","Faigi 12:22; 13:14"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 11, 'Moroi ba wamati göi, wa isöndra wa''abölö Sara andrö, ba wamobörö nga''ötö, ba lö lai wa no numalö ndröfinia, me no faduhu dödönia, ba zamabu''u andrö.[9]', '["MozI 18:10; 21;2,7; Rom 4:20,21"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 12, 'Andrö göi moma''uwu zi ha samösa andrö, ba si no mate, taŵa''ö, timba ndröfi ba mbanua yaŵa wa''ato, ba timba nene ba mbewe nasi andrö, si tebai la''erai ngawua.[10]', '["Rom 4:19; MozI 15:5","MozI 47:9; Sin 39:13","MozII 3:6"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 13, 'Ba ba wa''amate da''ö fefu, ba dali wamati, lö si falukha ira amabu''ula li andrö, ha moroi ba zaröu la''ila, ba la''owai, ba la''ombakha''ö, tome ira ba si fatewu, ba guli danö andre.[11]', '["Rom 4:19; MozI 15:5","MozI 47:9; Sin 39:13","MozII 3:6"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 14, 'Sanguma''ö da''ö sa, ba la''ombakha''ö, wa la''alui zi ndruhu mbanuara.', '["Rom 4:19; MozI 15:5","MozI 47:9; Sin 39:13","MozII 3:6"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 15, 'Ba na da''ö niŵa''öra, ba zi otarai ira, ba fakhamö mena''ö, mangawuli ira.', '["Rom 4:19; MozI 15:5","MozI 47:9; Sin 39:13","MozII 3:6"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 16, 'Ba me tenga da''ö, ba si sökhi ni''aluira, ya''ia zi so ba zorugo. Andrö wa lö aila khöra Lowalangi, na labe''e töinia Lowalangira; noa sa itaru''ö khöra mbanua.[12]', '["Rom 4:19; MozI 15:5","MozI 47:9; Sin 39:13","MozII 3:6"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 17, 'Moroi ba wamati, wa ibe''e sumange Giza''aki andrö Aberahamo, me tetandraigö ia, ononia si ha sambua andrö ibe''e sumange, ya''ia si no manema amabu''ula li andrö.[13]', '["MozI 22:1 b.t.","MozI 21:12; Rom 9:7","Rom 4:17"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 18, 'ba zi no muŵa''ö: "Ba khö Giza''aki tefotöi khöu nga''ötö."[14]', '["MozI 22:1 b.t.","MozI 21:12; Rom 9:7","Rom 4:17"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 19, 'Da''ö dödönia, he moroi ba ngai zi mate, ba i''ila isusugi Lowalangi, moroi ba da''ö göi itema mangawuli ia, me ilulu.[15]', '["MozI 22:1 b.t.","MozI 21:12; Rom 9:7","Rom 4:17"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 20, 'Moroi ba wamati, wa ifahowu''ö ndra Yakobo Ezau Iza''aki, ba zi falukha ira dania.[16]', '["MozI 27:28; 39"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 21, 'Moroi ba wamati, wa faoma ifahowu''ö nono Yosefo andrö Yakobo, me arakha mate ia, ba mangalulu ia faudu högö zi''onia.[17]', '["MozI 48:1-20; 47:31"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 22, 'Moroi ba wamati, wa itörö li Yosefo wa''awu''a Ndraono Gizeraeli andrö, me mate ia, ba ibe''e goroisa, ba wolohe botonia.[18]', '["MozI 50:24-25"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 23, 'Moroi ba wamati, wa labini''ö Moze ira inania, me sawena tumbu, tölu waŵa wa''ara, me la''ila, si sökhi nono andrö, ba lö la''ata''ufi goroisa razo andrö.[19]', '["MozII 2:2"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 24, 'Moroi ba wamati, wa lö ba dödö Moze, na laŵa''ö ono nono Wara''o alawe ia, me no ebua ia,[20]', '["MozII 2:10,11"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 25, 'awö wa abölö omasi ia, itaögö wamakao, awö mbanua Lowalangi, moroi isöndra wa''omuso dödö ba horö, si lö arara;', '["MozII 2:10,11"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 26, 'ba dödönia, ebua hare ba wango''aya andrö, khö Keriso, moroi ba gana''a Miserayi andrö; famoluo dania sa ifaigi.', '["MozII 2:10,11"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 27, 'Moroi ba wamati, wa iröi danö Miserayi, wa lö i''ata''ufi wönu razo andrö; i''olembai sa''ae zi lö oroma andrö, hulö na no i''ila.[21]', '["MozII 12:41; 10:28"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 28, 'Moroi ba wamati, wa ilau wasa andrö, awö wamaduwa do andrö, fa böi ibabaya ira samunu ono si a''a andrö.[22]', '["MozII 12:3-14"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 29, 'Moroi ba wamati, wa latörö nasi soyo andrö, hulö na tanö sabe''e, ba zalömö Ndrawa Miserayi, me latandraigö göi.[23]', '["MozII 14:16-31"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 30, 'Moroi ba wamati, wa adudu göli kara andrö, ba Yerikho, me no fitu bongi lafasui.[24]', '["Yos 6:1-20"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 31, 'Moroi ba wamati, wa lö tekiko Rakhaba andrö, sohorö andrö, awö zi lö molo''ö, me no ifa''amöi yomo khönia zamauze andrö, me no ihaogö khöra.[25]', '["Yos 2:1 b.t.; 6:17 b.t."]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 32, 'Ba hadia niŵa''ögu na ena''ö? Lö''ö sa fakhamö, na udunö-dunö ena''ö, hadia ia ba khö Gideono andrö, ba ba khö Mbaraki, ba ba khö Zimesono, ba ba khö Yefita ba ba khö Dawido ba ba khö Zamueli andrö, ba ba zama''ele''ö andrö.[26]', '["Sanguhuk 6:11; 4:6; 13:24; 11:1; Sin 78:70 b.t.; SamI 3:20; HalZin 3:24","SamII 8:1-14; SamI 12:3-4; Dan 6:22","Dan 3:25 b.t.; RazI 19:1-3; RazII 20:7; Sanguhuk 15:8,15; 16,28; 7:13,22"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 33, 'Si no molaŵa banua bö''ö, ba wamati, si no mamalua satulö, si no manema amabu''ula li, si no mondruhö bawa zingo,[27]', '["Sanguhuk 6:11; 4:6; 13:24; 11:1; Sin 78:70 b.t.; SamI 3:20; HalZin 3:24","SamII 8:1-14; SamI 12:3-4; Dan 6:22","Dan 3:25 b.t.; RazI 19:1-3; RazII 20:7; Sanguhuk 15:8,15; 16,28; 7:13,22"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 34, 'si no mamunu fa''abölö galitö, si no aefa ba mbawa zi''öli, si no mogamö fa''abölö, he si lö abölö, mböröta, si no abölö ba wanuwö, si no manimba sabölö niha bö''ö.[28]', '["Sanguhuk 6:11; 4:6; 13:24; 11:1; Sin 78:70 b.t.; SamI 3:20; HalZin 3:24","SamII 8:1-14; SamI 12:3-4; Dan 6:22","Dan 3:25 b.t.; RazI 19:1-3; RazII 20:7; Sanguhuk 15:8,15; 16,28; 7:13,22"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 35, 'No ba wemaoso, moroi ba ngai zi mate, latema mangawuli zi mate khöra ira alawe; ba so niforöfa, sanimba fangefa, ena''ö lakhamö wemaoso si sökhi,[29]', '["RazI 17:18 b.t.; RazII 4:32 b.t.","MozI 39:20; Yer 20:2","RazI 21:13; 19:10; RazII 1:8; Yak 5:10; HalZin 7:52"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 36, 'ba so zi no falukha fango''aya ba famözi-mözi, awö mböbö, ba awö gurunga;[30]', '["RazI 17:18 b.t.; RazII 4:32 b.t.","MozI 39:20; Yer 20:2","RazI 21:13; 19:10; RazII 1:8; Yak 5:10; HalZin 7:52"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 37, 'no latebu kara ira, no lafakao, no lasila, mate ira nibunu si''öli, mowaö-waö ira, uli mbiri-biri nukhara, ba ma uli nambi, no falukha ira wa''ambö, ba fa''afökhö, ba famakao.[31]', '["RazI 17:18 b.t.; RazII 4:32 b.t.","MozI 39:20; Yer 20:2","RazI 21:13; 19:10; RazII 1:8; Yak 5:10; HalZin 7:52"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 38, 'Ya''ira andrö, si tenga si nangea awö niha guli danö mena''ö; ba danö si mate misa elungu-lungu ira, ba ba hili misa, ba ba dögi narö gara, ba ba zo''arö hili.[32]', '["RazI 18:4; 19:4","Faigi 8:6"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 39, 'Ba da''ö fefu, ba lö nikhamöra amabu''ula li andrö, he ŵa''ae no nifaduhu''ö ira, moroi ba wamati andrö;', '["RazI 18:4; 19:4","Faigi 8:6"]', NULL),
  (3391847, 'NT', 'Heberaio', 11, 40, 'me no ihönagö ifaigi khoda zi sökhi Lowalangi, ena''ö böi mo''ahonoa ira lö ya''ita.[33]', '["RazI 18:4; 19:4","Faigi 8:6"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 1, 'Ba andrö, ya''ita göi, me no tefasui ita lawuo samaduhu''ö andrö, ba datatou''ö tou noro dödö andrö, fefu, awö horö andrö samasui ya''ita, ba data''anau''ö gölöda wagohisa, ba watandrasa töla andrö, si so fönada,[1]', '["KorI 9:24-27; Efes 4:22; Faigi 10:36","Faigi 2:10-13; Fil 2:8; Fam 3:21","Yoh 15:20"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 2, 'Ba tafaigi zolohe andrö, ba samo''ahonoa famati, Yesu, si no manaha röfa andrö, salahi wa''omuso dödö andrö, si no so fönania, si no mangositengagö fa''aila, ba si no mudadao ba gambölö dadaoma Lowalangi andrö.[2]', '["KorI 9:24-27; Efes 4:22; Faigi 10:36","Faigi 2:10-13; Fil 2:8; Fam 3:21","Yoh 15:20"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 3, 'Mitörö-törö sa''ae tödömi zi no manaha tödönia, na lamanö wamadaö khönia niha si so horö, fa böi atage ami, ba fa böi alulu dödömi.[3]', '["KorI 9:24-27; Efes 4:22; Faigi 10:36","Faigi 2:10-13; Fil 2:8; Fam 3:21","Yoh 15:20"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 4, 'Lö''ö na sondrugi do fanimbami horö andrö, ba wasöndrata khönia,[4]', '["KorI 10:13","Amaed 3:11-12; Yoh 5:17","Fam 3:19"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 5, 'ba no olifu ami wondrara dödö andrö, sihede khömi, amaedola wehede ba ndraono, imane: "He onogu! böi zi lö ba dödöu wotu andrö, khö Zo''aya, ba böi abu dödöu, na i''otu''ö ndra''ugö;[5]', '["KorI 10:13","Amaed 3:11-12; Yoh 5:17","Fam 3:19"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 6, 'somasi Zo''aya sa, ba i''otu''ö, ba ibago-bago fefu ndraono nihalönia khönia."[6]', '["KorI 10:13","Amaed 3:11-12; Yoh 5:17","Fam 3:19"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 7, 'Mitaha wotu; tödö Lowalangi khömi, ba no hulö ba ndraono; heza sa so ndraono, si lö i''otu''ö ama?', '["Amaed 10:17"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 8, 'Ba na lö te''otu''ö ami, si no falukha ira fefu, ba no ono horö ami, ba tenga si ndruhu nono.', '["Amaed 10:17"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 9, 'Ba no ae sangotu''ö ya''ita ndra amada, niha, ba no ta''ata''ufi ira, ba tenga mendrua manö möi ita barö mbawa Nama noso andrö, ena''ö auri ita?[7]', '["Amaed 10:17"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 10, 'Ba ya''ira sa, ba si lö arara, ha uga bongi, la''otu''ö ita, dali dödöra, ba ya''ia, ba ena''ö moguna, ena''ö möi khöda göi wa''ohau-haunia andrö.[8]', '["KorI 11:32","Yoh 16:20 b.t.; Yes 26:16 b.t.; Yak 1:12; 3:18"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 11, 'Fefu ngawalö wotu sa, ba götö iada''e, ba tenga fa''omuso dödö, taŵa''ö, ha fa''abu dödö, ba dania, ba sohahau dödö lua-luania, fa''atulö dödö, nifa''emania ba zi no mufamaha ba khönia andrö. [9]', '["KorI 11:32","Yoh 16:20 b.t.; Yes 26:16 b.t.; Yak 1:12; 3:18"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 12, 'Andrö mifuli mi''abe''e''ö danga, si no adada, ba balöduhi, si no atage andrö;[10]', '["Yes 35:3"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 13, 'ba mifaigi zadölö lala gahemi, fa lö ahole zi no ombuyu-mbuyu, ena''ö abe''e ato.', '["Yes 35:3"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3391848, 'NT', 'Heberaio', 12, 14, 'Migohi wa''atulö, ba niha fefu, ba fangohau-hau andrö; lö''ö sa sangila So''aya dania, niha, na lö da''ö.[11]', '["Sin 34:15; Rom 12:18; Mat 5:8-9","KorII 6:1; MozV 29:18"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 15, 'Ba mifaigi, fa böi falukha zi toröi furi, ba wa''ebua dödö andrö, fa böi molewiö ŵa''a safeto, ba wamoborö famakuyu, fa böi ato zi göna si ra''i-ra''iö.[12]', '["Sin 34:15; Rom 12:18; Mat 5:8-9","KorII 6:1; MozV 29:18"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 16, 'Böi ta''ila zohorö, ba ma si lö ngaroro, si mane Ezau andrö, samawa fa''asia''ania, ha samuza femanga mböli;[13]', '["Faigi 13:4; MozI 25:29 b.t.","MozI 27:30 b.t."]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 17, 'noa sa mirongo: dania göi, me edöna itema howu-howu andrö, ba tetibo ia; lö''ö sa isöndra lala wamalalini era-era, he ŵa''ae no mowöi daŵa hörönia, wangalui ya''ia.[14]', '["Faigi 13:4; MozI 25:29 b.t.","MozI 27:30 b.t."]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 18, 'Lö''ö sa nirugimi hili nibabaya andrö, sihola-hola andrö, ba lö nirugimi salu, ba sogömi-gömi, ba fe''ugu-ugu mbanua, si fao angi,[15]', '["MozII 19:17 b.t.; MozV 4:11-12","MozII 20:18 b.t.","MozII 19:12"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 19, 'ba li dorofe, ba li zihede andrö, me mangandrö zamondrongo andrö, böi sa''ae yamuhede khöra;[16]', '["MozII 19:17 b.t.; MozV 4:11-12","MozII 20:18 b.t.","MozII 19:12"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 20, 'me tebai lataha ni''oroi''ö andrö: "Ba he ahe zaliŵa-liŵa ba danö zanguhundragö hili, ba nibunu, nitebu kara;"[17]', '["MozII 19:17 b.t.; MozV 4:11-12","MozII 20:18 b.t.","MozII 19:12"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 21, 'wa''ata''ura zoroma andrö, tobali imane Moze: "Oi so wa''ata''ugu, manizi-nizi ndra''o!"', '["MozII 19:17 b.t.; MozV 4:11-12","MozII 20:18 b.t.","MozII 19:12"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 22, 'Ba no mirugi hili Ziona andrö, ba banua Lowalangi sauri andrö, Yeruzalema andrö, si yaŵa, ba zorugo, awö ngahönö mala''ika,[18]', '["Fam 14:1; 3:12; Yes 24:23; Gal 4:26; Dan 7:10; Yuda 14","Yak 1:18; Fam 14:4; Luk 10:20","Faigi 9:15; FetI 1:2"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 23, 'ba owuloa andrö, banua zi a''a, nisura töi ba zorugo, ba Lowalangi, sanguhuku fefu, ba niha ira, ba bekhu zatulö andrö si no mo''ahonoa,[19]', '["Fam 14:1; 3:12; Yes 24:23; Gal 4:26; Dan 7:10; Yuda 14","Yak 1:18; Fam 14:4; Luk 10:20","Faigi 9:15; FetI 1:2"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 24, 'ba sama''ema andrö, ba wawu''usa li si bohou, Yesu, ba do fanefe andrö, si sökhi fehede, moroi ba ndro Habeli.[20]', '["Fam 14:1; 3:12; Yes 24:23; Gal 4:26; Dan 7:10; Yuda 14","Yak 1:18; Fam 14:4; Luk 10:20","Faigi 9:15; FetI 1:2"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 25, 'Mifaigi, fa böi mitimba zihede andrö. Na tebai sa aefa da''ö, sanimba sanguma''ö li ba guli danö andre, ba tenga mendrua manö ita, na ta''erogö zihede moroi ba zorugo andrö?[21]', '["Faigi 2:1-3; 10:29","Sin 68:9; Hag 2:6,21; Mat 24:29","Fam 20:11; 21:1; KorII 5:1"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 26, 'Me luo da''ö ifaheu danö linia, ba iada''e, ba no ifabu''u linia, imane: "Samuza tö dania ufaheu, tenga ha tanö, banua si yaŵa göi".[22]', '["Faigi 2:1-3; 10:29","Sin 68:9; Hag 2:6,21; Mat 24:29","Fam 20:11; 21:1; KorII 5:1"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 27, 'Ba si "samuza tö" andrö, ba ba wamalalini nifaheu andrö, nifazökhi andrö, faekhu, ena''ö si lö tebulö zi tebai humede.[23]', '["Faigi 2:1-3; 10:29","Sin 68:9; Hag 2:6,21; Mat 24:29","Fam 20:11; 21:1; KorII 5:1"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 28, 'Andrö, me no möi khöda mbanua si tebai humeu-heu, ba data''andrö saoha gölö; da''ö zomasi Lowalangi, fe''amöida enoninia, yafao wangera-ngera ba fa''ata''u;[24]', '["Dan 2:44; 7:14,18; Kol 1:12; Sin 2:11-12","MozV 4:24"]', NULL),
  (3391848, 'NT', 'Heberaio', 12, 29, 'alitö si manga-manga hadia ia sa Lowalangida andrö.[25]', '["Dan 2:44; 7:14,18; Kol 1:12; Sin 2:11-12","MozV 4:24"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 1, 'Fangomasi''ö talifusö andrö, andrö, ba böi yatebulö.[1]', '["Rom 12:10","Rom 12:13; MozI 18:2 b.t.; 19:1 b.t.","Faigi 10:34; Mat 25:36; KorI 12:26; Rom 12:15"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 2, 'Böi mi''olifugö ami, fa böi abua gölömi ba dome; so sa ösa zi no mame''e gö mala''ika, si lö la''ila, ba zi manö.[2]', '["Rom 12:10","Rom 12:13; MozI 18:2 b.t.; 19:1 b.t.","Faigi 10:34; Mat 25:36; KorI 12:26; Rom 12:15"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 3, 'Mitörö-törö tödömi nikuru andrö, me no awöra nikuru ami, awö nifakao andrö, me si so ba mboto göi ami.[3]', '["Rom 12:10","Rom 12:13; MozI 18:2 b.t.; 19:1 b.t.","Faigi 10:34; Mat 25:36; KorI 12:26; Rom 12:15"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 4, 'Dozi sa, ba ndramu''onangegö warongasa, ba ba wa''orudu andrö, ba böi yafabaya hadia ia; ihuku sa Lowalangi zohorö andrö, awö zohoröni donga zodonga.[4]', '["Efes 5:5; TesI 4:3-6"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 5, 'Böi fatewu ba gera-erami wa''omasi gana''a, ya''abönö khömi zi ho so. Noa sa ya''ia zanguma''ö: "Lö''ö manö faröido khöu, balö''ö manö u''ositengagö ndra''ugö."[5]', '["TimI 6:6-10; Yos 1:5; MozV 31:8","Sin 118:6"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 6, 'Tobali tola abe''e dödöda, wanguma''ö: "So''aya zanolo ya''o, lö ata''u ndra''o. Hadia nilau niha khögu?"[6]', '["TimI 6:6-10; Yos 1:5; MozV 31:8","Sin 118:6"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 7, 'Mitörö-törö tödömi zolohe ya''ami andrö, si no mangombakha khömi taroma li Lowalangi; aekhula lalara mitöngöni, ba mi''ohia''ö wamatira andrö.[7]', '["Faigi 6:12; TesI 2:13; Fil 3:17","Fam 1:8; 17:18"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 8, 'Yesu Keriso andrö, ba ya''i-ya''ia manö, he menewi, ba he ma''ökhö, ba he irugi zi lö aetu.[8]', '["Faigi 6:12; TesI 2:13; Fil 3:17","Fam 1:8; 17:18"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 9, 'Böi mibe''e nidönisi ami, ba wamahaö si no oya ngawalö, si no fabö''ö; si sökhi sa na moroi ba wa''ahakhö dödö te''abe''e''ö dödö, böi ba gö, ba zi lö hare zanörö da''ö.[9]', '["Efes 4:14; Kol 2:20 b.t.; Rom 14:17"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 10, 'No so khöda naha wame''e sumange, ba zi lö tola manga zangai halöŵö andrö, ba nose andrö.', '["MozIII 16:27","Faigi 10:10; Mat 21:39; Yoh 19:17"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 11, 'Baero golombaseŵa sa tetunu nösi zaliŵa-liŵa ba danö andrö, ni''ohe gere sebua do ba ni''amoni''ö andrö fameta horö.[10]', '["MozIII 16:27","Faigi 10:10; Mat 21:39; Yoh 19:17"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 12, 'Andrö göi baero mbawa göli itaha wamakao Yesu, ena''ö i''amoni''ö mbanua, donia andrö.[11]', '["MozIII 16:27","Faigi 10:10; Mat 21:39; Yoh 19:17"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 14, 'Ba me si manö, ba damöi ita khönia, baero golombaseŵa, ba datalu''i wango''aya ya''ia andrö.[12]', '["FetI 4:14","Faigi 11:10.13-16; Fil 3:20"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 15, 'Ba datafafa''ema''ö khönia zumange fanuno, khö Lowalangi, böi mamalö-malö; ya''ia mbua-bua mbewe, sangombakha töinia.[14]', '["Sin 50:14; Efes 5:20"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 16, 'Böi mi''olifugö ami, ba wanolo si numana, ba ba dolo-tolo andrö; somasi Lowalangi sa zumange si manö.[15]', '["KorII 9:12-13","TesI 5:12 b.t.; Hes 33:7 b.t."]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 17, 'Mifondrondrongo li zolohe ya''ami andrö, ba mi''o''ö, ya''ira sa zanaro tödömi andrö, khöra tezofu-zofu li dania, ena''ö omuso dödöra wangombakha, ba ena''ö böi mangarö-ngarö ira; tenga sa sohare ami da''ö.[16]', '["KorII 9:12-13","TesI 5:12 b.t.; Hes 33:7 b.t."]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 18, 'Mi''angandrö salahima, noa sa faduhu dödöma, wa lö iteguga tödöma, me si sökhi manö zedöna matörö, fefu, hadia ia.[17]', '["KorII 1:11-12"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 19, 'Andrö mendrua manö ufarou dödömi, ba wolau da''ö, ena''ö alio tefuli ndra''o khömi.', '["KorII 1:11-12"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 20, 'Ba Lowalangi wa''ohahau dödö andrö, si no molohe yaŵa, moroi ba ngai zi mate, kubalo mbiri-biri andrö, sebua, balazi ndro wawu''usa li andrö, si lö aetu, Yesu andrö, So''aya ya''ita,[18]', '["Rom 16:20; Hes 34:23","Fil 2:13; TesI 5:23; Gal 1:5"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 21, 'ya''ia yamuhaogö ami, ba zi sökhi andrö fefu, ba wolo''ö somasi ia, yamu''a''asogö ba dödöda zomasi ia famaigi, moroi khö Yesu Keriso, ya khönia zumange, irugi zi lö aetu. Yaduhu.[19]', '["Rom 16:20; Hes 34:23","Fil 2:13; TesI 5:23; Gal 1:5"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 22, 'Ba u''andrö khömi, ya''ami ira talifusö, böi mitimba daroma li wamarou tödö andrö, lö''ö sa oya-oya nisuragu khömi.', '["TesI 3:2","Fam 22:21"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 23, 'Böi zi lö mirongo, wa no aefa dalifusöda Timoteo andrö, awönia dania ndra''o, wamaigi ya''ami, na alio möi ia.[20]', '["TesI 3:2","Fam 22:21"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 24, 'Mi''owai zolohe ya''ami andrö, fefu, awö ni''amoni''ö, fefu. La''owai ami si so ba Gitalia.', '["TesI 3:2","Fam 22:21"]', NULL),
  (3391849, 'NT', 'Heberaio', 13, 25, 'Yafalukha ami fefu wa''ebua dödö.[21]', '["TesI 3:2","Fam 22:21"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 1, 'Yakobo zanura da''e, enoni Lowalangi andrö ba enoni Yesu Keriso, ba zi felendrua tua andrö, sizaewe misa; ya''ahowu![1]', '["Gal 1:19; Yud 1; FetI 1:1"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 2, 'Mibe''e fa''omuso dödö manö, ya''ami ira talifusögu, na oya itörö ami fanandraigö, hadia ia ngawalö;[2]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 3, 'me no aboto ba dödömi, na no mutandraigö wamatimi, ba fanaha tödö lua-lua.[3]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 4, 'Ba famo''ahonoa dania wanaha tödö andrö, ena''ö mo''ahonoa ami, si lö sala, ba böi ambö hadia ia.[4]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 5, 'Ba na so ba khömi zambö fa''atua-tua, ba yamu''andrö khö Lowalangi, same''e manö, fefu gofu ha niha zangandrö, lö ihede-hede''ö; ba tebe''e khönia.[5]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 6, 'Ba yafaduhu dödönia, ba wangandrö, böi mangiwa; sangiwa tödö sa, ba no hulö ndrulu nasi, nifadaulu-daulu nangi, nifangörö-ngörö misa.[6]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 7, 'Böi sa yamuŵa''ö tödönia niha si manö, so dania hadia ia zinemania khö Zo''aya; niha si dua tödö,', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 8, 'samangörö-ngörö manö nilaunia, fefu.', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 9, 'Ba talifusö, side-ide, ba yamusuno ia, ba wa''asalaŵania;[7]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 10, 'ba so''ana''a, ba yamusuno ia ba wa''ide-idenia, me no lala mbowo ndru''u dania lalania.[8]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 11, 'Tumbu luo, so wa''aukhu zino, ba aleu ndru''u andrö, ba bowonia, ba atoru, ba taya wa''asökhinia; si manö göi dania wa''aleu zo''ana''a, ba lalania andrö.[9]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 12, 'Ya''ahowu niha, sanaögö fanandraigö andrö, na no faduhu dödö dania khönia, ba itema dakula fa''auri andrö, nifabu''u Zo''aya ba zangomasi''ö ya''ia.[10]', '["FetI 4:13; Mat 5:11,12; Ayati 12","Rom 5:3,4","Heb 10:36","Faigi 3:17; Mat 7:7","Faigi 5:15,16; Mat 7:7","Luk 1:47,52","KorII 12:9; FetI 1:24","Sin 90:5,6","Ayati 2; Faigi 5:11; Yob 5:17 b.t.; TimII 4:8; Fam 2:10"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 13, 'Böi yamuŵa''ö niha, na tetandraigö ia: Moroi khö Lowalangi, wa tetandraigö ndra''odo: Lowalangi, ba tebai tetandraigö ba zi lö sökhi, ba ya''ia, ba lö itandraigö niha.', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 14, 'Ba dozi nitandraigö, ba ba wangisö dödöra tezöbi-zöbi ira ba tedönisi.', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 15, 'Awena dania, na no abeto wangisö andrö, ba i''adonogö horö, ba horö andrö, na no mufalua, ba i''adonogö wa''amate.[11]', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 16, 'Böi elungu ami, ya''ami ira talifusögu, somasi ndra''o.', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 17, 'Ha sambalö ame''ela si sökhi, ba ha sambalö buala so''ahonoa zi otarai moroi si yaŵa, moroi khö Nama zihaga andrö, mitou, ba zi lö fa''atobali, ba he fa''atelumö-lumö.[12]', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 18, 'Nilau dödönia, wa no i''adonogö ita, moroi ba daroma li si duhu andrö, ena''ö böröta nifazökhinia ita.[13]', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 19, 'Ya''aboto ba dödömi, ya''ami ira talifusögu, somasi ndra''o: dozi niha, ba ndramu''alio''ö wamondrongo, böi ndramufahulö wehede, ba böi alio wofönu.[14]', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 20, 'Fönu niha andrö sa, ba lö ilau zatulö, wamaigi Lowalangi.[15]', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 21, 'Andrö miböhöli fefu, hadia ia, zi ra''i-ra''iö andrö, awö fefu walösökhi andrö, si no fahöna, ba mibologö dödömi wamonaha taroma li andrö, nitanö ba dödömi fangorifi nosomi.[16]', '["MozI 3:6; Rom 6:23","Yoh 3:27; Sin 139:12; Rom 11:29","FetI 1:23","Sangomb 5:1; Amaed 17:27","Amaed 29:22; Efes 4:26","Kol 3:8; KorI 15:1,2"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 22, 'Ba mi''o''ö daroma li andrö, ba böi ha famondrongo manö, wolimo ya''ami.[17]', '["Faigi 2:14; Mat 7:21; Luk 11:28","Faigi 2:12; Rom 8:2; Yoh 13:17","Faigi 3:2 b.t.; FetI 3:10","Yes 1:17; Mat 25:36"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 23, 'Na so zamondrongo taroma li andrö, ba na lö i''o''ö, ba no hulö niha samaigi bawania ba zörömi;', '["Faigi 2:14; Mat 7:21; Luk 11:28","Faigi 2:12; Rom 8:2; Yoh 13:17","Faigi 3:2 b.t.; FetI 3:10","Yes 1:17; Mat 25:36"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 24, 'na no ifaigi ia, ba mofanö sa''ae ia, ba i''anema''ö olifu, he wisa khala-khalania.', '["Faigi 2:14; Mat 7:21; Luk 11:28","Faigi 2:12; Rom 8:2; Yoh 13:17","Faigi 3:2 b.t.; FetI 3:10","Yes 1:17; Mat 25:36"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 25, 'Ba si no monehegö oroisa fangefa andrö, si no mo''ahonoa, ba si lö tebulö ba da''ö, si tenga ha samondrongo, solifu; na solo''ö göi ia: da''ö zodöŵa-döŵa tödö dania, ba wolaunia andrö.[18]', '["Faigi 2:14; Mat 7:21; Luk 11:28","Faigi 2:12; Rom 8:2; Yoh 13:17","Faigi 3:2 b.t.; FetI 3:10","Yes 1:17; Mat 25:36"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 26, 'Na so zanguma''ö tödönia, samosumange Lowalangi ia, ba na lö itaha lelania, na ilimo dödönia, ba no faya wamosumangenia Lowalangi.[19]', '["Faigi 2:14; Mat 7:21; Luk 11:28","Faigi 2:12; Rom 8:2; Yoh 13:17","Faigi 3:2 b.t.; FetI 3:10","Yes 1:17; Mat 25:36"]', NULL),
  (3443178, 'NT', 'Yakobo', 1, 27, 'Da''ö zi sökhi wamosumange Lowalangi, si lö si fabaya hadia ia, wamaigi Lowalangi Ama: na möi ita mutolo zi lö ama, si lö ina, awö zi no mate donga ba wa''abu dödöra, ba na tafaigi, fa böi göna ita si ra ira''iö andrö, ba niha guli danö.[20]', '["Faigi 2:14; Mat 7:21; Luk 11:28","Faigi 2:12; Rom 8:2; Yoh 13:17","Faigi 3:2 b.t.; FetI 3:10","Yes 1:17; Mat 25:36"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 1, 'Ya''ami ira talifusögu, böi mi''ebua''ö dödömi zambuana, ba wamati andrö, khö Zo''aya lakhömi andrö khöda, Yesu Keriso.', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 2, 'Na so ena''ö zi möi ba gowuloami niha solaeduru balaki, sobaru baru luo, ba na so göi zi möi, si numana, sobaru si lö sökhi-sökhi;', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 3, 'ba mifaigi ena''ö zobaru baru luo andrö, ba mimane ena''ö: Dadao ba da''e, ya''ugö faigi zi sökhi nahau; ba na mimane ba zi numana andrö: Ya''ugö, ba ba da''ö iagö, zizio, ba ma tou dadao, tou mbaku-baku gahegu andre!', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 4, 'ba tenga no mifonaha wanufa dödömi, ba tenga no sanguhuku, si so era-era si lö sökhi, ami?', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 5, 'Mifondrondrongo, ya''ami ira talifusögu, somasi ndra''o! Tenga no itutuyu Lowalangi zi numana ba guli danö andre, ena''ö fahöna khöra wamati andrö, ba ena''ö sanema ondröita ira, banua andrö, nifabu''unia ba zangomasi''ö ya''ia andrö? Ba ya''ami, ba no mi''ositengagö zi numana andrö[1]', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 6, 'Hadia, tenga so''ana''a andrö zamalangögö ya''ami, ba tenga ya''ira zanöbi ya''ami ba rafe?', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 7, 'Tenga ya''ira zango''aya töi si sökhi andrö, si no mube''e börö döimi andrö?[2]', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 8, 'Ba na mi''o''ö goroisa razo andrö, si so ba zura: "Omasi''ö zahatö khöu, si mane fa''omasiu ndra''ugö," ba no si sökhi milau.[3]', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 9, 'Ba na mi''ebua''ö dödömi zambuana, ba mamazökhi horö ami, ba ifaduhu''ö khömi oroisa, wa no sanawö ami.[4]', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 10, 'Na so sa ena''ö zolo''ö oroisa, ma''afefu, ba na isawö zambalö, ba no mo''ömö ia ba goroisa ma''afefu.[5]', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 11, 'Sanguma''ö: "Böi ohorö!" da''ö göi zanguma''ö: "Böi ange''e." Ba he lö mohorö''ö, ba na mange''e''ö, ba no tobali sanawö oroisa ndra''ugö.[6]', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 12, 'Mimanö wehede, ba mimanö wolau, si mane niha nihuku ba goroisa fangefa andrö dania.[7]', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 13, 'Lö''ö sa fa''ahakhö dödö ba wanguhuku si lö mangahakhösi tödönia; ba i''ositengagö wanguhuku fa''ahakhö dödö andrö.[8]', '["KorI 1:26","FetI 4:14","MozIII 19:18; Gal 5:14; Mat 22:36 b.t.","MozIII 19:15","MozV 27:26; Mat 5:19","MozII 20:13,14","Faigi 1:25","Mat 25:34 b.t., 41 b.t.; Mat 5:7"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 14, 'Hadia guna, ya''ami ira talifusögu, na so zanguma''ö, so khönia wamati, ba na lö bua-bua? Hadia, i''ila, i''orifi ia famati andrö?[9]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 15, 'Ba na so dalifusö matua, ba ma talifusö alawe, si lö nukha ba sambö balazo, ndrege zi ma''ökhö;', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 16, 'ba na so ba khömi zanguma''ö khöra: Mi''ae''e, ya''ohahau dödömi, mi''oleu, ba mi''abusoi''ö ami! ba na lö mibe''e zoguna fangehao mbotora, ba hadia guna?[10]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 17, 'Si manö göi wamati andrö, na lö bua-bua; no amaedola zi lö noso.[11]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 18, 'Ba ma so zanguma''ö: khöu wamati, ba khögu mbua-bua. Oroma''ö khögu wamatimö andrö, si lö bua-bua, ba ba mbua-buagu u''oroma''ö khöu wamati andrö.[12]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 19, 'Hadia, no faduhu dödöu, wa ha sambua Lowalangi? Si sökhi da''ö: faduhu göi dödö mbekhu ba da''ö, ba humokha mbura.[13]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 20, 'Ba hadia, omasi''ö ö''ila, ya''ugö niha si lö tödö, wa lö guna wamati si lö bua-bua?', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 21, 'Tuada Aberahamo andrö, hadia, tenga moroi ba mbua-bua isöndra wangatulö, me ibe''e sumange nononia Iza''aki andrö?[14]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 22, 'Ö''ila ba da''ö, itolo ba mbua-bua andrö famati, ba moroi ba mbua-bua andrö tefo''ahonoa wamati,[15]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 23, 'ba itörö zi so ba zura andrö, imane: "Ba mamati Gaberahamo khö Lowalangi, ba tebe''e fa''atulö dödönia da''ö, ba si fahuwu khö Lowalangi döinia".[16]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 24, 'Mi''ila ba da''ö, ba mbua-bua isöndra wangatulö niha, ba tenga ha ba wamati.', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 25, 'Si manö göi Rakhaba andrö, sohorö andrö, hadia, tenga ba mbua-bua isöndra wangatulö, me ifa''amöi yomo khönia zinenge andrö, ba me ifatörö ba lala bö''ö, wamofanö?[17]', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443326, 'NT', 'Yakobo', 2, 26, 'Hulö si mane boto sa, si lö fa''auri, na lö noso, si manö göi wamati andrö, lö fa''auri, na lö bua-bua.', '["Faigi 1:22; Mat 7:21; Rom 3:31; Tit 3:8","Luk 3:11","Faigi 2:26; Gal 5:6; KorI 13:2","Mat 7:20","Mar 1:24; HalZin 19:15","MozI 22:9–12; Heb 11:17","Rom 4:3; FetII 1:5–10","MozI 15:6; Nga''ötII 20:7; Yes 41:8","Yos 2:1 b.t.; Heb 11:31"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 1, 'Böi ato ami zamahaö, ya''ami ira talifusögu; noa sa mi''ila tedou dania wa''abe''e huku, nifatörö khöda.[1]', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 2, 'Asese sa sala ita, dozi ita. Na so zi lö sala ba li, ba no niha si no mo''ahonoa ia, sangila mamatöro botonia ma''asambua.[2]', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 3, 'Na tabe''e ba mbawa kudo zi''öli andrö, fa la''o''ö khöda, ba tafatörö mbotora, ma''asambua.[3]', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 4, 'Hiza göi, nowo andrö, ha wa''ebua ia, ba he ŵa''ae angi sabe''e wamofanö, ba tebali''ö zui amuri side-ide sibai andrö, heza nilau dödö zamatörö ya''ia.', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 5, 'Si manö göi lela andrö, ndroto-ndroto side-ide ia, ba no ebua hokha. Hiza wa''ide-ide galitö, ba ha wa''ebua gatua itunu.[4]', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 6, 'Alitö lela andrö, fa''ebua nösi guli danö ma''afefu wa''ebua zi lö atulö andrö, khönia, no föna ndroto-ndroto bö''ö lela andrö, lö sökhi mbotoda ma''asambua ibe''e, ifohola roda wa''auri andrö, ba nifohola narako ia.[5]', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 7, 'Telaŵa sa fefu ngawalö gutu ndru''u, ba fofo, ba ulö, ba saliŵa-liŵa ba nasi andrö; noa sa ilaŵa niha,', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3443328, 'NT', 'Yakobo', 3, 8, 'ba lela andrö; noa sa ilaŵa niha, ba lela andrö, ba lö sangila molaŵa ya''ia niha; si lö sökhi andrö, si lö ahono-hono, si no fahöna langu famunu.[6]', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 9, 'Fanuno Zo''aya, Ama, ia khöda, ba fangelifi niha, nibe''e famaedo Lowalangi.[7]', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 10, 'Ha sambua mbawa, ba faoma i''otarai ia, he fanuno, ba he fangelifi. Böi si manö, ya''ami ira talifusögu!', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 11, 'Hadia, ha sambua gumbu, ba faoma alua khönia, he sami, ba he ladu?', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 12, 'He wisa, ya''ami ira talifusögu, i''owua mbua falo töla marafala, ba i''owua marafala töla nagu? Ba tebai alua nidanö sami ba ladu.[8]', '["Mat 23:8; Hes 33:7,8","Sin 19:13","Sin 32:9","Faigi 1:26","Amaed 16:27; Mat 15:11,18","Sin 140:4","MozI 9:6","Mat 7:16"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 13, 'Ha niha ba khömi zatua-tua ba sotödö? Yamu''oroma''ö ba wa''atulö wolo''önia mbua-buania ba wa''ebolo dödö, ba wa''atua-tua andrö.[9]', '["Amaed 15:2; 16:21; Efes 5:15","Efes 4:31","KorI 2:6 b.t.; 3:19","Gal 5:15; KorI 3:3","TimI 1:5; Amaed 12:1","Yes 32:17; Fil 1:11"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 14, 'Ba na so ba dödömi wa''afökhö ba fasosota, ba böi misuno ami, ba böi milau waya, wamini''ö si duhu.[10]', '["Amaed 15:2; 16:21; Efes 5:15","Efes 4:31","KorI 2:6 b.t.; 3:19","Gal 5:15; KorI 3:3","TimI 1:5; Amaed 12:1","Yes 32:17; Fil 1:11"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 15, 'Tenga fa''atua-tua si otorai moroi si yaŵa da''ö, moroi ba guli danö da''ö moroi ba dödö manö, moroi ba mbekhu.[11]', '["Amaed 15:2; 16:21; Efes 5:15","Efes 4:31","KorI 2:6 b.t.; 3:19","Gal 5:15; KorI 3:3","TimI 1:5; Amaed 12:1","Yes 32:17; Fil 1:11"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 16, 'Ba zi so fa''afökhö dödö sa, ba fasosota, ba da''ö so göi wamakuyu, awö ngawalö wolau si lö sökhi, fefu.[12]', '["Amaed 15:2; 16:21; Efes 5:15","Efes 4:31","KorI 2:6 b.t.; 3:19","Gal 5:15; KorI 3:3","TimI 1:5; Amaed 12:1","Yes 32:17; Fil 1:11"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 17, 'Ba fa''atua-tua andrö, si otarai moroi si yaŵa, ba si oföna khönia, ba no ohau-hau, ba fanete da''ö, ba lö fasosota, ebolo dödö, i''o''ö li, no fahöna khönia wa''ahakhö dödö ba bua-bua i sökhi, lö i''ebua''ö dödö zambuana, lö mamini tödö.[13]', '["Amaed 15:2; 16:21; Efes 5:15","Efes 4:31","KorI 2:6 b.t.; 3:19","Gal 5:15; KorI 3:3","TimI 1:5; Amaed 12:1","Yes 32:17; Fil 1:11"]', NULL),
  (3443328, 'NT', 'Yakobo', 3, 18, 'Ba si lö fasosota zamazaewe bua wa''atulö dödö andrö, ba wa''atulö.[14]', '["Amaed 15:2; 16:21; Efes 5:15","Efes 4:31","KorI 2:6 b.t.; 3:19","Gal 5:15; KorI 3:3","TimI 1:5; Amaed 12:1","Yes 32:17; Fil 1:11"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 1, 'He moroi wa lö atulö ba khömi, ba he moroi wagua-guasa andrö? Tenga moroi ba wasöndrata wangisömi andrö, ba nösimi?[1]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 2, 'Mangisö ami, ba lö manema ami; mange''e ami ba afökhö dödömi, ba tebai mikhamö; fasöndra ami ba manuwö ba lö khömi, me lö mangandrö ami.', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 3, 'Mangandrö ami, ba lö mitema, me si lö sökhi wangandrömi andrö; ena''ö m''a ia, ba wangisömi andrö.[2]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 4, 'Ya''ami sohorö, ira matua ba ira alawe, hadia lö mi''ila wa no si fa''udu ba Lowalangi wahuwusa ba niha guli danö? Tobali na so zomasi fahuwu ba niha guli danö, ba ibali''ö si fa''udu khö Lowalangi ia.[3]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 5, 'Ma miwai faya-faya niŵa''ö ba zura andrö? Solohu Geheha andrö, nifonahania ba dödöda;[4]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 6, 'ba ebua sa atö na wa''ebua dödö andrö, ni''a''asogönia; andrö imane: "Itimba Lowalangi zi fayaŵa andrö, ba i''ebua''ö dödönia ba zangide-ide''ö ya''ira".[5]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 7, 'Ba mi''ae barö mbawa Lowalangi. Mitimba Gafökha, ba moloi ia, iröi ami.[6]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 8, 'Mi''ondrasi Lowalangi, ba i''ondrasi ami! Mihaogö danga, ya''ami si so horö! ba mi''ohau-hau''ö dödö ya''ami si dua tödö![7]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 9, 'Ya''afökhö khömi wamakaomi, ba mi''abusi tödö ba mi''ege-ege! Yatobali fa''abu dödö wa''ikimi andrö, ba yatobali fa''aila wa''omuso dödömi andrö![8]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 10, 'Mi''ide-ide''ö ami föna Zo''aya, ba ibali''ö salaŵa ami.[9]', '["Rom 7:23","Sin 66:18","Mat 6:24; YohI 2:15; Rom 8:7","Yes 42:8","Amaed 29:23; Luk 1:52","FetI 5:6,8,9","Nga''ötII 15:2; Yes 1:16","Faigi 5:1; Mat 5:4","Mat 18:4; 23:12"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 11, 'Böi mitandraŵaisi nawömi, ya''ami ira talifusö! Na so zanandraŵaisi talifusönia, ba ma sanguhuku talifusönia, ba itandraŵaisi goroisa, ba ihuku goroisa. Ba na öhuku goroisa, ba tenga solo''ö oroisa ndra''ugö, no sanguhuku ya''ia ndra''ugö.[10]', '["Sin 15:1–3; Mat 7:1; Yak 1:25","Mat 10:28; Rom 14:4"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 12, 'Ha samösa zame''e oroisa, ba sanguhuku, sangila mangorifi ba sangila mamakiko. Ba ya''ugö, ha niha ndra''ugö, sanguhuku awönia?[11]', '["Sin 15:1–3; Mat 7:1; Yak 1:25","Mat 10:28; Rom 14:4"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 13, 'Ba mifondrondrongo, ya''ami sanguma''ö: Ma''ökhö, ba ma mahemolu mofanöga, masaŵa mbanua heza, ba döfi dania ndra''aga ba da''ö, maniaga ba mangalui hare;[12]', '["Luk 12:18 b.t.","Amaed 27:1; Sin 144:4","HalZin 18:21","KorI 1:31","Luk 12:47"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 14, 'si lo mangila he wisa mahemolu. Hadia sa nosomi andrö? Zau-zau ami, si lö arara oroma, ba taya sa''ae.[13]', '["Luk 12:18 b.t.","Amaed 27:1; Sin 144:4","HalZin 18:21","KorI 1:31","Luk 12:47"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 15, 'Ba mimane ena''ö: Na omasi Lowalangi ba na so noso, ba malau da''ö, ba ma da''ö.[14]', '["Luk 12:18 b.t.","Amaed 27:1; Sin 144:4","HalZin 18:21","KorI 1:31","Luk 12:47"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 16, 'Ba iya''e, ba misuno ami, ba wayaŵasami andrö. Fefu wayaŵasa si manö, ba no si lö sökhi.[15]', '["Luk 12:18 b.t.","Amaed 27:1; Sin 144:4","HalZin 18:21","KorI 1:31","Luk 12:47"]', NULL),
  (3443456, 'NT', 'Yakobo', 4, 17, 'Ba na so zangila molau si sökhi, ba na lö ilau, ba horö da''ö khönia.[16]', '["Luk 12:18 b.t.","Amaed 27:1; Sin 144:4","HalZin 18:21","KorI 1:31","Luk 12:47"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 1, 'Ba mifondrondrongo, ya''ami so''ana''a, mi''ege-ege ba mi''angarö-ngarö, ba wa''afökhö andrö sanörö ya''ami dania.[1]', '["Amaed 11:28; Luk 6:24; TimI 6:9","Mat 6:19","MozV 24:14,15","Luk 16:19,25"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 2, 'No obou nibaya-bayami, ba no i''a hama nukhami andrö.', '["Amaed 11:28; Luk 6:24; TimI 6:9","Mat 6:19","MozV 24:14,15","Luk 16:19,25"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 3, 'Ana''ami andrö ba firömi, ba no i''a howu, ba tobali famaduhu''ö dödömi howunia andrö, ba i''a nösimi, hulö galitö. No mihöna girö-girö ba luo safuria andre.[2]', '["Amaed 11:28; Luk 6:24; TimI 6:9","Mat 6:19","MozV 24:14,15","Luk 16:19,25"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 4, 'Hiza, mu''ao sibai luo zohalöŵö andrö, nitahami andrö, luo zohalöŵö si no möi mamasi nowimi, ba no irugi dögi dalinga Zo''aya ngahönö fe''ao zamasi andrö.[3]', '["Amaed 11:28; Luk 6:24; TimI 6:9","Mat 6:19","MozV 24:14,15","Luk 16:19,25"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 5, 'No miforege wemanga, ba no mi''abusoi''ö ami, ba guli danö andre no mibula dödömi, ba luo wamahö.[4]', '["Amaed 11:28; Luk 6:24; TimI 6:9","Mat 6:19","MozV 24:14,15","Luk 16:19,25"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 6, 'No mi''etu''ö huku zatulö andrö, ba no mibunu; lö ilaŵa ami.', '["Amaed 11:28; Luk 6:24; TimI 6:9","Mat 6:19","MozV 24:14,15","Luk 16:19,25"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 7, 'Ba mibologö dödömi, wombase''ö, ya''ami ira talifusö, irugi wa''aso Zo''aya. Hiza, ibase''ö mbua danö, sebua böli andrö, sonowi, wamologö tödönia ba khönia, irege itema deu si föföna andrö ba teu safuria.[5]', '["Tit 2:13; Hos 6:3","Nga''ötII 15:7; FetI 4:7","Mat 24:33","Heb 11:36 b.t.; Mat 5:12","Faigi 1:12; Yob 1:21; 42:10; MozII 34:6 b.t."]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 8, 'Ba ya''ami göi, ba mibologö dödömi, mibalo-baloi, mi''a''aro''ö dödö, noa sa ahatö wa''aso Zo''aya andrö.[6]', '["Tit 2:13; Hos 6:3","Nga''ötII 15:7; FetI 4:7","Mat 24:33","Heb 11:36 b.t.; Mat 5:12","Faigi 1:12; Yob 1:21; 42:10; MozII 34:6 b.t."]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 9, 'Böi mi''angarö-ngarö ba khö nawömi, ya''ami ira talifusö, fa böi tehuku ami; hiza, so moroi sa zanguhuku andrö.[7]', '["Tit 2:13; Hos 6:3","Nga''ötII 15:7; FetI 4:7","Mat 24:33","Heb 11:36 b.t.; Mat 5:12","Faigi 1:12; Yob 1:21; 42:10; MozII 34:6 b.t."]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 10, 'Mihalö famaedo ba wanaha famakao ba ba wamologö tödö andrö zama''ele''ö andrö, si no fahuhuo ba döi Zo''aya, ya''ami ira talifusö.[8]', '["Tit 2:13; Hos 6:3","Nga''ötII 15:7; FetI 4:7","Mat 24:33","Heb 11:36 b.t.; Mat 5:12","Faigi 1:12; Yob 1:21; 42:10; MozII 34:6 b.t."]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 11, 'Hiza, tafahowu-howu''ö zi no manaha tödöra. No mirongo wanaha Yobi andrö tödönia, ba lua-lua Zo''aya, ba no mirongo; me no sahakhö sibai tödö Zo''aya ba sogolö tödö.[9]', '["Tit 2:13; Hos 6:3","Nga''ötII 15:7; FetI 4:7","Mat 24:33","Heb 11:36 b.t.; Mat 5:12","Faigi 1:12; Yob 1:21; 42:10; MozII 34:6 b.t."]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 12, 'Ba si oföna sibai, ya''ami ira talifusögu, ba böi mi''ae ba hölu, böi mibe''e hölu zorugo, ba böi göi tanö, ba ma hadia ia mbö''önia. Da''ö khömi: Ya''ia, na ya''ia, ba: lö''ö, na lö''ö, fa lö göna ami huku.[10]', '["Mat 5:34–37"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 13, 'Na so ba khömi zi göna famakao, ba yamangandrö, na so zohahau tödö, ba yamanunö.[11]', '["Sin 50:15; Efes 5:19","Mar 6:13","Mar 16:18; Mat 9:2","Sin 145:18,19; Amaed 15:29","HalZin 14:15; Luk 4:25; Fam 11:6","RazI 18:42 b.t.","Mat 18:15","Amaed 10:12; FetI 4:8"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 14, 'Na so zofökhö ba khömi, ba yamufahede''ö ba zatua mbanua, ba ndramangandrö ba khönia, ba ndramubayoini ia fanikha, ba döi Zo''aya;[12]', '["Sin 50:15; Efes 5:19","Mar 6:13","Mar 16:18; Mat 9:2","Sin 145:18,19; Amaed 15:29","HalZin 14:15; Luk 4:25; Fam 11:6","RazI 18:42 b.t.","Mat 18:15","Amaed 10:12; FetI 4:8"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 15, 'ba i''orifi dania zofökhö andrö fangandrö andrö, soroi ba wamati, ba i''abe''e''ö So''aya, ba na so horö, nifazökhinia, ba te''efa''ö khönia.[13]', '["Sin 50:15; Efes 5:19","Mar 6:13","Mar 16:18; Mat 9:2","Sin 145:18,19; Amaed 15:29","HalZin 14:15; Luk 4:25; Fam 11:6","RazI 18:42 b.t.","Mat 18:15","Amaed 10:12; FetI 4:8"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 16, 'Ba faoma mi''ombakha''ö khö nawömi horömi, ba faoma mi''angandrö, salahi nawömi, ena''ö tefadöhö wökhömi; abölö sibai wangandrö niha satulö, na moroi ba dödö.[14]', '["Sin 50:15; Efes 5:19","Mar 6:13","Mar 16:18; Mat 9:2","Sin 145:18,19; Amaed 15:29","HalZin 14:15; Luk 4:25; Fam 11:6","RazI 18:42 b.t.","Mat 18:15","Amaed 10:12; FetI 4:8"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 17, 'Eliya andrö, ba no niha, si mane amuatada gamuatania, ba mangandrö ia, moroi si''aikö ba dödö, fa böi moteu, ba lö teu ba danö, medölu fakhe a matonga.[15]', '["Sin 50:15; Efes 5:19","Mar 6:13","Mar 16:18; Mat 9:2","Sin 145:18,19; Amaed 15:29","HalZin 14:15; Luk 4:25; Fam 11:6","RazI 18:42 b.t.","Mat 18:15","Amaed 10:12; FetI 4:8"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 18, 'Ba ifuli mangandrö, ba so deu, moroi yaŵa ba mbanua, ba mowua danö.[16]', '["Sin 50:15; Efes 5:19","Mar 6:13","Mar 16:18; Mat 9:2","Sin 145:18,19; Amaed 15:29","HalZin 14:15; Luk 4:25; Fam 11:6","RazI 18:42 b.t.","Mat 18:15","Amaed 10:12; FetI 4:8"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 19, 'He ya''ami ira talifusögu! Na so ba khömi zi no elungu, si no mondröi si duhu, ba na so zolohe ya''ia mangawuli,[17]', '["Sin 50:15; Efes 5:19","Mar 6:13","Mar 16:18; Mat 9:2","Sin 145:18,19; Amaed 15:29","HalZin 14:15; Luk 4:25; Fam 11:6","RazI 18:42 b.t.","Mat 18:15","Amaed 10:12; FetI 4:8"]', NULL),
  (3443463, 'NT', 'Yakobo', 5, 20, 'ba böi zi lö aboto ba dödö da''ö: Solohe mangawuli samazökhi horö, moroi ba lala elungua andrö, ba i''efa''ö nosonia ba wa''amate ba oya ibalugö horö.[18]', '["Sin 50:15; Efes 5:19","Mar 6:13","Mar 16:18; Mat 9:2","Sin 145:18,19; Amaed 15:29","HalZin 14:15; Luk 4:25; Fam 11:6","RazI 18:42 b.t.","Mat 18:15","Amaed 10:12; FetI 4:8"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 1, 'Fetero zanura da''e, sinenge Yesu Keriso andrö, khömi si fatewu, nitutuyu andrö, sizaewe ba Wondro, ba ba Galatia, ba ba Gafadokia, ba ba Azia, ba ba Mbitinia,[1]', '["Yoh 7:35; Yak 1:1","Faigi 2:9; Rom 8:29; Heb 12:24; FetII 1:2"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 2, 'dali wangohonogöi Lowalangi Ama, föna, ba wangehao Geheha andrö, ba wolo''ö, ba ba wanefe ya''ami do Yesu Keriso andrö. Yafahöna khömi wa''ebua dödö ba fa''ohahau dödö.[2]', '["Yoh 7:35; Yak 1:1","Faigi 2:9; Rom 8:29; Heb 12:24; FetII 1:2"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 3, 'Nisuno Lowalangi, Ama Zo''aya ya''ita, Yesu Keriso, si no mamuli mangadonogö ya''ita, dali wa''ahakhö dödönia andrö, si no fahöna, ba wanötöna andrö, si tenga faya, moroi ba wemaoso Yesu Keriso andrö, moroi ba ngai zi mate,[3]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 4, 'ba wanema ondröita andrö si lö taya, si lö si lö göna, si lö ariri, ni''irö''ö khömi ba zorugo;[4]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 5, 'khömi nirorogö fa''abölö Lowalangi andrö, balazi wamati, ba wanema fa''auri si lö aetu andrö, si no awai, ba wangoroma''ö ya''ia, na luo safuria andrö.[5]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 6, 'Ba da''ö owua-wua dödömi, ya''ami, sabu tödö iada''e ma''ifu, na moguna, ba wa''oya ngawalö wanandraigö andrö.[6]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 7, 'Ena''ö tetandraigö wamatimi, ba ena''ö tesöndra, ebua mbölinia, moroi ba mbalaki, si tekiko sa atö, nitandraigö ba galitö, ena''ö falukha ami tesuno ami, ba mo akhömi ami, ba tefosumange ami, ba wa''ato''ele Yesu Keriso andrö,[7]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 8, 'somasi ami, he ŵa''ae lö mirai falukha, si faduhu dödömi iada''e, he ŵa''ae lö mi''ila ia, ba no owua-wua dödömi ba da''ö; tebai laŵa''ö ha wa''abölö-bölö wa''omuso dödö andrö, si no si ndruhu,[8]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 9, 'me misöndra wozu wamatimi andrö, fangorifi noso andrö.[9]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 10, 'Fangorifi andrö nifatou-tou zama''ele''ö andrö, da''ö ni''alu-aluira tödöra, sama''ele''ö fa''ebua dödö andrö, si falukha ami.[10]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 11, 'No la''alu-alui ha wa''ara ba he wisa ni''ötö Geheha Keriso andrö, sangöhönagö famaduhu''ö ba dödöra, wama''ele''ö famakao andrö, nitaha Keriso, awö lakhömi andrö, na no aefa wamakao.[11]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 12, 'Ba te''oroma''ö khöra, wa tenga khöra, wa khömi halöŵöra ba ngawalö hadia ia andrö, si no mufa''ombakha''ögö khömi iada''e, ba zangombakha turia somuso dödö andrö, ba khömi, balazi Geheha ni''amoni''ö andrö, nifatenge moroi ba zorugo; mala''ika göi zomasi mamaigi da''ö.[12]', '["Efes 1:3; 2:4 b.t.; Rom 6:4","Faigi 5:4; Kol 1:5","Efes 2:6,7; Yoh 10:28","Faigi 4:12,13; 5:10; Yoh 16:20,22; Heb 12:11","Rom 2:10; Yak 1:3; Faigi 4:13; Amaed 17:3","Yoh 20:29; KorII 5:7","TimII 2:10; Heb 10:39","Dan 2:44; Hag 2:7–9; Mat 13:17","Dan 9:24; 12:7 b.t.; Luk 24:26 b.t.; Heb 2:9","HalZin 2:30 b.t."]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 13, 'Andrö mi''a''aro''ö dödömi, böi ambö gera-erami, midöna-döna manö ba wa''ebua dödö andrö, ni''oro''ö khömi ba wa''ato''ele Yesu Keriso andrö.[13]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 14, 'Si mane ono solo''ö-lo''ö li, böi si mane amuata föna, ba gisö-isömi andrö föna, me lö mi''ila watahögö.[14]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 15, 'Tuladami ni''amoni''ö andrö, si no mogaoni ya''ami, si manö göi mi''amoni''ö ami, ba mbua-buami andrö, fefu,[15]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 16, 'me no so ba zura: "Mi''amoni''ö ami, me no ni''amoni''ö ndra''odo."[16]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 17, 'Ba na fa''ama ami khö zi lö mamaigi bawa niha, wanguhuku, same''e balazi bua-bua zamösana, ba mi''ata ufi zi lö göna bua-buami, götö wekolimi andrö;[17]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 18, 'me no mi''ila, tenga hadia ia zi tekiko, firö, ba ma ana''a hölimi ba huku faya, andrö, khö ndra tua,[18]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 19, 'no do sebua böli hölimi, hulö ndro nono mbiri-biri si lö sinegu, si lö si ta''unö, do Keriso andrö,[19]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 20, 'nihonogöi sa föna, me lö mufobörö danö na, ba nifa''ele''ö ba götö safuria andre, börö ami,[20]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 21, 'samati ba Lowalangi, moroi khönia, ba Lowalangi si no manusugi ya''ia moroi ba ngai zi mate, si no mame''e lakhömi khönia; tobali fanötöna ba Lowalangi göi wamatimi andrö.[21]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 22, 'Me no mihaogö dödömi, ba wolo''ö si duhu, ba wangomasi''ö talifusö, fa''omasi, si lö famini tödö, ba faoma moroi si''aikö ba dödömi mi''omasi''ö nawömi.[22]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 23, 'Si no mendrua tumbu ami, tenga moroi ba danömö sobou dania, no moroi ba zi lö obou, no moroi ba daroma li Lowalangi andrö, sauri, ba si lö tebulö.[23]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 24, 'Me no "hulö ndru''u nösi guli danö, ma''afefu, ba fefu lakhöminia andrö, ba hulö mbowo ndru''u; aleu ndru''u andrö, ba atoru mbowo,[24]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443614, 'NT', 'Fetero I', 1, 25, 'ba irugi zi lö aetu, ba lö tebulö daroma li Zo''aya andrö." Ba da''ö daroma li andrö, ni''ombakha''ö ba khömi, turia somuso dödö andrö.[25]', '["Faigi 5:8; Luk 12:35","Efes 4:17 b.t.","KorII 7:1","MozIII 11:44","Rom 2:6–11; Heb 12:28","KorI 6:20; Efes 4:17","Heb 9:14","Rom 16:25; TimII 1:9,10","HalZin 2:24,33; Heb 7:25","Rom 12:10; YohI 3:18","Yoh 1:13,14; Yak 1:18","Yes 40:6–8","Sin 119:89,96"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 1, 'Ba miböhöli fefu wa''afaito, awö ngawalö walimosa fefu, awö wamini tödö, awö wa''afökhö dödö, awö ngawalö wamöbögö si lö sökhi, fefu.[1]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 2, 'Hulö ndraono sawena tumbu, omasi ami zusu andrö, si oroi daroma li andrö, si lö si faruka, ena''ö tedou ami, ba khönia andrö, fangorifi,[2]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 3, 'na no mitandra wa''asökhi dödö Zo''aya.[3]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 4, 'Na mi''ondrasi ia, gowe sauri andrö, nitibo''ö niha sa, ba nituyu Lowalangi, sebua böli khönia;[4]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 5, 'ba mibe''e nifa''anö göi ami, gowe sauri, omo Geheha, ba wo''ere ni''amoni''ö ba wame''e sumange ni''a''asogö Geheha, somasi Lowalangi, balazi Yesu Keriso.[5]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 6, 'Me no si mane ba zura: "Hiza, ube''e ba Ziona gowe, toyo ba watalinga, nituyu, sebua böli, ba samati khönia ba tebai aila."[6]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 7, 'Ba fa''ebua döi khömi, ya''ami samati; ba ba zi lö mamati, ba no tobali toyo ba watalinga gowe andrö, nitibo''ö zotomo andrö, no tobali gowe nitendre, ba kara börö wa''ate''ala,[7]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 8, 'manendre ira, me lö la''o''ö daroma li andrö; ba da''ö göi nihonogöi khöra.[8]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 9, 'Ba ya''ami, ba mado nituyu, ere salaŵa, soi ni''amoni''ö, banua tana khö Lowalangi; ena''ö mituriagö gamuata zogaoni ya''ami, moroi ba zogömi-gömi, ba hagania andrö, sahöli-höli dödöda.[9]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 10, 'Ya''ami si tenga banua föna, ba si no banua Lowalangi iada''e, si lö muhakhösi tödö föna, ba si no muhakhösi tödö iada''e.[10]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 11, 'He ya''ami ni''omasi''ö! ufarou dödömi, me no si fatewu ami, me no sikoli: böi mifa''amöi ba dödömi wangisö nösi niha andrö, si fa''emali ba dödö.[11]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 12, 'Ba mihaogö mbua-buami, ba gotalua niha baero andrö, ena''ö lasuno Lowalangi, na baŵa we''amöinia, börö mbua-buami andrö si sökhi, na latöngöni da''ö, na no laböbögö khömi zi lö sökhi.[12]', '["Efes 4:22,31; Yak 1:21","Faigi 1:23; Heb 5:13","Sin 34:9","KorI 3:11; Sin 118:22; Mat 21:42","Efes 2:21 b.t.; Yes 61:6; Rom 12:1","Yes 28:16","HalZin 4:11; Yes 8:14","Luk 2:34","MozII 19:5,6; Fam 1:6; Tit 2:14; Kol 1:12,13","Hos 2:23; Rom 9:25","Sin 39:13; Rom 13:13,14","Faigi 3:16; Fil 2:15; Mat 5:16"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 13, 'Ba mi''o''ö fefu nifakhoi niha börö Zo''aya ya''ita, he razo, fondrege zalaŵa,', '["Rom 13:1 b.t.","Faigi 3:9; Tit 2:8","Gal 5:1,13","Faigi 4:8; Rom 12:10; Fam 14:7; Mat 22:21","Efes 6:5 b.t."]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 14, 'ba he kumandru andrö, nifatengenia, ba wangotu''ö sanao horö andrö, ba ba wanuno solau si sökhi.[13]', '["Rom 13:1 b.t.","Faigi 3:9; Tit 2:8","Gal 5:1,13","Faigi 4:8; Rom 12:10; Fam 14:7; Mat 22:21","Efes 6:5 b.t."]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 15, 'Si manö sa zomasi Lowalangi, folau si sökhi labe''e fama''afu mbawa ba wa lö mangila andrö, ba niha sambö era-era.[14]', '["Rom 13:1 b.t.","Faigi 3:9; Tit 2:8","Gal 5:1,13","Faigi 4:8; Rom 12:10; Fam 14:7; Mat 22:21","Efes 6:5 b.t."]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 16, 'Si mane si tenga sawuyu, ba böi si mane same''e balu-balu walösökhi wa no tenga sawuyu ira; si mane enoni Lowalangi.[15]', '["Rom 13:1 b.t.","Faigi 3:9; Tit 2:8","Gal 5:1,13","Faigi 4:8; Rom 12:10; Fam 14:7; Mat 22:21","Efes 6:5 b.t."]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 17, 'Dozi niha mifosumange, mi''omasi''ö watalifusöta, mi''ata''ufi Lowalangi, mifosumange razo.[16]', '["Rom 13:1 b.t.","Faigi 3:9; Tit 2:8","Gal 5:1,13","Faigi 4:8; Rom 12:10; Fam 14:7; Mat 22:21","Efes 6:5 b.t."]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 18, 'Ya''ami, sangai halöŵö, mi''o''ö li zokhö ya''ami, mi''ata''ufi sibai ira, böi ha ba zi sökhi, sebolo tödö, ba zafaito göi.[17]', '["Rom 13:1 b.t.","Faigi 3:9; Tit 2:8","Gal 5:1,13","Faigi 4:8; Rom 12:10; Fam 14:7; Mat 22:21","Efes 6:5 b.t."]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 19, 'Da''ö sa zomasi Lowalangi, na itaögö wamakao niha, me itörö tödönia Lowalangi, na itaha zi lö atulö.[18]', '["Mat 5:10,39 b.t.","Faigi 3:14,17; 4:16","Faigi 3:18; Luk 9:23; Yoh 13:15","Yes 53:9; KorII 5:21","Yes 53:7; Yoh 8:48–50","Kol 1:21,22; Rom 6:11; Yes 53:5","Yes 53:6; Yoh 10:11,14"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 20, 'Hadia sa duria da''ö, na mitaha, na la''otu''ö ami, me no so zalami? Ba na mitaha na lafakao ami, me no milau zi sökhi, da''ö zomasi Lowalangi.[19]', '["Mat 5:10,39 b.t.","Faigi 3:14,17; 4:16","Faigi 3:18; Luk 9:23; Yoh 13:15","Yes 53:9; KorII 5:21","Yes 53:7; Yoh 8:48–50","Kol 1:21,22; Rom 6:11; Yes 53:5","Yes 53:6; Yoh 10:11,14"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 21, 'Ba da''ö sa tekaoni ami, me no itaögö göi wamakao Keriso, salahimi, ba me no iröi wamaedo khömi, ena''ö mitara lahenia.[20]', '["Mat 5:10,39 b.t.","Faigi 3:14,17; 4:16","Faigi 3:18; Luk 9:23; Yoh 13:15","Yes 53:9; KorII 5:21","Yes 53:7; Yoh 8:48–50","Kol 1:21,22; Rom 6:11; Yes 53:5","Yes 53:6; Yoh 10:11,14"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 22, 'Ya''ia, lö nifazökhinia horö, ba lö murongo walimosa ba mbewenia.[21]', '["Mat 5:10,39 b.t.","Faigi 3:14,17; 4:16","Faigi 3:18; Luk 9:23; Yoh 13:15","Yes 53:9; KorII 5:21","Yes 53:7; Yoh 8:48–50","Kol 1:21,22; Rom 6:11; Yes 53:5","Yes 53:6; Yoh 10:11,14"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 23, 'Me lahede-hede''ö ia, ba lö ifuli ihede-hede''ö; me lafakao ia, ba lö ifangaha wolau balö, ibe''e ba danga zangatulö''ö fanguhuku andrö.[22]', '["Mat 5:10,39 b.t.","Faigi 3:14,17; 4:16","Faigi 3:18; Luk 9:23; Yoh 13:15","Yes 53:9; KorII 5:21","Yes 53:7; Yoh 8:48–50","Kol 1:21,22; Rom 6:11; Yes 53:5","Yes 53:6; Yoh 10:11,14"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 24, 'No i ohe yaŵa ba döla geu andrö horöda, ba mbotonia, ena''ö aefa ita ba horö andrö, ba ena''ö auri ita ba zatulö; moroi ba zokhonia andrö, wa döhö wökhömi.[23]', '["Mat 5:10,39 b.t.","Faigi 3:14,17; 4:16","Faigi 3:18; Luk 9:23; Yoh 13:15","Yes 53:9; KorII 5:21","Yes 53:7; Yoh 8:48–50","Kol 1:21,22; Rom 6:11; Yes 53:5","Yes 53:6; Yoh 10:11,14"]', NULL),
  (3443616, 'NT', 'Fetero I', 2, 25, 'Hulö mbiri-biri sa, si no elungu, ami föna, ba noa sa''ae mifuli ami khö gubalo dödömi andrö, khö zamaigi-maigi ya''ia.[24]', '["Mat 5:10,39 b.t.","Faigi 3:14,17; 4:16","Faigi 3:18; Luk 9:23; Yoh 13:15","Yes 53:9; KorII 5:21","Yes 53:7; Yoh 8:48–50","Kol 1:21,22; Rom 6:11; Yes 53:5","Yes 53:6; Yoh 10:11,14"]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 1, 'Si manö göi ndra alawe, ndramu''o''ö li ndra matuara, ena''ö tedönisi da''ö, ba mbua-bua ndra alawe andrö, he lö hede-hede, na so ösa, zi lö mamati ba daroma li andrö,[1]', '["Efes 5:22 b.t.; KorI 7:13–16","TimI 2:9 b.t.","Sin 45:14","MozI 18:12; Gal 4:31","KorI 7:3,5; Kol 3:19"]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 2, 'na lanehegö mbua-buami, wa mi''ata''ufi zi lö sökhi, awö wa no ohau-hau ami.', '["Efes 5:22 b.t.; KorI 7:13–16","TimI 2:9 b.t.","Sin 45:14","MozI 18:12; Gal 4:31","KorI 7:3,5; Kol 3:19"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3443738, 'NT', 'Fetero I', 3, 3, 'Böi fangehao baero wangehao zi manö, böi fondrandra bu ba fo''aya ana''a ba fonukha;[2]', '["Efes 5:22 b.t.; KorI 7:13–16","TimI 2:9 b.t.","Sin 45:14","MozI 18:12; Gal 4:31","KorI 7:3,5; Kol 3:19"]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 4, 'fangehaora niha bakha andrö, si no tobini, tödö andrö, ba zi lö tebulö wa''ebolo dödö ba fa''ahono-hono, si no omasiö Lowalangi.[3]', '["Efes 5:22 b.t.; KorI 7:13–16","TimI 2:9 b.t.","Sin 45:14","MozI 18:12; Gal 4:31","KorI 7:3,5; Kol 3:19"]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 5, 'Si manö sa göi wangehao ndra alawe ni''amoni''ö andrö, föna, sanötöna khö Lowalangi, ba la''o''ö li ndra matuara;', '["Efes 5:22 b.t.; KorI 7:13–16","TimI 2:9 b.t.","Sin 45:14","MozI 18:12; Gal 4:31","KorI 7:3,5; Kol 3:19"]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 6, 'si mane folo''ö Zara andrö li Gaberahamo, fatuha ia khönia; ma''uwunia ami, na mihaogö mbua-buami, ba na lö mi''ata''ufi wamakao, hadia ia.[4]', '["Efes 5:22 b.t.; KorI 7:13–16","TimI 2:9 b.t.","Sin 45:14","MozI 18:12; Gal 4:31","KorI 7:3,5; Kol 3:19"]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 7, 'Si manö göi ndra matua; mihaogö wa''orudu ba ndra alawe, böi sambö era-era, me no öna-öna wa''abötöra, mifosumange ira, me no awömi sanema ondröita andrö, fa''ebua dödö andrö, fa''auri, fa böi tetabi wangandrömi.[5]', '["Efes 5:22 b.t.; KorI 7:13–16","TimI 2:9 b.t.","Sin 45:14","MozI 18:12; Gal 4:31","KorI 7:3,5; Kol 3:19"]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 8, 'Ba fozu, ba ena''ö na ha sara dödömi fefu, ena''ö na afökhö khömi göi zafökhö khö nawömi, mi''omasi''ö dalifusö, ya''ahakhö dödömi nawömi, ba böi fayaŵa ami.[6]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 9, 'Böi misulöni zi lö sökhi awönia si lö sökhi, ba böi misulöni walelesa awönia falelesa; böi manö da''ö; samahowu''ö ami; ba da''ö sa tekaoni ami, ba wanema howu-howu.[7]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 10, '"Ha niha sa zomasi fangorifi, somasi i''ila mbaŵa si sökhi, ba yamutaha lelania, ba zi lö sökhi, ba bewenia, fa böi ilau waya.[8]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 11, 'Yamu''erogö zi lö sökhi, ba yamulau zi sökhi, yamu''alui wa''atulö, yamugohi.[9]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 12, 'Ihörö-hörögö sa zatulö So''aya, ba ibe''e mbörö dalingania ba wangandröra; ba itöngö So''aya zamazökhi si lö sökhi."[10]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 13, 'Ba ha niha zamakao ya''ami, na miforege wolo''ö si sökhi?[11]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 14, 'Ba he mitaha wamakao, na börö wa''atulö, ba ya''ahowu ami. Ba böi mi''ata''ufi wameta''ura, ba böi tokea ami,[12]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 15, 'ba mi''amoni''ö Keriso, So''aya, ba dödömi; böi mamalö-malö wa i''anema''ö mi''ila mibu''a, na so zanofu li khömi, ba wanötöna andrö, si so ba dödömi, gofu ha niha ia; ba böi aefa wa''ebolo dödö ba fa''ata''u; böi itegu ami tödömi,', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 16, 'ena''ö aila zanandraŵaisi ya''ami ba gamuatami si sökhi andrö, ba khö Keriso, na laböbögö khömi zi lö sökhi.[13]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 17, 'Sökhi sa, na tefakao ita ba wolau si sökhi, na nilau dödö Lowalangi ena''ö, moroi na tefakao ita ba wolau si lö sökhi.[14]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 18, 'Noa sa göi mate Keriso, zamuza, ba horö andrö, satulö andrö, salahi zi lö atulö, ena''ö i''ohe ita ba Lowalangi; nibunu sa na dali mboto, ba ni''orifi dali Geheha,[15]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 19, 'ba da''ö dali, ba we''amöinia ba wangombakha ba mbekhu ba gurunga,[16]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 20, 'si lö molo''ö föna, me ibologö dödönia Lowalangi wombalo-mbaloi, me luo No''akhi, me tefazökhi nowo andrö, ba ni''orifi si lö atoto andrö, ha daŵalu, ba nidanö.[17]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 21, 'Famaedo da''ö, famayagö idanö andrö, zangorifi ya''ami göi iada''e, tenga fameta da''i nösi, no fanofu tödö si lö sinegu, khö Lowalangi, börö wemaoso Yesu Keriso andrö,[18]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443738, 'NT', 'Fetero I', 3, 22, 'si so ba gambölö Lowalangi, me no möi ia ba zorugo, me no mube''e barö mbawania mala''ika, awö zalaŵa andrö, awö zabölö andrö.[19]', '["Kol 3:12 b.t.","Faigi 2:23; TesI 5:15; Mat 5:44","Sin 34:13 b.t.; Yak 1:26","TimI 6:11; Heb 12:14","Sin 34:16,17","Rom 8:28","Faigi 2:20; 4:14; Mat 10:28; Yes 8:12; 15:17","Tit 2:8","Faigi 2:19; 4:14–19","Luk 23:46; Faigi 2:21,24; Rom 6:10; 5:6–8; 1:4","Faigi 4:6; Efes 4:9","FetII 2:5; MozI 6:3; Heb 11:7","Heb 10:22 b.t.; Rom 6:4; Efes 5:26","Efes 1:20 b.t."]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 1, 'Ba me no itaha wamakao Keriso, ba nösinia, ba mi''a''aro''ö göi ami tödö si manö; noa sa ibato wamazökhi horö si no manaha famakao, ba nösinia;[1]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 2, 'ena''ö böi sa''ae mi''o''ö wangisö niha andrö, ba zi tosai nosomi ba guli danö, ena''ö somasi Lowalangi mi''o''ö.[2]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 3, 'Noa sa abönö, me no milau zomasi niha baero, ba götö si no numalö, me mitörö hokha, ba fangisö si lö sökhi, ba femabu-mabu, ba femanga-manga, ba famadu-madu tuo, ba fame''e-me''e adu andrö, si lö tola.[3]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 4, 'Andrö fa''ero ira, me lö fao ami, wanörö etuna wa''asilöyaŵa si manö, ba manandraŵa ira.[4]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 5, 'Ba tesekhegö dania ira khö zi no mama''anö ya''ia andrö, ba wanguhuku niha sauri, awö zi no mate.[5]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 6, 'Andrö sa te''ombakha''ö göi ba zi no mate duria somuso dödö andrö, ena''ö auri mbekhura, ba khö Lowalangi, he no tehuku ira, dali niha, ba mbotora.[6]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 7, 'Ba noa sa ahatö gamozua hadia ia, fefu. Ba mi''angenanöi, ba böi miförö, ba wangandrö andrö.[7]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 8, 'Ba si föföna, ba faoma moroi si''aikö ba dödömi mi''omasi''ö nawömi, me oya ibalugö horö fa''omasi andrö.[8]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 9, 'Faoma mibe''e gö khö nawömi na möi tomemi, böi mikökö-kökö.[9]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 10, 'Faoma mitolo nawömi, balazi hadia nitema zamösana, buala andrö, si mane niha si sökhi, nibe''e fa''ebua dödö Lowalangi andrö ba danga, fa ebua dödö si no oya ngawalö andrö.[10]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 11, 'Na so zi fahuhuo, ba ya si mane niŵa''ö Lowalangi; ba na enoni, ba ya si mane na moroi ba wa''abölö andrö, nibe''e Lowalangi, ena''ö tefosumange Lowalangi, fefu hadia ia nilau, börö Yesu Keriso; ya khönia zumange ba fa''abölö, irugi zi lö aetu! Yaduhu.[11]', '["Rom 6:6 b.t.","KorII 5:15","Rom 13:12 b.t.; Tit 3:3","Yoh 15:18 b.t.","TimII 4:1","Faigi 3:19 b.t.; Rom 6:10,11","YohI 2:18; Luk 21:34,36","Faigi 1:22; Kol 3:14; Yak 5:20","Heb 13:2; Fil 2:14","Rom 12:5,6","Rom 12:7; Kol 3:17; Faigi 5:11"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 12, 'Böi fatuwu khömi galitö fanandraigö andrö, ba khömi, si göna ami, ya''ami ni''omasiö; böi hulö na itörö ami si lö larai mila.[12]', '["Faigi 1:6,7; Yak 1:12","Faigi 1:7,8; Rom 8:17; Yak 1:2","Faigi 3:14; Mat 5:10,11","Faigi 2:20","HalZin 11:26; TimII 1:8,12","Hes 9:6; Luk 23:31; TesII 1:5,8","Amaed 11:31; Yer 49:12","Yak 5:13; Luk 23:46"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 13, 'Ndrohu-ndrohu zi no mo''urakha ami ba wamakao andrö khö Keriso, ba mi''omusoi''ö dödömi, ena''ö omuso göi dödömi, ba ena''ö owua-wua dödömi, na tefa''ele''ö dania lakhöminia andrö.[13]', '["Faigi 1:6,7; Yak 1:12","Faigi 1:7,8; Rom 8:17; Yak 1:2","Faigi 3:14; Mat 5:10,11","Faigi 2:20","HalZin 11:26; TimII 1:8,12","Hes 9:6; Luk 23:31; TesII 1:5,8","Amaed 11:31; Yer 49:12","Yak 5:13; Luk 23:46"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 14, 'Na latandraŵaisi ami, ba döi Keriso, ba ya''ahowu ami! me no ahono ba khömi Geheha lakhömi andrö, Eheha Lowalangi.[14]', '["Faigi 1:6,7; Yak 1:12","Faigi 1:7,8; Rom 8:17; Yak 1:2","Faigi 3:14; Mat 5:10,11","Faigi 2:20","HalZin 11:26; TimII 1:8,12","Hes 9:6; Luk 23:31; TesII 1:5,8","Amaed 11:31; Yer 49:12","Yak 5:13; Luk 23:46"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 15, 'Böi sa falukha ba khömi zanaha famakao me no sange''e ia, ba ma me no sanagö, ba ma me no sanao horö, ba ma me ihalö khönia zi tenga khönia.[15]', '["Faigi 1:6,7; Yak 1:12","Faigi 1:7,8; Rom 8:17; Yak 1:2","Faigi 3:14; Mat 5:10,11","Faigi 2:20","HalZin 11:26; TimII 1:8,12","Hes 9:6; Luk 23:31; TesII 1:5,8","Amaed 11:31; Yer 49:12","Yak 5:13; Luk 23:46"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 16, 'Ba na so zanaha famakao, me no niha Keriso ia, ba böi aila ia, ba yamusuno Lowalangi, ba döi andrö.[16]', '["Faigi 1:6,7; Yak 1:12","Faigi 1:7,8; Rom 8:17; Yak 1:2","Faigi 3:14; Mat 5:10,11","Faigi 2:20","HalZin 11:26; TimII 1:8,12","Hes 9:6; Luk 23:31; TesII 1:5,8","Amaed 11:31; Yer 49:12","Yak 5:13; Luk 23:46"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 17, 'Noa sa irugi baŵa, fa ibörötaigö fanguhuku, ba mbanua Lowalangi andrö. Ba na oföna ba khöda, ba hadia wozu zi lö molo''ö, turia somuso dödö andrö, khö Lowalangi?[17]', '["Faigi 1:6,7; Yak 1:12","Faigi 1:7,8; Rom 8:17; Yak 1:2","Faigi 3:14; Mat 5:10,11","Faigi 2:20","HalZin 11:26; TimII 1:8,12","Hes 9:6; Luk 23:31; TesII 1:5,8","Amaed 11:31; Yer 49:12","Yak 5:13; Luk 23:46"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 18, 'Ba na si lö lokha lö auri zatulö, ba heza i''iagö si lö molo''ö ba si so horö?[18]', '["Faigi 1:6,7; Yak 1:12","Faigi 1:7,8; Rom 8:17; Yak 1:2","Faigi 3:14; Mat 5:10,11","Faigi 2:20","HalZin 11:26; TimII 1:8,12","Hes 9:6; Luk 23:31; TesII 1:5,8","Amaed 11:31; Yer 49:12","Yak 5:13; Luk 23:46"]', NULL),
  (3443739, 'NT', 'Fetero I', 4, 19, 'Andrö, sanaha famakao, si faudu ba zomasi Lowalangi göi, ba ndramutou''ö nosora ba danga zomböi ya''ira andrö, si lö faröi, ndramutou''ö ba dangania, wolau si sökhi.[19]', '["Faigi 1:6,7; Yak 1:12","Faigi 1:7,8; Rom 8:17; Yak 1:2","Faigi 3:14; Mat 5:10,11","Faigi 2:20","HalZin 11:26; TimII 1:8,12","Hes 9:6; Luk 23:31; TesII 1:5,8","Amaed 11:31; Yer 49:12","Yak 5:13; Luk 23:46"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 1, 'U''andrö ba zatua andrö, ba khömi, ya''o, awöra satua, samaduhu''ö famakao Keriso andrö, ba awö ba lakhömi andrö, nifa''ele''ö dania.[1]', '["Tit 1:5; Luk 24:48; Fam 1:9","Yoh 21:16,17; HalZin 20:28; Tit 1:7,11","KorII 1:24; TimI 4:12","Heb 13:20; Yes 40:10,11; TimII 4:8; Fam 2:10,26"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 2, 'Mikubaloi rorogöfö Lowalangi andrö, ba khömi, böi mibe''e ni''o''ou ami; ena''ö na saoha gölö, dali Lowalangi, böi ba wangalui luo saila ita, ena''ö na moroi ba wa''omasi;[2]', '["Tit 1:5; Luk 24:48; Fam 1:9","Yoh 21:16,17; HalZin 20:28; Tit 1:7,11","KorII 1:24; TimI 4:12","Heb 13:20; Yes 40:10,11; TimII 4:8; Fam 2:10,26"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 3, 'böi si mane salaŵa, ba dana khöra; ena''ö na tobali duma-duma ami, ba nikubaloi andrö.[3]', '["Tit 1:5; Luk 24:48; Fam 1:9","Yoh 21:16,17; HalZin 20:28; Tit 1:7,11","KorII 1:24; TimI 4:12","Heb 13:20; Yes 40:10,11; TimII 4:8; Fam 2:10,26"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 4, 'Ba mitema dania dakula andrö, si tebai aleu, lakhömi andrö, na to''ele dania zatua gubalo.[4]', '["Tit 1:5; Luk 24:48; Fam 1:9","Yoh 21:16,17; HalZin 20:28; Tit 1:7,11","KorII 1:24; TimI 4:12","Heb 13:20; Yes 40:10,11; TimII 4:8; Fam 2:10,26"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 5, 'Si manö göi ami, ya''ami si akhi, mi''o''ö li zi a''a andrö. Ba dozi ami, ba faoma mi''olembe wa lö fayaŵa andrö ba khö nawömi; itimba sa Lowalangi zi fayaŵa, ba i''ebua''ö dödönia ba zangide-ide''ö ya''ira.[5]', '["Mat 20:26; Yak 4:6","Yak 4:10","Mat 6:25 b.t.; Sin 37:5","Faigi 4:7; HalZin 20:31; Luk 22:31","Yak 4:7; Fil 1:30","KorI 1:9; Efes 3:16,17","Faigi 4:11"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 6, 'Ba mi''ide-ide''ö ami, mibe''e ami ba danga Lowalangi andrö, sabölö, ena''ö ibe''e salaŵa ami, na no irugi baŵa.[6]', '["Mat 20:26; Yak 4:6","Yak 4:10","Mat 6:25 b.t.; Sin 37:5","Faigi 4:7; HalZin 20:31; Luk 22:31","Yak 4:7; Fil 1:30","KorI 1:9; Efes 3:16,17","Faigi 4:11"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 7, 'Mibe''e balazi ia, na so zabu dödömi, gofu hadia ia soso sa dödönia ami.[7]', '["Mat 20:26; Yak 4:6","Yak 4:10","Mat 6:25 b.t.; Sin 37:5","Faigi 4:7; HalZin 20:31; Luk 22:31","Yak 4:7; Fil 1:30","KorI 1:9; Efes 3:16,17","Faigi 4:11"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 8, 'Böi mabu-mabu ami, ba böi mörö-mörö, itörö sa danö si fa''udu khömi andrö, Afökha andrö, hulö zingo sindröndrö-ndröndrö, i''alu-alui, ha niha ni''ania.[8]', '["Mat 20:26; Yak 4:6","Yak 4:10","Mat 6:25 b.t.; Sin 37:5","Faigi 4:7; HalZin 20:31; Luk 22:31","Yak 4:7; Fil 1:30","KorI 1:9; Efes 3:16,17","Faigi 4:11"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 9, 'Da''ö mitimba, mi''abe''e''ö ami, ba wamati, me no mi''ila, si manö göi wamakao, sanörö talifusömi andrö, ba niha ba guli danö.[9]', '["Mat 20:26; Yak 4:6","Yak 4:10","Mat 6:25 b.t.; Sin 37:5","Faigi 4:7; HalZin 20:31; Luk 22:31","Yak 4:7; Fil 1:30","KorI 1:9; Efes 3:16,17","Faigi 4:11"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 10, 'Ba ifalua dania wamo''ahonoa ya''ami Lowalangi wa''ebua dödö andrö fefu, sogaoni ya''ami, ba lakhömi andrö khönia, si lö aetu, ba khö Keriso Yesu, i''abölö''ö ami, i''abe''e''ö ami, ba ifodane-dane ami, na no aefa mitaha wamakao ma''ifu![10]', '["Mat 20:26; Yak 4:6","Yak 4:10","Mat 6:25 b.t.; Sin 37:5","Faigi 4:7; HalZin 20:31; Luk 22:31","Yak 4:7; Fil 1:30","KorI 1:9; Efes 3:16,17","Faigi 4:11"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 11, 'Ya khönia wa''abölö, irugi zi lö aetu! Yaduhu.[11]', '["Mat 20:26; Yak 4:6","Yak 4:10","Mat 6:25 b.t.; Sin 37:5","Faigi 4:7; HalZin 20:31; Luk 22:31","Yak 4:7; Fil 1:30","KorI 1:9; Efes 3:16,17","Faigi 4:11"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 12, 'No usura khömi ma''ifu khö Ziliwano andrö, talifusö si lö faröi, uŵa''ö, famarou dödö nisuragu khömi ba famaduhu''ö, wa da''ö wa''ebua dödö Lowalangi andrö, si ndruhu, ba zi so ami andrö.[12]', '["TesI 1:1; Rom 5:2","HalZin 12:12","Rom 16:16; 8:1"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 13, 'I''owai ami awöda nituyu andrö, ba Mbabilona, ba onogu Mareko andrö.[13]', '["TesI 1:1; Rom 5:2","HalZin 12:12","Rom 16:16; 8:1"]', NULL),
  (3443740, 'NT', 'Fetero I', 5, 14, 'Faoma mi''owai naŵomi fa''agosa bawa ba wa''omasi andrö! Ya''ohahau dödömi, dozi ami, si so ba khö Keriso Yesu.[14]', '["TesI 1:1; Rom 5:2","HalZin 12:12","Rom 16:16; 8:1"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 1, 'Simoni Fetero zanura da''e, enoni Yesu Keriso ba sinengenia, ba zi no falukha famati omasi''ö andrö, si mane khöma, ba wa''atulö dödö andrö, khö Lowalangida, ba khö Zo''aya ya''ita, Yesu Keriso.', '["Yoh 17:3; FetI 1:2"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 2, 'Yafalukha ami wa''ebua dödö ba fa''ohahau dödö, yafahöna, ba wa''aboto ba dödömi Lowalangi, awö Yesu, So''aya ya''ita![1]', '["Yoh 17:3; FetI 1:2"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 3, 'Me noa sa i''amualagö khöda, ba wa''abölö Lowalangi andrö khönia, fefu zoguna ba wangorifi ba ba wolo''ö khö Lowalangi, balazi wa''aboto ba dödöda zogaoni ya''ita andrö, moroi ba lakhömi andrö ba moroi ba wa''asökhi dödö andrö khönia,[2]', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 4, 'ba ni''amualagö khöda fondrege zebua gamabu''ula li andrö, sebua böli, ena''ö möi khömi göi gamuata Lowalangi andrö, ba da''ö, na no mi''efa''ö ami ba wa''atekiko andrö, ba wangisö andrö, ba guli danö.[3]', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 5, 'Ba andrö ya''a''oi so wa''owölö-ölömi, ba wangoroma''ö bua-bua si sökhi, ba wamatimi andrö, ba ba mbua-bua si sökhi, ba fa''aboto ba dödö,', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 6, 'ba ba wa''aboto ba dödö, ba fanaha tödö, ba ba wanaha tödö, ba fa''anau gölö, ba ba wa''anau gölö, ba fangata''ufi Lowalangi,', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 7, 'ba ba wangata''ufi Lowalangi, ba fangomasi''ö talifusö, ba ba wangomasi''ö talifusö, ba fangomasi''ö niha fefu.[4]', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 8, 'Na so khömi da''ö sa, ba na tedou-dou, ba lö areu ami, ba tenga si lö bua ibe''e, ba wa''aboto ba dödömi Zo''aya ya''ita, Yesu Keriso;[5]', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 9, 'si lö da''ö sa, ba sau''a da''ö, no abösi, ba no olifu ia wangehao andrö, fameta horönia föna andrö.[6]', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 10, 'Andrö mendrua manö mi''owölö-ölögö, ya''ami ira talifusö, wanga''aro''ö fogaoni ya''ami andrö, awö wanutuyu ya''ami andrö; na milau da''ö sa, ba lö''ö manö te''ala ami.', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 11, 'Na si manö sa, ba lö te''ambösi khömi dania lala ba mbanua si lö tebulö andrö, khö Zo''aya ya''ita andrö, sangorifi ya''ita, Yesu Keriso.', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 12, 'Andrö wa lö ufamalö-malö wamasugi ba dödömi da''ö, he ŵa''ae no mi''ila, ba he ŵa''ae no aro dödömi ba zi duhu andrö, si so khömi.[7]', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 13, 'Ba no amaedola gömögu da''ö, uŵa''ö tödögu, fatua sodo ba nose andre, fa böi mörö ami ube''e, na ufasugi ba dödömi,[8]', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 14, 'me no u''ila, lö ara tö, ba uröi nosegu andre, me no ibokai göi khögu da''ö So''aya ya''ita, Yesu Keriso.[9]', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 15, 'Ba uforege göi, ena''ö lö mamalö-malö so khömi, na no mofanödo, fa mi''ila mifasugi ba dödömi da''ö.', '["FetI 2:9","Yoh 1:12; YohI 2:15–17","FetI 1:22; TesI 3:12","Tit 3:14; Yoh 15:16","YohI 2:9–11","Rom 15:14,15","KorII 5:1,4","TimII 4:6; Yoh 21:18,19"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 16, 'Tenga sa faya-faya, nifakhai dödö, dali khöma mege, me ma''ombakha''ö khömi wa''abölö Zo''aya ya''ita, Yesu Keriso, ba fa''ato''elenia; noa sa si no anehe-nehe fa''asalaŵania ndra''aga;[10]', '["TimI 1:4; Mat 17:1,2; YohI 1:1","Mat 3:17; 17:5","Mar 9:2","Yoh 5:39; Sin 119:105; KorII 4:6; Fam 2:28; Mal 2:4","KorI 2:11","SamII 23:2; Yes 34:16; Mat 10:20; 22:43"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 17, 'noa sa itema khö Lowalangi Ama zumange ba lakhömi, me tetandrösaigö khönia li andrö, moroi ba lakhömi andrö, si no ebua sibai, me imane: "Onogu omasiö da''ö, wa''omasigu ia."[11]', '["TimI 1:4; Mat 17:1,2; YohI 1:1","Mat 3:17; 17:5","Mar 9:2","Yoh 5:39; Sin 119:105; KorII 4:6; Fam 2:28; Mal 2:4","KorI 2:11","SamII 23:2; Yes 34:16; Mat 10:20; 22:43"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 18, 'Ba li andrö, ba no marongo, moroi ba mbanua si yaŵa, me soga khönia, ba hili ni''amoni''ö andrö,[12]', '["TimI 1:4; Mat 17:1,2; YohI 1:1","Mat 3:17; 17:5","Mar 9:2","Yoh 5:39; Sin 119:105; KorII 4:6; Fam 2:28; Mal 2:4","KorI 2:11","SamII 23:2; Yes 34:16; Mat 10:20; 22:43"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 19, 'ba no sambua na wa''aro li zama''ele''ö andrö, khöda, ba si sökhinia, na mitöngöni ia, hulö wandru, sohagaini naha si no ogömi-gömi, irege tobaha fa''amoluo, ba irege no tumbu madala andrö ba dödömi.[13]', '["TimI 1:4; Mat 17:1,2; YohI 1:1","Mat 3:17; 17:5","Mar 9:2","Yoh 5:39; Sin 119:105; KorII 4:6; Fam 2:28; Mal 2:4","KorI 2:11","SamII 23:2; Yes 34:16; Mat 10:20; 22:43"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 20, 'Na si a''a zaboto ba dödömi, wa tenga lua-lua gera-era niha fefu, hadia ia, wama''ele''ö andrö, ba zura.[14]', '["TimI 1:4; Mat 17:1,2; YohI 1:1","Mat 3:17; 17:5","Mar 9:2","Yoh 5:39; Sin 119:105; KorII 4:6; Fam 2:28; Mal 2:4","KorI 2:11","SamII 23:2; Yes 34:16; Mat 10:20; 22:43"]', NULL),
  (3444996, 'NT', 'Fetero II', 1, 21, 'Lö''ö sa irai tumbu hadia ia wama''ele''ö ba wa''edöna niha, nifatörö Geheha ni''amoni''ö niha, na humede ira; ba Lowalangi moroi.[15]', '["TimI 1:4; Mat 17:1,2; YohI 1:1","Mat 3:17; 17:5","Mar 9:2","Yoh 5:39; Sin 119:105; KorII 4:6; Fam 2:28; Mal 2:4","KorI 2:11","SamII 23:2; Yes 34:16; Mat 10:20; 22:43"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 1, 'Ba so göi zama''ele''ö sofaya ba khöra föna, si mane ba khömi, me so göi dania zamahaö sofaya, samobörö dania fa''atonia, ba wamakiko, sangosilö''ögö göi So''aya, si no mangöhöli ya''ira, ba sangasogö khöra fa''atekiko salio.[1]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 2, 'Ba ato dania zolo''ö khöra, ba wa''asilöyaŵara andrö, ba börö ira, wa tetandraŵaisi dania lala si duhu andrö.[2]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 3, 'Ba ba wa''omasira gana''a, ba lafakhai waya, ba lalimo ami, ba i''otarai föna sa''ae, ba lö ahou huku si göna ira, ba fa''atekikora, ba tenga si mörö.[3]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 4, 'Lö''ö sa salimagö khö Lowalangi mala''ika andrö, si no mamazökhi horö, noa sa itibo''ö ba narako, nirate ba zogömi-gömi, no ibe''e nitaha, ba wanguhuku dania,[4]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 5, 'ba lö salimagö khönia ösi guli danö föna, ha ira No''akhi andrö, sanuriagö fa''atulö dödö andrö, ni''orifinia, ba daŵalu, me ifatörö goloro ba niha si lö sökhi andrö.[5]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 6, 'Ba no itunu mbanua Zodoma andrö ba banua Gomora, i''etu''ö huku ba wanudugö, no ibe''e famaedo, ba niha si lö sökhi dania;[6]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 7, 'ba no i''orifi Loti andrö, satulö tödö, nifakao-kao andrö, ba nilau zi si lö yaŵa andrö, ba wa''asilöyaŵara;[7]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 8, 'afökhö sa ba zatulö andrö wamaigi, me no si fatewu ia khöra, ba afökhö wamondrongo; ero ma''ökhö falukha afökhö bakha dödönia, si no atulö andrö, ba mbua-bua si lö sökhi andrö.', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 9, 'I''ila So''aya i''efa''ö zangata''ufi Lowalangi, ba wanandraigö, ba i''ila itaha zi lö atulö andrö, irege luo wanguhuku ba wangotu''ö ya''ira;[8]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 10, 'ba oföna zanörö lala nösi niha andrö, wangisö si ra''i-ra''iö andrö, ba sangositengagö salaŵa; safaito andrö, si fayaŵa, — lö ata''u ira latandraŵaisi zolakhömi.[9]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 11, 'Ba mala''ika andrö, sabe''e ba sabölö moroi khöra, ba lö latandraŵaisi ira khö Zo''aya.[10]', '["MozV 13:1 b.t.; Mat 24:11; HalZin 20:30; YohI 4:1; Yud 4","Faigi 2:10,13,18; Rom 2:24","TimI 6:5","Yud 6; Fam 20:1; 9:1,11","Faigi 3:6; FetI 3:20","MozI 19:24; Yud 7","MozI 19:16,29","Sin 91:15; KorI 10:13","Yud 8; Tit 3:1,2; MozII 22:28","Yud 9"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 12, 'Ba ya''ira andrö, ba no timba zaliŵa-liŵa ba danö si lö tödö, si no to''ua sondra''u ba samakiko, latandraŵaisi zi lö la''ila na i, ba ba wa''atekikora andrö tekiko ira dania,[11]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 13, 'falukha ira luo wa lö atulö andrö, me no fa''omasira laŵa''ö tödöra wemanga-manga andrö, ba zi ma''ökhö, si ra''i-ra''iö ira ba saila ita, manga-manga ira, ba walimosara andrö, ba lahaogö-haogö göra, awömi.[12]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 14, 'Ba höröra, ba no ha sambalö ira alawe sohorö, ba lö labato-bato wanao horö, ladönisi dödö si lö aro na; tödöra, ba no mufamaha ba wa''omasi gana''a, ono ni''elifi ira.[13]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 15, 'No laröi lala satulö, ba no elungu ira, no latörö lala Mbileamo, ono Mbozoro andrö, si no omasi luo wa lö atulö andrö,[14]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 16, 'ba si falukha göi fotu golalöŵania andrö: kalide andrö, nifonoro, si lö li, ba ilau li niha, itenaŵa wa lö tödö zama''ele''ö andrö.[15]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 17, 'Ya''ira andrö, ba umbu si lö idanö ira, lawuo ni''oloi''ö nangi sabölö, ba ni''iro''ö si bongi andrö sogömi-gömi andrö.[16]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 18, 'Lalau waya, hokha, ba ladönisi niha, ba wa''asilöyaŵa, isö-isö nösi niha andrö, niha si no aefa ma''ifu ba zanörö lala elungua andrö.[17]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 19, 'Lafabu''u khöra wa''aefa, ba ya''ira, ba no sawuyu wa''atekiko; ba zabölö moroi khönia sa möi sawuyu niha.[18]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 20, 'Na si no aefa ira sa ba wa''ira-ira''iö andrö, ba niha guli danö, ba wa''aboto ba dödöra Zo''aya ya''ita, sangorifi ya''ita, Yesu Keriso, ba na ifuli zui te''u''u ira da''ö, na ifuli te''ala ira, ba no tobali abölö-bölö zafuria andrö khöra, moroi ba zi föföna.[19]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 21, 'Sökhi sa ena''ö khöra, na lö irai aboto ba dödöra lala satulö andrö, moroi na no aboto ba dödöra, ba lafuli furi, ba la''erogö zui goroisa andrö, ni''amoni''ö, nifa''ema khöra.[20]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444997, 'NT', 'Fetero II', 2, 22, 'No itörö ba khöra niŵa''ö ba gamaedola andrö, si duhu: "Asu samuli ya''ia ba gutania, ba bawi nifemondri sangawuli ba getuna."[21]', '["Yud 10","Yud 12; Luk 16:19; Fil 3:19","TimII 3:6","Yud 11; MozIV 22:5,7; Fam 2:14","MozIV 22:28 b.t.","Yud 12,13; Amaed 25:14; Dan 12:3","Yud 16","Yoh 8:34; Rom 6:16","Heb 6:4–6; Mat 12:45","Heb 10:26 b.t.; Luk 12:47","Amaed 26:11"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 1, 'Sambua sa''ae zilalö suragu, ya''ami ni''omasi''ö, nisuragu khömi, ba no faoma famasugi ba dödömi gera-era sohau-hau,[1]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 2, 'ena''ö itörö tödömi daroma li andrö, nihönagö zama''ele''ö ni''amoni''ö andrö fanguma''ö, ba oroisa zinenge andrö khömi, ba khö Zo''aya ya''ita, sangorifi ya''ita.[2]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 3, 'Da''ö zi a''a zaboto ba dödömi ena''ö wa so dania zango''aya, na luo safuria andrö, sanörö lala wangisö andrö khöra.[3]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 4, 'ba sanguma''ö: Hezo gamabu''ula linia andrö, ba wa''asonia? Me no aefa mate ndra tua sa, ba lö tebulö fefu, hadia ia, si mane ya''ia i''otarai ba mböröta nifazökhi Lowalangi.[4]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3444999, 'NT', 'Fetero II', 3, 5, 'Noa sa ni''odödögö wa tobini khöra, wa no i''otarai föna sa''ae so mbanua si yaŵa ba tanö tou, moroi ba nidanö, moroi ba daroma li Lowalangi,[5]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 6, 'si moi göi famakiko danö''a da''ö; inönöi idanö.[6]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 7, 'Ba banua si yaŵa iada''e ba tanö iada''e, ba no mutenagö, ba daroma li da''ö göi, no mutaha, ba wamatörö ba galitö, na luo wanguhuku andrö, no luo wa''atekiko niha si lö mangata''ufi Lowalangi.[7]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 8, 'Ba böi yatobini khömi zi sambalö andrö, ya''ami ni''omasi''ö; khö Zo''aya, ba no timba zi hönö fakhe zi ma''ö-ma''ökhö, ba timba zi ha ma''ö-ma''ökhö zi hönö fakhe.[8]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 9, 'Lö i''aragö gamabu''ula li andrö So''aya, si mane niŵa''ö niha ösa, wa fangaragö, ha fa''ebolo dödönia, börö ita, ba lö omasi ia tekiko ösa, ena''ö ahori falukha ira wamalalini era-era.[9]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 10, 'Ba hulö wa''aso zanagö, na irugi dania luo Zo''aya andrö, ba zofetu dania banua si yaŵa, wa''ataya, ba ba zadudu börötania, ba wa''akhozi, ba zakhozi tanö, awö nifazökhi, ba guli danö andrö.[10]', '["Faigi 1:13; FetI 5:12","Yud 17","TimI 4:1; Yud 18","Hes 12:22; Yes 5:19","Sin 136:6; 33:6","Faigi 2:5; MozI 7:11 b.t.","Faigi 2:9; Mat 24:35 b.t.","Sin 90:4","Faigi 3:15; Heb 10:37; Hes 18:23; 33:11","Mat 24:43 b.t.; TesI 5:2; Yes 51:6; Sin 102:27"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 11, 'Ba me sadudu da''ö fefu, ba hadia, lö miforege wanörö lala satulö andrö, awö wangata''ufi Lowalangi?[11]', '["Luk 21:36","Fil 3:20","Yes 65:17; Heb 2:5; Fam 21:27","TesI 5:23","Faigi 3:9; Rom 2:4","Rom 8:19","TesII 2:2; KorI 15:58","Kol 1:9–11; FetI 5:11"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 12, 'ba wanötöna, ena''ö irugi luo Lowalangi andrö, ba wehulu dödö ba da''ö ya''ia mbörö wa adudu mbanua si yaŵa, ba galitö, ba börö wa''alau mbörötania andrö, ba wa''akhozi.[12]', '["Luk 21:36","Fil 3:20","Yes 65:17; Heb 2:5; Fam 21:27","TesI 5:23","Faigi 3:9; Rom 2:4","Rom 8:19","TesII 2:2; KorI 15:58","Kol 1:9–11; FetI 5:11"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 13, 'Ba tadöna-döna mbanua si yaŵa, si bohou, ba tanö si bohou, dali gamabu''ula linia andrö — ba zahono fa''atulö dödö.[13]', '["Luk 21:36","Fil 3:20","Yes 65:17; Heb 2:5; Fam 21:27","TesI 5:23","Faigi 3:9; Rom 2:4","Rom 8:19","TesII 2:2; KorI 15:58","Kol 1:9–11; FetI 5:11"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 14, 'Andrö, ya''ami ni''omasi''ö, me midöna-döna zi manö, ba mi''owölö-ölögö, ena''ö lö hadia ia zi tokana ba sinegu khömi, fönania, na ifaigi, ba wa''atulö.[14]', '["Luk 21:36","Fil 3:20","Yes 65:17; Heb 2:5; Fam 21:27","TesI 5:23","Faigi 3:9; Rom 2:4","Rom 8:19","TesII 2:2; KorI 15:58","Kol 1:9–11; FetI 5:11"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 15, 'Ba fangorifi, miŵa''ö tödömi, wa''ebolo dödö Zo''aya ya''ita andrö, si mane nisura Waulo göi khömi, talifusöda ni''omasi''ö andrö, ba wa''atua-tua andrö, nibe''e khönia,[15]', '["Luk 21:36","Fil 3:20","Yes 65:17; Heb 2:5; Fam 21:27","TesI 5:23","Faigi 3:9; Rom 2:4","Rom 8:19","TesII 2:2; KorI 15:58","Kol 1:9–11; FetI 5:11"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 16, 'si mane fehedenia göi, na itörö linia da''ö, ba zura andrö, fefu, ba zi so ösa zafökhö famotokhi, nifuyu''ö zi lö mufahaö andrö ba si lö aro tödö, si mane sura bö''ö andrö göi, ba wamakiko ya''ira.[16]', '["Luk 21:36","Fil 3:20","Yes 65:17; Heb 2:5; Fam 21:27","TesI 5:23","Faigi 3:9; Rom 2:4","Rom 8:19","TesII 2:2; KorI 15:58","Kol 1:9–11; FetI 5:11"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 17, 'Ba ya''ami ni''omasi''ö, me no tohöna mi''ila, ba mi''angelama, fa lö adöni ami göi ba wa''elungu zi lö molo''ö andrö, ba fa lö tebulö ami ba wa''aromi andrö.[17]', '["Luk 21:36","Fil 3:20","Yes 65:17; Heb 2:5; Fam 21:27","TesI 5:23","Faigi 3:9; Rom 2:4","Rom 8:19","TesII 2:2; KorI 15:58","Kol 1:9–11; FetI 5:11"]', NULL),
  (3444999, 'NT', 'Fetero II', 3, 18, 'Ba yatedou khömi wa''ebua dödö andrö, ba fa''aboto ba dödömi Zo''aya ya''ita, Yesu Keriso, sangorifi ya''ita. Ya khönia zumange, he iada''e, ba he na luo si lö aetu andrö.[18]', '["Luk 21:36","Fil 3:20","Yes 65:17; Heb 2:5; Fam 21:27","TesI 5:23","Faigi 3:9; Rom 2:4","Rom 8:19","TesII 2:2; KorI 15:58","Kol 1:9–11; FetI 5:11"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 1, 'Si otarai mböröta andrö, nirongoma, ni''ila höröma, si no anehe ndra''aga, ba nibabaya dangama andrö, ba daroma li fangorifi andrö.[1]', '["Yoh 1:1,14; 20:27","Yoh 1:4; 17:3,5","Yoh 41:23","Yoh 15:11; FetI 4:13"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 2, 'Ba no tefa''ele''ö wa''auri andrö, ba no ma''ila, ba mafaduhu''ö, ba ma''ombakha''ö khömi wa''auri andrö, si lö aetu, si no so khö Nama, ba si no mufa''ele''ö khöda.[2]', '["Yoh 1:1,14; 20:27","Yoh 1:4; 17:3,5","Yoh 41:23","Yoh 15:11; FetI 4:13"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 3, 'Ni''ilama andrö, nirongoma, ma''ombakha''ö khömi göi, ena''ö awöma ami göi, ba awö Nama sa ita, ba awö Nononia, Yesu Keriso.[3]', '["Yoh 1:1,14; 20:27","Yoh 1:4; 17:3,5","Yoh 41:23","Yoh 15:11; FetI 4:13"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 4, 'Ba da''ö nisurama khömi, ena''ö a''oi so wa''omuso dödömi.[4]', '["Yoh 1:1,14; 20:27","Yoh 1:4; 17:3,5","Yoh 41:23","Yoh 15:11; FetI 4:13"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 5, 'Ba da''ö duria andrö, nirongoma khönia, ni''ombakha''öma khömi, wa no haga Lowalangi, awö wa lö hadia ia wa''ogömi-gömi ba dödönia.[5]', '["Yoh 1:9; 8:12","Faigi 2:9; Yoh 12:35 b.t.","Efes 5:8,9; Fam 1:5; Heb 9:12,14","Amaed 20:9; 28:13","Sin 32:3–5; Tit 2:14","Rom 3:4,10"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 6, 'Na taŵa''ö, awönia ita, ba na tatörö zogömi-gömi, ba no mofaya ita, ba tenga si duhu nilauda.[6]', '["Yoh 1:9; 8:12","Faigi 2:9; Yoh 12:35 b.t.","Efes 5:8,9; Fam 1:5; Heb 9:12,14","Amaed 20:9; 28:13","Sin 32:3–5; Tit 2:14","Rom 3:4,10"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 7, 'Ba na tatörö haga, si mane fe''asonia ba haga, ba no fa''awö ita, ba ihaogö ita do Nononia Yesu, iheta horöda fefu.[7]', '["Yoh 1:9; 8:12","Faigi 2:9; Yoh 12:35 b.t.","Efes 5:8,9; Fam 1:5; Heb 9:12,14","Amaed 20:9; 28:13","Sin 32:3–5; Tit 2:14","Rom 3:4,10"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 8, 'Na taŵa''ö lö horöda, ba tafowöhö ita, ba si duhu lö''ö ba dödöda.[8]', '["Yoh 1:9; 8:12","Faigi 2:9; Yoh 12:35 b.t.","Efes 5:8,9; Fam 1:5; Heb 9:12,14","Amaed 20:9; 28:13","Sin 32:3–5; Tit 2:14","Rom 3:4,10"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 9, 'Na ta''ombakha''ö horöda, ba lö faröi ia, ba no satulö ia, fa i''efa''ö khöda horö andrö, ba fa ihaogö ita, fa iheta fefu zi lö atulö.[9]', '["Yoh 1:9; 8:12","Faigi 2:9; Yoh 12:35 b.t.","Efes 5:8,9; Fam 1:5; Heb 9:12,14","Amaed 20:9; 28:13","Sin 32:3–5; Tit 2:14","Rom 3:4,10"]', NULL),
  (3446332, 'NT', 'Yohane I', 1, 10, 'Na taŵa''ö, lö nifazökhida horö, ba tabali''ö sofaya ia, ba taroma linia andrö lö''ö, ba dödöda.[10]', '["Yoh 1:9; 8:12","Faigi 2:9; Yoh 12:35 b.t.","Efes 5:8,9; Fam 1:5; Heb 9:12,14","Amaed 20:9; 28:13","Sin 32:3–5; Tit 2:14","Rom 3:4,10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 1, 'He ya''ami iraonogu! Andrö usura khömi da''ö, fa böi mifazökhi horö. Ba na so zamazökhi horö, ba so khöda zi lului manguma''ö khö Nama, Yesu Keriso, satulö tödö andrö.[1]', '["Rom 6:1,2; Yes 53:11,12","Faigi 4:10; KorII 5:18,19"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 2, 'Ba ya''ia höli ba horöda andrö, ba tenga ha ba horöda andrö, no ba horö nösi guli danö ma''afefu göi.[2]', '["Rom 6:1,2; Yes 53:11,12","Faigi 4:10; KorII 5:18,19"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 3, 'Ba ba da''ö oroma khöda, wa no aboto ba dödöda ia, na ta''o''ö goroisania.[3]', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 4, 'Na so zanguma''ö: No aboto ba dödögu ia, ba na lö i''o''ö goroisania, ba sofaya da''ö, ba si duhu lö''ö ba dödö da''ö.[4]', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 5, 'Ba na so zolo''ö linia, ba khönia mo''ahonoa wa''omasi Lowalangi andrö, si ndruhu-ndruhu. Ba da''ö aboto ba dödöda, wa ba khönia so ita.[5]', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 6, 'Na so zanguma''ö, ba khönia ahono ia, ba mo''ömö ia, fa si mane amuata da''ö göi gamuatania.[6]', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 7, 'He ya''ami ni''omasi''ö, tenga oroisa si bohou usura khömi, oroisa si no ara, si no so khömi, i''otarai mböröta; taroma li andrö, nirongomi, i''otarai mböröta, goroisa si no ara andrö.[7]', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 8, 'Oroisa si bohou zui usura khömi, si no duhu ba khönia ba ba khömi, me si taya zogömi-gömi andrö, ba me humaga sa''ae haga andrö, si ndruhu.[8]', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 9, 'Na so zanguma''ö, ba haga so ia, ba na fatiu dödönia ba dalifusönia, ba ba zogömi-gömi so ia, irugi da''e.', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 10, 'Sangomasi''ö talifusönia, ba no ahono ba haga, ba lö ba khönia fangala.', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 11, 'Si fatiu tödö khö dalifusönia, ba ba zogömi-gömi so ia, sogömi-gömi itörö, ba lö i''ila, heza isaŵa, me no ifobalunö hörönia sogömi-gömi andrö.[9]', '["Faigi 3, 6. Yoh 14, 21. Mat 7, 21","Faigi 4:20","Faigi 5:3; 4:12","Yoh 13:15","Faigi 3:11; YohII 1:5","Rom 13:12","Faigi 3:14,15; Yoh 12:35"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 12, 'Ufa''ohe''ö zura khömi, ya''ami iraono, me no mu''efa''ö khömi horömi, börö döinia.[10]', '["Luk 24:47","Yoh 1:7; Efes 6:11 b.t.","Rom 12:2; Yak 4:4","KorI 7:31; FetI 1:24"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 13, 'Ufa''ohe''ö zura khömi, ya''ami ira ama, me no aboto ba dödömi zi otarai mböröta andrö. Ufa''ohe''ö zura khömi, ya''ami ono matua, me no milaŵa Gafökha. No ufa''ohe''ö zura khömi, ya''ami iraono, me no aboto ba dödömi Nama.[11]', '["Luk 24:47","Yoh 1:7; Efes 6:11 b.t.","Rom 12:2; Yak 4:4","KorI 7:31; FetI 1:24"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 14, 'No ufa''ohe''ö zura khömi, ya''ami ira ama, me no aboto ba dödömi zi otarai mböröta andrö. No ufa''ohe''ö zura khömi, ya''ami ono matua, me no sabölö ami, ba me ahono ba dödömi daroma li Lowalangi, ba me no milaŵa Gafökha.', '["Luk 24:47","Yoh 1:7; Efes 6:11 b.t.","Rom 12:2; Yak 4:4","KorI 7:31; FetI 1:24"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 15, 'Böi mi''omasi''ö nösi guli danö, ba ma hadia ia, zi so ba guli danö. Na so zangomasi''ö ösi guli danö, ba lö fangomasi''ö Ama ba dödönia.[12]', '["Luk 24:47","Yoh 1:7; Efes 6:11 b.t.","Rom 12:2; Yak 4:4","KorI 7:31; FetI 1:24"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 16, 'Me tenga moroi khö Nama, me moroi ba nösi guli danö fefu, hadia ia, zi so ba guli danö, he fa''omasi nösi niha, ba he fa''omasi hörö, ba he fayaŵasa andrö, ba gana''a.', '["Luk 24:47","Yoh 1:7; Efes 6:11 b.t.","Rom 12:2; Yak 4:4","KorI 7:31; FetI 1:24"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 17, 'Ba si taya nösi guli danö, awö wa''omasinia andrö, ba solo''ö somasi Lowalangi, ba lö tebulö, irugi zi lö aetu.[13]', '["Luk 24:47","Yoh 1:7; Efes 6:11 b.t.","Rom 12:2; Yak 4:4","KorI 7:31; FetI 1:24"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 18, 'He ya''ami iraono! Amozua sa''ae, ba si mane nirongomi, so dania zi fa''udu khö Keriso, ba no ato iada''e zi tobali si fa''udu khö Keriso. Moroi ba da''ö aboto ba dödöda, wa amozua sa''ae.[14]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 19, 'Ba khöda la''otarai, ba tenga awöda ira; na awöda sa ira mena''ö, ba lö laheta ira khöda mena''ö, ba ena''ö oroma, wa lö dozi awöda ira.[15]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 20, 'Ba no so khömi wamayoini andrö, khö ni''amoni''ö andrö, ba mi''ila fefu, hadia ia.[16]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 21, 'Tenga andrö ufa''ohe''ö zura khömi, me lö mi''ila zi duhu, andrö ufa''ohe''ö khömi, me no mi''ila, ba me tenga moroi ba zi duhu fefu, hadia ia, waya.', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 22, 'Ha niha zofaya, baero zangosilö''ögö, wa Keriso andrö Yesu? Da''ö zi fa''udu khö Keriso, sangosilö''ögö Ama, awö Nono.[17]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 23, 'Dozi sangosilö''ögö Ono, ba lö''ö göi khöra Ama; sanehe Ono, ba khönia so göi Nama.[18]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 24, 'Nirongomi, i''otarai mböröta, ba ya''ahono ba dödömi. Na ahono ba dödömi nirongomi, i''otarai mböröta, ba ahono göi ami ba khö Nono ba ba khö Nama.[19]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 25, 'Ba da''ö gamabu''ula li andrö, nifabu''unia khöda: fa''auri si lö aetu andrö.[20]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 26, 'Da''ö nisuragu khömi, ba zamaelungu ya''ami andrö,', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 27, 'ba ya''ami — ba no ahono ba dödömi wamayoini andrö, nitemami khönia, ba lö moguna khömi, ifahaö ami niha, mi''iagö sa''ae ba khönia, dali wamahaö wamayoininia ya''ami andrö, ba ngawalö hadia ia, fefu, ba no si duhu, ba tenga faya; mi''o''ö wamahaönia ya''ami andrö.[21]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 28, 'Ba da''ö, ya''ami iraono, mi''iagö ba khönia, ena''ö lö aiŵö ita, na i''oroma''ö ia dania, ba ena''ö lö te''ailasi ita khönia, ba wa''asonia.[22]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446334, 'NT', 'Yohane I', 2, 29, 'Na mi''ila, satulö ia, ba ya''aboto ba dödömi, wa khönia tumbu göi dozi solau satulö andrö.[23]', '["FetI 4:7; TesII 2:3 b.t.; YohI 4:3; YohII 1:7","HalZin 20:30; KorI 11:19","KorII 1:21,22","Faigi 2:18; Yoh 20:31; FetII 2:1","Faigi 4:15; Yoh 5:23; YohII 1:9","Yoh 14:23","Faigi 5:11; Yoh 10:28","Yoh 14:26; 16:13","Yoh 15:4; Faigi 4:17","Faigi 3:7–10"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 1, 'Mifaigi, ha wa''ebua wa''omasi andrö, ni''amualagö Nama khöda, fa ono Lowalangi döida, ba fa duhu göi ononia ita. Da''ö mbörö, wa lö aboto ba dödö niha guli danö ita, me lö saboto ba dödöra ia.[1]', '["Yoh 1:12; Gal 4:6; Yoh 17:25","Rom 8:16 b.t.; Kol 3:4; Fil 3:21","Heb 12:14"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 2, 'He ya''ami ni''omasi''ö! ono Lowalangi ita iada''e, ba lö''ö na mu''oroma''ö, hadia ita dania. No ta''ila, na no mu''oroma''ö dania, ba fakhili-khili ita khönia, me tanehegö dania ia, he wisa ia.[2]', '["Yoh 1:12; Gal 4:6; Yoh 17:25","Rom 8:16 b.t.; Kol 3:4; Fil 3:21","Heb 12:14"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 3, 'Ba dozi sanötöna da''ö khönia, ba lahaogö ira, si mane ya''ia, si lö si ra''i-ra''iö.[3]', '["Yoh 1:12; Gal 4:6; Yoh 17:25","Rom 8:16 b.t.; Kol 3:4; Fil 3:21","Heb 12:14"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 4, 'Dozi samazökhi horö, ba lasawö göi goroisa, ba fanawö oroisa horö andrö.[4]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 5, 'Ba no mirongo, wa andrö tefa''ele''ö ia, ena''ö iheta horö andrö, ba lö horö ba dödönia.[5]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 6, 'Dozi sahono khönia, ba lö mamazökhi horö. Dozi samazökhi horö, ba lö larai la''ila ia, ba lö saboto ba dödöra ia.[6]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 7, 'He ya''ami iraono! böi yamufaelungu ami niha. Solau satulö, da''ö zatulö, si mane ya''ia andrö, si no atulö.[7]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 8, 'Moroi ba Gafökha zamazökhi horö; moroi ba mböröta sa ifazökhi horö Afökha. Ba da''ö tefa''ele''ö Nono Lowalangi, ena''ö ifakiko halöŵö Gafökha.[8]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 9, 'Dozi si tumbu ba Lowalangi, ba lö mamazökhi horö, me lö tebulö danömönia ba dödöra, ba tebai mamazökhi horö ira, me no moroi ba Lowalangi ira.[9]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 10, 'Ba da''ö oroma, ha niha nono Lowalangi, ba ha niha nono Gafökha. Dozi si lö molau satulö, ba tenga moroi ba Lowalangi ira, awö zi lö mangomasi''ö talifusönia.[10]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 11, 'Da''ö sa duria, nirongomi, i''otarai mböröta, fa faoma ta''omasi''ö nawöda.[11]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 12, 'Böi si mane Ka''ino andrö, soroi ba Gafökha samunu akhinia; ba hana wa ibunu? Me no si lö sökhi mbua-buania, ba me satulö sa mbua-bua nakhinia.[12]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 13, 'Ba böi ahöli-höli dödömi, ya''ami ira talifusö, na fatiu dödö niha guli danö khömi.[13]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 14, 'No ta''ila, no awu''a ita ba wa''amafe, no tasaŵa wa''auri, me ta''omasi''ö dalifusö; si lö mangomasi''ö, ba lö tebulö ba wa''amate.[14]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 15, 'Samunu niha dozi si fatiu tödö ba dalifusöra; ba mi''ila, lö samunu niha, si so fa''auri si lö aetu, si lö tebulö ba dödönia.[15]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 16, 'Ba da''ö no aboto ba dödöda wa''omasi andrö, me no ibelegö nosonia fönada, ba mo''ömö göi ita, tabelegö nosoda föna dalifusöda.[16]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 17, 'Ba na so zi so ana''a guli danö, ba na i''ila, ambö khö dalifusönia, ba na iduhö dödönia khönia, ba hezo wa''omasinia Lowalangi andrö, ba dödönia?[17]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 18, 'He ya''ami iraono! böi ba li ta''omasi''ö nawöda, ba böi ba lela, ba nilauda khönia ta''omasi''ö ia, ba si ndruhu-ndruhu.[18]', '["Faigi 5:17","Faigi 1:7; FetI 2:24","Faigi 2:3 b.t.","Faigi 2:26,29; Efes 5:6","Yoh 8:44; Heb 2:14","Faigi 5:1,18; FetI 1:23","Faigi 2:29; 4:8","Faigi 2:7,8; Yoh 13:34","MozI 4:8","Yoh 15:18 b.t.","Faigi 2:10,11","Mat 5:21,22; Gal 5:21","Yoh 15:13","MozV 15:7 b.t.; Yak 2:15,16","Rom 12:9,13"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 19, 'Ba ba da''ö aboto dania ba dödöda, wa moroi ba zi duhu ta''otarai, ba faduhu dödöda fönania tabe''e,[19]', '["Yoh 18:37","Yes 55:7–9","Heb 4:16","Faigi 5:14,15; Mar 11:24; Yoh 15:7","Yoh 6:29; 15:12; Efes 5:2","Faigi 4:13; Yoh 14:23; Rom 8:9"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 20, 'wa no ebua Lowalangi, moroi ba dödöda, awö wa no aboto ba dödönia fefu, hadia ia; na i''adugö ita tödöda.[20]', '["Yoh 18:37","Yes 55:7–9","Heb 4:16","Faigi 5:14,15; Mar 11:24; Yoh 15:7","Yoh 6:29; 15:12; Efes 5:2","Faigi 4:13; Yoh 14:23; Rom 8:9"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 21, 'He ya''ami ni''omasi''ö! na lö i''adugö ita tödöda, ba so khöda wa lö aiwö, khö Lowalangi.[21]', '["Yoh 18:37","Yes 55:7–9","Heb 4:16","Faigi 5:14,15; Mar 11:24; Yoh 15:7","Yoh 6:29; 15:12; Efes 5:2","Faigi 4:13; Yoh 14:23; Rom 8:9"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 22, 'ba hadia ia ni''andröda ba tatema khönia, me ta''o''ö goroisania, ba me talau zomasi ia.[22]', '["Yoh 18:37","Yes 55:7–9","Heb 4:16","Faigi 5:14,15; Mar 11:24; Yoh 15:7","Yoh 6:29; 15:12; Efes 5:2","Faigi 4:13; Yoh 14:23; Rom 8:9"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 23, 'Ba da''ö goroisania, ena''ö mamati ita ba döi Nononia, Yesu Keriso, ba ena''ö faoma ta''omasi''ö nawöda, si mane ni''oroi''önia khöda.[23]', '["Yoh 18:37","Yes 55:7–9","Heb 4:16","Faigi 5:14,15; Mar 11:24; Yoh 15:7","Yoh 6:29; 15:12; Efes 5:2","Faigi 4:13; Yoh 14:23; Rom 8:9"]', NULL),
  (3446335, 'NT', 'Yohane I', 3, 24, 'Ba na so zolo''ö oroisania, ba ba khönia ahono da''ö, ba ya''ia göi, ba lö tebulö ba zi manö. Ba ba da''ö aboto ba dödöda, wa lö tebulö ia ba khöda, ba Geheha andrö, nibe''enia khöda.[24]', '["Yoh 18:37","Yes 55:7–9","Heb 4:16","Faigi 5:14,15; Mar 11:24; Yoh 15:7","Yoh 6:29; 15:12; Efes 5:2","Faigi 4:13; Yoh 14:23; Rom 8:9"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 1, 'He ya''ami ni''omasi''ö! böi dozi eheha faduhu dödömi, mitandraigö sa geheha andrö, na moroi ba Lowalangi ira. No ato zama''ele''ö sofaya, si möi ba niha ba guli danö.[1]', '["TesI 5:19–22; Yoh 2:18; FetII 2:1","Yoh 1:1–14","Faigi 2:18,22; TesII 2:7","Faigi 5:4; Luk 11:22","Yoh 15:19","Yoh 8:47; 17:14"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 2, 'Ba da''ö aboto ba dödömi Geheha Lowalangi: Dozi eheha, sanehe Yesu Keriso, si no tobali ösi niha, ba moroi ba Lowalangi da''ö;[2]', '["TesI 5:19–22; Yoh 2:18; FetII 2:1","Yoh 1:1–14","Faigi 2:18,22; TesII 2:7","Faigi 5:4; Luk 11:22","Yoh 15:19","Yoh 8:47; 17:14"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 3, 'ba dozi eheha, si lö manehe Yesu, ba tenga moroi ba Lowalangi, ba da''ö gamuata zi fa''udu khö Keriso andrö, nirongomi, so ia, ba no so ia sa''ae ba guli danö.[3]', '["TesI 5:19–22; Yoh 2:18; FetII 2:1","Yoh 1:1–14","Faigi 2:18,22; TesII 2:7","Faigi 5:4; Luk 11:22","Yoh 15:19","Yoh 8:47; 17:14"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 4, 'Moroi ba Lowalangi ami, ya''ami iraono, ba no milaŵa da''ö, me no ebua zi so ba dödömi, moroi ba zi so ba niha ba guli danö andrö.[4]', '["TesI 5:19–22; Yoh 2:18; FetII 2:1","Yoh 1:1–14","Faigi 2:18,22; TesII 2:7","Faigi 5:4; Luk 11:22","Yoh 15:19","Yoh 8:47; 17:14"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 5, 'Moroi ba guli danö ira, andrö moroi ba guli danö huhuora, ba niha guli danö zamondrongo khöra.[5]', '["TesI 5:19–22; Yoh 2:18; FetII 2:1","Yoh 1:1–14","Faigi 2:18,22; TesII 2:7","Faigi 5:4; Luk 11:22","Yoh 15:19","Yoh 8:47; 17:14"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 6, 'Moroi ba Lowalangi ita. Si no aboto Lowalangi ba dödö, da''ö zamondrongo khöda; lö ifondrondrongo khöda si tenga moroi ba Lowalangi. Moroi ba da''ö aboto ba dödöda Geheha si duhu ba eheha samaelungu.[6]', '["TesI 5:19–22; Yoh 2:18; FetII 2:1","Yoh 1:1–14","Faigi 2:18,22; TesII 2:7","Faigi 5:4; Luk 11:22","Yoh 15:19","Yoh 8:47; 17:14"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 7, 'He ya''ami ni''omasi''ö! data''omasi''o nawöda, me no moroi ba Lowalangi wa''omasi andrö, ba me no si tumbu ba Lowalangi dozi sangomasi''ö awöra, ba me no aboto ba dödöra Lowalangi.[7]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 8, 'Si lö mangomasi''ö awönia, ba lö saboto ba dödönia Lowalangi, me no fa''omasi Lowalangi.', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 9, 'Ba da''ö no oroma wa''omasi Lowalangi andrö, ba khöda, me no ifatenge ba guli danö Nononia Lowalangi, ononia si ha sambua andrö, ena''ö auri ita balazi ia.[8]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 10, 'Ba da''ö so wa''omasi andrö, tenga wa no ta''omasi''ö Lowalangi, no wa no i''omasi''ö ita, awö wa no ifatenge Nononia, höli, ba horöda.[9]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 11, 'He ya''ami ni''omasi''ö! na no imanö wangomasi''ö ya''ita Lowalangi, ba mo''ömö göi ita fangomasi''ö awöda.', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 12, 'Samösa lö niha si no irai mangila Lowalangi; na ta''omasi''ö nawöda, ba lö tebulö ia ba dödöda, ba mo''ahonoa ba dödöda wangomasi''öda ya''ia.[10]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 13, 'Ba da''ö aboto ba dödöda, wa lö tebulö ita ba khönia, awö wa lö tebulö ia ba dödöda, me no ibe''e khöda Gehehania andrö, ösa.[11]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 14, 'Ba no anehe ndra''aga ba mafaduhu''ö, wa no ifatenge Ama Nononia, sangorifi ösi guli danö.[12]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 15, 'Na so zanehe, Ono Lowalangi Yesu, ba ba dödönia lö tebulö Lowalangi, ba ya''ia, ba lö tebulö ba khö Lowalangi.[13]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 16, 'Ba no aboto ba dödöda wa''omasi Lowalangi ita, ba no faduhu dödöda ba da''ö. Lowalangi, ba no fa''omasi, ba lö tebulö ba khö Lowalangi zi lö tebulö ba wa''omasi andrö, ba lö tebulö Lowalangi ba dödönia.[14]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 17, 'Ba da''ö mo''ahonoa wa''omasi andrö khöda, fa lö ata''u ita, na luo wanguhuku andrö, me no si mane ya''ia göi ita, ba guli danö andre.[15]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 18, 'Lö fa''ata''u ba wa''omasi andrö, ifofanö sa wa''ata''u fa''omasi si no mo''ahonoa, me no fa''afökhö wa''ata''u; ba sata''u ba lö mo''ahonoa na ba wa''omasi.[16]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 19, 'Ta''omasi''ö ia, me no oföna i''omasi''ö ita.', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 20, 'Na so zanguma''ö: Omasido Lowalangi, ba na fatiu dödönia ba dalifusönia, ba sofaya ia; Si lö mangomasi''ö talifusönia sa, ni''ila hörönia, ba tebai omasi ia Lowalangi, si lö i''ila hörönia.[17]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446336, 'NT', 'Yohane I', 4, 21, 'Ba da''ö goroisa, nibe''enia khöda, ena''ö i''omasi''ö göi dalifusönia sangomasi''ö Lowalangi.[18]', '["Faigi 3:11","Yoh 3:16","Rom 5:8; KorII 5:19,20","Yoh 1:18","Faigi 3:24","Mat 3:17; Yoh 3:17","Yoh 6:69; Ayati 2","Faigi 4:8,12","Faigi 2:28,6","Rom 8:15","Faigi 3:17; 2:4","Faigi 3:23; Yoh 13:34"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 1, 'Dozi samati, wa no Keriso andrö Yesu, ba moroi ba Lowalangi tumbu ira, ba dozi somasi so''ono ya''ia, ba la''omasi''ö göi zi no tumbu khönia andrö.[1]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 2, 'Ba da''ö aboto ba dödöda, wa ta''omasi''ö nono Lowalangi, na omasi ita Lowalangi, ba na ta''o''ö goroisania.', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3446337, 'NT', 'Yohane I', 5, 3, 'Da''ö sa wa''omasida Lowalangi, ena''ö ta''o''ö goroisania, ba tenga safökhö wolo''ö oroisania.[2]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 4, 'Fefu sa, zi tumbu ba Lowalangi, ba abölö moroi ba zoroi uli danö, ba da''ö wa''abölö, sabölö moroi ba zoroi uli danö andrö, famatida andrö.[3]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 5, 'Ha niha zabölö moroi ba zoroi uli danö, baero zamati, wa Ono Lowalangi Yesu?[4]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 6, 'Da''ö ia, zi no möi, balazi nidanö, ba balazi ndro, Yesu Keriso; tenga ha idanö khönia, no idanö awö ndro; ba Eheha andrö zamaduhu''ö; me no si duhu Geheha andrö.[5]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 7, 'Tölu sa zamaduhu''ö,[6]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 8, 'Eheha andrö, ba idanö andrö, ba do andrö, ba ha sara zi tölu andrö.[7]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 9, 'Na faduhu dödöda ba wamaduhu''ö niha, ba no ebua na wamaduhu''ö Lowalangi; da''ö sa wamaduhu''ö Lowalangi andrö, famaduhu''önia Ononia.[8]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 10, 'Khö zamati khö Nono Lowalangi so wamaduhu''ö andrö, ba dödönia. Si lö mamati li Lowalangi, ba no ibali''ö sofaya Lowalangi, me lö nifatinia famaduhu''ö andrö, famaduhu''ö Lowalangi Ononia.[9]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 11, 'Ba da''ö wamaduhu''ö andrö: wa no ibe''e khöda Lowalangi wa''auri si lö aetu, awö wa ba khö Nononia so wa''auri andrö.[10]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 12, 'Khö zi so Ono andrö, khönia so wa''auri andrö; ba zi lö Ono Lowalangi andrö, ba khönia lö fa''auri andrö.[11]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 13, 'Da''ö nisuragu khömi, ena''ö aboto ba dödömi, so khömi wa''auri si lö aetu, khömi samati ba döi Nono Lowalangi andrö.[12]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 14, 'Ba da''ö wa lö aiwö, si so khöda ba khönia: na so ni''andröda, hadia ia, si faudu ba zomasi ia, ba ifondrondrongo khöda.[13]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 15, 'Ba na no aboto ba dödöda ifondrondrongo khöda, na so ni''andröda, ba aboto göi ba dödöda, wa tatema ni''andröda khönia.', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 16, 'Na so zangila, mamazökhi horö dalifusönia, horö si tenga börö wa''amate, ba yamangandrö, ba ifa''aso khönia wa''auri, khö zamazökhi horö si tenga börö wa''amate. So horö börö wa''amate, ba tenga da''ö niŵa''ögu yamangandrö.[14]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 17, 'Horö fefu, hadia ia, zi lö atulö, ba so horö si tenga börö wa''amate.[15]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 18, 'No ta''ila, dozi si tumbu ba Lowalangi, ba lö lafazökhi horö; dozi sa, si tumbu ba Lowalangi, ba lö aefa khönia, ba lö ibabaya Afökha.[16]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 19, 'No aboto ba dödöda, wa moroi ba Lowalangi ita, ba ba danga Gafökha so nösi guli danö, ma''afefu.[17]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 20, 'Ba no tarongo, wa no möi Nono Lowalangi, si no mame''e khöda tödö, ena''ö aboto ba dödöda zi ndruhu andrö; ba ba khö zi ndruhu andrö so ita, ba khö Nononia Yesu Keriso. Da''ö Lowalangi si ndruhu ba fa''auri si lö aetu.[18]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446337, 'NT', 'Yohane I', 5, 21, 'He ya''ami iraono! Mi''angelama ba nadu andrö.[19]', '["Faigi 4:2,15; Yoh 1:12,13","YohII 1:6; Yoh 14:15; Mat 11:30","Faigi 2:15 b.t.; KorI 15:57","Rom 8:37","Yoh 19:34,35; 15:26","Mat 28:19; Yoh 1:1; 16:13–15","Heb 10:15; HalZin 10:47; Yoh 3:5; Mat 26:28","Yoh 8:17,18; 5:37","Rom 8:16; Yoh 3:33","Yoh 1:4","Yoh 3:36; 5:24","Yoh 20:31","Faigi 3:21,22; Yoh 14:13,14","Mat 12:31,32; Heb 6:4 b.t.","Faigi 3:4","Faigi 3:9;. Yoh 17:15","Faigi 4:4,5; Gal 1:4","Yoh 17:3; 14:6; 20:28; Fam 3:7; Rom 9:5; TimI 3:16; YohI 1:1,2","KorI 10:14"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 1, 'Satua andrö zanura da''e, khö Kiria nituyu andrö, ba ba nononia andrö, somasi ndra''o si ndruhu-ndruhu. Ba tenga ha ya''o, no dozi tanö bö''ö göi, si no aboto ba dödö si duhu.[1]', '["YohIII 1:1","TimI 1:2"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 2, 'Börö zi duhu andrö, si lö tebulö ba dödöda, si lö aefa khöda, irugi zi lö aetu.', '["YohIII 1:1","TimI 1:2"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 3, 'Yafalukha ami wa''ebua dödö, awö wa''ahakhö dödö, awö wa''ohahau dödö, khö Lowalangi Ama, ba khö Yesu Keriso, Ono Nama andrö, ba wa''aduhu ba ba wa''omasi.[2]', '["YohIII 1:1","TimI 1:2"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 4, 'No omuso sibai dödögu, me no usöndra, ba nonou andrö, zanörö lala zi duhu, solo''ö oroisa andrö, nitemada khö Nama.[3]', '["YohIII 1:3","YohI 3:11,23","YohI 5:3; Yoh 15:10"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 5, 'Ba iada''e, ba u''andrö khöu, ya''ugö Kiria, tenga hulö na oroisa si bohou usura khöu, no oroisa si no so khöda, i''otarai mböröta, ena''ö faoma ta''omasi''ö nawöda.[4]', '["YohIII 1:3","YohI 3:11,23","YohI 5:3; Yoh 15:10"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 6, 'Ba da''ö wa''omasi andrö, ena''ö tatörö lala goroisania. Da''ö goroisa, ena''ö mitörö, si mane nirongomi, i''otarai mböröta.[5]', '["YohIII 1:3","YohI 3:11,23","YohI 5:3; Yoh 15:10"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 7, 'Noa sa ato zamaelungu, si no möi ba niha ba guli danö, si lö manehe, wa no tobali ösi niha Yesu Keriso. Da''ö zamaelungu, da''ö zi fa''udu andrö, khö Keriso.[6]', '["YohI 2:18; 4:1–3","Fam 3:11","YohI 2:23","TesII 3:14; KorI 16:22; Gal 1:8,9"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 8, 'Mi''angelama, fa böi aekhu gölömi, ba halöŵömi andrö, ena''ö ahori mitema luo.[7]', '["YohI 2:18; 4:1–3","Fam 3:11","YohI 2:23","TesII 3:14; KorI 16:22; Gal 1:8,9"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 9, 'Dozi sanalu''i, si lö ahono ba wamahaö Keriso andrö, ba lö Lowalangi khöra; ba zi lö tebulö ba wamahaö andrö, ba da''ö so Nama, fabaya Ono.[8]', '["YohI 2:18; 4:1–3","Fam 3:11","YohI 2:23","TesII 3:14; KorI 16:22; Gal 1:8,9"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 10, 'Na so zi möi khömi, si lö molohe famahaö da''ö, ba böi mifa''amöi ia yomo, ba böi mi''owai ia.[9]', '["YohI 2:18; 4:1–3","Fam 3:11","YohI 2:23","TesII 3:14; KorI 16:22; Gal 1:8,9"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 11, 'Awönia ba mbua-buania si lö sökhi andrö na so zangowai ya''ia.', '["YohI 2:18; 4:1–3","Fam 3:11","YohI 2:23","TesII 3:14; KorI 16:22; Gal 1:8,9"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 12, 'Oya nisuragu khömi ena''ö, ba lö omasido ufake garate ba taŵa; udöna-döna sa möido khömi, ba fahuhuo ita, ena''ö mo''ahonoa wa''omuso dödöda.[10]', '["YohIII 13:14; YohI 1:4"]', NULL),
  (3446339, 'NT', 'Yohane II', 1, 13, 'La''owai ndra''ugö ono nakhiu ira alawe nituyu andrö.', '["YohIII 13:14; YohI 1:4"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 1, 'Satua andrö zanura da''e, khö, Gayo ni''omasi''ö somasi ndra''o, si ndruhu-ndruhu.[1]', '["YohII 1:1; Rom 16:23"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 2, 'He ya''ugö ni''omasi''ö! Fefu hadia ia khöu, ba omasido, na ohahau dödöu, ba na lö fökhöu, si mane fa''ohahau dödöu ba nosou.', '["YohII 1:1; Rom 16:23"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 3, 'No omuso sibai dödögu, me so dalifusö andrö, samaduhu''ö si duhu andrö, khöu, wa ötörö lala zi duhu.[2]', '["YohII 1:4","Mat 10:8; KorI 9:12 b.t.","Mat 10:40; Rom 16:2"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 4, 'Fondrege wa''omuso dödögu da''ö, na urongo, latörö lala zi duhu iraono khögu.', '["YohII 1:4","Mat 10:8; KorI 9:12 b.t.","Mat 10:40; Rom 16:2"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 5, 'He ya''ugö ni''omasi''ö! Satulö nilaumö ba dalifusö andrö, mendrua manö, me no niha bö''ö ira,', '["YohII 1:4","Mat 10:8; KorI 9:12 b.t.","Mat 10:40; Rom 16:2"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 6, 'samaduhu''ö fa''omasiu, ba zi so banua, ba sökhi, na ötolo ira, ba wofanö, si nangea ba khö Lowalangi.', '["YohII 1:4","Mat 10:8; KorI 9:12 b.t.","Mat 10:40; Rom 16:2"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 7, 'Börö sa döi andrö, wa mofanö ira, ba lö lahalö hadia ia ba niha baero.[3]', '["YohII 1:4","Mat 10:8; KorI 9:12 b.t.","Mat 10:40; Rom 16:2"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 8, 'Andrö mo''ömö ita, tatolo zi mane ya''ira andrö, ena''ö sanolo ba halöŵö ita, ba zi duhu andrö.[4]', '["YohII 1:4","Mat 10:8; KorI 9:12 b.t.","Mat 10:40; Rom 16:2"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 9, 'So zi no usura ba mbanua; ba lö itemaga Dioterefe andrö, somasi na sebuara ia.', '["FetI 3:11,13; YohI 2:29","Yoh 21:24"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 10, 'Andrö ufasugi ba dödönia mbua-buania, na sodo, nilaunia, wamatou ya''aga, fehede si lö sökhi; ba ambö na da''ö, lö''ö göi ifa''amöi khöra dalifusö andrö, ba itenaŵa zedöna mama''amöi ya''ira mena''ö, i''efa''ö ira banua.', '["FetI 3:11,13; YohI 2:29","Yoh 21:24"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 11, 'He ya''ugö ni''omasi''ö! Böi o''ö zi lö sökhi, si sökhi o''ö. Moroi ba Lowalangi zolau si sökhi; solau si lö sökhi, ba lö irai i''ila Lowalangi.[5]', '["FetI 3:11,13; YohI 2:29","Yoh 21:24"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 12, 'Dozi lafaduhu''ö Demeterio andrö, ba ifaduhu''ö göi ia si duhu; ba ya''aga göi, ba mafaduhu''ö ia, ba no ö''ila, wa no si duhu wamaduhu''öma.[6]', '["FetI 3:11,13; YohI 2:29","Yoh 21:24"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 13, 'Oya nisuragu khöu ena''ö, ba lö edönado ufake daŵa ba fanura, ba wanura ya''ia khöu;[7]', '["YohII 1:12","FetI 5:14"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 14, 'udöna-döna, alio falukha ita, ba fahuhuo ita dania.', '["YohII 1:12","FetI 5:14"]', NULL),
  (3446340, 'NT', 'Yohane III', 1, 15, 'Ya''ohahau dödöu! La''owai ndra''ugö si fahuwu andrö. Owai zi fahuwu, ötötöi döira.[8]', '["YohII 1:12","FetI 5:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 1, 'Yuda zanura da''e, enoni Yesu Keriso, talifusö Yakobo, ba nikaoni andrö, ni''omasi''ö, ba khö Lowalangi Ama, ba nirorogö khö Yesu Keriso.[1]', '["Yak 1:1; Mat 13:55; KorI 1:2; Yoh 17:11,15","FetII 1:2"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 2, 'Yafalukha ami wa''ahakhö dödö ba fa''ohahau dödö ba fa''omasi, yatedou khömi.[2]', '["Yak 1:1; Mat 13:55; KorI 1:2; Yoh 17:11,15","FetII 1:2"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 3, 'He ya''ami ni''omasi''ö! me no i''o''oudo tödögu, ba wanura khömi, he wisa wangorifi andrö, si no faoma falukha ita, ba lö tola lö usura khömi wamarou dödö, uŵa''ö, ena''ö mitimba zi fa''udu ba wamati andrö, si no mufa''ema zamuza, ba ni''amoni''ö andrö.[3]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 4, 'Noa sa fatewu ösa niha, ba nitandrösaigö huku andrö, ba zura, föna sa''ae; si no mangerogö Lowalangi; labalia''ö, ba wa''asilöyaŵa la''oguna''ö wa''ebua dödö Lowalangida andrö, ba samatörö ya''ita andrö, si ha samösa, So''aya ya''ita, Yesu Keriso, ba la''osilö''ögö.[4]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 5, 'Ba ufasugi ba dödömi, me no mi''ila zamuza fefu, hadia ia, wa no ifakiko zi lö mamati So''aya, ba zi samuza andrö, me no aefa i''efa''ö ira ba danö Miserayi.[5]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 6, 'Ba he mala''ika andrö, si lö mangaro''ö khöra fa''asalaŵara, sondröi nahiara andrö, ba no itaha ba rate si lö mamalö-malö, bakha ba zogömi-gömi, ba wanguhuku ya''ira, na baŵa sebua andrö dania.[6]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 7, 'Si mane Sodoma ba Gomora ba banua ba ngaira andrö, si no mohorö göi, hulö si mane ya''ira, si no molohi ösi niha bö''ö, me no mube''e famaedo ira, me lataha wotu andrö, ba galitö si lö mate-mate.[7]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 8, 'Ba si manö sa göi da''ö, sangifi-ngifi andrö, lata''unöi nösira, lö ba dödöra zalaŵa, latandraŵaisi zolakhömi.[8]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 9, 'Ba satua mala''ika andrö, Mikhaeli, me fasoso ira Gafökha, me fahuhuo ira, ba mboto Moze andrö, ba ata''u ia i''etu''ö hukunia, fanandraŵaisi, imane: Yamu''otu''ö ndra''ugö So''aya![9]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 10, 'Ba ya''ira andrö, ba latandraŵaisi zi lö la''ila na i, ba hadia zi no to''ua la''ila, si mane saliŵa-liŵa ba danö, si lö tödö, ba lahalö famakikora.[10]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 11, 'Alai ira, me no latörö lala Ga''ino andrö, ba me no adöni dödöra ba wamaelungu luo Mbile''amo andrö, ba me no tekiko ira, ba wolaŵa Gora andrö.[11]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 12, 'Da''ö zolau si lö sökhi, ba gowuloa fa''omasi andrö khömi, si lö ada''u-da''u orudu ba wemanga-manga; ya''ira zokubaloi ya''ira; no lawuo si lö teu ira, ni''oloi''ö nangi, eu sangaruwu na baŵa deu, si lö bua, si no mendrua mate, si no abo''a baya,[12]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 13, 'dulu nasi sabölö, saila ita khöra gotu-otu, döfi selungu-lungu, ba ni''irö''ö si bongi andrö, sogömi-gömi andrö, si lö aetu.[13]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 14, 'Ba noa sa göi ifa''ele''ö he wisa ira Khenoki andrö, fitu nga''ötö i''otarai duada Adamo, no imane: "Hiza, möi Zo''aya, awö ngafulu ngahönö ni''amoni''ö andrö khönia,[14]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 15, 'ba wanguhuku fefu, ha niha ira, ba ba wangotu''ö fefu zi no mangerogö Lowalangi, ba khöra andrö, ba mbua-buara andrö fefu, falösökhi andrö, nifa''uara, ba ba wehede safaito, fefu, nilau zanao horö andrö, si no mangerogö Lowalangi, khönia."[15]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 16, 'Sikökö-kökö andrö, sanahigö Lowalangi, ba nifatörönia khöra, sanörö lala wangisöra, ba fayaŵasa lua-lua mbewera, lasuno niha ba zi so ira, na so harera ba da''ö.[16]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 17, 'Ba ya''ami ni''omasi''ö, ba mitörö-törö tödömi daroma li andrö, si no lahönagö fanguma''ö sinenge Zo''aya ya''ita, Yesu Keriso,[17]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 18, 'me lamane khömi: "Ba götö safuria dania, ba so zango''aya, sanörö lala wangisöra andrö, ba wa''elungura."[18]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 19, 'Si oniagö ya''ira andrö, sanörö lala niha; si lö eheha.[19]', '["TimI 6:12","FetII 2:1–3; Gal 2:4; 5:13; Tit 1:16","Heb 3:16–19","Yoh 8:44; FetII 2:4,9","FetII 2:6; MozV 29:23; MozI 19:5; Yes 66:24; Mat 25:41","FetII 2:10","FetII 2:11; Dan 12:1; Fam 12:7","FetII 2:12","YohI 3:12; FetII 2:15,16; MozIV 16","FetII 2:13,17; Hes 34:2; Mat 7:19","Yes 57:20; FetII 2:17","MozI 5:18,22; MozV 33:2; Mat 25:31","TesII 1:7,8; Mat 12:36","FetII 2:18; Yak 2:1,9","FetII 3:2","FetII 3:3 b.t.; TimII 4:1 b.t.","Amaed 18:1; Rom 16:17; KorI 2:14"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 20, 'Ba ya''ami ni''omasi''ö, ba mi''a''azökhi ami, ba wamatimi andrö, ni''amoni''ö sibai, ba mi''angandrö, balazi Geheha ni''amoni''ö.[20]', '["Kol 2:7","Tit 2:13","TimII 2:25","Rom 11:14; KorI 3:15"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 21, 'Mi''aro''ö ami, ba wa''omasi Lowalangi ita, midöna-döna wa''ahakhö dödö Zo''aya ya''ita, Yesu Keriso, ba wa''auri si lö aetu.[21]', '["Kol 2:7","Tit 2:13","TimII 2:25","Rom 11:14; KorI 3:15"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 22, 'Ba mihakhösi tödö ösa, sangiwa tödö;[22]', '["Kol 2:7","Tit 2:13","TimII 2:25","Rom 11:14; KorI 3:15"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 23, 'mi''orifi, misöbi ba galitö; ba tanö bö''ö, ba mihakhösi tödö, ba mi''ata''ufi, ba mi''ogorofi göi mbaru andrö, si no ra''i-ra''iö ba nösi niha andrö.[23]', '["Kol 2:7","Tit 2:13","TimII 2:25","Rom 11:14; KorI 3:15"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 24, 'Ba khönia, sangila mondrorogö ya''ami, fa lö manendre ami, sangila mama''aso ya''ami föna lakhöminia andrö, si lö sinegu ba sowua-wua tödö,[24]', '["TesI 5:23; Rom 16:25 b.t.","FetII 3:18; TimI 1:17; 2:3"]', NULL),
  (3443012, 'NT', 'Yuda', 1, 25, 'khö Lowalangi si ha sambua andrö, sangorifi ya''ita, balazi Yesu Keriso, So''aya ya''ita, ya khönia lakhömi ba fa''asalaŵa ba fa''abe''e ba fa''abölö, i''otarai föna nga''ötö danö, ba iada''e, ba götö-götö wa''ara dania! Yaduhu.[25]', '["TesI 5:23; Rom 16:25 b.t.","FetII 3:18; TimI 1:17; 2:3"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 1, 'Fama''ele''ö Yesu Keriso da''e, nibe''e Lowalangi khönia, ba wangoroma''ö ba genoninia andrö, he wisa dania, si lö ara tö; ba no ifa''ila''ö, no ifa''ohe''ö ba mala''ikania, khö genoninia Yohane andrö.[1]', '["Faigi 22:6-7","Yoh 21:24; Faigi 19:10; YohI 1:1 b.t."]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 2, 'Si no mamaduhu''ö taroma li Lowalangi, awö wamaduhu''ö Yesu Keriso andrö, ha wa''oya ni''ilania.[2]', '["Faigi 22:6-7","Yoh 21:24; Faigi 19:10; YohI 1:1 b.t."]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 3, 'Ya''ahowu zombaso taroma li fama''ele''ö andrö, ba samondrongo ya''ia, ba solo''ö nisura andrö ba da''ö; noa sa ahatö ginötönia andrö.[3]', '["Faigi 22:7,10; Luk 11:28; FetI 4:7"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 4, 'Yohane zanura da''e, ba mbanua niha Keriso andrö, si fitu, ba Azia, Yafalukha ami wa''ebua dödö, ba fa''ohahau dödö, khö zi so andrö, si no so föna, ba si möi dania, ba ba Geheha andrö, si fitu, si so föna dadaomania andrö,[4]', '["Faigi 4:8; 3:1; Yes 11:2","Faigi 3:14; Yes 55:4; Yoh 18:37; Kol 1:18; Efes 5:25; 1:7","Faigi 5:10; FetI 2:5,9"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 5, 'ba khö Yesu Keriso, samaduhu''ö andrö, si lö faröi, si a''a zi oroi ba ngai zi mate, ba samatörö razo andrö, ba guli danö, khö zangomasi''ö ya''ita andrö, si no mangefa''ö ya''ita ba horöda andrö, donia,[5]', '["Faigi 4:8; 3:1; Yes 11:2","Faigi 3:14; Yes 55:4; Yoh 18:37; Kol 1:18; Efes 5:25; 1:7","Faigi 5:10; FetI 2:5,9"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 6, 'ba si no mame''e banua ya''ita ba ere Namania Lowalangi, ya khönia lakhömi ba fa''abölö, irugi zi lö aetu! Yaduhu.[6]', '["Faigi 4:8; 3:1; Yes 11:2","Faigi 3:14; Yes 55:4; Yoh 18:37; Kol 1:18; Efes 5:25; 1:7","Faigi 5:10; FetI 2:5,9"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 7, 'Hiza, so ia ba lawuo, ba la''ila dania ia dozi hörö, ba samahö ya''ia andrö, ba mege-ege dania ba khönia fefu soi niha ba guli danö. Ya''ia, Yaduhu.[7]', '["Mat 24:30; Dan 7:13; Sakh 12:10","Faigi 22:13; Yes 41:4"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 8, 'Alafa ndra''o ba omega ndra''o, iŵa''ö So''aya Lowalangi, si so, ba si no so föna, ba si möi dania, samatörö fefu, hadia ia.[8]', '["Mat 24:30; Dan 7:13; Sakh 12:10","Faigi 22:13; Yes 41:4"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 9, 'Ya''o, Yohane, talifusömi ba wamakao andrö, ba ba mbanua andrö, ba ba wanaha tödö andrö, ba khö Yesu, no sodo ba hulo andrö, Fatemo döi, börö daromali Lowalangi ba famaduhu''ö Yesu andrö.[9]', '["FetI 5:1; TimII 2:12; Faigi 20:4"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 10, 'Ba aheta nosogu, me luo Zo''aya, ba urongo furigu li sebua, hulö li dorofe,[10]', '["Faigi 4:1,2","Yes 48:12"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 11, 'imane: Hadia ni''ilau, ba tanö ba zura, ba fa''ohe''ö ba mbanua niha Keriso, si fitu andrö, ba Nefeso, ba ba Zimina, ba ba Weregamo, ba ba Diatira, ba ba Zade, ba ba Wiladefia, ba ba La''odikia.[11]', '["Faigi 4:1,2","Yes 48:12"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 12, 'Ba ubali''ö ndra''odo, ba wamaigi li andrö, sihede khögu; ba me ubali''ö ndra''o, ba u''ila naha wandru ana''a, fitu,[12]', '["Sakh 4:2","Faigi 2:1; 14:14; Dan 7:13; 10:5"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 13, 'ba ba gotalua naha wandru andrö, ba si hulö Nono Niha, no mobaru sanau, ba no mamöbö talu ana''a, ba dölö''ania.[13]', '["Sakh 4:2","Faigi 2:1; 14:14; Dan 7:13; 10:5"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 14, 'Ba högönia ba bunia, ba no afusi, hulö mbu mbiri-biri safusi, hulö mbetua, ba hörönia, ba no hulö hola-hola galitö,[14]', '["Dan 7:9; Faigi 2:18","Faigi 10:1; 14:2; Dan 10:6","Faigi 1:20; 2:12; 19:15; Heb 4:12"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 15, 'ba ahenia, ba hulö garamba nifahele, ba galitö, ba linia, ba no hulö wegoso-goso nidanö sebua.[15]', '["Dan 7:9; Faigi 2:18","Faigi 10:1; 14:2; Dan 10:6","Faigi 1:20; 2:12; 19:15; Heb 4:12"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 16, 'Ba so ba dangania kambölö ndröfi, fitu, ba i''otarai mbawania gari satarö, si faoma bawa, ba bawania, ba no hulö wehaga luo, ni fondrege wa''abölönia.[16]', '["Dan 7:9; Faigi 2:18","Faigi 10:1; 14:2; Dan 10:6","Faigi 1:20; 2:12; 19:15; Heb 4:12"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 17, 'Ba me u''ila ia, ba alaudo tou, fönania, hulö zi mate. Ba itufa ndra''o tangania kambölö, imane: "Böi ata''ufi, si föföna ndra''o, ba safuria,[17]', '["Faigi 2:8","Rom 6:9,10; Faigi 3:7"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 18, 'ba sauri andrö; ba no mate ndra''o, ba hiza, no auri ndra''o, irugi zi lö aetu ba so khögu wogoe ba wa''amate ba ba mbanua tou.[18]', '["Faigi 2:8","Rom 6:9,10; Faigi 3:7"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 19, 'Ba tanö ba zura hadia ni''ilau, ba hadia iada''e, ba hadia dania, na aefa da''e.[19]', '["Faigi 4:1","Faigi 2:1"]', NULL),
  (3392247, 'NT', 'Fama''ele''ö', 1, 20, 'Si no tobini khöu andrö, döfi andrö, si fitu, ni''ilau ba dangagu kambölö, awö naha wandru ana''a, andrö, si fitu: Döfi andrö, si fitu, ba no mala''ika mbanua si fitu andrö, ba naha wandru andrö, si fitu, ba no fitu banua."[20]', '["Faigi 4:1","Faigi 2:1"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 1, 'Ba mala''ika mbanua andrö, ba Nefeso, ba da''ö sura: Da''ö niŵa''ö zolohe tangania kambölö dofiandrö si fitu, sowaö-waö ba gotalua naha wandru ana''a andrö, si fitu:[1]', '["Faigi 1:13-20"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 2, 'No u''ila mbua-buau andrö, ba fa''erege dödöu, ba fa''anau gölöu, awö wa tebai ötaha zi lö sökhi; ba no ötandraigö zanguma''ö sinenge ira, ba tenga sa ya''ia, ba no ösöndra, wa sofaya ira;[2]', '["TesI 1:3; Efes 5:11; YohI 4:1","Faigi 1:20","Faigi 2:15; Sin 139:21-22; FetII 2:2 b.t."]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 3, 'ba no ötaha dödöu ba no ötaögö wamakao, börö döigu andrö, ba lö satage ndra''ugö.', '["TesI 1:3; Efes 5:11; YohI 4:1","Faigi 1:20","Faigi 2:15; Sin 139:21-22; FetII 2:2 b.t."]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 4, 'Ba da''ö zi fatuwu khögu, ba khömö andrö, wa no öböhöli wa''omasiu ba mböröta andrö.', '["TesI 1:3; Efes 5:11; YohI 4:1","Faigi 1:20","Faigi 2:15; Sin 139:21-22; FetII 2:2 b.t."]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 5, 'Andrö törö-törö tödöu hadia zi fahole khöu, ba falalini gera-erau, ba alui mbua-bua ba mböröta andrö; ba na lö ö''o''ö da''ö, ba möido khöu ba utuli''ö naha wandru andrö khöu ba nahania, na lö öfalalini gera-erau.[3]', '["TesI 1:3; Efes 5:11; YohI 4:1","Faigi 1:20","Faigi 2:15; Sin 139:21-22; FetII 2:2 b.t."]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 6, 'Ba da''ö zi so khöu; ö''ogorofi wolau nikola''iti andrö, ni''ogorofigu göi.[4]', '["TesI 1:3; Efes 5:11; YohI 4:1","Faigi 1:20","Faigi 2:15; Sin 139:21-22; FetII 2:2 b.t."]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 7, 'Si so tögi dalinga, ba yamufondrondrongo hadia niŵa''ö Geheha ba mbanua andrö: Ha niha zi möna ba ube''e önia mbua geu fangorifi andrö si so ba waradaiso andrö, khö Lowalangi![5]', '["Mat 11:15; Faigi 21:7; 22:2; MozI 2:9"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 8, 'Ba ba mala''ika mbanua andrö ba Zimina, ba da''ö sura: Da''ö niŵa''ö zi föföna andrö ba safuria, si no mate föna, ba si no auri iya''e.[6]', '["Faigi 1:17-18"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3392256, 'NT', 'Fama''ele''ö', 2, 9, 'No u''ila wamakaomö andrö, ba fa''anumanamö—ba no so''ana''a ndra''ugö—ba fanandraŵaisi ya''ugö andrö, ba zanguma''ö niha Yehuda ira, ba tenga sa ya''ia, ha sekola Zatana ira.[7]', '["KorII 6:10; Faigi 3:9; Yoh 8:39,44","Mat 10:28; FetI 4:12; KorI 9:25; Yak 1:12"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 10, 'Böi ata''ufi hadia ia, nitaögöu dania. Hiza, ibe''e ba gurunga ösa ami Afökha, ena''ö tetandraigö ami, ba nifakao ami, fulu bongi. Böi faröi ndra''ugö, irugi wa''amate, ba ube''e khöu dakula fa''auri andrö.[8]', '["KorII 6:10; Faigi 3:9; Yoh 8:39,44","Mat 10:28; FetI 4:12; KorI 9:25; Yak 1:12"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 11, 'Si so tögi dalinga, ba yamufondrondrongo hadia niŵa''ö Geheha ba mbanua andrö: Ha niha zi möna, ba tebai i''alani fa''amate si samuza andrö.[9]', '["Faigi 20:6,14"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 12, 'Ba ba mala''ika mbanua andrö, ba Weregamo, ba da''ö sura: Da''ö niŵa''ö zi so gari satarö andrö, si faoma bawa.[10]', '["Faigi 1:16"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 13, 'U''ila heza so nahau, ba zi so dadaoma Zatana andrö. Ba lö niböhöliu töigu andrö, ba lö ni''osilö''ögöu famati andrö khögu, me luo Gandrifa andrö, samaduhu''ö ya''o, si lö faröi andrö, nibunu ba khömi, ba zi so naha Zatana.[11]', '["Faigi 3:8","MozIV 31:16; Yud 11","Faigi 2:6","Yes 11:4; Faigi 19:15"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 14, 'Ba so ma''ifu zi fatuwu khögu, ba khömö andrö, me no so khöu ba da''ö zolo''ö famahaö Mbile''amo andrö. Samahaö Balaki andrö, ba wamobörö fangala föna Ndraono Gizeraeli, ba wemanga gö nadu ba ba wohorö.[12]', '["Faigi 3:8","MozIV 31:16; Yud 11","Faigi 2:6","Yes 11:4; Faigi 19:15"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 15, 'Ba so khöu göi zolo''ö famahaö nikola''iti andrö, si manö göi.[13]', '["Faigi 3:8","MozIV 31:16; Yud 11","Faigi 2:6","Yes 11:4; Faigi 19:15"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 16, 'Falalini gera-erau. Ba na lö da''ö, ba alio möido khöu, ba usuwö ira gari mbawagu andrö.[14]', '["Faigi 3:8","MozIV 31:16; Yud 11","Faigi 2:6","Yes 11:4; Faigi 19:15"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 17, 'Si so tögi dalinga, ba yamufondrondrongo hadia niŵa''ö Geheha, ba mbanua andrö: Ha niha zi möna, ba ube''e khönia "mana" si tobini andrö, ba ube''e khönia gara safusi, ba töi si bohou nisura ba dete gara andrö, si lö i''ila niha, baero zanema ya''ia andrö.[15]', '["Yoh 6:32; Yes 62:2"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 18, 'Ba ba mala''ika mbanua andrö ba Diatira, ba da''ö sura: Da''ö niŵa''ö Nono Lowalangi andrö, si so hörö andrö, si hulö hola-hola galitö, ba si so ahe, si hulö garamba.[16]', '["Faigi 1:14-15; HalZin 16:14"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 19, 'No u''ila mbua-buau andrö, ba fa''omasi andrö, ba famati andrö, ba fanolou andrö, ba fanaha tödö andrö, awö wa tedou mbua-buau safuria andrö, moroi ba zi föföna.[17]', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 20, 'Ba da''ö zi fatuwu khögu, ba khömö andrö, wa ötehe galawe andrö, Izebela, sanguma''ö sama''ele''ö ia, ba no samahaö enonigu andrö ba samaelungu ya''ira, ba wohorö, ba ba wemanga gö nadu.[18]', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 21, 'Ba no ufonoso ia, ena''ö ifalalini gera-erania, ba lö edöna ia ifalalini, ba wamöhöi fohorönia andrö ena''ö.', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 22, 'Hiza, utuli''ö tou ia ba zalo; ba awönia sohoröni ya''ia, ba ube''e ba wamakao sabölö-bölö, na lö lafalalini gera-erara, ba wamöhöi bua-buania andrö.', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 23, 'Ba ononia, ba ububunu ba ya''aboto ba dödö mbanua niha Keriso fefu misa, ya''o zanekhegö bua, awö dödö, ba udozigö ami wanulöni bua-bua zamösana.[19]', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 24, 'Ba uŵa''ö khömi, ya''ami zi tosai ba Diatira, ha wa''ato zi lö famahaö andrö, si lö aboto ba dödö fa''abakha dödö Zatana andrö, niŵa''öra: Lö''ö sa''ae ufonoro ami noro bö''ö.', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 25, 'Ba hadia zi so khömi, ba böi miböhöli, irege sodo.[20]', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 26, 'Ba ha niha zi möna, ba si lö mamöhöi halöŵö khögu, irugi gamozua, ba ube''e barö mbawania niha baero,[21]', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 27, 'ba ikubaloi ira si''o si''öli, si mane na larasa mbowoa tanö, si mane fanemagu göi mege khö Namagu;[22]', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 28, 'Ba ube''e khönia madala andrö.[23]', '["Heb 6:10","RazI 16:31; MozII 34:15","RazII 10:7-18; Sin 7:10; Mat 16:27; Faigi 20:12-13","Faigi 3:11","Faigi 20:4; 22:5; KorI 6:2","Faigi 19:15; Sin 2:8-9","FetII 1:19"]', NULL),
  (3392256, 'NT', 'Fama''ele''ö', 2, 29, 'Si so tögi dalinga, ba yamufondrondrongo hadia niŵa''ö Geheha ba mbanua andrö![24]', '["Faigi 3:6"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 1, 'Ba ba mala''ika mbanua andrö ba Zade, ba da''ö sura: Da''ö niŵa''ö zi so Eheha Lowalangi andrö, si fitu, awö ndröfi andrö, si fitu: No u''ila mbua-buau andrö, wa no töimö zauri, ba no si mate ndra''ugö.[1]', '["Faigi 1:4,16; 5:6"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 2, 'Faoso, ba abe''e''ö zi tosai andrö, si lö ara tö mate; tenga sa so''ahonoa mbua-buau andrö, föna Lowalangigu, wamaigigu.[2]', '["Hes 34:4,16","Faigi 16:15; TesI 5:2 b.t.","Faigi 7:14; Yes 64:6","Faigi 6:11; Fil 4:3; Mat 10:32 b.t."]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 3, 'Andrö törö-törö tödöu he wisa wanemau mege, ba he wisa wamondrongou, ba böi böhöli, ba falalini gera-erau. Ba na si mörö ndra''ugö, ba sodo dania, hulö zanagö, ba lö''ö manö ö''ila ha wa''alaŵa luo urugi ndra''ugö.[3]', '["Hes 34:4,16","Faigi 16:15; TesI 5:2 b.t.","Faigi 7:14; Yes 64:6","Faigi 6:11; Fil 4:3; Mat 10:32 b.t."]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 4, 'Ba so ösa khöu döi ba Zade, si lö mamoda''i nukhara, lö larai, ba awögu dania ira, nukha safusi nukhara, me no si nangea ira.[4]', '["Hes 34:4,16","Faigi 16:15; TesI 5:2 b.t.","Faigi 7:14; Yes 64:6","Faigi 6:11; Fil 4:3; Mat 10:32 b.t."]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 5, 'Si manö zi möna andrö, nifonukha nukha safusi, ba lö''ö manö sa''ae ubunu döinia ba zura wa''auri andrö, ba u''ombakha''ö döinia, ba zi so Amagu, ba ba zi so mala''ika andrö khönia.[5]', '["Hes 34:4,16","Faigi 16:15; TesI 5:2 b.t.","Faigi 7:14; Yes 64:6","Faigi 6:11; Fil 4:3; Mat 10:32 b.t."]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 6, 'Si so tögi dalinga, ba yamufondrondrongo hadia niŵa''ö Geheha ba mbanua andrö!', '[]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 7, 'Ba ba mala''ika mbanua andrö ba Wiladefia, ba da''ö sura: Da''ö niŵa''ö ni''amoni''ö andrö, si duhu andrö, si so fogoe andrö khö Dawido, samokai si lö sokusi, ba sokusi si lö samokai.[6]', '["Faigi 6:10; 1:18; Yes 22:22; Mat 16:19"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 8, 'No u''ila mbua-buau andrö; hiza, no ube''e fönau mbawandruhö si no teboka, si lö i''ila ikusi niha, ha niha ia; si lö aröuröu sa wa''abölöu, ba lö''ö sa niböhöliu taroma ligu andrö, ba lö ni''osilö''ögöu töigu.[7]', '["KorI 16:9","Faigi 2:9; Yes 49:23; 60:14","FetII 2:9; Mat 24:21 b.t.","Faigi 2:10,25; Kol 2:18","Yes 56:5; Faigi 2:17; 22:4; 21:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 9, 'Hiza, uhalö niha ba zekola Zatana andrö, sanguma''ö niha Yehuda ira, ba tenga sa ya''ia; sofaya ira. Hiza, möi ira ube''e, ba mangalulu ira, latuhi danö fönau. Ba aboto ba dödöra, wa no u''omasi''ö ndra''ugö.[8]', '["KorI 16:9","Faigi 2:9; Yes 49:23; 60:14","FetII 2:9; Mat 24:21 b.t.","Faigi 2:10,25; Kol 2:18","Yes 56:5; Faigi 2:17; 22:4; 21:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 10, 'Me no lö niböhöliu taroma li ba wa''anau gölö andrö, khögu, ba lö''ö göi uböhöli ndra''ugö, na baŵa wanandraigö andrö, sondrugi dania uli danö ma''afefu, ba wanandraigö niha sowanua ba guli danö.[9]', '["KorI 16:9","Faigi 2:9; Yes 49:23; 60:14","FetII 2:9; Mat 24:21 b.t.","Faigi 2:10,25; Kol 2:18","Yes 56:5; Faigi 2:17; 22:4; 21:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 11, 'Alio sodo; böi böhöi zi ho so khöu, fa böi lahalö dakulamö andrö.[10]', '["KorI 16:9","Faigi 2:9; Yes 49:23; 60:14","FetII 2:9; Mat 24:21 b.t.","Faigi 2:10,25; Kol 2:18","Yes 56:5; Faigi 2:17; 22:4; 21:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 12, 'Ha niha zi möna, ba ube''e ehomo ba gosali Lowalangigu, ba lö''ö manö sa''ae aheta ia, ba usura ba detenia döi Lowalangigu andrö, ba töi mbanua Lowalangigu andrö, töi Yeruzalema si bohou, si möi mitou, moroi ba zorugo, moroi ba Lowalangigu, ba töigu, si bohou andrö.[11]', '["KorI 16:9","Faigi 2:9; Yes 49:23; 60:14","FetII 2:9; Mat 24:21 b.t.","Faigi 2:10,25; Kol 2:18","Yes 56:5; Faigi 2:17; 22:4; 21:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 13, 'Si so tögi dalinga, ba ya''mufondrondrongo hadia niŵa''ö Geheha ba mbanua andrö!', '[]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 14, 'Ba ba mala''ika mbanua andrö ba La''odikia, ba da''ö sura: Da''ö niŵa''ö zi "yaduhu" andrö, samaduhu''ö andrö, si lö faröi ba si duhu, böröta nifazökhi Lowalangi andrö[12]', '["Kol 4:13,15; Faigi 1:5; KorII 1:20; Kol 1:15 b.t."]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 15, 'No u''ila mbua-bua andrö, wa tenga sokafu ndra''ugö, ba tenga göi saukhu. Ena''ö na fasambalö ndra''ugö, ma sokafu, ba ma saukhu.', '["Hos 12:9; KorI 4:8","Amaed 8:10 b.t.; Sakh 13:9; Faigi 16:15","Yob 5:17; Heb 12:6","Luk 12:36 b.t.; Yoh 14:23","Luk 22:29; Heb 12:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 16, 'Ba me no si manö, me no sanakhö-nakhö ndra''ugö, tenga saukhu ba tenga sokafu, ba utura''ö ndra''ugö ba mbawagu.', '["Hos 12:9; KorI 4:8","Amaed 8:10 b.t.; Sakh 13:9; Faigi 16:15","Yob 5:17; Heb 12:6","Luk 12:36 b.t.; Yoh 14:23","Luk 22:29; Heb 12:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 17, 'Öŵa''ö-ŵa''ö sa: "Niha si so ndra''o, no usöndra, lö hadia ia zambö khögu," ba lö''ö sa ö''ila, wa no sebua akaola ndra''ugö, ba sahakhö dödöda, ba si numana, ba sau''a, ba si lö nukha.[13]', '["Hos 12:9; KorI 4:8","Amaed 8:10 b.t.; Sakh 13:9; Faigi 16:15","Yob 5:17; Heb 12:6","Luk 12:36 b.t.; Yoh 14:23","Luk 22:29; Heb 12:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 18, 'Uŵa''ö sa khöu, ötuka gana''a khögu, si no mukhozi ba galitö, ena''ö mo''ana''a ndra''ugö, ba nukha safusi, ena''ö monukha''ö, fa lö oroma zaila''ö, me no lö nukhau, ba dalu-dalu hörö, ba wogule''ö ba höröu, ena''ö ö''ila niha.[14]', '["Hos 12:9; KorI 4:8","Amaed 8:10 b.t.; Sakh 13:9; Faigi 16:15","Yob 5:17; Heb 12:6","Luk 12:36 b.t.; Yoh 14:23","Luk 22:29; Heb 12:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 19, 'Ha niha sa zomasi ndra''o, ba utegu, ba u''otu''ö; andrö forege, ba falalini gera-erau.[15]', '["Hos 12:9; KorI 4:8","Amaed 8:10 b.t.; Sakh 13:9; Faigi 16:15","Yob 5:17; Heb 12:6","Luk 12:36 b.t.; Yoh 14:23","Luk 22:29; Heb 12:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 20, 'Hiza no so ndra''o moroi tou, ba ubökö-bökö mbawandruhö. Na so zamondrongo ligu, ba samokai bawandruhö, ba khönia möido yomo, ba orudu manga ndra''aga.[16]', '["Hos 12:9; KorI 4:8","Amaed 8:10 b.t.; Sakh 13:9; Faigi 16:15","Yob 5:17; Heb 12:6","Luk 12:36 b.t.; Yoh 14:23","Luk 22:29; Heb 12:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 21, 'Ha niha zi möna, ba utehe khönia, mudadao ia awögu, ba dadaomagu andrö, si mane ya''o, me no mönado, ba me no dumadaodo, awö Namagu, ba dadaomania.[17]', '["Hos 12:9; KorI 4:8","Amaed 8:10 b.t.; Sakh 13:9; Faigi 16:15","Yob 5:17; Heb 12:6","Luk 12:36 b.t.; Yoh 14:23","Luk 22:29; Heb 12:2"]', NULL),
  (3392259, 'NT', 'Fama''ele''ö', 3, 22, 'Si so tögi dalinga, ba yamufondrondrongo hadia niŵa''ö Geheha ba mbanua andrö!', '[]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 1, 'Ba aefa da''ö, ba so ni''ilagu, ba hiza mbawandruhö si no teboka ba zorugo, ba li andrö si föföna urongo mege, si hulö li dorofe, me humede ia khögu ba imane: Ae miyaŵa ba da''e, ba u''oroma''ö khöu hadia dania, na aefa da''e.[1]', '["Hes 1:1"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 2, 'Ba i''anema''ö aheta nosogu, ba hiza dadaoma nifedadao ba zorugo ba ba dadaoma andrö ba so zidadao,[2]', '["Faigi 1:10; 20:11","Hes 1:26-28"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 3, 'ba sidadao andrö ba no hulö weremata yasibi ba hulö weremata aki andrö wamaigigu, ba no tefasui dumi dadaoma andrö hulö zumurudi wamaigigu.[3]', '["Faigi 1:10; 20:11","Hes 1:26-28"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 4, 'Ba no tefasui dadaoma andrö dadaoma bö''ö, dua wulu a öfa, ba dua wulu a öfa zatua, sidadao ba dadaoma andrö si so nukha safusi ba takula ana''a ba högöra.[4]', '["Faigi 11:16; 19:4"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 5, 'Ba si otorai dadaoma no mege, ba gari mbanua, ba li niha, ba fe''ugu-ugu mbanua, ba fitu zulu alitö sihola-hola föna dadaoma andrö, ya''ia Geheha Lowalangi andrö si fitu.[5]', '["Faigi 1:4"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 6, 'Ba föna dadaoma andrö ba hulö mbaŵa nidanö sörömi faoma ira mbaluri; ba ba dalu dadaoma, ba ba zi fasui dadaoma, ba öfa nga''eu zaliŵa-liŵa ba danö, no falawu hörö, he moroi föna, ba he moroi furi.[6]', '["Faigi 15:2; 5:6,8; Hes 1:5; 18:22","Hes 1:10"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 7, 'Si sageu ba hulö zingo; ba si sageu ba hulö nono zaŵi; ba bawa zi sageu ba hulö mbawa niha; ba si sambua ba hulö moyo sihombo.[7]', '["Faigi 15:2; 5:6,8; Hes 1:5; 18:22","Hes 1:10"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 8, 'Ba ba zaliŵa-liŵa ba danö andrö si öfa nga''eu, ba önö gafi zageu, ba no afönu ira hörö, fasui, ba mibakha, ba lö labato-bato bongi ma''ökhö, lamane: Ni''amoni''ö, ni''amoni''ö, ni''amoni''ö Zo''aya, Lowalangi, samatörö fefu hadia ia, si no so föna, ba si so iada''e, ba si moi dania![8]', '["Hes 1:6,11; Yes 6:2-3; Faigi 1:4"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 9, 'Ba ero na labe''e saliŵa-liŵa ba danö lakhömi ba sumange ba fangandrö saohagölö ba zidadao andrö ba dadaoma sauri irugi zi lö aetu,[9]', '["Faigi 4:2; 5:14","Faigi 5:12,13; Yoh 1:3"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 10, 'ba latuhi danö satua andrö si dua wulu a öfa föna zidadao andrö ba dadaoma andrö mangalulu ira khö zauri andrö irugi zi lö aetu ba latou''ö tou dakulara no mege föna dadaoma ba lamane:', '["Faigi 4:2; 5:14","Faigi 5:12,13; Yoh 1:3"]', NULL),
  (3392260, 'NT', 'Fama''ele''ö', 4, 11, 'No sinangea manema ndra''ugö lakhömi ba sumange ba fa''abölö, ya''ugö So''aya ya''aga, Lowalangima, me no ya''ugö zamazökhi fefu hadia ia ba börö nilau dödöu wa so ia awö wa tefazökhi ia.[10]', '["Faigi 4:2; 5:14","Faigi 5:12,13; Yoh 1:3"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 1, 'Ba u''ila ba danga zidadao ba dadaoma andrö ba dangania kambölö, zura, nisura tanö bakha ba tanö baero si no mufotandro, fitu dandronia.[1]', '["Faigi 4:2,9; Hes 2:9,10"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 2, 'Ba u''ila mala''ika sabölö, si''ao, ebua linia, imane: Ha niha zi nangea mamokai sura andrö, ba si nangea mamo''a tandronia andrö?', '[]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 3, 'Ba lö sangila, he ba zorugo, ba he ba guli danö, ba he barö danö, lö sangila mamokai sura andrö ba famaigi ya''ia.', '[]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 4, 'Ba mege-ege sibai ndra''odo me lö falukha zi nangea mamokai sura andrö ba famaigi ya''ia.', '["Faigi 4:4; 22:16; MozI 49:9,10; Rom 15:12"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 5, 'Ba imane khögu satua andrö, si samösa: Böi e''e; hiza, no möna zingo andrö, mado Yuda, lewiö ba ŵa''a Dawido andrö, ba wamokai sura andrö, ba tandro andrö, si fitu.[2]', '["Faigi 4:4; 22:16; MozI 49:9,10; Rom 15:12"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 6, 'Ba u''ila ba dalu dadaoma andrö, ba ba gotalua zaliŵa-liŵa ba danö andrö, si öfa nga''eu, ba ba gotalua zatua andrö Nono mbiri-biri, sizizio, hulö nitaba, fitu dandrunia, ba fitu hörö, ya''ia Geheha Lowalangi andrö si fitu nifatenge ba guli danö ma''asagörö.[3]', '["Faigi 22:1; 1:4; Yoh 1:29; Sakh 3:9; 4:10"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 7, 'Ba so ia, ba ihalö zura andrö, ba danga zidadao ba dadaoma andrö, ba dangania kambölö.', '[]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 8, 'Ba me ihalö zura andrö, ba latuhi danö saliŵa-liŵa ba danö andrö, si öfa nga''eu, ba satua andrö, si dua wulu a öfa, föna Nono mbiri-biri andrö, no dozi ira biola ba figa ana''a, si no afönu kumöyö, ya''ia wangandrö niha ni''amoni''ö andrö.[4]', '["Faigi 4:9,10; 14:2; 8:3,4","Faigi 14:3,4; HalZin 20:28; Kol 1:14; FetI 1:18,19","Faigi 1:5,6; 20:6; FetI 2:9"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 9, 'Ba manunö ira, sinunö si bohou, lamane: No si nangea ndra''ugö ba wangai sura andrö ba ba wamokai tandronia; me no mutaba ndra''ugö, ba me no öhöli niha domö, khö Lowalangi, moroi ba ngawalö niwa fefu, ba moroi ba ngawalö li, ba moroi ba ngawalö mado, ba moroi ba ngawalö soi fefu,[5]', '["Faigi 4:9,10; 14:2; 8:3,4","Faigi 14:3,4; HalZin 20:28; Kol 1:14; FetI 1:18,19","Faigi 1:5,6; 20:6; FetI 2:9"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 10, 'ba no öbali''ö banua Lowalangida ba ere ira, ba salaŵa ira dania, ba guli danö.[6]', '["Faigi 4:9,10; 14:2; 8:3,4","Faigi 14:3,4; HalZin 20:28; Kol 1:14; FetI 1:18,19","Faigi 1:5,6; 20:6; FetI 2:9"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 11, 'Ba u''ila ba urongo zi hulö li mala''ika si no ato, si fasui dadaoma andrö, ba saliŵa-liŵa ba danö andrö, ba satua andrö, ba fa''atora ba no mewulu ngahönö wa fulu ngahönö ba mehönö wa hönö;[7]', '["Dan 7:9,10","Faigi 4:11"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 12, 'ebua lira, lamane; No si nangea Nono mbiri-biri andrö si no mutaba ba wanema fa''abölö ba fo''ana''a ba fa''atua-tua ba fa''abe''e ba sumange ba lakhömi ba howu-howu![8]', '["Dan 7:9,10","Faigi 4:11"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 13, 'Ba fefu hadia ia nifazökhi Lowalangi si so ba zorugo, ba ba guli danö, ba barö danö, ba ba nasi, ba ösinia fefu, ba lamane urongo: Khö zidadao andrö, ba dadaoma andrö ba khö Nono mbiri-biri andrö, ba howu-howu, ba sumange, ba lakhömi, ba fa''abölö irugi zi lö aetu![9]', '["Faigi 7:10-12; Fil 2:10","Faigi 19:4"]', NULL),
  (3392261, 'NT', 'Fama''ele''ö', 5, 14, 'Ba lamane saliŵa-liŵa ba danö andrö si öfa nga''eu; Yaduhu! Ba latuhi danö satua andrö, mangalulu ira.[10]', '["Faigi 7:10-12; Fil 2:10","Faigi 19:4"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 1, 'Ba u''ila me ibokai dandro si föföna, ba zi fitu andrö, Ono mbiri-biri, ba urongo, me muhede zaliŵa-liŵa ba danö andrö, si sageu, hulö we''ugu-ugu mbanua linia, imane: Aine![1]', '["Faigi 5:1–5; 4:6 b.t."]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 2, 'Ba u''ila, ba hiza kudo safusi, ba khö zi fakudo yaŵa, ba so wana sinali, ba tebe''e khönia dakula, ba mofanö ia, si mane si möna, ba ena''ö möna ia.[2]', '["Faigi 19:11–16"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 3, 'Ba me ibokai dandro fanete zi föföna, ba urongo me iŵa''ö saliŵa-liŵa ba danö andrö, si sageu: Aine!', '[]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 4, 'Ba so zi möi baero kudo bö''ö, soyo, ba khö zi fakudo yaŵa, ba tetehe wangeheta fa''atulö ba guli danö, ba ena''ö faoma labubunu nawöra, ba tebe''e khönia wöda sebua.', '[]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 5, 'Ba me ibokai dandro fanete zi dombua, ba urongo me iŵa''ö saliŵa-liŵa ba danö andrö, fanete zi dua geu: Aine! Ba u''ila, ba hiza kudo saitö, ba khö zi fakudo yaŵa, ba so wali''era ba danga.', '[]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 6, 'Ba urongo zi hulö li niha moroi ba gotalua zaliŵa-liŵa ba danö andrö si öfa nga''eu, imane: Sasuku zi samba hinaoya böra, ba sasuku göi zi tölu hinaoya rigi, ba fanikha andrö ba agu, ba böi fakiko.', '[]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 7, 'Ba me ibokai dandro fanete zi tölu, ba urongo li zaliŵa-liŵa ba danö andrö, fanete zi tölu nga''eu, imane: Aine!', '["Hes 14:21"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 8, 'Ba u''ila, ba hiza kudo sa''uzö-uzö, ba töi zi fakudo yaŵa, ba fa''amate, ba i''o''ö ia banua tou, ba tetehe khöra zi sambua ni''o''öfa tanö ba wamunu ya''ira föda ba lofo ba fökhö ba ba gutu ndru''u andrö ba guli danö.[3]', '["Hes 14:21"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 9, 'Ba me ibokai dandro fanete zi öfa, ba u''ila barö naha wame''e sumange andrö mbekhu nibubunu ba daroma li Lowalangi andrö ba ba wamaduhu''ö andrö si so khöra.[4]', '["Faigi 1:9","Faigi 3:7; 19:2; Sin 79:10","Faigi 3:5; Heb 11:40"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 10, 'Ba mu''ao ira, ebua lira, lamane: He So''aya, ni''amoni''ö, si ndruhu! ha wa''ara tö na lö manguhuku ndra''ugö, ba lö ölau mbalö ndroma andrö, ba zowanua ba guli danö andrö?[5]', '["Faigi 1:9","Faigi 3:7; 19:2; Sin 79:10","Faigi 3:5; Heb 11:40"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 11, 'Ba tedozigö ira baru safusi, ba laŵa''ö khöra, ena''ö lataha na dödöra, ma''ifu tö, irege mo''ahonoa, ha wa''ato nawöra enoni göi ba talifusöra, nibubunu na dania göi, si mane ya''ira göi.[6]', '["Faigi 1:9","Faigi 3:7; 19:2; Sin 79:10","Faigi 3:5; Heb 11:40"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 12, 'Ba u''ila, me ibokai dandro fanete zi lima, ba so ziheu sabölö-bölö, ba tobali aitö luo, hulö goni-goni bu, ba tobali hulö ndro mbaŵa ma''asambua.[7]', '["Faigi 16:18; Yes 13:13,10; Mat 24:29; Yoel 2:10","Yes 34:4; Sin 102:27; Faigi 16:20"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 13, 'Ba atoru ba danö ndröfi moroi ba mbanua si yaŵa, hulö na atoru mbua marafala na ifadögö angi sabölö-bölö.', '["Faigi 16:18; Yes 13:13,10; Mat 24:29; Yoel 2:10","Yes 34:4; Sin 102:27; Faigi 16:20"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 14, 'Ba aheta mbanua si yaŵa, hulö na lagölugö zura ba hili misa fefu, ba hulo fefu, ba awu''a ba nahara.[8]', '["Faigi 16:18; Yes 13:13,10; Mat 24:29; Yoel 2:10","Yes 34:4; Sin 102:27; Faigi 16:20"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 15, 'Ba razo ba guli danö, ba sebua, ba kumandra andrö, ba so''ana''a, ba sabölö, ba sawuyu fefu, ba si tenga sawuyu fefu, ba labini''ö ira ba dögi hili misa, ba barö gara ba hili.[9]', '["Yes 2:19","Faigi 9:6; Hos 10:8; Luk 23:30; Sin 2","Sef 1:14"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 16, 'Ba lamane ba hili ba ba gara andrö: Milangögö ndra''aga, mibalugö ndra''aga, fa böi i''ilaga sidadao ba dadaoma andrö, ba fa lö gönaga fönu Nono mbiri-biri andrö.[10]', '["Yes 2:19","Faigi 9:6; Hos 10:8; Luk 23:30; Sin 2","Sef 1:14"]', NULL),
  (3392269, 'NT', 'Fama''ele''ö', 6, 17, 'Noa sa irugi baŵa sebua andrö, baŵa wönura, ba ha niha zanaha?[11]', '["Yes 2:19","Faigi 9:6; Hos 10:8; Luk 23:30; Sin 2","Sef 1:14"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 1, 'Ba aefa da''ö, ba öfa u''ila mala''ika, si so ba watalinga danö andrö si öfa, sanaha angi ba danö andrö, si öfa, fa lö itörö angi danö ba asi ba hogu geu fefu.[1]', '["Sakh 6:5","Faigi 5:2","Faigi 9:4; Hes 9:4","Faigi 14:1"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 2, 'Ba u''ila mala''ika bö''ö, si möi miyaŵa, moroi ba gatumbukha luo, si so tandro khö Lowalangi sauri, ba mu''ao ia, ebua linia, ba mala''ika andrö, si öfa, ba nitehe famakiko uli danö ba asi,[2]', '["Sakh 6:5","Faigi 5:2","Faigi 9:4; Hes 9:4","Faigi 14:1"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 3, 'imane: Böi mifakiko guli danö, ba he asi, ba he eu andrö, irege no mafotandro genoni Lowalangida andrö, ba gangangora![3]', '["Sakh 6:5","Faigi 5:2","Faigi 9:4; Hes 9:4","Faigi 14:1"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 4, 'Ba urongo wa''ato nifotandro andrö, otu a öfa wulu a öfa ngahönö nifotandro, tedozigö mado Ndraono Gizeraeli andrö:[4]', '["Sakh 6:5","Faigi 5:2","Faigi 9:4; Hes 9:4","Faigi 14:1"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 5, 'Mado Yuda, ba felendrua ngahönö nifotandro, ba mado Rubeno, ba felendrua ngahönö, ba mado Gado, ba felendrua ngahönö,[5]', '["MozII 1:1–4","MozI 49:22"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 6, 'ba mado Gaseri, ba felendrua ngahönö, ba mado Nafetali, ba felendrua ngahönö ba mado Manase, ba felendrua ngahönö,', '["MozII 1:1–4","MozI 49:22"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 7, 'ba mado Zimeoni, ba felendrua ngahönö, ba mado Lewi, ba felendrua ngahönö, ba mado Isasari,', '["MozII 1:1–4","MozI 49:22"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 8, 'ba felendrua ngahönö, ba mado Zebuloni, ba felendrua ngahönö, ba mado Yosefo, ba felendrua ngahönö, ba mado Mbeniyami, ba felendrua ngahönö nifotandro.[6]', '["MozII 1:1–4","MozI 49:22"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 9, 'Ba aefa da''ö, ba u''ila, ba hiza zato sibai, si tebai i''erai niha, moroi ba ngawalö soi fefu, ba moroi ba ngawalö niwa fefu, ba moroi ba ngawalö mado fefu, ba moroi ba ngawalö li fefu, si so föna dadaoma andrö ba föna Nono mbiri-biri; nukha safusi nukhara, ba bulu nohi ba dangara.[7]', '["Faigi 5:9; 3:5,18; Mat 28:19","Faigi 5:13; 19:1","Faigi 5:11","Faigi 4:9 b.t.; 5:12 b.t."]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 10, 'Ba mu''ao ira, ebua lira, lamane: Fangorifi khö Lowalangida, sidadao ba dadaoma andrö, ba khö Nono mbiri-biri andrö![8]', '["Faigi 5:9; 3:5,18; Mat 28:19","Faigi 5:13; 19:1","Faigi 5:11","Faigi 4:9 b.t.; 5:12 b.t."]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 11, 'Ba no lafasui dadaoma andrö mala''ika andrö fefu, ba satua andrö, ba saliŵa-liŵa ba danö andrö, si öfa nga''eu, ba latuhi danö föna dadaoma andrö, lafalögu tou ira, mangalulu ira khö Lowalangi,[9]', '["Faigi 5:9; 3:5,18; Mat 28:19","Faigi 5:13; 19:1","Faigi 5:11","Faigi 4:9 b.t.; 5:12 b.t."]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 12, 'lamane: Yaduhu, howu-howu, ba lakhömi, ba fa''atua-tua, ba fangandrö saohagölö, ba sumange, ba fa''abölö, ba fa''abe''e, khö Lowalangida, irugi zi lö aetu! Yaduhu.[10]', '["Faigi 5:9; 3:5,18; Mat 28:19","Faigi 5:13; 19:1","Faigi 5:11","Faigi 4:9 b.t.; 5:12 b.t."]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 13, 'Ba humede zatua andrö, samösa, imane khögu: Da''ö, si so baru safusi andrö, ha niha ira, ba heza la''otarai?', '[]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 14, 'Ba umane khönia: Ya''ugö zangila, Tuha. Ba imane khögu: Ya''ira da''ö, si otarai wamakao sabölö-bölö andrö; ba no lababago mbarura, ba no la''afusi''ö, ba ndro Nono mbiri-biri andrö.[11]', '["KorII 4:8,17; YohI 1:7","Faigi 21:3","Yes 49:10; Sin 121:5,6","Faigi 5:6; 21:6,4; Sin 23:2; Yes 25:8"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 15, 'Da''ö mbörö, wa no so ira föna dadaoma Lowalangi andrö, awö wa no enoninia ira, bongi ma''ökhö, ba gosalinia; ba i''iagö yaŵara sidadao ba dadaoma andrö.[12]', '["KorII 4:8,17; YohI 1:7","Faigi 21:3","Yes 49:10; Sin 121:5,6","Faigi 5:6; 21:6,4; Sin 23:2; Yes 25:8"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3392270, 'NT', 'Fama''ele''ö', 7, 16, 'Lö''ö sa''ae olofo ira, ba lö''ö sa''ae owökhi dödöra, ba lö göna ira sino, ba he fa''aukhu, hadia ia,[13]', '["KorII 4:8,17; YohI 1:7","Faigi 21:3","Yes 49:10; Sin 121:5,6","Faigi 5:6; 21:6,4; Sin 23:2; Yes 25:8"]', NULL),
  (3392270, 'NT', 'Fama''ele''ö', 7, 17, 'me ikubaloi sa''ae ira Ono mbiri-biri andrö, si so ba dalu dadaoma andrö, ba ifasao ira ba gumbu nidanö fangorifi, ba Lowalangi zolosi dania fefu daŵa hörö ba höröra andrö.[14]', '["KorII 4:8,17; YohI 1:7","Faigi 21:3","Yes 49:10; Sin 121:5,6","Faigi 5:6; 21:6,4; Sin 23:2; Yes 25:8"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 1, 'Ba me ibokai dandro fanete zi önö, ba tobali ahono ba zorugo, so tanga za wa''ara.[1]', '["Faigi 6:1"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 2, 'Ba u''ila mala''ika andrö si dafitu si so föna Lowalangi ba tebe''e khöra dorofe, fitu.[2]', '["Luk 1:19; Mat 24:31","Faigi 5:8","Sin 141:2","Faigi 11:19"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 3, 'Ba so moroi sa mala''ika bö''ö, ba i''agö zinga naha wame''e sumange, ba so khönia, mako ba wanunu kumöyö, ana''a, ba labe''e khönia gumöyö, la''oya''ö, ena''ö ibe''e fonönö wangandrö niha ni''amoni''ö andrö, ena''ö idozigö, ba naha wame''e sumange, ana''a andrö, föna dadaoma andrö.[3]', '["Luk 1:19; Mat 24:31","Faigi 5:8","Sin 141:2","Faigi 11:19"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 4, 'Ba möi miyaŵa zimbo gumöyö andrö, fonönö wangandrö niha ni''amoni''ö, moroi ba danga mala''ika andrö, föna Lowalangi.[4]', '["Luk 1:19; Mat 24:31","Faigi 5:8","Sin 141:2","Faigi 11:19"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 5, 'Ba ihalö mako andrö, ba wanunu kumöyö, mala''ika andrö, ifo''ösi alitö, moroi ba naha wame''e sumange no mege, ba itibo''ö tou ba danö, ba so we''ugu-ugu mbanua, ba li niha, ba gari mbanua, ba duru danö.[5]', '["Luk 1:19; Mat 24:31","Faigi 5:8","Sin 141:2","Faigi 11:19"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 6, 'Ba lafa''anö ira, ba wolau torofe, mala''ika andrö, si dafitu, si so torofe andrö, si fitu.', '[]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 7, 'Ba ilau dorofe si föföna andrö, ba ilabu teu kara ba alitö, si faruka do, ba aekhu ba danö. Ba saraö akhozi tanö, ba saraö döla geu akhozi ba du''u sauri, fefu, ba akhozi.[6]', '["MozII 9:23 b.t","Faigi 9:1"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 8, 'Ba ilau dorofe mala''ika si samösa, fanete zi föföna, ba tetibo''ö ba nasi zi hulö hili sebua, si hola-hola, ba tobali do zi saraö nasi,', '["MozII 9:23 b.t","Faigi 9:1"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 9, 'ba saliŵa-liŵa ba nasi andrö, si so noso, ba saraö zi mate, ba owo andrö, ba saraö zaboto.', '["MozII 9:23 b.t","Faigi 9:1"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 10, 'Ba ilau dorofe mala''ika fanete zi darua andrö, ba so zatoru moroi ba mbanua si yaŵa döfi sebua, sihola-hola, hulö zulu, ba göna ba zi saraö nungo nidanö, ba ba nulu nidanö andrö,[7]', '["MozII 9:23 b.t","Faigi 9:1"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 11, 'Ba töi ndröfi andrö, ba Abesindro, ba tobali Abesindro zi saraö nidanö andrö, ba ato zi mate niha, ba nidanö andrö, me no afeto.', '["MozII 9:23 b.t","Faigi 9:1"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 12, 'Ba ilau dorofe mala''ika fanete zi datölu andrö, ba tebözi zi saraö luo, ba si saraö mbaŵa, ba si saraö ndröfi, ena''ö aitö zi saraö ba ena''ö lö moluo zi saraö zi ma''ökhö, ba si manö göi ba zi bongi.', '["MozII 9:23 b.t","Faigi 9:1"]', NULL),
  (3392271, 'NT', 'Fama''ele''ö', 8, 13, 'Ba u''ila, ba urongo moyo sambua, sihombo ba dalu mbanua, mu''ao ia, ebua linia, imane: Alai, alai, alai zowanua ba guli danö, ba li dorofe si tosai andrö, ba mala''ika si datölu andrö, solau dania![8]', '["Faigi 9:12; 11:14; 12:14"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 1, 'Ba ilau dorofe mala''ika fanete zi daöfa, ba u''ila ndröfi, si no atoru tou ba danö, moroi ba mbanua si yaŵa, ba tebe''e khönia wogoe mbawa gawuwukha andrö.[1]', '["Faigi 8:10; 20:1","Yoel 2:5 b.t.","Faigi 7:3 b.t.","Faigi 6:16"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 2, 'Ba ikoe mbawa gawuwukha andrö, ba möi miyaŵa zimbo, moroi ba mbawania, hulö zimbo zino wa''u sebua; ba tobali aitö luo, ba talu mbanua, ba zimbo mbawania andrö.', '["Faigi 8:10; 20:1","Yoel 2:5 b.t.","Faigi 7:3 b.t.","Faigi 6:16"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 3, 'Ba so zi otarai zimbo andrö tamo, si möi ba danö, ba tebe''e khöra wa''abölö, si mane fa''abölö dongo ba danö,[2]', '["Faigi 8:10; 20:1","Yoel 2:5 b.t.","Faigi 7:3 b.t.","Faigi 6:16"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 4, 'ba teŵa''ö khöra, ena''ö böi lafakiko ndru''u ba danö, ba he sobulu, fefu, ba he eu, fefu; ha niha andrö nifakiko, si lö tandro Lowalangi andrö, ba gangango.[3]', '["Faigi 8:10; 20:1","Yoel 2:5 b.t.","Faigi 7:3 b.t.","Faigi 6:16"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 5, 'Ba tetehe khöra, ena''ö böi labunu, ha lafakao, lima waŵa wa''ara. Ba fa''afökhö andrö ba khöra, ba no timba wa''afökhö ba dongo, na ituo niha.', '["Faigi 8:10; 20:1","Yoel 2:5 b.t.","Faigi 7:3 b.t.","Faigi 6:16"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 6, 'Ba na luo da''ö, ba la''alui wa''amate niha, ba lö lasöndra, omasi ira mate, ba i''aröu''ö ia khöra fa''amate.[4]', '["Faigi 8:10; 20:1","Yoel 2:5 b.t.","Faigi 7:3 b.t.","Faigi 6:16"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 7, 'Ba nga''eu damo andrö, ba hulö kudo, ni''aro''ö ba wanuwö, ba ba högöra, ba takula, hulö gana''a, ba bawara, ba hulö mbawa niha.[5]', '["Yoel 2:4,5","Efes 2:2; Yob 28:22"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 8, 'Ba bura, ba hulö mbu ndra alawe, ba iföra, ba hulö nifö zingo.', '["Yoel 2:4,5","Efes 2:2; Yob 28:22"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 9, 'Ba mo''öröba ira, hulö göröba si''öli, ba ruru gafira andrö, ba hulö ruru gureta soya kudo, si mandruo, ba wanuwö.', '["Yoel 2:4,5","Efes 2:2; Yob 28:22"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 10, 'Ba i''ora, ba hulö gi''o dongo, ba motuo, ba ba gi''ora so wa''abölöra, ba wamakiko niha, lima waŵa wa''ara.', '["Yoel 2:4,5","Efes 2:2; Yob 28:22"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 11, 'So zolohe ya''ira, razo, mala''ika gawuwukha, si so töi Abado, ba li Heberaio, ba ba li Ndrawa Heleni, ba Afolio döinia andrö.[6]', '["Yoel 2:4,5","Efes 2:2; Yob 28:22"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 12, 'No numalö wa''afökhö si föföna andrö, hiza dua balö tö wa''afökhö furi da''ö.[7]', '["Faigi 8:13"]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 13, 'Ba ilau dorofe mala''ika fanete zi dalima, ba urongo li, moroi ba dandru andrö, si öfa, ba naha wame''e sumange, ana''a andrö, föna Lowalangi,', '["Faigi 7:1; 16:12","Faigi 8:7-12","Faigi 5:11","Faigi 16:9,11; KorI 10:20; Sin 115:4 b.t."]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 14, 'imane ba mala''ika fanete zi dalima andrö, si so torofe andrö: Efa''ö mala''ika andrö, si daöfa, niböbö ba zinga nungo nidanö sebua andrö, Oifarati.[8]', '["Faigi 7:1; 16:12","Faigi 8:7-12","Faigi 5:11","Faigi 16:9,11; KorI 10:20; Sin 115:4 b.t."]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 15, 'Ba te''efa''ö mala''ika andrö, si daöfa, si no mama''anö, hadia wa''alaŵa luo, ba hadia luo, ba hadia mbaŵa, ba hadia ndröfi, ba wamunu si saraö niha.[9]', '["Faigi 7:1; 16:12","Faigi 8:7-12","Faigi 5:11","Faigi 16:9,11; KorI 10:20; Sin 115:4 b.t."]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 17, 'Ba si mane wangilagu kudo andrö, ba gangilata andrö, awö zi fakudo yaŵa: no mo''öröba alitö ba sohandru ba sa''usö, si mane talö balera; ba högö kudo, ba no hulö högö zingo, ba i''otarai mbawara alitö ba simbo ba talö balera.', '["Faigi 7:1; 16:12","Faigi 8:7-12","Faigi 5:11","Faigi 16:9,11; KorI 10:20; Sin 115:4 b.t."]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 18, 'Ba wamakao si tölu balö andrö tebunu zi saraö niha, ba galitö andrö, ba ba zimbo andrö, ba ba dalö balera andrö, si otarai mbawara.', '["Faigi 7:1; 16:12","Faigi 8:7-12","Faigi 5:11","Faigi 16:9,11; KorI 10:20; Sin 115:4 b.t."]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 19, 'Fa''abölö kudo andrö sa, ba ba mbawara so, ba ba gi''ora; i''ora sa, ba no hulö gulö, mohögö; ba da''ö wamakiko.', '["Faigi 7:1; 16:12","Faigi 8:7-12","Faigi 5:11","Faigi 16:9,11; KorI 10:20; Sin 115:4 b.t."]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 20, 'Ba si tosai niha, si lö mubunu, ba wamakao andrö, ba lö lafalalini gera-erara, ba wamöhöi mena''ö nifazökhi dangara andrö, ena''ö lö''ö sa''ae mangalulu ira ba mbekhu, ba ba nadu andrö ba nadu balaki, ba ba nadu firö, ba ba nadu aramba, ba na nadu kara, ba ba nadu eu andrö, si lö mangila niha, ba si lö mamondrongo li niha, ba si tebai mowaö-waö.[11]', '["Faigi 7:1; 16:12","Faigi 8:7-12","Faigi 5:11","Faigi 16:9,11; KorI 10:20; Sin 115:4 b.t."]', NULL),
  (3392272, 'NT', 'Fama''ele''ö', 9, 21, 'Ba lö lafalalini gera-erara, ba wamöhöi mena''ö fange''era andrö, awö wakelemusa andrö khöra, awö wohorö-horö andrö, awö wanagö-nagö andrö khöra.', '["Faigi 7:1; 16:12","Faigi 8:7-12","Faigi 5:11","Faigi 16:9,11; KorI 10:20; Sin 115:4 b.t."]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 1, 'Ba u''ila mala''ika bö''ö, sabölö, si möi mitou moroi ba mbanua si yaŵa, lawuo nukhania, ba dumi ba högönia yaŵa, ba bawania, ba no hulö luo, ba ahenia, ba no hulö daru nahe alitö.', '[]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 2, 'Ba so ba dangania zura side-ide, si no teboka, ba ihundragö nasi ahenia kambölö, ba ba danö so gahenia kabera.', '[]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 3, 'Ba mu''ao ia, ebua linia, hulö na mundröndrö-ndröndrö zingo; ba me no mu''ao ia, ba humede we''ugu-ugu mbanua andrö, si fitu, alua lira.', '[]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 4, 'Ba me no humede we''ugu-ugu mbanua andrö, si fitu, ba manurado mena''ö, ba urongo li, moroi ba mbanua si yaŵa, imane: Fotandro niŵa''ö we''ugu-ugu mbanua andrö, si fitu, ba böi sura ia.', '[]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 5, 'Ba ifazaŵa dangania kambölö mala''ika andrö, ni''ilagu, si hundragö asi ba tanö, ituturu mbanua, si yaŵa,', '["Faigi 8:2; 11:15; KorI 15:52"]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 6, 'ba fahölu ba zauri andrö, irugi zi lö aetu, samazökhi banua si yaŵa ba ösinia ba tanö ba ösi guli danö ba asi ba ösinia: wa lö nga''ötö danö sa''ae;', '["Faigi 8:2; 11:15; KorI 15:52"]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 7, 'na luo li mala''ika fanete zi daönö sa, na ilau dorofe dania, ba no alua göi zi no tobini andrö, khö Lowalangi, itörö ni''ombakha''önia, turia somuso dödö, ba genoninia andrö, sama''ele''ö.[1]', '["Faigi 8:2; 11:15; KorI 15:52"]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 8, 'Ba humede zui khögu li andrö, nirongogu moroi ba mbanua si yaŵa, imane: Ae halö zura side-ide andrö, si no teboka, ba danga mala''ika andrö, si hundragö asi ba tanö.', '[]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 9, 'Ba möido khö mala''ika andrö, uŵa''ö khönia, ena''ö ibe''e khögu zura side-ide andrö.', '[]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 10, 'Ba uhalö zura side-ide andrö, ba danga mala''ika andrö, ba utölö, ba ba mbawagu, ba ami, hulö ŵe ŵani, ba me no utölö, ba afeto mbetu''agu.', '[]', NULL),
  (3392273, 'NT', 'Fama''ele''ö', 10, 11, 'Ba lamane khögu: Lö tola lö öfuli mama''ele''ö, ba ngawalö mado, ba ba ngawalö soi, ba ba ngawalö li, ba ba razo soya.', '[]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 1, 'Ba labe''e khögu zukhu, hulö zi''o, ba lamane khögu: Faoso ba su''a gosali Lowalangi andrö, awö naha wame''e sumange, awö zangalulu bakha;[1]', '["Faigi 21:15; Sakh 2:1 b.t.; Hes 43:13","Luk 21:24; Faigi 13:5; Dan 8:13 b.t."]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 2, 'ba olayama gosali tanö baero, ba be''e baero, ba böi su''a ia, me nibe''e ba danga niha baero, ba lahundragö dania mbanua ni''amoni''ö andrö, öfa wulu a rua waŵa wa''ara.[2]', '["Faigi 21:15; Sakh 2:1 b.t.; Hes 43:13","Luk 21:24; Faigi 13:5; Dan 8:13 b.t."]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 3, 'Ba ube''e ba zamaduhu''ö andrö khögu, si darua, ba mama''ele''ö ira, hönö a dua ngaotu a önö ngafulu wongi wa''ara, goni-goni mbarura.[3]', '["Faigi 12:6,14; Yoel 1:13","Sakh 4:3,11,14","RazII 1:10,12; Yer 5:14","RazI 17:1; MozII 7:19"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 4, 'Da''ö zi dua geu töla falo andrö, ba si dombua naha wandru andrö, si so föna Zo''aya tanö.[4]', '["Faigi 12:6,14; Yoel 1:13","Sakh 4:3,11,14","RazII 1:10,12; Yer 5:14","RazI 17:1; MozII 7:19"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 5, 'Ba na so zamakiko ya''ira ena''ö, ba i''otarai mbawara alitö, ba i''a zi fa''udu khöra; na so zamakiko ya''ira ena''ö, ba si manö wamununia.[5]', '["Faigi 12:6,14; Yoel 1:13","Sakh 4:3,11,14","RazII 1:10,12; Yer 5:14","RazI 17:1; MozII 7:19"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 6, 'No mutehe khöra andrö wokusi banua si yaŵa, fa lö aekhu ba danö deu, götö mbaŵa wama''ele''öra andrö; ba no mutehe khöra nidanö andrö, ba wamali''ö do ya''ia, ba famatörö ba danö famakao, fefu, hadia ia, ha wa''asese zomasi ira.[6]', '["Faigi 12:6,14; Yoel 1:13","Sakh 4:3,11,14","RazII 1:10,12; Yer 5:14","RazI 17:1; MozII 7:19"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 7, 'Ba na no la''o''ozui wamaduhu''öra andrö, ba isuwö ira saliŵa-liŵa ba danö andrö, si otarai moroi si tou gawuwukha, ba ya''ia zi möna, ibunu ira.[7]', '["Faigi 13:1-8; 17:8; Dan 7:21","Faigi 16:19; Sin 79:2; KorI 2:8"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 8, 'Ba botora, ba tou ba newali so, ba mbanua sebua andrö, nifotöi Sodoma ba tanö Miserayi, amaedola, ba niforöfa göi So''aya ya''ira.[8]', '["Faigi 13:1-8; 17:8; Dan 7:21","Faigi 16:19; Sin 79:2; KorI 2:8"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 9, 'Ba la''ila mbotora andrö niha, ha mado ira, ba ha iwa, ba hadia lira, ba ha soi, tölu ngaluo a matonga wa''ara, ba lö labe''e niko''o mbotora andrö.[9]', '["Dan 7:21","Esit 9:19"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 10, 'Ba omuso dödö niha, sowanua ba guli danö, ba khöra andrö, owua-wua dödöra, ba faoma mama''ohe''ö buala ira khö nawöra, me no lafakao zowanua ba guli danö sama''ele''ö andrö, si darua.[10]', '["Dan 7:21","Esit 9:19"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 11, 'Ba me no aefa zi dua ngaluo a matonga, ba isaŵa ira noso fangorifi, moroi ba Lowalangi, ba muzizio ira, ba ihawui fa''ata''u sabölö-bölö zamaigi ya''ira.', '[]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 12, 'Ba larongo li sebua, moroi ba mbanua si yaŵa, imane khöra: Mi''ae miyaŵa ba da''e! Ba möi ira yaŵa ba zorugo, ba lawuo; ba lafaigi ira si fa''udu khöra andrö.', '[]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 13, 'Ba faudu da''ö, ba so ziheu sabölö-bölö, ba sambua ni''ofulu mbanua adudu, ba fitu ngahönö zi mate niha, ba ziheu andrö, ba si tokea zi tosai, ba lafosumange Lowalangi zorugo andrö.[11]', '["Faigi 9:20; 16:18; Mat 27:52","Faigi 9:12"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 14, 'No numalö wa''afökhö fanete zi föföna andrö, hiza, alio itörö fa''afökhö fanete zi dua balö andrö.[12]', '["Faigi 9:20; 16:18; Mat 27:52","Faigi 9:12"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 15, 'Ba ilau dorofe mala''ika fanete zi daönö, ba terongo li segebua ba zorugo, lamane: No möi khö Zo''aya ya''ita wamatörö andrö, ba guli danö, ba khö nibayoini andrö khönia, ba razo ia, irugi zi lö aetu.[13]', '["Faigi 10:7; 12:10; Dan 2:44; 7:27"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 16, 'Ba latuhi danö, lafalögu tou ira satua andrö, si dua wulu a öfa, sidadao föna Lowalangi, ba dadaomara andrö, mangalulu ira khö Lowalangi,[14]', '["Faigi 4:4,10","Faigi 4:8; 19:4,6"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 17, 'lamane: Ma''andrö saoha gölö khöu, ya''ugö So''aya, Lowalangi, samatörö fefu, hadia ia, si so, ba si no so föna, me no öhalö khöu wa''abölö andrö khöu, si no ebua, ba me no razo ndra''ugö.[15]', '["Faigi 4:4,10","Faigi 4:8; 19:4,6"]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 18, 'Ba no mofönu soi niha baero; ba no tesao wönumö, ba no irugi inöto, ba zi mate andrö, ena''ö tehuku ira, ba ena''ö öbe''e luo andrö, ba genoniu andrö, sama''ele''ö, awö ni''amoni''ö, awö zangata''ufi töimö andrö, he side-ide, ba he sebua, ba ena''ö öfakiko zamakiko uli danö andrö.[16]', '["Faigi 6:17; 20:12 b.t.; 14:7; Dan 7:9 b.t."]', NULL),
  (3392274, 'NT', 'Fama''ele''ö', 11, 19, 'Ba tebokai gosali Lowalangi andrö, ba zorugo, ba oroma dawöla gamabu''ula li andrö khönia, ba gosalinia andrö; ba so gari mbanua, ba li niha, ba fe''ugu-ugu mbanua, ba siheu, ba teu kara sabölö-bölö.[17]', '["Faigi 15:5,8; Heb 9:4; Faigi 16:18,21"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 1, 'Ba oroma dandra sebua ba zorugo, ira alawe sonukha luo, ba baŵa barö gahenia, ba ba högönia, ba no felendrua ndröfi, bala högönia.', '[]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 2, 'Ba no manabina, ba mangarö-ngarö ia, ba wa''afökhö hulu ba ba wa''afökhö wadono.', '[]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 3, 'Ba oroma dandra bö''ö ba zorugo, hiza naga sebua so''alitö fitu högö ba fulu rozi dandru, ba ba högönia ba fitu naya.[1]', '["Faigi 13:1 b.t.; Faigi 17:9 b.t.; Dan 7:7","Faigi 2:27; Sin 2:8-9"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 4, 'Ba i''onia, ba ibözini zi saraö ndröfi ba mbanua si yaŵa, itibo''ö tou ba danö. Ba i''agö föna ndra alawe no mege, sadono, naga andrö ba wemanga ono andrö na tumbu.', '["Faigi 13:1 b.t.; Faigi 17:9 b.t.; Dan 7:7","Faigi 2:27; Sin 2:8-9"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 5, 'Ba madono ia ono matua, sokubaloi dania fefu soi si''o si''öli. Ba te''ohe khö Lowalangi nononia andrö, föna dadaomania.[2]', '["Faigi 13:1 b.t.; Faigi 17:9 b.t.; Dan 7:7","Faigi 2:27; Sin 2:8-9"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 6, 'Ba moloi ndra alawe andrö, isaŵa danö si mate ba zi so naha khönia ni''asiwai Lowalangi, ena''ö labe''e gönia ba da''ö hönö a dua ngaotu a önö ngafulu wongi.[3]', '["Faigi 11:3"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 7, 'Ba tesao wanuwö ba mbanua si yaŵa: Mikha''eli andrö ba mala''ikania, ba fasuwö ba naga andrö. Ba fasuwö naga andrö awö mala''ikania.[4]', '["Dan 10:13,21; 12:1; Yud 9","Faigi 20:2; Luk 10:18; Yoh 12:31; KorII 11:3"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 8, 'Ba tebai ira, ba lö nahara sa''ae ba mbanua si yaŵa.', '["Dan 10:13,21; 12:1; Yud 9","Faigi 20:2; Luk 10:18; Yoh 12:31; KorII 11:3"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 9, 'Ba tetibo''ö naga sebua andrö, ulö satua andrö, sotöi Afökha ba Satana, samaelungu niha ba guli danö fefu; tetibo''ö si tou ia ba danö ba tetibo''ö göi mala''ikania andrö awönia.[5]', '["Dan 10:13,21; 12:1; Yud 9","Faigi 20:2; Luk 10:18; Yoh 12:31; KorII 11:3"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 10, 'Ba urongo li sebua, ba zorugo, imane: "Awena to''ele wangorifi andrö khö Lowalangida, ba fa''abölö andrö ba famatörö andrö; ba fa''atola andrö, khö nibayoini andrö khönia; me no tetibo''ö zangadugö talifusöda, si no mangadu-ngadugö ya''ira khö Lowalangida andrö, bongi ma''ökhö."[6]', '["Faigi 11:15; Sakh 3:1 b.t.; Yob 1:9 b.t.","Faigi 7:14; 2:10; Rom 8:33,34,37; Yoh 12:25"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 11, 'Ba no lalaŵa ia, börö ndro Nono mbiri-biri andrö ba taroma li famaduhu''öra, ba lö ni''omasi''öra nosora irugi wa''amate.[7]', '["Faigi 11:15; Sakh 3:1 b.t.; Yob 1:9 b.t.","Faigi 7:14; 2:10; Rom 8:33,34,37; Yoh 12:25"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 12, 'Andrö mi''omusoi''ö dödömi, ya''ami banua si yaŵa, awö zi so nahia ba da''ö. Ba alai guli danö, awö nasi, me no möi mitou Gafökha andrö khömi, ba me no ebua wönunia, ba me no i''ila, lö ara nitehe khönia".[8]', '["Yes 49:13; FetI 5:8"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 13, 'Ba me i''ila naga andrö, tetibo''ö ba danö ia, ba igohi ndra alawe andrö, si no madono ono matua andrö.', '[]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 14, 'Ba tebe''e ba ndra alawe andrö gafi, dombua, afi moyo sebua, ena''ö muhombo ia, ena''ö isaŵa danö si mate, nahania andrö ba nibe''e gönia, sagötö, ba dua götö, ba matonga nga''ötö wa''ara, nibini''ö ba gulö andrö.[9]', '["Dan 12:7; Faigi 8:13"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 15, 'Ba i''uta''ö ulö andrö nidanö furi ndra alawe andrö, hulö nidanö ba nungo nidanö wa''abölö-bölö ba wangahanigö yaia.', '[]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 16, 'Ba itolo ndra alawe tanö, ibokai mbawania tanö ibadu nidanö andrö ni''uta''ö naga.', '[]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 17, 'Ba mofönu naga ba ndra alawe, ba mofanö ia manuwö si tosai ma''uwunia solo''ö oroisa Lowalangi andrö, ba si so famaduhu''ö andrö khö Yesu Keriso.[10]', '["Faigi 14:12; 6:9"]', NULL),
  (3392275, 'NT', 'Fama''ele''ö', 12, 18, 'Ba möi baene ndra''o ba mbewe nasi.', '[]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 1, 'Ba u''ila zi möi yaŵa moroi ba nasi saliŵa-liŵa ba danö sageu, si fulu rozi tandru ba si fitu högö, ba ba dandrunia andrö ba fulu naya, ba ba högönia andrö ba töi fanandraŵaisi.[1]', '["Faigi 11:7; 12:3","Dan 7:4-6; Faigi 12:3,9"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 2, 'Ba saliŵa-liŵa ba danö andrö, ni''ilagu, ba no hulö harimo, ba ahenia ba hulö gahe mberua, ba bawania ba hulö mbawa zingo: ba ibe''e khönia wa''abe''enia naga andrö awö dadaomania, awö wa''abölönia si no ebua.[2]', '["Faigi 11:7; 12:3","Dan 7:4-6; Faigi 12:3,9"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 3, 'Ba si sambua högönia, ba hulö nifesokho ba wamunu; ba tobali döhö zokhonia ba wamunu andrö. Ba ahöli-höli dödö niha ba guli danö fefu, moroi furi zaliŵa-liŵa ba danö andrö.', '["Faigi 11:7; 12:3","Dan 7:4-6; Faigi 12:3,9"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 4, 'Ba mangalulu ira ba naga andrö, me no ibe''e ba zaliŵa-liŵa ba danö andrö wa''abölö ba mangalulu ira ba zaliŵa-liŵa ba danö andrö, lamane: Ha niha zi mane saliŵa-liŵa ba danö andrö ba ha niha zangila fasuwö khönia?', '[]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 5, 'Ba tebe''e khönia mbawa, ba wanguma''ö fayaŵasa ba ba wanandraŵaisi, ba tetehe khönia wolau da''ö, öfa wulu a rua waŵa wa''ara.[3]', '["Dan 7:8,11; Faigi 11:2","Dan 7:25"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 6, 'Ba humede ia, ba wanandraŵaisi Lowalangi ba wanandraŵaisi töinia, awö nahania, awö zowanua ba mbanua si yaŵa.[4]', '["Dan 7:8,11; Faigi 11:2","Dan 7:25"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 7, 'Ba tetehe khönia wanuwö ni''amoni''ö andrö, ba folaŵa ya''ira, ba tebe''e ba dangania fefu hadia ngawalö niwa, ba hadia ngawalö mado, ba hadia ngawalö li, hadia ngawalö soi.[5]', '["Faigi 11:7; Dan 7:21 b.t."]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 8, 'Ba mangalulu dania khönia fefu zowanua ba guli danö, si lö musura töi ba zura wa''auri andrö khö Nono mbiri-biri andrö, nitaba, i''otarai wamobörö danö''a.[6]', '["Faigi 17:8; 3:5"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 9, 'Si so tögi dalinga, ba yamufondrondrongo![7]', '["Faigi 2:7","Mat 26:52; MozI 9:6; Faigi 14:12"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 10, 'Sokuru niha, ba ni''ohe ba gurungu dania; samunu niha si''öli ba nibunu si''öli dania. Ba da''e so wa''anau gölö ni''amoni''ö andrö ba famatira.[8]', '["Faigi 2:7","Mat 26:52; MozI 9:6; Faigi 14:12"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 11, 'Ba u''ila zaliŵa-liŵa ba danö tanö bö''ö, si otarai moroi tou danö, ba dua rozi dandru, hulö ba nono mbiri-biri, ba fehedenia, ba no hulö wehede naga.[9]', '["MozI 3:1,4,5","Faigi 19:20","Mat 24:11,24; TesII 2:9"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 12, 'Ba ifalua fefu goroisa zaliŵa-liŵa ba danö andrö si föföna, fönania, ba mangalulu ba zaliŵa-liŵa ba danö si föföna andrö si no döhö sokho ba wamunu andrö, guli danö, awö zowanua ba guli danö, ibe''e.[10]', '["MozI 3:1,4,5","Faigi 19:20","Mat 24:11,24; TesII 2:9"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 13, 'Ba ifazökhi dandra sebua, ena''ö göi ibe''e aekhu tou galitö ba danö, moroi ba mbanua si yaŵa, ba zanehe niha.[11]', '["MozI 3:1,4,5","Faigi 19:20","Mat 24:11,24; TesII 2:9"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 14, 'Ba ifaelungu zowanua ba guli danö, ba dandra andrö, nitehe khönia famazökhi, föna zaliŵa-liŵa ba danö andrö, wanguma''ö ba niha sowanua ba guli danö, ena''ö lafazökhi wamaedo zaliŵa-liŵa ba danö andrö, si so sokho andrö, ba wöda, ba sauri.', '[]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 15, 'Ba tetehe khönia wamonoso famaedo zaliŵa-liŵa ba danö andrö, ena''ö muhede göi wamaedo zaliŵa-liŵa ba danö andrö, ba ena''ö ibe''e nibunu fefu ha wa''ato zi lö mangalulu ba wamaedo zaliŵa-liŵa ba danö andrö.', '[]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 16, 'Ba ibe''e lafazökhi khöra dandra ba dangara kambölö ba ma ba gangangora, dozi he iraono, ba he satua, he so''ana''a, ba he si numana, he si tenga sawuyu, ba he sawuyu,[12]', '["Faigi 14:9-11","Faigi 15:2"]', NULL),
  (3392276, 'NT', 'Fama''ele''ö', 13, 17, 'ena''ö lö tola mowöli niha, ha niha ia, ba lö tola mamawa hadia ia, ha si so tandra andrö, töi zaliŵa-liŵa ba danö andrö, ba ma numero töinia andrö.[13]', '["Faigi 14:9-11","Faigi 15:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3392276, 'NT', 'Fama''ele''ö', 13, 18, 'Ba da''e so wa''atua-tua! Ha niha zi si so fa''aboto ba dödö, ba yamu''erai wangerai saliŵa-liŵa ba danö andrö. Fangerai niha sa wangerai ya''ia. Ba numeronia andrö, ba 666.[14]', '["Faigi 17:9"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 1, 'Ba u''ila, ba hiza Nono mbiri-biri andrö, ba hili Ziona so, ba otu a öfa wulu a öfa ngahönö nawönia, nisura ba gangangora töinia ba töi Namania andrö.[1]', '["Faigi 5:6 b.t.; 7:3,4"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 2, 'Ba urongo li moroi ba mbanua si yaŵa, hulö wegoso-goso nidanö sebua, ba hulö we''ugu-ugu mbanua sabölö-bölö; ba hulö li mbiola, na lalau, li andrö nirongogu.[2]', '["Faigi 1:15; 5:8; 19:6","Faigi 5:9","Faigi 3:4; KorII 11:2","Efes 5:27; Sef 3:13"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 3, 'Ba manunö ira, sinunö si bohou, föna dadaoma andrö, ba föna zaliŵa-liŵa ba danö andrö si öfa nga''eu, ba föna zatua andrö. Ba lö sangila mamodomaesi sinunö andrö, ha si otu a öfa wulu a öfa ngahönö andrö, nihöli moroi ba guli danö.[3]', '["Faigi 1:15; 5:8; 19:6","Faigi 5:9","Faigi 3:4; KorII 11:2","Efes 5:27; Sef 3:13"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 4, 'Ya''ira da''ö zi lö si fabaya hadia ia, ba ndra alawe; amaedola nono alawe sa ira. Ya''ira zolo''ö Ono mbiri-biri andrö, heza möi. Ya''ira nihöli ba niha, nibe''e si a''a khö Lowalangi, ba khö Nono mbiri-biri andrö,[4]', '["Faigi 1:15; 5:8; 19:6","Faigi 5:9","Faigi 3:4; KorII 11:2","Efes 5:27; Sef 3:13"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 5, 'ba lö mu''ila ba mbewera waya. Si lö sinegu sa ira.[5]', '["Faigi 1:15; 5:8; 19:6","Faigi 5:9","Faigi 3:4; KorII 11:2","Efes 5:27; Sef 3:13"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 6, 'Ba u''ila mala''ika bö''ö sihombo ba dalu mbanua si yaŵa, si so turia somuso dödö si lö aetu ba wanuriagö ba zi so ba guli danö, ba ngawalö soi fefu, ba ba ngawalö niwa, ba ba ngawalö li, ba ba ngawalö mado fefu,[6]', '["Mat 24:14","Faigi 15:4; HalZin 14:15; Sin 146:6"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 7, 'no ebua linia, imane: Mi''ata''ufi Lowalangi, ba mibe''e khönia zumange, me no irugi inötö wanguhuku andrö khönia, ba mi''angalulu khö zamazökhi banua si yaŵa, ba tanö, ba asi, ba umbu nidanö andrö.[7]', '["Mat 24:14","Faigi 15:4; HalZin 14:15; Sin 146:6"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 8, 'Ba i''o''ö mala''ika bö''ö, samösa tö, imane: No adudu, no adudu Mbabilona sebua andrö, si no mamabadugö ba ngawalö soi niha fefu agu wönu andrö, ba wohorönia.[8]', '["Faigi 17:2,4,5; 18:2,3","Faigi 13:15-17","Faigi 16:19; 19:20; Sin 75:9; Mar 9:44"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 9, 'Ba i''o''ö ira mala''ika bö''ö, datölu möi da''ö, mu''ao ia, ebua linia, imane: Na so zangalulu ba zaliŵa-liŵa ba danö andrö, ba ba wamaedonia, nifatöfa tandra andrö ba gangangonia,[9]', '["Faigi 17:2,4,5; 18:2,3","Faigi 13:15-17","Faigi 16:19; 19:20; Sin 75:9; Mar 9:44"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 10, 'ba ma ba dete dangania, ba ibadu göi wöfö nagu wönu andrö, khö Lowalangi, si no mufazökhi, lö mufaruka, ba mako wönunia andrö, ba nifakao alitö ba talö balera ia, föna mala''ika ni''amoni''ö ba föna Nono mbiri-biri andrö.[10]', '["Faigi 17:2,4,5; 18:2,3","Faigi 13:15-17","Faigi 16:19; 19:20; Sin 75:9; Mar 9:44"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 11, 'Ba numalö dania miyaŵa zimbo ba wamakao ya''ira andrö, irugi zi lö aetu. Ba lö folombase khöra, bongi ma''ökhö, khöra si no mangalulu ba zaliŵa-liŵa ba danö andrö ba ba wamaedonia, awö zi no mufatöfa tandra döinia andrö.[11]', '["Faigi 19:3; Yes 34:9,10; Mat 25:46"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 12, 'Ba da''e so wa''anau gölö ni''amoni''ö andrö, solo''ö oroisa Lowalangi andrö, ba si lö mamulö''ö famati andrö khö Yesu.[12]', '["Faigi 13:10; 22:14"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 13, 'Ba urongo li moroi ba mbanua si yaŵa, imane: Sura: Ya''ahowu zi no mate, si mate ba khö Zo''aya, i''otarai da''e. Si ndruhu, iŵa''ö Eheha, ena''ö molombase ira me no aefa wa''erege dödöra andrö; i''o''ö sa ira bua-buara.[13]', '["Faigi 19:9; Yes 57:1,2; Hebr 4:9,10"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 14, 'Ba u''ila, ba hiza lawuo safusi ba so zidadao ba dete lawuo andrö, si hulö Nono Niha, so ba högönia dakula ana''a ba ba dangania, ba sabi satarö.[14]', '["Faigi 1:13; Dan 7:13 b.t."]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 15, 'Ba so mala''ika bö''ö, si otarai gosali andrö, mu''ao ia, ebua linia, ba zidadao ba lawuo andrö, imane: Fatörö zabimö andrö ba amasi, noa sa irugi inötö wamasi, me no oköli-köli mbasitö andrö ba danö![15]', '["Yoel 3:13"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 16, 'Ba ifatörö ba danö zabinia sidadao ba lawuo andrö, ba tebasi danö.[16]', '["Mat 13:39"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 17, 'Ba so mala''ika bö''ö, si otarai gosali andrö, ba zorugo, so khönia göi zabi satarö;[17]', '["Faigi 15:5","Faigi 16:7"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 18, 'ba so mala''ika bö''ö, si otarai naha wame''e sumange andrö, ba no mube''e ba dangania galitö andrö, ba mu''ao ia, ebua linia, ba zi so sabi satarö andrö, imane: Fatörö zabimö satarö andrö, ba taba mbua nagu ba döla, ba guli danö, me no asoso mbuania andrö![18]', '["Faigi 15:5","Faigi 16:7"]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 19, 'Ba ifatörö ba danö zabinia mala''ika andrö, itaba mbua nagu andrö, ba guli danö, ba itibo''ö ba wolazi sebua andrö, fönu Lowalangi.[19]', '["Faigi 19:15","Hes 32:6; Yes 63:3 b.t."]', NULL),
  (3392277, 'NT', 'Fama''ele''ö', 14, 20, 'Ba baero mbanua tehundragö wolazi andrö, ba mangele ndro, moroi ba wolazi andrö, irugi kaka mbawa kudo, felendrua ngaluo fofanö wa''aröu.[20]', '["Faigi 19:15","Hes 32:6; Yes 63:3 b.t."]', NULL),
  (3392278, 'NT', 'Fama''ele''ö', 15, 1, 'Ba u''ila dandra bö''ö ba zorugo, sebua ba sahöli-höli dödö: dafitu mala''ika, si so famakao andrö, si fitu balö, safuria, me ba da''ö te''o''ozui wönu Lowalangi andrö.[1]', '["Faigi 16:1; 17:1"]', NULL),
  (3392278, 'NT', 'Fama''ele''ö', 15, 2, 'Ba u''ila, ba hulö mbaŵa nidanö sörömi, si faruka alitö, ba ba zinga mbaŵa sörömi andrö so zi no molaŵa saliŵa-liŵa ba danö andrö ba famaedonia ba fangerai töinia andrö, so khöra mbiola Lowalangi.[2]', '["Faigi 4:6; 12:11","MozII 15; Yes 12; Sin 111:2 b.t.; 145:17; Faigi 16:7","Yer 10:7; Sin 98; 86:9,10"]', NULL),
  (3392278, 'NT', 'Fama''ele''ö', 15, 3, 'Ba manunö ira, sinunö genoni Lowalangi andrö, Moze, ba sinunö Nono mbiri-biri andrö, lamane: "No ebua wolaumö andrö ba sahöli-höli dödö, ya''ugö So''aya, Lowalangi, samatörö fefu, hadia ia; satulö ba si ndruhu lalamö andrö, ya''ugö, razo soi niha andrö.[3]', '["Faigi 4:6; 12:11","MozII 15; Yes 12; Sin 111:2 b.t.; 145:17; Faigi 16:7","Yer 10:7; Sin 98; 86:9,10"]', NULL),
  (3392278, 'NT', 'Fama''ele''ö', 15, 4, 'Ha niha zi lö ata''u, ya''ugö So''aya, ba ha niha zi lö manuno töimö andrö? Me ha ya''ugö ni''amoni''ö, me möi dania soi niha fefu, ba wangalulu khöu, me no mufa''ele''ö huku andrö khöu."[4]', '["Faigi 4:6; 12:11","MozII 15; Yes 12; Sin 111:2 b.t.; 145:17; Faigi 16:7","Yer 10:7; Sin 98; 86:9,10"]', NULL),
  (3392278, 'NT', 'Fama''ele''ö', 15, 5, 'Ba me aefa da''ö, ba u''ila, ba tebokai gosali, ose wamaduhu''ö andrö, ba zorugo,[5]', '["Faigi 11:19","Faigi 1:13; 19:8"]', NULL),
  (3392278, 'NT', 'Fama''ele''ö', 15, 6, 'ba möi baero mala''ika andrö si dafitu, si so famakao andrö, si fitu balö, la''otarai gosali andrö, muko si sökhi, si takile, mbarura, ba balaki mböbö dötö''ara.[6]', '["Faigi 11:19","Faigi 1:13; 19:8"]', NULL),
  (3392278, 'NT', 'Fama''ele''ö', 15, 7, 'Ba si sageu saliŵa-liŵa ba danö andrö, ba zi öfa nga''eu, ba ibe''e ba mala''ika andrö, si dafitu, mako balaki, fitu, nifönui fönu Lowalangi andrö, sauri irugi zi lö aetu.[7]', '["Faigi 6:1; 4:8,9"]', NULL),
  (3392278, 'NT', 'Fama''ele''ö', 15, 8, 'Ba tobali afönu simbo gosali andrö, ibe''e lakhömi Lowalangi andrö, ba fa''abölönia, ba lö sangila möi ba gosali bakha, irege no mufalua wamakao andrö, si fitu balö, ba mala''ika andrö, si dafitu.[8]', '["MozII 40:34; RazI 8:11; Yes 6:4"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 1, 'Ba urongo li sebua, moroi ba gosali, imane ba mala''ika andrö, si dafitu: Mi''ae mifaduwa ba danö nösi mako wönu Lowalangi andrö, si fitu.[1]', '["Faigi 15:5-7"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 2, 'Ba möi zi föföna andrö, ifaduwa ba danö nösi mako andrö khönia; ba tumbu waosa si lö sökhi ba sangobou ba niha andrö, si no mufatöfa tandra zaliŵa-liŵa ba danö andrö, ba si no mangalulu ba wamaedonia.[2]', '["MozII 9:9; Faigi 13:14-17"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 3, 'Ba ifaduwa ba nasi nösi mako khönia mala''ika fanete zi föföna andrö, ba tobali do, hulö ndro zi mate, ba mate zi so noso fefu, si so ba nasi.[3]', '["Faigi 8:8,9; MozII 7:17 b.t."]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 4, 'Ba ifaduwa ba nungo nidanö ba ba gumbu nidanö nösi mako khönia mala''ika fanete zi darua andrö, ba tobali do.', '[]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 5, 'Ba urongo, me iŵa''ö mala''ika nidanö andrö: Satulö ndra''ugö, ya''ugö si so, ba si no so föna, ni''amoni''ö, me no ömanö wanguhuku;[4]', '["Faigi 19:2","Faigi 18:24; Sin 79:2,3; Mat 23:34","Faigi 15:3; 6:3"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 6, 'me no aduwa ndro ni''omoni''ö, labe''e, awö ndro zama''ele''ö, ba no öfabadugö khöra ndro, no si nangea luora da''ö.[5]', '["Faigi 19:2","Faigi 18:24; Sin 79:2,3; Mat 23:34","Faigi 15:3; 6:3"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 7, 'Ba urongo, me imane naha wame''e sumange andrö: Si ndruhu, ya''ugö So''aya, Lowalangi, samatörö fefu, hadia ia, si ndruhu ba satulö huku andrö khöu.[6]', '["Faigi 19:2","Faigi 18:24; Sin 79:2,3; Mat 23:34","Faigi 15:3; 6:3"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 8, 'Ba ifaduwa ba luo nösi mako khönia mala''ika fanete zi datölu andrö.', '["Faigi 9:20,21; Yes 9:13"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 9, 'Ba tetehe khönia wogozi niha ba galitö; ba akhozi niha ba wa''aukhu sabölö-bölö, ba latandraŵaisi döi Lowalangi, samatörö famakao andrö, ba lö lafalalini gera-erara, ba wamosumange ya''ia ena''ö,[7]', '["Faigi 9:20,21; Yes 9:13"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 10, 'Ba ifaduwa ba dadaoma zaliŵa-liŵa ba danö andrö nösi mako khönia mala''ika fanete zi daöfa andrö, ba tobali ogömi-gömi mbanuania andrö; ba langanga lelara, ba wa''afökhö;[8]', '["Faigi 13:1,2; MozII 10:22 b.t.","Faigi 16:9"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 11, 'ba latandraŵaisi Lowalangi zorugo andrö, ba wa''afökhö andrö khöra, ba ba waosara andrö, ba lö lafalalini gera-erara, ba wamöhöi bua-buara andrö ena''ö.[9]', '["Faigi 13:1,2; MozII 10:22 b.t.","Faigi 16:9"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 12, 'Ba ifaduwa ba nidanö sebua andrö, Oifarati, nösi mako khönia mala''ika fanete zi dalima andrö, ba ogo''ö nidanönia, ena''ö molala ndra razo andrö, moroi ba gatumbukha luo.[10]', '["Faigi 9:14"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 13, 'Ba u''ila mbekhu si ra''i-ra''iö, tölu, si otarai mbawa naga andrö, ba bawa zaliŵa-liŵa ba danö andrö, ba bawa zame''ele''ö andrö, sofaya, hulö dalaho.[11]', '["Faigi 12:3,9; 13:11; 19:20","Faigi 13:13 b.t.; 19:19 b.t.; Mat 24:24"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 14, 'Bekhu zi mate sa ira, samazökhi tandra, si möi ba razo andrö, ba guli danö, ma''asagörö, ba wangowuloi ya''ira, ba wanuwö andrö, na baŵa sebua khö Lowalangi, samatörö fefu hadia ia.[12]', '["Faigi 12:3,9; 13:11; 19:20","Faigi 13:13 b.t.; 19:19 b.t.; Mat 24:24"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 15, 'Hiza, hulö we''amöi zanagö na sodo! Ya''ahowu zi lö mörö, si no mama''anö nukhania, fa böi si lö nukha ia, ba wowaö-waö, fa böi oroma zaila ia.[13]', '["Faigi 3:3,4,18; FetII 3:10; KorII 5:3","Sakh 12:11; 14:4"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 16, 'Ba i''owuloi ira ba mbanua andrö, sotöi Hamagedo, ba li Heberaio.[14]', '["Faigi 3:3,4,18; FetII 3:10; KorII 5:3","Sakh 12:11; 14:4"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 17, 'Ba ifaduwa ba dalu mbanua nösi mako khönia mala''ika fanete zi daönö, ba so li sebua, si otarai gosali andrö, moroi ba dadaoma andrö, imane: No awai![15]', '["Faigi 15:5; 21:6","Faigi 11:13,19","Faigi 14:8,10; Yes 51:22,23"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 18, 'Ba so gari mbanua ba li niha ba fe''ugu-ugu mbanua; ba so ziheu sabölö-bölö, si lö larai mila, götö we''aso niha ba guli danö; lö irai si manö wa''abölö-bölö ziheu.[16]', '["Faigi 15:5; 21:6","Faigi 11:13,19","Faigi 14:8,10; Yes 51:22,23"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 19, 'Ba tobali ni''otölu mbanua sebua andrö, ba adudu mbanua soi niha andrö. Ba itörö tödö Lowalangi Mbabilona sebua andrö, ba wame''e khönia ösi mako nagu andrö, fönunia andrö, saukhu.[17]', '["Faigi 15:5; 21:6","Faigi 11:13,19","Faigi 14:8,10; Yes 51:22,23"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 20, 'Ba moloi hulo fefu, ba lö mu''ila hili sa''ae.[18]', '["Faigi 6:14","Faigi 11:19; MozII 9:18"]', NULL),
  (3392280, 'NT', 'Fama''ele''ö', 16, 21, 'Ba aekhu ba danö deu kara, so safiku zambua ngawua, göna ba niha, ba latandraŵaisi Lowalangi niha, ba wamakao andrö, teu kara, me no abölö-bölö sibai wamakao andrö, khönia.[19]', '["Faigi 6:14","Faigi 11:19; MozII 9:18"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 1, 'Ba so mala''ika, samösa, awö zi dafitu andrö, si so mako andrö, si fitu, humede ia khögu, imane: Tabu, da''u''oroma''ö khöu wanguhuku sohorö sebua andrö, sidadao yaŵa nidanö sebua andrö.[1]', '["Faigi 15:6 b.t.; 16:19; Nakh 3:4","Faigi 18:3,9"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 2, 'Nihoröni razo andrö ba guli danö; ba no mabu zowanua ba guli danö agu wohorönia andrö.[2]', '["Faigi 15:6 b.t.; 16:19; Nakh 3:4","Faigi 18:3,9"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 3, 'Ba i''ohe ndra''o ba danö si mate; no aheta nosogu. Ba u''ila ndra alawe sidadao ba hulu zaliŵa-liŵa ba danö, soyo kirimisi, safönu töi wanandraŵaisi, fitu högö ba fulu rozi dandru.[3]', '["Faigi 13:1 b.t.","Faigi 18:16","TesII 2:7; Faigi 14:8; 18:2,10","Faigi 18:24"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 4, 'Ba nukha ndra alawe andrö, ba no baru luo ungu ba baru luo kirimisi, ba no mufo''aya ana''a ba indra-indra ba mani-mani, ba so ba dangania mako ana''a, safönu horö, awö zi ta''unö, ba wohorönia andrö.[4]', '["Faigi 13:1 b.t.","Faigi 18:16","TesII 2:7; Faigi 14:8; 18:2,10","Faigi 18:24"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 5, 'Ba ba gangangonia, ba no musura döi, si lö aboto ba dödö niha: Babilona sebua andrö, ina zohorö ba ina hokha andrö, ba guli danö.[5]', '["Faigi 13:1 b.t.","Faigi 18:16","TesII 2:7; Faigi 14:8; 18:2,10","Faigi 18:24"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 6, 'Ba u''ila mabu ndra alawe andrö do ni''amoni''ö andrö, ba do zamaduhu''ö Yesu. Ba ahöli-höli sibai dödögu me u''ila ia.[6]', '["Faigi 13:1 b.t.","Faigi 18:16","TesII 2:7; Faigi 14:8; 18:2,10","Faigi 18:24"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 7, 'Ba imane khögu mala''ika andrö: Hana wa ahöli-höli dödöu? Da''u''ombakha''ö khöu zi lö aboto ba dödö niha andrö, ba ndra alawe andrö, ba ba zaliŵa-liŵa ba danö andrö, solu''i ya''ia, si fitu högö, ba si fulu rozi tandru.', '["Faigi 11:7; 20:12,15","Faigi 13:1,18"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 8, 'Saliŵa-liŵa ba danö andrö ni''ilau, ba no so föna ba lö ya''ia iada''e, ba möi ia miyaŵa dania i''oroi gawuwukha, ba isaŵa wa''atekiko; ba ahöli-höli dania dödö zowanua ba guli danö andrö, si lö musura töi ba zura wa''auri andrö, i''otarai wamobörö danö''a, na la''ila zaliŵa-liŵa ba danö andrö, me no so ia föna, ba me lö ya''ia iada''e, ba me so dania.[7]', '["Faigi 11:7; 20:12,15","Faigi 13:1,18"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 9, 'Ba da''e moguna dödö, si so fa''atua-tua! Högö andrö, si fitu, ba fitu hili dadaoma ndra alawe andrö;[8]', '["Faigi 11:7; 20:12,15","Faigi 13:1,18"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 10, 'ba razo, dafitu. Si dalima, ba no tekiko, si samösa ba so iada''e, ba si samösa zui ba lö si so na, ba na so ia ba lö tola ara ia.', '["Faigi 11:7; 20:12,15","Faigi 13:1,18"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 11, 'Ba saliŵa-liŵa ba danö andrö, si no so föna, ba si lö''ö iada''e, ba ya''ia wanete zi dafitu andrö, ba samösa ia ba zi dafitu andrö, ba isaŵa wa''atekiko.', '[]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 12, 'Ba tandru andrö, si fulu rozi, ni''ilau, ba no razo, dafulu, si lö sanema na amatöröŵa, ba lasöndra wa''abölö razo, saza wa''ara, awö zaliŵa-liŵa ba danö andrö.[9]', '["Faigi 13:1; Dan 7:20,24","Faigi 16:14; 19:16 b.t. TimI 6:15; Mat 24:31"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 13, 'Ha sara dödö da''ö, ba labe''e ba zaliŵa-liŵa ba danö andrö wa''abe''era ba fa''abölöra.', '["Faigi 13:1; Dan 7:20,24","Faigi 16:14; 19:16 b.t. TimI 6:15; Mat 24:31"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 14, 'Ya''ira zi fasuwö dania ba Nono mbiri-biri andrö, ba abölö Nono mbiri-biri moroi khöra, me no So''aya sokhö ia, ba me razo razo, ba awönia andrö, ba no nikaoni ba nitutuyu ba si lö faröi.[10]', '["Faigi 13:1; Dan 7:20,24","Faigi 16:14; 19:16 b.t. TimI 6:15; Mat 24:31"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 15, 'Ba imane khögu: Idanö andrö, ni''ilau, ba zidadao zohorö andrö, ba no ngawalö mado da''ö, ba niha sato, ba ngawalö soi, ba ngawalö li.[11]', '["Sin 93:3","Faigi 18:7,8"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 16, 'Ba tandru andrö, si fulu rozi, ba saliŵa-liŵa ba danö andrö, ba ya''ira zi fatiu tödö ba zohorö andrö, ba ha ya''i-ya''ia labe''e, ba si lö nukha, ba la''a nösinia ba latunu ia, ba galitö.[12]', '["Sin 93:3","Faigi 18:7,8"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 17, 'Noa sa ibe''e ba dödöra Lowalangi wamalua gera-erania, ba folau si ha sara dödö, ba fame''e amatöröŵara ba zaliŵa-liŵa ba danö andrö, irege te''o''ozui niŵa''ö Lowalangi andrö.', '["Sin 93:3","Faigi 18:7,8"]', NULL),
  (3392283, 'NT', 'Fama''ele''ö', 17, 18, 'Ba ira alawe andrö, ni''ilau, ba ya''ia mbanua sebua andrö, samatörö razo, ba guli danö.[13]', '["Faigi 16:19"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 1, 'Ba me aefa da''ö ba u''ila mala''ika bö''ö, si möi mitou, moroi ba zorugo, sabölö sibai, ba tehagaini guli danö, ba lakhöminia.', '["Faigi 14:8; Yes 21:9; 34:11-14; Yer 51:8; 50:39","Faigi 14:8,10; Yer 51:7"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 2, 'Ba mu''ao ia, ebua linia, imane: No adudu, no adudu Mbabilona sebua andrö, ba no tobali naha mbekhu ba kurunga mbekhu si ra''i-ra''iö, fefu, ba kurunga wofo si ra''i-ra''iö, fefu, sogoro ita,[1]', '["Faigi 14:8; Yes 21:9; 34:11-14; Yer 51:8; 50:39","Faigi 14:8,10; Yer 51:7"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 3, 'me no labadu wöfö nagu wönu andrö, ba wohorö andrö khönia, fefu soi, ba no mohorö khönia razo andrö, ba guli danö ba saniaga andrö, ba guli danö, ba ba wa''abölö hokhania lasöndra wo''ana''a.[2]', '["Faigi 14:8; Yes 21:9; 34:11-14; Yer 51:8; 50:39","Faigi 14:8,10; Yer 51:7"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 4, 'Ba urongo li bö''ö, moroi ba mbanua si yaŵa, imane: Miheta ami khönia, ya''ami banuagu, fa böi fao ami ba horönia andrö, ba fa lö göna ami ösa, famakao ya''ia, andrö.[3]', '["Yes 48:20; Yer 51:6,45","Faigi 16:19; Yer 51:9","Yer 50:15,29; Sin 137:8","Yes 47:7 b.t.","Faigi 17:16; Yer 50:31 b.t."]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 5, 'Noa sa irugi mbanua si yaŵa horöra andrö, ba noa sa itörö tödö Lowalangi golalöŵara andrö.[4]', '["Yes 48:20; Yer 51:6,45","Faigi 16:19; Yer 51:9","Yer 50:15,29; Sin 137:8","Yes 47:7 b.t.","Faigi 17:16; Yer 50:31 b.t."]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 6, 'Misulöni khönia nilaunia, ba mifodua winaeta khönia, dali wolaunia andrö; mako andrö, nifo''ösinia, ba mifo''ösi khönia, mifomendrua.[5]', '["Yes 48:20; Yer 51:6,45","Faigi 16:19; Yer 51:9","Yer 50:15,29; Sin 137:8","Yes 47:7 b.t.","Faigi 17:16; Yer 50:31 b.t."]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 7, 'Ndrohu-ndrohu nifolakhöminia ya''ia, ba ndrohu-ndrohu ni''ebua''önia hokhania, ba mibe''e khönia wa''afökhö ba fa''abu dödö. Me iŵa''ö tödönia: Mudadao ndra''o, razo ira alawe, ba tenga si mate donga ndra''o, ba lö''ö manö u''ila wa''abu dödö.[6]', '["Yes 48:20; Yer 51:6,45","Faigi 16:19; Yer 51:9","Yer 50:15,29; Sin 137:8","Yes 47:7 b.t.","Faigi 17:16; Yer 50:31 b.t."]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 8, 'Andrö dania so wamakaonia, ha ma''ökhö: Fa''amate, ba fa''abu dödö, ba lofo, ba tetunu dania ia, ba galitö, me no sabölö Zo''aya, Lowalangi, sanguhuku ya''ia andrö.[7]', '["Yes 48:20; Yer 51:6,45","Faigi 16:19; Yer 51:9","Yer 50:15,29; Sin 137:8","Yes 47:7 b.t.","Faigi 17:16; Yer 50:31 b.t."]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 9, 'Ba la''e''esi dania ia, ba fa''ala-alai khönia razo andrö, ba guli danö, si no mohorö khönia, si no molau hokha ba khönia andrö, na la''ila zimbo andrö ba wanunu ya''ia.[8]', '["Faigi 17:2; Hes 36:26 b.t.","Ayati 2; TesI 5:3"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 10, 'Ba zaröu so ira, ba wa''ata''ura wamakao ya''ia andrö, lamane: Alai ndra''ugö, alai ndra''ugö, banua sebua andrö, Babilona, banua sabölö andrö, me ha saza wa''aso wanguhuku ya''ugö![9]', '["Faigi 17:2; Hes 36:26 b.t.","Ayati 2; TesI 5:3"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 11, 'Ba mege-ege zaniaga andrö ba guli danö, ba abu dödö, ba khönia andrö, me lö''ö sa''ae sowöli faniagara andrö,[10]', '["Hes 27:27-36","Hes 27:17"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 12, 'faniaga ana''a, ba firö, ba indra-indra, ba mani-mani, ba muko si sökhi, ba baru luo ungu, ba suto, ba baru luo kirimisi, ba eu samohua, fefu, ba gama-gama ifö guaza, ba gama-gama eu sebua böli, fefu; ba aramba,', '["Hes 27:27-36","Hes 27:17"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 13, 'ba si''öli, ba kara fuala, awö guli geu sami, ba dalu-dalu amoma, ba hadia ia nitunu, samohua, ba dalu-dalu nigule''ö, ba kumöyö, ba agu, ba fanikha, ba hamo si sökhi, ba gandru, ba saŵi, ba biri-biri, ba kudo, ba kureta, ba boto niha, awö noso niha.[11]', '["Hes 27:27-36","Hes 27:17"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 14, 'Ba bua geu andrö somasi dödöu ba no aheta khöu, ba hadia ia lakhömi fefu, ba hadia ia zoadu ba sohaga ba no taya khöu, ba lö''ö manö sa''ae oroma ia.', '["Hes 27:27-36","Hes 27:17"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 15, 'Saniaga da''ö, si no mo''ana''a ba khönia, ba ba zaröu so, ba wa''ata''ura wamakao ya''ia andrö, mege-ege ira, ba abu dödöra, ba lamane:', '["Faigi 17:4"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 16, 'Alai ndra''ugö! alai ndra''ugö! banua sebua andrö si so nukha muko si sökhi, ba baru luo ungu, ba baru luo kirimisi, föna ba nibe''e ana''a ba nifo''indra-indra, ba nifomani-mani, me ha saza wa''adudu gana''a si manö.[12]', '["Faigi 17:4"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 17, 'Ba dozi durumudi, ba dozi soloyo misa, ba ono nowo, ba ha wa''ato zohalöŵö ba nasi, ba ba zaröu so,[13],', '["Faigi 18:11","Hes 27:30","Faigi 12:12; Yer 51:48"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 18, 'ba mu''ao me la''ila zimbo andrö ba wanunu ya''ia, lamane: Hezo zi fagölö-gölö ba mbanua sebua andrö?', '["Faigi 18:11","Hes 27:30","Faigi 12:12; Yer 51:48"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 19, 'Ba lalau gawu-gawu ba högöra ba mu''ao ira, mege-ege ba abu dödö, lamane: Alai ndra''ugö! alai ndra''ugö! banua sebua, ba zo''ana''a fefu zi so owo ba nasi balazi gana''ania andrö; me ha saza wa''adudu.[14]', '["Faigi 18:11","Hes 27:30","Faigi 12:12; Yer 51:48"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 20, 'Omusoi''ö dödöu ba khönia, ya''ugö sorugo, ba ya''ami ni''amoni''ö, ba ya''ami sinenge, ba ya''ami sama''ele''ö, me no ilau mbalömi khönia Lowalangi.[15]', '["Faigi 18:11","Hes 27:30","Faigi 12:12; Yer 51:48"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 21, 'Ba ifazaŵa gowe mala''ika sabölö, si mane gowe zalaŵa sebua, ba itibo''ö ba nasi, imane: Si manö wa''atetibo Mbabilona andrö, banua sebua andrö, ba nangi sabölö-bölö, ba lö mu''ila ia sa''ae.[16]', '["Yer 51:63 b.t.","Yes 24:8","Yer 25:10; Yes 23:8","Faigi 17:6; Mat 23:35-37"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 22, 'Ba lö''ö sa''ae terongo ba khömö wolau biola, ba folau hadia ia mai-mai, ba folau sigu, ba falau torofe, ba lö''ö sa''ae tesöndra ba khömö duka hadia ia fefu, ba lö''ö sa''ae terongo ba khömö goko halu ba wanutu fakhe.[17]', '["Yer 51:63 b.t.","Yes 24:8","Yer 25:10; Yes 23:8","Faigi 17:6; Mat 23:35-37"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 23, 'Ba lö''ö sa''ae humaga ba khömö haga wandru, ba li zangowalu ba li nono nihalö, ba lö''ö sa''ae terongo ba khömö me no salaŵa ba guli danö zaniaga andrö khöu, me no tefaelungu fefu soi, ba wakelemusa andrö khömö![18]', '["Yer 51:63 b.t.","Yes 24:8","Yer 25:10; Yes 23:8","Faigi 17:6; Mat 23:35-37"]', NULL),
  (3392284, 'NT', 'Fama''ele''ö', 18, 24, 'Ba tesöndra ba khönia ndro zama''ele''ö, awö ndro ni''amoni''ö andrö ba do nibunu andrö fefu ba guli danö.[19]', '["Yer 51:63 b.t.","Yes 24:8","Yer 25:10; Yes 23:8","Faigi 17:6; Mat 23:35-37"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 1, 'Me aefa da''ö, ba urongo, ba hulö zebua li niha sato, ba zorugo, lamane: "Haleluya, khö Lowalangida wangorifi andrö, awö lakhömi andrö, awö wa''abölö andrö,[1]', '["Faigi 12:10","Faigi 16:7; 17:1 b.t.","Faigi 14:11; 18:9,18; Yes 34:10"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 2, 'me no si ndruhu ba me no satulö wanguhukunia andrö: noa sa ihuku zohorö andrö, sebua, si no mamakiko uli danö, ba wohorö-horönia andrö, ba no ilau mbalö ndro genoninia andrö, ba dangania."[2]', '["Faigi 12:10","Faigi 16:7; 17:1 b.t.","Faigi 14:11; 18:9,18; Yes 34:10"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 3, 'Ba lamane zui: "Haleluya, numalö miyaŵa zimbonia andrö, irugi zi lö aetu."[3]', '["Faigi 12:10","Faigi 16:7; 17:1 b.t.","Faigi 14:11; 18:9,18; Yes 34:10"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 5, 'Ba latuhi danö satua andrö si dua wulu a öfa, awö zaliŵa-liŵa ba danö andrö si öfa nga''eu, mangalulu ira khö Lowalangi, sidadao ba dadaoma andrö, lamane: Yaduhu, Haleluya![4]', '["Faigi 4:4,9,10","Sin 134:1","Faigi 14:2; 11:15,17","Sin 118:24; Faigi 21:2,9","Faigi 3:5; 15:6; Sin 132:9"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 6, 'Ba urongo, ba hulö li zato, ba hulö wegoso-goso nidanö sebua, ba hulö we''ugu-ugu mbanua, sabölö-bölö, lamane: "Haleluya, me no razo Zo''aya, Lowalangida andrö, samatörö fefu hadia ia![6]', '["Faigi 4:4,9,10","Sin 134:1","Faigi 14:2; 11:15,17","Sin 118:24; Faigi 21:2,9","Faigi 3:5; 15:6; Sin 132:9"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 7, 'Data''omusoi''ö dödöda, ba ta''owua-wua''ö dödöda, ba tafosumange ia; me no irugi walöŵa Nono mbiri-biri andrö, ba me no ifa''anö ia ngambatönia,[7]', '["Faigi 4:4,9,10","Sin 134:1","Faigi 14:2; 11:15,17","Sin 118:24; Faigi 21:2,9","Faigi 3:5; 15:6; Sin 132:9"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 8, 'ba no tetehe khönia, ena''ö i''onukha zi ndruhu muko si sökhi, sihaga; muko si sökhi andrö sa, ba ya''ia wa''atulö niha ni''amoni''ö andrö."[8]', '["Faigi 4:4,9,10","Sin 134:1","Faigi 14:2; 11:15,17","Sin 118:24; Faigi 21:2,9","Faigi 3:5; 15:6; Sin 132:9"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 9, 'Ba imane khögu: Sura: Ya''ahowu nikaoni ba walöŵa Nono mbiri-biri andrö! Ba imane khögu: Da''ö li Lowalangi andrö, si ndruhu.[9]', '["Faigi 14:13; Mat 22:2"]', NULL);
INSERT INTO "bible" ("page_id", "category", "book", "chapter", "verse", "text", "reference", "note") VALUES
  (3392285, 'NT', 'Fama''ele''ö', 19, 10, 'Ba utuhi danö föna gahenia, ba wangalulu khönia. Ba imane khögu: Böi! Awöu enoni ndra''odo, ba awö dalifusöu andrö, si so famaduhu''ö Yesu andrö. Khö Lowalangi angalulu. Famaduhu''ö Yesu sa, ba ya''ia Geheha wama''ele''ö andrö.[10]', '["Faigi 22:8 b.t.; HalZin 10:25,26; Faigi 12:17"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 11, 'Ba u''ila, teboka mbanua si yaŵa, ba hiza kudo safusi ba si fakudo yaŵa, ba "Si lö faröi" ba "Si ndruhu" döinia, ba atulö wanguhukunia ba fanuwönia.[11]', '["Faigi 6:2; 3:14","Faigi 1:14","Yes 63:1–3. Yoh 1:1"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 12, 'Ba no hola-hola galitö hörönia, ba ba högönia, ba no oya dakula, so döinia nisura, si lö i''ila niha, ha ya''ia zangila;[12]', '["Faigi 6:2; 3:14","Faigi 1:14","Yes 63:1–3. Yoh 1:1"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 13, 'ba barunia, ba no mu''ungugö ba ndro, ba töinia, ba "Taroma li Lowalangi".[13]', '["Faigi 6:2; 3:14","Faigi 1:14","Yes 63:1–3. Yoh 1:1"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 14, 'Ba la''o''ö ia sanuwö andrö, ba zorugo, ba hulu kudo safusi, si ndruhu muko safusi mbarura.', '["Faigi 1:16; 2:27; 14:19; Yes 63:2 b.t.","Faigi 17:14"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 15, 'Ba i''otarai mbawania gari satarö, ena''ö ibe''e famunu soi andrö. Ba ikubaloi dania ira, si''o si''öli, ba ihundragö wolazi nagu fönu saukhu andrö, khö Lowalangi, samatörö fefu, hadia ia.[14]', '["Faigi 1:16; 2:27; 14:19; Yes 63:2 b.t.","Faigi 17:14"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 16, 'Ba so döinia, nisura ba dete mbarunia ba ba zolania: "Razo razo ba So''aya sokhö."[15]', '["Faigi 1:16; 2:27; 14:19; Yes 63:2 b.t.","Faigi 17:14"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 17, 'Ba u''ila mala''ika, samösa, si so ba luo, ba mu''ao ia, ebua li, imane ba wofo fefu, sihombo ba dalu mbanua: Mi''aine, mi''owuloi ami, ba gowuloa sebua andrö, khö Lowalangi,[16]', '["Hes 39:4,17 b.t."]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 18, 'ba wemanga nösi razo, awö nösi gumandra, awö nösi zabölö andrö, awö nösi kudo, fabaya si fakudo yaŵa, awö nösi zi tenga sawuyu, fefu, fabaya sawuyu, ba ösi ndraono, awö nösi zatua.', '["Hes 39:4,17 b.t."]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 19, 'Ba u''ila me owulo ira zaliŵa-liŵa ba danö andrö razo ba guli danö, awö zabölö andrö khöra, ba wasuwöta ba zidadao ba kudo andrö ba ba zabölö andrö khönia.[17]', '["Faigi 13:1; 17:12 b.t.","Faigi 16:13; 13:11–17; 20:10–14; Dan 7:11"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 20, 'Ba te''ala zaliŵa-liŵa ba danö andrö labe''e, fabaya sama''ele''ö sofaya andrö, samazökhi tandra andrö, mege, fönania, famaelungu zi no manema tandra zaliŵa-liŵa ba danö andrö, si no mangalulu ba wamaedonia andrö; tetibo''ö auri zi darua andrö ba mbaŵa alitö andrö, sihola-hola talö balera.[18]', '["Faigi 13:1; 17:12 b.t.","Faigi 16:13; 13:11–17; 20:10–14; Dan 7:11"]', NULL),
  (3392285, 'NT', 'Fama''ele''ö', 19, 21, 'Ba tanö bö''ö andrö, ba nibunu gari zidadao ba kudo andrö, gari si otarai mbawania, ba abuso wofo fefu ösira andrö.', '["Faigi 13:1; 17:12 b.t.","Faigi 16:13; 13:11–17; 20:10–14; Dan 7:11"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 1, 'Ba u''ila mala''ika si möi mitou, moroi ba zorugo, so khönia wogoe mbawa gawuwukha andrö, awö rate sebua, ba dangania.[1]', '["Faigi 18:1; 1:18","Faigi 12:9; Yes 24:21 b.t."]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 2, 'Ba ira''u naga andrö, ulö satua andrö, ya''ia Gafökha, Satana andrö, ba irate, hönö fakhe wa''ara,[2]', '["Faigi 18:1; 1:18","Faigi 12:9; Yes 24:21 b.t."]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 3, 'ba itibo''ö ba gawuwukha andrö, ba ikusi ba ifotandro ba dete yaŵa, fa böi sa''ae ifaelungu soi niha andrö, irege alua zi hönö fakhe. Ba aefa da''ö, ba ni''efa''ö ia, ba lö arara.', '["Faigi 18:1; 1:18","Faigi 12:9; Yes 24:21 b.t."]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 4, 'Ba u''ila dadaoma, ba mudadao ira yaŵa, ba tetehe khöra, wanguhuku; awö noso niha, ni''eŵa bagi, ba wamaduhu''ö Yesu andrö, ba ba daroma li Lowalangi andrö, ba si lö irai mangalulu ba zaliŵa-liŵa ba danö andrö ba ba wamaedonia andrö, ba si lö manema tandra andrö, ba gangangora, ba ba dete dangara; ba ifuli auri ira ba salaŵa ira, awö Keriso, hönö fakhe wa''ara.[3]', '["Dan 7:9; 22:27; Mat 19:28; Faigi 6:9; 13:15 b.t.; 5:10"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 5, 'Ba tanö bö''ö, si mate, ba lö auri na, irege no alua zi hönö fakhe andrö. Da''ö wemaoso si föföna andrö.[4]', '["KorI 15:23-24","Faigi 2:11; 20:14; 1:6. FetI 2:5,9"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 6, 'Ya''ahowu ba no ni''amoni''ö zogamö femaoso si föföna andrö. Tebai ilaŵa da''ö fa''amate si samuza andrö; ere ira khö Lowalangi, ba khö Keriso, ba salaŵa ira awönia, zi hönö fakhe andrö.[5]', '["KorI 15:23-24","Faigi 2:11; 20:14; 1:6. FetI 2:5,9"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 7, 'Ba na no alua zi hönö fakhe andrö, ba te''efa''ö Zatana ba gurungania andrö.', '["Yes 11:12; Hes 38; Hes 39; Faigi 16:14"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 8, 'Ba möi ia baero, ba wamaelungu soi andrö, ba watalinga danö, si öfa, Gogi andrö ba Magogi, ba wangowuloi ya''ira ba wanuwö, ba fa''atora, ba no timba ngawua nene ba mbewe nasi.[6]', '["Yes 11:12; Hes 38; Hes 39; Faigi 16:14"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 9, 'Ba möi ira miyaŵa ba dalu danö ba lafasui golombaseŵa niha ni''amoni''ö andrö, ba banua omasiö andrö. Ba aekhu galitö moroi ba mbanua si yaŵa, ba i''a ira.[7]', '["Hes 38:22; 39:6"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 10, 'Ba Afökha andrö, samaelungu ya''ira, ba tetibo''ö ba mbaŵa alitö ba balera andrö, ba zi so göi zaliŵa-liŵa ba danö andrö ba sama''ele''ö sofaya andrö; ba tefakao ira bongi ma''ökhö irugi zi lö aetu.[8]', '["Faigi 19:20; 14:10,11; Mat 25:41"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 11, 'Ba u''ila dadaoma sebua, safusi, awö zidadao yaŵa; ba wamaiginia moloi danö, fabaya banua si yaŵa, ba lö falukha naha khöra.[9]', '["Faigi 4:2; FetII 3:7 b.t."]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 12, 'Ba u''ila zi no mate fefu, he satua, ba he iraono, föna dadaoma andrö so ira, ba tebokai zura; ba tebokai zura bö''ö, ya''ia zura wa''auri andrö. Ba tehuku zi mate andrö, balazi nisura ba zura andrö, dali mbua-buara.[10]', '["Faigi 3:5; 21:27; 2:23; Dan 7:10; Mat 16:27"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 13, 'Ba ibe''e baero asi zi mate andrö khönia, ba fa''amate andrö, ba banua tou, ba labe''e baero zi mate andrö, khöra, ba tehuku, dali mbua-bua zamösana.[11]', '["Yoh 5:28-29"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 14, 'Ba fa''amate andrö, ba banua tou, ba tetibo''ö ba mbaŵa alitö andrö, ya''ia wa''amate si samuza andrö, baŵa alitö.[12]', '["Faigi 21:8; KorI 15:26,54,55"]', NULL),
  (3392286, 'NT', 'Fama''ele''ö', 20, 15, 'Ba na so zi lö musöndra töi, na lö mutanö ba zura wa''auri, ba tetibo''ö ba mbaŵa alitö andrö.[13]', '["Faigi 20:10"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 1, 'Ba u''ila mbanua si yaŵa, si bohou, ba tanö si bohou; noa sa numalö mbanua si yaŵa si föföna, awö danö si föföna andrö, ba lö asi sa''ae.[1]', '["Faigi 20:11; Yes 65:17; 66:22; FetII 3:13","Faigi 3:12; Heb 12:22"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 2, 'Ba u''ila mbanua ni''amoni''ö andrö, Yeruzalema si bohou, silalö mitou moroi ba mbanua si yaŵa, moroi ba Lowalangi, nihaogö, hulö nono nihalö, si no mangehao khö zangai ya''ia.[2]', '["Faigi 20:11; Yes 65:17; 66:22; FetII 3:13","Faigi 3:12; Heb 12:22"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 3, 'Ba urongo li sebua, moroi ba dadaoma andrö, imane: Hiza nose Lowalangi andrö ba niha, ba mowanua ia ba khöra, ba ya''ira, ba banuania, ba ya''ia, Lowalangi, ba awöra,[3]', '["Hes 43:7; 37:27; Heb 9:11","Faigi 7:17; Yes 35:10","Faigi 20:11; Yes 43:18,19"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 4, 'ba i''osi dania daŵa hörö fefu, ba höröra, ba lö fa''amate sa''ae, ba lö fa''abu dödö, ba lö fege-ege, ba lö fa''afökhö sa''ae, me no numalö zi föföna andrö.[4]', '["Hes 43:7; 37:27; Heb 9:11","Faigi 7:17; Yes 35:10","Faigi 20:11; Yes 43:18,19"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 5, 'Ba imane sidadao ba dadaoma andrö: Hiza, ubohouni fefu hadia ia! Ba imane: Tanö ba zura, me si lö tebulö ba me no si ndruhu daroma li andre.[5]', '["Hes 43:7; 37:27; Heb 9:11","Faigi 7:17; Yes 35:10","Faigi 20:11; Yes 43:18,19"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 6, 'Ba imane khögu: No awai. Alafa ndra''o ba omega, böröta ndra''o ba amozua. Ba zowökhi tödö ube''e nidanö gumbu, idanö fangorifi andrö, saoha gölö.[6]', '["Faigi 16:17; 1:8; 22:13,17","Faigi 3:21; Heb 1:5","Faigi 22:15; 19:20; Gal 5:19 b.t.; Efes 5:5"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 7, 'Ha niha zi möna, da''ö zanema da''ö, ba Lowalanginia ndra''o ba onogu ia.[7]', '["Faigi 16:17; 1:8; 22:13,17","Faigi 3:21; Heb 1:5","Faigi 22:15; 19:20; Gal 5:19 b.t.; Efes 5:5"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 8, 'Ba sada''u-da''u andrö, ba si lö mamati, ba si ra''i-ra''iö, ba sange''e ba sohorö, ba si fakelemu, ba same''e-me''e adu, ba dozi sofaya, ba ba mbaŵa andrö, sihola-hola alitö ba talö balera, mo''urakha ira, ya''ia wa''amate si samuza andrö.[8]', '["Faigi 16:17; 1:8; 22:13,17","Faigi 3:21; Heb 1:5","Faigi 22:15; 19:20; Gal 5:19 b.t.; Efes 5:5"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 9, 'Ba so zamösa awö mala''ika si dafitu andrö, si so mako andrö, si fitu, nifo''ösi famakao andrö, si fitu balö, safuria, ba humede ia khögu, imane: Tabu, da''u''oroma''ö khöu nono nihalö andrö, fo''omo Nono mbiri-biri andrö.[9]', '["Faigi 15:1,6,7; 19:7"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 10, 'Ba i''ohe ndra''o ba hili sebua, salaŵa, aheta nosogu, ba ioroma''ö khögu mbanua ni''amoni''ö andrö, Yeruzalema, silalö mitou, moroi ba mbanua si yaŵa, moroi ba Lowalangi,[10]', '["Faigi 21:2; Hes 40:2","Hes 48:30-35; 43:2 b.t."]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 11, 'no so khönia lakhömi Lowalangi. Ba hagania, ba hulö mani-mani fondrege zebua böli, hulö yasibi sobaluri.[11]', '["Faigi 21:2; Hes 40:2","Hes 48:30-35; 43:2 b.t."]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 12, 'So göli kara, ebua ba alaŵa, ba felendrua mbawa göli, ba ba dete mbawa göli, ba felendrua mala''ika, ba töi, nisura ba dete, töi mado Ndraono Gizeraeli andrö, si felendrua.', '["Mat 16:18; Efes 2:20"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 13, 'Moroi ba gatumbukha, ba tölu mbawa göli, ba moroi yöu, ba tölu mbawa göli, ba moroi raya, ba tölu mbawa göli, ba moroi ba gaekhula, ba tölu mbawa göli.', '["Mat 16:18; Efes 2:20"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 14, 'Ba toyo göli kara, öli mbanua andrö, ba no felendrua, ba ba detenia, ba felendrua döi, töi zinenge Nono mbiri-biri andrö, si felendrua.[12]', '["Mat 16:18; Efes 2:20"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 15, 'Ba khö zihede khögu andrö, ba so helo[13] ana''a, ba wanu''a banua andrö, fabaya bawa gölinia ba ölinia kara andrö.[14]', '["Lafotöi helo sambua wakake ni''oguna''ö ba wanu''a fa''anau hadia ia, ni''erai faoma hela: sara hela, dua hela, tölu hela, btn. Moroi ba li Melayu elo.","Faigi 11:1"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 16, 'Ba öfa sagi naha mbanua andrö, ba faoma ira wa''anaunia wa''ebolonia. Ba isu''a mbanua helo no mege, ba otu ngaluo fofanö. Faoma ira wa''anaunia wa''ebolonia ba fa''alaŵania.[15]', '["Hes 48","Hela: töi wa''anu''a molo''ö zu''a-su''a sangoguna''ö helo. Fakhili ira meter ba sentimeter ni''oguna''öda ma''ökhö, nisu''a faoma meter."]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 17, 'Ba isu''a gölinia kara no mege, ba otu a öfa wulu a öfa hela[16], fanu''a ba niha, ya''ia wanu''a mala''ika.', '["Hes 48","Hela: töi wa''anu''a molo''ö zu''a-su''a sangoguna''ö helo. Fakhili ira meter ba sentimeter ni''oguna''öda ma''ökhö, nisu''a faoma meter."]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 18, 'Ba ölinia kara andrö, ba yasibi, ba banua, ba si ndruhu mbalaki, hulö zörömi sohahau.', '["Hes 48","Hela: töi wa''anu''a molo''ö zu''a-su''a sangoguna''ö helo. Fakhili ira meter ba sentimeter ni''oguna''öda ma''ökhö, nisu''a faoma meter."]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 19, 'Ba toyo göli mbanua andrö, kara, ba nifomani-mani, hadia ia ngawalö, fangehaonia. Toyo si föföna andrö ba yasibi, ba fanetenia, ba nila, ba fanete da''ö, ba kalisedo, ba fanete da''ö, ba sumurudi,[17]', '["Yes 54:11-12"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 20, 'ba fanete da''ö, ba una, ba fanete da''ö, ba yakudi soyo, ba fanete da''ö, ba firusi, ba fanete da''ö, ba asaki, ba fanete da''ö, ba yakudi sa''usö, ba fanete da''ö, ba sasabadiu, ba fanete da''ö, ba fusifaraga, ba fanete da''ö ba maritaisi.', '["Yes 54:11-12"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 21, 'Ba bawa göli andrö, si felendrua, ba no felendrua mani-mani, sambu-sambua bawa göli, ba ha sambu-sambua mani-mani. Ba ewali ba mbanua ba si ndruhu mbalaki, hulö zörömi sohahau.[18]', '["Faigi 22:2"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 22, 'Ba osali, ba lö u''ila ba mbanua; osalira sa''ae Zo''aya, Lowalangi, samatörö fefu, hadia ia, ba Ono mbiri-biri andrö.', '[]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 23, 'Ba ba mbanua andrö, ba lö moguna luo ba baŵa, ena''ö humaga khönia; ihagaini sa''ae ia lakhömi Lowalangi andrö, ba sulunia Nono mbiri-biri andrö.[19]', '["Faigi 22:5; Yes 60:19","Yes 60:3,5 b.t.; Sin 72:10"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 24, 'Ba mowaö-waö ba hagania soi niha, ba razo andrö, ba guli danö, ba la''ohe miyomo khönia lakhömira.[20]', '["Faigi 22:5; Yes 60:19","Yes 60:3,5 b.t.; Sin 72:10"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 25, 'Ba lö lakusi mbawa gölinia, na ma''ökhö, ba si bongi, ba lö''ö sa ba da''ö.[21]', '["Yes 60:11,20; Sakh 14:7"]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 26, 'Ba la''ohe miyomo khönia lakhömi soi niha, fabaya girö-giröra.', '[]', NULL),
  (3392289, 'NT', 'Fama''ele''ö', 21, 27, 'Ba lö''ö manö möi bakha khönia zi ra''i-ra''iö ba solau sogoro ita, awö waya, ha si no mutanö ba zura töi, ba zura wa''auri andrö, khö Nono mbiri-biri andrö.[22]', '["Yes 52:1; 60:21; Faigi 22:14-15; 13:8"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 1, 'Ba i''oroma''ö khögu zara nungo nidanö fangorifi, no ohahau, hulö mbaluri, si otarai dadaoma Lowalangi andrö ba dadaoma Nono mbiri-biri andrö,[1]', '["Hes 47:1","Faigi 21:21; 2:7; Hes 47:12"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 2, 'ba dalu golayamania; ba faoma fatambai nidanö andrö, ba eu fangorifi andrö, mewelendrua mowua, sara-sara waŵa, ba so mbuania. Ba bulu geu andrö, ba famadöhö wökhö soi niha baero andrö.[2]', '["Hes 47:1","Faigi 21:21; 2:7; Hes 47:12"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 3, 'Ba lö''ö sa''ae fangelifi, hadia ia. Ba so khönia dadaoma Lowalangi, ba dadaoma Nono Mbiri-biri andrö. Ba lafosumange ia enoninia andrö.[3]', '["Faigi 21:27; Sakh 14:11","Mat 5:8; Heb 12:14; Sin 17:15; Faigi 3:12","Faigi 21:22–25; Dan 7:18,27; TimII 2:12"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 4, 'Ba la''ila mbawania, ba so ba gangangora döinia.[4]', '["Faigi 21:27; Sakh 14:11","Mat 5:8; Heb 12:14; Sin 17:15; Faigi 3:12","Faigi 21:22–25; Dan 7:18,27; TimII 2:12"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 5, 'Ba lö si bongi sa''ae. Ba lö moguna khöra haga wandru, ba he haga luo, me ihagaini ira So''aya, Lowalangi, ba salaŵa ira, irugi zi lö aetu.[5]', '["Faigi 21:27; Sakh 14:11","Mat 5:8; Heb 12:14; Sin 17:15; Faigi 3:12","Faigi 21:22–25; Dan 7:18,27; TimII 2:12"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 6, 'Ba imane khögu: Si lö tebulö ba si ndruhu daroma li andre. Ba So''aya andrö, Lowalangi Geheha zama''ele''ö andrö, ba no ifatenge mala''ikania, ba wangoroma''ö khö genoninia andrö, hadia zi lö ara tö itörö.[6]', '["Faigi 21:5; 1:1","Faigi 1:3"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 7, 'Ba hiza, alio so ndra''o. Ya''ahowu zolo''ö taroma li fama''ele''ö andrö, ba zura andre.[7]', '["Faigi 21:5; 1:1","Faigi 1:3"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 8, 'Ba ya''o, Yohane, zangila da''ö ba samondrongo. Ba me aefa urongo, ba me aefa u''ila, ba ulaugö tou ndra''o, ba wangalulu ba mala''ika andrö, sangoroma''ö khögu da''ö.[8]', '["Faigi 1:4,9 b.t.; 19:10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 9, 'Ba imane khögu: Böi! Awöu enoni ndra''o, ba awö dalifusöu sama''ele''ö andrö, ba awö zolo''ö taroma li andrö ba zura andre; khö Lowalangi angalulu.', '["Faigi 10:4; Fil 4:5","Dan 12:10; TimII 3:13; Kol 1:10,11","Faigi 2:23; Yes 62:11; Rom 2:6","Faigi 21:6","Faigi 14:12; 21:12","Faigi 21:8; Fil 3:2; KorI 6:9,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 10, 'Ba imane khögu: Böi fotandro daroma li fama''ele''ö andrö, ba zura andre; noa sa''ae ahatö ginötö andrö.[9]', '["Faigi 10:4; Fil 4:5","Dan 12:10; TimII 3:13; Kol 1:10,11","Faigi 2:23; Yes 62:11; Rom 2:6","Faigi 21:6","Faigi 14:12; 21:12","Faigi 21:8; Fil 3:2; KorI 6:9,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 11, 'Solau si lö atulö, ba yamutohugö wolau, ba si ra''i-ra''iö, ba yamutohugö wa''ara''i-ra''iö; ba satulö, ba yamutohugö wolau satulö, ba ni''amoni''ö, ba yamutohugö we''amoni''ö ya''ia.[10]', '["Faigi 10:4; Fil 4:5","Dan 12:10; TimII 3:13; Kol 1:10,11","Faigi 2:23; Yes 62:11; Rom 2:6","Faigi 21:6","Faigi 14:12; 21:12","Faigi 21:8; Fil 3:2; KorI 6:9,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 12, 'Hiza, alio so ndra''o, ba fao khögu luo andrö khögu, ba wanulöni ba zamösana, dali mbua-buania.[11]', '["Faigi 10:4; Fil 4:5","Dan 12:10; TimII 3:13; Kol 1:10,11","Faigi 2:23; Yes 62:11; Rom 2:6","Faigi 21:6","Faigi 14:12; 21:12","Faigi 21:8; Fil 3:2; KorI 6:9,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 13, 'Alafa ndra''o ba omega, si föföna ndra''o ba safuria, böröta ndra''o ba amozua.[12]', '["Faigi 10:4; Fil 4:5","Dan 12:10; TimII 3:13; Kol 1:10,11","Faigi 2:23; Yes 62:11; Rom 2:6","Faigi 21:6","Faigi 14:12; 21:12","Faigi 21:8; Fil 3:2; KorI 6:9,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 14, 'Ya''ahowu zamabago nukhara, ena''ö tetehe khöra geu fangorifi andrö, ba ena''ö tefatörö ira ba mbawa göli andrö, miyomo ba mbanua.[13]', '["Faigi 10:4; Fil 4:5","Dan 12:10; TimII 3:13; Kol 1:10,11","Faigi 2:23; Yes 62:11; Rom 2:6","Faigi 21:6","Faigi 14:12; 21:12","Faigi 21:8; Fil 3:2; KorI 6:9,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 15, 'Baero so nasu andrö, awö zi fakelemu, awö zohorö, awö zange''e, awö zame''e-me''e adu, awö dozi solau faya, ba somasi ya''ia.[14]', '["Faigi 10:4; Fil 4:5","Dan 12:10; TimII 3:13; Kol 1:10,11","Faigi 2:23; Yes 62:11; Rom 2:6","Faigi 21:6","Faigi 14:12; 21:12","Faigi 21:8; Fil 3:2; KorI 6:9,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 16, 'Ya''o, Yesu andrö, no ufatenge mala''ika andrö khögu, ba wamaduhu''ö khömi da''ö, ba mbanua niha Keriso andrö. Lewiö Dawido ndra''odo, lewiö ba mbörö, ba ma''uwunia, madala andrö, sihaga.[15]', '["Faigi 1:1,2; 11; 5:5; Yes 11:1,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 17, 'Ba lamane Eheha ba ono nihalö andrö: Aine! Ba ha niha zamondrongo, ba yamuŵa''ö: Aine! Ba ha niha zowökhi tödö, ba yamöi, ha niha zomasi, ba yamutema nidanö fangorifi saoha gölö.[16]', '["Faigi 21:6; Yes 55:1; Yoh 7:37; 4:14","MozV 4:2; Amaed 30:6","Faigi 22:14; 21:2,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 18, 'Ufaduhu''ö ba niha fefu, samondrongo taroma li fama''ele''ö andrö ba zura andre: Na so zondrou''ö ya''ia, ba ifatörö khönia Lowalangi wamakao andrö, nisura ba zura andre.[17]', '["Faigi 21:6; Yes 55:1; Yoh 7:37; 4:14","MozV 4:2; Amaed 30:6","Faigi 22:14; 21:2,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 19, 'Ba na so zombuwu taroma li ba zura wama''ele''ö andre, ba iheta Lowalangi gurakhania ba geu fangorifi andrö ba ba mbanua ni''amoni''ö andrö, nisura ba zura andre.[18]', '["Faigi 21:6; Yes 55:1; Yoh 7:37; 4:14","MozV 4:2; Amaed 30:6","Faigi 22:14; 21:2,10"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 20, 'Imane samaduhu''ö da''e: Ya''ia lö ara tö so ndra''o. Yaduhu; aine Yesu, So''aya![19]', '["Faigi 1:7; Heb 10:37 b.t.","Rom 16:24"]', NULL),
  (3392290, 'NT', 'Fama''ele''ö', 22, 21, 'Yafalukha ami fefu wa''ebua dödö Zo''aya ya''ita, Yesu.[20]', '["Faigi 1:7; Heb 10:37 b.t.","Rom 16:24"]', NULL);
